  from public.read_published_managed_content('40000000-0000-4000-8000-000000000001')
  where kind = 'theory_question') = $expected_content$[{"itemId":"b39817d3-9f40-5d4d-a0f6-4892ed942f71","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Define entrepreneurship and explain any four of its dimensions with an example each."}},{"itemId":"93bcc233-d008-5644-a9ad-a5a0ebe330f8","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"Are entrepreneurs born or made? Use the Igba Boi system to support your answer."}},{"itemId":"3e8ac2e5-6278-5151-a752-e50ac292aa30","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"Define innovation and explain its four dimensions, giving one Nigerian example of each."}},{"itemId":"9a9855b4-670a-571e-943f-42692c7f6c8f","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"List the core components of a simple business plan and state what each one covers."}},{"itemId":"a96e4038-68ca-52bd-977d-bce0993a1497","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Outline the steps involved in registering a business in Nigeria."}},{"itemId":"add74835-1e5a-5023-bd76-43e46ad48e9b","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"Using SMEDAN (2017), distinguish between a micro enterprise and a small enterprise, and state two ways micro and small businesses contribute to employment generation."}},{"itemId":"9f7175bc-8e36-55f8-a7c5-c77196bd68c9","courseId":"40000000-0000-4000-8000-000000000001","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Define e-commerce and explain any four of its types with an example each."}}]$expected_content$::jsonb,
  'entrepreneurship-innovation: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000001')
  where kind = 'model_answer') = $expected_content$[{"itemId":"7f6817e8-2742-5c59-ab82-1afb8981b149","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"b39817d3-9f40-5d4d-a0f6-4892ed942f71","revision":1,"payload":{"body":"Define it as the process of identifying opportunities, mobilising resources, creating innovative products or services and taking risks to generate value and achieve profit. Then, for example: innovativeness (creating or improving; Flutterwave), proactiveness (acting ahead of competitors; Sim Shagaya and Konga), risk taking (calculated risks; Dangote investing despite import dominance), resource mobilisation (gathering and managing resources; Tony Elumelu and UBA)."}},{"itemId":"ba9c94e2-c7c5-56e0-881b-abf2fd8f4e50","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"93bcc233-d008-5644-a9ad-a5a0ebe330f8","revision":1,"payload":{"body":"State the born argument (high energy, natural charisma, high risk tolerance from birth; resilience, creativity, extraversion appear early) and the made argument (skills from education, mentorship and experience; accounting, management, marketing and emotional intelligence are learned). Describe Igba Boi as the world's largest business incubator: young people picked with no capital, nurtured through years of mentorship, then settled (funded). Conclude that its near 100% success rate and the teaching of trade, negotiation and supply chain management prove entrepreneurs can be made."}},{"itemId":"f575a5da-4bd7-5394-88a6-394cf15e30ae","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"3e8ac2e5-6278-5151-a752-e50ac292aa30","revision":1,"payload":{"body":"Innovation is the systematic practice of developing and marketing breakthrough products and services for adoption by customers (McKinsey, 2022); it is the successful implementation of new ideas that create value, not just invention. Product innovation (improving a product or creating a totally new one): Cowrywise and Piggyvest moving the Kolo to an app with interest. Process innovation (changing how a product is created or delivered to lower cost or increase speed): Chowdeck and Glovo bike delivery within 30 minutes. Market innovation (finding new markets or packaging for existing products): Peak Milk sachets for low-income earners. Organisational innovation (changing workplace culture or structure): Andela's results-based, work-from-home culture."}},{"itemId":"aa144c54-c8b6-5889-8b3a-f3a1d4434678","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"9a9855b4-670a-571e-943f-42692c7f6c8f","revision":1,"payload":{"body":"Define a business plan as a strategic roadmap detailing a company's goals and the methods to achieve them (Bank of America, 2025). Then the 8 components, one line each: Executive Summary (summary of the plan), Company Description (what the company does), Business Opportunity (market potential), Competitor Analysis (what makes you stand out), SWOT Analysis (strengths, weaknesses, opportunities, threats), Revenue Model (how you will make money), Financial Projection (growth prediction), Team (how you structure and manage the company)."}},{"itemId":"ed9939a4-0984-5705-88be-3222477840d7","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"a96e4038-68ca-52bd-977d-bce0993a1497","revision":1,"payload":{"body":"State that registration is managed by the Corporate Affairs Commission (CAC) under the Companies and Allied Matters Act (CAMA), mainly online through the iCRP Portal, and must be done within 28 days of starting. Then the 4 steps, one line each: choose and reserve a name (with 2 alternatives) on the CAC portal; complete the Pre-Registration Form (CAC-BN01) with business activity and proprietor/partner details (NIN, address, photo); pay the prescribed filing fees online; submit and await approval, then download the electronic Certificate of Registration and Certified Extract. End with the post-registration step: obtain a Tax Identification Number (TIN) from FIRS."}},{"itemId":"5441fc26-f88a-546c-a696-be963aa415fc","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"add74835-1e5a-5023-bd76-43e46ad48e9b","revision":1,"payload":{"body":"Micro: less than 10 employees and total assets (excluding land and building) not exceeding ₦5 million. Small: 10-49 employees and total assets between ₦5 million and ₦49 million, excluding land and buildings. Add one or two contrasts (informal and owner-managed versus formal, semi-formal management). Employment: any two of major source of job creation especially in developing economies; absorb unskilled, semi-skilled and skilled labour; provide jobs for youth, women and vulnerable groups and reduce pressure on the public sector and large firms."}},{"itemId":"15f55bd3-51f1-5981-98f0-0cbf82c14dcb","courseId":"40000000-0000-4000-8000-000000000001","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"9f7175bc-8e36-55f8-a7c5-c77196bd68c9","revision":1,"payload":{"body":"Define e-commerce as the buying and selling of goods and services, and the exchange of money and data, through electronic networks, primarily the internet. Then 1-2 lines each on any four: B2C (business to individual consumers, e.g. Jumia, Konga); B2B (business to business, e.g. Alibaba); C2C (individual to individual, e.g. Jiji.ng, eBay); C2B (individual to business, e.g. a freelancer on Upwork, influencers); B2G (business to government agencies, e.g. e-tendering); G2C (government services to citizens, e.g. online tax payment, e-visa)."}}]$expected_content$::jsonb,
  'entrepreneurship-innovation: model_answer published payload and identity match source');
