15","6/95","3/19"],"correctOption":3,"section":"Probability Foundations"}},{"itemId":"5039b4f5-db87-5dea-ade6-80cf4bee57ce","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"9d0d7f25-8fbb-4d1e-8568-ddb607189174","sourceKey":"quiz:146","parentItemId":null,"revision":1,"payload":{"prompt":"P(A) = 0.5, P(B|A) = 0.4, P(B|A') = 0.2. Using Bayes' theorem, P(A|B) is:","options":["0.50","0.60","0.67","0.70"],"correctOption":2,"section":"Probability Foundations"}},{"itemId":"8e44c178-808a-5ffa-9128-b16acfafc148","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"017cc076-45f4-4a35-bab3-c2a6d10904e1","sourceKey":"quiz:147","parentItemId":null,"revision":1,"payload":{"prompt":"If X has E(X) = 4 and Var(X) = 3, then E(2X + 5) is:","options":["8","10","13","17"],"correctOption":2,"section":"Probability Distributions"}},{"itemId":"21ed9cbd-6b05-564a-bc59-1e1606880f1d","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"8477c13f-5a02-4103-a2a9-762ba5abc0dc","sourceKey":"quiz:148","parentItemId":null,"revision":1,"payload":{"prompt":"If X has Var(X) = 3, then Var(2X + 5) is:","options":["3","6","10","12"],"correctOption":3,"section":"Probability Distributions"}},{"itemId":"7b20acb3-e567-5a5d-998e-fb8acd323783","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"0ad95d0f-bf06-492f-90e7-cf2484918af4","sourceKey":"quiz:149","parentItemId":null,"revision":1,"payload":{"prompt":"In a Binomial experiment with n = 8 and p = 0.25, the mean and variance are:","options":["Mean=2, Var=1.5","Mean=2, Var=2","Mean=3, Var=1.5","Mean=4, Var=3"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"574a7228-1922-5ccf-863c-a9ef97b93ea4","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"91e97c74-f83d-4874-88f2-4d487d51bc39","sourceKey":"quiz:15","parentItemId":null,"revision":1,"payload":{"prompt":"A cumulative frequency graph is commonly known as an:","options":["Ogive","Histogram","Frequency Polygon","Scatter Plot"],"correctOption":0,"section":"Data Presentation & Frequency Distributions"}},{"itemId":"0475b00d-6d48-59e4-a9cf-54b4f9d9c529","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"64e75303-b2bb-4df9-a6dc-72c38759bcca","sourceKey":"quiz:150","parentItemId":null,"revision":1,"payload":{"prompt":"X ~ B(10, 0.3). P(X = 3) is:","options":["0.2668","0.2335","0.2001","0.1763"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"91ee9b69-9f29-5688-9fa1-d027f3e0a027","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"69e86be4-240a-4627-8409-adcc3fdaf81e","sourceKey":"quiz:151","parentItemId":null,"revision":1,"payload":{"prompt":"X ~ B(10, 0.3). P(X = 0) is:","options":["0.0282","0.0324","0.0576","0.0710"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"6d9961d6-6344-5007-8614-41d6ae62eb56","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"95a278a3-d795-4aca-854c-cf924d52411d","sourceKey":"quiz:152","parentItemId":null,"revision":1,"payload":{"prompt":"A Poisson random variable X has λ = 3. P(X = 2) (using e⁻³ ≈ 0.0498) is:","options":["0.1494","0.2240","0.2241","0.2494"],"correctOption":1,"section":"Probability Distributions"}},{"itemId":"ecdee261-4f5f-5fe6-a6f8-dcc4613ad8d2","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"83511f92-4cbd-4b80-813f-3a2c8287116d","sourceKey":"quiz:153","parentItemId":null,"revision":1,"payload":{"prompt":"For a Poisson distribution with λ = 3, P(X = 0) + P(X = 1) (i.e. P(X ≤ 1)) is:","options":["0.0498 + 0.1494 = 0.1992","0.0498 + 0.1245 = 0.1743","0.0498 + 0.0996 = 0.1494","0.0498 + 0.1992 = 0.2490"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"53448e50-f770-5d93-a06d-291c05a5ee4f","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"c118155f-76a5-4e5e-a9f5-64cf5f129c4a","sourceKey":"quiz:154","parentItemId":null,"revision":1,"payload":{"prompt":"For a Poisson distribution, which statement correctly describes its variance?","options":["Variance equals twice the mean","Variance equals the square root of the mean","Variance equals the mean (λ)","Variance equals λ²"],"correctOption":2,"section":"Probability Distributions"}},{"itemId":"778e76ed-7b17-59e6-a626-e1c638b395c9","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"ced58d60-6117-4096-8fcd-cc72389355eb","sourceKey":"quiz:155","parentItemId":null,"revision":1,"payload":{"prompt":"Z is a standard normal variable. P(Z < 1.96) ≈ 0.9750. Therefore P(−1.96 < Z < 1.96) is:","options":["0.9500","0.9750","0.9000","0.9800"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"9fcd2ec4-830a-54c6-bf7e-764a48bc0931","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"b8bbca03-ccc2-466f-a837-0084800e2cef","sourceKey":"quiz:156","parentItemId":null,"revision":1,"payload":{"prompt":"X ~ N(60, 25) (mean=60, variance=25). P(X > 65) using Z = (65−60)/5 = 1.00; P(Z>1.00) is:","options":["0.1587","0.3413","0.6827","0.8413"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"efb478c8-3a73-55e6-808a-30166410ed1e","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"991eb70b-f404-43f5-91d8-67421fd740c3","sourceKey":"quiz:157","parentItemId":null,"revision":1,"payload":{"prompt":"X ~ N(μ, σ²). P(μ − 3σ < X < μ + 3σ) according to the empirical rule is approximately:","options":["68%","90%","95%","99.7%"],"correctOption":3,"section":"Probability Distributions"}},{"itemId":"646f6892-90b0-5b08-946d-692680116f43","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"76616a9f-a4fa-4bc9-9201-a61055edb8f5","sourceKey":"quiz:158","parentItemId":null,"revision":1,"payload":{"prompt":"The NORMAL DISTRIBUTION is completely described by its:","options":["Mean and variance only","Mean, median, and mode","Range and standard deviation","Mean, median, mode, and kurtosis"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"0dc750f9-aceb-55bf-9835-c62eafb09a0a","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"8a7dbdf3-4c36-4335-b856-3368097ed9bc","sourceKey":"quiz:159","parentItemId":null,"revision":1,"payload":{"prompt":"X ~ N(100, 16). The standardised Z-score for X = 92 is:","options":["-2.00","-1.00","-0.50","2.00"],"correctOption":0,"section":"Probability Distributions"}},{"itemId":"4e317d34-15be-5f1e-b252-78d04df6c3df","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"dc6ff7e2-ba9c-4606-89f5-1ec74910d0f8","sourceKey":"quiz:16","parentItemId":null,"revision":1,"payload":{"prompt":"In a Stem-and-Leaf plot, the \"Leaf\" usually represents:","options":["The first digit","The last digit","The average","The count"],"correctOption":1,"section":"Data Presentation & Frequency Distributions"}},{"itemId":"fd6afccb-1c5d-584e-8e02-72c368529d63","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"ebb9c1c8-23f4-4fdb-b00f-4b79f9d95868","sourceKey":"quiz:160","parentItemId":null,"revision":1,"payload":{"prompt":"A continuous uniform distribution over [a, b] has mean equal to:","options":["(b−a)/2","(a+b)/2","(b−a)²/12","ab/2"],"correctOption":1,"section":"Probability Distributions"}},{"itemId":"5dfc063d-81e1-53c5-88c0-6627eb99e004","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"b64a9e1b-49c2-443a-9df3-1fedf18c56ab","sourceKey":"quiz:161","parentItemId":null,"revision":1,"payload":{"prompt":"Let A and B be two events defined in a sample space S. The expression for \"Either A or B\" is:","options":["A and B","A ∪ B","A ∩ B","A ∩ B'"],"correctOption":1,"section":"Probability Foundations"}},{"itemId":"d36f89