":["Line Graph","Pie Chart","Ogive","Histogram"],"correctOption":1,"section":"Data Presentation & Frequency Distributions"}},{"itemId":"1fd80efd-3707-5130-ad17-f5d9ed828c53","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"2a816c42-5b8e-422d-bf11-84f5cdb1d8db","sourceKey":"quiz:170","parentItemId":null,"revision":1,"payload":{"prompt":"If A is an event, the probability of the complement of A, written as A' is given by:","options":["1 - P(A)","1 - P(A')","1 + P(A')","P(A) + P(A')"],"correctOption":0,"section":"Probability Foundations"}},{"itemId":"f16bc5ef-5d39-53ed-9f9e-db4e8b20c6e2","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"5049cb87-1850-49b7-a56c-fa0659d96f39","sourceKey":"quiz:171","parentItemId":null,"revision":1,"payload":{"prompt":"The probability of an impossible event is:","options":["less than 0","equal to 1","greater than 1","equal to 0"],"correctOption":3,"section":"Probability Foundations"}},{"itemId":"587e7b42-3088-5579-9868-067cba518f31","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"731c3c0f-e85b-466e-aa54-083907b53e42","sourceKey":"quiz:172","parentItemId":null,"revision":1,"payload":{"prompt":"A, B, C are the only events in a sample space, then P(A) + P(B) + P(C) = ?","options":["1","greater than 1","less than 1","between 0 and 1"],"correctOption":0,"section":"Probability Foundations"}},{"itemId":"ea13701e-6c42-546b-aa19-516305c72997","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"0a20f815-a0b4-400a-8913-cc63c4dcc9cd","sourceKey":"quiz:173","parentItemId":null,"revision":1,"payload":{"prompt":"The condition for which two events A and B are independent is that P(A ∩ B) equals:","options":["P(A)","P(A) × P(A|B)","P(A) × P(B)","P(A ∪ B)"],"correctOption":2,"section":"Probability Foundations"}},{"itemId":"8fc9f195-4338-5319-a23b-4252c135d9a3","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"a42055d6-6579-42d0-a0fe-a5b1ba8e1291","sourceKey":"quiz:174","parentItemId":null,"revision":1,"payload":{"prompt":"Suppose A and B are independent events with P(A) = 0.2, P(B) = 0.6. What is P(A|B)?","options":["0.2","0.6","0.12","0.8"],"correctOption":0,"section":"Probability Foundations"}},{"itemId":"d1be9b17-1d01-525a-95ce-9011a25935c1","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"d977f6b2-cc9f-4d99-acfa-fabda35584f8","sourceKey":"quiz:175","parentItemId":null,"revision":1,"payload":{"prompt":"If A and B are mutually exclusive events then P(A ∪ B) equals:","options":["P(A) × P(B)","P(A) + P(B)","P(A) × P(A|B)","1"],"correctOption":1,"section":"Probability Foundations"}},{"itemId":"0803b356-40a9-5656-8833-b70420822649","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"6e1e585b-8c55-4e55-aa3b-1f40ebcdee55","sourceKey":"quiz:176","parentItemId":null,"revision":1,"payload":{"prompt":"Given P(A) = 0.30, P(B) = 0.78, and P(A ∩ B) = 0.16, find P(A ∪ B):","options":["0.84","0.92","0.08","0.234"],"correctOption":1,"section":"Probability Foundations"}},{"itemId":"24b4e998-c683-5731-9e39-971c4d302105","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"23bc7047-2df0-4978-8913-68ba38c09a55","sourceKey":"quiz:177","parentItemId":null,"revision":1,"payload":{"prompt":"From a pack of 52 playing cards, one card is drawn at random. What is the probability that it is a jack of spade or queen of heart?","options":["1/52","2/52","1/26","4/52"],"correctOption":2,"section":"Probability Foundations"}},{"itemId":"c97b7751-24a2-5553-9997-2a9286de1b84","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"0a140f0e-9a06-4073-9304-489c472d3fea","sourceKey":"quiz:178","parentItemId":null,"revision":1,"payload":{"prompt":"25 lottery tickets are marked with first 25 numerals. A ticket is drawn at random. Find the probability that it is a multiple of 5 or 7:","options":["5/25","3/25","8/25","2/25"],"correctOption":2,"section":"Probability Foundations"}},{"itemId":"36d16c79-da80-575b-8a62-67f7f183e413","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"be5c6be1-560c-42d4-8de5-95b15234a519","sourceKey":"quiz:179","parentItemId":null,"revision":1,"payload":{"prompt":"An urn contains 4 red and 7 blue balls. Two balls are drawn one by one without replacement. Find the probability of getting 2 red balls:","options":["4/11","3/10","6/55","12/110"],"correctOption":2,"section":"Probability Foundations"}},{"itemId":"8504c7b5-1b98-5d67-83f7-378608ba5af4","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"e793177d-12a0-466a-a22e-02a75e86b93d","sourceKey":"quiz:18","parentItemId":null,"revision":1,"payload":{"prompt":"The midpoint of a class interval is calculated by:","options":["(Upper Boundary - Lower Boundary) / 2","(Upper Boundary + Lower Boundary) / 2","Lower Boundary + Class Width","Upper Boundary - Class Width"],"correctOption":1,"section":"Data Presentation & Frequency Distributions"}},{"itemId":"93b44a53-e731-5068-9cf5-4d3684bb9929","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"af909ed7-28b0-4fd8-bc8c-d08399d60660","sourceKey":"quiz:180","parentItemId":null,"revision":1,"payload":{"prompt":"Two dice are thrown together. Find the probability that the sum of the numbers turned up is either 6 or 8:","options":["10/36","5/18","8/36","12/36"],"correctOption":1,"section":"Probability Foundations"}},{"itemId":"dd9af5d5-f7a8-5a39-aa3f-b47c45c15961","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"07804270-e0bd-450d-a3f7-6c54f3734eae","sourceKey":"quiz:181","parentItemId":null,"revision":1,"payload":{"prompt":"A researcher conducts a study where they gather data from every single member of the target population. What is this method of data collection called?","options":["Sampling","Experimental Design","Census","Case Study"],"correctOption":2,"section":"Basic Concepts & Data Collection"}},{"itemId":"d521705e-51be-56cb-8ba4-583068d7f81e","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"dc85e751-85e6-4aed-aa28-af76f480257c","sourceKey":"quiz:182","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following graphical representations is best suited for displaying the cumulative frequency of a dataset?","options":["Scatter Plot","Histogram","Ogive","Pie Chart"],"correctOption":2,"section":"Graphical Representation"}},{"itemId":"5309754b-cb7a-531b-bc7e-e08a4ad98b97","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"a38c5295-70ea-4bf4-800c-f02082d5d8fd","sourceKey":"quiz:183","parentItemId":null,"revision":1,"payload":{"prompt":"If a dataset has a mean of 75 and a median of 60, what can be inferred about the distribution's skewness?","options":["It is positively skewed.","It is perfectly symmetrical.","It is negatively skewed.","It is platykurtic."],"correctOption":0,"section":"Skewness & Kurtosis"}},{"itemId":"89045642-71ac-51df-8466-aa96f76b75b0","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"c56f005c-cd88-4ebd-892c-63648bace9c6","sourceKey":"quiz:184","parentItemId":null,"revision":1,"payload":{"prompt":"The variance of a set of test scores is calculated to be s² = 49. What is the standard deviation (s)?","options":["49","2401","24.5","7"],"correctOption":3,"section":"Measures of Dispersion"}},{"itemId":"b6a6233d-547a-57eb-9540-454db8926e34","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"19e1dd5c-f8bd-47d6-b667-31ffaa182bae","sourceKey":"quiz:185","parentItemId":null,"revision":1,"payload":{"prompt":"A distribution that is significantly more peaked than a normal distribution is described as being:","options":["Platykurtic","Leptokurtic","Symmetrical","Mesokurtic"],"correctOption":1,"section":"Skewness & Kurtosis"}},{"itemId":"bc8175d3-82c8-5994-bb79-3ae4ae92643d","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"150552a5-10c0-4952-b03f-441d12dd9cd8","sourceKey":"quiz:186","parentItemId":null,"revision":1,"payload":{"prompt":"If two events A and B are mutually exclusive, what is the probability of both events occurring simultaneously, P(A ∩ B)?","options":["P(A) × P(B)","0","P(A) + P(B)","1"],"correctOption":1,"section":"Probability Foundations"}},{"itemId":"578255ff-4c52-5475-b11a-0325587dc692","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"fd508762-7cbf-4989-a7ce-a6167bf09c76","sourceKey":"quiz:187","parentItemId":null,"revision":1,"payload":{"prompt":"For a discrete random variable X, which formula is used to calculate the Expected Value E(X)?","options":["√Σ(xᵢ - μ)²pᵢ","Σxᵢ/n","Σpᵢ","Σxᵢpᵢ"],"correctOption":3,"section":"Probability Distributions"}},{"itemId":"f7d7d9ed-5c62-51a5-ada3-ed38872e150d","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"1582b4c0-6151-4c5c-a224-51604505867b","sourceKey":"quiz:188","parentItemId":null,"revision":1,"payload":{"prompt":"Which probability distribution is most appropriate for modeling the number of successes in n independent trials, where each trial has the same probability of success?","options":["Normal Distribution","Poisson Distribution","Binomial Distribution","Exponential Distribution"],"correctOption":2,"section":"Probability Distributions"}},{"itemId":"9b6b6179-92fc-5d22-9f50-4b87d7ca50f9","courseId":"40000000-0000-4000-8000-000000000003","kind":"cbt_question","questionId":"6a6d9298-45e5-4f04-999e-e6aa998f1ec2","sourceKey":"quiz:189","parentItemId":null,"revision":1,"payload":{"prompt":"In a standard normal distribution, what are the parameters for the mean (μ) and the standard deviation (σ)?","options":["μ = 1, σ = 0","μ = 0, σ = 1","μ = 1, σ = 1","μ = 0, 