  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '40000000-0000-4000-8000-000000000005' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"16c25a2f-1c6a-5bf1-bae1-7eb6d7ed5323","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"72e6351d-1b7e-40f0-a5ee-ab3ff2845386","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Given U = {1,2,...,10}, A = {1,3,5,7,9}, B = {2,3,5,7}. What is (A U B)'?","options":["{4, 6, 8, 10}","{1, 2, 9, 10}","{3, 5, 7}","{1, 2, 4, 6, 8, 10}"],"correctOption":0,"section":"Set Theory & Logic"}},{"itemId":"af2e89e6-f2be-5852-aeff-abc52503cb3d","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"50ed2580-8902-435c-b09e-d89500b5f56f","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"By De Morgan's Law, (A U B)' is equivalent to:","options":["A' U B'","A' n B'","(A n B)'","A' U B"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"4a931ebf-6d8a-5d87-8a86-68d5bb4de1b9","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"258e459b-97ff-478d-8cf5-dc04196bfc50","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"In business, finding TC from MC by integration is an example of moving from:","options":["Total data to marginal data","Marginal data to total data","Average data to total data","Fixed data to variable data"],"correctOption":1,"section":"Integral Calculus"}},{"itemId":"8dfa4b24-f00d-5a87-bbc7-6471f47c5e01","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"36e9f1c5-aa7f-4155-baed-cc5b758ba234","sourceKey":"quiz:11","parentItemId":null,"revision":1,"payload":{"prompt":"A set with n elements has how many proper subsets?","options":["2^n","2^n - 1","2^n - 2","n^2"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"dbf77146-94c3-5db8-ad9d-73e2992c0312","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"69ede7f7-8ecd-43bf-a0a1-9d8c21955787","sourceKey":"quiz:12","parentItemId":null,"revision":1,"payload":{"prompt":"What is the intersection of any set A with the empty set?","options":["A","The empty set","The Universal set","A'"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"18391e0f-d4f4-5a5f-b496-bac220d1ecbb","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"0120cdc7-29f0-4e85-b134-d144165b4765","sourceKey":"quiz:13","parentItemId":null,"revision":1,"payload":{"prompt":"If U = {all integers} and A = {even integers}, what is A'?","options":["All positive integers","All odd integers","All prime numbers","The empty set"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"324c93f1-7a46-5331-9b25-57e134fb1f58","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"d3a5d38e-d117-4b9d-be3f-7d83ee8f43e2","sourceKey":"quiz:14","parentItemId":null,"revision":1,"payload":{"prompt":"What is the cardinality of the set P = {x : x is a prime factor of 30}?","options":["2","3","4","5"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"97c9630b-c1cc-51d9-af81-d00ed2f9fc91","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"4efeceb2-5af1-456d-aa25-afba26eab9d8","sourceKey":"quiz:15","parentItemId":null,"revision":1,"payload":{"prompt":"Two sets are called \"Disjoint\" if their intersection is:","options":["The Universal set","Equal to either set","The empty set","The union of the sets"],"correctOption":2,"section":"Set Theory & Logic"}},{"itemId":"59d0e14f-d1f6-550b-8dac-00f2ddefb609","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"611e2ca2-945c-4954-a176-d17eb5a7eb01","sourceKey":"quiz:16","parentItemId":null,"revision":1,"payload":{"prompt":"The key formula for the union of two sets is n(A U B) = ?","options":["n(A) + n(B)","n(A) + n(B) - n(A n B)","n(A) x n(B)","n(A) - n(B) + n(A n B)"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"7811ed6f-d5d5-5cc7-b4f3-f5d432d92412","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"f22d95e1-7e93-4032-80e6-a2886b94544a","sourceKey":"quiz:17","parentItemId":null,"revision":1,"payload":{"prompt":"A Null set (empty set) contains:","options":["One element","Zero elements","Infinite elements","Undefined number of elements"],"correctOption":1,"section":"Set Theory & Logic"}},{"itemId":"be92c085-1c52-560e-aba5-f17dd56c4d09","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"dc5ffa03-d8fc-4159-8b79-4d53ab57829c","sourceKey":"quiz:18","parentItemId":null,"revision":1,"payload":{"prompt":"In a three-set Venn diagram, the region (A n B) \\ C represents:","options":["Elements in A and B but not in C","Elements in all three sets","Elements in A or B or C","Elements not in A and B"],"correctOption":0,"section":"Set Theory & Logic"}},{"itemId":"277162f8-f7c4-5c37-ac3f-a276720a8fb2","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"1de2e696-9e1e-4a14-a2f5-0eb5e2fb9cfe","sourceKey":"quiz:19","parentItemId":null,"revision":1,"payload":{"prompt":"\"The set of all products that are either defective or overpriced but not both\" is expressed as:","options":["D n O","D U O","D Delta O (Symmetric Difference)","(D U O)'"],"correctOption":2,"section":"Set Theory & Logic"}},{"itemId":"339089d4-a4ef-5a40-80c8-64c04763ee78","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"8e0acc55-2745-4e57-a71f-47ffe61dad36","sourceKey":"quiz:2","parentItemId":null,"revision":1,"payload":{"prompt":"In a group of 50 students, 30 take Accounting, 25 take Economics, and 10 take both. How many take neither?","options":["5","10","15","20"],"correctOption":0,"section":"Set Theory & Logic"}},{"itemId":"27e17251-175a-555a-8a3d-8c0dd4880a45","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"793566ae-a236-4d72-ba30-ef4c703f3ea7","sourceKey":"qu