t":"If MPS = 0.3 and S = 0 when Y = 100, the Saving function S(Y) is:","options":["0.3Y - 30","0.3Y + 30","0.3Y - 100","0.3Y"],"correctOption":0,"section":"Integral Calculus"}},{"itemId":"29c5dede-d323-583a-a025-30167a8a9739","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"3700af63-0278-4173-8be6-01d28b3bdc38","sourceKey":"quiz:94","parentItemId":null,"revision":1,"payload":{"prompt":"The area between y = x and y = x^2 from x=0 to x=1 is:","options":["1/3","1/6","1/2","1/4"],"correctOption":1,"section":"Integral Calculus"}},{"itemId":"d12ab81f-66e7-5c43-b659-9e0c6830a17b","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"890bf246-3274-4068-8989-8f23f4d96b2f","sourceKey":"quiz:95","parentItemId":null,"revision":1,"payload":{"prompt":"The integral of 5/x dx is:","options":["5x + C","5 ln|x| + C","-5/x^2 + C","5e^x + C"],"correctOption":1,"section":"Integral Calculus"}},{"itemId":"7bbddd5e-bb82-5e0e-b509-0ddcc0ab5302","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"0282b9b1-8dd4-471d-8fb9-db973dfd13ec","sourceKey":"quiz:96","parentItemId":null,"revision":1,"payload":{"prompt":"Producer Surplus at Q=5 for supply curve P = 2 + Q where equilibrium price is 7 is:","options":["10","12.5","15","25"],"correctOption":1,"section":"Integral Calculus"}},{"itemId":"fbdee403-a7a1-5288-818a-f79ee4ae3fbf","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"acba139d-b907-4a16-8d51-b515c84e9c7f","sourceKey":"quiz:97","parentItemId":null,"revision":1,"payload":{"prompt":"The definite integral of f(x) = 10 from x=2 to x=7 is:","options":["10","30","50","70"],"correctOption":2,"section":"Integral Calculus"}},{"itemId":"47a39cfd-080d-599d-8e90-ac98621596b4","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"0275042a-eb7b-4f8b-8e0c-883023a4710c","sourceKey":"quiz:98","parentItemId":null,"revision":1,"payload":{"prompt":"The integral of x^n dx equals (for n not equal to -1):","options":["nx^(n-1) + C","x^(n+1)/(n+1) + C","x^n/n + C","(n+1)x^n + C"],"correctOption":1,"section":"Integral Calculus"}},{"itemId":"16272858-e532-5fc0-b656-067a9914aa81","courseId":"40000000-0000-4000-8000-000000000005","kind":"cbt_question","questionId":"e798118b-b5a6-47ee-ba26-3c33ef32913b","sourceKey":"quiz:99","parentItemId":null,"revision":1,"payload":{"prompt":"Differentiation finds the rate of change; Integration finds the:","options":["Rate of acceleration","Accumulation of value (area)","Maximum point","Slope of tangent"],"correctOption":1,"section":"Integral Calculus"}}]$expected_content$::jsonb,
  'business-mathematics: cbt_question published payload and identity match source');
