  where kind = 'course_overview') = $expected_content$[{"itemId":"5aad5fe7-ca39-5228-9fd8-a71a4aa69e1c","courseId":"40000000-0000-4000-8000-000000000006","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":2,"payload":{"title":"Consumer Behaviour","body":"Study of consumer decision processes, buyer types, and the psychological, cultural, and social factors influencing consumer choices and market behaviour.","topics":[{"chapter":"1-2","description":"Consumer Decision-Making Process"},{"chapter":"3-4","description":"Types of Consumers and Buyer Behaviour"},{"chapter":"5-6","description":"Cultural and Social Influences on Consumer Behaviour"},{"chapter":"7-8","description":"Personality, Attitudes, and Perception"},{"chapter":"9-10","description":"Communication, Persuasion and Marketing Appeals"}],"examFocus":["Consumer decision-making models","Psychological factors affecting consumer choice","Cultural and social influences","Personality and attitude measurement","Communication theories in marketing","Theoretical explanations and applications"]}}]$expected_content$::jsonb,
  'consumer-behaviour: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000006')
  where kind = 'note') = $expected_content$[{"itemId":"78bf7a81-885d-5d87-8009-ab27ecdddfbb","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:1","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Consumer Behaviour","body":"Consumer behaviour is the study of how individuals, groups, and organizations select, buy, use, and dispose of goods, services, ideas, or experiences to satisfy needs and wants. It draws from psychology, sociology, and anthropology to understand purchasing decisions.","noteType":"topic_note","keyPoints":["Consumer vs. Customer: A customer purchases the product; a consumer is the end-user who benefits from it.","Types of Buyers: Impulse (spontaneous, emotional), Informed (research extensively), Brand Loyal (stick to trusted brands), Price Sensitive (hunt for discounts).","Economic Impact: Consumer spending stimulates production, supports GDP, and drives economic growth.","Online vs. Offline: Online shoppers value convenience and range; offline shoppers prefer tactile product experience."],"examTip":"Remember the distinction between customer (purchaser) and consumer (end-user) - they can be different people."}},{"itemId":"02a9f9dd-248e-5225-bff0-4f96a2db14d5","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:10","parentItemId":null,"revision":1,"payload":{"title":"Pricing Strategies and Consumer Value Perception","body":"Pricing strategies must align with consumer value perceptions. Customer-value-based pricing starts with analyzing consumer needs rather than costs. Competitive advantage mediates the relationship between pricing and performance.","noteType":"topic_note","keyPoints":["Cost-Based Pricing: Setting prices based on total expenses of providing the product/service.","Competition-Based Pricing: Setting prices based on what competitors charge.","Customer-Value-Based Pricing: Setting prices based on perceived value to the consumer.","Penetration Pricing: Low initial prices to attract large number of buyers quickly.","Skimming Pricing: High initial prices for new, unique products.","Psychological Pricing: Using prices like $9.99 instead of $10.00 to influence perception."],"examTip":"Customer-value-based pricing is most customer-centric - it starts with analyzing consumer needs, not costs."}},{"itemId":"4b7f472f-271b-59de-a5c1-055f16c69c13","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:2","parentItemId":null,"revision":1,"payload":{"title":"The 5-Stage Consumer Decision-Making Process","body":"Consumers move through five distinct stages when making purchase decisions: recognizing a problem, searching for information, evaluating alternatives, making a purchase decision, and evaluating post-purchase satisfaction.","noteType":"topic_note","keyPoints":["1. Problem Recognition: Triggered by internal stimuli (hunger) or external stimuli (advertisement).","2. Information Search: Internal (memory/past experiences) or external (reviews, friends, ads).","3. Evaluation of Alternatives: Comparing brands based on attributes, features, benefits, and costs.","4. Purchase Decision: Actual choice of what to buy, which brand, where to buy, and how to pay.","5. Post-Purchase Behaviour: Evaluating satisfaction - critical for loyalty and word-of-mouth."],"examTip":"Memorize the 5 stages in order. Post-purchase evaluation is critical because it drives future loyalty and recommendations."}},{"itemId":"2ad2e2e7-bc1b-5edd-8923-be6cf098777e","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:3","parentItemId":null,"revision":1,"payload":{"title":"Cultural and Social Influences","body":"Culture is the broadest and deepest influence on consumer behaviour, dictating fundamental tastes, norms, values, and traditions. Social class and sub-cultures provide additional layers of influence on purchasing decisions.","noteType":"topic_note","keyPoints":["Culture: Dictates fundamental tastes, norms, values, traditions (food, clothing, holidays).","Sub-Culture: Smaller groups providing specific identification (nationality, religion, racial groups, geographic regions).","Social Class: Division based on wealth, education, status - heavily affects media consumption and product choices.","Social Stratification: Measured by occupation, income, and education."],"examTip":"Culture is the BROADEST influence. Social class is measured using occupation, income, and education."}},{"itemId":"fd8f4fe0-5d7e-5cd5-80bf-5941f8da012b","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:4","parentItemId":null,"revision":1,"payload":{"title":"Reference Groups and External Influences","body":"Reference groups serve as standards for evaluating behavior and purchasing decisions. They exert influence through informational guidance, normative pressure to conform, and value-expressive inspiration.","noteType":"topic_note","keyPoints":["Reference Groups: Any group used as a standard for evaluating one's own behavior.","Aspirational Groups: Groups a person wants to join or emulate (celebrities, sports teams).","Dissociative Groups: Groups a person actively wants to avoid being associated with.","Informational Influence: Seeking explicit expert opinions (doctor, mechanic).","Utilitarian Influence: Buying to fit in, be rewarded, or avoid punishment by peers.","Value-Expressive Influence: Adopting group values to enhance self-image (eco-friendly products)."],"examTip":"Know the three types of group influence: Informational (expert advice), Utilitarian (fitting in), Value-Expressive (self-image)."}},{"itemId":"b0cac564-3ed1-5087-86e4-2e4386ea8de4","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:5","parentItemId":null,"revision":1,"payload":{"title":"Individual Psychology: Motivation and Perception","body":"Motivation is the driving force behind consumer actions. Maslow's Hierarchy explains that humans satisfy basic needs first. Perception involves how consumers select, organize, and interpret information through selective attention, distortion, and retention.","noteType":"topic_note","keyPoints":["Motivation: The driving force that impels consumers to action.","Maslow's Hierarchy: Physiological → Safety → Social → Esteem → Self-Actualization (satisfied in order).","Selective Attention: Consumers screen out most stimuli and notice only relevant information.","Selective Distortion: Consumers twist information to fit existing preconceptions.","Selective Retention: Consumers remember good points about liked products and forget competitors' advantages."],"examTip":"Maslow's hierarchy must be satisfied from bottom to top. The three selective processes are barriers marketers must overcome."}},{"itemId":"38bf5b23-0046-5e49-bb28-6aceb3aa35da","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:6","parentItemId":null,"revision":1,"payload":{"title":"Learning and Attitudes","body":"Consumer learning results from experience and influences future behavior. Classical conditioning associates brands with positive stimuli, while operant conditioning uses rewards. Attitudes consist of cognitive, affective, and conative components.","noteType":"topic_note","keyPoints":["Classical Conditioning: Learning to associate a brand with positive stimulus (music, imagery).","Instrumental (Operant) Conditioning: Rewarding specific behavior (loyalty points for purchases).","Tri-component Attitude Model: (1) Cognitive (knowledge), (2) Affective (feelings), (3) Conative (action likelihood).","Cognitive Dissonance: Post-purchase tension or regret when expectations aren't met.","Attitudes: Enduring favorable or unfavorable evaluations toward objects/brands."],"examTip":"Classical = association, Operant = reward. The conative component predicts likelihood of purchase action."}},{"itemId":"407f56f9-0a82-53e1-88fe-8f0c8e38e796","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:7","parentItemId":null,"revision":1,"payload":{"title":"Communication and Persuasive Techniques","body":"Effective marketing communication requires understanding the five components: sender, message, medium, receiver, and feedback. Credibility is critical - informal sources (friends/family) typically have higher credibility than formal sources (advertisers).","noteType":"topic_note","keyPoints":["Five Components: Sender (initiator), Message (encoded thought), Medium (channel), Receiver (target audience), Feedback (response).","Credibility: Perceived honesty and objectivity of the source.","Informal Sources: Friends/family have higher credibility (no financial gain perceived).","Formal Sources: Commercial advertisers have lower credibility.","Communication Barriers: Psychological noise (competing messages, distractions) and selective perception."],"examTip":"Remember the 5 components. Informal sources > Formal sources in credibility because of perceived objectivity."}},{"itemId":"cde2d36f-4a3d-514b-8c7b-83d0b15b450a","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:8","parentItemId":null,"revision":1,"payload":{"title":"Promotional Strategy and the AHP Model","body":"The Analytic Hierarchy Process (AHP) helps determine optimal promotional mix. For Nigerian insurance companies, advertising and personal selling were found most effective, while sales promotion received minimal investment priority.","noteType":"topic_note","keyPoints":["AHP Model: Determines best mix of promotional elements based on weighted criteria.","Best for Nigerian Insurance: Advertising (builds brand awareness and trust for intangible services).","Second Most Effective: Personal Selling (direct relationships, builds buyer conviction).","Minimal Investment: Sales Promotion (lowest direct impact on insurance policy sales).","Seven Promotional Tools: Advertising, Personal Selling, Sales Promotion, Public Relations, Publicity, Sponsorship, Direct Marketing."],"examTip":"AHP study: Advertising = best, Personal Selling = second, Sales Promotion = minimal investment."}},{"itemId":"1672c927-5703-5d2b-a865-e28711a08029","courseId":"40000000-0000-4000-8000-000000000006","kind":"note","questionId":null,"sourceKey":"topic-note:9","parentItemId":null,"revision":1,"payload":{"title":"Modern Decision-Making and Digital Influences","body":"Recent research shows consumer decision-making has shifted from sequential stages to continuous digital exploration. The Stimulus-Organism-Response (SOR) framework explains how external stimuli affect internal states and behavioral outcomes.","noteType":"topic_note","keyPoints":["Shift to Continuous Exploration: Social media and digital platforms blur traditional decision-making stages.","SOR Framework: External stimuli (web design, social proof) → Internal states (emotions, cognition) → Behavioral outcomes (purchase).","Green Purchasing: Increasing priority due to health consciousness and sustainability concerns.","Choice Architecture: The way choices are presented to influence decision-making (nudging).","Digital Nudging: Subtly guiding consumer behavior in online environments (defaults, framing, badges)."],"examTip":"SOR framework: Stimulus → Organism → Response. Digital nudging uses choice architecture to guide behavior."}}]$expected_content$::jsonb,
  'consumer-behaviour: note published payload and identity match source');
