    where i.course_id = '40000000-0000-4000-8000-000000000006' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"4f30ad18-a227-52ec-8530-1387b4a0cda7","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"b2cbe46b-eb1b-426c-add7-a9cdfcc11447","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Consumer behaviour is best defined as:","options":["The study of how companies manipulate people","The behavior consumers display in searching for, purchasing, using, and disposing of products","The mathematical calculation of price elasticity","The psychology of employee management"],"correctOption":1,"section":"Introduction to Consumer Behaviour"}},{"itemId":"b4fc986f-3183-5bbf-b7a3-b4999979763e","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"9a3a0e79-2c1f-4440-b0e8-714376071704","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"Post-purchase behaviour is critical because:","options":["It has no impact on future sales","Satisfied customers become loyal and generate positive word-of-mouth","Consumers always forget their purchases","It only matters for expensive items"],"correctOption":1,"section":"Decision-Making Process"}},{"itemId":"5e33bd76-79dc-58a1-a591-c0095d692e88","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"a629492a-9832-48e5-8358-649c8ab586e5","sourceKey":"quiz:11","parentItemId":null,"revision":1,"payload":{"prompt":"Culture is the broadest influence on consumer behaviour because it dictates:","options":["Only language","Fundamental tastes, norms, values, and traditions","Nothing important","Only clothing choices"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"4dd2f91d-faea-52d1-bd29-7c397ab9c4f0","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"7455a373-5a00-42b0-b027-74f5e48b312c","sourceKey":"quiz:12","parentItemId":null,"revision":1,"payload":{"prompt":"A sub-culture is:","options":["The main culture of a country","A smaller group within a culture providing specific identification (nationality, religion, region)","A group with no culture","Only applicable to rural areas"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"296b2a8e-f1b1-5e82-b012-c4f705f0be20","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"da327322-fd8e-4c31-adbb-955f91ff8957","sourceKey":"quiz:13","parentItemId":null,"revision":1,"payload":{"prompt":"Social class affects consumer behaviour through:","options":["No impact whatsoever","Wealth, education, values influencing media consumption and product choices","Only job title","Physical appearance"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"eed9cdf0-4890-53ed-bfa2-c724fa99f6a6","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"1c1d9485-0552-494e-927d-823dc331696e","sourceKey":"quiz:14","parentItemId":null,"revision":1,"payload":{"prompt":"Reference groups are:","options":["Groups used as a standard for evaluating one's own behavior or purchasing decisions","Groups with no influence","Only family members","Fictional characters"],"correctOption":0,"section":"Group & Cultural Influences"}},{"itemId":"f364eb86-6c44-534c-b486-9281c9e847e8","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"18600cc3-097d-484d-8e98-86797786babe","sourceKey":"quiz:15","parentItemId":null,"revision":1,"payload":{"prompt":"Aspirational groups are:","options":["Groups a person actively avoids","Groups a person wants to join or emulate","Groups with no members","Family only"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"7bce537b-beac-501a-a252-94a89cf35fe6","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"0332336e-b916-49d5-9682-6a79206f5975","sourceKey":"quiz:16","parentItemId":null,"revision":1,"payload":{"prompt":"Informational influence occurs when:","options":["A person ignores all advice","A person seeks explicit expert opinions (e.g., doctor, mechanic)","A person buys randomly","A person avoids information"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"543a6b4b-430e-5db3-9d47-38cd3dd24807","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"cda87dd8-74c4-40e0-8476-5b52eb7da3b6","sourceKey":"quiz:17","parentItemId":null,"revision":1,"payload":{"prompt":"Utilitarian (Normative) influence involves:","options":["Independent decision-making","Buying something to fit in or be rewarded/avoid punishment by friends or family","Avoiding all social groups","Only considering price"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"cd965a3e-7758-52f4-aced-556b2ddae895","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"938f0ada-d2f4-4144-8778-9ad7c1a7a5c5","sourceKey":"quiz:18","parentItemId":null,"revision":1,"payload":{"prompt":"Value-expressive influence means:","options":["Ignoring group values","Adopting values of a group to enhance self-image (e.g., buying eco-friendly products)","Expressing anger","Hiding your values"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"d9ab01fc-ee90-5b7f-bf03-5f39c2335dba","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"3048441c-34b5-4460-ae1b-a53792a44faa","sourceKey":"quiz:19","parentItemId":null,"revision":1,"payload":{"prompt":"Social stratification (social class) is typically measured using:","options":["Height and weight","Occupation, income, and education","Favorite color","Shoe size"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"fc979dbb-b10a-5777-8b21-f6b63ce498fc","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"33a0df98-c0b8-464a-9780-2a08831369bf","sourceKey":"quiz:2","parentItemId":null,"revision":1,"payload":{"prompt":"What is