  where kind = 'course_overview') = $expected_content$[{"itemId":"fc9a0adc-5f6f-5c98-a35f-7473c94a400a","courseId":"40000000-0000-4000-8000-000000000007","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":3,"payload":{"title":"Financial Accounting I","body":"Fundamentals of financial accounting under IFRS: the IASB conceptual framework and the key standards governing revenue, financial-statement presentation, inventories, accounting policies, property, plant and equipment, government grants, and borrowing costs.","topics":[{"chapter":"1","description":"IASB Framework for the Preparation and Presentation of Financial Statements"},{"chapter":"2","description":"IFRS 15 - Revenue from Contracts with Customers"},{"chapter":"3","description":"IAS 1 - Presentation of Financial Statements"},{"chapter":"4","description":"IAS 2 - Accounting for Inventory"},{"chapter":"5","description":"IAS 8 - Accounting Policies, Changes in Estimates and Errors"},{"chapter":"6","description":"IAS 16 - Property, Plant, and Equipment (PPE)"},{"chapter":"7","description":"IAS 20 - Government Grants"},{"chapter":"8","description":"IAS 23 - Borrowing Costs"}],"examFocus":["IASB Framework qualitative characteristics","IFRS 15 five-step revenue recognition model","IAS 1 complete set of financial statements","IAS 2 inventory valuation (lower of cost and NRV)","IAS 8 retrospective vs prospective application","IAS 16 depreciation calculations (straight-line & reducing balance)","IAS 20 government grants recognition rules","IAS 23 borrowing costs capitalization"],"outcomes":["Explain the purpose of the Conceptual Framework, the qualitative characteristics, the elements, recognition and measurement.","Apply the five-step model of IFRS 15 to recognise revenue.","Prepare and present financial statements in line with IAS 1.","Measure inventories at the lower of cost and net realisable value under IAS 2.","Account for changes in accounting policies and estimates, and correct prior period errors, under IAS 8.","Recognise, measure, depreciate, revalue and derecognise property, plant and equipment under IAS 16.","Account for government grants under IAS 20.","Capitalise borrowing costs on qualifying assets under IAS 23."],"assessment":["Expect objective questions and calculations on each standard.","Calculations come up in every topic. Work through every worked example until you can do them quickly.","Every topic is examinable."]}}]$expected_content$::jsonb,
  'financial-accounting-1: course_overview published payload and identity match source');
