  from public.read_published_managed_content('40000000-0000-4000-8000-000000000008')
  where kind = 'course_overview') = $expected_content$[{"itemId":"684b4900-fe11-57fe-9c14-d7270a801804","courseId":"40000000-0000-4000-8000-000000000008","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":3,"payload":{"title":"Communication in English","body":"Communication skills course covering listening, the sounds of English, stress and intonation, reading and comprehension, writing, grammar, vocabulary, and using the library and information sources.","outcomes":["Listen effectively in lectures and take notes that capture the essence of what is said.","Describe the organs of speech and identify the consonants, vowels and diphthongs of English with their symbols.","Divide words into syllables, place stress correctly and use the intonation tunes of English.","Read efficiently, using skimming, scanning and study reading, and avoid the common reading faults.","Answer comprehension questions and write a summary or synopsis.","Use study-reading methods such as SQ3R and explain how memory works.","Write a well-formed paragraph with a clear topic sentence, unity and coherence.","Write the main types of essay and punctuate correctly.","Build vocabulary and explain how English words are formed.","Identify word classes, phrases, clauses and sentence types, and avoid common sentence errors.","Use the library, its resources and its retrieval tools, and search electronic sources well.","Avoid plagiarism and cite sources in APA, Harvard and MLA style."],"assessment":["The exam is objective (CBT). Questions test definitions, lists and counts, examples, symbols and the exact wording used in this course.","Every topic is examinable."]}}]$expected_content$::jsonb,
  'use-of-english: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
