  from public.read_published_managed_content('40000000-0000-4000-8000-000000000008')
  where kind = 'note') = $expected_content$[{"itemId":"e3464900-6162-5329-821c-edc367e2f880","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Listening Skills","body":"What listening is and why it matters in lectures; the three conditions that cause ineffective listening; the seven strategies for better listening; formal versus informal listening; how listening links to note-taking (requirements, strategies, before/during/after a lecture, symbols and abbreviations).","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What listening is and why it matters in lectures; the three conditions that cause ineffective listening; the seven strategies for better listening; formal versus informal listening; how listening links to note-taking (requirements, strategies, before/during/after a lecture, symbols and abbreviations)."}],"lessons":[{"number":"1.1","title":"Listening and the lecture method","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Listening:","bold":true},{"text":" the ability of a person to "},{"text":"receive, perceive and decode","bold":true},{"text":" the meaning of spoken words. In class, it is the ability to receive, perceive and decode the meaning of what the lecturer is disseminating as knowledge. In short: the ability to identify and understand what a speaker is saying."}]},{"text":[{"text":"Listening is a "},{"text":"receptive skill","bold":true},{"text":" in language and communication. You must acquire it "},{"text":"consciously","bold":true},{"text":" to reach "},{"text":"communicative competence","bold":true},{"text":", which leads to excellence in your studies."}]},{"text":[{"text":"Why it is important:","bold":true},{"text":" without listening, communication is impossible."}]},{"text":[{"text":"Knowledge in a university is communicated through "},{"text":"lectures","bold":true},{"text":". The main goal of a lecture is to "},{"text":"impart knowledge","bold":true},{"text":" to students. Your duty is to capture the "},{"text":"essence","bold":true},{"text":" of what the lecturer says in your notes, which is impossible without effective listening."}]},{"text":[{"text":"A lecture has three parts:","bold":true},{"text":" introduction, main lecture (body) and conclusion."}]},{"text":[{"text":"Course outline:","bold":true},{"text":" a listing of the relevant "},{"text":"topics to be treated in a particular course","bold":true},{"text":", provided by the "},{"text":"lecturer","bold":true},{"text":"."}]},{"text":[{"text":"This course (GST 111, formerly GST 105 Use of English) covers listening, speaking (the sounds of English, i.e. phonology), reading, writing, grammar, vocabulary and use of the library. Epistemology is not part of it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The four language skills divide into two groups. "},{"text":"Receptive:","bold":true},{"text":" listening and reading (you take language in). "},{"text":"Productive:","bold":true},{"text":" speaking and writing (you produce language). When a question in this topic asks for the receptive skill, the answer is "},{"text":"listening","bold":true},{"text":"."}]},{"text":[{"text":"Trap: listening is "},{"text":"not","bold":true},{"text":" predicting what the speaker will say, guiding the speaker's speech, or simply keeping quiet. Keeping quiet is good manners; listening is understanding."}]},{"text":[{"text":"Trap: listening is the ability to receive, perceive and decode meaning. \"Denounce\" (to condemn publicly) is not part of the definition."}]},{"text":[{"text":"The skills involved in listening include understanding the speaker's "},{"text":"accent, vocabulary and presentation","bold":true},{"text":" of the topic. Reading the topic beforehand and preparing for the lecture are pre-lecture activities, not listening skills themselves."}]},{"text":[{"text":"A lecture is mostly one-way delivery, not an equal trade of information. Giving a course outline or introducing the lecturer is not its goal."}]},{"text":[{"text":"The course outline is prepared before teaching begins, so it lists topics, not the specific or main points raised in a lecture. Those belong in your notes."}]}]}]},{"number":"1.2","title":"Factors responsible for ineffective and unproductive listening","mustKnow":[{"type":"paragraph","text":[{"text":"Three conditions make listening ineffective:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical condition of the environment","bold":true},{"text":" where you receive the lecture. A "},{"text":"noisy","bold":true},{"text":" or "},{"text":"ill-ventilated","bold":true},{"text":" room inhibits listening."}]},{"text":[{"text":"Physiological condition of the lecturer:","bold":true},{"text":" his "},{"text":"speech defects, pronunciation problems and intonation","bold":true},{"text":". These are parts of communication skills, but when the speaker is deficient in them they become "},{"text":"barriers to listening","bold":true},{"text":"."}]},{"text":[{"text":"Psychological condition of the listener:","bold":true},{"text":" mostly the "},{"text":"emotional state","bold":true},{"text":" of the listener. It has a great impact on the result of listening."}]}]},{"type":"paragraph","text":[{"text":"Situations that make listening unproductive: noise, speech defects, pronunciation problems, intonation, the mind of the listener."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the condition to the person or thing: "},{"text":"physical = environment","bold":true},{"text":", "},{"text":"physiological = lecturer (speaker)","bold":true},{"text":", "},{"text":"psychological = listener","bold":true},{"text":". A speech defect is a "},{"text":"physiological","bold":true},{"text":" condition. Noise is "},{"text":"physical","bold":true},{"text":". Grief or excitement in the listener is "},{"text":"psychological","bold":true},{"text":"."}]},{"text":[{"text":"Trap: a \"spiritual\" condition is not one of the three."}]},{"text":[{"text":"Other barriers: an unfamiliar accent or speech affectation, and difficult vocabulary. "},{"text":"Organised and cohesive speech","bold":true},{"text":" helps the listener, so it does not harm listening."}]}]}]},{"number":"1.3","title":"Strategies for enhancing listening skills","mustKnow":[{"type":"paragraph","text":[{"text":"Seven strategies, in this order:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Eye contact:","bold":true},{"text":" maintaining eye contact with your lecturer is the "},{"text":"beginning","bold":true},{"text":" of any attempt at effective listening. It links your mind with the speaker's and establishes your physical readiness to process the message."}]},{"text":[{"text":"Identify and concentrate on the content of the lecture:","bold":true},{"text":" first identify what the lecture is about, then focus your mind on the content."}]},{"text":[{"text":"Repress all forms of emotional attachment:","bold":true},{"text":" suppress your emotion so that your interest is a product of genuine interest to know."}]},{"text":[{"text":"Avoid distractions:","bold":true},{"text":" noises inside and outside the lecture room."}]},{"text":[{"text":"Listening as a mental challenge:","bold":true},{"text":" see listening as a challenge you can overcome; prepare psychologically by stimulating your interest in the lecture."}]},{"text":[{"text":"Ask mental questions","bold":true},{"text":" as the lecture progresses."}]},{"text":[{"text":"Avoid hasty generalisations and conclusions:","bold":true},{"text":" be patient enough to let the speaker finish the point before you react."}]}]},{"type":"paragraph","text":[{"text":"Effective listening requires that you pay "},{"text":"total attention","bold":true},{"text":" to what the speaker is saying."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Eye contact","bold":true},{"text":" also lets you focus on the lecturer's actions in laboratory demonstrations or step-by-step explanations. Exam wording: maintain "},{"text":"eye","bold":true},{"text":" contact (not \"close\", \"full\" or \"virtual\")."}]},{"text":[{"text":"Emotional attachment","bold":true},{"text":" to the subject leads to "},{"text":"prejudices","bold":true},{"text":", which may come from religious, cultural, economic, tribal or financial bias against the topic or the lecturer. Personal emotions such as grief, happiness or love also hinder listening."}]},{"text":[{"text":"Distractions","bold":true},{"text":" include music, friends and classmates talking, spectacles created by people's manner of dressing, and humorous remarks by the lecturer. Admiring the lecturer's outfit is a distraction, not listening."}]},{"text":[{"text":"Mental questions","bold":true},{"text":" to ask: What is the main thrust of the lecture? How does it relate to my past knowledge of previous topics? What other course in my field has said something about this topic?"}]},{"text":[{"text":"Hasty generalisation:","bold":true},{"text":" drawing your conclusion on the content before the lecture ends. However attractive, agitating or irritating the delivery, there may still be something in it you will benefit from. Listen to the end, or until the lecturer pauses for your reaction."}]},{"text":[{"text":"Trap: effective listening does "},{"text":"not","bold":true},{"text":" mean dictating the speaker's pace, or judging his attitude and comportment. Critical thinking is useful, but it comes after you have fully taken in what was said."}]}]}]},{"number":"1.4","title":"Formal and informal listening","mustKnow":[{"type":"paragraph","text":[{"text":"There are "},{"text":"two types","bold":true},{"text":" of listening: "},{"text":"formal","bold":true},{"text":" and "},{"text":"informal","bold":true},{"text":"."}]},{"type":"table","header":[[],[{"text":"Formal listening"}],[{"text":"Informal listening"}]],"rows":[[[{"text":"Where"}],[{"text":"Specific formal environments, e.g. a university lecture, and all formal contexts"}],[{"text":"Normal, regular conversations with anyone we talk to or who talks to us"}]],[[{"text":"Purpose"}],[{"text":"Specific formal purposes, e.g. to pass exams"}],[{"text":"Not to pass exams; to improve our relationships with people"}]],[[{"text":"Strategies"}],[{"text":"Deploy the seven strategies above for maximum results"}],[{"text":"Still essential to improve our capacity to listen to others"}]]]},{"type":"paragraph","text":[{"text":"In the classroom we engage in formal listening for any of "},{"text":"six purposes","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"comprehend","bold":true},{"text":" or gain a general understanding of the lecture."}]},{"text":[{"text":"To "},{"text":"remember","bold":true},{"text":" a specific equation, formula or concept so you can define it when the time arises."}]},{"text":[{"text":"To "},{"text":"evaluate or criticise","bold":true},{"text":" a theory, a point of logic, the weakness or strength of an argument."}]},{"text":[{"text":"To "},{"text":"analyse","bold":true},{"text":" a step or method of arriving at an answer or the result of an experiment."}]},{"text":[{"text":"To "},{"text":"learn","bold":true},{"text":" so as to outline, account for and discuss the historical development of an event, theory or concept."}]},{"text":[{"text":"To learn the "},{"text":"critical tools","bold":true},{"text":" used in practical analysis of literary texts and how to deploy them to evaluate the texts' categories and functions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"These purposes are "},{"text":"not mutually exclusive","bold":true},{"text":": one lecture may need you to comprehend, criticise and evaluate a concept at the same time."}]},{"text":[{"text":"Lecturers try to focus on a specific topic, but not in every lecture. What you need most is "},{"text":"awareness of the situation","bold":true},{"text":", so you can relate it to former knowledge."}]},{"text":[{"text":"Exam wording: during lectures we engage in "},{"text":"formal","bold":true},{"text":" listening; regular conversations attract "},{"text":"informal","bold":true},{"text":" listening. \"Total\" and \"partial\" are not types of listening."}]},{"text":[{"text":"Informal listening still matters: listening skills shape your relationships in the larger society, not only your academic performance."}]}]}]},{"number":"1.5","title":"Listening and note-taking","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why take notes:","bold":true},{"text":" you cannot remember everything you listen to, however ingenious you are. Even verbatim recall is "},{"text":"tentative","bold":true},{"text":"; after a period you forget part or even the entire main gist. Hence the necessity of taking notes while listening."}]},{"text":[{"text":"Note-taking:","bold":true},{"text":" the aspect of communication skills that involves your ability to "},{"text":"keep a record of a speaker's message","bold":true},{"text":" and to "},{"text":"record the essential points from textbooks or written materials","bold":true},{"text":". Through it you engage actively in learning and produce your own written record of main ideas and important details for revision and examinations."}]}]},{"type":"paragraph","text":[{"text":"Six requirements of effective note-taking.","bold":true},{"text":" You must be able to:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Recognise the main ideas","bold":true},{"text":" in a speaker's message, lecture or reading material."}]},{"text":[{"text":"Identify only relevant information","bold":true},{"text":" from the lecture or reading."}]},{"text":[{"text":"Devise a personal system","bold":true},{"text":" of recording information that works for you (e.g. a format with columns: Heading, Source, Reference, Content, Details)."}]},{"text":[{"text":"Reduce the content","bold":true},{"text":" of the lecture to note form, possibly with a diagram format."}]},{"text":[{"text":"Possess the skills of "},{"text":"sentence reduction, summary, paraphrasing","bold":true},{"text":", etc."}]},{"text":[{"text":"Correctly cite and reference","bold":true},{"text":" sources when making notes from a textbook."}]}]},{"type":"paragraph","text":[{"text":"Five strategies for effective note-taking:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define the purpose","bold":true},{"text":" for listening or reading; have a firm grasp of the message or topic before you begin. For written material, skim and highlight the relevant parts."}]},{"text":[{"text":"Identify the function and purpose","bold":true},{"text":" of the text or lecture: make out the potentially important information; overview the outline as you listen or read. For a book, read the title, preface, foreword, abstract, table of contents and introduction, and skim the material."}]},{"text":[{"text":"Know the "},{"text":"organising principles","bold":true},{"text":" by which the lecturer or textbook presents the information."}]},{"text":[{"text":"Include your own thoughts","bold":true},{"text":" in the note, in a separate column or on the margin."}]},{"text":[{"text":"Do not write verbatim.","bold":true},{"text":" Use "},{"text":"shorthand","bold":true},{"text":": symbols, abbreviations, concept maps or diagrams."}]}]},{"type":"paragraph","text":[{"text":"Before, during and after a live lecture:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Before:","bold":true},{"text":" revise previous related lectures; read about the topic (a "},{"text":"pre-lecture survey","bold":true},{"text":"); check the meaning of new words that are vital terms in the course; prepare the format for note-taking; arrive in time to sit close to the lecturer."}]},{"text":[{"text":"During:","bold":true},{"text":" distinguish the lecture's "},{"text":"main points","bold":true},{"text":" from elaborations, examples, repetitions and re-statements; listen for "},{"text":"transition cues","bold":true},{"text":" (in addition, however, moreover, consequently) that mark movement from introduction to body to conclusion or summary; look out for "},{"text":"non-verbal cues","bold":true},{"text":" (facial expressions, gesticulations, body movement); observe "},{"text":"illustrations and demonstrations","bold":true},{"text":" with visual materials (diagrams, tables, drawings and their labels); listen for "},{"text":"phonological cues","bold":true},{"text":" (voice changes, accent, word stress, speed, emotional nuances)."}]},{"text":[{"text":"After:","bold":true},{"text":" "},{"text":"revise or review","bold":true},{"text":" the notes as soon as possible and compare notes with course-mates; "},{"text":"tidy up","bold":true},{"text":" handwriting and fill in missing bits; try out a "},{"text":"summary","bold":true},{"text":" of the lecture in your own words."}]}]},{"type":"paragraph","text":[{"text":"Common symbols and abbreviations:","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}],[{"text":"Abbreviation"}],[{"text":"Meaning"}]],"rows":[[[{"text":"→"}],[{"text":"gives, causes, leads to, results in"}],[{"text":"c.f."}],[{"text":"confer, compare"}]],[[{"text":"≠"}],[{"text":"not equal to, not the same as"}],[{"text":"i.e."}],[{"text":"that is"}]],[[{"text":"≡"}],[{"text":"equivalent to"}],[{"text":"NB"}],[{"text":"note well"}]],[[{"text":"¶"}],[{"text":"paragraph"}],[{"text":"diff."}],[{"text":"different"}]],[[{"text":"@"}],[{"text":"at"}],[{"text":"gov"}],[{"text":"government"}]],[[{"text":"&"}],[{"text":"and"}],[{"text":"NEC"}],[{"text":"necessary"}]],[[{"text":"+"}],[{"text":"more, plus, and"}],[{"text":"no."}],[{"text":"number"}]],[[],[],[{"text":"ed."}],[{"text":"editor"}]],[[],[],[{"text":"edn."}],[{"text":"edition"}]],[[],[],[{"text":"dev."}],[{"text":"development"}]],[[],[],[{"text":"L1"}],[{"text":"first language"}]],[[],[],[{"text":"cd."}],[{"text":"could"}]],[[],[],[{"text":"exc."}],[{"text":"except"}]],[[],[],[{"text":"incl."}],[{"text":"including"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organising principles","bold":true},{"text":" a lecture or text may follow: steps or stages of a process or event; general to specific ideas; simple to complex ideas; problems and solutions; causes and results; largest parts to smallest parts; well-known ideas to least known; most important point to least important; past ideas to present ones."}]},{"text":[{"text":"Note-taking from a text differs from note-taking in a live lecture because you cannot stop the lecturer to ask for a review (unless it is a recording). Hence the before, during and after activities."}]},{"text":[{"text":"Good notes are:","bold":true},{"text":" brief and concise, legible, systematic and orderly. They are "},{"text":"not","bold":true},{"text":" all that is said in class."}]},{"text":[{"text":"Good habits:","bold":true},{"text":" record the main points with a "},{"text":"selection","bold":true},{"text":" of illustrations and examples; summarise main points; think logically about ideas; disregard digressions; use personal abbreviations "},{"text":"consistently","bold":true},{"text":"."}]},{"text":[{"text":"Bad habits:","bold":true},{"text":" verbatim recording; recording all the lecturer says; recording main points with "},{"text":"all","bold":true},{"text":" the illustrations; using "},{"text":"inconsistent","bold":true},{"text":" personal abbreviations."}]},{"text":[{"text":"Pre-lecture preparation:","bold":true},{"text":" surveying the course outline and topic beforehand, reading introductory surveys of an unfamiliar topic, and arriving before the lecturer are all good. Speculating about the lecturer's sources is "},{"text":"not","bold":true},{"text":" preparation. A "},{"text":"pre-lecture survey","bold":true},{"text":" means reading up on a topic before the lecture."}]},{"text":[{"text":"Post-lecture activities are review, revision and summary. \"Disposal\" (throwing notes away) is not one."}]},{"text":[{"text":"Note-taking skills are sentence reduction, summary and paraphrasing. "},{"text":"Sound articulation","bold":true},{"text":" is a speaking skill, not a note-taking skill."}]},{"text":[{"text":"Abbreviation trap: "},{"text":"NEC","bold":true},{"text":" means \"necessary\", not National Executive Council or National Electoral Commission."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Listening = ability to receive, perceive and decode the meaning of spoken words; a receptive skill; without it communication is impossible."}]},{"text":[{"text":"A lecture imparts knowledge: introduction, main lecture, conclusion. A course outline lists a course's topics; the lecturer provides it."}]},{"text":[{"text":"Three conditions hinder listening: physical (environment), physiological (lecturer), psychological (listener)."}]},{"text":[{"text":"Seven strategies: eye contact; concentrate on content; repress emotional attachment; avoid distractions; mental challenge; mental questions; no hasty generalisations."}]},{"text":[{"text":"Formal listening (lectures; six purposes) versus informal (normal conversations)."}]},{"text":[{"text":"Six requirements and five strategies of note-taking; never verbatim, use shorthand consistently."}]},{"text":[{"text":"Before: revise, read up, check new words, prepare format, arrive early. During: main points, transition, non-verbal, visual and phonological cues. After: review, tidy up, summarise."}]},{"text":[{"text":"Good notes: brief, legible, systematic, orderly. NEC = necessary, c.f. = compare, NB = note well."}]}]}],"theory":{"itemId":"ec7fe978-c8e8-53e4-be5f-cc7dd10fcb82","question":[{"type":"paragraph","text":[{"text":"Define listening and discuss four strategies for enhancing listening skills."}]}]},"practice":[{"topic":"Listening Skills and Note-taking","named":false}]}},{"itemId":"bd5fff77-dc4a-5971-94fd-9946bf1edb57","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:10","parentItemId":null,"revision":1,"payload":{"title":"Grammar I: Word Classes and Phrases","body":"Grammar and its two branches (morphology, syntax); the hierarchy morpheme to sentence; free and bound morphemes; 8 traditional parts of speech against 9 modern word classes and the three criteria; forms, sub-classes and functions of nouns; sub-classes and cases of pronouns; determiners; adjectives (sub-classes, position, degree); verbs (5 forms, tenses, transitive/intransitive, primary and modal auxiliaries); adverbs; prepositions, the four groups of conjunctions, interjections; the phrase and its 8 types.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"Grammar and its two branches (morphology, syntax); the hierarchy morpheme to sentence; free and bound morphemes; 8 traditional parts of speech against 9 modern word classes and the three criteria; forms, sub-classes and functions of nouns; sub-classes and cases of pronouns; determiners; adjectives (sub-classes, position, degree); verbs (5 forms, tenses, transitive/intransitive, primary and modal auxiliaries); adverbs; prepositions, the four groups of conjunctions, interjections; the phrase and its 8 types."}],"lessons":[{"number":"10.1","title":"Grammar, its units and word classes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grammar:","bold":true},{"text":" the system of rules that determines how words are formed and combined to make sentences; in short, "},{"text":"the study of sentence structure","bold":true},{"text":"."}]},{"text":[{"text":"2 branches:","bold":true},{"text":" (1) "},{"text":"morphology","bold":true},{"text":", how words are formed; (2) "},{"text":"syntax","bold":true},{"text":", how constituents are arranged within a sentence."}]},{"text":[{"text":"2 steps in studying grammar:","bold":true},{"text":" (1) identify the "},{"text":"units or constituents","bold":true},{"text":" (words, phrases, clauses, sentences); (2) analyse the "},{"text":"patterns","bold":true},{"text":" they fall into and the meaning those patterns communicate."}]},{"text":[{"text":"Grammatical hierarchy, smallest to largest:","bold":true},{"text":" 1. morpheme, 2. word, 3. phrase, 4. clause, 5. sentence. The "},{"text":"morpheme","bold":true},{"text":" is the smallest unit, the "},{"text":"sentence","bold":true},{"text":" the largest. "},{"text":"Words are the building blocks of a sentence.","bold":true}]},{"text":[{"text":"Morpheme:","bold":true},{"text":" the smallest meaningful unit. "},{"text":"Free morphemes","bold":true},{"text":" stand alone as words (boy, go, in); "},{"text":"bound morphemes","bold":true},{"text":" cannot; they are affixes (un-, -s, -ed, -ly). Free morphemes sub-divide into "},{"text":"lexical","bold":true},{"text":" (content words: nouns, verbs, adjectives, adverbs) and "},{"text":"functional","bold":true},{"text":" (grammar words: prepositions, conjunctions, determiners, pronouns)."}]},{"text":[{"text":"Open class words:","bold":true},{"text":" classes to which new words can always be added (nouns, verbs, adjectives, adverbs). "},{"text":"Closed class (grammatical) words","bold":true},{"text":" rarely gain members (prepositions, conjunctions, determiners, pronouns)."}]},{"text":[{"text":"Parts of speech:","bold":true},{"text":" the "},{"text":"traditional","bold":true},{"text":" label, based on "},{"text":"notional (meaning)","bold":true},{"text":" criteria; "},{"text":"8","bold":true},{"text":" classes: nouns, pronouns, adjectives, verbs, prepositions, conjunctions, adverbs, interjections."}]},{"text":[{"text":"Word classes:","bold":true},{"text":" the "},{"text":"contemporary","bold":true},{"text":" label; "},{"text":"9","bold":true},{"text":" classes: nouns, pronouns, adjectives, "},{"text":"determiners","bold":true},{"text":", verbs, adverbs, prepositions, conjunctions, interjections."}]},{"text":[{"text":"3 criteria for a word's class:","bold":true},{"text":" (1) "},{"text":"notional (semantic):","bold":true},{"text":" meaning; (2) "},{"text":"morphological:","bold":true},{"text":" the affixes it takes; (3) "},{"text":"syntactic:","bold":true},{"text":" its position in the sentence and whether a regular word of the same class can replace it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Notional definitions: nouns signify "},{"text":"entities","bold":true},{"text":"; verbs "},{"text":"actions","bold":true},{"text":"; adjectives "},{"text":"states","bold":true},{"text":"; adverbs "},{"text":"manner","bold":true},{"text":"; prepositions "},{"text":"location","bold":true},{"text":"."}]},{"text":[{"text":"Why these are vague: "},{"text":"extermination","italic":true},{"text":" signifies an action but is a "},{"text":"noun","bold":true},{"text":"; "},{"text":"quick","italic":true},{"text":" in "},{"text":"quick fix","italic":true},{"text":" signifies manner but is an "},{"text":"adjective","bold":true},{"text":"; "},{"text":"Ibadan","italic":true},{"text":" denotes a location but is a "},{"text":"noun","bold":true},{"text":"."}]},{"text":[{"text":"Structural clues: a "},{"text":"determiner","bold":true},{"text":" signals a noun; a word that takes the "},{"text":"3rd person -s","bold":true},{"text":", "},{"text":"past tense","bold":true},{"text":" and "},{"text":"-ing","bold":true},{"text":" endings is likely a "},{"text":"verb","bold":true},{"text":"."}]},{"text":[{"text":"Trap: a paragraph is a unit of writing, not of grammar; lexis and syntax are areas of study, not units."}]},{"text":[{"text":"Trap: \"the study of the arrangement of constituents in a sentence\" is "},{"text":"syntax","bold":true},{"text":". Grammar is too broad (it includes morphology); graphology is the writing system."}]}]}]},{"number":"10.2","title":"Nouns","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Noun:","bold":true},{"text":" names a "},{"text":"person","bold":true},{"text":" (David), "},{"text":"animal","bold":true},{"text":" (lion), "},{"text":"place","bold":true},{"text":" (Nigeria), "},{"text":"thing","bold":true},{"text":" (book), "},{"text":"idea","bold":true},{"text":" (love), "},{"text":"incident","bold":true},{"text":" (flood) or "},{"text":"event","bold":true},{"text":" (Christmas)."}]},{"text":[{"text":"Structural definition:","bold":true},{"text":" takes the "},{"text":"plural","bold":true},{"text":" (tables), has a "},{"text":"possessive","bold":true},{"text":" (Bola's bag), can follow a "},{"text":"determiner","bold":true},{"text":" (a/this/my ball), occurs before and after a verb (Dayo is a boy). A noun "},{"text":"has no tense","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 grammatical forms:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Singular:","bold":true},{"text":" one; the dictionary headword (sister, apple)."}]},{"text":[{"text":"Plural:","bold":true},{"text":" more than one; regular nouns add "},{"text":"-s/-es","bold":true},{"text":" (sisters, apples)."}]},{"text":[{"text":"Singular possessive:","bold":true},{"text":" apostrophe + s (wife's, clown's)."}]},{"text":[{"text":"Plural possessive:","bold":true},{"text":" apostrophe after the plural -s (girls', clowns'); irregular plurals keep the -s (men's, children's)."}]}]},{"type":"paragraph","text":[{"text":"Pronunciation of plural -s/-es:","bold":true}]},{"type":"table","header":[[{"text":"Sound"}],[{"text":"After"}],[{"text":"Examples"}]],"rows":[[[{"text":"/s/"}],[{"text":"voiceless consonants"}],[{"text":"gates, taps, desks"}]],[[{"text":"/z/"}],[{"text":"voiced consonants and vowels"}],[{"text":"roads, friends, bananas"}]],[[{"text":"/ɪz/"}],[{"text":"sibilants /s, z, ʃ, ʒ, tʃ, dʒ/"}],[{"text":"nieces, wishes, judges, churches"}]]]},{"type":"paragraph","text":[{"text":"6 kinds of irregular noun:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Vowel change:","bold":true},{"text":" foot/feet, mouse/mice, man/men, tooth/teeth, woman/women, louse/lice, goose/geese."}]},{"text":[{"text":"-en/-ren:","bold":true},{"text":" brother/brethren, child/children, ox/oxen."}]},{"text":[{"text":"-f/-fe to -ves:","bold":true},{"text":" knife/knives, half/halves, leaf/leaves, wife/wives, loaf/loaves, wolf/wolves, hoof/hooves, scarf/scarves (dwarf: dwarfs/dwarves)."}]},{"text":[{"text":"No change:","bold":true},{"text":" sheep, aircraft, furniture, deer, salmon, grouse."}]},{"text":[{"text":"Plural only:","bold":true},{"text":" cattle, spectacles, shorts, glasses, clothes, pyjamas, tongs, scissors, trousers, binoculars."}]},{"text":[{"text":"With or without -s:","bold":true},{"text":" fish/fishes, elk/elks, herring/herrings, antelope/antelopes."}]}]},{"type":"paragraph","text":[{"text":"3 sub-class distinctions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Proper","bold":true},{"text":" (particular person, place, thing or idea; "},{"text":"usually capitalised","bold":true},{"text":": Chief Daniel, National Museum, Peugeot, Darwinism) versus "},{"text":"common","bold":true},{"text":" (general name: man, house, car, temptation). "},{"text":"Collective nouns","bold":true},{"text":" are common nouns naming a group: crew, staff, army, jury, chorus, panel, council, choir."}]},{"text":[{"text":"Count","bold":true},{"text":" (singular and plural: dog/dogs) versus "},{"text":"non-count","bold":true},{"text":" (no plural: furniture, warmth, grass, humour). A division of "},{"text":"common","bold":true},{"text":" nouns."}]},{"text":[{"text":"Concrete","bold":true},{"text":" (occupies space or is perceived by the senses: drug, sweet, music) versus "},{"text":"abstract","bold":true},{"text":" (idea, quality, characteristic: Christianity, Islam, Marxism, youth). Also a division of "},{"text":"common","bold":true},{"text":" nouns."}]}]},{"type":"paragraph","text":[{"text":"8 functions of a noun:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Subject:","bold":true},{"text":" "},{"text":"Mr Dokunboh","italic":true},{"text":" donated some books."}]},{"text":[{"text":"Direct object","bold":true},{"text":" (answers "},{"text":"what?","italic":true},{"text":"): Mr Dokunboh thanked "},{"text":"the lady","italic":true},{"text":"."}]},{"text":[{"text":"Indirect object","bold":true},{"text":" (answers "},{"text":"to/for whom?","italic":true},{"text":"): he donated some books to "},{"text":"the school","italic":true},{"text":"."}]},{"text":[{"text":"Subject complement:","bold":true},{"text":" Daniel is "},{"text":"an architect","italic":true},{"text":"."}]},{"text":[{"text":"Object complement:","bold":true},{"text":" They made the boy "},{"text":"the class captain","italic":true},{"text":"."}]},{"text":[{"text":"Prepositional complement:","bold":true},{"text":" I left him at "},{"text":"the bus-stop","italic":true},{"text":"."}]},{"text":[{"text":"Qualifier of another noun:","bold":true},{"text":" a concert on "},{"text":"Independence","italic":true},{"text":" Day."}]},{"text":[{"text":"Appositive:","bold":true},{"text":" The senator, "},{"text":"Mr Malaki","italic":true},{"text":", is very smart."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Possessive in speech follows the /ɪz/, /z/, /s/ rules. A base ending in s keeps the written possessive -s if pronounced (Chris's) and drops it if not (Jesus' name, for conscience' sake)."}]},{"text":[{"text":"A collective noun is "},{"text":"singular","bold":true},{"text":" for the group as a whole (The choir "},{"text":"meets","italic":true},{"text":") and "},{"text":"plural","bold":true},{"text":" for its members (The choir "},{"text":"have been","italic":true},{"text":" split)."}]},{"text":[{"text":"Count/non-count has "},{"text":"nothing to do with your ability to count","bold":true},{"text":"; some nouns are both ("},{"text":"two cup cakes","italic":true},{"text":" / "},{"text":"some cake","italic":true},{"text":")."}]},{"text":[{"text":"Trap: common nouns are classified "},{"text":"count/non-count","bold":true},{"text":" and "},{"text":"concrete/abstract","bold":true},{"text":" (every noun also has singular/plural number). "},{"text":"Possessive/non-possessive","bold":true},{"text":" is not a classification; possessive is a form a noun takes."}]},{"text":[{"text":"Trap: among "},{"text":"John, Kaduna, Ocean, mathematics","italic":true},{"text":", the odd one is "},{"text":"mathematics","bold":true},{"text":", a common noun naming a general field, not capitalised; the others carry the capital letter that marks a proper noun."}]},{"text":[{"text":"Gerund (verbal noun):","bold":true},{"text":" the -ing form used as a noun: "},{"text":"Driving","italic":true},{"text":" is my hobby."}]}]}]},{"number":"10.3","title":"Pronouns and determiners","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pronoun:","bold":true},{"text":" replaces a noun or noun phrase, usually to avoid repetition. "},{"text":"Mr James is my uncle. He lives in Ibadan.","italic":true},{"text":" The noun referred to is the "},{"text":"antecedent","bold":true},{"text":" (Mr James)."}]},{"text":[{"text":"A pronoun agrees with its antecedent in "},{"text":"4","bold":true},{"text":" things: "},{"text":"number, gender, person, case","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"8 sub-classes of pronouns:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal:","bold":true},{"text":" 1st person I, me, we, us; 2nd person you; 3rd person he, she, him, her, it, they, them. Third person singular shows "},{"text":"gender","bold":true},{"text":": he/him masculine, she/her feminine, it neuter."}]},{"text":[{"text":"Possessive:","bold":true},{"text":" ownership; some stand alone (mine, yours, hers, his, theirs, ours), others go before nouns."}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" ask questions: who, whom, whose, what, which."}]},{"text":[{"text":"Relative:","bold":true},{"text":" introduce a "},{"text":"relative (adjectival) clause","bold":true},{"text":": "},{"text":"the dress which I wore; the students who were late; the writer whom I would like to meet.","italic":true}]},{"text":[{"text":"Demonstrative:","bold":true},{"text":" this/that (singular), these/those (plural)."}]},{"text":[{"text":"Reciprocal:","bold":true},{"text":" two-way relationship; English has "},{"text":"two","bold":true},{"text":": "},{"text":"each other, one another","italic":true},{"text":"."}]},{"text":[{"text":"Reflexive and intensive:","bold":true},{"text":" -self/-selves forms (myself, yourself, himself, herself, itself; ourselves, yourselves, themselves). "},{"text":"Reflexive","bold":true},{"text":" reflects back to an earlier noun or pronoun ("},{"text":"He taught himself to drive","italic":true},{"text":"); "},{"text":"intensive","bold":true},{"text":" adds emphasis ("},{"text":"David himself cleaned the room","italic":true},{"text":")."}]},{"text":[{"text":"Indefinite:","bold":true},{"text":" no specific person or thing. Singular: anyone, anybody, either, neither, someone, something, little, much; plural: both, several, few, many, any, some ("},{"text":"Several were taken. Few were expected","italic":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"3 cases:","bold":true}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Use"}],[{"text":"Forms"}]],"rows":[[[{"text":"Subjective"}],[{"text":"subject"}],[{"text":"I, we, he, she, they, you, who, it"}]],[[{"text":"Objective"}],[{"text":"object"}],[{"text":"me, us, him, her, them, you, whom, it"}]],[[{"text":"Possessive"}],[{"text":"ownership"}],[{"text":"my/mine, our/ours, his, her/hers, their/theirs, your/yours, whose, its"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Determiner:","bold":true},{"text":" a word used "},{"text":"before a noun","bold":true},{"text":" to give information about it. Like adjectives, determiners qualify nouns, but they "},{"text":"lack descriptive content","bold":true},{"text":" and name no qualities, so modern grammar separates them."}]}]},{"type":"paragraph","text":[{"text":"5 classes of determiners:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Articles:","bold":true},{"text":" "},{"text":"the","italic":true},{"text":" (definite); "},{"text":"a, an","italic":true},{"text":" (indefinite)."}]},{"text":[{"text":"Possessives:","bold":true},{"text":" his, her, your, our, my, its, their."}]},{"text":[{"text":"Demonstratives:","bold":true},{"text":" this, that, these, those."}]},{"text":[{"text":"Quantifiers:","bold":true},{"text":" some, many, a few, few, little, a little, several, much."}]},{"text":[{"text":"Numerals:","bold":true},{"text":" one, two, three (cardinal); second, third, fortieth (ordinal)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: there is no \"refractive\" pronoun; it is a distortion of "},{"text":"reflexive","bold":true},{"text":"."}]},{"text":[{"text":"Who","italic":true},{"text":" is subjective, "},{"text":"whom","italic":true},{"text":" objective, "},{"text":"whose","italic":true},{"text":" possessive."}]},{"text":[{"text":"These, those, many, few, several","italic":true},{"text":" go only before "},{"text":"plural count","bold":true},{"text":" nouns; "},{"text":"much, little","italic":true},{"text":" with "},{"text":"non-count","bold":true},{"text":" nouns; "},{"text":"the, some","italic":true},{"text":" with both."}]},{"text":[{"text":"Two determiners cannot precede","bold":true},{"text":" one head noun ("},{"text":"that your book","italic":true},{"text":", "},{"text":"some few things","italic":true},{"text":" are wrong). A "},{"text":"singular count noun always needs a determiner","bold":true},{"text":" ("},{"text":"I gave my brother a pencil","italic":true},{"text":", not "},{"text":"pencil","italic":true},{"text":")."}]},{"text":[{"text":"Trap: the phrase with an "},{"text":"indefinite article","bold":true},{"text":" is "},{"text":"a big fat hen","italic":true},{"text":"; "},{"text":"the Golden Globe awards","italic":true},{"text":" has the definite article, "},{"text":"that house","italic":true},{"text":" a demonstrative, "},{"text":"my friend","italic":true},{"text":" a possessive."}]}]}]},{"number":"10.4","title":"Adjectives and adverbs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjective:","bold":true},{"text":" describes a noun or pronoun by "},{"text":"limiting its meaning","bold":true},{"text":"; answers "},{"text":"what kind?","bold":true},{"text":" (a "},{"text":"beautiful","italic":true},{"text":" day), "},{"text":"which one?","bold":true},{"text":" (a "},{"text":"prestigious","italic":true},{"text":" award), "},{"text":"how many?","bold":true},{"text":" ("},{"text":"several","italic":true},{"text":" people)."}]}]},{"type":"paragraph","text":[{"text":"9 sub-classes of adjectives:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Qualitative:","bold":true},{"text":" a quality (honest, rich)."}]},{"text":[{"text":"Classifying:","bold":true},{"text":" the group it belongs to (democratic, psychological)."}]},{"text":[{"text":"Quantifying:","bold":true},{"text":" amount, usually uncountable (some food, all their money)."}]},{"text":[{"text":"Colour:","bold":true},{"text":" brown, red."}]},{"text":[{"text":"Number:","bold":true},{"text":" exact number or order, countable only (ten people, first birthday)."}]},{"text":[{"text":"Emphatic:","bold":true},{"text":" emphasises feeling or degree (complete idiot, total nightmare)."}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" which way? whose house? what kind?"}]},{"text":[{"text":"Demonstrative:","bold":true},{"text":" that ball, this child."}]},{"text":[{"text":"Possessive:","bold":true},{"text":" my children, your mother."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Position:","bold":true},{"text":" before the noun = "},{"text":"attributive","bold":true},{"text":" ("},{"text":"the beautiful woman","italic":true},{"text":"); linked to the noun by a verb = "},{"text":"predicative","bold":true},{"text":" ("},{"text":"the food is delicious","italic":true},{"text":"). Attributive only: a "},{"text":"main","italic":true},{"text":" road, a "},{"text":"commanding","italic":true},{"text":" lead. Predicative only: the woman is "},{"text":"afraid","italic":true},{"text":"; the girl feels "},{"text":"faint","italic":true},{"text":"."}]},{"text":[{"text":"3 degrees:","bold":true},{"text":" "},{"text":"positive","bold":true},{"text":" (big), "},{"text":"comparative","bold":true},{"text":" (two things: bigger), "},{"text":"superlative","bold":true},{"text":" (three or more: biggest)."}]},{"text":[{"text":"Gradable","bold":true},{"text":" adjectives (big, tall, lazy) can be expressed in degrees and modified by adverbs (fairly big, very big). "},{"text":"Non-gradable","bold":true},{"text":" adjectives name absolute or extreme qualities and have no comparative: perfect, real, right, terrible, fatal, superior, ghastly, unique, utter, inferior, fake, genuine."}]},{"text":[{"text":"Adverb:","bold":true},{"text":" modifies a "},{"text":"verb, an adjective or another adverb","bold":true},{"text":" by making its meaning more specific: "},{"text":"Very beautiful women have always enticed foolish men quite successfully.","italic":true}]},{"text":[{"text":"Forms:","bold":true},{"text":" many add "},{"text":"-ly","bold":true},{"text":" to adjectives (smartly, quickly); others are independent words (very, quite, here, yesterday, often, so, nearby)."}]}]},{"type":"paragraph","text":[{"text":"Types of adverb:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Answers"}],[{"text":"Example"}]],"rows":[[[{"text":"Time"}],[{"text":"when?"}],[{"text":"He arrived "},{"text":"yesterday","italic":true},{"text":"."}]],[[{"text":"Manner"}],[{"text":"how?"}],[{"text":"She walks "},{"text":"briskly","italic":true},{"text":"."}]],[[{"text":"Place"}],[{"text":"where?"}],[{"text":"Tade travelled "},{"text":"to Ibadan","italic":true},{"text":"."}]],[[{"text":"Degree"}],[{"text":"to what extent?"}],[{"text":"My mother cooks "},{"text":"very well","italic":true},{"text":"."}]],[[{"text":"Frequency"}],[{"text":"how often?"}],[{"text":"The man jogs "},{"text":"regularly","italic":true},{"text":"."}]],[[{"text":"How many times"}],[{"text":"how many times?"}],[{"text":"Muslims pray "},{"text":"five times","italic":true},{"text":"."}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Comparative adds "},{"text":"-er","bold":true},{"text":" (-r after -e); superlative "},{"text":"-est","bold":true},{"text":" (-st after -e). Longer adjectives take "},{"text":"more/most","bold":true},{"text":" (more difficult, most difficult); some allow either (politer/more polite, likelier/more likely)."}]},{"text":[{"text":"Irregular adjectives:","bold":true},{"text":" good/better/best; bad/worse/worst; much/more/most; many/more/most; far/farther/farthest."}]},{"text":[{"text":"Trap: "},{"text":"tall, taller, tallest","italic":true},{"text":" illustrates a "},{"text":"gradable","bold":true},{"text":" adjective (expressed in degrees); \"comparative\" names only the middle form."}]},{"text":[{"text":"Trap: attributive/predicative = "},{"text":"position","bold":true},{"text":"; positive/comparative/superlative = "},{"text":"form (degree)","bold":true},{"text":"."}]},{"text":[{"text":"Order of adjectives:","bold":true},{"text":" quality, length, weight, size, shape, age, colour, origin, then the noun: "},{"text":"a beautiful big white house; an elegant short pink dress","italic":true},{"text":"."}]},{"text":[{"text":"Adverb degrees:","bold":true},{"text":" cheerfully/more cheerfully/most cheerfully; badly/worse/worst; well/better/best; soon/sooner/soonest; quickly/more quickly/most quickly. Adverbs also show order (first, last)."}]},{"text":[{"text":"Trap: "},{"text":"very well","italic":true},{"text":" is an adverb of "},{"text":"degree","bold":true},{"text":" ("},{"text":"very","italic":true},{"text":" tells the extent of "},{"text":"well","italic":true},{"text":"); "},{"text":"to Ibadan","italic":true},{"text":" works as an adverb of "},{"text":"place","bold":true},{"text":"."}]},{"text":[{"text":"Position:","bold":true},{"text":" an adverb modifying a "},{"text":"verb","bold":true},{"text":" can move ("},{"text":"Quickly he ate / He quickly ate / He ate quickly","italic":true},{"text":"); one modifying an "},{"text":"adjective or adverb","bold":true},{"text":" must come "},{"text":"immediately before","bold":true},{"text":" it ("},{"text":"very kind, so quickly","italic":true},{"text":"). Position changes meaning, since modifiers relate to the "},{"text":"closest modifiable word","bold":true},{"text":": "},{"text":"Smartly, he walked past","italic":true},{"text":" (the walking was smart) versus "},{"text":"He smartly walked past","italic":true},{"text":" (he was smart)."}]}]}]},{"number":"10.5","title":"Verbs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Verb:","bold":true},{"text":" expresses an "},{"text":"action","bold":true},{"text":" or a "},{"text":"state of being","bold":true},{"text":" and is "},{"text":"required to make a sentence","bold":true},{"text":". Action: dance, clap, jump. State of being: "},{"text":"be","bold":true},{"text":" (be, am, is, are, was, were, been, being), become, seem, appear, look, remain, feel, sound, smell."}]},{"text":[{"text":"Forms:","bold":true},{"text":" "},{"text":"be","italic":true},{"text":" has "},{"text":"8","bold":true},{"text":". Other verbs (action and state-of-being) usually have "},{"text":"5","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Base (infinitive):","bold":true},{"text":" dictionary form (look, take)."}]},{"text":[{"text":"Third person singular present:","bold":true},{"text":" -s/-es (looks, takes)."}]},{"text":[{"text":"Past tense","bold":true},{"text":" (looked, took)."}]},{"text":[{"text":"Perfect (past participle)","bold":true},{"text":" (looked, taken)."}]},{"text":[{"text":"Progressive (-ing)","bold":true},{"text":" (looking, taking)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Regular","bold":true},{"text":" verbs add "},{"text":"-ed","bold":true},{"text":" for past and perfect (look, kick, wait); "},{"text":"irregular","bold":true},{"text":" verbs form them otherwise (take, make, go)."}]},{"text":[{"text":"The -s/-es ending is pronounced like the noun plural: /ɪz/ passes, catches, pushes; /z/ robs, goes; /s/ cuts, looks, drinks."}]},{"text":[{"text":"Tense","bold":true},{"text":" relates the action to a "},{"text":"time","bold":true},{"text":". There are "},{"text":"about nine","bold":true},{"text":"; five are treated here:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Simple present:","bold":true},{"text":" something done "},{"text":"regularly","bold":true},{"text":" or going on all the time ("},{"text":"I jog every morning; The cock crows at dawn","italic":true},{"text":"). It signals "},{"text":"regularity","bold":true},{"text":"."}]},{"text":[{"text":"Present continuous:","bold":true},{"text":" happening "},{"text":"at the time of speaking or writing","bold":true},{"text":"; "},{"text":"be + -ing","bold":true},{"text":" ("},{"text":"I am dancing","italic":true},{"text":")."}]},{"text":[{"text":"Present perfect:","bold":true},{"text":" past action "},{"text":"linked to the present","bold":true},{"text":"; "},{"text":"has/have + past participle","bold":true},{"text":" ("},{"text":"I have lived in Lagos for ten years","italic":true},{"text":": started then, still there)."}]},{"text":[{"text":"Simple past:","bold":true},{"text":" happened and "},{"text":"completed","bold":true},{"text":" in the past ("},{"text":"I went to school yesterday","italic":true},{"text":")."}]},{"text":[{"text":"Simple future:","bold":true},{"text":" not yet happened; "},{"text":"will/shall + base","bold":true},{"text":" ("},{"text":"I shall leave for Kano tomorrow","italic":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Transitive verb:","bold":true},{"text":" action passes from subject to an "},{"text":"object","bold":true},{"text":"; it always occurs with an object ("},{"text":"The man shut the door","italic":true},{"text":"). "},{"text":"Intransitive verb:","bold":true},{"text":" subject but "},{"text":"no object","bold":true},{"text":" ("},{"text":"The baby slept; The baby cried","italic":true},{"text":")."}]},{"text":[{"text":"Auxiliary (helping) verbs","bold":true},{"text":" come in "},{"text":"2 types","bold":true},{"text":": "},{"text":"primary","bold":true},{"text":" ("},{"text":"have, be, do","bold":true},{"text":"), which can also be main verbs; "},{"text":"modal","bold":true},{"text":" (can, could, will, would, shall, should, may, might, must, ought to), which "},{"text":"cannot stand alone as main verbs","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary auxiliaries in both roles: "},{"text":"The dress is long","italic":true},{"text":" (main) / "},{"text":"The man is playing","italic":true},{"text":" (auxiliary); "},{"text":"I have a car","italic":true},{"text":" / "},{"text":"I have bought a car","italic":true},{"text":"; "},{"text":"I do a lot of knitting","italic":true},{"text":" / "},{"text":"I don't drink","italic":true},{"text":"."}]},{"text":[{"text":"Modals express possibility, probability, "},{"text":"ability","bold":true},{"text":" ("},{"text":"can","italic":true},{"text":"), "},{"text":"permission","bold":true},{"text":" ("},{"text":"may","italic":true},{"text":"), prediction, "},{"text":"obligation","bold":true},{"text":" ("},{"text":"must","italic":true},{"text":"), offers, promises."}]},{"text":[{"text":"Trap: "},{"text":"will, shall, could, should, can, may","italic":true},{"text":" are "},{"text":"modal auxiliaries","bold":true},{"text":". Auxiliaries are classified "},{"text":"primary and modal","bold":true},{"text":", never \"primary and secondary\" or \"modal and main\"; regular/irregular classifies verbs by past-tense formation."}]},{"text":[{"text":"Trap: simple present = "},{"text":"regularity","bold":true},{"text":", not \"now\"; \"now\" is the present continuous."}]},{"text":[{"text":"Trap: "},{"text":"The woman ate the food","italic":true},{"text":" has an object (transitive); "},{"text":"Your house is too far","italic":true},{"text":" has linking "},{"text":"is","italic":true},{"text":"; "},{"text":"The baby cried","italic":true},{"text":" follows the standard intransitive pattern."}]}]}]},{"number":"10.6","title":"Prepositions, conjunctions, interjections and phrases","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Preposition:","bold":true},{"text":" shows the "},{"text":"relationship","bold":true},{"text":" (time, place) between a noun or pronoun and another word: about, above, at, behind, by, for, from, into, of, to, under, with. "},{"text":"Compound (phrasal) prepositions:","bold":true},{"text":" because of, along with, next to, on account of, according to, owing to, instead of, in addition to, in spite of."}]},{"text":[{"text":"Prepositions "},{"text":"begin phrases that end with either a noun or a pronoun","bold":true},{"text":", the "},{"text":"object of the preposition (prepositional complement)","bold":true},{"text":": "},{"text":"behind the campus; under the table","italic":true},{"text":"."}]},{"text":[{"text":"Conjunction:","bold":true},{"text":" links words or groups of words. "},{"text":"4 groups:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coordinating:","bold":true},{"text":" join items of "},{"text":"equal grammatical status","bold":true},{"text":": "},{"text":"and, yet, but, or, nor, for, so","bold":true},{"text":" ("},{"text":"The man and his wife; firm yet fair","italic":true},{"text":"). They build "},{"text":"compound sentences","bold":true},{"text":"."}]},{"text":[{"text":"Correlative:","bold":true},{"text":" "},{"text":"pairs","bold":true},{"text":" joining items of equal status: "},{"text":"both...and; either...or; just as...so; neither...nor; not only...but (also); whether...or","bold":true},{"text":"."}]},{"text":[{"text":"Subordinating:","bold":true},{"text":" join two clauses, making one "},{"text":"dependent","bold":true},{"text":": because, when, if, as, although, though, since, before, after, as soon as, whenever, until, so that. They introduce "},{"text":"adverb clauses","bold":true},{"text":" and build "},{"text":"complex sentences","bold":true},{"text":"."}]},{"text":[{"text":"Conjunctive adverbs:","bold":true},{"text":" clarify the relationship between clauses of "},{"text":"equal status","bold":true},{"text":", more strongly than coordinators: also, however, moreover, nevertheless, besides, furthermore, still, consequently, therefore, thus, likewise, similarly ("},{"text":"He got to the bank after four; nevertheless, the cashier attended to him","italic":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interjection:","bold":true},{"text":" expresses "},{"text":"strong feeling, emotion or exclamation","bold":true},{"text":"; "},{"text":"no grammatical connection","bold":true},{"text":" to the other words; hardly used in formal writing: ouch, ha, oh, hey, eek, wow, oh no, watch it."}]},{"text":[{"text":"Phrase:","bold":true},{"text":" a group of words working in a sentence as a "},{"text":"single grammatical unit","bold":true},{"text":"; may be "},{"text":"just one word","bold":true},{"text":". Each type is "},{"text":"named after the word class of its key word (head)","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"8 types of phrase:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Noun phrase (NP):","bold":true},{"text":" head is a noun; does every job a noun does ("},{"text":"A heavy rain","italic":true},{"text":" fell: subject; Dami is "},{"text":"a very charming young man","italic":true},{"text":": subject complement)."}]},{"text":[{"text":"Verb phrase (VP):","bold":true},{"text":" main (lexical) verb + auxiliaries ("},{"text":"will go, is going, may have been going","italic":true},{"text":"); shows time, mood, voice, number, person; acts as "},{"text":"predicator","bold":true},{"text":"."}]},{"text":[{"text":"Prepositional phrase (PP):","bold":true},{"text":" preposition + its object ("},{"text":"in the fridge, under the bed, across the road","italic":true},{"text":")."}]},{"text":[{"text":"Adjective phrase (AdjP):","bold":true},{"text":" head is an adjective; modifies a noun ("},{"text":"very happy","italic":true},{"text":" man, "},{"text":"extremely valuable","italic":true},{"text":" documents, "},{"text":"happily married","italic":true},{"text":" couple)."}]},{"text":[{"text":"Adverb phrase (AdvP):","bold":true},{"text":" head is an adverb ("},{"text":"fairly regularly, very recently, extremely warmly","italic":true},{"text":")."}]},{"text":[{"text":"Appositive phrase:","bold":true},{"text":" a noun phrase next to another noun, identifying it ("},{"text":"The senator, Mr Malaki","italic":true},{"text":")."}]},{"text":[{"text":"Gerund phrase:","bold":true},{"text":" gerund + its modifiers or complement ("},{"text":"I love chatting with my friends","italic":true},{"text":")."}]},{"text":[{"text":"Participial phrase:","bold":true},{"text":" present or past participle + complement ("},{"text":"Sobbing uncontrollably, she tore up the pictures; Encouraged by her friends, she drove home","italic":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: "},{"text":"nevertheless","italic":true},{"text":" is a "},{"text":"conjunctive adverb","bold":true},{"text":", so it cannot introduce an adverb clause; "},{"text":"although, when, if","italic":true},{"text":" can."}]},{"text":[{"text":"Trap: "},{"text":"so","italic":true},{"text":" is coordinating but "},{"text":"so that","bold":true},{"text":" is "},{"text":"subordinating","bold":true},{"text":" (complex, not compound, sentence). "},{"text":"Even...then","italic":true},{"text":" is "},{"text":"not","bold":true},{"text":" a correlative pair."}]},{"text":[{"text":"A PP can act as an "},{"text":"adjective","bold":true},{"text":" ("},{"text":"The red book on the table is mine","italic":true},{"text":") or an "},{"text":"adverb","bold":true},{"text":" ("},{"text":"The bus arrived during the day","italic":true},{"text":"), which is why "},{"text":"to Ibadan","italic":true},{"text":" is an adverb of place."}]},{"text":[{"text":"Name a phrase by its "},{"text":"head","bold":true},{"text":": "},{"text":"across the road","italic":true},{"text":" is a "},{"text":"PP","bold":true},{"text":" (head "},{"text":"across","italic":true},{"text":") though "},{"text":"the road","italic":true},{"text":" inside it is an NP; in "},{"text":"because of the heavy rain","italic":true},{"text":", "},{"text":"the heavy rain","italic":true},{"text":" alone is a "},{"text":"noun phrase","bold":true},{"text":" (head "},{"text":"rain","italic":true},{"text":"); "},{"text":"extremely valuable","italic":true},{"text":" is an "},{"text":"adjective phrase","bold":true},{"text":" (head "},{"text":"valuable","italic":true},{"text":"), not an adverb phrase."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grammar = study of sentence structure; morphology (word formation) + syntax (arrangement)."}]},{"text":[{"text":"Hierarchy: morpheme < word < phrase < clause < sentence. Free morphemes = lexical + functional; bound = affixes."}]},{"text":[{"text":"Traditional: 8 parts of speech by meaning. Modern: 9 word classes (adds determiners) by notional, morphological and syntactic criteria."}]},{"text":[{"text":"Nouns: 4 forms; plural /s/ /z/ /ɪz/; proper/common, count/non-count, concrete/abstract; 8 functions; no tense."}]},{"text":[{"text":"Pronouns: 8 sub-classes, 3 cases; agree in number, gender, person, case. Determiners: articles, possessives, demonstratives, quantifiers, numerals."}]},{"text":[{"text":"Adjectives: 9 sub-classes; attributive vs predicative; positive, comparative (two), superlative (three+); gradable vs non-gradable."}]},{"text":[{"text":"Verbs: 5 forms (be has 8); transitive takes an object; auxiliaries = primary (have, be, do) + modal."}]},{"text":[{"text":"Simple present = regularity; present continuous = now; present perfect = past linked to present."}]},{"text":[{"text":"Adverbs: time, manner, place, degree, frequency; conjunctions: coordinating, correlative, subordinating, conjunctive adverbs."}]},{"text":[{"text":"Phrase = single unit named after its head; 8 types."}]}]}],"theory":{"itemId":"581e7879-0c09-57ec-994f-64e9d493d020","question":[{"type":"paragraph","text":[{"text":"Define a phrase and explain any four types of phrase in English with one example each."}]}]},"practice":[{"topic":"Grammar I: Word Classes and Phrases","named":false}]}},{"itemId":"a652032e-ce99-5b72-a681-36ab66baa78c","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:11","parentItemId":null,"revision":1,"payload":{"title":"Grammar II: Clauses and Sentences","body":"What a clause is; main versus subordinate clauses; the three clause types by form (finite, non-finite, verbless) and three by function (adjective/relative, adverb, noun); defining versus non-defining relative clauses and their commas; the sentence, major and minor sentences and fragments; simple, compound, multiple, complex and compound-complex sentences; the four sentence types by function; subject and predicate, S, V, O, C, A and the seven clause patterns; subject-verb agreement; the seven common sentence faults.","noteType":"guide_topic","number":11,"mustKnow":[{"text":"What a clause is; main versus subordinate clauses; the three clause types by form (finite, non-finite, verbless) and three by function (adjective/relative, adverb, noun); defining versus non-defining relative clauses and their commas; the sentence, major and minor sentences and fragments; simple, compound, multiple, complex and compound-complex sentences; the four sentence types by function; subject and predicate, S, V, O, C, A and the seven clause patterns; subject-verb agreement; the seven common sentence faults."}],"lessons":[{"number":"11.1","title":"The clause and its forms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hierarchy of grammatical units:","bold":true},{"text":" morpheme, word, phrase, clause, sentence. The clause is next in rank after the phrase; the "},{"text":"sentence is the highest unit of grammatical analysis","bold":true},{"text":"."}]},{"text":[{"text":"Clause:","bold":true},{"text":" a group of words that contains a "},{"text":"subject and a predicate","bold":true},{"text":"."}]},{"text":[{"text":"Main (independent) clause:","bold":true},{"text":" can stand by itself and make sense. It identifies what the sentence is about (the subject) and gives the essential information about it (the predicate)."}]},{"text":[{"text":"Subordinate (dependent) clause:","bold":true},{"text":" cannot stand by itself or make complete sense; it needs the main clause. It works inside the main clause like a "},{"text":"noun","bold":true},{"text":" or a "},{"text":"modifier","bold":true},{"text":"."}]},{"text":[{"text":"A simple sentence occurring by itself can also be called a clause.","bold":true},{"text":" When simple sentences combine into a larger sentence, each becomes a clause: "},{"text":"Olu kicked the ball and Ade caught it","italic":true},{"text":" has two clauses linked by "},{"text":"and","italic":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"3 types of subordinate clause by form","bold":true},{"text":" (structure):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Finite clause:","bold":true},{"text":" contains a "},{"text":"finite verb","bold":true},{"text":", a verb form that "},{"text":"changes","bold":true},{"text":" with "},{"text":"number, person and tense","bold":true},{"text":" ("},{"text":"visit, visits, visited, am visiting, is visiting","italic":true},{"text":")."}]},{"text":[{"text":"Non-finite clause:","bold":true},{"text":" contains a "},{"text":"non-finite verb","bold":true},{"text":", a form that "},{"text":"remains unchanging","bold":true},{"text":" whatever the number, person or tense. Often has "},{"text":"no subject","bold":true},{"text":": "},{"text":"It will be safer [for us to leave the scene]","italic":true},{"text":"; "},{"text":"The car [being repaired] is mine","italic":true},{"text":"; "},{"text":"[The applause having died down,] she began to sing","italic":true},{"text":"."}]},{"text":[{"text":"Verbless clause:","bold":true},{"text":" has "},{"text":"no verb","bold":true},{"text":", and usually no subject; both are understood from context: "},{"text":"He became a drug addict [while in prison]","italic":true},{"text":"; "},{"text":"[When in his famous sad mood,] he will not talk to anyone for days","italic":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Main + subordinate: "},{"text":"We had to abandon our home","italic":true},{"text":" | "},{"text":"as the flood waters rose higher","italic":true},{"text":"; "},{"text":"They found out","italic":true},{"text":" | "},{"text":"that he had lied to them","italic":true},{"text":"."}]},{"text":[{"text":"The subordinate clause may come "},{"text":"first","bold":true},{"text":" ("},{"text":"As the flood waters rose higher, we had to abandon our home","italic":true},{"text":") or be "},{"text":"embedded","bold":true},{"text":" in the main clause ("},{"text":"The boy [who came here today] is my cousin","italic":true},{"text":"; "},{"text":"My sister, [who lives in Warri,] is visiting us today","italic":true},{"text":")."}]},{"text":[{"text":"Finite verb changes: "},{"text":"They visit","italic":true},{"text":" (plural, present); "},{"text":"Mary visits","italic":true},{"text":" (singular); "},{"text":"Mary visited","italic":true},{"text":" (past); "},{"text":"I am visiting","italic":true},{"text":"."}]},{"text":[{"text":"Verbless clause rule:","bold":true},{"text":" only clauses whose main verb is "},{"text":"to be","bold":true},{"text":" ("},{"text":"is, am, are, was, were, be, been, being","italic":true},{"text":") can be verbless. The missing subject is usually the subject of the main clause: "},{"text":"while (he was) in prison","italic":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a finite clause contains "},{"text":"a verb that changes","bold":true},{"text":"; \"a verb that remains unchanging\" is non-finite and \"no verb at all\" is verbless. There is no "},{"text":"\"infinite clause\"","bold":true},{"text":"."}]}]}]},{"number":"11.2","title":"Clauses by function: adjective, adverb and noun clauses","mustKnow":[{"type":"paragraph","text":[{"text":"Subordinate clauses do the work of adjectives, adverbs and nouns, so there are "},{"text":"3 types by function","bold":true},{"text":":"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjective (or relative) clause:","bold":true},{"text":" modifies a "},{"text":"noun","bold":true},{"text":" (or pronoun) like an adjective. The other name for the adjective clause is "},{"text":"relative clause","bold":true},{"text":". Introduced by the "},{"text":"relative pronouns","bold":true},{"text":" "},{"text":"who, whom, whose, which, that","italic":true},{"text":" (occasionally "},{"text":"when, why, where","italic":true},{"text":"). The relative pronoun is the "},{"text":"subject","bold":true},{"text":" or "},{"text":"object","bold":true},{"text":" of its clause: "},{"text":"The man [who called you up this morning] is my uncle","italic":true},{"text":" ("},{"text":"who","italic":true},{"text":" = subject); "},{"text":"This is the man [whom the police questioned yesterday]","italic":true},{"text":" ("},{"text":"whom","italic":true},{"text":" = object)."}]},{"text":[{"text":"Adverb clause:","bold":true},{"text":" usually modifies the "},{"text":"verb","bold":true},{"text":" (time, place, manner, cause, condition, degree, comparison, concession), or an adjective, another adverb or the rest of the sentence. Introduced by "},{"text":"subordinating conjunctions","bold":true},{"text":": "},{"text":"when, if, since, before, as, because, although, while, wherever, after, unless, whether","italic":true},{"text":"."}]},{"text":[{"text":"Noun clause:","bold":true},{"text":" sits in noun positions and does noun jobs: "},{"text":"subject, direct object, indirect object, subject complement, object complement, prepositional complement, appositive","bold":true},{"text":". Usually introduced by "},{"text":"that","bold":true},{"text":"; also "},{"text":"what, where, who, whoever, whether, why, when, whatever","italic":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Relative clauses: 2 major functions","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"identify","bold":true},{"text":" the particular noun meant; they answer "},{"text":"\"which one?\"","bold":true},{"text":" This is the "},{"text":"defining (restrictive)","bold":true},{"text":" clause."}]},{"text":[{"text":"To give "},{"text":"additional information","bold":true},{"text":" about a noun already known. This is the "},{"text":"non-defining (non-restrictive)","bold":true},{"text":" clause."}]}]},{"type":"table","header":[[],[{"text":"Defining (restrictive)"}],[{"text":"Non-defining (non-restrictive)"}]],"rows":[[[{"text":"Job"}],[{"text":"Identifies: \"which one?\""}],[{"text":"Adds new, extra information"}]],[[{"text":"Essential to meaning?"}],[{"text":"Yes; fused into the sentence"}],[{"text":"No; can be left out"}]],[[{"text":"Commas"}],[{"text":"None","bold":true}],[{"text":"Paired commas","bold":true},{"text":", one before and one after"}]],[[{"text":"that","italic":true}],[{"text":"Accepted","bold":true}],[{"text":"Never","bold":true},{"text":" used"}]],[[{"text":"Pronoun omitted?"}],[{"text":"Yes, if not the subject ("},{"text":"the man we have been looking for","italic":true},{"text":")"}],[{"text":"No"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Defining:","bold":true},{"text":" "},{"text":"The man who lent you a book this morning is our Use of English instructor","italic":true},{"text":" (without the clause: \"which man?\"); "},{"text":"The banks which had failed to comply were sanctioned","italic":true},{"text":"."}]},{"text":[{"text":"Non-defining:","bold":true},{"text":" "},{"text":"My cousin Miriam, who was runner-up last year, won the first prize this year","italic":true},{"text":"; "},{"text":"Chike, who had never been to Lagos before, was excited about the trip.","italic":true},{"text":" Miriam and Chike are already known."}]},{"text":[{"text":"Commas change meaning:","bold":true},{"text":" "},{"text":"The students who arrived late for the lecture were locked out","italic":true},{"text":" = "},{"text":"some","bold":true},{"text":" students arrived late. "},{"text":"The students, who arrived late for the lecture, were locked out","italic":true},{"text":" = "},{"text":"all","bold":true},{"text":" students arrived late."}]},{"text":[{"text":"That","bold":true,"italic":true},{"text":":","bold":true},{"text":" "},{"text":"The students that arrived late were locked out","italic":true},{"text":" is correct (restrictive). "},{"text":"*Chike, that had never been to Lagos before, ...","italic":true},{"text":" is unacceptable. American English permits only "},{"text":"that","italic":true},{"text":" in defining clauses; use this as a guide to punctuating."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"restrictive clause\" is only a "},{"text":"sub-type","bold":true},{"text":" of relative clause, not another name for the adjective clause."}]},{"text":[{"text":"Adverb clauses:","bold":true},{"text":" "},{"text":"She hung onto his feet [as if her life depended on it]","italic":true},{"text":" is an "},{"text":"adverbial clause of manner","bold":true},{"text":" modifying "},{"text":"hung","italic":true},{"text":" (not adjectival; \"relative clause of manner\" and \"verbal clause\" are not clause types). "},{"text":"[Whenever he is upset,] he goes out and gets drunk","italic":true},{"text":" is an adverbial clause of "},{"text":"time","bold":true},{"text":". "},{"text":"If you study very hard","italic":true},{"text":" = condition; "},{"text":"Wherever they went","italic":true},{"text":" = place; "},{"text":"Although the two countries had signed a peace treaty","italic":true},{"text":" = concession; "},{"text":"because he was afraid","italic":true},{"text":" = cause."}]},{"text":[{"text":"Noun clauses:","bold":true},{"text":" "},{"text":"[That she was the best suited for the job] was pretty obvious","italic":true},{"text":" (subject); "},{"text":"We found out [that he was not telling the truth]","italic":true},{"text":" (direct object); "},{"text":"He told his pathetic story to [whoever he met on the way]","italic":true},{"text":" (indirect object); "},{"text":"The question now is [how we can solve this problem]","italic":true},{"text":" (subject complement); "},{"text":"Our reaction will depend on [what he does next]","italic":true},{"text":" (complement of the preposition "},{"text":"on","italic":true},{"text":"); "},{"text":"The fact [that she is not here now] speaks for itself","italic":true},{"text":" (appositive). A "},{"text":"nominal clause","bold":true},{"text":" = noun clause; "},{"text":"adjectival clause","bold":true},{"text":" = adjective clause."}]}]}]},{"number":"11.3","title":"The sentence and its types by form","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sentence, 2 definitions:","bold":true},{"text":" (1) a group of words that "},{"text":"begins with a capital letter and ends with a full stop","bold":true},{"text":"; (2) a group of words that "},{"text":"expresses a complete thought","bold":true},{"text":"."}]},{"text":[{"text":"Sentence fragment:","bold":true},{"text":" does "},{"text":"not","bold":true},{"text":" express a complete thought; essential parts are missing: "},{"text":"*Because I was hungry","italic":true},{"text":"; "},{"text":"*While Dad was driving across town.","italic":true},{"text":" "},{"text":"Unacceptable.","bold":true}]}]},{"type":"paragraph","text":[{"text":"By form, first distinguish:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Major sentences:","bold":true},{"text":" complete; contain the "},{"text":"subject and the predicate","bold":true},{"text":": "},{"text":"The carpenter completed the job this afternoon.","italic":true},{"text":" The vast majority of sentences are major."}]},{"text":[{"text":"Minor sentences:","bold":true},{"text":" "},{"text":"meaningful but grammatically incomplete","bold":true},{"text":"; they lack an essential component, but the omitted parts are "},{"text":"recoverable from context","bold":true},{"text":": "},{"text":"No fuel. Gatekeeper wanted. For sale. No vacancy. No smoking. Look out! Taxi, Surulere! Better luck next time!","italic":true},{"text":" "},{"text":"Acceptable.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Major sentences are further divided into 5 kinds:","bold":true}]},{"type":"table","header":[[{"text":"Kind"}],[{"text":"Clauses"}],[{"text":"Example"}]],"rows":[[[{"text":"Simple","bold":true}],[{"text":"one clause","bold":true},{"text":", "},{"text":"only one finite verb","bold":true},{"text":" (a single statement)"}],[{"text":"The boy killed the snake.","italic":true}]],[[{"text":"Compound","bold":true}],[{"text":"two","bold":true},{"text":" clauses, each independent and equal; two finite verbs"}],[{"text":"Ngozi was at the scene, but she didn't witness the accident.","italic":true}]],[[{"text":"Multiple","bold":true}],[{"text":"like compound, but "},{"text":"three or more","bold":true},{"text":" clauses"}],[{"text":"The fire was raging, the police kept the anxious crowd at bay, and the firefighters were dashing around.","italic":true}]],[[{"text":"Complex","bold":true}],[{"text":"one","bold":true},{"text":" independent (main) + "},{"text":"one or more","bold":true},{"text":" dependent (subordinate)"}],[{"text":"She met her husband while she was studying abroad.","italic":true}]],[[{"text":"Compound-complex","bold":true}],[{"text":"two or more","bold":true},{"text":" main + "},{"text":"at least one","bold":true},{"text":" subordinate"}],[{"text":"Olu kicked the ball as it rolled towards him and Ade caught it.","italic":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fragment vs minor sentence:","bold":true},{"text":" a fragment leaves the reader wondering; a minor sentence is clear: "},{"text":"(There is) no fuel. (A) gatekeeper (is) wanted. (You should) look out! (I wish you) better luck next time!","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"God bless you","italic":true},{"text":" is "},{"text":"not","bold":true},{"text":" a minor sentence: it has its own subject ("},{"text":"God","italic":true},{"text":") and verb ("},{"text":"bless","italic":true},{"text":"). "},{"text":"No smoking","italic":true},{"text":" is a minor sentence, not a simple one (no subject, no finite verb)."}]},{"text":[{"text":"Simple sentence trap:","bold":true},{"text":" one clause "},{"text":"and","bold":true},{"text":" one finite verb. Two clauses or two finite verbs means it is not simple. "},{"text":"The teacher asked a difficult question and no student could answer it","italic":true},{"text":" is compound."}]},{"text":[{"text":"Compound sentences","bold":true},{"text":" use "},{"text":"coordinating conjunctions","bold":true},{"text":" ("},{"text":"and, but, or, nor, for, yet","italic":true},{"text":") and "},{"text":"conjunctive adverbs","bold":true},{"text":" ("},{"text":"however, moreover, nevertheless, therefore, still, so","italic":true},{"text":")."}]},{"text":[{"text":"Complex:","bold":true},{"text":" the subordinate clause is joined by a "},{"text":"subordinating conjunction","bold":true},{"text":" ("},{"text":"They returned home after the war ended","italic":true},{"text":") or by "},{"text":"embedding","bold":true},{"text":" ("},{"text":"The escaping robber, who was shot in the head last night, died this morning","italic":true},{"text":"). "},{"text":"Trap:","bold":true},{"text":" one independent clause and "},{"text":"one or more","bold":true},{"text":" dependent clauses, not exactly one. Two independent clauses plus a subordinate one = compound-complex ("},{"text":"He washed the clothes when it stopped raining and ironed them later","italic":true},{"text":")."}]}]}]},{"number":"11.4","title":"Sentence types by function and the elements of a sentence","mustKnow":[{"type":"paragraph","text":[{"text":"4 sentence types by function:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Declarative:","bold":true},{"text":" makes a "},{"text":"statement","bold":true},{"text":"; ends with a "},{"text":"full stop (period)","bold":true},{"text":". "},{"text":"Tomorrow is my birthday.","italic":true}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" "},{"text":"asks a question","bold":true},{"text":". "},{"text":"What were you doing this morning?","italic":true}]},{"text":[{"text":"Imperative:","bold":true},{"text":" "},{"text":"gives directives","bold":true},{"text":". "},{"text":"Get out! Have a drink. Look out!","italic":true}]},{"text":[{"text":"Exclamatory:","bold":true},{"text":" expresses "},{"text":"strong emotion","bold":true},{"text":"; usually ends with an "},{"text":"exclamation mark","bold":true},{"text":". "},{"text":"Oh, my goodness! I'll be damned!","italic":true}]}]},{"type":"paragraph","text":[{"text":"12 kinds of imperative directive:","bold":true},{"text":" commanding ("},{"text":"Get out!","italic":true},{"text":"), inviting ("},{"text":"Have a drink.","italic":true},{"text":"), warning ("},{"text":"Look out!","italic":true},{"text":"), pleading ("},{"text":"Have mercy.","italic":true},{"text":"), permitting ("},{"text":"Suit yourself.","italic":true},{"text":"), suggesting ("},{"text":"Let's go by bus.","italic":true},{"text":"), advising ("},{"text":"Take the first flight.","italic":true},{"text":"), requesting ("},{"text":"Open the windows, please.","italic":true},{"text":"), meditating ("},{"text":"Let me see.","italic":true},{"text":"), expressing an imprecation ("},{"text":"Damn you!","italic":true},{"text":"), expressing good wishes ("},{"text":"Have a lovely day.","italic":true},{"text":"), instructing ("},{"text":"Stir for five minutes.","italic":true},{"text":")."}]},{"type":"paragraph","text":[{"text":"Elements of a sentence:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"2 major components:","bold":true},{"text":" the "},{"text":"subject","bold":true},{"text":" (names the person or thing about which something is said) and the "},{"text":"predicate","bold":true},{"text":" (what is said about the subject). "},{"text":"Birds","italic":true},{"text":" | "},{"text":"fly","italic":true},{"text":". "},{"text":"The happy children","italic":true},{"text":" | "},{"text":"poured out of the classroom","italic":true},{"text":"."}]},{"text":[{"text":"5 components:","bold":true},{"text":" "},{"text":"subject (S), verb (V), object (O), complement (C), adverbial or adjunct (A)","bold":true},{"text":"."}]},{"text":[{"text":"7 basic clause patterns","bold":true},{"text":" of the English simple sentence:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"SV:","bold":true},{"text":" "},{"text":"Jesus wept.","italic":true}]},{"text":[{"text":"SVO:","bold":true},{"text":" "},{"text":"The guards caught the thief.","italic":true}]},{"text":[{"text":"SVC:","bold":true},{"text":" "},{"text":"Kofi became the president.","italic":true}]},{"text":[{"text":"SVA:","bold":true},{"text":" "},{"text":"The plane took off at eight o'clock.","italic":true}]},{"text":[{"text":"SVOO:","bold":true},{"text":" "},{"text":"The man bought his wife a present.","italic":true}]},{"text":[{"text":"SVOC:","bold":true},{"text":" "},{"text":"The priest pronounced the couple man and wife.","italic":true}]},{"text":[{"text":"SVOA:","bold":true},{"text":" "},{"text":"The tribunal conducted the hearing behind closed doors.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" \"interlocutory\" is not a sentence type. "},{"text":"Oh, my goodness!","italic":true},{"text":" and "},{"text":"I don't believe that!","italic":true},{"text":" are exclamatory, "},{"text":"not","bold":true},{"text":" imperative. The plainest imperative is a bare verb with "},{"text":"you","italic":true},{"text":" understood: "},{"text":"Take the bus home.","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" the "},{"text":"major components of a sentence are the subject and the predicate","bold":true},{"text":", not main and subordinate clause, not independent and dependent clause, not nouns and adjectives."}]},{"text":[{"text":"Subject:","bold":true},{"text":" in "},{"text":"That boy is my cousin","italic":true},{"text":", "},{"text":"boy","italic":true},{"text":" is the "},{"text":"subject of the verb","bold":true},{"text":" "},{"text":"is","italic":true},{"text":"."}]},{"text":[{"text":"Direct object:","bold":true},{"text":" receives the action; answers \"what/whom?\" "},{"text":"Mr Dokunboh thanked the lady","italic":true},{"text":" ("},{"text":"the lady","italic":true},{"text":" = direct object); "},{"text":"The young lady thanked Mr Dokubo","italic":true},{"text":" ("},{"text":"Mr Dokubo","italic":true},{"text":" = direct object); "},{"text":"Mr Dokunboh donated some books","italic":true},{"text":" ("},{"text":"some books","italic":true},{"text":" = direct object)."}]},{"text":[{"text":"Indirect object:","bold":true},{"text":" the receiver, \"to or for whom?\", normally present only when the verb has two objects (SVOO). "},{"text":"We bought John a guitar","italic":true},{"text":": "},{"text":"John","italic":true},{"text":" = indirect object, "},{"text":"a guitar","italic":true},{"text":" = "},{"text":"direct object","bold":true},{"text":". "},{"text":"The man bought his wife a present","italic":true},{"text":": "},{"text":"his wife","italic":true},{"text":" = indirect, "},{"text":"a present","italic":true},{"text":" = direct."}]},{"text":[{"text":"Complement:","bold":true},{"text":" (i) a noun or noun phrase that is "},{"text":"the same as","bold":true},{"text":" the subject or object ("},{"text":"Nosa is my cousin","italic":true},{"text":"; "},{"text":"Kofi became the president","italic":true},{"text":", so SVC; "},{"text":"man and wife","italic":true},{"text":" = "},{"text":"the couple","italic":true},{"text":", so SVOC); or (ii) an "},{"text":"adjective describing","bold":true},{"text":" the subject or object ("},{"text":"The panel considered his remarks misleading","italic":true},{"text":")."}]},{"text":[{"text":"Adverbial (adjunct):","bold":true},{"text":" like an adverb, tells "},{"text":"time, place, manner","bold":true},{"text":": "},{"text":"at eight o'clock","italic":true},{"text":" (SVA), "},{"text":"behind closed doors","italic":true},{"text":" (SVOA)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"seven","bold":true},{"text":" patterns, not 4, 6 or 8; "},{"text":"SVCC is not one","bold":true},{"text":". "},{"text":"Jesus wept","italic":true},{"text":" = SV."}]}]}]},{"number":"11.5","title":"Subject-verb agreement (concord)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Concord","bold":true},{"text":" = grammatical agreement. "},{"text":"4 types:","bold":true},{"text":" subject-verb, pronoun-antecedent, determiner-noun head, tense concord. Focus: "},{"text":"subject-verb agreement in number","bold":true},{"text":" (singular/plural)."}]},{"text":[{"text":"Rule:","bold":true},{"text":" "},{"text":"singular subject, singular verb; plural subject, plural verb.","bold":true},{"text":" "},{"text":"The girl lives in Surulere. The girls live in Surulere.","italic":true}]},{"text":[{"text":"The -s inconsistency:","bold":true},{"text":" plural "},{"text":"nouns","bold":true},{"text":" take -s; "},{"text":"singular verbs","bold":true},{"text":" take -s. "},{"text":"The car drives. The cars drive.","italic":true}]}]},{"type":"paragraph","text":[{"text":"7 rules for doubtful subjects:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Joined by ","bold":true},{"text":"and","bold":true,"italic":true},{"text":":","bold":true},{"text":" "},{"text":"plural","bold":true},{"text":" ("},{"text":"The man and his wife were present. The manager and all his staff are here.","italic":true},{"text":"), "},{"text":"unless","bold":true},{"text":" the members form a "},{"text":"single unit","bold":true},{"text":" ("},{"text":"Hot lemonade and honey is good for a cold. Waiter, is the rice and beans ready? The MD and Chief Executive Officer of the company was introduced.","italic":true},{"text":")."}]},{"text":[{"text":"Singular members joined by ","bold":true},{"text":"(either...) or","bold":true,"italic":true},{"text":" / ","bold":true},{"text":"(neither...) nor","bold":true,"italic":true},{"text":":","bold":true},{"text":" singular ("},{"text":"Either the security man or the suspect is lying","italic":true},{"text":"). Plural members: plural ("},{"text":"Neither the apprentices nor their supervisors were available","italic":true},{"text":")."}]},{"text":[{"text":"Concord of proximity","bold":true},{"text":" (nearness): mixed "},{"text":"or","italic":true},{"text":"-compounds agree with the "},{"text":"nearest","bold":true},{"text":" member: "},{"text":"Either Janet or her parents visit...","italic":true},{"text":"; "},{"text":"Either you or Ibrahim is...","italic":true},{"text":"; "},{"text":"Either you or I am...","italic":true}]},{"text":[{"text":"Plural in form, singular in meaning:","bold":true},{"text":" always singular: "},{"text":"There is no news yet. Two hundred pounds is all he managed to save. Statistics is not as difficult as many think.","italic":true}]},{"text":[{"text":"Linking expressions","bold":true},{"text":" ("},{"text":"with, together with, accompanied by, as well as, along with, in collaboration with, in conjunction with, flanked by, escorted by, in addition to","italic":true},{"text":"): the verb "},{"text":"stays singular","bold":true},{"text":" with a singular subject: "},{"text":"The Manager, together with all his staff, was outside. The governor, accompanied by his aides, is walking down the street.","italic":true}]},{"text":[{"text":"The number of","bold":true,"italic":true},{"text":" (a specific figure) = "},{"text":"singular","bold":true},{"text":"; "},{"text":"a number of","bold":true,"italic":true},{"text":" (\"several\") = "},{"text":"plural","bold":true},{"text":": "},{"text":"The number of reported cases has dropped. A number of women and children have been treated.","italic":true}]},{"text":[{"text":"Collective nouns","bold":true},{"text":" ("},{"text":"class, committee, crew, team, congregation, audience, herd, jury","italic":true},{"text":"): singular if viewed as a "},{"text":"unit","bold":true},{"text":", plural if viewed as "},{"text":"individuals","bold":true},{"text":". This is "},{"text":"notional concord","bold":true},{"text":": "},{"text":"The jury has reached a verdict. The jury are still arguing over that point.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" only "},{"text":"The man and his wife were present","italic":true},{"text":" has a "},{"text":"plural compound subject","bold":true},{"text":"; lemonade and honey (one drink), rice and beans (one dish) and the MD and CEO (one person) are singular units."}]},{"text":[{"text":"And","bold":true,"italic":true},{"text":" vs a linking expression:","bold":true},{"text":" "},{"text":"The captain and several crew members were injured","italic":true},{"text":" gives both equal attention; "},{"text":"The captain, along with several crew members, was injured","italic":true},{"text":" focuses on the captain. "},{"text":"Organisation A in collaboration with Organisation B","italic":true},{"text":" = B played a subsidiary role."}]},{"text":[{"text":"Any "},{"text":"pronoun","bold":true},{"text":" referring to a collective noun must agree with it too. Faulty: "},{"text":"*The committee has concluded its deliberations and their report is expected","italic":true},{"text":" ("},{"text":"its","italic":true},{"text":" then "},{"text":"their","italic":true},{"text":"); "},{"text":"*The cabinet is divided, but it is hoped that they will soon agree","italic":true},{"text":" ("},{"text":"is","italic":true},{"text":" then "},{"text":"they","italic":true},{"text":")."}]}]}]},{"number":"11.6","title":"Common errors in sentence construction","mustKnow":[{"type":"paragraph","text":[{"text":"7 sentence faults:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Empty sentences:","bold":true},{"text":" grammatically correct but "},{"text":"say nothing","bold":true},{"text":": "},{"text":"*I want to acquire university education because acquiring university education will satisfy my long-felt desires.","italic":true},{"text":" Cancel or revise."}]},{"text":[{"text":"Padded sentences:","bold":true},{"text":" full of "},{"text":"unnecessary words","bold":true},{"text":". Two kinds: "},{"text":"unnecessary repetition","bold":true},{"text":" and "},{"text":"wordiness","bold":true},{"text":". Sentences should be "},{"text":"accurate, brief and clear","bold":true},{"text":"."}]},{"text":[{"text":"Overloaded sentences:","bold":true},{"text":" "},{"text":"too many facts and ideas","bold":true},{"text":" crowded in. Split them. Rules: (i) "},{"text":"say one thing at a time","bold":true},{"text":"; (ii) "},{"text":"say it simply and directly","bold":true},{"text":"."}]},{"text":[{"text":"Dangling modifiers:","bold":true},{"text":" modifiers whose word is "},{"text":"missing","bold":true},{"text":", so they have "},{"text":"nothing to modify","bold":true},{"text":": "},{"text":"*Returning home late one night, the gate was locked.","italic":true}]},{"text":[{"text":"Run-on sentences:","bold":true},{"text":" two or more sentences "},{"text":"collapsed into one with no punctuation","bold":true},{"text":" between them: "},{"text":"*Anne looked everywhere for her missing phone unfortunately she did not find it.","italic":true}]},{"text":[{"text":"The comma splice:","bold":true},{"text":" related to the run-on; a "},{"text":"comma weakly separates","bold":true},{"text":" sentences run together: "},{"text":"*Anne looked everywhere for her phone, unfortunately she did not find it, she reported the loss to the hostel warden.","italic":true}]},{"text":[{"text":"The sentence fragment:","bold":true},{"text":" a "},{"text":"phrase or subordinate clause","bold":true},{"text":" punctuated as a sentence: "},{"text":"A nominal clause functions like a noun. *While an adjectival clause modifies a noun.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Padding:","bold":true},{"text":" "},{"text":"*The modern businessman of today must completely master all of the principles of computerization","italic":true},{"text":": \"of today\" repeats \"modern\"; \"completely\" and \"all of\" repeat \"master\". "},{"text":"*...as a result of the fact that our computers broke down","italic":true},{"text":": seven words replaced by "},{"text":"because","bold":true},{"text":"."}]},{"text":[{"text":"Overloading:","bold":true},{"text":" one long sentence about a large university was split into three; one about Chike's parents into four."}]},{"text":[{"text":"Dangling modifiers:","bold":true},{"text":" correct use: "},{"text":"While climbing a palm tree, Amodu lost his grip","italic":true},{"text":" (the modifier attaches to "},{"text":"Amodu","italic":true},{"text":"). Faulty: "},{"text":"*Driving around Greensville a year later, it's clear the town will never be the same","italic":true},{"text":"; "},{"text":"*Having said that, there are other points to consider","italic":true},{"text":"; "},{"text":"*Returning home late one night, a snake bit Olu","italic":true},{"text":" (the modified word must be "},{"text":"right next to","bold":true},{"text":" the modifier, since modifiers attach to the "},{"text":"closest","bold":true},{"text":" noun or pronoun). "},{"text":"Two corrections:","bold":true},{"text":" put the doer next to the modifier ("},{"text":"Returning home late one night, Olu was bitten by a snake","italic":true},{"text":") or make the modifier a full clause ("},{"text":"As Olu returned home late one night, he was bitten by a snake","italic":true},{"text":")."}]},{"text":[{"text":"Run-ons:","bold":true},{"text":" break into sentences or link with suitable conjunctions."}]},{"text":[{"text":"While","bold":true,"italic":true},{"text":" and other "},{"text":"subordinating conjunctions","bold":true},{"text":" ("},{"text":"when, although, as, because, since, whenever, wherever","italic":true},{"text":") make a clause subordinate, so it cannot stand alone. Correct: "},{"text":"A nominal clause functions as a noun, while an adjectival clause modifies a noun.","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" run-on = "},{"text":"no","bold":true},{"text":" punctuation; comma splice = a "},{"text":"comma","bold":true},{"text":" where a full stop or conjunction is needed. Minor sentence = acceptable; fragment = not."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clause = subject + predicate; main stands alone, subordinate does not. A simple sentence alone is also a clause."}]},{"text":[{"text":"Form: finite (verb changes), non-finite (unchanging), verbless (no verb; "},{"text":"to be","italic":true},{"text":" only)."}]},{"text":[{"text":"Function: adjective/relative (noun; "},{"text":"who, whom, whose, which, that","italic":true},{"text":"), adverb (verb; subordinating conjunctions), noun (S, DO, IO, complement, appositive; "},{"text":"that","italic":true},{"text":")."}]},{"text":[{"text":"Defining: \"which one?\", no commas, accepts "},{"text":"that","italic":true},{"text":". Non-defining: extra information, paired commas, never "},{"text":"that","italic":true},{"text":"."}]},{"text":[{"text":"Major (subject + predicate) vs minor (incomplete but recoverable); fragments unacceptable."}]},{"text":[{"text":"Simple (1 clause, 1 finite verb), compound (2), multiple (3+), complex (1 main + 1 or more subordinate), compound-complex (2+ main + 1 or more subordinate)."}]},{"text":[{"text":"Declarative (statement), interrogative (question), imperative (directive), exclamatory (emotion)."}]},{"text":[{"text":"Subject + predicate; S, V, O, C, A; 7 patterns: SV, SVO, SVC, SVA, SVOO, SVOC, SVOA."}]},{"text":[{"text":"Concord: "},{"text":"and","italic":true},{"text":" plural unless one unit; "},{"text":"or/nor","italic":true},{"text":" nearest member; "},{"text":"together with","italic":true},{"text":" keeps singular; "},{"text":"the number of","italic":true},{"text":" singular, "},{"text":"a number of","italic":true},{"text":" plural; collective nouns notional."}]},{"text":[{"text":"7 faults: empty, padded, overloaded, dangling modifier, run-on, comma splice, fragment."}]}]}],"theory":{"itemId":"f080dbdc-2921-5808-9f7e-555c36543412","question":[{"type":"paragraph","text":[{"text":"Distinguish between defining and non-defining relative clauses, with one example of each, and show how punctuation affects meaning."}]}]},"practice":[{"topic":"Grammar II: Clauses and Sentences","named":false}]}},{"itemId":"d709d882-4a78-5857-8521-e2dc52415c0e","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:12","parentItemId":null,"revision":1,"payload":{"title":"The Library, Information Resources and Use","body":"The library, its types and five functions; data, information and information literacy; the five characteristics of good information; the six forms and two sources (primary, secondary) of information; the University of Lagos Library's three resource categories, five print collections, eleven types of reference collection, and where each is housed.","noteType":"guide_topic","number":12,"mustKnow":[{"text":"The library, its types and five functions; data, information and information literacy; the five characteristics of good information; the six forms and two sources (primary, secondary) of information; the University of Lagos Library's three resource categories, five print collections, eleven types of reference collection, and where each is housed."}],"lessons":[{"number":"12.1","title":"The library, its functions, data and information","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Library:","bold":true},{"text":" any "},{"text":"organised collection","bold":true},{"text":" for use by an individual or group of people; a collection of books gathered for purposes of "},{"text":"reading, study or reference","bold":true},{"text":". Today it means a body of "},{"text":"recorded information","bold":true},{"text":" brought together for specific purposes, "},{"text":"organised for use","bold":true},{"text":" and "},{"text":"made available to users","bold":true},{"text":"."}]},{"text":[{"text":"Types of library (the 5 named):","bold":true},{"text":" public, academic, special, school, private, and so on. A "},{"text":"court library","bold":true},{"text":" is not one of the named types."}]},{"text":[{"text":"5 basic functions","bold":true},{"text":" of every library, whatever its type, for resources in "},{"text":"print and electronic","bold":true},{"text":" format:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selection","bold":true}]},{"text":[{"text":"Acquisition","bold":true},{"text":" (acquiring print and non-print materials for users)"}]},{"text":[{"text":"Organisation","bold":true},{"text":" (organising resources for effective use)"}]},{"text":[{"text":"Preservation","bold":true},{"text":" (preserving the resources acquired)"}]},{"text":[{"text":"Dissemination","bold":true},{"text":" (making information available to users)"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Book selling","bold":true},{"text":" is not a library function."}]},{"text":[{"text":"Data:","bold":true},{"text":" plural of "},{"text":"datum","italic":true},{"text":"; "},{"text":"facts","bold":true},{"text":" used in describing or discussing an item or set of items; also facts, figures or instructions in a form that can be comprehended and communicated by a human being or processed by a computer. Another word for data is "},{"text":"fact","bold":true},{"text":"."}]},{"text":[{"text":"Information:","bold":true},{"text":" facts, news, opinions, messages, symbols, signals and "},{"text":"processed data","bold":true},{"text":" capable of "},{"text":"improving the knowledge state","bold":true},{"text":" of a user. It is the "},{"text":"building block","bold":true},{"text":" in the creation of "},{"text":"knowledge and wisdom","bold":true},{"text":"."}]},{"text":[{"text":"Information literacy:","bold":true},{"text":" the ability to "},{"text":"locate, retrieve, evaluate and apply","bold":true},{"text":" information as you convert it into knowledge; it also includes the ability to "},{"text":"recognise when information is needed","bold":true},{"text":". It stresses the skill of finding needed information and understanding how the library and its resources are organised."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Data and information are "},{"text":"not","bold":true},{"text":" the same. Data is raw facts; information is processed data that improves what you know. \"Another word for data\" is "},{"text":"fact","bold":true},{"text":", not information."}]},{"text":[{"text":"Information literacy distractors: \"information knowledge\", \"information discovery\" (only finding, not evaluating and applying), \"information explosion\" (the rapid growth in the amount of information), \"information support\", \"information asset\". None is the term."}]},{"text":[{"text":"Library sections and terms","bold":true},{"text":" you must recognise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Circulation section (circulation desk):","bold":true},{"text":" deals with the "},{"text":"borrowing and returning","bold":true},{"text":" of books; also where you ask for help locating a book (with the library catalogue and any library staff). Distributing books among affiliated libraries is inter-library lending, a separate service."}]},{"text":[{"text":"Acquisitions section:","bold":true},{"text":" acquires new materials. "},{"text":"Cataloguing section:","bold":true},{"text":" catalogues and classifies acquired materials. Both are back-office units."}]},{"text":[{"text":"Reference librarian:","bold":true},{"text":" the person who provides "},{"text":"reference services","bold":true},{"text":". Not the Chief Librarian or University Librarian (head of the library) and not a general \"library officer\"."}]},{"text":[{"text":"Weeding:","bold":true},{"text":" "},{"text":"removing outdated","bold":true},{"text":" (damaged or no-longer-useful) books from the collection. Not dusting shelves, clearing tables or screening users."}]},{"text":[{"text":"Catalogue:","bold":true},{"text":" gives the "},{"text":"bibliographic details","bold":true},{"text":" (author, title and "},{"text":"call number","bold":true},{"text":", also called the "},{"text":"call mark","bold":true},{"text":") needed to retrieve a book. Two forms: the "},{"text":"card catalogue","bold":true},{"text":" (author/title and subject) and the "},{"text":"Online Public Access Catalogue (OPAC)","bold":true},{"text":"."}]}]}]}]}]},{"number":"12.2","title":"Characteristics of good information","mustKnow":[{"type":"paragraph","text":[{"text":"Information is good if it has these "},{"text":"5 characteristics","bold":true},{"text":" (attributes, qualities):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Availability/Accessibility:","bold":true},{"text":" information is of no use if it is not within reach of its intended users; it should be "},{"text":"easy to obtain and access","bold":true},{"text":". Accessibility is the "},{"text":"ease with which information can be obtained","bold":true},{"text":"."}]},{"text":[{"text":"Accuracy:","bold":true},{"text":" information must be accurate for the purpose for which it is used."}]},{"text":[{"text":"Reliability:","bold":true},{"text":" the "},{"text":"truthfulness","bold":true},{"text":" with which information is presented; ensured by its "},{"text":"authoritativeness and dependability","bold":true},{"text":"."}]},{"text":[{"text":"Timeliness:","bold":true},{"text":" information must be provided "},{"text":"on time","bold":true},{"text":" for the purpose it is required; late information becomes "},{"text":"irrelevant","bold":true},{"text":". Timeliness is a "},{"text":"sub-set of accessibility","bold":true},{"text":"."}]},{"text":[{"text":"Relevance:","bold":true},{"text":" information must be relevant to the purpose and "},{"text":"suitable for the user","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" characteristics: "},{"text":"news","bold":true},{"text":" (a form information takes), "},{"text":"citation","bold":true},{"text":", "},{"text":"printing","bold":true},{"text":" (things done with information), "},{"text":"non-reliability","bold":true},{"text":" (the opposite of a required quality)."}]},{"text":[{"text":"Example of accessibility: the University of Lagos Library is the "},{"text":"major organ of information provision","bold":true},{"text":" in the university community and beyond; it gives access to many types and formats of information through the traditional "},{"text":"catalogue","bold":true},{"text":" and the "},{"text":"OPAC","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"Where information is not provided on time it becomes ...\" The answer is "},{"text":"irrelevant","bold":true},{"text":", never \"useful\" or \"relevant\"."}]}]}]},{"number":"12.3","title":"Types and sources of information","mustKnow":[{"type":"paragraph","text":[{"text":"6 types (forms) of information:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Oral:","bold":true},{"text":" spoken words."}]},{"text":[{"text":"Textual:","bold":true},{"text":" text and words."}]},{"text":[{"text":"Numeric:","bold":true},{"text":" numbers."}]},{"text":[{"text":"Bibliographic:","bold":true},{"text":" the use of multi-diversified means of dissemination."}]},{"text":[{"text":"Graphical:","bold":true},{"text":" graphs and charts."}]},{"text":[{"text":"Multimedia:","bold":true},{"text":" a "},{"text":"diversified medium","bold":true},{"text":" of communication such as "},{"text":"audio, visual, audio-visual","bold":true},{"text":" and so on."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Information can therefore be in the form of numbers, texts, graphs and charts ("},{"text":"all","bold":true},{"text":" of them)."}]}]},{"type":"paragraph","text":[{"text":"2 sources of information: primary and secondary.","bold":true}]},{"type":"table","header":[[],[{"text":"Primary source"}],[{"text":"Secondary source"}]],"rows":[[[{"text":"What it is"}],[{"text":"Stands on its own; gives a "},{"text":"first-hand","bold":true},{"text":" account of an event; provides the information the user needs "},{"text":"directly","bold":true}],[{"text":"Analyses, critiques, reviews or explains","bold":true},{"text":" a primary source"}]],[[{"text":"Who writes it"}],[{"text":"The original observer or creator"}],[{"text":"Scholars who studied the primary source and drew their own conclusions; often people "},{"text":"not present","bold":true},{"text":" when the event occurred"}]],[[{"text":"Literature"}],[{"text":"Novel, short story, poem"}],[{"text":"Criticism, reviews"}]],[[{"text":"History"}],[{"text":"Laws, letters, oral histories, diaries, newspaper articles on events"}],[{"text":"Books explaining the events"}]],[[{"text":"Science"}],[{"text":"Reports of original research","bold":true},{"text":" (journal articles, theses)"}],[{"text":"Textbooks, encyclopaedias, digests"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Neither type is by nature more or less reliable","bold":true},{"text":" than the other. Depending on your topic, primary documents may be essential; some disciplines require the information to be "},{"text":"current","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"The two sources of information\" are "},{"text":"primary and secondary","bold":true},{"text":". \"Print and electronic\" is a division by "},{"text":"format","bold":true},{"text":", not by kind of source; \"books and online\" and \"library and internet\" are informal. "},{"text":"Tertiary","bold":true},{"text":" is not one of the two categories."}]},{"text":[{"text":"Fill-in: \"A secondary source is one that "},{"text":"analyses and explains","bold":true},{"text":" a primary source.\" \"Disqualify\" and \"manipulates\" are not part of the definition."}]},{"text":[{"text":"A "},{"text":"thesis","bold":true},{"text":" is a "},{"text":"primary","bold":true},{"text":" source (original research). "},{"text":"Textbooks, encyclopaedias and digests","bold":true},{"text":" compile or explain other people's work, so they are "},{"text":"secondary","bold":true},{"text":"."}]},{"text":[{"text":"Journals","bold":true},{"text":" convey "},{"text":"recent original research and observation","bold":true},{"text":"; textbooks summarise established knowledge."}]},{"text":[{"text":"\"Multimedia ... diversified medium of communication such as ...\" The answer is "},{"text":"audio-visual","bold":true},{"text":", not text, graphs or numbers, which are single types."}]}]}]},{"number":"12.4","title":"Resources of the University of Lagos Library: print collections","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 categories of resources","bold":true},{"text":" in the University of Lagos Library: "},{"text":"Print, Non-print, Audio-visual","bold":true},{"text":" (all three)."}]},{"text":[{"text":"A. Print resources (books):","bold":true},{"text":" general and special collections, made up of "},{"text":"5 collections","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Africana collection","bold":true}]},{"text":[{"text":"Reference collection","bold":true}]},{"text":[{"text":"Reserved collection","bold":true}]},{"text":[{"text":"Serials collection","bold":true}]},{"text":[{"text":"Recent accessions","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"There is "},{"text":"no \"American collection\"","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Africana collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Print materials "},{"text":"published on Africa","bold":true},{"text":" by "},{"text":"African and non-African authors","bold":true},{"text":"; primarily "},{"text":"research","bold":true},{"text":" collections."}]},{"text":[{"text":"Housed at the "},{"text":"Research and Bibliographic Department","bold":true},{"text":", otherwise known as the "},{"text":"Gandhi Library","bold":true},{"text":", at the "},{"text":"basement","bold":true},{"text":" of the main library."}]},{"text":[{"text":"To use it, consult the "},{"text":"OPAC","bold":true},{"text":" or the "},{"text":"Card Catalogue","bold":true},{"text":" (author/title and subject) on the "},{"text":"ground floor","bold":true},{"text":" for the "},{"text":"author, title and call number (call mark)","bold":true},{"text":"."}]},{"text":[{"text":"Run on a "},{"text":"closed access system","bold":true},{"text":": users may "},{"text":"not","bold":true},{"text":" retrieve materials from the shelves; the "},{"text":"desk officer","bold":true},{"text":" retrieves them from the details supplied. Closed access means "},{"text":"restricted access","bold":true},{"text":"."}]},{"text":[{"text":"Access is "},{"text":"strictly for researchers and postgraduate students","bold":true},{"text":". Undergraduates enter only with a "},{"text":"letter from the head of department, supervisor or course lecturer","bold":true},{"text":"."}]},{"text":[{"text":"Africana materials are "},{"text":"not loanable","bold":true},{"text":" and may not be taken out of the department. They are consulted within the department; "},{"text":"photocopying is allowed","bold":true},{"text":". (True.)"}]},{"text":[{"text":"Other holdings: "},{"text":"special collections of notable individuals","bold":true},{"text":"; "},{"text":"newspapers, old and current, dating back to 1930","bold":true},{"text":" (the "},{"text":"West African Pilot","italic":true},{"text":", founded and owned by Nnamdi Azikiwe); magazines; "},{"text":"PhD theses","bold":true},{"text":" from the university; government papers; NGO papers; "},{"text":"cartographic materials","bold":true},{"text":" (maps); the "},{"text":"University of Lagos archives","bold":true},{"text":". A separate catalogue in the Gandhi Library lists these."}]}]},{"type":"paragraph","text":[{"text":"Reference collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Materials consulted to provide "},{"text":"specific information","bold":true},{"text":" whenever the need arises; also called "},{"text":"reference sources","bold":true},{"text":"; in "},{"text":"print and electronic","bold":true},{"text":" formats."}]},{"text":[{"text":"Contain "},{"text":"facts and rarely opinions","bold":true},{"text":" (True). "},{"text":"Not read from cover to cover","bold":true},{"text":" like books. Entries (tables, diagrams, statistics, maps) are arranged in "},{"text":"alphabetical order","bold":true},{"text":"."}]},{"text":[{"text":"Reference books "},{"text":"cannot be borrowed","bold":true},{"text":"; they are consulted in the "},{"text":"reference section","bold":true},{"text":", on the "},{"text":"left-hand side of the ground floor","bold":true},{"text":"."}]},{"text":[{"text":"Notable reference collections:","bold":true},{"text":" dictionaries, encyclopaedias, biographies, indexes, abstracts, fact sources, geographical sources, bibliographical sources, books of quotation, handbooks and manuals. "},{"text":"Books","bold":true},{"text":" in general and "},{"text":"journals","bold":true},{"text":" (serials) are "},{"text":"not","bold":true},{"text":" reference materials."}]}]},{"type":"paragraph","text":[{"text":"Reserved collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Valuable","bold":true},{"text":", often "},{"text":"rare","bold":true},{"text":" materials cutting across all disciplines."}]},{"text":[{"text":"Run on a "},{"text":"closed access system","bold":true},{"text":": you place a request with the "},{"text":"bibliographic details","bold":true},{"text":"; the material is retrieved for you."}]},{"text":[{"text":"Housed at the "},{"text":"Reserved Section","bold":true},{"text":", at the "},{"text":"immediate right on the ground floor","bold":true},{"text":"."}]},{"text":[{"text":"Must be "},{"text":"consulted within the reading room","bold":true},{"text":"; "},{"text":"not placed on long loan","bold":true},{"text":"; so reserved books "},{"text":"cannot be borrowed","bold":true},{"text":", but you can use them and "},{"text":"photocopy","bold":true},{"text":"."}]},{"text":[{"text":"Books are placed on reserve to "},{"text":"facilitate a rapid and wider circulation of scarce materials among users","bold":true},{"text":", not to protect them from wear, keep them from unregistered users or save them for serious students only. They are for students, not staff only."}]}]},{"type":"paragraph","text":[{"text":"Serials collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"serial","bold":true},{"text":" is any publication issued in "},{"text":"successive parts","bold":true},{"text":", appearing at "},{"text":"regular intervals","bold":true},{"text":", and as a rule "},{"text":"intended to be continued indefinitely","bold":true},{"text":"."}]},{"text":[{"text":"Examples: newspapers, magazines, newsletters, "},{"text":"journals","bold":true},{"text":", indexes, abstracts, reports, proceedings and transactions of societies."}]},{"text":[{"text":"Very important because of the "},{"text":"currency","bold":true},{"text":" of their content. Holdings are recorded in a "},{"text":"kardex","bold":true},{"text":" (a card information system holding bibliographic details), updated as new volumes arrive. Serials also have an "},{"text":"index to magazines","bold":true},{"text":" used for term papers."}]},{"text":[{"text":"Article/journal searches","bold":true},{"text":" are done in the "},{"text":"Serials section","bold":true},{"text":" and the "},{"text":"E-library","bold":true},{"text":", not in the Cataloguing or Acquisition sections."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Special collections in the Gandhi Library belong to: "},{"text":"Mahatma Gandhi","bold":true},{"text":" (Indian nationalist and elder statesman), "},{"text":"D.O. Fagunwa","bold":true},{"text":" (the \"Shakespeare of Africa\"), "},{"text":"Pa S.O. Solanke","bold":true},{"text":" (WASU Secretary), "},{"text":"Revd Awojobi","bold":true},{"text":", "},{"text":"Professor Babalola","bold":true},{"text":", "},{"text":"Yesufu Eke","bold":true},{"text":" (one-time bursar), "},{"text":"Bishop Kale","bold":true},{"text":" and "},{"text":"Professor Adetokunbo Sofoluwe","bold":true},{"text":" (former Vice-Chancellor)."}]},{"text":[{"text":"\"The Research and Bibliographic section houses ...\" The defining answer is "},{"text":"PhD theses","bold":true},{"text":"; old and current newspapers are also kept there. Law books belong to the general collection."}]},{"text":[{"text":"Location map: "},{"text":"basement","bold":true},{"text":" = Gandhi Library (Africana); "},{"text":"ground floor","bold":true},{"text":" = card catalogue, reference section (left), reserved section (immediate right); "},{"text":"third floor","bold":true},{"text":" = Automation Section and E-Library classrooms."}]},{"text":[{"text":"Open access (the opposite of closed access) lets users retrieve materials from the shelves themselves. The reserved and Africana systems are called "},{"text":"closed","bold":true},{"text":" access (not \"restricted access system\" or \"reserve access system\"), and what closed access "},{"text":"refers to","bold":true},{"text":" is "},{"text":"restricted access","bold":true},{"text":"."}]},{"text":[{"text":"Newspapers go back to "},{"text":"1930","bold":true},{"text":", not 1860, 1920 or 1960."}]}]}]},{"number":"12.5","title":"The eleven types of reference collection","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Dictionaries:","bold":true},{"text":" give information about "},{"text":"words","bold":true},{"text":": spelling, meaning, pronunciation, usage, synonyms, etymology and grammatical function. "},{"text":"3 types:","bold":true},{"text":" "},{"text":"general","bold":true},{"text":" (Oxford English Dictionary, Chambers English Dictionary), "},{"text":"specialised","bold":true},{"text":" and "},{"text":"subject","bold":true},{"text":" dictionaries (Roget's International Thesaurus, Dictionary of American Slang, Dictionary of the Yoruba Language, Dictionary of Modern Politics). Arranged "},{"text":"alphabetically","bold":true},{"text":"; housed at the "},{"text":"reference section","bold":true},{"text":". Dictionaries are used as quick "},{"text":"reference","bold":true},{"text":" sources. There is no \"anthem dictionary\"."}]},{"text":[{"text":"Encyclopaedias:","bold":true},{"text":" give "},{"text":"background and current information on any topic","bold":true},{"text":"; a book or set of books on "},{"text":"one or all branches of knowledge","bold":true},{"text":". "},{"text":"General","bold":true},{"text":" (Encyclopaedia Britannica, Encyclopaedia Americana) or "},{"text":"subject-based","bold":true},{"text":" (Encyclopedia of Library and Information Science, of Linguistics and Languages, of Philosophy). Alphabetical; at the "},{"text":"reference section","bold":true},{"text":"."}]},{"text":[{"text":"Fact sources:","bold":true},{"text":" provide "},{"text":"facts on a wide range of current issues","bold":true},{"text":": "},{"text":"directories","bold":true},{"text":" (Nigeria Yellow Pages, Directory of African Universities), "},{"text":"handbooks","bold":true},{"text":" (Guinness World Records, Handbook of Statistical Tables), "},{"text":"yearbooks","bold":true},{"text":" (Europa World Yearbook, Africa South of the Sahara) and "},{"text":"almanacs","bold":true},{"text":". Housed at the "},{"text":"reference section","bold":true},{"text":". Yearbooks are also called "},{"text":"annuals","bold":true},{"text":"."}]},{"text":[{"text":"Biographical sources:","bold":true},{"text":" information on "},{"text":"individuals","bold":true},{"text":": date of birth, place of birth, education, career achievements ("},{"text":"all of these","bold":true},{"text":"). "},{"text":"2 categories:","bold":true},{"text":" "},{"text":"universal and current","bold":true},{"text":" (International Who's Who, Webster's Biographical Dictionary, Who's Who) and "},{"text":"national and local","bold":true},{"text":" (Africa Who's Who, Newswatch Who's Who). Reference section, some in the Gandhi Library."}]},{"text":[{"text":"Bibliographical sources:","bold":true},{"text":" "},{"text":"lists","bold":true},{"text":" of articles in periodicals, books, conference proceedings, technical reports, theses and dissertations on a "},{"text":"subject","bold":true},{"text":" or by a "},{"text":"given author","bold":true},{"text":"; give quick access to knowledge in the shortest time. "},{"text":"National bibliography","bold":true},{"text":" (National Bibliography of Nigeria, British National Bibliography); "},{"text":"trade","bold":true},{"text":" (The Bookseller, Publishers' Trade List Annual); "},{"text":"subject","bold":true},{"text":" (Economic Development in Nigeria, Bibliographic Guide to Technology). Reference section; old ones in Gandhi."}]},{"text":[{"text":"Index:","bold":true},{"text":" a "},{"text":"directional aid","bold":true},{"text":" (indicator or pointer) to already published materials in "},{"text":"serial form","bold":true},{"text":" within a period; a systematic guide to the contents of a book or text; arranged alphabetically by author, title and subject; published as part of a book or separately. "},{"text":"4 types:","bold":true},{"text":" "},{"text":"book indexes","bold":true},{"text":", "},{"text":"index to collections","bold":true},{"text":" (Anthology of Shakespeare Plays), "},{"text":"periodical index","bold":true},{"text":" (Agricultural Index, British Education Index), "},{"text":"newspaper index","bold":true},{"text":"."}]},{"text":[{"text":"Abstracts:","bold":true},{"text":" a "},{"text":"summary","bold":true},{"text":" of a publication or article with enough bibliographical detail to trace the original; brings quick information to users who may not have access to the original. "},{"text":"3 types:","bold":true},{"text":" "},{"text":"indicative, informative, evaluative","bold":true},{"text":". Examples: Abstracts of English Studies, Nigerian Universities Dissertation Abstracts, Science Abstracts, Chemical Abstracts. Old ones (CAB) in Gandhi; recent ones at the reference section."}]},{"text":[{"text":"Geographical sources:","bold":true},{"text":" information on "},{"text":"places","bold":true},{"text":" (towns, cities, states, countries) and "},{"text":"physical features","bold":true},{"text":" (mountains, valleys, rivers): "},{"text":"maps","bold":true},{"text":" (Map of Nigeria), "},{"text":"atlases","bold":true},{"text":" (The Times Atlas of the World), "},{"text":"gazetteers","bold":true},{"text":" (Federal Republic of Nigeria Gazette) and "},{"text":"travel guides","bold":true},{"text":". Old ones in Gandhi; recent at the reference section."}]},{"text":[{"text":"Manuals:","bold":true},{"text":" "},{"text":"instructions on how to do things","bold":true},{"text":" (\"how to do\", \"how to perform\", \"make\"). Example: product manuals."}]},{"text":[{"text":"Books of quotation:","bold":true},{"text":" quotations on sets of subjects by certain authors, found through their indexes; consulted mostly by "},{"text":"speech makers and writers","bold":true},{"text":". Example: Home Book of Quotations."}]},{"text":[{"text":"Handbooks:","bold":true},{"text":" a "},{"text":"small ready reference source","bold":true},{"text":" that provides facts and information on places, techniques, institutions, subjects; used much like a manual. Examples: "},{"text":"Faculty and Departmental Handbooks","bold":true},{"text":" (True: a faculty handbook is a small ready reference source)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pairs the exam swaps:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fact sources","bold":true},{"text":" give facts on current issues; "},{"text":"biographical sources","bold":true},{"text":" give facts about "},{"text":"individuals","bold":true},{"text":"."}]},{"text":[{"text":"Bibliographical sources","bold":true},{"text":" list publications on a subject or by an author; an "},{"text":"index","bold":true},{"text":" points you to where items appear in serials or a book."}]},{"text":[{"text":"Bibliographical","bold":true},{"text":" (about publications) is not "},{"text":"biographical","bold":true},{"text":" (about people)."}]},{"text":[{"text":"Geographical sources","bold":true},{"text":" are the answer for \"places and physical features\" and for \"Map of Nigeria and travel guide\"; \"reference source\" is too general there."}]}]}]},{"text":[{"text":"\"The encyclopaedia is ...\" Choose "},{"text":"a book or set of books on one or all branches of knowledge","bold":true},{"text":", not \"on Britain\", \"on America\" or \"compiled by Chambers\"; those are only titles or publishers."}]},{"text":[{"text":"\"Reference materials include all EXCEPT\": "},{"text":"journals","bold":true},{"text":" (serials). \"Notable reference collection includes all EXCEPT\": "},{"text":"books","bold":true},{"text":"."}]},{"text":[{"text":"Handbooks appear twice: as a type of "},{"text":"fact source","bold":true},{"text":" and as a reference collection on their own. Both are correct. \"Encyclopedia\" and \"encyclopaedia\" are the same word."}]}]}]},{"number":"12.6","title":"Non-print and audio-visual resources","mustKnow":[{"type":"paragraph","text":[{"text":"B. Non-print resources","bold":true},{"text":" (soft copies, accessed electronically on computers, laptops and phones):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic books, electronic journals, electronic images, electronic texts/records","bold":true},{"text":" (full text from the internet), "},{"text":"servers","bold":true},{"text":" (library software), "},{"text":"CD-ROMs","bold":true},{"text":", floppy and flash disks, hard disks. The main electronic materials in most libraries are "},{"text":"e-books and e-periodicals","bold":true},{"text":"."}]},{"text":[{"text":"Non-print resources allow "},{"text":"multiple usage","bold":true},{"text":" of a material "},{"text":"at the same time","bold":true},{"text":" (a print book serves one person at a time)."}]},{"text":[{"text":"Managed by the "},{"text":"Automation Section","bold":true},{"text":", on the "},{"text":"third floor","bold":true},{"text":". Enquiries on how to access any resource go to the "},{"text":"Readers' Services","bold":true},{"text":" point."}]},{"text":[{"text":"Access area: the "},{"text":"E-Library","bold":true},{"text":": "},{"text":"two classrooms on the third floor","bold":true},{"text":" (undergraduate and postgraduate) plus the "},{"text":"MTN Connect Library","bold":true},{"text":" at the "},{"text":"Akintunde Ojo building","bold":true},{"text":". The library provides "},{"text":"wireless access","bold":true},{"text":", so you may use your own devices in other approved areas. E-resources cover all programmes of the university and beyond."}]},{"text":[{"text":"Remote access","bold":true},{"text":" to the library's online resources is through the "},{"text":"UNILAG Library website","bold":true},{"text":" (not a matric number, telephone directory or hall of residence)."}]}]},{"type":"paragraph","text":[{"text":"C. Audio-visual resources:","bold":true},{"text":" aids that make learning as real as possible, giving first-hand knowledge through "},{"text":"hearing and seeing","bold":true},{"text":". "},{"text":"3 groups:","bold":true}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Materials"}],[{"text":"Where"}]],"rows":[[[{"text":"Audio aids","bold":true}],[{"text":"Radio, tape-recorder, gramophone, audio cassette player"}],[{"text":"Music Library","bold":true}]],[[{"text":"Visual aids","bold":true}],[{"text":"Maps, pictures, textbooks, slide projector, transparencies, print materials"}],[{"text":"Research and Bibliographic Department and Automation Section"}]],[[{"text":"Audio-visual aids","bold":true}],[{"text":"LCD projector, "},{"text":"television","bold":true},{"text":", computers, VCD player, multimedia, artefacts"}],[{"text":"Various sections and the "},{"text":"Museum","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Print versus non-print:","bold":true},{"text":" print is hard copy on the shelves; non-print is soft copy (e-books, e-journals) accessed only on electronic devices and usable by many at once."}]},{"text":[{"text":"Trap: radio, tape-recorder, gramophone and cassette player are "},{"text":"audio","bold":true},{"text":" materials (sound only), not audio-visual and not simply \"electronic\". "},{"text":"Television","bold":true},{"text":" is the standard example of an "},{"text":"audio-visual","bold":true},{"text":" material. Electronic journals, electronic images, library software and CD-ROMs are "},{"text":"non-print","bold":true},{"text":", not audio-visual."}]},{"text":[{"text":"The "},{"text":"MTN Connect Library","bold":true},{"text":" is an e-library area; fact sources are at the "},{"text":"reference section","bold":true},{"text":"."}]},{"text":[{"text":"If a friend cannot find a book: use the "},{"text":"library catalogue","bold":true},{"text":" (card catalogue or OPAC) or ask the officer at the "},{"text":"circulation desk","bold":true},{"text":" or any library staff."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Library: 5 types (public, academic, special, school, private); 5 functions (selection, acquisition, organisation, preservation, dissemination)."}]},{"text":[{"text":"Data = facts; information = processed data; information literacy = locate, retrieve, evaluate, apply, and recognise when information is needed."}]},{"text":[{"text":"5 characteristics: availability/accessibility, accuracy, reliability, timeliness, relevance. Late information is irrelevant."}]},{"text":[{"text":"6 forms: oral, textual, numeric, bibliographic, graphical, multimedia. 2 sources: primary (first-hand; thesis) and secondary (analyses/explains; textbook, encyclopaedia)."}]},{"text":[{"text":"UNILAG Library: print, non-print, audio-visual. Print collections: Africana, Reference, Reserved, Serials, Recent accessions."}]},{"text":[{"text":"Africana = Gandhi Library, basement, closed access, researchers and postgraduates, not loanable, newspapers from 1930, PhD theses."}]},{"text":[{"text":"Reference = facts not opinions, not read cover to cover, not borrowable. Reserved = closed access, no long loan, rapid wider circulation of scarce materials."}]},{"text":[{"text":"Serials = successive parts, regular intervals, indefinitely; journals carry recent original research."}]},{"text":[{"text":"11 reference types: dictionaries (general, specialised, subject), encyclopaedias, fact sources (yearbooks = annuals), biographical, bibliographical, index, abstracts, geographical, manuals, books of quotation, handbooks."}]},{"text":[{"text":"Non-print = Automation Section, E-Library, multiple usage, remote access via library website; audio (Music Library), audio-visual (television)."}]}]}],"theory":{"itemId":"0b59eb48-441b-5264-be58-705b94b87e1e","question":[{"type":"paragraph","text":[{"text":"Highlight five characteristics of good information."}]}]},"practice":[{"topic":"Understanding the Library and Information Resources","named":false}]}},{"itemId":"e874aa7f-8187-5387-924a-f9b3eff80a0a","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:13","parentItemId":null,"revision":1,"payload":{"title":"Information Retrieval Tools","body":"The tools that locate information (library catalogue and OPAC, indexes, abstracts, bibliographies); how to search the OPAC by title, author, subject and keyword; the Library of Congress classes A to Z and the NLM scheme; the internet and its domain types; library databases; the five criteria for evaluating an information resource.","noteType":"guide_topic","number":13,"mustKnow":[{"text":"The tools that locate information (library catalogue and OPAC, indexes, abstracts, bibliographies); how to search the OPAC by title, author, subject and keyword; the Library of Congress classes A to Z and the NLM scheme; the internet and its domain types; library databases; the five criteria for evaluating an information resource."}],"lessons":[{"number":"13.1","title":"The library catalogue","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Information retrieval tools:","bold":true},{"text":" the tools or aids used to access information. They act as a guide to library resources. The three main ones are the "},{"text":"library catalogue","bold":true},{"text":", "},{"text":"indexes and abstracts","bold":true},{"text":", and the "},{"text":"bibliography","bold":true},{"text":"."}]},{"text":[{"text":"Library catalogue:","bold":true},{"text":" the "},{"text":"index","bold":true},{"text":" and essential tool for retrieving library resources. It gives access to "},{"text":"all","bold":true},{"text":" items the library holds, physical and digital: books, e-books, audiovisual materials, reference materials, reserve materials and databases. A library's entire holding is recorded in it."}]},{"text":[{"text":"2 formats of the catalogue:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Manual catalogue","bold":true},{"text":" (catalogue cards): arranged by "},{"text":"author, title and subject","bold":true},{"text":". Entries are filed in "},{"text":"alphabetical","bold":true},{"text":" order."}]},{"text":[{"text":"Online Public Access Catalogue (OPAC):","bold":true},{"text":" the electronic catalogue on the library website. Searched by "},{"text":"title, author, series and keywords","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"UNILAG's two public catalogue cabinets:","bold":true},{"text":" the "},{"text":"Author/Title","bold":true},{"text":" cabinet and the "},{"text":"Subject","bold":true},{"text":" cabinet."}]},{"text":[{"text":"Catalogues for official use only:","bold":true},{"text":" the "},{"text":"Shelf-list","bold":true},{"text":" and the "},{"text":"Authority","bold":true},{"text":" catalogue."}]},{"text":[{"text":"Call number","bold":true},{"text":" (call mark): the number generated when a material is catalogued. It tells you where the item sits on the shelf."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The internet is not always the best or first place to look; the catalogue shows what your own library has and where it is."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the manual card catalogue has author cards, title cards and subject cards. An \"index card\" is "},{"text":"not","bold":true},{"text":" a type of catalogue card."}]},{"text":[{"text":"Trap:","bold":true},{"text":" you can search the catalogue by author, title, subject (and in the OPAC, series and keyword). "},{"text":"Language","bold":true},{"text":" is not a search option."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the catalogue is a "},{"text":"locating tool","bold":true},{"text":"; it does not arrange books on the shelves. Shelf arrangement is the job of the "},{"text":"classification scheme","bold":true},{"text":" (Lesson 13.3)."}]},{"text":[{"text":"OPAC means Online "},{"text":"Public","bold":true},{"text":" Access Catalogue, not \"primary\" or \"private\". It is open to all library users."}]}]}]},{"number":"13.2","title":"Searching the OPAC","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The OPAC has a "},{"text":"Basic Search","bold":true},{"text":" and an "},{"text":"Advanced Search","bold":true},{"text":" platform."}]},{"text":[{"text":"Search by title:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"In the drop-down menu, select "},{"text":"\"Title Keyword\"","bold":true},{"text":"."}]},{"text":[{"text":"Type the title of the book in the next box."}]},{"text":[{"text":"A results page lists the items matching your terms; select your desired title."}]},{"text":[{"text":"Click the title to see its "},{"text":"full record","bold":true},{"text":" (bibliographic details), which also shows where the book is."}]},{"text":[{"text":"Check the "},{"text":"call number","bold":true},{"text":" to know the location."}]},{"text":[{"text":"Go to the shelf to retrieve the material."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search by author:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Select "},{"text":"\"Author Keyword\"","bold":true},{"text":" or "},{"text":"\"Author (last name first)\"","bold":true},{"text":"."}]},{"text":[{"text":"Type the name as "},{"text":"LAST NAME, FIRST NAME","bold":true},{"text":" if you chose \"Author (last name first)\". If you do not know the first name, leave it out or type the first initial."}]},{"text":[{"text":"Choose your author from the list of authors displayed."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search by subject:","bold":true},{"text":" type the subject area in the space provided; a list of subjects is displayed. Subject searching lets you "},{"text":"browse for items by subject","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Choosing the access point: if you do not know the author, use the "},{"text":"title keyword","bold":true},{"text":" when you know the title; if you know neither, use the "},{"text":"subject keyword","bold":true},{"text":". Repeat the process with any other search term you have."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Clause heading\" and \"phrase heading\" are not search types. The real access points are title, author, subject, series and keyword."}]}]}]},{"number":"13.3","title":"Classification: Library of Congress and NLM","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification scheme:","bold":true},{"text":" the system used to classify and arrange library books on the shelves. Shelf arrangement is done with a classification scheme, not with the catalogue."}]},{"text":[{"text":"UNILAG Main Library","bold":true},{"text":" uses the "},{"text":"Library of Congress (LC) Classification Scheme","bold":true},{"text":". The "},{"text":"College of Medicine Library, Idi-Araba","bold":true},{"text":", uses the "},{"text":"National Library of Medicine (NLM) Classification Scheme","bold":true},{"text":"."}]},{"text":[{"text":"Mixed notation:","bold":true},{"text":" the use of "},{"text":"letters of the alphabet as well as Arabic numerals","bold":true},{"text":". Also called "},{"text":"alpha-numeric","bold":true},{"text":". The LC scheme has a mixed notation."}]},{"text":[{"text":"LC main classes use the letters "},{"text":"A to Z","bold":true},{"text":". The letters "},{"text":"O, X and Y","bold":true},{"text":" are reserved for future expansion, so there is no Class O."}]}]},{"type":"table","header":[[{"text":"Letter"}],[{"text":"Subject"}]],"rows":[[[{"text":"A"}],[{"text":"General works"}]],[[{"text":"B"}],[{"text":"Philosophy"}]],[[{"text":"C"}],[{"text":"History"}]],[[{"text":"D"}],[{"text":"History and topography"}]],[[{"text":"E"}],[{"text":"United States (history)"}]],[[{"text":"F"}],[{"text":"United States (local)"}]],[[{"text":"G"}],[{"text":"Geography, Anthropology"}]],[[{"text":"H"}],[{"text":"Social science"}]],[[{"text":"J"}],[{"text":"Political science"}]],[[{"text":"K"}],[{"text":"Law"}]],[[{"text":"L"}],[{"text":"Education"}]],[[{"text":"M"}],[{"text":"Music"}]],[[{"text":"N"}],[{"text":"Fine art"}]],[[{"text":"P"}],[{"text":"Language and linguistics"}]],[[{"text":"Q"}],[{"text":"Science"}]],[[{"text":"R"}],[{"text":"Medicine"}]],[[{"text":"S"}],[{"text":"Agriculture"}]],[[{"text":"T"}],[{"text":"Technology"}]],[[{"text":"U"}],[{"text":"Military science"}]],[[{"text":"V"}],[{"text":"Natural science"}]],[[{"text":"Z"}],[{"text":"Bibliography"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Main classes are "},{"text":"sub-divided with two capital letters","bold":true},{"text":". Examples:"}]}]},{"type":"table","header":[[{"text":"Class Q: Science"}],[{"text":"Class H: Social science"}]],"rows":[[[{"text":"QA Mathematics"}],[{"text":"HA Statistics"}]],[[{"text":"QB Astronomy"}],[{"text":"HB Economic theory, Demography"}]],[[{"text":"QC Physics"}],[{"text":"HC Economic history and conditions"}]],[[{"text":"QD Chemistry"}],[{"text":"HD Economic history and conditions / Production"}]],[[{"text":"QE Geology"}],[{"text":"HE Transportation and communication"}]],[[{"text":"QH Natural history"}],[{"text":"HF Commerce"}]],[[{"text":"QK Botany"}],[{"text":"HG Finance"}]],[[{"text":"QL Zoology"}],[{"text":"HJ Public finance"}]],[[{"text":"QM Human anatomy"}],[{"text":"HM Sociology (General)"}]],[[{"text":"QP Physiology"}],[{"text":"HN Social history, conditions, problems and reform"}]],[[{"text":"QR Microbiology"}],[{"text":"HQ The family, Marriage"}]],[[],[{"text":"HS Societies / Secret societies"}]],[[],[{"text":"HT Communities, Classes, Races"}]],[[],[{"text":"HV Social pathology, Welfare and Criminology"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Dewey Decimal Classification (DDC):","bold":true},{"text":" a different scheme that divides knowledge into ten main classes numbered "},{"text":"000 to 999","bold":true},{"text":". UNILAG does "},{"text":"not","bold":true},{"text":" use it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exam favourites: Law = "},{"text":"K","bold":true},{"text":"; Language = "},{"text":"P","bold":true},{"text":"; Technology = "},{"text":"T","bold":true},{"text":"; Science = "},{"text":"Q","bold":true},{"text":"; Medicine = "},{"text":"R","bold":true},{"text":"; Fine art = "},{"text":"N","bold":true},{"text":"; Music = "},{"text":"M","bold":true},{"text":"; Social science = "},{"text":"H","bold":true},{"text":"; Agriculture = "},{"text":"S","bold":true},{"text":"; Geography = "},{"text":"G","bold":true},{"text":"; Education = "},{"text":"L","bold":true},{"text":"; General works = "},{"text":"A","bold":true},{"text":". \"Law and languages\" in that order = "},{"text":"K and P","bold":true},{"text":"."}]},{"text":[{"text":"Sociology books sit at shelf "},{"text":"HM","bold":true},{"text":" (Sociology, General). HC is Economic history, TA is under Technology, NA is under Fine art."}]},{"text":[{"text":"A call number mixes letters and Arabic numerals (e.g. HM followed by numbers); that is the mixed, alpha-numeric notation. Roman numerals are "},{"text":"not","bold":true},{"text":" used."}]},{"text":[{"text":"NLM scheme:","bold":true},{"text":" covers Medicine and related sciences. It uses the LC schedules as a supplement for subjects bordering on medicine and for general reference material. Because they overlap with NLM, the LC schedules "},{"text":"QM (Human anatomy), QR (Microbiology) and R (Medicine)","bold":true},{"text":" are "},{"text":"not used at all","bold":true},{"text":" by the NLM."}]},{"text":[{"text":"NLM structure (QS to QZ are preclinical sciences; W classes are the health professions and clinical medicine):"}]}]},{"type":"table","header":[[{"text":"Preclinical sciences"}],[{"text":"Medicine and related subjects"}]],"rows":[[[{"text":"QS Human anatomy"}],[{"text":"W Health professions"}]],[[{"text":"QT Physiology"}],[{"text":"WA Public health"}]],[[{"text":"QU Biochemistry"}],[{"text":"WB Practice of medicine"}]],[[{"text":"QV Pharmacology"}],[{"text":"WC Communicable diseases"}]],[[{"text":"QW Microbiology and Immunology"}],[{"text":"WD 100 Nutrition disorders; WD 200 Metabolic diseases; WD 300 Immunologic diseases; WD 400 Animal poisons; WD 500 Plant poisons; WD 600 Injuries caused by physical agents; WD 700 Aviation and space medicine"}]],[[{"text":"QX Parasitology"}],[{"text":"WE Musculoskeletal system"}]],[[{"text":"QY Clinical pathology"}],[{"text":"WF Respiratory system"}]],[[{"text":"QZ Pathology"}],[{"text":"WG Cardiovascular system"}]],[[],[{"text":"WH Hemic and lymphatic system"}]],[[],[{"text":"WI Digestive system"}]],[[],[{"text":"WJ Urogenital system"}]],[[],[{"text":"WK Endocrine system"}]],[[],[{"text":"WL Nervous system"}]],[[],[{"text":"WM Psychiatry"}]],[[],[{"text":"WN Radiology"}]],[[],[{"text":"WO Surgery"}]],[[],[{"text":"WP Gynaecology"}]],[[],[{"text":"WQ Obstetrics"}]],[[],[{"text":"WR Dermatology"}]],[[],[{"text":"WS Paediatrics"}]],[[],[{"text":"WT Geriatrics"}]],[[],[{"text":"WU Dentistry, Oral surgery"}]],[[],[{"text":"WV Otolaryngology"}]],[[],[{"text":"WW Ophthalmology"}]],[[],[{"text":"WX Hospitals and health facilities"}]],[[],[{"text":"WY Nursing"}]],[[],[{"text":"WZ History of medicine"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Questions to ask while searching the catalogue:","bold":true},{"text":" how many titles does the library have on your topic? What do the titles, dates and authors tell you? Are there subheadings? Are there cross-references or alternative headings? Will the library support your topic, or will you need "},{"text":"interlibrary loan","bold":true},{"text":"?"}]},{"text":[{"text":"Cross-references:","bold":true},{"text":" terms, names or subjects that lead you from the known to the unknown (and the reverse) in the catalogue."}]},{"text":[{"text":"Interlibrary loan:","bold":true},{"text":" students have no reciprocal borrowing privileges at all Nigerian universities, but UNILAG library can borrow materials from any university library in Nigeria for you. It can take a week or longer, so start early."}]}]}]},{"number":"13.4","title":"Indexes, abstracts and bibliographies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Indexes and abstracts:","bold":true},{"text":" bibliographic information sources that help users find information quickly and efficiently. They are also called "},{"text":"bridges to published information","bold":true},{"text":"."}]},{"text":[{"text":"Index:","bold":true},{"text":" an "},{"text":"indicator or pointer","bold":true},{"text":" to required information. It gives a systematic guide to the contents of a text or series of texts: names, places, titles, keywords and titles of publications. An index may be published at the "},{"text":"back of a book","bold":true},{"text":" or as a "},{"text":"separate publication","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" give the full text."}]},{"text":[{"text":"4 uses of an index:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Serves as a gateway to the information material."}]},{"text":[{"text":"Gives the basic information."}]},{"text":[{"text":"Provides only the entry points to users during their search for information."}]},{"text":[{"text":"Can list all the sources cited within a text or article."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Examples of indexes:","bold":true},{"text":" Newspaper Index, Engineering Index, Index Medicus. "},{"text":"Types of index:","bold":true},{"text":" book index, index to collections, periodical index, newspaper index."}]},{"text":[{"text":"Abstract:","bold":true},{"text":" a "},{"text":"brief summary","bold":true},{"text":" of the contents of a book, research article, thesis, speech or conference proceedings. "},{"text":"3 uses:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provides a description or summary of the content of the article."}]},{"text":[{"text":"Serves as a real "},{"text":"surrogate","bold":true},{"text":" (stand-in) of the document."}]},{"text":[{"text":"Lets a user know the content of the document without reading it from beginning to end."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Examples of abstracts:","bold":true},{"text":" Chemical Abstracts, Dissertation Abstracts, Library and Information Science Abstracts, Social Science Abstracts. "},{"text":"3 types of abstract:","bold":true},{"text":" "},{"text":"indicative","bold":true},{"text":", "},{"text":"informative","bold":true},{"text":" and "},{"text":"evaluative","bold":true},{"text":"."}]},{"text":[{"text":"Bibliography:","bold":true},{"text":" a "},{"text":"list of books or written sources of information on a subject","bold":true},{"text":", usually consulted in preparing a piece of work and referred to in the text. Examples in the University Library: "},{"text":"National Bibliography of Nigeria (NBN)","bold":true},{"text":" and "},{"text":"British National Bibliography (BNB)","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Index versus abstract: an index only "},{"text":"points","bold":true},{"text":" to where information is; an abstract "},{"text":"summarises","bold":true},{"text":" what the document says. Both are now mainly online; abstracts are usually collected, organised systematically and indexed."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"An index serves as a ______ to required information\": the full answer is "},{"text":"pointer and indicator","bold":true},{"text":", not one alone."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Review abstract\" is not a type of abstract. The three types are indicative, informative and evaluative."}]},{"text":[{"text":"Bibliography definitions you may see, all correct: a list of written sources on a subject; a list of books and articles someone used when writing on a subject; a list of books, magazines and articles about a particular subject. If all three appear together, the answer is \"all of the above\"."}]}]}]},{"number":"13.5","title":"The internet and library databases","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internet:","bold":true},{"text":" has a wealth of knowledge for anyone with access, but "},{"text":"anyone with access can place false information","bold":true},{"text":" on it. There are "},{"text":"no guidelines","bold":true},{"text":" on the general web for accuracy. So information from the internet "},{"text":"cannot","bold":true},{"text":" be assumed accurate; it must be evaluated."}]},{"text":[{"text":"4 domain types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":".com:","bold":true},{"text":" originally commercial, but can be used for anything as long as it is paid for."}]},{"text":[{"text":".edu:","bold":true},{"text":" used "},{"text":"only by accredited post-secondary institutions","bold":true},{"text":" (institutions of higher learning)."}]},{"text":[{"text":".gov and .us:","bold":true},{"text":" owned by the United States Government."}]},{"text":[{"text":".org:","bold":true},{"text":" owned by an organisation, but it does not matter "},{"text":"what type","bold":true},{"text":" of organisation."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Library databases:","bold":true},{"text":" collections of e-books, journals, newspapers and magazines, available anywhere with an internet connection and a login. They make searching for "},{"text":"peer-reviewed","bold":true},{"text":" articles easy. Examples of interfaces: "},{"text":"EBSCO, Science Direct, LexisNexis, JSTOR","bold":true},{"text":"."}]},{"text":[{"text":"Major benefit:","bold":true},{"text":" they are designed by proprietary publishers or aggregators and "},{"text":"subscribed to by the library to support student assignments and topics","bold":true},{"text":". They are more organised than Google results and easier to document and cite."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The Martin Luther King example: Google returns Wikipedia (anyone can edit it, so not reliable), the Nobel Peace Prize site (generally reliable) and www.martinlutherking.org, which is hosted by Stormfront, a white-supremacist organisation. A .org address proves nothing about reliability."}]},{"text":[{"text":"Access at UNILAG:","bold":true},{"text":" databases are reached through the library website when you are within the university "},{"text":"IP range","bold":true},{"text":"; some fee-based databases need a "},{"text":"password","bold":true},{"text":" for remote access."}]},{"text":[{"text":"Match subject coverage:","bold":true},{"text":" most disciplines have their own databases; others are "},{"text":"interdisciplinary","bold":true},{"text":". "},{"text":"EBSCO Host and JSTOR","bold":true},{"text":" are interdisciplinary; "},{"text":"Westlaw, HeinOnline and LexisNexis","bold":true},{"text":" are for Law; "},{"text":"JaypeeDigital","bold":true},{"text":" is for Clinical and Biomedical Sciences."}]},{"text":[{"text":"Match time coverage:","bold":true},{"text":" some databases give full text for the most recent 15 to 20 years, some only the current year, some over 100 years back."}]},{"text":[{"text":"7 types of information in databases:","bold":true},{"text":" full-text periodical articles; full-text encyclopaedic or reference sources; full-text books or chapters (e-books); government or primary documents; images, audio or video clips; statistical information; citations and/or abstracts."}]},{"text":[{"text":"Update frequency:","bold":true},{"text":" newspaper databases update "},{"text":"daily","bold":true},{"text":"; an encyclopaedia database irregularly or yearly. The more current your need, the more frequent the update you want."}]},{"text":[{"text":"2 most frequent ways results are ranked:","bold":true},{"text":" "},{"text":"chronologically by date","bold":true},{"text":" (most recent first; "},{"text":"LIFO","bold":true},{"text":", Last In First Out) and by "},{"text":"relevancy","bold":true},{"text":". Relevancy ranking counts how often search terms appear, how close they are to each other and how prominent they are; a term in the "},{"text":"title","bold":true},{"text":" counts as more relevant than one in the body."}]},{"text":[{"text":"Read the "},{"text":"abstract","bold":true},{"text":" before the full article; it may show the article is not needed. Databases have "},{"text":"PRINT, EMAIL and SAVE","bold":true},{"text":" buttons; still keep a back-up on a storage device."}]}]}]},{"number":"13.6","title":"Evaluating information resources","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Resources are evaluated to determine their "},{"text":"credibility and relevance","bold":true},{"text":" to your topic before you select them for research or an assignment."}]},{"text":[{"text":"5 criteria:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Currency:","bold":true},{"text":" publication date; how up to date the citations are; how current the information needs to be for your topic."}]},{"text":[{"text":"Relevancy:","bold":true},{"text":" does it relate directly to your topic or answer your question? Who is the audience (scholarly or general)? Is it primary or secondary? General background or in-depth?"}]},{"text":[{"text":"Authority:","bold":true},{"text":" who created it? Qualifications of the author, publisher or organisation; the author's education and experience; look for the author's biography or publisher information."}]},{"text":[{"text":"Accuracy:","bold":true},{"text":" is it supported by evidence? Can you verify it in another source? How extensive is the bibliography? Are there spelling, grammar or typographical errors?"}]},{"text":[{"text":"Purpose:","bold":true},{"text":" is it meant to inform, sell or persuade? Is it fair and balanced? Are there political, ideological, cultural, religious or personal biases? Is opinion or propaganda easy to recognise? Are there advertisements?"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"Size","bold":true},{"text":" is not a criterion. A long book is not more credible because it is big. Nor are \"intelligence\" or \"strategy\" criteria."}]},{"text":[{"text":"\"Currency, authority, ______ and ______\": the missing pair is "},{"text":"relevancy and accuracy","bold":true},{"text":"."}]},{"text":[{"text":"Quick reliability test: is it accurate, well written and current? Does it cover the topic thoroughly, state its purpose and give supporting documentation? Apply the five criteria to print and non-print sources alike."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Information retrieval tools: library catalogue, indexes and abstracts, bibliography."}]},{"text":[{"text":"Catalogue formats: manual (cards; author, title, subject; alphabetical) and OPAC (title, author, series, keyword). Shelf-list and Authority catalogues are for official use."}]},{"text":[{"text":"OPAC search: Title Keyword or Author Keyword, then full record, then call number, then shelf."}]},{"text":[{"text":"UNILAG Main Library: Library of Congress scheme (mixed, alpha-numeric notation; A to Z; O, X, Y reserved). College of Medicine: NLM scheme."}]},{"text":[{"text":"K Law, P Language, T Technology, Q Science, R Medicine, H Social science, HM Sociology."}]},{"text":[{"text":"Dewey Decimal: 000 to 999; not used at UNILAG."}]},{"text":[{"text":"Index = pointer and indicator; abstract = brief summary (indicative, informative, evaluative); bibliography = list of written sources on a subject (NBN, BNB)."}]},{"text":[{"text":"Internet: anyone can post false information; .com, .edu (accredited post-secondary only), .gov/.us, .org."}]},{"text":[{"text":"Library databases are subscribed to by the library for student assignments; EBSCO and JSTOR are interdisciplinary."}]},{"text":[{"text":"Evaluate with currency, relevancy, authority, accuracy, purpose. Not size."}]}]}],"theory":{"itemId":"1554bfcd-b06b-56b2-9054-2ead2b884028","question":[{"type":"paragraph","text":[{"text":"List the three information retrieval tools in the library and explain how the University of Lagos Main Library classifies its materials."}]}]},"practice":[{"topic":"Information Retrieval Tools","named":false}]}},{"itemId":"83084064-8894-5e3b-9ebd-8691e527c2f5","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:14","parentItemId":null,"revision":1,"payload":{"title":"Search Strategies","body":"What a search strategy is and its 3 basic steps; the 5 stages of an electronic search; simple, advanced and meta searches; the 6 search techniques (Boolean AND/OR/NOT, parenthesis, phrase, truncation, wildcards, field searching); keyword vs subject searching; search engines and Google Scholar; how to narrow or broaden a search, save sources and choose quotations.","noteType":"guide_topic","number":14,"mustKnow":[{"text":"What a search strategy is and its 3 basic steps; the 5 stages of an electronic search; simple, advanced and meta searches; the 6 search techniques (Boolean AND/OR/NOT, parenthesis, phrase, truncation, wildcards, field searching); keyword vs subject searching; search engines and Google Scholar; how to narrow or broaden a search, save sources and choose quotations."}],"lessons":[{"number":"14.1","title":"What a search strategy is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search strategy:","bold":true},{"text":" the art of planning and conducting searches for the most efficient result. Its whole essence is to conceptualise a research topic and access the right information resources needed for a project, so you can navigate your way to the end of the project."}]},{"text":[{"text":"Effective use of library resources requires a search strategy.","bold":true},{"text":" It is the process employed to achieve effective search results."}]},{"text":[{"text":"A research exercise must be driven by a subject matter or topic.","bold":true}]}]},{"type":"paragraph","text":[{"text":"3 basic steps","bold":true},{"text":" in a search strategy, in order:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identification of the subject matter/topic.","bold":true}]},{"text":[{"text":"General knowledge/overview of the subject matter/topic:","bold":true},{"text":" attempt a definition of the topic to get the right conceptualisation or scope. Use a "},{"text":"general encyclopedia","bold":true},{"text":" (Encyclopedia Britannica, Encyclopedia Americana), or sometimes a specialised reference source. Overviews give insight into the historical development or antecedents of the area."}]},{"text":[{"text":"Narrower overview:","bold":true},{"text":" move from the general concept to a narrower scope focused on specific areas of research and variables. Resources: "},{"text":"abstracts, indexes, bibliographies","bold":true},{"text":" (pointers or bridges to specific resources through their full bibliographic details), plus the "},{"text":"card catalogue","bold":true},{"text":" or "},{"text":"online catalogue","bold":true},{"text":" for specific titles or subjects."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic search strategy:","bold":true},{"text":" a structured organisation of terms used to search a database; it shows how search terms combine to retrieve the best results. "},{"text":"Relevant","bold":true},{"text":" results are on target or very close to the information sought."}]},{"text":[{"text":"A complex search statement is refined by adding "},{"text":"Boolean operators, quotation marks","bold":true},{"text":" (exact phrases), "},{"text":"truncation symbols","bold":true},{"text":" or "},{"text":"field search limiters","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The 5 stages of effective electronic searching","bold":true},{"text":" (do not rush to the first search box):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define your information need."}]},{"text":[{"text":"Decide which resource/s to use (both e-resources and search engines)."}]},{"text":[{"text":"Find out what search options your chosen resource offers."}]},{"text":[{"text":"Run your search."}]},{"text":[{"text":"Review and refine your search."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The 3 steps apply to both print and electronic resources. The physical library can be explored with the library guide and professional guidance; electronic resources demand "},{"text":"extra skills","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the 3 steps go from "},{"text":"general to narrow","bold":true},{"text":". Encyclopedias belong to step 2; abstracts, indexes and bibliographies to step 3."}]},{"text":[{"text":"Trap: \"effective use of library resources requires...\" "},{"text":"search strategies","bold":true},{"text":", not punctuality, smartness or maturity."}]},{"text":[{"text":"Keep the counts apart: "},{"text":"3 basic steps","bold":true},{"text":" of a search strategy; "},{"text":"5 stages","bold":true},{"text":" of an electronic search."}]}]}]},{"number":"14.2","title":"Types of searches","mustKnow":[{"type":"paragraph","text":[{"text":"To search is to carefully look for something; effective searching requires planning. There are "},{"text":"3 types of searches","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Simple search:","bold":true},{"text":" the user uses some "},{"text":"keywords","bold":true},{"text":" to perform a "},{"text":"quick information search","bold":true},{"text":" from a database or a search engine. It may retrieve a "},{"text":"huge amount of output","bold":true},{"text":" that takes time to sieve through. It is browsing rather than focused searching; one or two concepts may be used. Use it when you are "},{"text":"not sure of the type of information required","bold":true},{"text":" and when the topic is "},{"text":"not focused on any area","bold":true},{"text":"."}]},{"text":[{"text":"Advanced search:","bold":true},{"text":" the use of techniques that help to "},{"text":"define","bold":true},{"text":" the information being searched. "},{"text":"Filtering","bold":true},{"text":" is done to reduce the amount of items retrieved; filtering refines the search for relevancy. The user can apply "},{"text":"multiple search fields","bold":true},{"text":" to broaden or narrow the search. Available in most search tools such as "},{"text":"ScienceDirect, Ebrary, EbscoHost","bold":true},{"text":"."}]},{"text":[{"text":"Meta search:","bold":true},{"text":" the user uses a "},{"text":"variety of search tools simultaneously","bold":true},{"text":", through "},{"text":"meta search engines","bold":true},{"text":" such as "},{"text":"Dogpile, Search.com, Metacrawler and Vivisimo","bold":true},{"text":". These search many search tools (Google, Yahoo, MSN) at once."}]}]},{"type":"paragraph","text":[{"text":"3 things advanced searching helps you do:","bold":true},{"text":" apply filtering; reduce the number of items retrieved; apply multiple search fields."}]},{"type":"table","header":[[],[{"text":"Simple search"}],[{"text":"Advanced search"}],[{"text":"Meta search"}]],"rows":[[[{"text":"Advantage 1"}],[{"text":"Quick information search from a database or search engine"}],[{"text":"Allows filtering, so more relevant materials are retrieved"}],[{"text":"Uses a variety of search tools simultaneously"}]],[[{"text":"Advantage 2"}],[{"text":"Helpful when not sure of the type of information required"}],[{"text":"Reduces the number of items retrieved"}],[]],[[{"text":"Advantage 3"}],[{"text":"Useful when the topic is not focused on any area"}],[{"text":"Applies multiple search fields"}],[]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example of a simple search: "},{"text":"Malaria and Africa","bold":true},{"text":". It can cover any period, adults or children, male or female, any part of Africa, and may even retrieve information on Africa unrelated to malaria. The results are overwhelming, so the user must apply search techniques to focus them."}]},{"text":[{"text":"A meta search is conducted the same way as a search in a single engine; the "},{"text":"only difference","bold":true},{"text":" is that results come from several engines simultaneously."}]},{"text":[{"text":"Trap: \"retrieves a huge amount of information\" belongs to "},{"text":"simple","bold":true},{"text":" search, so it is the "},{"text":"exception","bold":true},{"text":" in any list of advanced-search advantages."}]},{"text":[{"text":"Trap: \"complex search\" and \"quick search\" are not recognised types. Multiple search fields = "},{"text":"advanced search","bold":true},{"text":"; many search tools at once = "},{"text":"meta search","bold":true},{"text":"; quick keyword search = "},{"text":"simple search","bold":true},{"text":"."}]},{"text":[{"text":"Advanced search lets you limit by fields such as "},{"text":"year of publication","bold":true},{"text":", language or author, not by size of book, number of pages or volume."}]}]}]},{"number":"14.3","title":"Search techniques","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search techniques:","bold":true},{"text":" ways of using search terms to find required information from search tools such as "},{"text":"OPAC (Online Public Access Catalogues), general search engines, search directories, portals and online databases (the deep web)","bold":true},{"text":"."}]},{"text":[{"text":"Choosing keywords:","bold":true},{"text":" identify the main concepts of your topic and build a list of keywords; this increases your search capacity (acid rain: \"wet deposition\", \"acid deposition\"). Do "},{"text":"not","bold":true},{"text":" type a complete sentence. Leave out minor words: articles (a, an, the) and prepositional or verb phrases. Stick to "},{"text":"nouns and noun phrases","bold":true},{"text":" that express the major concepts, and search for "},{"text":"synonyms","bold":true},{"text":" as alternative terms."}]},{"text":[{"text":"To find alternative keywords use a "},{"text":"thesaurus","bold":true},{"text":", the "},{"text":"Library of Congress Subject Headings","bold":true},{"text":", a "},{"text":"reference book","bold":true},{"text":" or "},{"text":"Internet subject directories","bold":true},{"text":". Write down all your search terms so you know which worked."}]}]},{"type":"paragraph","text":[{"text":"The 6 search techniques:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Boolean searching","bold":true}]},{"text":[{"text":"Parenthesis","bold":true}]},{"text":[{"text":"Phrase searching","bold":true}]},{"text":[{"text":"Truncation","bold":true}]},{"text":[{"text":"Wildcards","bold":true}]},{"text":[{"text":"Field searching","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Boolean searching:","bold":true},{"text":" based on the symbolic logic of "},{"text":"George Boole","bold":true},{"text":", a 19th-century English mathematician. Keywords are combined with connecting terms called "},{"text":"Boolean operators","bold":true},{"text":"; the "},{"text":"3 basic operators are AND, OR, NOT","bold":true},{"text":". Boolean techniques "},{"text":"reduce irrelevant documents","bold":true},{"text":". "},{"text":"2 reasons for using them:","bold":true},{"text":" to focus a search when the topic has multiple search terms; to connect pieces of information exactly as you want them (Second creation (title) AND Wilmot and Campbell (author) AND 2000 (year))."}]}]},{"type":"table","header":[[{"text":"Operator"}],[{"text":"Effect"}],[{"text":"Tells the database"}],[{"text":"Example"}]],"rows":[[[{"text":"AND","bold":true}],[{"text":"Narrows","bold":true},{"text":" results"}],[{"text":"ALL","bold":true},{"text":" terms must be present"}],[{"text":"cloning AND humans AND ethics"}]],[[{"text":"OR","bold":true}],[{"text":"Broadens","bold":true},{"text":" results; connects similar concepts ("},{"text":"synonyms","bold":true},{"text":")"}],[{"text":"ANY","bold":true},{"text":" term may be present"}],[{"text":"cloning OR genetics OR reproduction"}]],[[{"text":"NOT","bold":true}],[{"text":"Excludes","bold":true},{"text":" words; narrows"}],[{"text":"Ignore concepts implied by your terms"}],[{"text":"cloning NOT sheep"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Parenthesis:","bold":true},{"text":" brackets specify the "},{"text":"order","bold":true},{"text":" of interpretation. Information inside brackets is read "},{"text":"first","bold":true},{"text":", then information outside. (vomit OR diarrhoea) AND blood; Malaria AND (prevention OR control). Without brackets, keywords are searched left to right."}]},{"text":[{"text":"Phrase searching:","bold":true},{"text":" surround keywords in "},{"text":"quotation marks","bold":true},{"text":" so the engine finds only words that appear "},{"text":"side by side","bold":true},{"text":" in that order. It narrows results significantly. \"capital gains tax\", \"physician assisted suicide\", \"human genome project\"."}]},{"text":[{"text":"Truncation:","bold":true},{"text":" using an "},{"text":"asterisk (","bold":true},{"text":")","bold":true,"italic":true},{"text":" at the ","italic":true},{"text":"root","bold":true,"italic":true},{"text":" of a word so the tool retrieves all word variations after it. Purpose: to ","italic":true},{"text":"broaden","bold":true,"italic":true},{"text":" results. teen","italic":true},{"text":" retrieves teen, teens, teenager, teenagers, teenaged, teensy, teeny."}]},{"text":[{"text":"Wildcards:","bold":true},{"text":" characters that represent "},{"text":"one character or letter","bold":true},{"text":" in a word; useful when you are "},{"text":"not sure of the spelling","bold":true},{"text":" (American vs English spelling). Most common symbol: "},{"text":"?","bold":true},{"text":". An?mia retrieves anaemia and anemia; colo?r retrieves colour and color."}]},{"text":[{"text":"Field searching:","bold":true},{"text":" searching a "},{"text":"particular part of a computer record","bold":true},{"text":" (title, author's last name, date range, language; on the web, domain name, URL or file type). Use it to narrow very specifically: year of publication, language, affiliation, review articles, age, gender or abstract only."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discipline matters.","bold":true},{"text":" Information is organised into disciplines, and your topic's discipline shapes the research: one or more organisations may disseminate its information; there may be a standard terminology and a standard index; scholarly resources may be preferred over popular, primary over secondary, current over historical; and certain investigative methods may be preferred (laboratory experiments, simulations, field work, interviews, surveys, statistical analysis, tests and measurements, original thought and analysis)."}]},{"text":[{"text":"Keyword example: for a topic on university students who are heavy drinkers of alcohol and risk-taking behaviour, choose alcohol, alcoholic beverages, drinking, risk-taking behaviour, university students."}]},{"text":[{"text":"AND is implied","bold":true},{"text":" in many databases: Google turns \"college students test anxiety\" into college AND students AND test AND anxiety, so the words may appear separately. Fix this with phrases: \"college students\" AND \"test anxiety\"."}]},{"text":[{"text":"Search order:","bold":true},{"text":" databases usually treat "},{"text":"AND as the primary operator","bold":true},{"text":" and connect AND terms first. When mixing AND and OR, put the alternatives in brackets: (ethic"},{"text":" OR moral","italic":true},{"text":") AND (bioengineering OR cloning)."}]},{"text":[{"text":"Truncation cautions: do not truncate a very short root (too many words, poor relevance). Some engines truncate automatically for plural, -ing or -ed endings; symbols vary; some tools do not support it."}]},{"text":[{"text":"Trap: "},{"text":"* = truncation","bold":true},{"text":" (any letters after a root, broadens); "},{"text":"? = wildcard","bold":true},{"text":" (one letter inside a word, spelling variants). \"The asterisk sign (*) is known as...\" "},{"text":"truncation","bold":true},{"text":", not wild card."}]},{"text":[{"text":"Trap: "},{"text":"filtering is not a search technique","bold":true},{"text":"; it is what advanced searching does."}]},{"text":[{"text":"Trap: OR "},{"text":"broadens","bold":true},{"text":"; AND and NOT "},{"text":"narrow","bold":true},{"text":" or limit. \"Develop\" and \"differentiate\" are not Boolean functions."}]}]}]},{"number":"14.4","title":"Keyword vs subject searching, search engines and Google Scholar","mustKnow":[{"type":"paragraph","text":[{"text":"Most databases offer two ways to search:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Subject searching:","bold":true},{"text":" browsing for items by "},{"text":"subject heading","bold":true},{"text":"; returns only results where the term appears in the "},{"text":"subject field","bold":true},{"text":"."}]},{"text":[{"text":"Keyword searching:","bold":true},{"text":" looks for documents containing "},{"text":"one or more words specified by the user","bold":true},{"text":", anywhere in the record."}]}]},{"type":"table","header":[[{"text":"Keyword searching"}],[{"text":"Subject searching"}]],"rows":[[[{"text":"Natural language words describing your topic; good to start with"}],[{"text":"Pre-defined "},{"text":"controlled vocabulary","bold":true},{"text":" used to describe each item's content"}]],[[{"text":"More flexible; terms combine in many ways"}],[{"text":"Less flexible; you must know the exact controlled vocabulary term"}]],[[{"text":"Database looks for keywords "},{"text":"anywhere","bold":true},{"text":" in the record, not necessarily connected"}],[{"text":"Database looks only in the "},{"text":"subject heading or descriptor field","bold":true},{"text":", where the most relevant words appear"}]],[[{"text":"May yield too many or too few results"}],[{"text":"If too many results, "},{"text":"subheadings","bold":true},{"text":" focus on one aspect of the broader subject"}]],[[{"text":"May yield many irrelevant results"}],[{"text":"Results usually very relevant to the topic"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search engines:","bold":true},{"text":" huge databases of Internet files collected by a computer program called a "},{"text":"crawler, robot or spider","bold":true},{"text":". They have "},{"text":"no policies for selection of content","bold":true},{"text":" or evaluation, so results may not be what you expect. They use web browsers (e.g. Internet Explorer) to query the databases, index files into terms such as title, author and URL, and search mostly by "},{"text":"keywords","bold":true},{"text":". Example: "},{"text":"Google","bold":true},{"text":"."}]},{"text":[{"text":"3 times to use a search engine:","bold":true},{"text":" for general information; when a topic has many facets; for current information."}]},{"text":[{"text":"Google Scholar:","bold":true},{"text":" a useful search tool for "},{"text":"academic information","bold":true},{"text":". It holds scholarly material: "},{"text":"books, patents, journal articles and conference papers","bold":true},{"text":", and links to the full text of articles and to related or similar articles. A search on Malaria +Africa gave results from a book and from journal articles."}]},{"text":[{"text":"Ranking of results:","bold":true},{"text":" databases rank retrieved articles by "},{"text":"date","bold":true},{"text":" (most recent first) and "},{"text":"relevance","bold":true},{"text":" (how often and how prominently the search terms appear in the record)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the tool for academic information is "},{"text":"Google Scholar","bold":true},{"text":", not Google (whole web, no scholarly selection), not a web crawler (a program that collects pages) and not Opera Mini (a browser)."}]},{"text":[{"text":"Keyword searching is where you "},{"text":"start","bold":true},{"text":"; subject searching gives "},{"text":"precision","bold":true},{"text":" once you know the controlled term."}]},{"text":[{"text":"Ranking is never by \"number of times the search was conducted\" or \"number of records\"."}]}]}]},{"number":"14.5","title":"Assessing results, saving sources and quoting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Research is seldom neat. A first search may give "},{"text":"too much","bold":true},{"text":", "},{"text":"too little","bold":true},{"text":", or "},{"text":"unhelpful","bold":true},{"text":" information; you may need to redesign your topic question. The most common problem is results that are "},{"text":"too broad or unrelated","bold":true},{"text":"; the way out is to "},{"text":"rethink (change) your search strategy","bold":true},{"text":", not your topic, author or location."}]}]},{"type":"paragraph","text":[{"text":"6 ways to narrow a search (too many results):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Use "},{"text":"AND","bold":true},{"text":" to add relevant terms."}]},{"text":[{"text":"Use "},{"text":"NOT","bold":true},{"text":" to eliminate terms."}]},{"text":[{"text":"Search for words in the "},{"text":"title field","bold":true},{"text":" instead of the full text."}]},{"text":[{"text":"Use "},{"text":"phrase searching","bold":true},{"text":"."}]},{"text":[{"text":"Use "},{"text":"more specific vocabulary","bold":true},{"text":"."}]},{"text":[{"text":"Choose a "},{"text":"narrower category","bold":true},{"text":" of the major topic."}]}]},{"type":"paragraph","text":[{"text":"5 ways to broaden a search (too few results):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Combine "},{"text":"synonymous terms with OR","bold":true},{"text":"."}]},{"text":[{"text":"Think of the topic in "},{"text":"broader terms","bold":true},{"text":" and use more general vocabulary."}]},{"text":[{"text":"Use the "},{"text":"appropriate vocabulary for the discipline","bold":true},{"text":"."}]},{"text":[{"text":"Eliminate the least important concept.","bold":true}]},{"text":[{"text":"Use the "},{"text":"\"related documents\"","bold":true},{"text":" option offered by some engines and databases."}]}]},{"type":"paragraph","text":[{"text":"Saving sources:","bold":true},{"text":" save as much information about each source as possible, so you can find it again and build citations. Catalogues and databases let you "},{"text":"email, print or save","bold":true},{"text":" the citation information and sometimes the "},{"text":"full text","bold":true},{"text":". For a website, save the "},{"text":"URL","bold":true},{"text":" (cut and paste it into your email). "},{"text":"Memorising","bold":true},{"text":" a source is not a way of saving it."}]},{"type":"paragraph","text":[{"text":"Identifying sources to quote:","bold":true},{"text":" pick ideas and statements relevant to your topic. "},{"text":"4 reasons to use a quotation:","bold":true},{"text":" to add the power of the author's words to your argument; to disagree with the author's argument; to compare and contrast specific points of view; to note important research already available on your topic."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The narrowing and broadening lists are the Boolean table in action: AND and NOT narrow; OR broadens. Too "},{"text":"few","bold":true},{"text":" sources: "},{"text":"OR with synonyms","bold":true},{"text":", never AND or NOT."}]},{"text":[{"text":"Example of saving: in Academic Search Complete, open the record or full text and look for the email, print or save options. Some online newspapers and magazines let you email articles to yourself."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search strategy = the art of planning and conducting searches for the most efficient result; effective library use requires it."}]},{"text":[{"text":"3 basic steps: identify the topic; general overview (encyclopedia); narrower overview (abstracts, indexes, bibliographies, catalogue)."}]},{"text":[{"text":"5 stages of electronic search: define need; choose resources; learn search options; run; review and refine."}]},{"text":[{"text":"3 types: simple (quick keywords, huge output), advanced (filtering, multiple fields), meta (many search tools at once: Dogpile, Metacrawler, Search.com, Vivisimo)."}]},{"text":[{"text":"6 techniques: Boolean, parenthesis, phrase, truncation, wildcards, field searching. Filtering is not one."}]},{"text":[{"text":"AND narrows (all terms); OR broadens (synonyms, any term); NOT excludes."}]},{"text":[{"text":"Brackets read first; quotation marks = phrase; * = truncation (broadens); ? = wildcard (one letter)."}]},{"text":[{"text":"Keyword search = natural language, anywhere in the record; subject search = controlled vocabulary, subject field only."}]},{"text":[{"text":"Google Scholar is the tool for academic information; results are ranked by date and relevance."}]},{"text":[{"text":"Too many results: AND, NOT, title field, phrases. Too few: OR synonyms, broader terms. Save sources by email, print or save."}]}]}],"theory":{"itemId":"ff6ca6bc-9dce-5840-9ac7-584fe28ccd74","question":[{"type":"paragraph","text":[{"text":"Explain the three Boolean operators and give two reasons for using them in an online search."}]}]},"practice":[{"topic":"Search Strategies","named":false}]}},{"itemId":"ac7a570b-da0d-57d9-9911-e1a795ba4e49","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:15","parentItemId":null,"revision":1,"payload":{"title":"Style Manual, Citation and Referencing","body":"Copyright, fair use and unfair use; what plagiarism is (including self-plagiarism and cyber plagiarism), how to avoid it and its consequences; why we cite and what can be cited; the two parts of referencing and the five elements to record; which disciplines use APA, MLA, Harvard and Chicago; the in-text and reference-list rules of APA, Harvard and MLA with worked examples.","noteType":"guide_topic","number":15,"mustKnow":[{"text":"Copyright, fair use and unfair use; what plagiarism is (including self-plagiarism and cyber plagiarism), how to avoid it and its consequences; why we cite and what can be cited; the two parts of referencing and the five elements to record; which disciplines use APA, MLA, Harvard and Chicago; the in-text and reference-list rules of APA, Harvard and MLA with worked examples."}],"lessons":[{"number":"15.1","title":"Copyright, fair use and unfair use","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Copyright (author's right):","bold":true},{"text":" the law that says you "},{"text":"cannot use any creative work without the permission of the owner","bold":true},{"text":". Copyrighted works are protected by "},{"text":"law","bold":true},{"text":". Anyone found guilty of breaking it is "},{"text":"liable to prosecution under the law","bold":true},{"text":"."}]},{"text":[{"text":"Fair use:","bold":true},{"text":" \"a judicial doctrine that refers to a use of copyrighted material that does not infringe or violate the exclusive rights of the copyright holder\". In plain terms: fair use allows copyrighted works to be used "},{"text":"without permission, under certain conditions","bold":true},{"text":", for "},{"text":"academic purposes, to a certain limit","bold":true},{"text":"."}]},{"text":[{"text":"Purposes allowed under fair use:","bold":true},{"text":" criticism, comment, news reporting, teaching and similar "},{"text":"non-commercial","bold":true},{"text":" purposes."}]},{"text":[{"text":"Works eligible for copyright","bold":true},{"text":" (World Intellectual Property Organization): books, music, paintings, sculpture, films, computer programs, databases, advertisements, maps, technical drawings."}]},{"text":[{"text":"Unfair use:","bold":true},{"text":" when a student or researcher "},{"text":"copies any copyrighted work indiscriminately, with or without acknowledgement","bold":true},{"text":". Fair use has a limit; crossing it is unfair use."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"As a student you rely on the documented knowledge of other people. Fair use makes that legal; acknowledgement keeps it honest."}]},{"text":[{"text":"Trap: fair use is for "},{"text":"academic","bold":true},{"text":" purposes, not business, publishing or commercial purposes."}]},{"text":[{"text":"Trap: the punishment for violating copyright law is "},{"text":"prosecution under the law","bold":true},{"text":", not \"jail the offender\"."}]},{"text":[{"text":"Trap: "},{"text":"complimentary cards","bold":true},{"text":" are not on the WIPO list; books, music and paintings are."}]},{"text":[{"text":"Paraphrasing correctly","bold":true},{"text":", with acknowledgement, is fair use. Copying indiscriminately is unfair use; using without acknowledgement is plagiarism."}]}]}]},{"number":"15.2","title":"Plagiarism and how to avoid it","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Plagiarism:","bold":true},{"text":" from the Latin "},{"text":"plagiarius","italic":true},{"text":", meaning "},{"text":"\"kidnapper\"","bold":true},{"text":". It is the "},{"text":"act of using copyrighted work without permission or acknowledging the source","bold":true},{"text":". In the academic environment it is called "},{"text":"\"academic theft\"","bold":true},{"text":" and "},{"text":"academic fraud","bold":true},{"text":". A scholar who does not acknowledge all quoted and borrowed ideas as he reads and writes is guilty of plagiarism."}]},{"text":[{"text":"It covers:","bold":true},{"text":" other people's copyrighted work, an organisation's copyrighted work, and even your "},{"text":"own","bold":true},{"text":" work."}]},{"text":[{"text":"Self-plagiarism:","bold":true},{"text":" copying from your "},{"text":"previous assignment for a new assignment without acknowledgement","bold":true},{"text":"."}]},{"text":[{"text":"Cyber plagiarism:","bold":true},{"text":" using the "},{"text":"Internet","bold":true},{"text":" to appropriate the ideas or expression of another."}]},{"text":[{"text":"Rules for avoiding plagiarism","bold":true},{"text":" (any copyrighted work used must be duly acknowledged):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Internal citation or footnotes must be done "},{"text":"properly according to the prescribed reference style","bold":true},{"text":"."}]},{"text":[{"text":"Internal citation or footnotes must be "},{"text":"listed in the reference list or bibliography","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Three things a student must learn","bold":true},{"text":" to avoid plagiarism:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"How to "},{"text":"manage time","bold":true},{"text":" to leave enough time for academic work."}]},{"text":[{"text":"How to "},{"text":"paraphrase correctly","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"skill of citation","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Paraphrase:","bold":true},{"text":" restating another writer's idea "},{"text":"in your own words","bold":true},{"text":". A "},{"text":"direct quotation","bold":true},{"text":" uses the author's "},{"text":"exact words","bold":true},{"text":" and is shown with "},{"text":"quotation marks","bold":true},{"text":". Both must be cited."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In one line: to avoid plagiarism, other people's ideas must be "},{"text":"paraphrased and cited","bold":true},{"text":", and "},{"text":"all used works must be cited","bold":true},{"text":". Consulting a lecturer, using the library or reading a manuscript are good habits but do not by themselves stop plagiarism."}]},{"text":[{"text":"Trap: copying from a lecturer's handout or from the internet without acknowledgement is ordinary plagiarism, not self-plagiarism. Self-plagiarism is only about "},{"text":"your own","bold":true},{"text":" earlier work."}]},{"text":[{"text":"Trap: paraphrasing is "},{"text":"not","bold":true},{"text":" quoting verbatim and "},{"text":"not","bold":true},{"text":" translating into another language."}]},{"text":[{"text":"When taking notes, mark a direct quotation with "},{"text":"quotation marks","bold":true},{"text":" so you can tell it from your paraphrase later. Underlining or capitals are not the recognised way."}]},{"text":[{"text":"Citation is a skill learnt for "},{"text":"academic purposes","bold":true},{"text":"."}]}]}]},{"number":"15.3","title":"Consequences of plagiarism and reasons for citing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5 consequences of plagiarism","bold":true},{"text":" (personal, professional and legal):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"academic reputation","bold":true},{"text":" of the offender could be destroyed."}]},{"text":[{"text":"Suspension or rustication","bold":true},{"text":" of the affected student."}]},{"text":[{"text":"Summary dismissal","bold":true},{"text":" of an affected member of staff."}]},{"text":[{"text":"It can affect the "},{"text":"reputation of the institution","bold":true},{"text":"."}]},{"text":[{"text":"It can lead to "},{"text":"prosecution","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"6 reasons for citing","bold":true},{"text":" published works:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Acknowledging people's works and ideas is essential for "},{"text":"moral and legal","bold":true},{"text":" reasons."}]},{"text":[{"text":"To "},{"text":"give credit","bold":true},{"text":" to work done by others."}]},{"text":[{"text":"To "},{"text":"give direction","bold":true},{"text":" to prospective researchers on resources to consult."}]},{"text":[{"text":"Verification","bold":true},{"text":" of citations in support of the author's arguments."}]},{"text":[{"text":"It "},{"text":"reveals the scope and quality","bold":true},{"text":" of the researcher's work."}]},{"text":[{"text":"Positions in a research work are "},{"text":"strengthened","bold":true},{"text":" when previous good sources are cited."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sources that can be cited:","bold":true},{"text":" secondary sources (books, encyclopaedias, dictionaries, scholarly journals, newspapers, magazines), electronic resources, institutional sources, websites, and "},{"text":"grey literature","bold":true},{"text":" (theses and dissertations, technical reports, conference proceedings)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: a student who plagiarises can be "},{"text":"dismissed from school","bold":true},{"text":" (suspension or rustication). \"Jailed\" is tempting because prosecution is possible, but the direct student penalty is removal from school."}]},{"text":[{"text":"A "},{"text":"quotation","bold":true},{"text":" is used in a research write-up to "},{"text":"support an argument","bold":true},{"text":" with the author's own words (also to disagree with an author, compare views or note existing research), not to show off writing skills or vocabulary."}]},{"text":[{"text":"Trap: "},{"text":"every","bold":true},{"text":" type of source listed can go in a reference list: books, chapters or articles in edited books, web pages, journal articles, newspapers, theses. None is excluded."}]}]}]},{"number":"15.4","title":"Referencing styles and what to record","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Referencing style:","bold":true},{"text":" the "},{"text":"various ways of acknowledging literature sources consulted","bold":true},{"text":" in a piece of writing; a "},{"text":"set of rules","bold":true},{"text":" telling a researcher how to acknowledge the thoughts, ideas and works of others in a particular way. A crucial part of successful academic writing."}]},{"text":[{"text":"Style manual:","bold":true},{"text":" each style has a manual that guides its acceptable manner of citation and referencing."}]},{"text":[{"text":"Referencing has 2 parts:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"In-text referencing (internal citation):","bold":true},{"text":" the brief citation in the "},{"text":"body of the manuscript","bold":true},{"text":", right where the idea or words are used."}]},{"text":[{"text":"Reference list (bibliography):","bold":true},{"text":" the full details, placed "},{"text":"at the end","bold":true},{"text":" of the assignment."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rule:","bold":true},{"text":" any citation given in-text must appear in the reference list, "},{"text":"and vice versa","bold":true},{"text":". "},{"text":"Only exception:","bold":true},{"text":" "},{"text":"personal communications","bold":true},{"text":" (conversations, lectures, email). They are non-print and are cited "},{"text":"in the body of the text only","bold":true},{"text":"."}]},{"text":[{"text":"5 key elements to record","bold":true},{"text":" for every source:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Author","bold":true},{"text":" (how authors are cited varies by style)."}]},{"text":[{"text":"Title","bold":true},{"text":" (book: the title on the title page; anthology: the work's name and the book's title; periodical: the "},{"text":"article","bold":true},{"text":" name, not the periodical name)."}]},{"text":[{"text":"Publication information","bold":true},{"text":" (book: publisher and place; periodical: journal or magazine name, volume and issue numbers; website: the organisation that created the content)."}]},{"text":[{"text":"Dates","bold":true},{"text":" (record all date information)."}]},{"text":[{"text":"Access","bold":true},{"text":" (Web or print; URL or "},{"text":"Digital Object Identifier, DOI","bold":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Styles and disciplines:","bold":true}]}]},{"type":"table","header":[[{"text":"Style"}],[{"text":"Full name"}],[{"text":"Used mostly by"}]],"rows":[[[{"text":"APA","bold":true}],[{"text":"American Psychological Association"}],[{"text":"Social sciences","bold":true},{"text":" (and sciences)"}]],[[{"text":"MLA","bold":true}],[{"text":"Modern Language Association"}],[{"text":"Composition","bold":true},{"text":" and language courses"}]],[[{"text":"Chicago","bold":true}],[{"text":"Chicago style"}],[{"text":"Humanities","bold":true}]],[[{"text":"Harvard","bold":true}],[{"text":"Harvard (author-date)"}],[{"text":"University students generally"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A full bibliography entry shows "},{"text":"all","bold":true},{"text":" of: author's name and year, title and place of publication, and publisher. A bibliography is arranged "},{"text":"alphabetically","bold":true},{"text":" and sits at the "},{"text":"end","bold":true},{"text":" of the work. A "},{"text":"keyword","bold":true},{"text":" never appears in a reference entry; author, title and page numbers do."}]},{"text":[{"text":"Trap: \"NLA\", \"ALA\" and \"MPA\" are "},{"text":"not","bold":true},{"text":" referencing styles. The four to know are "},{"text":"APA, MLA, Harvard, Chicago","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"In-text citation appears in the body of the manuscript\" is "},{"text":"true","bold":true},{"text":", fully, not partially."}]},{"text":[{"text":"You will likely use different styles during your degree; the style depends on your "},{"text":"discipline","bold":true},{"text":", so always follow the citation guide your lecturer assigns."}]}]}]},{"number":"15.5","title":"APA style","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"APA","bold":true},{"text":" is most commonly used in the "},{"text":"social sciences","bold":true},{"text":", popular worldwide, has changed often and (as taught here) is in its "},{"text":"6th edition","bold":true},{"text":"."}]},{"text":[{"text":"In-text:","bold":true},{"text":" author's "},{"text":"surname, year of publication","bold":true},{"text":", and "},{"text":"page number only for a direct quotation","bold":true},{"text":"."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Quotations of "},{"text":"less than 40 words","bold":true},{"text":": inside the text, in "},{"text":"double quotation marks \" \"","bold":true},{"text":"."}]},{"text":[{"text":"Quotations of "},{"text":"more than 40 words","bold":true},{"text":": a "},{"text":"block","bold":true},{"text":" on a new line, "},{"text":"indented 5 spaces","bold":true},{"text":" from the left margin, "},{"text":"no quotation marks","bold":true},{"text":"."}]},{"text":[{"text":"No page numbers","bold":true},{"text":" when you summarise or paraphrase."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reference list","bold":true},{"text":" rules:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Alphabetical order","bold":true},{"text":" by the author's "},{"text":"surname","bold":true},{"text":"."}]},{"text":[{"text":"No author:","bold":true},{"text":" use the "},{"text":"title","bold":true},{"text":" in the author's place."}]},{"text":[{"text":"Italics","bold":true},{"text":" for book and journal titles, websites and the "},{"text":"volume number","bold":true},{"text":" of a journal. The "},{"text":"issue number","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" in italics."}]},{"text":[{"text":"Lines after the first line of an entry are "},{"text":"indented 5 spaces","bold":true},{"text":" (hanging indent)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Authors:","bold":true},{"text":" 2 authors: use "},{"text":"&","bold":true},{"text":" inside parentheses and "},{"text":"and","bold":true},{"text":" in the sentence. 3 to 5 authors: all surnames the first time, then "},{"text":"et al.","bold":true},{"text":" 6 or more: "},{"text":"et al.","bold":true},{"text":" from the "},{"text":"first","bold":true},{"text":" in-text citation. In the reference list, with "},{"text":"more than 6 authors","bold":true},{"text":", list the first six and then write "},{"text":"et al.","bold":true},{"text":" in place of the rest. The exam's wording for this rule is: after the sixth author, do "},{"text":"not","bold":true},{"text":" list any more names; write "},{"text":"et al.","bold":true},{"text":" in their place."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"John states \"all of us need reassurance occasionally\" (2002, p. 77). "},{"text":"or","italic":true},{"text":" (John, 2002, p. 77)"}],[{"text":"John, P. (2002). "},{"text":"Mental health and mental illness","italic":true},{"text":" (7th ed.). Philadelphia: Lippincott."}]],[[{"text":"Journal article"}],[{"text":"Gregory and Verdouw (2005) explain… "},{"text":"or","italic":true},{"text":" (Gregory & Verdouw, 2005)"}],[{"text":"Gregory, S., & Verdouw, J. (2005). Therapeutic touch: Its application for residents in aged care. "},{"text":"Australian Nursing Journal, 12","italic":true},{"text":"(7), 23-25."}]],[[{"text":"Web document"}],[{"text":"(Diabetes WA, 2006)"}],[{"text":"Diabetes WA. (2006). "},{"text":"Gestational","italic":true},{"text":". Retrieved October 17, 2008, from http://diabeteswa.com.au/Default.aspx?f=pv&ctr=Default&mid=133&pid=433&page_id=436"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order: "},{"text":"Author. (Year). Title. Place: Publisher.","bold":true},{"text":" For a journal: "},{"text":"Author. (Year). Article title. ","bold":true},{"text":"Journal, volume","bold":true,"italic":true},{"text":"(issue), pages.","bold":true},{"text":" For a web document: "},{"text":"Author. (Year). ","bold":true},{"text":"Title","bold":true,"italic":true},{"text":". Retrieved [date], from [URL].","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Web document with no date:","bold":true},{"text":" write "},{"text":"(n.d.)","bold":true},{"text":" for the year and still give "},{"text":"both the retrieval date and the URL","bold":true},{"text":": WA Deaf Society. (n.d.). "},{"text":"You have rights!","italic":true},{"text":" Retrieved October 17, 2008, from http://www.wadeaf.org.au/index.php?id=45. In text: (WA Deaf Society, n.d.)."}]},{"text":[{"text":"Book without an author:","bold":true},{"text":" the "},{"text":"title","bold":true},{"text":" (its first few words, in italics, with capitals) takes the author's place in text: ("},{"text":"Nursing Procedures","italic":true},{"text":", 2002, p. 17). Reference list: "},{"text":"Nursing procedures made incredibly easy","italic":true},{"text":". (2002). Springhouse: Springhouse. Exam answer: a book without an author is cited in text using "},{"text":"the title","bold":true},{"text":"."}]},{"text":[{"text":"Journal article with no author:","bold":true},{"text":" the first few words of the article title in "},{"text":"double quotation marks","bold":true},{"text":", with the comma inside the closing mark: (\"Mobile Phones,\" 2007)."}]},{"text":[{"text":"Editor:","bold":true},{"text":" Macpherson, G. (Ed.). (1995). "},{"text":"Black's medical dictionary","italic":true},{"text":" (38th ed.). London: A & C Black."}]},{"text":[{"text":"Secondary source:","bold":true},{"text":" Palfrey (2000, as cited in Talbot & Verrinder, 2005, p. 79). Only the book you actually "},{"text":"read","bold":true},{"text":" (Talbot & Verrinder) goes in the reference list."}]},{"text":[{"text":"Several authors at once:","bold":true},{"text":" (Hamilton, 2005; Stevens, 2003), in "},{"text":"alphabetical order","bold":true},{"text":", separated by a "},{"text":"semicolon","bold":true},{"text":"."}]},{"text":[{"text":"Database article or eBook:","bold":true},{"text":" end the entry with \"Retrieved from\" and the database or eBook library name."}]},{"text":[{"text":"Newspaper:","bold":true},{"text":" O'Leary, C. (2005, June 11). Painkillers raise heart attack risk. "},{"text":"The West Australian","italic":true},{"text":", p. 1."}]},{"text":[{"text":"Trap: in the reference list the "},{"text":"volume","bold":true},{"text":" is italic and the "},{"text":"issue","bold":true},{"text":" is not: "},{"text":"12","italic":true},{"text":"(7)."}]}]}]},{"number":"15.6","title":"Harvard and MLA styles","mustKnow":[{"type":"paragraph","text":[{"text":"Harvard","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primarily used by "},{"text":"university students","bold":true},{"text":". An "},{"text":"author-date","bold":true},{"text":" style with two types of citation: "},{"text":"in-text citations","bold":true},{"text":" (when quoting or paraphrasing; a fragment of the full citation in the body) and the "},{"text":"reference list","bold":true},{"text":"."}]},{"text":[{"text":"In-text format: "},{"text":"(Author's Last Name Year, Page Number)","bold":true},{"text":" with "},{"text":"no comma","bold":true},{"text":" between name and year: "},{"text":"(Austen 1813, p. 64)","bold":true},{"text":". Initials have "},{"text":"no full stops","bold":true},{"text":" and the year has "},{"text":"no brackets","bold":true},{"text":" in the reference list. Article titles go in "},{"text":"single quotation marks","bold":true},{"text":"; use "},{"text":"vol.","bold":true},{"text":", "},{"text":"no.","bold":true},{"text":", "},{"text":"pp.","bold":true},{"text":"; publisher comes "},{"text":"before","bold":true},{"text":" place."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"(Holt 1997) "},{"text":"or","italic":true},{"text":" Holt (1997) wrote that…"}],[{"text":"Holt, DH 1997, "},{"text":"Management principles and practices","italic":true},{"text":", Prentice-Hall, Sydney."}]],[[{"text":"Journal article"}],[{"text":"(Conley & Galeson 1998)"}],[{"text":"Conley, TG & Galeson, DW 1998, 'Nativity and wealth in mid-nineteenth century cities', "},{"text":"Journal of Economic History","italic":true},{"text":", vol. 58, no. 2, pp. 468-493."}]],[[{"text":"Web page"}],[{"text":"(Weida & Stolley 2013)"}],[{"text":"Weida, S & Stolley, K 2013, "},{"text":"Developing strong thesis statements","italic":true},{"text":". Available from: https://owl.english.purdue.edu/owl/resource/588/1/. [13 October 2015]."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order: "},{"text":"Author, Initials Year, ","bold":true},{"text":"Title","bold":true,"italic":true},{"text":", Publisher, Place.","bold":true},{"text":" Electronic: add "},{"text":"Available from: [source]. [date accessed]","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"MLA","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A widely used system that helps an author acknowledge others' ideas, lets a reader "},{"text":"quickly locate","bold":true},{"text":" the source, and shows the "},{"text":"scope and depth","bold":true},{"text":" of the research."}]},{"text":[{"text":"In-text:","bold":true},{"text":" author's "},{"text":"last name and page number","bold":true},{"text":", "},{"text":"no year","bold":true},{"text":" and "},{"text":"no comma","bold":true},{"text":": "},{"text":"(McDonagh 80)","bold":true},{"text":". MLA is the style that "},{"text":"excludes the year","bold":true},{"text":" from the in-text citation."}]},{"text":[{"text":"Reference list order:","bold":true},{"text":" "},{"text":"Author's last name, first name. Title. Place of publication: publisher, year.","bold":true},{"text":" Full first names, not initials; the year comes "},{"text":"last","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"In another study (McDonagh 80)… "},{"text":"or","italic":true},{"text":" McDonagh has discussed (80)…"}],[{"text":"McDonagh, Sean. "},{"text":"Why Are We Deaf to the Cry of the Earth","italic":true},{"text":". Dublin: Veritas, 2001."}]],[[{"text":"Journal article"}],[{"text":"Mann (850) argues…"}],[{"text":"Mann, Susan. \"Myths of Asian Womanhood.\" "},{"text":"Journal of Asian Studies","italic":true},{"text":" 59.1 (2000): 835-62."}]],[[{"text":"Web page"}],[{"text":"Harris argues… "},{"text":"or","italic":true},{"text":" (Harris)"}],[{"text":"Harris, Robert. \"Evaluating Internet Research Sources.\" "},{"text":"VirtualSalt","italic":true},{"text":". 15 June 2008. Web. 27 April 2011."}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Harvard variants:","bold":true},{"text":" 2 or 3 authors: (McCarthy, William & Pascale 1997). More than 3: (Bond et al. 1996) in text, but "},{"text":"all names","bold":true},{"text":" in the reference list. No author: ("},{"text":"A history of Greece","italic":true},{"text":" 1994). Editor: Jones, MD (ed) 1998; two editors: (eds). Chapter in an edited book: Milkman, R 1998, 'The new American workplace: High road or low road?' in P Thompson & C Warhurst (eds), "},{"text":"Workplaces of the future","italic":true},{"text":", pp. 22-34, Macmillan Press, London. Edition: 10th edn. Newspaper: Devlin, M 2011, 'Keys found to success by the less privileged', "},{"text":"The Australian","italic":true},{"text":", 16 November, p. 32."}]},{"text":[{"text":"MLA variants:","bold":true},{"text":" two or three authors: McLean, Bethany and Peter Elkind. "},{"text":"The Smartest Guys in the Room","italic":true},{"text":". New York: Portfolio, 2004; in text, McLean and Elkind (122). More than three: McGeady, Thomas et al.; in text, McGeady et al. (155). Editor: Booth, David. Ed. "},{"text":"Rethinking Social Development","italic":true},{"text":". Essex: Longman, 1994. E-journal: add the database, \"Web.\" and the access date. Print newspaper: Gleeson, Jim. \"Towards Holistic Approach to School Discipline.\" "},{"text":"Irish Times","italic":true},{"text":" 10 February 2006, p. 16."}]},{"text":[{"text":"Quick comparison of the three in-text forms","bold":true},{"text":" for the same quotation on page 77 of a 2002 book by John: APA "},{"text":"(John, 2002, p. 77)","bold":true},{"text":"; Harvard "},{"text":"(John 2002, p. 77)","bold":true},{"text":"; MLA "},{"text":"(John 77)","bold":true},{"text":"."}]},{"text":[{"text":"Trap: APA and Harvard are both "},{"text":"author-date","bold":true},{"text":" styles; only MLA leaves the year out of the in-text citation. In APA the year is in brackets in the reference list, (2002); in Harvard it is bare, 1997; in MLA it comes at the very end."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Copyright law protects creative works; violation means prosecution. Fair use = academic, non-commercial use within a limit; unfair use = indiscriminate copying."}]},{"text":[{"text":"Plagiarism (Latin "},{"text":"plagiarius","italic":true},{"text":", \"kidnapper\") = using copyrighted work without permission or acknowledgement; \"academic theft\". Self-plagiarism = reusing your own old assignment unacknowledged; cyber plagiarism = via the Internet."}]},{"text":[{"text":"Avoid it: cite properly in the prescribed style, list every citation in the reference list; learn time management, correct paraphrasing and the skill of citation."}]},{"text":[{"text":"5 consequences: reputation, suspension/rustication, dismissal of staff, institutional reputation, prosecution. 6 reasons to cite."}]},{"text":[{"text":"Referencing = in-text citation (body) + reference list (end); every in-text entry appears in the list and vice versa, except personal communications."}]},{"text":[{"text":"Record 5 elements: author, title, publication information, dates, access (URL/DOI)."}]},{"text":[{"text":"APA: social sciences; MLA: composition; Chicago: humanities; Harvard: author-date, university students."}]},{"text":[{"text":"APA: (Surname, Year, p. x); quotes under 40 words in double quotation marks, over 40 as an indented block; list alphabetical, title replaces a missing author, italics for titles and volume but not issue; more than 6 authors: six then et al.; no-date web: (n.d.) plus retrieval date and URL."}]},{"text":[{"text":"Harvard: (Holt 1997, p. 64), no comma; MLA: (McDonagh 80), no year."}]}]}],"theory":{"itemId":"6857b502-3b17-5f52-85ec-0c9586bcd0f6","question":[{"type":"paragraph","text":[{"text":"You have consulted a book written by O. P. Maxwell and I. Daniel, published in 2017 by Oxford in England, titled "},{"text":"Introduction to Geodesy","italic":true},{"text":". Show how you would enter it in the reference list in (a) APA and (b) Harvard style, and explain what plagiarism is and two ways to avoid it."}]}]},"practice":[{"topic":"Style Manual: Citation and Referencing","named":false}]}},{"itemId":"3c5daf1d-ee3e-5f1e-84ea-4a8893bc45ec","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Speaking Skills I, the Sounds of English","body":"The organs of speech and what each does; the 44 phonemes of English (24 consonants, 20 vowels); how consonants are described by place, manner and voicing; how vowels are described by tongue height, tongue position, lip shape and length; the 12 pure vowels and 8 diphthongs; IPA symbols and how to transcribe short words.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The organs of speech and what each does; the 44 phonemes of English (24 consonants, 20 vowels); how consonants are described by place, manner and voicing; how vowels are described by tongue height, tongue position, lip shape and length; the 12 pure vowels and 8 diphthongs; IPA symbols and how to transcribe short words."}],"lessons":[{"number":"2.1","title":"The organs of speech","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organs of speech:","bold":true},{"text":" all the parts of the body involved in producing speech sounds, from the "},{"text":"lungs","bold":true},{"text":" to the "},{"text":"lips and nose","bold":true},{"text":". About half the body, from the head to the abdomen, is needed for speech. The organs modify the airstream from the lungs to produce different sounds."}]},{"text":[{"text":"Lungs:","bold":true},{"text":" sponge-like tissues housed within the "},{"text":"rib cage","bold":true},{"text":". They provide the airstream for speech. Air pushed out from the lungs is the "},{"text":"pulmonic egressive airstream","bold":true},{"text":", the airstream used for English sounds."}]},{"text":[{"text":"Trachea:","bold":true},{"text":" the windpipe; air passes up through it from the lungs."}]},{"text":[{"text":"Larynx:","bold":true},{"text":" the voice box; it contains the "},{"text":"vocal folds","bold":true},{"text":", two elastic tissues."}]},{"text":[{"text":"Glottis:","bold":true},{"text":" the aperture (opening) between the vocal folds. It decides voicing:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Glottis held "},{"text":"open","bold":true},{"text":", air passes without obstruction = "},{"text":"voiceless","bold":true},{"text":" sound."}]},{"text":[{"text":"Glottis relatively "},{"text":"closed","bold":true},{"text":" so the vocal folds "},{"text":"vibrate","bold":true},{"text":" under air pressure = "},{"text":"voiced","bold":true},{"text":" sound. Voicing is caused by the "},{"text":"vibration","bold":true},{"text":" of the vocal folds."}]}]}]},{"text":[{"text":"Vocal tract:","bold":true},{"text":" the air passages above the larynx. Two parts: the "},{"text":"oral cavity","bold":true},{"text":" (mouth and pharynx) and the "},{"text":"nasal cavity","bold":true},{"text":" (nose)."}]},{"text":[{"text":"Articulators:","bold":true},{"text":" parts of the vocal tract used to form sounds (tongue, lips and so on). "},{"text":"Articulation","bold":true},{"text":" is the contact of two or more speech organs."}]},{"text":[{"text":"Active articulators","bold":true},{"text":" move (lips, tongue, soft palate). "},{"text":"Passive articulators","bold":true},{"text":" are fixed (teeth, hard palate). The "},{"text":"tongue","bold":true},{"text":" is the most flexible of all the organs of speech."}]}]},{"type":"paragraph","text":[{"text":"Other articulators and their functions:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Soft palate (velum):","bold":true},{"text":" a muscular flap at the back of the roof of the mouth. Raised, it presses against the back wall of the pharynx and shuts off the nasal tract so no air leaves through the nose. Lowered, air escapes through the nose (nasal sounds)."}]},{"text":[{"text":"Hard palate:","bold":true},{"text":" a bony structure at the front part of the roof of the mouth."}]},{"text":[{"text":"Alveolar ridge:","bold":true},{"text":" the rough surface just behind the upper teeth; you can feel it with the tip of the tongue."}]},{"text":[{"text":"Upper and lower teeth.","bold":true}]},{"text":[{"text":"Lips:","bold":true},{"text":" brought together, rounded or spread; for some consonants the lower lip touches the upper teeth."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Parts of the tongue used in articulation: "},{"text":"tip (apex), blade, front, centre (middle), back, root and body","bold":true},{"text":"."}]},{"text":[{"text":"Locations: lungs in the chest (rib cage); larynx and vocal folds in the neck; pharynx above the larynx; velum, hard palate, alveolar ridge and teeth in the mouth; nasal cavity in the nose. The "},{"text":"uvula","bold":true},{"text":" hangs at the end of the soft palate."}]},{"text":[{"text":"Trap: the lungs are housed in the "},{"text":"rib cage","bold":true},{"text":", not the larynx. The larynx houses the vocal folds."}]},{"text":[{"text":"Trap: \"separation\" of the vocal folds gives voicelessness; "},{"text":"vibration","bold":true},{"text":" gives voicing."}]},{"text":[{"text":"Trap: pulmonic (lungs) is the English airstream; glottalic and velaric airstreams belong to some other languages, and \"laryngeal\" names a place, not an airstream."}]}]}]},{"number":"2.2","title":"Consonants","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Phoneme:","bold":true},{"text":" a sound a language selects as significant, one that can keep meanings apart (distinguish words). The speech organs can make unlimited sounds; each language uses only a few."}]},{"text":[{"text":"English has "},{"text":"44 phonemes: 20 vowels and 24 consonants","bold":true},{"text":". (26 is the number of letters, not sounds.)"}]},{"text":[{"text":"Consonant:","bold":true},{"text":" a speech sound produced when at least "},{"text":"two articulators come in contact","bold":true},{"text":", obstructing the flow of air from the larynx to the lips or nostrils."}]},{"text":[{"text":"Consonants are described by "},{"text":"three parameters","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Place of articulation:","bold":true},{"text":" where the contact takes place."}]},{"text":[{"text":"Manner of articulation:","bold":true},{"text":" the nature of the obstruction."}]},{"text":[{"text":"State of the glottis (voicing):","bold":true},{"text":" whether or not the vocal folds vibrate."}]}]}]}]},{"type":"paragraph","text":[{"text":"Places of articulation","bold":true},{"text":" (9):"}]},{"type":"table","header":[[{"text":"Place"}],[{"text":"Organs involved"}],[{"text":"Sounds"}]],"rows":[[[{"text":"Bilabial"}],[{"text":"the two lips"}],[{"text":"/p/ /b/ /m/ /w/"}]],[[{"text":"Labio-dental"}],[{"text":"lower lip and upper front teeth"}],[{"text":"/f/ /v/"}]],[[{"text":"Dental"}],[{"text":"tongue tip or blade and upper front teeth"}],[{"text":"/θ/ /ð/"}]],[[{"text":"Alveolar"}],[{"text":"tongue blade or tip and alveolar ridge"}],[{"text":"/t/ /d/ /s/ /z/ /n/ /l/"}]],[[{"text":"Post-alveolar"}],[{"text":"tongue raised towards the ridge but no contact"}],[{"text":"/r/"}]],[[{"text":"Palato-alveolar"}],[{"text":"blade on alveolar ridge plus front of tongue raised to the palate"}],[{"text":"/ʃ/ /ʒ/ /ʧ/ /ʤ/"}]],[[{"text":"Palatal"}],[{"text":"front of tongue and hard palate"}],[{"text":"/j/"}]],[[{"text":"Velar"}],[{"text":"back of tongue and soft palate"}],[{"text":"/k/ /g/ /ŋ/"}]],[[{"text":"Glottal"}],[{"text":"vocal folds, friction but no vibration"}],[{"text":"/h/"}]]]},{"type":"paragraph","text":[{"text":"Manners of articulation","bold":true},{"text":" (7 groups):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stops (plosives)","bold":true},{"text":" /p t k b d g/: total closure of the airflow in the mouth, then sudden release."}]},{"text":[{"text":"Fricatives","bold":true},{"text":" /f v θ ð s z ʃ ʒ h/: two articulators come close; air escapes through a small passage with friction or a hissing sound."}]},{"text":[{"text":"Affricates","bold":true},{"text":" /ʧ ʤ/: begin as plosives, end as fricatives (total closure, then gradual release). They combine the manner of stops and fricatives, which their two-part symbols show."}]},{"text":[{"text":"Nasals","bold":true},{"text":" /m n ŋ/: complete closure in the mouth, the soft palate is lowered, so air escapes through the nose."}]},{"text":[{"text":"Approximants","bold":true},{"text":" /r w j/: a narrowing, but the articulators are not close enough to produce audible friction. /w/ and /j/ are a sub-group called "},{"text":"glides","bold":true},{"text":"."}]},{"text":[{"text":"Lateral","bold":true},{"text":" /l/: the centre of the tongue touches the alveolar ridge and air passes along the sides of the mouth."}]},{"text":[{"text":"Liquids:","bold":true},{"text":" /l/ and /r/ together form the group called liquids."}]}]},{"type":"paragraph","text":[{"text":"Voicing:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Voiceless (9):","bold":true},{"text":" /p t k s f ʃ θ h ʧ/."}]},{"text":[{"text":"Voiced (15):","bold":true},{"text":" /b d g z v ʒ ð ʤ m n ŋ l r w j/."}]}]},{"type":"paragraph","text":[{"text":"The 24 English consonants","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Voicing"}],[{"text":"Place"}],[{"text":"Manner"}],[{"text":"Examples"}]],"rows":[[[{"text":"/p/"}],[{"text":"voiceless"}],[{"text":"bilabial"}],[{"text":"stop"}],[{"text":"pot, spot, happy, hiccough"}]],[[{"text":"/b/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"stop"}],[{"text":"bad, robust, rubber, number"}]],[[{"text":"/t/"}],[{"text":"voiceless"}],[{"text":"alveolar"}],[{"text":"stop"}],[{"text":"top, cot, Thomas, kitten"}]],[[{"text":"/d/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"stop"}],[{"text":"den, dead, golden, friend"}]],[[{"text":"/k/"}],[{"text":"voiceless"}],[{"text":"velar"}],[{"text":"stop"}],[{"text":"cough, kitchen, character, queue"}]],[[{"text":"/g/"}],[{"text":"voiced"}],[{"text":"velar"}],[{"text":"stop"}],[{"text":"goat, ghost, haggard, rag"}]],[[{"text":"/f/"}],[{"text":"voiceless"}],[{"text":"labio-dental"}],[{"text":"fricative"}],[{"text":"off, fan, cough, chauffeur"}]],[[{"text":"/v/"}],[{"text":"voiced"}],[{"text":"labio-dental"}],[{"text":"fricative"}],[{"text":"van, of, cave, love"}]],[[{"text":"/θ/"}],[{"text":"voiceless"}],[{"text":"dental"}],[{"text":"fricative"}],[{"text":"thing, mouth, healthy, thigh"}]],[[{"text":"/ð/"}],[{"text":"voiced"}],[{"text":"dental"}],[{"text":"fricative"}],[{"text":"this, mother, clothe, worthy"}]],[[{"text":"/s/"}],[{"text":"voiceless"}],[{"text":"alveolar"}],[{"text":"fricative"}],[{"text":"see, cease, silence, centre"}]],[[{"text":"/z/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"fricative"}],[{"text":"zoo, rise, rays, maize"}]],[[{"text":"/ʃ/"}],[{"text":"voiceless"}],[{"text":"palato-alveolar"}],[{"text":"fricative"}],[{"text":"shoe, chauffeur, social, issue"}]],[[{"text":"/ʒ/"}],[{"text":"voiced"}],[{"text":"palato-alveolar"}],[{"text":"fricative"}],[{"text":"genre, seizure, garage, casual"}]],[[{"text":"/h/"}],[{"text":"voiceless"}],[{"text":"glottal"}],[{"text":"fricative"}],[{"text":"he, behave, heaven, offhand"}]],[[{"text":"/ʧ/"}],[{"text":"voiceless"}],[{"text":"palato-alveolar"}],[{"text":"affricate"}],[{"text":"church, touch, chew, catch"}]],[[{"text":"/ʤ/"}],[{"text":"voiced"}],[{"text":"palato-alveolar"}],[{"text":"affricate"}],[{"text":"edge, judge, George, joy"}]],[[{"text":"/m/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"nasal"}],[{"text":"man, hammer, mansion"}]],[[{"text":"/n/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"nasal"}],[{"text":"new, manner, sun, sunny"}]],[[{"text":"/ŋ/"}],[{"text":"voiced"}],[{"text":"velar"}],[{"text":"nasal"}],[{"text":"song, singing, nothingness"}]],[[{"text":"/l/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"lateral"}],[{"text":"letter, swallow, little, lofty"}]],[[{"text":"/r/"}],[{"text":"voiced"}],[{"text":"post-alveolar"}],[{"text":"approximant"}],[{"text":"right, marry, rarity, reaction"}]],[[{"text":"/w/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"glide (approximant)"}],[{"text":"twist, sweater, dwindle, war"}]],[[{"text":"/j/"}],[{"text":"voiced"}],[{"text":"palatal"}],[{"text":"glide (approximant)"}],[{"text":"youth, stew, few, yam, suitor"}]]]},{"type":"paragraph","text":[{"text":"The consonant chart arranges the same facts by place (columns) and manner (rows):"}]},{"type":"table","header":[[{"text":"Manner"}],[{"text":"Bilabial"}],[{"text":"Labio-dental"}],[{"text":"Dental"}],[{"text":"Alveolar"}],[{"text":"Post-alveolar"}],[{"text":"Palato-alveolar"}],[{"text":"Palatal"}],[{"text":"Velar"}],[{"text":"Glottal"}]],"rows":[[[{"text":"Plosives (stops)"}],[{"text":"p b"}],[],[],[{"text":"t d"}],[],[],[],[{"text":"k g"}],[]],[[{"text":"Fricatives"}],[],[{"text":"f v"}],[{"text":"θ ð"}],[{"text":"s z"}],[],[{"text":"ʃ ʒ"}],[],[],[{"text":"h"}]],[[{"text":"Affricates"}],[],[],[],[],[],[{"text":"ʧ ʤ"}],[],[],[]],[[{"text":"Nasals"}],[{"text":"m"}],[],[],[{"text":"n"}],[],[],[],[{"text":"ŋ"}],[]],[[{"text":"Lateral"}],[],[],[],[{"text":"l"}],[],[],[],[],[]],[[{"text":"Approximants"}],[{"text":"w"}],[],[],[],[{"text":"r"}],[],[{"text":"j"}],[],[]]]},{"type":"paragraph","text":[{"text":"In each pair the voiceless sound is on the left and the voiced on the right."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The slants / / around a symbol mark it as a phoneme, not a letter of the alphabet."}]},{"text":[{"text":"The voiceless th symbol is sometimes printed as /ɵ/; the correct IPA symbol is /θ/ (thing, youth, mouth). In typed questions it may come out as an odd character; any voiceless th option still means /θ/. The voiced one is /ð/ (this, mother)."}]},{"text":[{"text":"Sounds that share a "},{"text":"place","bold":true},{"text":" but differ in manner: /s/, /t/ and /n/ are all "},{"text":"alveolar","bold":true},{"text":" (/s/ fricative, /t/ stop, /n/ nasal). Sounds that share a "},{"text":"manner","bold":true},{"text":" but differ in place: /p/, /t/ and /k/ are all voiceless stops."}]},{"text":[{"text":"Trap: /f/ is "},{"text":"not","bold":true},{"text":" bilabial; it is labio-dental. Bilabials are /p b m w/."}]},{"text":[{"text":"Trap: the "},{"text":"lateral","bold":true},{"text":" is /l/ only. /r/ is the post-alveolar approximant (it is sometimes classed as a trill); /w/ and /j/ are glides."}]},{"text":[{"text":"Trap: the only "},{"text":"glottal","bold":true},{"text":" sound is /h/. /k/ and /g/ are velar."}]},{"text":[{"text":"Feel voicing: fingertips on your larynx while saying a long \"zzzz\" (vibration) then \"ssss\" (none). Or block your ears and contrast [s z f v ʃ ʒ]; you hear buzzing in /z v ʒ/."}]},{"text":[{"text":"Nasals and stops both start with complete closure; in nasals the velum drops and air leaves through the nose."}]}]}]},{"number":"2.3","title":"Vowels: the 12 pure vowels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vowel:","bold":true},{"text":" a sound produced "},{"text":"without any obstruction","bold":true},{"text":" to the airflow from the larynx to the lips. The articulators do not come close; there is "},{"text":"no contact","bold":true},{"text":". The vocal folds vibrate, so "},{"text":"all vowels are voiced","bold":true},{"text":"."}]},{"text":[{"text":"20 vowels: 12 pure vowels (monophthongs) and 8 diphthongs.","bold":true}]},{"text":[{"text":"Because the articulators never meet, vowels are "},{"text":"not","bold":true},{"text":" described by place or manner. Four parameters are used instead:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Tongue height","bold":true},{"text":" (vertical distance from the tongue to the palate): "},{"text":"high (close)","bold":true},{"text":" vowels /i: ɪ u: ʊ/; "},{"text":"low (open)","bold":true},{"text":" vowels /æ ɒ ʌ ɑ:/; "},{"text":"mid","bold":true},{"text":" vowels /ɛ ɜ: ə ɔ:/ in between."}]},{"text":[{"text":"Tongue horizontality","bold":true},{"text":" (which part of the tongue is raised highest): "},{"text":"front","bold":true},{"text":" /i: ɪ ɛ æ/; "},{"text":"back","bold":true},{"text":" /u: ʊ ɒ ɔ: ɑ:/; "},{"text":"central","bold":true},{"text":" /ɜ: ə ʌ/."}]},{"text":[{"text":"Lip rounding","bold":true},{"text":" (the easiest to observe): "},{"text":"spread","bold":true},{"text":" /i: ɪ ɛ æ/; "},{"text":"neutral","bold":true},{"text":" /ʌ ɜ: ɑ: ə/; "},{"text":"rounded","bold":true},{"text":" /ɒ ʊ ɔ: u:/."}]},{"text":[{"text":"Duration:","bold":true},{"text":" long or short. Because context can lengthen or shorten a vowel, the terms "},{"text":"tense","bold":true},{"text":" (= long: /i: ɜ: ɔ: u: ɑ:/) and "},{"text":"lax","bold":true},{"text":" (= short: /ɪ ɛ æ ʌ ə ɒ ʊ/) are preferred, stressing quality over quantity."}]}]}]}]},{"type":"paragraph","text":[{"text":"The 12 pure vowels","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Description"}],[{"text":"Examples"}]],"rows":[[[{"text":"/i:/"}],[{"text":"high, front, tense"}],[{"text":"seat, seed, receive, be, machine, key"}]],[[{"text":"/ɪ/"}],[{"text":"mid-high, front, lax"}],[{"text":"rich, basket, symbol, village, ladies"}]],[[{"text":"/ɛ/"}],[{"text":"mid, front, lax"}],[{"text":"bed, breath, many"}]],[[{"text":"/æ/"}],[{"text":"low, front, lax"}],[{"text":"man, back, hat, badge, land"}]],[[{"text":"/ɑ:/"}],[{"text":"low, back, tense"}],[{"text":"card, heart, clerk, pass, half, laugh"}]],[[{"text":"/ɒ/"}],[{"text":"low, back, lax"}],[{"text":"cot, was, cough, knowledge, because"}]],[[{"text":"/ɔ:/"}],[{"text":"mid-low, back, tense"}],[{"text":"war, four, door, board, cause, water, jaw, ought, broad"}]],[[{"text":"/ʊ/"}],[{"text":"mid-high, back, lax"}],[{"text":"full, book, woman, could"}]],[[{"text":"/u:/"}],[{"text":"high, back, tense"}],[{"text":"rule, food, who, soup, chew, blue, juice"}]],[[{"text":"/ʌ/"}],[{"text":"mid-low, central, lax"}],[{"text":"cup, son, young, blood, does"}]],[[{"text":"/ɜ:/"}],[{"text":"mid-high, central, tense"}],[{"text":"serve, nurse, bird, myrrh, work, search, journey"}]],[[{"text":"/ə/"}],[{"text":"mid, central, lax"}],[{"text":"woman, oblige, figure, mother, possible, suppose, colour"}]]]},{"type":"paragraph","text":[{"text":"The vowel chart","bold":true},{"text":" (tongue height down the side, tongue position across):"}]},{"type":"table","header":[[],[{"text":"Front"}],[{"text":"Central"}],[{"text":"Back"}]],"rows":[[[{"text":"High (close)"}],[{"text":"i: ɪ"}],[],[{"text":"u: ʊ"}]],[[{"text":"Mid"}],[{"text":"ɛ"}],[{"text":"ɜ: ə"}],[{"text":"ɔ:"}]],[[{"text":"Low (open)"}],[{"text":"æ"}],[{"text":"ʌ"}],[{"text":"ɒ ɑ:"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"high\" vowels are also called "},{"text":"close","bold":true},{"text":" vowels (tongue close to the roof of the mouth); \"low\" vowels are "},{"text":"open","bold":true},{"text":". \"High\" does not mean long or rounded."}]},{"text":[{"text":"Real vowel distinctions: high/low, close/open, front/back, long/short (tense/lax), spread/neutral/rounded. \"Rounded/around\" is not a distinction, and \"pursed\" is not a lip position."}]},{"text":[{"text":"Trap: what is "},{"text":"not","bold":true},{"text":" involved in vowel articulation is "},{"text":"contact","bold":true},{"text":" between articulators. Tongue movement, lip shaping and length all are."}]},{"text":[{"text":"/u:/ is the high, back, tense vowel; /i:/ is high and tense but "},{"text":"front","bold":true},{"text":"; /ɜ:/ is central; /ɑ:/ is low and back. In typed questions /ɜ:/ sometimes appears as /3:/ and /ɑ:/ as /a:/."}]},{"text":[{"text":"Schwa /ə/ is the mid central lax vowel of unstressed syllables (the \"a\" in woman, the \"er\" in mother)."}]},{"text":[{"text":"The vowel of bed is written /ɛ/ here; some dictionaries write it /e/. Same sound."}]},{"text":[{"text":"Length pairs differ in quality too: /i:/ high front vs /ɪ/ mid-high front; /u:/ high back vs /ʊ/ mid-high back; /æ/ low front vs /ɑ:/ low back; /ɒ/ low back vs /ɔ:/ mid-low back."}]}]}]},{"number":"2.4","title":"Diphthongs and the spelling problem","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Diphthong:","bold":true},{"text":" a vowel sound that consists of a "},{"text":"movement or glide from one vowel position to another","bold":true},{"text":". A pure vowel is static in phonetic space. Diphthongs contain two elements but are "},{"text":"equal in length to the long pure vowels","bold":true},{"text":". Their symbols show both elements."}]},{"text":[{"text":"The 8 diphthongs are grouped by the "},{"text":"direction of the glide","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Closing (rising) diphthongs (5):","bold":true},{"text":" first element a mid or low vowel, second element a "},{"text":"high","bold":true},{"text":" vowel."}]},{"text":[{"text":"Centring diphthongs (3):","bold":true},{"text":" first element a front or back vowel, ending in the central vowel "},{"text":"schwa /ə/","bold":true},{"text":"."}]}]}]}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Symbol"}],[{"text":"Examples"}]],"rows":[[[{"text":"Closing"}],[{"text":"/eɪ/"}],[{"text":"gate, waist, play, eight, they, great"}]],[[{"text":"Closing"}],[{"text":"/aɪ/"}],[{"text":"time, pie, fly, type, light, dye, eye"}]],[[{"text":"Closing"}],[{"text":"/ɔɪ/"}],[{"text":"boil, boy, joint, joy, oyster, void, voyage"}]],[[{"text":"Closing"}],[{"text":"/əʊ/"}],[{"text":"so, hoe, own, toast, soul, go, pillow"}]],[[{"text":"Closing"}],[{"text":"/aʊ/"}],[{"text":"house, how, loud, crowd, shout, owl"}]],[[{"text":"Centring"}],[{"text":"/ɪə/"}],[{"text":"here, cheer, media, idea, museum"}]],[[{"text":"Centring"}],[{"text":"/ɛə/"}],[{"text":"care, chair, bear, parent, aerial"}]],[[{"text":"Centring"}],[{"text":"/ʊə/"}],[{"text":"poor, gourd, endure, during"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"No sound-letter correspondence:","bold":true},{"text":" the same letters can be pronounced in many ways. The letter \"a\" is /eɪ/ in gate, /ə/ in woman, /ɛ/ in many, /ɪ/ in village, /æ/ in man, /ɑ:/ in pass and /ɒ/ in was. Never use spelling as a guide to pronunciation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Closing diphthongs end in /ɪ/ (eɪ, aɪ, ɔɪ) or /ʊ/ (əʊ, aʊ). Centring diphthongs all end in /ə/."}]},{"text":[{"text":"The vowel classes you may meet are "},{"text":"monophthongs","bold":true},{"text":" (12), "},{"text":"diphthongs","bold":true},{"text":" (8) and "},{"text":"triphthongs","bold":true},{"text":" (a glide through three positions, e.g. fire /faɪə/, formed by a closing diphthong plus schwa). There is no such thing as a "},{"text":"quadriphthong","bold":true},{"text":"."}]},{"text":[{"text":"Trap: diphthongs are single vowel phonemes, not two vowels. \"Care\" /kɛə/ has two sounds in total, not three."}]},{"text":[{"text":"Trap: \"pure vowel\" = monophthong = one steady position; \"diphthong\" = glide. Tense does not mean diphthong: /i:/ is a long pure vowel."}]}]}]},{"number":"2.5","title":"Symbols and transcription","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The symbols for English sounds are adapted from the "},{"text":"International Phonetic Association's alphabet (IPA)","bold":true},{"text":", not from the 26 letters. They represent the "},{"text":"phonemes","bold":true},{"text":", the sounds that differentiate words."}]},{"text":[{"text":"Transcription:","bold":true},{"text":" capturing an utterance or word as a linear sequence of sound symbols. It mirrors pronunciation. "},{"text":"Orthography","bold":true},{"text":" is the conventional spelling system. Phonetics is to pronunciation what orthography is to spelling."}]},{"text":[{"text":"Minimal pairs","bold":true},{"text":" show phonemes at work: /kʌt/ cut, /kɒt/ cot, /kɑ:t/ cart, /kæt/ cat, /kɔ:t/ caught, /kɪt/ kit. Change one vowel phoneme and the word changes."}]},{"text":[{"text":"The "},{"text":"length mark (diacritic) ':'","bold":true},{"text":" after a vowel symbol shows the vowel is "},{"text":"long","bold":true},{"text":": /i:/ seat vs /ɪ/ sit; /u:/ fool vs /ʊ/ full; /ɔ:/ caught vs /ɒ/ cot; /ɑ:/ cart vs /æ/ cat. It does not change the perceptual quality of the long vowel; it marks length only."}]},{"text":[{"text":"Number of letters is not number of sounds:"}]}]},{"type":"table","header":[[{"text":"Word"}],[{"text":"Transcription"}],[{"text":"Sounds"}],[{"text":"Letters"}]],"rows":[[[{"text":"source"}],[{"text":"/sɔ:s/"}],[{"text":"3"}],[{"text":"6"}]],[[{"text":"fall"}],[{"text":"/fɔ:l/"}],[{"text":"3"}],[{"text":"4"}]],[[{"text":"shirt"}],[{"text":"/ʃɜ:t/"}],[{"text":"3"}],[{"text":"5"}]],[[{"text":"tough"}],[{"text":"/tʌf/"}],[{"text":"3"}],[{"text":"5"}]],[[{"text":"care"}],[{"text":"/kɛə/"}],[{"text":"2"}],[{"text":"4"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"How to transcribe a monosyllabic word: say it aloud, ignore the spelling, write one symbol per sound. Worked examples: youth /ju:θ/ (glide /j/ + long /u:/ + voiceless /θ/; never written with the letter \"y\", never with /ð/); mouth /maʊθ/; state /steɪt/; love /lʌv/; teach /ti:ʧ/; care /kɛə/; proud /praʊd/; street /stri:t/."}]},{"text":[{"text":"Counting sounds: cheap /ʧi:p/ has "},{"text":"3","bold":true},{"text":" sounds (ch is one affricate). Trust /trʌst/ has 5; frog /frɒg/ has 4; thoughts /θɔ:ts/ has 4 (th is one sound, \"ough\" is one vowel)."}]},{"text":[{"text":"Trap: silent letters (knowledge, half, queue) and double letters (hammer, rubber) get one symbol or none. /ŋ/ in \"song\" is one sound spelt with two letters."}]},{"text":[{"text":"Pronounce correctly to transcribe correctly, and use the transcription your dictionary gives for every entry."}]},{"text":[{"text":"Trap: APA and MLA are referencing styles; the symbol source is the "},{"text":"IPA","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organs of speech run from the lungs (in the rib cage) to the lips and nose; the pulmonic egressive airstream powers English speech."}]},{"text":[{"text":"Glottis open = voiceless; vocal folds vibrating = voiced. The tongue is the most flexible articulator."}]},{"text":[{"text":"Active articulators move (lips, tongue, velum); passive ones are fixed (teeth, hard palate)."}]},{"text":[{"text":"44 phonemes: 24 consonants, 20 vowels (12 pure vowels + 8 diphthongs)."}]},{"text":[{"text":"Consonants: place (9), manner (stops, fricatives, affricates, nasals, approximants/glides, lateral, liquids), voicing (9 voiceless, 15 voiced)."}]},{"text":[{"text":"Bilabial /p b m w/; labio-dental /f v/; dental /θ ð/; alveolar /t d s z n l/; glottal /h/; lateral /l/."}]},{"text":[{"text":"Vowels: no contact, all voiced; described by tongue height, tongue horizontality, lip rounding, length (tense/lax). High = close, low = open."}]},{"text":[{"text":"Diphthongs glide: 5 closing (eɪ aɪ ɔɪ əʊ aʊ), 3 centring (ɪə ɛə ʊə)."}]},{"text":[{"text":"Symbols come from the IPA; ':' marks length; spelling is not a guide to sound (source = 3 sounds, 6 letters)."}]}]}],"theory":{"itemId":"012bd206-3418-51b1-b543-d68a623244a6","question":[{"type":"paragraph","text":[{"text":"What is the basic difference between consonant and vowel articulation, and how is each type of sound described?"}]}]},"practice":[{"topic":"Speaking Skills I: Sounds of English","named":false}]}},{"itemId":"b78678e1-46de-5434-893b-dd9b4075cfab","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"Speaking Skills II: The Syllable, Stress and Intonation","body":"What a syllable is and its structure (onset, peak, coda; C0-3VC0-4); acceptable and unacceptable consonant clusters; stress, the four factors of prominence and the three levels of stress; predicting stress phonologically, syntactically and morphologically; intonation, its three functions and the uses of the four tunes.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a syllable is and its structure (onset, peak, coda; C0-3VC0-4); acceptable and unacceptable consonant clusters; stress, the four factors of prominence and the three levels of stress; predicting stress phonologically, syntactically and morphologically; intonation, its three functions and the uses of the four tunes."}],"lessons":[{"number":"3.1","title":"The English syllable","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentals:","bold":true},{"text":" the individual consonant and vowel sounds."}]},{"text":[{"text":"Suprasegmentals:","bold":true},{"text":" features that apply to units higher than the segments (the syllable and beyond), such as "},{"text":"stress","bold":true},{"text":" and "},{"text":"intonation","bold":true},{"text":". They are \"above the segments\" but still need them to function."}]},{"text":[{"text":"Syllable:","bold":true},{"text":" a distinct group of sounds that can be pronounced in one moment of uninterrupted breath. It usually consists of a vowel which may be preceded or followed by one or more consonants. Easy to identify, hard to define: "},{"text":"education","italic":true},{"text":" has four syllables."}]},{"text":[{"text":"Two phonetic theories of the syllable:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Chest Pulse Theory:","bold":true},{"text":" the syllable equals a single puff of air by the intercostal muscles of the chest cavity."}]},{"text":[{"text":"Prominence Theory:","bold":true},{"text":" the syllable is the most prominent, relatively loudest or most sonorous sound in a phonetic environment."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Phonological definition:","bold":true},{"text":" looks at how English phonemes combine. A syllable has three parts:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Onset:","bold":true},{"text":" all the consonants before the vowel (optional)."}]},{"text":[{"text":"Peak:","bold":true},{"text":" the vowel itself (compulsory; the only obligatory element)."}]},{"text":[{"text":"Coda:","bold":true},{"text":" all the consonants after the vowel (optional)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formula:","bold":true},{"text":" "},{"text":"C0-3VC0-4","bold":true},{"text":". Onset: 0 to "},{"text":"3","bold":true},{"text":" consonants (maximum 3 at the beginning). Peak: an obligatory vowel. Coda: 0 to "},{"text":"4","bold":true},{"text":" consonants (maximum 4 at the end)."}]},{"text":[{"text":"Consonant cluster:","bold":true},{"text":" two or more consonants at the beginning or end of a syllable with no vowel between them, e.g. "},{"text":"spray","italic":true},{"text":" /spreɪ/, "},{"text":"street","italic":true},{"text":" /striːt/, "},{"text":"tasks","italic":true},{"text":" /tɑːsks/, "},{"text":"bagged","italic":true},{"text":" /bægd/."}]},{"text":[{"text":"Open syllable:","bold":true},{"text":" no coda (ends in the vowel), e.g. "},{"text":"slow","italic":true},{"text":" /sləʊ/, "},{"text":"tea","italic":true},{"text":" /tiː/. A CV syllable is open."}]},{"text":[{"text":"Closed syllable:","bold":true},{"text":" has a coda (ends in a consonant), e.g. "},{"text":"slap","italic":true},{"text":" /slæp/, "},{"text":"tag","italic":true},{"text":" /tæg/."}]},{"text":[{"text":"Minimal syllable:","bold":true},{"text":" a single sound preceded and followed by silence, e.g. "},{"text":"are","italic":true},{"text":" /ɑː/, "},{"text":"or","italic":true},{"text":" /ɔː/, "},{"text":"err","italic":true},{"text":" /ɜː/; also /m/ (agreement) and /ʃ/ (asking for silence). The dominant single-sound syllable is the "},{"text":"schwa /ə/","bold":true},{"text":", an unstressed vowel, as in "},{"text":"about","italic":true},{"text":" /əbaʊt/, "},{"text":"amiss","italic":true},{"text":" /əmɪs/."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Phonetically, a syllable has a "},{"text":"centre","bold":true},{"text":" with little or no obstruction to airflow and relative loudness (the vowel), surrounded by greater obstruction and less loudness (the consonants)."}]},{"text":[{"text":"Syllable structures (C = consonant, V = vowel):"}]}]},{"type":"table","header":[[{"text":"Structure"}],[{"text":"Examples"}]],"rows":[[[{"text":"V"}],[{"text":"I","italic":true},{"text":" /aɪ/, "},{"text":"eye","italic":true},{"text":", "},{"text":"oh","italic":true},{"text":" /əʊ/"}]],[[{"text":"CV"}],[{"text":"boy","italic":true},{"text":" /bɔɪ/, "},{"text":"no","italic":true}]],[[{"text":"VC"}],[{"text":"in","italic":true},{"text":" /ɪn/, "},{"text":"up","italic":true}]],[[{"text":"CVC"}],[{"text":"pick","italic":true},{"text":" /pɪk/, "},{"text":"sock","italic":true}]],[[{"text":"CCV"}],[{"text":"slow","italic":true},{"text":" /sləʊ/, "},{"text":"glue","italic":true}]],[[{"text":"CCVC"}],[{"text":"prayed","italic":true},{"text":" /preɪd/, "},{"text":"glued","italic":true}]],[[{"text":"CCVCC"}],[{"text":"prank","italic":true},{"text":" /præŋk/, "},{"text":"cracked","italic":true},{"text":" /krækt/"}]],[[{"text":"CCCV"}],[{"text":"spree","italic":true},{"text":" /spriː/, "},{"text":"straw","italic":true}]],[[{"text":"CCCVC"}],[{"text":"stretch","italic":true},{"text":" /stretʃ/"}]],[[{"text":"CCCVCC"}],[{"text":"sprint","italic":true},{"text":" /sprɪnt/"}]],[[{"text":"CVCCCC"}],[{"text":"waltzed","italic":true},{"text":" /wɒltst/"}]],[[{"text":"CCCVCCCC"}],[{"text":"strengths","italic":true},{"text":" /streŋkθs/"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Count sounds, not letters: "},{"text":"eye","italic":true},{"text":" is one vowel sound (V); "},{"text":"cracked","italic":true},{"text":" ends in /kt/; "},{"text":"axe","italic":true},{"text":" is VCC; "},{"text":"through","italic":true},{"text":" is CCV."}]},{"text":[{"text":"Restrictions on onset and coda:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"/ŋ/ and /ʒ/ do "},{"text":"not","bold":true},{"text":" occur in the onset (so /ŋɔɪz/ is unacceptable)."}]},{"text":[{"text":"/h/, /r/, /w/ and /j/ do "},{"text":"not","bold":true},{"text":" occur in the coda (so /lɔːw/ and /hɑːsh/ are unacceptable)."}]},{"text":[{"text":"A "},{"text":"three-consonant onset","bold":true},{"text":" always has "},{"text":"/s/","bold":true},{"text":" as the first consonant, "},{"text":"/p/, /t/ or /k/","bold":true},{"text":" as the second, and "},{"text":"/l/, /r/, /w/ or /j/","bold":true},{"text":" as the third: "},{"text":"strike","italic":true},{"text":" /straɪk/, "},{"text":"square","italic":true},{"text":" /skweə/, "},{"text":"stew","italic":true},{"text":" /stjuː/, "},{"text":"sprite","italic":true},{"text":" /spraɪt/. Any other three-consonant onset is deviant and unacceptable in English."}]}]}]},{"text":[{"text":"Trap: the compulsory constituent of a syllable is the "},{"text":"vowel","bold":true},{"text":", not the consonant, the schwa or a pause. The maximum onset is "},{"text":"3","bold":true},{"text":", not 4; four consonants are possible only in the coda ("},{"text":"strengths","italic":true},{"text":")."}]}]}]},{"number":"3.2","title":"Stress, prominence and levels of stress","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress:","bold":true},{"text":" the relative force of articulation or degree of auditory prominence of one syllable over others in a polysyllabic word. The prominence of one syllable over the others in a word is a function of "},{"text":"stress","bold":true},{"text":"."}]},{"text":[{"text":"Stress can fall on any syllable. First (initial): "},{"text":"REAson, MESsage, JAnitor","italic":true},{"text":". Second: "},{"text":"anNOUNcer, inTENtion, creAtion","italic":true},{"text":". Final: "},{"text":"reCORD","italic":true},{"text":" (verb), "},{"text":"agGRIEVED, reLENT","italic":true},{"text":"."}]},{"text":[{"text":"Two perspectives on stress:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production:","bold":true},{"text":" the speaker uses more muscular energy for stressed syllables."}]},{"text":[{"text":"Perception:","bold":true},{"text":" all stressed syllables share one thing, "},{"text":"prominence","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Four factors of prominence:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Loudness:","bold":true},{"text":" stressed syllables are louder."}]},{"text":[{"text":"Length:","bold":true},{"text":" a longer syllable is heard as stressed."}]},{"text":[{"text":"Pitch:","bold":true},{"text":" the rise and fall of the tone of the voice, from the speed of vocal cord vibration. A syllable said on a noticeably higher pitch than its neighbours is heard as prominent."}]},{"text":[{"text":"(Vowel) quality:","bold":true},{"text":" a syllable with a "},{"text":"strong","bold":true},{"text":" vowel quality attracts stress."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Pitch","bold":true},{"text":" produces the "},{"text":"strongest effect","bold":true},{"text":" on stress placement of all four factors."}]},{"text":[{"text":"Strong vowels","bold":true},{"text":" (usually stressed): long vowels /iː, ɜː, ɑː, uː, ɔː/, diphthongs and triphthongs. "},{"text":"Weak vowels","bold":true},{"text":" (usually unstressed): /ə/, /ɪ/, /ʊ/. Examples: "},{"text":"aBOUT, rePORT, reUnion, FURther, anNOYance, TEAcher","italic":true},{"text":"."}]},{"text":[{"text":"Marking stress:","bold":true},{"text":" a mark (ˈ) at the beginning of the stressed syllable, or capital letters: "},{"text":"ˈrebel","italic":true},{"text":" REbel, "},{"text":"acˈcount","italic":true},{"text":" acCOUNT, "},{"text":"ocˈcasion","italic":true},{"text":" ocCAsion, "},{"text":"biˈnoculars","italic":true},{"text":" biNOculars."}]},{"text":[{"text":"Three levels of stress:","bold":true}]}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Mark"}],[{"text":"Description"}],[{"text":"Examples"}]],"rows":[[[{"text":"Primary"}],[{"text":"raised stroke (ˈ)"}],[{"text":"the strongest stress; results from pitch movement within a word"}],[{"text":"withDRAWal, condemNAtion, POSTman, toGEther, inviTAtion"}]],[[{"text":"Secondary"}],[{"text":"subscript (ˌ)"}],[{"text":"weaker than primary, stronger than unstressed"}],[{"text":"first syllable of "},{"text":"millionaire","italic":true},{"text":" /ˌmɪljəˈneə/, "},{"text":"cigarette","italic":true},{"text":" /ˌsɪgəˈret/; second syllable of "},{"text":"congratulation","italic":true},{"text":", "},{"text":"responsibility","italic":true}]],[[{"text":"Zero (unstressed)"}],[{"text":"none"}],[{"text":"no recognisable prominence; weak vowels"}],[{"text":"first syllable of "},{"text":"retain, opinion","italic":true},{"text":"; middle of "},{"text":"intimate, custody","italic":true},{"text":"; last of "},{"text":"flavour, mother","italic":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A word usually has "},{"text":"one","bold":true},{"text":" primary-stressed syllable; longer words may add one secondary-stressed syllable and several unstressed ones."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Syllable and stress:","bold":true},{"text":" (a) stressed/accented = said with greater energy or breath force; unstressed/unaccented = not; (b) a stressed syllable is more prominent than the sounds around it; (c) word stress operates only on words of "},{"text":"more than one syllable","bold":true},{"text":". The schwa /ə/ and the "},{"text":"syllabic consonants /l, m, n/","bold":true},{"text":" usually occur in unstressed syllables ("},{"text":"about, bottle, cotton","italic":true},{"text":")."}]},{"text":[{"text":"Diphthongs","bold":true},{"text":" do "},{"text":"not","bold":true},{"text":" usually occur in unstressed syllables; the schwa, short vowels and syllabic consonants do."}]},{"text":[{"text":"The four factors usually work together, but prominence can come from only one or two."}]},{"text":[{"text":"Trap: "},{"text":"voice","bold":true},{"text":" (vocal cord vibration that separates /b/ from /p/) is "},{"text":"not","bold":true},{"text":" a factor of prominence; the four are loudness, length, pitch, quality."}]},{"text":[{"text":"Trap: zero stress means "},{"text":"unstressed","bold":true},{"text":" syllables. There is no \"tertiary\" stress."}]},{"text":[{"text":"Secondary stress often sits on the syllable that carried primary stress "},{"text":"before","bold":true},{"text":" a stress-moving affix was added: "},{"text":"reˈsponsible","italic":true},{"text":" becomes /rɪˌspɒnsɪˈbɪlɪti/, correctly marked "},{"text":"responsiˈbility","bold":true},{"text":", not reˈsponsibility."}]},{"text":[{"text":"Sentence stress:","bold":true},{"text":" content words (nouns, main verbs, adjectives) are usually stressed; "},{"text":"function words","bold":true},{"text":" ("},{"text":"the, of, and, a","italic":true},{"text":") are usually "},{"text":"unstressed","bold":true},{"text":" in connected speech, never \"always stressed\"."}]}]}]},{"number":"3.3","title":"Predicting stress: phonological and syntactic criteria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"English stress is "},{"text":"free","bold":true},{"text":" (not fixed): it can fall on the first, second, third or last syllable, so many learners learn each word individually. Still, "},{"text":"three criteria","bold":true},{"text":" help predict it:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Phonological:","bold":true},{"text":" the number of syllables and their internal constitution (syllable structure, strong or weak vowels)."}]},{"text":[{"text":"Syntactic:","bold":true},{"text":" the word class (part of speech)."}]},{"text":[{"text":"Morphological:","bold":true},{"text":" the internal structure of the word (simple, compound or complex; affixes)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress is "},{"text":"not","bold":true},{"text":" predicted historically or semantically."}]},{"text":[{"text":"Phonological criterion:","bold":true},{"text":" weak syllables (/ə, ɪ, ʊ/) are unstressed; strong syllables (long vowels, diphthongs, triphthongs, consonant clusters) are stressed. With two strong vowels, the stronger gets primary stress, the other secondary. Six rules:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Disyllabic nouns:","bold":true},{"text":" short vowel in the final syllable → stress the "},{"text":"first","bold":true},{"text":" syllable: "},{"text":"TIcket, ASset, PREmise, FOcus, MOney, PIDgin, TODdler","italic":true},{"text":"."}]},{"text":[{"text":"Disyllabic nouns:","bold":true},{"text":" long vowel or diphthong in the final syllable → stress the "},{"text":"final","bold":true},{"text":" syllable: "},{"text":"esTATE, balLOON, canTEEN, maCHINE, rouTINE","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic nouns:","bold":true},{"text":" a final syllable with a short vowel or the diphthong /əʊ/ does "},{"text":"not","bold":true},{"text":" attract stress: "},{"text":"toMORrow, anNOUNCEment, reJOINder, acCEPTance","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic nouns:","bold":true},{"text":" a penultimate (second) syllable with a long vowel, a diphthong other than /əʊ/, or a consonant-cluster coda "},{"text":"is","bold":true},{"text":" stressed: "},{"text":"poTAto, syNOPsis, diSASter, torNAdo, arRIval, conJUNCtion","italic":true},{"text":"."}]},{"text":[{"text":"Disyllabic adjectives:","bold":true},{"text":" open final syllable or consonant-cluster coda on the final syllable → stress the "},{"text":"final","bold":true},{"text":" syllable: "},{"text":"seVERE, corRECT, diRECT, adHERE, aGHAST","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic verbs:","bold":true},{"text":" final syllable with a short vowel or a one-consonant coda → stress the "},{"text":"second (penultimate)","bold":true},{"text":" syllable: "},{"text":"enCOUNter, imPREGnate, maRAUder, conSIder, soLIcit","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Syntactic criterion:","bold":true},{"text":" in noun-verb (and noun-adjective) pairs, the "},{"text":"noun","bold":true},{"text":" takes stress on the "},{"text":"first","bold":true},{"text":" syllable and the "},{"text":"verb","bold":true},{"text":" on the "},{"text":"second","bold":true},{"text":":"}]}]},{"type":"table","header":[[{"text":"Noun (first syllable)"}],[{"text":"Verb/Adjective (second syllable)"}]],"rows":[[[{"text":"EXport"}],[{"text":"exPORT (V)"}]],[[{"text":"REcord"}],[{"text":"reCORD (V)"}]],[[{"text":"ABstract"}],[{"text":"absTRACT (V)"}]],[[{"text":"AUgust (N)"}],[{"text":"auGUST (Adj)"}]],[[{"text":"PREsent (Adj)"}],[{"text":"preSENT (V)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Exceptions","bold":true},{"text":" (same stress in more than one class): "},{"text":"PREsent","italic":true},{"text":" (N/Adj), "},{"text":"INterest","italic":true},{"text":" (N/V), "},{"text":"CHALlenge","italic":true},{"text":" (N/V), "},{"text":"miSTAKE","italic":true},{"text":" (N/V), "},{"text":"COMfort","italic":true},{"text":" (N/V), "},{"text":"reSPECT","italic":true},{"text":" (N/V), "},{"text":"HARvest","italic":true},{"text":" (N/V); "},{"text":"adVICE","italic":true},{"text":" (N), "},{"text":"adVISE","italic":true},{"text":" (V). So "},{"text":"challenge","italic":true},{"text":" is "},{"text":"CHALlenge/CHALlenge","bold":true},{"text":" as noun and verb."}]},{"text":[{"text":"Compound noun vs noun phrase:","bold":true},{"text":" a "},{"text":"compound noun","bold":true},{"text":" is stressed on the "},{"text":"first","bold":true},{"text":" element; a "},{"text":"noun phrase","bold":true},{"text":" is stressed on the "},{"text":"second (rightmost)","bold":true},{"text":" element."}]}]},{"type":"table","header":[[{"text":"Compound noun (first element)"}],[{"text":"Noun phrase (second element)"}]],"rows":[[[{"text":"GREENhouse (glass building for plants)"}],[{"text":"a green HOUSE (a house that is green)"}]],[[{"text":"BLACKbird"}],[{"text":"a black BIRD"}]],[[{"text":"ENGLISH-teacher"}],[{"text":"an English TEACHER"}]],[[{"text":"WHITE house"}],[{"text":"a white HOUSE"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A compound noun is a "},{"text":"single entity","bold":true},{"text":" whose meaning may or may not relate to its parts ("},{"text":"Facebook","italic":true},{"text":"). A noun phrase is "},{"text":"two separate syntactic elements","bold":true},{"text":", preceded by an article ("},{"text":"a/an","italic":true},{"text":"), in which the first element modifies the second."}]},{"text":[{"text":"Trap: \"based on syllable structure\" = "},{"text":"phonological","bold":true},{"text":"; \"based on word class\" = "},{"text":"syntactic","bold":true},{"text":"; \"based on internal structure/affixes\" = "},{"text":"morphological","bold":true},{"text":"."}]},{"text":[{"text":"Matching stress patterns","bold":true},{"text":" (a common exam task: pick the word with the same stress as the given one):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First syllable (like "},{"text":"ˈhumble","italic":true},{"text":"): "},{"text":"STANdard, SADdle, PUnish, MARvel, PREtext, COMpact","italic":true},{"text":" (noun), "},{"text":"ACtivist, COMpany","italic":true},{"text":"."}]},{"text":[{"text":"Second syllable (like "},{"text":"comˈplaint","italic":true},{"text":", "},{"text":"conˈcern","italic":true},{"text":"): "},{"text":"sucCESS, rePORT, reGRET, reTURN, comBINE","italic":true},{"text":" (verb), "},{"text":"ocCURrence, inSURance, amBItion, reACtion","italic":true},{"text":"; like "},{"text":"proˈfessor","italic":true},{"text":": "},{"text":"creAtor","italic":true},{"text":"."}]},{"text":[{"text":"Third syllable (like "},{"text":"indiˈcation","italic":true},{"text":"): "},{"text":"eduCAtion","italic":true},{"text":". Words ending in "},{"text":"-tion","bold":true},{"text":" stress the syllable "},{"text":"just before","bold":true},{"text":" the ending."}]},{"text":[{"text":"Like "},{"text":"ˈcapitalism","italic":true},{"text":": "},{"text":"REgionalism","italic":true},{"text":". The suffix "},{"text":"-ism","bold":true},{"text":" does not move stress, so the word keeps the stress of its base ("},{"text":"CApital, REgion","italic":true},{"text":")."}]}]}]}]}]},{"number":"3.4","title":"Predicting stress: the morphological criterion","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Words are morphologically "},{"text":"simple","bold":true},{"text":", "},{"text":"compound","bold":true},{"text":" or "},{"text":"complex","bold":true},{"text":"; each structure guides stress."}]},{"text":[{"text":"Simple words","bold":true},{"text":" (single-base morphemes): one meaningful unit, e.g. "},{"text":"table, glass, window, boy","italic":true},{"text":". Their stress is found phonologically or syntactically."}]},{"text":[{"text":"Compound words:","bold":true},{"text":" two words that can each exist independently. Written three ways:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"One word: "},{"text":"suitcase, blackboard, windscreen","italic":true},{"text":"."}]},{"text":[{"text":"Hyphenated: "},{"text":"fruit-cake, baby-sitter, mother-tongue","italic":true},{"text":"."}]},{"text":[{"text":"Two words with a space: "},{"text":"child care, credit card, income tax, heart attack","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Compound stress rules","bold":true},{"text":" (determined by word class):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Compound nouns","bold":true},{"text":" (especially noun + noun): stress on the "},{"text":"first","bold":true},{"text":" element: "},{"text":"ˈhandbag, ˈguest house, ˈtea-party, ˈbookshelf, ˈcity mall","italic":true},{"text":"."}]},{"text":[{"text":"Compound adjectives","bold":true},{"text":" with an adjectival first element and "},{"text":"-ed","bold":true},{"text":" at the end: stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"ill-ˈmannered, well-ˈbred, heavy-ˈhanded","italic":true},{"text":"."}]},{"text":[{"text":"Compounds whose first element is a "},{"text":"number","bold":true},{"text":" (ordinal or cardinal): stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"two-ˈseater, five-ˈstar, second-ˈhand","italic":true},{"text":"."}]},{"text":[{"text":"Compound adverbs","bold":true},{"text":" (adverbial element + noun): stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"up-ˈcountry, down-ˈstream, inside-ˈout","italic":true},{"text":"."}]},{"text":[{"text":"Compound verbs","bold":true},{"text":" with an adverbial first element: stress on the "},{"text":"final","bold":true},{"text":" element: "},{"text":"down-ˈsize, back-ˈpedal, ill-ˈtreat","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Complex words:","bold":true},{"text":" two or more elements, formed by "},{"text":"affixation","bold":true},{"text":", e.g. "},{"text":"boys, unrepentant, disloyal, international, endearment","italic":true},{"text":". "},{"text":"Prefixes","bold":true},{"text":" go before the base ("},{"text":"un-","italic":true},{"text":" in "},{"text":"unpleasant","italic":true},{"text":"); "},{"text":"suffixes","bold":true},{"text":" go after ("},{"text":"-ness","italic":true},{"text":" in "},{"text":"fairness","italic":true},{"text":")."}]},{"text":[{"text":"Three types of affix by effect on stress:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stress-bearing affixes:","bold":true},{"text":" the affix itself carries primary stress: "},{"text":"semi-","italic":true},{"text":" ("},{"text":"ˈsemicircle","italic":true},{"text":"), "},{"text":"-eer","italic":true},{"text":" ("},{"text":"engiˈneer","italic":true},{"text":"), "},{"text":"-aire","italic":true},{"text":" ("},{"text":"millioˈnaire","italic":true},{"text":"), "},{"text":"-ette","italic":true},{"text":" ("},{"text":"cigaˈrette","italic":true},{"text":")."}]},{"text":[{"text":"Stress-neutral affixes:","bold":true},{"text":" the word keeps its original stress: "},{"text":"un-","italic":true},{"text":" and "},{"text":"-ing","italic":true},{"text":" ("},{"text":"ˈpleasant","italic":true},{"text":" / "},{"text":"unˈpleasant","italic":true},{"text":"; "},{"text":"ˈmarket","italic":true},{"text":" / "},{"text":"ˈmarketing","italic":true},{"text":")."}]},{"text":[{"text":"Stress-moving affixes:","bold":true},{"text":" stress stays on the stem but shifts to a different syllable: "},{"text":"-ic","italic":true},{"text":" and "},{"text":"-ity","italic":true},{"text":" ("},{"text":"ˈmagnet","italic":true},{"text":" / "},{"text":"magˈnetic","italic":true},{"text":"; "},{"text":"ˈinfidel","italic":true},{"text":" / "},{"text":"infiˈdelity","italic":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"stress-conserving\" is "},{"text":"not","bold":true},{"text":" a type of affix. The three types are bearing, neutral and moving."}]},{"text":[{"text":"-ism","italic":true},{"text":" behaves as stress-neutral ("},{"text":"CApitalism, REgionalism","italic":true},{"text":"); "},{"text":"-ity","italic":true},{"text":" and "},{"text":"-tion","italic":true},{"text":" move stress to the syllable before them ("},{"text":"responsiˈbility","italic":true},{"text":", "},{"text":"indiˈcation","italic":true},{"text":")."}]},{"text":[{"text":"Compound nouns are the only compound type stressed on the first element; adjective, number, adverb and verb compounds all stress the "},{"text":"second","bold":true},{"text":" element."}]}]}]},{"number":"3.5","title":"Intonation and the four tunes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Intonation:","bold":true},{"text":" the use of the "},{"text":"pitch of the voice","bold":true},{"text":" to convey meaning or syntactic information; the distinctive use of patterns of pitch or melody in an utterance; the rise and fall of the tone of the voice. Intonation in English is a matter of "},{"text":"sentence stress","bold":true},{"text":". It is the melody of speech."}]},{"text":[{"text":"No language is spoken in a monotone. "},{"text":"Tone:","bold":true},{"text":" the overall behaviour of pitch in speech."}]},{"text":[{"text":"Pitch changes are linguistic only when they affect meaning (the pitch changes of someone speaking while running are not): "},{"text":"You are travelling today","italic":true},{"text":" on a "},{"text":"falling","bold":true},{"text":" tone = statement; on a "},{"text":"rising","bold":true},{"text":" tone = question or doubt/surprise. Intonation in speech equals "},{"text":"punctuation","bold":true},{"text":" in writing."}]},{"text":[{"text":"Three functions of intonation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Grammatical:","bold":true},{"text":" shows the communicative function of a sentence (statement, question, exclamation)."}]},{"text":[{"text":"Attitudinal:","bold":true},{"text":" betrays the speaker's emotion or attitude (disinterest, sarcasm, boredom; anger, excitement, impatience)."}]},{"text":[{"text":"Discourse:","bold":true},{"text":" guides turn-taking in conversation (end-of-utterance patterns differ from mid-utterance ones), and points to the focus and implied meanings. "},{"text":"Yes/no","italic":true},{"text":" on a falling tone = definiteness or finality; on a rising tone = interest or continuity."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Four intonation tunes:","bold":true},{"text":" falling, rising, falling-rising, rising-falling."}]},{"text":[{"text":"Falling tune","bold":true},{"text":", five uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Declarative statements:","bold":true},{"text":" "},{"text":"We shall travel tomorrow.","italic":true}]},{"text":[{"text":"Imperatives","bold":true},{"text":" (commands, instructions, advice): "},{"text":"Look at the blackboard.","italic":true}]},{"text":[{"text":"Wh-questions:","bold":true},{"text":" "},{"text":"What did you see? Where is your sister?","italic":true}]},{"text":[{"text":"Tag questions seeking confirmation:","bold":true},{"text":" "},{"text":"It is true, isn't it?","italic":true}]},{"text":[{"text":"Exclamations:","bold":true},{"text":" "},{"text":"How brilliant he is! What a horrible accident!","italic":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rising tune","bold":true},{"text":", four uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Polar (yes/no) questions:","bold":true},{"text":" "},{"text":"Do you know his house? Can we go now?","italic":true}]},{"text":[{"text":"Polite requests","bold":true},{"text":" (interrogative or imperative form): "},{"text":"Kindly shut the door. Could you lend me some cash?","italic":true}]},{"text":[{"text":"Requests for repetition","bold":true},{"text":" (wh-question or echo question): "},{"text":"What did she say? Bisi has travelled?","italic":true}]},{"text":[{"text":"Tag questions seeking information:","bold":true},{"text":" "},{"text":"He has left, hasn't he?","italic":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Falling-rising tune","bold":true},{"text":", two uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Counting or listing:","bold":true},{"text":" each item takes a fall-rise until the last, which falls: "},{"text":"We can invite students, lawyers, soldiers, politicians and workers too.","italic":true}]},{"text":[{"text":"Sentence modifiers (adverbials):","bold":true},{"text":" "},{"text":"Fortunately, it did not rain. Clearly, she cannot drive well.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: wh-questions take a "},{"text":"falling","bold":true},{"text":" tune; yes/no questions take a "},{"text":"rising","bold":true},{"text":" tune. A wh-question rises only when asking for repetition."}]},{"text":[{"text":"Trap: tag questions take "},{"text":"both","bold":true},{"text":" tunes. Falling = seeking confirmation (you already believe it). Rising = seeking information (you really do not know)."}]},{"text":[{"text":"Trap: \"statement, question or exclamation\" = "},{"text":"grammatical","bold":true},{"text":" function; \"emotion or attitude\" = "},{"text":"attitudinal","bold":true},{"text":"; \"turn-taking\" = "},{"text":"discourse","bold":true},{"text":". \"Accentual\" refers to stress placement, not sentence type."}]},{"text":[{"text":"Trap: stress is prominence of a syllable within a "},{"text":"word","bold":true},{"text":"; intonation (not \"rhythm\") is pitch movement over an "},{"text":"utterance","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"rising-falling","bold":true},{"text":" tune is the fourth tune; it is typically used to show strong feeling, such as approval, disapproval or surprise. Declaratives take the falling tune, not rise-fall."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suprasegmentals = stress and intonation, above the segments (consonants and vowels)."}]},{"text":[{"text":"Syllable = onset (optional) + peak (compulsory vowel) + coda (optional): "},{"text":"C0-3VC0-4","bold":true},{"text":"."}]},{"text":[{"text":"Three-consonant onset = /s/ + /p, t, k/ + /l, r, w, j/. /ŋ, ʒ/ never start; /h, r, w, j/ never end a syllable."}]},{"text":[{"text":"Open syllable = no coda (CV); closed = has coda. Minimal syllable = one sound."}]},{"text":[{"text":"Stress = prominence of one syllable; four factors: loudness, length, pitch (strongest), quality. Not voice."}]},{"text":[{"text":"Three levels: primary (ˈ), secondary (ˌ, subscript), zero (unstressed). One primary stress per word."}]},{"text":[{"text":"English stress is free; predict it phonologically, syntactically, morphologically."}]},{"text":[{"text":"Noun = first syllable, verb = second (EXport/exPORT); exception: CHALlenge (N/V). Compound noun = first element; noun phrase = second."}]},{"text":[{"text":"Affixes: stress-bearing (-eer, -aire, -ette), stress-neutral (un-, -ing, -ism), stress-moving (-ic, -ity)."}]},{"text":[{"text":"Intonation = pitch for meaning; functions: grammatical, attitudinal, discourse. Falling: statements, commands, wh-questions, confirming tags, exclamations. Rising: yes/no questions, polite requests, repetition, information tags. Fall-rise: lists, adverbials."}]}]}],"theory":{"itemId":"ef210d0b-f9ba-5347-8a99-74e606af4cb3","question":[{"type":"paragraph","text":[{"text":"Stress is perceptually marked by four main features. List them and explain how each indicates stress."}]}]},"practice":[{"topic":"Speaking Skills II: Syllable, Stress, Intonation","named":false}]}},{"itemId":"7bcafa95-dda2-5e3e-8185-f144c7a52c88","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Reading Skills I: Strategies for Effective Reading","body":"What reading is and the 4 misconceptions; the 3 types of reading (skimming, scanning, study reading) and LEARNER; the 8 bad reading habits; the 3 strategies for efficient reading (preview, read with intent, review) and the steps under each.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What reading is and the 4 misconceptions; the 3 types of reading (skimming, scanning, study reading) and LEARNER; the 8 bad reading habits; the 3 strategies for efficient reading (preview, read with intent, review) and the steps under each."}],"lessons":[{"number":"4.1","title":"What reading is; reading efficiency and misconceptions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading:","bold":true},{"text":" the process of translating written or printed symbols and letters into words and sentences which convey meaning to the individual. The main purpose of reading is to "},{"text":"comprehend","bold":true},{"text":" a written material."}]},{"text":[{"text":"Reading involves "},{"text":"both the eyes and the brain","bold":true},{"text":". The "},{"text":"eyes","bold":true},{"text":" do the physical task of linking the letters and symbols to know what the author "},{"text":"says","bold":true},{"text":"; the "},{"text":"brain","bold":true},{"text":" interprets what the author "},{"text":"means","bold":true},{"text":". Essential to reading: written or printed signs, the eyes, the brain. "},{"text":"Not","bold":true},{"text":" essential: the articulatory (vocal) system."}]},{"text":[{"text":"Reading is a "},{"text":"developmental process","bold":true},{"text":" which can never be completely mastered. Many students get no instruction in reading and so develop unhealthy habits."}]},{"text":[{"text":"Reading efficiency:","bold":true},{"text":" the acquisition of proper reading skills which facilitate the efficient physical and mental processing of written materials; the relationship between the physical aspects of reading and reading speed, which influences comprehension."}]},{"text":[{"text":"Target speed: about "},{"text":"600 words per minute","bold":true},{"text":" by the end of your programme. Efficiency improves only through "},{"text":"constant reading practice","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 misconceptions about reading","bold":true},{"text":" (and the truth):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"You need to read everything.","bold":true},{"text":" No: read selectively, depending on your purpose, the nature of the material and your familiarity with it."}]},{"text":[{"text":"Everything on a page is equally important.","bold":true},{"text":" No: each text mixes important and not-so-important information; sort and evaluate what you need."}]},{"text":[{"text":"Everything can be read the same way.","bold":true},{"text":" No: purpose determines what you read, how fast or carefully, what you attend to and what you skip. Vary your technique to suit purpose and material."}]},{"text":[{"text":"Everything we read is \"true\".","bold":true},{"text":" No: read with a critical, questioning eye and some scepticism. Consider the "},{"text":"authority of the author","bold":true},{"text":" and the "},{"text":"author's purpose","bold":true},{"text":"; distinguish "},{"text":"facts","bold":true},{"text":" from "},{"text":"opinions, value judgements and generalisations","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"What determines how (and how fast) you read:","bold":true},{"text":" the "},{"text":"nature","bold":true},{"text":" of the material, your "},{"text":"purpose","bold":true},{"text":", and your "},{"text":"familiarity","bold":true},{"text":" with the topic. A newspaper is read once; a study text is studied repeatedly. The "},{"text":"author","bold":true},{"text":" and the "},{"text":"publisher","bold":true},{"text":" do not prescribe how you read. Trap: \"the author's prescription\" is the odd one out among factors deciding reading speed (the reader, who varies speed to suit the material, does count as a factor). Trap: asked what determines "},{"text":"how a material is read","bold":true},{"text":", choose "},{"text":"its nature","bold":true},{"text":" (newspaper once, study text repeatedly), not the reader, author or publisher."}]},{"text":[{"text":"A passage in "},{"text":"technical or difficult language","bold":true},{"text":" is best read at a "},{"text":"slow pace","bold":true},{"text":"."}]},{"text":[{"text":"Benefits of reading:","bold":true},{"text":" it enlarges your vocabulary and improves your listening, speaking and writing skills. It does "},{"text":"not","bold":true},{"text":" diminish your speech ability."}]},{"text":[{"text":"Critical reading (misconception 4) also helps in examinations that ask you to "},{"text":"apply, connect and evaluate","bold":true},{"text":" ideas."}]}]}]},{"number":"4.2","title":"Types of reading: skimming, scanning, study reading","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stages of reading development:","bold":true},{"text":" early primary school stresses word recognition and meaning: "},{"text":"\"learning to read\"","bold":true},{"text":". From mid-primary and junior secondary school the emphasis shifts to silent reading for comprehension: "},{"text":"\"reading to learn\"","bold":true},{"text":". In secondary school and higher institutions reading is used to learn facts and concepts and acquire new vocabulary and information."}]},{"text":[{"text":"Different "},{"text":"purposes","bold":true},{"text":" give different types of reading. Three types:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Skimming:","bold":true},{"text":" looking at the content quickly to get the "},{"text":"overall (general) idea","bold":true},{"text":". You look at the title and author, the blurb at the back (or the abstract of an article), the table of contents, preface and foreword, then the subtitles, tables, charts and the topic sentences of each paragraph, without bothering with details. You are "},{"text":"not","bold":true},{"text":" looking for specific information."}]},{"text":[{"text":"Scanning:","bold":true},{"text":" running the eyes quickly through the material in search of a "},{"text":"particular piece of specific information","bold":true},{"text":", or to see whether the material is relevant to your purpose. You ignore irrelevant details. You locate the section in the "},{"text":"table of contents or index","bold":true},{"text":", then read the indicated pages. In scanning, the "},{"text":"index","bold":true},{"text":" can be very important."}]},{"text":[{"text":"Study reading:","bold":true},{"text":" an "},{"text":"intensive","bold":true},{"text":" kind of reading: a thorough examination of the material and a critical analysis of the issues raised; reading to gather information that will translate to "},{"text":"knowledge","bold":true},{"text":". Guided by the acronym "},{"text":"LEARNER","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"LEARNER","bold":true},{"text":" (for productive study reading):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"L","bold":true},{"text":"ay out the purpose for reading."}]},{"text":[{"text":"E","bold":true},{"text":"xamine all parts of the material."}]},{"text":[{"text":"A","bold":true},{"text":"sk questions about each subheading during the study."}]},{"text":[{"text":"R","bold":true},{"text":"ead all materials on the topic to find answers to the set-out questions."}]},{"text":[{"text":"N","bold":true},{"text":"ote names, places, dates, events, directions and labels while reading."}]},{"text":[{"text":"E","bold":true},{"text":"ase away from studying one subject before starting another."}]},{"text":[{"text":"R","bold":true},{"text":"eview notes and materials before a test or a discussion."}]}]}],"explainMore":[{"type":"table","header":[[],[{"text":"Skimming"}],[{"text":"Scanning"}]],"rows":[[[{"text":"Goal"}],[{"text":"General idea of the whole"}],[{"text":"One specific piece of information"}]],[[{"text":"Tool"}],[{"text":"Title, blurb, contents, headings, topic sentences"}],[{"text":"Index or contents, then the pages"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"have a general idea of the topic\" = skimming; \"get specific information\" = scanning. \"Looking for specific details\" is the one thing skimming does "},{"text":"not","bold":true},{"text":" involve."}]},{"text":[{"text":"Trap: \"spinning\" and \"exploring\" are "},{"text":"not","bold":true},{"text":" types of reading."}]},{"text":[{"text":"LEARNER is a "},{"text":"mnemonic","bold":true},{"text":"; REARER, REALER and NEARER are distractors."}]}]}]},{"number":"4.3","title":"Reading deficiencies (bad reading habits)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading "},{"text":"speed","bold":true},{"text":" is directly related to "},{"text":"comprehension","bold":true},{"text":". Bad habits lead to slow reading with poor comprehension. Reading should involve no other muscles except those of the eyes."}]}]},{"type":"paragraph","text":[{"text":"8 bad reading habits:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Word-by-word reading:","bold":true},{"text":" emphasises word recognition and sounding out every word; slow and laborious."}]},{"text":[{"text":"Vocalisation:","bold":true},{"text":" moving the lips or any other vocal apparatus (tongue, throat, vocal cords) while reading; whispering to yourself, with or without audible sound. Comes from an emphasis on word recognition; reduces rate and comprehension."}]},{"text":[{"text":"Sub-vocalisation:","bold":true},{"text":" pronouncing the words in your mind with "},{"text":"no part of the vocal apparatus moving","bold":true},{"text":". Hinders comprehension. Written words represent both a sound system and an idea system; you need not go through the sounds to reach the ideas."}]},{"text":[{"text":"Moving the head from side to side:","bold":true},{"text":" stops the eyes focusing fully; divides attention; unnecessary and wasteful."}]},{"text":[{"text":"Finger-pointing:","bold":true},{"text":" pointing with a finger or any object to the words. The eyes naturally take in whole phrases and sentences; pointing forces them word by word."}]},{"text":[{"text":"Regression:","bold":true},{"text":" glancing "},{"text":"back","bold":true},{"text":" to re-read words, phrases and sentences. Usually caused by "},{"text":"lack of concentration","bold":true},{"text":"; corrected by concentrating. Some regression is sometimes necessary, but "},{"text":"excessive","bold":true},{"text":" regression hinders comprehension."}]},{"text":[{"text":"Short span of recognition:","bold":true},{"text":" "},{"text":"span of recognition","bold":true},{"text":" = the number of words you can recognise while your eyes are fixed at one point. A poor reader recognises one or two words per glance; a good reader has a "},{"text":"wide","bold":true},{"text":" span and takes in several words."}]},{"text":[{"text":"Erratic eye movement:","bold":true},{"text":" eyes moving across the line haphazardly instead of rhythmically. Good eyes move from the "},{"text":"middle of one phrase to the middle of the next","bold":true},{"text":", in tune with the syntactic arrangement of the line."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Habits 7 and 8 (narrow span and erratic movement) need "},{"text":"continual practice over time","bold":true},{"text":" to correct."}]},{"text":[{"text":"Eye movement terms:","bold":true},{"text":" the eyes do not glide along a line; they move in little jumps and stops. The forward jumps are "},{"text":"saccadic","bold":true},{"text":" movements; the backward glances are "},{"text":"regressive","bold":true},{"text":" movements. Both are "},{"text":"natural","bold":true},{"text":" reading movements; regression is a deficiency only when excessive. Trap: velaric, glottalic and pulmonic are airstream mechanisms in speech, not eye movements."}]},{"text":[{"text":"Trap: "},{"text":"a wide span of recognition","bold":true},{"text":" marks a "},{"text":"good","bold":true},{"text":" reader; it is not a bad habit."}]},{"text":[{"text":"Trap: the backward movement of the eyes is "},{"text":"regression","bold":true},{"text":", not \"backwarding\"."}]}]}]},{"number":"4.4","title":"Strategy 1: Preview before reading","mustKnow":[{"type":"paragraph","text":[{"text":"The strategies for efficient reading fall into "},{"text":"3 major parts","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preview before reading:","bold":true},{"text":" connect to your experience; decide what you need to know."}]},{"text":[{"text":"Read with intent:","bold":true},{"text":" search for key elements; highlight key points; annotate your impressions."}]},{"text":[{"text":"Review after reading:","bold":true},{"text":" review and evaluate what has been read."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Previewing is the first step","bold":true},{"text":" in reading a passage. Never start reading without first "},{"text":"skimming","bold":true},{"text":"; skimming belongs to the "},{"text":"preview","bold":true},{"text":" stage. Previewing familiarises you with the content and organisation, connects the material to your experience, helps you decide what you need to know, builds interest and concentration, and gives a mental outline before you read."}]}]},{"type":"paragraph","text":[{"text":"7 steps in previewing:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Check the "},{"text":"title, subtitles and author","bold":true},{"text":"."}]},{"text":[{"text":"Read the "},{"text":"introduction and the first paragraph","bold":true},{"text":" (where the author gives the general idea)."}]},{"text":[{"text":"Read "},{"text":"each heading and the first sentence","bold":true},{"text":" after it (headings together form a mini-outline)."}]},{"text":[{"text":"Read the "},{"text":"first sentence in a few paragraphs","bold":true},{"text":" on each page (when there are no headings)."}]},{"text":[{"text":"Examine all "},{"text":"photographs, charts, tables and diagrams","bold":true},{"text":"."}]},{"text":[{"text":"Read the "},{"text":"conclusion or summary","bold":true},{"text":" (a conclusion signals the end; a summary condenses the whole)."}]},{"text":[{"text":"Read any "},{"text":"end-of-assignment questions","bold":true},{"text":" (they show what is important and what you will be expected to know)."}]}]},{"type":"paragraph","text":[{"text":"Connect the material to your own experience (3 suggestions):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Think of "},{"text":"familiar situations","bold":true},{"text":" similar to the one in the material; note them in a journal or jotter."}]},{"text":[{"text":"Ask questions and answer them","bold":true},{"text":"; this recalls similar events that illuminate the content."}]},{"text":[{"text":"Allow your mind to jump","bold":true},{"text":" from one idea to another; write in your jotter or work with a friend."}]}]},{"type":"paragraph","text":[{"text":"Decide what you need to know and remember:","bold":true},{"text":" reading only because \"I've been told to read it\" leaves little behind, just as you cannot describe a twenty-naira note despite handling many. Decide first what you need to know, then turn the preview (title, headings, first paragraph, first sentences, subtitles) into "},{"text":"questions","bold":true},{"text":" you answer as you read. This strengthens comprehension and recall."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the first step in reading a passage is to "},{"text":"preview","bold":true},{"text":" it, not to summarise, edit or appreciate it. Summarising comes after reading."}]},{"text":[{"text":"Trap: skimming is classified under "},{"text":"preview before reading","bold":true},{"text":", not under reading with intent or review after reading."}]}]}]},{"number":"4.5","title":"Strategies 2 and 3: Read with intent; review after reading","mustKnow":[{"type":"paragraph","text":[{"text":"Read with intent.","bold":true},{"text":" Comprehension is usually gradual; active reading is actively searching for ideas and separating important from unimportant ones. You may need to read a material more than once. Three activities:"}]},{"type":"paragraph","text":[{"text":"(a) Search for 5 key elements:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The meaning of the "},{"text":"title and subtitles","bold":true},{"text":" (the title announces the topic and often the author's point of view; sometimes its meaning is clear only after reading everything)."}]},{"text":[{"text":"The "},{"text":"introduction","bold":true},{"text":": the opening paragraph; gives background, announces the focus, captures attention."}]},{"text":[{"text":"The "},{"text":"author's main point","bold":true},{"text":": in the "},{"text":"thesis statement","bold":true},{"text":", the one big idea the whole piece explores, usually in the "},{"text":"first or second paragraph","bold":true},{"text":"; sometimes elsewhere or merely implied."}]},{"text":[{"text":"The "},{"text":"support and explanation","bold":true},{"text":": the body; each paragraph has a "},{"text":"topic sentence","bold":true},{"text":" that explains an aspect of the thesis."}]},{"text":[{"text":"The "},{"text":"conclusion","bold":true},{"text":": closes the piece; may restate the main point, offer ideas for further thought or suggest future directions."}]}]},{"type":"paragraph","text":[{"text":"Spelling errors are not a key element.","bold":true}]},{"type":"paragraph","text":[{"text":"(b) Highlight key points","bold":true},{"text":" (read with a highlighter or pen in hand), 4 rules:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Decide what kinds of information to highlight (the task after reading decides this)."}]},{"text":[{"text":"Read first, then highlight","bold":true},{"text":" (prevents too much highlighting)."}]},{"text":[{"text":"Be selective","bold":true},{"text":" (makes important points stand out)."}]},{"text":[{"text":"Highlight key elements, words and phrases: the "},{"text":"thesis statement, topic sentences","bold":true},{"text":" and everything related to the thesis."}]}]},{"type":"paragraph","text":[{"text":"(c) Annotate your impressions.","bold":true},{"text":" "},{"text":"Annotation","bold":true},{"text":" = jotting down personal ideas about the material; your response to the author's ideas, written in the "},{"text":"margin","bold":true},{"text":": questions, agreement, disagreement, surprise, phrases summarising important points. 5 things to annotate:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Important points (e.g. the thesis statement) that prompt personal responses."}]},{"text":[{"text":"Sections you need further information on."}]},{"text":[{"text":"Sections where the author reveals his or her reasons for writing."}]},{"text":[{"text":"Ideas you agree with, disagree with or question."}]},{"text":[{"text":"Any "},{"text":"inconsistency","bold":true},{"text":" on the author's part."}]}]},{"type":"paragraph","text":[{"text":"Review after reading.","bold":true},{"text":" Do not simply close the book. Spend a few minutes reviewing and evaluating, "},{"text":"immediately","bold":true},{"text":" after reading, to increase what you remember. The "},{"text":"same steps used to preview are used to review","bold":true},{"text":". Goal: touch on each main point once more. Write a "},{"text":"summary","bold":true},{"text":" from the highlighted items and annotations (a start if you must later write an essay). Pay attention to "},{"text":"3 things","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"heading","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"highlighted or underlined items","bold":true},{"text":" that point to the main ideas."}]},{"text":[{"text":"The "},{"text":"annotated items","bold":true},{"text":" on the margin."}]}]},{"type":"paragraph","text":[{"text":"References are not part of the review.","bold":true}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why reading can be difficult:","bold":true},{"text":" the topic is uninteresting, you cannot \"connect\" with the author, or the style is confusing. You will not experience much difficulty if you "},{"text":"follow the appropriate steps","bold":true},{"text":" (preview, read with intent, review)."}]},{"text":[{"text":"Graphic organiser:","bold":true},{"text":" a diagram of the structure of the main points in a material; an active way to connect and review major ideas. It must include all the key elements. Helps when a material is hard."}]},{"text":[{"text":"With persistence and practice you gain speed, read more actively, and improve comprehension and the rate and depth of recollection. Reading is a conscious activity requiring total concentration."}]},{"text":[{"text":"Trap: annotation is "},{"text":"personal response","bold":true},{"text":" in the margin; highlighting is "},{"text":"marking the text","bold":true},{"text":". Both feed the review summary."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading = translating written/printed symbols into meaning; eyes (what the author says) + brain (what the author means); purpose: comprehension."}]},{"text":[{"text":"Target about 600 words per minute; efficiency grows only through constant practice."}]},{"text":[{"text":"4 misconceptions: read everything; everything equally important; everything read the same way; everything in print is true."}]},{"text":[{"text":"How you read depends on nature of material, purpose and familiarity, never the author or publisher."}]},{"text":[{"text":"Skimming = general idea; scanning = specific information (index); study reading = intensive, guided by LEARNER."}]},{"text":[{"text":"8 bad habits: word-by-word, vocalisation, sub-vocalisation, head movement, finger-pointing, regression, short span of recognition, erratic eye movement. Saccadic and regressive movements are natural."}]},{"text":[{"text":"3 strategies: preview (first step; 7 steps; skimming belongs here), read with intent (5 key elements, 4 highlighting rules, 5 things to annotate), review (heading, highlights, annotations)."}]},{"text":[{"text":"Difficulty: uninteresting topic, no connection with the author, confusing style; a graphic organiser helps."}]}]}],"theory":{"itemId":"89869c2e-9fb3-5179-b521-a6966386ef84","question":[{"type":"paragraph","text":[{"text":"Differentiate between skimming and scanning, and list four bad reading habits, stating why each is not recommended."}]}]},"practice":[{"topic":"Reading Skills I: Effective Reading Strategies","named":false}]}},{"itemId":"dc41bf63-45f6-5e55-9dfe-8b299a625cba","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Reading Skills II: Comprehension and Summary","body":"How to study a comprehension passage in stages (preview, first reading, second reading); the two major question types (MCQ and Traditional) and how to answer each; the four categories of comprehension questions; what a summary, synopsis and abstract are; the rules and the four steps for writing a summary.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"How to study a comprehension passage in stages (preview, first reading, second reading); the two major question types (MCQ and Traditional) and how to answer each; the four categories of comprehension questions; what a summary, synopsis and abstract are; the rules and the four steps for writing a summary."}],"lessons":[{"number":"5.1","title":"Studying a comprehension passage","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading","bold":true},{"text":" involves the eyes and the brain and is fundamental to acquiring knowledge. To understand a comprehension passage fully, study its components carefully and methodically."}]},{"text":[{"text":"Preview first:","bold":true},{"text":" previewing prepares you to study the passage in a \"questioning\" manner, as if searching for something. Turn the title into a question: \"The Causes of Election Violence\" becomes \"What are the causes of election violence?\""}]},{"text":[{"text":"Read the passage more than once.","bold":true},{"text":" This is the key habit for studying a comprehension passage effectively. A passage is best understood when it is read "},{"text":"more than once","bold":true},{"text":" (not simply \"once\", \"twice\" or \"thrice\")."}]},{"text":[{"text":"Match your speed to the passage:","bold":true},{"text":" your reading speed should correspond to how easy or difficult the language is."}]}]},{"type":"table","header":[[{"text":"Passage language"}],[{"text":"Speed"}],[{"text":"Reason"}]],"rows":[[[{"text":"Technical or difficult"}],[{"text":"Slow"}],[{"text":"To assimilate the peculiar vocabulary"}]],[[{"text":"Fairly familiar"}],[{"text":"Faster"}],[{"text":"Easier to follow"}]]]},{"type":"paragraph","text":[{"text":"The two stages of reading:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"First reading:","bold":true},{"text":" done "},{"text":"rapidly","bold":true},{"text":", whatever the nature of the passage, to get a "},{"text":"general impression of the central ideas","bold":true},{"text":". You gain insight into:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"What the writer's "},{"text":"tone","bold":true},{"text":" suggests about his or her "},{"text":"attitude","bold":true},{"text":" to the topic."}]},{"text":[{"text":"What the writer is trying to "},{"text":"achieve","bold":true},{"text":": to persuade, inform, educate, frighten or annoy the reader (the purpose)."}]},{"text":[{"text":"The "},{"text":"theme","bold":true},{"text":" or central idea of the passage."}]}]}]},{"text":[{"text":"Second reading:","bold":true},{"text":" done at a "},{"text":"much slower pace","bold":true},{"text":". Here you isolate the "},{"text":"main ideas from the minor ones","bold":true},{"text":", the "},{"text":"subjective from the objective","bold":true},{"text":", and the "},{"text":"direct from the indirect","bold":true},{"text":". It demands careful attention to details of the general ideas found in the first reading. Focus on:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sentences which "},{"text":"summarise","bold":true},{"text":" an idea or ideas."}]},{"text":[{"text":"Examples or illustrations","bold":true},{"text":"."}]},{"text":[{"text":"Statements which give a clue to the writer's "},{"text":"viewpoint","bold":true},{"text":"."}]},{"text":[{"text":"Statements which tend to "},{"text":"suggest ideas","bold":true},{"text":" to you."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First reading = fast, big picture (tone, purpose, theme). Second reading = slow, details (main vs minor, salient points). Exams swap these: if an option says the first reading is \"slow and detailed\", it is wrong."}]},{"text":[{"text":"A passage on \"The Michael Jackson Saga\" can be raced through; \"Globalist Action and the African Psyche\" must be read slowly. The difference is the difficulty of the language, not the length."}]},{"text":[{"text":"The four focus points of the second reading help you recognise the "},{"text":"salient points","bold":true},{"text":" (the most important ideas) of the passage."}]},{"text":[{"text":"Order: preview, first (rapid) reading, second (slow) reading, then answer the questions."}]}]}]},{"number":"5.2","title":"Answering the questions: MCQ and Traditional Type","mustKnow":[{"type":"paragraph","text":[{"text":"Three things comprehension passages do:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"They require you to "},{"text":"analyse","bold":true},{"text":" the contents of the passage."}]},{"text":[{"text":"They test your understanding by demanding a "},{"text":"summary of the salient points","bold":true},{"text":" or ideas."}]},{"text":[{"text":"They demand an "},{"text":"in-depth study","bold":true},{"text":" so that you can "},{"text":"infer","bold":true},{"text":" information that is not presented directly (implied, suggested or subtly indicated)."}]}]},{"type":"paragraph","text":[{"text":"Two major types of comprehension question:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Multiple Choice Questions (MCQ):","bold":true},{"text":" a "},{"text":"fast mode","bold":true},{"text":" of testing understanding. The alternatives are carefully designed to "},{"text":"disguise","bold":true},{"text":" the answer, which you obtain through a "},{"text":"process of elimination","bold":true},{"text":"."}]},{"text":[{"text":"Traditional Type Questions:","bold":true},{"text":" questions which require you to give answers "},{"text":"in your own words","bold":true},{"text":", e.g. \"What do you suppose is the writer's attitude towards the subject matter?\", \"What is your impression of the writer's viewpoint?\", \"In one sentence, summarise the central idea of the passage.\""}]}]},{"type":"paragraph","text":[{"text":"4 clues to answering MCQ:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Never mark more than one answer.","bold":true}]},{"text":[{"text":"Ensure that "},{"text":"all other options are incorrect","bold":true},{"text":" before marking your answer."}]},{"text":[{"text":"Attempt the question through a "},{"text":"process of elimination","bold":true},{"text":", discarding the incorrect answers."}]},{"text":[{"text":"There is "},{"text":"usually a correct answer","bold":true},{"text":" unless otherwise stated."}]}]},{"type":"paragraph","text":[{"text":"4 features of MCQ options:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Some answers are "},{"text":"suggested by the writer but not confirmed","bold":true},{"text":" in the text."}]},{"text":[{"text":"Some answers are "},{"text":"only partly correct","bold":true},{"text":"."}]},{"text":[{"text":"Some answers are "},{"text":"logically true but not specifically mentioned","bold":true},{"text":" in the text."}]},{"text":[{"text":"Some contain "},{"text":"zero answers","bold":true},{"text":", e.g. \"none of the above\", \"don't know\"."}]}]},{"type":"paragraph","text":[{"text":"4 features of Traditional Type questions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Some demand answers "},{"text":"obtainable only in the passage","bold":true},{"text":", e.g. \"According to the passage, what does globalisation mean?\""}]},{"text":[{"text":"Some require you to explain the "},{"text":"meaning of specific words in context","bold":true},{"text":", e.g. \"cat\" could be an animal or a metaphor (a cat with nine lives)."}]},{"text":[{"text":"Some demand your "},{"text":"personal opinion","bold":true},{"text":" about the contents, as long as your inferences are relevant to the text. These test your "},{"text":"imagination","bold":true},{"text":"."}]},{"text":[{"text":"Some demand your "},{"text":"personal deductions","bold":true},{"text":" based on what is implied, suggested or clearly stated."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MCQ","bold":true},{"text":" = Multiple Choice Questions. If an exam lists \"OPQ\", \"PVQ\", \"TDQ\" and \"MCQ\" as question types asked in comprehension passages, only "},{"text":"MCQ","bold":true},{"text":" is real."}]},{"text":[{"text":"\"Zero answer\" is the name for an option such as \"none of the above\" or \"don't know\". It carries no content of its own."}]},{"text":[{"text":"An MCQ needs only a choice; a Traditional question needs a written response in "},{"text":"your own words","bold":true},{"text":", so it demands in-depth understanding of the passage."}]},{"text":[{"text":"Word-in-context questions (feature 2) test whether you can tell the literal meaning from the figurative one. Answer with the meaning the "},{"text":"passage","bold":true},{"text":" uses, not the dictionary's first meaning."}]}]}]},{"number":"5.3","title":"The four categories of comprehension questions","mustKnow":[{"type":"paragraph","text":[{"text":"MCQ and Traditional Type describe the "},{"text":"format","bold":true},{"text":" of questions. When you consider the "},{"text":"tools examiners use to test understanding","bold":true},{"text":", there are "},{"text":"four categories","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct reference questions:","bold":true},{"text":" require you to "},{"text":"refer directly to the text","bold":true},{"text":", e.g. \"With reference to the passage, what are the major types of masquerades in Africa?\""}]},{"text":[{"text":"Inference questions:","bold":true},{"text":" require you to "},{"text":"infer","bold":true},{"text":" from the text, i.e. find out or establish the "},{"text":"relationship between two or more sentences or parts","bold":true},{"text":" of the passage, e.g. \"What do you consider the difference between the view expressed in sentence 1 and sentence 3 of paragraph four?\""}]},{"text":[{"text":"Supposition questions:","bold":true},{"text":" require you to "},{"text":"think about ideas which extend beyond the passage","bold":true},{"text":", relating aspects of the passage to the "},{"text":"outside world","bold":true},{"text":", e.g. \"What do you suppose is responsible for the negative attitude of labour leaders to most undemocratic governments in the world today?\""}]},{"text":[{"text":"Evaluation questions:","bold":true},{"text":" require an "},{"text":"evaluation of the passage","bold":true},{"text":" in terms of the "},{"text":"information provided","bold":true},{"text":" and the "},{"text":"effectiveness of the writer's language","bold":true},{"text":" in presenting the main idea, e.g. \"In your opinion, what is the motivation of the writer in this passage?\""}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"There is "},{"text":"no","bold":true},{"text":" \"affirmation question\" among the four. If an exam asks which is NOT one of the categories, the odd one out is whichever name is not direct reference, inference, supposition or evaluation."}]},{"text":[{"text":"Trap: \"two types\" and \"four categories\" are different lists. Two "},{"text":"types","bold":true},{"text":" (format): MCQ, Traditional. Four "},{"text":"categories","bold":true},{"text":" (examiner's tools): direct reference, inference, supposition, evaluation."}]},{"text":[{"text":"Signals in the stem: \"with reference to the passage\" = direct reference; \"difference between sentence 1 and sentence 3\" = inference; \"what do you suppose\" = supposition; \"in your opinion ... the writer's language\" = evaluation."}]},{"text":[{"text":"Supposition takes you "},{"text":"outside","bold":true},{"text":" the text to the world; evaluation keeps you "},{"text":"on","bold":true},{"text":" the text but asks you to judge it."}]}]}]},{"number":"5.4","title":"Summary, synopsis and abstract","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Summary (also synopsis or recap):","bold":true},{"text":" a "},{"text":"condensed version of an original work","bold":true},{"text":", usually about "},{"text":"one-third of the length","bold":true},{"text":" of the original. It highlights the "},{"text":"major points","bold":true},{"text":", with the sole purpose of helping the reader get the message in a more concise manner."}]},{"text":[{"text":"A "},{"text":"paragraph","bold":true},{"text":" can often be summarised in a "},{"text":"single sentence","bold":true},{"text":"; a "},{"text":"three or four paragraph passage","bold":true},{"text":" can usually be summarised in a "},{"text":"single paragraph","bold":true},{"text":"."}]},{"text":[{"text":"Synopsis:","bold":true},{"text":" a "},{"text":"summary of a plot","bold":true},{"text":". When you return from a movie and say what it was about, naming the main characters and what happened to them, that is a synopsis. Its use is "},{"text":"limited to novels, plays and stories","bold":true},{"text":". For all other reading materials, the "},{"text":"summary","bold":true},{"text":" is used."}]},{"text":[{"text":"Abstract:","bold":true},{"text":" a "},{"text":"shorter, more concise non-fiction summary","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Written summary of a comprehension passage:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Begin with a "},{"text":"lead","bold":true},{"text":" which states the "},{"text":"title, author, text type and main idea","bold":true},{"text":" of the text."}]},{"text":[{"text":"Arrange the ideas "},{"text":"clearly","bold":true},{"text":"."}]},{"text":[{"text":"Paraphrase","bold":true},{"text":" expressions with new words; "},{"text":"no quotations","bold":true},{"text":" from the text."}]},{"text":[{"text":"No dramatic structure is needed, because a summary does not retell a story."}]},{"text":[{"text":"Use the "},{"text":"present tense","bold":true},{"text":" or the "},{"text":"historic present","bold":true},{"text":"."}]},{"text":[{"text":"If the material is a "},{"text":"book or dissertation","bold":true},{"text":", present the "},{"text":"major facts","bold":true},{"text":" in common scientific language."}]}]},{"type":"paragraph","text":[{"text":"Summary in non-fiction:","bold":true},{"text":" non-fiction portrays "},{"text":"actual events","bold":true},{"text":". You highlight the "},{"text":"author's point of view","bold":true},{"text":" on the subject matter "},{"text":"without offering analysis or assessment","bold":true},{"text":". In addition to the guidelines above, you provide "},{"text":"numerical ratings and evaluations","bold":true},{"text":" of the titles covered."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap question: \"Which is NOT true about writing a summary?\" The false statement is \"quotations from the text are included\". True statements: expressions are paraphrased with new words; the major facts are included; the present tense is used."}]},{"text":[{"text":"\"A ____ is a condensed version of an original work\" = "},{"text":"summary","bold":true},{"text":". Not \"abstract\" (a specific short non-fiction summary), \"preface\" (an introduction before a book's main text) or \"blurb\" (the promotional text on a book's cover)."}]},{"text":[{"text":"\"A ____ is a summary of a plot\" = "},{"text":"synopsis","bold":true},{"text":". Not \"storyline\" (the plot itself), \"prologue\" (an introductory section) or \"episode\" (one part of a work)."}]},{"text":[{"text":"Why present tense? A summary describes what the text says now, so \"the writer argues\", not \"the writer argued\". "},{"text":"Historic present","bold":true},{"text":" = present tense used for past events (\"In 1349 the king issues an ordinance\"); it is accepted in summaries."}]}]}]},{"number":"5.5","title":"Strategies and steps for writing a summary","mustKnow":[{"type":"paragraph","text":[{"text":"Summary writing requires you to distinguish "},{"text":"important, less important and trivial","bold":true},{"text":" information, and to judge "},{"text":"main ideas","bold":true},{"text":" against "},{"text":"supporting details","bold":true},{"text":". The strategy depends on the type and length of the text."}]},{"type":"paragraph","text":[{"text":"3 recommended strategies:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Paragraph summarisation:","bold":true},{"text":" focus on "},{"text":"one paragraph at a time","bold":true},{"text":"."}]},{"text":[{"text":"Section summarisation:","bold":true},{"text":" focus on the "},{"text":"multi-paragraph section","bold":true},{"text":" that covers the topic and "},{"text":"integrate the multiple ideas","bold":true},{"text":"."}]},{"text":[{"text":"Multi-section summarisation","bold":true},{"text":" (e.g. report writing): read each section or chapter and make "},{"text":"at least three summarising statements","bold":true},{"text":" out of each. This creates a paragraph with a "},{"text":"topic sentence, at least three supporting sentences and a closing sentence","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Summarising a paragraph:","bold":true},{"text":" condense the whole paragraph into a few sentences. "},{"text":"Two results:","bold":true},{"text":" (1) you prove you understand it by translating it into your own words; (2) you reduce it to a more convenient form for review."}]},{"type":"paragraph","text":[{"text":"The 4 steps of summarising, in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Read","bold":true},{"text":" the paragraph to determine its "},{"text":"basic idea","bold":true},{"text":"."}]},{"text":[{"text":"Read it again","bold":true},{"text":" to pick out the "},{"text":"essentials","bold":true},{"text":", summarising mentally as you read; make notes if necessary."}]},{"text":[{"text":"Without consulting the paragraph","bold":true},{"text":", express its content "},{"text":"in your own words","bold":true},{"text":". If you get stuck, stop and repeat step 2."}]},{"text":[{"text":"Compare","bold":true},{"text":" your summary with the original and make any necessary "},{"text":"revisions","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Tense in summaries of literature:","bold":true}]},{"type":"table","header":[[{"text":"Text"}],[{"text":"Tense"}]],"rows":[[[{"text":"Drama"}],[{"text":"Present tense is most appropriate"}]],[[{"text":"Poems, stories, novels"}],[{"text":"Present preferred; past allowed if it seems more natural"}]]]},{"type":"paragraph","text":[{"text":"Whichever tense you choose, "},{"text":"use it throughout","bold":true},{"text":". Shifting tense gives the appearance of "},{"text":"uncertainty","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most paragraphs develop "},{"text":"one simple idea","bold":true},{"text":" by "},{"text":"repetition, explanation or illustration","bold":true},{"text":". If the idea is not stated openly, "},{"text":"distil","bold":true},{"text":" it from the sentences that come closest to stating it."}]},{"text":[{"text":"The same four steps in other words: (i) find the basic idea; (ii) eliminate whatever is not essential; (iii) write the summary, safest done with the original put aside; (iv) compare the digested form with the original for accuracy and revise."}]},{"text":[{"text":"Ordering trap: exams jumble the steps. The correct order is always "},{"text":"read for basic idea, read for essentials, express in own words, compare with original","bold":true},{"text":". Writing can never come before reading, and comparing can only come last."}]},{"text":[{"text":"Keep to the point:","bold":true},{"text":" no new opinions, no needless examples, no quotations."}]},{"text":[{"text":"Worked example. Original: \"Many students fail examinations not because they are unintelligent but because they prepare badly. They start reading a few days before the paper, read everything at the same speed, and never test themselves. Those who plan their reading, vary their speed and check their understanding usually do far better.\" One-sentence summary: \"Examination failure usually comes from poor preparation, so students who plan, vary their reading speed and test themselves do better.\" Check: basic idea kept, examples condensed, own words, present tense, under half the length."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Preview (turn the title into a question); read "},{"text":"more than once","bold":true},{"text":", at a speed matching the difficulty of the language."}]},{"text":[{"text":"First reading: "},{"text":"rapid","bold":true},{"text":", for tone, purpose, theme. Second reading: "},{"text":"much slower","bold":true},{"text":", for main vs minor ideas, summarising sentences, examples, viewpoint clues."}]},{"text":[{"text":"Two question "},{"text":"types","bold":true},{"text":": "},{"text":"MCQ","bold":true},{"text":" (fast; elimination; never mark more than one) and "},{"text":"Traditional Type","bold":true},{"text":" (your own words)."}]},{"text":[{"text":"MCQ options may be partly correct, logically true but not in the text, suggested but not confirmed, or "},{"text":"zero answers","bold":true},{"text":"."}]},{"text":[{"text":"Four "},{"text":"categories","bold":true},{"text":": "},{"text":"direct reference, inference, supposition, evaluation","bold":true},{"text":". No \"affirmation question\"."}]},{"text":[{"text":"Summary","bold":true},{"text":" = condensed version, about "},{"text":"one-third","bold":true},{"text":" the length. "},{"text":"Synopsis","bold":true},{"text":" = summary of a "},{"text":"plot","bold":true},{"text":" (novels, plays, stories). "},{"text":"Abstract","bold":true},{"text":" = short, concise non-fiction summary."}]},{"text":[{"text":"Written summary: lead (title, author, text type, main idea); paraphrase; "},{"text":"no quotations","bold":true},{"text":"; "},{"text":"present tense","bold":true},{"text":"."}]},{"text":[{"text":"Four steps: read for basic idea, read for essentials, write in own words, compare and revise. Three strategies: paragraph, section, multi-section."}]},{"text":[{"text":"Keep one tense throughout; shifting tense looks like uncertainty."}]}]}],"theory":{"itemId":"4e3c6792-c883-5505-b754-5200e0943a0e","question":[{"type":"paragraph","text":[{"text":"Explain the four categories of comprehension questions, giving one example of each."}]}]},"practice":[{"topic":"Reading Skills II: Comprehension and Summary","named":false}]}},{"itemId":"8d114f3f-b3af-5372-a0bf-0cd6fc6974aa","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Reading Skills III: Study Reading","body":"What reading is and why it is communication; what to read and when to read, including the conditions a serious student sets up; the four methods of study reading (SQ3R, PQRST, 3S3R, OK4R) plus flash cards, summarisation and mnemonics; the three types of memory and the three stages of storing information.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What reading is and why it is communication; what to read and when to read, including the conditions a serious student sets up; the four methods of study reading (SQ3R, PQRST, 3S3R, OK4R) plus flash cards, summarisation and mnemonics; the three types of memory and the three stages of storing information."}],"lessons":[{"number":"6.1","title":"What reading is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading:","bold":true},{"text":" an activity which involves looking at words and understanding their meanings, either for pleasure or for serious purposes like an examination. Put another way, reading is the process of translating written or printed symbols and letters into words and sentences which convey meaning."}]},{"text":[{"text":"Reading uses two things: the "},{"text":"eyes","bold":true},{"text":" and the "},{"text":"mental faculty","bold":true},{"text":" (the mind). It is understanding and interpreting written or printed words and signs."}]},{"text":[{"text":"Reading is a "},{"text":"process of communication","bold":true},{"text":". Most formal activities of learning take place through it."}]},{"text":[{"text":"Reading is an important part of the "},{"text":"learning process","bold":true},{"text":": it lets you garner (gather) the information you need for growth."}]},{"text":[{"text":"Through reading you "},{"text":"enlarge your vocabulary","bold":true},{"text":" and so improve your listening and writing."}]},{"text":[{"text":"Saccadic movement:","bold":true},{"text":" when you read, your eyes move by little jumps forward, then stop, then jump forward again, alternately along the line. The eyes can also jump "},{"text":"backward","bold":true},{"text":" to words already read."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Purposes of reading:","bold":true},{"text":" we read for pleasure, for examinations, for knowledge, for information. Reading is not for one purpose only. Trap: any option that says we read \"only\" for pleasure, \"only\" for exams or \"only\" for knowledge is false. If all the options carry \"only\", the correct answer is \"none of the above\"."}]},{"text":[{"text":"Reading is a "},{"text":"receptive","bold":true},{"text":" skill (you take in meaning), like listening. Speaking and writing are "},{"text":"productive","bold":true},{"text":" skills. Reading interprets written or printed symbols; listening interprets spoken words."}]},{"text":[{"text":"Reading is basic to learning in a literate society."}]}]}]},{"number":"6.2","title":"The nature of reading: what and when to read","mustKnow":[{"type":"paragraph","text":[{"text":"What to read","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading materials include "},{"text":"newspapers, magazines, phone directories and textbooks","bold":true},{"text":" on any subject."}]},{"text":[{"text":"Different materials are read in "},{"text":"different ways","bold":true},{"text":". Reading can involve "},{"text":"scanning","bold":true},{"text":", "},{"text":"skimming","bold":true},{"text":" or normal "},{"text":"study reading","bold":true},{"text":"."}]},{"text":[{"text":"Skimming is a mere "},{"text":"survey","bold":true},{"text":". A textbook is read with "},{"text":"concentration and effort","bold":true},{"text":"."}]},{"text":[{"text":"A newspaper is usually read through "},{"text":"once","bold":true},{"text":" and discarded. A textbook is read "},{"text":"over and over again","bold":true},{"text":"; ideas are questioned and recalled, possibly for examinations."}]},{"text":[{"text":"Rule: "},{"text":"the nature of the reading material dictates how it is read","bold":true},{"text":" and the rigour attached to its reading. What you read determines how you read."}]}]},{"type":"paragraph","text":[{"text":"When to read","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"You can read at "},{"text":"any time of the day","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"place","bold":true},{"text":" you choose for reading usually determines the nature of what is read. A newspaper or magazine can be read "},{"text":"anywhere and at any time","bold":true},{"text":". A mathematics textbook requires a "},{"text":"private, noise-free and distraction-free","bold":true},{"text":" area for adequate comprehension."}]},{"text":[{"text":"Marks of a "},{"text":"serious student","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sets aside a "},{"text":"particular time","bold":true},{"text":" of the day for study."}]},{"text":[{"text":"Studies at a "},{"text":"regular place","bold":true},{"text":" designated for it."}]},{"text":[{"text":"Draws up a "},{"text":"reading timetable","bold":true},{"text":"."}]},{"text":[{"text":"Prioritises","bold":true},{"text":" the reading schedule and excludes himself or herself from parties."}]},{"text":[{"text":"Eliminates distractions","bold":true},{"text":" as much as possible."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"reading study materials anywhere\" is "},{"text":"not","bold":true},{"text":" a mark of a serious student. Newspapers can be read anywhere; study materials need a fixed time and place."}]},{"text":[{"text":"Conditions that affect reading and listening.","bold":true},{"text":" Distractions fall into three groups. Know which is which:"}]}]},{"type":"table","header":[[{"text":"Condition"}],[{"text":"What it covers"}],[{"text":"Examples"}]],"rows":[[[{"text":"Physical","bold":true}],[{"text":"the environment around you"}],[{"text":"noise","bold":true},{"text":", a noisy or ill-ventilated room, music from radio, television, laptop or phone"}]],[[{"text":"Physiological","bold":true}],[{"text":"the body of the speaker or reader"}],[{"text":"speech defects, tiredness, illness, hunger"}]],[[{"text":"Psychological","bold":true}],[{"text":"the mind of the listener or reader"}],[{"text":"worries about love affairs, money or health; emotional state; prejudice"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise is a physical condition","bold":true},{"text":", not psychological or physiological. There is no \"spiritual\" category."}]},{"text":[{"text":"Texts you read for a course:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Prescribed text:","bold":true},{"text":" the recommended main book for a course. It usually contains "},{"text":"most of the topics to be treated, or the basis for discussion in the lectures","bold":true},{"text":". Trap: it does not contain "},{"text":"all","italic":true},{"text":" the topics, and it is not the lecturer's sole source."}]},{"text":[{"text":"Supplementary texts:","bold":true},{"text":" given so that students can "},{"text":"acquire additional information","bold":true},{"text":" for their courses. \"Supplement\" means to add to."}]}]}]},{"text":[{"text":"Selective reading","bold":true},{"text":" is important because it may be "},{"text":"impossible, or a waste of time, to read everything in a text","bold":true},{"text":". Depending on your purpose and how familiar the material is, you read selectively. Believing you must read every word is a misconception."}]},{"text":[{"text":"Good study practice: generate guide questions as you read, adopt a "},{"text":"flexible reading speed","bold":true},{"text":", and use "},{"text":"memory-enhancing devices","bold":true},{"text":" (mnemonics). "},{"text":"Not","bold":true},{"text":" recommended: reading with "},{"text":"pre-conceived ideas","bold":true},{"text":". Prejudice and emotional attachment to a subject block understanding; keep an open, questioning mind."}]}]}]},{"number":"6.3","title":"Study reading and the SQ3R technique","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Study reading:","bold":true},{"text":" the type of reading we engage in to gather information that will translate to knowledge on a specific area of study. It targets "},{"text":"detailed, sometimes critical, exploration and evaluation","bold":true},{"text":" of the content. To succeed you must read vigorously and widely and become an avid reader who can recall what has been read."}]},{"text":[{"text":"There are many methods of study reading. "},{"text":"Four","bold":true},{"text":" are treated here: "},{"text":"SQ3R, PQRST, 3S3R and OK4R","bold":true},{"text":"."}]},{"text":[{"text":"SQ3R","bold":true},{"text":" = "},{"text":"S","bold":true},{"text":"urvey, "},{"text":"Q","bold":true},{"text":"uestion, and 3R = "},{"text":"R","bold":true},{"text":"ead, "},{"text":"R","bold":true},{"text":"ecall/Recite, "},{"text":"R","bold":true},{"text":"eview."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"S, Survey:","bold":true},{"text":" examine the "},{"text":"preliminary matters","bold":true},{"text":" of the book: the "},{"text":"title, preface, foreword and table of contents","bold":true},{"text":". Read the "},{"text":"blurb","bold":true},{"text":" (it summarises what the book is about). Check the "},{"text":"publication date","bold":true},{"text":" to see whether the material is current. Ask whether the title is relevant to what you are searching for. To survey an "},{"text":"article or chapter","bold":true},{"text":", check the "},{"text":"title","bold":true},{"text":", the "},{"text":"first and concluding paragraphs","bold":true},{"text":", and the "},{"text":"topic sentences","bold":true},{"text":" of each paragraph."}]},{"text":[{"text":"Q, Question:","bold":true},{"text":" ask questions about what is being read. They direct and guide your reading and lead you to careful, serious study. Examples:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"How correct is the idea or information in the book?"}]},{"text":[{"text":"Does the book actually contain what it said it would in the introduction?"}]},{"text":[{"text":"Does the book contradict your opinions on the subject?"}]},{"text":[{"text":"What is the writer's aim in writing the book?"}]},{"text":[{"text":"Does the writer present his or her views objectively or otherwise?"}]}]}]},{"text":[{"text":"R1, Read:","bold":true},{"text":" a "},{"text":"careful reading","bold":true},{"text":" of the text, examining its main ideas, illustrations and examples, and getting answers to the questions you asked. You may read the text "},{"text":"two or three times","bold":true},{"text":". Read with a "},{"text":"critical mind","bold":true},{"text":", clarify issues, accommodate new vocabulary and take notes."}]},{"text":[{"text":"R2, Recall/Recite:","bold":true},{"text":" make an effort to remember from memory what you have read: definitions, keywords, new words, illustrations. Do this by "},{"text":"paraphrasing","bold":true},{"text":" or by using the "},{"text":"exact words","bold":true},{"text":" of the text; write the expressions down or have a "},{"text":"friend listen","bold":true},{"text":" while you recall them verbally. Go back to the text if you need to refresh your memory. Purpose: learn new ideas and add them to your knowledge base."}]},{"text":[{"text":"R3, Review:","bold":true},{"text":" to review is to "},{"text":"assess","bold":true},{"text":"; it is synonymous with "},{"text":"revision","bold":true},{"text":". You look again at everything you have done on the SQ3R scale, read the text again and make corrections, making sure "},{"text":"nothing has been forgotten","bold":true},{"text":". It is more or less a "},{"text":"repetition of all the steps","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap on the 3Rs: "},{"text":"Read, Recall, Review","bold":true},{"text":". \"Recite\" is another name for Recall, but \"Repeat\", \"Roll\", \"Replay\" and \"Rehash\" are not part of the method."}]},{"text":[{"text":"Trap on survey: the "},{"text":"blurb","bold":true},{"text":" belongs to the survey of a whole "},{"text":"book","bold":true},{"text":" (only books carry one). When surveying an "},{"text":"article or chapter","bold":true},{"text":", you consider the title, the introduction and conclusion, and the topic sentences, not a blurb."}]},{"text":[{"text":"\"Survey\" here has nothing to do with land surveyors or measuring the size of a book, and it is not an in-depth investigation of the content."}]},{"text":[{"text":"Seven reading strategies","bold":true},{"text":" that help you understand what you read at the Read stage:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reading with purpose and flexibility:","bold":true},{"text":" the nature of the material and your purpose dictate the thoroughness and speed of reading. Flexibility is your ability to "},{"text":"vary your reading speed","bold":true},{"text":" to suit the material. Skim, scan or study-read with your purpose and the difficulty of the material in mind."}]},{"text":[{"text":"Pre-reading:","bold":true},{"text":" read the preliminary details such as the introductory paragraph, and the conclusion, before the actual reading. It helps you organise what is to be read."}]},{"text":[{"text":"Identifying verbal and sense links:","bold":true},{"text":" words are strung into phrases, clauses and sentences. Look for cues and linkages; "},{"text":"keywords and topic sentences","bold":true},{"text":" help understanding."}]},{"text":[{"text":"Adopting a proper mental posture:","bold":true},{"text":" be mentally alert and stable. To aid this: (a) have a "},{"text":"regular place of study","bold":true},{"text":" so you adapt to the environment; (b) "},{"text":"avoid distractions","bold":true},{"text":", both physical (music from the radio, television, laptop or phone) and other forms (worries about love affairs, money or health)."}]},{"text":[{"text":"Dividing up the study material:","bold":true},{"text":" break the material into manageable smaller units and take one step at a time to aid assimilation."}]},{"text":[{"text":"Adhering to the writer's leads:","bold":true},{"text":" follow the text's division into "},{"text":"introduction, main body and conclusion","bold":true},{"text":" as the writer intends."}]},{"text":[{"text":"Being a participant reader:","bold":true},{"text":" take part in the process of communication by asking yourself important questions and finding the answers in the text; be critical of what you read."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: your mental posture is affected by music from gadgets, noise and worries about money or affairs. It is "},{"text":"not","bold":true},{"text":" affected by the "},{"text":"arrangement of keywords and topic sentences","bold":true},{"text":"; that is a reading strategy that helps you, not a distraction."}]}]}]},{"number":"6.4","title":"PQRST, 3S3R, OK4R and other study aids","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PQRST","bold":true},{"text":" = "},{"text":"P","bold":true},{"text":"review, "},{"text":"Q","bold":true},{"text":"uestion, "},{"text":"R","bold":true},{"text":"ead, "},{"text":"S","bold":true},{"text":"ummary, "},{"text":"T","bold":true},{"text":"est. It gives priority to the information to be examined, especially in an examination."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preview:","bold":true},{"text":" examine the topic and the various headings and ideas in the course outline."}]},{"text":[{"text":"Question:","bold":true},{"text":" ask the usual questions about what you are reading to aid understanding."}]},{"text":[{"text":"Read:","bold":true},{"text":" carefully read all materials related to the topic and select ideas that answer the questions."}]},{"text":[{"text":"Summary:","bold":true},{"text":" put all you have studied in summary form, taking account of illustrations and diagrams."}]},{"text":[{"text":"Test:","bold":true},{"text":" test yourself by answering the questions you formulated earlier, focusing only on the topic."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3S3R:","bold":true},{"text":" 3S = "},{"text":"Survey, Study-read, Speech-read","bold":true},{"text":"; 3R = "},{"text":"Recite, Reflect, Recollect","bold":true},{"text":"."}]},{"text":[{"text":"OK4R:","bold":true},{"text":" "},{"text":"O","bold":true},{"text":"verview, "},{"text":"K","bold":true},{"text":"ey points; 4R = "},{"text":"Read, Recall, Reflect, Review","bold":true},{"text":"."}]},{"text":[{"text":"3S3R and OK4R are strategies for studying better; they teach effective "},{"text":"note-taking","bold":true},{"text":" and "},{"text":"mnemonic devices","bold":true},{"text":"."}]},{"text":[{"text":"Other methods of study reading:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Flash cards:","bold":true},{"text":" cards of "},{"text":"A5 size","bold":true},{"text":" carrying short notes for revision. They are usually "},{"text":"visual clues","bold":true},{"text":"."}]},{"text":[{"text":"Summarisation:","bold":true},{"text":" read and recall what you have read in a short form using "},{"text":"keywords","bold":true},{"text":"; the keywords bring the ideas back in the examination hall."}]},{"text":[{"text":"Mnemonic devices:","bold":true},{"text":" acronyms or simple phrases that help you memorise ideas for an examination. Example: "},{"text":"ROYGBIV","bold":true},{"text":" for the colours of the rainbow: red, orange, yellow, green, blue, indigo, violet."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages of study reading","bold":true},{"text":" (3): it increases better study habits; it boosts your effort at studying and passing examinations; it helps you to study smartly and pass well."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: only "},{"text":"PQRST","bold":true},{"text":" is a real technique. STPQR, QRSTP and RSTPQ are scrambled letters, not methods."}]},{"text":[{"text":"Compare the acronyms: SQ3R and OK4R both contain Read, Recall and Review (OK4R adds Reflect); PQRST is the only one that ends with a "},{"text":"Test","bold":true},{"text":"; 3S3R is the only one with Speech-read and Recollect."}]}]}]},{"number":"6.5","title":"Reading, retaining and remembering","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory","bold":true},{"text":" controls the retention of what has been studied. The ability to remember and recollect what you have read is important to a student."}]},{"text":[{"text":"Three types of memory","bold":true},{"text":", classified by "},{"text":"how long","bold":true},{"text":" information is kept:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sensory memory (SM):","bold":true},{"text":" linked to the "},{"text":"senses","bold":true},{"text":": the ears, eyes, hands, tongue and nose. Information here is very "},{"text":"ephemeral","bold":true},{"text":" (short-lived). It is the first area of memory."}]},{"text":[{"text":"Short-term memory (STM):","bold":true},{"text":" the second compartment. Ideas stay for a "},{"text":"short time","bold":true},{"text":". Information is "},{"text":"organised","bold":true},{"text":" here; vital and relevant points are selected and irrelevant ones filtered out."}]},{"text":[{"text":"Long-term memory (LTM):","bold":true},{"text":" a "},{"text":"permanent","bold":true},{"text":" room for storing information. It is "},{"text":"large and limitless","bold":true},{"text":", and new ideas are allowed in."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Best way to remember","bold":true},{"text":" what you read: recall it "},{"text":"without using the exact words","bold":true},{"text":" of the textbook, that is, "},{"text":"paraphrase","bold":true},{"text":" in your own words. Another way is to "},{"text":"recite verbatim","bold":true},{"text":"; this suits lines in a play, words in a foreign language, or the sciences."}]},{"text":[{"text":"Three stages of storing information:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Encoding:","bold":true},{"text":" the ability to read, organise and internalise information."}]},{"text":[{"text":"Storage:","bold":true},{"text":" the ability to retain the information."}]},{"text":[{"text":"Retrieval:","bold":true},{"text":" remembering or recalling stored information. Aided by "},{"text":"attention","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Recall is aided by "},{"text":"attention, concentration and focus","bold":true},{"text":", and by "},{"text":"repetition, recitation and review","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the "},{"text":"brain","bold":true},{"text":" is not a sense organ, so it is "},{"text":"not","bold":true},{"text":" associated with sensory memory. The ears, eyes, hands, tongue and nose are."}]},{"text":[{"text":"Trap: the classification based on "},{"text":"length of storage","bold":true},{"text":" is "},{"text":"long-term and short-term","bold":true},{"text":" (with sensory memory as the very brief first stage). \"Transient and permanent\", \"visible and invisible\" and \"variable and invariable\" are not the terms used."}]},{"text":[{"text":"Trap: "},{"text":"reproduction","bold":true},{"text":" (simply producing information, as in an exam) does "},{"text":"not","bold":true},{"text":" enhance recall. Repetition, recitation and review do."}]},{"text":[{"text":"Practical test of good study reading: read a passage at least twice, then answer questions on it without looking back."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading = looking at words and understanding their meanings; eyes plus mind; a process of communication; saccadic eye movement."}]},{"text":[{"text":"We read for pleasure, exams and knowledge; never \"only\" one."}]},{"text":[{"text":"The nature of the material dictates how it is read: newspaper once, textbook over and over."}]},{"text":[{"text":"Serious student: fixed time, regular place, timetable, no parties, no distractions. Noise is a "},{"text":"physical","bold":true},{"text":" condition; worries are psychological."}]},{"text":[{"text":"Prescribed text covers most topics; supplementary texts add information; selective reading saves time."}]},{"text":[{"text":"Four methods: "},{"text":"SQ3R","bold":true},{"text":" (Survey, Question, Read, Recall, Review), "},{"text":"PQRST","bold":true},{"text":" (Preview, Question, Read, Summary, Test), "},{"text":"3S3R","bold":true},{"text":", "},{"text":"OK4R","bold":true},{"text":"."}]},{"text":[{"text":"Survey a book: title, preface, foreword, contents, blurb, date. Survey a chapter: title, first and last paragraphs, topic sentences."}]},{"text":[{"text":"Other aids: A5 flash cards, summarisation with keywords, mnemonics (ROYGBIV)."}]},{"text":[{"text":"Memory: sensory (senses, ephemeral), short-term, long-term (permanent, limitless). Stages: encoding, storage, retrieval."}]},{"text":[{"text":"Recall is aided by attention, repetition, recitation and review; paraphrasing beats memorising exact words."}]}]}],"theory":{"itemId":"d8a9e146-234e-515d-9111-7148c5c6a8b8","question":[{"type":"paragraph","text":[{"text":"Explain the SQ3R technique of study reading."}]}]},"practice":[{"topic":"Reading Skills III: Study Reading","named":false}]}},{"itemId":"ecbcb325-80a7-51c8-9ceb-f341de345514","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Writing Skills I: The Paragraph","body":"What a paragraph is; the 8 types and their helper words; the topic sentence and the 5 qualities of a good one; the 3-stage structure; the 5-step process; the 3 troubleshooting problems; the 4 elements; when to start a new paragraph; transitions and signposts.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What a paragraph is; the 8 types and their helper words; the topic sentence and the 5 qualities of a good one; the 3-stage structure; the 5-step process; the 3 troubleshooting problems; the 4 elements; when to start a new paragraph; transitions and signposts."}],"lessons":[{"number":"7.1","title":"What a paragraph is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paragraph:","bold":true},{"text":" a unit of any composition comprising a collection of related sentences dealing with a single topic. Simply: a sentence or group of sentences that support one main idea."}]},{"text":[{"text":"It usually contains a "},{"text":"main idea","bold":true},{"text":" and may contain a "},{"text":"sub-idea","bold":true},{"text":"."}]},{"text":[{"text":"Essay:","bold":true},{"text":" a combination of ideas from one paragraph to another that creates a united whole; all paragraphs support each other, leading from the first idea to the final resolution."}]},{"text":[{"text":"Length is not a determinant","bold":true},{"text":" in defining a paragraph. Single-sentence paragraphs are rare, so write a "},{"text":"minimum of three sentences","bold":true},{"text":"."}]},{"text":[{"text":"A good paragraph shows "},{"text":"unity and coherence","bold":true},{"text":", just as a good composition shows them among its paragraphs. These are the features shared by paragraphs and essays."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The unit described is the paragraph: not the sentence (too small), the essay (made of paragraphs) or \"text\" (too general)."}]},{"text":[{"text":"Trap: the shared pair is "},{"text":"unity and coherence","bold":true},{"text":", not \"unity and self-sufficiency\", \"cohesion and transparency\" or \"transition and cohesion\". Transition is only a device for achieving coherence."}]},{"text":[{"text":"True of paragraphs: they vary in length, each addresses only an aspect of the topic, and a paragraph is hardly ever longer than the entire essay. "},{"text":"Not","bold":true},{"text":" true: every paragraph begins with a topic sentence (Lesson 7.3)."}]}]}]},{"number":"7.2","title":"The 8 types of paragraph","mustKnow":[{"type":"paragraph","text":[{"text":"Learn each type by what it does, then its "},{"text":"helper words","bold":true},{"text":"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Definition:","bold":true},{"text":" explains the key words or main topic of a composition. Helpers: \"is defined as\", \"a kind of\". "},{"text":"Suicide is defined as the act of taking one's own life.","italic":true}]},{"text":[{"text":"Classification:","bold":true},{"text":" groups things or ideas into specific categories. Helpers: \"is a kind of\", \"can be divided into\", \"is a type of\", \"falls under\", \"belongs to\", \"is a part of\", \"fits into\", \"is grouped with\", \"is related to\", \"is associated with\". "},{"text":"Coal is a kind of non-renewable resource.","italic":true}]},{"text":[{"text":"Descriptive:","bold":true},{"text":" describes a person, place or thing. Helpers: \"measurement\", \"location\", \"size\", \"length\", \"is like\", \"colour\", \"width\", \"resembles\", \"above\", \"shape\", \"mass/weight\", \"below\", \"purpose\", \"speed\", \"beside\", \"near\", \"north/east/west\". "},{"text":"Ogbomosho is west of Ibadan.","italic":true}]},{"text":[{"text":"Comparison and contrast:","bold":true},{"text":" similarities and differences between two or more people, places, things or ideas. Helpers: \"is similar to\", \"on the other hand\", \"both\", \"however\", \"also\", \"but\", \"too\", \"in contrast to\", \"differs from\", \"while\". "},{"text":"Both Jos and Lagos have rain in August. However, rain in Lagos is heavier.","italic":true}]},{"text":[{"text":"Sequence:","bold":true},{"text":" describes a series of events or a process in some sort of order, usually based on "},{"text":"time","bold":true},{"text":". Helpers of order: \"first\", \"second\", \"third\", \"in the beginning\"; of time: \"recently\", \"previously\". "},{"text":"First, join a political party. Second, win your party's nomination. Third, win the election.","italic":true}]},{"text":[{"text":"Choice:","bold":true},{"text":" you choose which object, idea or action you prefer and give your opinion. Helpers of point of view: \"in my opinion\", \"belief\", \"feel\"; of personal opinion: \"like/dislike\", \"hope\", \"idea\". "},{"text":"In my opinion, football is more fun than lawn tennis.","italic":true}]},{"text":[{"text":"Explanation:","bold":true},{"text":" explains "},{"text":"how or why","bold":true},{"text":" something happens; explores "},{"text":"causes and effects","bold":true},{"text":". Helpers: \"because\", \"therefore\", \"thus\", \"since\". "},{"text":"Living conditions were terrible. Thus, many people moved to Europe.","italic":true}]},{"text":[{"text":"Evaluation:","bold":true},{"text":" makes "},{"text":"judgements","bold":true},{"text":" about people, ideas and possible actions, based on "},{"text":"criteria","bold":true},{"text":" you develop; you state your evaluation or recommendation and support it. Helpers of criteria: \"good/bad\", \"correct/incorrect\", \"moral/immoral\"; of recommendation: \"suggest\", \"recommend\", \"advise\". "},{"text":"I recommend that pesticides should not be used because they are harmful.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"a series of events or a process in some sort of order\" = "},{"text":"sequence","bold":true},{"text":", not descriptive (a person, place or thing) and not explanation."}]},{"text":[{"text":"Trap: \"explains how or why something happens\" = "},{"text":"explanation","bold":true},{"text":", not definition (key words) or sequence (time order)."}]},{"text":[{"text":"Choice vs evaluation: choice is what "},{"text":"I prefer","italic":true},{"text":"; evaluation is a judgement by criteria (good/bad, moral/immoral) plus a recommendation."}]}]}]},{"number":"7.3","title":"The topic sentence","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Topic sentence:","bold":true},{"text":" the sentence that "},{"text":"states the main idea","bold":true},{"text":" of the paragraph and "},{"text":"works as a summary","bold":true},{"text":" of it."}]},{"text":[{"text":"It is "},{"text":"the most important sentence","bold":true},{"text":" (and the most important part) of a paragraph."}]},{"text":[{"text":"It is "},{"text":"often but not always","bold":true},{"text":" the first sentence: usually first or second, occasionally last, sometimes in the middle."}]},{"text":[{"text":"A thesis statement is to an "},{"text":"essay","bold":true},{"text":" what a topic sentence is to "},{"text":"the paragraph","bold":true},{"text":": it is the "},{"text":"thesis of the paragraph","bold":true},{"text":"."}]},{"text":[{"text":"Read in sequence, an essay's topic sentences give a "},{"text":"sketch of the argument","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 qualities of a good topic sentence:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Concise and emphatic:","bold":true},{"text":" no longer than the idea requires; stresses the important word. "},{"text":"The Nigerian banking system has collapsed","italic":true},{"text":": brief, clear, strong, with the key word \"collapsed\" stressed at the end."}]},{"text":[{"text":"Lets readers "},{"text":"see your point immediately","bold":true},{"text":"; especially useful in an application or an argumentative essay."}]},{"text":[{"text":"Placed "},{"text":"at the end","bold":true},{"text":" of the paragraph when specific details "},{"text":"lead up to a generalisation","bold":true},{"text":"."}]},{"text":[{"text":"Occasionally "},{"text":"avoided","bold":true},{"text":", when the main idea is so obvious it need not be stated."}]},{"text":[{"text":"Carefully worded and restricted","bold":true},{"text":" (focused), which helps you generate and control your information."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"the most important sentence in a paragraph\" is the "},{"text":"topic","bold":true},{"text":" sentence, not \"first\", \"last\" or \"concluding\". First and last are positions; the concluding sentence is optional."}]},{"text":[{"text":"Trap: \"states the main idea and works as its summary\" is the topic sentence, not the conclusion (which only closes the paragraph)."}]},{"text":[{"text":"Since it can be first, middle, last or omitted, \"every paragraph begins with a topic sentence\" is "},{"text":"false","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Structure of a paragraph and the 5-step process","mustKnow":[{"type":"paragraph","text":[{"text":"3 stages of a typical academic paragraph:","bold":true}]},{"type":"table","header":[[{"text":"Stage"}],[{"text":"Name"}],[{"text":"Status"}]],"rows":[[[{"text":"1"}],[{"text":"Topic sentence or main idea"}],[{"text":"Essential"}]],[[{"text":"2"}],[{"text":"Body: support or detail sentences"}],[{"text":"Essential"}]],[[{"text":"3"}],[{"text":"Conclusion or concluding sentence"}],[{"text":"Optional"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A paragraph is "},{"text":"complete","bold":true},{"text":" when it has "},{"text":"a topic sentence and supporting details","bold":true},{"text":"."}]},{"text":[{"text":"Paragraph structure "},{"text":"parallels essay structure","bold":true},{"text":" in order and content: a coherent argument, supporting evidence/analysis, and a conclusion."}]}]},{"type":"paragraph","text":[{"text":"3 contents of a paragraph:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Topic sentence:","bold":true},{"text":" "},{"text":"two purposes","bold":true},{"text":": (1) the "},{"text":"thesis of your paragraph","bold":true},{"text":"; (2) pushes the essay's thesis forward and presents an arguable point. Usually first or second sentence; at the end occasionally, but not as a habit."}]},{"text":[{"text":"Support or detail sentences:","bold":true},{"text":" the "},{"text":"evidence/analysis","bold":true},{"text":" that makes your claim digestible. Balance "},{"text":"evidence","bold":true},{"text":" (facts, quotations, summary of events) with "},{"text":"analysis","bold":true},{"text":" (interpretation). Evidence-heavy = no argument; analysis-heavy = claim not supported."}]},{"text":[{"text":"Concluding observation:","bold":true},{"text":" closes with an observation that is "},{"text":"more than a summary","bold":true},{"text":"; a final idea that leads to the next step. Usually the last or second-to-last sentence."}]}]},{"type":"paragraph","text":[{"text":"Length:","bold":true},{"text":" paragraphs are hardly ever longer than one page, double spaced. "},{"text":"Lengthy","bold":true},{"text":" paragraphs signal a "},{"text":"lack of structure","bold":true},{"text":" (split them); "},{"text":"short","bold":true},{"text":" paragraphs signal a "},{"text":"lack of substance","bold":true},{"text":" (develop or merge)."}]},{"type":"paragraph","text":[{"text":"The 5-Step Process to Paragraph Development","bold":true},{"text":" (model paragraph: African oral narratives, proved by "},{"text":"illustration","bold":true},{"text":"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Decide on a controlling idea and create a topic sentence.","bold":true},{"text":" The controlling idea directs the paragraph's development and often appears as the topic sentence. "},{"text":"African oral narratives often had hidden double meanings.","italic":true}]},{"text":[{"text":"Explain the controlling idea:","bold":true},{"text":" tell the reader how to interpret the topic sentence. "},{"text":"On one level the narratives entertained; on another they spoke truths and imparted moral virtues.","italic":true}]},{"text":[{"text":"Give an example (or multiple examples):","bold":true},{"text":" support or evidence for the idea. The story \"The tortoise goes to a feast in the sky\": tortoise, disguised as a bird, attended a feast meant for birds; his greed made the birds take back their feathers."}]},{"text":[{"text":"Explain the example(s):","bold":true},{"text":" show each example's relevance to the topic sentence, usually in a separate sentence. Abandoned in the sky, tortoise sent a message home; the birds delivered the wrong message, his wife brought out furniture instead of mattresses, and he broke his back."}]},{"text":[{"text":"Complete the paragraph's idea or transition into the next paragraph:","bold":true},{"text":" tie up loose ends and recall the main idea, or move the reader on. "},{"text":"The moral is that greed could lead a person to becoming pretentious and would ultimately lead to his destruction.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Steps 3 and 4 "},{"text":"can be repeated","bold":true},{"text":" until the main idea is fully developed."}]},{"text":[{"text":"Trap: the process has "},{"text":"5","bold":true},{"text":" steps, not 1, 3 or 7. \"Choosing a controlling idea\", \"giving examples\" and \"explaining the controlling idea\" are all real steps; asked which is not a step, pick \"none of the above\"."}]},{"text":[{"text":"Trap: \"complete\" does not mean a capital letter and a full stop, and \"an argument\" on its own is not what completes a paragraph; the answer is a topic sentence and supporting details."}]}]}]},{"number":"7.5","title":"Troubleshooting and the 4 elements","mustKnow":[{"type":"paragraph","text":[{"text":"Troubleshoot a paragraph in 3 cases:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Topic sentence problem.","bold":true},{"text":" The topic sentence may be at the beginning, middle or end; it must be "},{"text":"in there somewhere","bold":true},{"text":". A paragraph may open with a "},{"text":"transition sentence","bold":true},{"text":" ("},{"text":"Like sharks, snakes and scorpions, dogs are widely feared","italic":true},{"text":"); the topic sentence should follow ("},{"text":"Although most people consider dogs quite dangerous, they are, for the most part, entirely harmless","italic":true},{"text":"). If it never comes, you have a problem."}]},{"text":[{"text":"Multiple controlling ideas.","bold":true},{"text":" "},{"text":"Eliminate","bold":true},{"text":" sentences on the second idea, or "},{"text":"split","bold":true},{"text":" into two or more paragraphs with one idea each. In the dogs paragraph, the sentences about groups that fry and eat dogs branch off; the revision removes them and ends by returning to the main idea."}]},{"text":[{"text":"Transitions within the paragraph","bold":true},{"text":" (intra-paragraph linkages): single words or short phrases that relate ideas and create logical progression, especially across multiple examples ("},{"text":"however","italic":true},{"text":", "},{"text":"The first is...","italic":true},{"text":", "},{"text":"The second is...","italic":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"Length (too long or too short) is "},{"text":"not","bold":true},{"text":" one of the three cases."}]},{"type":"paragraph","text":[{"text":"4 elements of an effective paragraph","bold":true},{"text":" (they overlap):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unity:","bold":true},{"text":" a "},{"text":"single focus","bold":true},{"text":" throughout; it must not begin with one point and end with another, or wander. Unity = "},{"text":"singularity of focus","bold":true},{"text":"."}]},{"text":[{"text":"Coherence:","bold":true},{"text":" the trait that makes the paragraph "},{"text":"easily understandable to a reader","bold":true},{"text":", created by "},{"text":"logical bridges","bold":true},{"text":" and "},{"text":"verbal bridges","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Logical bridges (2):","bold":true},{"text":" the same idea carried from sentence to sentence; successive sentences in "},{"text":"parallel form","bold":true},{"text":"."}]},{"text":[{"text":"Verbal bridges (4):","bold":true},{"text":" repeated "},{"text":"key words","bold":true},{"text":"; repeated "},{"text":"synonyms","bold":true},{"text":"; "},{"text":"pronouns","bold":true},{"text":" referring to nouns in earlier sentences; "},{"text":"transition words","bold":true},{"text":" linking sentences."}]}]}]},{"text":[{"text":"A topic sentence:","bold":true},{"text":" indicates in a general way the idea or thesis of the paragraph. Not every paragraph has a clear-cut one, and it can be anywhere, but the easy way is "},{"text":"near the beginning","bold":true},{"text":". Either way you should be able to summarise the paragraph."}]},{"text":[{"text":"Adequate development:","bold":true},{"text":" the topic is discussed "},{"text":"fully and adequately","bold":true},{"text":". A paragraph of only two or three sentences is probably not fully developed."}]}]},{"type":"paragraph","text":[{"text":"11 methods of adequate development:","bold":true},{"text":" (1) use examples and illustrations; (2) cite data (facts, statistics, evidence, details); (3) examine testimony (quotes and paraphrases); (4) use an anecdote or story; (5) define terms; (6) compare and contrast; (7) evaluate causes and reasons; (8) examine effects and consequences; (9) analyse the topic; (10) describe the topic; (11) offer a chronology of an event (time segments)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"easily understandable to the reader\" = "},{"text":"coherence","bold":true},{"text":", not unity or development. \"Completeness\" is not an element."}]},{"text":[{"text":"Trap: unity is not \"connection with other paragraphs\", brevity or elocution."}]},{"text":[{"text":"Trap: ways of enhancing coherence are transition words, synonyms, repeated key words "},{"text":"and pronouns","bold":true},{"text":". \"Avoiding pronouns\" is "},{"text":"not","bold":true},{"text":" one."}]}]}]},{"number":"7.6","title":"New paragraphs, transitions and signposts","mustKnow":[{"type":"paragraph","text":[{"text":"Start a new paragraph in 4 cases:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"When you begin a new idea or point.","bold":true},{"text":" Each new point within an extended idea gets its own paragraph."}]},{"text":[{"text":"To contrast information or ideas:","bold":true},{"text":" sides in a debate, points in an argument, any other difference."}]},{"text":[{"text":"When your readers need a pause:","bold":true},{"text":" a short break for readability, when the paragraph grows too long or the material is complex."}]},{"text":[{"text":"When you are ending your introduction or starting your conclusion.","bold":true},{"text":" These always sit in new paragraphs; many introductions and conclusions have several."}]}]},{"type":"paragraph","text":[{"text":"It is "},{"text":"not","bold":true},{"text":" ideal to start a new paragraph "},{"text":"when you have just introduced the topic","bold":true},{"text":"; stay and support it."}]},{"type":"paragraph","text":[{"text":"Transitions and signposts","bold":true},{"text":" are two very important elements of paragraphing:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Signposts:","bold":true},{"text":" internal aids to readers; usually several sentences or a paragraph outlining "},{"text":"what the article has covered and where it is going","bold":true},{"text":"."}]},{"text":[{"text":"Transitions:","bold":true},{"text":" usually one or several sentences that move from one idea to the next, used at the "},{"text":"end of most paragraphs","bold":true},{"text":" so they flow into the next. Transitions are also needed within paragraphs (Lesson 7.5)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Linking devices","bold":true},{"text":" (transition words) show how an idea follows from the last: "},{"text":"furthermore","italic":true},{"text":" (adding), "},{"text":"however","italic":true},{"text":" (contrasting), "},{"text":"finally","italic":true},{"text":" (ordering), "},{"text":"therefore","italic":true},{"text":", "},{"text":"thus","italic":true},{"text":", "},{"text":"on the other hand","italic":true},{"text":"."}]},{"text":[{"text":"Trap: "},{"text":"because","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" a linking device in this sense; it is a subordinating conjunction joining a dependent clause to a main clause inside one sentence. Among "},{"text":"furthermore","italic":true},{"text":", "},{"text":"however","italic":true},{"text":", "},{"text":"finally","italic":true},{"text":" and "},{"text":"because","italic":true},{"text":", the odd one out is "},{"text":"because","italic":true},{"text":"."}]},{"text":[{"text":"Trap: a new paragraph is "},{"text":"not","bold":true},{"text":" ideal \"when you have introduced the topic\"; concluding, contrasting and introducing a new idea are all proper moments."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paragraph = unit of composition: related sentences on a single topic; at least 3 sentences; length does not define it."}]},{"text":[{"text":"Paragraphs and essays share "},{"text":"unity and coherence","bold":true},{"text":"."}]},{"text":[{"text":"8 types: definition, classification, descriptive, comparison and contrast, sequence (time order), choice, explanation (how or why), evaluation (criteria plus recommendation)."}]},{"text":[{"text":"Topic sentence = states the main idea and works as its summary; the most important sentence; the thesis of the paragraph; often but not always first."}]},{"text":[{"text":"Good topic sentence: concise and emphatic; shows the point at once; at the end when details build to a generalisation; sometimes avoided; carefully worded and restricted."}]},{"text":[{"text":"Structure: topic sentence (essential), support sentences (essential), concluding sentence (optional)."}]},{"text":[{"text":"5 steps: controlling idea and topic sentence; explain it; example(s); explain example(s); complete or transition."}]},{"text":[{"text":"Troubleshoot 3 problems: topic sentence, multiple controlling ideas, transitions within the paragraph. Not length."}]},{"text":[{"text":"4 elements: unity, coherence (logical and verbal bridges), topic sentence, adequate development (11 methods)."}]},{"text":[{"text":"New paragraph: new idea, contrast, pause, ending introduction or starting conclusion. Signposts say where the piece has been and is going; transitions carry one idea into the next."}]}]}],"theory":{"itemId":"4bd81e1d-548e-510e-949b-183e435120aa","question":[{"type":"paragraph","text":[{"text":"Outline and explain the five-step process for paragraph development."}]}]},"practice":[{"topic":"Writing Skills I: The Paragraph","named":false}]}},{"itemId":"77671218-e56e-59ef-a2ef-64c688d32f17","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Writing Skills II: Essay Writing","body":"Why writing matters to scholarship; what an essay is and its thesis; the four essay types (narrative, analytical, descriptive, argumentative/persuasive) and what each demands; the COEM factor (Content, Organisation, Expression, Mechanics); introduction, body and conclusion; linking paragraphs; the punctuation marks and their functions; capitalisation, spelling, reports and the parts of a formal letter.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"Why writing matters to scholarship; what an essay is and its thesis; the four essay types (narrative, analytical, descriptive, argumentative/persuasive) and what each demands; the COEM factor (Content, Organisation, Expression, Mechanics); introduction, body and conclusion; linking paragraphs; the punctuation marks and their functions; capitalisation, spelling, reports and the parts of a formal letter."}],"lessons":[{"number":"8.1","title":"Writing, the essay and its parts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Writing","bold":true},{"text":" is an indispensable part of scholarship: about the most "},{"text":"permanent record","bold":true},{"text":" of your view on an issue. It requires "},{"text":"training, tact, imagination and rigour","bold":true},{"text":"."}]},{"text":[{"text":"Academic activity consists of observing phenomena and reporting on them, listening to lectures, group projects and, most important, "},{"text":"reading and reviewing","bold":true},{"text":". Through writing (term papers, research reports) you are tested on how much you have learned."}]},{"text":[{"text":"Essay:","bold":true},{"text":" a written paper of "},{"text":"several paragraphs","bold":true},{"text":" addressing a "},{"text":"central subject","bold":true},{"text":" clearly specified in the "},{"text":"thesis statement","bold":true},{"text":". An essay is a combination of ideas from one paragraph to another that creates a "},{"text":"united whole","bold":true},{"text":"."}]},{"text":[{"text":"Thesis:","bold":true},{"text":" the "},{"text":"major point an essay seeks to prove","bold":true},{"text":"; the central idea and organising principle. In a scholarly (expository) essay it is stated in the "},{"text":"first (introductory) paragraph","bold":true},{"text":". In imaginative writing (a short story) it is implied in the "},{"text":"conflict","bold":true},{"text":" and need not be in the first paragraph."}]},{"text":[{"text":"The thesis statement is to an essay what the topic sentence is to a paragraph.","bold":true}]},{"text":[{"text":"4 types of essay","bold":true},{"text":" (by content, goal or strategy): "},{"text":"narrative, analytical, persuasive (argumentative), descriptive","bold":true},{"text":". Keep them distinct; do not confuse the method of one with another."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Introduction:","bold":true},{"text":" states the "},{"text":"thesis","bold":true},{"text":", sets the "},{"text":"tone","bold":true},{"text":", gives the "},{"text":"plan","bold":true},{"text":" of the essay; arouses interest."}]},{"text":[{"text":"Middle (main body):","bold":true},{"text":" develops the thesis, one idea per paragraph."}]},{"text":[{"text":"Conclusion:","bold":true},{"text":" signals the "},{"text":"idea of concluding","bold":true},{"text":", looks back over the argument (a "},{"text":"flashback","bold":true},{"text":" or recap) and gives a "},{"text":"resolution of the thesis","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 main features of a full essay:","bold":true},{"text":" (1) appropriate choice of words and acceptable sentences; (2) good paragraphing and grammatical sentences; (3) coherence and use of standard writing conventions."}]},{"text":[{"text":"3 stages of the writing process:","bold":true},{"text":" "},{"text":"pre-writing","bold":true},{"text":" (planning, "},{"text":"brainstorming","bold":true},{"text":": jotting down every idea on the topic before organising them), "},{"text":"writing","bold":true},{"text":" (drafting), "},{"text":"proof-reading","bold":true},{"text":" (checking and correcting). "},{"text":"Publishing is not a stage.","bold":true},{"text":" Brainstorming is a fundamental of writing a good essay."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learning takes place when you can compare issues, define, classify, analyse and illustrate phenomena; your writing shows your competence and comprehension."}]},{"text":[{"text":"Trap: the three parts of good writing are "},{"text":"introduction, middle, conclusion","bold":true},{"text":", not \"introduction, summary, conclusion\" (the summary belongs in the conclusion)."}]},{"text":[{"text":"Trap: a "},{"text":"proposal","bold":true},{"text":" and an "},{"text":"experimental","bold":true},{"text":" essay are "},{"text":"not","bold":true},{"text":" essay types. \"Expository\" is another name for the factual, analytical essay; \"argumentative\" is another name for persuasive."}]},{"text":[{"text":"A "},{"text":"synopsis","bold":true},{"text":" is a summary; a "},{"text":"theme","bold":true},{"text":" is the general subject area; the "},{"text":"thesis","bold":true},{"text":" is the point you prove."}]}]}]},{"number":"8.2","title":"The four types of essay","mustKnow":[{"type":"paragraph","text":[{"text":"1. Narrative essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"sequential or chronological account","bold":true},{"text":" of an experience, procedure or incident; largely "},{"text":"reportorial","bold":true},{"text":". Ranges from a field-trip account to biography, autobiography and fiction. A "},{"text":"police statement","bold":true},{"text":" (what happened, in order) is narrative writing."}]},{"text":[{"text":"Chief aim:","bold":true},{"text":" to "},{"text":"arouse and sustain interest","bold":true},{"text":"; to make the reader feel a good story has been told."}]},{"text":[{"text":"Features: "},{"text":"story line, plot, suspense","bold":true},{"text":" and other rhetorical devices. It does "},{"text":"not","bold":true},{"text":" need a strong argument."}]},{"text":[{"text":"It "},{"text":"emphasises character and setting","bold":true},{"text":" so the reader identifies with the subject. It should be "},{"text":"racy","bold":true},{"text":" (lively), "},{"text":"captivating","bold":true},{"text":" and "},{"text":"plausibly handled","bold":true},{"text":". It lacks the complexity of other types."}]}]},{"type":"paragraph","text":[{"text":"2. Analytical essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The type a university student writes most. The writer identifies an issue, "},{"text":"examines","bold":true},{"text":" it in detail and "},{"text":"assesses its implications for human existence","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" give a chronological account."}]},{"text":[{"text":"2 forms (by strategy of rendition):","bold":true},{"text":" "},{"text":"rationalisations","bold":true},{"text":" (explain the state of things by interpreting facts or data so the reader can form a judgement) and "},{"text":"critiques","bold":true},{"text":" (review an issue, experiment or creative work by making "},{"text":"statements on its quality","bold":true},{"text":"; must rest on reliable and verifiable authority, fact, logic, clear thinking and valid opinion). "},{"text":"Criticism = the informed evaluation of imaginative writing.","bold":true},{"text":" Critique suits the humanities and social sciences."}]},{"text":[{"text":"Empirical method:","bold":true},{"text":" self-evident or verifiable facts; results come instantly without controversy (an object thrown up falls). Suits the "},{"text":"natural sciences","bold":true},{"text":"."}]},{"text":[{"text":"Interpreting the results of experiments may need "},{"text":"rationalisation, critique and empirical methods","bold":true},{"text":" combined (all three)."}]},{"text":[{"text":"A good analytical essay rests on "},{"text":"clear thinking, accurate or verified data, reliable authority and a clear conclusion","bold":true},{"text":" from the evidence, and separates the writer's opinion from facts."}]}]},{"type":"paragraph","text":[{"text":"3. Descriptive essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"detailed and often dispassionate account of people, incidents, scenes and situations","bold":true},{"text":" so the reader can imagine and visualise them as a participant/observer; it "},{"text":"creates a mental picture","bold":true},{"text":"."}]},{"text":[{"text":"Often part of fiction, biography or a "},{"text":"travelogue","bold":true},{"text":" (account of a travel). Objective: an overall impression that aligns the reader with the writer's view, by appealing to "},{"text":"visual and sensory perceptions","bold":true},{"text":"."}]},{"text":[{"text":"2 requirements:","bold":true},{"text":" (1) "},{"text":"appropriate wording","bold":true},{"text":": a large stock of visual and sensory vocabulary; the essay is "},{"text":"shorn of personal feelings","bold":true},{"text":" so the writer stays invisible; (2) "},{"text":"keen observation","bold":true},{"text":": authentic details; noticing what is uncommon to the general eye."}]}]},{"type":"paragraph","text":[{"text":"4. Argumentative (persuasive) essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The writer tries to get readers to "},{"text":"accept a point of view","bold":true},{"text":". Goal: to "},{"text":"sell an idea","bold":true},{"text":", "},{"text":"convince readers","bold":true},{"text":" to make up or change their minds, "},{"text":"persuade the audience","bold":true},{"text":" (all three). The writer "},{"text":"takes a stand","bold":true},{"text":". Argument is at the core of most university writing."}]},{"text":[{"text":"2 strategies:","bold":true},{"text":" (1) "},{"text":"the use of details","bold":true},{"text":": reasoning that is "},{"text":"inductive","bold":true},{"text":" (particular to general) or "},{"text":"deductive","bold":true},{"text":" (general to specific), using statistics, illustrations, justifications, cause/effect relations, analogies and appeals to authorities; (2) "},{"text":"appeal to the emotion","bold":true},{"text":": logic alone cannot win a reader; build a friendly disposition, show authority, arrange ideas for emotional impact."}]},{"text":[{"text":"Not","bold":true},{"text":" necessary in an argument: creating a mental picture (that is description)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Narrative: a narration fails when the subject is commonplace or has a trite moral; the reader says \"and so what?\" Fantasy works (science and detective fiction) if plausibly handled. Sample: \"A Face in the Night\" by Ruskin Bond (Mr Oliver and the faceless boy at Simla); its force lies in character, word choice and brevity."}]},{"text":[{"text":"Analytical example: an essay on a major decision (postgraduate study versus paid employment): state the decision in the first paragraph; give each reason its own paragraph. The sample on a mother giving up her baby for adoption (reasons: her age, her parents' problems, her own future) illustrates "},{"text":"rationalisation","bold":true},{"text":"."}]},{"text":[{"text":"Descriptive samples: \"In the Jungle\" (Gerald Durrell) emphasises "},{"text":"size","bold":true},{"text":" with visual words (\"tremendous\", \"choked\", \"ran riot\"); \"jungle\" appears only in the title. \"The Open Boat\" (Stephen Crane) uses colour, shape, sound and smell to evoke doom; the mood is "},{"text":"dejection and despair","bold":true},{"text":"."}]},{"text":[{"text":"Descriptive trap: words like \"dirty\", \"clean\", \"untidy\" (describing a slum) and superlatives like \"wonderful\", \"excellent\", \"best\" rob the essay of "},{"text":"detachment","bold":true},{"text":"; use them only where justified."}]},{"text":[{"text":"Persuasive sample: \"The Crime of Imprisonment\" uses "},{"text":"reasoning by analogy","bold":true},{"text":" (prisoner compared with a pneumonia patient punished and cured at once). Prisons aim to be "},{"text":"retributory, deterrent and reformative","bold":true},{"text":", yet men are not improved by injuries. The analogy works as an extended metaphor, appealing to emotion and logic."}]},{"text":[{"text":"Trap: a "},{"text":"police statement","bold":true},{"text":" is narrative in method (events in order), but a police report, an annual general meeting report and a sports report count as "},{"text":"expository","bold":true},{"text":" (they set out facts). A "},{"text":"newspaper article","bold":true},{"text":" is not classed as expository because it may narrate, describe, argue or entertain."}]}]}]},{"number":"8.3","title":"The COEM factor and connecting paragraphs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"COEM = Content, Organisation, Expression, Mechanics:","bold":true},{"text":" the four quality-control components that separate a well-executed essay from a poor one."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Content:","bold":true},{"text":" the "},{"text":"depth of treatment","bold":true},{"text":" of the subject; the authority or knowledge brought to it. Called the "},{"text":"\"meat of the essay\"","bold":true},{"text":". Two rules: (a) "},{"text":"limit or narrow the subject","bold":true},{"text":" to achieve depth, since content is a function of size: \"population growth\" is too large; \"Africa's Demographic Multiplications: Implications for the Continent's Economic Development\" is manageable; (b) "},{"text":"maintain a central idea","bold":true},{"text":" (the thesis), which guides selection of material and keeps you focused."}]},{"text":[{"text":"Organisation:","bold":true},{"text":" arranging materials in a "},{"text":"logical order","bold":true},{"text":" to create the desired effect. Develop (a) a suitable "},{"text":"introduction","bold":true},{"text":": perhaps the "},{"text":"most important part","bold":true},{"text":"; arouses and sustains interest; may range from a definition to general ideas; rests on a strong thesis; (b) the "},{"text":"main body","bold":true},{"text":": at the writer's discretion, but move from "},{"text":"familiar to unfamiliar","bold":true},{"text":", simple to complex; (c) a fitting "},{"text":"conclusion","bold":true},{"text":": inferences drawn from linking the facts presented; "},{"text":"striking, memorable and definitive","bold":true},{"text":"."}]},{"text":[{"text":"Expression:","bold":true},{"text":" discriminating choice of "},{"text":"suitable words","bold":true},{"text":" in simple, clear, unambiguous language. Writers lack the speaker's feedback (questions, gestures, tone of voice), so the key is to be "},{"text":"precise, concise and economical","bold":true},{"text":". Two steps: (a) "},{"text":"avoid jargon, deodorant language and highfalutin expressions","bold":true},{"text":"; (b) "},{"text":"be concrete","bold":true},{"text":" (\"Mrs Babatunde mailed the agreement to me\" names the performer; \"The agreement was mailed to me\" is non-concrete). Use clear, concise, forceful sentences and a friendly, natural, courteous tone."}]},{"text":[{"text":"Mechanics:","bold":true},{"text":" meaningful items in a sentence expressed in "},{"text":"symbols rather than words","bold":true},{"text":"; the technical term is "},{"text":"punctuation","bold":true},{"text":". Mechanics of writing also covers "},{"text":"capitalisation","bold":true},{"text":" and "},{"text":"spelling and letter shapes","bold":true},{"text":" (all of these)."}]}]},{"type":"paragraph","text":[{"text":"Connecting paragraphs","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Vary paragraph length.","bold":true},{"text":" Short paragraphs let the reader grasp facts quickly but become "},{"text":"choppy","bold":true},{"text":" if overused; long ones become "},{"text":"boring","bold":true},{"text":". A good essay has "},{"text":"a variation of long and short paragraphs","bold":true},{"text":", which improves continuity and the logic of thought."}]},{"text":[{"text":"Each paragraph communicates a "},{"text":"single idea","bold":true},{"text":" stated in a "},{"text":"topic sentence","bold":true},{"text":", clarified by examples, details and descriptions."}]},{"text":[{"text":"Paragraphs are related by "},{"text":"linking devices (linking expressions)","bold":true},{"text":": first; second; finally; in contrast with; compared to the above; following upon; furthermore; in addition; however. Their function is to specify "},{"text":"continuity","bold":true},{"text":" by establishing a clear relationship with the idea already expressed."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"COEM traps: not \"Entertainment\", \"Comment\" or \"Orientation\". Content is what the essay says; expression is how; organisation is the order; mechanics is the symbols."}]},{"text":[{"text":"Depth trap: to achieve depth you "},{"text":"narrow","bold":true},{"text":" the subject, never expand it. A broad subject is merely skimmed."}]},{"text":[{"text":"The inflated passage on \"organisational behaviour\" says, in fanciful words, only that the field has grown greatly and is now a separate discipline. Inflated vocabulary conceals near emptiness of idea and draws attention to the writer, not the subject."}]}]}]},{"number":"8.4","title":"Punctuation marks and their functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Punctuation marks:","bold":true},{"text":" symbols used to organise and structure expressions so as to convey the right meaning."}]},{"text":[{"text":"The frequently used marks: full stop (.), question mark (?), exclamation mark (!), quotation marks (\" \"), square brackets [ ], comma (,), semi-colon (;), colon (:), capital letters, hyphen (-), dash (–), ellipsis (...), apostrophe ('), parentheses or round brackets ( )."}]},{"text":[{"text":"4 general functions:","bold":true},{"text":" (a) integral to the meaning of the sentence; (b) signify completion or absence of completion of thought; (c) delineate attitudes or idiosyncrasies of speakers or writers; (d) demonstrate variations of pitch or intonation. Punctuation also separates subordinate ideas from major ones, marks stretches of direct speech and shows the possessive case. It does "},{"text":"not","bold":true},{"text":" indicate a writer's background."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Full stop (period):","bold":true},{"text":" ends a complete "},{"text":"declarative","bold":true},{"text":" or "},{"text":"imperative","bold":true},{"text":" sentence. Also marks off "},{"text":"abbreviations and initials","bold":true},{"text":" (Mr., Prof., Ph.D., E. A. Adedun). Omitted in "},{"text":"acronyms","bold":true},{"text":" (UNICEF, NEPA, FIFA, ASUU)."}]},{"text":[{"text":"Exclamation mark:","bold":true},{"text":" ends a structure expressing "},{"text":"surprise, horror, disappointment, anger, indeed all forms of excitement","bold":true},{"text":"; strong feeling, a warning or forceful command; punctuates "},{"text":"interjections","bold":true},{"text":" (Move! Look out! Oh, boy!). Hardly used in formal business writing."}]},{"text":[{"text":"Question mark:","bold":true},{"text":" ends a "},{"text":"direct question","bold":true},{"text":" (interrogative sentence). "},{"text":"Never","bold":true},{"text":" after an "},{"text":"indirect (reported) question","bold":true},{"text":": \"The manager demanded to know why production was slow.\""}]},{"text":[{"text":"Colon:","bold":true},{"text":" introduces a "},{"text":"list","bold":true},{"text":", especially after \"these\", \"namely\", \"the following\", \"as follows\". Also introduces "},{"text":"direct speech","bold":true},{"text":" after a speaker's name in dialogue (\"Okon said: 'I am hungry.'\") and the "},{"text":"publisher's name","bold":true},{"text":" in a reference entry (Ibadan: Heinemann)."}]},{"text":[{"text":"Semi-colon:","bold":true},{"text":" (a) "},{"text":"separates independent clauses","bold":true},{"text":", replacing a comma plus coordinating conjunction (\"Supply us with three cars; they must all be black\"); (b) separates "},{"text":"phrases and clauses in a series","bold":true},{"text":" that already contain commas; (c) sets off conjunctive adverbs (however, therefore, moreover) joining independent clauses."}]},{"text":[{"text":"Comma:","bold":true},{"text":" separates words, phrases, clauses, items and non-essentials; sets off a state from a town, a street from a city, the day from the month. The comma before \"and\" in a list is the "},{"text":"serial comma","bold":true},{"text":". Never put a comma between a "},{"text":"subject and its verb","bold":true},{"text":"."}]},{"text":[{"text":"Dash and hyphen:","bold":true},{"text":" the difference is "},{"text":"context, not length","bold":true},{"text":". The "},{"text":"dash","bold":true},{"text":" works in "},{"text":"syntactic","bold":true},{"text":" constructions and introduces "},{"text":"additional information","bold":true},{"text":" (\"All managers – I mean most managers – look forward to vacations\"). The "},{"text":"hyphen","bold":true},{"text":" works in "},{"text":"lexical","bold":true},{"text":" constructions (ex-senator, sister-in-law, bye-laws)."}]},{"text":[{"text":"Parentheses (round brackets):","bold":true},{"text":" mark off "},{"text":"additional or explanatory information","bold":true},{"text":" the sentence could do without (\"management (the decision-making body)\"). Brackets also enclose a "},{"text":"reference","bold":true},{"text":". Commas, dashes and parentheses differ in "},{"text":"degree","bold":true},{"text":": commas for closely related material, dashes to emphasise interruptions, parentheses for the least essential extras."}]},{"text":[{"text":"Square brackets:","bold":true},{"text":" enclose information "},{"text":"inserted into a quotation","bold":true},{"text":" for clarity."}]},{"text":[{"text":"Apostrophe:","bold":true},{"text":" shows "},{"text":"omission (contractions)","bold":true},{"text":": won't; and "},{"text":"possession","bold":true},{"text":": Ade's salary, Moses' allowance. "},{"text":"Never","bold":true},{"text":" with possessive pronouns: theirs, yours, "},{"text":"its","bold":true},{"text":" (\"the dog wagged its tail\"; \"it's\" means \"it is\"). Never used simply to form plurals."}]},{"text":[{"text":"Quotation marks (inverted commas):","bold":true},{"text":" used "},{"text":"in pairs","bold":true},{"text":" to enclose a third party's exact words (direct speech): Okon said: \"I am hungry.\" Not used for indirect speech: Okon said that he was hungry."}]},{"text":[{"text":"Ellipsis:","bold":true},{"text":" three dots showing items omitted from a quotation; "},{"text":"four dots","bold":true},{"text":" if the omission is at the end of a sentence (the fourth is the full stop)."}]},{"text":[{"text":"Capitalisation:","bold":true},{"text":" see Lesson 8.5."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Terminal punctuation marks","bold":true},{"text":" (they end a sentence): "},{"text":"full stop, question mark, exclamation mark","bold":true},{"text":". The comma is "},{"text":"not","bold":true},{"text":" terminal."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unpunctuated: \"william shakespeare 1564-1616 married a woman eight years his senior when he was eighteen.\" Punctuated: \"William Shakespeare (1564-1616) married a woman eight years his senior when he was eighteen.\" Likewise: \"...his collection, "},{"text":"Girls at War","italic":true},{"text":", took place on a cold December day in Lagos.\""}]},{"text":[{"text":"In Oswald Mtshali's poem a dead mother tells her son \"There is no heaven / Above the clouds\"; his reply \"WHAT!\" is neither question nor statement. Capitals plus exclamation mark pack in his surprise, horror and shock: mechanics introducing figurative language."}]},{"text":[{"text":"Serial comma: \"The General Manager, Production Manager and Operations Manager are going\" could mean the GM is being told two people are going; \"...Production Manager, and Operations Manager...\" makes three travellers clear. Insert it for clarity."}]},{"text":[{"text":"Paired-mark trap: only "},{"text":"quotation marks","bold":true},{"text":" come in pairs; question mark, hyphen and apostrophe are single."}]},{"text":[{"text":"Comma-splice trap: a comma alone cannot separate two independent clauses; use a semi-colon."}]},{"text":[{"text":"Colon-use trap: the colon's three uses are the list, direct speech and the publisher's name in a reference entry. Breaking a title into two parts is "},{"text":"not","bold":true},{"text":" one of them."}]},{"text":[{"text":"Poor punctuation distorts meaning; attention to these \"minor details\" can determine an employee's career."}]}]}]},{"number":"8.5","title":"Mechanics, spelling and other kinds of writing","mustKnow":[{"type":"paragraph","text":[{"text":"Capitalisation rules.","bold":true},{"text":" Use a capital letter:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"at the "},{"text":"beginning of a sentence","bold":true},{"text":" and after every terminal mark (full stop, question mark, exclamation mark);"}]},{"text":[{"text":"for the pronoun "},{"text":"\"I\"","bold":true},{"text":", wherever it occurs (an isolated \"I\");"}]},{"text":[{"text":"for "},{"text":"proper nouns","bold":true},{"text":" (John, Oshogbo, Africa) and "},{"text":"proper adjectives","bold":true},{"text":" of nationality and language (Chilean, Guatemalan, Gaelic, French);"}]},{"text":[{"text":"for names of "},{"text":"deities and sacred contexts","bold":true},{"text":" (God, Allah, the Bible);"}]},{"text":[{"text":"for "},{"text":"principal words in titles, headings and sub-headings","bold":true},{"text":" ("},{"text":"Elements of English Grammar and Usage","italic":true},{"text":"), and named courses (History);"}]},{"text":[{"text":"for "},{"text":"acronyms","bold":true},{"text":" (NFL, PTA, UNICEF) and letter-based words (U-turn)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not","bold":true},{"text":" capitalise "},{"text":"common nouns","bold":true},{"text":" (guesstimates, parsnip) unless they begin a sentence, and do not capitalise after a comma unless the word is a proper noun."}]}]},{"type":"paragraph","text":[{"text":"Spelling.","bold":true},{"text":" Learn these correctly spelled words: "},{"text":"harassment","bold":true},{"text":" (one r, two s), "},{"text":"embarrassment","bold":true},{"text":" (two r, two s), "},{"text":"accommodation","bold":true},{"text":" (two c, two m), "},{"text":"sheriff","bold":true},{"text":" (one r, two f), "},{"text":"souvenir","bold":true},{"text":" (not -ier), "},{"text":"chauffeur","bold":true},{"text":", "},{"text":"parachutist","bold":true},{"text":", "},{"text":"adolescence","bold":true},{"text":" (-esc-, -ence), "},{"text":"shrivel","bold":true},{"text":" (-el), "},{"text":"clammy","bold":true},{"text":" (two m), "},{"text":"sphinx","bold":true},{"text":", "},{"text":"repertoire","bold":true},{"text":", "},{"text":"vagrant","bold":true},{"text":", "},{"text":"resinous","bold":true},{"text":", "},{"text":"communication","bold":true},{"text":", "},{"text":"swinging","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Reports and technical writing","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Report:","bold":true},{"text":" a faithful account of an activity in which the writer participated; it provides "},{"text":"information to influence decisions and actions","bold":true},{"text":". A report must be based on "},{"text":"facts","bold":true},{"text":", not hearsay or arguments."}]},{"text":[{"text":"Objectivity:","bold":true},{"text":" the highest degree is expected in "},{"text":"scientific writing","bold":true},{"text":"."}]},{"text":[{"text":"Technical writing:","bold":true},{"text":" factual, practical, specialised writing: a "},{"text":"car manual, police reports, law reports","bold":true},{"text":". "},{"text":"Not","bold":true},{"text":" love poems. "},{"text":"SME = Subject Matter Expert","bold":true},{"text":", the specialist whose knowledge ensures the content is accurate."}]},{"text":[{"text":"Not reports: a "},{"text":"memorandum","bold":true},{"text":" (brief internal message), an "},{"text":"agenda","bold":true},{"text":" (list of meeting items), "},{"text":"anecdotes","bold":true},{"text":" (short stories), "},{"text":"prolegomena","bold":true},{"text":" (preliminary introduction to a book), an "},{"text":"episode","bold":true},{"text":" (one event in a story)."}]}]},{"type":"paragraph","text":[{"text":"Parts of a formal letter","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Writer's address and "},{"text":"date","bold":true},{"text":"."}]},{"text":[{"text":"Inside address:","bold":true},{"text":" the addressee's name, "},{"text":"designation","bold":true},{"text":" and address."}]},{"text":[{"text":"Salutation:","bold":true},{"text":" Dear Sir / Dear Madam / Dear Mr Okon."}]},{"text":[{"text":"Heading (subject line)","bold":true},{"text":"."}]},{"text":[{"text":"Body","bold":true},{"text":" of the letter."}]},{"text":[{"text":"Subscription","bold":true},{"text":" (complimentary close): "},{"text":"Yours faithfully","bold":true},{"text":" (after Dear Sir/Madam) or "},{"text":"Yours sincerely","bold":true},{"text":" (after a named person)."}]},{"text":[{"text":"Signature","bold":true},{"text":" and the writer's name."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Spotting a wrongly capitalised sentence: check the first letter (\"a parsnip is a root vegetable...\" fails), then proper nouns and acronyms (\"The nfl will repeat...\" fails; it should be NFL)."}]},{"text":[{"text":"Spelling traps: \"harrassment\" copies the double r of \"embarrassment\"; \"souvenier\" adds an unneeded e; \"Adolescense\" ends wrongly in -ense; \"adolescents\" are the people, \"adolescence\" is the stage (the awkward stage); \"parachutis\" has lost its final t; \"clamy\" has lost an m."}]},{"text":[{"text":"Letter trap: the \"subscription\" is the close before the signature, not the salutation, the addressee's designation or the body."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Writing is the most permanent record of your view; it needs training, tact, imagination, rigour."}]},{"text":[{"text":"Essay = several paragraphs on a central subject; the thesis is the point to prove, stated in the first paragraph; thesis : essay :: topic sentence : paragraph."}]},{"text":[{"text":"Four essay types: narrative (chronological, suspense, character and setting), analytical (rationalisations and critiques), descriptive (dispassionate, visual and sensory), argumentative/persuasive (details and appeal to emotion)."}]},{"text":[{"text":"COEM: Content (meat; narrow the subject), Organisation (introduction, body, conclusion), Expression (precise, concise, concrete), Mechanics (punctuation)."}]},{"text":[{"text":"Vary paragraph length; link paragraphs with linking expressions."}]},{"text":[{"text":"Full stop/period ends statements and marks initials; colon introduces lists and direct speech; semi-colon separates independent clauses; exclamation mark for interjections and excitement; question mark only for direct questions; apostrophe for contractions and possession (never its/theirs/yours); quotation marks in pairs; dash for added information; parentheses for explanatory extras."}]},{"text":[{"text":"Terminal marks: full stop, question mark, exclamation mark."}]},{"text":[{"text":"Capitalise sentence starts, \"I\", proper nouns and adjectives, deities, titles, acronyms; not common nouns."}]},{"text":[{"text":"Reports rest on facts and inform decisions; scientific writing is most objective; SME = subject matter expert; the subscription is \"Yours faithfully\"."}]}]}],"theory":{"itemId":"d9c56737-2394-5e87-a520-cafd3101f6c5","question":[{"type":"paragraph","text":[{"text":"Explain the COEM factor in essay writing."}]}]},"practice":[{"topic":"Writing Skills II: Essay Writing and Punctuation","named":false}]}},{"itemId":"32ce878f-a0db-5952-a8d8-2714a3589b45","courseId":"40000000-0000-4000-8000-000000000008","kind":"note","questionId":null,"sourceKey":"guide-topic:9","parentItemId":null,"revision":1,"payload":{"title":"Vocabulary Development","body":"What vocabulary is and where English words came from (Anglo-Saxon, Latin, French, Greek); active versus dormant (recognition) vocabulary and how to grow both; general and specialised dictionaries, including the thesaurus; the types of meaning (denotative, connotative, contextual); the word-formation processes (coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism); morphemes, roots, prefixes and suffixes; and how to choose the right word from a commonly confused pair.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What vocabulary is and where English words came from (Anglo-Saxon, Latin, French, Greek); active versus dormant (recognition) vocabulary and how to grow both; general and specialised dictionaries, including the thesaurus; the types of meaning (denotative, connotative, contextual); the word-formation processes (coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism); morphemes, roots, prefixes and suffixes; and how to choose the right word from a commonly confused pair."}],"lessons":[{"number":"9.1","title":"What vocabulary is and where English words came from","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vocabulary:","bold":true},{"text":" the "},{"text":"total stock of words available in a language","bold":true},{"text":"."}]},{"text":[{"text":"Lexicographers","bold":true},{"text":" (word experts) estimate English has about "},{"text":"one million","bold":true},{"text":" words, yet hardly any learner knows "},{"text":"10,000","bold":true},{"text":". "},{"text":"William Shakespeare","bold":true},{"text":" is said to have used "},{"text":"21,000","bold":true},{"text":" words in all his works."}]},{"text":[{"text":"Poor vocabulary","bold":true},{"text":" makes a speaker substitute an "},{"text":"almost-right word","bold":true},{"text":" for the right word, or simply avoid speaking his or her mind."}]},{"text":[{"text":"Meaning in words is largely a matter of agreement:","bold":true},{"text":" a word means what speakers agree it means. That is why a word from another language can become English once English speakers adopt it (e.g. "},{"text":"vuvuzela","bold":true},{"text":", only Zulu before the FIFA 2010 World Cup in South Africa, English afterwards)."}]},{"text":[{"text":"English vocabulary is vast because of "},{"text":"four main influences","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Anglo-Saxon:","bold":true},{"text":" the "},{"text":"basic form","bold":true},{"text":" of English and the bulk of words known as "},{"text":"Native English","bold":true},{"text":". The Anglo-Saxons were "},{"text":"three Germanic tribes","bold":true},{"text":": the "},{"text":"Angles, the Saxons and the Jutes","bold":true},{"text":", who invaded Britain (Britannia) in "},{"text":"450 AD","bold":true},{"text":" and settled. The land where the Angles settled was called "},{"text":"Angle-land","bold":true},{"text":", from which "},{"text":"England","bold":true},{"text":" comes. Later the "},{"text":"Norse and the Vikings","bold":true},{"text":" (Scandinavian tribes) also invaded, adding to the cultural mix."}]},{"text":[{"text":"Latin:","bold":true},{"text":" came in (a) through "},{"text":"Christianity","bold":true},{"text":" (Latin was the language of European Christianity, carried by the Roman church); (b) through the "},{"text":"Renaissance","bold":true},{"text":" in England, the rebirth of learning Greek and Roman classics. The Romans had invaded Britain long before the Anglo-Saxons but did "},{"text":"not interfere","bold":true},{"text":" with the native languages, "},{"text":"Gaelic, Celtic and Welsh","bold":true},{"text":"."}]},{"text":[{"text":"French:","bold":true},{"text":" through the "},{"text":"Norman Conquest of 1066 AD","bold":true},{"text":". French gave words for the "},{"text":"kitchen, cooking, government, administration and persons","bold":true},{"text":". French also entered English indirectly through Latin, because French is "},{"text":"80% Latin","bold":true},{"text":"."}]},{"text":[{"text":"Greek:","bold":true},{"text":" through the "},{"text":"Renaissance","bold":true},{"text":" and scholarly interest in Greek arts. To this day "},{"text":"scientists","bold":true},{"text":" use Greek to name inventions and discoveries."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example words by origin (exams ask \"which word came from...\"):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Anglo-Saxon:","bold":true},{"text":" everyday words: father, mother, son, wife, king, queen, house, home, sea, sheep, cow, dog, fire, bed, the numbers; tell, bring, drink, say, do, go, come, run, buy, sell, eat; dim, wise, good, little, brave, strong, merry; in, with, by, at, for, of, on, under; often, seldom; and, or, but, nor, until, because, unless."}]},{"text":[{"text":"Latin:","bold":true},{"text":" estate, clergy, pastor, janitor, temple, altar, choir, disciple, candle, priest, century, nun, communion, martyr, cross, rite, shrine, monk, mass, lily, robe, pear, virgin. Many are "},{"text":"church","bold":true},{"text":" words."}]},{"text":[{"text":"French:","bold":true},{"text":" vis-à-vis, souvenir, ambience, façade, milieu, elite, fiancée, mirage, genre, cuisine, vogue, faux pas, protégé, naïve, brochure, cliché, liaison, war, poultry, foyer, jacket, envoy, entrepreneur, debut, silhouette, courtesy, laissez-faire, connoisseur, camouflage, jargon, rapport, précis, résumé, chic, repertoire."}]},{"text":[{"text":"Greek:","bold":true},{"text":" alphabet, grammar, syllable, analysis, mystery, angel, myth, hymn, anecdote, rhetoric, logic, school, economics, apostle, anthology, chronicle, sympathy, pseudonym, epitaph, democracy, acrobat, geometry, "},{"text":"atmosphere","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Trap: the Anglo-Saxons are "},{"text":"three","bold":true},{"text":" tribes (Angles, Saxons, Jutes); the Norse and Vikings came "},{"text":"a few centuries later","bold":true},{"text":" and are not Anglo-Saxons."}]},{"text":[{"text":"Trap: the Norman Conquest is "},{"text":"French","bold":true},{"text":" influence (1066), not Latin. The Renaissance brought both "},{"text":"Latin and Greek","bold":true},{"text":"."}]}]}]},{"number":"9.2","title":"Two kinds of vocabulary, learning strategies and the dictionary","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2 kinds of vocabulary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active vocabulary:","bold":true},{"text":" the words a speaker "},{"text":"uses frequently","bold":true},{"text":" in spoken and written English."}]},{"text":[{"text":"Dormant or recognition vocabulary:","bold":true},{"text":" words a user "},{"text":"recognises","bold":true},{"text":" when seen or heard but "},{"text":"cannot clearly recall the meaning","bold":true},{"text":" of."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategies for growing vocabulary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Turn "},{"text":"recognition","bold":true},{"text":" vocabulary into "},{"text":"active","bold":true},{"text":" vocabulary: look up in the "},{"text":"dictionary","bold":true},{"text":" words that keep coming up in your reading, then "},{"text":"use them always","bold":true},{"text":" until you master them."}]},{"text":[{"text":"Keep your spoken and written English "},{"text":"simple","bold":true},{"text":" even as your vocabulary grows."}]},{"text":[{"text":"Build recognition vocabulary by "},{"text":"drawing new words","bold":true},{"text":" from the books you read and speeches you hear. "},{"text":"The wider your reading, the larger your recognition vocabulary.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A good dictionary is the basic tool","bold":true},{"text":" every student needs for effective study. It aids vocabulary development by giving "},{"text":"meanings","bold":true},{"text":", "},{"text":"pronunciation","bold":true},{"text":", "},{"text":"spelling","bold":true},{"text":" and "},{"text":"context of usage","bold":true},{"text":" (all of these)."}]},{"text":[{"text":"A dictionary tells you a word's "},{"text":"definition, spelling, usage, capitalisation, synonyms and antonyms, syllabication, word class and pronunciation","bold":true},{"text":"; unabridged ones add "},{"text":"etymology","bold":true},{"text":" (origin). It does "},{"text":"not","bold":true},{"text":" record the "},{"text":"year a word became obsolete","bold":true},{"text":" (at most it labels a word archaic)."}]},{"text":[{"text":"2 types of dictionary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"General (non-specialised):","bold":true},{"text":" wider coverage and usage. Two kinds: "},{"text":"unabridged","bold":true},{"text":" (contain most words of English with full details, some with etymology; the best source, so get one: e.g. Oxford Advanced Learner's Dictionary, Longman Dictionary of Contemporary English, BBC English Dictionary, Cambridge Dictionary of English) and "},{"text":"abridged","bold":true},{"text":" (shorter versions; guide spelling, capitalisation, punctuation and vocabulary; easy to carry: e.g. The Oxford Pocket Dictionary, Roget Pocket Dictionary, American Heritage Dictionary of the English Language, The Short Oxford English Dictionary). Always buy the "},{"text":"newest edition","bold":true},{"text":"."}]},{"text":[{"text":"Specialised (technical):","bold":true},{"text":" compiled for a "},{"text":"special purpose","bold":true},{"text":"; more thorough coverage of one subject. Three kinds:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dictionary of synonyms:","bold":true},{"text":" lists of words of "},{"text":"similar meaning","bold":true},{"text":". The "},{"text":"thesaurus","bold":true},{"text":" is designed for this. Examples: "},{"text":"Webster's Collegiate Thesaurus, Roget International Thesaurus, Modern Guide to Synonyms and Related Words","bold":true},{"text":"."}]},{"text":[{"text":"Scholarly dictionaries:","bold":true},{"text":" specialised in an area of learning: Oxford Dictionary of Philosophy / Psychology / Sociology, A Dictionary of Medical Terms, Standard Dictionary of Folklore, Mythology and Legend, Modern Science Dictionary, Medical Dictionary."}]},{"text":[{"text":"Usage dictionaries:","bold":true},{"text":" show "},{"text":"how words are used","bold":true},{"text":" in speech and writing; help with "},{"text":"collocation","bold":true},{"text":", "},{"text":"synonyms","bold":true},{"text":" and "},{"text":"common errors","bold":true},{"text":"."}]}]}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Collocation:","bold":true},{"text":" a group of words that habitually go together and behave like a "},{"text":"single word with a single meaning","bold":true},{"text":" (e.g. make a decision, earn a living)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"thesaurus","bold":true},{"text":" is a "},{"text":"specialised dictionary","bold":true},{"text":" (not simplified, pictorial or phonetic). Because it is a dictionary of synonyms, it is at once a "},{"text":"list of words","bold":true},{"text":", a set of "},{"text":"synonymous terms","bold":true},{"text":" and a "},{"text":"collection of selected terminology","bold":true},{"text":"; if an option says \"all of the above\", take it."}]},{"text":[{"text":"Other specialised dictionaries you may meet in questions: a "},{"text":"Dictionary of American Slang","bold":true},{"text":", a dictionary of a particular language (e.g. Yoruba), a dictionary of politics. "},{"text":"Webster's","bold":true},{"text":" and the "},{"text":"Oxford English Dictionary","bold":true},{"text":" are "},{"text":"general","bold":true},{"text":" dictionaries."}]},{"text":[{"text":"Usage example: instead of the vague word "},{"text":"thing","bold":true},{"text":", a usage dictionary suggests precise words: aspect, attribute, characteristic, detail, feature, issue, matter, point, subject, topic, trait. Say \"very useful\", not \"a very useful thing\"; \"something important\", not \"an important thing\"; \"so much\", not \"so many things\"."}]},{"text":[{"text":"Dictionary usage entries draw on classroom research and the "},{"text":"British National Corpus","bold":true},{"text":"."}]},{"text":[{"text":"Trap: dormant vocabulary is "},{"text":"not","bold":true},{"text":" unknown vocabulary; you recognise the word, you just cannot pin down its meaning. Unknown words are a third group."}]}]}]},{"number":"9.3","title":"Types of meaning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A word may have "},{"text":"two types of meaning","bold":true},{"text":", and "},{"text":"context","bold":true},{"text":" can add a third:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Denotative meaning:","bold":true},{"text":" the "},{"text":"literal","bold":true},{"text":" meaning; the meaning "},{"text":"lexicographers give a word and enter into the dictionary","bold":true},{"text":"; the meaning of a word "},{"text":"in isolation","bold":true},{"text":", making "},{"text":"direct reference","bold":true},{"text":" to a thing. Dark = lightlessness, no visibility; night = the hours outside daytime."}]},{"text":[{"text":"Connotative meaning:","bold":true},{"text":" meaning "},{"text":"associated with a word based on feelings, emotions and experiences","bold":true},{"text":"; an "},{"text":"underlying","bold":true},{"text":" meaning beyond the literal; it is "},{"text":"figurative","bold":true},{"text":", and it depends on the word's "},{"text":"environment and usage","bold":true},{"text":". \"He's dark\" = evil or malicious; \"in my dark moments\" = difficult, harsh, sorrowful times."}]},{"text":[{"text":"Contextual meaning (verbal context):","bold":true},{"text":" the meaning you work out for an unfamiliar word from the "},{"text":"other words in the sentence","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Useful clues to contextual meaning come from "},{"text":"paired words","bold":true},{"text":" or "},{"text":"parallelism","bold":true},{"text":". Paired words are either "},{"text":"complementary (parallel)","bold":true},{"text":", so the words are "},{"text":"similar","bold":true},{"text":" in meaning, or "},{"text":"contrasting","bold":true},{"text":", so they are "},{"text":"opposite","bold":true},{"text":" in meaning."}]},{"text":[{"text":"Poetic meaning","bold":true},{"text":" is usually "},{"text":"figurative","bold":true},{"text":" (connotative), not denotative."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Connotations may be "},{"text":"positive or negative","bold":true},{"text":". In the pairs persistent/stubborn, notorious/famous, secret/covert, smart/intelligent, light/fair, mountainous/huge, brilliant/clever, the word with the kinder feeling (persistent, famous, intelligent, fair, brilliant) has the positive connotation. "},{"text":"Persistent/stubborn","bold":true},{"text":" is the pair where one side ("},{"text":"stubborn","bold":true},{"text":") is clearly negative; light/fair, brilliant/clever and smart/intelligent are approving on both sides."}]},{"text":[{"text":"Worked examples of contextual clues:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Since he isn't "},{"text":"wasteful","bold":true},{"text":", he is "},{"text":"frugal","bold":true},{"text":"\": the negation of wasteful tells you frugal = careful with money (contrast)."}]},{"text":[{"text":"\"He was "},{"text":"unscrupulous","bold":true},{"text":" and "},{"text":"dishonest","bold":true},{"text":"\": paired by \"and\", so similar (complementary)."}]},{"text":[{"text":"\"Her "},{"text":"pulchritude","bold":true},{"text":" and "},{"text":"beauty","bold":true},{"text":" charmed the audience\": pulchritude is a synonym of beauty."}]},{"text":[{"text":"\"He's slow because he's a "},{"text":"tyro","bold":true},{"text":"\" = beginner. \""},{"text":"Vitriolic","bold":true},{"text":" remarks\" = angry. \"The counsel "},{"text":"prayed","bold":true},{"text":" the judge\" = pleaded. \"A "},{"text":"sneaking","bold":true},{"text":" suspicion\" = niggling."}]}]}]},{"text":[{"text":"Trap: options exams swap for \"denotative\": \"words used scientifically\", \"words which refer to the past\", \"listing in alphabetical order\". None is right; denotative words "},{"text":"make direct reference","bold":true},{"text":". \"Expressive\" and \"discursive\" are not types of meaning; the pair is "},{"text":"denotative/connotative","bold":true},{"text":"."}]}]}]},{"number":"9.4","title":"Word-formation strategies","mustKnow":[{"type":"paragraph","text":[{"text":"Words have entered English through various formation processes. The "},{"text":"processes of inventing words","bold":true},{"text":" are "},{"text":"coining, blending, compounding, clipping and reduplicating","bold":true},{"text":"; words are also formed by "},{"text":"affixation, neologism and acronyms","bold":true},{"text":" (8 processes in all)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coining:","bold":true},{"text":" creating a word or phrase for a "},{"text":"specific use","bold":true},{"text":", knowing it does not exist in the lexicon; the situation gives it meaning. Example: "},{"text":"\"wardrobe malfunction\"","bold":true},{"text":" (Janet Jackson). Others: skyjacker, skydiver, credibility gap, Clintonomics, normalcy, Oliver Twist (a person never contented), Casanova (a flirtatious man)."}]},{"text":[{"text":"Blending:","bold":true},{"text":" combining "},{"text":"part of one word with part of another","bold":true},{"text":"; the blend "},{"text":"shares the meaning of both","bold":true},{"text":". sit-com (situation + comedy), smog (smoke + fog), chillax (chill + relax), netiquette (internet + etiquette), camcorder (camera + recorder), chortle (chuckle + snort), telex (teleprinter + exchange), mimsy (miserable + flimsy). Also brunch, malware, webinar."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" the "},{"text":"easiest","bold":true},{"text":" method; combining "},{"text":"two or more existing (independent) words","bold":true},{"text":" to form a new word. Written as "},{"text":"one word","bold":true},{"text":" (boardroom, litterbug, sweatshop, linesman), "},{"text":"two words","bold":true},{"text":" (floppy disk, chat show, rummage sale, surrogate mother) or "},{"text":"hyphenated","bold":true},{"text":" (fail-safe, on-screen, one-upmanship, link-up)."}]},{"text":[{"text":"Clipping:","bold":true},{"text":" "},{"text":"shortening long words that are awkward in everyday speech","bold":true},{"text":"; part is clipped off, leaving the frequently used part. gov (governor), phone (telephone), bike (bicycle), exam (examination), lit (literature), civvy (civilian), lunch (luncheon); also ad, zoo, prep, gents, fax (facsimile)."}]},{"text":[{"text":"Reduplicating:","bold":true},{"text":" "},{"text":"doubling all or part of a word","bold":true},{"text":" with a single vowel or consonant change. hanky-panky, humdrum, boogie-woogie, helter-skelter, walkie-talkie, yum-yum, topsy-turvy, nitty-gritty, dilly-dally, titbit."}]},{"text":[{"text":"Acronym:","bold":true},{"text":" an abbreviation formed from the "},{"text":"initials","bold":true},{"text":" (or first two letters) of each word of a term; it becomes a word when added to the lexicon. Mostly from "},{"text":"names of organisations, inventions and discoveries","bold":true},{"text":". WAN (wide area network), VAT (value added tax), NASA, FIFA, NATO, OPEC, POTUS (President of the United States), scuba (self-contained underwater breathing apparatus), WYSIWYG (what you see is what you get)."}]},{"text":[{"text":"Affixation:","bold":true},{"text":" using "},{"text":"prefixes and suffixes","bold":true},{"text":" to form words (Lesson 9.5)."}]},{"text":[{"text":"Neologism:","bold":true},{"text":" the process in which "},{"text":"old words are given new meanings","bold":true},{"text":". Many dated words have taken on new meanings; some keep the old meaning as well."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Neologism examples (old meaning → new meaning): "},{"text":"nice","bold":true},{"text":" (pretending to be good → beautiful, kind, smart); "},{"text":"lady","bold":true},{"text":" (wife of a noble → spinster, single mother); "},{"text":"dull","bold":true},{"text":" (slow to learn → not flashy, boring); "},{"text":"first lady","bold":true},{"text":" (queen → wife of a president or governor); "},{"text":"promised land","bold":true},{"text":" (Canaan → a place of happiness and safety); "},{"text":"Waterloo","bold":true},{"text":" (a place name → a defeat); "},{"text":"bad","bold":true},{"text":" (unjust, wicked → dangerous, amazing). T. S. Eliot, in "},{"text":"Murder in the Cathedral","italic":true},{"text":", used "},{"text":"malevolence","bold":true},{"text":" so that his audience read it as \"violence by men\"."}]},{"text":[{"text":"Trap: in its widest sense a "},{"text":"neologism","bold":true},{"text":" is any "},{"text":"newly coined word or new meaning","bold":true},{"text":". So in a question like \"all but one are neologisms: atmosphere, brunch, malware, webinar\", the odd one out is "},{"text":"atmosphere","bold":true},{"text":", an old Greek-derived word; brunch, malware and webinar are recent blends. But when asked to "},{"text":"name the process in which old words get new meanings","bold":true},{"text":", the answer is "},{"text":"neologism","bold":true},{"text":", not coining (which makes a brand-new word) or blending."}]},{"text":[{"text":"Forms a word can take:","bold":true},{"text":" "},{"text":"simple","bold":true},{"text":" (one unit: table), "},{"text":"compound","bold":true},{"text":" (two or more independent words: suitcase, blackboard) and "},{"text":"complex","bold":true},{"text":" (a base with affixes: unreliable). "},{"text":"Compound-complex","bold":true},{"text":" is a type of "},{"text":"sentence","bold":true},{"text":", never a word form."}]},{"text":[{"text":"Trap: a blend joins "},{"text":"parts","bold":true},{"text":" of two words (smog); a compound joins "},{"text":"whole","bold":true},{"text":" words (boardroom); an acronym uses "},{"text":"initials","bold":true},{"text":" (NATO); clipping "},{"text":"cuts","bold":true},{"text":" one word (exam). \"Chopped\", \"chipped\" and \"crimped\" are not word-formation terms; the term is "},{"text":"clipped","bold":true},{"text":"."}]},{"text":[{"text":"Conversion","bold":true},{"text":" (changing a word's class without changing its form, e.g. \"to google\") is another process you may meet in options; it is not clipping."}]}]}]},{"number":"9.5","title":"Affixation and morphemes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Morpheme:","bold":true},{"text":" the smallest meaningful unit of a word."}]},{"text":[{"text":"Free morpheme:","bold":true},{"text":" can stand alone as a word (happy, boy, the). Free morphemes are sub-categorised into "},{"text":"lexical","bold":true},{"text":" (content words: nouns, verbs, adjectives, adverbs, e.g. boy, run, happy) and "},{"text":"functional","bold":true},{"text":" (grammar words: articles, prepositions, conjunctions, pronouns, e.g. the, of, and, she)."}]},{"text":[{"text":"Bound morpheme:","bold":true},{"text":" cannot stand alone; must attach to a free morpheme or root (un-, -ness, -ed). "},{"text":"Affixes are bound morphemes.","bold":true}]},{"text":[{"text":"Root (stem, base):","bold":true},{"text":" the part of a word "},{"text":"to which other elements can be added","bold":true},{"text":". The base of "},{"text":"educational","bold":true},{"text":" is "},{"text":"educate","bold":true},{"text":" (educate + -ion → education, + -al → educational)."}]},{"text":[{"text":"Affixes:","bold":true},{"text":" the general name for "},{"text":"prefixes and suffixes","bold":true},{"text":". "},{"text":"Affixation","bold":true},{"text":" is the "},{"text":"process","bold":true},{"text":" of adding them. "},{"text":"Every complex word contains an affix.","bold":true}]},{"text":[{"text":"Prefix:","bold":true},{"text":" a bound morpheme added at the "},{"text":"beginning","bold":true},{"text":" of a root (un- in unfaithful, unreliable). "},{"text":"Suffix:","bold":true},{"text":" a bound morpheme added at the "},{"text":"end","bold":true},{"text":" (-ly in happily)."}]},{"text":[{"text":"Unhappily = prefix (un-) + root (happy) + suffix (-ly).","bold":true}]},{"text":[{"text":"Affixes are "},{"text":"derivational","bold":true},{"text":" when they make a new word, changing the meaning and/or the word class (un- in unreliable; -ness in sadness), and "},{"text":"inflectional","bold":true},{"text":" when they only change tense or number without making a new word (-ed, -s)."}]},{"text":[{"text":"Suffix types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Noun-forming, added to verbs:","bold":true},{"text":" -al, -ance, -ion, -ment, -ure (arrival, severance, governance, domination, development, failure)."}]},{"text":[{"text":"Noun-forming, added to adjectives:","bold":true},{"text":" -dom, -ism, -cy, -ity, -ty, -ness, -th (freedom, socialism, normalcy, normality, loyalty, goodness, warmth)."}]},{"text":[{"text":"Noun-forming, added to nouns:","bold":true},{"text":" -age, -er, -hood, -ful, -dom, -ry, -ule (harbourage, worker, boyhood, handful, dukedom, forestry, globule)."}]},{"text":[{"text":"Adjective-forming, added to nouns:","bold":true},{"text":" -ful, -less, -ish (faithful, faithless, girlish)."}]},{"text":[{"text":"Verb-forming, added to adjectives:","bold":true},{"text":" -ize (socialize, idolize)."}]},{"text":[{"text":"Tense-forming, added to regular verbs:","bold":true},{"text":" -ed, -d (wanted, changed)."}]},{"text":[{"text":"Plural-forming:","bold":true},{"text":" -s, -es, -i, -ies, -ia, -ae (boys, classes, foci, criteria, personae)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Prefix types:","bold":true},{"text":" a "},{"text":"negative prefix","bold":true},{"text":" yields the "},{"text":"opposite","bold":true},{"text":" meaning of the root (a-, de-, dis-, contra-, mis-, im-, in-, retro-, un-). A "},{"text":"positive prefix","bold":true},{"text":" indicates "},{"text":"intensity, degree, emphasis or position","bold":true},{"text":" and does "},{"text":"not","bold":true},{"text":" form an antonym (extra-, post-, re-, sub-, semi-, co-, ultra-, hyper-, trans-, pro-, pre-, inter-, ante-, mega-, self-, circum-, bi-, mono-, pseudo- and others)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Affixation may "},{"text":"change meaning and word class","bold":true},{"text":" (govern → government), "},{"text":"change class but keep meaning","bold":true},{"text":" (arrive → arrival), or keep both while changing tense or number (wanted; boys)."}]},{"text":[{"text":"A "},{"text":"verb-forming prefix","bold":true},{"text":" can turn a noun into a verb: disgrace, imperil. A negative prefix on a negative word repositions it as positive: fetter → unfetter."}]},{"text":[{"text":"-ness","bold":true},{"text":" attaches to "},{"text":"adjectives","bold":true},{"text":" to make nouns: apt → aptness, just → justness, sad → sadness. It does not attach to an adverb (sadly) or to a word that is already a noun (comfort). If asked which of apt, sadly, comfort, just takes -ness \"by way of spelling\", the keyed answer is "},{"text":"apt","bold":true},{"text":" (aptness)."}]},{"text":[{"text":"anti-","bold":true},{"text":" means "},{"text":"against","bold":true},{"text":" (anti-social, antibiotic); do not confuse it with "},{"text":"ante-","bold":true},{"text":", which means "},{"text":"before","bold":true},{"text":" (antenatal). "},{"text":"-un","bold":true},{"text":" in unreliable is a "},{"text":"prefix","bold":true},{"text":", a "},{"text":"bound","bold":true},{"text":" morpheme and, more precisely, a "},{"text":"derivational","bold":true},{"text":" one, because it creates a new word with the opposite meaning."}]},{"text":[{"text":"Trap: a "},{"text":"phrase","bold":true},{"text":" is a group of words, not a word part. Prefix and suffix are the things "},{"text":"added","bold":true},{"text":"; the root is what they are added "},{"text":"to","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"grammatical\" is just another name for functional; the standard sub-categories of free morphemes are "},{"text":"lexical and functional","bold":true},{"text":"."}]}]}]},{"number":"9.6","title":"Choosing the right word: commonly confused pairs","mustKnow":[{"type":"paragraph","text":[{"text":"Good vocabulary means picking the "},{"text":"right","bold":true},{"text":" word, not the almost-right one. Learn these tested pairs:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Discover / invent:","bold":true},{"text":" you "},{"text":"discover","bold":true},{"text":" what already exists (a planet, a mineral); you "},{"text":"invent","bold":true},{"text":" what did not exist until someone made it. "},{"text":"Who ","italic":true},{"text":"invented","bold":true,"italic":true},{"text":" the telephone?","italic":true}]},{"text":[{"text":"Persuaded / convinced:","bold":true},{"text":" "},{"text":"convinced","bold":true},{"text":" = made to "},{"text":"believe","bold":true},{"text":" a fact is true; "},{"text":"persuaded","bold":true},{"text":" = talked into "},{"text":"doing","bold":true},{"text":" something. "},{"text":"The judge was ","italic":true},{"text":"convinced","bold":true,"italic":true},{"text":" that the man was guilty.","italic":true}]},{"text":[{"text":"Took / received:","bold":true},{"text":" a prize is "},{"text":"given","bold":true},{"text":", so the winner "},{"text":"receives","bold":true},{"text":" it; "},{"text":"took","bold":true},{"text":" suggests seizing. "},{"text":"He ","italic":true},{"text":"received","bold":true,"italic":true},{"text":" a prize for his diligence.","italic":true}]},{"text":[{"text":"Interfere in / interfere with:","bold":true},{"text":" you "},{"text":"interfere in","bold":true},{"text":" affairs that are not your business; something "},{"text":"interferes with","bold":true},{"text":" another thing by disturbing or blocking it (noise interferes with reading). "},{"text":"It is not wise to ","italic":true},{"text":"interfere in","bold":true,"italic":true},{"text":" family quarrels.","italic":true}]},{"text":[{"text":"Accept / agree:","bold":true},{"text":" "},{"text":"agree to","bold":true},{"text":" do something (say yes to a request); "},{"text":"accept","bold":true},{"text":" takes a noun object (accept an offer), never \"to go\". "},{"text":"She did not ","italic":true},{"text":"agree","bold":true,"italic":true},{"text":" to go.","italic":true}]},{"text":[{"text":"Deals with / deals in:","bold":true},{"text":" "},{"text":"deal in","bold":true},{"text":" = buy and sell as a trade; "},{"text":"deal with","bold":true},{"text":" = handle or manage a problem or person. "},{"text":"A butcher ","italic":true},{"text":"deals in","bold":true,"italic":true},{"text":" meat.","italic":true}]},{"text":[{"text":"Earn / win:","bold":true},{"text":" you "},{"text":"earn","bold":true},{"text":" a living (by work); you "},{"text":"win","bold":true},{"text":" prizes, games, competitions. "},{"text":"How does that man ","italic":true},{"text":"earn","bold":true,"italic":true},{"text":" his living?","italic":true}]},{"text":[{"text":"Remember / remind:","bold":true},{"text":" to "},{"text":"remind","bold":true},{"text":" someone is to make them remember; you "},{"text":"remember","bold":true},{"text":" for yourself. "},{"text":"Please ","italic":true},{"text":"remind","bold":true,"italic":true},{"text":" me to give the money back.","italic":true}]},{"text":[{"text":"Avenged / revenged:","bold":true},{"text":" to "},{"text":"avenge","bold":true},{"text":" a wrong is to punish the wrongdoer "},{"text":"on behalf of a victim","bold":true},{"text":", in the name of justice; "},{"text":"revenge","bold":true},{"text":" is personal retaliation (revenge yourself on an enemy). "},{"text":"The judge ","italic":true},{"text":"avenged","bold":true,"italic":true},{"text":" the wrong done to the child.","italic":true}]},{"text":[{"text":"Love / like:","bold":true},{"text":" "},{"text":"love","bold":true},{"text":" is deep and intense; "},{"text":"like","bold":true},{"text":" is weak (find pleasant). "},{"text":"Some people ","italic":true},{"text":"love","bold":true,"italic":true},{"text":" freedom so much that they are ready to die for it.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Test each pair by the "},{"text":"object","bold":true},{"text":" it takes: invent a device, discover a fact; convinced "},{"text":"that","bold":true},{"text":", persuaded "},{"text":"to","bold":true},{"text":"; agree "},{"text":"to go","bold":true},{"text":", accept "},{"text":"an invitation","bold":true},{"text":"; deal "},{"text":"in","bold":true},{"text":" goods, deal "},{"text":"with","bold":true},{"text":" people or problems; earn "},{"text":"money","bold":true},{"text":", win "},{"text":"a match","bold":true},{"text":"."}]},{"text":[{"text":"Check the "},{"text":"strength","bold":true},{"text":" of the word: the seriousness of \"ready to die for it\" tells you "},{"text":"love","bold":true},{"text":", not like."}]},{"text":[{"text":"These are the \"almost-right word\" errors a weak vocabulary produces; a usage dictionary lists them under common errors."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vocabulary = the total stock of words in a language; English has about one million words, Shakespeare used 21,000, most learners know under 10,000."}]},{"text":[{"text":"Sources of English words: Anglo-Saxon (Angles, Saxons, Jutes, 450 AD; Native English), Latin (Christianity, Renaissance), French (Norman Conquest 1066), Greek (Renaissance, science)."}]},{"text":[{"text":"Active vocabulary = words you use; dormant/recognition = words you recognise but cannot define. Grow both by reading widely and using the dictionary."}]},{"text":[{"text":"Dictionaries: general (unabridged, abridged) and specialised (synonyms/thesaurus, scholarly, usage). A thesaurus is a specialised dictionary of synonyms."}]},{"text":[{"text":"Denotative = literal, dictionary, in isolation; connotative = feelings, figurative, context; contextual meaning comes from paired words (complementary = similar, contrasting = opposite)."}]},{"text":[{"text":"Word formation: coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism (old words, new meanings)."}]},{"text":[{"text":"Word forms: simple, compound, complex; compound-complex is a sentence type."}]},{"text":[{"text":"Morphemes: free (lexical, functional) and bound (affixes). Prefix + root + suffix (un-happi-ly). Every complex word has an affix."}]},{"text":[{"text":"anti- = against; ante- = before. -ness makes nouns from adjectives."}]},{"text":[{"text":"Right word: invent/discover, convinced/persuaded, received, interfere in, agree to, deal in, earn a living, remind, avenge, love."}]}]}],"theory":{"itemId":"d71fc0df-1a2a-52a9-8b1f-20622cedf9bd","question":[{"type":"paragraph","text":[{"text":"Distinguish between denotative and connotative meaning, and explain how verbal context helps a reader work out the meaning of an unfamiliar word."}]}]},"practice":[{"topic":"Vocabulary Development","named":false}]}}]$expected_content$::jsonb,
  'use-of-english: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('40000000-0000-4000-8000-000000000008')
  where kind = 'cbt_question'), 0,
  'use-of-english: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '40000000-0000-4000-8000-000000000008' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"adea6f5c-bb94-5d06-8888-7b95eebc18e2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cdb88813-bb4d-5192-8483-44b01245c9f6","sourceKey":"bank:GST111:G111N1-001","parentItemId":null,"revision":1,"payload":{"prompt":"A 100L student at UNILAG who is grieving the loss of a relative finds it hard to follow a lecture. Which condition is causing her ineffective listening?","options":["The linguistic condition of the lecture","The psychological condition of the listener","The physiological condition of the lecturer","The physical condition of the environment"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Grief is an emotional state, and the emotional state or mind of the listener is a psychological condition. The physical condition refers to the environment, such as noise or poor ventilation, not to the listener's feelings."}},{"itemId":"6a81d1a7-8662-5bab-83e7-07f1137e1e7f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e95cdf7b-1f3c-53cc-ab89-d7ac6ec3f612","sourceKey":"bank:GST111:G111N1-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a purpose of formal listening?","options":["To analyse a method or step","To evaluate or criticise a theory or argument","To improve social relationships in normal conversation","To remember a formula or concept"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Improving relationships is what informal listening does in normal conversation. Evaluating a theory, remembering a formula and analysing a method are all purposes of formal listening in academic settings such as classes."}},{"itemId":"7a9c7df6-ee89-52d7-a8b8-0da2e687e62d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7719c94d-6ab0-577a-b8fa-e238375347f2","sourceKey":"bank:GST111:G111N1-003","parentItemId":null,"revision":1,"payload":{"prompt":"The skill of keeping a record of a speaker's message and recording the essential points from written materials is called","options":["note-taking","transcription","paraphrasing","skimming"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Note-taking is exactly this: keeping a record of what a speaker says and of the essential points in written texts. Paraphrasing is only one skill used within note-taking, namely restating an idea in your own words."}},{"itemId":"c05ec53e-4291-50d4-8360-2dd82060a190","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4ec277a8-6df0-550c-b201-0dc75e2b3968","sourceKey":"bank:GST111:G111N1-004","parentItemId":null,"revision":1,"payload":{"prompt":"To take notes effectively, a student needs skill in which of the following?","options":["Using a different set of symbols for each lecture","Writing down only the speaker's examples","Citing and referencing sources correctly","Recording everything the speaker says word for word"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Citing and referencing the works you use correctly is one of the six requirements for effective note-taking. Recording everything word for word is wrong because effective note-taking reduces content to a short, summarised form and avoids verbatim writing."}},{"itemId":"57c026bd-1bab-5d4e-ba5b-20572302a7b0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9a0a8d38-0fe0-5afa-99e0-bb472ba8f9cf","sourceKey":"bank:GST111:G111N1-005","parentItemId":null,"revision":1,"payload":{"prompt":"A lecturer in a firm's training session in Ikeja first explains what drives inflation in Nigeria and then explains what inflation does to households. Which organising principle is the lecture following?","options":["Past to present","General to specific","Problem and solution","Cause and result"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Moving from what produces something to what it leads to is the cause-and-result organising principle. Problem and solution would require the speaker to propose remedies, which this talk does not do."}},{"itemId":"0e01783f-0efd-5e6a-a73e-e4b63fab7bdd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"83d78fe2-a448-5df4-b828-b0b4f8cad076","sourceKey":"bank:GST111:G111N1-006","parentItemId":null,"revision":1,"payload":{"prompt":"While listening to a lecture, words such as 'in addition', 'however', 'moreover' and 'consequently' should be noted as","options":["visual illustrations","phonological cues","non-verbal cues","transition cues"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"These connecting words are transition cues that show how the speaker's ideas link and where the talk is heading. Phonological cues are features of the voice, such as accent, stress and speed, not linking words."}},{"itemId":"d412e10e-909f-5ae0-aa90-add6fe9e3a85","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b07d7268-5e01-5393-8a1b-26b34e0a2f47","sourceKey":"bank:GST111:G111N1-007","parentItemId":null,"revision":1,"payload":{"prompt":"During a lecture, changes in the lecturer's voice, accent, word stress and speed are examples of","options":["transition cues","phonological cues","visual illustrations","non-verbal cues"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Features carried by the sound of the voice, such as accent, word stress, speed and emotional nuance, are phonological cues. Non-verbal cues are different because they are seen, not heard: facial expressions, gestures and body movement."}},{"itemId":"42bb685c-cbe1-557f-b57d-19b0b6304f5d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f59dbfd3-c9d3-5c4e-aaaa-0e99f94e3b45","sourceKey":"bank:GST111:G111N1-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an AFTER-lecture activity for effective note-taking?","options":["Checking new words related to the topic","Preparing the format of your notes","Arriving early and sitting close to the lecturer","Comparing your notes with those of course-mates"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Comparing what you wrote with course-mates soon after the class helps you fill in gaps. Arriving early and sitting close to the speaker is a step taken before the class, as are checking new words and preparing the format you will write in."}},{"itemId":"55564b8e-d4c7-5efa-9619-39f7168da35f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"803a2a31-7582-5fcb-95e1-debe35987264","sourceKey":"bank:GST111:G111N1-009","parentItemId":null,"revision":1,"payload":{"prompt":"In note-taking, the abbreviation 'c.f.' stands for","options":["that is","note well","including","confer or compare"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"'c.f.' means confer, that is, compare one point with another. 'That is' is written as 'i.e.', 'note well' as 'NB' and 'including' as 'incl.'."}},{"itemId":"3e71549b-b898-5926-99ef-748befd1af70","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"34d8d292-a5d0-500f-826d-fae8fcbea0a2","sourceKey":"bank:GST111:G111N1-010","parentItemId":null,"revision":1,"payload":{"prompt":"A student deliberately ignores her tribal and religious bias against a guest lecturer so that she can follow his argument. Which listening strategy is she applying?","options":["Avoiding hasty generalisations","Suppressing emotional attachment","Treating listening as a mental challenge","Asking mental questions"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Putting aside religious, cultural, tribal or financial bias and personal emotions is the strategy of suppressing emotional attachment. Avoiding hasty generalisations is about waiting for the speaker to finish before drawing conclusions, which is a different strategy."}},{"itemId":"41c85ec9-4473-5476-ad5b-781082d0b8bd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7f891fa5-9b51-5a9c-8f05-1f1cbd91902f","sourceKey":"bank:GST111:G111N1-011","parentItemId":null,"revision":1,"payload":{"prompt":"When taking notes, where should you write your own thoughts about what the lecturer is saying?","options":["Mixed in with the lecturer's main points","In a separate column or in the margin","In a separate notebook kept at home","Nowhere, because personal thoughts are not allowed"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Your own thoughts should be added in a separate column or in the margin so that they stay distinct from the speaker's points. Mixing them in with the main points makes it hard to tell later which ideas came from the speaker."}},{"itemId":"19d29d02-0171-5716-bd36-7e2f7fd44b27","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f17165d0-7658-5159-8b70-e458a775ae0b","sourceKey":"bank:GST111:G111N1-012","parentItemId":null,"revision":1,"payload":{"prompt":"Of the 20 vowel sounds of English, how many are pure vowels (monophthongs)?","options":["12","20","24","8"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"English has 20 vowels made up of 12 pure vowels and 8 diphthongs. The figure 8 is the number of diphthongs, not of pure vowels."}},{"itemId":"d1a028bb-8fe4-5adf-9c3a-0a83ce7b45f7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dc222962-9235-5ce1-b50c-1705bc66e2cc","sourceKey":"bank:GST111:G111N1-013","parentItemId":null,"revision":1,"payload":{"prompt":"How many diphthongs are there in English?","options":["3","8","12","5"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"English has 8 diphthongs, made up of 5 closing diphthongs and 3 centring diphthongs. The figure 5 counts only the closing group, not all the diphthongs."}},{"itemId":"99ea38f9-cd8c-515c-a817-2b1fa890c975","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"42ab1290-0070-5c88-88f6-accb42763b4a","sourceKey":"bank:GST111:G111N1-014","parentItemId":null,"revision":1,"payload":{"prompt":"How many of the English diphthongs are closing (rising) diphthongs?","options":["5","8","12","3"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Five of the eight diphthongs are closing: they start with a mid or low element and glide to a high one. The other 3 are the centring diphthongs, which end in the schwa."}},{"itemId":"fca8daf8-fa9b-5c7c-a2ab-8baf73991b03","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"89e9d931-fa78-5247-a041-b36548e6ede8","sourceKey":"bank:GST111:G111N1-015","parentItemId":null,"revision":1,"payload":{"prompt":"The centring diphthongs of English are so called because they all end in","options":["a back rounded vowel","a nasal consonant","a high front vowel","the schwa, a central vowel"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"A centring diphthong glides towards the centre of the mouth and ends in the schwa. Ending in a high vowel is what marks the closing diphthongs instead."}},{"itemId":"7173262b-e754-500e-8936-635bd4256e27","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"345497aa-1662-5557-9bdd-6803d110bba0","sourceKey":"bank:GST111:G111N1-016","parentItemId":null,"revision":1,"payload":{"prompt":"How many consonant phonemes does English have?","options":["24","12","44","20"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Of the 44 English phonemes, 24 are consonants and 20 are vowels. The figure 44 is the total of all sounds, not the consonants alone."}},{"itemId":"d68114b8-9e8f-5f0c-ae43-20f6caa62300","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"618740b0-a13c-51f7-bd50-7900f6166625","sourceKey":"bank:GST111:G111N1-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the parameters for describing English consonants?","options":["State of the glottis","Place of articulation","Manner of articulation","Lip rounding"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Consonants are described by place of articulation, manner of articulation and the state of the glottis (voicing). Lip rounding is one of the parameters used for vowels, not consonants."}},{"itemId":"e83972bd-0a39-540b-aac9-873e988b31b4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dba62e6d-4e34-551d-a9d3-63a29419d3a1","sourceKey":"bank:GST111:G111N1-018","parentItemId":null,"revision":1,"payload":{"prompt":"English vowels are described WITHOUT reference to which of the following?","options":["Tongue height","Manner of articulation","Lip rounding","Duration"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are described by tongue height, tongue horizontality, lip rounding and duration, not by place or manner. Manner of articulation belongs to consonants, which involve an obstruction of the airflow."}},{"itemId":"7297502a-eff4-5fe3-9ecb-68ca87e5bfa9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"21357bd8-c322-5699-a435-0acd88c6e3eb","sourceKey":"bank:GST111:G111N1-019","parentItemId":null,"revision":1,"payload":{"prompt":"When the glottis is wide open so that air passes freely through it, the sound produced is","options":["voiceless","lateral","voiced","nasal"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"An open glottis lets the air through without making the vocal folds vibrate, so the sound is voiceless. A voiced sound needs the glottis nearly closed so that the folds vibrate."}},{"itemId":"3b0f9565-406f-5590-b408-591cfe9af59f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2b047441-3599-5dcb-9ff5-66f8c6d8b1bd","sourceKey":"bank:GST111:G111N1-020","parentItemId":null,"revision":1,"payload":{"prompt":"The gap between the vocal folds is called the","options":["larynx","glottis","pharynx","velum"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The glottis is the space between the two vocal folds. The larynx is the structure that houses the vocal folds, not the gap between them."}},{"itemId":"425b0bfb-9eb6-5eac-92c5-8f77533269e8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e807ae21-5552-5f3c-9d9b-6a03f4a351f9","sourceKey":"bank:GST111:G111N1-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which articulator is a muscular flap that is raised to shut off the nasal tract?","options":["The alveolar ridge","The hard palate","The soft palate","The glottis"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"The soft palate (velum) is the muscular flap that rises to close off the nose. The hard palate is the bony front part of the roof of the mouth and cannot move."}},{"itemId":"b894e42e-d54b-5b7a-92b0-19bcafd31c23","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"aed3972a-5d7f-5b2f-b513-0a52039cf2b4","sourceKey":"bank:GST111:G111N1-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the most flexible articulator?","options":["The lips","The tongue","The soft palate","The lower teeth"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The tongue is the most flexible articulator, with parts such as the tip, blade, front, centre, back and root. The lips are also active articulators, but they are less flexible than the tongue."}},{"itemId":"78ca03fb-938d-5bcb-9d8c-5a0213eb012c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"28db6706-d0a6-538e-837b-c6eaa0da6f11","sourceKey":"bank:GST111:G111N1-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a passive (fixed) articulator?","options":["The hard palate","The tongue","The soft palate","The lips"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Passive articulators do not move; the teeth and the hard palate are the fixed ones. The soft palate looks close to the hard palate but it is movable, so it is an active articulator."}},{"itemId":"63fa5203-db51-5adc-9897-9008e32f733f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e376783b-5db0-5939-ba23-f9ebce1799a5","sourceKey":"bank:GST111:G111N1-024","parentItemId":null,"revision":1,"payload":{"prompt":"Consonants produced with a closure in the mouth and the velum lowered, so that the air escapes through the nose, are called","options":["laterals","fricatives","approximants","nasals"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Nasals such as /m/ and /n/ block the mouth while the lowered velum lets the air out through the nose. A lateral, such as /l/, lets the air pass along the sides of the tongue instead."}},{"itemId":"5a20d873-b6d6-50fd-a8d9-4db799c63556","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cc97654b-56ce-5c6e-a923-e690a3a10d4d","sourceKey":"bank:GST111:G111N1-025","parentItemId":null,"revision":1,"payload":{"prompt":"The approximants /w/ and /j/ form the sub-group of sounds known as","options":["glides","affricates","laterals","liquids"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"/w/ and /j/ are the glides within the approximant class. Liquids is the name given to /l/ and /r/ together."}},{"itemId":"c4935ee1-9c60-5588-9ae0-66ed944e6c20","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b138797f-1d1b-5fe6-bddc-e3bec9084bd5","sourceKey":"bank:GST111:G111N1-026","parentItemId":null,"revision":1,"payload":{"prompt":"Taken together, the consonants /l/ and /r/ are known as","options":["stops","liquids","glides","nasals"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/l/ and /r/ are grouped together as the liquids. The glides are /w/ and /j/, a different sub-group."}},{"itemId":"481543ca-2fda-5814-b79f-7483eabe181f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"630391e2-b1c1-51a5-936e-bc82a625e7a8","sourceKey":"bank:GST111:G111N1-027","parentItemId":null,"revision":1,"payload":{"prompt":"Using the order voicing, place, manner, the English consonant /p/ is described as a","options":["voiceless labio-dental fricative","voiced bilabial stop","voiceless bilabial stop","voiceless alveolar stop"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/p/ is made with both lips (bilabial), with total closure and sudden release (stop), and without vibration of the vocal folds (voiceless). A voiced bilabial stop describes /b/, the voiced partner of /p/."}},{"itemId":"5156c8ee-2a70-5fdb-bc83-f1a9e5ed10ce","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7b158f78-f45f-50a5-8e89-caac506dc59b","sourceKey":"bank:GST111:G111N1-028","parentItemId":null,"revision":1,"payload":{"prompt":"The consonants /f/ and /v/ share the same place of articulation, which is","options":["bilabial","labio-dental","dental","alveolar"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/f/ and /v/ are made with the lower lip against the upper teeth, so they are labio-dental. Bilabial sounds use both lips, as in /p/, /b/ and /m/."}},{"itemId":"8c0f2c47-13bb-53f2-ad28-41937af90a4d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"71ce21a5-65af-57e8-a37c-eb5b99bd7ae0","sourceKey":"bank:GST111:G111N1-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair of English consonants is velar?","options":["/f/ and /v/","/k/ and /g/","/p/ and /b/","/t/ and /d/"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/k/ and /g/ are made with the back of the tongue against the soft palate (velum), so they are velar. /t/ and /d/ are also stops, but they are alveolar."}},{"itemId":"a2aff879-e38d-584f-b1eb-43d541f10a05","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b28a0459-3c63-5d89-9eb7-ae9fd66f53ec","sourceKey":"bank:GST111:G111N1-030","parentItemId":null,"revision":1,"payload":{"prompt":"The fact that the letter 'a' is pronounced differently in 'gate', 'woman', 'many' and 'village' shows that","options":["each English letter has one fixed sound","English spelling reliably shows pronunciation","the letter 'a' is always a diphthong","English has little or no sound-letter correspondence"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"The same letter stands for different sounds in these words, so English spelling does not match its sounds closely. That is why spelling cannot be trusted to show how a word is pronounced."}},{"itemId":"b2f02613-f683-5b69-a541-6ffd682e033e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ab171a7c-9677-5e56-9e1d-82b6db36c6eb","sourceKey":"bank:GST111:G111N1-031","parentItemId":null,"revision":1,"payload":{"prompt":"How many sounds are there in the word 'trust'?","options":["5","4","6","3"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"'trust' has five sounds: /t/, /r/, the short vowel heard in 'cut', /s/ and /t/. A common mistake is to count 4 by treating the cluster 'tr' or 'st' as a single sound."}},{"itemId":"e3ad04ef-ee9e-54fe-8929-8da9dfb371ac","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f39ff3e3-e2ea-57ba-9da9-10e6d7a6f80f","sourceKey":"bank:GST111:G111N1-032","parentItemId":null,"revision":1,"payload":{"prompt":"The theory that a syllable corresponds to one puff of air from the intercostal muscles is the","options":["Chest Pulse Theory","Coda Theory","Prominence Theory","Peak Theory"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The Chest Pulse Theory links each syllable to a single puff of air pushed out by the intercostal muscles. The Prominence Theory instead defines the syllable by the most prominent or sonorous sound in its environment."}},{"itemId":"b4010ef8-2d31-5a39-a939-84b7d3cea9d4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7e2fbf09-1577-5983-ab5b-5db2318227a1","sourceKey":"bank:GST111:G111N1-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following words is a closed syllable?","options":["tea","no","slow","slap"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A closed syllable ends in a consonant (a coda), and 'slap' ends in /p/. 'slow', 'tea' and 'no' all end in a vowel sound, so they are open syllables."}},{"itemId":"145118f6-e0d5-56cb-a056-4676220d19fd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6a7233e1-258e-59f7-a8bf-7d765d888089","sourceKey":"bank:GST111:G111N1-035","parentItemId":null,"revision":1,"payload":{"prompt":"A student asks a stranger, 'Where is the Faculty of Management Sciences?' to get new information. Which tune is normally used?","options":["Falling-rising","Falling","Rising","Rising-falling"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Wh-questions that seek new information are said on a falling tune. A rising tune is used for yes/no questions and for wh-questions that ask someone to repeat what was said, which is not the case here."}},{"itemId":"6336cefd-1ef4-57ec-ba9c-8efb8583a1ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"135c6eb4-083a-5274-8328-a0f1e1636a40","sourceKey":"bank:GST111:G111N1-036","parentItemId":null,"revision":1,"payload":{"prompt":"By the end of a university programme, a student's reading speed should be about","options":["600 words per minute","300 words per minute","200 words per minute","1,000 words per minute"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The target for reading efficiency is about 600 words per minute by the end of your programme, and it improves only with practice. Lower figures such as 300 words per minute fall well short of this target."}},{"itemId":"ab99d70e-4abf-5c9d-a688-e45f4021947f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0bf414b4-f35a-5cf2-ad4f-f1780cd91b2e","sourceKey":"bank:GST111:G111N1-037","parentItemId":null,"revision":1,"payload":{"prompt":"The relationship between the physical aspect of reading and reading speed, which in turn affects comprehension, is known as","options":["span of recognition","reading efficiency","study reading","skimming"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading efficiency means having the right skills for efficient physical and mental processing, linking the physical act of reading to speed and comprehension. Span of recognition is narrower: it is only how many words you take in at each eye fixation."}},{"itemId":"f248d00a-7b87-5019-ac4f-47bca8f35ef8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"60cac6c1-97f3-58f5-8091-f1c5165f3540","sourceKey":"bank:GST111:G111N1-038","parentItemId":null,"revision":1,"payload":{"prompt":"A student in Lagos accepts every claim in a newspaper simply because it has been printed. Which misconception about reading does she hold?","options":["Everything can be read the same way","Everything in print is true","You must read everything","Everything on a page is equally important"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Trusting a claim just because it is printed is the misconception that everything in print is true; a critical reader separates facts from opinions. Believing that everything on a page is equally important is a different misconception, about what to focus on rather than what to believe."}},{"itemId":"88f3bf3c-6514-5aba-bf70-66dc27d2424d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fa1fcc80-c291-5c7d-81b4-779ac53f2361","sourceKey":"bank:GST111:G111N1-039","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four misconceptions about reading?","options":["Everything can be read the same way","Reading speed is related to comprehension","Everything on a page is equally important","You must read everything"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Scholars agree that reading speed is directly related to comprehension, so this is a true statement, not a misconception. Believing that you must read everything is one of the four false ideas."}},{"itemId":"f3971742-67e5-5c43-a671-917a8c3e46f8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"aafb92c5-5563-5cd4-b2e9-74d01a481510","sourceKey":"bank:GST111:G111N1-040","parentItemId":null,"revision":1,"payload":{"prompt":"A reader who moves his lips or whispers the words while reading silently has the bad habit called","options":["regression","finger-pointing","vocalisation","sub-vocalisation"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Moving the lips or vocal apparatus, or whispering, is vocalisation. Sub-vocalisation is close but different: the words are pronounced only in the mind with no movement."}},{"itemId":"7aa42c13-daf1-5cca-9b19-887fc5176040","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3eecff55-ead1-51bc-afa6-d11906cd0791","sourceKey":"bank:GST111:G111N1-041","parentItemId":null,"revision":1,"payload":{"prompt":"Pronouncing words in the mind while reading, without any movement of the lips, is called","options":["vocalisation","word-by-word reading","regression","sub-vocalisation"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Sub-vocalisation is saying the words silently in the mind, and it slows reading down. Vocalisation involves visible lip movement or whispering, which is not happening here."}},{"itemId":"bea19797-6422-535a-a9d2-6363a4544d8d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7f7aba28-0ec7-5a0b-a8c1-b0aa89a1362e","sourceKey":"bank:GST111:G111N1-042","parentItemId":null,"revision":1,"payload":{"prompt":"A reader who recognises only one or two words at each eye fixation has","options":["regression","erratic eye movement","sub-vocalisation","a short span of recognition"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Taking in only one or two words per fixation is a short span of recognition, a bad habit; a good reader has a wide span. Erratic eye movement is about the eyes failing to move rhythmically from phrase to phrase."}},{"itemId":"90c86a0d-d1d8-5d59-8023-b7c7a162b6d4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"68e52bcc-533d-5f89-94ed-498aad2c355f","sourceKey":"bank:GST111:G111N1-043","parentItemId":null,"revision":1,"payload":{"prompt":"To avoid erratic eye movement, a reader's eyes should move","options":["along the line by following a pointing finger","together with the head from side to side","from the first letter of each word to the next","rhythmically from the middle of one phrase to the middle of the next"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Good readers move their eyes in a steady rhythm from the middle of one phrase to the middle of the next. Following a pointing finger is itself a bad habit, and moving the head is another, since only the eye muscles should be used."}},{"itemId":"afadfbd9-efa3-524f-962b-ecae70a5d288","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8ee0f705-55bf-5a83-9f2b-b117605da771","sourceKey":"bank:GST111:G111N1-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a bad reading habit?","options":["Previewing before reading","Reading with intent","Finger-pointing","Annotating in the margin"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Finger-pointing is one of the eight reading deficiencies or bad habits, along with vocalisation and regression. Previewing, annotating and reading with intent are all recommended strategies for reading efficiently."}},{"itemId":"541a96e5-98c2-5253-b579-e886925d11b2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7483c2f7-6199-597d-a324-469145914534","sourceKey":"bank:GST111:G111N1-045","parentItemId":null,"revision":1,"payload":{"prompt":"Regression, the habit of glancing back to re-read, is usually caused by","options":["reading with intent","poor concentration","a wide span of recognition","previewing the text"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Regression usually comes from poor concentration; some is acceptable, but too much hinders reading. A wide span of recognition is a sign of a good reader, so it does not cause regression."}},{"itemId":"a91ccfa9-3bb7-5b69-b2eb-b4efe33ea466","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2a480302-c095-5ce0-beaa-b48a4dd55418","sourceKey":"bank:GST111:G111N1-046","parentItemId":null,"revision":1,"payload":{"prompt":"What is the correct order of the three stages of reading efficiently?","options":["Preview before reading, review after reading, read with intent","Review before reading, read with intent, preview after reading","Preview before reading, read with intent, review after reading","Read with intent, preview before reading, review after reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"You first preview the text, then read it with intent, and finally review it after reading. Putting reading with intent first skips the preview stage, where skimming and connecting to your experience take place."}},{"itemId":"4877d345-72c5-523a-9cb5-2196f89fc5f6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fe08b989-39c3-5478-b3c9-c024524db031","sourceKey":"bank:GST111:G111N1-047","parentItemId":null,"revision":1,"payload":{"prompt":"Highlighting key points and annotating your impressions belong to which stage of reading efficiently?","options":["Reading with intent","Skimming the text","Reviewing after reading","Previewing before reading"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When reading with intent you search for key elements, highlight key points and annotate your impressions. Reviewing after reading then focuses on the highlights and annotations already made, rather than creating them."}},{"itemId":"f9c22bc8-45c1-5feb-a94d-f828f646ccb3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0f2d5e88-b333-5771-af51-444f4e6125f2","sourceKey":"bank:GST111:G111N1-048","parentItemId":null,"revision":1,"payload":{"prompt":"When reading with intent, the author's main point is usually found in the","options":["thesis statement","blurb on the cover","concluding paragraph","index at the back"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The author's main point is usually stated in the thesis statement in the first or second paragraph, though it may only be implied. The conclusion is a separate key element that closes the text rather than stating the main point first."}},{"itemId":"52ef1041-ccee-5d5b-9caa-0b8f30354305","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"027e87ea-b5d6-568f-b1ea-19cc95ac8c2a","sourceKey":"bank:GST111:G111N1-049","parentItemId":null,"revision":1,"payload":{"prompt":"Personal comments that a reader writes in the margin of a text are called","options":["previews","annotations","highlights","graphic organisers"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Annotation means writing your own comments in the margin, such as important points, questions and inconsistencies. Highlighting only marks words already in the text and adds nothing of your own."}},{"itemId":"e5659ee6-c80d-557a-8b45-202f26fc3d02","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4fe16d3c-049f-5db7-ad57-4f6e4c79eb2c","sourceKey":"bank:GST111:G111N1-050","parentItemId":null,"revision":1,"payload":{"prompt":"A diagram that shows the structure of the main points of a text, especially useful when the text is difficult, is a","options":["abstract","annotation","table of contents","graphic organiser"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"A graphic organiser is a diagram of how the main points fit together, and it helps with difficult texts. A table of contents lists chapters or sections; it does not map how the ideas relate."}},{"itemId":"74a7ebb7-8ed3-5518-8397-cad516bd4461","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b2827d71-17bb-5f48-b818-ad11b37433fd","sourceKey":"bank:GST111:G111N1-051","parentItemId":null,"revision":1,"payload":{"prompt":"When highlighting a text, which practice is recommended?","options":["Highlight every sentence that has a date","Read first, then highlight","Highlight before reading the passage","Highlight as much of the text as possible"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The rules are to decide what to highlight, read first and then highlight, be selective, and highlight the thesis and topic sentences. Highlighting as much as possible breaks the rule of being selective."}},{"itemId":"e37f53b3-9612-565d-9c5b-efa0fb8cb23f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9ef6e09e-7c75-51e3-a484-3800084fb087","sourceKey":"bank:GST111:G111N1-052","parentItemId":null,"revision":1,"payload":{"prompt":"When should a reader review a text after reading it?","options":["Only if the text was difficult","Only on the eve of the examination","Immediately after reading","About a week after reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Review after reading should be done immediately, using the same steps as previewing. Waiting until the eve of an examination means the details will already have faded."}},{"itemId":"40c0a995-6d51-5df2-8930-c192012b3876","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"73ab13c6-d89f-5a44-9e06-84164a488133","sourceKey":"bank:GST111:G111N1-053","parentItemId":null,"revision":1,"payload":{"prompt":"In reading, the eyes do the physical task. Which organ interprets what is read?","options":["The brain","The ears","The vocal apparatus","The eyes"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading uses the eyes for the physical task of seeing the symbols and the brain for interpreting them. The eyes only take in the printed symbols; they do not work out the meaning."}},{"itemId":"7ddc5d9f-41da-585e-b63a-4d7f692764c7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2c2870e3-0010-5007-b369-08ac4720a3aa","sourceKey":"bank:GST111:G111N1-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about reading as a skill is correct?","options":["It is fully mastered by the end of primary school","It depends only on the eyes","Its efficiency improves without practice","It is a developmental process that is never fully mastered"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading keeps developing throughout life and is never fully mastered, and its efficiency improves only with practice. It also uses the brain for interpretation, so 'only the eyes' is wrong."}},{"itemId":"3292d153-6a49-58a2-bd07-7c1fee2da964","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d7bc42d7-7225-5549-8097-22c0b066b45b","sourceKey":"bank:GST111:G111N1-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a step in previewing a text?","options":["Checking the title, subtitles and author","Reading the introduction or first paragraph","Writing a summary from your highlights and annotations","Examining photos, charts, tables and diagrams"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Writing a summary from highlights and annotations is part of reviewing after reading, not previewing. Checking the title and author, reading the introduction and examining charts are all among the seven previewing steps."}},{"itemId":"dd7b3c29-667b-5b43-8f8f-7342e733d00f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a03cb75e-6339-5068-8637-5c21ad1c10df","sourceKey":"bank:GST111:G111N1-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a way of connecting a text to your own experience before reading?","options":["Thinking of similar situations you have experienced","Reading only the conclusion","Counting the number of paragraphs","Copying the first paragraph word for word"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Connecting to your experience involves thinking of similar situations, asking and answering questions, and writing down ideas as they come. Reading only the conclusion is not a way of connecting to experience and skips most of the text."}},{"itemId":"1ee24e12-83a0-527e-bdb2-b72bcbd60e68","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e8257bc6-08af-5f87-8491-6bd1875eb0a6","sourceKey":"bank:GST111:G111N1-057","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Balogun market glances quickly over a newspaper just to get a general idea of what it is about. Which type of reading is this?","options":["Skimming","Regression","Study reading","Scanning"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Skimming is a quick look to get the overall or general idea of a text. Scanning is also quick, but it looks for one specific piece of information, which the trader is not doing."}},{"itemId":"d3b31b4f-c713-507c-8582-30ef83484102","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"170c08a6-0f56-54b9-beef-5031bf031796","sourceKey":"bank:GST111:G111N1-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of reading is intensive, thorough and critical?","options":["Previewing","Study reading","Scanning","Skimming"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Study reading is the intensive, thorough and critical type of reading used for serious learning. Skimming and scanning are quick runs through a text for the general idea or a specific detail."}},{"itemId":"2560b49c-f406-54ef-9ee4-0eb66fc5a970","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4a551306-5cfd-5a7a-9e59-a0bf1d1d302b","sourceKey":"bank:GST111:G111N1-059","parentItemId":null,"revision":1,"payload":{"prompt":"In the study-reading mnemonic LEARNER, the first 'E' stands for","options":["Examine all parts","Ease away from one subject","Evaluate the author","Explain the topic"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"In LEARNER, L is lay out the purpose and the first E is examine all parts. 'Ease away from one subject before starting another' is the second E, near the end of the mnemonic."}},{"itemId":"79b1f225-a3c8-591b-a797-74bb9b314d2c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"527548d9-d9c9-5b31-bb16-f0c28fede9ad","sourceKey":"bank:GST111:G111N1-060","parentItemId":null,"revision":1,"payload":{"prompt":"When previewing a passage titled 'The Causes of Election Violence', a good strategy is to","options":["memorise the title word for word","skip the title and read the conclusion","turn the title into a question","count the paragraphs in the passage"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Turning the title into a question, such as 'What are the causes of election violence?', gives your reading a purpose from the start. Skipping the title throws away the first clue to what the passage is about."}},{"itemId":"b13c65e5-11fb-57a2-afd1-644a901b856e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"216f103b-4f97-586b-a1c6-d5e78d0a269b","sourceKey":"bank:GST111:G111N1-061","parentItemId":null,"revision":1,"payload":{"prompt":"The first reading of a comprehension passage should be","options":["focused only on difficult vocabulary","word by word, to check every meaning","rapid, to get a general impression","slow, to separate main ideas from minor ones"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"The first reading is a quick one that gives a general impression of the tone, purpose and theme. Slow reading to separate main from minor ideas is the job of the second reading."}},{"itemId":"ce2075da-d8b8-5a5f-9d7c-f48704958af3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ea556653-a9fa-5b79-bb07-963b9e817999","sourceKey":"bank:GST111:G111N1-062","parentItemId":null,"revision":1,"payload":{"prompt":"Separating main ideas from minor ones, and subjective statements from objective ones, is the focus of the","options":["first reading","skimming stage","second reading","preview stage"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"The second reading is slower and is used to separate main from minor ideas, subjective from objective and direct from indirect statements. The first reading is rapid and only gives a general impression."}},{"itemId":"e3dc0e2b-b0a8-527d-a1e8-1d2a95eb09a2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"21bcec70-ed68-521e-ae14-749e70575e38","sourceKey":"bank:GST111:G111N1-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a focus of the FIRST reading of a comprehension passage?","options":["Separating main ideas from minor ones","The writer's tone and attitude","Separating subjective from objective statements","Separating direct from indirect statements"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"During the first, rapid reading you look for the writer's tone and attitude, purpose and central idea. The separating tasks, such as subjective versus objective, belong to the slower second reading."}},{"itemId":"d5c5b95d-b588-5149-9c97-5702a1b847af","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6039d1f1-2c99-5a06-a0bd-951070c01f84","sourceKey":"bank:GST111:G111N1-064","parentItemId":null,"revision":1,"payload":{"prompt":"Comprehension questions that require you to give answers in your own words are called","options":["traditional type questions","multiple choice questions","zero-answer questions","affirmation questions"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The two major formats are multiple choice questions and traditional type questions, and the traditional type expects answers in your own words. Multiple choice questions give you options to pick from instead."}},{"itemId":"d752ab85-11c9-5535-b51e-24e248c5f274","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8fb2901f-1e02-5f6a-abef-dfdeb83b943d","sourceKey":"bank:GST111:G111N1-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a useful clue for answering comprehension multiple choice questions?","options":["Choose the first option that seems partly correct","Always pick the longest option","Use elimination to rule out wrong options","Mark two answers when unsure"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Using elimination is one of the four MCQ clues, alongside making sure all other options are wrong. Choosing an option that is only partly correct is a trap, because some options are designed to be partly right."}},{"itemId":"ca7c8610-6e0f-54fa-9fcb-332e92084d5b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"90056ee2-6768-594e-a919-c0c05a2a73ca","sourceKey":"bank:GST111:G111N1-066","parentItemId":null,"revision":1,"payload":{"prompt":"In comprehension MCQs, options such as 'none of the above' and 'don't know' are referred to as","options":["zero answers","suggested answers","inferred answers","partial answers"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"Options like 'none of the above' or 'don't know' are called zero answers. Partial answers are different: they are options that are only partly correct."}},{"itemId":"c493e47b-8666-5490-9fd2-8f54d3099b51","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bdf9f55f-eafb-58a9-88c6-1be122822a1b","sourceKey":"bank:GST111:G111N1-067","parentItemId":null,"revision":1,"payload":{"prompt":"A traditional comprehension question asks whether 'cat' in a passage refers to the animal or is used as a metaphor. This question tests","options":["the title of the passage","the meaning of a word in context","the spelling of a word","the reader's personal opinion"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Asking whether 'cat' is literal or metaphorical tests the meaning of a word in its context. It is not an opinion question, because the answer must come from how the word is used in the passage."}},{"itemId":"e1808eae-90a6-5e83-a14f-330ee518385c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6313fd41-063d-59d4-80ea-0dfe4f74f613","sourceKey":"bank:GST111:G111N1-068","parentItemId":null,"revision":1,"payload":{"prompt":"Comprehension questions that require you to establish relationships between parts of the text are","options":["supposition questions","direct reference questions","inference questions","evaluation questions"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Inference questions ask you to connect parts of the text and see how they relate. Direct reference questions only ask you to point to what the text states."}},{"itemId":"0976fa49-b278-53d1-8648-6c4b7d04acf8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"499458b1-190d-5c93-bf7b-e2bfdfe2cdf6","sourceKey":"bank:GST111:G111N1-069","parentItemId":null,"revision":1,"payload":{"prompt":"Comprehension questions that require you to think beyond the passage to the outside world are","options":["direct reference questions","inference questions","evaluation questions","supposition questions"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Supposition questions take you beyond the passage into the outside world. Inference questions stay within the text, linking one part of it to another."}},{"itemId":"ef5e7703-f548-5d9c-a27f-2fad856b5b19","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d4c4c3c5-8fb3-5d44-bb6f-2404132ae580","sourceKey":"bank:GST111:G111N1-070","parentItemId":null,"revision":1,"payload":{"prompt":"Comprehension questions that require you to judge the information and the effectiveness of the writer's language are","options":["inference questions","evaluation questions","direct reference questions","supposition questions"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Evaluation questions ask you to judge both the information and how well the writer uses language. Supposition questions ask you to think beyond the passage, not to judge the writer's language."}},{"itemId":"5e0e4339-4c6c-591f-ab3e-d6878bdbc61a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fa07818d-cff9-596f-a4dc-09ad3ecda39b","sourceKey":"bank:GST111:G111N1-071","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an evaluation question on a comprehension passage?","options":["How effective is the writer's use of imagery in the last paragraph?","How is the flood in paragraph 1 related to the food shortage in paragraph 3?","In what year was the bridge built, according to the passage?","What might happen in your own town if the same policy were adopted?"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"Judging how effective the writer's imagery is assesses the writer's language, which is what evaluation questions do. Linking the flood in paragraph 1 to the food shortage in paragraph 3 is an inference question, because it connects parts of the text."}},{"itemId":"c2db8787-0e90-57ec-b073-3b0803229a7d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0bb03fbd-6b52-5c2a-958a-d1eff908e8ca","sourceKey":"bank:GST111:G111N1-072","parentItemId":null,"revision":1,"payload":{"prompt":"A comprehension question asks: 'How is the drought described in paragraph 1 related to the rise in food prices in paragraph 4?' This is","options":["an evaluation question","a supposition question","a direct reference question","an inference question"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"The question asks you to establish a relationship between two parts of the text, which makes it an inference question. A direct reference question would only ask for something stated in one place in the text."}},{"itemId":"8fcaeda6-1efc-5257-99f1-30abd4f036ec","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9d1cd651-2a49-50e8-b49e-d4061afd85b9","sourceKey":"bank:GST111:G111N1-073","parentItemId":null,"revision":1,"payload":{"prompt":"How many categories of comprehension question do examiners use to test understanding?","options":["2","6","4","3"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"There are four categories: direct reference, inference, supposition and evaluation. The figure 2 is the number of question formats (MCQ and traditional type), not categories."}},{"itemId":"f55a1aef-e134-539a-9c11-7057180ce3fe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"95e144d4-993f-5d9a-8210-8935253eb4a3","sourceKey":"bank:GST111:G111N1-074","parentItemId":null,"revision":1,"payload":{"prompt":"A summary is usually about what fraction of the length of the original work?","options":["Two-thirds","One-third","One-tenth","One-half"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A summary condenses the original to about one-third of its length. One-half would keep too much of the original to count as a proper condensed version."}},{"itemId":"68a94c40-39fb-5a93-bc52-cf64ba06e036","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ac346bf2-9b23-5e95-91b4-42f583fa881f","sourceKey":"bank:GST111:G111N1-075","parentItemId":null,"revision":1,"payload":{"prompt":"For which of the following would a synopsis, rather than a summary, be appropriate?","options":["A newspaper editorial","A novel","A research report","A textbook chapter"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A synopsis summarises a plot, so it is used only for novels, plays and stories. A research report has no plot, so it gets an ordinary summary."}},{"itemId":"537e1746-4f4d-52f9-8f34-31a60c6afca4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b37f5966-bec2-5d57-a719-b910680d8a5a","sourceKey":"bank:GST111:G111N1-076","parentItemId":null,"revision":1,"payload":{"prompt":"Short, concise summaries of non-fiction works are called","options":["synopses","abstracts","blurbs","prefaces"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Short, concise non-fiction summaries are known as abstracts. A synopsis is a plot summary used only for novels, plays and stories, so it does not fit non-fiction."}},{"itemId":"35228cc0-fd2a-52fb-b135-e12ab5010882","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"81d34803-a5b9-5d11-b1d1-8debb2e0a5b7","sourceKey":"bank:GST111:G111N1-077","parentItemId":null,"revision":1,"payload":{"prompt":"The lead of a written summary should give","options":["the title, author, text type and main idea","the summariser's opinion of the text","a direct quotation from the text","the dramatic climax of the text"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"A written summary begins with a lead stating the title, the author, the type of text and its main idea. A direct quotation is out of place because a summary should not quote from the text."}},{"itemId":"d96c4af7-7ebb-5828-a19b-3497809beab8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e5e424e2-b423-5d21-bda8-8bbff8074a37","sourceKey":"bank:GST111:G111N1-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which tense is preferred when writing a summary?","options":["The past perfect tense","The present tense or the historic present","The future tense","The past continuous tense"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Summaries are best written in the present tense or the historic present. The past tense is allowed for poems, stories and novels, but no past form is the preferred choice."}},{"itemId":"b2395fe7-5b1f-5597-93e7-3daf18a2153e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c70bdab3-0d1f-557a-8015-995adaa40bd6","sourceKey":"bank:GST111:G111N1-079","parentItemId":null,"revision":1,"payload":{"prompt":"Concerning tense, what should a writer AVOID in a summary?","options":["Using the present tense for a play","Using the present tense for a novel","Using the historic present","Shifting from one tense to another"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Whatever tense you choose, you should keep to it and not shift tenses. Using the present tense for a play is not a fault, because drama is summarised in the present tense."}},{"itemId":"a12f4282-b326-58e6-af20-c6c8cb827231","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"08fdc498-b442-5d81-9e6c-0b31d0d0ba65","sourceKey":"bank:GST111:G111N1-080","parentItemId":null,"revision":1,"payload":{"prompt":"When summarising a multi-section document such as a report, each section should have at least how many summarising statements?","options":["One","Two","Five","Three"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"For a multi-section summary, at least three summarising statements are written for each section. One statement per section is closer to a paragraph summary and would leave out too much."}},{"itemId":"d0ce788b-c026-5785-aea7-0cada7513d83","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c1f63574-e4da-5a78-8594-3b3dc219563e","sourceKey":"bank:GST111:G111N1-081","parentItemId":null,"revision":1,"payload":{"prompt":"A summary strategy that integrates the ideas of a section made up of several paragraphs is a","options":["synopsis","section summary","multi-section summary","paragraph summary"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A section summary pulls together the ideas of a multi-paragraph section. A paragraph summary deals with only one paragraph at a time."}},{"itemId":"00115857-185c-5cf3-996d-3034dead4c92","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1ab230a4-d22b-5381-9388-1ce369e8fd57","sourceKey":"bank:GST111:G111N1-082","parentItemId":null,"revision":1,"payload":{"prompt":"In the third step of summarising a paragraph, the writer should","options":["write the content in new words without looking at the original","read again to pick out the essentials","compare the summary with the original and revise it","read to find the basic idea"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The third step is to write the content in your own words without looking at the original. Comparing with the original and revising is the fourth and final step."}},{"itemId":"0a6d298e-2bfa-541f-9da4-bd04c245e833","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ebd27512-cf67-5eb4-a30e-854c21c49961","sourceKey":"bank:GST111:G111N1-083","parentItemId":null,"revision":1,"payload":{"prompt":"What is the FINAL step in summarising a paragraph?","options":["Compare your summary with the original and revise it","Express the content in your own words","Read the paragraph to find the basic idea","Read again to pick out the essentials"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The last of the four steps is to compare your version with the original and revise it. Expressing the content in your own words comes just before this, as the third step."}},{"itemId":"55deb4ca-69da-5ea0-ae02-cb12a8f2a084","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3f0f5968-2402-5142-a322-b10c06c121c0","sourceKey":"bank:GST111:G111N1-084","parentItemId":null,"revision":1,"payload":{"prompt":"When summarising, three or four paragraphs of an original text can be reduced to","options":["three paragraphs","two pages","one word","one paragraph"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"In summarising, a paragraph can become one sentence, and three or four paragraphs can become one paragraph. Keeping three paragraphs would hardly condense the text at all."}},{"itemId":"7fb55eb6-a32a-53fe-ae81-e66f12421ac5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"805a54c2-5ed4-5088-9adc-e1a490990af4","sourceKey":"bank:GST111:G111N1-085","parentItemId":null,"revision":1,"payload":{"prompt":"A summary of a non-fiction work should present","options":["the summariser's own critique of the author","a dramatic structure that builds suspense","the author's point of view without the summariser's own analysis","long quotations from the original"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"A non-fiction summary gives the author's point of view and leaves out the summariser's own analysis. Adding your own critique turns the summary into a review."}},{"itemId":"0fbca213-e314-5ea4-8c7b-ae1eeefad1dd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"040488a6-698b-59ae-9be3-c61bd219a01f","sourceKey":"bank:GST111:G111N1-086","parentItemId":null,"revision":1,"payload":{"prompt":"When summarising a book or a dissertation, the summary should use","options":["poetic and figurative language","slang and informal expressions","common scientific language","the writer's own exact sentences"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"For books and dissertations, a summary should use common scientific language. Copying the writer's own exact sentences breaks the rule of paraphrasing rather than quoting."}},{"itemId":"ee972336-48c7-540d-9285-e34a67b9d91e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"da50e5ec-ad36-50a7-b016-4523b59bfccf","sourceKey":"bank:GST111:G111N1-087","parentItemId":null,"revision":1,"payload":{"prompt":"In Barbara Tuchman's 'A Distant Mirror', used as an illustrative text on summary, the English ordinance of 1349 was reissued in 1351 as the","options":["Poor Law","Bill of Rights","Magna Carta","Statute of Labourers"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"The extract describes the English ordinance of 1349 being reissued in 1351 as the Statute of Labourers. The Magna Carta, Poor Law and Bill of Rights are other English laws that are not connected with this extract."}},{"itemId":"e5d85f5a-7899-5a17-a308-8cea4efcc6be","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"275aa709-f140-5b43-ae1f-16db0a6b1cc0","sourceKey":"bank:GST111:G111N1-088","parentItemId":null,"revision":1,"payload":{"prompt":"When answering a comprehension multiple choice question, how many options should a candidate mark?","options":["Every option that is partly correct","Only one option","None, if the answer is not obvious","Two, to be on the safe side"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Never mark more than one answer, since there is usually one correct answer. Marking every option that is partly correct is a trap, because some options are designed to be only partly right."}},{"itemId":"9a032a6e-e1e7-55e1-b95f-cdbcb8ad7ff2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2a9cdebb-61c9-5d1b-b559-04131e01a782","sourceKey":"bank:GST111:G111N1-089","parentItemId":null,"revision":1,"payload":{"prompt":"The extract from T. H. Huxley's 'Collected Essays', used as an illustrative text on summary, discusses","options":["the plague and wages in Europe","the first landing on the moon","'pure' versus 'applied' science","racial discrimination in London"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Huxley's essay deals with the distinction between 'pure' and 'applied' science. The plague and wages are the subject of the Tuchman extract, a different illustrative text."}},{"itemId":"2f475bb8-07c2-5b21-a3a3-f78aff43bfe3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"62b19ac0-1618-5218-9001-73d27843b85e","sourceKey":"bank:GST111:G111N1-090","parentItemId":null,"revision":1,"payload":{"prompt":"What should a writer do with the ideas of the original text when writing a summary?","options":["Add a personal judgement of the author","Copy the key sentences exactly","Present them in a dramatic structure","Arrange them clearly and paraphrase them in new words"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"A written summary arranges the ideas clearly and paraphrases them in new words. Building a dramatic structure is wrong, because a summary should have no dramatic structure."}},{"itemId":"95236d67-d7b0-516f-9036-6b6d9d1d4f00","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3a0528e3-75a6-53cd-860b-9cea8f71efc6","sourceKey":"bank:GST111:G111N1-091","parentItemId":null,"revision":1,"payload":{"prompt":"SQ3R, a method of study reading, stands for","options":["Summarise, Question, Read, Recall, Revise","Survey, Question, Read, Recall/Recite, Review","Scan, Question, Read, Recite, Repeat","Survey, Question, Reflect, Recollect, Review"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"SQ3R is Survey, Question, Read, Recall/Recite and Review. Reflect and Recollect belong to the 3S3R method, not to SQ3R."}},{"itemId":"8022d77e-c52d-5c03-b7f4-59c4e0cb48ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"44ae1121-64c2-54bd-b82e-78da5116a596","sourceKey":"bank:GST111:G111N1-092","parentItemId":null,"revision":1,"payload":{"prompt":"What do the letters of the study-reading method PQRST stand for?","options":["Prepare, Question, Read, Study, Test","Preview, Question, Read, Summary, Test","Preview, Question, Recall, Survey, Test","Preview, Quiz, Review, Summary, Text"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"PQRST is Preview, Question, Read, Summary and Test. The other expansions swap in words such as Recall, Study or Review, which do not belong to PQRST."}},{"itemId":"8dbafd30-ea95-574b-ad65-c59e0bc3ff3c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ff0b5044-b890-59bf-a790-410ba6beb03f","sourceKey":"bank:GST111:G111N1-093","parentItemId":null,"revision":1,"payload":{"prompt":"In the OK4R method of study reading, the letter 'K' stands for","options":["Key questions","Kind of text","Knowledge","Key points"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"OK4R is Overview, Key points, then Read, Recall, Reflect and Review. 'Key questions' sounds close, but questioning is a step in SQ3R and PQRST, not the K of OK4R."}},{"itemId":"2948b090-71c7-55eb-8d15-ae4338f66136","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"92307e55-8115-5dc4-a123-e421c9374ae1","sourceKey":"bank:GST111:G111N1-094","parentItemId":null,"revision":1,"payload":{"prompt":"Which method of study reading consists of Survey, Study-read, Speech-read, Recite, Reflect and Recollect?","options":["OK4R","SQ3R","PQRST","3S3R"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"The three S steps (Survey, Study-read, Speech-read) and three R steps (Recite, Reflect, Recollect) make up 3S3R. SQ3R also starts with Survey, but its other steps are Question, Read, Recall/Recite and Review."}},{"itemId":"fd8fec16-6bd2-56b2-864a-7e3cdca0b6b2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"45b9ce64-d932-5b31-b6bc-a0bbc2236971","sourceKey":"bank:GST111:G111N1-095","parentItemId":null,"revision":1,"payload":{"prompt":"Which method of study reading gives priority to information needed for examinations?","options":["SQ3R","3S3R","OK4R","PQRST"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"PQRST, which ends with Summary and Test, gives priority to information needed for exams. SQ3R is a general study-reading method that ends with Review rather than a test."}},{"itemId":"69b8eae9-fc10-5c47-a949-6f863ff68582","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"36b2f79a-1f73-5251-83a2-06e02336106b","sourceKey":"bank:GST111:G111N1-097","parentItemId":null,"revision":1,"payload":{"prompt":"The type of memory that stores information for a short time, organises it and filters out what is irrelevant is","options":["long-term memory","retrieval memory","short-term memory","sensory memory"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Short-term memory holds information briefly, organises it and removes what is irrelevant. Long-term memory, by contrast, is permanent and limitless."}},{"itemId":"49b3cc31-cade-523d-a673-33a08c26e3cf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"058935c7-7d3a-58a4-99fc-67f4914346ef","sourceKey":"bank:GST111:G111N1-098","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of memory is described as permanent, large and limitless?","options":["Working memory","Long-term memory","Sensory memory","Short-term memory"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Long-term memory is permanent, large and limitless. Short-term memory keeps information only for a short time before filtering it."}},{"itemId":"2e61be65-8cab-586b-ab6c-e1f06594134e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6be89239-1ac8-5cc4-a1bb-b95e0a05c95d","sourceKey":"bank:GST111:G111N1-099","parentItemId":null,"revision":1,"payload":{"prompt":"The type of memory linked to the senses, such as the eyes, ears and tongue, and which is very ephemeral, is","options":["retrieval memory","sensory memory","long-term memory","short-term memory"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Sensory memory is tied to the senses and fades almost at once, which is what 'very ephemeral' means. Short-term memory lasts a little longer and organises information."}},{"itemId":"948dfe9f-96a5-55ab-bcfd-133df7972131","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5127810b-35ae-5559-81e4-faed361649b7","sourceKey":"bank:GST111:G111N1-100","parentItemId":null,"revision":1,"payload":{"prompt":"What is the correct order of the stages of storing information in memory?","options":["Encoding, storage, retrieval","Retrieval, encoding, storage","Storage, encoding, retrieval","Encoding, retrieval, storage"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Information is first encoded (read, organised and internalised), then stored (retained), and finally retrieved (recalled). Storage cannot come before encoding, because information must be taken in before it can be kept."}},{"itemId":"4eb4660a-8812-5ed4-aa6e-45da17755a88","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f4c8b3bb-87e1-5494-b822-363dbb11c96e","sourceKey":"bank:GST111:G111N1-101","parentItemId":null,"revision":1,"payload":{"prompt":"Reading, organising and internalising information belong to which stage of storing information?","options":["Encoding","Storage","Recollection","Retrieval"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Encoding is the stage where you read, organise and internalise information. Storage is the next stage, where the information is retained."}},{"itemId":"8a732172-b58b-5a96-826c-07c056cf2ffa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9a789116-aa37-5346-ae6e-8a2eb8d50d0b","sourceKey":"bank:GST111:G111N1-102","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of storing information in which a student recalls what was learnt, aided by attention, is","options":["encoding","survey","retrieval","storage"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Retrieval is the recall stage, and attention helps it. Storage is only the keeping of information, not bringing it back out."}},{"itemId":"ce0a68ab-1ada-57b6-9959-9169b45f6bb6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"41530a53-5723-5430-b15e-3804f919b550","sourceKey":"bank:GST111:G111N1-103","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is described as the best way to remember what you read?","options":["Verbatim recitation","Highlighting every line","Paraphrasing","Reading once quickly"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Paraphrasing, putting ideas into your own words, is the best way to remember. Verbatim recitation suits only special cases such as play lines, foreign languages and the sciences."}},{"itemId":"b20e27b6-bfc3-5d13-8a6a-80aea2fe368e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"289cfc8d-f4c2-55fc-a599-a3c9deb4e96e","sourceKey":"bank:GST111:G111N1-104","parentItemId":null,"revision":1,"payload":{"prompt":"Using 'ROYGBIV' to remember the colours of the rainbow is an example of which study aid?","options":["A graphic organiser","Summarisation through keywords","A flash card","A mnemonic device"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"ROYGBIV is a mnemonic device or acronym in which each letter stands for a colour, from red to violet. A flash card is a separate study aid: a card with visual clues."}},{"itemId":"2c94a6ce-d7ef-5562-83aa-de8584e93bc7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"613ef458-d895-5e15-84a0-073d66ba994a","sourceKey":"bank:GST111:G111N1-105","parentItemId":null,"revision":1,"payload":{"prompt":"Flash cards recommended as a study aid are usually of which paper size?","options":["A5","A4","A3","A1"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Flash cards are A5 in size and carry visual clues. A4 is the standard size of a full sheet, which is larger than a flash card needs to be."}},{"itemId":"0c5c09c9-0eee-569d-ab6b-02857db36800","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6122fe4e-6be0-5c32-8ecb-645fda8fc3df","sourceKey":"bank:GST111:G111N1-106","parentItemId":null,"revision":1,"payload":{"prompt":"Unlike a newspaper, which is usually read once, a course book should be read","options":["once and quickly","only by skimming","repeatedly and with effort","only the night before an exam"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"The nature of what is being read decides how it is read: a newspaper is read once, but a course book is read repeatedly and with effort. Skimming a course book would give only the general idea, not the knowledge it is meant to provide."}},{"itemId":"a32f6b7d-5a5b-5b89-a7d3-8735df07b78d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b6188924-af12-5c96-a69d-9701ed73ad7b","sourceKey":"bank:GST111:G111N1-107","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a sub-strategy of the 'Read' stage of SQ3R?","options":["Identify verbal and sense links such as keywords and topic sentences","Assess the work by going over all the steps again","Remember the material from memory and tell it to a friend","Examine the title, preface and table of contents"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Identifying verbal and sense links is one of the seven sub-strategies of the Read stage. Going over all the steps again is the Review stage, which comes last."}},{"itemId":"07847e9c-0ee3-51ce-b27d-0470ab5fdd1c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"04e2015c-b7cd-5e04-ac06-e5614d095a1a","sourceKey":"bank:GST111:G111N1-108","parentItemId":null,"revision":1,"payload":{"prompt":"In SQ3R, the stage that is the same as revision is","options":["Survey","Question","Recall/Recite","Review"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"Review means assessing your work, which is the same as revision, by going over all the steps again. Recall/Recite is about remembering from memory, not revising the whole process."}},{"itemId":"eadf95aa-4b7c-525d-b8f6-6b1065bbaa12","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cca28216-37a8-56c7-8bf0-5df16e7c3a44","sourceKey":"bank:GST111:G111N1-109","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG student closes her course book and explains the chapter from memory to a friend in her hostel. Which stage of SQ3R is she practising?","options":["Recall/Recite","Review","Survey","Question"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Recall/Recite means remembering from memory, by paraphrasing or using the exact words, in writing or to a friend. Review is about assessing the work by going over all the steps again."}},{"itemId":"2935dc97-5f55-5a80-ba9b-a57e2a2edda0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"26d0d12b-7bba-5b8a-b4ed-69cfe85c302c","sourceKey":"bank:GST111:G111N1-110","parentItemId":null,"revision":1,"payload":{"prompt":"In study reading, asking 'Is the writer objective?' and 'Does it contradict my views?' belongs to which stage of SQ3R?","options":["Survey","Review","Question","Read"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"These are among the example questions of the Question stage of SQ3R. The Survey stage only looks over preliminary matter such as the title, preface and table of contents."}},{"itemId":"9312dfba-628e-5514-b72c-42f11aa3b3f6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"011ad3b4-fcc3-5f61-99dc-cd0b0e696b3b","sourceKey":"bank:GST111:G111N1-111","parentItemId":null,"revision":1,"payload":{"prompt":"Reading improves a student's listening and writing mainly because it","options":["reduces the need to attend lectures","trains the vocal apparatus","enlarges the student's vocabulary","removes the need for revision"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Reading enlarges your vocabulary, and a bigger vocabulary in turn improves listening and writing. Training the vocal apparatus is not what reading does; reading uses the eyes and the mental faculty."}},{"itemId":"955e72a6-c2dd-50b3-976f-0032f5026715","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0861f792-c2cd-542b-9f40-583c09033979","sourceKey":"bank:GST111:G111N1-112","parentItemId":null,"revision":1,"payload":{"prompt":"Reading is described as a process of communication through which","options":["spoken words are decoded","only pleasure is obtained","most formal learning takes place","speech ability is diminished"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Reading is a process of communication through which most formal learning takes place. Decoding spoken words describes listening, not reading."}},{"itemId":"5876a9fb-383b-58e8-bfcd-43a209691dba","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"38b1b7a0-2009-5390-a944-0ac39cf779aa","sourceKey":"bank:GST111:G111N1-113","parentItemId":null,"revision":1,"payload":{"prompt":"To develop a paragraph properly, a writer should normally write at least","options":["two sentences","ten sentences","one sentence","three sentences"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph should have at least three sentences; single-sentence paragraphs are rare. Two sentences is too few, since paragraphs of only two or three sentences risk inadequate development."}},{"itemId":"d8533f28-a2cd-5331-8d18-7a6ce6030667","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"00a24aac-d9f8-57a3-a674-3b1db8cb0b46","sourceKey":"bank:GST111:G111N1-114","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph that uses expressions such as 'can be divided into', 'falls under' and 'belongs to' is a","options":["sequence paragraph","definition paragraph","classification paragraph","descriptive paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"These expressions group things into categories, which is what a classification paragraph does. A definition paragraph instead explains key words with phrases such as 'is defined as'."}},{"itemId":"4cb972ba-c2f7-5130-ac80-a72ebb426533","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4c2ac7a1-a298-53d3-a219-a194a23a9b3b","sourceKey":"bank:GST111:G111N1-115","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph that uses words such as 'on the other hand', 'in contrast to' and 'differs from' is a","options":["explanation paragraph","classification paragraph","comparison and contrast paragraph","evaluation paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"These words show similarities and differences, the work of a comparison and contrast paragraph. A classification paragraph groups things into categories rather than setting them against each other."}},{"itemId":"d4f615d0-2abb-526b-a3cd-8224a14c8c4a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"29f220a2-cad4-5775-8ff0-b396af893b1c","sourceKey":"bank:GST111:G111N1-117","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph that judges people, ideas or actions against criteria and uses words such as 'suggest', 'recommend' and 'advise' is a/an","options":["explanation paragraph","evaluation paragraph","descriptive paragraph","choice paragraph"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An evaluation paragraph judges against criteria (good or bad, correct or incorrect) and makes recommendations. A choice paragraph only states a personal preference without judging against criteria."}},{"itemId":"df5a68e3-46b9-5dd6-9736-1f3c2e80a737","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9b7e7158-939e-520f-8da3-abd4effe4788","sourceKey":"bank:GST111:G111N1-118","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph in an economics essay begins: 'Inflation is defined as a sustained rise in the general price level.' What type of paragraph is it most likely to be?","options":["Classification","Description","Evaluation","Definition"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"The helper phrase 'is defined as' marks a definition paragraph, which explains key words. A classification paragraph would use phrases such as 'can be divided into' to group things."}},{"itemId":"51767f7f-4212-54e3-9b81-979985026053","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c12565ec-724b-5140-b9d7-d04e2de4248e","sourceKey":"bank:GST111:G111N1-119","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph that uses words of measurement, location, size, colour and shape, and phrases like 'resembles', is a","options":["comparison and contrast paragraph","classification paragraph","definition paragraph","descriptive paragraph"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Words of size, colour, shape and location, and 'resembles', describe a person, place or thing, which makes a descriptive paragraph. A comparison and contrast paragraph focuses on similarities and differences between two things."}},{"itemId":"035d5c28-02f1-5ad2-92ac-97e4be08a117","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9a1a57bc-7716-5db7-9dc0-d345308c2a2b","sourceKey":"bank:GST111:G111N1-120","parentItemId":null,"revision":1,"payload":{"prompt":"How many types of paragraph are identified, from definition to evaluation?","options":["6","11","5","8"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Eight types are identified: definition, classification, descriptive, comparison and contrast, sequence, choice, explanation and evaluation. The figure 11 is the number of methods of paragraph development, a different list."}},{"itemId":"74362142-57ad-5dfd-9a16-2c9089d2f2ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"03632b8b-7182-5d95-b02e-570e65076b9d","sourceKey":"bank:GST111:G111N1-121","parentItemId":null,"revision":1,"payload":{"prompt":"A topic sentence is best placed at the END of a paragraph when","options":["the main idea is obvious","the paragraph is very short","the paragraph introduces the essay","specific details lead up to a generalisation"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"When the paragraph builds from specific details towards a general point, the topic sentence goes at the end. When the main idea is obvious, the topic sentence can be left out altogether rather than moved."}},{"itemId":"2a9aaec3-8383-503a-a7ee-dc9fc680a41c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"82c11d71-5dc6-541d-91ae-0cd38709cac2","sourceKey":"bank:GST111:G111N1-122","parentItemId":null,"revision":1,"payload":{"prompt":"When may a writer leave out the topic sentence of a paragraph?","options":["When the main idea is obvious","When the writer is unsure of the main idea","When the paragraph has many examples","When the paragraph is the conclusion"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"A topic sentence can be left out when the main idea is already obvious to the reader. Being unsure of the main idea is a reason to fix the paragraph, not to drop the topic sentence."}},{"itemId":"6376009d-b9e7-5164-995e-9e640f17429e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e271d0fc-e69d-5fd9-90fb-8f5478d4c59f","sourceKey":"bank:GST111:G111N1-123","parentItemId":null,"revision":1,"payload":{"prompt":"In a concise and emphatic topic sentence such as 'The Nigerian banking system has collapsed', the key word is placed","options":["at the beginning","in the middle","at the end","in a separate sentence"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"A good topic sentence is concise and emphatic, with the key word placed at the end, as 'collapsed' is in the example. Placing it at the beginning loses the emphasis that the final position gives."}},{"itemId":"c3fca061-3763-58d0-8651-fbd8bbe318d6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8d7b0665-05fa-537c-b2e4-0c61fc2b247d","sourceKey":"bank:GST111:G111N1-124","parentItemId":null,"revision":1,"payload":{"prompt":"In the structure of a paragraph, the concluding sentence is","options":["essential, and simply repeats the topic sentence","a summary only, with no link to what follows","optional, and leads to the next step","always the first sentence of the paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The concluding sentence is optional and is more than a summary, because it leads to the next step. It usually comes last or second-to-last, never first."}},{"itemId":"faa18a32-8932-51e9-9aae-e480951030e4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4e0300e2-aae4-58ae-b7be-2e293916adc0","sourceKey":"bank:GST111:G111N1-125","parentItemId":null,"revision":1,"payload":{"prompt":"A body paragraph that is full of evidence but has very little analysis is weak because","options":["it is too short","it lacks a topic sentence","it has no argument","its claim is unsupported"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Evidence without analysis leaves the paragraph with no argument. An unsupported claim is the opposite problem, which happens when there is plenty of analysis but too little evidence."}},{"itemId":"4e02c83a-5ee8-5353-8c71-db58bedf081b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"80bfe887-5e06-5843-9dec-81b9b411c225","sourceKey":"bank:GST111:G111N1-126","parentItemId":null,"revision":1,"payload":{"prompt":"Very short paragraphs in an essay often suggest","options":["strong unity","a lack of substance","poor structure","too many controlling ideas"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Very short paragraphs suggest a lack of substance. Poor structure is what very long paragraphs tend to suggest, so it is the tempting but wrong choice here."}},{"itemId":"ac04075d-0463-5a16-8ca8-daeb1a951ecd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ac258c1b-41d6-55a0-9ad2-1c68ab05465d","sourceKey":"bank:GST111:G111N1-127","parentItemId":null,"revision":1,"payload":{"prompt":"In the five-step process of paragraph development, what comes right after explaining the controlling idea?","options":["Explaining the example or examples","Deciding on a controlling idea","Giving an example or examples","Completing the idea or moving to the next paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The steps are: decide on a controlling idea, explain it, give an example, explain the example, then complete the paragraph or transition. Explaining the example is step 4, so it comes after the example has been given."}},{"itemId":"d876124d-916f-5d57-972e-881cfc22fb95","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"10eaaa03-ed81-5d63-8380-8688c82fe8e2","sourceKey":"bank:GST111:G111N1-128","parentItemId":null,"revision":1,"payload":{"prompt":"In the five-step process of paragraph development, which steps may be repeated?","options":["Explaining examples and completing the paragraph (steps 4 and 5)","Giving examples and explaining them (steps 3 and 4)","Explaining the controlling idea and giving examples (steps 2 and 3)","Deciding on and explaining the controlling idea (steps 1 and 2)"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Steps 3 and 4, giving an example and explaining it, can be repeated to develop the paragraph further. The controlling idea in steps 1 and 2 is set only once, since a paragraph should have a single focus."}},{"itemId":"720acf10-8087-530c-b8ab-911112f00839","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8bd70349-1dca-507a-b537-3fc75977cb5a","sourceKey":"bank:GST111:G111N1-129","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph that contains multiple controlling ideas should be fixed by","options":["adding more examples","removing sentences or splitting the paragraph","replacing keywords with pronouns","adding a concluding sentence"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Multiple controlling ideas break unity, so the remedy is to remove the off-focus sentences or split the paragraph. Adding more examples would only make the paragraph longer without fixing its divided focus."}},{"itemId":"1cba4a20-1747-53fb-82d9-e9941d39ec0c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c5f0c7b3-6e8c-5afc-9653-a4a824bd0078","sourceKey":"bank:GST111:G111N1-130","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four elements of an effective paragraph?","options":["Considerable length","Coherence","Adequate development","Unity of focus"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The four elements are unity, coherence, a topic sentence and adequate development. Length is not one of them; in fact paragraphs are hardly ever longer than one double-spaced page."}},{"itemId":"2e0cf895-8c4f-5b8d-a010-40d553770ccb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"74c8940e-0101-547e-b707-908d87967da3","sourceKey":"bank:GST111:G111N1-131","parentItemId":null,"revision":1,"payload":{"prompt":"Repeating keywords, using synonyms and using pronouns that refer back to nouns build coherence through","options":["topic sentences","signposts","verbal bridges","logical bridges"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Verbal bridges are word-level links: repeated keywords, synonyms, pronouns and transition words. Logical bridges work at the level of ideas, carrying the same idea from sentence to sentence or using parallel forms."}},{"itemId":"246f2fd0-9334-5aa9-9a75-325a16c2e18f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7746a67b-f9d2-5720-a5d3-d84210fd5732","sourceKey":"bank:GST111:G111N1-132","parentItemId":null,"revision":1,"payload":{"prompt":"Carrying the same idea from sentence to sentence and using parallel sentence forms build coherence through","options":["signposts","verbal bridges","logical bridges","transitions"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Logical bridges carry the same idea through the paragraph and use parallel sentence forms. Verbal bridges are word-based links such as repeated keywords and synonyms."}},{"itemId":"cf2634b5-821d-5798-8df9-b25ed74323b2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"41ea2f82-94ed-5af8-9ec0-9d58232a05a7","sourceKey":"bank:GST111:G111N1-133","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a method of paragraph development?","options":["Punctuation","Anecdote","Testimony","Chronology"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"Anecdote, testimony and chronology are among the eleven methods of developing a paragraph. Punctuation is a writing convention, not a way of developing an idea."}},{"itemId":"6db37022-b9e7-5190-9fc6-a043b9cbce14","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e5c7992b-61f2-5d50-95f2-837dbbfe3ac0","sourceKey":"bank:GST111:G111N1-134","parentItemId":null,"revision":1,"payload":{"prompt":"Internal aids, usually several sentences or a whole paragraph, that outline what has been covered and where the text is going are called","options":["signposts","transitions","topic sentences","concluding sentences"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"Signposts tell the reader what has been covered and what comes next. Transitions are shorter links, one or more sentences, that move from one idea to the next."}},{"itemId":"58986b08-22f9-5b87-9b6f-bda5d2c06f7b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"711129bd-5971-53ef-b07a-e75fc614dc93","sourceKey":"bank:GST111:G111N1-135","parentItemId":null,"revision":1,"payload":{"prompt":"One or more sentences that move from one idea to the next, often at the end of a paragraph, are called","options":["thesis statements","topic sentences","signposts","transitions"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Transitions move the reader from one idea to the next and often sit at the end of a paragraph. Signposts are larger aids that outline what has been covered and where the text is going."}},{"itemId":"525ee67e-4532-5ad0-b243-2e62018154cb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8aba780a-1390-599a-8176-ef852f3c0812","sourceKey":"bank:GST111:G111N1-136","parentItemId":null,"revision":1,"payload":{"prompt":"Shakespeare is said to have used about how many words?","options":["21,000","1,000,000","12,000","10,000"],"correctOption":0,"section":"Vocabulary Development","explanation":"Shakespeare is said to have used about 21,000 words. The figure 10,000 is the number that hardly any learner knows, and one million is the estimate of all English words."}},{"itemId":"45800386-2c87-5f00-8589-a919f578926d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"65fb8fe4-3be3-5566-a47b-0a7fa61ce60e","sourceKey":"bank:GST111:G111N1-137","parentItemId":null,"revision":1,"payload":{"prompt":"French words such as those about the kitchen, cooking and government entered English mainly through","options":["the Renaissance","the arrival of the Angles, Saxons and Jutes","the spread of Christianity","the Norman Conquest of 1066 AD"],"correctOption":3,"section":"Vocabulary Development","explanation":"The Norman Conquest of 1066 AD brought French words about the kitchen, cooking, government and administration into English. The Renaissance is linked instead with Greek and Latin words, while the Angles, Saxons and Jutes brought Anglo-Saxon, the native base of English."}},{"itemId":"93285f3a-6806-595e-8889-a8fc813810b9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8a5312a1-c11a-5a5a-ac1d-68d4245f7527","sourceKey":"bank:GST111:G111N1-138","parentItemId":null,"revision":1,"payload":{"prompt":"The words 'dilly-dally', 'nitty-gritty' and 'topsy-turvy' are formed by","options":["clipping","blending","coining","reduplication"],"correctOption":3,"section":"Vocabulary Development","explanation":"Reduplication doubles all or part of a word, usually changing one vowel or consonant, as in 'dilly-dally'. Blending is different: it joins part of one word to part of another, as in 'smog' from smoke and fog."}},{"itemId":"3b596f28-1d0c-5560-8af7-2155a736786c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"24338763-25da-5fd5-9b81-45b6d38cdb2e","sourceKey":"bank:GST111:G111N2-001","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a non-finite clause?","options":["because he visited us","having died down","who came here today","while in prison"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A non-finite clause has a verb that does not change for number, person or tense, and it often has no subject; \"having died down\" fits this exactly. \"While in prison\" is tempting, but it has no verb at all, so it is a verbless clause, not a non-finite one."}},{"itemId":"513df50e-24ef-5f58-b4e1-73e1fe16c80d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5e704c62-7fdf-58b7-8d42-0ac82fe53e64","sourceKey":"bank:GST111:G111N2-002","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"While in prison, he wrote a novel\", the clause \"while in prison\" is best described as a","options":["finite clause","non-finite clause","verbless clause","noun clause"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"\"While in prison\" has no verb and no subject of its own; the missing subject is understood from the main clause (he), which makes it a verbless clause. It is not a non-finite clause, because a non-finite clause still contains a verb form such as \"being repaired\" or \"to leave\"."}},{"itemId":"b292ae7d-a882-5c2c-bdef-2bf8b0566ee1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2288e18e-7710-5697-89b2-5245efed8a55","sourceKey":"bank:GST111:G111N2-003","parentItemId":null,"revision":1,"payload":{"prompt":"What does the sentence \"The students who arrived late were locked out\" mean?","options":["None of the students arrived on time","All the students were locked out","The students came late because they were locked out","Only the students who came late were locked out"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Without commas, \"who arrived late\" is a defining relative clause: it identifies which students are meant, so only some of them, the late ones, were locked out. If the clause were set off by commas (\"The students, who arrived late, were locked out\"), it would be non-defining and would mean that all the students were locked out."}},{"itemId":"2abde2ae-b7d8-5d95-8d37-d2adb74f36e6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2b41e2c0-e33f-5ac4-a06b-6f9ab8efe7b8","sourceKey":"bank:GST111:G111N2-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which relative pronoun can NOT be used to introduce a non-defining relative clause?","options":["that","whose","which","who"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A non-defining clause adds extra information about a noun that is already known, is set off by paired commas, and does not allow \"that\" (so \"Chike, that had never been ...\" is wrong). \"Which\" is a tempting choice, but it can introduce a non-defining clause, for example \"The car, which was new, broke down\"."}},{"itemId":"0a68732e-f006-5ed7-8c6c-d77e39bcd0a1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7708a6cb-ab16-5aff-8f6e-721d8cc09e6c","sourceKey":"bank:GST111:G111N2-005","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"The fact that she is not here worries everyone in the department\", the clause \"that she is not here\" functions as","options":["a direct object","a subject complement","a prepositional complement","an appositive"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"The noun clause \"that she is not here\" explains what \"the fact\" is, so it stands in apposition to that noun. It is not a direct object, because it does not come after a verb as the thing acted on; it is attached to the noun \"fact\"."}},{"itemId":"a19256c9-a8ab-51bd-8444-5ccc5072f21d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"587da658-c216-5ce2-b22a-83214f7faa4d","sourceKey":"bank:GST111:G111N2-006","parentItemId":null,"revision":1,"payload":{"prompt":"A sentence that has two or more main clauses and at least one subordinate clause is called a","options":["compound sentence","compound-complex sentence","complex sentence","multiple sentence"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A compound-complex sentence combines the features of both types: two or more main clauses plus at least one subordinate clause. A complex sentence is the closest wrong choice, but it has only one main clause with one or more subordinate clauses."}},{"itemId":"fdb1211d-ebde-57ac-a44e-53cb866e7120","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b46a3017-f52e-5525-b7ab-6b0052154009","sourceKey":"bank:GST111:G111N2-007","parentItemId":null,"revision":1,"payload":{"prompt":"A major sentence made up of three or more independent clauses is known as a","options":["complex sentence","compound sentence","multiple sentence","compound-complex sentence"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"When three or more independent clauses are joined together, the result is a multiple sentence. A compound sentence is the nearest wrong answer, but it joins two independent clauses with coordinating conjunctions or conjunctive adverbs."}},{"itemId":"1487f0ce-bae8-513f-afea-de6e1b0c7b8c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"00d54404-daf5-5c21-8e32-dc1b7bde4855","sourceKey":"bank:GST111:G111N2-008","parentItemId":null,"revision":1,"payload":{"prompt":"The imperative sentence \"Let me see.\" expresses which type of directive?","options":["Pleading","Suggesting","Meditating","Permitting"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"\"Let me see\" is the speaker thinking aloud, which is the meditating type of directive. It may look like \"Let's go by bus\", but that one is suggesting, because it proposes an action to others; \"Suit yourself\" is permitting and \"Have mercy\" is pleading."}},{"itemId":"a7c494c4-7d35-5f9b-bedf-54a9f9b069d0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8d295053-bd8c-562c-a253-faed61e53243","sourceKey":"bank:GST111:G111N2-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which clause pattern does the sentence \"The plane took off at eight o'clock\" show?","options":["SVA","SVC","SVOA","SVO"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"The plane\" is the subject, \"took off\" is the verb and \"at eight o'clock\" is an adverbial of time, giving SVA. SVOA is tempting, but there is no object here, since nothing receives the action of taking off."}},{"itemId":"c267dbea-284a-5ea8-8b41-dd19557fc916","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f1e0a05a-0550-599d-bacb-58292ebee81d","sourceKey":"bank:GST111:G111N2-010","parentItemId":null,"revision":1,"payload":{"prompt":"Choose the correct verb: Either you or I ____ responsible for the shop in Balogun market.","options":["are","were","is","am"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"With \"either ... or\" joining mixed members, the verb follows the concord of proximity and agrees with the nearest subject, which is \"I\", so \"am\" is correct. \"Are\" is the tempting choice because \"you\" takes \"are\", but \"you\" is not the member closest to the verb."}},{"itemId":"713d5e5a-afe4-50a7-a292-8ce06680de09","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b8a553f3-82bd-570a-86df-7be98385208a","sourceKey":"bank:GST111:G111N2-011","parentItemId":null,"revision":1,"payload":{"prompt":"Choose the correct verb: The Manager, together with all his staff, ____ at the bank's end-of-year party in Victoria Island.","options":["was","were","have been","are"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A singular subject followed by \"together with\" still takes a singular verb, because the phrase after \"together with\" is not part of the subject; the subject is \"The Manager\". \"Were\" is tempting because \"all his staff\" sounds plural, but those words do not control the verb."}},{"itemId":"a8d60dda-1593-56bb-8a1f-cbbaa741ff97","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"654865b7-bffd-55ff-8547-7cadc5771f00","sourceKey":"bank:GST111:G111N2-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following sentences is grammatically correct?","options":["The number of students in the department is rising.","The number of students in the department are rising.","A number of students is absent from the test.","A number of students was absent from the test."],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"The number of\" refers to a single figure, so it takes a singular verb (is), while \"a number of\" means several and takes a plural verb (were or are). The sentence with \"The number of students ... are rising\" is the most tempting wrong option, but it wrongly treats \"the number\" as plural."}},{"itemId":"4199d488-56ae-5afd-8e05-e88c6cd67391","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3c041eea-c747-58b4-96be-5e1f77802a7c","sourceKey":"bank:GST111:G111N2-013","parentItemId":null,"revision":1,"payload":{"prompt":"\"The jury has reached a verdict\" takes a singular verb because the jury is thought of as one unit. This type of agreement with collective nouns is called","options":["pronoun-antecedent concord","concord of proximity","tense concord","notional concord"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Collective nouns follow notional concord: the verb is singular when the group acts as a unit and plural when its members act as individuals (\"The jury are still arguing\"). Concord of proximity is a different rule, used when a verb agrees with the nearest member of an \"either ... or\" or \"neither ... nor\" subject."}},{"itemId":"dee4c530-1858-5cfc-838e-e76e6c2b193b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a20db94d-febd-5b44-b1a9-1ddc66519f1d","sourceKey":"bank:GST111:G111N2-014","parentItemId":null,"revision":1,"payload":{"prompt":"\"Returning home late one night, a snake bit Olu.\" This sentence contains which fault?","options":["A run-on sentence","A padded sentence","A comma splice","A dangling modifier"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"The phrase \"Returning home late one night\" should modify Olu, but it sits next to \"a snake\", making it seem the snake was returning home; this is a dangling modifier. It can be corrected as \"Returning home late one night, Olu was bitten by a snake\". It is not a comma splice, because a comma splice joins two complete sentences with only a comma."}},{"itemId":"0be2c567-f009-52cb-9371-e58704ab1687","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"189de8c0-31d4-5999-a84a-977e370cd8df","sourceKey":"bank:GST111:G111N2-015","parentItemId":null,"revision":1,"payload":{"prompt":"A student writes \"Because I was hungry.\" as a complete sentence. This is an example of","options":["a sentence fragment","a simple sentence","an imperative sentence","a minor sentence"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"Because\" makes the clause dependent, so \"Because I was hungry.\" is an incomplete thought standing alone, which is a sentence fragment and is unacceptable. A minor sentence such as \"No vacancy.\" is tempting, but a minor sentence is acceptable because its missing parts can be recovered from the context."}},{"itemId":"59988e88-fe27-5644-a9e1-5aca54a2b198","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dd4dc378-ddcc-551b-bc16-20d42ad509d7","sourceKey":"bank:GST111:G111N2-016","parentItemId":null,"revision":1,"payload":{"prompt":"The College of Medicine Library, Idi-Araba, classifies its books using the","options":["Dewey Decimal Classification scheme","National Library of Medicine (NLM) scheme","Universal Decimal Classification scheme","Library of Congress (LC) scheme"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"The College of Medicine Library at Idi-Araba uses the National Library of Medicine scheme, which is designed for the medical sciences. The Library of Congress scheme is the tempting choice because the UNILAG main library uses it, but the medical library follows NLM."}},{"itemId":"8aceedc9-7836-5c1e-85f2-09a21647c33a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e5ff8e43-87f8-5858-b175-2a8716bc8200","sourceKey":"bank:GST111:G111N2-017","parentItemId":null,"revision":1,"payload":{"prompt":"The two public catalogue cabinets in the UNILAG library are the","options":["Title and Series catalogues","Shelf-list and Authority catalogues","Author and Keyword catalogues","Author/Title and Subject catalogues"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"UNILAG has two public catalogue cabinets: one for Author/Title and one for Subject. The Shelf-list and Authority catalogues also exist, but they are for official (staff) use, not for the public."}},{"itemId":"510cebe4-7b92-5ee4-b00c-8fd30e9176d6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1c4b1207-af0f-576f-b94e-9821c0e4e904","sourceKey":"bank:GST111:G111N2-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which catalogues in the library are meant for official use rather than for library users?","options":["The card catalogue and the OPAC","The index and the abstract","The Shelf-list and Authority catalogues","The Author/Title and Subject catalogues"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The Shelf-list and the Authority catalogues are kept for official use by library staff. The Author/Title and Subject catalogues are the tempting wrong answer, but those are the two public cabinets that users consult."}},{"itemId":"02062a20-d828-5956-b00b-e8432cf8300f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"654c5985-9803-59e6-843e-eaff84de4043","sourceKey":"bank:GST111:G111N2-019","parentItemId":null,"revision":1,"payload":{"prompt":"Indexes and abstracts are often described as","options":["bridges to published information","official-use catalogues","gateways to the library shelves","controlled vocabularies"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Indexes and abstracts are called bridges to published information because they lead the user to articles and documents that have been published. They are not official-use catalogues; that term refers to the Shelf-list and Authority catalogues kept by library staff."}},{"itemId":"459e8827-bc66-5cf9-9f34-2346038e39de","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c9df1685-d7f0-576c-8ad6-a341916c0ed3","sourceKey":"bank:GST111:G111N2-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes an index?","options":["A pointer that gives entry points to information but not the full text","A brief summary of a book, article or thesis","The number that shows where a book is shelved","A list of books or written works on a subject"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"An index is a pointer or indicator: it tells you where information can be found but does not give you the full text. A brief summary of a book or article is an abstract, which is a different tool, even though the two are often mentioned together."}},{"itemId":"48b21976-0561-5077-b429-950b5ce12944","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"08fc8660-0b00-5db7-8efe-53ccdb9eb163","sourceKey":"bank:GST111:G111N2-021","parentItemId":null,"revision":1,"payload":{"prompt":"Engineering Index and Index Medicus are examples of","options":["bibliographies","indexes","abstracts","library catalogues"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Engineering Index, Index Medicus and the Newspaper Index are all indexes, which point to where information can be found. They are not abstracts; examples of abstracts are Chemical Abstracts, Dissertation Abstracts and LISA, which give brief summaries of documents."}},{"itemId":"f85a428d-6e29-5f21-84d6-6c035c2c2e67","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7771243e-dbc7-5639-b47d-2327919bd70d","sourceKey":"bank:GST111:G111N2-022","parentItemId":null,"revision":1,"payload":{"prompt":"NBN and BNB are examples of which information retrieval tool?","options":["Library databases","Bibliographies","Indexes","Abstracts"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"A bibliography is a list of books or other written works on a subject, and NBN and BNB are examples of such lists. Indexes are tempting because they also point to information, but examples of indexes are Engineering Index and Index Medicus."}},{"itemId":"180171ec-2bfe-5b30-8007-430b2a33cdc9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fc420290-5944-50ac-9ddc-eb201a3bd221","sourceKey":"bank:GST111:G111N2-023","parentItemId":null,"revision":1,"payload":{"prompt":"In a library catalogue, terms that lead the user from known terms to unknown ones and back are called","options":["call numbers","authority entries","cross-references","subject keywords"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Cross-references link related terms in the catalogue, taking the user from a term they know to one they do not know, and back. A call number is different: it is the number generated when an item is catalogued and shows where it is located."}},{"itemId":"d2b33e40-a321-54c3-b4ae-0793ac6c87a8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dabf10ef-841e-52d4-b047-407943fba70e","sourceKey":"bank:GST111:G111N2-024","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG student searching the OPAC with \"Author (last name first)\" for a book by Chinua Achebe should type","options":["Chinua Achebe","Chinua A.","Achebe, Chinua","Chinua, Achebe"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"An author search with \"last name first\" requires the form LAST NAME, FIRST NAME, so the entry is \"Achebe, Chinua\". \"Chinua Achebe\" is how the name is normally written, which makes it tempting, but it puts the first name first."}},{"itemId":"bf988e11-02bc-5c22-9c07-e2189c128121","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d2cd91e0-011f-51a1-a956-5f9f5ef08f6e","sourceKey":"bank:GST111:G111N2-025","parentItemId":null,"revision":1,"payload":{"prompt":"A law student at UNILAG wants databases devoted to legal information. Which group should she use?","options":["EBSCOhost and JSTOR","Jaypee Digital","Westlaw, HeinOnline and LexisNexis","Dogpile and Metacrawler"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Westlaw, HeinOnline and LexisNexis are the law databases. EBSCOhost and JSTOR are tempting because they are well known, but they are interdisciplinary databases covering many subjects, not law specifically."}},{"itemId":"b08f700d-54cd-56d0-a64e-c485c2b2ab90","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2731a631-2e5f-5850-add9-56ae682523a2","sourceKey":"bank:GST111:G111N2-026","parentItemId":null,"revision":1,"payload":{"prompt":"When results in a library database are ranked by date, they are arranged","options":["chronologically, on a first in, first out basis","chronologically, on a last in, first out basis","alphabetically by author's surname","by how often the search terms appear"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Ranking by date is chronological and follows LIFO, last in, first out, so the newest items appear first. Ranking by how often the search terms appear is a different method, ranking by relevance."}},{"itemId":"6433d4a2-3fd3-5fbd-b198-659e4ed56bd4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ab786255-ac24-5ac1-933f-0027b2df79d9","sourceKey":"bank:GST111:G111N2-027","parentItemId":null,"revision":1,"payload":{"prompt":"In the Library of Congress scheme, books on Mathematics are found in subclass","options":["QA","QD","QC","HA"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Under class Q (Science), QA is Mathematics. QC is Physics and QD is Chemistry, and HA, though it holds Statistics, belongs to the Social science class H."}},{"itemId":"c195682d-5f71-5367-a0f7-c29a8f37d0d3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d2d5523b-bcff-52d5-bd64-78ee8558b472","sourceKey":"bank:GST111:G111N2-028","parentItemId":null,"revision":1,"payload":{"prompt":"A Business Administration student at UNILAG wants books on finance. Under the Library of Congress scheme, she should go to subclass","options":["HG","HF","HC","HB"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Under class H (Social science), HG is Finance. HF is the closest wrong choice, but it holds Commerce, while HB is Economic theory and HC is Economic history."}},{"itemId":"c32ae9e8-9433-5d61-b919-05d7657700df","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f288dec9-8139-5cfc-921c-7c4bf74cd133","sourceKey":"bank:GST111:G111N2-029","parentItemId":null,"revision":1,"payload":{"prompt":"In the National Library of Medicine (NLM) scheme, the preclinical sciences are classed in","options":["R","W to WZ","QA to QR","QS to QZ"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"NLM places the preclinical sciences, such as Human Anatomy (QS) and Physiology (QT), in QS to QZ. W to WZ is the tempting choice, but that range is used for medicine itself, such as WY Nursing."}},{"itemId":"41b94466-233b-5628-ac86-80262d704b95","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1119c776-644a-5299-bfb3-8981a1ef0304","sourceKey":"bank:GST111:G111N2-030","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG student needs a book held only by another university's library. Since students do not have reciprocal borrowing rights at all Nigerian universities, the service to use is","options":["interlibrary loan","an OPAC advanced search","cross-referencing","the Shelf-list"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Interlibrary loan lets UNILAG obtain an item from another library for its user, although it can take a week or more. An OPAC advanced search is tempting, but it only searches the library's own catalogue and cannot bring in a book from elsewhere."}},{"itemId":"2946db2c-1182-547e-9d1d-e6486ca15c59","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d20bc69f-f93b-58cb-9d08-cc269f82a6d2","sourceKey":"bank:GST111:G111N2-031","parentItemId":null,"revision":1,"payload":{"prompt":"In a basic search strategy, a general overview of a topic is best obtained from","options":["abstracts and indexes","a general encyclopaedia such as Britannica or Americana","a meta search engine","the card catalogue or OPAC"],"correctOption":1,"section":"Search Strategies","explanation":"After identifying the topic, the second step is to get a general overview, for example from a general encyclopaedia such as Britannica or Americana. Abstracts and indexes are tempting, but they belong to the third step, the narrower overview."}},{"itemId":"e89a6314-da72-5e5e-b5d3-0c70fff291ff","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1d0e11b2-cf51-54c5-8e3f-e97887defe19","sourceKey":"bank:GST111:G111N2-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following shows the correct order of the three basic steps in a search strategy?","options":["Identify the topic, take a narrower overview, get a general overview","Get a general overview, identify the topic, take a narrower overview","Identify the topic, get a general overview, take a narrower overview","Take a narrower overview, get a general overview, identify the topic"],"correctOption":2,"section":"Search Strategies","explanation":"A search begins by identifying the subject or topic, then moves to a general overview, and ends with a narrower overview using abstracts, indexes, bibliographies or the catalogue. Starting with the general overview is tempting, but a research exercise must be topic-driven, so the topic comes first."}},{"itemId":"3bf24a9e-062b-5434-9b77-45685b78314d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d3d7c19-49b4-59bd-8d3b-d95887ca7a27","sourceKey":"bank:GST111:G111N2-033","parentItemId":null,"revision":1,"payload":{"prompt":"In the five stages of electronic searching, what is the final stage?","options":["Decide which resources to use","Run the search","Review and refine","Define your information need"],"correctOption":2,"section":"Search Strategies","explanation":"The five stages end with reviewing the results and refining the search. Running the search is tempting, but it is the fourth stage; after it you still review what you found and adjust."}},{"itemId":"3006a1a1-ef74-5be6-af80-6751eaef5c3e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"56420d73-c7c6-5651-8efd-33f562bc49e7","sourceKey":"bank:GST111:G111N2-034","parentItemId":null,"revision":1,"payload":{"prompt":"In the five stages of electronic searching, which stage comes immediately after \"Decide which resources to use\"?","options":["Find out what search options they offer","Define your information need","Review and refine","Run the search"],"correctOption":0,"section":"Search Strategies","explanation":"Once you have chosen your resources, the next stage is to find out what search options they offer, and only then do you run the search. \"Run the search\" is tempting, but it is the fourth stage, not the third."}},{"itemId":"bdfddbbe-f738-59aa-a349-17bc7ff04da1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"96494bbe-9cbd-522b-9f6c-17994ae025a8","sourceKey":"bank:GST111:G111N2-035","parentItemId":null,"revision":1,"payload":{"prompt":"Boolean searching is based on the symbolic logic developed by","options":["George Boole, a 20th-century American librarian","Charles Boole, a 19th-century English philosopher","George Boole, a 19th-century English mathematician","George Bool, an 18th-century Scottish engineer"],"correctOption":2,"section":"Search Strategies","explanation":"Boolean searching takes its name from George Boole, a 19th-century English mathematician whose symbolic logic underlies the AND, OR and NOT operators. The option describing him as a 20th-century American librarian gets the name right but his century, nationality and profession wrong."}},{"itemId":"3806d08f-53bf-5217-b5f9-3aafc9f20bf0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2fa93436-48a0-5a84-84d7-e62e5d362db8","sourceKey":"bank:GST111:G111N2-036","parentItemId":null,"revision":1,"payload":{"prompt":"What is the effect of using AND between search terms?","options":["It excludes the second term from the results","It makes the terms appear side by side as a phrase","It broadens the search, because any of the terms may appear","It narrows the search, because all the terms must appear"],"correctOption":3,"section":"Search Strategies","explanation":"AND narrows a search because every record retrieved must contain all the terms. Broadening, where any of the terms may appear, is what OR does, so that option is the most tempting mix-up."}},{"itemId":"69bd3a1e-be97-5846-aaa5-c37b73cabb79","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dfbb1fdd-ae00-574d-8107-09346799e930","sourceKey":"bank:GST111:G111N2-037","parentItemId":null,"revision":1,"payload":{"prompt":"A student searches for \"cloning NOT sheep\". What will the results contain?","options":["Records on sheep that do not mention cloning","Records on cloning that do not mention sheep","Records on both cloning and sheep","Records on either cloning or sheep"],"correctOption":1,"section":"Search Strategies","explanation":"NOT excludes the term that follows it, so the search keeps records on cloning and removes any that mention sheep. Records on both cloning and sheep would come from AND, which is the most likely confusion."}},{"itemId":"37aea149-9413-5635-a173-a08571072f08","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bf6f9c73-8750-56a4-9eb7-58a310e3e08b","sourceKey":"bank:GST111:G111N2-038","parentItemId":null,"revision":1,"payload":{"prompt":"When you type several words into Google without any operator between them, Google treats them as if they were joined by","options":["NOT","OR","AND","quotation marks"],"correctOption":2,"section":"Search Strategies","explanation":"Google implies AND between the terms you type, so it looks for pages containing all of them. It does not assume quotation marks; without them the words do not have to appear side by side as a phrase."}},{"itemId":"7f05ee96-06e5-55c3-9ff2-28ca837ec075","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"15986335-a8c7-524e-9273-d0be44699d01","sourceKey":"bank:GST111:G111N2-039","parentItemId":null,"revision":1,"payload":{"prompt":"In the search \"(vomit OR diarrhoea) AND blood\", why are vomit OR diarrhoea placed in parentheses?","options":["So that those terms are excluded from the search","So that the search ignores different word endings","So that the two words must appear side by side","So that the terms inside the parentheses are read first"],"correctOption":3,"section":"Search Strategies","explanation":"Terms inside parentheses are read first, so the search first gathers records on vomit or diarrhoea and then keeps those that also mention blood. Making words appear side by side is the job of quotation marks in phrase searching, not parentheses."}},{"itemId":"e75e3957-2def-57bb-96b3-5174ebce0d8c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"24dd791c-c8ca-5abe-8816-9a454ed5927d","sourceKey":"bank:GST111:G111N2-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following search techniques broadens a search?","options":["Truncation","Phrase searching","Using NOT","Using AND"],"correctOption":0,"section":"Search Strategies","explanation":"Truncation broadens a search because a root with an asterisk retrieves all its endings, such as teen, teens and teenager. Phrase searching is tempting because it also uses a symbol, but quotation marks force the words to appear side by side, which narrows the search."}},{"itemId":"04a52f4a-99b6-5e59-81be-8a730ae441bf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bfd561fd-ca78-57a8-a605-21ade8b96b4c","sourceKey":"bank:GST111:G111N2-041","parentItemId":null,"revision":1,"payload":{"prompt":"A search for \"colo?r\" that retrieves both \"color\" and \"colour\" is using","options":["field searching","truncation","phrase searching","a wildcard"],"correctOption":3,"section":"Search Strategies","explanation":"A wildcard, usually \"?\", stands for one character, which makes it useful for US and UK spellings such as color and colour. Truncation is the closest wrong answer, but it uses an asterisk at the end of a root to pick up all possible endings."}},{"itemId":"74a09eb0-696d-5462-b970-4cb7caba2707","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bea7c899-2f72-5ab0-813e-ad922b26aab7","sourceKey":"bank:GST111:G111N2-042","parentItemId":null,"revision":1,"payload":{"prompt":"A student in Ikeja limits a search so that her keyword must appear in the title and the results must be PDF files. Which technique is she using?","options":["Truncation","Boolean searching","Wildcard searching","Field searching"],"correctOption":3,"section":"Search Strategies","explanation":"Field searching restricts the search to a specific part of the record, such as the title, author, date range, language, domain or file type. Boolean searching is tempting, but it combines terms with AND, OR and NOT rather than targeting parts of the record."}},{"itemId":"278f9ca3-b636-5c9e-b9f2-214b0f9dccd5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"63d3eeae-9a26-5aab-92ee-6a87e9d06fd7","sourceKey":"bank:GST111:G111N2-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of searching uses controlled vocabulary and searches only the subject or descriptor field?","options":["Subject searching","Meta search","Simple search","Keyword searching"],"correctOption":0,"section":"Search Strategies","explanation":"Subject searching relies on fixed subject headings (controlled vocabulary) and looks only in the subject or descriptor field, which makes it less flexible but gives very relevant results. Keyword searching is the opposite: it matches natural-language words anywhere in the record."}},{"itemId":"5f1d0074-25b8-557a-bbce-48fe5b688ee0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8233e1bf-83dd-549b-a804-556864388f26","sourceKey":"bank:GST111:G111N2-044","parentItemId":null,"revision":1,"payload":{"prompt":"Search engines build their huge databases of Internet files by using","options":["librarians who select and evaluate each file","call numbers assigned during cataloguing","a crawler, robot or spider","controlled vocabulary and subject headings"],"correctOption":2,"section":"Search Strategies","explanation":"Search engines collect Internet files automatically with programs called crawlers, robots or spiders. Librarians who select and evaluate each file is the tempting wrong option, but search engines have no selection or evaluation policy at all."}},{"itemId":"03bc165d-5e4b-5179-822e-ae472d7f0579","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f035a3a9-7d10-5349-96b2-c1f84d26c32e","sourceKey":"bank:GST111:G111N2-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about search engines such as Google is true?","options":["They have no selection or evaluation policy","They index only peer-reviewed journal articles","They search only the subject or descriptor field","They are subscribed to by the university library"],"correctOption":0,"section":"Search Strategies","explanation":"Search engines collect whatever their crawlers find and have no selection or evaluation policy, which is why their results must be judged carefully. Being subscribed to by the library describes library databases such as JSTOR and EBSCOhost, not search engines."}},{"itemId":"ec27d6db-82c5-55e8-8a8c-bfb97e3b45af","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cf1d682c-b7ce-5806-b7e9-890aa42bfdf3","sourceKey":"bank:GST111:G111N2-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a meta search engine?","options":["EBSCOhost","Google Scholar","JSTOR","Dogpile"],"correctOption":3,"section":"Search Strategies","explanation":"Dogpile, like Search.com and Metacrawler, is a meta search engine that searches several tools such as Google and Yahoo at the same time. JSTOR and EBSCOhost are library databases, and Google Scholar is a single search tool for academic information."}},{"itemId":"9c27d100-4bf2-53ea-b7d0-4e223570283a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"20ce50c0-5dbc-5d9e-93a8-8d3c4473afef","sourceKey":"bank:GST111:G111N2-047","parentItemId":null,"revision":1,"payload":{"prompt":"A 100L student researching \"the effects of acid rain on the crops in Ogun State\" should prepare keywords by","options":["keeping only the verbs in the sentence","typing the full sentence exactly as written","using nouns and noun phrases and dropping articles and prepositions","putting the whole sentence in quotation marks"],"correctOption":2,"section":"Search Strategies","explanation":"Good keywords are nouns and noun phrases, such as acid rain, crops and Ogun State, with words like \"the\" and \"on\" left out. Typing the full sentence is tempting, but searches work poorly with full sentences because the extra words add nothing useful."}},{"itemId":"c74c96dd-5d1f-5760-b74c-c04d9dd4d2dc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d62c49be-46af-5bb2-bb57-791de845451c","sourceKey":"bank:GST111:G111N2-048","parentItemId":null,"revision":1,"payload":{"prompt":"A search returns too many unrelated results. Which of the following would help?","options":["Using broader vocabulary","Searching the title field only","Dropping the least important concept","Combining synonyms with OR"],"correctOption":1,"section":"Search Strategies","explanation":"Restricting the search to the title field narrows the results, as do AND, NOT, phrase searching and more specific vocabulary. Combining synonyms with OR is the most tempting wrong option, but it broadens a search and is the remedy for too few results."}},{"itemId":"1dfa4a5a-05a9-521b-876c-016325a6b351","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b635121d-17e7-5c9d-afce-e493608ab279","sourceKey":"bank:GST111:G111N2-049","parentItemId":null,"revision":1,"payload":{"prompt":"A simple search is most suitable when","options":["you need to filter results by year of publication","you are unsure of what you need or the topic is unfocused","you want to use many search tools at the same time","you want to apply several search fields at once"],"correctOption":1,"section":"Search Strategies","explanation":"A simple search is a quick keyword search that suits an unfocused topic such as \"Malaria and Africa\", although it brings back a huge, often irrelevant output. Filtering by year of publication and applying several search fields are features of advanced search."}},{"itemId":"c04a07d4-75ef-5981-b7b3-56fd6d2b871d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e17a6182-dc4b-597a-a23c-86360577c552","sourceKey":"bank:GST111:G111N2-050","parentItemId":null,"revision":1,"payload":{"prompt":"The word \"plagiarism\" comes from the Latin word plagiarius, which means","options":["thief of books","copier","forger","kidnapper"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism comes from the Latin plagiarius, meaning \"kidnapper\", because the plagiarist carries off someone else's work as if it were his own. \"Thief of books\" is tempting since plagiarism is called academic theft, but that is not the meaning of the Latin word."}},{"itemId":"8dc6752e-7263-54f8-bc8d-629dc7d49e7d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2211c373-cfb0-5281-9daa-2a289da4028c","sourceKey":"bank:GST111:G111N2-051","parentItemId":null,"revision":1,"payload":{"prompt":"Using the Internet to take another person's ideas or expression without acknowledgement is known as","options":["secondary citation","fair use","cyber plagiarism","self-plagiarism"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"Cyber plagiarism is plagiarism carried out through the Internet, such as copying text from a website. Self-plagiarism is tempting, but it means copying from your own earlier assignment for a new one without acknowledgement."}},{"itemId":"605e565c-c7f5-506d-ab74-7e20c14803a9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9739c840-6be2-5f64-af2b-09bbefc8e394","sourceKey":"bank:GST111:G111N2-052","parentItemId":null,"revision":1,"payload":{"prompt":"Using APA style, which of the following is cited in the text but NOT included in the reference list?","options":["A journal article read in JSTOR","A telephone conversation with a bank manager in Lagos","A book on management principles","A government report found on a website"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Personal communications such as conversations and emails cannot be retrieved by the reader, so they are cited only in the text. A government report on a website is tempting, but it can be retrieved, so it appears in both the text and the reference list."}},{"itemId":"06d364c5-208d-50ee-862d-7b2c13f37a31","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2bc739d4-537c-5526-a348-2165c6169006","sourceKey":"bank:GST111:G111N2-053","parentItemId":null,"revision":1,"payload":{"prompt":"In APA style, a direct quotation of 40 words or more should be","options":["placed within the text in single quotation marks and italics","moved to a footnote at the bottom of the page","placed within the text in double quotation marks","set as a block on a new line, indented, without quotation marks"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A quotation of 40 words or more is set as a block starting on a new line, indented 5 spaces, with no quotation marks. Putting it in the text within double quotation marks is the rule for quotations of fewer than 40 words, which is why that option is tempting."}},{"itemId":"8e062f28-9ff8-5efb-98a5-b61951bfbdf3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"22ad1cf9-97c5-52e7-a11b-9da6f54fba80","sourceKey":"bank:GST111:G111N2-054","parentItemId":null,"revision":1,"payload":{"prompt":"A student read Talbot and Verrinder (2005), who quote Palfrey (2000), but she never read Palfrey's own work. In APA style, which work goes in her reference list?","options":["Palfrey (2000) only","Both Palfrey (2000) and Talbot and Verrinder (2005)","Talbot and Verrinder (2005) only","Neither source"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"In a secondary citation, only the work you actually read goes in the reference list, so Talbot and Verrinder is listed and Palfrey is mentioned in the text as \"as cited in\". Listing both is tempting, but Palfrey's work was not consulted directly."}},{"itemId":"1e7dd323-2a9b-5187-b5bc-eedecee74a4b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7793c89a-9b62-5087-91e4-f757cad5c43c","sourceKey":"bank:GST111:G111N2-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a correctly formatted Harvard in-text citation?","options":["(Austen 64)","(Austen 1813, p. 64)","(1813 Austen, p. 64)","(Austen, 1813, p. 64)"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Harvard is an author-date style with no comma between the author and the year, as in (Austen 1813, p. 64). The version with a comma after Austen looks very similar, but that comma is the APA pattern, while (Austen 64) is the MLA author-page form."}},{"itemId":"b55fe8e9-2f1c-58e9-9654-9ec5bf85f720","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a7ff7428-7267-5d74-bf6d-82baf8dbb789","sourceKey":"bank:GST111:G111N2-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an entry in MLA Works Cited format?","options":["McDonagh, Sean. Why are we Deaf to the Cry of the Earth. Dublin: Veritas, 2001.","McDonagh, S. (2001). Why are we deaf to the cry of the earth. Dublin: Veritas.","Sean McDonagh, 2001. Dublin: Veritas. Why are we Deaf to the Cry of the Earth.","McDonagh, S 2001, Why are we deaf to the cry of the earth, Veritas, Dublin."],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"MLA Works Cited entries follow the pattern Last name, First name. Title. Place: Publisher, Year, with the year at the end. The entry with \"(2001)\" straight after the initial is the APA pattern, and the one with the year after the name and no brackets is Harvard."}},{"itemId":"6b0e99eb-60d3-5f66-aaed-a7f438e8651f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5c6156a2-cda5-53fe-851b-9467a9dd2a34","sourceKey":"bank:GST111:G111N2-057","parentItemId":null,"revision":1,"payload":{"prompt":"In the APA reference \"Australian Nursing Journal, 12(7), 23-25\", which part is italicised along with the journal title?","options":["The volume number, 12","Both the volume and the issue numbers","The page range, 23-25","The issue number, 7"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"In APA, the journal title and its volume number are italicised, while the issue number in brackets is not. Italicising both the volume and issue numbers is the tempting mistake, because they sit side by side."}},{"itemId":"654263b8-6368-5b36-a254-4206aa683123","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"86a550c9-7972-594f-9614-2bc82cfc2fba","sourceKey":"bank:GST111:G111N2-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a purpose allowed under fair use?","options":["Criticism and comment","Selling photocopies of a published book for profit","News reporting","Teaching"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Fair use permits criticism, comment, news reporting, teaching and similar non-commercial uses of copyrighted works. Selling photocopies for profit is commercial, so it falls outside fair use; teaching may look like it needs permission, but it is one of the allowed purposes."}},{"itemId":"b1320982-b19b-5ccf-b6dc-97a1c8bfb8ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6944825a-5262-5712-bf54-54bbf66ba396","sourceKey":"bank:GST111:G111N2-059","parentItemId":null,"revision":1,"payload":{"prompt":"Copying a copyrighted work indiscriminately, with or without acknowledgement, is called","options":["fair use","self-plagiarism","paraphrasing","unfair use"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Unfair use is indiscriminate copying of a copyrighted work, and acknowledging the author does not make it acceptable. Fair use is the tempting opposite: it is use for academic and similar purposes up to a certain limit."}},{"itemId":"95bb2d28-6a43-5678-80ea-a883ecfb0177","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f1468137-6653-5a86-9419-a1b27d8575fb","sourceKey":"bank:GST111:G111N2-060","parentItemId":null,"revision":1,"payload":{"prompt":"A member of staff found guilty of plagiarism can face","options":["loss of hostel accommodation","summary dismissal","a written warning only","rustication"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"For staff, the consequence of plagiarism is summary dismissal, and prosecution is also possible. Rustication is tempting, but it is a penalty for students, together with suspension."}},{"itemId":"c7afc734-cf5b-563b-9b3e-04a6b58a27a8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"51661132-9e5d-5c0b-8e91-3a131aa8f46b","sourceKey":"bank:GST111:G111N2-061","parentItemId":null,"revision":1,"payload":{"prompt":"In APA style, page numbers are NOT required in the in-text citation when you","options":["quote fewer than 40 words directly","paraphrase or summarise an author's idea","quote 40 words or more as a block","quote a definition word for word"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"A paraphrase or summary needs only the author's surname and the year, with no page number. Any direct quotation, short or long, needs the page number as well, which rules out the other three options."}},{"itemId":"499f18cf-1efe-5a10-9f2c-53010010e406","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7c68dc81-acf9-5a81-8aad-9b1e4f05d941","sourceKey":"bank:GST111:GST111-0001","parentItemId":null,"revision":1,"payload":{"prompt":"Listening entails;","options":["Specifying what a speaker would say","The ability to identify and understand what a speaker is saying","Making assertions and statement that guide the speakers speech","Keeping quite so that the speaker is not distracted"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Listening is the ability to receive, perceive and decode the meaning of spoken words, so B is correct. It is a receptive skill: you take in and understand what the speaker is saying. Options A and C describe the listener acting on the speaker (predicting or guiding the speech), and D, keeping quiet, is just good manners, not listening itself."}},{"itemId":"ebe5e835-2aa2-5dca-bb01-ac86b1282ee2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c11e274d-8e34-5c8f-ba56-099e721ffdf1","sourceKey":"bank:GST111:GST111-0002","parentItemId":null,"revision":1,"payload":{"prompt":"Effective listening requires that;","options":["The listener dictates the pace and speed of the speakers delivery","The listener must pay total attention to what the speaker is saying","The listener interrupts the speaker whenever a point seems wrong","Examining the speakers attitude and comportment"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Effective listening starts with giving total attention to what the speaker is saying, which is option B. You concentrate on the content and wait for the speaker to finish a point before judging it. Option C is wrong because interrupting breaks your concentration and leads to hasty conclusions, and options A and D focus on controlling or judging the speaker instead of receiving the message."}},{"itemId":"c32136a5-e410-5a8e-87e0-6f304c69b4d4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e0a7dea3-98a4-5ab4-95bc-f4926b2fa57c","sourceKey":"bank:GST111:GST111-0003","parentItemId":null,"revision":1,"payload":{"prompt":"The skills involved in listening are;","options":["Reading through the topic carefully","Preparing ahead of the lecture","Understanding the speaker's accent, vocabulary and presentation of the topic.","Writing down verbatim everything the speaker says"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Listening is about decoding a spoken message, so the skills involved include understanding the speaker's accent, vocabulary and way of presenting the topic, which is option C. A lecturer's pronunciation and intonation can become barriers, which is why listeners learn to pick up cues like accent and word stress. Options A and B are things you do before the lecture, not listening skills, and D, writing down everything verbatim, is a note-taking habit you should avoid."}},{"itemId":"73b4f8ef-b4f0-5d85-a9aa-7ba863168b8c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9cb19fa9-c1b7-56cc-b446-9a0229d35268","sourceKey":"bank:GST111:GST111-0004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these does not negatively affect listening","options":["Interfering background noise","Unfamiliar accent and speech affectation","Difficult vocabulary","Organized and cohesive speech"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Organized and cohesive speech helps the listener follow the message, so it does not harm listening, and that makes D the answer to this 'does not' question. Listening becomes unproductive because of things like noise in the environment, a speaker's pronunciation problems and the listener's state of mind. Background noise (A), an unfamiliar accent (B) and difficult vocabulary (C) are all barriers, so they do hurt listening."}},{"itemId":"75092682-530a-53a3-adf0-263caf50eb52","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"eae413c8-320f-59bf-a2bd-7a060ce593c6","sourceKey":"bank:GST111:GST111-0005","parentItemId":null,"revision":1,"payload":{"prompt":"All but one of the following are necessary in pre-lecture preparations;","options":["Conducting surveys of course outlines and topic before hand","Making intelligent speculations about the lecturers sources","Arrival at lectures ahead of the lecturer","A reading of some introductory surveys if the topic is unfamiliar"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Option B is the odd one out: guessing about the lecturer's sources is not part of preparing for a lecture. Good preparation means revising related earlier lectures, reading about the topic, checking the meaning of new key words, and arriving early to sit close to the lecturer. Options A, C and D all match those habits, so they are necessary and cannot be the answer to this 'all but one' question."}},{"itemId":"8405fca2-42f3-56bc-b3a8-682fad05c65f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8a3f619c-5886-5ab5-bdf6-62e036869375","sourceKey":"bank:GST111:GST111-0006","parentItemId":null,"revision":1,"payload":{"prompt":"The main goal of a lecture is to;","options":["Give course outline to students","Impart knowledge to students","Trade information between lecturer and students","Introduce lecturers to students"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"The main goal of a lecture is to impart knowledge to students, which is option B. The lecturer speaks on a subject so that students can capture its essence. Giving a course outline (A) or introducing lecturers (D) are small administrative matters, and C is wrong because a lecture is mostly one-way delivery from lecturer to students, not an equal trade of information."}},{"itemId":"ed353e4d-510c-5adb-8bd0-93b020b19fd9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4f91ec7b-88b2-5fed-bda0-d978b1c381be","sourceKey":"bank:GST111:GST111-0007","parentItemId":null,"revision":1,"payload":{"prompt":"Lecturer delivery usually has three parts. These are;","options":["Introduction, main lecture and conclusion","Outline, main discussion and question time","Summary, main lecture and expansion of outlined points","Introduction, revision and conclusion"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Like any well-organized piece of communication, a lecture has an introduction, a main body and a conclusion, so A is correct. Lecturers even use transition words such as however and consequently to move from one part to the next. Options B and D include items like question time or revision that are not standard parts of the delivery itself, and C wrongly puts a summary at the start."}},{"itemId":"40f1bf39-e61f-5e47-8746-008f79cc5673","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b5223c03-2d74-5a0e-92b9-d80ba4bc13f6","sourceKey":"bank:GST111:GST111-0008","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a recommended practice in note taking;","options":["Verbatim recording","Use of personal abbreviations","Logical thinking of ideas","Summary of main points"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Verbatim recording, option A, is not recommended because you cannot and should not try to write down everything the lecturer says. Instead, reduce the lecture to note form using shorthand, symbols and abbreviations. Options B, C and D (personal abbreviations, logical organization of ideas and summarizing main points) are all good note-taking practices."}},{"itemId":"d364220a-93b6-597e-bfcf-aac006e1fff0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6b2470de-b523-5ca7-93ff-b3966b3b68dc","sourceKey":"bank:GST111:GST111-0010","parentItemId":null,"revision":1,"payload":{"prompt":"All but one of the following are bad habits in note taking;","options":["Verbatim recording of everything in note taking","Recording main points with all the illustration","Recording main points and a selection of illustrations and examples","Recording all that the lecturer says"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Good note-taking means separating main points from elaborations, examples and repetitions, and reducing the lecture to compact form. Recording the main points with just a selection of illustrations and examples (option C) does exactly this, so it is the one good habit. Options A and D both mean writing down everything, and B, recording every illustration, defeats the purpose of condensing the lecture."}},{"itemId":"bd05b256-ed4e-583e-8233-a8c72599d02a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"73706b32-6985-59cf-921a-0ad173c142ec","sourceKey":"bank:GST111:GST111-0011","parentItemId":null,"revision":1,"payload":{"prompt":"Note taking involves the following except;","options":["Summarizing the main point","Using inconsistent personal abbreviations","Making a selection from illustrations","Disregarding digressions"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Inconsistent personal abbreviations (option B) are not part of good note-taking. You may invent your own symbols and abbreviations, but you must use them consistently, otherwise you will not be able to read your own notes later. Summarizing main points (A), selecting from illustrations (C) and ignoring digressions (D) are all things effective note-takers do."}},{"itemId":"7c2e121c-77a2-5a00-8b21-a82b7b0cf4f0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9c2bbb25-5f5d-50c6-bf6f-50b33536c300","sourceKey":"bank:GST111:GST111-0012","parentItemId":null,"revision":1,"payload":{"prompt":"A pre-lecture survey is basically","options":["Asking relevant questions at the beginning of a lecture","Listening and taking down notes during a lecture","Reading up on a topic before the lecture","Discussing a topic with classmates after the lecture"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"A pre-lecture survey simply means reading up on a topic before the lecture, so C is correct. It prepares you by giving you background, along with revising earlier related lectures and checking new key terms. Option A happens at the start of the lecture, B during it and D after it, so none of them is done beforehand."}},{"itemId":"276ec181-93d4-5053-99f0-2b6dcfd93596","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"78f8d2b4-735d-59e6-aee1-36dff99547fb","sourceKey":"bank:GST111:GST111-0013","parentItemId":null,"revision":1,"payload":{"prompt":"A course outline is a listing of the","options":["Specific points raised during a lecture","Relevant topics to be treated in a particular course","Form and content of a topic","Main points articulated during a lecture"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"A course outline lists the relevant topics to be treated in a particular course, so B is correct. It is prepared before teaching begins, so it cannot be a record of the specific or main points raised in a lecture (A and D); those belong in lecture notes. Option C, the form and content of a topic, is much narrower than an outline that covers a whole course."}},{"itemId":"f55babce-3126-524d-a4e1-ba5fcf2aafa3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ce1b8577-0b86-54cc-a6e0-d5d3a8da65ed","sourceKey":"bank:GST111:GST111-0014","parentItemId":null,"revision":1,"payload":{"prompt":"A good note taken from listening to lecturers is not","options":["Brief and concise","Legible","All that is said in class","Systemic and orderly"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"A good note is not a record of all that is said in class, so C is the answer. You should not write down everything the lecturer says; good notes use shorthand, abbreviations and summary to capture the main ideas and relevant details. Being brief and concise (A), legible (B) and systematic and orderly (D) are all qualities of good notes, so they are not the answer to this 'is not' question."}},{"itemId":"238d32db-576a-5a0a-a361-b5b36204c0e1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4a9d7028-1871-588e-9949-68c7645ca866","sourceKey":"bank:GST111:GST111-0015","parentItemId":null,"revision":1,"payload":{"prompt":"Weeding as a library term means","options":["Dusting the shelves","Clearing the tables","Screening library users","Removing outdated books"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"In library work, weeding means removing outdated, damaged or no-longer-useful books from the collection so the shelves hold current, relevant material, which is option D. The word borrows the gardening idea of pulling out unwanted plants. Options A and B are ordinary cleaning jobs and C is about controlling users, none of which is what librarians mean by weeding."}},{"itemId":"b1fdaba2-d83f-536e-91e2-988ec6af85ba","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bb41af41-1923-5d99-b3a7-1a0134ba8bda","sourceKey":"bank:GST111:GST111-0016","parentItemId":null,"revision":1,"payload":{"prompt":"A full essay must have 3 main features","options":["Appropriate choice of words & acceptable sentences","Good paragraphing & grammatical sentences","Coherence & use of standard writing conventions","All of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Option D, all of the above, is correct because each of A, B and C names a real feature of a full essay: appropriate word choice and acceptable sentences, good paragraphing and grammatical sentences, and coherence with standard writing conventions. Choosing just one of A, B or C would leave out features that are equally required in a complete essay."}},{"itemId":"91017d53-54ab-572b-aecc-f68e689df5c8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e7154695-51c2-5008-8df3-34624bd44a92","sourceKey":"bank:GST111:GST111-0017","parentItemId":null,"revision":1,"payload":{"prompt":"Major features of any good writing include;","options":["Introduction, summary, conclusion","Introduction, middle, conclusion","Preamble, definition, main body","None of the above"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Any good piece of writing, like a good lecture or essay, moves from an introduction through a middle (the main body) to a conclusion, so B is correct. Option A wrongly puts the summary in the middle, and C leaves out the conclusion, so neither gives the standard three-part structure."}},{"itemId":"42cf024b-0cde-5ebb-87e1-b2be988ceb9a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2bd6ce83-8b43-5b3e-a6e8-5581b199cb4e","sourceKey":"bank:GST111:GST111-0018","parentItemId":null,"revision":1,"payload":{"prompt":"In report writing, the situation must be based on","options":["Hearsay","Arguments","Proof","Facts"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A report presents a situation to readers who may have to act on it, so it must be based on facts, which is option D. Hearsay (A) is unverified talk and has no place in a report, and arguments (B) belong to persuasive writing. Proof (C) is close, but proof is what you use to support a claim; the report itself rests on the facts of the situation observed."}},{"itemId":"803fa14a-990e-533c-9e7b-6c87b43a0d21","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"025a6d9d-9832-5f6e-8b58-9851b4ab6a90","sourceKey":"bank:GST111:GST111-0019","parentItemId":null,"revision":1,"payload":{"prompt":"The narrative essay has all but one of the following feature","options":["Suspense","Story line","Plot","Strong argument"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A strong argument (option D) is the feature a narrative essay does not need. A narrative essay is a sequential or chronological account of an experience or incident, marked by suspense and other devices so the reader feels a good story has been told. Suspense (A), story line (B) and plot (C) are all narrative features, while a strong argument belongs to the argumentative or persuasive essay."}},{"itemId":"f25b77bc-782c-5b2c-8bd6-7b25258dffc5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5773ded7-37dd-5298-b992-f5ad00390844","sourceKey":"bank:GST111:GST111-0020","parentItemId":null,"revision":1,"payload":{"prompt":"A thesis statement is to an essay what a topic sentence is to;","options":["An introductory paragraph","A concluding paragraph","The paragraph","The main paragraph"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A topic sentence states the main idea of its paragraph, just as a thesis statement states the central idea of the whole essay, so the parallel is with the paragraph, option C. The topic sentence works as the thesis of the paragraph. Options A, B and D are wrong because every paragraph has a topic sentence that controls it, not just the introductory, concluding or main one."}},{"itemId":"476502f4-dcf3-5bbb-8343-9be3b71ccd28","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"44a91626-bf28-5d44-8b0c-6e1bad2ec693","sourceKey":"bank:GST111:GST111-0021","parentItemId":null,"revision":1,"payload":{"prompt":"A police statement is an example of;","options":["An academic writing","Technical report writing","A narrative writing","A research report"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A police statement recounts what happened step by step, in the order events occurred, so it is narrative writing, option C. Narrative writing is a sequential or chronological account of an experience, procedure or incident, and it is largely reportorial in nature. It is not academic writing (A) or a research report (D), and although it reports facts, it is not a technical report (B) because it does not deal with specialized technical procedures."}},{"itemId":"9cdb1227-8f36-5a91-8786-e603b405ad65","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"254071b5-a295-5ac4-af9e-edb19ce3830e","sourceKey":"bank:GST111:GST111-0022","parentItemId":null,"revision":1,"payload":{"prompt":"The main features of an introductory paragraph are;","options":["Statement of thesis, setting of tone, plan","Quotation, topic sentence, summary of essay","Summary, statement of thesis, definition","None of the above"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An introductory paragraph states the thesis, sets the tone and gives the reader a plan of what will follow, so A is correct. A good introduction also arouses the reader's interest and keeps attention on the central theme. Options B and C include a summary of the essay, which belongs in the conclusion, not the introduction."}},{"itemId":"ab94732f-c8f7-5fc4-898c-275d2b7fff93","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"290f7534-b103-5636-a756-eb04c1f86c8f","sourceKey":"bank:GST111:GST111-0023","parentItemId":null,"revision":1,"payload":{"prompt":"Mechanics of writing consists of;","options":["Punctuation","Capitalization","Spelling & letter shapes","All of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Mechanics of writing means the symbols and conventions that organize writing on the page rather than the words themselves, and that covers punctuation, capitalization, and spelling and letter shapes. Since A, B and C are each part of mechanics, D, all of the above, is correct. Choosing only one would leave out other parts of mechanics."}},{"itemId":"0c94e4bb-51bc-580c-8e68-d6903c215cc2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"08475156-e7a8-5449-b9e1-b47f1ec60d00","sourceKey":"bank:GST111:GST111-0026","parentItemId":null,"revision":1,"payload":{"prompt":"Books are placed on reserve to","options":["Minimize wear and tear","To prevent them from getting to unregistered users","To preserve them for serious-minded library-going students","To facilitate a rapid and wider circulation of scarce materials among users"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Books are placed on reserve so that scarce or heavily demanded material can circulate quickly among many users instead of being borrowed by one person for weeks, which is option D. Reserved items are rare and valuable, are not placed on long loan and must be consulted in the reading room. Options A, B and C are wrong because reserving is about sharing access, not protecting books from wear, keeping them from unregistered users or saving them for only serious students."}},{"itemId":"4fdb4c86-6f25-5b6d-baea-2a6ffc047b4f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c6af6028-6906-52e0-8caa-17096c3de1a6","sourceKey":"bank:GST111:GST111-0027","parentItemId":null,"revision":1,"payload":{"prompt":"The circulation section of the library deals with","options":["Borrowing and returning of books","The distribution of books among affiliated libraries","The acquisition of new materials","The cataloguing and classification of acquired materials"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The circulation section handles the lending and return of books, so A is correct; the circulation desk is also where you can ask for help locating a book. Option B is interlibrary lending, a separate service, while acquiring new materials (C) and cataloguing and classifying them (D) are done by the acquisitions and cataloguing sections."}},{"itemId":"e700f576-4735-5084-89b0-f0ccdb5da6f4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"16482db8-f1fa-5546-bfce-711b5719fd8a","sourceKey":"bank:GST111:GST111-0028","parentItemId":null,"revision":1,"payload":{"prompt":"Reference books are those","options":["Used to write research papers","That cannot be borrowed","That are quite bulky","They contain a wealth of materials which cut across various disciplines"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Reference books such as dictionaries, encyclopaedias and handbooks are consulted for specific facts rather than read from cover to cover, so libraries keep them in the reference section and they cannot be borrowed, which is option B. Option A is too narrow, C (bulky) is irrelevant, and D describes general collections rather than what makes a book a reference book."}},{"itemId":"fd348cdd-8682-52b6-afbe-687b2a082e01","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c25aba99-0bce-50e5-b392-c18b8abcdf29","sourceKey":"bank:GST111:GST111-0029","parentItemId":null,"revision":1,"payload":{"prompt":"The system of classification in the University of Lagos main library is","options":["The call mark","The dewey decimal system","The library of congress system","The card catalogue"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library organizes its items using the Library of Congress (LC) classification scheme, so C is correct. LC uses letters A to Z for the main classes with numbers added. Option B, the Dewey Decimal system, is a different scheme, while a call mark (A) and the card catalogue (D) are tools for locating books, not classification systems."}},{"itemId":"7f6e0eaf-26be-578f-960e-d2fdc9748f5d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"18c22671-223b-507c-9503-10bb141774d1","sourceKey":"bank:GST111:GST111-0030","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not part of the card catalogue in library","options":["Index card","Author card","Subject","Title card"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"The manual card catalogue is arranged by author, title and subject, so author cards (B), subject cards (C) and title cards (D) are all part of it. An index card (option A) is not a type of catalogue card, which makes it the odd one out and the correct answer."}},{"itemId":"5cedf52c-2f41-5281-be30-ba76d0925b0b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cf4db145-8a83-5235-ae27-ba119de60341","sourceKey":"bank:GST111:GST111-0031","parentItemId":null,"revision":1,"payload":{"prompt":"The encyclopedia is","options":["A book or a set of books on Britain","A book or a set of books on America","A book or a set of books on one or all branches of knowledge","A book or a set of books compiled by chambers"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"An encyclopaedia is a book or set of books that gives background and current information on one or all branches of knowledge, so C is correct. Encyclopaedias can be general, like Britannica or Americana, or subject-based, like an encyclopaedia of philosophy. Options A, B and D mistake the names Britannica, Americana and Chambers for the definition; those are just titles or publishers."}},{"itemId":"137b639f-d71e-58ac-b29b-b14f96691535","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2e32801e-c1d0-5814-bd7a-f6d584c4a1f4","sourceKey":"bank:GST111:GST111-0032","parentItemId":null,"revision":1,"payload":{"prompt":"Books put in the reserve section of the library","options":["Are intended for use by library staff only","Cannot be borrowed","Can be borrowed for a full semester","Out of the reach of students"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Books in the reserve section cannot be borrowed out of the library, so B is correct. They are rare or valuable, kept on closed access, and must be consulted in the reading room, although photocopying is allowed. Option C is wrong because reserve items are never placed on long loan, and they are meant for students, not staff only (A), so they are not out of students' reach (D)."}},{"itemId":"55f51f3e-0d06-5acc-bffe-a57513931e95","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"13874866-e0b1-54ee-8e87-96b9b3366eec","sourceKey":"bank:GST111:GST111-0033","parentItemId":null,"revision":1,"payload":{"prompt":"Prescribed text usually","options":["Contain all the topics to be treated in a subject","Constitute the lecturers sole sources","Direct the reader to supplementary texts","Contain most of the topics to be treated or the basis for discussion in the lectures"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"A prescribed text is the recommended main book for a course, and it usually contains most of the topics to be treated or forms the basis for discussion in lectures, so D is correct. Option A is too strong because no single text covers every topic, and B is wrong because lecturers use many sources. Directing readers to supplementary texts (C) is a minor side role, not its main purpose."}},{"itemId":"f244ee0d-1ee8-5922-876c-ad338c1b7397","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"53e0df58-7056-5718-bff7-b0a018de92c9","sourceKey":"bank:GST111:GST111-0034","parentItemId":null,"revision":1,"payload":{"prompt":"Which one of these is not recommended for efficient studying","options":["Reading with pre-conceived ideas","Generation of guide questions as you read","Adoption of flexible reading speed","Employing memory enhancing devices"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Reading with pre-conceived ideas (option A) is not recommended because prejudices and emotional attachment to a subject get in the way of understanding; a good reader keeps an open, questioning mind. The other options are good study practices: asking guide questions as you read (B), varying your reading speed to suit purpose and difficulty (C), and using memory aids like mnemonics (D)."}},{"itemId":"2aec54e8-ed2e-50ac-8cbe-a52dedbcd295","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"361775a9-ad37-5016-a34c-2b0fe823d96c","sourceKey":"bank:GST111:GST111-0035","parentItemId":null,"revision":1,"payload":{"prompt":"Supplementary texts are usually given so that","options":["Students may have a wide reading list","Students can have the opportunity to acquire additional information for their courses","Students can fully understand the topics treated in their course","Students educational experience may be balanced"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Supplementary texts are given so that students can get additional information beyond what the main text covers, which is option B. The word 'supplement' means to add to. A long reading list (A) is not a goal in itself, and full understanding (C) or a balanced education (D) are too vague to be the stated purpose."}},{"itemId":"07b5b9b2-6e21-5b22-8866-7ae21de0dc07","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8c7f8700-3da8-5698-a629-23b7de613bd4","sourceKey":"bank:GST111:GST111-0036","parentItemId":null,"revision":1,"payload":{"prompt":"Selective reading is important to students because","options":["It will be in line with qualitative education","It reduces the stress campus rigors","It may be either impossible or a waste of time to read everything in the text","It reinforces the importance of reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Selective reading matters because it may be impossible, or a waste of time, to read everything in a text, so C is correct. Believing you must read every word is a misconception; depending on your purpose and how familiar the material is, you can read selectively. Options A, B and D give vague benefits that do not explain the real reason."}},{"itemId":"3bf59736-ba5d-5243-ad1d-e6b625228717","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e0d0e3c0-ffb6-5a2f-b916-435743b1f87a","sourceKey":"bank:GST111:GST111-0037","parentItemId":null,"revision":1,"payload":{"prompt":"Direct quotation can be distinguished from paraphrase in note taking by","options":["Underlining the quotation","Using quotation marks","Writing the quotation in capital letter","Writing in capital letters as well as underlining it"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"When taking notes, a direct quotation is shown by putting it in quotation marks, so B is correct. Short quotations are set within your text and enclosed in double quotation marks. Underlining (A) or writing in capitals (C and D) are not the recognized ways of showing that words are quoted exactly."}},{"itemId":"4b7cf968-361d-5ded-8d3e-91e326b8ebde","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9592251b-5283-5100-8b99-2bd0294e87cc","sourceKey":"bank:GST111:GST111-0038","parentItemId":null,"revision":1,"payload":{"prompt":"If a scholar does not acknowledge all quoted and borrowed ideas as he reads and writes, he is guilty of","options":["Perjury","Plagiarism","Permutation","Permissiveness"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is using someone's work or ideas without permission or without acknowledging where it came from, and it is often called academic theft, so B is correct. A scholar who does not acknowledge quoted and borrowed ideas is guilty of it. Perjury (A) is lying under oath, and permutation (C) and permissiveness (D) have nothing to do with academic honesty."}},{"itemId":"57d12a91-2141-5636-8f72-088e1537547a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8d31cff9-e8e5-51cf-92ec-45e2c465b80e","sourceKey":"bank:GST111:GST111-0039","parentItemId":null,"revision":1,"payload":{"prompt":"The dictionary contain all but information on","options":["The meaning of words","The pronunciation of words","Etymology","The year the words become obsolete"],"correctOption":3,"section":"Vocabulary Development","explanation":"A dictionary gives a word's spelling, meaning, pronunciation, usage, synonyms, etymology (origin) and grammatical functions. So meaning (A), pronunciation (B) and etymology (C) are all found there. The year a word became obsolete (option D) is not recorded; at most a dictionary labels a word as archaic, so D is the answer."}},{"itemId":"7a11b668-4a24-54f7-83c0-0782a2ee4267","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b6743bca-bb8e-5199-9996-5eccd1a034f4","sourceKey":"bank:GST111:GST111-0040","parentItemId":null,"revision":1,"payload":{"prompt":"Who ______ the telephone?","options":["Discovered","Invented","Founded","Explored"],"correctOption":1,"section":"Vocabulary Development","explanation":"Invented is correct because the telephone is a device that did not exist until someone created it. We discover things that already exist, such as a planet or a mineral, so discovered is the most tempting wrong choice. Founded is used for organisations and explored for places, so neither fits."}},{"itemId":"a8a288aa-7263-5a78-b69d-d8972ace6aca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d5323c6-6e1a-5ff4-a350-5c9b7ce8185b","sourceKey":"bank:GST111:GST111-0041","parentItemId":null,"revision":1,"payload":{"prompt":"The judge was ______ that the man was guilty","options":["Persuaded","Convinced","Believed","Trusted"],"correctOption":1,"section":"Vocabulary Development","explanation":"Convinced is correct because it means made to believe that something is true, which is what happens when a judge accepts that a man is guilty. Persuaded is the tempting choice, but it is normally used for being talked into doing something (persuaded to confess), not for believing a fact. Believed and trusted cannot be used in the pattern 'was ... that' here."}},{"itemId":"e559f46d-a228-52c1-9e49-93187cb1c253","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a858f133-6afc-55c1-a0fc-54595bcf5434","sourceKey":"bank:GST111:GST111-0042","parentItemId":null,"revision":1,"payload":{"prompt":"He ______ a prize for his diligence","options":["Took","Received","Made","Performed"],"correctOption":1,"section":"Vocabulary Development","explanation":"Received is correct because a prize is given to someone, so that person receives it. Took suggests he seized or helped himself to the prize, which does not fit being rewarded for diligence. Made and performed do not collocate with prize at all."}},{"itemId":"72efe3ba-bd35-59f0-8eaa-4b0345039d3c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3a057672-3b79-5a5d-8a05-850bab74e696","sourceKey":"bank:GST111:GST111-0043","parentItemId":null,"revision":1,"payload":{"prompt":"It is not wise to ______ family quarrels","options":["Interfere in","Interfere with","Interfere on","Interfere at"],"correctOption":0,"section":"Vocabulary Development","explanation":"We interfere in matters or affairs that are not our business, such as a family quarrel, so interfere in is correct. Interfere with is used when something disturbs, obstructs or tampers with something else, for example noise interfering with your reading. Interfere on and interfere at are not standard English."}},{"itemId":"4d534f33-4e73-5e17-8454-b5657929f634","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"822b3038-2c4f-5684-91c6-7cdcd2fc5ded","sourceKey":"bank:GST111:GST111-0044","parentItemId":null,"revision":1,"payload":{"prompt":"She did not ______ to go","options":["Accept","Agree","Allow","Admit"],"correctOption":1,"section":"Vocabulary Development","explanation":"To agree to do something means to say yes to a proposal or request, so agree is correct. Accept is the tempting choice, but it takes a noun object, as in accept an offer, so 'she did not accept to go' is non-standard. Allow would need an object (allow him to go), and admit to means to confess, so neither fits."}},{"itemId":"2f5008a0-2c27-5d7e-87e4-b54af9b11079","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"85b23ba8-225e-548c-911f-c0d51267c782","sourceKey":"bank:GST111:GST111-0045","parentItemId":null,"revision":1,"payload":{"prompt":"A butcher ______ meat","options":["Deals with","Deals in","Deals on","Deals at"],"correctOption":1,"section":"Vocabulary Development","explanation":"To deal in something means to buy and sell it as a trade, so a butcher deals in meat. Deals with means to handle or manage a problem or person, which gives the wrong meaning here. Deals on and deals at are not standard expressions."}},{"itemId":"f9c0c516-24b9-572d-a376-093e4c3eb877","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"46120d7d-7abd-5617-ad21-04360c293b03","sourceKey":"bank:GST111:GST111-0046","parentItemId":null,"revision":1,"payload":{"prompt":"How does that man ______ his living?","options":["Earn","Win","Achieve","Score"],"correctOption":0,"section":"Vocabulary Development","explanation":"We earn a living, meaning we work to get the money we need, so earn is correct. Win goes with prizes, games or competitions, so you cannot win your living. Achieve and score do not collocate with living either."}},{"itemId":"6ed352c8-e8c0-550c-9c2d-c5a4652a17d4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7b1c9cc2-3a73-5db7-82b6-bf53ce32b73a","sourceKey":"bank:GST111:GST111-0047","parentItemId":null,"revision":1,"payload":{"prompt":"Please ______ me to give the money back","options":["Remember","Remind","Recall","Memorise"],"correctOption":1,"section":"Vocabulary Development","explanation":"To remind someone is to make them remember something, which is exactly what the speaker wants, so remind is correct. Remember is something you do yourself, so 'please remember me to give the money back' is wrong. Recall and memorise also describe your own mental action and cannot take the pattern 'me to give'."}},{"itemId":"05128d6b-9b1e-5682-9afb-3b537f634397","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"33ad8912-9ba1-5575-890e-870e927a5738","sourceKey":"bank:GST111:GST111-0048","parentItemId":null,"revision":1,"payload":{"prompt":"The judge ______ the wrong done to the child","options":["Avenged","Revenged","Retaliated","Rebelled"],"correctOption":0,"section":"Vocabulary Development","explanation":"To avenge a wrong is to punish the wrongdoer on behalf of the victim, which is what a judge does in the name of justice, so avenged is correct. Revenged carries the idea of personal retaliation, as in revenging yourself on an enemy, so it does not fit a judge acting for a child. Retaliated and rebelled cannot take 'the wrong' as a direct object."}},{"itemId":"8a3c5801-fc01-5e6f-ac1c-222ea9c01884","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b80b9181-37a8-5f66-b692-d6b7825f6aae","sourceKey":"bank:GST111:GST111-0049","parentItemId":null,"revision":1,"payload":{"prompt":"Some people ________ freedom so much that they are ready to die for it","options":["Love","Like","Prefer","Fancy"],"correctOption":0,"section":"Vocabulary Development","explanation":"Love expresses a deep, intense feeling strong enough to make people willing to die for something, so it is correct. Like is far weaker, meaning only to find something pleasant, so it does not match the seriousness of being ready to die. Prefer and fancy are also too weak, and prefer needs a comparison."}},{"itemId":"af4c46e5-8623-5332-994f-5e6bab37f8b6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"015b24e5-7738-54aa-9155-3dc2a860017c","sourceKey":"bank:GST111:GST111-0050","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is a punctuation mark used in dialogue after a speakers name","options":["Full stop","Semi-colon","University","Colon"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In written dialogue, a colon follows the speaker's name to introduce the words spoken, as in Okon said: I am hungry, so D is correct. A full stop (A) would end the sentence before the speech begins, a semi-colon (B) joins related clauses, and option C, University, is not a punctuation mark at all."}},{"itemId":"fc7a93c1-76bb-5dac-a6d2-feea039e72e4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d28911f-76fc-5247-8947-a40779138adc","sourceKey":"bank:GST111:GST111-0052","parentItemId":null,"revision":1,"payload":{"prompt":"The ____ is used to mark off initials","options":["Semi-colon","Full stop","Bracket","Dash"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The full stop, option B, marks off initials and abbreviations, as in E. A. Adedun, Mr., Prof. or Ph.D. A semi-colon (A) joins clauses, a bracket (C) encloses extra material and a dash (D) sets off interrupting material, so none of them is used for initials."}},{"itemId":"ec0c309b-8f8c-5d6a-9944-174011ddb045","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"096f4418-eeb4-5dff-99ec-efecfd3557eb","sourceKey":"bank:GST111:GST111-0053","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following punctuation marks is used in pairs","options":["Question mark","Hyphen","Aprostrophe","Quotation"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Quotation marks, option D, always come in pairs: one to open the quoted words and one to close them, enclosing someone's exact words. A question mark (A), hyphen (B) and apostrophe (C) are each used singly, so they do not fit the description."}},{"itemId":"6b40ee61-b746-584b-bb45-e82612521493","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"23158dc5-44ef-5e1a-8c38-9b56105cd60a","sourceKey":"bank:GST111:GST111-0054","parentItemId":null,"revision":1,"payload":{"prompt":"Brackets are used to enclose","options":["A reference","Main ideas","Book titles","A & B"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Brackets enclose material that is additional to the main statement, and a typical example in academic writing is a reference, such as the author and year placed in brackets after a quotation, so A is correct. Main ideas (B) are never bracketed because they must stand out, and book titles (C) are shown in italics or underlined, which also makes D wrong."}},{"itemId":"a7585adf-cf69-51d4-95a2-d02d849827ae","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5f0719c1-4b92-5c21-a2a6-1396fb66d9ab","sourceKey":"bank:GST111:GST111-0055","parentItemId":null,"revision":1,"payload":{"prompt":"A full entry in a bibliography must show:","options":["Authors name & year of publication","Title of work & place of publication","Publisher","All of the above"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A full bibliography entry must identify the work completely, so it gives the author's name and year of publication, the title of the work, the place of publication and the publisher. Each of A, B and C is only part of a complete entry, so D, all of the above, is correct."}},{"itemId":"a1100b43-2065-57a7-9fb7-bb78e648752c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9d7ed97b-7123-5719-a1d1-56d96422efa9","sourceKey":"bank:GST111:GST111-0056","parentItemId":null,"revision":1,"payload":{"prompt":"Exclamation marks are used for","options":["Listings","Interjections","Confessions","Music"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, excitement or any strong feeling, and it punctuates interjections such as ouch, hey and oh, so B is correct. Listings (A) are introduced by a colon, and confessions (C) and music (D) have no special link to the exclamation mark."}},{"itemId":"a02f75de-530a-57b2-8110-01718ba8fe54","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ceab1b5b-44f1-51c2-8d6d-ca929be9d821","sourceKey":"bank:GST111:GST111-0057","parentItemId":null,"revision":1,"payload":{"prompt":"The arrangement of bibliography is","options":["Chronological","Idiosyncratic","Alphabetical","Whimsical"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"A bibliography is arranged alphabetically, option C, using the author's surname (or the title if there is no author), so readers can find any source quickly. Chronological order (A) is not the standard, and idiosyncratic (B) or whimsical (D) arrangements would make the list useless to readers."}},{"itemId":"48e008e2-c632-5b2b-8763-1488554502ba","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"69c7f757-cd31-5978-baa5-dff682a87b32","sourceKey":"bank:GST111:GST111-0058","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is used to introduce additional information","options":["Full stop","Apostrophe","Dash","Hyphen"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The dash, option C, introduces or sets off additional information that interrupts the main statement, as in All managers - I mean most managers - look forward to vacations. A full stop (A) ends a sentence, an apostrophe (B) shows possession or omission, and a hyphen (D) joins parts of words, so none of these introduces extra information."}},{"itemId":"8af1a477-e15e-5162-86cc-c28ae7ed47fc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f0fa55f1-acf5-5baf-9d7c-cf21f83f7fe1","sourceKey":"bank:GST111:GST111-0059","parentItemId":null,"revision":1,"payload":{"prompt":"Capitalization is necessary in all but one of the following","options":["Sentence initial position","Names of common nouns","Isolated 'I'","Names of deities and sacred contexts"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Capital letters are needed at the start of a sentence, for the pronoun I, and for proper nouns, including names of deities and sacred contexts. Common nouns (option B) such as table or city are written in lower case unless they begin a sentence, so B is the one case where capitalization is not necessary."}},{"itemId":"5d69f665-b0b9-56ac-9c5c-ce4159b06c33","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"73c739f0-aadb-5a66-996e-043bf86ccf96","sourceKey":"bank:GST111:GST111-0060","parentItemId":null,"revision":1,"payload":{"prompt":"The word here that can take the suffix, -NESS, by way of spelling is;","options":["Apt","Sadly","Comfort","Happily"],"correctOption":0,"section":"Vocabulary Development","explanation":"The suffix -ness turns adjectives into nouns, and apt is an adjective, so aptness, option A, is correct. Sadly (B) and happily (D) are adverbs, so they cannot take -ness in that form; the -ness words come from the adjectives sad and happy. Comfort (C) is already a noun, so comfortness is not a word."}},{"itemId":"293258b2-6c4f-5ea2-8e6b-8eedb28c8eca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b61764cf-f277-5cf5-814a-9c2752cd5493","sourceKey":"bank:GST111:GST111-0061","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is used to indicate possession in English?","options":["Inverted commas","Hyphen","Apostrophe","Quotation marks"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The apostrophe, option C, shows possession in English, as in Ade's salary or Moses' allowance. Inverted commas (A) and quotation marks (D) are the same thing and enclose quoted speech, while a hyphen (B) joins parts of compound words."}},{"itemId":"5dc70ec8-20d4-5908-a2fc-7ff9dab992e9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"407ff5f0-bb7c-5782-bdbb-8c9e294bc41e","sourceKey":"bank:GST111:GST111-0062","parentItemId":null,"revision":1,"payload":{"prompt":"'humble:","options":["Report","Regret","Standard","Return"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Humble is stressed on the first syllable (HUM-ble), and standard (STAN-dard), option C, has the same pattern. Report (re-PORT), regret (re-GRET) and return (re-TURN), options A, B and D, all carry their stress on the second syllable, so they do not match."}},{"itemId":"58ba7c12-e33b-5868-8629-b51a3d39a0ae","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"45728976-7e5e-57dd-bff1-7c94f2718c81","sourceKey":"bank:GST111:GST111-0063","parentItemId":null,"revision":1,"payload":{"prompt":"Com'plaint:","options":["success","saddle","punish","marvel"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Complaint is stressed on the second syllable (com-PLAINT), and success (suc-CESS), option A, has the same pattern. Saddle (SAD-dle), punish (PUN-ish) and marvel (MAR-vel), options B, C and D, are all stressed on the first syllable."}},{"itemId":"f46869ff-7b95-5060-a94e-4b8c014e2741","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3acfb8d1-4f66-59d4-8818-e00719c824eb","sourceKey":"bank:GST111:GST111-0067","parentItemId":null,"revision":1,"payload":{"prompt":"con'cern","options":["pretext","combine","concert","comment"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Concern is stressed on the second syllable (con-CERN), and the verb combine (com-BINE) has the same pattern, so B is correct. Pretext (PRE-text), concert (CON-cert) and comment (COM-ment) are all stressed on the first syllable. Concert may look tempting because it starts with con- like concern, but as a noun its stress falls on the first syllable."}},{"itemId":"2012b0b5-a9a3-5172-aab5-14275ed4e6eb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d40a820a-9967-554f-83e0-63899438bf14","sourceKey":"bank:GST111:GST111-0068","parentItemId":null,"revision":1,"payload":{"prompt":"pro'fessor","options":["creator","activist","company","minister"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Professor has its stress on the second syllable (pro-FES-sor), and creator (cre-A-tor) has the same pattern, so A is correct. Activist (AC-ti-vist), company (COM-pa-ny) and minister (MIN-is-ter) all take their stress on the first syllable, so they do not match."}},{"itemId":"9bc3e0cf-cf32-517f-a15e-89603dcfa06b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4caaebd3-59ab-5158-8198-373b80bbbeb5","sourceKey":"bank:GST111:GST111-0069","parentItemId":null,"revision":1,"payload":{"prompt":"indi'cation","options":["ambition","reaction","education","competitor"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Indication has four syllables with the main stress on the third (in-di-CA-tion), and education (ed-u-CA-tion) follows the same pattern, so C is correct. Words ending in -tion usually take their stress on the syllable just before the ending. Ambition (am-BI-tion) and reaction (re-AC-tion) have only three syllables, and competitor (com-PE-ti-tor) is stressed on the second syllable, so none of them matches."}},{"itemId":"0ca32043-1fc6-5b7a-a141-b5bd27b5edbc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"75e1d7a4-3f25-596b-b405-43d19a839bf2","sourceKey":"bank:GST111:GST111-0070","parentItemId":null,"revision":1,"payload":{"prompt":"'capitalism","options":["Occurrence","Insurance","Regionalism","Development"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Capitalism takes its main stress on the first syllable (CAP-i-tal-ism), and regionalism (RE-gion-al-ism) has the same pattern, so C is correct. The suffix -ism does not move the stress, so each word keeps the stress of its base (capital, region). Occurrence (oc-CUR-rence), insurance (in-SUR-ance) and development (de-VEL-op-ment) are all stressed on the second syllable."}},{"itemId":"c5f25096-207a-52c4-bc0d-1fcba4c48fcf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e7595bf7-1bff-55c1-b99a-3a354f3b7122","sourceKey":"bank:GST111:GST111-0076","parentItemId":null,"revision":1,"payload":{"prompt":"The course outline is usually provided by ____","options":["The department","Course representatives","Lecturers","All of the above"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"The course outline is prepared and handed out by the lecturer who will teach the course, option C, because the lecturer decides which topics will be covered and in what order. The department (A) approves the overall curriculum but does not give out an outline for each course, and course representatives (B) only pass on what the lecturer provides. Since A and B are not sources of the outline, D, all of the above, is also wrong."}},{"itemId":"82192ecf-1890-5ddb-9b6d-33f2a2dbd8c2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"eb5de8a1-78b0-5709-a636-5d367499df48","sourceKey":"bank:GST111:GST111-0078","parentItemId":null,"revision":1,"payload":{"prompt":"A basic reference tool every university student should personally own for effective study is ___","options":["A good dictionary","A well equipped library","A good encyclopedia","None of the above"],"correctOption":0,"section":"Vocabulary Development","explanation":"A good dictionary, option A, is the most basic tool a student needs, because it gives the meaning, spelling, pronunciation and usage of words needed in every course, and helps you grow your vocabulary. A well equipped library (B) and an encyclopedia (C) are valuable resources, but they are not the personal basic tool every student must own, so D is also wrong."}},{"itemId":"f35820fb-c96c-5681-aef2-35b4e3800a40","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4eceea78-1b7a-50c6-8932-ed76c32b739c","sourceKey":"bank:GST111:GST111-0079","parentItemId":null,"revision":1,"payload":{"prompt":"All except the following are included in the course outline of GST105: Use of English","options":["Use of the library","Grammar","Phonology","Epistemology"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"In this course, GST 105 (now GST 111) covers listening and speaking skills including the sounds of English (phonology), reading and writing skills, grammar, and the use of the library. So A, B and C are all in the outline. Epistemology (option D), the philosophical study of knowledge, is not part of a Use of English course, so it is the exception."}},{"itemId":"a9c3925a-4d88-5129-92ab-a9c6fb761600","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d351f6be-6bc4-5980-af3a-91f0f47a0bdb","sourceKey":"bank:GST111:GST111-0080","parentItemId":null,"revision":1,"payload":{"prompt":"The Dewey Decimal classification system assigns numbers in the following manner","options":["000 - 909","001 - 099","010 - 990","000 - 999"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The Dewey Decimal system divides all knowledge into ten main classes numbered from 000 to 999, so D is correct, with 000 for general works up to 900 for history and geography. Options A, B and C give ranges that stop short of the full three-digit span. Note that the UNILAG main library uses the Library of Congress scheme rather than Dewey."}},{"itemId":"0c6d8d36-e304-5319-8226-44205aac226f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"731c1a6e-8e54-5546-a961-22bb0fc7d830","sourceKey":"bank:GST111:GST111-0081","parentItemId":null,"revision":1,"payload":{"prompt":"In the library of congress classification system, law and languages take the following letters","options":["A and K","L and P","K and P","A and P"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"In the Library of Congress system, K stands for Law and P for Language and Linguistics, so law and languages take K and P, option C. Option B is wrong because L is the class for Education, not Law, and options A and D wrongly include A, which is the class for General Works."}},{"itemId":"f387e86b-b787-5984-b4de-219708f632ae","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cb81a185-9724-53f4-b4b9-e94d4c71bc6b","sourceKey":"bank:GST111:GST111-0082","parentItemId":null,"revision":1,"payload":{"prompt":"During the reading process the saccadic and regressive eye movements are","options":["Defective reading technique","Complementary reading technique","Retrogressive reading technique","Natural reading technique"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"When we read, our eyes move forward in little jumps and stops along the line (saccadic movement) and sometimes move back to words already read (regressive movement). Both are part of how the eyes naturally work in reading, so D, natural reading technique, is correct. They become a problem only when regression is excessive, so A and C are too negative, and B, complementary, is not the term used for these movements."}},{"itemId":"dc948ef5-1a71-595d-a71f-4253f5f344c1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1aba2a86-e6c5-5f57-832d-f47e6562dbfc","sourceKey":"bank:GST111:GST111-0083","parentItemId":null,"revision":1,"payload":{"prompt":"A very important part of a paragraph is","options":["The topic outline","The topic sentence","Sentence structure","Paragraph outline"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is the most important part of a paragraph because it states the main idea and works as a summary of the paragraph, so B is correct. A topic outline (A) and a paragraph outline (D) are planning tools rather than parts of the paragraph, and sentence structure (C) concerns individual sentences, not the idea that organizes the paragraph."}},{"itemId":"03cab751-887e-5ea8-b29e-744e76494de7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"09fe0a27-373a-5918-9594-e5cbd24f3d7d","sourceKey":"bank:GST111:GST111-0084","parentItemId":null,"revision":1,"payload":{"prompt":"_____ forms the building block of a sentence","options":["Sounds","Letters","Thoughts","Words"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Words, option D, are the building blocks of a sentence: they combine to form phrases and clauses, which in turn form sentences. Sounds (A) and letters (B) are the building blocks of words, not sentences, and thoughts (C) are what a sentence expresses rather than what it is made of."}},{"itemId":"48ed5fa2-2fce-594a-8c33-dd80b21a205b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cd3bd65e-60ee-53f9-ab6a-906af504e0b7","sourceKey":"bank:GST111:GST111-0085","parentItemId":null,"revision":1,"payload":{"prompt":"The punctuation mark used for interrogative sentence is ____","options":["Exclamation","Period","Question mark","Colon"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An interrogative sentence asks a question, and a direct question ends with a question mark, so C is correct. The exclamation mark (A) marks strong feeling, the period or full stop (B) ends a statement or command, and the colon (D) introduces a list or quotation."}},{"itemId":"8ae6b65b-3c83-5d2e-a226-39b08f5b5f4c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7d911c0d-2404-5a4a-9568-b23c994a0bcf","sourceKey":"bank:GST111:GST111-0086","parentItemId":null,"revision":1,"payload":{"prompt":"Another name for the period is ___","options":["Semi-colon","Hyphen","Full-stop","Exclamation"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Period is simply the American name for the full stop, so C is correct; it ends declarative and imperative sentences. The semi-colon (A), hyphen (B) and exclamation mark (D) are different marks with different uses, so they are not other names for the period."}},{"itemId":"2ae39dbb-982c-5980-8d16-1c1fddd4df5c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"de61d780-b65a-5079-a936-c4787c9d36a3","sourceKey":"bank:GST111:GST111-0087","parentItemId":null,"revision":1,"payload":{"prompt":"Brainstorming is one of the fundamentals of ____","options":["Writing a good essay","Passing an examination","Writing a good sentence","Paragraph improvement"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Brainstorming means freely generating and jotting down ideas on a topic before organizing them, and it is a fundamental first step in writing a good essay, so A is correct. It belongs to the planning stage, when the writer gathers material and decides on a central idea. It is not a way of passing examinations in general (B), and it works on ideas for a whole piece rather than a single sentence (C) or improving an already written paragraph (D)."}},{"itemId":"f9890843-1cbb-5220-9c30-502c0ec68da3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9f823642-a4f0-5aff-8959-5c659775cc4d","sourceKey":"bank:GST111:GST111-0088","parentItemId":null,"revision":1,"payload":{"prompt":"To ensure that the different paragraphs of an essay are properly related, you must use","options":["Lexical equivalence","Introductory remarks","Linking expressions","Descriptive expressions"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"To make the paragraphs of an essay flow into one another, you use linking expressions, option C, such as first, second, finally, furthermore, in addition and however. They show continuity with the idea already expressed. Lexical equivalence (A) and descriptive expressions (D) are not connecting devices, and introductory remarks (B) only open the essay rather than tie paragraphs together."}},{"itemId":"e7a153b0-ff48-5c67-a649-ffd9513d2af0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"081e2d8d-f2a0-5f23-b27b-8bdc3a4759f6","sourceKey":"bank:GST111:GST111-0089","parentItemId":null,"revision":1,"payload":{"prompt":"To mark off two or more independent clauses in a sentence, you should use a ___","options":["Paired commas","Semi-colon","Emphasis","Parenthesis"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A semi-colon, option B, marks off two or more independent clauses in one sentence, replacing a comma plus a coordinating conjunction, as in Supply us with three cars; they must all be black. Paired commas (A) and parentheses (D) enclose extra material inside a sentence rather than separating clauses, and emphasis (C) is not a punctuation mark."}},{"itemId":"249e1ab0-dee4-5878-bd6e-284ec277277f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"750b67b7-c43b-58cc-8ffb-7d9780b57b86","sourceKey":"bank:GST111:GST111-0090","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a common essay type","options":["Descriptive","Narrative","Expository and argumentative","Proposal"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Essays are commonly classed as narrative, expository (analytical), argumentative (persuasive) or descriptive, so A, B and C are all common essay types. A proposal (option D) is a business or research document that puts forward a plan, not a type of essay, so it is the answer to this 'is not' question."}},{"itemId":"7ec937d3-ba57-5dc4-a4e1-423ecf0f9f76","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0d26515b-0aae-5fc1-8e86-edcf5fdd1676","sourceKey":"bank:GST111:GST111-0091","parentItemId":null,"revision":1,"payload":{"prompt":"A faithful account of an activity in which the writer participated can be labeled","options":["Report","Memo","Prolegomena","Episode"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A faithful, factual account of an activity in which the writer took part is a report, option A, because a report records what actually happened for others to read and act on. A memo (B) is a short internal message, prolegomena (C) means a preliminary introduction to a book, and an episode (D) is a single event in a story rather than an account of one."}},{"itemId":"7834439c-b38f-5632-b13b-693b6cc63a29","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"11a616cb-b755-5176-abb7-7393de2e9eb6","sourceKey":"bank:GST111:GST111-0092","parentItemId":null,"revision":1,"payload":{"prompt":"A high degree of objectivity is normally expected in","options":["Scientific writing","Informal writing","Formal writing","Doctor-patient writing"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Scientific writing, option A, demands the highest degree of objectivity because it reports observations, data and results that must be verifiable whatever the writer feels. Informal writing (B) is personal by nature, and formal writing (C) is a broad category that includes opinion pieces, so formality alone does not guarantee objectivity. Doctor-patient writing (D) is not a recognized category of writing."}},{"itemId":"73ccd220-1158-5a5f-9f55-a42ebf70e736","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"33a4bb48-4703-573a-983b-d09a77182bf3","sourceKey":"bank:GST111:GST111-0093","parentItemId":null,"revision":1,"payload":{"prompt":"Technical writing may not include","options":["Car manual","Love poems","Police reports","Law reports"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Technical writing deals with factual, practical or specialized information in fields such as engineering, law and public administration, so a car manual (A), police reports (C) and law reports (D) are all technical documents. Love poems (option B) are imaginative and emotional, the opposite of technical writing, so B is what technical writing may not include."}},{"itemId":"ed9dc9ea-e500-5089-a848-77e83d8f3e63","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2ce63c16-f7d4-5cdc-a47c-4a1136609090","sourceKey":"bank:GST111:GST111-0094","parentItemId":null,"revision":1,"payload":{"prompt":"Poetic meaning of an expression is usually","options":["Expressive","Denotative","Figurative","Discursive"],"correctOption":2,"section":"Vocabulary Development","explanation":"Poetic meaning is usually figurative, option C, because poets use words beyond their literal dictionary sense to suggest images, feelings and associations. Denotative meaning (B) is the literal meaning, which is the opposite of what poetry relies on, and expressive (A) and discursive (D) are not the standard terms for this kind of meaning."}},{"itemId":"345dcab4-7620-5a24-b695-2be1707f7a8a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d42f30c0-a64e-50fd-976d-350268d126cd","sourceKey":"bank:GST111:GST111-0095","parentItemId":null,"revision":1,"payload":{"prompt":"Denotative words are","options":["Words which refer to the past","Listing words in alphabetical order","Words used scientifically","Words which make direct reference"],"correctOption":3,"section":"Vocabulary Development","explanation":"Denotative words make direct, literal reference to things, so D is correct. Denotative meaning is the literal meaning of a word, the one entered in the dictionary; for example, dark denotes the absence of light. Options A, B and C have nothing to do with denotation: referring to the past, alphabetical listing and scientific use are unrelated ideas."}},{"itemId":"3ee3181f-b614-53d7-8748-f3a11a924ca5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4c98c328-eeb6-5ea7-9fa2-5baa55aeb7b2","sourceKey":"bank:GST111:GST111-0096","parentItemId":null,"revision":1,"payload":{"prompt":"The bibliography is usually located at ___ part of a research work","options":["The beginning","The middle","The end","The preliminary"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"The bibliography, or reference list, is placed at the end of a research work, option C, so readers can follow the brief in-text citations to the full details of each source. The beginning (A) and preliminary pages (D) hold items like the title page and abstract, and nothing like a bibliography goes in the middle (B)."}},{"itemId":"e708e40e-f092-5256-bb7b-1d08cf840fee","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"99994e45-2f07-5483-a60f-3f60db8c978f","sourceKey":"bank:GST111:GST111-0097","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not one of the main divisions of the writing process","options":["Writing stage","Proof-reading stage","Publishing stage","Pre-writing stage"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The writing process is usually divided into a pre-writing stage (planning and gathering ideas), a writing stage (drafting) and a proof-reading stage (checking and correcting), so A, B and D are genuine divisions. Publishing (option C) is what may happen to a finished piece afterwards, not a stage of writing it, so C is the one that does not belong."}},{"itemId":"41feabc7-d9ba-5df4-93ec-bd29eafb1be9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6169b1c1-5372-55b6-9cc2-ecf624ac4f20","sourceKey":"bank:GST111:GST111-0098","parentItemId":null,"revision":1,"payload":{"prompt":"In technical writing, the acronym SME means","options":["Some subject example","Some managerial expertise","Subject matter expert","Simple marketing expert"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In technical writing, SME stands for Subject Matter Expert, option C: the specialist whose knowledge the writer draws on to make sure the content is accurate. Options A, B and D are made-up expansions that do not correspond to any recognized term in technical communication."}},{"itemId":"f7bc8bc7-cf28-56d5-a770-ed8c23f60410","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"46579df3-6660-5025-946d-689a459bd5f7","sourceKey":"bank:GST111:GST111-0099","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following would you write under subscription in a letter","options":["Addressee designation","Yours faithfully","Salutation","Body of the letter"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The subscription of a letter is the closing formula written just before the signature, such as Yours faithfully or Yours sincerely, so B is correct. The addressee's designation (A) belongs in the inside address at the top, the salutation (C) is the opening greeting such as Dear Sir, and the body (D) is the main message of the letter."}},{"itemId":"770e0eda-7545-5ce2-8fd1-5a31139d8d67","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7938c3e3-2511-5d38-88fa-e2da24345af8","sourceKey":"bank:GST111:GST111-0100","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following will provide information to influence our decisions and actions","options":["Reports","Memorandum","Agenda","Anecdotes"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Reports, option A, are written to supply the information decision makers need in order to decide and act, for example a committee report recommending a course of action. A memorandum (B) mainly passes on brief internal messages, an agenda (C) only lists the items for a meeting, and anecdotes (D) are short entertaining stories, not a reliable basis for decisions."}},{"itemId":"ead71c1a-f158-5031-9c7d-e41f495b2414","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0a74fbdc-0e40-5625-9ce7-b30182ecb091","sourceKey":"bank:GST111:GST111-0101","parentItemId":null,"revision":1,"payload":{"prompt":"One of the attributes of information is .................","options":["Citation","Printing","Relevance","Non-reliability"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Relevance, option C, is one of the attributes of good information, alongside availability, accuracy, reliability and timeliness. Citation (A) and printing (B) are things done with information, not qualities of it, and non-reliability (D) is the opposite of reliability, which is a required attribute."}},{"itemId":"83fc43c6-3614-5af6-90b1-c422d7bc250a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c7807703-04fa-5207-9c67-743778409035","sourceKey":"bank:GST111:GST111-0102","parentItemId":null,"revision":1,"payload":{"prompt":"The goal of an argumentative essay is to ..............","options":["persuade the audience","convince the readers","sell an idea","all of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An argumentative or persuasive essay tries to get readers to accept a point of view: it sells an idea, convinces readers and persuades the audience. Since all three of the listed goals are correct, all of the above is the right answer. Choosing just one of them would give only part of what an argumentative essay sets out to do."}},{"itemId":"1688edaf-6b0a-55ff-8e56-eb7cbe72e37c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"59cbca13-7137-5afd-beba-4399c65baf10","sourceKey":"bank:GST111:GST111-0103","parentItemId":null,"revision":1,"payload":{"prompt":"Meta Search involves use of ........................","options":["meta search engines","primary search engines","advanced search engines","basic search engines"],"correctOption":0,"section":"Search Strategies","explanation":"A meta search uses meta search engines, option A, such as Dogpile, Metacrawler, Search.com and Vivisimo, which send your query to several ordinary search engines at once and gather the results together. Options B, C and D (primary, advanced or basic search engines) describe single search engines or search modes, not the tool that performs a meta search."}},{"itemId":"53ac0030-b5dc-5667-861f-daa7639a187c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ff5e8272-f5b5-5492-8f54-6e3077df23fc","sourceKey":"bank:GST111:GST111-0104","parentItemId":null,"revision":1,"payload":{"prompt":"An example of a specialized dictionary is ..........","options":["Webster english dictionary","Oxford English dictionary","Dictionary of American slang","None"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The Dictionary of American Slang, option C, is a specialized dictionary because it is compiled for a particular purpose and covers only one area of vocabulary. Other specialized examples include the Dictionary of the Yoruba Language and the Dictionary of Modern Politics. Webster's (A) and the Oxford English Dictionary (B) are general dictionaries, so D, none, is also wrong."}},{"itemId":"2202ac07-f0d7-5e8d-bb1d-f5ee563b9e3c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f188a23c-c5bc-5bb6-8f34-a8e5d1540f87","sourceKey":"bank:GST111:GST111-0105","parentItemId":null,"revision":1,"payload":{"prompt":"Affixes which cause stress to move from one syllable to another are known as -------- --------------- affixes.","options":["stress-conserving","stress-neutral","stress-moving","stress-bearing"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Affixes that shift the stress to a different syllable of the stem are called stress-moving affixes, option C, for example -ic and -ity, as in MAGnet becoming magNETic and INfidel becoming infiDELity. Stress-neutral affixes (B) leave the original stress unchanged, like un- in unPLEASant, and stress-bearing affixes (D) carry the stress themselves, like -eer in engiNEER. Stress-conserving (A) is not a standard term."}},{"itemId":"8adc45bf-8e25-5ce7-a326-4c3646462cd8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2648f367-4270-5b0a-a57d-d517655e620c","sourceKey":"bank:GST111:GST111-0106","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the misspelled word below","options":["sphinx","embarrassment","repertoire","harrassment"],"correctOption":3,"section":"Vocabulary Development","explanation":"The misspelled word is harrassment, option D; the correct spelling is harassment, with one r and two s's. Sphinx (A), embarrassment (B) and repertoire (C) are all spelt correctly. Embarrassment is the one with double r and double s, which is probably why people wrongly add an extra r to harassment."}},{"itemId":"913dacab-dbc7-5d44-9b05-8056a3e1f4d8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"03849063-4925-5e91-9a98-6fd837aff193","sourceKey":"bank:GST111:GST111-0107","parentItemId":null,"revision":1,"payload":{"prompt":"The .............. sentence is the most important sentence in a paragraph.","options":["topic","last","concluding","first"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is the most important sentence in a paragraph because it states the main idea and acts as a summary of the paragraph, so A is correct. First (D) and last (B) describe positions rather than functions, and the topic sentence can appear in different places. A concluding sentence (C) is optional, so it cannot be the most important."}},{"itemId":"4f28c3f0-75fb-5122-aa66-adc5f26f0e0b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1644106e-5445-5cae-a323-fefb526924fa","sourceKey":"bank:GST111:GST111-0108","parentItemId":null,"revision":1,"payload":{"prompt":"Prepositions begin phrases that end with","options":["adjective or pronoun","either a noun or pronoun","conjunction or adjunct","verb or adverb"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Prepositions begin phrases that end with either a noun or a pronoun, called the object of the preposition, as in under the table or at the bus-stop. So B is correct. Options A, C and D name word classes that do not serve as the object of a preposition."}},{"itemId":"c8722c25-47ab-5341-a10e-1b88836d85ac","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7fa4bef9-ab5c-595f-85b0-e5019d38bed8","sourceKey":"bank:GST111:GST111-0109","parentItemId":null,"revision":1,"payload":{"prompt":"A dictionary aids vocabulary development by .....","options":["All of these","Suggesting meanings of words","Indicating the ways the words are pronounced","Indicating the context of usage and spelling"],"correctOption":0,"section":"Vocabulary Development","explanation":"A dictionary helps vocabulary grow by giving the meanings of words, showing how they are pronounced, and indicating their spelling and the contexts in which they are used. Since B, C and D are each true, A, all of these, is the correct choice; picking only one of them leaves out the others."}},{"itemId":"b8658fcb-c5ae-5bae-8dfa-6f7473445d7e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3027972c-ff52-508f-90f9-0502c3338c88","sourceKey":"bank:GST111:GST111-0110","parentItemId":null,"revision":1,"payload":{"prompt":"\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_is used to introduce a list","options":["colon","full stop","semi colon","comma"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The colon, option A, introduces a list, especially after words like the following or namely, as in Please purchase the following items: a suitcase, a pair of shoes and a bottle of perfume. A full stop (B) ends a sentence, a semi-colon (C) joins related clauses or separates items that already contain commas, and a comma (D) separates the items within the list rather than introducing it."}},{"itemId":"c14de02c-d812-5761-bbb6-4cd24f1ea577","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0c14f326-4bc4-53cd-bae1-c0ded7911ed6","sourceKey":"bank:GST111:GST111-0111","parentItemId":null,"revision":1,"payload":{"prompt":"Words can be in any of the following forms except:","options":["simple","complex","compound-complex","compound"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"A word can be simple (one unit, like table), compound (two words that can stand alone, like suitcase) or complex (a base with affixes, like unreliable). Compound-complex (option C) is not a word form; it is a type of sentence with two or more main clauses plus a subordinate clause. So C is the form a word cannot take."}},{"itemId":"c09eb97e-a051-593a-95dc-f011a2fd8971","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b1ec2421-7056-55d0-be6e-a4fb1544d127","sourceKey":"bank:GST111:GST111-0112","parentItemId":null,"revision":1,"payload":{"prompt":"Meaning in words is largely a matter of ........","options":["Agreement","discord","standardised opinion","Inherence"],"correctOption":0,"section":"Vocabulary Development","explanation":"Meaning in words is largely a matter of agreement, option A, because the link between a word and what it stands for is a convention shared by speakers of a language, not something natural in the word itself. English accepts new words like vuvuzela once speakers agree to use them. Discord (B) is the opposite of shared meaning, and inherence (D) wrongly suggests meaning is built into the word. Standardised opinion (C) is not the term used."}},{"itemId":"7fd0b58c-dacb-5864-8948-f3503705cad6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fe913b07-8ece-54f0-a617-3e681d9aedd7","sourceKey":"bank:GST111:GST111-0113","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a minor sentence","options":["Gatekeeper wanted.","No fuel.","No vacancy","God bless you"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Minor sentences are meaningful but grammatically incomplete structures whose missing parts can be recovered from context, such as Gatekeeper wanted, No fuel and No vacancy (options A, B and C). God bless you, option D, has a subject (God) and a finite verb (bless), so it is a complete major sentence, which makes it the one that is not a minor sentence."}},{"itemId":"443a391f-2bd1-5db1-88f8-e03dc485ddbf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cd3362b5-7f68-5462-ab35-d0c76f69e176","sourceKey":"bank:GST111:GST111-0114","parentItemId":null,"revision":1,"payload":{"prompt":"The element which makes a paragraph easily understandable to the reader is ..............","options":["unity","completeness","development","coherence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Coherence, option D, is the quality that makes a paragraph easy for the reader to follow, achieved through logical and verbal bridges such as repeated key words, pronouns and transition words. Unity (A) means the paragraph keeps to a single focus, and development (C) means the topic is fully discussed. Completeness (B) is not one of the named elements of a paragraph."}},{"itemId":"1705a03e-f47c-5918-adb2-c234701a13cc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1d073446-6f06-58c6-819d-e8b5e773b1f5","sourceKey":"bank:GST111:GST111-0115","parentItemId":null,"revision":1,"payload":{"prompt":"A secondary source is one that ............. and ................ a primary source.","options":["Critiques and disqualify","Reviews and manipulates","All","Analyzes & explains"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"A secondary source analyzes, critiques, reviews or explains a primary source, and is written by scholars who have studied the original and drawn their own conclusions. So D, analyzes and explains, matches the definition. Options A and B use words like disqualify and manipulates that are not part of the definition, so C, all, is also wrong."}},{"itemId":"af390b49-ae7b-5deb-92fe-4882ae2646a8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7eff6e9c-369b-54e9-b81a-168fcdee7a3f","sourceKey":"bank:GST111:GST111-0116","parentItemId":null,"revision":1,"payload":{"prompt":"An --------- summarizes the accurate content and presentation of a document","options":["Abstract","Electronic source","Index","Advance search"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"An abstract, option A, is a brief summary of the contents of a book, article, thesis or conference paper that tells the user what the document contains without reading it from beginning to end. An index (C) only points to where information can be found, an electronic source (B) is a format rather than a summary, and advanced search (D) is a searching technique."}},{"itemId":"214490ba-ef62-5144-8039-ba0010982dfb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"70227acd-96b7-5ae6-b44f-41af5496b684","sourceKey":"bank:GST111:GST111-0117","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a type of essay:","options":["experimental","narrative","analytical","descriptive"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Essays are classed by content and purpose into narrative, analytical, persuasive and descriptive types, so narrative (B), analytical (C) and descriptive (D) are all genuine essay types. Experimental, option A, describes a method of scientific inquiry, not a type of essay, so it is the answer to this 'not' question."}},{"itemId":"faf5ae31-d3e2-537b-871a-0efdbafb18af","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3ae16b18-24ae-5862-b9aa-73e3d172429b","sourceKey":"bank:GST111:GST111-0118","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT true about writing a summary?","options":["expressions are paraphrased with new words","the major facts are included","quotations from the text are included","the present tense is used"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"A good summary paraphrases the original in new words, presents the major facts and uses the present tense, so A, B and D are all true. Including quotations from the text (option C) goes against the rule of restating ideas in your own words, so C is the statement that is not true."}},{"itemId":"3ba3da49-9e31-5ff9-b504-27e6acd79974","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8d25f3ba-8d08-5480-a9f0-c0857c8bc84c","sourceKey":"bank:GST111:GST111-0120","parentItemId":null,"revision":1,"payload":{"prompt":"Interjections are usually punctuated with a/an ____________.","options":["question mark","comma","exclamation mark","period"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Interjections express strong or sudden feeling and are usually punctuated with an exclamation mark, as in Ouch! That was painful and Hey! Watch out! So C is correct. A question mark (A) is for direct questions, a period (D) ends ordinary statements, and a comma (B) is used only after mild interjections, which is not the usual punctuation."}},{"itemId":"f4628aca-24a6-5da8-af92-a8d7cab1c9ae","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"560410ed-e533-56dc-9cf1-00314448f391","sourceKey":"bank:GST111:GST111-0121","parentItemId":null,"revision":1,"payload":{"prompt":"Mixed notation refers to the use of letters of the alphabet as well as .............","options":["Arabic alphabets","Roman numerals","Arabic numerals","Greek symbols"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Mixed notation means combining letters of the alphabet with Arabic numerals (0 to 9), as the Library of Congress classification does, which is why it is called alpha-numeric. So C is correct. Roman numerals (B) and Greek symbols (D) are not used in this scheme, and Arabic alphabets (A) is a confusion, since the scheme uses the ordinary letters A to Z."}},{"itemId":"4613a692-19e4-5547-b0d2-617c4c8778f0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"990a83f3-c30b-53ce-837b-1398e984be4c","sourceKey":"bank:GST111:GST111-0122","parentItemId":null,"revision":1,"payload":{"prompt":"Radio, Tape-recorder, Gramophone and Audio cassette player are examples of ............","options":["Visual materials","Audio materials","Audio-visual materials","Electronic material"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Radio, tape-recorder, gramophone and audio cassette player all deliver information through sound alone, so they are audio materials, option B; in the University of Lagos library they are found in the Music Library. Visual materials (A), such as maps and pictures, appeal to the eye only, audio-visual materials (C) like television and LCD projectors combine sound and picture, and electronic material (D) is too broad a label for this group."}},{"itemId":"bb0e8ba9-65de-582d-ab2e-044c172c1ef8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3d474ebf-d6e9-519e-8a23-2d3bc0e71351","sourceKey":"bank:GST111:GST111-0123","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is correct?","options":["the responsibility is their's","the reward is your's","the dog wagged it's tail","the dog wagged its tail"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Possessive pronouns never take an apostrophe, so the correct forms are theirs, yours and its. Option D, the dog wagged its tail, follows this rule. Options A and B wrongly add apostrophes to possessive pronouns, and option C uses it's, which is a contraction of it is, not the possessive."}},{"itemId":"b58f305c-95f2-5529-b861-139e278edfed","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"16acf818-7b42-539a-a99b-65643cc40855","sourceKey":"bank:GST111:GST111-0124","parentItemId":null,"revision":1,"payload":{"prompt":"The main purpose of reading is to \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ a written material.","options":["Practice","Comprehend","Identify","Buy"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The main purpose of reading is to comprehend written material, so B is correct. The eyes link letters and symbols to see what the author says, while the brain interprets what the author means, and the goal of study reading is understanding and retaining the material. Practising (A), identifying (C) and buying (D) are not what reading itself is for."}},{"itemId":"f2c30f83-9b29-5cce-be7c-7d5b4ef9137a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a09a5057-7d3a-55bc-8362-500bab498844","sourceKey":"bank:GST111:GST111-0125","parentItemId":null,"revision":1,"payload":{"prompt":"Article/journal search can be carried out or done in these sections of the library","options":["Serials and E-library","Cataloguing Section","Acquisition section","University Librarian's office"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Journal and article searches are done in the Serials section, which holds publications issued in successive parts such as journals, newspapers and magazines, and in the E-library, where electronic journals and databases are accessed. So A is correct. The Cataloguing section (B) and Acquisition section (C) are back-office units that process materials, and the University Librarian's office (D) is administrative."}},{"itemId":"a27c5ca8-0e2a-5cc2-871d-d4988e6f2bb2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b2b92adb-db52-56d4-9918-5a1a56e449f6","sourceKey":"bank:GST111:GST111-0126","parentItemId":null,"revision":1,"payload":{"prompt":"Phonetics is to pronunciation what ---------------- is to spelling.","options":["syntax","semantics","interpretation","orthography"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Phonetics is the systematic study of how words are pronounced, and orthography, option D, is the conventional system of spelling words in a language, so the two are parallel. Syntax (A) deals with sentence structure and semantics (B) with meaning, while interpretation (C) is not a branch of language study, so none of them relates to spelling."}},{"itemId":"99b77ebf-e835-5646-98a1-aa2017e89529","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"50f69090-c534-5885-a426-fb2f8e808831","sourceKey":"bank:GST111:GST111-0127","parentItemId":null,"revision":1,"payload":{"prompt":"All of the following sources can be cited in a reference list EXCEPT.........","options":["Chapter or article in edited book","Web page","Books","None of the above"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Books, chapters or articles in edited books, and web pages can all be cited in a reference list, so every source in A, B and C is allowed. Since none of them is excluded, D, none of the above, is correct. Choosing A, B or C would wrongly suggest that a legitimate source type cannot be referenced."}},{"itemId":"d8d6ec46-af74-5021-863a-b807ad655d35","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ffafb7da-c902-5b77-b346-40fa8af0f222","sourceKey":"bank:GST111:GST111-0128","parentItemId":null,"revision":1,"payload":{"prompt":"Letter T is assigned to books on .......... in the Library of Congress Classification Scheme","options":["Arts","Technology","Science","Medicine"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"In the Library of Congress scheme, the letter T is assigned to Technology, option B. Arts come under N (Fine Art), Science under Q and Medicine under R, so options A, C and D are wrong."}},{"itemId":"1207574a-45f8-5240-a5da-283ace7280fa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"940377e5-fec0-5ed3-b841-c40d2c40b6b9","sourceKey":"bank:GST111:GST111-0129","parentItemId":null,"revision":1,"payload":{"prompt":"Index may be published as part of a book or separately","options":["Partially false","Partially true","False","True"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"The statement is true, option D: an index may be published as part of a book, like the index at the back of that book, or separately, like a periodical index that stands alone. Options A, B and C treat the statement as wholly or partly false, but both forms of publication really exist, with no qualification needed."}},{"itemId":"10ffe782-b845-5d17-9c15-d447cf246a28","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0bc4800f-c736-5e2a-8fbc-3fa483cbc342","sourceKey":"bank:GST111:GST111-0130","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the incorrectly spellled word below","options":["chauffeur","souvenier","vagrant","resinous"],"correctOption":1,"section":"Vocabulary Development","explanation":"The misspelled word is souvenier, option B; the correct spelling is souvenir, ending in -ir, not -ier. It is one of the words English borrowed from French. Chauffeur (A), vagrant (C) and resinous (D) are all spelt correctly."}},{"itemId":"8538d825-54f7-590d-932a-4e0beccab52a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e792f86e-1943-57cc-a56a-de49ca3c6cc8","sourceKey":"bank:GST111:GST111-0131","parentItemId":null,"revision":1,"payload":{"prompt":"In-text citation appears in the body of the manuscript.","options":["False","Partially true","True","Partially false"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"The statement is true, option C. Referencing has two parts: the in-text citation, which appears in the body of the manuscript right where another writer's idea or words are used, and the reference list at the end of the work. Options A, B and D wrongly suggest the in-text citation sits somewhere other than the manuscript."}},{"itemId":"4da0dcab-12ea-5da8-9198-9735d58e1cc3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"df0e64e8-4615-5815-86f2-0057a99e739c","sourceKey":"bank:GST111:GST111-0132","parentItemId":null,"revision":1,"payload":{"prompt":"The \"period\" is also written as \\_\\_\\_\\_\\_\\_\\_\\_\\_ in punctuation","options":["colon","quotation mark","full stop","comma"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The mark used at the end of a complete declarative or imperative sentence is called the full stop or period; the two names refer to the same symbol, so C is correct. A colon (A) introduces lists, quotation marks (B) enclose direct speech, and a comma (D) separates items within a sentence, so none of them is another name for the period."}},{"itemId":"5ba7744e-988b-58b5-bdb9-097bf0ff6a28","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ef6dcb37-db8a-5e9f-abae-062dc52c667f","sourceKey":"bank:GST111:GST111-0133","parentItemId":null,"revision":1,"payload":{"prompt":"A simple sentence has","options":["two clauses and no finite verb","one clause and contains only one finite verb","two clauses and contains only one finite verb","one clause and contains only two finite verb"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence makes a single statement, has only one clause and contains only one finite verb, as in The boy killed the snake, so B is correct. Options A and C describe two clauses, which would make the sentence compound, and D gives two finite verbs, which also means more than one clause."}},{"itemId":"dd1384ac-82dc-531c-a522-b912db4a8b3b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8ff6ac46-5139-589a-86fa-2f36f5f41af4","sourceKey":"bank:GST111:GST111-0134","parentItemId":null,"revision":1,"payload":{"prompt":"Arrangement in the library catalogue is in \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ order","options":["Chronological","Triangular","Alphabetical","Decimal"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"A library catalogue is arranged by author, title and subject, and its entries are filed in alphabetical order so users can look up a name or heading quickly, which is option C. Chronological order (A) would arrange by date, which is not how catalogues work. Triangular (B) is not an arrangement at all, and decimal (D) refers to a classification scheme for shelving, not the catalogue."}},{"itemId":"560875e9-b67b-57e9-ac13-41152c442a5a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"61e65902-d48a-5914-b9c2-99d32ee5cbd5","sourceKey":"bank:GST111:GST111-0135","parentItemId":null,"revision":1,"payload":{"prompt":"A .............. essay gives a detailed and often dispassionate account of people, incidents, scenes and situations in a vivid manner.","options":["narrative","analytical","persuasive","descriptive"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A descriptive essay gives a detailed and often dispassionate account of people, incidents, scenes and situations so the reader can picture them as if present, so D is correct. A narrative essay (A) tells events in sequence, an analytical essay (B) explains or evaluates, and a persuasive essay (C) argues for a point of view."}},{"itemId":"015178fc-c691-54da-8346-2723b3424ad1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"70bf6cce-3d96-5c1d-bdbe-a18bc07d8511","sourceKey":"bank:GST111:GST111-0136","parentItemId":null,"revision":1,"payload":{"prompt":"The symbol ':' used alongside a phonetic symbol suggests ----------------","options":["labialisation","colony","length","aspiration"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"A colon-like mark written after a vowel symbol is a length mark showing that the vowel is long, as in the contrast between /i:/ in seat and /I/ in sit, so C is correct. It changes only the length, not the quality of the sound. Aspiration (D) and labialisation (A) are different features of consonants, and colony (B) is not a phonetic term at all."}},{"itemId":"d1ab9bf3-1fb7-5ceb-bd9c-efac7c336580","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f98ae421-477d-5957-b5c6-a5a1f8dc4388","sourceKey":"bank:GST111:GST111-0137","parentItemId":null,"revision":1,"payload":{"prompt":"Information can be evaluated using the following criteria EXCEPT","options":["Accuracy","Relevancy","Size","Currency"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Information is evaluated using criteria such as currency, relevancy, authority, accuracy and purpose. Size (option C) is not one of them, since a long book or article is not more credible just because it is bigger. Accuracy (A), relevancy (B) and currency (D) are all genuine evaluation criteria."}},{"itemId":"c9abd2a6-518c-51b5-a7f3-a5dd2e334b05","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5a33e432-46fd-5612-9c4c-4fbe32335b9a","sourceKey":"bank:GST111:GST111-0138","parentItemId":null,"revision":1,"payload":{"prompt":"Another name for Adjective Clause is","options":["preemptive clause","restrictive clause","blackball clause","relative clause"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"A subordinate clause that modifies a noun the way an adjective does is called an adjectival clause or relative clause, because it is usually introduced by a relative pronoun such as who, whom, whose, which or that. So D is correct. A restrictive clause (B) is only one sub-type of relative clause, the defining kind, not another name for all adjective clauses, and A and C are not grammatical terms."}},{"itemId":"5c9c2d34-274e-5d8b-82b0-a67a9f74f9fe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"95be0a4f-0bcf-5a9c-a5c1-d6d6601d9eff","sourceKey":"bank:GST111:GST111-0139","parentItemId":null,"revision":1,"payload":{"prompt":"A maximum of --------------- consonants are permissible at the beginning of an English syllable.","options":["3","4","5","6"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The structure of the English syllable is C0-3 V C0-4, so the onset (the consonants before the vowel) can hold up to three consonants, as in spree, straw and sprint. That makes A, 3, correct. Options B, C and D (4, 5, 6) exceed the limit; four consonants are possible only at the end of a syllable, as in strengths."}},{"itemId":"e4527f61-5066-500f-b0f7-b780c861d8ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4e0541f8-bd21-51f5-aa9d-5f87ca78c74d","sourceKey":"bank:GST111:GST111-0140","parentItemId":null,"revision":1,"payload":{"prompt":".............. is consulted mostly by speech makers and writers","options":["Book of Quotation","Biographical book","Manual","Book of reference"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"A book of quotation supplies quotations on various subjects by particular authors, and it is mostly consulted by speech makers and writers, so A is correct. A biographical book (B) gives facts about individuals, a manual (C) explains how to do things, and a book of reference (D) is too general to be the answer."}},{"itemId":"43a64917-aade-5d17-b818-23806746eff5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c8bc6e04-6492-5c61-aa05-8b53266e651c","sourceKey":"bank:GST111:GST111-0141","parentItemId":null,"revision":1,"payload":{"prompt":"The terminal punctuation includes all except one","options":["comma","full stop","exclamation mark","question mark"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The full stop, question mark and exclamation mark are terminal punctuation marks because they signal the end of a sentence. The comma separates words, phrases and clauses inside a sentence and never ends one, so A is the odd one out. Options B, C and D are all terminal marks."}},{"itemId":"451550d3-a8f8-5aca-bb51-c32a05c59d29","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"68b3d127-ba33-5cd3-8607-c4c7f6d01a72","sourceKey":"bank:GST111:GST111-0142","parentItemId":null,"revision":1,"payload":{"prompt":"The simple present tense is used to indicate","options":["a completed past action","present","irregularity","regularity"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The simple present tense is used when someone does something regularly or something goes on all the time, for example I jog every morning or The cock crows at dawn. So it signals regularity, option D. Option B, present, is tempting because of the name, but an action happening right now is the job of the present continuous. A completed past action (A) needs the simple past, and irregularity (C) is the opposite of what this tense shows."}},{"itemId":"d56b9545-63b5-5303-b4d5-08fe1a2060c5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"02a98128-c10d-5697-a841-f8510b29f783","sourceKey":"bank:GST111:GST111-0143","parentItemId":null,"revision":1,"payload":{"prompt":"................. are allowed access into Gandhi Library","options":["External users only","Researchers and Post graduate students","Library staff only","None of the listed"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Access to the University of Lagos Research and Bibliographic Department, known as the Gandhi Library, is strictly for researchers and postgraduate students, so B is correct. Undergraduates are admitted only on presenting a letter from a head of department, supervisor or course lecturer. Options A and C name groups that are not the ones admitted, and D is wrong because a specific group is named."}},{"itemId":"3f8f860e-f9e3-5f87-b82d-c1b60cc3d37d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"47589b5b-3cf8-54e6-b63b-10029235ea68","sourceKey":"bank:GST111:GST111-0144","parentItemId":null,"revision":1,"payload":{"prompt":"Interrogative sentences \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["ask questions","express strong emotion","make statements","give commands"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"Sentences are classified by function into declarative, interrogative, imperative and exclamatory, and an interrogative sentence asks a question, such as What were you doing this morning? So A is correct. Option B describes the exclamatory sentence, C describes the declarative, and D describes the imperative."}},{"itemId":"0baad9d9-9681-5fb0-ab1d-85a806ab8566","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d65a601e-3091-5cd3-af9d-ff4555e4bd8b","sourceKey":"bank:GST111:GST111-0145","parentItemId":null,"revision":1,"payload":{"prompt":"Free morphemes are sub-categorized into ---------------","options":["grammatical and functional.","functional and descriptive.","lexical and functional.","descriptive and functional."],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Free morphemes are words that can stand alone, and they fall into two groups: lexical morphemes, which carry content meaning (nouns, verbs, adjectives and adverbs such as boy, run, happy), and functional morphemes, which do grammatical work (articles, prepositions, conjunctions and pronouns such as the, of, and). So C is correct. Options A, B and D pair functional with a label (grammatical, descriptive) that is not the standard partner term; grammatical is just another word for functional, not a separate class."}},{"itemId":"b901336c-67e1-5f8a-ae30-1c899b7570a2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f06c81d7-8d16-517f-9404-4fd9b961e5e5","sourceKey":"bank:GST111:GST111-0146","parentItemId":null,"revision":1,"payload":{"prompt":"Publications issued in successive parts, at regular intervals, and intended to be continued indefinitely are .......","options":["Serials collection","None","Serials report","Collective report"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"A publication issued in successive parts, at regular intervals, and usually intended to continue indefinitely is a serial, so A, serials collection, is correct. Newspapers, magazines, journals, indexes and abstracts are examples. Serials report and collective report (C and D) are not library terms, and B is wrong because the definition fits a serial exactly."}},{"itemId":"de415bc3-ec8d-5c12-abdc-3077c92269b4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ff16d144-b6f9-580c-84ce-59545a180e46","sourceKey":"bank:GST111:GST111-0147","parentItemId":null,"revision":1,"payload":{"prompt":"The main function of \\_\\_\\_\\_\\_\\_\\_\\_ is to separate independent clause","options":["exclamation mark","colon","semi colon","comma"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The semicolon is used to separate two independent clauses that could each stand alone, replacing a comma plus a coordinating conjunction, as in Supply us with three cars; they must all be black. So C is correct. A comma (D) is tempting, but a comma alone between independent clauses creates the error called a comma splice. A colon (B) introduces lists and an exclamation mark (A) ends excited statements."}},{"itemId":"871396bf-2150-5ce0-a48e-7756bfc20960","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b24b0352-58b3-575a-a8c9-ba1e02b18eed","sourceKey":"bank:GST111:GST111-0148","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a Type of Subordinate Clauses","options":["infinite Clause","the Non- finite Clause","the Finite Clause","the Verbless Clause"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"Subordinate clauses are classified by form into the finite clause (the verb changes with person, number and tense), the non-finite clause (the verb form stays the same) and the verbless clause (no verb at all). There is no such thing as an infinite clause in grammar, so A is the one that does not belong. Options B, C and D are all genuine types."}},{"itemId":"090c05f4-71a9-5e43-a828-8c617abb058b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"65a609cb-794a-5668-a3f8-04888b9082fa","sourceKey":"bank:GST111:GST111-0149","parentItemId":null,"revision":1,"payload":{"prompt":"................. is referred to as the meat of the essay.","options":["Content","Expression","Mechanics","Organization"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Content is the depth of treatment of the subject matter, and the knowledge and authority brought to the discussion, and it is described in everyday terms as the meat of the essay. So A is correct. Expression (B) is about choice of words, mechanics (C) is about punctuation and similar conventions, and organization (D) is the ordering of material; none of them is the substance itself."}},{"itemId":"e3566d3f-cec8-59ff-b76b-7e1c330e9a4c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cf828391-59f1-56b8-8741-964c698f4673","sourceKey":"bank:GST111:GST111-0150","parentItemId":null,"revision":1,"payload":{"prompt":"Africana materials are not loanable and users are not permitted to take them out of gandhi library","options":["Partially true","True","False","Partially false"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The statement is true, option B: Africana materials in the Gandhi Library (the Research and Bibliographic Department) are not loanable and cannot be taken out of that department. They may only be consulted there, although photocopying is allowed. Options A, C and D treat the statement as wholly or partly false, which is not correct."}},{"itemId":"d954456a-34db-51fb-ae23-d60454d657e7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9aa6c1d8-a711-50a4-bff5-86f7f5893f80","sourceKey":"bank:GST111:GST111-0151","parentItemId":null,"revision":1,"payload":{"prompt":"Example of Audio-visual materials is","options":["Map","Book","Television","Journal"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Television, option C, is an audio-visual material because it combines sound and picture; other examples are LCD projectors, computers and VCD players. A map (A) is a visual material only, while a book (B) and a journal (D) are print resources."}},{"itemId":"03a9de5a-0521-5246-9a7c-cd15c5852ac3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c917386b-30b7-563a-af17-4aa251e6e7af","sourceKey":"bank:GST111:GST111-0152","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'youth' can be transcribed as ------------------","options":["/ju:θ/","/ju:ð/","/yu:θ/","/yu:ð/"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Youth begins with the palatal glide /j/ (the sound spelt y), followed by the long vowel /u:/ as in food, and ends with the voiceless th sound /θ/, so A is correct. Options C and D wrongly use the letter y instead of the phonetic symbol /j/, and options B and D end in the voiced /ð/ of this and mother, which is not the sound in youth."}},{"itemId":"91f732fc-5639-5cdb-9536-ff925e4dc320","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ef541c40-cfb1-5395-a60e-eb1ba870e79f","sourceKey":"bank:GST111:GST111-0153","parentItemId":null,"revision":1,"payload":{"prompt":"Arrangement of materials on the shelves is done using\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["Catalogue","Nominal roll","Classification scheme","Planned steps"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Materials on the shelves are arranged using a classification scheme, option C. The University of Lagos main library uses the Library of Congress Classification Scheme (and the National Library of Medicine scheme at the College of Medicine), so books are shelved by their classification call numbers. A catalogue (A) is tempting, but it is the tool you search to find the call number, not the system that arranges the shelves. Options B and D are not library tools."}},{"itemId":"182d488a-b12a-5fa3-b2bc-b92b65ddea32","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2725f2d9-408d-5ec3-b6e7-894e13a5532a","sourceKey":"bank:GST111:GST111-0154","parentItemId":null,"revision":1,"payload":{"prompt":"The person who provides reference services is called...........","options":["Reference Librarian","Chief Librarian","University Librarian","Library Officer"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The librarian whose job is to help users find information and answer enquiries at the reference section is the reference librarian, option A; the title describes the service offered. A chief librarian (B) and a university librarian (C) are titles for the overall head of the library, and a library officer (D) is a general staff designation rather than the person who provides reference services."}},{"itemId":"a2e3a0bd-0719-553c-9c62-cc0e9848e311","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3e861ccd-fed6-50e4-b5e8-ed7b96b784f5","sourceKey":"bank:GST111:GST111-0155","parentItemId":null,"revision":1,"payload":{"prompt":"The ................. is the major point which an essay seeks to prove","options":["thesis","synopsis","subject matter","theme"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A good essay proves a major point, and that point is called the thesis, option A; it is the central idea and organizing principle that guides the choice of material. A theme (D) is the general subject area, subject matter (C) is what the essay is about rather than what it argues, and a synopsis (B) is a summary, for example of a plot."}},{"itemId":"0604bacd-4b96-5758-ba73-138947252bc0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d775384c-859c-5d68-9d23-30513e91cb0c","sourceKey":"bank:GST111:GST111-0156","parentItemId":null,"revision":1,"payload":{"prompt":"Apostrophes are used \\_\\_\\_\\_\\_\\_\\_\\_","options":["for transitivity","for epithensis","for contractions","to form plurals"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Apostrophes are used for contractions, option C, to show that letters have been omitted, as in won't. They are also used to show possession, as in Ade's salary. Option D is wrong because apostrophes are never used simply to form plurals, and they are not used in possessive pronouns like theirs or its. Options A and B are not functions of any punctuation mark."}},{"itemId":"899aaea7-ba8f-5eb0-bcfc-e1f51491ca00","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7dde8141-e4dd-5168-b5ae-c78b84898475","sourceKey":"bank:GST111:GST111-0157","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following are irregular nouns?","options":["man-men, woman-women, louse- lice.","Leaf-leaves, wife-wives, half-halves","all of these","foot-feet, goose-geese, tooth- teeth"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Irregular nouns include those that change an internal vowel in the plural (man-men, woman-women, louse-lice, foot-feet, goose-geese, tooth-teeth) and those that change -f or -fe to -ves (leaf-leaves, wife-wives, half-halves). Since A, B and D all give genuine irregular plurals, C, all of these, is correct. Picking any single option leaves out equally valid examples."}},{"itemId":"4e4baf41-1376-58b2-853a-3f0240acc9f8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8396d31a-529a-521c-8ca9-5d334291ff35","sourceKey":"bank:GST111:GST111-0158","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"He arrived yesterday\", the word \"yesterday\" is an","options":["adverb of frequency","adverb of time","adverb of degree","adverb of manner"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In He arrived yesterday, the word yesterday is an adverb of time because it answers the question when did he arrive? So B is correct. An adverb of frequency (A) would answer how often, degree (C) would answer to what extent, and manner (D) would answer how, none of which fits yesterday."}},{"itemId":"77ada61b-50f5-5a53-9e94-b92c34ed457f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1ffff0fb-bd64-5f6f-ae30-f1353711c2ff","sourceKey":"bank:GST111:GST111-0159","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'unhappily' contains-----------------","options":["prefix, root, suffix.","root, infix, suffix.","prefix, stem, root.","stem, root, suffix."],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Unhappily is built from three parts: the prefix un- (meaning not), the root happy, and the suffix -ly, which turns the adjective into an adverb, so A is correct. Option B is wrong because English words like this have no infix, and options C and D list two bases (stem and root) when unhappily has only one, and D also leaves out the prefix."}},{"itemId":"73aca271-f16b-54a6-af17-18cb5c27aa18","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4b4ad0c7-e13b-573e-b53b-eb6f30af412f","sourceKey":"bank:GST111:GST111-0160","parentItemId":null,"revision":1,"payload":{"prompt":"................. is not a type of abstract","options":["Informative abstract","Indicative abstract","Review abstract","Evaluative abstracts"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The three recognized types of abstract are the indicative, informative and evaluative abstracts. Review abstract (option C) is not one of them, so it is the answer. Options A, B and D are all genuine types."}},{"itemId":"48215cb0-08fa-5ab2-a1f3-8257fcfcf62c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"16e15808-14af-5270-a003-0a06331b2594","sourceKey":"bank:GST111:GST111-0161","parentItemId":null,"revision":1,"payload":{"prompt":"Sentences can be grouped into all but one of the following types","options":["interrogative","exclamatory","declarative","interlocutory"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Sentences are grouped by function into four types: declarative (statements), interrogative (questions), imperative (directives) and exclamatory (strong emotion). Interlocutory is a legal and conversational term, not a sentence type, so D is the odd one out. Options A, B and C all belong to the list."}},{"itemId":"9e1928ff-1f8b-50ba-81c4-bd3dc56dac47","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b3c52f56-3021-5b5b-beaf-4f62489c09ff","sourceKey":"bank:GST111:GST111-0162","parentItemId":null,"revision":1,"payload":{"prompt":"------------------- is the process of translating written or printed symbols and letters into words and sentences which convey meaning.","options":["listening","speaking","reading","writing"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading is the process of translating written or printed symbols and letters into words and sentences which convey meaning, using both the eyes and the brain, so C is correct. Listening (A) decodes spoken words rather than written symbols, while speaking (B) and writing (D) are productive skills that create language rather than interpret it."}},{"itemId":"9ef10186-57b5-5bb7-a23b-67b622d66e92","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ad868e2e-b9d6-5cc9-9c24-6de54412d4ec","sourceKey":"bank:GST111:GST111-0163","parentItemId":null,"revision":1,"payload":{"prompt":"I saw them across the road, the expression across the road can be described as a ------","options":["Verb phrase.","Adjective phrase","Noun phrase","Prepositional phrase"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"A prepositional phrase begins with a preposition and ends with a noun or pronoun called its object, as in under the bed and across the road, so D is correct. Option C, noun phrase, is tempting because the road is a noun phrase, but the whole expression is headed by the preposition across. Options A and B have a verb or adjective as the main word, which is not the case here."}},{"itemId":"0d3146e7-4df7-59e7-b819-bfb75f4c8da5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a5a597b5-ef00-5541-9e2a-4cee67ac2a8b","sourceKey":"bank:GST111:GST111-0164","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a distinction made between vowels.","options":["rounded/around","long/short","high/low","open/close"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are described by tongue height (high/low), openness (close/open), length (long/short, also called tense/lax) and lip shape, where the lips may be spread, neutral or rounded. Rounded contrasts with spread or neutral, never with 'around', which is not a phonetic term, so A is the one that is not a real distinction. Options B, C and D are all genuine pairs."}},{"itemId":"b6d63747-4219-56c6-b5f2-9c96ae715b7d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ed209f36-ad3c-52d4-b696-19d590710adf","sourceKey":"bank:GST111:GST111-0165","parentItemId":null,"revision":1,"payload":{"prompt":"The Research and Bibliographic section of the library houses ..........","options":["PhD theses","Both A and D","Law books","Old and current newspapers"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The Research and Bibliographic Department, known as the Gandhi Library, holds research materials including PhD theses and old and current newspapers dating back to 1930, so B, which combines A and D, is correct. Choosing A or D alone leaves out the other holding. Law books (C) are not what this department is known for."}},{"itemId":"510f38cc-ab1c-5827-8919-bdea58f39a1f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"012ac432-30ce-5181-bded-57947b8ddacd","sourceKey":"bank:GST111:GST111-0166","parentItemId":null,"revision":1,"payload":{"prompt":"Copyrighted works are protected by .............","options":["Book seller","Law","The author","Publisher"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Copyright law (or author's right) says that no one may use a creative work without the owner's permission, and anyone who does so is liable to prosecution, so B, law, is correct. The author (C) owns the right, but the protection comes from the law, while a book seller (A) and a publisher (D) merely sell or produce the work."}},{"itemId":"5a325fda-27fc-5dba-8f5f-c6d6a8525751","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"06a3ff62-f24e-582c-a811-770aae1a71da","sourceKey":"bank:GST111:GST111-0167","parentItemId":null,"revision":1,"payload":{"prompt":"A student that has committed plagiarism can be ...........","options":["Suspended or rusticated","Jailed","Given an award","Promoted"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"A student caught plagiarising can be suspended or rusticated, meaning sent away from school for a period, so A is correct. Option B, jailed, is tempting because prosecution is possible, but the usual penalty for a student is suspension or rustication. Options C and D (an award, a promotion) are rewards, not punishments."}},{"itemId":"390f0658-a68a-555c-80a4-6afc809f4376","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8adffd28-7ed8-5a76-999d-0cbf97efd4fd","sourceKey":"bank:GST111:GST111-0168","parentItemId":null,"revision":1,"payload":{"prompt":"Reference materials include the following EXCEPT:","options":["Encyclopaedia","Journals","Indexes","Dictionaries"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Journals are serials, meaning they are published in successive parts at regular intervals, so they are not classed as reference materials. Reference materials are things like dictionaries, encyclopaedias, indexes, biographies, handbooks and manuals, which you consult for quick facts. That is why A, C and D are all reference materials and B is the exception."}},{"itemId":"9415b74d-eb7e-595e-89da-b1960c77b903","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3c1ed1df-60dd-5ba3-9876-7c40391e4ee3","sourceKey":"bank:GST111:GST111-0169","parentItemId":null,"revision":1,"payload":{"prompt":"A/an ---------------- paragraph describes a series of events or a process in some sort of order.","options":["descriptive","explanation","evaluation","sequence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A sequence paragraph describes a series of events or a process in some order, usually time order, and it uses helper words like first, second, third and previously. Option B (explanation) tells how or why something happens, C (evaluation) makes judgements, and A (descriptive) paints a picture of a person, place or thing, so none of them is about order of events."}},{"itemId":"1404de8a-4057-5eff-908a-3b7771b15309","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"10a75c3f-a1a8-5b42-a74e-3f9d44a18e57","sourceKey":"bank:GST111:GST111-0170","parentItemId":null,"revision":1,"payload":{"prompt":"Clear thinking, accurate data, reliable authority and clear conclusion are applicable to ........ essay.","options":["persuasive","narrative","descriptive","analytical"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An analytical essay is built on clear thinking, accurate or verified data, reliable authority and clear conclusions drawn from the evidence, so D is correct. Option A (persuasive) leans on details plus appeals to emotion, B (narrative) tells a story in sequence, and C (descriptive) gives vivid accounts of scenes and people."}},{"itemId":"f3d934c2-b9d4-51c2-bcd3-7ce63643e4fe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fdcc416f-1e20-536f-8e6a-1a347b9d84d6","sourceKey":"bank:GST111:GST111-0171","parentItemId":null,"revision":1,"payload":{"prompt":"In essay writing, the acronym COEM means ................","options":["Content, Organisation, Entertainment, Mechanics","Content, Organisation, Expression, Mechanics","Comment, Organisation, Expression, Mechanics","Content, Orientation, Expression, Mechanics"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"COEM stands for Content, Organisation, Expression and Mechanics, the four quality-control components of a good essay, so B is correct. The other options each swap one word for a wrong one: A uses Entertainment instead of Expression, C uses Comment instead of Content, and D uses Orientation instead of Organisation."}},{"itemId":"1be0b3af-73df-52dd-81c3-7fd4eb23e4a0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"893ecde0-6088-5112-b0dd-92ed945df02b","sourceKey":"bank:GST111:GST111-0172","parentItemId":null,"revision":1,"payload":{"prompt":"................. is not a step in paragraph development.","options":["choosing a controlling idea","giving examples","none of these","explaining the controlling idea"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The steps in paragraph development are: choose a controlling idea and write a topic sentence, explain the controlling idea, give an example or examples, explain the examples, and then complete the idea or lead into the next paragraph. Since A, B and D are all genuine steps, C, none of these, is the answer to a question asking which is not a step."}},{"itemId":"05829610-7542-515c-b6fb-4ddec7da0baa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9b0f4686-5fa8-5b6d-8c79-61b37a0a9bc4","sourceKey":"bank:GST111:GST111-0173","parentItemId":null,"revision":1,"payload":{"prompt":"A question mark is not used at the end of ............","options":["a tag question","a direct question","an echo question","an indirect question"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A question mark is not used after an indirect (reported) question, because that kind of question is really a statement, as in The manager demanded to know why production was slow. So D is correct. A direct question (B), a tag question (A) such as She is here, isn't she? and an echo question (C) such as Bisi has travelled? all end with a question mark."}},{"itemId":"81a45893-e877-539a-9cc3-ddfaa7dd5dfa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"60cbbecd-bfda-557a-869e-d324c5735a86","sourceKey":"bank:GST111:GST111-0174","parentItemId":null,"revision":1,"payload":{"prompt":"............... is the informed evaluation of imaginative writing.","options":["criticism","coherence","blogging","essay writing"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Criticism is the analytical way of writing that gives an informed evaluation of imaginative writing, and critiques are one strategy of the analytical essay. Option B (coherence) is a quality of a good paragraph, C (blogging) is not an academic method, and D (essay writing) is too broad to be the specific word for judging literature."}},{"itemId":"221840d4-f6c0-59a0-9abf-b6065eba0a39","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fa33a2e6-75e2-532c-a0ae-7a803782762f","sourceKey":"bank:GST111:GST111-0175","parentItemId":null,"revision":1,"payload":{"prompt":"/s/ /t/ and /n/ are related based on their --------------- of articulation.","options":["place","manner","nature","length"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"The sounds /s/, /t/ and /n/ are all alveolar, made with the tip or blade of the tongue touching the alveolar ridge behind the upper teeth, so what they share is place of articulation. Option B (manner) is wrong because their manners differ: /s/ is a fricative, /t/ a stop and /n/ a nasal. Nature and length are not ways of describing consonants."}},{"itemId":"1f618a06-1d7e-55e8-8009-306bee145f54","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3aef8e01-dc34-5eb0-b54e-3720831ff9dd","sourceKey":"bank:GST111:GST111-0176","parentItemId":null,"revision":1,"payload":{"prompt":"-eer in 'engineer' and -aire in 'millionaire' are examples of -------------------- affixes.","options":["stress-neutral","stress-moving","stress-bearing","stress-conserving"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress-bearing affixes are the ones that carry the primary stress themselves, as -eer does in engineer and -aire does in millionaire, so C is correct. A (stress-neutral) affix leaves the stress where it was, B (stress-moving) shifts stress to another syllable of the stem, and D (stress-conserving) is not a recognised category."}},{"itemId":"5677b9a4-3ca9-58d0-bd86-061d5578731c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bd8aad12-88cd-57ba-9cdc-a5b7b5d7b1cb","sourceKey":"bank:GST111:GST111-0177","parentItemId":null,"revision":1,"payload":{"prompt":"Your mental posture while reading is not affected by ...............","options":["music from the radio or other gadgets","worries about money and affairs","the arrangement of keywords and topic sentences","noise"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Your mental posture for reading is disturbed by things like music from a radio or phone, noise, and worries about money, love or health. The arrangement of keywords and topic sentences is different: it is a reading strategy that helps you follow the text, so it does not disturb you, and C is the answer. A, B and D are all distractions."}},{"itemId":"402b75ba-ee9a-5966-9684-cf2a7fe9774b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5b92b391-36ae-5d78-b41e-5fc66f516ba8","sourceKey":"bank:GST111:GST111-0178","parentItemId":null,"revision":1,"payload":{"prompt":"The category of words to which new words can always be added is called-------","options":["open class words","closed class words","grammatical words","suffixation words."],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Open class words are word classes that readily accept new members, such as nouns, verbs, adjectives and adverbs, so new words like webinar or selfie can always be added. Closed class words (B) and grammatical words (C), such as prepositions and conjunctions, almost never gain new members. Suffixation words (D) is not a grammatical term."}},{"itemId":"b9eb0587-7a58-5b71-b872-c855c85b328e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"69313825-86eb-5ba4-8bfc-caa5428a85b6","sourceKey":"bank:GST111:GST111-0179","parentItemId":null,"revision":1,"payload":{"prompt":".............. is the punctuation mark used to express all forms of excitement.","options":["exclamation mark","question mark","semi-colon","colon"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, disappointment, anger, indeed all forms of excitement, as in Look out! or Oh, boy! Option B (question mark) ends direct questions, C (semi-colon) joins closely related independent clauses, and D (colon) introduces lists."}},{"itemId":"08834c3b-8655-5395-a914-df670ac91956","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5e3244d7-a9a3-55cd-a0a5-a767ca728f5f","sourceKey":"bank:GST111:GST111-0180","parentItemId":null,"revision":1,"payload":{"prompt":"To avoid plagiarism","options":["Other people's ideas must be paraphrased and cited","A lecturer must be consulted","One must use library properly","Manuscript must be read"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is avoided by acknowledging the work you use: paraphrasing other people's ideas properly and citing the sources in the prescribed style and the reference list. Option A captures exactly that. Consulting a lecturer (B), using the library (C) or reading the manuscript (D) may be good habits, but none of them by itself stops you from plagiarising."}},{"itemId":"1239080e-2a23-542c-8129-e7467746dbe4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8dd4a520-75b5-521c-9a34-d08925061c5d","sourceKey":"bank:GST111:GST111-0181","parentItemId":null,"revision":1,"payload":{"prompt":"The ability to recognize when information is needed is called .........","options":["Information knowledge","Data","Information explosion","Information literacy"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Information literacy is the ability to locate, retrieve, evaluate and apply information, and it includes recognising when information is needed (this is the American Library Association's definition). Option B (data) means raw facts, C (information explosion) is the rapid growth in the amount of information available, and A is not a recognised term."}},{"itemId":"2d858148-4944-52f4-8e44-19893a0df32b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"71b0c689-76fe-5be5-be26-f476c814382a","sourceKey":"bank:GST111:GST111-0182","parentItemId":null,"revision":1,"payload":{"prompt":"---------------------- is not a key element to look out for when reading a material.","options":["the conclusion","the introductory section","the author's main point.","spelling errors"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When reading with intent, the key elements to look for are the meaning of the title and subtitles, the introduction, the author's main point (thesis statement), the supporting explanation and the conclusion. Spelling errors are not among them; hunting for them is proofreading, not reading for understanding. A, B and C are all key elements, so D is the exception."}},{"itemId":"9d3bc800-176d-5456-8b28-e9bc7f4ebcce","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bcc5ce41-6391-51f2-9950-d47f06729f47","sourceKey":"bank:GST111:GST111-0183","parentItemId":null,"revision":1,"payload":{"prompt":"As a prefix, ANTI- means","options":["Congruent","Similar","Dissimilar","Against"],"correctOption":3,"section":"Vocabulary Development","explanation":"The prefix anti- means against or opposed to, as in anti-social, or antibiotic (against the life forms that cause disease). Option C (dissimilar) is tempting because opposing something can suggest difference, but anti- expresses opposition, not just being different. A and B (congruent, similar) point the opposite way. Also take care not to confuse anti- with ante-, which means before."}},{"itemId":"d07d2da6-63bf-5a09-865b-2ae7bf7291eb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2362943b-3f64-5c69-8a03-c78668c2424f","sourceKey":"bank:GST111:GST111-0184","parentItemId":null,"revision":1,"payload":{"prompt":"Which receptive skill involves receiving, perceiving and decoding spoken words?","options":["listening","speaking","reading","writing"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Listening is the receptive skill of receiving, perceiving and decoding the meaning of spoken words, so A is correct. Reading (C) is also receptive, but it decodes written symbols, not speech. Speaking (B) and writing (D) are productive skills, since they create language rather than receive it."}},{"itemId":"1e960e70-5344-5734-925d-458f55e72a6f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4b008116-5f67-5872-ae37-9e6322af10b7","sourceKey":"bank:GST111:GST111-0185","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is a feature shared by both paragraphs and essays:","options":["unity and self sufficiency","cohesion and transparency","transition and cohesion","unity and coherence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Both a good paragraph and a good essay show unity and coherence: unity means sticking to a single focus, and coherence means the ideas flow logically and are easy to follow. Options A, B and C each pair in something that is not a core feature, such as self sufficiency or transparency, or name transition, which is only a device for achieving coherence."}},{"itemId":"3b62bba1-49b2-5494-ae4d-958811ada71a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3e5bd0e5-a64d-5399-9705-1716929758a0","sourceKey":"bank:GST111:GST111-0186","parentItemId":null,"revision":1,"payload":{"prompt":"A quote is used in research write up to..................","options":["show off your writing skills","use vocabulary","convince your supervisor","support an argument"],"correctOption":3,"section":"Search Strategies","explanation":"You use a quotation to add the power of the author's own words to support your argument, and also to disagree with an author, compare points of view or note existing research, so D is correct. Showing off your writing skills, using vocabulary or convincing your supervisor (A, B and C) are not academic reasons for quoting."}},{"itemId":"c5b86059-06f7-5672-ab0b-4d308cfc186a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"92f34410-eafe-54db-bb8f-b9784562d120","sourceKey":"bank:GST111:GST111-0187","parentItemId":null,"revision":1,"payload":{"prompt":"The main kinds of electronic materials in most libraries are:","options":["e-books and e- periodicals","pamphlets and cassettes","cards and newspapers","pamphlets and videotapes"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic library materials are things like electronic books, electronic journals, electronic images and full-text records from the internet, so e-books and e-periodicals fit. Pamphlets, cassettes and videotapes (in B and D) are print or audio-visual items, not electronic ones, and option C (cards, newspapers) lists print formats."}},{"itemId":"f74ba458-f09a-5017-afb6-704144b63895","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b3ad14c0-f23d-58ac-8ec2-6b71d61cbc66","sourceKey":"bank:GST111:GST111-0188","parentItemId":null,"revision":1,"payload":{"prompt":"---------------- is not associated with sensory memory.","options":["the ears","the brain","the nose","the eyes"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Sensory memory is tied to the senses, so the organs involved are the ears, eyes, hands, tongue and nose. The brain is not a sense organ; it processes information after the senses have received it, so B is the one not associated with sensory memory. A, C and D are all sense organs."}},{"itemId":"fa16d176-39a1-57b7-9c3c-55b547462b08","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a444f5f8-83c1-5144-9648-601069156e66","sourceKey":"bank:GST111:GST111-0189","parentItemId":null,"revision":1,"payload":{"prompt":"One of these does not appear in the reference list","options":["Author's name","Page","Title of a work","Keyword"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A reference list entry records the author's surname and initials, the title of the work, and publication details such as place, publisher, date and page numbers. A keyword is just a term you type into a search engine or database to find material, so it never appears in a reference entry. That makes D correct, while A, B and C are all standard parts of a reference."}},{"itemId":"a667db4c-fe89-5f86-8fd2-2b2ea9926c51","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e86a746a-c33a-504c-a45f-e2552ef79060","sourceKey":"bank:GST111:GST111-0190","parentItemId":null,"revision":1,"payload":{"prompt":"To be elected ................, candidates must have a solid background in law enforcement.","options":["Sheriff","Sherrif","Sherif","Sherriff"],"correctOption":0,"section":"Vocabulary Development","explanation":"The correct spelling is sheriff, with one r and two f's, so A is correct. Option B doubles the r and drops an f, C drops an f, and D doubles both the r and the f, so all three are misspellings."}},{"itemId":"9aaade85-51bf-5662-a0e4-d2f0bc2a797d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9b48d423-bdc8-5067-9134-d1b493d4fd4b","sourceKey":"bank:GST111:GST111-0191","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a type of reading.","options":["spinning","study reading","scanning","skimming"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The types of reading are skimming (quick reading for the overall idea), scanning (searching for a specific piece of information) and study reading (intensive, critical reading). Spinning is not a reading technique at all, so A is the odd one out, and B, C and D are all genuine types."}},{"itemId":"b9b07c82-826b-538a-8409-68160e765394","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6fbb7f09-aaa0-5bce-aba6-a59d7df5ae31","sourceKey":"bank:GST111:GST111-0192","parentItemId":null,"revision":1,"payload":{"prompt":"An affix which does not affect the position of stress in a word is ---------------","options":["stress-neutral","stress-bearing","stress-conserving","stress-moving"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A stress-neutral affix does not change where the stress falls: the word keeps its original stress, as in pleasant and unpleasant, or market and marketing. Option B (stress-bearing) means the affix itself takes the stress, D (stress-moving) shifts it to another syllable, and C (stress-conserving) is not a recognised category."}},{"itemId":"b774452b-43f7-511f-8933-aa4610bc01ad","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3da0ae9a-ac74-5aa0-8764-92523e8a2101","sourceKey":"bank:GST111:GST111-0193","parentItemId":null,"revision":1,"payload":{"prompt":"There are -------------- sounds altogether in English.","options":["20","26","44","24"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English has forty-four significant sounds (phonemes): twenty vowels and twenty-four consonants, so C is correct. Options A (20) and D (24) are only the vowel count and the consonant count on their own, and B (26) is the number of letters in the alphabet. Letters and sounds do not correspond one to one."}},{"itemId":"8f361337-85e3-5ab4-b364-2bc5e5d0b29a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f431fa50-e476-55d6-8798-3cd9b06ea110","sourceKey":"bank:GST111:GST111-0194","parentItemId":null,"revision":1,"payload":{"prompt":"The term 'lateral' refers to -----------------","options":["/r/","/l/","/j/","/w/"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"A lateral consonant is made when the tip of the tongue touches the alveolar ridge and air escapes along the sides of the tongue, and that sound is /l/. Option A (/r/) is a post-alveolar approximant, while C and D (/j/ and /w/) are glides, a sub-group of approximants."}},{"itemId":"04b6b7d7-7f4f-5a14-a27e-7ef75f88d3fd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e79aba5f-c27d-5932-8df4-8bb406b32644","sourceKey":"bank:GST111:GST111-0195","parentItemId":null,"revision":1,"payload":{"prompt":"In \"My mother cooks very well\", the word \"very\" is an","options":["adverb of degree","adverb of place","adverb of manner","adverb of time"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In My mother cooks very well, the word very tells us to what extent she cooks well, so it is an adverb of degree, option A. Option C (manner) is tempting because well on its own says how she cooks, but very only intensifies well. Options B and D (place, time) do not fit at all."}},{"itemId":"9f55f94a-c3f8-5139-aa01-fac776c1701e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"573879d8-d71c-5d3d-a57b-72d1bb818908","sourceKey":"bank:GST111:GST111-0196","parentItemId":null,"revision":1,"payload":{"prompt":"Generally, information sources are divided into which of the following categories?","options":["Both C and D","Tertiary","Secondary","Primary"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Information sources fall into two categories: primary sources (first-hand accounts such as original research reports, diaries or novels) and secondary sources (works that analyse or explain a primary source). So the correct choice is A, which combines C and D. Choosing C or D alone leaves out the other category, and B (tertiary) is not one of the two categories."}},{"itemId":"96e15ff3-cdbd-56d4-9443-1c9cc0bfa4e7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8f3df6a0-576f-5411-89d6-793d20cc1235","sourceKey":"bank:GST111:GST111-0197","parentItemId":null,"revision":1,"payload":{"prompt":"Declarative sentences end with a/an \\_\\_\\_\\_\\_","options":["exclamation point","period","comma","question mark"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A declarative sentence is a statement, and it ends with a full stop or period, as in Our organisation trades in petroleum products. Option A (exclamation point) ends excited or emotional statements, D (question mark) ends direct questions, and C (comma) cannot end a sentence at all."}},{"itemId":"9f453f14-203c-53f0-aca3-7afe8d73c85b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"befd4160-086c-5ef1-8e8b-0583c48c234e","sourceKey":"bank:GST111:GST111-0198","parentItemId":null,"revision":1,"payload":{"prompt":"It is NOT ideal to begin a new paragraph when:","options":["readers need a pause in a long stretch of text","the next statement contrasts with the preceding information","you want to introduce a new idea","you are still developing the same main idea"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph keeps to a single main idea, so while you are still developing that idea you should stay in the same paragraph, which makes D correct. A new paragraph is the right move when you introduce a new idea (C), when the next statement contrasts with what came before (B), or when readers need a pause (A)."}},{"itemId":"77fc3ef7-e179-53c1-8100-d6dbb79f3775","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"862f3b25-7358-55ea-9e43-06eea9e7c1d7","sourceKey":"bank:GST111:GST111-0199","parentItemId":null,"revision":1,"payload":{"prompt":"A/an ---------------- paragraph explains how or why something happens.","options":["definition","explanation","choice","sequence"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An explanation paragraph explains how or why something happens, exploring causes and effects with helper words like because, therefore and thus. Option A (definition) explains key words, C (choice) states a preference, and D (sequence) describes events in time order."}},{"itemId":"c302311c-9067-5c38-9aca-fbc96abeb797","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1b847786-0c37-5862-8798-3e11a9538836","sourceKey":"bank:GST111:GST111-0200","parentItemId":null,"revision":1,"payload":{"prompt":"Criteria to evaluate credibility of Information resources are; currency, authority, ...... and ......","options":["Relevancy & intelligence","Strategy & accuracy","Relevancy & accuracy","None"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The criteria for judging information resources are currency, relevancy, authority, accuracy and purpose. With currency and authority already given, the missing two are relevancy and accuracy, so C is correct. Option A pairs relevancy with intelligence and B pairs accuracy with strategy, and neither of those is a criterion. D is wrong because a correct pair is listed."}},{"itemId":"e8ca24f6-aa18-5320-8067-a03765c73c34","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b9b14168-31b9-5590-add2-d9975d7e6039","sourceKey":"bank:GST111:GST111-0201","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following words is misspelled?","options":["parachutis","communication","accommodation","swinging"],"correctOption":0,"section":"Vocabulary Development","explanation":"The word in A is misspelt: the correct spelling is parachutist, ending in -ist, but option A has lost its final t. Communication, accommodation and swinging (B, C and D) are all spelt correctly, though accommodation is a common trap because it needs a double c and a double m."}},{"itemId":"5d440daa-f079-5dc8-b752-fb04eeaceb70","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c7d415d7-d6ba-58e3-a590-c4f332ed7a5e","sourceKey":"bank:GST111:GST111-0202","parentItemId":null,"revision":1,"payload":{"prompt":"............. collections are not expected to be read from cover to cover like books","options":["Reference","Abstract","Americana","Africana"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Reference collections, such as dictionaries, encyclopaedias, indexes and fact sources, are consulted for specific pieces of information, so they are not meant to be read from cover to cover. Option D (Africana) is a research collection of materials on Africa, and its books and theses are studied like other books. Option B (abstract) is only one type of reference source, not a library collection, and C (Americana) is the name of an encyclopaedia, not a collection."}},{"itemId":"87fa2003-221e-54c0-9081-b3056fa5b5c6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"84785199-42cd-59fb-86e0-57ed9c0a7ae8","sourceKey":"bank:GST111:GST111-0203","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a criterion for predicting stress.","options":["syntactic","phonological","morphological","semantic"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress placement in English words can be predicted using phonological criteria (the structure of the syllables), syntactic criteria (the word class, as in REcord versus reCORD) and morphological criteria (the effect of affixes). Semantic criteria, that is, meaning, are not used, so D is correct, and A, B and C are genuine criteria."}},{"itemId":"cbad0a46-f710-5b38-9961-4ac4d2e94a9b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dc8b0540-8fde-57b4-95d1-0b72e43aad12","sourceKey":"bank:GST111:GST111-0204","parentItemId":null,"revision":1,"payload":{"prompt":"To achieve depth in the treatment of a topic, the writer is advised to ......","options":["punctuate words appropriately","manage transition","limit/narrow the subject","expand the subject"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Depth of content depends on size: a large subject such as population growth cannot be treated exhaustively, so a writer must limit or narrow the subject at the start. Option D (expanding the subject) does the opposite and leads to skimming the surface. A and B (punctuation, transition) belong to mechanics and organisation, not depth of content."}},{"itemId":"916ad718-2099-52a6-976c-aec41d6154b7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bd6d2a6a-f8fb-5fdc-8d17-635670c050d5","sourceKey":"bank:GST111:GST111-0205","parentItemId":null,"revision":1,"payload":{"prompt":"The largest grammatical unit in English is the------and the smallest is the ---------","options":["paragraph, morpheme","sentence, morpheme","clause, word","sentence, phrase"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The grammatical units run from the morpheme, through the word, phrase and clause, up to the sentence, so the sentence is the largest unit and the morpheme the smallest. Option A is wrong because the paragraph is a unit of writing, not of grammar. Options C and D name units that sit in the middle of the scale, since the word and the phrase are both bigger than the morpheme."}},{"itemId":"6b8aff80-fe67-5dca-af3b-f1385fb18bd1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7e72aa51-6357-5c24-817c-99bb92ae549d","sourceKey":"bank:GST111:GST111-0206","parentItemId":null,"revision":1,"payload":{"prompt":"A library's entire holding is held in a manual database called --------","options":["Book box","Check list","Library holdings","Library catalogue"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The library catalogue is the index and essential tool for retrieving library resources, and it gives access to everything the library holds. It exists as a manual card catalogue and as the Online Public Access Catalogue (OPAC). Options A and B (book box, check list) are not library tools, and C (library holdings) is just the name for the collection itself, not the database that records it."}},{"itemId":"86610587-ca4e-5599-80b5-5a63711bf1c8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5c2f6fec-9afe-510c-87ba-dd6609f138b2","sourceKey":"bank:GST111:GST111-0207","parentItemId":null,"revision":1,"payload":{"prompt":"All are eligible for copyright according to World Intellectual Property Organization, EXCEPT ........","options":["Painting","Music","Books","Complimentary cards"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Works eligible for copyright under the World Intellectual Property Organization include books, music, paintings, sculpture, films, computer programs, databases, advertisements, maps and technical drawings. Complimentary cards are not on that list, so D is the exception, while A, B and C are all eligible."}},{"itemId":"aeb1d34e-2d54-5c80-a118-05aa61ca9458","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4d5ff559-c6d5-562e-956e-6c17a9c08906","sourceKey":"bank:GST111:GST111-0208","parentItemId":null,"revision":1,"payload":{"prompt":"................ is often called the awkward stage.","options":["Adolescense","Adolscence","Adolessents","Adolescence"],"correctOption":3,"section":"Vocabulary Development","explanation":"The correct spelling is adolescence, with -esc- in the middle and the noun ending -ence, and it is the stage of life often called awkward. Option A ends wrongly in -ense, B drops the e after the l, and C is a misspelt plural form (adolescents), which names the people rather than the stage of life."}},{"itemId":"bbd46b80-c3cd-5f04-adfe-722346aa3707","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"66b9d99c-b3f3-5e8b-8561-aa74815ee98d","sourceKey":"bank:GST111:GST111-0209","parentItemId":null,"revision":1,"payload":{"prompt":"\"OR\" is used as a search strategy when a user wants to ........... the search","options":["Limit","Develop","Broaden","Narrow"],"correctOption":2,"section":"Search Strategies","explanation":"The Boolean operator OR connects similar concepts or synonyms and broadens your search, because it tells the database that any of the terms may be present. Options A and D (limit, narrow) describe what AND and NOT do, and B (develop) is not a search function."}},{"itemId":"6bd6844f-c205-57cb-a653-7fcd135b84b9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bd6a9f33-6c4e-575e-b1af-c2f752aaf1e5","sourceKey":"bank:GST111:GST111-0210","parentItemId":null,"revision":1,"payload":{"prompt":"What is the function of the word \"boy\" in the sentence: That boy is my cousin?","options":["Object of the verb","Coplement of the noun","Subject of the verb","Complement of \"that\""],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"In That boy is my cousin, the noun phrase that boy names what the sentence is about and comes before the verb, so boy is the subject of the verb is. Option A (object) would receive the action of a verb, but the linking verb is has no such object. D is wrong because that is a demonstrative determiner pointing to boy, not something boy completes, and B is not a grammatical function."}},{"itemId":"8170f264-5a21-5506-8957-0025ef937221","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"14009a56-f441-523f-8876-a48ead305015","sourceKey":"bank:GST111:GST111-0211","parentItemId":null,"revision":1,"payload":{"prompt":"The two sources of information are:","options":["Books and Online sources","Library and Internet sources","Print and electronic sources","Primary and secondary sources"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"The two sources of information are primary and secondary. Primary sources give first-hand accounts such as original research, letters or novels, while secondary sources analyse, review or explain a primary source. Option C (print and electronic) is tempting because it is a real division of library resources by format, but it divides them by medium, not by kind of source. A and B are informal groupings, not the standard categories."}},{"itemId":"04fe36fe-29da-591f-9629-e83af09ff384","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"646fe724-ed95-519c-9afa-bbb44601c1bd","sourceKey":"bank:GST111:GST111-0212","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the incorrectly capitalised sentence","options":["The Parthenon is a temple dedicated to the goddess Athena","The Jewish festival of Passover commemorates the Exodus from Egypt","a parsnip is a root vegetable native to Eurasia","Blaise Pascal is a French scientist and mystic"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Every sentence must begin with a capital letter, and option C starts with a lower-case a (a parsnip is a root vegetable native to Eurasia), so it is incorrectly capitalised. Options A, B and D all begin with capitals and correctly capitalise their proper nouns (Parthenon, Athena, Passover, Egypt, Blaise Pascal, French)."}},{"itemId":"43320e09-6be3-5235-8cc1-912a5f91bc2b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cdd1850f-2d48-5654-be17-ee3d959a0a63","sourceKey":"bank:GST111:GST111-0213","parentItemId":null,"revision":1,"payload":{"prompt":"The prefix un- in the word \"unreliable\" can be described as a/an --------- morpheme.","options":["inflectional","free","lexical","derivational"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The prefix un- is a derivational morpheme because it creates a new word with a different meaning: reliable becomes its opposite, unreliable. Option A is wrong because inflectional morphemes such as -s or -ed only mark grammar like number or tense without making a new word. Options B and C are wrong because un- cannot stand alone, so it is neither a free morpheme nor a lexical (content) word."}},{"itemId":"06ce0eb2-b6e4-55f0-89fe-35c99fee7fea","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"08e030fe-0803-5039-9ab5-f37403c66de1","sourceKey":"bank:GST111:GST111-0214","parentItemId":null,"revision":1,"payload":{"prompt":"Fair use allows the usage of copyrighted works for ............","options":["Business purposes","Prosecution purposes","Publishing purposes","Academic purposes"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Fair use allows copyrighted works to be used without permission for purposes such as criticism, comment, news reporting and teaching, in short for academic purposes within certain limits. Options A and C (business, publishing) are commercial uses that need permission, and B (prosecution) is what can happen when copyright is infringed, not a permitted use."}},{"itemId":"e19747c9-c5b8-5259-9930-51ea45e87421","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"08267278-fe9f-55bb-a8e8-b30824b25545","sourceKey":"bank:GST111:GST111-0215","parentItemId":null,"revision":1,"payload":{"prompt":"Publications conveying recent original research and observation are known as..............","options":["Tables","Translations","Textbooks","Journals"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Journals are serials valued for the currency of their content, which is why recent original research and observations are published in them. Option C (textbooks) summarise established knowledge rather than report new findings, and A and B (tables, translations) are not publication types for original research."}},{"itemId":"62b293fc-7df9-5a17-beff-d08b299b4066","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6689f4cd-ea78-5f27-b999-d2b7de065531","sourceKey":"bank:GST111:GST111-0216","parentItemId":null,"revision":1,"payload":{"prompt":"Skimming can be classified under---------------","options":["preview before reading","none of the above.","review after reading","reading with intent"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Efficient reading has three stages: preview before reading, read with intent, and review after reading. Skimming gives you the overall idea and familiarises you with the content and organisation, so it belongs to the preview stage, which is why you should not start reading without skimming first. Option D (reading with intent) involves searching for key elements and highlighting, and C (review) comes after reading."}},{"itemId":"d9b765fc-bd84-51b0-a978-ca9df412d00b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f46c24d2-5bc9-543e-81ee-a32a0ca18bf2","sourceKey":"bank:GST111:GST111-0217","parentItemId":null,"revision":1,"payload":{"prompt":".............. is done to reduce the amount of items retrieved in advanced search","options":["Filtering","Exercises","Research","Simple search"],"correctOption":0,"section":"Search Strategies","explanation":"Filtering is what you do in an advanced search to refine for relevancy and reduce the number of items retrieved, using multiple search fields. Option D (simple search) does the opposite, often returning a huge amount of output, and B and C (exercises, research) are not search operations."}},{"itemId":"e3bc1f9e-bac2-50b6-890f-182653a58fb2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5b589e23-c8ae-520f-9a4d-91f9f7b23156","sourceKey":"bank:GST111:GST111-0218","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'challenge' when used as a noun or a verb is respectively stressed as----------------","options":["CHALlenge/chalLENGE","CHALlenge/CHALlenge","CHALLENGE/challenge","chalLENGE/CHALlenge"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"In this course, challenge is treated as an exception to the noun-verb stress rule: unlike EXport/exPORT or REcord/reCORD, it keeps the same stress pattern, CHALlenge, whether it is a noun or a verb. Options A and D wrongly assume the stress shifts between the two uses, and C has the wrong stress for both."}},{"itemId":"405dece0-55ca-591f-bae5-02ab48442d26","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1b5a5556-59d4-5340-9319-818fe7ee72df","sourceKey":"bank:GST111:GST111-0219","parentItemId":null,"revision":1,"payload":{"prompt":"If you stay in water too long, your fingertips will","options":["Shriveal","Shrivel","Shrivle","Shrival"],"correctOption":1,"section":"Vocabulary Development","explanation":"The correct spelling is shrivel, ending in -el, and it means to wrinkle and shrink, which is what fingertips do after a long time in water. Option A adds an extra a, C reverses the last two letters, and D wrongly ends in -al."}},{"itemId":"7f8cbb6f-c1ec-58ef-9e4c-4a084c6b220a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f879a12f-2570-5fb3-879d-8e6d19558c7a","sourceKey":"bank:GST111:GST111-0220","parentItemId":null,"revision":1,"payload":{"prompt":"Auxiliary verbs in English are classified into-------","options":["modal and main","primary and secondary","primary and modal","regular and irregular"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Auxiliary verbs are of two types: primary auxiliaries (have, be and do), which can also act as main verbs, and modal auxiliaries (can, will, shall, may, must), which never stand alone. Option A (modal and main) mixes an auxiliary type with main verbs, B (primary and secondary) invents a category, and D (regular and irregular) classifies verbs by how they form the past tense, not auxiliaries."}},{"itemId":"9e49fdce-19c9-52e5-95e9-0ab0b2a59e6e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c3858598-0322-598a-a174-067425d97b7f","sourceKey":"bank:GST111:GST111-0221","parentItemId":null,"revision":1,"payload":{"prompt":"The airstream that is used for the production of most English sounds is the ----------- ------ airstream.","options":["laryngeal","pulmonic","glottalic","velaric"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The lungs provide the airstream for most speech, and this air pushed out from the lungs is called the pulmonic egressive airstream. Option A (laryngeal) names where the vocal folds are rather than an airstream, while C and D (glottalic, velaric) are other airstream mechanisms used in some languages but not for ordinary English sounds."}},{"itemId":"7803ad25-e918-52a4-986d-e8a0e590c807","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c609e0b2-668b-5c56-94f2-835e77e294bf","sourceKey":"bank:GST111:GST111-0222","parentItemId":null,"revision":1,"payload":{"prompt":"Another word for data is......................","options":["Information","Fact","None of the above","Opinion"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Data means facts, or facts, figures or instructions in a form that can be processed, so another word for data is fact. Option A (information) is tempting, but information is data that has been processed to improve the user's knowledge, so the two are not the same. Option D (opinion) is a personal view, not raw facts."}},{"itemId":"0e45d117-5939-54c5-89ea-948605cb6c3c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"554a6181-ba1c-5386-8eae-02bad3b2cb43","sourceKey":"bank:GST111:GST111-0223","parentItemId":null,"revision":1,"payload":{"prompt":"The major components of a sentence are","options":["nouns and adjectives","the subject and the predicate","a main clause and a subordinate clause","independent clause and dependent clause"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"Every sentence has two major components: the subject, which names the person or thing being talked about, and the predicate, which says something about that subject, as in Birds (subject) fly (predicate). Options C and D (main/subordinate or independent/dependent clauses) describe how complex sentences are built, not the basic parts every sentence has, and A (nouns and adjectives) are word classes, not sentence parts."}},{"itemId":"9a900fdb-2868-5f45-a098-7475f9bada49","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0739b7ae-45dd-5686-8525-8ccac9a99056","sourceKey":"bank:GST111:GST111-0224","parentItemId":null,"revision":1,"payload":{"prompt":"Zero stress refers to:","options":["unstressed syllables","tertiary stress","secondary stress","primary stress"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Zero stress refers to unstressed syllables, such as the first syllable of about or the last syllable of mother. Polysyllabic words have three levels: primary, secondary and zero stress. Options C and D are the other two levels, which do carry some prominence, and B (tertiary) is not a level used in this course."}},{"itemId":"e1b47d18-e9d8-51b4-89b4-c32aad0c417f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5cb7bef8-4231-5bca-8186-cb7e4a06f860","sourceKey":"bank:GST111:GST111-0225","parentItemId":null,"revision":1,"payload":{"prompt":"Which stress level is marked with a subscript?","options":["secondary","zero","primary","tertiary"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Secondary stress is weaker than primary stress but stronger than an unstressed syllable, and it is marked with a subscript mark at the start of the syllable, as in the first syllable of millionaire or cigarette. Option C (primary) is marked with a raised stroke, B (zero stress) has no mark at all, and D (tertiary) is not a level used here."}},{"itemId":"379fdbcd-91ef-551f-ae00-7e5579de150d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7b961fb1-707b-5217-b4a8-dfcba4c4bda2","sourceKey":"bank:GST111:GST111-0226","parentItemId":null,"revision":1,"payload":{"prompt":"Faculty handbook is an example of small ready reference source","options":["Partially false","True","No","False"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The statement is true: a handbook is a small ready reference source that gives facts on places, techniques, institutions and subjects, and Faculty and Departmental Handbooks are standard examples. Options A, C and D all deny or partly deny that."}},{"itemId":"3e4c6e39-f26a-5450-8289-09fbc21d4b75","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b2e4237e-fd88-527c-b569-9164abe60b93","sourceKey":"bank:GST111:GST111-0227","parentItemId":null,"revision":1,"payload":{"prompt":"If neologism is taken to mean old words that have been given new meanings, which of the following is NOT an example of neologism?","options":["nice","lady","Waterloo","brunch"],"correctOption":3,"section":"Vocabulary Development","explanation":"Brunch is not an old word with a new meaning: it is a blend, made by joining part of breakfast to part of lunch. Nice, lady and Waterloo are all old words whose meanings have shifted, for example Waterloo, once just a place name, now also means a final defeat."}},{"itemId":"a0b57501-f385-53f6-aa35-1839ae284b3e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d69db7a2-e776-523a-a61c-425088fd1d78","sourceKey":"bank:GST111:GST111-0228","parentItemId":null,"revision":1,"payload":{"prompt":"One of the major benefits of using library databases is ............","options":["The fast internet speed","That they are subscribed to by the library to support students' assignments and research","All of the above","The value you get for your money"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"A major benefit of library databases is that they are designed by publishers or aggregators and subscribed to by the library to support student assignments and research, and they are more organised and easier to cite than general web results. Options A and D (internet speed, value for money) are not benefits of this kind, and C cannot be right since those two are wrong."}},{"itemId":"31316fe4-7a0f-5727-85a4-4d8819e00e78","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4042cb78-3034-5a3d-898b-dee8b5e8abca","sourceKey":"bank:GST111:GST111-0229","parentItemId":null,"revision":1,"payload":{"prompt":"Every complex word contains a/an --------------","options":["verb","noun","prefix","affix"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"A morphologically complex word is formed by adding an affix, a group of letters placed before (prefix) or after (suffix) the base, as in unrepentant, disloyal and endearment. So every complex word contains an affix. Option C (prefix) is too narrow, since a word like fairness is complex with only a suffix, and A and B (verb, noun) are word classes, not parts of a word."}},{"itemId":"dfafc578-7e1b-5812-8aaf-4b7f3b9e6f26","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7c491497-a550-5afc-af04-0d616625a886","sourceKey":"bank:GST111:GST111-0230","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following words contains three sounds?","options":["trust","cheap","frog","thoughts"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Cheap has three sounds because the ch is a single affricate consonant, as in church, followed by the long vowel in seat and then p. The other words have more: trust (A) has five sounds, frog (C) has four, and thoughts (D) has four (th, the vowel, t, s), so only B fits."}},{"itemId":"c86295a5-816a-5088-9b1b-4812f395a5b0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"65800c1e-7654-570f-95d3-1960ed07cd4a","sourceKey":"bank:GST111:GST111-0231","parentItemId":null,"revision":1,"payload":{"prompt":"In reviewing an item you have read, one of the following is not necessary.","options":["the annotated items","the heading","references","the highlighted items"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When you review material after reading, you pay attention to the heading, the highlighted or underlined items that point to the main ideas, and the annotated items in the margin. The author's references are not part of this review, so C is the one that is not necessary, while A, B and D are the three items you should look at."}},{"itemId":"e91f8b03-bf37-5d2c-9fd0-081dd81bdeaf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f4df54f9-9578-59c2-a7af-0be03fbe6b4d","sourceKey":"bank:GST111:GST111-0232","parentItemId":null,"revision":1,"payload":{"prompt":"Post-lecture activities include all the following except ------------","options":["review","summary","disposal","revision"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"After a lecture you should revise or review your notes quickly, compare them with course-mates, tidy up and fill in missing bits, and try a summary in your own words. Disposal means throwing the notes away, which defeats the purpose of note-taking, so C is the odd one out. Review, summary and revision (A, B and D) are all post-lecture activities."}},{"itemId":"bb8ed1d5-9a55-5286-a7f3-fd9a9a6a4056","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cb5dec09-5155-5aab-8764-6e46379a5cc4","sourceKey":"bank:GST111:GST111-0233","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a mark of a serious student?","options":["reading at a specific time and place","reading study materials anywhere","having a reading timetable","avoiding distractions while reading"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"A serious student plans study for a specific time at a regular place, draws up a reading timetable and avoids distractions, because a textbook, unlike a newspaper, needs a quiet, private area for understanding. Reading study materials just anywhere contradicts this, so B is not a mark of a serious student, while A, C and D are all good habits."}},{"itemId":"82ce778d-8477-58a2-baef-63289bb9134e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"aeedc51e-615d-50ad-833f-d95678d429a6","sourceKey":"bank:GST111:GST111-0234","parentItemId":null,"revision":1,"payload":{"prompt":"Noise is a ---------------- condition.","options":["physiological","physical","psychological","spiritual"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Noise is a physical condition, because it belongs to the environment, like a noisy or ill-ventilated room. Listening is hindered by physical conditions of the environment, physiological conditions of the speaker (A, such as speech defects) and psychological conditions of the listener (C, such as emotional state). Option D is not one of these categories."}},{"itemId":"90700180-f307-5967-9f43-78abdda09082","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"09cb970d-0376-53e9-abc7-107bfa033c68","sourceKey":"bank:GST111:GST111-0235","parentItemId":null,"revision":1,"payload":{"prompt":"In scanning a reading material. the reader seeks to --------------------","options":["get specific information","ensure grammaticality","have a general idea of the topic","check plagiarism"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"In scanning, your eyes run quickly through a text looking for a particular piece of information, ignoring everything not relevant to it, so A is correct. Option C (a general idea of the topic) describes skimming, not scanning, and B and D (grammaticality, plagiarism) are not purposes of reading at all."}},{"itemId":"c454b4e0-ae7c-59aa-8bef-cc3a086320b5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"25c7c38d-f128-5459-81b4-448eba5e2d92","sourceKey":"bank:GST111:GST111-0236","parentItemId":null,"revision":1,"payload":{"prompt":"3R stands for -----------------","options":["Read, Roll, Repeat","Read, Recite, Repeat","Read, Recall, Review","Read, Replay, Reharsh"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"The 3Rs in the SQ3R technique (Survey, Question, Read, Recall, Review) are Read, Recall and Review. Options A and D include steps such as Roll, Replay and Reharsh that are not part of the method. Option B is the closest trap because Recite is another name for Recall, but Repeat is not the third R."}},{"itemId":"7a70037d-502e-5ec9-bd63-bd2339001fbd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"38d76368-0375-5713-821b-6eadda45012f","sourceKey":"bank:GST111:GST111-0237","parentItemId":null,"revision":1,"payload":{"prompt":"A finite clause contains one of the following","options":["two or more verbs","no verb at all","a verb that changes","a verb that remains unchanging"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A finite clause contains a finite verb, a verb form that changes with number, person and tense (visit, visits, visited), so C is correct. Option D (a verb that remains unchanging) describes a non-finite clause, B (no verb) describes a verbless clause, and A (two or more verbs) is not a defining feature of any clause type."}},{"itemId":"7681df2f-868a-50d8-9f7f-a52da576b35f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3d29a02a-1549-569f-b82b-06f87111deee","sourceKey":"bank:GST111:GST111-0238","parentItemId":null,"revision":1,"payload":{"prompt":"The following are characteristics of information except .........","options":["Accessibility","News","Accuracy","Reliability"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The characteristics of good information are availability or accessibility, accuracy, reliability, timeliness and relevance. News is one form that information can take, not a quality it has, so B is the exception, while A, C and D are all characteristics."}},{"itemId":"a89d4747-54e3-55ce-ab3d-71c949536adc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ada00635-1da9-5a90-80c2-971f8f4d551d","sourceKey":"bank:GST111:GST111-0239","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"We bought John a guitar\", the phrase \" a guitar\" functions as-------- ?","options":["Object complement","Direct object","Indirect object","Subject complement"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"When a verb has two objects, the direct object answers what was bought, and the indirect object answers for or to whom. In We bought John a guitar, a guitar is what was bought, so it is the direct object, and John is the indirect object (option C). Options A and D (complements) would describe or rename the object or the subject, which a guitar does not do."}},{"itemId":"e3cdae64-f8e9-5867-8720-83a8d09097c0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9b4efcaa-43d2-5b30-889c-a13461d9c6d9","sourceKey":"bank:GST111:GST111-0240","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the lip positions used to describe English vowels?","options":["rounded","neutral","pursed","spread"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English vowels are described by three lip positions: spread (as in seat), neutral (as in cup) and rounded (as in food). Pursed is not one of these positions, so C is correct, while A, B and D are all genuine lip positions."}},{"itemId":"e28222ea-5f73-5b1a-96c3-9c32fc1ea374","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"00c759a0-7a1f-503f-86a5-8092adc2ad20","sourceKey":"bank:GST111:GST111-0241","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following does not describe a noun:","options":["can be in past or present tense","has a possessive form","can be singular or plural","can be proper or common"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Tense belongs to verbs, not nouns, so a noun is not something that can be in the past or present tense, and A is correct. A noun can take a plural, have a possessive form, and be proper or common, so B, C and D all describe nouns properly."}},{"itemId":"038fa583-a150-5793-9608-a52466b2a8bf","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"be9dc44f-51c2-5028-9db9-a0aa6c1fd1ed","sourceKey":"bank:GST111:GST111-0242","parentItemId":null,"revision":1,"payload":{"prompt":"The most commonly used citation style in Social sciences is ..............","options":["APA","MLA","Harvard","Chicago"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"APA (American Psychological Association) style is the one most commonly used to cite sources in the social sciences. Option B (MLA) is associated with composition and language courses, D (Chicago) with the humanities, and C (Harvard) is an author-date style popular with university students generally but not tied to the social sciences."}},{"itemId":"0586e333-9fba-5c11-8d28-f078d49a39b3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7571607e-0a72-5cdf-8e39-fa5d4f65f01c","sourceKey":"bank:GST111:GST111-0243","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT true of paragraphs?","options":["every paragraph begins with a topic sentence","they are of varying lengths","a paragraph is hardly ever longer than the entire essay.","the argument in a paragraph addresses only an aspect of the topic"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is often but not always the first sentence of a paragraph: it can come in the middle or at the end, and sometimes the main idea is so obvious that none is stated. So it is not true that every paragraph begins with one, and A is correct. Options B, C and D (varying lengths, shorter than the whole essay, addressing one aspect of the topic) are all true of paragraphs."}},{"itemId":"4ecb5974-d8b7-5c65-93ac-2f5635041546","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c1380980-a8b9-5618-aeb9-8b9d4dc1770b","sourceKey":"bank:GST111:GST111-0244","parentItemId":null,"revision":1,"payload":{"prompt":"Ranking of articles retrieved from databases is by ...........","options":["No of times the search was conducted","All of the above","The number of records","Date and relevance"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"Databases mostly rank results chronologically by date, with the most recent records first, and by relevancy, based on how often and how prominently the search terms appear in a record. Options A (number of times the search was run) and C (number of records) are not ranking methods, so B (all of the above) is also wrong."}},{"itemId":"d6884eec-7d2e-5e6c-bbe3-076d063a976e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"249c596b-c8e4-5050-8d0b-8cfc5ccad39d","sourceKey":"bank:GST111:GST111-0245","parentItemId":null,"revision":1,"payload":{"prompt":"Information can be in form of ................","options":["Numbers","All","Graphs& charts","Texts"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Information can take many forms: oral, textual, numeric, bibliographic, graphical (graphs and charts) and multimedia. Since numbers (A), graphs and charts (C) and texts (D) are all valid forms, the right answer is B, all of them. Picking any one alone leaves out the others."}},{"itemId":"95acfcb6-58bd-518b-ad72-b25d080ca3a5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"faaa2d3c-1d8a-5839-aaa6-ad6a28a54bd4","sourceKey":"bank:GST111:GST111-0246","parentItemId":null,"revision":1,"payload":{"prompt":"--------------- combines the manner of articulation of stops and fricatives.","options":["glides","vowels","affricates","nasals"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"Affricates begin like plosives (stops) and end like fricatives: the airflow is first blocked completely and then released gradually with friction, as in the first sounds of church and judge. Option D is wrong because nasals start with a closure but release air through the nose, and A is wrong because glides are approximants with no closure and no friction."}},{"itemId":"0be77796-3ee5-5a92-be86-cf3fb2a1e8e8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"aae46793-0997-5b20-8c8b-a0494b076235","sourceKey":"bank:GST111:GST111-0247","parentItemId":null,"revision":1,"payload":{"prompt":"The syllable in a word which has a --------------------- vowel quality usually attracts stress.","options":["high","strong","round","close"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A syllable with a strong vowel quality (a long vowel, diphthong or triphthong) tends to attract stress, while syllables with weak vowels such as the schwa are usually unstressed. Options A, C and D describe tongue height or lip shape, not whether a vowel is strong or weak, so they do not predict stress."}},{"itemId":"684c4b25-d966-5536-af2c-9cc2a4c5c731","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"527e7b7f-17d3-5012-9afa-efe1f2abf064","sourceKey":"bank:GST111:GST111-0249","parentItemId":null,"revision":1,"payload":{"prompt":"Which one of the following is a simple sentence","options":["Ngozi was at the scene, but she didn't witness the accident.","No smoking.","The boy killed the snake","The teacher asked a difficult question and no student could answer it."],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence makes a single statement with only one finite verb, and The boy killed the snake is exactly that. Options A and D are compound sentences, with two clauses joined by but and and. Option B, No smoking, is a minor sentence because it lacks a subject and a finite verb."}},{"itemId":"a8611fb6-bd23-54b0-8fb0-4486d86b9b00","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e767201a-2911-54ab-8c74-54d4bf59b1c9","sourceKey":"bank:GST111:GST111-0250","parentItemId":null,"revision":1,"payload":{"prompt":"The base word in \"Educational\" is","options":["educate","nal","Ed","duct"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Educational is built by affixation: the root educate takes the suffix -ion to give education, and then the suffix -al to give educational, so the base is educate. Options B, C and D are only fragments of letters or a suffix and cannot stand alone as words, so none of them is the base."}},{"itemId":"a510ad44-d0ef-5ae9-bc0c-96b7d96a2db7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bc391d14-739d-580a-b2b2-91e99ba4ddc5","sourceKey":"bank:GST111:GST111-0251","parentItemId":null,"revision":1,"payload":{"prompt":"Subject Searching allows one to ...........","options":["Browse from Library OPAC","Browse for items by subject","Browse for items by clause heading","Browse for items by phrase heading"],"correctOption":1,"section":"Search Strategies","explanation":"A subject search lets you browse for items by subject heading, returning only records where the term appears in the subject field. Option A is too general, since the OPAC can also be searched by title, author, series or keyword, and C and D name search types that do not exist."}},{"itemId":"352c6c4a-1191-5a5e-9f90-d5e8da5d05a6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b4e02ac1-4a95-5d09-bf8d-15d2df83aac4","sourceKey":"bank:GST111:GST111-0252","parentItemId":null,"revision":1,"payload":{"prompt":"Where information is not provided on time for the purpose for which it is required, it becomes ........","options":["Useful","Relevant","Relevant& useful","Irrelevant"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Timeliness is a quality of good information: it must be provided on time for the purpose it is needed for. If it comes late, it becomes irrelevant, so D is correct. Options A, B and C all describe good information, which is the opposite of what late information turns into."}},{"itemId":"dabf8379-3e7b-5386-a4f8-7e5c83cc578a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1643d598-908d-53eb-bbff-ec4e10e38acf","sourceKey":"bank:GST111:GST111-0253","parentItemId":null,"revision":1,"payload":{"prompt":"High vowels are also described as -------------------- vowels.","options":["long","rounded","open","close"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"When the tongue is held up close to the roof of the mouth, high vowels such as /i:/ and /u:/ are produced, and these are also called close vowels, so D is correct. Option C (open) is the opposite, since low vowels are open, and A and B describe length and lip shape, not tongue height."}},{"itemId":"5d64e72d-bc42-5cd1-b693-7084341e57d0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c23d5486-b9db-5e85-8555-7e87d2cd442c","sourceKey":"bank:GST111:GST111-0254","parentItemId":null,"revision":1,"payload":{"prompt":"Nouns can be subclassified in the following ways except one.","options":["Possessive and non-possessive","Concrete and abstract","Proper and common","Count and non-count"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Nouns are subclassified in three pairs: proper and common, count and non-count, and concrete and abstract. Possessive is a form that a noun can take (girl's, girls'), just as singular and plural are forms, so possessive and non-possessive is not a subclass. B, C and D are all genuine subclasses of nouns."}},{"itemId":"e64aa344-3b1f-51a0-b371-848921e152c7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"84816140-27be-5c1a-b4d2-6ea8847c5afa","sourceKey":"bank:GST111:GST111-0255","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not an imperative sentence","options":["Get out\\!","Look out\\!","Have a drink.","Oh, my goodness\\!"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Oh, my goodness! is an exclamatory sentence, expressing strong emotion, so it is not imperative. Get out!, Have a drink. and Look out! (A, C and B) are imperatives, because they command, invite and warn."}},{"itemId":"0c65d18b-5e9d-5e32-b737-c6e37db80b9b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"867ef24a-55ff-5f43-81a0-b0e95cac9a21","sourceKey":"bank:GST111:GST111-0256","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these letters of the alphabet cannot be found in the Library of Congress Classification Scheme?","options":["Letter G","Letter S","Letter C","Letter O"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"In the Library of Congress scheme, main classes are given letters of the alphabet, but O, X and Y are reserved for future expansion, so there is no Class O. Options A, B and C are all used: G is Geography and Anthropology, S is Agriculture and C is History."}},{"itemId":"d8123016-21cb-5fe9-a57c-2689e1b8e42e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"91ca97c5-5082-59ef-b161-813d249e65a3","sourceKey":"bank:GST111:GST111-0257","parentItemId":null,"revision":1,"payload":{"prompt":"Multimedia information pertains to the use of diversified medium of communication such as","options":["Text","Graphs","Audio-visual","Numbers"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Multimedia information uses a mix of media of communication such as audio, visual and audio-visual, so C is correct. Text, graphs and numbers (A, B and D) are each a single type of information, textual, graphical and numeric, rather than a mix of media."}},{"itemId":"dd0720fa-1d83-5b60-b442-73c0e641e5ec","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e4ef2fa4-5173-5eeb-bb77-a0a61c6754b0","sourceKey":"bank:GST111:GST111-0258","parentItemId":null,"revision":1,"payload":{"prompt":"Below are the steps involved in summarising a text; arrange them in the appropriate order. i. Express the contents of the text in your own words. ii. Read to find the basic ideas iii. Compare your summary with the original text. iv. Read to find the essentials.","options":["i, iii, ii, iv","iv, iii, ii, i","i,ii,iii,iv","ii, iv, i, iii"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"To summarise a text, you read to find the basic idea, read again to pick out the essentials, express the content in your own words, and finally compare your summary with the original, which is the order ii, iv, i, iii. Options A and C begin with writing the summary before reading, and B begins with the comparison, which can only come last."}},{"itemId":"bfa13ce1-1058-59db-910e-0a25c02067e3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c76a27e1-2b44-562b-aacf-4a1a160e9d85","sourceKey":"bank:GST111:GST111-0259","parentItemId":null,"revision":1,"payload":{"prompt":"A useful search tool for academic information is ..............","options":["Web crawler","Opera mini","Google scholar","Google"],"correctOption":2,"section":"Search Strategies","explanation":"Google Scholar is a useful search tool for academic information because it indexes scholarly materials such as books, patents, journal articles and conference papers. Option D (Google) is tempting, but ordinary Google searches the whole web with no selection for scholarly quality. A (web crawler) is a program that collects web pages and B (Opera Mini) is a browser, not a search tool."}},{"itemId":"ee4db8fb-89fe-5505-a1f4-a37a2da7fa7c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7e52ed47-c03e-5b20-9cdf-593cc69edc17","sourceKey":"bank:GST111:GST111-0260","parentItemId":null,"revision":1,"payload":{"prompt":"To avoid plagiarism, all used works must be ........","options":["Cited","Typed","Noted","Grouped"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"To avoid plagiarism, any work you use must be cited, through proper in-text citation and a reference list, so the original author gets credit. Typing, noting or grouping the works (B, C and D) does not credit the author and so does not prevent plagiarism."}},{"itemId":"4d3d60b7-7fb5-5394-9f47-fc86a0295115","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a29e5d89-415e-5640-a111-e794d606a41c","sourceKey":"bank:GST111:GST111-0261","parentItemId":null,"revision":1,"payload":{"prompt":"English stress is -----------------","options":["fixed","ordered","mixed","free"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"English stress is free, meaning it is not tied to one fixed position, so it can fall on the first, second, third or last syllable of a word, unlike languages where stress is fixed. Option A (fixed) is therefore the direct opposite of the right answer, and B and C are not terms used to describe stress systems."}},{"itemId":"7ee8e8f5-a621-5c3d-bf6b-29231eae3f9b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"adcaf318-513c-54be-ba81-7de12e9726b4","sourceKey":"bank:GST111:GST111-0262","parentItemId":null,"revision":1,"payload":{"prompt":"APA recommends that a book without an author should be cited in the text using .........","options":["The year of publication only","The publisher's name","The first few words of the title","The name of the library"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"When a book has no author, APA uses the first few words of the title in place of the author's name in the in-text citation, followed by the year. Option A is wrong because the year alone cannot tell the reader which source is meant, and B and D (publisher, library) are never used in place of the author."}},{"itemId":"2f1d3350-45f7-506c-b516-795be1edf079","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d2e88882-396b-523c-8cc9-dd8bc8f4101a","sourceKey":"bank:GST111:GST111-0263","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these does not belong in this group?","options":["Lagos","mathematics","John","Kaduna"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Lagos, John and Kaduna are proper nouns, each naming a particular place or person, and so they begin with capital letters. Mathematics is a common noun naming a general field of study, so B does not belong with the others."}},{"itemId":"9b8f9858-374b-5673-9911-11edd219d219","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"81edc4fe-8eaa-517a-86bb-e0f4307b91e2","sourceKey":"bank:GST111:GST111-0264","parentItemId":null,"revision":1,"payload":{"prompt":"Words that habitually go together, such as \"make a decision\" or \"heavy rain\", are known as","options":["continuation.","composition","connotation","Collocation"],"correctOption":3,"section":"Vocabulary Development","explanation":"A collocation is a group of words that habitually occur together, so we say make a decision rather than do a decision. Option C (connotation) is the feeling or association attached to a single word, not a word grouping, and A and B (continuation, composition) are not terms for words that go together."}},{"itemId":"f0edd660-9c17-5aa9-86a3-e6aa863cc641","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"02f13845-a329-55e7-a683-9312437cdc01","sourceKey":"bank:GST111:GST111-0265","parentItemId":null,"revision":1,"payload":{"prompt":"Which clause patterns is reflected in this sentence : Kofi became the president.","options":["SVOC","SVA","SVOO","SVC"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Kofi became the president follows the SVC pattern: Kofi is the subject, became is the verb, and the president is the subject complement because it refers to the same person as the subject. Option A (SVOC) would need an object as well as a complement, and C (SVOO) would need two objects, which this sentence does not have."}},{"itemId":"366a20b1-6154-54a1-9a83-f9068f4565fb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"502044e3-e00c-5da0-969c-897dfd403c6f","sourceKey":"bank:GST111:GST111-0266","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a compound noun?","options":["GREENhouse","black BIRD","an English TEAcher","white HOUSE"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Compound nouns carry stress on the first element, so GREENhouse (a glass building for plants) is a compound noun, whereas a green HOUSE, with stress on the second word, is just a noun phrase meaning a house that is green. Options B, C and D all stress the second element, which is the noun-phrase pattern."}},{"itemId":"57b8b289-ec76-53d4-9413-23985f39dd2e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0ecb93d3-2e70-5abb-81eb-d172afabecaf","sourceKey":"bank:GST111:GST111-0267","parentItemId":null,"revision":1,"payload":{"prompt":"An ............. is a summary of a publication or article","options":["Abstract","Anthology","Atlas","Index"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"An abstract is a summary of a publication or article that gives enough bibliographic detail to trace the original. Option D (index) only points to where information can be found, B (anthology) is a collection of writings, and C (atlas) is a book of maps."}},{"itemId":"362214fe-bd2f-594e-b6c3-772a60b878cb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"88c93f8f-3759-5176-9276-7044ec06c640","sourceKey":"bank:GST111:GST111-0268","parentItemId":null,"revision":1,"payload":{"prompt":"Advanced search allows you to limit your searches by:","options":["Size of book","Year of publication","Number of pages","Volume of book"],"correctOption":1,"section":"Search Strategies","explanation":"Advanced or field searching lets you narrow a search by specific fields such as year of publication, language or author, so B is correct. Size, number of pages and volume (A, C and D) are not standard limiters in library databases."}},{"itemId":"c119b6cf-5a85-5d77-8af5-37ae7e49296e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8a1263f9-407d-52f3-87bf-f2fac671baa4","sourceKey":"bank:GST111:GST111-0269","parentItemId":null,"revision":1,"payload":{"prompt":"Listening is not the ability to ------------------ the meaning of what is being said.","options":["perceive","denounce","receive","decode"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Listening is the ability to receive, perceive and decode the meaning of what is being said. To denounce means to condemn publicly, which has nothing to do with taking in meaning, so B is the odd one out. A, C and D all describe parts of listening."}},{"itemId":"c4d3a19f-327b-5227-a4f4-010995ee402e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3d275286-6af3-543e-9169-c1f2f64c84dd","sourceKey":"bank:GST111:GST111-0270","parentItemId":null,"revision":1,"payload":{"prompt":"Notable reference collection includes all of these EXCEPT......................","options":["Facts sources","Dictionaries","Books","Encyclopaedia"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"General books are not part of the reference collection, because reference materials are not read from cover to cover the way books are. Notable reference collections include dictionaries, encyclopaedias, fact sources, biographies, indexes and abstracts, so A, B and D are all included and C is the exception."}},{"itemId":"61bbfc15-3787-56a6-98c9-49e32602ba33","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9426054a-e1f3-5548-8c58-bd10b5588a7e","sourceKey":"bank:GST111:GST111-0271","parentItemId":null,"revision":1,"payload":{"prompt":"-------------------- is not a bilabial sound.","options":["/b/","/p/","/m/","/f/"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Bilabial sounds are made with the two lips coming together, as in /p/, /b/, /m/ and /w/. The sound /f/ is labio-dental, made with the lower lip touching the upper front teeth, so D is not bilabial, while A, B and C are."}},{"itemId":"a094939b-eb75-5117-b4d1-3de9d4aee97d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fc57837c-4e66-5bd6-bced-9e76ba0322a9","sourceKey":"bank:GST111:GST111-0272","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"Mr. Dokunboh donated some books\", the phrase \"some books\" is the","options":["subject complement","indirect object of the verb","subject of the verb","direct object of the verb"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In Mr. Dokunboh donated some books, some books receives the action of the verb and answers the question what was donated, so it is the direct object. Option B (indirect object) would apply only to a receiver such as the school in donated some books to the school, and C is wrong because Mr. Dokunboh, not the books, performs the action."}},{"itemId":"24f503a9-7ded-56b7-8f62-e39dbfc9d419","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ab0d7d05-0631-5dd3-bd57-62800f987347","sourceKey":"bank:GST111:GST111-0273","parentItemId":null,"revision":1,"payload":{"prompt":"Stress prediction based on syllable structure is basically ----------------","options":["syntactic","morphological","phonological","semantic"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The phonological criterion predicts stress from the number of syllables in a word and their internal structure, especially whether they contain strong or weak vowels, so C is correct. Option B (morphological) is based on affixes and word parts, A (syntactic) is based on word class, and D (semantic) is about meaning, so none of them concerns syllable structure."}},{"itemId":"50092c88-7fd9-5e30-9c6d-1f354f7a0769","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"59ac2fa5-6f2c-5ee4-9abe-081c9409353d","sourceKey":"bank:GST111:GST111-0274","parentItemId":null,"revision":1,"payload":{"prompt":"When an adjective is placed before a noun, it is said to be in what position?","options":["Superlative","Comparative","Attributive","Positive"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"An adjective placed before the noun it qualifies, as in the beautiful woman, is attributive, whereas one linked to the noun by a verb, as in the food is delicious, is predicative. Options A, B and D (superlative, comparative, positive) are degrees of comparison, which describe the form of an adjective, not its position."}},{"itemId":"fef83a42-df19-5698-b234-8277245df066","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b46b585e-26c2-5c84-b1ac-34d98b619df8","sourceKey":"bank:GST111:GST111-0275","parentItemId":null,"revision":1,"payload":{"prompt":"In which of the following pairs does one word carry a negative connotation?","options":["brave / courageous","persistent / stubborn","brilliant / clever","kind / generous"],"correctOption":1,"section":"Vocabulary Development","explanation":"Connotation is the feeling attached to a word beyond its literal meaning. Persistent is approving, but stubborn suggests an unreasonable refusal to change, so pair B contains a negative word. In A, C and D both words carry a positive feeling."}},{"itemId":"66a0201d-6d01-5e25-902e-cc561d2659f4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e59da3cc-9a6a-59b6-b9bd-ae70eba19bfa","sourceKey":"bank:GST111:GST111-0276","parentItemId":null,"revision":1,"payload":{"prompt":"----------------- words involve two or more independent words.","options":["compound","compound-complex","simple","complex"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Compound words are made of two or more words that can each stand independently, such as suitcase or blackboard. Option D (complex) is tempting, but a complex word contains an affix, as in unhappy, rather than two independent words. A simple word (C) has only one morpheme, and compound-complex (B) is a type of sentence, not a word type."}},{"itemId":"8b812dde-c087-5edc-8496-72ec81c62fd6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8ab2ff30-e12e-556d-8c9e-c3836cd49200","sourceKey":"bank:GST111:GST111-0277","parentItemId":null,"revision":1,"payload":{"prompt":"Grammar is broadly classified into----------","options":["lexis and structure.","morphemes and units","morphology and syntax","phonology and semantics"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Grammar is divided into morphology, the study of how words are formed, and syntax, the study of how words are arranged into phrases, clauses and sentences. Option D names phonology (the sound system) and semantics (meaning), which are other areas of language study, not branches of grammar. Option A is not the standard division, and B mixes a unit with a vague term."}},{"itemId":"b9d3664e-7c66-56a0-921d-27566175f764","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7ef0741e-5426-5cdf-8d97-d903b64d97a5","sourceKey":"bank:GST111:GST111-0278","parentItemId":null,"revision":1,"payload":{"prompt":"A passage written in a technical or difficult language is best read ------------------","options":["at a fast pace","at a slow pace","by scholars","by skimming it once"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Reading speed should match the difficulty of the passage, so a passage in technical or difficult language should be read at a slow pace to take in the unusual vocabulary. Option A (a fast pace) and D (skimming it once) would only give a rough idea and hurt understanding, and C is wrong because any reader can handle such a passage by slowing down."}},{"itemId":"a40b4504-a85c-53a6-8d0c-6472f97144d5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"447e0197-c221-562c-88e8-df836c08232a","sourceKey":"bank:GST111:GST111-0279","parentItemId":null,"revision":1,"payload":{"prompt":"The process of word formation where old words are given new meanings is called","options":["mixing","coining","blending","neologism"],"correctOption":3,"section":"Vocabulary Development","explanation":"Neologism here means the process in which old words are given new meanings, such as nice, which once meant pretending to be good and now means kind, or Waterloo, which now means a defeat. Option B (coining) creates a word for a specific use, and C (blending) joins parts of two words, as in smog, so neither gives an existing word a new meaning. A (mixing) is not a word-formation process."}},{"itemId":"17c5a7c8-771e-5fa3-a55a-611d71f82846","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6e23eb88-ede6-5eb6-82aa-b1e9f0f0c5f0","sourceKey":"bank:GST111:GST111-0280","parentItemId":null,"revision":1,"payload":{"prompt":"A comprehension passage is best understood when it is read -----------------","options":["more than once","thrice","once","twice"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"A comprehension passage is best understood when you read it more than once, with a quick first reading for the general idea and a slower second reading for details. Options B and D fix a specific number, but the advice is not limited to two or three readings, and C (once) goes against the advice completely."}},{"itemId":"71f70b19-5084-54ed-b19f-a6114377b95a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f9cfb631-fe37-56f5-920e-394f5c8bbc93","sourceKey":"bank:GST111:GST111-0282","parentItemId":null,"revision":1,"payload":{"prompt":"---------------- is the use of the rise and fall of voice pitch to convey meaning.","options":["intonation","stress","rhythm","intensity"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Intonation is the melody of speech: the rise and fall of pitch used to show meaning, such as whether a sentence is a statement or a question, or the speaker's attitude. Option B (stress) is the prominence of one syllable over others in a word, and C and D (rhythm, intensity) are not the names for meaningful pitch movement."}},{"itemId":"5890ba3f-8b3b-5586-828b-6da573b74755","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5e543fff-755e-5f86-bd67-3220f234dd48","sourceKey":"bank:GST111:GST111-0283","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is true?","options":["We read only for pleasure","None of the above","We read only for exams","We read for knowledge acquisition only"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"People read for many different purposes, from pleasure to serious ones like examinations and acquiring knowledge. Options A, C and D each use the word only, which makes each one false, so B (none of the above) is the only correct choice."}},{"itemId":"87d80267-7a91-54e9-a14f-876349fbb0f3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"46af9515-77f1-586f-860e-64cd059b46a3","sourceKey":"bank:GST111:GST111-0284","parentItemId":null,"revision":1,"payload":{"prompt":"What punctuation mark is used to express surprise?","options":["semi colon","full stop","exclamation mark","question mark"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, disappointment or any strong feeling. Option D (question mark) marks a direct question, B (full stop) ends an ordinary statement, and A (semi colon) separates clauses."}},{"itemId":"66b09479-9477-5d09-8a76-6d8e46c3afdd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6af6d653-ff8c-5c66-8b00-7469b86f3ae4","sourceKey":"bank:GST111:GST111-0285","parentItemId":null,"revision":1,"payload":{"prompt":"A thesaurus is a","options":["Specialised dictionary","simplified dictionary","pictorial dictionary","phonetic dictionary"],"correctOption":0,"section":"Vocabulary Development","explanation":"A thesaurus is a dictionary of synonyms, and it is classed among specialised dictionaries, alongside scholarly and usage dictionaries. Options B, C and D (simplified, pictorial, phonetic) are not categories under which a thesaurus belongs."}},{"itemId":"edac063f-a839-5086-87a0-fde7463017a0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a259b208-cedd-5177-904f-cc142decf91a","sourceKey":"bank:GST111:GST111-0286","parentItemId":null,"revision":1,"payload":{"prompt":"............ is when a researcher paraphrases correctly","options":["Unfair use","Academic theft","Plagiarism","Fair use"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Fair use allows copyrighted material to be used for academic purposes within limits, and paraphrasing correctly, with acknowledgment, is one of the skills that keeps a researcher within it. Option C (plagiarism) is using someone's work without acknowledgment, and A (unfair use) is copying indiscriminately, so correct paraphrasing is the opposite of both. Option B is not the term used."}},{"itemId":"e03f31a1-8424-5114-b30d-c0954325d8ab","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"13a959ad-8010-541b-84b8-1744c88d5745","sourceKey":"bank:GST111:GST111-0287","parentItemId":null,"revision":1,"payload":{"prompt":".................. is not a type of dictionary","options":["Subject dictionary","Anthem dictionary","General dictionary","Specialized dictionary"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The three types of dictionary are general dictionaries, specialised dictionaries and subject dictionaries. There is no such thing as an anthem dictionary, so B is the one that is not a type, while A, C and D are all real types."}},{"itemId":"1d1f38eb-1554-581c-85e9-4c227d46966a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b6d54188-d464-519b-bdba-7c2252f53c1e","sourceKey":"bank:GST111:GST111-0288","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements is not correct?","options":["noun phrases are stressed on the rightmost constituent","compound nouns are usually stressed on the first constituent","nouns are usually stressed.","function words are always stressed"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Statement D is incorrect because function words such as the, of and and are usually unstressed in connected speech, not always stressed. The other statements are correct: noun phrases are stressed on the rightmost element (A), compound nouns on the first element (B), and content words like nouns normally carry stress (C)."}},{"itemId":"8c0c2c93-031a-5e9b-9a91-d9c38fbd43af","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"46bfcc2b-3cdf-5cee-973a-517ec0657ada","sourceKey":"bank:GST111:GST111-0289","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence \"She hung onto his feet as if her life depended on it\", the clause \"as if her life depended on it\" is what type of clause?","options":["adverbial clause of manner","adjectival clause","relative clause of manner","verbal clause"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In She hung onto his feet as if her life depended on it, the clause as if her life depended on it modifies the verb hung by saying how she held on, so it is an adverbial clause of manner. Options B and C would need the clause to describe a noun, which it does not, and D is not a recognised clause type."}},{"itemId":"a196bd42-4148-5d71-951c-e1ee6a926579","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"42a6d6f7-bc22-5d7e-b8cc-5e2039b94a7a","sourceKey":"bank:GST111:GST111-0290","parentItemId":null,"revision":1,"payload":{"prompt":"When our eyes make a backward movement during reading, it is known as ---------- ----------","options":["clearing","backwarding","forwarding","regression"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Regression is glancing back to re-read words, phrases or sentences, usually because of poor concentration, and it is counted among bad reading habits. Options A, B and C (clearing, backwarding, forwarding) are not terms used for eye movement in reading."}},{"itemId":"1759aba0-79a8-5df7-9c1c-c57206dc11ae","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"03d24a8d-01ad-5c00-a445-3f4a08dc2378","sourceKey":"bank:GST111:GST111-0291","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following sentences makes use of an intransitive verb?","options":["My sister bought a car","The woman ate the food","Your house is too far.","The baby cried"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"An intransitive verb takes no object, and in The baby cried the verb cried has nothing after it receiving the action. Options A and B are transitive, since bought takes the object a car and ate takes the object the food. Option C uses the linking verb is with a complement, not an action verb without an object."}},{"itemId":"553d5cee-efc2-5d0b-a213-338e569e98b2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a010950e-250f-5c47-b37e-2dd1b6e38560","sourceKey":"bank:GST111:GST111-0292","parentItemId":null,"revision":1,"payload":{"prompt":"When keywords are embedded in quotes, the type of search performed is ..............","options":["Phrase search","Subject search","Boolean search","Basic search"],"correctOption":0,"section":"Search Strategies","explanation":"Phrase searching puts the keywords in quotation marks so the search engine returns only records where those words appear side by side in that order. Option C (Boolean search) uses operators like AND and OR, and B (subject search) searches the subject field, so neither depends on quotation marks."}},{"itemId":"1b37f8b4-5c41-5e56-9d11-eff7b5aeb891","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a2f152fa-264b-54d3-9a6e-f05ee80c498b","sourceKey":"bank:GST111:GST111-0293","parentItemId":null,"revision":1,"payload":{"prompt":"Enquiries on how to access any of the resources in a library can be made at the ........... Section","options":["Reference","Akintunde Ojo Building","Serials","Readers' Services"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Enquiries on how to access any of the library's resources are made at the Readers' Services point, so D is correct. Option B is a building, not a service point, and A (Reference) and C (Serials) are collections rather than the enquiry desk."}},{"itemId":"ed0aa8b5-aac0-514b-a85c-cf6134809e90","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3948e7e0-0aac-5ee7-b024-0590e7aed911","sourceKey":"bank:GST111:GST111-0294","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence 'The young lady thanked Mr Dokubo', the phrase 'Mr Dokubo' functions as a/an ...","options":["Complement","Indirect object","Qualifier","Direct object"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In The young lady thanked Mr Dokubo, Mr. Dokubo receives the action of the transitive verb thanked, which makes it the direct object. Option B (indirect object) would need a second object that the action is done for or to, and A (complement) would need the phrase to refer to the same person as the subject."}},{"itemId":"d499cf5b-fd26-557b-a0c7-1ef97986722f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b50a10e5-da12-5c87-98a5-37848f43b340","sourceKey":"bank:GST111:GST111-0295","parentItemId":null,"revision":1,"payload":{"prompt":"............. allows a User to apply multiple search fields","options":["Complex search","Quick search","Advanced search","Simple search"],"correctOption":2,"section":"Search Strategies","explanation":"Advanced search lets the user apply multiple search fields and filters to narrow down results. Options B and D (quick and simple search) use a single keyword box, and A (complex search) is not a recognised search type."}},{"itemId":"d10d56eb-e62b-5ede-946d-4433c6e4c6b1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"54db52ce-f50f-541a-b1bb-18300077f4bb","sourceKey":"bank:GST111:GST111-0296","parentItemId":null,"revision":1,"payload":{"prompt":"The various tools for accessing information are called ...............","options":["Information guides","Information keys","Information banks","Information retrieval tools"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The tools used to access information, such as library catalogues, the OPAC, indexes, abstracts and bibliographies, are called information retrieval tools. Options A, B and C (information guides, keys and banks) are not the terms used for these tools."}},{"itemId":"7298789f-bd72-5aa3-aca3-e232826d8de4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2d5fc16d-50e1-5bfb-b2c2-14ac4336cdcb","sourceKey":"bank:GST111:GST111-0297","parentItemId":null,"revision":1,"payload":{"prompt":"All of these are the advantages of using advanced search EXCEPT ...........","options":["Ability to filter search","Ability to reduce number of items retrieved","Ability to use multiple search fields","Ability to retrieve huge amount of information"],"correctOption":3,"section":"Search Strategies","explanation":"The advantages of advanced search are that you can apply filters, reduce the number of items retrieved and use multiple search fields. Retrieving a huge amount of information is what a simple search tends to do, not an advantage of advanced search, so D is the exception."}},{"itemId":"888aca7b-d21a-5df4-a34f-78f40b77daa6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"53a188a0-08bb-5030-a584-ae2d919e8696","sourceKey":"bank:GST111:GST111-0298","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following should not be capitalised?","options":["Gaelic","Chilean","Guesstimates","Guatemalan"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Gaelic, Chilean and Guatemalan are proper adjectives taken from the names of a language and nationalities, and proper nouns and their related forms take capital letters. Guesstimates is an ordinary common noun, so C should not be capitalised unless it begins a sentence."}},{"itemId":"3482b32d-41c7-5665-ac9e-77828d7b94f9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7408da0f-6b22-536a-ae1b-8d13d92304e0","sourceKey":"bank:GST111:GST111-0299","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the sentence that is incorrectly capitalised","options":["The nfl will repeat the best of the season this summer.","I'm going to be taking history next term.","Take a U-turn at that sign.","The PTA will fund our end-of-the-year party."],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Acronyms and initialisms such as UNICEF, FIFA and PTA are written in capital letters, so 'nfl' should be NFL, which makes A incorrectly capitalised. Option B is correct because ordinary school subjects such as history take a small letter, and C and D capitalise U-turn and PTA properly."}},{"itemId":"304df88d-3ed2-58ad-8742-37668e82f252","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8946dba4-403f-5ae8-a724-97d09cac33dc","sourceKey":"bank:GST111:GST111-0300","parentItemId":null,"revision":1,"payload":{"prompt":"When there are too few sources retrieved for a search, one can ............","options":["Use the AND Boolean operator","Combine synonymous terms with the OR Boolean operator","Use the NOT Boolean operator","None of the above"],"correctOption":1,"section":"Search Strategies","explanation":"When too few sources come back, you should broaden the search by combining synonymous terms with the OR operator. Options A and C (AND and NOT) do the opposite, since both narrow a search and are used when there are too many results."}},{"itemId":"99ef7691-5932-5899-9c25-f18692442dee","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d6f079fb-d8d5-53c6-8fce-89a216160cb4","sourceKey":"bank:GST111:GST111-0302","parentItemId":null,"revision":1,"payload":{"prompt":"The mnemonic -------------------- serves as a guide to productive study reading.","options":["LEARNER","REARER","REALER","NEARER"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"LEARNER is the mnemonic that guides productive study reading: Lay out the purpose, Examine all parts, Ask questions about each subheading, Read all materials on the topic, Note names, places and dates, Ease away from one subject before starting another, and Review before a test. Options B, C and D are not study-reading mnemonics."}},{"itemId":"eef380a3-4e12-5c7f-8fc6-c479c096780b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ab3973e9-2e66-5f64-926c-460e234b3e3b","sourceKey":"bank:GST111:GST111-0303","parentItemId":null,"revision":1,"payload":{"prompt":"An offence of self-plagiarism is said to have been committed if ..........","options":["None of these","You copy from your previous assignment for a new assignment without acknowledgment","You copy from your lecturer's handout without acknowledgement","You copy from the internet without acknowledgement"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Self-plagiarism happens when you copy from your own previous assignment for a new one without acknowledgment, because even your own earlier work must be cited. Options C and D describe ordinary plagiarism of other people's material, since the handout and the internet content are not your own work. Option A is wrong because B fits."}},{"itemId":"1da72242-44c0-56e2-9297-0ae79481e264","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e8207776-d936-592d-a9fb-ab110494d9c9","sourceKey":"bank:GST111:GST111-0304","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence: \"They came late because of the heavy rain\", the phrase the heavy rain is called?","options":["Verb phrase","Noun phrase","Adverbial phrase","Prepositional phrase"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The heavy rain is built around the head noun rain, with the determiner the and the adjective heavy describing it, so it is a noun phrase. Option D is tempting because the phrase follows because of, but the prepositional phrase is the whole group because of the heavy rain, while the heavy rain on its own is the noun phrase inside it."}},{"itemId":"f4ad6109-7509-5c74-bdac-b33b274b590d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0b88600f-86ca-5e3d-aab3-33bcc8eaf672","sourceKey":"bank:GST111:GST111-0305","parentItemId":null,"revision":1,"payload":{"prompt":"A/an ............ is a condensed version of an original work.","options":["preface","blurb","appendix","summary"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"A summary (also called a recap) is a condensed version of an original work, usually about one-third of its length. Option C, an appendix, adds extra material at the end of a work rather than shortening it, and A (preface) and B (blurb) are front-matter and back-cover texts, not condensed versions of the work."}},{"itemId":"1aef5324-b6a9-5dfc-ba89-2227d946e560","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"48b033b0-f41a-589c-8ee1-d2b16f339d2f","sourceKey":"bank:GST111:GST111-0306","parentItemId":null,"revision":1,"payload":{"prompt":"A verb which always occurs with an object is a/an \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ verb.","options":["intransitive","primary auxiliary","transitive","modal auxiliary"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"A transitive verb lets the action pass from the subject to an object, as in The man shut the door, so it always occurs with an object. Option A (intransitive) is the opposite, with no object, and B and D are helping verbs that accompany main verbs rather than taking objects themselves."}},{"itemId":"594ac9f4-6753-560a-93e4-9deca64c1f05","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fd7e62fc-cd7a-54c4-b33f-e2bd3c6f51ab","sourceKey":"bank:GST111:GST111-0307","parentItemId":null,"revision":1,"payload":{"prompt":"Parentheses are used to enclose\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ within a sentence","options":["added words to a quote","spelling errors","additional or explanatory information","slang"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Parentheses mark off additional or explanatory information within a sentence, something the sentence still makes sense without. Option A describes square brackets, which enclose words someone else adds to a quotation. Spelling errors and slang (B and D) are not what parentheses are for."}},{"itemId":"c5f3e87e-b421-56d1-9677-7d0ed9f7356a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5e4682b1-049b-5be1-a73c-9b3c1ec073ad","sourceKey":"bank:GST111:GST111-0308","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not necessary to make a syllable prominent.","options":["length","voice","pitch","loudness"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Four factors make a syllable prominent: loudness, length, pitch and vowel quality. Voice, meaning vocal fold vibration, is what separates sounds like /b/ and /p/, and it is not a feature of stress, so B is not necessary. A, C and D are all prominence factors."}},{"itemId":"87a4a598-0a7d-5df8-98e7-ebd90921792e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5cbfcf1a-b3bd-5242-a79b-753bcde00408","sourceKey":"bank:GST111:GST111-0309","parentItemId":null,"revision":1,"payload":{"prompt":"The use of keywords to perform quick information search is known as ............","options":["Simple search","Complex search","Meta search","Advanced search"],"correctOption":0,"section":"Search Strategies","explanation":"A simple search uses a few keywords to carry out a quick information search in a database or search engine. Option D (advanced search) involves filters and multiple fields, and C (meta search) uses several search engines at once, so neither is the quick keyword search described. Option B is not a recognised type."}},{"itemId":"3de4c55b-e8b4-5844-84b5-7cf312921e72","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"847031ca-dd26-545f-b29a-e96b4c1bb74b","sourceKey":"bank:GST111:GST111-0310","parentItemId":null,"revision":1,"payload":{"prompt":"Biographical sources are reference materials that provide individual information such as .....","options":["All of these","Date of birth","Place of birth","Career achievements"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Biographical sources give information on individuals such as date of birth, place of birth, education and career. Since B, C and D are all things they provide, A (all of these) is the complete answer, and picking one alone leaves out the others."}},{"itemId":"e7c66cc2-e5a6-5a42-9bca-cd28e7fdb40d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bcffb4b3-4558-5bcc-9dbb-348b00169310","sourceKey":"bank:GST111:GST111-0311","parentItemId":null,"revision":1,"payload":{"prompt":"The ------------------ is the only compulsory element in a syllable.","options":["vowel","verb","consonant","noun"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A syllable has an onset, a peak and a coda. The onset and coda (consonants) are optional, while the peak, which contains a vowel, is compulsory, so A is correct. Option C is wrong because a syllable like I or eye has no consonant at all, and B and D are word classes, not parts of a syllable."}},{"itemId":"3ceb5e4b-e444-5606-a15f-164e8b82c7eb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"861112ae-1bff-56a8-bcf7-e1fd41b888dc","sourceKey":"bank:GST111:GST111-0312","parentItemId":null,"revision":1,"payload":{"prompt":"The grammatical elements will, shall, could, should can and may are known as ----- --------","options":["Transitive verbs","Main verbs","Intransitive verbs","Modal auxiliaries."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Will, shall, could, should, can and may are modal auxiliary verbs, helping verbs that cannot stand alone but combine with main verbs to express ability, permission or obligation. Options A and C classify main verbs by whether they take an object, and B is wrong because modals are helping verbs, not main verbs."}},{"itemId":"b7942d59-f20d-58c4-a739-ef488a2d19be","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c67e6d5a-3643-5047-a567-3abd3d6cdaea","sourceKey":"bank:GST111:GST111-0313","parentItemId":null,"revision":1,"payload":{"prompt":"Effective use of the library resources requires ...............","options":["Punctuality","Search strategies","Smartness","Maturity"],"correctOption":1,"section":"Search Strategies","explanation":"Effective use of library resources requires search strategies, which is the art of planning and conducting searches to get the most efficient result. Punctuality, smartness and maturity (A, C and D) are personal qualities that do not by themselves help you find information."}},{"itemId":"71685ef9-7bdd-5271-9009-d146dad06fb9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"52dc36cc-6938-5cda-b746-010dadc359be","sourceKey":"bank:GST111:GST111-0314","parentItemId":null,"revision":1,"payload":{"prompt":"In relation to the tools used by examiners to test the candidates' understanding, the following question types can be identified except ....","options":["supposition question","evaluation question","affirmation question","inference question"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Comprehension questions fall into four categories based on the tools examiners use: direct reference, inference, supposition and evaluation questions. There is no affirmation question among them, so C is the exception, and A, B and D are genuine types."}},{"itemId":"01c2357d-9c2a-5227-b531-38c86cb5c82d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7de02e25-0d16-5faa-bb73-89516242ac36","sourceKey":"bank:GST111:GST111-0315","parentItemId":null,"revision":1,"payload":{"prompt":"Africana collection is found in ...............","options":["Serials","Gandhi Library","Reserved collection","Reference collection"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"At the University of Lagos Library, the Africana collection is housed in the Research and Bibliographic Department, known as the Gandhi Library, in the basement of the main library. Options C and D are separate collections on the ground floor, and A (Serials) is the collection of journals and periodicals."}},{"itemId":"2099c6c6-d16a-5219-8a08-a395f5cd82a4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c42f49aa-ff5c-5b40-b0ad-acac398b0230","sourceKey":"bank:GST111:GST111-0316","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a secondary source of information?","options":["Digest","Textbooks","Encyclopaedias","Thesis"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"A thesis is a primary source: it is original research produced by the researcher and counts as grey literature. Textbooks, encyclopaedias and digests (B, C and A) compile, explain or review other people's work, which makes them secondary sources, so D is the one that is not secondary."}},{"itemId":"240b5255-1ead-5f09-ada5-9a359b8454c9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"918405c9-4664-5ab2-9bf1-69589f5017a3","sourceKey":"bank:GST111:GST111-0317","parentItemId":null,"revision":1,"payload":{"prompt":"---------------------, according to experts, produces the strongest effect on stress placement than all the other features.","options":["length","loudness","pitch","vowel quality"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Pitch produces the strongest effect on stress placement of all the prominence factors, so C is correct. Length (A), loudness (B) and vowel quality (D) also contribute to prominence, but none is as powerful as a noticeable change in pitch."}},{"itemId":"c2c7ad20-5a32-56ab-9aaa-30e8e9b664c3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5d47d3c7-0023-5a39-bc45-7136f5b5cd3c","sourceKey":"bank:GST111:GST111-0318","parentItemId":null,"revision":1,"payload":{"prompt":"Electronic resources allows for ............ usage of resources at the same time","options":["Multiple","Restricted","Single","Complex"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic (non-print) resources allow multiple people to use the same material at the same time, unlike a printed book that only one person can hold at once, so A is correct. Option C (single) describes how a print copy is used, and B and D do not describe this feature."}},{"itemId":"44c2cacd-1c9d-5e72-b482-0943889a827c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7a93b03e-d6a9-599f-bee2-8c7b56aa7d44","sourceKey":"bank:GST111:GST111-0319","parentItemId":null,"revision":1,"payload":{"prompt":".............. is used to separate phrases and clauses in a series within a sentence when those items already contain commas.","options":["semi-colon","comma","colon","hyphen"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"When items in a series already contain commas, the semicolon separates them so the reader can see where each item ends, as in a list of names and their job titles. Option B (comma) is tempting, but more commas would make such a list confusing. The colon (C) introduces a list rather than separating its items, and the hyphen (D) joins words."}},{"itemId":"d5218beb-6cf2-581a-ad20-721f8b306a24","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"32d73142-ac34-5516-8f4e-27545c731c6d","sourceKey":"bank:GST111:GST111-0320","parentItemId":null,"revision":1,"payload":{"prompt":"Features which apply to units higher than the segments are known as ---------","options":["hierarchicals","phonologicals","segmentals","suprasegmentals"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Features such as stress and intonation operate on the syllable and beyond, not on individual consonant and vowel segments, so they are called suprasegmentals, meaning above the segments. Option C (segmentals) refers to the individual sounds themselves, and A and B are not terms used in phonology for this."}},{"itemId":"f3386444-a32c-5d21-ad30-b38427db6313","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d32bb005-9eb4-5f16-be4a-184bde823d65","sourceKey":"bank:GST111:GST111-0321","parentItemId":null,"revision":1,"payload":{"prompt":"The ------------ criterion for stress prediction takes the internal structure of the word into consideration.","options":["syntactic","phonological","semantic","morphological"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The morphological criterion for stress looks at the internal structure of a word, whether it is simple, compound or complex and what affixes it carries, so D is correct. Option B (phonological) looks at syllable and vowel structure, A (syntactic) looks at word class, and C (semantic) is about meaning, so none of them is about the word's internal make-up."}},{"itemId":"176f1ab1-dca3-5458-aeb9-c3d8a0c8b13e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"04e9c801-1040-5171-b334-af1d0d8502c4","sourceKey":"bank:GST111:GST111-0322","parentItemId":null,"revision":1,"payload":{"prompt":"The prominence of one syllable over other syllables in a word is a function of ...","options":["Stress","pitch","length","intensity"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress is the relative prominence of one syllable over the others in a word, so A is correct. Pitch, length and intensity (B, C and D) are the features that create that prominence, but the prominence itself is what we call stress."}},{"itemId":"16fd1077-2aee-5aa6-94f9-dd2494db9c13","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"346e4603-42fb-5213-95ff-5c1180b02cc0","sourceKey":"bank:GST111:GST111-0323","parentItemId":null,"revision":1,"payload":{"prompt":"Which tense do you use when you want to say that something is happening at the time you are speaking or writing","options":["present perfect tense","future tense","present tense","present continuous tense"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The present continuous tense is used for something happening at the time you are speaking or writing, and it is formed with be plus the -ing form, as in I am dancing. Option C, the simple present, is for habits and regular events, A (present perfect) links a past action to the present, and B (future) looks ahead."}},{"itemId":"bc8be633-a05e-5871-923f-ba5edd922a2c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9631de0f-3c67-5aec-8e7e-7bfd17d3789e","sourceKey":"bank:GST111:GST111-0324","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not involved in vowel articulation","options":["tongue movement","lip shaping","length","contact"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are produced with no obstruction to the airflow, so the articulators do not touch each other; that is why contact (D) is not involved in vowel articulation. Contact belongs to consonants. Tongue movement, lip shaping and length (A, B and C) are all used to describe vowels, so they are not the odd one out."}},{"itemId":"f2e829cc-5bc2-573b-8f11-cbe22236173b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"58421205-5319-5ad7-b203-ada624dbf485","sourceKey":"bank:GST111:GST111-0325","parentItemId":null,"revision":1,"payload":{"prompt":"The words tall, taller, tallest are examples of what kind of adjective?","options":["Concrete and abstract","Active","Non-gradable","Gradable"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Tall, taller, tallest shows an adjective that can be expressed in degrees, just like big, bigger, biggest or very big, so it is a gradable adjective (D). Option C, non-gradable, is the opposite: it covers absolute qualities such as perfect, unique or fatal that cannot be graded. A and B are not classes of adjective."}},{"itemId":"e3d8387b-3a6f-5ce8-8341-33fa66575b8d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a3ee913f-e727-5489-be4b-de84dbe484f6","sourceKey":"bank:GST111:GST111-0326","parentItemId":null,"revision":1,"payload":{"prompt":"The biographical source 'International Who's Who' is an example of a/an ....... source.","options":["National and current","Universal & current","International and local","National & local"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"International Who's Who is a universal and current biographical source, because it covers notable people from all over the world and is kept up to date. Options A and D describe sources limited to one country, such as Africa Who's Who or Newswatch Who's Who. Option C, 'international and local', is not a category used for biographical sources."}},{"itemId":"be4fd60b-fa32-58bb-8361-d9e57727447b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3d3a4698-613a-55fe-ad01-7615f7d61280","sourceKey":"bank:GST111:GST111-0327","parentItemId":null,"revision":1,"payload":{"prompt":"In the word 'janitor', stress falls on the ------------------- syllable.","options":["initial","final","medial","none of the above"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Janitor is stressed on the first syllable, so it is said JAnitor, just like reason and message. That makes the answer initial (A). Options B and C would move the stress to -i- or -tor, which is not how the word is pronounced."}},{"itemId":"0704f8c3-4697-5ec3-80c2-95cc8b5859bb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e9e09774-9242-5efd-ae10-39653ca78fd7","sourceKey":"bank:GST111:GST111-0328","parentItemId":null,"revision":1,"payload":{"prompt":"A simple sentence occurring by itself can also be called","options":["glottal","colossal","clause","verbal"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence that stands by itself has one subject and one predicate, which is exactly what a clause is, so it can also be called a clause (C). Options A and B are not grammatical units at all, and verbal (D) describes a form of the verb, not a sentence."}},{"itemId":"b4b6125c-d8a0-52ae-a299-de21b8bf8d1b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6098f779-259a-5d2c-b2ef-dfb1a78bc2c6","sourceKey":"bank:GST111:GST111-0329","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in reading a passage is to ------------------ it.","options":["appreciate","edit","summarise","preview"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Previewing comes first: you skim the title, headings and opening lines to get an idea of what the passage contains before reading it properly. Summarising (C) only comes after you have read, and editing and appreciating (B and A) are not stages of studying a passage."}},{"itemId":"a7372d95-d22e-5762-9ad5-e4d0fff1d87c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"177b7224-8203-5000-b3f4-c26e86ad20cb","sourceKey":"bank:GST111:GST111-0330","parentItemId":null,"revision":1,"payload":{"prompt":"The thesis statement is to an essay what the ............... is to a paragraph.","options":["supporting details","topic sentence","introduction","conclusion"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The topic sentence states the main idea of a paragraph and acts as the thesis of that paragraph, just as the thesis statement carries the central idea of a whole essay. Option A, supporting details, backs up the main idea rather than stating it. Introduction and conclusion (C and D) are parts of an essay, not the single controlling sentence of a paragraph."}},{"itemId":"c3d0b6ef-1e25-5902-9503-6a47145f8b90","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1193c977-9ada-5f5b-b0eb-8ce9121b30ef","sourceKey":"bank:GST111:GST111-0331","parentItemId":null,"revision":1,"payload":{"prompt":"Directories, handbooks, yearbooks and almanacs are ............. sources","options":["None of these","Bibliographical","Geographical","Fact"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Directories, handbooks, yearbooks and almanacs are fact sources: reference materials that give facts on a wide range of current issues. Option B refers to lists of books and articles on a subject, and C covers maps, atlases and gazetteers, so neither matches these four."}},{"itemId":"317758a0-cfd5-5ddf-a902-2c8dc7b4879e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6128719f-3df3-5674-b915-0f3fdb22dbb3","sourceKey":"bank:GST111:GST111-0332","parentItemId":null,"revision":1,"payload":{"prompt":"A complex sentence has","options":["one independent clause and one or more dependent clauses.","one independent clause and one dependent clause","two independent clauses and one dependent clause","two independent clauses and one or more dependent clauses"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A complex sentence has one independent (main) clause and one or more dependent (subordinate) clauses, so A is correct. Option B is too narrow because a complex sentence may have more than one dependent clause. C and D describe sentences with two independent clauses, which are compound-complex sentences."}},{"itemId":"43ee4aaa-674d-5af1-ad62-ed1e5f4d6fdb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5b37c3f0-3e8a-5caa-ac8d-013d8cf5ce64","sourceKey":"bank:GST111:GST111-0333","parentItemId":null,"revision":1,"payload":{"prompt":"The abbreviation NEC in note-taking means --------------------","options":["Non-Essential Creatures","National Executive Council","Necessary","National Electoral Commission"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"In note-taking, NEC is a shorthand for 'necessary', in the same way that no. stands for number and gov for government. Options B and D read NEC as the initials of an organisation, but that is not its meaning when you are making notes."}},{"itemId":"d4f09b82-fa1d-5144-9ac8-7ae561af9f6c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"56ced0bf-bd3d-56e6-9f2a-8befd612d092","sourceKey":"bank:GST111:GST111-0334","parentItemId":null,"revision":1,"payload":{"prompt":"Bibliography refers to...................","options":["All of these","A list of the written sources of information on a subject","A list of books and articles that have been used by someone when writing on a subject","List of books, magazines, articles, etc. about a particular subject"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"A bibliography is a list of written sources of information on a subject, including the books and articles consulted while preparing a piece of work. Because B, C and D each express part of that definition, 'All of these' (A) is the best answer."}},{"itemId":"3565638f-1f97-58a0-8528-1f58e43c0944","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c718db12-c753-5706-af10-fe227a2e3148","sourceKey":"bank:GST111:GST111-0336","parentItemId":null,"revision":1,"payload":{"prompt":"A good essay should contain .....................","options":["predominantly short paragraphs","a variation of long and short paragraphs","predominantly one-sentence paragraphs","predominantly long paragraphs"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A good essay mixes long and short paragraphs. Too many short paragraphs make the writing choppy, while too many long ones make it boring, so variety improves the flow of ideas (B). Options A, C and D each rely mainly on one length, which is the problem to avoid."}},{"itemId":"ea41b9f5-2c6e-544c-93cf-50c4c852bed6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cd2611fe-9405-5c09-9d48-126150835d10","sourceKey":"bank:GST111:GST111-0337","parentItemId":null,"revision":1,"payload":{"prompt":"A/an ---------------- is a summary of a plot.","options":["prologue","synopsis","episode","storyline"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A synopsis is a summary of a plot, the kind of account you give when someone asks what a film or novel was about. Storyline (D) is the plot itself rather than a summary of it, and prologue and episode (A and C) are parts of a work, not condensed versions of it."}},{"itemId":"109d474b-58cd-594f-856f-19f21595fdb7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9443debb-c50f-585d-98d2-89cae73443b5","sourceKey":"bank:GST111:GST111-0338","parentItemId":null,"revision":1,"payload":{"prompt":"In scanning, the -------------------- can be very important.","options":["preface","index","foreword","topic sentences"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When you scan, you are hunting for one particular piece of information, so you use the table of contents or the index to find the relevant pages and then read only those. Preface and foreword (A and C) are introductory sections that help with skimming, not with locating a specific fact, and topic sentences (D) help you understand paragraphs rather than find a detail quickly."}},{"itemId":"c021204f-29f1-5e24-9384-4d1e62537886","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5d8778d2-dc10-5b97-b173-cc9cffab0c49","sourceKey":"bank:GST111:GST111-0339","parentItemId":null,"revision":1,"payload":{"prompt":"The part of a word to which other elements can be added is called--------","options":["Suffix.","Phrase.","Root or stem.","Prefix."],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"The root (or stem) is the part of a word to which other elements are attached; affixation adds prefixes and suffixes to a root word. Options A and D are the elements that get added, not the part they are added to, and B, a phrase, is a group of words rather than part of a word."}},{"itemId":"08a4cdd4-21f3-5e0e-a813-a58c49d413a0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"224f92e0-2fa4-5440-adce-f7faddc85ee9","sourceKey":"bank:GST111:GST111-0340","parentItemId":null,"revision":1,"payload":{"prompt":"How many basic clause patterns are there in the English simple sentence?","options":["4","7","8","6"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"There are seven basic clause patterns in the English simple sentence: SV, SVO, SVC, SVA, SVOO, SVOC and SVOA. So B is correct, and 4, 8 and 6 (A, C and D) are the wrong counts."}},{"itemId":"8e728f8c-e869-5b36-a1a5-da839714ac65","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"185f947c-907f-5337-91ff-a015479fc89b","sourceKey":"bank:GST111:GST111-0341","parentItemId":null,"revision":1,"payload":{"prompt":"The Boolean operator \"OR\" is used in a search to .............","options":["Differentiate words","All","Connect synonyms","Exclude words"],"correctOption":2,"section":"Search Strategies","explanation":"OR connects two or more similar concepts or synonyms and broadens a search, because any one of the terms can appear in the results. Option D describes NOT, which excludes words, and A does not describe any Boolean operator."}},{"itemId":"a5377a19-811f-5d92-a9b6-6ddcccdc86ca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bd236046-9e7a-5daa-af65-fd6b0eb7f208","sourceKey":"bank:GST111:GST111-0342","parentItemId":null,"revision":1,"payload":{"prompt":"Law books in the University of Lagos Library can be found in.............","options":["Class H","Class K","Class G","Class M"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Law books in the University of Lagos Library are found in Class K, because K is the Law class in the Library of Congress scheme the library uses. Options A, C and D are other classes: H is Social Science, G is Geography and Anthropology, and M is Music."}},{"itemId":"6221c869-665d-5852-83b9-1b88076cfb57","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2885ffc4-b0ab-5028-9b55-77806dee6228","sourceKey":"bank:GST111:GST111-0343","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence 'She walks briskly', the word 'briskly' is a/an ...","options":["adverb of frequency","adverb of manner","adverb of place","adverb of degree"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'She walks briskly', the word briskly tells how the walking is done, so it is an adverb of manner (B). An adverb of frequency (A) would tell how often, place (C) would tell where, and degree (D) would tell to what extent."}},{"itemId":"ea2e4d07-4257-519a-8504-d7bc4353cc35","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"34ccf606-b137-5646-8113-cfd38bcf2fd8","sourceKey":"bank:GST111:GST111-0344","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT necessary when writing an argument.","options":["the use of details","creation of a mental picture","none of the above","appeal to emotion"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Creating a mental picture is the aim of descriptive writing, which appeals to visual and sensory perception, so it is not needed in an argument (B). Argument or persuasive writing relies on the use of details and the appeal to emotion, which is why A and D are necessary and therefore not the answer."}},{"itemId":"8c58f9fd-0b1e-52d7-b0fa-cc84463b5a00","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"478eb235-e107-52ec-b494-b61a0eaf6932","sourceKey":"bank:GST111:GST111-0345","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following conditions does not affect listening.","options":["the physiological","the physical","the spiritual","the psychological"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Three conditions affect listening: the physical condition of the environment, the physiological condition of the speaker and the psychological condition of the listener. Spiritual conditions are not among them, so C is the one that does not affect listening, while A, B and D do."}},{"itemId":"552e479b-8cd7-52d7-aa90-7b84f2c1d67d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"96cd83e1-d8c6-52ca-b60d-3ed1c7560dc2","sourceKey":"bank:GST111:GST111-0346","parentItemId":null,"revision":1,"payload":{"prompt":"We need to troubleshoot a paragraph in all the following cases except ..............","options":["when it is too long or too short","when there is a problem with its topic sentence","when it has multiple controlling ideas","when it has issues with transition within the paragraph"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph needs troubleshooting when its topic sentence is faulty, when it has multiple controlling ideas, or when its transitions are weak. Length alone is not a fault, because length does not decide what makes a paragraph, so A is the exception. Options B, C and D are all real reasons to troubleshoot."}},{"itemId":"fad5e2e2-b5d2-504d-bbe6-c719cd9f55de","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"917e2d55-9cc8-5e9b-9026-13925bdda230","sourceKey":"bank:GST111:GST111-0347","parentItemId":null,"revision":1,"payload":{"prompt":"Grammatical hierarchy in English is structured in which of the following ways?","options":["sentence, phrase, clause, word and morpheme.","morpheme, word, clause, phrase and sentence.","sentence, clause, phrase, word and sentence.","morpheme, word, phrase, clause and sentence."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The grammatical units rank from smallest to largest as morpheme, word, phrase, clause and sentence, so D is correct. Option A reverses the order, B wrongly puts the clause before the phrase, and C reverses the order and repeats 'sentence'."}},{"itemId":"40f6cf73-7c1d-56d5-8c4b-8f18b64e4ab3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2f61157e-d5db-52be-b5f4-05bfebe426b0","sourceKey":"bank:GST111:GST111-0348","parentItemId":null,"revision":1,"payload":{"prompt":"When a long word is shortened to make it less awkward in speech, it is said to be ...","options":["chopped","clipped","chipped","crimped"],"correctOption":1,"section":"Vocabulary Development","explanation":"Clipping is the shortening of long words that are awkward in everyday speech, as in exam from examination and phone from telephone. Chopped, chipped and crimped (A, C and D) are not terms for word formation."}},{"itemId":"98a495ce-c13f-5dc3-85c7-550a9065ec1e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"28be301a-79c4-516c-8424-ae4a9be76bc0","sourceKey":"bank:GST111:GST111-0350","parentItemId":null,"revision":1,"payload":{"prompt":"UNILAG students have remote access to UNILAG Library online resources via","options":["Matric number","The telephone directory","Hall of residence","UNILAG Library website"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"UNILAG students reach the library's databases and e-resources through the UNILAG Library website, using a password for some fee-based databases when connecting from outside the campus network. A matric number, the telephone directory and a hall of residence (A, B and C) are not gateways to the online resources."}},{"itemId":"deb67e75-062e-5cee-9a78-bdb94ec82f0c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"52207aed-8717-56c6-9d85-931da88e92aa","sourceKey":"bank:GST111:GST111-0351","parentItemId":null,"revision":1,"payload":{"prompt":"A research exercise must be ..............driven","options":["Strategy","Lesson plan","Subject/topic","Subject plan"],"correctOption":2,"section":"Search Strategies","explanation":"A research exercise must be driven by a subject or topic, because identifying the subject matter is the first step in a search strategy. Option A, strategy, is the overall plan built around the topic, and B and D are not terms used in this context."}},{"itemId":"edc22c91-59d3-50d3-bb74-31b4ecb953c8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ec90fe51-84ef-5934-8309-7cd65455038b","sourceKey":"bank:GST111:GST111-0352","parentItemId":null,"revision":1,"payload":{"prompt":"Reading for the purpose of gathering information that will translate to knowledge is also known as ---------------------","options":["study reading","exploring","scanning","skimming"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Study reading is the type of reading we do to gather information that will turn into knowledge in a specific area, so A is correct. Scanning and skimming (C and D) are quick reading techniques for finding specific facts or getting a general idea, not for deep learning. Exploring (B) is not a reading type."}},{"itemId":"328acfa9-ccbf-5d6e-872e-3fd2f39c281f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"366ca551-1950-58f4-8f02-b262e3e7e8a2","sourceKey":"bank:GST111:GST111-0353","parentItemId":null,"revision":1,"payload":{"prompt":"----------------- is the high, back tense vowel.","options":["/ɜ:/","/ɑ:/","/u:/","/i:/"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/u:/ is the high, back, tense vowel, heard in words like rule, food and who. Option D, /i:/, is also high and tense but it is a front vowel, A is a central vowel, and B is low and back."}},{"itemId":"b9ccf4f9-b0fa-5db7-90cb-21f88d127f6b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ec05a3bf-b1ba-59e9-85fe-48281f4b8259","sourceKey":"bank:GST111:GST111-0354","parentItemId":null,"revision":1,"payload":{"prompt":"............. is the act of using copyrighted work without permission or acknowledging the source.","options":["Dubbing","Copying and pasting","Plagiarism","Copying"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is using someone's work without permission or without acknowledging the source, and it is often described as academic theft. Copying and pasting, and copying (B and D) are actions that can lead to plagiarism but are not the name of the offence, and dubbing (A) means adding a new soundtrack to a film."}},{"itemId":"022b031f-8819-530d-b37d-d9cce23a99e7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f1b7cd69-4ca4-56bf-b4bf-b0750e8556ac","sourceKey":"bank:GST111:GST111-0356","parentItemId":null,"revision":1,"payload":{"prompt":"Any of these can be used as method of saving information materials retrieved from an electronic source EXCEPT \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["Email the document","Save the citation information/full text article","Memorise the source","Print the document"],"correctOption":2,"section":"Search Strategies","explanation":"Memorising a source leaves you no record to return to, so it is not a way of saving retrieved information (C). Catalogues and databases let you email, print or save the citation information and often the full text of an article, which is why A, B and D are all valid, and keeping a back-up copy is wise."}},{"itemId":"99a4d63c-e4ec-5e13-a95e-156efd080865","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0d964992-a0f8-52e8-af95-bc42154674a8","sourceKey":"bank:GST111:GST111-0357","parentItemId":null,"revision":1,"payload":{"prompt":"A three consonant onset obligatorily has -------------- as the first consonant.","options":["/k/","/s/","/t/","/p/"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A three-consonant onset always starts with /s/, followed by /p/, /t/ or /k/ and then /l/, /r/, /w/ or /j/, as in strike, square and sprite. So B is correct. Options A, C and D (/k/, /t/, /p/) are the sounds that can come second, not first."}},{"itemId":"fc3e6045-ca37-5b70-9287-5f3228bf726e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ff052c1b-c670-5f88-ba07-0e5fd71c6efa","sourceKey":"bank:GST111:GST111-0358","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence 'They lost some extremely valuable documents in the fire', the expression 'extremely valuable' is an example of a/an ...","options":["Adjective phrase","Noun phrase.","Prepositional phrase","Adverbial phrase"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'extremely valuable documents', the adjective valuable is the head word, modified by the adverb extremely, and the whole phrase describes the noun documents, so it is an adjective phrase (A). Option D is tempting because extremely is an adverb, but it is not the head of the phrase, and B would need a noun as the head."}},{"itemId":"ebb375ca-288e-541c-be2c-68d93f559685","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"92580dbe-d46e-5036-a3ea-eb6378c550af","sourceKey":"bank:GST111:GST111-0359","parentItemId":null,"revision":1,"payload":{"prompt":"In interpreting the results of experiments, .............. is/are often explored.","options":["empirical methods","critique","rationalisation","all of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"When interpreting the results of experiments, a combination of rationalisation, critique and empirical methods might be needed, so all three are explored and D is the complete answer. Options A, B and C each name only one of the three approaches."}},{"itemId":"660d5022-d168-5626-b019-a5a8f1c46c5b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"02cc3ab4-3a0f-59bf-b143-3feb1bec1abc","sourceKey":"bank:GST111:GST111-0360","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the reference style excludes the year of publication in the in-text citation?","options":["MLA","APA","MPA","Harvard"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"In MLA style, the in-text citation gives the author's last name and the page number, for example (McDonagh 80), with no year. APA and Harvard (B and D) are author-date styles that include the year, and MPA (C) is not a referencing style."}},{"itemId":"06810ffb-fe05-5174-9615-3e38ec893820","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"aef2fda9-ec6e-51f1-a842-56c766825ac7","sourceKey":"bank:GST111:GST111-0361","parentItemId":null,"revision":1,"payload":{"prompt":"Reference materials contain facts and rarely contain opinions.","options":["True","False","Partially true","Partially false"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The statement is true: reference materials mainly contain facts and rarely contain opinions, which is why we consult them for specific information instead of reading them from cover to cover. That rules out False (B) and the hedged options C and D."}},{"itemId":"74ea372b-4731-58d6-81d7-dc15c3293d4f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"73933141-fd30-5fec-a887-3ceb1c77e60f","sourceKey":"bank:GST111:GST111-0362","parentItemId":null,"revision":1,"payload":{"prompt":"Referencing is composed of two parts namely...................","options":["In-text referencing and reference list","Off-text referencing and referral list","Out-text referencing and bibliographies","On-text referencing and guide list"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Referencing has two parts: in-text referencing, which is the brief citation in the body of your work, and the reference list at the end, which gives the full details. So A is correct. Options B, C and D use labels that do not exist in any referencing style."}},{"itemId":"e8ecbf23-52a5-5d67-bb87-7652c2d6bbc8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9afce08b-75f7-509f-9108-d996ff2d1ad8","sourceKey":"bank:GST111:GST111-0363","parentItemId":null,"revision":1,"payload":{"prompt":"The URL of a website accredited to a post-secondary institution or institution of higher learning usually ends with ..........","options":[".com",".gov",".org",".edu"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The .edu ending is used only by accredited post-secondary institutions, so D is correct. The other endings are open to wider groups: .com (A) can be bought by anyone, .gov (B) belongs to government, and .org (C) is for organisations of any kind."}},{"itemId":"f51a989c-b3ad-5ef4-b03d-feaab246abf6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fbb0a276-e987-5320-94c4-6533988a501e","sourceKey":"bank:GST111:GST111-0364","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT a way of enhancing coherence.","options":["using transition words","using synonyms","repeating keywords","avoiding the use of pronouns"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Pronouns that refer back to nouns in earlier sentences help build coherence, so avoiding pronouns does not enhance it; it only makes writing clumsy and repetitive (D). Repeating keywords, using synonyms and using transition words (A, B and C) are all genuine ways of creating verbal bridges between sentences."}},{"itemId":"c102c03b-07f8-543b-ac44-13bab1f54601","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d0ba627d-7526-5583-8c07-fd9f896a35da","sourceKey":"bank:GST111:GST111-0365","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT true.","options":["through reading, you improve upon your listening skills","through reading, you diminish your speech ability","through reading, you enlarge your vocabulary","through reading, you improve your writing skills"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Reading builds your ability to speak rather than weakening it, so B is the false statement. Through reading you enlarge your vocabulary, which in turn improves your listening and writing, and the extra words and structures you meet also feed your speech. Options A, C and D are all real benefits of reading."}},{"itemId":"8bb9a0ca-b9af-5f52-b91c-dc90ffbe1124","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f14c5919-2cb7-5cb2-a727-e7b98e3fd07a","sourceKey":"bank:GST111:GST111-0366","parentItemId":null,"revision":1,"payload":{"prompt":"Analytical essays focus on the following except .............","options":["providing a sequential or chronological account","assessment of the implication for human existence","examination of the issue","identification of an issue"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Giving a sequential or chronological account of events is the defining feature of a narrative essay, not an analytical one (A). An analytical essay identifies an issue, examines it in detail and assesses its implications for human existence, which is why B, C and D all belong to analysis."}},{"itemId":"2ccaae01-8e73-5196-b41f-dae5d4bc4365","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"39de6457-2496-59be-b2f7-a149b5a7ee5f","sourceKey":"bank:GST111:GST111-0367","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a linking device:","options":["furthermore","however","finally","Because"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Because is a subordinating conjunction that joins a dependent clause to a main clause inside one sentence, so it is not a linking device in the sense of connecting paragraphs (D). Furthermore, however and finally (A, B and C) are linking devices that show how one idea continues from the one before."}},{"itemId":"419ecf6e-f6a4-5f9c-a875-896c8e82fc4f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"679a4634-663c-568d-8d27-9772e26de8fa","sourceKey":"bank:GST111:GST111-0368","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence 'Mr Dokunboh thanked the lady', the phrase 'the lady' is the ...","options":["direct object of the verb","indirect object of the verb","subject of the verb","object complement"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Mr. Dokunboh thanked the lady', the lady receives the action of the verb, so she is the direct object (A). Option C is wrong because Mr. Dokunboh, who does the thanking, is the subject. Option B, the indirect object, would answer 'to or for whom', and there is only one object in this sentence."}},{"itemId":"3d3f7f91-40a0-5172-8cba-d05b3366143e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1e3d4c5b-3ed6-5a38-8707-64b96bbfc45b","sourceKey":"bank:GST111:GST111-0369","parentItemId":null,"revision":1,"payload":{"prompt":"An index serves as .............. to required information","options":["Pointer","Indicator","Pointer and indicator","None"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"An index serves as both an indicator and a pointer to required information, giving a systematic guide to the contents of a book or text, so C is the complete answer. Options A and B each capture only half of the definition, which is why C is the best choice."}},{"itemId":"db1efbd5-a1af-5d58-869e-ee57c7af99c3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ea508d4d-e8b3-5746-8a9d-10a55f0583fa","sourceKey":"bank:GST111:GST111-0370","parentItemId":null,"revision":1,"payload":{"prompt":"Punctuation marks are used for the following except","options":["to separate subordinate idea from major ones in a sentence","to indicate stretches of direct speeches in a discourse","to indicate a writer's background","to show possessive case in proper and common nouns"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Punctuation marks organise and structure writing so it conveys the right meaning: commas separate subordinate ideas from main ones, quotation marks mark direct speech, and the apostrophe shows possession in nouns. Nothing in punctuation reveals a writer's background, so C is the odd one out, while A, B and D are real functions of punctuation."}},{"itemId":"6e80ea0e-9a51-5e39-ad51-83c726b896ce","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"19f0aeae-8b44-5b0b-aa87-afaa98d74788","sourceKey":"bank:GST111:GST111-0371","parentItemId":null,"revision":1,"payload":{"prompt":"The number generated when a library material is catalogued is called ...........","options":["Library number","Book number","Cataloguing number","Call number"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The number generated when a material is catalogued is the call number, also known as the call mark, which you need to find the book on the shelf. So D is correct. Library number, book number and cataloguing number (A, B and C) are not the technical term used in the library."}},{"itemId":"a352edde-747b-5e01-a4a7-0f2864dac63c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"71708183-dd13-587e-b394-376b85286588","sourceKey":"bank:GST111:GST111-0372","parentItemId":null,"revision":1,"payload":{"prompt":"A/an -------------- is a unit of any composition comprising a collection of related sentences dealing with a single topic.","options":["sentence","text","essay","paragraph"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph is a unit of composition made up of related sentences dealing with a single topic, so D is correct. An essay (C) is bigger, because it combines ideas from one paragraph to another. A sentence (A) is smaller than the unit described, and a text (B) is too general."}},{"itemId":"e4b66a0b-4e48-55ef-a8f9-65c7f7e9b2c9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e63deb75-ef32-58a3-ac8e-1f40fde5b308","sourceKey":"bank:GST111:GST111-0373","parentItemId":null,"revision":1,"payload":{"prompt":"In the sentence 'Tade travelled to Ibadan', the phrase 'to Ibadan' functions as an ...","options":["adverb of manner","adverb of place","adverb of frequency","adverb of time"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Tade travelled to Ibadan', the phrase to Ibadan tells where Tade travelled, so it is an adverb of place (B). It does not answer how (manner, A), how often (frequency, C) or when (time, D)."}},{"itemId":"5d25d69e-66b9-536c-bd61-6ceeb9ae9d94","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"39f2dd01-8de9-5b9a-b4b0-cf8861ab5f4b","sourceKey":"bank:GST111:GST111-0374","parentItemId":null,"revision":1,"payload":{"prompt":"Any information retrieved from the Internet can be considered accurate","options":["True","Partially true","False","Yes"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The statement is false: anyone with access can put false information online and there are no general rules on web accuracy, so information from the Internet must always be evaluated before you trust it (C). Options A, B and D all accept the claim in some form, which is risky."}},{"itemId":"1debca59-95a5-58f4-86da-f9fd2896d71b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c67a474a-8b2a-5fdf-b29d-4956fd5d5684","sourceKey":"bank:GST111:GST111-0375","parentItemId":null,"revision":1,"payload":{"prompt":"Lexical and functional morphemes are sub-groups of---------","options":["Free morphemes","stem words","root words","Bound morphemes"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Morphemes are first divided into free morphemes, which can stand alone as words, and bound morphemes, which must attach to a root. Free morphemes are then sub-grouped into lexical morphemes (content words like nouns, verbs and adjectives) and functional morphemes (grammar words like prepositions and conjunctions), so A is correct. Option D is wrong because bound morphemes are affixes such as prefixes and suffixes, and stems and roots (B, C) are not the parent category either."}},{"itemId":"8a29e30b-f7aa-595f-a697-1c343fa21cca","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e29f8982-0099-5f37-9d0e-c8a99dad83da","sourceKey":"bank:GST111:GST111-0376","parentItemId":null,"revision":1,"payload":{"prompt":"The following are search techniques EXCEPT..............","options":["Truncation","Boolean","Wild card","Filtering"],"correctOption":3,"section":"Search Strategies","explanation":"Filtering is not a search technique in its own right; it is something advanced searching does to reduce the number of items retrieved (D). The recognised search techniques are Boolean searching, parenthesis, phrase searching, truncation, wildcards and field searching, which is why A, B and C are not the exception."}},{"itemId":"dd2188ba-13ca-599a-9018-4fa61de64713","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3c1e3755-257d-527d-a056-dcab5c91fe08","sourceKey":"bank:GST111:GST111-0377","parentItemId":null,"revision":1,"payload":{"prompt":"Books on Sociology in the University of Lagos Library can be found in ........","options":["Shelf TA","Shelf HM","Shelf NA","Shelf HC"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library uses the Library of Congress scheme, where class H is Social Science and the sub-class HM is Sociology (General), so B is correct. HC is Economic History and Conditions, which makes D wrong, and TA and NA fall under Technology and Fine Art, not the social sciences."}},{"itemId":"7f22af26-ccfb-594c-98d3-7a22cd825a68","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a3c23934-c56c-55be-8ed5-ae737e8fb9bf","sourceKey":"bank:GST111:GST111-0378","parentItemId":null,"revision":1,"payload":{"prompt":"All of these are referencing styles EXCEPT ............","options":["MLA","NLA","APA","Harvard"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"APA, MLA, Harvard and Chicago are the main referencing styles, so A, C and D are all real styles. NLA is not a referencing style, which makes B the exception."}},{"itemId":"5e215187-584c-582e-a871-e35d6fbcc9e6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e97710ea-ec02-5c7e-9d1d-ed87adf41a4f","sourceKey":"bank:GST111:GST111-0379","parentItemId":null,"revision":1,"payload":{"prompt":"When you paraphrase a quote,","options":["you use your own words","you quote verbatim","you reuse it in another language","you use the exact words"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"To paraphrase is to express another writer's ideas in your own words. Options B and D describe quoting verbatim, which is the opposite of paraphrasing, and C, reusing it in another language, is translation, not paraphrase."}},{"itemId":"8a55053c-55e6-5d63-8cb3-03967b49248d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bbe25e00-d3f7-523e-a7a8-1d0be446602f","sourceKey":"bank:GST111:GST111-0380","parentItemId":null,"revision":1,"payload":{"prompt":"When using the American Psychological Association (APA) referencing style, the reference list should be arranged in ....... order","options":["Numerical","Chronological","Alphabetical","Citation"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"An APA reference list is set out in alphabetical order, using the author's surname, or the title when there is no author. Chronological order (B) is wrong because the date comes after the author, not first. Numerical order (A) belongs to numbered styles, not APA, and citation order (D) is not an APA rule."}},{"itemId":"7f213142-4358-52c3-80bc-ac0d4f315885","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8d02c381-4ddd-5049-a069-f799d54e13f7","sourceKey":"bank:GST111:GST111-0381","parentItemId":null,"revision":1,"payload":{"prompt":"University of Lagos Library has ..................library resources","options":["All of these","Print resources","Non-print resources","Audio-visual resources"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The University of Lagos Library has three categories of resources: print, non-print and audio-visual. Since all three are present, 'All of these' (A) is correct. Options B, C and D each name only one category, so each is incomplete on its own."}},{"itemId":"50e1d112-1b17-509b-a078-c7b91eac8e2e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6389d181-5be9-5ef7-8fac-82607cd5c192","sourceKey":"bank:GST111:GST111-0382","parentItemId":null,"revision":1,"payload":{"prompt":"Listening to a lecturer does not include -------","options":["watching out for non-verbal cues","observing illustrations and demonstrations","admiring his/her outfit and composure","listening to phonological cues"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Admiring the lecturer's outfit is a distraction created by dressing, not part of listening, so C is the answer. When listening to a lecturer you should watch for non-verbal cues, observe illustrations and demonstrations, and listen for phonological cues such as voice changes and stress, which are options A, B and D."}},{"itemId":"5077dced-5554-50ee-801d-3e9ae2abcde2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e65f97a9-0efc-5c6d-b761-cdf19ba00f5d","sourceKey":"bank:GST111:GST111-0383","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is a reading technique.","options":["STPQR","QRSTP","PQRST","RSTPQ"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"PQRST is a method of study reading, standing for Preview, Question, Read, Summary and Test, so C is correct. Options A, B and D just scramble the letters and do not match any study technique taught in this course."}},{"itemId":"7f93c03a-957c-5e2f-a572-e30ffd2eeca7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b5797702-e047-5fa5-aff1-b74053598446","sourceKey":"bank:GST111:GST111-0384","parentItemId":null,"revision":1,"payload":{"prompt":"The acronym 'OPAC' means ................","options":["Online primary access catalogue","Online Public Access Catalogue","Online private access catalogue","None"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"OPAC stands for Online Public Access Catalogue, the electronic version of the library catalogue, which can be searched by title, author, series and keywords. Options A and C change 'Public' to 'primary' or 'private', which is wrong because the catalogue is open to all library users."}},{"itemId":"14355f05-c545-5319-96e5-05b66e602105","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c1e6bb55-0bae-5e62-90c6-7dfbb1f00b0d","sourceKey":"bank:GST111:GST111-0385","parentItemId":null,"revision":1,"payload":{"prompt":"Vowel distinctions do not include:","options":["triphthongs","monophthongs","quadriphthongs","diphthongs"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English vowels are divided into pure vowels or monophthongs (12) and diphthongs (8), and triphthongs are also mentioned when discussing strong syllables. There is no class called quadriphthongs in English phonology, so C is the odd one out, while A, B and D are genuine vowel distinctions."}},{"itemId":"a66669ac-1a29-5df8-be09-ccff9b55d9ea","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cbd7f761-f2db-56b5-8e0d-6894a2cf26ec","sourceKey":"bank:GST111:GST111-0386","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following does not usually occur in unstressed syllables.","options":["syllabic consonants","short vowels","the schwa","diphthongs"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Diphthongs are strong vowels that attract stress, so they do not normally appear in unstressed syllables (D). The schwa and syllabic consonants usually occur in unstressed syllables, and weak syllables contain short vowels, which is why A, B and C are not the answer."}},{"itemId":"3e278491-f13a-52be-bbf3-d894d2241936","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"494f43e6-635c-5519-a368-bd7d5e222f6d","sourceKey":"bank:GST111:GST111-0388","parentItemId":null,"revision":1,"payload":{"prompt":"How many forms does state-of-being verbs and action verbs have","options":["5","7","2","9"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Apart from the verb be, which has eight forms, state-of-being verbs and action verbs usually have five forms: the base, the third person singular present, the past tense, the past participle and the -ing form. So A is correct. Two forms (C) is too few, while seven and nine (B and D) are more than any ordinary English verb has."}},{"itemId":"4f9f05a6-5ea0-566b-9c9d-be7628d8c9d2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2723a8da-f026-580c-9ccb-a7f9d8ade90a","sourceKey":"bank:GST111:GST111-0389","parentItemId":null,"revision":1,"payload":{"prompt":"The following are categories of resources in the library except .........","options":["Serials collection","Reserved collection","American collection","Africana collection"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The print collections of the University of Lagos Library are Africana, Reference, Reserved, Serials and Recent accessions. There is no American collection, so C is the odd one out, while A, B and D are genuine categories."}},{"itemId":"6c5fea54-6351-5b6d-b2dd-5d46833d8030","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"911fc4c8-1d20-5588-9a0b-5ea1fd4c59a3","sourceKey":"bank:GST111:GST111-0390","parentItemId":null,"revision":1,"payload":{"prompt":"--------------------- is not a bad reading habit.","options":["vocalisation","word-by-word reading","moving the head from side to side","havinga wide span of recognition."],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Having a wide span of recognition is a mark of a good reader, because the eyes take in several words at one fixation, so D is not a bad habit. Word-by-word reading, vocalisation and moving the head from side to side (B, A and C) are all reading deficiencies that slow you down and hurt comprehension."}},{"itemId":"9ca2ba05-9a4b-5a40-baa9-67d2b53360fa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4e0c6401-4ba4-5c20-b7f3-1dd221690d6d","sourceKey":"bank:GST111:GST111-0391","parentItemId":null,"revision":1,"payload":{"prompt":"Ability to locate, retrieve and evaluate information is known as.........","options":["Information support","Information asset","Information literacy","Information discovery"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Information literacy is the ability to locate, retrieve, evaluate and apply information, and to recognise when information is needed, so C is correct. Information discovery (D) sounds close but covers only finding information, not evaluating and using it. Options A and B are not terms used for this skill."}},{"itemId":"54015da9-fdee-559b-8261-80f6d1ba2171","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cbe5ec43-5a40-5f66-a4c3-58776b5ff436","sourceKey":"bank:GST111:GST111-0392","parentItemId":null,"revision":1,"payload":{"prompt":"Students are advised to maintain ---------------- contact with their lecturers during classes.","options":["eye","virtual","full","close"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Maintaining eye contact with your lecturer is the beginning of effective listening, because it links your mind with the speaker's and shows you are ready to process the message. So A is correct. Close contact (D) only suggests sitting near the lecturer, and virtual and full contact (B and C) are not the listening strategy being described."}},{"itemId":"cbe6384f-594e-5d01-968d-b9195eb4fa0f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"adb25553-f770-5bf3-94e2-83078187cbec","sourceKey":"bank:GST111:GST111-0393","parentItemId":null,"revision":1,"payload":{"prompt":"................. provide information on places and physical features","options":["Bibliographical source","None","Fact source","Geographical source"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Geographical sources provide information on places such as towns and countries and on physical features such as mountains and rivers; examples are maps, atlases, gazetteers and travel guides. Bibliographical sources (A) list books and articles, and fact sources (C) give facts on current issues, so neither deals with places and physical features."}},{"itemId":"060713df-aefb-5e48-b71e-4fc247d48098","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"47d4d577-8822-5b70-8442-bb287b185cca","sourceKey":"bank:GST111:GST111-0394","parentItemId":null,"revision":1,"payload":{"prompt":"The study of the arrangement of constituents within a sentence is called-------","options":["Grammar.","Syntax.","Graphology.","Morphology."],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Syntax studies how words are arranged and combined into phrases, clauses and sentences, which is exactly what the question describes (B). Grammar (A) is too broad, since it covers both how words are formed and how they are combined. Morphology (D) studies the internal structure of words, and graphology (C) deals with the writing system."}},{"itemId":"4c6b183e-9471-58eb-8e50-6233a0274eb5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dd05f964-dd1a-5359-aa47-6bef941a7174","sourceKey":"bank:GST111:GST111-0395","parentItemId":null,"revision":1,"payload":{"prompt":"\"Map of Nigeria\" and \"Travel guide\" are examples of ..................","options":["Biographical source","Fact source","Bibliography","Geographical source"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Maps such as the Map of Nigeria, atlases, gazetteers and travel guides are geographical sources, which give information on places and physical features (D). Option B, fact sources, covers directories, handbooks, yearbooks and almanacs, not places. Biographical sources (A) are about people, and a bibliography (C) is a list of publications."}},{"itemId":"3e3c9c12-b87f-58d0-9e95-6eaa33d37d3e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f7958842-2b89-5c3c-aa2f-9f2f34cd67f9","sourceKey":"bank:GST111:GST111-0396","parentItemId":null,"revision":1,"payload":{"prompt":"Collections published on Africa or African authors can be found in the University Library at the ........section","options":["Africana collection","Reserved collection","Serials","Reference collection"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Africana collections are print materials published on Africa by African and non-African authors, housed in the Research and Bibliographic Department (Gandhi Library), so A is correct. The reserved collection (B) holds rare and valuable materials across disciplines, serials (C) are periodicals, and the reference collection (D) holds dictionaries, encyclopedias and similar tools."}},{"itemId":"ed0a4879-f090-52fd-859d-f0aba00787d8","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e7a889d0-5592-52b6-b9ce-53c6e485ec9e","sourceKey":"bank:GST111:GST111-0397","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these words cannot be used to introduce an adverb clause?","options":["although","nevertheless","when","if"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"Nevertheless is a conjunctive adverb, which links two independent clauses of equal status rather than making one clause dependent, so it cannot introduce an adverb clause (B). Although, when and if (A, C and D) are genuine subordinating conjunctions that introduce adverb clauses."}},{"itemId":"09b2bae9-c3b9-5b10-925c-65958043ae50","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d39fa61d-9d5b-5d0d-b911-ee0c6e536ea5","sourceKey":"bank:GST111:GST111-0398","parentItemId":null,"revision":1,"payload":{"prompt":"Questions which require you to refer directly to the text are called ....","options":["supposition questions","inference questions","direct reference questions","evaluation questions"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Direct reference questions are those that require you to refer directly to the text, for example asking what the passage says about a topic (C). Inference questions (B) ask you to work out relationships between parts of the passage, supposition questions (A) take you beyond the passage, and evaluation questions (D) ask you to judge the writer's language and information."}},{"itemId":"fe2f90ae-cb15-564b-82e2-42c8feae3ff7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"535c1667-baa7-5839-b6b1-3fb3cbc6a693","sourceKey":"bank:GST111:GST111-0399","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Dokunboh thanked the lady. (Note: intended underline is \"the lady\")","options":["subject of the verb","object complement","indirect object of the verb","direct object of the verb"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Mr. Dokunboh thanked the lady', the lady receives the action of the verb, so she is the direct object (D). Option A is wrong because Mr. Dokunboh, who does the thanking, is the subject. Option C, the indirect object, would answer 'to or for whom', and there is only one object here."}},{"itemId":"f39ebf9a-76ab-513d-ada4-d02eed71d1c5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2f6ee549-d1b4-5e08-9135-dd39e082c1d4","sourceKey":"bank:GST111:GST111-0400","parentItemId":null,"revision":1,"payload":{"prompt":"Which clause patterns is reflected in this sentence : The man bought his wife a present.","options":["SVOO","SVOC","SVOA","SV"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'The man bought his wife a present', the man is the subject, bought is the verb, his wife is the indirect object and a present is the direct object, which is the SVOO pattern (A). SVOC (B) would need a complement describing the object, and SVOA (C) would need an adverbial of time or place, neither of which appears here."}},{"itemId":"eee7afb4-7365-5ee2-a908-94045c82f5aa","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"99e11cdf-0c9d-5d10-811a-ed6d119c0b7b","sourceKey":"bank:GST111:GST111-0401","parentItemId":null,"revision":1,"payload":{"prompt":"The ............... in a paragraph states the main idea in that paragraph and works as its summary.","options":["sentence","conclusion","punctuation","topic sentence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence states the main idea of a paragraph and works as its summary (D). Option B, conclusion, is wrong because the concluding sentence only closes the paragraph and is optional. A sentence in general (A) need not carry the main idea, and punctuation (C) is not a sentence at all."}},{"itemId":"6cc2473c-6fb3-5078-a064-4694e714fc4c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"652c5758-c0bd-5315-94a7-90acd66967a1","sourceKey":"bank:GST111:GST111-0402","parentItemId":null,"revision":1,"payload":{"prompt":"A paragraph is complete when it has ..............","options":["an initial capital letter and a a final full stop","none of the above","a topic sentence and supporting details","an argument"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph has a topic sentence (essential), supporting or detail sentences (essential) and a concluding sentence (optional), so it is complete once it has a topic sentence with supporting details (C). Option A describes the mechanics of a sentence, not a paragraph, and D is wrong because not every paragraph argues a point."}},{"itemId":"ecaa1a87-dac3-5895-939d-37c9993fdd1f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5094d574-20cb-58dd-b97e-4dd9ad287cc8","sourceKey":"bank:GST111:GST111-0403","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the imperative sentence below","options":["Take the bus home.","I don't believe that!","Did you take the bus home?","She walked quickly to the bus stop."],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"An imperative sentence gives a directive such as a command, instruction or piece of advice, usually with the subject 'you' understood, so 'Take the bus home.' is the imperative (A). Option B is an exclamatory sentence expressing strong feeling, C is an interrogative because it asks a question, and D is a declarative that simply makes a statement."}},{"itemId":"d78bc7c7-111f-5ade-bbd5-f45a39b5136f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"12535230-cf09-5655-974f-91e95b3bccce","sourceKey":"bank:GST111:GST111-0404","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these sentences has a plural compound subject","options":["The man and his wife were present.","Hot lemonade and honey is good for a cold.","The MD and Chief Executive Officer of the company was introduced","Waiter is the rice and beans ready?"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A compound subject joined by 'and' is plural, so 'The man and his wife' takes the plural verb were (A). In B, C and D the members are thought of as a single unit, such as one drink (lemonade and honey), one dish (rice and beans) or one person holding two titles, so those compound subjects are singular."}},{"itemId":"da71c2ec-1fc7-511e-a165-361755cb30fe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9df3dcaf-de34-5bea-8004-4b8269e388d2","sourceKey":"bank:GST111:GST111-0405","parentItemId":null,"revision":1,"payload":{"prompt":"Recalling stored information is enhanced by the following except ---------","options":["review","reproduction","repetition","recitation"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Recalling stored information is helped by repetition, recitation and review, which are all active ways of strengthening memory. Reproduction is just producing the information, for example in an exam, and does not improve recall, so B is the odd one out."}},{"itemId":"cb4d2f02-b9d2-5c59-b2d7-69a7cef07c13","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d8b21dd-ba4f-5e6d-80e8-a7b8a5167f26","sourceKey":"bank:GST111:GST111-0406","parentItemId":null,"revision":1,"payload":{"prompt":"Symbols used in phonetic transcription are adapted from -----------------","options":["PLA","APA","IPA","MLA"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"The symbols used to represent English sounds are adapted from the International Phonetic Association's alphabet, usually called the IPA (C). APA and MLA (B and D) are referencing styles, not phonetic systems, and PLA (A) is not a recognised source of phonetic symbols."}},{"itemId":"85c0734c-aa0a-594f-bf5f-90ba3aa8468b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"def3c8d4-cba2-5e9a-9fa4-b3205af339ed","sourceKey":"bank:GST111:GST111-0407","parentItemId":null,"revision":1,"payload":{"prompt":"The colon is used in the following situations except","options":["to introduce a list after words such as 'the following'","to introduce direct speech in some contexts","to join the parts of a compound word such as sister-in-law","to separate a title from its subtitle"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Joining the parts of a compound word such as sister-in-law is the job of the hyphen, not the colon, so C is the exception. The colon introduces a list, especially after 'the following' or 'as follows' (A), can introduce direct speech, as in Okon said: \"I am hungry.\" (B), and separates a title from its subtitle (D)."}},{"itemId":"722e229f-1bb0-57bf-a600-f7580fbd0f8d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9a477378-84e5-54f9-8e15-d4e6e5babf26","sourceKey":"bank:GST111:GST111-0408","parentItemId":null,"revision":1,"payload":{"prompt":"Citation is a skill that must be learnt ...........","options":["For Library usage","For information retrieval","For chatting online","For academic purposes"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Citation is a skill students must learn for academic purposes: to avoid plagiarism in an academic setting you must paraphrase correctly and acknowledge every source you use (D). Options A and B describe library skills rather than the reason for citing, and chatting online (C) has nothing to do with acknowledging sources."}},{"itemId":"dbc70a8a-0427-5d8f-8577-f14b8db84080","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"081a6b6a-c530-504b-a55c-27fe405547db","sourceKey":"bank:GST111:GST111-0409","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a Correlative conjunctions","options":["even...then","both...and;","neither...nor;","either...or;"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"The correlative conjunctions are both...and, either...or, just as...so, neither...nor, not only...but (also) and whether...or. 'Even...then' is not a recognised correlative pair, so A is the odd one out, while B, C and D are all genuine pairs."}},{"itemId":"1cfeb2e8-2805-5487-820c-a34e29e5730f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6a5ff15b-fca6-519b-a74f-4346708989dd","sourceKey":"bank:GST111:GST111-0410","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a basic clause pattern in the English simple sentence","options":["SVA","SVCC","SVOA","SVO"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"The seven basic clause patterns are SV, SVO, SVC, SVA, SVOO, SVOC and SVOA. SVCC is not one of them because a clause does not take two complements in this way, so B is the answer. SVA, SVOA and SVO (A, C and D) are all genuine patterns."}},{"itemId":"83b43841-fa4a-527b-a4ad-c73958749012","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2d1b4e8b-d950-5e40-8508-4022a28158f1","sourceKey":"bank:GST111:GST111-0411","parentItemId":null,"revision":1,"payload":{"prompt":"One can search the library catalogue for information materials using all EXCEPT .........","options":["Language","Title","Author","Subject"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"The manual catalogue is searched by author, title and subject, and the OPAC adds series and keywords. Language is not an access point of the library catalogue, so A is the odd one out, while B, C and D are standard ways of searching."}},{"itemId":"f50d10cd-07b1-570c-b469-8574e6d54689","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a5c78cf5-d001-5151-a238-831540333898","sourceKey":"bank:GST111:GST111-0412","parentItemId":null,"revision":1,"payload":{"prompt":"You will not experience much difficulty with a reading material if you ---------------","options":["follow the appropriate steps","find the style confusing","cannot connect with the author","find the topic uninteresting"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"You will not struggle much with a reading material if you follow the appropriate steps, such as previewing, reading with intent and reviewing (A). Options B, C and D are the usual causes of difficulty, namely a confusing style, not connecting with the author and an uninteresting topic, so they are the opposite of what the question asks for."}},{"itemId":"73dfbde3-a5f1-5f2c-81f4-62bed6465266","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2f3023e5-7b5b-58d5-b6d8-ffa6ffa8fa32","sourceKey":"bank:GST111:GST111-0413","parentItemId":null,"revision":1,"payload":{"prompt":"A Closed Access System of collection in a library refers to ...............","options":["Restricted access","Materials to be borrowed for home use","Materials to be retrieved directly by the user","Materials not to be photocopied"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"In a closed access system, users may not take materials from the shelves themselves; the desk officer fetches the material once the bibliographic details are given, so access is restricted (A). Option C describes the opposite, open access, and B and D are about borrowing and copying rules, not about how materials are accessed."}},{"itemId":"4c1fba54-ee4f-59dc-a71c-c2967e3f0094","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ab4c015a-fb5a-5ef0-b891-29b08987bb8d","sourceKey":"bank:GST111:GST111-0414","parentItemId":null,"revision":1,"payload":{"prompt":"A word usually has --------------- primarily-stressed syllable(s).","options":["2","1","3","4"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"In longer words there is usually just one primarily stressed syllable, possibly one more with secondary stress, and several unstressed ones. So a word normally has one primary stress (B). Options A, C and D give too many; extra prominent syllables carry secondary stress, not primary stress."}},{"itemId":"fd10ee1a-0159-5b1e-bdbe-41fc4101f9e0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"68ed30ce-8692-5afa-a94f-d969a71a8fbf","sourceKey":"bank:GST111:GST111-0415","parentItemId":null,"revision":1,"payload":{"prompt":"The __________ is used before a list of items","options":["colon","semicolon","period","question mark"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The colon introduces a list, especially after words like 'these', 'namely', 'the following' or 'as follows' (A). The semicolon (B) separates items within a list that already contain commas, but it does not introduce the list. The period (C) ends a sentence and the question mark (D) ends a direct question."}},{"itemId":"85bbe78e-a26d-5f34-963c-3da4a41281e1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4325a630-fcab-5c71-96e3-019b37be51c0","sourceKey":"bank:GST111:GST111-0416","parentItemId":null,"revision":1,"payload":{"prompt":"Prefixes and suffixes are generally known as ----------","options":["Affixation","Root","Stem","Affixes"],"correctOption":3,"section":"Vocabulary Development","explanation":"Prefixes and suffixes together are called affixes, groups of letters added before or after a base (D). Option A, affixation, is the process of adding them, not the name of the elements themselves, while root and stem (B and C) are the bases the affixes attach to."}},{"itemId":"4bf1fa47-32bb-5cb9-9ff3-12f1e2c64d78","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a4aa14eb-4e0c-5ac7-b407-0d41b2886c76","sourceKey":"bank:GST111:GST111-0417","parentItemId":null,"revision":1,"payload":{"prompt":"Fact sources at the University of lagos Library are housed at the ..........","options":["MTN Library","Boulos Library","Reference section","Automation Section"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Fact sources such as directories, handbooks, yearbooks and almanacs are reference materials, so they are housed at the reference section of the library (C). The MTN Connect Library (A) and the Automation Section (D) deal with electronic, non-print resources, and the Boulos Library (B) is not where fact sources are kept."}},{"itemId":"64bf5cd0-a0ae-5c0b-a311-e28997fb86da","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"74c2b51f-7ff7-553f-96b1-2fb92ae3e65f","sourceKey":"bank:GST111:GST111-0418","parentItemId":null,"revision":1,"payload":{"prompt":"During lectures, we engage in ------------------- listening.","options":["informal","formal","total","partial"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Formal listening takes place in formal or academic settings, so during lectures we engage in formal listening (B). Informal listening (A) happens in everyday conversation and helps relationships. Total and partial listening (C and D) are not recognised types of listening."}},{"itemId":"b0b67f4e-34a9-5684-87e9-559a1186e1e3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"061cc758-c79f-5c23-995e-6d84c68e286b","sourceKey":"bank:GST111:GST111-0419","parentItemId":null,"revision":1,"payload":{"prompt":"The lungs are housed in the -------------------------","options":["spinal cord","pharynx","larynx","rib cage"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"The lungs are sponge-like tissues housed in the rib cage, and they provide the airstream used for speech (D). The larynx (C) is tempting because it is part of the airway, but it houses the vocal folds, not the lungs. The pharynx (B) is part of the throat above the larynx, and the spinal cord (A) is part of the nervous system."}},{"itemId":"a07f623d-fa27-5717-87fa-4236881becb2","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6306f6a3-0ff9-59e7-9f52-02f1e8fd8895","sourceKey":"bank:GST111:GST111-0420","parentItemId":null,"revision":1,"payload":{"prompt":"The man jogs regularly.","options":["adverb of place","adverb of time","adverb of manner","adverb of frequency"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'The man jogs regularly', the word regularly tells how often the man jogs, so it is an adverb of frequency (D). Manner (C) would answer how, time (B) would answer when, and place (A) would answer where."}},{"itemId":"c6d2a5fd-9cbf-5e39-b26d-d0d0c1d620b3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6de998bb-865d-5faf-8385-3bac7cba8655","sourceKey":"bank:GST111:GST111-0421","parentItemId":null,"revision":1,"payload":{"prompt":"Types of libraries include all of these EXCEPT ..................","options":["Public","Special","Reserved","Academic"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Public, academic and special libraries, along with school and private libraries, are types of library. Reserved (C) is not a type of library but a collection within a library, holding valuable and rare materials on closed access. A law or court library, for example, is a kind of special library (B)."}},{"itemId":"3217e60b-f949-5695-b98a-ede6b51ee71e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a153031c-2142-51cf-a0a7-6a59216356bf","sourceKey":"bank:GST111:GST111-0423","parentItemId":null,"revision":1,"payload":{"prompt":"The punishment for violating copyright law is ..............","options":["Prosecute the offender under the law","All of the above","Ban the offender from the library","Kill the offender"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Copyrighted works are protected by law, so anyone who violates copyright can be prosecuted under the law (A). 'All of the above' (B) cannot be right because it would include killing the offender (D), which is not a legal punishment. A library ban (C) is not the legal penalty for breaking copyright law."}},{"itemId":"9f049e92-d628-5958-bb61-33a167284627","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"47ac92b5-989e-506d-8990-bc04f5583f0d","sourceKey":"bank:GST111:GST111-0424","parentItemId":null,"revision":1,"payload":{"prompt":"A survey of an article or chapter in a book does not take -------------------- into consideration.","options":["the blurb","the topic sentences","its title","the introduction and conclusion"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Surveying an article or chapter means checking the title, the first and concluding paragraphs and the topic sentences of each paragraph. The blurb is used when surveying a whole book, since only books carry one, so A is the exception. Options B, C and D are all parts of surveying an article or chapter."}},{"itemId":"b4906fe4-9bfc-5c7e-b124-f22bb84d017a","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5bdc39f8-9a51-5711-a1ad-02132f28c071","sourceKey":"bank:GST111:GST111-0425","parentItemId":null,"revision":1,"payload":{"prompt":"When you retrieve research results that are too broad or unrelated, the way out is to...........","options":["Change your search strategy","Change your topic","Change the author","Change your location"],"correctOption":0,"section":"Search Strategies","explanation":"When your results are too broad or unrelated, you need to rethink your search strategy, for example by adding AND terms, using phrase searching or choosing more specific vocabulary (A). Changing your topic (B) abandons the research rather than improving the search, and changing the author or your location (C and D) would not make the results more relevant."}},{"itemId":"e4eb9783-d7dd-5620-9b36-013a2f8fc0fe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9131c72d-e2f0-5ea1-a33e-9b001f86a67e","sourceKey":"bank:GST111:GST111-0426","parentItemId":null,"revision":1,"payload":{"prompt":"The ------------------ tune is used in declarative sentences.","options":["fall-rise","rising","rise-fall","falling"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The falling tune is used in declarative statements, as well as in commands, wh-questions and exclamations (D). The rising tune (B) is used for yes/no questions and polite requests, the fall-rise (A) is for lists and sentence modifiers, and the rise-fall (C) is not the tune linked with statements."}},{"itemId":"8c338305-7662-591e-ad43-be2e4d8ba9df","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dedce23d-956b-53a8-8bd5-ee4abb2e0089","sourceKey":"bank:GST111:GST111-0427","parentItemId":null,"revision":1,"payload":{"prompt":"How a reading material is read is determined by --------------------.","options":["its nature","the publishers","the author","the reader"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"The nature of a reading material decides how it is read and how rigorously: a newspaper is read once and discarded, while a study book is studied repeatedly (A). Option D, the reader, is tempting because readers vary their speed, but it is the material's nature that determines the approach. The author (C) and publishers (B) have no say in how you read."}},{"itemId":"1eb842a5-e7c9-5f94-b28d-9d4867c8d9d6","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"7de3bff3-51ea-569f-ae76-62a17a522805","sourceKey":"bank:GST111:GST111-0428","parentItemId":null,"revision":1,"payload":{"prompt":"When the intonation of a sentence identifies that sentence as a statement, question etc. it is said to perform a/an ------------------ function.","options":["grammatical","attitudinal","accentual","discourse"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Showing whether an utterance is a statement, a question or an exclamation is the grammatical function of intonation (A). The attitudinal function (B) reveals the speaker's emotion or attitude, and the discourse function (D) guides turn-taking in conversation. Accentual (C) relates to stress placement, not sentence type."}},{"itemId":"5bcbb0cf-9a0a-535f-a109-ff87dee6d1ff","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d96784f8-7267-571b-918e-308d6b2cdaac","sourceKey":"bank:GST111:GST111-0429","parentItemId":null,"revision":1,"payload":{"prompt":"To develop a paragraph, a .............. step process is advised.","options":["1","5","7","3"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Paragraph development follows a 5-step process: decide on a controlling idea and write a topic sentence, explain it, give examples, explain the examples, and complete the idea or move on to the next paragraph. So B is correct, and 1, 7 and 3 (A, C and D) give the wrong number of steps."}},{"itemId":"5a94c336-b877-53c5-a04c-73d0ace92b1d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"130a89f7-d340-5fe9-aaa9-ec2f45365cce","sourceKey":"bank:GST111:GST111-0430","parentItemId":null,"revision":1,"payload":{"prompt":"Another name for the argumentative essay is ........ essay.","options":["authoritative","rational","persuasive","expository"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The argumentative essay is also called the persuasive essay, because the writer takes a stand and tries to get readers to accept a point of view (C). Expository (D) describes writing that explains or informs rather than argues, and authoritative and rational (A and B) are not names of essay types."}},{"itemId":"f7204022-290b-55ba-9e11-69c00bb1fdcd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"4e049a11-25ab-5ee6-ad94-9aa7d0b81924","sourceKey":"bank:GST111:GST111-0431","parentItemId":null,"revision":1,"payload":{"prompt":"Reserved collections in University of lagos Library are run on ............. access system","options":["Closed","Open","Self-service","Reserve"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Reserved collections run on a closed access system: a user requests an item by giving its bibliographic details, and the material is fetched and used within the reading room (A). Open access (B) and self-service (C) would let users take materials from the shelves themselves, which is not allowed for reserved items. 'Reserve' (D) is the name of the collection, not the access system."}},{"itemId":"2cc46584-1d62-5b3c-b05f-95044d8d6fe4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"db952d1c-d574-56f3-82e5-449db141a745","sourceKey":"bank:GST111:GST111-0433","parentItemId":null,"revision":1,"payload":{"prompt":"......occurs when the meaning of a word depends on its environment and usage.","options":["connotation","pronunciation","contextual meaning","Assimilation"],"correctOption":2,"section":"Vocabulary Development","explanation":"Contextual meaning is meaning worked out from the word's environment, using clues in the sentence such as paired words or parallelism (C). Connotation (A) is tempting, but it is the figurative meaning a word carries from feelings and experience, as in 'he's dark' meaning evil. Pronunciation and assimilation (B and D) concern sounds, not meaning."}},{"itemId":"9185542d-68bb-5ff8-b52f-da0c771203f4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e28cf0f1-186c-5f67-a2b1-889354bc3a08","sourceKey":"bank:GST111:GST111-0434","parentItemId":null,"revision":1,"payload":{"prompt":"The chief aim of a narrative essay is to ......","options":["arouse and sustain reader's interest","defend a position","create a mental image of something","explain a process"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The chief aim of a narrative essay is to arouse and sustain the reader's interest, making them feel a good story has been told (A). Defending a position (B) is the aim of argumentative writing, creating a mental image (C) belongs to the descriptive essay, and explaining a process (D) is expository or analytical."}},{"itemId":"8fee06d1-db19-5baf-ac1f-f6be9f18efda","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d48185ff-41a4-59b6-acbd-b0b3556e40b6","sourceKey":"bank:GST111:GST111-0435","parentItemId":null,"revision":1,"payload":{"prompt":"An analytical essay provides information such as ..............","options":["rationalisation","all of the above","critique","none of the above"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In an analytical essay, information comes in two basic forms: rationalisations, which explain the state of things, and critiques, which review and judge quality. Since A and C are both correct, 'all of the above' (B) is the right choice, and 'none of the above' (D) is plainly wrong."}},{"itemId":"a334a554-3b42-5c3a-ac7b-cf40fef8fe15","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"10f68433-209e-5eae-b7af-2ac8a9e3aebd","sourceKey":"bank:GST111:GST111-0436","parentItemId":null,"revision":1,"payload":{"prompt":"University of lagos Library has newspapers dating as far back as .........","options":["1860","1920","1930","1960"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The Gandhi Library holds newspapers, old and current, dated as far back as 1930, including the West African Pilot, so C is correct. Options A, B and D give other dates: 1860 (A) is far too early, and 1960 (D) would leave out the pre-independence papers the library holds."}},{"itemId":"2ab65f83-3514-52bd-89b4-c2856a20522e","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c49c205b-8369-5d58-8bb1-541c265ab948","sourceKey":"bank:GST111:GST111-0437","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a type of Pronoun","options":["possessive pronouns","refractive pronouns","interrogative pronouns","reciprocal pronouns"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The types of pronoun include personal, possessive, interrogative, relative, demonstrative, reciprocal, reflexive, intensive and indefinite pronouns. There is no class called refractive pronouns; the word is a distortion of reflexive, so B is the answer. Possessive, interrogative and reciprocal pronouns (A, C and D) are all genuine types, reciprocal ones being each other and one another."}},{"itemId":"b1b7150c-6fd6-55cf-a937-a99ad4e14345","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f7d119d1-5261-5a19-81da-1d1533153b63","sourceKey":"bank:GST111:GST111-0438","parentItemId":null,"revision":1,"payload":{"prompt":"The ................. essay emphasizes character and setting.","options":["descriptive","narrative","persuasive","analytical"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A narrative essay emphasises character and setting so that the reader can identify with the subject and the situation (B). Option A, descriptive, is tempting because description also paints scenes, but character and setting are tied specifically to narration. Persuasive and analytical essays (C and D) focus on arguments and analysis."}},{"itemId":"a27c7aa3-5691-54b7-a566-4315315ca810","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"95872953-e830-5687-9aea-5ce63da3fe58","sourceKey":"bank:GST111:GST111-0439","parentItemId":null,"revision":1,"payload":{"prompt":"Electronic journals, electronic images, library software, CD-ROMS are ................","options":["Non-print resources","Print and non-print","Audio-visual resources","Print resources"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic books, electronic journals, electronic images, library software and CD-ROMs are non-print resources, managed by the Automation Section and accessed in the E-Library (A). Audio-visual resources (C) refer to aids like projectors, televisions and tape recorders, and B and D wrongly include print materials."}},{"itemId":"e33d1b48-a089-5811-83e4-e88b091e257d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"18ab668c-df0e-588f-80ae-1986c8638770","sourceKey":"bank:GST111:GST111-0440","parentItemId":null,"revision":1,"payload":{"prompt":"She hung onto his feet as if her life depended on it. What type of clause is 'as if her life depended on it'?","options":["adjectival clause","verbal clause","adverbial clause of manner","relative clause of manner"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"In 'as if her life depended on it', the clause modifies the verb hung by telling how she held on, so it is an adverbial clause of manner (C). An adjectival clause (A) would modify a noun, not a verb, and 'relative clause of manner' (D) is not a recognised clause type. Option B is not a clause type either."}},{"itemId":"a1907f26-249a-5c50-8163-1bd0effab30b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8c1f3c01-8269-509f-ba6c-d860b4543a4c","sourceKey":"bank:GST111:GST111-0441","parentItemId":null,"revision":1,"payload":{"prompt":"Unity in a paragraph suggests ........","options":["connection with other paragraphs","singularity of focus","elocution","brevity"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Unity means the whole paragraph keeps a single focus and does not wander into different ideas, so B is correct. Connection with other paragraphs (A) is about linking paragraphs with transitions, not about unity within one paragraph. Brevity (D) is about length, and elocution (C) concerns speaking."}},{"itemId":"cc41ce07-9331-5ecf-817f-ce940c1f3b90","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2789d80e-2ba3-5065-b060-61ed5c361b8f","sourceKey":"bank:GST111:GST111-0442","parentItemId":null,"revision":1,"payload":{"prompt":"A syllable with a CV structure is said to be ----------------------","options":["close","strong","weak","open"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A CV syllable ends in a vowel, so it has no coda and is an open syllable (D), like the words tea and slow. Closed syllables (A) end in a consonant, as in CVC. Strong and weak (B and C) describe the vowel quality in a syllable, not its structure."}},{"itemId":"b72b5993-4a46-58d3-ab82-c52e0c658141","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"bfa6fe48-46a2-5de1-aca4-7fa89366652d","sourceKey":"bank:GST111:GST111-0444","parentItemId":null,"revision":1,"payload":{"prompt":"Libraries perform all of these functions EXCEPT .....................","options":["Organisation","Preservation","Book selling","Acquisition"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"All libraries perform the basic functions of selection, acquisition, organisation, preservation and dissemination of information resources. Book selling is a commercial activity, not a library function, so C is the odd one out, while A, B and D are all library functions."}},{"itemId":"3b70fd0e-7611-5b6d-84f2-613aca43b4d3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d93a43aa-4bcb-5ccc-990e-351fde46916d","sourceKey":"bank:GST111:GST111-0445","parentItemId":null,"revision":1,"payload":{"prompt":"Wow! Oh no! and Watch it! are ___________","options":["prepositions","interjections","nouns","conjunctions"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Interjections are words or phrases that express strong feelings, emotions or exclamation, like Wow! Oh no! and Watch it! (B). Prepositions and conjunctions (A and D) show relationships or join words, and nouns (C) name things, so none of them expresses sudden emotion in this way."}},{"itemId":"7d65c508-526b-5766-80b7-2a674c25c97f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1b1e6dcc-33b0-51dc-b40d-07e30a88fae8","sourceKey":"bank:GST111:GST111-0446","parentItemId":null,"revision":1,"payload":{"prompt":"The Classification Scheme used for classifying and arranging library books in the University of Lagos Library is:","options":["American Library Classification Scheme","University Classification Scheme","Library of Congress Classification Scheme","Cataloguing and Classification Scheme"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library arranges its items by the Library of Congress (LC) classification scheme, which uses the letters A to Z for the main classes (C). Options A and B are not real schemes, and D, cataloguing and classification, describes the general activity rather than a named scheme."}},{"itemId":"c5d50845-3eb0-5584-b32a-14dd4550f754","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"402422ea-c915-5abb-8260-e7dd769c0c0b","sourceKey":"bank:GST111:GST111-0447","parentItemId":null,"revision":1,"payload":{"prompt":"Survey, in reading, involves ---------------.","options":["investigating the depth of the content","liaising with surveyors before reading","examining the preliminary matters and blurb of the book","measuring the length and breadth of the book"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"In the survey stage of SQ3R, you examine the preliminary matters of a book, such as the title, preface, foreword and table of contents, and read the blurb for a summary of the book (C). Option A describes deeper study reading, not a survey, and B and D play on the everyday meaning of survey and have nothing to do with reading."}},{"itemId":"369561dc-ee83-557c-bd2e-4c1343037746","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"597eb893-43e2-5b21-bdf1-e4c55419440c","sourceKey":"bank:GST111:GST111-0448","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following are types of index?","options":["Book index, periodical index and newspaper index","Indicative, informative and evaluative indexes","General, specialised and subject indexes","Primary and secondary indexes"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Indexes are pointers to published information, and they include the book index, the index to collections, the periodical index and the newspaper index (A). Option B is tempting, but indicative, informative and evaluative are the types of abstract, not index. General, specialised and subject (C) are types of dictionary, and primary and secondary (D) are sources of information."}},{"itemId":"c10b2651-8765-557f-a92a-287cd33f3a0f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b765bdaf-c793-5a28-9255-5272f20338d7","sourceKey":"bank:GST111:GST111-0449","parentItemId":null,"revision":1,"payload":{"prompt":"What is the process employed in achieving effective search results?","options":["Key","Search strategy","Call up number","Concept"],"correctOption":1,"section":"Search Strategies","explanation":"Search strategy is the art of planning and conducting searches to get the most efficient result, so it is the process asked about (B). Key (A) and concept (D) are elements you use within a search, while a call number (C) is the shelf address of a book, not a process."}},{"itemId":"84398f53-077c-5f14-9541-7909525c8001","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b562a667-54a2-5ef9-afc2-97bd4ec51202","sourceKey":"bank:GST111:GST111-0450","parentItemId":null,"revision":1,"payload":{"prompt":"Which clause patterns is reflected in this sentence : Jesus wept.","options":["SV","SVC","SVO","SVA"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'Jesus wept', Jesus is the subject and wept is the verb, with no object, complement or adverbial, so the pattern is SV (A). SVO (C) would need something receiving the action, and SVC and SVA (B and D) would need a complement or an adverbial after the verb."}},{"itemId":"df23bd94-0b01-56b1-acd7-aac8541504a3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"989ec3f2-780a-5bbf-b8a4-5c5514ca16f4","sourceKey":"bank:GST111:GST111-0451","parentItemId":null,"revision":1,"payload":{"prompt":"Skimming involves the following except------------------","options":["looking for specific details","reading the abstract","reading the blurb","looking at the table of contents"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Looking for specific details is scanning, not skimming, so A is the exception. In skimming you look at the title, blurb, abstract, table of contents and topic sentences to get a general idea, without hunting for particular facts, which is why B, C and D are all part of skimming."}},{"itemId":"61155354-faf7-5325-bf1e-f7b51beb749c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3135d660-3939-5a40-823d-1e7cc462849a","sourceKey":"bank:GST111:GST111-0452","parentItemId":null,"revision":1,"payload":{"prompt":"Yes/No questions are naturally asked using the ........................ tune.","options":["rising","fall-rise","falling","rise-fall"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The rising tune is used to ask yes/no (polar) questions, as in 'Can we go now?' (A). The falling tune (C) is used for statements, commands and wh-questions, the fall-rise (B) is for lists and sentence modifiers, and the rise-fall (D) is not linked with yes/no questions."}},{"itemId":"8ea3f5f5-43a9-5e47-8c30-b93236dc025c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5b87f293-908c-56e4-992c-c95d81f30acf","sourceKey":"bank:GST111:GST111-0454","parentItemId":null,"revision":1,"payload":{"prompt":"Yearbooks are also known as ........","options":["Annual","Dictionary","Handbook","Directory"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Yearbooks are published once a year to record the facts and events of that year, which is why they are also called annuals (A). Handbooks and directories (C and D) are separate kinds of fact source alongside yearbooks, not other names for them, and a dictionary (B) deals with words, not yearly facts."}},{"itemId":"7e2d38a8-bbed-5018-a166-9c451d9d7a19","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"0521af4f-5655-5017-ad8c-7e02249cdfb2","sourceKey":"bank:GST111:GST111-0455","parentItemId":null,"revision":1,"payload":{"prompt":"Voicing occurs as a result the ------------------ of the vocal folds.","options":["agitation","vibration","separation","relaxation"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Voicing happens when the glottis is relatively closed and the vocal folds vibrate under air pressure from the lungs, so the answer is vibration (B). Separation (C) describes the open glottis that produces voiceless sounds, and agitation and relaxation (A and D) are not the terms used for voicing."}},{"itemId":"a2ef3721-728b-5277-b75c-2f65f356bf26","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"3caf1369-1fbe-563d-b550-336be1034717","sourceKey":"bank:GST111:GST111-0456","parentItemId":null,"revision":1,"payload":{"prompt":"When a user deploys a variety of search tools simultaneously, it is called ........","options":["Meta search","Advanced search","Simple search","Search tool"],"correctOption":0,"section":"Search Strategies","explanation":"A meta search is one where the user uses a variety of search tools at the same time, through meta search engines such as Dogpile and Metacrawler that search Google, Yahoo and others at once (A). Advanced search (B) applies filters and multiple fields within one tool, and simple search (C) uses a few keywords in a single search box."}},{"itemId":"781dc850-0a35-581f-88b9-daacd947d0d5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"077fc16f-0da0-5272-bb65-9d614c1350f0","sourceKey":"bank:GST111:GST111-0457","parentItemId":null,"revision":1,"payload":{"prompt":"Using the APA referencing style, any article retrieved from a website with no date of publication should be cited in the reference list but the following information must be included:","options":["The url from where the article was accessed","The date the article was retrieved","The date and URL from where the document was obtained","None of the above"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"An APA reference for a web document with no date uses (n.d.) and then states when and where it was obtained, as in 'Retrieved October 17, 2008, from' followed by the URL, so both the retrieval date and the URL are needed (C). Options A and B each give only one of the two required pieces of information, so they are incomplete."}},{"itemId":"dd095964-3d02-57ad-bdc5-38829d497d66","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9785a6ec-fa75-5901-87ef-71e1dc15542c","sourceKey":"bank:GST111:GST111-0458","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following skills is not necessary in note-taking.","options":["sound articulation","sentence reduction","summary","paraphrasing"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Sound articulation is a speaking skill, not a note-taking skill, so A is the odd one out. Effective note-taking needs skills such as recognising main ideas, reducing content to note form, sentence reduction, summary and paraphrasing, which are B, C and D."}},{"itemId":"522e51ed-921a-5a8b-adb3-67e3a9cfe8fc","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"91503b61-95ce-585c-8a51-130fe25ae100","sourceKey":"bank:GST111:GST111-0459","parentItemId":null,"revision":1,"payload":{"prompt":"The asterisk sign (\\*) in a search is known as .............","options":["Simple search","Wild card","Phrase search","Truncation"],"correctOption":3,"section":"Search Strategies","explanation":"Truncation means putting an asterisk (*) after the root of a word so the search retrieves all its variations, for example teen* finding teens and teenagers (D). Option B, wildcard, is tempting, but wildcards replace a single letter and most commonly use the ? symbol, as in colo?r. Phrase searching (C) uses quotation marks, and simple search (A) is a basic keyword search."}},{"itemId":"1318f19c-909f-5ea8-86dc-4dc143a3bb6d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"85ef0a0f-8f8f-5631-8947-84528f782616","sourceKey":"bank:GST111:GST111-0460","parentItemId":null,"revision":1,"payload":{"prompt":"When the meaning of a word is considered in isolation, it is known as ......meaning.","options":["complex","objective","connotative","denotative"],"correctOption":3,"section":"Vocabulary Development","explanation":"Denotative meaning is the literal, dictionary meaning of a word considered on its own, as in 'dark' meaning without light (D). Connotative meaning (C) comes from feelings, emotions and experience, so it is not meaning in isolation. Complex and objective (A and B) are not recognised types of word meaning."}},{"itemId":"6652b58d-58d8-5b2f-a49f-079a007e37fd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"67d89f33-046a-53a2-b1b7-f912d5d5e23c","sourceKey":"bank:GST111:GST111-0461","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'responsibility' is correctly stressed as ------------","options":["respon'sibility","'responsibility","responsi'bility","re'sponsibility"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Responsibility has primary stress on the fourth syllable, bil, and secondary stress on the second syllable, so the correct marking is responsi'bility (C). Option D, re'sponsibility, is tempting because the base word responsible is stressed there, but the suffix -ity moves the primary stress to the syllable just before it."}},{"itemId":"1f539f72-1782-50e5-afe5-29c7c5c75fd3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c8dc9313-3463-55f4-be09-4595c4174982","sourceKey":"bank:GST111:GST111-0462","parentItemId":null,"revision":1,"payload":{"prompt":"Based on the length of storage of information, memory is classified into ------","options":["visible and invisible","variable and invariable","long and short-term","active and dormant"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"By how long information is kept, memory is divided into short-term memory, which stores information briefly and filters out what is irrelevant, and long-term memory, which is permanent and large (C). Sensory memory is the very brief memory linked to the senses. Active and dormant (D) describe kinds of vocabulary, not memory, and A and B are not memory types at all."}},{"itemId":"9170260b-e0a8-51ec-bd59-f468f992c53d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5b750f30-8b19-588c-a317-6147547fb686","sourceKey":"bank:GST111:GST111-0463","parentItemId":null,"revision":1,"payload":{"prompt":"\"un\" in the word \"unfaithful\" is an example of a","options":["subjunction","prefix","conjunct","suffix"],"correctOption":1,"section":"Vocabulary Development","explanation":"An affix added at the beginning of a word, like un- in unfaithful or unpleasant, is a prefix (B). A suffix (D) is added at the end of a word, like -ful in the same word. Subjunction and conjunct (A and C) are not names for word parts; a conjunct is a linking word."}},{"itemId":"afe38528-3970-5007-9e1b-012a865334b0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"09939134-f488-59dc-b091-0ec3716add80","sourceKey":"bank:GST111:GST111-0464","parentItemId":null,"revision":1,"payload":{"prompt":"A/an .... is a combination of ideas from one paragraph to another, that creates a united whole.","options":["text","essay","sentence","paragraph"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An essay is a combination of ideas from one paragraph to another that creates a united whole, because all the paragraphs support each other (B). A paragraph (D) is the single unit being combined, not the combination itself, a sentence (C) is smaller still, and a text (A) is too general."}},{"itemId":"19dfdf9c-a91f-5063-9bce-894142a5e17c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d4c01e3-ad1a-55ef-8945-21248e048b95","sourceKey":"bank:GST111:GST111-0465","parentItemId":null,"revision":1,"payload":{"prompt":"The reading speed adopted depends on all the following except ---------------------------","options":["the nature of the reading material","the reader","the purpose of the reading","the author's prescription"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The nature of the reading material and your purpose decide how thoroughly and how fast you read, and a flexible reader changes speed to suit the material, so A, B and C all matter. The author does not prescribe how fast you read, so D is the odd one out."}},{"itemId":"85f4358a-e383-5a8f-b76e-e2e56f35f747","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ca156488-8130-5f14-ac46-dfd2dad82817","sourceKey":"bank:GST111:GST111-0466","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following phrases contains an indefinite article?","options":["That house","A big fat hen","The Golden Globe awards.","My friend"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The articles are the (definite) and a or an (indefinite), so 'A big fat hen' contains the indefinite article a (B). Option C uses the definite article the, while that (A) is a demonstrative and my (D) is a possessive determiner."}},{"itemId":"725f52f8-5bbd-5c56-92fe-32fad6e4f7b3","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"f467ba63-9fe1-5fa1-80a0-d686657a6e35","sourceKey":"bank:GST111:GST111-0467","parentItemId":null,"revision":1,"payload":{"prompt":"The words fax, prep, gents, zoo and ad are examples of which word-formation process?","options":["clipping","conversion","Blend","Acronym"],"correctOption":0,"section":"Vocabulary Development","explanation":"Clipping is shortening a long word that is awkward in speech, keeping only part of it, as in fax from facsimile or zoo from zoological garden (A). A blend (C) combines parts of two different words, like smog from smoke and fog, and an acronym (D) is formed from the initials of several words. Conversion (B) changes a word's class without changing its form."}},{"itemId":"8f408af0-e4fe-5c29-96ce-7999bd31e5b1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"57b3885d-a107-5cb4-9804-a279efd17504","sourceKey":"bank:GST111:GST111-0468","parentItemId":null,"revision":1,"payload":{"prompt":"-------------- is the use of the pitch of the voice to convey meaning or syntactic information.","options":["rhythm","intonation","stress","phonetics"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Intonation is the use of the pitch of the voice to convey meaning or syntactic information (B). Stress (C) is the extra prominence given to one syllable within a word, rhythm (A) is the timing pattern of speech, and phonetics (D) is the study of speech sounds as a whole."}},{"itemId":"2e31f50f-0ed6-5b68-a714-fa4bbab18f27","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6f29934c-9eb1-5e1e-99dc-5e0731090660","sourceKey":"bank:GST111:GST111-0469","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT essential to reading","options":["printed signs","the eyes","the articulatory system","written signs"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading is translating written or printed symbols into meaning, and it involves the eyes and the brain. The articulatory system (lips, tongue, vocal cords) is not needed, and moving the vocal organs while reading is actually a bad habit called vocalisation, so C is the answer. Printed signs, the eyes and written signs (A, B and D) are all essential."}},{"itemId":"8e654e96-eee0-59ed-b78e-4209656f69bb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ce926c9b-605d-51f0-a757-61b461d9d9e2","sourceKey":"bank:GST111:GST111-0470","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a coordinating conjunction used to join the clauses of a compound sentence?","options":["so that","but","and","yet"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"So that is a subordinating conjunction that makes one clause depend on another, which produces a complex sentence, so it is not used in compound sentences (A). Compound sentences use coordinating conjunctions such as and, but, or, nor, for and yet, which is why B, C and D are not the answer."}},{"itemId":"346287a0-c236-5744-a58f-744d25cca971","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"fc8682d8-4f57-5251-9122-2346947f6bb3","sourceKey":"bank:GST111:GST111-0472","parentItemId":null,"revision":1,"payload":{"prompt":"What is a thesaurus?","options":["A dictionary of synonyms, which is a specialised dictionary","A general dictionary that gives the etymology of most words","A list of sources placed at the end of a research work","A brief summary of a book or article"],"correctOption":0,"section":"Vocabulary Development","explanation":"A thesaurus is a dictionary of synonyms, such as Roget International Thesaurus, and it counts as a specialised dictionary (A). Option B describes a general unabridged dictionary, which covers most words with details and etymology. A list of sources at the end of a work (C) is a bibliography, and a brief summary (D) is an abstract."}},{"itemId":"3ff952eb-d2b5-56e5-95bf-52c479136f2f","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"dfb96b82-36b6-552b-9a62-69cbdcffa11f","sourceKey":"bank:GST111:GST111-0473","parentItemId":null,"revision":1,"payload":{"prompt":"An index serves as .............. to required information","options":["A full-text copy","Pointer and indicator","None","A summary"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"An index is a directional aid that points to and indicates where information can be found, so it serves as a pointer and indicator (B). It does not give the full text of the material (A), and a brief summary of a document (D) is an abstract, not an index."}},{"itemId":"18a86db9-7a02-5287-8d56-21a382e1ae9d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"825b9495-71b8-5e5d-be80-9c3850e2eb91","sourceKey":"bank:GST111:GST111-0474","parentItemId":null,"revision":1,"payload":{"prompt":"The movement of the eyes in the process of reading can be described as ------------","options":["velaric","glottalic","saccadic","pulmonic"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"When we read, our eyes move in little jumps forward and then stop, and this movement is called saccadic (C). Velaric, glottalic and pulmonic (A, B and D) are airstream mechanisms in speech production and have nothing to do with eye movement."}},{"itemId":"34e3360b-512f-5007-9a9c-64969326d500","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"9b4b110a-7513-5090-98c9-0959c9f22825","sourceKey":"bank:GST111:GST111-0476","parentItemId":null,"revision":1,"payload":{"prompt":"The caverns were so damp that my skin felt","options":["Clamy","Clammby","Clamby","Clammy"],"correctOption":3,"section":"Vocabulary Development","explanation":"The correct spelling is clammy, with a double m and a y, meaning unpleasantly damp and sticky (D). Option A, clamy, drops the second m, while B and C insert a b that does not belong in the word."}},{"itemId":"53f3bb20-0986-51d3-b78e-f34f4e827bfe","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"6d2f4287-a73c-515f-a346-40d3ccbe1aaf","sourceKey":"bank:GST111:GST111-0477","parentItemId":null,"revision":1,"payload":{"prompt":"Grammar is categorized into two major sections, namely;","options":["Lexis and morphology.","Syntax and semantics.","Syntax and phonetics.","Morphology and syntax."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Grammar is traditionally divided into morphology, the study of how words are formed, and syntax, the study of how words are combined into sentences (D). Option B is wrong because semantics is the study of meaning, not a branch of grammar, and C is wrong because phonetics studies speech sounds. Lexis (A) refers to vocabulary rather than grammatical structure."}},{"itemId":"392eba9b-15a1-5446-86f6-bac02d3639f9","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"832a7e4c-572a-5179-94fd-34c9b0d69871","sourceKey":"bank:GST111:GST111-0478","parentItemId":null,"revision":1,"payload":{"prompt":"---------------- is a glottal sound.","options":["/k/","/w/","/h/","/j/"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/h/ is a voiceless glottal fricative, made with friction at the glottis, the gap between the vocal folds (C). /k/ (A) is a voiceless velar stop made with the back of the tongue against the soft palate. /w/ (B) is a bilabial glide and /j/ (D) is a palatal glide, so neither is made at the glottis."}},{"itemId":"68cf1438-117a-5462-960e-3c92693279bb","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a74fbc96-14bf-55c8-acaa-ee4fd4c3f3d8","sourceKey":"bank:GST111:GST111-0479","parentItemId":null,"revision":1,"payload":{"prompt":"Not waiting for the lecture to end before drawing yourconclusion on the content suggests --------------","options":["hasty generalisation","emotional attachment","distraction","mental challenge"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Not waiting for the lecture to end before drawing a conclusion is hasty generalisation (A); a good listener is patient enough to let the speaker finish the point before reacting. Emotional attachment (B) refers to prejudice about the topic or lecturer, distraction (C) refers to noise and other interruptions, and mental challenge (D) is actually a positive attitude to adopt."}},{"itemId":"1dcd7eef-62e8-50a0-9cb3-ad31a54c5881","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"c4feeaef-20a4-524a-8e0e-b351fb45a5e1","sourceKey":"bank:GST111:GST111-0480","parentItemId":null,"revision":1,"payload":{"prompt":"Dictionaries are used as quick ------- sources in the library","options":["Publication","Manual","Serial","Reference"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Dictionaries are reference materials, consulted quickly for specific information such as spelling, meaning and pronunciation, and housed at the reference section of the library (D). Serial (C) refers to publications issued in successive parts, like journals and newspapers, and publication and manual (A and B) are not the category dictionaries belong to."}},{"itemId":"ced605ba-e8ee-5ff3-914d-0b272fd8d4a1","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"cdbe567c-a827-5a20-82e0-2a00362c6c45","sourceKey":"bank:GST111:GST111-0481","parentItemId":null,"revision":1,"payload":{"prompt":"Which clause patterns is reflected in this sentence : The priest pronounced the couple man and wife.","options":["SVOC","SVA","SVC","SVOO"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'The priest pronounced the couple man and wife', the priest is the subject, pronounced is the verb, the couple is the object and man and wife is the object complement, which describes the same people as the object. That is the SVOC pattern (A). SVOO (D) would need two different objects, such as a receiver and a thing given, while SVA and SVC (B and C) have no object at all."}}]$expected_content$::jsonb,
  'use-of-english: cbt_question published payload and identity match source');
set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000008')
  where kind = 'theory_question') = $expected_content$[{"itemId":"ec7fe978-c8e8-53e4-be5f-cc7dd10fcb82","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Define listening and discuss four strategies for enhancing listening skills."}},{"itemId":"581e7879-0c09-57ec-994f-64e9d493d020","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:10","parentItemId":null,"revision":1,"payload":{"prompt":"Define a phrase and explain any four types of phrase in English with one example each."}},{"itemId":"f080dbdc-2921-5808-9f7e-555c36543412","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:11","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between defining and non-defining relative clauses, with one example of each, and show how punctuation affects meaning."}},{"itemId":"0b59eb48-441b-5264-be58-705b94b87e1e","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:12","parentItemId":null,"revision":1,"payload":{"prompt":"Highlight five characteristics of good information."}},{"itemId":"1554bfcd-b06b-56b2-9054-2ead2b884028","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:13","parentItemId":null,"revision":1,"payload":{"prompt":"List the three information retrieval tools in the library and explain how the University of Lagos Main Library classifies its materials."}},{"itemId":"ff6ca6bc-9dce-5840-9ac7-584fe28ccd74","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:14","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the three Boolean operators and give two reasons for using them in an online search."}},{"itemId":"6857b502-3b17-5f52-85ec-0c9586bcd0f6","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:15","parentItemId":null,"revision":1,"payload":{"prompt":"You have consulted a book written by O. P. Maxwell and I. Daniel, published in 2017 by Oxford in England, titled Introduction to Geodesy. Show how you would enter it in the reference list in (a) APA and (b) Harvard style, and explain what plagiarism is and two ways to avoid it."}},{"itemId":"012bd206-3418-51b1-b543-d68a623244a6","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"What is the basic difference between consonant and vowel articulation, and how is each type of sound described?"}},{"itemId":"ef210d0b-f9ba-5347-8a99-74e606af4cb3","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"Stress is perceptually marked by four main features. List them and explain how each indicates stress."}},{"itemId":"89869c2e-9fb3-5179-b521-a6966386ef84","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Differentiate between skimming and scanning, and list four bad reading habits, stating why each is not recommended."}},{"itemId":"4e3c6792-c883-5505-b754-5200e0943a0e","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the four categories of comprehension questions, giving one example of each."}},{"itemId":"d8a9e146-234e-515d-9111-7148c5c6a8b8","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the SQ3R technique of study reading."}},{"itemId":"4bd81e1d-548e-510e-949b-183e435120aa","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Outline and explain the five-step process for paragraph development."}},{"itemId":"d9c56737-2394-5e87-a520-cafd3101f6c5","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the COEM factor in essay writing."}},{"itemId":"d71fc0df-1a2a-52a9-8b1f-20622cedf9bd","courseId":"40000000-0000-4000-8000-000000000008","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:9","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between denotative and connotative meaning, and explain how verbal context helps a reader work out the meaning of an unfamiliar word."}}]$expected_content$::jsonb,
  'use-of-english: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000008')
  where kind = 'model_answer') = $expected_content$[{"itemId":"999936c6-81ea-5806-8e41-7ecad6a74cb5","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"ec7fe978-c8e8-53e4-be5f-cc7dd10fcb82","revision":1,"payload":{"body":"Define listening (the ability to receive, perceive and decode the meaning of spoken words; a receptive skill without which communication is impossible). Then 1-2 lines each on four strategies, e.g. eye contact (links your mind with the speaker's, shows readiness), concentrating on content (identify the topic, focus on the message), repressing emotional attachment (avoid prejudice from bias or personal emotions), avoiding hasty generalisations (let the speaker finish the point before reacting)."}},{"itemId":"13f5c8fb-1fde-5aa2-989c-105de38c40cc","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:10","parentItemId":"581e7879-0c09-57ec-994f-64e9d493d020","revision":1,"payload":{"body":"Define a phrase as a group of words (possibly one word) working as a single grammatical unit and named after its head word. Then one or two lines each on four types, e.g. noun phrase (a heavy rain, works as a noun), verb phrase (may have gone, main verb plus auxiliaries), prepositional phrase (under the bed, preposition plus object, works as adjective or adverb), adjective phrase (extremely valuable, modifies a noun)."}},{"itemId":"64dce646-70cb-578f-be61-a7ad893af70b","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:11","parentItemId":"f080dbdc-2921-5808-9f7e-555c36543412","revision":1,"payload":{"body":"Define the relative (adjective) clause. Defining: identifies the noun (\"which one?\"), essential, no commas, accepts that (The students who arrived late were locked out: some students). Non-defining: adds information about a known noun, non-essential, paired commas, never that (The students, who arrived late, were locked out: all students). Conclude that the commas change \"some\" to \"all\"."}},{"itemId":"73ff98d9-640f-52bb-bcf6-b4415a5dedc9","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:12","parentItemId":"0b59eb48-441b-5264-be58-705b94b87e1e","revision":1,"payload":{"body":"Define information briefly (processed data that improves the user's knowledge). Then one or two lines each: availability/accessibility (easy to obtain and within reach); accuracy (correct for its purpose); reliability (truthful, authoritative, dependable); timeliness (on time, or it becomes irrelevant); relevance (suited to the purpose and the user)."}},{"itemId":"028b7b14-2b90-597a-944b-6bef48558e99","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:13","parentItemId":"1554bfcd-b06b-56b2-9054-2ead2b884028","revision":1,"payload":{"body":"Name the library catalogue (manual and OPAC), indexes and abstracts, and bibliography, with one line on each. Then state that the Main Library uses the Library of Congress scheme: mixed (alpha-numeric) notation, main classes A to Z with O, X and Y reserved, sub-divided by two letters (e.g. HM Sociology). Add that the College of Medicine uses the NLM scheme."}},{"itemId":"f7d5cf3e-e2fc-5a93-8533-71330bbbc6e7","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:14","parentItemId":"ff6ca6bc-9dce-5840-9ac7-584fe28ccd74","revision":1,"payload":{"body":"Name George Boole. AND narrows: all terms must be present (cloning AND humans AND ethics). OR broadens: connects synonyms, any term may be present (cloning OR genetics OR reproduction). NOT excludes a word (cloning NOT sheep). Reasons: to focus a search with multiple terms; to connect pieces of information exactly as wanted (title AND author AND year). Mention that AND is often implied and that brackets fix the order."}},{"itemId":"0515e25a-8a3b-5b8d-8f30-88be56131b12","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:15","parentItemId":"6857b502-3b17-5f52-85ec-0c9586bcd0f6","revision":1,"payload":{"body":"(a) APA: Maxwell, O. P., & Daniel, I. (2017). Introduction to geodesy. England: Oxford. (b) Harvard: Maxwell, OP & Daniel, I 2017, Introduction to geodesy, Oxford, England. Then define plagiarism (using copyrighted work without permission or acknowledging the source; \"academic theft\") and give the two rules: cite properly in the prescribed style, and list every citation in the reference list or bibliography."}},{"itemId":"ee5079f7-f445-5731-bcd8-ff63ef8bb625","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"012bd206-3418-51b1-b543-d68a623244a6","revision":1,"payload":{"body":"Consonants: at least two articulators make contact and obstruct the airflow; described by place of articulation, manner of articulation and state of the glottis (voicing), e.g. /p/ voiceless bilabial stop. Vowels: no obstruction, no contact, all voiced; described by tongue height, tongue horizontality, lip rounding and duration (tense/lax), e.g. /i:/ high front tense. Mention the counts: 24 consonants, 20 vowels."}},{"itemId":"3f87732b-324b-58aa-b0c3-c8828461ab7c","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"ef210d0b-f9ba-5347-8a99-74e606af4cb3","revision":1,"payload":{"body":"Define stress (relative prominence of one syllable over others in a polysyllabic word). Then one or two lines each: loudness (stressed syllable is louder), length (longer syllable heard as stressed), pitch (higher pitch from faster vocal cord vibration; strongest effect), quality (strong vowel or diphthong versus weak /ə, ɪ, ʊ/). Close: the factors usually combine."}},{"itemId":"9904caa0-e35c-571c-9d78-e77aa7c3e210","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"89869c2e-9fb3-5179-b521-a6966386ef84","revision":1,"payload":{"body":"Skimming: quick reading for the overall idea via title, blurb, contents, headings, topic sentences; no specific information sought. Scanning: quick search for one specific piece of information using the index or contents; ignores irrelevant details. Then any four habits, one line each, e.g. word-by-word reading (slow, laborious), vocalisation (moving vocal organs cuts rate and comprehension), finger-pointing (forces the eyes word by word), regression (excessive backward glances hinder comprehension)."}},{"itemId":"368a6527-0c25-5c69-bf99-ef7db127e13d","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"4e3c6792-c883-5505-b754-5200e0943a0e","revision":1,"payload":{"body":"State that the categories come from the tools examiners use to test understanding. Then one or two lines each: direct reference (refer directly to the text; \"with reference to the passage...\"); inference (establish the relationship between parts of the passage; \"the difference between sentence 1 and sentence 3...\"); supposition (think beyond the passage to the outside world; \"what do you suppose is responsible for...\"); evaluation (judge the information and the effectiveness of the writer's language; \"in your opinion, what is the writer's motivation?\")."}},{"itemId":"457b4fe5-0559-5b25-a241-ee60cc354fc6","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"d8a9e146-234e-515d-9111-7148c5c6a8b8","revision":1,"payload":{"body":"Define study reading. Expand SQ3R: Survey (preliminary matters: title, preface, foreword, contents, blurb, date), Question (ask guiding questions about correctness, aim, objectivity), Read (careful, critical reading, two or three times, taking notes), Recall/Recite (remember from memory by paraphrasing or exact words), Review (assess and revise everything; a repetition of all the steps). One line each."}},{"itemId":"ec3a518b-003c-572d-b89f-ad38c8232af8","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"4bd81e1d-548e-510e-949b-183e435120aa","revision":1,"payload":{"body":"Name the five steps in order, one or two lines each: (1) decide on a controlling idea and write a topic sentence; (2) explain the controlling idea; (3) give one or more examples as evidence; (4) explain each example's relevance to the topic sentence; (5) complete the idea or transition to the next paragraph. Add that steps 3 and 4 may be repeated, and illustrate with the African oral narratives model (the tortoise and the feast in the sky)."}},{"itemId":"2b2688f4-ffe5-567d-95cc-49c61c43dc9f","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:8","parentItemId":"d9c56737-2394-5e87-a520-cafd3101f6c5","revision":1,"payload":{"body":"Define COEM as the four quality-control components of an essay. Then 2-3 lines each: Content (depth of treatment, the \"meat\"; narrow the subject; keep a central idea or thesis), Organisation (logical ordering; suitable introduction, body from familiar to unfamiliar, striking conclusion), Expression (precise, concise, concrete words; avoid jargon and highfalutin language), Mechanics (punctuation and related symbols that convey the right meaning). Close by saying that together they distinguish a well-executed essay from a poorly rendered one."}},{"itemId":"29222e23-31c2-5672-aecd-e5c2a2b315bf","courseId":"40000000-0000-4000-8000-000000000008","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:9","parentItemId":"d71fc0df-1a2a-52a9-8b1f-20622cedf9bd","revision":1,"payload":{"body":"Define denotative meaning (literal, dictionary meaning; dark = lightlessness). Define connotative meaning (associated, figurative meaning from feelings and experience; \"he's dark\" = evil). Then explain verbal context: clues from paired words that are complementary (similar meaning: unscrupulous and dishonest) or contrasting (opposite meaning: not wasteful, so frugal), with one example of each."}}]$expected_content$::jsonb,
  'use-of-english: model_answer published payload and identity match source');
