  where kind = 'course_overview') = $expected_content$[{"itemId":"31430adf-b11f-5f51-8f58-cb27f8156d28","courseId":"40000000-0000-4000-8000-000000000010","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"International Organisational Behaviour","body":"A foundational course examining how culture, defined as the collective programming of the mind, shapes organisational behaviour across borders. The course moves from core cultural frameworks (Hofstede, GLOBE, Trompenaars) through perception, motivation, personality, communication, team management, leadership, negotiation, HR practice, organisational structure, ethics, and future trends including global mobility and AI. Assumes introductory Organisational Behaviour and Management.","topics":[{"chapter":"1","description":"The Imperative for International OB — Culture, the Onion Model, Values vs Practices"},{"chapter":"2","description":"Cultural Frameworks I — Hofstede's Dimensions, Schwartz's Values, the Lewis Model"},{"chapter":"3","description":"Cultural Frameworks II — The GLOBE Study, Trompenaars' Dilemmas, the Meyer Culture Map"},{"chapter":"4","description":"Perception, Attribution, and Attitudes Across Cultures"},{"chapter":"5","description":"Motivation in Cross-Cultural Context — Maslow, Herzberg, Equity Theory"},{"chapter":"6","description":"Personality and Cultural Intelligence (CQ) — The Big Five across cultures"},{"chapter":"7","description":"Communication Styles — High-Context vs Low-Context"},{"chapter":"8","description":"Managing Multicultural and Virtual Teams — Trust and Conflict"},{"chapter":"9","description":"Cross-Cultural Leadership — Universal vs Culturally-Contingent Perspectives"},{"chapter":"10","description":"Cross-Cultural Negotiation and Decision-Making"},{"chapter":"11","description":"International Human Resource Management — Expatriate Selection and Culture Shock"},{"chapter":"12","description":"Organisational Structure, Culture and Change — Pyramids, Machines, Markets, Families"},{"chapter":"13","description":"Ethics, CSR, and Sustainability in a Global Economy"},{"chapter":"14","description":"Course Integration and Future Trends — Global Mobility, Digital Nomads, and AI"}],"examFocus":["The distinction between Values (invisible, stable) and Practices (visible, changeable)","Why transferring Western management models to other countries often fails","Definitions and real-world examples of High vs Low Power Distance","Why Individualism correlates with national wealth and Collectivism with poverty","Comparing Hofstede's dimensions with GLOBE's (e.g., institutional vs in-group collectivism)","How locus of control (internal vs external) changes with Uncertainty Avoidance","Why US motivation theories (Maslow, Herzberg) fail outside Western/individualist contexts","How Individualism vs Collectivism alters the peak of Maslow's pyramid","The difference between an individual's personality and a nation's collective culture","Edward T. Hall's High vs Low Context theory and its mapping to Individualism/Collectivism","How Masculinity/Femininity dictates conflict resolution style in teams","Why participative management (e.g., MBO) fails in High Power Distance countries","The role of the Go-between or mediator in Collectivist business negotiations","The four phases of the Acculturation Curve","Why standard performance appraisals fail in collectivist societies (loss of face)","Mapping the Pyramid, Machine, Market, and Family structures to PDI and UAI dimensions","The correlation between cultural Femininity, development aid, and environmental protection","The illusion of the \"Global Village\" — technology does not erase cultural differences"]}}]$expected_content$::jsonb,
