  where kind = 'course_overview') = $expected_content$[{"itemId":"577bde2b-9ef5-521c-b103-b65737b7b097","courseId":"40000000-0000-4000-8000-000000000011","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":2,"payload":{"title":"Principles of Business Administration II","body":"Covers how businesses manage people, change, decisions, communication and ethics, and how the Nigerian financial system and securities market fund them.","topics":[{"chapter":"1","description":"Human Resource Management: Nature, Scope, and Importance"},{"chapter":"2","description":"Human Resource Planning, Recruitment, Selection, and Employee Development"},{"chapter":"3","description":"Employee Motivation, Leadership, and Performance Management"},{"chapter":"4","description":"Organisational Change and Change Management"},{"chapter":"5","description":"Managerial Decision-Making and Problem Solving"},{"chapter":"6","description":"Organisational Behaviour, Communication, and Team Dynamics"},{"chapter":"7","description":"Organisational Culture, Power, Politics, and Workplace Dynamics"},{"chapter":"8","description":"Business Communication, Information Systems, and Digital Management"},{"chapter":"9","description":"Business Ethics, Corporate Responsibility, and Ethical Decision-Making"},{"chapter":"10","description":"Nigeria's Banking, Financial System, and Securities Market"}],"examFocus":["Difference between Personnel Management and HRM","Objectives and functions of HRM","Maslow's Hierarchy of Needs (five levels, ordering, examples)","Herzberg's Two-Factor Theory — Hygiene (context) vs Motivator (content) factors","Lewin's Change Model and Kotter's Eight-Step Model","Drivers of and resistance to organisational change","Fields' (2000) three levels of organisational change (implemental, strategic, org-wide)","Types of managerial decisions: strategic, tactical, operational","Rationality and bounded rationality in decision-making","Nature and scope of organisational behaviour (individual, group, organisational levels)","Stages of group development (forming, storming, norming, performing, adjourning)","Formal vs informal groups; command group vs task group","Barriers to effective communication; formal vs informal channels","Structure of the Nigerian financial system (CBN, NDIC, SEC, NAICOM, PenCom)","Financial intermediation and its key functions","Expansionary vs contractionary monetary policy and business impact","Shares, bonds, debentures, and mutual funds — definitions and risk/reward","Sources of business finance: equity finance vs debt finance vs venture capital","NGX Group structure and capital market intermediaries (SEC, CSCS, NGX RegCo)","Ethical theories, CSR, and workplace ethical issues"]}}]$expected_content$::jsonb,
  'principles-business-administration-2: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000011')
  where kind = 'note') = $expected_content$[]$expected_content$::jsonb,
  'principles-business-administration-2: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('40000000-0000-4000-8000-000000000011')
  where kind = 'cbt_question'), 0,
  'principles-business-administration-2: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '40000000-0000-4000-8000-000000000011' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"152970d3-b087-5648-add8-e7c9d2fd027d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6537e2cb-21d8-5d49-9506-b417e2e1113b","sourceKey":"bank:BUA202:BCI-003","parentItemId":null,"revision":1,"payload":{"prompt":"Anything that interferes with accurate communication between a sender and a receiver is referred to as:","options":["The channel","Feedback","The grapevine","Noise"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Noise is any interference, such as poor network, a loud environment or language differences, that distorts the message. Option A, the channel, is the medium that carries the message, not the interference. Option C, the grapevine, is the informal communication network in an organisation."}},{"itemId":"a233f503-4074-5c52-9c63-2be938030a48","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e3109365-44d8-5f33-814b-10abe796c42e","sourceKey":"bank:BUA202:BCI-004","parentItemId":null,"revision":1,"payload":{"prompt":"A sales manager in Ikeja sends a voice note to his team, but the network is so poor that the audio keeps breaking and some words are lost. In the communication process, the poor network is best described as:","options":["Feedback","Noise","Decoding","Encoding"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Noise is anything that interferes with accurate communication, and poor internet is a typical example. Option C, decoding, would be the team interpreting the message, which they cannot do properly because of the interference. Option D, encoding, was done by the manager when he put his ideas into words."}},{"itemId":"b8277b35-8fc7-5267-94ca-1fbfa1fdfee1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c39c60de-4467-56ae-8d68-4ebefce00385","sourceKey":"bank:BUA202:BCI-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about the 'concise' characteristic of effective communication is correct?","options":["Conciseness only matters in oral communication, not in written reports","A concise message avoids unnecessary information but must not leave out essential information","Being concise means using technical jargon so that fewer words are needed","The shortest possible message is always the most effective message"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Concise communication cuts out unnecessary words, but concise does not mean incomplete, because a short message that omits essential information is ineffective. Option D ignores this warning. Option C confuses brevity with jargon, which actually makes a message less clear."}},{"itemId":"27ddbc1c-f741-5569-b97d-35493365cf61","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b138f7d0-95d8-5cab-8488-72a918092cf6","sourceKey":"bank:BUA202:BCI-007","parentItemId":null,"revision":1,"payload":{"prompt":"A memo inviting staff of a Yaba firm to a Monday 9 a.m. meeting reaches them on Tuesday afternoon. The memo was clear and correct. Which characteristic of effective communication did it fail?","options":["Accurate","Appropriate","Concise","Timely"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Timely communication arrives while the information is still useful, and a meeting invitation received after the meeting is useless. Option A does not apply because the memo's details were correct. Options C and B are about length and suitability of language, which were not the problem here."}},{"itemId":"207b9d7a-6d36-5bba-99d1-6fe6197c29b0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5567aae5-3222-5aa7-93a5-6c25d72c628e","sourceKey":"bank:BUA202:BCI-008","parentItemId":null,"revision":1,"payload":{"prompt":"A company's letter to a regulator contains correct, complete and timely information, but it is written in street slang with emojis. Which characteristic of effective communication is missing?","options":["Accurate","Timely","Appropriate","Complete"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Appropriate communication uses language, tone and a medium that suit the audience, and slang with emojis does not suit a regulator. Options B, D and A are all satisfied in the scenario, since the letter was on time, complete and correct."}},{"itemId":"869a84be-57a7-56f0-bb8c-ea60270acec6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"003df8dd-8d39-56cd-aae7-41bb2222969d","sourceKey":"bank:BUA202:BCI-009","parentItemId":null,"revision":1,"payload":{"prompt":"Communication that follows officially recognised organisational structures and channels, is usually documented and can be traced to an identifiable source is called:","options":["Non-verbal communication","Informal communication","Grapevine communication","Formal communication"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Formal communication follows the official structure, for example official emails, written reports and policy documents, and it is documented and traceable. Options B and C describe the unofficial network that operates outside these structures. Option A is communication without words, such as gestures."}},{"itemId":"e0f54d98-5852-5751-b44e-28dacd7ec1b0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9baddf19-c713-57d6-a562-d085abd61813","sourceKey":"bank:BUA202:BCI-010","parentItemId":null,"revision":1,"payload":{"prompt":"Information that flows from higher levels of management to lower levels, such as policies, instructions and organisational objectives, is known as:","options":["Horizontal communication","Downward communication","Upward communication","Diagonal communication"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Downward communication moves from senior management to subordinates and typically carries policies, instructions and objectives. Option C flows the other way, from employees to management. Option A takes place between people at the same level."}},{"itemId":"7b7dc7d2-2d5b-5444-95fb-22c7dd573c35","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9153ba8e-36f3-5abd-aa92-6bf276d001c0","sourceKey":"bank:BUA202:BCI-011","parentItemId":null,"revision":1,"payload":{"prompt":"Staff of a Lagos bottling company drop complaints and suggestions in a suggestion box that is opened weekly by the General Manager. This is an example of:","options":["Upward communication","Downward communication","Grapevine communication","Horizontal communication"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Upward communication flows from lower levels to management and includes complaints, suggestions, reports and feedback. Option B is the reverse direction. Option C is wrong because a suggestion box is an official channel, not the informal grapevine."}},{"itemId":"25ee7fc5-6438-5f18-9047-93cc7dad4338","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c48f329e-9840-5c60-9b13-28f92380848f","sourceKey":"bank:BUA202:BCI-012","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing manager of a Lagos FMCG firm meets the finance manager, who is at the same level, to agree on next quarter's advertising budget. This is:","options":["Downward communication","Horizontal communication","Diagonal communication","Upward communication"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Horizontal communication occurs between employees or departments at the same organisational level, and this exact pairing is the standard example. Option C, diagonal communication, would involve people at different levels in different departments. Options A and D involve movement up or down the hierarchy."}},{"itemId":"d828d30c-b439-5c9d-a5fc-27924384aa8d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ebfbd948-2939-5b3f-b57f-d7e03c979110","sourceKey":"bank:BUA202:BCI-013","parentItemId":null,"revision":1,"payload":{"prompt":"An HR Manager contacts a Sales Officer in another department directly, without going through the Sales Manager. This type of communication is:","options":["Horizontal communication","Downward communication","Diagonal communication","Upward communication"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Diagonal communication cuts across different departments and different levels, outside the standard reporting line, and can speed up decisions. Option A needs both people to be at the same level, which is not the case here. Options D and B describe flows within one chain of command."}},{"itemId":"04b0d7fb-fb6a-58d5-a3bd-a03c0d90c324","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"391243e4-98a3-5459-a62a-2bb0dd078aa8","sourceKey":"bank:BUA202:BCI-016","parentItemId":null,"revision":1,"payload":{"prompt":"Rumours spreading through informal channels can harm an organisation in several ways. Which of the following is NOT one of those harmful effects?","options":["They reduce employee trust","They distort information","They create a permanent official record of decisions","They create anxiety among staff"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Rumours may distort information, create anxiety, damage reputations and reduce employee trust. Creating a permanent official record is a feature of formal written communication, not of rumours. Options B, D and A are all listed harmful effects."}},{"itemId":"04eed8db-8194-5d2a-a71d-feae9dc3c9f3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"87a4cd87-4e28-5e8f-98c8-e05b31d9265b","sourceKey":"bank:BUA202:BCI-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing correctly contrasts formal and informal communication?","options":["Formal: based on personal relationships; Informal: based on organisational objectives","Formal: written records available; Informal: usually no records","Formal: does not follow hierarchy; Informal: follows hierarchy","Formal: fast and flexible; Informal: slow and planned"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Formal communication is official, planned and recorded, while informal communication is unofficial and usually leaves no records. Option D reverses the speed contrast, since formal communication tends to be slower. Options C and A also swap the features of the two types."}},{"itemId":"e834339d-cbc5-57d4-9706-aaeba77acdaa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"742955d9-237e-5cc0-a7f1-bcdd95ae32ea","sourceKey":"bank:BUA202:BCI-018","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturing company issues a press release to the media, writes to its bankers and sends an annual report to investors. These are examples of:","options":["External communication","Horizontal communication","Grapevine communication","Internal communication"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"External communication takes place between the organisation and outsiders such as customers, suppliers, banks, government, investors and the media. Option D is communication within the organisation. Option B is a type of internal communication between people at the same level."}},{"itemId":"7ca59250-97ea-5f23-b39a-35667793ffc0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1e96c476-1499-5285-bb9b-04e4de221c9d","sourceKey":"bank:BUA202:BCI-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of oral communication?","options":["Feedback is delayed","It is impersonal","It is too slow for urgent matters","There is usually no permanent record"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Oral communication through meetings, phone calls and interviews gives quick, personal, immediate feedback, but it leaves no permanent record and can be misunderstood. Options A, B and C describe the opposite of oral communication's real advantages."}},{"itemId":"f52f9826-ef88-54a3-a012-7ce108b9a496","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"43869e8d-90e0-569a-88b2-753750749a40","sourceKey":"bank:BUA202:BCI-020","parentItemId":null,"revision":1,"payload":{"prompt":"In a contract dispute, a Lagos construction firm presents a signed letter in court to prove what was agreed with a supplier. Which advantage of written communication does this show?","options":["It can serve as legal evidence","It gives immediate feedback","It is quick and personal","It avoids the need for a channel"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Written communication such as letters, reports and memos provides a permanent, accurate record that can serve as legal evidence. Options B and C are advantages of oral communication. Option D is wrong because every message needs a channel."}},{"itemId":"8d70d8e9-9ec3-548f-bf7c-a37c8617fd40","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fc2ee09d-e554-563b-8bfb-cf697c65d558","sourceKey":"bank:BUA202:BCI-021","parentItemId":null,"revision":1,"payload":{"prompt":"Facial expressions, eye contact, gestures, body language and appearance are all forms of:","options":["Oral communication","Non-verbal communication","Written communication","Visual communication"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Non-verbal communication takes place without words, and sometimes body language says more than spoken words. Option D, visual communication, uses images and symbols such as charts, graphs and infographics. Options C and A both use words."}},{"itemId":"88239132-b9b3-564d-9a4d-42bc299f0850","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"35f9f750-934a-5d74-ad2c-007d48571a76","sourceKey":"bank:BUA202:BCI-022","parentItemId":null,"revision":1,"payload":{"prompt":"An IT consultant explains a new system to market traders using terms like 'API latency' and 'cloud instances', and the traders understand very little. The main barrier here is a:","options":["Psychological barrier","Language barrier","Physical barrier","Cultural barrier"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Language barriers include different languages, technical jargon and poor vocabulary, and here the jargon blocks understanding. Option C covers things like noise, distance and faulty equipment. Option A covers emotions such as fear, stress and anger."}},{"itemId":"60b28258-430c-57a2-ba7d-43ded4438008","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2e79f9d1-928b-5610-9ce0-0cb35b886528","sourceKey":"bank:BUA202:BCI-023","parentItemId":null,"revision":1,"payload":{"prompt":"A newly employed graduate is too afraid of the Managing Director to report a costly error he noticed. Which barrier to communication does this illustrate?","options":["Organisational barrier","Language barrier","Psychological barrier","Physical barrier"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Psychological barriers arise from the state of mind of the people communicating, such as fear, stress, anger or lack of confidence. Option A refers to structural problems like a long chain of command or information overload. Option B needs a language or jargon problem, which is not present."}},{"itemId":"fa795295-48dd-5cff-ae41-7945b18a243f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cf969ffc-9ae3-5ef6-8644-9235aa88f3a8","sourceKey":"bank:BUA202:BCI-024","parentItemId":null,"revision":1,"payload":{"prompt":"A business report is best described as:","options":["An informal verbal update given by a supervisor during a lunch break","A personal opinion piece written by an employee for social media","A short notice pinned on the staff board announcing a public holiday","A formal written document that presents facts, findings, analysis and recommendations to help management make informed decisions"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"A business report is formal and written, and it presents facts, findings, analysis and recommendations in a structured, objective way to support decisions. Option A is informal and oral. Option B is subjective, while a good report must be objective and evidence-based."}},{"itemId":"38b27c28-a5dc-50cf-ae89-42f7a10e8bc6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6f5e1834-8056-5cb6-b9f6-39c4aa901d4b","sourceKey":"bank:BUA202:BCI-025","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket chain produces a monthly sales report that simply lists sales by branch, and a separate report that explains why profits are falling and recommends solutions. These two reports are, respectively:","options":["A progress report and a research report","An analytical report and an informational report","An informational report and an analytical report","A financial report and a progress report"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"An informational report provides facts only, such as a monthly sales report, while an analytical report adds analysis and recommendations, such as a report on declining profits. Option B reverses the two. Option A is wrong because a progress report tracks a project and a research report presents research findings."}},{"itemId":"fa4a76c1-f9d9-500c-9927-02157a728037","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e24d7071-7eb5-59ff-9cec-003eccd9f37f","sourceKey":"bank:BUA202:BCI-026","parentItemId":null,"revision":1,"payload":{"prompt":"Every Friday, a site engineer sends management an update on how far the construction of a new warehouse in Ota has gone. This is a:","options":["Financial report","Progress report","Research report","Informational press release"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"A progress report shows how far a project has gone, which is exactly what a weekly construction update does. Option C presents findings from research. Option A contains financial statements such as the income statement and balance sheet."}},{"itemId":"cf981a50-bd42-573d-9357-9f8524fe3da7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7f674794-6781-5656-99b5-593238f1c016","sourceKey":"bank:BUA202:BCI-027","parentItemId":null,"revision":1,"payload":{"prompt":"In the structure of a business report, the section that explains how the information in the report was gathered is the:","options":["Methodology","Recommendations","Appendices","Conclusion"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"The methodology section explains the methods used to collect and analyse information, and it comes after the introduction and objectives but before the findings. Option B gives the suggested actions. Option C holds supporting documents at the end of the report."}},{"itemId":"c05b49c5-f97f-5bd7-8b3e-38c949c81f84","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4a031a98-32ea-5e1b-8b56-4df0cd823ded","sourceKey":"bank:BUA202:BCI-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of a good business report?","options":["Subjective","Well-organised","Evidence-based","Objective"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"A good business report is clear, accurate, concise, objective, well-organised, evidence-based and easy to understand, so a subjective report based on personal opinion fails the test. Options D, C and B are all listed qualities of a good report."}},{"itemId":"4a7dc5d3-3fc3-5b44-9149-2ea7a2ff72be","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0b53c936-1dbb-53c8-b6b1-b1f55c35be25","sourceKey":"bank:BUA202:BCI-029","parentItemId":null,"revision":1,"payload":{"prompt":"Managerial communication refers to:","options":["The informal chats among employees during lunch and social events","Advertising messages that managers send to the firm's customers","The exchange of information between managers and employees for planning, organising, leading, controlling and decision-making","Communication that takes place only among top executives at board meetings"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Managerial communication is the exchange of information between managers and employees to carry out the management functions and make decisions. Option D is too narrow because it leaves out employees. Option A describes the grapevine, and option B is external marketing communication."}},{"itemId":"4cc1c7de-1bc2-5429-887f-41a44cd4c66c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4d13d11a-4c97-556e-a17b-965956615952","sourceKey":"bank:BUA202:BCI-030","parentItemId":null,"revision":1,"payload":{"prompt":"Digital communication in organisations is best defined as:","options":["The exchange of information using electronic devices and digital technologies","Any communication that uses numbers rather than words","Face-to-face meetings held only in the company's boardroom","The exchange of handwritten letters through the postal service"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Digital communication uses the internet and electronic systems, such as email, WhatsApp, Zoom and company websites, to send and receive information almost instantly. Options D and C are traditional forms of communication. Option B misreads 'digital' as meaning numbers."}},{"itemId":"131e6927-6ddd-5dc6-afd0-f4799c8bdef8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8944fbdd-fc48-5aa7-b9de-90306bbd237f","sourceKey":"bank:BUA202:BCI-031","parentItemId":null,"revision":1,"payload":{"prompt":"A private internal network used only by a company's employees to share policies, company news and internal information is called a(n):","options":["Intranet","Internet","Extranet open to customers","Social media page"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"An intranet is a private internal network for employees only, used for sharing policies, company news, employee records and internal communication. Option B, the internet, is the open public network. Option D is public-facing and is used for advertising and customer engagement."}},{"itemId":"b7a84874-8ae1-53e8-8d2c-596ef7394bd1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3c02dee4-59be-50fa-b5bf-d20d84d095c3","sourceKey":"bank:BUA202:BCI-032","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos firm trains its staff in Kano and Port Harcourt through a live Zoom session instead of flying them to Lagos. Which advantage of video conferencing does this show most directly?","options":["It creates no need for training","It removes all security concerns","It saves travel costs","It works without the internet"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Video conferencing allows online meetings, interviews and training, and its advantages include saving travel costs and allowing remote collaboration. Option B is wrong because security concerns are a listed disadvantage. Option D is wrong because internet issues are another disadvantage."}},{"itemId":"f7552e07-e3e1-57cb-be17-1d7f45da0920","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0db42191-57d0-5d36-bb6b-0110c16e0b20","sourceKey":"bank:BUA202:BCI-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a challenge of digital communication commonly faced by Nigerian organisations?","options":["Cybersecurity threats","Poor internet connectivity","Power outages","Lower spending on paper and postage"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Lower spending on paper, postage and transport is an advantage of digital communication (cost reduction), not a challenge. Options C, B and A are listed challenges, together with lack of digital skills, software failures and data breaches."}},{"itemId":"095d83ad-4a30-5fe6-ad50-893d819c8af7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d3854101-a0a6-5a28-9bd6-8357b87f79f7","sourceKey":"bank:BUA202:BCI-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a component of a Management Information System?","options":["Procedures","Hardware","Database","Shareholders' equity"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"The components of an MIS are hardware, software, database, procedures, people and network. Shareholders' equity is an item in a company's balance sheet, not part of an information system. Options B, A and C are all MIS components."}},{"itemId":"c5be3989-47f0-5134-b5dc-77bcb33cd091","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e547d36a-7db1-568a-a5da-09f74ff3d919","sourceKey":"bank:BUA202:BCI-036","parentItemId":null,"revision":1,"payload":{"prompt":"A bank's information system includes written rules on how staff enter customer data, how files are backed up every night and who may access passwords. These rules form which component of the MIS?","options":["Procedures","Network","Software","Hardware"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Procedures are the rules that guide how the system is used, such as data entry, backup and security procedures. Option C, software, refers to the programs that run the system. Option B, network, is what lets the computers talk to each other, such as LAN, WAN or Wi-Fi."}},{"itemId":"d4b4012a-a651-5b9e-bf12-91de1a69b675","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cb33be45-2d78-58a7-a0f9-d9e244296586","sourceKey":"bank:BUA202:BCI-037","parentItemId":null,"revision":1,"payload":{"prompt":"ATM withdrawals, payroll processing and sales processing are handled mainly by which type of information system?","options":["Decision Support System (DSS)","Transaction Processing System (TPS)","Office Automation System (OAS)","Executive Information System (EIS)"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"A Transaction Processing System processes daily business transactions, and ATM transactions, payroll and sales processing are its classic examples. Option D gives summary information to top executives. Option A helps managers with complex decisions rather than routine transactions."}},{"itemId":"d084836a-fd13-5cb5-82b3-740a798ca872","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4bf02ffa-d269-5b09-b430-293924fd8092","sourceKey":"bank:BUA202:BCI-038","parentItemId":null,"revision":1,"payload":{"prompt":"An information system that integrates all business departments, such as finance, marketing, HR and production, into one system is called:","options":["Office Automation System (OAS)","Executive Information System (EIS)","Enterprise Resource Planning (ERP)","Transaction Processing System (TPS)"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"ERP integrates the different business departments, such as finance, marketing, HR and production, so they share one system. Option A supports office work like word processing, email and spreadsheets. Option B provides information to top executives."}},{"itemId":"ca7e223d-95c2-59eb-ad09-75274bc342f9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f7ea000e-8b9c-5e51-8764-de2c08738e6c","sourceKey":"bank:BUA202:BCI-039","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches an information system to its main users or purpose?","options":["Transaction Processing System - supports complex non-routine decisions","Office Automation System - integrates finance, HR and production","Decision Support System - processes ATM withdrawals and payroll","Executive Information System - provides information to top executives"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"An Executive Information System provides information to top executives. Option C describes a TPS, option B describes ERP, and option A describes a DSS, so each of them pairs a system with another system's role."}},{"itemId":"69bd8b66-ea36-5489-9d27-44ec672c1796","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"019c70dc-4626-56ed-8a47-06dc7044822b","sourceKey":"bank:BUA202:BCI-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly distinguishes data from information?","options":["Data are raw, unorganised facts used as input; information is processed, organised and used for decision-making","Data and information mean the same thing in business","Data are always numbers, while information is always written in words","Data are processed facts used for decision-making; information is raw input"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Data are raw facts with little meaning on their own, and they become information once they are processed, organised and interpreted for decision-making. Option D swaps the two terms. Option C is wrong because data can be names, phone numbers or attendance records, not just numbers."}},{"itemId":"7da7c10e-87b7-57ab-9107-1ebb0ce6bbc3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"77226b8d-7508-5036-98f4-2bc8b1d44a08","sourceKey":"bank:BUA202:BCI-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of information rather than data?","options":["The number of loaves of bread sold each day this week","Daily attendance figures recorded at the gate","A list of customers' names and phone numbers","A statement that sales at the Surulere branch rose sharply in March and should guide April stock orders"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Information is data that has been processed and interpreted so that it can guide a decision, which is what the statement about the March sales rise does. Options C, B and A are raw facts and figures that have not yet been organised or analysed, so they are data."}},{"itemId":"102ae6a4-e506-5495-a584-97ed766b0a7f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"806fe2e2-cb1b-5234-9fd1-5284806959a2","sourceKey":"bank:BUA202:BCI-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an EXTERNAL source of data for a business?","options":["Sales records","Payroll records","Production reports","Government publications"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"External sources come from outside the business, for example government publications, market research, industry reports, customer feedback and competitor analysis. Options B, C and A are produced inside the business, so they are internal sources."}},{"itemId":"a59568c5-6bf2-5f17-964c-44dafa94fe18","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"dbcd6492-ccda-511f-ba42-7f808098ffa6","sourceKey":"bank:BUA202:BCI-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of good information for managerial decision-making?","options":["Relevance","Excessive volume","Verifiability","Timeliness"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Good information is accurate, complete, relevant, timely, reliable, understandable, accessible, verifiable and consistent. Too much information actually causes information overload, which is a communication barrier. Options A, C and D are listed qualities of good information."}},{"itemId":"55bf6a8b-d5e5-5ac5-b2d5-6bbc84a9a8d9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"156e173b-6231-5425-a3e1-56e533fd97d3","sourceKey":"bank:BUA202:BCI-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of remote work mainly to the EMPLOYER rather than the employee?","options":["Reduced office expenses","Better work-life balance","More personal autonomy","Reduced transport costs"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"For employers, remote work reduces office expenses, gives access to global talent, can raise productivity and keeps the business running during emergencies. Options D, B and C are benefits listed for employees, such as saving on transport and a better work-life balance."}},{"itemId":"1e4bdac7-de7b-598e-ab53-9ab317819126","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e5a22641-9769-5356-8054-e9f9ba43caec","sourceKey":"bank:BUA202:BCI-046","parentItemId":null,"revision":1,"payload":{"prompt":"Digital business refers to:","options":["Selling computers, phones and other digital devices only","A business that keeps all its records on paper but advertises online","Conducting business operations using digital technologies, electronic systems and the internet to create value for customers","Any business registered with the Corporate Affairs Commission after 2020"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Digital business means running business operations with digital technologies, electronic systems and the internet, for example online shopping platforms, mobile banking and digital payments. Option A confuses the products sold with the way the business operates. Option B uses only one digital tool and keeps paper-based operations."}},{"itemId":"deb20020-68df-5acf-b441-62b13ca708fe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c60583f0-c449-5af0-9e16-ead214b3934a","sourceKey":"bank:BUA202:BCI-047","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery recorded 400 loaves sold on Monday and 460 on Tuesday. When this data is processed into information, what is the percentage change in sales from Monday to Tuesday (to 2 decimal places)?","options":["60.00% increase","13.04% increase","15.00% increase","115.00% increase"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Turning raw data into information means processing it, here with percentage change = (new - old) / old x 100 = (460 - 400) / 400 x 100 = 15.00%. Option B comes from dividing the change by the new figure (60 / 460), and option A reports the change of 60 loaves as if it were a percentage."}},{"itemId":"1f1ff165-344e-568d-8bc2-fe27cc932f2c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4618a4b4-dd7c-5d86-8785-3a50213d6395","sourceKey":"bank:BUA202:BCI-048","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere supermarket's weekly sales fell from N2,500,000 to N2,150,000. What is the percentage change in sales (to 2 decimal places)?","options":["86.00% decrease","14.00% decrease","14.00% increase","16.28% decrease"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Percentage change = (new - old) / old x 100 = (2,150,000 - 2,500,000) / 2,500,000 x 100 = -14.00%, a decrease. Option D divides the fall of N350,000 by the new figure instead of the old one. Option A gives the new sales as a percentage of the old (86%), not the change."}},{"itemId":"e5688452-82a2-5f73-835a-e34de999067f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f335c28f-c3c3-56c4-8543-605c2b0ec0cf","sourceKey":"bank:BUA202:BCI-049","parentItemId":null,"revision":1,"payload":{"prompt":"A shop recorded daily customer counts of 180, 240, 210 and 270 over four days. If a manager processes this data into an average daily figure, what is the average number of customers per day?","options":["225","900","270","300"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Average = total / number of days = (180 + 240 + 210 + 270) / 4 = 900 / 4 = 225 customers per day. Option B is the total without dividing, and option D divides the total by 3 instead of 4 days."}},{"itemId":"65281417-09e6-507b-a229-9baae63eb595","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4e1b161e-0be8-5032-b513-1f0ecd5b4d59","sourceKey":"bank:BUA202:BCI-050","parentItemId":null,"revision":1,"payload":{"prompt":"Attendance records for a department show that 45 of its 60 staff were present on Monday. What is the absence rate for that day?","options":["25%","33.33%","75%","15%"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Absence rate = staff absent / total staff x 100 = (60 - 45) / 60 x 100 = 15 / 60 x 100 = 25%. Option C is the attendance rate, not the absence rate, and option B wrongly divides the 15 absentees by the 45 who were present."}},{"itemId":"f11d9504-f005-59ee-ab35-2bfb9653ed9a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b74de6d2-560e-52c4-9626-a8f44c795707","sourceKey":"bank:BUA202:CHG-001","parentItemId":null,"revision":1,"payload":{"prompt":"Any significant alteration in the structure, operations, culture, technology, strategies or processes of an organisation, moving it from its current state to a desired future state, is called","options":["Strategic planning","Organisational structure","Organisational change","Organisational culture"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Organisational change is any significant alteration in how the organisation is set up or operates, taking it from where it is to where it wants to be. Option D is shared values and beliefs, option B is the arrangement of roles and reporting lines, and option A is the process of setting long-term goals, which may lead to change but is not the change itself."}},{"itemId":"1a009ff3-3549-5200-a9d7-6fc5afc92fbb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"855f065e-8f64-5b06-858b-42fec151a86c","sourceKey":"bank:BUA202:CHG-002","parentItemId":null,"revision":1,"payload":{"prompt":"The systematic process of planning, implementing, monitoring and sustaining organisational change so that it is introduced smoothly with minimal disruption is","options":["Change management","Downsizing","Organisational change","Resistance to change"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Change management is the deliberate process of planning, carrying out, monitoring and sustaining a change. Option C is the change itself rather than how it is managed, option D is people's unwillingness to accept change, and option B is one particular kind of personnel change."}},{"itemId":"48ceaf83-dd5d-5bf2-84b9-7efe9e06de14","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3c8ea80e-b5c7-59a5-b89d-a67a7fa3ffa8","sourceKey":"bank:BUA202:CHG-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of organisational change?","options":["It may be planned or unplanned","It is influenced by internal and external factors","It occurs only once in the life of an organisation","It is continuous"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Organisational change is continuous, not a one-off event, because the environment keeps changing. Options D, A and B are genuine characteristics, along with being necessary for survival and affecting employees positively or negatively."}},{"itemId":"032f0767-8a57-53de-926f-1e7bc0ef697b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"77b60bd4-b6af-56a0-aa5a-4aa8c9d4bd24","sourceKey":"bank:BUA202:CHG-005","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian beverage company decides to enter the Ghanaian market and introduce a new line of products. This is an example of","options":["Structural change","Strategic change","Personnel change","Cultural change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Strategic change involves changes made to achieve long-term goals, such as entering new markets or launching new products. Option A is about departments and reporting lines, option C about recruitment, promotion or downsizing, and option D about values and attitudes."}},{"itemId":"86647ddb-fd59-53a6-928d-e0402c87f027","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cb9e14d6-06c5-546e-9653-11468bd2e5c3","sourceKey":"bank:BUA202:CHG-006","parentItemId":null,"revision":1,"payload":{"prompt":"A firm merges its sales and marketing departments and changes who reports to whom. This is","options":["Technological change","Structural change","Strategic change","Cultural change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Structural change alters the organisation's structure, for example by creating or merging departments and changing reporting relationships. Option A involves new equipment or systems, option D involves values and beliefs, and option C involves long-term goals such as new markets."}},{"itemId":"90a7cb27-9617-5fb2-b930-1df016960a3b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"06d63e98-085c-5004-8163-d12b0e7fec30","sourceKey":"bank:BUA202:CHG-007","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos replaces manual ledgers with computerised accounting and introduces online banking. This is an example of","options":["Technological change","Cultural change","Personnel change","Structural change"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Introducing new technology or equipment, such as computerised accounting, online banking, automation or AI, is technological change. Option C concerns staff movements, option D concerns departments and reporting lines, and option B concerns values and attitudes."}},{"itemId":"df15c7de-54c6-59d0-ba94-bfd62727f63f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"caf7c18d-de5a-5557-ab6a-e6361f751791","sourceKey":"bank:BUA202:CHG-008","parentItemId":null,"revision":1,"payload":{"prompt":"Management at an Abuja firm tries to get staff to value teamwork instead of competing against one another individually. This is an example of","options":["Structural change","Personnel change","Cultural change","Technological change"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Cultural change alters the organisation's values, beliefs and attitudes, such as promoting teamwork over individual competition. Option A would change departments or reporting lines, option D would introduce new equipment, and option B would involve hiring, promoting or laying off people."}},{"itemId":"f98b3b18-01c6-5ff1-a970-5d49853bab90","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3f2869d4-0637-5768-9e84-9b334340f9eb","sourceKey":"bank:BUA202:CHG-009","parentItemId":null,"revision":1,"payload":{"prompt":"Recruitment, promotion, training, downsizing and retirement are examples of which type of organisational change?","options":["Strategic change","Cultural change","Technological change","Personnel change"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Personnel change involves changes to the people in the organisation, such as who is hired, promoted, trained or released. Option A concerns long-term goals and markets, option B values and beliefs, and option C new equipment and systems."}},{"itemId":"47c2b611-df73-5fb9-ade7-f092db655e62","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4052f65f-e8d5-5a28-93bd-c16bc5d38b28","sourceKey":"bank:BUA202:CHG-011","parentItemId":null,"revision":1,"payload":{"prompt":"A newly appointed MD at a Port Harcourt firm introduces a new set of policies within her first month. As a driver of change, this is best classified as","options":["An external driver (government policy)","An internal driver (new leadership)","An external driver (customer preferences)","An external driver (globalisation)"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"New leadership originates within the organisation, so it is an internal driver; a new manager often brings different policies. Options A, D and C are all forces from outside the organisation."}},{"itemId":"caf6bcbc-cd9c-5a2c-ad5a-ced748ff89c2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"657a0ae7-a9b2-509f-8d8c-1a525d72f3c4","sourceKey":"bank:BUA202:CHG-012","parentItemId":null,"revision":1,"payload":{"prompt":"Rising inflation and a sharp fall in the naira exchange rate force a Lagos importer to cut costs and restructure. This driver of change is","options":["Organisational growth, an internal driver","Economic conditions, an external driver","Innovation, an internal driver","Financial problems caused by new leadership, an internal driver"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Inflation, recession and exchange rate movements are economic conditions that come from outside the firm and may require cost-cutting. Options D, C and A are internal drivers that originate within the organisation, and none of them describes what triggered this change."}},{"itemId":"3c2671e2-b404-5360-8f0d-21a4711e7dad","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be065acb-f43c-53fb-973e-b66732659307","sourceKey":"bank:BUA202:CHG-013","parentItemId":null,"revision":1,"payload":{"prompt":"The business environment in which organisations operate is characterised as","options":["Fixed, single-sided and stable","Dynamic, multifaceted and complex","Static, simple and predictable","Unchanging, uniform and controllable"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"The business environment keeps changing, has many sides and is complex, which is why organisations must keep adapting. Options C, A and D describe a stable environment in which change management would hardly be needed."}},{"itemId":"6687987d-9d63-5c60-9db2-0038b706dc8d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4e05b60a-2a35-5c72-9447-6041789e7644","sourceKey":"bank:BUA202:CHG-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is listed as a factor that brings about organisational change?","options":["The absence of competitors","A permanently stable national economy","The emergence of a knowledge workforce","Unchanging customer expectations"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"The rise of a knowledge workforce is one of the listed factors that push organisations to change, along with competition, technology, regulation and globalisation. Options B, A and D describe conditions that would reduce the need for change, not cause it."}},{"itemId":"a5b9c0d4-caa7-5401-8b81-a6d754458dc0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c040baad-8ba0-53f1-8878-07604d2d62b0","sourceKey":"bank:BUA202:CHG-015","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation grows and its employees need new knowledge and abilities, the change is in the area of employee skills. This is mainly addressed through","options":["Changing the organisation's logo","Raising the prices of products","Reducing the number of departments","Training and development programmes"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Change in employee skills means staff must learn new knowledge and abilities, so change management uses training and development programmes. Option A is a branding decision, option B a pricing decision, and option C a structural change."}},{"itemId":"88532c3c-a0a8-59bb-a86c-709b7a8a8b26","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0e28022f-684d-589b-b4f9-9b62d6c7d986","sourceKey":"bank:BUA202:CHG-016","parentItemId":null,"revision":1,"payload":{"prompt":"In which area of organisational change does management mainly use communication, motivation and involvement to encourage positive attitudes and teamwork towards the change?","options":["Structure","Employee attitude","Technology","Strategy"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Change in employee attitude targets staff willingness to accept and support change, and organisations shape it through communication, motivation and involvement. Option C concerns adopting new tools and software, option A concerns departments and reporting lines, and option D concerns the long-term plan."}},{"itemId":"1e3a258c-18f5-5697-ae49-42e5d5cb95de","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"93ef8624-7145-5249-8300-a8a1b99ae919","sourceKey":"bank:BUA202:CHG-019","parentItemId":null,"revision":1,"payload":{"prompt":"Field's (2006) third level of organisational change is best described as","options":["A minor change to the daily procedures of one department only","A strategic questioning of purpose and agenda limited to top management","An organisation-wide effort involving order, beliefs, values and the relationships among subsystem groups","An implemental adjustment that keeps the existing alignment of the system"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"The third level is the broadest: an organisation-wide effort touching order, beliefs, values and how the subsystems relate. Option D is the first level, option B resembles the second level, and option A is too narrow for any but the first level."}},{"itemId":"8658ff69-e467-576a-a3c8-b7cd9b10ea2a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"94963370-e7a4-540c-b074-4743349df1a4","sourceKey":"bank:BUA202:CHG-020","parentItemId":null,"revision":1,"payload":{"prompt":"The unwillingness of employees or organisations to accept new ideas, methods, policies or procedures is called","options":["Refreezing","Change management","Resistance to change","Organisational inertia planning"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Resistance to change is the reluctance to accept new ideas, methods, policies or procedures, often because people fear uncertainty. Option B is the process of managing change, option A is Lewin's final stage that makes change permanent, and option D is not a recognised term."}},{"itemId":"b5080a21-39f3-51f4-9a50-18f76b3a074e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9486c77e-47ee-54dd-b16a-05d21cff3158","sourceKey":"bank:BUA202:CHG-021","parentItemId":null,"revision":1,"payload":{"prompt":"When a Lagos bottling plant announces it will install automated packing lines, the packers protest because they worry the machines will replace them. The main cause of their resistance is","options":["Fear of job loss","Increased workload","Habit","Poor leadership"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Workers who worry automation will take their jobs are resisting out of fear of job loss. Option B would apply if the change made them work harder, option C if they simply preferred old routines, and option D if weak leaders were the problem."}},{"itemId":"094db532-8459-5c84-b2b8-3f2ed2288628","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a2ddc720-07ff-51bd-bbcd-d9c6eb9fb30e","sourceKey":"bank:BUA202:CHG-022","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a firm keep using the old filing system even though a better one has been introduced, saying they are simply used to the old way. Their resistance arises from","options":["Habit","Increased workload","Lack of trust","Fear of job loss"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Habit makes people comfortable with existing routines, so they resist even a better new method. Option D would involve worry about being replaced, option C doubts about management's motives, and option B complaints that the change means more work."}},{"itemId":"be50a447-deb4-53e1-9417-6925da112694","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"71df25fe-e9f2-5cd5-9453-7898a39dec28","sourceKey":"bank:BUA202:CHG-023","parentItemId":null,"revision":1,"payload":{"prompt":"Older clerks at an Ibadan insurance company avoid the new computer system because they fear they do not have the computer skills to operate it. This cause of resistance is","options":["Lack of trust in management","Lack of skills","Increased workload","Poor leadership"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Fearing that one cannot use the new technology is resistance due to lack of skills, which training can address. Option C concerns extra work, option D weak leaders, and option A doubts about management's honesty or motives."}},{"itemId":"d83878f2-c536-58c1-a3aa-0ec188bcffc8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"50cc8984-e37b-54f5-9758-516315767768","sourceKey":"bank:BUA202:CHG-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an effect of resistance to change?","options":["Low productivity","Faster implementation of the change","Poor teamwork","Industrial disputes"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Resistance slows change down; delays in implementation are one of its effects, so faster implementation is not. Options A, D and C are listed effects, along with employee dissatisfaction and reduced organisational performance."}},{"itemId":"56d846ef-c104-59ce-8dc6-4ad76496434f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"888d31ef-1b7f-5ac0-bd4c-fe35e052787d","sourceKey":"bank:BUA202:CHG-025","parentItemId":null,"revision":1,"payload":{"prompt":"As a way of managing resistance to change, counselling is used mainly to","options":["Give employees the technical skills to use new systems","Reward employees who support the change","Explain to employees why the change is necessary","Help employees adjust emotionally to the change"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Counselling helps employees cope emotionally with the change. Option A describes training, option B describes rewards, and option C describes effective communication."}},{"itemId":"7319eb41-d053-57fa-b7fc-4264028b7ac2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"84cab84d-5c04-5df7-b49b-3ed3c2f74138","sourceKey":"bank:BUA202:CHG-026","parentItemId":null,"revision":1,"payload":{"prompt":"Before introducing a new shift system, the manager of a Kano factory holds meetings where workers suggest how the shifts should be organised, and many suggestions are adopted. Which method of reducing resistance is being used?","options":["Coercion","Counselling","Rewards","Employee participation"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Allowing employees to contribute ideas is employee participation, which builds ownership of the change. Option A forces change through threats, option B helps people adjust emotionally, and option C recognises those who support the change after the fact."}},{"itemId":"b6bf6804-460d-5fb5-bf1e-354d9efd7970","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"32b58061-0fac-59bf-b036-030297226512","sourceKey":"bank:BUA202:CHG-027","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter and Schlesinger's approaches to overcoming resistance, a company that offers a union an improved severance package in return for the union's agreement to a restructuring is using","options":["Facilitation and support","Negotiation and agreement","Education and communication","Explicit and implicit coercion"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Negotiation and agreement means offering something of value in exchange for acceptance of the change, as with the severance package here. Option C relies on explaining the change, option A on emotional and practical support, and option D on threats or force."}},{"itemId":"c4295a0b-6068-5ac9-b830-ffe5f788dae0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f3dc2d51-527d-588a-b146-2dd493df9a65","sourceKey":"bank:BUA202:CHG-028","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter and Schlesinger's approaches to overcoming resistance, a manager who tells staff that anyone who refuses to adopt the new system will be transferred or lose their job is using","options":["Explicit and implicit coercion","Manipulation and co-optation","Negotiation and agreement","Participation and involvement"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Coercion forces acceptance by threatening job loss, transfer or other penalties; it is fast but risky because it breeds resentment. Option D involves staff in designing the change, option B gives resisters a token role or selective information, and option C offers incentives in exchange for agreement."}},{"itemId":"e962144b-4c26-5d3e-8c8a-7550d198cb5e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1120bf29-2a04-5516-bef0-6c78d93dbc22","sourceKey":"bank:BUA202:CHG-029","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter and Schlesinger's approaches to overcoming resistance, giving the leader of a group of resisters a visible but largely symbolic role on the change committee in order to win his endorsement is","options":["Manipulation and co-optation","Facilitation and support","Participation and involvement","Education and communication"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Co-optation gives a resistance leader a desirable role mainly to gain his endorsement, not to use his ideas, which is why it falls under manipulation and co-optation. Option D relies on explaining the case for change, option B on training and emotional support, and option C on genuinely using staff input in designing the change."}},{"itemId":"7a731188-0860-5625-b2a0-e1a0199c8eb9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1095fa0c-eb54-5056-9663-2c8d0c121f72","sourceKey":"bank:BUA202:CHG-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit of effective change management?","options":["It improves employee confidence during the change","It minimises disruptions to normal operations","It reduces employee resistance to the change","It guarantees that no employee will ever object to any change"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Change management reduces resistance but cannot guarantee that nobody will ever object. Options C, B and A are real benefits, along with improving communication, ensuring successful implementation and increasing competitiveness."}},{"itemId":"2cf2c038-bd8b-5edc-a01f-e3a8a8f377a3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9f865b95-5f23-59f8-b65b-7998b2d2f714","sourceKey":"bank:BUA202:CHG-031","parentItemId":null,"revision":1,"payload":{"prompt":"In the six-step change management process (identify the need, plan, communicate, implement, monitor progress, reinforce), the step that ensures the new practices become permanent is","options":["Plan the change","Communicate the change","Reinforce the change","Monitor progress"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Reinforcing the change, the final step, makes sure the new practices stick and become permanent. Option D checks whether objectives are being achieved, option B informs employees of the reasons and benefits, and option A develops objectives and implementation strategies."}},{"itemId":"5c397336-a3ad-54ac-a661-180826421f36","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2c5f6988-4c3f-50f0-a7cf-f7e959db8c1e","sourceKey":"bank:BUA202:CHG-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which option gives the steps of the six-step change management process in the correct order?","options":["Identify the need, plan, communicate, implement, monitor progress, reinforce","Identify the need, implement, plan, communicate, monitor progress, reinforce","Communicate, identify the need, plan, monitor progress, implement, reinforce","Plan, identify the need, implement, communicate, reinforce, monitor progress"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"The process starts by identifying why change is needed, then planning it, communicating it, implementing it, monitoring progress and finally reinforcing it. Option D plans before knowing the need, option B implements before planning, and option C communicates before the need is even identified."}},{"itemId":"46ef4b9c-e7ca-539a-94d4-10de6c2c107f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"62ab866b-0279-5751-a07f-c53a3011d195","sourceKey":"bank:BUA202:CHG-033","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos hospital has just launched a new electronic records system and is now checking, week by week, whether waiting times have fallen as planned. In the six-step change management process, which step is this?","options":["Reinforce the change","Monitor progress","Identify the need for change","Communicate the change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Checking whether objectives are being achieved after implementation is the monitor progress step. Option C comes at the very start, option A comes last and makes the change permanent, and option D comes before implementation."}},{"itemId":"cb67a3ff-d2d0-54a9-9624-49b82b24b44b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"87060ae7-62a1-5340-a736-4b7ed12958d4","sourceKey":"bank:BUA202:CHG-034","parentItemId":null,"revision":1,"payload":{"prompt":"In Lewin's change model, the unfreezing stage involves","options":["Establishing new policies and rewarding compliance","Preparing employees by explaining the need for change, creating awareness and reducing resistance","Introducing the new technology and training staff to use it","Celebrating short-term wins"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Unfreezing prepares people for change by explaining why it is needed, building awareness and lowering resistance. Option C belongs to the changing stage, option A to refreezing, and option D is a step in Kotter's model."}},{"itemId":"07b98f24-9758-52fb-80ff-d7fcebd828a1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a83269fa-5e49-5bf6-92cb-1c5767b57d22","sourceKey":"bank:BUA202:CHG-035","parentItemId":null,"revision":1,"payload":{"prompt":"A company installs a fingerprint attendance machine and trains all staff on how to clock in with it. In Lewin's model, this is the","options":["Changing (movement) stage","Unfreezing stage","Refreezing stage","Anchoring stage"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"The changing stage is where implementation actually happens, such as introducing new technology and providing training. Option B comes before, explaining why the change is needed, option C comes after, making the change permanent, and option D is Kotter's final step, not a Lewin stage."}},{"itemId":"6ff6c111-af68-5586-9438-9aa64dbb492a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1f6b426b-3efe-58b2-b0b9-30f9d0c9a760","sourceKey":"bank:BUA202:CHG-036","parentItemId":null,"revision":1,"payload":{"prompt":"Six months after a new procurement system was introduced at an Abuja agency, management writes it into the official policy manual and gives awards to units that follow it fully. In Lewin's model, this is the","options":["Urgency stage","Changing stage","Unfreezing stage","Refreezing stage"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Refreezing makes the change permanent by establishing new policies, rewarding compliance and reinforcing new behaviour. Option C prepares people before the change, option B is the implementation itself, and option A relates to Kotter's first step."}},{"itemId":"d37d799c-d045-55ad-a0d1-d399d7aad328","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"657d1384-07db-5e12-8002-7610ee75ac2b","sourceKey":"bank:BUA202:CHG-037","parentItemId":null,"revision":1,"payload":{"prompt":"Before introducing new accounting software, management at an Enugu firm holds a meeting to explain why the old system can no longer cope and why the change is necessary. In Lewin's model, this is the","options":["Refreezing stage","Short-term wins stage","Unfreezing stage","Changing stage"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Explaining why the change is needed, to prepare people and reduce resistance, is unfreezing. Option D is when the software is actually introduced, option A is when the new way is made permanent, and option B is a Kotter step."}},{"itemId":"65a67c2c-104a-58a4-8df7-09340d9c35a3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"04ceef56-1bb2-5ec3-814b-75ef364c58da","sourceKey":"bank:BUA202:CHG-039","parentItemId":null,"revision":1,"payload":{"prompt":"Lewin's force field analysis explains change in terms of","options":["Driving forces that push for change and restraining forces that resist it","Strategic, tactical and operational decisions","Expectancy, instrumentality and valence","Hygiene factors and motivators"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Force field analysis sees the current situation as a balance between driving forces for change and restraining forces against it; change happens when driving forces are strengthened or restraining forces weakened. Option D is Herzberg's theory, option C is Vroom's theory, and option B is a classification of managerial decisions."}},{"itemId":"77a072ba-3b92-5a5c-959e-51b769bee244","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f6120c82-a2e0-5abe-b508-bdca41e0407b","sourceKey":"bank:BUA202:CHG-042","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter's eight-step model, which step comes immediately after 'communicate the vision'?","options":["Develop a vision","Create short-term wins","Build a guiding coalition","Remove obstacles"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"After the vision is communicated (step 4), the next step is to remove obstacles (step 5) that hinder the change. Option B is step 6, option A is step 3, and option C is step 2."}},{"itemId":"43d7c9ad-8d3b-5ef9-a76d-6b7856ca8f36","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"834b6479-8c49-59a2-a53f-2f0d55ba9c08","sourceKey":"bank:BUA202:CHG-043","parentItemId":null,"revision":1,"payload":{"prompt":"The final step in Kotter's eight-step model is to","options":["Anchor the change in the organisation's culture","Refreeze the change","Create a sense of urgency","Sustain momentum"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Kotter's last step anchors the change by making the new practices part of the organisational culture. Option D is step 7, option C is step 1, and option B is the final stage of Lewin's model, not Kotter's."}},{"itemId":"ce4a39ca-ab17-52f1-84d1-0fea1d9099e2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e3432acc-8923-576d-97c5-315a09bb358e","sourceKey":"bank:BUA202:CHG-044","parentItemId":null,"revision":1,"payload":{"prompt":"Three months into a branch modernisation programme, the CEO of a Nigerian bank publicly celebrates the first two branches that cut customer waiting time in half. In Kotter's model, this is","options":["Create short-term wins","Anchor the change","Create a sense of urgency","Develop a vision"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Celebrating early, visible successes to build momentum is the short-term wins step. Option C comes first and shows why change is needed, option B comes last and embeds the change in the culture, and option D sets out the picture of the future."}},{"itemId":"4edfe98f-d806-53f2-9eb8-ac2c1d694134","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c6dce183-6d89-54eb-a1ec-e212c3d808b9","sourceKey":"bank:BUA202:CHG-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of Kotter's eight-step model?","options":["It is too simple for large organisations","It assumes change has a clear end with no further steps","It ignores the need to communicate a vision","It is time-consuming and requires strong leadership"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Kotter's model is detailed, so it takes time, needs strong leadership and is hard to apply in very unstable environments. Options A and B are criticisms of Lewin's model, and option C is false because communicating the vision is one of Kotter's steps."}},{"itemId":"41627890-cd0c-580b-ab04-77b568efaefa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"65783595-8ddf-5a6e-b1e6-86207ca97f89","sourceKey":"bank:BUA202:CHG-047","parentItemId":null,"revision":1,"payload":{"prompt":"A person or group who initiates, guides and takes responsibility for managing change in an organisation is called","options":["A gatekeeper","A guiding coalition of shareholders only","A line auditor","A change agent"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"A change agent is anyone, inside or outside the organisation, who acts as a catalyst for change and manages the change process. Option B is wrong because Kotter's guiding coalition is a team of influential people, not shareholders only, option A controls the flow of information, and option C is not a recognised term."}},{"itemId":"2c1afce3-ddc6-5fba-86b8-e30797759b5e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"28b8aa17-bba9-5092-9ec7-0b32bfbab5ec","sourceKey":"bank:BUA202:CHG-048","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturer hires an outside consulting firm as its change agent instead of using one of its own managers. Which is the main advantage and the main drawback of this choice?","options":["Advantage: no cost at all; drawback: too much loyalty to current managers","Advantage: deep knowledge of the firm's history; drawback: lack of objectivity","Advantage: guaranteed staff acceptance; drawback: no new ideas","Advantage: a more objective, fresh view; drawback: less knowledge of the firm's culture, history and people"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"External change agents bring objectivity and new ideas because they are not tied to internal politics, but they lack an insider's knowledge of the organisation's culture and people. Option B describes an internal change agent, option A is wrong because consultants are paid and are not bound to current managers, and option C wrongly promises acceptance and denies the fresh perspective outsiders bring."}},{"itemId":"32f63bb4-e674-5080-b95c-77776097913b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"95df1151-9e25-572a-9377-7a11cbf20359","sourceKey":"bank:BUA202:CHG-049","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian firm's change programme keeps stalling because frequent shifts in government policy and high inflation repeatedly upset its cost plans. These challenges are best described as","options":["Limited funding and inadequate technology","Corruption and poor infrastructure","Unstable government policies and economic instability","Resistance from employees and inadequate training"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Frequent policy shifts and high inflation are the challenges of unstable government policies and economic instability that Nigerian organisations face during change. Options D, B and A are also real challenges in Nigeria, but none of them describes what is happening in this scenario."}},{"itemId":"db8f59e6-8bc8-5b2d-a65e-f626dbd07bd6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ed0b7423-8343-519e-8414-7467a705e4eb","sourceKey":"bank:BUA202:CHG-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a recommended strategy for managing change in Nigerian organisations?","options":["Building trust between management and employees","Encouraging employee participation in decisions","Keeping change plans secret from staff until implementation is complete","Training employees regularly on new systems"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Hiding plans from staff undermines communication and trust, which are central to managing change well. Options D, B and A are recommended strategies, alongside improving communication, investing in technology, strengthening leadership, developing flexible policies and rewarding innovation."}},{"itemId":"f3403c88-435b-5f3a-b63f-a3171b136025","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e6afa386-f287-5fe2-b787-3ca3176aa019","sourceKey":"bank:BUA202:CUL-001","parentItemId":null,"revision":1,"payload":{"prompt":"The pattern of shared values, beliefs, assumptions and norms that shapes how members of an organisation think and behave is called","options":["organisational structure","organisational policy","organisational culture","organisational chart"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Organisational culture is the shared system of values, beliefs and assumptions that guides how people behave at work, often summed up as 'the way we do things here'. Option A is the formal arrangement of roles and reporting lines. Option D is only a diagram of that structure."}},{"itemId":"93e27ce2-1db4-5a73-b2b0-90538d8ef92c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"84245b81-fe5b-5268-b129-7d381236469d","sourceKey":"bank:BUA202:CUL-002","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational culture matters mainly because it","options":["shapes employee beliefs, behaviours and working relationships, and affects how well the organisation adapts","fixes the salaries of all employees","replaces the need for formal rules and structure","applies only to employees at the top of the hierarchy"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Culture shapes employees' beliefs, behaviours and working relationships, and can help or hinder the organisation's ability to adapt to its external environment. Option C overstates it; culture works alongside structure rather than replacing it. Option D is wrong because culture affects everyone in the organisation."}},{"itemId":"99b9a239-9799-5354-b064-d6ab7d599bb0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d5cb18cf-3b50-534e-9a24-4863fe9e7def","sourceKey":"bank:BUA202:CUL-003","parentItemId":null,"revision":1,"payload":{"prompt":"The model that describes organisational culture at three levels - artifacts, espoused values and basic underlying assumptions - was developed by","options":["Bruce Tuckman","Charles Handy","Edgar Schein","Herbert Simon"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Edgar Schein described culture as having three levels, from visible artifacts to espoused values to deeply held basic assumptions. Option A is known for the stages of group development. Option B is known for the power, role, task and person cultures."}},{"itemId":"2714baab-84d2-5127-8754-6bc90567adf0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bcbdc6bc-ebf1-5754-8702-3bd80ee239cf","sourceKey":"bank:BUA202:CUL-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which option arranges Schein's levels of organisational culture from the MOST visible to the LEAST visible?","options":["Artifacts, basic underlying assumptions, espoused values","Basic underlying assumptions, espoused values, artifacts","Artifacts, espoused values, basic underlying assumptions","Espoused values, artifacts, basic underlying assumptions"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Artifacts are the visible surface, espoused values are the stated beliefs below them, and basic underlying assumptions are the deepest, unconscious level. Option B gives the order from least to most visible. Options D and A mix up the middle and surface levels."}},{"itemId":"873e2d6a-46e9-52ac-b2f1-b38c3fdc2f14","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5bd11a3c-6abb-5c02-849d-354c781a164b","sourceKey":"bank:BUA202:CUL-005","parentItemId":null,"revision":1,"payload":{"prompt":"Visitors to a Lagos tech start-up notice open-plan offices, staff in jeans and colourful murals on the walls. In Schein's model, these are examples of","options":["artifacts","subcultures","basic underlying assumptions","espoused values"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Artifacts are the visible, tangible parts of culture such as office layout, dress, logos and ceremonies. Option D refers to the values the company states, for example in a mission statement. Option C is the deepest, taken-for-granted level that visitors cannot see."}},{"itemId":"a9022582-318c-5297-ab11-5c2ddcdfae10","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4f4a73cf-ef7b-542e-86f0-69b3198264f5","sourceKey":"bank:BUA202:CUL-006","parentItemId":null,"revision":1,"payload":{"prompt":"A bank's published code of conduct declares that 'integrity, customer focus and teamwork' are its core values. In Schein's model, these stated values belong to the level of","options":["informal organisation","artifacts","basic underlying assumptions","espoused values"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Espoused values are the strategies, goals and values an organisation openly states and claims to hold. Option B refers to visible items such as buildings, dress and logos. Option C refers to beliefs so deeply held they are taken for granted and rarely stated."}},{"itemId":"f784f1c1-16e2-5ff3-8920-62f54e89e9ed","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"44fa74fb-2d76-57c2-94ef-fee2f85869c4","sourceKey":"bank:BUA202:CUL-007","parentItemId":null,"revision":1,"payload":{"prompt":"In Schein's model, basic underlying assumptions are","options":["the logos, uniforms and office designs of the organisation","the formal rules found in the staff handbook","deeply held, taken-for-granted beliefs that are often unconscious and hard to change","the values written in the company's annual report"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Basic underlying assumptions are the deepest level of culture: beliefs so taken for granted that people rarely question or even notice them, which makes them hard to change. Option A describes artifacts. Option D describes espoused values."}},{"itemId":"4d374ce1-0cc4-5b8c-a39d-e257162e6821","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6eb6c237-d2ec-5d5b-ab6a-4fd56da93f3b","sourceKey":"bank:BUA202:CUL-008","parentItemId":null,"revision":1,"payload":{"prompt":"A strong organisational culture is one in which","options":["the core values are intensely held and widely shared by members","employees change jobs frequently","the rules are written down in great detail","there are many conflicting subcultures and no shared values"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"In a strong culture the organisation's core values are both intensely held and widely shared, so they have a big influence on behaviour. Option D describes a weak culture. Option C is about formalisation, which is different from cultural strength."}},{"itemId":"82cd876a-6764-5433-8a79-facb248a1fc8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"48b5160a-7a30-5785-af81-18ca566da8fd","sourceKey":"bank:BUA202:CUL-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is generally associated with a STRONG organisational culture?","options":["The absence of any shared values","Weak influence of shared values on employee behaviour","Constant disagreement about what the organisation stands for","Lower employee turnover, because staff agree on what the organisation stands for"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Because members share and commit to the same core values, a strong culture builds loyalty and is linked with lower employee turnover. Options C, B and A all describe a weak culture, in which values are not widely shared."}},{"itemId":"a7d8a797-a488-5862-8871-d5b6d7c933f6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"86b29069-2aa3-5c6c-ab94-dc6d932bb71e","sourceKey":"bank:BUA202:CUL-010","parentItemId":null,"revision":1,"payload":{"prompt":"A possible DISADVANTAGE of a very strong organisational culture is that it can","options":["make employees unsure of the organisation's values","become a barrier to change when the environment shifts","cause staff to have no loyalty to the organisation","increase confusion about acceptable behaviour"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Strong cultures make people cling to established ways, so they can become a barrier to change, diversity and mergers when conditions change. Options A, D and C describe problems of weak cultures, not strong ones."}},{"itemId":"89695de6-1ab4-54f2-b171-ccfc33738652","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d64f1af7-7632-5e43-8e2e-94a917de412e","sourceKey":"bank:BUA202:CUL-011","parentItemId":null,"revision":1,"payload":{"prompt":"The core values shared by a majority of an organisation's members, as opposed to values found only in particular departments, are called the","options":["counterculture","dominant culture","informal organisation","subculture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"The dominant culture expresses the core values shared by most members and gives the organisation its distinct personality. Option D is a mini-culture within a department or location. Option C is the network of unofficial relationships, not a set of values."}},{"itemId":"323277eb-b154-53f0-a6ea-b50128e30727","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8c377848-5506-5818-a599-30a7851024ad","sourceKey":"bank:BUA202:CUL-012","parentItemId":null,"revision":1,"payload":{"prompt":"Within a large Nigerian bank, the IT department has its own relaxed dress code and working style, while still sharing the bank's core values. The IT department has its own","options":["formal organisation","subculture","basic underlying assumptions for the whole bank","dominant culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"A subculture is a mini-culture within part of an organisation, reflecting that unit's common problems or experiences, while keeping the core values. Option D refers to the values shared across most of the bank. Option A refers to the officially designed structure."}},{"itemId":"e6fae596-33aa-5716-802b-4d281f5b375f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be3256c1-4897-5bb3-ae1e-553c84bc1d98","sourceKey":"bank:BUA202:CUL-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a common way employees learn an organisation's culture?","options":["Material symbols and the organisation's special language","Stories about the founder and past events","Reading the national constitution","Rituals such as award ceremonies"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Culture is passed on through stories, rituals, physical symbols (such as office layout or company cars) and language specific to the organisation. The national constitution is a legal document of a country, not a carrier of a particular company's culture. Options B, D and A are standard ways culture is transmitted."}},{"itemId":"47a827bf-89b2-5522-af84-f844c2e7f9a4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e8447ba1-962e-5153-b2e7-f28fcd2e6124","sourceKey":"bank:BUA202:CUL-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the four culture types in the Competing Values Framework?","options":["Strong, weak, dominant and sub","Formal, informal, open and closed","Power, role, task and person","Clan, adhocracy, hierarchy and market"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"The Competing Values Framework identifies clan, adhocracy, hierarchy and market cultures. Option C is Charles Handy's classification of culture, a different model. Option A mixes terms about cultural strength and subcultures."}},{"itemId":"61de0749-5504-5d1b-b922-dc648f70c462","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6284df26-bb36-58a7-ad4b-874084d9df9e","sourceKey":"bank:BUA202:CUL-017","parentItemId":null,"revision":1,"payload":{"prompt":"A culture with an external focus and flexibility that emphasises innovation, risk-taking and entrepreneurship is the","options":["hierarchy culture","adhocracy culture","clan culture","market culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"The adhocracy culture faces outward and stays flexible, encouraging innovation, risk-taking and entrepreneurship, as in software or film. Option C is flexible but internally focused on relationships. Option D is external but focused on results and competition rather than innovation."}},{"itemId":"92b81434-1abe-573e-afea-2d6b10f77bfe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9c3f4494-19eb-50db-9194-479e10c8cb8e","sourceKey":"bank:BUA202:CUL-018","parentItemId":null,"revision":1,"payload":{"prompt":"A culture with an internal focus and stability that emphasises efficiency, process, cost control and careful decision-making is the","options":["adhocracy culture","hierarchy culture","market culture","clan culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"The hierarchy culture is internally focused and controlled, emphasising efficiency, process, cost control and careful decision-making, which suits bureaucratic organisations. Option C is externally focused on competition and results. Option D is internal but flexible and people-centred."}},{"itemId":"e55ede06-920c-5259-99dd-c9b6c6f2ef0b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f7215e50-8b65-5948-b63b-c8c8cbdefcbd","sourceKey":"bank:BUA202:CUL-019","parentItemId":null,"revision":1,"payload":{"prompt":"A culture with an external focus and stability that concentrates on competing, delivering results, speed and getting things done is the","options":["adhocracy culture","clan culture","market culture","hierarchy culture"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"The market culture is externally focused and controlled, driving competition, results and speed, which suits sales-and-delivery-driven organisations. Option D shares the stability but looks inward at process. Option A shares the external focus but values flexibility and innovation."}},{"itemId":"351277e0-fe24-5604-9e13-bf170bdad322","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1c9db08e-d0da-5f51-967d-23e11d94cb31","sourceKey":"bank:BUA202:CUL-020","parentItemId":null,"revision":1,"payload":{"prompt":"A young Lagos animation studio rewards staff for experimenting with new ideas, accepts failures as part of learning and constantly launches new products. Its culture is best described as","options":["market culture","hierarchy culture","clan culture","adhocracy culture"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Innovation, experimentation and risk-taking with an outward focus are the marks of an adhocracy culture, common in fast-paced creative industries. Option B would stress rules, process and cost control. Option A would stress beating competitors and hitting sales targets."}},{"itemId":"6a232d1c-ad38-5b50-9dbc-b4692154c0b8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"482db634-7f09-5230-94c9-f840701e18b9","sourceKey":"bank:BUA202:CUL-021","parentItemId":null,"revision":1,"payload":{"prompt":"A government parastatal in Abuja runs on detailed procedures, multiple approval levels and strict cost control, and staff are rewarded for following process carefully. Its culture is best described as","options":["market culture","hierarchy culture","clan culture","adhocracy culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"An internal focus on process, efficiency, cost control and careful decisions is the hierarchy culture, typical of bureaucratic organisations. Option D would favour risk-taking and innovation. Option A would emphasise winning customers and results speed over procedure."}},{"itemId":"205ed7b1-0386-5915-860c-0e31e04dff32","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e346c62c-8da5-5a42-bc62-a2696632dc44","sourceKey":"bank:BUA202:CUL-022","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian beverage distributor ranks its sales teams weekly, pays large bonuses for beating targets and talks constantly about taking market share from rivals. Its culture is best described as","options":["hierarchy culture","clan culture","adhocracy culture","market culture"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"An external, results-driven focus on competing, hitting targets and speed is the market culture. Option B would put relationships and mentoring first. Option A would focus inward on process and rules rather than beating rivals."}},{"itemId":"1d2247fb-8721-580c-8898-f5dcab4d0e7d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f7bf71cf-7ccd-5259-945d-9328725ca7a1","sourceKey":"bank:BUA202:CUL-023","parentItemId":null,"revision":1,"payload":{"prompt":"In Charles Handy's classification of culture, a culture in which power is concentrated in one central figure, often the founder, and is pictured as a spider's web is the","options":["task culture","person culture","role culture","power culture"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Handy's power culture radiates from a central person, like a spider at the centre of a web, which is common in small owner-managed firms. Option C is based on rules, procedures and job roles. Option A is built around project teams and expertise."}},{"itemId":"3b7f0aca-996d-56e1-9273-224f74d2622f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"28cae736-ff00-5bdc-a202-8e4145f84e2b","sourceKey":"bank:BUA202:CUL-024","parentItemId":null,"revision":1,"payload":{"prompt":"In Handy's classification, a culture built on clearly defined job roles, rules and procedures, typical of large bureaucracies and civil services, is the","options":["power culture","task culture","person culture","role culture"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"The role culture relies on formal roles, rules and procedures, and power comes from one's position; Handy pictured it as a Greek temple. Option A centres on one powerful person. Option B organises work around project teams."}},{"itemId":"1feb8597-1939-5234-9620-ec1cda1915c6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9dabafa2-bf3c-52aa-b351-633ffea8ec6d","sourceKey":"bank:BUA202:CUL-025","parentItemId":null,"revision":1,"payload":{"prompt":"In organisational behaviour, power is best defined as","options":["the formal job title a person holds","the total number of subordinates a manager supervises","the capacity of one person to influence the behaviour of another","the amount of money a person earns"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Power is the capacity to influence the behaviour of others, so that they act in ways they otherwise would not. Option A is only one possible basis of power, legitimate position. Options B and D may be linked to power but do not define it."}},{"itemId":"af5a8c08-10a7-57e2-a101-e9d54be5f44a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ec9a1266-f989-5e96-9be9-5444ef765752","sourceKey":"bank:BUA202:CUL-026","parentItemId":null,"revision":1,"payload":{"prompt":"The typology of five bases of power - reward, coercive, legitimate, expert and referent - was developed by","options":["Tuckman and Jensen","French and Raven","Cameron and Quinn","Herbert Simon"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"John French and Bertram Raven identified the five bases of social power. Option A is linked to the stages of group development. Option C is linked to the Competing Values Framework of culture."}},{"itemId":"a3772573-5b65-5e98-9ac7-9c045c166eaf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2b840304-074b-510f-bc07-d95c07e18016","sourceKey":"bank:BUA202:CUL-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of French and Raven's five bases of power?","options":["Charismatic power","Legitimate power","Referent power","Expert power"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"French and Raven's five bases are reward, coercive, referent, expert and legitimate power. Charisma is usually discussed under referent power, but 'charismatic power' is not one of the five named bases. Options C, D and B are all in the typology."}},{"itemId":"6ad93feb-7f70-5791-9693-8838b3a69bae","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8a0b42b9-a1bc-5fa5-8ce2-889ac84e17a7","sourceKey":"bank:BUA202:CUL-028","parentItemId":null,"revision":1,"payload":{"prompt":"Power based on the belief that a person can grant desired outcomes such as money or recognition is called","options":["legitimate power","coercive power","reward power","referent power"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Reward power rests on the ability to give things people value, such as pay rises, bonuses or recognition. Option B is the opposite, the ability to punish. Option A rests on the right that comes with a position."}},{"itemId":"cc62fd16-9c64-5f7c-b77f-55ae1fec2db1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"251311f3-3e4e-58f0-9aae-b7aaf82728b3","sourceKey":"bank:BUA202:CUL-029","parentItemId":null,"revision":1,"payload":{"prompt":"Power based on the belief that a person can punish others, by inflicting harm or withholding something they value, is called","options":["reward power","coercive power","legitimate power","expert power"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Coercive power depends on fear of punishment, such as a query, demotion or withheld bonus. Option A depends on granting desired outcomes. Option D depends on specialised knowledge."}},{"itemId":"57da69a5-d3b4-5953-9346-002911b2eb2e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"85bd3df2-9d63-5dd2-97b5-8f9b1bb1705e","sourceKey":"bank:BUA202:CUL-030","parentItemId":null,"revision":1,"payload":{"prompt":"Power based on the belief that a person has the 'right' to influence others by virtue of their position or role is called","options":["expert power","legitimate power","reward power","referent power"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Legitimate power comes from a formal position, so subordinates accept that the holder has the right to give instructions. Option D comes from others admiring and wanting to identify with the person. Option A comes from specialised knowledge."}},{"itemId":"4cabed62-a7fa-5483-94a0-5df72eb348a1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"244ebaab-a7df-5d0a-986a-4f3ecf2b7582","sourceKey":"bank:BUA202:CUL-031","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a Lagos hospital follow the advice of a junior IT officer on cybersecurity because she is the only one who understands the new system. She is using","options":["legitimate power","coercive power","expert power","reward power"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Expert power is based on the belief that a person has, and is willing to share, needed knowledge, regardless of rank. Option A would require a senior position, which she does not hold. Options B and D involve punishing or rewarding, which she cannot do."}},{"itemId":"8c26dfa8-378d-542a-b504-115ed7cb7134","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"732a44ab-549f-5447-b0b7-94892f6e29d2","sourceKey":"bank:BUA202:CUL-032","parentItemId":null,"revision":1,"payload":{"prompt":"Young employees at a Nigerian media company copy the dress and work habits of a popular, admired colleague and want to be accepted by her, although she has no formal authority over them. Her influence comes from","options":["referent power","coercive power","expert power","legitimate power"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Referent power is based on others wanting to associate with or be accepted by a person they admire. Option D requires formal position, which she lacks. Option C would require specialised knowledge to be the reason they follow her."}},{"itemId":"08507be0-bc62-5d0d-b777-5d6c9d331b27","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b4f607aa-022b-593d-975c-db030a8b5beb","sourceKey":"bank:BUA202:CUL-033","parentItemId":null,"revision":1,"payload":{"prompt":"A factory supervisor in Agbara tells workers that anyone who arrives late will lose a day's pay. The supervisor is relying mainly on","options":["coercive power","referent power","expert power","reward power"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Threatening to withhold pay is a form of punishment, so the supervisor is using coercive power. Option D would involve offering something desirable for good behaviour. Option B depends on admiration rather than threats."}},{"itemId":"d0ea8216-46e2-53dc-8e27-0006e91eb98a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9181fd2c-df48-5851-8bff-21e822bdbb73","sourceKey":"bank:BUA202:CUL-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which bases of power tend to produce GENUINE COMMITMENT from followers?","options":["Coercive and reward power","Coercive and legitimate power","Legitimate and reward power","Referent and expert power"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Referent and expert power come from the person rather than the position, and they tend to produce genuine commitment. Reward and legitimate power produce mixed results, while coercive power often brings mere compliance with resentment. So options B, A and C all include bases that do not reliably produce commitment."}},{"itemId":"d2ea5949-7182-5d38-9a8f-b169a682b05f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"523e1f91-f7b3-5bae-bc0d-3e1b76c9fa01","sourceKey":"bank:BUA202:CUL-035","parentItemId":null,"revision":1,"payload":{"prompt":"Heavy reliance on coercive power by a manager is most likely to result in","options":["higher job satisfaction across the team","admiration and a desire to imitate the manager","mere compliance along with resentment and resistance","strong personal commitment from followers"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Coercive power often produces only compliance, and it breeds resentment and resistance. Option D is the typical result of referent or expert power. Option B describes the basis of referent power, not a result of threats."}},{"itemId":"c2811e90-80ff-529a-8b2f-e91430190328","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ada58214-6689-531c-bb4b-10740db5f58d","sourceKey":"bank:BUA202:CUL-036","parentItemId":null,"revision":1,"payload":{"prompt":"Of French and Raven's bases, which two are usually classed as PERSONAL power, coming from the individual rather than from the position held?","options":["Expert and referent power","Reward and coercive power","Legitimate and reward power","Coercive and legitimate power"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Expert and referent power come from a person's own knowledge or attractiveness, so they move with the person if he changes jobs. Legitimate, reward and coercive power come from the formal position, so options C, D and B are positional (formal) power."}},{"itemId":"5e09572e-3a28-56e3-bbe5-114878b808fd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"629fc3be-06e1-51fe-aed0-ab4ac9b7dd6d","sourceKey":"bank:BUA202:CUL-037","parentItemId":null,"revision":1,"payload":{"prompt":"Political behaviour in organisations is best described as activities that","options":["follow the official chain of command at all times","are not part of one's formal role but influence, or try to influence, the distribution of advantages and disadvantages","involve campaigning for national elections during office hours","are required by the job description and approved by management"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Organisational politics covers actions outside one's formal role used to gain or protect advantages, such as forming alliances or controlling information. Option D describes normal job duties. Option C confuses workplace politics with party politics."}},{"itemId":"4bded9fd-0864-5fdf-9140-948d503b9551","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f4432003-4a4e-5899-8d53-20adee3feebc","sourceKey":"bank:BUA202:CUL-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of LEGITIMATE rather than illegitimate political behaviour?","options":["Forming a coalition with colleagues to support a budget proposal","Hiding files that a co-worker needs","Sabotaging a rival's project","Spreading false rumours about a colleague"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Legitimate political behaviour is everyday politicking such as forming coalitions, lobbying or complaining to a supervisor. Options C, D and B are illegitimate because they violate the implied rules of the game and harm others."}},{"itemId":"21237ca1-7856-51b6-a64c-b058b5f4e371","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3612e7ff-76d7-517a-8f25-5d4a811565d8","sourceKey":"bank:BUA202:CUL-039","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following organisational conditions is most likely to INCREASE political behaviour?","options":["Scarce resources and unclear performance evaluation","Abundant resources and clear goals","High trust and objective performance measures","Clear roles and transparent reward systems"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Politics grows when resources are scarce, goals or roles are ambiguous and performance evaluation is unclear, because people compete for advantage. Options B, C and D describe conditions that reduce the need for political behaviour."}},{"itemId":"020907aa-a5e4-5a25-9a58-3a4cc8de6e9f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ac03ce63-1b42-56a2-bbc8-bc33e5abe57b","sourceKey":"bank:BUA202:CUL-040","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which individuals attempt to control the impression others form of them is called","options":["impression management","the halo effect","social loafing","coercive power"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"Impression management covers tactics such as flattery, self-promotion and conforming to opinions to shape how others see you. Option B is a perceiver's error, not something the target does. Option C is reduced effort in groups."}},{"itemId":"29ee436d-b1ce-512c-a1c7-2fc7ae3c08dd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"033ece0a-fe2b-5f9c-91ef-d68db255339b","sourceKey":"bank:BUA202:CUL-041","parentItemId":null,"revision":1,"payload":{"prompt":"Before a promotion exercise, an officer in a Lagos firm repeatedly praises his manager's ideas and agrees with everything she says to win her favour. This political tactic is","options":["exchange","coalition building","rational persuasion","ingratiation"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Ingratiation is using flattery, praise or friendliness to win favour before making a request. Option B involves enlisting others' support. Option C relies on logical arguments and facts."}},{"itemId":"e6eaa36b-281e-50b7-9fc8-bf49e1eb3f9b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a3ed43e1-d966-5d3e-8493-e77fe0eeb715","sourceKey":"bank:BUA202:CUL-042","parentItemId":null,"revision":1,"payload":{"prompt":"The formal organisation is best described as","options":["the officially designed structure of roles, reporting lines and communication channels set up by management","the social clubs employees join after work","the grapevine through which rumours spread","the network of friendships that forms naturally among employees"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"The formal organisation is what management deliberately designs: roles, reporting lines and official channels. Options D, C and B are all parts of the informal organisation, which emerges naturally."}},{"itemId":"462a2448-91a7-5372-9110-7d6970019779","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"35f04167-4fee-53bd-8647-6bd7aef6ee9c","sourceKey":"bank:BUA202:CUL-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best captures the relationship between the formal and the informal organisation?","options":["The informal organisation only hinders work and should be abolished","The formal organisation shows how the organisation is supposed to function; the informal organisation shows how it actually functions","The informal organisation is designed by management; the formal one emerges naturally","The two are identical in every organisation"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"The formal organisation is designed and describes how work is supposed to happen, while the informal organisation emerges from daily relationships and reflects how work actually gets done. Option C reverses the two. Option A is wrong because the informal organisation can help as well as hinder work."}},{"itemId":"24f9c825-8f53-576a-9100-793cc848ab60","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c654e1af-376b-5bf0-a27c-3840a470113f","sourceKey":"bank:BUA202:CUL-044","parentItemId":null,"revision":1,"payload":{"prompt":"In a Nigerian manufacturing firm, staff often go to a long-serving storekeeper, not their supervisors, to find out how to get things done quickly, through his network of friends across departments. This shows the influence of the","options":["legitimate power of the storekeeper","hierarchy culture","informal organisation","formal organisation"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"The storekeeper's influence comes from unofficial relationships that emerged over time, which is the informal organisation at work. Option D would route requests through official reporting lines. Option A is wrong because his position gives him no formal authority over these staff."}},{"itemId":"e9fb1d28-b36d-52bc-b673-9366a0b9115c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9fc56196-56d2-56ef-a871-95cf72a68e45","sourceKey":"bank:BUA202:CUL-045","parentItemId":null,"revision":1,"payload":{"prompt":"In workplace diversity, which of the following is an example of DEEP-LEVEL diversity?","options":["Differences in age","Differences in gender","Differences in ethnic background","Differences in values, personality and work preferences"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Deep-level diversity refers to differences in values, personality and work preferences, which become clear only as people get to know each other. Options A, B and C are surface-level diversity, which is visible or easily known demographic differences."}},{"itemId":"fff737b3-713c-5b3c-9ab2-107c32c86d6e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e5cd072e-f037-54e4-94b9-5b3470224f59","sourceKey":"bank:BUA202:DEC-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of identifying a choice among alternative courses of action is known as","options":["controlling","problem diagnosis","decision-making","planning"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Decision-making is the process of identifying a choice among alternative courses of action, so it always involves picking between options. Option D is about setting objectives, which uses decisions but is a wider management function. Option B is only one step inside the decision process, where causes are investigated."}},{"itemId":"f984eecf-93dd-5db7-8145-f58ab8e74ff1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"60880117-f9d2-5476-b20e-cf74da072e77","sourceKey":"bank:BUA202:DEC-002","parentItemId":null,"revision":1,"payload":{"prompt":"A decision situation exists when certain conditions are present. Which of the following is NOT one of those conditions?","options":["More than one course of action is possible","All the relevant information about every option is available","A choice among the courses of action must be made","A problem or opportunity has been identified"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"A decision exists when a problem or opportunity is identified, more than one course of action is possible and a choice must be made. Complete information is not required; in fact managers rarely have it, which is why bounded rationality exists. Options D, A and C are exactly the three conditions."}},{"itemId":"e661de65-173a-5add-850b-29aa68517bfd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ac47fea3-7818-5458-8b66-251df34dd10a","sourceKey":"bank:BUA202:DEC-003","parentItemId":null,"revision":1,"payload":{"prompt":"The owner of a Yaba bakery has only one supplier of flour in the area and no other way to get flour. Strictly speaking, why is there no real decision to make about the flour supplier?","options":["The owner lacks complete information","No problem or opportunity has been identified","The situation involves risk rather than certainty","Only one course of action is possible"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"A decision requires more than one possible course of action; with only one supplier and no alternative, there is nothing to choose between. Option B is wrong because the need for flour is clearly identified. Option A is wrong because incomplete information does not stop a decision from existing; it only makes it harder."}},{"itemId":"e0d4220e-04c5-5bf9-b301-a8d66250531f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0326daba-7d12-5ac6-b3c2-b188904840f6","sourceKey":"bank:BUA202:DEC-004","parentItemId":null,"revision":1,"payload":{"prompt":"When decision-making is linked to the four functions of management, the question 'What corrective action is required?' belongs to which function?","options":["Leading","Controlling","Planning","Organising"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Controlling compares results with plans and decides what corrective action is required. Option C asks what objectives should be pursued, option D asks how resources should be arranged, and option A asks how employees should be motivated."}},{"itemId":"49e3a7e5-a973-5040-8db4-51bf3a19ceba","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"aea2443e-1a9a-5024-93d3-77e77a2d1a86","sourceKey":"bank:BUA202:DEC-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing of a management function with its typical decision question is CORRECT?","options":["Planning - What corrective action is required?","Organising - How should resources be arranged?","Controlling - How should employees be motivated?","Leading - Which objectives should be pursued?"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Organising is about arranging resources, so its decision question is how resources should be arranged. Option A wrongly gives planning the controlling question; planning asks which objectives to pursue. Options D and C also swap the questions between functions."}},{"itemId":"fe66d7b5-5107-51aa-82c3-0224cdcea477","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4e6fc91b-e5d5-5c2b-9024-fb3d2748d9bb","sourceKey":"bank:BUA202:DEC-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of strategic decisions?","options":["They are associated with significant uncertainty","They are routine and easy to reverse","They are complex","They are long-term in nature"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Strategic decisions are long-term, complex, often difficult to reverse and associated with significant uncertainty. Being routine and easy to reverse is the opposite, and describes programmed day-to-day decisions. Options D, C and A are all genuine characteristics of strategic decisions."}},{"itemId":"edac660f-9412-57d6-bcae-2528e7d8201e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fed407f3-8593-589b-8e34-9d4d4439462b","sourceKey":"bank:BUA202:DEC-007","parentItemId":null,"revision":1,"payload":{"prompt":"The board of a Lagos-based fintech decides to expand operations into Ghana and Kenya over the next five years. This is best classified as","options":["a tactical decision","a programmed decision","an operational decision","a strategic decision"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Deciding whether to expand or diversify concerns the overall long-term direction of the company and is taken by the board, so it is strategic. Option A would be how each department plans to support the expansion. Option B is wrong because a first-time expansion is unique and unfamiliar, not routine."}},{"itemId":"18c4a0e7-3118-5fa2-8429-22045da7d4dd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7c74e737-e03f-5d99-8bfc-98014db6b7c9","sourceKey":"bank:BUA202:DEC-008","parentItemId":null,"revision":1,"payload":{"prompt":"After the board of a Nigerian supermarket chain decides to grow market share, the head of marketing draws up a six-month departmental promotion plan to support that goal. The head of marketing's decision is","options":["a non-programmed strategic decision","a strategic decision","a tactical decision","an operational decision"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Tactical decisions translate strategic objectives into departmental plans and are made by middle managers or heads of departments. Option B is the board's original choice to grow market share. Option D would be day-to-day matters such as which cashier works which shift."}},{"itemId":"ce1f9e56-f9f0-5c8f-8063-cab2124f671d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"17a1e008-220e-524a-95d9-28facec8dcaf","sourceKey":"bank:BUA202:DEC-009","parentItemId":null,"revision":1,"payload":{"prompt":"A shift supervisor at a Dangote cement depot decides which loaders will work the morning shift today. This is","options":["a non-programmed decision","a strategic decision","a tactical decision","an operational decision"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Operational decisions concern the day-to-day functioning of the organisation and are made by supervisors and frontline managers. Option B is about long-term direction set at the top. Option C is a middle-level departmental plan, not a daily staffing choice."}},{"itemId":"52700fd5-6b6d-5957-8245-073dc5872d54","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9a6c8dbf-fe0d-5d2f-879a-114d45822460","sourceKey":"bank:BUA202:DEC-010","parentItemId":null,"revision":1,"payload":{"prompt":"Non-programmed decisions are best described as decisions that are","options":["made only by first-line managers on a daily basis","unique, complex and unfamiliar, requiring judgement, creativity and analysis","routine and repetitive, handled by standard operating procedures","made by following rules written in the staff handbook"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Non-programmed decisions are unique, complex and unfamiliar, so no ready rule exists and managers must use judgement, creativity and analysis. Options C and D describe programmed decisions. Option A wrongly ties them to one level; first-line managers mostly make routine decisions."}},{"itemId":"ab2f8c6c-b89c-5143-b4cd-32d1ad82b812","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fd3e98e7-9a83-5657-b69a-3bd65b6dfa0b","sourceKey":"bank:BUA202:DEC-011","parentItemId":null,"revision":1,"payload":{"prompt":"A bank's staff handbook states exactly how many days of annual leave each grade of staff receives. A request for annual leave handled under this rule is an example of","options":["a programmed decision","a non-programmed decision","a decision under uncertainty","a strategic decision"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Leave requests are routine and repetitive, and the handbook already sets the rule, so this is a programmed decision. Option B would apply to a new, unfamiliar problem with no rule. Option D concerns long-term direction, not routine staff administration."}},{"itemId":"1320afb1-8bd8-59b0-b6f7-2b5e3f8e9955","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"df35dbdf-6412-5c03-980a-0cd130af4270","sourceKey":"bank:BUA202:DEC-012","parentItemId":null,"revision":1,"payload":{"prompt":"In the eight-step managerial decision-making process, which step comes immediately AFTER establishing decision criteria?","options":["Diagnose the problem","Generate alternatives","Select an alternative","Evaluate alternatives"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"The order is identify, diagnose, establish criteria, generate alternatives, evaluate alternatives, select, implement and evaluate the outcome. So once criteria are set, alternatives are generated. Option D cannot come next because there is nothing to evaluate until alternatives exist; option A comes before the criteria."}},{"itemId":"a7102cb9-ddd4-521d-a51e-99aff755972a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"82b4039b-8706-57f5-8a9c-e670740da124","sourceKey":"bank:BUA202:DEC-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following shows the correct order of these four steps of the decision-making process?","options":["Establish decision criteria - Diagnose the problem - Implement the decision - Evaluate alternatives","Evaluate alternatives - Diagnose the problem - Establish decision criteria - Implement the decision","Diagnose the problem - Establish decision criteria - Evaluate alternatives - Implement the decision","Diagnose the problem - Evaluate alternatives - Establish decision criteria - Implement the decision"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Causes are diagnosed first, then criteria are set, then alternatives are evaluated against those criteria, and only then is the chosen option implemented. Option D evaluates alternatives before criteria exist, which is impossible because alternatives are judged by the criteria. Options A and B also put diagnosis in the wrong place."}},{"itemId":"ddd82aa4-2ad3-5556-b310-d976057a19f8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"557404d8-29c3-5681-8cad-cfc648a37d63","sourceKey":"bank:BUA202:DEC-015","parentItemId":null,"revision":1,"payload":{"prompt":"The step of the decision-making process in which the manager investigates the causes of the problem is called","options":["identifying the problem","establishing decision criteria","diagnosing the problem","evaluating alternatives"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Diagnosis means investigating the causes, for example what changed, when and in which department. Option A only notices that something needs attention. Option B decides which factors will be used to judge options."}},{"itemId":"4c1afc01-707c-5cbf-9e74-37a03631cf4f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"19331c67-6423-541a-a8a0-420c16cdc21a","sourceKey":"bank:BUA202:DEC-016","parentItemId":null,"revision":1,"payload":{"prompt":"Sales at a Kano beverage distributor have fallen for three months. The manager first says, 'The fall in sales is only what we can see; I need to find what is really causing it.' Which idea is the manager applying?","options":["Anchoring on the first information","Escalation of commitment","Distinguishing symptoms from the underlying problem","Satisficing"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"A drop in sales is a symptom, not the problem itself, so a good manager looks past it to the root cause, just as headache is a symptom of malaria. Option B is continuing a failing course because of past investment. Option D is accepting a good-enough choice, which is not what the manager is doing here."}},{"itemId":"c8c98d6d-2c1b-5868-bedb-74d8a69e0a91","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a7a1d181-681f-5b0c-8d1b-654cf07fbb41","sourceKey":"bank:BUA202:DEC-017","parentItemId":null,"revision":1,"payload":{"prompt":"In the decision-making process, 'establishing decision criteria' means","options":["checking whether the decision solved the problem","determining what factors will be used to evaluate alternatives","choosing the option considered most appropriate","listing every possible course of action"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Decision criteria are the factors, such as cost, quality, speed, risk and ethics, against which alternatives will be judged. Option D is generating alternatives. Option C is selecting an alternative and option A is evaluating the outcome."}},{"itemId":"18de6a90-2772-521e-8cad-c4c23db55b8d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"31e13d84-65a8-50b8-ad51-072ee6879c2c","sourceKey":"bank:BUA202:DEC-018","parentItemId":null,"revision":1,"payload":{"prompt":"Implementing a decision requires several things. Which of the following is NOT one of them?","options":["Unanimous approval from all shareholders","Communication","Clear responsibility and timelines","Resources"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Implementation requires resources, communication, responsibility and timelines so that the chosen option is actually carried out. Shareholder approval is not a general requirement for implementing managerial decisions. Options D, B and C are all listed requirements."}},{"itemId":"3fd85c18-a031-5137-871a-3071da0d5bed","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3a2cd9a6-367f-5ce6-9aa3-74e3d27de2df","sourceKey":"bank:BUA202:DEC-019","parentItemId":null,"revision":1,"payload":{"prompt":"A state government rewards a young man with a car for rescuing a child from a canal. Within weeks, several people stage fake rescues hoping for similar rewards. The fake rescues are best described as","options":["the decision criteria","a programmed decision","satisficing behaviour","unintended consequences of the decision"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"The government did not plan for copycat stunts, so they are unintended consequences, which the final step of evaluating outcomes is meant to catch. Option A refers to factors used to judge alternatives before choosing. Option C means accepting a good-enough option, which is unrelated."}},{"itemId":"61ae7ac8-20f8-583e-8e1c-b7853cf3c6c3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f5d5d1dc-f12d-5e26-af5d-a23257bd778c","sourceKey":"bank:BUA202:DEC-021","parentItemId":null,"revision":1,"payload":{"prompt":"The rational decision-making model is often presented as which sequence?","options":["Choice - Problem identification - Alternatives - Evaluation - Implementation - Evaluation","Problem identification - Alternatives - Evaluation - Choice - Implementation - Evaluation","Problem identification - Choice - Alternatives - Implementation - Evaluation - Evaluation","Alternatives - Problem identification - Choice - Evaluation - Implementation - Evaluation"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"The model moves logically from identifying the problem to listing alternatives, evaluating them, choosing, implementing and finally evaluating results. Option C makes the choice before alternatives exist. Options D and A also start in the wrong place."}},{"itemId":"42dad884-f864-5995-a443-f6503877306d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6b8aae8b-2c18-5c3c-88bf-5b4a9fd0aebc","sourceKey":"bank:BUA202:DEC-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a strength of the rational decision-making model?","options":["It lets managers rely on gut feeling when data is scarce","It encourages systematic analysis and reduces impulsive decisions","It assumes managers have limited time and information","It removes the need to evaluate the outcome afterwards"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"The rational model encourages systematic analysis, reduces impulsive decisions and provides a structured process. Option C is the opposite of its assumptions. Option A is not a feature of a fact-based model, and option D is wrong because the model ends with evaluation."}},{"itemId":"16c9ac2f-397b-59ba-861d-d6d958c8d697","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fcdc4b54-2751-53c9-bcb9-4a4dea3884bf","sourceKey":"bank:BUA202:DEC-024","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of bounded rationality is associated with","options":["Henri Fayol","Abraham Maslow","Kurt Lewin","Herbert Simon"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Herbert Simon introduced bounded rationality, the idea that decision-makers work under limits such as incomplete information and limited cognitive capacity. Option A is known for the principles and functions of management. Option B is known for the hierarchy of needs and option C for the unfreeze-change-refreeze change model."}},{"itemId":"5af00501-37f7-5780-b7d3-cf2d830ea1b5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bd38969e-073e-525d-a1e4-676089e9d229","sourceKey":"bank:BUA202:DEC-025","parentItemId":null,"revision":1,"payload":{"prompt":"Selecting an option that is good enough or satisfactory, because the absolute best solution cannot be identified, is called","options":["escalation of commitment","optimising","satisficing","anchoring"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Satisficing means settling for a satisfactory, good-enough option, which is what managers do under bounded rationality. Option B means finding the single best solution, which the rational model assumes. Option A is a bias about continuing a failing project."}},{"itemId":"c636f129-2a97-5c54-894d-80726d900b57","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"633825f8-07fc-5ae1-b376-47b4d722cd4a","sourceKey":"bank:BUA202:DEC-026","parentItemId":null,"revision":1,"payload":{"prompt":"Bounded rationality recognises that decision-makers operate under limitations. Which of the following is NOT one of those limitations?","options":["Time pressure","Unlimited access to reliable information","Limited cognitive capacity","Organisational constraints"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Bounded rationality lists incomplete information, limited cognitive capacity, time pressure, uncertainty and organisational constraints. Unlimited access to reliable information is the opposite of a limitation; it is an assumption of the rational model. Options C, A and D are all genuine limitations."}},{"itemId":"5534ef26-8aa5-5c63-98e3-8b6431845bb6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b6a1ddc1-45c1-56f3-89ff-f6f779d9204f","sourceKey":"bank:BUA202:DEC-027","parentItemId":null,"revision":1,"payload":{"prompt":"A procurement officer at a Port Harcourt oil-servicing firm needs a generator within two days. She checks three vendors and buys from the first one that meets the budget and power rating, without searching further. Her approach is an example of","options":["satisficing under bounded rationality","the rational model's search for the best option","escalation of commitment","confirmation bias"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Under time pressure she accepts the first option that meets her minimum standards, which is satisficing, a direct result of bounded rationality. Option B would require identifying and comparing all alternatives to find the best. Option C involves sticking with a failing course because of past investment, which is not the case here."}},{"itemId":"21f5f081-4064-5ebb-a6b1-765a8ed6ed2d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"50b68114-a215-5481-8c0e-8e77ae676a2b","sourceKey":"bank:BUA202:DEC-028","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency to seek information that supports one's existing beliefs is called","options":["confirmation bias","overconfidence bias","availability bias","anchoring bias"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Confirmation bias is seeking information that supports what you already believe while disregarding contradicting evidence. Option D is relying too heavily on the first information received. Option C is relying on information that is easily recalled."}},{"itemId":"a460517e-0e9f-5291-a9ac-3f6a3b698555","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bb452b2d-dc15-53cb-920d-d0f3394d0d4b","sourceKey":"bank:BUA202:DEC-029","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier first quotes N9 million for a delivery van. Even after the admin manager learns that similar vans sell for about N6 million, he negotiates only down to N8.5 million, still treating N9 million as his reference point. This illustrates","options":["escalation of commitment","satisficing","anchoring bias","availability bias"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"The first quote of N9 million anchored his judgement, so he relied too heavily on it even after better price information became available. Option D would involve a vivid, easily recalled example. Option A would involve continuing to pour money into a failing project."}},{"itemId":"c926c50e-6a11-5691-9980-93a3d7356ad0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"042fcd87-8656-5ff3-a0a0-089f11463d7a","sourceKey":"bank:BUA202:DEC-030","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian logistics company has already spent N40 million on a tracking app that keeps failing. The MD approves another N15 million, arguing, 'We have spent too much to stop now.' Which bias is this?","options":["Escalation of commitment","Confirmation bias","Availability bias","Anchoring bias"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Escalation of commitment is continuing to invest in a failing project because resources have already been invested; the N40 million is a sunk cost. Option D is about over-relying on the first information received. Option B is about seeking only supporting information, which is not the MD's stated reason."}},{"itemId":"befab512-85a4-50c8-87e9-9203b701d730","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2856f0f5-9bd2-5fc8-a827-8296bb3cb829","sourceKey":"bank:BUA202:DEC-031","parentItemId":null,"revision":1,"payload":{"prompt":"After a widely shared video of a robbery at an ATM, a branch manager concludes that ATM robberies are now the bank's biggest risk, although records show card fraud causes far greater losses. This illustrates","options":["availability bias","anchoring bias","overconfidence bias","escalation of commitment"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Availability bias is judging likelihood by how easily a vivid or recent example comes to mind rather than by actual probability, like fearing shark attacks more than falling coconuts. Option B would require sticking to the first piece of information received. Option C is overestimating one's own knowledge or ability."}},{"itemId":"800a8d87-c32b-567e-afba-20bd520e2017","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b44b3fe9-ca9b-5530-9010-97757fa38fb6","sourceKey":"bank:BUA202:DEC-032","parentItemId":null,"revision":1,"payload":{"prompt":"A new sales manager in Abuja refuses to look at market research because he is sure his ten years of experience tell him exactly what customers want. He is showing","options":["escalation of commitment","availability bias","overconfidence bias","anchoring bias"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Overconfidence bias is the tendency to overestimate one's own knowledge or ability, which leads him to dismiss data. Option B would involve relying on an easily recalled event. Option A would involve relying on the first information he received."}},{"itemId":"ab0e7508-e60b-5eaf-a3e4-f6776501e949","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"36ef099b-73c8-5877-bf33-436c698404b8","sourceKey":"bank:BUA202:DEC-033","parentItemId":null,"revision":1,"payload":{"prompt":"In decision-making, a situation of RISK exists when","options":["the manager has no information at all about the future","the outcome of every alternative is known in advance","possible outcomes are difficult to identify and probabilities cannot be calculated","possible outcomes can be identified and their probabilities can reasonably be estimated"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Risk exists when the possible outcomes are known and probabilities can reasonably be estimated, for example from past experience, which is why insurance can exist. Option C defines uncertainty. Option B describes certainty, where there is no doubt about outcomes."}},{"itemId":"9a21573b-1ac3-59b7-814d-4e5199d6c8b7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3c08ab16-7f80-5684-84e9-2b582ed14807","sourceKey":"bank:BUA202:DEC-034","parentItemId":null,"revision":1,"payload":{"prompt":"A decision is said to be made under conditions of CERTAINTY when","options":["neither the outcomes nor their probabilities can be identified","the decision is routine and covered by a staff handbook","probabilities of outcomes can be estimated but the result is unknown","the decision-maker knows the exact outcome of each alternative in advance"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Certainty means the outcome of each alternative is known, for example a fixed-rate deposit with a guaranteed return. Option C describes risk and option A describes uncertainty. Option B describes a programmed decision, which is a different classification."}},{"itemId":"f49d7a52-ebdb-57fa-aaa3-fc6c7cf3af7f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"076b485c-7917-54de-97d4-d62ff0d17f7b","sourceKey":"bank:BUA202:DEC-035","parentItemId":null,"revision":1,"payload":{"prompt":"Bag A contains 100 balls: 40 red and 60 black. Bag B also contains 100 red and black balls, but the mix is not disclosed. A player who must guess the colour drawn from Bag B faces","options":["certainty, because there are only two colours","risk, because the probabilities are known exactly","risk, because there are 100 balls in the bag","uncertainty, because no meaningful probability can be assigned"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"With Bag B the ratio is hidden, so no meaningful probability can be assigned, which is uncertainty. Bag A is the risk case, because the 40:60 ratio lets you estimate a probability. Option A is wrong because knowing there are two colours does not tell you the outcome."}},{"itemId":"35487dd0-e843-5f19-a94c-b8091cc4e8b0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"79076b44-ab2f-589f-b09e-dded3ea2a53f","sourceKey":"bank:BUA202:DEC-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following events is best classified as UNCERTAINTY rather than risk for a Nigerian business?","options":["A sudden pandemic lockdown that no one expected","A 30% chance of rain on an outdoor event based on weather data","A 5% chance of fire damage estimated from insurance records","A 2% default rate on loans calculated from past borrowers"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"A sudden lockdown like the COVID-19 one was unexpected, with outcomes hard to identify and no reliable probability, so it is uncertainty. Options C, B and D all have probabilities estimated from records or data, which makes them risk."}},{"itemId":"d92a40c9-89d7-55c6-87d3-f61b5cf809d3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d830fff8-7f33-5d06-bb1a-7601aa244784","sourceKey":"bank:BUA202:DEC-037","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos events company estimates that a new concert project has a 0.6 probability of earning a profit of N500,000 and a 0.4 probability of making a loss of N200,000. What is the expected value of the project?","options":["N150,000","N220,000","N300,000","N380,000"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Expected value = sum of (probability x outcome) = 0.6 x 500,000 + 0.4 x (-200,000) = 300,000 - 80,000 = N220,000. Option D treats the loss as a gain and adds it. Option A takes a simple average and ignores the probabilities, and option C forgets the loss entirely."}},{"itemId":"ac76bfdd-7da1-5682-9fc4-0994b55e5c52","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9ad15f16-e5de-5080-babe-d3699dfdcac3","sourceKey":"bank:BUA202:DEC-038","parentItemId":null,"revision":1,"payload":{"prompt":"A manager compares two investments. Investment P pays N800,000 with probability 0.5 or N200,000 with probability 0.5. Investment Q pays N600,000 with probability 0.7 or N300,000 with probability 0.3. Using expected value, which investment should be chosen and what is its expected value?","options":["Investment P, with expected value N500,000","Investment Q, with expected value N450,000","Investment Q, with expected value N510,000","Investment P, because its highest payoff is N800,000"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"EV(P) = 0.5 x 800,000 + 0.5 x 200,000 = N500,000; EV(Q) = 0.7 x 600,000 + 0.3 x 300,000 = N510,000, so Q is higher. Option D picks the investment with the biggest single payoff and ignores probabilities. Option B takes a simple average of Q's payoffs instead of weighting them."}},{"itemId":"8d4177a4-12be-511c-9d15-4071c8dde2e1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3f3e1cad-8831-5432-97e5-f8969d1e77b5","sourceKey":"bank:BUA202:DEC-039","parentItemId":null,"revision":1,"payload":{"prompt":"A distributor in Onitsha estimates monthly profit from a new product line as follows: high demand N1,500,000 (probability 0.2), medium demand N900,000 (probability 0.5), low demand N400,000 (probability 0.3). What is the expected monthly profit?","options":["N750,000","N900,000","N933,333","N870,000"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Expected profit = 0.2 x 1,500,000 + 0.5 x 900,000 + 0.3 x 400,000 = 300,000 + 450,000 + 120,000 = N870,000. Option C is a simple average that ignores probabilities. Option B just takes the most likely outcome, and option A leaves out the low-demand outcome."}},{"itemId":"47bc3d70-4b40-54ac-b4a9-4c45ebbc1316","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b10a10df-8bcc-5ba5-a13d-a811289f5f72","sourceKey":"bank:BUA202:DEC-040","parentItemId":null,"revision":1,"payload":{"prompt":"A caterer must pay a fixed cost of N1,000,000 to serve at a wedding fair. Revenue will be N2,000,000 if attendance is high (probability 0.3) or N1,200,000 if attendance is low (probability 0.7). What is the expected PROFIT from attending the fair?","options":["N440,000","N600,000","N200,000","N1,440,000"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Expected revenue = 0.3 x 2,000,000 + 0.7 x 1,200,000 = N1,440,000; expected profit = N1,440,000 - 1,000,000 = N440,000. Option D forgets to subtract the fixed cost. Option B uses a simple average of revenues, and option C uses only the low-attendance revenue."}},{"itemId":"39bec4d9-ce11-59d3-8bdc-121322d0ab2e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"344be1d6-9c89-52d9-8916-dec8ec2cd23b","sourceKey":"bank:BUA202:DEC-041","parentItemId":null,"revision":1,"payload":{"prompt":"A project has three possible outcomes: a gain of N400,000 (probability 0.25), a gain of N250,000 (probability 0.45), or a loss of N100,000. Only these three outcomes are possible. What is the expected value of the project?","options":["N183,333","N212,500","N242,500","N182,500"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"The probabilities must sum to 1, so P(loss) = 1 - 0.25 - 0.45 = 0.30; EV = 0.25 x 400,000 + 0.45 x 250,000 + 0.30 x (-100,000) = 100,000 + 112,500 - 30,000 = N182,500. Option C adds the loss instead of subtracting it. Option B ignores the loss outcome, and option A is a simple average."}},{"itemId":"a347db3e-af67-58c8-af4e-027808c0e28e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0422b76f-c401-5c12-8b13-a3b53a26e92e","sourceKey":"bank:BUA202:DEC-042","parentItemId":null,"revision":1,"payload":{"prompt":"Records show that a warehouse in Apapa has a 5% chance of a fire in any year, and a fire would cause a loss of N4,000,000. What is the expected annual loss from fire?","options":["N3,800,000","N2,000,000","N20,000","N200,000"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Expected loss = probability x loss = 0.05 x 4,000,000 = N200,000. Option B uses 0.5 instead of 0.05, and option C uses 0.005, both errors in converting 5% to a decimal. Option A subtracts the expected loss from the full loss, which has no meaning."}},{"itemId":"801c3bce-355a-52a8-bad4-3b416fedf527","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"84e53174-caf8-5fed-a5ca-673cd781b69b","sourceKey":"bank:BUA202:DEC-043","parentItemId":null,"revision":1,"payload":{"prompt":"A bag contains 100 balls: 40 red and 60 black. A player wins N1,000 if a red ball is drawn at random and nothing otherwise. What is the expected value of one draw?","options":["N600","N400","N500","N1,000"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"P(red) = 40/100 = 0.4, so EV = 0.4 x 1,000 + 0.6 x 0 = N400. Option A uses the probability of black instead of red. Option C wrongly assumes a 50-50 chance, and option D ignores probability altogether."}},{"itemId":"3a5cf57c-b829-51a5-a46d-0bb7369b6827","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e4f170f0-e74f-5edc-8faa-57951aeffa38","sourceKey":"bank:BUA202:DEC-044","parentItemId":null,"revision":1,"payload":{"prompt":"Supplier X charges N2,000,000; there is a 0.1 probability of late delivery, which would add N500,000 in extra costs. Supplier Y charges N1,950,000; there is a 0.4 probability of late delivery, which would add N400,000. Based on expected total cost, which supplier should be chosen?","options":["Supplier X, expected cost N2,050,000","Supplier Y, expected cost N2,110,000","Supplier X, expected cost N2,500,000","Supplier Y, because its price is lower at N1,950,000"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Expected cost(X) = 2,000,000 + 0.1 x 500,000 = N2,050,000; expected cost(Y) = 1,950,000 + 0.4 x 400,000 = N2,110,000, so X is cheaper on average. Option D looks only at the quoted price and ignores the risk of late delivery. Option C adds the full late-delivery cost without weighting it by its probability."}},{"itemId":"a003df86-dd6a-505b-a30a-5a0e4c565972","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3147c111-d659-50b8-9269-699ae17e26b8","sourceKey":"bank:BUA202:DEC-045","parentItemId":null,"revision":1,"payload":{"prompt":"A group decision-making technique in which members freely suggest as many ideas as possible while criticism of any idea is withheld until later is called","options":["brainstorming","the nominal group technique","groupthink","the Delphi technique"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Brainstorming encourages a free flow of many ideas and forbids criticism during idea generation, which supports creativity. Option D collects expert opinions anonymously through questionnaires without face-to-face meetings. Option C is a problem in groups, not a technique."}},{"itemId":"935ec8b7-da1a-5cb9-8290-35a86522ef8a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d270cbc3-7a58-5589-acf1-52b2e898a839","sourceKey":"bank:BUA202:DEC-046","parentItemId":null,"revision":1,"payload":{"prompt":"In which group decision technique do experts who never meet face to face answer a series of questionnaires, with a coordinator summarising responses and sending them back until a consensus emerges?","options":["Brainstorming","The nominal group technique","The Delphi technique","Devil's advocacy"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"The Delphi technique uses anonymous experts, repeated questionnaire rounds and feedback from a coordinator, with no face-to-face meeting. Option B also uses independent idea writing, but members meet in the same room to present and vote. Option A is a face-to-face idea session."}},{"itemId":"d6f59888-4805-522b-85bd-20d8f5145a13","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2cedb7f8-1ace-55c1-b4c5-725ff13f228c","sourceKey":"bank:BUA202:DEC-047","parentItemId":null,"revision":1,"payload":{"prompt":"The nominal group technique is a group decision method in which members","options":["argue openly until the most senior member decides","meet only online and never see one another's ideas","write ideas independently, present them one at a time, discuss them, then rank them individually","answer mailed questionnaires anonymously over several rounds"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"In the nominal group technique members meet but first write their ideas silently, present them in turn, discuss them and then rank them independently, which stops a few loud members from dominating. Option D describes the Delphi technique. Option A is the kind of domination the technique is designed to prevent."}},{"itemId":"2fbbce2b-2bdc-5d42-b198-8d31632c72a8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a1bd8a0d-aaf5-58f2-bca8-2138bcc99b5a","sourceKey":"bank:BUA202:DEC-048","parentItemId":null,"revision":1,"payload":{"prompt":"A situation in which pressure for agreement in a cohesive group causes members to suppress doubts and fail to examine alternatives critically is called","options":["satisficing","groupthink","social loafing","brainstorming"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Groupthink occurs when the desire for agreement overrides realistic appraisal of alternatives, so dissent is suppressed. Option D is a technique that deliberately encourages many ideas. Option C is members putting in less effort in a group, not suppressing disagreement."}},{"itemId":"9bade330-1495-5548-b498-b102eb8d88ab","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9be498bf-4a01-55b7-b544-ee50346fe4d9","sourceKey":"bank:BUA202:DEC-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is generally regarded as an ADVANTAGE of group decision-making over individual decision-making?","options":["It brings more complete information and a wider range of alternatives","It is usually faster than an individual decision","It removes all pressure to conform","It makes responsibility for the outcome very clear"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Groups pool members' knowledge, so they bring more complete information and generate more alternatives, which also improves acceptance of the decision. Option B is wrong because groups are usually slower. Options D and C are actually disadvantages: responsibility becomes ambiguous and pressure to conform can increase."}},{"itemId":"641ad85a-52f2-518f-8120-aa0e588d0caa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e99781c2-2f47-58b7-890d-dd14cc9bf232","sourceKey":"bank:BUA202:DEC-050","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank's credit committee appoints one member to deliberately argue against every loan proposal before it is approved, so that weaknesses are exposed. This practice is meant mainly to reduce","options":["groupthink","anchoring on the first quote","satisficing","the need for decision criteria"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"A devil's advocate challenges the group's preferred option, which forces critical examination and guards against groupthink. Option C is about accepting good-enough options, which the advocate does not target directly. Option D is wrong because criteria are still needed to judge proposals."}},{"itemId":"26b786e6-f13b-5a99-834c-b423a8e690b3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be0c7e88-6d50-520f-a30a-8a26faa476e3","sourceKey":"bank:BUA202:ETH-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an objective of business ethics?","options":["To promote honesty","To protect stakeholders","To maximise short-term profit at any cost","To build trust"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The objectives of business ethics are to promote honesty, ensure fairness, build trust, protect stakeholders and improve corporate reputation. Chasing profit at any cost works against all of these. Options A, D and B are listed objectives."}},{"itemId":"60d119a1-997a-5477-8c1e-87a74bae5a19","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2af4b280-46ad-5719-a67b-5daa0a4e225a","sourceKey":"bank:BUA202:ETH-003","parentItemId":null,"revision":1,"payload":{"prompt":"The ethical theory which holds that decisions should produce the greatest good for the greatest number of people is:","options":["Utilitarianism","Justice theory","Deontology","Virtue ethics"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Utilitarianism judges a decision by its consequences and favours whatever produces the greatest good for the greatest number. Option C, deontology, says rules must be followed whatever the consequences. Option D, virtue ethics, focuses on good character."}},{"itemId":"3ea12558-61d2-56cc-8e0c-efb6c16895bb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d6d8f73d-d715-5afb-8e87-e3edbe28c322","sourceKey":"bank:BUA202:ETH-004","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos supermarket chain cuts prices on staple foods because the decision benefits thousands of low-income customers, even though its margins fall slightly. This reasoning reflects:","options":["Virtue ethics","Utilitarianism","Deontology","Shareholder theory"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The decision is justified by the large total benefit to many customers, which is the utilitarian test of the greatest good for the greatest number. Option C would focus on a duty or rule rather than on outcomes. Option D, shareholder theory, would put the owners' profit first, which is the opposite of what happened."}},{"itemId":"2f92f163-b4ab-53f3-88fc-86e38a337c47","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0d7aef7a-1f37-5626-b502-dc9efecdd96a","sourceKey":"bank:BUA202:ETH-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a major weakness of utilitarianism as a guide to business decisions?","options":["It focuses only on the decision-maker's character","It cannot be applied to business decisions","It ignores the consequences of actions","The interests of minorities may suffer"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Because utilitarianism looks at total welfare, a decision that benefits the majority can still harm a minority, and that is its main weakness. Option C is wrong because utilitarianism is entirely about consequences. Option A describes virtue ethics."}},{"itemId":"9dbdf2ff-a1d4-517d-9f7d-5674c11351bb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"43662d20-d477-5865-9906-460b77f68b31","sourceKey":"bank:BUA202:ETH-006","parentItemId":null,"revision":1,"payload":{"prompt":"The ethical theory which holds that actions should follow moral rules or duties regardless of their consequences is:","options":["Utilitarianism","Ethical relativism","Deontology","Virtue ethics"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Deontology, or duty ethics, says some actions are right or wrong in themselves, so rules such as 'never lie to customers' must be obeyed whatever the outcome. Option A is the opposite view, judging actions by their consequences. Option D looks at the person's character rather than rules."}},{"itemId":"f6000b04-534d-5fc7-9842-5dec16f8bf76","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"55342d50-513d-5ced-9069-371fa0982da5","sourceKey":"bank:BUA202:ETH-007","parentItemId":null,"revision":1,"payload":{"prompt":"An accountant refuses to backdate an invoice, even though her manager says doing so would help the firm win an important contract. She says, 'Falsifying records is wrong, whatever the result.' Her reasoning is based on:","options":["Philanthropic responsibility","Deontology","Utilitarianism","Satisficing"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"She treats honesty as a duty that must be kept whatever the consequences, which is deontological (duty) reasoning. Option C would weigh the benefit of winning the contract against the harm. Option A is a level of CSR about donations and community support, not a theory of reasoning."}},{"itemId":"32af143a-0ff7-5313-8726-3f13716d8d3e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"473a0c10-827d-592c-a88e-768f09bba85f","sourceKey":"bank:BUA202:ETH-009","parentItemId":null,"revision":1,"payload":{"prompt":"A company applies the same written promotion criteria to all staff, regardless of their ethnic group, religion or state of origin. This approach best reflects:","options":["Virtue ethics","Ethical egoism","Utilitarianism","Justice theory"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Justice theory holds that people should be treated fairly and equally, which is what applying the same criteria to everyone achieves. Option C would focus on total benefit rather than equal treatment. Option A focuses on the character of the decision-maker."}},{"itemId":"71c238ba-f2b4-5e0a-8973-0159811af754","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a77d8b07-0111-5b14-86c8-2dcde5ea4d0d","sourceKey":"bank:BUA202:ETH-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts utilitarianism and deontology?","options":["Utilitarianism protects minorities, while deontology ignores rules","Utilitarianism judges actions by rules, while deontology judges them by consequences","Utilitarianism judges actions by their consequences, while deontology judges them by whether they follow moral duties or rules","Both theories judge actions only by the character of the person acting"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Utilitarianism looks at outcomes and asks which choice gives the greatest good for the greatest number, while deontology asks whether an action keeps a duty or rule. Option B swaps the two theories. Option D describes virtue ethics."}},{"itemId":"40a52724-c3e2-587c-8f15-a3df99c52616","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c43fbd3f-14e9-5a58-805f-002af3623386","sourceKey":"bank:BUA202:ETH-011","parentItemId":null,"revision":1,"payload":{"prompt":"The philosopher most closely associated with duty-based (deontological) ethics is:","options":["Immanuel Kant","Aristotle","Jeremy Bentham","Milton Friedman"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Immanuel Kant is the classic thinker behind duty-based ethics, arguing that moral duties must be followed whatever the consequences. Option C, Bentham, is linked with utilitarianism, and option B, Aristotle, with virtue ethics. Option D, Friedman, is known for the shareholder view of business responsibility."}},{"itemId":"12a6ad1c-282e-5bc5-a1f6-ddf00440707f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e030a380-777f-52e0-a861-d9e56074ed73","sourceKey":"bank:BUA202:ETH-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following shows the correct order of the ethical decision-making process?","options":["Decide, gather facts, identify the issue, implement, consider stakeholders, evaluate alternatives, review outcomes","Identify the issue, decide, implement, gather facts, consider stakeholders, evaluate alternatives, review outcomes","Identify the issue, gather facts, consider stakeholders, evaluate alternatives, decide, implement, review outcomes","Gather facts, decide, identify the issue, consider stakeholders, implement, evaluate alternatives, review outcomes"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A sound ethical decision starts by naming the issue and getting the facts, then thinks about who is affected and compares options before deciding, acting and reviewing. Option A decides before even identifying the issue. Option B implements a decision before gathering any facts."}},{"itemId":"0a9207fe-831f-55c3-84a7-9f608614b401","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ca49dfa3-99b2-54f6-9887-bdd10f83a84b","sourceKey":"bank:BUA202:ETH-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes an ethical issue from an ethical dilemma?","options":["An ethical issue is a broad social question with controversy over the right thing to do; a dilemma is a specific situation where an individual finds it hard to decide","An ethical issue always involves breaking the law, while a dilemma never does","The two terms mean exactly the same thing","An ethical issue is a personal decision point; a dilemma is a broad social controversy"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical issue, such as environmental protection, is a wide area of controversy, while an ethical dilemma is a particular decision where the right action is unclear or every option has some negative consequence. Option D reverses the two. Option B is wrong because neither term depends on the law being broken."}},{"itemId":"dee70687-aaaf-56d0-a19d-4c4ed8e098ea","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2d59ec26-c7eb-540e-a751-2a61ed03c77c","sourceKey":"bank:BUA202:ETH-016","parentItemId":null,"revision":1,"payload":{"prompt":"In Carroll's pyramid of corporate social responsibility, which responsibility forms the BASE of the pyramid?","options":["Ethical responsibility","Philanthropic responsibility","Legal responsibility","Economic responsibility"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Carroll places economic responsibility, being profitable, at the base because a business that cannot survive cannot meet any other responsibility. Legal (C) and ethical (A) responsibilities sit above it, and philanthropic responsibility (B) is at the top."}},{"itemId":"5d09f711-dfc3-5019-a049-caa49d1d9856","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"043a8ca7-7843-5e0c-8428-244c8872ebbf","sourceKey":"bank:BUA202:ETH-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which responsibility sits at the TOP of Carroll's pyramid of corporate social responsibility?","options":["Philanthropic responsibility","Ethical responsibility","Legal responsibility","Economic responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Philanthropic responsibility, giving back to the community through donations and support, is at the top of Carroll's pyramid. Option D, economic responsibility, is at the base. Options C and B are the two middle layers."}},{"itemId":"6f1d0b55-75eb-5c9c-a89a-dd37adbd4d54","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d88ad098-3154-502c-9d76-ae520baee6b7","sourceKey":"bank:BUA202:ETH-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following lists Carroll's four CSR responsibilities in the correct order from the base of the pyramid to the top?","options":["Legal, economic, philanthropic, ethical","Economic, legal, ethical, philanthropic","Philanthropic, ethical, legal, economic","Ethical, legal, economic, philanthropic"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Carroll's pyramid starts with economic responsibility at the base, then legal, then ethical, with philanthropic responsibility at the top. Option C is the right list but from top to bottom. Options A and D mix up the layers."}},{"itemId":"6a807d7f-2423-5096-8f9a-8c64a26678cd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"57e229e9-e877-5551-b091-b93a6a034f9f","sourceKey":"bank:BUA202:ETH-019","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos paint manufacturer pays its company income tax on time and follows all environmental regulations on waste disposal. These actions fulfil mainly its:","options":["Legal responsibility","Ethical responsibility beyond the law","Philanthropic responsibility","Economic responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Paying taxes and obeying environmental regulations is obeying the law, which is the legal layer of CSR. Option C would involve voluntary donations to the community. Option B refers to going beyond what the law requires, which is not described here."}},{"itemId":"d5e86486-668a-5aef-b587-9bea1a5b7478","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"72b6fbdd-6673-5848-9aff-a33407a0c5f5","sourceKey":"bank:BUA202:ETH-020","parentItemId":null,"revision":1,"payload":{"prompt":"A food processing company treats its waste water before releasing it, even though no law in its area yet requires it, because management believes polluting the community's stream is wrong. This is an example of:","options":["Ethical responsibility","Economic responsibility","Legal responsibility","Philanthropic responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Ethical responsibility means doing what is morally right even when the law does not demand it. Option C does not fit because no law requires the treatment. Option D refers to donations and charitable giving rather than avoiding harm in the firm's own operations."}},{"itemId":"7d5b65fc-70fc-57ad-8826-5e777223841f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"18d7dfd5-bcfe-59f5-8f40-6313f852410a","sourceKey":"bank:BUA202:ETH-021","parentItemId":null,"revision":1,"payload":{"prompt":"A bank based in Lagos funds scholarships for 50 UNILAG students from low-income homes. Under Carroll's pyramid, this is an example of:","options":["Philanthropic responsibility","Ethical responsibility","Legal responsibility","Economic responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Donating to communities, for example by funding scholarships, is philanthropic responsibility, the voluntary top layer of the pyramid. Option C is wrong because no law requires the scholarships. Option D is about making profits ethically."}},{"itemId":"93913259-f2d2-59fc-90e4-0cad25710122","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5240417e-6cc0-57c8-9675-1b0311fec1ae","sourceKey":"bank:BUA202:ETH-022","parentItemId":null,"revision":1,"payload":{"prompt":"In Carroll's pyramid, which responsibility is described as 'desired' by society rather than required or expected?","options":["Philanthropic responsibility","Legal responsibility","Economic responsibility","Ethical responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Carroll describes economic and legal responsibilities as required by society, ethical responsibility as expected, and philanthropic responsibility as desired. So philanthropy is welcome but voluntary. Option D, ethical responsibility, is expected, which is stronger than desired."}},{"itemId":"1f15ca0b-e182-5160-a642-8eb1140d0b33","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"300a5dd4-5cbd-5916-8972-4b68c0443562","sourceKey":"bank:BUA202:ETH-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit of corporate social responsibility to a business?","options":["Competitive advantage","Better reputation","Automatic exemption from paying company taxes","Customer loyalty"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The benefits of CSR include a better reputation, customer loyalty, employee satisfaction and competitive advantage. CSR does not exempt a company from taxes, and paying taxes is itself part of responsible conduct. Options B, D and A are all listed benefits."}},{"itemId":"d6e286b6-f3b9-5f38-aa31-3f49ebc1ad99","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"52ceb750-b5b9-5d23-992d-9cdf04554e4a","sourceKey":"bank:BUA202:ETH-024","parentItemId":null,"revision":1,"payload":{"prompt":"In the stakeholder view of the firm, a stakeholder is best defined as:","options":["Any group or individual who can affect or is affected by the achievement of the organisation's objectives","Only a person who owns shares in the company","Only government agencies that regulate the company","Only the employees listed on the company's payroll"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The stakeholder view defines a stakeholder broadly as anyone who can affect, or is affected by, the firm's objectives, such as owners, employees, customers, suppliers and the community. Option B describes only shareholders, which is the narrower shareholder view. Options D and C pick out just one group each."}},{"itemId":"e3d931bb-fe39-520b-9cbc-46a31a4245bc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"046cc6e5-1044-59f2-b9be-cbf5e1d79daf","sourceKey":"bank:BUA202:ETH-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best contrasts the shareholder view and the stakeholder view of business responsibility?","options":["The shareholder view says firms must serve only the community, while the stakeholder view focuses only on owners","The shareholder view says the main duty of business is to increase profits within the law, while the stakeholder view says managers must balance the interests of all affected groups","Both views agree that businesses should ignore their owners' interests","The stakeholder view says firms should obey the law, while the shareholder view rejects the law"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The shareholder view, linked with Milton Friedman, holds that business should increase profits for its owners while staying within the rules, while the stakeholder view asks managers to balance the claims of owners, employees, customers, suppliers and the community. Option A swaps the two views. Option D is wrong because both views accept the law."}},{"itemId":"da132e06-7ea0-5178-8ff9-9880f961e801","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4b7475dd-035a-5da9-b443-d2a86e8c7933","sourceKey":"bank:BUA202:ETH-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which economist famously argued that the social responsibility of business is to increase its profits, within the rules of the game?","options":["Herbert Simon","Archie Carroll","Milton Friedman","Immanuel Kant"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Milton Friedman argued in 1970 that the social responsibility of business is to increase its profits while staying within the rules, which is the classic shareholder view. Option B, Carroll, built the four-level CSR pyramid. Option A, Simon, is known for bounded rationality in decision-making."}},{"itemId":"12ffa26f-0968-597f-9cb4-da665c75262a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8fd1a947-10ff-5c64-bdf1-efa5ef2418e4","sourceKey":"bank:BUA202:ETH-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an INTERNAL stakeholder of a company?","options":["Government regulators","The local community around its factory","Its customers","Its employees"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Internal stakeholders are people inside the organisation, such as employees (and owners and managers), whose interests are tied directly to how the firm is run. Options B, A and C are outside the organisation, so they are external stakeholders, even though the company must still balance their claims."}},{"itemId":"06b91000-3680-52cb-ba65-0f171e653706","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"54f1151d-e3fb-5435-808c-16a4373719b8","sourceKey":"bank:BUA202:ETH-028","parentItemId":null,"revision":1,"payload":{"prompt":"Residents living near a cement factory in Ogun State complain about dust and noise and ask the company to install filters. In stakeholder terms, the residents are:","options":["Not stakeholders, because they did not buy the cement","The community, an external stakeholder","Shareholders, internal stakeholders","Employees, internal stakeholders"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The local community is affected by the firm's operations, so it is a stakeholder even without buying anything, and it is outside the firm. Option C and option D are internal groups with a different relationship to the firm. Option A wrongly limits stakeholders to customers."}},{"itemId":"12780fcd-6618-5ecf-afe6-2903646873d3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ebc80691-f59c-5ae3-9e69-c0a94462bb23","sourceKey":"bank:BUA202:ETH-031","parentItemId":null,"revision":1,"payload":{"prompt":"A branch manager hires his nephew as an accountant ahead of two better-qualified applicants. Which workplace ethical issue does this illustrate?","options":["Confidentiality breach","Bribery","Nepotism","Bullying"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Nepotism is favouring relatives in matters such as hiring and promotion, regardless of merit. Option B would involve giving or receiving something of value to influence a decision. Option D is mistreating or intimidating a colleague."}},{"itemId":"3abfd161-39b3-5e01-b89e-8e37fe6ff89f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f088a34a-0d7d-5fda-860c-28fbc339797e","sourceKey":"bank:BUA202:ETH-033","parentItemId":null,"revision":1,"payload":{"prompt":"An HR officer posts colleagues' salary details and medical records in a staff WhatsApp group for fun. Which workplace ethical issue is this?","options":["Conflict of interest","Confidentiality breach","Nepotism","Kickback"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Sharing private staff records without authority is a confidentiality breach. Option C is favouring relatives. Option D is a secret payment returned to someone who arranged a contract."}},{"itemId":"7bae4e8d-3f4b-5b81-ad53-4a91cdcd4b84","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b2ee32ea-23bf-598e-944c-4f4cc1c9e55f","sourceKey":"bank:BUA202:ETH-034","parentItemId":null,"revision":1,"payload":{"prompt":"Whistle-blowing in an organisation refers to:","options":["Spreading rumours through the grapevine","Accepting a gift from a supplier after a contract is signed","Using a whistle to start and end the working day","Exposing illegal or unethical behaviour within the organisation"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Whistle-blowing is exposing illegal or unethical behaviour inside an organisation, often at personal or career risk, which is why whistleblower protection is an important prevention measure. Option A is informal communication, not reporting wrongdoing. Option B falls under bribes versus gifts."}},{"itemId":"facf25e9-78ef-5451-95ed-a58c05f29bf3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c759dc54-ee3b-57eb-899c-2caa15774967","sourceKey":"bank:BUA202:ETH-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recommended measure for preventing workplace ethical issues?","options":["Removing all company policies","Abolishing disciplinary procedures","Discouraging staff from reporting misconduct","Whistleblower protection"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Workplace ethical problems are prevented through ethics training, company policies, whistleblower protection, monitoring and fair discipline. Options A, C and B would all remove the safeguards that discourage misconduct."}},{"itemId":"0e99cdfc-8537-5374-be0e-e0b0db0f8067","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"433fb755-61f8-5ad8-bcc3-29897e368493","sourceKey":"bank:BUA202:ETH-037","parentItemId":null,"revision":1,"payload":{"prompt":"Ada learns in confidence from her manager that her close friend in another unit will soon be laid off. She feels torn between keeping her employer's confidence and warning her friend. This is a:","options":["Case of nepotism","Conflict of loyalty","Case of embezzlement","Conflict of interest"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A conflict of loyalty happens when an employee is caught between obligations to the employer and to a friend or family member, such as knowing a friend is about to be laid off. Option D involves personal gain interfering with the employer's interests, which is not the case. Option A is favouring relatives."}},{"itemId":"38922b0c-199a-5d51-bf86-2abe7542ee34","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c2ed927b-4660-5861-8084-50dcdcba327d","sourceKey":"bank:BUA202:ETH-038","parentItemId":null,"revision":1,"payload":{"prompt":"Corruption, in the context of business ethics, is best defined as:","options":["The abuse of power for personal gain","The lawful payment of taxes to government","The voluntary donation of funds to charity","The use of new technology to improve efficiency"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Corruption is the abuse of power for personal gain, with examples such as bribery, embezzlement, fraud, money laundering and kickbacks. Options B, D and C are lawful or even responsible actions."}},{"itemId":"d724e9b0-4fdd-5287-9b91-0569a4863b3f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7abd6bee-25b4-52f2-8534-854296e9512e","sourceKey":"bank:BUA202:ETH-039","parentItemId":null,"revision":1,"payload":{"prompt":"A cashier at a Lagos hospital secretly transfers part of the patient fees she collects into her own bank account. This is:","options":["Embezzlement","Nepotism","Money laundering","A kickback"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Embezzlement is stealing or misappropriating money that has been entrusted to one's care, which is what the cashier does. Option D is a secret payment returned to the person who arranged a deal. Option C is disguising where illegally obtained money came from."}},{"itemId":"7159c2cc-ff24-5336-91c1-44dbf212abaa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f8560579-f5d1-503b-86a9-6bc79d68b3c9","sourceKey":"bank:BUA202:ETH-040","parentItemId":null,"revision":1,"payload":{"prompt":"After winning a N50 million contract, a contractor secretly pays 10% of the contract sum back to the official who approved it. This payment is best described as a:","options":["Dividend","Philanthropic donation","Kickback","Commission disclosed to the board"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A kickback is a secret payment returned to the person who helped secure a contract, in return for that favour. Option A is a lawful share of company profits paid to shareholders. Option D is wrong because the payment was secret, not disclosed."}},{"itemId":"34aacbeb-abba-5486-991d-c4af3eb7322a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1abbf71b-8e2a-56d6-86e6-e405ef1928cd","sourceKey":"bank:BUA202:ETH-041","parentItemId":null,"revision":1,"payload":{"prompt":"Money laundering refers to:","options":["Disguising the illegal origin of money so that it appears to come from legitimate sources","Transferring money between one's own legitimate accounts","Lending money to customers at high interest rates","Washing and repacking old naira notes for re-issue"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Money laundering is the process of making money obtained from crime look as if it came from lawful activity, and it is one of the corrupt practices businesses must guard against. Option D takes the word 'laundering' literally. Option B is a normal, legal transaction."}},{"itemId":"27a07636-50ac-5c21-b568-a7958e2fe295","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b6963d85-81f0-5e52-a5f9-e747da74454c","sourceKey":"bank:BUA202:ETH-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an effect of corruption on an economy?","options":["An increase in foreign investment","Loss of trust","Poor economic growth","Damaged reputation"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Corruption leads to loss of trust, reduced investment, poor economic growth, financial losses and damaged reputation. It drives investors away rather than attracting them, so an increase in foreign investment is not an effect. Options B, C and D are listed effects."}},{"itemId":"089d3473-ee96-551b-8dbf-0619feae49b0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"555b933a-bc42-5c6b-a3b1-1134da517772","sourceKey":"bank:BUA202:ETH-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which Nigerian anti-corruption agency was established in 2000 under the Corrupt Practices and Other Related Offences Act?","options":["Economic and Financial Crimes Commission (EFCC)","Securities and Exchange Commission (SEC)","Nigeria Deposit Insurance Corporation (NDIC)","Independent Corrupt Practices and Other Related Offences Commission (ICPC)"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The ICPC was set up in 2000 under the Corrupt Practices and Other Related Offences Act to fight corruption in Nigeria. Option A, the EFCC, was created a few years later to focus on economic and financial crimes. Options C and B are financial-sector regulators, not anti-corruption agencies."}},{"itemId":"cda8b315-be42-5ab8-857d-835ceabd244b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"023c403a-f30a-5da1-94c9-a75ce99b7680","sourceKey":"bank:BUA202:ETH-045","parentItemId":null,"revision":1,"payload":{"prompt":"Under the whistleblowing policy approved by Nigeria's Federal Executive Council in December 2016, a whistleblower whose information leads to the voluntary return of stolen public funds may be rewarded with:","options":["Between 25% and 50% of the amount recovered","A fixed sum of N100,000 regardless of the amount","Between 2.5% and 5% of the amount recovered","Nothing, because the policy offers no reward"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The policy approved in December 2016 offers a reward of between 2.5% (minimum) and 5% (maximum) of the funds recovered as a result of the information. Option A multiplies the real range by ten. Option D is wrong because the reward was the main incentive the policy introduced."}},{"itemId":"c07f29ad-5cdf-5938-8153-986f5f421d67","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"74bbfe77-5531-5753-a049-a271f98b0fd4","sourceKey":"bank:BUA202:ETH-047","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage company in Lagos introduces bottle recycling, cuts pollution from its plant and switches to energy-saving equipment. These actions fall under which pillar of sustainability?","options":["Legal sustainability","Environmental sustainability","Social sustainability","Economic sustainability"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Pollution control, recycling and energy conservation are the examples given for environmental sustainability. Option C covers employee welfare and community development. Option D is about long-term profitability. Option A is not one of the three pillars."}},{"itemId":"2372b10a-3f05-5bfc-936f-9346b3df1c4a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"21fc5877-fae9-56d7-95ae-3a96afffb774","sourceKey":"bank:BUA202:ETH-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of responsible business conduct?","options":["Producing safe products","Avoiding taxes through falsified records","Respecting human rights","Treating workers fairly"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Responsible business conduct means respecting human rights, protecting the environment, obeying laws, treating workers fairly, producing safe products, paying taxes and avoiding corruption. Falsifying records to avoid tax breaks the law and the duty to pay taxes. Options C, A and D are all part of responsible conduct."}},{"itemId":"446be38f-f901-562a-b803-085e8d7a2300","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"83ef998f-081f-53bd-aaad-06a68e9c8564","sourceKey":"bank:BUA202:ETH-049","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian Code of Corporate Governance 2018, which sets governance principles for companies in Nigeria, was issued by the:","options":["National Pension Commission (PenCom)","Nigeria Deposit Insurance Corporation (NDIC)","Independent Corrupt Practices Commission (ICPC)","Financial Reporting Council of Nigeria (FRC)"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The Financial Reporting Council of Nigeria issued the Nigerian Code of Corporate Governance 2018, released in January 2019, to promote good governance, transparency and accountability in companies. Options B and A regulate deposit insurance and pensions. Option C investigates corrupt practices but does not issue governance codes."}},{"itemId":"2fdf5005-2e72-5d2e-bf28-52a87d93c742","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"371b1f15-8c3b-5976-baa6-1a9fce46dd5d","sourceKey":"bank:BUA202:ETH-050","parentItemId":null,"revision":1,"payload":{"prompt":"A company's lawyers confirm that a new product label is legal, but it deliberately hides an ingredient that many customers would object to. Which statement best describes the situation?","options":["The action is illegal because anything unethical is automatically illegal","The action is legal but may still be unethical, because ethics goes beyond the minimum the law requires","The action must be ethical because it is legal","Ethics does not apply because the decision was made by lawyers"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Business ethics is about what is right or wrong, and it goes beyond simply obeying the law, so a legal action can still be dishonest and unethical. Option C wrongly treats legality as the same as ethics. Option A makes the opposite mistake, since not every unethical act is against the law."}},{"itemId":"e6365cb8-f9c2-5f71-a6f7-c9ce57d165af","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"238e5d44-93ea-521b-9eb6-8e09a5233289","sourceKey":"bank:BUA202:FIN-001","parentItemId":null,"revision":1,"payload":{"prompt":"A financial system is best defined as:","options":["The network of institutions, markets and regulatory bodies that facilitates the flow of funds from savers to borrowers","The set of taxes collected by the Federal Government","The accounting department of a large company","The total amount of cash printed by the Central Bank in a year"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"A financial system is the complex network of institutions, markets and regulators that moves funds from savers to borrowers, and it acts as the economic backbone of a country. Option D describes only currency issue, which is one task of the central bank. Option B is fiscal revenue, not the financial system."}},{"itemId":"7f62009f-7460-5795-b34c-3e42a6869442","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9c772240-05cb-52c2-9481-3ccb2b0f5d2f","sourceKey":"bank:BUA202:FIN-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes the money market from the capital market?","options":["The money market deals in long-term funds, while the capital market deals in short-term funds","Both markets deal only in foreign currencies","The money market trades only physical cash, while the capital market trades only machinery","The money market deals in short-term funds, while the capital market deals in long-term funds such as shares and bonds"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The money market provides short-term funds, usually for a year or less, while the capital market provides long-term funds through instruments such as shares and bonds. Option A swaps the two. Option C confuses financial instruments with physical cash and equipment."}},{"itemId":"0d367eae-57fe-5889-b1df-c7bc09fe4280","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"856914e4-535d-5808-9e84-23f47cf17b3a","sourceKey":"bank:BUA202:FIN-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a money market instrument in Nigeria?","options":["A 15-year corporate debenture","A 10-year Federal Government bond","A 91-day Federal Government Treasury bill","Ordinary shares of a company listed on NGX"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"A Treasury bill is a short-term debt instrument issued by the Federal Government through the CBN, with primary auction tenors of 91, 182 and 364 days (as at 2025-2026), so it belongs to the money market. Options D, B and A are long-term instruments traded in the capital market."}},{"itemId":"c3e44759-01cd-5b42-844a-bfc3476a7990","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9b16b6bf-adc2-595c-a292-3c7a57ca18ed","sourceKey":"bank:BUA202:FIN-005","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian financial system is best described as:","options":["A system controlled entirely by foreign banks","A market-dominated system made up only of stock exchanges","A single informal system with no government regulation","A dual-structured, bank-dominated system with a formal sector and an informal sector"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Nigeria's financial system is dual-structured, with a formal sector regulated by government agencies and an informal sector of unregulated local arrangements, and it is mainly bank-dominated. Option C ignores the regulated formal sector. Option B is wrong because banks, not stock exchanges, dominate the system."}},{"itemId":"5ef435fa-b1e5-52ed-a9e9-8a0e68d026c9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"034117c5-c77e-59c3-95a4-9b11c5074401","sourceKey":"bank:BUA202:FIN-006","parentItemId":null,"revision":1,"payload":{"prompt":"Twenty market women in Oyingbo each contribute N5,000 weekly, and each week one member collects the whole pot in turn. This arrangement belongs to which part of the Nigerian financial system?","options":["The informal sector (esusu or ajo)","The formal sector, as a microfinance bank","The formal sector, as a merchant bank","The capital market, as a mutual fund"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Rotating thrift contributions known as esusu or ajo are unregistered arrangements, so they belong to the informal sector together with local moneylenders and cooperative societies. Option B is a licensed, regulated institution. Option D is a professionally managed, regulated investment vehicle."}},{"itemId":"ef49dfc2-5401-5e00-9a24-447313f7f1ac","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a9b53c5f-76f4-526a-b6e9-270c17559fc6","sourceKey":"bank:BUA202:FIN-007","parentItemId":null,"revision":1,"payload":{"prompt":"Under the CBN Act 2007, which of the following is NOT one of the principal objects of the Central Bank of Nigeria?","options":["Issuing legal tender currency in Nigeria","Regulating and supervising insurance companies","Acting as banker and financial adviser to the Federal Government","Ensuring monetary and price stability"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The CBN's principal objects under the CBN Act 2007 are to ensure monetary and price stability, issue legal tender currency, maintain external reserves, promote a sound financial system and act as banker and adviser to the Federal Government (as at 2026). Insurance is regulated by the National Insurance Commission (NAICOM), not the CBN. Options D, A and C are all CBN objects."}},{"itemId":"830ca403-e7b5-5708-bef9-2ee5fc4a7027","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"11a31b8d-8a89-5eac-8119-73c8ff00fd2d","sourceKey":"bank:BUA202:FIN-008","parentItemId":null,"revision":1,"payload":{"prompt":"When the Central Bank of Nigeria is described as the 'lender of last resort', it means that the CBN:","options":["Provides liquidity to banks in financial distress when they cannot borrow elsewhere","Lends only to foreign governments after all other lenders have refused","Is the last institution to receive repayment when a company is wound up","Lends money directly to members of the public who are refused bank loans"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"As lender of last resort, the central bank supplies liquidity to banks during financial stress, when other sources of funds have dried up, to protect the stability of the system. Option D is wrong because the CBN does not lend to the general public. Option C confuses the idea with the order of creditors in liquidation."}},{"itemId":"20c069a7-4650-573f-bef2-0333cc4a60f4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a9e335ed-dec3-519d-a202-814c7635cd91","sourceKey":"bank:BUA202:FIN-010","parentItemId":null,"revision":1,"payload":{"prompt":"As at 2026, the apex regulator of the Nigerian capital market and the law under which it now operates are:","options":["The Central Bank of Nigeria, under the CBN Act 2007","The Securities and Exchange Commission, under the Investments and Securities Act 2025","The NGX Regulation Limited, under the Companies Act","The NDIC, under the NDIC Act 2023"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The SEC is the apex regulator of the Nigerian capital market, and the Investments and Securities Act 2025, signed in March 2025, repealed the ISA 2007 and reaffirmed that role. Option A oversees monetary policy and banks. Option C, NGX RegCo, regulates trading on the exchange but is not the apex regulator of the whole market."}},{"itemId":"e59c7685-672d-5795-aec6-f44956818b33","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a1fa97ee-b1f8-5f04-a634-920d9bd6e4c6","sourceKey":"bank:BUA202:FIN-011","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos insurance company wants approval to introduce a new motor insurance product. Which regulator is primarily responsible for supervising it?","options":["National Insurance Commission (NAICOM)","Nigeria Deposit Insurance Corporation (NDIC)","Securities and Exchange Commission (SEC)","National Pension Commission (PenCom)"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NAICOM regulates and supervises the insurance industry in Nigeria. Option B, the NDIC, insures bank deposits, which is a different kind of insurance and not supervision of insurers. Option D, PenCom, regulates pension funds."}},{"itemId":"f1e48184-7ab1-558c-a8a0-21da384625d3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5e0c902d-98bc-57c3-9070-3637d1c11bce","sourceKey":"bank:BUA202:FIN-012","parentItemId":null,"revision":1,"payload":{"prompt":"The National Pension Commission (PenCom), which regulates and supervises pension administration in Nigeria, was established by the:","options":["CBN Act 1958","Pension Reform Act 2004","Investments and Securities Act 2025","NDIC Act 2023"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"PenCom was established by the Pension Reform Act 2004 and works under the Pension Reform Act 2014 (as at 2026) to regulate and supervise pension funds. Option A established the central bank. Option C governs the capital market."}},{"itemId":"ac363704-c3ab-5803-a42d-7845a41e27ad","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1ca5b0d8-0a77-5da5-ad2f-3b545318cf05","sourceKey":"bank:BUA202:FIN-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing correctly matches a Nigerian authority with the policy it is mainly responsible for?","options":["SEC - monetary policy; NDIC - fiscal policy","Federal Ministry of Finance - monetary policy; Central Bank of Nigeria - fiscal policy","Federal Ministry of Finance - fiscal policy; Central Bank of Nigeria - monetary policy","PenCom - exchange rate policy; NAICOM - monetary policy"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The Federal Ministry of Finance oversees the nation's broader fiscal policy, that is government spending and taxation, while the CBN formulates monetary and exchange rate policy. Option B swaps the two. Options A and D give policies to regulators that supervise specific sectors."}},{"itemId":"b537901b-752b-5477-a1a1-2f5e862f0815","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"372902f0-cbfa-5254-8e7d-c2a59a0cece5","sourceKey":"bank:BUA202:FIN-014","parentItemId":null,"revision":1,"payload":{"prompt":"Banks that focus on wholesale banking, investment banking and medium- to long-term financing, rather than retail banking for individuals, are:","options":["Primary mortgage banks","Microfinance banks","Merchant banks","Commercial banks"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Merchant banks concentrate on wholesale and investment banking and medium- to long-term financing for corporate clients. Option B serves rural people, low-income earners and MSMEs. Option D provides retail, corporate and international banking to the general public."}},{"itemId":"1986507d-cf29-5112-93c4-ce8fb609dc75","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3d06b7cb-5565-5523-9bba-d49b4fa9c096","sourceKey":"bank:BUA202:FIN-015","parentItemId":null,"revision":1,"payload":{"prompt":"Non-interest banks in Nigeria, such as Jaiz Bank, operate on the basis of:","options":["Islamic finance principles","Lending only to the Federal Government","Accepting only foreign currency deposits","Charging the highest interest rates in the market"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Non-interest banks operate on Islamic finance principles, which avoid charging or paying interest. Jaiz Bank, Nigeria's first non-interest bank, began operations in January 2012. Option D is the opposite of how these banks work."}},{"itemId":"d9d9f2dd-6731-57a5-abf9-5e1ffc19849e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"70a21e10-a2ef-5d4a-b0d3-6fec3543acf1","sourceKey":"bank:BUA202:FIN-016","parentItemId":null,"revision":1,"payload":{"prompt":"A cassava farmer in rural Benue with no collateral needs a small loan of N150,000 to buy fertiliser. Which type of Nigerian bank is designed mainly for customers like her?","options":["The Central Bank of Nigeria","A merchant bank","The Federal Mortgage Bank of Nigeria","A microfinance bank"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Microfinance banks cater to the financial needs of rural populations, low-income earners and MSMEs; they replaced community banks under the CBN's 2005 microfinance policy. Option B focuses on wholesale and corporate finance. Option A does not lend to individuals at all."}},{"itemId":"58cf5b13-9040-5936-9bab-00c00eca99f1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"94e58686-66df-598b-a1bc-99cd7d6d5b66","sourceKey":"bank:BUA202:FIN-017","parentItemId":null,"revision":1,"payload":{"prompt":"The apex institution for primary mortgage banks in Nigeria, which drives housing finance, is the:","options":["Bank of Agriculture (BOA)","Nigerian Export-Import Bank (NEXIM)","Federal Mortgage Bank of Nigeria (FMBN)","Bank of Industry (BOI)"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The FMBN is the apex institution for primary mortgage banks and drives housing finance in Nigeria. Option D finances industrial enterprises. Option B supports exports, and option A supports agriculture."}},{"itemId":"faabef7e-86c0-52aa-b0ab-f6151f106dbf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e249fba6-97a0-507c-bce1-5f2cb4793f6d","sourceKey":"bank:BUA202:FIN-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches a Nigerian development finance institution with its target sector?","options":["Bank of Agriculture - housing","Bank of Industry - agriculture","NEXIM - exports","FMBN - industrial manufacturing"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Development finance institutions are government-backed and target particular sectors: NEXIM supports exports, the Bank of Industry supports industry and enterprises, and the Bank of Agriculture supports farming. Option B gives BOI the wrong sector, and option A and option D also mismatch the institutions."}},{"itemId":"aa32b4cd-dc1f-50ae-b2eb-bc4a2a4d84e8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d2db1d5e-02f6-5bad-8097-581d3e2e07ba","sourceKey":"bank:BUA202:FIN-019","parentItemId":null,"revision":1,"payload":{"prompt":"When the CBN abolished the universal banking model in 2010, banking licences were reorganised into which categories?","options":["Federal, state and local government banks","Retail, wholesale and digital-only banks","Commercial, merchant and specialised banks","Universal, rural and urban banks"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"In 2010 the CBN repealed universal banking and created three licence types: commercial banks, merchant banks and specialised banks, which include non-interest, microfinance, development and mortgage banks. Option D keeps the universal model that was abolished. Options A and B are not CBN licence categories."}},{"itemId":"076a3106-e281-59d1-9abf-ee189eba2a44","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e78f797c-43a4-59a9-86bf-2918928b649f","sourceKey":"bank:BUA202:FIN-020","parentItemId":null,"revision":1,"payload":{"prompt":"Financial intermediation refers to:","options":["The direct exchange of goods between two traders without money","The government's collection of taxes from businesses","The printing of currency notes by the central bank","The process by which financial institutions act as middlemen between those with surplus capital and those who need capital"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Financial intermediation is the process where banks, mutual funds, insurers and other institutions stand between savers and borrowers, so that capital flows efficiently with lower risk and transaction costs. Option A describes barter. Options B and C are government and central bank activities, not intermediation."}},{"itemId":"2af646f3-7b80-5b2c-bad1-3fe848d758c4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"03679fba-c0be-5ce9-99bb-983d22a62fc4","sourceKey":"bank:BUA202:FIN-021","parentItemId":null,"revision":1,"payload":{"prompt":"When a bank uses customers' short-term savings deposits to fund a 20-year mortgage, it is performing:","options":["Maturity transformation","Risk diversification","Price discovery","Payment processing"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Maturity transformation is converting short-term deposits into long-term loans, such as funding a long mortgage with savings accounts. Option B is pooling funds from many sources to protect savers from default. Option C is a function of markets setting prices."}},{"itemId":"1b1b08ac-5ecb-5030-8b3c-4a9641fd06e1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0da1fd4d-f0df-5b66-b6ad-61f5f088b229","sourceKey":"bank:BUA202:FIN-022","parentItemId":null,"revision":1,"payload":{"prompt":"Mr Okafor deposits his savings in a bank rather than lending directly to a stranger, because the bank checks borrowers' creditworthiness for him. This benefit of intermediation is called:","options":["Maturity transformation","Payment processing","Capital formation","Reducing asymmetric information"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Intermediaries reduce asymmetric information by evaluating borrowers' creditworthiness so that individual savers do not have to. Option A is about the mismatch between short-term deposits and long-term loans. Option B is providing clearing and digital payment networks."}},{"itemId":"e752dafa-e0e5-51ba-93c6-b4c8f62f65c3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"56d2634c-4416-5661-a4b9-1129dd709452","sourceKey":"bank:BUA202:FIN-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly classifies a financial intermediary?","options":["Credit union - investment intermediary","Insurance company - contractual institution","Commercial bank - contractual institution","Mutual fund - depository institution"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Contractual institutions are insurance companies that collect premiums and pay out when specified events happen. Depository institutions are commercial banks, credit unions and building societies, while investment intermediaries are mutual funds, pension funds and investment banks, so options C, D and A are all misclassified."}},{"itemId":"52a73037-79af-5f19-b313-77c3f7ae64fd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3fba92af-dc5e-5e1e-a639-1e92e75a4819","sourceKey":"bank:BUA202:FIN-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an expansionary (easing) monetary policy action?","options":["Reducing banks' reserve requirements","Selling government securities to reduce the money supply","Lowering the Monetary Policy Rate","Injecting liquidity through open market operations"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Selling government securities withdraws money from the economy, which is a contractionary (tightening) action. Lowering the policy rate, cutting reserve requirements and injecting liquidity are the easing actions used to stimulate a sluggish economy, so options C, A and D are all expansionary."}},{"itemId":"25727a09-a7f0-5f11-a070-fefd96f1e446","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a22db76b-2655-5663-8e29-fc16ef6cffd7","sourceKey":"bank:BUA202:FIN-025","parentItemId":null,"revision":1,"payload":{"prompt":"To fight high inflation, the CBN sharply raises the Monetary Policy Rate. What is the most likely effect on a Lagos manufacturing firm planning to borrow for a new factory?","options":["Borrowing becomes cheaper, so the firm expands faster","The firm no longer needs to pay interest on existing loans","Borrowing becomes more expensive, so the firm may delay the investment","The firm's loan is automatically cancelled by the CBN"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Raising the policy rate is contractionary: credit becomes more expensive, and businesses may delay large investments or hiring because of the higher cost of capital. Option A describes the effect of expansionary policy. Options D and B are not how monetary policy works."}},{"itemId":"b2560407-8ece-5b3f-8310-e8dd19edb328","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"89cf9eea-ba5a-521f-9c9a-5f998d8dda1b","sourceKey":"bank:BUA202:FIN-026","parentItemId":null,"revision":1,"payload":{"prompt":"The Central Bank of Nigeria's benchmark interest rate, introduced in December 2006 to replace the Minimum Rediscount Rate, is called the:","options":["Prime Lending Rate","Treasury Bill Rate","Cash Reserve Ratio (CRR)","Monetary Policy Rate (MPR)"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The Monetary Policy Rate became the CBN's benchmark rate under the framework that took effect in December 2006, replacing the Minimum Rediscount Rate. Option C is the share of deposits banks must keep with the CBN, not the benchmark rate. Option A is the rate commercial banks charge their best customers."}},{"itemId":"5d767d17-ba9e-5ea6-905b-eca32e74064f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6896a490-32cd-590d-8a2f-2390839e2143","sourceKey":"bank:BUA202:FIN-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes the primary market from the secondary market for securities?","options":["In the primary market new securities are issued and the issuer receives the funds; in the secondary market existing securities are traded and the proceeds go to the selling investor","The primary market deals only in bonds, while the secondary market deals only in shares","The issuer receives the money in both markets","In the primary market existing shares are traded; in the secondary market new shares are issued"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The primary market is where companies and governments issue new securities, for example through an IPO, and the issuer gets the money directly; in the secondary market investors trade existing securities among themselves. Option D reverses the two markets. Option C is wrong because the issuer is not involved in secondary trades."}},{"itemId":"6d20b286-47f2-5d4c-8130-3ac167715506","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"94b25651-af47-5661-9274-eca160534f95","sourceKey":"bank:BUA202:FIN-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly traces the history of Nigeria's main stock exchange?","options":["The Nigerian Stock Exchange (2021), renamed Lagos Stock Exchange (1977)","Lagos Stock Exchange (1960), renamed The Nigerian Stock Exchange (1977), demutualised into the Nigerian Exchange Group (2021)","Abuja Securities Exchange (1960), merged with FMDQ in 2021","Nigerian Exchange Group (1960), renamed Lagos Stock Exchange (1977), demutualised in 2021"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The exchange was founded in 1960 as the Lagos Stock Exchange, was renamed The Nigerian Stock Exchange in 1977, and was demutualised in 2021 into the Nigerian Exchange Group, a publicly quoted holding company. Option D puts the names in the wrong order, and option C does not describe this exchange's history at all."}},{"itemId":"b0570a0a-6643-54e0-927a-018fd5916faa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d3ec9b0a-55f1-5db3-b876-405b125a07b4","sourceKey":"bank:BUA202:FIN-030","parentItemId":null,"revision":1,"payload":{"prompt":"The subsidiary of the Nigerian Exchange Group that serves as the independent regulatory arm, enforcing listing rules and monitoring trading compliance, is:","options":["NGX Real Estate Limited (NGX RelCo)","Nigerian Exchange Limited (NGX)","NGX Regulation Limited (NGX RegCo)","Central Securities Clearing System (CSCS)"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NGX RegCo is the independent regulatory arm that enforces listing rules, monitors trading compliance and keeps markets fair and orderly. Option B is the operating exchange where trading takes place. Option A manages the group's property and physical facilities."}},{"itemId":"1a224c52-5e3b-54e9-a7be-ca5b16d74adb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"753e5f37-eb9e-5f6a-9ae1-54d4561501b0","sourceKey":"bank:BUA202:FIN-032","parentItemId":null,"revision":1,"payload":{"prompt":"A shareholder has a dispute with a stockbroking firm over a capital market transaction. Which specialised body was established to adjudicate such capital market disputes quickly?","options":["Central Securities Clearing System (CSCS)","Nigeria Deposit Insurance Corporation (NDIC)","Investment and Securities Tribunal (IST)","Federal Mortgage Bank of Nigeria (FMBN)"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The Investment and Securities Tribunal is a specialised judicial body for resolving capital market disputes quickly and efficiently. Option B protects bank depositors. Option A clears and settles trades but does not judge disputes."}},{"itemId":"bf0470b1-f399-5402-b134-44bfe11e477a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"179a4d49-0dfd-55e3-8721-e19ba565308d","sourceKey":"bank:BUA202:FIN-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing correctly matches a capital market operator with its role?","options":["Registrar - maintains records of share ownership and processes dividend payments","Issuing house - keeps the register of shareholders","Stockbroker - acts as legal custodian of assets for bondholders","Trustee - buys and sells shares on behalf of investors"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Registrars keep records of who owns shares and process corporate actions such as dividend payments. Option D describes a stockbroker, option C describes a trustee, and option B confuses issuing houses, which underwrite and package new issues, with registrars."}},{"itemId":"c88d34ed-33bd-55db-a8fd-9e890209b30f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8a66f58b-85b1-503c-9aa5-0d2b7ee8574e","sourceKey":"bank:BUA202:FIN-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly describes a trading platform in the Nigerian capital market?","options":["Nigerian Exchange Group - the Islamic bank regulator","FMDQ Group - the apex regulator of the capital market","NASD OTC Securities Exchange - the central securities depository","NASD OTC Securities Exchange - an over-the-counter platform for trading unquoted public company securities"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NASD OTC is an over-the-counter platform for securities of public companies that are not listed on the exchange, while FMDQ provides platforms for fixed income, currencies and derivatives. Option B gives FMDQ the SEC's role. Option C gives NASD the role of CSCS."}},{"itemId":"d3c2e9e6-09e8-5aba-9bb2-c8d0534327e6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5c65296c-7977-5613-8476-174b5aee142b","sourceKey":"bank:BUA202:FIN-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly compares shares and bonds?","options":["Shares are loans to the company; bonds represent ownership","Shares represent ownership and carry higher risk; bonds are loans to the issuer and are generally safer, with steady income","Bonds historically offer the highest potential returns and the highest risk","Both shares and bonds guarantee fixed interest payments"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Shares are units of ownership that offer the highest potential returns but also the highest risk, while bonds are loans to a company or government that pay periodic interest and return the principal at maturity. Option A swaps ownership and debt. Option C gives bonds the risk profile of shares."}},{"itemId":"34f7e635-073f-5ddd-a743-da6aa8beb734","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8eec7f48-b39d-5b69-8d9f-8643c81abdb1","sourceKey":"bank:BUA202:FIN-036","parentItemId":null,"revision":1,"payload":{"prompt":"What mainly distinguishes a debenture from a secured bond?","options":["A debenture is a short-term money market instrument","A debenture is backed by specific physical collateral and pays lower interest","A debenture is usually unsecured and relies on the issuer's creditworthiness, so it typically pays a higher interest rate","A debenture makes its holder a part-owner of the company"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Debentures are long-term debt instruments that are usually unsecured, relying on the company's reputation, so they pay higher interest to compensate for the extra risk. Option B describes a secured bond. Option D describes shares."}},{"itemId":"b9b7db84-2cd7-5ea8-bd6d-c1fdedbd88a6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"978094db-5eda-5e6e-ac09-989cd24a1f65","sourceKey":"bank:BUA202:FIN-037","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund is best described as:","options":["A share of ownership in one company only","A pooled investment vehicle, managed by professionals, that combines money from many investors to buy a diversified portfolio","A loan from a commercial bank to a single investor","A savings account that pays a fixed interest rate"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"A mutual fund pools money from many investors, is managed by professionals and buys a diversified basket of shares, bonds or other assets; investors own units of the fund rather than the assets themselves. Option A describes a single share. Option D describes a bank deposit."}},{"itemId":"6fbdc5e3-02dd-5b67-a42a-e1d5e817b347","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1e222c28-d243-54ea-8b18-8e81d280001e","sourceKey":"bank:BUA202:FIN-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts equity finance with debt finance?","options":["Debt finance involves selling shares; equity finance involves taking bank loans","Both require fixed repayments of principal and interest","Equity finance has no mandatory repayment but gives up part ownership; debt finance must be repaid with interest regardless of performance","Equity finance must be repaid with fixed interest; debt finance gives investors ownership"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"With equity finance, investors buy part of the business and are rewarded through dividends or a later sale, with no compulsory repayment; with debt finance, the firm must repay principal plus interest on schedule whatever its performance. Options D and A swap the two. Option B ignores the main difference that equity carries no fixed repayment."}},{"itemId":"18c9a1f6-08a1-5bcb-873e-951d941cff8e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b43da225-a58e-54f6-a983-11936f724a8f","sourceKey":"bank:BUA202:FIN-039","parentItemId":null,"revision":1,"payload":{"prompt":"A Yaba tech start-up receives N400 million from a firm that specialises in early-stage, high-growth businesses. In return, the firm takes a 30% stake, a board seat and expects an eventual exit through acquisition. This source of finance is:","options":["Trade credit","Venture capital","Debt finance","A bank overdraft"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Venture capital is a high-risk form of equity finance in which specialist firms invest in early-stage, high-growth start-ups in exchange for ownership, some control and an expected exit. Options C, A and D are forms of debt that must be repaid and do not give the lender ownership."}},{"itemId":"ba60cbec-6bdb-51a1-9b91-5c9149e43cf6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"20572bdb-d02f-5e31-8d9e-fe7026cd4665","sourceKey":"bank:BUA202:FIN-040","parentItemId":null,"revision":1,"payload":{"prompt":"The board of a profitable Lagos company must decide whether to pay out this year's profit to shareholders or keep it to fund expansion. This is a:","options":["Marketing decision","Dividend decision","Financing decision","Investment decision"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The dividend decision is about what share of earnings to pay to shareholders and what share to reinvest in the company. Option D is about which long-term projects to fund. Option C is about the balance of debt and equity used to fund the business."}},{"itemId":"46a29b0a-80ec-5052-a3ea-d5026ce0609e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4ce672e6-ee14-5e86-95fb-4225357a0325","sourceKey":"bank:BUA202:FIN-041","parentItemId":null,"revision":1,"payload":{"prompt":"Net Present Value (NPV), Internal Rate of Return (IRR) and the payback period are tools used mainly for which financial decision?","options":["Investment decisions (capital budgeting)","Dividend decisions","Financing decisions on debt and equity","Decisions on staff recruitment"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Investment decisions, also called capital budgeting, choose which long-term projects or assets to fund, and NPV, IRR and payback period are the usual tools. Option B is about paying out or retaining earnings. Option C is about how the business will be funded."}},{"itemId":"2c05e58f-b8b3-5641-9789-c014d5f1c82c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c1e0af38-c141-534e-b70f-b2e4891dbb44","sourceKey":"bank:BUA202:FIN-042","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company is considering a machine costing N5,000,000 that will generate equal net cash inflows of N2,000,000 a year. What is the payback period?","options":["2.5 years","3 years","0.4 years","2 years"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"With equal annual inflows, payback period = initial investment / annual cash inflow = 5,000,000 / 2,000,000 = 2.5 years. Option C divides the inflow by the cost, which turns the formula upside down. Options D and B round to whole years and ignore the part-year needed."}},{"itemId":"ed465eee-6fe3-5cdf-86e6-9c7a6c7549a0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d327feb8-93f6-53ca-a29a-9a40c1c014b4","sourceKey":"bank:BUA202:FIN-043","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N9,000,000 and is expected to produce net cash inflows of N3,000,000, N4,000,000, N4,000,000 and N2,000,000 in years 1 to 4. Assuming cash flows arise evenly within each year, what is the payback period?","options":["2.25 years","3.00 years","2.77 years","2.50 years"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"After 2 years the project has recovered 3,000,000 + 4,000,000 = 7,000,000, leaving 2,000,000 to recover from year 3's inflow of 4,000,000, so payback = 2 + 2,000,000 / 4,000,000 = 2.50 years. Option B rounds up to the end of year 3. Option C wrongly uses the average annual inflow (9,000,000 / 3,250,000)."}},{"itemId":"1d24c760-9977-5914-9ae9-c990d30e8c08","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"73ebb79a-adf0-548f-8fa4-249fcc401a6e","sourceKey":"bank:BUA202:FIN-044","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N1,000,000 now and will generate N600,000 at the end of each of the next 2 years. Using a discount rate of 10% per annum (annual compounding), what is the project's Net Present Value (to the nearest naira)?","options":["N1,041,322","N90,909","N41,322","N200,000"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NPV = 600,000 / 1.1 + 600,000 / (1.1)^2 - 1,000,000 = 545,455 + 495,868 - 1,000,000 = N41,322. Option D ignores discounting and simply subtracts the cost from N1,200,000. Option A is the present value of the inflows before subtracting the cost."}},{"itemId":"17408198-c1c4-5f41-a1ce-551886f8ae56","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4cb4a186-f970-58ac-948c-bdf41f83cf7e","sourceKey":"bank:BUA202:FIN-045","parentItemId":null,"revision":1,"payload":{"prompt":"An investment costs N2,000,000 today and will return a single payment of N2,300,000 at the end of year 2. Using a discount rate of 10% per annum compounded annually, what is the NPV (to the nearest naira) and should the project be accepted on the NPV rule?","options":["N300,000; accept","-N99,174; reject","N90,909; accept","N1,900,826; accept"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NPV = 2,300,000 / (1.1)^2 - 2,000,000 = 1,900,826 - 2,000,000 = -N99,174, and a negative NPV means the project should be rejected. Option A ignores the time value of money. Option C discounts for only one year (2,300,000 / 1.1 - 2,000,000)."}},{"itemId":"c12e9703-12c8-5c4d-80cf-a48ccc619a67","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"65d40ffd-4476-553a-aa9b-877c9109081d","sourceKey":"bank:BUA202:FIN-046","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of N1,000,000 today returns a single cash inflow of N1,210,000 at the end of year 2, with no other cash flows. What is its Internal Rate of Return (IRR), with annual compounding?","options":["12.1% per annum","10% per annum","21% per annum","10.5% per annum"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The IRR is the rate at which NPV equals zero, so 1,000,000 x (1 + r)^2 = 1,210,000, giving (1 + r)^2 = 1.21 and r = 10%. Option C is the total return over two years, not the annual rate. Option D divides the 21% simple return by 2 and ignores compounding."}},{"itemId":"021dd42a-e984-50d9-a98e-6279aa146d41","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"08f3e8c7-8b23-50a0-82db-9135dfb7b6e0","sourceKey":"bank:BUA202:FIN-047","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian company earned a profit after tax of N80 million and paid dividends of N30 million to shareholders. What percentage of earnings did it retain for reinvestment?","options":["62.5%","37.5%","166.67%","266.67%"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Retention ratio = (earnings - dividends) / earnings x 100 = (80 - 30) / 80 x 100 = 62.5%. Option B is the dividend payout ratio (30 / 80), not the retention ratio. Option C wrongly divides the retained N50 million by the dividends."}},{"itemId":"438b0dbd-3bc7-5445-8303-99d039764b50","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1e8481b4-0236-5bcb-9842-83062168f6f4","sourceKey":"bank:BUA202:FIN-048","parentItemId":null,"revision":1,"payload":{"prompt":"A listed company earned N120 million after tax, has 200 million ordinary shares and decides to pay out 40% of its earnings as dividends. What is the dividend per share?","options":["N0.24","N0.36","N0.60","N2.40"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Dividend per share = (earnings x payout ratio) / number of shares = (120,000,000 x 0.40) / 200,000,000 = 48,000,000 / 200,000,000 = N0.24. Option C is earnings per share, which ignores the 40% payout. Option B uses the 60% that was retained instead of the 40% paid out."}},{"itemId":"9da065bb-0a87-5338-8b4c-5cb4fb7ece44","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f0016a6b-358f-566d-9de5-c1eb2b3c4c5b","sourceKey":"bank:BUA202:FIN-049","parentItemId":null,"revision":1,"payload":{"prompt":"An investor bought shares of a Lagos bank at N20.00 each, received a dividend of N1.50 per share during the year and sold the shares at N24.00 at the year end. What was the total return on the investment for the year (to 2 decimal places)?","options":["7.50%","27.50%","20.00%","22.92%"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Total return = (dividend + capital gain) / purchase price x 100 = (1.50 + 4.00) / 20.00 x 100 = 27.50%. Option C counts only the capital gain of N4.00, and option A counts only the dividend. Option D wrongly divides by the selling price of N24.00."}},{"itemId":"2a56208f-6526-51a7-9b9f-c570c54a22cc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ecef9375-6f9c-5762-8b11-95e7bfbf6a46","sourceKey":"bank:BUA202:FIN-050","parentItemId":null,"revision":1,"payload":{"prompt":"Tola bought 500 shares at N12.00 each and later sold all of them at N15.00 each. Ignoring commissions and taxes, what was her capital gain?","options":["N3","N7,500","N6,000","N1,500"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Capital gain = number of shares x (selling price - buying price) = 500 x (15.00 - 12.00) = N1,500. Option B is the total sale proceeds (500 x 15), and option C is the original cost (500 x 12), not the gain. Option A is the gain on one share only."}},{"itemId":"614417eb-4962-5c61-87c4-6043866e4b10","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"58bf373d-9052-54e6-8e2f-2106275392d6","sourceKey":"bank:BUA202:FIN-051","parentItemId":null,"revision":1,"payload":{"prompt":"A Federal Government bond with a face value of N1,000,000 pays a coupon of 12% per annum, paid semi-annually. How much interest does the bondholder receive at each coupon payment?","options":["N60,000","N10,000","N240,000","N120,000"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Each semi-annual coupon = face value x annual coupon rate / 2 = 1,000,000 x 0.12 / 2 = N60,000. Option D is the full annual interest, paid as if only once a year. Option B is the monthly figure (120,000 / 12), which does not apply to semi-annual payments."}},{"itemId":"9fe02235-2eab-5d0e-9aae-9b0daf13bfc1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"74733139-5cb2-5697-9745-e2cb76c82fee","sourceKey":"bank:BUA202:FIN-052","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos SME borrows N2,000,000 from the Bank of Industry at 9% per annum simple interest for 3 years, with principal and interest repaid at the end. What is the total amount repayable (to the nearest naira)?","options":["N2,590,058","N2,540,000","N540,000","N2,180,000"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"With simple interest, total repayment = principal x (1 + rate x time) = 2,000,000 x (1 + 0.09 x 3) = N2,540,000. Option A wrongly compounds the interest: 2,000,000 x (1.09)^3. Option C is only the interest, without the principal."}},{"itemId":"db9101d9-7f5d-5638-9a33-789a00cc4aab","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"204daa69-bc2b-5907-b5ce-551a1d987342","sourceKey":"bank:BUA202:FIN-053","parentItemId":null,"revision":1,"payload":{"prompt":"A founder owns all 1,000,000 shares of her company. To raise equity finance, the company issues 250,000 new shares to an angel investor. What percentage of the company does the investor now own?","options":["80%","25%","20%","75%"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Investor's stake = new shares / total shares after the issue = 250,000 / (1,000,000 + 250,000) x 100 = 20%. Option B divides by the founder's original 1,000,000 shares and forgets that the total has grown. Option A is the founder's remaining stake."}},{"itemId":"8fd006a3-9024-5ce7-a70b-0acc6d34c217","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2c7571f4-3b6c-591e-8ee2-0bc766131e5d","sourceKey":"bank:BUA202:FIN-054","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund has total assets of N900 million, liabilities of N50 million and 425 million units in issue. Taking net asset value (NAV) per unit as (total assets - liabilities) / units in issue, what is the NAV per unit (to 2 decimal places)?","options":["N2.12","N0.50","N2.24","N2.00"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NAV per unit = (900,000,000 - 50,000,000) / 425,000,000 = 850,000,000 / 425,000,000 = N2.00. Option A ignores the liabilities (900 / 425), and option C adds the liabilities instead of subtracting them (950 / 425). Option B turns the formula upside down."}},{"itemId":"a9ba9da6-5797-52bc-92aa-c9e64b2cb05f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"86ef902f-7c11-524c-a8e1-01d8f2e70210","sourceKey":"bank:BUA202:FIN-055","parentItemId":null,"revision":1,"payload":{"prompt":"A company can raise N5,000,000 either through an unsecured debenture at 15% per annum or a secured bond at 12% per annum. How much more annual interest will it pay if it chooses the debenture?","options":["N750,000","N1,350,000","N600,000","N150,000"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Extra interest = 5,000,000 x (0.15 - 0.12) = 750,000 - 600,000 = N150,000 a year, reflecting the higher rate investors demand for an unsecured debenture. Option A is the total debenture interest and option C is the total bond interest, not the difference. Option B adds the two together."}},{"itemId":"1e7ecaba-615d-50ea-b371-3be54da372c6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"dcb3e8bd-44ee-5fc8-bcd0-47e3f6c05092","sourceKey":"bank:BUA202:HRM-001","parentItemId":null,"revision":1,"payload":{"prompt":"The systematic process of managing people within an organisation, which involves recruiting, hiring, deploying and managing employees, is known as","options":["Workforce planning","Industrial relations","Human resource management","Organisational development"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Human resource management is the systematic process of managing people in an organisation, covering recruiting, hiring, deploying and managing employees. Option A (workforce planning) and option B (industrial relations) are only parts of what HRM covers, while option D is about improving the whole organisation, not managing its people as such."}},{"itemId":"6ebf6fa8-b8de-526b-b907-945a2380ccd9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2b8c49c1-20e1-5a33-8991-3c8b427ce0e7","sourceKey":"bank:BUA202:HRM-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of human resource management?","options":["It supports the wellbeing of employees","It treats employees mainly as interchangeable factors of production","It focuses on people","It aligns the goals of individuals with the goals of the organisation"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"HRM sees people as complex beings to be developed, so treating them as interchangeable factors of production is the opposite of an HRM feature; that was the flaw of the classical school. Options C, D and A are all genuine features: HRM focuses on people, aligns individual and organisational goals, and supports employee wellbeing."}},{"itemId":"cfce9a40-36d0-5f0f-b28d-96cd043782cd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"45cd2462-5592-5797-8de8-295cdf5b99c6","sourceKey":"bank:BUA202:HRM-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which author gave the concise definition \"HRM is the utilization of individuals to achieve organizational objectives\"?","options":["Michael Armstrong","R. Wayne Mondy","John Storey","Edwin B. Flippo"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"R. Wayne Mondy's definition is the shortest of the standard definitions: HRM is simply using individuals to achieve organisational objectives. Option A (Armstrong) stressed a strategic approach to managing the organisation's most valued assets, option D (Flippo) listed six operative functions, and option C (Storey) linked HRM to competitive advantage through a committed workforce."}},{"itemId":"f7e1ab7b-9a84-5732-8294-2ee83198f88a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"22faaf0a-ab22-5ebb-9de3-dc83dd38f72b","sourceKey":"bank:BUA202:HRM-006","parentItemId":null,"revision":1,"payload":{"prompt":"\"HRM is the design of formal systems in an organization to manage human talent for accomplishing organizational goals.\" This definition belongs to","options":["Gary Dessler","Robert L. Mathis and John H. Jackson","Wendell L. French","John Bratton and Jeff Gold"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Mathis and Jackson define HRM in systems terms: designing formal systems to manage human talent for organisational goals. Option D (Bratton and Gold) tied HRM to sustainable competitive advantage, option C (French) listed recruitment, selection, development, utilisation and accommodation, and option A (Dessler) is known for a practical, managerial-responsibility view rather than this wording."}},{"itemId":"9e454891-345d-58e1-9a98-ca9f8744a84b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5987c621-2329-5e30-9965-b25196f0b324","sourceKey":"bank:BUA202:HRM-007","parentItemId":null,"revision":1,"payload":{"prompt":"Bratton and Gold define HRM as a strategic approach to managing employment relations to achieve sustainable competitive advantage. Their definition is rooted in which theory of the firm?","options":["Scientific management","Bureaucratic theory","Agency theory","The resource-based view"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The resource-based view says a firm gains lasting advantage from valuable resources that rivals find hard to copy, and Bratton and Gold treat people as exactly such a resource. Option A and option B are classical management theories that treated workers as inputs, and option C is about the relationship between owners and managers, not people as a basis of advantage."}},{"itemId":"84519e4e-ca4c-53d8-86d0-5d0110edb670","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7a7e634b-406a-5cdc-a2dd-a1c3090cbe17","sourceKey":"bank:BUA202:HRM-008","parentItemId":null,"revision":1,"payload":{"prompt":"John Storey's definition of HRM is especially remembered for solidifying the distinction between","options":["Recruitment and selection","Personnel records and payroll","Hard HRM and soft HRM","Line management and staff management"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Storey described HRM as seeking competitive advantage through a highly committed workforce, and his work cemented the contrast between hard HRM (people as a cost to control) and soft HRM (people as an asset to develop). Option D is a separate organisational distinction, and options A and B are pairs of routine HR activities, not the conceptual split Storey is known for."}},{"itemId":"78011c82-0f9c-5850-a6dd-f1579fd23f2c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"87389335-6660-5b0a-b8d9-9a7922c670c5","sourceKey":"bank:BUA202:HRM-009","parentItemId":null,"revision":1,"payload":{"prompt":"The MD of a Lagos packaging company sees staff mainly as a cost to be controlled: headcount is kept to a minimum, jobs are tightly specified and spending on training is cut whenever possible. This approach is best described as","options":["The human relations approach","Talent management","Soft HRM","Hard HRM"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Hard HRM treats people as a cost or resource to be controlled and used efficiently, which matches tight headcount and minimal training. Option C is the opposite, treating people as valued assets to be developed, option A stresses workers' social and emotional needs, and option B is about attracting, developing and retaining talent, which this MD is neglecting."}},{"itemId":"958e1279-3e16-55e6-8cc6-473d64589c1d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3ad44572-a620-510d-b523-4420647cc4ac","sourceKey":"bank:BUA202:HRM-010","parentItemId":null,"revision":1,"payload":{"prompt":"An Abuja software firm invests heavily in training, involves staff in decisions and tries to win their long-term commitment because it regards them as its most valuable asset. This reflects","options":["Traditional personnel administration","Soft HRM","Hard HRM","The classical school of management"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Soft HRM treats employees as valued assets whose commitment and development create advantage, which is exactly this firm's approach. Option C treats people as a cost to be controlled, option A is mainly routine record-keeping and administration, and option D saw workers as passive labour inputs."}},{"itemId":"b301de44-4007-5b62-afbf-0de65b2dd64d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"883631e0-98f3-5bbf-b124-71fb28fa875b","sourceKey":"bank:BUA202:HRM-011","parentItemId":null,"revision":1,"payload":{"prompt":"\"A strategic approach to the management of an organization's most valued assets, the people working there, who individually and collectively contribute to the achievement of its objectives.\" Which author defined HRM this way?","options":["Michael Armstrong","Wendell L. French","Edwin B. Flippo","R. Wayne Mondy"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Michael Armstrong framed HRM as a strategic approach to managing people as the organisation's most valued assets, so HRM must align with business strategy. Option B and option C gave earlier, more administrative definitions built on lists of activities, and option D gave a very short 'utilization of individuals' definition."}},{"itemId":"a784bb69-2fbc-5fd4-80bf-9af37261d363","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d6351dff-fdfd-5b77-8e39-fee2e387f852","sourceKey":"bank:BUA202:HRM-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which author defined HRM as \"the recruitment, selection, development, utilization of, and accommodation to, human resources by organizations\"?","options":["John Storey","Wendell L. French","Michael Armstrong","John Bratton and Jeff Gold"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Wendell L. French gave this activity-based definition, which keeps HRM in an administrative, procedural mould. Options A, C and D all gave strategic definitions that link HRM to organisational strategy or competitive advantage rather than listing activities."}},{"itemId":"a5a34889-0741-59fb-ae30-ac78896dff41","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"abb05ba7-b561-517c-b95a-41b23532ca8e","sourceKey":"bank:BUA202:HRM-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which author is associated with viewing HRM through the lens of managerial responsibility, with a practical and operational focus on specific functional practices?","options":["John Storey","Michael Armstrong","Gary Dessler","John Bratton and Jeff Gold"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Gary Dessler's view of HRM is practical and operational, focused on what managers must actually do in specific HR practices. Option A is known for the hard versus soft distinction, option D for linking HRM to sustainable competitive advantage, and option B for describing HRM as a strategic approach."}},{"itemId":"8c98466b-305b-50e0-9d5b-62c723a3ba32","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9a8f34d8-e953-539e-bafa-0fade5081a3b","sourceKey":"bank:BUA202:HRM-014","parentItemId":null,"revision":1,"payload":{"prompt":"Taken together, definitions of HRM from the 1960s to the 2000s show a general shift","options":["From managing teams to managing individual machines and equipment","From a strategic view of managing people to a purely administrative one","From a focus on employee wellbeing to a focus on payroll only","From an administrative, procedural view of managing people to a strategic view"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Early definitions such as Flippo's and French's describe administrative activities, while later ones such as Armstrong's, Storey's and Bratton and Gold's treat HRM as a strategic partner tied to competitive advantage. Option B reverses the real direction of change, and options C and A describe shifts that never happened in how HRM was defined."}},{"itemId":"8cb92ae1-e2fe-5792-a2f3-758703465bef","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"962217f7-b756-589a-8276-1666e0bcc336","sourceKey":"bank:BUA202:HRM-017","parentItemId":null,"revision":1,"payload":{"prompt":"Career development, job satisfaction, work-life balance, employee wellbeing, and recognition and dignity are grouped under which category of HRM objectives?","options":["Organisational objective","Personal objective","Societal objective","Functional objective"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The personal objective focuses on the individual employee's own experience at work, including career growth, satisfaction, balance, wellbeing and dignity. Option D is about the HR function's systems, option C is about obligations to society, and option A is about organisational results."}},{"itemId":"7d547fd6-4efe-5ba1-9773-98d68162c777","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"17ab8d33-3d5e-520b-9312-05801cd9c1ef","sourceKey":"bank:BUA202:HRM-018","parentItemId":null,"revision":1,"payload":{"prompt":"Workforce planning, productivity enhancement, cost management, organisational development and talent acquisition are examples of which category of HRM objectives?","options":["Organisational objective","Functional objective","Personal objective","Societal objective"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The organisational objective is HRM's contribution to the business itself, such as planning the workforce, raising productivity, controlling cost and acquiring talent. Option C centres on the individual employee, option D on duties to society, and option B on the quality of HR's own systems and metrics."}},{"itemId":"0c787fce-8ead-5b09-87ad-92cb67803d91","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7a5620ac-3dc0-5e6c-b883-aeab9bc73161","sourceKey":"bank:BUA202:HRM-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a personal objective of HRM?","options":["Career development","Work-life balance","Recognition and dignity","Productivity enhancement"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Productivity enhancement is an organisational objective because it serves the business's performance rather than the individual employee. Options A, B and C are all personal objectives, centred on the employee's own growth, balance and dignity."}},{"itemId":"914f02c6-bc7e-5012-b2a1-64d83aff44f9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"222593a4-7528-5f7a-b14f-89854052cd55","sourceKey":"bank:BUA202:HRM-020","parentItemId":null,"revision":1,"payload":{"prompt":"The HR unit of a Lagos bank introduces flexible working hours, a staff wellness programme and a clear career path for every officer. Which category of HRM objectives is it mainly pursuing?","options":["Personal objective","Societal objective","Functional objective","Organisational objective"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Flexible hours, wellness and career paths all serve employees' own work-life balance, wellbeing and career development, which are personal objectives. Option B would involve legal compliance or CSR, option C would involve HR systems and metrics, and option D would involve business targets such as productivity or cost."}},{"itemId":"64928169-7d10-53e2-bab6-d5943e49db7e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2b0a2cae-bb9d-5aac-bdc8-2d4b924ce917","sourceKey":"bank:BUA202:HRM-021","parentItemId":null,"revision":1,"payload":{"prompt":"An HR manager in Ibadan builds a monthly dashboard that tracks staff turnover, absence rates and time-to-hire, and uses it to improve HR's own processes. Which HRM objective does this mainly serve?","options":["Organisational objective","Functional objective","Societal objective","Personal objective"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Tracking HR metrics to improve HR's own processes is part of the functional objective, which covers HR systems quality and HR metrics and analysis. Option D centres on employees' own needs, option C on duties to society, and option A on business-wide goals like productivity and cost."}},{"itemId":"ca95a173-47f5-5a38-bdc2-7d91903b30cd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"aeff7059-4fcd-5925-8e62-bc4355b04c2b","sourceKey":"bank:BUA202:HRM-022","parentItemId":null,"revision":1,"payload":{"prompt":"Every organisation is said to have three basic components. Which of the following is NOT one of them?","options":["Purpose","Technology","People","Structure"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The three basic components of any organisation are people, purpose and structure; technology is a tool an organisation uses, not one of these three. Option C is the workforce that drives the organisation, option A is its reason for existing, and option D is how it assigns roles and tasks."}},{"itemId":"7a427771-ff96-5e81-b2e4-388767f4e472","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0317fed3-e09d-578b-a154-f6059c46362a","sourceKey":"bank:BUA202:HRM-023","parentItemId":null,"revision":1,"payload":{"prompt":"The element of an organisation that dictates how roles, responsibilities and tasks are assigned, shown through the organogram, processes, policies and strategic plans, is its","options":["Purpose","Culture","Structure","People"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Structure is how an organisation arranges roles, responsibilities and tasks to accomplish its purpose, and it is seen in the organogram, processes and policies. Option A is the reason the organisation exists, option D is the workforce that carries out plans, and option B is shared values and beliefs, which is not one of the three core elements."}},{"itemId":"248b87f6-fe6a-5f2d-b075-6bbe89aedb0b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"513f75dc-9aff-5059-8528-6ae026ec2a8b","sourceKey":"bank:BUA202:HRM-024","parentItemId":null,"revision":1,"payload":{"prompt":"Why are people described as the driving force of an organisation?","options":["People decide the organisation's mission without any reference to its structure","People are the cheapest resource an organisation can obtain","People can be replaced by machines once the structure is in place","Without people to implement plans, the structure and purpose cannot be achieved"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"People are the driving force because they are the ones who implement plans; without them, the purpose and structure exist only on paper. Option A misstates their role, option B is not the reason they matter, and option C contradicts the point that people bring creativity and judgement machines cannot replace."}},{"itemId":"99eea225-69e2-59bd-ade7-6ac7bb6147a9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ba111090-b9f8-5d84-ba18-acb78d10a4d7","sourceKey":"bank:BUA202:HRM-025","parentItemId":null,"revision":1,"payload":{"prompt":"The primary reason an organisation is established, defined by its mission and vision and broken down into specific objectives, is its","options":["Organogram","Structure","Purpose","Workforce plan"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Purpose is why the organisation exists, expressed through its mission and vision and then broken into objectives such as providing a service or earning revenue. Option B is how roles and tasks are arranged, option A is just a chart that shows the structure, and option D is an HR tool for sizing the workforce."}},{"itemId":"6c44f062-61e5-5798-abc4-94f52afd01ec","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"129ae428-e185-5107-99d2-75a303d2c95c","sourceKey":"bank:BUA202:HRM-027","parentItemId":null,"revision":1,"payload":{"prompt":"Directing, motivating and influencing the people within an organisation describes which management function?","options":["Leading","Controlling","Organising","Planning"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Leading is the people-facing function of management: directing, motivating and influencing staff. Option B is about monitoring and correcting performance, option C about structuring resources and activities, and option D about setting goals and courses of action."}},{"itemId":"2b62fda9-2c3f-5156-8b9b-45fdc05f4ea9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b62446f5-917d-55a5-a6f0-b2a4c7d6a68e","sourceKey":"bank:BUA202:HRM-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which conclusion is drawn from the human relations movement about employees?","options":["They are social and emotional assets whose wellbeing and satisfaction directly drive performance","They are inanimate factors of production like machines and capital","They are motivated only by money, so pay is the sole lever managers need","They work best when isolated from co-workers and closely timed"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The human relations movement showed that people are social, emotional beings and that their wellbeing and satisfaction directly affect performance. Option D is contradicted by the finding that isolating workers hurts performance, option C ignores their social needs, and option B is the classical school's view that the movement rejected."}},{"itemId":"5aac9122-4ff7-567b-992f-1036c5b28553","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d2dcedcc-e3ad-5be4-86a7-1d222abb37bc","sourceKey":"bank:BUA202:HRM-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of the classical school of management?","options":["The human relations movement","Scientific management","General administrative theory","Bureaucratic theory"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The human relations movement came after the classical school and reacted against it by stressing workers' social and emotional needs. Options B, C and D are the three branches of the classical school, which treated people as passive labour inputs."}},{"itemId":"092eda89-061c-5a6d-a06a-b8cb2db16f4c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0af83675-e332-558e-8434-8b7788a4fa36","sourceKey":"bank:BUA202:HRM-032","parentItemId":null,"revision":1,"payload":{"prompt":"Sizing and planning human capital so that it supports company strategies is the HRM functional area called","options":["Performance management","Employee relations","Workforce planning","Compensation management"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Workforce planning means working out how many people, with what skills, the business needs to carry out its strategy. Option D structures pay and rewards, option A monitors and evaluates how employees perform, and option B handles grievances and the work environment."}},{"itemId":"9a782544-d8f8-5c5e-a00a-b0e21f36b1a3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5df5bbe5-badc-5741-8fc1-8206b7be09b4","sourceKey":"bank:BUA202:HRM-034","parentItemId":null,"revision":1,"payload":{"prompt":"At a Port Harcourt oil services firm, the HR team handles staff grievances, addresses complaints about canteen conditions and works to keep the workplace conducive. These activities belong to which HRM functional area?","options":["Recruitment and selection","Performance management","Compensation management","Employee relations and well-being"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Employee relations and well-being covers resolving grievances, addressing staff concerns and maintaining a conducive work environment. Option B is about monitoring and evaluating performance, option C about pay and incentives, and option A about sourcing and hiring people."}},{"itemId":"726aa6d6-eaa0-5e11-9675-9fb5360df71d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c2f9c154-74c9-5d11-93d0-a2db12cf0930","sourceKey":"bank:BUA202:HRM-035","parentItemId":null,"revision":1,"payload":{"prompt":"The HRM functional area concerned with monitoring and evaluating how employees carry out their work is","options":["Workforce planning","Employee relations","Training and development","Performance management"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Performance management monitors and evaluates employee execution so that results can be improved. Option B deals with grievances and the work climate, option A sizes the workforce, and option C builds skills over the long term rather than evaluating current performance."}},{"itemId":"c2134f6a-dc17-504f-abb4-3c901cb5be28","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7b047361-fde1-545f-b9c4-cc6c06552aa1","sourceKey":"bank:BUA202:HRM-036","parentItemId":null,"revision":1,"payload":{"prompt":"Cultivating employees' skills, capabilities and professional certifications over the long term is the HRM function of","options":["Training and development","Performance management","Compensation management","Recruitment and selection"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Training and development builds employees' skills and professional qualifications over time. Option C concerns pay and incentives, option B evaluates how well people perform, and option D brings new people into the organisation."}},{"itemId":"41850e82-541c-538b-bb01-fb76ae9b381b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"60a47dc5-e742-5cf5-b8e1-fa430717e9dd","sourceKey":"bank:BUA202:HRM-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which characteristic of HRM refers to actively aligning individual workers' behaviours and outputs with corporate goals?","options":["Strategic integration","Human capital","Goal alignment","Competitive advantage"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Goal alignment is about making sure what each worker does and produces supports the company's goals. Option A is HR working with top leadership on strategy, option D is the result of executing HRM well, and option B is the skills and knowledge employees hold."}},{"itemId":"a5d79dfa-dbaf-5aeb-be3b-8f950845bed7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"eddaca9e-bd5b-501c-9302-a1ce76f02dd7","sourceKey":"bank:BUA202:HRM-040","parentItemId":null,"revision":1,"payload":{"prompt":"Talent management is best defined as","options":["Strategies to attract, develop, retain and use people with the required skills and aptitude to meet current and future organisational needs","The process of structuring pay, bonuses and incentives for top performers only","The emotional commitment an employee has to the organisation and its goals","The collective skills and knowledge of employees that add to the organisation's value"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Talent management covers the whole cycle of attracting, developing, retaining and using people with the right skills for present and future needs. Option C defines employee engagement, option D defines human capital, and option B describes part of compensation management."}},{"itemId":"026c0033-ac79-5a64-81dc-8bc082c39f95","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0ca5d38e-2763-5463-a05c-a9557f8a6b3f","sourceKey":"bank:BUA202:HRM-042","parentItemId":null,"revision":1,"payload":{"prompt":"It is said that there is no best way to manage people. The reason given is that","options":["Every organisation uses the same management methods","Labour laws forbid a single approach to managing staff","Managers are not trained in people management","People are complex beings with complex needs"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Because people are complex beings with complex and varied needs, no single formula works for managing all of them, and effective HRM depends on the conditions of each organisational setting. Options C, A and B are not the reason, and option A is untrue since organisations differ widely."}},{"itemId":"1ba63b90-157f-584e-9e5f-70fc6846b14c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"72988416-b56d-55cb-8f55-36fc499d69aa","sourceKey":"bank:BUA202:HRM-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes human resource management from traditional personnel management?","options":["Personnel management is broader in scope than HRM and includes business strategy","HRM is strategic and proactive, linked to business strategy, while personnel management is mainly administrative and reactive","HRM deals only with payroll and staff records, while personnel management handles strategy","They are simply two names for exactly the same function with no difference in approach"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Traditional personnel management focused on routine administration such as records, payroll and rules, and responded to problems as they arose, while HRM is integrated with business strategy and treats people as assets to be developed. Option A and option C reverse the two, and option D ignores the clear shift in approach."}},{"itemId":"18d3af66-bcbc-50c0-ab61-5da3a2c017a4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"eb8c8386-8af0-5130-8616-b242492fa6c1","sourceKey":"bank:BUA202:HRM-044","parentItemId":null,"revision":1,"payload":{"prompt":"An officer at an Onitsha trading company spends all her time keeping staff files, processing leave forms and running payroll, and has no input into the company's business plans. Her role is closest to","options":["Traditional personnel management","Strategic human resource management","Organisational development","Talent management"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Routine administration such as records, leave and payroll, with no link to business strategy, is the hallmark of traditional personnel management. Option B would require her to work with top management on strategy, option D involves attracting, developing and retaining talent, and option C is planned improvement of the whole organisation."}},{"itemId":"85188ac1-9a47-506c-89cf-77b4ba9891a7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cc57f76f-1ec8-5b95-bb95-591aa2a4f1de","sourceKey":"bank:BUA202:HRM-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is more characteristic of HRM than of traditional personnel management?","options":["Viewing employees as valuable assets whose development creates competitive advantage","Keeping the people function separate from business strategy","Focusing mainly on record-keeping and compliance with staff rules","Reacting to staff problems only after they arise"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"HRM sees people as assets to develop and links their management to competitive advantage, as in Bratton and Gold's definition. Options C, D and B describe the older personnel management approach, which was administrative, reactive and cut off from strategy."}},{"itemId":"cde033f6-ef5e-5899-8ee6-b4b75c7debf5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f816f4cd-3873-5a94-8794-75fba7618e0c","sourceKey":"bank:BUA202:HRM-046","parentItemId":null,"revision":1,"payload":{"prompt":"In most organisations, who is directly responsible for the day-to-day supervision, appraisal and coaching of the employees in a work unit?","options":["The HR department alone, with no role for line managers","The board of directors","The line manager of that unit, with the HR department giving specialist support","The trade union representative"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Line managers carry day-to-day people responsibilities for their own teams, such as directing, appraising and coaching, while the HR department provides policies, advice and specialist services. Option A wrongly removes line managers from people management, option B sets overall direction rather than supervising staff, and option D represents workers rather than managing them."}},{"itemId":"c9ebe3e9-470f-5278-93e3-7c36600a2704","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"49820622-295c-5507-83e2-bf5f6420fa6d","sourceKey":"bank:BUA202:HRM-047","parentItemId":null,"revision":1,"payload":{"prompt":"A production supervisor in an Ikeja factory wants to discipline a worker for repeated lateness. What is the usual role of the HR department in this situation?","options":["To stay out of the matter completely because discipline is not an HR issue","To take over supervising the worker permanently","To advise on the correct disciplinary policy and procedure while the supervisor handles the case","To dismiss the worker immediately without involving the supervisor"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The HR department plays an advisory, specialist role: it designs policies and advises line managers on handling issues like discipline fairly and legally, while the line manager deals with the employee. Option B confuses advising with supervising, option A ignores HR's role in employee relations, and option D skips both the line manager and fair procedure."}},{"itemId":"e3f6402a-6aa8-59dc-849a-aca3e892f6ca","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fcdd9367-9b2e-5b9e-ab93-53706c9c0bf5","sourceKey":"bank:BUA202:HRM-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which characteristic of HRM holds that, when properly executed, HRM ensures the organisation remains competitive within its market?","options":["Employee relations","Competitive advantage","Goal alignment","Strategic integration"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The competitive advantage characteristic says good HRM helps the organisation stay ahead of rivals in its market. Option C is about aligning individual output with corporate goals, option D is about HR working with top leadership on strategy, and option A is an HR functional area dealing with grievances and wellbeing."}},{"itemId":"b0e34e73-e2ee-54f3-ba10-72e7a97a9c18","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"10c7fb7f-662d-55a9-b150-386a9ae4c118","sourceKey":"bank:BUA202:HRM-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is listed among the broader objectives of HRM?","options":["Knowledge retention","Maximising shareholder dividends","Preparing statutory financial statements","Fixing the selling prices of products"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Knowledge retention, keeping valuable know-how inside the organisation as staff come and go, is one of HRM's broader objectives, alongside managing change and diversity and inclusion. Option B is a finance goal, option D is a marketing decision, and option C is an accounting task."}},{"itemId":"ee1a848e-31d2-5464-8ed3-fd9f3a86fe7d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"feef8746-5dd6-527e-9bb1-7f30a88be1cf","sourceKey":"bank:BUA202:HRM-050","parentItemId":null,"revision":1,"payload":{"prompt":"HRM encompasses functions such as workforce planning, recruitment, training, performance management, compensation and employee relations. Which of the following is NOT one of these HRM functions?","options":["Product design","Compensation","Workforce planning","Employee relations"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Designing products is an engineering or marketing task, not a people-management function. Options C, B and D are all functions HRM encompasses, together with recruitment, training and performance management."}},{"itemId":"bbeb5c68-da15-536e-91f0-a4067b2b7d14","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"55c699c7-8703-552c-bb12-e5967befd0e0","sourceKey":"bank:BUA202:HRP-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of developing a plan to satisfy an organisation's human resource needs, so that it has the right number of employees with the right skills in the right places at the right times, is called","options":["Performance appraisal","Job analysis","Succession planning","Human resource planning"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Human resource planning matches the organisation's future people needs with the people it will have, in number, skills, place and time. Option B studies a single job's tasks and requirements, option A evaluates how employees have performed, and option C focuses only on filling key positions."}},{"itemId":"21fbe4a1-3a61-5bca-913f-0baaaf10f6f0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b03f8886-c0bb-56c0-8f23-a2b068345f91","sourceKey":"bank:BUA202:HRP-004","parentItemId":null,"revision":1,"payload":{"prompt":"A job description is a written statement of","options":["How well the current job holder has performed","The duties and responsibilities of a job","The qualifications and skills a person needs to fill the job","The salary and benefits paid to the job holder only"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"A job description sets out what the job involves: its duties, responsibilities and reporting lines. Option C describes the job specification, which focuses on the person rather than the job, option A is a performance appraisal, and option D is only part of the reward package."}},{"itemId":"fa81a147-1d62-5912-b35f-34b736306426","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a0f216a4-c2ac-5366-87df-a1f022e60cba","sourceKey":"bank:BUA202:HRP-005","parentItemId":null,"revision":1,"payload":{"prompt":"A job specification states","options":["The performance targets the job holder must meet this year","The duties, tasks and reporting lines that make up the job","The steps the organisation follows in its selection process","The qualifications, skills and experience required of the job holder"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"A job specification describes the kind of person needed for the job, such as qualifications, skills and experience. Option B is the job description, option C describes the selection process, and option A describes performance objectives."}},{"itemId":"e411d1cd-dfb2-5d8d-9bc4-fac70e3cbebe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"66e6b6f7-d3f4-55ec-8280-d2f225ac9222","sourceKey":"bank:BUA202:HRP-006","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos firm's document for an accountant role reads: 'B.Sc. Accounting, ICAN membership, at least three years' audit experience, good spreadsheet skills.' This document is a","options":["Job description","Performance appraisal form","Job specification","Offer letter"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Listing the qualifications, membership and experience the job holder must have is what a job specification does. Option A would list the duties of the role, option D offers the job to a chosen candidate, and option B records how someone has performed."}},{"itemId":"59167997-85b4-5345-ab3e-3fcecb806ef6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a5d93220-1fa1-50c8-9499-b58ef198ea1d","sourceKey":"bank:BUA202:HRP-007","parentItemId":null,"revision":1,"payload":{"prompt":"A document for an Abuja hotel's front office supervisor states: 'Supervises six receptionists, prepares the daily occupancy report, resolves guest complaints, reports to the front office manager.' This is a","options":["Employment test","Job description","Job specification","Succession plan"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Listing duties, responsibilities and the reporting line is the content of a job description. Option C would state the qualifications and experience needed, option A assesses candidates, and option D plans who will fill key roles in future."}},{"itemId":"2ff5b1bf-0992-5856-85a1-d3cbedb63c0e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"adbbbb8f-9314-560b-b780-4bf911f90170","sourceKey":"bank:BUA202:HRP-008","parentItemId":null,"revision":1,"payload":{"prompt":"The two main documents produced from a job analysis are","options":["The organisation chart and the payroll register","The appraisal form and the training plan","The job description and the job specification","The offer letter and the employment contract"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Job analysis produces a job description, which covers the job's duties, and a job specification, which covers the qualifications the holder needs. Option D belongs to the end of selection, option B belongs to performance management and training, and option A relates to structure and pay administration."}},{"itemId":"51281c36-6800-5a77-9185-585e59164f76","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"58afb466-d83e-576a-93d3-b46d9fb7a2cd","sourceKey":"bank:BUA202:HRP-009","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm's HR forecast shows that demand for machine operators next year will exceed the supply of available workers. Which response fits this situation?","options":["Eliminating some operator positions","Offering early retirement to current operators","Not replacing operators who resign","Offering overtime or subcontracting part of the work"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"When demand for labour exceeds supply, the firm needs more labour, so hiring, overtime, subcontracting or labour-saving initiatives are the right responses. Options B, C and A reduce the workforce, which is what a firm does when supply exceeds demand."}},{"itemId":"5bdcfc41-f15b-5ec5-83ca-4f8225d4bd6e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"258f31dc-094f-54dd-88f4-e7e667a8361c","sourceKey":"bank:BUA202:HRP-010","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano bank's HR forecast shows it will have more clerical staff than it needs after automating some processes. Which response is appropriate?","options":["Asking clerks to work overtime","Subcontracting clerical work to an outside firm","Not replacing clerks who leave and offering early retirement","Recruiting more clerks through agencies"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"When supply of labour exceeds demand, the firm reduces its workforce gradually through attrition, early retirement or, if needed, eliminating positions. Options D, A and B add labour, which suits a shortage, not a surplus."}},{"itemId":"34b9033d-699e-56b7-8972-bd33af053277","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2439b9d2-4758-59dc-a5c6-f878e5133eb8","sourceKey":"bank:BUA202:HRP-011","parentItemId":null,"revision":1,"payload":{"prompt":"The purpose of human resource supply and demand forecasting is to","options":["Compare available workers with forecast needs to identify future hiring or job-reduction needs","Set the selling prices of the firm's labour-intensive products","Calculate the expected market demand for the firm's products next year","Measure how satisfied customers are with the service of staff"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"HR supply and demand forecasting compares how many workers will be available with how many will be needed, so the firm knows whether to hire or reduce staff. Option C is sales forecasting, option B is a pricing decision, and option D is a marketing measure."}},{"itemId":"17034250-4cc8-597e-b4e2-077b8a6167c1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b5999c52-9a08-563e-8003-0c931dca76b3","sourceKey":"bank:BUA202:HRP-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes recruitment from selection?","options":["Recruitment chooses the best candidate; selection attracts applicants","Recruitment attracts a pool of suitable applicants; selection chooses the best candidate from that pool","Recruitment and selection both mean training new employees","Selection always happens before recruitment"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Recruitment comes first and builds a pool of qualified applicants, while selection follows and picks the most suitable person from that pool. Option A swaps the two, option C confuses them with training, and option D gets the order wrong."}},{"itemId":"ffe89bd5-e661-50a6-a6c3-62fad3c001ba","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ede492b0-b961-577b-ad35-5eff80a6033d","sourceKey":"bank:BUA202:HRP-013","parentItemId":null,"revision":1,"payload":{"prompt":"Choosing the best-qualified person from a group of applicants for a job is called","options":["Recruitment","Placement planning","Selection","Orientation"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Selection is the step where the organisation picks the most suitable candidate from those who applied. Option A is attracting the applicants in the first place, option D introduces the new hire to the organisation after appointment, and option B is not the name of this step."}},{"itemId":"fb406f31-538e-5a1e-a3d5-1a57306ed6c0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6b2c69f7-1198-5410-a161-b5d411cbd46f","sourceKey":"bank:BUA202:HRP-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of internal recruitment?","options":["It motivates staff by signalling upward mobility and is usually cheaper","It is the only option for entry-level roles","It always brings fresh ideas from outside the company","It never creates another vacancy to fill"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Filling a post from within shows staff they can grow, costs less and involves a candidate whose performance is already known. Option C is an advantage of external recruitment, option D is false because promoting someone leaves their old post empty, and option B describes when external recruitment is needed."}},{"itemId":"9c45694e-bd39-5949-aa83-504e5ca66797","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a5090067-943e-54cb-bf29-9a08e9f6b6df","sourceKey":"bank:BUA202:HRP-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of internal recruitment?","options":["It discourages staff by blocking promotion","It is always more expensive than external recruitment","It creates a new vacancy and may limit fresh ideas","The candidate's performance is completely unknown"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Promoting from within leaves the promoted person's old job empty and keeps the same thinking inside the firm. Option D is a drawback of external recruitment, option B reverses the usual cost advantage of internal recruitment, and option A is wrong because internal recruitment actually encourages staff."}},{"itemId":"0bb6fd12-3613-5d78-a550-bed4777911b9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5bd82a04-e2a5-5874-a7ab-750d6c286a10","sourceKey":"bank:BUA202:HRP-016","parentItemId":null,"revision":1,"payload":{"prompt":"The main advantage of external recruitment is that it","options":["Uses candidates whose performance is already known","Is cheaper and less risky than promoting from within","Signals upward mobility to existing staff","Brings in new skills and perspectives from outside the organisation"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"External recruitment brings in fresh skills and ideas the firm does not yet have. Option B is the opposite of the truth, since external hiring is usually costlier and riskier, and options C and A are advantages of internal recruitment."}},{"itemId":"bf2f9f8e-0910-5a44-9857-0a566d7f18a3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b9874ccd-809f-5a3d-a8bb-99223deb4fbf","sourceKey":"bank:BUA202:HRP-018","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank fills the vacant post of branch manager by promoting one of its experienced relationship officers. This is an example of","options":["External recruitment","Internal recruitment","Headhunting","Campus recruitment"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Filling a post with an existing employee, for example by promotion, is internal recruitment. Options A, C and D all bring in people from outside the organisation."}},{"itemId":"921d3979-de67-53f0-a3f9-efcb495f78fa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"88fe8895-d57e-5361-bc11-e7cde3fdd0c4","sourceKey":"bank:BUA202:HRP-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a source of external recruitment?","options":["Internal job posting","Private employment agency","Campus recruitment","Newspaper or online job advertisement"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"An internal job posting advertises a vacancy to existing staff, so it is an internal recruitment method. Options D, B and C all reach people outside the organisation."}},{"itemId":"23406ef7-cf76-5122-9617-4aea3b34d776","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d5431c73-f533-56c2-9cc8-9044b5dee777","sourceKey":"bank:BUA202:HRP-020","parentItemId":null,"revision":1,"payload":{"prompt":"A recruitment method in which current employees recommend friends or contacts for vacant positions is called","options":["Employee referral","Headhunting","Job rotation","Walk-in application"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"An employee referral uses existing staff to recommend suitable candidates they know. Option C is a training method, option B uses specialist search firms to find senior people, and option D is when a job seeker turns up without being referred."}},{"itemId":"1d8e5d25-0ca0-58d6-a307-bfb5e5e8db6e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"48b500e9-69b6-55d3-85ab-c52a2d5d2282","sourceKey":"bank:BUA202:HRP-021","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian conglomerate pays a specialist search firm to identify and approach a suitable finance director who is currently employed by a competitor. This method is","options":["Headhunting (executive search)","Internal job posting","Employee referral","Campus recruitment"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Headhunting, or executive search, uses specialist firms to find and approach senior professionals, often people already employed elsewhere. Option D targets students and fresh graduates, option B advertises to existing staff, and option C relies on staff recommendations rather than a paid search firm."}},{"itemId":"38224961-53a2-50fc-9cdb-9e29e571e306","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"610e9e68-e260-5967-b548-95bbe0a8b20a","sourceKey":"bank:BUA202:HRP-022","parentItemId":null,"revision":1,"payload":{"prompt":"A consulting firm sets up a stand at a UNILAG career fair to recruit final-year students into its graduate trainee programme. This recruitment method is","options":["Campus recruitment","Headhunting","Internal recruitment","Succession planning"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Recruiting directly from universities and career fairs is campus recruitment, commonly used for graduate trainee roles. Option B targets experienced senior people, option C uses existing staff, and option D grooms insiders for key posts."}},{"itemId":"c9faf855-fa0d-518f-81d4-7c354a50af15","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"44c1e99a-075b-5c2a-a42d-f270d51ce137","sourceKey":"bank:BUA202:HRP-023","parentItemId":null,"revision":1,"payload":{"prompt":"In a selection process made up of application, employment tests, interview, physical exam and reference checks, and final decision, which stage is used to confirm a candidate's claims about education and work experience?","options":["Employment tests","Final decision","Physical exam and reference checks","Application"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Reference checks verify what the candidate has claimed about qualifications and experience, while the physical exam confirms fitness for the job. Option D is only an initial screen based on what the candidate says, option A measures skills or aptitude, and option B is the choice made after checks are complete."}},{"itemId":"646ea9dc-40b7-5e50-825c-e0611d3b5cbd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"946279a0-7415-5315-b954-2eeff86c4767","sourceKey":"bank:BUA202:HRP-024","parentItemId":null,"revision":1,"payload":{"prompt":"In a selection process made up of application, employment tests, interview, physical exam and reference checks, and final decision, the final decision is usually made by","options":["The line manager who will oversee the position","An external auditor","The trade union","The newest employee in the department"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"The final hiring decision normally rests with the line manager who will supervise the new employee, or an equivalent decision-maker, since that person must work with the hire. Options B, D and C have no role in choosing the candidate."}},{"itemId":"7c6b5e90-e47f-57c3-9bd3-1058b0d21eeb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"08102354-4314-55c5-bc0c-bf2cc44d3cee","sourceKey":"bank:BUA202:HRP-025","parentItemId":null,"revision":1,"payload":{"prompt":"In the selection process, the application form is mainly used as","options":["The final hiring decision made by the line manager","An initial screening tool based on the candidate's education and work background","A test of the candidate's personality and temperament","A check on the candidate's physical fitness for the job"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"The application gathers basic details about education and experience so the firm can screen out clearly unsuitable candidates early. Option A comes at the end of selection, option C is an employment test, and option D is the physical exam."}},{"itemId":"63e8f34b-fe39-5129-b651-ff9c1588a216","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8cd56bc9-290c-59d5-920f-f45a5eb1c523","sourceKey":"bank:BUA202:HRP-026","parentItemId":null,"revision":1,"payload":{"prompt":"A selection test that measures a candidate's potential or ability to learn new skills is","options":["A medical test","An integrity test","An aptitude test","A personality test"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"An aptitude test measures a person's capacity to learn or develop a skill, not just what they already know. Option D measures traits such as sociability or emotional stability, option A checks physical health, and option B assesses honesty."}},{"itemId":"03927f46-682c-5845-a135-b57c01a80c61","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1e8fad07-999c-53f8-a7e5-e50148698863","sourceKey":"bank:BUA202:HRP-027","parentItemId":null,"revision":1,"payload":{"prompt":"As part of selection for a secretarial post, candidates are asked to type a two-page letter so that their speed and accuracy can be measured. This is","options":["An aptitude test","A personality test","A reference check","A skills (work-sample) test"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"A work-sample or skills test asks candidates to do a real piece of the job, here typing, to measure their current ability. Option B measures traits, option A measures potential to learn rather than present skill, and option C contacts previous employers."}},{"itemId":"9d6ff4f6-0908-52fd-84b0-4b8f8f089940","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7411b102-210f-54cf-ad5f-5fc861cb19df","sourceKey":"bank:BUA202:HRP-028","parentItemId":null,"revision":1,"payload":{"prompt":"An interview in which every candidate is asked the same set of predetermined questions in the same order is","options":["A stress interview","A structured interview","An exit interview","An unstructured interview"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"A structured interview uses a fixed set of questions for all candidates, which makes answers easier to compare fairly. Option D is free-flowing with no set questions, option A deliberately puts candidates under pressure, and option C is held with employees who are leaving."}},{"itemId":"22885190-17ba-50a3-8588-74388247a890","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5ef8bf89-eb79-5116-a073-75b9403485b9","sourceKey":"bank:BUA202:HRP-029","parentItemId":null,"revision":1,"payload":{"prompt":"An unstructured interview is one in which","options":["Every candidate answers exactly the same written questions","There is no fixed list of questions and the conversation flows freely","The candidate is asked only about hypothetical future situations","Several interviewers question the candidate at the same time"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"In an unstructured interview the interviewer follows the conversation rather than a script. Option A describes a structured interview, option D a panel interview, and option C a situational interview."}},{"itemId":"50a705ae-e4fe-5a5b-b3b2-d5aed5b96240","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1b6f1453-5d67-5088-a8f1-e1766d595e4a","sourceKey":"bank:BUA202:HRP-030","parentItemId":null,"revision":1,"payload":{"prompt":"A candidate for a management trainee post at a Lagos telecoms company is interviewed at the same sitting by the HR manager, the head of operations and a senior engineer. This is","options":["An exit interview","A telephone screening interview","A one-on-one interview","A panel interview"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"A panel interview has several interviewers questioning the candidate together. Option C involves only one interviewer, option A is held with staff who are leaving, and option B is a short preliminary call."}},{"itemId":"aad729d7-cf21-5a52-899f-19ecc01289d9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6f79965c-be65-56e2-8356-500ced8a0945","sourceKey":"bank:BUA202:HRP-031","parentItemId":null,"revision":1,"payload":{"prompt":"An interviewer asks: 'Tell me about a time when you had to handle an angry customer. What did you do?' This type of interview question is","options":["Stress","Leading","Behavioural","Situational"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Behavioural questions ask candidates how they actually behaved in past situations, on the idea that past behaviour predicts future behaviour. Option D asks what the candidate would do in a hypothetical situation, option A deliberately pressures the candidate, and option B hints at the desired answer."}},{"itemId":"a02f413b-1364-56fe-abb7-512481396812","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5f1b410f-08bf-5f23-b36e-32a52d71bca7","sourceKey":"bank:BUA202:HRP-032","parentItemId":null,"revision":1,"payload":{"prompt":"An interviewer asks: 'Suppose a customer insists on a refund that company policy does not allow. What would you do?' This is a","options":["Personality test item","Reference check","Behavioural interview question","Situational interview question"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Situational questions present a hypothetical future scenario and ask what the candidate would do. Option C asks about what the candidate actually did in the past, option B involves contacting previous employers, and option A measures traits through a written test."}},{"itemId":"4373890d-e68e-5a5a-8557-4caabca63e99","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"415f1aa7-60ca-5182-b394-59440c1b1c1a","sourceKey":"bank:BUA202:HRP-033","parentItemId":null,"revision":1,"payload":{"prompt":"A selection test is said to be valid when it","options":["Is short and cheap to administer","Measures what it is meant to measure and predicts job performance","Gives the same results each time it is taken","Is taken by every applicant at the same time"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Validity means the test actually measures what it claims to measure, such as ability to do the job. Option C describes reliability, which is consistency, while options A and D are practical features, not validity."}},{"itemId":"a80d0043-f555-5523-9a13-4744f7184ab5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5bf76037-d8e9-52e0-a0e1-b54e655f3a3c","sourceKey":"bank:BUA202:HRP-034","parentItemId":null,"revision":1,"payload":{"prompt":"A selection test is said to be reliable when it","options":["Can be completed in under ten minutes","Accurately predicts how well candidates will perform on the job","Is approved by the labour ministry","Produces consistent results when repeated under similar conditions"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Reliability is about consistency: the same person should score about the same when tested again. Option B describes validity, and options C and A have nothing to do with how consistent the test is."}},{"itemId":"97d9c9b9-35a3-5e20-9f8d-51ec354f1ca7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3ecc6a6d-7329-5b6f-a82a-7c7e4d75a715","sourceKey":"bank:BUA202:HRP-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes the purpose of the selection interview?","options":["It replaces the need for any tests, reference checks or other selection steps","It is held after the new employee has worked in the firm for one year","It is used only to tell the chosen candidate what the salary will be","It lets the employer learn more about the candidate and the candidate learn about the job and organisation"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"The interview is a two-way exchange: the employer assesses the candidate, and the candidate learns about the role and organisation. Option A is wrong since interviews sit alongside tests and checks, option C is far too narrow, and option B describes an appraisal, not selection."}},{"itemId":"736cd9c4-3945-542a-a3b7-2a4ea2b2a91a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"73dc2acb-d7d3-5c12-9dda-5957b71f1d7d","sourceKey":"bank:BUA202:HRP-037","parentItemId":null,"revision":1,"payload":{"prompt":"On her first day at a Lagos firm, a new graduate finds no desk ready, nobody introduces her to colleagues, and she is handed a 200-page manual to read at once. This shows","options":["A structured selection interview held on the first day","A poorly handled orientation that can sour a new hire's first impression","A well-designed onboarding programme for graduate hires","Effective off-the-job training for new employees"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"No workspace, no introductions and information overload are classic signs of poor orientation, which can leave a bad first impression. Option C is the opposite, option D is training held away from daily work, and option A happens before hiring."}},{"itemId":"69ef7169-8d5f-5a64-b297-d8681007079a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"eb32697b-1bab-5c9f-81f5-673962145f0a","sourceKey":"bank:BUA202:HRP-038","parentItemId":null,"revision":1,"payload":{"prompt":"Informal, hands-on learning that takes place while the employee is doing the actual work is","options":["On-the-job training","Off-the-job training","Job analysis","Orientation"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"On-the-job training means learning while doing the real job, often with guidance from experienced staff. Option B takes place away from the work setting, option D is the introduction for new hires, and option C studies the job itself."}},{"itemId":"adea5d4b-ecdb-5c51-a433-09b8efd95b6e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d8826f07-a065-5059-9dfd-658570d5cdcc","sourceKey":"bank:BUA202:HRP-039","parentItemId":null,"revision":1,"payload":{"prompt":"Off-the-job training is best described as","options":["Structured programmes held away from daily work distractions, often for complex or specialised skills","Introducing a new hire to company policies on the first day","Moving an employee through different jobs within the firm","Learning by watching an experienced colleague at the workstation"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Off-the-job training takes employees away from their normal work so they can focus on structured learning, which suits complex skills. Option D is on-the-job coaching, option C is job rotation, and option B is orientation."}},{"itemId":"f862b8ae-e758-5434-88d4-f052efc6ec6b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"87e67a18-6f86-5fe6-a465-9796eaca4604","sourceKey":"bank:BUA202:HRP-040","parentItemId":null,"revision":1,"payload":{"prompt":"A new cashier at a bank branch in Enugu learns the job by working at the counter beside an experienced teller who guides her through each transaction. This is","options":["Off-the-job training","Vestibule training","On-the-job training","Orientation"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Learning at the actual counter, while doing real transactions under guidance, is on-the-job training. Option A would take her to a classroom or training centre, option B uses a simulated work area set apart from the real one, and option D is the general introduction to the organisation."}},{"itemId":"e8e554a0-0f30-535e-aeb6-716d74b446fc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fe88820a-7ab4-5e14-8d7a-513a38389c7b","sourceKey":"bank:BUA202:HRP-041","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing company sends its supervisors to a three-day leadership workshop at a training centre in Ibadan. This is an example of","options":["Off-the-job training","Employee referral","Job rotation","On-the-job training"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Training held away from the workplace in a structured programme is off-the-job training. Option D happens while doing the actual job, option C moves staff through different jobs, and option B is a recruitment method."}},{"itemId":"346c024d-d37e-5c48-a2d3-755c073915c5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0523ff93-a0a2-5003-8af1-5c1b4a0348b7","sourceKey":"bank:BUA202:HRP-042","parentItemId":null,"revision":1,"payload":{"prompt":"Moving an employee through a series of different jobs over a period so that they gain broad experience of the organisation is called","options":["Job rotation","Job enrichment","Job specification","Succession planning"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Job rotation shifts employees from one job to another to broaden their skills and understanding. Option B adds more responsibility and challenge to the same job, option C is a statement of qualifications, and option D grooms people for specific key posts."}},{"itemId":"0779c614-24e0-5bc2-bfa6-ad81936de956","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a221bc39-e3aa-58f6-8f0b-cf672b76c975","sourceKey":"bank:BUA202:HRP-043","parentItemId":null,"revision":1,"payload":{"prompt":"In Aba, a young person spends three years learning tailoring under a master tailor, combining practical work with instruction until he can practise independently. This training method is","options":["Vestibule training","Apprenticeship","Orientation","Job rotation"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Apprenticeship is a long period of learning a trade under an experienced master, combining instruction and practical work. Option A uses a simulated work area, option D moves staff across different jobs, and option C is a short introduction for new hires."}},{"itemId":"00ac8f9e-3f48-5c22-8e92-3c944e51302a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"01613d8a-7f38-5ac2-964e-9a08a8fabd9f","sourceKey":"bank:BUA202:HRP-044","parentItemId":null,"revision":1,"payload":{"prompt":"Vestibule training is training that","options":["Takes place only through online courses","Consists of reading the company's history and policies","Happens at the employee's actual workstation during normal work","Takes place in a separate area set up to simulate the real work environment and equipment"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Vestibule training uses a training area equipped like the real workplace, so trainees can practise without disrupting actual work. Option A is e-learning, option C is on-the-job training, and option B is part of orientation."}},{"itemId":"3b38ee23-39fe-54bc-82f6-aee7ba10ab8b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1ce4922c-7c1a-5999-b139-2e8069957f12","sourceKey":"bank:BUA202:HRP-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes training from development?","options":["Training is long-term, while development is short-term","Training is for managers only, while development is for junior staff only","Training improves skills for the current job, while development prepares employees for future roles and growth","Training and development mean exactly the same thing"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Training is usually short-term and focused on the present job, while development is longer-term and builds people for future responsibilities. Option B is not a real distinction, option A reverses the time focus, and option D ignores the difference."}},{"itemId":"811dcd44-feae-5e59-95c7-3ac50376b3ef","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"18140d6f-5ee6-5fe7-baaf-8bc923f5f822","sourceKey":"bank:BUA202:HRP-046","parentItemId":null,"revision":1,"payload":{"prompt":"The ongoing process by which an employee, with the organisation's support, plans and progresses through a sequence of jobs and growing responsibilities is","options":["Selection","Orientation","Career development","Job analysis"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Career development is the planned growth of an employee's career over time, supported by the organisation through training, mentoring and promotion opportunities. Option B is a one-off introduction for new staff, option D studies jobs, and option A chooses new hires."}},{"itemId":"1b951caf-18d7-5143-86d7-f92b0a21822a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"70588254-488e-570b-b9b3-401cb0f43824","sourceKey":"bank:BUA202:HRP-047","parentItemId":null,"revision":1,"payload":{"prompt":"Identifying and developing internal employees who can take over key positions when those positions become vacant is called","options":["Downsizing","Succession planning","Job enlargement","Recruitment"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Succession planning makes sure the organisation has prepared people ready to step into key roles when current holders leave or retire. Option D attracts applicants, often from outside, option A reduces staff numbers, and option C adds tasks to a job."}},{"itemId":"b80c99bd-619c-5829-a342-1f68e256f17b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b9eca0a2-d570-5469-b26a-990f3c79cb7c","sourceKey":"bank:BUA202:HRP-048","parentItemId":null,"revision":1,"payload":{"prompt":"The managing director of an Abuja firm will retire in two years. The board picks the deputy MD, gives her more responsibilities and sends her on executive programmes so that she can take over smoothly. This is","options":["Job rotation","Succession planning","External recruitment","Orientation"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Grooming a chosen insider to take over a key post when it becomes vacant is succession planning. Option C would look outside the firm, option A moves staff across many jobs for broad experience, and option D introduces new hires to the organisation."}},{"itemId":"ff85a55e-6640-587e-b279-8c85f7127c26","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4100aaf8-e100-50f8-a3d1-4573f90aceae","sourceKey":"bank:BUA202:HRP-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a purpose of human resource planning?","options":["Identifying shortages or surpluses of workers","Forecasting future staffing needs","Ensuring the right skills are available when needed","Setting the selling price of the firm's products"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Pricing products is a marketing and finance decision, not an HR planning purpose. Options B, A and C are exactly what HR planning does: forecasting needs, spotting gaps or surpluses, and making sure the right skills are available at the right time."}},{"itemId":"c59ed8bd-96ba-517d-a149-4aacb7d54bd5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f7010597-6d72-5a95-91d1-501e0196e455","sourceKey":"bank:BUA202:MOT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process through which managers initiate, direct and sustain employees' behaviour towards a desired direction is called","options":["Motivation","Orientation","Delegation","Controlling"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Motivation is what starts, steers and keeps up employees' effort towards the goals managers want. Option D monitors results and corrects deviations, option C passes authority to subordinates, and option B introduces new staff to the organisation."}},{"itemId":"817fc3a2-0bab-57e6-8a56-cc4b38ad113c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cf40ec93-9d1e-590d-8acd-2d67169b025e","sourceKey":"bank:BUA202:MOT-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly describes the basic motivation cycle?","options":["New behaviour -> unmet need -> outcome","Satisfaction -> new behaviour -> unmet need","Outcome -> unmet need -> new behaviour","Unmet need -> new behaviour -> outcome (satisfaction)"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Motivation starts with an unmet need, which triggers new behaviour aimed at an outcome that satisfies the need; if the outcome is unsatisfactory, the need stays unmet and the cycle continues. Options C, A and B put the steps in the wrong order, since behaviour is a response to a need, not its cause."}},{"itemId":"70cb313d-743e-541d-a68c-87035c6c5988","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"929fd80a-98d6-5984-9312-f23ca8c62e95","sourceKey":"bank:BUA202:MOT-003","parentItemId":null,"revision":1,"payload":{"prompt":"A worker who has just secured a comfortable, well-paid job no longer works harder simply to get more food and shelter. This illustrates the principle that","options":["Lower needs are always more important than higher needs","Money is the only true motivator","Hygiene factors create satisfaction","A satisfied need is no longer a motivator"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Once a need is satisfied it stops driving behaviour, so the person moves on to higher needs. Option A overstates the hierarchy, option C misstates Herzberg, since hygiene factors only prevent dissatisfaction, and option B is contradicted by the example itself."}},{"itemId":"0b58c1a2-490f-5dbb-8fbe-a2fb5271999c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2d907775-0311-5832-9934-633ad0712938","sourceKey":"bank:BUA202:MOT-004","parentItemId":null,"revision":1,"payload":{"prompt":"According to Abraham Maslow, the basis of motivation is","options":["The design of the organisation chart","Close supervision by managers","Human needs: to motivate a person, find and satisfy his need","Fear of punishment"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Maslow held that needs are the basis for motivation, so managers must identify what a person needs and help satisfy it. Options D and B reflect a controlling, Theory X style of management, and option A concerns structure, not motivation."}},{"itemId":"d46ccabd-4fea-522c-9717-e60897dd3ef3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9d1dacc9-f048-5f05-acbf-45fc4682ae57","sourceKey":"bank:BUA202:MOT-007","parentItemId":null,"revision":1,"payload":{"prompt":"An employee at a Lagos manufacturing firm values his job mainly for its job security and pension plan. Which level of Maslow's hierarchy is he trying to satisfy?","options":["Social needs","Safety needs","Physiological needs","Esteem needs"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Job security and a pension protect a person against future danger and loss, which is the safety level. Option C concerns basic survival such as food and shelter, option D concerns respect and recognition, and option A concerns friendship and belonging."}},{"itemId":"d763ce3c-b274-560f-b8eb-e89c72d163c5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9586373f-c0fc-59c0-92c5-ef653b935411","sourceKey":"bank:BUA202:MOT-008","parentItemId":null,"revision":1,"payload":{"prompt":"A new staff member at an Ibadan firm feels unhappy until she makes friends among her colleagues and is accepted into the team. Which need is she satisfying?","options":["Social (love and belonging) need","Safety need","Physiological need","Self-actualisation need"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The social need is the need to feel wanted, associate freely and belong to a group, which is what friendship at work satisfies. Option D is about reaching one's potential, option C about food and shelter, and option B about protection from danger."}},{"itemId":"cc0e6ac1-38c4-58eb-b9e6-1deeaea3cdab","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"93bff091-3976-5506-9c5a-82ddab52dad6","sourceKey":"bank:BUA202:MOT-009","parentItemId":null,"revision":1,"payload":{"prompt":"A bank officer is most motivated by public recognition of her work and being promoted to a respected title. Which level of Maslow's hierarchy does this reflect?","options":["Safety needs","Physiological needs","Social needs","Esteem needs"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Esteem needs are about respect, recognition and being appreciated, which promotion and public recognition provide. Option C is about belonging, option A about security, and option B about basic survival."}},{"itemId":"1c213af2-ac75-550b-85bd-50d8418e7b25","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7f0ab1bf-2da9-5415-a557-2b40a5ba689e","sourceKey":"bank:BUA202:MOT-010","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy, a worker who wants a salary mainly so that he can buy food and pay for shelter is trying to satisfy his","options":["Safety needs","Physiological needs","Esteem needs","Self-actualisation needs"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Food, water, clothing and shelter are physiological needs, the base of the pyramid, which must be met before other needs motivate. Option A covers protection and security, option C respect and recognition, and option D reaching one's full potential."}},{"itemId":"5db2dc26-fd9e-54ba-be56-907089ad5819","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d4f5b536-6dcc-5729-b870-cd7bc22134e5","sourceKey":"bank:BUA202:MOT-011","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy, the esteem need is best described as the need","options":["To be self-confident, to be seen and to be appreciated","For food, water, clothing and shelter","To be free from danger and physical harm","To belong to and be accepted by a social group"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Esteem needs centre on self-confidence, respect and being appreciated by others. Option C describes safety needs, option D social needs, and option B physiological needs."}},{"itemId":"957cdaa1-0d1c-53e9-94e4-f8845d32f4be","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"74afc2b8-2d15-5d02-bf47-646c15e1e1f7","sourceKey":"bank:BUA202:MOT-013","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's two-factor theory, motivators are factors that","options":["Relate to the physical working environment","Merely prevent workers from complaining","Create satisfaction and encourage employees to perform better","Are the same as pay and company policy"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Motivators such as achievement, recognition, responsibility and growth create satisfaction and drive performance. Option B describes hygiene factors, and options A and D list job context items, which are hygiene factors rather than motivators."}},{"itemId":"86637c21-29b8-5c23-906e-f5b98df2cc18","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"281bd5ce-ac81-523f-947b-2370f77d5d97","sourceKey":"bank:BUA202:MOT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a hygiene factor in Herzberg's two-factor theory?","options":["Company policy","Working conditions","Achievement","Salary"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Achievement is a motivator because it comes from the content of the job itself and creates satisfaction. Options D, A and B are hygiene factors, which only prevent dissatisfaction."}},{"itemId":"7e8c096d-5ada-5957-8041-e341ca5e2c16","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a4e11341-9440-5fce-8aa7-5a195509607f","sourceKey":"bank:BUA202:MOT-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a motivator in Herzberg's two-factor theory?","options":["Supervision","Personal growth","Recognition","Responsibility"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Supervision is part of the job context, so it is a hygiene factor that prevents dissatisfaction rather than creating motivation. Options C, D and B are motivators that come from the work itself."}},{"itemId":"8c7489bc-eade-54cc-b269-d479e91a5ac6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5f9d8f28-9e43-530b-afd2-65699d36cd93","sourceKey":"bank:BUA202:MOT-016","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's theory, the job context factors (pay, working conditions, supervision, interpersonal relationships) correspond to","options":["Self-actualisation needs","Motivators","Valence","Hygiene factors"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Job context factors surround the job rather than make up the work itself, and they are Herzberg's hygiene factors. Option B corresponds to job content such as achievement and responsibility, option A is a Maslow level, and option C is a term from Vroom's expectancy theory."}},{"itemId":"17e51139-1eee-589e-a519-15f22936cdd8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f1b9be8c-8f97-55e5-b1da-d828b18334ab","sourceKey":"bank:BUA202:MOT-017","parentItemId":null,"revision":1,"payload":{"prompt":"A Kaduna textile firm raises all salaries and improves canteen conditions. Complaints stop, but output does not rise. In Herzberg's terms, the firm has improved","options":["Expectancy","Self-actualisation needs","Hygiene factors","Motivators"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Pay and canteen conditions are hygiene factors: improving them removes dissatisfaction, which is why complaints stopped, but they do not motivate extra effort. Option D would include achievement, responsibility or recognition, option B is a Maslow concept, and option A belongs to Vroom's theory."}},{"itemId":"b419d2b1-6518-5efa-a917-bc2aa63ec7e4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2ac2fbd7-a579-5308-a26f-ed87d088c849","sourceKey":"bank:BUA202:MOT-018","parentItemId":null,"revision":1,"payload":{"prompt":"A manager gives a capable junior analyst responsibility for leading a challenging new project, and the analyst becomes noticeably more energetic and committed. In Herzberg's terms, the manager has used","options":["Theory X supervision","A hygiene factor","A motivator","A financial reward"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Responsibility and challenge are part of job content, Herzberg's motivators, which create satisfaction and drive effort. Option B would be something like pay or working conditions, option A relies on close control, and option D is wrong because no money was offered."}},{"itemId":"6134a85f-fefb-5bfa-a5c2-c40f7d40e915","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b5117860-30a7-58e6-a042-8b918a4c22fd","sourceKey":"bank:BUA202:MOT-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts Maslow's and Herzberg's theories?","options":["Herzberg's theory deals with expectancy, instrumentality and valence","Maslow uses two factors, while Herzberg uses five levels","Maslow arranges needs in five levels, while Herzberg groups factors into two sets: hygiene factors and motivators","Both theories say pay is the strongest motivator of all"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Maslow explains what people need through a five-level hierarchy, while Herzberg explains what satisfies or dissatisfies them through two groups of factors. Option B swaps the two theories, option D misstates both, and option A describes Vroom's expectancy theory."}},{"itemId":"026b5b2d-69af-5723-b523-188f6d03241c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"03b14286-4972-5528-9e00-078ae9e211b0","sourceKey":"bank:BUA202:MOT-020","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who holds McGregor's Theory X assumptions believes that employees","options":["Enjoy work and can motivate themselves","Are creative and seek responsibility","Work best when left completely free","Dislike work, avoid responsibility and need close supervision"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Theory X is McGregor's negative view of workers: they dislike work, avoid responsibility and must be closely supervised. Options A and B describe Theory Y, and option C describes a laissez-faire approach."}},{"itemId":"38b0e894-e974-5d14-a77a-4b66c7323cff","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"67153808-39a6-521b-a7e5-73ec558cecb6","sourceKey":"bank:BUA202:MOT-021","parentItemId":null,"revision":1,"payload":{"prompt":"Under McGregor's Theory Y, employees are assumed to","options":["Enjoy work, accept responsibility and can motivate themselves","Hate work and avoid responsibility whenever possible","Need constant threats of punishment before they will work","Care only about money and nothing else at work"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Theory Y is McGregor's positive view: people can enjoy work, take responsibility and direct themselves. Options B, C and D reflect the negative Theory X view."}},{"itemId":"a35c9895-20a8-563b-9892-14a9c4ea4e4a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0ff0eb42-7caa-5ea8-b642-a090495a4514","sourceKey":"bank:BUA202:MOT-022","parentItemId":null,"revision":1,"payload":{"prompt":"The leadership style that typically follows from Theory X assumptions is","options":["Participative","Laissez-faire","Democratic","Authoritarian (controlling)"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"If a manager believes workers dislike work and avoid responsibility, he will control and direct them closely, which is an authoritarian style. Options A and C follow from Theory Y, which trusts workers to take part in decisions, and option B gives workers almost complete freedom."}},{"itemId":"4324b12f-cde3-5cfb-8c93-44b47810981d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a5874d92-04af-5be4-b28e-2ba84a912a4c","sourceKey":"bank:BUA202:MOT-023","parentItemId":null,"revision":1,"payload":{"prompt":"The leadership style that typically follows from Theory Y assumptions is","options":["Coercive","Participative","Bureaucratic","Authoritarian"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"A Theory Y manager trusts workers to be responsible and creative, so he involves them in decisions, a participative style. Options D and A follow from Theory X's distrust of workers, and option C relies on rules rather than participation."}},{"itemId":"a915174f-a7ae-5641-b1b9-c970a8533fed","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"49647d2b-b1a2-5a53-9832-f5c501fa3d7f","sourceKey":"bank:BUA202:MOT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Theory X and Theory Y, two opposing sets of assumptions managers hold about workers, were put forward by","options":["Frederick Herzberg","Douglas McGregor","Victor Vroom","David McClelland"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Douglas McGregor proposed Theory X and Theory Y. Option C developed expectancy theory, option A the two-factor theory, and option D the theory of achievement, affiliation and power needs."}},{"itemId":"9f684ae9-0397-5987-a66e-efa25d243307","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f6e80af3-b715-5be2-abb6-d112b6d44690","sourceKey":"bank:BUA202:MOT-025","parentItemId":null,"revision":1,"payload":{"prompt":"A factory manager in Kano insists on clocking every worker in and out, checks on them every hour and says, 'If I turn my back, they will stop working.' His view of workers reflects","options":["McGregor's Theory Y","McClelland's need for affiliation","McGregor's Theory X","Herzberg's motivators"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Believing workers will shirk unless closely watched is the Theory X view. Option A assumes workers enjoy work and can direct themselves, option D refers to job content factors like achievement, and option B is a person's need for friendly relationships."}},{"itemId":"f9593d34-2ded-57d2-91a1-413b6a1767af","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bd815968-3278-5ac8-b7a6-76ffdb484927","sourceKey":"bank:BUA202:MOT-026","parentItemId":null,"revision":1,"payload":{"prompt":"In McClelland's theory of needs, the desire to excel, to master challenging but achievable tasks and to receive feedback on performance is the need for","options":["Security","Affiliation","Power","Achievement"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"The need for achievement drives people to excel, choose moderately challenging goals and seek feedback. Option B is the desire for friendly relationships, option C the desire to influence or control others, and option A is not one of McClelland's three needs."}},{"itemId":"cc950089-6ac8-5359-9645-aee4c39bb0ca","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be47c389-6fa3-5356-a5b2-84f2974351c7","sourceKey":"bank:BUA202:MOT-027","parentItemId":null,"revision":1,"payload":{"prompt":"In McClelland's theory of needs, the desire for friendly, close and cooperative relationships with others is the need for","options":["Affiliation","Achievement","Power","Self-actualisation"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The need for affiliation is the wish to be liked and accepted and to have warm relationships. Option B is about excelling at tasks, option C about influencing others, and option D is a Maslow level."}},{"itemId":"728de43d-d68d-56dd-9c23-38803d269123","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"434cde5e-b902-5d14-99fc-a46f2f59a44f","sourceKey":"bank:BUA202:MOT-028","parentItemId":null,"revision":1,"payload":{"prompt":"In McClelland's theory of needs, the desire to influence, direct or control the behaviour of others is the need for","options":["Power","Esteem","Achievement","Affiliation"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The need for power is the drive to have impact on, and control over, others. Option D is the wish for warm relationships, option C the drive to excel at tasks, and option B is a level in Maslow's hierarchy, not one of McClelland's needs."}},{"itemId":"a8970b98-ff68-5f72-8db2-b5b558f04d72","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"00088725-2336-5f06-997e-ce4dc21848fc","sourceKey":"bank:BUA202:MOT-029","parentItemId":null,"revision":1,"payload":{"prompt":"A sales officer in Abuja always asks for stretching but realistic targets and wants weekly feedback on how close she is to hitting them. In McClelland's terms, she shows a high need for","options":["Safety","Achievement","Affiliation","Power"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Seeking moderately difficult goals and regular feedback is the classic sign of a high need for achievement. Option C would show in a focus on friendships, option D in a desire to control others, and option A is not one of McClelland's needs."}},{"itemId":"f04a7234-efb0-56dc-b777-2fae1998cda9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a41583d1-5e01-5c74-8f65-51b4e3456994","sourceKey":"bank:BUA202:MOT-030","parentItemId":null,"revision":1,"payload":{"prompt":"In Vroom's expectancy theory, the perceived probability that effort will lead to good performance is called","options":["Valence","Instrumentality","Expectancy","Equity"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Expectancy is the effort-to-performance belief: 'If I try hard, I will perform well.' Option B is the belief that performance will lead to a reward, option A is how much the reward is valued, and option D belongs to Adams' equity theory."}},{"itemId":"086ad0f6-1252-590e-b1c7-a3b874cc43b6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cc8393a3-f716-5050-acdc-1105af6e106d","sourceKey":"bank:BUA202:MOT-031","parentItemId":null,"revision":1,"payload":{"prompt":"In Vroom's expectancy theory, the belief that good performance will actually lead to a reward such as a bonus or promotion is","options":["Hygiene","Valence","Instrumentality","Expectancy"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Instrumentality is the performance-to-reward link: 'If I perform well, I will be rewarded.' Option D is the effort-to-performance link, option B is how much the reward is valued, and option A is from Herzberg's theory."}},{"itemId":"42eeef2c-9a81-5324-8fbb-cc173a0525b9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f1e35361-1c64-50b9-8cc6-4d86c6c0a1bf","sourceKey":"bank:BUA202:MOT-032","parentItemId":null,"revision":1,"payload":{"prompt":"In Vroom's expectancy theory, how desirable or attractive a particular reward is to an individual is called","options":["Expectancy","Inputs","Valence","Instrumentality"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Valence is the value a person places on an outcome, which can be positive, neutral or negative. Option D is the belief that performance leads to the reward, option A the belief that effort leads to performance, and option B is a term from equity theory."}},{"itemId":"454ebc6d-b4aa-516d-88d5-f451b7d05cb1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c4bfe413-b20a-562e-9966-16bfb3133bde","sourceKey":"bank:BUA202:MOT-033","parentItemId":null,"revision":1,"payload":{"prompt":"Under Vroom's expectancy theory, in which motivation is the product of expectancy, instrumentality and valence, a worker who places no value at all on the bonus being offered will be","options":["Not motivated by the bonus, even if expectancy and instrumentality are high","Motivated to the same level as a worker who values the bonus","Motivated only if instrumentality is low","Highly motivated, because expectancy is high"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Because the three factors multiply, a zero valence makes the whole product zero, so a reward the worker does not value will not motivate him however achievable it is. Option D ignores valence, option C gets the effect of instrumentality backwards, and option B treats valence as irrelevant."}},{"itemId":"9637c9f0-cd1f-5d77-b106-981b1eda31e0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7372a867-6a73-5e56-9cae-9e032cb76eb6","sourceKey":"bank:BUA202:MOT-034","parentItemId":null,"revision":1,"payload":{"prompt":"A salesperson at a Lagos car dealership knows that selling more vehicles earns a bonus she values, so she works harder. Which motivation theory best explains her behaviour?","options":["McGregor's Theory X","Herzberg's two-factor theory","Maslow's hierarchy of needs","Expectancy theory"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Expectancy theory says people work hard when they believe effort leads to performance, performance leads to reward, and the reward is valuable, exactly as here. Option C focuses on levels of need, option A is a manager's negative assumption about workers, and option B sorts factors into hygiene and motivators."}},{"itemId":"2f1c67ae-21ad-521f-be11-d3313335171f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6c15ec2f-da25-582b-bd11-8258cbffaeb4","sourceKey":"bank:BUA202:MOT-035","parentItemId":null,"revision":1,"payload":{"prompt":"A worker says: 'However hard I try, I can never reach these production targets, so why bother?' In expectancy theory, his low motivation is caused by low","options":["Valence","Expectancy","Instrumentality","Hygiene"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"He doubts that his effort can produce the required performance, which is low expectancy, the effort-to-performance link. Option A would mean he does not value the reward, option C would mean he doubts performance will be rewarded, and option D is Herzberg's term."}},{"itemId":"496f8040-c35b-55c1-9c01-8dc47ddb6796","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e26abbd5-2924-50b4-a873-a781f4516f9e","sourceKey":"bank:BUA202:MOT-036","parentItemId":null,"revision":1,"payload":{"prompt":"Adams' equity theory states that employees are motivated by","options":["The belief that effort leads to performance and reward","Setting specific and challenging goals","Comparing the ratio of their outcomes to inputs with that of a referent other and seeking fairness","Satisfying needs in a fixed hierarchy from basic to higher"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Equity theory says people compare what they get relative to what they give with others; if the comparison seems unfair, they act to restore fairness. Option D is Maslow, option A is Vroom, and option B is Locke's goal-setting theory."}},{"itemId":"cd16f96b-30b8-58b7-abdb-88e125bb6549","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e3b5b2a9-0c8d-589a-8ab5-473b90032181","sourceKey":"bank:BUA202:MOT-037","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde finds out that a colleague with the same qualifications, experience and workload earns more than he does, and he reduces his effort. This is best explained by","options":["McClelland's theory, because he has a high need for power","Equity theory, because he perceives that he is under-rewarded","Maslow's theory, because he seeks self-actualisation","Herzberg's theory, because pay is a motivator"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Tunde has compared his outcome-to-input ratio with a colleague's, seen unfairness against himself, and cut his inputs to restore balance, which is the equity theory explanation. Option D is wrong because Herzberg treats pay as a hygiene factor, not a motivator, option A has nothing to do with comparing rewards, and option C is about realising potential rather than fairness."}},{"itemId":"409c291c-f4af-5912-b3e3-ff03624a6183","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f8ce208b-6297-581f-bc65-97bdc38210f6","sourceKey":"bank:BUA202:MOT-038","parentItemId":null,"revision":1,"payload":{"prompt":"In equity theory, an employee's 'inputs' are","options":["The number of hours the firm is open each week","The company's raw materials and machines","What the employee contributes, such as effort, skills, experience and time","The pay, bonuses and recognition the employee receives"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Inputs are contributions the employee brings to the job, such as effort, skill, experience and time. Option D describes outcomes, the other side of the ratio, and options B and A are not personal contributions at all."}},{"itemId":"f6d0bf3d-5b23-55c5-9f6e-22b910f1cfdc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"52caf359-f7b9-577d-812f-be4ba180d35f","sourceKey":"bank:BUA202:MOT-039","parentItemId":null,"revision":1,"payload":{"prompt":"Locke's goal-setting theory holds that performance is generally highest when employees","options":["Are given easy goals they are sure to reach","Work towards specific, challenging goals and receive feedback on progress","Are simply told to 'do their best'","Set no goals so that they feel free"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Goal-setting theory finds that specific, difficult but accepted goals, with feedback, lead to higher performance than vague or easy goals. Option C is the vague goal the theory argues against, option A produces less effort, and option D removes the direction goals provide."}},{"itemId":"4a7a50ca-54f4-5207-859a-942ef227bcee","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ca2cfaa9-5be7-5588-9c79-4b31082eabf9","sourceKey":"bank:BUA202:MOT-040","parentItemId":null,"revision":1,"payload":{"prompt":"Manager A tells her team, 'Increase loan recoveries by 15 percent by the end of June, and I will review progress with you every two weeks.' Manager B says, 'Just do your best.' Which theory predicts that Manager A's team will perform better?","options":["Herzberg's hygiene theory","Goal-setting theory","Theory X","Equity theory"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Goal-setting theory predicts that a specific, challenging goal with regular feedback beats a vague 'do your best' instruction. Option D is about fairness of rewards, option C is a negative assumption about workers, and option A covers job context factors such as pay and conditions."}},{"itemId":"18fdbc4f-22d8-59f9-bc67-1d7e4b4d124a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2bfe3856-0ca7-5c05-abac-6130cbe37788","sourceKey":"bank:BUA202:MOT-041","parentItemId":null,"revision":1,"payload":{"prompt":"Influencing people towards achieving goals is the meaning of","options":["Leadership","Controlling","Staffing","Budgeting"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Leadership is the ability to influence people so that they work towards goals. Option B is monitoring performance and correcting deviations, option C is filling positions, and option D is financial planning."}},{"itemId":"e130007a-ce51-5ddd-8f1b-1b906198e1b1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"099390fc-7660-5117-a116-de4f70cc34d7","sourceKey":"bank:BUA202:MOT-042","parentItemId":null,"revision":1,"payload":{"prompt":"The leadership style in which the leader makes all decisions alone, often seen in military settings, is","options":["Autocratic","Participative","Democratic","Laissez-faire"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"In autocratic leadership, the leader decides everything and expects subordinates to comply. Options C and B involve employees in decisions, and option D leaves employees to work freely with little direction."}},{"itemId":"6204de86-c8da-59c1-bf4c-01bab70e4a27","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f1649df0-5fd5-5041-bed9-b7493efbae0d","sourceKey":"bank:BUA202:MOT-043","parentItemId":null,"revision":1,"payload":{"prompt":"A leadership style in which employees participate in decision-making is called","options":["Laissez-faire leadership","Transactional supervision","Autocratic leadership","Democratic leadership"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Democratic leadership invites employees to contribute to decisions, though the leader usually has the final say. Option C keeps all decisions with the leader, option A leaves employees to decide almost entirely on their own, and option B is based on exchanging rewards for performance."}},{"itemId":"ec5c7b1b-00ef-5586-8278-171fad6fc094","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5f1bceab-eca3-5424-904f-16f5e926e382","sourceKey":"bank:BUA202:MOT-044","parentItemId":null,"revision":1,"payload":{"prompt":"The head of a research team of highly qualified scientists in Ile-Ife sets broad aims and then leaves the team members to decide how to do their work, intervening very little. This leadership style is","options":["Theory X","Democratic","Laissez-faire","Autocratic"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Laissez-faire leadership gives skilled staff freedom to work with minimal interference, and research teams are a typical example. Option D would mean the leader decides everything, option B would mean the leader actively involves the team in group decisions while still guiding them, and option A is a set of negative assumptions that would lead to close control."}},{"itemId":"f174c6bb-9394-5552-bbd6-095d19f28e5d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"95990772-5a90-5a97-a8e2-5c6069bdf3ee","sourceKey":"bank:BUA202:MOT-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common disadvantage of laissez-faire leadership?","options":["It is too slow because everyone must vote on every decision","It can lead to lack of direction and poor coordination when staff are inexperienced","It causes low morale because the leader decides everything alone","It requires the leader to supervise every task personally"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"With little guidance from the leader, laissez-faire works only with skilled, self-driven staff; otherwise it can cause drift and poor coordination. Option A is a drawback of democratic leadership, option C of autocratic leadership, and option D describes close supervision, the opposite of laissez-faire."}},{"itemId":"e206a6a6-c39b-56f6-82e6-b1f791e38c48","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0c744917-21fc-5194-beed-3baffac91ef4","sourceKey":"bank:BUA202:MOT-046","parentItemId":null,"revision":1,"payload":{"prompt":"Evaluating employees' performance, for purposes such as promotion, salary increases, training and feedback, is called","options":["Orientation","Performance appraisal","Recruitment","Job analysis"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Performance appraisal is the evaluation of how well employees have done their jobs, used for promotion, pay, training and feedback decisions. Option D studies the job itself, option A introduces new hires, and option C attracts applicants."}},{"itemId":"47a420c5-877f-5848-ab6a-ebdcbbb89a5f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"02ecefaa-0977-50a3-8d01-2814a45ab8dc","sourceKey":"bank:BUA202:MOT-048","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method in which employees in a group are placed in order from best to worst performer is","options":["Ranking","Management by objectives","Checklist","360-degree feedback"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The ranking method simply orders employees from best to worst. Option C uses a list of statements the rater ticks, option B measures results against jointly agreed objectives, and option D gathers feedback from many people around the employee."}},{"itemId":"c15ffc2f-344e-5d9f-ad49-09129f6e3cdd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0cc433e2-2205-5e4b-b63a-f3796bf56c62","sourceKey":"bank:BUA202:MOT-049","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method that collects feedback on an employee from supervisors, peers, subordinates and sometimes customers, as well as the employee's self-assessment, is","options":["Rating scale","360-degree feedback","Ranking","Checklist"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"360-degree feedback gathers views from all around the employee, not just the boss. Option C orders employees from best to worst, option A scores traits on a scale, and option D uses yes/no statements, usually completed by one rater."}},{"itemId":"85c3bca1-717a-5d8d-be5c-a3228af8949b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a78179b5-f796-53f0-ba90-96c4cd6d21d4","sourceKey":"bank:BUA202:MOT-050","parentItemId":null,"revision":1,"payload":{"prompt":"Management by objectives (MBO) as an appraisal method involves","options":["Ticking a list of yes/no statements about the employee's work","Collecting anonymous ratings of the employee from customers only","Ranking all employees in the unit in order from best to worst","The manager and employee jointly setting objectives and later evaluating performance against them"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"In MBO, manager and employee agree specific objectives together, and performance is judged by how far those objectives are met. Option C is ranking, option A is the checklist method, and option B is only one part of 360-degree feedback."}},{"itemId":"70f023b0-8eb7-57d8-b081-cd4b6d1737a0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"388a1228-d22b-5d38-8db2-1df04e6c8074","sourceKey":"bank:BUA202:MOT-051","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal error in which one strong positive impression of an employee influences the rater's judgement of all the employee's other traits is the","options":["Halo effect","Leniency error","Central tendency error","Recency effect"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The halo effect happens when one good trait, such as punctuality, makes the rater score everything else highly too. Option C is rating everyone as average, option D is letting recent events outweigh the whole period, and option B is rating everyone too generously."}},{"itemId":"5e7e7871-735a-5b27-b184-f81951405791","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d096ede2-c906-5905-b239-574e6d4556ea","sourceKey":"bank:BUA202:MOT-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes employee engagement from employee morale?","options":["Engagement is the mood of workers; morale is their commitment to the organisation","Engagement is emotional commitment to the organisation; morale is the confidence and enthusiasm employees feel towards work","Engagement and morale both mean the level of pay employees receive","Engagement applies only to managers; morale applies only to junior staff"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Engagement is about commitment to the organisation and its goals, while morale is about mood, the confidence and enthusiasm people feel at work; in short, engagement is commitment and morale is mood. Option A swaps the two, option C confuses both with pay, and option D invents a distinction that does not exist."}},{"itemId":"8884d238-217f-50cb-8b9c-0e3f75096290","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3c26d843-9bdd-5bc6-88fb-76b049e20670","sourceKey":"bank:BUA202:MOT-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a non-financial reward?","options":["Profit sharing","Commission on sales","Public recognition of good work","Annual bonus"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Recognition rewards employees without direct money payment, as do praise, promotion and flexible working hours. Options B, A and D are all financial rewards paid in money."}},{"itemId":"a012ccd7-ee54-579f-8b71-52b3887fa7ca","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"19f29f56-f5d6-5d08-a958-cf796301d8c2","sourceKey":"bank:BUA202:MOT-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit of a well-motivated workforce?","options":["Increased productivity","More innovation","Reduced absenteeism","Higher labour turnover"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Motivation reduces labour turnover because satisfied workers are more likely to stay, so higher turnover is not a benefit. Options A, C and B are all listed benefits of motivation."}},{"itemId":"0d035adb-2f20-53a1-a76c-33646ed5001c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9e8a8b57-63e9-5481-a961-73f574d0a464","sourceKey":"bank:BUA202:MOT-055","parentItemId":null,"revision":1,"payload":{"prompt":"In the Ohio State leadership studies, leader behaviour that involves scheduling work, deciding what is to be done and how, providing direction and maintaining performance standards is called","options":["Consideration","Laissez-faire leadership","Employee-centred behaviour","Initiating structure"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Initiating structure is the task-oriented dimension of leader behaviour identified in the Ohio State studies. Option A is the relationship-oriented dimension, being supportive and respecting members' ideas, option C is the Michigan studies' people-focused behaviour, and option B is a hands-off style that gives little direction."}},{"itemId":"4e71593e-1f3a-51da-8847-108dec46eabe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"36d44ed7-19c4-5585-b045-693be26ad25a","sourceKey":"bank:BUA202:OBC-001","parentItemId":null,"revision":1,"payload":{"prompt":"The field of study that examines how individuals, groups and organisational structures affect one another and behaviour within organisations is called","options":["industrial relations","human resource planning","organisational development","organisational behaviour"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Organisational behaviour studies how individuals, groups and organisational structures affect one another, so managers can understand and improve behaviour at work. Option B is forecasting staff needs. Option C is a planned change effort, which is one topic inside OB rather than the whole field."}},{"itemId":"7597069b-b063-5ed7-ba51-a34a7789f434","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"986cd10c-ddc7-5c5c-a279-5ef48669ec50","sourceKey":"bank:BUA202:OBC-002","parentItemId":null,"revision":1,"payload":{"prompt":"Describing organisational behaviour as having a 'scientific approach' means that it","options":["uses laboratory equipment to measure workers' physical strength","depends mainly on the personal opinions of managers","applies research and analysis to study human behaviour rather than relying on assumption","studies only machines and technology in the workplace"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"OB applies scientific methods, relying on research and analysis rather than assumption, to understand people at work. Option B is the opposite, because opinion without evidence is what the scientific approach avoids. Options A and D confuse OB with physical or engineering studies."}},{"itemId":"2ddd3fad-c1e2-5422-8070-00a739f815f1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c9578443-dc31-5611-8d03-54929f95d18c","sourceKey":"bank:BUA202:OBC-003","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational behaviour is inter-disciplinary. Which of the following is NOT one of the disciplines it draws from?","options":["Civil engineering","Anthropology","Psychology","Sociology"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"OB draws from psychology, sociology, anthropology, political science, economics and management, all of which study human behaviour or organisations. Civil engineering deals with structures such as roads and bridges, not human behaviour. Options C, D and B are core contributing disciplines."}},{"itemId":"ca23eca3-8bd9-55cb-9bb5-68af4a5a884b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9a4a6585-50d8-5566-94b8-7f129004056a","sourceKey":"bank:BUA202:OBC-004","parentItemId":null,"revision":1,"payload":{"prompt":"The statement that organisational behaviour is 'goal oriented' means that its ultimate objective is to","options":["replace managers with automated systems","improve organisational effectiveness and employee performance","increase the number of rules in the organisation","reduce the wages paid to employees"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Being goal oriented means OB aims to improve organisational effectiveness and employee performance. Option C confuses OB with bureaucracy. Options A and D are not aims of OB at all."}},{"itemId":"8f69deb4-b394-5028-a006-a7f2b55f8bad","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"862ccb1e-0a6d-521d-a50d-231118e76063","sourceKey":"bank:BUA202:OBC-005","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational behaviour is described as a 'dynamic field' because it","options":["deals with the movement of goods in a warehouse","has fixed principles that never change","studies only the behaviour of top managers","keeps evolving as organisations adapt to environmental and technological changes"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"OB is dynamic because it evolves continuously as organisations adapt to changes in their environment and technology. Option B is the opposite of dynamic. Option A confuses OB with logistics."}},{"itemId":"dce1bc14-3a5a-5e99-ae27-a3260b5251a1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b8210222-3016-590d-8339-56a014ee4999","sourceKey":"bank:BUA202:OBC-006","parentItemId":null,"revision":1,"payload":{"prompt":"In the scope of organisational behaviour, perception, personality and job satisfaction are studied at which level?","options":["Group level","Industry level","Individual level","Organisational level"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Perception, personality, learning, motivation, job satisfaction and emotion are individual-level topics because they concern each person. Option A covers topics like teamwork and group dynamics. Option D covers structure, culture and change."}},{"itemId":"912f33bd-566f-5e83-a667-622c0df074ff","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"946e4422-5e1c-5c11-9cfe-56ed56e4efc3","sourceKey":"bank:BUA202:OBC-007","parentItemId":null,"revision":1,"payload":{"prompt":"Teamwork, power and politics, and conflict management fall under which level of organisational behaviour?","options":["Organisational level","Group level","Individual level","National level"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"These topics arise when people interact in groups, so they belong to the group level along with group dynamics, communication and leadership. Option C covers traits of single persons such as personality. Option A covers organisation-wide matters such as structure and culture."}},{"itemId":"03f3ddac-95f5-5c93-9977-1a6511004797","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"857fb824-531d-5904-8c78-1b3208e2f805","sourceKey":"bank:BUA202:OBC-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the four elements of organisational behaviour?","options":["Forming, storming, norming and performing","Land, labour, capital and entrepreneurship","Planning, organising, leading and controlling","People, structure, technology and environment"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The four key elements of OB are people, structure, technology and environment, which together shape how work is done. Option C lists the functions of management. Option A lists stages of group development and option B lists factors of production."}},{"itemId":"ba7d323f-3f5e-5506-bb8e-3c9792a94e47","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a42d4eb9-1450-5f68-bed9-9d3209973a93","sourceKey":"bank:BUA202:OBC-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT usually listed as an importance of studying organisational behaviour?","options":["It facilitates organisational change","It improves employees' performance","It guarantees that the organisation will never face competition","It reduces workplace conflicts"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"OB helps improve performance, job satisfaction, leadership, communication, teamwork and change, and reduces conflict. No field of study can guarantee freedom from competition. Options B, D and A are all listed benefits."}},{"itemId":"2e8edadf-0408-58b4-b8ff-8defd680fcb6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"61994857-3b57-5f4e-9215-6de01892f577","sourceKey":"bank:BUA202:OBC-011","parentItemId":null,"revision":1,"payload":{"prompt":"In organisational behaviour, a group is best defined as","options":["a collection of individuals who interact, share common interests and goals, and work together to achieve an objective","a single employee working alone on a specialised task","any number of people who happen to be in the same place at the same time","all the customers who buy a company's product"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A group needs interaction, common goals and shared effort toward an objective. Option C describes a crowd, such as passengers at a bus stop, who do not interact toward a shared goal. Option B cannot be a group because a group needs two or more people."}},{"itemId":"d17f6f1f-27b9-528a-989b-71d8af1fda4d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3b15959d-b1cf-51b5-8e0d-c2c5a9b397e1","sourceKey":"bank:BUA202:OBC-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of a group?","options":["Two or more people","Members work in complete isolation from one another","Mutual influence among members","Shared norms and values"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Groups are marked by two or more people, common goals, interaction, mutual influence, shared norms and values, and interdependence. Working in complete isolation means no interaction, so it cannot describe a group. Options A, C and D are listed features."}},{"itemId":"e7b485ce-e58c-5f17-ab0a-e85e613849c3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fd15be0f-ffdb-503e-87cc-9d248cf9cda0","sourceKey":"bank:BUA202:OBC-013","parentItemId":null,"revision":1,"payload":{"prompt":"A branch manager at a Nigerian bank and the five officers who report directly to her form a","options":["task group","interest group","command group","friendship group"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A command group is a formal group made up of a manager and the subordinates who report directly to that manager. Option A is a formal group formed for a specific project. Options D and B are informal groups that grow out of social ties rather than the reporting structure."}},{"itemId":"3bb08a77-0e32-5cf0-8e4d-50f70f95d935","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"95d17ec0-b5fa-59ea-bea2-f5373e75611b","sourceKey":"bank:BUA202:OBC-014","parentItemId":null,"revision":1,"payload":{"prompt":"A company sets up a committee of staff from different departments to organise its 25th anniversary dinner, after which the committee will be dissolved. This committee is a","options":["task group","friendship group","interest group","command group"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A task group is a formal group formed to complete a specific project or assignment, such as a committee to organise a company event. Option D is a manager with direct subordinates. Options B and C are informal groups that form through social interaction, not management's design."}},{"itemId":"62d0862b-bc4a-5e81-a3e2-ade6fcc3c95b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"56a02e15-d7a7-5793-883d-ac6c501cdc5b","sourceKey":"bank:BUA202:OBC-015","parentItemId":null,"revision":1,"payload":{"prompt":"Several employees at an Ikeja factory who all support the same football club meet every Monday to discuss weekend matches. This is an example of","options":["a formal committee","a task group","an informal group","a command group"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Informal groups develop through social interaction among employees, such as interest and friendship groups, rather than being formed by management. Options D, B and A are all formal groups created by the organisation for work purposes."}},{"itemId":"20ac8965-b355-5fc7-a484-f5d9732a5222","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"326ce0f2-0b72-5b1a-a03e-03f40a3d1755","sourceKey":"bank:BUA202:OBC-016","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between formal and informal groups?","options":["Informal groups exist only outside working hours","Formal groups have no leaders, while informal groups always do","Formal groups always have more members than informal groups","Formal groups are created by the organisation for work purposes; informal groups emerge from social interaction among employees"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Formal groups, such as command and task groups, are deliberately set up by the organisation, while informal groups such as friendship and interest groups arise naturally. Option C is wrong because size does not define the type. Option A is wrong because informal groups operate inside the workplace too."}},{"itemId":"4a3fa295-8576-5f3a-aae5-3e1f946731f2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ef8180c4-5764-50ea-a965-cc8b2ea86adc","sourceKey":"bank:BUA202:OBC-018","parentItemId":null,"revision":1,"payload":{"prompt":"Members of a newly formed project team at a Lagos firm are polite but unsure of the team's purpose, structure and leadership. The team is in the","options":["storming stage","forming stage","norming stage","performing stage"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Forming is the first stage, marked by uncertainty about purpose, structure and leadership while members get to know one another. Option A comes next, when members begin to express opinions and clash. Option D comes when the team becomes fully functional."}},{"itemId":"2b21c4f6-b468-5931-bf33-7ff3d18cc1e7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9cc21189-f7c8-54a8-af9d-78f57012736a","sourceKey":"bank:BUA202:OBC-019","parentItemId":null,"revision":1,"payload":{"prompt":"Members of a group begin to express their opinions and ideas openly, and disagreements arise over who should lead and how work should be done. This describes the","options":["storming stage","adjourning stage","forming stage","norming stage"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"In the storming stage members express opinions and ideas, and conflict over roles and leadership is common. Option C is the polite, uncertain start. Option D follows storming, when trust and norms are established."}},{"itemId":"65ddf9f0-0b64-549e-80cb-440ebd37f77d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e8756f58-da76-5d0b-8574-a907cdec08fa","sourceKey":"bank:BUA202:OBC-020","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of group development in which members establish norms and strong relationships built on trust, cooperation and unity is the","options":["norming stage","performing stage","storming stage","adjourning stage"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Norming is when the group agrees its norms and builds trust, cooperation and unity. Option C is the conflict stage that comes before it. Option B comes after, when the group is fully functional and focused on the task."}},{"itemId":"a55a6fd1-0a1b-5630-9b0a-9bff902148de","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be1777c9-b28b-5208-b7b6-5e0f4f7c2c87","sourceKey":"bank:BUA202:OBC-021","parentItemId":null,"revision":1,"payload":{"prompt":"A task group set up to organise a company conference completes its work and is disbanded. It has reached the","options":["adjourning stage","forming stage","performing stage","norming stage"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Adjourning is the final stage, when a temporary group wraps up and disbands. Option C is when the group is functioning well on its task. Option B is the start of a group's life, not its end."}},{"itemId":"5106796f-c73f-5b1d-ade9-e470b20bd94e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"96a57afa-5d3f-5619-9ad9-dbcc86533559","sourceKey":"bank:BUA202:OBC-022","parentItemId":null,"revision":1,"payload":{"prompt":"The model of group development made up of forming, storming, norming and performing (with adjourning added later) is associated with","options":["Bruce Tuckman","Herbert Simon","Edgar Schein","Douglas McGregor"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Bruce Tuckman proposed forming, storming, norming and performing in 1965, and adjourning was added later with Mary Ann Jensen. Option B is known for bounded rationality. Option C is known for the three levels of organisational culture."}},{"itemId":"85a1dc57-ab32-553b-a282-b0bc571cf4c0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d5d38974-ee85-5b7f-8795-b6aae45b6220","sourceKey":"bank:BUA202:OBC-023","parentItemId":null,"revision":1,"payload":{"prompt":"A department of 25 people finds that meetings drag on, not everyone gets a chance to speak, and coordination is difficult. Which factor influencing group behaviour is most clearly at work?","options":["Communication channel choice","Coercion","Group size","Shared norms"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Group size affects behaviour: as groups grow, coordination becomes harder and members get fewer chances to contribute. Option B involves force or threats, which is not described. Option D concerns accepted standards of behaviour, which are not the issue here."}},{"itemId":"a5736ebd-bffd-5d4f-aa12-2821299c584e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ecf212fe-fb24-5ea4-8393-8abd2aa8f985","sourceKey":"bank:BUA202:OBC-024","parentItemId":null,"revision":1,"payload":{"prompt":"Acceptable standards of behaviour that are shared by members of a group are called","options":["norms","roles","status","goals"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Norms are the shared standards of acceptable behaviour in a group, such as how hard to work or how to dress. Option B refers to the set of behaviours expected of a person in a particular position. Option C refers to a socially defined rank or position."}},{"itemId":"1bee34ba-7226-5b92-80b6-4f9c72c6588f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f98f5997-aa57-53b4-b33a-e5ff8ceb980c","sourceKey":"bank:BUA202:OBC-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes a work team from a work group?","options":["A group always has more members than a team","A team's coordinated effort produces performance greater than the sum of individual inputs, while a group mainly shares information","A team has no leader, while a group always has one","A group has collective accountability, while a team has only individual accountability"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A work team creates positive synergy through coordinated effort and complementary skills, while a work group interacts mainly to share information and help each member perform in his own area. Option D reverses the accountability point: teams add mutual accountability. Option A is wrong because size does not distinguish them."}},{"itemId":"06728afc-1f24-504e-9674-21da3e64aab0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2ce9f26a-7e59-5174-975d-94c6e5a4deb1","sourceKey":"bank:BUA202:OBC-026","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency for individuals to put in less effort when working collectively than when working alone is called","options":["role conflict","groupthink","social loafing","synergy"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Social loafing happens when people in a group reduce effort because individual contributions are hard to identify. Option B is the suppression of dissent for the sake of agreement. Option D is the opposite effect, where combined effort exceeds the sum of individual inputs."}},{"itemId":"c6db93bc-eed8-5e48-8ec3-5735eef9a948","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d607b77e-43d8-5f2c-8565-9eda928f27e4","sourceKey":"bank:BUA202:OBC-027","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which group members are attracted to one another and motivated to stay in the group is called","options":["role ambiguity","group size","social loafing","group cohesiveness"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Cohesiveness is how strongly members are attracted to each other and want to remain part of the group. Option A is uncertainty about what one's role requires. Option C is reduced effort in a group."}},{"itemId":"54f72900-83f7-574a-8a45-d8fb1eab5d0a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fe4da63d-181b-57a8-9257-62ea8af52e28","sourceKey":"bank:BUA202:OBC-028","parentItemId":null,"revision":1,"payload":{"prompt":"In organisational behaviour, perception is best defined as the process by which individuals","options":["form groups to achieve common objectives","organise and interpret sensory impressions to give meaning to their environment","copy the behaviour of their supervisors","transmit messages to other members of the organisation"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Perception is how people organise and interpret what their senses pick up, which is why two people can see the same event differently. Option C is a form of learning by imitation. Option D describes communication."}},{"itemId":"90bade8c-c892-5674-9131-f055d82a4ffd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"51f91ee3-de92-5c16-bc56-eb94850ddc24","sourceKey":"bank:BUA202:OBC-029","parentItemId":null,"revision":1,"payload":{"prompt":"Factors that influence perception are usually grouped as factors in the perceiver, in the target and in the situation. Which of the following is NOT one of these three groups?","options":["Factors in the perceiver","Factors in the shareholders","Factors in the situation","Factors in the target"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Perception is shaped by the perceiver (attitudes, motives, experience), the target being perceived and the situation (time, setting). Shareholders are not one of these categories. Options A, D and C are the three standard groups."}},{"itemId":"72fc74e0-cca8-5a5b-8857-ced11501cd6c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"393aecad-0a8d-5406-8831-48ce6eda73a5","sourceKey":"bank:BUA202:OBC-030","parentItemId":null,"revision":1,"payload":{"prompt":"A manager rates a new staff member highly on every aspect of performance simply because she is very articulate in meetings. This perceptual error is called","options":["self-serving bias","stereotyping","the contrast effect","the halo effect"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The halo effect occurs when one positive characteristic shapes a general impression of a person. Option B is judging someone by the group he belongs to. Option C is judging someone by comparison with others encountered just before."}},{"itemId":"3b144008-bfce-5a62-af04-ec527307df4f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ebdef366-53f9-5520-874b-7cce173baa53","sourceKey":"bank:BUA202:OBC-031","parentItemId":null,"revision":1,"payload":{"prompt":"A recruiter assumes that a job applicant from a particular ethnic group must be good at trading, without assessing her individually. This is","options":["the contrast effect","the halo effect","stereotyping","selective perception"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Stereotyping is judging a person on the basis of one's perception of the group to which that person belongs. Option B is letting one trait of the individual colour the whole impression. Option D is noticing only information consistent with one's interests."}},{"itemId":"d6f9dc63-660e-58e4-b5c2-aec0a96b906a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0daf00a0-fe42-5f0b-8174-e0ded52efbc1","sourceKey":"bank:BUA202:OBC-032","parentItemId":null,"revision":1,"payload":{"prompt":"When his team meets its target, a supervisor says it was due to his excellent leadership; when the team misses its target, he blames poor market conditions. This shows","options":["anchoring bias","the halo effect","the fundamental attribution error","self-serving bias"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Self-serving bias is attributing one's own successes to internal factors and failures to external factors. Option C is about judging OTHER people, overestimating internal causes of their behaviour. Option A is a decision bias about over-relying on first information."}},{"itemId":"fb20f704-bb33-526f-b138-e4e7c80898b9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"66228ee4-cbb9-57d0-a9ed-32c34cc0b8b6","sourceKey":"bank:BUA202:OBC-033","parentItemId":null,"revision":1,"payload":{"prompt":"When judging the behaviour of others, the tendency to underestimate external factors and overestimate internal or personal factors is called","options":["selective perception","the fundamental attribution error","self-serving bias","projection"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The fundamental attribution error is blaming others' behaviour on their personality while overlooking the situation, for example assuming a late colleague is lazy when traffic was the cause. Option C concerns how people explain their OWN successes and failures. Option A is noticing selectively based on one's interests."}},{"itemId":"742bd0a1-2617-58a2-9abb-075c365a152d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ee620fe4-dc37-5154-9307-f94ddc024ee1","sourceKey":"bank:BUA202:OBC-035","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, if a staff member has submitted every report late for the past year, his behaviour shows high","options":["distinctiveness","cohesiveness","consensus","consistency"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Consistency asks whether the person responds the same way over time; late reports every month for a year is highly consistent, which points to an internal cause. Option A would mean he behaves differently across situations. Option C would mean most colleagues also submit late."}},{"itemId":"3c9c817a-7ef2-57d7-aaa6-fe6875c02549","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7283a063-450f-5a77-ac4e-1a640ae7c2de","sourceKey":"bank:BUA202:OBC-036","parentItemId":null,"revision":1,"payload":{"prompt":"Evaluative statements, favourable or unfavourable, about objects, people or events are called","options":["values","perceptions","norms","attitudes"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Attitudes are evaluative statements that reflect how a person feels about something, such as 'I like my job'. Option B is the process of interpreting sensory impressions. Option C refers to shared group standards of behaviour."}},{"itemId":"8f7bf9a4-47e8-59b6-967b-a9ddac309968","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d538cd86-db89-5049-b3e4-64c2b6d4bbff","sourceKey":"bank:BUA202:OBC-037","parentItemId":null,"revision":1,"payload":{"prompt":"The statement 'I am angry that my salary is lower than my colleague's' reflects which component of an attitude?","options":["Behavioural component","Affective component","Perceptual component","Cognitive component"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The affective component is the emotional or feeling part of an attitude, here anger. Option D would be the belief itself, such as 'my salary is lower than his'. Option A would be the intention to act, such as 'I will look for another job'."}},{"itemId":"ccdf4aa9-a0cc-5e42-92cf-91dd746b5809","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4debfee0-1a8c-59d7-9ed5-2a4e231c6d80","sourceKey":"bank:BUA202:OBC-038","parentItemId":null,"revision":1,"payload":{"prompt":"The statement 'I intend to resign and look for another job' reflects which component of an attitude?","options":["Behavioural component","Cognitive component","Normative component","Affective component"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The behavioural component is the intention to behave in a certain way toward someone or something. Option B is a belief or opinion and option D is the feeling attached to it."}},{"itemId":"b3dca415-4541-51c1-b230-e7a2ae203f92","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c41be457-8985-53f3-9a30-b67be1e1d736","sourceKey":"bank:BUA202:OBC-039","parentItemId":null,"revision":1,"payload":{"prompt":"The discomfort a person feels when there is incompatibility between two or more attitudes, or between behaviour and attitudes, is known as","options":["cognitive dissonance","the halo effect","social loafing","role ambiguity"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Cognitive dissonance is the tension felt when attitudes and behaviour do not match, for example a manager who values honesty being told to hide a product defect. People usually try to reduce it by changing an attitude or behaviour. Option D is unclear role expectations and option C is reduced effort in groups."}},{"itemId":"e3d28f6c-348f-50f1-91bc-bd96cff6aa80","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"01a8cc02-7f39-563a-85e8-2f2634a8846d","sourceKey":"bank:BUA202:OBC-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the 'Big Five' personality dimensions?","options":["Intelligence","Punctuality","Conscientiousness","Seniority"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The Big Five dimensions are extraversion, agreeableness, conscientiousness, emotional stability and openness to experience. Option A is a mental ability, not a personality dimension. Options B and D are a single behaviour and a job position respectively."}},{"itemId":"4c985b52-ee7c-54c3-b3d1-50b0c9715780","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1d62a995-faea-5d76-a77d-7662696078e6","sourceKey":"bank:BUA202:OBC-041","parentItemId":null,"revision":1,"payload":{"prompt":"In which small-group communication network does all information pass through one central person, so that a leader emerges clearly?","options":["Wheel","Chain","Circle","All-channel"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"In the wheel network a central figure acts as the conduit for all group communication, so the network is centralised, fast and leader-focused. Option D lets every member communicate with every other member. Option C links each member only to the two people beside him."}},{"itemId":"4cff7a33-53a2-5080-a098-677119114745","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"44cbaac1-6a8a-581f-ae98-c3e166a40472","sourceKey":"bank:BUA202:OBC-042","parentItemId":null,"revision":1,"payload":{"prompt":"A communication network in which every member of a team can communicate directly with every other member is called the","options":["all-channel network","wheel network","chain network","Y network"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"In the all-channel network everyone communicates freely with everyone else, which is typical of self-managed teams. Option B routes everything through one central person. Option C follows the formal chain of command step by step."}},{"itemId":"d7b027b8-9607-58b9-abd3-e96859ddff4e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"540606f1-d640-53b2-8f9a-f504b27d51a4","sourceKey":"bank:BUA202:OBC-043","parentItemId":null,"revision":1,"payload":{"prompt":"A message that passes from the managing director to the general manager, then to a department head and then to a supervisor, following the formal line of authority, is moving through which network?","options":["Wheel","Chain","Circle","All-channel"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The chain network rigidly follows the formal chain of command, passing information level by level. Option A would have one central person speaking directly with every member. Option D would let every member talk to every other member."}},{"itemId":"e4511e90-9f19-5a7d-aae4-e46398fcbe9b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c65140c2-4a5d-5956-9abb-1a819187a531","sourceKey":"bank:BUA202:OBC-044","parentItemId":null,"revision":1,"payload":{"prompt":"Of the chain, wheel and all-channel communication networks, which is generally associated with the HIGHEST member satisfaction?","options":["Wheel","All three give the same level of satisfaction","Chain","All-channel"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"The all-channel network gives every member an equal chance to participate, so it is associated with high member satisfaction. Option A centralises communication in one person, which lowers satisfaction for everyone else. Option C restricts members to passing messages along a fixed line."}},{"itemId":"48cf8b1b-1814-5594-b5a3-b516557d5a59","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d064a9bb-f3d8-5296-aac4-79eb056cd137","sourceKey":"bank:BUA202:OBC-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a barrier to effective communication in organisations?","options":["Active listening","Feedback","Information overload","Choosing the right channel"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Information overload occurs when the information people receive exceeds their capacity to process it, so messages are ignored or forgotten. Options B, A and D are ways to improve communication, not barriers to it."}},{"itemId":"eaa210f8-9de1-5a84-a399-3da4332e623c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ac3f66bb-18c1-5585-ae33-900f1f74466b","sourceKey":"bank:BUA202:OBC-046","parentItemId":null,"revision":1,"payload":{"prompt":"A sales officer reports only the good news to his regional manager and leaves out falling sales figures so that he looks good. This barrier to communication is called","options":["noise","decoding","filtering","information overload"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Filtering is a sender's deliberate manipulation of information so the receiver sees it more favourably. Option D is receiving more information than one can process. Option B is the normal step where the receiver interprets a message."}},{"itemId":"dd173dd1-16bd-5cdc-b4d4-6779d0bdf81d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b1e5b861-563e-5113-a97b-761b18d942a4","sourceKey":"bank:BUA202:OBC-047","parentItemId":null,"revision":1,"payload":{"prompt":"In conflict management, a style that is high in both assertiveness and cooperativeness, where parties work together to find a solution that fully satisfies everyone, is called","options":["avoiding","collaborating","compromising","accommodating"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Collaborating seeks a win-win outcome that fully meets both parties' concerns, so it is high on both assertiveness and cooperativeness. Option C is a middle position where each side gives up something. Option D puts the other party's concerns above one's own."}},{"itemId":"adbd8174-8328-59fb-82b1-c33c6b0fd1c0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9ef1dda4-06b2-5bd4-baa9-c4a2281cdda5","sourceKey":"bank:BUA202:OBC-048","parentItemId":null,"revision":1,"payload":{"prompt":"Two managers at a Lagos firm each want the whole of a N10 million training budget. They agree that each will get N5 million, so each gives up part of what he wanted. This conflict-handling style is","options":["competing","compromising","collaborating","avoiding"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Compromising means each party gives up something to reach a middle position, as with splitting the budget. Option C would look for a solution that satisfies both fully, for example finding extra funds. Option A means one side pushes to win at the other's expense."}},{"itemId":"574d1056-02bc-5431-871e-4e4276fc7b18","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"99cb4dd5-23df-557d-aa94-90fdb484a0c1","sourceKey":"bank:BUA202:OBC-049","parentItemId":null,"revision":1,"payload":{"prompt":"Conflict that supports the goals of a group and improves its performance is called","options":["relationship conflict","dysfunctional conflict","role ambiguity","functional conflict"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Functional conflict is constructive: it supports group goals, for example a debate that exposes a weak plan. Option B hinders group performance. Option A focuses on personal relationships and is usually harmful."}},{"itemId":"57acc482-1e63-50c4-92b2-54c264ce4268","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f7ebf818-16a4-5a7f-a2a5-07bed477f16e","sourceKey":"bank:BUA202:OBC-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is listed as an importance of groups in an organisation?","options":["They guarantee that conflict never occurs","They enhance problem solving and improve decision making","They remove the need for managers","They allow individuals to avoid all responsibility"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Groups facilitate communication, promote cooperation, improve decision making, enhance problem solving and increase motivation. Option C is wrong because groups still need leadership. Options A and D are false; groups can create conflict and do not remove responsibility."}},{"itemId":"6cd4b8cd-5818-599c-9256-f2d529c3313f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a76de78b-bd54-5802-8296-2f02cf4e4d65","sourceKey":"bank:BUA202:PQ-001-a","parentItemId":null,"revision":1,"payload":{"prompt":"Edwin B. Flippo's classic definition of HRM lists six operative functions. Which of the following is NOT one of them?","options":["Procurement","Advertising","Separation","Integration"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The six operative functions in this definition are procurement, development, compensation, integration, maintenance and separation of human resources. Advertising is a marketing activity, not an HR operative function. Options A, C and D are all part of the six-function list, from bringing people in (procurement) to their exit (separation)."}},{"itemId":"9d61bc48-9d0e-5d42-a12e-40147a541104","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9f742c60-5b39-5705-8586-c6c287341c03","sourceKey":"bank:BUA202:PQ-001-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which definition presents HRM as 'a strategic approach to the management of an organization's most valued assets, the people working there'?","options":["Edwin B. Flippo's definition","Michael Armstrong's definition","R. Wayne Mondy's definition","Wendell L. French's definition"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"This wording frames people as the organisation's most valued assets and treats HRM as strategic, which is the hallmark of Michael Armstrong's definition. Option C is the very short definition that HRM is the utilisation of individuals to achieve organisational objectives. Options A and D are earlier, more administrative definitions built around activities such as recruitment, procurement and compensation."}},{"itemId":"0772bbf3-40b6-5057-9586-6a08b98b12b2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8b14cbeb-616c-564c-ba6d-b6c1a026c959","sourceKey":"bank:BUA202:PQ-001-c","parentItemId":null,"revision":1,"payload":{"prompt":"Taken as a whole, how did definitions of HRM change between the 1960s and the 2000s?","options":["They moved from a strategic view of people to a purely payroll and record-keeping view","They remained essentially unchanged, describing HRM only as hiring and firing","They moved from an administrative, procedural view of managing staff to a strategic view linking people to competitive advantage","They stopped treating people as a resource and focused only on machines and capital"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Early definitions described HRM through operational activities such as procurement, compensation and separation, while later ones described it as strategic, aimed at sustainable competitive advantage and organisational goals. Option A reverses the direction of the change. Options B and D are wrong because later definitions place even more weight on people, not less, and clearly go beyond hiring and firing."}},{"itemId":"efc6db77-519e-5ebb-b468-df64d183b072","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"551e1140-5ba3-568d-9599-8290a4083145","sourceKey":"bank:BUA202:PQ-001-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which definition of HRM is most closely associated with establishing the distinction between 'hard' and 'soft' HRM?","options":["Mathis and Jackson's definition of HRM as the design of formal systems to manage human talent","Wendell L. French's definition of HRM as the recruitment, selection, development, utilisation of, and accommodation to, human resources","R. Wayne Mondy's definition of HRM as the utilisation of individuals to achieve organisational objectives","John Storey's definition of HRM as a distinctive approach to employment management seeking competitive advantage through a highly committed workforce"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"John Storey's work is widely credited with the hard versus soft HRM distinction: hard HRM treats people mainly as a cost to be controlled, while soft HRM treats them as valued assets to be developed and committed. Options A, B and C are real definitions of HRM, but they are not the ones known for drawing this hard/soft line."}},{"itemId":"92c9a47a-0367-50d8-b91c-68e85dd5eab8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3593ff10-4ea5-5218-ad26-4cc9aac4d301","sourceKey":"bank:BUA202:PQ-002-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the three core elements (basic components) of any organisation?","options":["Planning, Organising and Controlling","Mission, Vision and Profit","Capital, Land and Machinery","Purpose, Structure and People"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Every organisation rests on a purpose (why it exists), a structure (how roles and tasks are arranged) and people (who carry out the work). Option A lists functions of management, not elements of an organisation. Option C lists factors of production, and option B mixes parts of purpose with an outcome."}},{"itemId":"f584935b-f496-5303-adfa-a9051bc919fa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fa0180c1-83ab-558e-8f95-4ea2ef11fe9d","sourceKey":"bank:BUA202:PQ-002-b","parentItemId":null,"revision":1,"payload":{"prompt":"Among the three core elements of an organisation, which one is described as the driving force without which neither the purpose nor the structure can be achieved?","options":["Purpose","Technology","Structure","People"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"People are the driving force: plans, organograms and policies achieve nothing unless people carry them out. Option C, structure, only arranges roles and responsibilities, and option A, purpose, is the reason the organisation exists. Option B is not one of the three core elements at all."}},{"itemId":"6a1baa7e-13e6-5122-9b0c-f9969be725bc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a1f8a2c6-375d-504c-9e05-b0d50d3fe3eb","sourceKey":"bank:BUA202:PQ-002-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which function of management involves monitoring performance and taking corrective action to make sure organisational goals are met?","options":["Planning","Organising","Leading","Controlling"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Controlling closes the management cycle by comparing actual performance with goals and correcting any deviations. Option A, planning, sets the goals and the course of action in the first place. Option B, organising, arranges resources and activities, and option C, leading, is about directing, motivating and influencing people."}},{"itemId":"212f469b-bda1-5564-9be4-6f39ccaf1eb7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c5a8f2df-dae0-525b-ad22-dca69d983344","sourceKey":"bank:BUA202:PQ-003-a","parentItemId":null,"revision":1,"payload":{"prompt":"What was the main criticism of the Classical School of management (scientific management, administrative theory and bureaucracy) in how it treated workers?","options":["It treated workers as passive labour inputs, much like machines or other factors of production","It ignored efficiency and productivity altogether","It gave workers too much freedom to make strategic decisions","It focused mainly on workers' social and emotional needs"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The Classical School viewed people as inanimate labour inputs to be managed like machinery, with little regard for their psychological or social needs. Option D describes the Human Relations view, which came later as a reaction to this flaw. Options B and C are wrong because classical thinkers kept decision-making at the top and were obsessed with efficiency."}},{"itemId":"42784e5d-bd38-5045-ad85-dd2d4d8daf32","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0e7d9387-931d-54e4-8f3f-a4b5567dd563","sourceKey":"bank:BUA202:PQ-003-b","parentItemId":null,"revision":1,"payload":{"prompt":"The Hawthorne experiments, which showed that workers' social and emotional needs strongly affect their performance, are associated with which school of thought?","options":["General Administrative Theory","Scientific Management","The Human Relations Movement","Bureaucratic Theory"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The Hawthorne studies, led by Elton Mayo, launched the Human Relations Movement by showing that attention, group relationships and morale affect output. Options A, B and D are all branches of the earlier Classical School, which treated workers mainly as inputs to be organised efficiently."}},{"itemId":"ba44f78f-41ae-5293-b679-a1761c26ceda","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5ad5a2ed-2557-5f6d-9894-418e34deea88","sourceKey":"bank:BUA202:PQ-004-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the four-category classification of HRM objectives (societal, organisational, functional and personal), legal compliance, ethical employment practices and corporate social responsibility fall under which objective?","options":["Personal objective","Societal objective","Functional objective","Organisational objective"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The societal objective concerns HRM's responsibility to the wider society, so obeying the law, ethical employment and CSR belong here. Option A is about the individual employee, such as career growth and work-life balance. Options C and D concern the quality of the HR function itself and HR's contribution to the business."}},{"itemId":"7fbf329f-b86a-501c-b384-8792fe86f6e2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ed1a7d0c-2e75-5d01-9663-e425a18d8e3e","sourceKey":"bank:BUA202:PQ-004-b","parentItemId":null,"revision":1,"payload":{"prompt":"Under the same four-category framework, career development, work-life balance and employee wellbeing are examples of which HRM objective?","options":["Functional objective","Organisational objective","Personal objective","Societal objective"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Personal objectives focus on the individual employee's own needs and experience, such as growth, satisfaction, wellbeing and dignity. Option D looks outward to society through legal and ethical duties. Option B covers business needs like productivity and cost management, and option A covers how well the HR department itself runs."}},{"itemId":"140cf753-bce1-5ccb-8333-6eaeca9fa9aa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"84e392aa-f1b5-5780-b1db-4d23b4ef53b3","sourceKey":"bank:BUA202:PQ-004-c","parentItemId":null,"revision":1,"payload":{"prompt":"Within the four-category framework of HRM objectives, which objective is concerned with HR metrics and analysis, HR systems quality and HR business partnering?","options":["Organisational objective","Functional objective","Societal objective","Personal objective"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"The functional objective is about the quality of the HR department's own operations, so its systems, metrics and partnering with business units sit here. Option A is close, but it refers to HR's contribution to the organisation as a whole, such as workforce planning, productivity and cost management. Options C and D concern employees as individuals and society at large."}},{"itemId":"565914ab-57b1-517b-be90-2c2cbd930f5d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"17ca6029-6f50-5360-bd0a-10df2e3df28d","sourceKey":"bank:BUA202:PQ-005-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which functional area of HRM is responsible for structuring pay, rewards and incentives?","options":["Compensation management","Performance management","Workforce planning","Employee relations"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Compensation management designs salary structures, bonuses and other rewards. Option C sizes and plans the workforce to support strategy, and option B monitors and evaluates how well employees perform. Option D handles grievances and the general work climate rather than pay design."}},{"itemId":"a56da2c7-4b5c-51c5-a5c3-bfe9aa297438","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fc1a25f7-2250-5e89-999b-fbc2dfcd98b8","sourceKey":"bank:BUA202:PQ-005-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which characteristic of modern HRM refers to HR working directly with executive leadership so that human capital supports the organisation's overall strategy?","options":["Employee relations","Goal alignment","Strategic integration","Competitive advantage"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Strategic integration means HR sits with top leadership and builds people plans into the organisation's big-picture strategy. Option B, goal alignment, is related but refers to lining up individual workers' behaviour and outputs with corporate goals. Option D is the result of good HRM rather than the working relationship itself, and option A is a functional area, not a distinguishing characteristic."}},{"itemId":"832a2a4c-e229-5d34-bb44-1d030744db8e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6f71a691-f2dc-53cf-be55-7755a793ada4","sourceKey":"bank:BUA202:PQ-006-a","parentItemId":null,"revision":1,"payload":{"prompt":"An MD says: 'We don't need an HRM department; a Personnel Officer who handles hiring and payroll is enough.' Which response best reflects the modern, strategic view of HRM?","options":["HRM should replace line managers completely, so all supervision becomes HR's job","The MD is right, because HRM is simply another name for payroll administration","Hiring and payroll are necessary but not sufficient; HRM must also plan the workforce, manage performance and align people with business strategy","The MD is right, because people are factors of production to be managed like machines"],"correctOption":2,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Strategic definitions treat HRM as aligning people with organisational strategy to achieve competitive advantage, which goes well beyond transactional hiring and payroll. Option B reduces HRM to administration, which is exactly the older personnel view being challenged. Option D repeats the classical flaw of treating workers as inputs, and option A overstates HR's role, since line managers still manage their own teams."}},{"itemId":"2e05b4af-2438-5377-9138-b2f5c655f9c0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c763d2e3-cf1f-549c-bc75-0ef7ab6763c3","sourceKey":"bank:BUA202:PQ-006-b","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturing firm's Personnel Officer handles only hiring and payroll. Which strategic HRM activity is most clearly missing from this arrangement?","options":["Keeping employee files up to date","Placing job advertisements","Processing monthly salaries","Workforce planning that aligns people with the firm's business strategy"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Strategic HRM plans the size and skills of the workforce to support where the business is going, and links people management to corporate goals. Options A, B and C are routine administrative tasks that a Personnel Officer already handles, so they are not what is missing."}},{"itemId":"345c7dd6-af89-5504-9f6b-b47d45414758","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8e516072-d64f-52bc-9e17-4148102fb173","sourceKey":"bank:BUA202:PQ-007-a","parentItemId":null,"revision":1,"payload":{"prompt":"A company's HR objectives focus only on cutting recruitment costs and processing payroll on time. Using the societal, organisational, functional and personal classification of HRM objectives, which two categories are being neglected entirely?","options":["Functional and personal objectives","Societal and personal objectives","Organisational and societal objectives","Organisational and functional objectives"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Cutting recruitment costs serves the organisational objective of cost management, and on-time payroll reflects functional HR systems quality, so those two are covered. Nothing addresses legal and ethical duties to society or employees' career growth, satisfaction and wellbeing, which are the societal and personal objectives. Options A, C and D each name at least one category the company is already serving."}},{"itemId":"2859324e-0041-57ef-bf42-2f5e5f658d24","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ad8b4810-e7b2-5737-b402-4bda6ab3fb68","sourceKey":"bank:BUA202:PQ-007-b","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's HR department meets its cost and payroll targets but ignores career development, job satisfaction and employee wellbeing. Which outcome is the most likely risk?","options":["Higher staff turnover and lower employee engagement","Elimination of all legal compliance risks","Automatic improvement in employee morale","Lower recruitment costs and faster payroll processing"],"correctOption":0,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Neglecting the personal objective leaves employees feeling undeveloped and unvalued, which typically shows up as disengagement and people leaving. Option D describes what the firm is already achieving, not a risk. Option C is the opposite of what neglect produces, and option B is wrong because ignoring wider obligations can increase, not remove, compliance exposure."}},{"itemId":"f0478aa7-458d-5894-8e9b-1c8eabed9ce9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"10690a2e-1d56-5674-87a9-6149127ff5b2","sourceKey":"bank:BUA202:PQ-008-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which option arranges Maslow's hierarchy of needs correctly from the lowest level to the highest?","options":["Safety, Physiological, Social (love), Esteem, Self-actualisation","Physiological, Social (love), Safety, Self-actualisation, Esteem","Self-actualisation, Esteem, Social (love), Safety, Physiological","Physiological, Safety, Social (love), Esteem, Self-actualisation"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Maslow's pyramid starts with basic physiological needs such as food and shelter, then safety, social belonging, esteem, and finally self-actualisation at the top. Option A swaps the first two levels, and option B misplaces safety and esteem. Option C gives the right levels but from highest to lowest, not lowest to highest."}},{"itemId":"e42aa0d0-9a25-576b-8b82-491e2ac47084","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9d44e750-25f7-5089-86db-806d16775286","sourceKey":"bank:BUA202:PQ-008-b","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow, a factory manager who ensures that machines are guarded and the work environment is free from danger is mainly satisfying which need?","options":["Safety needs","Self-actualisation needs","Physiological needs","Esteem needs"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Safety needs are about freedom from danger and protection, which is what a safe work environment provides. Option C refers to basic survival needs like food, water and shelter. Options B and D are higher-order needs for recognition and for reaching one's full potential."}},{"itemId":"eebdd15b-5c91-5d36-b386-7376ed66bff0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b41e4416-55b8-5d37-9f02-8866e055b0f5","sourceKey":"bank:BUA202:PQ-008-c","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy, the need to become whatever one is capable of becoming and make full use of one's potential is called:","options":["Social (love) need","Safety need","Esteem need","Self-actualisation need"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Self-actualisation sits at the top of the hierarchy and is about achieving one's full potential. Option C is about self-confidence and being appreciated by others, which is close but still about recognition rather than growth to full potential. Options A and B are lower needs for belonging and protection."}},{"itemId":"016ac40a-f209-51f6-a11d-819874414e8e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d2ec9650-da84-5c16-b79c-513fcf036ed5","sourceKey":"bank:BUA202:PQ-008-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best captures a central principle of Maslow's hierarchy of needs?","options":["Higher-level needs must be satisfied before physiological needs can motivate","A need that has been fully satisfied remains the strongest motivator","Lower-level needs must be largely satisfied before higher-level needs begin to motivate behaviour","All five levels of need motivate a person equally at the same time"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Maslow argued that people move up the pyramid: basic needs come first, and only once they are met do higher needs become the main drivers of behaviour. Option D ignores the idea of a hierarchy, and option A reverses it. Option B contradicts the principle that a satisfied need is no longer a motivator."}},{"itemId":"7c61824c-323d-56f3-a81e-2940ad5ea3f7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7ec5f1c2-0210-5893-97b7-32cee239d580","sourceKey":"bank:BUA202:PQ-009-a","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's Two-Factor Theory, which of the following is a job context (hygiene) factor rather than a job content (motivator) factor?","options":["Responsibility","Achievement","Growth","Pay"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Job context or hygiene factors surround the job, such as pay, working conditions, supervision and relationships with colleagues. Options A, B and C come from the work itself, so they are job content factors, which Herzberg called motivators."}},{"itemId":"2e4a3ba4-d7cb-5010-acc3-7c84b5262236","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c30cc2ae-319f-5e5a-b17f-ef0d4ce3542b","sourceKey":"bank:BUA202:PQ-009-b","parentItemId":null,"revision":1,"payload":{"prompt":"According to Herzberg, what happens when job context (hygiene) factors such as good working conditions and fair pay are adequately provided?","options":["Employees reach self-actualisation","Dissatisfaction is prevented, but employees are not necessarily motivated","Job content factors become unnecessary","Employees become highly motivated to perform"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Hygiene factors only remove the causes of complaint: when they are missing, workers are dissatisfied, and when they are present, workers are simply not dissatisfied. Real motivation comes from job content factors such as achievement and responsibility, so option D is wrong. Option A borrows a term from Maslow, and option C is wrong because managers still need content factors to motivate."}},{"itemId":"08d5bbf2-84d9-5cca-bfe8-0da943dc2353","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8aea0a6b-6eb6-5238-880c-dc6c594fecc6","sourceKey":"bank:BUA202:PQ-009-c","parentItemId":null,"revision":1,"payload":{"prompt":"A manager wants to genuinely motivate staff, not just stop complaints. Following Herzberg, which action is most appropriate?","options":["Organise more social events with colleagues","Repaint the office and improve the canteen","Introduce stricter supervision","Give employees more challenging work, responsibility and opportunities for achievement"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Herzberg's motivators lie in the content of the job itself, such as challenge, responsibility, achievement and growth. Options A and B improve working conditions and interpersonal relationships, which are hygiene factors that prevent dissatisfaction but do not motivate on their own. Option C concerns supervision, which is also a hygiene factor and may even reduce satisfaction."}},{"itemId":"97306da5-c049-5c54-b0dd-77e575d2163d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fa75e1b3-de4f-5dea-b5d0-c54d5f50ee9d","sourceKey":"bank:BUA202:PQ-010-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manager believes that the average employee dislikes work, avoids responsibility and must be closely supervised. This manager holds which set of assumptions?","options":["McGregor's Theory Y","McGregor's Theory X","Vroom's Expectancy Theory","Herzberg's Two-Factor Theory"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Theory X assumes people dislike work and must be controlled, which leads to an authoritarian, tightly supervising style. Option A, Theory Y, makes the opposite, positive assumptions about employees. Options C and D are separate motivation theories, not sets of managerial assumptions about human nature."}},{"itemId":"c24db60f-3532-5867-b329-c3e8dcb5798c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c22e5f50-f38e-50a0-a880-ff7af99cefb3","sourceKey":"bank:BUA202:PQ-010-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which leadership style is most consistent with McGregor's Theory Y assumptions?","options":["Participative, allowing employees discretion and involvement in decisions","Bureaucratic, with no room for employee initiative","Coercive, relying on threats of punishment","Authoritarian, with close supervision and strict control"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Theory Y assumes people are creative, can direct themselves and accept responsibility, so a Theory Y leader extends trust and invites participation. Options B, C and D all rely on control and limit employee initiative, which fits Theory X assumptions instead."}},{"itemId":"fe20d153-7c5c-5e1a-b450-6037f8b2c765","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a98bc70d-ddd0-5455-9d7f-bb0787d5262b","sourceKey":"bank:BUA202:PQ-010-c","parentItemId":null,"revision":1,"payload":{"prompt":"In Vroom's Expectancy Theory, the term for how attractive or desirable a particular outcome (such as a bonus or promotion) is to an individual is:","options":["Instrumentality","Expectancy","Hygiene","Valence"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Valence is the value a person places on an outcome; if the reward does not matter to the person, motivation falls. Option B, expectancy, is the belief that effort will lead to good performance, and option A, instrumentality, is the belief that good performance will lead to the outcome. Option C is a Herzberg term and has nothing to do with Vroom's model."}},{"itemId":"b3c2cce3-47d7-5e3e-936e-5624557399b3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a2331b29-7a7f-575a-91cf-5de236f2dcfa","sourceKey":"bank:BUA202:PQ-010-d","parentItemId":null,"revision":1,"payload":{"prompt":"A salesperson works hard only if she believes her effort will raise her sales, that higher sales will earn a bonus, and that the bonus is worth having. Which theory does this illustrate?","options":["Maslow's Hierarchy of Needs","McGregor's Theory X","Herzberg's Two-Factor Theory","Vroom's Expectancy Theory"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Expectancy Theory links effort to performance, performance to reward, and the value of that reward, which is exactly the chain in this example. Option A explains motivation through levels of need, not a chain of beliefs. Options B and C deal with managerial assumptions and with satisfiers versus dissatisfiers respectively."}},{"itemId":"27e97125-94ac-5b6e-a1a7-20c1d8bf45d7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a2616fa7-f4ff-5732-a267-11bbbb10c350","sourceKey":"bank:BUA202:PQ-011-a","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation in the workplace is best defined as:","options":["The formal reporting relationships within an organisation","The monitoring of performance and correction of deviations from plans","The process of hiring and placing employees in suitable jobs","The process through which managers initiate, direct and sustain employees' behaviour towards a desired direction"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Motivation is about starting, steering and keeping up employee behaviour so it moves towards organisational goals. Option C describes recruitment and selection. Option B describes the controlling function, and option A describes organisational structure."}},{"itemId":"7970bdf0-7962-5392-86a4-72e23c1ad0f4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3db2e37d-edc1-54cb-9f50-305236c4a2b7","sourceKey":"bank:BUA202:PQ-011-b","parentItemId":null,"revision":1,"payload":{"prompt":"Why does a need that has already been satisfied stop functioning as a motivator?","options":["Because behaviour is driven by unmet needs, so once a need is met it no longer pushes the person to act","Because satisfied needs are replaced by lower-level needs","Because managers stop paying attention to satisfied needs","Because satisfied needs automatically turn into hygiene factors"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The motivation cycle begins with an unmet need that triggers behaviour; once the outcome satisfies the need, the tension that drove the behaviour disappears. Option D mixes in Herzberg's terminology incorrectly. Option C is about managers rather than the employee's own drive, and option B is wrong because, in Maslow's view, attention moves up to higher needs, not down."}},{"itemId":"7e6a7cb1-b3df-560c-bfb8-abae50b00bbf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"64f0c539-01eb-5f60-a9a3-ee2123ff496a","sourceKey":"bank:BUA202:PQ-011-c","parentItemId":null,"revision":1,"payload":{"prompt":"In the basic motivation cycle, what starts the process that leads to new behaviour?","options":["An unmet need","A completed task","A performance appraisal","A satisfactory outcome"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"The cycle runs from an unmet need, to new behaviour, to an outcome that may or may not satisfy the need. Option D comes at the end of the cycle, not the start. Options B and C are workplace events that may follow behaviour but do not begin the cycle."}},{"itemId":"5490dfa9-7a6f-5505-b42a-1541849ba100","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c3ddfb67-494c-5731-a0c7-a56d86eb32c6","sourceKey":"bank:BUA202:PQ-012-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an INTERNAL factor driving organisational change, rather than an external one?","options":["Globalisation","Increased competition","Changes in employee attitudes","New government regulation or deregulation"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Employee attitudes arise inside the organisation, so a shift in how staff think and behave is an internal pressure for change. Options A, B and D all come from the firm's external environment: rival firms, government action and the widening global economy."}},{"itemId":"ae94c534-e337-5a50-9316-124b6264d8fe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b885beba-4af2-5ccb-bed2-5788d250c3b7","sourceKey":"bank:BUA202:PQ-012-b","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank changes its operations after the regulator introduces new rules and rival banks launch cheaper digital services. These pressures for change are best described as:","options":["External drivers of change","Levels of change","Internal drivers of change","Resistance to change"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Regulation and competition originate outside the organisation, so they are external drivers. Option C would be things like changing employee attitudes or skills inside the bank. Option B refers to how deep a change goes, and option D is the opposition people show to change, not its causes."}},{"itemId":"c1f96b2f-abdd-50d9-af0d-a501d40619f0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0b8892e7-2d9d-5410-b227-59a8b70f78c2","sourceKey":"bank:BUA202:PQ-013-a","parentItemId":null,"revision":1,"payload":{"prompt":"A firm creates a new department, merges two teams and changes reporting lines to improve coordination. In which area of the organisation is change taking place?","options":["Employee attitude","Strategy","Structure","Employee skills"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Structure refers to how the organisation is arranged, including departments, reporting lines and responsibilities, so this is structural change. Option B is the long-term plan for achieving goals. Options A and D relate to employees' knowledge and their willingness to support change, not to how units are arranged."}},{"itemId":"0ec8ed2b-b0fd-51cc-b0db-a94972805d33","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"23172348-49d1-59c9-aab9-af3c05842d25","sourceKey":"bank:BUA202:PQ-013-b","parentItemId":null,"revision":1,"payload":{"prompt":"As a company grows, it runs training and development programmes so staff gain new knowledge and abilities. This is change in which area?","options":["Strategy","Structure","Employee skills","Technology"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"When employees need new knowledge and abilities, the change is in employee skills, and it is managed mainly through training and development. Option B would involve changing departments or reporting lines. Option A concerns the organisation's long-term plan, and option D concerns adopting new tools and software."}},{"itemId":"9927e2a5-dbba-50cd-b3b7-53a2216bb7ee","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"108646c5-841e-5b56-b3f0-f4bf5200a880","sourceKey":"bank:BUA202:PQ-013-c","parentItemId":null,"revision":1,"payload":{"prompt":"A company rethinks its long-term plan for achieving its goals because market conditions have shifted. This is change in which area?","options":["Systems and processes","Structure","Strategy","Employee attitude"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Strategy is the organisation's long-term plan, and it is the area that changes when market conditions or business objectives shift. Option A concerns the day-to-day methods for doing work. Options B and D concern employees' willingness to change and the arrangement of departments, respectively."}},{"itemId":"557f938b-43a1-5d4f-a7b1-6c4c749c29be","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9f67831b-0bb2-532b-9fd6-0c7463d06496","sourceKey":"bank:BUA202:PQ-014-a","parentItemId":null,"revision":1,"payload":{"prompt":"In Field's (2006) three levels of organisational change, which level is strategic in nature and questions the organisation's purpose and agenda?","options":["First level","Second level","Third level","None of the levels; this is resistance to change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"The second level is strategic: it asks whether the organisation's purpose and agenda are still right. Option A, the first level, is implemental and keeps the existing alignment of the system. Option C, the third level, is the broadest, organisation-wide effort involving order, beliefs, values and how subsystems relate, and option D is not a level at all."}},{"itemId":"f3add0c1-4157-5448-9381-f7e6be621548","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ad47ae72-76f1-529e-ae9a-5dd13489ea6c","sourceKey":"bank:BUA202:PQ-014-b","parentItemId":null,"revision":1,"payload":{"prompt":"In Field's (2006) three levels of organisational change, the first level is best described as:","options":["Organisation-wide, involving beliefs, values and the relationships between subsystems","Revolutionary, replacing the entire workforce","Implemental, seeking to maintain the existing alignment within the organisational system","Strategic, questioning the organisation's purpose and agenda"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"The first level is the narrowest and least disruptive: it implements adjustments while keeping the current alignment in place. Option D describes the second level and option A describes the third. Option B is not part of the three-level model."}},{"itemId":"f099e658-ea47-5c72-8af6-b3b388af9abc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e69348f1-eb02-582c-a80f-9a9213b92f24","sourceKey":"bank:BUA202:PQ-015-a","parentItemId":null,"revision":1,"payload":{"prompt":"What are the three stages of Lewin's change model, in the correct order?","options":["Unfreeze, Change, Refreeze","Change, Unfreeze, Refreeze","Plan, Do, Check","Urgency, Vision, Anchor"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Lewin's model first unfreezes existing habits, then moves people to the new way of working, and finally refreezes the new behaviour so it becomes permanent. Option B has the right words in the wrong order. Option C is a quality-improvement cycle, and option D picks out steps from Kotter's eight-step model."}},{"itemId":"d5156be5-3a01-55c9-8dcf-9826490def1e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"167df4c7-7cfc-5e65-8c2f-95d98abef69f","sourceKey":"bank:BUA202:PQ-015-b","parentItemId":null,"revision":1,"payload":{"prompt":"During which stage of Lewin's model would management establish new policies and reward employees for adopting the new way of working, so the change becomes permanent?","options":["Refreezing","Unfreezing","Creating urgency","Changing (movement)"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Refreezing locks in the change through new policies, rewards and reinforcement of new behaviour. Option B prepares people by explaining why change is needed and reducing resistance. Option D is when the change is actually implemented, through training or new technology, and option C is the first step of Kotter's model, not a Lewin stage."}},{"itemId":"3cb98cbb-4dd6-5182-857a-0f0431eca0a1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ebfa9ed4-04f6-53e2-acab-99a268ce6551","sourceKey":"bank:BUA202:PQ-015-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best compares Lewin's and Kotter's change models?","options":["Lewin's model is a simple three-stage framework, while Kotter's is a more detailed eight-step process for leading large-scale change","Kotter's model deals only with resistance to change, while Lewin's deals only with technology","Both models skip the step of making the change permanent","Lewin's model has eight steps, while Kotter's has three"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Lewin offers a basic three-stage pattern for change, while Kotter expands it into eight practical steps suited to large organisations. Option D swaps the number of steps. Option C is wrong because both end by making change stick (refreezing and anchoring), and option B misrepresents both models."}},{"itemId":"8bbd588c-a26a-5f01-87fc-cbf6c476325f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"82ea408d-adf4-5f00-8e9c-58682eafe2bd","sourceKey":"bank:BUA202:PQ-015-e","parentItemId":null,"revision":1,"payload":{"prompt":"A common criticism of Lewin's three-step model is that it:","options":["Has too many steps for managers to remember","Can only be used in government organisations","Assumes change has a clear end point, whereas change in many organisations is continuous","Ignores the need to make change permanent"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Lewin's model is praised for its simplicity, but critics say the idea of refreezing assumes the organisation settles into a stable state, while real organisations often face ongoing change. Option A fits Kotter's longer model better than Lewin's three steps. Option D is wrong because refreezing is exactly about making change permanent, and option B has no basis."}},{"itemId":"dc18142c-e17f-5cf6-bfbd-2f113dad7ee3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0512c1a2-c575-520f-be3c-2380bcf89775","sourceKey":"bank:BUA202:PQ-016-a","parentItemId":null,"revision":1,"payload":{"prompt":"Decisions that translate top management's direction into departmental plans that units can implement are called:","options":["Strategic decisions, made by top management","Tactical decisions, made by middle-level managers","Programmed decisions, made by any employee","Operational decisions, made by first-line managers"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Tactical decisions sit in the middle: departmental heads and middle managers break the organisation's overall direction into workable plans. Option A sets that overall direction in the first place. Option D covers day-to-day running, and option C describes routine decisions handled by rules, which is a different way of classifying decisions."}},{"itemId":"800e0c5d-cc0c-5bbf-86b9-5ffd43def475","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"932b0a30-0427-5e07-b21c-a9bf9f1bb708","sourceKey":"bank:BUA202:PQ-016-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company's board and CEO decide whether to diversify into a new industry. This is an example of:","options":["A programmed decision","A tactical decision","An operational decision","A strategic decision"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Strategic decisions concern the long-term direction of the whole organisation, such as which industry to operate in or whether to expand or diversify, and they are made at the top. Options B and C are made lower down to implement plans or run daily operations. Option A is wrong because diversification is unique and complex, not routine."}},{"itemId":"b8f6c886-2f0d-59aa-867e-e6ff0293f9f1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7848781b-bdab-55fb-bc1a-a70c31ab7cb8","sourceKey":"bank:BUA202:PQ-016-c","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor decides how to allocate today's shifts among workers on the shop floor. This is best classified as:","options":["A strategic decision","A tactical decision","An operational decision","A non-programmed decision"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Operational decisions deal with the day-to-day running of the organisation and are made by first-line managers and supervisors. Option A concerns long-term direction, and option B concerns turning strategy into departmental plans. Option D is wrong because shift allocation is routine and familiar, not unique and complex."}},{"itemId":"331f55ba-c899-5bb5-9704-b2d0788b29bb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d7fc1182-dff4-51c0-97e8-7428edbec94d","sourceKey":"bank:BUA202:PQ-017-a","parentItemId":null,"revision":1,"payload":{"prompt":"A bag contains 100 balls: 40 red and 60 black. A decision-maker must bet on drawing a red ball. Because the outcomes and their probabilities are known, this situation is one of:","options":["Certainty","Risk","Bounded rationality","Uncertainty"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Risk exists when the possible outcomes can be identified and their probabilities can be estimated, here a 40 percent chance of red. Option D would apply if the mix of balls were not disclosed, so no meaningful probability could be assigned. Option A is wrong because the outcome is still unknown, and option C describes limits on decision-makers, not a decision condition."}},{"itemId":"2d9c19a4-7d5e-598d-b857-2835b228613d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cbe18d27-9643-51c0-ab13-245ad28122cf","sourceKey":"bank:BUA202:PQ-017-b","parentItemId":null,"revision":1,"payload":{"prompt":"A sudden national lockdown, which no one had expected and to which no reliable probability could have been assigned in advance, is an example of decision-making under:","options":["Programmed conditions","Risk","Uncertainty","Certainty"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Uncertainty exists when possible outcomes are hard to identify and reliable probabilities cannot be calculated, as with an unexpected lockdown. Option B requires probabilities that can reasonably be estimated, for example from past experience. Options A and D wrongly suggest the outcome was known or routine."}},{"itemId":"b4e8bb1f-fb63-5a4e-9335-550270df313e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"763e5678-fd1b-5a66-8a1e-8ea6bee273ea","sourceKey":"bank:BUA202:PQ-017-c","parentItemId":null,"revision":1,"payload":{"prompt":"Why is insurance possible for many business hazards?","options":["Because the hazards are programmed decisions","Because insurers know exactly which firms will suffer losses","Because they involve uncertainty, where no probability can be estimated","Because they involve risk, whose probability can be estimated from past experience"],"correctOption":3,"section":"Managerial Decision-Making and Problem Solving","explanation":"Insurers price policies by estimating the likelihood of losses from past data, which is only possible when a situation involves risk. Option C is the opposite: true uncertainty cannot be priced. Option B confuses estimating probabilities with knowing outcomes, and option A misuses a term for routine decisions."}},{"itemId":"7d0f7770-2489-512e-81bd-b47e94b76b29","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"14e73267-63ed-5e7a-bb83-a6f0dc8889d4","sourceKey":"bank:BUA202:PQ-018-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an assumption of the rational decision-making model?","options":["The decision-maker settles for the first option that is good enough","The decision-maker relies mainly on feelings and personal relationships","The decision-maker has complete information and can identify and evaluate all alternatives","The decision-maker's information and time are always limited"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"The rational model assumes a clear grasp of the problem, complete information, all alternatives identified, consequences evaluated accurately and the best option chosen. Option A describes satisficing under bounded rationality. Option B is the opposite of the model's objective, fact-based approach, and option D is a limitation of the model rather than one of its assumptions."}},{"itemId":"c8f3c6f5-5471-5db7-88a1-d364348986a0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"31d43f76-ebce-5f64-a0b0-ce7740325914","sourceKey":"bank:BUA202:PQ-018-b","parentItemId":null,"revision":1,"payload":{"prompt":"Why is the rational decision-making model often described as an ideal rather than a full description of how managers actually decide?","options":["Because it encourages impulsive decisions","Because it has no structured steps","Because managers rarely have complete information, unlimited time or unlimited resources","Because it ignores the need to evaluate alternatives"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"In real life managers face incomplete information, time pressure and scarce resources, so they cannot always follow every step perfectly. Options A, B and D are wrong because the model's strengths are exactly that it reduces impulsive decisions, gives a structured process and requires systematic evaluation of alternatives."}},{"itemId":"c4981267-566d-5d6e-bdd8-513e17e519a2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"56fd185f-6142-5027-8a91-438b86dc92ab","sourceKey":"bank:BUA202:PQ-019-a","parentItemId":null,"revision":1,"payload":{"prompt":"The idea that decision-makers face limits such as incomplete information, limited cognitive capacity and time pressure is known as:","options":["Confirmation bias","Escalation of commitment","Bounded rationality","Programmed decision-making"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Bounded rationality recognises that human reasoning operates within real limits, so managers cannot always find the perfect answer. Options A and B are specific biases that distort judgement. Option D refers to routine decisions handled by rules and procedures."}},{"itemId":"80f6172a-6aeb-5010-979a-775d613b91c1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2a0c1f2d-e4e5-5043-b9a8-e63b4b63a0f9","sourceKey":"bank:BUA202:PQ-019-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manager stops searching once she finds a supplier that meets her minimum requirements, instead of evaluating every possible supplier. This behaviour is called:","options":["Anchoring","Satisficing","Escalation of commitment","Optimising"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Satisficing means choosing an option that is good enough or satisfactory rather than the absolute best, a natural response to bounded rationality. Option D is what the rational model assumes, choosing the best possible option. Options A and C are biases: over-reliance on first information, and sticking with a failing course because of past investment."}},{"itemId":"9bcd8232-7519-593c-acf0-310c9786218b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"eff8f3b2-9b87-5305-bb82-f8cac1cbf4f2","sourceKey":"bank:BUA202:PQ-020-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manager keeps pouring money into a failing project because 'we have already spent too much to stop now.' Which bias is this?","options":["Availability bias","Overconfidence bias","Escalation of commitment","Anchoring bias"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Escalation of commitment is continuing a failing course of action because of resources already invested, the sunk-cost trap. Option D is over-reliance on the first piece of information received. Option A is judging likelihood by how easily examples come to mind, and option B is overestimating one's own knowledge or ability."}},{"itemId":"27ecc78b-293b-53c6-b312-21785abf0251","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c9b3a6fd-3371-53c5-aba6-925328c53809","sourceKey":"bank:BUA202:PQ-020-b","parentItemId":null,"revision":1,"payload":{"prompt":"During salary negotiations, a manager keeps relying on the first figure mentioned, even after better market data becomes available. Which bias is this?","options":["Escalation of commitment","Availability bias","Anchoring bias","Confirmation bias"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Anchoring bias is relying too heavily on the first information received, even when better information appears later. Option D is seeking information that supports an existing belief. Option A concerns continuing a failing investment, and option B concerns judging probability by how memorable examples are."}},{"itemId":"5c990e1e-aefb-56e6-a080-2cf9d1177770","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f86383a9-f463-5ffc-b876-86c80d3e1eeb","sourceKey":"bank:BUA202:PQ-020-c","parentItemId":null,"revision":1,"payload":{"prompt":"People often fear shark attacks more than being hit by falling coconuts, simply because shark scenes are more vivid and memorable. Which bias does this illustrate?","options":["Anchoring bias","Availability bias","Confirmation bias","Overconfidence bias"],"correctOption":1,"section":"Managerial Decision-Making and Problem Solving","explanation":"Availability bias is judging how likely something is by how easily examples come to mind, often because they are recent or vivid, rather than by actual probability. Option A is about over-relying on first information. Option C is about seeking supporting evidence for an existing belief, and option D is about overestimating ability."}},{"itemId":"ccf70a49-eba8-5b2c-a296-807b3cba8dbf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c584e138-5bef-5351-939f-c352f97c9fd3","sourceKey":"bank:BUA202:PQ-020-d","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who believes a new product will succeed reads only reports that support this view and ignores evidence that contradicts it. Which bias is this?","options":["Confirmation bias","Escalation of commitment","Anchoring bias","Availability bias"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"Confirmation bias is the tendency to seek information that supports an existing belief while disregarding contradicting evidence. Option D is about how easily examples come to mind. Option B involves continuing to invest because of past spending, and option C is over-reliance on the first information received."}},{"itemId":"67a6d941-763c-5523-bcaa-3eeeff11a998","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6a55f532-1275-5c58-834c-1c3756586406","sourceKey":"bank:BUA202:PQ-021-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the eight-step managerial decision-making process, which step comes immediately after diagnosing the problem?","options":["Selecting an alternative","Generating alternatives","Establishing decision criteria","Implementing the decision"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"After identifying and diagnosing the problem, the manager sets the criteria, such as cost, quality, speed or risk, that will be used to judge alternatives. Option B comes next, once criteria exist. Options A and D come later still, after alternatives have been evaluated."}},{"itemId":"10414f81-1e33-56ef-bc0f-d0bbeadec8a8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"05aecf8e-c781-516d-a5fd-488a04ab83d9","sourceKey":"bank:BUA202:PQ-021-b","parentItemId":null,"revision":1,"payload":{"prompt":"What is the final step of the eight-step managerial decision-making process?","options":["Evaluating the outcome of the decision","Implementing the decision","Identifying the problem or opportunity","Selecting an alternative"],"correctOption":0,"section":"Managerial Decision-Making and Problem Solving","explanation":"The process ends by evaluating the outcome: did the decision solve the problem, were there unintended consequences, and what should change? Option B is the seventh step, just before evaluation. Option D is the sixth step, and option C is the very first step."}},{"itemId":"214bd1a8-e099-5662-b4cb-6cf5ba012af5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a7bb0e00-8a9b-5ba8-a5b6-c2bebeb736c3","sourceKey":"bank:BUA202:PQ-021-c","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's sales have dropped. Before choosing a solution, the manager investigates what changed, when it changed and which department is involved, treating the drop as a symptom. Which step is the manager carrying out?","options":["Generating alternatives","Evaluating the outcome","Diagnosing the problem","Implementing the decision"],"correctOption":2,"section":"Managerial Decision-Making and Problem Solving","explanation":"Diagnosing the problem means investigating its root causes rather than reacting to surface symptoms, just as a headache is a symptom and not the underlying illness. Option B happens only after a decision has been implemented. Options A and D come later, after the true problem and decision criteria are clear."}},{"itemId":"028c8186-edaf-52f7-a6e4-13cff44a95b8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2a7bab5d-d87b-5f34-adf9-c14905f65403","sourceKey":"bank:BUA202:PQ-022-a","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational Behaviour draws on psychology, sociology, anthropology, economics and political science. This feature is described as its:","options":["Inter-disciplinary nature","Goal-oriented nature","Dynamic nature","Application-oriented nature"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Organisational Behaviour borrows ideas and methods from several disciplines, which is what inter-disciplinary means. Option B refers to its aim of improving organisational effectiveness and performance. Option C refers to the field evolving as organisations change, and option D refers to applying its principles to solve workplace problems."}},{"itemId":"84ec96cf-bf98-5be6-84c8-88cf8f6f9af6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"02f62c57-55da-528e-a293-e0df90e0399e","sourceKey":"bank:BUA202:PQ-022-b","parentItemId":null,"revision":1,"payload":{"prompt":"At which level of Organisational Behaviour would a study of employees' personality, perception and job satisfaction fall?","options":["Organisational level","Individual level","Group level","Industry level"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Personality, perception, learning, motivation and job satisfaction are characteristics of individual people, so they belong to the individual level. Option C covers things like team dynamics, communication and conflict among people. Option A covers structure, culture and organisational change, and option D is not one of the three levels of Organisational Behaviour."}},{"itemId":"d4dd0fe4-9e84-5ee5-b08a-7c99f8b7ec96","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7e9a250e-77f1-5061-a0b7-b9c9eb4b80ad","sourceKey":"bank:BUA202:PQ-022-c","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational culture, organisational structure and organisational change are studied at which level of Organisational Behaviour?","options":["Personal level","Individual level","Organisational level","Group level"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Culture, structure, change and development are properties of the organisation as a whole, so they belong to the organisational level. Option B covers personal traits like personality and perception. Option D covers teamwork and group decision-making, and option A is not one of the three levels."}},{"itemId":"be7be3bd-e195-519d-b770-44db56a4e32c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"31a316f7-8d93-5cde-9135-dcf271d4b423","sourceKey":"bank:BUA202:PQ-022-d","parentItemId":null,"revision":1,"payload":{"prompt":"The feature of Organisational Behaviour that means it relies on research and systematic analysis rather than assumption is its:","options":["Human-oriented nature","Goal-oriented nature","Scientific approach","Dynamic nature"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Organisational Behaviour applies scientific methods, such as research and analysis, to study human behaviour at work. Option A refers to its focus on people and relationships. Options B and D refer to the field changing over time and to its aim of improving effectiveness."}},{"itemId":"d66cecbc-2967-5193-ba05-09903b58466a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e17760c2-209a-5a9f-a293-5740c6a3769b","sourceKey":"bank:BUA202:PQ-023-a","parentItemId":null,"revision":1,"payload":{"prompt":"A company sets up a committee to organise its end-of-year event. Once the event is over, the committee is dissolved. What type of group is this?","options":["A friendship group","A command group","An interest group","A task group"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A task group is a formal group created to complete a specific project or assignment, such as organising an event. Option B is also formal, but it consists of a manager and the subordinates who report directly to them. Options A and C are informal groups that form through social interaction, not by the organisation's design."}},{"itemId":"a88a85e4-936c-587d-9e0d-c97978363290","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d47cf3c5-ce1f-5979-a101-3220a70c8472","sourceKey":"bank:BUA202:PQ-023-b","parentItemId":null,"revision":1,"payload":{"prompt":"A group made up of a manager and the subordinates who report directly to that manager is called:","options":["A task group","A command group","An interest group","A friendship group"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"A command group is set out by the organisation chart: a supervisor plus the people who report to them. Option A is formed for a specific project and crosses normal reporting lines. Options C and D are informal groups that arise from employees' own social ties and shared interests."}},{"itemId":"2187cd04-4783-5c62-8df6-e35fbb60eb90","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6fd42392-28aa-5d52-810c-f457fc555eab","sourceKey":"bank:BUA202:PQ-023-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes informal groups from formal groups?","options":["Informal groups always have a supervisor, while formal groups never do","Informal groups exist only outside the workplace","Informal groups are created by management, while formal groups arise from friendships","Informal groups develop naturally through social interaction among employees, while formal groups are deliberately established by the organisation"],"correctOption":3,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Formal groups, such as command and task groups, are set up deliberately by the organisation, while informal groups, such as friendship and interest groups, grow out of social interaction. Option C reverses the two. Option A is wrong because informal groups have no officially appointed supervisor, and option B is wrong because informal groups form inside the workplace too."}},{"itemId":"ad7eca1e-e9be-5b4c-af2c-04b0d1bd17c6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"66734783-9a5d-5c15-8295-cead685f628b","sourceKey":"bank:BUA202:PQ-024-b","parentItemId":null,"revision":1,"payload":{"prompt":"In which stage of group development do members express differing opinions and ideas, often causing friction?","options":["Norming","Performing","Storming","Adjourning"],"correctOption":2,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Storming is when members push their own views and the group experiences conflict as it finds its footing. Option A comes after this, when norms, trust and cooperation are established. Option B is when the group becomes fully functional, and option D is when it disbands."}},{"itemId":"bcbeda89-3bad-5c50-b151-36525757a6bb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3b0d13a2-7f59-53c9-84e0-7e0d0ce62c7a","sourceKey":"bank:BUA202:PQ-024-c","parentItemId":null,"revision":1,"payload":{"prompt":"A project team has completed its assignment and its members are being released back to their departments. Which stage of group development is this?","options":["Adjourning","Norming","Performing","Forming"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Adjourning is the final stage, when the group disbands after its purpose has been fulfilled. Option C is the stage before, when the team is working productively. Options B and D are early stages, when the group first comes together and then agrees on norms."}},{"itemId":"2e446e9b-8688-5694-8881-e8dadba34cf2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"63274627-79e9-5c80-ba94-903760e15c0f","sourceKey":"bank:BUA202:PQ-025-a","parentItemId":null,"revision":1,"payload":{"prompt":"The shared expectations that guide how members of a group are supposed to behave are called group:","options":["Adjourning","Norms","Size","Coercion"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Norms are the agreed standards of behaviour that members are expected to follow, and they strongly shape how a group behaves. Option C is the number of members, which affects coordination and communication. Option D is the use of pressure or force on members, and option A is a stage of group development, not a factor shaping behaviour."}},{"itemId":"21e925b1-f60b-5fcf-b22e-eb0b06464e64","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2e510e1d-8c9c-5135-8f9f-8637b8c1abc5","sourceKey":"bank:BUA202:PQ-025-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which group of items lists factors that influence group behaviour?","options":["Group size, norms, leadership and communication","Purpose, structure and people","Forming, storming, norming and performing","Planning, organising, leading and controlling"],"correctOption":0,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Group size, norms, leadership and communication (along with coercion) all shape how a group actually behaves day to day. Option C lists stages of group development rather than influencing factors. Option D lists the functions of management, and option B lists the core elements of an organisation."}},{"itemId":"487e4e3f-ac7f-5902-97d3-81c5fb602611","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b9fb68ff-c5b1-50a8-8ccc-232d3d94e481","sourceKey":"bank:BUA202:PQ-026-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, converting an idea into words, symbols or images is called:","options":["Feedback","Decoding","Encoding","Noise"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Encoding is the sender's job of turning an intended meaning into a form that can be transmitted. Option B is the reverse, when the receiver interprets the message. Option A is the receiver's response, and option D is anything that distorts or interferes with the message."}},{"itemId":"c0e28276-8e60-55d3-b2d7-93c53d9ccb94","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ee190e6d-fb77-53b4-8e75-92cc2617cd77","sourceKey":"bank:BUA202:PQ-026-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly represents the seven-part communication process?","options":["Sender, Channel, Encoding, Message, Feedback, Receiver, Decoding","Receiver, Decoding, Message, Channel, Sender, Encoding, Feedback","Sender, Encoding, Message, Channel, Receiver, Decoding, Feedback","Sender, Message, Decoding, Channel, Receiver, Encoding, Feedback"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"The sender encodes an idea into a message, sends it through a channel to the receiver, who decodes it and responds with feedback. Option D places decoding before the message reaches the receiver and encoding at the receiver's end. Options A and B also scramble the order, for example by starting with the receiver or giving feedback before decoding."}},{"itemId":"e58368fd-0d52-5f28-a176-24554ba7dca7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0bd1699c-cfb9-5ef0-88f5-bf18cc8d9aa4","sourceKey":"bank:BUA202:PQ-026-c","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, anything that distorts, filters or interferes with accurate communication is called:","options":["Encoding","Channel","Noise","Feedback"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Noise is any interference, such as jargon, distractions or bias, that causes the message to be misunderstood, and the sender should try to minimise it. Option B is the medium used, such as email or a meeting. Option D is the receiver's response, and option A is turning ideas into symbols."}},{"itemId":"889f05c6-2940-579d-b502-f3c1ecd6c0de","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e4316871-fc76-5771-bf50-a09677d3b555","sourceKey":"bank:BUA202:PQ-026-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of the communication process tells the sender whether the message was understood as intended?","options":["Encoding","Channel","Feedback","Message"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Feedback is the receiver's verbal or non-verbal response, and it confirms whether communication actually took place. Option A happens at the sender's end before transmission. Options B and D are the medium and the content, neither of which shows whether the message was understood."}},{"itemId":"284c6d29-94a3-554b-ac4a-7ae8b3427bc9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ede839b9-a05f-54ae-8cc0-ed529aea4baa","sourceKey":"bank:BUA202:PQ-027-a","parentItemId":null,"revision":1,"payload":{"prompt":"Employees send complaints, reports and suggestions to their managers. This flow of formal communication is called:","options":["Horizontal communication","Upward communication","Grapevine communication","Downward communication"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Upward communication flows from lower levels to higher levels of the organisation, carrying feedback, reports, complaints and suggestions. Option D flows from managers to subordinates, such as policies and instructions. Option A is between people at the same level, and option C is informal rather than formal."}},{"itemId":"85f82f64-45c3-52ee-b891-e4fbe190aab1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5b8e95c7-904e-556c-be9a-649032951a8d","sourceKey":"bank:BUA202:PQ-027-b","parentItemId":null,"revision":1,"payload":{"prompt":"A sales officer communicates directly with the head of the finance department, a different department and a higher level, outside the normal reporting line. This is:","options":["Upward communication","Downward communication","Horizontal communication","Diagonal communication"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Diagonal communication cuts across both departments and hierarchical levels, outside the standard reporting structure. Option C is between people at the same level. Options A and B move up or down within the same chain of command."}},{"itemId":"71898f72-4e20-587d-99d6-075ed13d92ad","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e0ea5830-fd9c-51a6-9df5-1e000711b179","sourceKey":"bank:BUA202:PQ-027-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes the grapevine from a rumour?","options":["The grapevine is the informal channel itself, while a rumour is unverified or distorted information that may travel through it","There is no difference; the two terms mean the same thing","The grapevine is a formal channel, while a rumour is an informal one","The grapevine always carries false information, while a rumour is always true"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"The grapevine is the network, and true, false or partial information can pass through it; a rumour is specifically unverified or distorted information. Option D is wrong because grapevine information is not necessarily inaccurate and can even be faster than formal channels. Option C wrongly calls the grapevine formal, and option B ignores the difference between a channel and its content."}},{"itemId":"0ccbcc98-d1b1-5da9-87ab-6ce7ecdb79b3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8fc029dc-46f6-5837-ace4-d8ee7a493412","sourceKey":"bank:BUA202:PQ-028-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manager sends a very short memo that leaves out the deadline staff need in order to act. Which characteristic of effective communication has been violated?","options":["Completeness","Timeliness","Appropriateness","Conciseness"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"A complete message gives the receiver enough information to understand and act on it, and missing the deadline breaks that rule. Option D is tempting, but conciseness means avoiding unnecessary information, not leaving out essential information. Options B and C relate to sending information while still useful and suiting tone and medium to the audience."}},{"itemId":"aa792482-f5ed-59aa-bb3e-05eae63a730d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c260a687-bd67-5c05-9c54-42ff54ca2790","sourceKey":"bank:BUA202:PQ-028-b","parentItemId":null,"revision":1,"payload":{"prompt":"Information about a training session reaches employees the day after the session has taken place. Which characteristic of effective communication is missing?","options":["Clarity","Timeliness","Conciseness","Accuracy"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Timely communication arrives while the information is still useful, and a notice received after the event is useless. Option D is about factual correctness, which may still be fine here. Options A and C are about being easily understood and avoiding unnecessary detail."}},{"itemId":"4b81eb37-5b58-536f-844d-5366ea8bd914","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"4a19b482-8b4d-5866-a4d2-bc5a3c5e8e6c","sourceKey":"bank:BUA202:PQ-028-c","parentItemId":null,"revision":1,"payload":{"prompt":"Using language, tone and medium suited to the audience is which characteristic of effective communication?","options":["Timeliness","Accuracy","Appropriateness","Completeness"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"An appropriate message fits its audience, for example avoiding jargon with non-specialists or choosing a formal tone for official matters. Option B concerns facts being correct. Options A and D concern giving enough information and delivering it in time."}},{"itemId":"fb3fd3b8-d551-57d1-af20-13ba283eff41","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"126b0ca6-ad24-5c83-bb2b-59b280c0fee3","sourceKey":"bank:BUA202:PQ-029-a","parentItemId":null,"revision":1,"payload":{"prompt":"The function of a financial system that bridges surplus units (such as households with extra money) and deficit units (such as businesses that need funds) is:","options":["Financial intermediation","Risk management","Payment facilitation","Price discovery"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Financial intermediation channels funds from those who have surplus money to those who need it, mainly through banks and other institutions. Option D is about markets setting fair prices through supply and demand. Option C is about moving funds for everyday transactions, and option B provides tools like insurance and derivatives to manage risks."}},{"itemId":"943cf6db-681b-57c0-bb95-88b13dbdbfb8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b73a88e9-03c9-5b2b-ab11-3aac3b1d6197","sourceKey":"bank:BUA202:PQ-029-b","parentItemId":null,"revision":1,"payload":{"prompt":"Financial markets bring buyers and sellers together so that fair prices for securities and assets are set by supply and demand. This function is called:","options":["Mobilisation of savings","Financial intermediation","Price discovery","Capital formation"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Price discovery is the process by which trading between many buyers and sellers establishes an asset's market value. Option A gathers small, scattered savings into a pool for investment. Option D converts savings into capital for building and expanding, and option B links savers with borrowers."}},{"itemId":"dfaf17b9-baae-542e-89b4-7b7a7a224566","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"dbfdae4b-4cb8-52bc-92f8-f39933d23eb4","sourceKey":"bank:BUA202:PQ-029-c","parentItemId":null,"revision":1,"payload":{"prompt":"Pooling the small, scattered savings of many individuals and channelling them into productive investment is known as:","options":["Payment facilitation","Price discovery","Risk management","Mobilisation of savings"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Mobilisation of savings aggregates many small deposits so they can fund larger productive investments. Option B is about setting asset prices. Option A is about moving money for transactions, and option C is about protecting against losses through tools like insurance."}},{"itemId":"b6687855-41b6-50dc-b43e-7e3bf96bab65","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"296c8370-e1e1-5de5-93bf-aac2a895a417","sourceKey":"bank:BUA202:PQ-029-d","parentItemId":null,"revision":1,"payload":{"prompt":"Insurance policies and derivatives that allow firms to hedge against losses support which function of the financial system?","options":["Risk management","Capital formation","Mobilisation of savings","Price discovery"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Risk management tools such as insurance and derivatives let individuals and firms hedge, diversify and manage financial and physical risks. Option B is about turning savings into productive capital. Options C and D are about setting market prices and pooling savings."}},{"itemId":"4da2b919-af75-5d8b-9fa9-9be5f2266e77","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d4a4800a-01b6-58e5-b1b2-d6def28b1a4c","sourceKey":"bank:BUA202:PQ-030-a","parentItemId":null,"revision":1,"payload":{"prompt":"In Nigeria's financial system, which body insures bank deposits and protects depositors in the event of bank failure?","options":["National Insurance Commission (NAICOM)","Nigeria Deposit Insurance Corporation (NDIC)","Securities and Exchange Commission (SEC)","National Pension Commission (PenCom)"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"NDIC provides deposit insurance, so depositors are protected up to set limits if a bank fails. Option A is tempting because of the word insurance, but NAICOM regulates and supervises the insurance industry. Option D regulates pensions, and option C is the apex regulator of the capital market."}},{"itemId":"1562ca88-14da-5f39-b8af-cfb160a75d3e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f8e95189-d904-5530-b8e1-7144ac7c25a7","sourceKey":"bank:BUA202:PQ-030-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which Nigerian body regulates and supervises the administration of pension funds, including Pension Fund Administrators?","options":["National Insurance Commission (NAICOM)","Central Bank of Nigeria (CBN)","Nigeria Deposit Insurance Corporation (NDIC)","National Pension Commission (PenCom)"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"PenCom regulates, supervises and ensures the effective administration of pension matters in Nigeria. Option B regulates banks and conducts monetary policy. Option A regulates insurance companies, and option C insures bank deposits."}},{"itemId":"eb791b9b-7ac2-5ed0-b6b9-7b0a523a3167","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"874d662b-b2ac-53e3-aa59-7fdff0925f5a","sourceKey":"bank:BUA202:PQ-030-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following belongs to the INFORMAL sector of the Nigerian financial system?","options":["Microfinance banks","Unregistered thrift societies such as esusu or ajo","Merchant banks","Pension Fund Administrators"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The informal sector operates outside the regulatory structure and includes local moneylenders and unregistered thrift groups such as esusu and ajo. Options A, C and D are licensed institutions supervised by regulators, so they belong to the formal sector."}},{"itemId":"2846f864-ae13-5ae8-9f8a-f635904c264f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ed1f755d-5224-5713-b1dd-be3bf63ee81d","sourceKey":"bank:BUA202:PQ-030-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which body is the apex regulatory authority of Nigeria's banking sector, responsible for monetary policy and issuing legal tender?","options":["Nigeria Deposit Insurance Corporation (NDIC)","Central Bank of Nigeria (CBN)","Securities and Exchange Commission (SEC)","Federal Ministry of Finance"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The CBN formulates monetary and exchange rate policy, issues the naira as legal tender, regulates banks and acts as lender of last resort. Option D handles fiscal policy, meaning government revenue and spending, not monetary policy. Option C regulates the capital market, and option A insures deposits."}},{"itemId":"af144e5e-1b00-5506-8c84-0bb0072a2b1e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"df37e7ee-4c07-5526-9a07-a1f7c115e143","sourceKey":"bank:BUA202:PQ-031-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of EXPANSIONARY (easing) monetary policy?","options":["The central bank raises its benchmark interest rate","The central bank sells government securities to reduce the money supply","The central bank lowers its benchmark interest rate and reduces banks' reserve requirements","The central bank increases the reserve ratio for commercial banks"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Expansionary policy makes money cheaper and more available, for example by cutting the policy rate, lowering reserve requirements or injecting liquidity. Options A, B and D all reduce the money supply or make credit more expensive, which is contractionary (tightening) policy."}},{"itemId":"28275059-40fe-5a42-abf2-dadf27888984","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3a7ab29c-37a9-52d8-8fe3-07fade05cfe0","sourceKey":"bank:BUA202:PQ-031-b","parentItemId":null,"revision":1,"payload":{"prompt":"When a central bank adopts contractionary monetary policy, what is the most likely effect on businesses?","options":["Borrowing becomes more expensive, so firms may delay large investments or hiring","Consumer demand rises because credit is cheaper","Borrowing becomes cheaper, so firms expand rapidly","Firms' debt-servicing costs fall sharply"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Tightening raises interest rates and reduces credit, increasing the cost of capital, so businesses tend to postpone expansion and hiring. Options B, C and D describe the effects of expansionary policy, where cheaper credit encourages borrowing, lowers debt costs and boosts demand."}},{"itemId":"32ab46d4-1a87-56ed-a472-b637cc6f4aa3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ec48331f-9974-521a-a8b4-c10235d2814e","sourceKey":"bank:BUA202:PQ-031-c","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main goal of contractionary monetary policy?","options":["To stimulate a recessionary economy","To reduce high inflation and stabilise prices","To reduce unemployment by encouraging borrowing","To increase the money supply"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Contractionary policy cools an overheating economy by tightening credit, mainly to bring down high inflation. Options A and C are goals of expansionary policy, which tries to revive a sluggish economy and protect jobs. Option D is the opposite of what tightening does."}},{"itemId":"d7b4b9ff-99ac-51d6-884c-f16ad01218e9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"51baed75-58a2-526e-b0c9-ab3796b21a59","sourceKey":"bank:BUA202:PQ-032-a","parentItemId":null,"revision":1,"payload":{"prompt":"According to EFInA's Access to Financial Services in Nigeria (A2F) 2023 survey, roughly what share of Nigerian adults were formally financially included?","options":["About 40 percent","About 64 percent","About 26 percent","About 90 percent"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The A2F 2023 survey reported formal financial inclusion of about 64 percent of adults, up from 56 percent in 2020, driven largely by fintech, mobile money and agent networks. Option C is the share of adults who were completely financially excluded in that survey, not the share formally included. Options A and D do not match the survey's findings."}},{"itemId":"897054c8-7432-5a5d-886c-d3a455b543eb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"db958137-b95b-5196-8098-a5e890d2c238","sourceKey":"bank:BUA202:PQ-032-b","parentItemId":null,"revision":1,"payload":{"prompt":"According to EFInA's A2F 2023 survey, which part of Nigeria had the highest rates of financial exclusion?","options":["Lagos and other major southern cities","The South West","The northern regions, especially the North West and North East","The South South"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"In 2023, financial exclusion was highest in northern Nigeria, with the North West and North East well above the national average, where many rely on cash and informal savings like ajo or esusu. Options A, B and D point to southern areas, which had much lower exclusion rates."}},{"itemId":"6e93d29a-b108-510b-832b-78ca90927d64","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f28bdf67-59ad-512a-afde-c061f5a24650","sourceKey":"bank:BUA202:PQ-032-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following has been a major driver of the growth of formal financial inclusion in Nigeria in recent years (up to 2023)?","options":["The closure of microfinance banks across the country","A ban on digital payments in rural areas","Expansion of mobile money, fintech platforms and agent networks, supported by BVN and NIN identity verification","The replacement of bank accounts with unregistered thrift societies"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Fintech and mobile-money platforms, agent networks and trusted digital identity (BVN and NIN) have made it far easier for adults to open and use formal accounts. Options A and B would reduce access rather than expand it. Option D describes moving to the informal sector, which is the opposite of formal inclusion."}},{"itemId":"2805d122-6fe1-592a-8d90-16bd4f333e20","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e7922e94-0297-5ec9-ab41-1a94654ec2b0","sourceKey":"bank:BUA202:PQ-033-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the Nigerian capital market, which institution provides clearing, settlement and central depository services for trades executed on the Nigerian Exchange?","options":["Nigeria Deposit Insurance Corporation (NDIC)","Central Securities Clearing System (CSCS) Plc","Investments and Securities Tribunal (IST)","FMDQ Group"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"CSCS is the central securities depository that clears and settles transactions and keeps records of securities holdings. Option C is a specialised court that resolves capital market disputes. Option D runs platforms mainly for fixed income, currencies and derivatives, and option A insures bank deposits."}},{"itemId":"527c66f3-2faf-59fd-93cd-5cc23951e91d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7b09cd3a-e97e-5e22-8f2a-edf7ce347a99","sourceKey":"bank:BUA202:PQ-033-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which body in Nigeria is a specialised tribunal established to adjudicate capital market disputes quickly?","options":["NGX Regulation Limited (NGX RegCo)","Investments and Securities Tribunal (IST)","Central Securities Clearing System (CSCS)","Securities and Exchange Commission (SEC)"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The IST is a specialised judicial body for resolving capital market disputes. Option D is the apex regulator that makes and enforces rules, not a court. Option A enforces listing and trading rules on the exchange, and option C handles clearing and settlement."}},{"itemId":"e60fdd35-00a4-5e5d-b594-546b6662b9f0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2171ae73-1556-5bcb-a451-3ad9d49d5211","sourceKey":"bank:BUA202:PQ-033-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which institution is the apex regulator of the Nigerian capital market?","options":["Central Securities Clearing System (CSCS)","Securities and Exchange Commission (SEC)","Central Bank of Nigeria (CBN)","National Insurance Commission (NAICOM)"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The SEC is the chief regulator of the capital market, responsible for regulating and developing it and protecting investors. Option C regulates the banking system and monetary policy. Option D regulates insurance, and option A is a market infrastructure provider, not a regulator."}},{"itemId":"f40daa59-6c63-5b6c-b3a2-5bdf673165e0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"04664bdc-7773-5f01-8f7e-941dc34b026c","sourceKey":"bank:BUA202:PQ-033-d","parentItemId":null,"revision":1,"payload":{"prompt":"In 2021 the Nigerian Stock Exchange demutualised into the Nigerian Exchange Group. Which of its subsidiaries is the operating exchange where securities are traded?","options":["NASD OTC Securities Exchange","NGX Regulation Limited (NGX RegCo)","Nigerian Exchange Limited (NGX)","NGX Real Estate Limited (NGX RelCo)"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Nigerian Exchange Limited is the operating exchange that facilitates trading in equities, fixed income, exchange traded products and other instruments. Option B is the group's independent regulatory arm, and option D manages its real estate and physical facilities. Option A is a separate over-the-counter platform, not part of the NGX Group."}},{"itemId":"f5c5552b-e488-5f80-aad1-cdcf23b336fd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8cbff5c1-ac2b-5e76-bd06-0c1146e4ff37","sourceKey":"bank:BUA202:PQ-033-e","parentItemId":null,"revision":1,"payload":{"prompt":"Which capital market operators maintain records of share ownership and process corporate actions such as dividend payments?","options":["Trustees","Stockbrokers","Issuing houses","Registrars"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Registrars keep the register of shareholders and handle corporate actions like paying dividends. Option A acts as legal custodian of assets on behalf of bondholders and fund investors. Option B buys and sells securities for investors, and option C underwrites and packages new issues."}},{"itemId":"b1bad324-aae5-5b5b-804f-6d823f83fd37","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"79d9a4b2-8014-5211-af7d-ce9cb0f7cf45","sourceKey":"bank:BUA202:PQ-034-b","parentItemId":null,"revision":1,"payload":{"prompt":"An investor who buys shares (equities) in a company earns returns mainly through:","options":["Insurance payouts","Dividends and capital gains","Guaranteed government grants","Fixed periodic interest and repayment of principal at maturity"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"A shareholder becomes a part-owner and earns from a share of profits (dividends) and from selling shares at a higher price (capital gains). Option D describes how bonds and debentures pay their holders. Options A and C are not ways in which equity investments generate returns."}},{"itemId":"206affe4-6de0-54eb-b22b-5c6d22236b51","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"42a35b4d-3773-50ca-be91-5e1349e21f57","sourceKey":"bank:BUA202:PQ-034-c","parentItemId":null,"revision":1,"payload":{"prompt":"A pooled investment vehicle in which professionals invest money from many investors in a diversified portfolio, with each investor owning units, is called:","options":["A bond","A debenture","An ordinary share","A mutual fund"],"correctOption":3,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"A mutual fund pools money from many investors, is professionally managed, and gives even small investors instant diversification through units in the portfolio. Options A and B are debt instruments issued by a single borrower. Option C is ownership in one company, so it offers no built-in diversification."}},{"itemId":"7f20712a-eb57-53e5-b0a3-72185af5eedf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1ab0bc0a-00a8-54f9-97be-215d13c095f9","sourceKey":"bank:BUA202:PQ-034-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following generally carries the highest risk but also the highest potential long-term return?","options":["Bank savings deposits","Shares (equities)","Government bonds","Secured corporate bonds"],"correctOption":1,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Shares historically offer the highest potential returns but also the greatest risk, because their prices move with market conditions and dividends are not guaranteed. Options C and D pay fixed interest and return principal, making them safer with lower returns. Option A is the safest of all and offers the lowest return."}},{"itemId":"ff94029c-e685-5780-a10a-ca3fe4859353","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"aa1cc381-6437-56a6-a78e-319a999e8f05","sourceKey":"bank:BUA202:PQ-035-a","parentItemId":null,"revision":1,"payload":{"prompt":"A finance manager uses Net Present Value (NPV) and Internal Rate of Return (IRR) to decide which long-term project to fund. Which financial decision is this?","options":["Investment decision (capital budgeting)","Working capital decision","Financing decision","Dividend decision"],"correctOption":0,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"Choosing which long-term projects or assets to fund is the investment decision, also called capital budgeting, and NPV, IRR and payback period are its main tools. Option C is about how to raise the money, through debt or equity. Option D is about sharing profits, and option B concerns short-term assets and liabilities, not one of the three pillars."}},{"itemId":"5b45c695-bcf9-5b7f-8de8-58bc37fa7632","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0d9611ad-5454-55fa-8c48-f4ed910aebdf","sourceKey":"bank:BUA202:PQ-035-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company is deciding what mix of bank loans, bonds and new shares to use in raising funds for expansion. This is a:","options":["Investment decision","Marketing decision","Financing decision","Dividend decision"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The financing decision determines how to fund operations and growth by balancing debt and equity to keep the cost of capital low while managing risk. Option A decides what to invest in, not how to pay for it. Option D decides how much profit to pay out, and option B is outside financial decision-making."}},{"itemId":"fa3271e0-2d43-5f47-a6c4-afa4c89a17d4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a57e1c9e-7676-5136-be2f-c2daed9b183e","sourceKey":"bank:BUA202:PQ-035-c","parentItemId":null,"revision":1,"payload":{"prompt":"A profitable company must decide what proportion of its earnings to pay to shareholders and how much to reinvest. This is a:","options":["Investment decision","Financing decision","Dividend decision","Capital budgeting decision"],"correctOption":2,"section":"The Nigerian Banking and Financial System and Securities Market","explanation":"The dividend decision balances paying out profits to shareholders against retaining earnings for future growth. Option B concerns the mix of debt and equity used to raise funds. Options A and D are the same pillar under two names, deciding which long-term projects to fund."}},{"itemId":"7ce5dd6d-643a-50d4-a9d9-52cd3b42dc3f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8d4eb5f5-29f9-53a9-b3b9-1dc1d0cfd7f4","sourceKey":"bank:BUA202:PQ-036-a","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between a job description and a job specification?","options":["A job description lists the duties and responsibilities of a job, while a job specification lists the qualifications and skills needed to do it","A job description lists the qualifications needed, while a job specification lists the duties of the job","Both terms mean the same thing","A job description sets the salary, while a job specification sets working hours"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Job analysis produces two documents: the job description, which sets out what the job involves, and the job specification, which sets out what kind of person is needed to do it. Option B swaps the two. Option C ignores the distinction, and option D confuses them with terms of employment."}},{"itemId":"b48c5171-0a39-51db-900f-15a2aa321db5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b3410ef9-c099-5665-ad71-65776c873692","sourceKey":"bank:BUA202:PQ-036-b","parentItemId":null,"revision":1,"payload":{"prompt":"HR forecasting shows that a firm's demand for workers will exceed the available supply. Which response is appropriate?","options":["Freeze hiring and not replace employees who leave","Hire more workers, use overtime or subcontract some work","Eliminate existing positions","Offer early retirement packages"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"When demand for labour exceeds supply, the firm must add capacity through hiring, overtime, subcontracting or labour-saving initiatives. Options A, C and D reduce the workforce, which is how firms respond when supply exceeds demand."}},{"itemId":"60f98f83-fff9-5552-af49-5b7849e4f59c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d6ee63c4-3206-5c52-a4d4-5495a3f8f0ad","sourceKey":"bank:BUA202:PQ-036-c","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic human resource planning begins with which activity?","options":["Analysing the organisation's mission, objectives and strategy to determine what kind of people it needs","Setting the annual dividend","Running employee orientation","Conducting exit interviews"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"HR planning starts from the organisation's mission, objectives and strategy, because the people needed depend on where the business is going. Options C and D are HR activities that come much later in the employment cycle. Option B is a financial decision, not part of HR planning."}},{"itemId":"d240159a-d02d-5729-8c4f-934ceacb4d2f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"02e00d55-2e71-5378-998d-b273baafedd5","sourceKey":"bank:BUA202:PQ-036-d","parentItemId":null,"revision":1,"payload":{"prompt":"The process of identifying the tasks, responsibilities, skills, knowledge and abilities a job requires is called:","options":["Performance appraisal","Job analysis","Orientation","Job rotation"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Job analysis systematically studies a job to determine what it involves and what it takes to do it, producing the job description and job specification. Option D moves employees between jobs for development. Option A evaluates how well people perform, and option C introduces new hires to the organisation."}},{"itemId":"af94cab5-ec22-5a74-9f5c-e660dbdf0c5e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a7c2a572-29e9-5316-b76c-e3fcf2f1cd28","sourceKey":"bank:BUA202:PQ-037-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of internal recruiting over external recruiting?","options":["It is the only option for filling entry-level positions","It brings in fresh ideas and perspectives from outside the company","It motivates existing staff by showing chances for promotion, and the candidate's performance is already known","It never creates another vacancy"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Promoting from within signals upward mobility, is usually cheaper, and reduces risk because the organisation already knows the candidate's track record. Option B is an advantage of external recruiting. Option D is false, since moving someone internally leaves their old job empty, and option A is also false because entry-level jobs usually need external recruiting."}},{"itemId":"affeb0ce-9254-536c-ae0f-771ae2bd6352","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"226f2854-33e9-5db1-ae01-0d90d744863c","sourceKey":"bank:BUA202:PQ-037-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a typical disadvantage of external recruiting?","options":["It reduces the inflow of new ideas","It limits the organisation to the skills it already has","It is usually more costly and risky because the candidate is relatively unknown to the organisation","It always demotivates new employees"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"External recruitment involves advertising and screening costs, and the employer has less information about how an outsider will perform. Options A and B are drawbacks of internal recruiting, which keeps the same talent pool. Option D has no basis."}},{"itemId":"3b0fcf42-b7e6-5390-8cf6-12602fa2703f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a12d01f7-be41-5b1b-840e-4181ccb9032c","sourceKey":"bank:BUA202:PQ-037-c","parentItemId":null,"revision":1,"payload":{"prompt":"During selection, an employer contacts a candidate's former employers to confirm claims about the candidate's education and experience. This step is called:","options":["Performance appraisal","Reference checking","Orientation","Job analysis"],"correctOption":1,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Reference checks verify what candidates say about their background before a final hiring decision. Option C happens after someone has been hired. Option D studies the job rather than the candidate, and option A evaluates existing employees."}},{"itemId":"08a18f2a-1e34-5b9b-b8f8-99b993afc9f0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"42adabaf-834f-5c9b-aceb-02b3e30c0e88","sourceKey":"bank:BUA202:PQ-038-a","parentItemId":null,"revision":1,"payload":{"prompt":"The process of introducing new employees to the organisation's history, policies and culture, and explaining pay, benefits and how performance will be assessed, is called:","options":["Orientation (onboarding)","Job analysis","Succession planning","Off-the-job training"],"correctOption":0,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Orientation welcomes new hires and explains how the organisation works and what is expected of them. Option D develops specific skills away from the workplace for existing employees. Option C prepares people to fill important future positions, and option B studies the requirements of a job."}},{"itemId":"00eda249-b403-5338-abf3-312992b7a628","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8432c15e-d13d-5b69-b100-0cd93923b903","sourceKey":"bank:BUA202:PQ-038-b","parentItemId":null,"revision":1,"payload":{"prompt":"A new machine operator learns by working alongside an experienced colleague during normal working hours. This is an example of:","options":["Performance appraisal","External recruitment","On-the-job training","Off-the-job training"],"correctOption":2,"section":"HR Planning, Recruitment, Selection and Development","explanation":"On-the-job training is hands-on learning while doing the actual work, often with guidance from experienced staff. Option D takes place away from daily work, for example in classrooms or workshops. Options A and B are about hiring and evaluating employees, not training them."}},{"itemId":"a624d987-72bc-576a-9019-cec9a4e7634e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"965e15ce-3bc1-5e48-8e4f-0da4e318bf4f","sourceKey":"bank:BUA202:PQ-038-c","parentItemId":null,"revision":1,"payload":{"prompt":"Why do organisations continue training employees after orientation?","options":["Training is required only for employees who are about to be dismissed","Orientation already provides every skill an employee will ever need","Training replaces the need for recruitment","Employees rarely arrive with every skill they will need, and job requirements change over time"],"correctOption":3,"section":"HR Planning, Recruitment, Selection and Development","explanation":"Ongoing training and development fill skill gaps and keep employees up to date as jobs and technology change. Options A and B are false, since training serves all employees and orientation is only an introduction. Option C is wrong because training develops staff the firm already has and does not remove the need to hire."}},{"itemId":"142c02c0-d5c1-5683-8bb8-d18065b31c14","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"57460593-5eec-567b-a3e8-cfbf4b578df5","sourceKey":"bank:BUA202:PQ-039-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the Competing Values Framework, which culture type combines an internal focus with flexibility and emphasises teamwork, relationships and mentoring?","options":["Market culture","Clan culture","Adhocracy culture","Hierarchy culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Clan culture is internally focused and flexible, like an extended family built on collaboration and mentoring. Option C is also flexible but externally focused on innovation and risk-taking. Options A and D emphasise stability and control, with market culture focused on results and hierarchy culture on processes and efficiency."}},{"itemId":"8d6cce08-c2f9-51eb-9154-00ad29399b48","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"532ee5d1-995d-5235-aac8-4d68b14a8ea8","sourceKey":"bank:BUA202:PQ-039-b","parentItemId":null,"revision":1,"payload":{"prompt":"A fast-moving software start-up that values innovation, risk-taking and entrepreneurship most closely fits which culture type in the Competing Values Framework?","options":["Market culture","Adhocracy culture","Hierarchy culture","Clan culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Adhocracy culture is externally focused and flexible, prizing creativity, experimentation and entrepreneurship. Option C values stability, rules and careful processes, which is the opposite. Option D focuses on internal relationships, and option A focuses on competing and delivering results through control."}},{"itemId":"e3b79e89-d3df-518e-8788-ca8f926e88b0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cd6e3abb-6f66-5b23-98ee-075e6c76c5e7","sourceKey":"bank:BUA202:PQ-039-c","parentItemId":null,"revision":1,"payload":{"prompt":"A government agency that emphasises formal procedures, efficiency, cost control and careful, rule-based decision-making best illustrates which culture type?","options":["Clan culture","Hierarchy culture","Adhocracy culture","Market culture"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Hierarchy culture combines an internal focus with stability and control, giving a structured, procedure-driven workplace. Option C values innovation and flexibility. Option A values relationships and teamwork, and option D, though also control-oriented, looks outward to competition and results."}},{"itemId":"29fdd811-43de-5e61-a1d2-0e93176af590","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c10fba37-e2fc-5f4d-9e84-2ab93b22bcae","sourceKey":"bank:BUA202:PQ-039-d","parentItemId":null,"revision":1,"payload":{"prompt":"The two dimensions used in the Competing Values Framework to classify organisational culture are:","options":["Internal versus external focus, and flexibility versus stability (control)","Tall versus flat structure, and centralised versus decentralised authority","Profit versus non-profit, and public versus private ownership","Strong versus weak culture, and formal versus informal structure"],"correctOption":0,"section":"Organisational Culture, Power and Politics","explanation":"The framework crosses an internal-external focus axis with a flexibility-stability axis to produce the clan, adhocracy, market and hierarchy cultures. Options B, C and D describe other ways of classifying organisations, not the axes of this framework."}},{"itemId":"34f1c953-9bca-5259-b49c-94629d198a92","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"584baf3c-e1c6-5061-a46d-e011cea88b96","sourceKey":"bank:BUA202:PQ-040-a","parentItemId":null,"revision":1,"payload":{"prompt":"Colleagues follow a manager's advice because she is the only person in the firm who fully understands its new accounting software. Which base of power does she have?","options":["Coercive power","Expert power","Legitimate power","Referent power"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Expert power comes from having specialised knowledge or skills that others need. Option C comes from holding a formal position. Option D comes from being admired or liked so that others want to identify with the person, and option A comes from the ability to punish."}},{"itemId":"5232eb95-1c39-5566-a538-f6a6a0055bcd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f952ee1c-593e-526f-a54e-ed93fbda42f1","sourceKey":"bank:BUA202:PQ-040-b","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor gets compliance by threatening to deny workers overtime or issue queries. Which base of power is being used?","options":["Expert power","Referent power","Coercive power","Reward power"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Coercive power rests on the belief that a person can punish or withhold something valued. Option D is the opposite, based on granting desired outcomes like bonuses or recognition. Options A and B rest on knowledge and on personal attraction, not on threats."}},{"itemId":"a828a4df-ce56-5bc3-ae7c-d7061837fe53","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"73e86855-58dc-5dac-b19e-6be5b1ac6043","sourceKey":"bank:BUA202:PQ-040-c","parentItemId":null,"revision":1,"payload":{"prompt":"Employees accept a new head of department's instructions simply because of the official position she has been appointed to. This is:","options":["Expert power","Reward power","Referent power","Legitimate power"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"Legitimate power is based on the belief that a person has the right to influence others because of their position or role. Option C comes from personal admiration, and option A from specialised knowledge. Option B depends on the ability to give rewards, which is not what makes employees follow her here."}},{"itemId":"69877bab-90f5-5932-9c6f-2c97c84a1dd7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5edd6db7-0b09-5b4f-a749-a1b63becfc1d","sourceKey":"bank:BUA202:PQ-040-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which base of power is based on others admiring a person and wanting to identify with or be accepted by them?","options":["Reward power","Referent power","Coercive power","Legitimate power"],"correctOption":1,"section":"Organisational Culture, Power and Politics","explanation":"Referent power flows from personal charisma and the desire of others to associate with the person. Option D comes from formal authority. Options A and C come from the ability to punish or to reward."}},{"itemId":"34b6c8b1-d69a-5622-b28c-dd2525528e95","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d0522358-a094-56fc-ab2c-514d5cd7cd2d","sourceKey":"bank:BUA202:PQ-041-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes the informal organisation from the formal organisation?","options":["The informal organisation consists only of written policies and procedures","The informal organisation is shown on the organisation chart, while the formal organisation is not","The informal organisation is easier for management to control than the formal organisation","The informal organisation is the unofficial network of relationships that emerges naturally, while the formal organisation is the structure deliberately designed by management"],"correctOption":3,"section":"Organisational Culture, Power and Politics","explanation":"The formal organisation is the official design of roles, reporting lines and channels, while the informal organisation is the network of personal relationships that grows as people interact. Options A and B describe features of the formal organisation. Option C is wrong because the informal organisation is harder, not easier, to control."}},{"itemId":"d4ec7d43-a64d-5e12-8808-73e7662272f7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"26df8c38-fa19-510b-89ab-e6c4853d75c2","sourceKey":"bank:BUA202:PQ-041-b","parentItemId":null,"revision":1,"payload":{"prompt":"A department's official reporting lines run through its manager, but staff actually turn to a long-serving colleague for advice and news. This colleague's influence is part of the:","options":["Organisation chart","Chain of command","Informal organisation","Formal organisation"],"correctOption":2,"section":"Organisational Culture, Power and Politics","explanation":"Influence that arises from personal relationships and trust rather than official position belongs to the informal organisation, which shows how the organisation actually works. Options A, B and D all refer to the official, designed structure that shows how the organisation is supposed to work."}},{"itemId":"3adf1981-ca8a-5b38-9197-c55771c6fbea","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b478093c-6747-59cf-82fe-0d8162b55d4c","sourceKey":"bank:BUA202:PQ-042-a","parentItemId":null,"revision":1,"payload":{"prompt":"Business ethics is best defined as:","options":["The laws that businesses must obey to avoid prosecution","The strategies firms use to maximise profit at any cost","The rules of accounting for preparing financial statements","The moral principles and standards that guide business behaviour and determine what is right or wrong in business activities"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Business ethics concerns moral principles about right and wrong in business, going beyond simple legal compliance to honesty, fairness and doing no harm. Option A is too narrow, since something can be legal yet still unethical. Option B contradicts ethics, and option C describes accounting standards."}},{"itemId":"4c4b2b73-9775-50b7-bc2e-0350d52cf02c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1213b37b-d173-560a-a416-759705567502","sourceKey":"bank:BUA202:PQ-042-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manager must choose between laying off ten workers to save the company or keeping them and risking the jobs of everyone; every option harms someone. This situation is best described as:","options":["A legal requirement","A programmed decision","An ethical dilemma","A conflict of loyalty only"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical dilemma is a situation where it is hard to decide because the right course is unclear or every option carries a negative consequence for someone. Option B is a routine decision handled by rules, which this is not. Option D is narrower, describing being torn between an employer and a friend or relative, and option A is wrong because no law dictates the choice here."}},{"itemId":"8ccbb74a-f622-521c-bbcc-5f17a2add17c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7ad59bf9-7925-520e-8f69-04b0b87b2538","sourceKey":"bank:BUA202:PQ-043-a","parentItemId":null,"revision":1,"payload":{"prompt":"A purchasing manager steers company contracts to a firm owned by his brother, even though better offers exist. Which category of ethical issue does this represent?","options":["Honesty in advertising","Conflict of interest","Whistle-blowing","Conflict of loyalty"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A conflict of interest arises when personal interests interfere with the employer's or stakeholders' best interests, as with favouring a relative's company. Option C is exposing wrongdoing, which is the opposite of what is happening. Option D involves being torn between duties to an employer and to a friend, without personal gain, and option A concerns deceiving customers."}},{"itemId":"1f4b7555-ff67-5f25-b2d9-7f2858466e6a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e71b42de-903b-5462-a267-a92a8ba33e55","sourceKey":"bank:BUA202:PQ-043-b","parentItemId":null,"revision":1,"payload":{"prompt":"An employee reports her company's illegal dumping of toxic waste to the regulators, knowing this could damage her career. This act is called:","options":["Insider trading","Bribery","Whistle-blowing","Conflict of interest"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Whistle-blowing is exposing illegal or unethical behaviour within an organisation, often at personal or career risk to the person who speaks up. Option A is trading on non-public information for personal gain. Options B and D are forms of misconduct, not acts of exposing it."}},{"itemId":"2c6710ac-ff97-527a-9385-14f3b8e05353","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1c122c82-3dd4-58af-ab66-b3ebd63cec7c","sourceKey":"bank:BUA202:PQ-043-c","parentItemId":null,"revision":1,"payload":{"prompt":"A company director buys shares in his firm just before a profitable merger is announced, using information not yet available to the public. This is:","options":["A conflict of loyalty","Corporate philanthropy","Insider trading","Whistle-blowing"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Insider trading uses non-public information to gain in the market, and it is both unethical and illegal. Option D means exposing wrongdoing. Option A is being torn between an employer and a friend, and option B is charitable giving by businesses."}},{"itemId":"04958bae-a0e0-5f89-84b2-f152f355b2e0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5f8a3a17-dc84-5211-980a-e98fbc4c08dc","sourceKey":"bank:BUA202:PQ-043-d","parentItemId":null,"revision":1,"payload":{"prompt":"When judging whether something of value offered by a supplier is an acceptable gift or a bribe, which factors matter most?","options":["Only the receiver's job title","Only whether the gift is wrapped","Its cost, timing and type, and the relationship between giver and receiver","Whether the gift arrives by post or in person"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A gift becomes a bribe when it is meant to influence a decision, so the value, the timing (for example, during a contract decision), the type of gift and the relationship between the parties all matter. Options A, B and D focus on trivial details that do not reveal whether the gift is meant to influence a decision."}},{"itemId":"de94aba9-c87e-5815-8814-5904eb4f7280","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2b4c7e7b-01aa-59d7-86d9-36b4fa2a69ad","sourceKey":"bank:BUA202:PQ-044-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the four areas of corporate social responsibility (economic, legal, ethical and philanthropic), donating to community projects is an example of which responsibility?","options":["Philanthropic responsibility","Ethical responsibility","Legal responsibility","Economic responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Philanthropic responsibility is voluntary giving back to society, such as donations and community projects. Option D is about making profits ethically, and option C is about obeying the law. Option B is about doing what is morally right beyond the law, but charitable giving specifically is the philanthropic area."}},{"itemId":"d63a99cd-8623-5c49-bf9a-b4f4820a09b3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"79df800e-4aca-5884-ad96-d42fbd145126","sourceKey":"bank:BUA202:PQ-044-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes management's role under corporate social responsibility?","options":["To focus on the community while ignoring profitability","To satisfy customers only, ignoring employees","To balance the often-competing claims of owners, employees, customers and the community","To favour shareholders at the expense of all other groups"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A socially responsible company weighs the legitimate claims of all its stakeholders rather than serving one group at the expense of others. Options A, B and D each favour a single group, which is exactly what balanced CSR tries to avoid; even option A fails because a business must remain profitable to serve anyone."}},{"itemId":"35228542-8e54-54e3-960d-8293db1fc401","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"89c798bc-aec9-5128-9e52-c74bed0ce651","sourceKey":"bank:BUA202:PQ-045-a","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational change is best described as:","options":["The systematic process of planning, implementing, monitoring and sustaining changes in an organisation","Any significant alteration in an organisation's structure, operations, culture, technology, strategies or processes, moving it from its current state to a desired future state","The replacement of an organisation's top management by a new board of directors","The routine day-to-day running of an organisation's existing operations"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Organisational change is the alteration itself - in structure, culture, technology, strategy or processes - that moves a firm from where it is to where it wants to be. Option A defines change management, which is the process of handling a change rather than the change itself. Option C is only one possible example of change, and option D describes keeping things as they are."}},{"itemId":"d3359bfe-d3a7-55cc-bf46-9b1a389185dc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c4113668-352d-5028-9100-fdad74130783","sourceKey":"bank:BUA202:PQ-045-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an objective organisations pursue when they introduce change?","options":["Remaining competitive and improving customer satisfaction","Adapting to technological developments","Improving efficiency and productivity","Increasing operating costs"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Firms change in order to become more efficient, cut costs, adapt to technology, satisfy customers and stay competitive, so raising operating costs is not a goal of change. Options C, B and A are all genuine objectives of change; any cost increase during a change is a side effect to manage, not a target."}},{"itemId":"6afc8df2-0e7b-5880-bdc2-7fdd0ff51ec8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c5690c4f-8b90-5f49-a5bd-df52ff018dd0","sourceKey":"bank:BUA202:PQ-045-c","parentItemId":null,"revision":1,"payload":{"prompt":"A company merges two departments and changes its reporting lines so that branch managers now report to regional heads. This is mainly an example of which type of organisational change?","options":["Technological change","Personnel change","Cultural change","Structural change"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Structural change alters how an organisation is arranged - its departments, reporting relationships and responsibilities - which is exactly what merging departments and changing reporting lines does. Option C concerns values and attitudes, option B concerns people moves such as recruitment, promotion or downsizing, and option A concerns new equipment or systems."}},{"itemId":"a5959f79-e9c1-5eb1-af40-d89fd1a4923f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"beb1c415-f556-56c4-b177-1a05d7811bae","sourceKey":"bank:BUA202:PQ-046-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an EXTERNAL driver of organisational change?","options":["The appointment of a new managing director","Expansion of the organisation into more branches","Poor employee performance","New tax laws introduced by the government"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"External drivers come from outside the organisation, and government policies such as tax reforms, labour laws and environmental rules force firms to adjust. Options A, C and B all start inside the organisation - new leadership, weak performance and growth - so they are internal drivers."}},{"itemId":"c19e707e-06ec-5861-8f21-c3b780ec175f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"42eb8954-c0af-55d6-8129-653e07b211c0","sourceKey":"bank:BUA202:PQ-046-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an INTERNAL driver of organisational change?","options":["Exchange-rate fluctuations in the economy","Changes in customers' tastes","Financial problems that force the firm to restructure to cut costs","Competitors launching better products"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Internal drivers originate within the organisation, and a firm's own financial problems are a classic reason to restructure and cut costs. Options D, B and A - competition, customer tastes and economic conditions - all come from the outside environment, so they are external drivers."}},{"itemId":"5c4a015a-f5e9-5c9c-a6ae-ba1e42c722c1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bc3d1791-f1ce-5b4d-b04d-328f12e5ddae","sourceKey":"bank:BUA202:PQ-046-c","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank introduces mobile banking because rival banks already offer it and more customers now prefer banking on their phones. This change is driven mainly by:","options":["Internal forces - the growth of the bank's workforce","Internal forces - poor employee performance","Internal forces - the personal preferences of a new managing director","External forces - technology, competition and customer preferences"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"New technology, rivals' moves and shifting customer preferences all come from the bank's environment, so this is change pushed by external forces. Options B, C and A name internal drivers that the scenario does not mention."}},{"itemId":"a1297241-dae0-5959-a2b1-d8db9421a2e5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ee7fa900-9795-54bc-825c-d747883bf41f","sourceKey":"bank:BUA202:PQ-047-a","parentItemId":null,"revision":1,"payload":{"prompt":"Resistance to change refers to:","options":["The forces in the external environment that push an organisation to change","Management's refusal to listen to employee complaints","The stage at which a new change is made permanent in an organisation","The unwillingness of employees or organisations to accept new ideas, methods, policies or procedures"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Resistance to change is the reluctance of people, or of the organisation as a whole, to accept new ideas, methods or procedures, often because they fear uncertainty. Option C describes refreezing, option B is a leadership failure rather than resistance to change, and option A describes external drivers of change."}},{"itemId":"db43b295-1a62-591c-ab85-84b0ed246323","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"66ee5f2a-a248-517c-a895-c9b89202a099","sourceKey":"bank:BUA202:PQ-047-b","parentItemId":null,"revision":1,"payload":{"prompt":"Workers in a factory oppose the installation of automated machines because they worry the machines will replace them. Which cause of resistance does this mainly show?","options":["Habit","Fear of job loss","Lack of trust in management","Increased workload"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"The workers' worry is that automation will take their jobs, which is fear of job loss, one of the most common causes of resistance. Option A is about comfort with old routines, option D is about having to work harder, and option C is about doubting management's intentions - none of these is the concern described."}},{"itemId":"5397ba94-716c-536e-8a05-b3f0c1bf763f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8a9c52f9-8b24-50fe-9987-93bdf8280599","sourceKey":"bank:BUA202:PQ-047-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a likely EFFECT of strong employee resistance to change?","options":["Faster implementation of the change","An immediate fall in labour costs","Improved teamwork and morale","Delays in implementing the change and lower productivity"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"When employees resist, the change takes longer to put in place and output often falls, along with dissatisfaction, poor teamwork and even industrial disputes. Options A and C describe the opposite of what resistance causes, and option B is not a result of resistance at all."}},{"itemId":"ded15cbf-58fb-5247-af89-41fd3243996d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"16d685e1-ec74-533a-9448-88ec3021b678","sourceKey":"bank:BUA202:PQ-048-a","parentItemId":null,"revision":1,"payload":{"prompt":"Staff in a firm resist new accounting software because they fear they cannot use it. Which strategy most directly addresses this cause of resistance?","options":["Threatening employees with dismissal","Rewarding only the managers who approved the change","Delaying any communication about the change until the software is installed","Training employees on the new software"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"The resistance comes from a lack of skills, so training gives staff the ability and confidence to use the system. Option A uses fear and usually deepens resistance, option C creates uncertainty, and option B does nothing for the staff who actually have to use the software."}},{"itemId":"6dc60d00-f4b6-5a6c-b095-a51f93309a87","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"83496933-8be0-5303-8828-1089d300d150","sourceKey":"bank:BUA202:PQ-048-b","parentItemId":null,"revision":1,"payload":{"prompt":"Allowing employees to contribute ideas and take part in planning a change mainly reduces resistance by:","options":["Giving them a sense of ownership and commitment to the change","Removing the need to communicate with them","Guaranteeing that no employee will be affected by the change","Making the change happen without any leadership"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Participation makes employees feel the change is partly theirs, so they are more committed to making it work. Option B is wrong because participation itself depends on communication, option C promises something no change can guarantee, and option D ignores that strong leadership is still needed."}},{"itemId":"ed9bba8f-ad8d-532b-9e4e-fff83a5ec08b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"36e2c3eb-5484-55dd-8ba0-a1d298682d25","sourceKey":"bank:BUA202:PQ-048-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following would INCREASE rather than reduce resistance to change?","options":["Announcing the change suddenly without explaining why it is needed","Offering counselling to employees who are anxious about the change","Recognising and rewarding employees who support the change","Explaining clearly why the change is necessary"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"People resist what they do not understand, so springing a change on them with no explanation raises fear and opposition. Options D, B and C - communication, counselling and rewards - are standard ways of reducing resistance."}},{"itemId":"132115bf-7150-58e9-9740-2d00a71feb1e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a16bd695-1954-529d-8d5d-fc3d7965d4f8","sourceKey":"bank:BUA202:PQ-049-a","parentItemId":null,"revision":1,"payload":{"prompt":"Change management is best defined as:","options":["The systematic process of planning, implementing, monitoring and sustaining organisational change","The resistance employees show towards new policies","Any alteration in an organisation's structure, technology, people or processes","The external factors that force organisations to change"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Change management is about how a change is handled - planning it, carrying it out, checking it and making it stick - so it is introduced smoothly with minimal disruption. Option C defines organisational change itself, option B defines resistance to change, and option D describes external drivers."}},{"itemId":"c520e990-2b6b-52c4-8e4e-d53d3784ca0e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bc9fe981-19fa-5eba-9e5b-6c3140b4a14b","sourceKey":"bank:BUA202:PQ-049-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes organisational change from change management?","options":["Organisational change is the process of managing change; change management is the change itself","Organisational change is always planned, while change management may be unplanned","Organisational change is the actual change (what changes); change management is the process of managing how it is implemented","Both terms mean exactly the same thing"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Organisational change is the outcome - what actually changes - while change management is the planned, systematic process of implementing it. Option A reverses the two ideas, option D ignores the difference, and option B is backwards too, since organisational change may be planned or unplanned while change management is usually planned."}},{"itemId":"cf02865e-6b11-58b5-8c55-79593b7e3964","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"12a0995b-8b8e-5319-808e-1f45f6eae907","sourceKey":"bank:BUA202:PQ-049-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of change management?","options":["It ensures the organisation will never need to change again","It reduces employee resistance and minimises disruption during change","It guarantees that no employee will ever resist change","It removes the need for leadership during change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Good change management lowers resistance, improves communication and keeps disruption to a minimum, which makes successful implementation more likely. Option C overstates it, since resistance can be reduced but not eliminated, option D is wrong because leadership is central to managing change, and option A ignores that change is continuous."}},{"itemId":"35189eab-5b32-5852-8b29-3ff31984ff85","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"820c1a07-4e6c-5220-b39d-0f95b29f28aa","sourceKey":"bank:BUA202:PQ-050-a","parentItemId":null,"revision":1,"payload":{"prompt":"What is the first step in the change management process?","options":["Reinforce the change","Monitor progress","Implement the change","Identify the need for change"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Every change process begins by working out why change is necessary; planning, communicating and implementing all depend on that. Option C comes in the middle of the process, while options A and B come near the end, after the change has been introduced."}},{"itemId":"017485c8-2fcf-5512-b9ca-18cb34c14616","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c4c75df8-d557-5056-8c50-333e8c4ccc09","sourceKey":"bank:BUA202:PQ-050-b","parentItemId":null,"revision":1,"payload":{"prompt":"In the change management process, which step comes after planning the change and before implementing it?","options":["Monitoring progress","Communicating the change to employees, explaining its reasons and benefits","Reinforcing the change","Identifying the need for change"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"The usual order is identify the need, plan, communicate, implement, monitor, then reinforce, so communication sits between planning and implementation. Option D is the very first step, and options A and C only happen after the change has been introduced."}},{"itemId":"29917715-68ce-5242-92df-c6fee2ece4db","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9e87582f-51ab-5089-b104-18304f14bd73","sourceKey":"bank:BUA202:PQ-050-c","parentItemId":null,"revision":1,"payload":{"prompt":"Why is the monitoring (evaluation) stage important in the change management process?","options":["It identifies why change is needed in the first place","It checks whether the objectives of the change are being achieved so corrections can be made","It is used to announce the change to employees for the first time","It is the stage at which the new policies or systems are first introduced"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Monitoring compares results with the objectives of the change, showing whether it is working and what needs adjusting. Option A describes identifying the need, option D describes implementation, and option C describes communicating the change."}},{"itemId":"9e71992d-55df-58d8-b23f-1237d2f125d4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"177f7d28-e214-5310-a668-f659b6aa2f6b","sourceKey":"bank:BUA202:PQ-051-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company plans to replace manual attendance registers with fingerprint machines. Management holds meetings to explain why the old system is inefficient and why a change is needed. Under Lewin's model, this activity belongs to which stage?","options":["Unfreezing","Changing (movement)","Refreezing","Anchoring"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Unfreezing prepares people for change by creating awareness, explaining why the old way must go and reducing resistance - exactly what the meetings do. Option B is when the fingerprint machines are actually installed and staff are trained, option C is when the new system is made permanent, and option D is a Kotter step, not a Lewin stage."}},{"itemId":"06ee1648-7e86-5b22-a5a5-5b547886e2c5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e37011df-586c-5a48-8555-610cb7164c1e","sourceKey":"bank:BUA202:PQ-051-c","parentItemId":null,"revision":1,"payload":{"prompt":"After a company installs fingerprint attendance machines, management issues a new attendance policy and rewards staff who comply so that the new system becomes the normal way of working. Under Lewin's model, this is:","options":["Unfreezing","Creating a sense of urgency","Refreezing","Changing (movement)"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Refreezing locks in the change through new policies, rewards and reinforcement of the new behaviour so people do not drift back to old habits. Option A happens before the change, option D is the actual installation and training, and option B is the first step of Kotter's model."}},{"itemId":"2f3a20f3-4df8-5a78-8a3f-1edfedc2455a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1388655b-710a-5533-b67c-a3634a535170","sourceKey":"bank:BUA202:PQ-052-a","parentItemId":null,"revision":1,"payload":{"prompt":"What is the first step in Kotter's eight-step change model?","options":["Anchor the change in the culture","Create a sense of urgency","Build a guiding coalition","Develop a vision"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Kotter starts by showing people why change is needed now, because without urgency people stay comfortable with the status quo. Options C and D are steps two and three, and option A is the final step."}},{"itemId":"fbcfc0fc-294d-53dc-ad14-d183e942287a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"3221c6c4-a9dd-5fbb-ac3b-3d183c525615","sourceKey":"bank:BUA202:PQ-052-b","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter's model, forming a team of influential people with enough power and credibility to lead the change is called:","options":["Creating short-term wins","Removing obstacles","Building a guiding coalition","Communicating the vision"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"The guiding coalition is the team that leads and champions the change, and it is Kotter's second step. Option A is about celebrating early successes, option B is about clearing barriers, and option D is about explaining the vision to everyone affected."}},{"itemId":"f34f0080-8e8d-52c6-875a-46c6530278a4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"13d2ce91-2c8f-5d17-b7ea-bbc28cb21c7e","sourceKey":"bank:BUA202:PQ-052-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which option shows the correct order of these steps in Kotter's model?","options":["Create short-term wins -> Develop a vision -> Remove obstacles -> Communicate the vision","Develop a vision -> Communicate the vision -> Remove obstacles -> Create short-term wins","Remove obstacles -> Create short-term wins -> Develop a vision -> Communicate the vision","Communicate the vision -> Develop a vision -> Create short-term wins -> Remove obstacles"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Kotter's steps three to six are develop a vision, communicate it, remove obstacles, then create short-term wins - you cannot share a vision before creating it, or celebrate wins before clearing the way for them. Options D, A and C all scramble this logical sequence."}},{"itemId":"6b579790-a351-512f-87cd-24a370ca9864","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6690dff8-96e5-5683-a7bc-9b72089a621a","sourceKey":"bank:BUA202:PQ-052-d","parentItemId":null,"revision":1,"payload":{"prompt":"Kotter's final step, 'anchor the change', means:","options":["Forming a team to lead the change","Showing employees why the change is urgent","Celebrating the first visible successes of the change","Making the new practices part of the organisation's culture so they last"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Anchoring builds the new ways of working into the organisation's culture, so the change survives after the leaders who drove it move on. Option C describes short-term wins, option B describes creating urgency, and option A describes building a guiding coalition."}},{"itemId":"4380dfa9-0994-5866-b3bb-898c993d76b7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1fa4a537-c4ea-58f7-bb48-724993565295","sourceKey":"bank:BUA202:PQ-053-b","parentItemId":null,"revision":1,"payload":{"prompt":"Kotter's final step, anchoring the change in the organisation's culture, corresponds most closely to which stage of Lewin's model?","options":["Refreezing","Changing (movement)","None; Lewin's model has no stage for making change permanent","Unfreezing"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Refreezing and anchoring both make the new way of working permanent, so Kotter's last step matches Lewin's last stage. Option D matches Kotter's early preparation steps, option B matches the middle steps where change is carried out, and option C is wrong because refreezing is exactly that stage."}},{"itemId":"3391abe0-640c-50d7-ac1a-037ad11e34a6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ebcf43e9-96cd-50dc-8814-83b24f8c70c9","sourceKey":"bank:BUA202:PQ-053-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a disadvantage of Kotter's model when compared with Lewin's?","options":["It has no step for communicating with employees","It assumes change has a clear end after only three stages","It is more time-consuming and requires strong leadership to carry through","It is too simple for large, complex organisations"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Because Kotter's model has eight detailed steps, it takes longer and depends on strong, committed leaders to drive it. Option D and option B are criticisms of Lewin's simpler model, and option A is wrong because communicating the vision is one of Kotter's steps."}},{"itemId":"f8d059fc-e4a2-5089-b068-89cf460ca7a3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"78a4f6f6-6ea1-5cd7-b248-c2b0f13ec2a1","sourceKey":"bank:BUA202:PQ-054-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT usually a challenge to managing change in Nigerian organisations?","options":["Easy access to cheap, long-term funding","Poor infrastructure such as unreliable power supply","Frequent changes in government policies","Economic instability and high inflation"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Limited funding is one of the challenges Nigerian firms face during change, so easy access to cheap long-term funds is not a challenge. Options B, D and C - poor infrastructure, economic instability and unstable policies - are commonly cited obstacles, along with corruption, inadequate technology and inadequate training."}},{"itemId":"808e35a2-fc49-508a-9464-ab7a984a24d4","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a69e44be-0c45-5047-b4d6-c0200f9a381f","sourceKey":"bank:BUA202:PQ-054-b","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company introduces a new digital system, but many staff lack the skills to use it and are afraid of it. Which strategy best supports the change?","options":["Punish employees who ask questions about the system","Reduce communication to avoid alarming staff","Train employees regularly and involve them in the change","Allow rumours to spread news of the change informally"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"Regular training closes the skills gap, and involving staff builds trust and commitment, both standard strategies for managing change in Nigerian organisations. Options B and D worsen uncertainty, and option A discourages the very questions that help people adjust."}},{"itemId":"dcb6ddd2-db35-59c4-8224-4e76e2893873","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"02c0ab4b-7ea2-5509-bdc4-90728c34ab52","sourceKey":"bank:BUA202:PQ-055-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which need sits at the TOP of Maslow's hierarchy?","options":["Safety","Self-actualisation","Esteem","Social (love/belonging)"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Self-actualisation - becoming everything one is capable of and using one's full potential - is the highest level. Option C is the level just below it, while options D and A are lower still."}},{"itemId":"0b82aaae-ddeb-5b1e-a54e-c70dd6feca83","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"269eb560-2f77-51b2-9143-fe67a634ee76","sourceKey":"bank:BUA202:PQ-056-b","parentItemId":null,"revision":1,"payload":{"prompt":"The basic motivation cycle starts with:","options":["An unmet need, which leads to behaviour aimed at satisfying it","A performance appraisal, which creates new needs","A satisfied need, which continues to drive behaviour","A reward, which then creates a need"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Motivation begins with an unmet need: the need triggers behaviour, and the behaviour produces an outcome that either satisfies the need or leaves it unmet. Option D reverses cause and effect, option C is wrong because a satisfied need no longer motivates, and option B has nothing to do with how needs arise."}},{"itemId":"e6111cfc-3623-5f0c-8e7e-149226f3e5c9","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5f0ca7ee-301e-59ee-96e9-cda656b45249","sourceKey":"bank:BUA202:PQ-057-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an importance of motivation in an organisation?","options":["It increases productivity","It reduces absenteeism","It increases labour turnover","It improves employee satisfaction"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Motivated staff are more likely to stay, so motivation reduces labour turnover rather than increasing it. Options A, B and D are genuine benefits of motivation, alongside encouraging innovation and improving overall organisational performance."}},{"itemId":"94d4407d-0b71-5653-83cd-9798e21a26e1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"bd591f85-019e-5703-b7fe-e30659fcf8fa","sourceKey":"bank:BUA202:PQ-057-b","parentItemId":null,"revision":1,"payload":{"prompt":"After a company introduces a bonus and recognition scheme, its staff come to work more regularly and fewer of them resign. Which benefits of motivation does this show?","options":["Higher recruitment costs and more vacancies","Increased absenteeism and higher labour turnover","Reduced absenteeism and reduced labour turnover","Reduced productivity and lower morale"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Coming to work more regularly means less absenteeism, and fewer resignations means lower labour turnover - two classic benefits of a motivated workforce. Options B, D and A describe the opposite of what the scenario shows."}},{"itemId":"2d9a8fac-de21-520c-a950-b9ea304e4fb5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"41e0142b-7080-57dd-ae61-a1582bff8187","sourceKey":"bank:BUA202:PQ-058-a","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow, why does a well-paid worker with a secure job begin to seek recognition and promotion?","options":["Once lower-level needs are satisfied they stop motivating, and higher-level needs such as esteem become the motivators","People always seek self-actualisation first before any other need","Recognition is a physiological need that must be met before safety","Lower-level needs never stop motivating, no matter how well they are satisfied"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Maslow argued that a satisfied need is no longer a motivator, so once physiological and safety needs are met, people move up to social, esteem and finally self-actualisation needs. Option D contradicts this principle, option B reverses the order of the hierarchy, and option C wrongly places recognition, which is an esteem need."}},{"itemId":"dc1573fd-3016-5b60-b0b7-20e270153fb2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d57f57e5-a48b-524e-b6a8-d3e5200abb4e","sourceKey":"bank:BUA202:PQ-058-b","parentItemId":null,"revision":1,"payload":{"prompt":"An employee values job security, a pension scheme and a safe working environment. Which level of Maslow's hierarchy do these mainly satisfy?","options":["Safety needs","Self-actualisation needs","Physiological needs","Esteem needs"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Safety needs are about protection and freedom from danger, which job security, pensions and safe workplaces provide. Option C covers basics like food and shelter, option D covers respect and recognition, and option B covers reaching one's full potential."}},{"itemId":"5c3baa29-ef89-5ebf-8771-d7da72ad09fa","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"26dbf501-5b07-5e8f-97e3-56037a0f8a46","sourceKey":"bank:BUA202:PQ-058-c","parentItemId":null,"revision":1,"payload":{"prompt":"Promotion and recognition at work mainly satisfy which level of Maslow's hierarchy?","options":["Physiological needs","Esteem needs","Social needs","Safety needs"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Esteem needs are the desire for respect, self-confidence and appreciation, so recognition and promotion meet them. Option C is about belonging and friendship at work, option D is about protection and security, and option A is about basic survival."}},{"itemId":"576ea9a5-fb84-540c-9cd4-c82aeb9d6a73","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5350e7d7-343d-5b5f-8cf5-f664ce1bed8c","sourceKey":"bank:BUA202:PQ-059-a","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's two-factor theory, hygiene factors are those that:","options":["Relate only to the challenge and growth found in the work itself","Prevent dissatisfaction when present but do not by themselves motivate","Create strong motivation and satisfaction when present","Have no effect on employees' satisfaction or dissatisfaction"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Hygiene factors such as pay, company policy and working conditions stop employees from complaining, but having them does not make people truly motivated. Option C describes motivators, option D is wrong because their absence clearly causes dissatisfaction, and option A describes the job-content factors, which are motivators."}},{"itemId":"1692dd90-6fa8-5827-b5c5-8b51af758d66","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"705d448f-4aae-57ef-b2fc-467c77f6a604","sourceKey":"bank:BUA202:PQ-059-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a MOTIVATOR (not a hygiene factor) in Herzberg's theory?","options":["Salary","Company policy","Working conditions","Recognition for achievement"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Motivators come from the work itself - achievement, recognition, responsibility, growth - and they create real satisfaction. Options A, C and B are hygiene (job-context) factors that only prevent dissatisfaction."}},{"itemId":"8820e65e-c663-5b9e-8525-adb01b2f35d7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a5a8ffa1-a641-5343-bc84-2b3d2cd7a8b8","sourceKey":"bank:BUA202:PQ-059-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a HYGIENE factor in Herzberg's theory?","options":["Personal growth","Responsibility","Achievement","Supervision"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Supervision belongs to the job context, along with pay, policy and working conditions, so it is a hygiene factor. Options B, C and A come from the content of the job itself and are motivators."}},{"itemId":"f5e0dc9a-1b95-542d-bc6a-b9a7579c5c01","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5c43bb35-5682-515b-897b-0d547d3d6076","sourceKey":"bank:BUA202:PQ-060-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who holds Theory Y assumptions is most likely to use which leadership style?","options":["Authoritarian, with close supervision","Strict rule-based control with no delegation","Participative, involving employees in decisions","Coercive, based on threats of punishment"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Theory Y assumes people enjoy work, are creative and can direct themselves, so the manager involves them and delegates. Options A, D and B all reflect the controlling approach that goes with Theory X."}},{"itemId":"d26038a6-4baf-54de-8c18-179caa18e015","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9bb37218-c367-5dc3-af62-30228665ffd3","sourceKey":"bank:BUA202:PQ-060-c","parentItemId":null,"revision":1,"payload":{"prompt":"Who developed Theory X and Theory Y?","options":["Frederick Herzberg","Victor Vroom","Abraham Maslow","Douglas McGregor"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Douglas McGregor described Theory X and Theory Y as two opposite sets of assumptions managers hold about workers. Option C is linked with the hierarchy of needs, option A with the two-factor theory, and option B with expectancy theory."}},{"itemId":"3ce400e5-f048-5c4f-8813-27a3a25bdccf","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"35bd9616-8000-5a39-84bf-8ad56cedfb0a","sourceKey":"bank:BUA202:PQ-061-a","parentItemId":null,"revision":1,"payload":{"prompt":"Expectancy theory of motivation is associated with:","options":["Victor Vroom","Abraham Maslow","Douglas McGregor","Frederick Herzberg"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Victor Vroom proposed expectancy theory, which explains motivation through people's beliefs about effort, performance and rewards. Option C developed Theory X and Theory Y, option B the hierarchy of needs, and option D the two-factor theory."}},{"itemId":"0425d7af-f67b-57f0-b674-46e741b07180","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0eea6ca9-75b3-5af3-8382-c33265679113","sourceKey":"bank:BUA202:PQ-061-b","parentItemId":null,"revision":1,"payload":{"prompt":"Expectancy theory states that an employee will be most motivated when they believe:","options":["All their lowest-level needs have been satisfied","Their manager supervises them closely","Effort will lead to good performance, good performance will be rewarded, and the reward is valuable to them","Hygiene factors such as pay are present"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Expectancy theory follows the chain effort -> performance -> reward: motivation is high only when all three links are believed, for example a salesperson who knows extra sales will earn a bonus they want. Option A comes from Maslow, option D from Herzberg, and option B reflects Theory X thinking."}},{"itemId":"bafffada-7e51-536c-b4e3-ed622a2fc7d1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e0e2a425-be06-571d-992c-8543622bd6cc","sourceKey":"bank:BUA202:PQ-061-c","parentItemId":null,"revision":1,"payload":{"prompt":"In expectancy theory, valence refers to:","options":["The belief that good performance will be rewarded","How much the employee values the reward","The belief that effort will lead to good performance","The amount of effort the employee puts into the job"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"Valence is how attractive or desirable the reward is to the individual; a bonus nobody wants has low valence. Option C is expectancy, option A is instrumentality, and option D is the effort itself, not one of the three beliefs."}},{"itemId":"fd9144cf-2f7b-5ac4-b124-3cf4d998d5f3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"85705571-4120-54e9-899f-912292f110ff","sourceKey":"bank:BUA202:PQ-062-a","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership is best defined as:","options":["The process of recruiting and selecting staff","The formal authority held only by top management","The process of influencing people towards achieving goals","The process of evaluating employees' job performance"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Leadership is about influence - getting people to work willingly towards shared goals - and anyone at any level can exercise it. Option D describes performance appraisal, option B confuses leadership with formal position, and option A is an HR function."}},{"itemId":"2a97d87e-1a08-5e8c-8c3d-23b416dd4aea","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"9e04a223-d7cd-57af-8624-c1100d61b017","sourceKey":"bank:BUA202:PQ-062-b","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor sets goals for her team and then inspires and persuades the members to work willingly towards them. She is mainly exercising:","options":["Performance appraisal","Recruitment","Job analysis","Leadership"],"correctOption":3,"section":"Motivation, Leadership and Performance Management","explanation":"Inspiring and persuading people to pursue goals is the heart of leadership, which is influencing others towards achieving objectives. Option A evaluates past performance, option C studies the content of jobs, and option B attracts new applicants."}},{"itemId":"b05516c2-c406-5c1a-8e47-06f15d8af350","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"fb4eab62-f496-5a43-a7a7-45f5d29144bd","sourceKey":"bank:BUA202:PQ-063-a","parentItemId":null,"revision":1,"payload":{"prompt":"In which leadership style does the leader make all decisions alone and expect subordinates to obey?","options":["Participative","Autocratic","Laissez-faire","Democratic"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"An autocratic leader keeps decision-making to himself or herself, as is common in military settings. Options D and A involve employees in decisions, and option C leaves most decisions to the employees."}},{"itemId":"5ec685f0-cb77-5084-83b9-5bbf852d1542","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2f36e91a-015c-519b-ab37-1d50794341fd","sourceKey":"bank:BUA202:PQ-063-b","parentItemId":null,"revision":1,"payload":{"prompt":"A research team leader gives highly skilled scientists the freedom to choose their own methods and make most decisions with little interference. This is:","options":["Theory X leadership","Autocratic leadership","Laissez-faire leadership","Democratic leadership"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"Laissez-faire ('let them do') leadership gives employees freedom to work on their own, which suits experts such as research teams. Option B keeps all decisions with the leader, option D involves staff but the leader still guides the decision, and option A relies on close control."}},{"itemId":"fb354b8a-1fd9-55a2-9555-32b93819ba0d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"db2585cd-cfb7-5ece-82e7-ea346ea95268","sourceKey":"bank:BUA202:PQ-063-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists three leadership styles?","options":["Hygiene factors, motivators, valence","Autocratic, democratic, laissez-faire","Physiological, safety, esteem","Unfreezing, changing, refreezing"],"correctOption":1,"section":"Motivation, Leadership and Performance Management","explanation":"The three classic leadership styles are autocratic (leader decides), democratic (employees participate) and laissez-faire (employees work freely). Option C lists Maslow's needs, option D lists Lewin's change stages, and option A mixes terms from motivation theories."}},{"itemId":"5e83f4e5-5f33-55ef-aee7-b3144b9217b7","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b9653e36-07d8-527f-8b0c-9e21c6d59a98","sourceKey":"bank:BUA202:PQ-064-a","parentItemId":null,"revision":1,"payload":{"prompt":"Performance appraisal means:","options":["The systematic evaluation of an employee's job performance over a period","The introduction of a new employee to the organisation","The process of designing the content of a job","The process of attracting candidates to apply for a job"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Performance appraisal is the regular, structured assessment of how well an employee is doing the job, such as a bank manager evaluating staff every six months. Option D is recruitment, option B is orientation or onboarding, and option C is job design."}},{"itemId":"c6396e9d-f96c-50e7-bed4-b6f46adacf09","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"37f99cf4-2ecb-52eb-bb80-be7e3122bdca","sourceKey":"bank:BUA202:PQ-064-b","parentItemId":null,"revision":1,"payload":{"prompt":"In 360-degree feedback, an employee's performance is assessed by:","options":["Only the employee's immediate supervisor","An external auditor once a year","Several people around them, such as supervisors, peers, subordinates and sometimes customers","Only the employee, through self-assessment"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"360-degree feedback gathers views from all around the employee - above, beside and below, and sometimes outside - to give a fuller picture. Option A is a traditional top-down appraisal, option D is only self-appraisal, and option B confuses appraisal with financial auditing."}},{"itemId":"b24904f9-5b61-5441-bdbc-360ac59c5835","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"95d1d56d-62e4-509e-b210-f97372df0667","sourceKey":"bank:BUA202:PQ-064-c","parentItemId":null,"revision":1,"payload":{"prompt":"Under management by objectives (MBO) as an appraisal method, an employee is evaluated by:","options":["Comparing actual results with objectives agreed in advance with the manager","Ticking a list of statements that describe their behaviour","Ranking all employees from best to worst","Comparing them with a colleague chosen at random"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"MBO starts with the manager and employee agreeing specific objectives, and performance is later judged by how far those objectives were met. Option C is the ranking method, option B is the checklist method, and option D is not a recognised appraisal method."}},{"itemId":"03e94087-657c-5237-a4a0-31d2d333818c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0b87f9df-383c-5c0b-9f41-bf1eb4441e3b","sourceKey":"bank:BUA202:PQ-065-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an objective of performance appraisal?","options":["Fixing the selling price of the company's products","Giving employees feedback on their performance","Identifying employees' training needs","Providing a basis for promotion and salary increases"],"correctOption":0,"section":"Motivation, Leadership and Performance Management","explanation":"Appraisal is about employees, so product pricing is a marketing decision, not an appraisal objective. Options C, D and B are genuine objectives of appraisal, alongside deciding on rewards."}},{"itemId":"f6a1e030-01ca-5020-b0b4-0d9344fc31b6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d877056c-288d-5eab-a970-2ff50faba652","sourceKey":"bank:BUA202:PQ-065-b","parentItemId":null,"revision":1,"payload":{"prompt":"A bank's appraisal shows that a teller makes frequent errors with the new banking software. The most appropriate use of this result is to:","options":["Ignore the result because appraisal is only for record-keeping","Increase the teller's salary as a reward","Identify a training need and arrange training","Immediately promote the teller"],"correctOption":2,"section":"Motivation, Leadership and Performance Management","explanation":"One of the main purposes of appraisal is to spot skill gaps so that training can close them. Options D and B reward weak performance, and option A wastes the appraisal, whose purpose is to inform decisions on training, promotion, pay and feedback."}},{"itemId":"eca80811-ed43-51fa-b5df-515944f7b450","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0339a913-1bd5-5829-aab9-b77c3db1198a","sourceKey":"bank:BUA202:PQ-066-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of organisational change?","options":["A company paying staff salaries on the usual date","A company replacing manual records with a computerised accounting system","Employees following the existing work routine","A manager holding the regular weekly meeting"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Organisational change is any significant alteration in structure, technology, people or processes, and moving from manual to computerised records is a technological change. Options A, C and D are routine activities that keep things as they already are."}},{"itemId":"3e398a25-05a1-59c7-b045-0cedcb89bb70","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be89225c-d356-5611-af05-15f10962d788","sourceKey":"bank:BUA202:PQ-066-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about organisational change is correct?","options":["It is caused only by external factors such as government policy","It happens only once in the life of an organisation","It is always planned and comes only from top management","It may be planned or unplanned and can be driven by internal or external factors"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Organisational change is continuous, can be planned or unplanned, and is influenced by both internal and external factors. Option C ignores unplanned change, option B ignores that change is continuous, and option A ignores internal drivers such as new leadership or financial problems."}},{"itemId":"b3f6b593-d0da-59ca-ac6e-368e4c39fbd2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2ff03327-37f0-5f0d-b557-dcad8b0557e6","sourceKey":"bank:BUA202:PQ-067-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair correctly matches each driver of change with its type?","options":["Government policy - internal; customer preferences - internal","New leadership - external; globalisation - internal","New leadership - internal; globalisation - external","Competition - internal; poor employee performance - external"],"correctOption":2,"section":"Organisational Change and Change Management","explanation":"New leadership starts inside the organisation, while globalisation is a force in the outside environment. Options B and D reverse the categories, and option A wrongly calls government policy and customer preferences internal when both come from outside."}},{"itemId":"5b978b35-60be-5baa-a6e4-49029b680813","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"615f35ca-7781-5a7b-bd1f-9fc25d5cf7ac","sourceKey":"bank:BUA202:PQ-067-b","parentItemId":null,"revision":1,"payload":{"prompt":"Inflation and exchange-rate fluctuations force a Nigerian manufacturer to cut costs and restructure. This is an example of change driven by:","options":["Internal new leadership","Internal innovation","Internal employee demands","External economic conditions"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Inflation and exchange rates belong to the economy outside the firm, so this is an external driver. Options A, C and B are internal drivers that the scenario does not mention."}},{"itemId":"d2e3f8a0-9bbf-509e-a451-aa4989cb2410","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d993b3b3-4e0a-594f-9d5b-b72b89d36c55","sourceKey":"bank:BUA202:PQ-068-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a cause of resistance to change?","options":["Clear communication and involvement of employees in the change","Habit and comfort with existing routines","Fear of the unknown","Lack of trust in management"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Clear communication and involvement reduce resistance; they are cures, not causes. Options C, B and D are typical causes, together with fear of job loss, poor communication, lack of skills, increased workload and poor leadership."}},{"itemId":"f20db7a6-c21d-51cd-9ee1-8bf5f82b5d44","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0f9375e1-5276-5158-a0fd-567ab0e9c61d","sourceKey":"bank:BUA202:PQ-068-b","parentItemId":null,"revision":1,"payload":{"prompt":"Employees resist a new procedure mainly because management never explained what it involves or why it is needed. The main cause of resistance here is:","options":["Poor communication","Increased workload","Habit","Fear of job loss"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Employees resist changes they do not understand, and the scenario shows management failing to explain the change, which is poor communication. Option B would be about extra work, option C about attachment to old routines, and option D about worry over losing jobs - none of which is described."}},{"itemId":"89e67a61-4b6c-5d4f-8208-9881d15cf9be","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cf5ecb97-dc28-5909-ab06-70bd26f5a586","sourceKey":"bank:BUA202:PQ-069-a","parentItemId":null,"revision":1,"payload":{"prompt":"In Lewin's change model, the 'changing' (movement) stage involves:","options":["Actually implementing the change, for example introducing new technology, procedures and training","Identifying the external forces that cause change","Preparing people by explaining why the change is needed","Making the change permanent through new policies and rewards"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"The changing stage is where the new system or way of working is actually introduced and people are trained to use it. Option C is unfreezing, option D is refreezing, and option B is analysing drivers of change rather than a Lewin stage."}},{"itemId":"afa0683d-10fd-500e-b61f-18d5d888da33","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"adc29ed2-f403-53fd-a6c9-7533226e3bd2","sourceKey":"bank:BUA202:PQ-069-b","parentItemId":null,"revision":1,"payload":{"prompt":"Who developed the three-step Unfreeze - Change - Refreeze model of change?","options":["Douglas McGregor","Victor Vroom","John Kotter","Kurt Lewin"],"correctOption":3,"section":"Organisational Change and Change Management","explanation":"Kurt Lewin proposed that successful change moves through unfreezing, changing and refreezing. Option C developed the eight-step model, while options A and B are known for motivation theories (Theory X/Y and expectancy theory)."}},{"itemId":"a14be1c6-1543-572f-9f65-4975099864ec","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5c2aa7ba-08e5-56ad-b07e-448f864a7a5b","sourceKey":"bank:BUA202:PQ-070-a","parentItemId":null,"revision":1,"payload":{"prompt":"Who developed the eight-step model of leading change?","options":["John Kotter","Kurt Lewin","Frederick Herzberg","Abraham Maslow"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"John Kotter expanded the idea of planned change into eight steps, from creating urgency to anchoring the change in culture. Option B developed the three-step model, while options D and C are motivation theorists."}},{"itemId":"5d1d9068-3280-5f7e-9328-0da7ec7b85c5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ce11aba1-6181-5a69-a011-1d6fb081eb8b","sourceKey":"bank:BUA202:PQ-070-b","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter's model, celebrating early visible successes to build momentum is called:","options":["Creating short-term wins","Building a guiding coalition","Creating a sense of urgency","Anchoring the change"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Short-term wins (step six) are early, visible successes that prove the change is working and keep people motivated. Option D is the final step, option C is the first step, and option B is the second step."}},{"itemId":"d3e746a1-f6f5-58cb-bdad-8e9d55b7484b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b0ae301a-c633-5f24-8eef-72d56c188247","sourceKey":"bank:BUA202:PQ-070-c","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter's model, which step comes immediately after 'create short-term wins'?","options":["Sustain momentum - consolidate gains and keep improving","Develop a vision","Anchor the change in the culture","Remove obstacles"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"After short-term wins (step six), Kotter's step seven builds on them, keeping momentum and improving until the change is complete. Option C is the final step that follows, while options B and D come earlier in the model."}},{"itemId":"77d49ec8-c8cd-5130-9096-e9cc6ccd4cf5","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"527f2744-bb4d-5f08-8219-e54f9a2bc2c1","sourceKey":"bank:BUA202:PQ-071-a","parentItemId":null,"revision":1,"payload":{"prompt":"Kotter's first step, creating a sense of urgency, corresponds most closely to which stage of Lewin's model?","options":["Unfreezing","Refreezing","Changing (movement)","None of Lewin's stages"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Creating urgency breaks people out of their comfort with the old way, which is what unfreezing does in Lewin's model. Option C matches Kotter's middle steps where the change is carried out, option B matches Kotter's anchoring step, and option D is wrong because the two models line up closely."}},{"itemId":"541253b6-4fad-5a07-ace5-2647a2839e39","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6519bb0b-88ea-504c-bda4-60c44ff07e8e","sourceKey":"bank:BUA202:PQ-071-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an advantage of Kotter's model compared with Lewin's?","options":["It gives more detailed, step-by-step guidance for leading large-scale change","It works without strong leadership","It has fewer steps and is quicker to apply","It assumes change ends once it has been made"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Kotter's eight steps turn Lewin's broad framework into a detailed, practical guide that suits large organisations. Option C is wrong because Kotter has more steps and is more time-consuming, option B is wrong because it depends on strong leadership, and option D is a criticism made of Lewin's model."}},{"itemId":"2678d4c2-1e07-5e96-b4ae-90d32c396175","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"d4ca2075-3532-5d3d-9598-b9324b40862e","sourceKey":"bank:BUA202:PQ-072-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair of actions would best help a manager reduce resistance to change?","options":["Cutting training to save time","Communicating clearly why the change is needed and allowing employees to participate","Ignoring complaints and threatening dismissal","Keeping the change secret and imposing it suddenly"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Explaining the reasons for change and involving employees reduces fear and builds commitment. Options D and C increase uncertainty and hostility, and option A leaves staff without the skills they need, which is itself a cause of resistance."}},{"itemId":"ccd7dc64-a3db-50a6-af83-0136d33a2183","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"78755c0e-feef-5097-b08d-bd255321c169","sourceKey":"bank:BUA202:PQ-072-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manager notices that some employees are anxious and emotionally upset about a planned restructuring. Which approach is most suitable?","options":["Provide counselling and support to help them adjust","Publicly criticise the anxious employees","Stop all communication about the restructuring","Speed up the change without explanation"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Counselling helps employees cope with the emotional side of change, which reduces resistance. Options C and D increase uncertainty, and option B damages trust and morale."}},{"itemId":"aff345c8-05de-5e7a-abb9-644aaf1eaba1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"621cda49-803a-566c-82ae-317f431257a2","sourceKey":"bank:BUA202:PQ-073-a","parentItemId":null,"revision":1,"payload":{"prompt":"Business communication is best defined as:","options":["Advertising products to customers only","Informal conversations among friends at work only","The systematic exchange of information, ideas, instructions and opinions among people within and outside an organisation to achieve its objectives","Communication among managers alone, excluding employees"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Business communication covers every exchange of information inside the organisation and with outsiders such as customers, suppliers, regulators and investors, all aimed at its goals. Option A is only one narrow form of external communication, option D leaves out employees, and option B covers only the informal grapevine."}},{"itemId":"13edee9d-f99d-5a43-b35f-0be479af24c1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"66c1f93c-0976-5f0b-84ac-e13dfdaa1ef6","sourceKey":"bank:BUA202:PQ-073-d","parentItemId":null,"revision":1,"payload":{"prompt":"A poor internet connection during an online meeting, a loud environment and language barriers are all examples of which element of communication?","options":["Channel","Noise","Encoding","Feedback"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Noise is anything that interferes with accurate communication, whether physical (sound, bad network) or semantic (language). Option D is the receiver's response, option C is forming the message, and option A is the medium itself, such as email or a meeting."}},{"itemId":"cb11d774-ba98-5568-8f0d-e519166d5102","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"adf63667-1b03-5974-ad99-c46bea89bf7f","sourceKey":"bank:BUA202:PQ-073-e","parentItemId":null,"revision":1,"payload":{"prompt":"The receiver's response that shows the sender whether the message was understood is called:","options":["Channel","Decoding","Encoding","Feedback"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Feedback, such as an employee replying 'Yes, I understand the instructions', completes the process and tells the sender whether communication really happened. Option B is the receiver interpreting the message, option C is the sender forming it, and option A is the medium used to send it."}},{"itemId":"60110eae-ec9d-500c-8c01-279097026a01","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"89eb4545-902a-51b2-b703-2f22540ace32","sourceKey":"bank:BUA202:PQ-074-a","parentItemId":null,"revision":1,"payload":{"prompt":"The grapevine refers to:","options":["The informal, unofficial communication network through which information spreads in an organisation","A formal written report sent to top management","The official chain of command used for formal instructions","Communication with customers and suppliers"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"The grapevine is the informal network - chats between colleagues, office WhatsApp groups, lunch talk - that carries information outside official channels. Options C and B are formal communication, and option D is external communication."}},{"itemId":"e03d596a-1319-55ae-9125-c4514f9c744e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c780083c-9dd7-5fb6-919d-3bf67eea88b9","sourceKey":"bank:BUA202:PQ-074-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a characteristic of formal communication?","options":["It spreads mainly through rumours","It follows the official organisational structure and is usually documented","It is unofficial and usually leaves no records","It does not follow any hierarchy"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Formal communication moves through official channels and hierarchy, and it is usually recorded, such as memos, reports and official emails. Options C, A and D describe informal communication (the grapevine)."}},{"itemId":"cff8c92d-89a9-509f-9ef1-99b0058f7705","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8152010c-a60b-594e-8feb-69481cb5fa58","sourceKey":"bank:BUA202:PQ-074-c","parentItemId":null,"revision":1,"payload":{"prompt":"An employee sends a written complaint with suggestions to her head of department. This is an example of:","options":["Upward communication","Horizontal communication","Downward communication","Grapevine communication"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Upward communication flows from employees to management, carrying complaints, suggestions, feedback and reports. Option C flows from management to staff, option B is between people at the same level, and option D is informal, while this complaint is formal."}},{"itemId":"379ad311-4c6e-5b80-9827-45a02efac4ab","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"c7aab5c4-347b-54cc-81c3-cb8a0d309689","sourceKey":"bank:BUA202:PQ-074-d","parentItemId":null,"revision":1,"payload":{"prompt":"Communication between the marketing manager and the finance manager, who are at the same level in the organisation, is:","options":["Downward communication","Upward communication","Diagonal communication","Horizontal communication"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Horizontal communication takes place between people or departments at the same level and helps coordination and teamwork. Options A and B move between levels in the hierarchy, and option C crosses both departments and levels, such as an HR manager speaking directly with a sales officer."}},{"itemId":"8f96e983-fd7c-5612-a383-340acfb6f08f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"56bd3af2-9b83-5f43-802b-eee1a54834fd","sourceKey":"bank:BUA202:PQ-075-a","parentItemId":null,"revision":1,"payload":{"prompt":"A Management Information System (MIS) is best described as:","options":["A system, usually computer-based, that collects, processes, stores and provides information to managers for planning, decision-making and control","A machine used only for typing letters","The department that handles employee welfare","A system used only to process customer cash withdrawals"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"An MIS turns raw data into useful information and delivers it to managers so they can plan, decide, coordinate and control. Option B is a single office tool, option C is an HR function, and option D describes one routine transaction, which is the work of a transaction processing system."}},{"itemId":"9e4b141a-b33d-55db-91da-cde4a42f81b6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ba11f66f-8e50-56b0-932e-28c3f0b926ea","sourceKey":"bank:BUA202:PQ-075-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an importance of MIS?","options":["It removes the need for managers to make decisions","It helps managers monitor and control performance","It improves coordination between departments","It supports better and faster decision-making"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"An MIS supports managers' decisions with accurate, timely information; it does not replace managerial judgement. Options D, C and B are genuine benefits, along with better planning, productivity and customer service."}},{"itemId":"8f67273a-5a36-57d4-b19d-fd7260dd6598","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"cd627f7d-86bd-50ae-a0c1-42b419a89fd5","sourceKey":"bank:BUA202:PQ-075-c","parentItemId":null,"revision":1,"payload":{"prompt":"An information system that processes routine daily business transactions such as payroll, sales and ATM transactions is called a:","options":["Executive Information System (EIS)","Decision Support System (DSS)","Office Automation System (OAS)","Transaction Processing System (TPS)"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"A TPS handles the high volume of everyday transactions that keep a business running. Option A gives summary information to top executives, option B helps managers with complex decisions, and option C supports office work such as word processing and email."}},{"itemId":"06363db5-f313-5cf1-823b-b54a5da6140c","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"12602e9f-5f7e-5857-8352-82c4f132248d","sourceKey":"bank:BUA202:PQ-076-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes data?","options":["Facts that have been processed and organised for decision-making","Raw, unprocessed facts and figures with little meaning on their own","The final decision taken by management","Conclusions drawn by managers from reports"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"Data are raw facts - such as daily sales figures or attendance records - that mean little until they are organised and analysed. Option A describes information, option D is an interpretation built on information, and option C is the result of the decision-making process."}},{"itemId":"ba1e6210-547e-5b15-a493-8c2663f53136","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"2e7d3e2f-58be-5623-8c4c-d7b7dbde482f","sourceKey":"bank:BUA202:PQ-076-b","parentItemId":null,"revision":1,"payload":{"prompt":"A shop records sales of 250, 320 and 280 units on Monday, Tuesday and Wednesday. A manager's report then states: 'Sales rose by 28% from Monday to Tuesday, then fell slightly on Wednesday.' Which statement is correct?","options":["Both the figures and the statement are information","The daily figures are data; the report's statement is information","Both the figures and the statement are data","The daily figures are information; the report's statement is data"],"correctOption":1,"section":"Business Communication, Information Systems and Digital Management","explanation":"The three daily figures are raw facts (data), while the report processes them into a meaningful trend (information) that managers can act on; 320 is 28% more than 250. Option D reverses the two ideas, and options C and A ignore the difference between unprocessed input and processed output."}},{"itemId":"f19622a9-38f0-57e7-b941-011921007abc","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f0ea3ea5-cf42-5ae9-a92a-ec70686353cf","sourceKey":"bank:BUA202:PQ-076-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a characteristic of good information?","options":["It includes as much detail as possible, whether relevant or not","It is raw and unprocessed","It is accurate, relevant and timely","It arrives after the decision has already been made"],"correctOption":2,"section":"Business Communication, Information Systems and Digital Management","explanation":"Good information must be accurate, relevant and timely, as well as complete, reliable and understandable. Option B describes data, option D is useless because it comes too late, and option A leads to information overload."}},{"itemId":"69a2216f-5b62-5efe-8d8f-e3a07b2ecf80","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e9fb4091-a757-5f7d-8b04-33903445dd87","sourceKey":"bank:BUA202:PQ-077-a","parentItemId":null,"revision":1,"payload":{"prompt":"Digital communication is:","options":["The exchange of information using electronic devices and digital technologies such as email, video conferencing and messaging apps","Communication using only body language","Face-to-face communication without any technology","Communication only through printed letters and memos"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Digital communication uses the internet and electronic systems, such as email, WhatsApp, Zoom or Teams, to send and receive information quickly. Option D is traditional written communication, option C is oral communication, and option B is non-verbal communication."}},{"itemId":"288e5cfc-ceb7-5294-8a4a-57516005e6ca","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"aea77970-1d82-5bbe-b39a-f7952fd0114d","sourceKey":"bank:BUA202:PQ-077-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an ADVANTAGE of digital communication?","options":["Speed and lower cost, since messages arrive instantly with less spending on paper, postage and transport","Dependence on internet access and power supply","Information overload","Exposure to cybersecurity threats"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Digital tools deliver messages instantly and cut the costs of paper, postage and travel, which is why firms rely on them. Options D, B and C are disadvantages or challenges of digital communication."}},{"itemId":"40ec1e16-3670-52a6-9451-27180997a523","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"61d0346c-6ce5-57d4-804f-83dc9c727995","sourceKey":"bank:BUA202:PQ-077-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a CHALLENGE of digital communication for many Nigerian organisations?","options":["Poor internet connectivity and power outages","Faster collaboration among staff in different locations","Easy electronic storage of messages","Global reach to international customers"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Digital communication depends on stable internet and electricity, so poor connectivity and power outages are real challenges. Options D, C and B are advantages of digital communication, not problems."}},{"itemId":"56d0d21f-11bc-5410-bdaa-43a9d42e464b","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1e706439-4ac6-5c3c-b63e-ee0584cba5f6","sourceKey":"bank:BUA202:PQ-078-a","parentItemId":null,"revision":1,"payload":{"prompt":"Remote work (telecommuting) means:","options":["Employees performing their duties outside the traditional office using digital communication technologies","Contracting all of a firm's work out to another company","Working only during night shifts","Employees working only at the head office"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Remote work lets employees do their jobs from home, co-working spaces, while travelling or from branch offices, connected by digital tools such as Zoom, Teams and Google Drive. Option D is the opposite, option B describes outsourcing, and option C is about working hours, not location."}},{"itemId":"5740b140-d1b1-5a3e-a2bc-573d180527e2","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"566ecf81-206f-5b1d-8774-105b2a55f1fb","sourceKey":"bank:BUA202:PQ-078-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a benefit of remote work systems for the EMPLOYER?","options":["Higher cybersecurity risks","Greater difficulty in supervising employees","Isolation and loneliness of staff","Reduced office expenses and access to talent from a wider area"],"correctOption":3,"section":"Business Communication, Information Systems and Digital Management","explanation":"Employers save on office space and running costs and can hire skilled people regardless of location. Options C, B and A are disadvantages of remote work."}},{"itemId":"9e0073be-6b26-5e66-b53f-56fb64b3fbc8","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0f862d75-dbfc-5391-ad23-679dcef67779","sourceKey":"bank:BUA202:PQ-078-c","parentItemId":null,"revision":1,"payload":{"prompt":"During a lockdown or public emergency, remote work systems are especially important to an organisation because they:","options":["Allow the business to continue operating even when staff cannot come to the office","Guarantee that no cyber attacks will occur","Remove the need to set performance objectives","Eliminate the need for any communication"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"Remote work supports business continuity: staff can keep working from wherever they are when offices are closed. Option D is wrong because remote work depends heavily on communication, option B ignores its security risks, and option C is wrong because tracking agreed objectives is a best practice for remote teams."}},{"itemId":"8d3f541e-cebb-56f6-9e01-c79c22bb8d7f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"6156d603-2c7b-57fa-917e-7274a0916ef9","sourceKey":"bank:BUA202:PQ-079-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of business ethics?","options":["It makes compliance with the law unnecessary","It builds customer trust and enhances the company's image","It allows managers to hide information from stakeholders","It increases the chances of fraud"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Ethical conduct builds trust with customers, prevents fraud, improves employee morale and protects the company's reputation. Options C and D describe unethical outcomes, and option A is wrong because ethics works alongside the law, not in place of it."}},{"itemId":"bff16a55-83c2-5049-bad7-29952a851e11","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"84bada4c-59af-5672-ba38-20b3f6f90352","sourceKey":"bank:BUA202:PQ-080-a","parentItemId":null,"revision":1,"payload":{"prompt":"A firm chooses the option that will produce the greatest good for the greatest number of people. Which ethical theory is it applying?","options":["Virtue ethics","Utilitarianism","Justice theory","Deontology (duty ethics)"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Utilitarianism judges actions by their consequences, choosing what brings the most benefit to the most people, though minority interests can suffer. Option D focuses on following rules regardless of consequences, option A on good character, and option C on fair and equal treatment."}},{"itemId":"e86bc7c5-995b-5be5-8b73-1a1b6129cc59","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"1d34bb19-7286-5c30-8eba-057696fbe04f","sourceKey":"bank:BUA202:PQ-080-b","parentItemId":null,"revision":1,"payload":{"prompt":"Deontology (duty ethics) holds that:","options":["Ethics is mainly about developing good character traits such as honesty and courage","Actions are right if they bring the highest profit","Actions are right if they follow moral rules or duties, regardless of their consequences","Actions are right if they produce the greatest good for the greatest number"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Deontology says some duties must be kept no matter the outcome - for example, never lie to customers. Option D describes utilitarianism, option A describes virtue ethics, and option B is not an ethical theory at all."}},{"itemId":"4d2ef069-ea40-510a-88d9-6d3ece1f641a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"68cadf12-6294-50a6-ad38-ebb8aefc8b09","sourceKey":"bank:BUA202:PQ-080-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which ethical theory focuses mainly on the character of the person, such as honesty, integrity and courage?","options":["Utilitarianism","Justice theory","Deontology (duty ethics)","Virtue ethics"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Virtue ethics asks what a person of good character would do, stressing traits like honesty, integrity, courage and respect. Option A looks at consequences, option C at rules and duties, and option B at fairness in how people are treated."}},{"itemId":"ccf94d74-4af7-5966-be96-aa787dc89a98","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a21773f2-c567-559c-88f3-7508adc465f2","sourceKey":"bank:BUA202:PQ-080-d","parentItemId":null,"revision":1,"payload":{"prompt":"Justice theory judges an action mainly by whether:","options":["It follows a fixed moral rule regardless of consequences","It reflects good character in the decision-maker","People are treated fairly and equally","It produces the greatest total happiness"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Justice theory is concerned with fairness, so an action is ethical if benefits and burdens are shared fairly and people are treated equally. Option D is utilitarianism, option A is deontology, and option B is virtue ethics."}},{"itemId":"3a5d5df1-11f4-51df-a860-42e7c2816ae1","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e64fafd5-983a-5553-97cb-15dab390f0a0","sourceKey":"bank:BUA202:PQ-081-a","parentItemId":null,"revision":1,"payload":{"prompt":"Corporate Social Responsibility (CSR) is:","options":["A government agency that regulates companies","The practice of maximising shareholders' profit at any cost to society","A legal requirement for a business to pay company income tax and nothing more","The obligation of a business to contribute positively to society while making profits"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"CSR means a business looks beyond profit alone and takes responsibility for its impact on employees, customers, communities and the environment. Option C reduces CSR to one legal duty, option B is the opposite of CSR, and option A confuses CSR with a regulator."}},{"itemId":"ea974acb-7268-5764-b154-8d72fa8071fe","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5bce2dde-8991-5b87-8a96-bcd49a37702e","sourceKey":"bank:BUA202:PQ-081-b","parentItemId":null,"revision":1,"payload":{"prompt":"A bank builds a library for its host community even though no law requires it to. Which area of CSR does this represent?","options":["Philanthropic responsibility","Operational responsibility","Economic responsibility","Legal responsibility"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Philanthropic responsibility is voluntary giving back to society, such as donations and community projects. Option C is about making profits ethically, option D is about obeying the law, which does not require this project, and option B is not one of the areas of CSR."}},{"itemId":"c78d64f1-537b-5a90-84a4-ee108f2a2d8d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ed8360c4-5778-5f95-8aa3-6c3b179f94c3","sourceKey":"bank:BUA202:PQ-081-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a benefit of CSR to a business?","options":["Higher fines from regulators","Lower employee satisfaction","Loss of competitive advantage","Better reputation and greater customer loyalty"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Socially responsible firms tend to enjoy a better reputation, loyal customers, more satisfied employees and a competitive edge. Options A, B and C are the opposite of what CSR usually brings."}},{"itemId":"44675c3b-7e8a-5073-9f25-0db7251acf59","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"936fcc9a-92f5-5cd8-885e-0cbe5eb08883","sourceKey":"bank:BUA202:PQ-082-a","parentItemId":null,"revision":1,"payload":{"prompt":"Ethical leadership means:","options":["Pursuing results by any means necessary","Leading mainly through fear and punishment","Leading with honesty, integrity, fairness and accountability","Making decisions secretly to avoid questions"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical leader models honesty, integrity, fairness and accountability, which builds trust and an ethical culture. Options B, D and A describe behaviour that undermines trust and encourages unethical conduct."}},{"itemId":"3b8fbb38-1a4c-5df4-a780-05eeff8de089","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ce5c2ef1-334e-5265-9648-0727f0e57d3e","sourceKey":"bank:BUA202:PQ-082-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of ethical leadership?","options":["Accountability","Secrecy and favouritism in decision-making","Fairness","Transparency"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Ethical leaders are open and treat people fairly, so secrecy and favouritism go against ethical leadership. Options D, A and C are core characteristics, together with honesty, integrity and respect."}},{"itemId":"824ba2f9-83eb-5d85-b91c-e26504fd661d","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7ed40f30-1ec4-5ef3-a6bc-41f5763f3cb2","sourceKey":"bank:BUA202:PQ-082-c","parentItemId":null,"revision":1,"payload":{"prompt":"A managing director openly admits that a costly decision was her mistake and takes responsibility for correcting it. Which characteristic of ethical leadership does she show?","options":["Accountability","Nepotism","Laissez-faire","Autocracy"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Accountability means accepting responsibility for one's decisions and their results, including mistakes. Option D is a leadership style where the leader decides alone, option B is an unethical practice of favouring relatives, and option C is a hands-off leadership style."}},{"itemId":"284b429f-f376-54d5-92d7-f2675f7dc0b3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e3c36d7e-22bc-505d-8505-fc9682c60fc6","sourceKey":"bank:BUA202:PQ-083-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manager gives a job to his nephew, who is less qualified than the other applicants. Which workplace ethical issue is this?","options":["Nepotism","Insider trading","Whistleblowing","Sexual harassment"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Nepotism is favouring relatives or family members in hiring or promotion instead of choosing on merit. Option C is reporting wrongdoing, option D is unwelcome sexual conduct, and option B is trading shares using non-public information."}},{"itemId":"575f0d49-49c5-5fa1-ad86-75e9a9e613cd","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"0e898624-0b9b-5194-9793-e26acc2bd3b8","sourceKey":"bank:BUA202:PQ-083-b","parentItemId":null,"revision":1,"payload":{"prompt":"A procurement officer awards a supply contract to a company that he secretly co-owns. This is an example of:","options":["Whistleblowing","Conflict of interest","Discrimination","Bullying"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A conflict of interest arises when a person's private interest clashes with their duty to the employer, as when an officer awards a contract to his own company. Option C is unfair treatment based on personal characteristics, option D is intimidation of colleagues, and option A is exposing wrongdoing."}},{"itemId":"1e6fbfc5-c569-500a-9154-e8349724ea35","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"f56b5319-038c-5db1-8ea7-1f309c3a4695","sourceKey":"bank:BUA202:PQ-083-c","parentItemId":null,"revision":1,"payload":{"prompt":"Refusing to promote a qualified employee because of her religion or ethnic group is:","options":["Nepotism","Whistleblowing","Embezzlement","Discrimination"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Discrimination is treating someone unfairly because of characteristics such as religion, ethnicity or gender rather than merit. Option A specifically means favouring relatives, option C is stealing funds placed in one's care, and option B is reporting wrongdoing."}},{"itemId":"07d07e93-2407-5c6b-aa7c-aa45de0fe49e","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"e3b37035-2dcc-57a4-ad9e-6c70c98fbebe","sourceKey":"bank:BUA202:PQ-083-d","parentItemId":null,"revision":1,"payload":{"prompt":"Using the company's official vehicle and fuel for private family trips without permission is an example of:","options":["Discrimination","Sexual harassment","Whistleblowing","Misuse of company resources"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Using the employer's property for personal purposes without approval is misuse of company resources. Options B and A concern how people are treated, and option C is reporting wrongdoing, not committing it."}},{"itemId":"d847edf7-82fb-5c27-a172-2a9311a5e74f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"44610f92-2ed1-5a59-881e-41e5d33593f9","sourceKey":"bank:BUA202:PQ-084-a","parentItemId":null,"revision":1,"payload":{"prompt":"Corruption is best defined as:","options":["Any business activity that makes a large profit","Lawful competition between firms","Reporting wrongdoing to the authorities","The abuse of entrusted power for private gain"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Corruption is using a position of power or trust for personal benefit, through bribery, embezzlement, fraud, kickbacks or money laundering. Options A and B are normal, legal business activities, and option C is whistleblowing, which helps fight corruption."}},{"itemId":"4839cc7e-896f-5f56-935b-273f70bc1033","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8f855d05-f7ff-5bcd-bd8c-18891d32410c","sourceKey":"bank:BUA202:PQ-084-b","parentItemId":null,"revision":1,"payload":{"prompt":"A finance officer secretly moves company funds placed in his care into his personal account. This is:","options":["Whistleblowing","Embezzlement","A kickback","Nepotism"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Embezzlement is stealing money that one has been trusted to manage. Option C is a secret payment returned to someone for steering business their way, option D is favouring relatives, and option A is reporting wrongdoing."}},{"itemId":"c0f3ab31-f4a6-58c5-9abf-177574c75859","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"8f2939bd-2806-5a19-8da0-78ef502f6b2d","sourceKey":"bank:BUA202:PQ-084-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which measure helps PREVENT corruption in an organisation?","options":["Allowing one person to authorise and approve all payments","Strong internal controls and regular auditing","Keeping financial records hidden from auditors","Removing protection for whistleblowers"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Internal controls and audits, together with transparency, accountability and anti-corruption laws, make it harder to hide wrongdoing. Options C, D and A all weaken checks and make corruption easier."}},{"itemId":"e1834dae-5944-592b-837b-925682db9b02","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"be6b7629-6960-5582-bcde-463c2c657f00","sourceKey":"bank:BUA202:PQ-085-a","parentItemId":null,"revision":1,"payload":{"prompt":"Sustainability is best defined as:","options":["Using up natural resources as fast as possible to grow quickly","Avoiding all business activity that uses resources","Meeting present needs without compromising the ability of future generations to meet their own needs","Maximising profit in the current year only"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Sustainability balances today's needs with those of future generations, so resources and the environment are not destroyed for short-term gain. Options D and A ignore the future, and option B is unrealistic because sustainability is about responsible use, not no use."}},{"itemId":"af0117ad-70fd-5bdd-ae8c-506cef0de1fb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"dc833b58-2342-5309-8b08-a54e794f5ae2","sourceKey":"bank:BUA202:PQ-085-b","parentItemId":null,"revision":1,"payload":{"prompt":"What are the three pillars of sustainability?","options":["Physiological, safety and esteem","Legal, political and technological","Planning, organising and controlling","Economic, social and environmental"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The three pillars are economic (long-term profitability), social (employee welfare, community development) and environmental (pollution control, recycling, energy conservation). Option A lists Maslow's needs, option B lists environmental forces, and option C lists management functions."}},{"itemId":"9db7e989-2f68-5943-b697-9b66e8145357","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"316beb27-9b39-5178-8b94-7b96390c0332","sourceKey":"bank:BUA202:PQ-085-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of ENVIRONMENTAL sustainability?","options":["Employee welfare programmes","Long-term profitability","Community development projects","Recycling waste and conserving energy"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Environmental sustainability protects the natural environment through actions such as pollution control, recycling and saving energy. Option B belongs to the economic pillar, while options A and C belong to the social pillar."}},{"itemId":"5735a26c-d814-5ce3-8a70-51acaa4ef0fb","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"7d9a2dce-15c4-51b8-a19e-5274767cdd0e","sourceKey":"bank:BUA202:PQ-085-d","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an example of responsible business conduct?","options":["Hiding product defects from customers","Dumping waste into rivers to cut costs","Paying taxes, treating workers fairly and producing safe products","Bribing officials to win contracts"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Responsible business conduct means respecting human rights, protecting the environment, obeying laws, treating workers fairly, making safe products, paying taxes and avoiding corruption. Options D, B and A are clear examples of irresponsible and unethical behaviour."}},{"itemId":"95a33ac8-c823-5e93-b555-94bc705d4480","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"a006f673-05bd-5edd-89ff-2ef53b8d7365","sourceKey":"bank:BUA202:PQ-086-a","parentItemId":null,"revision":1,"payload":{"prompt":"How many steps or stages are in Kotter's change model and Lewin's change model respectively?","options":["Eight and five","Eight and three","Three and eight","Six and three"],"correctOption":1,"section":"Organisational Change and Change Management","explanation":"Kotter's model has eight steps, from creating urgency to anchoring the change, while Lewin's has three stages: unfreeze, change and refreeze. Option C swaps the two, and options D and A give numbers that match neither model."}},{"itemId":"fe5d1200-1169-5db6-a702-628132e87ec6","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"198b4049-d851-532d-a21f-13cb20ac52b2","sourceKey":"bank:BUA202:PQ-086-b","parentItemId":null,"revision":1,"payload":{"prompt":"In Kotter's model, which step involves dealing with barriers, such as outdated systems or resistant structures, that block the change?","options":["Remove obstacles","Anchor the change","Create short-term wins","Develop a vision"],"correctOption":0,"section":"Organisational Change and Change Management","explanation":"Removing obstacles (step five) clears away barriers and supplies the resources people need so they can act on the vision. Option C is about celebrating early successes, option D is about picturing the future, and option B is about making the change part of the culture."}},{"itemId":"90570fe9-1a7e-5af8-9290-e2dcfc977cf3","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"ff734601-78ad-54ab-aae9-28ed172514aa","sourceKey":"bank:BUA202:PQ-087-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which writer defined HRM as the planning, organising, directing and controlling of the procurement, development, compensation, integration, maintenance and separation of human resources?","options":["Robert L. Mathis and John H. Jackson","Edwin B. Flippo","John Storey","R. Wayne Mondy"],"correctOption":1,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Edwin B. Flippo's classic definition lists six operative functions - procurement, development, compensation, integration, maintenance and separation - giving an operational, administrative view of managing people. Option D defined HRM simply as using individuals to achieve organisational objectives, option C is linked with the hard versus soft HRM distinction, and option A described HRM as designing formal systems to manage human talent."}},{"itemId":"1918dafc-1e62-5cd3-847e-8b89dfa856e0","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"440094f8-9704-4c6d-8e4c-ded8be13dc59","sourceKey":"quiz:138","parentItemId":null,"revision":2,"payload":{"prompt":"The informal communication network through which information spreads within an organisation outside official channels is called:","options":["The grapevine","Downward communication","The organisation chart","A policy document"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"The grapevine is the unofficial network of conversations and social contacts through which information travels at work. Option B is a formal channel. Options C and D represent official structures and documents, which are formal by definition."}},{"itemId":"87e262d1-440c-5e57-883f-7332bfdd1a64","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"5c3d7bf4-355c-40bc-b29d-317c9ff2b8bf","sourceKey":"quiz:15","parentItemId":null,"revision":2,"payload":{"prompt":"Structuring pay, rewards and incentives falls under which functional area of HRM?","options":["Workforce planning","Recruitment and selection","Training and development","Compensation management"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Compensation management is the HRM area that designs pay, rewards and incentives. Option C builds skills and certifications, option B finds and hires talent, and option A sizes the workforce to fit strategy."}},{"itemId":"1192f48e-8790-5edb-a338-fd6ca7fa2771","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b106af01-37b8-4086-a521-53224f38051d","sourceKey":"quiz:17","parentItemId":null,"revision":2,"payload":{"prompt":"The collective skills, knowledge and abilities of employees that contribute to an organisation's value are known as","options":["Working capital","Employee engagement","Talent management","Human capital"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Human capital is the value held in employees' skills, knowledge and abilities. Option C is the strategy for attracting and developing such people, option B is their emotional commitment, and option A is a finance term for current assets minus current liabilities."}},{"itemId":"92fe35c3-217b-5c4e-b2d8-b3636a0f593a","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"17e73634-2829-4e1f-a975-1d66f9426759","sourceKey":"quiz:18","parentItemId":null,"revision":2,"payload":{"prompt":"The emotional commitment an employee has to the organisation and its goals is called","options":["Goal alignment","Job specification","Human capital","Employee engagement"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Employee engagement is the emotional commitment staff feel towards the organisation and its goals. Option C is the skills and knowledge they hold, option B is a statement of a job's required qualifications, and option A is HR's work of linking individual output to corporate goals."}},{"itemId":"b89fab99-d49b-5314-b23f-35f435f7d37f","courseId":"40000000-0000-4000-8000-000000000011","kind":"cbt_question","questionId":"b170fee5-2fe2-439e-8864-7e48beb727cb","sourceKey":"quiz:252","parentItemId":null,"revision":2,"payload":{"prompt":"What is the correct order of the five stages of group development?","options":["Forming, Norming, Storming, Performing, Adjourning","Forming, Storming, Norming, Performing, Adjourning","Storming, Forming, Norming, Adjourning, Performing","Norming, Forming, Storming, Performing, Adjourning"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Groups first come together (forming), then go through friction as opinions clash (storming), settle on norms and trust (norming), become productive (performing), and finally disband (adjourning). Options A, C and D each put at least one stage out of sequence; in particular, norming comes after storming, not before it."}}]$expected_content$::jsonb,
  'principles-business-administration-2: cbt_question published payload and identity match source');
