    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '40000000-0000-4000-8000-000000000012' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"27b852d0-a0aa-5bc7-8597-9a9b2b2ec66b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"535d4b8b-f316-52f5-9b48-77e8791d8c50","sourceKey":"bank:BUA204:ANL-001","parentItemId":null,"revision":1,"payload":{"prompt":"An Ikeja electronics shop budgeted sales revenue of N80 million for the year and actually achieved N86 million. Using Variance (%) = [(Actual - Budget) / Budget] x 100, what is the variance?","options":["+7.5%, adverse","-7.5%, adverse","+7.0%, favourable","+7.5%, favourable"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Variance = 86 - 80 = +N6 million, and 6 / 80 x 100 = +7.5%; revenue above budget is favourable. Option C divides by actual revenue (6 / 86 = 7.0%) instead of budget, and Option A misclassifies higher-than-budget revenue as adverse."}},{"itemId":"fd4433c8-60cf-52eb-9f42-406c7a3047e6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8316e7ea-9d14-558a-ba8d-6b6d2d226fb7","sourceKey":"bank:BUA204:ANL-002","parentItemId":null,"revision":1,"payload":{"prompt":"A Kaduna textile firm budgeted N4.5 million for factory overheads but actually spent N4.05 million. What is the cost variance?","options":["N450,000 adverse","N450,000 favourable","N45,000 favourable","N405,000 favourable"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Variance = 4,050,000 - 4,500,000 = -N450,000, and because actual cost is below budget the variance is favourable. Option A applies the revenue rule to a cost, and Option D and Option C are slips in the subtraction."}},{"itemId":"6192b37a-4f14-5e75-be56-7b42df22e414","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f54115e9-2f26-5fb7-b147-51144f096f06","sourceKey":"bank:BUA204:ANL-003","parentItemId":null,"revision":1,"payload":{"prompt":"A Benin distributor budgeted a monthly profit of N60 million but made N54 million. What is the percentage variance (to 1 decimal place)?","options":["-10.0%","-6.0%","+10.0%","-11.1%"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Variance (%) = (54 - 60) / 60 x 100 = -6 / 60 x 100 = -10.0%, an adverse variance because profit fell short of budget. Option D wrongly divides by the actual figure (6 / 54), Option C has the wrong sign, and Option B gives the naira shortfall in millions as if it were a percentage."}},{"itemId":"996650ba-7cdb-51cc-ac26-bd060f7db218","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"944419e8-5335-558c-a95d-829edfbb45bc","sourceKey":"bank:BUA204:ANL-004","parentItemId":null,"revision":1,"payload":{"prompt":"Actual vs budgeted sales (N million) for a Lagos retailer were: Q1 42 vs 40; Q2 63 vs 70; Q3 38 vs 44; Q4 60 vs 55. Which quarter had the largest adverse variance in percentage terms?","options":["Q4","Q1","Q3","Q2"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Percentage variances are Q1 +5.0%, Q2 -10.0%, Q3 -13.6% (-6 / 44) and Q4 +9.1%, so Q3 is the worst in percentage terms. Option D has the biggest shortfall in naira (-N7 million), but measured against its larger budget it is a smaller percentage, and Q1 and Q4 are favourable."}},{"itemId":"002932f7-5987-5765-aed5-8b4b0b189097","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bbec6faf-6f15-59de-b2c8-ff06599eb334","sourceKey":"bank:BUA204:ANL-005","parentItemId":null,"revision":1,"payload":{"prompt":"Actual vs budgeted sales (N million) for a Lagos retailer were: Q1 42 vs 40; Q2 63 vs 70; Q3 38 vs 44; Q4 60 vs 55. What is the overall variance for the year as a percentage of the annual budget (to 2 decimal places)?","options":["-2.96%","+2.87%","-2.39%","-2.87%"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Annual actual is 203 and annual budget is 209, so variance = (203 - 209) / 209 x 100 = -2.87%, a small adverse variance overall. Option A divides by actual instead of budget, Option C averages the four quarterly percentages (which gives each quarter equal weight regardless of size), and Option B has the wrong sign."}},{"itemId":"9457f53d-37ee-5c38-b568-dc6d62cba05a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3960e4ee-2c4a-56cb-92b9-9c61483f02b1","sourceKey":"bank:BUA204:ANL-006","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N360,000, a selling price of N200 and a variable cost of N120 per unit. In a sensitivity test, the price is cut by 10% with all else unchanged. What is the new break-even point?","options":["2,000 units","6,000 units","4,950 units","4,091 units"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"The new price is 200 x 0.9 = 180, so contribution per unit = 180 - 120 = 60 and BEP = 360,000 / 60 = 6,000 units (up from 4,500). Option C just raises the old BEP by 10%, Option A divides fixed cost by price instead of contribution, and Option D wrongly reduces the BEP."}},{"itemId":"bd553302-e6ef-5816-aa14-5611bab138ae","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"07adc78d-3b87-58a9-b1e3-f8464cf3b763","sourceKey":"bank:BUA204:ANL-007","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N600,000, a selling price of N400 and a variable cost of N250 per unit. If fixed costs rise by 20%, all else unchanged, what is the new break-even point?","options":["5,760 units","3,333 units","4,000 units","4,800 units"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"New FC = 600,000 x 1.2 = 720,000 and contribution is still 400 - 250 = 150, so BEP = 720,000 / 150 = 4,800 units, exactly 20% above the original 4,000. Option C is the original BEP, Option B divides the old BEP by 1.2, and Option A applies the 20% rise twice."}},{"itemId":"f8bc54e5-65fd-5bb6-a73f-61de40930195","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6c20116f-519a-5a4b-a1c1-ada785ee593a","sourceKey":"bank:BUA204:ANL-008","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N270,000, a price of N300 and a variable cost of N200 per unit. Variable cost rises by 8%. What is the new break-even point, rounded UP to the next whole unit?","options":["3,214 units","2,916 units","2,500 units","3,215 units"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"New variable cost = 200 x 1.08 = 216, so contribution = 300 - 216 = 84 and BEP = 270,000 / 84 = 3214.29, rounded up to 3,215 because a part unit cannot be sold. Option A rounds down, which leaves the firm just short of break-even, Option B simply raises the old BEP of 2,700 by 8%, and Option C reduces the variable cost instead of raising it."}},{"itemId":"ac38150d-9482-54ca-a17a-f8a4af942c20","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"73f48f5c-39d9-5b0c-be13-79100a556468","sourceKey":"bank:BUA204:ANL-009","parentItemId":null,"revision":1,"payload":{"prompt":"Monthly advertising spend x (N'000) and sales y (N'000) for a Yaba shop are: (2, 5), (4, 9), (6, 10), (8, 15), (10, 16). Using r = Sum[(x - x-bar)(y - y-bar)] / sqrt{Sum(x - x-bar)^2 x Sum(y - y-bar)^2}, what is Pearson's r (to 2 decimal places)?","options":["0.98","0.46","0.96","1.40"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Here x-bar = 6 and y-bar = 11, Sum(x - x-bar)(y - y-bar) = 56, Sum(x - x-bar)^2 = 40 and Sum(y - y-bar)^2 = 82, so r = 56 / sqrt(40 x 82) = 0.98, a strong positive relationship. Option C is r squared, Option D is the regression slope b, and Option B adds the two sums of squares instead of multiplying them under the square root."}},{"itemId":"e78d8c81-2f1a-5b30-9884-0f9782f44a38","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"879d8a3e-4428-5f09-9f36-293a79fd6bcf","sourceKey":"bank:BUA204:ANL-010","parentItemId":null,"revision":1,"payload":{"prompt":"For 5 pairs of observations, n = 5, Sum x = 15, Sum y = 34, Sum xy = 117, Sum x^2 = 55 and Sum y^2 = 264. Using r = [n Sum xy - Sum x Sum y] / sqrt{[n Sum x^2 - (Sum x)^2][n Sum y^2 - (Sum y)^2]}, what is r (to 2 decimal places)?","options":["1.50","0.83","0.13","0.69"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Numerator = 5(117) - 15(34) = 75; denominator = sqrt[(5(55) - 15^2)(5(264) - 34^2)] = sqrt(50 x 164) = 90.55, so r = 75 / 90.55 = 0.83. Option D is r squared, Option A is the regression slope b, and Option C forgets to square Sum x and Sum y in the denominator."}},{"itemId":"2227ca66-1009-5caf-ab81-5afc6b874624","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2b81948a-fc82-596c-9d91-53279550837f","sourceKey":"bank:BUA204:ANL-011","parentItemId":null,"revision":1,"payload":{"prompt":"A study of Lagos supermarkets finds a correlation of r = 0.8 between shelf space and sales. What percentage of the variation in sales is explained by shelf space?","options":["36%","64%","80%","89%"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"The coefficient of determination is r^2 = 0.8^2 = 0.64, so 64% of the variation in sales is explained by shelf space. Option C reads r itself as the percentage explained, Option A is the unexplained part (1 - 0.64), and Option D takes the square root of 0.8 instead of squaring it."}},{"itemId":"7c56c889-82c1-5d5e-959b-8a86cd505284","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"044441a5-bdf0-5a6f-a9f8-7d5adf3b383d","sourceKey":"bank:BUA204:ANL-012","parentItemId":null,"revision":1,"payload":{"prompt":"A regression of weekly demand on price gives R^2 = 0.49 and a negative slope. What is the correlation coefficient r?","options":["+0.7","-0.49","-0.24","-0.7"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"r is the square root of R^2, so |r| = sqrt(0.49) = 0.7, and it takes the sign of the slope, giving r = -0.7. Option A ignores the negative slope, Option B treats R^2 as if it were r, and Option C squares 0.49 instead of taking its square root."}},{"itemId":"b5d3bb34-452b-5d5a-b721-371204f17c42","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d4f261f8-defe-5f2a-a2d1-5e7a3ad07014","sourceKey":"bank:BUA204:ANL-013","parentItemId":null,"revision":1,"payload":{"prompt":"The regression of monthly sales (y, N'000) on advertising spend (x, N'000) for an Owerri firm is y = 120 + 4.5x. What are predicted sales when advertising spend is N20,000?","options":["N2,490,000","N90,000","N210,000","N124,500"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Substituting x = 20 gives y = 120 + 4.5(20) = 120 + 90 = 210 thousand, i.e. N210,000. Option B leaves out the intercept, Option D forgets to multiply the slope by x, and Option A multiplies the whole of (120 + 4.5) by 20."}},{"itemId":"e031714a-843c-5769-b22e-c0d4d9bb2833","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0c3a3a60-3cf7-5c40-888e-167afed91fd1","sourceKey":"bank:BUA204:ANL-014","parentItemId":null,"revision":1,"payload":{"prompt":"The regression equation of sales (y, N'000) on advertising (x, N'000) is y = 50 + 3x. In business language, if advertising is increased by N5,000, sales are expected to:","options":["Rise by N15,000","Rise by N65,000","Rise by N8,000","Rise by N3,000"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"The slope b = 3 means each extra N1,000 of advertising adds about N3,000 of sales, so N5,000 more advertising adds 3 x 5 = 15 thousand. Option D gives the effect of only N1,000, Option B is the predicted total sales at x = 5 (50 + 15) rather than the change, and Option C adds 5 and 3."}},{"itemId":"0bae6b3c-ef76-5887-949b-9a66d0af8165","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f00b210a-47b7-5e94-985e-6d440e8858f5","sourceKey":"bank:BUA204:ANL-015","parentItemId":null,"revision":1,"payload":{"prompt":"A demand study for a soft drink gives the regression y = 900 - 15x, where y is daily crates sold and x is the price in naira per bottle. What is predicted demand at a price of N40?","options":["885 crates","1,500 crates","35,400 crates","300 crates"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"y = 900 - 15(40) = 900 - 600 = 300 crates; the negative slope means demand falls by 15 crates for each N1 rise in price. Option B adds instead of subtracting, Option A subtracts only one slope unit, and Option C multiplies (900 - 15) by 40."}},{"itemId":"e442ff23-9429-5c04-869f-a0649f27677e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"de0f155e-1d0f-5642-b0ca-ca04fef78730","sourceKey":"bank:BUA204:ANL-016","parentItemId":null,"revision":1,"payload":{"prompt":"A test of whether a new training programme changed average output gives a p-value of 0.03. Using the rule 'reject H0 when the p-value is less than the significance level', what is the conclusion?","options":["Significant at both the 5% and the 1% levels","Not significant at either level","Not significant at the 5% level but significant at the 1% level","Significant at the 5% level but not at the 1% level"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Since 0.03 < 0.05, H0 is rejected at the 5% level, but since 0.03 > 0.01 it is not rejected at the stricter 1% level. Option A forgets that the 1% level needs p below 0.01, and Option C reverses the logic, because a stricter level is always harder to pass."}},{"itemId":"279edbea-fbfe-5161-86d9-e52d83169920","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cf03c6d0-30dd-5678-9d9b-67ce8d9d7986","sourceKey":"bank:BUA204:ANL-017","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos logistics firm's annual revenue rose from N40 million to N50 million. In a trend interpretation, what is the percentage increase?","options":["125%","25%","10%","20%"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Percentage change = (50 - 40) / 40 x 100 = 25%, measured against the starting value. Option D divides by the new value (10 / 50), Option C reads the N10 million change as a percentage, and Option A is the ratio of new to old revenue, not the increase."}},{"itemId":"88c86730-b30a-5390-a948-76a8b443711e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f813d884-053d-51f9-bf41-f303b04e2656","sourceKey":"bank:BUA204:ANL-018","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst reports that average sales in Q3 fell by 12%, then explains that this matters because it signals weakening customer demand that could hurt year-end profit. The second part of her work is best described as:","options":["Data analysis, because it answers 'How?' and 'What?'","Data presentation, because it uses a chart","Data collection, because it gathers new facts","Data interpretation, because it answers 'So what?' and 'Why?'"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Data interpretation explains what a result means for the business, answering 'So what?' and 'Why?'. Working out that sales fell 12% is data analysis (Option A), which answers 'How?' and 'What?', and nothing in the scenario involves collecting (Option C) or charting (Option B) data."}},{"itemId":"eb71c2ae-b729-59ff-869e-45b72a119aaf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e72b471f-f79f-522a-8f20-f50476d1d8ec","sourceKey":"bank:BUA204:ANL-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three main techniques for interpreting quantitative findings for management?","options":["Network analysis","Trend analysis","Sensitivity analysis","Variance analysis"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"The three interpretation techniques are variance analysis (actual vs budget), trend analysis (direction over time) and sensitivity analysis (what-if testing). Network analysis is a scheduling technique (critical path planning), so it is not one of them, while Option D, Option B and Option C all are."}},{"itemId":"98fed646-2324-530d-a17d-e9f67af66a26","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4846c2da-f71f-5fef-a90f-61e0da4eb8b3","sourceKey":"bank:BUA204:ANL-020","parentItemId":null,"revision":1,"payload":{"prompt":"Demand for mobile data in Nigeria has risen gradually and steadily over the past ten years as smartphone use has spread. This pattern is a:","options":["Secular trend","Seasonal variation","Cyclical variation","Random variation"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"A secular trend is a gradual long-term movement in one direction, typically caused by things like population growth or technology adoption. Seasonal variation (Option B) repeats within each year, cyclical variation (Option C) follows boom-and-recession swings, and random variation (Option D) comes from one-off shocks."}},{"itemId":"6917386a-efff-55fe-a4b5-a94a93d80a7f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d2b99b0c-f5f2-514e-b3f9-a2c49f6151fa","sourceKey":"bank:BUA204:ANL-021","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano clothing retailer's sales jump every year in the weeks before Sallah and Christmas, then fall back. This pattern is best described as:","options":["Cyclical variation","Seasonal variation","Random variation","Secular trend"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"A regular pattern that repeats within each year, such as festive-season demand, is seasonal variation. A secular trend (Option D) is a long-term gradual movement, cyclical variation (Option A) is a longer, irregular swing linked to the business cycle, and random variation (Option C) is unpredictable."}},{"itemId":"04663ec6-78f6-50a7-901f-aa5c941082da","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"66bbb894-e933-51c0-8b7c-d8564a461f3c","sourceKey":"bank:BUA204:ANL-022","parentItemId":null,"revision":1,"payload":{"prompt":"A cement company's sales rise for several years during an economic boom and then fall for some years during a recession. This pattern is:","options":["Cyclical variation","Random variation","Secular trend","Seasonal variation"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Cyclical variation is a longer, irregular swing linked to the wider business cycle of boom and recession. Seasonal variation (Option D) repeats within a single year, a secular trend (Option C) moves steadily in one direction, and random variation (Option B) is a one-off shock."}},{"itemId":"455d128a-e96c-5619-bd9b-830d48034126","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cee900cc-7015-559b-8059-b6570c8c8e37","sourceKey":"bank:BUA204:ANL-023","parentItemId":null,"revision":1,"payload":{"prompt":"A dock workers' strike shuts Apapa port for two weeks, causing a one-off dip in an importer's monthly sales. In time series terms, this dip is:","options":["Random (irregular) variation","Cyclical variation","Seasonal variation","Secular trend"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Random or irregular variation covers unpredictable, one-off fluctuations such as strikes, natural disasters or policy shocks. Seasonal (Option C) and cyclical (Option B) variations are recurring patterns, and a secular trend (Option D) is a long-term movement."}},{"itemId":"a2b4d950-4bac-54fc-b03f-31ed2f7294fb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"83ac234a-86a0-5292-92ed-b2496cb49b16","sourceKey":"bank:BUA204:ANL-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a favourable variance?","options":["Actual labour cost is above the budgeted labour cost","Actual profit is below the budgeted profit","Actual revenue is below the budgeted revenue","Actual material cost is below the budgeted material cost"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"A variance is favourable when results are better than budget, which for a cost means spending less than planned. Option C and Option B are adverse because revenue and profit fell short of budget, and Option A is adverse because the cost was higher than planned."}},{"itemId":"19d29584-d16c-5b89-a44c-20f026749445","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e0ddd9d0-831c-55ec-8892-e38cf4275ad9","sourceKey":"bank:BUA204:ANL-025","parentItemId":null,"revision":1,"payload":{"prompt":"Comparing actual performance with a budgeted or target figure, expressing the difference in naira and percentage terms, and classifying it as favourable or adverse is called:","options":["Regression analysis","Variance analysis","Trend analysis","Sensitivity analysis"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Variance (deviation) analysis compares actual results with a budget or target and labels each difference favourable or adverse. Trend analysis (Option C) studies direction of movement over time, sensitivity analysis (Option D) re-runs a model with changed inputs, and regression (Option A) fits a prediction line."}},{"itemId":"0f064376-85d0-5b4b-ad21-830c77c6f270","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2baa3b96-b9e9-5098-9dc9-4b5217e39509","sourceKey":"bank:BUA204:ANL-026","parentItemId":null,"revision":1,"payload":{"prompt":"A manager re-runs a break-even model several times, changing price, then variable cost, then fixed cost, to see which change moves the result most. The main benefit of this sensitivity analysis is that it:","options":["Compares actual results with the budget","Shows which assumptions the result is most sensitive to, so they get the closest scrutiny","Removes the need for accurate input data","Guarantees that the break-even point will be achieved"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Sensitivity ('what-if') analysis tests how robust a result is by changing key inputs, revealing which assumptions matter most and deserve careful checking. It cannot guarantee an outcome (Option D) or replace good data (Option C), and comparing actual with budget (Option A) is variance analysis."}},{"itemId":"d7b5ff17-f206-5155-9e05-27ebc5d24628","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2a32aa29-5c26-5bf8-886e-9957696bd8b9","sourceKey":"bank:BUA204:ANL-027","parentItemId":null,"revision":1,"payload":{"prompt":"In a business report presenting quantitative findings, the Title Page should state:","options":["The report title, author, recipient and date","The data sources and techniques used","A one-paragraph summary of findings and the recommendation","Detailed workings and raw data"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"The Title Page identifies the report: its title, who wrote it, who it is for and the date. A one-paragraph overview (Option C) is the Executive Summary, data sources and techniques (Option B) belong in the Methodology, and detailed workings (Option D) go in the Appendices."}},{"itemId":"d71fbcaa-5245-5c1f-b976-6ac8ab9e40a3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7b196014-3ab3-5c53-9b75-329e182e9993","sourceKey":"bank:BUA204:ANL-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which section of a business report states the purpose, scope and background of the analysis?","options":["Executive Summary","Conclusion and Recommendations","Introduction / Terms of Reference","Methodology"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"The Introduction or Terms of Reference sets out why the analysis was done, what it covers and the background. The Executive Summary (Option A) gives a brief overview of findings for busy readers, the Methodology (Option D) explains data and techniques, and the Conclusion (Option B) says what action to take."}},{"itemId":"c1c9e178-e3f6-54a9-bf04-c4154e78d6d1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7ca08c6f-5f7f-5498-92b5-870d0b53df46","sourceKey":"bank:BUA204:ANL-029","parentItemId":null,"revision":1,"payload":{"prompt":"In a report to the board of a Lagos bank, the section containing the regression results, supporting tables and charts is the:","options":["Executive Summary","Findings / Analysis section","Appendices","Methodology section"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Findings / Analysis is where results are presented, supported by tables, charts and calculations. Methodology (Option D) only explains which data and techniques were used, the Executive Summary (Option A) is a brief overview, and the Appendices (Option C) hold detailed workings and raw data for verification."}},{"itemId":"1b5bcaac-2051-5040-ad22-be33bd2771e0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ee19fd27-e5e2-5fc0-bb61-f867fe5ee94e","sourceKey":"bank:BUA204:ANL-030","parentItemId":null,"revision":1,"payload":{"prompt":"The section of a business report that summarises what the findings mean and states what action should be taken is the:","options":["Introduction / Terms of Reference","Findings / Analysis","Conclusion and Recommendations","Title Page"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Conclusion and Recommendations translates the findings into meaning and a recommended course of action. Findings (Option B) present the results themselves, the Introduction (Option A) gives purpose and scope, and the Title Page (Option D) only identifies the report."}},{"itemId":"6cc4db65-7d88-5f78-895d-03cca1a07f8e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b6742c9c-40e2-5057-b0b0-668b220d236b","sourceKey":"bank:BUA204:ANL-031","parentItemId":null,"revision":1,"payload":{"prompt":"In the standard seven-section structure of a business report presenting quantitative findings, which section comes immediately before Findings / Analysis?","options":["Conclusion and Recommendations","Introduction / Terms of Reference","Methodology","Executive Summary"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"The order is Title Page, Executive Summary, Introduction / Terms of Reference, Methodology, Findings / Analysis, Conclusion and Recommendations, then Appendices. The reader needs to know how the data were obtained and analysed before seeing the results, which is why Methodology sits just before Findings; Option B comes one step earlier."}},{"itemId":"3ebd7108-9caf-5486-8d02-72563970b3af","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7b98a298-0661-571c-a26e-4178504c8bc2","sourceKey":"bank:BUA204:ANL-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the seven standard sections of a business report presenting quantitative findings?","options":["Appendices","Executive Summary","Methodology","Statement of Cash Flows"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"The seven sections are Title Page, Executive Summary, Introduction / Terms of Reference, Methodology, Findings / Analysis, Conclusion and Recommendations, and Appendices. A Statement of Cash Flows is a financial statement, not a report section, while Option B, Option C and Option A are all standard sections."}},{"itemId":"4f41c7ae-6ad1-5bd2-837d-c211d480e869","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ef53d2ef-0e30-51b8-a67a-02a989c23a9b","sourceKey":"bank:BUA204:ANL-033","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst fits a regression of sales on advertising using only five months of data. How should she present the prediction in her report?","options":["As a definitive prediction, since regression is objective","Without the figures, to avoid confusing the reader","Only in the Appendices, never in the Findings","With an explicit caution that the small sample limits its reliability"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"A finding should always be reported alongside its limitations, and a regression based on only five data points needs a clear caution about the small sample. Presenting it as definitive (Option A) overstates its reliability, while hiding it (Option C and Option B) withholds a relevant result from decision makers."}},{"itemId":"e69ec320-5de5-52ba-a5d3-5466f54829da","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0714d3f5-6c6d-5403-8ca2-cb9020051dad","sourceKey":"bank:BUA204:ANL-034","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian survey firm feeds a model with sales data that contain many typing errors and missing months, and the model's forecast proves badly wrong. Which limitation of quantitative findings does this illustrate?","options":["Correlation does not prove causation","Past patterns may not continue","Garbage in, garbage out (GIGO)","Models omit qualitative factors"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"GIGO means the accuracy of any result depends on the quality of the input data, so biased or incomplete data give misleading conclusions however correct the technique. Option A, Option B and Option D are real limitations too, but none of them describes errors in the data themselves."}},{"itemId":"65e92374-794f-5e26-802b-7513272338e7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1ec969dd-1b69-54e5-9155-e7bb169cf1aa","sourceKey":"bank:BUA204:ANL-035","parentItemId":null,"revision":1,"payload":{"prompt":"A trainee analyst writes four statements about the reliability of quantitative findings. Which statement is INCORRECT?","options":["A correctly applied technique removes the need to check the quality of the input data","Past trends may not continue into the future","Over-reliance on one optimal answer can crowd out managerial judgement","Models may omit qualitative factors such as competitor reaction"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"This statement is incorrect, because even a correctly applied technique gives misleading results when fed poor data (garbage in, garbage out). Option D, Option B and Option C are genuine limitations: models simplify reality, past patterns can break, and a single number should not replace judgement."}},{"itemId":"3fc1f80d-aaa0-5e53-9925-b24fba46429d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e891e751-262a-5188-9f7f-f54b10ab3fd7","sourceKey":"bank:BUA204:ANL-036","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos importer bases next year's budget on a steady three-year sales trend, but a sudden currency devaluation sharply changes demand. Which limitation of quantitative findings does this show?","options":["A small sample always gives a perfect forecast","Correlation does not establish causation","Past patterns may not continue into the future","Garbage in, garbage out"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Trends and correlations from the past may not continue, especially in volatile or rapidly changing markets such as one hit by a devaluation. The data here were accurate, so GIGO (Option D) does not apply, and Option B is about cause and effect between two variables; Option A is simply untrue."}},{"itemId":"7bce3b13-e570-51e6-bcc2-1d6f91d6aced","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"05df66b2-74ab-5f43-9d60-f41e59e9d18d","sourceKey":"bank:BUA204:ANL-037","parentItemId":null,"revision":1,"payload":{"prompt":"Across Nigerian states, monthly umbrella sales and malaria cases are strongly positively correlated. The most sensible interpretation is that:","options":["Buying umbrellas causes malaria","Malaria causes people to buy umbrellas","A third factor, the rainy season, probably drives both","The correlation must be a calculation error"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Correlation shows association, not cause and effect; both variables rise in the rainy season, so the weather is a lurking third variable explaining the link. Option A and Option B wrongly read causation into the correlation, and Option D is wrong because a genuine correlation can exist without a direct causal link."}},{"itemId":"f496f697-ff7e-52f8-81dd-15f43021f80d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"78ad45bc-d792-5872-9ff9-0c092b9741f5","sourceKey":"bank:BUA204:ANL-039","parentItemId":null,"revision":1,"payload":{"prompt":"Study X finds r = -0.85 between price and demand, while Study Y finds r = +0.6 between advertising and sales. Which statement is correct?","options":["Study X shows the stronger linear relationship, but in the opposite direction","Study X shows no relationship because r is negative","Both relationships are equally strong","Study Y shows the stronger relationship because its r is positive"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Strength depends on how close r is to +1 or -1 (its size), and the sign shows direction, so |-0.85| > |0.6| means X is stronger but negative. Option D confuses direction with strength, and Option B is wrong because a negative r indicates an inverse relationship, not no relationship."}},{"itemId":"fd8f59c2-c98d-59df-9ecb-bd0056908100","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"450add14-3357-5846-ad45-9914835b0289","sourceKey":"bank:BUA204:ANL-040","parentItemId":null,"revision":1,"payload":{"prompt":"A scatter diagram shows a clear U-shaped pattern between temperature and sales, yet Pearson's r is close to 0. What is the correct interpretation?","options":["The data must contain errors","There is little linear relationship, but a strong non-linear one may still exist","There is a perfect positive relationship","There is definitely no relationship of any kind"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Pearson's r measures only the strength of a linear relationship, so a value near 0 means no straight-line pattern, not no relationship at all; a curved pattern can give r close to 0. Option D over-reads the result, Option C contradicts r near 0, and Option A assumes an error with no evidence."}},{"itemId":"441fbfd3-fb2d-5a7b-afba-f0a312816e9d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8d48e0e8-2442-53d9-8e82-f3a545afe232","sourceKey":"bank:BUA204:ANL-041","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company tests whether a new training programme affects average output. The statement 'the training programme has no effect on average output' is the:","options":["Alternative hypothesis (H1)","Level of significance","Null hypothesis (H0)","Type I error"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"The null hypothesis is the default assumption that no effect or difference exists. The alternative hypothesis (Option A) is what the firm is trying to prove, that the training does have an effect, while a Type I error (Option D) and the significance level (Option B) relate to the decision rule, not the claim being tested."}},{"itemId":"0971a87d-c2f0-5741-b9a9-c61571607ce8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"68e5031a-fd7b-593d-94b6-8ab064f7b9e6","sourceKey":"bank:BUA204:ANL-042","parentItemId":null,"revision":1,"payload":{"prompt":"A bank concludes that a new loan policy reduced defaults when, in reality, it had no effect. This mistake is a:","options":["Type I error","Sampling frame error","Type II error","Confirmation of the null hypothesis"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Rejecting a true null hypothesis (here 'the policy has no effect') is a Type I error, a false positive. A Type II error (Option C) is the opposite: failing to reject a false null hypothesis. Option D is wrong because the bank actually rejected the null hypothesis."}},{"itemId":"7b9b72c2-0c97-5881-be30-537141545bbc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7a929e84-d996-5ded-b169-8b0efe3c0ee9","sourceKey":"bank:BUA204:ANL-043","parentItemId":null,"revision":1,"payload":{"prompt":"When a researcher tests at a 5% significance level (alpha = 0.05), the 0.05 represents:","options":["The probability that the null hypothesis is true","The proportion of variation explained by the model","The probability of rejecting a true null hypothesis (Type I error)","The probability of failing to reject a false null hypothesis"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"The significance level alpha is the probability of a Type I error, rejecting H0 when it is actually true. Option D describes beta, the Type II error probability, Option B describes R^2, and Option A is a common misreading, because alpha is set before the test and is not the probability that H0 is true."}},{"itemId":"713f7d6c-57d9-5727-b978-ef1b4c963fb4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"076998d9-dcb0-5c4e-81c3-9a4afd65e238","sourceKey":"bank:BUA204:ANL-044","parentItemId":null,"revision":1,"payload":{"prompt":"After trying a new menu in only two of its 40 Lagos branches for one week, a restaurant chain concludes that the menu raises sales everywhere. Which interpretation problem is most likely?","options":["Confirmation bias","Correlation vs causation","Small sample size, so the result may be due to chance","Data quality issues"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Conclusions drawn from very small samples, here two branches over one week, may reflect chance rather than a true pattern. Confirmation bias (Option A) means reading data to fit existing beliefs, Option B concerns mistaking association for cause, and nothing suggests the sales figures themselves were inaccurate (Option D)."}},{"itemId":"1057e7e3-8d0b-545a-93ac-82b9f2417580","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b9ad4dce-0948-592c-88f8-cc85f7d31a6a","sourceKey":"bank:BUA204:ANL-045","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst tells the managing director of an Ibadan firm only that 'the EMV is N68,000'. Why is this report incomplete?","options":["EMV figures must always be shown in the Appendices only","The figure means little until its implications for risk, strategy and action are explained","The managing director should be given the raw data instead","An EMV must always be reported as a percentage"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"A correct calculation is only half of quantitative analysis; the other half is interpreting what it means for the organisation and what action should follow. Hiding the result in the Appendices (Option A), giving raw data only (Option C) or forcing a percentage (Option D) does not explain its meaning to a non-technical reader."}},{"itemId":"981e89f4-2bae-54ea-b55c-4c246690e023","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"326214f4-f140-5fb1-8189-3004b12fb46a","sourceKey":"bank:BUA204:DAT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of measuring and gathering information and variables in an established, systematic fashion that enables one to answer stated hypotheses and evaluate actions is called:","options":["Data collection","Data presentation","Tabulation","Data interpretation"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Data collection is the systematic measuring and gathering of information so that stated hypotheses can be answered and actions evaluated. Option B comes later and shows the data in charts and tables, option C is arranging data in rows and columns, and option D is drawing meaning from data that have already been gathered."}},{"itemId":"16cffed6-94e9-5990-9b01-91601cd60468","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"48610641-5753-5a1f-a574-917a918d3164","sourceKey":"bank:BUA204:DAT-002","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket manager in Ikeja designs her own questionnaire and gives it to 200 shoppers to measure their satisfaction with a new loyalty card. The data she obtains are:","options":["Primary data","Documentary data","Published data","Secondary data"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Primary data are collected first-hand by the researcher for a specific purpose, exactly as the manager does with her own questionnaire. Options D, B and C all describe data already collected by someone else for another purpose and then reused."}},{"itemId":"c26eb7ea-3ab2-5413-a255-92400b213aea","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9178de54-0eb9-5851-b688-4005ee3b56ce","sourceKey":"bank:BUA204:DAT-003","parentItemId":null,"revision":1,"payload":{"prompt":"A financial analyst uses exchange-rate figures published by the Central Bank of Nigeria to study how import costs have changed over five years. These figures are an example of:","options":["Experimental data","Primary data","Observational data","Secondary data"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Secondary data were collected by someone else for another purpose and are reused by the analyst, as with published central bank statistics. Option B would require the analyst to collect the figures first-hand, while options A and C are primary methods in which the researcher runs an experiment or watches events directly."}},{"itemId":"43c14cdc-afc6-5375-92c4-1202918f62f0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"42784165-1b52-53d5-8b2a-6b4d867c5b44","sourceKey":"bank:BUA204:DAT-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a method of collecting primary data?","options":["Extracting figures from a company's published financial statements","Administering a questionnaire to customers","Observing customer flow in a store","Running a controlled experiment on a new product formula"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Extracting figures from published financial statements reuses data prepared by someone else, so it is a documentary (secondary) method. Options B, C and D (questionnaire, observation and experiment) all gather data first-hand for the researcher's own purpose."}},{"itemId":"fa2c2e54-a636-508d-907e-b1bb978c742b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fe57edfb-c149-51eb-bb88-7bd0a554c9ea","sourceKey":"bank:BUA204:DAT-005","parentItemId":null,"revision":1,"payload":{"prompt":"To study how shoppers move through a new store layout, a researcher stands quietly and records the paths customers take, without asking them any questions. Which data collection method is this?","options":["Observation","Interview","Experiment","Questionnaire"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Observation records behaviour or events as they happen without questioning the subjects, which is how customer flow in a store is typically studied. Options B and D both involve asking people questions, and option C requires deliberately changing a variable under controlled conditions."}},{"itemId":"c24b6edc-822f-5f46-9df5-91ffe38a4698","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3c9d22bb-8e40-55bc-a542-6e0452dd16ac","sourceKey":"bank:BUA204:DAT-006","parentItemId":null,"revision":1,"payload":{"prompt":"A drinks company sells a new reduced-sugar formula in five outlets and the old formula in five similar outlets, keeping price and display the same, to see the effect on sales. This method of data collection is:","options":["Observation","An interview","An experiment","A documentary method"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"An experiment manipulates one variable (here the formula) under controlled conditions to observe its effect, as when testing a new product formula. Option A only watches events without changing anything, option B questions people directly, and option D uses existing records."}},{"itemId":"14e881fd-2373-5011-9775-16d3eae36eca","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bd73aedd-9038-57db-a74b-747015a1a3a9","sourceKey":"bank:BUA204:DAT-007","parentItemId":null,"revision":1,"payload":{"prompt":"A structured set of written questions administered to respondents, commonly used for customer satisfaction surveys, is called:","options":["An interview","An observation schedule","A questionnaire","An experiment"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A questionnaire is a structured set of written questions given to respondents, which makes it well suited to customer satisfaction surveys. Option A is direct verbal questioning, option B records behaviour without questions, and option D manipulates a variable under controlled conditions."}},{"itemId":"b83fe954-5d4c-5758-8aeb-255e88a53ba0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7a55784f-f20c-5496-8701-23986667a6b2","sourceKey":"bank:BUA204:DAT-008","parentItemId":null,"revision":1,"payload":{"prompt":"As a method of data collection, an interview is best described as:","options":["extracting data from existing records or publications","a set of written questions that respondents complete on their own","direct verbal questioning, which may be structured or unstructured","recording events as they occur without asking any questions"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"An interview gathers data through direct verbal questioning, structured or unstructured, and is often used for in-depth market research. Option B describes a questionnaire, option D describes observation, and option A describes the documentary (secondary) method."}},{"itemId":"3d0dcb54-15df-521a-9f20-3d6b1553731b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"64102fa2-daba-535f-a132-a02bdb389a6d","sourceKey":"bank:BUA204:DAT-009","parentItemId":null,"revision":1,"payload":{"prompt":"The number of customers served per day at a bank branch is an example of:","options":["Discrete quantitative data","Continuous quantitative data","Secondary qualitative data","Qualitative (categorical) data"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Customers are counted in whole numbers (you cannot serve 12.6 customers), so the data are discrete quantitative data. Option B would apply to measurements such as time or weight that can take any value in a range, and options D and C describe categories or attributes rather than amounts."}},{"itemId":"bbf93aa9-9893-54fa-b1a0-65abc2b90be8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c6e6c87c-8e5e-5cc0-b0b3-d2992021f961","sourceKey":"bank:BUA204:DAT-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of CONTINUOUS data?","options":["The number of cars sold per week","The time taken to serve each customer at a fast-food counter","The number of staff in each branch","The brand of phone each customer prefers"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Continuous data can take any value within a range, and time can be measured to any fraction of a second. Options C and A are counts, which are discrete, and option D is a category, which is qualitative data."}},{"itemId":"25ded399-600b-51d1-85db-808cd18ea3dd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f654a944-b5d9-5414-b349-4e588499c48a","sourceKey":"bank:BUA204:DAT-011","parentItemId":null,"revision":1,"payload":{"prompt":"A market researcher records whether each respondent prefers Brand X, Brand Y or Brand Z of noodles. The variable 'brand preference' is:","options":["Continuous quantitative data","Ratio-scale numerical data","Discrete quantitative data","Qualitative (categorical) data"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Brand preference describes a category or attribute rather than an amount, so it is qualitative (categorical) data. Options C and A are quantitative data that answer 'how much' or 'how many', and option B also refers to numerical measurement, which brand names are not."}},{"itemId":"aad1a5a9-f3c6-59b2-bc64-66c4fb7dd60e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b6dd66c6-8738-5e27-91b0-d4f73c9af037","sourceKey":"bank:BUA204:DAT-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT quantitative data?","options":["The department each employee works in","Weight of each bag of rice produced","Number of employees in each branch","Monthly salary of each employee"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"The department is an attribute or category, so it is qualitative data. Options D, C and B answer 'how much' or 'how many' and are therefore quantitative (salary and weight are continuous, the number of employees is discrete)."}},{"itemId":"eef12fb0-c2b0-522c-9c6e-cfb3c9eda94f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0afb6d87-8bc6-5705-93dd-02178f33a3ad","sourceKey":"bank:BUA204:DAT-013","parentItemId":null,"revision":1,"payload":{"prompt":"The main focus of QUANTITATIVE data collection is:","options":["producing findings that are not meant to apply beyond the people studied","understanding context, processes, perspectives and meaning","testing hypotheses derived from theory and estimating the size of a phenomenon","selecting participants purposively to explore deep insights"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Quantitative data collection focuses on testing hypotheses derived from theory and estimating how large a phenomenon is. Options B, D and A all describe qualitative data collection, which seeks context and meaning, uses purposive sampling and does not aim to generalise."}},{"itemId":"678c60da-1849-5e82-91df-a986028b6933","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d5e723ba-a8a4-51ad-ae5e-a12e1cccdffb","sourceKey":"bank:BUA204:DAT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about generalisability is CORRECT?","options":["Qualitative studies intend to generalise findings to a larger population, while quantitative findings are generally not generalisable","Quantitative studies intend to generalise findings to a larger population, while qualitative findings are generally not generalisable","Neither quantitative nor qualitative studies can say anything about a population","Both quantitative and qualitative studies always generalise their findings to the whole population"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Quantitative data collection aims to generalise its findings to a larger population, whereas qualitative findings are generally not generalisable to a specific population. Option A reverses the two approaches, option D ignores the difference between them, and option C is wrong because quantitative studies are designed to generalise."}},{"itemId":"766a02d2-bc50-586f-ad22-bf479d00d7b5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e0085769-1142-53ea-b5f2-59a9a69d1b11","sourceKey":"bank:BUA204:DAT-015","parentItemId":null,"revision":1,"payload":{"prompt":"A researcher wants findings from a survey of Lagos SMEs to apply to ALL SMEs in Lagos. How should she select participants?","options":["By theoretical sampling","By purposive sampling","By choosing only firms she already knows well","By probability sampling"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Quantitative research that aims to generalise to a population selects participants by probability sampling, so every unit has a known chance of selection. Options B and A are used in qualitative research, whose findings are not meant to be generalised, and option C is a convenience choice that would bias the results."}},{"itemId":"e6514739-8011-5d62-9078-dddbe9fec65a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8bb2aecb-83f8-5dfa-a8ec-39a2c324d589","sourceKey":"bank:BUA204:DAT-016","parentItemId":null,"revision":1,"payload":{"prompt":"A sampling method in which every member of the population has an equal chance of being selected, for example by drawing names from a hat, is:","options":["Systematic sampling","Stratified sampling","Purposive sampling","Simple random sampling"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"In simple random sampling every member of the population has an equal chance of selection, as in a lottery draw. Option B first divides the population into subgroups, option A picks every kth item from a list after a starting point, and option C deliberately chooses particular participants, so chances are not equal."}},{"itemId":"89b86c6e-9fb6-5ade-a30a-b9d9a029c490","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"349a1d1f-a86d-504d-b981-df409cbcddba","sourceKey":"bank:BUA204:DAT-017","parentItemId":null,"revision":1,"payload":{"prompt":"A bank divides its staff into junior, senior and management groups and then selects a random sample from EACH group. This is:","options":["Simple random sampling","Stratified sampling","Systematic sampling","Purposive sampling"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Stratified sampling divides the population into subgroups (strata) and draws a random sample from each, so every group is represented. Option C takes every kth name from a single list, option A samples from the whole population without forming groups, and option D is a non-probability method used in qualitative research."}},{"itemId":"118d2780-0aa0-5807-a042-fe4c37c4b6bb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9195d325-da3e-53ed-a56c-7b44c5634c60","sourceKey":"bank:BUA204:DAT-018","parentItemId":null,"revision":1,"payload":{"prompt":"From an alphabetical list of 2,000 customers, a researcher picks the 5th name and then every 40th name after it. This is:","options":["Stratified sampling","Systematic sampling","Theoretical sampling","Purposive sampling"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Systematic sampling selects every kth item from an ordered list after a starting point, here every 40th customer after the 5th. Option A would first divide customers into subgroups, while options D and C are non-probability methods in which the researcher chooses participants deliberately."}},{"itemId":"33910c18-0f79-5ab2-a293-4ca5d261bd9c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7a235ffe-65da-5a08-bc66-2191c634b152","sourceKey":"bank:BUA204:DAT-019","parentItemId":null,"revision":1,"payload":{"prompt":"A frequency distribution is best described as:","options":["a chart in which slices of a circle represent parts of a whole","a graph of points joined by lines to show change over time","a list of raw data in the exact order in which they were collected","an arrangement of raw data into classes showing the number of observations falling into each class"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"A frequency distribution organises raw data into classes (or categories) and shows how many observations fall into each, which makes patterns easier to see. Option A describes a pie chart, option C is ungrouped raw data, which is what the distribution is meant to replace, and option B describes a line graph."}},{"itemId":"06c7aa44-1e48-5d03-95e4-9b0b1b64f028","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c3c5b922-2b71-5669-bb5d-461be31fe186","sourceKey":"bank:BUA204:DAT-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT true of a bar chart?","options":["The lengths of its bars are proportional to the values they represent","Its bars are of equal width","Its bars touch each other because the variable is continuous","It is suitable for comparing discrete categories such as sales by region"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Bars that touch because the variable is continuous describe a histogram; a bar chart's bars are separated by gaps because the categories are separate. Options B, A and D are all true of a bar chart: equal-width bars, lengths proportional to values, and use for comparing discrete categories."}},{"itemId":"1468b513-f102-533f-93f4-061a54643c90","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"70bfb5d0-0fbb-5ca4-9773-26242293c0c5","sourceKey":"bank:BUA204:DAT-021","parentItemId":null,"revision":1,"payload":{"prompt":"The finance director of a Lagos firm wants to show the board how the total operating cost is split between salaries, rent, marketing and logistics. Which chart is most appropriate?","options":["Line graph","Pie chart","Histogram","Scatter diagram"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A pie chart shows the composition of a whole, with each slice in proportion to its share of the total, and it works best with a few categories like these four. Option A is for trends over time, option C is for the distribution of a continuous grouped variable, and option D shows the relationship between two variables."}},{"itemId":"5e082800-e8ee-5136-9543-fc6a998ae07f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f1ddf1ee-7878-5030-8a56-65b3aff01cdc","sourceKey":"bank:BUA204:DAT-022","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst wants to show how the naira-dollar exchange rate moved month by month over the last 24 months. Which chart should she use?","options":["Pie chart","Histogram","Line graph","Bar chart of separate categories"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A line graph joins data points with lines and is the standard chart for showing how a quantity changes over a continuous period, so it is the choice whenever the message is a trend. Option A shows parts of a whole, option D compares separate categories, and option B shows the distribution of grouped data rather than change over time."}},{"itemId":"0e180a6b-d243-5aba-8911-e7d24a2f58e2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a6618c61-108b-5e2d-b903-1f9907dd3f22","sourceKey":"bank:BUA204:DAT-023","parentItemId":null,"revision":1,"payload":{"prompt":"A delivery company has grouped the delivery times (in minutes) of 300 orders into classes such as 10-under 20, 20-under 30 and so on. To show the distribution of these times, the most appropriate chart is a:","options":["Pie chart","Simple bar chart with gaps between bars","Histogram","Line graph"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A histogram is used for continuous, grouped quantitative data, with adjoining bars whose areas represent class frequencies, which fits grouped delivery times. Option A shows parts of a whole, option D shows a trend over time, and option B is for separate categories, not continuous classes."}},{"itemId":"098fd06f-7ba2-5bca-b9f0-f360bf1c8953","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"16187378-e084-51ff-930b-5b83727eb4cd","sourceKey":"bank:BUA204:DAT-024","parentItemId":null,"revision":1,"payload":{"prompt":"In a histogram, which feature of each bar is proportional to the frequency of its class?","options":["Its colour","Its area","Its position on the vertical axis label","The gap between it and the next bar"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"In a histogram the area of each bar is proportional to the frequency of its class; when all classes have the same width, the heights also follow the frequencies. Option A carries no numerical meaning, option D is wrong because histogram bars have no gaps, and option C is not a feature of the bar itself."}},{"itemId":"4e7e7329-4bdf-5276-a508-30afb52750c5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"06ac7f51-249a-51ed-96f9-2352c1db2a04","sourceKey":"bank:BUA204:DAT-025","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing manager plots each month's advertising spend against that month's sales as a set of points, to see whether the two variables are related. This chart is a:","options":["Scatter diagram","Ogive","Pie chart","Histogram"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"A scatter diagram plots pairs of values to show the relationship between two variables and forms the basis for correlation and regression. Option B plots cumulative frequency, option C shows parts of a whole, and option D shows the distribution of one grouped variable."}},{"itemId":"2427da79-0455-537e-a85e-562c29c60783","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9b83805d-fc78-5715-8b93-6b3ba87371e1","sourceKey":"bank:BUA204:DAT-026","parentItemId":null,"revision":1,"payload":{"prompt":"A 'less than' ogive is drawn by plotting:","options":["cumulative frequencies against the lower class limits of the first class only","cumulative frequencies against the upper class boundaries","class frequencies against the class midpoints","percentages of the total against slice angles"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"An ogive is a cumulative frequency curve; for a 'less than' ogive each cumulative frequency is plotted against the upper class boundary, because it counts all observations below that boundary. Option C describes a frequency polygon, option A would give only one point, and option D relates to a pie chart."}},{"itemId":"b25c3a50-ab14-55d3-9e9b-bb0c00e69956","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"99f3fc40-07ab-5c66-95d4-d94b31644a83","sourceKey":"bank:BUA204:DAT-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of a well-constructed statistical table?","options":["A clear title","Totals where appropriate","Leaving out the units so the table looks less cluttered","Properly labelled rows and columns"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A good table states its units clearly; leaving them out makes the figures impossible to interpret correctly. Options A, D and B (a clear title, labelled rows and columns, and totals where appropriate) are all features of a good table, along with a statement of where secondary data came from."}},{"itemId":"426ed921-f164-5af5-aa7b-e33aa92b00c4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"63fff78c-4a9d-5222-994d-59e83a6de8b8","sourceKey":"bank:BUA204:DAT-028","parentItemId":null,"revision":1,"payload":{"prompt":"When is a table usually preferred to a chart for presenting data?","options":["When the message is a trend over time","When the audience needs to see a pattern quickly without reading figures","When exact values matter more than visual impression","When the aim is to show parts of a whole at a glance"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Well-designed tables are one of the most precise ways to present data, so they are preferred when exact values matter more than visual impression. Options A, D and B are situations where charts (a line graph, a pie chart, or charts generally) communicate better because they show patterns at a glance."}},{"itemId":"0185a9b8-5120-5568-a291-ef8ac36cdee6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1269e434-8b7e-5efc-ae8e-29dd90e11d0e","sourceKey":"bank:BUA204:DAT-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes a bar chart from a histogram?","options":["There is no difference; the two names refer to the same chart","A bar chart compares separate categories and has gaps between bars; a histogram shows the distribution of a continuous variable and its bars touch","A bar chart's bars touch; a histogram's bars are separated by gaps","A bar chart shows the distribution of a continuous variable; a histogram compares separate categories"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A bar chart compares separate categories, so its bars are separated by gaps, while a histogram shows how one continuous variable is spread across numerical classes, so its bars touch. Options D and C reverse the two charts, and option A ignores a distinction that is often tested."}},{"itemId":"b5be52a2-5ac6-52ed-bfae-369c01dbba58","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"090d78c3-c4b4-56ec-b74a-416c0e2ed9a4","sourceKey":"bank:BUA204:DAT-030","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst studying inflation in Nigeria uses consumer price figures published by the National Bureau of Statistics. Which data collection method is she using?","options":["Documentary (secondary) method","Observation","Experiment","Structured interview"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Extracting data from existing records or publications, such as NBS inflation statistics, is the documentary or secondary method. Options C, B and D are primary methods in which the analyst would gather new data herself."}},{"itemId":"bb206c00-4562-52e7-a9c7-aa0f1f903bd9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"90fc709d-5cfe-5a2f-8b4e-6393aa1ce4d2","sourceKey":"bank:BUA204:DAT-031","parentItemId":null,"revision":1,"payload":{"prompt":"For whole-number data, the class 20-29 has 19.5 and 29.5 as its:","options":["Class midpoints","Class frequencies","Class boundaries","Class limits"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Class boundaries for whole-number data are found by subtracting 0.5 from the lower limit and adding 0.5 to the upper limit, giving 19.5 and 29.5. Option D gives the stated values 20 and 29, option A would be the single value 24.5, and option B refers to counts of observations, not class edges."}},{"itemId":"1c334a40-ad6e-55af-8285-15ca38fa92b4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"511a6850-a084-5150-9c50-cc9cd58ff19c","sourceKey":"bank:BUA204:DAT-032","parentItemId":null,"revision":1,"payload":{"prompt":"The daily sales (in N'000) of 16 kiosks are: 34, 47, 52, 41, 38, 49, 55, 44, 60, 39, 46, 51, 43, 58, 40, 36. What is the range of the data?","options":["60","26","94","45.81"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Range = highest value - lowest value = 60 - 34 = 26. Option A is just the highest value, option C adds the extremes instead of subtracting, and option D is the mean, which is a measure of average, not spread."}},{"itemId":"181f806e-cf1d-51f7-890a-ea3543639eb8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a88e7ecf-d93d-598c-a238-2d3812cc8833","sourceKey":"bank:BUA204:DAT-033","parentItemId":null,"revision":1,"payload":{"prompt":"The daily sales (in N'000) of 16 kiosks are: 34, 47, 52, 41, 38, 49, 55, 44, 60, 39, 46, 51, 43, 58, 40, 36. In a grouped frequency distribution using classes 30-39, 40-49, 50-59 and 60-69, what is the frequency of the class 40-49?","options":["8","7","6","4"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Tallying values from 40 to 49 inclusive gives [40, 41, 43, 44, 46, 47, 49], so the frequency is 7. Option C usually comes from leaving out the boundary value 40, option A from also counting a value outside the class, and option D is the frequency of class 50-59."}},{"itemId":"cefb0aa8-8202-5a34-83c7-d43cf16b773b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d2fc5025-3ab1-5524-81b2-4df67b4c3286","sourceKey":"bank:BUA204:DAT-034","parentItemId":null,"revision":1,"payload":{"prompt":"A set of exam scores has a highest value of 97 and a lowest value of 42. Using Class Width = (Highest - Lowest) / Number of classes, rounded UP to the next whole number, what class width should be used for 6 classes?","options":["17","9","24","10"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Class width = (97 - 42) / 6 = 55 / 6 = 9.17, rounded up to 10. Option B rounds down, which leaves the classes too narrow to cover the highest value, option A divides only the highest value, and option C adds the extremes instead of subtracting."}},{"itemId":"03381751-ff7f-5c7f-a0b9-deddc86f89ef","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"65e29f05-31b8-519a-be82-c39db0c167a2","sourceKey":"bank:BUA204:DAT-035","parentItemId":null,"revision":1,"payload":{"prompt":"For whole-number data, what are the class boundaries of the class 25-34?","options":["24.5 and 34.5","25 and 34","25.5 and 33.5","24 and 35"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Class boundaries = class limits -/+ 0.5, so the lower boundary is 25 - 0.5 = 24.5 and the upper boundary is 34 + 0.5 = 34.5. Option B gives the class limits themselves, option C moves the boundaries inward instead of outward, and option D moves them out by a whole unit."}},{"itemId":"910625b3-ff50-5c36-b139-52d99565ba3a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aed49cc8-8ade-54d9-8fe7-05c1caa77711","sourceKey":"bank:BUA204:DAT-036","parentItemId":null,"revision":1,"payload":{"prompt":"What is the class midpoint (class mark) of the class 25-34?","options":["9","29.5","59","30"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Class midpoint = (lower limit + upper limit) / 2 = (25 + 34) / 2 = 29.5, which is the same as (24.5 + 34.5) / 2. Option D uses 35 as the upper limit, option A is the difference between the limits, and option C adds the limits but forgets to divide by 2."}},{"itemId":"a106961b-d786-5826-b106-cfa59e65af13","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"53ec819a-1bf9-58b7-91b8-08527ea9d8b4","sourceKey":"bank:BUA204:DAT-037","parentItemId":null,"revision":1,"payload":{"prompt":"A grouped frequency distribution of whole-number data uses the classes 10-19, 20-29, 30-39 and so on. Taking class width as upper class boundary minus lower class boundary, what is the class width?","options":["9.5","9","19","10"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"For 10-19 the boundaries are 9.5 and 19.5, so the width is 19.5 - 9.5 = 10 (also the gap between successive lower limits, 20 - 10). Option B subtracts the class limits (19 - 10), a common mistake, option A mixes a limit with a boundary, and option C is just the upper limit."}},{"itemId":"cd7ffa1f-c56d-572c-9f20-c115ae64a33c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"513e28c2-a708-5749-abe3-a1df4a141ff4","sourceKey":"bank:BUA204:DAT-038","parentItemId":null,"revision":1,"payload":{"prompt":"In a survey of 40 traders, 15 fall in the turnover class N50,000-N99,999. What is the relative frequency of this class, as a percentage?","options":["62.5%","37.5%","2.7%","60.0%"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Relative frequency = class frequency / total frequency x 100 = 15 / 40 x 100 = 37.5%. Option D divides by the traders outside the class, option A is the share of traders outside the class, and option C inverts the fraction."}},{"itemId":"48bd8e5e-6baf-56f1-8356-dc7baa5e2ea6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"276d7ba4-5ca6-502e-b7bc-91ed0bb2c6a1","sourceKey":"bank:BUA204:DAT-039","parentItemId":null,"revision":1,"payload":{"prompt":"The marks of 40 staff in a training test are grouped as follows (class: frequency): 10-19: 4; 20-29: 9; 30-39: 15; 40-49: 8; 50-59: 4. What is the cumulative frequency up to and including the class 30-39?","options":["15","13","36","28"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Cumulative frequency adds the frequencies up to that class: 4 + 9 + 15 = 28. Option A is only the frequency of 30-39, option B stops one class early, and option C goes one class too far."}},{"itemId":"7138de5b-d159-59ce-8f1f-e26898cd3d40","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9c5626dc-eb22-5650-a934-a09bad602258","sourceKey":"bank:BUA204:DAT-040","parentItemId":null,"revision":1,"payload":{"prompt":"The marks of 40 staff are grouped as follows (class: frequency): 10-19: 4; 20-29: 9; 30-39: 15; 40-49: 8; 50-59: 4. On a 'less than' ogive, plotting cumulative frequency against upper class boundaries, which point is plotted for the class 30-39?","options":["(39, 15)","(34.5, 28)","(39.5, 28)","(29.5, 28)"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"The upper class boundary of 30-39 is 39 + 0.5 = 39.5 and the cumulative frequency to that point is 4 + 9 + 15 = 28, so the point is (39.5, 28). Option A uses the upper limit and the simple frequency, option B uses the class midpoint, and option D uses the lower boundary."}},{"itemId":"8d2008ce-c5cb-5613-89d2-0754688d3527","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9f788780-5880-5a0c-a297-7f5b6fef2268","sourceKey":"bank:BUA204:DAT-041","parentItemId":null,"revision":1,"payload":{"prompt":"The marks of 40 staff are grouped as follows (class: frequency): 10-19: 4; 20-29: 9; 30-39: 15; 40-49: 8; 50-59: 4. What percentage of the staff scored 40 marks or more?","options":["70.0%","20.0%","67.5%","30.0%"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Staff scoring 40 or more are in 40-49 and 50-59: 8 + 4 = 12, and 12 / 40 x 100 = 30.0%. Option B counts only the 40-49 class, option A is the percentage BELOW 40, and option C wrongly includes the 30-39 class."}},{"itemId":"285d7ee7-82f7-53f9-b10f-13d78ba06ab4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"783812aa-03de-5e5e-b392-d274122c21e8","sourceKey":"bank:BUA204:DAT-042","parentItemId":null,"revision":1,"payload":{"prompt":"Using these grouped marks (class: frequency): 10-19: 4; 20-29: 9; 30-39: 15; 40-49: 8; 50-59: 4, how many staff scored at least 30 marks?","options":["27","12","15","28"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"At least 30 means the classes 30-39, 40-49 and 50-59: 15 + 8 + 4 = 27. Option D is the cumulative frequency up to 39, which counts the wrong end of the table, option C is only the 30-39 class, and option B leaves out the 30-39 class."}},{"itemId":"3724d3a0-1377-5dc3-88d0-432124d6a503","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6e444b17-1a5e-5277-b9fa-18483e51845d","sourceKey":"bank:BUA204:DAT-043","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's operating budget of N6,000,000 includes N1,350,000 for transport. Using Angle = (Value / Total) x 360 degrees, what angle should the transport slice have on a pie chart?","options":["81.0 degrees","40.5 degrees","104.5 degrees","22.5 degrees"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Angle = (1,350,000 / 6,000,000) x 360 = 0.225 x 360 = 81.0 degrees. Option D is the percentage share (22.5%), not the angle, option B uses 180 instead of 360, and option C divides by the other categories instead of the whole budget."}},{"itemId":"8efc6187-fd52-5902-a73c-dba1ebeb45cc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a9a440be-9ab5-52b3-969d-4a60ec727458","sourceKey":"bank:BUA204:DAT-044","parentItemId":null,"revision":1,"payload":{"prompt":"On a pie chart of a company's total sales of N5,000,000, the slice for Abuja has an angle of 72 degrees. What were Abuja's sales?","options":["N69,444.44","N2,000,000","N3,600,000","N1,000,000"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Value = (angle / 360) x total = (72 / 360) x 5,000,000 = 0.2 x 5,000,000 = N1,000,000. Option C treats the angle as a percentage, option A divides the total by the angle, and option B uses 180 instead of 360."}},{"itemId":"c62be632-74a9-52f8-ac16-21d0222566b3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"63347c22-afde-540d-b19a-2d763f2068fa","sourceKey":"bank:BUA204:DAT-045","parentItemId":null,"revision":1,"payload":{"prompt":"In a pie chart of staff by department, the Marketing slice has an angle of 54 degrees. What percentage of the staff work in Marketing?","options":["30%","15%","85%","54%"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Percentage = angle / 360 x 100 = 54 / 360 x 100 = 15%. Option D reads the angle as a percentage, option A divides by 180 instead of 360, and option C is the share of all the other departments."}},{"itemId":"44f4cc5d-ac94-503d-ba75-3dcbe630ecf6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b910eccd-15e9-5974-bb11-e2327031211e","sourceKey":"bank:BUA204:DAT-046","parentItemId":null,"revision":1,"payload":{"prompt":"A pie chart has five slices. Four of them have angles of 100, 120, 60, 45 degrees. What is the angle of the fifth slice?","options":["70 degrees","72 degrees","10 degrees","35 degrees"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"All slices of a pie chart must add up to 360 degrees, so the fifth slice = 360 - (100 + 120 + 60 + 45) = 360 - 325 = 35 degrees. Option C mixes degrees and percentages, option B assumes all five slices are equal (360 / 5), and option A doubles the correct figure."}},{"itemId":"fee53d91-86f3-5c57-9c22-54df74e5ccdf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c169f498-621b-5521-b475-dbe5dfec5c82","sourceKey":"bank:BUA204:DAT-047","parentItemId":null,"revision":1,"payload":{"prompt":"In a survey of 240 UNILAG students, 50 said they prefer a particular mobile network. What angle should this group have on a pie chart?","options":["33.3 degrees","37.5 degrees","75 degrees","20.8 degrees"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Angle = (50 / 240) x 360 = 75 degrees. Option D is the percentage share, not the angle, option A arranges the formula wrongly, and option B uses 180 instead of 360."}},{"itemId":"dfcb63cc-2dd7-5101-b06f-587dc4e99c26","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"00dd1d63-60f2-5015-a44f-37fa4c3b7dde","sourceKey":"bank:BUA204:DAT-048","parentItemId":null,"revision":1,"payload":{"prompt":"A budget of N10,000,000 gives N3,500,000 to salaries and N2,000,000 to marketing. On a pie chart of the budget, how many degrees larger is the salaries slice than the marketing slice?","options":["54 degrees","270 degrees","126 degrees","15 degrees"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Salaries = 0.35 x 360 = 126 degrees and marketing = 0.2 x 360 = 72 degrees, so the difference is 54 degrees (or directly, 1,500,000/10,000,000 x 360). Option D is the difference in percentage points, option C is just the salaries angle, and option B divides by the marketing figure instead of the total."}},{"itemId":"982e014e-4066-5367-a168-a834565c4024","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0daa0797-5314-5dae-93b8-a6e53113dc5d","sourceKey":"bank:BUA204:DAT-049","parentItemId":null,"revision":1,"payload":{"prompt":"In a histogram with unequal class widths, bar heights are drawn as frequency density = frequency / class width so that areas are proportional to frequencies. A class '20 to under 40' kg has a frequency of 30. What is its frequency density?","options":["1.5 per kg","600 per kg","30 per kg","1.58 per kg"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Class width = 40 - 20 = 20 kg, so frequency density = 30 / 20 = 1.5 per kg. Option C uses the raw frequency, which would exaggerate the wide class, option D uses a width of 19, and option B multiplies instead of dividing."}},{"itemId":"f456ef4f-f150-5595-81ab-76fd76727e33","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"edda7eeb-05a5-5c9e-8aaa-351f374e4a1a","sourceKey":"bank:BUA204:DAT-050","parentItemId":null,"revision":1,"payload":{"prompt":"A researcher wants a systematic sample of 60 customers from a list of 1,200. Using sampling interval k = N / n, what is k?","options":["1,140","60","20","0.05"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"k = N / n = 1,200 / 60 = 20, so every 20th customer is selected after a random start. Option B is the sample size itself, option D is the sampling fraction n / N, and option A subtracts instead of dividing."}},{"itemId":"2c1c7ba8-6b73-58f3-b7ab-77bb706390ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e9910faf-dde3-5ec2-8d93-ebed7d8ae3a0","sourceKey":"bank:BUA204:DAT-051","parentItemId":null,"revision":1,"payload":{"prompt":"In a systematic sample with a sampling interval of 20, the randomly chosen starting point is item number 7. What is the item number of the 4th unit selected?","options":["28","80","87","67"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"The selected items are 7, 27, 47, 67, ..., so the 4th is 7 + (4 - 1) x 20 = 67. Option C adds one interval too many, option A multiplies the starting point by 4, and option B ignores the starting point."}},{"itemId":"fe93b83e-2249-5c31-a313-76b26be86461","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8f5b74fc-1d2a-5038-abd3-fc07a08144fa","sourceKey":"bank:BUA204:DAT-052","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has 300 junior staff, 150 senior staff and 50 managers. A stratified sample of 60 is drawn with PROPORTIONAL allocation (each group's share of the sample equals its share of the workforce). How many junior staff should be in the sample?","options":["36","5","20","90"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Junior staff are 300 / 500 = 0.6 of the workforce, so the sample includes 0.6 x 60 = 36 junior staff. Option C splits the sample equally between the three groups, option B divides the group size by the sample size, and option D compares juniors with the other groups instead of with the total."}},{"itemId":"fe3e09ce-9514-5a4b-8528-0674b4cec6e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"04828a60-2e79-5e06-89cf-b41141abaa24","sourceKey":"bank:BUA204:DAT-053","parentItemId":null,"revision":1,"payload":{"prompt":"In a grouped frequency distribution, two consecutive class midpoints are 14.5 and 24.5. What is the class width?","options":["19.5","9","10","5"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"With equal class widths, consecutive midpoints are exactly one class width apart, so width = 24.5 - 14.5 = 10. Option A averages the midpoints, option B subtracts 1 as if working with limits, and option D halves the gap."}},{"itemId":"aaaae16e-aa31-58fb-9cec-4a2d7116ca7f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"805304ae-69e8-5b47-b0a8-6037ddbaad2b","sourceKey":"bank:BUA204:DAT-054","parentItemId":null,"revision":1,"payload":{"prompt":"For whole-number data, a class has a midpoint of 44.5 and a class width of 10. What are its class LIMITS?","options":["39.5-49.5","40-49","34.5-44.5","44.5-54.5"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"The boundaries are 44.5 -/+ 5, i.e. 39.5 and 49.5; for whole-number data the limits are 0.5 inside the boundaries, giving 40-49. Option A gives the boundaries rather than the limits, and options C and D wrongly treat the midpoint as an end of the class."}},{"itemId":"668ff5c8-de30-502d-8551-4de25fe42158","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dcd2f8e3-8e70-5219-8cbe-16c59dff6605","sourceKey":"bank:BUA204:DAT-055","parentItemId":null,"revision":1,"payload":{"prompt":"Data range from a lowest value of 12 to a highest value of 71 (whole numbers). If classes of width 10 are used, starting with the class 10-19, how many classes are needed to cover all the data?","options":["6","5","8","7"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"The classes are 10-19, 20-29, 30-39, 40-49, 50-59, 60-69 and 70-79; the highest value 71 falls in 70-79, so 7 classes are needed. Option A stops at 60-69 and leaves out 71, option B divides the range (59) by 10 and rounds down, and option C adds an unnecessary extra class."}},{"itemId":"203e8e32-f131-5977-9fb8-d406d105b762","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0c1903e7-0857-5340-97c5-cd86137b5f57","sourceKey":"bank:BUA204:DEC-001","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Maximax criterion, which strategy should be chosen?","options":["Expand","Outsource","Expand and Maintain are tied","Maintain"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximax takes the best payoff in each row (Expand 150, Maintain 90, Outsource 55) and picks the highest of these, so Expand with N150,000 is chosen. Option D has only the second-highest row maximum (90), Option C is wrong because no other row reaches 150, and Option B is the Maximin (best-of-the-worst) choice."}},{"itemId":"ce630127-c8ae-5451-9b6f-2dc7879dc67d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"971ba604-a522-5359-b711-cf177672d537","sourceKey":"bank:BUA204:DEC-002","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Maximin criterion, which strategy should be chosen?","options":["Maintain","Outsource","Maintain and Outsource are tied","Expand"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin takes the worst payoff in each row (Expand -30, Maintain 20, Outsource 40) and picks the highest of these, so Outsource is the safest choice. Option D is the optimistic Maximax choice, and Option A has a worst case of only N20,000."}},{"itemId":"56d4bf1e-16bd-5848-ad91-6254dc08fd0e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"891737da-bd7e-5f7a-9763-8fe26f1668cd","sourceKey":"bank:BUA204:DEC-003","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Laplace criterion, what is the average payoff for Outsource (to the nearest naira)?","options":["N45,500","N47,500","N46,667","N70,000"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace treats the three states as equally likely, so Outsource's average is (40 + 45 + 55) / 3 = 46.67 thousand, about N46,667. Option A is an EMV that wrongly uses unequal probabilities, Option B is just the midpoint of the best and worst payoffs, and Option D divides the row total by 2 instead of 3."}},{"itemId":"86eb7e5f-aaa5-52dc-b1fc-b5f94dc21527","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c51018dc-6158-52cc-9e62-80e45c748f00","sourceKey":"bank:BUA204:DEC-004","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Which strategy does the Laplace (equally likely) criterion recommend?","options":["Maintain and Outsource are tied","Expand","Maintain","Outsource"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace averages each row with equal weights: Expand (-30 + 60 + 150) / 3 = 60, Maintain 165 / 3 = 55 and Outsource 140 / 3 = 46.67, so Expand has the highest average. Option C is close but its average is N5,000 lower, and Option D is the cautious Maximin choice."}},{"itemId":"15bfc469-5266-522f-9e9a-a87ffb8c94a8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d390d94e-c895-5360-8044-5c4c2bf64a05","sourceKey":"bank:BUA204:DEC-005","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. In the regret (opportunity loss) table, what is the regret for Expand under Low demand (in N'000)?","options":["0","10","70","180"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret is the best payoff in the column minus the payoff in the cell: the best Low-demand payoff is 40, so Expand's regret is 40 - (-30) = 70. Option B comes from treating -30 as +30, and Option D wrongly uses the row (150 - (-30)) instead of the column."}},{"itemId":"5f2d12e1-0ccd-55e5-a655-01b3a863bfa3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b31283ea-d432-5d48-b1c3-b2c7f6b8f5b2","sourceKey":"bank:BUA204:DEC-006","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. What is the maximum regret for Outsource (in N'000)?","options":["55","15","95","110"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Column maxima are 40, 60 and 150, so Outsource's regrets are 0, 15 and 95, giving a maximum regret of 95. Option B is only its Medium-demand regret, Option D adds the regrets together instead of taking the largest, and Option A is simply its best payoff."}},{"itemId":"92981694-cb0a-53e4-81fc-2434f46f8f79","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4536d389-4288-55b1-af45-69fc84b66604","sourceKey":"bank:BUA204:DEC-007","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Minimax Regret (Savage) criterion, which strategy should be chosen?","options":["Expand","Maintain","Outsource","Expand and Maintain are tied"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"The maximum regrets are Expand 70 (Low column), Maintain 60 (High column) and Outsource 95 (High column), and the smallest of these is 60, so Maintain is chosen. Option A has the second-smallest maximum regret, while Option C would leave the firm regretting up to N95,000 if demand turned out High."}},{"itemId":"4aec8e53-df9b-530c-a1f1-cb9a65fa3d23","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ec2e37a2-00fa-5e1c-a029-beaa6e79ead9","sourceKey":"bank:BUA204:DEC-008","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Hurwicz criterion with coefficient of optimism alpha = 0.6 (applied to the best payoff), what is the Hurwicz value for Maintain (in N'000)?","options":["62","54","55","48"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz value = alpha x Max + (1 - alpha) x Min = 0.6(90) + 0.4(20) = 54 + 8 = 62. Option D wrongly puts the 0.6 weight on the worst payoff, Option C is the Laplace average, and Option B forgets to add the weighted minimum."}},{"itemId":"f74f4ce5-55fe-58c4-8681-ca7743918212","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6936eac8-eb7d-5a96-a64a-cfc4052bc2eb","sourceKey":"bank:BUA204:DEC-009","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. Using the Hurwicz criterion with coefficient of optimism alpha = 0.2 (applied to the best payoff), which strategy should be chosen?","options":["Maintain","Outsource","Expand","Expand and Outsource are tied"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"With alpha = 0.2 the values are Expand 0.2(150) + 0.8(-30) = 6, Maintain 0.2(90) + 0.8(20) = 34 and Outsource 0.2(55) + 0.8(40) = 43, so Outsource is highest. A low alpha means a pessimistic manager, so the result moves towards the Maximin choice; Option C would be chosen only with a high alpha."}},{"itemId":"74869dd7-3bc3-59d5-886a-35f3c9de0cf5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"99222e27-d8a8-555a-8b60-889c9eba83ea","sourceKey":"bank:BUA204:DEC-010","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. The probabilities of Low, Medium and High demand are estimated at 0.3, 0.5 and 0.2. What is the EMV of Expand?","options":["N60,000","N69,000","N51,000","N72,000"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV = sum of probability x payoff = 0.3(-30) + 0.5(60) + 0.2(150) = -9 + 30 + 30 = 51 thousand, i.e. N51,000. Option B treats the -30 loss as a profit, Option A is the simple Laplace average that ignores the probabilities, and Option D is the expected payoff with perfect information."}},{"itemId":"fbbc3eef-bcdb-536c-835e-ee5d5cebf7a8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2b53bc56-4556-5ecd-883e-e8bccb6949d9","sourceKey":"bank:BUA204:DEC-011","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. The probabilities of Low, Medium and High demand are 0.3, 0.5 and 0.2. Using the EMV criterion, which strategy should be chosen?","options":["Outsource","Expand and Maintain are tied","Expand","Maintain"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMVs are Expand 0.3(-30) + 0.5(60) + 0.2(150) = 51, Maintain 0.3(20) + 0.5(55) + 0.2(90) = 51.5 and Outsource 0.3(40) + 0.5(45) + 0.2(55) = 45.5, so Maintain is best by N500. Option C is the tempting choice because of its large High-demand payoff, but its expected value is slightly lower."}},{"itemId":"4e9b6de9-d877-5afc-a546-aa4f87d150af","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6d497f7b-b5b5-5c40-97bf-b4e794649d25","sourceKey":"bank:BUA204:DEC-012","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. The probabilities of Low, Medium and High demand are 0.3, 0.5 and 0.2. What is the expected payoff with perfect information (EPPI)?","options":["N51,500","N20,500","N72,000","N83,333"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"With perfect information the firm always picks the best payoff in each state: EPPI = 0.3(40) + 0.5(60) + 0.2(150) = 12 + 30 + 30 = 72 thousand. Option A is the best EMV without perfect information, Option B is the EVPI, and Option D averages the column maxima without using the probabilities."}},{"itemId":"63ce2006-754c-5da4-8228-694a69ed01e1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cb2beaac-76fc-57c7-bc20-9ee42c2ba841","sourceKey":"bank:BUA204:DEC-013","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. The probabilities of Low, Medium and High demand are 0.3, 0.5 and 0.2. What is the Expected Value of Perfect Information (EVPI)?","options":["N20,500","N26,500","N21,000","N72,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"EVPI = EPPI - best EMV = 72,000 - 51,500 = N20,500, the most the firm should pay for a perfect demand forecast. Option C subtracts Expand's EMV (51,000) instead of the best EMV, Option B subtracts the worst EMV, and Option D forgets to subtract anything."}},{"itemId":"400fb2e6-222a-5b95-848b-4d515c626d6b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c6043834-06d1-5778-ab99-b2110e0ef835","sourceKey":"bank:BUA204:DEC-014","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. The probabilities of Low, Medium and High demand are 0.3, 0.5 and 0.2. What is the Expected Opportunity Loss (EOL) of Maintain?","options":["N85,000","N28,333","N20,500","N21,000"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maintain's regrets are 20, 5 and 60, so EOL = 0.3(20) + 0.5(5) + 0.2(60) = 6 + 2.5 + 12 = 20.5 thousand; notice it equals the EVPI because Maintain is the best-EMV choice. Option D is Expand's EOL, Option A adds the regrets without probabilities, and Option B is their simple average."}},{"itemId":"6e824519-70bf-55f0-ac26-80b6b9ceab42","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a910088a-1e38-519c-b183-f357a935defc","sourceKey":"bank:BUA204:DEC-015","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company must choose one of three strategies. Its payoff table (profit in N'000) is: Expand: Low demand -30, Medium demand 60, High demand 150; Maintain: Low 20, Medium 55, High 90; Outsource: Low 40, Medium 45, High 55. If the company knew for certain that demand would be Medium, which strategy should it choose?","options":["Maintain, because it has the highest EMV","Outsource","Expand","Maintain"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under certainty only one state of nature applies, so the manager simply picks the highest payoff in that column: Expand earns 60 against 55 for Maintain and 45 for Outsource. Option A is wrong because EMV is a tool for risk, not certainty, where probabilities are no longer needed."}},{"itemId":"54873749-a59b-5b66-81dd-b99291212109","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c967cd51-cd0a-5e3e-8c47-f50ad5f2acf3","sourceKey":"bank:BUA204:DEC-016","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Which farm size does the Maximin criterion recommend?","options":["Small","Medium","Medium and Large are tied","Large"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin compares the worst payoff of each option (Small 15, Medium -5, Large -25) and chooses the best of these, so Small is chosen because it never makes a loss. Option D is the option an optimist would favour because of its N85,000 upside, but it has the worst downside."}},{"itemId":"8f302d9f-5b21-508c-94dd-b70e1a65a922","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dbda73ed-25da-54a5-8ec1-3cf94f191a6e","sourceKey":"bank:BUA204:DEC-017","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Using the Laplace criterion, what is the average payoff for Medium (in N'000)?","options":["30","27.5","22.5","36.67"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace gives each of the four states an equal weight of 1/4: (-5 + 25 + 40 + 50) / 4 = 110 / 4 = 27.5. Option A treats the -5 loss as +5, Option D divides by 3 instead of 4, and Option C is the midpoint of the best and worst payoffs."}},{"itemId":"2312e8b0-eb7e-5c97-9fd9-99feb43d5934","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43cb02ab-df0c-58f9-a65e-3a1927536c5c","sourceKey":"bank:BUA204:DEC-018","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Which farm size does the Laplace criterion recommend?","options":["Large","Medium","Small","Small and Medium are tied"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The equally weighted averages are Small 90/4 = 22.5, Medium 110/4 = 27.5 and Large 120/4 = 30, so Large has the highest average. Option C is the Maximin choice, and Option B is the Minimax Regret choice for this table, not the Laplace one."}},{"itemId":"8be2f6cc-9749-5560-af6a-55de5fee8170","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2385e52c-358f-5411-9eb4-a7f048b646d0","sourceKey":"bank:BUA204:DEC-019","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Using the Hurwicz criterion with coefficient of optimism alpha = 0.7 (applied to the best payoff), what is the Hurwicz value for Large (in N'000)?","options":["67","59.5","8","52"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz = 0.7 x Max + 0.3 x Min = 0.7(85) + 0.3(-25) = 59.5 - 7.5 = 52. Option C puts the 0.7 weight on the worst payoff instead of the best, Option A treats the -25 loss as a gain, and Option B forgets the weighted minimum altogether."}},{"itemId":"44b52aab-4f43-5268-a7ef-60de01d00a15","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"74c77c88-9202-5d77-8a31-c85f1718e2ae","sourceKey":"bank:BUA204:DEC-020","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Using the Hurwicz criterion with coefficient of optimism alpha = 0.3 (applied to the best payoff), which farm size should be chosen?","options":["Medium","Large","Small","Medium and Large are tied"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz values are Small 0.3(30) + 0.7(15) = 19.5, Medium 0.3(50) + 0.7(-5) = 11.5 and Large 0.3(85) + 0.7(-25) = 8, so Small is chosen. With a low alpha the manager leans towards pessimism; Option B would win only at a much higher alpha."}},{"itemId":"2d22f2d6-8dd5-5a66-9ff6-18f285efd47a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"59f6a3a4-7bb2-50a1-9887-a2052dc2ab04","sourceKey":"bank:BUA204:DEC-021","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. In the regret table, what is the regret for Small under Excellent conditions (in N'000)?","options":["15","30","0","55"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"The best payoff in the Excellent column is 85 (Large), so Small's regret is 85 - 30 = 55. Option C wrongly compares Small with its own best payoff, Option B is just Small's payoff, and Option A is the difference between Small's best and worst payoffs."}},{"itemId":"9c9f3684-7602-52c8-a339-6552306a85da","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"44ea47b1-c911-59ba-b0ac-a7911da0232f","sourceKey":"bank:BUA204:DEC-022","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. Using the Minimax Regret criterion, which farm size should be chosen?","options":["Small and Large are tied","Large","Small","Medium"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Column maxima are 15, 25, 50 and 85, giving maximum regrets of Small 55, Medium 35 and Large 40 (Poor column: 15 - (-25)), so Medium has the smallest maximum regret. Option B is close at 40, and Option C carries a large regret of 55 if conditions are Excellent."}},{"itemId":"d34259d4-592f-5953-8e37-07d7ec1a4a18","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6793c0b7-d54d-5231-9c19-f3f557ce72df","sourceKey":"bank:BUA204:DEC-023","parentItemId":null,"revision":1,"payload":{"prompt":"An Ogun State poultry farmer must choose a farm size without any probability estimates. Payoffs (profit in N'000) are: Small: Poor 15, Fair 20, Good 25, Excellent 30; Medium: Poor -5, Fair 25, Good 40, Excellent 50; Large: Poor -25, Fair 10, Good 50, Excellent 85. What is the maximum regret for Large (in N'000)?","options":["10","0","85","40"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Large's regrets are 15 - (-25) = 40, 25 - 10 = 15, 0 and 0, so its maximum regret is 40. Option A comes from treating -25 as +25 in the Poor column, and Option B only looks at the Good and Excellent columns where Large is the best option."}},{"itemId":"8baaf84c-4a31-5fcf-90b3-cdede73ac9cd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f0b07b55-aa6a-52f5-94b2-a9d6c80f92b3","sourceKey":"bank:BUA204:DEC-024","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Abuja considers three investments. Returns (N million) under Recession, Normal and Boom conditions are: Treasury bills 8, 8, 8; Real estate -4, 10, 22; Shares -10, 12, 30. The probabilities of Recession, Normal and Boom are 0.25, 0.5 and 0.25. What is the EMV of Real estate?","options":["N11.5 million","N28 million","N9.5 million","N9.33 million"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV = 0.25(-4) + 0.5(10) + 0.25(22) = -1 + 5 + 5.5 = N9.5 million. Option D is the simple (Laplace) average that ignores the probabilities, Option A treats the -4 loss as a gain, and Option B just adds the three returns."}},{"itemId":"08f021bd-d155-5464-ade0-f14bada77b17","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4d3350f0-f9ab-56a9-9420-88e685a304d1","sourceKey":"bank:BUA204:DEC-025","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Abuja considers three investments. Returns (N million) under Recession, Normal and Boom conditions are: Treasury bills 8, 8, 8; Real estate -4, 10, 22; Shares -10, 12, 30. The probabilities of Recession, Normal and Boom are 0.25, 0.5 and 0.25. Using EMV, which investment should be chosen?","options":["Real estate and Shares are tied","Real estate","Shares","Treasury bills"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMVs are Treasury bills 8, Real estate 9.5 and Shares 0.25(-10) + 0.5(12) + 0.25(30) = 11, so Shares give the highest expected return. Option D is the safe Maximin choice, which ignores the probabilities altogether."}},{"itemId":"75f6dc7a-8bc2-5991-85ff-67f35f08a004","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3c8c9462-8e07-54b6-b070-fa955435b0ae","sourceKey":"bank:BUA204:DEC-026","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Abuja considers three investments. Returns (N million) under Recession, Normal and Boom conditions are: Treasury bills 8, 8, 8; Real estate -4, 10, 22; Shares -10, 12, 30. The probabilities of Recession, Normal and Boom are 0.25, 0.5 and 0.25. What is the Expected Value of Perfect Information?","options":["N4.5 million","N7.5 million","N15.5 million","N6 million"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"EPPI = 0.25(8) + 0.5(12) + 0.25(30) = 15.5, and EVPI = 15.5 - best EMV of 11 = N4.5 million. Option C is the EPPI itself, Option B subtracts the Treasury bill EMV instead of the best EMV, and Option D is Real estate's expected opportunity loss."}},{"itemId":"6c0de3e1-208b-5b5a-b2e4-7b2f60afb0fc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f9831d75-7c4f-5447-8219-be9de36e6c47","sourceKey":"bank:BUA204:DEC-027","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Abuja considers three investments. Returns (N million) under Recession, Normal and Boom conditions are: Treasury bills 8, 8, 8; Real estate -4, 10, 22; Shares -10, 12, 30. The probabilities of Recession, Normal and Boom are 0.25, 0.5 and 0.25. What is the Expected Opportunity Loss of Real estate?","options":["N4.5 million","N22 million","N6 million","N7.33 million"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Real estate's regrets are 8 - (-4) = 12, 12 - 10 = 2 and 30 - 22 = 8, so EOL = 0.25(12) + 0.5(2) + 0.25(8) = 3 + 1 + 2 = N6 million. Option A is the EOL of Shares (which equals the EVPI), Option D is the unweighted average of the regrets, and Option B is their simple sum."}},{"itemId":"0a292c53-e18e-598b-9574-f02d9fcb4cb3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"394b9454-006e-5ca8-8d52-5e4c23c42889","sourceKey":"bank:BUA204:DEC-028","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Abuja considers three investments. Returns (N million) under Recession, Normal and Boom conditions are: Treasury bills 8, 8, 8; Real estate -4, 10, 22; Shares -10, 12, 30. The probabilities of Recession, Normal and Boom are 0.25, 0.5 and 0.25. A consultant offers a perfectly accurate economic forecast for a fee of N6 million. What should the investor do?","options":["Accept, because the fee is below the best EMV of N11 million","Accept, because the fee is below the EPPI of N15.5 million","Decline, because the fee exceeds the EVPI of N4.5 million","Decline, because the fee exceeds the EVPI of N15.5 million"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EVPI = EPPI - best EMV = 15.5 - 11 = N4.5 million, which is the most perfect information is worth, so paying N6 million is not justified. Option B and Option A compare the fee with the wrong benchmark, and Option D uses the EPPI figure as if it were the EVPI."}},{"itemId":"b45eff3a-997e-5221-a8e1-7f9c885902d1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"431c1702-8698-55e1-adb8-903e6c49eb39","sourceKey":"bank:BUA204:DEC-029","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano manufacturer can Build a new factory (cost N50 million) or Upgrade its existing line (cost N20 million). Demand will be High with probability 0.7 or Low with probability 0.3. Revenues are: new factory N120 million (High) or N40 million (Low); upgrade N70 million (High) or N35 million (Low). What is the net EMV of building the new factory?","options":["N46 million","N96 million","N14 million","N30 million"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Net EMV = 0.7(120) + 0.3(40) - 50 = 84 + 12 - 50 = N46 million. Option B is the classic error of forgetting to subtract the N50 million cost, Option D averages the two revenues as if they were equally likely, and Option C swaps the probabilities."}},{"itemId":"d2eb5864-a9c3-511b-bcaf-b6bb73b42d6d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7896051a-eba9-53b0-a1d9-80cb5066bc96","sourceKey":"bank:BUA204:DEC-030","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano manufacturer can Build a new factory (cost N50 million) or Upgrade its existing line (cost N20 million). Demand will be High with probability 0.7 or Low with probability 0.3. Revenues are: new factory N120 million (High) or N40 million (Low); upgrade N70 million (High) or N35 million (Low). Rolling back the tree with EMV, what should the firm do?","options":["Upgrade the line; its net EMV is N6.5 million higher","Build the new factory; its net EMV is N36.5 million higher","Upgrade the line, because its cost is N30 million lower","Build the new factory; its net EMV is N6.5 million higher"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Net EMVs are new factory 84 + 12 - 50 = 46 and upgrade 49 + 10.5 - 20 = 39.5, so the new factory is better by N6.5 million. Option B compares gross revenues (96 vs 59.5) without netting off the costs, and Option C looks at cost alone instead of expected net value."}},{"itemId":"75065d2a-94ea-5b78-8e74-ede0769de216","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4b8cb6da-e0ef-5edd-8f50-dc01af61a55f","sourceKey":"bank:BUA204:DEC-031","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano manufacturer can Build a new factory (cost N50 million) or Upgrade its existing line (cost N20 million). Demand will be High with probability 0.7 or Low with probability 0.3. Revenues are: new factory N120 million (High) or N40 million (Low); upgrade N70 million (High) or N35 million (Low). If the new factory is built and demand turns out Low, what is the net outcome?","options":["-N10 million","N70 million","N15 million","N40 million"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The net outcome on that branch is revenue minus cost: 40 - 50 = -N10 million, which is the downside risk of the bigger investment. Option D ignores the cost, Option B is the net outcome if demand is High, and Option C is the upgrade's Low-demand net outcome (35 - 20)."}},{"itemId":"005e5ec9-9933-572f-93e3-827da9dd45ed","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c1afed14-d355-5f1a-a6ac-e6ead2dc8312","sourceKey":"bank:BUA204:DEC-032","parentItemId":null,"revision":1,"payload":{"prompt":"A Port Harcourt firm can Launch a product or Not launch (payoff N0). If it launches, demand is High (probability 0.6, payoff N80 million) or Low (probability 0.4). If demand is Low, the firm then decides between Withdrawing (payoff -N10 million) or running a Promotion, which succeeds with probability 0.5 (payoff N30 million) or fails with probability 0.5 (payoff -N20 million). Rolling back the tree, what value should be placed on the decision node reached when demand is Low?","options":["N5 million","-N2.5 million","-N10 million","N25 million"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"At the Promotion chance node, EMV = 0.5(30) + 0.5(-20) = 5; at the decision node the firm takes the better branch, so the node is worth max(5, -10) = N5 million. Option C picks the worse branch, Option B averages the two branches instead of choosing between them, and Option D treats the -20 as a gain."}},{"itemId":"aac0dc1a-cd4b-558c-acd3-815a3252b0ad","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"40882089-7009-511a-b38d-35d2216c6870","sourceKey":"bank:BUA204:DEC-033","parentItemId":null,"revision":1,"payload":{"prompt":"A Port Harcourt firm can Launch a product or Not launch (payoff N0). If it launches, demand is High (probability 0.6, payoff N80 million) or Low (probability 0.4). If demand is Low, the firm then decides between Withdrawing (payoff -N10 million) or running a Promotion, which succeeds with probability 0.5 (payoff N30 million) or fails with probability 0.5 (payoff -N20 million). What is the EMV of launching the product?","options":["N50 million","N48 million","N44 million","N58 million"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The Low-demand decision node is worth max(0.5(30) + 0.5(-20), -10) = 5, so EMV(Launch) = 0.6(80) + 0.4(5) = 48 + 2 = N50 million, well above N0 for not launching. Option C wrongly uses the Withdraw value of -10, Option B drops the Low-demand branch, and Option D treats the -20 promotion loss as a gain."}},{"itemId":"f2175269-797a-5d56-a627-7d9517fc7cc7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e2e2da47-49a2-5986-91df-e931aa4bac16","sourceKey":"bank:BUA204:DEC-034","parentItemId":null,"revision":1,"payload":{"prompt":"An Ibadan retailer may open a Large or a Small outlet. Payoffs (N'000) are: Large: Favourable market 250, Unfavourable market -110; Small: Favourable 130, Unfavourable -30. At what probability of a Favourable market do the two outlets have the same EMV?","options":["0.75","0.5","0.4","0.6"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Let p be P(Favourable): EMV(Large) = 250p - 110(1 - p) = 360p - 110 and EMV(Small) = 130p - 30(1 - p) = 160p - 30; setting them equal gives 200p = 80, so p = 0.4. Option D is the probability of an Unfavourable market at that point, and Option B simply assumes the states are equally likely."}},{"itemId":"d50765bb-ceb0-5868-aca4-8dc843ffd9f7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c76e8b1f-7a99-5240-a626-6fa4ed5e7733","sourceKey":"bank:BUA204:DEC-035","parentItemId":null,"revision":1,"payload":{"prompt":"An Ibadan retailer may open a Large or a Small outlet. Payoffs (N'000) are: Large: Favourable market 250, Unfavourable market -110; Small: Favourable 130, Unfavourable -30. If the probability of a Favourable market is 0.5, which outlet maximises EMV and what is its EMV?","options":["Large, with EMV of N180,000","Small, with EMV of N50,000","Small, with EMV of N80,000","Large, with EMV of N70,000"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV(Large) = 0.5(250) + 0.5(-110) = 70 and EMV(Small) = 0.5(130) + 0.5(-30) = 50, so Large is chosen with N70,000. Option C treats the -110 loss as a gain, and Option B is the Small outlet's EMV, which is lower."}},{"itemId":"5ec6eda8-6180-5f3f-9bd0-c1110bd1430d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fa86910b-a26f-5144-b1d4-284d7fae14ff","sourceKey":"bank:BUA204:DEC-036","parentItemId":null,"revision":1,"payload":{"prompt":"Two projects have the following payoffs (N'000): Project A: best 100, worst -20; Project B: best 60, worst 20. Using the Hurwicz criterion (alpha = coefficient of optimism, applied to the best payoff), at what value of alpha is the manager indifferent between A and B, and which is preferred above it?","options":["alpha = 0.5; Project B is preferred above it","alpha = 0.5; Project A is preferred above it","alpha = 0.6; Project B is preferred above it","alpha = 0.4; Project A is preferred above it"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz(A) = 100a - 20(1 - a) = 120a - 20 and Hurwicz(B) = 60a + 20(1 - a) = 40a + 20; equating them gives 80a = 40, so a = 0.5. A higher alpha means more optimism, which favours A with its larger best payoff, so Option A reverses the direction."}},{"itemId":"bdd64cb6-917a-5d86-b70f-d685abfa28e3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"155d80c6-f8f7-59c0-9bbd-91375a26ad42","sourceKey":"bank:BUA204:DEC-037","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere fruit seller buys crates at N3,000 and sells them at N5,000; unsold crates are worthless at the end of the day. She can stock 10 or 20 crates, and daily demand is either 10 or 20 crates. What is the payoff if she stocks 20 crates and demand is 10 crates?","options":["N40,000","N20,000","-N10,000","N0"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Revenue is only 10 x 5,000 = 50,000 while cost is 20 x 3,000 = 60,000, so the payoff is -N10,000. Option B uses the profit from stocking exactly 10 crates and ignores the 10 unsold ones, and Option A assumes all 20 crates are sold."}},{"itemId":"c885e044-59ff-500d-a71f-b45976ba8068","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"18dbd2ca-6d01-530b-915e-6ab3d13542e3","sourceKey":"bank:BUA204:DEC-038","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere fruit seller buys crates at N3,000 and sells them at N5,000; unsold crates are worthless at the end of the day. She can stock 10 or 20 crates, and daily demand is either 10 or 20 crates. If P(demand = 20) = 0.7 and P(demand = 10) = 0.3, what is the EMV of stocking 20 crates?","options":["N40,000","N34,000","N15,000","N25,000"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Payoffs for stocking 20 are -10,000 (demand 10) and 40,000 (demand 20), so EMV = 0.3(-10,000) + 0.7(40,000) = -3,000 + 28,000 = N25,000. Option B wrongly uses N20,000 as the low-demand payoff, Option C averages the payoffs equally, and Option A assumes high demand is certain."}},{"itemId":"d4b54016-f77a-5269-bdf9-0430d2eedb9e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"32fc9be1-7de0-59ef-ac29-9711cdfd5bd2","sourceKey":"bank:BUA204:DEC-039","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere fruit seller buys crates at N3,000 and sells them at N5,000; unsold crates are worthless at the end of the day. She can stock 10 or 20 crates, and daily demand is either 10 or 20 crates. With P(demand = 20) = 0.7 and P(demand = 10) = 0.3, what is the Expected Value of Perfect Information?","options":["N9,000","N34,000","N5,000","N14,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Stocking 10 earns N20,000 for sure and stocking 20 has EMV N25,000, so the best EMV is 25,000; EPPI = 0.3(20,000) + 0.7(40,000) = 34,000, giving EVPI = 34,000 - 25,000 = N9,000. Option D subtracts the poorer EMV, Option B is the EPPI itself, and Option C is the gap between the two EMVs."}},{"itemId":"40dc0e7c-92be-5604-a43c-b116493a631c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1194b923-8a57-5199-93e4-5d28da4e233c","sourceKey":"bank:BUA204:DEC-040","parentItemId":null,"revision":1,"payload":{"prompt":"A firm estimates P(Low demand) = 0.25 and P(Medium demand) = 0.45, with High demand as the only other state. An alternative pays N10,000 (Low), N40,000 (Medium) and N90,000 (High). What is its EMV?","options":["N20,500","N46,667","N56,500","N47,500"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Probabilities must sum to 1, so P(High) = 1 - 0.25 - 0.45 = 0.30, and EMV = 0.25(10,000) + 0.45(40,000) + 0.30(90,000) = 2,500 + 18,000 + 27,000 = N47,500. Option A leaves out the High state, Option B is the equally weighted average, and Option C uses 0.40 for High."}},{"itemId":"75b1ad7e-f54c-5ae9-86ce-285792c93ec4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d8831534-29f1-5699-825f-ec9fff64344a","sourceKey":"bank:BUA204:DEC-041","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos construction firm can Bid for a contract or Not bid (payoff N0). If it bids, it wins with probability 0.3 and earns a profit of N500,000, or loses with probability 0.7 and loses N250,000 in preparation costs. Using EMV, what should it do?","options":["Bid, because the EMV of bidding is N125,000","Not bid, because the EMV of bidding is -N25,000","Not bid, because the EMV of bidding is -N75,000","Bid, because the EMV of bidding is N325,000"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV(Bid) = 0.3(500,000) + 0.7(-250,000) = 150,000 - 175,000 = -N25,000, which is below the N0 of not bidding. Option D treats the loss as a gain, Option A averages the two payoffs as if equally likely, and Option C swaps the probabilities in part of the calculation."}},{"itemId":"6840388f-9f81-5616-9091-435be12398e4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b7f53afc-6fb3-5373-96ed-0d7f741d5086","sourceKey":"bank:BUA204:DEC-042","parentItemId":null,"revision":1,"payload":{"prompt":"An analytic and systematic approach to the study of decision making, using a rational process to select the best of several alternatives, is known as:","options":["Linear programming","Decision theory","Network analysis","Sensitivity analysis"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Decision theory is the analytic, systematic study of how to choose the best of several alternatives using a rational process. Linear programming (Option A) allocates scarce resources, network analysis (Option C) schedules project activities, and sensitivity analysis (Option D) tests how results change when assumptions change."}},{"itemId":"9be530cc-02d9-562d-9bcb-a66fb9a81b07","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a1adaf8f-bde5-571f-a3d6-49bc7ec34724","sourceKey":"bank:BUA204:DEC-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the approaches to making decisions identified in decision theory, alongside intuition, experience, voting and doing nothing?","options":["Critical path analysis","Authority","Simple regression","Hypothesis testing"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"The five approaches are intuition, experience, authority, voting and doing nothing, and authority means a decision is made by someone with the power to impose it. Hypothesis testing (Option D), critical path analysis (Option A) and regression (Option C) are quantitative techniques, not general approaches to decision making."}},{"itemId":"2be0dfa1-52ef-5327-ae76-8f3cb929096c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4c6f8f30-a0cc-541b-93fd-350a9950e264","sourceKey":"bank:BUA204:DEC-044","parentItemId":null,"revision":1,"payload":{"prompt":"Members of a cooperative society in Abeokuta choose the location of their new warehouse by a show of hands, and the option with the most hands wins. Which approach to decision making is this?","options":["Do nothing","Intuition","Authority","Voting"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Choosing the option backed by the most members is decision making by voting. Authority (Option C) would mean one person with power imposing the choice, intuition (Option B) relies on gut feeling, and doing nothing (Option A) means no choice is made at all."}},{"itemId":"9b5c6e57-3256-5424-9d68-67b06be8cd7c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e4a9ea63-e075-5e24-87e0-b24843e40597","sourceKey":"bank:BUA204:DEC-045","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery manager can decide the selling price of a loaf, but cannot control next year's rate of inflation. In decision theory, the selling price is:","options":["A state of nature","A payoff","A controllable decision variable","An uncontrollable decision variable"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Controllable variables are under the decision maker's control and are the alternatives or options available, and the bakery sets its own price. Inflation is the uncontrollable variable, or state of nature (Option D and Option A), while a payoff (Option B) is the result of a decision, not a variable the manager sets."}},{"itemId":"45922d99-80f5-518e-ab5f-088c25e4cec3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dfecc193-c9ac-58d0-98e8-a851a8690fd8","sourceKey":"bank:BUA204:DEC-046","parentItemId":null,"revision":1,"payload":{"prompt":"For a Nigerian importer, next year's naira exchange rate cannot be controlled but will strongly affect the profit from each import plan. In a payoff table, the possible exchange-rate levels are treated as:","options":["Decision alternatives","States of nature","Controllable variables","Goals or objectives"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"States of nature are the uncontrollable variables, the future conditions that the decision maker cannot influence but which determine the payoff of each alternative. The import plans themselves are the alternatives (Option A), which are controllable variables (Option C), and the goal (Option D) is the aim, such as maximising profit."}},{"itemId":"31c2702a-c054-5d05-8a1a-9f50944a407e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"661dfabd-dee3-5db1-8028-979f55deacf8","sourceKey":"bank:BUA204:DEC-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of decision making is the rational aim, such as maximising profit or minimising cost, that guides the whole decision process?","options":["Goal / Objectives","State of nature","Action","Payoff"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The goal or objective is the rational aim that guides the decision, for example maximising profit. Action (Option C) is the act of choosing among options, a state of nature (Option B) is an uncontrollable condition, and the payoff (Option D) is the benefit received from a particular choice."}},{"itemId":"27814edb-f57f-5c42-b8eb-53b7fa0a429a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d16b774d-c845-510f-b766-9de05056a287","sourceKey":"bank:BUA204:DEC-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the elements of decision making?","options":["Action","Sample size","State of nature","Payoff"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"The elements of decision making are action, states of nature, alternatives, payoff and goals or objectives. Sample size is a statistics idea about how many observations are collected, so it is not an element of a decision problem, while Option A, Option C and Option D all are."}},{"itemId":"f7bd7855-fbfc-5d36-bb9b-04b56cb0922d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aea24122-0ae3-5e9d-86d0-d74910b7dc93","sourceKey":"bank:BUA204:DEC-049","parentItemId":null,"revision":1,"payload":{"prompt":"A company places N10 million in a fixed deposit at a guaranteed 12% interest rate for one year. This is an example of decision making under:","options":["Conflict","Certainty","Risk","Uncertainty"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under certainty the outcome of each alternative is known in advance, as with a fixed deposit at a known interest rate. Risk (Option C) applies when outcomes are uncertain but their probabilities are known, and uncertainty (Option D) applies when even the probabilities are unknown."}},{"itemId":"5e4f19f3-3357-54a7-b1d0-0e5ccac6940b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"acaac397-1eba-5608-b3c4-572618152549","sourceKey":"bank:BUA204:DEC-050","parentItemId":null,"revision":1,"payload":{"prompt":"An FMCG firm in Lagos is launching a new drink. Ten years of sales records show high demand in 6 out of 10 similar launches. The firm is making the decision under:","options":["Certainty","Ambiguity","Uncertainty","Risk"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under risk, outcomes are not certain but the probability of each state of nature is known or can be estimated, here from historical launch data (high demand about 0.6). Certainty (Option A) would mean the outcome is known in advance, and uncertainty (Option C) would mean no probabilities can be assigned."}},{"itemId":"c34832e9-9495-5e16-a4e7-08020102c6c7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d371f85c-0bd9-50fd-858c-a3a1703ee03c","sourceKey":"bank:BUA204:DEC-051","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian fintech plans to enter a completely new, unresearched foreign market and has no basis for assigning probabilities to possible demand levels. Which set of tools fits this situation?","options":["Deterministic models and linear programming","EVPI and expected opportunity loss","Expected Monetary Value and decision trees","Maximax, Maximin, Minimax Regret, Hurwicz and Laplace"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"With no probabilities the firm faces uncertainty, which is handled with the five criteria: Maximax, Maximin, Minimax Regret, Hurwicz and Laplace. EMV, decision trees, EVPI and EOL (Option C and Option B) all need probabilities, which is the risk situation, and deterministic models (Option A) suit certainty."}},{"itemId":"4be91f22-5c90-55ad-9505-6e4df6304ab5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"51ded331-861f-59a4-9acd-eb455f7363a4","sourceKey":"bank:BUA204:DEC-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which tools are associated with decision making under certainty?","options":["Hurwicz and Laplace criteria","Maximax and Maximin criteria","Expected Monetary Value and decision trees","Deterministic models such as linear programming"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under certainty all information about the uncontrollable variable is known, so deterministic models such as linear programming are used. EMV and decision trees (Option C) belong to risk situations, while the criteria in Option B and Option A belong to uncertainty."}},{"itemId":"0cb15b87-f9e9-50c0-ae2e-26757cb3b67f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"72b77caf-7ed9-5f3f-9432-e381b5b0bad8","sourceKey":"bank:BUA204:DEC-054","parentItemId":null,"revision":1,"payload":{"prompt":"The Hurwicz criterion is also called the:","options":["Criterion of realism","Criterion of equal likelihood","Criterion of regret","Criterion of pessimism"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz is called the criterion of realism because it takes a weighted average of the best and worst outcomes rather than looking at only one extreme. Equal likelihood (Option B) describes Laplace, pessimism (Option D) describes Maximin, and regret (Option C) describes the Savage criterion."}},{"itemId":"4c10968c-37d1-5a88-bf09-2a01bae92196","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ecafca58-60ae-5f5d-a0ea-ca732c3e6830","sourceKey":"bank:BUA204:DEC-055","parentItemId":null,"revision":1,"payload":{"prompt":"In the Hurwicz criterion, alpha x Max + (1 - alpha) x Min, where alpha is the coefficient of optimism, setting alpha = 1 gives the same decision as which criterion?","options":["Laplace","Maximax","Maximin","Minimax Regret"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"With alpha = 1 the formula becomes 1 x Max + 0 x Min, so only each row's best payoff counts, which is exactly Maximax. Setting alpha = 0 would give Maximin (Option C), while Laplace (Option A) averages all payoffs and Minimax Regret (Option D) works from a regret table."}},{"itemId":"2fd9cc52-d01e-5b05-bfc7-a4e649129024","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"be707215-a232-5726-b378-e334cd08321a","sourceKey":"bank:BUA204:DEC-056","parentItemId":null,"revision":1,"payload":{"prompt":"The Savage criterion is another name for:","options":["The Minimax Regret criterion","The criterion of realism","The Maximin criterion","The equally likely criterion"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Savage is the Minimax Regret criterion: build a regret table and choose the alternative with the smallest maximum regret. Maximin (Option C) looks at the worst payoffs, equally likely (Option D) is Laplace, and the criterion of realism (Option B) is Hurwicz."}},{"itemId":"d9c06bfa-1112-586f-bf3e-e9ff2d310e68","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cfce8613-ad45-5517-b525-958d92e6aca8","sourceKey":"bank:BUA204:DEC-057","parentItemId":null,"revision":1,"payload":{"prompt":"Without any probability data, a manager in Enugu gives each of four possible market conditions a weight of 1/4 and picks the option with the highest average payoff. Which criterion is she using?","options":["Expected Monetary Value","Maximin","Laplace","Hurwicz"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace assumes all states of nature are equally likely, so each of four states gets 1/4 and the highest average is chosen. Hurwicz (Option D) weights only the best and worst payoffs, EMV (Option A) uses estimated probabilities from data, and Maximin (Option B) uses only the worst payoffs."}},{"itemId":"c503c45b-dadf-515d-ba09-ad7d336b391b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"985bcdf0-dc3c-5b38-a5db-4e4e5d347ffe","sourceKey":"bank:BUA204:DEC-058","parentItemId":null,"revision":1,"payload":{"prompt":"A cautious Onitsha trader, with no idea how likely each market condition is, looks at the worst possible outcome of each stock option and picks the option whose worst outcome is least bad. Which criterion is this?","options":["Maximin","Minimax Regret","Maximax","Laplace"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Choosing the best of the worst outcomes is the Maximin, or pessimistic, criterion favoured by risk-averse decision makers. Maximax (Option C) is the optimist's best-of-the-best, Minimax Regret (Option B) works on opportunity losses rather than payoffs, and Laplace (Option D) averages all outcomes."}},{"itemId":"dcb191ed-74da-586f-8170-7b1dce142229","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5f06c04c-2a9d-5fb4-bd71-e5df1ca4d33c","sourceKey":"bank:BUA204:DEC-059","parentItemId":null,"revision":1,"payload":{"prompt":"An Abuja hotel manager says: 'Whatever happens, I want to keep to a minimum how much I would have missed by not picking the best option for the market that actually occurs.' Which criterion matches her thinking?","options":["Maximin","Hurwicz","Maximax","Minimax Regret"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"What she 'would have missed' is the regret or opportunity loss, and keeping the largest possible regret as small as possible is the Minimax Regret (Savage) criterion. Maximin (Option A) protects the worst payoff, not the worst regret, and Maximax (Option C) chases the highest payoff."}},{"itemId":"51dabf87-75fa-50c5-a290-62753d27781b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8d01c177-1ae3-55b2-bf2b-972f27f6a330","sourceKey":"bank:BUA204:DEC-060","parentItemId":null,"revision":1,"payload":{"prompt":"The expression Sum of [Probability of state x Regret under that state] measures the:","options":["Expected Monetary Value (EMV)","Expected Opportunity Loss (EOL)","Hurwicz value","Expected Value of Perfect Information (EVPI)"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Weighting each regret (opportunity loss) by its probability and adding gives the Expected Opportunity Loss. EMV (Option A) weights payoffs, not regrets, and EVPI (Option D) is the expected payoff with perfect information minus the best EMV."}},{"itemId":"3bc8eb45-e48c-5f8e-86bb-b40711df4bb3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e51c3aff-d582-5349-9d99-467d6c26b50e","sourceKey":"bank:BUA204:DEC-063","parentItemId":null,"revision":1,"payload":{"prompt":"In the nine-stage decision-making process, which stage comes immediately after 'Identify the possible outcomes'?","options":["Implementation of decision","Selection of best optimal action","Screening alternative courses of action","List the pay-off/profit of each"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"The nine stages run: define the problem, gather information, screen alternatives, identify outcomes, list the pay-off of each, analyse the alternatives, select the best action, implement and evaluate. Screening (Option C) comes before identifying outcomes, while selection (Option B) and implementation (Option A) come later."}},{"itemId":"9815d181-a029-577b-a387-926fe3f52dbf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ccd922d6-64ad-5f1c-b1df-b9a186f54556","sourceKey":"bank:BUA204:DEC-064","parentItemId":null,"revision":1,"payload":{"prompt":"In the six-step version of the decision-making process, which step comes immediately after 'List all possible decision alternatives'?","options":["Identify all possible outcomes (states of nature)","Clearly define the problem","Make and implement the decision","Select and apply an appropriate decision model"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The six steps are: define the problem, list the alternatives, identify the possible outcomes (states of nature), list the payoff for each alternative-outcome combination, select and apply a decision model, then make and implement the decision. Defining the problem (Option B) comes first, while choosing a model (Option D) and implementing (Option C) come only after the payoffs are listed."}},{"itemId":"0bfa8eab-6365-52d9-be07-376e7f7f909e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b2745552-8e0b-5eea-8a4e-3ce2dade6690","sourceKey":"bank:BUA204:DEC-065","parentItemId":null,"revision":1,"payload":{"prompt":"Why may EMV be a poor guide for a one-off, high-stakes decision such as a Nigerian SME investing its entire capital in one project?","options":["EMV does not use probabilities","EMV cannot be calculated when payoffs include losses","EMV always recommends the safest alternative","EMV is a long-run average and ignores the risk of a single large loss"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV is the average result over many repetitions, so for a one-off decision it hides the chance of a loss that could threaten the firm's survival and ignores the manager's attitude to risk. Option B is false because losses enter the EMV as negative payoffs, Option C is false because EMV is risk-neutral, and Option A is false because EMV is built from probabilities."}},{"itemId":"fdeda9e6-3953-52d5-ab92-8808a4604b6c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c8ab4aeb-6c7e-5216-9448-86232122f5b7","sourceKey":"bank:BUA204:INT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The scientific approach to managerial decision-making in which raw data are processed and manipulated with mathematical and statistical tools to produce meaningful information for a decision is called:","options":["Brainstorming","Intuitive decision-making","Qualitative analysis","Quantitative analysis"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis turns raw data into meaningful information using mathematical and statistical tools, giving a structured, scientific basis for decisions. Option C relies on descriptive, judgemental information rather than mathematical processing, option B rests mainly on experience and gut feeling, and option A is an idea-generation exercise, not a data-processing approach."}},{"itemId":"e219b241-a5ea-5c1f-91c6-1f246226b6c9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ef72a829-126e-517f-9c9e-acf276dcd721","sourceKey":"bank:BUA204:INT-003","parentItemId":null,"revision":1,"payload":{"prompt":"Why did businesses take up operational research methods after the Second World War?","options":["The methods were shown to remove the need for any managerial judgement in business","Military planners refused to share the methods, so firms had to develop entirely new ones","Governments made the use of mathematical models compulsory for every registered company","They saw that the logic used to allocate scarce military resources could also optimise production, inventory, transport and investment decisions"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"During the war, Allied planners used mathematics to deploy scarce resources such as radar and convoys, and firms later recognised that the same logic could optimise production schedules, inventory, transport routes and investment portfolios. Option C invents a legal requirement, option A is wrong because quantitative methods complement rather than replace judgement, and option B contradicts the idea that business borrowed the wartime logic."}},{"itemId":"1c4c9113-c9e2-5562-94a7-f3b780a14d58","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a8a4e831-842f-5136-b519-0f333253d2c5","sourceKey":"bank:BUA204:INT-004","parentItemId":null,"revision":1,"payload":{"prompt":"The managing director of a Lagos manufacturing firm says: 'Now that we have a production model, our managers no longer need to use their judgement.' This view is mistaken mainly because quantitative analysis:","options":["is only useful for government and military planning, not for manufacturing firms","complements managerial judgement by narrowing down the reasonable choices before final judgement is applied","can only handle qualitative factors such as staff morale and the political climate","should only be used after a decision has already been taken by intuition"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis gives an objective, repeatable and defensible basis for decisions, but it complements rather than replaces judgement: it narrows the range of reasonable choices, and managers still weigh factors that resist measurement. Option A is wrong because firms widely use these methods, option D reverses the proper order, and option C describes qualitative judgement, not quantitative analysis."}},{"itemId":"475b16df-8c9c-54ff-a43a-3d67129650f7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b296fd52-c9b7-53f3-8937-579f91996f83","sourceKey":"bank:BUA204:INT-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a feature of Quantitative Analysis in Management (QAM)?","options":["It avoids comparing alternatives so that decisions can be made quickly","It replaces measurable data with the opinions of experienced staff","It relies mainly on the personal experience of the most senior manager","It provides an orderly and systematic framework for defining, analysing and solving problems"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"One feature of QAM is that it offers an orderly, systematic framework for defining, analysing and solving problems, alongside using measurable data and evaluating alternatives systematically. Option C describes intuitive decision-making, option A is the opposite of QAM's systematic comparison of options, and option B contradicts its use of numerical, measurable data rather than opinions."}},{"itemId":"5ae1dcdd-16f6-55ba-860d-738632abda88","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d6181ea5-fcb8-5bfc-b691-b44e61bdbbe8","sourceKey":"bank:BUA204:INT-006","parentItemId":null,"revision":1,"payload":{"prompt":"Within QAM, AHP and ANP are used as:","options":["multicriteria decision-making models (Analytic Hierarchy Process and Analytic Network Process)","methods for recording customer behaviour by direct observation","formulas for calculating simple and compound interest","qualitative techniques that rely on expert opinion alone, like SWOT analysis"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"AHP (Analytic Hierarchy Process) and ANP (Analytic Network Process) are multicriteria decision-making models, used when a choice must balance several criteria at once. Option B describes the observation method of data collection, option D confuses them with qualitative tools, and option C refers to time-value-of-money formulas, which are unrelated."}},{"itemId":"797d15fc-10cc-59c1-bfa2-d56ca97583bc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d95247a0-544f-5749-8191-5c92f5b75819","sourceKey":"bank:BUA204:INT-007","parentItemId":null,"revision":1,"payload":{"prompt":"Through forecasting and statistical analysis, managers can predict future trends and reduce business risks. This importance of QAM is best described as:","options":["Competitive advantage","Performance accountability","Resource allocation","Forecasting and risk reduction"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Predicting future trends and lowering business risk through forecasting and statistical analysis is the 'forecasting and risk reduction' benefit of QAM. Option C is about sharing out scarce resources efficiently, option B is about justifying and evaluating managers' own performance, and option A is about winning against rivals through data-driven decisions."}},{"itemId":"caee6b18-a166-5554-aab5-53f1646c966e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ad2cd682-c6d8-5e6d-87ad-fa827dc7d049","sourceKey":"bank:BUA204:INT-008","parentItemId":null,"revision":1,"payload":{"prompt":"QAM gives managers a means to justify and evaluate their own managerial performance. This importance of QAM is known as:","options":["Performance accountability","Problem-solving","Better decisions","Forecasting and risk reduction"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Performance accountability means QAM provides an accountable, evidence-based way for managers to justify and evaluate their own performance. Option C is about making superior decisions from facts and logic, option B is about solving complex problems systematically, and option D is about predicting trends and reducing risk."}},{"itemId":"430416e3-2bc6-55be-b881-10f18964d822","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f7e04801-6b15-521d-98af-20bd7b2018e3","sourceKey":"bank:BUA204:INT-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an importance of Quantitative Analysis in Management?","options":["It helps allocate scarce resources more effectively and efficiently","It guarantees that every decision taken will be profitable","It helps organisations gain competitive advantage through data-driven decisions","It helps proffer solutions to complex business problems systematically"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"QAM improves the quality of decisions, but no technique can guarantee that every decision will be profitable, because outcomes still depend on uncertain events and on factors that cannot be measured. Options A, C and D (resource allocation, competitive advantage and problem-solving) are all genuine benefits of QAM."}},{"itemId":"ddce4dc1-8514-590d-9ebc-6e9ba8381093","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"925b2cac-a427-5a2e-ab53-166cfde0b27b","sourceKey":"bank:BUA204:INT-010","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage company in Ibadan uses quantitative techniques for sales forecasting, pricing decisions and measuring how effective its advertisements are. In which functional area is QAM being applied?","options":["Marketing management","Human resource management","Production and operations management","Supply chain and logistics"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Sales forecasting, market research, pricing decisions and advertisement effectiveness are QAM applications in marketing management. Option B covers workforce planning and staff scheduling, option C covers inventory control, capacity planning, scheduling and quality control, and option D covers transportation, route optimisation and warehouse selection."}},{"itemId":"cbc4178b-3e73-5afc-b900-a452d3042b9d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"245d3ca1-a183-5aca-bc78-3e08bbf28d2b","sourceKey":"bank:BUA204:INT-011","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital uses quantitative methods for workforce planning, nurse scheduling and compensation analysis. This is an application of QAM in:","options":["Financial management","Human resource management","Supply chain and logistics","Marketing management"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Workforce planning, staff scheduling, compensation analysis and productivity analysis are QAM applications in human resource management. Option A covers investment appraisal, budgeting and cash flow forecasting, option D covers forecasting sales and pricing, and option C covers transport planning and warehouse selection."}},{"itemId":"a60b0098-8116-5957-8f1a-1631461e1d9b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b62c3153-0e1b-5bd1-ae47-35b656dfcdcd","sourceKey":"bank:BUA204:INT-012","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano-based distributor uses quantitative models to decide where to site a new warehouse and which delivery routes its trucks should follow. The functional area of application is:","options":["Marketing management","Financial management","Human resource management","Supply chain and logistics"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Transportation planning, route optimisation, distribution planning and warehouse selection are QAM applications in supply chain and logistics. Option A deals with sales forecasting and pricing, option B with investment appraisal and budgeting, and option C with workforce planning and staff scheduling."}},{"itemId":"e31b5c08-e703-5436-993f-98a8ccefd5f3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"edcdbd01-8e56-51d6-8453-3e6ca8053b75","sourceKey":"bank:BUA204:INT-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a typical application of QAM in financial management?","options":["Cash flow forecasting","Route optimisation for delivery vans","Budgeting","Portfolio management"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Route optimisation is a supply chain and logistics application, not a financial management one. Options C, A and D (budgeting, cash flow forecasting and portfolio management) are all listed QAM applications in financial management, together with investment appraisal and risk analysis."}},{"itemId":"a2783459-b11a-5add-ae23-fc8216121760","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"69a83d39-6115-5ac0-be88-cc1eeb96499f","sourceKey":"bank:BUA204:INT-014","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket manager computes the mean, median and mode of daily sales for last month simply to summarise how the store performed. Which type of analytical tool is she using?","options":["Inferential analysis","Simulation","Likert scale","Descriptive analysis"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Descriptive analysis uses measures such as the mean, median and mode to summarise and describe a set of data. Option A would be used to draw conclusions about a larger population from a sample, option B imitates a real process to test outcomes, and option C is an ordinal scale for measuring attitudes."}},{"itemId":"dbc85255-6379-59d4-943f-edb4aa672a74","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b7938f63-54c5-563e-b63f-29d823a9811b","sourceKey":"bank:BUA204:INT-015","parentItemId":null,"revision":1,"payload":{"prompt":"A bank surveys 400 of its 50,000 customers and uses the results to reach conclusions about all 50,000 customers. This is an example of:","options":["Simulation","Descriptive analysis","Inferential analysis","Mathematical modelling"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Inferential analysis draws conclusions about a whole population from a sample, exactly as the bank does by generalising from 400 customers to all 50,000. Option B only summarises the data actually collected, option D builds deterministic or probabilistic models of a situation, and option A imitates a real process to test outcomes."}},{"itemId":"9e5c81c0-ae5b-5f50-985b-c0ced7ce026c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"de8601c3-a5dc-555b-9cfc-318368f6aaa7","sourceKey":"bank:BUA204:INT-016","parentItemId":null,"revision":1,"payload":{"prompt":"As an analytical tool in QAM, mathematical modelling refers to:","options":["interviewing experts and averaging their opinions","building deterministic or probabilistic models that represent real situations","summarising data with the mean, median and mode","measuring attitudes on an ordinal scale such as 1 to 5"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Mathematical modelling represents a real situation with deterministic or probabilistic models made of numbers, symbols and equations. Option D describes a Likert scale, option C describes descriptive analysis, and option A describes a qualitative, opinion-based approach."}},{"itemId":"6c48570f-6f82-54d6-912e-9d376bd9ea70","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b1dc0674-24b0-5570-b56e-29cadefaefb7","sourceKey":"bank:BUA204:INT-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following lists the stages of the seven-stage quantitative analysis process in the CORRECT order?","options":["Define the problem, construct the model, acquire input data, develop a solution, implement the results, test the solution, analyse the results","Define the problem, construct the model, acquire input data, test the solution, develop a solution, analyse the results, implement the results","Acquire input data, analyse the results, define the problem, construct the model, develop a solution, test the solution, implement the results","Define the problem, construct the model, acquire input data, develop a solution, test the solution, analyse the results, implement the results"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"The process runs: define the problem, construct the model, acquire input data, develop a solution, test the solution, analyse the results, and finally implement the results. Option B tests a solution before one has been developed, option A implements before testing and analysing, and option C analyses results before the problem is even defined."}},{"itemId":"2bba2365-c392-5e6f-8572-d3d4ba828f55","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a72347f7-9569-5628-b262-c92e53fa8bac","sourceKey":"bank:BUA204:INT-019","parentItemId":null,"revision":1,"payload":{"prompt":"In the seven-stage quantitative analysis process, which stage comes immediately BEFORE implementing the results?","options":["Analysing the results","Testing the solution","Acquiring input data","Developing a solution"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Analysing the results (stage 6), which includes sensitivity analysis, is the last step before the solution is implemented in stage 7. Option B is stage 5, option D is stage 4 and option C is stage 3, all of which come earlier."}},{"itemId":"ed64d09d-8308-5448-b6ad-aa099f3c9b1f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"29dbc640-0c8d-56e3-9dbd-39310344cec8","sourceKey":"bank:BUA204:INT-020","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of the quantitative analysis process in which the model is manipulated to arrive at the best (optimal) solution, for example by solving equations or using a linear programming algorithm, is:","options":["Testing the solution","Implementing the results","Constructing the model","Developing a solution"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Developing a solution means working the model, by solving equations, doing what-if analysis or running algorithms such as linear programming, to find the best answer. Option C is about translating the problem into mathematical relationships in the first place, option A checks the data and model for accuracy, and option B puts the solution into use in the organisation."}},{"itemId":"fdc3bd60-ebfb-5d66-8ce7-8d4379668a16","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d51c7527-96ed-54f8-92e5-69b812a20dd4","sourceKey":"bank:BUA204:INT-021","parentItemId":null,"revision":1,"payload":{"prompt":"Translating a business problem into equations, inequalities, formulas or logical statements that represent reality in simplified form takes place at which stage of the quantitative analysis process?","options":["Constructing the model","Defining the problem","Analysing the results","Acquiring input data"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Constructing the model is the stage where the problem is turned into mathematical relationships such as equations and inequalities. Option B produces a clear statement of the problem but no equations, option D gathers the figures the model will use, and option C studies the implications of the solution, including sensitivity analysis."}},{"itemId":"dd23cbdd-fa00-5315-8738-9e0f8b3976a4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0feb0d15-e374-5d0b-ab4c-e01c05c452ce","sourceKey":"bank:BUA204:INT-022","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst at a Lagos food company builds an excellent model to cut packaging costs, but the company's real problem was falling sales caused by poor distribution. The project fails mainly because of a weakness at which stage?","options":["Defining the problem","Acquiring input data","Testing the solution","Implementing the results"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"A poorly defined problem leads to a technically correct but practically useless answer, which is what happens when the wrong problem (packaging cost) is modelled. Option B would be the cause only if the figures fed into the model were wrong, option C checks accuracy but cannot fix the wrong question, and option D concerns putting a solution into practice, which is not the failure here."}},{"itemId":"30e406b1-7f17-5f8a-816e-d745a8ecccd1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5a8d86ed-2e7e-5fd0-92ae-c8f3b51713d0","sourceKey":"bank:BUA204:INT-023","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's inventory model is correctly built, but a clerk keyed in last year's demand figures wrongly, so the model recommends order quantities that make no sense. This situation illustrates:","options":["Garbage in, garbage out (GIGO)","Resistance to change","An iconic model","Sensitivity analysis"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"GIGO means that even a perfect model produces poor recommendations when the input data are unreliable, which is exactly what the wrong demand figures cause. Option B is about people refusing a new solution, option D is a deliberate test of how results change when inputs change, and option C is a physical model that looks like the real object."}},{"itemId":"96a84cbd-18e8-59ba-a42f-5a57b550bbfe","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e298a1e3-f187-557f-b42a-d9afde846739","sourceKey":"bank:BUA204:INT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Before rolling out a new sales-forecasting model, an analyst runs it on last year's data to see whether it would have predicted the sales that actually occurred. Which stage of the quantitative analysis process is this?","options":["Developing a solution","Implementing the results","Defining the problem","Testing the solution"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Testing the solution checks both the input data and the model for accuracy and consistency, often by comparing results with historical outcomes, as the analyst does here. Option C comes much earlier and only states the problem, option A finds the solution but does not check it against past results, and option B happens after testing, when the model is put into use."}},{"itemId":"d9076771-da95-5029-ada0-8560b013c980","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bc64737b-5993-5a40-896e-223a1e12a0e3","sourceKey":"bank:BUA204:INT-025","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of the quantitative analysis process that involves incorporating the solution into the organisation, and which often needs the support of operating management and careful change management, is:","options":["Constructing the model","Testing the solution","Implementing the results","Analysing the results"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Implementing the results is the final stage, where the solution is built into the organisation's operations, so it depends heavily on management support and change management. Option D studies the implications and sensitivity of the solution, option B checks accuracy before use, and option A is an early stage that builds the mathematical relationships."}},{"itemId":"a7f28e82-020e-5a18-8644-4a05dbec7af6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f20f7126-820b-5dfa-bc76-90243180d9e1","sourceKey":"bank:BUA204:INT-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly compares quantitative and qualitative analysis?","options":["Quantitative analysis is largely objective, while qualitative analysis is largely subjective","Quantitative analysis uses experience and intuition, while qualitative analysis uses statistics and models","Both approaches rely only on numerical, measurable data","Quantitative analysis is largely subjective, while qualitative analysis is largely objective"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis uses numerical data, mathematics and models, so it is largely objective; qualitative analysis uses experience, intuition and opinion, so it is largely subjective. Option D reverses the two, option B swaps their tools, and option C is wrong because qualitative analysis works with descriptive, judgemental data."}},{"itemId":"3824f03d-168a-5b2c-962c-70d17e8b15ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"98b94fa9-91f0-5209-b5f9-24e0dc632dce","sourceKey":"bank:BUA204:INT-029","parentItemId":null,"revision":1,"payload":{"prompt":"A Port Harcourt importer's model recommends ordering 500 cartons, but the MD postpones the order because the government is expected to change import policy soon. In decision-making terms, the expected policy change is best described as:","options":["a schematic model of the import process","an input data error of the garbage-in, garbage-out type","a qualitative factor that is hard to quantify but may dominate the decision","a mathematical constraint already built into the model"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Government action is a qualitative factor: it is frequently impossible to quantify yet it may dominate the final decision, which is why quantitative results are combined with judgement. Option B would mean the model's data were wrong, which is not the case, option D is wrong because the policy change is outside the model, and option A is a type of model, not a factor."}},{"itemId":"4da3cb47-5d2e-51ba-b7ab-36f6cf009ec8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1401931a-a5f4-5209-a08c-d33dc004bed7","sourceKey":"bank:BUA204:INT-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a physical (iconic) model?","options":["An organisational chart showing reporting lines","A graph relating vehicle speed to fuel consumption","A model aircraft used in wind-tunnel testing","The break-even formula FC / (P - V)"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"A physical (iconic) model looks like the real object, only larger or smaller, as a model aircraft does. Options B and A are schematic (analogue) models, which do not look like the real thing but behave like it, and option D is a mathematical (symbolic) model built from symbols and numbers."}},{"itemId":"6135dce5-d646-526a-a0ce-c44124299826","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"883642b6-fc03-5931-9b87-5a8a5bb48717","sourceKey":"bank:BUA204:INT-031","parentItemId":null,"revision":1,"payload":{"prompt":"A transport manager uses a graph showing how fuel consumption changes as vehicle speed changes. The graph does not look like a vehicle but behaves like the real relationship. This is a:","options":["Physical (iconic) model","Scale model","Schematic (analogue) model","Mathematical (symbolic) model"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"A schematic (analogue) model does not look like the real object but behaves like it, such as a graph relating speed to fuel consumption. Options A and B look like the real object (only larger or smaller), and option D uses equations and symbols rather than a picture of the relationship."}},{"itemId":"f797a8a1-4558-538e-8c16-48eaebf9bc8a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ce632511-b828-59ce-bc76-b6f179a71d40","sourceKey":"bank:BUA204:INT-032","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between a physical (iconic) model and a schematic (analogue) model?","options":["An iconic model is always larger than the real object, while an analogue model is always smaller","An iconic model is used only in finance, while an analogue model is used only in production","An iconic model looks like the real object, while an analogue model does not look like it but behaves like it","An iconic model uses equations, while an analogue model uses physical materials"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"An iconic model physically resembles the real thing at a different scale, whereas an analogue model behaves like the real system without looking like it, such as a graph or an organisational chart. Option D describes mathematical models, option A is wrong because iconic models can be larger or smaller, and option B invents limits on where each type is used."}},{"itemId":"ec7b2fd2-0c91-5a4f-87ec-7ec584f7cd60","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d628de93-ce72-5b2c-b573-16c5ec2a1a9a","sourceKey":"bank:BUA204:INT-033","parentItemId":null,"revision":1,"payload":{"prompt":"A model, in quantitative analysis, is best described as:","options":["an exact copy of reality that must match every detail to be useful","a simplified representation or abstraction of reality that captures the essential features of a problem","a decision reached by intuition without any data","a collection of raw, unprocessed figures"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A model is a simplified representation (abstraction) of reality, like an architect's blueprint; it need not be exact as long as it captures the essential features of the problem. Option A is wrong because models are deliberately simplified, option C describes intuition, not a model, and option D describes raw data, which a model processes."}},{"itemId":"61d98e50-edcb-58f8-9f0d-58d2489b1663","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4a94f22c-ef32-51f0-8e2d-1c9bf04cbbf1","sourceKey":"bank:BUA204:INT-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of using models in management decision-making?","options":["Models allow managers to ask what-if questions cheaply without disrupting operations","Models save time and money compared with trial-and-error in the real system","Models guarantee that all the assumptions behind a decision are correct","Models force managers to be explicit about objectives, constraints and assumptions"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Models make assumptions explicit, but they cannot guarantee those assumptions are correct; that is why solutions must be tested. Options A, D and B are genuine advantages: cheap what-if analysis, forcing clarity about objectives and assumptions, and saving time and money over real-world trial and error."}},{"itemId":"842f9aa1-2375-567b-91a8-30ef2b02aa81","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c58d91a6-6bd4-5f21-83a9-91fc3e589fbe","sourceKey":"bank:BUA204:INT-035","parentItemId":null,"revision":1,"payload":{"prompt":"Instead of trying ten different prices in its shops for a month each, an Abuja retailer tests all ten prices on a spreadsheet model in one afternoon. Which advantage of models does this illustrate?","options":["Models make qualitative factors such as competitor reaction irrelevant","Models remove the need to collect any input data","Models allow what-if questions to be asked cheaply without disrupting actual operations","Models guarantee that the chosen price will maximise profit in practice"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Testing the prices on a model lets the retailer ask what-if questions quickly and cheaply without disturbing real sales. Option B is wrong because a model still needs accurate data (GIGO), option A is wrong because qualitative factors still matter, and option D overstates what a model can promise in real conditions."}},{"itemId":"8f9f7c58-f466-5159-8c74-5a6f4cbba3b3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"977775cc-f0d4-5ddf-a54f-ac8bb4c53aa1","sourceKey":"bank:BUA204:INT-036","parentItemId":null,"revision":1,"payload":{"prompt":"A manager applies a standard textbook-style inventory model, unchanged, to a unique problem involving fast-spoiling fresh fish, and the recommendations prove unworkable. This is a problem associated with:","options":["Developing a model: a stock model may need modifying to fit special circumstances","Acquiring input data: the figures were gathered too optimistically","Testing: the solution was compared with historical outcomes","Implementation: staff resisted the change"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"A common pitfall in developing a model is believing a stock quantitative model fits a unique problem; the model may need to be modified for special circumstances such as perishability. Option B is a data problem, not a model-fit problem, option D concerns people resisting change, and option C describes a proper check, not a problem."}},{"itemId":"7fd2e632-beee-552b-a1d5-0762d83654db","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a87786c5-6091-58d0-9a81-c06f0bff357d","sourceKey":"bank:BUA204:INT-038","parentItemId":null,"revision":1,"payload":{"prompt":"Before a solution is used, it should be tested to determine whether it is realistic, easy to use, valuable to the organisation under varying conditions, and:","options":["approved by competitors","worth the cost","free of every assumption","as complex as possible"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Solutions should be tested to see whether they are realistic, easy to use, valuable under varying conditions and worth the cost of implementing. Option A is irrelevant because competitors do not approve a firm's decisions, option C is impossible because every model rests on assumptions, and option D is wrong because a good model should be as simple as possible while still capturing the real features."}},{"itemId":"5b214c17-45d8-521a-bd2d-a13e48c9e645","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0480e08d-5adc-537e-af97-8290789aeb4a","sourceKey":"bank:BUA204:INT-039","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a Nigerian bank resist a new, quantitatively derived queue-management system. Which response best addresses this implementation problem?","options":["Dropping sensitivity analysis so that the results look more certain","Communication, training and management support to overcome organisational inertia","Replacing the mathematical model with a physical scale model","Collecting a larger set of input data and rerunning the model"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Resistance to change is an implementation problem, and success requires communication, training and management support to overcome organisational inertia. Option D improves data but does nothing about people's resistance, option C changes the type of model without solving the human problem, and option A would hide useful information rather than build acceptance."}},{"itemId":"49052b96-b9b2-5223-86c4-6babcc76f9e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d6ff7ded-fa54-596f-909a-307c07d97a3b","sourceKey":"bank:BUA204:INT-040","parentItemId":null,"revision":1,"payload":{"prompt":"Method A has a higher fixed cost but a lower variable cost per unit than Method B, and the two methods cost the same at 2,000 units. If expected output is 3,500 units, which method should management choose?","options":["Method B, because a lower fixed cost always makes a method cheaper","Method A, because above the indifference point its lower variable cost makes it cheaper","Either method, because they cost the same at every level of output","Method B, because above the indifference point the higher variable cost is spread over more units"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Above the indifference point, the method with the lower variable cost per unit is cheaper because its higher fixed cost is spread over more units, so Method A wins at 3,500 units. Option A ignores the variable cost, which dominates at high output, option C is wrong because they are equal only at 2,000 units, and option D confuses which cost is spread over more units."}},{"itemId":"35f96c13-e07c-57f1-b8c7-eeb102d7c016","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"15f48625-4003-550b-999d-2ed4498bf409","sourceKey":"bank:BUA204:MAT-001","parentItemId":null,"revision":1,"payload":{"prompt":"In the linear total cost function TC = a + bx, where x is the number of units produced, the slope b represents:","options":["the total cost","the fixed cost","the variable cost per unit","the number of units produced"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"In y = a + bx the slope b is the rate of change of y as x rises, which in a total cost function is the variable cost of each extra unit. Option B is the intercept a, option A is y itself, and option D is the independent variable x."}},{"itemId":"fba56544-6a1a-5441-84bc-37731968d1b4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"91b7b358-b3ac-5c2d-8e6d-4c022db6f97a","sourceKey":"bank:BUA204:MAT-003","parentItemId":null,"revision":1,"payload":{"prompt":"On a break-even chart, the region to the LEFT of the break-even point, between the total cost and total revenue lines, represents:","options":["the contribution per unit","the margin of safety","a profit","a loss"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"To the left of the break-even point total cost is above total revenue, so the gap between them is a loss; to the right TR exceeds TC and the gap is profit. Option C describes the right-hand region, option B measures how far sales are above break-even, and option A is a per-unit figure, not an area on the chart."}},{"itemId":"7744a62a-00e5-5ee7-b319-70e752ef0638","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"961ecbaa-b9b2-5af7-8538-f3072bbd986c","sourceKey":"bank:BUA204:MAT-004","parentItemId":null,"revision":1,"payload":{"prompt":"If a firm increases its selling price per unit while fixed cost and variable cost per unit stay the same, its break-even point in units will:","options":["remain unchanged","decrease","become equal to fixed cost","increase"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"A higher price raises contribution per unit (P - V), so fewer units are needed to cover the same fixed cost, and BEP = FC / (P - V) falls; on the chart the TR line becomes steeper and the break-even point moves left. Option D would follow a fall in price or a rise in costs, option A ignores the change in contribution, and option C mixes units with naira."}},{"itemId":"872b0dab-a4df-5c8c-a167-0c7cd0fb999e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8cfd06d1-3634-5150-9c00-a1a41c8bab94","sourceKey":"bank:BUA204:MAT-005","parentItemId":null,"revision":1,"payload":{"prompt":"If the variable cost per unit rises while selling price and fixed cost stay the same, the break-even point in units will:","options":["decrease","increase","fall to zero","remain unchanged"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"A higher variable cost reduces contribution per unit (P - V), so more units are needed to recover the same fixed cost and BEP = FC / (P - V) rises. Option A would follow a rise in price or a fall in variable cost, option D ignores that contribution has changed, and option C could only happen if fixed cost were zero."}},{"itemId":"daa33952-d601-568d-8407-d88190de69ee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cecff2e1-7ef9-52ae-bbf2-2ae01c6b5124","sourceKey":"bank:BUA204:MAT-006","parentItemId":null,"revision":1,"payload":{"prompt":"Margin, as a pricing measure, expresses profit as a percentage of:","options":["total revenue of the whole firm","selling price","fixed cost","cost price"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Margin (%) = (Selling Price - Cost) / Selling Price x 100, so its base is the selling price. Option D is the base for mark-up, which is why mark-up is the larger figure for a profitable item, while options C and A are not used as the base for either measure."}},{"itemId":"cc5982b6-537a-5151-b025-d84eb96b9b5d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3662d4a0-8a02-5a6f-9525-2470c5d647a5","sourceKey":"bank:BUA204:MAT-007","parentItemId":null,"revision":1,"payload":{"prompt":"For the same principal and interest rate over a period longer than one year, annual compound interest compared with simple interest gives:","options":["a larger accumulated amount","a larger amount only when the rate is above 10%","the same accumulated amount","a smaller accumulated amount"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"From the second year onward compound interest earns interest on interest already added, so it always accumulates more than simple interest over more than one year at any positive rate. Option C is only true for exactly one year, option D has it backwards, and option B adds a condition that does not exist."}},{"itemId":"86830af4-7424-52f9-be37-8e7774429b4c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3ff9fe45-6b77-5793-b329-09bd1edef592","sourceKey":"bank:BUA204:MAT-008","parentItemId":null,"revision":1,"payload":{"prompt":"Logarithms are best described as:","options":["the inverse of indices, used to simplify exponential calculations","equations whose variables are raised only to the first power","statements of constraints using signs such as less than or equal to","two or more equations solved together for several unknowns"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A logarithm is the inverse of an index (power) and simplifies exponential calculations such as continuous growth. Option B describes linear equations, option C describes linear inequalities, and option D describes simultaneous equations."}},{"itemId":"5ee3fd76-9901-5120-82ac-e4c2a73840fb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"082f7693-cc20-51ab-bb38-012d3bbb006b","sourceKey":"bank:BUA204:MAT-009","parentItemId":null,"revision":1,"payload":{"prompt":"Company X has a margin of safety of 3,000 units while Company Y, in the same industry, has a margin of safety of 200 units. What does this tell management?","options":["Company X's fixed costs must be lower than Company Y's","Company X has a higher break-even point than Company Y","Company Y is less likely than Company X to make a loss if sales fall","Company X's sales can fall much further than Company Y's before it starts making a loss"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"The margin of safety shows how far sales can fall before the business makes a loss, so a larger margin means lower risk. Option B cannot be concluded because the margin depends on both actual sales and break-even sales, option C reverses the meaning, and option A cannot be concluded without the cost figures."}},{"itemId":"cb751536-08b6-58dc-877c-338c6c4237cf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c77eea9a-4782-55e4-acd4-db23e5f9d3c4","sourceKey":"bank:BUA204:MAT-010","parentItemId":null,"revision":1,"payload":{"prompt":"The amount that each unit sold contributes towards covering fixed costs (and then towards profit) is called the:","options":["contribution margin","margin of safety","marginal cost","average cost"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution margin, CM = P - v, is what each unit adds towards covering fixed cost once its own variable cost has been met. Option C is the cost of one extra unit, option D is total cost divided by output, and option B is actual sales minus break-even sales."}},{"itemId":"90af7a7a-7c48-58d1-b06b-342149a829ea","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a6dc7442-e01c-56ab-9c62-c502af97cb54","sourceKey":"bank:BUA204:MAT-011","parentItemId":null,"revision":1,"payload":{"prompt":"The cost of producing one additional unit of output is known as:","options":["contribution margin","average cost","fixed cost","marginal cost"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Marginal cost, MC = change in TC / change in Q, is the extra cost of producing one more unit. Option B spreads total cost over all units, option C does not change with output at all, and option A is price minus variable cost per unit."}},{"itemId":"077a290e-e745-561b-aef9-e1050d872a9f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a531de7b-b029-5325-9010-e6f6653cf501","sourceKey":"bank:BUA204:MAT-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a FIXED cost for a bakery?","options":["Monthly rent on the bakery premises","Flour used for each loaf","Packaging for each loaf","Piece-rate wages paid per loaf"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A fixed cost stays constant regardless of output, as rent does whether the bakery makes 100 or 10,000 loaves. Options B, C and D all rise with each loaf produced, so they are variable costs."}},{"itemId":"3a6fbf3e-e5a5-594a-8a1d-68224162878b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a23aa3fd-850c-5852-8b42-15242a8ae649","sourceKey":"bank:BUA204:MAT-013","parentItemId":null,"revision":1,"payload":{"prompt":"Two cost plans are compared: one has a low fixed charge and a high cost per unit, the other a high fixed charge and a low cost per unit. BELOW their indifference point, which plan is cheaper?","options":["The plan with the lower cost per unit","The plan with the lower fixed charge","Both plans cost exactly the same","It cannot be determined without the selling price"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Below the indifference point few units are involved, so the fixed charge dominates and the plan with the lower fixed charge is cheaper; above it, the lower cost per unit wins. Option A is only cheaper above the indifference point, option C is true only at that point, and option D is wrong because the comparison involves costs only."}},{"itemId":"6e8cfc7e-4c33-5858-87a4-15cf3a1de4e3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cf52f91d-3556-5371-930f-fe78ab883e7d","sourceKey":"bank:BUA204:MAT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Break-even revenue (break-even sales in naira) is calculated as:","options":["break-even quantity x variable cost per unit","fixed cost / selling price per unit","break-even quantity x selling price per unit","fixed cost x selling price per unit"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"BER = BEQ x P converts the break-even number of units into naira sales. Option A gives the total variable cost at break-even, not revenue, option D has no meaning, and option B ignores variable cost and would understate break-even units."}},{"itemId":"58e3ba02-16b6-5ba4-bafa-f253de0c82a1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c80b0917-81fb-5b90-b00d-624fd573a3c9","sourceKey":"bank:BUA204:MAT-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following expressions is equal to profit, where Q is quantity, P is price, v is variable cost per unit and FC is fixed cost?","options":["(P - v) - FC","FC / (P - v)","Q(P - v) + FC","Q(P - v) - FC"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Profit = TR - TC = PQ - (FC + vQ) = Q(P - v) - FC, i.e. total contribution minus fixed cost. Option C adds fixed cost instead of subtracting it, option B is the break-even quantity, and option A forgets to multiply contribution by the number of units."}},{"itemId":"5328f1ef-9cb3-56bb-84b3-831544f6e85b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a219aff9-cb6c-505d-aa60-5b1f44398a25","sourceKey":"bank:BUA204:MAT-016","parentItemId":null,"revision":1,"payload":{"prompt":"In the formula Percentage Change = (New Value - Old Value) / Old Value x 100, the change is measured relative to:","options":["the average of the old and new values","the sum of the old and new values","the new value","the old value"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Percentage change always divides the change by the original (old) value. Dividing by the new value, as in option C, is a common mistake that understates an increase, and options A and B are not part of the formula."}},{"itemId":"f2c1e341-c56e-557f-b501-f39e0d9fa0c5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"83101565-38bb-51b4-8d77-dcc0e09f24a2","sourceKey":"bank:BUA204:MAT-017","parentItemId":null,"revision":1,"payload":{"prompt":"A manager states that 'labour used must not exceed 100 hours per week'. Which mathematical form best expresses this?","options":["An index such as (100)^2","A linear inequality such as 4x + 2y <= 100","A logarithm such as log(100)","A linear equation such as 4x + 2y = 100"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"A limit that must not be exceeded is a constraint, written as a linear inequality using <= ; such inequalities are the constraints of linear programming. Option D forces labour to be exactly 100 hours, which is stricter than 'must not exceed', while options C and A are unrelated operations."}},{"itemId":"2f12e15d-d4a5-5c08-b25e-1a0f2c13fca7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"de8447f0-d0f6-53af-9705-455456d7e969","sourceKey":"bank:BUA204:MAT-018","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos printing firm has fixed costs of N450,000 per month and a variable cost of N320 per copy. Using TC = FC + VQ, what is its total cost for a month in which it produces 2,500 copies?","options":["N1,250,000","N800,000","N450,320","N144,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"TC = FC + VQ = 450,000 + 320 x 2,500 = 450,000 + 800,000 = N1,250,000. Option B is only the variable cost and forgets the fixed cost, option C adds the cost of a single unit instead of 2,500 units, and option D wrongly multiplies the fixed and variable costs."}},{"itemId":"d3950e20-67b2-55fc-8601-05d83b23f7ca","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d0a2c0d1-7be8-5146-a683-752087cdbba5","sourceKey":"bank:BUA204:MAT-019","parentItemId":null,"revision":1,"payload":{"prompt":"A furniture maker in Aba sells 1,840 stools at N6,500 each. What is its total revenue?","options":["N1,196,000","N119,600,000","N8,340","N11,960,000"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"TR = P x Q = 6,500 x 1,840 = N11,960,000. Option C adds price and quantity instead of multiplying, while options A and B are place-value slips that are ten times too small or too large."}},{"itemId":"4f85da3e-f3b5-5e85-aff3-827b27442591","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dbb5931d-0e94-525c-916d-fe9868643b7f","sourceKey":"bank:BUA204:MAT-020","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N1,200,000, a selling price of N900 per unit and a variable cost of N540 per unit. What is its profit when it sells 5,000 units?","options":["N3,300,000","N3,000,000","N600,000","N1,800,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Profit = Q(P - v) - FC = 5,000 x (900 - 540) - 1,200,000 = 1,800,000 - 1,200,000 = N600,000. Option D is total contribution and forgets the fixed cost, option A ignores variable cost, and option B adds the fixed cost instead of subtracting it."}},{"itemId":"44d9595e-4d50-5862-a2e9-297b86807c7f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"caf2f4da-de39-5323-8c3a-012e1019f3a2","sourceKey":"bank:BUA204:MAT-021","parentItemId":null,"revision":1,"payload":{"prompt":"A water-packaging firm has fixed costs of N2,400,000, sells each bag pack at N1,500 and has a variable cost of N900 per pack. If market demand is only 3,000 packs, what is the result?","options":["A profit of N1,800,000","A loss of N2,400,000","A loss of N600,000","A profit of N600,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Profit = Q(P - v) - FC = 3,000 x 600 - 2,400,000 = 1,800,000 - 2,400,000 = -600,000, a loss of N600,000, because 3,000 packs is below the break-even point of 4,000 packs. Option D gets the size right but the sign wrong, option B is the loss only at zero output, and option A is total contribution with fixed cost ignored."}},{"itemId":"7f6a4f2e-b27c-5cba-8287-f38437a04534","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"db019045-c065-5562-8328-45586e474dea","sourceKey":"bank:BUA204:MAT-022","parentItemId":null,"revision":1,"payload":{"prompt":"Chika's Kitchen has fixed costs of N840,000 per month. Each meal sells for N650 and has a variable cost of N440. What is the break-even point in meals per month?","options":["1,909 meals","4,000 meals","1,292 meals","771 meals"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"BEP = FC / (P - V) = 840,000 / (650 - 440) = 840,000 / 210 = 4,000 meals. Option C divides by price and ignores variable cost, option A divides by variable cost, and option D adds the variable cost to price instead of subtracting it."}},{"itemId":"6d94245b-bb40-5fca-a3d2-3eaaa26916ec","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1256862b-766a-5041-89a3-b6e24f8f74f7","sourceKey":"bank:BUA204:MAT-023","parentItemId":null,"revision":1,"payload":{"prompt":"A cosmetics producer has fixed costs of N1,800,000, a selling price of N2,000 per jar and a variable cost of N1,250 per jar. What is its break-even revenue in naira?","options":["N1,800,000","N3,000,000","N4,800,000","N2,880,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"BEQ = 1,800,000 / (2,000 - 1,250) = 2,400 jars, so BER = BEQ x P = 2,400 x 2,000 = N4,800,000. Option B multiplies by variable cost instead of price, option A multiplies by contribution (which just gives back the fixed cost), and option D uses a formula with no meaning."}},{"itemId":"463b3394-0db4-5516-bae4-f52e43b54a25","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"747834c5-7061-5599-ba00-4a872a8f83c6","sourceKey":"bank:BUA204:MAT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi Bags has fixed costs of N960,000, sells each bag for N1,200 and has a variable cost of N800 per bag. How many bags must it sell to earn a target profit of N640,000?","options":["1,600 bags","2,400 bags","1,333 bags","4,000 bags"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Required units = (FC + Target Profit) / (P - V) = (960,000 + 640,000) / (1,200 - 800) = 1,600,000 / 400 = 4,000 bags. Option A forgets that fixed cost must be covered first, option B is just the break-even point, and option C divides by price instead of contribution."}},{"itemId":"6c4121b7-7d8d-5987-b83c-ee31f6f7b452","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"50243430-ffc3-544c-9160-5e9f3d4b8c9b","sourceKey":"bank:BUA204:MAT-025","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N1,500,000, a selling price of N750 and a variable cost of N450 per unit. It currently sells 7,200 units. What is its margin of safety in units?","options":["12,200 units","2,200 units","5,000 units","5,200 units"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"BEP = 1,500,000 / (750 - 450) = 5,000 units, so margin of safety = actual sales - break-even sales = 7,200 - 5,000 = 2,200 units. Option C is the break-even point itself, option D computes break-even by dividing by price, and option A adds instead of subtracting."}},{"itemId":"79997b67-ac6f-5774-8cf5-0607430494b2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4df7d57c-367b-57f4-bdd0-a8e5f9076c15","sourceKey":"bank:BUA204:MAT-026","parentItemId":null,"revision":1,"payload":{"prompt":"A snack maker has fixed costs of N720,000, sells each pack for N400 and has a variable cost of N280 per pack. Budgeted sales are 8,500 packs. What is the margin of safety in naira (valued at selling price)?","options":["N1,000,000","N300,000","N700,000","N2,400,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"BEP = 720,000 / (400 - 280) = 6,000 packs; margin of safety = 8,500 - 6,000 = 2,500 packs, and in naira 2,500 x 400 = N1,000,000. Option C values the margin at variable cost, option B values it at contribution per unit, and option D is break-even revenue, not the margin of safety."}},{"itemId":"e9e45f8d-9899-5dfd-be97-3b5bb9f9780e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dd862d76-ec50-55c6-94c9-4fc47fb2a5d7","sourceKey":"bank:BUA204:MAT-027","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N1,350,000, a selling price of N500 and a variable cost of N320 per unit, and actual sales of 9,000 units. Expressing the margin of safety as a percentage of ACTUAL sales, what is the margin of safety (to 1 decimal place)?","options":["16.7%","36.0%","20.0%","83.3%"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"BEP = 1,350,000 / (500 - 320) = 7,500 units; margin of safety = 9,000 - 7,500 = 1,500 units, and 1,500 / 9,000 x 100 = 16.7%. Option C divides by break-even sales instead of actual sales, option D is break-even sales as a share of actual sales, and option B is the contribution as a share of price."}},{"itemId":"e85f5c7e-92e1-50bf-a569-517e2ad2c016","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"916b1744-35e8-5c55-a19e-f815c5d9377e","sourceKey":"bank:BUA204:MAT-028","parentItemId":null,"revision":1,"payload":{"prompt":"A cap maker has fixed costs of N600,000 and a variable cost of N350 per cap. It expects to sell exactly 4,000 caps. What selling price per cap would make it just break even?","options":["N650","N500","N150","N350"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"At break-even TR = TC, so P x 4,000 = 600,000 + 350 x 4,000; P = 350 + 600,000 / 4,000 = 350 + 150 = N500. Option C covers only fixed cost per cap, option D covers only variable cost, and option A doubles the fixed-cost share by mistake."}},{"itemId":"f1f5e1d1-8d73-5775-8f0a-e41e4a514b36","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"60023a89-e64f-548e-916a-939e113b116e","sourceKey":"bank:BUA204:MAT-029","parentItemId":null,"revision":1,"payload":{"prompt":"A firm breaks even at 2,500 units. Its selling price is N1,800 per unit and its variable cost is N1,100 per unit. What are its fixed costs?","options":["N4,500,000","N1,750,000","N2,750,000","N7,250,000"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Since BEP = FC / (P - V), FC = BEP x (P - V) = 2,500 x (1,800 - 1,100) = 2,500 x 700 = N1,750,000. Option A is break-even revenue, option C is total variable cost at break-even, and option D adds price and variable cost."}},{"itemId":"c24da989-e3f5-515f-a137-0455e4b8e9c1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"664a590a-d6d6-5485-91b8-05a9d3d6cc82","sourceKey":"bank:BUA204:MAT-030","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's fixed cost is N300,000 and its variable cost is N125 per unit. Using AC = TC / Q, what is its average cost per unit at an output of 2,000 units?","options":["N150","N550,000","N275","N125"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"TC = 300,000 + 125 x 2,000 = 550,000, so AC = 550,000 / 2,000 = N275. Option D is only the variable cost per unit, option A is only fixed cost per unit, and option B is total cost, which has not been divided by output."}},{"itemId":"857e1f4d-a347-5c4c-b52f-315c567be1a6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"38840e3e-5d19-5f3c-a10b-4a763b5b2083","sourceKey":"bank:BUA204:MAT-031","parentItemId":null,"revision":1,"payload":{"prompt":"A factory's total cost is N1,240,000 when it produces 400 units and N1,330,000 when it produces 450 units. Using MC = change in TC / change in Q, what is the marginal cost per unit over this range?","options":["N3,100","N1,800","N90,000","N2,955.56"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"MC = (1,330,000 - 1,240,000) / (450 - 400) = 90,000 / 50 = N1,800 per unit. Options D and A are average costs at one output level, and option C is the total change in cost, not divided by the change in output."}},{"itemId":"7dcb47b3-9c0f-5acc-8afd-85cd6b427175","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b0fad350-51bf-54fd-b24f-3c2caab5a768","sourceKey":"bank:BUA204:MAT-032","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's total cost follows a straight line TC = a + bx. Total cost is N650,000 at 1,000 units and N860,000 at 1,600 units. What is the variable cost per unit, b?","options":["N580.77","N350","N650","N537.50"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"b = (change in TC) / (change in units) = (860,000 - 650,000) / (1,600 - 1,000) = 210,000 / 600 = N350. Options C and D are average costs at one level, which wrongly include fixed cost, and option A is an average of the two totals, which also includes fixed cost."}},{"itemId":"77ba36e5-dad9-5e2e-a14c-9f3c7a9008d0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7568743a-77de-56ba-a75d-dbe6df3a108c","sourceKey":"bank:BUA204:MAT-033","parentItemId":null,"revision":1,"payload":{"prompt":"A delivery firm's monthly cost is linear, TC = a + bx, where x is the number of deliveries. TC is N380,000 for 200 deliveries and N590,000 for 500 deliveries. What is the fixed cost, a?","options":["N240,000","N30,000","N700","N210,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"First b = (590,000 - 380,000) / (500 - 200) = N700 per delivery; then a = TC - bx = 380,000 - 700 x 200 = N240,000. Option C is the variable cost per delivery, option B pairs the lower cost with the higher output, and option D is just the change in total cost."}},{"itemId":"89077467-7c0b-5014-a109-4cff54a6cc32","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"52bb7e3b-7516-5c0f-8756-f7fb01987555","sourceKey":"bank:BUA204:MAT-034","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Onitsha buys a pair of shoes for N1,600 and sells it for N2,000. What is the mark-up percentage?","options":["20%","4%","25%","80%"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Mark-up = (SP - Cost) / Cost x 100 = (2,000 - 1,600) / 1,600 x 100 = 400 / 1,600 x 100 = 25%. Option A is the margin, which divides by selling price, option D is cost as a share of selling price, and option B simply divides the profit by 100."}},{"itemId":"71abf67f-7b98-56d1-b7da-44467e43449a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"df1793b4-2344-52b3-a9e5-a27b0ebae909","sourceKey":"bank:BUA204:MAT-035","parentItemId":null,"revision":1,"payload":{"prompt":"A phone accessory costs N3,600 and is sold for N4,500. What is the margin on selling price?","options":["20%","80%","25%","125%"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Margin = (SP - Cost) / SP x 100 = (4,500 - 3,600) / 4,500 x 100 = 900 / 4,500 x 100 = 20%. Option C is the mark-up on cost, which is always larger for a profitable item, option B is cost as a share of price, and option D is price as a share of cost."}},{"itemId":"d52f8f9a-801f-5f4c-ae2e-60245a1ad7e4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"34a5ddee-afa3-5fdc-9354-7479bf9b0db7","sourceKey":"bank:BUA204:MAT-036","parentItemId":null,"revision":1,"payload":{"prompt":"A bookshop prices its stock at a mark-up of 35% on cost. What is the selling price of a book that costs N2,400?","options":["N3,692.31","N2,435","N1,560","N3,240"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"SP = Cost x (1 + mark-up) = 2,400 x 1.35 = N3,240. Option A treats 35% as a margin on selling price, option C subtracts the mark-up, and option B adds 35 naira instead of 35%."}},{"itemId":"2ba8ad1b-280f-50ee-b9e1-748302cf8eb1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fd39faf5-157d-5018-b20d-ee851e5e9996","sourceKey":"bank:BUA204:MAT-037","parentItemId":null,"revision":1,"payload":{"prompt":"A retailer wants a margin of 25% on SELLING PRICE for an item that costs her N3,000. What selling price should she charge?","options":["N4,500","N4,000","N2,250","N3,750"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Margin is based on selling price, so Cost = SP x (1 - 0.25); SP = 3,000 / 0.75 = N4,000 (check: profit 1,000 / 4,000 = 25%). Option D applies 25% to cost, which is a mark-up and gives only a 20% margin, option C subtracts instead of adding, and option A doubles the percentage."}},{"itemId":"8144cd98-0a95-51d8-a457-9a2ab785f2b0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f50b5da0-e6eb-5bb6-90be-beb512083bbd","sourceKey":"bank:BUA204:MAT-038","parentItemId":null,"revision":1,"payload":{"prompt":"A shirt is sold for N6,900, which includes a mark-up of 15% on cost. What did the shirt cost?","options":["N4,600","N6,000","N5,865","N7,935"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"SP = Cost x (1 + 0.15), so Cost = 6,900 / 1.15 = N6,000. Option C takes 15% off the selling price, which treats the mark-up as if it were based on selling price, option A divides by 1.5 instead of 1.15, and option D adds a further mark-up instead of removing it."}},{"itemId":"e899a11d-e570-52a8-96e7-3f71c22c8206","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"60633741-7f88-5749-8794-4af598f04980","sourceKey":"bank:BUA204:MAT-039","parentItemId":null,"revision":1,"payload":{"prompt":"An item is sold at a mark-up of 60% on cost. What is the equivalent margin on selling price?","options":["60.0%","40.0%","37.5%","150.0%"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Take cost = 100; SP = 160, profit = 60, so margin = 60 / 160 x 100 = 37.5%. Option A assumes mark-up and margin are equal, option B subtracts from 100, and option D divides by 40, which is the formula for converting a margin into a mark-up."}},{"itemId":"8e517850-49de-5144-8fc7-32f053277160","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"52cfb5aa-87df-5318-a8bd-ab563e21334c","sourceKey":"bank:BUA204:MAT-040","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket earns a margin of 30% on the selling price of its goods. What is the equivalent mark-up on cost, to 2 decimal places?","options":["23.08%","30.00%","70.00%","42.86%"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Take SP = 100; profit = 30, cost = 70, so mark-up = 30 / 70 x 100 = 42.86%. Option B assumes margin and mark-up are the same, option A divides by 130, which converts the other way round, and option C is just the cost share of price."}},{"itemId":"65eca1a3-55f0-59f9-973f-c35dcb55a7ed","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ba7f6b14-4d9e-587a-83d5-0c9e361db296","sourceKey":"bank:BUA204:MAT-041","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos restaurant's monthly sales rose from N1,250,000 to N1,550,000. What is the percentage increase, to 1 decimal place?","options":["19.4%","124.0%","30.0%","24.0%"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Percentage change = (New - Old) / Old x 100 = (1,550,000 - 1,250,000) / 1,250,000 x 100 = 300,000 / 1,250,000 x 100 = 24.0%. Option A divides by the new value, option B is the new value as a percentage of the old, and option C is a place-value slip."}},{"itemId":"f93a2341-96d4-5e48-bcfa-511628a48d71","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"19823a9c-c924-5851-9dbb-fe78b43cd5c7","sourceKey":"bank:BUA204:MAT-042","parentItemId":null,"revision":1,"payload":{"prompt":"Production of cartons at a factory fell from 480 per day to 396 per day. What is the percentage change?","options":["A decrease of 17.5%","A decrease of 21.2%","An increase of 17.5%","A decrease of 82.5%"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Percentage change = (396 - 480) / 480 x 100 = -84 / 480 x 100 = -17.5%, a decrease of 17.5%. Option B divides by the new value, option C has the right size but the wrong direction, and option D is the new output as a percentage of the old."}},{"itemId":"e1ab564c-7f6c-5c76-994d-22b3b354a753","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6e40ae16-e1df-5754-ac02-60f712fc0312","sourceKey":"bank:BUA204:MAT-043","parentItemId":null,"revision":1,"payload":{"prompt":"Two partners, Ade and Bola, share a profit of N960,000 in the ratio 3:5 respectively. How much does Bola receive?","options":["N1,600,000","N480,000","N360,000","N600,000"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Total parts = 3 + 5 = 8; Bola's share = 5/8 x 960,000 = N600,000. Option C is Ade's share, option A wrongly divides by Ade's 3 parts instead of the total, and option B splits the profit equally."}},{"itemId":"d112eab1-6e46-5635-9b4b-4126f12695b6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ca3bed80-7a45-58d8-bcfc-ecceb3d664fb","sourceKey":"bank:BUA204:MAT-044","parentItemId":null,"revision":1,"payload":{"prompt":"If 12 machine operators produce 1,500 units in a shift, how many units would 20 operators produce in a shift, assuming output is directly proportional to the number of operators?","options":["2,500 units","900 units","30,000 units","1,508 units"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Output per operator = 1,500 / 12 = 125 units, so 20 operators produce 20 x 125 = 2,500 units. Option B inverts the proportion, option D adds the extra operators as if each were one unit, and option C forgets to divide by the original 12 operators."}},{"itemId":"a5ecb6e8-c1b6-5840-974c-4604fcc43753","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5d221ca0-a170-55e4-88dc-8c26a91c1cf3","sourceKey":"bank:BUA204:MAT-045","parentItemId":null,"revision":1,"payload":{"prompt":"Using I = P x R x T, what is the simple interest on N450,000 invested for 3 years at 12% per annum?","options":["N162,000","N54,000","N612,000","N182,218"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"I = P x R x T = 450,000 x 0.12 x 3 = N162,000. Option B is the interest for only one year, option D is compound interest, and option C is the total amount (principal plus interest) rather than the interest."}},{"itemId":"7f674272-872b-5036-bdd5-cf1cff14bf31","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f5e7b10e-cb9e-5d67-8220-c6573c8e1c99","sourceKey":"bank:BUA204:MAT-046","parentItemId":null,"revision":1,"payload":{"prompt":"N380,000 is deposited at 7.5% per annum simple interest for 4 years. Using A = P(1 + RT), what is the amount at the end of the period?","options":["N494,000","N114,000","N408,500","N507,478"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A = P(1 + RT) = 380,000 x (1 + 0.075 x 4) = 380,000 x 1.30 = N494,000. Option B is only the interest, option D uses the compound interest formula, and option C covers just one year."}},{"itemId":"76172346-03a0-52f4-a445-f856d6bbdc83","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2695fcd9-6971-5821-9f5d-79d4a4ea8f1a","sourceKey":"bank:BUA204:MAT-047","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N250,000 attracts simple interest of N90,000 over 4 years. What is the annual rate of interest?","options":["6.62%","0.09%","9%","36%"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"From I = PRT, R = I / (P x T) = 90,000 / (250,000 x 4) = 0.09 = 9% per annum. Option D forgets to divide by the 4 years, option B forgets to convert the decimal to a percentage, and option A wrongly divides by principal plus interest."}},{"itemId":"20ee9c8b-b8b0-5e69-8f27-6e2cdc5890f3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9bbd84a2-41d8-52b3-b1bc-d85b852185d1","sourceKey":"bank:BUA204:MAT-048","parentItemId":null,"revision":1,"payload":{"prompt":"How many years will it take N400,000 to grow to N560,000 at 8% per annum simple interest?","options":["3.57 years","17.5 years","5 years","4.37 years"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Interest needed = 560,000 - 400,000 = 160,000; T = I / (P x R) = 160,000 / (400,000 x 0.08) = 160,000 / 32,000 = 5 years. Option B uses the final amount instead of the interest, option D is the compound-interest answer, and option A bases the yearly interest on the final amount instead of the principal."}},{"itemId":"5099447c-680c-5a24-b19d-906ee4272d27","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"470d1ad2-94ed-5185-b083-1a3ad867bc52","sourceKey":"bank:BUA204:MAT-049","parentItemId":null,"revision":1,"payload":{"prompt":"Mrs Okafor invests N500,000 at 12% per annum compounded annually. Using A = P(1 + R)^n, what is the amount after 3 years, to the nearest naira?","options":["N680,000","N202,464","N702,464","N627,200"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"A = 500,000 x (1.12)^3 = 500,000 x 1.404928 = N702,464. Option A is the simple-interest amount, option B is only the compound interest earned, and option D compounds for one year too few."}},{"itemId":"070a9ebe-6fbf-54ca-b8c4-689cc2c3fc20","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9f79569a-71f7-530a-a898-18f970792a68","sourceKey":"bank:BUA204:MAT-050","parentItemId":null,"revision":1,"payload":{"prompt":"N800,000 is invested for 4 years at 9% per annum compounded annually. What is the compound interest EARNED, to the nearest naira?","options":["N288,000","N329,265","N1,129,265","N257,265"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"A = 800,000 x (1.09)^4 = 1,129,265.29, so interest earned = A - P = 1,129,265.29 - 800,000 = N329,265. Option C is the full amount rather than the interest, option A is simple interest, and option D subtracts the first year's amount instead of the principal."}},{"itemId":"7b39bb8e-7663-5de8-84aa-af8885272e43","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1aa6860d-8389-539d-b8c5-f2c1e60ed496","sourceKey":"bank:BUA204:MAT-051","parentItemId":null,"revision":1,"payload":{"prompt":"N600,000 is invested for 4 years at 10% per annum. By how much does the amount under annual compound interest exceed the amount under simple interest, to the nearest naira?","options":["N278,460","N60,000","N38,460","N240,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Compound: 600,000 x (1.1)^4 = 878,460; simple: 600,000 x (1 + 0.1 x 4) = 840,000; difference = N38,460, the interest on interest. Option D is the simple interest itself, option A is the compound interest itself, and option B is just one year's simple interest."}},{"itemId":"fc00bd80-e7e2-50d1-80d3-4d3b2ced898f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ad827fd4-205a-5079-a31d-37c2f0e04732","sourceKey":"bank:BUA204:MAT-052","parentItemId":null,"revision":1,"payload":{"prompt":"N200,000 is invested at 8% per annum compounded QUARTERLY for 2 years. Using A = P(1 + R)^n with R as the rate per quarter and n as the number of quarters, what is the amount, to the nearest naira?","options":["N234,332","N233,280","N208,080","N370,186"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"R per quarter = 8% / 4 = 2% and n = 4 x 2 = 8 quarters, so A = 200,000 x (1.02)^8 = N234,332. Option B compounds annually, option D uses the annual rate for every quarter, and option C uses the quarterly rate but only 2 periods."}},{"itemId":"1160c59d-5d64-5773-b3a9-159589557f52","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a631ac96-e67f-5d6a-a238-4dbba4f89034","sourceKey":"bank:BUA204:MAT-053","parentItemId":null,"revision":1,"payload":{"prompt":"How much must a parent invest today at 10% per annum compounded annually to have N1,000,000 for school fees in 3 years' time? Give the answer to the nearest naira.","options":["N1,331,000","N769,231","N729,000","N751,315"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"From A = P(1 + R)^n, P = A / (1 + R)^n = 1,000,000 / (1.1)^3 = 1,000,000 / 1.331 = N751,315. Option B uses simple interest, option C reduces by 10% each year, which is not the same as dividing by 1.1, and option A grows the amount instead of discounting it."}},{"itemId":"549bd12d-fd72-5ba7-a3b8-b7f529edf0d6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e3f166b9-b764-542e-bbf1-6525ffd68c3d","sourceKey":"bank:BUA204:MAT-054","parentItemId":null,"revision":1,"payload":{"prompt":"Solve for x: 5x - 18 = 2x + 27.","options":["x = 15","x = 6.43","x = 9","x = 3"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Collect x terms on one side and numbers on the other: 5x - 2x = 27 + 18, so 3x = 45 and x = 15. Option D subtracts 18 instead of adding it, option B adds the x coefficients instead of subtracting, and option C ignores the 2x on the right-hand side."}},{"itemId":"b46ae6fb-868f-5179-8f77-62b94defd3e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9402936a-7451-512b-afea-40b14bd360b4","sourceKey":"bank:BUA204:MAT-055","parentItemId":null,"revision":1,"payload":{"prompt":"A sales agent earns a fixed weekly allowance of N15,000 plus N450 commission on every unit sold. Last week she earned N42,000 in total. How many units did she sell?","options":["127 units","93 units","60 units","33 units"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Set up the equation 15,000 + 450x = 42,000; then 450x = 27,000 and x = 27,000 / 450 = 60 units. Option B ignores the fixed allowance, option A adds the allowance instead of subtracting it, and option D divides only the allowance by the commission."}},{"itemId":"0bccf108-1c97-597f-8355-08c818f35285","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"33b367d2-8922-5b61-8c59-3df25aa22160","sourceKey":"bank:BUA204:MAT-056","parentItemId":null,"revision":1,"payload":{"prompt":"Data Plan A charges a fixed N1,000 per month plus N8 per megabyte; Data Plan B charges a fixed N3,500 per month plus N3 per megabyte. At how many megabytes per month do the two plans cost the same?","options":["900 MB","500 MB","437.50 MB","227.27 MB"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Set the costs equal: 1,000 + 8m = 3,500 + 3m, so 5m = 2,500 and m = 500 MB. Option A adds the fixed fees instead of subtracting, option D adds the rates instead of subtracting, and option C ignores Plan A's fee and Plan B's rate."}},{"itemId":"d216db3d-be4f-59d5-9079-b3dedae69066","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b07c6bfe-1ebd-5f28-a897-ede21f30a7a1","sourceKey":"bank:BUA204:MAT-057","parentItemId":null,"revision":1,"payload":{"prompt":"Courier X charges N8,000 plus N120 per km; Courier Y charges N20,000 plus N70 per km. For a 400 km delivery, which courier is cheaper and by how much?","options":["Courier X, by N8,000","Courier X, by N20,000","Courier Y, by N12,000","Courier Y, by N8,000"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Cost X = 8,000 + 120 x 400 = N56,000; Cost Y = 20,000 + 70 x 400 = N48,000, so Y is cheaper by N8,000. This fits the indifference point of 12,000/50 = 240 km: beyond it the lower per-km rate wins. Option A picks the wrong courier, option C compares fixed charges only, and option B compares only the per-km charges and picks the wrong courier."}},{"itemId":"ad802dba-03ac-5639-a3ea-7b964aa9bdae","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"779c0276-bc11-5f64-b87c-60a800282ae8","sourceKey":"bank:BUA204:MAT-058","parentItemId":null,"revision":1,"payload":{"prompt":"A firm sells only cabinets at N15,000 each and stools at N6,000 each. Last month it sold 150 items in total for revenue of N1,530,000. How many cabinets did it sell?","options":["80 cabinets","75 cabinets","102 cabinets","70 cabinets"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Let T = cabinets and S = stools: T + S = 150 and 15,000T + 6,000S = 1,530,000. Substituting S = 150 - T gives 15,000T + 900,000 - 6,000T = 1,530,000, so 9,000T = 630,000 and T = 70 (stools = 80). Option A is the number of stools, option C assumes all revenue came from cabinets, and option B simply halves the total."}},{"itemId":"84054291-d5e9-564e-a2f4-e2177e94b6ef","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"96af80ae-21f9-5ce0-b97b-ec538052b0b8","sourceKey":"bank:BUA204:MAT-059","parentItemId":null,"revision":1,"payload":{"prompt":"A caterer's orders give two equations for the price of a plate of rice (x) and a plate of beans (y), in naira: 2x + 3y = 3,100 and 4x + y = 3,200. What is the price of a plate of rice, x?","options":["N800","N630","N650","N600"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Multiply the second equation by 3: 12x + 3y = 9,600; subtract the first: 10x = 6,500, so x = N650 (and y = N600). Check: 2(650) + 3(600) = 3,100. Option D is the value of y, option A ignores y in the second equation, and option B averages the totals over all coefficients."}},{"itemId":"b66eb482-5b08-59ac-aff0-ba7ce2e0520b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c8f4335-bb19-522c-8a08-99271f41ba72","sourceKey":"bank:BUA204:MAT-060","parentItemId":null,"revision":1,"payload":{"prompt":"Each chair takes 4 hours of carpentry and only 150 carpentry hours are available per week, so 4x <= 150. What is the largest whole number of chairs, x, that can be made in a week?","options":["38 chairs","600 chairs","37 chairs","37.5 chairs"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"From 4x <= 150, x <= 37.5; since chairs must be whole and the limit cannot be exceeded, the maximum is 37. Option A rounds up and would need 152 hours, more than available, option D is not a whole number of chairs, and option B multiplies instead of dividing."}},{"itemId":"92f66b78-7ef4-558d-a9b4-cbe059d28360","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c29f5d00-5cef-58cd-b8b7-8314d45b1980","sourceKey":"bank:BUA204:MAT-061","parentItemId":null,"revision":1,"payload":{"prompt":"A company's annual sales are N2,500,000 this year and are expected to grow at 8% per year compound. Using indices, what are the expected sales in 4 years' time, to the nearest naira?","options":["N3,673,320","N3,401,222","N3,300,000","N3,149,280"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Sales = 2,500,000 x (1.08)^4 = 2,500,000 x 1.36048896 = N3,401,222. Option C adds 8% of the first year's sales each year (simple growth), option D uses one year too few, and option A compounds for one year too many."}},{"itemId":"b7eaeeb4-8e0e-5778-98b6-c86c066c20a0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"10593cd1-b74b-5e6a-b022-26d681128a2b","sourceKey":"bank:BUA204:MAT-062","parentItemId":null,"revision":1,"payload":{"prompt":"Using logarithms, how many complete years are needed for an investment to at least DOUBLE at 10% per annum compounded annually? (Solve (1.1)^n = 2.)","options":["10 years","7 years","7.27 years","8 years"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Taking logs, n = log 2 / log 1.1 = 0.30103 / 0.04139 = 7.27, so the investment first doubles after 8 complete years. Option B rounds down, but after 7 years the factor is only 1.9487, option A is the simple-interest answer (10% x 10 = 100%), and option C is the exact solution of the equation, which is not a whole number of years."}},{"itemId":"cbe11186-260f-5bd4-b09c-16d593aa622e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c177193b-34a7-59a6-9c3e-7f0c3e7eee33","sourceKey":"bank:BUA204:MAT-063","parentItemId":null,"revision":1,"payload":{"prompt":"A company plans a circular water tank base with a radius of 14 m. Using Area = pi x r^2 with pi = 3.142, what is the area of the base?","options":["43.988 m^2","87.976 m^2","2,463.328 m^2","615.832 m^2"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Area = 3.142 x 14^2 = 3.142 x 196 = 615.832 m^2. Option B is the circumference (2 x pi x r), option A forgets to square the radius, and option C squares the diameter instead of the radius."}},{"itemId":"e0d8fba2-f7fd-54d4-affe-30bc51b9d286","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7015e32c-309b-5032-8a9e-0bbd49433892","sourceKey":"bank:BUA204:MAT-064","parentItemId":null,"revision":1,"payload":{"prompt":"A cold room is 30 m long, 18 m wide and 6 m high. What is its storage volume?","options":["540 m^3","1,656 m^3","3,240 m^3","54 m^3"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Volume = L x B x H = 30 x 18 x 6 = 3,240 m^3. Option A is only the floor area, option B is the total surface area of the room, and option D just adds the three dimensions."}},{"itemId":"56d8c409-6327-552f-8bc7-33c83a4fe4b5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a67820af-9494-5d00-8b01-b1ec04233dc6","sourceKey":"bank:BUA204:MAT-065","parentItemId":null,"revision":1,"payload":{"prompt":"A firm sells 4,000 units at N1,000 each, with a variable cost of N600 per unit and fixed costs of N900,000. If it raises its price by 10% and sales volume stays the same, what will its new profit be?","options":["N1,100,000","N700,000","N2,000,000","N770,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"New price = 1,000 x 1.1 = 1,100; new profit = 4,000 x (1,100 - 600) - 900,000 = 2,000,000 - 900,000 = N1,100,000. Option D simply adds 10% to the old profit of N700,000, option B is the old profit, and option C forgets the fixed cost."}},{"itemId":"a103c695-5397-51d1-a60e-551b448b8644","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dc915df1-75e6-57d8-81cc-afd7d41f415c","sourceKey":"bank:BUA204:MAT-066","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N1,000,000, a selling price of N500 and a variable cost of N300 per unit. If fixed costs rise by 20% with price and variable cost unchanged, what is the new break-even point?","options":["6,000 units","5,000 units","4,000 units","2,400 units"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"New FC = 1,000,000 x 1.2 = 1,200,000; new BEP = 1,200,000 / (500 - 300) = 6,000 units, up from 5,000, because more fixed cost must be covered by the same contribution. Option B is the old break-even point, option C wrongly reduces it, and option D divides by price instead of contribution."}},{"itemId":"fd613587-b6ca-58d0-8291-4bb5bcadaf65","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2fe951d9-92de-5bb4-9268-40afeb9dd43e","sourceKey":"bank:BUA204:MAT-067","parentItemId":null,"revision":1,"payload":{"prompt":"A trader wants a total profit of N750,000 and makes a profit of N2,500 on each unit she sells. How many units must she sell?","options":["299 units","300 units","30 units","1,875 units"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Units required = target profit / profit per unit = 750,000 / 2,500 = 300 units. Option D multiplies instead of dividing, option A wrongly subtracts one unit's profit first, and option C is a place-value slip."}},{"itemId":"46cbdfa2-2aea-5dd4-accd-6ee735abab79","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"21c11809-66a5-5926-b8c0-5b9755e8dfb7","sourceKey":"bank:BUA204:MAT-068","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery pays N250,000 a month in rent and salaries regardless of output, and spends N180 on ingredients and packaging for each loaf. Which function gives its total monthly cost (TC) for Q loaves?","options":["TC = 250,000Q - 180","TC = 180 + 250,000Q","TC = 250,000 + 180Q","TC = (250,000 + 180)Q"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Total cost = fixed cost + (variable cost per unit x quantity), so TC = 250,000 + 180Q. Option B swaps the fixed and variable parts, option A makes fixed cost depend on output and subtracts the variable cost, and option D wrongly multiplies the fixed cost by output too."}},{"itemId":"80881d75-13dc-5d8e-8461-7c9532bc1ab1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f27888d3-f1bb-58c2-b436-65df5a51c35c","sourceKey":"bank:BUA204:MAT-069","parentItemId":null,"revision":1,"payload":{"prompt":"A firm expects to sell 5,000 units. Its fixed costs are N1,100,000 and its variable cost is N700 per unit. What selling price per unit will give it a profit of exactly N400,000?","options":["N780","N920","N300","N1,000"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Profit = Q(P - v) - FC, so 400,000 = 5,000(P - 700) - 1,100,000; P = 700 + (1,100,000 + 400,000) / 5,000 = 700 + 300 = N1,000. Option B is only the break-even price, option A ignores fixed cost, and option C forgets to add the variable cost per unit."}},{"itemId":"4b4573cd-9733-5f49-ab8f-76928d21da6b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a5b2f5a8-5b34-5672-bac0-ebdb21ca7125","sourceKey":"bank:BUA204:MAT-070","parentItemId":null,"revision":1,"payload":{"prompt":"A factory's fixed costs are N3,600,000 per quarter and each unit sold contributes N1,440 towards fixed costs. How many units must it sell in the quarter to break even?","options":["2,500 units","400 units","1,250 units","5,000 units"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"BEQ = FC / contribution per unit = 3,600,000 / 1,440 = 2,500 units. Option D doubles the answer, option B inverts the division, and option C halves the answer; none of these makes total contribution equal fixed cost."}},{"itemId":"20360254-457b-5fea-b318-5abe62138b5c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e268878a-e3cd-59bb-8343-1703f8ea964f","sourceKey":"bank:BUA204:OPM-001","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos events company plans a product launch with these activities: A (no predecessor, 5 days), B (no predecessor, 3 days), C (after A, 4 days), D (after B, 7 days), E (after C and D, 2 days). What is the minimum project duration?","options":["11 days","7 days","21 days","12 days"],"correctOption":3,"section":"Operational Modelling","explanation":"The paths are A-C-E = 5 + 4 + 2 = 11 days and B-D-E = 3 + 7 + 2 = 12 days; the critical path is the longest path, so the project needs 12 days. Option A is the shorter path, option C adds every activity duration as if all were done one after another, and option B is just the longest single activity."}},{"itemId":"d9a5b603-79a4-5514-b5c2-f8ed8b4ac7b7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1bb3093f-4c77-545c-83f1-7b0b767acb90","sourceKey":"bank:BUA204:OPM-002","parentItemId":null,"revision":1,"payload":{"prompt":"For the same launch project, A (no predecessor, 5 days), B (no predecessor, 3 days), C (after A, 4 days), D (after B, 7 days), E (after C and D, 2 days), which is the critical path?","options":["A - C - E","A - C - D - E","A - B - E","B - D - E"],"correctOption":3,"section":"Operational Modelling","explanation":"B-D-E takes 12 days against 11 days for A-C-E, and the critical path is the longest path through the network, the one that sets the project duration. Option A is the shorter path, which has 1 day of float, and options C and B are not valid paths because they ignore the stated predecessors."}},{"itemId":"60f07b1d-825f-5370-b52f-1be6ecc8baac","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"80c4776c-5dc1-5296-b4f7-5c360b602d21","sourceKey":"bank:BUA204:OPM-003","parentItemId":null,"revision":1,"payload":{"prompt":"For a launch project with activities A (no predecessor, 5 days), B (no predecessor, 3 days), C (after A, 4 days), D (after B, 7 days), E (after C and D, 2 days), what is the total float of activity A?","options":["11 days","1 day","0 days","5 days"],"correctOption":1,"section":"Operational Modelling","explanation":"A's earliest finish is 5; working backwards from the 12-day finish, E must start by day 10, so C must finish by day 10 and start by day 6, giving A a latest finish of 6. Total float = LFT - EFT = 6 - 5 = 1 day. Option C would apply only to an activity on the critical path, option D is A's duration, and option A is the length of A's path, not its slack."}},{"itemId":"c12ef025-399b-5fb1-b905-a16f201fb908","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e1c86eb7-c00e-55de-87a3-8aece7469acd","sourceKey":"bank:BUA204:OPM-004","parentItemId":null,"revision":1,"payload":{"prompt":"In a launch project with activities A (no predecessor, 5 days), B (no predecessor, 3 days), C (after A, 4 days), D (after B, 7 days), E (after C and D, 2 days), activity C is delayed by 3 days (it now takes 7 days). What is the new project duration?","options":["14 days","15 days","13 days","12 days"],"correctOption":0,"section":"Operational Modelling","explanation":"C had only 1 day of float, so a 3-day delay pushes path A-C-E to 5 + 7 + 2 = 14 days, which now exceeds B-D-E (12 days) and becomes critical. Option B adds the full 3 days to the original 12-day duration, ignoring C's float, option D assumes the delay is fully absorbed, and option C wrongly assumes C had 2 days of float."}},{"itemId":"c32bed93-40f3-571e-bd6e-bda0ac541a0e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9cde6fb4-b68a-51b9-8f78-e6b5cf22e5f7","sourceKey":"bank:BUA204:OPM-005","parentItemId":null,"revision":1,"payload":{"prompt":"A factory upgrade in Ota has these activities (durations in weeks): A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete. What is the earliest start time of activity F?","options":["Week 9","Week 23","Week 11","Week 12"],"correctOption":3,"section":"Operational Modelling","explanation":"F cannot start until both D and E are finished, so its EST is the LATEST of their earliest finish times: D finishes at 3 + 4 + 5 = 12 and E at 3 + 6 + 2 = 11, giving EST = 12. Option C takes the earlier of the two finishes, option A is C's earliest finish, and option B adds the two predecessors' finish times together."}},{"itemId":"93affdd0-e93f-5c32-926b-d77a74122875","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"79bd7a42-3518-58d6-836c-5963d7dab902","sourceKey":"bank:BUA204:OPM-006","parentItemId":null,"revision":1,"payload":{"prompt":"For the same factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, what is the project duration?","options":["15 weeks","13 weeks","14 weeks","27 weeks"],"correctOption":0,"section":"Operational Modelling","explanation":"The paths are A-B-D-F = 3 + 4 + 5 + 3 = 15, A-C-E-F = 3 + 6 + 2 + 3 = 14 and A-C-G = 3 + 6 + 4 = 13 weeks, so the longest (critical) path gives 15 weeks. Options C and B are the non-critical paths, and option D is the sum of all activity durations."}},{"itemId":"d7c45667-8a5f-5463-bfee-750e3bbbc766","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"acd3ab5b-02c8-5a93-befb-2076bea84612","sourceKey":"bank:BUA204:OPM-007","parentItemId":null,"revision":1,"payload":{"prompt":"For the same factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, which path is critical?","options":["A - C - G","A - B - D - F","A - C - E - F","A - B - D - G"],"correctOption":1,"section":"Operational Modelling","explanation":"A-B-D-F takes 15 weeks, longer than A-C-E-F (14) and A-C-G (13), so it is the critical path with zero float on each of its activities. Options C and A have 1 and 2 weeks of float, and option D is not a valid path because G follows C, not D."}},{"itemId":"81378e88-4fff-5502-b489-353bc228e6d4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"16f45c20-6321-54c4-9553-0ff3a571fb5f","sourceKey":"bank:BUA204:OPM-008","parentItemId":null,"revision":1,"payload":{"prompt":"For the same factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, what is the total float of activity G?","options":["0 weeks","2 weeks","4 weeks","1 week"],"correctOption":1,"section":"Operational Modelling","explanation":"G's earliest finish is 3 + 6 + 4 = 13, and since it is an end activity its latest finish is the project duration, 15, so float = LFT - EFT = 15 - 13 = 2 weeks. Option A treats G as critical, option C is G's duration, and option D is the float of activity C, not G."}},{"itemId":"368a517d-d89a-5fea-a5de-1e96719e4b98","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c5f5ba29-9611-53d6-9e1e-385262903032","sourceKey":"bank:BUA204:OPM-009","parentItemId":null,"revision":1,"payload":{"prompt":"For the same factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, what is the latest finish time of activity C?","options":["Week 15","Week 10","Week 11","Week 9"],"correctOption":1,"section":"Operational Modelling","explanation":"LFT is the EARLIEST of the latest start times of the activities that follow: E must start by 12 - 2 = 10 (since F starts by 12) and G by 15 - 4 = 11, so C must finish by week 10. Option C uses G's latest start instead of the earliest, option D is C's earliest finish, and option A is the project end."}},{"itemId":"65bafe5b-abba-5360-87c5-115a25395676","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2ae8381f-06ec-5220-b976-6d3d39ed0591","sourceKey":"bank:BUA204:OPM-010","parentItemId":null,"revision":1,"payload":{"prompt":"For the same factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, the latest finish of C is week 10. What is the total float of C?","options":["1 week","0 weeks","4 weeks","2 weeks"],"correctOption":0,"section":"Operational Modelling","explanation":"C's earliest finish is 3 + 6 = 9, so total float = LFT - EFT = 10 - 9 = 1 week. Option B wrongly treats C as critical, option C subtracts C's duration from its latest finish (giving its latest start) instead, and option D is the float of G."}},{"itemId":"fcf81e92-c9ec-54e6-b957-8761f5083312","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"625850ba-ad68-5a76-b1bc-93b781e97686","sourceKey":"bank:BUA204:OPM-011","parentItemId":null,"revision":1,"payload":{"prompt":"Activity S in a shop-fitting project can start only when P (2 days), Q (4 days) and R (3 days) are all finished; P, Q and R all start at day 0. S takes 5 days. What are the earliest start and earliest finish times of S?","options":["EST = day 3, EFT = day 8","EST = day 4, EFT = day 9","EST = day 2, EFT = day 7","EST = day 9, EFT = day 14"],"correctOption":1,"section":"Operational Modelling","explanation":"EST is the latest of the predecessors' earliest finish times, max(2, 4, 3) = 4, and EFT = EST + duration = 4 + 5 = 9. Option C uses the earliest predecessor finish, option D adds all three predecessor durations as if they were done in sequence, and option A uses the average of the predecessor durations."}},{"itemId":"a2297985-9ad1-506d-899b-fa44c137c62a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6d5b5cd2-3757-5bfa-882b-7db98a779c87","sourceKey":"bank:BUA204:OPM-012","parentItemId":null,"revision":1,"payload":{"prompt":"A software rollout has activities A (no predecessor, 6 days), B (no predecessor, 4 days), C (after A, 3 days), D (after B, 5 days) and E (after C and D, 2 days). Which statement is correct?","options":["B-D-E is the only critical path, taking 11 days","A-C-E is the only critical path, taking 11 days","The project takes 20 days","There are two critical paths, A-C-E and B-D-E, each taking 11 days"],"correctOption":3,"section":"Operational Modelling","explanation":"A-C-E = 6 + 3 + 2 = 11 days and B-D-E = 4 + 5 + 2 = 11 days, so both are longest paths and both are critical, with zero float on every activity; a delay on either path delays the project. Options B and A miss the second critical path, and option C adds every duration together."}},{"itemId":"6f6c58e4-4e09-58b9-82fd-f38b7a70e30d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5bcb9453-99f2-5907-8c8b-a605fc51741d","sourceKey":"bank:BUA204:OPM-013","parentItemId":null,"revision":1,"payload":{"prompt":"In PERT, the expected time of an activity is te = (a + 4m + b) / 6. For installing a generator, the optimistic time a = 4 days, most likely m = 6 days and pessimistic b = 14 days. What is te?","options":["6 days","8 days","7 days","10.5 days"],"correctOption":2,"section":"Operational Modelling","explanation":"te = (4 + 4 x 6 + 14) / 6 = 42 / 6 = 7 days. Option B takes a simple average of the three estimates, option A uses only the most likely time, and option D divides by 4 instead of 6."}},{"itemId":"fd9b52ee-c302-5c18-b3b4-d6a8dcc6bab8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5cdfa265-5824-56c5-b4e7-cccc895b1b8f","sourceKey":"bank:BUA204:OPM-014","parentItemId":null,"revision":1,"payload":{"prompt":"A pharmacy in Ikeja sells 4,800 packs of a drug a year. Each order costs N1,500 to place and holding one pack for a year costs N40. What is the Economic Order Quantity?","options":["3,795 packs","600 packs","360,000 packs","8 packs"],"correctOption":1,"section":"Operational Modelling","explanation":"EOQ = sqrt(2DS / H) = sqrt(2 x 4,800 x 1,500 / 40) = sqrt(360,000) = 600 packs. Option C forgets the square root, option D inverts the fraction inside the root, and option A leaves out the holding cost H."}},{"itemId":"7f150e35-0a4c-5312-ba7a-7293c2cef8ec","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2286768f-5a2d-5424-946a-1bc3357148c8","sourceKey":"bank:BUA204:OPM-015","parentItemId":null,"revision":1,"payload":{"prompt":"For a pharmacy (annual demand 4,800 packs, EOQ 600 packs), how many orders will be placed each year?","options":["4 orders","300 orders","16 orders","8 orders"],"correctOption":3,"section":"Operational Modelling","explanation":"Number of orders = D / Q* = 4,800 / 600 = 8. Option A divides by twice the EOQ, option C divides by half the EOQ (the average stock), and option B is the average inventory Q*/2, not a number of orders."}},{"itemId":"f1aad30b-d744-59ed-95e1-526357cab6fd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"48f1129a-7f28-528b-ad0a-a2adbb45fdae","sourceKey":"bank:BUA204:OPM-016","parentItemId":null,"revision":1,"payload":{"prompt":"For the same pharmacy (D = 4,800 packs, S = N1,500, H = N40, EOQ = 600 packs), what is the total annual inventory cost at the EOQ?","options":["N24,000","N12,000","N36,000","N48,000"],"correctOption":0,"section":"Operational Modelling","explanation":"Total cost = (D / Q)S + (Q / 2)H = 8(1,500) + 300(40) = 12,000 + 12,000 = N24,000; as expected the two parts are equal at the EOQ. Option B counts only one of the two costs, option C uses the full Q (not Q/2) for the holding cost, and option D doubles the correct total by counting each cost twice."}},{"itemId":"886ddb8f-3d73-5f7c-bc31-2000dec15d9a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c841f7e-f68a-59b3-9296-ae941fe5e943","sourceKey":"bank:BUA204:OPM-017","parentItemId":null,"revision":1,"payload":{"prompt":"A pharmacy works 300 days a year, sells 4,800 packs evenly through the year, and its supplier takes 5 days to deliver. What is the reorder point?","options":["600 packs","40 packs","80 packs","16 packs"],"correctOption":2,"section":"Operational Modelling","explanation":"Daily demand = 4,800 / 300 = 16 packs, so ROP = daily demand x lead time = 16 x 5 = 80 packs; a new order is placed when stock falls to 80. Option D is only one day's demand, option B multiplies the number of orders per year (8) by the lead time, and option A is the EOQ, which is how much to order, not when."}},{"itemId":"ea7b890e-94ec-5a2d-ab76-eb0c190764c4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c08fe9a5-46cf-5704-81a6-1bf8c8a43a67","sourceKey":"bank:BUA204:OPM-018","parentItemId":null,"revision":1,"payload":{"prompt":"A cement depot's EOQ is 1,000 bags (annual demand 12,500 bags, ordering cost N2,000 per order, holding cost N50 per bag per year). Under the EOQ model, what is the average inventory held?","options":["1,000 bags","500 bags","12.5 bags","6,250 bags"],"correctOption":1,"section":"Operational Modelling","explanation":"Stock falls steadily from Q to zero between deliveries, so average inventory = Q / 2 = 1,000 / 2 = 500 bags. Option A is the full order quantity, option C is the number of orders per year (12,500 / 1,000), and option D is half of annual demand."}},{"itemId":"30d24278-918a-51d4-bc98-90e2680357af","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"281469e7-5c53-562a-bae0-7c79ba178ae1","sourceKey":"bank:BUA204:OPM-019","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket sells 9,000 tins of milk a year at a purchase cost of N800 per tin. Ordering costs N1,600 per order, and annual holding cost is 25% of the purchase cost. What is the EOQ (to the nearest tin)?","options":["190 tins","379 tins","144,000 tins","1,073 tins"],"correctOption":1,"section":"Operational Modelling","explanation":"First find H = 25% x N800 = N200 per tin per year; then EOQ = sqrt(2 x 9,000 x 1,600 / 200) = sqrt(144,000) = 379 tins. Option D uses 25 instead of N200 as H, option A uses the full purchase price as H, and option C forgets the square root."}},{"itemId":"fbf84326-939a-563e-b4c5-7729349159c5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0ba51276-7431-5bb5-aa94-be13d9780ef9","sourceKey":"bank:BUA204:OPM-020","parentItemId":null,"revision":1,"payload":{"prompt":"A pharmacy with D = 4,800 packs, S = N1,500 and H = N40 decides to order 400 packs at a time instead of its EOQ of 600. What will its total annual inventory cost be?","options":["N26,000","N18,000","N34,000","N24,000"],"correctOption":0,"section":"Operational Modelling","explanation":"Total cost = (D / Q)S + (Q / 2)H = (4,800 / 400)(1,500) + (400 / 2)(40) = 18,000 + 8,000 = N26,000, which is N2,000 more than at the EOQ. Option D is the cost at the EOQ, option B is the ordering cost alone, and option C uses the full Q of 400 rather than Q/2 in the holding cost."}},{"itemId":"ee5796e6-dae8-5d2f-9800-b60d17cb5dc2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0762e7a5-cff8-5224-bbde-44a9c34d22be","sourceKey":"bank:BUA204:OPM-021","parentItemId":null,"revision":1,"payload":{"prompt":"If the same pharmacy (D = 4,800 packs, S = N1,500, H = N40) orders 800 packs at a time, what are its annual ordering cost and annual holding cost?","options":["Ordering N12,000; holding N12,000","Ordering N9,000; holding N32,000","Ordering N9,000; holding N16,000","Ordering N16,000; holding N9,000"],"correctOption":2,"section":"Operational Modelling","explanation":"Ordering cost = (D / Q)S = (4,800 / 800)(1,500) = 6 x 1,500 = N9,000 and holding cost = (Q / 2)H = 400 x 40 = N16,000; with Q above the EOQ, holding cost now exceeds ordering cost. Option D swaps the two, option B uses Q instead of Q/2 for holding, and option A gives the equal costs that apply only at the EOQ of 600."}},{"itemId":"b522093a-81ed-5610-b298-e44083167f6d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3f1ab78f-4c72-5928-a7bb-1d8ae06090e4","sourceKey":"bank:BUA204:OPM-022","parentItemId":null,"revision":1,"payload":{"prompt":"A distributor places 8 orders a year and operates 300 days a year. Assuming orders are evenly spaced, how many working days pass between orders?","options":["8 days","37.5 days","2,400 days","45.6 days"],"correctOption":1,"section":"Operational Modelling","explanation":"If 8 orders are spread over 300 working days, the time between orders is 300 / 8 = 37.5 days. Option A confuses the number of orders with the interval, option C multiplies instead of dividing, and option D divides 365 calendar days by 8, which ignores the stated 300 working days."}},{"itemId":"c4b49f9e-d929-5cfa-9f7d-00efbac70604","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2bc671bb-13d8-53b3-a532-2767f6deb5db","sourceKey":"bank:BUA204:OPM-023","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's EOQ is 600 units. If annual demand quadruples while ordering and holding costs stay the same, what is the new EOQ?","options":["600 units","2,400 units","849 units","1,200 units"],"correctOption":3,"section":"Operational Modelling","explanation":"Because EOQ = sqrt(2DS / H), multiplying D by 4 multiplies the EOQ by sqrt(4) = 2, so the new EOQ is 1,200 units. Option B wrongly increases the EOQ in proportion to demand, option A assumes no change, and option C multiplies by sqrt(2), as if demand had only doubled."}},{"itemId":"076861f3-65c2-5175-9925-ee30f40dbbbd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e93acaf8-fd74-5d6b-9193-5a5eff11578e","sourceKey":"bank:BUA204:OPM-024","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's EOQ is 600 units. If the cost of placing each order doubles while demand and holding cost are unchanged, what is the new EOQ (to the nearest unit)?","options":["849 units","300 units","1,200 units","424 units"],"correctOption":0,"section":"Operational Modelling","explanation":"S sits under the square root, so doubling S multiplies the EOQ by sqrt(2) = 1.4142: 600 x 1.4142 = 849 units. Option C doubles the EOQ directly, option B halves it, and option D divides by sqrt(2), which is what would happen if the HOLDING cost doubled instead."}},{"itemId":"fa3518bf-c1a6-5293-a630-7c4141c79cf7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4fc292f4-cb54-543d-9a7a-e1bfc3e23ccb","sourceKey":"bank:BUA204:OPM-025","parentItemId":null,"revision":1,"payload":{"prompt":"At its EOQ, a firm's annual holding cost is N9,500. What is its total annual inventory cost (ordering plus holding) at the EOQ?","options":["N19,000","N28,500","N9,500","N4,750"],"correctOption":0,"section":"Operational Modelling","explanation":"At the EOQ, total ordering cost always equals total holding cost, so ordering cost is also N9,500 and the total is 9,500 + 9,500 = N19,000. Option C counts only the holding cost, option D halves it, and option B counts one of the costs twice."}},{"itemId":"514a4e04-bb9b-51ae-b522-9f977d3429b4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ce6d6630-6959-58e6-b97a-651460f0b5d9","sourceKey":"bank:BUA204:OPM-026","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano feed mill uses 150 bags of maize a week, and the supplier's lead time is 3 weeks. Assuming constant usage, at what stock level should the mill reorder?","options":["150 bags","50 bags","450 bags","153 bags"],"correctOption":2,"section":"Operational Modelling","explanation":"Reorder point = demand per period x lead time in the same period units = 150 x 3 = 450 bags, enough to cover usage while the order is in transit. Option A covers only one week, option B divides instead of multiplying, and option D adds the lead time to the weekly demand."}},{"itemId":"1d68d4f5-c52a-566b-85c6-8d1efcb3b565","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0668db1d-9997-5f68-b77c-b8badfb4f98d","sourceKey":"bank:BUA204:OPM-027","parentItemId":null,"revision":1,"payload":{"prompt":"A tailor makes shirts (x) and trousers (y). Each shirt needs 2 hours of cutting and each pair of trousers 3 hours; 120 cutting hours are available per week. Which constraint correctly represents cutting time?","options":["3x + 2y <= 120","x + y <= 120","2x + 3y <= 120","2x + 3y >= 120"],"correctOption":2,"section":"Operational Modelling","explanation":"Total cutting time used is 2 hours per shirt times x plus 3 hours per pair times y, and it cannot exceed the 120 hours available, giving 2x + 3y <= 120. Option A attaches the coefficients to the wrong products, option D reverses the inequality (it would force at least 120 hours), and option B ignores the time each item takes."}},{"itemId":"c11b8771-2a90-5870-b853-29e6bf622201","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c31a2b5e-a927-5456-b174-be2f044b3328","sourceKey":"bank:BUA204:OPM-028","parentItemId":null,"revision":1,"payload":{"prompt":"In a tailoring problem, profit is N800 per shirt (x) and N1,200 per pair of trousers (y). Which objective function should be used?","options":["Maximise Z = 800x + 1,200y","Maximise Z = 1,200x + 800y","Minimise Z = 800x + 1,200y","Maximise Z = 2,000(x + y)"],"correctOption":0,"section":"Operational Modelling","explanation":"The objective is to maximise total profit, which is the profit per unit times the number of units of each product: Z = 800x + 1,200y. Option C would minimise profit, option B swaps the unit profits, and option D wrongly applies the combined profit to every unit of both products."}},{"itemId":"f9d38a9a-f9bb-5e72-bd05-7718ef6bc0a2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3b9de72e-717f-5afe-b1ca-ad6661eb4c45","sourceKey":"bank:BUA204:OPM-029","parentItemId":null,"revision":1,"payload":{"prompt":"When graphing the constraint 4x + 5y <= 200, where does the boundary line cut the axes?","options":["(800, 0) and (0, 1,000)","(40, 0) and (0, 50)","(50, 0) and (0, 40)","(200, 0) and (0, 200)"],"correctOption":2,"section":"Operational Modelling","explanation":"Setting y = 0 gives 4x = 200, so x = 50; setting x = 0 gives 5y = 200, so y = 40. Option B swaps the divisions, option D ignores the coefficients, and option A multiplies instead of dividing."}},{"itemId":"c0caea3f-8f38-540e-b2d7-9b94cea63d76","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"79c4fc44-71c9-5e3b-a861-bf90b2dffc29","sourceKey":"bank:BUA204:OPM-030","parentItemId":null,"revision":1,"payload":{"prompt":"At which point do the constraint lines 2x + y = 40 and x + 3y = 45 intersect?","options":["x = 18, y = 4","x = 10, y = 15","x = 15, y = 10","x = 20, y = 15"],"correctOption":2,"section":"Operational Modelling","explanation":"From the first equation y = 40 - 2x; substituting gives x + 3(40 - 2x) = 45, so -5x = -75, x = 15 and y = 40 - 30 = 10. Check: 2(15) + 10 = 40 and 15 + 3(10) = 45. Option B swaps x and y, while options D and A fail at least one of the two equations."}},{"itemId":"8b80f6d3-156c-5354-86b4-c10df5b48534","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d0f73e5c-64c9-5424-ac8b-4385a425b539","sourceKey":"bank:BUA204:OPM-031","parentItemId":null,"revision":1,"payload":{"prompt":"Maximise Z = 30x + 40y subject to 2x + y <= 40, x + 3y <= 45, x >= 0, y >= 0. The corner points of the feasible region are (0, 0), (20, 0), (15, 10) and (0, 15). What is the maximum value of Z?","options":["1,600 at (0, 40)","850 at (15, 10)","600 at (0, 15)","600 at (20, 0)"],"correctOption":1,"section":"Operational Modelling","explanation":"Evaluating Z at each corner: (0,0) gives 0, (20,0) gives 600, (15,10) gives 450 + 400 = 850 and (0,15) gives 600, so the maximum is 850 at (15, 10). Options D and C are other corners with lower values, and option A uses (0, 40), which violates x + 3y <= 45 and so lies outside the feasible region."}},{"itemId":"2a764c18-aa1f-5a22-bd20-0706ff90b7be","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7c2f67c0-c409-5c19-bea0-dddc69ab9379","sourceKey":"bank:BUA204:OPM-032","parentItemId":null,"revision":1,"payload":{"prompt":"With the same constraints (2x + y <= 40, x + 3y <= 45, x, y >= 0; corners (0, 0), (20, 0), (15, 10), (0, 15)), the objective changes to Maximise Z = 50x + 20y. What is the optimal solution?","options":["x = 15, y = 10, Z = 950","x = 0, y = 15, Z = 300","x = 20, y = 0, Z = 1,000","x = 20, y = 15, Z = 1,300"],"correctOption":2,"section":"Operational Modelling","explanation":"Z at the corners is 0, 1,000, 950 and 300, so the best corner is (20, 0) with Z = 1,000; the optimum is not always at the intersection of the two constraints. Option A assumes the intersection is always optimal, option B is the weakest non-zero corner, and option D is not feasible because 2(20) + 15 = 55 exceeds 40."}},{"itemId":"2a797a36-0428-509c-8e01-ac8bfc74b1e0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e0e9b3c8-1b9b-580d-9f2b-30d9229e4f81","sourceKey":"bank:BUA204:OPM-033","parentItemId":null,"revision":1,"payload":{"prompt":"For the constraints 2x + y <= 40 and x + 3y <= 45 with x, y >= 0, which of these points is NOT a corner point of the feasible region?","options":["(0, 15)","(15, 10)","(20, 0)","(0, 40)"],"correctOption":3,"section":"Operational Modelling","explanation":"(0, 40) is where 2x + y = 40 meets the y-axis, but there x + 3y = 120, far above 45, so it lies outside the feasible region. The other points are genuine corners: (20, 0) is option C on the x-axis, (15, 10) is option B where the two constraints meet, and (0, 15) is option A where x + 3y = 45 meets the y-axis."}},{"itemId":"fccf0c0f-3c3d-5c1c-839b-2728721a1060","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4f195830-d442-537a-9066-fcf14a9b82b7","sourceKey":"bank:BUA204:OPM-034","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's constraints are 2x + y <= 40 (machine hours) and x + 3y <= 45 (labour hours), with x, y >= 0. Which production plan is feasible?","options":["x = 5, y = 14","x = 12, y = 12","x = 18, y = 6","x = 10, y = 11"],"correctOption":3,"section":"Operational Modelling","explanation":"Check each constraint: for (10, 11), 2(10) + 11 = 31 <= 40 and 10 + 33 = 43 <= 45, so both hold. Option B needs 12 + 36 = 48 labour hours, option C needs 36 + 6 = 42 machine hours, and option A needs 5 + 42 = 47 labour hours, so each breaks a constraint."}},{"itemId":"e8c52a54-dba9-5e06-ba34-b275bcdd508e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b19bf8c0-a366-515f-b70a-38134bd41e34","sourceKey":"bank:BUA204:OPM-035","parentItemId":null,"revision":1,"payload":{"prompt":"In the same problem (2x + y <= 40 machine hours, x + 3y <= 45 labour hours), the optimal plan is x = 20, y = 0. How many labour hours are left unused at this plan?","options":["45 hours","20 hours","25 hours","0 hours"],"correctOption":2,"section":"Operational Modelling","explanation":"Labour used = 20 + 3(0) = 20 hours, so 45 - 20 = 25 labour hours remain idle, while machine hours (2 x 20 = 40) are fully used. Option D confuses labour with the fully used machine constraint, option B is the hours actually used, and option A is the total available."}},{"itemId":"ae979946-d886-59af-9d81-9a9401450c67","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cb5ac081-d276-550f-a9c8-f4b5e43b3dd1","sourceKey":"bank:BUA204:OPM-036","parentItemId":null,"revision":1,"payload":{"prompt":"A poultry farm mixes two feeds, X and Y. Minimise cost C = 40x + 60y subject to x + y >= 10 (energy), x + 3y >= 18 (protein), x, y >= 0. The corner points of the feasible region are (0, 10), (6, 4) and (18, 0). What is the minimum cost?","options":["N600 at (0, 10)","N720 at (18, 0)","N480 at (6, 4)","N0 at (0, 0)"],"correctOption":2,"section":"Operational Modelling","explanation":"Evaluating C at each corner gives (0,10): 600, (6,4): 240 + 240 = 480 and (18,0): 720, so the cheapest mix is 6 units of X and 4 of Y at N480. Options A and B are corners with higher cost, and option D uses the origin, which breaks both >= constraints and is not feasible."}},{"itemId":"bacb80ba-87bc-57de-9b39-d3a854479d7e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a1b58e66-7112-51c4-9a17-273e81d682da","sourceKey":"bank:BUA204:OPM-037","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery makes bread (x) and cakes (y). Mixing: x + 2y <= 40 hours; Baking: 3x + 2y <= 60 hours; x, y >= 0. Profit is N400 per batch of bread and N500 per batch of cakes. Using the corner-point method, what is the maximum profit?","options":["N10,000","N11,500","N8,000","N14,500"],"correctOption":1,"section":"Operational Modelling","explanation":"Corners are (0,0), (20,0), (0,20) and the intersection: subtracting x + 2y = 40 from 3x + 2y = 60 gives 2x = 20, x = 10, y = 15. Profit is 0, 8,000, 10,000 and 4,000 + 7,500 = 11,500, so the maximum is N11,500 at (10, 15). Option A is the (0, 20) corner, option C is the (20, 0) corner, and option D uses (10, 21), which is infeasible."}},{"itemId":"12cc510f-13fa-50f9-95c0-321e5676c2bb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cd8055ab-5773-5db4-aaa0-6f7951105d4e","sourceKey":"bank:BUA204:OPM-038","parentItemId":null,"revision":1,"payload":{"prompt":"In the same bakery problem (x + 2y <= 40, 3x + 2y <= 60, corners (0, 0), (20, 0), (0, 20), (10, 15)), the profit on bread rises to N1,200 per batch while cake stays at N500. What is the new optimal plan?","options":["20 batches of bread and no cakes, profit N24,000","No bread and 20 cakes, profit N10,000","10 bread and 15 cakes, profit N19,500","20 bread and 15 cakes, profit N31,500"],"correctOption":0,"section":"Operational Modelling","explanation":"With Z = 1,200x + 500y the corners give 0, 24,000, 10,000 and 12,000 + 7,500 = 19,500, so the optimum moves to (20, 0) with N24,000. Option C keeps the old optimum without re-checking every corner, option B is a weaker corner, and option D is infeasible because 3(20) + 2(15) = 90 exceeds 60."}},{"itemId":"31b1d5d4-a374-5b87-9a4a-f17bd703cfdd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d6772b26-7672-5b85-b1e2-b395dc4578f8","sourceKey":"bank:BUA204:OPM-039","parentItemId":null,"revision":1,"payload":{"prompt":"A nutritionist wants a mix of two foods. Each unit of food x supplies 3 g of protein and each unit of food y supplies 5 g, and the mix must supply AT LEAST 60 g of protein. Which constraint is correct?","options":["3x + 5y <= 60","3x + 5y >= 60","5x + 3y >= 60","x + y >= 60"],"correctOption":1,"section":"Operational Modelling","explanation":"Protein supplied is 3x + 5y grams and the requirement is a minimum, so the inequality is >=: 3x + 5y >= 60. Option A turns the minimum into a maximum, option C attaches the protein contents to the wrong foods, and option D ignores how much protein each unit contains."}},{"itemId":"f6f2953d-84e6-5859-8eee-de285e24dab2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e1ebbb9c-2e5b-5b81-ba04-056a64651352","sourceKey":"bank:BUA204:OPM-040","parentItemId":null,"revision":1,"payload":{"prompt":"For the factory upgrade, A (no predecessor, 3 weeks), B (after A, 4), C (after A, 6), D (after B, 5), E (after C, 2), F (after D and E, 3), G (after C, 4); the project ends when F and G are both complete, activity C (6 weeks) has a latest finish time of week 10. What is its latest start time?","options":["Week 9","Week 3","Week 4","Week 16"],"correctOption":2,"section":"Operational Modelling","explanation":"Latest start = latest finish - duration = 10 - 6 = week 4, so C can start up to one week after its earliest start (week 3) without delaying the project. Option B is C's earliest start, option D adds the duration instead of subtracting it, and option A is C's earliest finish."}},{"itemId":"22b699af-a6cd-515d-bb6e-9a018f325988","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"73129caf-1c1c-59e0-b83c-468a97898f4b","sourceKey":"bank:BUA204:OPM-041","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos distributor sells 10,000 cartons a year and works 250 days a year. Delivery takes 4 working days. What is the reorder point?","options":["110 cartons","160 cartons","40 cartons","2,500 cartons"],"correctOption":1,"section":"Operational Modelling","explanation":"Daily demand = 10,000 / 250 = 40 cartons, so ROP = 40 x 4 = 160 cartons. Option C is just the daily demand, option A uses 365 days instead of the 250 working days (27.4 x 4), and option D divides annual demand by the lead time."}},{"itemId":"836bf4f1-d63f-547e-b887-3a8289aa0476","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a39d1db3-565f-5ccc-8f03-ea3059830763","sourceKey":"bank:BUA204:OPM-042","parentItemId":null,"revision":1,"payload":{"prompt":"Sharma (2007) describes a 'simplified representation or abstraction of reality'. This describes a:","options":["Constraint","Parameter","Model","Feasible region"],"correctOption":2,"section":"Operational Modelling","explanation":"A model is a simplified representation or abstraction of reality, built so that the effect of changes can be studied without experimenting on the real system. Option A is a resource limit inside a model, option B is a characteristic attribute bearing on system behaviour, and option D is the set of solutions satisfying all LP constraints."}},{"itemId":"6a83450e-26c3-5661-93fc-05d7fab9b2e7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cc5c7cde-a938-57fa-a6c6-b74bd26a8955","sourceKey":"bank:BUA204:OPM-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of Sharma's three top qualities of an effective model?","options":["Validity","Value","Usability","Complexity"],"correctOption":3,"section":"Operational Modelling","explanation":"Sharma (2007) lists validity, usability and value as the three top qualities of an effective model; a good model is a simplification, so complexity is not one of them. Validity (option A), usability (option C) and value (option B) are all on the list."}},{"itemId":"9790757b-3da7-5226-a8ce-b1b041fb1f9b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43cd49e8-07e5-5bf4-a12f-ff71e86187fc","sourceKey":"bank:BUA204:OPM-044","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank builds a model that describes how customer queues lengthen as more people arrive, but the model does not choose the best number of tellers. This is a:","options":["Descriptive model","Normative (optimisation) model","Iconic model","Analogue model"],"correctOption":0,"section":"Operational Modelling","explanation":"A descriptive model describes and predicts facts and relationships but has no objective function to select the best alternative. Option B would prescribe the optimal number of tellers, option C is a physical or pictorial likeness such as a blueprint, and option D uses one set of properties to represent another."}},{"itemId":"5dcce0a1-f774-54f2-ab23-63b242b3878a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"12d58c46-2975-5505-a1ab-d4d060e26a24","sourceKey":"bank:BUA204:OPM-045","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian refinery uses a linear programming model that selects the product mix giving the highest possible profit. This is best classified as a:","options":["Normative (optimisation) model","Descriptive model","Iconic model","Analogue model"],"correctOption":0,"section":"Operational Modelling","explanation":"Normative or optimisation models are prescriptive: they develop objective decision rules that yield an optimum solution, which is exactly what an LP product-mix model does. Option B only describes relationships without choosing the best option, and options C and D are physical or property-substitution representations rather than decision rules."}},{"itemId":"cef63507-75ec-51e3-bff2-7917e2f7cffb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1619ae72-88b8-57ab-9731-156e117e9381","sourceKey":"bank:BUA204:OPM-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of model is the MOST abstract, using symbols and equations to represent the system?","options":["Mathematical (symbolic) model","Analogue (diagrammatic) model","Descriptive model","Iconic (physical) model"],"correctOption":0,"section":"Operational Modelling","explanation":"Mathematical or symbolic models are the most abstract, representing a system entirely through symbols and equations such as Z = 5x + 4y. Option D looks like the real thing, option B substitutes one property for another, and option C is classified by purpose (describing rather than optimising), not by its degree of abstraction."}},{"itemId":"14d3121c-ff1f-52ef-a2fc-2fc1c45a5f59","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c243a0c5-5dfd-5044-8569-8f963511f2f7","sourceKey":"bank:BUA204:OPM-048","parentItemId":null,"revision":1,"payload":{"prompt":"In a mathematical model, 'constants' are:","options":["Components whose values are fixed for the purpose of the study","Ways in which the variables and parameters interlink","Symbols whose values can vary","The factors outside the decision maker's control"],"correctOption":0,"section":"Operational Modelling","explanation":"Constants are the components of a mathematical model that keep fixed values throughout the study. Option C describes variables, option B describes relationships, and option D describes exogenous variables."}},{"itemId":"f7e75c66-954b-5889-99b6-98e90a022af0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5a59435d-824b-59b0-b349-f2fddc17619f","sourceKey":"bank:BUA204:OPM-049","parentItemId":null,"revision":1,"payload":{"prompt":"In a mathematical model, the characteristic attributes that bear on the behaviour of the system are called:","options":["Decision variables","Constants","Parameters","Relationships"],"correctOption":2,"section":"Operational Modelling","explanation":"Parameters are the characteristic attributes bearing on system behaviour. Option B, constants, are components with fixed values, option D, relationships, are the ways variables and parameters interlink, and option A refers to the quantities the decision maker controls."}},{"itemId":"2ea9584b-a8f0-5483-8f4f-51a488c0e1c3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"86ed4422-14a5-5a62-8ceb-76e985e52535","sourceKey":"bank:BUA204:OPM-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five categories of decision-making variables in operations research models?","options":["Intermediate variables","Performance measures","Exogenous variables","Random error variables"],"correctOption":3,"section":"Operational Modelling","explanation":"The five categories are decision variables, exogenous variables, policies and constraints, performance measures, and intermediate variables; 'random error variables' is not among them. Exogenous variables (option C), performance measures (option B) and intermediate variables (option A) are all on the list."}},{"itemId":"f2542ce7-9899-5746-8a6f-8bd403618fdf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"38637ec5-c11e-56dd-81e9-455a3d0064ec","sourceKey":"bank:BUA204:OPM-051","parentItemId":null,"revision":1,"payload":{"prompt":"A factory manager in Ota chooses how many units of each product to make next month. In an operations research model, these quantities are:","options":["Constants","Performance measures","Exogenous variables","Decision variables"],"correctOption":3,"section":"Operational Modelling","explanation":"Decision variables are under the decision maker's control, and the manager chooses production quantities. Option C covers factors outside the manager's control such as competitor actions or the exchange rate, option A holds fixed values, and option B is what is used to judge the outcome, such as profit."}},{"itemId":"980f572c-4fc7-5bc6-9535-3efef2560d9b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"15faff65-e179-5be6-b0da-5abfe6ab46a0","sourceKey":"bank:BUA204:OPM-052","parentItemId":null,"revision":1,"payload":{"prompt":"An inventory model for a Lagos supermarket treats daily customer demand as a random variable with a known probability distribution. The model is:","options":["Deterministic","Analogue","Probabilistic","Iconic"],"correctOption":2,"section":"Operational Modelling","explanation":"A model in which at least one parameter or decision variable is a random variable is probabilistic (stochastic). Option A assumes every parameter is known with certainty, as in the basic EOQ model with constant demand, while options D and B classify models by form, not by certainty."}},{"itemId":"8c8ac631-7284-5ba9-8970-48c9035caefd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5ee6f306-ebf3-5706-bfbf-a31953c4b41d","sourceKey":"bank:BUA204:OPM-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly compares deterministic and probabilistic models?","options":["Both assume certainty but differ in the number of variables","Deterministic models include random variables, while probabilistic models assume certainty","Deterministic models assume all parameters are known with certainty, while probabilistic models include at least one random variable","Deterministic models are physical, while probabilistic models are symbolic"],"correctOption":2,"section":"Operational Modelling","explanation":"Deterministic models treat every parameter and functional relationship as known with certainty, whereas probabilistic models include randomness through at least one random variable. Option B reverses the two, option A ignores the role of uncertainty, and option D confuses certainty with model form (iconic versus mathematical)."}},{"itemId":"3e1a7725-10be-5947-89b8-88568333fd8e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43a562e9-f09a-530b-abf5-f082bc968e04","sourceKey":"bank:BUA204:OPM-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a component of a linear programming model?","options":["Probabilities attached to each state of nature","A set of linear constraints","A linear objective function","Non-negativity restrictions"],"correctOption":0,"section":"Operational Modelling","explanation":"An LP model has three components: a linear objective function, linear constraints and non-negativity restrictions. Probabilities of states of nature belong to decision-making under risk, not LP. Options C, B and D are the three genuine components."}},{"itemId":"fe3ca978-d901-5b3b-9490-9cafac8b6b7d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aa98bbd8-78c7-5e50-b28d-202af18eb322","sourceKey":"bank:BUA204:OPM-055","parentItemId":null,"revision":1,"payload":{"prompt":"In linear programming, decision variables are:","options":["The area that satisfies all the constraints","The limits on available resources","The value of the objective function at the optimum","The unknown quantities being solved for, such as the number of units of each product"],"correctOption":3,"section":"Operational Modelling","explanation":"Decision variables are the unknowns the LP solves for, for example x = units of Product A and y = units of Product B. Option B describes constraints, option A is the feasible region, and option C is the optimal value of Z."}},{"itemId":"a8581cf3-58bf-5d4c-b04d-bae956ed4adb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1beb5453-68fc-5ec5-b966-d52e5fa5b608","sourceKey":"bank:BUA204:OPM-056","parentItemId":null,"revision":1,"payload":{"prompt":"For a maximisation LP with only <= constraints and x, y >= 0, where on the graph does the feasible region lie?","options":["Above every constraint line","In any quadrant where the objective function is positive","Only on the constraint lines themselves","In the first quadrant, on or below every constraint line"],"correctOption":3,"section":"Operational Modelling","explanation":"Each <= constraint is satisfied on or below its line, and non-negativity confines the solution to the first quadrant, so the feasible region is the area bounded by the axes and all the constraint lines. Option A would break the <= constraints, option C ignores the interior points, and option B ignores non-negativity."}},{"itemId":"07bb4c26-2f80-5e5e-844c-49aff7e87c47","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"924f95c4-a23e-5676-98d5-1e2cf71223ff","sourceKey":"bank:BUA204:OPM-057","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing of operational model and the managerial problem it mainly addresses is correct?","options":["EOQ model - production scheduling","Linear programming - finding the critical path","Network analysis - inventory optimisation","Linear programming - resource allocation"],"correctOption":3,"section":"Operational Modelling","explanation":"Linear programming allocates scarce resources among competing activities, network analysis (CPM/PERT) is for production scheduling, and the EOQ model is for inventory optimisation. Options A and C swap the roles of the EOQ and network models, and option B gives LP the job of CPM."}},{"itemId":"92bf1b71-9f41-5637-b884-6f07a7bcec81","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"891a1f54-2f37-540b-b888-ec47460dffea","sourceKey":"bank:BUA204:OPM-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence describes the common logic shared by network analysis, the EOQ model and linear programming?","options":["Define an objective, identify the constraints, and find the best feasible course of action","State a null hypothesis, test it, and accept or reject it","Collect data, draw a chart, and report the trend","List the states of nature, assign probabilities, and compute the EMV"],"correctOption":0,"section":"Operational Modelling","explanation":"All three classical operational models follow the same logic: define an objective, identify constraints, and find the best feasible course of action. Option C describes data presentation, option B describes hypothesis testing, and option D describes decision-making under risk."}},{"itemId":"77f24e4e-31d7-5808-b954-65cf394eec22","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5ca696a4-0b4b-52c2-b6c6-0555913fe6fd","sourceKey":"bank:BUA204:OPM-059","parentItemId":null,"revision":1,"payload":{"prompt":"Under the EOQ model, what happens as the order quantity is increased?","options":["Both annual ordering and holding costs fall","Annual ordering cost rises while annual holding cost falls","Both costs rise in proportion","Annual ordering cost falls while annual holding cost rises"],"correctOption":3,"section":"Operational Modelling","explanation":"Larger orders mean fewer orders per year (D / Q falls), so ordering cost falls, but the average stock Q / 2 rises, so holding cost rises; the EOQ balances the two. Option A ignores the higher stock held, option B reverses the effects, and option C ignores that fewer orders are placed."}},{"itemId":"035246b4-7eaf-5dd7-9d54-b93d69a193d3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"26ac2d43-004e-5b58-89aa-e98e9bcae5fb","sourceKey":"bank:BUA204:OPM-060","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano retailer pays N2,500 in processing and delivery charges each time it places an order with its supplier. In the EOQ model this is:","options":["The holding cost per unit per year (H)","The reorder point","The ordering cost per order (S)","The annual demand (D)"],"correctOption":2,"section":"Operational Modelling","explanation":"Ordering cost is the fixed cost incurred each time an order is placed, such as processing and delivery charges, and is S in the EOQ formula. Option A covers storage, insurance, spoilage and money tied up in stock, option D is the yearly quantity required, and option B is the stock level that triggers a new order."}},{"itemId":"fed4d75d-7d55-55be-abe1-5b432da81982","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"deab0009-3a1d-54a9-845c-8834a8f86658","sourceKey":"bank:BUA204:OPM-062","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos importer finds that demand for its product swings sharply around festive seasons and that port delays make lead times unreliable. Which adaptation of the basic EOQ approach is most appropriate?","options":["Order exactly the EOQ and ignore the variation","Hold safety stock and use a more dynamic inventory model","Replace the EOQ with the critical path method","Set the reorder point to zero"],"correctOption":1,"section":"Operational Modelling","explanation":"When demand and lead time are not constant, the basic EOQ can cause stockouts or excess stock, so firms add safety stock, use periodic review, or adopt more dynamic models. Option A ignores the violated assumptions, option D guarantees stockouts during the lead time, and option C is a scheduling tool, not an inventory model."}},{"itemId":"290fd09f-c745-5247-87ea-dec2edfa8830","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ff6d3ff0-807d-5a4e-9793-06859fbaccc8","sourceKey":"bank:BUA204:OPM-063","parentItemId":null,"revision":1,"payload":{"prompt":"In network analysis, 'the latest of the earliest finish times of all preceding activities' defines the:","options":["Latest Finish Time (LFT)","Earliest Finish Time (EFT)","Total float","Earliest Start Time (EST)"],"correctOption":3,"section":"Operational Modelling","explanation":"An activity cannot begin until all its predecessors are complete, so its EST is the latest of their earliest finish times. Option A is the earliest of the latest start times of succeeding activities, option B is EST plus duration, and option C is LFT minus EFT."}},{"itemId":"f5d870bf-a713-557a-9a50-676049ea633c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4756b6c7-3738-5c8b-a99a-70f032d05ff7","sourceKey":"bank:BUA204:OPM-064","parentItemId":null,"revision":1,"payload":{"prompt":"During construction of a filling station, an activity on the critical path is delayed by 2 days, while every other activity runs to schedule. What happens to the project?","options":["Only the activities on non-critical paths are delayed","The whole project is delayed by 2 days","The project is unaffected because other activities have float","The project finishes 2 days earlier"],"correctOption":1,"section":"Operational Modelling","explanation":"Critical activities have zero float, so any delay on the critical path delays the whole project by the same amount. Option C confuses this with a delay on a non-critical activity that has float to absorb it, option A has the logic backwards, and option D has no basis."}},{"itemId":"f40a8b27-fe89-5295-b687-568be7c179d4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6ffd9fa8-7d81-5876-9075-9f771d43dc2a","sourceKey":"bank:BUA204:OPM-065","parentItemId":null,"revision":1,"payload":{"prompt":"PERT, used alongside CPM in production scheduling, stands for:","options":["Project Estimation and Resource Timing","Programme Evaluation and Review Technique","Planned Expenditure and Revenue Tracking","Production Efficiency and Reorder Technique"],"correctOption":1,"section":"Operational Modelling","explanation":"PERT is the Programme Evaluation and Review Technique, a network-based tool used with the Critical Path Method to plan, sequence and control projects with many interrelated activities. Options A, D and C are invented expansions that mix in inventory or budgeting terms."}},{"itemId":"792a4588-2fb5-5e7d-93b7-2036174435bd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f02ce4b3-2098-53de-93dc-151ebb22f943","sourceKey":"bank:BUA204:PQ-001","parentItemId":null,"revision":1,"payload":{"prompt":"Quantitative analysis is also commonly referred to as:","options":["Behavioural Science","Operations Research","Organisational Theory","Industrial Psychology"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis is also known as Operations Research (OR), Management Science or Decision Science, because it applies mathematical and statistical methods to management problems. Options A, C and D are behavioural or organisational disciplines that study people and structures rather than using quantitative models to solve decision problems."}},{"itemId":"91bf120f-3834-5361-92a4-89337258c1ee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f1ae6548-626b-5fec-bd13-e5fbbd3a0eda","sourceKey":"bank:BUA204:PQ-002","parentItemId":null,"revision":1,"payload":{"prompt":"The first stage in the quantitative analysis process is:","options":["Constructing the model","Testing the solution","Defining the problem","Implementing the results"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Every quantitative analysis begins by developing a clear, concise statement of the problem, because that statement gives direction to all the later stages. Constructing the model (A) comes second, while testing (B) and implementing (D) come much later in the process."}},{"itemId":"26311539-cb72-5f8a-bca9-c967f09de0a8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e0552441-97a1-537a-8861-29af1bb8ea39","sourceKey":"bank:BUA204:PQ-003","parentItemId":null,"revision":1,"payload":{"prompt":"A scale model of a new office building is an example of a:","options":["Mathematical model","Physical (iconic) model","Schematic model","Heuristic model"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A physical or iconic model looks like the real object it represents, only larger or smaller, which is exactly what a scale model of a building is. A schematic model (C) does not look like the real thing but behaves like it, and a mathematical model (A) uses equations and symbols rather than a physical likeness."}},{"itemId":"f57c4c1d-17b4-5f77-9ccd-63e2f3677686","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fbfae4da-eb60-5daf-9518-96303087fd5d","sourceKey":"bank:BUA204:PQ-004","parentItemId":null,"revision":1,"payload":{"prompt":"GIGO in quantitative analysis stands for:","options":["Goals In, Goals Out","Garbage In, Garbage Out","Growth In, Growth Out","General Input, General Output"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"GIGO means Garbage In, Garbage Out: if the input data fed into a model are inaccurate, the results will be poor no matter how good the model is. The other expansions in A, C and D are made-up phrases that do not describe this data-quality principle."}},{"itemId":"6c06d26b-2fbc-578b-b91d-c042dfe2cc2a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"59d96abf-60c0-57ac-a90f-8d0af683df4c","sourceKey":"bank:BUA204:PQ-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a qualitative factor in decision-making?","options":["Break-even point","Government policy change","Net present value","Standard deviation"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A government policy change is a qualitative factor: it can strongly affect a decision but is difficult to express as a precise number. The break-even point (A), net present value (C) and standard deviation (D) are all calculated figures, so they are quantitative measures."}},{"itemId":"2f4c1fad-ae23-59bc-8b53-8467c21320f3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a483f850-97db-51eb-9d83-3b6f7e8c5d08","sourceKey":"bank:BUA204:PQ-006","parentItemId":null,"revision":1,"payload":{"prompt":"An organisational chart is best described as a:","options":["Physical model","Mathematical model","Schematic (analogue) model","Iconic model"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"An organisational chart does not look like the organisation itself, but it represents how the organisation works, showing reporting relationships, so it is a schematic (analogue) model. Physical and iconic models (A and D) physically resemble the real object, and a mathematical model (B) is built from equations and symbols."}},{"itemId":"2fd72d31-ec84-5e0d-be83-498584b2e6d7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"eb9f2359-7316-50e4-b8a3-6ef64b31bd3a","sourceKey":"bank:BUA204:PQ-007","parentItemId":null,"revision":1,"payload":{"prompt":"Operations Research originated from techniques developed during:","options":["The Industrial Revolution","World War II","The Great Depression","The Information Age"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Operations Research grew out of the work of Allied military planners in World War II, who used mathematical methods to deploy scarce resources such as radar and convoys. Businesses later adopted the same methods, but the field did not begin in the Industrial Revolution (A), the Great Depression (C) or the Information Age (D)."}},{"itemId":"5c221aa7-4143-5798-9368-9ee944180a2a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9f93d9a6-b9d4-533e-ac56-2d22d76f58c3","sourceKey":"bank:BUA204:PQ-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which stage of the QA process involves checking both the model and input data for accuracy?","options":["Defining the problem","Testing the solution","Implementing the results","Constructing the model"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"In the testing stage, both the input data and the model are checked for accuracy and consistency, often by comparing results with past outcomes, before the solution is used. Constructing the model (D) is where the model is built, not checked, and implementation (C) happens only after testing."}},{"itemId":"3cd5de60-9064-5f41-a485-184b0739502a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"85cef8a3-eaad-5e36-a255-5bd2dab08d14","sourceKey":"bank:BUA204:PQ-009","parentItemId":null,"revision":1,"payload":{"prompt":"A mathematical model is considered good when it is:","options":["As complex as possible","Simple yet captures relevant features of the problem","Based purely on intuition","Free of all assumptions"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A good model is simple enough to understand and use, yet complete enough to capture the features that really affect the decision. Making it as complex as possible (A) makes it hard to use, intuition alone (C) is not modelling, and every model relies on some assumptions, so D is unrealistic."}},{"itemId":"0d02c9bd-1e76-5186-80cd-b888721effa9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2bc6b763-327f-566b-a528-296f7bb85f22","sourceKey":"bank:BUA204:PQ-010","parentItemId":null,"revision":1,"payload":{"prompt":"Sensitivity analysis is most closely associated with which stage of the QA process?","options":["Defining the problem","Analysing the results","Acquiring input data","Implementing the results"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"When analysing the results, the analyst checks the implications of the solution and performs sensitivity analysis to see how the answer changes if inputs or the model change. Acquiring input data (C) is about gathering figures, and implementing (D) is about putting the solution into practice."}},{"itemId":"8ef08d57-76df-5a91-bf76-f33d15da3e56","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b82eefa8-53f3-57d7-bd7c-d95c7f6844fa","sourceKey":"bank:BUA204:PQ-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT typically a reason quantitative analysis solutions fail to be implemented?","options":["Resistance to change","Lack of management support","Excess input data accuracy","Solutions that are difficult to understand"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Having very accurate input data is a strength, not a cause of failure, so C is the odd one out. Resistance to change (A), lack of management support (B) and solutions that managers cannot understand (D) are all common reasons why technically sound solutions are never put into use."}},{"itemId":"ada5092f-84c0-5928-bb2e-cd64271e4d97","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bca74344-3d79-5682-90fd-971cfd2fb1a7","sourceKey":"bank:BUA204:PQ-012","parentItemId":null,"revision":1,"payload":{"prompt":"Quantitative analysis primarily complements managerial decision-making by:","options":["Replacing all managerial judgement","Providing an objective, structured basis for decisions","Eliminating the need for data","Avoiding the use of mathematics"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis gives managers an objective, repeatable and structured basis for decisions, which they then combine with their own judgement. It does not replace judgement (A), and it depends on data and mathematics rather than eliminating them (C and D)."}},{"itemId":"6014a539-9522-5c0b-bba6-9024db061f03","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6e1d3639-7fc7-514f-a359-1f86f88198d4","sourceKey":"bank:BUA204:PQ-013-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best defines quantitative analysis in management?","options":["Decision-making based mainly on a manager's experience, intuition and judgement","Collecting opinions from a panel of experts until they reach agreement","A scientific approach to decision-making that uses mathematical and statistical tools to turn raw data into meaningful information","Recording business transactions in books of account"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis is the scientific, structured approach in which raw data are processed with mathematical and statistical tools to produce information that supports a decision. Option A describes intuitive, qualitative decision-making, option B describes an expert-opinion method such as Delphi, and option D describes bookkeeping."}},{"itemId":"15f06937-16fe-5855-b3e4-251e4101197d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5bfea769-2ba2-5f17-89a2-a04ac29c02a7","sourceKey":"bank:BUA204:PQ-013-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT another name commonly used for quantitative analysis?","options":["Behavioural science","Operations research","Decision science","Management science"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Behavioural science studies human behaviour and is not another name for quantitative analysis. Management science (D), operations research (B) and decision science (C) are all accepted alternative names for the discipline."}},{"itemId":"96b33c93-13a3-5af1-a849-74ba0230021c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a31dca6c-cba7-55a7-a7a8-fb8d00d02c1d","sourceKey":"bank:BUA204:PQ-014-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the seven-stage quantitative analysis process, which stage comes immediately after constructing the model?","options":["Developing a solution","Defining the problem","Acquiring input data","Testing the solution"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"The seven stages run: defining the problem, constructing the model, acquiring input data, developing a solution, testing the solution, analysing the results and implementing the results. So acquiring input data follows model construction. Developing a solution (A) needs the data first, testing (D) comes later, and defining the problem (B) comes before the model."}},{"itemId":"c150962a-83ba-55bf-9adb-840ed7e5d8a7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"330b1841-ec9b-5f31-9e01-20f8006a7943","sourceKey":"bank:BUA204:PQ-014-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the LAST stage of the seven-stage quantitative analysis process?","options":["Developing a solution","Implementing the results","Analysing the results","Testing the solution"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"The process ends with implementing the results, where the solution is incorporated into the organisation with the support of operating management. Analysing the results (C) is the sixth stage, testing (D) the fifth and developing a solution (A) the fourth."}},{"itemId":"34c6b0bb-25bd-5b08-867e-f0a9c7f59881","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8789d377-a319-5927-93e6-5be3bbd2f330","sourceKey":"bank:BUA204:PQ-014-c","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence shows four stages of the quantitative analysis process in the correct order?","options":["Defining the problem -> Developing a solution -> Constructing the model -> Implementing the results","Constructing the model -> Defining the problem -> Testing the solution -> Developing a solution","Defining the problem -> Constructing the model -> Developing a solution -> Analysing the results","Acquiring input data -> Defining the problem -> Analysing the results -> Testing the solution"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"In the correct order a problem is defined, then modelled, then solved, and the results are analysed later. Option B builds the model before defining the problem, option A solves before building the model, and option D collects data before the problem is defined and analyses results before testing."}},{"itemId":"660df03a-e4a7-5efc-8408-a900eef4da9d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cafd7938-b930-52cb-bc3b-6b36c6019d7b","sourceKey":"bank:BUA204:PQ-015-a","parentItemId":null,"revision":1,"payload":{"prompt":"A graph relating a car's speed to its fuel consumption is an example of which type of model?","options":["Physical (iconic) model","Heuristic model","Schematic (analogue) model","Scale model"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"A schematic or analogue model does not look like the real thing but behaves like it, and a graph of speed against fuel use represents how the car behaves without looking like a car. Physical (iconic) and scale models (A and D) physically resemble the real object, while a heuristic (B) is a rule of thumb rather than a model type in this classification."}},{"itemId":"df79da49-09a4-57dd-b749-f0caef0f3644","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f40f7d2e-4ce8-5fb5-9e1f-c055923605c4","sourceKey":"bank:BUA204:PQ-015-b","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main distinguishing feature of a physical (iconic) model?","options":["It uses numbers and symbols to represent relationships","It looks like the real object it represents, only larger or smaller","It relies only on the manager's intuition","It does not look like the real object but behaves like it"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A physical (iconic) model is a likeness of the real thing, such as a scale model of a factory floor or a model aircraft. Option D describes a schematic (analogue) model, option A describes a mathematical (symbolic) model, and option C is not a model at all."}},{"itemId":"93f2b371-4be7-5de0-8243-ecad6f481fb7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7ed259d7-b613-5a23-aa29-c1c19cdbaace","sourceKey":"bank:BUA204:PQ-016-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of using models in managerial decision-making?","options":["They guarantee a perfect representation of reality","They make qualitative factors irrelevant","They allow managers to ask 'what-if' questions cheaply without disrupting actual operations","They remove the need to collect any data"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Models let managers test 'what-if' scenarios on paper or a computer instead of experimenting on the real business, which saves time and money. Models still need data (D), are simplifications rather than perfect copies of reality (A), and qualitative factors remain important (B)."}},{"itemId":"e5c8ff1d-86da-5d2c-91bf-5f72eb990d32","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0aab4fa9-af1b-5b7a-91cf-1908d8250624","sourceKey":"bank:BUA204:PQ-016-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of using models in management?","options":["They save time and money compared with trial-and-error in the real system","They eliminate the need for managerial judgement","They force managers to be explicit about objectives, constraints and assumptions","They help handle complex problems with many interrelated variables systematically"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Models support managerial judgement but do not eliminate it, so this is not an advantage. Being explicit about objectives and assumptions (C), saving time and money (A) and handling complex problems systematically (D) are all genuine advantages of modelling."}},{"itemId":"99ae0e97-6ab7-513a-9f20-f6e2380b7de7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d89235b6-571c-576a-87e0-d5f5a9926824","sourceKey":"bank:BUA204:PQ-017-a","parentItemId":null,"revision":1,"payload":{"prompt":"A technically correct model is fed with carelessly gathered, unreliable figures. According to the GIGO principle, what is the likely result?","options":["Poor, untrustworthy recommendations","Accurate results, because a correct model corrects bad data","Results that are always too optimistic","No result at all, because the model cannot run"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Garbage In, Garbage Out means that bad input data produce bad output, however well the model is built. A model cannot correct faulty data (B), it will usually still produce an answer (D), and the errors could push results in either direction rather than always upwards (C)."}},{"itemId":"b847b776-92a4-579d-8dce-a082551a83b2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ce4e38ff-c979-5353-ac31-de86ff97a98f","sourceKey":"bank:BUA204:PQ-017-b","parentItemId":null,"revision":1,"payload":{"prompt":"The GIGO problem is most directly linked with which stage of the quantitative analysis process?","options":["Implementing the results","Acquiring input data","Analysing the results","Defining the problem"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"GIGO is about the quality of the data fed into a model, so it belongs to the stage of acquiring input data. Defining the problem (D) is about stating the problem clearly, while analysing (C) and implementing (A) results come after the data have already been used."}},{"itemId":"7a424245-b8bf-5233-8be2-46d9ee2e44c2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cbe637da-5a6c-5525-bfc6-7b8d1a22c57c","sourceKey":"bank:BUA204:PQ-018-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following lists contains ONLY qualitative factors that may influence a business decision?","options":["Weather conditions, political climate, competitor behaviour","Net present value, break-even point, standard deviation","Standard deviation, economic order quantity, government policy","Break-even point, weather conditions, net present value"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Weather, the political climate and competitor behaviour can strongly affect a decision but cannot easily be reduced to a single number, so they are qualitative factors. Options D and C mix in calculated measures such as break-even point, NPV, standard deviation and EOQ, and option B is made up entirely of quantitative measures."}},{"itemId":"80b8f245-7ce9-5042-aba6-0ce6839fe5cd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4256a116-794f-50a0-b615-8aabe117dfbb","sourceKey":"bank:BUA204:PQ-019-a","parentItemId":null,"revision":1,"payload":{"prompt":"Why is the 'defining the problem' stage regarded as the most important stage of the quantitative analysis process?","options":["It gives direction to every later stage, and a wrongly defined problem leads to a technically correct but practically useless solution","It is the only stage that requires numerical data","It is the stage where the optimal solution is calculated","It is the stage where sensitivity analysis is carried out"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Every later stage builds on the problem statement, so if the problem is defined wrongly, even a perfectly solved model answers the wrong question. The optimal solution is calculated when developing a solution (C), data are needed at several stages (B), and sensitivity analysis belongs to analysing the results (D)."}},{"itemId":"f2868bc5-3db4-5b8f-bf6b-4fb485ff0a1e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6ce1ef8e-38c3-5090-a683-e449dbf4c02e","sourceKey":"bank:BUA204:PQ-020-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following could cause a technically optimal quantitative solution to fail at the implementation stage?","options":["Defining the problem clearly at the start","Testing the model against historical outcomes","Using accurate input data","Staff resistance to change"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"Even the best solution can fail if the people who must use it resist the change, or if management does not support it. Accurate data (C), proper testing (B) and a clear problem definition (A) are good practices that make successful implementation more likely, not less."}},{"itemId":"37604486-f33b-5f99-9a02-3b7b447f1f07","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7a113d2e-5cde-52db-b1c1-6b67785d425b","sourceKey":"bank:BUA204:PQ-021-a","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos distribution company wants to decide how many cartons to order each time so that its total ordering and holding costs are as low as possible. Which quantitative tool is most suitable?","options":["Correlation coefficient","Break-even analysis","Economic order quantity (EOQ) model","Pie chart"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"The EOQ model finds the order size that minimises the combined cost of placing orders and holding stock, which is exactly this inventory problem. Break-even analysis (B) finds the sales level where revenue equals cost, a pie chart (D) only presents proportions, and a correlation coefficient (A) measures the relationship between two variables."}},{"itemId":"074e4a82-015d-54ad-8d1c-8c5576f20e14","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2b56a306-d61b-5093-afbb-8ac98d531bb6","sourceKey":"bank:BUA204:PQ-021-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes the role of quantitative analysis in managerial decision-making in a Nigerian business?","options":["It is only relevant to very large multinational companies","It replaces managerial judgement entirely, so local conditions can be ignored","It provides an objective, repeatable basis for decisions that complements managerial judgement and awareness of local factors such as inflation","It is useful only for military planning, where it began"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis supports decisions with objective, repeatable numbers, but it works best when combined with judgement about local factors such as inflation, exchange-rate movements and infrastructure. It does not replace judgement (B), and although it began in wartime planning (D), it is used by businesses of all sizes, not only multinationals (A)."}},{"itemId":"cbc8dc62-ea6a-5bcf-bea8-32b5f3e2ce85","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5fe64376-4863-5a97-8df6-88e148f8923a","sourceKey":"bank:BUA204:PQ-022-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best explains why a model need not be a perfect representation of reality to be useful?","options":["A model is useful if it captures the essential features relevant to the decision, even though it simplifies reality","A model is useful only when it contains no assumptions","Any simplification makes a model useless for decision-making","A model is useful only when it replicates every detail of reality"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Models are deliberate simplifications; what matters is that they capture the features that really affect the decision. Requiring every detail (D) would make models too complex and costly, simplification does not make a model useless (C), and every model relies on some assumptions (B)."}},{"itemId":"42ca82e1-9d1d-5cd9-9a83-76f2bc864e49","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a0cb340b-a99e-5087-a0a7-5af4c5354aa7","sourceKey":"bank:BUA204:PQ-022-b","parentItemId":null,"revision":1,"payload":{"prompt":"Making a model more complete by adding more and more detail usually comes at the cost of:","options":["Greater complexity, making it harder and costlier to build and use","Fewer variables to manage","Lower accuracy in representing the problem","Less need for input data"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"There is a trade-off between completeness and simplicity: more detail can improve accuracy, but it makes the model more complex, costly and harder to use. Extra detail does not normally lower accuracy (C), and it means more variables (B) and more input data (D), not fewer."}},{"itemId":"20dcfce0-c907-5b66-9d07-82a059ae4bc2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"327b6b32-1895-54af-99e6-c501597fa07f","sourceKey":"bank:BUA204:PQ-023-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer checks how its cost-minimising production plan would change if raw-material prices rose by 10%. Which stage of the quantitative analysis process is this?","options":["Testing the solution","Analysing the results","Acquiring input data","Defining the problem"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Checking how a solution responds to a change in an input such as raw-material price is sensitivity analysis, which is part of analysing the results. Testing the solution (A) checks the model and data for accuracy, acquiring input data (C) is about gathering figures, and defining the problem (D) happens at the very start."}},{"itemId":"7ca0aec2-262d-51a4-8574-f05b9968cef7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f8417614-1b57-5726-a67d-a3c1024da5c9","sourceKey":"bank:BUA204:PQ-023-b","parentItemId":null,"revision":1,"payload":{"prompt":"Before adopting a new cost model, a factory compares the model's predicted cost with the actual cost recorded last month. This belongs to which stage?","options":["Analysing the results","Constructing the model","Testing the solution","Implementing the results"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Comparing model predictions with actual historical results is a way of testing whether the model and its data are accurate before relying on them. Analysing the results (A) is about implications and sensitivity, implementing (D) is rolling the solution out, and constructing the model (B) is building the equations in the first place."}},{"itemId":"39e79708-9f26-5d1f-a3e5-347173d21ed9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ab210c4a-f9f6-529f-b38c-bb6f144ea24e","sourceKey":"bank:BUA204:PQ-023-c","parentItemId":null,"revision":1,"payload":{"prompt":"Writing the equation TC = FC + VQ to represent a factory's total cost belongs to which stage of the quantitative analysis process?","options":["Constructing the model","Defining the problem","Implementing the results","Acquiring input data"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Translating a business situation into mathematical relationships, such as a total-cost equation, is constructing the model. Acquiring input data (D) means collecting the actual cost figures to put into the equation, defining the problem (B) comes before modelling, and implementing (C) comes at the end."}},{"itemId":"6a1b3c70-9f54-5eec-bc34-1199346eebdb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f4f90752-240a-5076-a971-95b565f8fbd0","sourceKey":"bank:BUA204:PQ-024-a","parentItemId":null,"revision":1,"payload":{"prompt":"Managers refuse to use a mathematically optimal solution because they cannot understand how it was derived. Which remedy is most appropriate?","options":["Skip the testing stage to save time","Make the model more complex","Collect input data to more decimal places","Explain the solution and its logic in plain managerial language"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"An optimal solution is of little value if managers do not understand or trust it, so presenting it clearly in plain language helps them accept it. More decimal places (C) and a more complex model (B) would not help understanding, and skipping testing (A) would make the solution less reliable."}},{"itemId":"b371e9ec-b35e-5f09-b165-b7f02d0014dd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7c90e0e3-0075-552e-b7d8-f5759cecc08a","sourceKey":"bank:BUA204:PQ-024-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which remedy best deals with conflicting viewpoints among stakeholders at the problem-definition stage?","options":["Involve all relevant stakeholders early to agree the problem statement","Leave the problem definition until the implementation stage","Begin building the model immediately and define the problem later","Rely on one department's view of the problem only"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Bringing stakeholders together early helps everyone agree on what the problem really is before any modelling begins. Starting the analysis before the problem is understood (C) is a known pitfall, relying on one department (D) ignores wider organisational impacts, and the problem must be defined first, not at implementation (B)."}},{"itemId":"d669e69f-d7f4-5c9e-862c-8d3969737436","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7756621f-db26-5197-ae1d-ca47eccd6717","sourceKey":"bank:BUA204:PQ-025-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a qualitative technique for decision-making?","options":["Economic order quantity","Net present value","Break-even analysis","Delphi method"],"correctOption":3,"section":"Introduction to Quantitative Analysis in Management","explanation":"The Delphi method gathers and refines expert opinion, so it relies on judgement rather than calculation and is a qualitative technique. Break-even analysis (C), net present value (B) and EOQ (A) are all calculations, so they are quantitative techniques."}},{"itemId":"df6b80dc-8d85-538f-8ec4-19e5f84a80b8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"22195925-2239-5d4c-a3d5-9e753e11cc6e","sourceKey":"bank:BUA204:PQ-025-b","parentItemId":null,"revision":1,"payload":{"prompt":"Why is a combination of quantitative and qualitative analysis often recommended for managerial decisions?","options":["Quantitative analysis narrows the feasible alternatives objectively, while qualitative judgement weighs factors that resist measurement","Combining the two removes all uncertainty from decisions","Qualitative analysis is always more accurate than quantitative analysis","Quantitative analysis cannot handle numerical data on its own"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"Numbers help to screen options objectively, while judgement covers things like political risk or staff morale that are hard to measure, so together they give more robust decisions. Qualitative analysis is not always more accurate (C), quantitative analysis is built for numerical data (D), and no combination removes all uncertainty (B)."}},{"itemId":"465ffa66-1eb8-5189-bb40-f7f6f12f5dfb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0dedac6c-c5ce-5997-89b7-a08b96c1608f","sourceKey":"bank:BUA204:PQ-025-c","parentItemId":null,"revision":1,"payload":{"prompt":"A major limitation of quantitative analysis, compared with qualitative analysis, is that it:","options":["Is largely subjective","May be biased or inconsistent because it rests on personal opinion","May ignore factors that cannot be measured","Relies mainly on experience and intuition"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Because quantitative analysis works with numerical, measurable data, it can overlook important factors that cannot be measured. Being subjective (A), relying on intuition (D) and being prone to personal bias (B) describe qualitative analysis rather than quantitative analysis."}},{"itemId":"3a0cf5f6-3b0e-5765-ae8c-0bb6953457fd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2d86de5a-23c9-5d43-8f4b-c68420523566","sourceKey":"bank:BUA204:PQ-026","parentItemId":null,"revision":1,"payload":{"prompt":"In the equation TC = FC + VQ, the letter V represents:","options":["Total cost","Variable cost per unit","Fixed cost","Total volume"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"In TC = FC + VQ, V is the variable cost per unit, which is multiplied by the quantity Q to give total variable cost. Total cost (A) is TC on the left of the equation, fixed cost (C) is FC, and quantity is Q, not V, so D is wrong."}},{"itemId":"d3f75028-942f-5179-bd52-96045f58e57a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1dcdc203-6d29-5b71-9a2b-76edc6be3231","sourceKey":"bank:BUA204:PQ-027","parentItemId":null,"revision":1,"payload":{"prompt":"The break-even point occurs where:","options":["TR > TC","TR < TC","TR = TC","FC = 0"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"At the break-even point total revenue exactly equals total cost, so the firm makes neither profit nor loss. TR greater than TC (A) means a profit, TR less than TC (B) means a loss, and fixed cost being zero (D) is not the definition of break-even."}},{"itemId":"091c958f-8600-5f0f-9968-497e3d2ad837","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"982b6c2c-10d0-57ed-9770-09caa249c613","sourceKey":"bank:BUA204:PQ-028","parentItemId":null,"revision":1,"payload":{"prompt":"Contribution per unit is calculated as:","options":["Price - Fixed cost","Price - Variable cost","Price + Variable cost","Fixed cost / Price"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution per unit is selling price minus variable cost per unit (P - V); it is the amount each unit contributes towards covering fixed costs and then profit. Subtracting fixed cost from price (A) mixes a per-unit figure with a total figure, and options C and D are not contribution formulas."}},{"itemId":"f7aeb6d0-21a8-5fec-a1db-fd6c3146c817","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fdee07c5-34c8-5041-aded-8f148a9769d0","sourceKey":"bank:BUA204:PQ-029","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has FC = N100,000, P = N50 and V = N30. Its break-even point in units is:","options":["2,000","3,333","5,000","1,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"BEP in units = FC / (P - V) = 100,000 / (50 - 30) = 100,000 / 20 = 5,000 units. Option A divides by the price (100,000 / 50), and option B divides by the variable cost (100,000 / 30), instead of by the contribution per unit."}},{"itemId":"01c7fe32-3f79-507c-8133-7a116706a1f1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a0c3eb05-cc3c-5dbd-aba5-a7dfd0d5e6f8","sourceKey":"bank:BUA204:PQ-030","parentItemId":null,"revision":1,"payload":{"prompt":"Margin of safety is defined as:","options":["Actual sales minus break-even sales","Fixed cost minus variable cost","Total revenue minus total cost at zero output","Price minus contribution"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"The margin of safety is the amount by which actual (or budgeted) sales exceed break-even sales, showing how far sales can fall before a loss is made. Fixed cost minus variable cost (B), revenue minus cost at zero output (C) and price minus contribution (D, which just gives variable cost) are not the margin of safety."}},{"itemId":"98509893-b678-5580-ab56-a6d6408ae65c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4dd60765-f586-5a6f-ab4b-5c947a9a59a9","sourceKey":"bank:BUA204:PQ-031","parentItemId":null,"revision":1,"payload":{"prompt":"If an item costing N500 is sold at a 20% mark-up, the selling price is:","options":["N520","N600","N400","N625"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Mark-up is based on cost, so the profit is 20% x N500 = N100 and the selling price is N500 + N100 = N600. Option D (N625) is the price that would give a 20% margin on selling price (500 / 0.8), and option A adds only N20 instead of 20%."}},{"itemId":"b3d0457d-250f-524c-86ae-e2c4512c9e8d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9535ea02-52bf-597d-849a-e4ff342a617a","sourceKey":"bank:BUA204:PQ-032","parentItemId":null,"revision":1,"payload":{"prompt":"For a profitable item, the margin (profit as a percentage of selling price) will always be ______ the mark-up (profit as a percentage of cost).","options":["equal to","greater than","less than","unrelated to"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Margin divides the profit by the selling price, which is larger than the cost, so the margin percentage is always smaller than the mark-up percentage. For example, an item costing N800 and selling for N1,000 has a 25% mark-up but only a 20% margin, so B is the reverse of the truth and A cannot be right."}},{"itemId":"4c528023-ee40-5aa1-a003-49d35b386144","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"68f2fb5b-cda0-51ba-b50a-d3116db6e764","sourceKey":"bank:BUA204:PQ-033","parentItemId":null,"revision":1,"payload":{"prompt":"Simple interest on N100,000 at 8% per annum for 2 years is:","options":["N8,000","N16,000","N116,640","N216,000"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Simple interest I = P x R x T = 100,000 x 0.08 x 2 = N16,000. Option A is the interest for only one year, and option C (N116,640) is the total amount under compound interest, not the simple interest earned."}},{"itemId":"2e5c66ff-7ef2-5bf7-8838-d51f13058961","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a134e07d-720b-5536-9f74-2b1bf8f44bd6","sourceKey":"bank:BUA204:PQ-034","parentItemId":null,"revision":1,"payload":{"prompt":"Compound interest differs from simple interest because it:","options":["Ignores the principal","Charges interest on accumulated interest","Is always lower","Applies only to loans"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Under compound interest, each period's interest is added to the principal and then earns interest itself, so interest is charged on accumulated interest. It does not ignore the principal (A), it is generally higher rather than lower than simple interest over more than one period (C), and it applies to savings and investments as well as loans (D)."}},{"itemId":"cb8a42a8-d56a-5d4b-8b25-57a65f71b15a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b64fabaf-e554-552d-a347-a70052087b71","sourceKey":"bank:BUA204:PQ-035","parentItemId":null,"revision":1,"payload":{"prompt":"Two simultaneous linear equations with two unknowns can be solved by:","options":["Differentiation only","Substitution or elimination","Integration","Regression"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Two simultaneous linear equations are solved by substitution (expressing one unknown in terms of the other) or elimination (adding or subtracting the equations to remove one unknown). Differentiation (A) and integration (C) are calculus tools, and regression (D) fits a line to data rather than solving a pair of equations."}},{"itemId":"5e65cf90-4484-52e6-9ea7-151fad9cd97a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3b9439d5-4f40-5f08-b122-32360dde4970","sourceKey":"bank:BUA204:PQ-036","parentItemId":null,"revision":1,"payload":{"prompt":"If sales rise from N80,000 to N100,000, the percentage increase is:","options":["20%","25%","80%","12.5%"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Percentage change = (new - old) / old x 100 = (100,000 - 80,000) / 80,000 x 100 = 25%. Option A wrongly divides the N20,000 increase by the new value of N100,000 instead of the old value."}},{"itemId":"fa7d2bf0-6fec-59d2-b5de-41a94e5f1ee1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5719d594-d0cf-5ec7-83fc-e0f2a045f653","sourceKey":"bank:BUA204:PQ-037","parentItemId":null,"revision":1,"payload":{"prompt":"An increase in fixed cost, all else constant, will cause the break-even point (in units) to:","options":["Decrease","Remain unchanged","Increase","Become negative"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Since BEP = FC / (P - V), a higher fixed cost with the same contribution per unit means more units must be sold to cover it, so the break-even point rises. It would only decrease (A) if fixed cost fell or contribution rose, and it cannot stay the same (B) when the numerator changes."}},{"itemId":"314b5e95-4818-5e84-b5f9-608f7f8dffc0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3edc0112-67d0-5f81-829e-6fdf81c7801b","sourceKey":"bank:BUA204:PQ-038-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the formula BEP (units) = FC / (P - V), what does the term (P - V) represent?","options":["Total cost per unit","Profit after fixed costs","Contribution per unit","Margin of safety"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"P is the selling price per unit and V is the variable cost per unit, so P - V is the contribution each unit makes towards fixed costs. It is not total cost per unit (A) because fixed cost is not included, it is not profit after fixed costs (B), and the margin of safety (D) is actual sales minus break-even sales."}},{"itemId":"e00ef295-c79d-5449-855b-ba65fc936c99","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8b94cda8-0699-5181-a745-86531e768a9d","sourceKey":"bank:BUA204:PQ-038-b","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed costs of N240,000, a selling price of N80 per unit and a variable cost of N50 per unit. What is its break-even point in units?","options":["3,000 units","8,000 units","4,800 units","1,846 units"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution per unit = 80 - 50 = N30, so BEP = 240,000 / 30 = 8,000 units. Option A divides by the selling price, option C divides by the variable cost, and option D wrongly adds price and variable cost (240,000 / 130)."}},{"itemId":"d0f277ff-31ac-54a4-878f-3486a1f48bf9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"24ea2750-3381-562b-9ee3-9e8b3728fb49","sourceKey":"bank:BUA204:PQ-039-a","parentItemId":null,"revision":1,"payload":{"prompt":"Mark-up and margin differ mainly in the base used. Which statement is correct?","options":["Both mark-up and margin use cost as the base","Mark-up uses cost as the base; margin uses selling price as the base","Mark-up uses selling price as the base; margin uses cost as the base","Both mark-up and margin use selling price as the base"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Mark-up expresses profit as a percentage of cost, while margin expresses the same profit as a percentage of selling price. Option C reverses the two, and options A and D wrongly give them the same base, which would make them identical."}},{"itemId":"1ed33205-560d-53f3-b9eb-80edee56df70","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"23dc4172-be5b-5683-9890-1bb67215413b","sourceKey":"bank:BUA204:PQ-039-b","parentItemId":null,"revision":1,"payload":{"prompt":"An item costs N1,500 and is sold for N2,000. What is its margin (profit as a percentage of selling price)?","options":["500%","75%","25%","33.3%"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Profit = 2,000 - 1,500 = N500, and margin = 500 / 2,000 x 100 = 25%. Option D (33.3%) is the mark-up, because it divides the profit by the cost of N1,500, and option B is cost as a percentage of selling price."}},{"itemId":"f7348bf6-9b0b-5781-a26c-85a2e0607e97","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b1129dde-fb75-5403-9d73-85e2829f41e0","sourceKey":"bank:BUA204:PQ-040-a","parentItemId":null,"revision":1,"payload":{"prompt":"A trader buys an item for N1,200 and sells it for N1,500. What is the mark-up percentage?","options":["25%","30%","20%","80%"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Mark-up = (selling price - cost) / cost x 100 = (1,500 - 1,200) / 1,200 x 100 = 300 / 1,200 x 100 = 25%. Option C (20%) is the margin, found by dividing the N300 profit by the selling price instead of the cost, and option D is cost as a percentage of selling price."}},{"itemId":"41ddb0f2-c53e-5613-915a-a0cb42958f7e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dc7317f2-f7ab-5dc5-b83b-d0bc4c935beb","sourceKey":"bank:BUA204:PQ-041-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the compound interest formula A = P(1 + R)^n, what does n represent?","options":["The number of periods","The amount accumulated","The interest rate per period","The principal"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"In A = P(1 + R)^n, n is the number of compounding periods, which is the power the growth factor is raised to. P is the principal (D), R is the interest rate per period (C) and A is the amount accumulated (B)."}},{"itemId":"cce5006c-9ca7-5dc0-a857-81d688bb663c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"41cbabb8-467c-51e2-8635-b3b3352f6e78","sourceKey":"bank:BUA204:PQ-041-b","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is invested at 10% per annum compound interest, compounded annually. Using A = P(1 + R)^n, what amount will it grow to after 2 years?","options":["N110,000","N121,000","N120,000","N21,000"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"A = 100,000 x (1.10)^2 = 100,000 x 1.21 = N121,000. Option C (N120,000) is the simple interest amount, which ignores interest on interest, option A is the amount after only one year, and option D is the interest earned rather than the total amount."}},{"itemId":"450f3e92-6891-5e2e-8648-3d1f9e794d1c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5163fa31-00a5-56d9-808e-467b658e9701","sourceKey":"bank:BUA204:PQ-042-a","parentItemId":null,"revision":1,"payload":{"prompt":"What is the simple interest on N250,000 invested for 4 years at 6% per annum?","options":["N60,000","N65,619","N15,000","N310,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Simple interest I = P x R x T = 250,000 x 0.06 x 4 = N60,000. Option C is the interest for one year only, option D is the total amount (principal plus interest), and option B is the compound interest, which would be earned only if interest were added to the principal each year."}},{"itemId":"0e1842f6-76ac-5b1b-bb62-e95e0f783e7f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9003ad72-04c6-5637-aed6-cb5c81ce5c16","sourceKey":"bank:BUA204:PQ-043-a","parentItemId":null,"revision":1,"payload":{"prompt":"What does a large margin of safety tell management about the riskiness of its sales forecast?","options":["Fixed costs are too high for the business to survive","The business is currently operating below its break-even point","Sales can fall a long way before the business starts making a loss, so the risk of a loss is lower","The contribution per unit is negative"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"The margin of safety is actual or budgeted sales minus break-even sales, so a large margin means sales have a big cushion before falling into the loss zone. A business below break-even (B) would have no positive margin of safety, and the margin does not by itself show that fixed costs are too high (A) or that contribution is negative (D)."}},{"itemId":"e8eef31c-b169-597e-b1e1-75350d846699","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"91581d4f-1896-59a5-bb42-ef5193d619a7","sourceKey":"bank:BUA204:PQ-044-a","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's fixed costs increase, but its selling price and variable cost per unit stay the same. What happens to its break-even point in units, and why?","options":["It falls, because the contribution per unit increases","It rises, because the variable cost per unit increases","It rises, because a larger fixed cost must be recovered by the same contribution per unit","It stays the same, because the contribution per unit has not changed"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"BEP = FC / (P - V); with P and V unchanged the contribution per unit is the same, so a bigger fixed cost needs more units to cover it and the break-even point rises. Contribution does not increase (A), the break-even point cannot stay the same when fixed cost rises (D), and option B gives the right direction but the wrong reason, since variable cost is unchanged."}},{"itemId":"16cc534d-8a63-52c7-ac97-301b8c002cd9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8fa911a8-f5b9-5662-8ab5-f22b2a8634d0","sourceKey":"bank:BUA204:PQ-045-a","parentItemId":null,"revision":1,"payload":{"prompt":"Solve for x: 3x + 12 = 45.","options":["x = 19","x = 15","x = 11","x = 33"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Subtract 12 from both sides to get 3x = 33, then divide by 3 to get x = 11. Option A adds 12 instead of subtracting it (57 / 3), option B ignores the 12 (45 / 3), and option D stops before dividing by 3."}},{"itemId":"19de8ca4-ed0a-5450-aeb7-f5ec4a980942","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0bf8f8d8-2061-514c-b600-5137e335b409","sourceKey":"bank:BUA204:PQ-046-a","parentItemId":null,"revision":1,"payload":{"prompt":"A company has fixed costs of N800,000 per month, a selling price of N400 per unit and a variable cost of N240 per unit. What is its break-even point in units and in naira sales?","options":["2,000 units; N800,000","3,333 units; N1,333,333","5,000 units; N1,200,000","5,000 units; N2,000,000"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution per unit = 400 - 240 = N160, so BEP = 800,000 / 160 = 5,000 units, and BEP in naira = 5,000 x N400 = N2,000,000. Option B divides by the variable cost and option A divides by the selling price, while option C has the right units but values them at variable cost instead of selling price."}},{"itemId":"8c511305-0a1e-5538-a2ff-c54e1f10a645","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f907fa80-fc41-5ce1-a4a0-031223209788","sourceKey":"bank:BUA204:PQ-046-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company has fixed costs of N800,000 per month, a selling price of N400 per unit and a variable cost of N240 per unit. How many units must it sell to earn a target profit of N480,000 per month?","options":["5,333 units","3,000 units","3,200 units","8,000 units"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Required units = (FC + target profit) / contribution per unit = (800,000 + 480,000) / 160 = 1,280,000 / 160 = 8,000 units. Option B forgets to add the fixed cost, option C divides by the selling price instead of the contribution, and option A divides by the variable cost."}},{"itemId":"2e78e1b8-bdaa-54fd-a871-910e721e0ec9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a70c151d-0c8c-5051-9430-cf67484dace7","sourceKey":"bank:BUA204:PQ-046-c","parentItemId":null,"revision":1,"payload":{"prompt":"A company with fixed costs of N800,000, a selling price of N400 per unit and a variable cost of N240 per unit currently sells 6,000 units a month. What is its margin of safety?","options":["1,000 units, or N400,000 of sales","1,000 units, or N160,000 of sales","1,000 units, or N240,000 of sales","6,000 units, or N2,400,000 of sales"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Break-even is 800,000 / (400 - 240) = 5,000 units, so the margin of safety = 6,000 - 5,000 = 1,000 units, worth 1,000 x N400 = N400,000 of sales. Options B and C value the 1,000 units at contribution or variable cost instead of selling price, and option D is simply total sales."}},{"itemId":"9b01a9bb-d01b-5b89-a2b3-f5b39c5f026a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a7949951-6b8b-5a71-b094-fa86fd5c6d11","sourceKey":"bank:BUA204:PQ-047-a","parentItemId":null,"revision":1,"payload":{"prompt":"N350,000 is invested for 5 years at 9% per annum simple interest. Using A = P(1 + RT), what is the maturity value?","options":["N507,500","N381,500","N538,518","N157,500"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A = 350,000 x (1 + 0.09 x 5) = 350,000 x 1.45 = N507,500. Option D is only the interest earned, option C is the compound interest amount, and option B is the amount after just one year."}},{"itemId":"a894a65b-423f-5d41-954f-4cead05d892a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1e28bd5c-b551-5a77-a041-870ecbc474e0","sourceKey":"bank:BUA204:PQ-047-b","parentItemId":null,"revision":1,"payload":{"prompt":"N350,000 is invested for 5 years at 9% per annum, compounded annually. Using A = P(1 + R)^n and rounding to the nearest naira, what is the maturity value?","options":["N538,518","N507,500","N381,500","N188,518"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A = 350,000 x (1.09)^5 = 350,000 x 1.538624 = N538,518 to the nearest naira. Option B is the simple interest amount, option D is only the compound interest earned, and option C is the value after one year."}},{"itemId":"d127de40-0b57-543c-8abf-062d7630a82e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4464eb17-d47a-5fa4-83ea-c4ecb62cad1e","sourceKey":"bank:BUA204:PQ-047-c","parentItemId":null,"revision":1,"payload":{"prompt":"N350,000 is invested for 5 years at 9% per annum. To the nearest naira, how much more does annual compound interest yield than simple interest, and why?","options":["Nothing, because both methods use the same rate and period","About N31,018, because from Year 2 onward compound interest also earns interest on previously accumulated interest","About N157,500, because compound interest doubles the simple interest","About N31,018, because simple interest is charged on a smaller rate"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Compound gives N538,518 and simple gives N507,500, a difference of about N31,018, because compound interest earns interest on interest. Option D has the right figure but a false reason, since both use 9%, option C wrongly treats the whole simple interest as the gap, and option A ignores the compounding effect."}},{"itemId":"b3992d7c-d282-55b8-a5cf-c714065e21fb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"164c6dbf-d4ca-5ba3-a052-dfcc39e18092","sourceKey":"bank:BUA204:PQ-048-a","parentItemId":null,"revision":1,"payload":{"prompt":"Company X charges a flat N10,000 plus N150 per km; Company Y charges a flat N25,000 plus N80 per km. At what distance (to 1 decimal place) do both companies charge the same amount?","options":["312.5 km","65.2 km","214.3 km","166.7 km"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Set 10,000 + 150d = 25,000 + 80d, so 70d = 15,000 and d = 214.3 km. Option B wrongly adds the two per-km rates (15,000 / 230), while options D and A simply divide one flat fee by one per-km rate."}},{"itemId":"3667eea4-5527-5fe5-a73d-38875906a3ec","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"02b341bc-cbeb-5431-bee3-63ba938b3b3c","sourceKey":"bank:BUA204:PQ-048-b","parentItemId":null,"revision":1,"payload":{"prompt":"Company X charges a flat N10,000 plus N150 per km; Company Y charges a flat N25,000 plus N80 per km. Which company should a client use for a 300 km delivery?","options":["Company X, because its flat fee is lower","Company X, which costs N49,000 against N55,000 for Company Y","Company Y, which costs N49,000 against N55,000 for Company X","Either, because both charge the same at 300 km"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"At 300 km, X costs 10,000 + 150 x 300 = N55,000 and Y costs 25,000 + 80 x 300 = N49,000, so Y is cheaper by N6,000. Option B swaps the two costs, option A looks only at the flat fee and ignores the higher per-km rate, and both firms charge the same only at about 214.3 km, not 300 km (D)."}},{"itemId":"8bf4e4ba-04a5-52ca-99a3-795b86167009","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"00385991-221d-55c6-88a8-efbd74a94eb4","sourceKey":"bank:BUA204:PQ-049-a","parentItemId":null,"revision":1,"payload":{"prompt":"On a standard break-even chart (quantity on the x-axis, naira on the y-axis), where does the total cost line start?","options":["At the level of fixed cost on the vertical axis","At the break-even point","At the maximum output level","At the origin"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Even at zero output the firm must pay its fixed costs, so the total cost line begins at the fixed-cost level and rises with variable cost. The total revenue line, not the total cost line, starts at the origin (D), the break-even point (B) is where the two lines cross, and option C makes no sense as a starting point."}},{"itemId":"a4f5b3af-e0eb-5c87-9158-2f220d54f3df","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"24365143-657b-5496-8977-f0150831b2a5","sourceKey":"bank:BUA204:PQ-049-b","parentItemId":null,"revision":1,"payload":{"prompt":"On a break-even chart, what happens if the selling price increases while fixed cost and variable cost per unit stay the same?","options":["The total revenue line becomes steeper and the break-even point moves to a lower quantity","Nothing changes, because costs are unchanged","The total revenue line becomes flatter and the break-even point moves to a higher quantity","The total cost line shifts upward and the break-even point moves to a higher quantity"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"A higher price makes total revenue rise faster with each unit, so the TR line becomes steeper and meets the total cost line sooner, giving a lower break-even quantity. Option C describes a price cut, option D describes a rise in costs, and option B ignores the fact that revenue has changed."}},{"itemId":"d2dfcfea-cb39-5ec3-b1de-8bba657a8146","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8d3356a6-095e-5c37-98f5-76798b7dfcc1","sourceKey":"bank:BUA204:PQ-050-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a limitation of break-even analysis as a decision tool?","options":["It cannot be used to help with pricing decisions","It assumes costs and revenue behave in a straight-line way across all output levels","It cannot be used to calculate the margin of safety","It cannot be used to find the output needed for a target profit"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Break-even analysis assumes linear cost and revenue behaviour, a single product or constant sales mix, and ignores the time value of money, which may not hold in a real business. In fact it is useful for pricing (A), measuring the margin of safety (C) and finding target-profit output (D), so those are strengths, not limitations."}},{"itemId":"7c55df78-6432-5deb-86b7-958b51410b46","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"05746a7c-45ce-5d5e-b424-6b9266494049","sourceKey":"bank:BUA204:PQ-051","parentItemId":null,"revision":1,"payload":{"prompt":"Data collected first-hand by a researcher for a specific purpose is called:","options":["Secondary data","Primary data","Discrete data","Grouped data"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Primary data are collected first-hand by the researcher for the specific purpose at hand, for example through a questionnaire or interview. Secondary data (A) were collected by someone else for another purpose, while discrete (C) and grouped (D) describe the type or arrangement of data, not how they were collected."}},{"itemId":"f665c4b1-1a42-5c55-aadc-26e8b2c558ee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fe5fbb4c-9533-5a6a-96a2-8af36eeeec0b","sourceKey":"bank:BUA204:PQ-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of secondary data?","options":["A questionnaire administered by the analyst","Government statistics published by the NBS","A new experiment","Direct observation of customers"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Statistics published by the National Bureau of Statistics were collected by someone else for another purpose, so an analyst who reuses them is using secondary data. A questionnaire (A), an experiment (C) and direct observation (D) are all ways the analyst collects primary data personally."}},{"itemId":"443d46e5-a732-5a44-9387-a822fd6576e8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"64231495-b11c-58a4-8827-c01d1a20d360","sourceKey":"bank:BUA204:PQ-053","parentItemId":null,"revision":1,"payload":{"prompt":"Discrete data can be described as:","options":["Data that can take any value within a range","Countable data taking whole-number values","Data collected through observation only","Data with no numerical value"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Discrete data are countable and take whole-number values, such as the number of employees in a branch. Option A describes continuous data, option C mixes up the type of data with a collection method, and option D describes qualitative (categorical) data."}},{"itemId":"ded372d0-f189-573f-9c86-56f31c60685e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"34d621c6-204b-535a-9f83-4e563a88e42e","sourceKey":"bank:BUA204:PQ-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which chart is most appropriate for comparing sales across five different regions?","options":["Pie chart","Histogram","Bar chart","Scatter diagram"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A bar chart is the best choice for comparing separate categories such as regions, because the bar lengths can be compared directly. A pie chart (A) shows parts of a whole, a histogram (B) shows the distribution of a continuous variable, and a scatter diagram (D) shows the relationship between two variables."}},{"itemId":"9eef806e-238c-59d4-a7ae-8c8e994cf737","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"81fe9078-be41-5d7b-b8fc-ab5eb22a0a1a","sourceKey":"bank:BUA204:PQ-055","parentItemId":null,"revision":1,"payload":{"prompt":"In a histogram, the bars:","options":["Are always separated by gaps","Touch one another because the variable is continuous","Represent categorical data only","Must all be the same colour"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Histogram bars are drawn touching each other because they represent continuous class intervals with no break between them. Gaps between bars (A) and categorical data (C) are features of a bar chart, and colour (D) has nothing to do with how a histogram is defined."}},{"itemId":"3be44dbd-49cb-5a39-bfb9-dfb88ead936c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d685e483-7838-5d36-8874-18d2477eac4a","sourceKey":"bank:BUA204:PQ-056","parentItemId":null,"revision":1,"payload":{"prompt":"The angle of a pie chart slice is calculated as:","options":["(Value / Total) x 100","(Value / Total) x 360 degrees","Value x Total","Total / Value"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A full circle is 360 degrees, so each slice gets (value / total) x 360 degrees. Option A gives the percentage of the total, not the angle, and options C and D do not produce a share of the circle at all."}},{"itemId":"b31be94e-3a50-564a-b210-abb0e9f6ef73","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e33f171b-ad16-58c0-b436-38da938b72d9","sourceKey":"bank:BUA204:PQ-057","parentItemId":null,"revision":1,"payload":{"prompt":"A line graph is best suited to showing:","options":["Composition of a whole","Trend over time","Frequency distribution","Categorical comparison"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A line graph joins data points over successive periods, so it is the standard chart for showing a trend over time, such as monthly revenue. Composition of a whole (A) suits a pie chart, a frequency distribution (C) suits a histogram, and a categorical comparison (D) suits a bar chart."}},{"itemId":"9afe9431-a325-547c-906e-ff0157840d04","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"00ca82e8-c0f7-5b88-91cf-d489a918355f","sourceKey":"bank:BUA204:PQ-058","parentItemId":null,"revision":1,"payload":{"prompt":"The width of a class in a grouped frequency distribution is approximately:","options":["Highest value / lowest value","(Highest - Lowest) / Number of classes","Number of classes / Range","Sum of all values / frequency"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Class width is found by dividing the range (highest value minus lowest value) by the number of classes you want, then usually rounding up to a convenient figure. Option C turns the formula upside down, option A is a ratio rather than a range, and option D is the formula for a mean."}},{"itemId":"fae92c6c-c3ee-5952-b0ab-ae6aa4892b5e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"031cb071-9425-5989-aed4-1bd3c1c8782e","sourceKey":"bank:BUA204:PQ-059","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a method of primary data collection?","options":["Reading a company's annual report","Conducting an interview","Using NBS inflation data","Reviewing a trade journal"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"An interview collects information directly from respondents for the researcher's own purpose, so it is a primary method. Annual reports (A), NBS inflation data (C) and trade journals (D) already exist and were prepared by others, so using them means relying on secondary data."}},{"itemId":"cdd3a27a-7354-5bb5-8893-e5aad7f96f70","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"60da418a-8857-512a-a000-902a4460af79","sourceKey":"bank:BUA204:PQ-060","parentItemId":null,"revision":1,"payload":{"prompt":"A pie chart is generally unsuitable when there are:","options":["Two categories","Three categories","More than five or six categories","Exactly one category"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"With more than about five or six categories, a pie chart fills up with thin slices that are hard to read and compare, so a bar chart is usually better. Two or three categories (A and B) are well within what a pie chart handles comfortably."}},{"itemId":"591468bf-30fc-5d7d-b0f7-5a39a415d59b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"173001fc-bad6-5679-8d30-f7e2c18e3128","sourceKey":"bank:BUA204:PQ-061","parentItemId":null,"revision":1,"payload":{"prompt":"Continuous data differs from discrete data in that continuous data:","options":["Can only take whole-number values","Can take any value within a given range","Cannot be measured","Is always categorical"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Continuous data can take any value within a range, including fractions, such as weight or time. Whole-number values only (A) describe discrete data, continuous data are measured rather than unmeasurable (C), and categorical data (D) are qualitative."}},{"itemId":"bf1559d8-2899-5ee1-b4c2-c1da30344236","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2d41f70b-8f02-54d0-877f-4208ff7c008b","sourceKey":"bank:BUA204:PQ-062","parentItemId":null,"revision":1,"payload":{"prompt":"Class boundaries for whole-number data are typically obtained by:","options":["Multiplying class limits by 2","Adding and subtracting 0.5 from the class limits","Dividing class limits by the number of classes","Ignoring the limits entirely"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"For whole-number data, class boundaries are found by subtracting 0.5 from the lower limit and adding 0.5 to the upper limit, so that 38-42 becomes 37.5-42.5 and there are no gaps between classes. Multiplying (A) or dividing (C) the limits does not close the gaps between classes."}},{"itemId":"37877fc9-fc85-503c-80c2-6cd412cf6f66","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8b8eecc8-b616-5ffb-88ac-4f32723ed69a","sourceKey":"bank:BUA204:PQ-063-a","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's marketing team designs and administers its own customer satisfaction survey. The data it collects are best described as:","options":["Secondary data","Primary data","Published data","Documentary data from existing records"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"The team collected the information first-hand for its own specific purpose, so the survey results are primary data. Secondary data (A), existing records (D) and published data (C) all refer to information that someone else has already collected for another purpose."}},{"itemId":"b4c619a7-4e99-5232-b2f4-e1ca0c40b647","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"68179443-7f13-5d02-b5f5-460e74e50607","sourceKey":"bank:BUA204:PQ-063-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes secondary data?","options":["Data collected first-hand by the researcher for a specific purpose","Data that can only take whole-number values","Data already collected by someone else for another purpose and reused by the analyst","Data obtained by changing one variable under controlled conditions"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Secondary data already exist because someone else collected them for a different purpose, such as NBS inflation statistics, and the analyst simply reuses them. Option A describes primary data, option B describes discrete data, and option D describes an experiment, which is a primary method."}},{"itemId":"41c8a049-ad2f-5980-ac86-6ed02c587931","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b43fd38e-db39-5d3c-9e1f-b484df8eac59","sourceKey":"bank:BUA204:PQ-064-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which list contains ONLY methods of primary data collection?","options":["Questionnaire, interview, observation","Questionnaire, NBS statistics, interview","Experiment, published financial statements, interview","Annual reports, trade journals, observation"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Questionnaires, interviews and observation all gather fresh data directly for the researcher, as do experiments. Each of the other lists includes a secondary item: NBS statistics in B, annual reports and trade journals in D, and published financial statements in C."}},{"itemId":"6c45b0c0-2af3-50ee-8fa8-c11d2167db2a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"33421f9e-6924-511a-b955-fa740e8487f1","sourceKey":"bank:BUA204:PQ-064-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company changes one ingredient in a product formula under controlled conditions and records the effect on taste ratings. Which data collection method is this?","options":["Observation","Interview","Questionnaire","Experiment"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"An experiment deliberately changes one variable under controlled conditions to see its effect, which is what testing a new formula does. Observation (A) records behaviour as it happens without manipulating anything, while interviews (B) and questionnaires (C) ask people questions."}},{"itemId":"4e383d17-2e41-5a5c-8c0c-b887a28f68de","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"959dc2f5-562d-5f9b-aafe-612d92f56936","sourceKey":"bank:BUA204:PQ-065-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of continuous data?","options":["The number of customers served per day","The number of staff in a branch","The weight of bags of rice in kilograms","The number of cars sold in a month"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Weight can take any value within a range, such as 49.75 kg, so it is continuous data. The number of staff (B), customers (A) and cars (D) are all counts that take whole-number values, which makes them discrete data."}},{"itemId":"0645b8bb-10be-537f-9bd1-0265139430eb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f12e2b92-fbde-520e-aac6-339516b7dc10","sourceKey":"bank:BUA204:PQ-066-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes a histogram from a bar chart?","options":["A bar chart's bars touch and show a continuous variable, while a histogram's bars are separated and compare categories","Both have gaps between bars; they differ only in colour","A histogram's bars touch and show the distribution of a continuous variable, while a bar chart's bars are separated and compare categories","In a bar chart bar area shows frequency, while in a histogram only bar height matters"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A histogram shows how one continuous variable is distributed across numerical classes, so its bars touch, while a bar chart compares separate categories with gaps between bars. Option A reverses the two, option B ignores the real difference, and option D also reverses them, since it is in a histogram that bar area represents frequency."}},{"itemId":"23e5ef7d-4054-5eab-825a-18c4e9198212","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ccc28a25-aee8-5e88-ba70-efa15d951405","sourceKey":"bank:BUA204:PQ-066-b","parentItemId":null,"revision":1,"payload":{"prompt":"In a histogram, the frequency of each class is represented by:","options":["The gap between bars","The colour of the bar","The angle of the slice","The area of the bar"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"In a histogram the area of each bar is proportional to the frequency of its class, which matters especially when classes have unequal widths. Histograms have no gaps between bars (A), colour carries no frequency information (B), and slice angles (C) belong to pie charts."}},{"itemId":"caf961c2-d1a0-55f6-a614-76930e594c14","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2ded498c-7ca6-5f11-aa29-0e627b9fdc63","sourceKey":"bank:BUA204:PQ-067-a","parentItemId":null,"revision":1,"payload":{"prompt":"Why would a pie chart be unsuitable for presenting data with 12 categories?","options":["A pie chart cannot show angles greater than 180 degrees","Many thin slices clutter the chart and make similar-sized slices hard to compare","A pie chart can only show trends over time","A pie chart can only be used for continuous data"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Pie charts work best with about five or six categories or fewer; with 12, the slices become thin and similar slices are hard to tell apart. A pie chart uses the full 360 degrees (A), trends over time suit a line graph (C), and pie charts show parts of a whole, not continuous distributions (D)."}},{"itemId":"f633e586-bc74-51ed-9725-03a1237faeee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1b3e7bb6-48a3-5fc8-b3a9-c4bfd5caa50a","sourceKey":"bank:BUA204:PQ-067-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which chart would usually present the values of 12 separate categories more clearly than a pie chart?","options":["Bar chart","Scatter diagram","Pie chart with more colours","Histogram"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"A bar chart lets the reader compare 12 separate categories easily, because bar lengths are simple to line up and compare. A histogram (D) is for continuous grouped data, a scatter diagram (B) shows the relationship between two variables, and extra colours (C) do not solve the problem of too many thin slices."}},{"itemId":"d0e05b96-8493-5e36-9274-e63648d409dc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bf435e8f-bc7d-5624-84a2-6a406a325181","sourceKey":"bank:BUA204:PQ-068-a","parentItemId":null,"revision":1,"payload":{"prompt":"In a grouped frequency distribution, class width refers to:","options":["The total number of classes","The midpoint of a class","The number of observations in a class","The size of each class interval"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Class width is the size of each class interval, estimated as (highest value - lowest value) / number of classes. The number of observations in a class (C) is its frequency, the midpoint (B) is the class mark, and the number of classes (A) is a separate choice made before finding the width."}},{"itemId":"988dc66d-858a-55d8-8a9f-86bd4cc87adb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9d17b9c4-9ea6-524c-bbc9-5f829b265f99","sourceKey":"bank:BUA204:PQ-068-b","parentItemId":null,"revision":1,"payload":{"prompt":"A data set has a highest value of 87 and a lowest value of 12. Using class width = (highest - lowest) / number of classes, what is the class width for 5 classes?","options":["15","2.4","75","17.4"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"The range is 87 - 12 = 75, and 75 / 5 = 15. Option D divides the highest value alone by 5, option C is the range before dividing, and option B divides the lowest value by 5."}},{"itemId":"cec7c03e-85b1-5486-9d48-7db98ab99b93","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1fd42efa-d056-599f-a50e-245e5b02c36d","sourceKey":"bank:BUA204:PQ-069-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a feature of a well-constructed statistical table?","options":["Leaving out totals even where they help the reader","A clear, descriptive title","Omitting units of measurement","Unlabelled columns to save space"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A good table has a clear title, labelled rows and columns with units stated, totals where appropriate, and a statement of where any secondary data came from. Unlabelled columns (D), missing units (C) and leaving out helpful totals (A) all make a table harder to understand."}},{"itemId":"768008f0-5dd1-5c0e-b7e4-bea2cc244c79","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"78e65ea5-cbbe-5f86-bbc2-ad2a4f8e996d","sourceKey":"bank:BUA204:PQ-070-a","parentItemId":null,"revision":1,"payload":{"prompt":"A line graph should be preferred over a bar chart when the aim is to:","options":["Compare the sales of separate branches at one point in time","Compare the number of staff in different departments","Show how a variable changes over successive time periods","Show how a total budget is split into parts"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"A line graph is the chart of choice when the message is a trend, because it joins values across successive periods. Comparing branches (A) or departments (B) at one point in time is a categorical comparison that suits a bar chart, and showing parts of a total (D) suits a pie chart."}},{"itemId":"27669f04-06aa-5310-a64c-57c76bc921ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bdd24c52-50f0-5a99-81ef-cef2f02543f0","sourceKey":"bank:BUA204:PQ-071-a","parentItemId":null,"revision":1,"payload":{"prompt":"The monthly expenditure (N'000) of 24 households is: 35, 42, 28, 51, 39, 47, 33, 55, 44, 38, 49, 31, 46, 40, 53, 36, 48, 29, 50, 37, 45, 32, 41, 43. Using 6 classes, with class width = range / number of classes rounded UP to a whole number, what are the range and class width?","options":["Range 55; class width 10","Range 83; class width 14","Range 27; class width 4","Range 27; class width 5"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"The highest value is 55 and the lowest is 28, so the range is 27; 27 / 6 = 4.5, which rounds up to a class width of 5. Option A uses the highest value instead of the range, option C rounds down, which would leave some values outside the classes, and option B adds the highest and lowest values instead of subtracting them."}},{"itemId":"8b72e3c5-4afd-5c5b-8ff9-1dfb632bd6ea","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9d450bfd-711e-5ce7-b57b-632c56814fb2","sourceKey":"bank:BUA204:PQ-071-b","parentItemId":null,"revision":1,"payload":{"prompt":"The monthly expenditure (N'000) of 24 households is: 35, 42, 28, 51, 39, 47, 33, 55, 44, 38, 49, 31, 46, 40, 53, 36, 48, 29, 50, 37, 45, 32, 41, 43. Using the classes 28-32, 33-37, 38-42, 43-47, 48-52 and 53-57, what is the frequency of the class 38-42?","options":["3","5","6","4"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"The values falling in 38-42 are 38, 39, 40, 41 and 42, giving a frequency of 5. The full set of frequencies is 4, 4, 5, 5, 4 and 2, which correctly add up to 24; option D matches the neighbouring classes 28-32 and 33-37, not 38-42."}},{"itemId":"6f4d8eb6-81ca-509d-be53-b6b9632e84f0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"82311ce5-1521-5797-acac-a4eb00780323","sourceKey":"bank:BUA204:PQ-072-a","parentItemId":null,"revision":1,"payload":{"prompt":"A budget of N10,000,000 includes Raw Materials of N2,800,000. Using angle = (value / total) x 360 degrees, what is the pie-chart angle for Raw Materials?","options":["100.8 degrees","28 degrees","36 degrees","126 degrees"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Raw Materials are 2,800,000 / 10,000,000 = 28% of the budget, and 0.28 x 360 = 100.8 degrees. Option B gives the percentage instead of the angle, while D (126 degrees) would be the angle for a 35% share and C (36 degrees) for a 10% share."}},{"itemId":"90218c3d-51f1-5193-8d89-7c61b8a568de","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6a29e245-c203-5449-92ee-1c3bc1f87a92","sourceKey":"bank:BUA204:PQ-072-b","parentItemId":null,"revision":1,"payload":{"prompt":"A N10,000,000 budget is split as: Salaries N3,500,000; Raw Materials N2,800,000; Marketing N1,200,000; Overheads N1,500,000; Logistics N1,000,000. Which category would have a pie-chart angle of 54 degrees?","options":["Logistics","Overheads","Marketing","Salaries"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"An angle of 54 degrees is 54 / 360 = 15% of the total, which is N1,500,000, the Overheads figure. Marketing (C) at 12% gets 43.2 degrees, Logistics (A) at 10% gets 36 degrees, and Salaries (D) at 35% gets 126 degrees."}},{"itemId":"ee61252c-76e1-53ad-ae4e-9df6222f7140","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"400b8e23-5f1d-54fd-b95c-8bef6e097765","sourceKey":"bank:BUA204:PQ-073-a","parentItemId":null,"revision":1,"payload":{"prompt":"A managing director wants to compare the performance of five branch managers this quarter. Which chart is most suitable?","options":["Histogram","Bar chart","Pie chart","Line graph"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Five branch managers are separate categories being compared at one point in time, which is exactly what a bar chart is for. A pie chart (C) shows parts of a whole, a line graph (D) shows a trend over time, and a histogram (A) shows the distribution of a continuous variable."}},{"itemId":"381d2c6f-d263-5165-9772-d19b90852bac","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d578939a-a3bf-5d93-a536-f50c8f50ea68","sourceKey":"bank:BUA204:PQ-073-b","parentItemId":null,"revision":1,"payload":{"prompt":"A managing director wants to see the distribution of the ages of 150 employees. Which chart is most suitable?","options":["Scatter diagram","Pie chart","Line graph","Histogram"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Age is a continuous variable, and showing how 150 ages are spread across age classes is a frequency distribution, which a histogram presents. A pie chart (B) shows shares of a total, a line graph (C) shows change over time, and a scatter diagram (A) shows the relationship between two variables."}},{"itemId":"21b7e2d5-6637-518f-b911-4447187ff06c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ed208622-1090-558c-8445-d45912dc3c54","sourceKey":"bank:BUA204:PQ-073-c","parentItemId":null,"revision":1,"payload":{"prompt":"A managing director wants to see how the company's monthly profit has changed over the past two years. Which chart is most suitable?","options":["Histogram","Line graph","Pie chart","Organisational chart"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Monthly profit over two years is a trend over successive time periods, which a line graph shows best. A pie chart (C) shows composition of a whole, a histogram (A) shows a frequency distribution, and an organisational chart (D) shows reporting relationships, not figures."}},{"itemId":"d41a9340-9bb0-5772-b1dc-f97cd44cbef0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9b385973-4e2b-5dab-9665-4a6bed364bc2","sourceKey":"bank:BUA204:PQ-074-a","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with tables, a major limitation of charts and graphs when reporting to senior management is that they:","options":["Take longer to interpret at a glance","May lose precision and can be made misleading, for example through distorted scales","Cannot show comparisons between categories","Always preserve exact figures better than tables"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Charts communicate patterns quickly, but readers cannot easily see exact figures, and a stretched or cut-off scale can mislead. Charts are actually faster to read at a glance (A), they are very good at showing comparisons (C), and it is tables, not charts, that preserve exact figures (D)."}},{"itemId":"f69a6081-0981-5807-b7e4-2f1922c11a59","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fe8b70bb-a96c-543f-9543-d90ed3e3d5f0","sourceKey":"bank:BUA204:PQ-074-b","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main advantage of presenting data in a table rather than a chart?","options":["A table is always more persuasive to a busy audience","A table needs no title or labels","A table shows patterns and trends faster at a glance","A table preserves exact figures for detailed checking and verification"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Tables keep the precise values, which makes them useful for detailed checking and audit. Seeing patterns quickly (C) and persuading a busy audience (A) are strengths of charts, and a good table still needs a clear title and labels (B)."}},{"itemId":"4f4c3be4-e52f-5263-a034-fd2592628181","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bc5a542f-736d-53d5-ae29-cb4a130dddb1","sourceKey":"bank:BUA204:PQ-075-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a typical drawback of secondary data compared with primary data?","options":["It may be outdated or collected for a different purpose","It cannot be obtained from government publications","It is always tailored to the specific research question","It is usually more expensive and slower to obtain"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"Because secondary data were gathered by others for their own purposes, they may be out of date, defined differently or of uncertain quality for the current study. Secondary data are usually cheaper and faster to obtain (D), tailoring to the research question is a strength of primary data (C), and government publications such as NBS statistics are a common place to find secondary data (B)."}},{"itemId":"8ba3f478-7b8e-5618-94e7-4dde3a6236bc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"02584dd8-df45-5592-879b-98356f61876d","sourceKey":"bank:BUA204:PQ-075-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a typical drawback of primary data?","options":["It was collected by someone else for another purpose","It is usually out of date","It is more costly and time-consuming to collect","It is not tailored to the specific research question"],"correctOption":2,"section":"Data Collection, Organisation and Presentation","explanation":"Collecting fresh data through surveys, interviews or experiments takes time and money, which is the main drawback of primary data. Options D, B and A describe weaknesses of secondary data, because primary data are collected now, for the specific purpose, by the researcher."}},{"itemId":"4f190de7-8006-5bdb-baa5-b7344008997a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c12d400d-7286-55de-bf64-a5f5ed640869","sourceKey":"bank:BUA204:PQ-076","parentItemId":null,"revision":1,"payload":{"prompt":"The arithmetic mean of 4, 8, 6, 10, 12 is:","options":["8","9","7","10"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The mean is the sum of the values divided by how many there are: (4 + 8 + 6 + 10 + 12) / 5 = 40 / 5 = 8. The other options come from adding or dividing incorrectly; for example, 10 (D) would need a total of 50."}},{"itemId":"b2d1cc28-8e4f-560a-9fec-8d772ddf264e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"31181f30-3747-5b3f-ab4c-e2ccc832da38","sourceKey":"bank:BUA204:PQ-077","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following measures is least affected by extreme values (outliers) in a data set?","options":["Arithmetic mean","Range","Variance","Median"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The median is the middle value of the ranked data, so one very large or very small value hardly moves it. The mean (A) is pulled towards extreme values because every value enters the total, while the range (B) and variance (C) depend heavily on the most extreme values."}},{"itemId":"cda908ba-22eb-5ab4-896e-cd9e2178f3b7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"69aa585f-09c4-5eac-8778-00f014100268","sourceKey":"bank:BUA204:PQ-078","parentItemId":null,"revision":1,"payload":{"prompt":"The standard deviation is calculated as:","options":["The square of the variance","The square root of the variance","The mean of the data","The range divided by 2"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Standard deviation is the square root of the variance, which brings the measure of spread back to the original units of the data. Squaring the variance (A) goes the wrong way, and the mean (C) and half the range (D) are different measures altogether."}},{"itemId":"cb0299c5-c674-5b8b-9bc9-3192169307e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2a78a6d9-c5fc-57fe-b9b5-4c69737f4658","sourceKey":"bank:BUA204:PQ-079","parentItemId":null,"revision":1,"payload":{"prompt":"A coefficient of correlation of r = -0.9 indicates:","options":["A strong positive relationship","No relationship","A strong negative relationship","A weak negative relationship"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The negative sign shows that as one variable rises the other falls, and a value of 0.9, close to 1, shows the relationship is strong. Option A ignores the negative sign, option B would need r close to 0, and option D would need a value much nearer to 0, such as -0.2."}},{"itemId":"6d89f955-f5d3-54ff-bce7-8e5cd36b20fc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c453e6fb-e8fe-5351-9be2-74d5551ea25a","sourceKey":"bank:BUA204:PQ-080","parentItemId":null,"revision":1,"payload":{"prompt":"In a normal distribution, approximately what percentage of observations fall within +/-1 standard deviation of the mean?","options":["50%","68%","95%","99.7%"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"By the empirical rule, about 68% of observations lie within one standard deviation either side of the mean. About 95% (C) lie within two standard deviations and about 99.7% (D) within three, while 50% (A) is the share on each side of the mean."}},{"itemId":"62c015ec-623e-5471-8b5a-5d40820f77d6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5aa45533-9791-5816-b173-b016d0147028","sourceKey":"bank:BUA204:PQ-081","parentItemId":null,"revision":1,"payload":{"prompt":"The coefficient of determination is given by:","options":["r","r squared","1/r","square root of r"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The coefficient of determination is r squared, which shows the proportion of the variation in y that is explained by x. The plain correlation coefficient r (A) measures strength and direction, while 1/r (C) and the square root of r (D) have no standard meaning here."}},{"itemId":"4b34271b-6fc2-5d2e-9b16-65767f17a46b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"be7930f4-1bbb-5f16-b785-b3b107f83d50","sourceKey":"bank:BUA204:PQ-082","parentItemId":null,"revision":1,"payload":{"prompt":"The Upper Control Limit on a standard control chart is typically set at:","options":["Mean + 1 standard deviation","Mean + 2 standard deviations","Mean + 3 standard deviations","Mean x 3"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Standard control charts set the UCL at the process mean plus three standard deviations, and the LCL at the mean minus three. Limits at one or two standard deviations (A and B) would flag too many false alarms, and multiplying the mean by 3 (D) is not how control limits work."}},{"itemId":"6c51c696-92e6-5acc-8dd8-556de5bb6086","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b33083db-474b-57a3-a316-73575559e2c9","sourceKey":"bank:BUA204:PQ-083","parentItemId":null,"revision":1,"payload":{"prompt":"If two data sets have the same mean but different standard deviations, the set with the larger standard deviation is:","options":["More consistent","Less variable","More spread out / less consistent","Identical in spread"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"A larger standard deviation means the values are scattered further from the mean, so that data set is more spread out and less consistent. Options A and B describe the set with the smaller standard deviation, and option D contradicts the different standard deviations."}},{"itemId":"a2b57c68-6d3a-5aaf-bf46-776b7f69aa74","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f95eab84-ebbd-5e27-a0b1-ecb585b1157b","sourceKey":"bank:BUA204:PQ-084","parentItemId":null,"revision":1,"payload":{"prompt":"The slope (b) in a simple linear regression equation represents:","options":["The y-intercept","The average rate of change in y for a one-unit change in x","The correlation coefficient","The total variation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"In y-hat = a + bx, the slope b shows how much y changes, on average, when x increases by one unit. The y-intercept (A) is a, the value of y when x is zero, and the correlation coefficient (C) is a separate measure, r."}},{"itemId":"275b8c90-b458-57d2-8473-8759639681ed","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2b7d3efd-0466-5a97-adb4-c1dc4217274b","sourceKey":"bank:BUA204:PQ-085","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a measure of dispersion?","options":["Range","Standard deviation","Mode","Variance"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The mode is the most frequently occurring value, so it is a measure of central tendency, not of spread. The range (A), standard deviation (B) and variance (D) all describe how widely the data are scattered."}},{"itemId":"114dac1d-d110-5578-9d8d-68e3d0a19abd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f3bec5d7-2d4d-51bd-ae54-842da466f0dc","sourceKey":"bank:BUA204:PQ-086","parentItemId":null,"revision":1,"payload":{"prompt":"A correlation coefficient of r = 0 suggests:","options":["A perfect positive relationship","A perfect negative relationship","No linear relationship","A strong relationship"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"An r of 0 means there is no linear relationship between the two variables. A perfect positive relationship (A) would be r = +1, a perfect negative one (B) would be r = -1, and a strong relationship (D) needs r close to +1 or -1."}},{"itemId":"26eca34c-e96a-51ee-86c1-5adede6b9958","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"90202668-7ce4-5376-91a0-ae4c4a417294","sourceKey":"bank:BUA204:PQ-087","parentItemId":null,"revision":1,"payload":{"prompt":"The mode of a data set is:","options":["The middle value","The average value","The most frequently occurring value","The largest value"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The mode is the value that occurs most often in a data set. The middle value (A) is the median, the average (B) is the mean, and the largest value (D) is the maximum."}},{"itemId":"78f64fc0-1d94-5969-b5d0-a01c61c93d35","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1ef76110-9e68-56de-ad23-b8875dc757c7","sourceKey":"bank:BUA204:PQ-088-a","parentItemId":null,"revision":1,"payload":{"prompt":"A company wants a single figure for the \"typical\" salary of its staff, but a few directors earn far more than everyone else. Which measure is most appropriate?","options":["Standard deviation","Mean","Range","Median"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The median is the middle value of the ranked salaries, so the few very high director salaries do not drag it upwards. The mean (B) would be pulled up by those extreme values, while the range (C) and standard deviation (A) measure spread rather than a typical value."}},{"itemId":"82aae428-4ea2-5f4f-ac57-77c33fe3ce5a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fc0b73bb-ccff-5226-a59f-cc4b2c7c63b7","sourceKey":"bank:BUA204:PQ-088-b","parentItemId":null,"revision":1,"payload":{"prompt":"For the data 5, 7, 7, 8, 9, 10, 40, which statement is correct (mean to 1 decimal place)?","options":["Mean = 12.3, median = 7, mode = 8","Mean = 8, median = 12.3, mode = 7","Mean = 12.3, median = 8, mode = 7","Mean = 7, median = 8, mode = 12.3"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The mean is 86 / 7 = 12.3, the median is the 4th of the 7 ranked values, which is 8, and the mode is 7 because it appears twice. The other options mix up the three measures; notice also that the outlier 40 pulls the mean above the median."}},{"itemId":"12422cc9-b3fd-5b38-873c-987c39914d2e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"61819a57-5588-5b9e-8eea-84b5101e4764","sourceKey":"bank:BUA204:PQ-089-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula gives the coefficient of variation (CV)?","options":["(Mean / Standard deviation) x 100%","(Variance / Mean) x 100%","(Range / Mean) x 100%","(Standard deviation / Mean) x 100%"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The coefficient of variation is the standard deviation expressed as a percentage of the mean, which measures relative dispersion and allows sets with different means or units to be compared. Option A turns the ratio upside down, while options B and C use variance or range instead of standard deviation."}},{"itemId":"fc3cf957-124f-582b-a831-714714911397","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a970e31a-5f09-5e15-9514-871430717afa","sourceKey":"bank:BUA204:PQ-089-b","parentItemId":null,"revision":1,"payload":{"prompt":"Investment A has a mean return of 20% with a standard deviation of 4%; Investment B has a mean return of 10% with a standard deviation of 3%. Using CV = (SD / mean) x 100%, which investment has the lower relative risk?","options":["Both carry equal relative risk","B, with a CV of 20% against 30% for A","B, because its standard deviation is lower","A, with a CV of 20% against 30% for B"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"CV for A = 4 / 20 x 100 = 20% and CV for B = 3 / 10 x 100 = 30%, so A has less risk per unit of return. Option C compares standard deviations only, which is misleading when the means differ, and option B swaps the two CVs."}},{"itemId":"0c1ce791-f594-538e-9aba-be7bd59eb88a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a51e423f-c422-57df-b90e-fc2df715c6ec","sourceKey":"bank:BUA204:PQ-090-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes correlation from regression analysis?","options":["Correlation proves causation, while regression does not","Both only measure the strength of a relationship and cannot be used for prediction","Regression measures the strength and direction of a relationship; correlation fits a line used for prediction","Correlation measures the strength and direction of a linear relationship; regression fits a line that can be used to predict one variable from the other"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Correlation gives a single number, r, describing how strong and in what direction a linear relationship is, while regression goes further by fitting a line such as y-hat = a + bx for prediction. Option C swaps the two, option B ignores the predictive use of regression, and correlation never proves causation (A)."}},{"itemId":"e8f4685d-445d-542f-be50-c366d370640f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f8f49f5e-adb7-54cf-a07b-169f0ed5fec6","sourceKey":"bank:BUA204:PQ-091-a","parentItemId":null,"revision":1,"payload":{"prompt":"According to the empirical rule, approximately what percentage of observations in a normal distribution lie within +/-2 standard deviations of the mean?","options":["95%","50%","99.7%","68%"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The empirical rule says about 68% of values lie within one standard deviation, about 95% within two, and about 99.7% within three. So 68% (D) and 99.7% (C) belong to one and three standard deviations, and 50% (B) is simply the half on each side of the mean."}},{"itemId":"d985a1ef-55ad-5bba-b8ee-d5a0345483e1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b24e02ac-7601-53e9-bf65-347d1ce48f1c","sourceKey":"bank:BUA204:PQ-091-b","parentItemId":null,"revision":1,"payload":{"prompt":"Test scores are normally distributed with a mean of 60 and a standard deviation of 5. Using the empirical rule, approximately what percentage of scores lie between 45 and 75?","options":["99.7%","50%","68%","95%"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"45 and 75 are each 15 marks, or 3 standard deviations, away from the mean of 60, and about 99.7% of values lie within +/-3 standard deviations. Option D would apply to 50-70 (two standard deviations), and option C to 55-65 (one standard deviation)."}},{"itemId":"8d2711b6-edc3-511a-921e-9cc3ee375503","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7468f59b-3f16-57fb-ae5e-76e2ce766929","sourceKey":"bank:BUA204:PQ-092-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a managerial use of a control chart?","options":["To detect when a production process has drifted outside acceptable limits","To compute the break-even point","To find the critical path of a project","To calculate the economic order quantity"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"A control chart plots measurements over time against upper and lower limits, so managers can spot when a process drifts out of control and separate random variation from real problems. EOQ (D), the critical path (C) and the break-even point (B) are found with other tools."}},{"itemId":"91a97b59-a830-5ac2-965b-d3e54da13b1c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"201cbf4c-2937-50fd-b448-cbb38116e10d","sourceKey":"bank:BUA204:PQ-093-a","parentItemId":null,"revision":1,"payload":{"prompt":"Ice-cream sales and drowning incidents are found to be strongly positively correlated. Which is the best explanation?","options":["Drowning incidents cause ice-cream sales to rise","A third variable, hot weather, increases both","Eating ice-cream causes drowning","The correlation coefficient must have been calculated wrongly"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Correlation measures association, not cause and effect; here hot weather is a lurking variable that pushes up both ice-cream sales and swimming, and so drownings. Options C and A wrongly assume one variable causes the other, and a genuine correlation can exist without either causing the other, so the calculation need not be wrong (D)."}},{"itemId":"141e8bc1-5c58-5eaf-ad3b-a16e47ddb728","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7f8ab8dc-a246-57f8-9217-1ff6427ccb67","sourceKey":"bank:BUA204:PQ-094-a","parentItemId":null,"revision":1,"payload":{"prompt":"For the data 14, 9, 21, 17, 11, 19, what are the range and the mean (to 2 decimal places)?","options":["Range = 12; mean = 15.17","Range = 21; mean = 15.17","Range = 12; mean = 18.20","Range = 30; mean = 15.17"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Range = highest - lowest = 21 - 9 = 12, and the mean = 91 / 6 = 15.17. Option B gives the highest value instead of the range, option C divides the total by 5 instead of 6, and option D adds the highest and lowest values instead of subtracting."}},{"itemId":"55b62e18-e48f-5459-98b9-14e6ffb45aa9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"57c068e1-e86f-56ed-a6ad-d424f083bd85","sourceKey":"bank:BUA204:PQ-095-a","parentItemId":null,"revision":1,"payload":{"prompt":"In the regression line y-hat = a + bx, what does a represent?","options":["The intercept: the predicted value of y when x = 0","The predicted value of the dependent variable","The slope: the change in y for a one-unit change in x","The value of the independent variable"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The constant a is the intercept, where the line crosses the y-axis, giving the predicted y when x is zero. The slope is b (C), the independent variable is x (D), and the predicted value of the dependent variable is y-hat itself (B)."}},{"itemId":"2da2c5d9-0a94-5428-a14f-9009b191d378","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"980fad00-6a29-5a29-ae04-d919d8d0e03c","sourceKey":"bank:BUA204:PQ-095-b","parentItemId":null,"revision":1,"payload":{"prompt":"A regression line is y-hat = 19.5 + 2.93x, where x is advertising spend and y-hat is predicted sales (both in N'000). What are the predicted sales when x = 20?","options":["22.4 (N22,400)","58.6 (N58,600)","78.1 (N78,100)","448.6 (N448,600)"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Substitute x = 20: y-hat = 19.5 + 2.93 x 20 = 19.5 + 58.6 = 78.1, or about N78,100. Option B forgets to add the intercept, option A just adds a and b, and option D multiplies (a + b) by 20."}},{"itemId":"371fd942-c813-5b9b-aa2f-ba21f7b4ac69","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9d00f138-edfd-55e4-b918-ff76f89ca531","sourceKey":"bank:BUA204:PQ-096-a","parentItemId":null,"revision":1,"payload":{"prompt":"The test scores of 8 management trainees are 62, 75, 58, 80, 70, 65, 90, 72. What is the mean score?","options":["74.0","81.7","71.5","71.0"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The scores add up to 572, and 572 / 8 = 71.5. Option D is the median (the average of the 4th and 5th ranked values, 70 and 72), option A is halfway between the lowest and highest scores, and option B divides by 7 instead of 8."}},{"itemId":"661a4622-9ab1-5ccf-8597-ba8212e935ae","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fc44226e-4730-5bbb-bc7d-ca147fde331e","sourceKey":"bank:BUA204:PQ-096-b","parentItemId":null,"revision":1,"payload":{"prompt":"The test scores of 8 trainees are 62, 75, 58, 80, 70, 65, 90, 72. Treating them as a population (variance = sum of squared deviations / n), what is the variance?","options":["9.64","93.00","744.00","106.29"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The mean is 71.5, the squared deviations add up to 744, and the population variance = 744 / 8 = 93.00. Option D divides by n - 1 = 7 (the sample formula), option A is the standard deviation, and option C is the sum of squared deviations before dividing."}},{"itemId":"a9c74a32-de4f-5be1-974c-45d430fcd705","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f53dcaed-1cea-5bce-9054-1b7bce17b5c6","sourceKey":"bank:BUA204:PQ-096-c","parentItemId":null,"revision":1,"payload":{"prompt":"The test scores of 8 trainees are 62, 75, 58, 80, 70, 65, 90, 72. Treating them as a population (divide by n), what is the standard deviation to 2 decimal places?","options":["93.00","9.64","10.31","3.10"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The population variance is 744 / 8 = 93, and the standard deviation is the square root of 93, which is 9.64. Option C uses the sample formula (dividing by 7), option A is the variance itself, and option D takes the square root twice."}},{"itemId":"52fb7ad0-9111-5c55-96cc-8afbdedaf4cf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"437fb028-389a-5c42-9d58-dcec4701a151","sourceKey":"bank:BUA204:PQ-097-a","parentItemId":null,"revision":1,"payload":{"prompt":"For 6 sales representatives, years of experience (x) and monthly sales (y, N'000) are: (1, 28), (2, 35), (3, 40), (5, 52), (6, 58), (8, 70). Using b = [n(sum xy) - (sum x)(sum y)] / [n(sum x^2) - (sum x)^2], what is the slope b to 2 decimal places?","options":["0.17","22.43","9.97","5.94"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"With sum x = 25, sum y = 283, sum xy = 1,386 and sum x^2 = 139, b = (6 x 1,386 - 25 x 283) / (6 x 139 - 625) = 1,241 / 209 = 5.94. Option C simply divides sum xy by sum x^2, option A turns the fraction upside down, and option B is the intercept a, not the slope."}},{"itemId":"d323b4c2-4ef7-5ea3-a539-7732e1797204","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8d69938a-2ae4-5fc9-8552-196a5ea1bdf3","sourceKey":"bank:BUA204:PQ-097-b","parentItemId":null,"revision":1,"payload":{"prompt":"For 6 sales representatives, years of experience (x) and monthly sales (y, N'000) give the regression line y-hat = 22.43 + 5.94x. What are the predicted monthly sales for a representative with 10 years of experience (to 1 decimal place)?","options":["70.0 (about N70,000)","106.6 (about N106,600)","59.4 (about N59,400)","81.8 (about N81,800)"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Substitute x = 10: y-hat = 22.43 + 5.94 x 10 = 22.43 + 59.4 = 81.8, or about N81,800. Option C leaves out the intercept, option B wrongly uses the mean of y (47.17) in place of the intercept, and option A is just the observed sales of the representative with 8 years."}},{"itemId":"65918355-998b-506f-91fd-ae9e6c88da8f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3d70e16b-ad9a-5cfb-aae4-d4f8e7175428","sourceKey":"bank:BUA204:PQ-098-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a main property of the normal distribution?","options":["It is a symmetrical, bell-shaped curve with mean, median and mode equal at the centre","The total area under the curve equals 2","It is skewed to the right, so the mean is greater than the median","The mode lies at the far left of the curve"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The normal curve is symmetrical and bell-shaped, so the mean, median and mode all sit together at the centre. A right-skewed curve (C) is not normal, the total area under the curve is 1 or 100% (B), and the mode is at the centre, not the edge (D)."}},{"itemId":"033972ba-5046-5c55-8b12-d584e5aa20bb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b6c7a97b-dcbb-5272-8892-2a4cc7b5640b","sourceKey":"bank:BUA204:PQ-098-b","parentItemId":null,"revision":1,"payload":{"prompt":"The total area under a normal distribution curve is equal to:","options":["0.68","1 (that is, 100%)","0.5","It depends on the standard deviation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The area under the normal curve represents all possible observations, so it always totals 1, or 100%. Half of that, 0.5 (C), lies on each side of the mean, 0.68 (A) is the area within one standard deviation, and the total does not change with the standard deviation (D), which only alters the shape."}},{"itemId":"ef4b43da-1c3d-5a3b-8253-d9058eb76a0d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4611d93a-13da-51f4-8b42-31ec5faf035c","sourceKey":"bank:BUA204:PQ-099-a","parentItemId":null,"revision":1,"payload":{"prompt":"Team A's weekly sales (N'000) are 50, 52, 48, 51, 49 and Team B's are 30, 60, 70, 40, 50; both average 50. Using population standard deviation (divide by n), which statement is correct?","options":["Team A has a standard deviation of about 1.41, so it is more consistent than Team B","Team B has a standard deviation of about 1.41, so it is more consistent than Team A","Team A has a standard deviation of about 14.14, so it is less consistent than Team B","Both teams are equally consistent because they have the same mean"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Team A's squared deviations add up to 10, so its SD is the square root of 10 / 5, about 1.41, while Team B's add up to 1,000, giving an SD of about 14.14. So Team A is far more consistent; options B and C swap the figures, and option D wrongly assumes that the same mean means the same spread."}},{"itemId":"544069ef-607d-5b29-80cf-92149745789b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f3bdd345-b93c-5130-b7ba-589e752b07a3","sourceKey":"bank:BUA204:PQ-099-b","parentItemId":null,"revision":1,"payload":{"prompt":"Team B's weekly sales (N'000) are 30, 60, 70, 40, 50, with a mean of 50 and a population standard deviation of about 14.14. Using CV = (SD / mean) x 100%, what is Team B's coefficient of variation (to 1 decimal place)?","options":["3.5%","28.3%","14.1%","2.8%"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"CV = 14.14 / 50 x 100 = 28.3%, so the variation is a little over a quarter of the average weekly sales. Option D is Team A's CV (1.41 / 50), option C is just the standard deviation, and option A divides the mean by the standard deviation instead."}},{"itemId":"79ae0b74-2904-5edd-b34c-b26f98588865","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ff002fbd-b621-5ab4-af24-02a9b5030e20","sourceKey":"bank:BUA204:PQ-100-a","parentItemId":null,"revision":1,"payload":{"prompt":"A filling process has a mean of 50 mm and a standard deviation of 0.4 mm. Using control limits of mean +/- 3 standard deviations, what are the UCL and LCL?","options":["UCL = 51.2 mm; LCL = 50.0 mm","UCL = 51.2 mm; LCL = 48.8 mm","UCL = 50.4 mm; LCL = 49.6 mm","UCL = 50.8 mm; LCL = 49.2 mm"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"UCL = 50 + 3 x 0.4 = 51.2 mm and LCL = 50 - 3 x 0.4 = 48.8 mm. Option D uses 2 standard deviations, option C uses only 1, and option A wrongly puts the lower limit at the mean."}},{"itemId":"c27b2672-7940-589d-b384-67feec85b03d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"296f2383-0419-5bd3-845d-2920c2a73daf","sourceKey":"bank:BUA204:PQ-100-b","parentItemId":null,"revision":1,"payload":{"prompt":"On a control chart, a sample measurement falls above the Upper Control Limit. How should management interpret this?","options":["The control limits should simply be widened so the point fits","The process may be out of control because of a special cause, and should be investigated","The process is in statistical control, with only random variation present","The point should be ignored because it is above, not below, the limits"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Points within the limits suggest only random variation, but a point outside either limit signals that a special cause may be at work and the process should be investigated. Option C describes points inside the limits, widening the limits (A) would hide the problem, and points above the UCL matter just as much as those below the LCL (D)."}},{"itemId":"f5ebae0d-9db4-579f-8ea5-00830e98d378","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cca0ba90-21bd-5f3a-a055-9971388bf710","sourceKey":"bank:BUA204:PQ-101","parentItemId":null,"revision":1,"payload":{"prompt":"The critical path in a project network is:","options":["The path with the lowest total cost","The longest path through the network","The shortest path through the network","The path with the most activities"],"correctOption":1,"section":"Operational Modelling","explanation":"The critical path is the longest path through the network, and it sets the minimum time needed to complete the project, so any delay on it delays the whole project. The shortest path (C) has spare time (float), cost (A) does not define the critical path, and the path with the most activities (D) is not necessarily the longest in time."}},{"itemId":"b770c42b-fbe3-51e6-af98-b318c0ad6523","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4ed8cb2b-590e-59a7-b46d-5b9cfdecab7f","sourceKey":"bank:BUA204:PQ-102","parentItemId":null,"revision":1,"payload":{"prompt":"Total float on the critical path is always:","options":["Positive","Negative","Zero","Equal to project duration"],"correctOption":2,"section":"Operational Modelling","explanation":"Activities on the critical path have no spare time, so their total float is zero; delaying any of them delays the whole project. Positive float (A) belongs to non-critical activities, and float is never equal to the whole project duration (D)."}},{"itemId":"0ee2d2f2-ce66-52db-b446-82b5f93fbb2a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c7309705-c5df-58dc-a256-5a159ed85b44","sourceKey":"bank:BUA204:PQ-103","parentItemId":null,"revision":1,"payload":{"prompt":"The EOQ formula is:","options":["square root of (2DS/H)","2DS/H","(D/S) x H","square root of (DH/2S)"],"correctOption":0,"section":"Operational Modelling","explanation":"EOQ = square root of (2DS / H), where D is annual demand, S is the ordering cost per order and H is the holding cost per unit per year. Option B forgets the square root, and option D turns the terms inside the square root the wrong way round."}},{"itemId":"b97c043d-913c-5a18-ae4e-43d7be7205b3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4da5aa51-6020-5ace-bf9a-23c794881121","sourceKey":"bank:BUA204:PQ-104","parentItemId":null,"revision":1,"payload":{"prompt":"In the EOQ model, S represents:","options":["Annual demand","Holding cost per unit","Ordering cost per order","Safety stock"],"correctOption":2,"section":"Operational Modelling","explanation":"In EOQ = square root of (2DS / H), S is the cost of placing one order, such as processing and delivery charges. Annual demand (A) is D, the holding cost per unit (B) is H, and safety stock (D) is not part of the basic EOQ formula."}},{"itemId":"a9a580b8-3dfb-5d75-ab0b-a95b2dec8482","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"41dd0e8f-98aa-5d31-b85b-0bd5fa4e76e6","sourceKey":"bank:BUA204:PQ-105","parentItemId":null,"revision":1,"payload":{"prompt":"In the basic EOQ model, when the order quantity equals the Economic Order Quantity, total annual ordering cost:","options":["Is always zero","Always equals total annual holding cost","Is always greater than holding cost","Has no relationship with holding cost"],"correctOption":1,"section":"Operational Modelling","explanation":"The EOQ is the point where the falling ordering-cost curve meets the rising holding-cost curve, so the two annual costs are exactly equal there and their total is lowest. This equality is a handy check on any EOQ calculation. Option C would mean you are ordering too often (too small a quantity), and Option A is impossible because every order placed costs something."}},{"itemId":"73ab0db6-1f17-59df-9c0a-8c51b617acae","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bf53aea6-6f71-596d-bbe9-1a80da141895","sourceKey":"bank:BUA204:PQ-106","parentItemId":null,"revision":1,"payload":{"prompt":"The Reorder Point (ROP) is calculated as:","options":["EOQ / 2","Daily demand x Lead time","Annual demand / EOQ","Holding cost x Lead time"],"correctOption":1,"section":"Operational Modelling","explanation":"The reorder point is the stock level at which a new order must be placed so that stock lasts until delivery, so it equals daily demand multiplied by the lead time in days. Option C gives the number of orders per year, and Option A gives the average inventory held under EOQ, not the reorder level."}},{"itemId":"833458de-b9b9-5c66-aee9-0b7981b89353","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"58f7e937-29c9-5125-91f9-97d67de0bb16","sourceKey":"bank:BUA204:PQ-107","parentItemId":null,"revision":1,"payload":{"prompt":"In linear programming, the objective function is:","options":["Always a constraint","The function to be maximised or minimised","Always non-linear","Irrelevant to the solution"],"correctOption":1,"section":"Operational Modelling","explanation":"The objective function states the goal of the model, such as maximising profit or minimising cost, in terms of the decision variables. Option A confuses it with the constraints, which limit the resources available, and Option C is wrong because in linear programming the objective function is linear by definition."}},{"itemId":"2cacf3bc-38b4-5cd9-b221-96426e7c5e2d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"235df816-5736-579c-a4f2-8d4742ced693","sourceKey":"bank:BUA204:PQ-108","parentItemId":null,"revision":1,"payload":{"prompt":"Non-negativity restrictions in linear programming require that:","options":["Decision variables can be any real number","Decision variables must be <= 0","Decision variables must be >= 0","Only the objective function must be positive"],"correctOption":2,"section":"Operational Modelling","explanation":"Non-negativity restrictions say each decision variable must be zero or positive, because a firm cannot produce a negative number of units. Option B reverses the sign, and Option A would allow meaningless negative production quantities."}},{"itemId":"ab49ac5c-fd9d-5411-84c3-5ac92a8b913a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2612ec33-9c9d-53c8-9f24-0e5d25ea92b6","sourceKey":"bank:BUA204:PQ-109","parentItemId":null,"revision":1,"payload":{"prompt":"Which technique would best help a project manager determine the minimum time to complete a multi-activity production schedule?","options":["EOQ","Linear programming","Critical Path Method","Regression analysis"],"correctOption":2,"section":"Operational Modelling","explanation":"The Critical Path Method maps all activities and their dependencies and finds the longest path through the network, which is the minimum time needed to finish the whole project. Option B, linear programming, is for allocating limited resources to maximise or minimise an objective, and Option A, EOQ, is for inventory ordering decisions."}},{"itemId":"6c2dc539-2c93-54c3-a744-e752d3927b27","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"414baae2-7c43-5491-9a0e-cf18b8bbd2d2","sourceKey":"bank:BUA204:PQ-110","parentItemId":null,"revision":1,"payload":{"prompt":"An activity with zero total float lies on the:","options":["Shortest path","Critical path","Any random path","None of the paths"],"correctOption":1,"section":"Operational Modelling","explanation":"Float is the time an activity can be delayed without delaying the project, and activities on the critical path have none, so zero float marks a critical activity. Option A is wrong because the shortest path is the one with the most spare time, not the least."}},{"itemId":"4d14ba9e-a5ca-56ca-a7f5-dfa9176e3740","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a20c3f11-d101-580a-9ac4-1891b6d7c3ac","sourceKey":"bank:BUA204:PQ-111","parentItemId":null,"revision":1,"payload":{"prompt":"Holding (carrying) cost in inventory management includes:","options":["Cost of placing an order","Cost of storage, insurance, and spoilage","Selling price of the item","Cost of production labour"],"correctOption":1,"section":"Operational Modelling","explanation":"Holding cost is the cost of keeping stock, such as warehousing, insurance, spoilage and the money tied up in inventory. Option A is the ordering cost, which is the other cost the EOQ model balances, while Options C and D are not inventory carrying costs."}},{"itemId":"dcf719d3-0231-5e38-a71f-ad6d351b300a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4db02dc5-f03f-546d-83e9-5d519221be6b","sourceKey":"bank:BUA204:PQ-112","parentItemId":null,"revision":1,"payload":{"prompt":"A feasible region in linear programming represents:","options":["All infeasible solutions","The set of all solutions that satisfy every constraint","Only the optimal solution","The objective function line"],"correctOption":1,"section":"Operational Modelling","explanation":"The feasible region is the area on the graph containing every combination of decision variables that satisfies all the constraints at once, including non-negativity. Option C is too narrow: the optimal solution is just one point (usually a corner point) inside this region, and Option D is a separate line used to find that point."}},{"itemId":"9c63b01c-faae-5609-9584-51adc23220c8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"27982fdf-16ec-528f-b675-a1a9d22edba8","sourceKey":"bank:BUA204:PQ-113-a","parentItemId":null,"revision":1,"payload":{"prompt":"In network analysis (CPM), the critical path is:","options":["The path with the largest number of activities","The shortest path through the project network","The longest path through the project network","The path made up of the cheapest activities"],"correctOption":2,"section":"Operational Modelling","explanation":"The critical path is the longest path through the network, and its length is the minimum time in which the whole project can be completed. Option B is the opposite, since the shortest path usually has spare time (float), and Option A is wrong because a path with many short activities can still be shorter in total time."}},{"itemId":"b04fe063-e3d6-593b-8387-37e40d75a620","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1b74536e-83a6-5ff1-a7a4-c907eb3b2540","sourceKey":"bank:BUA204:PQ-113-b","parentItemId":null,"revision":1,"payload":{"prompt":"An activity on the critical path of a production project is delayed by 2 days, and nothing else changes. What happens to the project completion date?","options":["It is unchanged, because the activity has float to absorb the delay","It is delayed by 4 days","It is brought forward by 2 days","It is delayed by 2 days"],"correctOption":3,"section":"Operational Modelling","explanation":"Critical activities have zero float, so any delay to one of them pushes the whole project back by the same amount, here 2 days. This is why a production manager monitors critical-path activities most closely. Option A would only be true for a non-critical activity with enough float."}},{"itemId":"376d7ea6-6d43-5916-845a-e4dc8b83b4cd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"879a08bb-5b52-5749-9bba-15ae4fc4141c","sourceKey":"bank:BUA204:PQ-114-a","parentItemId":null,"revision":1,"payload":{"prompt":"The Economic Order Quantity (EOQ) formula is (D = annual demand, S = ordering cost per order, H = annual holding cost per unit):","options":["EOQ = sqrt(DS / 2H)","EOQ = 2DS / H","EOQ = sqrt(2DH / S)","EOQ = sqrt(2DS / H)"],"correctOption":3,"section":"Operational Modelling","explanation":"The EOQ is the square root of twice annual demand times the ordering cost per order, divided by the annual holding cost per unit. Option C swaps S and H, and Option B forgets the square root, which would give a number far too large."}},{"itemId":"a70d71fe-2c48-57c0-839e-1f5622a68bcf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7c663ed6-0808-562d-9c8d-c9f71ff32260","sourceKey":"bank:BUA204:PQ-114-b","parentItemId":null,"revision":1,"payload":{"prompt":"In the EOQ formula EOQ = sqrt(2DS / H), the symbol H stands for:","options":["The lead time in hours","The annual holding cost per unit","The holding cost per order placed","The total annual holding cost for all stock"],"correctOption":1,"section":"Operational Modelling","explanation":"H is the cost of holding one unit in stock for a year, covering items like storage, insurance and spoilage. Option D is the total holding cost, which is (Q/2) x H and is an output of the model rather than an input, while Option C confuses holding cost with ordering cost, which is charged per order."}},{"itemId":"83d7a17c-6534-553f-bf89-b0a5c4202cde","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"de200d4b-ec8e-5eb4-8447-0ab5c44a82df","sourceKey":"bank:BUA204:PQ-115-a","parentItemId":null,"revision":1,"payload":{"prompt":"In network analysis, total float (slack) of an activity is:","options":["The total duration of the whole project","The amount of time the activity can be delayed without delaying the overall project completion date","The time between placing an order and receiving it","The earliest time at which the activity can start"],"correctOption":1,"section":"Operational Modelling","explanation":"Total float is the spare time an activity has: it can be delayed by up to this amount without pushing back the project finish date, and it is zero on the critical path. Option C describes lead time in inventory, and Option D describes the Earliest Start Time, which is used to calculate float but is not float itself."}},{"itemId":"4277bcd4-864e-5648-bf06-445fd3e13c40","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a1c0e9f3-f90d-5f55-8f61-df49e42355e6","sourceKey":"bank:BUA204:PQ-115-b","parentItemId":null,"revision":1,"payload":{"prompt":"Using Total Float = Latest Finish Time (LFT) - Earliest Finish Time (EFT), an activity with EFT = day 9 and LFT = day 12 has a total float of:","options":["3 days","12 days","21 days","0 days"],"correctOption":0,"section":"Operational Modelling","explanation":"Total float = LFT - EFT = 12 - 9 = 3 days, so this activity can slip by up to 3 days without delaying the project. Option C wrongly adds the two times, and Option D would apply only if the activity were on the critical path."}},{"itemId":"3a13f44b-a358-5f68-b936-a30117a954e4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"58e355ee-0500-5354-af84-5670143067b2","sourceKey":"bank:BUA204:PQ-116","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three components of a linear programming model?","options":["The constraints","The non-negativity restrictions","The reorder point","The objective function"],"correctOption":2,"section":"Operational Modelling","explanation":"A linear programming model is made up of an objective function (what to maximise or minimise), constraints (limits on resources) and non-negativity restrictions (variables cannot be negative). The reorder point belongs to inventory control under the EOQ model, not to linear programming."}},{"itemId":"a0fb5457-12cc-541e-ac5f-800852b9b2e9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2a4fc9a4-accc-52f1-9edf-b0a044810290","sourceKey":"bank:BUA204:PQ-117-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a cost of holding TOO LITTLE inventory?","options":["Greater spoilage of stored items","Stockouts, leading to lost sales and production stoppages","Higher storage and insurance costs","Cash tied up in unsold stock"],"correctOption":1,"section":"Operational Modelling","explanation":"Holding too little stock risks running out, which means lost sales, disappointed customers and stopped production lines. Options C, D and A are all costs of holding too MUCH inventory, which is the other side of the trade-off the EOQ balances."}},{"itemId":"b6f7f63e-3bdf-5001-a2af-87c93c7a4363","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d844df45-f118-55e3-b3fa-f700d661910a","sourceKey":"bank:BUA204:PQ-117-b","parentItemId":null,"revision":1,"payload":{"prompt":"The EOQ model finds the order quantity that minimises the combined total of:","options":["Ordering cost and holding cost","Lead time and daily demand","Selling price and variable cost","Fixed cost and total revenue"],"correctOption":0,"section":"Operational Modelling","explanation":"Larger orders cut ordering cost but raise holding cost, so the EOQ balances these two competing costs to make their total as low as possible. Option C relates to contribution margin, Option D to break-even analysis, and Option B gives the reorder point rather than the order quantity."}},{"itemId":"d8e50ea3-e03e-5f88-b1e8-862e5296d2e4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"67bc2fdb-f392-5487-a01a-aff6568d7c74","sourceKey":"bank:BUA204:PQ-118-a","parentItemId":null,"revision":1,"payload":{"prompt":"A shop uses 40 units of a product per day and the supplier's lead time is 5 days. Using ROP = Daily demand x Lead time, what is the reorder point?","options":["200 units","35 units","8 units","45 units"],"correctOption":0,"section":"Operational Modelling","explanation":"ROP = 40 units per day x 5 days = 200 units, so a new order should be placed when stock falls to 200 units. Option C divides instead of multiplying, and Option D simply adds the two figures."}},{"itemId":"b0a08925-2872-5b34-9994-bdca7931e019","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0b536cc9-6f25-5ddd-a8c8-38bcb4547b1d","sourceKey":"bank:BUA204:PQ-118-b","parentItemId":null,"revision":1,"payload":{"prompt":"Why is lead time part of the reorder point calculation?","options":["Stock on hand must be enough to cover demand during the period between placing an order and receiving it","Lead time determines the ordering cost per order","Lead time is needed to calculate the EOQ itself","Lead time determines the annual holding cost per unit"],"correctOption":0,"section":"Operational Modelling","explanation":"The reorder point is set so that the stock left when you order will last until the new delivery arrives, so the waiting time (lead time) multiplied by daily usage gives the level needed. Option C is wrong because the basic EOQ formula uses only D, S and H, not lead time."}},{"itemId":"9097a5ca-b6d4-52cf-809f-2972578edc22","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a0946475-3789-5622-8013-f3266fd55335","sourceKey":"bank:BUA204:PQ-119","parentItemId":null,"revision":1,"payload":{"prompt":"In a linear programming model for a factory, which of the following is a CONSTRAINT rather than the objective function?","options":["Minimise total cost C = 500x + 700y","Maximise profit Z = 2,000x + 1,800y","Machine time: 4x + 2y <= 80 hours","Maximise contribution Z = 30x + 45y"],"correctOption":2,"section":"Operational Modelling","explanation":"A constraint is a limit on resources, such as the 80 available machine hours, and it restricts which values of the decision variables are possible. Options B, A and D each state something to be maximised or minimised, which is what an objective function does."}},{"itemId":"a65f8f0c-d230-5bcf-983b-fe6513aebae5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8712906f-bc40-5882-ac31-7e2a1886b506","sourceKey":"bank:BUA204:PQ-120","parentItemId":null,"revision":1,"payload":{"prompt":"The basic EOQ model assumes demand is known and constant. If demand actually fluctuates significantly, what is the practical implication?","options":["Ordering cost will always exceed holding cost, so no orders should be placed","The EOQ automatically adjusts and remains exactly optimal","Holding cost becomes zero","The basic EOQ may lead to stockouts or excess stock, so safety stock or a more dynamic inventory model should be used"],"correctOption":3,"section":"Operational Modelling","explanation":"The EOQ formula is derived for steady, predictable usage, so when demand swings the fixed order quantity can leave the firm short in busy periods or overstocked in slow ones. Adding safety stock or using a model that allows for variable demand protects against this. Option B is wrong because the basic formula has no mechanism for adjusting to changing demand."}},{"itemId":"e65a9f0c-3149-50b9-8aaa-806548e79ff9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cf820727-3989-5cf1-add1-68902af940f2","sourceKey":"bank:BUA204:PQ-121-a","parentItemId":null,"revision":1,"payload":{"prompt":"A project has activities A (no predecessor, 4 days), B (no predecessor, 6 days), C (after A, 5 days), D (after B, 3 days) and E (after both C and D, 4 days). What is the total project duration?","options":["9 days","22 days","10 days","13 days"],"correctOption":3,"section":"Operational Modelling","explanation":"The two paths are A-C-E = 4 + 5 + 4 = 13 days and B-D-E = 6 + 3 + 4 = 13 days, and the project takes as long as the longest path, so 13 days. Option B adds every activity as if they ran one after another, ignoring that A-C and B-D run in parallel."}},{"itemId":"a80d5ca4-018d-53cf-852d-fb3ab43ca455","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"70a1654b-dc63-57e3-a6de-521556c6ba29","sourceKey":"bank:BUA204:PQ-121-b","parentItemId":null,"revision":1,"payload":{"prompt":"A project has activities A (no predecessor, 4 days), B (no predecessor, 6 days), C (after A, 5 days), D (after B, 3 days) and E (after both C and D, 4 days). Which path(s) are critical?","options":["Only A-C-E","Neither, because the two paths are of equal length","Only B-D-E","Both A-C-E and B-D-E"],"correctOption":3,"section":"Operational Modelling","explanation":"Both paths take 13 days, which is the project duration, so both have zero float and both are critical. A delay on any activity on either path would delay the project. Option B is wrong because equal longest paths do not cancel out; a network can have more than one critical path."}},{"itemId":"ba55121d-5f0c-5c9d-89a0-948518e5ffb2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"76bacb07-5566-575f-a8fb-54f2638ffcc8","sourceKey":"bank:BUA204:PQ-122-a","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket sells 9,600 units of a product a year. Ordering cost is N750 per order, annual holding cost is N20 per unit, lead time is 8 days and the supermarket operates 300 days a year. What is the EOQ, to the nearest whole unit?","options":["1,200 units","23 units","849 units","600 units"],"correctOption":2,"section":"Operational Modelling","explanation":"EOQ = sqrt(2 x 9,600 x 750 / 20) = sqrt(720,000) = 848.5, which rounds to 849 units. Option D leaves out the 2 in the formula, and Option B swaps the ordering and holding costs."}},{"itemId":"d6892643-939a-5a19-a61a-22e8e3489137","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"35f90c0c-821e-5584-b282-95626567295c","sourceKey":"bank:BUA204:PQ-122-b","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket sells 9,600 units of a product a year. Ordering cost is N750 per order, annual holding cost is N20 per unit, lead time is 8 days and the supermarket operates 300 days a year. What is the total annual inventory cost (ordering cost + holding cost) at the EOQ, to the nearest naira?","options":["N16,971","N12,000","N33,941","N8,485"],"correctOption":0,"section":"Operational Modelling","explanation":"At the EOQ of about 848.5 units, ordering cost = (9,600 / 848.5) x 750 = about N8,485 and holding cost = (848.5 / 2) x 20 = about N8,485, giving a total of about N16,971. Option D counts only one of the two equal components, and Option C doubles the correct total."}},{"itemId":"29f74321-3d5d-540e-88fb-dfb4a32cded0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d9ee3d74-1a3d-5e80-aff5-93f8d5f9b932","sourceKey":"bank:BUA204:PQ-122-c","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket sells 9,600 units of a product a year. Ordering cost is N750 per order, annual holding cost is N20 per unit, lead time is 8 days and the supermarket operates 300 days a year. What is the reorder point?","options":["213 units","256 units","32 units","300 units"],"correctOption":1,"section":"Operational Modelling","explanation":"Daily demand = 9,600 / 300 = 32 units, so the reorder point = 32 x 8 days = 256 units. Option C is just the daily demand, and Option A wrongly uses 360 working days instead of 300."}},{"itemId":"ca8ce7ae-8ff1-56fa-99d6-62fae6fd982c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e4685140-3495-512f-bc4d-7fedbd3c6ec6","sourceKey":"bank:BUA204:PQ-123-a","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer makes products P and Q. Each P needs 4 machine hours and 2 labour hours; each Q needs 2 machine hours and 3 labour hours. Weekly capacity is 80 machine hours and 60 labour hours. Profit is N2,000 per P and N1,800 per Q. Which constraint correctly represents machine time?","options":["4P + 2Q >= 80","4P + 2Q <= 80","4P + 3Q <= 80","2P + 3Q <= 80"],"correctOption":1,"section":"Operational Modelling","explanation":"Each P uses 4 machine hours and each Q uses 2, and total use cannot exceed the 80 hours available, so 4P + 2Q <= 80. Option A reverses the inequality, which would force the firm to use at least 80 hours, and Option D uses the labour coefficients by mistake."}},{"itemId":"cea0ffa7-b2f6-5a3b-b9e7-f4f7aff783cb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"87ebfdc1-3cfd-55fc-8585-27a8e3ddf099","sourceKey":"bank:BUA204:PQ-123-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer makes products P and Q. Each P needs 4 machine hours and 2 labour hours; each Q needs 2 machine hours and 3 labour hours. Weekly capacity is 80 machine hours and 60 labour hours. Profit is N2,000 per P and N1,800 per Q. Using the corner-point method, which production mix maximises weekly profit?","options":["P = 20, Q = 0, giving N40,000","P = 10, Q = 15, giving N47,000","P = 15, Q = 10, giving N48,000","P = 0, Q = 20, giving N36,000"],"correctOption":2,"section":"Operational Modelling","explanation":"Solving 4P + 2Q = 80 and 2P + 3Q = 60 together gives P = 15 and Q = 10, and profit there is 2,000(15) + 1,800(10) = N48,000, higher than the other corners (N40,000 and N36,000). Option B is not even feasible, because it needs 2(10) + 3(15) = 65 labour hours, more than the 60 available."}},{"itemId":"13572c39-52a0-5272-8fc4-45b196dab7e6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b10e5090-02f6-5932-8a8a-1c3c8523e508","sourceKey":"bank:BUA204:PQ-124","parentItemId":null,"revision":1,"payload":{"prompt":"How does network analysis (CPM/PERT) help a manager manage bottlenecks in a complex production schedule?","options":["It identifies the zero-float critical activities to monitor most closely, while non-critical activities can be rescheduled within their float without delaying completion","It calculates the economic order quantity for each activity's materials","It removes the need to monitor any activities once the network is drawn","It guarantees that no activity in the project will be delayed"],"correctOption":0,"section":"Operational Modelling","explanation":"By finding the critical path, network analysis shows which activities are the true bottlenecks, so management can focus attention and resources there, while float on other activities gives room to re-sequence them safely. Option D overstates it: the technique highlights delay risk but cannot prevent delays, and Option B describes the EOQ model."}},{"itemId":"57953254-9fa7-59af-b196-115445922671","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9594e4e6-6eae-5024-9cb3-52e977188c58","sourceKey":"bank:BUA204:PQ-125-a","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an assumption of the basic EOQ model?","options":["Quantity discounts are available for large orders","Ordering and holding costs are constant","Lead time is known","Demand is known and constant"],"correctOption":0,"section":"Operational Modelling","explanation":"The basic EOQ model assumes known, constant demand, constant ordering and holding costs, a known lead time and no quantity discounts. Allowing quantity discounts requires an extended version of the model, so Option A is the one that does not belong."}},{"itemId":"83531f1f-c1af-578e-8a43-0d7d3eb68c74","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"78c60e46-ec71-58ff-808b-5f2542c2cf6b","sourceKey":"bank:BUA204:PQ-125-b","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian importer finds that delivery lead times are unreliable because of port congestion. Which adaptation of the basic EOQ approach is most appropriate?","options":["Carry safety stock in addition to the stock needed to cover normal lead-time demand","Double the holding cost in the EOQ formula","Set the reorder point to zero","Ignore lead time and order only once a year"],"correctOption":0,"section":"Operational Modelling","explanation":"When lead times are uncertain, keeping safety stock gives a buffer so that a late delivery does not cause a stockout. Option C would make stockouts almost certain, because the new order would only be placed when shelves are already empty."}},{"itemId":"3b0acc71-3ea6-540e-af2b-f238c7a109ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2bb15e91-8d3c-5e86-ba3e-05c51a06c687","sourceKey":"bank:BUA204:PQ-126","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making under risk differs from decision-making under uncertainty in that, under risk:","options":["Outcomes are guaranteed","Probabilities of states of nature are known or estimable","No alternatives exist","Only one state of nature is possible"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under risk, the decision-maker can attach probabilities to each possible state of nature, which allows tools like Expected Monetary Value. Option A describes decision-making under certainty, and under uncertainty no such probabilities are available."}},{"itemId":"cb19834e-2982-5467-b5de-11cec1746de1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4002042c-2636-584b-be2d-d2cc3009023b","sourceKey":"bank:BUA204:PQ-127","parentItemId":null,"revision":1,"payload":{"prompt":"The Maximax criterion is associated with a decision-maker who is:","options":["Pessimistic","Risk-averse","Optimistic","Indifferent to risk"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximax picks the alternative with the highest possible payoff, assuming the best state of nature will occur, which is an optimistic outlook. Options A and B describe the Maximin decision-maker, who focuses on protecting against the worst case."}},{"itemId":"47a12f3c-2454-5287-b02e-20c350f42550","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"743bfba3-8e9a-5b8d-a78c-36f6033901d8","sourceKey":"bank:BUA204:PQ-128","parentItemId":null,"revision":1,"payload":{"prompt":"The Maximin criterion selects the alternative with the:","options":["Highest of the best payoffs","Highest of the worst payoffs","Lowest of the worst payoffs","Average of all payoffs"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin takes the worst payoff for each alternative and then chooses the best of those worst cases, giving the safest guaranteed result. Option A is the Maximax rule, and Option D describes the Laplace criterion."}},{"itemId":"15d19a18-958d-5811-9231-356542756997","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e998287d-58ca-5a72-8141-561b7d6296b6","sourceKey":"bank:BUA204:PQ-129","parentItemId":null,"revision":1,"payload":{"prompt":"Expected Monetary Value (EMV) is calculated by:","options":["Adding all payoffs","Multiplying each payoff by its probability and summing","Taking the highest payoff only","Subtracting the lowest from the highest payoff"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV is a probability-weighted average: each payoff is multiplied by its probability and the results are added, EMV = sum of (probability x payoff). Option A ignores probabilities altogether, and Option C is the Maximax approach rather than EMV."}},{"itemId":"1d229c4c-541a-516a-86bd-00f3c08ec7ef","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"03ed9d23-c8f9-5dbd-b3f7-799c5db8dec8","sourceKey":"bank:BUA204:PQ-130","parentItemId":null,"revision":1,"payload":{"prompt":"In a decision tree, a square node represents:","options":["A chance event","A decision point","A final payoff","A probability value"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"A square node marks a point where the manager chooses between alternatives. Option A describes a circle node, where nature decides the outcome according to probabilities."}},{"itemId":"56bc0ee5-5fde-5d90-ae2a-b9d04ac1888f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ab4f3e8e-9875-551e-9adc-a4ca8f6eeb0b","sourceKey":"bank:BUA204:PQ-131","parentItemId":null,"revision":1,"payload":{"prompt":"In a decision tree, a circle node represents:","options":["A decision point","A chance (probability) event","The final outcome","The objective function"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"A circle node is a chance node, where an uncertain event occurs and its possible outcomes are shown as branches with probabilities. Option A is the square node, where the decision-maker chooses, and Option D belongs to linear programming, not decision trees."}},{"itemId":"19f083ef-75b9-57ec-b22a-c65515d4166f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"807feb42-998f-5954-a0f6-6af6de6f50f6","sourceKey":"bank:BUA204:PQ-132","parentItemId":null,"revision":1,"payload":{"prompt":"The Expected Value of Perfect Information (EVPI) represents:","options":["The cost of doing nothing","The maximum amount worth paying for perfect information","The minimum guaranteed payoff","The probability of the best outcome"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"EVPI is the expected payoff with perfect information minus the best EMV without it, so it shows the most a firm should pay for perfect information such as a perfect market forecast. Option C describes the Maximin result, not EVPI."}},{"itemId":"a10cd189-20cf-5aba-964a-33c65bf7edc6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43492b91-d823-5c7e-aad0-651509e7a8fa","sourceKey":"bank:BUA204:PQ-133","parentItemId":null,"revision":1,"payload":{"prompt":"The Minimax Regret criterion seeks to:","options":["Maximise the maximum payoff","Minimise the maximum opportunity loss","Maximise probability","Minimise the number of alternatives"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Minimax Regret finds the largest regret (opportunity loss) for each alternative and then picks the alternative whose largest regret is smallest. Option A is the Maximax rule, which looks at payoffs rather than regrets."}},{"itemId":"0469b0a6-4f41-5c55-9182-d362f502ba57","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6946dedc-ad7d-5d74-992b-3df05b17942e","sourceKey":"bank:BUA204:PQ-134","parentItemId":null,"revision":1,"payload":{"prompt":"The Laplace criterion assumes that:","options":["Only the best state of nature will occur","All states of nature are equally likely","Probabilities are unknown and irrelevant","Only the worst state matters"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"The Laplace (equally likely) criterion gives every state of nature the same weight and chooses the alternative with the highest average payoff. Option A is the Maximax assumption and Option D is the Maximin assumption."}},{"itemId":"7e5b4754-6d21-590a-84b0-1dde648c4faf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0fc15612-c17d-5d93-8581-49cfb660c58d","sourceKey":"bank:BUA204:PQ-135","parentItemId":null,"revision":1,"payload":{"prompt":"Regret (opportunity loss) for a given state of nature is calculated as:","options":["Best payoff in that state minus the payoff for the alternative chosen","Worst payoff minus best payoff","EMV minus EVPI","Probability times payoff"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret measures what you lose by not picking the best alternative for the state that occurs, so it is the best payoff in that state minus the payoff of your chosen alternative. Option D is the building block of EMV, not regret, and Option B would give a negative figure."}},{"itemId":"a23889fc-e2b0-52a8-972d-df0489b04c3e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fbc27169-c228-57ac-95d6-7d6fc96b292a","sourceKey":"bank:BUA204:PQ-136","parentItemId":null,"revision":1,"payload":{"prompt":"'Rolling back' a decision tree means:","options":["Starting calculations from the leftmost decision node","Working backwards from the final payoffs to the first decision","Ignoring probabilities","Discarding chance nodes"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Rolling back means working from right to left: computing EMVs at chance nodes and choosing the best branch at decision nodes until you reach the first decision. Option A is the wrong direction, and Options C and D would throw away the information the tree is built on."}},{"itemId":"7e6ee030-73cc-5235-86a0-3f336042732a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"35b42421-88bc-56ad-9dd1-e6d5d92ff4b8","sourceKey":"bank:BUA204:PQ-137","parentItemId":null,"revision":1,"payload":{"prompt":"A decision environment in which outcomes are known with full certainty is called decision-making under:","options":["Risk","Uncertainty","Certainty","Ambiguity"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under certainty, the outcome of each alternative is known in advance, so the manager simply picks the best one. Under risk (Option A) outcomes depend on states with known probabilities, and under uncertainty (Option B) the probabilities are not known."}},{"itemId":"48fed584-555b-55a6-8791-b9391c8a98b6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a9347dee-b3df-5564-8107-3f80b85eb1bb","sourceKey":"bank:BUA204:PQ-138","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making under UNCERTAINTY is a situation in which:","options":["The possible states of nature are known but no probabilities are available for them","Probabilities of the states of nature are known or can be estimated","The outcome of every alternative is known in advance","Only one alternative is available"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under uncertainty, the manager knows what could happen but cannot attach probabilities, so criteria such as Maximax, Maximin, Minimax Regret and Laplace are used instead of EMV. Option B describes decision-making under risk, and Option C describes certainty."}},{"itemId":"0a9024b5-033a-5d80-9c7e-052b78fbdb6a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a5ade59b-d8e7-595b-86a0-21e90b21d289","sourceKey":"bank:BUA204:PQ-139","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a criterion for decision-making under uncertainty (where no probabilities are available)?","options":["Maximin","Maximax","Expected Monetary Value (EMV)","Minimax Regret"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV needs a probability for each state of nature, so it is a tool for decision-making under risk. Maximax, Maximin and Minimax Regret work without probabilities, which is why they are used under uncertainty."}},{"itemId":"54448ccf-6117-5b83-8a5b-da9a7c3e3a89","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bb03151a-9861-5f33-897a-ecab0405c3d4","sourceKey":"bank:BUA204:PQ-140","parentItemId":null,"revision":1,"payload":{"prompt":"An investment yields a profit of N80,000 with probability 0.7 and a loss of N10,000 with probability 0.3. What is its Expected Monetary Value?","options":["N59,000","N53,000","N35,000","N70,000"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV = 0.7(80,000) + 0.3(-10,000) = 56,000 - 3,000 = N53,000. Option A treats the loss as a gain, Option D just adds the payoffs without weighting them, and Option C is a simple average that ignores the probabilities."}},{"itemId":"c98efd96-1dd0-55ee-becf-bc29e4d7c73d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"91e06c90-d10b-50f8-8901-c9f46792956e","sourceKey":"bank:BUA204:PQ-141","parentItemId":null,"revision":1,"payload":{"prompt":"The EVPI for a product launch decision is N12,000. A research firm offers a perfectly accurate market forecast for N15,000. What should the manager do?","options":["Decline the offer, because its cost is more than the EVPI","Accept the offer, because N15,000 is more than N12,000","Accept the offer, because perfect information is always worth buying","Decline the offer, because EVPI shows the information has no value"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"EVPI is the maximum amount worth paying for perfect information, so paying N15,000 for information worth at most N12,000 is not cost-justified. Option D misreads EVPI: the information does have value (N12,000), just less than the price asked."}},{"itemId":"59400e7e-eb98-5404-8ae3-40ec6dcee160","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"90e59c50-958a-5901-997c-7eb5b26994b1","sourceKey":"bank:BUA204:PQ-142","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about decision tree symbols is correct?","options":["Both decision and chance nodes are drawn as circles","A decision node is drawn as a triangle and a chance node as a square","A decision node is drawn as a square and a chance node as a circle","A decision node is drawn as a circle and a chance node as a square"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"A square marks a point where the decision-maker chooses between alternatives, while a circle marks a point where an uncertain event occurs with outcomes governed by probability. Option D reverses the two symbols, which is the most common slip."}},{"itemId":"873eee2b-d223-5ff9-9adf-3c4e311423a2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"355bf85a-8c57-50f4-a1f3-693b27356bd6","sourceKey":"bank:BUA204:PQ-143","parentItemId":null,"revision":1,"payload":{"prompt":"Why might a risk-averse manager prefer the Maximin criterion to the Maximax criterion?","options":["Maximin chooses the alternative with the best worst-case outcome, protecting against large losses","Maximin uses probabilities to compute an average payoff","Maximin always gives a higher payoff than Maximax","Maximin chooses the alternative with the highest possible payoff"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin looks at the worst result each alternative could produce and picks the best of these, so it guarantees a floor and limits downside risk. Option D describes Maximax, which ignores downside risk, and Option B describes EMV."}},{"itemId":"b11145b2-8713-5c39-b5e3-52e550f93443","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6d9e02f3-668e-5757-8312-b44bcdcb7544","sourceKey":"bank:BUA204:PQ-144","parentItemId":null,"revision":1,"payload":{"prompt":"Under a particular state of nature, the best payoff available from any alternative is N90,000. The alternative chosen pays N60,000 under that state. What is the regret (opportunity loss)?","options":["N30,000","N60,000","N150,000","N90,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret = best payoff in that state - payoff of the chosen alternative = 90,000 - 60,000 = N30,000. Option C adds the two payoffs instead of subtracting, and Options D and B simply restate one of the payoffs."}},{"itemId":"6aa9d13b-80c8-5bf0-aa3e-4c3c492731b2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"04214290-a007-55f4-84b2-66911459bc33","sourceKey":"bank:BUA204:PQ-145","parentItemId":null,"revision":1,"payload":{"prompt":"Two managers apply different but valid decision criteria to the same payoff table and recommend different alternatives. What is the best explanation?","options":["One of the managers must have made an arithmetic error","Valid criteria always give the same recommendation","The payoff table must be invalid","The criteria reflect different attitudes to risk, so each recommendation can be justified"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Each criterion weighs the same payoffs differently: Maximax reflects optimism, Maximin reflects caution and Laplace treats outcomes as equally likely. So two rational managers with different risk appetites can reach different but defensible choices. Option A is wrong because differing answers are expected, not a sign of error."}},{"itemId":"e2ed954d-430e-5e2a-9c6f-5c97c91f1dac","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a3237074-2284-5688-bb91-6fa5f8c794d1","sourceKey":"bank:BUA204:PQ-146-a","parentItemId":null,"revision":1,"payload":{"prompt":"Payoff table (profit, N'000) for Recession, Stable and Boom: S1 = 10, 40, 70; S2 = 30, 35, 50; S3 = -10, 45, 100. Which strategy is selected under Maximax, Maximin and Laplace respectively?","options":["S3, S2, S3","S3, S2, S1","S2, S3, S3","S3, S1, S2"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximax picks S3 (best payoff 100), Maximin picks S2 (its worst payoff of 30 is the highest of the worst payoffs 10, 30 and -10), and Laplace picks S3 (average 45, against 40 for S1 and 38.3 for S2). Option B gets Laplace wrong, since S1's average of 40 is below S3's 45."}},{"itemId":"2205ffe0-b5a3-5cb6-97c9-8d8afffb96f1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e103516f-1b0a-5c93-bc72-c26afd7597a9","sourceKey":"bank:BUA204:PQ-146-b","parentItemId":null,"revision":1,"payload":{"prompt":"Payoff table (profit, N'000) for Recession, Stable and Boom: S1 = 10, 40, 70; S2 = 30, 35, 50; S3 = -10, 45, 100. Under the Laplace criterion, what is the average payoff of S2, to one decimal place?","options":["N115.0 thousand","N35.0 thousand","N38.3 thousand","N40.0 thousand"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace treats the three states as equally likely, so the average for S2 = (30 + 35 + 50) / 3 = 115 / 3 = 38.3 thousand. Option A is the total before dividing by 3, and Option D is S1's average, not S2's."}},{"itemId":"8ddb5ddb-2c03-5c9a-bd63-07cd849fee41","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d2f3d6a9-2d0c-545e-bacc-c5a7250cf420","sourceKey":"bank:BUA204:PQ-147","parentItemId":null,"revision":1,"payload":{"prompt":"Payoff table (profit, N'000) for Recession, Stable and Boom: S1 = 10, 40, 70; S2 = 30, 35, 50; S3 = -10, 45, 100. Applying the Minimax Regret criterion, which strategy is recommended?","options":["S1, with a maximum regret of N30 thousand","S2, with a maximum regret of N50 thousand","S3, with a maximum regret of N40 thousand","S3, with a maximum regret of N0"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The best payoffs per state are 30, 45 and 100, so the maximum regrets are S1 = 30, S2 = 50 and S3 = 40 (from 30 - (-10) in a recession). The smallest of these is 30, so S1 is chosen. Option D picks S3, but its large regret in a recession rules it out under this criterion."}},{"itemId":"e497638f-d13a-5228-89fa-e63e67daf446","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"17b3ad94-b0d6-509e-b362-bde6b46c1a0c","sourceKey":"bank:BUA204:PQ-148-a","parentItemId":null,"revision":1,"payload":{"prompt":"Probabilities: Recession 0.3, Stable 0.5, Boom 0.2. Payoff table (profit, N'000) for Recession, Stable and Boom: S1 = 10, 40, 70; S2 = 30, 35, 50; S3 = -10, 45, 100. Which strategy has the highest Expected Monetary Value?","options":["S3, with EMV of N45,000","S1, with EMV of N37,000","S3, with EMV of N39,500","S2, with EMV of N36,500"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV(S1) = 0.3(10) + 0.5(40) + 0.2(70) = 37, EMV(S2) = 36.5 and EMV(S3) = 0.3(-10) + 0.5(45) + 0.2(100) = 39.5 thousand, so S3 is best at N39,500. Option A is S3's simple (Laplace) average, which ignores the given probabilities."}},{"itemId":"88cc92dc-4b8d-538b-b841-86c70fc05129","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c47c339c-d539-5e72-b10f-2275f3d4df48","sourceKey":"bank:BUA204:PQ-148-b","parentItemId":null,"revision":1,"payload":{"prompt":"Probabilities: Recession 0.3, Stable 0.5, Boom 0.2. Payoff table (profit, N'000) for Recession, Stable and Boom: S1 = 10, 40, 70; S2 = 30, 35, 50; S3 = -10, 45, 100. What is the Expected Value of Perfect Information (EVPI)?","options":["N12,000","N51,500","N14,500","N39,500"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"With perfect information the firm picks the best strategy in each state: EPPI = 0.3(30) + 0.5(45) + 0.2(100) = 51.5 thousand. EVPI = 51,500 - best EMV of 39,500 = N12,000. Option B is the expected payoff with perfect information before subtracting the best EMV, and Option D is the best EMV itself."}},{"itemId":"6d5da759-037e-5e75-9cfe-0aeaf264b7fd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3a2aab52-f424-551d-aee6-5539340b15f5","sourceKey":"bank:BUA204:PQ-149-a","parentItemId":null,"revision":1,"payload":{"prompt":"A firm can enter an export market directly or through a local distributor. Direct entry pays N500,000 if trade conditions are favourable (probability 0.6) and loses N200,000 if unfavourable (probability 0.4). The distributor route pays N300,000 if favourable and N50,000 if unfavourable, with the same probabilities. Rolling back the decision tree, which route should be chosen?","options":["Distributor, with EMV of N350,000","Direct entry, with EMV of N300,000","Direct entry, with EMV of N220,000","Distributor, with EMV of N200,000"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"At each chance node, EMV(direct) = 0.6(500,000) + 0.4(-200,000) = N220,000 and EMV(distributor) = 0.6(300,000) + 0.4(50,000) = N200,000. At the decision node the branch with the higher EMV, direct entry, is chosen. Option B ignores the probabilities, and Option A simply adds the distributor payoffs."}},{"itemId":"e44d78ae-eb72-56e9-bc96-c5dcc75fe0b6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c4b16e4b-c979-59fc-bbb7-0107cdc917e7","sourceKey":"bank:BUA204:PQ-149-b","parentItemId":null,"revision":1,"payload":{"prompt":"When rolling back a decision tree, what is done at a chance node and at a decision node?","options":["Compute the EMV at the chance node; choose the branch with the highest EMV at the decision node","Add all payoffs at both types of node","Choose the highest payoff at the chance node; compute the EMV at the decision node","Choose the lowest payoff at the chance node; choose the lowest EMV at the decision node"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"At a chance node nature decides, so the best you can do is weight each outcome by its probability to get the EMV. At a decision node the manager chooses, so the branch with the highest EMV is kept and the others are pruned. Option C swaps the two operations."}},{"itemId":"5be6836e-6ae3-518f-9a9a-1fd8eb2d4771","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"223a3e38-32e7-5658-86cc-bf03b1f7cbcf","sourceKey":"bank:BUA204:PQ-150","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a genuine LIMITATION of using Expected Monetary Value as the sole basis for a risky decision?","options":["EMV ignores probability information completely","EMV reflects the average outcome over many repetitions and ignores the manager's attitude to risk, so it can mislead in a one-off, high-stakes decision","EMV always selects the alternative with the lowest risk","EMV cannot be calculated when some payoffs are losses"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV is a long-run average, so for a single big decision a high-EMV option with a chance of a ruinous loss may still be unwise for a cautious firm. Option A is the reverse of the truth, since using probabilities is one of EMV's strengths, and Option D is false because losses are simply entered as negative payoffs."}},{"itemId":"08c1e82b-a7d8-5f4e-9e88-6977b5434b94","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"daf0f197-4d04-5842-92a3-6f2e296e2472","sourceKey":"bank:BUA204:PQ-151","parentItemId":null,"revision":1,"payload":{"prompt":"A variance is described as 'favourable' when:","options":["Actual cost exceeds budgeted cost","Actual profit falls short of budgeted profit","Actual results are better than budget","Actual results exactly equal budget"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"A favourable variance means performance beat the budget, such as higher revenue or lower cost than planned. Options A and B both describe adverse variances, where results are worse than budget."}},{"itemId":"96439e2e-beba-5ac2-acc7-440dafa3e343","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"22fceeec-ae8d-5452-9102-aa20600882a2","sourceKey":"bank:BUA204:PQ-152","parentItemId":null,"revision":1,"payload":{"prompt":"Percentage variance is calculated as:","options":["Actual / Budget","(Actual - Budget) / Budget x 100","Budget / Actual x 100","Actual - Budget only"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Percentage variance expresses the difference between actual and budget as a share of the budget: (Actual - Budget) / Budget x 100. Option D gives the variance in naira, not in percentage terms, and Option A gives a ratio rather than a variance."}},{"itemId":"198e81ac-e03d-5700-8648-711af7347010","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7746fbee-8330-5964-b354-809c4ade24e3","sourceKey":"bank:BUA204:PQ-153","parentItemId":null,"revision":1,"payload":{"prompt":"In time series analysis, a regular pattern of demand that repeats within each year is called:","options":["Secular trend","Seasonal variation","Cyclical variation","Random variation"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Seasonal variation is a pattern that repeats within the year, such as higher sales every festive season. Option A is a long-term gradual movement, and Option C is a longer, irregular swing tied to the business cycle."}},{"itemId":"a732a7f0-8fae-5034-b93a-bc1b2b126ffd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"576cc3f3-d54a-54e6-8ff5-cea59dae7b92","sourceKey":"bank:BUA204:PQ-154","parentItemId":null,"revision":1,"payload":{"prompt":"Sensitivity analysis is primarily used to:","options":["Eliminate the need for data","Test how a model's result changes when input assumptions change","Replace the need for a model entirely","Guarantee a single correct answer"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Sensitivity or 'what-if' analysis re-runs a model with changed inputs, such as a new price or cost, to see how much the result moves. Option D is the opposite of its purpose, since it shows how answers vary under different assumptions."}},{"itemId":"4e6f0bc4-dc56-53d3-8c18-3188b0005bcf","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0ca64a15-939c-5318-b3a2-b00341758f74","sourceKey":"bank:BUA204:PQ-155","parentItemId":null,"revision":1,"payload":{"prompt":"Which section of a business report is written for a reader with no time to read the full document?","options":["Appendices","Methodology","Executive Summary","Findings"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"The Executive Summary is a short overview of the main findings and the recommendation, written so a busy reader can grasp the report quickly. Option A holds detailed workings and raw data, which is the least likely part for a busy reader to look at."}},{"itemId":"1e44fb2c-143d-5b7d-be94-9783c0a1a916","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"380ddf42-00cf-5dba-ae12-0fb28aef1db0","sourceKey":"bank:BUA204:PQ-156","parentItemId":null,"revision":1,"payload":{"prompt":"The Methodology section of a quantitative business report should state:","options":["The recommendation only","The data sources and techniques used","The appendices","The title of the report only"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"The Methodology explains where the data came from and which quantitative techniques were applied, so readers can judge how reliable the findings are. Option A belongs in the Conclusion and Recommendations section."}},{"itemId":"749c2ac5-b2aa-587c-bf55-8a840d893156","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5fa01e06-f300-5242-adde-bb7245a7f8ce","sourceKey":"bank:BUA204:PQ-157","parentItemId":null,"revision":1,"payload":{"prompt":"A cyclical variation in a time series is best described as:","options":["A short, regular pattern within one year","A longer, irregular swing linked to the business cycle","A one-off random shock","A perfectly straight-line trend"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Cyclical variation refers to longer, irregular movements that follow the wider business cycle of boom and recession over several years. Option A describes seasonal variation, and Option C describes random variation."}},{"itemId":"aad88a9c-ddac-55d9-a85e-6bb1a6518d94","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5e2a00a3-b004-507c-a46a-5fa6db6b67f1","sourceKey":"bank:BUA204:PQ-158","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a limitation of quantitative findings?","options":["They are always free of bias","They depend on the quality of input data","They eliminate the need for managerial judgement","They are unaffected by sample size"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Quantitative results are only as good as the data fed into them, so poor or biased data leads to unreliable conclusions (garbage in, garbage out). Options A, C and D are false claims; in particular, findings still need managerial judgement and are affected by sample size."}},{"itemId":"f2c00760-565a-53db-b2de-7902611f95c3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"649caade-84ff-5863-8b56-323dd127f749","sourceKey":"bank:BUA204:PQ-159","parentItemId":null,"revision":1,"payload":{"prompt":"An adverse variance occurs when:","options":["Actual cost is less than budgeted cost","Actual revenue exceeds target","Actual results are worse than budget","Actual results equal budget exactly"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"An adverse variance means performance was worse than planned, such as costs above budget or revenue below target. Options A and B both describe favourable variances."}},{"itemId":"e4009c29-0c34-5704-a90b-4994f9d4dcb2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2a66c0d2-2ae2-52b4-997b-02b41a196768","sourceKey":"bank:BUA204:PQ-160","parentItemId":null,"revision":1,"payload":{"prompt":"The appendices of a business report typically contain:","options":["The executive summary","Detailed workings and raw data","The recommendation only","The report title"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Appendices hold detailed workings, raw data and supporting tables for readers who want to check the analysis, keeping the main body short and readable. Option A appears near the front of the report, not at the back."}},{"itemId":"7ef31506-68ec-5829-bcc5-1a28fb451d59","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"45d6c5f2-b1b7-5ca6-8f08-3a8fb242d039","sourceKey":"bank:BUA204:PQ-161","parentItemId":null,"revision":1,"payload":{"prompt":"Why is correlation alone an insufficient basis for a managerial recommendation?","options":["Correlation cannot be calculated for business data","Correlation does not establish causation","Correlation is always equal to 1","Correlation is irrelevant to interpretation"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Two variables can move together because of coincidence or a third factor, so a strong correlation does not prove that one causes the other. Option C is false because r can take any value from -1 to +1, and Option A is false because correlation is widely used on business data."}},{"itemId":"b2822dbc-097a-5185-8bb0-2e1d3cc6f966","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fead2379-b2d7-5f71-9bc4-f8d343f889b5","sourceKey":"bank:BUA204:PQ-162","parentItemId":null,"revision":1,"payload":{"prompt":"A 'what-if' analysis on a break-even model that recalculates the break-even point after a cost increase is an example of:","options":["Trend analysis","Variance analysis","Sensitivity analysis","Regression analysis"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Changing one input, here a cost, and recalculating the result to see its effect is sensitivity analysis. Option B compares actual results with budget after the event, and Option A studies the direction of a series over time."}},{"itemId":"0caed890-2292-5fa6-8c2f-0f4de60449c7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8a115f03-da15-5645-8231-c7f770d9bcbe","sourceKey":"bank:BUA204:PQ-163","parentItemId":null,"revision":1,"payload":{"prompt":"A firm budgeted sales of N500,000 but actual sales were N540,000. Using Variance (%) = (Actual - Budget) / Budget x 100, what is the variance?","options":["-8%, adverse","+8%, adverse","+7.4%, favourable","+8%, favourable"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Variance = 540,000 - 500,000 = N40,000, and 40,000 / 500,000 x 100 = +8%. Sales above budget is a good result, so it is favourable. Option C divides by actual sales instead of budget, and Option B gets the direction wrong, since higher-than-budget revenue is favourable."}},{"itemId":"d271fe02-d552-5dbc-97ef-8155d4dabef4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"37968577-1451-5a20-92f7-c3f082d335c0","sourceKey":"bank:BUA204:PQ-164-a","parentItemId":null,"revision":1,"payload":{"prompt":"Higher retail sales every December, year after year, are an example of:","options":["Random variation","Cyclical variation","Secular trend","Seasonal variation"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"A pattern that repeats at the same time each year is seasonal variation. Option C is a gradual long-term movement in one direction, and Option B is a longer, irregular swing linked to boom and recession."}},{"itemId":"5d795689-80ae-5844-9ec1-653e14faad90","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bd16b7d7-86f6-5bcd-b0ad-5ca824abb0ad","sourceKey":"bank:BUA204:PQ-164-b","parentItemId":null,"revision":1,"payload":{"prompt":"A steady rise in a country's population over several decades is an example of:","options":["Secular trend","Seasonal variation","Cyclical variation","Random variation"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"A secular trend is a gradual, long-term movement in one direction, like population growth over decades. Option B repeats within a year, and Option C rises and falls with the business cycle rather than moving steadily one way."}},{"itemId":"3c277a37-f2fd-58ff-be0a-63daa436d267","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"16d6bf46-8970-5a4c-92f4-4761ff0f88c0","sourceKey":"bank:BUA204:PQ-165","parentItemId":null,"revision":1,"payload":{"prompt":"Beyond showing how a result changes, what key management benefit does sensitivity ('what-if') analysis provide?","options":["It removes the need to collect data for the model","It proves that the model's assumptions are correct","It converts an adverse variance into a favourable one","It identifies which input assumptions the result is most sensitive to, so they deserve the closest scrutiny"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"By changing inputs one at a time, sensitivity analysis shows which assumptions move the answer most, telling managers where accurate estimates matter most. Option B is wrong because it tests assumptions under different values rather than proving them right."}},{"itemId":"d984d04f-e110-550d-ad16-9411b7aea544","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3cb66728-6a43-56a7-91c2-21c02c653536","sourceKey":"bank:BUA204:PQ-166","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence gives the typical order of sections in a business report presenting quantitative findings?","options":["Title Page, Appendices, Introduction, Methodology, Findings, Executive Summary, Conclusion and Recommendations","Title Page, Introduction, Findings, Methodology, Appendices, Executive Summary, Conclusion and Recommendations","Title Page, Executive Summary, Introduction, Methodology, Findings, Conclusion and Recommendations, Appendices","Executive Summary, Title Page, Methodology, Introduction, Conclusion and Recommendations, Findings, Appendices"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"A report opens with the Title Page and a short Executive Summary, sets the scene in the Introduction, explains the Methodology, presents the Findings, draws Conclusions and Recommendations, and ends with Appendices of detailed workings. Option B places the Executive Summary near the end, which defeats its purpose for busy readers."}},{"itemId":"ee09d798-7ddb-5814-b92f-ef146d220d5f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9c52078c-5e57-5fda-aa61-4edfb177aaff","sourceKey":"bank:BUA204:PQ-167","parentItemId":null,"revision":1,"payload":{"prompt":"Why should an analyst disclose the limitations of a quantitative finding alongside the finding itself?","options":["So the finding appears more precise than it is","So decision-makers do not place more confidence in the result than is warranted","Because disclosure removes the need for managerial judgement","Because limitations make the finding invalid and it should be ignored"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Stating limits such as a small sample or unreliable data helps decision-makers use the result with appropriate caution. Option D goes too far: a finding with limitations can still be useful if read sensibly, and Option A is the opposite of honest reporting."}},{"itemId":"45fcaf6c-77c6-50d0-b0ec-6c7e1a07509a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f51bf4b8-af19-5af3-a468-35054ffa6561","sourceKey":"bank:BUA204:PQ-168","parentItemId":null,"revision":1,"payload":{"prompt":"A company budgeted N2,000,000 in costs but actually spent N2,300,000. What is the cost variance?","options":["N300,000 (15%), favourable","N300,000 (13%), adverse","N2,300,000 (115%), adverse","N300,000 (15%), adverse"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Variance = 2,300,000 - 2,000,000 = N300,000, and 300,000 / 2,000,000 x 100 = 15%. Spending more than budget is worse than planned, so it is adverse. Option A gets the direction wrong, and Option B divides by actual cost instead of budget."}},{"itemId":"4c5c8602-eed3-59d2-a3a2-6e04edce1689","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43208a03-9f1c-54dc-abab-fe91e097ba8d","sourceKey":"bank:BUA204:PQ-169","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a valid reason why historical trends may not be a reliable guide to future performance?","options":["Past data are always perfectly accurate","Structural changes, such as a new competitor or a regulatory change, can break past patterns","Time series always move in a straight line","Future demand is always identical to past demand"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"A trend only continues if the conditions behind it continue, and events such as new competition, new regulation or one-off past factors can change the pattern. Options A, C and D are false statements that would actually support relying on history."}},{"itemId":"7b2b052f-8058-5f13-9b94-a69b65fb89c1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e484e62d-5d80-5ac4-87cc-0ff4e60edccc","sourceKey":"bank:BUA204:PQ-170","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's sales rise during several years of economic boom and then fall during the recession that follows. This movement is an example of:","options":["Secular trend","Cyclical variation","Random variation","Seasonal variation"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Longer, irregular swings that follow the business cycle of boom and recession are cyclical variation. Option D repeats within a single year, and Option A is a steady long-term movement in one direction."}},{"itemId":"8c5385ca-d226-580b-8c3f-871cdb2a2ce7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"93598513-9f5a-515c-95fd-252c2d6bae8a","sourceKey":"bank:BUA204:PQ-171-a","parentItemId":null,"revision":1,"payload":{"prompt":"A company's quarterly profit (Actual vs Budget, N'million) was: Q1 18 vs 20; Q2 25 vs 22; Q3 19 vs 24; Q4 30 vs 26. Which quarter had the largest adverse percentage variance?","options":["Q3, at -20.8%","Q4, at +15.4%","Q3, at -26.3%","Q1, at -10.0%"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Q3 variance = 19 - 24 = -N5m, and -5 / 24 x 100 = -20.8%, worse than Q1's -10.0%. Option C divides by actual profit instead of budget, and Option B is a favourable variance, not an adverse one."}},{"itemId":"7b8ac4b7-0b2b-5c8f-a6a1-4e7f22b276ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2d2a04b7-07d5-5c8a-bbc2-d1873397bf3b","sourceKey":"bank:BUA204:PQ-171-b","parentItemId":null,"revision":1,"payload":{"prompt":"A company's quarterly profit (Actual vs Budget, N'million) was: Q1 18 vs 20; Q2 25 vs 22; Q3 19 vs 24; Q4 30 vs 26. What is the variance for Q2, with percentage to one decimal place?","options":["+N3m (+13.6%), favourable","+N3m (+13.6%), adverse","-N3m (-13.6%), adverse","+N3m (+12.0%), favourable"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Q2 variance = 25 - 22 = +N3m, and 3 / 22 x 100 = +13.6%. Profit above budget is favourable. Option D divides by actual profit (25) instead of budget, and Option B wrongly labels a better-than-budget profit as adverse."}},{"itemId":"a5f33f10-f033-586a-992b-0367f93c9a0e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e61d15f8-7557-563e-9434-c2c35c13c4c9","sourceKey":"bank:BUA204:PQ-172-a","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery has fixed costs of N500,000, a selling price of N250 per unit and a variable cost of N150 per unit, so its break-even point is 5,000 units. If the selling price rises by 8%, what is the new break-even point, to the nearest unit?","options":["3,846 units","4,167 units","4,630 units","5,400 units"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"New price = 250 x 1.08 = N270, so contribution = 270 - 150 = N120 and BEP = 500,000 / 120 = 4,166.7, about 4,167 units. Option C simply cuts the old BEP by 8% (5,000 / 1.08), which ignores the effect on contribution per unit."}},{"itemId":"8e2299e1-4078-5a7e-95c3-f3739c9dacce","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"671287cc-95b0-5d9c-a063-1f4b189437d1","sourceKey":"bank:BUA204:PQ-172-b","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery has fixed costs of N500,000, a selling price of N250 per unit and a variable cost of N150 per unit, so its break-even point is 5,000 units. Which change reduces the break-even point by the larger percentage: (i) an 8% price increase or (ii) a 15% cut in fixed costs?","options":["The 15% fixed-cost cut (-15.0%) has a larger effect than the 8% price increase (about -8.0%)","Neither change affects the break-even point","Both changes reduce the break-even point by exactly 15%","The 8% price increase (about -16.7%) has a larger effect than the 15% fixed-cost cut (-15.0%)"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"The price rise lifts contribution from N100 to N120 and the BEP falls to about 4,167 units (-16.7%), while the fixed-cost cut gives 425,000 / 100 = 4,250 units (-15.0%). Price has a strong effect because it changes the contribution on every unit sold. Option A wrongly assumes an 8% price rise cuts the BEP by only 8%."}},{"itemId":"2a7601e2-70d5-5a01-8411-8695103d5de3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"28a298a3-c9e2-53ae-a469-2e26ff032f3d","sourceKey":"bank:BUA204:PQ-173","parentItemId":null,"revision":1,"payload":{"prompt":"In a business report presenting market research findings to a board, which section states the purpose and scope of the study?","options":["Introduction / Terms of Reference","Findings / Analysis","Methodology","Appendices"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"The Introduction or Terms of Reference tells the board why the study was done and what it covers. Option C explains the data sources and techniques used, and Option B presents the actual results."}},{"itemId":"2cfd0e8a-776e-51fa-b8d8-c49fccbcf293","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"00dd85ec-bb86-5367-91bf-319faac9e953","sourceKey":"bank:BUA204:PQ-174-a","parentItemId":null,"revision":1,"payload":{"prompt":"The 'GIGO' principle in quantitative analysis means that:","options":["Good results are guaranteed if the right formula is used","Greater sample size always gives an exact answer","Graphs are always more reliable than tables","Poor-quality input data produce unreliable results, even when a technique is correctly applied"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"GIGO stands for 'garbage in, garbage out': no technique can turn bad data into a reliable answer. Option A is the error GIGO warns against, since a correct formula applied to poor data still gives a poor result."}},{"itemId":"a440759a-663b-569b-aebb-6ba1d30636bb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"39e4770f-9e9b-55e5-b08f-05eddd344d58","sourceKey":"bank:BUA204:PQ-175","parentItemId":null,"revision":1,"payload":{"prompt":"How does data interpretation differ from data analysis in managerial decision-making?","options":["Interpretation replaces the need for calculation","Analysis answers 'so what?', while interpretation answers 'how much?'","They are the same activity under different names","Analysis answers 'how?' and 'what?', while interpretation answers 'so what?' and 'why?'"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Analysis produces the numbers, such as a break-even point or an EMV, while interpretation explains what those numbers mean for the business and what action to take. Option A is wrong because the two work together: interpretation needs sound calculation to build on."}},{"itemId":"e8377921-9c8e-5a96-8264-efae138251ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4fa9a17b-1a29-5210-8904-457a2bb69f52","sourceKey":"bank:BUA204:PQ-177","parentItemId":null,"revision":1,"payload":{"prompt":"Which mathematical concept is used to solve a product-mix problem with two unknowns, such as finding how many Tables and how many Chairs were sold from given totals?","options":["Simultaneous equations","Logarithms","Indices","Linear inequality"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"With two unknowns and two facts (for example total units and total profit), you form two equations and solve them together, which is the method of simultaneous equations. Option D sets limits rather than finding exact values, and Options B and C deal with powers and growth."}},{"itemId":"b91b458e-52dd-5121-b041-5b7a61c40f2e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7053e39a-a7f9-5b2b-b505-b890660edbbc","sourceKey":"bank:BUA204:PQ-178","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for Total Cost (TC) is (FC = fixed cost, v = variable cost per unit, Q = quantity):","options":["TC = FC + (v x Q)","TC = FC x VC","TC = P x Q","TC = FC - VC"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Total cost is fixed cost plus total variable cost, and total variable cost is the variable cost per unit times the quantity. Option C is the formula for total revenue, not total cost."}},{"itemId":"4a930019-12d1-5d7a-b7ab-b5e7140b694a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7174695e-dfd1-5c25-850a-af2f53416213","sourceKey":"bank:BUA204:PQ-180","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's selling price is N5,000 per unit, variable cost is N3,000 per unit and fixed cost is N1,000,000. What is the contribution margin per unit?","options":["N8,000","N2,000","N3,000","N1,500"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution margin = selling price - variable cost = 5,000 - 3,000 = N2,000 per unit. Fixed cost is not used in this step. Option A adds instead of subtracting, and Option C is just the variable cost."}},{"itemId":"8abfbe5d-ca55-5624-8a4d-86f111c14ef5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ff126772-caae-53d3-a111-523153788377","sourceKey":"bank:BUA204:PQ-182","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's selling price is N5,000 per unit, variable cost is N3,000 per unit and fixed cost is N1,000,000. What is the Break-Even Revenue (BER)?","options":["N1,500,000","N1,000,000","N2,500,000","N5,000,000"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"First BEQ = 1,000,000 / (5,000 - 3,000) = 500 units, then BER = BEQ x selling price = 500 x 5,000 = N2,500,000. Option B is just the fixed cost, which is the contribution needed, not the revenue needed, to break even."}},{"itemId":"cf616b2f-558c-5f46-8821-fabdbaa11816","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0bb613a1-99b5-5857-bc16-46274f968cb6","sourceKey":"bank:BUA204:PQ-183","parentItemId":null,"revision":1,"payload":{"prompt":"A company sells 2,500 units at N8,000 each. What is the Total Revenue?","options":["N20,000,000","N25,000,000","N16,000,000","N10,000,000"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Total revenue = price x quantity = 8,000 x 2,500 = N20,000,000. The other options come from multiplying the wrong figures."}},{"itemId":"8fd493bc-0732-5711-a34d-051e0795e549","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a95e4f7c-ce9f-52f9-8745-be4dc796cdb3","sourceKey":"bank:BUA204:PQ-184","parentItemId":null,"revision":1,"payload":{"prompt":"A firm makes a profit of N20,000 on each Table and N10,000 on each Chair. It sold 200 products in total and made a total profit of N2,800,000. How many Chairs were sold?","options":["80","120","150","100"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Solve T + C = 200 and 20,000T + 10,000C = 2,800,000 together: substituting T = 200 - C gives 4,000,000 - 10,000C = 2,800,000, so C = 120. Option A is the number of Tables, not Chairs."}},{"itemId":"de7f8cb4-02f8-5f27-b9ac-86f687806226","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"34b133e9-0999-5e06-8dfd-507115772404","sourceKey":"bank:BUA204:PQ-185","parentItemId":null,"revision":1,"payload":{"prompt":"A firm makes a profit of N20,000 on each Table and N10,000 on each Chair. It sold 200 products in total and made a total profit of N2,800,000. How many Tables were sold?","options":["120","90","80","70"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"From T + C = 200 and 20,000T + 10,000C = 2,800,000, the Chairs come to 120, so Tables = 200 - 120 = 80. Check: 20,000(80) + 10,000(120) = 1,600,000 + 1,200,000 = N2,800,000. Option A is the number of Chairs."}},{"itemId":"70556cea-d3a6-53df-bacb-e39815914f0f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b1dbf8f0-5e7a-5dd2-868c-4d3ff5cb87db","sourceKey":"bank:BUA204:PQ-186","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of N1,000,000 grows at 10% per year, compounded annually. What is its future value after 3 years?","options":["N1,100,000","N1,331,000","N1,300,000","N1,310,000"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"With compound growth, FV = P(1 + r)^n = 1,000,000 x (1.10)^3 = N1,331,000, because each year's interest also earns interest. Option C, N1,300,000, is the simple-interest answer, and Option A is the value after only one year."}},{"itemId":"e98f3581-1bcd-59ad-b857-9afd97865086","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8be92822-a686-59f3-a065-d354106ef0e0","sourceKey":"bank:BUA204:PQ-187","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula gives the future value (FV) of an amount P invested for n years at an annual compound interest rate r?","options":["FV = P / (1 + r)^n","FV = P x r x n","FV = P(1 + r)^n","FV = P + rn"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Under compound interest the amount is multiplied by (1 + r) once for every year, giving FV = P(1 + r)^n. Option A is the present value formula (discounting), and Option B gives only the simple interest earned, not the future value."}},{"itemId":"421b8bc9-e2b7-57bd-b4e7-336c73fc7872","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"656cc780-d009-5070-967b-505e47845c87","sourceKey":"bank:BUA204:PQ-188","parentItemId":null,"revision":1,"payload":{"prompt":"A circular waste reservoir has a radius of 10 m. Taking pi = 3.142, what is its area?","options":["314.2 m^2","628.4 m^2","31.42 m^2","100 m^2"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Area of a circle = pi x r^2 = 3.142 x 10^2 = 3.142 x 100 = 314.2 m^2. Option B doubles this (using 2 x pi x r^2 by mistake), and Option D forgets to multiply by pi."}},{"itemId":"d6c06487-742d-564a-be4d-ec7f3f32af19","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"da5698f5-26f3-52a4-9f46-c45f2fb70c24","sourceKey":"bank:BUA204:PQ-189","parentItemId":null,"revision":1,"payload":{"prompt":"A warehouse is 40 m long, 25 m wide and 8 m high. What is its volume?","options":["5,000 m^3","1,000 m^3","800 m^3","8,000 m^3"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Volume of a rectangular space = length x breadth x height = 40 x 25 x 8 = 8,000 m^3. Option B, 1,000, is only the floor area (40 x 25) in square metres, without the height."}},{"itemId":"9272fcb4-0707-5602-9b61-6d276562f147","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"47ef60b5-4e13-5aaf-8858-03aab4092a0e","sourceKey":"bank:BUA204:PQ-191","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm has fixed cost of N45,000,000, a selling price of N9,000 per unit and a variable cost of N6,000 per unit. What is the Break-Even Quantity?","options":["15,000 units","5,000 units","7,500 units","10,000 units"],"correctOption":0,"section":"Basic Mathematical Concepts for Management","explanation":"Contribution margin = 9,000 - 6,000 = N3,000, so BEQ = 45,000,000 / 3,000 = 15,000 units. Option B would come from dividing by the selling price instead of the contribution margin."}},{"itemId":"d9c7b791-ecec-55a6-bd25-3e47eeccb66e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e4086304-4884-5490-9ce3-bbc87577d728","sourceKey":"bank:BUA204:PQ-192","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed cost of N45,000,000, a selling price of N9,000 per unit and a variable cost of N6,000 per unit. Using Q = (FC + target profit) / contribution margin, what output is needed to earn a target profit of N25,000? (Round up to the next whole unit.)","options":["15,000 units","23,333 units","15,009 units","15,008 units"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Q = (45,000,000 + 25,000) / 3,000 = 15,008.33, which rounds up to 15,009 units, since selling 15,008 would fall just short of the target. Option A is the break-even quantity, which gives zero profit, and Option D rounds down."}},{"itemId":"c4920824-439d-5d26-a2d5-98aabda79ab4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c6a997f-2013-5fa6-b5d5-ea64bfd8394e","sourceKey":"bank:BUA204:PQ-193","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has fixed cost of N45,000,000, a selling price of N9,000 per unit and a variable cost of N6,000 per unit, giving a break-even quantity of 15,000 units. If market demand is only 5,000 units, what is the correct managerial implication?","options":["The firm should immediately shut down operations permanently","Demand has no effect on break-even status","The firm easily breaks even with room for extra profit","The firm cannot break even and must consider reducing costs, raising price or finding new markets"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Demand of 5,000 units is far below the 15,000 units needed to break even, so the firm will make a loss at current prices and costs. The sensible response is to change the figures, by cutting fixed or variable costs, raising the price or finding new markets. Option A is too extreme, since the problem may be fixable."}},{"itemId":"1690cd95-e70f-56eb-ba78-1042d48b1437","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fc1ab6e9-ed3e-588d-a7fd-69ea238ca06f","sourceKey":"bank:BUA204:PQ-194","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula defines Marginal Cost (MC)?","options":["MC = FC / Q","MC = TR - TC","MC = change in TC / change in Q","MC = TC / Q"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"Marginal cost is the extra cost of producing one more unit, measured as the change in total cost divided by the change in quantity. Option D is average cost, and Option B is profit."}},{"itemId":"467679e2-7387-51fe-98aa-d04e91ff5113","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"51bf93de-d9f4-52b6-937a-9667628e300a","sourceKey":"bank:BUA204:PQ-201","parentItemId":null,"revision":1,"payload":{"prompt":"On the usual interpretation scale for Pearson's r, a value between 0.7 and 0.9 indicates:","options":["Perfect correlation","Strong positive correlation","Weak positive correlation","Moderate positive correlation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Values of r from 0.7 to 0.9 are close to +1, so they show a strong positive relationship. Option D applies to middle values around 0.4 to 0.6, and Option A applies only to r = +1.0 exactly."}},{"itemId":"d1e57f53-68bc-563f-bb36-c8cf10ac14ce","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"919b4bfe-de60-58ab-864e-e52950374847","sourceKey":"bank:BUA204:PQ-208","parentItemId":null,"revision":1,"payload":{"prompt":"A manager recorded advertising expenditure (x) and sales (y) over 5 months: x = 1, 2, 3, 4, 5 and y = 2, 4, 5, 8, 9. What is the sum of xy?","options":["110","95","90","102"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Multiply each pair and add: (1 x 2) + (2 x 4) + (3 x 5) + (4 x 8) + (5 x 9) = 2 + 8 + 15 + 32 + 45 = 102. This sum is an input to Pearson's r, and it is not the same as multiplying the totals, (sum of x) x (sum of y) = 15 x 28 = 420; Options A, B and C come from adding the products wrongly."}},{"itemId":"24490bc4-18a5-51cd-b40b-8873490daefb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2781a9ee-f01f-5b3f-8026-2e105e003288","sourceKey":"bank:BUA204:PQ-209","parentItemId":null,"revision":1,"payload":{"prompt":"A manager recorded advertising expenditure (x) and sales (y) over 5 months: x = 1, 2, 3, 4, 5 and y = 2, 4, 5, 8, 9. What is the sum of x^2 (the sum of the squared x values)?","options":["50","45","55","60"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Squaring each x value and adding gives 1 + 4 + 9 + 16 + 25 = 55, so C is correct. Options A (50), B (45) and D (60) come from slips in squaring or adding. Remember that the sum of x^2 is not the same as (sum of x)^2, which would be 15^2 = 225."}},{"itemId":"41a7109a-cd70-538f-9777-2fd197102e9a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3920f9a8-89b7-5838-a4fd-a4c4b14791f8","sourceKey":"bank:BUA204:PQ-210","parentItemId":null,"revision":1,"payload":{"prompt":"A manager recorded advertising expenditure (x) and sales (y) over 5 months: x = 1, 2, 3, 4, 5 and y = 2, 4, 5, 8, 9. What is the sum of y^2 (the sum of the squared y values)?","options":["180","170","190","200"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Squaring each y value gives 4, 16, 25, 64 and 81, which add up to 190, so C is correct. Options A (180), B (170) and D (200) are near misses from slips in squaring or adding. Also, the sum of y^2 is different from (sum of y)^2 = 28^2 = 784."}},{"itemId":"9fd9eaa3-61e2-5ff5-a61c-f629b8be320a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"43e6efef-f5b7-5a8c-ba0e-a60f7e1754eb","sourceKey":"bank:BUA204:PQ-211","parentItemId":null,"revision":1,"payload":{"prompt":"A manager recorded advertising expenditure (x) and sales (y) over 5 months: x = 1, 2, 3, 4, 5 and y = 2, 4, 5, 8, 9. Pearson's correlation coefficient for this data is r = 0.988 (to 3 decimal places). This indicates:","options":["No relationship","A strong positive relationship","A weak negative relationship","A perfect negative relationship"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"An r value close to +1 means the two variables move together very closely in the same direction, so B, a strong positive relationship, is correct. Option D would need r = -1 and option C would need a small negative r. Option A applies when r is close to 0, which is far from 0.988."}},{"itemId":"5616851f-c2b1-5fc4-aec2-597a9c8d1b86","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"718d68e3-af59-5451-9581-3cc75a43d08a","sourceKey":"bank:BUA204:PQ-211-b","parentItemId":null,"revision":1,"payload":{"prompt":"A manager recorded advertising expenditure (x) and sales (y) over 5 months: x = 1, 2, 3, 4, 5 and y = 2, 4, 5, 8, 9. Using Pearson's formula r = [n(sum xy) - (sum x)(sum y)] / sqrt{[n(sum x^2) - (sum x)^2][n(sum y^2) - (sum y)^2]}, what is r? (Round to 3 decimal places.)","options":["0.988","0.542","0.976","1.800"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Here n = 5, sum x = 15, sum y = 28, sum xy = 102, sum x^2 = 55 and sum y^2 = 190, so the numerator is 5(102) - 15(28) = 90 and the denominator is sqrt[(275 - 225)(950 - 784)] = sqrt(8,300) = 91.104, giving r = 0.988 (A). Option C (0.976) is r squared, not r, and option B (0.542) comes from dividing 90 by only one bracket (166) without the square root. Option D (1.800) is impossible because r always lies between -1 and +1."}},{"itemId":"6ae24624-2055-54b8-a62a-8c47e76cc3ed","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"82e80f9e-403a-5dce-8023-02c36fdcf791","sourceKey":"bank:BUA204:PQ-213","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a typical business application of correlation analysis?","options":["Assisting in forecasting and business planning","Determining criminal liability in a court case","Studying price and demand relationships","Studying the relationship between sales and advertising"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Correlation analysis measures how strongly two quantitative variables move together, which is why it is used for sales and advertising, price and demand, and forecasting and planning (options A, C and D). Determining criminal liability is a legal judgement about individual responsibility, not a measure of association between business variables, so B is the odd one out."}},{"itemId":"a5961cd9-ca1e-594d-8164-18441b738d69","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"50c8de5f-7b52-5aad-8f66-ae4cd892a288","sourceKey":"bank:BUA204:PQ-215","parentItemId":null,"revision":1,"payload":{"prompt":"Correlation in which the amount of change in one variable does NOT bear a constant ratio to the amount of change in the other variable is called:","options":["Linear correlation","Zero correlation","Partial correlation","Non-linear correlation"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"When the change in one variable does not bear a constant ratio to the change in the other, the points follow a curve rather than a straight line, which is non-linear (curvilinear) correlation, so D is correct. Option A, linear correlation, is the opposite case where the ratio of change is constant. Option B means no relationship at all, and option C is about holding other variables constant, not the shape of the relationship."}},{"itemId":"a26906e4-3937-53ed-8dac-a5df7d03e64b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c435e76f-158b-571b-b39e-0d318c85a445","sourceKey":"bank:BUA204:PQ-222","parentItemId":null,"revision":1,"payload":{"prompt":"QAM is intended to:","options":["Eliminate the need for managers entirely","Only be used by government agencies","Improve managerial decision-making ability, not replace judgement or common sense","Completely replace human judgement in decision-making"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Quantitative analysis is meant to sharpen and support a manager's decisions, not to replace good judgement, perception or common sense, so C is correct. Options A and D overstate its role, since managers still interpret results and weigh factors that cannot be measured. Option B is wrong because QAM is used by businesses of all kinds, not only government."}},{"itemId":"c550f03c-021e-513c-ba68-770cdc728e90","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f5eff4bb-4148-5dd4-ab1d-625bffd956f5","sourceKey":"bank:BUA204:PQ-229","parentItemId":null,"revision":1,"payload":{"prompt":"Which chart shows proportions by giving each category an angle = (frequency / total) x 360 degrees?","options":["Scatter Diagram","Pie Chart","Line Graph","Histogram"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A pie chart divides a full circle of 360 degrees into slices, with each slice's angle proportional to its share of the total, so B is correct. Option A plots pairs of values, option C shows change over time and option D shows the frequency distribution of continuous data, so none of them uses angles."}},{"itemId":"2abb5513-0db3-567c-8357-925d2f00e171","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e673b0f9-00eb-545c-b873-c6fcee26af7a","sourceKey":"bank:BUA204:PQ-240","parentItemId":null,"revision":1,"payload":{"prompt":"The Z-score formula is (X = value, mu = mean, sigma = standard deviation):","options":["Z = sigma / (X - mu)","Z = mu / X","Z = (X - mu) / sigma","Z = (X - mu) x sigma"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"A Z-score tells you how many standard deviations a value lies from the mean, so you subtract the mean and divide by the standard deviation: Z = (X - mu) / sigma, option C. Option D multiplies by sigma instead of dividing, and option A turns the correct fraction upside down. Option B ignores the standard deviation completely."}},{"itemId":"145b0a83-71c0-5839-b28b-48a9007a1540","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"770a17de-cffb-5158-9dcc-bf46dc59a5f6","sourceKey":"bank:BUA204:PQ-244","parentItemId":null,"revision":1,"payload":{"prompt":"Which test should be used to compare a sample mean to a known population mean when the sample is large (n >= 30) and the population standard deviation (sigma) is known?","options":["Z-Test","Chi-Square","ANOVA","t-Test"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"With a large sample and a known population standard deviation, the sampling distribution of the mean is treated as normal, so the Z-test (A) is used. Option D, the t-test, is for small samples where sigma is unknown, option B handles categorical data, and option C compares three or more group means."}},{"itemId":"4d8e12a7-a1d2-5ffb-af2b-e383f6ad7cc5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"32a54168-cfa1-5e58-a383-946d331c65c0","sourceKey":"bank:BUA204:PQ-257","parentItemId":null,"revision":1,"payload":{"prompt":"In Ragsdale's classification of models, which of these is an example of a predictive model?","options":["Goal programming","CPM","Linear programming","Regression analysis"],"correctOption":3,"section":"Operational Modelling","explanation":"Predictive models are used when the exact relationship between variables is not known in advance and has to be estimated from data, which is exactly what regression analysis does, so D is correct. Options A, B and C (goal programming, CPM and linear programming) are prescriptive models, where the relationships are well defined and the model points to the best decision."}},{"itemId":"f31a01db-9355-52bc-a0de-5f7d7780a7fd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9af825d0-5052-5e2e-9e03-b910ec619449","sourceKey":"bank:BUA204:PQ-262","parentItemId":null,"revision":1,"payload":{"prompt":"Maximise Z = 5x + 4y subject to 6x + 4y <= 24, x + 2y <= 6, x >= 0 and y >= 0. Using the graphical (corner-point) method, what is the optimal solution?","options":["x = 0, y = 0, Z = 0","x = 3, y = 1.5, Z = 21","x = 4, y = 0, Z = 20","x = 0, y = 3, Z = 12"],"correctOption":1,"section":"Operational Modelling","explanation":"The corner points of the feasible region are (0, 0), (4, 0), (3, 1.5) and (0, 3), where (3, 1.5) comes from solving 6x + 4y = 24 and x + 2y = 6 together. Evaluating Z gives 0, 20, 21 and 12 respectively, so the maximum is Z = 21 at x = 3, y = 1.5 (option B). Options C and D are feasible corners but give a lower Z, and option A is the origin, where Z = 0."}},{"itemId":"57359e44-e839-552e-b757-f1bd97af653c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"538004cc-54db-585c-9b15-e548abccf977","sourceKey":"bank:BUA204:PQ-268","parentItemId":null,"revision":1,"payload":{"prompt":"The Hurwicz (Criterion of Realism) formula, with alpha as the coefficient of optimism, is:","options":["alpha x Max + (1 - alpha) x Min","Min payoff only","Average of all payoffs","Max payoff only"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The Hurwicz criterion takes a weighted average of each alternative's best and worst payoffs, using alpha as the coefficient of optimism: alpha x Max + (1 - alpha) x Min, so A is correct. Option D is the maximax rule and option B the maximin rule, which are the special cases alpha = 1 and alpha = 0. Option C is the Laplace (equally likely) approach."}},{"itemId":"636a6c98-a6d4-53d1-a473-3710fbd73e9e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"56c4f23b-4328-5571-b788-76bc31ca1f08","sourceKey":"bank:BUA204:PQ-270","parentItemId":null,"revision":1,"payload":{"prompt":"A firm can build a Large Plant (payoff N200,000 if the market is favourable, -N180,000 if unfavourable), a Small Plant (N100,000 or -N20,000) or Do Nothing (N0 either way). The probability of a favourable market is 0.6 and of an unfavourable market 0.4. Which alternative has the highest expected monetary value (EMV)?","options":["Small Plant (N52,000)","Both plants tied","Do Nothing (N0)","Large Plant (N48,000)"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Small Plant EMV = 0.6(100,000) + 0.4(-20,000) = 60,000 - 8,000 = N52,000, while Large Plant EMV = 0.6(200,000) + 0.4(-180,000) = 120,000 - 72,000 = N48,000, so A is correct. Option D has the bigger upside, but its large possible loss pulls its EMV down. Option B is wrong because the two EMVs differ, and option C gives only N0."}},{"itemId":"f5243564-d31d-5814-8226-d7e812723676","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c717a13e-aa80-5253-aa84-eec71f97f00b","sourceKey":"bank:BUA204:PQ-270-b","parentItemId":null,"revision":1,"payload":{"prompt":"A firm can build a Large Plant (payoff N200,000 if the market is favourable, -N180,000 if unfavourable), a Small Plant (N100,000 or -N20,000) or Do Nothing (N0 either way). The probability of a favourable market is 0.6 and of an unfavourable market 0.4. What is the EMV of the Large Plant?","options":["N48,000","N10,000","-N28,000","N120,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV = 0.6(200,000) + 0.4(-180,000) = 120,000 - 72,000 = N48,000, so A is correct. Option D counts only the favourable branch and ignores the possible loss, option B is a simple average of the two payoffs that ignores the probabilities, and option C comes from swapping the two probabilities."}},{"itemId":"32e986df-2fda-5850-b010-603b62d04ea5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"19f3ce39-53d4-574a-9ce2-4da08c4079a9","sourceKey":"bank:BUA204:PQ-275","parentItemId":null,"revision":1,"payload":{"prompt":"Decisions are commonly made through five traditional approaches, two of which are authority and 'do nothing'. Which of these is NOT one of the five?","options":["Voting","Experience","Intuition","Regression analysis"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"The five traditional approaches to decision making are intuition, experience, authority, voting and doing nothing, so voting (A), experience (B) and intuition (C) are all on the list. Regression analysis (D) is a quantitative statistical technique, not one of these informal approaches, so it is the correct answer."}},{"itemId":"410fd020-0193-502c-9c18-a85dd0132087","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"485e05e1-f7e4-5cf7-acc6-889030ab3dd3","sourceKey":"bank:BUA204:PQ-276","parentItemId":null,"revision":1,"payload":{"prompt":"Decision Theory is best defined as:","options":["A qualitative-only approach with no data","An analytic and systematic approach to studying decision making, using a rational process for selecting the best of several alternatives","A purely mathematical formula with no room for judgement","A method used only for financial forecasting"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Decision theory is an analytic and systematic way of studying decisions, using a rational process to choose the best of several alternatives, so B is correct. Option A is wrong because decision theory uses data such as payoffs and probabilities, while option C ignores the role of judgement in setting up and interpreting the problem. Option D is too narrow, since decision theory applies to product, expansion and many other decisions."}},{"itemId":"faa84f4f-92c7-5c9b-a284-1e96688eaf5f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"761afa16-1e7e-567a-b196-aefec7da4cfd","sourceKey":"bank:BUA204:PQ-282","parentItemId":null,"revision":1,"payload":{"prompt":"Among the elements of decision making (action, state of nature, alternatives, payoff, goal), which element refers to actually making a choice out of the different options?","options":["Action","State of Nature","Payoff","Alternatives"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Action is the act of choosing one course from the options available, so A is correct. Option D, alternatives, are the options themselves rather than the act of choosing between them. Option B refers to conditions outside the decision maker's control, and option C is the benefit that results from the choice."}},{"itemId":"dc7005a2-8365-554f-a76c-73d99cce6068","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"081dcddf-af78-54af-b38c-c8a0e6dd8e78","sourceKey":"bank:BUA204:PQ-286","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the LAST of the nine stages in the detailed decision-making process?","options":["Analysis of physical/alternative actions","Selection of best optimal action","Evaluate the result","Implementation of decision"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"After a decision has been implemented, the result must be evaluated to see whether the objective was achieved, so evaluating the result (C) is the last stage. Option D, implementation, comes just before it, option B, selecting the best action, comes before implementation, and option A, analysing the alternatives, comes earlier still."}},{"itemId":"a45d5196-e3aa-50f7-8828-58a583e3b339","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d6eef9a9-59e6-596d-bdc8-8110249f8d64","sourceKey":"bank:BUA204:PQ-287","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Savage (Minimax Regret) method, what is Full's regret in the Poor market column?","options":["14,000","22,000","4,000","16,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret is the best payoff in a column minus the actual payoff in that cell. The best payoff under a Poor market is Minimal's 18,000, so Full's regret is 18,000 - 4,000 = 14,000 (A). Option C is Full's payoff, not its regret, option B comes from adding instead of subtracting, and option D is Minimal's regret in the High column."}},{"itemId":"5550d12d-fc21-5434-a9d5-bcff7af93974","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b9198b64-5e43-5cb7-9e57-760702360f21","sourceKey":"bank:BUA204:PQ-288","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Savage (Minimax Regret) method, what is Minimal's regret in the Moderate market column?","options":["10,000","15,500","500","14,500"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"The best payoff under a Moderate market is Full's 15,000, and Minimal earns -500 there, so its regret is 15,000 - (-500) = 15,500 (B). Option D treats the loss as a gain (15,000 - 500), option C is just the size of Minimal's loss, and option A is Partial's regret in the same column."}},{"itemId":"baef3230-81de-57d9-9c31-22e9e96f9375","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a1a5e199-b439-5785-996f-8368fd6bdbbe","sourceKey":"bank:BUA204:PQ-289","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Maximax criterion, which product line(s) should be chosen?","options":["Partial only, at 18,000","Minimal only","Full only, at 15,000","Full or Partial (tied at 20,000)"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximax takes the best payoff in each row: Full 20,000, Partial 20,000 and Minimal 18,000. The highest of these, 20,000, is reached by both Full and Partial, so they tie and D is correct. Options A and C quote wrong row maximums, and option B (Minimal) has the lowest best case of the three."}},{"itemId":"2c829613-2643-5993-ad81-2b0c054b4b1d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3d3dcd03-573e-59b4-b436-5ce41d9791cf","sourceKey":"bank:BUA204:PQ-290","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Maximin criterion, which product line should be chosen?","options":["Partial","Minimal","Full","All three are tied"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin takes the worst payoff in each row: Full -2,000, Partial 500 and Minimal -500. The best of these worst cases is Partial's 500, so A is correct. Options C and B both risk a loss in their worst state, and option D is wrong because the three row minimums are all different."}},{"itemId":"84392e08-3431-5736-9359-06d72545f3c6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c714f4e3-fa44-5161-ae62-e4020f6c53f6","sourceKey":"bank:BUA204:PQ-291","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. What is Partial's row minimum when applying the Maximin criterion?","options":["1,000","-500","500","-2,000"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Partial's payoffs across the four markets are 20,000, 5,000, 1,000 and 500, so its row minimum is 500 and C is correct. Option A (1,000) is its payoff under a Low market, not the smallest, while option B (-500) is Minimal's minimum and option D (-2,000) is Full's."}},{"itemId":"a1381b56-2fe4-5776-80cb-e4d0506416d3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6dea627a-ff4c-5b8a-b87f-14d2fcdba5dc","sourceKey":"bank:BUA204:PQ-292","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Laplace (equally likely) criterion, what is the average payoff for the Full product line?","options":["N8,500","N9,250","N6,875","N6,625"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace treats all four states as equally likely, so Full's average is (20,000 + 15,000 - 2,000 + 4,000) / 4 = 37,000 / 4 = N9,250, making B correct. Option D (N6,625) is Partial's average and option C (N6,875) is Minimal's, while option A does not match any row's correct average."}},{"itemId":"003d6f43-d6ba-5ec9-919e-9687d601068f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9d246530-cd8d-5aa8-9961-9b047acc085b","sourceKey":"bank:BUA204:PQ-293","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Which product line does the Laplace (equally likely) criterion recommend?","options":["Full","Full and Partial (tied)","Partial","Minimal"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Laplace averages each row: Full N9,250, Partial N6,625 and Minimal N6,875. Full has the highest average, so A is correct. Option D (Minimal) has the second-highest average and option C (Partial) the lowest, while option B is wrong because Full and Partial do not tie under this criterion (they tie only under Maximax)."}},{"itemId":"12b19688-cb7f-58a2-8898-3a07fb40ba67","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9ffaba68-3d22-58c5-aca7-17a987ae9c02","sourceKey":"bank:BUA204:PQ-294","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Applying the Hurwicz criterion with alpha (coefficient of optimism) = 0.55, what is Partial's Hurwicz value?","options":["N10,100","N11,000","N9,675","N11,225"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Hurwicz = alpha x (row maximum) + (1 - alpha) x (row minimum). For Partial this is 0.55(20,000) + 0.45(500) = 11,000 + 225 = N11,225, so D is correct. Option B (N11,000) leaves out the 0.45 x 500 term, option A (N10,100) is Full's value and option C (N9,675) is Minimal's."}},{"itemId":"6d71cdee-255b-5e77-a4c0-63bff164f91c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1b4a4dfe-f813-54a4-9757-5ab227438f7f","sourceKey":"bank:BUA204:PQ-295","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Which product line does the Hurwicz criterion with alpha (coefficient of optimism) = 0.55 recommend?","options":["Minimal","Partial","Full and Minimal (tied)","Full"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"With alpha = 0.55 the Hurwicz values are Full 0.55(20,000) + 0.45(-2,000) = N10,100, Partial 0.55(20,000) + 0.45(500) = N11,225 and Minimal 0.55(18,000) + 0.45(-500) = N9,675. Partial has the highest value, so B is correct; Full (D) comes second, and option C is wrong because Full and Minimal have different values."}},{"itemId":"f8036584-13d5-5056-8784-66ce56e3d9fe","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"698c7cc0-7b3b-5320-9e11-de4de72258c9","sourceKey":"bank:BUA204:PQ-296","parentItemId":null,"revision":1,"payload":{"prompt":"In the Savage (Minimax Regret) method, where each column of the payoff table is a state of nature, the regret for a given cell is calculated as:","options":["Row average minus column average","Column maximum minus the actual payoff in that cell","Actual payoff minus the column minimum","Row maximum minus the actual payoff"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret measures how much you lose by not choosing the best alternative for a given state of nature, so it is the column maximum minus the actual payoff in that cell; B is correct. Option D compares across different states of nature in the same row, which is not the regret idea, while options A and C use averages or minimums instead of the best payoff for that state."}},{"itemId":"263c11cf-759d-5f4d-ab9a-ea96544bb883","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9dd75105-7a7d-5370-ae72-8b19b18b9995","sourceKey":"bank:BUA204:PQ-297","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Savage (Minimax Regret) method, what is Full's regret value in the Low market column?","options":["8,000","3,000","2,000","6,000"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Regret in a cell is the column maximum minus that cell's payoff. The best payoff under a Low market is Minimal's 6,000, and Full earns -2,000 there, so its regret is 6,000 - (-2,000) = 8,000; A is correct. Option D (6,000) is the column maximum itself, and options B and C do not follow from the column-maximum-minus-payoff rule."}},{"itemId":"6f51be8c-93a9-5bfd-a60d-4b1eafe8919b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"eb4e9841-595d-501e-ab10-14f6391fb67b","sourceKey":"bank:BUA204:PQ-298","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Using the Savage (Minimax Regret) criterion, which product line is recommended?","options":["Full","Full and Partial (tied)","Minimal","Partial"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Each line's largest regret is Full 14,000, Partial 17,500 and Minimal 16,000. The smallest of these maximum regrets is Full's 14,000, so A is correct. Options C (Minimal) and D (Partial) carry bigger worst-case regrets, and option B is wrong because Full and Partial do not tie under this criterion."}},{"itemId":"7efb3efa-c6c6-5a66-8a47-9226535ac70d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"41a17eea-741c-547c-9cd1-123cf5dac81d","sourceKey":"bank:BUA204:PQ-299","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer's marketing manager does not know the probabilities of market acceptance for a new product and has this payoff table (N; negative figures are losses) for three product lines under four market states (High, Moderate, Low, Poor): Full = 20,000, 15,000, -2,000, 4,000; Partial = 20,000, 5,000, 1,000, 500; Minimal = 4,000, -500, 6,000, 18,000. Which two criteria both recommend Partial (alone) as the best choice? (Hurwicz uses alpha = 0.55.)","options":["Laplace and Savage","Maximax and Laplace","Maximin and Hurwicz","Savage only"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin picks Partial because its worst payoff (500) is the best of the worst cases, and Hurwicz with alpha = 0.55 also picks Partial at N11,225, so C is correct. Laplace and Savage both recommend Full, which rules out options A and D, and Maximax gives a tie between Full and Partial rather than Partial alone, so option B also fails."}},{"itemId":"1d4958ea-15b4-52d2-8a5a-311fb2c40b57","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"93524b81-3d22-5108-a2f5-2ca28e205f92","sourceKey":"bank:BUA204:PQ-302","parentItemId":null,"revision":1,"payload":{"prompt":"In a five-step data interpretation framework, which step comes FIRST?","options":["Analyse the Data","Clean and Organise the Dataset","Define Questions and Goals","Visualise and Communicate Findings"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"Before any data is cleaned or analysed, you must be clear about the business question or goal you want answered, because that decides which data matters; C is correct. Cleaning and organising (B) and analysing (A) follow once the questions are set, and visualising and communicating findings (D) is the final step."}},{"itemId":"cd6131e9-e6b7-5e1e-afac-41993d5d36a4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e029f0ae-1c54-5974-958b-a058188df524","sourceKey":"bank:BUA204:PQ-304","parentItemId":null,"revision":1,"payload":{"prompt":"In simple linear regression (y-hat = a + bx), 'b' represents:","options":["The slope - change in y for each 1-unit increase in x","The intercept","The predicted value y-hat","R-squared"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"'b' is the slope of the line, showing how much y is expected to change for each one-unit increase in x, so A is correct. Option B is 'a', option C is the predicted value calculated from the whole equation, and option D, R-squared, measures how much of the variation in y the line explains."}},{"itemId":"80a467af-fcab-5007-9160-109df359207a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ce539399-c03d-5093-9862-2adf0c39a6fc","sourceKey":"bank:BUA204:STA-001","parentItemId":null,"revision":1,"payload":{"prompt":"A kiosk in Yaba recorded the number of recharge cards sold on 7 days: 34, 41, 29, 38, 45, 33, 40. What is the arithmetic mean number of cards sold per day (to 2 decimal places)?","options":["43.33","32.50","38.00","37.14"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The mean is Sum x / n = 260 / 7 = 37.14 cards per day. Option A divides by n - 1 = 6 instead of the number of values, option C is the median (the middle value after sorting), and option B divides by 8, one more than the number of days."}},{"itemId":"9f09cfaf-5562-5958-9860-97075ba15b69","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"11a80e1f-b3e2-55ee-a7f8-25d70482bca1","sourceKey":"bank:BUA204:STA-002","parentItemId":null,"revision":1,"payload":{"prompt":"The daily absences recorded in a Lagos factory over 5 days had a mean of 14. Four of the daily figures were 12, 15, 9 and 18. What was the fifth figure?","options":["14","2","13.5","16"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Since mean = Sum x / n, the total must be 14 x 5 = 70; the four known values add to 54, so the fifth value is 70 - 54 = 16. Option C is just the mean of the four known values, and option A wrongly assumes the missing figure must equal the mean. Option B comes from using a total of 14 x 4 = 56 instead of 14 x 5."}},{"itemId":"cd37e379-d7e3-52ee-b3cc-62b2b13cad31","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"92c769f0-7dd2-543d-b63f-b032aed56c72","sourceKey":"bank:BUA204:STA-003","parentItemId":null,"revision":1,"payload":{"prompt":"The monthly sales commissions (N'000) of 9 sales agents in an Ibadan distribution firm were: 52, 47, 61, 39, 58, 44, 50, 66, 41. What is the median commission?","options":["N50,000","N58,000","N52,500","N50,889"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Arranged in order the values are 39, 41, 44, 47, 50, 52, 58, 61, 66, and the middle (5th) value is 50, so the median is N50,000. Option B is the 5th value of the unsorted list, a common slip when the data are not first arranged in order. Option D is the mean, not the median, and option C is just the midpoint of the lowest and highest values."}},{"itemId":"a33715b9-a714-5d26-b6c6-7168ab873687","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7448a1e1-129f-5aa1-8ebd-851fa99c64fa","sourceKey":"bank:BUA204:STA-004","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery in Surulere recorded the number of loaves returned unsold on 8 days: 27, 35, 22, 31, 40, 29, 33, 25. What is the median number of loaves returned?","options":["29.0","31.0","30.0","35.5"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"With an even number of values, the median is the average of the two middle values after sorting: 22, 25, 27, 29, 31, 33, 35, 40 gives (29 + 31) / 2 = 30.0. Options A and B pick only one of the two middle values, and option D averages the 4th and 5th values of the unsorted list."}},{"itemId":"89ccc665-eca6-5cae-be42-2196b27fd759","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7d8eff35-eec6-5cb2-aab5-a2a1bec92ec8","sourceKey":"bank:BUA204:STA-005","parentItemId":null,"revision":1,"payload":{"prompt":"The number of customer complaints received by a GTCO branch on 12 days were: 3, 5, 4, 5, 2, 6, 5, 4, 3, 5, 4, 1. What is the mode?","options":["4","4.5","5","6"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The mode is the value that occurs most often; 5 appears four times, more than any other value, so the mode is 5. Option A (4) appears only three times, option D is the largest value, and option B is the median of the data, not the mode."}},{"itemId":"af03af09-b128-5fe5-8bb9-64470bdc59c2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"92e77367-64a4-5911-8d31-f0f360f37e6e","sourceKey":"bank:BUA204:STA-006","parentItemId":null,"revision":1,"payload":{"prompt":"The ages of 8 apprentices in a Kano auto workshop are: 12, 15, 11, 12, 18, 15, 14, 10. Which statement about the mode is correct?","options":["The mode is 13.375, the average of all the ages","The mode is 12 only, because it appears first","The data are bimodal, with modes 12 and 15","There is no mode, because no value appears more than twice"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Both 12 and 15 occur twice while every other age occurs once, so the data have two modes (bimodal). Option B is wrong because the order of appearance does not matter, option D is wrong because a value appearing twice when others appear once is still a mode, and option A gives the mean, not the mode."}},{"itemId":"4c0f1491-704b-57e9-a082-dc59bba01186","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fd2194ec-c80a-5815-a7a6-4c8580b8a44d","sourceKey":"bank:BUA204:STA-007","parentItemId":null,"revision":1,"payload":{"prompt":"A transport firm recorded the number of breakdowns per bus in a month: 0 breakdowns (6 buses), 1 (10 buses), 2 (12 buses), 3 (8 buses), 4 (4 buses). What is the mean number of breakdowns per bus (to 2 decimal places)?","options":["1.85","7.40","14.80","2.00"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"For a frequency distribution, mean = Sum fx / Sum f = (0 + 10 + 24 + 24 + 16) / 40 = 74 / 40 = 1.85 breakdowns. Option D averages the values 0 to 4 and ignores the frequencies, option C divides Sum fx by the number of categories (5) instead of the total frequency, and option B divides Sum fx by Sum x."}},{"itemId":"188faf1b-ca75-52e2-a81b-ffc368547ff2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"eaedd04e-0f0a-5381-8202-57d10e0b4835","sourceKey":"bank:BUA204:STA-008","parentItemId":null,"revision":1,"payload":{"prompt":"The daily sales (N'000) of 40 POS operators in Ikeja are grouped as: 10 to under 20 (4), 20 to under 30 (9), 30 to under 40 (15), 40 to under 50 (8), 50 to under 60 (4). Using class midpoints, what is the mean daily sales?","options":["N35,000","N34,750","N278,000","N29,750"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Using midpoints 15, 25, 35, 45, 55, Sum fx = 60 + 225 + 525 + 360 + 220 = 1,390 and Sum f = 40, so the mean is 1,390 / 40 = 34.75, i.e. N34,750. Option D uses the lower class limits instead of midpoints, option A averages the midpoints without weighting by frequency, and option C divides Sum fx by the number of classes."}},{"itemId":"b871908e-c6d7-5ffe-aeb8-edafe793e772","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"66a9cce9-c979-5d21-88db-cde202bf71a6","sourceKey":"bank:BUA204:STA-009","parentItemId":null,"revision":1,"payload":{"prompt":"The years of service of 40 staff of a Port Harcourt firm are grouped as: 0 to under 4 (5), 4 to under 8 (12), 8 to under 12 (18), 12 to under 16 (5). Using class midpoints, what is the mean length of service?","options":["83.0 years","8.3 years","10.3 years","8.0 years"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Midpoints are 2, 6, 10 and 14, so Sum fx = 10 + 72 + 180 + 70 = 332 and the mean is 332 / 40 = 8.3 years. Option C uses the upper class limits instead of midpoints, option D is the simple average of the midpoints ignoring frequencies, and option A divides by the number of classes instead of Sum f."}},{"itemId":"fd55616f-9dce-5809-a23d-3e3792ba1a4c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"954d16bc-f17b-56a2-a125-c14476816750","sourceKey":"bank:BUA204:STA-010","parentItemId":null,"revision":1,"payload":{"prompt":"The scores of 50 job applicants on an aptitude test at a Lagos bank are: 20 to under 30 (6), 30 to under 40 (10), 40 to under 50 (16), 50 to under 60 (12), 60 to under 70 (6). Using Median = L + [(n/2 - CF) / f] x c, where CF is the cumulative frequency before the median class, what is the median score (to 2 decimal places)?","options":["45.00","51.25","55.63","45.63"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"n/2 = 25, and the cumulative frequencies 6, 16, 32 show that the 25th score lies in the 40 to under 50 class, so L = 40, CF = 16, f = 16, c = 10. Median = 40 + [(25 - 16) / 16] x 10 = 40 + 5.625 = 45.63. Option A is simply the midpoint of the median class, option C forgets to subtract CF, and option B uses a class width of 20 instead of 10."}},{"itemId":"d1b78811-d9ec-5088-930e-f34d363c273e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ca64d004-807b-5256-a00f-5548fbab5196","sourceKey":"bank:BUA204:STA-011","parentItemId":null,"revision":1,"payload":{"prompt":"The weekly electricity bills (N) of 40 shops in a plaza are grouped as: 100 to under 200 (8), 200 to under 300 (14), 300 to under 400 (12), 400 to under 500 (6). Using Median = L + [(n/2 - CF) / f] x c, what is the median weekly bill (to the nearest naira)?","options":["N300","N286","N346","N283"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"n/2 = 20 and the cumulative frequencies are 8, 22, 34, 40, so the median class is 200 to under 300 with L = 200, CF = 8, f = 14 and c = 100. Median = 200 + [(20 - 8) / 14] x 100 = 200 + 85.71 = N286. Option D wrongly places the median in the 300 to under 400 class, option A divides by the next class's frequency (12) instead of 14, and option C uses (n + 1)/2 and forgets to subtract CF."}},{"itemId":"d4c89363-ad66-537f-9797-46ae63599bd3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f17ec7d8-3eaa-58d6-a462-9340d76795a7","sourceKey":"bank:BUA204:STA-012","parentItemId":null,"revision":1,"payload":{"prompt":"The ages of 60 customers of a Lekki boutique are grouped as: 15 to under 25 (9), 25 to under 35 (18), 35 to under 45 (21), 45 to under 55 (12). Which class contains the median?","options":["35 to under 45","45 to under 55","15 to under 25","25 to under 35"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The median is the (n/2)th = 30th value; cumulative frequencies are 9, 27, 48, 60, so the 30th customer falls in the 35 to under 45 class. Option D is chosen when the cumulative total of 27 is mistaken for having passed 30, while options B and C are classes far from the middle position."}},{"itemId":"151d5cc6-0e12-5576-8f4d-8aa866865256","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f7d9caa5-c6a6-516c-a1cc-cca2d0631c85","sourceKey":"bank:BUA204:STA-013","parentItemId":null,"revision":1,"payload":{"prompt":"The daily output (units) of 50 tailors in Aba is grouped as: 10 to under 20 (7), 20 to under 30 (13), 30 to under 40 (19), 40 to under 50 (11). Using Mode = L + [d1 / (d1 + d2)] x c, where d1 and d2 are the differences between the modal class frequency and the frequencies of the classes before and after it, what is the mode (to 2 decimal places)?","options":["35.00","33.33","35.71","34.29"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The modal class is 30 to under 40 (highest frequency 19), so L = 30, d1 = 19 - 13 = 6, d2 = 19 - 11 = 8 and c = 10. Mode = 30 + [6 / 14] x 10 = 30 + 4.29 = 34.29. Option A is just the midpoint of the modal class, option C swaps d1 and d2, and option B uses 6 / 18, adding the modal frequency differences incorrectly."}},{"itemId":"5d96c314-e765-5088-9443-95744b6e96b0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c55afc4-e442-595d-8362-a6755cd42ced","sourceKey":"bank:BUA204:STA-014","parentItemId":null,"revision":1,"payload":{"prompt":"The prices (N) charged for the same bag of rice by 6 traders at Mile 12 market are: 4,500; 3,800; 5,200; 4,100; 6,100; 3,950. What is the range of the prices?","options":["N4,608","N1,600","N2,300","N2,150"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Range = Highest value - Lowest value = 6,100 - 3,800 = N2,300. Option B subtracts the first listed price from the highest (6,100 - 4,500), option D uses 3,950 as the lowest value, and option A is the mean price, which is a measure of central tendency rather than dispersion."}},{"itemId":"89a5972f-3489-5a5d-9230-04b443b8aa5b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"278f3900-7d53-5964-8d96-95050d8e7dad","sourceKey":"bank:BUA204:STA-015","parentItemId":null,"revision":1,"payload":{"prompt":"Treating the data as a population, what is the variance of the weekly overtime hours of 5 security staff: 8, 12, 10, 14, 6? (Use variance = Sum(x - mean)^2 / n.)","options":["10.00","8.00","2.83","2.40"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The mean is 50 / 5 = 10, the squared deviations are 4, 4, 0, 16, 16, summing to 40, so the population variance is 40 / 5 = 8.00. Option A divides by n - 1 = 4 (the sample formula), option C is the standard deviation (the square root of 8), and option D is the mean absolute deviation, which ignores squaring."}},{"itemId":"cac45dbf-1495-513a-b3da-0ec0e029e3cb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aa0d05fc-d1d6-5354-a7cb-462ba45180d3","sourceKey":"bank:BUA204:STA-016","parentItemId":null,"revision":1,"payload":{"prompt":"A quality officer takes a SAMPLE of 5 cartons and counts the damaged eggs in each: 15, 22, 18, 25, 20. Using the sample formula variance = Sum(x - mean)^2 / (n - 1), what is the sample variance?","options":["11.60","14.50","58.00","3.81"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The mean is 100 / 5 = 20, the squared deviations are 25, 4, 4, 25, 0, summing to 58, and the sample variance is 58 / 4 = 14.50. Option A divides by n = 5 (the population formula), option D is the sample standard deviation, and option C is the sum of squared deviations before dividing."}},{"itemId":"b85d2174-9850-5d81-8815-27a9bcc25c2b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cbe82e7f-2ea2-54ee-885b-5562f09f0709","sourceKey":"bank:BUA204:STA-017","parentItemId":null,"revision":1,"payload":{"prompt":"The daily number of passengers carried by a keke rider over 5 days were 42, 38, 45, 35, 40. Treating these as a population, what is the standard deviation (to 2 decimal places)?","options":["3.81","11.60","1.67","3.41"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Mean = 200 / 5 = 40; squared deviations are 4, 4, 25, 25, 0, summing to 58; population variance = 58 / 5 = 11.6 and SD = sqrt(11.6) = 3.41. Option B stops at the variance without taking the square root, option A uses the sample formula (divide by 4), and option C takes the square root of the mean absolute deviation."}},{"itemId":"73247467-5100-5068-b07e-365d3af5ec08","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"435d03b7-5a03-53f4-a310-1ee9721b0f9b","sourceKey":"bank:BUA204:STA-018","parentItemId":null,"revision":1,"payload":{"prompt":"A sample of 6 days' deliveries by a dispatch rider gave: 6, 9, 12, 7, 11, 9. Using the sample standard deviation s = sqrt[Sum(x - mean)^2 / (n - 1)], what is s (to 2 decimal places)?","options":["2.08","2.28","2.60","5.20"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Mean = 54 / 6 = 9; squared deviations 9, 0, 9, 4, 4, 0 sum to 26; sample variance = 26 / 5 = 5.2 and s = sqrt(5.2) = 2.28. Option A uses the population formula (divide by 6), option D is the sample variance without the square root, and option C halves the variance instead of square-rooting it."}},{"itemId":"314dcaa5-2fc6-5c6c-ad11-c0e184e9c9c8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b1e8b05d-2d47-5e21-b153-1bf05d3169f2","sourceKey":"bank:BUA204:STA-019","parentItemId":null,"revision":1,"payload":{"prompt":"Two Abuja sales teams each averaged N60,000 weekly sales over 5 weeks. Team X (N'000): 60, 64, 58, 62, 56. Team Y (N'000): 40, 80, 70, 50, 60. Using population standard deviations, which conclusion is correct?","options":["Team Y (SD about 14.14) is more consistent than Team X (SD about 2.83)","Both teams are equally consistent because their means are equal","Team X (SD about 8.00) is less consistent than Team Y (SD about 7.07)","Team X (SD about 2.83) is more consistent than Team Y (SD about 14.14)"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Team X has squared deviations summing to 40, so SD = sqrt(40/5) = 2.83, while Team Y's sum to 1,000, giving SD = sqrt(200) = 14.14; the smaller SD means Team X's sales vary less from week to week. Option A reverses the interpretation (a larger SD means less consistency), and option B wrongly assumes equal means imply equal spread."}},{"itemId":"457b2f51-0974-5be7-a4c9-9f880f155e3a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9b7a2bc0-aa7c-515c-96f6-07046c3aadd6","sourceKey":"bank:BUA204:STA-020","parentItemId":null,"revision":1,"payload":{"prompt":"The standard deviation of the monthly fuel cost of a logistics firm is N3,500. What is the variance of the monthly fuel cost?","options":["N59.16 (the square root of 3,500)","N7,000 (twice 3,500)","12,250,000 naira-squared (3,500^2)","N1,750 (half of 3,500)"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Standard deviation is the square root of the variance, so the variance is the SD squared: 3,500^2 = 12,250,000 (in squared naira). Option A takes the square root instead of squaring, while options D and B halve or double the SD, which has no statistical meaning."}},{"itemId":"7d024265-483d-55ed-b30d-5ff8c5da074f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c96d922-b1f3-5553-9a24-250a46c5dadb","sourceKey":"bank:BUA204:STA-021","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos supermarket's daily revenue has a mean of N250,000 and a standard deviation of N30,000. What is the coefficient of variation?","options":["N220,000","88.0%","12.0%","833.3%"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"CV = (SD / mean) x 100% = (30,000 / 250,000) x 100% = 12.0%. Option D inverts the ratio (mean / SD), option B subtracts the CV from 100%, and option A simply subtracts the SD from the mean, which is not a relative measure."}},{"itemId":"80457e80-67cb-5cfc-9afe-68fcafb17d49","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"77292333-9aee-54b0-b4da-df6d16b0fec1","sourceKey":"bank:BUA204:STA-022","parentItemId":null,"revision":1,"payload":{"prompt":"Share P has a mean monthly return of 30 kobo with SD 4.5 kobo; Share Q has a mean of 75 kobo with SD 9 kobo. Using the coefficient of variation, which share is relatively riskier?","options":["Share P, CV = 15.0% against 12.0% for Q","Share Q, because its SD of 9 kobo is larger","Share Q, CV = 8.3% against 6.7% for P","Both are equally risky, CV = 15.0% each"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"CV measures dispersion relative to the mean: P = 4.5 / 30 x 100% = 15.0% and Q = 9 / 75 x 100% = 12.0%, so P is relatively riskier even though its SD is smaller. Option B compares raw SDs, which is misleading when means differ, and option C inverts the CV formula."}},{"itemId":"60714668-122d-5c79-964d-6abfd40a54ac","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9e4c6778-fac3-5bb7-be30-e499d4e028af","sourceKey":"bank:BUA204:STA-023","parentItemId":null,"revision":1,"payload":{"prompt":"The daily production (crates) of a soft-drink line over 5 days was 20, 25, 30, 25, 25. Using the population standard deviation, what is the coefficient of variation (to 2 decimal places)?","options":["14.14%","7.91%","40.00%","12.65%"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Mean = 125 / 5 = 25; squared deviations 25, 0, 25, 0, 0 sum to 50, so SD = sqrt(50/5) = 3.162 and CV = 3.162 / 25 x 100% = 12.65%. Option C uses the variance (10) instead of the SD, option A uses the sample SD (divide by 4), and option B inverts the ratio."}},{"itemId":"c8d1add1-9ed4-57de-81e4-411479e63b7c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0f3b89cb-7fe5-5838-a5ad-b07859156b7f","sourceKey":"bank:BUA204:STA-024","parentItemId":null,"revision":1,"payload":{"prompt":"For a population of 10 monthly sales figures (N'000), Sum x = 80 and Sum x^2 = 700. Using variance = (Sum x^2 / n) - (mean)^2, what is the population variance?","options":["70","6.67","62","6"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The mean is 80 / 10 = 8, so variance = 700 / 10 - 8^2 = 70 - 64 = 6. Option A forgets to subtract the squared mean, option B applies the sample (n - 1) version, and option C subtracts the mean rather than the squared mean."}},{"itemId":"81f710be-f0e6-50c6-a3b2-361eed01c415","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2f57f8a8-201a-531b-99fa-51ed5493e468","sourceKey":"bank:BUA204:STA-025","parentItemId":null,"revision":1,"payload":{"prompt":"A hotel recorded the number of rooms cleaned per hour by 10 cleaners: 1 room (2 cleaners), 2 rooms (5), 3 rooms (2), 4 rooms (1). Treating this as a population, what is the variance (Sum f(x - mean)^2 / Sum f)?","options":["0.76","0.87","0.84","1.34"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The mean is Sum fx / Sum f = (2 + 10 + 6 + 4) / 10 = 2.2; Sum f(x - 2.2)^2 = 2(1.44) + 5(0.04) + 2(0.64) + 1(3.24) = 7.6, so variance = 7.6 / 10 = 0.76. Option D ignores the frequencies, option B is the standard deviation, and option C divides by Sum f - 1 = 9."}},{"itemId":"9abf5bc4-426e-5d7a-ade8-4a45cb922acc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aa2fdd31-4437-5d8f-8517-4848880feb8c","sourceKey":"bank:BUA204:STA-026","parentItemId":null,"revision":1,"payload":{"prompt":"The monthly salaries of 20 clerks have a mean of N85,000 and a standard deviation of N6,000. If every clerk receives a flat increase of N5,000, what are the new mean and standard deviation?","options":["Mean N90,000; SD N6,000","Mean N85,000; SD N6,000","Mean N90,000; SD N11,000","Mean N90,000; SD N6,353"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Adding the same amount to every value shifts the whole distribution, so the mean rises by N5,000 to N90,000, but each deviation from the mean is unchanged, so the SD stays at N6,000. Option C wrongly adds the increase to the SD, option B ignores the increase altogether, and option D scales the SD in proportion to the mean."}},{"itemId":"34973a44-6d9e-5ecf-9967-c7eea74c7b43","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"173cfc07-1bb8-5945-807d-8d31bf76ffff","sourceKey":"bank:BUA204:STA-027","parentItemId":null,"revision":1,"payload":{"prompt":"Scores on a bank's recruitment test are normally distributed with mean 65 and standard deviation 8. What is the z-score of a candidate who scored 78?","options":["1.040","9.750","1.625","0.203"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"z = (X - mu) / sigma = (78 - 65) / 8 = 1.625, so the candidate is 1.625 standard deviations above the mean. Option D divides by the variance (64) instead of the SD, option B forgets to subtract the mean, and option A multiplies by sigma instead of dividing."}},{"itemId":"fba694e2-c01e-5a55-adcd-48b5fd651a88","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e02dbef4-54d4-5f0d-a36b-33eed57fb2e2","sourceKey":"bank:BUA204:STA-028","parentItemId":null,"revision":1,"payload":{"prompt":"The time taken to serve customers at a fast-food outlet is normally distributed with mean 50 seconds and SD 5 seconds. What is the z-score for a service time of 42 seconds?","options":["-1.6","0.84","-0.32","1.6"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"z = (42 - 50) / 5 = -1.6; the negative sign shows the time is below the mean. Option D drops the sign, option C divides by the variance (25), and option B divides the value by the mean, which is not a z-score."}},{"itemId":"e903a29e-f05c-5258-bf30-f526acf316b2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e8078693-dbb6-5a29-bc0b-3445f835046f","sourceKey":"bank:BUA204:STA-029","parentItemId":null,"revision":1,"payload":{"prompt":"Weekly sales of a product are normally distributed with mean 120 units and SD 16 units. A store manager wants the sales level that is 1.5 standard deviations above the mean. What is it?","options":["121.5 units","144 units","180 units","96 units"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Rearranging z = (X - mu) / sigma gives X = mu + z sigma = 120 + 1.5 x 16 = 144 units. Option A adds z without multiplying by sigma, option C multiplies the mean by 1.5, and option D subtracts, giving the value 1.5 SD below the mean."}},{"itemId":"ba9f7c7e-ebb0-57ee-8e12-357959a504a2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"21addb2b-196c-5633-8a70-a37b9eb8d13b","sourceKey":"bank:BUA204:STA-030","parentItemId":null,"revision":1,"payload":{"prompt":"Daily cash withdrawals at an ATM are normally distributed with mean N2,400,000 and SD N300,000. About what percentage of days have withdrawals between N2,100,000 and N2,700,000?","options":["95%","68%","99.7%","34%"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"N2,100,000 and N2,700,000 are exactly one SD (N300,000) below and above the mean, and the empirical rule puts about 68% of observations within +/-1 SD. Option A is the figure for +/-2 SD and option C for +/-3 SD, while option D is only the half on one side of the mean."}},{"itemId":"0a026808-7754-56ce-ae8c-f7c9e2250d88","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"555f2ccd-42bb-5d31-af3c-420aaef7f0e0","sourceKey":"bank:BUA204:STA-031","parentItemId":null,"revision":1,"payload":{"prompt":"The weights of bags of cement are normally distributed with mean 50 kg and SD 0.4 kg. Using the empirical rule, about what percentage of bags weigh MORE than 50.8 kg?","options":["2.5%","47.5%","16%","5%"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"50.8 kg is 2 SD above the mean; about 95% of bags lie within +/-2 SD, leaving 5% in the two tails, so about 2.5% lie above 50.8 kg by symmetry. Option D forgets to split the 5% between the two tails, option C is the tail beyond 1 SD, and option B is the share between the mean and +2 SD."}},{"itemId":"634e3d7e-6782-5473-8127-3a40c762d3da","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"77acc9e2-1c78-5757-8ab0-08b008092b63","sourceKey":"bank:BUA204:STA-032","parentItemId":null,"revision":1,"payload":{"prompt":"A firm employs 2,000 machine operators whose productivity scores are normally distributed with mean 70 and SD 6. Using the empirical rule, about how many operators score between 52 and 88?","options":["1,900","2,000","1,360","1,994"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"52 and 88 are 3 SD (18 points) below and above the mean, so about 99.7% of operators lie in this range: 0.997 x 2,000 = 1,994. Option A uses 95% (the +/-2 SD figure), option C uses 68% (the +/-1 SD figure), and option B assumes every operator falls within the range."}},{"itemId":"8abafa5c-11d7-50d8-8e52-354d36f5366a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0cdac0af-2184-50f8-a4ca-ffeb3ce3f343","sourceKey":"bank:BUA204:STA-033","parentItemId":null,"revision":1,"payload":{"prompt":"A bottling plant fills sachet water with a process mean of 500 ml and a process standard deviation of 4 ml. Using limits set at 3 standard deviations, what is the Upper Control Limit?","options":["512 ml","508 ml","504 ml","1,500 ml"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"UCL = mean + 3 sigma = 500 + 3(4) = 512 ml. Option C uses only 1 SD, option B uses 2 SD, and option D multiplies the mean by 3 instead of adding 3 standard deviations."}},{"itemId":"223bd05d-6706-5cc7-8d3a-002d5247db75","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b2871130-8acd-5b00-8bfb-377c2b313429","sourceKey":"bank:BUA204:STA-034","parentItemId":null,"revision":1,"payload":{"prompt":"The average length of steel rods produced by a Kaduna mill is 120 cm with a process standard deviation of 1.5 cm. Using 3-sigma control limits, what is the Lower Control Limit?","options":["117.0 cm","118.5 cm","124.5 cm","115.5 cm"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"LCL = mean - 3 sigma = 120 - 3(1.5) = 115.5 cm. Option B subtracts only one SD, option A subtracts two SDs, and option C is the Upper Control Limit, not the lower one."}},{"itemId":"41ab7cb8-2b8d-5e81-8196-0b4366fd1ae4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"74215be8-b92f-5641-a509-7985fb8f0b13","sourceKey":"bank:BUA204:STA-035","parentItemId":null,"revision":1,"payload":{"prompt":"A process has mean 80 g and standard deviation 2 g, with 3-sigma control limits. Sample means for five hours were 83.5 g, 78.0 g, 86.4 g, 75.2 g and 81.9 g. Which hour signals that the process may be out of control?","options":["The hour with 83.5 g","The hour with 75.2 g","The hour with 78.0 g","The hour with 86.4 g"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The limits are 80 +/- 3(2), i.e. LCL = 74 g and UCL = 86 g, and only 86.4 g lies outside them, so it signals a possible special cause to investigate. Options A and B lie more than 1 SD from the mean but are still inside the 3-sigma limits, and option C is close to the mean."}},{"itemId":"e0286945-14d8-53a0-800f-0260c7b8aea8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"addc215d-99e2-56e7-a201-7cfa34fa61a4","sourceKey":"bank:BUA204:STA-036","parentItemId":null,"revision":1,"payload":{"prompt":"A survey of 36 households in Ikorodu found mean monthly spending on transport of N4,200. The population standard deviation is N600. What is the 95% confidence interval for the mean? (CI = mean +/- z x sigma / sqrt n.)","options":["N4,004 to N4,396","N3,024 to N5,376","N4,167.33 to N4,232.67","N4,036 to N4,364"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The margin is 1.96 x 600 / sqrt(36) = 1.96 x 100 = N196, so the interval is 4,200 +/- 196, i.e. N4,004 to N4,396. Option D uses the 90% value 1.645, option C divides by n instead of sqrt n, and option B forgets to divide sigma by sqrt n at all."}},{"itemId":"fe3fd93a-e5cb-5c88-a0a3-02655e2e64ff","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b99e6a39-8053-559c-ac71-b1b6e2759648","sourceKey":"bank:BUA204:STA-037","parentItemId":null,"revision":1,"payload":{"prompt":"A sample of 25 customers spent an average of 52 minutes in a shopping mall; the population SD is 10 minutes. What is the UPPER limit of the 99% confidence interval for the mean time (to 2 decimal places)?","options":["53.03 minutes","57.15 minutes","55.92 minutes","46.85 minutes"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Upper limit = mean + z x sigma / sqrt n = 52 + 2.576 x 10 / 5 = 52 + 5.152 = 57.15 minutes. Option C uses the 95% value 1.96, option D is the lower limit, and option A divides sigma by n instead of sqrt n."}},{"itemId":"b33880ea-6061-5a8d-b8ee-f555c29fe527","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"990aa078-44a9-5218-a5c7-1a7c85183304","sourceKey":"bank:BUA204:STA-038","parentItemId":null,"revision":1,"payload":{"prompt":"For a 90% confidence interval for the mean daily sales of a supermarket chain, a sample of 64 days is used and the population SD is N800. What is the margin of error (z x sigma / sqrt n) to 2 decimal places?","options":["N20.56","N196.00","N257.60","N164.50"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Margin of error = 1.645 x 800 / sqrt(64) = 1.645 x 100 = N164.50. Option B uses the 95% value 1.96, option C uses the 99% value 2.576, and option A divides by 64 instead of its square root."}},{"itemId":"f680c95f-9072-5258-8fe1-84681aada3b0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a913e887-d8e6-52ba-9ae1-95f8ba321996","sourceKey":"bank:BUA204:STA-039","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing officer recorded radio adverts per week (x) and sales in N'000 (y): (1, 10), (2, 14), (3, 15), (4, 19), (5, 22). What is Sum xy?","options":["1,200","95","1,421","269"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Sum xy multiplies each pair and adds: 10 + 28 + 45 + 76 + 110 = 269. Option A is Sum x times Sum y (15 x 80), which is a different term in the formula, option C adds Sum x^2 and Sum y^2, and option B merely adds Sum x and Sum y."}},{"itemId":"2cd40ba5-2b3c-5707-a6ae-6332c6c6bfb2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5ec3c2c5-fac7-58f7-8af9-a52d07b61a94","sourceKey":"bank:BUA204:STA-040","parentItemId":null,"revision":1,"payload":{"prompt":"Using the same data, (1, 10), (2, 14), (3, 15), (4, 19), (5, 22), where n = 5, Sum x = 15, Sum y = 80, Sum xy = 269, Sum x^2 = 55 and Sum y^2 = 1,366, what is Pearson's correlation coefficient r (to 3 decimal places)?","options":["0.989","0.978","0.007","2.900"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"r = [5(269) - 15(80)] / sqrt{[5(55) - 15^2][5(1,366) - 80^2]} = 145 / sqrt(50 x 430) = 145 / 146.63 = 0.989, a very strong positive relationship. Option B is r^2 (the coefficient of determination), option D is the regression slope b (145 / 50), and option C forgets to take the square root of the denominator."}},{"itemId":"e2654475-2e1d-5810-bb98-f58d0ccea2ea","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6667d3a1-db0a-57d8-9b34-caf1b1c0442b","sourceKey":"bank:BUA204:STA-041","parentItemId":null,"revision":1,"payload":{"prompt":"A phone dealer in Computer Village records the price of a handset in N'0,000 (x) and weekly units sold (y): (3, 40), (5, 36), (7, 31), (9, 27), (11, 21). Given n = 5, Sum x = 35, Sum y = 155, Sum xy = 991, Sum x^2 = 285, Sum y^2 = 5,027, what is Pearson's r (to 3 decimal places)?","options":["0.998","0.995","-2.350","-0.998"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Numerator = 5(991) - 35(155) = -470; denominator = sqrt{[5(285) - 35^2][5(5,027) - 155^2]} = sqrt(200 x 1,110) = 471.17; r = -470 / 471.17 = -0.998, a very strong negative relationship (higher price, fewer sales). Option A drops the negative sign, option B is r^2, which can never be negative, and option C is the regression slope b, not r."}},{"itemId":"dba0e6cd-9310-5301-ada3-5764cc11c88e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a784eaa1-75c7-5f18-8bcf-542a64c51783","sourceKey":"bank:BUA204:STA-042","parentItemId":null,"revision":1,"payload":{"prompt":"For two variables, Sum(x - x-bar)(y - y-bar) = 84, Sum(x - x-bar)^2 = 60 and Sum(y - y-bar)^2 = 196. Using r = Sum[(x - x-bar)(y - y-bar)] / sqrt{Sum(x - x-bar)^2 x Sum(y - y-bar)^2}, what is r (to 3 decimal places)?","options":["3.863","0.429","0.775","1.400"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"r = 84 / sqrt(60 x 196) = 84 / 108.44 = 0.775, a strong positive relationship. Option B divides only by Sum(y - y-bar)^2, option D is 84 / 60, which is the regression slope b rather than r, and option A adds the two square roots instead of multiplying inside one root."}},{"itemId":"2629b262-4f98-54a9-b464-703510dea166","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a55270fc-beaa-504a-88a4-f36e6a5a33fd","sourceKey":"bank:BUA204:STA-043","parentItemId":null,"revision":1,"payload":{"prompt":"The correlation between training hours and productivity at a Lagos factory is r = 0.85. What percentage of the variation in productivity is explained by training hours?","options":["85%","92.20%","72.25%","15%"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The coefficient of determination is r^2 = 0.85^2 = 0.7225, so 72.25% of the variation in productivity is explained by training hours. Option A uses r itself, option B takes the square root of r, and option D is simply 1 - r, which has no meaning here."}},{"itemId":"05d33abe-75b5-59ad-a4c6-6668f47e1ba9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c727b561-45e1-5fee-9608-7c655a344df2","sourceKey":"bank:BUA204:STA-044","parentItemId":null,"revision":1,"payload":{"prompt":"A regression of weekly demand on price gives y-hat = 900 - 12x, with coefficient of determination r^2 = 0.64. What is the correlation coefficient r?","options":["-0.64","-0.80","+0.80","+0.4096"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"r is the square root of r^2, so |r| = sqrt(0.64) = 0.80, and r takes the sign of the slope; since b = -12 is negative, r = -0.80. Option C ignores the sign of the slope, option A confuses r with r^2, and option D squares 0.64 instead of square-rooting it."}},{"itemId":"145ff9d0-f4ef-571b-bc2e-fb58153d6bf8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f6951d40-b2dd-5c36-822b-de514f357013","sourceKey":"bank:BUA204:STA-045","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos eatery recorded promotion spending x (N'000) and sales y (N'000) over 5 weeks: (2, 15), (4, 19), (6, 26), (8, 30), (10, 35). With n = 5, Sum x = 30, Sum y = 125, Sum xy = 852 and Sum x^2 = 220, what is the regression slope b?","options":["0.46","2.55","3.87","1.00"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"b = [n Sum xy - Sum x Sum y] / [n Sum x^2 - (Sum x)^2] = [5(852) - 30(125)] / [5(220) - 30^2] = 510 / 200 = 2.55. Option A forgets to subtract (Sum x)^2 in the denominator, option C divides Sum xy by Sum x^2 directly, and option D is the correlation coefficient, not the slope."}},{"itemId":"939d6da6-b0fe-5e04-8acd-f5a9c96728e2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3a94b865-b88b-5b55-9884-09496823e4f5","sourceKey":"bank:BUA204:STA-046","parentItemId":null,"revision":1,"payload":{"prompt":"For the same eatery data (x-bar = 6, y-bar = 25) the slope is b = 2.55. What is the intercept a of the regression line y-hat = a + bx?","options":["-57.75","9.70","22.45","40.30"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"a = y-bar - b x-bar = 25 - 2.55(6) = 25 - 15.3 = 9.70. Option D adds instead of subtracting, option A swaps x-bar and y-bar, and option C subtracts b without multiplying it by x-bar."}},{"itemId":"df2aff89-71b2-565d-bd53-7f2e230b0fae","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c8ab3cb0-d8ff-58d3-bc59-6ee199912b70","sourceKey":"bank:BUA204:STA-047","parentItemId":null,"revision":1,"payload":{"prompt":"Using the regression line y-hat = 9.7 + 2.55x, where x is weekly promotion spending (N'000) and y is weekly sales (N'000), what sales are predicted when N12,000 is spent on promotion?","options":["N147,000","N40,300","N118,950","N30,600"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Substituting x = 12: y-hat = 9.7 + 2.55(12) = 9.7 + 30.6 = 40.3, i.e. N40,300. Option A multiplies both a and b by x, option D leaves out the intercept, and option C multiplies the intercept rather than the slope by x."}},{"itemId":"b1003e97-6816-539b-92fc-2feda7abb6e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cc4201cc-63e2-5573-afa6-546f3a8057d7","sourceKey":"bank:BUA204:STA-048","parentItemId":null,"revision":1,"payload":{"prompt":"A recruitment agency recorded years of experience x and monthly pay y (N'0,000) for 5 staff: (2, 8), (3, 11), (5, 14), (6, 17), (9, 25). Given Sum x = 25, Sum y = 75, Sum xy = 446 and Sum x^2 = 155, use y-hat = a + bx (unrounded b and a) to predict the pay of someone with 10 years' experience (to 2 decimal places).","options":["31.57","13.17","23.67","26.83"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"b = [5(446) - 25(75)] / [5(155) - 625] = 355 / 150 = 2.3667 and a = 15 - 2.3667(5) = 3.1667, so y-hat = 3.1667 + 2.3667(10) = 26.83 (about N268,300). Option C ignores the intercept, option A predicts for x = 12 instead of 10, and option B adds 10 to a without multiplying by b."}},{"itemId":"47b6053f-a955-5d5a-bec7-b917c87c97b7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9c539f5b-e844-5ac8-8d0a-3788ae5d8998","sourceKey":"bank:BUA204:STA-049","parentItemId":null,"revision":1,"payload":{"prompt":"A firm estimates y-hat = 45 + 3.2x, where y is monthly sales (N'000) and x is the number of sales calls made. What does the model predict will happen to sales if a representative makes 5 MORE calls than before?","options":["Sales rise by N48,200","Sales rise by N3,200","Sales rise by N16,000","Sales rise by N61,000"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The slope b = 3.2 is the change in y for each one-unit increase in x, so 5 extra calls raise predicted sales by 5 x 3.2 = 16 thousand, i.e. N16,000; the intercept does not affect a change. Option D adds the intercept to the change, option B is the effect of only one extra call, and option A adds b to the intercept."}},{"itemId":"2374e421-187e-55f2-a717-316f394e1e0f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"782d02e8-c8da-5f4c-b983-a7b6c7c0c940","sourceKey":"bank:BUA204:STA-050","parentItemId":null,"revision":1,"payload":{"prompt":"Two judges ranked 6 entries in a Lagos small-business pitch competition. Judge 1: A=1, B=2, C=3, D=4, E=5, F=6. Judge 2: A=2, B=1, C=4, D=3, E=6, F=5. Using Spearman's R = 1 - 6 Sum d^2 / [n(n^2 - 1)], what is R (to 3 decimal places)?","options":["0.171","0.971","0.829","0.838"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Every pair of ranks differs by 1, so Sum d^2 = 6 and R = 1 - 6(6) / [6(35)] = 1 - 36 / 210 = 0.829, a strong agreement between the judges. Option D uses n^2 + 1 instead of n^2 - 1, option B leaves out the 6 in the numerator, and option A forgets to subtract from 1."}},{"itemId":"d72d7605-55ed-5864-97ca-ca5c3f40a1b1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f1da3e39-4f19-5524-b0e4-959607a18781","sourceKey":"bank:BUA204:STA-051","parentItemId":null,"revision":1,"payload":{"prompt":"Five provision shops recorded weekly sales of a detergent (cartons) and their selling prices (N): Shop 1 (45, 700), Shop 2 (38, 820), Shop 3 (52, 650), Shop 4 (30, 900), Shop 5 (41, 760). Ranking each variable from highest = 1, what is Spearman's rank correlation R = 1 - 6 Sum d^2 / [n(n^2 - 1)]?","options":["-1.00","1.00","0.00","-0.50"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Sales ranks are 2, 4, 1, 5, 3 and price ranks are 4, 2, 5, 1, 3, giving d^2 values 4, 4, 16, 16, 0, so Sum d^2 = 40 and R = 1 - 240 / 120 = -1.00, a perfect negative rank correlation (higher price, lower sales). Option B drops the sign, while options C and D would need Sum d^2 of 20 and 30 respectively."}},{"itemId":"0c1eadff-9d91-5f39-8a93-02eda7786c20","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7b861f42-ee36-5f31-be46-8665fbbeb8ab","sourceKey":"bank:BUA204:STA-052","parentItemId":null,"revision":1,"payload":{"prompt":"In ranking 10 branch managers on two performance criteria, an HR officer finds Sum d^2 = 33. Using R = 1 - 6 Sum d^2 / [n(n^2 - 1)], what is Spearman's rank correlation (to 2 decimal places)?","options":["0.80","0.20","0.97","-1.20"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"R = 1 - 6(33) / [10(100 - 1)] = 1 - 198 / 990 = 0.80, a strong positive agreement between the two criteria. Option D uses n(n - 1) in the denominator, option B forgets to subtract the fraction from 1, and option C leaves out the 6."}},{"itemId":"4eaa3d76-9433-5c88-85b7-315b6e4181f6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"28c5bf2b-98e5-5dcc-81d5-da45b8c3ec31","sourceKey":"bank:BUA204:STA-053","parentItemId":null,"revision":1,"payload":{"prompt":"For the daily sales of 40 roadside vendors, the first quartile is N3,200, the median is N4,500 and the third quartile is N6,100. What is the interquartile range?","options":["N1,600","N4,650","N1,300","N2,900"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"IQR = Q3 - Q1 = 6,100 - 3,200 = N2,900, the spread of the middle 50% of the data. Option C is the median minus Q1 and option A is Q3 minus the median, each covering only a quarter of the data, while option B averages Q1 and Q3."}},{"itemId":"f55f530a-ad7a-5242-981d-7046d1d9f7b0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6d5ec5d0-5ad4-554b-a15d-13f1059ad7f9","sourceKey":"bank:BUA204:STA-054","parentItemId":null,"revision":1,"payload":{"prompt":"A company has 20 field staff in Lagos with a mean monthly allowance of N45,000 and 30 field staff in Abuja with a mean of N55,000. What is the mean allowance of all 50 staff combined?","options":["N49,000","N50,000","N51,000","N55,000"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The combined mean weights each group mean by its size: (20 x 45,000 + 30 x 55,000) / 50 = 2,550,000 / 50 = N51,000. Option B is the simple average of the two means, which ignores the different group sizes, option A attaches the weights to the wrong groups, and option D has no valid basis."}},{"itemId":"6a4fe48f-ec9f-5406-8782-5d649e613fe3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9c3a6994-f1f3-5b8b-a911-c8a99e429f32","sourceKey":"bank:BUA204:STA-055","parentItemId":null,"revision":1,"payload":{"prompt":"The daily earnings (N'00) of 7 traders are 60, 65, 70, 72, 75, 80 and 450. Which measure best represents typical earnings, and what is its value?","options":["The range, 390","The mean, 124.57","The mode, 450","The median, 72"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"The extreme value 450 pulls the mean up to 124.57, far above what six of the seven traders earn, whereas the median (the 4th sorted value, 72) is not affected by the outlier. Option B is distorted by the extreme value, option C is wrong because no value repeats, and option A is a measure of dispersion, not of typical earnings."}},{"itemId":"8207cb7a-67cd-5a31-9a20-cfebdfb1ad8f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cff1a973-6291-503b-ba04-6c0d926d2d91","sourceKey":"bank:BUA204:STA-056","parentItemId":null,"revision":1,"payload":{"prompt":"A student recorded her weekly spending on food (N) over 6 weeks: 1,200; 950; 1,430; 1,100; 870; 1,310. What was her mean weekly spending (to the nearest naira)?","options":["N980","N1,150","N1,372","N1,143"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Mean = Sum x / n = 6,860 / 6 = N1,143. Option C divides by 5 instead of 6, option B is the median (average of the two middle values), and option A divides by 7, one more than the number of weeks."}},{"itemId":"f3e707e2-ec6b-579c-9dfe-35da02948a6a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"52cc1ba1-ab72-5f2b-90d1-cca66ed560b0","sourceKey":"bank:BUA204:STA-057","parentItemId":null,"revision":1,"payload":{"prompt":"Ada scored 72 in Accounting (class mean 60, SD 8) and 84 in Economics (class mean 75, SD 5). Using z-scores, in which subject did she perform better relative to her classmates?","options":["Accounting, z = 0.19 against 0.36","Accounting, because its gap of 12 marks above the mean is larger","Both equally, because each score is above its class mean","Economics, z = 1.80 against 1.50"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"z standardises each score: Accounting z = (72 - 60) / 8 = 1.50 and Economics z = (84 - 75) / 5 = 1.80, so Economics is the stronger relative performance. Option B compares raw gaps from the mean and ignores the different spreads, option C ignores how far above the mean each score is in SD units, and option A divides by the variances instead of the SDs."}},{"itemId":"b58c1fdf-8ab4-5b38-b7ec-39b47c1bf690","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8832e7be-1b98-5572-93b2-00bc9ddff30b","sourceKey":"bank:BUA204:STA-058","parentItemId":null,"revision":1,"payload":{"prompt":"Monthly phone bills of a company's staff are normally distributed with mean N8,000 and SD N1,200. Within which range do about 95% of the bills lie?","options":["N6,800 to N9,200","N7,040 to N8,960","N5,600 to N10,400","N4,400 to N11,600"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"About 95% of a normal distribution lies within +/-2 SD of the mean: 8,000 +/- 2(1,200) gives N5,600 to N10,400. Option A is the +/-1 SD range (about 68%), option D is the +/-3 SD range (about 99.7%), and option B wrongly takes 12% of the mean on each side."}},{"itemId":"c62eda4c-8e4c-588b-960c-260f4dfce081","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f31f8911-dddb-587c-84d1-51a4b6b5bee2","sourceKey":"bank:BUA204:STA-059","parentItemId":null,"revision":1,"payload":{"prompt":"For 5 branches, the number of staff (x) and customer satisfaction scores (y) are: (2, 30), (4, 26), (5, 33), (7, 29), (8, 35). Given n = 5, Sum x = 26, Sum y = 153, Sum xy = 812, Sum x^2 = 158 and Sum y^2 = 4,731, what is Pearson's r and how is it best described?","options":["r = 0.24, no linear relationship at all","r = -0.49, a weak negative relationship","r = 0.49, a moderate positive relationship","r = 0.49, a strong positive relationship"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"r = [5(812) - 26(153)] / sqrt{[5(158) - 26^2][5(4,731) - 153^2]} = 82 / sqrt(114 x 246) = 82 / 167.46 = 0.49, which falls in the 0.4 to 0.6 band for a moderate positive correlation. Option D gives the right value but overstates its strength, option B gets the sign wrong, and option A reports r^2 and wrongly calls it no relationship."}},{"itemId":"629c0a9f-b49a-5e3d-a156-fe97b0a8cab1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cd7293c9-0479-595f-bbb6-092045a53014","sourceKey":"bank:BUA204:STA-060","parentItemId":null,"revision":1,"payload":{"prompt":"King defined statistics as:","options":["The method of judging collective, natural and social phenomena from the results of analysis, enumeration or collection of estimates","The science of estimates and probabilities, used when counting is not possible","The collection, presentation and interpretation of data in tables, graphs and diagrams","The science of counting and the science of averages"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"King's definition presents statistics as a method of judging collective, natural and social phenomena from the results of analysis, enumeration or estimates. Option D is Bowley's definition, option B is Boddington's, and option C describes descriptive statistics, which is a branch rather than a definition of the whole subject."}},{"itemId":"0604285f-5241-558d-afc1-c40a0ac34304","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"307624b3-5bed-5d6e-900f-f192eb2aaf3d","sourceKey":"bank:BUA204:STA-061","parentItemId":null,"revision":1,"payload":{"prompt":"A market researcher in Onitsha surveys 200 shoppers and uses the results to estimate the average spending of all shoppers in the city. Which branch of statistics is she using?","options":["Descriptive statistics","Iconic statistics","Normative statistics","Inferential statistics"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Drawing conclusions about a whole population from limited sample information is inferential statistics. Option A, descriptive statistics, only collects, presents and interprets the data in hand without generalising beyond it, while options B and C borrow labels from model classification and are not branches of statistics."}},{"itemId":"36f900f0-9357-5cd3-b6a7-49efbf165254","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"eafe0df7-690b-5e0a-a0c9-7ad3db3281a8","sourceKey":"bank:BUA204:STA-062","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a measure of dispersion?","options":["Coefficient of variation","Median","Standard deviation","Interquartile range"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The median is a measure of central tendency: it locates the middle of the data rather than describing spread. The interquartile range (option D), coefficient of variation (option A) and standard deviation (option C) all measure how widely values are scattered."}},{"itemId":"e6f90d70-3b02-5d57-adcc-6cef2655ee00","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9cb15811-4467-5bf1-9324-4d00dc5522a8","sourceKey":"bank:BUA204:STA-063","parentItemId":null,"revision":1,"payload":{"prompt":"The spread of the middle 50% of a data set, found by subtracting the first quartile from the third quartile, is called the:","options":["Interquartile range","Variance","Coefficient of variation","Range"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The interquartile range is Q3 - Q1 and measures the spread of the middle half of the data, so it is not distorted by extreme values. Option D, the range, uses the highest and lowest values, option B averages squared deviations from the mean, and option C expresses the SD as a percentage of the mean."}},{"itemId":"f5eeb605-b8e8-5823-bc06-046a6181f71a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"05717bc1-fbfd-559e-b4e4-177b2d9186fe","sourceKey":"bank:BUA204:STA-064","parentItemId":null,"revision":1,"payload":{"prompt":"The coefficient of variation, CV = (SD / mean) x 100%, is mainly used to:","options":["Locate the middle value of a data set","Compare the relative variability of data sets with different means or units","Set the upper and lower limits on a control chart","Measure the strength of the linear relationship between two variables"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Because CV expresses the SD as a percentage of the mean, it measures relative dispersion and allows fair comparison of risk or consistency when means or units differ. Option D describes correlation, option A describes the median, and option C describes control limits, which use the mean plus or minus 3 SD."}},{"itemId":"5bdd98cf-bf9d-50eb-8332-8b87199f4341","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2e1a4b81-8deb-5fa2-8000-4d0cd47a8a2c","sourceKey":"bank:BUA204:STA-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a property of the normal distribution?","options":["The mean is always greater than the median","It is skewed to the right","The total area under the curve equals 1 (100%)","Only 50% of observations lie within 3 standard deviations of the mean"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"The normal curve is a probability distribution, so the total area under it is 1 (100%); it is also symmetrical and bell-shaped. Option A is wrong because the mean, median and mode coincide, option B contradicts its symmetry, and option D is wrong because about 99.7% lie within 3 SD."}},{"itemId":"ec5d6f15-e09a-5f7d-a170-3250a6a02798","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4aac7107-0e4f-5ded-96c7-e8256df625cf","sourceKey":"bank:BUA204:STA-066","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of the normal distribution?","options":["It has a long tail on one side because extreme values are more common there","It is symmetrical and bell-shaped","Its mean, median and mode coincide at the centre","About 68% of observations lie within one standard deviation of the mean"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"The normal distribution is symmetrical, so neither tail is longer than the other; a long tail on one side describes a skewed distribution. Options B, C and D are all genuine features: the bell shape, the coinciding mean, median and mode, and the 68% part of the empirical rule."}},{"itemId":"4d55019b-a255-5be5-83b1-5a8ed2edc40c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"16f9df27-4275-53d6-911c-0d19d9848475","sourceKey":"bank:BUA204:STA-067","parentItemId":null,"revision":1,"payload":{"prompt":"A quality manager at a Lagos paint factory tests H0: 'the mean fill volume is 4 litres'. In reality the mean IS 4 litres, but the test leads her to reject H0. What has occurred?","options":["A Type I error","A Type II error","A sampling frame error","A correct decision"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Rejecting a null hypothesis that is actually true is a Type I error (a false positive), whose probability is alpha. Option B, a Type II error, would be failing to reject a false H0, option D is wrong because a true H0 was rejected, and option C concerns how a sample is drawn, not the test decision."}},{"itemId":"15d34f2d-fe2e-560a-b2cb-aeaff966d66c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0956dfc4-adca-5e12-8d79-68ee22b3bd09","sourceKey":"bank:BUA204:STA-068","parentItemId":null,"revision":1,"payload":{"prompt":"A bank tests H0: 'the new app has no effect on average transaction time'. The app actually does reduce transaction time, but the test fails to reject H0. This is:","options":["The level of confidence","A Type II error","The alternative hypothesis","A Type I error"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Failing to reject a null hypothesis that is actually false is a Type II error (a false negative), whose probability is beta. Option D, a Type I error, is rejecting a true H0, option C is the statement the test tries to support (the effect exists), and option A relates to confidence intervals."}},{"itemId":"c5f635d1-b81e-5b9f-b13b-21ec568b255f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e6a1af87-76f3-5ed2-be04-115d324b853a","sourceKey":"bank:BUA204:STA-069","parentItemId":null,"revision":1,"payload":{"prompt":"In hypothesis testing, the null hypothesis (H0) is:","options":["The range of values within which the population mean is expected to lie","The default assumption that no effect or difference exists","The claim the researcher is trying to prove","The probability of rejecting a true hypothesis"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"H0 is the default position of 'no effect or no difference' that the test tries to find evidence against. Option C is the alternative hypothesis H1, option D describes alpha, the probability of a Type I error, and option A describes a confidence interval."}},{"itemId":"7de9d82f-fb78-538d-ad7f-6856fc79a5f4","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"418a04fb-1578-5a0c-8547-b316fba66c25","sourceKey":"bank:BUA204:STA-070","parentItemId":null,"revision":1,"payload":{"prompt":"A researcher wants to test whether the mean weight of 12 sampled bags of garri differs from 50 kg. The population standard deviation is unknown. Which test is appropriate?","options":["ANOVA (F-test)","t-test","Chi-square test","Z-test"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"With a small sample (n < 30) and an unknown population SD, the t-test is used. Option D, the Z-test, needs a large sample with sigma known, option C is for categorical or nominal data, and option A compares the means of three or more groups."}},{"itemId":"be9af86c-0057-53c3-8cdc-a3e77607b259","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ca24c583-f3bc-53f1-a1ec-e0776f9247f6","sourceKey":"bank:BUA204:STA-071","parentItemId":null,"revision":1,"payload":{"prompt":"An HR officer wants to test whether job grade (junior, middle, senior) is independent of preferred pension provider (three named providers), using counts of staff in each category. Which test should be used?","options":["Chi-square test","t-test","Z-test","Pearson's correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Counts of staff falling into named categories are categorical (nominal) data, and the chi-square test checks independence or goodness of fit for such data. Options B and C test means of numerical data, and option D measures linear association between two numerical variables."}},{"itemId":"083f7a8f-3829-5fa8-b5ae-aa3d37c82123","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4313fbd8-8783-5dbf-9e44-35c1fdc6218d","sourceKey":"bank:BUA204:STA-072","parentItemId":null,"revision":1,"payload":{"prompt":"A retailer compares the mean daily sales of four branches (Ikeja, Yaba, Ajah and Ikorodu) to see whether any differ significantly. Which test is most appropriate?","options":["Spearman's rank correlation","ANOVA (F-test)","Chi-square test","t-test for two means"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"ANOVA is designed to compare the means of three or more groups at once. Option C is for categorical counts, option D handles only two groups at a time, and option A measures association between two ranked variables rather than differences in means."}},{"itemId":"bf5edb0c-ff82-550e-b151-4c5b93bf4cdb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b9e2b23c-50b7-534c-ab75-2ece80d26420","sourceKey":"bank:BUA204:STA-074","parentItemId":null,"revision":1,"payload":{"prompt":"A study finds a strong positive correlation between the number of generators sold and the number of mosquito nets sold in Lagos markets each month. Both rise in the rainy season. What is the most appropriate conclusion?","options":["The correlation must be a calculation error because the products are unrelated","A third factor (the season) may drive both, so correlation alone does not show that one causes the other","Mosquito net sales cause generator sales","Generator sales cause mosquito net sales"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Correlation is not causation: a lurking variable such as the season can make two series move together without one causing the other. Options D and C assume a causal direction the data cannot prove, and option A is wrong because a genuine correlation can exist even between unrelated products."}},{"itemId":"7498e6a2-dc1b-534e-96f0-f680676c1995","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"110dbc94-0b78-5fdb-8931-ac4378570990","sourceKey":"bank:BUA204:STA-075","parentItemId":null,"revision":1,"payload":{"prompt":"An economist studies the relationship between maize yield and fertiliser use while holding rainfall constant. This is an example of:","options":["Partial correlation","Total correlation","Multiple correlation","Non-linear correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Partial correlation studies two variables while holding the other variables constant. Option C, multiple correlation, would study yield against fertiliser and rainfall together, option B, total correlation, considers all variables without holding any constant, and option D describes the shape of a relationship, not which variables are controlled."}},{"itemId":"d8867781-4804-5a76-bbea-0272d7667a27","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f3662e2f-0e68-5921-9fe4-c10df6fd14d8","sourceKey":"bank:BUA204:STA-076","parentItemId":null,"revision":1,"payload":{"prompt":"A correlation coefficient of r = 0.5 between advertising spend and footfall is best described as:","options":["Moderate positive correlation","Perfect positive correlation","Strong positive correlation","Moderate negative correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Values of r between 0.4 and 0.6 indicate moderate positive correlation. Option C needs r of about 0.7 to 0.9, option B needs r = +1, and option D would need a negative value of r."}},{"itemId":"9bf2bd26-3da8-516a-bd43-8446b8dafd8b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a5317281-46bc-56e2-bfff-b83dccee5776","sourceKey":"bank:BUA204:STA-077","parentItemId":null,"revision":1,"payload":{"prompt":"On a scatter diagram of price against quantity demanded for bread, all the points lie exactly on a straight line sloping downwards. The correlation coefficient is:","options":["r = +1","r = 0","r = -1","r = -0.5"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Points lying exactly on a downward-sloping straight line show a perfect negative linear relationship, r = -1. Option A is an exact upward-sloping line, option B means no linear relationship, and option D would show scattered points with only a moderate downward trend."}},{"itemId":"45f81e9c-a04e-5584-96d7-fb867d6ece08","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fa1bc90b-4e68-58a2-8b28-a2e5acebadde","sourceKey":"bank:BUA204:STA-079","parentItemId":null,"revision":1,"payload":{"prompt":"A control chart for the weight of noodle packs shows every point inside the UCL and LCL, scattered randomly around the centre line. What should the production manager conclude?","options":["The control limits must have been set at 1 standard deviation","The process is out of control and must be stopped immediately","The process appears to be in statistical control, with only random variation present","The process mean has shifted upwards"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Points within the 3-sigma limits with no pattern suggest only random (common-cause) variation, so the process is in control. Option B applies only when points fall outside the limits, option A has no basis in the chart pattern, and option D would show up as a run of points drifting above the centre line or crossing the UCL."}},{"itemId":"890db3cb-eb20-57c4-8293-999a090cba71","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bb7326d6-37a7-5478-8fb0-f7bdae052c3b","sourceKey":"bank:BUA204:STA-080","parentItemId":null,"revision":1,"payload":{"prompt":"The 'average of the squared deviations of the values from their mean' defines the:","options":["Mean deviation","Coefficient of variation","Variance","Standard deviation"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Variance is Sum(x - mean)^2 divided by n (or n - 1 for a sample), i.e. the average squared deviation. Option D, the standard deviation, is its square root, option A averages absolute (not squared) deviations, and option B divides the SD by the mean."}},{"itemId":"8acb15cb-763c-5bde-963c-569098304819","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ccb72f45-30e7-41b2-9b06-c44dc5bcd53c","sourceKey":"quiz:1","parentItemId":null,"revision":2,"payload":{"prompt":"Which of the following expresses a constraint in linear programming, e.g. 'labour <= 100 hours'?","options":["Simultaneous equation","Logarithm","Linear equation","Linear inequality"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Constraints set limits such as 'no more than 100 hours', so they are written with inequality signs like <= or >=, making them linear inequalities. Option C, a linear equation, uses an equals sign and would force exactly 100 hours to be used."}},{"itemId":"45c361af-4ea1-5635-a00f-6f0027c799f6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c53feb47-149b-4f89-8905-9f981bd9700b","sourceKey":"quiz:102","parentItemId":null,"revision":2,"payload":{"prompt":"Variables under the control of the decision maker, also called alternatives/options, are:","options":["Controllable variables","Exogenous variables","Uncontrollable variables","State of nature"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"Controllable variables are the ones the decision maker can actually choose or approve, which is why they are also called alternatives or options, so A is correct. Options C and D (uncontrollable variables and states of nature) are factors the decision maker cannot control, and option B, exogenous variables, likewise lie outside the decision maker's control."}},{"itemId":"b9d123a8-003c-5f2c-8e93-3c9568aa2be1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"58ee0ab0-136b-44fb-b326-1d79d998e791","sourceKey":"quiz:103","parentItemId":null,"revision":2,"payload":{"prompt":"Variables that are NOT under the control of the decision maker, but can influence the decision, are called:","options":["Performance measures","Controllable variables","Decision variables","Uncontrollable variables"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Uncontrollable variables cannot be chosen by the decision maker but still affect the result, and they shape the environment in which the decision is made, so D is correct. Options B and C are controlled by the decision maker, and option A measures how well an objective is achieved rather than being an outside influence."}},{"itemId":"8bcc08f9-09e0-54f6-9625-1de265d20775","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1c0aaf13-62c4-4750-a326-f6a4c9454bf6","sourceKey":"quiz:104","parentItemId":null,"revision":2,"payload":{"prompt":"In which decision-making environment is all information about the uncontrollable variable known for certainty?","options":["Ambiguity","Certainty","Uncertainty","Stochastic / Risk"],"correctOption":1,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under certainty, everything about the uncontrollable variable is known in advance, so each alternative has one known outcome and deterministic tools such as LP can be used; B is correct. Option D, risk, knows only the probabilities of outcomes, option C, uncertainty, does not even know the probabilities, and option A is not one of the three standard environments."}},{"itemId":"f30dc0f2-5e1f-5243-82c3-69d3b70fc94f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"db5f5270-c56f-4cb9-a31f-959eaee45ddb","sourceKey":"quiz:105","parentItemId":null,"revision":2,"payload":{"prompt":"In which decision-making environment is the occurrence of the uncontrollable variable unknown, but its likelihood is known?","options":["Certainty","Uncertainty","Determinism","Stochastic / Risk"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"In a risk (stochastic) environment you do not know which outcome will occur, but you do know the probability of each one, which is what makes EMV possible; D is correct. Option A, certainty, knows the outcome exactly, option B, uncertainty, has no probabilities, and option C, determinism, is just another way of describing certainty."}},{"itemId":"34aa0939-65eb-5be0-8f27-64a5c019b643","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7754b9af-8265-4944-be69-acff6166067e","sourceKey":"quiz:106","parentItemId":null,"revision":2,"payload":{"prompt":"In which decision-making environment can you NOT ascribe a probability to the uncontrollable variable's occurrence?","options":["Certainty","Stochastic / Risk","Determinism","Uncertainty"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under uncertainty you cannot attach any probability to the possible states of nature, so criteria such as Maximax, Maximin, Hurwicz, Laplace and Minimax Regret are used instead of EMV; D is correct. Option B, risk, does have known probabilities, while options A and C both describe situations where the outcome is known for certain."}},{"itemId":"06088287-f4f0-5415-a0f0-3d75fa21d1be","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2fcb1f40-e4ac-4e49-bd79-d20e57388eb7","sourceKey":"quiz:108","parentItemId":null,"revision":2,"payload":{"prompt":"Which element of decision making refers to the uncontrollable decision variables?","options":["Alternatives","Payoff","Action","State of Nature"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"States of nature are the possible conditions or events that the decision maker cannot control, such as high or low market demand, so D is correct. Options A and C relate to what the decision maker can choose and do, and option B is the result of a choice under a given state."}},{"itemId":"2a052665-c36a-5de1-95c3-b9a86b5b3da8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c02cb5a-152f-468e-84cd-bc956d1cf2ca","sourceKey":"quiz:109","parentItemId":null,"revision":2,"payload":{"prompt":"Which element of decision making refers to the benefits accrued to you for making a decision?","options":["Payoff","Goal / Objectives","Action","State of Nature"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"The payoff is the benefit (or loss) that results from taking a particular action under a particular state of nature, so A is correct. Option B is the aim that guides the whole decision, option C is the act of choosing, and option D is the uncontrollable condition that helps determine the payoff."}},{"itemId":"556f7a02-0601-5e4a-bad7-2f85f76b5562","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0de1148a-7d1b-40a0-a448-007dada9db0f","sourceKey":"quiz:110","parentItemId":null,"revision":2,"payload":{"prompt":"In the detailed nine-stage decision-making process, which stage comes immediately after 'Gather Information'?","options":["Identify the possible outcomes","Definition of the decision problem","Screening Alternative Courses of Action","Evaluate the result"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"The nine stages run: define the decision problem, gather information, screen the alternative courses of action, identify possible outcomes, list the payoffs, analyse the alternatives, select the best action, implement the decision and evaluate the result. Screening alternatives (C) therefore follows gathering information. Option B comes before it, option A comes after it, and option D is the very last stage."}},{"itemId":"89cc290f-9acb-5086-ac04-a5dc77e43ef0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b7be4241-5400-4874-94b7-8d6beaa79909","sourceKey":"quiz:125","parentItemId":null,"revision":2,"payload":{"prompt":"Data analysis (as distinct from data interpretation) answers which questions?","options":["How? and What?","Who? and Which?","So what? and Why?","When? and Where?"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Data analysis is about organising and examining data to find out what the patterns are and how the figures behave, so it answers 'How?' and 'What?'; A is correct. Option C, 'So what?' and 'Why?', is the job of data interpretation, which explains what the patterns mean. Options B and D are not how the two activities are distinguished."}},{"itemId":"cf602aa4-634d-55ef-af85-0404d7af3084","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aadd1bae-f19d-4cb2-945d-75616b8066be","sourceKey":"quiz:126","parentItemId":null,"revision":2,"payload":{"prompt":"Data interpretation (as distinct from data analysis) answers which questions?","options":["So what? and Why?","How? and What?","When? and Where?","Who? and Which?"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Data interpretation takes the patterns found during analysis and explains their meaning and implications for the business, answering 'So what?' and 'Why?'; A is correct. Option B, 'How?' and 'What?', belongs to data analysis, and options C and D are not how the two activities are distinguished."}},{"itemId":"de4ecbd5-9644-5e09-ba00-66bfa06fe9c1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bc225b16-1181-493b-8c88-b83d87d1984d","sourceKey":"quiz:130","parentItemId":null,"revision":2,"payload":{"prompt":"If b < 0 in a regression equation y-hat = a + bx, this indicates:","options":["A positive relationship","A perfect relationship","No relationship","A negative relationship  -  y decreases as x increases"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"A negative slope means the regression line slopes downward, so y tends to fall as x rises, which is a negative relationship; D is correct. Option A would need b > 0 and option C would need b = 0. Option B is wrong because the sign of b says nothing about whether the fit is perfect."}},{"itemId":"d0038c40-3d5e-5686-aa98-b7a25233558b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"075c98c8-23b4-43f5-8d6d-8f190f42936d","sourceKey":"quiz:131","parentItemId":null,"revision":2,"payload":{"prompt":"R-squared (R^2) represents:","options":["The intercept of the line","The strength of correlation only","The slope of the regression line","The proportion of variance in y explained by x"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"R-squared, the coefficient of determination, gives the proportion of the variation in y that is explained by x, ranging from 0 to 1; D is correct. In simple regression it equals r squared, so option B is tempting, but R-squared is read as explained variation rather than as the correlation itself. Options A and C are the regression coefficients a and b."}},{"itemId":"f26735be-5526-51f0-b3b8-94e2e6e5ade3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"be1051d1-c51b-49a8-8e74-424436e4edb9","sourceKey":"quiz:132","parentItemId":null,"revision":2,"payload":{"prompt":"Which challenge involves conclusions from very small samples possibly being due to chance rather than a true pattern?","options":["Confirmation Bias","Correlation vs Causation","Small Sample Size","Data Quality Issues"],"correctOption":2,"section":"Analysis and Interpretation of Results","explanation":"With very few observations, a pattern may appear simply by chance and disappear when more data is collected, which is the small sample size problem; C is correct. Option A is about reading data to fit existing beliefs, option B is about mistaking association for cause, and option D is about inaccurate or incomplete data."}},{"itemId":"947c38b2-42eb-5fd4-b4d1-2047f4682573","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"54fbd9bc-296d-4a7b-95ac-53c291a15000","sourceKey":"quiz:133","parentItemId":null,"revision":2,"payload":{"prompt":"The tendency to interpret data in a way that confirms pre-existing beliefs is called:","options":["Small Sample Size","Correlation vs Causation","Data Quality Issues","Confirmation Bias"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Confirmation bias is the tendency to look for, favour or interpret evidence so that it supports what you already believe, so D is correct. Option A relates to drawing conclusions from too few observations, option B to treating correlation as proof of cause, and option C to errors or gaps in the data itself."}},{"itemId":"fc5a44a4-dea0-5f41-b86b-24c59e33d8d3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"dfc0edd2-b69f-4d5a-8725-8b6415d683a0","sourceKey":"quiz:134","parentItemId":null,"revision":2,"payload":{"prompt":"Which analytical method breaks users into groups sharing characteristics to track behaviour over time?","options":["Thematic Analysis","Cohort Analysis","Content Analysis","Narrative Analysis"],"correctOption":1,"section":"Analysis and Interpretation of Results","explanation":"Cohort analysis groups users who share a characteristic, such as the month they signed up, and tracks how each group behaves over time, so B is correct. Options A and D are qualitative methods for themes and stories in text, and option C counts words or concepts in content rather than following groups of users."}},{"itemId":"e9fba496-8d0f-5987-9524-d9ae2e6f4fe5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"89c4297f-e735-495a-8560-d57a63a3e372","sourceKey":"quiz:136","parentItemId":null,"revision":2,"payload":{"prompt":"Quantifying the presence of words, concepts, or themes in texts/images is called:","options":["Narrative Analysis","Thematic Analysis","Cohort Analysis","Content Analysis"],"correctOption":3,"section":"Analysis and Interpretation of Results","explanation":"Content analysis systematically counts and quantifies the presence of particular words, concepts or themes in texts or images, so D is correct. Option B, thematic analysis, interprets the meaning of themes rather than measuring how often they appear, option A focuses on the stories people tell, and option C follows groups of users over time."}},{"itemId":"bf95d9aa-1cd0-5f27-b772-154ee37e8afa","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5cd60a04-9395-4387-b889-375d42be4a68","sourceKey":"quiz:15","parentItemId":null,"revision":2,"payload":{"prompt":"A businessperson wants a profit of N600,000 and makes N3,000 profit per unit. How many units must she sell?","options":["250 units","180 units","150 units","200 units"],"correctOption":3,"section":"Basic Mathematical Concepts for Management","explanation":"Units required = target profit / profit per unit = 600,000 / 3,000 = 200 units. The other options do not give N600,000 when multiplied by N3,000."}},{"itemId":"a3162b89-8f7d-5ce6-9cfa-da5dac793b5f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"57cf296c-6ee6-4409-b1fe-0893ed2a772c","sourceKey":"quiz:20","parentItemId":null,"revision":2,"payload":{"prompt":"Average Cost (AC) is defined as:","options":["AC = FC / Q","AC = TC / Q","AC = TC - FC","AC = TR / Q"],"correctOption":1,"section":"Basic Mathematical Concepts for Management","explanation":"Average cost is total cost divided by the number of units produced, i.e. cost per unit. Option A is only average fixed cost, and Option D gives average revenue (price)."}},{"itemId":"a7ad9403-ff22-5bf7-831f-dbc1458f4e8b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ef9fc021-fb24-484a-923a-00594eb8e23a","sourceKey":"quiz:21","parentItemId":null,"revision":2,"payload":{"prompt":"Correlation analysis measures:","options":["Causation between two variables","The average of two variables","The strength and direction of a linear relationship between two variables","The variance of a dataset"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Correlation shows how strongly two variables move together in a straight-line pattern and whether they move in the same or opposite directions. Option A is the classic trap: correlation does not prove that one variable causes the other."}},{"itemId":"67737515-a77c-5ea6-bb80-4ab29bfcd119","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ed408ff3-9397-46b6-9ca5-965dbde6338d","sourceKey":"quiz:22","parentItemId":null,"revision":2,"payload":{"prompt":"The value of the correlation coefficient (r) ranges between:","options":["-1 and +1","0 and 1","-100 and +100","0 and 100"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Pearson's r runs from -1 (perfect negative) through 0 (no linear relationship) to +1 (perfect positive). Option B would leave no room for negative relationships, which do occur, for example between price and demand."}},{"itemId":"85fa6f40-9f44-5c68-8be6-3018ac2f28af","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"70e4b166-ef8f-46e0-816b-a372f803bca9","sourceKey":"quiz:23","parentItemId":null,"revision":2,"payload":{"prompt":"If advertising expenditure increases and sales also increase, this is an example of:","options":["Positive correlation","Negative correlation","Partial correlation","Zero correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"When two variables move in the same direction, the correlation is positive. Option B would require sales to fall as advertising rises, and Option C describes a relationship studied while holding other variables constant."}},{"itemId":"bed89e62-7c8c-5b0a-9cad-e734cf93ecc8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c3e4d341-f058-41a6-bc35-e01f855ad163","sourceKey":"quiz:24","parentItemId":null,"revision":2,"payload":{"prompt":"If price increases and quantity demanded decreases, this illustrates:","options":["Negative correlation","Positive correlation","Total correlation","Multiple correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Variables moving in opposite directions show negative correlation, as when a higher price leads to lower demand. Option B would need both to rise or fall together."}},{"itemId":"b50e99c9-efd1-5504-a79b-29b4665937dd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ffc5b723-c393-4f31-a30e-c4f5d675307e","sourceKey":"quiz:25","parentItemId":null,"revision":2,"payload":{"prompt":"A correlation coefficient of r = +1.0 indicates:","options":["Perfect negative correlation","Perfect positive correlation","No relationship","Weak positive correlation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"r = +1.0 is the highest possible value and means all points lie exactly on an upward-sloping straight line, a perfect positive relationship. Option A is r = -1.0, and Option C is r = 0."}},{"itemId":"00dfa95b-bd80-518c-9b67-0736089ba677","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9ace8c44-a9dd-48bc-bec3-3e6954b9c423","sourceKey":"quiz:27","parentItemId":null,"revision":2,"payload":{"prompt":"Studying the relationship between only two variables (e.g. demand and supply), assuming a linear relationship, is called:","options":["Partial correlation","Multiple correlation","Total correlation","Simple correlation"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Simple correlation looks at just one pair of variables. Option B involves three or more variables at once, and Option A studies two variables while holding others constant."}},{"itemId":"4aedfa97-350e-5480-bcad-94a11a993667","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"815baf52-4866-46b9-bb88-259e4978f686","sourceKey":"quiz:28","parentItemId":null,"revision":2,"payload":{"prompt":"Studying the relationship between crop yield and TWO factors, rainfall and chemical fertiliser, simultaneously (Y = a + b1x1 + b2x2) is an example of:","options":["Partial correlation","Multiple correlation","Simple correlation","Non-linear correlation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"When one variable is related to two or more others at the same time, the study is multiple correlation. Option C is limited to two variables only, and Option A would study yield against one factor while holding the other fixed."}},{"itemId":"9f26978e-0287-5eea-aa55-331cff29818c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a948a204-6802-41c4-b635-23d7e90a5425","sourceKey":"quiz:29","parentItemId":null,"revision":2,"payload":{"prompt":"Studying the relationship between two variables while holding all other variables constant is called:","options":["Partial correlation","Total correlation","Multiple correlation","Simple correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Partial correlation isolates the link between one pair of variables by keeping the effect of the others fixed. Option B considers all the variables together without holding any constant, which is the opposite approach."}},{"itemId":"00a5f9b8-57a7-50cf-affd-79a90d713b66","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ecc55d34-6041-4c9b-8071-a2943fc48bf2","sourceKey":"quiz:30","parentItemId":null,"revision":2,"payload":{"prompt":"Correlation in which the rate of change between two variables is constant is called:","options":["Linear correlation","Non-linear correlation","Partial correlation","Zero correlation"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"If one variable changes by a constant amount for each unit change in the other, the points follow a straight line and the correlation is linear. Option B applies when the rate of change varies, producing a curved pattern."}},{"itemId":"8d216704-239f-5c3d-9487-61695929a6f0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0c71da2b-9607-45a7-8f84-d0a782c7c864","sourceKey":"quiz:31","parentItemId":null,"revision":2,"payload":{"prompt":"On a scatter diagram, points falling exactly on an upward-sloping straight line represent:","options":["Perfect negative correlation","Perfect positive correlation","Zero correlation","Weak correlation"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Points lying exactly on a rising straight line mean the variables move together perfectly, so r = +1, perfect positive correlation. Option A would need a downward-sloping line, and Option C would show no clear pattern."}},{"itemId":"5a37c13b-88bd-5d96-befd-11e0d3548498","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"11c4598e-0dcc-425e-b456-5bcfa6ff3a98","sourceKey":"quiz:32","parentItemId":null,"revision":2,"payload":{"prompt":"Which method is used to calculate correlation for ranked (ordinal) data?","options":["Spearman Rank Correlation","ANOVA","Pearson Correlation Coefficient","Regression Analysis"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"Spearman's rank correlation works on the ranks of the data, which makes it suitable for ordinal data such as rankings. Option C, Pearson's r, is meant for interval or ratio data measured on a numeric scale."}},{"itemId":"f2bf6bc1-5be6-579d-b040-e6b3f40824ba","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"58a6e464-954a-427d-886f-22645fba661b","sourceKey":"quiz:37","parentItemId":null,"revision":2,"payload":{"prompt":"The fact that ice cream sales and shark attacks both rise in summer (with warm weather being the real cause of both) illustrates the danger of:","options":["Assuming correlation implies causation","Data quality issues","Small sample size","Confirmation bias"],"correctOption":0,"section":"Analysis and Interpretation of Results","explanation":"Ice cream sales and shark attacks rise together only because warm weather drives both, so treating one as the cause of the other confuses correlation with causation; A is correct. Option B is about inaccurate or incomplete data, C is about drawing conclusions from too few observations, and D is about reading data to fit beliefs you already hold, none of which is the issue here."}},{"itemId":"d1705232-743c-5620-8f8e-29316074236f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1631f500-de81-4d1d-be19-9c0bbced9c94","sourceKey":"quiz:39","parentItemId":null,"revision":2,"payload":{"prompt":"Studying the relationship among ALL variables simultaneously, without holding any constant, is called:","options":["Simple correlation","Partial correlation","Non-linear correlation","Total correlation"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Total correlation studies the relationship among all the variables together, without holding any of them constant, so D is correct. Option B, partial correlation, does the opposite: it looks at two variables while the effect of the others is held constant. Option A, simple correlation, involves only two variables, and option C describes the shape of a relationship rather than how many variables are studied."}},{"itemId":"ec8fb12a-8969-5d11-8ce2-9afeef09ec24","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9a2a39c0-ded0-465f-9c87-a622b2f5042b","sourceKey":"quiz:41","parentItemId":null,"revision":2,"payload":{"prompt":"Quantitative Analysis in Management (QAM) is defined as:","options":["A legal framework for corporate governance","A purely qualitative approach to management with no data","The application of mathematical, statistical, and analytical techniques to managerial decision-making","A method of predicting elections using surveys"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"QAM means applying mathematical, statistical and analytical techniques to support managerial decisions, so C is correct. Option B describes the opposite of QAM, which depends on data. Options A and D describe corporate governance law and election polling, which are not what the discipline is about."}},{"itemId":"50e3b6e5-4f2d-58db-89ba-d9a0a5b66c9e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"99cb2b40-7904-4ffc-87aa-8eb4ba4c1ceb","sourceKey":"quiz:42","parentItemId":null,"revision":2,"payload":{"prompt":"Which of these is NOT one of the features of QAM?","options":["Relies primarily on intuition and guesswork rather than data","Uses numerical and measurable data  -  not guesses or opinions","Provides a scientific basis for managerial functions and activities","Supports objective decision-making by removing bias from the process"],"correctOption":0,"section":"Introduction to Quantitative Analysis in Management","explanation":"QAM rests on numerical, measurable data and systematic techniques, so relying on intuition and guesswork (option A) is exactly what it is designed to move away from. Options B, C and D are genuine features: it uses measurable data, gives a scientific basis to managerial functions and supports objective, less biased decisions."}},{"itemId":"03788497-b80e-5d96-866a-dc10349a83a2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"02bb90ce-ff48-4888-bcb6-b76f3c0cc61b","sourceKey":"quiz:43","parentItemId":null,"revision":2,"payload":{"prompt":"Which functional area applies QAM to inventory control, capacity planning, and scheduling?","options":["Financial Management","Human Resource Management","Production & Operations Management","Marketing Management"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Inventory control, capacity planning and scheduling are all about running the production process efficiently, so they belong to Production and Operations Management (C). Financial Management (A) applies QAM to investment and budgeting, Human Resource Management (B) to workforce planning and staff scheduling, and Marketing Management (D) to sales forecasting and pricing."}},{"itemId":"2e4ca170-ba25-59e6-9b13-fc41fde92ad0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bbd8445e-2bf3-468a-9bca-5134722bf87c","sourceKey":"quiz:44","parentItemId":null,"revision":2,"payload":{"prompt":"Which functional area applies QAM to investment appraisal, risk analysis, and portfolio management?","options":["Supply Chain & Logistics","Financial Management","Production & Operations Management","Marketing Management"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Investment appraisal, risk analysis and portfolio management are money-related decisions, so they fall under Financial Management (B). Supply Chain and Logistics (A) uses QAM for transport and distribution planning, Production and Operations (C) for inventory and scheduling, and Marketing (D) for sales forecasting, market research and pricing."}},{"itemId":"22598741-ed48-52bd-aa3c-3c280d4cb4c0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"323b2a9c-685f-43b3-afa4-527450d94ff7","sourceKey":"quiz:45","parentItemId":null,"revision":2,"payload":{"prompt":"An ordinal scale used to measure attitudes and opinions (e.g. 1-5 or 1-7) is called a(n):","options":["Inferential Analysis","Likert Scale","Simulation","Descriptive Analysis"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"A Likert scale asks respondents to rate their level of agreement on an ordered scale such as 1 to 5 or 1 to 7, so B is correct. Option A draws conclusions about a population from a sample, option D summarises data with measures like the mean, and option C imitates real processes; none of these is a rating scale."}},{"itemId":"e4ba48dc-26b2-564d-9f7b-97b1f324ef86","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"534d3ad1-85b2-4d4f-90b9-8e5e62148b04","sourceKey":"quiz:46","parentItemId":null,"revision":2,"payload":{"prompt":"Imitating real-world processes to test outcomes without real-world risk describes:","options":["Descriptive Analysis","Likert Scale","Simulation","Statistical Analysis"],"correctOption":2,"section":"Introduction to Quantitative Analysis in Management","explanation":"Simulation builds a model that imitates a real process so managers can try out different scenarios without real-world cost or risk, so C is correct. Options A and D are ways of summarising or testing data rather than imitating a process, and option B is a rating scale for attitudes."}},{"itemId":"f4d07b40-3682-5013-bb60-82fbc736f454","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aa2d1f85-c3a5-43f0-b654-7534e42a3ae7","sourceKey":"quiz:48","parentItemId":null,"revision":2,"payload":{"prompt":"Which analytical tool involves hypothesis testing, regression, ANOVA, and correlation?","options":["Likert Scale","Statistical Analysis","Descriptive Analysis","Simulation"],"correctOption":1,"section":"Introduction to Quantitative Analysis in Management","explanation":"Hypothesis testing, regression, ANOVA and correlation are the tools of statistical analysis, which goes beyond describing data to testing relationships and differences, so B is correct. Option C only summarises data with measures such as the mean, median and mode. Option A is a rating scale and option D imitates real-world processes."}},{"itemId":"ba27d753-90ee-5557-a9a5-90d44d71eb70","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"56d89a95-4ed9-46e4-8fa9-15f0c60b764d","sourceKey":"quiz:50","parentItemId":null,"revision":2,"payload":{"prompt":"Published reports, government statistics, and past research are examples of:","options":["Qualitative Data","Nominal Data","Primary Data","Secondary Data"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Published reports, government statistics and past research were collected by other people for their own purposes, which makes them secondary data, so D is correct. Option C, primary data, is collected first-hand for your own purpose. Options A and B describe the nature of data (non-numerical, or named categories), not who collected it."}},{"itemId":"9b14101b-b371-5ee8-9011-9a99bc43d4a5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"899c6cce-fe68-47ef-b07c-807b4756b1f9","sourceKey":"quiz:51","parentItemId":null,"revision":2,"payload":{"prompt":"Which of these is a characteristic of qualitative data collection?","options":["Participants may be randomly assigned to treatments","Intent is to generalise findings to a larger population","Uses probability sampling to select participants","Open-ended and less structured in protocol"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Qualitative data collection is open-ended and less structured, letting participants explain context, meaning and experiences in their own words, so D is correct. Options A, B and C all describe quantitative research, which uses probability sampling, aims to generalise to a larger population and may randomly assign participants to treatments."}},{"itemId":"4f1f12f6-f75d-5eca-8d90-d1496e218401","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a4daf09d-3a34-451c-a577-892ee20f4bee","sourceKey":"quiz:52","parentItemId":null,"revision":2,"payload":{"prompt":"Which sampling approach is typically used in qualitative research?","options":["Random assignment","Probability sampling","Systematic sampling","Purposive / theoretical sampling"],"correctOption":3,"section":"Data Collection, Organisation and Presentation","explanation":"Qualitative research picks participants deliberately because they can provide rich information on the topic, which is purposive or theoretical sampling, so D is correct. Options B and C are probability-based methods used when the goal is to generalise to a population, and option A is a feature of experiments, not a way of selecting people to study."}},{"itemId":"13a3f2f1-77cb-517b-8bce-d0bb7b6d2772","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"45b858e9-5c79-4085-b40c-54fd4c0d547c","sourceKey":"quiz:53","parentItemId":null,"revision":2,"payload":{"prompt":"Which chart is like a bar chart for continuous data, with no gaps between bars?","options":["Histogram","Bar Chart","Ogive","Pie Chart"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"A histogram shows the frequency distribution of continuous data, with bars standing side by side and no gaps because the class intervals run on continuously, so A is correct. Option B, the bar chart, compares separate categories and normally has gaps between bars. Option C is a cumulative frequency curve and option D shows parts of a whole."}},{"itemId":"8baf9f90-a30c-5c34-a1db-bcd76c4847ea","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"472009fc-12f7-4e0f-8e38-5b1d2ebd1999","sourceKey":"quiz:55","parentItemId":null,"revision":2,"payload":{"prompt":"Which tool is the basis for correlation and regression analysis?","options":["Ogive","Scatter Diagram","Bar Chart","Frequency Distribution Table"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"A scatter diagram plots pairs of values for two variables, letting you see whether and how closely they move together, which is why it is the starting point for correlation and regression; B is correct. Option A shows cumulative frequencies, option C compares categories and option D organises a single variable into classes, so none of them shows the relationship between two variables."}},{"itemId":"b41eb892-0a12-5c44-935c-0863c7789785","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"5d6b4f4b-7700-4d42-bf3b-7b4ef57881d6","sourceKey":"quiz:56","parentItemId":null,"revision":2,"payload":{"prompt":"A cumulative frequency curve used to find the median/quartiles graphically is called a(n):","options":["Line Graph","Ogive","Pie Chart","Histogram"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"An ogive plots cumulative frequency against the class boundaries, and reading across at half the total frequency gives the median (at a quarter and three-quarters, the quartiles), so B is correct. Option A shows trends over time, option C shows parts of a whole and option D shows ordinary, not cumulative, frequencies."}},{"itemId":"e8cdf40e-7f45-542b-b463-89f5c5c0358d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f7159190-83c3-44c7-9b8c-7838438497c1","sourceKey":"quiz:57","parentItemId":null,"revision":2,"payload":{"prompt":"Extended one-on-one conversations used to uncover deep insights describe:","options":["In-depth Interviews","Document Review","Observation","Surveys with close-ended questions"],"correctOption":0,"section":"Data Collection, Organisation and Presentation","explanation":"In-depth interviews are long, one-on-one conversations designed to explore a person's views and experiences in detail, so A is correct. Option C involves watching behaviour rather than talking, option B means studying existing documents, and option D uses fixed answer choices that cannot uncover deep insights."}},{"itemId":"f0226c6e-eece-506a-a1e3-c2a523e27c60","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"53258225-3856-4ce4-9103-1cfa4cc03ef5","sourceKey":"quiz:58","parentItemId":null,"revision":2,"payload":{"prompt":"Using multiple data collection methods together to strengthen findings is called:","options":["Randomisation","Triangulation","Standardisation","Stratification"],"correctOption":1,"section":"Data Collection, Organisation and Presentation","explanation":"Triangulation means using more than one method or type of data to study the same question, so that findings confirmed in several ways are more credible; B is correct. Option A refers to assigning participants by chance, option C means keeping procedures the same for everyone, and option D means dividing a population into subgroups before sampling."}},{"itemId":"9fc8acd5-e8fd-5008-881f-9e8c503029ab","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"972775a9-cb53-4819-a8af-bda1e21ae54e","sourceKey":"quiz:59","parentItemId":null,"revision":2,"payload":{"prompt":"Which author defined statistics as \"the science of counting\" and \"the science of averages\"?","options":["Ragsdale","King","Boddington","Bowley"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Defining statistics as the science of counting and also the science of averages is the classical definition given by Bowley, so D is correct. King (B) described statistics as a method of judging collective, natural and social phenomena from analysis or enumeration, while Boddington (C) called it the science of estimates and probabilities. Option A is not linked to this definition."}},{"itemId":"5f52fa85-9049-5d36-9e5f-e4c665d08b5f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"874a3571-5113-4391-9caa-7d0f9914610b","sourceKey":"quiz:6","parentItemId":null,"revision":2,"payload":{"prompt":"A firm's selling price is N5,000 per unit, variable cost is N3,000 per unit and fixed cost is N1,000,000. What is the Break-Even Quantity (BEQ)?","options":["333 units","1,000 units","500 units","200 units"],"correctOption":2,"section":"Basic Mathematical Concepts for Management","explanation":"BEQ = fixed cost / contribution margin = 1,000,000 / (5,000 - 3,000) = 1,000,000 / 2,000 = 500 units. Option A wrongly divides by the variable cost of N3,000, and Option D divides by the selling price of N5,000, instead of the contribution margin."}},{"itemId":"6451f66d-59db-5b78-863d-5c4275c6f4fd","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"33479795-6780-45a3-86fd-cb363ec0b300","sourceKey":"quiz:60","parentItemId":null,"revision":2,"payload":{"prompt":"Which author defined statistics as \"the science of estimates and probabilities\", used when counting is not possible?","options":["Bowley","King","Sharma","Boddington"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Boddington's definition starts from the point that when counting is not possible, estimates are needed, so statistics becomes the science of estimates and probabilities; D is correct. Bowley (A) defined it as the science of counting and of averages, and King (B) as a method of judging collective, natural and social phenomena. Option C is not linked to this definition."}},{"itemId":"bc5c9dc9-08f4-58ca-85bc-04e91c123bdb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"10f6e852-655b-4455-b457-e732bd8cc71b","sourceKey":"quiz:61","parentItemId":null,"revision":2,"payload":{"prompt":"Descriptive statistics deals with:","options":["Drawing conclusions from a sample about a population","Only qualitative, non-numerical data","Testing hypotheses using probability alone","Collection, presentation, and interpretation of data using tables, graphs, and diagrams"],"correctOption":3,"section":"Statistical Analysis for Management","explanation":"Descriptive statistics is about collecting, presenting and interpreting data through tables, graphs, diagrams and summary measures, so D is correct. Option A describes inferential statistics, which draws conclusions about a population from a sample, and option C also belongs to inferential work. Option B is wrong because descriptive statistics mainly handles numerical data."}},{"itemId":"666563c2-13fc-5aa4-814a-c5eac04233f8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"13c0fddb-9282-4f1b-8f71-c26d59c4fe05","sourceKey":"quiz:62","parentItemId":null,"revision":2,"payload":{"prompt":"Inferential statistics deals with:","options":["Only presenting data in tables and charts","Making estimates and drawing conclusions from limited (sample) information","Calculating averages for a full population census","Collecting primary data only"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"Inferential statistics uses limited sample information to make estimates and draw conclusions about a wider population, so B is correct. Option A is the job of descriptive statistics, and option C involves a full census, where there is nothing left to infer. Option D is about how data is collected, not how conclusions are drawn."}},{"itemId":"1a9e963d-4ccc-570f-bf46-edc778c211a2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e9feb1fa-c018-48b3-a291-55bdcaee2995","sourceKey":"quiz:63","parentItemId":null,"revision":2,"payload":{"prompt":"The mean (x-bar) is calculated as:","options":["Middle value when data is sorted","x-bar = sum of x / n","Value with highest frequency","Max - Min"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The arithmetic mean adds up all the values and divides by how many there are, x-bar = sum of x / n, so B is correct. Option A describes the median, option C the mode, and option D the range, which is a measure of spread rather than an average."}},{"itemId":"80a4eaae-e13a-5a4e-a88f-978b5123e142","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"866ec4ad-84ea-454d-8508-be6d83f352f3","sourceKey":"quiz:64","parentItemId":null,"revision":2,"payload":{"prompt":"Which measure is defined as \"the middle value when data is sorted\"?","options":["Variance","Median","Mode","Mean"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"When data are arranged in order, the value in the middle position is the median (with an even number of values, it is the average of the two middle ones), so B is correct. Option D, the mean, is the sum divided by the count, option C, the mode, is the most frequent value, and option A, variance, measures spread."}},{"itemId":"f019368c-5923-521c-aa59-cae845bdd345","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a13064ea-12cb-4c00-9308-877d7e29ee87","sourceKey":"quiz:67","parentItemId":null,"revision":2,"payload":{"prompt":"In hypothesis testing, rejecting a TRUE null hypothesis is called:","options":["p-value error","Type II Error","Type I Error","Significance error"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"A Type I error is a false positive: you reject the null hypothesis even though it is actually true, and its probability is the significance level alpha, so C is correct. Option B, a Type II error, is the reverse mistake of failing to reject a false null hypothesis. Options A and D are not standard names for this error."}},{"itemId":"25e136b6-ae4b-5e67-869c-4bdb9f730632","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7f28adbd-b6b4-49be-8714-3396a64fe4ee","sourceKey":"quiz:68","parentItemId":null,"revision":2,"payload":{"prompt":"Failing to reject a FALSE null hypothesis is called:","options":["Confidence error","Type I Error","Type II Error","Alpha error"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"Failing to reject a null hypothesis that is actually false is a false negative, known as a Type II error, so C is correct. Option B, the Type I error, is rejecting a true null, and option D, alpha error, is another name for that same Type I error. Option A is not a standard error type."}},{"itemId":"6c20f39c-2baf-5f3f-b864-bfae118d37e5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ecc5a58e-428e-428e-a017-4b46f24d4cd5","sourceKey":"quiz:70","parentItemId":null,"revision":2,"payload":{"prompt":"Which test compares the means of THREE OR MORE groups?","options":["ANOVA","t-Test","Z-Test","Chi-Square"],"correctOption":0,"section":"Statistical Analysis for Management","explanation":"ANOVA (analysis of variance) uses an F-test to check whether the means of three or more groups differ, so A is correct. Options B and C compare one or two means at a time, and running many separate t-tests instead would inflate the chance of a Type I error. Option D is for categorical data, not means."}},{"itemId":"ccc874f0-ef6e-5c4d-9035-14f4ada9b233","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9ccc2b3b-56c4-4feb-947a-8399bc084563","sourceKey":"quiz:71","parentItemId":null,"revision":2,"payload":{"prompt":"For a 95% confidence interval, the z critical value is:","options":["2.576","1.645","1.960","1.0"],"correctOption":2,"section":"Statistical Analysis for Management","explanation":"For a 95% confidence interval, 2.5% is left in each tail of the standard normal curve, which gives a critical value of z = 1.960, so C is correct. Option B (1.645) belongs to a 90% interval and option A (2.576) to a 99% interval, while option D (1.0) covers only about 68% of values."}},{"itemId":"95a84f41-c1bb-5a8e-bd78-c334493e110a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"adfd8017-78db-48b5-b718-42dee84a6464","sourceKey":"quiz:72","parentItemId":null,"revision":2,"payload":{"prompt":"Which test is used for categorical/nominal data to test independence or goodness of fit?","options":["t-Test","Chi-Square","Z-Test","ANOVA"],"correctOption":1,"section":"Statistical Analysis for Management","explanation":"The chi-square test works with counts in categories, testing whether two categorical variables are independent or whether observed frequencies fit an expected pattern, so B is correct. Options A, C and D all compare means of numerical data, which is not what goodness-of-fit or independence tests do."}},{"itemId":"6259da02-c388-5ffe-975f-e02b19f8ba1e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"9f85d598-10d4-4211-8ae7-b6b5981faa1e","sourceKey":"quiz:73","parentItemId":null,"revision":2,"payload":{"prompt":"According to Akingbade et al (1991), a model is:","options":["An exact replica of reality with no simplification","A prediction that is always 100% accurate","A representation of an existing or proposed system in order to predict the effect of changes","A tool used only in the physical sciences"],"correctOption":2,"section":"Operational Modelling","explanation":"A model is a representation of an existing or proposed system, built so that the effect of changes can be predicted without experimenting on the real system, so C is correct. Option A is wrong because models deliberately simplify reality, and option B is wrong because no model predicts perfectly. Option D is wrong because models are widely used in business and management."}},{"itemId":"4f6b5360-d7c9-5c5e-be29-153da2d29aee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b2479653-03f1-48d1-8707-80afbabfbbc7","sourceKey":"quiz:74","parentItemId":null,"revision":2,"payload":{"prompt":"The three top qualities of an effective model (Sharma, 2007) are:","options":["Size, Scale, Scope","Accuracy, Precision, Reliability","Validity, Usability, Value","Cost, Speed, Simplicity"],"correctOption":2,"section":"Operational Modelling","explanation":"An effective model must be valid (it represents the real system faithfully), usable (decision makers can actually apply it) and valuable (its benefits justify its cost), so C is correct. Option B lists measurement qualities rather than these three, and options A and D describe size or cost rather than what makes a model effective."}},{"itemId":"6953a799-3119-5672-917d-30b6cf6c33eb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7325e764-93e9-4977-953b-8d6849592c6a","sourceKey":"quiz:75","parentItemId":null,"revision":2,"payload":{"prompt":"Models that describe and predict facts/relationships but do NOT select the best alternative are called:","options":["Descriptive models","Normative models","Iconic models","Optimizing models"],"correctOption":0,"section":"Operational Modelling","explanation":"Descriptive models describe and predict facts and relationships in a system but have no objective function, so they cannot pick out the best alternative; A is correct. Options B and D are optimising models that do select the best solution, while option C classifies models by their physical appearance, not by purpose."}},{"itemId":"86930d68-6fad-5040-a8c2-2111bb34ddd5","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3773a429-1293-4d6b-8e56-e91d3bb57ffa","sourceKey":"quiz:76","parentItemId":null,"revision":2,"payload":{"prompt":"Prescriptive models that develop objective decision rules for an optimum solution are called:","options":["Descriptive models","Normative (Optimization) models","Analogue models","Simulation models"],"correctOption":1,"section":"Operational Modelling","explanation":"Normative or optimisation models are prescriptive: they set out objective decision rules that lead to the best (optimal) solution, as linear programming does, so B is correct. Option A only describes a system without choosing the best alternative. Option C classifies models by form, and option D imitates a process to test outcomes rather than prescribing an optimum."}},{"itemId":"7c976a7c-4d23-50c2-8edf-8212f05ac7f2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"abcdfe24-8541-4623-8123-92871fe08ad2","sourceKey":"quiz:77","parentItemId":null,"revision":2,"payload":{"prompt":"A physical, pictorial representation such as a blueprint or a globe is called a(n):","options":["Mathematical model","Normative model","Analogue model","Iconic model"],"correctOption":3,"section":"Operational Modelling","explanation":"An iconic model looks like the real thing, usually scaled up or down, as with a blueprint, a globe or a scale model of a building, so D is correct. Option C, an analogue model, uses one set of properties to stand for another, and option A uses symbols and equations. Option B classifies models by purpose (finding the best solution), not by appearance."}},{"itemId":"bb1f4a2c-7970-5a3e-afb0-4342fce66195","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"498b7b52-1b6c-4c71-b667-df8ca019819f","sourceKey":"quiz:78","parentItemId":null,"revision":2,"payload":{"prompt":"Representing the flow of electrons through a wire by the flow of water through a pipe is an example of a(n):","options":["Iconic model","Analogue model","Descriptive model","Mathematical model"],"correctOption":1,"section":"Operational Modelling","explanation":"An analogue model uses one set of properties to represent another, such as water flowing in a pipe standing for electrons flowing in a wire, so B is correct. Option A would physically resemble the wire itself, option D would use equations, and option C refers to a model's purpose (describing rather than optimising), not this kind of substitution."}},{"itemId":"d8d1fbf1-04e6-5030-9613-b5869a47fdef","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3e218104-62e5-44ce-923d-c1b2b84286bf","sourceKey":"quiz:79","parentItemId":null,"revision":2,"payload":{"prompt":"Models in which at least one parameter or decision variable is a random variable are called:","options":["Standard models","Deterministic models","Static models","Probabilistic models"],"correctOption":3,"section":"Operational Modelling","explanation":"When at least one parameter or decision variable is random, outcomes can only be described in terms of probabilities, so the model is probabilistic (stochastic); D is correct. Option B, deterministic models, assume everything is known with certainty. Option C refers to models that ignore changes over time, and option A is not a standard model type."}},{"itemId":"a2c66042-38a0-588b-87fa-62674406b17d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3800d6a3-3887-4b53-a1d2-2f1e35b2c964","sourceKey":"quiz:80","parentItemId":null,"revision":2,"payload":{"prompt":"Models that assume all parameters and functional relationships are known with certainty are called:","options":["Deterministic models","Custom-made models","Dynamic models","Probabilistic models"],"correctOption":0,"section":"Operational Modelling","explanation":"Deterministic models assume all parameters and relationships are known with certainty, so the same inputs always give the same output; A is correct. Option D is the opposite, since probabilistic models include random variables. Option C refers to models that capture changes over time, and option B describes models built for one specific problem."}},{"itemId":"49cb35fd-6bf1-50f6-8301-307f4c594d08","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8b457dec-e46f-42b2-8254-cc27d67655f4","sourceKey":"quiz:81","parentItemId":null,"revision":2,"payload":{"prompt":"In Ragsdale's classification of models, the category with known, well-defined functional relationships, where the independent variables are known or under the decision maker's control, is called:","options":["Predictive models","Prescriptive models","Analogue models","Descriptive models"],"correctOption":1,"section":"Operational Modelling","explanation":"When both the functional relationship and the inputs are known or controllable, the model can tell the manager which values to choose, which makes it prescriptive; linear programming is a typical example, so B is correct. Option A, predictive models, apply when the functional relationship is ill-defined, and option D, descriptive models, apply when the relationship is known but the independent variables are uncertain. Option C classifies models by physical form, not this way."}},{"itemId":"0b128b36-48e1-53bd-bb3c-bc2bcb397c09","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"80c93058-b1a7-484e-9124-1f9f75bca38b","sourceKey":"quiz:83","parentItemId":null,"revision":2,"payload":{"prompt":"Which of the five categories of decision-making variables represents factors outside the decision maker's control, such as competitor actions?","options":["Decision Variables","Performance Measures","Exogenous Variables","Intermediate Variables"],"correctOption":2,"section":"Operational Modelling","explanation":"Exogenous variables matter to the decision but are determined by forces outside the decision maker's control, such as competitors' actions or the state of the economy, so C is correct. Option A, decision variables, are the ones the manager does control. Option B measures how well the objective is achieved, and option D links decision variables to performance measures inside the model."}},{"itemId":"9a7bffbb-9bf1-5e78-9c26-24bcf72cd5ce","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ee32367f-5e80-4db4-8ad4-5f7e7f8e3d89","sourceKey":"quiz:85","parentItemId":null,"revision":2,"payload":{"prompt":"In LP, the feasible region is:","options":["The objective function line","The area outside all constraint lines","A single point","The area satisfying all constraints simultaneously"],"correctOption":3,"section":"Operational Modelling","explanation":"The feasible region is the set of all points that satisfy every constraint at the same time, usually shaded on the graph, so D is correct. Option B describes points that break the constraints, option A is just the line for one value of Z, and option C is wrong because the feasible region is normally an area containing many possible solutions."}},{"itemId":"306bc50f-1d6f-523d-aa19-be9f978681e9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"40bfe3d8-bed8-4831-9cb2-553ac61aa914","sourceKey":"quiz:86","parentItemId":null,"revision":2,"payload":{"prompt":"In the graphical LP method, the optimal solution is found at:","options":["The centre of the feasible region","A corner (vertex) of the feasible region","The origin only","Any random point in the feasible region"],"correctOption":1,"section":"Operational Modelling","explanation":"In a graphical LP problem the objective function reaches its best value at a corner (vertex) of the feasible region, which is why every corner point is evaluated, so B is correct. Interior points such as the centre (option A) or random points (option D) can always be improved by moving towards an edge. Option C, the origin, is only one of the corners and usually gives zero profit."}},{"itemId":"9c8c75e3-405a-5fbc-a593-d5711faa5fee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7f8ab39a-1f79-4667-8b18-d9e478e2a788","sourceKey":"quiz:88","parentItemId":null,"revision":2,"payload":{"prompt":"LP applied to minimising the cost of shipping goods from sources to destinations is called:","options":["Production Scheduling","Transportation Planning","Capacity Planning","Inventory Optimisation"],"correctOption":1,"section":"Operational Modelling","explanation":"Transportation planning uses LP to decide how much to ship from each supply point to each destination so that total shipping cost is as low as possible, so B is correct. Option A schedules what to produce and when, option C deals with how much capacity a firm needs, and option D concerns how much stock to hold."}},{"itemId":"1224b53e-0523-5d1e-8b5f-55c1d2130494","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a95937e5-b21d-457f-a1df-493443c8f931","sourceKey":"quiz:89","parentItemId":null,"revision":2,"payload":{"prompt":"Which decision-making environment uses EMV and Decision Trees?","options":["Ambiguity","Uncertainty","Certainty","Risk"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Under risk, outcomes are not known for certain but each one has a known probability, which is exactly what EMV and decision trees need, so D is correct. Option C, certainty, needs no probabilities, and option B, uncertainty, has no probabilities, so it uses criteria such as Maximax and Maximin instead. Option A is not one of the three standard decision environments."}},{"itemId":"22a288db-6667-5dba-a05f-9a3c2f1c936a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c6852cdd-5ea9-4c3d-a455-7d28cf66fdf7","sourceKey":"quiz:90","parentItemId":null,"revision":2,"payload":{"prompt":"Choosing the alternative with the maximum possible payoff describes:","options":["Maximin (Pessimistic)","Minimax Regret","Maximax (Optimistic)","Equally Likely (Laplace)"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximax is the optimistic criterion: find the best payoff for each alternative and pick the alternative with the highest of these, so C is correct. Option A looks at worst cases instead, option B minimises the largest regret, and option D chooses the highest average payoff."}},{"itemId":"8533f580-44d2-561e-b175-8eb2d155ab9d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"37678ace-2685-4ef8-b4ba-9b4950b15542","sourceKey":"quiz:91","parentItemId":null,"revision":2,"payload":{"prompt":"Choosing the alternative that maximises the minimum payoff describes:","options":["Maximax (Optimistic)","Criterion of Realism (Hurwicz)","Equally Likely (Laplace)","Maximin (Pessimistic)"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Maximin is the pessimistic criterion: list the worst payoff for each alternative and choose the alternative whose worst case is the best, so D is correct. Option A focuses on the best possible payoffs, option B weights best and worst outcomes with a coefficient of optimism, and option C averages all payoffs equally."}},{"itemId":"662b8a51-8cf0-54fd-992b-0d7b24fa55c2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"65781e91-7bb2-4ba2-abcf-3873f919b85c","sourceKey":"quiz:92","parentItemId":null,"revision":2,"payload":{"prompt":"Minimising the maximum opportunity loss describes:","options":["Maximax","Equally Likely (Laplace)","Minimax Regret","Maximin"],"correctOption":2,"section":"Decision Theory and Managerial Decision-Making","explanation":"Minimax regret (Savage) builds a regret or opportunity-loss table, finds each alternative's largest regret and picks the alternative where that largest regret is smallest, so C is correct. Options A and D work directly on payoffs (best case and worst case), not on regrets. Option B chooses the highest average payoff."}},{"itemId":"02ab7b2b-a342-5536-a634-c1f69133db8c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2df03bf9-3109-4571-b31e-803c81cf410d","sourceKey":"quiz:94","parentItemId":null,"revision":2,"payload":{"prompt":"EMV is calculated as:","options":["P(state) + Payoff(state)","sum of Payoff / n","Max payoff - Min payoff","sum of [P(state) x Payoff(state)]"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"EMV multiplies each payoff by the probability of its state of nature and adds the results, EMV = sum of [P(state) x Payoff(state)], so D is correct. Option A adds probabilities to payoffs, which makes no sense, option B is a simple average that ignores the probabilities, and option C is the range of payoffs."}},{"itemId":"e209a24a-8820-5335-b777-25001fa4fe6c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"864af51e-58ec-42c9-bde0-ec7f85b4cfb2","sourceKey":"quiz:98","parentItemId":null,"revision":2,"payload":{"prompt":"Decision trees are solved using the:","options":["Rollback method (working backwards from right to left)","Graphical method","Forward method (left to right)","Simplex method"],"correctOption":0,"section":"Decision Theory and Managerial Decision-Making","explanation":"A decision tree is solved by rolling back: start from the terminal payoffs on the right, compute EMVs at chance nodes and choose the best branch at decision nodes, working towards the left; A is correct. Option C goes the wrong way, since you cannot value a decision before the outcomes after it are known. Options B and D are linear programming solution methods."}},{"itemId":"638bd060-4ea4-5cdf-95e7-6ea7ac07dab3","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"92594cea-8215-4048-88ff-617977e0e361","sourceKey":"quiz:99","parentItemId":null,"revision":2,"payload":{"prompt":"Which is the FIRST of the six steps in decision making?","options":["Select a decision model","Make and implement the decision","List all possible outcomes","Clearly define the problem"],"correctOption":3,"section":"Decision Theory and Managerial Decision-Making","explanation":"Every sound decision starts by clearly defining the problem, because the alternatives, outcomes and payoffs all depend on it, so D is correct. Listing outcomes (option C) and selecting a decision model (option A) come later, and making and implementing the decision (option B) is the final step of the six."}}]$expected_content$::jsonb,
  'quantitative-analysis-management: cbt_question published payload and identity match source');
