  where kind = 'course_overview') = $expected_content$[{"itemId":"42bd1029-7f56-5b8d-824a-92f2405670f1","courseId":"40000000-0000-4000-8000-000000000013","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":2,"payload":{"title":"Philosophy, Logic and Human Existence","body":"A foundational course examining what philosophy is and why it matters, moving from its nature and scope through the classical branches — metaphysics, epistemology, ethics and aesthetics, logic and argument, and the philosophy of other disciplines — before turning outward to socio-political philosophy, African philosophy, the philosophy and history of science, and philosophy's broader relevance to technology and society.","topics":[{"chapter":"1","description":"Conception, Nature, Scope and Problems of Philosophy"},{"chapter":"2","description":"A Survey of the History of Philosophy"},{"chapter":"3","description":"Metaphysics as a Branch of Philosophy"},{"chapter":"4","description":"Epistemology as a Branch of Philosophy"},{"chapter":"5","description":"Ethics and Aesthetics"},{"chapter":"6","description":"Logic and Its Importance"},{"chapter":"7","description":"Inference and Argument Types in Logic"},{"chapter":"8","description":"Laws of Thought, Elementary Formal Rules of Reasoning and Fallacies"},{"chapter":"9","description":"The Philosophy of Other Disciplines"},{"chapter":"10","description":"Socio-Political Philosophy"},{"chapter":"11","description":"African Philosophy"},{"chapter":"12","description":"The Concept and Nature of Philosophy of Science"},{"chapter":"13","description":"The History and Method of Science"},{"chapter":"14","description":"Philosophy, Science and Technology"},{"chapter":"15","description":"Philosophy and Its Relevance to Society"}],"examFocus":["The distinction between the narrow (technical) and broad (worldview) senses of philosophy","Why 'What is philosophy?' is treated as philosophy's own most fundamental problem","The shift from Pre-Socratic cosmology (Thales, Anaximander, Heraclitus, Parmenides) to Socrates' turn toward ethics","Why metaphysics lost independent status to the positive sciences, and how it remains their 'ground'","The rationalist vs empiricist divide, and Plato's account of knowledge as acquaintance with Forms","The three subdivisions of ethics (descriptive, meta-ethics, normative) and teleological vs deontological theories","Why logic is not the same discipline as the psychology of reasoning","The distinction between deductive validity and inductive strength/correctness","The three Laws of Thought (Identity, Contradiction, Excluded Middle) and their symbolic forms","How philosophy functions as the 'infrastructure' underlying law, history, religion, and science","Why prescribing the organisation of the ideal state is socio-political philosophy's central task","The narrow and broad senses of philosophy in African philosophy, and its four core content areas","Why philosophy should not become subservient ('handmaiden') to science, and what 'Philosophical Science' means","The trajectory of Greek scientific thought from Thales through Plato and Aristotle","Why philosophy's relevance to society lies in providing an organised, coherent view of a disjointed world"]}}]$expected_content$::jsonb,
