mpt":"Ethics helps prevent society from falling into anarchy and","options":["justice and fairness","progress and development","harmony and peace","chaos and disorder"],"correctOption":3,"section":"Master Question Bank"}},{"itemId":"5588eab6-7f7e-511b-932f-79c71dfd49c6","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"ca6c357d-e194-4363-b759-cdb3c485fa0a","sourceKey":"quiz:85","parentItemId":null,"revision":1,"payload":{"prompt":"Logic is useful to every human being because all people seek some degree of","options":["comfort and pleasure","knowledge and certainty","influence and recognition","power and authority"],"correctOption":1,"section":"Master Question Bank"}},{"itemId":"66f3e090-ea70-5b13-8519-be35f405346c","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"9b2012a0-be93-4989-864e-21e1d44f5dd9","sourceKey":"quiz:86","parentItemId":null,"revision":1,"payload":{"prompt":"A deductive argument with coherent form but false premises is still considered","options":["observationally doubtful generally","logically valid nonetheless","experimentally weak entirely","probabilistically uncertain always"],"correctOption":1,"section":"Master Question Bank"}},{"itemId":"cd4bbee1-f305-574c-a756-c040def711ff","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"8a9449d8-0391-4d39-a9f5-2e23317134ec","sourceKey":"quiz:87","parentItemId":null,"revision":1,"payload":{"prompt":"Metaphysical theories differ mainly because philosophers disagree about","options":["functions of language","ultimate nature reality","methods of economics","structure of governments"],"correctOption":1,"section":"Master Question Bank"}},{"itemId":"b7300f83-98b0-5a6c-8771-46a907de0e11","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"8e1e149d-fee9-4131-9736-a53c429ac616","sourceKey":"quiz:88","parentItemId":null,"revision":1,"payload":{"prompt":"Philosophy as metaphysi