    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '40000000-0000-4000-8000-000000000014' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"0ea29316-8ade-51f4-9644-ed67f9fb43e9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8388c981-7d6a-5057-bcec-5c46fd42db28","sourceKey":"bank:BUA216:BND-001","parentItemId":null,"revision":1,"payload":{"prompt":"A bond has a face value of N1,000, pays an annual coupon of 8% and matures in 3 years. If the market yield is 10% per annum, what is its current market price, to 2 decimal places?","options":["N950.26","N991.31","N751.31","N1,000.00"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Po = 80 x [1 - (1.10)^-3] / 0.10 + 1,000 / (1.10)^3 = 198.95 + 751.31 = N950.26. Option C values only the face value and forgets the coupons. Option D discounts at the coupon rate instead of the market yield, and B adds the coupons without discounting them."}},{"itemId":"c87a4fea-e9de-5635-a939-af5008500d65","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f86eeef6-9028-52a7-9188-d7530f3083b1","sourceKey":"bank:BUA216:BND-002","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Holdings Plc has a 4-year bond with a face value of N1,000 and a 12% annual coupon. Investors now require a yield of 10% per annum. What is the bond's market value, to 2 decimal places?","options":["N1,480.00","N683.01","N939.25","N1,063.40"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Coupon = 12% x 1,000 = N120, so Po = 120 x [1 - (1.10)^-4] / 0.10 + 1,000 / (1.10)^4 = 380.38 + 683.01 = N1,063.40, a premium because the coupon beats the yield. Option C swaps the coupon rate and the yield, B counts only the face value, and A adds all cash flows without discounting."}},{"itemId":"7c1ddb39-53ca-5c92-9992-96e47462c918","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b221441-eee7-5e50-82b8-cd6cb6416d21","sourceKey":"bank:BUA216:BND-003","parentItemId":null,"revision":1,"payload":{"prompt":"A 5-year bond with a face value of N1,000 pays a 10% annual coupon. If the market yield is also 10% per annum, what is the price of the bond, to the nearest naira?","options":["N621","N1,000","N1,500","N379"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"When the coupon rate equals the market yield, the bond sells at par: 100 x 3.7908 + 1,000 x 0.6209 = 379.08 + 620.92 = N1,000. Option A is only the present value of the face value and D is only the present value of the coupons. Option C ignores discounting completely."}},{"itemId":"f6dd2c59-8e6b-5c49-94ae-e3cf94e67592","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c111dbb8-f5b7-5fb6-9cac-6cd5b1f445a2","sourceKey":"bank:BUA216:BND-004","parentItemId":null,"revision":1,"payload":{"prompt":"A bond with a face value of N5,000 pays 9% interest once a year and matures in 2 years. The required yield is 12% per annum. What is the bond's value, to 2 decimal places?","options":["N5,263.87","N4,746.49","N3,985.97","N4,885.97"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Annual interest = 9% x 5,000 = N450. Po = 450/1.12 + (450 + 5,000)/(1.12)^2 = 401.79 + 4,344.71 = N4,746.49. Option A swaps the coupon rate and the yield, C ignores the interest payments, and D adds the interest without discounting it."}},{"itemId":"05b405b4-5031-53d0-aa42-a2c237b6885e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6bbe410-a56a-5bf8-ba76-f1a1a0bc3388","sourceKey":"bank:BUA216:BND-005","parentItemId":null,"revision":1,"payload":{"prompt":"A 3-year bond with a par value of N1,000 carries a 14% annual coupon. The market yield on similar bonds is 11% per annum. Calculate the bond's price to 2 decimal places.","options":["N930.35","N871.19","N1,000.00","N1,073.31"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Po = 140 x [1 - (1.11)^-3] / 0.11 + 1,000 / (1.11)^3 = 342.12 + 731.19 = N1,073.31. Option A wrongly uses 11% as the coupon and 14% as the yield. Option B adds only one year's coupon, undiscounted, to the PV of the face value, and C assumes the bond sells at par even though the coupon and yield differ."}},{"itemId":"db509d8a-76bc-580c-87a2-dd9400fe1f13","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fdc128ff-6361-55a7-9782-e6eaa3ec9625","sourceKey":"bank:BUA216:BND-006","parentItemId":null,"revision":1,"payload":{"prompt":"An FGN bond has a face value of N100, a 13% annual coupon and 5 years to maturity. If the market yield is 15% per annum, what is its price, to 2 decimal places?","options":["N107.03","N49.72","N43.58","N93.30"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Po = 13 x [1 - (1.15)^-5] / 0.15 + 100 / (1.15)^5 = 43.58 + 49.72 = N93.30, below par because the yield is above the coupon. Option A swaps the two rates, while B and C each give only one part of the price (face value only or coupons only)."}},{"itemId":"70ba26a7-1f90-5f3c-aec5-381a9386251d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a5604848-145f-59d5-ad63-4b77acd0fe28","sourceKey":"bank:BUA216:BND-007","parentItemId":null,"revision":1,"payload":{"prompt":"A 2-year bond with a face value of N1,000 pays a 12% annual coupon. If the market yield is 9% per annum, by how much does its price exceed its face value (the premium), to 2 decimal places?","options":["N50.70","N30.00","N52.77","N60.00"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Price = 120/1.09 + 1,120/(1.09)^2 = 110.09 + 942.68 = N1,052.77, so the premium is 1,052.77 - 1,000 = N52.77. Option A is the discount that would arise if the two rates were swapped. Option D is the undiscounted extra coupon (3% x 1,000 x 2), and B is one year's extra coupon only."}},{"itemId":"7c673550-47c4-5bbe-8de4-ba769ef36094","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f76ccc3-6f09-5375-bdc6-028ef09b2980","sourceKey":"bank:BUA216:BND-008","parentItemId":null,"revision":1,"payload":{"prompt":"A zero-coupon bond will pay N10,000 at maturity in 3 years and pays no interest before then. If investors require 12% per annum compounded annually, what is its price today, to 2 decimal places?","options":["N7,971.94","N7,117.80","N6,400.00","N7,352.94"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A zero-coupon bond's price is just the present value of its face value: 10,000 / (1.12)^3 = 10,000 / 1.404928 = N7,117.80. Option D uses simple discounting (1 + 0.12 x 3), C simply deducts 36% from the face value, and A uses 2 periods instead of 3."}},{"itemId":"1cfcf16f-3e1d-5943-a193-0b7dcca2d65d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"27003200-add9-5b13-b0e0-833458db822a","sourceKey":"bank:BUA216:BND-009","parentItemId":null,"revision":1,"payload":{"prompt":"Lekki Infrastructure issues a 4-year zero-coupon bond with a face value of N1,000. With a market yield of 15% per annum (annual compounding), at what price should it sell, to 2 decimal places?","options":["N657.52","N625.00","N522.01","N571.75"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Price = 1,000 / (1.15)^4 = 1,000 / 1.74901 = N571.75, because the only cash flow is the face value at maturity. Option B uses simple interest (1 + 0.15 x 4), A discounts for only 3 years, and C wrongly multiplies by (0.85)^4 instead of dividing by (1.15)^4."}},{"itemId":"7cda9892-1181-54bd-a5c1-b42de56d62ed","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e71d3a6d-077a-541d-86ec-b5dcbf24b2c8","sourceKey":"bank:BUA216:BND-010","parentItemId":null,"revision":1,"payload":{"prompt":"A zero-coupon bond with a face value of N1,000 matures in 3 years. The market yield is 10% per annum compounded semi-annually. What is the bond's price, to 2 decimal places?","options":["N863.84","N746.22","N564.47","N751.31"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"With semi-annual compounding, the periodic rate is 10%/2 = 5% and there are 3 x 2 = 6 periods, so Po = 1,000 / (1.05)^6 = N746.22. Option D uses annual compounding, C doubles the periods but forgets to halve the rate, and A halves the rate but forgets to double the periods."}},{"itemId":"fe44c5ec-20ea-564c-b262-0f2a5e2479a0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b416fa3e-6a9a-50d5-a700-85f68a651778","sourceKey":"bank:BUA216:BND-011","parentItemId":null,"revision":1,"payload":{"prompt":"A 6-year bond with a face value of N1,000 pays an 11% annual coupon, and the market yield is 13% per annum. What is the present value of the coupon payments alone, to 2 decimal places?","options":["N660.00","N480.32","N465.36","N439.73"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The coupons form an ordinary annuity: 110 x [1 - (1.13)^-6] / 0.13 = 110 x 3.99755 = N439.73. Option A adds the coupons without discounting, B is the present value of the face value rather than the coupons, and C discounts at the coupon rate instead of the market yield."}},{"itemId":"83771bb9-e93e-5910-acb3-960ed85950b7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"38b313a0-a1d3-5488-b51e-6b6e742e01b9","sourceKey":"bank:BUA216:BND-012","parentItemId":null,"revision":1,"payload":{"prompt":"A bond with a face value of N2,000 matures in 5 years. Using a market yield of 14% per annum, what is the present value of the face value (PT) that will be repaid at maturity, to 2 decimal places?","options":["N1,184.16","N1,176.47","N6,866.16","N1,038.74"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"PV of the face value = PT / (1 + Kd)^n = 2,000 / (1.14)^5 = 2,000 / 1.925415 = N1,038.74. Option B uses simple interest (1 + 0.14 x 5), C wrongly applies the annuity factor to a single lump sum, and A uses 4 years instead of 5."}},{"itemId":"0b37021e-7821-5e69-9657-6b63a1832627","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"725f981b-9278-59a0-a352-26e96e4f9415","sourceKey":"bank:BUA216:BND-013","parentItemId":null,"revision":1,"payload":{"prompt":"A bond with a face value of N5,000 has a coupon rate of 7.5% per annum, paid semi-annually. How much interest does the holder receive on each payment date?","options":["N93.75","N375.00","N187.50","N750.00"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Annual interest = 7.5% x 5,000 = N375, and with two payments a year each payment is 375 / 2 = N187.50. Option B is the full annual coupon, A divides by four as if payments were quarterly, and D doubles the annual coupon instead of halving it."}},{"itemId":"f5d657c6-423a-5084-834d-e9e58a6b4047","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7e570f14-52f6-5570-91b4-b6a131c69367","sourceKey":"bank:BUA216:BND-014","parentItemId":null,"revision":1,"payload":{"prompt":"A 4-year bond with a face value of N1,000 and a 10% annual coupon is currently priced at par because the market yield is 10%. If the market yield rises to 12% per annum, by how much does the price fall, to 2 decimal places?","options":["N80.00","N20.00","N66.24","N60.75"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"At 12% the price becomes 100 x 3.03735 + 1,000 x 0.63552 = N939.25, a fall of 1,000 - 939.25 = N60.75. Option B is just 2% of face value for one year, A is 2% of face value times 4 years without discounting, and C is the rise in price that a fall to 8% would cause."}},{"itemId":"77b340f2-91c1-5994-95f9-439b7dbd687f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c0be8cfd-fdf3-5330-a1a0-eb00d88da16f","sourceKey":"bank:BUA216:BND-015","parentItemId":null,"revision":1,"payload":{"prompt":"A 4-year, 10% annual coupon bond with a face value of N1,000 was bought at par. Market yields then fall to 8% per annum. What is the bond's new price, to 2 decimal places?","options":["N939.25","N1,066.24","N835.03","N1,080.00"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Po = 100 x [1 - (1.08)^-4] / 0.08 + 1,000 / (1.08)^4 = 331.21 + 735.03 = N1,066.24, so the price rises as the yield falls. Option A is the price at 12%, which wrongly moves the price down. Option C counts only one undiscounted coupon, and D simply adds 8% to the face value."}},{"itemId":"00a223cd-8884-55a0-8c87-d79d79380493","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c4996601-f201-517e-85ac-3eb892392729","sourceKey":"bank:BUA216:BND-016","parentItemId":null,"revision":1,"payload":{"prompt":"Bond X (2 years) and Bond Y (6 years) both have a face value of N1,000, a 10% annual coupon and are priced at par. If the market yield rises to 12% per annum, how much MORE does Bond Y's price fall than Bond X's, to 2 decimal places?","options":["N33.80","N48.43","N82.23","N0.00"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Bond X falls to N966.20 (a drop of 33.80) and Bond Y falls to N917.77 (a drop of 82.23), so Y falls 82.23 - 33.80 = N48.43 more. This shows longer-maturity bonds carry more interest rate risk. Options C and A are each bond's own price drop rather than the difference, and D wrongly assumes maturity makes no difference."}},{"itemId":"40200ce4-a880-5c58-b18e-f28b1564a7a2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bf269a00-8609-5a49-9e43-a71cc7c78d13","sourceKey":"bank:BUA216:BND-017","parentItemId":null,"revision":1,"payload":{"prompt":"A 3-year bond with a face value of N1,000 pays a 12% coupon semi-annually. The market yield is 10% per annum compounded semi-annually. What is the bond's price, to 2 decimal places?","options":["N1,027.23","N825.79","N1,050.76","N1,049.74"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Use 60 per half-year, a periodic rate of 5% and 6 periods: Po = 60 x [1 - (1.05)^-6] / 0.05 + 1,000 / (1.05)^6 = 304.54 + 746.22 = N1,050.76. Option B doubles the periods but forgets to halve the rate (the classic error), D treats the bond as annual, and A halves the rate but uses only 3 periods."}},{"itemId":"8deecaa9-9ac1-5abe-b2c9-778f10041071","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2af7da54-895d-5dc5-8686-411b05508833","sourceKey":"bank:BUA216:BND-018","parentItemId":null,"revision":1,"payload":{"prompt":"A bond with a face value of N1,000 pays an 8% coupon in two equal half-yearly instalments and matures in 2 years. The required yield is 12% per annum compounded semi-annually. Find the price to 2 decimal places.","options":["N757.01","N932.40","N930.70","N1,069.30"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Half-yearly coupon = N40, periodic rate = 6%, periods = 4: Po = 40 x 3.46511 + 1,000 / (1.06)^4 = 138.60 + 792.09 = N930.70. Option A forgets to halve the 12% rate, B treats coupons as annual, and D uses the full annual coupon of 80 every half-year."}},{"itemId":"8f8a1a10-7346-5ef6-9367-7c9c33370fe2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b598d314-a250-5ff1-bef3-b2124de7d1a8","sourceKey":"bank:BUA216:BND-019","parentItemId":null,"revision":1,"payload":{"prompt":"Ogun State Government issues a 5-year bond with a par value of N1,000 that pays N50 every six months. If the market rate is 12% compounded semi-annually, what is the bond's value, to 2 decimal places?","options":["N747.67","N1,000.00","N604.48","N926.40"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Periodic rate = 12%/2 = 6% and periods = 5 x 2 = 10, so Po = 50 x 7.36009 + 1,000 / (1.06)^10 = 368.00 + 558.39 = N926.40. Option C uses 12% per half-year (forgetting to halve the rate), A uses 5 annual periods at 12% with only N50 a year, and B wrongly assumes par even though the N50 half-yearly coupon (10% a year) is below the 12% yield."}},{"itemId":"755645bb-10e1-5066-ba97-9d99b9125ac2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"abe9a28f-a873-5431-96a1-53f73b683c46","sourceKey":"bank:BUA216:BND-020","parentItemId":null,"revision":1,"payload":{"prompt":"A 2-year bond with a face value of N5,000 pays a 10% coupon semi-annually. The market yield is 8% per annum compounded semi-annually. What is its price, to 2 decimal places?","options":["N5,000.00","N5,178.33","N4,503.18","N5,181.49"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Coupon per half-year = 5,000 x 10% / 2 = N250, periodic rate = 4%, periods = 4: Po = 250 x 3.62990 + 5,000 / (1.04)^4 = 907.47 + 4,274.02 = N5,181.49. Option B treats the bond as paying annually, C forgets to halve the 8% yield, and A assumes par although the coupon exceeds the yield."}},{"itemId":"9c4a9029-fc60-522a-b330-fda4f2d0c36b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f2827de3-d919-5b3b-9931-3e2a7d8f686a","sourceKey":"bank:BUA216:BND-021","parentItemId":null,"revision":1,"payload":{"prompt":"Taking current yield as annual coupon / current market price, what is the current yield of a N1,000 face value bond with a 9% annual coupon that trades at N900?","options":["10.00%","11.11%","8.10%","9.00%"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Current yield = 90 / 900 = 0.10, that is 10.00%. Option D is the coupon rate, which uses face value instead of market price. Option C multiplies 9% by 0.9, and B inverts the relationship (1,000 / 900 - 1)."}},{"itemId":"137817cf-6b70-56a1-b5cc-06bf5d99c4c6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fed4512f-6834-59b1-8381-d2e2b0c39c74","sourceKey":"bank:BUA216:BND-022","parentItemId":null,"revision":1,"payload":{"prompt":"Taking current yield as annual coupon / current market price, a N1,000 face value bond pays a 12% annual coupon and sells for N1,250. What is its current yield, to 2 decimal places?","options":["9.60%","25.00%","12.00%","15.00%"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Current yield = 120 / 1,250 = 0.096, that is 9.60%, which is below the coupon rate because the bond trades at a premium. Option C is the coupon rate, which divides by face value instead of price, D multiplies the coupon rate by 1,250 / 1,000 instead of dividing, and B is the premium (250) as a percentage of face value."}},{"itemId":"db07666d-1b6b-536f-ae8b-d42243190cd0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c5da6a09-a51a-5673-9826-4e9a789a5195","sourceKey":"bank:BUA216:BND-023","parentItemId":null,"revision":1,"payload":{"prompt":"A 2-year, 10% annual coupon bond with a face value of N1,000 is priced to give a market yield of 12% per annum. Taking current yield as annual coupon / market price, what is its current yield, to 2 decimal places?","options":["12.42%","10.00%","12.00%","10.35%"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"First price the bond: 100/1.12 + 1,100/(1.12)^2 = N966.20. Current yield = 100 / 966.20 = 10.35%. Option B divides by face value (giving the coupon rate), C confuses current yield with the market yield used for discounting, and A uses N120 as the coupon."}},{"itemId":"0383da1a-bcce-5f4c-87c7-f1a56d3faded","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9783e86c-e7f9-5e8f-98dd-4e43fdfaabbd","sourceKey":"bank:BUA216:BND-024","parentItemId":null,"revision":1,"payload":{"prompt":"An investor buys a call option on Dangote Cement shares with a strike price of N500 for a premium of N30 per share. At expiry the share price is N580. What is the buyer's profit per share? Ignore transaction costs and the time value of money.","options":["-N30","N50","N80","N110"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The call is exercised: payoff = 580 - 500 = N80, and profit = payoff - premium = 80 - 30 = N50. Option C is the payoff before deducting the premium, D adds the premium instead of deducting it, and A is the loss only if the option expired unused."}},{"itemId":"1d1b013d-d326-541c-9e1f-aa7ba5c83633","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c54fe82e-7bb1-5f41-94fd-002592e3cfc7","sourceKey":"bank:BUA216:BND-025","parentItemId":null,"revision":1,"payload":{"prompt":"Halima buys a put option with a strike price of N200 for a premium of N15 per share. At expiry the share price is N160. What is her profit per share? Ignore transaction costs and the time value of money.","options":["N55","N40","-N15","N25"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A put pays strike - spot: 200 - 160 = N40, and profit = 40 - 15 = N25. Option B forgets to deduct the premium, A adds the premium, and C assumes the put is worthless even though the share price is below the strike."}},{"itemId":"6d87fb70-4b3c-5004-8036-8194088d1f19","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4169b637-4dc9-5513-9941-aef5229aa570","sourceKey":"bank:BUA216:BND-026","parentItemId":null,"revision":1,"payload":{"prompt":"A call option has a strike price of N500 and cost a premium of N30 per share. At expiry the share price is N480. What is the buyer's profit or loss per share? Ignore transaction costs and the time value of money.","options":["-N30","-N50","-N20","N0"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"With the share price below the strike, the buyer will not exercise, so the payoff is zero and the loss equals the premium paid: -N30. Option B wrongly exercises and adds the premium to the 20 shortfall, C counts only the 20 gap, and D forgets that the premium was already paid."}},{"itemId":"b9c2d79d-1875-5f47-b5b0-6d06cd95aab9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d42cd621-c132-552d-a6e1-0e2cf0c4bc12","sourceKey":"bank:BUA216:BND-027","parentItemId":null,"revision":1,"payload":{"prompt":"Zenith Traders WROTE (sold) a put option with a strike price of N1,200 and received a premium of N50 per share. At expiry the share price is N1,100 and the buyer exercises. What is the writer's profit or loss per share? Ignore transaction costs and the time value of money.","options":["N50","-N100","-N50","-N150"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The writer must buy at N1,200 a share worth N1,100, losing N100, but keeps the N50 premium, so the net result is -100 + 50 = -N50. Option A is the buyer's profit, B ignores the premium received, and D treats the premium as a cost to the writer."}},{"itemId":"acc16688-e55f-5110-bf68-5e0126699041","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dcd3170d-d395-5123-a748-7abb217e4517","sourceKey":"bank:BUA216:BND-028","parentItemId":null,"revision":1,"payload":{"prompt":"A writer sells a call option with a strike price of N80 for a premium of N6 per share. At expiry the share price is N75. What is the writer's profit per share? Ignore transaction costs and the time value of money.","options":["-N5","-N6","N6","N11"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The share is below the strike, so the buyer does not exercise and the writer simply keeps the premium of N6, which is the most a call writer can earn. Option B is the buyer's loss, D wrongly adds the 5 gap to the premium, and A wrongly treats the N5 gap below the strike as a loss and ignores the premium."}},{"itemId":"37917fa0-bb19-5cdb-b1c2-14bea71d159c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5feaff81-9250-53ec-ad69-f5a10b32f003","sourceKey":"bank:BUA216:BND-029","parentItemId":null,"revision":1,"payload":{"prompt":"A call option on a share has a strike price of N350 and a premium of N25. At expiry, what share price must be reached for the buyer to just break even? Ignore transaction costs and the time value of money.","options":["N350","N325","N375","N400"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A call buyer breaks even when the payoff equals the premium: strike + premium = 350 + 25 = N375. Option B is the put break-even (strike - premium), A is the strike alone, which ignores the premium, and D double-counts the premium."}},{"itemId":"82a0a0ca-b257-5741-a81e-02bea621a8cb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"39b84e28-b8e1-5620-ab8d-f2810a80e094","sourceKey":"bank:BUA216:BND-030","parentItemId":null,"revision":1,"payload":{"prompt":"A put option on a share has a strike price of N350 and a premium of N25. Below what share price at expiry does the put buyer start making a profit? Ignore transaction costs and the time value of money.","options":["N300","N350","N325","N375"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A put buyer breaks even at strike - premium = 350 - 25 = N325, so any price below N325 gives a profit. Option D is the call break-even, B ignores the premium, and A deducts the premium twice."}},{"itemId":"3d515436-7e9a-544a-8684-b86310dd131d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ca5784b4-607f-508c-b927-d6789f26ae78","sourceKey":"bank:BUA216:BND-031","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde buys one call option contract covering 100 shares, with a strike price of N40 and a premium of N3 per share. At expiry the share price is N52. What is his total profit? Ignore transaction costs and the time value of money.","options":["N900","N1,200","N300","N1,500"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Profit per share = (52 - 40) - 3 = N9, and for 100 shares that is N900. Option B forgets the premium, D adds the premium, and C is the total premium paid rather than the profit."}},{"itemId":"3d946777-03e0-53ef-b8c3-8da1a9f3e579","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15418a09-5b7e-5f3e-8c30-a79c788e7b41","sourceKey":"bank:BUA216:BND-032","parentItemId":null,"revision":1,"payload":{"prompt":"An investor buys put options on 500 shares with a strike price of N60 and a premium of N4 per share. At expiry the share price is N70. What is the investor's total profit or loss? Ignore transaction costs and the time value of money.","options":["-N2,000","-N5,000","-N3,000","N3,000"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"With the price above the strike, the put is not exercised, so the loss is the premium paid: 4 x 500 = N2,000. Option B wrongly exercises (10 x 500) without counting the premium, C nets the 10 gap against the premium, and D treats the rise as a gain to the put buyer."}},{"itemId":"190c8251-d790-5734-a636-8ff94aeef5a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2bf11074-e91d-5608-8a64-d8dc8e7c8195","sourceKey":"bank:BUA216:BND-033","parentItemId":null,"revision":1,"payload":{"prompt":"A put option has a strike price of N600. At expiry the share price is N650. What is the payoff (before premium) to the put holder per share?","options":["-N50","N50","N0","N650"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A put pays max(strike - spot, 0) = max(600 - 650, 0) = 0, because nobody would sell at N600 a share worth N650; the holder simply lets it expire. Option B is the payoff of a call, A forgets that the holder can refuse to exercise, so payoff is never negative, and D confuses payoff with the share price."}},{"itemId":"be05423b-50b9-50be-9b58-6eaf566ef7e1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"69e49e4d-c203-5585-9667-f01565048417","sourceKey":"bank:BUA216:BND-034","parentItemId":null,"revision":1,"payload":{"prompt":"Ada buys 10 call option contracts on MTN Nigeria shares, each covering 100 shares, at a premium of N2.50 per share. What is the maximum amount she can lose? Ignore transaction costs and the time value of money.","options":["N25","N2,500","Unlimited, if the share price keeps rising","N250"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"An option buyer's loss is limited to the premium paid: 10 x 100 x 2.50 = N2,500. Option D covers only one contract, A covers 10 shares, and C describes the risk of an uncovered call writer, not a buyer."}},{"itemId":"22fa0bfa-252d-5ba3-95f6-b2fb637f435b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b6496d47-352d-531a-a61e-a414b41cdc84","sourceKey":"bank:BUA216:BND-035","parentItemId":null,"revision":1,"payload":{"prompt":"An investor owns 1,000 shares and buys put options on them with a strike price of N90 at a premium of N5 per share. At expiry the share price has fallen to N70. Counting the premium, what is the effective amount per share she receives by exercising and selling at the strike? Ignore transaction costs and the time value of money.","options":["N85","N90","N70","N65"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Exercising the put lets her sell at N90, and after the N5 premium she effectively receives 90 - 5 = N85 per share, which is the floor the hedge guarantees. Option B ignores the premium, C is the unhedged market price, and D deducts the premium from the market price instead."}},{"itemId":"a1e4538d-e175-594f-a5c6-2897d0c4a370","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c7d428ce-2582-53fa-aaef-225c5d23843d","sourceKey":"bank:BUA216:BND-036","parentItemId":null,"revision":1,"payload":{"prompt":"A call option has a strike price of N100 and a premium of N8. At expiry, what share price would give the buyer a profit of exactly N20 per share? Ignore transaction costs and the time value of money.","options":["N128","N108","N120","N112"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Profit = (spot - strike) - premium, so 20 = (S - 100) - 8 and S = N128. Option C ignores the premium, D subtracts the premium instead of adding it, and B is the break-even price (strike + premium), where profit is zero."}},{"itemId":"b61bef01-a7b6-5bd9-8a3f-7782ffcfd816","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"30922d09-65cb-5fa5-b51f-90d97f25e8aa","sourceKey":"bank:BUA216:BND-037","parentItemId":null,"revision":1,"payload":{"prompt":"An investor buys a put option on 100 shares of a bank, strike price N75, premium N6 per share. At expiry the share price is N60. What is the total profit? Ignore transaction costs and the time value of money.","options":["N2,100","-N600","N1,500","N900"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Profit per share = (75 - 60) - 6 = N9, so total profit = 9 x 100 = N900. Option C forgets the premium, A adds it, and B treats the option as unexercised."}},{"itemId":"fd99f149-d2ab-577c-ba83-362daf59f6d6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"689fa721-210f-54c9-b67d-90b4807d3cd7","sourceKey":"bank:BUA216:BND-038","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano food processor enters a forward contract to buy 200 bags of rice in 3 months at N45,000 per bag. On the delivery date the spot price is N48,000 per bag. What is the processor's gain from the forward compared with buying at spot?","options":["-N600,000","N9,600,000","N600,000","N3,000"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The buyer pays the agreed N45,000 instead of N48,000, saving 3,000 x 200 = N600,000. Option B is the full spot cost of 200 bags, D is the gain on one bag only, and A is the seller's result, not the buyer's."}},{"itemId":"7adc9fa7-589e-505c-9bf0-a9cd25721614","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"032ec13a-e75f-5d08-aaf3-daa54ac9c6db","sourceKey":"bank:BUA216:BND-039","parentItemId":null,"revision":1,"payload":{"prompt":"A maize farmer agrees in a forward contract to sell 50 tonnes at harvest for N300,000 per tonne. At harvest the spot price is N270,000 per tonne. How much does the farmer receive in total under the contract?","options":["N1,500,000","N15,000,000","N28,500,000","N13,500,000"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A forward is binding, so the farmer delivers 50 tonnes at the agreed price: 50 x 300,000 = N15,000,000, whatever the spot price. Option D uses the spot price, A is only the gain over spot, and C wrongly adds both prices together."}},{"itemId":"70cf8a83-91a2-571d-8886-c9418cc763d1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d762a7c1-7107-5ef4-8316-458fd0324093","sourceKey":"bank:BUA216:BND-040","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturer agrees a forward contract to buy US$10,000 in 6 months at N1,500 per dollar. At maturity the spot rate is N1,560 per dollar. How much naira does the forward save the manufacturer?","options":["N15,000,000","N60","N600,000","N15,600,000"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Without the forward the dollars would cost 10,000 x 1,560 = N15.6m; with it they cost N15.0m, a saving of 60 x 10,000 = N600,000. Option B is the saving per dollar, A is the forward cost, and D is the spot cost."}},{"itemId":"b1a8dad1-8f6e-522f-bd7b-70042c47f87d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d826848c-e5a5-56c5-b5c0-a906b3f1be52","sourceKey":"bank:BUA216:BND-041","parentItemId":null,"revision":1,"payload":{"prompt":"A trader holds one long futures contract covering 100 units. The settlement price moves from N2,000 to N2,040 in one day. With daily settlement, how much is credited or debited to the trader's margin account that day?","options":["N4,000 credited","N204,000 credited","N4,000 debited","N40 credited"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A long position gains when the futures price rises: 40 x 100 = N4,000 is credited at the end of the day. Option C is what happens to the short side, D forgets to multiply by the contract size, and B is the value of the whole contract, not the day's change."}},{"itemId":"090f2b8b-0837-5a5b-a16b-439ebf617f9c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9dee9aa6-f6aa-5ca8-84c0-9408fd53bc60","sourceKey":"bank:BUA216:BND-042","parentItemId":null,"revision":1,"payload":{"prompt":"A speculator is long one futures contract of 1,000 units bought at N500. The daily settlement prices over the next three days are N510, N495 and N505. What is the net amount credited to the margin account over the three days?","options":["-N5,000","-N15,000","N35,000","N5,000"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Daily settlements are +10,000, -15,000 and +10,000, giving a net of +N5,000, the same as (505 - 500) x 1,000. Option B is only the second day, C adds the sizes of the moves (10 + 15 + 10 = 35) x 1,000 and ignores that one was a loss, and A is the short side's result."}},{"itemId":"f9ea842e-7edf-528e-b62c-457a613cac45","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"060b7baf-7a03-5c2b-956d-bcbfa84f6ad9","sourceKey":"bank:BUA216:BND-043","parentItemId":null,"revision":1,"payload":{"prompt":"A trader deposits an initial margin of N50,000 and takes a short futures position on 200 units at N1,000 per unit. If losses are deducted from the margin account daily and the futures price rises to N1,180, what is the margin balance (assuming no top-ups)?","options":["N86,000","N36,000","N14,000","N49,820"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A short position loses when the price rises: 180 x 200 = N36,000 loss, so the balance is 50,000 - 36,000 = N14,000. Option A treats the rise as a gain, B is the loss itself, and D forgets to multiply by 200 units."}},{"itemId":"0619a080-bed1-5de9-9e51-95cc2a8b25fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"38a0f6c7-0262-5e3d-ab7b-79bb78b4cf32","sourceKey":"bank:BUA216:BND-044","parentItemId":null,"revision":1,"payload":{"prompt":"A long futures position on 100 units has an initial margin of N20,000 and a maintenance margin of N15,000. The futures price falls by N70 per unit. If a margin call requires topping the account back up to the initial margin, how much must the trader deposit?","options":["N13,000","N0","N2,000","N7,000"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The loss is 70 x 100 = N7,000, leaving 13,000, which is below the 15,000 maintenance level, so the account must go back to 20,000: a deposit of N7,000. Option C tops up only to the maintenance margin, A is the remaining balance, and B wrongly says no call is needed."}},{"itemId":"782ab243-9a23-5d0e-9cdd-6e9b9068bc43","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"30515b5b-6575-556d-8aa7-9936766ca8e8","sourceKey":"bank:BUA216:BND-045","parentItemId":null,"revision":1,"payload":{"prompt":"A speculator buys 5 futures contracts, each covering 1,000 units, at N25.00 per unit and closes them out at N27.50 per unit. What is the speculator's total profit?","options":["N137,500","N2,500","N12,500","N125,000"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Profit = (27.50 - 25.00) x 1,000 x 5 = N12,500. Option B counts only one contract, A is the closing value of all contracts, and D wrongly multiplies the price gain by 50,000 units."}},{"itemId":"a52401fb-5a5e-5043-8b26-3f9b2b4b63cb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"65b5e56a-5b5f-5cb4-bfec-438d6fc1741a","sourceKey":"bank:BUA216:BND-046","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery uses futures to fix the price of 20 tonnes of wheat at N400,000 per tonne. At settlement the spot price is N450,000 per tonne; the bakery buys at spot and receives the gain on its futures. What is its net cost of the wheat?","options":["N1,000,000","N8,000,000","N10,000,000","N9,000,000"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Spot cost = 20 x 450,000 = N9,000,000, futures gain = 50,000 x 20 = N1,000,000, so net cost = N8,000,000, which is exactly the locked price. Option D ignores the hedge, A is only the futures gain, and C adds the gain instead of deducting it."}},{"itemId":"769958f3-f4ae-54c0-92f0-b3a873886f05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15760ec6-8447-51ee-b484-6a5885daa059","sourceKey":"bank:BUA216:BND-047","parentItemId":null,"revision":1,"payload":{"prompt":"A call option has a strike price of N1,000 and the underlying share now trades at N1,150. A put on the same share has the same strike. What are the payoffs per share if both are exercised (or allowed to expire) at this price?","options":["Call N1,150, put N0","Call N0, put N150","Call N150, put -N150","Call N150, put N0"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The call pays max(1,150 - 1,000, 0) = N150, while the put pays max(1,000 - 1,150, 0) = 0, so the put holder lets it expire. Option B swaps the two, C wrongly gives the put a negative payoff, and A confuses the call payoff with the share price."}},{"itemId":"c03971b4-adfb-5037-a0e2-6d5a8a329f4f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e049b281-fb46-5811-bc95-1d663612f60a","sourceKey":"bank:BUA216:BND-048","parentItemId":null,"revision":1,"payload":{"prompt":"Bonds are described as 'fixed income' instruments mainly because they","options":["promise the holder regular interest payments of a fixed amount","give the holder a fixed share of the issuer's profits","are always sold at exactly their face value","can only be sold back to the issuer at a fixed price"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A bond's coupon is set when it is issued, so the holder knows in advance the interest (R) to be received each period, plus the principal at maturity. Option B describes equity, whose returns depend on profits. Option D is false because bonds trade on the secondary market, and C is false because prices move above or below face value as yields change."}},{"itemId":"f2f5756f-c6ac-50e1-8ded-7f24f981a2a5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d8777437-eb09-5a04-add7-a85a0e475049","sourceKey":"bank:BUA216:BND-049","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi buys newly issued Federal Government of Nigeria bonds worth N2 million. In relation to the government, Bisi has become","options":["a lender (creditor) to whom interest and principal are owed","the writer of an option on government revenue","a part-owner entitled to vote on government policy","a party to a futures contract with the government"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A bond is a loan made by the investor and owed by the borrower, here the government, so Bisi is a creditor entitled to interest and repayment of principal. Option C describes a shareholder in a company, while B and D describe derivative positions, not bond ownership."}},{"itemId":"cf6ee46e-96e5-51e9-aa99-7f9b94fd6982","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1b36fbe8-46e5-5f79-827b-c877f86016a7","sourceKey":"bank:BUA216:BND-050","parentItemId":null,"revision":1,"payload":{"prompt":"Governments and companies issue bonds mainly in order to","options":["avoid paying interest on borrowed funds","hedge the price of raw materials","raise capital for operations or new projects","transfer ownership of the business to investors"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Bonds are a way of borrowing: issuers raise capital for operations or new projects and pay interest in return. Option D is what issuing shares does, B is the job of derivatives such as futures, and A is wrong because bondholders are paid interest."}},{"itemId":"bf41fa1a-c727-57a9-9a67-387ca55812b6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0bd397b5-7d4d-560b-9f0e-dcd3350a3165","sourceKey":"bank:BUA216:BND-051","parentItemId":null,"revision":1,"payload":{"prompt":"In the bond valuation formula Po = SUM[R / (1 + Kd)^t] + PT / (1 + Kd)^n, what does Kd represent?","options":["The face or terminal value repaid at maturity","The market yield (required return) used to discount the bond's cash flows","The number of years to maturity","The annual fixed interest paid on the bond"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Kd is the yield, the rate investors require, and it is the discount rate applied to each coupon and to the face value. Option D is R, A is PT and C is n."}},{"itemId":"41d7b977-bfca-5f06-8e8e-e1f0c573da66","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b7479c90-4c8e-5bea-b0b7-d3413d2fc018","sourceKey":"bank:BUA216:BND-052","parentItemId":null,"revision":1,"payload":{"prompt":"In bond valuation, the symbol PT stands for","options":["the total of all coupons over the bond's life","the face or terminal value of the bond","the annual coupon interest","the current market price of the bond"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"PT is the face (terminal) value, the principal repaid when the bond matures, and it is discounted with (1 + Kd)^n. Option D is Po, the value being calculated, C is R, and A is not a symbol in the formula at all."}},{"itemId":"1f13cc5c-9ae4-5b82-a644-4043cbc0eb7b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c813cf37-332d-567f-8c54-7a50883f6612","sourceKey":"bank:BUA216:BND-053","parentItemId":null,"revision":1,"payload":{"prompt":"In the bond valuation formula, which symbol represents the bond's annual fixed interest payment?","options":["PT","Kd","R","Po"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"R is the annual fixed interest (the coupon in naira), for example 10% of a N1,000 face value gives R = N100. Po is the current market price (option D), PT is the face value (option A) and Kd is the market yield (option B)."}},{"itemId":"81d00109-54dc-580e-99c6-ed0254521335","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9c6d7457-2a36-5dca-993b-c5048f5ab09a","sourceKey":"bank:BUA216:BND-054","parentItemId":null,"revision":1,"payload":{"prompt":"The expression SUM[R / (1 + Kd)^t] + PT / (1 + Kd)^n, with t running from 1 to n, calculates","options":["the current market price (value) of a bond","the future value of the bond's coupons at maturity","the current yield of the bond","the total interest a bondholder receives"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The formula discounts every coupon and the face value back to today, so it gives Po, the current market price. Option B would require compounding forward, not discounting. Option C is coupon divided by price, and D would simply be R x n with no discounting."}},{"itemId":"591a3b46-dfce-5e91-887b-3b8982632515","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c484e832-7ec7-5302-b7be-b1269cbc680c","sourceKey":"bank:BUA216:BND-055","parentItemId":null,"revision":1,"payload":{"prompt":"When valuing a bond that pays a fixed annual coupon, the stream of coupons is most conveniently valued using","options":["the future value of an annuity due factor","the present value of an ordinary annuity factor","the simple interest formula","the present value of a single lump sum factor applied once"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Equal coupons at the end of each year form an ordinary annuity, so they are valued with [1 - (1 + Kd)^-n] / Kd, then the face value is added as a separate lump sum. Option A compounds forward and assumes payments at the start, D suits only the face value, and C ignores compounding."}},{"itemId":"74116641-b170-5797-9f6c-9d737f8c8f1c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8beb06d1-5016-5850-9da8-6d2576aad0d9","sourceKey":"bank:BUA216:BND-056","parentItemId":null,"revision":1,"payload":{"prompt":"What happens to the price of an existing fixed-coupon bond when market interest rates (yields) rise?","options":["It rises","It rises only if the bond is close to maturity","It stays the same because the coupon is fixed","It falls"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Price and yield move in opposite directions: a higher yield in the denominator reduces the present value of the fixed coupons and face value. Option A gets the direction wrong, C confuses a fixed coupon with a fixed price, and B has no basis because rising yields push prices down at every maturity."}},{"itemId":"8df37fa6-8f4a-51be-b593-2a004b8e5a66","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"99ce87e9-29be-5674-8f1a-db563d98cc0e","sourceKey":"bank:BUA216:BND-057","parentItemId":null,"revision":1,"payload":{"prompt":"A bond whose market yield is HIGHER than its coupon rate will sell","options":["at a premium, above its face value","at a discount, below its face value","at a price equal to its total coupons","exactly at its face value"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"If investors require more than the coupon pays, they will only buy at a lower price, so the bond sells at a discount, as when a 10% coupon bond priced at 12% is worth about N927.88 per N1,000. Option A applies when the yield is below the coupon, and D applies when they are equal. Option C has no basis."}},{"itemId":"e749e10a-c9b1-5234-9da6-b6bcf7f42ebf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"67a5933f-ded8-5034-bcba-6f3d204b4ea9","sourceKey":"bank:BUA216:BND-058","parentItemId":null,"revision":1,"payload":{"prompt":"A bond is trading at a premium (above its face value). This means that","options":["its coupon rate is higher than the current market yield","it is a zero-coupon bond","its coupon rate is lower than the current market yield","its coupon rate equals the current market yield"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A premium arises when the bond pays more interest than investors currently require, so they bid the price above par. Option C produces a discount, D produces a price at par, and B is wrong because zero-coupon bonds always sell below face value when yields are positive."}},{"itemId":"e9e67121-bf35-56c9-a23b-fb4cc0a2120f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"724e7e4b-ec06-588f-8ed6-dce3b5596cb5","sourceKey":"bank:BUA216:BND-059","parentItemId":null,"revision":1,"payload":{"prompt":"A 3-year bond with a 15% annual coupon and a N1,000 face value is valued at a market yield of exactly 15%. Without detailed calculation, its price will be","options":["exactly N1,450","exactly N1,000 (at par)","above N1,000 (at a premium)","below N1,000 (at a discount)"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"When the coupon rate equals the market yield, the present value of the coupons and face value adds up exactly to the face value, so the bond sells at par. Options C and D need the coupon and yield to differ, and A adds the undiscounted coupons to the face value."}},{"itemId":"3cc62e71-18a2-574e-8588-4da5788a3582","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8040ce78-a272-5f8a-a232-7c359130db62","sourceKey":"bank:BUA216:BND-060","parentItemId":null,"revision":1,"payload":{"prompt":"An FGN bond with a face value of N1,000 is quoted at N1,080 on the secondary market. What can you conclude?","options":["The current market yield is above the bond's coupon rate","The current market yield is below the bond's coupon rate","The bond must be a zero-coupon bond","The bond's coupon rate equals the market yield"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A price above face value is a premium, which happens when the coupon rate is higher than the yield investors now require. Option A would make it sell at a discount, D would give a price of exactly N1,000, and C is wrong because zero-coupon bonds sell below face value."}},{"itemId":"7a39f9a4-b353-5a56-b38a-d59afc6ef019","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"65d9eac2-51ed-58d2-8d1a-7da683cd31ce","sourceKey":"bank:BUA216:BND-061","parentItemId":null,"revision":1,"payload":{"prompt":"Other things being equal, which bond's price is MOST sensitive to a change in market interest rates (greatest interest rate risk)?","options":["A 1-year bond","A 6-month treasury bill","A 20-year bond","A 3-year bond"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Longer-dated bonds have more of their value in distant cash flows, so a change in the discount rate moves their price the most. For example, a rise in yield from 10% to 12% cuts a 6-year 10% bond by about N82 per N1,000 but a 2-year bond by only about N34. The shorter instruments in A, D and B are less sensitive."}},{"itemId":"8db22bbf-b49a-550d-bd52-49abb598162a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"49109bd7-2195-5173-a39f-2f4a79390966","sourceKey":"bank:BUA216:BND-062","parentItemId":null,"revision":1,"payload":{"prompt":"In the context of bonds, interest rate risk is best described as","options":["the risk that changes in market interest rates will reduce the value of the bond","the risk of being unable to meet payment obligations when they fall due","the risk that the issuer fails to pay interest and principal","the risk arising from introducing debt into a firm's capital structure"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Interest rate risk is exposure to adverse changes in market rates; for a bondholder, rising rates push the bond's price down. Option C is default (credit) risk, B is liquidity risk and D is financial risk."}},{"itemId":"73fcb7bf-d634-59ff-8119-6632302a619c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3a2ed495-25a8-5392-b9df-4a0b4bb50a45","sourceKey":"bank:BUA216:BND-063","parentItemId":null,"revision":1,"payload":{"prompt":"When a bond pays coupons semi-annually, the correct adjustment to the valuation is to","options":["halve the number of periods but keep the annual discount rate","halve the coupon and the discount rate, and double the number of periods","double the number of periods but keep the annual discount rate","double the coupon and the discount rate, and halve the number of periods"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Each half-year is one period, so the coupon per period is C/2, the rate per period is Kd/2 and there are 2n periods. Option D reverses every adjustment. Option C is the most common exam error: doubling the periods but forgetting to halve the rate. Option A adjusts the wrong item."}},{"itemId":"9cd822aa-4a43-564d-ac67-304ddd429e3e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dc61240b-cfff-5df8-b40b-c6aaafe9250d","sourceKey":"bank:BUA216:BND-064","parentItemId":null,"revision":1,"payload":{"prompt":"A 4-year bond pays coupons every six months and the market yield is quoted as 16% compounded semi-annually. Which of the following is NOT a correct step in valuing it?","options":["Discounting each of the 8 half-yearly cash flows at 16% per period","Using a periodic discount rate of 8%","Using half the annual coupon as the payment each period","Using 8 periods in the calculation"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Discounting at the full 16% while using 8 half-yearly periods is the classic semi-annual error; the correct rate per half-year is 16%/2 = 8%. Options B, D and C are all correct steps: rate halved, periods doubled and coupon halved."}},{"itemId":"c28db0e2-1615-54b1-b42d-6f5270e1a015","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8085305c-bc6a-5c66-9964-ee213896083a","sourceKey":"bank:BUA216:BND-065","parentItemId":null,"revision":1,"payload":{"prompt":"A zero-coupon bond is one that","options":["pays interest every year but never repays the principal","pays interest at a rate that changes with market rates","is always sold above its face value","pays no periodic interest and is sold below face value, paying the face value at maturity"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A zero-coupon bond has R = 0, so its price is just PT / (1 + Kd)^n, which is below face value when yields are positive; the investor's return is the gap between price and face value. Option A describes a perpetual bond, B a floating-rate bond, and C gets the pricing backwards."}},{"itemId":"635a4008-41ae-5fbc-b475-5edf53b4fdf5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9fe810e7-b446-5e5c-a6de-3b7422759246","sourceKey":"bank:BUA216:BND-066","parentItemId":null,"revision":1,"payload":{"prompt":"The face value (par value) of a bond is","options":["the total interest paid over the bond's life","the price the bond currently trades at in the market","the principal amount repaid to the holder on the maturity date","the interest rate investors currently require"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Face or par value (PT) is the principal the issuer repays at maturity, and the coupon is usually stated as a percentage of it. Option B is the market price Po, which can be above or below face value, A is the coupon stream, and D is the yield Kd."}},{"itemId":"f475ad01-4dca-5961-9f72-97410200b225","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a8b5198b-343e-5f59-a927-4d3e3401ccd0","sourceKey":"bank:BUA216:BND-067","parentItemId":null,"revision":1,"payload":{"prompt":"An option is best described as a derivative contract that gives the buyer","options":["the right, but not the obligation, to buy or sell an underlying asset at a preset price within a specific period","the obligation to buy an underlying asset at a preset price on a fixed date","a fixed income and the return of principal at maturity","part ownership of the issuing company"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"What defines an option is that the buyer has a right, not a duty, so the buyer can walk away if exercising is not worthwhile. Option B describes a futures or forward contract, C describes a bond and D describes an ordinary share."}},{"itemId":"bc179426-2cb1-5a6c-99a9-963e0732f285","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"22685233-d768-525d-b3cc-b71e2800b01b","sourceKey":"bank:BUA216:BND-068","parentItemId":null,"revision":1,"payload":{"prompt":"An option that gives its holder the right to BUY an underlying asset at a preset price is called a","options":["forward contract","call option","futures contract","put option"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A call is an option to buy. A put (option D) is an option to sell, while forwards (option A) and futures (option C) are obligations, not rights."}},{"itemId":"5aae86ff-d3e3-53ad-87bb-7317d8d3a133","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f4587677-6ecb-5dfc-8bc2-e77ee9aae69d","sourceKey":"bank:BUA216:BND-069","parentItemId":null,"revision":1,"payload":{"prompt":"An option that gives its holder the right to SELL an underlying asset at a preset price is called a","options":["bond","put option","forward contract","call option"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A put is an option to sell, so it gains value when the asset's price falls. A call (option D) is the right to buy, a forward (option C) is a binding obligation, and a bond (option A) is a debt instrument."}},{"itemId":"3f47b8b6-10dd-58d1-858d-274337fc5f47","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2cde6240-9f5d-59db-b3c1-3e54660078a8","sourceKey":"bank:BUA216:BND-070","parentItemId":null,"revision":1,"payload":{"prompt":"Investors use options for several purposes. Which of the following is NOT one of them?","options":["Guaranteeing a profit regardless of price movements","Hedging","Income","Leverage"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Options are used for leverage (controlling a large position with a small premium), income (writers earn premiums) and hedging (protecting against price moves). No option guarantees a profit whatever happens; a buyer can lose the whole premium. Options D, C and B are genuine uses."}},{"itemId":"8ed1e43f-ff91-5554-8eb3-a96d3b3df3bb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d4711837-92e9-519e-81cc-5be0981f9330","sourceKey":"bank:BUA216:BND-071","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a component of an option contract?","options":["Premium","Coupon rate","Strike price","Expiration date"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The components of an option are the underlying asset, the strike price, the premium and the expiration date. A coupon rate belongs to a bond, not an option. Options C, A and D are all option components."}},{"itemId":"9cc028f9-d37a-5bdb-aa86-f1bd7d31d335","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"448c0f83-baa9-5fe6-b9d3-e48eac28f6b5","sourceKey":"bank:BUA216:BND-072","parentItemId":null,"revision":1,"payload":{"prompt":"In an option contract, the premium is","options":["the profit the buyer makes when the option is exercised","the date on which the contract ends","the price at which the underlying asset can be bought or sold","the upfront fee paid by the buyer to the seller (writer) of the option"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The premium is the price of the option itself, paid upfront by the buyer to the writer, and the writer keeps it whether or not the option is exercised. Option C is the strike price, B is the expiration date, and A confuses the cost of the option with its result."}},{"itemId":"c6797be5-cdfc-5427-80d5-ec59d664d81b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b04cd93-510a-5f7b-8ebc-0c68a6db8941","sourceKey":"bank:BUA216:BND-073","parentItemId":null,"revision":1,"payload":{"prompt":"The strike price of an option is","options":["the preset price at which the holder may buy or sell the underlying asset","the market price of the underlying asset on the expiry date","the date after which the option can no longer be exercised","the fee the buyer pays to obtain the option"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The strike (exercise) price is fixed in the contract and is the price at which the holder may buy (call) or sell (put) the asset. Option D is the premium, B is the spot price at expiry, which may differ from the strike, and C is the expiration date."}},{"itemId":"f45ef66f-8b7e-5c3a-9cfc-e6d6d50c4cf0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cf36df56-2d15-5196-bf51-f531fc110f7f","sourceKey":"bank:BUA216:BND-074","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly compares the buyer and the writer (seller) of an option?","options":["The buyer's possible loss is unlimited while the writer's is limited to the premium","Both the buyer and the writer are obliged to complete the trade at expiry","The writer pays the premium and decides whether to exercise","The buyer has a right and pays the premium; the writer receives the premium and must perform if the buyer exercises"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The buyer pays the premium for a right and loses at most that premium; the writer collects the premium but has the obligation if exercise happens. Option B describes futures, C reverses the roles, and A gets the risks backwards, because the writer, not the buyer, faces the larger possible loss."}},{"itemId":"43a37ffc-df1a-5fe8-b688-f372af557826","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"836a747a-6439-558c-8807-c5cc0754544e","sourceKey":"bank:BUA216:BND-075","parentItemId":null,"revision":1,"payload":{"prompt":"A call option is said to be 'in the money' when","options":["the market price of the underlying asset is above the strike price","the market price of the underlying asset equals the strike price","the premium paid exceeds the strike price","the market price of the underlying asset is below the strike price"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A call is in the money when exercising it would pay something, that is when the asset is worth more than the strike. Option D describes an out-of-the-money call (but an in-the-money put), B is at the money, and C has no bearing on moneyness."}},{"itemId":"2f8ef52d-8daf-59d6-8cc3-e997116928de","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8f084864-dfd4-5983-96fa-9b4b73dd26f6","sourceKey":"bank:BUA216:BND-076","parentItemId":null,"revision":1,"payload":{"prompt":"Seplat shares trade at N230. A put option on the shares has a strike price of N250. This put option is","options":["worthless because the share price is below the strike","at the money","out of the money","in the money"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A put gives the right to sell at N250 a share worth N230, so it has an exercise value of N20 and is in the money. A call at the same strike would be out of the money (option C). Option B needs the price to equal the strike, and A gets the put logic backwards."}},{"itemId":"e87650ab-7c01-560c-b5b4-69dbd83c9622","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0c2c7511-19bf-592d-a96f-8e7cc08c69c1","sourceKey":"bank:BUA216:BND-077","parentItemId":null,"revision":1,"payload":{"prompt":"A standardised, legally binding contract to buy or sell an underlying asset at a pre-set price on a specific future date is a","options":["forward contract","zero-coupon bond","call option","futures contract"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Standardised plus legally binding plus a future date is the definition of a futures contract. A call option (option C) is a right, not a binding obligation. A forward (option A) is also binding but is not standardised, and a zero-coupon bond (option B) is a debt instrument."}},{"itemId":"9e166c9b-7aed-537c-b80b-944cdecd1a74","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f150fac8-e884-5d46-a6c9-7a3a8769d643","sourceKey":"bank:BUA216:BND-078","parentItemId":null,"revision":1,"payload":{"prompt":"The main purpose for which futures contracts are used is","options":["raising long-term capital for new projects","financial hedging, that is, risk reduction","earning fixed interest income","acquiring ownership in a company"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Futures are mainly used to hedge, locking in a price so that a firm is protected against adverse price movements. Option A is why bonds are issued, C describes a bond's coupon, and D describes buying shares."}},{"itemId":"0eab5b23-3997-55b3-a920-007aef576815","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2f0e1451-e06d-5568-96f5-ed28a252eb16","sourceKey":"bank:BUA216:BND-079","parentItemId":null,"revision":1,"payload":{"prompt":"How do the obligations of the parties in a futures contract differ from those in an option contract?","options":["In futures neither party is obliged until a premium is paid","In both futures and options the buyer may walk away by forfeiting a premium","In futures both buyer and seller must honour the contract, while an option buyer has a voluntary right","In futures only the seller is obliged, while in options both parties are obliged"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Futures bind both parties compulsorily; options give the buyer a right that may or may not be used. Option D gets both halves wrong, B describes only options, and A invents a premium that futures do not have."}},{"itemId":"c5c1b805-b23c-544b-bbf1-68c7cfdc3381","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6fc432fe-f69e-57a0-9f9d-02904546e926","sourceKey":"bank:BUA216:BND-080","parentItemId":null,"revision":1,"payload":{"prompt":"In Nigeria, standardised futures contracts are traded on","options":["the NGX (Nigerian Exchange Group)","the Central Bank's treasury bill auction","the primary market for new shares only","a private agreement between two parties only"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Because futures are standardised, they trade publicly on an exchange, the NGX. Option D describes forward contracts, B is a money market process, and C is about newly issued shares, not derivatives."}},{"itemId":"c5dfe327-d03f-5b68-a37d-346910acb157","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"578123a4-0580-5cc6-bc86-6b3c8ca14a1b","sourceKey":"bank:BUA216:BND-081","parentItemId":null,"revision":1,"payload":{"prompt":"Futures contracts can be settled by","options":["physical delivery only","conversion into ordinary shares","physical delivery of the asset or cash settlement","cash settlement only"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Futures may end with the actual asset being delivered or with a cash payment of the price difference. Options D and A each leave out one of the two methods, and B is not a way futures are settled."}},{"itemId":"497b534d-a8dd-5c10-b388-a09d24ca6e5e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1e2faf31-134c-5cb1-886d-a1f02d852fab","sourceKey":"bank:BUA216:BND-082","parentItemId":null,"revision":1,"payload":{"prompt":"A contract involving an obligation to buy or sell an asset at a certain time in the future for a certain price, arranged privately between a buyer and a seller, is a","options":["put option","forward contract","futures contract","treasury bill"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A forward is a private, binding agreement to trade at a set price and date. A futures contract (option C) is also binding but is standardised and exchange-traded, a put (option A) is a right rather than an obligation, and a treasury bill (option D) is a short-term government debt instrument."}},{"itemId":"78301d41-a839-5a18-aa92-f8aa9de5570b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3da86881-3742-591f-a950-c4d4f426a99f","sourceKey":"bank:BUA216:BND-083","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is TRUE of a forward contract but NOT of a futures contract?","options":["It is settled daily","It is standardised","It carries credit risk because it is a private deal between the two parties","It is traded publicly on the NGX"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A forward is a private agreement, so each party relies on the other to perform, which creates credit risk; futures are virtually free of credit risk. Options B, D and A are all features of futures, not forwards."}},{"itemId":"585aa05f-0558-559e-89ef-6ddc8849ad0a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0c21da1d-2bd9-54e3-bc10-19527230a5e7","sourceKey":"bank:BUA216:BND-084","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of futures contracts?","options":["They are settled daily","They are standardised","They are virtually free of credit risk","They are private transactions between a buyer and a seller"],"correctOption":3,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Being a private, one-to-one transaction is the mark of a forward contract; futures are traded publicly on the exchange. Options B, A and C are genuine features of futures."}},{"itemId":"4e99f1ce-91aa-502b-b579-39a590de1474","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9c8769ef-1a50-5547-8efa-0cfb0ec1c64c","sourceKey":"bank:BUA216:BND-085","parentItemId":null,"revision":1,"payload":{"prompt":"A contract is settled daily, with gains and losses passed through the parties' accounts each day (marking to market). This describes","options":["a call option buyer's position before exercise","a futures contract","a forward contract","a bond"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Daily settlement is a feature of futures; forwards (option C) are settled only at the end of the contract. A bond (option D) pays periodic coupons rather than daily gains and losses, and an option buyer (option A) simply pays a premium upfront."}},{"itemId":"9816949c-2db5-5506-a409-ed39284e88c9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aa0297f1-8623-5736-b869-615199d674fb","sourceKey":"bank:BUA216:BND-086","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches each contract with its delivery arrangement?","options":["Forward: a single delivery date; futures: a frequent range of dates","Forward: a frequent range of dates; futures: a single delivery date","Both forwards and futures: a single delivery date","Both forwards and futures: no delivery date is ever set"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A forward is tailored to one agreed delivery date, while futures are listed for a range of standard dates. Option B swaps them, and C and D ignore the difference between the two contracts."}},{"itemId":"548d609c-ea47-52ae-a84c-6b1f55de9805","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"41889561-6cb0-5c8f-8e27-92baf493c789","sourceKey":"bank:BUA216:BND-087","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian cocoa exporter sells cocoa futures today to lock in the price for cocoa it will harvest in six months, so that a fall in prices will not hurt its revenue. This is an example of","options":["hedging","issuing a bond","arbitrage between bonds","speculation"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The exporter already has exposure to cocoa prices and uses futures to reduce that risk, which is hedging, the main purpose of futures. Speculation (option D) means taking on price risk in the hope of a profit, while C and B have nothing to do with locking in a commodity price."}},{"itemId":"5d768598-d483-5ca5-8330-24350b9b5939","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5132e8ad-9e19-5293-91ef-a1182e1549c2","sourceKey":"bank:BUA216:BND-088","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best distinguishes hedging from speculation with derivatives?","options":["Hedging and speculation both remove all risk from the investor's position","A hedger aims to profit from price movements; a speculator aims to reduce risk","A hedger uses derivatives to reduce an existing risk; a speculator takes on risk hoping to profit from price movements","Hedging uses only options while speculation uses only futures"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"Hedging offsets a risk the party already faces, such as a farmer locking in a selling price, while speculation deliberately takes a position to gain from expected price changes. Option B reverses the two, D is wrong because either instrument can be used for either purpose, and A is false because speculation increases risk."}},{"itemId":"2c271988-dce7-5ebd-b42e-ba2abd0930e8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8285aafd-9ea3-583d-a5b0-39f9af1329c9","sourceKey":"bank:BUA216:BND-089","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos importer must pay a foreign supplier US$50,000 in three months and fears the naira will weaken. Which action would HEDGE this risk?","options":["Waiting and buying the dollars at whatever the spot rate is in three months","Buying a put option on the US dollar","Entering a forward contract to buy US$50,000 in three months at a fixed naira rate","Entering a forward contract to sell US$50,000 in three months at a fixed naira rate"],"correctOption":2,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"The importer needs to buy dollars later, so fixing the purchase price now with a forward to BUY removes the risk of a weaker naira. Option D would add to the exposure, A leaves the risk untouched, and B gains when the dollar falls, which is the opposite of the importer's risk."}},{"itemId":"1acccc31-7dfe-5ac0-9f06-e7b399b138ca","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4adc1b16-367e-5c19-bde2-62c9b1dccae8","sourceKey":"bank:BUA216:BND-090","parentItemId":null,"revision":1,"payload":{"prompt":"Options, futures and forwards are all called derivatives because","options":["their value is derived from an underlying asset such as shares, commodities or currencies","they always pay a fixed rate of interest","they give the holder ownership of the issuing company","they are issued only by governments to raise funds"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A derivative's value depends on the price of something else, the underlying asset, which can be shares, commodities, currencies or bonds. Option D describes government bonds, B describes fixed income instruments, and C describes shares."}},{"itemId":"f8d4697f-b9fc-5d28-bfef-b14bd7d5bf6a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"603185ca-499f-5015-b627-cf68141c1c61","sourceKey":"bank:BUA216:CAP-001","parentItemId":null,"revision":1,"payload":{"prompt":"An investment holding that consists of a minimum of two different securities, also described as a basket of investment, is called a:","options":["Security market line","Risk-free asset","Beta","Portfolio"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A portfolio is a combination of at least two different securities, which is why it is also called a basket of investment. Option A is the line drawn from the CAPM equation, Option C measures systematic risk, and Option B is a single riskless investment such as a treasury bill."}},{"itemId":"b23effcb-833b-5c07-8edf-6043dd1fb990","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b14f5d25-26a6-5671-b9b2-fdd5ddf12ae4","sourceKey":"bank:BUA216:CAP-002","parentItemId":null,"revision":1,"payload":{"prompt":"Portfolio theory is best described as:","options":["The way a portfolio is selected with the aim of reducing or minimising the risk on that portfolio","The way a single security is priced so that its return equals the market return","The way a firm decides how much of its profit to pay out as dividends","The way an investor chooses the one security with the highest expected return"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Portfolio theory is about selecting a combination of securities so that the risk of the whole portfolio is reduced, eliminated or minimised. Option D describes putting everything into one high-return security, which ignores risk, while Option B is closer to the pricing idea in CAPM and Option C is dividend policy."}},{"itemId":"9786bf50-0648-5632-80c0-97eb76b1724d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0084bafa-770c-5899-aac1-475c8ff04bc8","sourceKey":"bank:BUA216:CAP-003","parentItemId":null,"revision":1,"payload":{"prompt":"In the expression PR = WxRx + WyRy, the terms Wx and Wy represent:","options":["The standard deviation of each security","The expected return of each security","The beta of each security","The proportion of each security in the portfolio"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Wx and Wy are the weights, that is the share of the portfolio invested in security X and security Y, and together they must total 100 percent. Option B is wrong because the expected returns are Rx and Ry, and Options A and C are risk measures that do not appear in the portfolio return formula."}},{"itemId":"2ca33074-9458-5061-b4e6-562fbeaf0b49","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"41263f59-734c-5ce1-8869-10d8bd6e3945","sourceKey":"bank:BUA216:CAP-004","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio's expected return is:","options":["The highest return among the securities in it","The sum of the returns of the securities in it","The simple average of the returns of the securities in it","The weighted average of the returns of the securities in it, weighted by the proportion of each security"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Portfolio return is a weighted average: each security's return is multiplied by the proportion of the portfolio invested in it, and the results are added. Option C would only be correct if every weight were equal, and Option B ignores the weights altogether."}},{"itemId":"3d3d103c-3dcd-52fc-ae87-b3d04c7d50ff","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8fb3e015-7b8c-53c0-a486-3447b8b8dfd7","sourceKey":"bank:BUA216:CAP-005","parentItemId":null,"revision":1,"payload":{"prompt":"In portfolio theory, portfolio risk refers to:","options":["The proportion of the portfolio held in the riskiest security only","The total amount of money invested in the portfolio","The relationships between the securities that make up the portfolio","The rate of return on treasury bills"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Portfolio risk depends on how the securities in the portfolio relate to one another, which is why combining securities can reduce risk. Option B is the size of the investment, not its risk, and Option D is the risk-free rate."}},{"itemId":"675b7df9-91b0-5bae-8b03-a37309d89e37","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e1ea42bf-938a-5427-9217-d29ea320d087","sourceKey":"bank:BUA216:CAP-006","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst builds a portfolio and writes the weights as 45% in security A and 45% in security B. What is wrong with this set of weights?","options":["Weights must be stated in naira, never as percentages","Nothing is wrong, because equal weights are always required","The weights must total 100 percent, so 10% of the portfolio is unaccounted for","The weights must total 50 percent for a two-security portfolio"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The weights in a portfolio must add up to 100 percent because together they describe the whole amount invested; 45% plus 45% is only 90%. Option B is wrong because weights need not be equal, and Option A is wrong because naira amounts are converted into proportions before they are used."}},{"itemId":"5d023514-a169-59e2-bbab-af3ed2a1b9df","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"75774b8e-98e6-5dc8-98bc-c3d97e0ff052","sourceKey":"bank:BUA216:CAP-007","parentItemId":null,"revision":1,"payload":{"prompt":"The capital asset pricing model is built on the model of portfolio choice developed in 1959 by:","options":["Eugene Fama","Harry Markowitz","John Maynard Keynes","Irving Fisher"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM grew out of Harry Markowitz's model of portfolio choice, which showed how investors can combine securities to balance return and risk. Option A is linked with market efficiency, while Options C and D are economists known for work on money and interest rather than portfolio choice."}},{"itemId":"2f828f82-ec23-5b53-bfd7-dfc55b67f840","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4190b427-75b2-513c-a205-f9f48f9376f6","sourceKey":"bank:BUA216:CAP-008","parentItemId":null,"revision":1,"payload":{"prompt":"The capital asset pricing model can be described as:","options":["An equilibrium pricing model","A bond valuation model","A capital budgeting model","A working capital model"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM is an equilibrium pricing model: it states the return a security should offer, given its systematic risk, when the market is in balance. Options B, C and D belong to other areas of financial management, namely bond valuation, project appraisal and the management of current assets respectively."}},{"itemId":"c0f36a3b-e351-59ee-a727-340a90ee6a0d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"33728c57-5865-5850-a03b-c7f23fd030c0","sourceKey":"bank:BUA216:CAP-009","parentItemId":null,"revision":1,"payload":{"prompt":"The main emphasis of the capital asset pricing model is on:","options":["Calculating the working capital needed by a firm","Removing all risk from an investor's portfolio","Choosing the cheapest source of long-term finance","Pricing individual securities to determine the contribution each makes to the overall portfolio"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM focuses on pricing individual securities, so that an investor can see what each security contributes to the whole portfolio. Option B is wrong because systematic risk can never be removed, and Options A and C belong to other topics."}},{"itemId":"2ed4d528-8edd-55d5-a871-adf3e8443f55","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"535d623b-ed76-5866-aa05-a715d6b599ee","sourceKey":"bank:BUA216:CAP-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes systematic risk from unsystematic risk?","options":["Systematic risk can be diversified away, while unsystematic risk cannot","Neither is affected by the number of securities held","Both can be fully eliminated by holding enough securities","Systematic risk cannot be diversified away, while unsystematic risk can be reduced by diversification"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Systematic risk is uncontrollable and cannot be diversified away by any investor, while unsystematic risk is controllable and diversifiable. Option A reverses the two, and Option C is wrong because no amount of diversification removes systematic risk."}},{"itemId":"67b1c971-9add-5602-b6b2-0fc0e365171a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dc3ea11f-74b8-5ab5-b418-a264e2a50060","sourceKey":"bank:BUA216:CAP-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of systematic risk?","options":["General inflation in the economy","A strike by a company's employees","Interest rate fluctuations","A stock market crash"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A strike affects only the company concerned, so it is an unsystematic risk that diversification can reduce. Options A, C and D affect almost every security at once, which is what makes them systematic risks."}},{"itemId":"5f04d459-6b30-569a-88a7-417f48c69bdb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"16bc92ce-6f38-5160-b723-5ec3c930543d","sourceKey":"bank:BUA216:CAP-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of unsystematic risk?","options":["Company fraud","War","Changes in company management","Raw material shortage at a firm"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"War affects the whole economy and every investor, so it is a systematic risk that cannot be diversified away. Options A, C and D are problems inside particular companies, which makes them unsystematic."}},{"itemId":"aa264899-07c9-588a-8c17-9ab1d7aa01a2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6625c542-57b1-5c72-b0c9-bc0d59299ab3","sourceKey":"bank:BUA216:CAP-013","parentItemId":null,"revision":1,"payload":{"prompt":"Under CAPM, which of the following is classified as an unsystematic risk?","options":["Technological advancements","Interest rate fluctuations","Natural disasters","A stock market crash"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Technological advancements are treated as unsystematic risk because they affect particular firms differently and can be diversified. Options B, C and D are all systematic risks that hit the whole market."}},{"itemId":"286490fc-4d6f-5adf-b007-a664a83119ad","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0cf3ee66-e1d9-589a-b49c-809088d95dc6","sourceKey":"bank:BUA216:CAP-014","parentItemId":null,"revision":1,"payload":{"prompt":"Shares of Ikorodu Paints Plc fall sharply after an internal fraud by its finance director is discovered. Shares of other listed companies are unaffected. This is an example of:","options":["Unsystematic risk","Systematic risk","Risk-free rate","Market risk premium"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Company fraud is specific to one firm, so it is an unsystematic risk, and an investor holding many different shares would feel only a small part of the loss. Option B is wrong because the rest of the market was unaffected, and Options C and D are inputs to the CAPM equation, not types of risk."}},{"itemId":"b5ed4c27-2ac1-539b-b0a4-53c3a4277b49","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d6f7d23-6667-548d-a460-2f91da46943e","sourceKey":"bank:BUA216:CAP-015","parentItemId":null,"revision":1,"payload":{"prompt":"A sudden rise in the general rate of inflation in Nigeria reduces the returns on almost all shares on the stock exchange. An investor holding 40 different shares still loses value. This is because:","options":["The investor's portfolio had a beta of zero","The investor held too few shares to remove the risk","General inflation is a systematic risk that cannot be diversified away","General inflation is an unsystematic risk that the investor failed to diversify"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"General inflation affects the whole market, so it is a systematic risk, and adding more shares does not remove it. Options B and D wrongly suggest more diversification would help, and Option A is wrong because a zero-beta portfolio would not move with the market at all."}},{"itemId":"b6bee4b2-1c06-51d4-9676-9243b83dd40f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c92be11-8aff-59a8-bf1b-68ae31061840","sourceKey":"bank:BUA216:CAP-016","parentItemId":null,"revision":1,"payload":{"prompt":"Kano Agro Ltd and Enugu Textiles Plc each face separate problems: Kano Agro has a raw material shortage and Enugu Textiles has a sudden change of management. An investor wants to reduce exposure to risks like these. The best approach is to:","options":["Hold only treasury bills and the shares of one of the firms","Wait for the general inflation rate to fall","Spread the investment across many different securities","Invest everything in whichever of the two firms has the higher beta"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A raw input shortage and a change of management are firm-specific, unsystematic risks, and these are controllable through diversification. Option D concentrates the risk instead of spreading it, and Option B confuses these firm problems with an economy-wide factor."}},{"itemId":"a00f0bd0-7f83-5e6e-b858-6447b923a8f8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"66d64931-5391-59a5-a04d-a23d49951505","sourceKey":"bank:BUA216:CAP-017","parentItemId":null,"revision":1,"payload":{"prompt":"In the CAPM equation E(Ri) = RF + (Rm - RF)Bi, the beta Bi represents:","options":["The unsystematic risk of security i","The systematic risk of security i","The total amount invested in security i","The risk-free rate of return"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Beta measures the systematic risk of a security, that is how sensitive it is to movements in the whole market. Option A is wrong because CAPM does not reward unsystematic risk, which can be diversified, and Option D is RF."}},{"itemId":"3197c45d-af4f-5e21-a2de-a9fed4f8f4bf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"82886d99-2d6b-5129-80f8-518c13041eab","sourceKey":"bank:BUA216:CAP-018","parentItemId":null,"revision":1,"payload":{"prompt":"In the CAPM equation, the expression (Rm - RF) is called the:","options":["Market risk premium","Security market line","Risk-free rate","Beta of the security"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Rm minus RF is the extra return the market offers above the risk-free rate, known as the market risk premium. It is multiplied by beta and then added to RF. Option C is RF alone, and Option B is the whole equation, not this one term."}},{"itemId":"b37a01f8-9447-5b18-96aa-363712bea5bb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"94d285f8-52ad-5139-b4c4-9d6303d80227","sourceKey":"bank:BUA216:CAP-019","parentItemId":null,"revision":1,"payload":{"prompt":"The equation E(Ri) = RF + (Rm - RF)Bi is also known as the:","options":["Efficient frontier","Yield curve","Security market line","Capital budgeting line"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The CAPM equation is the security market line (SML), which shows the required return for each level of beta. Option A is a curve of efficient portfolios plotted against standard deviation, and Option B relates bond yields to maturity."}},{"itemId":"fa53298a-2af3-5d30-9f38-fd8f4bde5bad","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d3208a1-f5c8-5c41-8a84-f7673a0d198c","sourceKey":"bank:BUA216:CAP-020","parentItemId":null,"revision":1,"payload":{"prompt":"When applying CAPM in Nigeria, the treasury bill rate is normally used as:","options":["Bi, the beta of the security","Rm, the expected return of the market","RF, the risk-free rate","E(Ri), the expected return of the security"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Treasury bills are short-term government securities with practically no default risk, so their rate is used as RF. Option B is the return on the stock market as a whole, which is a different input."}},{"itemId":"fd4b8ab7-9d0a-5d00-9827-86e0b086ee29","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a77acda8-52fd-52b8-a8ec-dc0f2bae7b6c","sourceKey":"bank:BUA216:CAP-021","parentItemId":null,"revision":1,"payload":{"prompt":"In CAPM, Rm stands for:","options":["The expected return of the market","The market risk premium","The risk-free rate","The return on security m only"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Rm is the expected return on the market as a whole, such as the stock market return. Option C is RF, and Option B is Rm minus RF, not Rm alone."}},{"itemId":"d6e773dd-8496-58b6-b1df-2111caef6a4a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a883fde4-a797-5f95-bd22-c73d4eebfd87","sourceKey":"bank:BUA216:CAP-022","parentItemId":null,"revision":1,"payload":{"prompt":"If a security's given (forecast) return is above the return on the security market line, the security is:","options":["Underpriced","Overpriced","Correctly priced","Risk-free"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A security offering more than the SML requires for its beta is a bargain, so it is underpriced and worth buying. Option B is the common trap: a return BELOW the SML means overpriced, not above."}},{"itemId":"311eddfe-b41f-58b4-b21a-6f8f9434ddbb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4b8321d2-4dde-5b33-aa45-3d9046e3d1a9","sourceKey":"bank:BUA216:CAP-023","parentItemId":null,"revision":1,"payload":{"prompt":"If a security's given return is below the return required by the security market line, the security is:","options":["Underpriced","A bargain to buy","Correctly priced","Overpriced"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A security that returns less than CAPM requires for its level of systematic risk is overpriced, so investors should avoid or sell it. Options A and B reverse the rule, since a bargain is one whose return is above the SML."}},{"itemId":"f8d994bc-89ce-566f-b176-2a7f5af22f1e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ddb2c36f-022b-57b5-8283-36d3b71fa525","sourceKey":"bank:BUA216:CAP-024","parentItemId":null,"revision":1,"payload":{"prompt":"A security whose given return is exactly equal to its security market line return is said to be:","options":["Overpriced","Underpriced","Correctly priced","Risk-free"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"When the given return equals the SML required return, the security offers exactly what its beta deserves, so it is correctly priced. Option D is wrong because a security on the SML can still carry systematic risk."}},{"itemId":"30b090c7-ad24-5d8a-8ac4-72200c829e8a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f296cddf-2ea8-5b1f-86f9-557efcc12f64","sourceKey":"bank:BUA216:CAP-025","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst finds that a share is underpriced according to CAPM. The appropriate advice to an investor is to:","options":["Sell the share, because it offers less return than its risk requires","Buy the share, because it offers more return than its risk requires","Sell the share, because its beta must be negative","Ignore the share, because underpriced shares are always risk-free"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"An underpriced share has a given return above its SML return, which makes it a bargain, so the advice is to buy. Option A describes an overpriced share, and Options C and D make claims about risk that pricing alone does not tell us."}},{"itemId":"2352da01-7096-5303-8b1f-8b782d7a633a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"973a77ab-3dad-573a-9b03-c888dbd0c7ce","sourceKey":"bank:BUA216:CAP-026","parentItemId":null,"revision":1,"payload":{"prompt":"When computing a required return with CAPM, the correct order of working is to:","options":["Divide Rm minus RF by beta, then add RF","Multiply Rm by beta first, then subtract RF","Find Rm minus RF first, multiply by beta, then add RF","Add RF to Rm first, then multiply by beta"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The market risk premium (Rm - RF) is found first, multiplied by beta, and then added to RF to give E(Ri). Option B applies beta to the whole market return, and Option A divides by beta, both of which give wrong required returns."}},{"itemId":"5b4908f7-6cf9-5833-ab10-efadf787ad52","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"617d5dd5-013a-5080-a236-17c152238fa1","sourceKey":"bank:BUA216:CAP-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the assumptions of the capital asset pricing model?","options":["Investors can borrow and lend freely at the risk-free rate","Investors pay taxes and transaction costs on every trade","Investors are risk-averse","All investors share the same single-period planning horizon"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM assumes perfect markets with no taxes and no transaction costs, so a world with taxes and dealing costs on every trade contradicts the model. Options A, C and D are all standard CAPM assumptions."}},{"itemId":"d4b6412f-c465-5c0d-978a-164266bf8fd8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c90b1b12-2155-5428-b810-ca10440f7ce6","sourceKey":"bank:BUA216:CAP-028","parentItemId":null,"revision":1,"payload":{"prompt":"Under the assumptions of CAPM, investors assess securities on the basis of:","options":["Market price and number of shares","Dividend yield and book value","Expected return and standard deviation","Liquidity and gearing"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM assumes risk-averse investors who judge securities by their expected return and their risk measured by standard deviation. Options A, B and D are ratio and market measures that the model does not use as its basis of choice."}},{"itemId":"eb7891e2-3c62-5b71-b697-a685ce30b55c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4ac52d9d-3298-5c6c-a2aa-77aa85a9c129","sourceKey":"bank:BUA216:CAP-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an assumption of the capital asset pricing model?","options":["Investors cannot borrow at the risk-free rate","Securities can only be bought in large, indivisible blocks","All investors share the same forecasts of returns and risk","Different investors have different forecasts and planning horizons"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM assumes all investors share the same single-period horizon and the same forecasts, called homogeneous expectations. Option B contradicts the assumption that securities are perfectly divisible, and Option A contradicts free borrowing and lending at the risk-free rate."}},{"itemId":"6eed685d-2f79-5d5f-bfde-afda009a1625","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70da415f-4b8f-5a5a-a975-b6cc044e4db0","sourceKey":"bank:BUA216:CAP-030","parentItemId":null,"revision":1,"payload":{"prompt":"The CAPM assumption that 'securities are perfectly divisible' means that:","options":["An investor can buy any fraction of a security, however small","Every security pays a dividend that can be divided among shareholders","Securities can be split into systematic and unsystematic parts","Each investor must hold an equal number of shares in every company"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Perfect divisibility means investments can be bought in any amount, so investors can hold exactly the portfolio weights they want. Option C confuses divisibility with the split of risk into its two types."}},{"itemId":"ed5fa6e8-842d-514e-bee9-b118413e173e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"13ae0434-0300-5b5c-86ff-ceea29b967d1","sourceKey":"bank:BUA216:CAP-031","parentItemId":null,"revision":1,"payload":{"prompt":"In the CAPM equation, which input is specific to the individual security rather than common to all securities in the market?","options":["The market risk premium","Beta","The expected market return","The risk-free rate"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"RF, Rm and therefore Rm - RF are the same for every security in a market, so the only security-specific input is beta. That is why two securities in the same market have different required returns only because their betas differ; Options A, C and D are shared inputs."}},{"itemId":"9775c491-30c7-5446-90aa-09335a1a998c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fe9f52e7-f3f1-5ceb-9fb3-4c39ed5ab393","sourceKey":"bank:BUA216:CAP-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of risk is rewarded with extra expected return under CAPM?","options":["Neither type of risk","Unsystematic risk, measured by standard deviation","Unsystematic risk, measured by beta","Systematic risk, measured by beta"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM adds a premium of (Rm - RF) x beta, so only systematic risk, measured by beta, earns extra return. Unsystematic risk can be diversified away at no cost, so Options B and C are wrong, and Option A ignores the premium altogether."}},{"itemId":"7c260278-2a40-5e9b-a662-d6b2a33e8e3e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ff9e6d8b-24a5-598b-8a28-e6db7caadd4c","sourceKey":"bank:BUA216:CAP-033","parentItemId":null,"revision":1,"payload":{"prompt":"A security with a beta of 1.0 is expected to:","options":["Move in the opposite direction to the market","Be twice as volatile as the market","Have no systematic risk at all","Move in line with the market, with the same systematic risk as the market"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The market itself has a beta of 1.0, so a security with beta 1.0 has the same systematic risk as the market and, under CAPM, a required return equal to Rm. Option C describes a beta of zero, and Option A describes a negative beta."}},{"itemId":"a270d41d-7cae-5c80-9e3d-90352d70ac29","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"074bd1fa-6ebf-5788-9e4e-22fb8c86a022","sourceKey":"bank:BUA216:CAP-034","parentItemId":null,"revision":1,"payload":{"prompt":"Share P has a beta of 1.6 and share Q has a beta of 0.7. Which statement is correct?","options":["Q has more systematic risk than the market and P has less","P will always earn a lower return than Q","Both have less systematic risk than the market","P has more systematic risk than the market and Q has less"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A beta above 1 means a share is more sensitive to market movements than the market itself, and a beta below 1 means less sensitive. Option A reverses this, and Option B is wrong because, under CAPM, the higher-beta share P has the higher required return."}},{"itemId":"a891321a-49a6-5ded-8fb0-44fa16e0a594","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"53745208-169d-5020-b880-5e4397e9a7fd","sourceKey":"bank:BUA216:CAP-035","parentItemId":null,"revision":1,"payload":{"prompt":"As more securities with less than perfectly positive correlation are added to a portfolio, the portfolio's total risk:","options":["Falls, until mainly systematic risk remains","Rises steadily with each security added","Falls to zero once about 20 securities are held","Stays the same, because risk depends only on beta"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Diversification removes unsystematic risk, so total risk falls as securities are added, but it levels off at the systematic risk that cannot be diversified away. Option C is wrong because systematic risk never disappears, and Option B is the opposite of the diversification effect."}},{"itemId":"7e85b2dc-c07d-5d25-bb64-0995aca1fde2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d3090485-5ccf-5538-9e9c-05b4888e2120","sourceKey":"bank:BUA216:CAP-036","parentItemId":null,"revision":1,"payload":{"prompt":"Two-security portfolios are formed from shares with the same standard deviations but different correlation coefficients. Which correlation gives the GREATEST reduction in portfolio risk?","options":["+1.0","+0.5","-1.0","0.0"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The lower the correlation between two securities, the more their movements offset each other, and a correlation of -1.0 gives the greatest risk reduction (risk can even be eliminated with the right weights). Option A, perfect positive correlation, gives no risk reduction at all, and Options B and D give partial reduction."}},{"itemId":"e1e44ca0-ebe3-509f-af37-72f69322f5b9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ec5407bf-9c7c-5c42-ba91-d56ef1fb183f","sourceKey":"bank:BUA216:CAP-037","parentItemId":null,"revision":1,"payload":{"prompt":"In portfolio theory, the efficient frontier is:","options":["The set of portfolios that contain only risk-free assets","The set of portfolios with a beta of exactly 1.0","The line showing required return against beta for single securities","The set of portfolios that give the highest expected return for each level of risk"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The efficient frontier, from Markowitz's portfolio choice model, traces the portfolios that offer the most return for each level of risk (or the least risk for each return); no rational investor would choose a portfolio below it. Option C describes the security market line, which uses beta rather than total risk."}},{"itemId":"3a343db0-9406-5ef9-ba54-81e1d1622076","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"104e54c9-f76c-5a3e-8425-4f8d4bd34c00","sourceKey":"bank:BUA216:CAP-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes the capital market line (CML) from the security market line (SML)?","options":["Both lines measure risk by the coefficient of variation","The CML plots return against beta; the SML plots return against standard deviation","The CML applies only to single securities; the SML applies only to portfolios","The CML plots return against standard deviation for efficient portfolios; the SML plots required return against beta for any security"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The CML measures risk by total risk (standard deviation) and applies to efficient portfolios that combine the market portfolio with the risk-free asset, while the SML measures risk by beta and prices any security. Option B swaps the two risk measures, and Option C reverses where each line applies."}},{"itemId":"7af17c56-e61a-5662-accb-87db50eda2c2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0b6b1937-e83c-564e-9f77-8bff4a4b61b4","sourceKey":"bank:BUA216:CAP-039","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a recognised limitation of the capital asset pricing model?","options":["Beta is usually estimated from past data and may not hold in future","It shows that unsystematic risk earns a higher return than systematic risk","Its assumptions of no taxes and no transaction costs are unrealistic","It is hard to identify a truly risk-free rate and the true market return"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM says the opposite: only systematic risk earns a premium, so Option B is not a limitation but a misstatement of the model. Options A, C and D are genuine criticisms, since the perfect-market assumptions are unrealistic and the inputs RF, Rm and beta must be estimated."}},{"itemId":"7a93ec49-3a4b-5609-b456-f95b1647471e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ec5c5a5e-056f-5e69-83cd-d5e1f28264f9","sourceKey":"bank:BUA216:CAP-040","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 10%, the expected return on the market is 16% and a share has a beta of 1.5. Using CAPM, the share's required return is:","options":["9%","19%","34%","25%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = RF + (Rm - RF) x beta = 10% + (16% - 10%) x 1.5 = 10% + 9% = 19%. Option C multiplies the whole market return by beta instead of the market risk premium, and Option A forgets to add the risk-free rate."}},{"itemId":"33fc051e-df50-5297-a07f-e8c40a55e3cb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f44c918-e759-5f4b-b015-1b6854c6d792","sourceKey":"bank:BUA216:CAP-041","parentItemId":null,"revision":1,"payload":{"prompt":"Treasury bills yield 8% and the stock market is expected to return 14%. What is the required return on a share with a beta of 0.6?","options":["11.6%","3.6%","16.4%","18%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = 8% + (14% - 8%) x 0.6 = 8% + 3.6% = 11.6%. Option D divides the market risk premium by beta instead of multiplying, and Option C applies beta to the full 14% market return."}},{"itemId":"9cbf469e-cb9a-58d9-ad5f-8b1973c4cc4c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5998bb10-c8b2-5e8c-92ee-8e82d706efc6","sourceKey":"bank:BUA216:CAP-042","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 9% and the expected market return is 15%. What is the CAPM required return on a share with a beta of 1.0?","options":["9%","6%","15%","24%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = 9% + (15% - 9%) x 1.0 = 15%, so a share with beta 1.0 requires exactly the market return. Option B is only the market risk premium, and Option A is the return for a beta of zero."}},{"itemId":"0ca9230a-51f3-594f-acf6-41988d22f4d1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"74397497-7a41-5473-839b-afd716f3066f","sourceKey":"bank:BUA216:CAP-043","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 11% and the expected market return is 17%. What is the CAPM required return on an investment with a beta of zero?","options":["0%","6%","11%","17%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"With beta = 0, E(R) = 11% + (17% - 11%) x 0 = 11%, so an investment with no systematic risk earns only the risk-free rate. Option A forgets that RF is still added, and Option D is the return for a beta of 1.0."}},{"itemId":"7e918941-3a55-51dd-a27d-dd7a922bb506","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb6a2984-68a1-55f8-92cb-373904e66129","sourceKey":"bank:BUA216:CAP-044","parentItemId":null,"revision":1,"payload":{"prompt":"Given RF = 0.07, Rm = 0.13 and a beta of 2.2, the expected return on the security using CAPM is (to 1 decimal place):","options":["13.2%","26.2%","20.2%","35.6%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = 0.07 + (0.13 - 0.07) x 2.2 = 0.07 + 0.132 = 0.202, or 20.2%. Option D multiplies 0.13 by beta instead of the premium 0.06, and Option B adds the premium to Rm instead of RF."}},{"itemId":"f27e30a7-0bc2-5be5-b666-49e76eaec440","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5390876c-7f3b-5d2c-a604-46cecdba4a0f","sourceKey":"bank:BUA216:CAP-045","parentItemId":null,"revision":1,"payload":{"prompt":"Lekki Logistics Plc has a beta of 1.2. The treasury bill rate is 12.5% and the stock market is expected to return 20%. The return shareholders require on Lekki Logistics shares is:","options":["24%","21.5%","9%","18.75%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = 12.5% + (20% - 12.5%) x 1.2 = 12.5% + 9% = 21.5%. Option A simply multiplies the market return by beta and ignores the risk-free rate, and Option D divides the premium by beta."}},{"itemId":"187d71fb-6b64-52f4-bed6-fd4811d26dd8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e3c9f6a7-38b8-54c7-9b83-8c2e026711b1","sourceKey":"bank:BUA216:CAP-046","parentItemId":null,"revision":1,"payload":{"prompt":"An investor expects the market to return 11%, while government treasury bills pay 6%. A share has a beta of 1.8. By how many percentage points does the share's CAPM required return exceed the market's expected return?","options":["9 percentage points","4 percentage points","4.8 percentage points","5 percentage points"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Required return = 6% + (11% - 6%) x 1.8 = 15%, which is 15% - 11% = 4 percentage points above the market. Option D is just the market risk premium, and Option A is the share's risk premium over RF, not over the market."}},{"itemId":"e9537bbd-6432-5e5a-9662-179aa4040e54","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1244ffee-8b70-569b-8c30-c3df82c38973","sourceKey":"bank:BUA216:CAP-047","parentItemId":null,"revision":1,"payload":{"prompt":"The expected return on the market is 18% and the risk-free rate is 11%. The market risk premium is:","options":["29%","14.5%","7%","18%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Market risk premium = Rm - RF = 18% - 11% = 7%, the extra return the market pays above the risk-free rate. Option A adds the two rates, and Option D is the market return itself, not the premium."}},{"itemId":"5e9e0c3f-782e-518a-8e7f-aa4af1bcb6c5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"78c850df-2afd-5388-a8d3-d7320e591f41","sourceKey":"bank:BUA216:CAP-048","parentItemId":null,"revision":1,"payload":{"prompt":"A share with a beta of 1.6 has a CAPM required return of 17%. If the risk-free rate is 9%, the market risk premium is:","options":["5%","12.8%","10.62%","8%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"From E(R) = RF + (Rm - RF) x beta, (Rm - RF) = (E(R) - RF) / beta = (17% - 9%) / 1.6 = 5%. Option D is the share's own risk premium before dividing by beta, and Option B multiplies by beta instead of dividing."}},{"itemId":"3672ccb2-a925-5562-8b99-8fa140bf9d08","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2731e3a9-9805-547a-864d-6ef066210a86","sourceKey":"bank:BUA216:CAP-049","parentItemId":null,"revision":1,"payload":{"prompt":"A share has a CAPM required return of 20%. The risk-free rate is 8% and the expected market return is 16%. The share's beta is (to 2 decimal places):","options":["0.67","1.25","1.5","2.5"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Rearranging CAPM, beta = (E(R) - RF) / (Rm - RF) = (20 - 8) / (16 - 8) = 12 / 8 = 1.5. Option A turns the fraction upside down, and Option B divides the share's return by the market return without removing RF."}},{"itemId":"573751c5-3079-55cf-b0b5-ad19acd2da1f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0e32ea2b-dde0-5e5f-a8b2-10170604acf1","sourceKey":"bank:BUA216:CAP-050","parentItemId":null,"revision":1,"payload":{"prompt":"A share has a CAPM required return of 13%. The risk-free rate is 10% and the expected market return is 16%. The share's beta is (to 2 decimal places):","options":["1.3","0.5","0.81","2"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Rearranging CAPM, beta = (E(R) - RF) / (Rm - RF) = (13 - 10) / (16 - 10) = 3 / 6 = 0.5. Option D turns the fraction upside down, and Option C divides the share's return by the market return without removing RF."}},{"itemId":"bd709018-626e-5c80-aab6-6f51b010a7f2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0e85d554-5f36-5321-8df2-37b9014d3eb6","sourceKey":"bank:BUA216:CAP-051","parentItemId":null,"revision":1,"payload":{"prompt":"A share has a CAPM required return of 15.6%. The risk-free rate is 12% and the expected market return is 18%. The share's beta is (to 2 decimal places):","options":["0.60","1.67","1.3","0.87"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Rearranging CAPM, beta = (E(R) - RF) / (Rm - RF) = (15.6 - 12) / (18 - 12) = 3.6 / 6 = 0.6. Option B turns the fraction upside down, and Option D divides the share's return by the market return without removing RF."}},{"itemId":"18c2c7a9-0330-5370-ac14-05a4acf156fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0aacad3e-861a-5b07-9ef6-c2425a8d864e","sourceKey":"bank:BUA216:CAP-052","parentItemId":null,"revision":1,"payload":{"prompt":"A share with a beta of 0.5 has a CAPM required return of 14% when the expected market return is 18%. The risk-free rate is:","options":["5%","4%","16%","10%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = RF + (Rm - RF) x beta gives 14 = RF + (18 - RF) x 0.5 = 0.5RF + 9, so 0.5RF = 5 and RF = 10%. Option A stops at 5% and forgets that RF also appears inside the bracket, and Option B is just the gap between the two returns."}},{"itemId":"61f72073-49be-53eb-ad67-b767c1764371","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"645423c3-5ec7-5b27-85ee-76e4dd70cd6d","sourceKey":"bank:BUA216:CAP-053","parentItemId":null,"revision":1,"payload":{"prompt":"The market risk premium is 6%. A share with a beta of 1.4 has a CAPM required return of 18.4%. The risk-free rate is:","options":["8.4%","13.14%","10%","12.4%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"RF = E(R) - (Rm - RF) x beta = 18.4% - 6% x 1.4 = 18.4% - 8.4% = 10%. Option D subtracts the premium without multiplying by beta, and Option A is the share's risk premium, not the risk-free rate."}},{"itemId":"0d8f282c-a7d3-5a48-a6d2-b7bd34000155","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"79936d80-01ce-5b4f-ad62-17ccdc9a8caf","sourceKey":"bank:BUA216:CAP-054","parentItemId":null,"revision":1,"payload":{"prompt":"A share with a beta of 1.5 has a CAPM required return of 22%. The risk-free rate is 10%. The expected return on the market is:","options":["8%","28%","18%","14.67%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"(Rm - RF) = (E(R) - RF) / beta = (22 - 10) / 1.5 = 8%, so Rm = 10% + 8% = 18%. Option A is only the market risk premium, and Option B multiplies by beta instead of dividing."}},{"itemId":"8bb1c308-1c4d-5f18-83aa-87d1b2384fff","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7c02579d-ba7b-572c-916c-2b77604d722f","sourceKey":"bank:BUA216:CAP-055","parentItemId":null,"revision":1,"payload":{"prompt":"A defensive share with a beta of 0.85 has a CAPM required return of 12.4% when the risk-free rate is 9%. The expected market return is (to 2 decimal places):","options":["11.89%","14.59%","13%","4%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"(Rm - RF) = (12.4 - 9) / 0.85 = 4%, so Rm = 9% + 4% = 13%. Option A multiplies the share's premium by beta, and Option D gives only the market risk premium."}},{"itemId":"eb0f8432-792d-5da4-a68c-ddfb673ca07b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0a86a286-ab6e-5421-a709-f622625e0483","sourceKey":"bank:BUA216:CAP-056","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 10%, Rm = 15%. Share J has a beta of 1.2 and an analyst forecasts its return at 17%. According to CAPM, share J is:","options":["Overpriced, because its SML return is 28%","Correctly priced, because its SML return is 17%","Underpriced, because its SML return is 16%","Overpriced, because its SML return is 16%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML return = 10% + (15% - 10%) x 1.2 = 16%. The forecast 17% is above 16%, so J offers more than its risk requires and is underpriced. Option D gets the number right but reverses the rule, and Option A multiplies the full market return by beta."}},{"itemId":"21360778-4c0a-5a58-b29c-ae03aba36a06","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a5ae38a9-394f-5ca0-a240-d761a53b244d","sourceKey":"bank:BUA216:CAP-057","parentItemId":null,"revision":1,"payload":{"prompt":"The treasury bill rate is 9% and the market return is 14%. Security K has a beta of 1.8 and a given return of 17%. Security K is:","options":["Overpriced, because its given return is below its SML return of 18%","Correctly priced, because its SML return is 17%","Underpriced, because its given return is above its SML return of 11.78%","Underpriced, because its given return is above the market return of 14%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML return = 9% + (14% - 9%) x 1.8 = 18%. The given 17% is below 18%, so K is overpriced. Option D wrongly compares the return with Rm instead of the SML for K's own beta, and Option C divides the premium by beta."}},{"itemId":"fe5becc3-7e42-5427-b7d6-a31c21ba2486","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ae1cf98-57bf-5d5e-9156-b1d5cb255278","sourceKey":"bank:BUA216:CAP-058","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 12% and Rm = 17%. Security L has a beta of 0.6 and its expected return is estimated at 15%. Security L is:","options":["Risk-free, because its beta is below 1","Overpriced","Correctly priced","Underpriced"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML return = 12% + (17% - 12%) x 0.6 = 12% + 3% = 15%, exactly equal to the estimated 15%, so L is correctly priced. Option B might come from comparing 15% with Rm of 17%, and Option A is wrong because any positive beta carries systematic risk."}},{"itemId":"804d0b82-64b0-578b-9b94-fb027b5f54a6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6a61e1d3-af7a-5461-8725-758228472949","sourceKey":"bank:BUA216:CAP-059","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 8% and the market return is 13%. Three shares have the following betas and forecast returns: A (beta 0.8, 13%), B (beta 1.4, 14%), C (beta 2.0, 18%). Which share(s) are underpriced?","options":["C only","A and C","B only","A only"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML returns are A: 8% + 5% x 0.8 = 12%, B: 8% + 5% x 1.4 = 15% and C: 8% + 5% x 2.0 = 18%. Only A's forecast (13%) is above its SML return, so only A is underpriced; B is below its SML (overpriced) and C is exactly on it (correctly priced), which rules out Options B and C."}},{"itemId":"883d8be7-8ee4-50f9-9671-e90f0121a059","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a48adc7-5531-5b97-9759-ffd0b12f9676","sourceKey":"bank:BUA216:CAP-060","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 11% and Rm = 16%. Securities X, Y and Z have betas of 0.4, 1.0 and 1.6 and given returns of 14%, 16% and 18% respectively. Which security is overpriced?","options":["None of them","Z","Y","X"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML returns: X = 11% + 5% x 0.4 = 13%, Y = 11% + 5% x 1.0 = 16%, Z = 11% + 5% x 1.6 = 19%. Z's given 18% is below its 19% SML return, so Z is overpriced. X is above its SML (underpriced) and Y is on it (correctly priced), so Options C and D are wrong."}},{"itemId":"9631f8e8-a384-5691-826d-944dcbc2a8c5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"854ff99c-5e73-5694-ade0-6d00fe31c7f1","sourceKey":"bank:BUA216:CAP-061","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 10%, Rm = 16%. A share with a beta of 0.9 is forecast to return 17.5%. By how much is the forecast return above or below the share's SML return?","options":["1.5 percentage points above","7.5 percentage points above","6.9 percentage points below","2.1 percentage points above"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML return = 10% + (16% - 10%) x 0.9 = 15.4%, so the forecast 17.5% is 17.5 - 15.4 = 2.1 percentage points above the SML (the share is underpriced). Option A compares with Rm instead, and Option C comes from multiplying the whole market return by beta."}},{"itemId":"cf3b787a-c82b-56f4-ba94-2f7d540bfad1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4f2ff561-c721-568e-8feb-0d88f4108537","sourceKey":"bank:BUA216:CAP-062","parentItemId":null,"revision":1,"payload":{"prompt":"Treasury bills yield 7% and the market is expected to return 12%. Ota Breweries Plc has a beta of 1.5, and its shares are expected to return 13%. Which option correctly gives the required return and the pricing verdict?","options":["25%; overpriced","14.5%; underpriced","7.5%; underpriced","14.5%; overpriced"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Required return = 7% + (12% - 7%) x 1.5 = 14.5%. The expected 13% is below 14.5%, so the share is overpriced. Option B has the right figure but the wrong verdict, Option A multiplies Rm by beta, and Option C forgets to add RF."}},{"itemId":"6962c6b5-301b-5058-9d0a-d1e811c412a1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"72d46fd8-4377-599c-8139-a0a92d3307f7","sourceKey":"bank:BUA216:CAP-063","parentItemId":null,"revision":1,"payload":{"prompt":"A share's possible returns are 10% (probability 0.3), 18% (probability 0.5) and 26% (probability 0.2). Its beta is 1.5, RF = 9% and Rm = 15%. Comparing its expected return with its CAPM required return, the share is:","options":["Overpriced, since its expected return of 17.2% is below the required 18%","Underpriced, since its expected return of 17.2% is above the market return of 15%","Correctly priced, since its expected return of 18% equals the required return","Underpriced, since its expected return of 17.2% is above the required 13%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Expected return = 0.3 x 10% + 0.5 x 18% + 0.2 x 26% = 17.2%, and required return = 9% + (15% - 9%) x 1.5 = 18%. Since 17.2% is below 18%, the share is overpriced. Option B compares with Rm instead of the SML return for this beta, and Option C uses a simple average of the returns."}},{"itemId":"5c10558c-2ee8-5bd5-96ef-f8c337f1b4ab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"09082ee4-989c-56bd-b6ab-998b1d3d3bf3","sourceKey":"bank:BUA216:CAP-064","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is made up of 60% in security X, expected to return 15%, and 40% in security Y, expected to return 25%. The expected return on the portfolio is:","options":["20%","40%","21%","19%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"PR = WxRx + WyRy = (0.6 x 15%) + (0.4 x 25%) = 9% + 10% = 19%. Option A is a simple average that ignores the weights, Option C attaches the weights to the wrong securities, and Option B adds the returns."}},{"itemId":"06c4ca01-442c-501d-be27-7d80db44a21d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2f2d1dd9-ae5b-54e3-9e57-7de48a9bdc76","sourceKey":"bank:BUA216:CAP-065","parentItemId":null,"revision":1,"payload":{"prompt":"Security A is expected to return 12% and security B 20%. If an investor puts 25% of his funds in A and 75% in B, the portfolio's expected return is:","options":["14%","18%","16%","32%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"PR = (0.25 x 12%) + (0.75 x 20%) = 3% + 15% = 18%. Option A reverses the weights, and Option C is the simple average of the two returns."}},{"itemId":"8ec1557c-2e4f-5ab9-9aed-95b61b6831b1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8a695e80-b039-5356-8bb6-1acc1926c1a9","sourceKey":"bank:BUA216:CAP-066","parentItemId":null,"revision":1,"payload":{"prompt":"Mrs Adebayo invests N300,000 in Ilorin Cement shares, expected to return 14%, and N700,000 in Benin Foods shares, expected to return 24%. The expected return on her portfolio is:","options":["21%","38%","17%","19%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The weights are 300,000/1,000,000 = 0.3 and 700,000/1,000,000 = 0.7, so PR = (0.3 x 14%) + (0.7 x 24%) = 4.2% + 16.8% = 21%. Option D ignores the different amounts invested, and Option C attaches the larger weight to the lower-return share."}},{"itemId":"14954f1e-29ae-58f8-9349-63b89fec00fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e58b7534-aea6-5c1c-895f-01b0f8658ad6","sourceKey":"bank:BUA216:CAP-067","parentItemId":null,"revision":1,"payload":{"prompt":"An investor holds N450,000 in share L, expected to return 10%, and N150,000 in share M, expected to return 22%. The expected return on the portfolio is:","options":["19%","16%","32%","13%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Total invested is N600,000, so the weights are 450/600 = 0.75 and 150/600 = 0.25. PR = (0.75 x 10%) + (0.25 x 22%) = 7.5% + 5.5% = 13%. Option B is the unweighted average, and Option A swaps the weights."}},{"itemId":"d4b0a260-0b49-516b-8f06-8c50a1724b89","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2541302-20b8-5360-ac80-c82332f5b506","sourceKey":"bank:BUA216:CAP-068","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio contains three securities: 50% in P (expected return 12%), 30% in Q (18%) and 20% in R (25%). The portfolio's expected return is:","options":["20.3%","55%","16.4%","18.33%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(Rp) = SUM[wi x E(Ri)] = (0.5 x 12%) + (0.3 x 18%) + (0.2 x 25%) = 6% + 5.4% + 5% = 16.4%. Option D is the simple average of the three returns, and Option A attaches 50% to R and 20% to P."}},{"itemId":"f45caccd-e3a5-5381-a1e2-c004a4899a30","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"89337d81-6d38-5eee-b38b-8b0fb280ca73","sourceKey":"bank:BUA216:CAP-069","parentItemId":null,"revision":1,"payload":{"prompt":"An investment club invests N200,000 in share A (expected return 10%), N300,000 in share B (16%) and N500,000 in share C (22%). The expected return on the club's portfolio is:","options":["16%","48%","14.2%","17.8%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Total is N1,000,000, giving weights of 0.2, 0.3 and 0.5. E(Rp) = (0.2 x 10%) + (0.3 x 16%) + (0.5 x 22%) = 2% + 4.8% + 11% = 17.8%. Option A is the simple average, and Option C attaches the largest weight to the lowest-return share."}},{"itemId":"951dcd46-a221-5544-88d7-3fd5e23df2c3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb558db0-14f1-56ec-b4f7-e995f6f11b26","sourceKey":"bank:BUA216:CAP-070","parentItemId":null,"revision":1,"payload":{"prompt":"An investor places N2,000,000 in a portfolio, 40% in share S (expected return 15%) and 60% in share T (expected return 20%). The expected return on the portfolio in naira is:","options":["N360,000","N340,000","N700,000","N350,000"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Portfolio return = (0.4 x 15%) + (0.6 x 20%) = 6% + 12% = 18%, and 18% of N2,000,000 = N360,000. Option D uses the simple average of 17.5%, and Option B swaps the weights to get 17%."}},{"itemId":"d532601c-408d-54cb-8ff4-1cefbce49082","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f1439ba0-c226-5328-adc1-807b26b3cca8","sourceKey":"bank:BUA216:CAP-071","parentItemId":null,"revision":1,"payload":{"prompt":"Security X is expected to return 10% and security Y 22%. What proportion of a two-security portfolio must be invested in Y to achieve an expected return of 17% (to 2 decimal places)?","options":["50%","41.67%","58.33%","77.27%"],"correctOption":2,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Let w be the weight in Y: 10(1 - w) + 22w = 17, so 12w = 7 and w = 7/12 = 58.33%. Option B is the weight in X, and Option D divides the target by Y's return, ignoring X altogether."}},{"itemId":"cea57b12-638c-5a1e-a744-aa975901a7d3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ece0821a-9290-5ef4-9239-75931cbe088d","sourceKey":"bank:BUA216:CAP-072","parentItemId":null,"revision":1,"payload":{"prompt":"Share A is expected to return 8% and share B 20%. To earn 17% on a portfolio of only A and B, the proportion invested in A must be:","options":["85%","75%","50%","25%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"With weight w in B, 8(1 - w) + 20w = 17, so 12w = 9 and w = 75% in B, leaving 25% in A. Option B is the weight in B, not A, and Option A divides the target return by B's return."}},{"itemId":"40e2b1f6-18fe-5e4c-b3ec-34f39248cb3c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3ad10dfa-83ce-5371-ab96-ca3e6c3bc526","sourceKey":"bank:BUA216:CAP-073","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 10% and Rm = 15%. Share L has a beta of 0.6 and share M a beta of 1.8. Using their SML returns, what is the expected return on a portfolio of 40% L and 60% M?","options":["16%","16.6%","15.4%","29.8%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML returns are L = 10% + 5% x 0.6 = 13% and M = 10% + 5% x 1.8 = 19%. PR = (0.4 x 13%) + (0.6 x 19%) = 5.2% + 11.4% = 16.6%. Option C swaps the weights, and Option D comes from multiplying the full market return by beta when finding each SML return."}},{"itemId":"6ea0895a-9482-5f0f-9477-072b3f92b916","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5dc718d2-5c90-5c03-a697-797b5c12ab94","sourceKey":"bank:BUA216:CAP-074","parentItemId":null,"revision":1,"payload":{"prompt":"The treasury bill rate is 9% and the market return is 13%. An investor puts 70% of her funds in share G (beta 0.5) and 30% in share H (beta 2.0). Using CAPM returns, the expected portfolio return is:","options":["12.8%","15.2%","21.35%","14%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"CAPM returns are G = 9% + 4% x 0.5 = 11% and H = 9% + 4% x 2.0 = 17%. PR = (0.7 x 11%) + (0.3 x 17%) = 12.8%. Option D ignores the weights, and Option B attaches 70% to H instead of G."}},{"itemId":"cd76798f-531d-565f-bb93-4dbe2c28c858","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5417a3dc-9c44-5012-adec-5d2b6143e4f5","sourceKey":"bank:BUA216:CAP-075","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is invested 40% in a share with a beta of 0.9 and 60% in a share with a beta of 1.4. The portfolio beta is:","options":["1.2","1.1","1.15","2.3"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A portfolio's beta is the weighted average of the individual betas: (0.4 x 0.9) + (0.6 x 1.4) = 0.36 + 0.84 = 1.2. Option C is the simple average, and Option B attaches the weights to the wrong shares."}},{"itemId":"ec705015-0a3b-57e0-8e6f-18bfd3164754","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"07df986f-d4d2-5f40-935a-27d82f3de9ba","sourceKey":"bank:BUA216:CAP-076","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund holds N500,000 in share A (beta 1.2), N300,000 in share B (beta 0.8) and N200,000 in share C (beta 1.5). The beta of the fund's portfolio is:","options":["1.23","1.14","1.17","3.5"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Weights are 0.5, 0.3 and 0.2 of the N1,000,000 total, so portfolio beta = (0.5 x 1.2) + (0.3 x 0.8) + (0.2 x 1.5) = 0.6 + 0.24 + 0.3 = 1.14. Option C is the simple average of the betas, and Option A attaches 50% to C instead of A."}},{"itemId":"c0b2470f-694d-59e8-a0f3-75b89014f419","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"eea1b6c0-b047-529c-b4cf-eb55f0f9342e","sourceKey":"bank:BUA216:CAP-077","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is split equally between a share with a beta of 0.8 and a share with a beta of 1.6. If RF = 10% and Rm = 15%, the CAPM required return on the portfolio is:","options":["16%","6%","15%","28%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Portfolio beta = (0.5 x 0.8) + (0.5 x 1.6) = 1.2, so E(Rp) = 10% + (15% - 10%) x 1.2 = 16%. Option C assumes a beta of 1.0, Option D multiplies the full market return by beta, and Option B leaves out RF."}},{"itemId":"5e3a91e1-7fbb-5c6a-89d4-9ca40a1abad9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"474fc1b4-d375-5950-87f9-0e6e61c97924","sourceKey":"bank:BUA216:CAP-078","parentItemId":null,"revision":1,"payload":{"prompt":"An investor holds a fund with a beta of 1 and wants to combine it with a share of beta 1.8 so that the overall portfolio beta is 1.32. What proportion of the portfolio must be in the beta 1.8 share?","options":["60%","40%","73.33%","32%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"With weight w in the share, (1 - w) x 1.0 + w x 1.8 = 1.32, so 0.8w = 0.32 and w = 40%. Option A is the weight left in the fund, and Option C divides the target beta by 1.8 without allowing for the fund's own beta."}},{"itemId":"ae744b0b-11e3-523f-86c6-165ed7d47708","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c30b3f92-18c6-5286-a512-7040e76b4908","sourceKey":"bank:BUA216:CAP-079","parentItemId":null,"revision":1,"payload":{"prompt":"The covariance between the returns on share Z and the market is 0.0048. The variance of market returns is 0.004 and the variance of share Z's returns is 0.009. Taking beta as covariance(Z, market) / variance(market), the beta of share Z is:","options":["0.8","1.2","0.53","0.83"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Beta = Cov(Z, M) / Var(M) = 0.0048 / 0.004 = 1.2. Option D turns the fraction upside down, Option C divides by the share's own variance, and Option A is the correlation coefficient, which divides by both standard deviations."}},{"itemId":"b898d7ce-df76-5fe0-8458-0039d89255fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2078c1f2-576f-50e8-87f9-6d87b20e3c8e","sourceKey":"bank:BUA216:CAP-080","parentItemId":null,"revision":1,"payload":{"prompt":"Share W has a standard deviation of 24%, the market has a standard deviation of 16%, and the correlation between them is 0.5. Taking beta = correlation x (SD of share / SD of market), the beta of W is:","options":["0.75","0.5","1.5","0.33"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Beta = 0.5 x (24 / 16) = 0.5 x 1.5 = 0.75. Option C leaves out the correlation, and Option D puts the market's standard deviation on top instead of the share's."}},{"itemId":"9a1d20ad-6eaf-5400-994a-d69c38f1fafd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3d2f956d-a7eb-5c20-9bf4-9eb78a31580d","sourceKey":"bank:BUA216:CAP-081","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is 60% in share A (standard deviation 20%) and 40% in share B (standard deviation 30%). The correlation between A and B is 0.2. Using Var(p) = wA^2 SDA^2 + wB^2 SDB^2 + 2 wA wB r SDA SDB, the portfolio standard deviation is (to 2 decimal places):","options":["24%","18.59%","25%","16.97%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Var(p) = (0.36 x 400) + (0.16 x 900) + (2 x 0.6 x 0.4 x 0.2 x 20 x 30) = 144 + 144 + 57.6 = 345.6, so SD = square root of 345.6 = 18.59%. Option A is the weighted average of the standard deviations, which is only correct when the correlation is +1, and Option D leaves out the covariance term."}},{"itemId":"89c66e76-0a93-57d5-b8ff-e5040ed0ab6f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"693afc24-5b44-54e0-8bd2-ea787fea8512","sourceKey":"bank:BUA216:CAP-082","parentItemId":null,"revision":1,"payload":{"prompt":"Shares A and B have standard deviations of 12% and 18% and are perfectly negatively correlated (correlation -1). What proportion of the portfolio must be in A to make the portfolio's risk zero?","options":["60%","40%","66.67%","50%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"With correlation -1, portfolio SD = |wA x 12 - wB x 18|, which is zero when wA x 12 = (1 - wA) x 18, giving wA = 18 / (12 + 18) = 60%. Option B is the weight in B, and Option D would leave the riskier share B dominating, so risk would not be zero."}},{"itemId":"f418460a-bbcc-510a-af41-a60a620921f9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2062a207-2aab-56b2-9ecc-02acf52d15b7","sourceKey":"bank:BUA216:CAP-083","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is split 50:50 between two shares with standard deviations of 10% and 20%. If the returns on the two shares are perfectly positively correlated (correlation +1), the portfolio standard deviation is:","options":["5%","15%","11.18%","22.36%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"With correlation +1 there is no diversification benefit, so the portfolio SD is simply the weighted average: (0.5 x 10%) + (0.5 x 20%) = 15%. Option C is the result for zero correlation and Option A is the result for correlation -1, both of which show risk falling only when correlation is below +1."}},{"itemId":"1f855f89-1835-56b8-98f2-93b3432d4477","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"99ce4bc1-c3eb-5ac2-ad42-d09793ff91c1","sourceKey":"bank:BUA216:CAP-084","parentItemId":null,"revision":1,"payload":{"prompt":"Using the capital market line E(Rp) = RF + [(Rm - RF) / SDm] x SDp, with RF = 10%, Rm = 18%, market standard deviation 20% and an efficient portfolio standard deviation of 15%, the expected portfolio return is:","options":["13.5%","6%","20.67%","16%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(Rp) = 10% + (8% / 20%) x 15% = 10% + 0.4 x 15% = 16%. Option C turns the risk ratio upside down, and Option B forgets to add the risk-free rate."}},{"itemId":"933002a8-58eb-50c2-baf0-f2206ee44a8e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9add377a-b29d-5946-8e36-579e29a5bf90","sourceKey":"bank:BUA216:CAP-085","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 11% and Rm = 17%. Share D has a beta of 1.5 and share E a beta of 0.5. The difference between their CAPM required returns is:","options":["3 percentage points","1 percentage point","17 percentage points","6 percentage points"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"D requires 11% + 6% x 1.5 = 20% and E requires 11% + 6% x 0.5 = 14%, a difference of 6 percentage points, which equals the 6% premium times the beta gap of 1.0. Option B is only the beta gap, and Option C applies the betas to the full market return."}},{"itemId":"4b1d96a5-0aa3-531c-bb89-6409ee2b2ae5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d5ec965d-383a-57ad-af0e-80eaf860aaec","sourceKey":"bank:BUA216:CAP-086","parentItemId":null,"revision":1,"payload":{"prompt":"If the market risk premium rises because Rm increases from 19% to 21% while RF stays at 13%, what is the new required return on a share with a beta of 1.25?","options":["23%","20.5%","26.25%","21%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"The new premium is 21% - 13% = 8%, so E(R) = 13% + 8% x 1.25 = 13% + 10% = 23%. Option B is the old required return using a 6% premium, and Option D leaves beta out of the calculation."}},{"itemId":"8c79bd55-c5bd-5a45-aa36-c159bde57b53","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"14139936-b742-59d3-9da1-bcd0c8984e53","sourceKey":"bank:BUA216:CAP-087","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 10% and Rm = 16%. If a share's beta doubles from 0.75 to 1.5, its CAPM required return:","options":["Doubles from 14.5% to 29%","Stays at 14.5%, because RF and Rm are unchanged","Rises from 22% to 34%","Rises from 14.5% to 19%"],"correctOption":3,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Old return = 10% + 6% x 0.75 = 14.5%; new return = 10% + 6% x 1.5 = 19%. Only the risk premium part doubles (from 4.5% to 9%), so Option A is wrong to double the whole return, and Option C multiplies the full market return by beta."}},{"itemId":"16db3c54-e5f7-5f8d-8c63-6236452ad82a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ed9c0006-a66d-5379-82fd-3ae30e954ab7","sourceKey":"bank:BUA216:CAP-088","parentItemId":null,"revision":1,"payload":{"prompt":"Using CAPM with RF = 10% and Rm = 14%, what is the required return on a share whose beta is 0.5?","options":["17%","12%","18%","7%"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"E(R) = 10% + (14% - 10%) x 0.5 = 10% + 2% = 12%. A beta below 1 gives a required return between RF and Rm. Option A multiplies the market return by beta, and Option C divides the premium by beta."}},{"itemId":"7b222367-1a61-5268-bd9d-3c67132bfb47","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"31949aaf-4c77-5ea8-9757-1c1f42f9972a","sourceKey":"bank:BUA216:CAP-089","parentItemId":null,"revision":1,"payload":{"prompt":"The treasury bill rate is 14% and the stock market return is 22%. Three shares have betas and forecast returns as follows: Ade (0.5, 19%), Bisi (1.5, 26%), Chidi (2.5, 33%). Which of them is correctly priced?","options":["Ade only","Bisi only","All three","Chidi only"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML returns: Ade = 14% + 8% x 0.5 = 18%, Bisi = 14% + 8% x 1.5 = 26%, Chidi = 14% + 8% x 2.5 = 34%. Only Bisi's forecast equals its SML return; Ade is above (underpriced) and Chidi is below (overpriced), so Options A and D are wrong."}},{"itemId":"f00dd2d0-58e3-56b9-9d54-975177133ec1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"98ef3039-e643-5da7-95cf-05187a5e4669","sourceKey":"bank:BUA216:CAP-090","parentItemId":null,"revision":1,"payload":{"prompt":"RF = 10% and Rm = 18%. Shares P, Q and R have betas of 0.5, 1.0 and 1.5 and forecast returns of 16%, 19% and 21%. Which share offers the largest return above its SML return?","options":["They are all equally attractive","P","Q","R"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"SML returns are P = 10% + 8% x 0.5 = 14%, Q = 10% + 8% x 1.0 = 18% and R = 10% + 8% x 1.5 = 22%. The gaps are P +2, Q +1 and R -1 percentage points, so P is the most underpriced. Option D might be chosen because R has the highest forecast return, but R is actually below its SML and so overpriced."}},{"itemId":"260411f7-2eca-520b-a2eb-25e0a3c2b8ca","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d4797e2c-36aa-555b-85f5-2ec0131bc2ec","sourceKey":"bank:BUA216:CAP-091","parentItemId":null,"revision":1,"payload":{"prompt":"Two correctly priced shares lie on the security market line. Share M has a beta of 0.8 and a return of 14.8%, and share N has a beta of 1.6 and a return of 19.6%. The market risk premium is:","options":["6%","3%","4.8%","18.5%"],"correctOption":0,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Along the SML each extra unit of beta adds one market risk premium, so (Rm - RF) = (19.6 - 14.8) / (1.6 - 0.8) = 4.8 / 0.8 = 6% (and RF = 14.8 - 6 x 0.8 = 10%). Option C is the gap in returns without dividing by the gap in beta, Option D wrongly divides a whole return by beta, while Option B divides by N's beta instead of the beta gap."}},{"itemId":"7cafdeb1-142d-56c6-96a4-438dfc06d558","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9928481d-26d2-528f-ab63-ad150028e474","sourceKey":"bank:BUA216:EFF-001","parentItemId":null,"revision":1,"payload":{"prompt":"Capital market efficiency describes a market in which","options":["security prices are fixed by the regulator to protect investors","security prices quickly and fully reflect all available information","security prices move slowly so that every investor can react in time","security prices are set mainly by the largest investors in the market"],"correctOption":1,"section":"Market Efficiency","explanation":"An efficient capital market is one where prices adjust quickly and fully to all available information, no single participant dominates and transaction costs are not high. Option A describes regulated prices, not efficient ones. Option C is the opposite of efficiency, because slow adjustment would let alert investors earn abnormal profits."}},{"itemId":"7c895950-a37d-51a7-ac19-1787deec80a5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ae14fdf-077a-59a1-aeb4-116b042a01c9","sourceKey":"bank:BUA216:EFF-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the features of an efficient capital market?","options":["Transaction costs are high enough to discourage frequent trading","No individual investor dominates the market","Security prices quickly and fully reflect all available information","Prices respond to new information as soon as it arrives"],"correctOption":0,"section":"Market Efficiency","explanation":"An efficient capital market has prices that fully reflect information, no dominant individual and transaction costs that are not high. High transaction costs work against efficiency because they stop investors from trading on new information, so prices adjust less fully. Option C, Option B and Option D are all genuine features of an efficient market."}},{"itemId":"e2685076-b5d5-5af3-859a-57455cddca74","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0f9e0a1b-c2ee-5844-95c1-eaf599d3d86c","sourceKey":"bank:BUA216:EFF-003","parentItemId":null,"revision":1,"payload":{"prompt":"On a small stock exchange, one investment group accounts for about 70% of all trades and can move share prices almost at will. Which condition for capital market efficiency is most clearly violated?","options":["Prices should reflect historical price information","Funds should move from surplus units to deficit units","No individual should dominate the market","Transaction costs should not be high"],"correctOption":2,"section":"Market Efficiency","explanation":"An efficient capital market requires that no individual dominates the market, so that prices come from many independent buyers and sellers. A group that can move prices at will breaks exactly this condition. Option D concerns trading costs, which the scenario does not mention, and Option B describes allocational efficiency rather than the problem of market power."}},{"itemId":"3fd3d289-1502-50ff-ac8a-373f2a215752","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"08476d7c-eee3-5531-9852-9f7842ea60f7","sourceKey":"bank:BUA216:EFF-004","parentItemId":null,"revision":1,"payload":{"prompt":"Stockbrokers on an exchange charge commissions of 9% on every purchase and every sale of shares, so many investors stop trading on news. Which feature of an efficient capital market is missing?","options":["Transaction costs that are not high","Transfer of savings to productive investment","Absence of any dominant individual investor","Prices determined by demand and supply"],"correctOption":0,"section":"Market Efficiency","explanation":"An efficient capital market needs transaction costs that are not high; very high commissions stop investors acting on information, so prices do not fully reflect it. Option C would be the issue if one investor controlled trading, which is not the case here. Option D and Option B describe pricing and allocational efficiency rather than the cost of trading."}},{"itemId":"9398d4cf-ec8c-5851-9081-e90dc4a90ee8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"795b564c-e34d-5436-8372-00743533e667","sourceKey":"bank:BUA216:EFF-005","parentItemId":null,"revision":1,"payload":{"prompt":"A capital market that transfers financial resources from surplus units to deficit units for productive investment, through the intermediation process, is said to have","options":["allocational efficiency","strong form efficiency","pricing efficiency","operational efficiency"],"correctOption":0,"section":"Market Efficiency","explanation":"Allocational efficiency is the optimal allocation of scarce savings to productive investment in a way that benefits all, which happens when funds pass from surplus units to deficit units. Option D is about intermediaries doing this job at minimum cost, not about where the funds go. Option C is about prices reflecting information correctly."}},{"itemId":"8aeb3724-e7dc-5a3d-8618-6b58224738fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a625a5d2-8193-5bec-a0ff-1461877aadf4","sourceKey":"bank:BUA216:EFF-006","parentItemId":null,"revision":1,"payload":{"prompt":"A market in which the intermediaries who channel funds from savers to borrowers do so at a minimum cost that still gives them a fair return for their services is said to be","options":["allocationally efficient","operationally efficient","pricing efficient","semi-strong form efficient"],"correctOption":1,"section":"Market Efficiency","explanation":"Operational efficiency is about the cost of intermediation: brokers, banks and other intermediaries move funds at minimum cost while earning fair compensation for their services. Option A concerns where savings end up (productive investment), not what the service costs. Option C concerns whether prices reflect information."}},{"itemId":"a05346a2-b48b-542a-921f-59dfd5e5d3f9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c70b8bcd-d700-59b8-a378-40526ef02a4b","sourceKey":"bank:BUA216:EFF-007","parentItemId":null,"revision":1,"payload":{"prompt":"Pricing efficiency in a capital market means that","options":["demand and supply set prices, based on a correct evaluation of all available information","the regulator approves the price of every new share issue in advance","intermediaries channel funds from savers to borrowers at minimum cost","savings are transferred from surplus units to deficit units for productive use"],"correctOption":0,"section":"Market Efficiency","explanation":"A market is price efficient when the forces of demand and supply set prices, prices act as signals for capital allocation, and they rest on a correct evaluation of all available information. Option C defines operational efficiency and Option D defines allocational efficiency. Option B describes administered pricing, which is not market pricing at all."}},{"itemId":"be7a1db8-21e6-50b7-88da-5874ba30d6fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1624977e-88cb-5d8b-857d-a803aedb8721","sourceKey":"bank:BUA216:EFF-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three classes of capital market efficiency?","options":["Allocational efficiency","Operational efficiency","Pricing efficiency","Distributional efficiency"],"correctOption":3,"section":"Market Efficiency","explanation":"The three classes of capital market efficiency are allocational, operational and pricing efficiency. Distributional efficiency is not one of them. Option A, Option B and Option C are the three recognised classes, dealing respectively with where funds go, the cost of moving them, and how well prices reflect information."}},{"itemId":"fc1bf3db-e301-5862-b872-bc21a030d1e7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fd7983fb-be5c-563e-8b33-3603461a3ba7","sourceKey":"bank:BUA216:EFF-009","parentItemId":null,"revision":1,"payload":{"prompt":"Through the Nigerian capital market, savings from thousands of households are raised by a bond issue and used to build a new cement plant that creates jobs and output. This mainly illustrates","options":["pricing efficiency","allocational efficiency","weak form efficiency","operational efficiency"],"correctOption":1,"section":"Market Efficiency","explanation":"Moving savings from surplus units (households) to a deficit unit (the cement company) for productive investment is allocational efficiency, the intermediation process. Option D would require information about the cost charged by intermediaries, which the scenario does not give. Option A and Option C are about how prices reflect information."}},{"itemId":"521072fd-d755-5007-9ce8-c7bd0ec158da","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"085e2493-90ff-53c3-a047-d88dc5e6f1e9","sourceKey":"bank:BUA216:EFF-010","parentItemId":null,"revision":1,"payload":{"prompt":"Competition among issuing houses and stockbrokers in Lagos has pushed their fees down to a level that just covers their costs and gives them a fair reward for their work. This development improves the market's","options":["allocational efficiency","operational efficiency","strong form efficiency","pricing efficiency"],"correctOption":1,"section":"Market Efficiency","explanation":"Operational efficiency means intermediaries channel funds at minimum cost while still earning fair compensation for services rendered, which is exactly what lower but fair fees achieve. Option A is about directing savings to productive investment, and Option D is about prices correctly reflecting information. The scenario is about the cost of the service, so operational efficiency fits best."}},{"itemId":"ec341471-8ce8-56b5-9314-d3b9ac0b3d92","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"05f27105-2dce-52d9-8ffe-ef56ade49984","sourceKey":"bank:BUA216:EFF-012","parentItemId":null,"revision":1,"payload":{"prompt":"Fama's weak, semi-strong and strong forms of efficiency are best seen as different degrees of which class of capital market efficiency?","options":["Allocational efficiency, since they ask how savings reach deficit units","Regulatory efficiency, since they ask how well the regulator enforces rules","Pricing efficiency, since they ask how much information share prices reflect","Operational efficiency, since they ask how cheaply brokers can trade"],"correctOption":2,"section":"Market Efficiency","explanation":"The three forms are defined by the information set that prices reflect: past prices, all public information, or all public and private information. That is a question about how efficiently prices process information, which is pricing efficiency. Option D and Option A describe operational and allocational efficiency, which are about the cost and direction of fund flows rather than information in prices."}},{"itemId":"1677f008-27c6-52ea-a574-eed4f56c64b7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"edbc812b-3895-55ec-a063-67ff479516c7","sourceKey":"bank:BUA216:EFF-013","parentItemId":null,"revision":1,"payload":{"prompt":"The capital market, whose efficiency is being studied, is best described as","options":["a market where only funds needed for one year or less are raised","a market where banks lend surplus cash to one another overnight","a market where governments borrow short-term through treasury bills alone","a market where long-term funds are raised, for example through shares"],"correctOption":3,"section":"Market Efficiency","explanation":"The capital market is where long-term funds are raised, and shares are a typical instrument traded there; in Nigeria its major regulator is the Securities and Exchange Commission. Option A describes the money market, which deals in funds needed for a year or less. Option C and Option B are also money market activities."}},{"itemId":"8450bd93-b67a-574c-ad6d-413a8e60681a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"22df542f-4aab-5e6d-8797-3ef43e518f31","sourceKey":"bank:BUA216:EFF-014","parentItemId":null,"revision":1,"payload":{"prompt":"The classification of market efficiency into weak, semi-strong and strong forms is associated with","options":["William Sharpe (1964)","Harry Markowitz (1952)","Eugene Fama (1970)","Modigliani and Miller (1958)"],"correctOption":2,"section":"Market Efficiency","explanation":"Eugene Fama in 1970 categorised market efficiency into the weak, semi-strong and strong forms. Option B is linked with portfolio theory and Option A with the capital asset pricing model. Option D is linked with capital structure theory, not market efficiency."}},{"itemId":"3de20e8d-9eb2-5707-8689-2fdf5fcad20a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4d9aa14a-2dff-512a-abba-b2165ec99f2a","sourceKey":"bank:BUA216:EFF-015","parentItemId":null,"revision":1,"payload":{"prompt":"Weak form efficiency is concerned with whether security prices reflect","options":["all publicly available information","only information released by the regulator","historical price or return information","all information, both public and private"],"correctOption":2,"section":"Market Efficiency","explanation":"Weak form efficiency deals with the adjustment of prices to historical price or return information, so past prices cannot be used to earn abnormal profit. Option A is the information set of the semi-strong form. Option D is the information set of the strong form."}},{"itemId":"987142de-b190-5f7c-a7b1-b181a6e60e44","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"edb18292-79ed-5f14-88c8-c9c24983521e","sourceKey":"bank:BUA216:EFF-016","parentItemId":null,"revision":1,"payload":{"prompt":"Semi-strong form efficiency is concerned with whether security prices reflect","options":["only information contained in audited financial statements","all information, including that held privately by insiders","all publicly available information","only past share prices and trading volumes"],"correctOption":2,"section":"Market Efficiency","explanation":"Semi-strong efficiency asks whether prices reflect all publicly available information, which includes past prices, published accounts, announcements and economic news. Option D is too narrow and describes the weak form. Option B goes beyond public information and describes the strong form, while Option A is only one part of public information."}},{"itemId":"9b8b4951-3913-59d8-9186-d2c0c4587455","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ace30a39-a82b-5769-930f-5f1a79df80c8","sourceKey":"bank:BUA216:EFF-017","parentItemId":null,"revision":1,"payload":{"prompt":"Strong form efficiency is concerned with whether security prices fully reflect","options":["only historical price and return information","only information that has been reported in the national press","only publicly available information","all information, whether available to the public or private"],"correctOption":3,"section":"Market Efficiency","explanation":"Strong form efficiency is the most demanding: prices reflect every piece of information, public or private, so no one can earn abnormal profit even with monopolistic access to information. Option A describes the weak form and Option C the semi-strong form. Option B is a subset of public information."}},{"itemId":"e1004e7d-cbf8-5641-9a65-0216464aa945","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9b1834f9-c2fc-5f62-85a3-53b055f18ec5","sourceKey":"bank:BUA216:EFF-018","parentItemId":null,"revision":1,"payload":{"prompt":"A trader at a Lagos brokerage studies past price charts and moving averages of quoted shares and claims this lets her earn abnormal returns. If the market is weak form efficient,","options":["her chart analysis will consistently earn abnormal returns","her chart analysis cannot consistently earn abnormal returns","only her use of published accounts can be ruled out","she can earn abnormal returns only on days of low trading"],"correctOption":1,"section":"Market Efficiency","explanation":"In a weak form efficient market prices already reflect all historical price and return information, so studying past charts (technical analysis) cannot consistently beat the market. Option A contradicts the weak form directly. Option C confuses weak form with semi-strong form, which is the form that defeats analysis of published accounts."}},{"itemId":"cde3334a-2f94-50f8-a90b-0d1c16ea7680","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d5d123da-0d4c-5e3d-b130-0426e6ec98d1","sourceKey":"bank:BUA216:EFF-019","parentItemId":null,"revision":1,"payload":{"prompt":"An investment analyst carefully studies the published annual reports, dividend announcements and economic forecasts of quoted companies to pick undervalued shares. If the market is semi-strong form efficient, this approach","options":["will work only if the analyst also uses past price charts","will not be a reliable way to earn superior returns","will reliably earn superior returns because accounts are public","will work, because semi-strong efficiency only rules out chart analysis"],"correctOption":1,"section":"Market Efficiency","explanation":"In a semi-strong efficient market all publicly available information is already incorporated in current prices, so fundamental analysis of published information cannot reliably earn superior returns. Option D is wrong because semi-strong efficiency defeats both technical and fundamental analysis. Option A is wrong because past prices are also public and already reflected."}},{"itemId":"b972fffe-6d44-5c3c-ab4c-747651c92a70","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70fb99d5-c6f1-521a-9376-47cc43b57519","sourceKey":"bank:BUA216:EFF-020","parentItemId":null,"revision":1,"payload":{"prompt":"A company director buys shares a week before the board's unannounced decision to accept a lucrative takeover offer becomes public, and earns a large abnormal profit. If the market were strong form efficient,","options":["he would still earn abnormal profit, since only public information is priced","only investors using past price charts would be prevented from earning such profit","the director's profit would be normal because takeovers do not affect prices","he could not earn abnormal profit, as prices would already reflect the private news"],"correctOption":3,"section":"Market Efficiency","explanation":"Under strong form efficiency prices reflect all information, public or private, so even someone with monopolistic access to information cannot earn abnormal profit. A director profiting from unannounced news therefore shows the market is not strong form efficient. Option A describes the semi-strong form, and Option B describes the weak form only."}},{"itemId":"63aa2231-9957-5b0e-bdbd-6b54fd6bd8ae","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d2199f8-44d2-57e5-a8e9-908bdfff90f1","sourceKey":"bank:BUA216:EFF-021","parentItemId":null,"revision":1,"payload":{"prompt":"A capital market is weak form efficient but not semi-strong form efficient. Which of the following could still earn an investor abnormal returns?","options":["Forecasting prices from historical return patterns","Analysis of newly published company accounts","Buying shares that rose on each of the last five days","Trading rules based on past price movements"],"correctOption":1,"section":"Market Efficiency","explanation":"If the market is weak form efficient, all historical price and return information is already in prices, so Option D, Option C and Option A, which all rely on past prices, cannot beat the market. Because the market is not semi-strong efficient, public information such as new accounts is not fully priced, so analysing it can still earn abnormal returns."}},{"itemId":"1ef5d15d-13a9-58de-a418-376e220ae464","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"38f57e4b-5d62-55db-aaa4-1b31314c10a9","sourceKey":"bank:BUA216:EFF-022","parentItemId":null,"revision":1,"payload":{"prompt":"If a capital market is semi-strong form efficient, which of the following statements is correct?","options":["Technical analysis fails, but fundamental analysis still produces superior returns","Both technical and fundamental analysis reliably produce superior returns","Fundamental analysis fails, but technical analysis still produces superior returns","Neither technical nor fundamental analysis will reliably produce superior returns"],"correctOption":3,"section":"Market Efficiency","explanation":"Semi-strong efficiency means all publicly available information, including past prices and published fundamentals, is already reflected in prices, so neither technical nor fundamental analysis is a reliable route to superior returns. Option A describes a market that is only weak form efficient. Option C gets the relationship backwards, because past prices are part of public information."}},{"itemId":"18b8e189-016d-5e40-9813-b5428a69219d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d09fc8da-225c-547f-8f16-bd6d63dab326","sourceKey":"bank:BUA216:EFF-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT true of a strong form efficient capital market?","options":["Technical analysis of past prices cannot earn abnormal profit","Fundamental analysis of published data cannot earn abnormal profit","Insiders with private information can earn abnormal profit","Prices reflect all information, both public and private"],"correctOption":2,"section":"Market Efficiency","explanation":"In a strong form efficient market no investor can earn abnormal profit from any information, even with monopolistic access to it, so the claim about insiders is false. Option D is the definition of the strong form. Option B and Option A are true because the strong form also includes the semi-strong and weak forms."}},{"itemId":"62b291de-d20d-54d7-9924-01ab9321a1b7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d11e711d-7082-5cdf-a554-2b02d971527b","sourceKey":"bank:BUA216:EFF-024","parentItemId":null,"revision":1,"payload":{"prompt":"If a capital market is semi-strong form efficient, then it must also be","options":["strong form efficient","inefficient in the weak form","operationally inefficient","weak form efficient"],"correctOption":3,"section":"Market Efficiency","explanation":"Historical prices are part of publicly available information, so a market whose prices reflect all public information must also reflect past prices; semi-strong efficiency therefore implies weak form efficiency. Option A does not follow, because private information may still not be reflected. Option B contradicts the nested nature of the forms."}},{"itemId":"35523d6e-0687-570c-97b2-77d96091e694","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fd804bc8-a09b-54b2-ad6f-635768f87f45","sourceKey":"bank:BUA216:EFF-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about the forms of market efficiency is correct?","options":["A semi-strong form efficient market is always strong form efficient","A weak form efficient market is not necessarily semi-strong form efficient","A weak form efficient market is always strong form efficient","A strong form efficient market need not be weak form efficient"],"correctOption":1,"section":"Market Efficiency","explanation":"The forms are nested: strong includes semi-strong, which includes weak, but not the other way round. A market can reflect past prices without reflecting all public information, so weak form does not guarantee semi-strong form. Option C and Option A reverse the direction of the nesting, and Option D is false because the strong form reflects all information, including past prices."}},{"itemId":"7d4b63be-0190-5d8f-b8d0-b59e944f7acf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d6ee7c1-c280-5ebe-a2a3-419506ef2dcb","sourceKey":"bank:BUA216:EFF-026","parentItemId":null,"revision":1,"payload":{"prompt":"Ranked from the smallest information set to the largest, the forms of market efficiency are","options":["strong form, semi-strong form, weak form","weak form, semi-strong form, strong form","weak form, strong form, semi-strong form","semi-strong form, weak form, strong form"],"correctOption":1,"section":"Market Efficiency","explanation":"The weak form covers only historical prices and returns, the semi-strong form covers all publicly available information, and the strong form covers all information, public and private. Each set contains the one before it, so the order is weak, semi-strong, strong. Option A lists them from largest to smallest, and Option D and Option C mix up the order."}},{"itemId":"dd12d10f-88b2-5525-9f74-c2562006f38d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"52043bf5-45bf-5140-b77d-49f2f6ef4121","sourceKey":"bank:BUA216:EFF-027","parentItemId":null,"revision":1,"payload":{"prompt":"XYZ Plc announces a 40% rise in profits at 10.00 a.m. Within minutes its share price jumps to a new level and then shows no further drift. This behaviour is most consistent with","options":["strong form inefficiency only","operational inefficiency","weak form inefficiency","semi-strong form efficiency"],"correctOption":3,"section":"Market Efficiency","explanation":"When prices adjust quickly and fully to a public announcement, with no later drift that investors could exploit, the market is behaving as semi-strong efficient. Option C would involve predictable patterns in past prices, which the scenario does not show. Option A is about whether insiders can profit from private information, which this announcement does not test."}},{"itemId":"f5dee40a-3323-5dc2-8781-dfdd4a3c9cdb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"16e0e7cc-ae36-5927-b22e-4ea7865e389f","sourceKey":"bank:BUA216:EFF-028","parentItemId":null,"revision":1,"payload":{"prompt":"After Delta Plc publicly announces a large special dividend, its share price rises only slowly over the next three weeks, and investors who buy on the announcement day consistently earn abnormal returns. This is evidence that the market is","options":["not weak form efficient","fully strong form efficient","not semi-strong form efficient","semi-strong form efficient"],"correctOption":2,"section":"Market Efficiency","explanation":"In a semi-strong efficient market the price would adjust quickly and fully once the dividend became public, leaving no abnormal return for late buyers. A slow drift that investors can exploit with public information shows the market is not semi-strong efficient. Option B and Option D would rule out this profit, and Option A is not what the evidence tests, because the profit comes from a public announcement, not from past prices."}},{"itemId":"e3437e2d-6a29-5fca-95e2-35f9887a34fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"572c6005-0a59-59d4-a5fc-b583b4db6512","sourceKey":"bank:BUA216:EFF-029","parentItemId":null,"revision":1,"payload":{"prompt":"A researcher finds that a trading rule, 'buy any share whose price has risen 5% above its recent low and sell when it falls 5% below its recent high', consistently beats the market on an exchange after costs. This finding suggests the exchange is","options":["semi-strong form efficient","not weak form efficient","strong form efficient","weak form efficient"],"correctOption":1,"section":"Market Efficiency","explanation":"The rule uses only past price information, so if it consistently earns abnormal returns after costs, prices do not fully reflect historical information and the market is not weak form efficient. Option D is contradicted directly by the finding. Option C and Option A are also ruled out, because both forms include weak form efficiency."}},{"itemId":"44189587-7873-54be-9a4c-1edee7539d06","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5a453420-47ab-5e7c-80ee-e23e93d4c3d5","sourceKey":"bank:BUA216:EFF-030","parentItemId":null,"revision":1,"payload":{"prompt":"The form of efficiency under which no investor can earn abnormal profit 'even if he has monopolistic access to such information' is the","options":["operational form","weak form","strong form","semi-strong form"],"correctOption":2,"section":"Market Efficiency","explanation":"Monopolistic access to information means information held privately by an insider. Only the strong form says prices reflect even private information, so such access gives no advantage. Option B concerns past prices only and Option D concerns public information only."}},{"itemId":"01d160f5-e464-59ed-982f-6536f8551404","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aa303f63-d3f1-55c7-be2e-f438809f34da","sourceKey":"bank:BUA216:EFF-031","parentItemId":null,"revision":1,"payload":{"prompt":"'Investors cannot use historical cost or past statistics to beat the market, except with insider information.' This statement describes","options":["semi-strong form efficiency","strong form efficiency","weak form efficiency","allocational efficiency"],"correctOption":2,"section":"Market Efficiency","explanation":"Using past statistics to beat the market is ruled out by weak form efficiency, which concerns historical price and return information; the exception for insider information shows the statement does not claim private information is priced. Option A would also rule out public information such as accounts, and Option B would rule out insider information too."}},{"itemId":"56095a17-3c0a-51be-864d-3005d3d68d1e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cd9999bc-a946-5c0f-9286-68a5a403f19c","sourceKey":"bank:BUA216:EFF-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches each form of market efficiency with the type of analysis it makes unprofitable?","options":["Weak form - technical analysis; semi-strong form - technical and fundamental analysis; strong form - also insider information","Weak form - technical analysis; semi-strong form - insider information only; strong form - fundamental analysis only","Weak form - insider information only; semi-strong form - fundamental analysis; strong form - technical analysis only","Weak form - fundamental analysis; semi-strong form - technical analysis; strong form - insider information only"],"correctOption":0,"section":"Market Efficiency","explanation":"Weak form efficiency defeats technical analysis based on past prices, semi-strong efficiency adds published information so fundamental analysis also fails, and strong form efficiency defeats even the use of private insider information. Option D swaps the weak and semi-strong forms. Option C and Option B wrongly attach insider information to the weaker forms."}},{"itemId":"92896093-390c-5f2e-bcca-282669df8353","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d0f445aa-4d83-509a-a358-c92e644ee249","sourceKey":"bank:BUA216:EFF-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following would NOT be included in the information set of the semi-strong form of efficiency?","options":["A board decision to cut the dividend, not yet announced","The company's published annual report and accounts","The share's closing prices over the last two years","A Central Bank announcement of a change in interest rates"],"correctOption":0,"section":"Market Efficiency","explanation":"The semi-strong form covers all publicly available information, so anything not yet released, such as an unannounced board decision, lies outside it and belongs only to the strong form. Option B and Option D are public announcements. Option C is historical price information, which is public and therefore also in the semi-strong set."}},{"itemId":"a1c609fb-2d57-5563-b758-4145b7cd00a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1d92b956-5065-58ac-8756-e0371fb30c05","sourceKey":"bank:BUA216:EFF-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is part of the information set of the weak form of efficiency?","options":["A newly announced merger between two quoted banks","The company's latest published profit figures","Confidential plans known only to the company's directors","Past daily closing prices and returns of the share"],"correctOption":3,"section":"Market Efficiency","explanation":"The weak form is concerned with historical price or return information, such as past closing prices. Option B and Option A are public information that belongs to the semi-strong set. Option C is private information that only the strong form covers."}},{"itemId":"b4f2942e-0858-5378-b526-fa7928cfa3f3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4eb54493-c22d-5ad4-b192-1c309804788e","sourceKey":"bank:BUA216:EFF-035","parentItemId":null,"revision":1,"payload":{"prompt":"The method of valuing shares by studying published accounts, earnings, dividends, management and economic conditions to find a share's intrinsic value is called","options":["insider dealing","technical analysis","random walk analysis","fundamental analysis"],"correctOption":3,"section":"Market Efficiency","explanation":"Fundamental analysis estimates a share's true value from published information about the company and the economy; semi-strong efficiency says it cannot reliably produce superior returns. Option B studies past price and volume patterns instead. Option A uses private information that is not available to the public."}},{"itemId":"b1444add-4ad5-5cab-8b05-ea0d966bbd85","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6f9664e-9107-53d7-8cec-47cf4af68757","sourceKey":"bank:BUA216:EFF-036","parentItemId":null,"revision":1,"payload":{"prompt":"The method of predicting share prices by studying charts of past prices and trading volumes is called","options":["fundamental analysis","technical analysis","ratio analysis","event study analysis"],"correctOption":1,"section":"Market Efficiency","explanation":"Technical (chart) analysis looks for patterns in past prices and volumes to forecast future prices, and weak form efficiency says this cannot consistently earn abnormal returns. Option A values shares from published company and economic information. Option D is a research method for testing how prices respond to announcements."}},{"itemId":"3a25e83d-06c3-5443-bdaa-00bbc711d513","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ef17bf2e-16d2-51bd-afc4-290e7fab6147","sourceKey":"bank:BUA216:EFF-039","parentItemId":null,"revision":1,"payload":{"prompt":"The random walk theory of share prices states that","options":["share prices follow repeating patterns that charts can identify","successive price changes are independent, so past changes cannot predict future ones","share prices always return to their long-run average level within a year","share prices rise steadily in line with the company's long-term growth rate"],"correctOption":1,"section":"Market Efficiency","explanation":"Under a random walk, each price change is independent of the ones before it, so knowing past changes does not help forecast the next one. Option C describes mean reversion, a predictable pattern. Option A is the belief behind chart analysis, which the random walk rejects."}},{"itemId":"40807996-c662-515a-b224-88ba96df9ec2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b60c5d06-9e25-5f06-82fd-fbef9daffac0","sourceKey":"bank:BUA216:EFF-040","parentItemId":null,"revision":1,"payload":{"prompt":"Evidence that share prices follow a random walk is most directly evidence in support of","options":["operational efficiency","strong form efficiency","allocational efficiency","weak form efficiency"],"correctOption":3,"section":"Market Efficiency","explanation":"If price changes are random and independent, past prices contain no exploitable pattern, which is exactly what weak form efficiency says. A random walk says nothing about whether private information is priced, so it cannot by itself confirm Option B. Option A and Option C are about intermediation costs and fund allocation rather than price behaviour."}},{"itemId":"38ece12b-e4ed-516e-a40e-dca1027211aa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b26c41f1-57dd-5189-8854-0f92f11971ac","sourceKey":"bank:BUA216:EFF-041","parentItemId":null,"revision":1,"payload":{"prompt":"Why are random price movements consistent with an efficient market?","options":["Prices change only on new information, which by nature is unpredictable","Regulators adjust prices at random intervals to prevent speculation","Efficient markets have no transaction costs, so prices move for no reason","Investors in efficient markets trade without looking at any information"],"correctOption":0,"section":"Market Efficiency","explanation":"In an efficient market prices already reflect what is known, so they move only on genuinely new information; because news cannot be predicted, the resulting price changes look random. Option D gets it backwards, since efficiency comes from investors acting quickly on information. Option B and Option C invent causes that have nothing to do with efficiency."}},{"itemId":"7403f6a6-94f8-5de7-8860-be1458f2c105","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4648ba7d-a568-5475-96b3-f962a3fca370","sourceKey":"bank:BUA216:EFF-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a test of weak form efficiency?","options":["Checking whether successive share price changes are correlated with each other","Comparing the returns of company directors trading their own shares with the market","Measuring how quickly prices react to profit announcements","Comparing the fees charged by stockbrokers with their costs"],"correctOption":0,"section":"Market Efficiency","explanation":"Weak form tests ask whether past prices predict future prices, for example through serial correlation tests, runs tests or filter rules; no significant correlation supports weak form efficiency. Option C is an event study, a test of the semi-strong form. Option B tests the strong form, and Option D concerns operational efficiency."}},{"itemId":"a48a992a-2d4e-52bd-a0f4-b3a202334466","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"339b1f33-9439-5e0b-8d8d-e9d448925411","sourceKey":"bank:BUA216:EFF-043","parentItemId":null,"revision":1,"payload":{"prompt":"An event study that measures abnormal returns around public announcements such as dividend or earnings releases is mainly a test of","options":["strong form efficiency","operational efficiency","semi-strong form efficiency","weak form efficiency"],"correctOption":2,"section":"Market Efficiency","explanation":"Event studies check whether prices adjust quickly and fully to public announcements, which is what semi-strong efficiency requires. Option D is tested with past price patterns, such as serial correlation. Option A is tested by checking whether insiders or others with private information earn abnormal returns."}},{"itemId":"c23e8ce3-8592-506e-b1a2-cc1fc58a6191","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"916fd504-2319-5128-9758-f8e5d65192ea","sourceKey":"bank:BUA216:EFF-044","parentItemId":null,"revision":1,"payload":{"prompt":"Researchers check whether company directors and other insiders earn abnormal returns when they trade in their own companies' shares. This is a test of","options":["allocational efficiency","semi-strong form efficiency","weak form efficiency","strong form efficiency"],"correctOption":3,"section":"Market Efficiency","explanation":"Insiders hold private information, so if they consistently earn abnormal returns, prices do not reflect private information and the market is not strong form efficient. Option C would be tested with past price patterns. Option B would be tested by price reactions to public announcements."}},{"itemId":"7936cd46-1d09-5567-80c2-fdd64d49710e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"df4c752b-e365-534b-9d55-7bbc00e121f5","sourceKey":"bank:BUA216:EFF-045","parentItemId":null,"revision":1,"payload":{"prompt":"In the study of market efficiency, an 'anomaly' is","options":["a share whose price is fixed by the market regulator","a return pattern that seems to contradict market efficiency","a sudden price change caused by new public information","a market in which all transaction costs are zero"],"correctOption":1,"section":"Market Efficiency","explanation":"An anomaly is a regular, apparently exploitable pattern in returns, such as a calendar or size effect, that should not exist if markets were efficient. Option C is the normal behaviour of an efficient market, which reacts quickly to new information. Option A and Option D have nothing to do with return patterns."}},{"itemId":"aa26aa85-0d34-54c8-b942-c89922a0f6b8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4777c4a2-793c-5407-89ba-3a73a819b262","sourceKey":"bank:BUA216:EFF-046","parentItemId":null,"revision":1,"payload":{"prompt":"Over many years, shares on an exchange have tended to earn unusually high returns in January compared with other months, and investors could have profited by buying in December. This is an example of","options":["a calendar anomaly, conflicting with weak form efficiency","an event study of a public announcement","evidence that the market is allocationally efficient","a test showing that the market is strong form efficient"],"correctOption":0,"section":"Market Efficiency","explanation":"A predictable seasonal pattern such as the January effect is a calendar anomaly; because it is visible from past returns, it conflicts with weak form efficiency. Option D is wrong because an exploitable pattern is evidence against efficiency. Option B is wrong because no specific public announcement is involved."}},{"itemId":"288876e1-9b25-56b1-b8b1-00b51c6bf5c8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2c0d5080-a15c-527c-b277-c7256d5197d4","sourceKey":"bank:BUA216:EFF-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of a market anomaly?","options":["Small companies earning higher risk-adjusted returns than large ones","Prices drifting for weeks in the direction of an earnings surprise","Unusually high returns in January compared with other months","Share prices moving randomly in response to unpredictable news"],"correctOption":3,"section":"Market Efficiency","explanation":"Random price moves in response to unpredictable news are exactly what an efficient market predicts, so they are not an anomaly. Option A is the size effect, Option C is the January effect and Option B is post-announcement drift, all patterns that appear to contradict efficiency."}},{"itemId":"a946d001-f600-529a-acc6-0ef3cba2f8ec","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bff37817-c5f9-58d5-aa85-a582cbd242db","sourceKey":"bank:BUA216:EFF-048","parentItemId":null,"revision":1,"payload":{"prompt":"If the Nigerian stock market were semi-strong form efficient, which strategy would make most sense for an ordinary investor?","options":["Trade frequently using chart patterns to beat the market","Pay an analyst to study published accounts to find underpriced shares","Hold a diversified portfolio and avoid paying for share-picking advice","Buy only shares whose prices rose sharply last month"],"correctOption":2,"section":"Market Efficiency","explanation":"When public information is already in prices, neither fundamental nor technical analysis reliably beats the market, so the sensible approach is to diversify, keep costs low and expect a fair return for risk. Option B relies on fundamental analysis and Option A on technical analysis, both defeated by semi-strong efficiency. Option D uses past prices, which even weak form efficiency rules out."}},{"itemId":"cc551478-9ffd-5987-9d39-9d6c426116e9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"00936881-f1f8-5273-969a-0508cb40a7df","sourceKey":"bank:BUA216:EFF-049","parentItemId":null,"revision":1,"payload":{"prompt":"The finance director of Kola Foods Plc changes the depreciation method so that reported profit rises by N50 million, although the company's cash flows are unchanged. In a semi-strong form efficient market, the share price would","options":["rise, because only insiders can see the unchanged cash flows","not rise in a lasting way, as investors see through the change","fall sharply and stay down, because the change is illegal","rise permanently in proportion to the higher reported profit"],"correctOption":1,"section":"Market Efficiency","explanation":"In a semi-strong efficient market all public information, including disclosures on accounting policies, is reflected in prices, so a cosmetic change that leaves cash flows unchanged does not create value. Option D assumes investors are fooled by reported figures. Option A is wrong because the change and its effect are disclosed publicly."}},{"itemId":"e4894840-3d24-556b-9297-d6e3d34652f4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"67d2f773-84b0-5421-ad21-4b1bf6a6d51f","sourceKey":"bank:BUA216:EFF-050","parentItemId":null,"revision":1,"payload":{"prompt":"For company managers, an important implication of an efficient capital market is that","options":["timing new share issues for 'high' prices offers little benefit","issuing shares only after a run of price rises secures better prices","smoothing reported profits raises the share price permanently","the share price ignores decisions until the next annual report"],"correctOption":0,"section":"Market Efficiency","explanation":"If prices fully reflect available information, the current share price is a fair estimate of value, so managers cannot reliably pick moments when it is too high. Option C assumes the market is fooled by accounting presentation. Option D contradicts the quick adjustment of prices to news, and Option B relies on past price trends that carry no predictive value."}},{"itemId":"5f7fc330-7684-5863-a03a-4bc04581a9ab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c0b9e07-19d4-5c02-ba80-ee400f89f663","sourceKey":"bank:BUA216:EFF-051","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common MISUNDERSTANDING of the efficient market hypothesis?","options":["In an efficient market, no investor can ever earn a positive return","In an efficient market, investors earn a fair return for the risk they bear","In an efficient market, prices adjust quickly to new information","In an efficient market, consistently beating the market is very difficult"],"correctOption":0,"section":"Market Efficiency","explanation":"Efficiency rules out consistent abnormal returns, not positive returns: investors still earn a normal return that compensates them for risk. Option B, Option C and Option D are correct statements of what efficiency implies, so the claim that no one can ever earn a positive return is the misunderstanding."}},{"itemId":"4ab9697c-e7e6-512d-8ac1-551f41d04ea8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c8e9269a-44a9-5117-be65-5a0f71189558","sourceKey":"bank:BUA216:EFF-052","parentItemId":null,"revision":1,"payload":{"prompt":"In a perfectly efficient capital market, a newly listed share at its market price is best described as","options":["fairly priced, with an expected return that just fits its risk","always overpriced, because the issuing promoters set the price","always underpriced, offering a guaranteed abnormal return","impossible to value, since its price moves at random"],"correctOption":0,"section":"Market Efficiency","explanation":"Efficient prices fully reflect available information, so a share is fairly priced and its expected return matches its risk, which is why buying it is a zero abnormal return investment. Option C and Option B assume systematic mispricing, which efficiency rules out. Option D confuses random price changes with random price levels; prices are still based on information."}},{"itemId":"a915a1e1-f001-581d-b3e2-0075f2d7b949","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7fe5625d-5a22-507e-b836-80521e87ef04","sourceKey":"bank:BUA216:EFF-053","parentItemId":null,"revision":1,"payload":{"prompt":"Ocean Bank Plc shares earned an actual return of 18% in a month when their expected (normal) return was 12%. Taking abnormal return = actual return - expected return, the abnormal return is","options":["6%","1.5%","30%","-6%"],"correctOption":0,"section":"Market Efficiency","explanation":"Abnormal return = actual return - expected return = 18% - 12% = 6%. Option D reverses the subtraction (expected minus actual), while Option C wrongly adds the two returns. A positive abnormal return means the share did better than its normal return."}},{"itemId":"96a123a8-5b50-511b-9989-2490e08ea60c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15797e3d-e73b-5c50-8961-d59268b9e5b1","sourceKey":"bank:BUA216:EFF-054","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 10%, the expected market return is 16% and Bisi Plc has a beta of 1.2. Using CAPM, expected return = Rf + beta x (Rm - Rf). If Bisi Plc's actual return for the year was 21%, its abnormal return is","options":["11.0%","3.8%","5.0%","-3.8%"],"correctOption":1,"section":"Market Efficiency","explanation":"Expected return = 10% + 1.2 x (16% - 10%) = 10% + 7.2% = 17.2%, so abnormal return = 21% - 17.2% = 3.8%. Option C compares the actual return with the market return and ignores beta. Option A compares it with the risk-free rate only, and Option D subtracts in the wrong order."}},{"itemId":"379acfa6-2881-587e-8fab-39a8a2e41160","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a8ea8a56-3ac7-5db3-aa91-d4f730a9c2a1","sourceKey":"bank:BUA216:EFF-055","parentItemId":null,"revision":1,"payload":{"prompt":"Taking abnormal return = actual return - expected return, the daily returns of Zenith Agro Plc around a merger announcement were: Day 1 actual 1.9%, expected 0.7%; Day 2 actual 1.1%, expected 0.3%; Day 3 actual 0.2%, expected 0.7%. The cumulative abnormal return over the three days is","options":["2.0%","2.5%","3.2%","1.5%"],"correctOption":3,"section":"Market Efficiency","explanation":"Abnormal returns are 1.9 - 0.7 = 1.2%, 1.1 - 0.3 = 0.8% and 0.2 - 0.7 = -0.5%, so the cumulative abnormal return is 1.2 + 0.8 - 0.5 = 1.5%. Option A ignores the negative third day (1.2 + 0.8). Option C adds the actual returns only, and Option B adds the absolute values, treating the -0.5% as positive."}},{"itemId":"57b6f3bf-7d2e-55c6-b178-c4d8a882494e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1849e3ed-8e90-589e-bb76-92b1f5a9165d","sourceKey":"bank:BUA216:EFF-056","parentItemId":null,"revision":1,"payload":{"prompt":"An investor bought shares of Lekki Foods Plc at N50, received a dividend of N2 during the year and sold the shares at N56 at the end of the year. The expected return on the share for the year was 11%. Taking actual return = (closing price - opening price + dividend) / opening price, the abnormal return is","options":["1%","16%","5%","3.29%"],"correctOption":2,"section":"Market Efficiency","explanation":"Actual return = (56 - 50 + 2) / 50 = 8 / 50 = 16%, so abnormal return = 16% - 11% = 5%. Option A leaves out the N2 dividend (12% - 11%). Option D divides by the closing price instead of the opening price (14.29% - 11%), and Option B is the actual return without deducting the expected return."}},{"itemId":"6bb6644e-8c29-5335-9516-0cca96726414","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"efa16842-94ca-5c06-b3f8-298c24851c1c","sourceKey":"bank:BUA216:EFF-057","parentItemId":null,"revision":1,"payload":{"prompt":"Using the market-adjusted model, in which a share's expected return equals the market return, a share earned 7% during a week in which the All-Share Index rose by 4%. The abnormal return for the week is","options":["11%","1.75%","3%","-3%"],"correctOption":2,"section":"Market Efficiency","explanation":"Under the market-adjusted model, expected return = market return = 4%, so abnormal return = 7% - 4% = 3%. Option D subtracts the share's return from the market return. Option A adds the two returns, and Option B divides 7 by 4, which is not how an abnormal return is measured."}},{"itemId":"57e072a2-a2d4-53f3-b27d-b423af1d3a79","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bd28e8b3-4578-5def-aeb4-c4777d670c44","sourceKey":"bank:BUA216:EFF-058","parentItemId":null,"revision":1,"payload":{"prompt":"A fund manager invested N2,000,000 in a portfolio that earned 15% in a year when its expected return, given its risk, was 11%. Taking abnormal return = actual return - expected return, the abnormal profit in naira is","options":["N80,000","N800,000","N300,000","N220,000"],"correctOption":0,"section":"Market Efficiency","explanation":"Abnormal return = 15% - 11% = 4%, so abnormal profit = 4% x N2,000,000 = N80,000. Option C is the total profit at 15%, which includes the normal return the manager was expected to earn. Option D is just the expected profit at 11%, and Option B treats the 4% as 40%."}},{"itemId":"742799f3-f1fc-5af4-b844-00cc3f19ab05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"62cf0557-7aa0-5e3a-976d-22dd2d539f68","sourceKey":"bank:BUA216:EFF-059","parentItemId":null,"revision":1,"payload":{"prompt":"Using the market model, expected return = alpha + beta x market return. For Ade Plc, alpha = 1% and beta = 1.5. In a month when the market return was 8%, Ade Plc's actual return was 10%. The abnormal return is","options":["2.0%","-2.0%","-3.0%","3.0%"],"correctOption":2,"section":"Market Efficiency","explanation":"Expected return = 1% + 1.5 x 8% = 13%, so abnormal return = 10% - 13% = -3%; the share underperformed what the market model predicted. Option A compares the actual return with the market return and ignores alpha and beta. Option D subtracts in the wrong order, and Option B reverses the market-return shortcut (8% - 10%)."}},{"itemId":"b54b8ec3-08c7-5af2-8e7f-103176322028","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"78778ac1-75ed-5b71-94e5-9c201da8bddd","sourceKey":"bank:BUA216:EFF-060","parentItemId":null,"revision":1,"payload":{"prompt":"On the day Femi Telecom Plc announced a new licence, its share price rose from N100 to N108 (no dividend). The market as a whole rose by 2% that day and the share's beta is 1.0, so its expected return equals the market return. The abnormal return on the announcement day is","options":["6%","8%","10%","-6%"],"correctOption":0,"section":"Market Efficiency","explanation":"Actual return = (108 - 100) / 100 = 8% and expected return = 1.0 x 2% = 2%, so abnormal return = 8% - 2% = 6%. Option B is the raw return, which forgets to remove the part caused by the general market rise. Option C adds the market return instead of subtracting it, and Option D reverses the order."}},{"itemId":"9ffb554e-a5c1-57f5-9622-f6b6d86cb059","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f376feac-ad04-53ab-a0c5-7df24bcc938c","sourceKey":"bank:BUA216:EFF-061","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-free rate is 8%, the expected market return is 13% and Chuks Plc has a beta of 0.8. Using CAPM, expected return = Rf + beta x (Rm - Rf). If Chuks Plc earned an actual return of 9%, its abnormal return is","options":["1.0%","-3.0%","3.0%","-4.0%"],"correctOption":1,"section":"Market Efficiency","explanation":"Expected return = 8% + 0.8 x (13% - 8%) = 8% + 4% = 12%, so abnormal return = 9% - 12% = -3%. Option D compares the actual return with the market return (9% - 13%) and ignores beta. Option A compares it with the risk-free rate only, and Option C reverses the subtraction."}},{"itemId":"8b66c7ce-117b-5c7a-a0ef-329ab5565dfe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c059d7d3-f99c-5a26-8167-41378b6dc25b","sourceKey":"bank:BUA216:EFF-062","parentItemId":null,"revision":1,"payload":{"prompt":"Ibadan Steel Plc's shares trade at N40. At noon the company publicly announces a contract that analysts agree adds exactly N4 of value per share, and nothing else changes. If the market is semi-strong form efficient, the share price immediately after the announcement should be about","options":["N48","N41","N44","N40"],"correctOption":2,"section":"Market Efficiency","explanation":"In a semi-strong efficient market new public information is reflected quickly and fully, so the price should move at once to N40 + N4 = N44. Option D assumes no reaction at all and Option B assumes only part of the news is priced at first, which would let alert investors earn abnormal profit. Option A is an overreaction, which efficiency also rules out."}},{"itemId":"868b89fc-a333-5b39-84f4-160710b7437b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e40091b1-cf45-5f71-98c1-fb3be7fe0715","sourceKey":"bank:BUA216:F101-001","parentItemId":null,"revision":1,"payload":{"prompt":"The arithmetic process of determining the final value of a payment or a series of payments when interest is known is called ------","options":["Time value of money","Compounding","Simple interest","Banker's interest"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Compounding is the process of moving a present amount forward in time by adding interest on both the principal and the interest already earned, which gives its final (future) value. Time value of money (A) is the broad idea that money today is worth more than money later, not the arithmetic process itself. Simple interest (C) and banker's interest (D) are particular ways of charging interest, not the name of the process."}},{"itemId":"dedbf0d8-71e6-5ffe-a43f-45c6f945e018","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b9aa7041-135f-5c07-8265-4a035cd08294","sourceKey":"bank:BUA216:F101-002","parentItemId":null,"revision":1,"payload":{"prompt":"How much will an investor have after 5 years if he invests N20,000 at 10% simple interest per annum?","options":["N25,000","N30,000","N100,000","N200,000"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Simple interest is P x R x T = 20,000 x 0.10 x 5 = N10,000, so the investor will have 20,000 + 10,000 = N30,000. Option A adds only 2.5 years of interest. Options C and D come from multiplying the principal by 5 or by 10 instead of applying the rate."}},{"itemId":"0f5545b2-bcb7-52bd-9239-7d89771efde3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3151bb58-be95-512e-ab6f-881e455ab02a","sourceKey":"bank:BUA216:F101-003","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT a major source of short-term finance.","options":["Factoring","Bill finance","Leasing","Trade credit"],"correctOption":2,"section":"Working Capital Management","explanation":"Leasing is a medium- to long-term source of finance, because it lets a firm use an asset such as a vehicle or machine over several years without buying it. Factoring (A), bill finance (B) and trade credit (D) all provide funds for a few months at most, so they are short-term sources."}},{"itemId":"6a492808-73dc-59f5-88ea-7e39f1a3f550","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3b7f598c-247a-59b8-9c51-855e68885c32","sourceKey":"bank:BUA216:F101-004","parentItemId":null,"revision":1,"payload":{"prompt":"At what annual rate of compound interest will N2,000 grow to N2,721 after 4 years?","options":["5%","6%","9%","8%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Solve 2,000(1 + r)^4 = 2,721: (1 + r)^4 = 1.3605, so 1 + r = 1.3605^(1/4) = 1.08, giving r = 8%. Check: 2,000 x 1.08^4 = N2,720.98. At 6% (B) the amount would be only about N2,525, and at 9% (C) about N2,823."}},{"itemId":"440f709b-7e30-5899-aa7c-1ccc6f6b03cf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"887d0209-e21a-503b-98e0-6664d2d50363","sourceKey":"bank:BUA216:F101-005","parentItemId":null,"revision":1,"payload":{"prompt":"What amount should be invested now at 20% simple interest per annum to accumulate N184,000 in 3 years?","options":["N52,500","N306.66","N115,000","N305.50"],"correctOption":2,"section":"Mathematics of Finance","explanation":"With simple interest, A = P(1 + RT), so 184,000 = P(1 + 0.20 x 3) = 1.6P, giving P = 184,000 / 1.6 = N115,000. Check: interest is 115,000 x 0.2 x 3 = N69,000, and 115,000 + 69,000 = N184,000. Options A, B and D do not satisfy this equation."}},{"itemId":"8ee16c63-56bd-598d-bc24-f14f5709c6af","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9a5aef6f-5d03-52c1-bd50-330ba1c1a40a","sourceKey":"bank:BUA216:F101-006","parentItemId":null,"revision":1,"payload":{"prompt":"The raising of capital funds and using them to generate returns, and paying returns to the suppliers of funds, are known as ------ functions of the firm.","options":["Marketing","Accounting","Finance","Production"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"The finance function covers obtaining funds, investing them to earn returns, and rewarding those who supplied the funds through interest and dividends. Marketing (A) deals with selling the firm's products, accounting (B) with recording and reporting transactions, and production (D) with turning inputs into goods."}},{"itemId":"f1f5cb1c-a551-55f0-9fb5-1645070239fa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"348ec030-db8b-5fb7-b61a-4fd8a803c548","sourceKey":"bank:BUA216:F101-007","parentItemId":null,"revision":1,"payload":{"prompt":"Princess received an endowment of N5.0 million and decided to deposit it in a bank that pays an interest rate of 15% compounded quarterly. In how many years will she be able to accumulate N6.0 million to enable her to implement her desired project?","options":["4.95 yrs","1.24 yrs","1.20 yrs","1.08 yrs"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The quarterly rate is 15%/4 = 3.75%, so 5(1.0375)^(4n) = 6, giving 4n = log 1.2 / log 1.0375 = 4.95 quarters and n = 4.95 / 4 = 1.24 years. Option A is the number of quarters, not years. Options C and D are too short; after 1.20 years the deposit would be below N6 million."}},{"itemId":"1883a3cf-1410-504c-b288-d03346084af0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b4d51547-5905-5705-8e11-cc100510e4f3","sourceKey":"bank:BUA216:F101-008","parentItemId":null,"revision":1,"payload":{"prompt":"Kenny is entitled to a cash payment of N10 million in 5 years. If the opportunity interest rate is 10% payable semi-annually, what is the minimum amount he would be comfortable with if he is to receive the entitlement today?","options":["N6.21m","N6.86m","N6.14m","N3.86m"],"correctOption":2,"section":"Mathematics of Finance","explanation":"With semi-annual compounding there are 10 periods at 5% each, so PV = 10m / 1.05^10 = 10m / 1.6289 = N6.14m. Option A (N6.21m) uses annual compounding at 10%, which ignores the twice-yearly interest. Option D (N3.86m) is the interest portion, 10m - 6.14m, not the present value."}},{"itemId":"c0ffc68e-fc55-5fb5-a652-13a8b3dec5c3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fe7c06f4-ec1f-5e5c-9491-e5eb32119249","sourceKey":"bank:BUA216:F101-009","parentItemId":null,"revision":1,"payload":{"prompt":"Precious plans to retire in two years, after which she will be entitled to an annual payment of N100,000 for the next 10 years, the first payment coming one year after she retires. If her normal interest rate is 10%, what is the equivalent value today of the payments?","options":["N614,456","N507,815","N492,185","N641,456"],"correctOption":1,"section":"Mathematics of Finance","explanation":"This is a deferred annuity. At retirement (year 2) the 10 payments are worth 100,000 x [1 - 1.1^-10] / 0.1 = N614,457; discounting that back 2 years gives 614,457 / 1.21 = N507,815. Option A stops at the value on the retirement date and forgets to discount the last two years. Options C and D do not match the calculation."}},{"itemId":"104491b4-14c4-521e-a095-0ad644f7f007","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cfa02b61-fb2a-58a5-abe9-0295662477f9","sourceKey":"bank:BUA216:F101-010","parentItemId":null,"revision":1,"payload":{"prompt":"Unilag Ventures borrowed N100,000 at an interest rate of 10% per annum with a maturity of 3 years, amortized annually in equal instalments. How much is the principal outstanding at the end of the second year?","options":["N33,232.63","N40,211.48","N63,444.89","N36,555.89"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The equal instalment is 100,000 x 0.1 / (1 - 1.1^-3) = N40,211.48. After year 1 the balance is 110,000 - 40,211.48 = N69,788.52; after year 2 it is 69,788.52 x 1.1 - 40,211.48 = N36,555.89, which the final instalment exactly clears. Option B is the instalment itself, not the balance."}},{"itemId":"246bc649-ab36-557f-8f9e-05b281038b05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a8010579-1ec6-51db-ad80-11808ed1c8be","sourceKey":"bank:BUA216:F101-011","parentItemId":null,"revision":1,"payload":{"prompt":"The Department of Finance desires to accumulate N100,000 in 3 years by making equal deposits at the end of each year into a special fund, which it plans to use to acquire a set of learning aids. How much would be in the fund at the end of 2 years if the interest rate is 10% per annum?","options":["N63,444.11","N36,555.89","N30,211.48","N69,788.52"],"correctOption":0,"section":"Mathematics of Finance","explanation":"The yearly deposit is 100,000 x 0.1 / (1.1^3 - 1) = N30,211.48. By the end of year 2 the first deposit has grown to 30,211.48 x 1.1 and the second has just been made, so the fund holds 30,211.48 x 2.1 = N63,444.11. Option C is a single deposit, and option B is what is still missing from the N100,000 target."}},{"itemId":"6dc06813-6719-5a9c-aaa8-c1642a55aeb9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"95b517a8-89b9-51d5-bbcf-ee7758e8798a","sourceKey":"bank:BUA216:F101-012","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take for an amount to quadruple itself if the interest rate is 12% compounded annually?","options":["13.5 yrs","11.2 yrs","12.23 yrs","None of the above"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Quadrupling means (1.12)^n = 4, so n = log 4 / log 1.12 = 0.6021 / 0.0492 = 12.23 years. Option B (11.2) is too short; 1.12^11.2 is only about 3.56. Since C matches the calculation exactly, D is wrong."}},{"itemId":"3a052435-8718-5f1d-bb9d-b203cca09c9d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aa8aedd1-b32c-51b4-b5e2-7d5d09444b1b","sourceKey":"bank:BUA216:F101-013","parentItemId":null,"revision":1,"payload":{"prompt":"At what interest rate, compounded annually, will an investment of N150,000 yield N500,000 in 5 years?","options":["26.30%","27.10%","28.0%","27.23%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Solve 150,000(1 + r)^5 = 500,000: (1 + r)^5 = 3.3333, so 1 + r = 3.3333^(1/5) = 1.2723 and r = 27.23%. The nearby options are close distractors: at 27.10% (B) the investment would reach only about N497,500, and at 28% (C) it would overshoot to about N515,400."}},{"itemId":"6e853845-e087-5f7c-963e-5421ea0fba6f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ac9d35e9-0717-567d-b510-8a2433fa5e23","sourceKey":"bank:BUA216:F101-014","parentItemId":null,"revision":1,"payload":{"prompt":"Chike will invest an annual sum of N200,000 at the end of each year for 5 years. If the interest rate is 20% per annum, find how much will be realized at the end of the period.","options":["N1,888,320","N1,488,320","N1,428,320","N1,488,120"],"correctOption":1,"section":"Mathematics of Finance","explanation":"This is the future value of an ordinary annuity: 200,000 x [(1.2^5 - 1) / 0.2] = 200,000 x 7.4416 = N1,488,320. Option D differs only in the hundreds, and options A and C do not match the annuity factor of 7.4416. Option B is also the right figure before the extra year of interest that an annuity due would add."}},{"itemId":"66a15746-9b60-5801-9fa2-cb3adc07405c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d3a52c50-e6d8-5d1d-aa9f-7df3080e6bea","sourceKey":"bank:BUA216:F101-015","parentItemId":null,"revision":1,"payload":{"prompt":"If Chibuzor will invest an annuity of N200,000 for 5 years at an interest rate of 20% per annum, find how much he will realize at the end of the period, assuming the first instalment is made now.","options":["N1,785,984","N1,783,984","N1,782,984","N1,781,984"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Paying at the start of each year makes this an annuity due, so each payment earns one extra year of interest: 1,488,320 x 1.2 = N1,785,984. The other options differ from this by a few thousand naira and do not match the calculation."}},{"itemId":"f4e5d668-1b58-508c-8e49-28b04d475301","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2911b7d5-862d-5ea4-8699-b27baa98f0c2","sourceKey":"bank:BUA216:F101-016","parentItemId":null,"revision":1,"payload":{"prompt":"From the following figures: Stock N5,000; Trade creditors N2,000; Debtors N3,000; Bank overdraft N1,600; Bank N1,500; Accrued expenses N400; Cash N500. Calculate the current ratio.","options":["1:1","2:1","2.5:1","1.5:1"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Current assets are stock + debtors + bank + cash = 5,000 + 3,000 + 1,500 + 500 = N10,000. Current liabilities are trade creditors + bank overdraft + accrued expenses = 2,000 + 1,600 + 400 = N4,000. The current ratio is 10,000 : 4,000 = 2.5:1. Option B (2:1) is the usual rule-of-thumb ideal, not this firm's figure."}},{"itemId":"f7dec059-ad95-5ac2-a014-50abce70552b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"64b3df9f-1fcf-5aaf-b6ac-77763f6e7f05","sourceKey":"bank:BUA216:F101-017","parentItemId":null,"revision":1,"payload":{"prompt":"From the following figures: Stock N5,000; Trade creditors N2,000; Debtors N3,000; Bank overdraft N1,600; Bank N1,500; Accrued expenses N400; Cash N500. Calculate the quick (acid-test) ratio.","options":["0.75:1","1:1","1.5:1","1.25:1"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"The quick ratio leaves out stock because it is the least liquid current asset: (10,000 - 5,000) / 4,000 = 5,000 / 4,000 = 1.25:1. Option B (1:1) is the usual ideal benchmark, not this firm's ratio. Option A (0.75:1) and option C (1.5:1) do not match liquid assets divided by current liabilities."}},{"itemId":"fcdca09d-0300-5525-8791-f307d656332d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cc4b3c06-a257-5c07-99cb-5da35855c286","sourceKey":"bank:BUA216:F101-018","parentItemId":null,"revision":1,"payload":{"prompt":"Given that Inventories are N3,100; Accounts receivable N8,000; Accounts payable N4,000; Cash and cash equivalents N6,260; and Taxation N2,250, calculate the current ratio.","options":["1.78:1","2.78:1","3.78:1","4.78:1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Current assets are 3,100 + 8,000 + 6,260 = N17,360. Current liabilities, accounts payable plus taxation, are 4,000 + 2,250 = N6,250. The current ratio is 17,360 / 6,250 = 2.78:1. Taxation must be included in current liabilities because tax payable is due within the year; leaving it out would give 17,360 / 4,000 = 4.34, which is not an option."}},{"itemId":"cd7d32a3-e25a-5efe-b2a8-96b566327b78","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8372e624-18bf-5bb5-a3b3-fd07b1385baa","sourceKey":"bank:BUA216:F101-019","parentItemId":null,"revision":1,"payload":{"prompt":"Given that Inventories are N3,100; Accounts receivable N8,000; Accounts payable N4,000; Cash and cash equivalents N6,260; and Taxation N2,250, calculate the quick ratio.","options":["1.28:1","2.28:1","3.28:1","4.28:1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The quick ratio excludes inventories: (17,360 - 3,100) / 6,250 = 14,260 / 6,250 = 2.28:1. Option A (1.28) is one whole unit too low, and options C and D are too high. Only B matches liquid assets divided by current liabilities."}},{"itemId":"df62faa8-2d12-56ae-ae91-94d140d2977e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70add23d-9758-583d-b6d6-400f6a8ef250","sourceKey":"bank:BUA216:F101-020","parentItemId":null,"revision":1,"payload":{"prompt":"Short-term solvency ratio is also known as ------","options":["Stock market ratio","Efficiency ratio","Liquidity ratio","Stability ratio"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Short-term solvency ratios, such as the current ratio and quick ratio, measure a firm's ability to meet obligations falling due within a year, which is what liquidity means. Stability ratio (D) is the other name for long-term solvency ratios. Efficiency ratios (B) measure how well assets are used, and stock market ratios (A) relate to share prices."}},{"itemId":"31a1094c-1a59-5046-8640-ec942d7018fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9bee3a92-04fb-5aa9-b593-7804d5c1b81d","sourceKey":"bank:BUA216:F101-021","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the apex regulatory agency in the Nigerian capital market.","options":["NDIC","SEC","NICOM","CBN"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The Securities and Exchange Commission (SEC) is the apex regulator of the Nigerian capital market, overseeing securities issues, the exchanges and market operators. The CBN (D) is the apex regulator of the money market and banking system. NDIC (A) insures bank deposits, and NICOM (C) is not the capital market regulator."}},{"itemId":"806ac28e-287b-5259-8dc2-2a87cce20486","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fcbb54ee-4e1f-5be4-b579-3122e61910f8","sourceKey":"bank:BUA216:F101-022","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.5), N60,000 (0.3) and N70,000 (0.2). To the nearest whole percent, the coefficient of variation of the security is","options":["20%","13%","14%","16%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Expected return = 0.5(50,000) + 0.3(60,000) + 0.2(70,000) = N57,000. Variance = 0.5(7,000)^2 + 0.3(3,000)^2 + 0.2(13,000)^2 = 61,000,000, so the standard deviation is N7,810.25. CV = 7,810.25 / 57,000 = 13.7%, which rounds to 14%. Option B (13%) truncates instead of rounding."}},{"itemId":"e5892043-8884-57d2-a0b6-04d89449da73","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"99742753-b7c0-56bf-8ed0-1188b4352915","sourceKey":"bank:BUA216:F101-023","parentItemId":null,"revision":1,"payload":{"prompt":"One of the characteristics of finance is that ------","options":["It hinders business growth","It serves as a standard upon which business can be measured","It distorts the expansion of business","It does not link the other activities of a business together"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Finance provides a common money measure for every part of a business, so performance, costs and growth can all be judged in financial terms. Options A and C describe the opposite of what finance does, since funds make growth and expansion possible. Option D is also false, because finance links production, marketing and other activities through budgets and funds."}},{"itemId":"cf6e395d-6ade-59e9-aa08-235db34da312","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"21b3eacf-454f-56d7-a9d1-496b3723f9b0","sourceKey":"bank:BUA216:F101-024","parentItemId":null,"revision":1,"payload":{"prompt":"------ objective enhances a good business environment.","options":["Survival","Social responsibility","Profit maximization","Increase in market share"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The social responsibility objective commits the firm to caring for its community, employees, customers and the environment, which builds goodwill and a healthier environment for business. Survival (A) is about staying in operation, profit maximization (C) focuses on the firm's own earnings, and increase in market share (D) is about beating competitors."}},{"itemId":"ba4834f2-175a-5f4b-a9a1-1ff0d7575e19","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"284e8b5a-77fc-5fa1-806d-39b953543c84","sourceKey":"bank:BUA216:F101-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which firm objective has been attacked by all and sundry?","options":["Increase in market share","Survival","Social responsibility","Profit maximization"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Profit maximization is the most widely criticised objective. It ignores the timing of returns and risk, the term 'profit' is vague, and pursuing it can lead firms to neglect workers, customers and society. Survival (B) and social responsibility (C) are generally seen as reasonable goals, and market share (A) has not drawn the same broad criticism."}},{"itemId":"e1ab9def-0b71-54ac-bf44-788ebbae29a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"054d8c4f-7c46-505e-899b-3dfb94540927","sourceKey":"bank:BUA216:F101-026","parentItemId":null,"revision":1,"payload":{"prompt":"------ objective has been widely accepted as the best means of maximizing the economic welfare of the shareholders of a firm.","options":["Increase in market share","Survival","Social responsibility","Shareholders' wealth maximization"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Shareholders' wealth maximization aims to raise the market value of the owners' shares, taking account of the timing and risk of returns, so it is accepted as the best measure of shareholders' economic welfare. Market share (A), survival (B) and social responsibility (C) may support the firm, but none of them directly measures what owners gain."}},{"itemId":"81706e3e-bde5-55e0-88d0-e089ab4979b4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"83543fc9-3f69-5136-b8e1-f7b1cfc4fef9","sourceKey":"bank:BUA216:F101-027","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of the firm that has to do with giving all stakeholders satisfactory returns for their inputs is ------","options":["Increase in market share","Satisfaction","Survival","Social responsibility"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The satisfaction (satisficing) objective means the firm aims for results that are good enough to satisfy every stakeholder group: owners, workers, lenders and suppliers. It does not maximize for one group. Social responsibility (D) focuses on society and the environment rather than rewarding each contributor's input, and survival (C) is only about staying in business."}},{"itemId":"42a6d34f-6cf8-52ea-aac7-011fad652818","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e35d1523-1879-5cb9-8cbb-b51c76955385","sourceKey":"bank:BUA216:F101-028","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of capturing more of the market demand for their product in an industry is known as ------","options":["Shareholders' wealth maximization","Increase in market share","Survival","Social responsibility"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Market share is the portion of total industry demand that a firm captures, so aiming to capture more of it is the increase-in-market-share objective. Shareholders' wealth maximization (A) concerns share value, survival (C) is about continuing to exist, and social responsibility (D) concerns society."}},{"itemId":"db21545d-a5e0-552c-b525-6446ff3db4ab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d6c16d9-3e46-52ce-8616-5c3d3dfad070","sourceKey":"bank:BUA216:F101-029","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take N35,000 deposited into an account to accumulate to N450,000 at a 25% annual compound interest rate?","options":["11 years","12 years","13 years","10 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Solve 35,000(1.25)^n = 450,000: 1.25^n = 12.857, so n = log 12.857 / log 1.25 = 1.1091 / 0.0969 = 11.45 years, which is 11 years to the nearest year. Option B (12) would be the first whole year in which the target is passed, but the question asks for the nearest year. Option D (10) is too short."}},{"itemId":"52fd1d75-d56e-5405-b11d-726346075891","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1ac0a033-342e-50c6-814b-de2a63a8b658","sourceKey":"bank:BUA216:F101-030","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N300,000 received in 5 years' time if such funds yield 15% per annum?","options":["N149,000","N603.41","N149,153.02","N603,407.17"],"correctOption":2,"section":"Mathematics of Finance","explanation":"PV = 300,000 / 1.15^5 = 300,000 / 2.011357 = N149,153.02. Option A is a rounded figure that does not match the discount factor. Option D (N603,407.17) is the future value, 300,000 x 1.15^5, rather than the present value."}},{"itemId":"2db01c11-b562-5a19-88b0-87877c88fecc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"77a81a3e-af34-535d-86d7-5fc188905ce2","sourceKey":"bank:BUA216:F101-031","parentItemId":null,"revision":1,"payload":{"prompt":"Assuming N100,000 is put in a fixed deposit account with a bank that offers the depositor 24% interest per annum payable twice in a quarter (eight times a year), calculate the compounded value of the investment if it is made for 4 years.","options":["N160,470.64","N160,470.46","N160,469","N257,508.28"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Twice a quarter means 8 compounding periods a year, so each period earns 24%/8 = 3% and there are 4 x 8 = 32 periods. The value is 100,000 x 1.03^32 = N257,508.28. Options A, B and C, about N160,470, come from 1.03^16, which counts only 16 periods (two years)."}},{"itemId":"63eb288e-b8b3-5ded-a7a5-63ebfc6c3535","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"512dbeba-f1c0-5152-b9cb-99396567105e","sourceKey":"bank:BUA216:F101-032","parentItemId":null,"revision":1,"payload":{"prompt":"FLAKKY has just secured a job with CHEVROME Oil Plc on a 3-year contract with a monthly salary of N800,000, paid at the end of each month, and an annual bonus of N2.5 million, paid at the end of each year. What is the present value of FLAKKY's job contract if the discount rate is 15% per annum (1.25% per month for the salary)?","options":["N23,077,813.90","N5,708,062.79","N28,785,876.69","None of the above"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Salary PV = 800,000 x [1 - 1.0125^-36] / 0.0125 = N23,077,813.90, and bonus PV = 2,500,000 x [1 - 1.15^-3] / 0.15 = N5,708,062.79. The contract is worth the sum, N28,785,876.69. Options A and B are each only one part of the contract."}},{"itemId":"daf9bab3-dc7e-5da3-9a2e-eba1caebb6b8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8516605f-04b6-5034-9e48-94999c929f4c","sourceKey":"bank:BUA216:F101-033","parentItemId":null,"revision":1,"payload":{"prompt":"Blessing has just been promised a lump sum payment of N2,000,000 in the future if she agrees to deposit N50,000 at the beginning of every year starting from now. How many years will it take Blessing to earn the lump sum if any deposit she makes attracts interest at the rate of 21% per annum?","options":["10 yrs","11 yrs","12 yrs","13 yrs"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Deposits at the start of each year form an annuity due: 50,000 x 1.21 x [(1.21^n - 1) / 0.21] = 2,000,000, so 1.21^n = 7.942 and n = log 7.942 / log 1.21 = 10.87, which means 11 years. After 10 years (A) the fund is only about N1.65 million, short of the target, while 12 or 13 years (C, D) are more than needed."}},{"itemId":"b70c7e84-d231-556c-a3af-aadec26fcc2a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"da4c4db4-c37e-5645-995d-26fbeb611fe8","sourceKey":"bank:BUA216:F101-034","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The expected return of the security is","options":["N56,000","N66,000","N68,000","N61,000"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: 0.1(50,000) + 0.2(60,000) + 0.7(70,000) = 5,000 + 12,000 + 49,000 = N66,000. Option D (N61,000) is the expected value when the probabilities are 0.3, 0.3 and 0.4."}},{"itemId":"68bc96a3-7f5e-5e29-8c81-8d58e115240c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c6bebe9b-7844-5cc3-b392-c3291105f2d0","sourceKey":"bank:BUA216:F101-035","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The variance of the security is","options":["N44,000,000","N44,300,000","N6,633.25","N69,000,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"With an expected return of N66,000, the variance is 0.1(-16,000)^2 + 0.2(-6,000)^2 + 0.7(4,000)^2 = 25,600,000 + 7,200,000 + 11,200,000 = 44,000,000. Option C (N6,633.25) is the standard deviation, the square root of the variance. Option B is a near-miss figure."}},{"itemId":"a60e0f8b-342c-50eb-8379-2dc1b8b3981c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"334cd3e8-e93d-5db1-8889-7f508323f295","sourceKey":"bank:BUA216:F101-036","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The standard deviation of the security is","options":["N6,633.25","N8,306.62","N44,000,000","N44,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"The standard deviation is the square root of the variance: square root of 44,000,000 = N6,633.25. Option C is the variance itself. Option B (N8,306.62) is the standard deviation for probabilities of 0.3, 0.3 and 0.4, not these."}},{"itemId":"677f9a30-cb8d-5b90-b31f-ee4c6e1b64f4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c8edb04c-a10b-5441-8036-27e0062058f2","sourceKey":"bank:BUA216:F101-037","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). The standard deviation of the security is","options":["N25,000","N6,633.25","N44,000,000","N57,000"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Expected return = 0.7(50,000) + 0.2(60,000) + 0.1(70,000) = N54,000. Variance = 0.7(4,000)^2 + 0.2(6,000)^2 + 0.1(16,000)^2 = 44,000,000, so the standard deviation is N6,633.25. Reversing the probabilities moves the mean but leaves the spread unchanged. Option C is the variance, not its square root."}},{"itemId":"6ce1b160-5328-55b9-a074-eb2d5ee5cf6f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aaa2bf29-38d3-5f79-a27b-068a46581c8e","sourceKey":"bank:BUA216:F101-038","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). To the nearest whole percent, the coefficient of variation of the security is","options":["14%","12%","11%","10%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"The coefficient of variation is standard deviation divided by expected return: 6,633.25 / 66,000 = 0.1005, or 10%. Option B (12%) is the CV of the same returns with the probabilities reversed, where the expected return is only N54,000."}},{"itemId":"65ebffad-2a75-51cc-aaf5-7756557b7d3c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8bc18486-fbf5-57be-b12f-b99268d4013b","sourceKey":"bank:BUA216:F101-039","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). The expected value of the security is","options":["N66,000","N7,810.25","N61,000,000","N54,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Expected value = 0.7(50,000) + 0.2(60,000) + 0.1(70,000) = 35,000 + 12,000 + 7,000 = N54,000. Option A (N66,000) is the result when the 0.7 probability sits on N70,000 instead of N50,000. Option B is a standard deviation figure, not an expected value."}},{"itemId":"a896acb1-c722-5c79-924c-8401ba073711","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7bc139d0-0a42-550a-bd09-e0f0d99c020a","sourceKey":"bank:BUA216:F101-040","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). The variance of the security is","options":["N44,000","N7,810.25","N44,000,000","N57,000"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Around the expected value of N54,000, the variance is 0.7(4,000)^2 + 0.2(6,000)^2 + 0.1(16,000)^2 = 11,200,000 + 7,200,000 + 25,600,000 = 44,000,000. Option A drops three zeros. Option B is a standard deviation, and option D is an expected value."}},{"itemId":"07a667c8-0b04-5c51-98f5-53ea3fb37d4b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6702f4e2-8beb-547f-8e5f-f676ee5788ed","sourceKey":"bank:BUA216:F101-041","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). To the nearest whole percent, the coefficient of variation of the security is","options":["13%","11%","12%","N54,000"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"CV = standard deviation / expected value = 6,633.25 / 54,000 = 0.1228, or 12%. Option D (N54,000) is the expected value, not a ratio. Option A (13%) and option B (11%) do not match the calculation."}},{"itemId":"d2652c4b-d12b-5aa9-bf40-a77ff597bb48","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4e5303ec-bb05-5b2c-a6c1-ff328b25eac1","sourceKey":"bank:BUA216:F101-042","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the risk concerned with the introduction of debt into a firm's capital structure.","options":["Business risk","Economic risk","Investment risk","Financial risk"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Financial risk arises when a firm uses debt. The fixed interest and repayments must be met whatever happens, which raises the chance that shareholders' returns will swing or that the firm will default. Business risk (A) comes from the uncertainty of operations themselves, even with no debt at all."}},{"itemId":"fdb8c58b-5136-53b9-aed0-694a9ad85a9c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"42afb60c-c3c4-50b8-a831-1c31bf86deed","sourceKey":"bank:BUA216:F101-043","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the risk concerned with the uncertainty of the future prospects of a firm.","options":["Business risk","Economic risk","Investment risk","Financial risk"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Business risk is the uncertainty about a firm's future operating results, such as sales, costs and profits, that comes from the nature of its business and its market. Financial risk (D) is the additional risk created by using debt. Economic risk (B) refers to the wider economy rather than the firm's own prospects."}},{"itemId":"50f27247-c1de-5568-acc9-a872eb353bb6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c466d5eb-e71f-5689-b989-ff29ab289ea7","sourceKey":"bank:BUA216:F101-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key area of finance?","options":["Corporate finance for business funding","Product innovation and design","Staff development programs","Consumer behavior analysis"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Corporate finance, which deals with how businesses raise and use funds, is one of the main areas of finance alongside personal and public finance. Options B, C and D belong to production, human resources and marketing respectively."}},{"itemId":"d4633c54-7223-5730-af83-f37169de0805","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8d590ed9-0de9-546b-87c7-52e25f6ca777","sourceKey":"bank:BUA216:F101-047","parentItemId":null,"revision":1,"payload":{"prompt":"Personal finance focuses on:","options":["Directing corporate cash flows","Handling an individual's financial assets","Administering public sector budgets","Facilitating global trade deals"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Personal finance is about how an individual or household manages income, savings, spending and investments, so B fits. Option A is corporate finance, C is public finance, and D is international trade."}},{"itemId":"d94f64f7-5a66-5119-9a99-7c958551d08e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3c70f275-06ec-50ff-9c75-fe778278c91e","sourceKey":"bank:BUA216:F101-048","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money is a fundamental concept in:","options":["Market segmentation strategies","Finance and investment decisions","Employee relations management","Production process optimization"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The time value of money says that money available now is worth more than the same amount later because it can earn a return, which makes it central to finance and investment decisions (B). Options A, C and D are marketing, human resources and production topics that do not rely on this idea."}},{"itemId":"cd0dcad2-67e4-5188-acbf-669de326e100","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bf798571-9ba1-58b0-87c3-ae61d85462e9","sourceKey":"bank:BUA216:F101-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a role of a financial manager?","options":["Recruiting new team members","Evaluating investment opportunities","Crafting product prototypes","Analyzing market demographics"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A main job of the financial manager is the investment decision: assessing which projects or assets are worth putting money into. Recruiting staff (A) is human resources, prototypes (C) is production, and demographics (D) is marketing research."}},{"itemId":"7a804f2c-d214-509d-b072-8cb06a0bc1f3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"07c29bff-c0f5-5433-832a-43a33b8f9706","sourceKey":"bank:BUA216:F101-050","parentItemId":null,"revision":1,"payload":{"prompt":"The study of finance helps in:","options":["Optimizing resource allocation decisions","Minimizing competitive pressures","Sidestepping financial foresight","Disregarding economic indicators"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Finance helps decision makers allocate scarce funds to the uses that give the best return for the risk taken, so A is correct. Options C and D are the opposite of what finance teaches, and B is not something studying finance achieves."}},{"itemId":"47286b7d-6116-5c52-9e7b-65dc7bd6ab13","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"eae34ee1-2214-5bd8-ac3e-e49d4aded6fb","sourceKey":"bank:BUA216:F101-051","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a type of financial decision?","options":["Setting product price points","Planning capital expenditures","Selecting new hires","Developing ad campaigns"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Planning capital expenditure is an investment decision, one of the core financial decisions alongside financing and dividend decisions. Pricing (A) and advertising (D) are marketing choices, and hiring (C) is a human resources choice."}},{"itemId":"b2688d83-9f3d-5e9d-aa80-ecf634305b47","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"976d1c67-9de5-5d19-99a1-dc028bdb1d5d","sourceKey":"bank:BUA216:F101-052","parentItemId":null,"revision":1,"payload":{"prompt":"The field of finance includes:","options":["Investments and financial market dynamics","Exclusively ledger maintenance","Solely promotional activities","Purely manufacturing processes"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Finance covers investments and the workings of financial markets, among other areas. Options B, C and D use words like \"exclusively\", \"solely\" and \"purely\", and they describe bookkeeping, promotion and manufacturing rather than the broad field of finance."}},{"itemId":"eaf8a56c-d0b3-5c81-a3eb-434c33a7dff9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"85a9fcf8-83ea-54a0-a8ee-0e8cf34a1b86","sourceKey":"bank:BUA216:F101-053","parentItemId":null,"revision":1,"payload":{"prompt":"A financial manager must balance:","options":["Risk exposure and potential returns","Staff morale and output levels","Advertising and revenue goals","Design quality and innovation"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Every financial decision involves a risk-return trade-off: higher expected returns usually come with higher risk, so the financial manager must balance the two. Options B, C and D are concerns of human resources, marketing and product design."}},{"itemId":"f5f348d8-8929-5e45-9dab-8c9c6c1504bd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"829e6109-57b2-5b81-a150-a3d8751cbce4","sourceKey":"bank:BUA216:F101-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a component of financial planning?","options":["Defining monetary objectives","Engineering a new product","Onboarding personnel","Surveying market trends"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Financial planning starts with setting financial goals, such as how much to save, invest or raise, and then planning how to reach them. Options B, C and D are product development, human resources and market research tasks."}},{"itemId":"d8529840-d2f6-545c-ace4-47626f268838","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d813cd8f-f26f-59c9-b117-c0092bf09b88","sourceKey":"bank:BUA216:F101-055","parentItemId":null,"revision":1,"payload":{"prompt":"The primary focus of corporate finance is:","options":["Managing individual savings accounts","Overseeing a firm's financial operations","Administering tax policies","Boosting workforce motivation"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Corporate finance deals with the financial activities of a firm, such as raising capital, choosing investments and paying dividends. Option A is personal finance and C relates to public finance, while D is a human resources issue."}},{"itemId":"024abc37-9b0d-52f7-91f8-ebfa03b575d4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"08d1e15e-6a10-58f5-8cd9-f1f34d83287e","sourceKey":"bank:BUA216:F101-056","parentItemId":null,"revision":1,"payload":{"prompt":"Finance is important because it:","options":["Enables informed strategic choices","Eliminates planning requirements","Centers solely on profit gains","Neglects risk considerations"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Finance gives managers the information and tools to make well-informed strategic choices about funds, risk and return. Option B is wrong because finance requires planning, D is wrong because risk is central to finance, and C is too narrow since finance looks at more than profit."}},{"itemId":"e53bdb7b-ca72-5b75-8977-602809a957a5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"84a92cef-f6cf-5a69-a3b0-07ae82d65d85","sourceKey":"bank:BUA216:F101-057","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of diversification in finance refers to:","options":["Concentrating funds in one asset","Spreading investments to mitigate risk","Amplifying borrowing levels","Curtailing profit margins"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Diversification means spreading money across different investments so that a loss on one can be offset by gains on others, reducing overall risk. Option A, putting all funds in one asset, is the opposite and increases risk."}},{"itemId":"04528124-0ae8-51f5-b84d-d880e773a67e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8d80664d-ce8b-5ca7-a699-b0a088f85d7e","sourceKey":"bank:BUA216:F101-058","parentItemId":null,"revision":1,"payload":{"prompt":"The primary objective of a business firm is often to:","options":["Maximize profits for its owners","Limit employee well-being","Evade market rivalry","Scale back output"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Traditionally, a business firm's main objective is taken to be profit maximisation, earning as much profit as possible for its owners. Options B, C and D would harm the business, so none of them can be its objective."}},{"itemId":"424faebe-896f-53d4-9313-cf5e16236c32","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3517e029-08ac-5b00-9f45-9bb0fade0d49","sourceKey":"bank:BUA216:F101-059","parentItemId":null,"revision":1,"payload":{"prompt":"Maximizing shareholder wealth means:","options":["Enhancing stock value and payouts","Lowering staff remuneration","Overlooking client demands","Bypassing financial strategies"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Shareholder wealth maximisation means increasing the value of the owners' stake, shown through a rising share price and dividends. Options B, C and D would tend to damage the firm and reduce shareholder value over time."}},{"itemId":"99886200-180b-5cb3-9f96-f4ca14e5a220","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a7d5aea1-b609-5cd9-b07e-48adf789b860","sourceKey":"bank:BUA216:F101-060","parentItemId":null,"revision":1,"payload":{"prompt":"A secondary objective of a business firm might be:","options":["Corporate social responsibility initiatives","Escalating debt levels","Shrinking revenue streams","Dodging tax responsibilities"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Besides profit or wealth, firms often pursue secondary goals such as corporate social responsibility, for example supporting the community or protecting the environment. Options B, C and D are harmful outcomes or illegal behaviour, not objectives."}},{"itemId":"c4749324-7c28-575d-a440-bc0120c340a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"23a4e553-18a7-5300-91ec-b93ed3ddff61","sourceKey":"bank:BUA216:F101-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a long-term objective of a firm?","options":["Covering daily operational costs","Expanding market presence","Employing short-term workers","Depleting stock reserves"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Expanding market presence is a long-term goal because it takes years of investment and planning to achieve. Covering daily costs (A) and using short-term workers (C) are short-run matters, and running down stock (D) is not an objective."}},{"itemId":"5fb095f7-c400-58ca-83c6-5544501c3d69","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"64a95754-be60-5b05-9934-456d937ce868","sourceKey":"bank:BUA216:F101-062","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of profit maximization focuses on:","options":["Immediate financial gains","Sustained operational viability","Worker contentment","Customer retention"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Profit maximisation is often criticised for focusing on short-term, immediate profits while ignoring timing and risk. Sustained viability (B) is closer to wealth maximisation, and worker contentment (C) and customer retention (D) are separate goals."}},{"itemId":"1c885120-99c7-5327-8b0c-637e23bd5c53","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0b6818e2-b1aa-58a8-8bdd-9039082d9b8a","sourceKey":"bank:BUA216:F101-063","parentItemId":null,"revision":1,"payload":{"prompt":"A business firm's objective to survive in the market is:","options":["A growth-driven goal","A survival-focused goal","A profit-centric goal","A community-oriented goal"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Staying in business, especially in tough or competitive conditions, is a survival objective, so B is correct. Growth (A) is about expanding, profit (C) is about earnings, and community goals (D) are social objectives."}},{"itemId":"1768cbba-fd62-5d63-9719-1ac049936044","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"df90f096-ee85-5368-8a30-69c0af3fdbf0","sourceKey":"bank:BUA216:F101-065","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of a firm to maintain liquidity means:","options":["Ensuring cash for short-term needs","Growing long-term liabilities","Cutting sales volumes","Halting investment activities"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A liquidity objective means the firm keeps enough cash or near-cash assets to meet short-term obligations such as wages and supplier bills as they fall due. Growing long-term liabilities (B) does not provide liquidity, and cutting sales (C) or halting investment (D) are not what liquidity means."}},{"itemId":"0d54af0c-05a6-5cf5-a9d5-a2295d7c32e0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"89ce670a-462e-5370-b723-261e08fa3533","sourceKey":"bank:BUA216:F101-066","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to grow often involves:","options":["Shrinking business operations","Entering untapped markets","Limiting profit potential","Avoiding competitive threats"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Growth usually means getting bigger, for example by entering new markets, launching products or expanding capacity. Shrinking operations (A) and limiting profit (C) are the opposite of growth, and avoiding competition (D) does not grow the business."}},{"itemId":"d4e8120b-84ad-5589-a950-b75e1f726c81","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"13f4e9ea-232a-5067-82ed-1a7f3d999de8","sourceKey":"bank:BUA216:F101-067","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a social objective of a business firm?","options":["Boosting profit margins","Enhancing community welfare","Reducing staff perks","Increasing leverage"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Social objectives are about the firm's responsibility to society, such as improving community welfare. Boosting margins (A) is a profit objective, while cutting staff perks (C) and increasing leverage (D) are not social goals."}},{"itemId":"cb878e1a-dc97-5421-8e43-c5f39ae974fd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cab6b00f-b771-5dda-b596-035e3a8adba9","sourceKey":"bank:BUA216:F101-068","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of maximizing shareholder wealth aligns with:","options":["Building enduring value","Short-term expense cuts","Lowering dividend payouts","Shunning capital investments"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Wealth maximisation looks at the long run, aiming to build lasting value for shareholders. Short-term cost cuts (B) relate more to short-run profit, and cutting dividends (C) or avoiding investment (D) do not by themselves build value."}},{"itemId":"550439c0-b64f-5859-a4b6-d0e5fc411b27","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"19ff3bf0-f1c7-5d08-8b01-f0ca767d42e2","sourceKey":"bank:BUA216:F101-069","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to innovate can lead to:","options":["Diminished market competition","Greater market penetration","Elevated short-term expenses","Both B and C"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Innovation can help a firm reach more customers and gain market share (B), but research and development also raise costs in the short term (C), so both are true and D is correct. Option A is wrong because innovation usually increases competition rather than reducing it."}},{"itemId":"43d7655b-4638-5b7b-9b02-49e91cc46a01","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4a723242-2a38-528e-8cb1-6bb88ac75064","sourceKey":"bank:BUA216:F101-070","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of a firm to be ethical involves:","options":["Disregarding legal standards","Adhering to equitable practices","Prioritizing profits above all","Limiting transparency efforts"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Ethical behaviour means acting fairly and honestly, following fair practices in dealing with customers, staff and society. Ignoring the law (A), putting profit above everything (C) and reducing transparency (D) are all unethical."}},{"itemId":"ec7e12e5-99bf-5f9e-af48-67b20f6f682c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b092adee-b6b3-53c0-847f-aabddb66714f","sourceKey":"bank:BUA216:F101-071","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to increase efficiency focuses on:","options":["Lowering costs and boosting output","Raising debt obligations","Decreasing revenue targets","Stifling innovative efforts"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Efficiency means getting more output from the same or fewer resources, which means lower costs and higher output. Raising debt (B), lowering revenue targets (C) and blocking innovation (D) do not improve efficiency."}},{"itemId":"acb48761-b282-594d-9d43-a71584c4ebe4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8643a701-090b-58aa-a8ef-387334e1c3a8","sourceKey":"bank:BUA216:F101-072","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of compound interest means:","options":["Interest accrues solely on the initial amount","Interest builds on principal and prior interest","No interest is generated","Interest is disbursed once only"],"correctOption":1,"section":"Mathematics of Finance","explanation":"With compound interest, each period's interest is added to the principal, so later interest is earned on both the principal and the interest already earned. Option A describes simple interest, where interest is only calculated on the original amount."}},{"itemId":"a8d2df16-48b2-5961-800d-de2ea3705fb9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"20d40cc8-f7a5-5480-88b7-1d6b6a1a3767","sourceKey":"bank:BUA216:F101-073","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for simple interest is:","options":["I = P x R x T","I = P x (1 + R x T)","I = P x R / T","I = P + R x T"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Simple interest is I = P x R x T, where P is the principal, R the rate per year and T the time in years. Option B gives the total amount (principal plus interest), not the interest alone, and C and D are not valid formulas."}},{"itemId":"e15eaafa-8196-571b-9151-b97430dc4b87","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e97e4d90-221b-5323-837e-8e828fbe99c4","sourceKey":"bank:BUA216:F101-074","parentItemId":null,"revision":1,"payload":{"prompt":"If N1,000 is invested at 5% simple interest per annum for 2 years, what is the simple interest earned?","options":["N50","N100","N150","N200"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Simple interest is I = P x R x T = 1,000 x 0.05 x 2 = N100, because interest is earned only on the original amount each year. Option A (N50) is just one year's interest, while C and D overstate it, since simple interest does not compound."}},{"itemId":"85a5e5c2-13c8-512a-8a24-e9f7d55465b9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5440fcb1-fa37-5908-ae2f-da1dd34598f2","sourceKey":"bank:BUA216:F101-075","parentItemId":null,"revision":1,"payload":{"prompt":"The future value of money takes into account:","options":["The impact of time on value","Just the original principal","Only the applied interest rate","Merely the duration"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Future value shows what money today will grow to after earning interest over time, so it brings in the principal, the rate and the time together. Options B, C and D each look at only one of these parts."}},{"itemId":"0783dda8-5a8f-5934-ab4e-92aa16544b0b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3c6b8da2-5b2d-5ef4-bad8-ddacf4753bfd","sourceKey":"bank:BUA216:F101-076","parentItemId":null,"revision":1,"payload":{"prompt":"The present value of money is:","options":["Today's worth of future cash flows","Historical value of past earnings","Future worth of current funds","Value ignoring interest effects"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Present value is what a future amount of money is worth today after discounting it at an appropriate interest rate. Option C describes future value, B looks at the past, and D is wrong because present value depends on interest."}},{"itemId":"5181bca6-b7db-5050-8f5e-860664bb5fb0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"626ac93e-9068-52f2-b059-ae72a1ac461f","sourceKey":"bank:BUA216:F101-077","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for compound interest is:","options":["A = P x (1 + R/n)^(n x t)","A = P x R x T","A = P + R x T","A = P x (1 + R)"],"correctOption":0,"section":"Mathematics of Finance","explanation":"The compound amount is A = P x (1 + R/n)^(n x t), where n is the number of compounding periods per year and t is the number of years. Option B is the simple interest formula, and D only covers one period."}},{"itemId":"b62169a3-9912-5248-8c8a-3141f8472054","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0008148d-e8c6-53fb-bd8d-9fd8da5d077a","sourceKey":"bank:BUA216:F101-078","parentItemId":null,"revision":1,"payload":{"prompt":"If N500 is invested at 4% compounded annually for 3 years, what is the future value?","options":["N560.00","N562.43","N580.00","N600.00"],"correctOption":1,"section":"Mathematics of Finance","explanation":"With annual compounding, FV = 500 x (1.04)^3 = N562.43, because each year's interest also earns interest. Option A (N560) is what simple interest would give (500 + 500 x 0.04 x 3), and C and D are too high."}},{"itemId":"5c86a6b3-bd8b-5ed1-8fb5-141c86275ffc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8539bcd6-14f7-5e65-b856-2b96f21246e6","sourceKey":"bank:BUA216:F101-079","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money concept states that:","options":["Present funds outvalue future funds","Future funds outvalue present funds","Money retains static value","Money's worth is unchanging"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Money received today is worth more than the same amount in the future because it can be invested to earn interest, and inflation reduces its buying power over time. Option B reverses this, and C and D ignore the time value of money entirely."}},{"itemId":"cf87619e-265c-5891-b4a1-1ba89beb55b2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e988a2a2-2713-59bd-8bae-68caa5d6f495","sourceKey":"bank:BUA216:F101-080","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity is:","options":["A one-time lump sum","A sequence of regular payments","A borrowing agreement","An equity investment"],"correctOption":1,"section":"Mathematics of Finance","explanation":"An annuity is a series of equal payments made at regular intervals for a fixed period, such as monthly rent or loan repayments. Option A is a single lump sum, which is the opposite of an annuity."}},{"itemId":"6e4b245f-e709-5e07-86d4-4671dafe996c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7fc96ad9-ef0e-5a82-9136-3829390d6e5a","sourceKey":"bank:BUA216:F101-081","parentItemId":null,"revision":1,"payload":{"prompt":"The discount rate is used to:","options":["Project future cash growth","Determine current cash value","Elevate interest charges","Shrink principal amounts"],"correctOption":1,"section":"Mathematics of Finance","explanation":"A discount rate is used to convert future cash flows into their present value, that is, their value today. Option A describes compounding toward a future value, while C and D are not what discounting does."}},{"itemId":"607dc713-507f-514e-99fd-37fc67c58671","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"31d4be1f-9385-5265-9ca6-ac1d7244c6be","sourceKey":"bank:BUA216:F101-082","parentItemId":null,"revision":1,"payload":{"prompt":"If the interest rate increases, the present value of a future cash flow:","options":["Rises due to higher returns","Falls due to discounting","Stays constant regardless","Drops to zero entirely"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Present value is PV = FV / (1 + r)^n, so a higher interest rate makes the denominator bigger and the present value smaller. Option A gets the direction wrong, and D is wrong because PV falls but does not become zero."}},{"itemId":"7914702b-d80e-5f88-9afd-ecd93a565d67","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7e587004-a44d-5053-a314-30b58f7dae01","sourceKey":"bank:BUA216:F101-083","parentItemId":null,"revision":1,"payload":{"prompt":"The effective annual rate (EAR) takes into account:","options":["Basic interest without compounding","Frequency of interest compounding","Principal amount alone","Duration without adjustments"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The effective annual rate shows the true yearly return once compounding more than once a year is taken into account: EAR = (1 + r/m)^m - 1, where m is the number of compounding periods. Option A describes the nominal rate, which ignores compounding."}},{"itemId":"96fb2b72-3ce0-5218-af4b-f6db59eefa76","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f8cc49d6-8d7e-53dd-84f6-b9bcc931b0ea","sourceKey":"bank:BUA216:F101-084","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity is:","options":["A limited payment series","An endless stream of equal payments","A solitary cash disbursement","A financed debt obligation"],"correctOption":1,"section":"Mathematics of Finance","explanation":"A perpetuity is a stream of equal payments that continues forever, and its present value is PV = payment / r. Option A describes an ordinary annuity, which ends after a fixed number of payments."}},{"itemId":"b6dce759-7f1b-53b7-b1a8-37c2f02ad5ed","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8c79a282-d2c7-506e-ad96-0b970f680438","sourceKey":"bank:BUA216:F101-085","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for the future value of an annuity is used to:","options":["Assess a one-off payment's worth","Compute a payment series' total","Calculate basic interest gains","Estimate discounted present value"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The future value of an annuity formula adds up a series of regular payments plus the interest they earn, giving their total value at the end. Option A is for a single sum, and D describes the present value of an annuity."}},{"itemId":"de2dc19c-1ee2-52a6-a4a2-265da48d6482","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"747ed948-0b4c-5627-bb83-a18e05f6664f","sourceKey":"bank:BUA216:F101-086","parentItemId":null,"revision":1,"payload":{"prompt":"A financial market is a place where:","options":["Physical goods are manufactured","Financial instruments are exchanged","Workers are recruited","Products are advertised"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A financial market is where financial assets such as shares, bonds and treasury bills are bought and sold. Options A, C and D describe factories, labour markets and advertising, which do not trade financial instruments."}},{"itemId":"f1d4a1a5-8ba1-58c3-acb6-eb9cefd540de","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"baa1842f-2f01-5c83-8e35-1183b90a9669","sourceKey":"bank:BUA216:F101-087","parentItemId":null,"revision":1,"payload":{"prompt":"The stock market is an example of:","options":["A short-term lending market","A long-term capital market","A workforce exchange","A raw materials market"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The stock market trades shares, which are long-term securities, so it is part of the capital market. Option A describes the money market, which deals with short-term lending and borrowing."}},{"itemId":"22ab939e-65b7-5ea7-a8c9-4517d9db6f32","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb62ad3e-44d8-5165-87d5-24f089c3737a","sourceKey":"bank:BUA216:F101-088","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a financial instrument?","options":["A production facility","An equity share in a firm","A piece of machinery","A corporate office building"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A financial instrument is a tradeable claim to money or ownership, such as a share or a bond, so an equity share is correct. Options A, C and D are physical (real) assets, not financial instruments."}},{"itemId":"9bff74c5-444f-59d0-bdb3-a9d640e20880","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"082d2212-c98f-5869-b7bb-be0ccc1f92f0","sourceKey":"bank:BUA216:F101-089","parentItemId":null,"revision":1,"payload":{"prompt":"The primary market is where:","options":["Investors trade existing assets","New securities are first offered","Used securities are resold","Commodities are swapped"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The primary market is where new securities are sold for the first time, for example in an initial public offering, so the issuing company gets the money. Options A and C describe the secondary market, where existing securities change hands between investors."}},{"itemId":"a49d019e-03f0-5495-8664-f5a27b038187","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b5cdfee5-721a-546d-b281-8b507896e5bf","sourceKey":"bank:BUA216:F101-090","parentItemId":null,"revision":1,"payload":{"prompt":"The secondary market allows investors to:","options":["Purchase freshly issued stocks","Exchange previously issued securities","Launch new debt offerings","Generate fresh equity shares"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"In the secondary market, investors buy and sell securities that have already been issued, as happens daily on a stock exchange. Options A, C and D describe new issues, which take place in the primary market."}},{"itemId":"583c706b-d297-568c-bba6-5f890375dec1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0fae64a2-cea6-5ef0-8051-b1bb5df6b68e","sourceKey":"bank:BUA216:F101-091","parentItemId":null,"revision":1,"payload":{"prompt":"A bond is:","options":["A stake in company ownership","A debt instrument issued by a borrower","An equity-based security","A traded physical asset"],"correctOption":1,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A bond is a debt instrument: the issuer borrows money from investors and promises to pay interest and repay the principal at maturity. Options A and C describe shares (equity), which give ownership rather than a loan, and D describes a commodity, not a security."}},{"itemId":"bcc481dc-39ef-56e3-9fab-31852f8bbbac","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dee8accd-4764-52e0-a2b9-f6332d87826a","sourceKey":"bank:BUA216:F101-092","parentItemId":null,"revision":1,"payload":{"prompt":"The money market deals with:","options":["Long-term investment vehicles","Short-term financial instruments","Agricultural goods","Property transactions"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The money market deals in short-term instruments, usually maturing within a year, such as treasury bills and commercial paper. Option A describes the capital market, and C and D are commodity and property markets."}},{"itemId":"85eabcd7-cbc2-5141-bb90-f82b32e4faeb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6b96bc3-2359-54f9-9481-af5101cebc64","sourceKey":"bank:BUA216:F101-093","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a role of financial markets?","options":["Curtailing competitive forces","Enabling fund transfers efficiently","Raising production expenses","Restricting investment options"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Financial markets move funds efficiently from savers who have surplus money to borrowers and firms that need it. Options A, C and D are the opposite of what well-functioning financial markets do."}},{"itemId":"2ad190d1-c22d-5699-a53f-f537b3799803","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e9acf6fa-17dc-5229-aacb-06aded07ea28","sourceKey":"bank:BUA216:F101-094","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian Exchange (NGX), formerly the Nigerian Stock Exchange (NSE), is an example of:","options":["A liquidity-focused money market","An equity-driven capital market","A goods-trading commodity market","An employment labor market"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The Nigerian Stock Exchange, now the Nigerian Exchange, is where long-term securities such as shares are traded, so it is part of the capital market. Option A is wrong because the money market deals with short-term instruments, not shares."}},{"itemId":"5cc1a35e-40e0-5c9c-99e6-f99ccc586651","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"79ac1c70-d204-52b1-9ff4-eb4e0551e7d8","sourceKey":"bank:BUA216:F101-095","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund is:","options":["A standalone stock investment","A collective investment pool","A fixed-income debt security","A personal loan product"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A mutual fund pools money from many investors and invests it in a spread of securities managed by professionals. Option A is a single share, C is a bond, and D is a loan."}},{"itemId":"2be5634b-8082-54d6-933a-31683f7f5b0a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d255daba-45d0-577c-a152-cab6f65987fc","sourceKey":"bank:BUA216:F101-096","parentItemId":null,"revision":1,"payload":{"prompt":"The capital market is primarily concerned with:","options":["Short-term cash flow needs","Long-term financing solutions","Staff compensation funding","Product promotion budgets"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The capital market provides long-term finance through instruments such as shares and bonds. Option A describes the money market, which meets short-term cash needs."}},{"itemId":"87a90d4c-d950-5535-b59e-ee1118740e85","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5cdc9f7b-44da-58ad-83f3-5277adf035b3","sourceKey":"bank:BUA216:F101-097","parentItemId":null,"revision":1,"payload":{"prompt":"A financial intermediary is:","options":["A producer of tangible goods","A link between lenders and borrowers","An equity security type","A debt issuance tool"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A financial intermediary, such as a bank, stands between savers (lenders) and borrowers, collecting funds from one group and lending to the other. Option A describes a manufacturer, and C and D are instruments rather than institutions."}},{"itemId":"2996925c-3e26-5f79-9c34-22825a75d4a1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c28a6bd4-4a85-58fc-acf1-829531c2d9f6","sourceKey":"bank:BUA216:F101-098","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a participant in financial markets?","options":["Investors seeking returns","Factories producing goods","Stores selling products","Workers in operations"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Investors who supply funds hoping to earn a return are key participants in financial markets. Factories, shops and workers (B, C and D) are part of the goods and labour markets, not financial markets."}},{"itemId":"1f2175c4-cca5-5651-b1e0-43704729a949","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"431d8afe-1bd4-5d06-9fa9-4d4f4e6f2c12","sourceKey":"bank:BUA216:F101-099","parentItemId":null,"revision":1,"payload":{"prompt":"The price of a stock is determined by:","options":["Government-set price controls","Market supply and demand forces","Employee wage levels","Manufacturing cost structures"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Share prices in an open market are set by the forces of supply and demand, as buyers and sellers react to news about the company and the economy. Option A is wrong because share prices are not fixed by government, and C and D affect a company indirectly at most."}},{"itemId":"3df60225-6bc4-5a78-9d7f-b1dba35192e0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7d36fd72-c7b4-56e0-9d48-d157e0f18438","sourceKey":"bank:BUA216:F101-100","parentItemId":null,"revision":1,"payload":{"prompt":"Risk in finance refers to:","options":["Assured investment outcomes","Uncertainty in expected returns","Guaranteed profit margins","Rejection of investment plans"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Risk in finance is the uncertainty about returns: actual returns may differ from what was expected. Options A and C describe certainty, the opposite of risk, and D has nothing to do with risk."}},{"itemId":"21388df3-971b-506b-bf78-a96586b435b2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1620b276-e124-5b34-9982-266780c59764","sourceKey":"bank:BUA216:F101-101","parentItemId":null,"revision":1,"payload":{"prompt":"Systematic risk is:","options":["Unique to a specific firm","Broad market risk impacting all","Mitigated by portfolio variety","Confined to one sector"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Systematic risk is market-wide risk, from factors such as recessions, inflation or interest rate changes, that affects all firms. Options A and D describe unsystematic risk, and C is wrong because diversification cannot remove systematic risk."}},{"itemId":"ca4a0f4b-ca37-5c4e-880d-6f719beb133b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c6eb4799-03ce-5841-8ace-9d8dc417047e","sourceKey":"bank:BUA216:F101-102","parentItemId":null,"revision":1,"payload":{"prompt":"Unsystematic risk can be reduced by:","options":["Focusing on one stock holding","Diversifying across assets","Raising debt exposure","Avoiding all investments"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Unsystematic risk is specific to individual firms, so holding many different assets lets losses on some be offset by gains on others. Option A increases this risk, and D avoids risk only by giving up any return."}},{"itemId":"19182220-e8a1-5eca-b208-d1ecdab1b1c5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"91f6a562-b23d-5b5c-b626-6e3309d8a1a6","sourceKey":"bank:BUA216:F101-103","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of systematic risk?","options":["A firm's ineffective leadership","An economic downturn market-wide","A defective product launch","A company-specific strike"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"An economic downturn hits almost all firms at once, so it is a systematic (market) risk. Poor leadership (A), a faulty product (C) and a strike at one company (D) are firm-specific, unsystematic risks."}},{"itemId":"549340ff-7d0c-5273-b698-69faaa80b27f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6cd06f3-94c5-5c05-a9c3-f01da636bdc4","sourceKey":"bank:BUA216:F101-104","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-return tradeoff means:","options":["Greater risk yields lower gains","Higher risk offers higher potential rewards","Risk and reward are disconnected","Minimal risk ensures big returns"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"The risk-return trade-off says investors will only take on more risk if they expect a higher return, so riskier investments offer higher potential rewards. Option A reverses the relationship, and D is wrong because low-risk assets usually give modest returns."}},{"itemId":"190a3e57-2f7d-573f-876b-ebd0f7c89d19","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e642b22e-26ca-5c78-86c4-fc860ba988ec","sourceKey":"bank:BUA216:F101-105","parentItemId":null,"revision":1,"payload":{"prompt":"A risk-averse investor prefers:","options":["Volatile high-stakes ventures","Stable low-risk options","Complete investment abstention","Speculative high-return bets"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"A risk-averse investor dislikes uncertainty and will choose safer, lower-risk investments, accepting lower returns. Options A and D describe a risk seeker, and C is wrong because being risk averse does not mean refusing to invest."}},{"itemId":"640ba1a4-e1ad-5c4d-bf97-f762118c7f6d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"304c0e12-9eaa-5f73-b789-080059d1c63c","sourceKey":"bank:BUA216:F101-106","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a tool for analyzing risk?","options":["Income and expense reports","Standard deviation of returns","Promotional campaign plans","Factory output timelines"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Standard deviation measures how widely returns spread around the expected return, so a larger figure means more risk. Income and expense reports (A) show performance rather than risk, and C and D are marketing and production plans."}},{"itemId":"446392ed-8509-5542-8cc8-5be03f57bebe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"df15ea67-30cf-5c2b-b235-5397aaeefefe","sourceKey":"bank:BUA216:F101-107","parentItemId":null,"revision":1,"payload":{"prompt":"Credit risk refers to:","options":["A debtor failing to repay a loan","Market price volatility","Rising inflation pressures","Internal mismanagement"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Credit risk, or default risk, is the chance that a borrower will not repay a loan or interest on time. Price swings (B) are market risk, inflation (C) is purchasing power risk, and mismanagement (D) is a business risk."}},{"itemId":"fe2a7673-f297-5bba-b00d-3aa362133ba8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4ab5a85d-96a7-5089-ae59-3e6336d9130d","sourceKey":"bank:BUA216:F101-109","parentItemId":null,"revision":1,"payload":{"prompt":"A risk management strategy includes:","options":["Eliminating all uncertainties","Assessing and reducing risks","Amplifying risk exposure","Overlooking potential threats"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Risk management means identifying and assessing risks, then taking steps to reduce or control them. Option A is impossible because no business can remove all uncertainty, and C and D make things worse."}},{"itemId":"07eff0fc-0fb3-5bd7-8786-44b53187e7eb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6ed807f2-32ed-5567-85de-8f91cf2488d1","sourceKey":"bank:BUA216:F101-110","parentItemId":null,"revision":1,"payload":{"prompt":"Liquidity risk refers to:","options":["Difficulty liquidating assets fast","Inflation eroding value","Leadership errors in strategy","Market expansion challenges"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Liquidity risk is the danger of not being able to turn an asset into cash quickly without losing much of its value. Option B describes inflation risk, and C is a management risk."}},{"itemId":"9990a88d-accc-5528-b9b6-541248ab51fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4b0bfceb-675f-5585-abb9-778dcf28cb84","sourceKey":"bank:BUA216:F101-111","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a method to manage financial risk?","options":["Hedging with derivatives","Increasing leverage levels","Narrowing investment scope","Halting all funding activities"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Hedging means taking a position, often through contracts such as forwards or options, that offsets possible losses on another position, so it is a way to manage risk. Increasing leverage (B) and narrowing investments (C) raise risk, and D stops the business working."}},{"itemId":"3dc7d620-fdde-5e56-a2a1-06799f574dd2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"125728dc-2cad-5efa-9365-230aecbade87","sourceKey":"bank:BUA216:F101-112","parentItemId":null,"revision":1,"payload":{"prompt":"Interest rate risk affects:","options":["Fixed-income asset valuations","Equity prices exclusively","Commodity market trends","Real estate appreciation"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"When interest rates rise, the prices of fixed-income assets such as bonds fall, and the reverse is also true, so interest rate risk mainly affects them. Option B is wrong because the effect is not limited to shares, and C and D are not mainly driven by this risk."}},{"itemId":"ab13357c-2f54-5df7-89eb-0b60f471eef4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4bca7e8d-0449-5ca1-a62a-b62c2c35c7f1","sourceKey":"bank:BUA216:F101-113","parentItemId":null,"revision":1,"payload":{"prompt":"A risk premium is:","options":["Extra return for risk acceptance","Assured gain on investments","Cost of securing loans","Reduction in uncertainty"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"A risk premium is the extra return investors demand above a risk-free rate for accepting extra risk. Option B is the opposite, since a premium exists because returns are not guaranteed, and C describes the cost of borrowing."}},{"itemId":"1cfe8f23-b4f2-513a-a7ee-556170a20f37","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"abdefc2d-c1c4-548f-aeab-d25621029b1e","sourceKey":"bank:BUA216:F101-114","parentItemId":null,"revision":1,"payload":{"prompt":"Financial ratio analysis is used to:","options":["Gauge a firm's operational success","Innovate product offerings","Recruit new staff members","Promote company services"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Ratio analysis compares figures from financial statements to judge a firm's performance, such as its liquidity, profitability and efficiency. Options B, C and D are product, staffing and marketing activities."}},{"itemId":"61ccf2f8-6493-5650-ac7c-201d148b22ce","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"119e65b0-399e-59b0-9381-e05185b7274d","sourceKey":"bank:BUA216:F101-115","parentItemId":null,"revision":1,"payload":{"prompt":"The current ratio measures:","options":["Profit generation capacity","Short-term liquidity strength","Debt financing reliance","Process efficiency levels"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The current ratio (current assets / current liabilities) shows whether a firm can meet its short-term debts, so it is a liquidity ratio. Option A is a profitability ratio, C is a leverage ratio, and D is an activity ratio."}},{"itemId":"807f4519-68d2-5681-b94d-b29b188653e0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aca503a9-19ff-5a64-95d1-f3f14cca071e","sourceKey":"bank:BUA216:F101-116","parentItemId":null,"revision":1,"payload":{"prompt":"A high debt-to-equity ratio indicates:","options":["Minimal financial exposure","Significant leverage usage","Strong profit margins","Reduced borrowing"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Debt-to-equity compares borrowed funds with owners' funds, so a high figure means the firm relies heavily on debt (high leverage). Options A and D say the opposite, and C is wrong because this ratio does not measure profit."}},{"itemId":"b90d0928-188e-5def-978f-279b87006360","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70aa5048-6ad3-5597-8fe7-0b8b73589d70","sourceKey":"bank:BUA216:F101-117","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for the current ratio is:","options":["Current assets / Current liabilities","Total assets / Total liabilities","Net income / Revenue","Total debt / Equity"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The current ratio = Current assets / Current liabilities, for example 200,000 / 100,000 = 2:1. Option C is the net profit margin and D is the debt-to-equity ratio."}},{"itemId":"e7072c92-f4a9-5898-8863-e32e52a80911","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dc5e6a66-5fc0-591f-8058-ca414b07808b","sourceKey":"bank:BUA216:F101-118","parentItemId":null,"revision":1,"payload":{"prompt":"The return on equity (ROE) measures:","options":["Profit from shareholder funds","Cash flow availability","Operational streamlining","Market dominance"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Return on equity (net profit / shareholders' equity) shows how much profit a company earns on the funds invested by its owners. Option B is about liquidity, and C and D are not measured by ROE."}},{"itemId":"df881b26-ba8a-5a9a-b08a-2c17854cba7e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1dba657e-6edb-5f08-8d92-8e43b18ab8b6","sourceKey":"bank:BUA216:F101-119","parentItemId":null,"revision":1,"payload":{"prompt":"A low quick ratio suggests:","options":["Robust liquidity reserves","Challenges meeting short-term debts","High earnings potential","Minimal leverage"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The quick ratio compares the most liquid assets (current assets minus inventory) with current liabilities, so a low figure warns that the firm may struggle to pay short-term debts. Option A is the opposite, and C and D are not measured by liquidity ratios."}},{"itemId":"b04e22cd-9815-51b9-b498-7198cbc836c5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"25d2b8c5-7989-5c9d-9b8d-3ae28f9f951c","sourceKey":"bank:BUA216:F101-120","parentItemId":null,"revision":1,"payload":{"prompt":"The gross profit margin is calculated as:","options":["Gross profit / Sales revenue","Net profit / Sales revenue","Sales revenue / Gross profit","Net profit / Equity"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The gross profit margin = Gross profit / Sales revenue, showing what share of each naira of sales is left after cost of sales. Option B is the net profit margin, and C turns the ratio upside down."}},{"itemId":"bafd39a6-a1aa-59b8-8f24-3b6f8d986892","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6b00cbcd-2d78-5313-8795-287853628f4e","sourceKey":"bank:BUA216:F101-121","parentItemId":null,"revision":1,"payload":{"prompt":"The inventory turnover ratio measures:","options":["Speed of inventory sales","Overall profit levels","Cash flow readiness","Debt repayment capacity"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Inventory turnover (cost of sales / average inventory) shows how quickly a firm sells and replaces its stock, so it is an activity ratio. Options B, C and D are measured by profitability, liquidity and leverage ratios."}},{"itemId":"620f4d07-2b1e-590c-adf1-0b718915deae","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"619b4089-42ab-59c9-99ce-dedd9c5d8da6","sourceKey":"bank:BUA216:F101-122","parentItemId":null,"revision":1,"payload":{"prompt":"A high price-to-earnings (P/E) ratio indicates:","options":["Potential stock overvaluation","Stock undervaluation signal","Low company profitability","Excessive borrowing"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"A high P/E means investors are paying a lot for each naira of earnings, which can be a sign that the share is overvalued (it may also reflect strong growth expectations, which is why A says 'potential'). Option B is the opposite reading, and C and D are not measured by the P/E ratio."}},{"itemId":"e495284d-b27f-5aee-8c70-986a4863ad67","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"12610972-a5bf-5188-9c8c-00bb84b6fd03","sourceKey":"bank:BUA216:F101-123","parentItemId":null,"revision":1,"payload":{"prompt":"The debt ratio is calculated as:","options":["Total debt / Total assets","Total assets / Total debt","Net income / Total debt","Equity / Total debt"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The debt ratio = Total debt / Total assets, showing what share of the firm's assets is financed by borrowing. Option B turns the ratio upside down, and D is the inverse of the debt-to-equity ratio."}},{"itemId":"0969d566-97aa-5b02-abef-ccea65d9e5cb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7c6467a2-f89b-5d73-a5ce-d2a57de4ec82","sourceKey":"bank:BUA216:F101-124","parentItemId":null,"revision":1,"payload":{"prompt":"The net profit margin measures:","options":["Operational cost efficiency","Profit after all costs","Liquidity position","Stock rotation speed"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Net profit margin = Net profit / Sales, so it shows how much profit remains from each naira of sales after all expenses, including interest and tax. Option C is measured by liquidity ratios and D by inventory turnover."}},{"itemId":"6f83e2ad-32e3-5d62-8dd5-6453eda4463e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb6e708b-95e0-5542-bdf9-00c904b98085","sourceKey":"bank:BUA216:F101-125","parentItemId":null,"revision":1,"payload":{"prompt":"A high accounts receivable turnover ratio indicates:","options":["Delayed payment collection","Swift receivable recovery","Excessive debt levels","Reduced sales volume"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Receivables turnover (credit sales / average receivables) is high when customers pay quickly, so the firm collects its debts fast. Option A describes a low turnover, and C and D are not shown by this ratio."}},{"itemId":"d8df89d7-e4f0-563c-a950-30302127afd0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"584a6341-8c0e-51b4-85ca-637e605a3c60","sourceKey":"bank:BUA216:F101-126","parentItemId":null,"revision":1,"payload":{"prompt":"The quick ratio excludes:","options":["Cash on hand","Inventory from calculations","Receivables due soon","Short-term obligations"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The quick (acid-test) ratio = (Current assets - Inventory) / Current liabilities, so inventory is left out because it is the hardest current asset to turn into cash quickly. Cash (A) and receivables (C) are included, and short-term obligations (D) are the denominator."}},{"itemId":"c760c01e-9467-5d6f-acd3-2fac17aaa7e8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4866ec5a-26b5-50eb-b84b-04d72d0ded62","sourceKey":"bank:BUA216:F101-127","parentItemId":null,"revision":1,"payload":{"prompt":"Financial ratios are useful for:","options":["Tracking performance trends","Engineering new products","Staffing decisions","Advertising plans"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Ratios let managers and investors compare a firm's results over several years or against other firms, showing trends in performance. Options B, C and D are product, staffing and marketing decisions that ratios do not directly guide."}},{"itemId":"b7b820ef-5fa0-578b-a7b6-bb3ab1c3ba71","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"850c3055-e93d-5854-aa53-a6083e4ba067","sourceKey":"bank:BUA216:F101-143","parentItemId":null,"revision":1,"payload":{"prompt":"What is finance primarily concerned with?","options":["Marketing strategies","Management of money and investments","Product pricing","Employee welfare"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Finance deals with managing money: raising funds, investing them and managing risk and return. Marketing (A), pricing (C) and employee welfare (D) belong to other business functions."}},{"itemId":"938a0a4f-37f0-56ef-974d-dd2bfeb9bbbe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e93ca358-7b1b-5627-bf60-3d832bd8e1d0","sourceKey":"bank:BUA216:F101-144","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a long-term source of finance?","options":["Trade credit","Commercial paper","Bank overdraft","Debenture"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"A debenture is a long-term loan raised by a company from the public, often lasting many years, so it is a long-term source of finance. Trade credit (A) and commercial paper (B) are short-term, and a bank overdraft (C) is repayable on demand, so it is also short-term."}},{"itemId":"61d55076-8cf2-56f9-a039-4a422d107fff","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"59e48411-e7ca-5610-8a3d-7a1b4b4b8544","sourceKey":"bank:BUA216:F101-145","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main goal of financial management?","options":["Maximizing shareholder wealth","Reducing taxes","Increasing market share","Minimizing costs"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Financial management aims to maximise shareholder wealth, which means increasing the value of the owners' investment over the long run. Reducing taxes (B), increasing market share (C) and minimising costs (D) can help, but they are means to an end rather than the main goal."}},{"itemId":"558066d5-ccf7-50f0-88fd-4f91eb42ba4b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c470d75-a406-5925-9b11-bd9470b0fe5a","sourceKey":"bank:BUA216:F101-146","parentItemId":null,"revision":1,"payload":{"prompt":"What is the capital market used for?","options":["Short-term borrowing","Long-term borrowing and lending","Currency exchange","Day-to-day business expenses"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The capital market is where long-term funds are borrowed and lent, through instruments such as shares, bonds and debentures. Option A describes the money market, and C describes the foreign exchange market."}},{"itemId":"09e1d0c9-432f-5198-8efe-355c6b065881","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d372ee2-2b37-50fd-bf61-ab525dfee736","sourceKey":"bank:BUA216:F101-148","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a financial institution?","options":["Commercial banks","Stock exchange","Insurance companies","Supermarkets"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Financial institutions deal in money and financial services, such as banks, insurance companies and stock exchanges. A supermarket sells goods to consumers, so it is not a financial institution."}},{"itemId":"0bafdb25-4125-5dc3-a7e2-948f8e691ee7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"09a69817-61ff-527a-be83-616f595a9797","sourceKey":"bank:BUA216:F101-149","parentItemId":null,"revision":1,"payload":{"prompt":"Liquidity refers to:","options":["The profitability of a company","The ease of converting assets to cash","The total liabilities of a company","The long-term growth of a company"],"correctOption":1,"section":"Working Capital Management","explanation":"Liquidity is how easily and quickly an asset can be turned into cash without losing much value. Profitability (A), total liabilities (C) and growth (D) are different measures of a business."}},{"itemId":"a926336d-3d7a-5462-8de3-0b5c6feaf7b1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"312836ad-7f84-5166-8c2f-5e3289a063cb","sourceKey":"bank:BUA216:F101-150","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money concept implies:","options":["A dollar today is worth less than a dollar tomorrow","A dollar today is worth more than a dollar tomorrow","Money has no value over time","Money value remains constant"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Money today is worth more than the same amount tomorrow because it can be invested to earn interest. Option A reverses this, and C and D ignore the time value of money."}},{"itemId":"b8a4ab9a-3bfe-557c-8050-8f922a1b4c12","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70e79073-0931-567d-acb1-873f52e85f61","sourceKey":"bank:BUA216:F101-151","parentItemId":null,"revision":1,"payload":{"prompt":"What is another name for equity financing?","options":["Loan capital","Ownership capital","Fixed capital","Debt capital"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Equity finance comes from the owners, for example by issuing shares, so it is also called ownership capital. Loan capital (A) and debt capital (D) are borrowed funds, which are the opposite of equity."}},{"itemId":"c23bb2f5-d676-560e-adff-fbb3b025262f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ffa3b6ed-416c-5db4-937d-a3a76f9d3f01","sourceKey":"bank:BUA216:F101-152","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial ratio measures a company's ability to pay short-term liabilities?","options":["Profit margin ratio","Quick ratio","Debt-to-equity ratio","Inventory turnover"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The quick (acid-test) ratio compares liquid assets with current liabilities, so it measures the ability to pay short-term debts. Profit margin (A) measures profitability, debt-to-equity (C) measures leverage, and inventory turnover (D) measures activity."}},{"itemId":"c9a1c4ac-c2fc-52cc-8b47-17d116e875b4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a19d81f-0809-5f73-bc51-2c05f960049c","sourceKey":"bank:BUA216:F101-153","parentItemId":null,"revision":1,"payload":{"prompt":"What is a dividend?","options":["A company's net profit","Interest paid on debt","A portion of a company's profit distributed to shareholders","An expense on the balance sheet"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A dividend is the part of a company's profit paid out to its shareholders as a return on their investment. Option A is total profit, and B describes interest paid to lenders, not owners."}},{"itemId":"96c944a9-2e43-5c9c-8c56-15c2a648e683","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ccea1e6-8c46-5bc0-b614-80266b9a226f","sourceKey":"bank:BUA216:F101-154","parentItemId":null,"revision":1,"payload":{"prompt":"Which market deals with the buying and selling of newly issued securities?","options":["Primary market","Secondary market","Tertiary market","Capital market"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Newly issued securities are first sold in the primary market, where the money goes to the issuing company. The secondary market (B) trades existing securities, and while the capital market (D) contains a primary segment, the term \"primary market\" is the precise answer."}},{"itemId":"7c3ce7d1-7aaa-5d7f-a991-4f0f076aefb6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"85b8de55-f027-5357-896d-ed752c6da8dc","sourceKey":"bank:BUA216:F101-155","parentItemId":null,"revision":1,"payload":{"prompt":"The cost of capital refers to:","options":["The cost of operating a business","The cost of obtaining funds","The cost of goods sold","The cost of management"],"correctOption":1,"section":"Net Present Value","explanation":"The cost of capital is the return a firm must pay to obtain funds, such as interest on debt or the return shareholders expect. Option A is general operating cost, and C is the cost of the goods a firm sells."}},{"itemId":"fb1488d7-6126-5933-bb2a-4e4e7df73421","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cf2e60e5-247a-5e6e-bf0c-5443bff97c2f","sourceKey":"bank:BUA216:F101-156","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a financial asset?","options":["Machinery","Cash","Inventory","Accounts payable"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A financial asset is a claim to money, such as cash, shares or bonds. Machinery (A) and inventory (C) are physical assets, and accounts payable (D) is a liability, not an asset."}},{"itemId":"f5827a51-da05-55cf-95d7-62be4b3167a8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e2e39135-e575-530d-ae22-4f09fa8d2b47","sourceKey":"bank:BUA216:F101-158","parentItemId":null,"revision":1,"payload":{"prompt":"What does ROI stand for?","options":["Return on Interest","Rate of Investment","Return on Investment","Return of Income"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"ROI stands for Return on Investment, which measures the gain from an investment relative to its cost. Options A, B and D are not the correct expansion of the abbreviation."}},{"itemId":"df93a625-59e9-50bb-b9af-f859cd2c97b3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"543508cd-a883-5584-9f26-519d3b3617ff","sourceKey":"bank:BUA216:F101-159","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a component of working capital?","options":["Long-term debt","Fixed assets","Current liabilities","Share capital"],"correctOption":2,"section":"Working Capital Management","explanation":"Working capital = Current assets - Current liabilities, so current liabilities are a component of it. Long-term debt (A), fixed assets (B) and share capital (D) are long-term items, not part of working capital."}},{"itemId":"85c14bef-c1d2-58a5-965a-1fc10376c7c8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2c19945d-3e93-57b0-aa04-a1c31e6d61aa","sourceKey":"bank:BUA216:F101-160","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial market deals with short-term securities?","options":["Capital market","Money market","Commodity market","Forex market"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The money market is where short-term securities, usually maturing within a year, such as treasury bills and commercial paper, are traded. The capital market (A) deals in long-term securities, the commodity market (C) trades physical goods, and the forex market (D) trades currencies."}},{"itemId":"29c15770-ea29-5e6e-b2bb-c4220c876d0b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"08be2a89-3244-51c9-ba7f-4d1a67db3f4f","sourceKey":"bank:BUA216:F101-161","parentItemId":null,"revision":1,"payload":{"prompt":"Capital budgeting is primarily concerned with:","options":["Managing daily expenses","Making long-term investment decisions","Setting up marketing plans","Managing human resources"],"correctOption":1,"section":"Net Present Value","explanation":"Capital budgeting is the process of evaluating and choosing long-term investments, such as new machinery or a new factory, that will bring returns over many years. Managing daily expenses (A) is working capital management, and C and D belong to marketing and human resources."}},{"itemId":"9bfc55a1-56f2-51f7-8ef6-5569d10b54d4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"933432ab-2ac9-5087-b3d9-f6ac06cc4d7f","sourceKey":"bank:BUA216:F101-163","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following represents ownership in a company?","options":["Bond","Stock","Loan","Certificate of deposit"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A stock (share) makes the holder a part-owner of the company, with a claim on its profits and assets. Bonds (A), loans (C) and certificates of deposit (D) are all debt instruments, so the holder is a lender to the issuer, not an owner."}},{"itemId":"de8da2bb-3e51-55c2-a6a4-fbf2e2f8b84a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"445ee6ae-017a-55f1-94c1-8eb18fbb1cbd","sourceKey":"bank:BUA216:F101-165","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an example of current assets?","options":["Inventory","Accounts receivable","Land","Cash"],"correctOption":2,"section":"Working Capital Management","explanation":"Land is a fixed (non-current) asset because it is held for long-term use and is not expected to be turned into cash within a year. Inventory (A), accounts receivable (B) and cash (D) are all current assets, since they are cash or will become cash within the normal operating cycle."}},{"itemId":"a0bba7af-9299-5645-abcc-9474ee4fc74a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2d75cf0-688b-5b59-99bc-338f84e9b742","sourceKey":"bank:BUA216:F101-166","parentItemId":null,"revision":1,"payload":{"prompt":"What does the term \"leverage\" refer to in finance?","options":["Using equity only for financing","Using debt to finance investments","Reducing operational expenses","Increasing dividends"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Leverage means using borrowed money (debt) to finance investments, with the aim of boosting returns to the owners. Option A is the opposite, since using equity only means there is no leverage at all. Cutting expenses (C) or raising dividends (D) have nothing to do with how the business is financed."}},{"itemId":"5bba8e13-fd07-5c75-80bd-5797382881c6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"208afcc5-70e7-5ba3-9a74-839252921f39","sourceKey":"bank:BUA216:F101-169","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is not a source of short-term finance?","options":["Bank overdraft","Trade credit","Commercial paper","Bonds"],"correctOption":3,"section":"Working Capital Management","explanation":"Bonds are long-term debt, usually running for many years, so they are not a source of short-term finance. Bank overdrafts (A), trade credit (B) and commercial paper (C) are all repaid within a year, which is why they are classed as short-term finance."}},{"itemId":"1968bb57-690f-55e0-b4ef-fd255cd984fd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4ad77813-57f7-5d7d-b32f-d145db01a5e7","sourceKey":"bank:BUA216:F101-170","parentItemId":null,"revision":1,"payload":{"prompt":"The process of determining the present value of future cash flows is called:","options":["Compounding","Discounting","Budgeting","Hedging"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Discounting converts a future amount back into its value today by removing the interest it could have earned, for example PV = FV / (1 + r)^n. Compounding (A) works the other way, growing a present amount into a future value. Budgeting (C) and hedging (D) are unrelated activities."}},{"itemId":"97e36711-a5bb-53b5-8ed3-cf702e01d3f5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"02fdcb62-47af-5619-b082-200dbcfe60c4","sourceKey":"bank:BUA216:F101-172","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is:","options":["A collection of financial statements","A combination of financial investments","A cash management strategy","A tax-saving plan"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"A portfolio is a collection or combination of investments, such as shares and bonds, held by one investor. Option A confuses it with a set of financial statements, while C and D describe a cash management strategy and a tax plan, not a group of investments."}},{"itemId":"447fdf48-f70b-597f-bb71-43d05ffd70fb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8d8c8e9d-e1a5-5cf6-983d-5ce5eb688e6e","sourceKey":"bank:BUA216:F101-173","parentItemId":null,"revision":1,"payload":{"prompt":"What is the major role of a stock exchange?","options":["Lend money to businesses","Facilitate the trading of securities","Manage national debts","Control interest rates"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A stock exchange provides an organised market where existing securities such as shares and bonds are bought and sold. It does not lend money to businesses (A); that is what banks do. Managing national debt (C) and controlling interest rates (D) are central bank and government roles."}},{"itemId":"8eefae87-151a-5bc2-a3e4-dea0f03fb8d4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"68e4cf53-942a-5607-9fd9-f412e746c35b","sourceKey":"bank:BUA216:F101-174","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a capital budgeting technique?","options":["Internal Rate of Return (IRR)","Debt-to-equity ratio","Current ratio","Cash conversion cycle"],"correctOption":0,"section":"Net Present Value","explanation":"Internal Rate of Return (IRR) is used to evaluate long-term investment projects, which makes it a capital budgeting technique. The debt-to-equity ratio (B) and current ratio (C) are financial ratios, and the cash conversion cycle (D) is a working capital measure, so none of them are used to appraise projects."}},{"itemId":"4b7c4d98-a1e8-5184-9938-0ed4a97aad70","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8139da6a-0dcd-537a-a0aa-9f9fb43c269e","sourceKey":"bank:BUA216:F101-176","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main objective of a business?","options":["Maximizing profits","Customer satisfaction","Employee welfare","Reducing liabilities"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Making profit is the basic reason most businesses exist, so profit maximisation is the main objective among these options. Customer satisfaction (B) and employee welfare (C) are important, but they support the business in earning profit rather than being its main goal. Reducing liabilities (D) is a financial management choice, not the overall objective."}},{"itemId":"d726935f-d300-5a3e-8e46-fe8e5043f0c0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"eaf86629-1cec-514b-8219-0ec3add442fe","sourceKey":"bank:BUA216:F101-177","parentItemId":null,"revision":1,"payload":{"prompt":"Market risk is also known as:","options":["Diversifiable risk","Systematic risk","Unsystematic risk","Credit risk"],"correctOption":1,"section":"Capital Asset Pricing Model and Portfolio Theory","explanation":"Market risk is the risk that affects the whole market, for example from inflation or interest rate changes, and it is also called systematic risk. It cannot be removed by diversification, so options A and C (diversifiable or unsystematic risk) describe the opposite type. Credit risk (D) is the risk that a borrower fails to repay."}},{"itemId":"ce5898d9-1680-51e7-96df-4185ead276e3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e368b8d9-b929-5ee5-98e2-f20ba78d6fb3","sourceKey":"bank:BUA216:F101-179","parentItemId":null,"revision":1,"payload":{"prompt":"Current liabilities are obligations that are expected to be settled within:","options":["6 months","1 year","2 years","5 years"],"correctOption":1,"section":"Working Capital Management","explanation":"Current liabilities are debts due for settlement within one year (or within the normal operating cycle), such as trade creditors and overdrafts. Six months (A) is too short a cut-off, while two or five years (C and D) would cover long-term liabilities."}},{"itemId":"a7a99f64-a4fe-5c7d-b169-40ed8f7313d2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3f47e010-fe68-596b-8fbd-4e61b1d0719b","sourceKey":"bank:BUA216:F101-182","parentItemId":null,"revision":1,"payload":{"prompt":"A financial ratio that measures profitability is:","options":["Debt ratio","Current ratio","Return on equity (ROE)","Quick ratio"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Return on equity (ROE) measures how much profit a company earns for each naira of shareholders' funds, so it is a profitability ratio. The debt ratio (A) is a leverage ratio, while the current ratio (B) and quick ratio (D) measure liquidity."}},{"itemId":"edb707fb-8289-5660-a6eb-381dfe0ad1fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f9b66259-e596-53ab-811f-4c9541780408","sourceKey":"bank:BUA216:F101-184","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of equity financing?","options":["No obligation to repay","Interest payments are tax-deductible","Reduces ownership control","Short-term funding"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Equity finance does not have to be repaid, and dividends are not a fixed legal obligation, which reduces the pressure on the firm. Tax-deductible interest (B) is an advantage of debt, not equity. Diluting ownership control (C) is actually a disadvantage of issuing shares, and equity is long-term, not short-term funding (D)."}},{"itemId":"21728b1d-8324-5db8-bbaf-369375c112b6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d881c88-59f4-5b21-b51e-8e7f37e3b65a","sourceKey":"bank:BUA216:F101-186","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not part of working capital?","options":["Cash","Inventory","Fixed assets","Accounts receivable"],"correctOption":2,"section":"Working Capital Management","explanation":"Working capital is current assets minus current liabilities, so it covers short-term items like cash, inventory and receivables. Fixed assets such as buildings and machinery are long-term, so they are not part of working capital. Options A, B and D are all current assets."}},{"itemId":"ff68fca2-5210-5ed8-a595-6e360dd6de20","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2ba73415-ad10-5cf1-9b93-6a63f1cb5db5","sourceKey":"bank:BUA216:F101-187","parentItemId":null,"revision":1,"payload":{"prompt":"A debt instrument that pays interest and is redeemable at a future date is a:","options":["Bond","Stock","Mutual fund","Derivative"],"correctOption":0,"section":"Bonds, Interest Rates, Forwards, Futures and Options","explanation":"A bond is a debt instrument: the issuer borrows money, pays interest over the life of the bond and repays the principal on the redemption date. Stock (B) represents ownership, not debt. A mutual fund (C) is a pooled investment, and a derivative (D) gets its value from another asset."}},{"itemId":"e47e4d3e-b01b-57a4-a0a3-4870a9d27b6e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"00ff364c-05d8-5eba-a3d9-c09a9034b943","sourceKey":"bank:BUA216:F101-188","parentItemId":null,"revision":1,"payload":{"prompt":"An increase in working capital usually indicates:","options":["Higher liquidity","Higher debt levels","Lower profitability","Lower liquidity"],"correctOption":0,"section":"Working Capital Management","explanation":"Working capital is current assets minus current liabilities, so a rise usually means the business has more short-term resources to cover its short-term debts, which is higher liquidity. Option D says the opposite. Working capital does not directly measure debt levels (B) or profitability (C)."}},{"itemId":"8baa01d3-e96d-5dbe-8984-176f9d8b12e3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"77b22e45-89f8-5f33-800c-5632d6326f8d","sourceKey":"bank:BUA216:F101-189","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary role of a financial manager?","options":["Manage marketing activities","Ensure customer satisfaction","Manage a firm's finances and maximize value","Prepare legal documents"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A financial manager looks after the firm's finances, deciding how funds are raised, invested and distributed so as to maximise the value of the firm. Marketing (A), customer satisfaction (B) and legal documents (D) belong to other departments."}},{"itemId":"893b7c60-7866-5048-b6d4-353b372a93cd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c380c029-96fa-51b0-908b-402f5101b972","sourceKey":"bank:BUA216:F101-190","parentItemId":null,"revision":1,"payload":{"prompt":"Find the present value of N7,500 promised to be paid in 5 years time. Interest is compounded continuously at 20%.","options":["N2,759","N6,500","N7,900","N5,800"],"correctOption":0,"section":"Mathematics of Finance","explanation":"With continuous compounding, PV = FV x e^(-rt). Here PV = 7,500 x e^(-0.20 x 5) = 7,500 x e^(-1) = 7,500 x 0.3679 = N2,759. Options B, C and D are far too high; discounting over 5 years at 20% must reduce the amount sharply, and C is even more than the future amount."}},{"itemId":"5c5e8a22-500c-5cfb-861d-06c6660f6cbe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5d4bdaaf-f7fd-5fc1-84f7-d246018ad25c","sourceKey":"bank:BUA216:F101-191","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take N5,000 invested now to accumulate to N30,000 if the interest rate is 20% per annum compounded annually?","options":["10 years","11 years","9 years","8 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Solve 5,000 x (1.20)^n = 30,000, so (1.20)^n = 6 and n = ln 6 / ln 1.20 = 9.83 years, which is 10 years to the nearest year. Nine years (C) is not enough, since 5,000 x (1.20)^9 = N25,799, short of N30,000. Eleven years (B) and eight years (D) are further from the exact figure."}},{"itemId":"ce65f7a8-7aad-54da-8afb-bc0720d46f35","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f1e4b25-9d55-5e55-a53c-734de9436b88","sourceKey":"bank:BUA216:F101-192","parentItemId":null,"revision":1,"payload":{"prompt":"What will be the total amount receivable from an investment of N800,000 made for 4 and half years at 12% compounded annual interest?","options":["N1,332,205","N1,258,815","N1,232,000","N896,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Compound value = 800,000 x (1.12)^4.5 = 800,000 x 1.6653 = N1,332,205. Option D, N896,000, is just one year of 12% interest added (800,000 x 1.12). Option C (N1,232,000) is simple interest, 800,000 x (1 + 0.12 x 4.5), and option B does not match the compounding of 12% for 4.5 years."}},{"itemId":"cbc7ac69-6ab6-5a9f-97c2-3d4cee37a727","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e069c3a1-3500-538d-ad99-c432e543721b","sourceKey":"bank:BUA216:F101-193","parentItemId":null,"revision":1,"payload":{"prompt":"Kenny wishes to determine how much depositing N15,000 at the end of each year will amount to in the next five years. If the annual interest rate is 12%, how much will be in his account?","options":["N26,435","N106,728","N95,293","N54,072"],"correctOption":2,"section":"Mathematics of Finance","explanation":"This is the future value of an ordinary annuity: FV = 15,000 x [(1.12)^5 - 1] / 0.12 = 15,000 x 6.3528 = N95,293. Option B, N106,728, is what you get if each deposit is made at the start of the year (an annuity due). Option A is the future value of just one N15,000 deposit, and D is the present value of the five deposits, not their future value."}},{"itemId":"8e2a5ec4-0799-53bb-91c4-d3a75d9e8586","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9eb27c83-f40f-5099-9816-4e1dabcdebcd","sourceKey":"bank:BUA216:F101-194","parentItemId":null,"revision":1,"payload":{"prompt":"Goodluck Plc. Has been offered an opportunity to receive N350,000 in 6 years time from now. If the firm can earn 10% on its money, how much is it worth today?","options":["N197,566","N620,046","N177,566","N217,322"],"correctOption":0,"section":"Mathematics of Finance","explanation":"PV = 350,000 / (1.10)^6 = 350,000 / 1.7716 = N197,566. Option B, N620,046, is the future value, which compounds forward instead of discounting back. Options C and D are close in size but do not match the correct discount factor."}},{"itemId":"e5ac0c3b-2e9a-51dc-85a0-b0bb91c2aa9e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"42c12930-1938-53e8-83ff-8176d41f3848","sourceKey":"bank:BUA216:F101-195","parentItemId":null,"revision":1,"payload":{"prompt":"An account holder deposits N8,500 in savings account paying 8% interest compounded quarterly. How much will be in the account at the end of the five years.","options":["N12,600","N12,631","N12,489","N39,618"],"correctOption":1,"section":"Mathematics of Finance","explanation":"With quarterly compounding, use a rate of 8% / 4 = 2% per quarter for 5 x 4 = 20 quarters. FV = 8,500 x (1.02)^20 = 8,500 x 1.4859 = N12,631. Option C uses annual instead of quarterly compounding, giving 8,500 x (1.08)^5 = N12,489. Option A (N12,600) and D (N39,618) do not match the calculation."}},{"itemId":"c39bcf1e-a19c-5ff2-b7a7-3c24d8387b50","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9783166e-0964-5ac4-b404-f42fa012f893","sourceKey":"bank:BUA216:F101-196","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nWhat is the expected value of Security X","options":["N25,000","N31,000","N28,500","N31,500"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Expected value = sum of each return x its probability: E(X) = 27,000(0.5) + 30,000(0.2) + 35,000(0.1) + 40,000(0.2) = 13,500 + 6,000 + 3,500 + 8,000 = N31,000. Option D, N31,500, comes from an arithmetic slip, and N25,000 (A) is too low, since every return of X is at least N27,000."}},{"itemId":"b55c60ac-b5ee-5db3-8a74-1c1aca8a9b99","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"712f2202-4eef-54bf-a232-d2dca9442a50","sourceKey":"bank:BUA216:F101-197","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe variance of Security Y is","options":["N23,250,000","N27,500,000","N23,500,000","none of the above"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Variance = sum of p x (return - expected value)^2. With E(Y) = N25,500: 0.1(15,000-25,500)^2 + 0.3(22,000-25,500)^2 + 0.2(27,000-25,500)^2 + 0.4(30,000-25,500)^2 = 11,025,000 + 3,675,000 + 450,000 + 8,100,000 = 23,250,000. Options B and C are close but do not match this total, so D (none of the above) is also wrong."}},{"itemId":"6b0d18dc-e268-523b-a5c6-b9c17fd9c3d6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ef03a247-8c3c-50a8-af4e-245cbb32a1be","sourceKey":"bank:BUA216:F101-198","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe standard deviation of Security X is","options":["N5,099","N4,822","N5,220","none of the above"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"First find the variance of X around E(X) = N31,000: 0.5(-4,000)^2 + 0.2(-1,000)^2 + 0.1(4,000)^2 + 0.2(9,000)^2 = 8,000,000 + 200,000 + 1,600,000 + 16,200,000 = 26,000,000. Standard deviation = square root of 26,000,000 = N5,099. Option B (N4,822) is the standard deviation of Y and option C (N5,220) is that of Z."}},{"itemId":"eaabc292-6ec2-5066-98d4-6b23a9e82006","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4fdf6730-8fc9-5fa0-b760-95b37061ae2e","sourceKey":"bank:BUA216:F101-199","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security Z, to the nearest whole percent, is","options":["16%","18%","20%","19%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Coefficient of variation = standard deviation / expected value. For Z, E(Z) = N25,500 and variance = 27,250,000, so SD = N5,220 and CV = 5,220 / 25,500 = 0.205, about 20%. Options A (16%) and D (19%) are roughly the CVs of X and Y, not Z."}},{"itemId":"d7a1b635-a919-5b53-8653-092d3fd250c3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"27d8fdc1-545e-543e-a7b8-78b6f95d3507","sourceKey":"bank:BUA216:F101-200","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security Y is","options":["16%","18%","20%","19%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"For Y, E(Y) = N25,500 and variance = 23,250,000, so SD = square root of 23,250,000 = N4,822. CV = 4,822 / 25,500 = 0.189, which is about 19%. Option B (18%) is slightly too low, and A (16%) belongs to Security X."}},{"itemId":"33658e4b-26e2-5596-9c3e-4d1e44011c99","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"db6a5f76-dd93-5c5f-a53f-5422c731b555","sourceKey":"bank:BUA216:F101-201","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security X is","options":["16%","18%","20%","19%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"For X, E(X) = N31,000 and SD = square root of 26,000,000 = N5,099. CV = 5,099 / 31,000 = 0.164, about 16%. Options C (20%) and D (19%) are roughly the CVs of Z and Y."}},{"itemId":"5a2b3b0e-5d08-5554-ad61-8ddf65cf6ad2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d473815e-8aab-526d-890b-327e4133fc6a","sourceKey":"bank:BUA216:F101-202","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nIf James is a risk averse investor, which security would you recommend to him (use the coefficient of variation as the measure of risk)","options":["Security X","Security Y","Security A","Security Z"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Because the three securities have different expected returns, risk should be compared using the coefficient of variation, which is risk per naira of expected return. X has the lowest CV (about 16%, against about 19% for Y and 20% for Z) and also the highest expected return, N31,000, so a risk-averse investor should pick X. Option B (Security Y) has a slightly lower standard deviation, but it carries more risk for each naira it is expected to earn. Option C (Security A) is not one of the securities in the table."}},{"itemId":"72f8c52a-126e-5d6b-9172-7eccf4b45c78","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"838f3903-28f3-50e1-8656-c8dd64b5996f","sourceKey":"bank:BUA216:F101-203","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] DATA (N000): Credit Sales 40,000; Average Debtors 10,000; Profit before Tax 6,000; Total Assets 54,000; Interest on Loan 8,000; Stock 3,000; Cash 7,600; Trade Creditors 3,900; Tax rate 35%; Shareholder funds 160,000; Long term debt 10,000\nThe Return on Shareholder equity (profit after tax / shareholder funds) to the nearest whole number is","options":["2%","3%","4%","5%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Return on shareholders' equity here is profit after tax divided by shareholders' funds. Profit after tax = 6,000 x (1 - 0.35) = 3,900, so the return = 3,900 / 160,000 = 2.44%, which is 2% to the nearest whole number. Option C (4%) comes from using profit before tax (6,000 / 160,000 = 3.75%), which ignores the tax the firm must pay."}},{"itemId":"69f859fa-be7f-5c66-80b3-9aaae00a1073","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4a8125f9-2506-5bce-bba9-f3a99daf58d4","sourceKey":"bank:BUA216:F101-204","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] DATA (N000): Credit Sales 40,000; Average Debtors 10,000; Profit before Tax 6,000; Total Assets 54,000; Interest on Loan 8,000; Stock 3,000; Cash 7,600; Trade Creditors 3,900; Tax rate 35%; Shareholder funds 160,000; Long term debt 10,000\nThe Return on total assets (profit before interest and tax / total assets) to the nearest whole percent is","options":["25%","26%","27%","28%"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Return on total assets here compares profit before interest and tax with total assets. Profit before interest and tax = 6,000 + 8,000 = 14,000, so the return = 14,000 / 54,000 = 25.9%, which is 26% to the nearest whole percent. Option A (25%) rounds down incorrectly, and C and D overstate the return."}},{"itemId":"396a1eee-ca22-5ea8-8b75-658eb4f7d909","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8ec53e58-277c-5d85-9c38-77a67b43d4cc","sourceKey":"bank:BUA216:F101-205","parentItemId":null,"revision":1,"payload":{"prompt":"Long-term solvency ratio is also known as","options":["Efficiency ratio.","Stability ratio","Working capital ratio","Actual growth ratio"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Long-term solvency ratios show whether a firm can survive and meet its long-term debts, so they are also called stability ratios. Efficiency ratios (A) measure how well assets are used, and the working capital ratio (C) is a short-term liquidity measure. Option D is not a standard ratio group."}},{"itemId":"bb99f8eb-bb33-547a-9e0d-a637befdf299","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"99c072b4-3665-5eac-8230-859710e6f99d","sourceKey":"bank:BUA216:F101-206","parentItemId":null,"revision":1,"payload":{"prompt":"Financing decision is otherwise known as","options":["Capital budgeting decision","Capital rating decision","Capital project decision","Capital mix decision"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"The financing decision is about choosing the right combination of debt and equity to fund the firm, which is why it is called the capital mix (capital structure) decision. Capital budgeting (A) and capital project decisions (C) belong to the investment decision. Option B is not a recognised term."}},{"itemId":"d218fb8d-ab74-5a74-972e-b714006359d3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"adf927b6-1643-59e6-9223-e3455e45dd7b","sourceKey":"bank:BUA216:F101-207","parentItemId":null,"revision":1,"payload":{"prompt":"N950 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N2,109","N2,709","N2,700","N2,797"],"correctOption":3,"section":"Mathematics of Finance","explanation":"For continuous compounding, FV = PV x e^(rt) = 950 x e^(0.135 x 8) = 950 x e^1.08 = 950 x 2.9447 = N2,797. Options B (N2,709) and C (N2,700) understate the growth, and A (N2,109) is far too low."}},{"itemId":"c3aefab3-b8b4-5c51-bc6d-ccdb435f8af5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bfaf2ff4-38c9-5bd1-ad24-a3784cb3cb0d","sourceKey":"bank:BUA216:F101-208","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N290,000 received in 5 years' times, if such fund yields 15% per annum?","options":["N583,294","N144,181","N144,153","N145,153"],"correctOption":1,"section":"Mathematics of Finance","explanation":"PV = 290,000 / (1.15)^5 = 290,000 / 2.0114 = N144,181. Option A (N583,294) is the future value, which compounds forward instead of discounting. Options C and D are close but do not match the correct discount factor."}},{"itemId":"7176dc53-fad2-5cdd-aa56-1a9c9d127e52","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5c4bc08b-5bcd-558d-b09d-b3413fc783e4","sourceKey":"bank:BUA216:F101-209","parentItemId":null,"revision":1,"payload":{"prompt":"N9,000 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N26,109","N26,509","N26,000","N26,502"],"correctOption":3,"section":"Mathematics of Finance","explanation":"For continuous compounding, FV = PV x e^(rt) = 9,000 x e^(0.135 x 8) = 9,000 x e^1.08 = 9,000 x 2.9447 = N26,502. Options A, B and C are close but do not match this result."}},{"itemId":"173acfaa-7745-5a27-953a-2e8182350148","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9682118d-765d-553f-a1c3-949dadfaa69b","sourceKey":"bank:BUA216:F101-210","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a finance function.","options":["Financial control","Financial forensics","Financial analysis","Financial planning"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The finance function covers planning, raising, analysing and controlling a firm's funds, so financial control (A), financial analysis (C) and financial planning (D) are all finance functions. Financial forensics is the investigation of fraud and financial crime, which is a specialist audit and legal activity rather than a routine finance function."}},{"itemId":"e632a590-e020-5eab-9b7c-d4da8858e68a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"91cb1c9b-be15-56d1-98a6-f97233087b7a","sourceKey":"bank:BUA216:F101-212","parentItemId":null,"revision":1,"payload":{"prompt":"......... is a finance employee who manages the funds of an organization and undertakes financial management roles","options":["Financial manager","Financial analyst","Financial controller","Financial planner"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A financial manager is responsible for managing an organisation's funds, making the investment, financing and dividend decisions. A financial analyst (B) studies and reports on financial data, and a financial planner (D) usually advises individuals. A financial controller (C) mainly oversees accounting and reporting rather than the whole finance function."}},{"itemId":"eb4492f2-1820-5dd2-87e3-098969a9f067","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dc3f1caf-1dfb-5af3-9441-4d8aa211d68d","sourceKey":"bank:BUA216:F101-213","parentItemId":null,"revision":1,"payload":{"prompt":"......... is an example of money market instrument","options":["Preference share stock","Debenture stock","Certificate of deposit","Common stock"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"The money market deals in short-term funds, usually for a year or less, and a certificate of deposit is a short-term promissory note issued by a bank that pays interest to the holder. Preference shares (A), debenture stock (B) and common stock (D) are long-term securities traded in the capital market."}},{"itemId":"f78b9146-23d3-5953-a342-ba869fa4a2c6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"36d9c22e-f03e-5e10-9d07-2e983c270caf","sourceKey":"bank:BUA216:F101-214","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take an investment to triple itself if the interest rate is 15% per annum compounded annually?","options":["8 years","7 years","9 years","10 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Tripling means (1.15)^n = 3, so n = ln 3 / ln 1.15 = 1.0986 / 0.1398 = 7.86 years, which is 8 years to the nearest year. Seven years (B) is not enough, since (1.15)^7 = 2.66, and 9 or 10 years (C, D) are further from the exact figure."}},{"itemId":"ee07dc96-7238-5487-af85-aeeb956d749d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f64183f-494c-5476-8eb9-cf5407492673","sourceKey":"bank:BUA216:F101-215","parentItemId":null,"revision":1,"payload":{"prompt":"......... is an example of Capital market instrument","options":["Debenture stock","Banker acceptance","Bank deposit","Commercial paper"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"The capital market deals in long-term funds, and debenture stock is long-term debt, so it is a capital market instrument. Bankers' acceptances (B), bank deposits (C) and commercial paper (D) are short-term, so they belong to the money market."}},{"itemId":"94ce667b-2376-5042-bf8a-604375928b7d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a8769fb0-a46c-5fc3-ad17-a323d150c15f","sourceKey":"bank:BUA216:F101-216","parentItemId":null,"revision":1,"payload":{"prompt":"Dividend decision is otherwise known as","options":["Capital mix decision","Capital rationing decision","Capital budgeting decision","Profit allocation decision"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"The dividend decision is about how much of the profit is paid out to shareholders and how much is retained in the business, so it is also called the profit allocation decision. The capital mix decision (A) is the financing decision, while capital budgeting (C) and capital rationing (B) belong to the investment decision."}},{"itemId":"295ea580-3a88-52fb-acac-362e11d50d3d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"490a22e4-a3d9-5425-8a0f-a28c19fde0c2","sourceKey":"bank:BUA216:F101-217","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a reason why shareholders' wealth maximization objective is superior to the profit maximization objective.","options":["Wealth maximization objective allows shareholders to receive their reward on investment inform of dividend while profit maximization objective only allow that shareholders to earn profit.","Shareholders' wealth maximization considers the inherent risk associated with an investment project while profit maximization does not","Wealth maximization does not consider the timing of returns while profit maximization considers.","Wealth maximization objective considers the long term prospects of the firm while profit maximization objective only consider the short-term objectives of the firm."],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Wealth maximisation is preferred precisely because it does consider the timing of returns through the time value of money, while profit maximisation ignores it. Option C states the reverse, so it is not a valid reason. Options B and D are genuine advantages: wealth maximisation accounts for risk and for the firm's long-term prospects."}},{"itemId":"35f50591-92cf-542a-8691-f975fec5645b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3ebc5339-0ee6-56b7-927d-1e8786d99b5e","sourceKey":"bank:BUA216:F101-218","parentItemId":null,"revision":1,"payload":{"prompt":"......... can be described as a complex of institutions, instruments, rules and regulations that facilitates the mobilization and transfer of resources from savings surplus to deficit economic units","options":["Savings market","Economic system","Financial system","Savings system"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A financial system is the network of institutions, instruments, rules and regulations that moves funds from surplus (saving) units to deficit (borrowing) units. Options A and D describe only the saving side, and an economic system (B) is the wider way a whole economy is organised, not just its financial arrangements."}},{"itemId":"2696a164-4b2e-515e-9b59-e4f16cd2091a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"64edb9da-0ae3-550b-9c1e-9f75c0ac7f74","sourceKey":"bank:BUA216:F101-219","parentItemId":null,"revision":1,"payload":{"prompt":"Equity security is also known as","options":["Preference share stock","Ordinary share stock","Convertible security","Debenture stock"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Equity securities are ordinary shares, which give the holder ownership and a residual claim on the firm's profits and assets. Preference shares (A) and convertibles (C) are often treated as hybrids of debt and equity, and debenture stock (D) is pure debt."}},{"itemId":"695bc9ef-8313-55d4-b5c7-2a3d2b8023d9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"08042f5a-0196-59c7-b242-66237752ccac","sourceKey":"bank:BUA216:F101-220","parentItemId":null,"revision":1,"payload":{"prompt":"N7,000 is compounding continuously at 14.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N22,330","N22,309","N22,000","N21,329"],"correctOption":0,"section":"Mathematics of Finance","explanation":"For continuous compounding, FV = PV x e^(rt) = 7,000 x e^(0.145 x 8) = 7,000 x e^1.16 = 7,000 x 3.1899 = N22,330. Option B (N22,309) and D (N21,329) are close but do not match, and C (N22,000) is a rounded figure that does not match."}},{"itemId":"1d6de539-c458-5f51-badb-0c510b680df6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ce42606-c9d6-51d2-8230-0ed8ffed4743","sourceKey":"bank:BUA216:F101-221","parentItemId":null,"revision":1,"payload":{"prompt":"What annual interest rate, compounded quarterly and to the nearest whole percent, will make N5,000 accumulate to N20,000 in 4 years?","options":["24%","36%","37%","9%"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Solve 5,000 x (1 + r/4)^16 = 20,000, so (1 + r/4)^16 = 4 and 1 + r/4 = 4^(1/16) = 1.0905. The quarterly rate is about 9.05%, so the annual rate compounded quarterly is 4 x 9.05% = 36.2%, which is 36% to the nearest whole percent. Option D (9%) is only the rate per quarter, and 24% (A) would only turn N5,000 into about N12,700."}},{"itemId":"7dcc64ac-6a82-5e0b-bc9a-66cc5f6d4937","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b8506cff-4b47-5b4b-81b6-55a17f91e170","sourceKey":"bank:BUA216:F101-222","parentItemId":null,"revision":1,"payload":{"prompt":"......... Is the apex of money market regulatory agency.","options":["Central bank of Nigeria","Nigeria stock exchange","Issuing Houses","Securities and Exchange Commission"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"The Central Bank of Nigeria is the apex regulator of the money market and of banks. The Securities and Exchange Commission (D) is the apex regulator of the capital market, the Nigerian Stock Exchange (B) is a market operated for trading securities, and issuing houses (C) help companies raise capital."}},{"itemId":"15e81983-41cc-551f-be85-58b06979704e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8b696eaa-f36b-5797-a314-c277c3a32fcf","sourceKey":"bank:BUA216:F101-223","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N400,000 received in 5 years' time, if such fund yields 15% per annum?","options":["N198,153","N198,871","N193,149","N197,153"],"correctOption":1,"section":"Mathematics of Finance","explanation":"PV = 400,000 / (1.15)^5 = 400,000 / 2.0114 = N198,871. Options A, C and D are close in size but do not match the correct discount factor of 1 / 2.0114."}},{"itemId":"8832bbfb-d1af-550c-a9d1-c10d14d8b932","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a98ca150-39a3-5ec2-9eea-37dc1f8edde4","sourceKey":"bank:BUA216:F101-224","parentItemId":null,"revision":1,"payload":{"prompt":"The ideal minimum ratio for quick ratio is","options":["2.5:1","1:1","2:1","1.5:1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The quick (acid-test) ratio excludes inventory, and the commonly accepted ideal is 1:1, meaning quick assets just cover current liabilities. Option D (1.5:1) and A (2.5:1) are higher than the accepted norm, and 2:1 (C) is the standard for the current ratio, not the quick ratio."}},{"itemId":"a37e7943-dbea-5a17-8767-e6f830120a08","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cf039fc1-4dba-5a02-a5bd-2492e0e09896","sourceKey":"bank:BUA216:F101-225","parentItemId":null,"revision":1,"payload":{"prompt":"Investment decision is otherwise known as","options":["Capital project decision","Capital mix decision","Capital budgeting decision","Capital rationing decision"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"The investment decision is about choosing which long-term assets or projects to put money into, which is why it is called the capital budgeting decision. The capital mix decision (B) is the financing decision. Capital rationing (D) is only a special situation within investment, when funds are limited."}},{"itemId":"a4def0d7-bb38-548d-96c3-7aa374296391","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7858ec45-1f58-54f1-bf1d-312db94673cd","sourceKey":"bank:BUA216:F101-226","parentItemId":null,"revision":1,"payload":{"prompt":"The ideal minimum ratio for current ratio","options":["2.5:1","2:1","1.5:1","1:1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The commonly accepted ideal current ratio is 2:1, meaning current assets are twice current liabilities, giving a comfortable safety margin. Option D (1:1) is the norm for the quick ratio, while 1.5:1 and 2.5:1 (C and A) are not the standard benchmarks."}},{"itemId":"28b9d959-f1a5-54e7-8d76-2150a6dc8063","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b1763e49-0081-5922-be7b-c0ada9076ddf","sourceKey":"bank:BUA216:F101-227","parentItemId":null,"revision":1,"payload":{"prompt":"A financial market instrument sold by blue-chip companies to meet short-term financial obligations, and backed only by the issuing bank's or company's promise to pay the face value on the maturity date specified on the instrument, is called?","options":["Debenture","Corporate bond","Call money","Commercial paper"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Commercial paper is a short-term, unsecured promissory note issued by large, creditworthy (blue-chip) companies and backed only by the issuer's promise to pay the face value at maturity. Debentures (A) and corporate bonds (B) are long-term debt, and call money (C) is very short-term lending between banks."}},{"itemId":"a0479f1d-f2cd-569a-9192-60cd44fa4176","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4669d695-5081-5fb8-952b-f03b725e2b7d","sourceKey":"bank:BUA216:F101-228","parentItemId":null,"revision":1,"payload":{"prompt":"N770 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N2,207","N2,109","N2,267","N2,200"],"correctOption":2,"section":"Mathematics of Finance","explanation":"For continuous compounding, FV = PV x e^(rt) = 770 x e^(0.135 x 8) = 770 x e^1.08 = 770 x 2.9447 = N2,267. Option B (N2,109) understates the growth, and A and D do not match the calculation."}},{"itemId":"78306c7c-3fe4-5067-8275-dcf6f4607b2d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"82d100e1-98b9-551e-9d9c-8f81182194f5","sourceKey":"bank:BUA216:F101-229","parentItemId":null,"revision":1,"payload":{"prompt":"If I invest N120,000 at the end of each year for 'n' years at 10% interest per annum to accumulate N1,000,000, find 'n'.","options":["6.36yrs","6.20yrs","6.0yrs","7yrs"],"correctOption":0,"section":"Mathematics of Finance","explanation":"This is the future value of an annuity: 120,000 x [(1.10)^n - 1] / 0.10 = 1,000,000. So (1.10)^n - 1 = 0.8333, giving (1.10)^n = 1.8333 and n = ln 1.8333 / ln 1.10 = 6.36 years. Seven years (D) would give more than N1,000,000, and 6.0 years (C) falls short."}},{"itemId":"9a0cec31-a1df-5419-b183-c72f83d375b5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fabec354-75d3-5e68-9aae-745c6764695b","sourceKey":"bank:BUA216:F101-230","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N250,000 received in 5 years' time, if such fund yields 15% per annum?","options":["N124,153","N124,253","N124,294","N153,149"],"correctOption":2,"section":"Mathematics of Finance","explanation":"PV = 250,000 / (1.15)^5 = 250,000 / 2.0114 = N124,294. Options A and B are close but do not match the discount factor, and D (N153,149) is far off."}},{"itemId":"3383e481-1701-56b2-a3f9-ccbe7a2a5065","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c68e9f04-453b-5e1a-81cd-204f4eed7735","sourceKey":"bank:BUA216:F101-231","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N260,000 received in 5 years' time, if such fund yields 15% per annum compounded annually? (Answer to the nearest naira.)","options":["N129,153","N153,149","N148,153","N129,266"],"correctOption":3,"section":"Mathematics of Finance","explanation":"PV = 260,000 / (1.15)^5 = 260,000 / 2.0114 = N129,266. Option A (N129,153) is close but does not match, and B and C are too high for a sum discounted at 15% over 5 years."}},{"itemId":"ba1c4306-c133-5a44-b873-dd0ca3b4add5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ab06d2df-2551-52e8-a9b1-735339a6b146","sourceKey":"bank:BUA216:F101-232","parentItemId":null,"revision":1,"payload":{"prompt":"One of these require financial statement to advice clients","options":["Shareholder","Management","Analyst","Researcher"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Financial analysts study companies' financial statements so they can advise their clients on whether to invest. Shareholders (A) and management (B) use statements for their own decisions, not to advise clients, and a researcher (D) studies them for academic purposes."}},{"itemId":"c696e328-5fa3-5613-912d-7103b2dc9780","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"885bc558-d2ee-5f98-b086-59f3001a10fa","sourceKey":"bank:BUA216:F101-233","parentItemId":null,"revision":1,"payload":{"prompt":"For a given market price per share, state the relationship between EPS and the P/E ratio","options":["Direct","Complementary","Inverse","Regular"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"The P/E ratio is market price per share divided by EPS, so for a given share price a higher EPS gives a lower P/E. That makes the relationship inverse. Option A (direct) would mean they rise together, which is not what the formula shows."}},{"itemId":"e3b808b9-a8bb-5333-8fa3-3bf9dee962d2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"027ab199-f961-5a54-ab6c-513d273807a3","sourceKey":"bank:BUA216:F101-234","parentItemId":null,"revision":1,"payload":{"prompt":"This is a market value ratio","options":["Gross Profit Margin","Time interest earned","Earning yield","None"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Earnings yield (EPS divided by market price per share) uses the share's market price, so it is a market value ratio. Gross profit margin (A) is a profitability ratio, and times interest earned (B) is a leverage or coverage ratio, which is why D is also wrong."}},{"itemId":"ea4d2d83-6eaf-56d2-a70e-43c8978941de","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"84e8f0b2-c415-56dc-9ef0-b5aa45be539c","sourceKey":"bank:BUA216:F101-236","parentItemId":null,"revision":1,"payload":{"prompt":"I will receive N250,000 at the end of each year for 4 years. Find the present value of these receipts if the interest rate is 10% per annum.","options":["N792,456.36","N792,406.36","N792,466.36","N782,466.36"],"correctOption":2,"section":"Mathematics of Finance","explanation":"This is the present value of an ordinary annuity: PV = 250,000 x [1 - (1.10)^-4] / 0.10 = 250,000 x 3.1699 = N792,466.36. Options A and B differ only in small digits, and D (N782,466.36) is N10,000 too low."}},{"itemId":"67c6b3d2-f7e8-5611-a3e6-4108e7ebbcc7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"95aa455b-3f2a-56f2-b93b-0bccc9d54312","sourceKey":"bank:BUA216:F101-237","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an economic objective of a business firm?","options":["Sales growth","Improvement in market share","Profits and return on investment","Conservation of natural resources"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Economic objectives of a firm are commercial performance goals such as sales growth (A), a bigger market share (B), and profits and return on investment (C). Conservation of natural resources is a social or environmental objective rather than an economic one, so D is the odd one out."}},{"itemId":"f500cf99-dbf5-5653-95b5-b6a6f64ea3df","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"570c2ef0-b362-585d-83a8-7b51fb0d2ab3","sourceKey":"bank:BUA216:F101-238","parentItemId":null,"revision":1,"payload":{"prompt":"The ratio that shows the extent to which the claims of short-term creditors are covered by assets expected to be converted to cash within a year is called?","options":["Current ratio","Quick ratio","Debt ratio","Creditor ratio"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The current ratio (current assets / current liabilities) shows how far short-term creditors' claims are covered by assets expected to become cash within a year. The quick ratio (B) is stricter, because it leaves out inventory. Options C and D are not standard liquidity ratios with this meaning."}},{"itemId":"f98c5a60-d99a-57fa-a7c2-ff05562415c6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c69cac2d-9e87-5520-8e14-ad9191442b34","sourceKey":"bank:BUA216:F101-239","parentItemId":null,"revision":1,"payload":{"prompt":"The major managerial function of a financial manager in a limited liability company are among others except","options":["Investment decision","Dividend decision","Financial decision","Acquisition decision."],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"The three major finance decisions of a financial manager are the investment decision (A), the dividend decision (B) and the financing decision (C). An acquisition decision is a specific strategic choice, not one of the three core finance functions."}},{"itemId":"337795fc-5dce-5806-beeb-aa156ff993ee","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1546bcff-a56c-59d2-85ec-85918b797282","sourceKey":"bank:BUA216:F101-240","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is most appropriate as an Objective of a business organization?","options":["To achieve long term growth in earnings","To maximize shareholder wealth","To make efficient use of resources","To minimize input costs"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Maximising shareholder wealth is the most appropriate overall objective because it takes account of risk, the timing of returns and long-term value. Long-term earnings growth (A) is also partly true, but it ignores risk, and efficient use of resources (C) and cost minimisation (D) are ways of reaching the main goal rather than the goal itself."}},{"itemId":"f84da64a-0074-5e8c-a6ef-241312b94b26","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"34cb554c-b2cf-52ed-8f0d-8cc0f5aac14e","sourceKey":"bank:BUA216:F101-241","parentItemId":null,"revision":1,"payload":{"prompt":"Shareholder wealth\" in a firm is represented by:","options":["the number of people employed in the firm","the book value of the firm's assets less the book value of its liabilities","the amount of salary paid to its employees.","the market price per share of the firm's common stock."],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Shareholder wealth is reflected in the market price of the firm's shares, because the share price captures expected future returns, their timing and their risk. Book value (B) is based on historical accounting figures, not market value. The number of employees (A) and salaries paid (C) have nothing to do with owners' wealth."}},{"itemId":"c1a7fb41-2da9-5db6-b61e-f568f083ada3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f3191777-be22-5776-ade2-de0f909bf85f","sourceKey":"bank:BUA216:F101-242","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following reasons is not why wealth maximization is better than profit maximization as an objective of a business firm?","options":["Explicit consideration of risks in investments","Recognition of the prospects of a firms in the short-run","Recognition of the perception of shareholders. about the returns realizable from investment","Consideration of time value of money concept"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Wealth maximisation is better because it focuses on the firm's long-term prospects, not the short run, so option B is not a valid reason. Options A, C and D are genuine reasons: wealth maximisation considers risk, shareholders' view of expected returns through the share price, and the time value of money."}},{"itemId":"c58baeb8-6f3c-58e3-b3de-80adce2ada9a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"86de490f-1853-512e-af8e-d7b644143303","sourceKey":"bank:BUA216:F101-243","parentItemId":null,"revision":1,"payload":{"prompt":"At the end of each year for the next ten years, you will receive cash flows of N50. If the appropriate discount rate is 5.5 percent, how much would you pay for this annuity?","options":["N259.82","N299.02","N338.99","N376.88"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The price of the annuity is its present value: PV = 50 x [1 - (1.055)^-10] / 0.055 = 50 x 7.5376 = N376.88. Options A, B and C are all too low, since ten payments of N50 total N500 and discounting at 5.5% should not cut that by as much as they suggest."}},{"itemId":"34481ecf-ce01-5aa8-b2c3-c2e5b5f10c2b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"79ac18c7-c8db-5d7f-9513-621c7dfd3dfa","sourceKey":"bank:BUA216:F101-244","parentItemId":null,"revision":1,"payload":{"prompt":"Assuming N100,000 is placed in a fixed deposit account with a bank that offers the depositor 24% interest per annum compounded quarterly, calculate the compounded value of the investment if it is made for 2 years.","options":["N160,470.64","N159,384.81","N190,662.40","N201,219.65"],"correctOption":1,"section":"Mathematics of Finance","explanation":"With quarterly compounding, the rate per quarter is 24% / 4 = 6% for 2 x 4 = 8 quarters. FV = 100,000 x (1.06)^8 = 100,000 x 1.5938 = N159,384.81. Option C (N190,662.40) and D are too high, and A (N160,470.64) does not match this calculation."}},{"itemId":"73392895-dc61-5f7c-8295-51bf00b39c53","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15a5639c-7a81-52a8-8dd8-a1e06ceb4fca","sourceKey":"bank:BUA216:F101-245","parentItemId":null,"revision":1,"payload":{"prompt":"A project has a cost of N53,500 and its expected net cash inflows are N11,500 per annum for 6 years. If the cost of capital is 5%, the project's Net Present Value (NPV) is","options":["N78,221.46","N81,087.46","N58,370.46","N4,870.46"],"correctOption":3,"section":"Net Present Value","explanation":"NPV = PV of inflows - cost. PV of inflows = 11,500 x [1 - (1.05)^-6] / 0.05 = 11,500 x 5.0757 = N58,370.46, so NPV = 58,370.46 - 53,500 = N4,870.46. Option C (N58,370.46) is only the present value of the inflows before subtracting the cost, and A and B are wrong totals."}},{"itemId":"0d30fb8d-b71b-515d-bf5d-a35763094480","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0fad5349-5e54-5423-95ee-f0604aa23b0c","sourceKey":"bank:BUA216:F101-246","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The expected value of the project is","options":["N15,000","N18,000","N28,000","N61,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Expected value = sum of each cash flow x its probability: 50,000(0.3) + 60,000(0.3) + 70,000(0.4) = 15,000 + 18,000 + 28,000 = N61,000. Options A, B and C are just the separate parts of this sum, not the full expected value."}},{"itemId":"5dcd1129-fb3b-5cf8-b89b-58d1fb947d6e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3df5be2-0c09-5d89-bcdb-7520c5f568f5","sourceKey":"bank:BUA216:F101-247","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The variance of the project is","options":["N36,300,000","N300,000","N32,400,000","N69,000,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"With expected value N61,000, variance = 0.3(50,000-61,000)^2 + 0.3(60,000-61,000)^2 + 0.4(70,000-61,000)^2 = 36,300,000 + 300,000 + 32,400,000 = 69,000,000. Options A, B and C are only the individual terms of this sum, not the total variance."}},{"itemId":"d011a2c3-03f7-5976-a7b0-051a7033bc41","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6ddbc924-c237-5ba3-a4f9-aeeaf4904e67","sourceKey":"bank:BUA216:F101-248","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The standard deviation of the project is","options":["N7,810.25","N8,306.62","N69,000,000","N57,000"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Standard deviation is the square root of the variance. Variance = 69,000,000, so SD = square root of 69,000,000 = N8,306.62. Option C (69,000,000) is the variance itself, not its square root, and A and D do not match the calculation."}},{"itemId":"277a2f8b-9819-562e-902e-84359709c1bf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1af9a8f9-f082-5b57-9ceb-bcae95dd3045","sourceKey":"bank:BUA216:F101-249","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project are given as follows: N50,000 (0.3), N60,000 (0.3) and N70,000 (0.4). The coefficient of variation of the project, to the nearest whole percent, is","options":["14%","34%","24%","13%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Expected cash flow = 0.3(50,000) + 0.3(60,000) + 0.4(70,000) = N61,000, and the standard deviation is the square root of 69,000,000 = N8,306.62. Coefficient of variation = 8,306.62 / 61,000 = 13.6%, which is 14% to the nearest whole percent. Option D (13%) truncates the figure instead of rounding it, and B and C are far too high."}},{"itemId":"c6ab9900-9fa3-586b-8595-f51208ab0b75","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"505b5344-025f-5cf2-ba2e-40c60517ff74","sourceKey":"bank:BUA216:F101-250","parentItemId":null,"revision":1,"payload":{"prompt":"The two major types of annuity are......... and.........","options":["ordinary annuity, annuity due","Regular , irregular annuity","Perpetual, deferred annuity","All of the above"],"correctOption":0,"section":"Mathematics of Finance","explanation":"The two main types of annuity are the ordinary annuity, where payments come at the end of each period, and the annuity due, where payments come at the start. Perpetuities and deferred annuities (C) are special cases, and B is not a standard classification, so D is also wrong."}},{"itemId":"f5263d29-1fe3-5f9b-8099-c44625c1d0c0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e523975b-7eee-50ca-b1cc-6231a5fafd40","sourceKey":"bank:BUA216:MAT-001","parentItemId":null,"revision":1,"payload":{"prompt":"Adaeze invests N250,000 at 12% simple interest per annum for 4 years. What is the total interest earned at the end of the 4 years? (Answer to the nearest naira.)","options":["N30,000","N143,380","N120,000","N370,000"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Simple interest is P x T x R = 250,000 x 4 x 0.12 = N120,000. Option B applies compound interest, 250,000[(1.12)^4 - 1], which this deposit does not earn, while Option A is only one year's interest and Option D is the total amount, not the interest."}},{"itemId":"80480058-7072-5912-8b27-8442a56ae7e0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bcde810a-9224-5e64-9841-036791514d69","sourceKey":"bank:BUA216:MAT-002","parentItemId":null,"revision":1,"payload":{"prompt":"Simple interest of N54,000 was earned on a principal of N150,000 at 12% per annum. For how long was the money invested? (Answer in years to 2 decimal places.)","options":["3.00 years","2.00 years","2.71 years","4.00 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Rearranging SI = P x T x R gives T = SI / (P x R) = 54,000 / (150,000 x 0.12) = 54,000 / 18,000 = 3.00 years. Option C wrongly treats the growth as compound interest and solves with logarithms."}},{"itemId":"df88cc44-8fb2-584b-8dc9-779e33c02372","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"eebcd287-6523-5015-b2dc-6eb9cd784a48","sourceKey":"bank:BUA216:MAT-003","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N210,000 attracted simple interest of N63,000 over 2 years. What was the annual simple interest rate? (Answer to 2 decimal places.)","options":["7.50%","15.00%","14.02%","30.00%"],"correctOption":1,"section":"Mathematics of Finance","explanation":"R = SI / (P x T) = 63,000 / (210,000 x 2) = 0.15, or 15.00%. Option D forgets to divide by the 2 years, and Option C treats the growth as compound by taking the square root of 1.3."}},{"itemId":"69df7127-cc49-5670-8ee0-18c684243be3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"062a3d4d-82d4-5fbd-80cf-8455b2bab5e6","sourceKey":"bank:BUA216:MAT-004","parentItemId":null,"revision":1,"payload":{"prompt":"N400,000 is invested for 3 years at 10% per annum. By how much does the interest earned under annual compounding exceed the interest earned under simple interest? (Answer to the nearest naira.)","options":["N12,400","N132,400","N1,240","N4,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Compound interest is 400,000[(1.1)^3 - 1] = 132,400 and simple interest is 400,000 x 3 x 0.1 = 120,000, a difference of N12,400. Option D is the gap after only 2 years, and Option B is the whole compound interest rather than the difference."}},{"itemId":"73e2a620-8be5-57c3-b65f-9ddeb7094e9a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c61ca3d9-4702-5640-9d05-3af30fc7596d","sourceKey":"bank:BUA216:MAT-005","parentItemId":null,"revision":1,"payload":{"prompt":"N300,000 is invested at 10% interest compounded annually. How much interest is earned in the third year alone? (Answer to the nearest naira.)","options":["N36,300","N99,300","N30,000","N33,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Under compound interest the third year's interest is charged on the balance at the start of year 3, 300,000 x (1.1)^2 = 363,000, so interest is 363,000 x 0.1 = N36,300. Option C is the constant yearly figure under simple interest, Option D is year 2's interest, and Option B is the total interest for all three years."}},{"itemId":"93f0a843-56b2-5b4c-a328-aa4fee031b5c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"48fc1ebd-7f4c-5b1c-8f44-5a34852ed24c","sourceKey":"bank:BUA216:MAT-006","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the amounts at the end of each year under simple interest as an arithmetic progression, N200,000 invested at 8% simple interest grows to N216,000, N232,000, N248,000 and so on. What is the amount at the end of year 6? (Answer to the nearest naira.)","options":["N312,000","N317,375","N296,000","N280,000"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The amounts form an AP with first term 216,000 and common difference 16,000 (the constant yearly interest), so the 6th term is 216,000 + 5 x 16,000 = N296,000, the same as 200,000(1 + 6 x 0.08). Option B compounds the interest, while Option D and Option A count one year too few or too many."}},{"itemId":"d51653c3-63ba-5ad5-b4e5-5d635da2e125","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"04d40a5c-f71d-5f38-ba5d-0e4515bca7b7","sourceKey":"bank:BUA216:MAT-007","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde invests N450,000 for 5 years at 14% interest compounded annually. What is the future value of the investment, to the nearest naira?","options":["N765,000","N760,032","N866,437","N416,437"],"correctOption":2,"section":"Mathematics of Finance","explanation":"FV = PV(1 + i)^n = 450,000 x (1.14)^5 = N866,437. Option A uses simple interest, Option B compounds for only 4 years, and Option D is the interest earned rather than the future value."}},{"itemId":"0dc931c6-00c7-5e6f-83bc-83341f2df95e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3b18766-cc0c-5c3a-82fa-cbda81034e9a","sourceKey":"bank:BUA216:MAT-008","parentItemId":null,"revision":1,"payload":{"prompt":"Ngozi deposits N60,000 at 18% interest compounded annually for 4 years. What is the total compound interest earned, to the nearest naira?","options":["N116,327","N43,200","N56,327","N38,582"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Compound interest = PV[(1 + i)^n - 1] = 60,000 x [(1.18)^4 - 1] = N56,327. Option B is the simple interest figure, and Option A is the full amount including the N60,000 principal."}},{"itemId":"062f8462-46ea-5e70-960c-981e855d633f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f0d81910-2ccc-5150-bbd8-1d380b31d19d","sourceKey":"bank:BUA216:MAT-009","parentItemId":null,"revision":1,"payload":{"prompt":"N250,000 is invested at 16% interest compounded annually. Using a year-by-year schedule, what is the amount at the end of year 2? (Answer to the nearest naira.)","options":["N330,000","N290,000","N390,224","N336,400"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Year 1 interest is 40,000 giving 290,000; year 2 interest is 290,000 x 0.16 = 46,400 giving N336,400, which equals 250,000 x (1.16)^2. Option A adds a flat 40,000 each year as with simple interest."}},{"itemId":"7b5ac80a-7eee-5145-b5c4-42f8397cd83b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8b17588f-5596-5c9a-bca1-3096efb6ad79","sourceKey":"bank:BUA216:MAT-010","parentItemId":null,"revision":1,"payload":{"prompt":"A company deposits N500,000 that earns 10% compounded annually for the first 2 years and 12% compounded annually for the next 3 years. What is the balance at the end of year 5, to the nearest naira?","options":["N780,000","N805,255","N881,171","N849,981"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The balance after 2 years is 500,000 x (1.1)^2 = 605,000, which then grows at 12% for 3 years: 605,000 x (1.12)^3 = N849,981. Option C and Option B apply one rate to all 5 years, and Option A uses simple interest for both phases."}},{"itemId":"c539c985-ce42-5738-83d9-ea0b5e930f4b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a1d03dd-c6e4-5c6c-a414-2aa4ae40fdbc","sourceKey":"bank:BUA216:MAT-011","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N1,500,000 receivable in 4 years' time if money earns 13% compounded annually? (Answer to the nearest naira.)","options":["N986,842","N1,039,575","N2,445,710","N919,978"],"correctOption":3,"section":"Mathematics of Finance","explanation":"PV = FV / (1 + i)^n = 1,500,000 / (1.13)^4 = N919,978. Option C compounds forward instead of discounting, and Option A discounts at simple interest."}},{"itemId":"5f2af428-5f09-5e02-b55d-530353eef03f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2546f697-d0a2-59ab-8233-661c2eff88a6","sourceKey":"bank:BUA216:MAT-012","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N900,000 due in 3 years if the discount rate is 16% per annum compounded semi-annually? (Answer to the nearest naira.)","options":["N567,153","N714,449","N369,398","N576,592"],"correctOption":0,"section":"Mathematics of Finance","explanation":"With semi-annual compounding the rate per period is 16%/2 = 8% and there are 3 x 2 = 6 periods, so PV = 900,000 / (1.08)^6 = N567,153. Option D ignores the semi-annual compounding, and Option B halves the rate but forgets to double the periods."}},{"itemId":"35f14cfd-2653-54b6-8c21-c47aad065aa1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4fcb32d5-9050-5df8-8908-69dafe87590d","sourceKey":"bank:BUA216:MAT-013","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier is owed N1,200,000 payable in 2 years. At 20% per annum compounded quarterly, what is the present value of this receivable, to the nearest naira?","options":["N1,088,435","N812,207","N987,243","N833,333"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Quarterly compounding gives 20%/4 = 5% per quarter over 2 x 4 = 8 quarters: PV = 1,200,000 / (1.05)^8 = N812,207. Option D uses annual compounding, while Option A and Option C use the wrong number of quarters."}},{"itemId":"fa0bce27-f9af-5cec-9eb9-509ee2f1e1de","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0615eb7a-5caa-592d-b83d-2f0e17d9c60b","sourceKey":"bank:BUA216:MAT-014","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N600,000 to be received in 3 years if interest is compounded continuously at 15% per annum? (Answer to the nearest naira.)","options":["N516,425","N394,510","N940,987","N382,577"],"correctOption":3,"section":"Mathematics of Finance","explanation":"For continuous compounding PV = FV x e^(-in) = 600,000 x e^(-0.15 x 3) = 600,000 x e^(-0.45) = N382,577. Option B discounts with annual compounding, Option C compounds forward instead of discounting, and Option A forgets to multiply the rate by 3 years."}},{"itemId":"f48a8c51-7ba5-551e-94f7-d908e222ba1b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8161a54d-af08-50a4-830e-009c351aeffd","sourceKey":"bank:BUA216:MAT-015","parentItemId":null,"revision":1,"payload":{"prompt":"What is the discount factor (present value of N1) for 3 years at 15% compounded annually, to 4 decimal places?","options":["0.7561","0.6575","0.6897","1.5209"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The discount factor is 1 / (1 + i)^n = 1 / (1.15)^3 = 0.6575. Option D is the compound factor (1.15)^3, the reciprocal of the right answer, and Option C uses simple interest."}},{"itemId":"148b1573-29c6-5940-bc66-b8c454faea70","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2b99502-a1ec-5f6b-9bce-7acdb4501db5","sourceKey":"bank:BUA216:MAT-016","parentItemId":null,"revision":1,"payload":{"prompt":"A business expects cash inflows of N100,000 at the end of year 1, N200,000 at the end of year 2 and N300,000 at the end of year 3. At a discount rate of 10% compounded annually, what is the total present value of these inflows, to the nearest naira?","options":["N481,593","N450,789","N545,455","N513,148"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Each flow is discounted for its own year: 100,000/1.1 + 200,000/(1.1)^2 + 300,000/(1.1)^3 = 90,909 + 165,289 + 225,394 = N481,593. Option B discounts the whole N600,000 for 3 years, and Option D matches the discount factors to the wrong years."}},{"itemId":"9b379bfc-d7ef-5348-a90c-9db017643fc5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af9787c0-d354-5d9a-b747-3928d19468c1","sourceKey":"bank:BUA216:MAT-017","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N1,000,000 receivable in 18 months if the discount rate is 20% per annum compounded semi-annually? (Answer to the nearest naira.)","options":["N760,726","N751,315","N866,784","N179,859"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Eighteen months is 3 half-years at 10% each, so PV = 1,000,000 / (1.1)^3 = N751,315. Option A uses annual compounding over 1.5 years, and Option C uses the half-year rate with the period still counted in years."}},{"itemId":"cf9db37a-301b-504b-bae2-49d54a2a8967","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3c03061f-b68f-54c0-92d0-e0ee7ae658fa","sourceKey":"bank:BUA216:MAT-018","parentItemId":null,"revision":1,"payload":{"prompt":"N300,000 is deposited at 18% per annum compounded monthly for 2 years. What is the future value, to the nearest naira?","options":["N309,067","N428,851","N358,685","N417,720"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Monthly compounding gives 18%/12 = 1.5% per month over 2 x 12 = 24 months: FV = 300,000 x (1.015)^24 = N428,851. Option D compounds annually, and Option C uses only 12 months."}},{"itemId":"f460e79c-5d00-5095-adea-a8d80ff92684","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"55acc8ac-e1cc-5626-8506-49a6d7fe14b3","sourceKey":"bank:BUA216:MAT-019","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi saves N150,000 in an account paying 12% per annum compounded every four months. What will the account hold after 5 years, to the nearest naira?","options":["N264,351","N270,142","N182,498","N328,668"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Every four months means m = 3, so the rate per period is 12%/3 = 4% over 5 x 3 = 15 periods: FV = 150,000 x (1.04)^15 = N270,142. Option D applies the 4% rate four times a year, Option A compounds annually, and Option C forgets to multiply the years by m."}},{"itemId":"ff7090cb-f08f-5ec3-88d8-928294b115f0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9571f324-6c69-5d97-a87c-c8945cc02727","sourceKey":"bank:BUA216:MAT-020","parentItemId":null,"revision":1,"payload":{"prompt":"A bank offers 32% per annum payable twice in a quarter. What will a deposit of N80,000 grow to in 2 years, to the nearest naira?","options":["N149,838","N148,074","N109,486","N139,392"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Twice in a quarter means m = 8, so the rate per period is 32%/8 = 4% over 2 x 8 = 16 periods: FV = 80,000 x (1.04)^16 = N149,838. Option B uses quarterly compounding (m = 4), and Option C uses the right rate but only 8 periods."}},{"itemId":"287f9f8a-7cba-537b-a548-c75d5103675b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"928276fd-8451-583d-b326-0f837967f2ad","sourceKey":"bank:BUA216:MAT-021","parentItemId":null,"revision":1,"payload":{"prompt":"N1,000,000 is invested for 3 years at 12% per annum. How much more is earned if interest is compounded quarterly rather than annually? (Answer to the nearest naira.)","options":["N20,833","N44,928","N425,761","N13,591"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Quarterly: 1,000,000 x (1.03)^12 = 1,425,761; annually: 1,000,000 x (1.12)^3 = 1,404,928; the extra is N20,833. Option C is the total quarterly interest, not the difference, and Option D compares semi-annual with annual compounding instead."}},{"itemId":"6fd1f44d-b794-58d9-abc6-29a15e188f4a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"483aebe8-ca80-5a73-bb79-8682fc2caa92","sourceKey":"bank:BUA216:MAT-022","parentItemId":null,"revision":1,"payload":{"prompt":"An investor places N500,000 in an account paying 24% per annum compounded twice in a month. What is the balance after 1 year, to the nearest naira?","options":["N634,867","N620,000","N804,219","N563,413"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Twice in a month means m = 24, so the rate per period is 24%/24 = 1% over 24 periods: FV = 500,000 x (1.01)^24 = N634,867. Option C uses the monthly rate of 2% for 24 periods, Option B is annual compounding, and Option D uses only 12 periods."}},{"itemId":"774600f1-8316-5ca2-ab38-8ad9891ef2be","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6b02a945-d943-52f9-b0c2-97ce934921aa","sourceKey":"bank:BUA216:MAT-023","parentItemId":null,"revision":1,"payload":{"prompt":"N350,000 is invested for 3 years at 14% per annum compounded continuously. What is the future value, to the nearest naira? (Take e = 2.71828.)","options":["N497,000","N402,596","N532,686","N518,540"],"correctOption":2,"section":"Mathematics of Finance","explanation":"FV = PV x e^(in) = 350,000 x e^(0.14 x 3) = 350,000 x e^0.42 = N532,686. Option D uses annual compounding, which gives slightly less, and Option B forgets to multiply the rate by the 3 years."}},{"itemId":"2522b2fa-a348-52c7-80f5-b8819fc58f0a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fc74aa86-f517-5e63-b41a-a6dd3d26da88","sourceKey":"bank:BUA216:MAT-024","parentItemId":null,"revision":1,"payload":{"prompt":"What sum must be invested today at 12% per annum compounded continuously to have N2,500,000 in 4 years? (Answer to the nearest naira.)","options":["N1,588,795","N2,217,301","N1,546,958","N1,300,000"],"correctOption":2,"section":"Mathematics of Finance","explanation":"PV = FV x e^(-in) = 2,500,000 x e^(-0.48) = N1,546,958. Option A discounts with annual compounding, and Option B uses e^(-0.12), ignoring the 4 years."}},{"itemId":"b3253303-3861-5162-a1d7-92e5841a4564","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"46e66d30-f691-5790-9976-6c483c370f49","sourceKey":"bank:BUA216:MAT-025","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take money to double at 10% per annum compounded continuously? (Answer in years to 2 decimal places.)","options":["7.20 years","7.27 years","6.93 years","10.00 years"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Setting 2 = e^(0.1n) gives n = ln 2 / 0.1 = 6.93 years. Option B is the doubling time under annual compounding, and Option A is the Rule of 72 estimate, which is only an approximation."}},{"itemId":"b91104a6-d784-50a6-a9da-888774b1fdba","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c0990625-910f-5d8c-9583-4b33cc50bfca","sourceKey":"bank:BUA216:MAT-026","parentItemId":null,"revision":1,"payload":{"prompt":"At what annual rate, compounded continuously, will N200,000 grow to N300,000 in 4 years? (Answer to 2 decimal places.)","options":["12.50%","10.67%","40.55%","10.14%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"From 300,000 = 200,000 x e^(4r), r = ln(1.5) / 4 = 0.4055 / 4 = 10.14%. Option B is the annually compounded rate (1.5)^(1/4) - 1, and Option A is the simple interest rate."}},{"itemId":"2caa8203-b660-5bef-94c3-f998bafc9c1b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"366dbca6-39de-5b81-b1fe-860afd480747","sourceKey":"bank:BUA216:MAT-027","parentItemId":null,"revision":1,"payload":{"prompt":"N500,000 is invested for 2 years at 20% per annum. How much more does it earn under continuous compounding than under annual compounding? (Answer to the nearest naira.)","options":["N10,701","N12,050","N245,912","N25,912"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Continuous: 500,000 x e^0.4 = 745,912; annual: 500,000 x (1.2)^2 = 720,000; the difference is N25,912. Option C is the full continuous interest, and Option B compares semi-annual rather than continuous compounding with annual."}},{"itemId":"78fcf3eb-d087-5d6d-86ec-28464f228ec7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"85bf4576-0820-5c3d-bcd3-43739ede421d","sourceKey":"bank:BUA216:MAT-028","parentItemId":null,"revision":1,"payload":{"prompt":"A bank quotes a nominal rate of 24% per annum compounded monthly. What is the effective annual rate, to 2 decimal places?","options":["26.25%","24.00%","26.82%","27.12%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"EAR = (1 + r/m)^m - 1 = (1.02)^12 - 1 = 26.82%. Option B is just the nominal rate, Option D is the continuous-compounding rate, and Option A assumes quarterly compounding."}},{"itemId":"a442ad74-669d-57a7-90f5-1f5d821eb63d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ccf21266-c2f2-58c8-9383-b485e4a045e9","sourceKey":"bank:BUA216:MAT-029","parentItemId":null,"revision":1,"payload":{"prompt":"What is the effective annual rate of 16% per annum compounded quarterly? (Answer to 2 decimal places.)","options":["16.64%","4.25%","16.00%","16.99%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"EAR = (1 + 0.16/4)^4 - 1 = (1.04)^4 - 1 = 16.99%. Option C ignores compounding within the year, and Option A assumes semi-annual compounding."}},{"itemId":"0cf0e29b-f71b-5000-9bc2-16438cbb5e7b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"928ff791-8ef8-500a-bb2b-09193c3c22c9","sourceKey":"bank:BUA216:MAT-030","parentItemId":null,"revision":1,"payload":{"prompt":"What is the effective annual rate of 18% per annum compounded continuously? (Answer to 2 decimal places.)","options":["19.72%","18.81%","18.00%","11.97%"],"correctOption":0,"section":"Mathematics of Finance","explanation":"With continuous compounding EAR = e^r - 1 = e^0.18 - 1 = 19.72%. Option C is the nominal rate, and Option B is the semi-annual EAR; continuous compounding gives the highest EAR for a given nominal rate."}},{"itemId":"7d4f2cf4-fe1c-5c8e-8a25-177b699f5fe0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b46de9a6-cdd0-559c-8802-b208cf06f011","sourceKey":"bank:BUA216:MAT-031","parentItemId":null,"revision":1,"payload":{"prompt":"Four banks quote the following on savings. Which offers the highest effective annual rate? (EAR = (1 + r/m)^m - 1.)","options":["21.2% per annum compounded annually","19% per annum compounded monthly","20% per annum compounded quarterly","20% per annum compounded semi-annually"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Converting each: 21.2% annual gives 21.20%; 20% semi-annual gives (1.1)^2 - 1 = 21.00%; 20% quarterly gives (1.05)^4 - 1 = 21.55%; 19% monthly gives (1.0158)^12 - 1 = 20.75%. The quarterly offer is highest, so Option A, the largest headline rate, is not the best deal once compounding is considered."}},{"itemId":"658d20fc-b384-5769-a5bb-b6d764fa6313","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"81f49d05-1678-54af-a7fb-b68704540bc6","sourceKey":"bank:BUA216:MAT-032","parentItemId":null,"revision":1,"payload":{"prompt":"What nominal annual rate, compounded quarterly, gives an effective annual rate of 12.55%? (Answer to 2 decimal places.)","options":["12.18%","12.55%","12.00%","3.14%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Rearranging EAR = (1 + r/4)^4 - 1 gives r = 4[(1.1255)^(1/4) - 1] = 12.00%. Option B confuses the effective with the nominal rate, and Option A uses semi-annual compounding."}},{"itemId":"c24f96bd-2fed-53e7-9831-65e2a8c87298","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fbbc0b22-5c34-5055-b669-f7a8078c802f","sourceKey":"bank:BUA216:MAT-033","parentItemId":null,"revision":1,"payload":{"prompt":"What is the effective annual rate of 30% per annum compounded twice in a quarter? (Answer to 2 decimal places.)","options":["33.55%","34.25%","34.74%","30.00%"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Twice in a quarter means m = 8: EAR = (1 + 0.30/8)^8 - 1 = (1.0375)^8 - 1 = 34.25%. Option A uses m = 4 (quarterly), and Option C uses m = 24 (twice a month)."}},{"itemId":"78bc5147-330a-5538-a81e-11a93585b1a6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f2fa7d56-dfb2-5b60-9847-935a8b533fa8","sourceKey":"bank:BUA216:MAT-034","parentItemId":null,"revision":1,"payload":{"prompt":"What is the effective annual rate of 12% per annum compounded every four months? (Answer to 2 decimal places.)","options":["12.00%","12.49%","16.99%","4.00%"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Every four months means m = 3: EAR = (1 + 0.12/3)^3 - 1 = (1.04)^3 - 1 = 12.49%. Option C compounds the 4% rate four times instead of three, Option A is the nominal rate, and Option D is only the rate per period."}},{"itemId":"0be1fb2e-ec83-52da-9c8f-d507d340eed5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1e8b9d2b-0397-554c-8f3e-2ef7d48a7750","sourceKey":"bank:BUA216:MAT-035","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take N250,000 to grow to N400,000 at 12% per annum compounded annually? (Answer in years to 2 decimal places.)","options":["4.15 years","0.24 years","5.00 years","3.92 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"From 1.6 = (1.12)^n, n = log 1.6 / log 1.12 = 4.15 years. Option C uses simple interest, Option D divides by the rate instead of log(1.12), and Option B inverts the ratio."}},{"itemId":"5e7da039-27e3-5746-b02f-6c0d6ef58586","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9cfbe249-cc04-59f4-8822-86c7029aa75e","sourceKey":"bank:BUA216:MAT-036","parentItemId":null,"revision":1,"payload":{"prompt":"Exactly how long does it take money to double at 9% per annum compounded annually, to 2 decimal places? (Compare with the Rule of 72.)","options":["11.11 years","3.34 years","7.70 years","8.04 years"],"correctOption":3,"section":"Mathematics of Finance","explanation":"n = log 2 / log 1.09 = 8.04 years, which is close to the Rule of 72 estimate of 72/9 = 8 years, confirming the answer. Option B divides log 2 by 0.09 instead of by log 1.09, Option C is the continuous-compounding doubling time, and Option A is the simple interest doubling time."}},{"itemId":"5be0600c-bb46-5822-abda-0c2cad547d66","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"302e783a-5caf-5580-9087-ce2def906e2e","sourceKey":"bank:BUA216:MAT-037","parentItemId":null,"revision":1,"payload":{"prompt":"Using the Rule of 72, approximately what annual interest rate will double an investment in 6 years? (Answer to 1 decimal place.)","options":["16.7%","24.0%","12.0%","7.2%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The Rule of 72 says years to double is about 72 / rate, so rate is about 72 / 6 = 12.0%. Option D divides 72 by 10 instead, and Option A is the simple interest rate needed to double in 6 years."}},{"itemId":"14d3ba02-4de8-5f08-ba5d-8269d632fe87","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0208eba6-980d-5d2e-81df-c1739b777072","sourceKey":"bank:BUA216:MAT-038","parentItemId":null,"revision":1,"payload":{"prompt":"Using the Rule of 72, roughly how many years will a deposit take to double at 8% per annum compounded annually? (Answer in years to 2 decimal places.)","options":["6.00 years","12.50 years","9.00 years","8.00 years"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Years to double is about 72 / 8 = 9.00 years (the exact figure, log 2 / log 1.08, is 9.01 years). Option B is 100 / 8, the simple interest doubling time."}},{"itemId":"c2da3e50-f7a3-55ab-af33-d48bd30b61ec","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fa68403a-6a79-5a12-8e22-b15d7b55cf45","sourceKey":"bank:BUA216:MAT-039","parentItemId":null,"revision":1,"payload":{"prompt":"How long will N500,000 take to grow to N800,000 at 16% per annum compounded quarterly? (Answer in years to 2 decimal places.)","options":["3.75 years","3.17 years","3.00 years","3.05 years"],"correctOption":2,"section":"Mathematics of Finance","explanation":"With 4% per quarter, 1.6 = (1.04)^(4n), so n = log 1.6 / (4 x log 1.04) = 3.00 years. Option B uses annual compounding, and Option D uses semi-annual compounding at 8% per half-year."}},{"itemId":"e7c447e5-1244-5cc3-9a21-0b0c657f2753","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"273f7e08-ecc6-5d85-9554-4c638f3d1ab8","sourceKey":"bank:BUA216:MAT-040","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take N100,000 to grow to N150,000 at 12% per annum compounded monthly? (Answer in years to 2 decimal places.)","options":["3.40 years","4.17 years","40.75 years","3.58 years"],"correctOption":0,"section":"Mathematics of Finance","explanation":"At 1% a month, 1.5 = (1.01)^(12n), so n = log 1.5 / (12 x log 1.01) = 3.40 years. Option D uses annual compounding, Option B uses simple interest, and Option C is the number of months, not years."}},{"itemId":"89a44fb1-b4dc-593b-be7f-309ebe41ffe4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"504e1463-4119-5c0b-a063-3dc71e434e5d","sourceKey":"bank:BUA216:MAT-041","parentItemId":null,"revision":1,"payload":{"prompt":"A cooperative saves N50,000 at the end of each year in an account paying 10% compounded annually. How many years will it take to accumulate N500,000? (Answer to 2 decimal places.)","options":["10.00 years","24.16 years","6.78 years","7.27 years"],"correctOption":3,"section":"Mathematics of Finance","explanation":"From 500,000 = 50,000[(1.1)^n - 1]/0.1, (1.1)^n = 2, so n = log 2 / log 1.1 = 7.27 years. Option A ignores interest altogether, and Option B treats the target as a single lump sum growing from N50,000."}},{"itemId":"5cde0e37-d2c2-52eb-8991-9315d33848e0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0a2ce9e8-5c43-59c6-808d-f8450f0bca03","sourceKey":"bank:BUA216:MAT-042","parentItemId":null,"revision":1,"payload":{"prompt":"At what annual rate, compounded annually, will N200,000 grow to N350,000 in 5 years? (Answer to 2 decimal places.)","options":["15.00%","11.19%","12.00%","11.84%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"From 1.75 = (1 + i)^5, i = (1.75)^(1/5) - 1 = 11.84%. Option A is the simple interest rate (75% spread over 5 years), and Option B is the continuously compounded rate, ln(1.75)/5."}},{"itemId":"369db740-1337-5618-a3af-c866f1942cc2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2f8228d8-9c22-539a-8c02-c58ebbadbffb","sourceKey":"bank:BUA216:MAT-043","parentItemId":null,"revision":1,"payload":{"prompt":"What nominal annual rate, compounded semi-annually, will make N100,000 grow to N180,000 in 4 years? (Answer to 2 decimal places.)","options":["15.25%","20.00%","15.83%","7.62%"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Using r = m[(FV/PV)^(1/(n x m)) - 1] = 2[(1.8)^(1/8) - 1] = 15.25%. Option C is the annually compounded rate, and Option D is only the half-year rate, which must be doubled to get the nominal annual rate."}},{"itemId":"98f8fd2d-fce4-578b-808c-755b95d84bb9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d3e68894-2b04-5064-9df0-1de9734f98d2","sourceKey":"bank:BUA216:MAT-044","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of N500,000 grows to N864,000 in 3 years with annual compounding. What is the annual interest rate? (Answer to 2 decimal places.)","options":["18.00%","24.27%","20.00%","25.00%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"From 1.728 = (1 + i)^3, the cube root of 1.728 is 1.2, so i = 0.2 or 20.00%. Option B is the simple interest rate found by spreading the 72.8% growth over 3 years, which ignores compounding."}},{"itemId":"d5d9e41a-b890-5246-826e-57dee22fd351","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fc367fb6-8a2f-57f1-b7af-71bf08e1f8df","sourceKey":"bank:BUA216:MAT-045","parentItemId":null,"revision":1,"payload":{"prompt":"What nominal annual rate, compounded quarterly, will make N60,000 accumulate to N100,000 in 3 years? (Answer to 2 decimal places.)","options":["4.35%","22.22%","17.40%","18.56%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"r = 4[(100,000/60,000)^(1/12) - 1] = 4[(1.6667)^(1/12) - 1] = 17.40%. Option D is the annually compounded rate, and Option A is the quarterly rate before multiplying by 4."}},{"itemId":"c9e4ecbb-73a4-5075-b8a3-14f662a382c5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2740f953-f4d4-582e-ae5a-9ae7991b0779","sourceKey":"bank:BUA216:MAT-046","parentItemId":null,"revision":1,"payload":{"prompt":"A 6-year discount factor is exactly 0.5 (N1 in 6 years is worth 50 kobo today). What annual compound rate does this imply? (Answer to 2 decimal places.)","options":["12.00%","8.33%","16.67%","12.25%"],"correctOption":3,"section":"Mathematics of Finance","explanation":"If 1/(1 + i)^6 = 0.5 then (1 + i)^6 = 2, so i = 2^(1/6) - 1 = 12.25%. Option A is the Rule of 72 estimate, which is close but not exact, and Option C is the simple interest rate that doubles money in 6 years."}},{"itemId":"43430fb4-222b-5a11-8872-7170b80e4c9b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b8efe634-8893-5b4e-8c42-b1883881c5f9","sourceKey":"bank:BUA216:MAT-047","parentItemId":null,"revision":1,"payload":{"prompt":"Femi deposits N40,000 at the end of each year for 5 years into an account paying 15% compounded annually. What is the future value of the deposits, to the nearest naira?","options":["N310,150","N200,000","N269,695","N402,271"],"correctOption":2,"section":"Mathematics of Finance","explanation":"FV of an ordinary annuity = A[(1 + i)^n - 1]/i = 40,000 x [(1.15)^5 - 1]/0.15 = N269,695. Option A is the annuity due figure (deposits at the start of each year), and Option D wrongly compounds all five deposits from today."}},{"itemId":"de74ed27-0252-5168-ae12-2f8b864bb835","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e77b901b-e18b-5203-9179-5be281170703","sourceKey":"bank:BUA216:MAT-048","parentItemId":null,"revision":1,"payload":{"prompt":"A firm sets aside N25,000 at the end of every quarter for 3 years in an account paying 12% per annum compounded quarterly. What will the account hold at the end of the 3 years, to the nearest naira?","options":["N300,000","N337,440","N354,801","N365,445"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Use 3% per quarter and 12 quarterly deposits: FV = 25,000 x [(1.03)^12 - 1]/0.03 = N354,801. Option B treats it as an annual annuity at 12% times 4, and Option D is the annuity due result."}},{"itemId":"7ce3ae80-d6ae-5d52-84d3-15bc341033a2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4b32d088-e880-5a7c-acd1-c9a513e01ee4","sourceKey":"bank:BUA216:MAT-049","parentItemId":null,"revision":1,"payload":{"prompt":"Chidi deposits N30,000 at the end of each year at 10% compounded annually. Using a year-by-year schedule, what is the balance at the end of year 3, just after the third deposit? (Answer to the nearest naira.)","options":["N99,300","N109,230","N90,000","N39,930"],"correctOption":0,"section":"Mathematics of Finance","explanation":"End of year 1: 30,000; year 2: 30,000 + 3,000 interest + 30,000 = 63,000; year 3: 63,000 + 6,300 + 30,000 = N99,300, the same as 30,000 x [(1.1)^3 - 1]/0.1. Option B assumes the deposits were made at the beginning of each year."}},{"itemId":"4dd3d33d-9a9f-5bbc-8dbe-2560f52e3a99","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c042854b-ad30-57a2-b93a-6adbcb4a4453","sourceKey":"bank:BUA216:MAT-050","parentItemId":null,"revision":1,"payload":{"prompt":"N50,000 is saved at the end of each year for 4 years at 20% compounded annually. How much of the final balance is interest? (Answer to the nearest naira.)","options":["N268,400","N160,000","N68,400","N122,080"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The final balance is 50,000 x [(1.2)^4 - 1]/0.2 = 268,400; deducting the N200,000 deposited gives interest of N68,400. Option A is the whole balance, and Option D is the interest for an annuity due."}},{"itemId":"29cb56e6-ff77-5e74-9e8b-45a970761087","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b809d06f-bdcb-5447-ba09-0b66f2884501","sourceKey":"bank:BUA216:MAT-051","parentItemId":null,"revision":1,"payload":{"prompt":"Treating ordinary-annuity deposits as a geometric progression, N20,000 deposited at the end of each year for 6 years at 10% compounded annually gives a final balance of 20,000(1 + 1.1 + (1.1)^2 + ... + (1.1)^5). What is this sum, to the nearest naira?","options":["N122,102","N154,312","N169,743","N193,261"],"correctOption":1,"section":"Mathematics of Finance","explanation":"This is a GP with first term 20,000, ratio 1.1 and 6 terms, so the sum is 20,000[(1.1)^6 - 1]/(1.1 - 1) = N154,312, the FV of an ordinary annuity. Option C adds one extra growth factor, the annuity due result, and Option A sums only 5 terms."}},{"itemId":"ba4bf191-b7d3-5921-ac45-967d01aa479b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1807aecb-e6dd-5041-8425-553e5b69b03e","sourceKey":"bank:BUA216:MAT-052","parentItemId":null,"revision":1,"payload":{"prompt":"Femi deposits N40,000 at the beginning of each year for 5 years, starting now, at 15% compounded annually. What is the future value at the end of year 5, to the nearest naira?","options":["N350,150","N269,695","N310,150","N230,000"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Deposits starting now form an annuity due: FV = A[(1 + i)^n - 1]/i x (1 + i) = 40,000 x [(1.15)^5 - 1]/0.15 x 1.15 = N310,150. Option B is the ordinary annuity result, which forgets that each deposit earns one extra year of interest."}},{"itemId":"7b84b3c2-6dad-597b-999a-c9b8f688bfbd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dd8b3e01-2bcc-5191-923c-578270d3e457","sourceKey":"bank:BUA216:MAT-053","parentItemId":null,"revision":1,"payload":{"prompt":"Using FV = A{(1 + i)^(n+1) - (1 + i)}/i, find the future value of N30,000 paid at the beginning of each year for 4 years at 25% compounded annually. (Answer to 2 decimal places.)","options":["N142,968.75","N172,968.75","N246,210.94","N216,210.94"],"correctOption":3,"section":"Mathematics of Finance","explanation":"FV = 30,000 x [(1.25)^5 - 1.25]/0.25 = 30,000 x (3.0518 - 1.25)/0.25 = N216,210.94, which equals the ordinary annuity amount x 1.25. Option B is the ordinary annuity figure, and Option C subtracts 1 instead of (1 + i)."}},{"itemId":"3c3e2070-5ed2-5956-aaaa-d67b97a2993b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5f8ec2fd-5aaa-5428-84b5-374d290b5ad2","sourceKey":"bank:BUA216:MAT-054","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is saved every year for 3 years at 10% compounded annually. By how much does the final balance exceed that of end-of-year deposits if each deposit is made at the beginning of the year instead? (Answer to the nearest naira.)","options":["N33,100","N10,000","N364,100","N30,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Ordinary: 100,000 x [(1.1)^3 - 1]/0.1 = 331,000; due: 331,000 x 1.1 = 364,100; the difference is N33,100, one extra year of interest on the ordinary balance. Option C is the annuity due balance itself, and Option B is just one year's interest on one deposit."}},{"itemId":"ed6967aa-916c-5ae6-a0eb-3440bb042636","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7a6255c7-b16a-5d6a-b442-a6cbe96380a1","sourceKey":"bank:BUA216:MAT-055","parentItemId":null,"revision":1,"payload":{"prompt":"A school deposits N20,000 at the beginning of each quarter for 2 years in an account paying 16% per annum compounded quarterly. What is the balance at the end of 2 years, to the nearest naira?","options":["N211,656","N191,656","N184,285","N200,448"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Rate per quarter is 4% over 8 deposits made at the start of each quarter: FV = 20,000 x [(1.04)^8 - 1]/0.04 x 1.04 = N191,656. Option C is the ordinary annuity result, and Option D treats the deposits as N80,000 a year at 16%."}},{"itemId":"377b7063-1878-507e-aef5-59d8921eb55c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8f6b560c-7dde-5caf-84d2-b488028aa6d1","sourceKey":"bank:BUA216:MAT-056","parentItemId":null,"revision":1,"payload":{"prompt":"Olu starts a savings plan by depositing N60,000 today and the same amount at the start of each of the next 5 years (6 deposits in all), earning 12% compounded annually. What is the balance at the end of year 6, to the nearest naira?","options":["N710,576","N545,341","N486,911","N426,911"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Deposits starting today form an annuity due of 6 payments: FV = 60,000 x [(1.12)^6 - 1]/0.12 x 1.12 = N545,341. Option C treats the deposits as end-of-year payments, and Option D counts only 5 deposits."}},{"itemId":"da1182f6-a0fb-5ff6-a510-b61999df44ef","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4f5c6529-a686-55a5-8f01-45bd0737b27d","sourceKey":"bank:BUA216:MAT-057","parentItemId":null,"revision":1,"payload":{"prompt":"N15,000 is invested immediately and then at the start of each following year, for 8 annual deposits, at 10% compounded annually. What is the accumulated value at the end of year 8, to the nearest naira?","options":["N88,026","N120,000","N188,692","N171,538"],"correctOption":2,"section":"Mathematics of Finance","explanation":"'Invested immediately' signals an annuity due: FV = 15,000 x [(1.1)^8 - 1]/0.1 x 1.1 = N188,692. Option D is the ordinary annuity amount, and Option A is a present value rather than a future value."}},{"itemId":"4f71b99f-a71d-5f9c-85a5-69e76927c2a4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c7bfaf68-db86-5345-aa29-7ee3e566fab4","sourceKey":"bank:BUA216:MAT-058","parentItemId":null,"revision":1,"payload":{"prompt":"What lump sum must be invested today at 14% compounded annually to provide N150,000 at the end of each year for 5 years? (Answer to the nearest naira.)","options":["N389,526","N587,057","N514,962","N991,516"],"correctOption":2,"section":"Mathematics of Finance","explanation":"PV of an ordinary annuity = A[1 - (1 + i)^(-n)]/i = 150,000 x [1 - (1.14)^(-5)]/0.14 = N514,962. Option B is the annuity due value, and Option D is the future value of the payments."}},{"itemId":"afd3f453-5be4-58dd-82e2-935da6fc65ab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bb3f2b9b-db46-510d-be6d-e415d4cbc617","sourceKey":"bank:BUA216:MAT-059","parentItemId":null,"revision":1,"payload":{"prompt":"A car dealer offers a payment plan of N20,000 at the end of each month for 2 years. At 12% per annum compounded monthly, what is the cash-equivalent value today, to the nearest naira?","options":["N480,000","N429,116","N424,868","N405,612"],"correctOption":2,"section":"Mathematics of Finance","explanation":"With 1% a month and 24 payments, PV = 20,000 x [1 - (1.01)^(-24)]/0.01 = N424,868. Option D treats it as N240,000 a year at 12%, and Option B assumes payments at the start of each month."}},{"itemId":"0c49a74f-9e5d-5ffd-9c01-5afc90cfd6a6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8b9f8528-d474-57e1-a95a-ceeff6f9d139","sourceKey":"bank:BUA216:MAT-060","parentItemId":null,"revision":1,"payload":{"prompt":"Musa will receive N200,000 a year for 4 years, with the first payment at the end of year 3. At 10% compounded annually, what is the present value today, to the nearest naira?","options":["N633,973","N871,052","N476,313","N523,945"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The 4-payment annuity is worth 200,000 x [1 - (1.1)^(-4)]/0.1 = 633,973 one year before its first payment, i.e. at the end of year 2, so PV = 633,973 / (1.1)^2 = N523,945. Option C discounts for 3 years, double-counting a year, and Option A ignores the deferral."}},{"itemId":"d2d90911-daa7-5ccb-8843-f667b5344c16","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"88a6ec66-2883-50b2-ae5a-c131720076d9","sourceKey":"bank:BUA216:MAT-061","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value annuity factor for 6 years at 13%, to 4 decimal places?","options":["4.5172","3.9975","8.3227","2.8819"],"correctOption":1,"section":"Mathematics of Finance","explanation":"The factor is [1 - (1 + i)^(-n)]/i = [1 - (1.13)^(-6)]/0.13 = 3.9975. Option A is the annuity due factor, and Option C is the future value annuity factor."}},{"itemId":"2eda491a-588f-500f-8b3a-ffe5fecb86b6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"395f4c2c-3d9c-5278-ae75-3c45d846b079","sourceKey":"bank:BUA216:MAT-062","parentItemId":null,"revision":1,"payload":{"prompt":"Grace invests the present value of N100,000 a year for 3 years at 15% compounded annually (end-of-year withdrawals). What balance remains in the account immediately after the first withdrawal, to the nearest naira?","options":["N228,323","N262,571","N162,571","N128,323"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The deposit is 100,000 x [1 - (1.15)^(-3)]/0.15 = 228,323; with interest it grows to 262,571, and after withdrawing 100,000 the balance is N162,571, exactly the PV of the two remaining withdrawals. Option D forgets to add the year's interest before withdrawing."}},{"itemId":"ce886c6f-7788-53e9-813e-5f37505b1a97","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e21da646-fa85-59cb-92b7-314ee58096e1","sourceKey":"bank:BUA216:MAT-063","parentItemId":null,"revision":1,"payload":{"prompt":"What lump sum must be invested today at 14% compounded annually to provide N150,000 at the beginning of each year for 5 years, starting now? (Answer to the nearest naira.)","options":["N514,962","N587,057","N437,057","N669,245"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Payments starting now form an annuity due: PV = A[1 - (1 + i)^(-n)]/i x (1 + i) = 150,000 x 3.4331 x 1.14 = N587,057. Option A is the ordinary annuity value, which wrongly discounts the first payment for a year."}},{"itemId":"eb3a0ea5-30db-5949-8334-753b9385e6bf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"736872ff-93ad-53a3-88f9-33cd6f39e506","sourceKey":"bank:BUA216:MAT-064","parentItemId":null,"revision":1,"payload":{"prompt":"Using PV = A{(1 + i) - (1 + i)^(-n+1)}/i, find the present value of N90,000 payable at the beginning of each of the next 4 years at 20% compounded annually. (Answer to 2 decimal places.)","options":["N189,583.33","N322,986.11","N232,986.11","N279,583.33"],"correctOption":3,"section":"Mathematics of Finance","explanation":"PV = 90,000 x [1.2 - (1.2)^(-3)]/0.2 = 90,000 x (1.2 - 0.5787)/0.2 = N279,583.33. Option C is the ordinary annuity value, and Option B wrongly uses (1.2)^(-4) instead of (1.2)^(-(n - 1))."}},{"itemId":"cd2a7c9f-2439-536d-9101-91d4d9b2ed5c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e83d1600-7b3c-5e45-9653-a8b0a4499211","sourceKey":"bank:BUA216:MAT-065","parentItemId":null,"revision":1,"payload":{"prompt":"A shop's rent of N1,200,000 a year is paid in advance at the start of each year for 3 years. At 15% compounded annually, what is the present value of the rent, to the nearest naira?","options":["N3,150,851","N2,367,058","N3,600,000","N2,739,870"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Rent paid in advance is an annuity due: PV = 1,200,000 x [1 - (1.15)^(-3)]/0.15 x 1.15 = N3,150,851. Option D treats the rent as paid at year-end."}},{"itemId":"098f827b-d2f6-55a0-864a-205651c93dd0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1377940a-3176-5248-9a7a-6ad6f69656c4","sourceKey":"bank:BUA216:MAT-066","parentItemId":null,"revision":1,"payload":{"prompt":"A lottery winner will receive N2,000,000 a year for 5 years, with the first payment today. At 12% compounded annually, what is the prize worth today, to the nearest naira?","options":["N7,209,552","N12,705,695","N8,074,699","N5,674,269"],"correctOption":2,"section":"Mathematics of Finance","explanation":"First payment today means an annuity due: PV = 2,000,000 x [1 - (1.12)^(-5)]/0.12 x 1.12 = N8,074,699. Option A is the ordinary annuity value and Option B is a future value."}},{"itemId":"e6c4af77-4fa2-53e9-acbd-0db6cf7fdb1c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2c838367-0750-57bb-a7d4-605a1cd7547d","sourceKey":"bank:BUA216:MAT-067","parentItemId":null,"revision":1,"payload":{"prompt":"For payments of N250,000 a year for 4 years at 10% compounded annually, by how much does the present value of an annuity due exceed that of an ordinary annuity? (Answer to the nearest naira.)","options":["N79,247","N25,000","N100,000","N871,713"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Ordinary PV = 250,000 x 3.1699 = 792,466; due PV = 792,466 x 1.1 = 871,713; the gap is N79,247. Option D is the annuity due PV itself, and Option B is only one year's interest on one payment."}},{"itemId":"a77ebe8d-66f9-598a-9cab-e4240139521c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"829b77f0-74dd-5a97-a1ac-b0b1a12d8e16","sourceKey":"bank:BUA216:MAT-068","parentItemId":null,"revision":1,"payload":{"prompt":"A tenant pays N50,000 at the beginning of each month for 1 year. At 24% per annum compounded monthly, what is the present value of the payments, to the nearest naira?","options":["N483,871","N528,767","N600,000","N539,342"],"correctOption":3,"section":"Mathematics of Finance","explanation":"With 2% a month, PV = 50,000 x [1 - (1.02)^(-12)]/0.02 x 1.02 = N539,342. Option B assumes end-of-month payments."}},{"itemId":"35a27f29-ea3c-566f-904f-f1cab48bbc2b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8d85c8c1-4a9c-5c13-ad64-6d24b62ff270","sourceKey":"bank:BUA216:MAT-069","parentItemId":null,"revision":1,"payload":{"prompt":"A trust will pay N180,000 at the end of every year forever. If the required return is 15% per annum, what is the present value of the trust payments? (Answer to the nearest naira.)","options":["N156,522","N1,380,000","N27,000","N1,200,000"],"correctOption":3,"section":"Mathematics of Finance","explanation":"PV of a perpetual annuity = A / i = 180,000 / 0.15 = N1,200,000. Option C multiplies by the rate instead of dividing, and Option B treats the first payment as received today."}},{"itemId":"db7d0707-aa0a-5d9c-b7aa-e9cae0342c8f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5f4df846-89fd-5d31-8b0e-591f1b4ffcc8","sourceKey":"bank:BUA216:MAT-070","parentItemId":null,"revision":1,"payload":{"prompt":"A family endows a scholarship with N5,000,000 invested at 12% per annum. What equal annual award can be paid at the end of each year forever without reducing the capital? (Answer to the nearest naira.)","options":["N41,666,667","N600,000","N416,667","N535,714"],"correctOption":1,"section":"Mathematics of Finance","explanation":"From PV = A / i, A = PV x i = 5,000,000 x 0.12 = N600,000. Option A divides instead of multiplying, and Option C divides by 12 as if spreading the fund over 12 years."}},{"itemId":"d70eabf6-5352-5d89-9ef2-903c78b8bba8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0eeed379-62c6-5e65-9d39-4e287ee9e6a0","sourceKey":"bank:BUA216:MAT-071","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity paying N90,000 at the end of each year is selling for N750,000. What annual rate of return does it offer? (Answer to 2 decimal places.)","options":["8.33%","12.00%","9.00%","14.40%"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Since PV = A / i, i = A / PV = 90,000 / 750,000 = 12.00%. Option A divides the price by the payment, which gives a number of years' purchase, not a rate."}},{"itemId":"f28d9a5a-6bcc-5506-bc67-7883320fea5d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"767bcff2-9d74-5768-a040-5868909ac9fd","sourceKey":"bank:BUA216:MAT-072","parentItemId":null,"revision":1,"payload":{"prompt":"An estate pays N100,000 a year forever, with the first payment received today. At 20% per annum, what is the present value of the payments? (Answer to the nearest naira.)","options":["N600,000","N500,000","N416,667","N20,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"With the first payment today, the value is today's payment plus a normal perpetuity: 100,000 + 100,000/0.2 = N600,000, the same as (A/i) x (1 + i). Option B is the ordinary perpetuity value, which assumes the first payment comes in one year."}},{"itemId":"58262919-cfbd-55b1-a32b-fa540ee77772","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2b4edb7e-f3fc-52e8-8273-61a688761ca6","sourceKey":"bank:BUA216:MAT-073","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity of N60,000 a year will start with its first payment at the end of year 4. At 12% compounded annually, what is its present value today, to the nearest naira?","options":["N398,597","N317,759","N500,000","N355,890"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The perpetuity is worth 60,000/0.12 = 500,000 one year before its first payment, at the end of year 3, so PV = 500,000 / (1.12)^3 = N355,890. Option B discounts for 4 years, and Option C ignores the delay."}},{"itemId":"23741f28-0934-56ae-8b9c-a2624c77535a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"90fbda95-69db-5ea0-8fce-a12eda20fd9c","sourceKey":"bank:BUA216:MAT-074","parentItemId":null,"revision":1,"payload":{"prompt":"An investment pays N25,000 at the end of every quarter forever. At 10% per annum compounded quarterly, what is its present value? (Answer to the nearest naira.)","options":["N250,000","N240,818","N4,000,000","N1,000,000"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Match the payment to the period rate: 10%/4 = 2.5% per quarter, so PV = 25,000 / 0.025 = N1,000,000. Option A divides a quarterly payment by an annual rate, Option C multiplies by 4 a second time, and Option B divides a quarterly payment by the effective annual rate."}},{"itemId":"f3212c5b-3f53-5458-ba05-acc6d59b425b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6499135-df59-540a-94d8-f5e3e41fd450","sourceKey":"bank:BUA216:MAT-075","parentItemId":null,"revision":1,"payload":{"prompt":"Using PV = A1/(r - g), where A1 is the payment one year from now, find the value of a stream that pays N120,000 next year and grows at 5% a year forever, if the required return is 15%. (Answer to the nearest naira.)","options":["N800,000","N1,200,000","N1,260,000","N600,000"],"correctOption":1,"section":"Mathematics of Finance","explanation":"PV = 120,000 / (0.15 - 0.05) = 120,000 / 0.10 = N1,200,000. Option A ignores the growth, Option D adds the growth rate to the discount rate instead of subtracting it, and Option C grows a payment that is already next year's."}},{"itemId":"3060aedc-4e23-5160-82a0-92d3a497889a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a1ff73bc-b170-5d8f-b7ec-93ab741a8121","sourceKey":"bank:BUA216:MAT-076","parentItemId":null,"revision":1,"payload":{"prompt":"A company has just paid an annual royalty of N100,000, which is expected to grow at 4% a year forever. Using PV = A1/(r - g), where A1 is next year's payment, and a 14% required return, what is the value of the future royalties? (Answer to the nearest naira.)","options":["N1,040,000","N1,000,000","N714,286","N742,857"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Next year's payment is A1 = 100,000 x 1.04 = 104,000, so PV = 104,000 / (0.14 - 0.04) = N1,040,000. Option B forgets to grow the payment just made by one year, and Option C ignores growth altogether."}},{"itemId":"3cbccd4d-1104-5a0f-94c8-e7e58f4cb175","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5dc57c0e-d79e-5e70-9b9a-fbd7c721cb22","sourceKey":"bank:BUA216:MAT-077","parentItemId":null,"revision":1,"payload":{"prompt":"A growing perpetuity whose first payment, one year from now, is N180,000 is valued at N2,000,000 using PV = A1/(r - g) and a 16% required return. What growth rate is assumed? (Answer to 2 decimal places.)","options":["5.00%","25.00%","7.00%","9.00%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Rearranging, r - g = A1 / PV = 180,000 / 2,000,000 = 0.09, so g = 0.16 - 0.09 = 7.00%. Option D is (r - g) itself, not g, and Option B adds instead of subtracting."}},{"itemId":"a191d130-5d4c-5d60-95c8-32baf390d36b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ec73ef1e-5b5d-53a4-b18c-5ce4fc90e7a9","sourceKey":"bank:BUA216:MAT-078","parentItemId":null,"revision":1,"payload":{"prompt":"Using PV = A1/(r - g), a growing perpetuity paying N64,000 next year and growing at 6% a year is priced at N800,000. What required return does this imply? (Answer to 2 decimal places.)","options":["2.00%","14.48%","14.00%","8.00%"],"correctOption":2,"section":"Mathematics of Finance","explanation":"r = A1/PV + g = 64,000/800,000 + 0.06 = 0.08 + 0.06 = 14.00%. Option D omits the growth rate, and Option A subtracts it."}},{"itemId":"bf544684-a1ed-5015-ad01-04a2a756534e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af1417d4-2839-559b-b4d7-6a7917bedadf","sourceKey":"bank:BUA216:MAT-079","parentItemId":null,"revision":1,"payload":{"prompt":"A company needs N2,000,000 in 5 years to replace a generator. What equal amount must it deposit at the end of each year into a sinking fund earning 12% compounded annually? (Answer to the nearest naira.)","options":["N400,000","N281,089","N314,819","N554,819"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Sinking fund payment = FV x i / [(1 + i)^n - 1] = 2,000,000 x 0.12 / [(1.12)^5 - 1] = N314,819. Option A ignores interest, and Option D uses the loan amortisation formula, which applies to a present value, not a future target."}},{"itemId":"5577fda2-ce1e-50ce-b295-f110c029c02d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"004f1124-1fb8-536c-841f-eafa99f9d7d6","sourceKey":"bank:BUA216:MAT-080","parentItemId":null,"revision":1,"payload":{"prompt":"A school must redeem a N5,000,000 bond in 4 years. It makes equal deposits at the end of every six months into a fund earning 16% per annum compounded semi-annually. What is each deposit, to the nearest naira?","options":["N470,074","N625,000","N493,438","N986,875"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Use 8% per half-year and 8 deposits: PMT = 5,000,000 x 0.08 / [(1.08)^8 - 1] = N470,074. Option D is the annual deposit at 16% for 4 years, and Option C halves that annual deposit, which ignores interest earned between half-years."}},{"itemId":"a2b43fa8-17f4-56a8-9083-f539b479d533","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5f1424d8-ecfb-5659-9059-427260d6ad9c","sourceKey":"bank:BUA216:MAT-081","parentItemId":null,"revision":1,"payload":{"prompt":"To accumulate N1,000,000 in 4 years, Ada makes equal deposits starting now and at the beginning of each of the next 3 years, at 10% compounded annually. What is each deposit, to the nearest naira?","options":["N195,883","N227,273","N163,797","N215,471"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Deposits starting now form an annuity due, so PMT = FV x i / {[(1 + i)^n - 1](1 + i)} = 1,000,000 x 0.1 / (4.641 x 1.1) = N195,883. Option D is the end-of-year (ordinary) sinking fund payment, which is larger because each deposit earns one year less interest."}},{"itemId":"3d77a777-7bd1-5168-b658-f54e2298a805","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0f3817d5-2e97-530f-8f27-90baf0b22065","sourceKey":"bank:BUA216:MAT-082","parentItemId":null,"revision":1,"payload":{"prompt":"A firm builds a sinking fund of N3,000,000 over 6 years with end-of-year deposits earning 15% compounded annually. How much of the N3,000,000 comes from interest? (Answer to the nearest naira.)","options":["N943,736","N2,056,264","N1,703,017","N2,700,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Each deposit is 3,000,000 x 0.15 / [(1.15)^6 - 1] = 342,710, so total deposits are 6 x 342,710 = 2,056,264 and interest is 3,000,000 - 2,056,264 = N943,736. Option B is the total deposited, not the interest, and Option C is the difference between the target and its present value."}},{"itemId":"392f3bd9-4c42-5a4f-95d7-d4d7f94ba913","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"099e7c45-85c2-5af2-a3ac-1346ef6d3f5c","sourceKey":"bank:BUA216:MAT-083","parentItemId":null,"revision":1,"payload":{"prompt":"A sinking fund targets N1,500,000 in 5 years with end-of-year deposits at 10% compounded annually. What is the balance in the fund immediately after the third deposit? (Answer to the nearest naira.)","options":["N900,000","N813,254","N1,239,669","N737,089"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Each deposit is 1,500,000 x 0.1 / [(1.1)^5 - 1] = 245,696; after 3 deposits the fund holds 245,696 x [(1.1)^3 - 1]/0.1 = N813,254. Option D ignores interest on earlier deposits, and Option C is the present value of the target at year 3, which would only be right for a single lump sum."}},{"itemId":"7fbb6929-9db5-5178-a0ca-8788987e23c7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"520b8d02-0ac0-58c0-a67e-90f20a1ffab0","sourceKey":"bank:BUA216:MAT-084","parentItemId":null,"revision":1,"payload":{"prompt":"A bank lends N1,000,000 for 4 years at 15% per annum, repayable in equal instalments at the end of each year. What is the annual instalment, to the nearest naira?","options":["N400,000","N200,265","N250,000","N350,265"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Loan instalment = PV x i / [1 - (1 + i)^(-n)] = 1,000,000 x 0.15 / [1 - (1.15)^(-4)] = N350,265. Option A adds a flat 15% interest on the original loan to an equal principal share, and Option B uses the sinking fund formula."}},{"itemId":"ac85a4d4-4134-5edb-a1f4-a7e4fa48001a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5a38d763-bf8c-50ef-8408-866844f6ae63","sourceKey":"bank:BUA216:MAT-085","parentItemId":null,"revision":1,"payload":{"prompt":"A N6,000,000 mortgage is repayable over 5 years by equal monthly instalments at the end of each month, at 18% per annum compounded monthly. What is the monthly instalment, to the nearest naira?","options":["N100,000","N152,361","N159,889","N1,918,667"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Use 1.5% per month over 60 months: PMT = 6,000,000 x 0.015 / [1 - (1.015)^(-60)] = N152,361. Option C divides the annual instalment by 12, which ignores monthly compounding, and Option A ignores interest."}},{"itemId":"153237ae-a2fa-539c-97a5-2230b15e9b1b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"842ee9a0-0577-59d5-aff7-a804155138c5","sourceKey":"bank:BUA216:MAT-086","parentItemId":null,"revision":1,"payload":{"prompt":"Ifeoma borrows N2,000,000 at 12% per annum for 5 years, repayable by equal end-of-year instalments of N554,819. How much of the first instalment is interest? (Answer to the nearest naira.)","options":["N48,000","N240,000","N314,819","N554,819"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Interest for a period is the opening balance x rate = 2,000,000 x 0.12 = N240,000. Option D is the whole instalment, and Option C is the principal repaid by that instalment."}},{"itemId":"cde2a2bd-b8c8-528c-b15b-db3bbbd8b1e5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb3059f1-b592-5d20-83a7-1087505e7cbf","sourceKey":"bank:BUA216:MAT-087","parentItemId":null,"revision":1,"payload":{"prompt":"Ifeoma borrows N2,000,000 at 12% per annum for 5 years, repayable by equal end-of-year instalments. How much principal is repaid by the first instalment? (Answer to the nearest naira.)","options":["N554,819","N240,000","N400,000","N314,819"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The instalment is 2,000,000 x 0.12 / [1 - (1.12)^(-5)] = 554,819; interest is 2,000,000 x 0.12 = 240,000; so principal repaid = 554,819 - 240,000 = N314,819. Option B is the interest portion, and Option C assumes equal principal repayments."}},{"itemId":"bccfcdba-047d-50ee-b0cc-f641bc224b89","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e91fa75e-37c7-58c5-b27c-4d1c2e1b561a","sourceKey":"bank:BUA216:MAT-088","parentItemId":null,"revision":1,"payload":{"prompt":"A N2,000,000 loan at 12% per annum is repaid by 5 equal end-of-year instalments. What is the outstanding balance immediately after the first instalment? (Answer to the nearest naira.)","options":["N1,445,181","N1,685,181","N1,600,000","N2,240,000"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Closing balance = opening balance + interest - payment = 2,000,000 + 240,000 - 554,819 = N1,685,181. Option A forgets to add the year's interest, and Option C assumes equal principal repayments of N400,000."}},{"itemId":"979c2a14-c7c6-5e23-875e-3c552dac3e9f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d0c4727d-dc32-5f80-82b5-1323cdbce62c","sourceKey":"bank:BUA216:MAT-089","parentItemId":null,"revision":1,"payload":{"prompt":"A N800,000 loan at 20% per annum is repaid by 4 equal end-of-year instalments. What is the outstanding balance immediately after the second instalment? (Answer to the nearest naira.)","options":["N472,131","N650,969","N400,000","N181,937"],"correctOption":0,"section":"Mathematics of Finance","explanation":"The instalment is 800,000 x 0.2 / [1 - (1.2)^(-4)] = 309,033. The balance after 2 payments is the PV of the 2 remaining instalments: 309,033 x [1 - (1.2)^(-2)]/0.2 = N472,131. Option C assumes equal principal repayments, Option D ignores interest, and Option B is the balance after only one instalment."}},{"itemId":"06a99ee6-34c8-5142-8e61-16076275abda","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2c6a0a34-4d7b-5a0b-9866-22f28e1ac65a","sourceKey":"bank:BUA216:MAT-090","parentItemId":null,"revision":1,"payload":{"prompt":"A N1,500,000 loan at 18% per annum is repaid in 3 equal end-of-year instalments. What is the total interest paid over the life of the loan? (Answer to the nearest naira.)","options":["N964,548","N810,000","N2,069,657","N569,657"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The instalment is 1,500,000 x 0.18 / [1 - (1.18)^(-3)] = 689,868; three instalments total 2,069,604, so interest is 2,069,604 - 1,500,000 = N569,657. Option B charges 18% on the original loan every year, ignoring that the balance falls, and Option A compounds the whole loan for 3 years."}},{"itemId":"7b0f4461-f6ad-5ac5-a07a-21a1e49a869a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3415d81a-79fc-52a6-86c0-28228c4235d2","sourceKey":"bank:BUA216:MAT-091","parentItemId":null,"revision":1,"payload":{"prompt":"A N900,000 equipment loan at 12% per annum is repaid by 4 equal annual instalments, with the first instalment paid immediately. What is each instalment, to the nearest naira?","options":["N225,000","N296,311","N331,868","N264,563"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Payments starting now form an annuity due, so PMT = PV x i / {[1 - (1 + i)^(-n)](1 + i)} = 900,000 x 0.12 / (3.0373 x 1.12) = N264,563. Option B is the instalment if the first payment came at the end of year 1, and Option C multiplies by 1.12 instead of dividing."}},{"itemId":"e3e8ad64-3c46-51b1-a3b1-d2c6c341cf01","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9e18f67f-d5f2-5f83-b1ad-f4388836d04c","sourceKey":"bank:BUA216:MAT-092","parentItemId":null,"revision":1,"payload":{"prompt":"A N400,000 loan is repaid over 2 years by equal end-of-quarter instalments, at 16% per annum compounded quarterly. What is each quarterly instalment, to the nearest naira?","options":["N62,296","N59,411","N50,000","N43,411"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Use 4% per quarter over 8 quarters: PMT = 400,000 x 0.04 / [1 - (1.04)^(-8)] = N59,411. Option A divides the annual instalment by 4, and Option D uses the sinking fund formula."}},{"itemId":"5374b152-50b8-5edd-91b5-0a550708ad1b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"52176466-c3c5-551b-b9c9-16591f835374","sourceKey":"bank:BUA216:MAT-093","parentItemId":null,"revision":1,"payload":{"prompt":"A N1,000,000 loan at 10% per annum is repaid by 3 equal end-of-year instalments of N402,114.80. How much interest is included in the second instalment? (Answer to the nearest naira.)","options":["N69,789","N332,326","N100,000","N66,667"],"correctOption":0,"section":"Mathematics of Finance","explanation":"After the first instalment the balance is 1,000,000 + 100,000 - 402,114.80 = 697,885.20, so year 2 interest is 697,885.20 x 0.10 = N69,789. Option C is year 1's interest on the original loan, and Option B is the principal repaid in year 2."}},{"itemId":"77f4b631-af5e-5625-9843-89ecf3a92333","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b7d05efa-1d86-5a74-8829-411db333ae41","sourceKey":"bank:BUA216:MAT-094","parentItemId":null,"revision":1,"payload":{"prompt":"A new staff member's salary starts at N1,200,000 in year 1 and rises by a fixed N50,000 each year (an arithmetic progression). What is the total salary over the first 10 years? (Answer to the nearest naira.)","options":["N14,250,000","N12,000,000","N14,500,000","N12,500,000"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Sum of an AP = n/2[2a + (n - 1)d] = 10/2 x [2,400,000 + 9 x 50,000] = N14,250,000. Option D gives a N50,000 increase in all 10 years including the first, and Option B ignores the increases."}},{"itemId":"97985b98-f67f-530f-8d2a-e50bd46b0cb9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9c0f87a5-ed47-50af-be35-7e18c98b713a","sourceKey":"bank:BUA216:MAT-095","parentItemId":null,"revision":1,"payload":{"prompt":"An amount grows at 8% compound interest, so the year-end balances form a geometric progression. If the balance at the end of year 1 is N108,000, what is the balance at the end of year 5 (the 5th term)? (Answer to the nearest naira.)","options":["N158,687","N142,560","N146,933","N136,049"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The nth term of a GP is ar^(n-1), so the 5th term is 108,000 x (1.08)^4 = N146,933 (equal to 100,000 x (1.08)^5). Option A uses one power too many, and Option B adds a constant amount each year as with simple interest."}},{"itemId":"eca0a682-0a4c-5736-8c3a-6e6d601f394d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5513ce7d-f6e5-5315-a9a5-ce9e1a988ac6","sourceKey":"bank:BUA216:MAT-096","parentItemId":null,"revision":1,"payload":{"prompt":"A naira expected some time in the future is not equivalent to a naira today. This idea is known as:","options":["The law of one price","Purchasing power parity","Time value of money","Liquidity preference ratio"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Time value of money says money today is worth more than the same amount later, because today's money can earn interest; it underlies simple and compound interest, present values and future values. Option B and Option A are exchange-rate and pricing ideas, not about the timing of cash."}},{"itemId":"74300998-c697-50fa-bdf1-0185e535c4e3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"82b0b7f9-e7e4-5716-a405-29051e5827f6","sourceKey":"bank:BUA216:MAT-097","parentItemId":null,"revision":1,"payload":{"prompt":"In mathematics of finance, interest is best described as:","options":["The total amount at the end of the period","The reduction in value of a future sum","The original amount invested","The payment made for the use of money"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Interest is the payment made for the use of money, earned by a lender or saver and paid by a borrower. Option C describes the principal, and Option A describes the amount or future value, which includes the principal."}},{"itemId":"fcb33f48-f022-5e26-adff-37c93619f514","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5cd36928-a855-59af-8c81-317c42d35bdf","sourceKey":"bank:BUA216:MAT-098","parentItemId":null,"revision":1,"payload":{"prompt":"Simple interest is interest earned on:","options":["The original amount invested (the principal) only","The principal plus interest previously earned","Each payment and the interest accumulated on it","The future value of the investment"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Simple interest is earned on the original principal only, so SI = P x T x R and the yearly interest stays constant. Option B describes compound interest, where interest is added to the principal as it is earned."}},{"itemId":"b59bea8d-1b36-5011-a01a-737b972989d7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7046967d-3bb4-55dd-9024-001bda9f5790","sourceKey":"bank:BUA216:MAT-099","parentItemId":null,"revision":1,"payload":{"prompt":"Interest earned on the original amount invested plus previously earned interest is called:","options":["Nominal interest","Compound interest","Simple interest","Discount interest"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Compound interest is earned on the principal plus interest already earned, so the base grows each year. Option C is earned on the principal only, which is why its yearly amount never changes."}},{"itemId":"85396197-449f-50e7-94eb-9439d03a28d9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"28df4b49-c2ee-5380-be90-c84c1d8dd9e9","sourceKey":"bank:BUA216:MAT-100","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT true of simple interest?","options":["The annual interest increases from year to year","The annual interest remains constant from year to year","The principal remains constant from year to year","It is calculated as P x T x R"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Under simple interest the principal does not change, so each year's interest is the same; a rising yearly interest is a feature of compound interest. Option B, Option C and Option D are all correct descriptions of simple interest."}},{"itemId":"61f81d42-6bff-5059-8682-8a605dac257d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0c65c95e-5580-5b95-a52a-97b781f59a8e","sourceKey":"bank:BUA216:MAT-101","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about compound interest is correct?","options":["The annual interest stays constant while the principal grows","It always gives less interest than simple interest for periods longer than one year","The principal stays constant while the annual interest grows","Both the annual interest and the amount on which interest is charged increase each year"],"correctOption":3,"section":"Mathematics of Finance","explanation":"With compound interest each year's interest is added to the balance, so both the base and the yearly interest grow, as in 10,000, 11,000 and 12,100 on N100,000 at 10%. Option B is backwards: for more than one year compounding gives more interest than simple interest."}},{"itemId":"910cc8c3-dc2d-54c9-8c81-d09231558994","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a246a79a-1d95-59de-a27d-dab20f91c8f5","sourceKey":"bank:BUA216:MAT-102","parentItemId":null,"revision":1,"payload":{"prompt":"A single amount of money invested for a specified period at a specified annual compound interest rate is called:","options":["A sinking fund","A lump sum","A perpetuity","An annuity"],"correctOption":1,"section":"Mathematics of Finance","explanation":"A lump sum is one single amount invested for a set period at a compound rate, valued with FV = PV(1 + i)^n. Option D and Option C involve a series of equal payments, not a single amount."}},{"itemId":"7115e43e-9566-56da-b976-9686337fb883","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"386718e5-194d-50c2-8983-5f7ff24701b6","sourceKey":"bank:BUA216:MAT-103","parentItemId":null,"revision":1,"payload":{"prompt":"The present value of a lump sum is:","options":["The sum of a series of equal payments and their interest","The amount an investment will grow to at a future date","The worth today of an amount to be received in the future","The total interest earned over the life of an investment"],"correctOption":2,"section":"Mathematics of Finance","explanation":"The present value is what a future amount is worth as at now, found by discounting: PV = FV/(1 + i)^n. Option B describes future value, the opposite direction."}},{"itemId":"9324a916-20b4-599a-858b-5a69fa72b064","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9f7f0592-26c9-51da-b213-d6731aa60e87","sourceKey":"bank:BUA216:MAT-104","parentItemId":null,"revision":1,"payload":{"prompt":"The formula PV = FV / (1 + i)^n is best described as:","options":["The effective annual rate formula","The reciprocal (reverse) of the future value formula, used for discounting","The future value of an ordinary annuity","The simple interest formula rearranged for principal"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Dividing by (1 + i)^n reverses compounding, so this formula discounts a future lump sum back to today. Option D would divide by (1 + nR), not (1 + i)^n, and Option A has the form (1 + r/m)^m - 1."}},{"itemId":"63637fd8-8f8a-50c9-928e-a4ceef07cfaf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"97163225-2dae-520d-83d7-999410eb40d7","sourceKey":"bank:BUA216:MAT-105","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank pays interest on a fixed deposit 'every four months'. In FV = PV(1 + i/m)^(n x m), what is m?","options":["2","3","12","4"],"correctOption":1,"section":"Mathematics of Finance","explanation":"A year has twelve months, so compounding every four months happens 12/4 = 3 times a year, giving m = 3. Option D is quarterly (every three months), and Option A is semi-annual."}},{"itemId":"6560dd07-ee6d-5095-a209-a43a152726a4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"17d1d559-e2f6-52cb-936c-292ce35c788d","sourceKey":"bank:BUA216:MAT-106","parentItemId":null,"revision":1,"payload":{"prompt":"Interest that is 'payable twice in a quarter' is compounded how many times a year?","options":["8","4","6","24"],"correctOption":0,"section":"Mathematics of Finance","explanation":"There are 4 quarters in a year and interest is paid twice in each, so m = 2 x 4 = 8. Option B is simple quarterly compounding, and Option D is twice a month."}},{"itemId":"fad698aa-bff6-5340-a3a4-a3240283ed3d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"34cc7e0e-1a5e-5ef4-9f0d-a99ee9ce0f39","sourceKey":"bank:BUA216:MAT-107","parentItemId":null,"revision":1,"payload":{"prompt":"A microfinance bank credits interest 'twice in a month'. What value of m should be used?","options":["24","6","8","12"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Twice in each of 12 months means interest is compounded 2 x 12 = 24 times a year. Option D is monthly compounding, and Option C is twice in a quarter."}},{"itemId":"73ba1942-448a-5213-b835-8d41ee6e1b76","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6173a5b-c115-508b-9c9f-3948412f63e6","sourceKey":"bank:BUA216:MAT-108","parentItemId":null,"revision":1,"payload":{"prompt":"In the continuous compounding formula FV = PV x e^(i x n), the symbol e is:","options":["The number of compounding periods per year","The base of the natural logarithm, approximately 2.71828","The exponent equal to the number of years","The effective annual rate"],"correctOption":1,"section":"Mathematics of Finance","explanation":"e is a mathematical constant, about 2.71828, the base of natural logarithms; continuous compounding raises it to the power i x n. Option D is EAR, and Option A is m in discrete compounding."}},{"itemId":"31fa9075-f6cf-57a0-9c32-ea9ef4f55356","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"42edf0c8-3348-52c1-93dd-b652363b4f95","sourceKey":"bank:BUA216:MAT-109","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula gives the present value of a sum FV due in n years when interest is compounded continuously at rate r?","options":["PV = FV x e^(-rn)","PV = FV x e^(rn)","PV = FV / (1 + r)^n","PV = FV / (1 + r/m)^(mn)"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Continuous discounting reverses FV = PV x e^(rn), so PV = FV x e^(-rn), the same as FV / e^(rn). Option B compounds forward, and Option C and Option D are discrete (annual and m-times-a-year) discounting."}},{"itemId":"4c47fc33-d291-5a7e-aa91-945100423c2b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"78d885e1-1bf4-50d0-b732-471ade5bf7cf","sourceKey":"bank:BUA216:MAT-110","parentItemId":null,"revision":1,"payload":{"prompt":"A series of equal payments or receipts that occur at the END of each period is called:","options":["A lump sum","A perpetual annuity","An annuity due","An ordinary annuity"],"correctOption":3,"section":"Mathematics of Finance","explanation":"An ordinary annuity has its equal payments at the end of each period, such as deposits made at each year-end. Option C has payments at the beginning of each period, and Option A is a single amount."}},{"itemId":"8ec87569-3951-52f3-908a-9507d33857b6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"296d1c6c-50ad-5f4e-a255-3a33545b610f","sourceKey":"bank:BUA216:MAT-111","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity due is a series of equal payments or receipts that occur:","options":["Indefinitely, with no end date","Once, at the end of the investment period","At the end of each period","At the beginning of each period"],"correctOption":3,"section":"Mathematics of Finance","explanation":"An annuity due has its payments at the start of each period, so each payment earns one extra period of interest compared with an ordinary annuity. Option C describes an ordinary annuity and Option A a perpetuity."}},{"itemId":"4d10683f-6627-5646-b897-e20563a4448b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"97126117-a5b6-5dfb-8bd1-707c9a8b7e07","sourceKey":"bank:BUA216:MAT-112","parentItemId":null,"revision":1,"payload":{"prompt":"A constant income stream of regularly recurring identical payments, paid out from a lump sum of capital and expected indefinitely, is:","options":["An ordinary annuity","A sinking fund","A perpetual annuity (perpetuity)","An annuity due"],"correctOption":2,"section":"Mathematics of Finance","explanation":"A perpetual annuity pays equal amounts forever, and its present value is simply A / i. Option A and Option D run for a fixed number of periods, and Option B is a fund built up to meet a future amount."}},{"itemId":"e3a49bc6-dc38-5e87-b161-e2c11b1f8796","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ce75b149-abc4-5b7e-b215-747f05c96dd8","sourceKey":"bank:BUA216:MAT-113","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the three types of annuity?","options":["Ordinary annuity, amortised loan and perpetual bond","Lump sum, annuity due and sinking fund","Simple annuity, compound annuity and continuous annuity","Ordinary annuity, annuity due and perpetual annuity"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Annuities are classified as ordinary (end of period), due (beginning of period) and perpetual (forever). Option B mixes in a lump sum and a sinking fund, which are not annuity types."}},{"itemId":"51d968fd-d3c1-597b-b01e-8f1dc0275fe0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15849052-1245-5ab6-b9ae-9dd43df0161c","sourceKey":"bank:BUA216:MAT-114","parentItemId":null,"revision":1,"payload":{"prompt":"Dayo signs up for a savings plan: 'pay N50,000 a year for 5 years, starting now'. Which formula should be used to find the value of his savings at the end of year 5?","options":["Present value of an ordinary annuity","Present value of a perpetuity","Future value of an ordinary annuity","Future value of an annuity due"],"correctOption":3,"section":"Mathematics of Finance","explanation":"'Starting now' means each payment is at the beginning of the period, which is an annuity due, and he wants the end value, so it is the future value of an annuity due. Option C would apply only if the first payment were one year from now."}},{"itemId":"c14be1f2-9abc-5f1e-9afb-aec5e4d469f7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7cdbd9f4-1d6d-5d4b-b19d-ffe6091a8451","sourceKey":"bank:BUA216:MAT-115","parentItemId":null,"revision":1,"payload":{"prompt":"A pension scheme promises 'N300,000 a year for 10 years, first payment one year from now'. Its value today is found as the present value of:","options":["A perpetuity","An ordinary annuity","A lump sum","An annuity due"],"correctOption":1,"section":"Mathematics of Finance","explanation":"'First payment one year from now' means payments at the end of each year, which is an ordinary annuity, and the value today is its present value. Option D would be used if the first payment were made today."}},{"itemId":"e0e6d852-6d33-5ef8-a6bc-4227fa65d60d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8b1f83be-8dfd-5fe0-b8a7-8ce97eb02124","sourceKey":"bank:BUA216:MAT-116","parentItemId":null,"revision":1,"payload":{"prompt":"How is the value of an annuity due obtained from the value of the corresponding ordinary annuity (same payment, rate and number of periods)?","options":["Multiply the ordinary annuity value by r","Add one payment to the ordinary annuity future value","Divide the ordinary annuity value by (1 + r)","Multiply the ordinary annuity value by (1 + r)"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Each payment of an annuity due happens one period earlier, so it gains one extra period of interest: annuity due = ordinary annuity x (1 + r), for both PV and FV. Option C goes the wrong way, making the annuity due smaller."}},{"itemId":"0fda80b0-213b-51df-822f-a625620ee37c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"58fc76d4-05fc-51ee-8863-f116149836d1","sourceKey":"bank:BUA216:MAT-117","parentItemId":null,"revision":1,"payload":{"prompt":"The formula PMT = FV x r / [(1 + r)^n - 1] is used to calculate:","options":["The present value of a perpetuity","The periodic deposit into a sinking fund to reach a target amount","The equal instalment on an amortised loan","The effective annual rate"],"correctOption":1,"section":"Mathematics of Finance","explanation":"This formula takes a future target (FV) and finds the equal end-of-period deposit needed, which is a sinking fund payment. Option C uses PV x r / [1 - (1 + r)^(-n)], because a loan starts from a present value."}},{"itemId":"c6085b2e-6ee7-5632-a2dd-19de5e4847e6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"407b3852-1acc-5377-b8af-0f7b478ade66","sourceKey":"bank:BUA216:MAT-118","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula gives the equal end-of-period instalment needed to repay a loan of PV over n periods at rate r?","options":["PMT = PV x r","PMT = PV x r / [1 - (1 + r)^(-n)]","PMT = PV / n","PMT = FV x r / [(1 + r)^n - 1]"],"correctOption":1,"section":"Mathematics of Finance","explanation":"A loan instalment is the payment whose present value equals the amount borrowed, so PMT = PV x r / [1 - (1 + r)^(-n)]. Option D is the sinking fund formula, Option C ignores interest, and Option A only covers interest, as in a perpetuity."}},{"itemId":"b7587cf6-dbd6-5a1c-a733-1542f0b67a92","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0bf37655-bc9e-575f-b8c9-c4ad9e091cf6","sourceKey":"bank:BUA216:MAT-119","parentItemId":null,"revision":1,"payload":{"prompt":"In a loan amortisation schedule, the principal repaid in a period is calculated as:","options":["Instalment minus the interest for the period","Opening balance multiplied by the rate","Instalment plus the interest for the period","Opening balance minus the instalment"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Each instalment first covers the period's interest, and whatever is left reduces the loan: principal repaid = payment - interest. Option B is the interest itself, and Option D skips adding the period's interest to the balance."}},{"itemId":"02fd38f2-4997-5139-b799-bf1c2d1fdbec","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"85dbcf01-5389-52c1-8c96-4a0f61219eed","sourceKey":"bank:BUA216:MAT-120","parentItemId":null,"revision":1,"payload":{"prompt":"The expression (1 + r/m)^m - 1, where r is a nominal annual rate compounded m times a year, measures:","options":["The effective annual rate","The nominal annual rate","The present value factor","The rate per compounding period"],"correctOption":0,"section":"Mathematics of Finance","explanation":"This converts a nominal rate compounded m times a year into the equivalent once-a-year rate, the effective annual rate, so different offers can be compared. Option B is the quoted rate before compounding, and Option D is r/m."}},{"itemId":"526d21a2-d5ec-540b-8a1f-1f37fe6cc719","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9b2c605f-5bba-51cf-8a3a-5fdde21c608c","sourceKey":"bank:BUA216:MAT-121","parentItemId":null,"revision":1,"payload":{"prompt":"For a given nominal annual rate, how does the effective annual rate change as interest is compounded more often?","options":["It stays equal to the nominal rate","It rises, approaching e^r - 1 under continuous compounding","It falls, approaching the nominal rate","It rises without any limit"],"correctOption":1,"section":"Mathematics of Finance","explanation":"More frequent compounding adds interest on interest more often, so the EAR rises, but it levels off at the continuous limit e^r - 1 (for 12% nominal, about 12.75%). Option D is wrong because that ceiling is fixed by e^r - 1."}},{"itemId":"228b2889-5121-505a-a7f8-7d0183a4055d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb3c7d98-044a-5450-b3df-161a7062c95b","sourceKey":"bank:BUA216:MAT-122","parentItemId":null,"revision":1,"payload":{"prompt":"The Rule of 72 is used to:","options":["Calculate the exact effective annual rate","Find the present value of a perpetuity","Determine the number of compounding periods in a year","Estimate the number of years it takes money to double"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Years to double is approximately 72 divided by the interest rate percentage, which is a quick check on any 'how many years' answer. It is an approximation, so Option A is wrong because it does not give an exact rate."}},{"itemId":"6497f545-377f-54cc-99f3-153557449dc5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bb477341-f2c7-5e72-adec-f4d78f1d5bec","sourceKey":"bank:BUA216:MAT-123","parentItemId":null,"revision":1,"payload":{"prompt":"When solving (1 + r)^n = FV/PV for n using logarithms, which statement is correct?","options":["Only natural logarithms give the correct answer","Either log base 10 or natural log may be used, provided the same base is used in numerator and denominator","The answer must be divided by the interest rate after taking logs","Only log base 10 gives the correct answer"],"correctOption":1,"section":"Mathematics of Finance","explanation":"n = log(FV/PV) / log(1 + r) gives the same result in any base because the base cancels out, as long as both logs use it. Option A and Option D wrongly restrict the base, and Option C confuses this with the continuous-compounding rearrangement."}},{"itemId":"8a0ce9e2-9f7b-5cf8-8b5e-4652eea02cef","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"06f808a7-8b18-52af-ae23-60c90663f332","sourceKey":"bank:BUA216:MAT-124","parentItemId":null,"revision":1,"payload":{"prompt":"The formula FV = A x {(1 + i)^n - 1} / i measures:","options":["The future value of a lump sum","The future value of an ordinary annuity","The future value of an annuity due","The present value of an ordinary annuity"],"correctOption":1,"section":"Mathematics of Finance","explanation":"This formula adds up end-of-period payments of A together with the compound interest on each, which is the future value of an ordinary annuity. Option C needs an extra (1 + i) factor, and Option D uses 1 - (1 + i)^(-n)."}},{"itemId":"ccc3f1c4-ed28-5d4c-99ad-bc88400f494c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"38a2e794-8830-58fb-a51a-90b44147e4e2","sourceKey":"bank:BUA216:MAT-125","parentItemId":null,"revision":1,"payload":{"prompt":"The formula PV = A x {(1 + i) - (1 + i)^(-n+1)} / i gives:","options":["The present value of an annuity due","The future value of an annuity due","The present value of a perpetuity","The present value of an ordinary annuity"],"correctOption":0,"section":"Mathematics of Finance","explanation":"This is the present value of payments made at the beginning of each period; it equals A[1 - (1 + i)^(-n)]/i x (1 + i). Option D lacks the extra (1 + i) factor, and Option B would involve (1 + i)^(n+1)."}},{"itemId":"772bd1f4-f007-53e1-be2e-4e5e659bfe3d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"80997c5a-36e0-5923-be52-a73a2c0f1bcb","sourceKey":"bank:BUA216:MAT-126","parentItemId":null,"revision":1,"payload":{"prompt":"The formula FV = A x {(1 + i)^(n+1) - (1 + i)} / i is used to find:","options":["The future value of an ordinary annuity","The present value of an annuity due","The future value of an annuity due","The sinking fund payment"],"correctOption":2,"section":"Mathematics of Finance","explanation":"Raising to (n + 1) and subtracting (1 + i) is the same as multiplying the ordinary annuity future value by (1 + i), which gives the future value of an annuity due. Option A is A[(1 + i)^n - 1]/i without the extra factor."}},{"itemId":"c14fbc98-a88c-5bd2-a835-14d2d2e896b3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b4c7239-e896-5566-8566-2d5a3d9d3565","sourceKey":"bank:BUA216:MAT-127","parentItemId":null,"revision":1,"payload":{"prompt":"The amount that must be invested today at a given compound rate to enable an investor to receive a series of equal end-of-period payments over a specific period is the:","options":["Present value of an ordinary annuity","Present value of a lump sum","Future value of an ordinary annuity","Sinking fund"],"correctOption":0,"section":"Mathematics of Finance","explanation":"Investing a sum today to fund equal year-end payments is the present value of an ordinary annuity, PV = A[1 - (1 + i)^(-n)]/i. Option C looks forward to the value at the end, and Option B relates to a single future payment."}},{"itemId":"c92833c6-4564-5b6f-924e-b5db5cca48c0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b0e67393-aac2-52ee-affb-4a8a884a3e95","sourceKey":"bank:BUA216:MAT-128","parentItemId":null,"revision":1,"payload":{"prompt":"The sum of all payments in an annuity together with the compound interest accumulated on each is the annuity's:","options":["Present value","Effective rate","Amortisation instalment","Future value"],"correctOption":3,"section":"Mathematics of Finance","explanation":"Adding every payment plus the interest each has earned by the end gives the future value of the annuity. Option A discounts payments back to today rather than accumulating them forward."}},{"itemId":"7b5d22f2-c9e9-52d1-b877-37b1e2a44529","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6853dfd2-3d56-5659-b6b2-19b4c3e2ae8c","sourceKey":"bank:BUA216:MAT-129","parentItemId":null,"revision":1,"payload":{"prompt":"For a growing perpetuity valued with PV = A1/(r - g), which condition must hold for the formula to give a meaningful value?","options":["The first payment A1 must be greater than PV","The growth rate g must equal r","The growth rate g must be greater than r","The required return r must be greater than the growth rate g"],"correctOption":3,"section":"Mathematics of Finance","explanation":"The denominator r - g must be positive; if g were equal to or above r, the formula would give an infinite or negative value. Option C and Option B break the formula for exactly that reason."}},{"itemId":"7330c851-b595-5839-9af1-daa02afa714c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"208f5ce7-6dce-5e7e-82d2-ab5180238344","sourceKey":"bank:BUA216:MAT-130","parentItemId":null,"revision":1,"payload":{"prompt":"The process of converting a future amount into its equivalent value today by applying an interest rate is called:","options":["Compounding","Discounting","Annualising","Amortising"],"correctOption":1,"section":"Mathematics of Finance","explanation":"Discounting works backwards from a future sum to its present value, using PV = FV/(1 + i)^n. Option A is the forward process that turns a present amount into a future value, and Option D is the gradual repayment of a loan."}},{"itemId":"a90294f6-23b1-5605-a89a-2acade70e0d0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d681f1b9-a62f-50de-abfd-92a954f7da22","sourceKey":"bank:BUA216:NPV-001","parentItemId":null,"revision":1,"payload":{"prompt":"A financial metric that assesses an investment's profitability by comparing the present value of its expected future cash flows with its initial investment cost is called the:","options":["Payback period","Future value of an annuity","Accounting rate of return (ARR)","Net present value (NPV)"],"correctOption":3,"section":"Net Present Value","explanation":"Net present value discounts the future cash flows to today and deducts the initial investment cost, so it shows whether a project would be profitable. Payback (A) only counts how long it takes to recover the outlay, and ARR (C) uses accounting profit rather than discounted cash flows. A future value (B) compounds forward instead of discounting back."}},{"itemId":"bf22a428-19ac-5389-b123-cce1825eef57","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"02663fd6-895f-59a9-bbb8-c0ef32343577","sourceKey":"bank:BUA216:NPV-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes how a project's net present value is obtained?","options":["Add up the expected future cash flows and deduct the initial investment cost","Divide the average annual accounting profit by the initial investment and multiply by 100","Compound the initial investment forward and compare it with the total future cash flows","Discount the expected future cash flows to present value and deduct the initial investment cost"],"correctOption":3,"section":"Net Present Value","explanation":"NPV converts each future cash flow into present value using the cost of capital and then subtracts the initial outlay. Option A ignores the time value of money because the cash flows are not discounted, and option B is the accounting rate of return. Option C works in future values and is not how NPV is defined."}},{"itemId":"51c768d3-5eff-5afe-8e02-70d23f1b1f43","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8e188cea-4dec-50e2-a382-b468f3bda59f","sourceKey":"bank:BUA216:NPV-003","parentItemId":null,"revision":1,"payload":{"prompt":"In the formula NPV = SUM[At / (1 + r)^n] - C0, what does C0 represent?","options":["The initial outlay or investment cost","The cash flow at time t","The number of years of the project","The rate or cost of capital"],"correctOption":0,"section":"Net Present Value","explanation":"C0 is the cost paid at the start (time 0), which is why it is deducted after the future cash flows have been discounted. At (B) is the cash flow received at time t, r (D) is the cost of capital used for discounting, and n (C) is the number of years."}},{"itemId":"86537dc4-e626-5a87-81a0-1a5af3e79937","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a7d95563-1a1f-5b4c-9e8a-34f65727c1b4","sourceKey":"bank:BUA216:NPV-004","parentItemId":null,"revision":1,"payload":{"prompt":"In NPV analysis, the rate r used to discount a project's future cash flows is normally the:","options":["Project's accounting rate of return","Firm's cost of capital","Project's payback period expressed as a percentage","Rate of inflation only"],"correctOption":1,"section":"Net Present Value","explanation":"The cash flows are discounted at the cost of capital, the return the firm's providers of finance require, so a positive NPV means the project earns more than that cost. The ARR (A) is an output of a different appraisal method, not the discount rate. Inflation alone (D) and the payback period (C) do not measure the required return on the firm's funds."}},{"itemId":"901018b7-e9f0-56bd-845e-2b751b2c99b1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1f9c835b-bd05-5aa1-8793-2410d05eedcf","sourceKey":"bank:BUA216:NPV-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which expression gives the present value (discount) factor for a cash flow received at the end of year n when the cost of capital is r?","options":["(1 + r)^n","1 / (1 + r)^n","[1 - (1 + r)^-n] / r","1 / (1 + r x n)"],"correctOption":1,"section":"Net Present Value","explanation":"The discount factor 1 / (1 + r)^n turns a single future amount into today's value under compound interest. Option A is the compound (future value) factor, the reverse of discounting. Option C is the present value annuity factor for a constant stream, and option D uses simple interest, which is not how cash flows are discounted in NPV."}},{"itemId":"08861936-0087-5c50-b5b4-d6f2ad6eb729","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d37ba650-f338-572a-b928-a7204b2008f2","sourceKey":"bank:BUA216:NPV-006","parentItemId":null,"revision":1,"payload":{"prompt":"A project's annual cash inflow is the same amount every year for five years. The quickest correct way to find the present value of these inflows is to:","options":["Multiply the annual cash inflow by the number of years","Multiply the annual cash inflow by the discount factor for year 5 only","Multiply the annual cash inflow by the present value annuity factor [1 - (1 + r)^-n] / r","Divide the annual cash inflow by the cost of capital"],"correctOption":2,"section":"Net Present Value","explanation":"When the cash flow is constant, the annuity factor adds up all the yearly discount factors in one step, so PV = annual inflow x [1 - (1 + r)^-n] / r. Option A ignores discounting altogether, and option B treats all five payments as if they arrived in year 5. Option D is the perpetuity formula, which assumes the inflow continues forever."}},{"itemId":"e88a33aa-055b-5576-8ca3-d79c942cd143","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"102ee060-0588-51b8-9df6-f44b6ff10ffc","sourceKey":"bank:BUA216:NPV-007","parentItemId":null,"revision":1,"payload":{"prompt":"Under the NPV decision rule, a project whose NPV is positive should be:","options":["Accepted","Postponed until its NPV becomes zero","Accepted only if its payback period is under two years","Rejected"],"correctOption":0,"section":"Net Present Value","explanation":"A positive NPV means the discounted inflows exceed the initial outlay, so the project adds value and should be accepted. Rejecting it (D) is the rule for a negative NPV. The NPV rule does not add a payback condition (C), and there is no reason to wait for the NPV to fall to zero (B)."}},{"itemId":"bcc2302d-9113-5d26-a6f1-be32ed213cf2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"36402f6d-c6ec-5f0b-b195-85574257c99a","sourceKey":"bank:BUA216:NPV-008","parentItemId":null,"revision":1,"payload":{"prompt":"Ijebu Plastics Ltd appraises a new moulding machine at its 14% cost of capital and finds an NPV of -N2.3 million. Based on the NPV rule, the company should:","options":["Accept the machine, because a negative NPV means the outlay is recovered quickly","Reject the machine, because the present value of its inflows is less than its cost","Accept the machine, because any project with cash inflows should be undertaken","Accept the machine, provided its IRR is above zero"],"correctOption":1,"section":"Net Present Value","explanation":"A negative NPV shows that the discounted inflows fall short of the initial outlay, so the project would reduce the firm's value and is rejected. Options A and C accept a project the NPV rule rejects, and option A also misreads what a negative NPV means. Option D is wrong because an IRR above zero but below 14% still leaves a negative NPV."}},{"itemId":"23aa66d7-4408-5d75-8d08-06838f3cd694","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"252abc08-137d-5cc0-b443-5a3434968b45","sourceKey":"bank:BUA216:NPV-009","parentItemId":null,"revision":1,"payload":{"prompt":"A project has an NPV of exactly zero at the firm's cost of capital. Which statement about it is correct under the NPV rules?","options":["Its payback period is exactly equal to its life","It earns exactly the cost of capital, and it may still be worth undertaking, for example to build experience or a portfolio","It earns a return above the cost of capital and must be ranked first","It must be rejected because it makes a loss equal to its initial outlay"],"correctOption":1,"section":"Net Present Value","explanation":"At a zero NPV the discounted inflows exactly cover the outlay, so the project earns exactly the cost of capital; it is worth undertaking to build experience or a portfolio. Option D is wrong because a zero NPV is not a loss of the outlay. Option C describes a positive NPV, and option A confuses NPV with payback."}},{"itemId":"141b0333-f727-5225-a5cc-85cae56eeafb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f1b19e3-c3c0-5684-9fec-01849b94d6e5","sourceKey":"bank:BUA216:NPV-010","parentItemId":null,"revision":1,"payload":{"prompt":"Projects that cannot be undertaken together, so that accepting one means rejecting the other, are called:","options":["Contingent projects","Mutually exclusive projects","Independent projects","Annuity projects"],"correctOption":1,"section":"Net Present Value","explanation":"Mutually exclusive projects compete for the same purpose, such as two alternative sites for one factory, so only one can be chosen. Independent projects (C) can each be accepted on their own merits. Contingent projects (A) depend on another project going ahead, and 'annuity projects' (D) simply describes even cash flows."}},{"itemId":"8cebfddf-480f-5305-8269-c93a42559cad","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0f90d10d-1df0-53b8-a5af-82b2dd18744a","sourceKey":"bank:BUA216:NPV-011","parentItemId":null,"revision":1,"payload":{"prompt":"Lekki Cold Stores must choose ONE of three alternative refrigeration systems. At its cost of capital the NPVs are: System P N4.2 million, System Q N6.8 million and System R N5.1 million. Which should it choose?","options":["System P","All three systems, since every NPV is positive","System R","System Q"],"correctOption":3,"section":"Net Present Value","explanation":"Because only one system can be installed, the projects are mutually exclusive and the one with the highest NPV, System Q at N6.8 million, is chosen. Systems P (A) and R (C) add less value. Option B would be right only for independent projects with no budget limit."}},{"itemId":"ee500524-a14e-5aa8-a7aa-b668ae1ae715","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e93ac5bf-2b91-57e9-a7f8-0e588bb37918","sourceKey":"bank:BUA216:NPV-012","parentItemId":null,"revision":1,"payload":{"prompt":"Kaduna Agro Ltd has no shortage of funds and is considering three INDEPENDENT projects with NPVs of N1.5 million, -N0.4 million and N0.2 million. Which decision is correct?","options":["Reject all three, because one of them has a negative NPV","Accept only the project with the NPV of N1.5 million","Accept all three, because their total NPV is positive","Accept the projects with NPVs of N1.5 million and N0.2 million and reject the other"],"correctOption":3,"section":"Net Present Value","explanation":"Independent projects do not compete with each other, so each one with a positive NPV is accepted and each one with a negative NPV is rejected. Option B applies the mutually exclusive rule of choosing only the highest NPV. Options C and A wrongly judge the projects as a group instead of one by one."}},{"itemId":"bb6875ff-c7ee-5b68-9c37-6f1d8fd186be","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"58c59beb-deb8-51b7-b439-c18a29a134df","sourceKey":"bank:BUA216:NPV-013","parentItemId":null,"revision":1,"payload":{"prompt":"The discount rate at which a project's NPV is exactly zero is the project's:","options":["Accounting rate of return (ARR)","Profitability index","Internal rate of return (IRR)","Cost of capital"],"correctOption":2,"section":"Net Present Value","explanation":"The IRR is the rate that makes the present value of the inflows equal the initial outlay, so NPV is zero at that rate; linear interpolation between a positive-NPV rate and a negative-NPV rate estimates it. The ARR (A) is based on accounting profit, and the profitability index (B) is a ratio, not a rate. The cost of capital (D) is the firm's required return, which the IRR is compared against."}},{"itemId":"4480dbaf-4ab4-54d4-b832-9e2fcb9b6c3e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e522e517-bcac-595c-bc57-512ca9e8c846","sourceKey":"bank:BUA216:NPV-014","parentItemId":null,"revision":1,"payload":{"prompt":"Using the internal rate of return method, an independent project should be accepted when:","options":["Its IRR is greater than zero","Its IRR is less than the cost of capital","Its IRR is greater than its accounting rate of return","Its IRR is greater than the cost of capital"],"correctOption":3,"section":"Net Present Value","explanation":"If the IRR exceeds the cost of capital, the project's NPV at the cost of capital is positive, so it adds value. A project with an IRR below the cost of capital (B) has a negative NPV. Comparing IRR with ARR (C) mixes two unrelated measures, and an IRR above zero (A) can still be below what the finance costs."}},{"itemId":"ccab8391-529f-57f0-bb67-6ec5879299d7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dedd7620-b176-571c-ae12-690df28cdbae","sourceKey":"bank:BUA216:NPV-015","parentItemId":null,"revision":1,"payload":{"prompt":"When estimating IRR by linear interpolation, IRR = L + [NPVL / (NPVL + |NPVH|)] x (H - L). Which statement about L and H is correct?","options":["L is a lower discount rate giving a negative NPV and H is a higher discount rate giving a positive NPV","L is a lower discount rate giving a positive NPV and H is a higher discount rate giving a negative NPV","L and H must both be rates at which the NPV is positive","L is the life of the project and H is the highest cash flow"],"correctOption":1,"section":"Net Present Value","explanation":"NPV falls as the discount rate rises, so the zero point lies between a lower rate with a positive NPV and a higher rate with a negative NPV. Option A reverses the signs, which cannot happen for a normal project, and option C would not bracket the zero point. Option D misreads the symbols entirely."}},{"itemId":"65795b30-8dcc-5779-b97d-121824d27ef6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b6261ae1-3e35-5d44-8ce2-be29142c6ba9","sourceKey":"bank:BUA216:NPV-016","parentItemId":null,"revision":1,"payload":{"prompt":"Two mutually exclusive projects give conflicting rankings: Project M has the higher NPV but Project N has the higher IRR. Unless a question specifically asks for IRR, which project should be chosen?","options":["Project M, because NPV is the preferred basis when NPV and IRR conflict","Project N, because a higher percentage return is always better","Neither project, because the methods disagree","Both projects, because each ranks first on one method"],"correctOption":0,"section":"Net Present Value","explanation":"When NPV and IRR rank mutually exclusive projects differently, the NPV ranking is followed because it measures the actual increase in wealth in naira. Option B relies on IRR, which can favour a smaller project with a high percentage return but less value added. Options D and C ignore that mutually exclusive projects require exactly one choice."}},{"itemId":"306931ad-c103-52a3-a1dd-aeb4e98f1827","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8a4ebff0-d1a1-59c0-8b13-4bc89a9c3bae","sourceKey":"bank:BUA216:NPV-017","parentItemId":null,"revision":1,"payload":{"prompt":"Ogun Ceramics must choose between two mutually exclusive kilns at a 12% cost of capital. Kiln A: NPV N3.6 million, IRR 19%. Kiln B: NPV N5.2 million, IRR 16%. Which kiln should be chosen?","options":["Kiln B, because it has the higher NPV","Kiln A, because it has the higher IRR","Neither kiln, because NPV and IRR give different rankings","Kiln A, because its IRR exceeds the cost of capital by more"],"correctOption":0,"section":"Net Present Value","explanation":"Both kilns are acceptable, but because only one can be chosen and the methods conflict, the higher NPV wins: Kiln B adds N5.2 million of value against N3.6 million. Options B and D follow the IRR ranking, which is not the default when the two methods conflict. Option C rejects two projects that both have positive NPVs."}},{"itemId":"e773a896-963c-570e-9b82-48427b781f07","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bf9369ff-8322-5420-a1c1-c6cdb6e93b32","sourceKey":"bank:BUA216:NPV-018","parentItemId":null,"revision":1,"payload":{"prompt":"The length of time it takes for a project's cash inflows to recover its initial outlay is the:","options":["Payback period","Project's economic life","Internal rate of return","Profitability index"],"correctOption":0,"section":"Net Present Value","explanation":"The payback period measures how quickly the initial investment is recovered; for even cash flows it is initial outlay / annual cash inflow. The IRR (C) is a percentage return and the profitability index (D) is a ratio of present values. The economic life (B) is how long the project runs, which is usually longer than its payback."}},{"itemId":"5a9121f8-6df1-59d2-bdb0-6eee0ab2976d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3d2fc6bd-56ba-59c4-b6bf-ca6494aa377d","sourceKey":"bank:BUA216:NPV-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a weakness of the simple payback period method?","options":["It does not measure the project's overall profitability","It ignores the time value of money","It is easy to calculate and understand","It ignores cash flows received after the payback period"],"correctOption":2,"section":"Net Present Value","explanation":"Simplicity is a strength of payback, which is why many firms use it as a quick screen. Its weaknesses are that it does not discount cash flows (B), it ignores everything after the outlay is recovered (D), and so it cannot show how much value the project adds overall (A)."}},{"itemId":"c4ec89a4-4a30-5e9d-adf3-a9d698cbf3ef","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"23772652-27b4-5bbb-ad8a-18da6a6e49a5","sourceKey":"bank:BUA216:NPV-020","parentItemId":null,"revision":1,"payload":{"prompt":"How does the discounted payback period differ from the simple payback period?","options":["It includes all cash flows after the payback point","It measures the time to recover the outlay from cash inflows that have first been discounted at the cost of capital","It always gives a shorter recovery period than simple payback","It measures the time to recover the outlay from undiscounted cash inflows"],"correctOption":1,"section":"Net Present Value","explanation":"Discounted payback uses the present values of the inflows, so it allows for the time value of money that simple payback ignores. Because discounted inflows are smaller, it is normally longer, not shorter (C), than simple payback. Option D describes simple payback, and option A is wrong because both payback measures ignore cash flows after recovery."}},{"itemId":"7440d476-53ec-5bfc-b4a0-d7284323a8e8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d857630f-21e9-588a-8a09-106ae4697f86","sourceKey":"bank:BUA216:NPV-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of the accounting rate of return (ARR)?","options":["It discounts cash flows at the cost of capital","It is expressed as a percentage of the investment","It ignores the timing of profits within the project's life","It is based on accounting profit rather than cash flow"],"correctOption":0,"section":"Net Present Value","explanation":"ARR is average annual profit divided by investment, multiplied by 100, so it uses undiscounted accounting profit and does not discount anything. It is indeed profit-based (D), expressed as a percentage (B), and blind to whether profits come early or late (C)."}},{"itemId":"23ae8388-7ce9-5a14-9774-d836b76579fd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0539cb48-a787-55be-9d75-fc73c6184e4c","sourceKey":"bank:BUA216:NPV-022","parentItemId":null,"revision":1,"payload":{"prompt":"The profitability index (PI) of a project is calculated as:","options":["Average annual profit / Initial investment x 100","Initial investment / Present value of future cash inflows","Present value of future cash inflows / Initial investment","Total undiscounted cash inflows / Initial investment"],"correctOption":2,"section":"Net Present Value","explanation":"The PI shows the present value generated per naira invested, so a PI above 1 corresponds to a positive NPV. Option B is the inverse, option D ignores discounting, and option A is the accounting rate of return."}},{"itemId":"35324d15-5d60-5349-901f-313fc4fb20f1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"69e5743f-c9d1-517a-8be4-3756fb804cd5","sourceKey":"bank:BUA216:NPV-023","parentItemId":null,"revision":1,"payload":{"prompt":"For a conventional project, which set of results is consistent with a positive NPV at the cost of capital?","options":["IRR equal to zero and profitability index equal to 1","IRR above the cost of capital and profitability index above 1","IRR below the cost of capital and profitability index above 1","IRR above the cost of capital and profitability index below 1"],"correctOption":1,"section":"Net Present Value","explanation":"A positive NPV means the PV of inflows exceeds the outlay, so the PI is above 1, and the rate that would bring NPV down to zero (the IRR) must be higher than the cost of capital. Options C and D each contain one signal of a negative NPV. Option A mixes up an IRR of zero with a PI of 1, which actually means IRR equals the cost of capital."}},{"itemId":"8cb96aeb-c7be-56a6-b869-0bd151d48a2f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"037b9e08-7736-5d68-b358-bcf70cc4fdc1","sourceKey":"bank:BUA216:NPV-024","parentItemId":null,"revision":1,"payload":{"prompt":"When a firm faces capital rationing (a limit on funds) and its projects are divisible, projects are best ranked by:","options":["Payback period","Size of the initial outlay","Accounting rate of return","Profitability index"],"correctOption":3,"section":"Net Present Value","explanation":"Under capital rationing the aim is the most NPV per naira of scarce capital, which is exactly what the profitability index measures. Payback (A) and ARR (C) ignore discounting and value added, and ranking by outlay (B) says nothing about value created."}},{"itemId":"ca353f49-90e9-5b78-a162-70754cd73f50","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f792ab3a-d670-5314-8d1b-ca15677af166","sourceKey":"bank:BUA216:NPV-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of the NPV method over the payback method?","options":["It shows how quickly the outlay is recovered","It does not require a cost of capital to be estimated","It considers the time value of money and all the project's cash flows","It expresses the result as a percentage that is easy to compare"],"correctOption":2,"section":"Net Present Value","explanation":"NPV discounts every cash flow over the whole life of the project, so it captures both timing and total value. Option B is false because NPV needs a cost of capital, option A is the purpose of payback, and option D describes IRR or ARR, since NPV is an absolute naira figure."}},{"itemId":"c54915a4-933c-5443-9420-ce752caa8385","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"339069a7-a4e8-5e74-80a2-dd67c2483e24","sourceKey":"bank:BUA216:NPV-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a limitation of the NPV method?","options":["It ignores the time value of money","It ignores cash flows that arise after the payback period","Its result depends on an estimated cost of capital, and it gives an absolute naira figure rather than a rate of return","It uses accounting profit instead of cash flow"],"correctOption":2,"section":"Net Present Value","explanation":"NPV is only as good as the discount rate chosen, and because it is a naira amount it does not show the return per naira invested. Options A, B and D are weaknesses of payback and ARR, not NPV, which discounts all cash flows."}},{"itemId":"89e2be52-69c8-5846-9d46-4039839e3918","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"663cec1e-1a78-54ae-8779-8cccb60ecadd","sourceKey":"bank:BUA216:NPV-027","parentItemId":null,"revision":1,"payload":{"prompt":"For a conventional project (an outlay followed by inflows), what happens to NPV as the discount rate increases?","options":["NPV first falls and then rises","NPV stays the same","NPV rises","NPV falls"],"correctOption":3,"section":"Net Present Value","explanation":"A higher rate makes every discount factor 1 / (1 + r)^n smaller, so the present value of the inflows shrinks while the outlay at time 0 stays the same; NPV therefore falls. This is why IRR interpolation needs a lower rate with a positive NPV and a higher rate with a negative NPV. Options C, B and A contradict how discounting works for a normal project."}},{"itemId":"2c7fcaec-b757-5dea-a28e-68c374d26cb9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"65cef76d-f612-5224-85af-f7f43e62051a","sourceKey":"bank:BUA216:NPV-028","parentItemId":null,"revision":1,"payload":{"prompt":"A student reads a year-5 discount factor of 0.42 off a table instead of the correct 0.4823. What is the effect on his NPV answer for a project with a positive year-5 inflow?","options":["There is no effect, because discount factors only affect payback","The NPV is understated, because the year-5 present value is too low","Only the IRR changes, not the NPV","The NPV is overstated, because the year-5 present value is too high"],"correctOption":1,"section":"Net Present Value","explanation":"A smaller factor makes the present value of the year-5 inflow too small, so the total PV of inflows and therefore the NPV are understated. Option D has the direction reversed. Options A and C are wrong because every discount factor feeds directly into the NPV."}},{"itemId":"373e5f8a-b92e-5418-bc6a-1338ab65fd60","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"02c74db4-ccf0-5275-874d-993b2527e3ad","sourceKey":"bank:BUA216:NPV-029","parentItemId":null,"revision":1,"payload":{"prompt":"A firm appraises five projects with payback, ARR, NPV and IRR. Which statement is correct?","options":["Payback and ARR always rank projects in the reverse order of NPV","Payback and ARR sometimes agree with NPV and IRR and sometimes do not, so the four methods should not be assumed to rank projects identically","NPV and IRR can never rank projects differently","All four methods always rank projects identically"],"correctOption":1,"section":"Net Present Value","explanation":"Payback and ARR ignore the time value of money, so their rankings may or may not match the discounted methods; in some cases one project ranks first on all four, but that cannot be assumed. Options D and A claim a fixed relationship that does not exist, and option C is false because NPV and IRR can conflict for mutually exclusive projects."}},{"itemId":"c1265610-5c9a-5d4f-8e4f-c8df3212010f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7e180ce2-8b01-5d22-ba6c-8b5257162ccd","sourceKey":"bank:BUA216:NPV-030","parentItemId":null,"revision":1,"payload":{"prompt":"In the assessment of risk, the payback period is classified as a:","options":["Measure of systematic risk","Non-probability method","Ratio of liquidity","Probability method"],"correctOption":1,"section":"Net Present Value","explanation":"Payback appears among the non-probability methods of assessing risk, together with sensitivity analysis, the risk adjusted method, the certainty equivalent factor and simulation, because a shorter payback limits exposure to uncertain later years. Probability methods (D) use expected value, variance and standard deviation. Payback is neither a beta-type measure (A) nor a liquidity ratio (C)."}},{"itemId":"183b1583-96e1-5cab-a90e-bff0a9e0a7a4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4d01ef1f-2071-50f8-84ad-93725943db1b","sourceKey":"bank:BUA216:NPV-031","parentItemId":null,"revision":1,"payload":{"prompt":"What is the discount factor for a cash flow received at the end of year 3 at a cost of capital of 15%, to 4 decimal places?","options":["0.7561","0.6575","1.5209","0.6897"],"correctOption":1,"section":"Net Present Value","explanation":"Discount factor = 1 / (1.15)^3 = 1 / 1.5209 = 0.6575. Option C is (1.15)^3 itself, the compounding factor, and option D uses simple interest, 1 / (1 + 0.15 x 3). Option A is the year-2 factor."}},{"itemId":"12c004f7-e466-54ae-98e6-d94ee3a884aa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"052af9f9-02fc-5966-ace0-f93f4dd60285","sourceKey":"bank:BUA216:NPV-032","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value annuity factor for 4 years at 10%, using [1 - (1 + r)^-n] / r, to 4 decimal places?","options":["3.6364","0.6830","3.1699","4.6410"],"correctOption":2,"section":"Net Present Value","explanation":"Annuity factor = [1 - (1.10)^-4] / 0.10 = (1 - 0.6830) / 0.10 = 3.1699. Option B is only (1.10)^-4, the single year-4 discount factor, and option D is the future value annuity factor [(1.10)^4 - 1] / 0.10. Option A multiplies the year-1 factor 0.9091 by 4."}},{"itemId":"b8074f45-043f-5681-8157-80517207b337","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9fa16e36-6d3c-51b9-b5d9-20c213502418","sourceKey":"bank:BUA216:NPV-033","parentItemId":null,"revision":1,"payload":{"prompt":"Bauchi Grains expects a project to produce a single cash inflow of N2,000,000 at the end of year 3. At a 12% cost of capital, the present value of this inflow is closest to:","options":["N2,809,860","N1,470,590","N1,594,390","N1,423,560"],"correctOption":3,"section":"Net Present Value","explanation":"PV = 2,000,000 / (1.12)^3 = 2,000,000 x 0.7118 = about N1,423,560. Option A compounds instead of discounting, and option B uses simple interest, 2,000,000 / 1.36. Option C discounts for only two years."}},{"itemId":"6726a434-7a97-5704-9c1e-29cf7bbcb8d7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a36cebe4-07ac-51ac-a9b0-5fb6a81b8625","sourceKey":"bank:BUA216:NPV-034","parentItemId":null,"revision":1,"payload":{"prompt":"Adeyemi Foods is considering a project costing N500,000 with cash inflows of N200,000, N250,000 and N180,000 at the end of years 1, 2 and 3. If the cost of capital is 10%, the NPV is closest to:","options":["N523,670","N23,670","N130,000","-N23,940"],"correctOption":1,"section":"Net Present Value","explanation":"PV of inflows = 200,000 x 0.9091 + 250,000 x 0.8264 + 180,000 x 0.7513 = about N523,670, so NPV = 523,670 - 500,000 = about N23,670. Option A is the PV of inflows before deducting the outlay, and option C ignores discounting (630,000 - 500,000). Option D discounts each inflow one year too many."}},{"itemId":"9eb78616-4781-56b8-bb09-dd4fefc417c4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d3941117-a9e0-5053-9fc9-b215f5ac1258","sourceKey":"bank:BUA216:NPV-035","parentItemId":null,"revision":1,"payload":{"prompt":"Kano Textiles Ltd plans a project costing N5,000,000 with expected cash inflows of N2,000,000, N2,500,000, N1,800,000 and N1,200,000 over years 1 to 4. At a cost of capital of 15%, the NPV (using discount factors to 4 decimal places) is closest to:","options":["N5,499,000","N499,000","N353,000","N2,500,000"],"correctOption":1,"section":"Net Present Value","explanation":"Using factors 0.8696, 0.7561, 0.6575 and 0.5718, the PV of inflows is about N5,499,000, so NPV = 5,499,000 - 5,000,000 = about N499,000. Option A forgets to deduct the outlay and option D adds up undiscounted cash flows. Option C wrongly treats the uneven flows as an annuity of their average, N1,875,000 a year."}},{"itemId":"ae1cc6a9-0359-5bee-a6d3-6dd639832080","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9ee0a163-d036-5f65-bc5a-f21e1dcd183d","sourceKey":"bank:BUA216:NPV-036","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N900,000 and is expected to generate N300,000, N350,000 and N400,000 at the end of years 1, 2 and 3. If the cost of capital is 18%, the NPV is closest to:","options":["-N150,900","N150,900","-N4,600","N150,000"],"correctOption":0,"section":"Net Present Value","explanation":"PV of inflows = 300,000 / 1.18 + 350,000 / (1.18)^2 + 400,000 / (1.18)^3 = about N749,050, so NPV = 749,050 - 900,000 = about -N150,950 and the project is rejected. Option D ignores discounting, and option B has the right size but the wrong sign. Option C discounts at 8% instead of 18%."}},{"itemId":"a87114d5-d1f9-55cf-af5b-8674bab1e7ea","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2810db96-21f5-54ad-a48e-d0340f9d621f","sourceKey":"bank:BUA216:NPV-037","parentItemId":null,"revision":1,"payload":{"prompt":"Eko Bottling Plc is evaluating a filling line costing N900,000. The expected cash inflows for years 1 to 5 are N250,000, N300,000, N300,000, N250,000 and N200,000. At a 12% cost of capital, the NPV is closest to:","options":["N48,300","N948,300","-N65,200","N400,000"],"correctOption":0,"section":"Net Present Value","explanation":"Discounting each inflow at 12% (factors 0.8929, 0.7972, 0.7118, 0.6355, 0.5674) gives a PV of about N948,270, so NPV = 948,270 - 900,000 = about N48,270. Option B is the PV of inflows without deducting the cost, and option D is the undiscounted surplus. Option C leaves out the year-5 inflow."}},{"itemId":"216cb63f-c450-521d-8f7e-34c224bd324c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1f9c128c-7174-5408-a965-e430af57234b","sourceKey":"bank:BUA216:NPV-038","parentItemId":null,"revision":1,"payload":{"prompt":"A machine costs N750,000 and will generate a net cash inflow of N250,000 at the end of each year for 4 years. With a cost of capital of 10%, the NPV is closest to:","options":["N42,470","N121,710","N250,000","N792,470"],"correctOption":0,"section":"Net Present Value","explanation":"Because the inflow is constant, PV = 250,000 x [1 - (1.10)^-4] / 0.10 = 250,000 x 3.1699 = about N792,470, so NPV = 792,470 - 750,000 = about N42,470. Option C ignores discounting, and option D is the PV of inflows before the outlay is deducted. Option B wrongly treats the inflows as an annuity due, as if the first one arrived immediately."}},{"itemId":"8708ebed-0b1b-589c-8617-7bb673a2ed1c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"23f86e00-9364-540a-bc07-1da22a3ebb14","sourceKey":"bank:BUA216:NPV-039","parentItemId":null,"revision":1,"payload":{"prompt":"Onitsha Motors Ltd is considering an investment of N2,400,000 that yields N600,000 a year at the end of each of the next 5 years. If the cost of capital is 14%, the NPV is closest to:","options":["N271,000","N600,000","-N842,000","-N340,000"],"correctOption":3,"section":"Net Present Value","explanation":"PV of inflows = 600,000 x [1 - (1.14)^-5] / 0.14 = 600,000 x 3.4331 = about N2,060,000, so NPV = 2,060,000 - 2,400,000 = about -N340,000 and the project should be rejected. Option B ignores the time value of money, and option A discounts at 4% instead of 14%. Option C discounts all five inflows as if each arrived in year 5."}},{"itemId":"68e46cd3-67d0-56b5-941a-a41bf64314ab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"36e4af9d-bf9e-580f-87e3-711c5ad2b715","sourceKey":"bank:BUA216:NPV-040","parentItemId":null,"revision":1,"payload":{"prompt":"Using the present value annuity factor, find the NPV of a project costing N1,500,000 that returns N600,000 at the end of each year for 3 years, if the cost of capital is 8%. The NPV is closest to:","options":["N6,000,000","N1,546,300","N46,300","N300,000"],"correctOption":2,"section":"Net Present Value","explanation":"Annuity factor = [1 - (1.08)^-3] / 0.08 = 2.5771, so PV = 600,000 x 2.5771 = about N1,546,260 and NPV = 1,546,260 - 1,500,000 = about N46,260. Option B omits the outlay and option D ignores discounting. Option A uses the perpetuity formula 600,000 / 0.08, as if the inflows lasted forever."}},{"itemId":"16d4fb5a-d7ad-58bd-a5bc-423aafe7e977","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9d4ae715-8404-587c-afb8-608e5acdd140","sourceKey":"bank:BUA216:NPV-041","parentItemId":null,"revision":1,"payload":{"prompt":"Ibadan Print House can buy a press that would save N120,000 in cash at the end of each year for 5 years. If its cost of capital is 12%, what is the most it should pay for the press (the price at which NPV would be zero)?","options":["N600,000","N340,460","N432,570","N484,480"],"correctOption":2,"section":"Net Present Value","explanation":"The break-even price equals the PV of the savings: 120,000 x [1 - (1.12)^-5] / 0.12 = 120,000 x 3.6048 = about N432,570; paying more gives a negative NPV. Option A ignores discounting, and option B discounts every saving as if it arrived in year 5. Option D treats the savings as an annuity due."}},{"itemId":"930562e7-e9b4-5334-8503-d23801a01434","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bd322914-7006-5f72-9e87-9915d5aba611","sourceKey":"bank:BUA216:NPV-042","parentItemId":null,"revision":1,"payload":{"prompt":"A delivery van costs N1,200,000 and will generate net cash inflows of N400,000 at the end of each year for 4 years. It will also be sold for scrap for N100,000 at the end of year 4. At a 12% cost of capital, the NPV is closest to:","options":["N500,000","N14,900","N78,500","N114,900"],"correctOption":2,"section":"Net Present Value","explanation":"PV = 400,000 x 3.0373 + 100,000 x 0.6355 = 1,214,940 + 63,550 = about N1,278,490, so NPV = about N78,490. Option B leaves out the scrap value, and option A ignores discounting. Option D adds the scrap value without discounting it back from year 4."}},{"itemId":"3332ca2d-7773-5448-b9b0-990d4e6deff5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"52355387-b0c3-5c76-ab32-22afd25ac76d","sourceKey":"bank:BUA216:NPV-043","parentItemId":null,"revision":1,"payload":{"prompt":"Jos Dairy must choose ONE of two machines, each costing N1,000,000, at a 10% cost of capital. Machine X returns N450,000 a year for 3 years. Machine Y returns N200,000, N400,000 and N700,000 in years 1, 2 and 3. Which machine should be chosen?","options":["Machine Y, because its single largest inflow (N700,000) is the highest of any year","Machine Y, NPV about N38,300","Both machines, because both have positive NPVs","Machine X, NPV about N119,100"],"correctOption":3,"section":"Net Present Value","explanation":"NPV of X = 450,000 x 2.4869 - 1,000,000 = about N119,080, and NPV of Y = 200,000 x 0.9091 + 400,000 x 0.8264 + 700,000 x 0.7513 - 1,000,000 = about N38,320. Since the machines are mutually exclusive, X, with the higher NPV, is chosen. Option A ignores timing, because Y's large inflow comes late and is heavily discounted, and option C applies the independent-project rule."}},{"itemId":"ee789fcf-def8-5439-8c18-3c699461b64b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"613f3b95-6572-52d2-9ff7-010cf9e66c5b","sourceKey":"bank:BUA216:NPV-044","parentItemId":null,"revision":1,"payload":{"prompt":"A project requires an outlay of N3,000,000 and will produce equal cash inflows at the end of each of the next 4 years. At a 10% cost of capital, what minimum annual inflow is needed for the project to break even in NPV terms (NPV = 0)?","options":["N946,410","N646,410","N1,098,080","N750,000"],"correctOption":0,"section":"Net Present Value","explanation":"Set annual inflow x annuity factor = outlay, so annual inflow = 3,000,000 / 3.1699 = about N946,410. Option D simply divides by 4 and ignores the time value of money. Option B divides by the future value annuity factor instead of the present value factor, and option C compounds the outlay for four years and then divides by 4."}},{"itemId":"f549072c-ca57-501d-9451-c2c0c6cb9109","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4bbaae1e-34c7-50b6-8d42-b3c05a5ce6b5","sourceKey":"bank:BUA216:NPV-045","parentItemId":null,"revision":1,"payload":{"prompt":"A toll bridge costs N5,000,000 and is expected to yield a net cash inflow of N600,000 at the end of every year forever. If the cost of capital is 10%, its NPV is:","options":["-N4,454,545","N6,000,000","-N1,000,000","N1,000,000"],"correctOption":3,"section":"Net Present Value","explanation":"The PV of a perpetual inflow is A / r = 600,000 / 0.10 = N6,000,000, so NPV = 6,000,000 - 5,000,000 = N1,000,000. Option B is the PV before deducting the cost, and option C reverses the subtraction. Option A counts only the first year's inflow, 600,000 / 1.10 - 5,000,000."}},{"itemId":"3314f685-19a3-57eb-ae61-6bad30c8cdfb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5d32e8cd-6b16-5889-a777-41427de33227","sourceKey":"bank:BUA216:NPV-046","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N840,000 and generates an equal net cash inflow of N240,000 a year. Its payback period is:","options":["3.0 years","4.0 years","0.29 years","3.5 years"],"correctOption":3,"section":"Net Present Value","explanation":"Payback = initial outlay / annual cash inflow = 840,000 / 240,000 = 3.5 years. Option C divides the inflow by the outlay, the wrong way round. Options A and B round to whole years and lose the half year needed to recover the remaining N120,000."}},{"itemId":"91786ccd-06a5-5fa0-803c-6bd79f1337ef","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ca915fe0-a6b3-5d10-baac-48b81ac0f818","sourceKey":"bank:BUA216:NPV-047","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N700,000 and its cash inflows for years 1 to 4 are N200,000, N300,000, N250,000 and N150,000. Assuming cash flows arise evenly within each year, its payback period is:","options":["2.8 years","2.67 years","3.11 years","3.0 years"],"correctOption":0,"section":"Net Present Value","explanation":"After 2 years N500,000 has been recovered, leaving N200,000, which is 200,000 / 250,000 = 0.8 of year 3, so payback = 2.8 years. Option C divides the outlay by the average inflow (700,000 / 225,000), which only works for even cash flows. Option B divides the shortfall by the year-2 inflow instead of the year-3 inflow, and option D rounds up to a whole year."}},{"itemId":"fc1eb619-be6f-50ad-9c33-33ad9f9cdc08","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5da88f62-3e07-580b-85ad-f88a9c431f09","sourceKey":"bank:BUA216:NPV-048","parentItemId":null,"revision":1,"payload":{"prompt":"Abeokuta Printers invests N1,000,000 in a project with cash inflows of N300,000, N400,000 and N500,000 in years 1, 2 and 3, arising evenly through each year. To the nearest month, the payback period is:","options":["2 years 7 months","2 years 6 months","3 years 0 months","2 years 9 months"],"correctOption":0,"section":"Net Present Value","explanation":"After 2 years N700,000 is recovered, leaving N300,000; 300,000 / 500,000 = 0.6 of a year = 0.6 x 12 = 7.2 months, so payback is about 2 years 7 months. Option B reads 2.6 years as 2 years 6 months, forgetting to convert the decimal into months. Option D divides the shortfall by the year-2 inflow, and option C rounds up to a whole year."}},{"itemId":"899388eb-5ea4-5e73-93de-f065a5033088","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7cb1bf6c-bb80-530d-92f5-8ce65dd8cdf1","sourceKey":"bank:BUA216:NPV-049","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N500,000 and its cash inflows for years 1 to 4 are N200,000, N250,000, N200,000 and N150,000, arising evenly through each year. Using a 10% cost of capital, the discounted payback period, to 2 decimal places, is:","options":["2.56 years","2.25 years","2.74 years","3.00 years"],"correctOption":2,"section":"Net Present Value","explanation":"Discounted inflows are about N181,820, N206,610 and N150,260 for years 1 to 3; after 2 years N388,430 is recovered, leaving N111,570, so payback = 2 + 111,570 / 150,260 = 2.74 years. Option B is the simple (undiscounted) payback, and option D rounds up to a whole year. Option A divides the remaining amount by the undiscounted year-3 inflow."}},{"itemId":"9f553978-a8d9-511d-978b-da9094295bed","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"111ad933-aa18-5825-a307-b6dfb3401664","sourceKey":"bank:BUA216:NPV-050","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N600,000 and earns N250,000 a year for 4 years, arising evenly through each year. At a 10% cost of capital, how much longer is its discounted payback period than its simple payback period (to 2 decimal places)?","options":["0.00 years","0.60 years","0.88 years","0.48 years"],"correctOption":3,"section":"Net Present Value","explanation":"Simple payback = 600,000 / 250,000 = 2.40 years. Discounted inflows are N227,270, N206,610 and N187,830, so discounted payback = 2 + (600,000 - 433,880) / 187,830 = 2.88 years, a difference of 0.48 years. Option A wrongly assumes discounting has no effect, option C compares with 2 whole years instead of 2.40, and option B rounds discounted payback up to 3 years."}},{"itemId":"6744079e-16ba-56be-92c9-ff253ae9fa8e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"40448642-c4aa-5721-bd68-10ab24dc2607","sourceKey":"bank:BUA216:NPV-051","parentItemId":null,"revision":1,"payload":{"prompt":"A machine costing N2,000,000 is expected to earn accounting profits of N300,000, N400,000, N500,000 and N400,000 over its 4-year life. Taking ARR = (average annual profit / initial investment) x 100, the ARR is:","options":["40%","20%","80%","5%"],"correctOption":1,"section":"Net Present Value","explanation":"Average annual profit = (300,000 + 400,000 + 500,000 + 400,000) / 4 = N400,000, so ARR = 400,000 / 2,000,000 x 100 = 20%. Option C uses total profit instead of the yearly average, and option A divides by average investment (half the cost), which is not the definition stated. Option D divides the average profit by the cost and then by 4 again."}},{"itemId":"80bce7e7-f18c-5134-80f5-934344dd8360","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2d0a21f-d154-585a-a082-4a2a515032c0","sourceKey":"bank:BUA216:NPV-052","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N1,000,000, has a scrap value of N200,000 at the end of its 4-year life, and earns an average annual accounting profit of N150,000. Taking ARR = (average annual profit / average investment) x 100, where average investment = (cost + scrap value) / 2, the ARR is:","options":["30%","15%","18.75%","25%"],"correctOption":3,"section":"Net Present Value","explanation":"Average investment = (1,000,000 + 200,000) / 2 = N600,000, so ARR = 150,000 / 600,000 x 100 = 25%. Option B divides by the initial cost instead of the average investment. Option C uses cost minus scrap (N800,000), and option A halves the cost but ignores the scrap value (N500,000)."}},{"itemId":"05359c79-8765-5e53-84eb-ba47c9096585","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8f116a44-e606-5db6-a0a8-d71ad0170ca4","sourceKey":"bank:BUA216:NPV-053","parentItemId":null,"revision":1,"payload":{"prompt":"Benin Bakeries buys an oven for N900,000 with a 3-year life and no scrap value, depreciated on a straight-line basis. Annual net cash inflows are N420,000, N450,000 and N480,000. Taking ARR = (average annual profit / initial investment) x 100, the ARR to 2 decimal places is:","options":["16.67%","5.56%","50.00%","33.33%"],"correctOption":0,"section":"Net Present Value","explanation":"Depreciation is 900,000 / 3 = N300,000 a year, so profits are N120,000, N150,000 and N180,000, an average of N150,000; ARR = 150,000 / 900,000 x 100 = 16.67%. Option C uses average cash flow (N450,000) instead of profit, forgetting depreciation. Option D divides by average investment (N450,000), and option B divides by the life a second time."}},{"itemId":"b3a0108d-72dd-58d9-ad59-4a8fe6f28a4d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"76e1b4a3-1b5a-5409-bd85-aab8ba5b6361","sourceKey":"bank:BUA216:NPV-054","parentItemId":null,"revision":1,"payload":{"prompt":"Calabar Fisheries requires a minimum ARR of 20%. A proposed boat costs N4,000,000 and is expected to earn total accounting profits of N2,880,000 over its 4-year life. Taking ARR = (average annual profit / initial investment) x 100, what is the ARR and the decision?","options":["18%; reject, because it is below the 20% target","36%; accept, because it is above the 20% target","18%; accept, because any positive ARR is acceptable","72%; accept, because it is above the 20% target"],"correctOption":0,"section":"Net Present Value","explanation":"Average annual profit = 2,880,000 / 4 = N720,000, so ARR = 720,000 / 4,000,000 x 100 = 18%, which is below the 20% target, so the boat is rejected. Option D uses total profit instead of the yearly average. Option C has the right ARR but ignores the target, and option B divides by half the cost instead of the initial investment stated."}},{"itemId":"2d1c548f-7457-5a00-8c25-257228c412a5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dce59ee8-d4c0-56a1-a687-936908344497","sourceKey":"bank:BUA216:NPV-055","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N600,000 and produces N250,000 at the end of each year for 3 years. At a 10% cost of capital, its profitability index (PV of inflows / initial investment) to 2 decimal places is:","options":["1.04","1.25","0.04","0.97"],"correctOption":0,"section":"Net Present Value","explanation":"PV of inflows = 250,000 x 2.4869 = about N621,710, so PI = 621,710 / 600,000 = 1.04; as this is above 1, the project is acceptable. Option B uses undiscounted inflows (750,000 / 600,000), and option D inverts the ratio. Option C divides the NPV by the outlay."}},{"itemId":"4fe82902-9f0b-5af8-b834-9bafa0451637","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9ebb3ce4-8634-5ec4-aa9e-c9e9e0996a8a","sourceKey":"bank:BUA216:NPV-056","parentItemId":null,"revision":1,"payload":{"prompt":"A project requiring an initial investment of N300,000 has an NPV of N90,000. Its profitability index (PV of inflows / initial investment) is:","options":["1.30","3.33","0.30","0.77"],"correctOption":0,"section":"Net Present Value","explanation":"PV of inflows = NPV + outlay = 90,000 + 300,000 = N390,000, so PI = 390,000 / 300,000 = 1.30. Option C divides the NPV alone by the outlay, and option B divides the outlay by the NPV. Option D is the inverse of the correct ratio."}},{"itemId":"9c4c1a5b-70e2-599d-b5c8-12865c993a42","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f5c16047-4e5b-5fd3-b769-a263e2c57a16","sourceKey":"bank:BUA216:NPV-057","parentItemId":null,"revision":1,"payload":{"prompt":"Zaria Mills has only N10 million to invest this year. The projects are divisible: A costs N4m (NPV N1.2m), B costs N6m (NPV N1.5m), C costs N5m (NPV N1.4m) and D costs N3m (NPV N0.45m). Ranking by profitability index (PV of inflows / cost), which plan maximises NPV within the budget?","options":["All of C and B, nothing of A","All of A and D, plus three-fifths of C","All of A and C, plus one-sixth of B","All of A and B"],"correctOption":2,"section":"Net Present Value","explanation":"PIs are A 5.2/4 = 1.30, C 6.4/5 = 1.28, B 7.5/6 = 1.25 and D 3.45/3 = 1.15. Funding A and C uses N9m and the last N1m buys one-sixth of B, giving NPV 1.2 + 1.4 + 0.25 = N2.85m. Option D gives N2.70m, option A costs N11m, which exceeds the budget, and option B gives only 1.2 + 0.45 + 0.84 = N2.49m."}},{"itemId":"3e917ab7-a35a-5fc1-96fa-48ed5ba3db36","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"14624e4c-6103-5499-8b02-e69002437922","sourceKey":"bank:BUA216:NPV-058","parentItemId":null,"revision":1,"payload":{"prompt":"A firm with N8 million available can choose among divisible projects: P costs N5m with NPV N1.0m, Q costs N4m with NPV N1.2m, and R costs N2m with NPV N0.3m. Ranking by profitability index (PV of inflows / cost), what total NPV does the optimal plan produce?","options":["N1.50m","N2.20m","N2.00m","N1.30m"],"correctOption":2,"section":"Net Present Value","explanation":"PIs are Q 5.2/4 = 1.30, P 6.0/5 = 1.20 and R 2.3/2 = 1.15, so fund all of Q (N4m) and then the remaining N4m in P, which is four-fifths of P. Total NPV = 1.2 + 0.8 x 1.0 = N2.00m. Option A funds Q and R only, option B adds the NPVs of Q and P in full although that would need N9m, and option D funds P and R only."}},{"itemId":"5d66b7b2-51da-5f09-8766-047846abe1e5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2ddc534c-2b1c-500a-860f-bd9e7f6d31b1","sourceKey":"bank:BUA216:NPV-059","parentItemId":null,"revision":1,"payload":{"prompt":"A project has an NPV of +N48,000 at 10% and -N24,000 at 16%. Using IRR = L + [NPVL / (NPVL + |NPVH|)] x (H - L), the IRR is:","options":["12%","4%","14%","22%"],"correctOption":2,"section":"Net Present Value","explanation":"IRR = 10% + [48,000 / (48,000 + 24,000)] x 6% = 10% + 0.6667 x 6% = 14%. Option A puts the negative NPV in the numerator, and option D subtracts 24,000 in the denominator instead of adding it. Option B forgets to add the lower rate of 10%."}},{"itemId":"87ec12cd-536b-558f-800e-de5e0acf930d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0fef00d0-d512-531b-8199-302c49581c00","sourceKey":"bank:BUA216:NPV-060","parentItemId":null,"revision":1,"payload":{"prompt":"Lagos Ferry Services finds that a new boat has an NPV of N1,250,000 at 15% and -N750,000 at 20%. By linear interpolation, the IRR to 2 decimal places is:","options":["3.13%","16.88%","18.13%","27.50%"],"correctOption":2,"section":"Net Present Value","explanation":"IRR = 15% + [1,250,000 / (1,250,000 + 750,000)] x 5% = 15% + 0.625 x 5% = 18.13%. Option B uses the negative NPV as the numerator, and option D subtracts the NPVs in the denominator. Option A leaves out the lower rate of 15%."}},{"itemId":"a1005dc6-d580-540a-9c63-5c4c9a7f1505","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e7c1e116-8cae-54b6-aac1-49ff3469e8b3","sourceKey":"bank:BUA216:NPV-061","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N1,000,000 and returns N400,000 at the end of each year for 3 years. Its NPV is positive at 5% and negative at 15%. Using linear interpolation between 5% and 15%, the IRR to 1 decimal place is approximately:","options":["5.1%","9.9%","10.1%","40.0%"],"correctOption":2,"section":"Net Present Value","explanation":"NPV at 5% = 400,000 x 2.7232 - 1,000,000 = about N89,300, and at 15% = 400,000 x 2.2832 - 1,000,000 = about -N86,710. IRR = 5% + [89,300 / (89,300 + 86,710)] x 10% = about 10.1%. Option B puts the negative NPV in the numerator, option A omits the 5% starting rate, and option D is the simple yearly cash return 400,000 / 1,000,000, which ignores recovery of the outlay."}},{"itemId":"7c9be25f-393b-5176-8745-11c9c12e59ac","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"80f97873-3811-5179-82b9-31084bf2a519","sourceKey":"bank:BUA216:NPV-062","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N30,000 and yields N8,000 a year for 5 years. Its NPV is N326 at 10% and -N6,075 at 20%. Using linear interpolation, the IRR to 1 decimal place is:","options":["10.5%","9.4%","0.5%","19.5%"],"correctOption":0,"section":"Net Present Value","explanation":"IRR = 10% + [326 / (326 + 6,075)] x 10% = about 10.5%. Option D uses the negative NPV as the numerator, and option B subtracts the absolute negative NPV in the denominator instead of adding it. Option C forgets to add the lower rate of 10%."}},{"itemId":"2396d0f1-4bb3-5276-a3ad-e9ee70378105","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8839a02d-0a22-53e6-9cba-be71cd43931e","sourceKey":"bank:BUA216:NPV-063","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N379,079 and generates N100,000 at the end of each year for 5 years. Which of the following rates is its IRR (the rate at which NPV = 0)?","options":["10%","12%","26.4%","8%"],"correctOption":0,"section":"Net Present Value","explanation":"At the IRR, annual inflow x annuity factor = outlay, so the required factor is 379,079 / 100,000 = 3.7908, which is the 5-year annuity factor at 10%: 100,000 x [1 - (1.10)^-5] / 0.10 = N379,079. At 12% (B) the NPV is negative and at 8% (D) it is positive. Option C is just 100,000 / outlay, which ignores recovery of the outlay."}},{"itemId":"5285b647-de0f-57a5-bacf-70f193c7a91b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"de243da5-d027-522a-879d-3b72e4ac4f1e","sourceKey":"bank:BUA216:NPV-064","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of N500,000 today returns a single cash inflow of N575,000 at the end of one year. Its IRR is:","options":["13.04%","115.00%","15.00%","7.50%"],"correctOption":2,"section":"Net Present Value","explanation":"Setting NPV = 575,000 / (1 + IRR) - 500,000 = 0 gives 1 + IRR = 575,000 / 500,000 = 1.15, so IRR = 15%. Option A divides the gain of N75,000 by the inflow instead of the outlay, and option B is the ratio 1.15 written as a percentage without subtracting 1. Option D halves the return as if it were earned over two years."}},{"itemId":"36a640d5-c725-526c-a7c9-bda8a68b4633","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c266cacd-809a-57ee-8561-3deeb2b09578","sourceKey":"bank:BUA216:NPV-065","parentItemId":null,"revision":1,"payload":{"prompt":"A plot of land bought for N1,000,000 is expected to be sold for N1,210,000 at the end of 2 years, with no other cash flows. The IRR of this investment is:","options":["9.1%","21.0%","10.5%","10.0%"],"correctOption":3,"section":"Net Present Value","explanation":"NPV is zero when 1,210,000 / (1 + IRR)^2 = 1,000,000, so (1 + IRR)^2 = 1.21 and IRR = 10%. Option B is the total two-year gain of 21%, and option C divides that by 2 as if the return were simple interest. Option A discounts the gain instead, 1 - 1,000,000 / 1,100,000, which is not the IRR."}},{"itemId":"af667bbe-4c9c-5a67-9de0-b2e93250c2ca","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c5925311-595b-5743-8825-8e5d3e7184c8","sourceKey":"bank:BUA216:NPV-066","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N800,000 and yields N300,000, N350,000 and N400,000 in years 1 to 3. If the discount rate were 0%, its NPV would be:","options":["N1,050,000","N0","N250,000","-N800,000"],"correctOption":2,"section":"Net Present Value","explanation":"At 0% every discount factor is 1, so NPV = 300,000 + 350,000 + 400,000 - 800,000 = N250,000, the undiscounted surplus. Option A forgets to deduct the outlay, option B confuses a 0% rate with a zero NPV, and option D ignores the inflows."}},{"itemId":"05b82f42-d82b-56d8-8888-b4a65acbbfd5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"65dafc10-4f5c-550e-82b4-e57d0defe2ea","sourceKey":"bank:BUA216:NPV-067","parentItemId":null,"revision":1,"payload":{"prompt":"An investor is offered a franchise that will pay N300,000, N300,000, N400,000 and N400,000 at the end of years 1 to 4. If she requires 12%, the maximum she should pay for it (the price giving an NPV of zero) is closest to:","options":["N1,400,000","N889,700","N1,171,400","N1,045,900"],"correctOption":3,"section":"Net Present Value","explanation":"Maximum price = PV of the inflows = 300,000 x (0.8929 + 0.7972) + 400,000 x (0.7118 + 0.6355) = about N1,045,930. Option A ignores discounting, and option B discounts the whole N1,400,000 as if it all arrived in year 4. Option C discounts each payment one year too few, treating the first payment as received today."}},{"itemId":"5d320e92-8688-5dc8-9b9f-8223733536ad","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ca4b896-f09c-57d0-aebb-92de16603a76","sourceKey":"bank:BUA216:NPV-068","parentItemId":null,"revision":1,"payload":{"prompt":"Warri Shipping uses the 20% discount factors 0.8333 (year 1), 0.6944 (year 2) and 0.5787 (year 3). A project costs N2,500,000 and yields N1,200,000, N1,000,000 and N900,000 in years 1 to 3. Its NPV is:","options":["N2,215,190","N158,260","N600,000","-N284,810"],"correctOption":3,"section":"Net Present Value","explanation":"PV of inflows = 1,200,000 x 0.8333 + 1,000,000 x 0.6944 + 900,000 x 0.5787 = 999,960 + 694,400 + 520,830 = N2,215,190, so NPV = 2,215,190 - 2,500,000 = -N284,810 and the project is rejected. Option C ignores the factors, and option A is the PV of inflows before deducting the cost. Option B shifts every factor back by one year."}},{"itemId":"c7bab6a9-bb38-510b-8690-72ed0411008c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"81953418-69c1-5e65-bfe6-64ba1d9d73cf","sourceKey":"bank:BUA216:NPV-069","parentItemId":null,"revision":1,"payload":{"prompt":"A project's only year-5 cash inflow is N500,000. A student uses a discount factor of 0.42 instead of the correct 0.4823. By how much does he understate the project's NPV?","options":["N210,000","N241,150","N62,300","N31,150"],"correctOption":3,"section":"Net Present Value","explanation":"The error in the PV is 500,000 x (0.4823 - 0.42) = 500,000 x 0.0623 = N31,150, and since everything else is unchanged, NPV is understated by the same N31,150. Option B is the correct PV itself (500,000 x 0.4823), and option A is the wrong PV (500,000 x 0.42). Option C doubles the error."}},{"itemId":"bee95ed8-5b9d-5e11-8512-82c870faa976","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"554aa934-73db-52b4-b7dd-fe892ee2e45a","sourceKey":"bank:BUA216:NPV-070","parentItemId":null,"revision":1,"payload":{"prompt":"Owerri Palm Oil Ltd's cost of capital is 20%. A crushing plant costs N1,000,000 and will give net cash inflows of N450,000 at the end of each of the next 4 years. The NPV is closest to:","options":["N713,500","N164,900","N800,000","N1,164,900"],"correctOption":1,"section":"Net Present Value","explanation":"Annuity factor = [1 - (1.20)^-4] / 0.20 = 2.5887, so PV = 450,000 x 2.5887 = about N1,164,930 and NPV = about N164,930. Option C ignores discounting, and option D is the PV before deducting the cost. Option A discounts at 2% instead of 20%."}},{"itemId":"9e6c4183-c35c-5941-82e7-9fa64d86849d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"691d8bc1-0ab4-5227-8238-86d0f7f01ce9","sourceKey":"bank:BUA216:NPV-071","parentItemId":null,"revision":1,"payload":{"prompt":"A project needs N400,000 now and a further N100,000 at the end of year 1. It then produces N250,000 at the end of each of years 2, 3 and 4. At a 10% cost of capital, the NPV is closest to:","options":["N74,300","N121,700","N65,200","N250,000"],"correctOption":0,"section":"Net Present Value","explanation":"NPV = -400,000 - 100,000 x 0.9091 + 250,000 x (0.8264 + 0.7513 + 0.6830) = -400,000 - 90,910 + 565,170 = about N74,260. Option C fails to discount the year-1 outlay, and option B treats the inflows as arriving in years 1 to 3. Option D ignores discounting altogether."}},{"itemId":"54e4455c-08f3-5a82-a255-b83b831a238a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb37aed5-bed7-5135-9f5b-bc35046394dc","sourceKey":"bank:BUA216:NPV-072","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N48,000 and its net cash inflows are N12,000 per annum for 6 years. At a cost of capital of 10%, its NPV is closest to:","options":["N11,021","N4,263","N24,000","N52,263"],"correctOption":1,"section":"Net Present Value","explanation":"Annuity factor for 6 years at 10% = [1 - (1.10)^-6] / 0.10 = 4.3553, so PV = 12,000 x 4.3553 = N52,263 and NPV = 52,263 - 48,000 = about N4,263. Option C is the undiscounted surplus, and option D omits the outlay. Option A divides the cost by the annuity factor, which gives the break-even annual inflow, not the NPV."}},{"itemId":"b74d5b53-a0e0-59f1-874e-6abb145c7610","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bf0cee47-f3c2-5259-b7f2-248927a580d7","sourceKey":"bank:BUA216:NPV-073","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N48,000 and its net cash inflows are N12,000 per annum for 6 years. Its payback period is:","options":["2.0 years","6.0 years","0.25 years","4.0 years"],"correctOption":3,"section":"Net Present Value","explanation":"Payback = initial outlay / annual cash inflow = 48,000 / 12,000 = 4.0 years. Option B is the project's whole life, and option C divides the inflow by the outlay. Option A is the 2 years remaining after payback, not the payback period itself."}},{"itemId":"f4b7e131-fdc9-5008-897e-b4471adf8d0e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6b419184-c747-51ab-b441-aef3dad9f29f","sourceKey":"bank:BUA216:NPV-074","parentItemId":null,"revision":1,"payload":{"prompt":"A project costing N2,000,000 has even annual cash inflows and a payback period of exactly 4 years. What is its annual cash inflow?","options":["N250,000","N500,000","N400,000","N8,000,000"],"correctOption":1,"section":"Net Present Value","explanation":"Since payback = outlay / annual inflow, the annual inflow = 2,000,000 / 4 = N500,000. Option D multiplies instead of dividing. Options C and A divide by 5 and 8 years, which do not match the stated payback of 4 years."}},{"itemId":"a1784724-a32f-5ec9-b324-8ca98b1c0e41","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3d642547-76b0-5c65-94b3-ee9b0754f452","sourceKey":"bank:BUA216:NPV-075","parentItemId":null,"revision":1,"payload":{"prompt":"Sokoto Power Ltd is considering a project costing N180 million with cash flows of N60m, N80m, N70m and N40m over four years. The cost of capital is 15%. What is the NPV (to the nearest N0.1m) and the decision?","options":["N181.6m; accept the project","N1.6m; accept the project","N1.6m; reject the project","N70.0m; accept the project"],"correctOption":1,"section":"Net Present Value","explanation":"Using factors 0.8696, 0.7561, 0.6575 and 0.5718, PV = 52.18 + 60.49 + 46.03 + 22.87 = about N181.6m, so NPV = 181.6 - 180 = about N1.6m. Because the NPV is positive, the project is accepted, so option C has the right figure but the wrong decision. Option D ignores discounting and option A is the PV of the inflows before deducting the cost."}},{"itemId":"f3d7d48e-d2c3-58b2-8122-fbdd73cf2e74","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a25a057c-1e0d-55e8-8dbb-8a5297a501b5","sourceKey":"bank:BUA216:NPV-076","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N1,000,000 and yields N500,000, N400,000 and N300,000 in years 1 to 3. By how much does its NPV fall if the cost of capital rises from 8% to 14%? (Closest answer)","options":["N95,200","-N51,100","N200,000","N44,000"],"correctOption":0,"section":"Net Present Value","explanation":"NPV at 8% = about N44,050 and NPV at 14% = about -N51,130, so NPV falls by about N95,200. A higher rate shrinks every discount factor, which is why NPV drops. Option D is the NPV at 8% itself and option B the NPV at 14%, while option C is the undiscounted surplus."}},{"itemId":"4bbb9c0d-7615-5915-ab3a-2693527dae02","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"810f54f0-d524-594d-a356-121932e05984","sourceKey":"bank:BUA216:NPV-077","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N800,000 and yields N300,000, N350,000 and N300,000 in years 1 to 3. At a 12% cost of capital, what is its profitability index (PV of inflows / initial investment), to 2 decimal places, and should it be accepted?","options":["1.05; accept","0.95; accept","0.95; reject","1.19; accept"],"correctOption":2,"section":"Net Present Value","explanation":"PV of inflows = 300,000 x 0.8929 + 350,000 x 0.7972 + 300,000 x 0.7118 = about N760,410, so PI = 0.95. A PI below 1 means a negative NPV, so the project is rejected; option B has the right figure but the wrong decision. Option D uses undiscounted inflows and option A inverts the ratio."}},{"itemId":"9c57a116-26de-5056-b9bc-0b596e805880","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"11daa797-1de9-585c-8bae-705d4ca4f287","sourceKey":"bank:BUA216:NPV-078","parentItemId":null,"revision":1,"payload":{"prompt":"To 4 decimal places, the present value annuity factor for 5 years at 15% is:","options":["3.3522","6.7424","0.4972","4.3478"],"correctOption":0,"section":"Net Present Value","explanation":"Annuity factor = [1 - (1.15)^-5] / 0.15 = (1 - 0.4972) / 0.15 = 3.3522. Option B is the future value annuity factor, and option C is the single discount factor for year 5. Option D multiplies the year-1 factor by 5 instead of adding the five different factors."}},{"itemId":"40e90566-f90f-5cfc-930b-d9b860066ca9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9190391a-f4d7-5879-a257-df3805bde1dc","sourceKey":"bank:BUA216:NPV-079","parentItemId":null,"revision":1,"payload":{"prompt":"A project with an initial outlay of N300 million has an expected cash flow of N80 million a year for five years. If the cost of capital is 12%, what is the NPV to the nearest N0.1 million?","options":["-N60.8m","-N11.6m","N288.4m","N100.0m"],"correctOption":1,"section":"Net Present Value","explanation":"Annuity factor = [1 - (1.12)^-5] / 0.12 = 3.6048, so PV = 80 x 3.6048 = N288.4m and NPV = 288.4 - 300 = -N11.6m, so the project should be rejected. Option D ignores discounting, and option C is the PV before the outlay is deducted. Option A discounts at 20% instead of 12%."}},{"itemId":"e8b9de18-37ad-5d27-af5f-c69da2b942f4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a26bf75d-3acd-5f12-a2a1-e609fb824fdd","sourceKey":"bank:BUA216:NPV-080","parentItemId":null,"revision":1,"payload":{"prompt":"A project's NPV is N2.4 million at 12% and -N1.6 million at 18%. Using linear interpolation, what is the IRR to 1 decimal place, and should the project be accepted if the cost of capital is 14%?","options":["15.6%; reject","14.4%; accept","18.0%; accept","15.6%; accept"],"correctOption":3,"section":"Net Present Value","explanation":"IRR = 12% + [2.4 / (2.4 + 1.6)] x 6% = 12% + 0.6 x 6% = 15.6%, which exceeds the 14% cost of capital, so the project is accepted. Option A has the right IRR but the wrong decision, and option B uses the negative NPV in the numerator (12% + 0.4 x 6%). Option C is simply the higher trial rate, which cannot be the IRR because NPV is already negative there."}},{"itemId":"27450ac5-c8bd-5c78-9b4e-b859074d8c3a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"76e9a701-3d0f-5f85-a805-e02145d831ed","sourceKey":"bank:BUA216:NPV-081","parentItemId":null,"revision":1,"payload":{"prompt":"Kwara Feeds evaluates two INDEPENDENT projects at 10%. Project A costs N400,000 and returns N180,000 a year for 3 years. Project B costs N600,000 and returns N200,000, N250,000 and N260,000 in years 1 to 3. Which decision is correct?","options":["Accept B only, since it is the larger project","Reject A and accept B, since B has the larger inflows","Accept A (NPV about N47,600) and reject B (NPV about -N16,200)","Accept both, since each has total inflows above its cost"],"correctOption":2,"section":"Net Present Value","explanation":"NPV of A = 180,000 x 2.4869 - 400,000 = about N47,640, while NPV of B = 200,000 x 0.9091 + 250,000 x 0.8264 + 260,000 x 0.7513 - 600,000 = about -N16,200. Each independent project is judged on its own NPV, so A is accepted and B rejected. Option D ignores discounting, and options B and A judge by size instead of value added."}},{"itemId":"92994090-cc32-5602-821f-e372e2e18fde","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d120a2a-89c4-55e5-b4ca-708dbae6ec41","sourceKey":"bank:BUA216:OVF-001","parentItemId":null,"revision":1,"payload":{"prompt":"\"The management of money and money claims\" is a definition of which of the following?","options":["Book-keeping","Finance","Taxation","Auditing"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Finance is defined as the management of money and money claims, so wherever money is available, finance is available. Option A only records transactions, option D checks the accuracy of financial records, and option C deals with levies paid to government; none of them is the management of money itself."}},{"itemId":"bac04fb1-1707-5d11-a2be-c0235c6fad8c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"12d9ecac-79d4-5660-914a-0dac1b6e1e02","sourceKey":"bank:BUA216:OVF-002","parentItemId":null,"revision":1,"payload":{"prompt":"Within a business firm, finance is best described as dealing with:","options":["The inflows (sources) and outflows (uses) of funds","The design and packaging of products","The recruitment and training of staff","The scheduling of production runs"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Finance deals with where a firm's funds come from (inflows) and where they go (outflows), which is why it links all business relationships. Options C, B and D describe personnel, marketing and production work; these activities need funds, but they are not finance itself."}},{"itemId":"e96bfaca-52a2-581e-8405-9ddde6ef8003","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7fecdef0-5224-54e5-820e-986a4869d19c","sourceKey":"bank:BUA216:OVF-003","parentItemId":null,"revision":1,"payload":{"prompt":"Since finance is money, the availability of finance in a business means the availability of:","options":["Customers","Profit","Raw materials","Money"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Finance is money, so having finance available simply means having money available to the business. Profit (option B) is a result of operations and may exist on paper without cash, while customers (option A) and raw materials (option C) are things money is used to obtain."}},{"itemId":"8d97bacb-819b-5e26-a16a-c377dcf37f38","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9b6e858f-ace3-5c3a-9eac-d756d49016d4","sourceKey":"bank:BUA216:OVF-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the reasons finance is important in a business firm?","options":["It enhances business growth","It links other activities such as marketing, purchasing and production together","It serves as a standard upon which business performance can be measured","It removes the need for separate marketing and production functions"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Finance supports the other functions; it does not replace them, so option D is not a reason for its importance. Options A, C and B are genuine reasons: finance enables growth, gives a money yardstick for judging performance, and ties marketing, purchasing, production and distribution together."}},{"itemId":"b1bede81-eb2f-5d7a-ac2c-3ede06c257c6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"59368f8a-1906-598e-af9b-01ae2f9be139","sourceKey":"bank:BUA216:OVF-005","parentItemId":null,"revision":1,"payload":{"prompt":"At Ikeja Foods Ltd, the marketing, purchasing and production departments cannot carry out their plans until the finance department releases the approved budget to each of them. This best illustrates that finance:","options":["Can be ignored once sales begin","Links all the other activities of the business together","Is a new discipline that has grown rapidly","Is concerned only with paying taxes"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Every department depends on funds released through finance, which shows finance acting as the link that holds marketing, purchasing and production together. Option C is true of finance in general but has nothing to do with this scenario, while options D and A are false descriptions of finance."}},{"itemId":"0e6bf184-8a13-5080-afcc-8a221d8143a6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af1bb07a-9b1a-57de-96bd-ace68e402f29","sourceKey":"bank:BUA216:OVF-006","parentItemId":null,"revision":1,"payload":{"prompt":"The board of Oyo Textiles Plc compares this year's naira turnover, profit and return on capital with last year's figures to judge how well the company performed. Which importance of finance does this show?","options":["Finance removes business risk","Finance is a new discipline which has grown rapidly","Finance links marketing and distribution activities","Finance serves as a standard upon which business performance can be measured"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Expressing results in money terms gives the board a common yardstick, so finance serves as the standard for measuring performance. Option C is another importance of finance but describes coordination of departments, not measurement, and option B describes the growth of finance as a field of study. Option A is false because finance cannot remove risk."}},{"itemId":"e95a5286-6355-5aaf-a37e-f47437fc3a8f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ac40f44c-e374-5a1b-9fd3-749c4185b9bb","sourceKey":"bank:BUA216:OVF-007","parentItemId":null,"revision":1,"payload":{"prompt":"In a financial market, the parties who have surplus money and buy financial instruments are the:","options":["Issuers","Borrowers","Regulators","Lenders"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Lenders have money to spare, and they part with it by buying the financial instruments that borrowers issue. Borrowers (option B) and issuers (option A) are the ones who need money and sell instruments, while regulators (option C) supervise the market rather than supply funds."}},{"itemId":"86c3dce8-07fd-590e-b36c-5bc1059ccf87","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"594c7fb0-6456-5391-9719-f1ee1b099f11","sourceKey":"bank:BUA216:OVF-008","parentItemId":null,"revision":1,"payload":{"prompt":"In a financial market, borrowers are also described as:","options":["Buyers of financial instruments","Sellers of financial instruments","Regulators of financial instruments","Guarantors of financial instruments"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Borrowers need money, so they issue (sell) financial instruments to the lenders who supply it. Option A describes lenders, who buy the instruments, and options D and C describe other roles such as a bank guarantee or market supervision."}},{"itemId":"5885b3f0-e7ae-562a-89f4-8aa133cb2f3b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a9ebd2b8-a1ba-5cef-97f7-c19e2636b2a7","sourceKey":"bank:BUA216:OVF-009","parentItemId":null,"revision":1,"payload":{"prompt":"The receipt which a borrower issues to a lender as a promise or evidence to pay back the capital is called a:","options":["Sales invoice","Bank statement","Financial security (financial instrument)","Dividend warrant"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A financial security or instrument is the borrower's written evidence of the promise to repay the lender's capital. A dividend warrant (option D) pays a dividend to a shareholder, a bank statement (option B) lists account transactions, and a sales invoice (option A) bills a customer for goods."}},{"itemId":"f5eef5ef-0ddb-5716-af6a-172b752e1fd0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"481b9741-efe4-50b6-88a3-e1c093b1e944","sourceKey":"bank:BUA216:OVF-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a correct description of a financial market?","options":["Any system or structure that makes it possible to trade in different kinds of financial securities","A market where financial instruments like debt, debentures and equities are traded","A market where only physical commodities such as cocoa and crude oil are exchanged for cash","A market where government, companies and individual investors can trade in financial securities"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A financial market trades financial claims such as shares and debentures, not physical goods, so option C is not a description of it. Options A, B and D are all accepted definitions of a financial market."}},{"itemId":"0b37a3e9-76e6-56ac-9991-983a91ca7024","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3bb49b3c-0f51-5e7e-913c-68b5502ba095","sourceKey":"bank:BUA216:OVF-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following would be the main difficulty in an economy without financial markets?","options":["Borrowers would find it difficult to locate lenders","Interest rates would always be zero","Firms would no longer need any funds","Savers would have more investment choices"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A market brings buyers and sellers together, so without financial markets those who need money would struggle to find those who have it. Option C is false because firms always need funds, option B has no basis, and option D is the reverse of what would happen, since savers would have fewer outlets."}},{"itemId":"8978bfdb-01e2-55b3-9cfb-21f07dc5f4e6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"26c4b5a9-438e-50f0-9c46-a4dc79d50814","sourceKey":"bank:BUA216:OVF-012","parentItemId":null,"revision":1,"payload":{"prompt":"Funds raised in the money market can be used for a maximum period of:","options":["One year or less","Five years","Ten years or more","More than one year"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"The money market is for short-term funds only, so money raised there can be used for a maximum of one year or less. Option D describes the capital market, and options B and C are medium- and long-term periods that also belong to the capital market."}},{"itemId":"e68fa572-4193-51c6-8dfa-72388862afd3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb533bde-2f97-518c-a4da-a6753657d0ea","sourceKey":"bank:BUA216:OVF-013","parentItemId":null,"revision":1,"payload":{"prompt":"Kaduna Agro Ltd needs N50 million for eight months to buy grain stock before the harvest season ends. Which market is the appropriate place to raise these funds?","options":["Capital market","Money market","Secondary market for debentures","Primary market for ordinary shares"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Eight months is less than one year, so the need is short-term and belongs in the money market. Options A, D and C are all parts of the capital market, which deals in securities lasting more than one year."}},{"itemId":"d51b1ba1-19aa-5047-83c4-9f8e8ea05cdc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ca221c19-ae65-59f8-ac3e-916fcf40a96d","sourceKey":"bank:BUA216:OVF-014","parentItemId":null,"revision":1,"payload":{"prompt":"Benue Cement Plc wants to raise N2 billion to build a new plant that will be repaid over twelve years. Which market should it approach?","options":["Capital market","Money market","Repurchase agreement market","Treasury bills market"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A twelve-year need is long-term, and the capital market is the market for medium- and long-term securities with a life of more than one year. Option B only provides funds for one year or less, and options D and C are money market instruments."}},{"itemId":"6543170b-3198-5cd7-b686-c8d1d55c97ae","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aeda171a-a091-5c0a-95e4-8ee6f89d3d51","sourceKey":"bank:BUA216:OVF-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts the money market and the capital market?","options":["The money market deals in securities of one year or less; the capital market deals in securities of more than one year","The money market deals in securities of more than one year; the capital market deals in securities of one year or less","The money market deals only in shares; the capital market deals only in treasury bills","Both markets deal only in securities of more than five years"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"The dividing line between the two is one year: short-term securities (one year or less) are traded in the money market and medium- and long-term securities (more than one year) in the capital market. Option B reverses the two, option D ignores the short-term market altogether, and option C mixes up the instruments, since treasury bills are money market instruments."}},{"itemId":"faf49123-c282-5d42-962b-84e3462d419a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bc163348-156a-5f0b-9dd9-bbb690dcf08a","sourceKey":"bank:BUA216:OVF-016","parentItemId":null,"revision":1,"payload":{"prompt":"The capital market is best described as the market for:","options":["Overnight lending between banks only","Short-term financial securities of one year or less","Medium- and long-term financial securities","Foreign currencies only"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"The capital market is where securities with a life span of more than one year, that is medium- and long-term securities, are bought and sold. Option B describes the money market, and options A and D describe narrower markets for very short-term interbank loans and foreign exchange."}},{"itemId":"0ae8dbeb-e795-52f6-bef1-6d3173cf9b11","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bb4c6c73-7ed5-55db-a439-a9f34a6b2a3c","sourceKey":"bank:BUA216:OVF-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a money market instrument?","options":["Debenture","Treasury bill","Certificate of deposit","Banker's acceptance"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A debenture is a long-term debt instrument traded in the capital market, so it is not a money market instrument. Treasury bills (option B), certificates of deposit (option C) and bankers' acceptances (option D) are all short-term money market instruments."}},{"itemId":"2cac9618-e81b-5ba0-86a3-f17380300167","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3781976b-7d6c-5566-a3ab-925d3cde9d15","sourceKey":"bank:BUA216:OVF-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a capital (secondary) market instrument?","options":["Repurchase agreement","Equity share","Debenture","Ordinary share"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A repurchase agreement is a short-term money market arrangement in which a security is sold and later bought back. Ordinary shares (option D), debentures (option C) and equity shares (option B) are long-term securities traded in the capital market."}},{"itemId":"65c71c73-091e-58ce-8692-9ab623b54ab4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"399aaf29-1e8c-5235-adc9-ac3669857221","sourceKey":"bank:BUA216:OVF-019","parentItemId":null,"revision":1,"payload":{"prompt":"An instrument used by government to borrow funds for a short time, and usually issued by the Central Bank, is a:","options":["Debenture","Ordinary share","Treasury bill","Certificate of deposit"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Treasury bills are short-term government borrowing instruments, issued through the Central Bank. A debenture (option A) and an ordinary share (option B) are long-term company securities, and a certificate of deposit (option D) is issued by a bank, not by government."}},{"itemId":"ef22b315-1e81-5e11-8d92-db25ad3e8532","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c72c33c0-7754-5329-baf5-bb88a369efc4","sourceKey":"bank:BUA216:OVF-020","parentItemId":null,"revision":1,"payload":{"prompt":"A repurchase agreement is an arrangement in which:","options":["A company sells new shares to the public for the first time","The seller sells a security to the buyer and agrees to buy the same security back later","The buyer promises to pay the seller and the buyer's bank stands as guarantor","A bank issues a note giving the bearer the right to receive interest"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"In a repurchase agreement both parties agree that the seller will sell a security now and buy the same security back from the buyer later. Option D describes a certificate of deposit, option C a banker's acceptance, and option A a primary market share issue."}},{"itemId":"e624add4-3ace-543f-80fd-69e53ddbb8d6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"376b94f2-826c-56f1-b2de-d116a35f3dae","sourceKey":"bank:BUA216:OVF-021","parentItemId":null,"revision":1,"payload":{"prompt":"Coastline Bank sells N500 million of government securities to another bank today and agrees to buy back the same securities next Friday at an agreed price. This transaction is a:","options":["Repurchase agreement","Certificate of deposit","Banker's acceptance","Initial public offer"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Selling a security and agreeing to repurchase the same security later is exactly a repurchase agreement, a money market tool for short-term funds. A banker's acceptance (option C) involves a bank guaranteeing a buyer's promise to pay, a certificate of deposit (option B) is a bank's interest-bearing note, and an initial public offer (option D) is a sale of new shares."}},{"itemId":"37ff9da5-7bab-5f16-a0b6-4c2bc0ea817b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8ca566d9-8437-5368-8549-6d7e115ecc36","sourceKey":"bank:BUA216:OVF-022","parentItemId":null,"revision":1,"payload":{"prompt":"A promissory note issued by a bank which gives the bearer the right to receive interest is a:","options":["Treasury bill","Debenture","Banker's acceptance","Certificate of deposit"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"A certificate of deposit is a bank's promissory note that entitles the holder to interest. A treasury bill (option A) is issued for government, a banker's acceptance (option C) is a buyer's promise to pay guaranteed by its bank, and a debenture (option B) is long-term company debt."}},{"itemId":"336785d8-1ea2-5b88-9cf9-d792bc19c952","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bb37ac8f-cdb8-5744-9749-f425d6765982","sourceKey":"bank:BUA216:OVF-023","parentItemId":null,"revision":1,"payload":{"prompt":"An importer in Kano promises to pay a foreign supplier for goods in 90 days, and the importer's bank stands as guarantor of the payment. This instrument is a:","options":["Treasury bill","Banker's acceptance","Ordinary share","Repurchase agreement"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A banker's acceptance is a buyer's promise to pay the seller, guaranteed by the buyer's bank, which is exactly the importer's position here. A repurchase agreement (option D) involves selling and buying back a security, a treasury bill (option A) is government borrowing, and an ordinary share (option C) is ownership in a company."}},{"itemId":"a810c48c-b6c7-5128-ae7f-da0563807a88","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9498f64b-8e30-52ed-be19-f3646489f24a","sourceKey":"bank:BUA216:OVF-024","parentItemId":null,"revision":1,"payload":{"prompt":"In a banker's acceptance, the role of the buyer's bank is to:","options":["Sell the goods to the buyer","Stand as guarantor of the buyer's promise to pay the seller","Buy back the goods from the buyer at a later date","Issue shares to the seller"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The banker's acceptance is the buyer's promise to pay, and the buyer's bank guarantees that promise, which makes it acceptable to the seller. Option A is the seller's role, option C confuses it with a repurchase arrangement, and option D has nothing to do with the instrument."}},{"itemId":"832273e0-d882-5f05-911c-bae9ea92d299","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a4afcb0-207d-5700-9b61-b1fc35e3822a","sourceKey":"bank:BUA216:OVF-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches a money market instrument with its issuer or guarantor?","options":["Certificate of deposit - issued by a bank","Banker's acceptance - guaranteed by the seller's shareholders","Certificate of deposit - issued by the Securities and Exchange Commission","Treasury bill - issued by a commercial company"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A certificate of deposit is a promissory note issued by a bank, so option A is the correct pairing. Treasury bills (option D) are government instruments issued through the Central Bank, a banker's acceptance (option B) is guaranteed by the buyer's bank, and the Securities and Exchange Commission (option C) is a regulator, not an issuer."}},{"itemId":"6b05aa05-d5d9-5433-bc94-7eee59924881","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2c13bc89-d822-5c13-bee8-324a4610b8be","sourceKey":"bank:BUA216:OVF-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a function of financial markets?","options":["Promoting economic growth by making money available to different sectors","Generating savings and investments in the economy","Providing a platform for effective implementation of monetary policy","Guaranteeing every investor a profit on the securities bought"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Financial markets channel funds and support policy, but no market can guarantee that every investor makes a profit, so option D is not a function. Options A, C and B are all recognised functions of financial markets."}},{"itemId":"924e96bc-e181-51c8-8d7f-66e1f45f8511","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"288b79a3-d206-5aab-b8d0-f44a3f45ae79","sourceKey":"bank:BUA216:OVF-027","parentItemId":null,"revision":1,"payload":{"prompt":"To reduce the amount of money in circulation, the Central Bank of Nigeria sells treasury bills to banks and investors. Which function of financial markets does this illustrate?","options":["Providing avenues for long-term equity investment","Fixing the prices of consumer goods","Providing a platform for effective implementation of monetary policy","Making the issuing company the buyer in the secondary market"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Selling treasury bills takes money out of circulation, and the market gives the Central Bank a platform to carry out such monetary policy actions. Option A relates to shares, not short-term bills, option D is not a market function at all, and option B has no link to financial markets."}},{"itemId":"424807a7-1699-5c53-8b6e-f7c2beaf811e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1c56b1a7-595f-565b-bb88-e224bbd30693","sourceKey":"bank:BUA216:OVF-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a function of financial markets?","options":["Fixing the salaries of civil servants","Guaranteeing that every borrower will repay","Determining the tax rate on company profits","Stabilising the demand and supply of money for short-time transactions"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Financial markets help to balance the demand for and supply of money for short-term transactions. Options A and C are government budget and tax decisions, and option B is false because markets cannot guarantee repayment by every borrower."}},{"itemId":"f5f9cac8-aff1-55c1-ac15-75147b77c04d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d634700a-0bcc-5961-ab43-284a86f32859","sourceKey":"bank:BUA216:OVF-029","parentItemId":null,"revision":1,"payload":{"prompt":"A poultry farm in Ogun State, a telecoms firm in Lagos and a road contractor in Abuja all raise funds from savers through the financial market. Which function of financial markets is shown?","options":["Stabilising money for short-time transactions only","Promoting economic growth by making money available to different sectors","Replacing the need for savings","Providing a platform for monetary policy"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Funds are flowing from savers to firms in agriculture, telecoms and construction, which is how financial markets promote growth by making money available to different sectors. Option D is about Central Bank actions, option A is too narrow for this case, and option C is wrong because the funds come from savings."}},{"itemId":"47ba8a0e-04a7-510a-ace8-3fce86e811bf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0d641971-84c7-5b1d-9a55-8bf1c4022c2f","sourceKey":"bank:BUA216:OVF-030","parentItemId":null,"revision":1,"payload":{"prompt":"Transactions in the primary market are usually between:","options":["The Central Bank and the Securities and Exchange Commission","Two companies exchanging goods","Two investors who already hold the security","The company issuing the security and the investors buying it"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"The primary market is where newly issued securities are sold, so the deal is between the issuing company and the investors who buy. Option C describes the secondary market, option A involves regulators rather than market traders, and option B is ordinary trade, not a financial market transaction."}},{"itemId":"50b6e953-63ff-5f74-be07-116a7b31d355","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"14357798-06f9-5016-b463-1c6f4382a52b","sourceKey":"bank:BUA216:OVF-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about the secondary market is TRUE?","options":["It is part of the money market","The issuing company receives the money from every resale of its shares","Only newly issued securities are traded there","The company that issued the securities does not get involved in its transactions"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"In the secondary market investors resell already existing securities to other investors, and the issuing company is not involved. Option C describes the primary market, option B is false because resale money goes to the selling investor, and option A is wrong because the secondary market is a division of the capital market."}},{"itemId":"6c8fb367-6891-5408-afd5-dba834f68e2e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"09f83e6d-dcea-5086-b069-ae03a929c126","sourceKey":"bank:BUA216:OVF-032","parentItemId":null,"revision":1,"payload":{"prompt":"Lekki Power Plc offers its shares to the public for the first time in order to raise funds for expansion. The investors who buy the shares are dealing in the:","options":["Repurchase market","Secondary market","Money market","Primary market"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"These are newly issued shares sold by the company itself, so the transaction takes place in the primary market. The secondary market (option B) trades shares that already exist, while the money market (option C) and repurchase agreements (option A) deal in short-term instruments."}},{"itemId":"271278a4-fd20-5ee0-9bb9-a02f4dda6893","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6d04951-fd66-546c-83ed-7c418594cb9a","sourceKey":"bank:BUA216:OVF-033","parentItemId":null,"revision":1,"payload":{"prompt":"Mrs. Adeyemi sells 10,000 shares she bought three years ago in a listed bank to another investor through the stock exchange. Who receives the money from this sale?","options":["The Central Bank of Nigeria","The bank and Mrs. Adeyemi equally","Mrs. Adeyemi, the selling investor","The bank that originally issued the shares"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"This is a secondary market sale of existing shares between two investors, so the money goes to the investor who sells. The issuing bank (options D and B) received its money only when the shares were first issued and takes no part in later resales, and the Central Bank (option A) is not a party to the trade."}},{"itemId":"606b3956-0c7a-5cf0-8eb7-6e32101beb61","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0037afc2-4c94-5f8e-8f73-2e31d88238d3","sourceKey":"bank:BUA216:OVF-034","parentItemId":null,"revision":1,"payload":{"prompt":"A part ownership in which each member is a fractional owner and bears the maximum entrepreneurial liability related to a trading concern is a(n):","options":["Treasury bill","Certificate of deposit","Ordinary (equity) share","Debenture"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"An ordinary or equity share makes its holder a part owner of the company who carries the main business risk. A debenture (option D) makes its holder a creditor, while treasury bills (option A) and certificates of deposit (option B) are short-term debt instruments with no ownership."}},{"itemId":"07916406-9ae3-5ec7-a34f-0e70f5739149","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f8c1e463-aac6-5b3d-ac48-cf48b92bb5bb","sourceKey":"bank:BUA216:OVF-035","parentItemId":null,"revision":1,"payload":{"prompt":"When a company issues debentures to investors, the investors become the company's:","options":["Owners","Creditors","Directors","Guarantors"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"A debenture is a debt instrument, so its holders have lent money to the company and become its creditors, entitled to interest and repayment of principal. Owners (option A) are ordinary shareholders, and directors (option C) and guarantors (option D) are not created by buying debt."}},{"itemId":"d477186d-49ae-5e32-b74e-cee91971221b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5f4d74ff-ca42-5654-bc36-b3a7d55f79a6","sourceKey":"bank:BUA216:OVF-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes an ordinary shareholder from a debenture holder?","options":["The ordinary shareholder is a part owner, while the debenture holder is a creditor","Both are creditors of the company","The ordinary shareholder is a creditor, while the debenture holder is a part owner","Both are part owners of the company"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Ordinary shares give part ownership of the company, while a debenture is a debt instrument whose holder lends to the company as a creditor. Option C reverses the two roles, and options B and D wrongly treat the two securities as the same kind of claim."}},{"itemId":"ce46dccb-7776-53cc-b857-3863eb9d9ec7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"04354b3c-d2e3-5b3a-b3a1-5965ebb416df","sourceKey":"bank:BUA216:OVF-037","parentItemId":null,"revision":1,"payload":{"prompt":"Taking a debenture as a debt instrument that is not secured by physical assets or collateral, which of the following is a feature of a debenture?","options":["It promises to pay interest and principal to the holder","It gives the holder part ownership of the company","It must be repaid within one year in the money market","It is issued only by the Central Bank"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"A debenture promises its holders interest and repayment of principal, which is what makes it a debt instrument. Option B describes an ordinary share, option C wrongly places it in the money market although it is a capital market instrument, and option D is wrong because debentures are issued by companies."}},{"itemId":"eaec7314-5b89-5f96-900b-4ee34e09e940","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e2736b62-0bc3-5c4b-a03a-0b4dbc0c9a90","sourceKey":"bank:BUA216:OVF-038","parentItemId":null,"revision":1,"payload":{"prompt":"The finance manager of Aba Plastics Ltd is evaluating whether to spend N80 million on a new moulding machine expected to generate cash inflows for eight years. This is an example of which finance decision?","options":["Profit allocation decision","Dividend decision","Financing decision","Investment decision"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Deciding whether to commit funds to a long-term asset such as a machine is the investment (capital budgeting) decision. The financing decision (option C) is about how the money will be raised, while the dividend decision (option B), also called the profit allocation decision (option A), is about sharing profit."}},{"itemId":"f062d507-2ba9-5611-9027-b0029aaaaa0d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"72bde98e-1f6e-507b-be3b-7565ee4924a7","sourceKey":"bank:BUA216:OVF-039","parentItemId":null,"revision":1,"payload":{"prompt":"Having approved a new factory, the board of Delta Oil Services Plc must now choose between a bank loan and a rights issue to raise the N500 million required. This is an example of which finance decision?","options":["Working capital decision","Investment decision","Financing decision","Dividend decision"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Choosing how to raise funds, here debt (a loan) versus equity (a rights issue), is the financing or capital mix decision. The investment decision (option B) was taken when the factory was approved, the dividend decision (option D) concerns profit distribution, and option A concerns day-to-day current assets and liabilities."}},{"itemId":"4cb1416d-600d-55af-974f-81d954d0a011","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fd81d5dc-2af2-5c45-b556-c1f10dabf2c7","sourceKey":"bank:BUA216:OVF-040","parentItemId":null,"revision":1,"payload":{"prompt":"After earning a profit after tax of N120 million, the directors of Enugu Breweries Plc decide to pay 40% to shareholders and plough back the remaining 60% into the business. This is an example of which finance decision?","options":["Capital rationing decision","Investment decision","Dividend decision","Financing mix decision"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Splitting profit between a payout to shareholders and retention in the business is the dividend (profit allocation) decision. The investment decision (option B) is about which assets to acquire, the financing mix decision (option D) is about choosing between debt and equity, and capital rationing (option A) is about choosing projects when funds are limited."}},{"itemId":"82a7c20e-7835-5a18-ac28-781f19ed327c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af2a2ea5-dec2-52ea-8db6-0db6f0fe5286","sourceKey":"bank:BUA216:OVF-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the logical order in which most businesses take their major finance decisions?","options":["Dividend decision, then financing decision, then investment decision","Dividend decision, then investment decision, then financing decision","Financing decision, then dividend decision, then investment decision","Investment decision, then financing decision, then dividend decision"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"A firm first decides what to invest in, then how to finance it, and finally what to do with the profits the investment earns, so the order is investment, financing, dividend. Options B, C and A put profit distribution or fund raising before the firm even knows what it is investing in."}},{"itemId":"a37f3fef-9eb5-5246-a64a-c51b2711f212","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e4b6ab4f-a5e5-5cf9-872e-1f938db01208","sourceKey":"bank:BUA216:OVF-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of the investment decision?","options":["Ranking competing long-term projects","Deciding whether to replace an old production line","Choosing the proportion of debt and equity in the firm's capital","Evaluating whether to buy a new delivery fleet"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Choosing the mix of debt and equity is the financing (capital mix) decision, not an investment decision. Options D, A and B all involve deciding which long-term assets or projects to commit funds to, which is the investment or capital budgeting decision."}},{"itemId":"7233755e-d261-5bc5-8a57-5e6f5ddc2d4b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f11b9d57-719e-5196-9208-eba9adc1ea7a","sourceKey":"bank:BUA216:OVF-043","parentItemId":null,"revision":1,"payload":{"prompt":"The dividend decision is closely linked to the financing decision mainly because:","options":["Profits retained instead of paid out become internal finance for the firm","Dividends are paid only in the money market","Paying dividends increases the firm's debt","Dividends are a legal expense deducted before tax"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Every naira of profit not paid out as dividend stays in the business as retained earnings, which is a means of financing new investment, so the two decisions affect each other. Option D is false because dividends are paid out of profit after tax, option C confuses dividends with borrowing, and option B has no meaning."}},{"itemId":"b2bebe89-33b1-51eb-bb41-112ecd607ade","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"416c80da-9f90-5256-8fb9-cde9316f8cab","sourceKey":"bank:BUA216:OVF-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a weakness of profit maximisation as the objective of a firm?","options":["It uses discounted cash flows to judge projects","It focuses on the market value of the firm's shares","It ignores the risk attached to expected profits","It takes account of the time value of money"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Profit maximisation simply chooses the highest profit figure, without asking how risky that profit is. Options A, B and D are actually features of wealth maximisation, which discounts cash flows, focuses on share value and allows for the time value of money."}},{"itemId":"2f4fb4b7-da07-5981-a156-c1739b2398f1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f7087e9e-12b9-5b95-8c98-6cd07f4ad7cf","sourceKey":"bank:BUA216:OVF-045","parentItemId":null,"revision":1,"payload":{"prompt":"A director says the company's goal is to maximise profit, but board members cannot agree whether this means profit before or after tax, total profit or profit per share, this year or over ten years. This illustrates which criticism of profit maximisation?","options":["Profit maximisation considers too much risk","The term 'profit' is vague or ambiguous","Profit maximisation always uses market prices","Profit maximisation discounts future profits too heavily"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Because 'profit' can be measured in many ways and over different periods, the goal is ambiguous and gives managers no precise target. Options A, C and D are wrong because profit maximisation does not consider risk, does not rely on share prices and does not discount future profits at all."}},{"itemId":"30abe7b1-c050-5a0f-a130-f0da497d36af","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c502b063-174e-5cf1-b777-53b6d8b84cae","sourceKey":"bank:BUA216:OVF-046","parentItemId":null,"revision":1,"payload":{"prompt":"Under the wealth maximisation objective, a firm should accept an investment project when:","options":["It is financed entirely by debt","Its accounting profit in the first year is the highest","It produces the largest total undiscounted profit","Its net present value is positive"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Wealth maximisation judges projects by discounting their cash flows, and a project with a positive net present value adds to the value of the shareholders' wealth. Options B and C are profit maximisation thinking that ignores timing and risk, and option A confuses the investment decision with the financing decision."}},{"itemId":"1b2e221f-f2fe-532c-b5fe-86ba59243d4c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e40e04d2-adbe-5cd8-b4bc-16a0c6c0b21c","sourceKey":"bank:BUA216:OVF-047","parentItemId":null,"revision":1,"payload":{"prompt":"Project A is expected to earn profits of N600,000, N400,000 and N200,000 at the end of years 1, 2 and 3. Project B is expected to earn N200,000, N400,000 and N600,000 over the same years. Using a discount rate of 10% per annum, by how much does the present value of Project A exceed that of Project B, to the nearest naira?","options":["N963,186","N63,110","N0","N1,026,296"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"PV(A) = 600,000/1.1 + 400,000/(1.1)^2 + 200,000/(1.1)^3 = N1,026,296 and PV(B) = 200,000/1.1 + 400,000/(1.1)^2 + 600,000/(1.1)^3 = N963,186, so A exceeds B by N63,110. Option C is the profit maximisation view, which sees both projects as equal because each earns N1,200,000 in total and ignores timing. Options D and A are the separate present values, not the difference."}},{"itemId":"6cda378d-546e-5ac9-91ae-2aa128c0fa89","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a45f3fa5-3ea1-535f-9af2-9d6c7940aa5a","sourceKey":"bank:BUA216:OVF-048","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N1,000,000 today and is expected to return a single cash inflow of N1,150,000 at the end of year 2. If the required rate of return is 10% per annum compounded annually, what is the project's net present value, to the nearest naira?","options":["N150,000","-N49,587","-N41,667","N45,455"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"NPV = 1,150,000/(1.1)^2 - 1,000,000 = 950,413 - 1,000,000 = -N49,587, so a wealth-maximising firm would reject it. Option A is the N150,000 surplus a profit-maximiser would see by ignoring the time value of money, option D discounts for only one year, and option C uses 20% simple interest instead of compounding."}},{"itemId":"3d871a7d-607b-57d5-9619-47cfcbeff138","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"96e6c0b5-4a3b-5fc6-b4d6-0df5281e0b55","sourceKey":"bank:BUA216:OVF-049","parentItemId":null,"revision":1,"payload":{"prompt":"Ibadan Foods Plc has 4,000,000 ordinary shares in issue. After it announces a profitable new contract, its share price rises from N12.50 to N14.00. Taking shareholders' wealth as the number of shares multiplied by the market price per share, by how much has shareholders' wealth increased?","options":["N1.50","N50,000,000","N56,000,000","N6,000,000"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Shareholders' wealth rises by 4,000,000 x (14.00 - 12.50) = 4,000,000 x 1.50 = N6,000,000. Options C and B are the total wealth after and before the announcement, not the increase, and option A is the gain per share only."}},{"itemId":"7a4a0c17-d414-5c2a-80a0-a0e4c4660076","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f44bffff-dc04-5e7b-8610-b03bbaa83b7e","sourceKey":"bank:BUA216:OVF-050","parentItemId":null,"revision":1,"payload":{"prompt":"The conflict of interest that arises when the managers of a company pursue their own goals instead of maximising the wealth of the shareholders is known as the:","options":["Free-rider problem","Liquidity problem","Agency problem","Gearing problem"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Managers act as agents of the shareholders, and when they put their own interests first the resulting conflict is called the agency problem. A liquidity problem (option B) is a shortage of cash, the free-rider problem (option A) concerns people enjoying benefits without paying, and gearing (option D) concerns the mix of debt and equity."}},{"itemId":"8ee6f4df-1d3b-54c2-b786-ba0e4b50014b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bac53d46-8c1d-5c6a-a683-d68e2ebc068d","sourceKey":"bank:BUA216:OVF-051","parentItemId":null,"revision":1,"payload":{"prompt":"In the agency relationship within a limited liability company, the shareholders are the:","options":["Principals","Auditors","Creditors","Agents"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Shareholders own the company and appoint managers to run it on their behalf, so the shareholders are the principals and the managers are the agents. Option D is the managers' role, creditors (option C) are lenders such as debenture holders, and auditors (option B) are appointed to check the managers."}},{"itemId":"53a43ac9-3726-57df-80da-d8b519352eaa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb2bbf7e-93db-5a2b-93c2-e81760fee102","sourceKey":"bank:BUA216:OVF-052","parentItemId":null,"revision":1,"payload":{"prompt":"The managers of Sokoto Steel Plc buy themselves expensive official cars and reject a profitable but risky expansion project because they fear it might threaten their jobs. This behaviour is an example of:","options":["The dividend decision","Wealth maximisation","The agency problem","Financial intermediation"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"The managers are placing their own comfort and job security above the shareholders' wealth, which is the agency problem. The dividend decision (option A) concerns profit distribution, wealth maximisation (option B) is the very goal they are failing to pursue, and financial intermediation (option D) concerns channelling funds between savers and borrowers."}},{"itemId":"05205151-cd9f-550c-a53d-3c14a98203a2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b53961bd-a0f5-50e2-a009-37f8368f0999","sourceKey":"bank:BUA216:OVF-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the best example of an agency cost borne by shareholders?","options":["Fees paid for an external audit to monitor the managers","Corporate income tax paid to government","The cost of raw materials used in production","Interest paid to the company's bankers"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Agency costs are costs shareholders incur to monitor or control managers, and an external audit is a classic monitoring cost. Options C, B and D are normal operating, tax and financing costs that would arise even if there were no conflict between owners and managers."}},{"itemId":"db313ce8-6b0c-5e39-9cdd-9783e70d3790","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3b63a975-2600-5a0c-b914-dada5670264e","sourceKey":"bank:BUA216:OVF-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following measures is most likely to reduce the agency problem between shareholders and managers?","options":["Removing the requirement for an annual audit","Linking managers' rewards to the company's share price through share options","Paying managers a fixed salary regardless of performance","Allowing managers to set their own pay"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Share options make managers gain when the share price rises, so their interests move into line with those of the shareholders. Options C, A and D either remove the incentive to perform or weaken the shareholders' control, which would make the agency problem worse."}},{"itemId":"b55b5862-4171-5152-a180-11cfb9de5dd8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cd10b28c-5e5f-541f-bf3b-9378b2fe1c58","sourceKey":"bank:BUA216:OVF-055","parentItemId":null,"revision":1,"payload":{"prompt":"The agency problem in large companies arises mainly from:","options":["The separation of ownership from control","The payment of interest on debentures","The existence of the Securities and Exchange Commission","The use of the money market for short-term funds"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"In large companies the shareholders who own the business are not the managers who control it, and this separation creates the room for conflicting goals. Options D, C and B describe market features and regulation that do not by themselves create a conflict between owners and managers."}},{"itemId":"ba59448c-5fad-52b4-b2b3-c744fcda04f8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b159fd2a-da25-5c57-a017-0315de1d53d6","sourceKey":"bank:BUA216:OVF-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a financial intermediary?","options":["An insurance company","A pension fund administrator","The Securities and Exchange Commission","A commercial bank"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"A financial intermediary collects funds from savers and passes them on to borrowers or investments, which banks, insurers and pension fund administrators all do (options D, A and B). The Securities and Exchange Commission regulates the capital market but does not take in savings or lend funds."}},{"itemId":"713cc3f0-160f-5c97-8b2c-158eb467df3a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b313832-9154-5178-8e31-e63779f80dc5","sourceKey":"bank:BUA216:OVF-057","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which financial institutions transfer financial resources from surplus units (savers) to deficit units (borrowers) for productive investment is called:","options":["Financial intermediation","Hedging","Disintermediation","Arbitrage"],"correctOption":0,"section":"Overview of Finance and Financial Markets","explanation":"Moving funds from surplus units to deficit units through institutions is the intermediation process. Disintermediation (option C) is the opposite, where borrowers bypass the institutions, arbitrage (option D) is profiting from price differences, and hedging (option B) is reducing risk."}},{"itemId":"b52c1e41-b888-5c00-9ea9-638bcb223dad","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"330c8303-9429-52b6-8e22-9a8ca2aebd01","sourceKey":"bank:BUA216:OVF-058","parentItemId":null,"revision":1,"payload":{"prompt":"A commercial bank accepts many small savings deposits that customers can withdraw at short notice and uses them to grant a five-year loan to a manufacturer. Which service of a financial intermediary does this illustrate?","options":["Issuing new shares on behalf of the depositors","Transforming short-term deposits into long-term loans (maturity transformation)","Implementing fiscal policy for government","Guaranteeing a buyer's promise to pay a seller"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The bank turns short-term, withdrawable deposits into a long-term loan, which is maturity transformation, one of the main services of intermediaries. Option C is a government budget role, option A would be a primary market share issue, and option D describes a banker's acceptance."}},{"itemId":"111f6dae-7222-5bc3-a874-1cbdc8363f95","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d4cccc3d-201f-5f67-b97b-d60633bc3286","sourceKey":"bank:BUA216:OVF-059","parentItemId":null,"revision":1,"payload":{"prompt":"An investor buys a 91-day treasury bill with a face value of N10,000,000 for N9,700,000 and holds it to maturity. Using a 365-day year, what is the annualised yield on the amount invested, to 2 decimal places?","options":["12.03%","3.09%","12.24%","12.41%"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Yield = (discount / price) x (365 / days) = (300,000 / 9,700,000) x (365 / 91) = 12.41%. Option A divides the discount by the face value instead of the price, option C uses a 360-day year, and option B is the 91-day return before annualising."}},{"itemId":"6c7b7920-63df-5b39-bf20-078e0f059466","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"862a94ee-cf03-5efa-afac-d6c1e269b5ae","sourceKey":"bank:BUA216:OVF-060","parentItemId":null,"revision":1,"payload":{"prompt":"A 182-day treasury bill with a face value of N5,000,000 is issued at a discount rate of 12% per annum, where price = face value x (1 - discount rate x days/365). What is the issue price, to 2 decimal places?","options":["N4,717,712.75","N299,178.08","N4,700,821.92","N4,696,666.67"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Price = 5,000,000 x (1 - 0.12 x 182/365) = 5,000,000 - 299,178.08 = N4,700,821.92. Option D uses a 360-day year, option A divides the face value by (1 + 0.12 x 182/365) instead of using the stated discount formula, and option B is the discount, not the price."}},{"itemId":"e4186b31-f75f-578f-9106-4f3a11e7a3c7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6bd11a57-14aa-5b2f-9dba-d4d6fdf37131","sourceKey":"bank:BUA216:OVF-061","parentItemId":null,"revision":1,"payload":{"prompt":"Under a repurchase agreement, Bank X sells government securities to Bank Y for N20,000,000 and agrees to buy them back after 14 days for N20,092,000. Using a 365-day year and the selling price as the base, what is the implied annual interest rate, to 2 decimal places?","options":["0.46%","11.99%","11.94%","11.83%"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"Interest = 20,092,000 - 20,000,000 = N92,000, so the rate = (92,000 / 20,000,000) x (365 / 14) = 11.99%. Option A is the 14-day rate before annualising, option D uses a 360-day year, and option C divides by the repurchase price instead of the selling price."}},{"itemId":"ef52acf6-2659-557d-a623-27defa390f06","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2042f64-e183-5de1-9690-03b1ee36152b","sourceKey":"bank:BUA216:OVF-062","parentItemId":null,"revision":1,"payload":{"prompt":"A bank issues a 180-day certificate of deposit of N2,000,000 paying simple interest of 10% per annum. Using a 365-day year, how much interest will the bearer receive at maturity, to 2 decimal places?","options":["N200,000.00","N100,000.00","N49,315.07","N98,630.14"],"correctOption":3,"section":"Overview of Finance and Financial Markets","explanation":"Interest = 2,000,000 x 0.10 x 180/365 = N98,630.14. Option B uses a 360-day year, option A charges a full year's interest, and option C wrongly halves the 180-day interest again."}},{"itemId":"1d50f763-2705-5b54-b7f6-ccf52abded8e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c4fdd0b0-f252-5eea-bcea-0ea3b5836b63","sourceKey":"bank:BUA216:OVF-063","parentItemId":null,"revision":1,"payload":{"prompt":"Ondo Cocoa Plc sells 2,000,000 new shares to the public at N5.00 each. A year later, an investor who bought 500,000 of these shares resells them to another investor on the stock exchange at N7.00 each. How much in total has Ondo Cocoa Plc received from these two transactions?","options":["N14,000,000","N10,000,000","N3,500,000","N13,500,000"],"correctOption":1,"section":"Overview of Finance and Financial Markets","explanation":"The company receives money only in the primary market: 2,000,000 x N5.00 = N10,000,000. The resale of 500,000 x N7.00 = N3,500,000 is a secondary market trade whose proceeds go to the selling investor, so option D wrongly adds it, option A values all the shares at the later price, and option C is the resale amount alone."}},{"itemId":"9dd46234-6d21-5c8f-876c-4c4a72506f2e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c39ed97f-55c9-52fb-9a08-638d4300996f","sourceKey":"bank:BUA216:OVF-064","parentItemId":null,"revision":1,"payload":{"prompt":"Kwara Mills Plc earns a profit after tax of N8,000,000 and adopts a dividend payout ratio of 35%. How much of the profit is retained in the business as internal finance?","options":["N8,000,000","N10,800,000","N5,200,000","N2,800,000"],"correctOption":2,"section":"Overview of Finance and Financial Markets","explanation":"Retained earnings = 8,000,000 x (1 - 0.35) = 8,000,000 x 0.65 = N5,200,000. Option D is the dividend paid, option A ignores the dividend altogether, and option B wrongly adds the dividend to the profit."}},{"itemId":"626ca966-8e1b-5c37-8799-464aadbf2624","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b2a35b25-bf21-5bac-80e3-64c174a6610a","sourceKey":"bank:BUA216:PEN-001","parentItemId":null,"revision":1,"payload":{"prompt":"A retirement savings pool created by employers, unions or government to provide workers with income when they retire is called a:","options":["Hedge fund","Mutual fund","Sinking fund","Pension fund"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A pension fund collects regular contributions during a worker's career, invests them professionally and pays them out as income after retirement. Option B pools money from the general public for investment, not specifically for retirement, and option A is a private high-risk pool for wealthy investors. Option C is money set aside to repay a debt or replace an asset."}},{"itemId":"a58bddf5-546d-5775-adb5-91e4014c2462","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4e719d25-3120-5d2a-9e06-798528596979","sourceKey":"bank:BUA216:PEN-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes how a pension fund works?","options":["Regular contributions are professionally invested and later paid out as a pension","Contributions are kept as idle cash and returned without any growth","Members borrow from the pool at low interest during their working years","The government pays all retirees from taxes with no member contributions"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"In a pension fund, employees and employers make regular contributions into a retirement savings account, which is invested to grow and is later distributed as a pension. Option C describes a cooperative loan scheme, and option B ignores the investment that makes the fund grow. Option D describes a pay-as-you-go state arrangement with no contributions, not a pension fund."}},{"itemId":"0a474687-86fb-5834-bb42-4ed47939434a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cc8a8cb4-e80c-5aa3-88d7-5ac2e663a465","sourceKey":"bank:BUA216:PEN-003","parentItemId":null,"revision":1,"payload":{"prompt":"Under Nigeria's Pension Reform Act 2014, what is the minimum total contribution (employer plus employee) to an employee's retirement savings account, as a percentage of monthly emoluments?","options":["15%","8%","10%","18%"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Pension Reform Act 2014 sets a minimum of 10% from the employer and 8% from the employee, a combined 18% of monthly emoluments. Option A (15%) was the combined rate under the earlier 2004 Act. Options C and B are only the employer's and the employee's shares on their own."}},{"itemId":"6ce1ef9f-92ee-5f6c-b888-58f303f01aab","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"db9fdcb1-090a-5344-84ab-9baa37b3c567","sourceKey":"bank:BUA216:PEN-004","parentItemId":null,"revision":1,"payload":{"prompt":"Under Nigeria's Contributory Pension Scheme (Pension Reform Act 2014), the pension contributions of an employee must be privately managed by:","options":["Any commercial bank the employee chooses","A licensed pension fund administrator","The Central Bank of Nigeria","The employee's own employer"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Contributions under the scheme are managed exclusively by a licensed (registered) pension fund administrator, which opens the employee's retirement savings account and invests the money. Option D is wrong because the employer only deducts and remits the contributions, it does not manage them. Options A and C are not licensed to administer pension funds under the scheme."}},{"itemId":"87206b93-c8bd-5198-93be-114b6e2577a1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c091f72-a23c-56d6-8c87-a584d197ed0f","sourceKey":"bank:BUA216:PEN-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a function of a pension fund administrator?","options":["Paying retirement benefits to the retiree","Keeping safe custody of the pension assets on trust","Investing and managing pension fund assets","Opening a retirement savings account for the employee"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Safe custody of pension assets is the job of the pension fund custodian, which holds the assets and acts on the administrator's instructions. Opening the retirement savings account (D), investing and managing the assets (C) and paying retirement benefits (A) are all functions of the pension fund administrator."}},{"itemId":"cc1551af-fc02-50cb-9d24-e249ccb827db","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1384d222-daec-5aa2-98ea-897e8478fabe","sourceKey":"bank:BUA216:PEN-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a function of a pension fund administrator?","options":["Providing regular account statements and updates on fund transactions","Licensing other pension fund administrators","Setting the minimum contribution rates for all employers","Deducting contributions from workers' salaries at source"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A pension fund administrator keeps contributors informed by sending regular statements and updates on transactions in their accounts. Options C and B belong to the law and the regulator (the National Pension Commission), not to an administrator. Option D is the employer's duty, since the employer deducts and remits the contributions."}},{"itemId":"0bd4edda-109c-5fa6-b2f1-041c032b541b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f6347c05-6cee-53d9-b364-7bdaf335ec9d","sourceKey":"bank:BUA216:PEN-007","parentItemId":null,"revision":1,"payload":{"prompt":"Adaeze's employer remits her pension contributions every month. One firm invests the money and pays her benefits, while a separate firm holds the pension assets in safe keeping and settles trades only on the first firm's instructions. Under the Pension Reform Act 2014, the second firm is a:","options":["Pension fund administrator","Stockbroker","Fund trustee for unit holders","Pension fund custodian"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A pension fund custodian keeps pension assets in safe custody, separate from the administrator, and acts on the administrator's instructions. Option A, the administrator, is the first firm that invests and pays benefits. Options C and B are roles in collective investment schemes and share trading, not the holder of pension assets."}},{"itemId":"a7f1f50e-c2b6-5f10-b1b3-d224447011a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"05c77dce-3571-5c2b-b66b-955949ced79e","sourceKey":"bank:BUA216:PEN-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which body regulates and supervises pension fund administrators and custodians under Nigeria's Pension Reform Act 2014?","options":["The Corporate Affairs Commission","The National Pension Commission (PenCom)","The Nigerian Exchange Group","The Securities and Exchange Commission (SEC)"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The National Pension Commission (PenCom) superintends the Contributory Pension Scheme, licenses administrators and custodians and can intervene in their management. Option D regulates the capital market and collective investment schemes such as unit trusts, not pension operators. Options C and A are a stock exchange group and the company registry."}},{"itemId":"58fcaa8a-83d1-5393-8d20-8db61fe6056d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f6eac800-ad20-5239-9fc5-632624169e3e","sourceKey":"bank:BUA216:PEN-009","parentItemId":null,"revision":1,"payload":{"prompt":"The Pension Reform Act 2014, which now governs Nigeria's Contributory Pension Scheme, repealed which earlier law?","options":["The Investments and Securities Act 2007","The Companies and Allied Matters Act 2020","The Pension Reform Act 2004","The Banks and Other Financial Institutions Act 2020"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Pension Reform Act 2014, signed on 1 July 2014, repealed the Pension Reform Act 2004 that first set up the scheme. Option A is a capital market law (itself later replaced in 2025), and options B and D govern companies and banks, not pensions."}},{"itemId":"1a4964d0-86bf-5d02-9d91-18856b1d6d10","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"807258bc-efe5-5445-ba04-b12078737372","sourceKey":"bank:BUA216:PEN-010","parentItemId":null,"revision":1,"payload":{"prompt":"A pension plan that promises a specific, guaranteed monthly payout on retirement, calculated from the worker's salary history and years of service, is a:","options":["Personal or informal pension plan","Defined contribution plan","Money market fund","Defined benefit plan"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A defined benefit plan fixes the pension itself in advance using a formula based on salary and years of service. Option B fixes only the contributions, so the payout varies with investment performance. Option A is a flexible plan for self-employed or informal workers, and option C is a type of mutual fund."}},{"itemId":"77fb1bff-cb9c-5c19-85b3-19ff97f5b135","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b84b1d7-2f52-511f-b88f-1c5278f514c9","sourceKey":"bank:BUA216:PEN-011","parentItemId":null,"revision":1,"payload":{"prompt":"A pension plan with fixed contributions, in which the final retirement payout rises or falls with the performance of the funds invested, is a:","options":["Defined contribution plan","Defined benefit plan","Unfunded pay-as-you-go scheme","Final salary scheme"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"In a defined contribution (contributory) plan, what is fixed is the amount paid in; the amount paid out depends on how well the invested money performs. Options B and D guarantee the payout instead, a final salary scheme being a form of defined benefit plan. Option C pays pensions from current income rather than from invested contributions."}},{"itemId":"72b66dfd-e81f-5355-9c79-a17d156d2563","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f2d88c57-04b3-5760-9ff5-80c0861a6897","sourceKey":"bank:BUA216:PEN-012","parentItemId":null,"revision":1,"payload":{"prompt":"In which type of pension plan does the employee bear the investment risk, because a poor investment performance directly reduces the retirement payout?","options":["Defined benefit plan","Guaranteed annuity plan","Defined contribution plan","Final salary scheme"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"In a defined contribution plan the payout depends on how the invested contributions perform, so weak returns reduce the employee's pension and the risk sits with the employee. In a defined benefit plan (A), including a final salary scheme (D), the payout is promised, so the employer or sponsor must make up any shortfall. Option B also describes a promised payout."}},{"itemId":"cd6c8a08-0332-5103-a75b-8ebb2cc7b267","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ea54708-37f5-583b-a843-54871a3ae78c","sourceKey":"bank:BUA216:PEN-013","parentItemId":null,"revision":1,"payload":{"prompt":"In a defined benefit pension plan, who bears the risk that the invested funds perform poorly?","options":["The employee, whose pension falls when returns fall","No one, because defined benefit funds are not invested","The pension fund custodian, who must refund any losses","The employer or plan sponsor, who must still pay the promised benefit"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Because a defined benefit plan guarantees the payout, the sponsor (usually the employer) must fund the promised pension even if investments do badly. Option A describes a defined contribution plan. Option C is wrong because a custodian only holds assets safely, and option B is wrong because defined benefit funds are normally invested too."}},{"itemId":"af101bf2-73c6-5f46-9bef-ed30ae877ad2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"24f0cda7-4eb0-53f9-9718-f5e015b98810","sourceKey":"bank:BUA216:PEN-014","parentItemId":null,"revision":1,"payload":{"prompt":"Kunle is a self-employed tailor in Aba with irregular income. He wants to save for retirement in a flexible way. Which type of pension plan is designed for him?","options":["Personal or informal pension plan","Defined benefit plan","Closed-end fund","Employer group life policy"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A personal or informal pension plan is designed for self-employed people and informal sector workers to save for retirement flexibly. Option B is normally offered by an employer and promises a salary-based payout, which Kunle does not have. Option D is life insurance cover, not retirement savings, and option C is a listed investment fund, not a pension plan."}},{"itemId":"6a563c20-5b53-5990-bde2-3ed68c76f49e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"06bad225-b843-57dc-b94d-f75b0b09ae4d","sourceKey":"bank:BUA216:PEN-015","parentItemId":null,"revision":1,"payload":{"prompt":"At retirement, Mrs Okafor learns that her pension depends entirely on the balance in her retirement savings account, which grew from her and her employer's fixed contributions and the returns earned on them. Her plan is best described as a:","options":["Defined benefit plan","Unfunded pension plan","Hedge fund","Defined contribution plan"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Fixed contributions plus whatever the investments earned, with no promised payout, is the mark of a defined contribution plan. Option A would have promised her a specific amount based on salary and years of service. Option B is wrong because her pension comes from an accumulated, invested balance, and option C is an investment pool, not a pension plan."}},{"itemId":"4ddc5d7e-9a2f-5b98-967e-55b9e3c39cfb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7a1b50fb-ce6c-5692-9c38-d0921968c18a","sourceKey":"bank:BUA216:PEN-016","parentItemId":null,"revision":1,"payload":{"prompt":"A pension plan in which benefits are paid out of an accumulated pool of contributions that has been set aside and invested in advance is described as:","options":["Funded","Unfunded","Pay-as-you-go","Defined benefit by definition"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A funded plan builds up a pool of assets from contributions before benefits fall due, and pays pensions from that pool. Options B and C describe the opposite arrangement, where pensions are paid from the sponsor's current income or current contributions. Option D is wrong because a defined benefit plan can be either funded or unfunded."}},{"itemId":"ca50c3c5-a6c5-5fd9-b03e-f55bfef6c232","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dd387c6d-592c-5126-bb3b-8dbe84a54e2f","sourceKey":"bank:BUA216:PEN-017","parentItemId":null,"revision":1,"payload":{"prompt":"A state government pays its retired workers' pensions each month directly out of that month's revenue, without any invested pool of assets. This pension arrangement is:","options":["Unfunded","A money market fund","A defined contribution plan","Funded"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"When pensions are paid from current revenue rather than from assets set aside in advance, the plan is unfunded (pay-as-you-go). Option D requires an accumulated, invested pool. Option C is wrong because a contribution plan pays out of each member's own invested balance, and option B is a mutual fund type."}},{"itemId":"cf132b0f-afd8-59b8-9b54-0acab5bed64f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1c33731d-c3f4-5117-bb2f-e6747534e572","sourceKey":"bank:BUA216:PEN-018","parentItemId":null,"revision":1,"payload":{"prompt":"Under Nigeria's Contributory Pension Scheme (Pension Reform Act 2014), each employee's contributions go into an individual retirement savings account that is invested and paid out at retirement. This scheme is therefore best described as:","options":["Unfunded and defined benefit","Funded and defined benefit","Unfunded and defined contribution","Funded and defined contribution"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Contributions are fixed percentages of emoluments and accumulate in an invested individual account, so the scheme is funded, and the payout depends on the account balance, so it is defined contribution. Option A describes a pay-as-you-go guaranteed pension. Option B wrongly implies a guaranteed payout, and option C wrongly implies there is no invested pool."}},{"itemId":"9d86d435-d5a9-5138-baa2-650fbc62bb74","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1ec0fe82-d4cf-5689-8be9-bb699a1d45e0","sourceKey":"bank:BUA216:PEN-019","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, within what period after paying salaries must an employer deduct and remit employees' pension contributions?","options":["3 months","30 days","7 working days","24 hours"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Pension Reform Act 2014 requires employers to remit the deducted contributions within 7 working days of paying salaries, and late remittance attracts a penalty. Options D, B and A are not the deadline set by the Act."}},{"itemId":"9b26b070-c7a6-5ae0-8e8d-48c15ec02969","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e2d56d2e-fc08-50a5-b48f-30b7e978902f","sourceKey":"bank:BUA216:PEN-020","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, a private sector employer is required to join the Contributory Pension Scheme if it has at least how many employees?","options":["3","5","50","15"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The 2014 Act raised the threshold for compulsory participation of private sector employers to 15 employees, from 5 under the earlier law. Option B is the old 2004 threshold, and options A and C are not the figure in the Act; employees of smaller firms may still join voluntarily."}},{"itemId":"3f9a9de2-01d9-59e2-8145-ca07ae92d31f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ad3a8ee3-85bb-55eb-82d8-a55c4d6c08e9","sourceKey":"bank:BUA216:PEN-021","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, the monthly emoluments on which pension contributions are based must not be less than the total of:","options":["Basic salary only","Basic salary, housing allowance and transport allowance","Housing allowance and leave allowance","Basic salary and overtime pay"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Act treats monthly emoluments as the total emoluments in the contract of employment, but never less than basic pay plus housing and transport allowances. Option A leaves out the two allowances, and options D and C include items that are not part of this minimum base."}},{"itemId":"0781808c-842c-5eed-a2c8-e82b486c9596","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3a98c39e-0c5a-548d-aa49-9b0b82123d40","sourceKey":"bank:BUA216:PEN-022","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, an employee who resigns or is disengaged and remains without a job for 4 months may withdraw what share of the balance in his or her retirement savings account?","options":["100%","50%","10%","25%"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The 2014 Act allows a person who retires voluntarily, resigns or is disengaged, and stays unemployed for 4 months, to access 25% of the retirement savings account balance. Options B, C and A are not the percentage in the Act; withdrawing everything would defeat the purpose of saving for retirement."}},{"itemId":"30ec55ad-6fd5-51fb-93cc-c02efcc5b457","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4e488f52-e217-5b4a-9176-c40d9675567c","sourceKey":"bank:BUA216:PEN-023","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, the minimum contributions are 10% of monthly emoluments from the employer and 8% from the employee. Tola's monthly emoluments are N250,000. What is the minimum total amount that should be paid into her retirement savings account each month?","options":["N25,000","N45,000","N20,000","N37,500"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Total contribution = (10% + 8%) x monthly emoluments = 0.18 x 250,000 = N45,000. Option A is only the employer's 10% and option C only the employee's 8%. Option D uses the old combined rate of 15%."}},{"itemId":"8cc4e57b-c51b-517f-bb0e-c081549c6f0e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6850f49-6fd2-5909-8bca-d28aecbdf9a0","sourceKey":"bank:BUA216:PEN-024","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014 the employee's minimum pension contribution is 8% of monthly emoluments and the employer's is 10%. If Ibrahim's monthly emoluments are N320,000, how much should be deducted from his pay each month as his own contribution?","options":["N25,600","N6,400","N32,000","N57,600"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The employee's share = 8% x 320,000 = N25,600. Option C applies the employer's 10% rate, and option D is the combined 18% paid by both parties. Option B is only the 2% difference between the two rates."}},{"itemId":"cd736597-c827-54f7-a789-e9d6cd3acf36","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7494c031-24d6-5f5a-a469-f376686254fb","sourceKey":"bank:BUA216:PEN-025","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, an employer must contribute at least 10% of monthly emoluments and the employee at least 8%. An employee's monthly emoluments are N180,000. What is the employer's minimum contribution for a full year of 12 months?","options":["N18,000","N172,800","N388,800","N216,000"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Annual employer contribution = 10% x 180,000 x 12 = N216,000. Option A is only one month's contribution, option C uses the combined 18% rate, and option B uses the employee's 8% rate."}},{"itemId":"bc851e4c-b57b-50b3-9ddc-3d4a6138aca8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7d97f13f-ab0b-570d-8b54-b6351b81e13b","sourceKey":"bank:BUA216:PEN-026","parentItemId":null,"revision":1,"payload":{"prompt":"Chioma's monthly pay is: basic salary N200,000, housing allowance N80,000, transport allowance N40,000 and meal allowance N30,000. Her contract defines pensionable emoluments as basic salary plus housing and transport allowances. Taking the minimum rates of 10% (employer) and 8% (employee) under the Pension Reform Act 2014, what is the total monthly pension contribution?","options":["N57,600","N63,000","N32,000","N36,000"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Pensionable emoluments = 200,000 + 80,000 + 40,000 = N320,000, and total contribution = 18% x 320,000 = N57,600. Option B wrongly includes the meal allowance (18% of N350,000), and option D applies 18% to basic salary alone. Option C is only the employer's 10%."}},{"itemId":"94c31cb7-fed8-5b82-9dd2-04559a5f7267","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ed3f6e53-8b63-5663-8e87-fcfae435eda5","sourceKey":"bank:BUA216:PEN-027","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, an employer that chooses to bear the full cost of pension contributions (so the employee contributes nothing) must contribute at least 20% of monthly emoluments. If an employee's monthly emoluments are N150,000, what is the employer's minimum monthly contribution under this option?","options":["N27,000","N30,000","N12,000","N15,000"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"When the employer bears the whole cost, the minimum is 20% of emoluments: 0.20 x 150,000 = N30,000. Option A uses the normal combined rate of 18%, while options D and C are the ordinary 10% employer and 8% employee shares."}},{"itemId":"e579f2d6-ceb5-5ad2-9da8-ef250b76abaa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3f41ab1f-4da9-58cd-bc05-cbae35b257ef","sourceKey":"bank:BUA216:PEN-028","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014, an employer must keep a group life insurance policy for each employee worth at least three times the employee's annual emolument. If an employee's annual emolument is N3,600,000, what is the minimum cover?","options":["N900,000","N10,800,000","N3,600,000","N1,200,000"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Minimum cover = 3 x annual emolument = 3 x 3,600,000 = N10,800,000. Option C is only one year's emolument, option D divides by 3 instead of multiplying, and option A treats the cover as three months' pay."}},{"itemId":"b7726ab4-8faf-5c91-bc09-6e06d4bc8f93","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b43739c6-8d3b-510d-a187-050820858b4b","sourceKey":"bank:BUA216:PEN-029","parentItemId":null,"revision":1,"payload":{"prompt":"Under the Pension Reform Act 2014 the minimum contributions are 10% (employer) and 8% (employee) of monthly emoluments, and an employee may also make voluntary contributions. Yusuf earns monthly emoluments of N300,000 and also pays a voluntary contribution of N20,000 a month. How much goes into his retirement savings account each month in total?","options":["N50,000","N54,000","N44,000","N74,000"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Mandatory contributions = 18% x 300,000 = N54,000, and adding the voluntary N20,000 gives N74,000. Option B leaves out the voluntary contribution. Option C adds the voluntary amount to the employee's 8% only, and option A adds it to the employer's 10% only."}},{"itemId":"aed9f358-4756-5342-9481-0f3d411d4073","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"60ac44f2-560b-57d5-9e8b-b0ef282357b3","sourceKey":"bank:BUA216:PEN-030","parentItemId":null,"revision":1,"payload":{"prompt":"A defined benefit (final salary) pension scheme pays an annual pension of 1/60 of final annual salary for each year of service. Mr Bello retires after 30 years of service. His final annual salary is N4,800,000 and his career-average salary is N3,600,000. What is his annual pension?","options":["N200,000","N2,400,000","N80,000","N1,800,000"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Annual pension = (30 / 60) x 4,800,000 = N2,400,000. Option D wrongly uses the career-average salary instead of final salary, option C forgets to multiply by the 30 years of service, and option A is the monthly pension rather than the annual figure."}},{"itemId":"9f2bad17-fe7d-58f2-8f09-50c9e9fce7c3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3fbde972-dc0a-5bb9-9e96-d0fa1f2bfc11","sourceKey":"bank:BUA216:PEN-031","parentItemId":null,"revision":1,"payload":{"prompt":"Under a defined contribution plan, N600,000 is paid into a member's account at the END of each year for 3 years. The account earns 10% per annum compounded annually. To the nearest naira, what is the account balance immediately after the third payment?","options":["N2,184,600","N1,980,000","N1,986,000","N1,800,000"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"This is an ordinary annuity: FV = 600,000 x [(1.1)^3 - 1] / 0.1 = 600,000 x 3.31 = N1,986,000. Option D ignores interest, and option A treats the payments as an annuity due (made at the start of each year). Option B uses simple instead of compound interest."}},{"itemId":"42eef4b9-99d8-5340-a965-b2c0902e0c08","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ac086a8-9636-5731-9a19-f605a0c5aa96","sourceKey":"bank:BUA216:PEN-032","parentItemId":null,"revision":1,"payload":{"prompt":"An investment vehicle managed by finance professionals that lets individuals own a fraction of a large, diversified portfolio and share proportionally in its gains, losses or income is a:","options":["Treasury bill","Pension fund administrator","Mutual fund","Defined benefit plan"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A mutual fund pools money from many investors to buy a spread of stocks, bonds and money market instruments, and each investor shares in the results in proportion to his holding. Option B manages retirement savings accounts rather than a fund open to all investors, option D is a type of pension promise, and option A is a single short-term government security."}},{"itemId":"04482529-4ed8-58dc-a3da-58ae1ae5efb0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f628904b-6025-5307-9c9f-f5b1df72b156","sourceKey":"bank:BUA216:PEN-033","parentItemId":null,"revision":1,"payload":{"prompt":"Mutual funds are commonly categorised by all of the following EXCEPT:","options":["Their investment objective","Their risk level","The number of unit holders in the fund","Their underlying asset"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Mutual funds are grouped by how risky they are, what assets they hold and what they aim to achieve, which gives types such as money market, bond, equity and balanced funds. The number of people holding units does not define the type of fund. Options B, D and A are all standard bases of classification."}},{"itemId":"c8fa2752-14b2-51de-bb63-1a6e79943e03","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb5bc5c5-2e59-5777-8798-7a8d9ba231bb","sourceKey":"bank:BUA216:PEN-034","parentItemId":null,"revision":1,"payload":{"prompt":"A low-risk, highly liquid mutual fund that invests in short-term securities such as treasury bills and commercial paper is a:","options":["Equity fund","Money market fund","Balanced fund","Foreign currency fund"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A money market fund holds short-term instruments like treasury bills and commercial paper, so it is low risk and highly liquid. Option A invests mainly in company shares and is high risk. Option C mixes equity and bonds, and option D focuses on dollar-denominated assets."}},{"itemId":"dc0c8fbd-261d-5fab-95d5-81f4395d4e43","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9653b924-6007-50da-ad84-fc5c23c1abca","sourceKey":"bank:BUA216:PEN-035","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi wants somewhere to keep her emergency savings where the capital is well protected and she can withdraw quickly. Which type of mutual fund best suits her?","options":["Money market fund","Hedge fund","Equity fund","Balanced fund"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A money market fund is low risk and highly liquid, which makes it ideal for preserving capital and holding emergency funds. Option C is high risk, so its value can fall just when she needs the money. Option B is not a mutual fund and is usually closed to ordinary investors, and option D carries medium risk because of its equity portion."}},{"itemId":"9ccaa63b-d99f-5f82-9840-b080b493e717","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3b29b3c5-8c3e-5187-8605-6e00772cbf8c","sourceKey":"bank:BUA216:PEN-036","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund that invests in government and corporate debt to generate steady interest income, with low to moderate risk, is a:","options":["Equity fund","Money market fund","Halal fund","Fixed income (bond) fund"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A fixed income or bond fund buys government and corporate debt and aims for steady interest income. Option A buys company shares, option B buys only short-term instruments, and option C avoids interest-bearing instruments altogether."}},{"itemId":"9efe4459-e162-5946-9e0b-b9bd48ab8ed3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9da5be1f-6827-505f-aeb0-680d8565d3c2","sourceKey":"bank:BUA216:PEN-037","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of mutual fund is described as high risk, high reward, because it focuses primarily on company stocks?","options":["Balanced fund","Fixed income fund","Money market fund","Equity fund"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"An equity fund invests mainly in company shares, whose prices can rise or fall sharply, so it offers high potential reward with high risk. Options C and B hold debt instruments and are low or low-to-moderate risk. Option A mixes equity with bonds, giving medium risk."}},{"itemId":"2041844b-5405-5eaa-9774-062ce40eb970","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"da3fccf0-9d28-5d3d-8ee4-8ede9d47f5c7","sourceKey":"bank:BUA216:PEN-038","parentItemId":null,"revision":1,"payload":{"prompt":"A medium-risk mutual fund that combines a mixture of equities and bonds for balanced growth and risk protection is a:","options":["Money market fund","Foreign currency fund","Balanced (hybrid) fund","Equity fund"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A balanced or hybrid fund holds both shares and bonds, so it seeks growth from equities while bonds cushion the risk. Option D is almost all shares, option A holds short-term instruments only, and option B is defined by its currency, not by an equity-bond mix."}},{"itemId":"c882abcc-af94-5bcc-a344-681e8a7b30f9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"59a2ed90-f1fa-5fb3-8af1-ea1d68788dee","sourceKey":"bank:BUA216:PEN-039","parentItemId":null,"revision":1,"payload":{"prompt":"Emeka is worried that the naira will keep depreciating and wants a mutual fund that protects the value of his savings. Which fund focuses on dollar-denominated assets for this purpose?","options":["Fixed income fund","Halal fund","Foreign currency fund","Money market fund"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A foreign currency fund invests in dollar-denominated assets, so its value holds up when the local currency loses value. Options D and A usually hold naira instruments and so remain exposed to depreciation. Option B is defined by its ethical rules, not by its currency."}},{"itemId":"6cbeb996-cc3d-52c8-9e9f-f2fba84d556b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ad2f8d37-d41e-5e89-b399-02fb2146d3ee","sourceKey":"bank:BUA216:PEN-040","parentItemId":null,"revision":1,"payload":{"prompt":"Alhaji Musa wants to invest through a mutual fund but, for religious reasons, he will not hold interest-bearing instruments or invest in prohibited sectors. Which fund is designed for him?","options":["Money market fund","Halal or sharia-compliant fund","Hedge fund","Fixed income fund"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A halal or sharia-compliant fund is an ethically focused fund that avoids interest-bearing instruments and prohibited sectors. Options D and A earn mainly interest, which he wants to avoid. Option C is not a mutual fund and uses high-risk strategies with no such ethical restriction."}},{"itemId":"1b3a7c7b-70e0-507c-91ae-7c3d99ed4ded","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a2450600-5c70-50e4-9a0b-369752b2f95e","sourceKey":"bank:BUA216:PEN-041","parentItemId":null,"revision":1,"payload":{"prompt":"Arrange these mutual funds from LOWEST to HIGHEST risk: equity fund, money market fund, balanced fund.","options":["Money market fund, equity fund, balanced fund","Equity fund, balanced fund, money market fund","Money market fund, balanced fund, equity fund","Balanced fund, money market fund, equity fund"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Money market funds are low risk, balanced funds are medium risk because they mix bonds with shares, and equity funds are high risk. Option B reverses the order. Options D and A misplace the balanced fund, which sits between the other two."}},{"itemId":"acc8fdb7-ff04-5d7e-8162-c4e521710f80","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a85bc08e-d860-5597-b463-0ae6b72e20e2","sourceKey":"bank:BUA216:PEN-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a way in which a mutual fund generates income for its investors?","options":["Collecting fixed fees from the fund's own unit holders","Appreciation in the value of the shares it holds","Capital gains on securities sold at a profit","Dividend and interest income on its investments"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Fees charged to unit holders are a cost to investors and an income to the fund manager, not a return earned for investors. A mutual fund earns for its investors through dividends and interest (D), capital gains (C) and appreciation of the shares it holds (B)."}},{"itemId":"84d9704e-ef38-5042-ba2d-af55a6dbf6b9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d7e06895-095c-52a7-9495-c98a0c723840","sourceKey":"bank:BUA216:PEN-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes an open-end fund from a closed-end fund?","options":["An open-end fund creates and redeems units continuously at NAV; a closed-end fund's units trade on an exchange","An open-end fund's units trade only on a stock exchange; a closed-end fund redeems units at NAV daily","An open-end fund has a fixed number of units; a closed-end fund issues new units on demand","An open-end fund is restricted to wealthy investors; a closed-end fund is open to the public"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"An open-end fund keeps issuing new units and buying them back from investors at a price based on net asset value. A closed-end fund issues a fixed number of units, which are then listed and traded on the exchange at market prices. Options B and C reverse the two, and option D confuses fund structure with who may invest."}},{"itemId":"fb812511-e225-5af0-84d1-3773002069d3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4befd9a7-d6c4-58c4-b472-a42229a28695","sourceKey":"bank:BUA216:PEN-044","parentItemId":null,"revision":1,"payload":{"prompt":"Ngozi holds units in a fund that issued a fixed number of units at its launch. To sell, she must go through a stockbroker and accept the price on the stock exchange, which may differ from the fund's net asset value. Her fund is:","options":["A closed-end fund","An open-end fund","A defined benefit plan","A money market fund"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A closed-end fund does not create or redeem units after the offer, so investors buy and sell its units on the exchange through a stockbroker at market-determined prices. Option B would buy her units back directly at NAV. Option C is a pension plan, and option D is usually an open-end fund that redeems units directly."}},{"itemId":"8177a0e2-4016-51bd-99bd-94e23107d8f2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8e6be13b-1539-5f80-b0cb-0ca357e02fdc","sourceKey":"bank:BUA216:PEN-045","parentItemId":null,"revision":1,"payload":{"prompt":"For a mutual fund, (total assets - total liabilities) / number of units outstanding measures the fund's:","options":["Front-end load","Net asset value per unit","Rate of return","Expense ratio"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Net asset value (NAV) is the fund's assets minus its liabilities, and dividing by the units in issue gives NAV per unit, the price at which an open-end fund issues and redeems units. Option D compares annual expenses with net assets, option A is a sales charge on purchases, and option C compares the change in value over a period with the starting value."}},{"itemId":"61274fd5-783d-59b1-ad10-64322ccbe28a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8257ac55-52cb-53fb-ba2d-6b2fc044ee02","sourceKey":"bank:BUA216:PEN-046","parentItemId":null,"revision":1,"payload":{"prompt":"In a Nigerian unit trust, the agreement between the fund manager and the trustee that sets out the parties' rights, responsibilities and the fund's investment objectives is the:","options":["Retirement savings account","Custody receipt","Trust deed","Prospectus summary"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A unit trust is set up under a trust deed between the fund manager and the trustee, which sets out rights, duties and investment objectives. Option D is an offer document for investors, option A is a pension account, and option B is not the founding agreement of a unit trust."}},{"itemId":"23dec1d4-3ed5-58d9-b612-5c93c32a46d6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7d6be10e-c383-53d2-bf89-70a2b6d89fd1","sourceKey":"bank:BUA216:PEN-047","parentItemId":null,"revision":1,"payload":{"prompt":"In Nigeria, collective investment schemes such as unit trusts are regulated by the Securities and Exchange Commission under which current law?","options":["Pension Reform Act 2014","Pension Reform Act 2004","Investments and Securities Act 2025","Investments and Securities Act 2007"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Investments and Securities Act 2025, signed in March 2025, repealed the 2007 Act and is now the law under which the SEC regulates the capital market, including collective investment schemes. Option D is the repealed earlier Act. Options A and B are pension laws, which are administered by the National Pension Commission."}},{"itemId":"119c5b2d-6a08-581d-bf30-7cf7fef72616","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ea363fe2-0d74-5975-ac4f-c2730a4129cb","sourceKey":"bank:BUA216:PEN-048","parentItemId":null,"revision":1,"payload":{"prompt":"A sales charge deducted from an investor's money at the time units in a mutual fund are BOUGHT is called a:","options":["Performance fee","Back-end load","Front-end load","Management fee"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A front-end load is a sales charge taken when the investor buys, so less of the money is actually invested in units. Option B is charged when units are sold or redeemed. Options D and A are ongoing charges for managing the fund and for beating a target return, not a charge at purchase."}},{"itemId":"f08164fc-26c9-52b5-a6b5-a97010b48689","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c08f9b46-5e57-5c30-a3e6-25eccc88d187","sourceKey":"bank:BUA216:PEN-049","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund's total annual operating expenses expressed as a percentage of its average net assets is the:","options":["Front-end load","Net asset value","Expense ratio","Discount to NAV"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The expense ratio = annual operating expenses / average net assets, showing what share of the fund is used up each year in running costs. Option B is the fund's value per unit, option A is a one-off charge on purchase, and option D compares a closed-end fund's market price with its NAV."}},{"itemId":"a9095030-d27b-505f-93f3-81063d410904","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2283dbd5-9f0e-5ca9-abc5-8f460f79e29a","sourceKey":"bank:BUA216:PEN-050","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund has total assets of N520 million and total liabilities of N20 million. It has 40 million units outstanding. What is its net asset value (NAV) per unit?","options":["N0.08","N12.00","N12.50","N13.00"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"NAV per unit = (total assets - liabilities) / units = (520m - 20m) / 40m = N12.50. Option D ignores the liabilities (520 / 40), option B deducts the liabilities twice, and option A divides units by net assets, turning the formula upside down."}},{"itemId":"948ff72d-46a3-512a-8fca-200bf508f2bd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"23420a91-c757-59ca-85fe-81dcaf7f24c3","sourceKey":"bank:BUA216:PEN-051","parentItemId":null,"revision":1,"payload":{"prompt":"A unit trust holds securities with a market value of N85 million and cash of N5 million. It owes management fees of N2 million and has other liabilities of N3 million. There are 10 million units in issue. What is the NAV per unit?","options":["N8.50","N9.00","N8.00","N8.80"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Total assets = 85m + 5m = N90m; liabilities = 2m + 3m = N5m; NAV per unit = (90m - 5m) / 10m = N8.50. Option B ignores the liabilities, option C leaves out the cash, and option D deducts only the fees owed."}},{"itemId":"cf8c3cde-b390-5404-ad16-01240259dc8d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c49cb80b-2a93-51c9-80dc-53a5ef8880ef","sourceKey":"bank:BUA216:PEN-052","parentItemId":null,"revision":1,"payload":{"prompt":"Femi invests N1,000,000 in an open-end fund whose NAV is N20.00 per unit. The fund charges a front-end load of 5% of the amount invested, and the rest buys units at NAV. How many units does he receive?","options":["47,500 units","47,619 units","50,000 units","52,500 units"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Load = 5% x 1,000,000 = N50,000, so N950,000 buys units: 950,000 / 20 = 47,500 units. Option C ignores the load, option B treats the load as a percentage of the net amount (1,000,000 / 1.05 / 20), and option D adds the load instead of deducting it."}},{"itemId":"580a923d-fb75-5793-8eac-a1e94221cf78","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aff302d9-6102-5f89-9f75-19f58cf01b86","sourceKey":"bank:BUA216:PEN-053","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund's NAV is N19.00 per unit and it charges a front-end load of 5% of the offer (purchase) price, so that offer price = NAV / (1 - load). What is the offer price per unit?","options":["N20.00","N18.05","N19.95","N19.00"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Offer price = 19.00 / (1 - 0.05) = 19.00 / 0.95 = N20.00, and the 5% load (N1.00) is 5% of that offer price. Option C adds 5% of NAV instead, option B deducts the load from NAV, and option D ignores the load."}},{"itemId":"065d319a-f658-53a3-ab03-4a89a8b43d37","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1bc0efbf-d2d3-5272-84bf-6ec18c162eb3","sourceKey":"bank:BUA216:PEN-054","parentItemId":null,"revision":1,"payload":{"prompt":"Kemi redeems 10,000 units of an open-end fund at an NAV of N15.00 per unit. The fund charges a back-end load of 2% of the redemption value. How much does she receive?","options":["N3,000","N147,000","N153,000","N150,000"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Redemption value = 10,000 x 15.00 = N150,000; the 2% back-end load is N3,000, so she receives N147,000. Option D forgets the load, option C adds it instead of deducting it, and option A is just the load itself."}},{"itemId":"3d9844ed-606b-5d36-9763-c2883ef1cd95","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"326cc94b-cc39-5e98-a398-e711b5310bd8","sourceKey":"bank:BUA216:PEN-055","parentItemId":null,"revision":1,"payload":{"prompt":"An equity fund's NAV per unit rose from N10.00 at the start of the year to N10.80 at the end, and it paid income distributions of N0.40 per unit during the year. Taking return = (change in NAV + distributions) / opening NAV, what was the fund's return for the year?","options":["11.11%","12%","8%","4%"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Return = (10.80 - 10.00 + 0.40) / 10.00 = 1.20 / 10.00 = 12%. Option C ignores the distributions, and option D counts only the distributions. Option A divides by the closing NAV instead of the opening NAV."}},{"itemId":"f124bf0e-ee92-5fe2-9f1f-17d0a2951796","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f0b0390c-1320-5f33-872a-2f9d0b1fb4fc","sourceKey":"bank:BUA216:PEN-056","parentItemId":null,"revision":1,"payload":{"prompt":"A balanced fund's NAV per unit fell from N16.00 to N14.40 over the year, and it paid distributions of N0.32 per unit. Taking return = (change in NAV + distributions) / opening NAV, what was its return?","options":["+8%","-8.89%","-10%","-8%"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Return = (14.40 - 16.00 + 0.32) / 16.00 = -1.28 / 16.00 = -8%. Option C ignores the distributions, option A gets the sign wrong, and option B divides by the closing NAV of N14.40."}},{"itemId":"1829208d-d7a3-5082-b0ed-ff11581a969a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d288d02a-f238-537e-a7ed-d762ef76011a","sourceKey":"bank:BUA216:PEN-057","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund had total annual operating expenses of N36 million and average net assets of N2.4 billion. Taking expense ratio = annual expenses / average net assets, what is its expense ratio?","options":["0.15%","1.5%","15%","3.6%"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Expense ratio = 36m / 2,400m = 0.015 = 1.5%. Options C and A come from misplacing the decimal point (millions versus billions), and option D just quotes the expense figure as a percentage without dividing."}},{"itemId":"087688b3-6c89-5b1f-83d9-bf5ff9487828","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6beef5bf-c16f-5827-9e45-4f40729b526e","sourceKey":"bank:BUA216:PEN-058","parentItemId":null,"revision":1,"payload":{"prompt":"A fund earned a gross return of 14% on its investments for the year, and its expense ratio is 1.75%. Taking the investors' net return as gross return minus expense ratio, what was the net return?","options":["15.75%","12.25%","1.75%","13.76%"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Net return = 14% - 1.75% = 12.25%, since expenses are taken out of the fund before investors share the return. Option A adds the expenses instead of deducting them, option D multiplies 14% by (1 - 0.0175), which is not the stated method, and option C is only the expense ratio."}},{"itemId":"2a3f062e-a5e4-50be-95b2-a0674f4b7511","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3e168a8-1464-50db-9a1e-9867cb501161","sourceKey":"bank:BUA216:PEN-059","parentItemId":null,"revision":1,"payload":{"prompt":"A closed-end fund has a NAV of N25.00 per unit but its units are trading on the stock exchange at N22.50. Measuring the premium or discount as (market price - NAV) / NAV, the units are trading at:","options":["A 10% discount","An 11.11% premium","A 10% premium","An 11.11% discount"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"(22.50 - 25.00) / 25.00 = -0.10, so the units sell at a 10% discount to NAV. Option C gets the direction wrong, since a price below NAV is a discount. Options D and B divide by the market price instead of NAV."}},{"itemId":"281a343c-fcc9-5c0b-a2ba-db758b7dfd9c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fe0cb9c8-ad3b-5371-bcf6-41cd04ed1873","sourceKey":"bank:BUA216:PEN-060","parentItemId":null,"revision":1,"payload":{"prompt":"Shade owns 25,000 of the 2,000,000 units in issue of a mutual fund. The fund distributes income of N8,000,000 to unit holders in proportion to their holdings. How much does Shade receive?","options":["N1,000,000","N10,000","N320","N100,000"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Shade's share = (25,000 / 2,000,000) x 8,000,000 = 0.0125 x 8,000,000 = N100,000, because each unit holder shares proportionally in the fund's income. Options A and B come from misplacing the decimal point, and option C divides the income by her units instead of using her proportion."}},{"itemId":"1a4d5b8e-6d53-5967-abc3-0b6a4960a82c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"30060165-007a-51c1-bc56-e9ea8a691ce8","sourceKey":"bank:BUA216:PEN-061","parentItemId":null,"revision":1,"payload":{"prompt":"A balanced fund invests 60% of its assets in equities expected to return 20% and 40% in bonds expected to return 12%. What is the fund's expected return as a weighted average?","options":["15.2%","16.0%","16.8%","32.0%"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Expected return = (0.6 x 20%) + (0.4 x 12%) = 12% + 4.8% = 16.8%. Option B is a simple average that ignores the weights, option A swaps the weights, and option D adds the two returns together."}},{"itemId":"744264b6-151e-5d55-9995-ccdc7fb74f39","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1464f7b4-4741-51c6-a412-50fea71f53f4","sourceKey":"bank:BUA216:PEN-062","parentItemId":null,"revision":1,"payload":{"prompt":"A private, actively managed investment pool that uses high-risk, flexible strategies to generate high returns, is loosely regulated and is typically restricted to high net worth accredited investors and institutions, is a:","options":["Pension fund","Mutual fund","Money market fund","Hedge fund"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A hedge fund is a private, loosely regulated pool using high-risk, flexible strategies, open mainly to wealthy accredited investors and institutions. Option B is tightly regulated and open to the public, and option C is a low-risk type of mutual fund. Option A exists to provide retirement income for workers."}},{"itemId":"fb8fc3c2-ff59-5a0e-ae9f-e1510514ece6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c81cabd-9eb0-51af-8ea2-82f1ac99d580","sourceKey":"bank:BUA216:PEN-063","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"hedge\" in hedge fund comes from the practice of:","options":["Limiting membership to workers of one employer or union","Investing only in government treasury bills to avoid all risk","Offsetting potential losses in the core portfolio by taking inverse or protective positions","Guaranteeing investors a fixed return regardless of performance"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Hedging means protecting a position against loss by taking an opposite (inverse) or protective position, and hedge funds took their name from doing this. Option B describes a money market approach, option D is something hedge funds do not offer, and option A describes an occupational pension fund."}},{"itemId":"a4788c8c-8c1c-519e-aab2-45fb191cb3f3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9cadebef-57c0-5c14-b7a4-13ff83e969e6","sourceKey":"bank:BUA216:PEN-064","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly compares mutual funds and hedge funds?","options":["Mutual funds are tightly regulated and open to the public; hedge funds are loosely regulated and restricted","Both are loosely regulated and open to anyone with any amount of money","Both are tightly regulated and open only to institutional investors","Mutual funds are loosely regulated; hedge funds are tightly regulated and open to the public"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Mutual funds are tightly regulated and open to the general public, while hedge funds are loosely regulated and usually restricted to high net worth accredited investors and institutions. Option D reverses the two, and options C and B wrongly treat the two types of fund as the same."}},{"itemId":"72de0ea6-b013-5cfb-9f66-623f8ef1ba48","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b8752c5-241f-5196-ada2-e18a0368bd4a","sourceKey":"bank:BUA216:PEN-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of a hedge fund?","options":["It uses high-risk, flexible strategies","It is open to the general public and tightly regulated","It pools capital from multiple investors","It is overseen by a professional fund manager"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Being open to the general public and tightly regulated describes a mutual fund, not a hedge fund. Hedge funds do use high-risk, flexible strategies (A), are overseen by a professional fund manager (D) and pool capital from several investors (C)."}},{"itemId":"2146ec44-6824-5e39-8d00-b565b5d07046","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b9c39342-6d75-58a1-b17b-9e2a6a57b9f8","sourceKey":"bank:BUA216:PEN-066","parentItemId":null,"revision":1,"payload":{"prompt":"Dayo, a first-year student with N50,000 of savings, wants professional management and a share in a diversified portfolio. Which investment vehicle is open to him?","options":["A pension fund custodian","A hedge fund","A defined benefit plan","A mutual fund"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Mutual funds are open to the general public and let small investors own a fraction of a large, professionally managed portfolio. Option B is usually restricted to high net worth accredited investors and institutions. Option C is an employer pension promise, and option A is an institution that holds pension assets, not an investment he can buy."}},{"itemId":"fcc9a979-2e14-5f62-b0a5-823405a08e35","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cba46eda-6cd8-53d3-8528-ee4f3c288fd4","sourceKey":"bank:BUA216:PEN-067","parentItemId":null,"revision":1,"payload":{"prompt":"A hedge fund charges a management fee of 2% of assets under management plus a performance fee of 20% of the year's investment profit. Its assets under management are N1 billion and its profit for the year is N150 million. What are the total fees for the year?","options":["N30 million","N50 million","N46 million","N20 million"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Management fee = 2% x 1,000m = N20m; performance fee = 20% x 150m = N30m; total = N50m. Options D and A give only one of the two fees. Option C wrongly deducts the management fee from profit before taking the performance fee, which is not the stated method."}},{"itemId":"0e935098-1632-579f-827a-3bd2c99e4b8d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"610a464a-3033-5ec4-86e5-dd5eadacdef2","sourceKey":"bank:BUA216:PEN-068","parentItemId":null,"revision":1,"payload":{"prompt":"In the money management industry, the party that makes the investment decisions for a fund on behalf of its investors is the:","options":["Fund manager","Custodian","Trustee","Registrar"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The fund manager (asset manager) decides what to buy and sell for the fund on behalf of the unit holders. Option B keeps the fund's assets in safe custody, option C watches over the manager on behalf of investors under the trust deed, and option D keeps the register of unit holders."}},{"itemId":"640f9694-4bf9-5767-b3eb-ee679b7f9c36","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb0e8623-ed7f-574d-b192-4495ece10d50","sourceKey":"bank:BUA216:PEN-069","parentItemId":null,"revision":1,"payload":{"prompt":"In a unit trust, the party whose main role is to protect the unit holders by holding the trust on their behalf and ensuring the fund manager follows the trust deed is the:","options":["Fund manager","Pension fund administrator","Trustee","Stockbroker"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The trustee is party to the trust deed and acts for the unit holders, checking that the fund manager keeps to the deed's terms and investment objectives. Option A is the party being supervised, option D only executes trades on the exchange, and option B belongs to the pension system."}},{"itemId":"56c6628e-bec8-501a-bac2-ee6c91710b42","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"60ada4ae-ee4c-558d-ad56-424a75d9be05","sourceKey":"bank:BUA216:PEN-070","parentItemId":null,"revision":1,"payload":{"prompt":"Why are pension assets in Nigeria held by a pension fund custodian, separate from the pension fund administrator that invests them?","options":["To keep contributors' assets safe and apart from the administrator's own assets","To guarantee contributors a fixed pension regardless of returns","To allow the administrator to use the assets as its working capital","To let the custodian choose the investments instead of the administrator"],"correctOption":0,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"The Pension Reform Act 2014 requires pension funds and assets to be kept separate from the operating company's assets and held with a custodian, so contributors' money is protected if the administrator gets into trouble. Option C is exactly what the separation prevents. Option D is wrong because the custodian acts on the administrator's instructions, and option B confuses custody with a defined benefit promise."}},{"itemId":"d03089f8-99de-52a4-9138-9c3b76f40446","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3397c914-7869-5cfe-ba16-0586827445e9","sourceKey":"bank:BUA216:PEN-071","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of investing through a mutual fund?","options":["Diversification across many securities","A guaranteed return that can never fall below the amount invested","Professional management of the portfolio","Ownership of a fraction of a large portfolio with a small sum"],"correctOption":1,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A mutual fund shares its gains AND losses with investors, so returns are not guaranteed and the value of units can fall. Professional management (C), diversification (A) and the ability to own part of a large portfolio with little money (D) are genuine advantages of mutual funds."}},{"itemId":"f8d098db-88ab-5644-8462-f6bae5aadf37","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a681ba97-91bc-5eed-9853-c30a69e811bf","sourceKey":"bank:BUA216:PEN-072","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a risk that an investor in an equity mutual fund must accept?","options":["Units can never be sold or redeemed once bought","The fund cannot hold more than one company's shares","The fund manager may keep all the gains and pass on only losses","The value of units can fall when the shares in the portfolio fall"],"correctOption":3,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"Because investors share proportionally in the fund's losses as well as its gains, a fall in share prices reduces the value of their units; equity funds are high-risk for this reason. Option C is wrong because gains are shared proportionally too. Option A is false for both open-end and closed-end funds, and option B contradicts the diversified nature of a mutual fund."}},{"itemId":"fc103869-40b0-5789-aee9-34423d193995","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"039b7378-6d3b-5971-9ec1-e785427ce510","sourceKey":"bank:BUA216:PEN-073","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a type of mutual fund?","options":["Money market fund","Halal fund","Defined benefit fund","Fixed income fund"],"correctOption":2,"section":"Pension Funds, Mutual Funds and the Money Management Industry","explanation":"A defined benefit arrangement is a type of pension plan that promises a set payout, not a mutual fund. Money market funds (A), fixed income funds (D) and halal or sharia-compliant funds (B) are all types of mutual fund classified by risk, assets and objective."}},{"itemId":"8086352d-fc8e-5c96-bee6-1407fa259570","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0bf525d1-7b2f-5a50-925a-ab62b0f14771","sourceKey":"bank:BUA216:RAT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The relationship between financial data in the financial statements that aids or assists in the evaluation of the financial condition and performance of a company is called:","options":["Financial forecasting","Working capital management","Capital budgeting","Financial ratio analysis"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Financial ratio analysis relates one figure in the financial statements to another so that a company's financial condition and performance can be judged. Option C is about choosing long-term investment projects, and option B is about managing current assets and current liabilities, not about comparing statement figures in general. Option A looks forward to predict future figures rather than relating existing ones."}},{"itemId":"b470ab90-e1cf-5a3e-9052-65edbb72a9c1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"093ac461-a025-5cdb-b0bb-f4ed4c15cec2","sourceKey":"bank:BUA216:RAT-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes financial ratio analysis?","options":["Recording a company's transactions in its books of original entry","Auditing a company's accounts to confirm that they are free from fraud","Estimating the present value of a company's future cash flows","Relating figures in the financial statements to one another to evaluate a company's financial condition and performance"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Ratio analysis works with figures that are already in the financial statements and expresses them in relation to one another so that condition and performance can be evaluated. Option A is bookkeeping, option C is discounting or valuation, and option B is the work of an auditor."}},{"itemId":"9978f27e-8e48-553e-a873-c33bebaf4345","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"56cd2a38-5300-524c-87e4-5d8ac3765af0","sourceKey":"bank:BUA216:RAT-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of financial ratio analysis?","options":["It allows a company's results to be compared with the industry average","It identifies the causes of a company's problems","It gives full information from a single ratio taken by itself","It removes the problem of different definitions of terms"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"One strength of ratio analysis is that it allows comparison with similar companies and with the industry average. Options B, D and C are the opposite of the recognised weaknesses: ratios do not identify causes of problems, they suffer from problems of definition, and a ratio taken by itself provides little useful information."}},{"itemId":"3accc157-274b-58fb-941d-be354d0c359e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c30599fb-96a8-5db5-848d-3dde016d395a","sourceKey":"bank:BUA216:RAT-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of financial ratio analysis?","options":["It is very simple to calculate","Its analyses are useful in identifying problem areas of the company","It is very easy to understand","It identifies the causes of the company's problems"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Ratios can point to problem areas, but they do not explain why the problems exist, so identifying causes is a weakness, not a strength. Options C, A and B are all genuine advantages. Do not confuse identifying problem areas (option B, an advantage) with identifying causes."}},{"itemId":"1be5f4ba-457e-51ab-91bf-e53515fd7904","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d74bfd17-630a-52f7-a95c-eda20b95332a","sourceKey":"bank:BUA216:RAT-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of financial ratio analysis?","options":["It is very simple to calculate","It is useful in identifying problem areas","Problems of definition","It allows comparison between two similar companies"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Problems of definition arise because terms such as profit, debt or capital employed can be measured in different ways, so two analysts may produce different ratios from the same accounts. Options D, A and B are advantages of ratio analysis, not disadvantages."}},{"itemId":"8de70739-78d9-5d2d-8077-9252bfce8919","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"31459e3b-2af4-57d6-b139-9e81a36f6e2c","sourceKey":"bank:BUA216:RAT-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a disadvantage of financial ratio analysis?","options":["Ratios do not identify the causes of company problems","A ratio taken by itself provides little useful information","Ratios allow comparison with the industry average","Ratios can be easily misinterpreted"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Comparison with the industry average is one of the main benefits of ratio analysis. Options D, B and A are all recognised weaknesses: ratios are easily misread, mean little in isolation, and show symptoms rather than causes."}},{"itemId":"b58ddf64-f5e2-50f9-bbb1-f06ed3d9f32b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e42ec710-f744-5f09-b26b-e99f057a0cc3","sourceKey":"bank:BUA216:RAT-007","parentItemId":null,"revision":1,"payload":{"prompt":"An analyst finds that the return on capital employed of Ikeja Plastics Ltd fell from 18% to 11% in one year. The ratio alone does not tell her whether the fall came from higher costs, lower prices or idle machinery. This illustrates which limitation of ratio analysis?","options":["Ratios allow comparison with the industry average","Ratios are very simple to calculate","Problems of definition","Ratios do not identify the causes of company problems"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"The ratio signals that something is wrong but cannot explain the cause; the analyst must investigate further. Option C would apply if the difficulty were in how capital employed or profit is defined, which is not the issue here. Options B and A are advantages, not limitations."}},{"itemId":"aa943cc3-271a-53e4-85b6-273854956c3c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3dc64d2-9f52-5e3f-859d-a308894fe8c7","sourceKey":"bank:BUA216:RAT-008","parentItemId":null,"revision":1,"payload":{"prompt":"Two analysts compute the gearing ratio of the same Lagos company from the same accounts. One treats preference shares as fixed interest capital and the other treats them as equity, so they get different answers. This illustrates which limitation of ratio analysis?","options":["Ratios are very easy to understand","Ratios allow comparison between two similar companies","Problems of definition","A ratio taken by itself provides little useful information"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"When the same ratio can be defined in different ways, results differ and comparisons become unreliable; this is the problem of definition. Option D concerns a single ratio lacking a benchmark, which is not the issue here. Options A and B are advantages."}},{"itemId":"93c24815-acea-53c4-8459-7eb06d356061","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"698908f8-be91-5cdb-a6d7-c78a449ee490","sourceKey":"bank:BUA216:RAT-009","parentItemId":null,"revision":1,"payload":{"prompt":"A student is told only that Oshodi Traders Ltd has a current ratio of 1.6 : 1, with no previous years' figures and no industry average. Which limitation of ratio analysis does this situation best illustrate?","options":["Problems of definition","Ratios are very simple to calculate","Ratios do not identify the causes of company problems","A ratio taken by itself provides little useful information"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"A ratio becomes meaningful only when compared with something, such as earlier years, a similar company or the industry average. Option C concerns explaining why a problem exists, and option A concerns inconsistent measurement; neither is the issue when there is simply no benchmark. Option B is an advantage."}},{"itemId":"6dd44bc1-706a-5ace-80c6-c9449bb50ac8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"208809a5-35c5-5b43-abad-9fc9fb06a719","sourceKey":"bank:BUA216:RAT-010","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano fertiliser supplier is deciding whether to sell goods on 60 days' credit to a farm cooperative and examines the cooperative's current and acid test ratios. In this case the supplier is acting as which user of financial ratio analysis?","options":["Creditor","Competitor","Shareholder","Government"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"A supplier who grants credit becomes a creditor and uses liquidity ratios to judge whether it will be paid on time. Option B would be a rival firm benchmarking itself, option C is an owner of the business, and option D uses ratios mainly for regulation and tax purposes."}},{"itemId":"39354a89-8a42-56be-a54f-a9270bca9e8a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ba5a9a05-49e3-5d1b-aee1-fe87a49778e3","sourceKey":"bank:BUA216:RAT-011","parentItemId":null,"revision":1,"payload":{"prompt":"A paint manufacturer in Ota studies the published gross profit margins of a rival paint company to judge how its own pricing and costs compare. Which user of financial ratio analysis is the manufacturer in this situation?","options":["Competitor","Employee","Customer","Financial institution"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Rival firms use each other's ratios to benchmark performance, so the manufacturer is acting as a competitor. Option C would buy the rival's paint, option B works for a company, and option D would be a bank or similar lender."}},{"itemId":"2fa3f48f-0f51-5c76-aa9f-fb4f20c74965","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"783b32d8-9397-50af-bbfd-221da794f9e8","sourceKey":"bank:BUA216:RAT-012","parentItemId":null,"revision":1,"payload":{"prompt":"Financial ratios are classified into four groups. Which of the following is NOT one of those four groups?","options":["Short term solvency or liquidity ratio","Efficiency and profitability ratio","Cash budgeting and forecasting ratio","Long term solvency and stability ratio"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"The four groups are short term solvency (liquidity or working capital) ratios, efficiency and profitability ratios, long term solvency and stability ratios, and stock market or investor interest ratios. Options A, B and D are three of those groups; cash budgeting is a planning tool, not a ratio group."}},{"itemId":"0fdcbbee-0813-5774-91cd-73a3b6b75c26","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1baaffec-e1c5-55db-bb6f-4b9cb0b77448","sourceKey":"bank:BUA216:RAT-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which group of ratios measures the ability of a company to meet its long term obligations?","options":["Stock market or investor interest ratios","Efficiency and profitability ratios","Long term solvency and stability ratios","Short term solvency or working capital ratios"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Long term solvency and stability ratios, such as gearing, fixed interest cover and the debt ratio, look at whether a company can carry its long-term debt. Option D deals with current obligations, option B with performance in relative terms, and option A with information for investment decisions."}},{"itemId":"60d2cee8-5ea8-576d-8dae-78159a9ef338","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"76e3aad9-70ef-5cd3-b6f5-2fde9fcdc45a","sourceKey":"bank:BUA216:RAT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which group of ratios measures the performance of a company in relative terms?","options":["Stock market or investor interest ratios","Long term solvency and stability ratios","Short term solvency or liquidity ratios","Efficiency and profitability ratios"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Efficiency and profitability ratios, such as gross profit margin, ROTA and ROCE, express profit relative to sales, assets or capital, so they measure performance in relative terms. Option B focuses on long-term debt-paying ability and option C on meeting current obligations. Option A helps investors make investment decisions."}},{"itemId":"51ed0a47-9e4f-5c75-bcc2-253c59c4a2b3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a10636fa-18ed-51fd-9240-95b87068e7b2","sourceKey":"bank:BUA216:RAT-015","parentItemId":null,"revision":1,"payload":{"prompt":"Stock market or investor interest ratios such as dividend yield and the price/earnings ratio are mainly intended to:","options":["Measure how quickly debtors pay the company","Enable investors to make reasonable investment decisions","Show whether the company can pay its trade creditors this month","Show how much of the company's assets are financed by debt"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Investor interest ratios relate earnings and dividends to the number of shares and the share price, which helps investors decide whether to buy, hold or sell. Option C is the job of liquidity ratios, option D is the debt ratio, and option A is the average collection period."}},{"itemId":"de7a6d44-9aa0-53b9-b1c7-6b640c62d47c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15dd6f76-b40c-5ed8-a241-7ca5683c6720","sourceKey":"bank:BUA216:RAT-016","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following ratios belongs to the long term solvency and stability group?","options":["Fixed interest cover","Earnings yield","Acid test ratio","Gross profit margin"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Fixed interest cover shows how many times EBIT covers the annual interest on debt, which bears on the ability to meet long-term obligations. Option C is a short term liquidity ratio, option D is a profitability ratio, and option B is an investor interest ratio."}},{"itemId":"1898b835-47f5-5a1f-bf76-c5f47fdf51ee","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1c55fed9-1d99-5f0b-982f-54a942ded899","sourceKey":"bank:BUA216:RAT-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following ratios belongs to the stock market or investor interest group?","options":["Return on capital employed","Current ratio","Debt ratio","Earnings yield"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Earnings yield (EPS divided by market price per share) relates earnings to the share price and is an investor interest ratio. Option C is a long term solvency ratio, option A is a profitability ratio, and option B is a liquidity ratio."}},{"itemId":"69146c2a-51d7-51b4-86ed-37b1bb038474","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"63f158a3-792b-59e4-a2a7-34efd928e2a3","sourceKey":"bank:BUA216:RAT-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a short term solvency (liquidity or working capital) ratio?","options":["Gearing ratio","Average collection period","Acid test ratio","Current ratio"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The gearing ratio compares fixed interest capital with equity capital and belongs to the long term solvency and stability group. Options D, C and B all relate to current assets and current liabilities and are grouped as short term or working capital ratios."}},{"itemId":"ebb6bac5-9bac-5b0b-9e2e-213db7a7bde4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8b1135db-1688-561a-8959-b6657558815f","sourceKey":"bank:BUA216:RAT-019","parentItemId":null,"revision":1,"payload":{"prompt":"A ratio is calculated as cost of sales divided by average stock, where average stock is (opening stock + closing stock) / 2. What is this ratio called?","options":["Acid test ratio","Stock turnover","Gross profit margin","Average payment period"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Stock turnover shows how many times the average stock is used up and replaced through cost of sales during the period, and it is expressed in times. Option A removes stock from current assets, option C relates gross profit to sales, and option D relates trade creditors to credit purchases."}},{"itemId":"9b6cabb3-bc09-55bf-8754-5a8d8e144dc4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1c7d3eb4-8e8f-5004-8028-44b12af93999","sourceKey":"bank:BUA216:RAT-020","parentItemId":null,"revision":1,"payload":{"prompt":"The ratio (trade creditors / credit purchases) x 365 days measures:","options":["The average number of days customers take to pay the company","The number of times stock is replaced in a year","The proportion of total assets financed by debt","The average number of days a company takes to pay its suppliers"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"This is the average payment period: it converts trade creditors into days of credit purchases, showing how long the company takes to pay suppliers. Option A is the average collection period, which uses trade debtors and credit sales. Option B is stock turnover and option C is the debt ratio."}},{"itemId":"33090c55-d712-5555-a712-2bb0775778bf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0eea0955-3d38-59c5-a9a3-ec17b61904ae","sourceKey":"bank:BUA216:RAT-021","parentItemId":null,"revision":1,"payload":{"prompt":"The ratio (EBIT / capital employed) x 100 is known as:","options":["Fixed interest cover","Return on shareholders' equity","Return on capital employed","Net profit margin"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Return on capital employed divides earnings before interest and tax by capital employed and expresses the result as a percentage. Option B uses earnings after interest and tax over shareholders' equity, option D divides profit by sales, and option A divides EBIT by the annual interest charge."}},{"itemId":"51001480-3654-5645-a2f6-8dc38004a3f8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8c178d26-3cf3-553b-8b29-9a8648ae28d5","sourceKey":"bank:BUA216:RAT-022","parentItemId":null,"revision":1,"payload":{"prompt":"The ratio (shareholders' equity / total tangible assets) x 100 is called the:","options":["Return on shareholders' equity","Debt ratio","Proprietary ratio","Gearing ratio"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"The proprietary ratio shows what percentage of the tangible assets is financed by the owners' funds. Option B uses total debt over total assets, option D compares fixed interest capital with equity capital, and option A would put profit, not equity, in the numerator."}},{"itemId":"0e32e85c-d8fc-5a1a-adbb-8534521f695b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f3be7ef2-a011-5431-b30b-eef4443e8ee8","sourceKey":"bank:BUA216:RAT-023","parentItemId":null,"revision":1,"payload":{"prompt":"When computing the gearing ratio as fixed interest capital / equity capital, fixed interest capital is made up of:","options":["Debt capital plus preference share capital","Debt capital only","Current liabilities plus long term debt","Ordinary share capital plus share premium"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Fixed interest capital is all capital that carries a fixed return: debt capital and preference share capital. Option B leaves out preference shares, which also earn a fixed dividend. Option D is part of equity capital, and option C is the total debt used in the debt ratio."}},{"itemId":"46e78ff3-2a5b-5bd2-989d-d6a9eadb53d4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fbac377b-1692-5ab5-a96d-32c14ece1c89","sourceKey":"bank:BUA216:RAT-024","parentItemId":null,"revision":1,"payload":{"prompt":"When computing the gearing ratio as fixed interest capital / equity capital, which of the following is NOT part of equity capital?","options":["Revenue reserves","Preference share capital","Retained earnings","Share premium"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Preference share capital carries a fixed dividend, so it is counted as fixed interest capital, not equity. Equity capital is ordinary share capital plus share premium, revenue reserves and retained earnings, so options D, A and C all belong in it."}},{"itemId":"ac58bfe5-962e-5d11-b948-b585494da6a3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1d0a38bf-289c-5254-b878-14d5b1f11355","sourceKey":"bank:BUA216:RAT-025","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the gearing ratio as fixed interest capital / equity capital, Badagry Haulage Ltd has a gearing ratio of 1.5 : 1. What does this indicate?","options":["Current assets are one and a half times current liabilities, so liquidity is adequate","Equity capital is one and a half times fixed interest capital, so the company is lowly geared","Fixed interest capital is one and a half times equity capital, so the company is highly geared and carries high financial risk","Profit before interest covers interest one and a half times, so interest is very safe"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"A gearing ratio above 1 : 1 on this definition means the company is financed more by fixed interest capital than by equity, which raises the fixed charges it must meet and therefore its financial risk. Option B reverses the ratio. Option A describes a current ratio and option D describes interest cover."}},{"itemId":"50091ad6-4e57-5d0a-8aad-7641a991564e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4e638c02-711f-5265-9a37-5175d67216e6","sourceKey":"bank:BUA216:RAT-026","parentItemId":null,"revision":1,"payload":{"prompt":"In the debt ratio, (total debt / total assets) x 100, total debt is taken as:","options":["Current liabilities only","Long term debt plus preference share capital","Current liabilities plus long term debt","Long term debt only"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"For the debt ratio, total debt includes both current liabilities and long term debt. Option D ignores short-term obligations, option B is fixed interest capital as used in gearing, and option A leaves out long-term borrowing."}},{"itemId":"c6698cde-834e-5439-8f21-f18463abc30a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e5a21970-32cd-5385-b3b9-30078434acd3","sourceKey":"bank:BUA216:RAT-027","parentItemId":null,"revision":1,"payload":{"prompt":"Fixed interest cover, calculated as earnings before interest and tax divided by the annual fixed interest charged on debt, measures:","options":["The proportion of profit paid out as dividends","How many times current assets cover current liabilities","The percentage of total assets financed by debt","How many times profit before interest and tax can pay the year's interest charge"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Fixed interest cover tells lenders how comfortably operating profit covers interest; the higher the figure, the safer the interest payments. Option A describes dividend payout, option B the current ratio, and option C the debt ratio."}},{"itemId":"f08e3522-ced4-5fed-9312-31bb751477c4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"38f14dda-2307-54e7-b9a4-b6baebf2de4d","sourceKey":"bank:BUA216:RAT-028","parentItemId":null,"revision":1,"payload":{"prompt":"Apapa Shipping Ltd has fixed interest cover of 1.2 times, while the industry average is 6 times. The most reasonable comment is that:","options":["A modest fall in profit could leave the company unable to meet its interest payments","The company is too liquid and is holding idle cash","The company has more than enough profit to pay its interest","The company's shares must be underpriced on the stock exchange"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Cover of only 1.2 times means EBIT is barely above the interest charge, so a small drop in profit could make interest unpayable; lenders would see this as risky, especially against an industry average of 6 times. Option C is the opposite conclusion. Options B and D cannot be drawn from an interest cover figure."}},{"itemId":"c90b0b0c-3923-502e-a6ad-cf3827c6e6de","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"061e234d-a20a-5262-905f-8203665e6662","sourceKey":"bank:BUA216:RAT-029","parentItemId":null,"revision":1,"payload":{"prompt":"Shares of Ibadan Brewers Plc have a price/earnings ratio of 15. This means that:","options":["The company earns a 15% return on capital employed","The company pays N15 of dividend for every N1 of share price","Each share earns N15 for every N1 invested","Investors are paying N15 for every N1 of earnings per share"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"The P/E ratio is market price per share divided by earnings per share, so a P/E of 15 means the market price is 15 times the EPS. Option B confuses earnings with dividends, option A mixes in a profitability ratio, and option C turns the ratio upside down."}},{"itemId":"9002be5c-05c6-516b-ace2-776fc41dff0a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6359be5a-9eb4-5d9b-b4d9-d73e87f2be37","sourceKey":"bank:BUA216:RAT-030","parentItemId":null,"revision":1,"payload":{"prompt":"How is the earnings yield related to the price/earnings (P/E) ratio?","options":["Earnings yield and the P/E ratio are unrelated","Earnings yield is the reciprocal of the P/E ratio","Earnings yield equals the P/E ratio minus the dividend yield","Earnings yield equals the P/E ratio multiplied by the dividend per share"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Earnings yield is EPS / market price per share, while P/E is market price per share / EPS, so one is simply the other turned upside down (often shown as a percentage). Options D and C invent relationships with dividends, and option A ignores that both use the same two figures."}},{"itemId":"bbb48cd2-fb9a-599e-bcba-554bcf0f92a9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0ed5ea61-67e9-50c5-9d05-ae15446d688f","sourceKey":"bank:BUA216:RAT-031","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between dividend yield and earnings yield?","options":["Dividend yield is a liquidity ratio, while earnings yield is a profitability ratio","Dividend yield uses EBIT, while earnings yield uses gross profit","Dividend yield uses dividend per share in the numerator, while earnings yield uses earnings per share","Dividend yield uses market price per share, while earnings yield uses book value per share"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Both ratios divide by market price per share; dividend yield puts DPS on top, earnings yield puts EPS on top. Option D is wrong because both use market price. Option A is wrong because both are investor interest ratios, and option B uses the wrong profit figures."}},{"itemId":"dac2be81-d8ec-5dac-9f59-b56621c3fd01","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c9d9560d-d37e-5bd0-9e8d-bc64f5a68f24","sourceKey":"bank:BUA216:RAT-032","parentItemId":null,"revision":1,"payload":{"prompt":"The average collection period of Aba Shoes Ltd rose from 30 days last year to 62 days this year, while its credit terms remained 30 days. This most likely indicates that:","options":["The company has reduced its long-term borrowing","The company is paying its suppliers more quickly","Customers are taking longer to pay and credit control has weakened","Stock is being sold faster than before"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"The average collection period measures how long debtors take to pay, so a rise to 62 days against 30-day terms shows slower collection and weaker credit control. Option B concerns the average payment period, option D concerns stock turnover, and option A is a gearing matter."}},{"itemId":"a7116426-8522-5774-8dfa-e3714487c58d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"52d47368-fc85-5e4d-8d83-777a4f314fc3","sourceKey":"bank:BUA216:RAT-033","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, Onitsha Spare Parts Ltd's stock turnover fell from 9 times to 4 times while its range of goods was unchanged. The most reasonable interpretation is that:","options":["The company's gross profit margin must have doubled","Stock is being sold and replaced more quickly than before","Stock is moving more slowly, which may point to overstocking or slow-selling items","Debtors are paying the company faster"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"A lower stock turnover means stock is replaced fewer times a year, so goods stay on the shelves longer, which suggests overstocking or slow-moving lines. Option B describes a rise in turnover. Option A does not follow from stock turnover, and option D is about the collection period."}},{"itemId":"edb02834-0a4d-5461-afc7-36bfc6c6181f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7f0c3c71-12b8-5d77-8423-7b6fdde4d839","sourceKey":"bank:BUA216:RAT-034","parentItemId":null,"revision":1,"payload":{"prompt":"The gross profit margin of Mushin Bakery fell from 30% to 22% although sales revenue stayed the same. Which explanation is consistent with this fall?","options":["Administrative expenses rose","Cost of sales rose relative to sales","Corporate tax rose","Interest on loans rose"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Gross profit margin is (sales - cost of sales) / sales x 100, so with sales unchanged, a fall can only come from higher cost of sales, for example dearer flour. Options A, D and C are charged below gross profit, so they affect net profit but not the gross profit margin."}},{"itemId":"a3111f50-174c-58f6-8ce0-536ed6ee971f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5b40aa39-7e59-5c79-ace5-3ef64ebbece4","sourceKey":"bank:BUA216:RAT-035","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between the current ratio and the acid test (quick) ratio?","options":["The acid test ratio uses long term liabilities instead of current liabilities","The acid test ratio excludes stock from current assets, while the current ratio includes it","The acid test ratio includes fixed assets, while the current ratio does not","The acid test ratio excludes cash from current assets, while the current ratio includes it"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Both ratios divide by current liabilities; the acid test simply deducts stock from current assets first. Option D removes the wrong item, since cash is the most liquid asset. Options A and C bring long-term items into a short-term ratio."}},{"itemId":"ac3880cb-8701-559b-9e30-bee4f1075781","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dd0767e7-3708-51fe-a29a-09f33c0dc9bf","sourceKey":"bank:BUA216:RAT-036","parentItemId":null,"revision":1,"payload":{"prompt":"Why is stock deducted from current assets when calculating the acid test ratio?","options":["Stock is usually the least liquid current asset, since it must first be sold before it becomes cash","Stock is a fixed asset and should never be in current assets","Stock is already counted in current liabilities","Stock is always valued at zero in the balance sheet"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"The acid test is a stricter test of liquidity, so it leaves out stock, which may take time to sell and may fetch less than its book value. Option B is wrong because stock is a current asset. Options D and C are simply false statements about stock."}},{"itemId":"cdba0553-62ba-545b-809b-4a98bc2aa8fc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"276d2983-5f62-5318-b696-1fa242022b33","sourceKey":"bank:BUA216:RAT-037","parentItemId":null,"revision":1,"payload":{"prompt":"Ilorin Agro Ltd has a current ratio of 1.1 : 1, while the conventional ideal is 2 : 1. Which comment is most appropriate?","options":["The company is highly geared with long-term debt","The company holds too much idle working capital","Current assets barely cover current liabilities, so the company may struggle to meet short-term obligations","The company's shares are overvalued"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"A current ratio of 1.1 : 1 is well below the 2 : 1 ideal, so there is little cushion of current assets over current liabilities. Option B would apply to a very high current ratio. Option A needs the gearing ratio and option D needs market ratios."}},{"itemId":"0f338ba2-e1ec-56e0-99af-4b3514b18a05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3d106964-e6f6-5f2f-9a6d-7ede715b9589","sourceKey":"bank:BUA216:RAT-038","parentItemId":null,"revision":1,"payload":{"prompt":"Surulere Pharmacy Ltd has a current ratio of 6 : 1, against an industry average of 2 : 1. A sensible interpretation is that:","options":["Liquidity is more than adequate, but funds may be tied up unproductively in current assets","The company has very little stock or cash","The company has borrowed heavily on long-term loans","The company is likely to default on payments to its suppliers"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"A very high current ratio means short-term debts are easily covered, but it may also mean too much idle cash, excess stock or slow debtors that earn little return. Options D and B suggest poor liquidity, the opposite of what the ratio shows. Option C cannot be concluded from the current ratio."}},{"itemId":"df6da46c-3cc0-5e9d-94a3-14088bc93183","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5bcae453-0a1a-59de-bbdb-a65af379ec96","sourceKey":"bank:BUA216:RAT-039","parentItemId":null,"revision":1,"payload":{"prompt":"Return on capital employed uses EBIT in the numerator mainly because:","options":["EBIT is always equal to gross profit","EBIT excludes all operating expenses","Capital employed is provided by both lenders and shareholders, so the profit used should be before interest is paid to lenders","EBIT is the profit left for ordinary shareholders after all charges"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Capital employed includes long-term debt as well as equity, so the matching return is profit before interest and tax, which is available to all providers of capital. Option D describes earnings after interest and tax, used in ROSE. Option A is false since operating expenses come between gross profit and EBIT, and option B is the reverse of the truth."}},{"itemId":"2ab661a9-8c52-5522-8f18-3d2d396208b0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cf302ef2-80b3-52e8-be21-dbf6772afe92","sourceKey":"bank:BUA216:RAT-040","parentItemId":null,"revision":1,"payload":{"prompt":"Return on shareholders' equity (ROSE), also called return on equity, uses earnings after interest and tax (EAIT) rather than EBIT because:","options":["EAIT measures cash held at the bank","EAIT is always higher than EBIT","EAIT includes the interest paid to debenture holders","EAIT is the profit that belongs to shareholders after lenders and tax have been paid"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Shareholders are entitled only to what is left after interest and tax, so their return should be measured with EAIT over shareholders' equity. Option C is wrong because interest has already been deducted. Option B is wrong because EAIT is lower than EBIT whenever there is interest or tax, and option A confuses profit with cash."}},{"itemId":"8cd0b2e7-6ec3-5f5f-9eb6-5a005d8f81e3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c31f1baa-c103-52f4-962b-0d0883881f14","sourceKey":"bank:BUA216:RAT-041","parentItemId":null,"revision":1,"payload":{"prompt":"How does return on total assets (ROTA), also called return on assets, differ from return on capital employed (ROCE)?","options":["ROTA uses gross profit while ROCE uses EAIT","Both use EBIT, but ROTA divides by total assets while ROCE divides by capital employed (total assets less current liabilities)","ROTA is a liquidity ratio while ROCE is an investor interest ratio","ROTA divides by shareholders' equity while ROCE divides by sales"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"ROTA = (EBIT / total assets) x 100 and ROCE = (EBIT / capital employed) x 100, so only the denominator differs; because capital employed is smaller than total assets, ROCE is normally the higher figure. Options A and D use the wrong figures, and option C misclassifies two profitability ratios."}},{"itemId":"0b626471-6960-5fdd-ab7b-62775fbf47b4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d2b4de0-6bc0-5b56-b03d-686342bb46d7","sourceKey":"bank:BUA216:RAT-042","parentItemId":null,"revision":1,"payload":{"prompt":"First Bank is considering a five-year loan to Ogun Cement Ltd. Which group of ratios would the bank's credit officer focus on most?","options":["Efficiency ratios such as gross profit margin only","Short term ratios only, because loans are always repaid within a year","Stock market ratios such as dividend yield","Long term solvency and stability ratios such as gearing and fixed interest cover"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"A long-term lender wants to know whether the company can carry more debt and keep paying interest, which is what gearing, the debt ratio and fixed interest cover show. Option C matters to equity investors. Option A is too narrow, and option B is wrong because a five-year loan is a long-term obligation."}},{"itemId":"b10bd0f7-dfc6-5e59-8d2a-0336d5730b5d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cc941b80-1e85-516b-9f22-d6441b2233a7","sourceKey":"bank:BUA216:RAT-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following ratios is correctly matched with the unit in which it is normally expressed?","options":["Current ratio - naira","Average collection period - days","Stock turnover - percentage","Gearing ratio - days"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"The average collection period multiplies by 365 days, so its answer is in days. Stock turnover is expressed in times, so option C is wrong. Gearing (option D) and the current ratio (option A) are expressed as x : 1."}},{"itemId":"9077d7ec-c88c-527c-9223-a4482858c327","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"30304567-2490-560d-8740-cd803934923c","sourceKey":"bank:BUA216:RAT-044","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the cash ratio as (cash + marketable securities) / current liabilities, why is it regarded as a stricter test of liquidity than the acid test ratio?","options":["It includes fixed assets as well as current assets","It uses long term debt instead of current liabilities","It adds stock back into the numerator","It leaves out debtors as well as stock and counts only the most liquid assets"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"The cash ratio counts only cash and near-cash items, so unlike the acid test it also excludes debtors, who may not pay on time. Options A and B bring long-term items into a short-term ratio, and option C would make it less strict, not more."}},{"itemId":"b6db0b42-b4d9-5dd6-9ad3-286546737479","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d245d741-aca6-5524-aaaa-6fabf1e143eb","sourceKey":"bank:BUA216:RAT-045","parentItemId":null,"revision":1,"payload":{"prompt":"What does the abbreviation EAIT stand for in ratios such as EPS and return on shareholders' equity?","options":["Earnings after interest and tax","Earnings after inventory and tax","Earnings available for investment and trade","Expenses after interest and tax"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"EAIT means earnings after interest and tax, the profit left for shareholders, and it is the numerator in both EPS and ROSE. The other options are made-up expansions that do not correspond to any figure in the income statement."}},{"itemId":"7b6c5ef4-9e52-51c2-bc32-2144cab8c4e5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2fad29b7-38f9-513f-93cf-ef5c3c480f3e","sourceKey":"bank:BUA216:RAT-046","parentItemId":null,"revision":1,"payload":{"prompt":"Dividend per share (DPS) is calculated as:","options":["Gross dividend / market price per share","Gross dividend / number of shares issued and fully paid","Market price per share / gross dividend","Earnings after interest and tax / number of shares issued and fully paid"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"DPS spreads the total (gross) dividend over the number of shares issued and fully paid. Option D is EPS, option A mixes total dividend with a per-share price, and option C is upside down."}},{"itemId":"53fa8487-a7fb-50db-96f5-12ee455b335b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c663dced-c13f-58e1-b676-0fa94cdd5470","sourceKey":"bank:BUA216:RAT-047","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund manager wants to compare the cash return from dividends that she would earn on N1 invested in the shares of two listed Nigerian banks at current market prices. Which ratio is most suitable?","options":["Average payment period","Dividend yield","Gearing ratio","Gross profit margin"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Dividend yield divides dividend per share by market price per share, so it shows the dividend return on money invested at today's price. Option C measures financial risk, option A measures how quickly a firm pays suppliers, and option D measures trading profitability."}},{"itemId":"589406a1-0b8c-5ef0-891d-23f71d5ec409","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8de04865-43c2-56a7-9a82-b810db013ad4","sourceKey":"bank:BUA216:RAT-048","parentItemId":null,"revision":1,"payload":{"prompt":"Ekiti Stores Ltd has the following balances: stock N18,000, debtors N13,500, cash N4,500, prepayments N1,000, trade creditors N9,000, accrued expenses N3,000 and bank overdraft N4,000. Calculate the current ratio (to 2 decimal places).","options":["2.31 : 1","0.43 : 1","3.08 : 1","1.19 : 1"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Current ratio = current assets / current liabilities = (18,000 + 13,500 + 4,500 + 1,000) / (9,000 + 3,000 + 4,000) = 37,000 / 16,000 = 2.31 : 1. Option C leaves the bank overdraft out of current liabilities, although an overdraft is repayable on demand. Option D is the acid test ratio, and option B turns the ratio upside down."}},{"itemId":"6a077140-9c92-5243-a2ff-d71d3a4f92b8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d4e09a3e-dbc8-5343-b009-8082b9c28e9d","sourceKey":"bank:BUA216:RAT-049","parentItemId":null,"revision":1,"payload":{"prompt":"Ekiti Stores Ltd has the following balances: stock N18,000, debtors N13,500, cash N4,500, prepayments N1,000, trade creditors N9,000, accrued expenses N3,000 and bank overdraft N4,000. Calculate the acid test (quick) ratio (to 2 decimal places).","options":["1.19 : 1","2.31 : 1","1.12 : 1","1.58 : 1"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Acid test = (current assets - stock) / current liabilities = (37,000 - 18,000) / 16,000 = 19,000 / 16,000 = 1.19 : 1. Option B is the current ratio, which forgets to remove stock. Option D leaves the bank overdraft out of current liabilities, and option C divides stock by current liabilities instead of removing it."}},{"itemId":"81ce8f8f-2e5f-5474-8ed3-0f6679de0833","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0e913d76-c01b-5b2b-9eeb-dcc04f82015a","sourceKey":"bank:BUA216:RAT-050","parentItemId":null,"revision":1,"payload":{"prompt":"Yaba Electronics Ltd has working capital (current assets minus current liabilities) of N45,000 and current liabilities of N30,000. What is its current ratio?","options":["1.50 : 1","0.40 : 1","2.50 : 1","0.67 : 1"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Current assets = working capital + current liabilities = 45,000 + 30,000 = 75,000, so current ratio = 75,000 / 30,000 = 2.50 : 1. Option A divides working capital by current liabilities, forgetting that working capital is already net of current liabilities. Option B inverts the correct ratio, and option D divides current liabilities by working capital."}},{"itemId":"b183bd78-7190-5932-b7f3-0aa870e9c2f3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9cf7c552-0192-513c-93a6-940d67ccd84f","sourceKey":"bank:BUA216:RAT-051","parentItemId":null,"revision":1,"payload":{"prompt":"Asaba Textiles Ltd has a current ratio of 2.4 : 1, current liabilities of N35,000 and stock of N28,000. Calculate its acid test ratio.","options":["1.60 : 1","0.80 : 1","0.67 : 1","2.40 : 1"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Current assets = 2.4 x 35,000 = 84,000. Acid test = (84,000 - 28,000) / 35,000 = 56,000 / 35,000 = 1.60 : 1. Option D is simply the current ratio, which forgets to remove stock. Option B divides stock by current liabilities, and option C divides current assets less stock by current assets instead of by current liabilities."}},{"itemId":"b69b6cb8-b16e-5563-8c65-43d0f4fb320c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d497ef55-f840-5702-b194-26d33a436037","sourceKey":"bank:BUA216:RAT-052","parentItemId":null,"revision":1,"payload":{"prompt":"Calabar Foods Ltd has a current ratio of 2.5 : 1 and an acid test ratio of 1.5 : 1. Its current liabilities are N40,000. What is the value of its stock?","options":["N60,000","N100,000","N160,000","N40,000"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Current assets = 2.5 x 40,000 = 100,000 and quick assets = 1.5 x 40,000 = 60,000. Stock is the difference: 100,000 - 60,000 = N40,000. Option A is the quick assets figure, option B is total current assets, and option C adds the two asset figures instead of subtracting them."}},{"itemId":"6d1f1439-15b0-5572-856b-c333a5be2d4c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d78e69de-bdac-50e4-95ad-f01ff11f2770","sourceKey":"bank:BUA216:RAT-053","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the cash ratio as (cash + marketable securities) / current liabilities, Jos Tin Traders Ltd has cash of N12,000, marketable securities of N6,000, debtors of N20,000, stock of N25,000 and current liabilities of N45,000. Calculate the cash ratio.","options":["0.40 : 1","0.84 : 1","1.40 : 1","0.27 : 1"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Cash ratio = (12,000 + 6,000) / 45,000 = 18,000 / 45,000 = 0.40 : 1. Option B also includes debtors, which gives the acid test ratio instead. Option C includes all current assets (the current ratio), and option D uses cash alone and leaves out the marketable securities."}},{"itemId":"0e1ab528-9bd6-5fcf-84f2-0d6a1fc8288c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"732092a8-7676-51ab-8d3b-4725fd41553a","sourceKey":"bank:BUA216:RAT-054","parentItemId":null,"revision":1,"payload":{"prompt":"Wuse Supermarket Ltd has current assets of N60,000 and current liabilities of N30,000. It then pays N10,000 cash to its trade creditors. What is its current ratio immediately after the payment?","options":["3.00 : 1","2.00 : 1","2.50 : 1","1.67 : 1"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Paying creditors reduces both current assets and current liabilities by 10,000, so the new current ratio = 50,000 / 20,000 = 2.50 : 1. Option B is the old ratio, which assumes no change. Option D reduces only current assets (50,000 / 30,000), and option A reduces only current liabilities (60,000 / 20,000)."}},{"itemId":"7aad57d9-4ee9-5594-9939-9a9c89a9eff0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"19334f0c-e892-54e7-ba25-71aaba5af91d","sourceKey":"bank:BUA216:RAT-055","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, where average stock = (opening stock + closing stock) / 2, calculate the stock turnover of Lekki Fashion House given opening stock of N18,000, closing stock of N30,000 and cost of sales of N168,000.","options":["9.33 times","5.60 times","7.00 times","3.50 times"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Average stock = (18,000 + 30,000) / 2 = 24,000, so stock turnover = 168,000 / 24,000 = 7.00 times. Option B uses closing stock only (168,000 / 30,000), which is the most common mistake. Option A uses opening stock only, and option D divides by the sum of the two stocks without halving it."}},{"itemId":"8bc52d3e-ba38-5c96-b94e-edb7d098da4c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d10a34cb-920f-50c5-9ea5-5b105ddd0d4c","sourceKey":"bank:BUA216:RAT-056","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, where average stock = (opening stock + closing stock) / 2, find the stock turnover of Agege Provisions Ltd. Sales were N250,000, gross profit was N70,000, opening stock was N22,000 and closing stock was N18,000.","options":["9.00 times","10.00 times","12.50 times","3.50 times"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Cost of sales = sales - gross profit = 250,000 - 70,000 = 180,000. Average stock = (22,000 + 18,000) / 2 = 20,000, so stock turnover = 180,000 / 20,000 = 9.00 times. Option C wrongly uses sales instead of cost of sales, option B uses closing stock only, and option D uses gross profit in the numerator."}},{"itemId":"eb8f303d-1048-523b-bf65-42aefdb49398","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f40164f6-cecc-5aed-bc00-7d3cea436b1b","sourceKey":"bank:BUA216:RAT-057","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, where average stock = (opening stock + closing stock) / 2, calculate the stock turnover of Enugu Hardware Ltd. Opening stock was N15,000, purchases were N120,000 and closing stock was N25,000.","options":["4.40 times","5.50 times","6.00 times","8.00 times"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Cost of sales = opening stock + purchases - closing stock = 15,000 + 120,000 - 25,000 = 110,000. Average stock = (15,000 + 25,000) / 2 = 20,000, so turnover = 110,000 / 20,000 = 5.50 times. Option C uses purchases instead of cost of sales, option A divides by closing stock, and option D adds closing stock instead of subtracting it."}},{"itemId":"0f808a46-663f-5b4e-aec0-3eb615f6186a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"19cf72ba-352c-5cb0-b29b-3baaa0a562e0","sourceKey":"bank:BUA216:RAT-058","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, Owerri Paints Ltd has a stock turnover of 6 times. Its opening stock was N20,000 and closing stock N30,000. What was its cost of sales?","options":["N120,000","N300,000","N150,000","N180,000"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Average stock = (20,000 + 30,000) / 2 = 25,000, and cost of sales = stock turnover x average stock = 6 x 25,000 = N150,000. Option D multiplies by closing stock, option A by opening stock, and option B by the sum of the two stocks without halving."}},{"itemId":"b6cccdc3-162c-5755-8e96-6fb141a3fdf7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cbe9a3b3-1036-50f7-ae01-9910498a272a","sourceKey":"bank:BUA216:RAT-059","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, where average stock = (opening stock + closing stock) / 2, Benin Furniture Ltd achieved a stock turnover of 8 times on cost of sales of N200,000. Its opening stock was N22,000. What was its closing stock?","options":["N3,000","N28,000","N50,000","N25,000"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Average stock = 200,000 / 8 = 25,000, so opening + closing = 50,000 and closing stock = 50,000 - 22,000 = N28,000. Option D is the average stock itself, option A subtracts opening stock from the average instead of from twice the average, and option C is the sum of the two stocks."}},{"itemId":"07f28d96-ee54-5e5d-a670-4d12b9a4d188","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"680fc33f-8868-5691-b5f7-425540c48a45","sourceKey":"bank:BUA216:RAT-060","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock holding period as (average stock / cost of sales) x 365 days, with average stock = (opening stock + closing stock) / 2, how many days on average does Kaduna Grains Ltd hold stock? Opening stock was N40,000, closing stock N50,000 and cost of sales N547,500. (Answer to the nearest day.)","options":["60 days","30 days","27 days","33 days"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Average stock = (40,000 + 50,000) / 2 = 45,000, so holding period = 45,000 / 547,500 x 365 = 30 days. Option D uses closing stock only, option C uses opening stock only, and option A adds the two stocks without halving them."}},{"itemId":"f5ee6ce4-c1e9-5d18-9e4e-d1571b2cd744","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b2734317-9932-5061-a41d-00e82f7593c6","sourceKey":"bank:BUA216:RAT-061","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Ikorodu Cables Ltd made total sales of N730,000, of which N657,000 were on credit, and had trade debtors of N54,000 at the year end. Calculate its average collection period.","options":["30 days","12 days","270 days","27 days"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Average collection period = (trade debtors / credit sales) x 365 = (54,000 / 657,000) x 365 = 30 days. Option D uses total sales, but only credit sales create debtors. Option B turns the ratio upside down, which gives debtors turnover in times rather than days, and option C divides by cash sales (N73,000)."}},{"itemId":"35c73f1f-cbb9-5514-8fd4-cf8d773dac44","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ec5e3810-e0e0-54d2-aec7-6bbb22f977b5","sourceKey":"bank:BUA216:RAT-062","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Sango Ota Plastics Ltd had total sales of N900,000, of which N180,000 were cash sales. Trade debtors at the year end were N96,000. Calculate the average collection period to the nearest day.","options":["8 days","49 days","39 days","195 days"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Credit sales = 900,000 - 180,000 = 720,000, so average collection period = (96,000 / 720,000) x 365 = 48.67, about 49 days. Option C wrongly uses total sales (96,000 / 900,000 x 365 = 39 days); only credit sales create debtors. Option D uses cash sales, and option A inverts the ratio and gives debtors turnover in times, not days."}},{"itemId":"9db9fe89-20ae-57ad-8e97-0e92ee39a690","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8cdee9e8-d68b-547e-9f5e-7f86bd579c9a","sourceKey":"bank:BUA216:RAT-063","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Ajah Builders Ltd made total purchases of N365,000, of which N292,000 were on credit, and owed trade creditors N36,000 at the year end. Calculate its average payment period.","options":["8 days","36 days","45 days","180 days"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Average payment period = (trade creditors / credit purchases) x 365 = (36,000 / 292,000) x 365 = 45 days. Option B uses total purchases, but only credit purchases create trade creditors. Option D divides by cash purchases (N73,000), and option A inverts the ratio and gives creditor turnover in times rather than days."}},{"itemId":"5d18f85f-dc8d-5d7c-8abc-37c808f66485","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"97756645-0a58-5291-b377-223f3b3a017f","sourceKey":"bank:BUA216:RAT-064","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Ondo Cocoa Processors Ltd made total purchases of N500,000, of which 20% were for cash and the rest on credit. Trade creditors at the year end were N50,000. Calculate the average payment period to the nearest day.","options":["46 days","37 days","183 days","8 days"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Credit purchases = 80% x 500,000 = 400,000, so average payment period = (50,000 / 400,000) x 365 = 45.6, about 46 days. Option B wrongly uses total purchases (50,000 / 500,000 x 365 = 37 days). Option C uses cash purchases, and option D inverts the ratio and gives creditor turnover in times, not days."}},{"itemId":"21a9ed6e-aa0a-5b52-a5cc-b973b5db7b18","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"625fd557-84a0-5a1e-b203-d90cd636f837","sourceKey":"bank:BUA216:RAT-065","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Abeokuta Adire Ltd makes credit sales of N1,460,000 a year and its average collection period is 40 days. What is the value of its trade debtors?","options":["N120,000","N36,500","N162,222","N160,000"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Rearranging the formula, trade debtors = credit sales x collection period / 365 = 1,460,000 x 40 / 365 = N160,000. Option C uses a 360-day year, option B divides credit sales by 40 instead of using days over 365, and option A uses 30 days instead of 40."}},{"itemId":"c932163c-5acd-5f04-bba9-e99f4d9b2980","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b75dff58-6f05-5061-8e26-e7acf93c98e2","sourceKey":"bank:BUA216:RAT-066","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, Port Harcourt Marine Ltd had opening stock of N20,000, closing stock of N90,000 and cost of sales of N220,000; all purchases were on credit. Trade creditors at the year end were N30,000. Calculate the average payment period to the nearest day.","options":["50 days","38 days","73 days","10 days"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Credit purchases = cost of sales + closing stock - opening stock = 220,000 + 90,000 - 20,000 = 290,000. Average payment period = (30,000 / 290,000) x 365 = 37.8, about 38 days. Option A uses cost of sales instead of purchases, option C subtracts closing stock and adds opening stock the wrong way round (purchases of 150,000), and option D inverts the ratio."}},{"itemId":"f4bffdb3-79ab-52d1-8309-1a388350c8af","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"751247bf-886d-5a62-b31e-e8ebc8116923","sourceKey":"bank:BUA216:RAT-067","parentItemId":null,"revision":1,"payload":{"prompt":"Taking asset turnover as sales / total assets, Ojota Logistics Ltd had sales of N600,000 and total assets of N240,000. Calculate its asset turnover.","options":["1.25 times","2.50 times","5.00 times","0.40 times"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Asset turnover = 600,000 / 240,000 = 2.50 times, meaning each N1 of assets generated N2.50 of sales. Option D inverts the ratio. Option C divides by half the assets, and option A divides by twice the assets."}},{"itemId":"0f65eb91-ee52-5f2b-83e2-5c9456dd5925","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"be882a42-9019-5bd4-a8be-22f35e13bf15","sourceKey":"bank:BUA216:RAT-068","parentItemId":null,"revision":1,"payload":{"prompt":"Ilupeju Cosmetics Ltd had sales of N320,000 and cost of sales of N248,000. Calculate its gross profit margin (to 2 decimal places).","options":["2.25%","77.50%","29.03%","22.50%"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Gross profit = 320,000 - 248,000 = 72,000, so gross profit margin = (72,000 / 320,000) x 100 = 22.50%. Option B is cost of sales as a percentage of sales. Option C divides gross profit by cost of sales (a mark-up, not a margin), and option A misplaces the decimal point."}},{"itemId":"2be0f917-1f56-5e4d-994f-87011b58da05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"158d1d34-e4ba-5d3d-b41f-898508a90519","sourceKey":"bank:BUA216:RAT-069","parentItemId":null,"revision":1,"payload":{"prompt":"Oyo Garri Processors had sales of N450,000. Opening stock was N35,000, purchases were N300,000 and closing stock was N47,000. Calculate the gross profit margin (to 2 decimal places).","options":["33.33%","56.25%","36.00%","15.11%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Cost of sales = 35,000 + 300,000 - 47,000 = 288,000. Gross profit = 450,000 - 288,000 = 162,000, so gross profit margin = 162,000 / 450,000 x 100 = 36.00%. Option A uses purchases as cost of sales, option D adds closing stock instead of subtracting it, and option B divides gross profit by cost of sales."}},{"itemId":"76bb3f66-3727-5ee7-95c1-c2666f27a7b1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"04586768-230e-5b6a-a742-105628ee22a2","sourceKey":"bank:BUA216:RAT-070","parentItemId":null,"revision":1,"payload":{"prompt":"Taking net profit margin as (EBIT / sales) x 100, calculate the net profit margin of Festac Printers Ltd, which had sales of N480,000, EBIT of N72,000, interest of N12,000 and tax of N18,000.","options":["15.00%","6.67%","12.50%","8.75%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Net profit margin = (72,000 / 480,000) x 100 = 15.00%, because the stem defines it on EBIT. Option C deducts interest first (60,000), option D deducts both interest and tax (42,000), and option B divides sales by EBIT."}},{"itemId":"81ee9250-3858-5680-8d1e-28ab130afc1e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d4365b56-6e67-58fa-92cf-a8fa8ebfe452","sourceKey":"bank:BUA216:RAT-071","parentItemId":null,"revision":1,"payload":{"prompt":"Taking net profit margin as (net profit after interest and tax / sales) x 100, calculate the net profit margin of Maryland Bakery Ltd. Sales were N800,000, EBIT N120,000, interest N20,000 and tax at 30% of profit before tax.","options":["12.50%","15.00%","8.00%","8.75%"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Profit before tax = 120,000 - 20,000 = 100,000; tax = 30,000; net profit after tax = 70,000. Net profit margin = 70,000 / 800,000 x 100 = 8.75%. Option B uses EBIT, option A uses profit before tax, and option C takes tax on EBIT instead of on profit before tax."}},{"itemId":"90146e88-e59d-5653-b3c0-1ddd35452140","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d79d96a-b1e5-5ffa-836b-12c13e71be7a","sourceKey":"bank:BUA216:RAT-072","parentItemId":null,"revision":1,"payload":{"prompt":"Taking return on total assets (ROTA), also called return on assets, as (EBIT / total assets) x 100, calculate ROTA for Gbagada Motors Ltd. EBIT was N54,000, interest N9,000, tax N13,500 and total assets N450,000.","options":["12.00%","8.33%","7.00%","10.00%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"ROTA = (54,000 / 450,000) x 100 = 12.00%. Option D uses profit after interest (45,000), option C uses profit after interest and tax (31,500), and option B inverts the ratio."}},{"itemId":"d76f5610-23d3-5d4a-a4d1-69093d7888d2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ba165c69-c785-5dbe-910a-bb63abdb08a7","sourceKey":"bank:BUA216:RAT-073","parentItemId":null,"revision":1,"payload":{"prompt":"Taking return on capital employed as (EBIT / capital employed) x 100, where capital employed = total assets - current liabilities, find ROCE for Mile 12 Distributors Ltd. EBIT was N63,000, total assets N520,000 and current liabilities N100,000.","options":["15.00%","12.12%","63.00%","10.16%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Capital employed = 520,000 - 100,000 = 420,000, so ROCE = 63,000 / 420,000 x 100 = 15.00%. Option B uses total assets instead of capital employed (this is ROTA). Option D adds current liabilities instead of deducting them, and option C divides by current liabilities."}},{"itemId":"7d1b156c-0bea-5562-863f-2b16ccf82745","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"94388b50-1109-5c83-81e3-4dbe17a5f8f8","sourceKey":"bank:BUA216:RAT-074","parentItemId":null,"revision":1,"payload":{"prompt":"Taking ROCE as (EBIT / capital employed) x 100, where capital employed is shareholders' equity plus long-term debt, find the ROCE of Lokoja Steel Ltd. EBIT was N81,000, interest on the debt was N15,000, shareholders' equity N300,000 and long-term debt N150,000.","options":["27.00%","14.67%","18.00%","54.00%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Capital employed = 300,000 + 150,000 = 450,000, so ROCE = 81,000 / 450,000 x 100 = 18.00%. Option A divides by equity only, option D divides by long-term debt only, and option B deducts interest from EBIT first (66,000 / 450,000), although ROCE uses profit before interest."}},{"itemId":"eff6e312-0d6b-578a-ad45-3e549da7b1e7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b51ede25-03dc-5d06-90a2-b8fc9f7e2d38","sourceKey":"bank:BUA216:RAT-075","parentItemId":null,"revision":1,"payload":{"prompt":"Taking return on shareholders' equity (ROSE), also called return on equity, as (EAIT / shareholders' equity) x 100, calculate ROSE for Ikoyi Consulting Ltd. EAIT was N45,000 and shareholders' equity N250,000.","options":["5.56%","1.80%","9.00%","18.00%"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"ROSE = (45,000 / 250,000) x 100 = 18.00%. Option A divides equity by EAIT, option C divides EAIT by twice the equity, and option B misplaces the decimal point."}},{"itemId":"e91aaa5a-f953-5e1d-a4d9-1880f5ba86c4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"27628959-ff01-5f7c-9fea-10a5951e5781","sourceKey":"bank:BUA216:RAT-076","parentItemId":null,"revision":1,"payload":{"prompt":"Taking return on shareholders' equity (ROSE) as (EAIT / shareholders' equity) x 100, find ROSE for Kubwa Water Ltd. EBIT was N120,000, interest N20,000, tax was 30% of profit before tax, and shareholders' equity was N350,000.","options":["28.57%","20.00%","18.29%","34.29%"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Profit before tax = 120,000 - 20,000 = 100,000; tax = 30,000; EAIT = 70,000. ROSE = 70,000 / 350,000 x 100 = 20.00%. Option D uses EBIT, option A uses profit before tax, and option C applies tax to EBIT before deducting interest."}},{"itemId":"041a4db2-2a3a-55ff-a2e9-c6bf4e3a3c05","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"96ca1287-cf68-5e40-8f89-d4224b628aa3","sourceKey":"bank:BUA216:RAT-077","parentItemId":null,"revision":1,"payload":{"prompt":"Taking ROTA as (EBIT / total assets) x 100, find ROTA for Ojuelegba Auto Parts Ltd. Sales were N700,000, cost of sales N420,000, operating expenses N140,000, interest N20,000 and total assets N560,000.","options":["50.00%","125.00%","21.43%","25.00%"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"EBIT = sales - cost of sales - operating expenses = 700,000 - 420,000 - 140,000 = 140,000, so ROTA = 140,000 / 560,000 x 100 = 25.00%. Option A uses gross profit (280,000), option C deducts interest as well (120,000), and option B divides sales by total assets and expresses it as a percentage."}},{"itemId":"d4e16d3a-7ac6-540c-a005-eb571498df15","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a8de3515-82df-51fd-9f66-990415729eab","sourceKey":"bank:BUA216:RAT-078","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the gearing ratio as fixed interest capital / equity capital, where fixed interest capital = debt capital + preference share capital, calculate the gearing of Nnewi Motors Ltd. Debentures were N200,000, preference share capital N50,000, ordinary share capital N300,000, share premium N40,000 and retained earnings N160,000.","options":["0.40 : 1","0.50 : 1","0.36 : 1","0.33 : 1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Fixed interest capital = 200,000 + 50,000 = 250,000; equity capital = 300,000 + 40,000 + 160,000 = 500,000. Gearing = 250,000 / 500,000 = 0.50 : 1. Option A leaves out the preference shares, option D uses fixed interest capital over total capital, and option C counts preference shares as equity."}},{"itemId":"6f5bd841-a451-57df-ad01-734b016ccf55","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"903a997a-39e0-5bff-aa2b-d869fc486da7","sourceKey":"bank:BUA216:RAT-079","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the gearing ratio as fixed interest capital / equity capital, where fixed interest capital = debt capital + preference share capital, find the gearing of Gombe Cotton Ltd. Long-term loans were N450,000, preference share capital N150,000, ordinary share capital N250,000, revenue reserves N70,000 and retained earnings N80,000.","options":["1.50 : 1","1.12 : 1","0.60 : 1","0.67 : 1"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Fixed interest capital = 450,000 + 150,000 = 600,000; equity = 250,000 + 70,000 + 80,000 = 400,000. Gearing = 600,000 / 400,000 = 1.50 : 1, so the company is highly geared. Option B ignores preference shares, option C uses fixed interest capital over total capital, and option D inverts the ratio."}},{"itemId":"21b31c60-6047-554f-bcbd-ea89b358eb91","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"36da5abd-afbf-5231-9fe3-a3edf3f4f1e8","sourceKey":"bank:BUA216:RAT-080","parentItemId":null,"revision":1,"payload":{"prompt":"Taking gearing as fixed interest capital / equity capital, where fixed interest capital = debt capital + preference share capital, which of these companies is the most highly geared? Company P: debt N100,000, preference N20,000, equity N300,000. Company Q: debt N80,000, preference N70,000, equity N250,000. Company R: debt N150,000, preference nil, equity N400,000. Company S: debt N60,000, preference N30,000, equity N360,000.","options":["Company S","Company R","Company P","Company Q"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Gearing ratios are P = 120,000 / 300,000 = 0.40, Q = 150,000 / 250,000 = 0.60, R = 150,000 / 400,000 = 0.375 and S = 90,000 / 360,000 = 0.25, so Q is the most highly geared. Option B looks highest only if preference shares are ignored and debt alone is compared, and options C and A are lower on either basis."}},{"itemId":"1f990d8b-6f31-5c6a-9b9c-fb5f1db64c73","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7601d4ea-5815-57db-ab42-0ef901bf73a0","sourceKey":"bank:BUA216:RAT-081","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the gearing ratio as fixed interest capital / equity capital, where fixed interest capital = debt capital + preference share capital, Kwara Rice Mills Ltd has equity capital of N800,000 and preference share capital of N100,000. How much debt capital would give it a gearing ratio of exactly 0.6 : 1?","options":["N540,000","N480,000","N380,000","N580,000"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Required fixed interest capital = 0.6 x 800,000 = 480,000. Debt = 480,000 - 100,000 = N380,000, since preference shares already count as fixed interest capital. Option B forgets to subtract the preference shares, option D adds them instead of subtracting, and option A uses 0.6 x (800,000 + 100,000)."}},{"itemId":"7a661eb6-5729-59a9-b3f7-1a549b01be2e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ddf15487-900a-51ef-be97-7d33559d9add","sourceKey":"bank:BUA216:RAT-082","parentItemId":null,"revision":1,"payload":{"prompt":"Taking fixed interest cover as EBIT / annual fixed interest charged on debt, Ilesa Bottling Ltd earned EBIT of N96,000 and has N300,000 of 10% debentures. Calculate its fixed interest cover.","options":["2.20 times","3.20 times","0.31 times","0.32 times"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Annual interest = 10% x 300,000 = 30,000, so fixed interest cover = 96,000 / 30,000 = 3.20 times. Option A uses profit after interest (66,000 / 30,000), option D divides EBIT by the face value of the debentures, and option C inverts the ratio."}},{"itemId":"e7ac5d96-5828-56fa-8e96-617d0103d9d0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a6580289-df09-5988-839e-f1c207a7a891","sourceKey":"bank:BUA216:RAT-083","parentItemId":null,"revision":1,"payload":{"prompt":"Taking fixed interest cover as EBIT / annual fixed interest charged on debt, Akure Timber Ltd reported profit before tax of N75,000 after charging interest of N25,000. Calculate its fixed interest cover.","options":["4.00 times","0.25 times","2.00 times","3.00 times"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"EBIT = profit before tax + interest = 75,000 + 25,000 = 100,000, so cover = 100,000 / 25,000 = 4.00 times. Option D uses profit before tax without adding back interest (75,000 / 25,000), option C subtracts interest twice, and option B inverts the ratio."}},{"itemId":"9d278c06-70f5-5d62-8abd-5c62efffb143","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bfeeb5df-d9c6-5641-9ad5-f8fd3288cc4e","sourceKey":"bank:BUA216:RAT-084","parentItemId":null,"revision":1,"payload":{"prompt":"Taking fixed interest cover as EBIT / annual fixed interest charged on debt, Ijebu Ode Foods Ltd has EBIT of N150,000. It has a N400,000 bank loan at 12% and N200,000 of 15% debentures. Calculate its fixed interest cover.","options":["1.92 times","2.08 times","5.00 times","3.12 times"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Annual interest = 12% x 400,000 + 15% x 200,000 = 48,000 + 30,000 = 78,000, so cover = 150,000 / 78,000 = 1.92 times. Option D counts only the bank loan interest, option C counts only the debenture interest, and option B applies the 12% rate to the whole N600,000 of debt (72,000)."}},{"itemId":"58644538-73d2-531f-94b9-65cbf6ab97bb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9016b8d8-f5c4-597c-aa23-be00e79b9c81","sourceKey":"bank:BUA216:RAT-085","parentItemId":null,"revision":1,"payload":{"prompt":"Taking fixed interest cover as EBIT / annual fixed interest charged on debt, Sokoto Leather Ltd has fixed interest cover of 5 times and annual interest of N18,000. What is its EBIT?","options":["N72,000","N108,000","N90,000","N3,600"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"EBIT = cover x interest = 5 x 18,000 = N90,000. Option A is profit after interest (90,000 - 18,000), option D divides interest by 5, and option B adds interest back again to EBIT."}},{"itemId":"9eecbb1e-690d-58ed-b566-2355a5fc31b8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3bd07e22-77da-56de-8538-3160178bf5a6","sourceKey":"bank:BUA216:RAT-086","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the debt ratio as (total debt / total assets) x 100, where total debt = current liabilities + long term debt, calculate the debt ratio of Ikeja Pharma Ltd. Current liabilities were N40,000, long term debt N80,000 and total assets N400,000.","options":["42.86%","20.00%","30.00%","10.00%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Total debt = 40,000 + 80,000 = 120,000, so debt ratio = 120,000 / 400,000 x 100 = 30.00%. Option B uses long term debt only, option D uses current liabilities only, and option A divides total debt by total assets less total debt (that is, by equity)."}},{"itemId":"a0da208a-e78f-527c-9a1b-3a22e3c9f9fb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d5cd0078-c2b5-5e0d-9e0e-2860c9f41980","sourceKey":"bank:BUA216:RAT-087","parentItemId":null,"revision":1,"payload":{"prompt":"Bida Agro Ltd's balance sheet shows: fixed assets N350,000, current assets N150,000, ordinary share capital N200,000, retained earnings N100,000, long term loan N120,000 and current liabilities N80,000. Taking the debt ratio as (total debt / total assets) x 100, where total debt = current liabilities + long term debt, find the debt ratio.","options":["66.67%","24.00%","57.14%","40.00%"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Total assets = 350,000 + 150,000 = 500,000 and total debt = 80,000 + 120,000 = 200,000, so debt ratio = 200,000 / 500,000 x 100 = 40.00%. Option B uses only the long term loan, option C divides total debt by fixed assets, and option A compares total debt with shareholders' equity."}},{"itemId":"90bb4b6e-983f-50b0-a284-fd000787fbcc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4a10e216-3dbf-5757-ae3f-0f598169f760","sourceKey":"bank:BUA216:RAT-088","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the proprietary ratio as (shareholders' equity / total tangible assets) x 100, find the proprietary ratio of Victoria Island Media Ltd. Shareholders' equity was N360,000 and total assets were N500,000, including goodwill (an intangible asset) of N50,000.","options":["65.45%","72.00%","80.00%","125.00%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Total tangible assets = 500,000 - 50,000 = 450,000, so proprietary ratio = 360,000 / 450,000 x 100 = 80.00%. Option B uses total assets without removing goodwill, option A adds goodwill to assets a second time, and option D inverts the ratio."}},{"itemId":"0033f523-55a1-580e-afd9-3a993f2ae0d5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"24011334-bea6-5974-94e4-eb54f834a488","sourceKey":"bank:BUA216:RAT-089","parentItemId":null,"revision":1,"payload":{"prompt":"Zaria Grains Plc declared a gross dividend of N180,000 and has 1,200,000 shares issued and fully paid. What is its dividend per share?","options":["N6.67","N0.15","N0.30","N1.50"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"DPS = gross dividend / number of shares issued and fully paid = 180,000 / 1,200,000 = N0.15, or 15 kobo. Option D misplaces the decimal point, option C divides by half the shares, and option A inverts the ratio."}},{"itemId":"87367405-3234-5286-8a15-393eb58888f9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"429b01c8-c8f1-5fca-af16-cb90b64ac28d","sourceKey":"bank:BUA216:RAT-090","parentItemId":null,"revision":1,"payload":{"prompt":"Owo Oil Mills Plc has issued and fully paid ordinary share capital of N2,000,000 made up of 50 kobo shares. It declares a gross dividend of N600,000. What is its dividend per share in kobo?","options":["60 kobo","7.5 kobo","30 kobo","15 kobo"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Number of shares = 2,000,000 / 0.50 = 4,000,000, so DPS = 600,000 / 4,000,000 = N0.15, or 15 kobo. Option C wrongly treats the N2,000,000 share capital as 2,000,000 shares, option A divides by 1,000,000 shares, and option B divides by 8,000,000 shares, as if each share were 25 kobo."}},{"itemId":"dfa04ec5-2064-5ced-8243-d639ab87136b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aa3c6616-96da-5300-b465-a36b06ea8363","sourceKey":"bank:BUA216:RAT-091","parentItemId":null,"revision":1,"payload":{"prompt":"Taking earnings per share as earnings after interest and tax / number of shares issued and fully paid (with no deduction for preference dividend), find the EPS of Yola Livestock Plc. EAIT was N450,000 and there are 3,000,000 shares issued and fully paid.","options":["N1.50","N0.15","N0.23","N6.67"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"EPS = 450,000 / 3,000,000 = N0.15 per share. Option A misplaces the decimal point, option C divides by 2,000,000 shares, and option D inverts the ratio."}},{"itemId":"cc63c74e-a178-5dd5-98aa-bd24bccab90e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"33eeb601-9999-5e38-b94a-e1c2bdffda82","sourceKey":"bank:BUA216:RAT-092","parentItemId":null,"revision":1,"payload":{"prompt":"Taking earnings per share as earnings after interest and tax / number of shares issued and fully paid, find the EPS of Minna Granite Plc. EBIT was N900,000, interest N100,000, tax was 30% of profit before tax, and 2,000,000 shares are issued and fully paid.","options":["N0.40","N0.56","N0.45","N0.28"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Profit before tax = 900,000 - 100,000 = 800,000; tax = 240,000; EAIT = 560,000. EPS = 560,000 / 2,000,000 = N0.28. Option C uses EBIT, option A uses profit before tax, and option B divides EAIT by only 1,000,000 shares."}},{"itemId":"a348c9b1-f0e2-5633-9c02-c35641ecd80c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9e57ca8a-a07f-52a6-a3fc-80b5e441c7e5","sourceKey":"bank:BUA216:RAT-093","parentItemId":null,"revision":1,"payload":{"prompt":"Taking earnings per share as earnings after interest and tax / number of shares issued and fully paid, with NO deduction of preference dividend, find the EPS of Makurdi Feeds Plc. EAIT was N720,000, preference dividend paid was N120,000, and 2,400,000 ordinary shares are issued and fully paid.","options":["N0.05","N0.30","N0.35","N0.25"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"On the stated definition, EPS = 720,000 / 2,400,000 = N0.30, with no deduction for preference dividend. Option D deducts the preference dividend (600,000 / 2,400,000), which is a different convention from the one stated. Option A divides the preference dividend by the shares, and option C adds the preference dividend to earnings."}},{"itemId":"4ed9917f-e59e-5d70-82b9-d19a0da27111","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9cb740fd-d41d-5c88-b4d4-2806745822e7","sourceKey":"bank:BUA216:RAT-094","parentItemId":null,"revision":1,"payload":{"prompt":"Lafia Beverages Plc pays a dividend per share of N0.90 and its shares trade at N12.00. Taking dividend yield as (DPS / market price per share) x 100, calculate the dividend yield.","options":["7.50%","0.75%","13.33%","10.00%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Dividend yield = (0.90 / 12.00) x 100 = 7.50%. Option C inverts the ratio and gives a figure that looks like a P/E. Option B misplaces the decimal point, and option D divides by N9 as if the price were reduced by the dividend."}},{"itemId":"cef58473-481d-5685-a56b-de1bd8918456","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6669da73-628e-5892-8daf-1784cc3f2bba","sourceKey":"bank:BUA216:RAT-095","parentItemId":null,"revision":1,"payload":{"prompt":"Uyo Telecom Plc declared a gross dividend of N1,500,000 on 5,000,000 shares issued and fully paid. Its market price per share is N6.00. Taking dividend yield as (DPS / market price per share) x 100, calculate the dividend yield.","options":["5.00%","30.00%","20.00%","10.00%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"DPS = 1,500,000 / 5,000,000 = N0.30, so dividend yield = 0.30 / 6.00 x 100 = 5.00%. Option B divides total dividend by total market value of 5,000,000 shares at N1 (a wrong price), option C inverts DPS and price, and option D uses DPS of N0.60 by dividing by 2,500,000 shares."}},{"itemId":"9af9bdfb-7c09-591d-ba9a-9be989db7215","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"008e413a-2e0a-5b04-8b21-c8d666ff546e","sourceKey":"bank:BUA216:RAT-096","parentItemId":null,"revision":1,"payload":{"prompt":"Taking earnings yield as (EPS / market price per share) x 100, find the earnings yield of Okene Cement Plc, whose EPS is N1.50 and whose shares trade at N12.00.","options":["12.50%","1.25%","8.00%","15.00%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Earnings yield = (1.50 / 12.00) x 100 = 12.50%. Option C is the P/E ratio (12 / 1.5 = 8) wrongly labelled as a percentage. Option B misplaces the decimal point, and option D divides EPS by N10 instead of the market price."}},{"itemId":"d9ca1009-6efd-531d-9104-bbbaa564e8b5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"11aa5145-861c-5ad3-9d59-1650b1cf870c","sourceKey":"bank:BUA216:RAT-097","parentItemId":null,"revision":1,"payload":{"prompt":"Bauchi Dairy Plc's shares trade at N18.00 and its earnings per share is N1.20. Calculate its price/earnings ratio.","options":["21.60 times","15.00 times","16.80 times","0.07 times"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"P/E ratio = market price per share / EPS = 18.00 / 1.20 = 15.00 times. Option D inverts the ratio and gives the earnings yield as a decimal. Option C subtracts instead of dividing, and option A multiplies the two figures."}},{"itemId":"d1345d9b-c5d0-514f-addd-e64e9ee324ac","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3c8cd85-0bc8-5998-9f65-1ca375bf7878","sourceKey":"bank:BUA216:RAT-098","parentItemId":null,"revision":1,"payload":{"prompt":"Taking EPS as earnings after interest and tax / number of shares issued and fully paid, find the price/earnings ratio of Awka Pharmaceuticals Plc. EAIT was N2,400,000, there are 8,000,000 shares issued and fully paid, and the market price per share is N4.50.","options":["15.00 times","0.07 times","7.50 times","1.35 times"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"EPS = 2,400,000 / 8,000,000 = N0.30, so P/E = 4.50 / 0.30 = 15.00 times. Option B inverts the ratio, option C divides the price by EPS computed on 4,000,000 shares, and option D multiplies price by EPS instead of dividing."}},{"itemId":"c7033c31-d1f0-55fb-b02a-8e6918e3b346","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0faee8b9-c62e-5976-84f1-c9096ef6d01e","sourceKey":"bank:BUA216:RAT-099","parentItemId":null,"revision":1,"payload":{"prompt":"Shares of Damaturu Foods Plc trade on a price/earnings ratio of 12, and its earnings per share is N0.85. What is the market price per share?","options":["N14.12","N0.07","N12.85","N10.20"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Market price = P/E x EPS = 12 x 0.85 = N10.20. Option B divides EPS by the P/E, option A divides the P/E by the EPS, and option C adds the two figures."}},{"itemId":"e02674e6-3c6c-5656-ac38-0e49ade8519e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3bb9dea1-50cc-5102-b340-01ed5893cd29","sourceKey":"bank:BUA216:RAT-100","parentItemId":null,"revision":1,"payload":{"prompt":"A share has a price/earnings ratio of 8. Taking earnings yield as (EPS / market price per share) x 100, what is its earnings yield?","options":["10.00%","8.00%","12.50%","1.25%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Earnings yield is the reciprocal of the P/E: (1 / 8) x 100 = 12.50%. Option B simply writes the P/E as a percentage. Option D misplaces the decimal point, and option A uses 1 / 10 instead of 1 / 8."}},{"itemId":"f465aa62-68d0-5992-ac85-62af4c697ee7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"52409a3f-41f2-5282-b3cb-3058f5d7ef01","sourceKey":"bank:BUA216:RAT-101","parentItemId":null,"revision":1,"payload":{"prompt":"Taking dividend cover as EPS / DPS, find the dividend cover of Keffi Oil Plc, whose EPS is N1.20 and whose dividend per share is N0.40.","options":["0.33 times","1.60 times","0.80 times","3.00 times"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Dividend cover = 1.20 / 0.40 = 3.00 times, so earnings could pay the dividend three times over. Option A inverts the ratio and shows the payout ratio as a decimal. Option C subtracts instead of dividing, and option B adds the two figures."}},{"itemId":"c1501b83-8d44-5b9e-b591-0e452d9a7625","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6a676cfb-f86c-52d3-8cd3-8b8107252abc","sourceKey":"bank:BUA216:RAT-102","parentItemId":null,"revision":1,"payload":{"prompt":"Taking dividend cover as earnings after interest and tax / total dividend, Ogbomoso Farms Plc reported EBIT of N1,000,000, interest of N200,000, tax at 30% of profit before tax, and paid a total dividend of N280,000. Calculate its dividend cover.","options":["2.86 times","3.57 times","0.50 times","2.00 times"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Profit before tax = 1,000,000 - 200,000 = 800,000; tax = 240,000; EAIT = 560,000. Dividend cover = 560,000 / 280,000 = 2.00 times. Option B uses EBIT, option A uses profit before tax, and option C inverts the ratio."}},{"itemId":"5482bfdf-f049-547d-abe9-5c4fffeaff0c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"05317251-7236-53d7-aee9-8468d8aaed66","sourceKey":"bank:BUA216:RAT-103","parentItemId":null,"revision":1,"payload":{"prompt":"Taking dividend yield as (DPS / market price per share) x 100, Nsukka Books Plc pays a dividend per share of N0.60 and its dividend yield is 5%. What is its market price per share?","options":["N3.00","N0.12","N0.03","N12.00"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Market price = DPS / dividend yield = 0.60 / 0.05 = N12.00. Option A multiplies DPS by 5, option B divides 0.60 by 5 rather than by 0.05, and option C multiplies by 0.05."}},{"itemId":"c9cc505a-e07a-5d11-9c09-26af7ceeb3e6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"44cbe15c-866b-5939-afa9-11b00741c335","sourceKey":"bank:BUA216:RAT-104","parentItemId":null,"revision":1,"payload":{"prompt":"Taking EPS as earnings after interest and tax / number of shares issued and fully paid, find the earnings yield, (EPS / market price per share) x 100, of Ikot Ekpene Crafts Plc. EAIT was N900,000, there are 6,000,000 shares issued and fully paid and the market price per share is N2.50.","options":["16.67%","6.00%","0.60%","12.00%"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"EPS = 900,000 / 6,000,000 = N0.15, so earnings yield = 0.15 / 2.50 x 100 = 6.00%. Option A is the P/E ratio (2.50 / 0.15) treated as a percentage. Option D divides EAIT by the market value of only 3,000,000 shares, and option C misplaces the decimal point."}},{"itemId":"5b740dc0-1d1c-51c0-b655-52c3f707a247","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fe37681b-180f-5134-af01-56535b8f4fba","sourceKey":"bank:BUA216:RAT-105","parentItemId":null,"revision":1,"payload":{"prompt":"Taking current ratio as current assets / current liabilities, Ado Ekiti Traders Ltd has current assets of N150,000 and a current ratio of 2.5 : 1. What are its current liabilities?","options":["N75,000","N60,000","N100,000","N375,000"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Current liabilities = current assets / current ratio = 150,000 / 2.5 = N60,000. Option D multiplies instead of dividing, option C divides by 1.5, mixing up the current ratio with working capital, and option A divides by 2 (the ideal ratio) instead of the actual ratio."}},{"itemId":"31bd7d7f-c63e-5eb2-8dda-e8c938931fd8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6f9a54d-bb4f-5197-b2f4-ca5414902c79","sourceKey":"bank:BUA216:RAT-106","parentItemId":null,"revision":1,"payload":{"prompt":"Taking ROCE as (EBIT / capital employed) x 100, which company earns the highest return on capital employed? Company W: EBIT N60,000, capital employed N400,000. Company X: EBIT N90,000, capital employed N750,000. Company Y: EBIT N45,000, capital employed N250,000. Company Z: EBIT N120,000, capital employed N1,000,000.","options":["Company Y","Company X","Company Z","Company W"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"ROCE: W = 15%, X = 12%, Y = 18% and Z = 12%, so Y earns the highest return. Option C has the largest EBIT, but ratio analysis compares profit relative to capital, not absolute profit."}},{"itemId":"c10825c8-11f4-52a4-859e-f692bc60b4cf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f14bc228-919f-50c3-9bf5-735c613d72e5","sourceKey":"bank:BUA216:RAT-107","parentItemId":null,"revision":1,"payload":{"prompt":"Taking ROTA as (EBIT / total assets) x 100, net profit margin as (EBIT / sales) x 100 and asset turnover as sales / total assets, a company has a net profit margin of 8% and an asset turnover of 2.5 times. What is its ROTA?","options":["3.20%","20.00%","5.50%","10.50%"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Since (EBIT / sales) x (sales / total assets) = EBIT / total assets, ROTA = 8% x 2.5 = 20.00%. Option D adds the two figures, option A divides the margin by the turnover, and option C subtracts."}},{"itemId":"df3ccd8b-9d8d-5974-84b4-c3d9cdecadb8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fcac173e-81c9-5c6e-8397-a5cbc86d82c7","sourceKey":"bank:BUA216:RAT-108","parentItemId":null,"revision":1,"payload":{"prompt":"Lagos Island Textiles Ltd had sales of N500,000 and gross profit of N150,000 in Year 1, and sales of N600,000 and gross profit of N150,000 in Year 2. By how many percentage points did the gross profit margin change?","options":["A fall of 16.67 percentage points","No change","A rise of 20.00 percentage points","A fall of 5.00 percentage points"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Year 1 margin = 150,000 / 500,000 x 100 = 30%; Year 2 margin = 150,000 / 600,000 x 100 = 25%. The margin fell by 5.00 percentage points. Option B says no change because gross profit stayed the same, which ignores the rise in sales. Option C is the percentage change in sales, and option A is the relative fall (5 / 30 = 16.67%) instead of percentage points."}},{"itemId":"f04927f3-4026-5ca9-8dcc-9298d433f8e5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c58b864-1a99-55ab-82bf-d9fd8ecc7739","sourceKey":"bank:BUA216:RAT-109","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Bottlers Ltd's balance sheet shows: fixed assets N700,000; stock N90,000; debtors N70,000; cash N40,000; ordinary share capital N300,000; share premium N50,000; retained earnings N150,000; 10% preference share capital N100,000; debentures N200,000; current liabilities N100,000. EBIT for the year was N140,000. Calculate the acid test ratio.","options":["2.00 : 1","1.10 : 1","0.40 : 1","0.90 : 1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Current assets = 90,000 + 70,000 + 40,000 = 200,000. Acid test = (200,000 - 90,000) / 100,000 = 1.10 : 1. Option A is the current ratio, option C uses cash only, and option D divides stock by current liabilities."}},{"itemId":"2cb7a7a4-7e03-5e3e-831b-c71299a93f68","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"47166b64-109e-5acf-a0e9-1d4b792e1394","sourceKey":"bank:BUA216:RAT-110","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Bottlers Ltd's balance sheet shows: fixed assets N700,000; stock N90,000; debtors N70,000; cash N40,000; ordinary share capital N300,000; share premium N50,000; retained earnings N150,000; 10% preference share capital N100,000; debentures N200,000; current liabilities N100,000. EBIT for the year was N140,000. Taking the gearing ratio as fixed interest capital / equity capital, where fixed interest capital = debt capital + preference share capital, calculate the gearing ratio.","options":["0.33 : 1","0.60 : 1","0.38 : 1","0.40 : 1"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Fixed interest capital = 200,000 + 100,000 = 300,000; equity capital = 300,000 + 50,000 + 150,000 = 500,000. Gearing = 300,000 / 500,000 = 0.60 : 1. Option D ignores the preference shares, option C uses fixed interest capital over total long-term capital (800,000), and option A counts preference shares as equity (200,000 / 600,000)."}},{"itemId":"a9f6129f-56b5-5c60-88ea-d78108ff21ed","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"70eebd8b-b3f7-5ae9-b179-3b70bd8d110d","sourceKey":"bank:BUA216:RAT-111","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Bottlers Ltd's balance sheet shows: fixed assets N700,000; stock N90,000; debtors N70,000; cash N40,000; ordinary share capital N300,000; share premium N50,000; retained earnings N150,000; 10% preference share capital N100,000; debentures N200,000; current liabilities N100,000. EBIT for the year was N140,000. Taking ROCE as (EBIT / capital employed) x 100, where capital employed = total assets - current liabilities, calculate ROCE.","options":["17.50%","20.00%","15.56%","28.00%"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Total assets = 700,000 + 200,000 = 900,000, so capital employed = 900,000 - 100,000 = 800,000 and ROCE = 140,000 / 800,000 x 100 = 17.50%. Option C divides by total assets (this is ROTA), option D divides by ordinary shareholders' equity only (500,000), and option B divides by fixed assets."}},{"itemId":"cb2537b9-1b71-5a1d-97c4-4aa965b36526","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"66ba2d4c-de6f-5dc0-997f-389ba465152f","sourceKey":"bank:BUA216:RAT-112","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Bottlers Ltd's balance sheet shows: fixed assets N700,000; stock N90,000; debtors N70,000; cash N40,000; ordinary share capital N300,000; share premium N50,000; retained earnings N150,000; 10% preference share capital N100,000; debentures N200,000; current liabilities N100,000. EBIT for the year was N140,000. Taking the debt ratio as (total debt / total assets) x 100, where total debt = current liabilities + long term debt, calculate the debt ratio.","options":["22.22%","44.44%","33.33%","11.11%"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Total debt = 100,000 + 200,000 = 300,000 and total assets = 700,000 + 200,000 = 900,000, so debt ratio = 300,000 / 900,000 x 100 = 33.33%. Option A uses the debentures only, option B also adds preference shares to debt, and option D uses current liabilities only."}},{"itemId":"07da40f4-b6fb-50f5-97db-c18bebd2268f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cc594aca-93f4-59f0-adee-f2aa27914411","sourceKey":"bank:BUA216:RAT-113","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Bottlers Ltd's balance sheet shows: fixed assets N700,000; stock N90,000; debtors N70,000; cash N40,000; ordinary share capital N300,000; share premium N50,000; retained earnings N150,000; 10% preference share capital N100,000; debentures N200,000; current liabilities N100,000. EBIT for the year was N140,000. Taking fixed interest cover as EBIT / annual fixed interest charged on debt, and given that the debentures carry 14% interest, calculate the fixed interest cover.","options":["5.00 times","0.20 times","7.00 times","3.68 times"],"correctOption":0,"section":"Financial Ratio Analysis","explanation":"Annual debenture interest = 14% x 200,000 = 28,000, so cover = 140,000 / 28,000 = 5.00 times. Option D also adds the 10% preference dividend (10,000) to the interest charge, though preference dividend is not interest on debt. Option C uses 10% instead of 14%, and option B inverts the ratio."}},{"itemId":"dc8f96d8-ddf0-5006-b272-0effcfd0b5b7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"69fc2669-eab4-5f68-a7d9-fb6e906c529b","sourceKey":"bank:BUA216:RAT-114","parentItemId":null,"revision":1,"payload":{"prompt":"Taking stock turnover as cost of sales / average stock, where average stock = (opening stock + closing stock) / 2, Kano Leather Works had sales of N360,000, cost of sales of N240,000, opening stock of N36,000 and closing stock of N44,000. Calculate the stock turnover.","options":["6.67 times","6.00 times","9.00 times","5.45 times"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"Average stock = (36,000 + 44,000) / 2 = 40,000, so stock turnover = 240,000 / 40,000 = 6.00 times. Option C uses sales instead of cost of sales, option D uses closing stock only, and option A uses opening stock only."}},{"itemId":"629587da-8ac1-5442-8145-a708e0fd14cd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f9531d7b-22e6-5d05-ae4d-7442d1c0a35c","sourceKey":"bank:BUA216:RAT-115","parentItemId":null,"revision":1,"payload":{"prompt":"Gusau Motors Ltd has stock N24,000, debtors N30,000, cash N6,000 and current liabilities N40,000. Calculate its current ratio.","options":["0.90 : 1","1.35 : 1","1.50 : 1","0.67 : 1"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Current ratio = (24,000 + 30,000 + 6,000) / 40,000 = 60,000 / 40,000 = 1.50 : 1. Option A is the acid test ratio, which leaves out stock. Option D inverts the ratio, and option B leaves out the cash."}},{"itemId":"50fb4b2d-a11f-5db6-825c-52968547ec1a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bba8bdc3-cd18-5e3e-bcf7-fb5e5b6f8bf7","sourceKey":"bank:BUA216:RAT-116","parentItemId":null,"revision":1,"payload":{"prompt":"Taking net profit margin as (EBIT / sales) x 100, Mararaba Tiles Ltd has a net profit margin of 12% and EBIT of N84,000. What were its sales?","options":["N94,080","N1,008,000","N10,080","N700,000"],"correctOption":3,"section":"Financial Ratio Analysis","explanation":"Sales = EBIT / net profit margin = 84,000 / 0.12 = N700,000. Option C multiplies EBIT by 12% instead of dividing, option B multiplies by 12, and option A adds 12% to EBIT."}},{"itemId":"2efab5b2-5f64-5a68-a347-0bae6a765442","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9944d1e1-c465-5a97-81f8-d9751679c024","sourceKey":"bank:BUA216:RAT-117","parentItemId":null,"revision":1,"payload":{"prompt":"Taking ROSE as (EAIT / shareholders' equity) x 100, Isolo Prints Ltd achieved ROSE of 15% on shareholders' equity of N600,000. Tax is 30% of profit before tax and interest paid was N30,000. What was its EBIT, to the nearest naira?","options":["N128,571","N120,000","N158,571","N147,000"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"EAIT = 15% x 600,000 = 90,000. Profit before tax = 90,000 / 0.7 = 128,571 (to the nearest naira), and EBIT = 128,571 + 30,000 = N158,571. Option B adds interest to EAIT without grossing up for tax, option D grosses up by multiplying by 1.3 instead of dividing by 0.7, and option A forgets to add back interest."}},{"itemId":"4cbb91c9-e9cb-52aa-a758-c5d752fec4f8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"508c286a-8af6-5d62-a06a-a25959bf0788","sourceKey":"bank:BUA216:RAT-118","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the average collection period as (trade debtors / credit sales) x 365 days, Iwo Ceramics Ltd had opening trade debtors of N50,000 and closing trade debtors of N70,000, and you are told to use the average of the two. Credit sales were N730,000. Calculate the average collection period.","options":["60 days","35 days","30 days","25 days"],"correctOption":2,"section":"Financial Ratio Analysis","explanation":"Average debtors = (50,000 + 70,000) / 2 = 60,000, so collection period = 60,000 / 730,000 x 365 = 30 days. Option B uses closing debtors only, option D uses opening debtors only, and option A uses the sum of the two balances."}},{"itemId":"5413e990-0e21-52bc-b40a-1599c661ac46","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"97fb3581-0be7-5388-9275-96af7e5ff5dc","sourceKey":"bank:BUA216:RAT-119","parentItemId":null,"revision":1,"payload":{"prompt":"Taking DPS as gross dividend / number of shares issued and fully paid, and dividend yield as (DPS / market price per share) x 100, Ilaro Glass Plc has 10,000,000 shares issued and fully paid, a market price of N8.00 per share and a dividend yield of 4%. What was the gross dividend?","options":["N80,000,000","N3,200,000","N20,000,000","N400,000"],"correctOption":1,"section":"Financial Ratio Analysis","explanation":"DPS = 4% x 8.00 = N0.32, so gross dividend = 0.32 x 10,000,000 = N3,200,000. Option D takes 4% of the number of shares, as if each share were worth N1. Option C divides N8.00 by 4 to get DPS, and option A is the total market value of the shares."}},{"itemId":"c9cf54e8-275a-534a-82de-96dbe60f7fec","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bbae92e0-1b65-523a-8d4e-78c3f6161be5","sourceKey":"bank:BUA216:RSK-001","parentItemId":null,"revision":1,"payload":{"prompt":"The situation in which the future outcome is unknown but the likelihood of its occurrence can be estimated or determined is called","options":["risk","uncertainty","speculation","certainty"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Risk exists when we do not know the future outcome but can still estimate the probability of each possible outcome. Option B, uncertainty, is the case where those probabilities cannot be estimated at all, while certainty means the outcome is already known."}},{"itemId":"82e6c479-729a-58aa-91c2-9a344a0cc671","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"176ec49f-8e3d-5a67-99f2-088d90c34cca","sourceKey":"bank:BUA216:RSK-002","parentItemId":null,"revision":1,"payload":{"prompt":"When the future outcome of a decision is unknown and the probability of its occurrence cannot be estimated or determined, the decision maker faces","options":["risk","business risk","uncertainty","financial risk"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Uncertainty describes a future we cannot attach probabilities to. Risk differs because there the probabilities of the possible outcomes can be estimated; financial and business risk are particular types of risk, not the no-probability situation."}},{"itemId":"8556e88b-5e49-5e3f-80c5-1b1350b9632e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"948d589f-d577-5bb6-80e8-d7473b476ce4","sourceKey":"bank:BUA216:RSK-003","parentItemId":null,"revision":1,"payload":{"prompt":"The key feature that distinguishes risk from uncertainty is that under risk","options":["the future outcome is known in advance with certainty","no probabilities can be attached to any outcome","only losses are possible and gains cannot occur","the probabilities of possible future outcomes can be estimated"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"In both risk and uncertainty the actual future outcome is unknown; what separates them is that probabilities can be estimated under risk but not under uncertainty. Option B describes uncertainty itself, and option A, a known outcome, would be certainty rather than risk."}},{"itemId":"46d31b48-be78-5f28-aeb7-07c748e4d1f6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"16caf7f7-4346-5fdb-9646-3332601c9155","sourceKey":"bank:BUA216:RSK-004","parentItemId":null,"revision":1,"payload":{"prompt":"Ada Foods Ltd plans to launch a brand-new product in a market that has never existed before. Management has no past data or experience from which to estimate the probability of any level of sales. The situation Ada Foods faces is best described as","options":["risk, because the probabilities of outcomes can be estimated","uncertainty, because the probabilities of outcomes cannot be estimated","liquidity risk, because sales are unknown","certainty, because the product is new"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"When no probabilities can be attached to the possible outcomes, the decision is made under uncertainty. It would be risk only if management could estimate the likelihood of each sales level, and liquidity risk concerns failing to meet payments when due, not unknown demand."}},{"itemId":"e27e0cfb-a26c-5108-9e4f-feb84ec56830","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0af33272-942c-5dd1-b6a0-0a8fb686af45","sourceKey":"bank:BUA216:RSK-005","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano grain trader has 20 years of records showing that a good harvest occurs 60% of the time, a fair harvest 30% of the time and a poor harvest 10% of the time. His decision on how much grain to store is therefore made under","options":["uncertainty, since the harvest outcome is unknown","risk, since the likelihood of each outcome can be estimated","certainty, since the probabilities add up to 100%","financial risk, since grain prices may change"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"The outcome of the next harvest is unknown, but the trader can estimate the probability of each outcome, which is exactly what defines risk. Uncertainty would require that no probabilities could be estimated, and knowing probabilities does not make the outcome certain."}},{"itemId":"65c29528-58a7-598e-aa3b-fd565acf4b31","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5d5b3b61-63ed-527d-9d23-7ff5ce9df284","sourceKey":"bank:BUA216:RSK-006","parentItemId":null,"revision":1,"payload":{"prompt":"Business risk is the risk concerned with","options":["the inability to meet payment obligations in full and on time","shifts in macroeconomic variables or forces","the future uncertainty about a company's operating prospects","the introduction of debt into a company's capital structure"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Business risk relates to the uncertainty of the firm's operations themselves, such as its future sales, costs and operating profit. Option D describes financial risk, option B describes economic risk and option A describes liquidity risk."}},{"itemId":"fe7fb7e2-fbbe-52cf-8760-459cab2fb72b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"cb9a47e6-d5ef-50a5-acf8-e95cf8d42804","sourceKey":"bank:BUA216:RSK-007","parentItemId":null,"revision":1,"payload":{"prompt":"Zenith Plastics Ltd, previously financed wholly by equity, raises a N400 million long-term bank loan to fund expansion. The type of risk that this decision directly introduces is","options":["business risk","financial risk","market risk","liquidity risk"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Financial risk is the risk concerned with the introduction of debt into a company's capital structure, which is exactly what the bank loan does. Business risk concerns the operating prospects of the company whatever its financing, and market risk relates to the overall performance of financial markets."}},{"itemId":"40d30eba-6771-53bf-88e4-a7820be4335d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c3a46c57-8cea-51e5-8a55-fc2ec23e489b","sourceKey":"bank:BUA216:RSK-008","parentItemId":null,"revision":1,"payload":{"prompt":"The risk concerned with the amount of risk an organisation is exposed to due to shifts in macroeconomic variables or forces is known as","options":["financial risk","economic risk","liquidity risk","business risk"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Economic risk comes from changes in the wider economy, such as inflation, exchange rates and economic growth. Business risk is tied to the company's own operating prospects, while financial risk comes from using debt."}},{"itemId":"92d518fb-caed-59c3-a090-95dd0cdc96b4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aff6d422-3164-5430-b28c-a4d34901ec2e","sourceKey":"bank:BUA216:RSK-009","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos importer finds that a sharp fall in the value of the naira and a rise in the national inflation rate have increased its costs and reduced demand. The risk from these shifts in macroeconomic forces is best classified as","options":["liquidity risk","economic risk","financial risk","business risk only"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Exchange rates and inflation are macroeconomic variables, so exposure to shifts in them is economic risk. Financial risk would require the introduction of debt, and liquidity risk concerns the inability to pay obligations when due."}},{"itemId":"39c938ae-2eb8-5f5b-bcb9-bd9a799916f2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8fef8a42-47ae-53fc-bfe3-b32c0330b034","sourceKey":"bank:BUA216:RSK-010","parentItemId":null,"revision":1,"payload":{"prompt":"Interest rate risk is the risk concerned with","options":["the inability to meet payment obligations in full and on time when they become due","the exposure of a bank's current or future earnings and capital to adverse changes in market rates","the future uncertainty about a company's operating prospects","the introduction of debt into a company's capital structure"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Interest rate risk is the exposure of a bank's present or future earnings and capital to unfavourable movements in market rates. Option A is liquidity risk, option D is financial risk and option C is business risk."}},{"itemId":"db1bf12b-1fbf-5289-97e8-62729f46894a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7d3f947f-b5de-537d-afde-53b3e2cea6cf","sourceKey":"bank:BUA216:RSK-011","parentItemId":null,"revision":1,"payload":{"prompt":"After a sudden change in market interest rates, a Nigerian commercial bank finds that the interest it earns on its fixed-rate loans no longer covers the higher rates it must pay on deposits, reducing its earnings and capital. The bank is suffering from","options":["liquidity risk","financial risk","business risk","interest rate risk"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"The bank's earnings and capital have been hurt by adverse changes in market rates, which is the definition of interest rate risk. Liquidity risk would concern failing to make payments on time, and financial risk relates to debt in a company's capital structure."}},{"itemId":"b5f82027-9a3d-53a5-a7f7-439e2d2fdbc7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c7e003c6-cfdd-5dfa-8d71-4ecdbadb3f38","sourceKey":"bank:BUA216:RSK-012","parentItemId":null,"revision":1,"payload":{"prompt":"Market risk is best described as the risk concerned with","options":["shifts in macroeconomic variables affecting only one organisation","the introduction of debt into a company's capital structure","the inability to meet payment obligations as they fall due","the potential for losses arising from factors influencing the overall performance of financial markets"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Market risk is the possibility of losses caused by factors that affect the performance of financial markets as a whole. Option B describes financial risk and option C describes liquidity risk."}},{"itemId":"a71f4500-9710-557e-b463-516f2d251ec8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b1fe969c-2462-54e9-ade5-e6eaeff73ab0","sourceKey":"bank:BUA216:RSK-013","parentItemId":null,"revision":1,"payload":{"prompt":"Eko Distributors Ltd is profitable on paper, but most of its money is tied up in stock and slow-paying customers, so it cannot pay a supplier the N15 million due this Friday. The risk the company has run into is","options":["liquidity risk","economic risk","market risk","business risk"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Liquidity risk is the risk of loss from being unable to meet payment obligations in full and on time when they fall due, which is Eko's position. Being profitable does not remove this risk, and economic and market risk come from the wider economy and financial markets."}},{"itemId":"5e8ed75e-dfc6-5180-a231-0361710e119e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"13709294-1a90-5866-9596-d6ca49fc88ea","sourceKey":"bank:BUA216:RSK-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following pairings of a type of risk with its description is INCORRECT?","options":["Business risk - the future uncertainty about a company's operating prospects","Market risk - factors influencing the overall performance of financial markets","Liquidity risk - the introduction of debt into a company's capital structure","Economic risk - shifts in macroeconomic variables or forces"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Introducing debt into the capital structure describes financial risk, not liquidity risk; liquidity risk is the inability to meet payment obligations in full and on time. The other three pairings correctly match each risk to its description."}},{"itemId":"5ac366d5-5b37-5a0e-8edd-0f2c7e9683a1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a215c15-4a87-597b-a193-29b07acf649d","sourceKey":"bank:BUA216:RSK-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a probability method of treating risk?","options":["Expected return","Coefficient of variation","Sensitivity analysis","Standard deviation"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Sensitivity analysis is a non-probability method because it tests how results change when inputs change, without using probabilities. Expected return, variance, standard deviation and coefficient of variation are the probability methods."}},{"itemId":"1a5f6d0f-1e98-5fd4-a4dc-6c213f19ec7c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"87847ac8-0efa-50bb-aa71-160a745348ef","sourceKey":"bank:BUA216:RSK-016","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a non-probability method of treating risk?","options":["Variance","Coefficient of variation","Simulation","Expected value"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Simulation is one of the non-probability methods, alongside sensitivity analysis, payback period, the risk adjusted method and the certainty equivalent factor. Variance, expected value and coefficient of variation all belong to the probability method."}},{"itemId":"87e83aa9-5051-5bcc-bf08-23feaca88b9e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a632ba7c-3bdd-586d-b60b-f643f04c034b","sourceKey":"bank:BUA216:RSK-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a non-probability method of treating risk?","options":["Certainty equivalent factor","Risk adjusted method","Variance","Payback period"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Variance is calculated from a probability distribution, so it is a probability method. Payback period, the certainty equivalent factor and the risk adjusted method are all non-probability methods."}},{"itemId":"fc9ea507-bd84-51ff-be9f-3178a4e22514","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7590b3b3-c118-50a4-9ffd-763f07abeb2e","sourceKey":"bank:BUA216:RSK-018","parentItemId":null,"revision":1,"payload":{"prompt":"When the payback period is used to deal with risk in an investment decision, it is classified as","options":["a measure of expected return","a measure of dispersion around the mean","a non-probability method of treating risk","a probability method of treating risk"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Payback period is listed among the non-probability methods, together with sensitivity analysis, the risk adjusted method, the certainty equivalent factor and simulation. It does not use probabilities, so it is not a probability method, nor is it an expected return or dispersion measure."}},{"itemId":"6bf5a752-db2e-5a0f-a952-dfc53d49dfd2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"13271372-dc7d-5281-8cee-d6de1feeef7e","sourceKey":"bank:BUA216:RSK-019","parentItemId":null,"revision":1,"payload":{"prompt":"When comparing securities with the probability method, a higher variance, standard deviation and coefficient of variation indicate","options":["that the security is risk-free","higher risk in that security","a higher guaranteed return","lower risk in that security"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"The rule is that the higher the variance, standard deviation and coefficient of variation, the higher the risk in that security, and vice versa. These measures show how widely returns may spread, so they do not guarantee higher returns or indicate a risk-free security."}},{"itemId":"6e2a10f2-6ee3-5924-9370-838b9504201e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d6dec854-7264-5513-969d-fca74b229be3","sourceKey":"bank:BUA216:RSK-020","parentItemId":null,"revision":1,"payload":{"prompt":"A risk-averse investor choosing between securities analysed by the probability method will select the security with the","options":["lowest variance, standard deviation or coefficient of variation","widest spread of possible returns","highest variance, standard deviation or coefficient of variation","highest expected return regardless of risk"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"A risk-averse investor dislikes risk, so he or she picks the security with the lowest risk measure. Choosing the highest variance or widest spread, options B and C, is the behaviour of a risk taker."}},{"itemId":"9bc17034-e160-5dce-bfad-af9bb84d284c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"72961cfa-7e48-5fee-b68c-ff786fa70c2e","sourceKey":"bank:BUA216:RSK-021","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi is a risk taker investor. An analyst gives her the coefficients of variation of three shares: Share P 12%, Share Q 31% and Share R 19%. Using the coefficient of variation as the measure of risk, Bisi should choose","options":["Share Q","Share R","none of the shares, because all are risky","Share P"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"A risk taker selects the security with the highest risk, and Share Q has the highest coefficient of variation at 31%. Share P, with the lowest CV, would be the choice of a risk-averse investor."}},{"itemId":"392fd5df-5032-536a-854f-7d7447f1fc5c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fb5a3197-1961-5551-8133-9e6a51059dd1","sourceKey":"bank:BUA216:RSK-022","parentItemId":null,"revision":1,"payload":{"prompt":"An investor who is indifferent to risk and simply chooses the investment with the highest expected return, ignoring its variance or standard deviation, is described as","options":["a risk taker","risk seeking only in losses","risk neutral","risk averse"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"A risk-neutral investor cares only about expected return and is indifferent to the level of risk. A risk-averse investor would favour lower risk and a risk taker (risk seeker) would favour higher risk, so both pay attention to the risk measure."}},{"itemId":"efc2a4fe-ef32-542e-8c37-b3f145e3ad22","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"664ddcaa-8e3e-5103-bdd9-ca19d9845fb5","sourceKey":"bank:BUA216:RSK-023","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde is offered either a certain payment of N200,000 or a gamble that pays N400,000 with probability 0.5 and nothing with probability 0.5. Both have the same expected value of N200,000, and Tunde chooses the certain N200,000. His behaviour shows that he is","options":["a risk taker","risk neutral","risk averse","irrational, since both have equal value"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Given two choices with the same expected value, Tunde prefers the one with no risk, which is risk-averse behaviour. A risk-neutral person would be indifferent between the two, and a risk taker would prefer the gamble."}},{"itemId":"5a473837-b802-5652-8b30-1587a79dff38","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ea35f8c0-2d0c-526f-a4c5-99f8c0ee6519","sourceKey":"bank:BUA216:RSK-024","parentItemId":null,"revision":1,"payload":{"prompt":"Kemi is offered either a certain N50,000 or a lottery paying N100,000 with probability 0.5 and N0 with probability 0.5 (expected value N50,000). She chooses the lottery even though it has the same expected value and much higher risk. Kemi is best described as","options":["risk neutral","risk averse","a hedger","a risk taker (risk seeker)"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Choosing the riskier option when expected values are equal shows a preference for risk, which is a risk taker or risk seeker. A risk-averse investor would take the certain N50,000, and a risk-neutral one would not mind either way."}},{"itemId":"043d0f99-d51e-5ea4-84ee-89a46d4ffee5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2d20688d-3837-5950-af65-934e968ca70c","sourceKey":"bank:BUA216:RSK-025","parentItemId":null,"revision":1,"payload":{"prompt":"The coefficient of variation, CV = (SD / ER) x 100, measures","options":["the average return expected from an investment","the amount of risk per unit of expected return","the total return earned over a holding period","the proportion of a portfolio held in one security"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Dividing the standard deviation by the expected return gives relative risk, that is, how much risk is carried for each unit of expected return. The expected return itself (option A) is the average outcome, not a risk measure."}},{"itemId":"e82c644e-a772-5978-b1de-f98839110681","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b0970d7d-9cd5-5e29-9a7f-49b0706f868f","sourceKey":"bank:BUA216:RSK-026","parentItemId":null,"revision":1,"payload":{"prompt":"Two projects have very different expected returns: Project K expects N2 million and Project L expects N20 million. To compare their riskiness fairly, the most suitable measure is the","options":["range of the probabilities","variance alone","expected return","coefficient of variation"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"When expected returns differ greatly, the standard deviation or variance alone can mislead because a bigger project naturally has bigger naira deviations. The coefficient of variation divides SD by ER, so it gives risk per naira of expected return and makes the comparison fair."}},{"itemId":"6a52dc1b-a63c-57cf-8435-31bdbdf31c23","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"9dd58ea0-ec28-5da1-b533-df1fa50cbf09","sourceKey":"bank:BUA216:RSK-027","parentItemId":null,"revision":1,"payload":{"prompt":"Standard deviation, calculated as the square root of the variance, measures","options":["the dispersion of possible returns around the expected return","the risk per unit of expected return","the most likely single return of an investment","the weighted average of the possible returns"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Standard deviation shows how widely the possible returns are spread around the expected return; a bigger spread means more risk. The weighted average of returns is the expected return, and risk per unit of return is the coefficient of variation."}},{"itemId":"0bf3002a-79d5-51de-adca-d5268e94dfb6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1fd05152-f811-5e20-9cda-5fa1acb4e855","sourceKey":"bank:BUA216:RSK-028","parentItemId":null,"revision":1,"payload":{"prompt":"The expected return of a security, ER = sum of (Probability x Return), is also known as the","options":["variance","mean or expected value","standard deviation","coefficient of variation"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average of the possible returns, which is why it is also called the mean or expected value. Variance, standard deviation and coefficient of variation measure risk rather than the average outcome."}},{"itemId":"e7a49360-dec4-51ec-aa3c-ba15767988f6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a52e0bca-5b0f-5d99-92c9-1cd307df5413","sourceKey":"bank:BUA216:RSK-029","parentItemId":null,"revision":1,"payload":{"prompt":"Risks that are uncontrollable by investors and cannot be diversified away by any investor, such as war or a general rise in inflation, are called","options":["business-specific risks","unsystematic risks","liquidity risks","systematic risks"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Systematic risks affect the whole market, so no investor can remove them by holding more securities. Unsystematic risks, option B, are controllable and diversifiable because they affect particular companies."}},{"itemId":"ccd1cabd-2c85-5ec9-b72e-fe4740bbb22c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"667eb731-9dc9-51c5-926c-806723e34732","sourceKey":"bank:BUA216:RSK-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of unsystematic risk?","options":["General inflation","A shortage of production inputs at one manufacturing company","A natural disaster affecting the whole economy","A stock market crash"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"A shortage of inputs at one firm affects that company, so the risk can be reduced by spreading investment across other firms; that makes it unsystematic. A market crash, general inflation and economy-wide natural disasters are systematic risks that affect all securities."}},{"itemId":"2f2a522f-68dd-552f-8d30-cc987b102ad4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b9388e77-8a03-52dc-8014-5834576a454b","sourceKey":"bank:BUA216:RSK-032","parentItemId":null,"revision":1,"payload":{"prompt":"By spreading her funds across shares of many unrelated companies, an investor can reduce","options":["unsystematic risk, but not systematic risk","systematic risk, but not unsystematic risk","both systematic and unsystematic risk to zero","neither systematic nor unsystematic risk"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Unsystematic risks are controllable and diversifiable, so holding many unrelated securities reduces them. Systematic risks cannot be diversified away by any investor, which rules out options B and C."}},{"itemId":"60104489-dba0-5df3-be1f-0c779835a8bb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0bbb53a4-8089-5343-bd59-9d6f1655210a","sourceKey":"bank:BUA216:RSK-037","parentItemId":null,"revision":1,"payload":{"prompt":"A 91-day Federal Government treasury bill offers a near-certain 12% return, while shares in a new Lagos tech start-up have widely spread possible returns. Investors will only buy the start-up's shares if their expected return is well above 12%. This illustrates","options":["the risk-return trade-off: a higher risk must be compensated by a higher expected return","that risk-averse investors always choose the investment with the highest variance","that diversification removes all risk from the start-up's shares","that higher-risk investments always produce a higher actual return"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Investors demand extra expected return for bearing extra risk, which is the risk-return trade-off. Option D is wrong because a higher expected return is not a guaranteed actual return, and option C is wrong because systematic risk can never be diversified away."}},{"itemId":"026d9394-159f-54c6-a6b9-8e10a5729b23","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"91c7d928-699b-5b97-a682-2363aa9d918f","sourceKey":"bank:BUA216:RSK-039","parentItemId":null,"revision":1,"payload":{"prompt":"For Security X being considered by an investor, the possible returns and their probabilities are: N5,000 (probability 0.1); N6,000 (probability 0.3); N7,000 (probability 0.6). The expected return is","options":["N5,500","N7,000","N6,000","N6,500"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: ER = sum of (P x R) = 0.1 x 5,000 + 0.3 x 6,000 + 0.6 x 7,000 = N6,500. By contrast, taking a simple average of the returns, which ignores the probabilities, gives N6,000, and picking only the most likely return gives N7,000."}},{"itemId":"3797d795-4252-50e3-90f8-56fa1f3cd356","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af21a314-525c-5c6c-9159-eb85cef0cdf3","sourceKey":"bank:BUA216:RSK-040","parentItemId":null,"revision":1,"payload":{"prompt":"For Security X being considered by an investor, the possible returns and their probabilities are: N5,000 (probability 0.1); N6,000 (probability 0.3); N7,000 (probability 0.6). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["450,000","2,750,000","916,667","700,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"First ER = 6,500. Then Var = sum of P x (R - ER)^2 = 0.1 x (-1,500)^2 + 0.3 x (-500)^2 + 0.6 x (500)^2 = 450,000. Adding the squared deviations without multiplying by the probabilities gives 2,750,000, and dividing that by the number of outcomes gives 916,667; both ignore the probabilities."}},{"itemId":"d2bc50ac-c008-5f58-831d-5ddcd9869278","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"073ff3a8-8997-51fb-8dc8-d744ac200f7c","sourceKey":"bank:BUA216:RSK-041","parentItemId":null,"revision":1,"payload":{"prompt":"For Security Y being considered by an investor, the possible returns and their probabilities are: N8,000 (probability 0.2); N7,000 (probability 0.4); N6,000 (probability 0.4). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to 2 decimal places, is","options":["N840.63","N1,456.02","N748.33","N640.00"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER = 6,800, and Var = sum of P x (R - ER)^2 = 560,000, so SD = sqrt(560,000) = N748.33. The figure N1,456.02 comes from squaring the deviations without weighting them by the probabilities, and N640.00 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"e3da2c17-c295-507a-bbb3-aac227b8fea2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"05f80f62-15e7-5ac7-aa5b-c36a6447ba3e","sourceKey":"bank:BUA216:RSK-042","parentItemId":null,"revision":1,"payload":{"prompt":"For Security Y being considered by an investor, the possible returns and their probabilities are: N8,000 (probability 0.2); N7,000 (probability 0.4); N6,000 (probability 0.4). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["82.35%","11.00%","908.69%","9.35%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"ER = 6,800, Var = 560,000 and SD = sqrt(560,000) = 748.33, so CV = (748.33 / 6,800) x 100 = 11.00%. Turning the ratio upside down, ER / SD x 100, gives 908.69%, and dividing SD by the highest return instead of ER gives 9.35%."}},{"itemId":"32f54b9b-0b8f-56ce-b1b7-5c783b5026bd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e97cb67a-f00a-5a88-ad89-fda553745625","sourceKey":"bank:BUA216:RSK-043","parentItemId":null,"revision":1,"payload":{"prompt":"Willy, a risk taker investor, is considering two securities. Security X: N5,000 (probability 0.1), N6,000 (0.3), N7,000 (0.6). Security Y: N8,000 (probability 0.2), N7,000 (0.4), N6,000 (0.4). Using probability-weighted variance and CV = (SD / ER) x 100, which recommendation is correct?","options":["Security Y, because its variance of 450,000 is lower than X's","Security X, because its expected return of N6,500 is higher than Y's","Security Y, because its CV of about 11.00% is higher than X's CV of about 10.32%","Security X, because its CV of about 10.32% is lower than Y's CV of about 11.00%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER(X) = N6,500, Var(X) = 450,000, SD = 670.82, CV = 10.32%; ER(Y) = N6,800, Var(Y) = 560,000, SD = 748.33, CV = 11.00%. A risk taker chooses the security with the higher risk, so Y is recommended. Option D is the risk-averse choice, and options A and B misstate the figures, since Y has the higher expected return and the higher variance."}},{"itemId":"0e8b81e6-28f2-51e2-930b-e62235084187","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b19cd1d5-889a-5f56-b773-fdbfdde89403","sourceKey":"bank:BUA216:RSK-044","parentItemId":null,"revision":1,"payload":{"prompt":"Security B has returns of N6,000 (probability 0.7), N4,000 (probability 0.2) and N3,000 (probability 0.1). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of Security B is","options":["7,630,000","1,210,000","2,543,333","1,100"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"ER = 0.7 x 6,000 + 0.2 x 4,000 + 0.1 x 3,000 = 5,300. Var = 0.7 x 700^2 + 0.2 x (-1,300)^2 + 0.1 x (-2,300)^2 = 343,000 + 338,000 + 529,000 = 1,210,000. The figure 1,100 is the standard deviation, while 7,630,000 adds the squared deviations without weighting by the probabilities."}},{"itemId":"5453880e-79cc-5240-b03d-d66f305e6670","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"015b58b3-850c-5102-b883-576a3e2eb260","sourceKey":"bank:BUA216:RSK-045","parentItemId":null,"revision":1,"payload":{"prompt":"James, a risk-averse investor, finds that Security A has an expected return of N4,700 and a standard deviation of N640, while Security B has an expected return of N5,300 and a standard deviation of N1,100. Using CV = (SD / ER) x 100, rounded to the nearest whole percent, which is the correct recommendation?","options":["Security A, with a CV of 734% against 482% for B","Security A, with a CV of 14% against 21% for B","Security B, with a CV of 21% against 14% for A","Security B, because its expected return is higher"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"CV(A) = 640 / 4,700 x 100 = 14% and CV(B) = 1,100 / 5,300 x 100 = 21%. A risk-averse investor selects the lower risk, so Security A is recommended. Option C is the risk taker's choice, and the 734% and 482% figures come from inverting the formula to ER / SD."}},{"itemId":"062ffbd8-b85f-5077-bae4-026217f13a2d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"af508e44-812d-55de-a6cc-0f20ec19573a","sourceKey":"bank:BUA216:RSK-046","parentItemId":null,"revision":1,"payload":{"prompt":"For an investment in Obi Bakeries Ltd, the possible returns and their probabilities are: N7,000 (probability 0.1); N11,000 (probability 0.6); N15,000 (probability 0.3). The expected return is","options":["N10,200","N11,000","N11,800","N9,000"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: ER = sum of (P x R) = 0.1 x 7,000 + 0.6 x 11,000 + 0.3 x 15,000 = N11,800. By contrast, taking a simple average of the returns, which ignores the probabilities, gives N11,000, and matching the probabilities to the returns in reverse order gives N10,200."}},{"itemId":"7d80d131-6e59-5536-8a7a-a51a50b55a7b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7382529f-3d76-5991-ad2d-bfab8d352420","sourceKey":"bank:BUA216:RSK-047","parentItemId":null,"revision":1,"payload":{"prompt":"For an investment in Obi Bakeries Ltd, the possible returns and their probabilities are: N7,000 (probability 0.1); N11,000 (probability 0.6); N15,000 (probability 0.3). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["33,920,000","6,400,000","11,306,667","5,760,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"First ER = 11,800. Then Var = sum of P x (R - ER)^2 = 0.1 x (-4,800)^2 + 0.6 x (-800)^2 + 0.3 x (3,200)^2 = 5,760,000. Adding the squared deviations without multiplying by the probabilities gives 33,920,000, and dividing that by the number of outcomes gives 11,306,667; both ignore the probabilities."}},{"itemId":"238cbc09-e752-5e0d-8206-2805f3f3d93b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3f50564e-56a9-566b-a349-af014369067d","sourceKey":"bank:BUA216:RSK-048","parentItemId":null,"revision":1,"payload":{"prompt":"For an investment in Obi Bakeries Ltd, the possible returns and their probabilities are: N7,000 (probability 0.1); N11,000 (probability 0.6); N15,000 (probability 0.3). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to the nearest naira, is","options":["N3,363","N1,920","N2,400","N5,824"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER = 11,800, and Var = sum of P x (R - ER)^2 = 5,760,000, so SD = sqrt(5,760,000) = N2,400. The figure N5,824 comes from squaring the deviations without weighting them by the probabilities, and N1,920 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"9481aad1-f32c-5e18-89b8-f3031f58b2eb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"41c516b2-7cb0-510b-abac-33be51c8fb23","sourceKey":"bank:BUA216:RSK-049","parentItemId":null,"revision":1,"payload":{"prompt":"For an investment in Obi Bakeries Ltd, the possible returns and their probabilities are: N7,000 (probability 0.1); N11,000 (probability 0.6); N15,000 (probability 0.3). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["20.34%","491.67%","16.00%","488.14%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"ER = 11,800, Var = 5,760,000 and SD = sqrt(5,760,000) = 2,400.00, so CV = (2,400.00 / 11,800) x 100 = 20.34%. Turning the ratio upside down, ER / SD x 100, gives 491.67%, and dividing SD by the highest return instead of ER gives 16.00%."}},{"itemId":"dc79698e-f272-5a53-adfd-1e9c28a5aee4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"31592888-6031-5017-a840-44d5a60e92da","sourceKey":"bank:BUA216:RSK-050","parentItemId":null,"revision":1,"payload":{"prompt":"For a poultry project in Ogun State, the possible returns and their probabilities are: N9,000 (probability 0.3); N14,000 (probability 0.5); N19,000 (probability 0.2). The expected return is","options":["N14,500","N14,000","N13,000","N13,500"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: ER = sum of (P x R) = 0.3 x 9,000 + 0.5 x 14,000 + 0.2 x 19,000 = N13,500. By contrast, taking a simple average of the returns, which ignores the probabilities, gives N14,000, and matching the probabilities to the returns in reverse order gives N14,500."}},{"itemId":"ce374aaa-a2ea-53fe-aa6f-fa23bc1a4e6b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2291a160-2a24-5c7e-ae2e-067e9832a432","sourceKey":"bank:BUA216:RSK-051","parentItemId":null,"revision":1,"payload":{"prompt":"For a poultry project in Ogun State, the possible returns and their probabilities are: N9,000 (probability 0.3); N14,000 (probability 0.5); N19,000 (probability 0.2). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["16,916,667","12,500,000","50,750,000","12,250,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"First ER = 13,500. Then Var = sum of P x (R - ER)^2 = 0.3 x (-4,500)^2 + 0.5 x (500)^2 + 0.2 x (5,500)^2 = 12,250,000. Adding the squared deviations without multiplying by the probabilities gives 50,750,000, and dividing that by the number of outcomes gives 16,916,667; both ignore the probabilities."}},{"itemId":"6c706da4-5db3-5383-b409-bf8447101414","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"127631b0-5a3b-5dc0-995b-7fc7bd45bb2d","sourceKey":"bank:BUA216:RSK-052","parentItemId":null,"revision":1,"payload":{"prompt":"For a poultry project in Ogun State, the possible returns and their probabilities are: N9,000 (probability 0.3); N14,000 (probability 0.5); N19,000 (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to the nearest naira, is","options":["N4,113","N2,700","N7,124","N3,500"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"ER = 13,500, and Var = sum of P x (R - ER)^2 = 12,250,000, so SD = sqrt(12,250,000) = N3,500. The figure N7,124 comes from squaring the deviations without weighting them by the probabilities, and N2,700 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"6d4e7b44-eadf-5201-a4ab-99450b16c2cc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"46898c93-c117-5441-8a2d-c1ac4cca52a9","sourceKey":"bank:BUA216:RSK-053","parentItemId":null,"revision":1,"payload":{"prompt":"For a poultry project in Ogun State, the possible returns and their probabilities are: N9,000 (probability 0.3); N14,000 (probability 0.5); N19,000 (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["18.42%","907.41%","25.93%","385.71%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER = 13,500, Var = 12,250,000 and SD = sqrt(12,250,000) = 3,500.00, so CV = (3,500.00 / 13,500) x 100 = 25.93%. Turning the ratio upside down, ER / SD x 100, gives 385.71%, and dividing SD by the highest return instead of ER gives 18.42%."}},{"itemId":"9c35656f-5dc8-586a-8eb7-c562e3cf5ce9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"383a3358-5c50-5052-9ec3-07f43bcee8af","sourceKey":"bank:BUA216:RSK-054","parentItemId":null,"revision":1,"payload":{"prompt":"For a transport project in Ibadan, the possible returns and their probabilities are: N13,000 (probability 0.2); N22,000 (probability 0.6); N28,000 (probability 0.2). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["23,040,000","114,480,000","23,200,000","38,160,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"First ER = 21,400. Then Var = sum of P x (R - ER)^2 = 0.2 x (-8,400)^2 + 0.6 x (600)^2 + 0.2 x (6,600)^2 = 23,040,000. Adding the squared deviations without multiplying by the probabilities gives 114,480,000, and dividing that by the number of outcomes gives 38,160,000; both ignore the probabilities."}},{"itemId":"f9e601cf-9acf-50d2-b68f-5fe416b06bce","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"37242587-9747-52ac-b55e-97046a67d088","sourceKey":"bank:BUA216:RSK-055","parentItemId":null,"revision":1,"payload":{"prompt":"For a transport project in Ibadan, the possible returns and their probabilities are: N13,000 (probability 0.2); N22,000 (probability 0.6); N28,000 (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to the nearest naira, is","options":["N6,177","N3,360","N4,800","N10,700"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER = 21,400, and Var = sum of P x (R - ER)^2 = 23,040,000, so SD = sqrt(23,040,000) = N4,800. The figure N10,700 comes from squaring the deviations without weighting them by the probabilities, and N3,360 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"b392b661-7975-5229-8f25-aca24ada40fb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7ba5df3c-4d8f-5ff8-af14-e951cd5920b3","sourceKey":"bank:BUA216:RSK-056","parentItemId":null,"revision":1,"payload":{"prompt":"For shares in Ikeja Water Plc, the possible returns and their probabilities are: N16,000 (probability 0.25); N17,000 (probability 0.5); N20,000 (probability 0.25). The expected return is","options":["N17,250","N17,500","N17,667","N17,000"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: ER = sum of (P x R) = 0.25 x 16,000 + 0.5 x 17,000 + 0.25 x 20,000 = N17,500. By contrast, taking a simple average of the returns, which ignores the probabilities, gives N17,667, and picking only the most likely return gives N17,000."}},{"itemId":"d5fc9148-3428-5980-822c-c9653571a57b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d1550a23-dc99-5f00-8e4e-5b3cfa3e0474","sourceKey":"bank:BUA216:RSK-057","parentItemId":null,"revision":1,"payload":{"prompt":"For shares in Ikeja Water Plc, the possible returns and their probabilities are: N16,000 (probability 0.25); N17,000 (probability 0.5); N20,000 (probability 0.25). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to the nearest naira, is","options":["N2,958","N1,708","N1,250","N1,500"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"ER = 17,500, and Var = sum of P x (R - ER)^2 = 2,250,000, so SD = sqrt(2,250,000) = N1,500. The figure N2,958 comes from squaring the deviations without weighting them by the probabilities, and N1,250 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"48a817fe-91c7-5997-ac50-cc9344afc509","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0a5a8fa5-90be-5d72-8229-26574e693476","sourceKey":"bank:BUA216:RSK-058","parentItemId":null,"revision":1,"payload":{"prompt":"For a printing business in Enugu, the possible returns and their probabilities are: N13,000 (probability 0.5); N17,000 (probability 0.3); N20,000 (probability 0.2). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["7,840,000","28,080,000","8,977,778","9,360,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"First ER = 15,600. Then Var = sum of P x (R - ER)^2 = 0.5 x (-2,600)^2 + 0.3 x (1,400)^2 + 0.2 x (4,400)^2 = 7,840,000. Adding the squared deviations without multiplying by the probabilities gives 28,080,000, and dividing that by the number of outcomes gives 9,360,000; both ignore the probabilities."}},{"itemId":"9bbc080e-9262-55e2-a73d-cc6ee2dc72fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"646e86be-cee1-512f-9aae-189686fd2f58","sourceKey":"bank:BUA216:RSK-059","parentItemId":null,"revision":1,"payload":{"prompt":"For a printing business in Enugu, the possible returns and their probabilities are: N13,000 (probability 0.5); N17,000 (probability 0.3); N20,000 (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["17.95%","502.56%","14.00%","557.14%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"ER = 15,600, Var = 7,840,000 and SD = sqrt(7,840,000) = 2,800.00, so CV = (2,800.00 / 15,600) x 100 = 17.95%. Turning the ratio upside down, ER / SD x 100, gives 557.14%, and dividing SD by the highest return instead of ER gives 14.00%."}},{"itemId":"6c67e6a5-0b92-5a33-bc36-12cc99ac44eb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ba6ce05c-6d0b-5a29-b8d1-ae4475031bbf","sourceKey":"bank:BUA216:RSK-060","parentItemId":null,"revision":1,"payload":{"prompt":"For a cold-room project in Kano, the possible returns and their probabilities are: N17,000 (probability 0.4); N23,000 (probability 0.4); N26,000 (probability 0.2). The expected return is","options":["N21,200","N17,000","N22,000","N23,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Expected return is the probability-weighted average: ER = sum of (P x R) = 0.4 x 17,000 + 0.4 x 23,000 + 0.2 x 26,000 = N21,200. By contrast, taking a simple average of the returns, which ignores the probabilities, gives N22,000, and picking only the most likely return gives N17,000."}},{"itemId":"ac885c76-479c-5f99-ba38-ef8c4a4055ea","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e7cfb0a6-4fa2-568d-95a5-98d966f58ea2","sourceKey":"bank:BUA216:RSK-061","parentItemId":null,"revision":1,"payload":{"prompt":"For a cold-room project in Kano, the possible returns and their probabilities are: N17,000 (probability 0.4); N23,000 (probability 0.4); N26,000 (probability 0.2). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["13,600,000","43,920,000","14,640,000","12,960,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"First ER = 21,200. Then Var = sum of P x (R - ER)^2 = 0.4 x (-4,200)^2 + 0.4 x (1,800)^2 + 0.2 x (4,800)^2 = 12,960,000. Adding the squared deviations without multiplying by the probabilities gives 43,920,000, and dividing that by the number of outcomes gives 14,640,000; both ignore the probabilities."}},{"itemId":"573d0a9d-fab9-51df-971a-573f5008f96a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"81f537a0-f936-5557-8888-1723de113414","sourceKey":"bank:BUA216:RSK-062","parentItemId":null,"revision":1,"payload":{"prompt":"For a cold-room project in Kano, the possible returns and their probabilities are: N17,000 (probability 0.4); N23,000 (probability 0.4); N26,000 (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["588.89%","16.98%","13.85%","611.32%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"ER = 21,200, Var = 12,960,000 and SD = sqrt(12,960,000) = 3,600.00, so CV = (3,600.00 / 21,200) x 100 = 16.98%. Turning the ratio upside down, ER / SD x 100, gives 588.89%, and dividing SD by the highest return instead of ER gives 13.85%."}},{"itemId":"f97fb56c-6e87-5d4b-96e2-525993451714","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"77515478-ff25-573c-9c4b-3028ababb5f0","sourceKey":"bank:BUA216:RSK-063","parentItemId":null,"revision":1,"payload":{"prompt":"For a fashion retail outlet in Abuja, the possible returns and their probabilities are: N12,000 (probability 0.2); N15,000 (probability 0.5); N27,000 (probability 0.3). Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the returns is","options":["126,000,000","42,000,000","36,000,000","72,000,000"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"First ER = 18,000. Then Var = sum of P x (R - ER)^2 = 0.2 x (-6,000)^2 + 0.5 x (-3,000)^2 + 0.3 x (9,000)^2 = 36,000,000. Adding the squared deviations without multiplying by the probabilities gives 126,000,000, and dividing that by the number of outcomes gives 42,000,000; both ignore the probabilities."}},{"itemId":"ee92b15a-fb4e-5a49-bca2-58ea9ab576fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"44875e15-d466-5e46-bf4f-9c0ec4cea01b","sourceKey":"bank:BUA216:RSK-064","parentItemId":null,"revision":1,"payload":{"prompt":"For a fashion retail outlet in Abuja, the possible returns and their probabilities are: N12,000 (probability 0.2); N15,000 (probability 0.5); N27,000 (probability 0.3). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the returns, to the nearest naira, is","options":["N6,481","N5,400","N6,000","N11,225"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"ER = 18,000, and Var = sum of P x (R - ER)^2 = 36,000,000, so SD = sqrt(36,000,000) = N6,000. The figure N11,225 comes from squaring the deviations without weighting them by the probabilities, and N5,400 is just the average absolute deviation, which is never squared and rooted."}},{"itemId":"1355fa25-a800-535b-b4d9-b47d934e1e34","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f47cd95e-c95b-58db-ae78-9f606e94e172","sourceKey":"bank:BUA216:RSK-065","parentItemId":null,"revision":1,"payload":{"prompt":"For a fashion retail outlet in Abuja, the possible returns and their probabilities are: N12,000 (probability 0.2); N15,000 (probability 0.5); N27,000 (probability 0.3). Taking variance as the probability-weighted sum of P x (R - ER)^2 and CV = (SD / ER) x 100, the coefficient of variation, to 2 decimal places, is","options":["300.00%","62.36%","22.22%","33.33%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"ER = 18,000, Var = 36,000,000 and SD = sqrt(36,000,000) = 6,000.00, so CV = (6,000.00 / 18,000) x 100 = 33.33%. Turning the ratio upside down, ER / SD x 100, gives 300.00%, and dividing SD by the highest return instead of ER gives 22.22%."}},{"itemId":"6788378e-82bc-515f-9e66-7fd6e709e993","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"68598c94-0005-546c-8829-16a265f4b053","sourceKey":"bank:BUA216:RSK-066","parentItemId":null,"revision":1,"payload":{"prompt":"A share's return depends on the state of the economy: boom 25% (probability 0.3), normal 15% (probability 0.5) and recession -5% (probability 0.2). The expected return of the share is","options":["14.00%","11.67%","16.00%","15.00%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"ER = 0.3 x 25 + 0.5 x 15 + 0.2 x (-5) = 7.5 + 7.5 - 1 = 14.00%. A simple average of the three returns gives 11.67%, and treating the recession return as +5% instead of -5% gives 16.00%."}},{"itemId":"1920eb74-247c-5e22-b2e7-708386dc130e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0c24fb30-4ab3-5efc-8762-a62ee24222f9","sourceKey":"bank:BUA216:RSK-067","parentItemId":null,"revision":1,"payload":{"prompt":"A share's return depends on the state of the economy: boom 25% (probability 0.3), normal 15% (probability 0.5) and recession -5% (probability 0.2). Its expected return is 14%. Using the probabilities as weights, so that variance = sum of P x (R - ER)^2, the variance of the share's return (in %^2) is","options":["109.00","161.00","483.00","10.44"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Var = 0.3 x (25 - 14)^2 + 0.5 x (15 - 14)^2 + 0.2 x (-5 - 14)^2 = 36.3 + 0.5 + 72.2 = 109.00. Adding the squared deviations without probabilities gives 121 + 1 + 361 = 483, and 10.44 is the standard deviation, not the variance."}},{"itemId":"2aa601bd-b80e-53d2-97d6-afe5eae37669","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c30fdba6-8cb2-5667-b762-c154fb63c5ec","sourceKey":"bank:BUA216:RSK-068","parentItemId":null,"revision":1,"payload":{"prompt":"A share has an expected return of 14% and returns of 25% (probability 0.3), 15% (probability 0.5) and -5% (probability 0.2). Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the share's return, to 2 decimal places, is","options":["21.98%","10.44%","12.69%","109.00%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Var = 36.3 + 0.5 + 72.2 = 109, so SD = sqrt(109) = 10.44%. The figure 21.98% is the square root of the unweighted sum of squared deviations (483), 109.00% is the variance mistaken for SD, and 12.69% is sqrt(161) from wrongly treating -5% as +5%."}},{"itemId":"9b8ddb37-7ced-546b-9934-a7150ed0b1bd","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1f292087-31ec-5de2-99f6-4d8bad3cd7eb","sourceKey":"bank:BUA216:RSK-069","parentItemId":null,"revision":1,"payload":{"prompt":"Project M has an expected return of N13,500 and a standard deviation of N3,500. Project N has an expected return of N21,400 and a standard deviation of N4,800. Using the coefficient of variation, CV = (SD / ER) x 100, as the measure of risk, a risk-averse investor should choose","options":["Project M, because its CV of 25.93% is lower than N's 22.43%","Project M, because its standard deviation of N3,500 is lower","Project N, because its CV of 25.93% is higher than M's 22.43%","Project N, because its CV of 22.43% is lower than M's 25.93%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"CV(M) = 3,500 / 13,500 x 100 = 25.93% and CV(N) = 4,800 / 21,400 x 100 = 22.43%, so N carries less risk per naira of expected return and suits a risk-averse investor. Option B judges by standard deviation alone, which misleads when the expected returns differ, and options A and C swap the two CVs."}},{"itemId":"315154bc-e4a9-5539-9c34-4391d572bf13","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b506469b-23eb-5b84-97cd-a5068bb483e4","sourceKey":"bank:BUA216:RSK-070","parentItemId":null,"revision":1,"payload":{"prompt":"Project M has an expected return of N13,500 and a variance of 12,250,000. Project N has an expected return of N21,400 and a variance of 23,040,000. A risk taker investor who uses the coefficient of variation, CV = (SD / ER) x 100, as the measure of risk will choose","options":["Project M, with a CV of 90,740.74%","Project N, with a CV of 22.43%","Project N, with a CV of 107,663.55%","Project M, with a CV of 25.93%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"SD(M) = sqrt(12,250,000) = 3,500, so CV(M) = 3,500 / 13,500 x 100 = 25.93%; SD(N) = sqrt(23,040,000) = 4,800, so CV(N) = 22.43%. A risk taker picks the higher CV, Project M. The very large percentages come from dividing the variance, rather than its square root, by ER."}},{"itemId":"69156732-87b3-59c8-9819-72124ad86944","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4d8f22d1-0825-5612-9e34-6411eefca9e6","sourceKey":"bank:BUA216:RSK-071","parentItemId":null,"revision":1,"payload":{"prompt":"Share G: N16,000 (probability 0.25), N17,000 (0.5), N20,000 (0.25). Share H: N17,000 (probability 0.4), N23,000 (0.4), N26,000 (0.2). Taking variance as probability-weighted and CV = (SD / ER) x 100, which statement is correct?","options":["H has the higher CV (16.98% against 8.57%), so a risk-averse investor would choose H","G and H have the same CV, so the choice depends only on expected return","H has the higher CV (16.98% against 8.57%), so a risk taker would choose H","G has the higher CV (16.98% against 8.57%), so a risk taker would choose G"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"G: ER = 17,500, Var = 2,250,000, SD = 1,500, CV = 8.57%. H: ER = 21,200, Var = 12,960,000, SD = 3,600, CV = 16.98%. A risk taker selects the higher risk, which is H; a risk-averse investor would choose G, so option A is wrong."}},{"itemId":"930b4c25-0a3e-55cf-9ce9-23aecde9e2fe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4bbb3ea2-b56b-5dd3-9851-9c46d72165f1","sourceKey":"bank:BUA216:RSK-072","parentItemId":null,"revision":1,"payload":{"prompt":"An investment has three possible returns: N10,000 with probability 0.25, N16,000 with an unknown probability, and N22,000 with probability 0.35. Given that the probabilities of all outcomes must add up to 1, the expected return is","options":["N10,200","N15,800","N16,000","N16,600"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"The missing probability is 1 - 0.25 - 0.35 = 0.40, so ER = 0.25 x 10,000 + 0.40 x 16,000 + 0.35 x 22,000 = 2,500 + 6,400 + 7,700 = N16,600. Ignoring the middle outcome gives N10,200, and the simple average of the returns is N16,000."}},{"itemId":"35275bfa-e736-5e48-b666-bfc709ac01c1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ccd978a7-4d06-5bd2-976c-fcd6c4ae8299","sourceKey":"bank:BUA216:RSK-073","parentItemId":null,"revision":1,"payload":{"prompt":"A project has an expected return of N14,100. Its possible returns are N8,000 (probability 0.2), an unknown amount X (probability 0.5) and N20,000 (probability 0.3). The value of X is","options":["N14,300","N14,100","N6,500","N13,000"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"From ER = sum of P x R: 14,100 = 0.2 x 8,000 + 0.5X + 0.3 x 20,000 = 1,600 + 0.5X + 6,000, so 0.5X = 6,500 and X = N13,000. Stopping at 0.5X gives N6,500, and assuming X equals the expected return gives N14,100."}},{"itemId":"a809da88-7ef1-54c5-821b-9b57cf18353c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ff8ce332-2ca8-53c9-9be9-71f0083823c0","sourceKey":"bank:BUA216:RSK-074","parentItemId":null,"revision":1,"payload":{"prompt":"Analysts believe a share is equally likely to return 6%, 10%, 14% or 18% next year, so each return has a probability of 0.25. The expected return of the share is","options":["14.00%","10.00%","48.00%","12.00%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"ER = 0.25 x (6 + 10 + 14 + 18) = 0.25 x 48 = 12.00%. Forgetting to multiply by the probabilities gives 48.00%, and 10% or 14% are just individual outcomes, not the weighted average."}},{"itemId":"26b88f0b-3a76-511b-b1e8-f815f6b9f0e8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"91bd5b00-bd21-51a0-9065-23dfd7ac1261","sourceKey":"bank:BUA216:RSK-075","parentItemId":null,"revision":1,"payload":{"prompt":"A share is equally likely to return 6%, 10%, 14% or 18% (probability 0.25 each) and its expected return is 12%. Taking variance as the probability-weighted sum of P x (R - ER)^2, the standard deviation of the return, to 2 decimal places, is","options":["4.62%","4.47%","8.94%","20.00%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Var = 0.25 x (36 + 4 + 4 + 36) = 0.25 x 80 = 20, so SD = sqrt(20) = 4.47%. The figure 20.00% is the variance, 8.94% is sqrt(80) from forgetting the probabilities, and 4.62% is sqrt(80/3), a sample-style formula that does not use the given probabilities."}},{"itemId":"8b7f2a1a-644f-51dc-ac5a-f5b57c105d12","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7c0fc0e0-17f1-5698-a131-a48afd91d2eb","sourceKey":"bank:BUA216:RSK-076","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the range of an investment's returns as the highest possible return minus the lowest possible return, what is the range of a project whose possible returns are N9,000 (probability 0.3), N14,000 (probability 0.5) and N19,000 (probability 0.2)?","options":["N10,000","N13,500","N5,000","N14,000"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"Range = highest return - lowest return = 19,000 - 9,000 = N10,000; the probabilities are not used. N5,000 is the gap between adjacent outcomes only, and N13,500 is the expected return, not a measure of spread."}},{"itemId":"a379b00e-0a6f-580a-b62e-2d39ed5f62a4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0ecda80a-4074-5776-8496-1d70f1f12e5f","sourceKey":"bank:BUA216:RSK-077","parentItemId":null,"revision":1,"payload":{"prompt":"Taking range as the highest possible return minus the lowest possible return, Share S has possible returns of 4%, 12% and 30%, while Share T has possible returns of 10%, 15% and 21%. Using range as a rough measure of risk, which statement is correct?","options":["S has a range of 26% and T a range of 11%, so T appears riskier","S has a range of 26% and T a range of 11%, so S appears riskier","S has a range of 18% and T a range of 6%, so S appears riskier","Both shares have the same range, so they are equally risky"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Range(S) = 30 - 4 = 26% and Range(T) = 21 - 10 = 11%; a wider range means outcomes are more spread out, so S looks riskier. The 18% and 6% figures use the gap between only the top two outcomes."}},{"itemId":"e79aac51-ccde-5a86-993d-bd13f5343102","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"8878ba8e-a9eb-5571-8d05-480bdf126421","sourceKey":"bank:BUA216:RSK-078","parentItemId":null,"revision":1,"payload":{"prompt":"Ngozi bought a share for N1,200 and sold it one year later for N1,450, having received a dividend of N60 during the year. Taking holding period return = (selling price - buying price + dividend) / buying price x 100, her holding period return, to 2 decimal places, is","options":["5.00%","21.38%","20.83%","25.83%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"HPR = (1,450 - 1,200 + 60) / 1,200 x 100 = 310 / 1,200 x 100 = 25.83%. Leaving out the dividend gives 20.83%, dividing by the selling price gives 21.38%, and 5.00% is only the dividend yield."}},{"itemId":"826beda9-9b93-5d50-b001-c150bac0c06b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fd504fd3-f06a-5e54-be60-47d83bb06adf","sourceKey":"bank:BUA216:RSK-079","parentItemId":null,"revision":1,"payload":{"prompt":"An investor bought shares at N800 each, received a dividend of N40 per share, and sold them at N720 each. Taking holding period return = (selling price - buying price + dividend) / buying price x 100, the holding period return is","options":["-10.00%","-5.00%","15.00%","-5.56%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"HPR = (720 - 800 + 40) / 800 x 100 = -40 / 800 x 100 = -5.00%, a loss even after the dividend. Ignoring the dividend gives -10.00%, adding the price fall as a gain gives 15.00%, and dividing by the selling price gives -5.56%."}},{"itemId":"876fddb7-fc75-5431-8215-6b6045d2d67f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"69795385-289f-56b5-a7e4-ad0ed0437a68","sourceKey":"bank:BUA216:RSK-080","parentItemId":null,"revision":1,"payload":{"prompt":"Musa buys a share for N2,000 and expects a dividend of N90 during the year. Taking holding period return = (selling price - buying price + dividend) / buying price x 100, the selling price he needs at the end of the year to earn a holding period return of exactly 18% is","options":["N2,180","N2,270","N2,450","N2,360"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Required: (P - 2,000 + 90) / 2,000 = 0.18, so P - 1,910 = 360 and P = N2,270. Ignoring the dividend gives N2,360, and adding the dividend instead of subtracting it gives N2,450."}},{"itemId":"7c40bea0-298d-5e68-8e9a-e02f4810b062","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6dd529ac-cb16-57ef-8c1c-424fd5690438","sourceKey":"bank:BUA216:RSK-081","parentItemId":null,"revision":1,"payload":{"prompt":"An investor puts 60% of her funds in Share A, with an expected return of 16%, and 40% in Share B, with an expected return of 24%. Using PR = Wa x Ra + Wb x Rb, the expected return on the portfolio is","options":["19.20%","20.80%","20.00%","40.00%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"PR = 0.6 x 16% + 0.4 x 24% = 9.6% + 9.6% = 19.20%. A simple average of the two returns gives 20.00%, adding the returns gives 40.00%, and swapping the weights gives 0.4 x 16 + 0.6 x 24 = 20.80%."}},{"itemId":"9c4a01d5-a857-50e5-8d71-09dffc9fe6e6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1a351543-43a0-5583-86bc-021a2e67bdfc","sourceKey":"bank:BUA216:RSK-082","parentItemId":null,"revision":1,"payload":{"prompt":"Chidi invests N3,000,000 in Security X with an expected return of 12% and N2,000,000 in Security Y with an expected return of 22%. Using the weighted-average formula PR = Wx x Rx + Wy x Ry, the expected portfolio return is","options":["17.00%","34.00%","16.00%","18.00%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"The weights are 3m / 5m = 0.6 for X and 2m / 5m = 0.4 for Y, so PR = 0.6 x 12% + 0.4 x 22% = 7.2% + 8.8% = 16.00%. Using equal weights gives 17.00%, swapping the weights gives 18.00%, and adding the returns gives 34.00%."}},{"itemId":"732444a0-bdc1-5c23-af2f-0838d6688d25","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d9fcee15-7c9e-5e48-a82b-2bce5336dee2","sourceKey":"bank:BUA216:RSK-083","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund holds three securities: 50% in a bond fund expected to return 10%, 30% in Share P expected to return 15% and 20% in Share Q expected to return 20%. Using the general portfolio formula PR = sum of (weight x expected return), the expected portfolio return is","options":["13.50%","14.50%","15.00%","45.00%"],"correctOption":0,"section":"Analysis of Risk and Return","explanation":"PR = 0.5 x 10% + 0.3 x 15% + 0.2 x 20% = 5% + 4.5% + 4% = 13.50%. The simple average of the three returns is 15.00%, and adding them gives 45.00%."}},{"itemId":"d6d3f10b-1048-59db-a998-f454e51c53f6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0e5c6c0a-29bc-5803-8fc4-ec486cd0003b","sourceKey":"bank:BUA216:RSK-084","parentItemId":null,"revision":1,"payload":{"prompt":"Share K has an expected return of 14% and Share L has an expected return of 26%. Using PR = Wk x Rk + Wl x Rl with the weights adding up to 100%, what proportion of the portfolio must be invested in Share L to obtain an expected portfolio return of 20%?","options":["60%","50%","76.92%","40%"],"correctOption":1,"section":"Analysis of Risk and Return","explanation":"Let w be the weight in L: 14(1 - w) + 26w = 20, so 12w = 6 and w = 0.5, i.e. 50%. The figure 76.92% comes from 20 / 26, which ignores the return contributed by Share K, and 60% or 40% do not satisfy the equation (they give 21.2% and 18.8%)."}},{"itemId":"fe1677f0-c92b-5b58-859a-67b3024173ee","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2e52dbdc-c3c1-5975-8891-bd1a4fad93fb","sourceKey":"bank:BUA216:RSK-085","parentItemId":null,"revision":1,"payload":{"prompt":"Share Q returns 10%, 20% or 30% and Share R returns 30%, 10% or 5% in a boom, normal economy or recession respectively. The probabilities of boom, normal and recession are 0.3, 0.5 and 0.2. If an investor puts 50% in each share, using PR = Wq x E(Rq) + Wr x E(Rr), the expected portfolio return is","options":["15.00%","19.00%","17.50%","17.00%"],"correctOption":3,"section":"Analysis of Risk and Return","explanation":"E(Rq) = 0.3 x 10 + 0.5 x 20 + 0.2 x 30 = 19%, and E(Rr) = 0.3 x 30 + 0.5 x 10 + 0.2 x 5 = 15%, so PR = 0.5 x 19% + 0.5 x 15% = 17.00%. Using simple averages of each share's returns instead of probability-weighted ones gives 17.50%, while 19.00% and 15.00% are the individual shares' expected returns."}},{"itemId":"5547bc9a-dd54-555a-af88-2d7e7cc3b5d2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"84abc8f5-b2a4-52ae-bb1b-f8bf75668e62","sourceKey":"bank:BUA216:RSK-086","parentItemId":null,"revision":1,"payload":{"prompt":"Security U has a standard deviation of N2,400 on an expected return of N11,800, while Security V has a standard deviation of N2,800 on an expected return of N15,600. Using CV = (SD / ER) x 100 and rounding to 2 decimal places, a risk-averse investor should select","options":["Security U, because its standard deviation of N2,400 is lower","Security V, because its CV of 557.14% is higher than U's 491.67%","Security V, because its CV of 17.95% is lower than U's 20.34%","Security U, because its CV of 20.34% is higher than V's 17.95%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"CV(U) = 2,400 / 11,800 x 100 = 20.34% and CV(V) = 2,800 / 15,600 x 100 = 17.95%. V has less risk per naira of expected return, so a risk-averse investor chooses V. Option A relies on SD alone, which ignores the difference in expected returns, and option B inverts the formula."}},{"itemId":"de9a9dc8-ee10-5c1b-b596-bcc3eaec620c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fc85a258-0594-5caa-b1dc-3efa1c5a94aa","sourceKey":"bank:BUA216:RSK-087","parentItemId":null,"revision":1,"payload":{"prompt":"A security has a probability-weighted variance of returns of 2,890,000 (calculated as sum of P x (R - ER)^2) and an expected return of N8,500. Its standard deviation and coefficient of variation, CV = (SD / ER) x 100, are","options":["N1,700 and 500.00%","N2,890 and 34.00%","N1,700 and 20.00%","N1,445,000 and 17,000.00%"],"correctOption":2,"section":"Analysis of Risk and Return","explanation":"SD = sqrt(2,890,000) = N1,700, and CV = 1,700 / 8,500 x 100 = 20.00%. Inverting the CV formula gives 8,500 / 1,700 x 100 = 500%, and halving the variance instead of taking its square root gives the N1,445,000 figure."}},{"itemId":"0bb860db-b42b-58ea-bd6f-b3dcec98a839","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ab125b70-d02c-5da9-808c-e321d05ea50e","sourceKey":"bank:BUA216:WCM-001","parentItemId":null,"revision":1,"payload":{"prompt":"Ikeja Traders Ltd has stock of N450,000, debtors of N320,000, cash of N130,000 and trade creditors of N380,000. What is its working capital?","options":["N70,000","N520,000","N1,280,000","N900,000"],"correctOption":1,"section":"Working Capital Management","explanation":"Working capital is current assets less current liabilities: (450,000 + 320,000 + 130,000) - 380,000 = N520,000. Option D is only total current assets (the creditors were not deducted), Option C wrongly adds the creditors, and Option A leaves stock out of current assets."}},{"itemId":"c7d05707-5ae8-5426-b6fb-d2329b25cf41","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c9523982-a70f-59fa-bb18-8436c3be4fb8","sourceKey":"bank:BUA216:WCM-002","parentItemId":null,"revision":1,"payload":{"prompt":"Surulere Foods Ltd reports: stock N600,000; debtors N250,000; cash at bank N130,000; trade creditors N310,000; bank overdraft N120,000; accrued expenses N40,000. What is the company's working capital?","options":["N550,000","N630,000","N670,000","N510,000"],"correctOption":3,"section":"Working Capital Management","explanation":"Current assets total 600,000 + 250,000 + 130,000 = N980,000 and current liabilities total 310,000 + 120,000 + 40,000 = N470,000, so working capital is N510,000. Option C deducts only trade creditors, Option B forgets the bank overdraft and Option A forgets the accrued expenses; all three are current liabilities."}},{"itemId":"a05eab1b-612a-513f-a65b-bef5afb3646d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"aabf1867-05f0-5e05-8202-2e2ded12f8a0","sourceKey":"bank:BUA216:WCM-003","parentItemId":null,"revision":1,"payload":{"prompt":"Ajah Plastics Ltd has current assets of N2,400,000 and a current ratio of 1.6 : 1. What is its working capital?","options":["N900,000","N3,840,000","N1,440,000","N1,500,000"],"correctOption":0,"section":"Working Capital Management","explanation":"Current liabilities = current assets / current ratio = 2,400,000 / 1.6 = N1,500,000, so working capital = 2,400,000 - 1,500,000 = N900,000. Option D is the current liabilities figure, not working capital, while Option B multiplies by the ratio instead of dividing and Option C simply takes 60% of current assets."}},{"itemId":"d25ab429-da37-53ed-9503-28dd384c7a99","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5f36868e-8020-5939-b714-18c9e8c5e565","sourceKey":"bank:BUA216:WCM-004","parentItemId":null,"revision":1,"payload":{"prompt":"Oshodi Stores Ltd has working capital of N500,000. It then buys stock worth N200,000 on credit from a supplier. What is its working capital immediately after this purchase?","options":["N900,000","N300,000","N500,000","N700,000"],"correctOption":2,"section":"Working Capital Management","explanation":"Buying stock on credit raises current assets (stock) by N200,000 and current liabilities (creditors) by the same N200,000, so working capital = current assets - current liabilities stays at N500,000. Option D counts only the rise in stock and Option B counts only the rise in creditors."}},{"itemId":"3ca094f8-ca07-5ffc-89b9-acd2f469a5ac","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3b7d3960-c94c-50f4-908e-27f976325ac4","sourceKey":"bank:BUA216:WCM-005","parentItemId":null,"revision":1,"payload":{"prompt":"Yaba Electricals Ltd has current assets of N900,000 and current liabilities of N450,000. It uses N150,000 cash to pay trade creditors. What is the current ratio after the payment (to 2 decimal places)?","options":["1.50 : 1","2.50 : 1","1.67 : 1","2.00 : 1"],"correctOption":1,"section":"Working Capital Management","explanation":"After the payment current assets fall to 900,000 - 150,000 = N750,000 and current liabilities fall to 450,000 - 150,000 = N300,000, so the current ratio = 750,000 / 300,000 = 2.50 : 1. Option D is the old ratio, and Option C reduces cash but forgets that creditors also fell. Working capital itself stays at N450,000; only the ratio changes."}},{"itemId":"1207f286-9d9b-5f0b-b2a0-3b8f5ba3af9f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d2e2fd36-3e62-559e-9b3b-89a4a8083fd3","sourceKey":"bank:BUA216:WCM-006","parentItemId":null,"revision":1,"payload":{"prompt":"Apapa Distributors Ltd has stock of N360,000, debtors of N240,000, cash of N120,000 and current liabilities of N400,000. Taking the current ratio as current assets / current liabilities, what is its current ratio?","options":["0.56 : 1","1.80 : 1","0.90 : 1","1.50 : 1"],"correctOption":1,"section":"Working Capital Management","explanation":"Current assets = 360,000 + 240,000 + 120,000 = N720,000, so the current ratio = 720,000 / 400,000 = 1.80 : 1, a little below the ideal of 2 : 1. Option C is the acid test ratio (stock removed), Option D leaves out cash, and Option A turns the ratio upside down."}},{"itemId":"c5df1b19-52cc-583b-b3fa-8999c631b526","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a430ee63-2c28-5885-bbec-eaa74bbff237","sourceKey":"bank:BUA216:WCM-007","parentItemId":null,"revision":1,"payload":{"prompt":"Using the figures for a company with stock of N360,000, debtors of N240,000, cash of N120,000 and current liabilities of N400,000, what is the acid test (quick) ratio, taken as (current assets - stock) / current liabilities?","options":["0.60 : 1","0.90 : 1","0.30 : 1","1.80 : 1"],"correctOption":1,"section":"Working Capital Management","explanation":"The acid test ratio removes stock because it is the least liquid current asset: (720,000 - 360,000) / 400,000 = 0.90 : 1, just below the ideal of 1 : 1. Option D is the current ratio, Option A uses debtors only and Option C uses cash only."}},{"itemId":"cc4158a8-aca9-5447-931c-e99e4ef36948","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1f6febe4-f30a-5254-9880-9d092782ec65","sourceKey":"bank:BUA216:WCM-008","parentItemId":null,"revision":1,"payload":{"prompt":"Kano Textiles Ltd made credit sales of N7,300,000 during the year and has trade debtors of N1,200,000 at the year end. Using a 365-day year, what is its average collection period (to the nearest day)?","options":["60 days","59 days","6 days","2,220 days"],"correctOption":0,"section":"Working Capital Management","explanation":"Average collection period = trade debtors x 365 / credit sales = 1,200,000 x 365 / 7,300,000 = 60 days. Option B uses a 360-day year, which is only correct when a question states it, Option C is the debtors turnover (about 6.08 times) read as days, and Option D turns the formula upside down."}},{"itemId":"82401fce-6717-5016-85cb-d1824c4c3c6d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4d56be00-53bf-50a4-a8ed-1f96e845a829","sourceKey":"bank:BUA216:WCM-009","parentItemId":null,"revision":1,"payload":{"prompt":"Aba Shoes Ltd made credit purchases of N4,380,000 in the year and owes trade creditors N540,000 at the year end. Using a 365-day year, what is its average payment period (to the nearest day)?","options":["44 days","8 days","2,961 days","45 days"],"correctOption":3,"section":"Working Capital Management","explanation":"Average payment period = trade creditors x 365 / credit purchases = 540,000 x 365 / 4,380,000 = 45 days. Option A uses 360 days instead of 365, Option B is the creditors turnover (about 8.1 times) and Option C inverts the formula."}},{"itemId":"29b3a1d8-904a-5f4d-91d5-05e5edb61589","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6b3be5a3-024e-5ad9-996a-a7752bc74dca","sourceKey":"bank:BUA216:WCM-010","parentItemId":null,"revision":1,"payload":{"prompt":"Onitsha Hardware Ltd had opening stock of N240,000, closing stock of N360,000 and cost of sales of N2,400,000. Taking stock turnover as cost of sales / average stock, where average stock = (opening + closing) / 2, what is its stock turnover?","options":["6.67 times","4 times","8 times","10 times"],"correctOption":2,"section":"Working Capital Management","explanation":"Average stock = (240,000 + 360,000) / 2 = N300,000, so stock turnover = 2,400,000 / 300,000 = 8 times. Option A uses closing stock only and Option D uses opening stock only, while Option B divides by the total of opening and closing stock without halving it."}},{"itemId":"fd436f60-450e-57b4-be64-51ea48d601c2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4120c253-c8dc-5816-a1ce-cdab75bddf8a","sourceKey":"bank:BUA216:WCM-011","parentItemId":null,"revision":1,"payload":{"prompt":"Ibadan Paints Ltd had opening stock of N240,000, closing stock of N360,000 and cost of sales of N2,190,000. Taking the stock holding period as average stock x 365 / cost of sales, where average stock = (opening + closing) / 2, how many days is stock held on average?","options":["60 days","50 days","7.3 days","40 days"],"correctOption":1,"section":"Working Capital Management","explanation":"Average stock is (240,000 + 360,000) / 2 = N300,000, so the holding period = 300,000 x 365 / 2,190,000 = 50 days. Option A uses closing stock instead of average stock and Option C is the stock turnover (7.3 times) mislabelled as days."}},{"itemId":"7cdb988d-85cf-5c45-9438-5c5c9c0296f6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a78f73fb-4732-57fb-90c6-8279ff426060","sourceKey":"bank:BUA216:WCM-012","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the operating (working capital) cycle as stock holding period + debtors collection period - creditors payment period, what is the cycle for a firm that holds stock for 50 days, collects from debtors in 40 days and pays creditors in 35 days?","options":["125 days","55 days","90 days","45 days"],"correctOption":1,"section":"Working Capital Management","explanation":"The cycle measures how long cash is tied up: 50 + 40 - 35 = 55 days, because credit from suppliers shortens the time the firm's own money is locked in. Option A adds the creditors period instead of subtracting it, Option C ignores creditors altogether and Option D subtracts the debtors period and adds the creditors period."}},{"itemId":"dc8e163d-43f1-54aa-92b1-e30544bec42c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"917e5d12-e003-51a2-9ad2-89052e6808b8","sourceKey":"bank:BUA216:WCM-013","parentItemId":null,"revision":1,"payload":{"prompt":"Benin Biscuits Ltd: average stock N400,000; cost of sales N3,650,000; trade debtors N900,000; credit sales N5,475,000; trade creditors N500,000; credit purchases N3,650,000. Using a 365-day year and taking the operating cycle as stock days + debtor days - creditor days, what is the operating cycle?","options":["150 days","50 days","70 days","100 days"],"correctOption":1,"section":"Working Capital Management","explanation":"Stock days = 400,000 x 365 / 3,650,000 = 40; debtor days = 900,000 x 365 / 5,475,000 = 60; creditor days = 500,000 x 365 / 3,650,000 = 50. Operating cycle = 40 + 60 - 50 = 50 days. Option A adds the creditor days, Option D leaves them out, and Option C swaps the roles of stock and creditors."}},{"itemId":"1c788e60-a01d-555b-aa79-8925d5209934","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a2734679-6582-546d-8801-177ddb10a467","sourceKey":"bank:BUA216:WCM-014","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer holds raw materials for 20 days, production (work in progress) takes 10 days, finished goods are held for 15 days, debtors take 45 days to pay and suppliers allow 30 days' credit. Taking the working capital cycle as the sum of the stock and debtor periods less the creditor period, how long is the cycle?","options":["45 days","60 days","90 days","120 days"],"correctOption":1,"section":"Working Capital Management","explanation":"Add every stage from cash to raw inputs through to debtors back to cash, then deduct supplier credit: 20 + 10 + 15 + 45 - 30 = 60 days. Option D adds the 30 days of supplier credit, Option C ignores it, and Option A counts only the three stock stages."}},{"itemId":"c7e0278b-13f6-5389-9f40-f2d270cd2ada","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0410373a-b9b2-5bbf-be5a-1da8c2cdf7e4","sourceKey":"bank:BUA216:WCM-015","parentItemId":null,"revision":1,"payload":{"prompt":"Ogun Ceramics Ltd has an operating cycle of 73 days and annual operating costs of N10,000,000, incurred evenly. Using a 365-day year and taking the working capital required as annual operating cost / number of operating cycles in a year, how much working capital does it need?","options":["N136,986","N1,000,000","N50,000,000","N2,000,000"],"correctOption":3,"section":"Working Capital Management","explanation":"The number of cycles in a year is 365 / 73 = 5, so working capital required = 10,000,000 / 5 = N2,000,000. Option C multiplies by the number of cycles instead of dividing, Option B wrongly halves the requirement as if it were an average balance, and Option A divides by the cycle length in days instead of by the number of cycles."}},{"itemId":"5fe41d02-86f9-5230-b423-e8a818d36d84","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4c632261-367d-527d-8a5a-3ef60edd2699","sourceKey":"bank:BUA216:WCM-016","parentItemId":null,"revision":1,"payload":{"prompt":"Ilorin Bottlers Ltd uses 24,000 units of a component a year. Each order costs N250 to place and carrying cost is N12 per unit per annum. Using EOQ = square root of (2 x D x OC / CC), what is the economic order quantity?","options":["707 units","1,414 units","1,000,000 units","1,000 units"],"correctOption":3,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 24,000 x 250 / 12) = square root of 1,000,000 = 1,000 units; check: ordering cost (24 orders x N250 = N6,000) equals carrying cost (500 x N12 = N6,000). Option A forgets the 2 in the formula, Option B halves the carrying cost, and Option C forgets to take the square root."}},{"itemId":"8d635dd9-0432-5e13-a062-a13b4aa9e344","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c440afdc-e949-55d1-8d9a-1a8290fa2785","sourceKey":"bank:BUA216:WCM-017","parentItemId":null,"revision":1,"payload":{"prompt":"Calabar Cement Ltd has annual demand of 72,000 bags, an ordering cost of N400 per order and a carrying cost of N16 per bag per annum. What is the economic order quantity, to the nearest bag?","options":["3,600,000 bags","1,897 bags","2,683 bags","1,342 bags"],"correctOption":1,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 72,000 x 400 / 16) = square root of 3,600,000 = 1,897 bags (about 1,897.37). At this quantity ordering and carrying costs are equal, about N15,179 each. Option D drops the 2, Option C halves the carrying cost, and Option A omits the square root."}},{"itemId":"881a9558-ced0-5299-94ae-c08f10ea249a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"45f80917-bea1-5a36-9a71-08d319d012db","sourceKey":"bank:BUA216:WCM-018","parentItemId":null,"revision":1,"payload":{"prompt":"Owerri Pharma Ltd needs 40,000 units a year. Each unit costs N50, each order costs N300, and the annual carrying cost is 20% of the purchase price per unit. What is the economic order quantity, to the nearest unit?","options":["10,954 units","1,095 units","1,549 units","632 units"],"correctOption":2,"section":"Working Capital Management","explanation":"First convert the carrying cost to naira: 20% x N50 = N10 per unit per annum. EOQ = square root of (2 x 40,000 x 300 / 10) = 1,549 units. Option B uses N20 as the carrying cost, Option A divides by 0.2 instead of N10, and Option D swaps the ordering cost with the unit price."}},{"itemId":"22d82bd0-ba91-5e67-ac35-8a7b1ac5f97d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a6d6b239-3a1c-581b-8083-9259690d2fac","sourceKey":"bank:BUA216:WCM-019","parentItemId":null,"revision":1,"payload":{"prompt":"Jos Dairy Ltd has annual demand of 45,000 units, ordering cost of N600 per order and carrying cost of N24 per unit per annum. How many orders will it place in a year if it buys the economic order quantity each time?","options":["30 orders","42 orders","15 orders","60 orders"],"correctOption":0,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 45,000 x 600 / 24) = 1,500 units, and number of orders = D / EOQ = 45,000 / 1,500 = 30. Option D divides demand by half the EOQ (the average stock), Option C divides by double the EOQ, and Option B comes from forgetting the 2 in the EOQ formula (EOQ of about 1,061)."}},{"itemId":"acf5e5a7-4bf0-5152-8e5e-968828bd3373","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f7358de1-c9ef-50be-a627-16384f4747bc","sourceKey":"bank:BUA216:WCM-020","parentItemId":null,"revision":1,"payload":{"prompt":"A firm has annual demand of 45,000 units, an EOQ of 1,500 units and an ordering cost of N600 per order. What is its total annual ordering cost when it orders the EOQ?","options":["N18,000","N36,000","N9,000","N27,000,000"],"correctOption":0,"section":"Working Capital Management","explanation":"Total ordering cost = (D / Q) x OC = (45,000 / 1,500) x 600 = 30 x 600 = N18,000. Option B is ordering plus carrying cost together, Option D multiplies annual demand by the cost per order, and Option C wrongly halves the ordering cost as if it were carrying cost."}},{"itemId":"fee805c6-976f-577d-b85a-c7aabb7b6e79","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b233640d-b058-5604-9e73-c8476d445243","sourceKey":"bank:BUA216:WCM-021","parentItemId":null,"revision":1,"payload":{"prompt":"Sokoto Grains Ltd uses 9,600 bags a year, with ordering cost of N150 per order and carrying cost of N8 per bag per annum. What is the total annual carrying cost when it orders the economic order quantity?","options":["N4,800","N1,200","N38,400","N2,400"],"correctOption":3,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 9,600 x 150 / 8) = 600 bags, so total carrying cost = (Q / 2) x CC = 300 x 8 = N2,400, which matches the ordering cost of 16 orders x N150 = N2,400. Option A forgets that average stock is half the order quantity, and Option C applies the carrying cost to half of annual demand."}},{"itemId":"6fc89c50-ccb5-5954-b452-2a975eb2f487","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"0930bf5e-ccd0-5be3-b25f-4be5c9b15c8f","sourceKey":"bank:BUA216:WCM-022","parentItemId":null,"revision":1,"payload":{"prompt":"Akure Cocoa Ltd has annual demand of 20,000 units, ordering cost of N400 per order, carrying cost of N4 per unit per annum and a purchase price of N30 per unit. Taking the controllable cost as total ordering cost + total carrying cost, what is the controllable cost at the EOQ?","options":["N12,000","N8,000","N4,000","N608,000"],"correctOption":1,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 20,000 x 400 / 4) = 2,000 units. Total ordering cost = 10 x 400 = N4,000 and total carrying cost = 1,000 x 4 = N4,000, so controllable cost = N8,000. Option C counts only one of the two costs, Option D also adds the purchase cost, which EOQ cannot reduce, and Option A charges carrying cost on the full 2,000 units."}},{"itemId":"399e9719-0210-5229-b3f5-b22588ed058a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"15414e41-c905-50a4-a771-1e96ee6a7155","sourceKey":"bank:BUA216:WCM-023","parentItemId":null,"revision":1,"payload":{"prompt":"Warri Fisheries Ltd buys 16,200 cartons a year at N25 each. Ordering cost is N100 per order and carrying cost is N4 per carton per annum. Taking total stock cost as total ordering cost + total carrying cost + total purchase cost, what is the total cost at the EOQ?","options":["N410,400","N408,600","N405,000","N3,600"],"correctOption":1,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x 16,200 x 100 / 4) = 900 cartons. Ordering cost = 18 x 100 = N1,800, carrying cost = 450 x 4 = N1,800 and purchase cost = 16,200 x 25 = N405,000, giving N408,600. Option C is purchase cost alone, Option D is only the controllable part, and Option A forgets to halve the EOQ when finding carrying cost."}},{"itemId":"78f897a0-f2e4-5c71-90c6-80ec6733415b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"289e0a37-3ca3-5543-a721-d5acdb50f3c6","sourceKey":"bank:BUA216:WCM-024","parentItemId":null,"revision":1,"payload":{"prompt":"Lokoja Steel Ltd needs 15,000 units of a part a year. The purchase price is N60 per unit and each order costs N500 to place. What is the total annual purchase cost of the part?","options":["N900,000","N30,000","N900,500","N7,500,000"],"correctOption":0,"section":"Working Capital Management","explanation":"Total purchase cost = purchase price per unit x annual demand = 60 x 15,000 = N900,000. Option D multiplies demand by the ordering cost, a common mix-up when both figures are given close together, Option B multiplies the two costs together, and Option C adds one order cost to the purchase cost."}},{"itemId":"8e6746e1-c5ec-5392-a136-6648332df343","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fe2120e5-710a-5eef-9370-dae980676f02","sourceKey":"bank:BUA216:WCM-025","parentItemId":null,"revision":1,"payload":{"prompt":"A company's EOQ is 800 units. Annual demand is 64,000 units and carrying cost is N20 per unit per annum. Using EOQ = square root of (2 x D x OC / CC), what must the ordering cost per order be?","options":["N200","N50","N100","N400"],"correctOption":2,"section":"Working Capital Management","explanation":"Squaring the formula gives OC = EOQ^2 x CC / (2 x D) = 640,000 x 20 / 128,000 = N100. Check: 80 orders x N100 = N8,000 equals 400 x N20 = N8,000. Option A forgets the 2 in the denominator, and the other two figures double or quadruple the error."}},{"itemId":"957aef2c-85dc-50ea-bb04-98be99172bbe","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f00e7b22-37d0-5b6f-a286-45c3b68888df","sourceKey":"bank:BUA216:WCM-026","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's EOQ is 1,200 units when annual demand is 30,000 units. If annual demand rises to 120,000 units while ordering and carrying costs per unit stay the same, what is the new EOQ?","options":["1,697 units","1,200 units","4,800 units","2,400 units"],"correctOption":3,"section":"Working Capital Management","explanation":"EOQ moves with the square root of demand. Demand has risen 4 times, so EOQ rises by the square root of 4 = 2, giving 2 x 1,200 = 2,400 units. Option C assumes EOQ rises in proportion to demand, Option B assumes it does not change, and Option A multiplies by the square root of 2."}},{"itemId":"faa00ec8-c651-50bf-836d-271464b1f145","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6f0bdacb-b74c-57d8-99a4-b5def4ff5a4e","sourceKey":"bank:BUA216:WCM-027","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's EOQ is 900 units. If both the ordering cost per order and the carrying cost per unit double, with demand unchanged, what is the new EOQ?","options":["900 units","1,800 units","450 units","1,273 units"],"correctOption":0,"section":"Working Capital Management","explanation":"EOQ = square root of (2 x D x OC / CC); doubling both OC and CC leaves the fraction OC / CC unchanged, so the EOQ stays at 900 units. Option B reacts only to the higher ordering cost, Option D multiplies by the square root of 2, and Option C reacts only to the higher carrying cost."}},{"itemId":"e25644c0-db23-5dc7-ab2d-ec797d622a93","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"46deae87-1413-57c8-a09d-b442c43cb3fc","sourceKey":"bank:BUA216:WCM-028","parentItemId":null,"revision":1,"payload":{"prompt":"A company orders its economic order quantity and finds that its total annual ordering cost is N45,000. With no safety stock, what is its total annual carrying cost?","options":["N90,000","N45,000","N22,500","N135,000"],"correctOption":1,"section":"Working Capital Management","explanation":"At the economic order quantity, total ordering cost equals total carrying cost, so carrying cost is also N45,000 and the controllable cost is N90,000. Option A is that controllable total, not the carrying cost, and Option C wrongly halves the figure."}},{"itemId":"fb31711c-c71e-5129-824b-166a843d8a73","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"24ce33cc-f511-5633-9670-9bf9db9529f6","sourceKey":"bank:BUA216:WCM-029","parentItemId":null,"revision":1,"payload":{"prompt":"At its EOQ, a firm's total ordering cost plus total carrying cost is N30,000. The carrying cost is N15 per unit per annum. What is the EOQ?","options":["4,000 units","1,414 units","1,000 units","2,000 units"],"correctOption":3,"section":"Working Capital Management","explanation":"At the EOQ the two costs are equal, so carrying cost = 30,000 / 2 = N15,000. Since carrying cost = (Q / 2) x 15, Q / 2 = 1,000 and Q = 2,000 units. Option C is the average stock (Q / 2), and Option A sets the whole N30,000 equal to carrying cost."}},{"itemId":"c64d7482-97fb-582e-b9b4-80dd379221c1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"713ac91c-0568-5c91-93f3-0029deb58b95","sourceKey":"bank:BUA216:WCM-030","parentItemId":null,"revision":1,"payload":{"prompt":"A retailer orders 2,400 units each time (its EOQ) and also keeps a safety stock of 300 units. Assuming steady usage, what is its average stock level?","options":["2,700 units","1,200 units","1,350 units","1,500 units"],"correctOption":3,"section":"Working Capital Management","explanation":"Average stock = (order quantity / 2) + safety stock = 1,200 + 300 = 1,500 units, because the safety stock sits underneath the normal saw-tooth pattern of stock. Option B ignores the safety stock, Option A adds the safety stock to the full order quantity, and Option C halves the safety stock as well."}},{"itemId":"00d9a63f-3a9f-5b9b-b63e-5fe1a2c3aa96","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5709532c-2c91-55ad-a169-4c1f17b37ae3","sourceKey":"bank:BUA216:WCM-031","parentItemId":null,"revision":1,"payload":{"prompt":"Port Harcourt Oil Services needs 50,000 units a year and orders 1,200 units each time. How many orders does it place in a year, to the nearest whole order?","options":["21 orders","83 orders","24 orders","42 orders"],"correctOption":3,"section":"Working Capital Management","explanation":"Number of orders = D / Q = 50,000 / 1,200 = 41.67, which rounds to 42 orders. Option A divides by twice the order quantity, Option B divides by half the order quantity (the average stock), and Option C confuses the 1,200 and 50,000 in the division."}},{"itemId":"c64303bc-ae4b-5adb-96d1-73516927a2fb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6127e99c-77b1-5804-9f3a-cbe387f80461","sourceKey":"bank:BUA216:WCM-032","parentItemId":null,"revision":1,"payload":{"prompt":"Maiduguri Feeds Ltd uses 36,500 bags a year and orders 1,825 bags each time. Using a 365-day year, how many days are there between orders?","options":["20 days","36.50 days","18.25 days","9.13 days"],"correctOption":2,"section":"Working Capital Management","explanation":"Number of orders = 36,500 / 1,825 = 20 a year, so the interval between orders = 365 / 20 = 18.25 days. Option A is the number of orders, not days, Option D halves the interval, and Option B doubles it."}},{"itemId":"4e69f415-4691-54bb-bfd9-f50e4bb60468","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"630ae9d7-d38f-5e3b-845f-2c64be4f48b1","sourceKey":"bank:BUA216:WCM-033","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery uses 120 bags of flour a day and its supplier takes 8 days to deliver after an order is placed. With no safety stock, at what stock level should it reorder?","options":["15 bags","960 bags","1,920 bags","128 bags"],"correctOption":1,"section":"Working Capital Management","explanation":"Reorder level = daily usage x lead time = 120 x 8 = 960 bags, so a new delivery arrives just as stock runs out. Option A divides instead of multiplying, Option C doubles the lead time, and Option D adds the two figures."}},{"itemId":"a4c208bf-e184-5930-b931-93649953d012","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a2e5a80a-a0d7-5b1d-8426-574ca21f9421","sourceKey":"bank:BUA216:WCM-034","parentItemId":null,"revision":1,"payload":{"prompt":"Kaduna Textiles uses 250 metres of fabric a day, lead time is 6 days, and it keeps a safety stock of 400 metres. What is its reorder level?","options":["2,300 metres","1,900 metres","1,100 metres","1,500 metres"],"correctOption":1,"section":"Working Capital Management","explanation":"Reorder level = (daily usage x lead time) + safety stock = 250 x 6 + 400 = 1,900 metres. Option D ignores the safety stock, Option C deducts it instead of adding it, and Option A counts it twice."}},{"itemId":"453bc9e3-6233-5eab-8460-96e25f64d09b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"43b47353-f041-55df-8de4-28e4b0dfc74e","sourceKey":"bank:BUA216:WCM-035","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the reorder level as maximum usage x maximum lead time, find the reorder level for a firm whose usage ranges from 150 to 300 units a day (average 200) and whose lead time ranges from 5 to 10 days (average 7).","options":["1,400 units","2,000 units","2,100 units","3,000 units"],"correctOption":3,"section":"Working Capital Management","explanation":"Using the worst case protects against stock-outs: 300 units x 10 days = 3,000 units. Option A uses average usage and average lead time, Option C uses maximum usage with average lead time, and Option B uses average usage with maximum lead time."}},{"itemId":"60b2b295-321b-5ced-933b-7d3797083e6c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e89e2b59-d15e-5c0f-a3ae-4ae817860807","sourceKey":"bank:BUA216:WCM-036","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's reorder level is 3,000 units, average usage is 200 units a day and average lead time is 7 days. Taking the minimum stock level as reorder level - (average usage x average lead time), what is the minimum level?","options":["1,400 units","1,600 units","2,800 units","4,400 units"],"correctOption":1,"section":"Working Capital Management","explanation":"Minimum level = 3,000 - (200 x 7) = 3,000 - 1,400 = 1,600 units, the level below which stock should not normally fall. Option A is only the average usage during the lead time, Option D adds instead of subtracting, and Option C subtracts only 200 units."}},{"itemId":"157ccdea-7d55-5896-b269-a9e14186417c","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ba7672fc-5917-550f-b400-d74b7c39b895","sourceKey":"bank:BUA216:WCM-037","parentItemId":null,"revision":1,"payload":{"prompt":"Taking the maximum stock level as reorder level + reorder quantity - (minimum usage x minimum lead time), find the maximum level for a firm with a reorder level of 3,000 units, reorder quantity of 2,500 units, minimum usage of 150 units a day and minimum lead time of 5 days.","options":["4,750 units","5,500 units","6,250 units","2,250 units"],"correctOption":0,"section":"Working Capital Management","explanation":"Maximum level = 3,000 + 2,500 - (150 x 5) = 5,500 - 750 = 4,750 units. Option C adds the 750 instead of subtracting it, Option B forgets to subtract it at all, and Option D leaves out the reorder quantity."}},{"itemId":"0ca26568-cda4-56c9-b604-e7b3983fa8b9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"deb7cae0-6021-5659-9953-73cbcfdc9070","sourceKey":"bank:BUA216:WCM-038","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier offers credit terms of 2/10 net 30. Using Cost = [% discount / (100 - % discount)] x [365 / (maximum payment period - discount period)], what is the annual cost of not taking the discount (to 2 decimal places)?","options":["24.83%","74.49%","36.50%","37.24%"],"correctOption":3,"section":"Working Capital Management","explanation":"Cost = (2 / 98) x (365 / (30 - 10)) = 0.020408 x 18.25 = 37.24%. Option C divides by 100 instead of 98, Option A uses the full 30 days instead of the extra 20 days of credit, and Option B uses the 10-day discount period as the gap."}},{"itemId":"71d13158-e3b7-5b2c-bab1-f3f81d54e056","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"59bce6ae-7163-58fd-ad30-3939e7c99841","sourceKey":"bank:BUA216:WCM-039","parentItemId":null,"revision":1,"payload":{"prompt":"Credit terms are 1/10 net 40. Using a 365-day year, what is the annual cost of forgoing the cash discount (to 2 decimal places)?","options":["36.87%","12.17%","12.29%","9.22%"],"correctOption":2,"section":"Working Capital Management","explanation":"Cost = (1 / 99) x (365 / (40 - 10)) = (1 / 99) x 12.17 = 12.29%. Option D divides 365 by 40 instead of by the 30 extra days, Option B divides the discount by 100 instead of 99, and Option A divides 365 by the 10-day discount period."}},{"itemId":"4b3241c3-6927-500a-a8d4-d460e1271cbf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dce085e2-7992-5d36-ab41-4cc70dbfb449","sourceKey":"bank:BUA216:WCM-040","parentItemId":null,"revision":1,"payload":{"prompt":"Gombe Agro Ltd buys on terms of 3/15 net 60. Using a 365-day year, what is the annual cost of not taking the discount (to 2 decimal places)?","options":["25.09%","18.81%","75.26%","24.33%"],"correctOption":0,"section":"Working Capital Management","explanation":"Cost = (3 / 97) x (365 / (60 - 15)) = 0.030928 x 8.111 = 25.09%. Option B uses 60 days instead of the 45-day gap, Option D uses 100 instead of 97 in the first bracket, and Option C uses the 15-day discount period as the gap."}},{"itemId":"aadd1b23-dfa7-5456-8680-742592d5fc0b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"20f3a666-f22b-5483-b1b4-d74d5cbd846b","sourceKey":"bank:BUA216:WCM-041","parentItemId":null,"revision":1,"payload":{"prompt":"A company operating a 360-day year is offered credit terms of 2/10 net 60. What is the annual cost of not taking the discount (to 2 decimal places)?","options":["12.24%","14.90%","14.40%","14.69%"],"correctOption":3,"section":"Working Capital Management","explanation":"With the stated 360-day year, cost = (2 / 98) x (360 / (60 - 10)) = (2 / 98) x 7.2 = 14.69%. Option B uses 365 days even though the question states 360, Option A divides by 60 instead of the 50-day gap, and Option C divides by 100 instead of 98."}},{"itemId":"d65bc3dd-2f73-5fc9-abb2-6dc8b2ecc80f","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"418a3c50-aec8-58d0-8e01-2ecbdfb2ac47","sourceKey":"bank:BUA216:WCM-042","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 360-day year, what is the annual cost of not taking advantage of credit terms of 4/10 net 50 (to 2 decimal places)?","options":["36.00%","38.02%","30.00%","37.50%"],"correctOption":3,"section":"Working Capital Management","explanation":"Cost = (4 / 96) x (360 / (50 - 10)) = 0.041667 x 9 = 37.50%. Option B uses 365 days although 360 is stated, Option C divides by 50 days instead of 40, and Option A divides the discount by 100 instead of 96."}},{"itemId":"6ff86483-32bd-56cc-9d19-f3104c7a512a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6c5cbf6a-5f6e-54cc-9562-f077133f135d","sourceKey":"bank:BUA216:WCM-043","parentItemId":null,"revision":1,"payload":{"prompt":"Enugu Furniture Ltd can buy timber on terms of 2/10 net 40 or borrow from its bank at 18% a year to pay early. Using a 365-day year, what should it do?","options":["Forgo the discount, because the bank rate of 18% is higher than the 2% discount","Borrow at 18% and take the discount, because forgoing it costs about 24.83% a year","Borrow and take the discount, because forgoing it costs about 74.49% a year","Forgo the discount, because its annual cost is only about 0.17%"],"correctOption":1,"section":"Working Capital Management","explanation":"Cost of forgoing = (2 / 98) x (365 / 30) = 24.83%, which is more than the 18% bank rate, so borrowing to pay on day 10 is cheaper. Option A compares an annual rate with a 2% charge for only 30 days, Option D turns the day fraction upside down (30 / 365 instead of 365 / 30), and Option C reaches the right decision with the wrong figure (it uses the 10-day discount period)."}},{"itemId":"5f0a0537-06af-5e3e-863a-a71d8e0cc994","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3344b90c-0862-5ad1-9395-a7d5cd58172d","sourceKey":"bank:BUA216:WCM-044","parentItemId":null,"revision":1,"payload":{"prompt":"Using a 365-day year, which of the following credit terms carries the HIGHEST annual cost of not taking the discount?","options":["1/10 net 30","3/30 net 90","2/15 net 45","2/10 net 60"],"correctOption":2,"section":"Working Capital Management","explanation":"Using Cost = [d / (100 - d)] x [365 / (MPP - discount period)]: 2/15 net 45 gives (2/98) x (365/30) = 24.83%, 1/10 net 30 gives 18.43%, 2/10 net 60 gives 14.90% and 3/30 net 90 gives 18.81%. A bigger discount does not always mean a higher cost; what matters is the discount relative to the number of extra days of credit."}},{"itemId":"1e3d2e2a-3b5d-53f4-a1c6-9d05b6fe9888","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"43ceb20f-74f8-5799-b437-0e054921af42","sourceKey":"bank:BUA216:WCM-045","parentItemId":null,"revision":1,"payload":{"prompt":"Ife Crafts Ltd receives an invoice for N500,000 on terms of 2/10 net 30 and pays on day 8. How much does it pay?","options":["N500,000","N490,000","N499,000","N510,000"],"correctOption":1,"section":"Working Capital Management","explanation":"Paying within the 10-day discount period earns the 2% discount: 500,000 - (2% x 500,000) = N490,000. Option A ignores the discount, Option D adds 2% as if it were a penalty, and Option C takes only 0.2% off."}},{"itemId":"662775b1-5729-5dd3-8195-7c1e0c8ca229","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1efed1b4-49b5-5057-ab2d-cac9fdcd6bc1","sourceKey":"bank:BUA216:WCM-046","parentItemId":null,"revision":1,"payload":{"prompt":"A distributor plans to change its credit terms from net 30 to 3/10 net 30. Using a 365-day year, what is the annual cost of the new credit policy to the distributor (to 2 decimal places)?","options":["54.75%","37.63%","56.44%","55.67%"],"correctOption":2,"section":"Working Capital Management","explanation":"Cost = (3 / 97) x (365 / (30 - 10)) = 0.030928 x 18.25 = 56.44%. Option D uses a 360-day year (about 55.67%), which is only right when the question states it, Option A divides by 100 instead of 97, and Option B divides 365 by 30 instead of the 20-day gap."}},{"itemId":"4c8e1a38-f415-568a-a6fc-31f323e5b54b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"de7a65cf-7886-5fa2-9a6f-690891553080","sourceKey":"bank:BUA216:WCM-047","parentItemId":null,"revision":1,"payload":{"prompt":"Credit terms are 2/10 net 45. Using a 365-day year, what is the cost of not taking advantage of the cash discount, to 2 decimal places?","options":["21.28%","74.49%","20.86%","16.55%"],"correctOption":0,"section":"Working Capital Management","explanation":"Cost = (2 / 98) x (365 / (45 - 10)) = (2 / 98) x 10.43 = 21.28%, about 21%. Option C uses 100 instead of 98 in the first bracket, Option D divides 365 by 45 instead of 35, and Option B divides 365 by the 10-day discount period."}},{"itemId":"eff6b01e-8f4a-50ad-86eb-2a031a333e00","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d7f24000-9547-50a9-a350-84ba692bf2ff","sourceKey":"bank:BUA216:WCM-048","parentItemId":null,"revision":1,"payload":{"prompt":"Lekki Ventures has an opening cash balance of N250,000 for March. It expects cash receipts from sales of N1,400,000, payments for purchases of N1,150,000 and other cash expenses of N180,000. What is the expected closing cash balance?","options":["N500,000","N70,000","N320,000","N180,000"],"correctOption":2,"section":"Working Capital Management","explanation":"Closing balance = opening balance + receipts - payments = 250,000 + 1,400,000 - 1,150,000 - 180,000 = N320,000. Option A forgets the other cash expenses, Option B forgets the opening balance, and Option D reverses the signs of receipts and payments."}},{"itemId":"e9f3fdf5-c0dc-543b-baf2-379a26b62e1d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4ebe49ec-5002-5680-8203-ec4564e937a2","sourceKey":"bank:BUA216:WCM-049","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's cash balance at 1 January is N100,000. Expected receipts are N600,000 in January and N750,000 in February; expected payments are N720,000 in January and N640,000 in February. What is the expected closing cash balance at the end of February?","options":["N210,000","N110,000","-N20,000","N90,000"],"correctOption":3,"section":"Working Capital Management","explanation":"January closes at 100,000 + 600,000 - 720,000 = -N20,000 (an overdraft), which becomes February's opening balance: -20,000 + 750,000 - 640,000 = N90,000. Option C is the January closing figure, Option B ignores the balance brought forward, and Option A skips January entirely."}},{"itemId":"43508cc0-7958-52e4-a259-ecbc610459dc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e59dd5d2-309c-5205-a3a7-0c66ab852e14","sourceKey":"bank:BUA216:WCM-050","parentItemId":null,"revision":1,"payload":{"prompt":"Bauchi Wholesalers' sales are N400,000 in January, N500,000 in February and N600,000 in March. 30% of sales are for cash and the remaining 70% are collected in the month after sale. What are total cash receipts from sales in March?","options":["N600,000","N350,000","N570,000","N530,000"],"correctOption":3,"section":"Working Capital Management","explanation":"March receipts = 30% of March sales + 70% of February sales = 180,000 + 350,000 = N530,000. Option C applies the percentages to the wrong months, Option A treats all March sales as cash received in March, and Option B counts only the collections from February."}},{"itemId":"77fc4403-6180-589b-96ca-18ce3fbb391e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"04de3160-9bec-56ed-910a-0ea9b82462a0","sourceKey":"bank:BUA216:WCM-051","parentItemId":null,"revision":1,"payload":{"prompt":"A company expects an opening cash balance of N80,000, receipts of N900,000 and payments of N1,050,000 next month. It wants to keep a minimum cash balance of N50,000. How much short-term finance must it arrange?","options":["N120,000","N70,000","N50,000","N20,000"],"correctOption":0,"section":"Working Capital Management","explanation":"Closing balance before financing = 80,000 + 900,000 - 1,050,000 = -N70,000. To end the month with N50,000 the firm must raise 70,000 + 50,000 = N120,000. Option B covers the deficit but ignores the minimum balance, and Option C covers only the minimum balance."}},{"itemId":"905b9d0d-3ba1-58b4-bdb7-6af757d3af1e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e192d21b-a7fb-5dfd-a12f-be9c70055b7f","sourceKey":"bank:BUA216:WCM-052","parentItemId":null,"revision":1,"payload":{"prompt":"Owode Beverages Ltd has fixed assets of N10m. Its current assets never fall below N4m and rise to N7m at the seasonal peak. Under the matching (hedging) approach, how much long-term finance should it have?","options":["N14m","N10m","N17m","N13m"],"correctOption":0,"section":"Working Capital Management","explanation":"The matching approach finances permanent assets with long-term funds and temporary assets with short-term funds. Permanent assets = fixed assets N10m + permanent current assets N4m = N14m. Option C also finances the N3m seasonal peak with long-term money (a conservative policy), Option B ignores permanent current assets, and Option D wrongly adds the seasonal N3m instead of the permanent N4m."}},{"itemId":"2e9217c8-1bee-50df-9537-998c5f313eca","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e830dece-6e9a-547e-b23e-6f2c90c8577e","sourceKey":"bank:BUA216:WCM-053","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's current assets fluctuate between a minimum of N4m and a seasonal peak of N7m during the year. What is the amount of temporary (fluctuating) working capital at the peak?","options":["N3m","N4m","N11m","N7m"],"correctOption":0,"section":"Working Capital Management","explanation":"Temporary working capital is the extra current assets needed above the permanent minimum: 7m - 4m = N3m. Option B is the permanent working capital, Option D is the total at the peak, and Option C adds the two levels together."}},{"itemId":"2e8e041a-0a71-56b2-8d7d-1813882ae824","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"31399fda-bac9-56ca-abfd-98e00002bf61","sourceKey":"bank:BUA216:WCM-054","parentItemId":null,"revision":1,"payload":{"prompt":"Ojota Motors Ltd has total current assets of N1,800,000 and current liabilities of N1,100,000. Taking gross working capital as total current assets, what is its gross working capital?","options":["N2,900,000","N700,000","N1,800,000","N1,100,000"],"correctOption":2,"section":"Working Capital Management","explanation":"Gross working capital is simply the total investment in current assets, N1,800,000. Option B is net working capital (current assets less current liabilities), Option A adds the liabilities, and Option D is the current liabilities figure."}},{"itemId":"02d99c84-8ca3-5d9d-9bb9-b672c6831465","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"2575e6d1-753d-5209-ab43-0603d50e3a09","sourceKey":"bank:BUA216:WCM-055","parentItemId":null,"revision":1,"payload":{"prompt":"Zaria Mills Ltd expects credit sales of N9,125,000 next year and wants an average collection period of 40 days. Using a 365-day year, what level of trade debtors is consistent with this target?","options":["N228,125","N1,013,889","N1,000,000","N25,000"],"correctOption":2,"section":"Working Capital Management","explanation":"Rearranging average collection period = debtors x 365 / credit sales gives debtors = 9,125,000 x 40 / 365 = N1,000,000. Option B uses a 360-day year, Option A divides sales by 40, and Option D is just one day's credit sales."}},{"itemId":"97a57f82-86e9-559f-9f22-ac91aed24541","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6c6917f0-e6d8-5e14-b9ce-de14130739cc","sourceKey":"bank:BUA216:WCM-056","parentItemId":null,"revision":1,"payload":{"prompt":"A firm with credit sales of N7,300,000 a year cuts its average collection period from 60 days to 45 days. Using a 365-day year, how much cash is released from debtors?","options":["N304,167","N300,000","N900,000","N1,200,000"],"correctOption":1,"section":"Working Capital Management","explanation":"Debtors fall from 7,300,000 x 60 / 365 = N1,200,000 to 7,300,000 x 45 / 365 = N900,000, releasing N300,000 of cash. Option C is the new debtors balance and Option D is the old balance, not the change; Option A uses a 360-day year."}},{"itemId":"0988c887-bdd3-53a1-8471-5d93f2e3d2c7","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"067bfa14-924a-5ed6-8a6c-6265b1f31c1f","sourceKey":"bank:BUA216:WCM-057","parentItemId":null,"revision":1,"payload":{"prompt":"Current assets less current liabilities is known as:","options":["Fixed capital","Shareholders' funds","Working capital","Capital employed"],"correctOption":2,"section":"Working Capital Management","explanation":"Working capital is current assets less current liabilities, the running capital a company uses day to day. Option D is total assets less current liabilities, which includes long-term assets, and Option B is the owners' equity."}},{"itemId":"7ff7b968-ee71-5d08-a26e-6488478c1e30","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"74f2950b-ac3b-5b1c-9a9c-12c976050c6a","sourceKey":"bank:BUA216:WCM-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes working capital?","options":["The total of fixed assets and current assets","The running capital used in the day-to-day operations of a company","The capital contributed by ordinary shareholders","The long-term funds used to buy land and machinery"],"correctOption":1,"section":"Working Capital Management","explanation":"Working capital is the running capital of a company, the funds tied up in stock, debtors and cash less what is owed to creditors. Option D describes long-term (capital) investment, Option C is share capital, and Option A is total assets."}},{"itemId":"b7f49e6a-6e3c-56f1-b6f8-5e873cd12879","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1cef9ce2-1072-5c7f-9eac-e842e6b3d382","sourceKey":"bank:BUA216:WCM-059","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the main current assets that make up working capital?","options":["Stock","Creditors","Debtors","Cash"],"correctOption":1,"section":"Working Capital Management","explanation":"Current assets consist mainly of stock, debtors and cash. Creditors are amounts the company owes, so they are the main current liability, deducted from current assets when working capital is calculated."}},{"itemId":"ddf645af-94f8-5c50-bf11-000e0ed98cbf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"333ca65d-be09-5e30-8906-f8e13c4fd5cc","sourceKey":"bank:BUA216:WCM-060","parentItemId":null,"revision":1,"payload":{"prompt":"Working capital management can be defined as:","options":["The management of all aspects of current assets and current liabilities","The selection of long-term investment projects using NPV","The choice between debt and equity in the capital structure","The decision on how much profit to pay out as dividend"],"correctOption":0,"section":"Working Capital Management","explanation":"Working capital management covers every aspect of current assets and current liabilities. Option B is capital budgeting, Option C is the capital structure decision and Option D is the dividend decision; all three are long-term finance decisions."}},{"itemId":"01f148b4-eed7-5337-8361-e607ec08a17e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"d34bcd34-e85b-5607-a11a-4810da129ab4","sourceKey":"bank:BUA216:WCM-061","parentItemId":null,"revision":1,"payload":{"prompt":"Working capital management is also described as a combination of which three activities?","options":["Capital budgeting, dividend policy and gearing","Portfolio selection, hedging and arbitrage","Cash management, stock management and debtors management","Budgeting, auditing and taxation"],"correctOption":2,"section":"Working Capital Management","explanation":"Working capital management combines cash management, stock management and debtors management, the three main current assets. The other options list long-term finance decisions, investment techniques or general accounting tasks."}},{"itemId":"00088b77-8367-5ef7-8494-8499660ed282","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6d396580-da70-5937-b3eb-015dd64647c3","sourceKey":"bank:BUA216:WCM-062","parentItemId":null,"revision":1,"payload":{"prompt":"Under-capitalisation refers to a situation where a company has:","options":["Small capital, which gives a high return on investment","Huge capital, which gives a small return on investment","No working capital because current liabilities exceed current assets","Equal amounts of debt and equity capital"],"correctOption":0,"section":"Working Capital Management","explanation":"Under-capitalisation means operating with small capital, so each naira earns a high return on investment, though the firm may be stretched. Option B is the opposite case, over-capitalisation, and Option C describes negative working capital rather than under-capitalisation."}},{"itemId":"aa2d1485-64de-54f2-b4c8-6527fa4c73fb","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"4e5a4525-c901-5847-9452-df6d50780171","sourceKey":"bank:BUA216:WCM-063","parentItemId":null,"revision":1,"payload":{"prompt":"Agege Foods Plc keeps huge balances of idle cash and stock far above what its operations need, and its return on investment has become very small. This situation is best described as:","options":["An aggressive working capital policy","Over-capitalisation","Overtrading","Under-capitalisation"],"correctOption":1,"section":"Working Capital Management","explanation":"Over-capitalisation means huge capital giving a small return on investment, exactly what idle cash and excess stock produce. Option D is the opposite (small capital, high return), Option A uses minimal current assets and short-term funds, and Option C means expanding sales too fast on too little capital."}},{"itemId":"db57112b-e053-5796-acd3-cfae4100e9a0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"054c48e3-6fe6-5992-a5e8-9c9b14625269","sourceKey":"bank:BUA216:WCM-064","parentItemId":null,"revision":1,"payload":{"prompt":"The working capital cycle is best defined as:","options":["The period over which a fixed asset is depreciated","The time between placing an order with a supplier and receiving the goods","The number of times stock is replaced in a year","The total length of time required to convert cash into raw materials, work in progress, finished goods and debtors, and back into cash"],"correctOption":3,"section":"Working Capital Management","explanation":"The working capital cycle is the total time needed to go from cash back to cash through raw inputs, work in progress, finished goods and debtors. Option C is stock turnover, Option B is the lead time used in setting the reorder level, and Option A has nothing to do with working capital."}},{"itemId":"5524387a-854a-5ba3-8ec0-f533b44c0ac0","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"7b97c232-9103-5970-8eb8-ffbe00930258","sourceKey":"bank:BUA216:WCM-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the working capital cycle of a manufacturing company?","options":["Cash - raw materials - work in progress - finished goods - debtors - cash","Cash - finished goods - raw materials - work in progress - debtors - cash","Cash - debtors - finished goods - work in progress - raw materials - cash","Cash - raw materials - finished goods - work in progress - creditors - cash"],"correctOption":0,"section":"Working Capital Management","explanation":"Cash buys raw inputs (raw stock), which become work in progress and then finished goods; these are sold on credit to create debtors, who finally pay cash. Option C runs the cycle backwards, Option B puts finished goods before production, and Option D swaps the production stages and replaces debtors with creditors."}},{"itemId":"d6f77ff5-6875-53b7-8363-4fe96a6903ba","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"fd6fff47-4cf0-57ca-b02b-eb7f5d7f6fdb","sourceKey":"bank:BUA216:WCM-066","parentItemId":null,"revision":1,"payload":{"prompt":"In the working capital cycle, which event comes immediately after the conversion of work in progress into finished goods?","options":["Conversion of raw materials to work in progress","Conversion of finished goods to debtors through credit sales","Conversion of cash to raw materials","Conversion of debtors to cash"],"correctOption":1,"section":"Working Capital Management","explanation":"Once goods are finished they are sold on credit, turning them into debtors; only after that do debtors pay cash. Option C is the first stage and Option A is the second, and Option D is the final stage that comes after debtors are created."}},{"itemId":"738bb730-4c8c-5c0c-bb8d-d569bddd2c8b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"816ca914-a33f-573d-bcad-84150729b956","sourceKey":"bank:BUA216:WCM-067","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a stage of the working capital cycle?","options":["Conversion of fixed assets to cash","Conversion of cash to raw materials","Conversion of finished goods to debtors","Conversion of debtors to cash"],"correctOption":0,"section":"Working Capital Management","explanation":"The cycle involves only current items: cash, raw inputs, work in progress, finished goods and debtors. Selling fixed assets is a long-term investment decision, not part of the day-to-day cycle."}},{"itemId":"97191756-4c32-5e53-ab67-317ac75a55b4","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1541ea12-7220-52ca-9cd0-9fbbe1ed3eb5","sourceKey":"bank:BUA216:WCM-068","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT listed among the factors affecting the working capital of a company?","options":["Inflation rate prevailing in the economy","Business fluctuation","Nominal value of the company's ordinary shares","Production cycle"],"correctOption":2,"section":"Working Capital Management","explanation":"The nominal (par) value of shares is an accounting label on equity and does not change how much stock, debtors or cash a firm needs. The production cycle, inflation and business fluctuations all directly change the working capital a company must hold."}},{"itemId":"ce2f19c1-eca4-5b2f-a2ee-4393ddb33290","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5166bd6c-8430-57a6-a2a1-016b8e788f47","sourceKey":"bank:BUA216:WCM-069","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a factor affecting the working capital of a company?","options":["Location of the registered office","Number of directors on the board","Date of incorporation of the company","Dividend policy adopted by the company"],"correctOption":3,"section":"Working Capital Management","explanation":"Dividend policy affects working capital because paying out cash dividends drains the cash available for day-to-day operations. The number of directors, date of incorporation and registered office have no direct effect on the level of current assets."}},{"itemId":"bbd3b3ea-b1d1-57f3-aa03-104cb5a99d9e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"136cc409-9be8-5464-af5b-eea1f84e80a7","sourceKey":"bank:BUA216:WCM-070","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos furniture maker takes four months to turn timber into finished wardrobes, while a nearby bakery turns flour into bread in one day. The furniture maker needs far more working capital mainly because of its:","options":["Availability of credit","Dividend policy","Inflation rate","Production cycle"],"correctOption":3,"section":"Working Capital Management","explanation":"A longer production cycle keeps cash tied up in raw inputs and work in progress for longer, so more working capital is needed. Dividend policy, availability of credit and inflation can also affect working capital, but the difference described here comes from the length of production."}},{"itemId":"aa789b97-ba83-5a9b-9a30-d8690d4573a6","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"28c6cb88-6ecd-55d6-beba-27dde867d00e","sourceKey":"bank:BUA216:WCM-071","parentItemId":null,"revision":1,"payload":{"prompt":"Eko Distributors decides to give customers 90 days to pay instead of 30 days. Which factor affecting working capital is at work, and what is its likely effect?","options":["Size of the business; working capital is unaffected","Operating efficiency; working capital requirement falls","Credit policy; working capital requirement falls as debtors decrease","Credit policy; working capital requirement rises as debtors increase"],"correctOption":3,"section":"Working Capital Management","explanation":"The credit policy adopted by a company is a factor affecting working capital. Longer credit terms mean customers pay later, so debtors build up and more working capital is tied up. Option C gets the direction wrong, and the other options name the wrong factor."}},{"itemId":"2b219f0d-bacd-5bca-8a99-995e1d7cdaaa","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"dc94364c-23b3-5e89-bd2e-352ca3d7e4e5","sourceKey":"bank:BUA216:WCM-072","parentItemId":null,"revision":1,"payload":{"prompt":"In stock management, the term 'stock' refers to:","options":["Debtors and prepayments","Cash and short-term investments","Ordinary and preference shares","Raw materials, work in progress and finished goods"],"correctOption":3,"section":"Working Capital Management","explanation":"Stock (inventory) covers raw inputs, work in progress and finished goods. Option C refers to stock in the sense of shares, which is a different meaning of the word, and the remaining options are other current assets."}},{"itemId":"561d6adc-491b-557b-9897-f5fc019ea101","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"851196b0-3c2c-5dff-9c2b-3a4e9dd0156e","sourceKey":"bank:BUA216:WCM-073","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the tasks involved in the management of stock?","options":["Determining the dividend payout ratio","Setting the maximum and minimum levels of stock","Determining the reorder level","Determining the re-order quantity"],"correctOption":0,"section":"Working Capital Management","explanation":"Stock management involves setting the reorder level, the re-order quantity, and the maximum and minimum stock levels, all aimed at minimising total stock cost in production. The dividend payout ratio is a long-term finance decision."}},{"itemId":"77eb4314-e1f9-5671-bbc7-b2b27c884f42","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"f9f5042a-76de-5f1e-9c7d-3bb7912365fd","sourceKey":"bank:BUA216:WCM-074","parentItemId":null,"revision":1,"payload":{"prompt":"The re-order quantity that minimises the total of stock carrying cost and stock ordering cost is also known as the:","options":["Safety stock","Maximum stock level","Economic order quantity","Reorder level"],"correctOption":2,"section":"Working Capital Management","explanation":"The re-order quantity that minimises carrying plus ordering cost is the optimal re-order quantity or economic order quantity (EOQ). Option D is the stock level that triggers an order, not the quantity ordered, Option A is a buffer against stock-outs, and Option B is an upper control limit."}},{"itemId":"3b19b3ab-7ac6-555f-883e-f67551cf637d","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"ac98caa3-b39e-584b-9345-0ec8e50442dd","sourceKey":"bank:BUA216:WCM-075","parentItemId":null,"revision":1,"payload":{"prompt":"Where D is annual demand, OC is the cost per order and CC is the annual carrying cost per unit, the total annual carrying cost at order quantity Q* is:","options":["(Q* / 2) x CC","(D / Q*) x OC","D x CC","Q* x CC"],"correctOption":0,"section":"Working Capital Management","explanation":"Average stock is half the order quantity, so total carrying cost = (Q* / 2) x CC. Option B is the total ordering cost, Option D forgets that only half the order is held on average, and Option C charges carrying cost on the whole year's demand."}},{"itemId":"be400701-3330-5eca-8391-f27a94b743cf","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"1484e6db-ab3c-57ff-8d58-4ba1a41a4e6c","sourceKey":"bank:BUA216:WCM-076","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an assumption of the basic economic order quantity model?","options":["Quantity discounts are available for bulk purchases","No stock-outs are allowed","Annual demand and cost per order are constant","Purchase price per unit is known with certainty"],"correctOption":0,"section":"Working Capital Management","explanation":"The basic EOQ model assumes no discount is allowed, so quantity discounts break its assumptions. It also assumes no stock-outs, a known price per unit, and constant annual demand, ordering cost and carrying cost."}},{"itemId":"f2076cb3-2cb3-5241-8d20-024cbb87e044","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"bfc9c34d-60e5-5581-b598-288b3909738c","sourceKey":"bank:BUA216:WCM-077","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an assumption underlying the economic order quantity model?","options":["Stock-outs are allowed if they reduce costs","Demand fluctuates with the season","Annual carrying cost is constant","Ordering cost rises with every order placed"],"correctOption":2,"section":"Working Capital Management","explanation":"The EOQ model assumes annual carrying cost is constant, along with constant demand and cost per order, no discounts and no stock-outs. The other options contradict those assumptions."}},{"itemId":"2f33d8f6-decc-5516-8bc4-0b0813e6e41a","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"98939cef-4580-5877-9a4d-4335dde4882a","sourceKey":"bank:BUA216:WCM-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which costs does the economic order quantity seek to minimise?","options":["Ordering cost and carrying cost","Purchase cost only","Purchase cost and carrying cost","Ordering cost and purchase cost"],"correctOption":0,"section":"Working Capital Management","explanation":"EOQ balances ordering cost against carrying cost; these two make up the controllable cost. Total purchase cost (price x annual demand) is the same whatever order size is chosen, so options that include it are wrong."}},{"itemId":"fc58903b-b2bd-5b10-85de-37bd6e38ba79","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"5513be9d-6b6c-5b1e-ba68-1ae9951dd6f5","sourceKey":"bank:BUA216:WCM-079","parentItemId":null,"revision":1,"payload":{"prompt":"At the economic order quantity, which relationship always holds in the basic EOQ model?","options":["Total ordering cost equals total purchase cost","Total carrying cost is zero","Number of orders equals the order quantity","Total ordering cost equals total carrying cost"],"correctOption":3,"section":"Working Capital Management","explanation":"At the optimum the two controllable costs are equal, which gives a quick check on any EOQ answer. Option A confuses ordering with purchase cost, Option B would only happen if no stock were ever held, and Option C is a coincidence that happens only for particular figures."}},{"itemId":"2be835d3-6195-5ff6-9806-14b7d66c9ef2","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"db4ffcde-c01a-5d75-8d36-3495d4e6a332","sourceKey":"bank:BUA216:WCM-080","parentItemId":null,"revision":1,"payload":{"prompt":"If the annual carrying cost per unit rises while demand and ordering cost stay the same, the economic order quantity will:","options":["Fall","Double","Stay the same","Rise"],"correctOption":0,"section":"Working Capital Management","explanation":"Carrying cost is in the denominator of EOQ = square root of (2 x D x OC / CC), so a higher carrying cost makes it cheaper to hold less stock and order more often, and the EOQ falls. Option D would follow from higher demand or ordering cost, not higher carrying cost."}},{"itemId":"f7418b84-e280-5fdb-ace8-e8f5137bcd2e","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e0f0186e-8f3b-5e03-8955-cede7e6ec298","sourceKey":"bank:BUA216:WCM-081","parentItemId":null,"revision":1,"payload":{"prompt":"Safety (buffer) stock is best described as:","options":["Goods received from suppliers but not yet paid for","The quantity ordered each time an order is placed","Extra stock held to protect against running out when usage or lead time is higher than expected","Stock that has become obsolete and must be written off"],"correctOption":2,"section":"Working Capital Management","explanation":"Safety stock is a cushion kept above normal needs so that the firm does not run out during delays or unusual demand; it is added to the reorder level. Option B is the order quantity, while Option D and Option A describe obsolete stock and unpaid purchases."}},{"itemId":"ebb949bd-86d7-54c1-b658-2c3022ae38ed","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b706ba47-2c46-5216-9d5f-29fc4a9aaba9","sourceKey":"bank:BUA216:WCM-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the steps involved in cash management?","options":["Determining the optimal cash balance","Preparing the cash budget","Determining the economic order quantity","Investing the surplus fund"],"correctOption":2,"section":"Working Capital Management","explanation":"Cash management involves cash budgeting, managing the cash book, determining the optimal cash balance, investing surplus funds and financing deficits. The economic order quantity belongs to stock management, not cash management."}},{"itemId":"173184a8-ce76-5a1c-9b91-259bdb5e1df8","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b84799ab-1bd4-5d6f-bba3-54efb298c6a1","sourceKey":"bank:BUA216:WCM-083","parentItemId":null,"revision":1,"payload":{"prompt":"A cash budget is best defined as:","options":["A statement of assets and liabilities at a point in time","A list of debtors arranged by how long they have owed","A statement of expected cash receipts and expected cash payments over a future period","A record of profit earned over the past year"],"correctOption":2,"section":"Working Capital Management","explanation":"A cash budget shows the expected cash income and expected cash expenditure over a coming period, which may be daily, weekly, monthly or quarterly. Option A is a balance sheet, Option D is an income statement, and Option B is an age analysis of debtors."}},{"itemId":"04a127a8-9a85-5985-881d-a16408c359e5","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"03eac3b1-87bc-5f6a-b978-e136565484a7","sourceKey":"bank:BUA216:WCM-084","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian firm's cash budget shows a large surplus of cash expected next quarter. Which cash management step should follow?","options":["Increasing the reorder level","Tightening the credit policy","Investing the surplus fund","Financing the deficit fund"],"correctOption":2,"section":"Working Capital Management","explanation":"Investing the surplus fund is one of the steps of cash management; idle cash earns nothing, so a forecast surplus should be placed in suitable short-term investments. Option D applies when the budget shows a shortfall, and the other options are stock and debtors decisions."}},{"itemId":"249e600c-7699-51de-ad7f-85040d6b652b","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"6432722e-9869-5c94-ad8c-649dccbca5da","sourceKey":"bank:BUA216:WCM-085","parentItemId":null,"revision":1,"payload":{"prompt":"Debtors management is mainly concerned with:","options":["How fast the company recovers cash from its debtors","How much stock the company holds","How quickly the company pays its suppliers","How the company raises long-term loans"],"correctOption":0,"section":"Working Capital Management","explanation":"Debtors management is about how fast cash is recovered from customers who bought on credit, through good ledger records, credit policy and a recovery plan. Option C is creditors (payables) management and Option B is stock management."}},{"itemId":"41e9b534-1de5-5211-9703-bc0b8d02eebc","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"c47573e2-0cd0-5f20-8d11-7d80a6edef2c","sourceKey":"bank:BUA216:WCM-086","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the factors to consider for proper debtors management?","options":["Determining the reorder level","Adequate and updated ledger account statements","Adequate and proper recovery plan","Adequate and proper credit policy"],"correctOption":0,"section":"Working Capital Management","explanation":"Proper debtors management needs updated ledger statements, a sound credit policy, a recovery plan and proper recovery of cash from bad debtors. The reorder level is a stock management tool."}},{"itemId":"ea8852d8-af76-54e5-bd67-e2648ce53109","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"a317b8f0-526c-57f0-9493-5200ef2ad38d","sourceKey":"bank:BUA216:WCM-087","parentItemId":null,"revision":1,"payload":{"prompt":"In the credit terms '2/10 net 45', what does the 45 represent?","options":["The number of days within which the discount can be taken","The maximum payment period in days","The percentage discount offered","The interest rate charged on late payment"],"correctOption":1,"section":"Working Capital Management","explanation":"In 2/10 net 45, the 45 is the maximum payment period: the full invoice must be paid within 45 days. The 10 is the discount period in days and the 2 is the percentage discount."}},{"itemId":"a267165b-5921-5988-ae65-649eb4808ea9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"b1b61738-ab2f-57c7-bd79-aa32ebf79c86","sourceKey":"bank:BUA216:WCM-088","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier sells on terms of '3/15 net 60'. What do the 3 and the 15 mean?","options":["A 15% discount is available if payment is made within 3 days","Interest of 3% is charged on balances unpaid after 15 days","A 3% discount is available if payment is made within 15 days","Payment must be made in 3 instalments over 15 days"],"correctOption":2,"section":"Working Capital Management","explanation":"The first figure is the percentage discount and the second is the number of days in which it can be claimed, so 3% is deducted if the buyer pays within 15 days; otherwise the full amount is due by day 60. Option A swaps the two figures."}},{"itemId":"9488d521-359f-5125-b251-a2dfebfc65ac","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"e6236ec5-dbe5-5f79-80ae-1dbb4e905504","sourceKey":"bank:BUA216:WCM-089","parentItemId":null,"revision":1,"payload":{"prompt":"When calculating the cost of not taking a cash discount, which day count should be used if the question does not state one?","options":["360 days","The number of days in the credit period","365 days","300 days"],"correctOption":2,"section":"Working Capital Management","explanation":"The default is a 365-day year; 360 days is used only when a question explicitly says the company operates a 360-day year. The result is sensitive to this choice, so always read the question first. Option D and Option B are not standard day counts."}},{"itemId":"5f8bcedf-86b0-5281-a2a2-82e07e3d6fe3","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"3372122a-8953-553c-9b2e-2110399d898a","sourceKey":"bank:BUA216:WCM-090","parentItemId":null,"revision":1,"payload":{"prompt":"Gross working capital refers to:","options":["Fixed assets less long-term debt","Current assets less current liabilities","The total investment in current assets","Total assets less current liabilities"],"correctOption":2,"section":"Working Capital Management","explanation":"Gross working capital is the total of current assets. Option B is net working capital, the measure used in the standard definition of working capital, and Option D is capital employed."}},{"itemId":"1547cb78-d731-524c-a875-34b63f620586","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"79989a89-8ae1-518a-b5bc-19e5dfa1a092","sourceKey":"bank:BUA216:WCM-091","parentItemId":null,"revision":1,"payload":{"prompt":"Permanent working capital is best described as:","options":["Current assets needed only during seasonal peaks","The fixed assets of the business","Working capital financed entirely by trade creditors","The minimum level of current assets a firm needs at all times to carry on its operations"],"correctOption":3,"section":"Working Capital Management","explanation":"Permanent working capital is the minimum level of current assets that never disappears while the business operates. Option A describes temporary (fluctuating) working capital, and Option B is a fixed asset, not working capital."}},{"itemId":"8d444f4a-8e90-554b-a149-dab8576e19c9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"49d79ec9-8f08-5b7d-ae9f-6e1190b80e77","sourceKey":"bank:BUA216:WCM-092","parentItemId":null,"revision":1,"payload":{"prompt":"Under an aggressive working capital financing policy, a firm:","options":["Holds large cash balances financed by equity","Uses short-term funds to finance temporary current assets and part of its permanent assets","Matches the maturity of each source of finance to the life of the asset financed","Uses long-term funds to finance all permanent assets and all temporary current assets"],"correctOption":1,"section":"Working Capital Management","explanation":"An aggressive policy relies heavily on cheap but risky short-term finance, using it even for part of the permanent assets. Option D is a conservative policy, Option C is the matching (hedging) approach, and Option A describes over-cautious liquidity rather than an aggressive policy."}},{"itemId":"459fc07b-1bd9-51ad-b0c2-0eedb05d0bc1","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"43e221ca-8394-54a0-98cf-42be3f708b46","sourceKey":"bank:BUA216:WCM-093","parentItemId":null,"revision":1,"payload":{"prompt":"Which working capital financing policy uses long-term funds to finance all permanent assets and some or all of the temporary current assets, giving low risk but lower profitability?","options":["Aggressive policy","Matching (hedging) policy","Conservative policy","Under-capitalisation"],"correctOption":2,"section":"Working Capital Management","explanation":"A conservative policy leans on long-term finance even for part of the seasonal needs, so the firm rarely faces refinancing pressure but pays more for its funds. Option A uses more short-term finance and Option B finances temporary assets only with short-term funds."}},{"itemId":"ba09b050-55c1-5344-bd47-d7cae3235bf9","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"12f9a2ff-7f16-5d04-9262-6ebc5b7cdda9","sourceKey":"bank:BUA216:WCM-094","parentItemId":null,"revision":1,"payload":{"prompt":"Kwara Rice Mills Ltd keeps extra cash in its account in case a machine breaks down unexpectedly or a customer delays payment. Which motive for holding cash does this illustrate?","options":["Transactions motive","Compensating balance motive","Speculative motive","Precautionary motive"],"correctOption":3,"section":"Working Capital Management","explanation":"Holding cash as a cushion against unexpected events is the precautionary motive. Option A covers routine payments such as wages and suppliers, Option C is holding cash to take advantage of opportunities such as a fall in prices, and Option B relates to balances a bank requires."}},{"itemId":"3f6444ca-2e34-51de-bfd1-3b8ea1f4aa62","courseId":"40000000-0000-4000-8000-000000000014","kind":"cbt_question","questionId":"30d24afd-8011-5801-9d81-def0336d20d2","sourceKey":"bank:BUA216:WCM-095","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano trader holds extra cash so she can buy large quantities of grain if prices fall sharply after harvest. This reflects the:","options":["Speculative motive for holding cash","Precautionary motive for holding cash","Optimal cash balance motive","Transactions motive for holding cash"],"correctOption":0,"section":"Working Capital Management","explanation":"Keeping cash ready to profit from favourable price movements is the speculative motive. Option D is cash for routine day-to-day payments, Option B is cash kept for emergencies, and Option C is not one of the motives for holding cash."}}]$expected_content$::jsonb,
  'introduction-financial-management: cbt_question published payload and identity match source');
