00000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"2d5096f2-fdfb-46be-8671-f08373c5405f","sourceKey":"quiz:101","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated importance of integrating sustainability into business strategy?","options":["It enhances long-term business growth","Producing electric and hybrid vehicles","Process innovation","It lowers production and operation cost"],"correctOption":0,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"7090808f-00b9-58f2-9d3e-77c1c1795c53","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"eb80952b-cb17-44d3-9a8e-6bc23312b1d8","sourceKey":"quiz:102","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated key elements of a sustainable business strategy?","options":["It enhances brand image and customer trust","It reduces environmental impact","Leadership commitment","It reduces material use"],"correctOption":2,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"52e3aac7-1c11-5a29-ac74-984b18a641c8","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"472a6399-67a7-4946-85de-599c1e205b40","sourceKey":"quiz:103","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated steps for integrating sustainability into business strategy?","options":["It improves corporate reputation","Assess current environmental and social impact","High initial investment cost","Producing electric and hybrid vehicles"],"correctOption":1,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"59fb57c2-a930-5a4f-b80c-35b9913a078e","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"4f30b1d0-197c-424f-90bf-39026c521bf6","sourceKey":"quiz:104","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated objectives of green innovation?","opti