  where kind = 'course_overview') = $expected_content$[{"itemId":"828363c8-eac4-5a23-a995-3904a8c01aaf","courseId":"66dc36be-2c4d-5821-ac32-a5c8e4ae4886","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Business Statistics I","body":"Every topic is examinable. Work through every worked example with a calculator.","outcomes":["Explain what statistics is, the types of data and scales of measurement, and how data are collected and sampled.","Organise data into tables and frequency distributions and present them in charts and graphs.","Calculate and interpret the mean, median, mode and other averages, and quartiles, deciles and percentiles.","Calculate and interpret the range, quartile deviation, mean deviation, variance, standard deviation and coefficient of variation.","Measure the shape of a distribution with coefficients of skewness and kurtosis.","Apply the rules of probability, including conditional probability, Bayes' theorem and counting rules.","Find the expected value and variance of a random variable.","Calculate binomial, Poisson, uniform, exponential and normal probabilities."],"assessment":["Expect objective questions: definitions and classifications, and many short calculations."]}}]$expected_content$::jsonb,
