  where kind = 'course_overview') = $expected_content$[{"itemId":"7de7ab8f-ff10-5502-845a-0680e91142e1","courseId":"e6ebc3e3-e990-5459-84af-06a4f05aea89","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Mathematics for Business","body":"Every topic is examinable. Work through every worked example with a calculator.","outcomes":["Integrate functions and use integration to find totals from marginal functions, areas, and consumer's and producer's surplus.","Use algebraic, exponential and logarithmic functions to model and solve business and economics problems.","Differentiate functions and interpret marginal cost, revenue, profit and elasticity.","Find maximum and minimum values, including with two variables and constraints, and use growth and decay models.","Find market equilibrium and break-even points and analyse cost, revenue and profit.","Calculate simple and compound interest, present values, annuities and loan repayments.","Work with matrices, determinants and inverses, and solve systems of equations.","Use arithmetic and geometric progressions in business problems.","Apply set operations and Venn diagrams to counting problems.","Model consumption, saving and market penetration."],"assessment":["Expect objective questions, mostly short calculations, plus some definitions and rules."]}}]$expected_content$::jsonb,
