  from public.read_published_managed_content('fa9abff6-1f94-5735-bbd3-c9104da6df05')
  where kind = 'course_overview') = $expected_content$[{"itemId":"01056477-565c-5c2d-ba31-ab08932bca13","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Principles of Management","body":"The exam is mostly objective (CBT). Be ready for some theory questions too, where you define, list and explain.","outcomes":["Explain who managers are, what they do, and how management thinking developed.","Describe the environment managers work in, including culture, globalization, social responsibility and ethics.","Apply the decision-making process and explain how managers plan and choose strategies.","Describe the elements of organizational structure and compare common organizational designs.","Outline the human resource management process, from planning and hiring to appraisal and pay.","Explain why organizations change, how people react to change, and how managers encourage innovation.","Explain what shapes individual behaviour and how groups and teams work.","Compare the main theories of motivation and how managers reward employees.","Compare the main theories of leadership and explain how managers communicate and manage information.","Explain the control process and the basics of operations management."],"assessment":["Continuous assessment (tests and assignments): 30 to 40 marks.","Final exam: 60 to 70 marks, lasting 2 to 3 hours.","You need at least 65% lecture attendance to sit the exam."]}}]$expected_content$::jsonb,
  'principles-management: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('fa9abff6-1f94-5735-bbd3-c9104da6df05')
  where kind = 'note') = $expected_content$[{"itemId":"bce825f0-4027-5787-94c8-cc1c107cf052","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Managers and Management","body":"Managers and their three levels; efficiency, effectiveness and the functions; Mintzberg's roles and Katz's skills; why study management; science or art; history.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Managers and their three levels; efficiency, effectiveness and the functions; Mintzberg's roles and Katz's skills; why study management; science or art; history."}],"lessons":[{"number":"1.1","title":"Organizations, managers and levels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organization:","bold":true},{"text":" a deliberate arrangement of people to accomplish a specific purpose. Not a building, a mere group, or only profit-makers."}]},{"text":[{"text":"3 characteristics:","bold":true},{"text":" "},{"text":"goals","bold":true},{"text":" (purpose), "},{"text":"people","bold":true},{"text":", a deliberate "},{"text":"structure","bold":true},{"text":" (rules, regulations, values) that defines how members relate to one another at work. A student fraternity qualifies."}]},{"text":[{"text":"Nonmanagerial employees","bold":true},{"text":" do not direct or oversee others."}]},{"text":[{"text":"Manager:","bold":true},{"text":" works with and through others, directing and overseeing their activities. "},{"text":"Coordinating and integrating others' work","bold":true},{"text":" makes a job managerial. Managers may also do ordinary tasks. Managers get the chance to think creatively and use their imagination."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Top (strategic):","bold":true},{"text":" whole-organization decisions: vision, mission, long-term goals, policy, budgets. Board of Directors, chairperson, CEO, COO, executive vice president."}]},{"text":[{"text":"Middle (tactical):","bold":true},{"text":" between first-line and top; the link. Interpret directives, implement policies, turn goals into action, coordinate departments. Department head, division manager, plant manager, agency head, project leader, functional manager."}]},{"text":[{"text":"First-line (lower, supervisory, operational):","bold":true},{"text":" supervise workers: daily operations, routine decisions, training, performance. Report to middle managers. Focus on employee efficiency and motivation. Day-to-day administration of policies is operational (first-line) management's work. Supervisor, team leader, shift manager."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First-line is the lowest level of management; where it is not offered, a middle manager is the lowest level listed (nonmanagerial staff are not a management level). Coordinating departments is "},{"text":"not","bold":true},{"text":" a top-level job."}]},{"text":[{"text":"Newer organizations are more "},{"text":"dynamic","bold":true},{"text":"; managers are more varied in age, background and gender."}]}]}]},{"number":"1.2","title":"Management, efficiency, effectiveness and the functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management:","bold":true},{"text":" the process of getting things done effectively and efficiently, with and through people. Also: coordinating resources (planning, organizing, leading, controlling) to achieve goals. Organizational success depends on efficient management of resources; the main aim is organizational goals. It helps organizations achieve goals with minimal resources."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" doing things "},{"text":"right","bold":true},{"text":"; the "},{"text":"means","bold":true},{"text":". Relation of inputs to outputs: most output from least input; cutting cost while reaching goals."}]},{"text":[{"text":"Effectiveness:","bold":true},{"text":" doing the "},{"text":"right things","bold":true},{"text":"; the "},{"text":"ends","bold":true},{"text":". Attaining goals, e.g. delivering before the deadline."}]},{"text":[{"text":"Good management needs "},{"text":"both","bold":true},{"text":" high. Same sweets at lower cost = efficient, "},{"text":"not","bold":true},{"text":" more effective. Better sweets at lower cost = both. Effective management achieves organizational goals efficiently, never wasting resources. More cars at the same cost but full of defects = efficient only."}]},{"text":[{"text":"Henri Fayol","bold":true},{"text":" (French industrialist) gave "},{"text":"5 functions:","bold":true},{"text":" planning, organizing, commanding, coordinating, controlling. Today "},{"text":"4 (POLC):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"P","bold":true},{"text":"lanning (first): setting goals and how to reach them: objectives, strategy, forecasting, decision-making, timelines, mission and vision."}]},{"text":[{"text":"O","bold":true},{"text":"rganizing: structuring work: grouping tasks, allocating resources, assigning duties, delegating authority, organizational chart."}]},{"text":[{"text":"L","bold":true},{"text":"eading (= directing): influencing, motivating, communicating, mentoring, settling conflict. "},{"text":"Motivation","bold":true},{"text":" = encouraging employees to work. "},{"text":"Delegation","bold":true},{"text":" = assigning duties and responsibilities to employees."}]},{"text":[{"text":"C","bold":true},{"text":"ontrolling (last): monitoring, comparing, correcting; evaluating results; ensures all activities are aligned with organizational objectives and tasks are done correctly and on time."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" functions: innovating; departmentalization (part of organizing)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Directing","bold":true},{"text":" initiates action (other functions prepare the setting). It is continuous and flows top to bottom: a manager directs his subordinate and takes instructions from his boss."}]},{"text":[{"text":"Staffing:","bold":true},{"text":" recruiting, selecting, training, appraising, retaining: the right number and mix of people in the right positions. Budgeting is "},{"text":"not","bold":true},{"text":" staffing."}]},{"text":[{"text":"Coordinating:","bold":true},{"text":" synergizing the efforts of separate units to reach goals. It "},{"text":"is","bold":true},{"text":" a management function, relates to organizing, needs leadership. Needed because of task specialization, human differences, task dependency. Mechanisms: rules and procedures, plans and goals, management hierarchy (\"organization\" is not one). "},{"text":"External","bold":true},{"text":" coordination is with outside stakeholders. Problems: poor communication, differing leadership styles, differing formality of structure; not acceptable plans. Lack of commitment causes failure."}]},{"text":[{"text":"Management is "},{"text":"continuous","bold":true},{"text":"; a good manager communicates well. Management thought grew with socio-economic development, managers' experience and thinkers' foundations."}]}]}]},{"number":"1.3","title":"Roles, skills and universality","mustKnow":[{"type":"paragraph","text":[{"text":"Mintzberg's 10 roles","bold":true},{"text":" (from closely studying "},{"text":"5 chief executives","bold":true},{"text":"), in 3 groups:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal (3):","bold":true},{"text":" figurehead, leader, liaison."}]},{"text":[{"text":"Informational (3):","bold":true},{"text":" monitor, disseminator, spokesperson."}]},{"text":[{"text":"Decisional (4):","bold":true},{"text":" entrepreneur, disturbance handler, resource allocator, negotiator."}]},{"text":[{"text":"Interpersonal = dealing with people, ceremonial and symbolic duties. Informational = receiving, gathering, spreading information. Decisional = decisions. \"Technical\" is not a role."}]},{"text":[{"text":"Dinner speech = figurehead. Attending a professional or scientists' meeting = liaison. Reading business newspapers = monitor. Negotiator is decisional: decides when to compromise."}]}]},{"type":"paragraph","text":[{"text":"Katz's skills:","bold":true},{"text":" technical, human (interpersonal), conceptual. The four-skill version adds "},{"text":"political","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Technical:","bold":true},{"text":" job-specific (building codes, computer programming); matters most at first-line."}]},{"text":[{"text":"Human:","bold":true},{"text":" getting along with and motivating people; needed at all levels."}]},{"text":[{"text":"Conceptual:","bold":true},{"text":" abstract thinking, seeing the whole, applying information to solve problems; matters most at top."}]},{"text":[{"text":"Political:","bold":true},{"text":" networking, building a power base; for those moving up."}]}]},{"type":"paragraph","text":[{"text":"Universality:","bold":true},{"text":" all managers make decisions and do the 4 functions, but not identically. Emphasis varies with "},{"text":"level","bold":true},{"text":", "},{"text":"profit vs nonprofit","bold":true},{"text":", "},{"text":"size","bold":true},{"text":", "},{"text":"country","bold":true},{"text":". Almost every task involves a decision."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mintzberg's surprise: managers spent only a short time on each activity."}]},{"text":[{"text":"All three interpersonal roles fit "},{"text":"leading","bold":true},{"text":"; resource allocator fits "},{"text":"planning","bold":true},{"text":". Higher levels stress figurehead, liaison, disseminator, spokesperson, negotiator; lower levels stress "},{"text":"leader","bold":true},{"text":"."}]},{"text":[{"text":"As managers rise, technical skill matters less; human skill stays needed. A president needs technical skill least. Managers with strong "},{"text":"human skills bring out the best in their people","bold":true},{"text":"."}]},{"text":[{"text":"Political skill: networking, social astuteness, sincerity; not a dominant personality."}]},{"text":[{"text":"Nonprofits","bold":true},{"text":" differ in how they "},{"text":"judge success","bold":true},{"text":"; tight budgets demand efficiency."}]},{"text":[{"text":"Small business:","bold":true},{"text":" under 500 staff and no major industry influence. Manager is a "},{"text":"generalist","bold":true},{"text":"; "},{"text":"spokesperson","bold":true},{"text":" matters more. Informal, simpler design; control by direct observation, not computerised monitoring. Large firms focus internally, on "},{"text":"resource allocation","bold":true},{"text":"."}]}]}]},{"number":"1.4","title":"Why study management; science or art","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2 reasons:","bold":true},{"text":" (1) we deal with organizations every day; (2) you will manage or be managed. Well-managed organizations prosper in hard times through a "},{"text":"loyal customer base","bold":true},{"text":"."}]},{"text":[{"text":"Universality of management:","bold":true},{"text":" needed in every type and size of organization, level, work area and country."}]},{"text":[{"text":"4 forces:","bold":true},{"text":" changing workplaces, ethics and trust (including "},{"text":"mistrust between managers and employees","bold":true},{"text":"), economic and political uncertainty, changing technology. Key areas: "},{"text":"customers","bold":true},{"text":", "},{"text":"innovation","bold":true},{"text":". Employees who are unwilling to work is "},{"text":"not","bold":true},{"text":" one of these forces."}]},{"text":[{"text":"Management is "},{"text":"both","bold":true},{"text":" a science and an art."}]},{"text":[{"text":"Science","bold":true},{"text":" (objective): systematic knowledge and universal principles; clear guidelines; systematic planning; decision-making based on data; experimentation, observation, facts; measured and tested; removes bias; predictable, consistent results; applies to any organization; e.g. time and motion study."}]},{"text":[{"text":"Art","bold":true},{"text":" (subjective): practical skill and personal judgement; creativity, innovation, intuition, vision, experience, talent; improves with continuous practice; develops unique solutions; matters most in strategic decision-making; motivation, leadership style, conflict resolution. \"An art of getting things done\" means it requires human skills."}]},{"text":[{"text":"Both","bold":true},{"text":" because it combines creativity (art) and structure (science)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It is an "},{"text":"inexact science","bold":true},{"text":" because it deals with human behaviour. "},{"text":"Mintzberg","bold":true},{"text":" stressed the art side. Trial and error is "},{"text":"not","bold":true},{"text":" scientific."}]},{"text":[{"text":"Scientific management (productivity, standard work methods, data) is criticised as "},{"text":"mechanistic and rigid","bold":true},{"text":", ignoring human aspects."}]},{"text":[{"text":"Management is often hard and thankless; success depends on how well "},{"text":"others","bold":true},{"text":" perform. Managers create an environment where members work to their best, think creatively, and rely on "},{"text":"every member","bold":true},{"text":" to raise productivity. The direct-supervisor relationship is the biggest factor in productivity and loyalty."}]},{"text":[{"text":"Hardest ethical challenge: laying off hardworking, productive staff."}]},{"text":[{"text":"Customer satisfaction is increasingly a key goal; a prompt, helpful human answer shows responsiveness. "},{"text":"Innovation","bold":true},{"text":" gives an advantage over competitors."}]},{"text":[{"text":"C.K. Prahalad","bold":true},{"text":" introduced \"core competency\". A football fan gains least."}]}]}]},{"number":"1.5","title":"History of management","mustKnow":[{"type":"paragraph","text":[{"text":"Management is ancient; its study as a discipline began in the "},{"text":"20th century","bold":true},{"text":". Five eras:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Early:","bold":true},{"text":" Arsenal of Venice, "},{"text":"Adam Smith","bold":true},{"text":" ("},{"text":"Wealth of Nations","italic":true},{"text":", division of labour), Industrial Revolution (machine power replaced human power)."}]},{"text":[{"text":"Classical:","bold":true},{"text":" "},{"text":"Taylor","bold":true},{"text":" (scientific management, \"one best way\"; focus on process efficiency), "},{"text":"Gilbreths","bold":true},{"text":", "},{"text":"Fayol","bold":true},{"text":", "},{"text":"Weber","bold":true},{"text":" (bureaucracy)."}]},{"text":[{"text":"Behavioural (OB):","bold":true},{"text":" "},{"text":"Owen","bold":true},{"text":" (working conditions), "},{"text":"Munsterberg","bold":true},{"text":" (industrial psychology), "},{"text":"Follett","bold":true},{"text":" (individual and group behaviour), "},{"text":"Barnard","bold":true},{"text":" (cooperative social systems; first to call organizations open systems), "},{"text":"Hawthorne Studies","bold":true},{"text":" (Mayo; the most important contribution to the growth of organizational behaviour)."}]},{"text":[{"text":"Quantitative:","bold":true},{"text":" operations research / management science, from World War II; "},{"text":"TQM","bold":true},{"text":" (total quality management, the quality revolution of the 1980s-90s)."}]},{"text":[{"text":"Contemporary:","bold":true},{"text":" systems, contingency (\"it depends\"), information technology."}]}]},{"type":"paragraph","text":[{"text":"Four approaches of the early 20th century: scientific management, general administrative, quantitative, OB. Systems is "},{"text":"not","bold":true},{"text":" one."}]},{"type":"paragraph","text":[{"text":"Fayol's 14 principles:","bold":true},{"text":" division of work · authority · discipline · unity of command · unity of direction · subordination of individual interest · remuneration · centralization · scalar chain · order · equity · stability of tenure · initiative · esprit de corps. \"Equality\" and \"monopoly\" are "},{"text":"not","bold":true},{"text":" principles."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Division of work:","bold":true},{"text":" tasks by skill (specialization); raises efficiency."}]},{"text":[{"text":"Authority:","bold":true},{"text":" right to give orders and expect obedience; balanced with responsibility."}]},{"text":[{"text":"Discipline:","bold":true},{"text":" respect for agreements and rules. "},{"text":"Remuneration:","bold":true},{"text":" fair pay."}]},{"text":[{"text":"Unity of command:","bold":true},{"text":" one boss; gives clear lines of authority and reduces confusion. "},{"text":"Unity of direction:","bold":true},{"text":" common objectives."}]},{"text":[{"text":"Scalar chain:","bold":true},{"text":" line of authority top to bottom. "},{"text":"Esprit de corps:","bold":true},{"text":" team spirit."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Smith:","bold":true},{"text":" division of labour raises productivity: more skill and dexterity, less time lost switching tasks, labour-saving inventions (not strict control of time)."}]},{"text":[{"text":"Taylor:","bold":true},{"text":" Pennsylvania steel companies; shocked that workers used different methods, took it easy, produced only about a third of what they could, and were placed regardless of ability. Concern: "},{"text":"worker efficiency","bold":true},{"text":". Study: "},{"text":"pig iron","bold":true},{"text":". Recommended "},{"text":"incentive pay","bold":true},{"text":"."}]},{"text":[{"text":"Gilbreths:","bold":true},{"text":" began with "},{"text":"bricklaying","bold":true},{"text":"; used motion pictures to study hand and body motions; "},{"text":"therbligs","bold":true},{"text":" = basic hand motions."}]},{"text":[{"text":"General administrative theory","bold":true},{"text":" (Fayol, Weber): the whole organization. Fayol studied "},{"text":"macro","bold":true},{"text":" issues, Taylor "},{"text":"micro","bold":true},{"text":"."}]},{"text":[{"text":"Weber's bureaucracy:","bold":true},{"text":" division of labour, hierarchy, detailed rules, impersonality, "},{"text":"formal selection","bold":true},{"text":" (choosing people for jobs on the basis of their "},{"text":"technical qualifications","bold":true},{"text":"), career orientation."}]},{"text":[{"text":"OB","bold":true},{"text":" is linked with motivation. Munsterberg links with scientific management; work groups trace to Follett."}]},{"text":[{"text":"Hawthorne:","bold":true},{"text":" began as "},{"text":"lighting","bold":true},{"text":" tests; group norms drive individual behaviour; productivity and human relations."}]},{"text":[{"text":"Quantitative:","bold":true},{"text":" from WWII military problems. "},{"text":"Linear programming","bold":true},{"text":" allocates resources; "},{"text":"EOQ","bold":true},{"text":" sets inventory levels. Motivating individuals is "},{"text":"not","bold":true},{"text":" quantitative."}]},{"text":[{"text":"TQM","bold":true},{"text":" (quality management; "},{"text":"Deming and Juran","bold":true},{"text":"): continual improvement, customer needs; costs can fall while productivity rises."}]},{"text":[{"text":"Contingency:","bold":true},{"text":" flexible, no one best way."}]},{"text":[{"text":"Trends:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Workforce diversity:","bold":true},{"text":" gender, race, age and more. "},{"text":"Learning organization:","bold":true},{"text":" keeps learning, adapting, changing. "},{"text":"Knowledge management:","bold":true},{"text":" members systematically gather and share knowledge."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" exploiting opportunities others have not noticed. 3 themes: pursuing opportunities, innovation, growth."}]},{"text":[{"text":"E-business:","bold":true},{"text":" the organization's work through internet links; "},{"text":"e-commerce","bold":true},{"text":" is its sales and marketing side. Levels: "},{"text":"enhanced","bold":true},{"text":", "},{"text":"enabled","bold":true},{"text":" (internet improves traditional work, no online selling), "},{"text":"total","bold":true},{"text":" (revolves around the internet). "},{"text":"Intranet:","bold":true},{"text":" internal network for employees only."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organization = goals + people + structure."}]},{"text":[{"text":"Management = efficient (means), effective (ends) work through people."}]},{"text":[{"text":"Fayol's 5 functions became "},{"text":"POLC","bold":true},{"text":"; directing = leading."}]},{"text":[{"text":"Mintzberg: 10 roles (3 interpersonal, 3 informational, 4 decisional)."}]},{"text":[{"text":"Katz: technical (first-line), human (all levels), conceptual (top), plus political."}]},{"text":[{"text":"Management is both a science and an art. History: early, classical, behavioural, quantitative, contemporary."}]}]}],"theory":{"itemId":"18575d93-235d-5ae2-971c-dc04634c2596","question":[{"type":"paragraph","text":[{"text":"Define management and explain its four functions."}]}]},"practice":[{"topic":"Managers and Management","named":false}]}},{"itemId":"4bf7fefb-d37c-5226-85b6-ae5d4e3ebe35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:10","parentItemId":null,"revision":1,"payload":{"title":"Foundations of Control and Operations Management","body":"Control, its process, types and tools; operations management; value chain management; quality.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"Control, its process, types and tools; operations management; value chain management; quality."}],"lessons":[{"number":"10.1","title":"Control and the control process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling:","bold":true},{"text":" evaluating progress towards goals by "},{"text":"monitoring, comparing and taking corrective action","bold":true},{"text":", so "},{"text":"actual performance meets planned goals","bold":true},{"text":". It is the "},{"text":"last","bold":true},{"text":" management function. The real test of an effective control system is "},{"text":"whether the organization's goals are being achieved","bold":true},{"text":". Control minimises deviations from standards because it helps managers "},{"text":"check errors and take corrective action","bold":true},{"text":"."}]},{"text":[{"text":"3 reasons control matters:","bold":true},{"text":" (1) the "},{"text":"planning–controlling link","bold":true},{"text":" (control checks planning's goals and feeds new planning); (2) "},{"text":"empowering employees","bold":true},{"text":" (managers delegate without fearing blame for mistakes); (3) "},{"text":"protecting the workplace","bold":true},{"text":" (from disasters, scandals, violence, supply disruption, security breaches, terrorism)."}]},{"text":[{"text":"Control process, 3 steps:","bold":true},{"text":" (1) "},{"text":"measure","bold":true},{"text":" actual performance; (2) "},{"text":"compare","bold":true},{"text":" with the standard; (3) "},{"text":"take managerial action","bold":true},{"text":" (corrective action). Key elements: "},{"text":"setting (establishing) performance standards","bold":true},{"text":" (taken from planning's goals, and the first element of control), "},{"text":"measuring performance, comparing actual results with planned objectives, and taking corrective action","bold":true},{"text":". Performance measurement means comparing actual results with planned objectives."}]},{"text":[{"text":"4 information sources for measuring:","bold":true},{"text":" personal observation, statistical reports, oral reports, written reports."}]},{"text":[{"text":"Range of variation:","bold":true},{"text":" acceptable limits of variance between actual performance and the standard. Act only "},{"text":"outside","bold":true},{"text":" it; watch "},{"text":"size and direction","bold":true},{"text":"."}]},{"text":[{"text":"3 actions:","bold":true},{"text":" (1) do nothing; (2) correct actual performance (e.g. change pay or training); (3) revise the standard (if unrealistic)."}]},{"text":[{"text":"Immediate corrective action:","bold":true},{"text":" corrects at "},{"text":"once","bold":true},{"text":", treats the symptom (same-day overtime). "},{"text":"Basic corrective action:","bold":true},{"text":" asks "},{"text":"how and why","bold":true},{"text":", fixes the "},{"text":"source","bold":true},{"text":" (replace the faulty machine)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personal observation","bold":true},{"text":" ("},{"text":"MBWA","bold":true},{"text":", management by walking around): first-hand, unfiltered, small details; but biased, slow, looks like distrust. "},{"text":"Statistical:","bold":true},{"text":" graphs show relationships; limited facts, ignore subjective factors. "},{"text":"Oral:","bold":true},{"text":" quick; filtered, no permanent record. "},{"text":"Written:","bold":true},{"text":" comprehensive, formal, easy to file; slower to prepare."}]},{"text":[{"text":"Twin functions:","bold":true},{"text":" planning and control both look at goals (planning sets, control checks), occur at "},{"text":"all levels","bold":true},{"text":", are continuous, use quantitative techniques and standards, and use budgets and ratios."}]},{"text":[{"text":"What","bold":true},{"text":" you measure decides what employees work hard at. Any unit: satisfaction, turnover, absenteeism. Job-specific: units produced, sales. Output hard to count: "},{"text":"subjective","bold":true},{"text":" measures."}]},{"text":[{"text":"Fair standard missed: hold to it and explain; do not lower it."}]},{"text":[{"text":"Trap:","bold":true},{"text":" if every option accurately describes control, \"which does not\" = none of the above."}]}]}]},{"number":"10.2","title":"Types of control and organizational performance","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Feedforward","bold":true},{"text":" (predictive): "},{"text":"before","bold":true},{"text":" the activity; foresee and prevent problems."}]},{"text":[{"text":"Concurrent:","bold":true},{"text":" "},{"text":"during","bold":true},{"text":"; correct problems as they happen."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" "},{"text":"after","bold":true},{"text":" completion; uses performance data to assess whether goals were met."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategic control:","bold":true},{"text":" ensures the organization is "},{"text":"moving in the right direction","bold":true},{"text":" by tracking strategy "},{"text":"as it is implemented","bold":true},{"text":", to detect problems or threats."}]},{"text":[{"text":"3 measures of organizational performance:","bold":true},{"text":" (1) "},{"text":"productivity","bold":true},{"text":" (total output ÷ inputs); (2) "},{"text":"effectiveness","bold":true},{"text":" (how appropriate goals are, how well met); (3) "},{"text":"industry and company rankings","bold":true},{"text":" (published lists that rank organizations on set measures)."}]},{"text":[{"text":"Organizational performance:","bold":true},{"text":" combined result of all work activities. More productive = more output from the same or fewer inputs."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedforward:","bold":true},{"text":" most "},{"text":"desirable","bold":true},{"text":"; needs timely, accurate information. Examples: inspecting raw materials, training before work, servicing machines."}]},{"text":[{"text":"Concurrent:","bold":true},{"text":" best known is "},{"text":"direct supervision","bold":true},{"text":"; MBWA too."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" most "},{"text":"popular","bold":true},{"text":"; damage already done. Shows how effective "},{"text":"planning","bold":true},{"text":" was; can raise "},{"text":"motivation","bold":true},{"text":" (people want to know how they did). Examples: year-end financial statements, post-sale surveys, exam results."}]}]}]},{"number":"10.3","title":"Control tools and today's control issues","mustKnow":[{"type":"paragraph","text":[{"text":"4 financial ratio groups:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Liquidity","bold":true},{"text":" (meeting "},{"text":"current, short-term debts","bold":true},{"text":"): current ratio = current assets ÷ current liabilities; acid test = (current assets − inventories) ÷ current liabilities."}]},{"text":[{"text":"Leverage","bold":true},{"text":" (use of "},{"text":"debt","bold":true},{"text":", ability to pay interest): debt to assets = total debt ÷ total assets; times interest earned = profits before interest and taxes ÷ interest charges."}]},{"text":[{"text":"Activity","bold":true},{"text":" ("},{"text":"efficient use","bold":true},{"text":" of assets): inventory turnover = sales ÷ inventory; total asset turnover = sales ÷ total assets."}]},{"text":[{"text":"Profitability","bold":true},{"text":" (assets "},{"text":"generating profit","bold":true},{"text":"): profit margin = net profit after taxes ÷ total sales; return on investment = net profit after taxes ÷ total assets."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Budget:","bold":true},{"text":" a "},{"text":"planning and control","bold":true},{"text":" tool; gives "},{"text":"quantitative standards","bold":true},{"text":"."}]},{"text":[{"text":"MIS (management information system):","bold":true},{"text":" gives managers information "},{"text":"regularly","bold":true},{"text":". "},{"text":"Data","bold":true},{"text":" = raw, unanalysed facts; "},{"text":"information","bold":true},{"text":" = analysed data."}]},{"text":[{"text":"Information controls:","bold":true},{"text":" a "},{"text":"tool","bold":true},{"text":" to control other activities, and an "},{"text":"area to be controlled","bold":true},{"text":" (encryption, firewalls, back-ups)."}]},{"text":[{"text":"Balanced scorecard","bold":true},{"text":" ("},{"text":"Robert Kaplan and David Norton","bold":true},{"text":"): "},{"text":"4 areas","bold":true},{"text":": financial, customer, internal processes, people/innovation/growth assets. Finance alone can hide poor service or staff development."}]},{"text":[{"text":"Benchmarking:","bold":true},{"text":" searching for "},{"text":"best practices","bold":true},{"text":" among competitors or noncompetitors; a "},{"text":"benchmark","bold":true},{"text":" is the standard of excellence compared against. "},{"text":"Xerox:","bold":true},{"text":" first major US effort. "},{"text":"Internal","bold":true},{"text":" benchmarking copies a top unit's practices elsewhere."}]},{"text":[{"text":"4 contemporary control issues:","bold":true},{"text":" (1) cross-cultural differences and global turmoil; (2) workplace concerns (privacy, theft, violence); (3) customer interactions; (4) corporate governance."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Distant global units cannot be observed directly, so controls are more "},{"text":"formal","bold":true},{"text":"."}]},{"text":[{"text":"Employee theft:","bold":true},{"text":" employees' unauthorised taking of company property for own use. Careful hiring and clear policies = feedforward; supervision = concurrent; investigation after theft = feedback."}]},{"text":[{"text":"Service profit chain:","bold":true},{"text":" satisfied employees → better service → customer loyalty → profit."}]},{"text":[{"text":"Corporate governance:","bold":true},{"text":" governing a corporation so "},{"text":"owners' interests are protected","bold":true},{"text":". 2 reform areas: "},{"text":"boards of directors' role","bold":true},{"text":" and "},{"text":"financial reporting","bold":true},{"text":" ("},{"text":"Sarbanes-Oxley Act, 2002","bold":true},{"text":", US)."}]}]}]},{"number":"10.4","title":"Operations management and productivity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Operations function:","bold":true},{"text":" produces goods or services. "},{"text":"Operations management:","bold":true},{"text":" administration of business structure, practices and processes to "},{"text":"enhance efficiency and maximise profit","bold":true},{"text":"; the "},{"text":"design and control of the transformation process","bold":true},{"text":" (resources into goods and services)."}]},{"text":[{"text":"3 goals:","bold":true},{"text":" controlling costs, maximising profitability, proper allocation of resources."}]},{"text":[{"text":"It "},{"text":"begins and ends with the customer","bold":true},{"text":"; everyone has customers "},{"text":"at the next process","bold":true},{"text":"."}]},{"text":[{"text":"6 functions:","bold":true},{"text":" planning, scheduling, purchasing, controlling, quality control, inventory control."}]},{"text":[{"text":"4 types:","bold":true},{"text":" (1) "},{"text":"manufacturing","bold":true},{"text":" (goods); (2) "},{"text":"service","bold":true},{"text":" (intangible); (3) "},{"text":"logistics","bold":true},{"text":" (movement and storage of goods); (4) "},{"text":"project management","bold":true},{"text":" (a one-off project, planning to completion)."}]},{"text":[{"text":"Transformation process:","bold":true},{"text":" "},{"text":"inputs","bold":true},{"text":" (people, technology, capital, equipment, materials, information) → "},{"text":"transformation","bold":true},{"text":" (work activities, operations methods, management activities) → "},{"text":"outputs","bold":true},{"text":" (goods, services)."}]},{"text":[{"text":"Productivity = outputs ÷ inputs","bold":true},{"text":" (1,200 loaves ÷ 300 labour-hours = 4 per labour-hour)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Operations is vital because of "},{"text":"global competition","bold":true},{"text":", the "},{"text":"rise of the service economy","bold":true},{"text":" and the need for efficient procurement, production and delivery."}]},{"text":[{"text":"Manufacturing:","bold":true},{"text":" physical goods, storable. "},{"text":"Service:","bold":true},{"text":" nonphysical, used as produced (banks, hospitals)."}]},{"text":[{"text":"Productivity needs "},{"text":"both people and operations variables","bold":true},{"text":"."}]},{"text":[{"text":"W. Edwards Deming:","bold":true},{"text":" "},{"text":"14 points","bold":true},{"text":" for management's productivity (plan for the "},{"text":"long","bold":true},{"text":" term, drive out fear, break down barriers, statistical control); linked with "},{"text":"TQM","bold":true},{"text":"; early influence in "},{"text":"Japan","bold":true},{"text":"."}]}]}]},{"number":"10.5","title":"Value chain management and quality","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value:","bold":true},{"text":" features and attributes customers will give up resources (usually money) for."}]},{"text":[{"text":"Value chain:","bold":true},{"text":" the entire series of work activities that "},{"text":"add value at each step","bold":true},{"text":", raw materials to finished product. The "},{"text":"customer","bold":true},{"text":" decides what value is and when."}]},{"text":[{"text":"Value chain management:","bold":true},{"text":" managing activities and information along the "},{"text":"entire","bold":true},{"text":" chain. Goal: meet and exceed customer needs, with "},{"text":"full and seamless integration","bold":true},{"text":" of members. "},{"text":"External","bold":true},{"text":" focus, incoming "},{"text":"and","bold":true},{"text":" outgoing, goal "},{"text":"effectiveness","bold":true},{"text":" (most value for customers)."}]},{"text":[{"text":"Supply chain management:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" focus on efficient flow of "},{"text":"incoming","bold":true},{"text":" materials, goal "},{"text":"efficiency","bold":true},{"text":" (cut costs)."}]},{"text":[{"text":"6 requirements:","bold":true},{"text":" coordination and collaboration; technology investment; organizational processes; leadership; employees; organizational culture and attitudes."}]},{"text":[{"text":"4 obstacles:","bold":true},{"text":" organizational barriers; cultural attitudes; required capabilities; people."}]},{"text":[{"text":"Benefits:","bold":true},{"text":" improved procurement, logistics, product development; enhanced customer order management."}]},{"text":[{"text":"Quality:","bold":true},{"text":" ability of a product or service to reliably do what it should and satisfy customer expectations."}]},{"text":[{"text":"TQM:","bold":true},{"text":" philosophy driven by "},{"text":"continuous improvement","bold":true},{"text":" and responsiveness to customer needs, with employee involvement."}]},{"text":[{"text":"Mass customisation:","bold":true},{"text":" a product when, where, how customers want it."}]},{"text":[{"text":"ISO 9000:","bold":true},{"text":" "},{"text":"international quality management standards","bold":true},{"text":", uniform process guidelines; set by the International Organization for Standardization."}]},{"text":[{"text":"Six Sigma:","bold":true},{"text":" programme to reduce defects, lower costs, save time, improve satisfaction; goal "},{"text":"no more than 3.4 defects per million","bold":true},{"text":" units or procedures."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Obstacles:","bold":true},{"text":" "},{"text":"organizational barriers","italic":true},{"text":" = refusing to share information, resisting change, security worries; "},{"text":"cultural attitudes","italic":true},{"text":" = lack of trust, fear of losing intellectual property; "},{"text":"required capabilities","italic":true},{"text":" = partners lack skills or systems; "},{"text":"people","italic":true},{"text":" = unwilling to change, low commitment, time and energy."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling = monitoring, comparing, correcting; the last function. Process: measure, compare, act (standards come from planning)."}]},{"text":[{"text":"Actions: do nothing, correct (immediate = symptom, basic = cause) or revise the standard."}]},{"text":[{"text":"Feedforward before (most desirable); concurrent during; feedback after (most popular)."}]},{"text":[{"text":"4 control issues: cross-cultural, workplace concerns, customer interactions, corporate governance."}]},{"text":[{"text":"Tools: 4 ratio groups, budget, MIS, balanced scorecard, benchmarking."}]},{"text":[{"text":"Operations: 3 goals, 6 functions, 4 types; productivity = outputs ÷ inputs."}]},{"text":[{"text":"Value chain: external, effectiveness; supply chain: internal, efficiency. Six Sigma: 3.4 per million."}]}]}],"theory":{"itemId":"6d50cf35-2fa6-5b75-87ec-b821597a8811","question":[{"type":"paragraph","text":[{"text":"Define controlling and explain the steps in the control process."}]}]},"practice":[{"topic":"Foundations of Control and Operations Management","named":false}]}},{"itemId":"fd610879-a2a3-5306-b741-a80a83caacdf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"The Management Environment and Integrative Managerial Issues","body":"Environment, culture, global management, social responsibility, ethics, diversity.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Environment, culture, global management, social responsibility, ethics, diversity."}],"lessons":[{"number":"2.1","title":"How much do managers matter? The external environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Omnipotent view:","bold":true},{"text":" managers "},{"text":"directly responsible","bold":true},{"text":" for success or failure; the "},{"text":"dominant","bold":true},{"text":" view (\"take-charge\" executive; sacked coaches). "},{"text":"Symbolic view:","bold":true},{"text":" "},{"text":"external forces","bold":true},{"text":" responsible; managers have "},{"text":"limited","bold":true},{"text":" effect on substantive outcomes."}]},{"text":[{"text":"Managers are limited by "},{"text":"culture and environment","bold":true},{"text":". "},{"text":"Internal constraints","bold":true},{"text":" exist in "},{"text":"every","bold":true},{"text":" organization (staff resisting an idea). Managers "},{"text":"widen discretion","bold":true},{"text":" by changing/influencing culture and environment."}]},{"text":[{"text":"External environment:","bold":true},{"text":" forces and institutions "},{"text":"outside","bold":true},{"text":" the organization that could potentially affect performance; "},{"text":"uncontrollable","bold":true},{"text":". "},{"text":"Internal:","bold":true},{"text":" employees, culture."}]},{"text":[{"text":"6 components:","bold":true},{"text":" "},{"text":"economic","bold":true},{"text":" (interest rates, inflation, disposable income, stock market, exchange rates); "},{"text":"demographic","bold":true},{"text":" (population characteristics); "},{"text":"technological","bold":true},{"text":" (automation, office systems; changed fastest); "},{"text":"sociocultural","bold":true},{"text":" (values, attitudes, lifestyles, expectations); "},{"text":"political/legal","bold":true},{"text":" (laws, tax, labour and trade rules, stability, government policy); "},{"text":"global","bold":true},{"text":"."}]},{"text":[{"text":"Business environment:","bold":true},{"text":" "},{"text":"internal and external","bold":true},{"text":" factors, including economic, social ("},{"text":"demographics","bold":true},{"text":" is a social factor), political and technological ones; "},{"text":"climate change","bold":true},{"text":" is an environmental factor. "},{"text":"Exchange-rate","bold":true},{"text":" changes affect "},{"text":"international trade","bold":true},{"text":"; a growing economy brings "},{"text":"increased business opportunities","bold":true},{"text":". "},{"text":"Technological innovation by competitors","bold":true},{"text":" is an "},{"text":"external threat","bold":true},{"text":"."}]},{"text":[{"text":"Competitive environment:","bold":true},{"text":" described by "},{"text":"market conditions","bold":true},{"text":"; "},{"text":"market structure","bold":true},{"text":" = "},{"text":"level of competition","bold":true},{"text":". "},{"text":"Free-market economy:","bold":true},{"text":" "},{"text":"consumer choice","bold":true},{"text":", competition, prices set by supply and demand."}]},{"text":[{"text":"Business strategy","bold":true},{"text":" is influenced by "},{"text":"internal resources, economic conditions and technological trends","bold":true},{"text":"; "},{"text":"strategic planning","bold":true},{"text":" = "},{"text":"setting long-term goals","bold":true},{"text":". "},{"text":"Business growth","bold":true},{"text":" is affected by "},{"text":"market demand, political stability and economic policies","bold":true},{"text":". A business's "},{"text":"primary objective","bold":true},{"text":" is to "},{"text":"generate profits","bold":true},{"text":"; "},{"text":"business policies","bold":true},{"text":" "},{"text":"regulate internal operations","bold":true},{"text":"."}]},{"text":[{"text":"Specific (micro):","bold":true},{"text":" direct, immediate impact; unique, changing with conditions: "},{"text":"customers, suppliers, competitors, pressure groups","bold":true},{"text":". Government policy is "},{"text":"not","bold":true},{"text":" micro."}]},{"text":[{"text":"General (macro):","bold":true},{"text":" the 6 components; "},{"text":"smaller","bold":true},{"text":" effect than specific. Industry conditions are "},{"text":"not","bold":true},{"text":" part of it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suppliers:","bold":true},{"text":" materials, equipment, capital, labour (lending bank, nurses' union, local labour market); managers want steady inputs at "},{"text":"lowest price","bold":true},{"text":". "},{"text":"Competitors","bold":true},{"text":" include substitutes (courier vs postal service; video recorder vs TV network). "},{"text":"Pressure group:","bold":true},{"text":" consumer group seeking safety laws. The "},{"text":"Internet","bold":true},{"text":" removed geographic boundaries between competitors."}]},{"text":[{"text":"Disability law = "},{"text":"political/legal","bold":true},{"text":"; falling charity donations = "},{"text":"economic","bold":true},{"text":". "},{"text":"Baby Boomers","bold":true},{"text":" born 1946–1964; "},{"text":"Gen Y","bold":true},{"text":" thinks, learns, shops in new ways. 2008 recession: "},{"text":"homeowners unable to pay mortgages","bold":true},{"text":"; "},{"text":"low","bold":true},{"text":" interest rates left firms leveraged."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" Strengths, Weaknesses, Opportunities, Threats. "},{"text":"Oligopoly","bold":true},{"text":" = few sellers. Inflation raises costs; "},{"text":"Central Bank","bold":true},{"text":" regulates. Firms influence environment by "},{"text":"lobbying","bold":true},{"text":", adapt by "},{"text":"restructuring","bold":true},{"text":"."}]}]}]},{"number":"2.2","title":"How the environment affects managers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 effects: (1) jobs and employment, (2) "},{"text":"environmental uncertainty","bold":true},{"text":", (3) stakeholder relationships."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" 2 dimensions, "},{"text":"change","bold":true},{"text":" (frequent = "},{"text":"dynamic","bold":true},{"text":", minimal = "},{"text":"stable","bold":true},{"text":") and "},{"text":"complexity","bold":true},{"text":" ("},{"text":"number of components","bold":true},{"text":", "},{"text":"knowledge","bold":true},{"text":" of them). Managers keep it "},{"text":"as low as possible","bold":true},{"text":"."}]},{"text":[{"text":"Stakeholders:","bold":true},{"text":" groups "},{"text":"affected by","bold":true},{"text":" the organization's decisions and actions (investors, employees, customers). "},{"text":"External","bold":true},{"text":" stakeholders include "},{"text":"suppliers","bold":true},{"text":" (and customers); "},{"text":"internal","bold":true},{"text":" ones are "},{"text":"employees, in-house sales staff and management","bold":true},{"text":"."}]},{"text":[{"text":"4 steps:","bold":true},{"text":" (1) identify stakeholders; (2) find their interests or concerns; (3) decide how critical each is; (4) decide how to manage each relationship. "},{"text":"3 tools:","bold":true},{"text":" environmental scanning, forecasting, benchmarking."}]},{"text":[{"text":"Scanning:","bold":true},{"text":" screening large amounts of information to "},{"text":"anticipate and interpret","bold":true},{"text":" changes; foundation for "},{"text":"forecasts","bold":true},{"text":"; advanced scanning raised profits and growth."}]},{"text":[{"text":"Forecasting:","bold":true},{"text":" "},{"text":"predicting future outcomes","bold":true},{"text":" (e.g. changing a product because more women are expected to buy it in future); gives "},{"text":"information that helps decisions","bold":true},{"text":"; must be timely. "},{"text":"Quantitative:","bold":true},{"text":" mathematical rules on "},{"text":"historical data","bold":true},{"text":". "},{"text":"Qualitative:","bold":true},{"text":" judgement of "},{"text":"knowledgeable individuals","bold":true},{"text":"."}]},{"text":[{"text":"Benchmarking:","bold":true},{"text":" best practices of competitors "},{"text":"or noncompetitors","bold":true},{"text":" giving "},{"text":"superior performance","bold":true},{"text":"; may study a firm with a different product."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Competitor intelligence:","bold":true},{"text":" one of the fastest-growing scanning areas; "},{"text":"anticipates","bold":true},{"text":" competitors' actions; about "},{"text":"80%","bold":true},{"text":" from "},{"text":"your own employees, suppliers and customers","bold":true},{"text":". "},{"text":"Reverse engineering","bold":true},{"text":" (studying competitor's product) is common; intelligence methods can be "},{"text":"legal but unethical","bold":true},{"text":". "},{"text":"Global scanning","bold":true},{"text":" value depends on "},{"text":"own global activities","bold":true},{"text":"."}]},{"text":[{"text":"Forecasting tips:","bold":true},{"text":" simple methods; more than one; shorter periods; compare with "},{"text":"\"no change\"","bold":true},{"text":" forecast (right about "},{"text":"half","bold":true},{"text":" the time). Accuracy falls over longer periods; best when environment "},{"text":"not changing rapidly","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" frequent "},{"text":"power outages","bold":true},{"text":". Poor infrastructure: "},{"text":"delayed production and distribution","bold":true},{"text":" (government should "},{"text":"invest in infrastructure","bold":true},{"text":"). Corruption: "},{"text":"delays decisions, reduces efficiency","bold":true},{"text":" (reduce by "},{"text":"promoting ethical practices","bold":true},{"text":"). Poor education and skills: "},{"text":"training and skill development","bold":true},{"text":". Bureaucratic delays: "},{"text":"technology","bold":true},{"text":" (social media for marketing). Ethical approach promotes "},{"text":"transparency and fairness","bold":true},{"text":"."}]}]}]},{"number":"2.3","title":"Organizational culture","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizational culture:","bold":true},{"text":" shared values, principles, traditions, ways of doing things that influence how members act; "},{"text":"shared meaning","bold":true},{"text":", like "},{"text":"personality","bold":true},{"text":"; part of corporate culture is "},{"text":"employee behaviour","bold":true},{"text":". A "},{"text":"perception","bold":true},{"text":"; "},{"text":"descriptive","bold":true},{"text":" (not whether members "},{"text":"like","bold":true},{"text":" it); "},{"text":"shared","bold":true},{"text":"."}]},{"text":[{"text":"7 dimensions:","bold":true},{"text":" attention to detail, outcome orientation, people orientation, team orientation, aggressiveness, stability, innovation and risk taking. "},{"text":"Compensation is not one.","bold":true}]},{"text":[{"text":"Source:","bold":true},{"text":" "},{"text":"founder's","bold":true},{"text":" vision or mission. "},{"text":"4 ways passed on:","bold":true},{"text":" stories, rituals, material symbols, language."}]},{"text":[{"text":"Strong culture:","bold":true},{"text":" key values deeply held, widely shared; influences employees "},{"text":"more","bold":true},{"text":" than weak culture; staff "},{"text":"more committed","bold":true},{"text":". Most are "},{"text":"moderate to strong","bold":true},{"text":". Value-behaviour link "},{"text":"fairly straightforward","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stories:","bold":true},{"text":" significant events or people. "},{"text":"Rituals:","bold":true},{"text":" repeated activities reinforcing values, key goals, who is important or expendable. "},{"text":"Material symbols:","bold":true},{"text":" office size, dress, reserved parking ("},{"text":"stock options are not","bold":true},{"text":"). "},{"text":"Language:","bold":true},{"text":" in-house jargon (\"work judo\"); learning it shows acceptance, keeps culture alive."}]}]}]},{"number":"2.4","title":"Globalization and managing globally","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Globalization:","bold":true},{"text":" increasing international trade and relations; world one marketplace, borders matter less, more growth opportunities, rivals appear anywhere; managers handle economic, political, cultural differences. "},{"text":"Parochialism:","bold":true},{"text":" seeing the world from "},{"text":"one perspective","bold":true},{"text":" (sign: "},{"text":"monolingualism","bold":true},{"text":")."}]},{"text":[{"text":"Ethnocentric:","bold":true},{"text":" "},{"text":"home","bold":true},{"text":" country best; linked to parochialism and "},{"text":"MNCs","bold":true},{"text":"; least helpful. "},{"text":"Polycentric:","bold":true},{"text":" "},{"text":"host-country","bold":true},{"text":" managers know best. "},{"text":"Geocentric:","bold":true},{"text":" "},{"text":"world view","bold":true},{"text":"; best for global success. Global management needs "},{"text":"sensitivity to national customs","bold":true},{"text":"; the advice for global success is to "},{"text":"build an understanding of cultural differences","bold":true},{"text":"."}]},{"text":[{"text":"MNC:","bold":true},{"text":" operations in several countries (common from "},{"text":"mid-1960s","bold":true},{"text":"). "},{"text":"Multidomestic:","bold":true},{"text":" "},{"text":"decentralises","bold":true},{"text":". "},{"text":"Global:","bold":true},{"text":" "},{"text":"centralises","bold":true},{"text":" at home. "},{"text":"Transnational/borderless:","bold":true},{"text":" removes structural divisions creating artificial geographic barriers (raises efficiency, effectiveness, competitiveness). Dropping country structure for industries = "},{"text":"borderless","bold":true},{"text":"."}]},{"text":[{"text":"3 stages:","bold":true},{"text":" "},{"text":"I","bold":true},{"text":" exporting, importing; "},{"text":"II","bold":true},{"text":" staff abroad as salespeople or "},{"text":"hiring agents","bold":true},{"text":"; "},{"text":"III","bold":true},{"text":" licensing, franchising, strategic alliances, "},{"text":"joint ventures","bold":true},{"text":", subsidiaries. "},{"text":"Foreign subsidiary","bold":true},{"text":" = "},{"text":"greatest risk","bold":true},{"text":". "},{"text":"Joint venture","bold":true},{"text":" = type of "},{"text":"strategic alliance","bold":true},{"text":" (shared plant or product costs)."}]},{"text":[{"text":"3 environments abroad:","bold":true},{"text":" legal-political, economic, cultural ("},{"text":"religion is not","bold":true},{"text":" one). Economic threat: changing "},{"text":"inflation rates","bold":true},{"text":". Culture hardest to learn: "},{"text":"natives least able to explain","bold":true},{"text":" it."}]},{"text":[{"text":"Hofstede's 5:","bold":true},{"text":" power distance; individualism vs collectivism; quantity vs quality of life; uncertainty avoidance; long-term vs short-term orientation. "},{"text":"GLOBE's 9:","bold":true},{"text":" assertiveness, future orientation, gender differentiation, uncertainty avoidance, power distance, individualism/collectivism, in-group collectivism, performance orientation, humane orientation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"High power distance:","bold":true},{"text":" titles, rank, status count; meeting representatives have very different status. "},{"text":"Collectivism:","bold":true},{"text":" group looks after, protects members. "},{"text":"Quantity of life:","bold":true},{"text":" assertiveness, material things; "},{"text":"quality:","bold":true},{"text":" relationships, caring. "},{"text":"Uncertainty avoidance:","bold":true},{"text":" tolerance of risk, unusual behaviour; "},{"text":"high","bold":true},{"text":" = low tolerance, formal rules."}]},{"text":[{"text":"EU:","bold":true},{"text":" 12 countries, regaining economic strength against "},{"text":"United States and Japan","bold":true},{"text":", removing barriers on border controls, taxes, subsidies, employment, investment, trade, nationalist policies and travel (all of the above). "},{"text":"EMU:","bold":true},{"text":" shared currency, "},{"text":"euro","bold":true},{"text":". "},{"text":"NAFTA:","bold":true},{"text":" Mexico, Canada, United States. "},{"text":"ASEAN:","bold":true},{"text":" Southeast Asia."}]},{"text":[{"text":"Trap:","bold":true},{"text":" older \"transnational\" = decentralised, local nationals run operations, marketing adapted per country; \"products made only locally\" is "},{"text":"not","bold":true},{"text":" a feature."}]}]}]},{"number":"2.5","title":"Social responsibility, green management, ethics and diversity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classical view:","bold":true},{"text":" only responsibility is to "},{"text":"maximise profits for stockholders","bold":true},{"text":". "},{"text":"Milton Friedman","bold":true},{"text":": spending on \"social good\" "},{"text":"adds to costs","bold":true},{"text":"."}]},{"text":[{"text":"Socioeconomic view:","bold":true},{"text":" business "},{"text":"more than an economic institution","bold":true},{"text":"; "},{"text":"protect and improve society's welfare","bold":true},{"text":"."}]},{"text":[{"text":"Social responsibility (CSR):","bold":true},{"text":" obligation "},{"text":"beyond law and economics","bold":true},{"text":" to pursue long-term goals good for society; ethical practice."}]},{"text":[{"text":"Social obligation:","bold":true},{"text":" does "},{"text":"only the minimum the law requires","bold":true},{"text":" (economic and legal duties; meeting pollution and anti-discrimination laws), with no extra duty to stakeholders. "},{"text":"Social responsiveness:","bold":true},{"text":" adapting to changing "},{"text":"societal conditions","bold":true},{"text":" (recycled paper). "},{"text":"Social responsibility:","bold":true},{"text":" adds "},{"text":"ethical","bold":true},{"text":" imperative. "},{"text":"Social screening:","bold":true},{"text":" social criteria in investment decisions. "},{"text":"Values-based management:","bold":true},{"text":" managers establish, promote, practise "},{"text":"shared values","bold":true},{"text":", which guide decisions; building them "},{"text":"not easy","bold":true},{"text":"."}]},{"text":[{"text":"Sustainability:","bold":true},{"text":" goals and long-term shareholder value through "},{"text":"economic, environmental and social","bold":true},{"text":" opportunities. "},{"text":"Greening:","bold":true},{"text":" decisions tied to "},{"text":"natural environment","bold":true},{"text":"; pollution, toxic waste, global warming and resource depletion are "},{"text":"global environmental problems","bold":true},{"text":". "},{"text":"Environmental sustainability","bold":true},{"text":" = "},{"text":"reducing waste and pollution","bold":true},{"text":"; "},{"text":"ethical practices","bold":true},{"text":" promote "},{"text":"long-term sustainability","bold":true},{"text":"."}]},{"text":[{"text":"4 green approaches:","bold":true},{"text":" "},{"text":"legal","bold":true},{"text":" (law only) → "},{"text":"market","bold":true},{"text":" (customers' preferences) → "},{"text":"stakeholder","bold":true},{"text":" (many stakeholders' demands) → "},{"text":"activist","bold":true},{"text":" (greatest sensitivity; best shows social responsibility). \"Responsibility\" is "},{"text":"not","bold":true},{"text":" one."}]},{"text":[{"text":"4 stages of expanding responsibility:","bold":true},{"text":" Stage 1 owners/management (stockholders); Stage 2 adds "},{"text":"employees (human resource concerns)","bold":true},{"text":"; Stage 3 adds "},{"text":"customers and suppliers","bold":true},{"text":" (safe products, fair prices); Stage 4 society."}]},{"text":[{"text":"Ethics:","bold":true},{"text":" rules or principles defining right and wrong. "},{"text":"4 views:","bold":true},{"text":" "},{"text":"utilitarian","bold":true},{"text":" (greatest good for greatest number; efficiency, profit; "},{"text":"most business people","bold":true},{"text":"); "},{"text":"rights","bold":true},{"text":" (based on "},{"text":"respecting and protecting individual liberties and freedoms","bold":true},{"text":": privacy, free speech, conscience, life, safety, due process); "},{"text":"justice","bold":true},{"text":" (rules "},{"text":"fair and impartial","bold":true},{"text":", within the law); "},{"text":"integrative social contracts","bold":true},{"text":" (norms already in industries and companies). \"Principled\" is "},{"text":"not","bold":true},{"text":" one."}]},{"text":[{"text":"3 ways to encourage ethics:","bold":true},{"text":" "},{"text":"code of ethics","bold":true},{"text":" (formal document), "},{"text":"ethical leadership","bold":true},{"text":", "},{"text":"ethics training","bold":true},{"text":". "},{"text":"Workforce diversity:","bold":true},{"text":" how people are "},{"text":"different from and similar to","bold":true},{"text":" one another."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Decisions with a social responsibility dimension:","bold":true},{"text":" employee relations, charitable giving, pricing, conserving resources, product quality and safety, trading in countries that abuse human rights."}]},{"text":[{"text":"For:","bold":true},{"text":" "},{"text":"ethical obligation","bold":true},{"text":" (right thing); "},{"text":"better environment","bold":true},{"text":" (helping solve social problems builds a better community that attracts and keeps skilled workers); "},{"text":"discouraging regulation","bold":true},{"text":"; "},{"text":"balance of responsibility and power","bold":true},{"text":" (firms hold great power; if the responsibility they accept does not match it, the "},{"text":"public good suffers","bold":true},{"text":"); "},{"text":"possession of resources","bold":true},{"text":" (firms have the money, technical skills and management ability to support public and charitable projects); public expectations; image; long-run profits. "},{"text":"Against:","bold":true},{"text":" "},{"text":"violation of profit maximization","bold":true},{"text":" (only economic interests); dilution of purpose; "},{"text":"costs","bold":true},{"text":" (higher prices); "},{"text":"too much power","bold":true},{"text":"; lack of skills; "},{"text":"lack of accountability","bold":true},{"text":" (leaders are not directly answerable to the public for shaping social policy)."}]},{"text":[{"text":"Studies: "},{"text":"positive","bold":true},{"text":" link with economic performance; "},{"text":"little evidence","bold":true},{"text":" of harm."}]},{"text":[{"text":"Moral development:","bold":true},{"text":" preconventional; "},{"text":"conventional","bold":true},{"text":" (keep order, meet others' expectations); principled. "},{"text":"Ego strength:","bold":true},{"text":" strength of convictions. "},{"text":"Locus of control:","bold":true},{"text":" belief in controlling one's fate (\"hit targets despite weather\" = "},{"text":"internal","bold":true},{"text":"). "},{"text":"Formal rules","bold":true},{"text":" most encourage ethics; "},{"text":"strong","bold":true},{"text":" high-standards culture supports it. "},{"text":"Issue intensity:","bold":true},{"text":" characteristics of the issue; 6 factors (harm, consensus, probability, immediacy, closeness, concentration); \"chance of being found out\" is "},{"text":"not","bold":true},{"text":" one."}]},{"text":[{"text":"Also reduce unethical behaviour: selection, codes, training; "},{"text":"phone listening is not","bold":true},{"text":" one. Global firms "},{"text":"clarify","bold":true},{"text":" guidelines."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Omnipotent vs symbolic; 6 components; 4 specific groups."}]},{"text":[{"text":"Scanning, forecasting, benchmarking; 7 culture dimensions; 3 global attitudes."}]},{"text":[{"text":"Obligation, responsiveness, responsibility."}]}]}],"theory":{"itemId":"860e6a6e-f521-5acc-9133-ca48c349ee04","question":[{"type":"paragraph","text":[{"text":"Distinguish between the classical and socioeconomic views of social responsibility, and explain social obligation, social responsiveness and social responsibility."}]}]},"practice":[{"topic":"The Management Environment and Integrative Managerial Issues","named":false}]}},{"itemId":"80aeeeb2-854c-55a0-a396-5fda44fde69c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"Foundations of Decision Making and Foundations of Planning","body":"The 8-step decision process, decision types and conditions, group decisions; planning, the 6-step strategic process, strategies, goals, MBO and planning tools.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The 8-step decision process, decision types and conditions, group decisions; planning, the 6-step strategic process, strategies, goals, MBO and planning tools."}],"lessons":[{"number":"3.1","title":"The decision-making process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Decision making:","bold":true},{"text":" choosing among alternatives (the best course of action); closely linked with "},{"text":"planning","bold":true},{"text":"; its primary goal is to "},{"text":"resolve organizational issues efficiently","bold":true},{"text":". It does not by itself lead to performance monitoring or industrial harmony. "},{"text":"Problem:","bold":true},{"text":" a gap between existing and desired states."}]},{"text":[{"text":"8 steps:","bold":true},{"text":" 1 identify a problem; 2 identify decision criteria; 3 allocate weights to criteria; 4 develop alternatives ("},{"text":"consider all alternatives","bold":true},{"text":"); 5 analyse alternatives; 6 select one; 7 implement it; 8 evaluate its effectiveness. "},{"text":"Ignoring team feedback","bold":true},{"text":" is not a step; corrective action follows evaluation."}]},{"text":[{"text":"Criteria:","bold":true},{"text":" factors relevant to solving the problem. "},{"text":"Heuristics:","bold":true},{"text":" rules of thumb."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1:","bold":true},{"text":" "},{"text":"pressure to act","bold":true},{"text":" must exist first."}]},{"text":[{"text":"Step 3:","bold":true},{"text":" score the most important criterion (10), weight the others against it; if all are equal, weighting is not needed."}]},{"text":[{"text":"Steps 5-6:","bold":true},{"text":" appraise alternatives against the "},{"text":"criteria","bold":true},{"text":"; pick the "},{"text":"highest score","bold":true},{"text":"."}]},{"text":[{"text":"Step 7:","bold":true},{"text":" letting those affected "},{"text":"take part","bold":true},{"text":" raises commitment. "},{"text":"Step 8:","bold":true},{"text":" final; reviewing outcomes and "},{"text":"feedback","bold":true},{"text":" "},{"text":"evaluate effectiveness","bold":true},{"text":" and "},{"text":"identify areas for improvement","bold":true},{"text":"; you may "},{"text":"restart","bold":true},{"text":"."}]},{"text":[{"text":"Confirmation bias","bold":true},{"text":" is the "},{"text":"most common","bold":true},{"text":" bias. "},{"text":"Sunk costs","bold":true},{"text":" are "},{"text":"irrelevant","bold":true},{"text":" to future decisions. Bias is reduced by "},{"text":"seeking expert advice","bold":true},{"text":"."}]},{"text":[{"text":"An effective decision is "},{"text":"rational","bold":true},{"text":"; its key feature is "},{"text":"careful analysis of alternatives","bold":true},{"text":"; makers are "},{"text":"proactive and analytical","bold":true},{"text":". The decision-making process ensures "},{"text":"efficient use of resources","bold":true},{"text":". Under uncertainty, be "},{"text":"flexible and adaptive","bold":true},{"text":"."}]},{"text":[{"text":"Time pressure","bold":true},{"text":" hinders decisions; quick ones are "},{"text":"not always optimal","bold":true},{"text":". "},{"text":"Experience, complexity and time constraints","bold":true},{"text":" all influence decision-making speed; risk and certainty also matter."}]}]}]},{"number":"3.2","title":"Approaches, types of decisions and conditions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rational:","bold":true},{"text":" consistent choices that "},{"text":"maximise value","bold":true},{"text":" within limits; a perfectly rational maker is "},{"text":"objective and logical","bold":true},{"text":"; the model assumes "},{"text":"complete information","bold":true},{"text":" and logical evaluation (bounded rationality has limited information)."}]},{"text":[{"text":"Bounded rationality:","bold":true},{"text":" rational "},{"text":"within limits","bold":true},{"text":" of information and resources; "},{"text":"simplified models","bold":true},{"text":"; "},{"text":"satisfice","bold":true},{"text":" = accept \"good enough\". Perfect rationality gives a "},{"text":"maximising","bold":true},{"text":" choice; bounded gives a "},{"text":"satisficing","bold":true},{"text":" one."}]},{"text":[{"text":"Intuition:","bold":true},{"text":" experience, feelings, accumulated judgement (\"gut feeling\"); research finds managers use information from the "},{"text":"subconscious","bold":true},{"text":" to help them decide."}]},{"text":[{"text":"Escalation of commitment:","bold":true},{"text":" more commitment to an earlier decision despite evidence it was wrong."}]},{"text":[{"text":"Structured problem:","bold":true},{"text":" familiar, easily defined (equipment breakdown). Needs a "},{"text":"programmed","bold":true},{"text":" decision: routine, repetitive, uses past solutions (daily office hours); lower-level managers. Problem, decision and level link up: "},{"text":"integration","bold":true},{"text":". It "},{"text":"improves organizational efficiency","bold":true},{"text":" and cuts the need for costly managerial talent; a local fast-food manager makes the most."}]},{"text":[{"text":"Unstructured problem:","bold":true},{"text":" new, unusual, ambiguous or incomplete information. Needs a "},{"text":"nonprogrammed","bold":true},{"text":" decision: unique, nonrecurring, custom-made, usually under "},{"text":"uncertainty","bold":true},{"text":"; upper-level managers."}]},{"text":[{"text":"3 ways to make programmed decisions:","bold":true},{"text":" "},{"text":"procedure","bold":true},{"text":" (related, sequential steps); "},{"text":"rule","bold":true},{"text":" (explicit statement of what may or may not be done); "},{"text":"policy","bold":true},{"text":" (guideline that "},{"text":"sets parameters","bold":true},{"text":", with an "},{"text":"ambiguous term","bold":true},{"text":", e.g. \"productive relationships with organizations in its community\")."}]},{"text":[{"text":"3 conditions:","bold":true},{"text":" "},{"text":"certainty","bold":true},{"text":" (every outcome known, e.g. three dealers' prices); "},{"text":"risk","bold":true},{"text":" (probabilities estimable, e.g. a Lagos shop using last rainy season's sales); "},{"text":"uncertainty","bold":true},{"text":" (neither: the outcome is "},{"text":"unpredictable","bold":true},{"text":", with outcomes unknown and risk not measurable)."}]},{"text":[{"text":"Under uncertainty:","bold":true},{"text":" "},{"text":"maximax","bold":true},{"text":" = maximise the maximum payoff (all on the long shot), optimist; "},{"text":"maximin","bold":true},{"text":" = maximise the minimum payoff, pessimist; "},{"text":"minimax","bold":true},{"text":" = minimise the maximum \"regret\"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rationality assumes","bold":true},{"text":" a clear problem, single goal, "},{"text":"constant, stable","bold":true},{"text":" preferences (\"preferences keep changing\" is not one), best "},{"text":"economic","bold":true},{"text":" interests; it is possible when problems are simple, goals clear, alternatives few. Culture, politics and power also shape decisions."}]},{"text":[{"text":"Intuition's aspects:","bold":true},{"text":" experience, feelings, cognitive skills, subconscious processing, values; never programmed decisions."}]},{"text":[{"text":"Styles:","bold":true},{"text":" directive, analytic, conceptual, behavioural."}]},{"text":[{"text":"Levels:","bold":true},{"text":" "},{"text":"strategic","bold":true},{"text":" (top; long-term); "},{"text":"tactical","bold":true},{"text":" (middle; "},{"text":"medium-term","bold":true},{"text":", turns strategy into specific actions; if \"medium-term\" is absent, choose \"short-term goals\"); "},{"text":"operational","bold":true},{"text":" (first-line; "},{"text":"day-to-day operations and specific tasks","bold":true},{"text":", routine)."}]},{"text":[{"text":"Centralised:","bold":true},{"text":" authority at the top. "},{"text":"Decentralised:","bold":true},{"text":" delegated downward."}]}]}]},{"number":"3.3","title":"Group decisions and decision tools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group","bold":true},{"text":" style = "},{"text":"collaboration and consensus","bold":true},{"text":"."}]},{"text":[{"text":"Benefits:","bold":true},{"text":" more information and alternatives, greater acceptance and legitimacy. "},{"text":"Drawbacks:","bold":true},{"text":" time-consuming, minority domination, "},{"text":"groupthink","bold":true},{"text":", ambiguous responsibility."}]},{"text":[{"text":"Groupthink:","bold":true},{"text":" overemphasis on consensus; members hold back different views."}]},{"text":[{"text":"3 ways to boost creativity:","bold":true},{"text":" 1 "},{"text":"brainstorming","bold":true},{"text":" (many ideas, criticism withheld); 2 "},{"text":"nominal group technique","bold":true},{"text":" (members write ideas independently; discussion restricted); 3 "},{"text":"electronic meetings","bold":true},{"text":" (interaction by computer)."}]},{"text":[{"text":"National culture","bold":true},{"text":" affects decisions and risk taking."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vroom-Yetton:","bold":true},{"text":" subordinates' "},{"text":"participation","bold":true},{"text":". "},{"text":"Delphi:","bold":true},{"text":" "},{"text":"expert opinions","bold":true},{"text":". "},{"text":"Decision tree:","bold":true},{"text":" evaluates choices systematically."}]},{"text":[{"text":"Cost-benefit analysis:","bold":true},{"text":" pros and cons. "},{"text":"SWOT:","bold":true},{"text":" "},{"text":"qualitative","bold":true},{"text":". "},{"text":"Scenario analysis:","bold":true},{"text":" future possibilities. "},{"text":"PERT:","bold":true},{"text":" project duration."}]},{"text":[{"text":"Opportunity cost:","bold":true},{"text":" best alternative foregone. "},{"text":"Risk tolerance:","bold":true},{"text":" willingness to take risks. "},{"text":"Risk management:","bold":true},{"text":" assessing potential losses. "},{"text":"Ethical decisions:","bold":true},{"text":" morality, fairness; a step in ethical decision-making is "},{"text":"identifying stakeholders","bold":true},{"text":". "},{"text":"Participative decision-making:","bold":true},{"text":" its key element is "},{"text":"employee involvement","bold":true},{"text":"."}]}]}]},{"number":"3.4","title":"Planning, strategic management and strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning:","bold":true},{"text":" making goals, policies and procedures: defining goals, setting an overall strategy, developing comprehensive plans "},{"text":"to integrate and coordinate","bold":true},{"text":" work. Deciding in advance what, how, when, by whom. Key elements: "},{"text":"goals","bold":true},{"text":", "},{"text":"plans","bold":true},{"text":". It includes "},{"text":"developing and selecting a course of action","bold":true},{"text":" and "},{"text":"decision-making","bold":true},{"text":", never creating problems. Success of a plan depends on "},{"text":"proper planning and execution","bold":true},{"text":"."}]},{"text":[{"text":"It is the "},{"text":"first (primary)","bold":true},{"text":" function, the foundation of the others, at "},{"text":"all levels","bold":true},{"text":". Organizing is to structure as planning is to "},{"text":"goal setting","bold":true},{"text":". Its first step is "},{"text":"setting objectives","bold":true},{"text":"; begin by working out how to satisfy customer needs."}]},{"text":[{"text":"Formal planning:","bold":true},{"text":" specific goals over years, "},{"text":"written","bold":true},{"text":", shared. "},{"text":"Informal:","bold":true},{"text":" general, lacks continuity, unwritten, little sharing."}]},{"text":[{"text":"4 reasons for planning:","bold":true},{"text":" direction; less impact of change; less waste and redundancy; sets control standards."}]},{"text":[{"text":"Criticisms:","bold":true},{"text":" rigidity; replaces intuition; focus on today's competition; reinforces success; a "},{"text":"dynamic environment","bold":true},{"text":" cannot be planned for. Regulations, unions and other environmental forces limit options and "},{"text":"reduce the impact of planning","bold":true},{"text":" on performance."}]},{"text":[{"text":"Strategic management:","bold":true},{"text":" decisions and actions determining "},{"text":"long-run","bold":true},{"text":" performance; uses all management functions; suits all organizations."}]},{"text":[{"text":"6 steps:","bold":true},{"text":" 1 identify "},{"text":"mission, goals, strategies","bold":true},{"text":" (mission = reason for being in business; purpose and direction); 2 "},{"text":"external analysis","bold":true},{"text":" (competitors, laws, labour supply): "},{"text":"opportunities and threats","bold":true},{"text":"; it is finished when managers have an "},{"text":"accurate picture of the external environment","bold":true},{"text":" and are "},{"text":"aware of trends","bold":true},{"text":" that could affect the organization; 3 "},{"text":"internal analysis","bold":true},{"text":": "},{"text":"strengths and weaknesses","bold":true},{"text":"; 4 "},{"text":"formulate","bold":true},{"text":" strategies: develop and evaluate alternatives, choose those that "},{"text":"use strengths and correct weaknesses","bold":true},{"text":"; 5 "},{"text":"implement","bold":true},{"text":"; 6 "},{"text":"evaluate","bold":true},{"text":" (how effective were they?)."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" combined internal and external analysis. "},{"text":"Core competencies:","bold":true},{"text":" major value-creating skills, capabilities, resources, exceptional or unique (e.g. meeting a target market's needs on a large scale; communicating with customers worldwide in their own languages). An organization's "},{"text":"strengths and weaknesses","bold":true},{"text":" play a "},{"text":"key","bold":true},{"text":" role in corporate planning. Strong and weak cultures affect strategy differently, and a culture's "},{"text":"content","bold":true},{"text":" affects which strategies can be pursued; a strong culture is "},{"text":"harder to change","bold":true},{"text":"."}]},{"text":[{"text":"Strategy levels:","bold":true},{"text":" "},{"text":"corporate","bold":true},{"text":" (which businesses, each unit's role); "},{"text":"business/competitive","bold":true},{"text":" (how to compete in each business); "},{"text":"functional","bold":true},{"text":" (supports "},{"text":"business-level","bold":true},{"text":")."}]},{"text":[{"text":"3 corporate strategies:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Growth:","bold":true},{"text":" more markets or products, via concentration, integration, diversification. "},{"text":"Horizontal integration:","bold":true},{"text":" same industry (two airlines merging). "},{"text":"Vertical:","bold":true},{"text":" backward or forward. "},{"text":"Related diversification:","bold":true},{"text":" different but related industries. "},{"text":"Unrelated:","bold":true},{"text":" different, unconnected."}]},{"text":[{"text":"Stability:","bold":true},{"text":" continue as now; fits slow or no growth and industry upheaval."}]},{"text":[{"text":"Renewal:","bold":true},{"text":" addresses decline: "},{"text":"retrenchment","bold":true},{"text":" (deals with weaknesses, stabilises operations, renews resources) and "},{"text":"turnaround","bold":true},{"text":"."}]}]}]},{"text":[{"text":"BCG matrix:","bold":true},{"text":" high growth + high share = "},{"text":"star","bold":true},{"text":"; high growth + low share = "},{"text":"question mark","bold":true},{"text":"; low growth + high share = "},{"text":"cash cow","bold":true},{"text":"; low growth + low share = "},{"text":"dog","bold":true},{"text":" (neither uses nor makes much cash)."}]},{"text":[{"text":"SBUs:","bold":true},{"text":" independent businesses with own strategies, each serving a clearly defined product-market segment. "},{"text":"Competitive advantage:","bold":true},{"text":" a distinct edge; steady quality makes it "},{"text":"sustainable","bold":true},{"text":"."}]},{"text":[{"text":"Porter's 3 strategies:","bold":true},{"text":" "},{"text":"cost leadership","bold":true},{"text":" (lowest cost structure); "},{"text":"differentiation","bold":true},{"text":" (unique in ways customers value, e.g. faster-response systems); "},{"text":"focus","bold":true},{"text":" (advantage in a narrow niche). Some "},{"text":"industries","bold":true},{"text":" are more profitable than others."}]},{"text":[{"text":"Porter's 5 forces:","bold":true},{"text":" "},{"text":"new entrants","bold":true},{"text":" (barriers: economies of scale, brand loyalty); "},{"text":"substitutes","bold":true},{"text":" (switching costs, buyer loyalty); "},{"text":"buyers","bold":true},{"text":"' power; "},{"text":"suppliers","bold":true},{"text":"' power (concentration, substitute inputs); "},{"text":"existing rivalry","bold":true},{"text":" (growth, demand, product differences)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning cannot remove change; it makes managers "},{"text":"anticipate","bold":true},{"text":" it and think about its impact. Research on planning is "},{"text":"positive","bold":true},{"text":"; "},{"text":"quality","bold":true},{"text":" and "},{"text":"implementation","bold":true},{"text":" matter more than extent. Where it failed, the "},{"text":"external environment","bold":true},{"text":" (regulations, unions) was to blame. Labour supply is "},{"text":"external","bold":true},{"text":"."}]},{"text":[{"text":"Strategic weapons:","bold":true},{"text":" customer service (staff training), employee skills, innovation (first to market = "},{"text":"first mover","bold":true},{"text":"), quality, "},{"text":"benchmarking","bold":true},{"text":". Senior managers choose whether innovation focuses on "},{"text":"basic research, product innovation or process development","bold":true},{"text":" (process development improves existing work processes and makes the firm more efficient). "},{"text":"Rule of three:","bold":true},{"text":" three companies usually hold most of the market; only three full-line generalists."}]}]}]},{"number":"3.5","title":"Goals, plans and planning tools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"To "},{"text":"fail to plan","bold":true},{"text":" is to "},{"text":"plan to fail","bold":true},{"text":".\" "},{"text":"Who does the planning","bold":true},{"text":" gives the best understanding of how an organization plans. Planning tools and techniques help managers "},{"text":"prepare confidently for the future","bold":true},{"text":"."}]},{"text":[{"text":"Goals (objectives):","bold":true},{"text":" desired outcomes; same meaning; the "},{"text":"foundation of planning","bold":true},{"text":", they give direction and are the "},{"text":"standard against which actual results are measured","bold":true},{"text":". "},{"text":"Plans:","bold":true},{"text":" resource allocations, schedules, actions to meet goals."}]},{"text":[{"text":"2 goal types:","bold":true},{"text":" financial and strategic. "},{"text":"Stated goals:","bold":true},{"text":" what the organization wants stakeholders to believe; they seem to conflict because different groups (stockholders, customers, employees, the public) are given "},{"text":"different objectives","bold":true},{"text":". "},{"text":"Real goals:","bold":true},{"text":" what members do."}]},{"text":[{"text":"Traditional goal setting:","bold":true},{"text":" top managers set goals, split into subgoals; they grow "},{"text":"less clear and unified","bold":true},{"text":" downward. Each level works toward the goals "},{"text":"assigned to its own area of responsibility","bold":true},{"text":". Clear hierarchy = "},{"text":"means-ends chain","bold":true},{"text":"."}]},{"text":[{"text":"MBO","bold":true},{"text":" ("},{"text":"Peter Drucker","bold":true},{"text":"): goals "},{"text":"jointly","bold":true},{"text":" set, "},{"text":"progress reviewed periodically","bold":true},{"text":", rewards by progress. It "},{"text":"increases","bold":true},{"text":" performance. Weaknesses: poor in changing environments, individual focus, not taken seriously."}]},{"text":[{"text":"Well-written goals:","bold":true},{"text":" outcomes not actions; measurable; timed; challenging but attainable; written; communicated. A "},{"text":"single goal","bold":true},{"text":" tempts unethical behaviour because managers "},{"text":"neglect other important parts of their job just to look good on that one measure","bold":true},{"text":"; no single measure shows success."}]},{"text":[{"text":"Plans by breadth:","bold":true},{"text":" "},{"text":"strategic","bold":true},{"text":" (whole organization, overall goals, positions it in its environment, longer, broader) vs "},{"text":"operational","bold":true},{"text":" (how to achieve goals; lower levels; concerned with "},{"text":"day-to-day operations and specific tasks","bold":true},{"text":")."}]},{"text":[{"text":"By time frame:","bold":true},{"text":" "},{"text":"long-term","bold":true},{"text":" (over 3 years) vs "},{"text":"short-term","bold":true},{"text":" (1 year or less)."}]},{"text":[{"text":"By specificity:","bold":true},{"text":" "},{"text":"specific","bold":true},{"text":" (no room for interpretation, e.g. 2.45 per cent tobacco tax rise over 2 years) vs "},{"text":"directional","bold":true},{"text":" (flexible guidelines; flexibility costs the "},{"text":"clarity","bold":true},{"text":" specific plans provide)."}]},{"text":[{"text":"By frequency of use:","bold":true},{"text":" "},{"text":"single-use","bold":true},{"text":" (unique situation) vs "},{"text":"standing","bold":true},{"text":" (repeated activities, e.g. skateboarding policy)."}]},{"text":[{"text":"3 contingency factors:","bold":true},{"text":" organizational level, environmental uncertainty, length of future commitments ("},{"text":"commitment concept","bold":true},{"text":": plans reach far enough to meet commitments made)."}]},{"text":[{"text":"2 approaches:","bold":true},{"text":" "},{"text":"traditional","bold":true},{"text":" (top managers, helped by planning specialists) and "},{"text":"members take part","bold":true},{"text":" (plans become more than paper)."}]},{"text":[{"text":"Uncertain environments:","bold":true},{"text":" keep formal planning; plans "},{"text":"specific but flexible","bold":true},{"text":"; planning "},{"text":"ongoing","bold":true},{"text":"; \"long term\" has changed. Pushing planning down "},{"text":"flattens","bold":true},{"text":" hierarchy. Issues are "},{"text":"not equally important","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Explain more: planning tools","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Budget:","bold":true},{"text":" numerical plan allocating resources to specific activities (even space); popular as it applies to many kinds of organizations and to "},{"text":"work activities within organizations","bold":true},{"text":"; brings financial discipline across the organization. Many managers dislike preparing budgets, seeing the process as "},{"text":"time-consuming, inflexible, inefficient and ineffective","bold":true},{"text":"."}]},{"text":[{"text":"Gantt chart:","bold":true},{"text":" "},{"text":"Henry Gantt","bold":true},{"text":" (associate of "},{"text":"Frederick Taylor","bold":true},{"text":"), for "},{"text":"scheduling","bold":true},{"text":"; "},{"text":"time horizontal","bold":true},{"text":", activities vertical; compares plan with "},{"text":"actual progress","bold":true},{"text":". "},{"text":"Load chart:","bold":true},{"text":" vertical axis lists departments or "},{"text":"specific resources","bold":true},{"text":"."}]},{"text":[{"text":"PERT:","bold":true},{"text":" schedules "},{"text":"projects","bold":true},{"text":"; activity order and time or costs. "},{"text":"Events:","bold":true},{"text":" end points marking completion of major activities. "},{"text":"Activities:","bold":true},{"text":" time or resources between events. "},{"text":"Slack time:","bold":true},{"text":" possible delay without delaying the project. "},{"text":"Critical path:","bold":true},{"text":" longest sequence."}]},{"text":[{"text":"Break-even analysis:","bold":true},{"text":" "},{"text":"profit projections","bold":true},{"text":" (e.g. an Ikeja store's jacket target); total revenue = "},{"text":"total cost","bold":true},{"text":". Needs price, variable cost per unit, "},{"text":"total fixed costs","bold":true},{"text":". Property taxes are fixed."}]},{"text":[{"text":"Linear programming:","bold":true},{"text":" needs limited resources and an outcome to optimise, so not every allocation problem; applications include choosing "},{"text":"transport routes","bold":true},{"text":" that minimise shipping costs, "},{"text":"sharing an advertising budget","bold":true},{"text":" among plans and "},{"text":"assigning personnel","bold":true},{"text":" to projects; a change in one variable gives an "},{"text":"exactly proportional","bold":true},{"text":" change in the other."}]},{"text":[{"text":"Project management:","bold":true},{"text":" completing a "},{"text":"project","bold":true},{"text":" (one-time, definite start and end) on time, within budget, to specification. "},{"text":"Identify","bold":true},{"text":" activities and resources first. Members stay in permanent work areas, so influence is "},{"text":"communication and persuasion","bold":true},{"text":"."}]},{"text":[{"text":"Scenario (contingency) planning:","bold":true},{"text":" alternative courses for unexpected events; reduces uncertainty by playing out situations; different assumptions give different outcomes; hard for "},{"text":"random events","bold":true},{"text":". Tools never replace managers' "},{"text":"skills and capabilities","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Decision = choice among alternatives; problem = gap; 8 steps."}]},{"text":[{"text":"Rational maximises; bounded satisfices."}]},{"text":[{"text":"Programmed = structured; nonprogrammed = unstructured, uncertainty."}]},{"text":[{"text":"Maximax optimist, maximin pessimist, minimax regret."}]},{"text":[{"text":"Planning = goals and plans; 6 strategic steps."}]},{"text":[{"text":"Growth, stability, renewal; cost leadership, differentiation, focus."}]}]}],"theory":{"itemId":"b1536dbc-f454-5dad-8fa7-0dae17d04b05","question":[{"type":"paragraph","text":[{"text":"Explain the steps in the strategic management process. Distinguish between growth, stability and renewal strategies."}]}]},"practice":[{"topic":"Foundations of Decision Making and Planning","named":false}]}},{"itemId":"ee7efb0c-8198-5380-8487-f0053e33961b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Organization Design and Structure","body":"The six design elements; authority and power; mechanistic vs organic; the four contingency factors; the designs; today's challenges.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The six design elements; authority and power; mechanistic vs organic; the four contingency factors; the designs; today's challenges."}],"lessons":[{"number":"4.1","title":"Organizing, work specialization and departmentalization","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizing:","bold":true},{"text":" arranging and structuring work to accomplish organizational goals. It "},{"text":"follows planning","bold":true},{"text":". Organizing is to "},{"text":"structure","bold":true},{"text":" as planning is to "},{"text":"goal setting","bold":true},{"text":"."}]},{"text":[{"text":"Structure:","bold":true},{"text":" the formal framework by which job tasks are divided, grouped and coordinated. "},{"text":"Chart:","bold":true},{"text":" its picture. "},{"text":"Design:","bold":true},{"text":" developing or changing it."}]},{"text":[{"text":"6 elements of design:","bold":true},{"text":" work specialization, departmentalization, chain of command, span of control, centralization/decentralization, formalization. Together they decide if a structure is "},{"text":"mechanistic or organic","bold":true},{"text":"."}]},{"text":[{"text":"7 purposes of organizing:","bold":true},{"text":" divide work into jobs and departments; assign tasks and responsibilities; coordinate tasks; cluster jobs into units; establish relationships among individuals, groups, departments; establish formal lines of authority; allocate and deploy resources. (\"It creates services\" is not one.)"}]},{"text":[{"text":"Work specialization (division of labour):","bold":true},{"text":" the degree to which tasks are divided into separate jobs; each employee does "},{"text":"part","bold":true},{"text":" of an activity, not the whole."}]},{"text":[{"text":"Departmentalization:","bold":true},{"text":" the basis on which jobs are grouped to achieve goals. "},{"text":"5 types:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Functional:","bold":true},{"text":" by functions or tasks."}]},{"text":[{"text":"Geographic:","bold":true},{"text":" by territory or location."}]},{"text":[{"text":"Product:","bold":true},{"text":" by product line or service."}]},{"text":[{"text":"Process:","bold":true},{"text":" by product or customer "},{"text":"flow","bold":true},{"text":"."}]},{"text":[{"text":"Customer:","bold":true},{"text":" by type of customer and needs. Now more important: tracks customer needs and responds to changes."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Principles:","bold":true},{"text":" "},{"text":"unity of objective","bold":true},{"text":" (the structure must serve the organization's goals); "},{"text":"efficiency","bold":true},{"text":" ("},{"text":"lowest cost, least waste","bold":true},{"text":"); division of work; span of control; "},{"text":"scalar chain","bold":true},{"text":" (line of authority top to bottom); unity of command; "},{"text":"parity of authority and responsibility","bold":true},{"text":" (in balance); "},{"text":"delegation of authority","bold":true},{"text":" (decision power at the proper level); balance, flexibility, continuity. "},{"text":"Publicity","bold":true},{"text":" is not a principle."}]},{"text":[{"text":"Early view: endless source of productivity. Too far: boredom, fatigue, absenteeism, turnover. More tasks per worker "},{"text":"reduces","bold":true},{"text":" it."}]},{"text":[{"text":"Cross-functional team:","bold":true},{"text":" people from different functions."}]}]}]},{"number":"4.2","title":"Chain of command, authority, power and span of control","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Chain of command:","bold":true},{"text":" the unbroken line of authority from top to lowest levels; shows who reports to whom. The formal structure of authority is the "},{"text":"hierarchy","bold":true},{"text":"."}]},{"text":[{"text":"Authority:","bold":true},{"text":" the rights of a position to tell people what to do and expect compliance. "},{"text":"Responsibility:","bold":true},{"text":" obligation to perform a duty."}]},{"text":[{"text":"Unity of command:","bold":true},{"text":" each person reports to "},{"text":"only one","bold":true},{"text":" manager (Fayol; keeps authority continuous)."}]},{"text":[{"text":"Delegation:","bold":true},{"text":" transferring authority to another person for specific duties."}]},{"text":[{"text":"Line authority:","bold":true},{"text":" directs employees' work; follows the chain of command. "},{"text":"Staff authority:","bold":true},{"text":" supports, assists, advises and reduces the load of line managers."}]},{"text":[{"text":"Authority","bold":true},{"text":" is a "},{"text":"right","bold":true},{"text":", from the "},{"text":"position","bold":true},{"text":". "},{"text":"Power","bold":true},{"text":" is a "},{"text":"capacity to influence","bold":true},{"text":" decisions and is the "},{"text":"broader","bold":true},{"text":" concept; authority is part of it."}]},{"text":[{"text":"5 sources of power:","bold":true},{"text":" "},{"text":"legitimate","bold":true},{"text":" (position; same as authority), "},{"text":"coercive","bold":true},{"text":" (ability to punish or control), "},{"text":"reward","bold":true},{"text":" (pay, bonuses, praise), "},{"text":"expert","bold":true},{"text":" (special knowledge), "},{"text":"referent","bold":true},{"text":" (personal traits others admire)."}]},{"text":[{"text":"Span of control:","bold":true},{"text":" the number of employees a manager can efficiently and effectively supervise. It decides the number of management "},{"text":"levels","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Authority stays with the post when holder leaves. Power without authority: a secretary controlling access."}]},{"text":[{"text":"Chain of command matters less today: "},{"text":"information technology and empowered employees","bold":true},{"text":"."}]},{"text":[{"text":"Narrow span = tall. Wide span = flat","bold":true},{"text":" (few levels). Not \"thin\"."}]},{"text":[{"text":"4,096 operatives: span 4 needs "},{"text":"1,365","bold":true},{"text":" managers, "},{"text":"7","bold":true},{"text":" levels (with operatives); span 8 needs "},{"text":"585","bold":true},{"text":", "},{"text":"5","bold":true},{"text":" levels."}]},{"text":[{"text":"Wider span is more "},{"text":"efficient","bold":true},{"text":" (lower cost, faster decisions, better communication). Too wide: effectiveness falls (too little supervision); many people to control is the disadvantage. "},{"text":"Trend:","bold":true},{"text":" wider spans (cut costs, speed decisions, empower staff)."}]},{"text":[{"text":"Wider span when:","bold":true},{"text":" staff well trained; tasks similar and simple; staff close together; standardized procedures; good information system. Not a factor: organization age."}]}]}]},{"number":"4.3","title":"Centralization, formalization, mechanistic vs organic, contingency factors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Centralization:","bold":true},{"text":" decision making concentrated at upper levels. "},{"text":"Decentralization:","bold":true},{"text":" lower-level managers give input or make decisions. "},{"text":"Employee empowerment:","bold":true},{"text":" increasing workers' decision-making discretion."}]},{"text":[{"text":"Formalization:","bold":true},{"text":" the degree to which jobs are standardized and guided by rules and procedures."}]}]},{"type":"table","header":[[{"text":"Mechanistic"}],[{"text":"Organic"}]],"rows":[[[{"text":"Rigid, tightly controlled, efficient"}],[{"text":"Flexible; changes quickly"}]],[[{"text":"Specialized, standardized jobs"}],[{"text":"Cross-functional, cross-hierarchical teams"}]],[[{"text":"Clear chain of command"}],[{"text":"Free flow of information"}]],[[{"text":"Narrow spans"}],[{"text":"Wide spans"}]],[[{"text":"Centralized, high formalization"}],[{"text":"Decentralized, low formalization"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 contingency factors:","bold":true},{"text":" "},{"text":"strategy, size, technology, environmental uncertainty.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trend:","bold":true},{"text":" decentralization, for flexibility and responsiveness. "},{"text":"Centralize when:","bold":true},{"text":" stable environment; less capable lower managers; large firm; significant decisions; crisis. "},{"text":"Decentralize when:","bold":true},{"text":" uncertain environment; capable managers wanting a say; minor decisions; open culture; geographic spread. Every decision needing the unit head's sign-off = centralized."}]},{"text":[{"text":"Strategy:","bold":true},{"text":" "},{"text":"structure follows strategy.","bold":true},{"text":" 3 focuses: "},{"text":"innovation","bold":true},{"text":" (meaningful, unique new products) = "},{"text":"organic","bold":true},{"text":"; "},{"text":"cost minimization","bold":true},{"text":" = "},{"text":"mechanistic","bold":true},{"text":"; "},{"text":"imitation","bold":true},{"text":" (copying market leaders to cut risk) = a "},{"text":"mix","bold":true},{"text":". Diversification is not one."}]},{"text":[{"text":"Size:","bold":true},{"text":" as an organization takes on more employees its structure becomes more "},{"text":"specialized","bold":true},{"text":" (not informal): more departmentalization, centralization, rules (not decentralization), so more "},{"text":"mechanistic","bold":true},{"text":"."}]},{"text":[{"text":"Technology: Joan Woodward","bold":true},{"text":" studied small manufacturing firms in "},{"text":"southern England","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit","bold":true},{"text":" (units or small batches): least complex; organic."}]},{"text":[{"text":"Mass","bold":true},{"text":" ("},{"text":"large-batch","bold":true},{"text":"): moderate; "},{"text":"mechanistic","bold":true},{"text":"."}]},{"text":[{"text":"Process","bold":true},{"text":" (continuous): "},{"text":"most","bold":true},{"text":" complex; organic."}]}]}]},{"text":[{"text":"Environment:","bold":true},{"text":" stable suits mechanistic; dynamic, uncertain suits "},{"text":"organic","bold":true},{"text":". Forces towards organic: global competition, rivals' faster innovation, customers wanting better quality and faster delivery."}]}]}]},{"number":"4.4","title":"Traditional and contemporary designs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional","bold":true},{"text":" (more mechanistic): "},{"text":"simple, functional, divisional.","bold":true},{"text":" Structures grow simple, then functional, then divisional, becoming more "},{"text":"specialized","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple:","bold":true},{"text":" low departmentalization, "},{"text":"wide spans","bold":true},{"text":", authority centralized in one person, little formalization. Suits "},{"text":"very small firms with few employees","bold":true},{"text":" (even one selling worldwide). Strength: fast, flexible, cheap. Weakness: relying on one person is risky."}]},{"text":[{"text":"Functional:","bold":true},{"text":" groups similar occupational specialties. Strength: cost savings from specialization. Weakness: functions lose sight of the whole; specialists isolated."}]},{"text":[{"text":"Divisional:","bold":true},{"text":" "},{"text":"autonomous, self-contained","bold":true},{"text":" units linked by a "},{"text":"product or service","bold":true},{"text":". Strength: "},{"text":"focus on results","bold":true},{"text":". Weakness: "},{"text":"duplication","bold":true},{"text":" of activities and resources."}]}]}]},{"text":[{"text":"Contemporary:","bold":true},{"text":" team, matrix, project, boundaryless, learning organization."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Team:","bold":true},{"text":" whole organization of work teams; "},{"text":"empowerment","bold":true},{"text":" most important."}]},{"text":[{"text":"Matrix:","bold":true},{"text":" functional specialists assigned to projects under a "},{"text":"project manager","bold":true},{"text":"; functional plus "},{"text":"product","bold":true},{"text":" departmentalization."}]},{"text":[{"text":"Project:","bold":true},{"text":" employees "},{"text":"continuously","bold":true},{"text":" work on projects; advanced matrix."}]},{"text":[{"text":"Boundaryless:","bold":true},{"text":" not limited by horizontal, vertical or external boundaries."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Team:","bold":true},{"text":" fewer barriers between functions; weakness: "},{"text":"no clear chain of command","bold":true},{"text":"."}]},{"text":[{"text":"Matrix:","bold":true},{"text":" "},{"text":"two bosses","bold":true},{"text":" (functional and project manager), so it "},{"text":"breaks unity of command","bold":true},{"text":". Strength: fluid, flexible. Weaknesses: complex assignments; task and personality conflicts."}]},{"text":[{"text":"Project:","bold":true},{"text":" no formal department to return to between projects."}]},{"text":[{"text":"Boundaries:","bold":true},{"text":" horizontal = between "},{"text":"functions","bold":true},{"text":"; vertical = between "},{"text":"levels","bold":true},{"text":"; external = with customers, suppliers. Cross-level teams and outside agencies remove them; "},{"text":"virtual","bold":true},{"text":" or "},{"text":"network","bold":true},{"text":" designs minimize them."}]},{"text":[{"text":"3 boundaryless forms:","bold":true},{"text":" "},{"text":"virtual","bold":true},{"text":" (small full-time core plus outside specialists hired "},{"text":"temporarily","bold":true},{"text":"); "},{"text":"network","bold":true},{"text":" (small core "},{"text":"outsources","bold":true},{"text":" major functions such as manufacturing, accounting, payroll); "},{"text":"modular","bold":true},{"text":" (suppliers make "},{"text":"components","bold":true},{"text":", the firm assembles)."}]}]}]},{"number":"4.5","title":"Today's design challenges","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"4 challenges:","bold":true},{"text":" keeping employees connected (linking dispersed or mobile staff through "},{"text":"technology","bold":true},{"text":"); managing global structural issues (understand how "},{"text":"culture shapes structure","bold":true},{"text":"); building a learning organization; designing flexible work arrangements."}]},{"text":[{"text":"Learning organization:","bold":true},{"text":" capacity to continuously learn, adapt and change. Ability to "},{"text":"learn and apply","bold":true},{"text":" may be its only lasting advantage. It needs "},{"text":"information","bold":true},{"text":"."}]},{"text":[{"text":"5 flexible work arrangements:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Telecommuting:","bold":true},{"text":" working from home, linked by technology."}]},{"text":[{"text":"Compressed workweek:","bold":true},{"text":" longer days, fewer days."}]},{"text":[{"text":"Flextime:","bold":true},{"text":" set weekly hours; staff vary start and finish within limits."}]},{"text":[{"text":"Job sharing:","bold":true},{"text":" two or more people split one full-time job."}]},{"text":[{"text":"Contingent workforce:","bold":true},{"text":" temporary, freelance or contract workers, as demand requires."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learning organization features:","bold":true},{"text":" design = boundaryless, teams, empowerment; information shared openly, timely, accurately; leadership = shared vision, collaboration; culture = strong relationships, community, caring, trust. All members help solve work problems."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizing follows planning; 6 elements; 5 departmentalizations."}]},{"text":[{"text":"Authority = right; power = broader; one boss."}]},{"text":[{"text":"Narrow span = tall; wide = flat, efficient."}]},{"text":[{"text":"Mechanistic = rigid; organic = flexible."}]},{"text":[{"text":"Contingency: strategy, size, technology, environment."}]},{"text":[{"text":"Traditional: simple, functional, divisional."}]}]}],"theory":{"itemId":"829a57bc-6a83-58b7-8f63-2b5338a3a853","question":[{"type":"paragraph","text":[{"text":"Explain the six key elements of organizational design."}]}]},"practice":[{"topic":"Organization Design and Structure","named":false}]}},{"itemId":"81e93b67-fa80-5cc7-86d3-c07a2d7b96b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Managing Human Resources","body":"The 8 HRM activities.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The 8 HRM activities."}],"lessons":[{"number":"5.1","title":"Why HRM matters, the HRM process and outside influences","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HRM:","bold":true},{"text":" getting, training, keeping and rewarding the right people. Old name: "},{"text":"staffing","bold":true},{"text":" (includes appraisal; not budgeting)."}]},{"text":[{"text":"3 reasons HRM matters:","bold":true},{"text":" "},{"text":"competitive advantage","bold":true},{"text":", "},{"text":"strategy","bold":true},{"text":", effect on "},{"text":"performance","bold":true},{"text":"."}]},{"text":[{"text":"High-performance work practices:","bold":true},{"text":" raise individual and organizational performance, e.g. self-managed teams, decentralised decisions, flexible jobs, open communication, performance-based pay, person-job fit."}]},{"text":[{"text":"8 activities, 3 groups:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Identify and select competent employees: HR planning (1), recruitment and decruitment (2), selection (3)."}]},{"text":[{"text":"Give up-to-date skills and knowledge: orientation (4), training (5)."}]},{"text":[{"text":"Retain competent, high-performing employees: performance management (6), compensation and benefits (7), career development (8)."}]}]}]},{"text":[{"text":"External factors:","bold":true},{"text":" labour unions, laws and regulations, demographic trends; the whole process sits inside the external environment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour union:","bold":true},{"text":" represents workers via "},{"text":"collective bargaining","bold":true},{"text":", giving a "},{"text":"collective bargaining agreement","bold":true},{"text":" (pay, hours, conditions)."}]},{"text":[{"text":"Nigeria: "},{"text":"NLC","bold":true},{"text":" (umbrella body of trade unions); "},{"text":"ASUU","bold":true},{"text":" (university academic staff union); "},{"text":"Labour Act","bold":true},{"text":" (law on hiring, pay, dismissal)."}]},{"text":[{"text":"Affirmative action programmes:","bold":true},{"text":" improve protected groups' position (hiring, promotion). "},{"text":"Demographic trends:","bold":true},{"text":" diverse, ageing workforce. "},{"text":"Hugo Munsterberg","bold":true},{"text":", father of industrial psychology: scientific selection."}]}]}]},{"number":"5.2","title":"HR planning, recruitment and decruitment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HR planning","bold":true},{"text":" ("},{"text":"employment planning","bold":true},{"text":"): right number and kinds of capable people, right places, right times. "},{"text":"2 steps:","bold":true},{"text":" assess current human resources, then meet future needs (from mission, goals, strategy, demand)."}]},{"text":[{"text":"Human resource inventory:","bold":true},{"text":" record of current employees' education, past jobs, languages, skills."}]},{"text":[{"text":"Job analysis","bold":true},{"text":" (first): defines jobs and needed behaviours; produces:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job description:","bold":true},{"text":" written statement of what the job is: what the jobholder does, how, why. The "},{"text":"job","bold":true},{"text":"."}]},{"text":[{"text":"Job specification:","bold":true},{"text":" minimum qualifications (knowledge, skills, attitudes) for the job. The "},{"text":"person","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Recruitment:","bold":true},{"text":" locating, identifying, attracting capable applicants. "},{"text":"Decruitment:","bold":true},{"text":" reducing the workforce."}]},{"text":[{"text":"7 decruitment options:","bold":true},{"text":" "},{"text":"firing","bold":true},{"text":" (permanent, involuntary); "},{"text":"layoffs","bold":true},{"text":" (temporary, involuntary); "},{"text":"attrition","bold":true},{"text":" (not filling jobs left by resignations or retirements, no one forced out); "},{"text":"transfers","bold":true},{"text":" (sideways or downward, usually no cost cut, balance labour inside); "},{"text":"reduced workweeks","bold":true},{"text":" (cutting everyone's weekly hours instead of letting people go); "},{"text":"early retirements","bold":true},{"text":" (incentives for older, senior staff); "},{"text":"job sharing","bold":true},{"text":" (usually two part-timers share one full-time job)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recruitment sources","bold":true},{"text":" (advantage; disadvantage):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal search: low cost, morale, known candidates; limited supply, no diversity gain."}]},{"text":[{"text":"Employee referrals: staff know the job, stake their name; no diversity gain."}]},{"text":[{"text":"Adverts, internet: many unqualified applicants."}]},{"text":[{"text":"School and college: large pool; mostly entry-level."}]},{"text":[{"text":"Public agencies: low cost; less skilled."}]},{"text":[{"text":"Private agencies (\"headhunters\"): careful screening; costly, little commitment."}]},{"text":[{"text":"Temporary help: short-term needs; expensive."}]}]}]}]}]},{"number":"5.3","title":"Selection","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selection:","bold":true},{"text":" screening applicants to hire the most appropriate; "},{"text":"prediction","bold":true},{"text":"."}]},{"text":[{"text":"4 outcomes:","bold":true},{"text":" two correct decisions (accepting someone who succeeds; rejecting someone who would have failed), two errors. "},{"text":"Accept error:","bold":true},{"text":" hiring someone who performs poorly (costs: training, poor work, firing and rehiring). "},{"text":"Reject error:","bold":true},{"text":" rejecting someone who would have done well (costs: discrimination claims, losing talent to rivals)."}]},{"text":[{"text":"Validity:","bold":true},{"text":" proven relationship between a device and a criterion such as later job performance (predicts). "},{"text":"Reliability:","bold":true},{"text":" measures the same thing "},{"text":"consistently","bold":true},{"text":". Reliable need not be valid."}]},{"text":[{"text":"6 selection devices:","bold":true},{"text":" application forms, written tests, performance-simulation tests, interviews, background investigations, physical examinations."}]},{"text":[{"text":"Realistic job preview (RJP):","bold":true},{"text":" "},{"text":"positive and negative","bold":true},{"text":" information on job and company; raises satisfaction, lowers turnover."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Application forms:","bold":true},{"text":" basic facts; screen out unqualified applicants. "},{"text":"Written tests:","bold":true},{"text":" intelligence, aptitude, personality, integrity."}]},{"text":[{"text":"Performance-simulation tests","bold":true},{"text":" use actual job behaviour. "},{"text":"Work sampling:","bold":true},{"text":" small replica of the job, central tasks performed; routine, standard jobs. "},{"text":"Assessment centres:","bold":true},{"text":" interviews, problem-solving, group exercises, panel-judged; test "},{"text":"managerial potential","bold":true},{"text":"."}]},{"text":[{"text":"Interviews:","bold":true},{"text":" more valid, reliable if "},{"text":"structured","bold":true},{"text":" (same planned questions). "},{"text":"Behavioural interview:","bold":true},{"text":" how candidates handled real past situations."}]},{"text":[{"text":"Background investigations:","bold":true},{"text":" check application facts and references; references have little value (referees say only good things). "},{"text":"Physical examinations:","bold":true},{"text":" jobs with physical demands; sometimes insurance."}]},{"text":[{"text":"Weber: choosing by technical qualifications is "},{"text":"formal selection","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Orientation and training","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Orientation:","bold":true},{"text":" introducing new employees to the job and organization; moves them from "},{"text":"outsider to insider","bold":true},{"text":", lowers anxiety, makes early quitting less likely."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Work unit:","bold":true},{"text":" unit goals, how the job adds to them, co-workers."}]},{"text":[{"text":"Organization:","bold":true},{"text":" company goals, history, philosophy, rules, HR policies (pay, overtime, leave, fringe benefits)."}]}]}]},{"text":[{"text":"Training:","bold":true},{"text":" building job skills and knowledge to do jobs better; raises performance."}]},{"text":[{"text":"Training methods, 2 groups:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional:","bold":true},{"text":" on-the-job training, job rotation, mentoring and coaching, experiential exercises (role play, simulations), workbooks, manuals, classroom lectures."}]},{"text":[{"text":"Technology-based:","bold":true},{"text":" CDs, DVDs, video and audio recordings, videoconferencing, teleconferencing, e-learning (internet-based)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job rotation:","bold":true},{"text":" sideways moves to learn several jobs. "},{"text":"Mentoring and coaching:","bold":true},{"text":" experienced employee advises a newer one. "},{"text":"General","bold":true},{"text":" training: communication, computer skills, customer service. "},{"text":"Specific:","bold":true},{"text":" safety, leadership, diversity awareness, product knowledge, ethics."}]},{"text":[{"text":"Signs training is needed: falling output, poorer quality, more accidents, new technology. Training fixes lack of "},{"text":"ability","bold":true},{"text":"."}]}]}]},{"number":"5.5","title":"Performance management, pay, retention and careers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Performance management system:","bold":true},{"text":" setting standards and appraising performance for objective HR decisions and records."}]},{"text":[{"text":"7 appraisal methods","bold":true},{"text":" (advantage; disadvantage):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Written essay:","bold":true},{"text":" writes strengths, weaknesses, past performance, potential; reflects writer's skill."}]},{"text":[{"text":"Critical incidents:","bold":true},{"text":" records behaviours separating effective from ineffective work; rich examples; slow, no numbers."}]},{"text":[{"text":"Graphic rating scales:","bold":true},{"text":" rates factors on a 1 to 5 scale; quick, numbers; little depth."}]},{"text":[{"text":"BARS:","bold":true},{"text":" rates specific job behaviours, "},{"text":"combining critical incidents and graphic rating scales","bold":true},{"text":"; slow, hard to build."}]},{"text":[{"text":"Multiperson comparisons:","bold":true},{"text":" compare one person with others; hard with many, legal concerns."}]},{"text":[{"text":"MBO:","bold":true},{"text":" judged on achieving agreed goals; slow."}]},{"text":[{"text":"360-degree:","bold":true},{"text":" feedback from supervisors, co-workers, subordinates, customers, self; slow."}]}]}]},{"text":[{"text":"3 multiperson comparisons:","bold":true},{"text":" "},{"text":"group order ranking","bold":true},{"text":" (top fifth etc.); "},{"text":"individual ranking","bold":true},{"text":" (best to worst); "},{"text":"paired comparison","bold":true},{"text":" (each against every other). These are "},{"text":"relative","bold":true},{"text":"; other methods are "},{"text":"absolute","bold":true},{"text":"."}]},{"text":[{"text":"Skill-based pay:","bold":true},{"text":" rewards demonstrable skills. "},{"text":"Variable pay:","bold":true},{"text":" pay depends on performance."}]},{"text":[{"text":"Compensation:","bold":true},{"text":" base pay, incentives, "},{"text":"benefits","bold":true},{"text":" (nonwage extras: health care, pensions, leave)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discipline:","bold":true},{"text":" actions to enforce standards and rules. "},{"text":"Employee counselling:","bold":true},{"text":" helps employees overcome performance problems. Cannot do it: train or coach. Will not: discipline or counsel."}]},{"text":[{"text":"Pay-level factors:","bold":true},{"text":" tenure, performance, kind of job, kind of business, unionised or not, labour- or capital-intensive, management's pay philosophy, location, profitability, size."}]},{"text":[{"text":"Retention:","bold":true},{"text":" keeping satisfied employees (fair pay, benefits, recognition, development). "},{"text":"Career:","bold":true},{"text":" sequence of positions over a lifetime. "},{"text":"Career development:","bold":true},{"text":" helps employees plan and grow careers in the organization."}]}]}]},{"number":"5.6","title":"Current HRM issues","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Downsizing:","bold":true},{"text":" planned elimination of jobs."}]},{"text":[{"text":"Layoff-survivor sickness:","bold":true},{"text":" attitudes, perceptions, behaviours of employees who "},{"text":"remain","bold":true},{"text":" after involuntary cuts (insecurity, unfairness, guilt, stress, lower motivation)."}]},{"text":[{"text":"Sexual harassment:","bold":true},{"text":" unwanted action or activity of a sexual nature that explicitly or implicitly affects employment, performance or work environment. "},{"text":"Quid pro quo:","bold":true},{"text":" job benefit tied to sexual favours. "},{"text":"Hostile environment:","bold":true},{"text":" conduct makes the workplace offensive or intimidating, no job benefit. From a manager or co-worker, against men or women."}]},{"text":[{"text":"Workplace spirituality:","bold":true},{"text":" culture whose values promote purpose through meaningful work in the context of community; not organized religion."}]},{"text":[{"text":"5 features of a spiritual organization:","bold":true},{"text":" strong sense of purpose, focus on individual development, trust and openness, employee empowerment, toleration of employee expression."}]},{"text":[{"text":"HR costs to control:","bold":true},{"text":" "},{"text":"health care","bold":true},{"text":" (wellness programmes, healthy-habit rewards) and "},{"text":"pensions","bold":true},{"text":" (reduce or redesign plans)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Downsizing:","bold":true},{"text":" give leavers notice, severance pay, outplacement. Survivors: let them talk, explain reasons."}]},{"text":[{"text":"Preventing harassment:","bold":true},{"text":" written policy, training, safe reporting, prompt investigation. "},{"text":"Managing diversity:","bold":true},{"text":" wider recruiting net, bias-free selection, diversity training."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"8 activities, 3 groups."}]},{"text":[{"text":"Job description = job; specification = person."}]},{"text":[{"text":"Firing permanent, layoff temporary."}]},{"text":[{"text":"Validity predicts; reliability is consistent."}]},{"text":[{"text":"BARS = critical incidents + graphic rating scales."}]},{"text":[{"text":"Skill-based pay: skills; variable: performance."}]}]}],"theory":{"itemId":"07639d6e-7ae4-5601-b110-361c95df96aa","question":[{"type":"paragraph","text":[{"text":"Explain the HRM process and describe four methods of appraising performance."}]}]},"practice":[{"topic":"Managing Human Resources","named":false}]}},{"itemId":"147675a1-c1bd-5b7e-8be4-0a37e4ef4372","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Managing Change and Innovation","body":"Forces and agents of change, Lewin, OD, resistance, stress, innovation.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"Forces and agents of change, Lewin, OD, resistance, stress, innovation."}],"lessons":[{"number":"6.1","title":"Change, its forces and its agents","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizational change:","bold":true},{"text":" any alteration of people, structure or technology in an organization."}]},{"text":[{"text":"Change agent:","bold":true},{"text":" a person who acts as a catalyst and takes responsibility for managing the change process."}]},{"text":[{"text":"External forces (5):","bold":true},{"text":" 1. marketplace (competition: rival firms and their new products or prices); 2. government laws and regulations; 3. technology; 4. labour markets; 5. economic changes (interest rates, inflation, recession)."}]},{"text":[{"text":"Internal forces (4):","bold":true},{"text":" 1. changes in organizational strategy; 2. changes in the workforce (age, education, gender, nationality); 3. new equipment; 4. changes in employee attitudes."}]}]},{"type":"table","header":[[{"text":"Change agent"}],[{"text":"Strength"}],[{"text":"Weakness"}]],"rows":[[[{"text":"Internal manager","bold":true}],[{"text":"Knows the organization; more thoughtful as he or she lives with the results"}],[{"text":"May be overcautious"}]],[[{"text":"Outside consultant","bold":true}],[{"text":"Objective view that insiders lack"}],[{"text":"Knows little of the organization's history, culture, procedures and people; may push more drastic change (does not live with the results)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sorting: laws, a skilled-labour shortage = external. A new market = strategy; new machines = equipment (internal)."}]},{"text":[{"text":"Change agents: managers, nonmanagers (e.g. HR change specialists) or outside consultants; large changes often use consultants."}]}]}]},{"number":"6.2","title":"How change happens, types of change and OD","mustKnow":[{"type":"paragraph","text":[{"text":"2 views of change:","bold":true}]},{"type":"table","header":[[],[{"text":"Calm waters"}],[{"text":"White-water rapids"}]],"rows":[[[{"text":"Picture"}],[{"text":"Large ship on a calm sea, storm now and then"}],[{"text":"Small raft on constant, rough rapids"}]],[[{"text":"Change is"}],[{"text":"An occasional break in stable life; fits "},{"text":"Lewin's 3 steps","bold":true}],[{"text":"Natural and constant; constant uncertainty and adjustment"}]],[[{"text":"Managing it"}],[{"text":"Done once, then things settle"}],[{"text":"A continual process"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lewin's 3 steps, in order:","bold":true},{"text":" 1. "},{"text":"unfreezing","bold":true},{"text":" the status quo; 2. "},{"text":"changing","bold":true},{"text":" to a new state; 3. "},{"text":"refreezing","bold":true},{"text":" to make the change permanent."}]},{"text":[{"text":"Status quo:","bold":true},{"text":" an equilibrium state. "},{"text":"Driving forces","bold":true},{"text":" push behaviour away from it; "},{"text":"restraining forces","bold":true},{"text":" hold back movement away from it."}]},{"text":[{"text":"3 ways to unfreeze:","bold":true},{"text":" increase driving forces; decrease restraining forces; combine both."}]},{"text":[{"text":"3 types of change:","bold":true},{"text":" "},{"text":"structure","bold":true},{"text":" (elements: authority relationships, coordinating mechanisms, job design, span of control, formalization, departmentalization; e.g. merging departments, wider spans of control, cutting layers; attitudes and perceptions are NOT structure but people change); "},{"text":"technology","bold":true},{"text":" (equipment, tools, work processes; e.g. automation, computerization, new machines; "},{"text":"automation","bold":true},{"text":" replaces certain tasks done by people with machines); "},{"text":"people","bold":true},{"text":" (attitudes, expectations, perceptions, behaviour; e.g. training, team building, OD)."}]},{"text":[{"text":"Organizational development (OD):","bold":true},{"text":" techniques or programmes to change people and the nature and quality of interpersonal work relationships. It is the main tool for people change."}]},{"text":[{"text":"4 OD techniques:","bold":true}]}]},{"type":"table","header":[[{"text":"Technique"}],[{"text":"What it does"}]],"rows":[[[{"text":"Survey feedback","bold":true}],[{"text":"Questionnaire assesses attitudes and perceptions about the change; results used to spot and solve problems"}]],[[{"text":"Process consultation","bold":true}],[{"text":"Outside consultant helps managers see how interpersonal processes affect the way work is done"}]],[[{"text":"Team building","bold":true}],[{"text":"Helps a work group set goals, build good relationships, clarify each member's role and responsibilities"}]],[[{"text":"Intergroup development","bold":true}],[{"text":"Changes the attitudes, stereotypes and perceptions work groups hold about each other"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lewin treats change as a "},{"text":"break","bold":true},{"text":" in equilibrium. Refreezing stabilises the new situation so it is not short-lived: balance the forces again, e.g. reward the new behaviour."}]},{"text":[{"text":"White-water fits today's uncertain environments (a course whose timetable keeps changing)."}]},{"text":[{"text":"Team building is "},{"text":"within","bold":true},{"text":" one group; intergroup development is "},{"text":"between","bold":true},{"text":" groups."}]}]}]},{"number":"6.3","title":"Resistance to change and how to reduce it","mustKnow":[{"type":"paragraph","text":[{"text":"4 reasons for resistance:","bold":true},{"text":" 1. "},{"text":"uncertainty","bold":true},{"text":" (known replaced by unknown); 2. "},{"text":"habit","bold":true},{"text":" (preferring routine); 3. "},{"text":"concern over personal loss","bold":true},{"text":" (status, money, authority, friendships); 4. "},{"text":"belief that the change is not in the organization's best interest","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"6 techniques to reduce resistance:","bold":true}]},{"type":"table","header":[[{"text":"Technique"}],[{"text":"Use when"}],[{"text":"Advantage"}],[{"text":"Drawback"}]],"rows":[[[{"text":"Education and communication","bold":true},{"text":" (memos, meetings)"}],[{"text":"Misinformation"}],[{"text":"Clears up misunderstandings"}],[{"text":"May not work when trust and credibility are lacking"}]],[[{"text":"Participation","bold":true},{"text":" (involve those affected in the decision)"}],[{"text":"Resisters have expertise"}],[{"text":"Raises involvement and acceptance"}],[{"text":"Takes time; may give a poor solution"}]],[[{"text":"Facilitation and support","bold":true},{"text":" (counselling, training, paid leave)"}],[{"text":"Resisters are fearful and anxious"}],[{"text":"Helps people adjust"}],[{"text":"Can be expensive; no guarantee of success"}]],[[{"text":"Negotiation","bold":true},{"text":" (exchange something of value, e.g. special pay package)"}],[{"text":"Powerful group"}],[{"text":"Can \"buy\" commitment"}],[{"text":"Can be costly; opens the door for others to demand deals"}]],[[{"text":"Manipulation","bold":true},{"text":" (covert influence: twisting facts) and "},{"text":"co-optation","bold":true},{"text":" (manipulation plus participation: \"buying off\" resistance leaders with a key role)"}],[{"text":"Powerful group's support needed"}],[{"text":"Cheap and easy way to gain support"}],[{"text":"Can backfire; change agent may lose credibility"}]],[[{"text":"Coercion","bold":true},{"text":" (direct threats: transfer, loss of promotion, poor reviews)"}],[{"text":"Powerful group's support needed"}],[{"text":"Cheap and easy way to gain support"}],[{"text":"May be illegal; may undermine the change agent's credibility"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Resistance can give stability and lead to useful debate, but it slows adaptation. People with a lot invested in the current system (long-serving staff) resist most."}]},{"text":[{"text":"Change often creates "},{"text":"stress","bold":true},{"text":"."}]}]}]},{"number":"6.4","title":"Employee stress","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress:","bold":true},{"text":" the adverse reaction people have to excessive pressure placed on them from extraordinary demands, constraints or opportunities."}]},{"text":[{"text":"Constraints:","bold":true},{"text":" barriers that keep us from doing what we desire. "},{"text":"Demands:","bold":true},{"text":" the loss of something desired."}]},{"text":[{"text":"3 groups of symptoms:","bold":true},{"text":" "},{"text":"physical","bold":true},{"text":" (faster heart and breathing rates, higher blood pressure, headaches); "},{"text":"psychological","bold":true},{"text":" (job dissatisfaction, tension, irritability, boredom, procrastination); "},{"text":"behavioural","bold":true},{"text":" (absenteeism, turnover, more smoking or drinking, rapid speech, fidgeting, sleep problems)."}]},{"text":[{"text":"2 groups of causes:","bold":true},{"text":" 1. "},{"text":"organizational (job-related):","bold":true},{"text":" task demands, role demands, interpersonal demands, organization structure, organizational leadership; 2. "},{"text":"personal:","bold":true},{"text":" family issues, personal economic problems, personality type."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Task demands:","bold":true},{"text":" the job itself (design, conditions, layout). "},{"text":"Interpersonal demands:","bold":true},{"text":" co-workers (poor support). "},{"text":"Organization structure:","bold":true},{"text":" too many rules, little say in decisions. "},{"text":"Organizational leadership:","bold":true},{"text":" a style creating tension, fear and anxiety, with unrealistic pressure to perform."}]},{"text":[{"text":"Stress is not always bad (it can bring opportunity); excess is the problem. "},{"text":"Role conflict","bold":true},{"text":" = expectations hard to meet at once; "},{"text":"role overload","bold":true},{"text":" = more expected than time allows; "},{"text":"role ambiguity","bold":true},{"text":" = expectations unclear."}]},{"text":[{"text":"Type A:","bold":true},{"text":" chronic time urgency, excessive competitive drive, difficulty enjoying leisure. "},{"text":"Type B:","bold":true},{"text":" relaxed, no time urgency or impatience. The harmful part of Type A is "},{"text":"hostility and anger","bold":true},{"text":"."}]},{"text":[{"text":"Reducing stress:","bold":true},{"text":" employee selection (match people to jobs); realistic job preview during selection; clear goals with feedback (MBO) to cut role ambiguity; job redesign; communication during change; employee assistance programmes (EAPs: counselling for personal problems); wellness programmes (fitness, healthy eating, stopping smoking)."}]}]}]},{"number":"6.5","title":"Creativity and innovation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Creativity:","bold":true},{"text":" the ability to combine ideas in a unique way or to make unusual associations between ideas. It produces the idea."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" taking a creative idea and turning it into a useful product, service or method of operation. It improves productivity and competitiveness."}]},{"text":[{"text":"Systems view of innovation:","bold":true},{"text":" 1. "},{"text":"inputs:","bold":true},{"text":" creative people and groups; 2. "},{"text":"transformation:","bold":true},{"text":" a creative environment, process and situation; 3. "},{"text":"outputs:","bold":true},{"text":" innovative products and work methods."}]},{"text":[{"text":"Idea champions:","bold":true},{"text":" individuals who actively and enthusiastically support new ideas, build support, overcome resistance and make sure innovations are implemented. Traits: very high self-confidence, persistence, energy, risk-taking."}]},{"text":[{"text":"3 sets of variables that foster innovation:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Structural:","bold":true},{"text":" organic structure (flexible: low formalization, centralization, specialization); abundant resources; frequent communication between units; minimal time pressure; work and nonwork support."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" accept ambiguity; tolerate the impractical; keep external controls low; tolerate risk; tolerate conflict; focus on ends rather than means; open-system focus; give positive feedback."}]},{"text":[{"text":"Human resource:","bold":true},{"text":" actively promote training and development; offer high job security; encourage people to become idea champions."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Abundant resources:","bold":true},{"text":" buy innovations, afford failures, try many ideas. "},{"text":"Minimal time pressure:","bold":true},{"text":" extreme pressure lowers creativity."}]},{"text":[{"text":"Tolerate risk:","bold":true},{"text":" failures not punished. "},{"text":"Open-system focus:","bold":true},{"text":" watching the environment. "},{"text":"High job security:","bold":true},{"text":" less fear of being fired for mistakes."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Change = people, structure or technology; 5 external, 4 internal forces."}]},{"text":[{"text":"Calm waters = Lewin's 3 steps; white-water = constant change; OD changes people (insiders cautious, outsiders may be drastic)."}]},{"text":[{"text":"Stress: 3 symptom groups, 2 cause groups. Resistance: 4 reasons, 6 remedies. Creativity = the idea; innovation = the idea made useful."}]}]}],"theory":{"itemId":"9c690f6d-55fa-51be-9dca-8e0f4183c11f","question":[{"type":"paragraph","text":[{"text":"Explain why employees resist organizational change and discuss the techniques managers can use to reduce resistance."}]}]},"practice":[{"topic":"Managing Change and Innovation","named":false}]}},{"itemId":"006b8fa8-d019-5c9e-ac09-7e00435a3088","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Individual Behaviour, Groups and Work Teams","body":"What OB studies, what shapes individual behaviour, and how groups and teams form, clash and perform.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What OB studies, what shapes individual behaviour, and how groups and teams form, clash and perform."}],"lessons":[{"number":"7.1","title":"Organizational behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Behaviour:","bold":true},{"text":" actions of people. "},{"text":"Organizational behaviour (OB):","bold":true},{"text":" study of the actions of people at work. "},{"text":"2 areas:","bold":true},{"text":" individual and group behaviour. "},{"text":"3 goals:","bold":true},{"text":" explain, predict, influence (not \"eliminate\")."}]},{"text":[{"text":"6 employee behaviours:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Productivity:","bold":true},{"text":" performance measure of efficiency and effectiveness."}]},{"text":[{"text":"Absenteeism:","bold":true},{"text":" failure to show up for work."}]},{"text":[{"text":"Turnover:","bold":true},{"text":" voluntary and involuntary permanent withdrawal from the organization."}]},{"text":[{"text":"OCB (organizational citizenship behaviour):","bold":true},{"text":" discretionary behaviour, not in the formal job, that helps the organization work well."}]},{"text":[{"text":"Job satisfaction:","bold":true},{"text":" general attitude to the job."}]},{"text":[{"text":"Workplace misbehaviour:","bold":true},{"text":" intentional behaviour that could harm the organization or people in it; 4 forms: deviance, aggression, antisocial behaviour, violence."}]}]}]},{"text":[{"text":"Iceberg:","bold":true},{"text":" visible = strategies, objectives, policies, structure, technology, formal authority, chain of command. Hidden = attitudes, perceptions, group norms, informal interactions, interpersonal and intergroup conflicts. Most of what drives behaviour is below the surface."}]},{"text":[{"text":"7 factors influencing individual behaviour:","bold":true},{"text":" biography/demography, age, gender, societal responsibilities, marital status, personality, values and attitudes. "},{"text":"5 factors that change behaviour:","bold":true},{"text":" demographic/biological factors, personality, values and attitudes, motivation, learning."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Owen:","bold":true},{"text":" concerned about terrible working conditions. "},{"text":"Munsterberg:","bold":true},{"text":" founded industrial psychology, the scientific study of people at work. "},{"text":"Follett:","bold":true},{"text":" studied organizations through individual and group behaviour; modern work groups trace to her. "},{"text":"Barnard:","bold":true},{"text":" organizations are social systems needing cooperation; first to call them open systems."}]},{"text":[{"text":"Hawthorne Studies (Elton Mayo):","bold":true},{"text":" began as lighting tests; biggest contribution to OB; found social norms or group standards drive individual work behaviour."}]},{"text":[{"text":"OB is most tied to employee motivation. Current issues: generational differences, negative behaviour."}]}]}]},{"number":"7.2","title":"Attitudes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Attitudes:","bold":true},{"text":" evaluative statements, favourable or unfavourable, about objects, people or events; show how a person feels."}]},{"text":[{"text":"3 components:","bold":true},{"text":" "},{"text":"cognitive","bold":true},{"text":" (beliefs, opinions, knowledge); "},{"text":"affective","bold":true},{"text":" (emotions, feelings); "},{"text":"behavioural","bold":true},{"text":" (intention to behave a certain way)."}]},{"text":[{"text":"4 job-related attitudes:","bold":true},{"text":" "},{"text":"job satisfaction","bold":true},{"text":" (general attitude to the job); "},{"text":"job involvement","bold":true},{"text":" (identifying with the "},{"text":"job","bold":true},{"text":", active part in it, performance seen as important to self-worth); "},{"text":"organizational commitment","bold":true},{"text":" (identifying with the "},{"text":"organization","bold":true},{"text":" and its goals, wanting to stay); "},{"text":"employee engagement","bold":true},{"text":" (connected to, satisfied with, enthusiastic about the job)."}]},{"text":[{"text":"Cognitive dissonance (Leon Festinger):","bold":true},{"text":" any incompatibility or inconsistency between attitudes, or between behaviour and attitudes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"People change the attitude or behaviour, or find a reason for the gap. Effort depends on "},{"text":"importance","bold":true},{"text":" of the elements, "},{"text":"influence","bold":true},{"text":" the person feels he has, "},{"text":"rewards","bold":true},{"text":" (high pay eases it)."}]},{"text":[{"text":"Managers measure attitudes with attitude surveys."}]},{"text":[{"text":"Satisfied employees: lower absenteeism and turnover; satisfied, engaged ones: better customer service."}]}]}]},{"number":"7.3","title":"Personality and emotional intelligence","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" unique combination of emotional, thought and behavioural patterns affecting how a person reacts and interacts with others. From "},{"text":"heredity and environment","bold":true},{"text":". 3 influences: perception, emotions, religion."}]},{"text":[{"text":"Big Five (OCEAN):","bold":true},{"text":" "},{"text":"Openness","bold":true},{"text":" (imaginative, curious, artistically sensitive); "},{"text":"Conscientiousness","bold":true},{"text":" (responsible, dependable, persistent, achievement-oriented; best linked to job performance); "},{"text":"Extraversion","bold":true},{"text":" (sociable, talkative, assertive); "},{"text":"Agreeableness","bold":true},{"text":" (good-natured, cooperative, trusting); "},{"text":"Neuroticism","bold":true},{"text":" (tense, anxious, insecure; opposite = "},{"text":"emotional stability","bold":true},{"text":")."}]},{"text":[{"text":"MBTI:","bold":true},{"text":" 4 dimensions, "},{"text":"16","bold":true},{"text":" types: Extravert/Introvert (social interaction); Sensing/Intuitive (gathering data); Feeling/Thinking (decision making); Perceptive/Judgemental (style of making decisions)."}]},{"text":[{"text":"Other traits:","bold":true},{"text":" "},{"text":"locus of control","bold":true},{"text":" (internal: \"I control my fate\"; external: luck or others; internals more satisfied and involved); "},{"text":"Machiavellianism","bold":true},{"text":" (pragmatic, emotionally distant, ends justify means; suits bargaining jobs such as sales, negotiating); "},{"text":"self-esteem","bold":true},{"text":" (liking or disliking oneself; low = more open to outside influence); "},{"text":"self-monitoring","bold":true},{"text":" (adjusting behaviour to the situation); "},{"text":"risk-taking","bold":true},{"text":" (willingness to take chances; high risk-takers make quick decisions on little information, low risk-takers decide slowly and want more information); "},{"text":"proactive personality","bold":true},{"text":" (spots opportunities, shows initiative, persists until change happens)."}]},{"text":[{"text":"Emotional intelligence (EI):","bold":true},{"text":" ability to notice and manage emotional cues and information. "},{"text":"5 dimensions:","bold":true},{"text":" self-awareness, self-management, self-motivation, empathy, social skills. Matters most in jobs needing much social interaction."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Holland's personality-job fit:","bold":true},{"text":" satisfaction highest, turnover lowest when personality matches job. 6 types: realistic, investigative, social, conventional, enterprising, artistic."}]},{"text":[{"text":"Big Five appear across many cultures; locus of control differs between cultures."}]}]}]},{"number":"7.4","title":"Perception and learning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Perception:","bold":true},{"text":" giving meaning to our environment by organizing and interpreting sensory impressions. Influenced by the "},{"text":"perceiver","bold":true},{"text":" (attitudes, interests, experience, expectations), the "},{"text":"target","bold":true},{"text":", the "},{"text":"situation","bold":true},{"text":"."}]},{"text":[{"text":"Attribution theory:","bold":true},{"text":" we judge people differently depending on whether we see the cause as internal or external. 3 factors: "},{"text":"distinctiveness","bold":true},{"text":" (acts differently elsewhere? high = external); "},{"text":"consensus","bold":true},{"text":" (others in the same situation act the same? high = external); "},{"text":"consistency","bold":true},{"text":" (acts this way over time? high = internal)."}]},{"text":[{"text":"Fundamental attribution error:","bold":true},{"text":" judging "},{"text":"others","bold":true},{"text":", we underestimate external and overestimate internal factors. "},{"text":"Self-serving bias:","bold":true},{"text":" we credit "},{"text":"our own","bold":true},{"text":" success to internal factors, failure to external ones (luck)."}]},{"text":[{"text":"4 judging shortcuts:","bold":true},{"text":" "},{"text":"selectivity","bold":true},{"text":" (taking in only bits of what we see, by interests, background, attitudes); "},{"text":"assumed similarity","bold":true},{"text":" (\"like me\" effect); "},{"text":"stereotyping","bold":true},{"text":" (judging by the group someone belongs to); "},{"text":"halo effect","bold":true},{"text":" (one characteristic, such as looks, shapes the whole impression)."}]},{"text":[{"text":"Learning:","bold":true},{"text":" relatively permanent change in behaviour from experience. "},{"text":"Operant conditioning (B. F. Skinner):","bold":true},{"text":" behaviour is a function of its consequences. "},{"text":"Social learning theory:","bold":true},{"text":" learning by observing others and direct experience; 4 processes: attentional, retention, motor reproduction, reinforcement."}]},{"text":[{"text":"4 ways to shape behaviour:","bold":true},{"text":" "},{"text":"positive reinforcement","bold":true},{"text":" (something pleasant follows; strengthens); "},{"text":"negative reinforcement","bold":true},{"text":" (something unpleasant removed, such as nagging stopping; strengthens); "},{"text":"punishment","bold":true},{"text":" (penalty follows; weakens); "},{"text":"extinction","bold":true},{"text":" (reward sustaining the behaviour removed; weakens). "},{"text":"Shaping behaviour:","bold":true},{"text":" guiding learning in graduated steps, reinforcing each step towards the desired behaviour."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Negative reinforcement is not punishment."}]},{"text":[{"text":"Managers should reward wanted behaviour and model it; staff learn from what managers do."}]}]}]},{"number":"7.5","title":"Groups and group behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group:","bold":true},{"text":" two or more interacting and interdependent individuals who come together to achieve specific goals."}]},{"text":[{"text":"Formal:","bold":true},{"text":" purposeful, structured (hierarchy, rules), assigned roles, officially recognised (e.g. a bank's finance department). "},{"text":"Informal:","bold":true},{"text":" spontaneous, unstructured, based on personal connections and social needs (friendship groups, lunch or football groups, social clubs)."}]},{"text":[{"text":"2 formal types:","bold":true},{"text":" "},{"text":"command group","bold":true},{"text":" (set by the organization chart: supervisor and direct subordinates); "},{"text":"task group","bold":true},{"text":" (specific task, set time; disbands after)."}]},{"text":[{"text":"5 stages in order:","bold":true},{"text":" 1. "},{"text":"Forming:","bold":true},{"text":" people join; purpose, structure, leadership defined; uncertainty. 2. "},{"text":"Storming:","bold":true},{"text":" conflict over control and direction; ends when a clear leadership hierarchy emerges. 3. "},{"text":"Norming:","bold":true},{"text":" close relationships, cohesiveness, shared expectations. 4. "},{"text":"Performing:","bold":true},{"text":" structure accepted; energy on the task; last stage for permanent groups. 5. "},{"text":"Adjourning:","bold":true},{"text":" temporary groups wrap up and break up."}]},{"text":[{"text":"Role:","bold":true},{"text":" behaviour patterns expected of someone in a given position. "},{"text":"Role conflict:","bold":true},{"text":" facing different role expectations at once."}]},{"text":[{"text":"Norms:","bold":true},{"text":" standards accepted and shared by members; commonly cover work effort and performance. "},{"text":"Asch study:","bold":true},{"text":" many went along with a deliberately wrong group answer on line lengths: pressure to conform."}]},{"text":[{"text":"Status:","bold":true},{"text":" prestige grading, position or rank in a group; formal (title, office) or informal (education, age, skill). Members must see it as fair."}]},{"text":[{"text":"Size:","bold":true},{"text":" small groups finish tasks faster; large groups suit problem solving and diverse input."}]},{"text":[{"text":"Social loafing:","bold":true},{"text":" less effort when working collectively than alone. Reduce it by making each contribution identifiable and measurable."}]},{"text":[{"text":"Cohesiveness:","bold":true},{"text":" how far members are attracted to the group and share its goals. Productivity: high and aligned with organization goals = strong increase; high, not aligned = decrease; low, aligned = moderate increase; low, not aligned = no significant effect."}]},{"text":[{"text":"Groupthink:","bold":true},{"text":" heavy group pressure on an individual to align his opinion with the others."}]},{"text":[{"text":"Group decisions:","bold":true},{"text":" advantages: more complete information, more diverse alternatives, greater acceptance, greater legitimacy. Disadvantages: time-consuming, minority domination, pressure to conform, ambiguous responsibility (unclear who is accountable)."}]}]}]},{"number":"7.6","title":"Teams and conflict","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Work team:","bold":true},{"text":" members work intensely on a specific, common goal using positive synergy (whole greater than sum of parts), individual and mutual accountability, complementary skills."}]},{"text":[{"text":"5 differences, groups vs teams:","bold":true},{"text":" accountability (individual / shared); goals (individual / shared); interdependence (limited / high); focus (individual / collective performance); collaboration (less / heavy emphasis). Leadership: one leader in charge in a group; often shared in a team."}]},{"text":[{"text":"4 team types:","bold":true},{"text":" "},{"text":"problem-solving","bold":true},{"text":" (same department; suggests improvements, usually cannot carry them out); "},{"text":"self-managed","bold":true},{"text":" (no manager; whole work process; plans, schedules, assigns work, decides); "},{"text":"cross-functional","bold":true},{"text":" (different departments or specialities); "},{"text":"virtual","bold":true},{"text":" (linked by technology while apart)."}]},{"text":[{"text":"8 characteristics of effective teams:","bold":true},{"text":" clear goals, relevant skills, mutual trust, unified commitment, good communication, negotiating skills, appropriate leadership, internal and external support."}]},{"text":[{"text":"Conflict:","bold":true},{"text":" perceived incompatible differences resulting in interference or opposition. "},{"text":"3 views:","bold":true},{"text":" "},{"text":"traditional","bold":true},{"text":" (bad, avoid it); "},{"text":"human relations","bold":true},{"text":" (natural, inevitable, need not be negative); "},{"text":"interactionist","bold":true},{"text":" (some conflict is necessary for good performance)."}]},{"text":[{"text":"Functional","bold":true},{"text":" conflict supports group goals and improves performance; "},{"text":"dysfunctional","bold":true},{"text":" prevents reaching them."}]},{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"task","bold":true},{"text":" (content and goals of work); "},{"text":"relationship","bold":true},{"text":" (interpersonal; almost always dysfunctional); "},{"text":"process","bold":true},{"text":" (how work gets done)."}]},{"text":[{"text":"5 handling styles:","bold":true},{"text":" "},{"text":"avoiding","bold":true},{"text":" (withdraw or suppress); "},{"text":"accommodating","bold":true},{"text":" (other's needs above yours); "},{"text":"forcing","bold":true},{"text":" (yours at the other's expense); "},{"text":"compromising","bold":true},{"text":" (each gives up something); "},{"text":"collaborating","bold":true},{"text":" (win-win for all)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Too little conflict: dull, slow to change. Too much: chaos."}]},{"text":[{"text":"Managers shape team behaviour by "},{"text":"selection, training, rewards","bold":true},{"text":" (reward cooperation and team results, not only individual effort)."}]},{"text":[{"text":"Global teams bring more ideas but face language, culture and trust problems."}]},{"text":[{"text":"Teams cost more time and resources; use when work is complex, needs different perspectives and members depend on one another."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OB: actions of people at work; explain, predict, influence."}]},{"text":[{"text":"Big Five OCEAN; MBTI 16 types; EI 5 dimensions."}]},{"text":[{"text":"Attribution: distinctiveness, consensus, consistency."}]},{"text":[{"text":"Reinforcement strengthens; punishment and extinction weaken."}]},{"text":[{"text":"Stages: forming, storming, norming, performing, adjourning."}]},{"text":[{"text":"Conflict: 3 views, 3 types, 5 styles."}]}]}],"theory":{"itemId":"42bbfaf2-990f-56e5-b3bd-ae66a546c271","question":[{"type":"paragraph","text":[{"text":"Distinguish between a group and a team, and explain the five stages of group development."}]}]},"practice":[{"topic":"Individual Behaviour, Groups and Work Teams","named":false}]}},{"itemId":"afc18495-3b1b-51ab-8888-85221395539d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Motivating and Rewarding Employees","body":"The theories of motivation, how they fit together, and how to design rewards.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The theories of motivation, how they fit together, and how to design rewards."}],"lessons":[{"number":"8.1","title":"What motivation is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation:","bold":true},{"text":" the process by which a person's efforts are energized, directed and sustained toward attaining a goal; put simply, "},{"text":"encouraging employees to work effectively","bold":true},{"text":". It belongs to "},{"text":"leading","bold":true},{"text":"."}]},{"text":[{"text":"3 elements:","bold":true},{"text":" 1. "},{"text":"Energy","bold":true},{"text":" (intensity or drive); 2. "},{"text":"Direction","bold":true},{"text":" (effort channelled toward organizational goals); 3. "},{"text":"Persistence","bold":true},{"text":" (effort continues until the goal is achieved)."}]},{"text":[{"text":"Process, 6 steps:","bold":true},{"text":" unsatisfied need → tension → drives → search behaviour → satisfied need (also worded \"satisfying behaviour\" or \"satisfied behaviour\") → reduction of tension."}]},{"text":[{"text":"Motivating employees effectively requires "},{"text":"understanding their individual needs and goals","bold":true},{"text":"; one size does not fit all."}]},{"text":[{"text":"Intrinsic:","bold":true},{"text":" from inside (achievement, enjoying the work). "},{"text":"Extrinsic:","bold":true},{"text":" external rewards (pay, bonuses, promotion, recognition)."}]},{"text":[{"text":"Content theories (what motivates):","bold":true},{"text":" Maslow, Herzberg, McClelland. "},{"text":"Process theories (how motivation works):","bold":true},{"text":" Vroom, Adams, Locke and Latham."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Satisfaction is not an element. Vroom is process, not content."}]}]}]},{"number":"8.2","title":"Early theories of motivation","mustKnow":[{"type":"paragraph","text":[{"text":"1. Maslow's hierarchy of needs (Abraham Maslow),","bold":true},{"text":" lowest to highest:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological:","bold":true},{"text":" food, water, shelter (\"primary needs\")."}]},{"text":[{"text":"Safety:","bold":true},{"text":" protection from harm, job security, health insurance, pension."}]},{"text":[{"text":"Social:","bold":true},{"text":" affection, belonging, acceptance, friendship."}]},{"text":[{"text":"Esteem:","bold":true},{"text":" internal (self-respect, autonomy, achievement); external (status, recognition, attention)."}]},{"text":[{"text":"Self-actualization:","bold":true},{"text":" growth, achieving one's potential."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lower-order:","bold":true},{"text":" physiological, safety; satisfied "},{"text":"externally","bold":true},{"text":" (pay, contracts, tenure). "},{"text":"Higher-order:","bold":true},{"text":" the other three; satisfied "},{"text":"internally","bold":true},{"text":"."}]},{"text":[{"text":"Assumptions:","bold":true},{"text":" behaviour is based on needs; needs come in a fixed order; a satisfied need no longer motivates, so the person moves up."}]}]},{"type":"paragraph","text":[{"text":"2. McGregor (Douglas McGregor).","bold":true},{"text":" "},{"text":"Theory X","bold":true},{"text":" (negative): little ambition, dislike work, avoid responsibility, need close control. "},{"text":"Theory Y","bold":true},{"text":" (positive): self-direction, accept and seek responsibility, see work as natural."}]},{"type":"paragraph","text":[{"text":"3. Herzberg's two-factor (motivation-hygiene) theory (Frederick Herzberg).","bold":true}]},{"type":"table","header":[[{"text":"Hygiene factors ("},{"text":"extrinsic","bold":true},{"text":")"}],[{"text":"Motivators ("},{"text":"intrinsic","bold":true},{"text":")"}]],"rows":[[[{"text":"Remove dissatisfaction; do not motivate"}],[{"text":"Create satisfaction; motivate; concern the job itself"}]],[[{"text":"Salary, company policy, supervision, working conditions, relations with others, job security"}],[{"text":"Achievement, recognition, the work itself, responsibility, advancement, growth"}]]]},{"type":"paragraph","text":[{"text":"4. McClelland's three needs (David McClelland):","bold":true},{"text":" "},{"text":"Achievement","bold":true},{"text":" (drive to succeed and excel in relation to a set of standards); "},{"text":"Power","bold":true},{"text":" (need to make others behave in a way they would not have behaved otherwise); "},{"text":"Affiliation","bold":true},{"text":" (desire for friendly and close interpersonal relationships)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maslow:","bold":true},{"text":" helps managers understand what motivates each employee. Status and recognition are esteem, not social."}]},{"text":[{"text":"McGregor","bold":true},{"text":" favoured Theory Y: participation in decisions, responsible and challenging jobs, good group relations. No evidence either set is valid or that Theory Y always raises motivation."}]},{"text":[{"text":"Herzberg:","bold":true},{"text":" opposite of satisfaction = "},{"text":"no satisfaction","bold":true},{"text":"; opposite of dissatisfaction = "},{"text":"no dissatisfaction","bold":true},{"text":". Fixing hygiene makes workers calm, not motivated. His work led to "},{"text":"job enrichment","bold":true},{"text":"."}]},{"text":[{"text":"McClelland:","bold":true},{"text":" high achievers want personal responsibility, fast feedback, "},{"text":"moderate","bold":true},{"text":" risk. Best managers tend to be "},{"text":"high in power, low in affiliation","bold":true},{"text":"."}]}]}]},{"number":"8.3","title":"Goal-setting and reinforcement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Goal-setting theory (Edwin Locke, later with Gary Latham):","bold":true},{"text":" specific and challenging goals motivate. "},{"text":"Clear","bold":true},{"text":", "},{"text":"difficult but attainable","bold":true},{"text":" goals "},{"text":"with feedback","bold":true},{"text":" raise performance. Specific beats \"do your best\"; accepted difficult goals beat easy ones."}]},{"text":[{"text":"SMART:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific (clear, well defined); "},{"text":"M","bold":true},{"text":"easurable (progress tracked with numbers); "},{"text":"A","bold":true},{"text":"chievable/attainable (realistic, within reach; goals that are too difficult cause "},{"text":"discouragement","bold":true},{"text":"); "},{"text":"R","bold":true},{"text":"elevant (fits objectives and values); "},{"text":"T","bold":true},{"text":"ime-bound (deadline)."}]},{"text":[{"text":"Reinforcement theory (B. F. Skinner):","bold":true},{"text":" behaviour is a function of its consequences. "},{"text":"Reinforcers:","bold":true},{"text":" consequences that, coming immediately after a behaviour, increase the chance it will be repeated."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Self-generated feedback","bold":true},{"text":" (tracking own progress) beats feedback from others."}]},{"text":[{"text":"Participation does not always beat assigned goals, but makes people "},{"text":"accept","bold":true},{"text":" a hard goal."}]},{"text":[{"text":"Other conditions: "},{"text":"goal commitment","bold":true},{"text":", "},{"text":"self-efficacy","bold":true},{"text":" (belief one can do the task), task type, national culture. "},{"text":"MBO","bold":true},{"text":" applies goal-setting."}]},{"text":[{"text":"Reinforcement ignores inner needs, goals and expectations. "},{"text":"Ignore","bold":true},{"text":" rather than punish unwanted behaviour: punishment works faster but is often temporary, with unpleasant side effects."}]},{"text":[{"text":"Trap:","bold":true},{"text":" goal-setting = goal "},{"text":"before","bold":true},{"text":" the action; reinforcement = consequence "},{"text":"after","bold":true},{"text":" it."}]}]}]},{"number":"8.4","title":"Job design and the job characteristics model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job design:","bold":true},{"text":" the way tasks are combined to form complete jobs. "},{"text":"Job scope:","bold":true},{"text":" number of different tasks and how often repeated. "},{"text":"Job depth:","bold":true},{"text":" degree of control over the work."}]},{"text":[{"text":"Job enlargement:","bold":true},{"text":" "},{"text":"horizontal","bold":true},{"text":" expansion, increasing scope (more tasks of the same kind). "},{"text":"Job enrichment:","bold":true},{"text":" "},{"text":"vertical","bold":true},{"text":" expansion, adding planning and evaluating responsibilities (increases depth)."}]},{"text":[{"text":"Job characteristics model (Hackman and Oldham): 5 core dimensions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Skill variety:","bold":true},{"text":" range of activities, skills, talents."}]},{"text":[{"text":"Task identity:","bold":true},{"text":" completing a whole, identifiable piece of work."}]},{"text":[{"text":"Task significance:","bold":true},{"text":" effect on the lives or work of others."}]},{"text":[{"text":"Autonomy:","bold":true},{"text":" freedom and discretion in scheduling and choosing methods."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" direct, clear information on performance."}]}]}]},{"text":[{"text":"3 critical psychological states:","bold":true},{"text":" skill variety + task identity + task significance → "},{"text":"experienced meaningfulness","bold":true},{"text":"; autonomy → "},{"text":"experienced responsibility","bold":true},{"text":"; feedback → "},{"text":"knowledge of actual results","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Outcomes: high internal motivation, performance quality, satisfaction, "},{"text":"low","bold":true},{"text":" absenteeism and turnover. Works best for high "},{"text":"growth-need strength","bold":true},{"text":" (a trait, not a dimension). Job enrichment is a "},{"text":"non-financial","bold":true},{"text":" incentive."}]}]}]},{"number":"8.5","title":"Equity, expectancy and integration","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equity theory (J. Stacy Adams):","bold":true},{"text":" an employee compares their "},{"text":"input-outcome ratio","bold":true},{"text":" with that of relevant others and acts to correct inequity. "},{"text":"Inputs:","bold":true},{"text":" effort, experience, education, skill. "},{"text":"Outcomes:","bold":true},{"text":" pay, recognition, promotion."}]},{"text":[{"text":"3 referents:","bold":true},{"text":" 1. "},{"text":"Other","bold":true},{"text":" (similar jobs in the organization, friends, neighbours, professional associates); 2. "},{"text":"System","bold":true},{"text":" (pay policies and procedures); 3. "},{"text":"Self","bold":true},{"text":" (own past experience)."}]},{"text":[{"text":"Expectancy theory (Victor Vroom):","bold":true},{"text":" a person acts based on the expectation that the act will bring a given outcome and on how attractive that outcome is. "},{"text":"3 linkages:","bold":true},{"text":" 1. "},{"text":"Expectancy","bold":true},{"text":" (effort-performance); 2. "},{"text":"Instrumentality","bold":true},{"text":" (performance-reward); 3. "},{"text":"Valence","bold":true},{"text":" (attractiveness of reward)."}]},{"text":[{"text":"Integrated model:","bold":true},{"text":" expectancy theory is the base. Chain: individual effort → individual performance → organizational rewards → individual goals. "},{"text":"Opportunity","bold":true},{"text":" to perform also affects performance. Goal-setting: goals direct effort. Reinforcement: rewards reinforce behaviour. Equity: rewards must feel fair. Needs theories: rewards meet needs. JCM: a well-designed job raises motivation directly."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ratio lower than referent's = "},{"text":"under-rewarded","bold":true},{"text":"; higher = "},{"text":"over-rewarded","bold":true},{"text":"."}]},{"text":[{"text":"Responses to inequity:","bold":true},{"text":" distort own or others' inputs or outcomes; make others change theirs; change own inputs or outcomes (work less); choose a different referent; quit."}]},{"text":[{"text":"Distributive justice:","bold":true},{"text":" fairness of the "},{"text":"amount","bold":true},{"text":" and allocation of rewards; affects "},{"text":"satisfaction","bold":true},{"text":" more. "},{"text":"Procedural justice:","bold":true},{"text":" fairness of the "},{"text":"process","bold":true},{"text":"; affects commitment, trust in the boss, intention to quit."}]},{"text":[{"text":"Motivation is low if "},{"text":"any one","bold":true},{"text":" linkage is weak. What counts is "},{"text":"perception","bold":true},{"text":". A reward staff do not want = low valence; doubting a promised bonus will be paid = weak instrumentality."}]}]}]},{"number":"8.6","title":"Current motivation issues and designing rewards","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tough economic times:","bold":true},{"text":" find creative ways to keep efforts energized, directed and sustained. "},{"text":"Cross-cultural challenge:","bold":true},{"text":" most theories were developed in the United States, so do not fit every culture."}]},{"text":[{"text":"Flexible work arrangements:","bold":true},{"text":" "},{"text":"compressed workweek","bold":true},{"text":" (longer days, fewer days); "},{"text":"flextime","bold":true},{"text":" (set weekly hours, start and end times vary within limits around common core hours); "},{"text":"job sharing","bold":true},{"text":" (two or more people split one full-time job); "},{"text":"telecommuting","bold":true},{"text":" (working from home, linked by computer)."}]},{"text":[{"text":"Unique groups:","bold":true},{"text":" "},{"text":"professionals","bold":true},{"text":" want job challenge, keeping up with their field, support and recognition; "},{"text":"contingent workers","bold":true},{"text":" want a chance to become permanent and training; "},{"text":"low-skilled, minimum-wage workers","bold":true},{"text":" respond to recognition programmes and sincere praise."}]},{"text":[{"text":"3 ways to design rewards:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Open-book management:","bold":true},{"text":" financial statements shared with all employees, who learn to read them and see how their work affects results."}]},{"text":[{"text":"Employee recognition programmes:","bold":true},{"text":" personal attention; interest, approval, appreciation for a job well done."}]},{"text":[{"text":"Pay-for-performance programmes:","bold":true},{"text":" variable pay based on a performance measure: piece-rate pay, wage incentive plans, profit-sharing, lump-sum bonuses."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Culture:","bold":true},{"text":" Maslow's order fits American culture; where people strongly avoid uncertainty "},{"text":"safety","bold":true},{"text":" can top it, where caring and relationships matter most "},{"text":"social","bold":true},{"text":" can. McClelland's high achiever fits cultures like the United States. Interesting work, growth and achievement appear across cultures."}]},{"text":[{"text":"Professionals' loyalty is often to their "},{"text":"profession","bold":true},{"text":" more than their employer. Watch "},{"text":"equity","bold":true},{"text":" problems when contingent workers sit beside better-paid permanent staff. Pay-for-performance fits "},{"text":"expectancy theory","bold":true},{"text":"."}]},{"text":[{"text":"Financial incentives:","bold":true},{"text":" pay rises, bonuses, profit-sharing, piece-rate pay, perquisites, co-partnership. "},{"text":"Non-financial:","bold":true},{"text":" praise, recognition, job enrichment, flexible hours."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation = efforts energized, directed, sustained toward a goal. Content: Maslow, Herzberg, McClelland. Process: Vroom, Adams, Locke and Latham."}]},{"text":[{"text":"Maslow has 5 needs; McClelland 3. Herzberg: hygiene (incl. salary) vs motivators."}]},{"text":[{"text":"SMART: specific, measurable, achievable, relevant, time-bound. Reinforcement (Skinner): consequences shape behaviour."}]},{"text":[{"text":"Enlargement = horizontal, scope; enrichment = vertical, depth. JCM: 5 dimensions, 3 states."}]},{"text":[{"text":"Equity: other, system, self. Expectancy: expectancy, instrumentality, valence."}]},{"text":[{"text":"3 reward designs: open-book management, recognition programmes, pay-for-performance."}]}]}],"theory":{"itemId":"a46fb73b-a0ea-527f-8974-fb4bb16711f4","question":[{"type":"paragraph","text":[{"text":"Explain Herzberg's two-factor theory and state its implications for managers."}]}]},"practice":[{"topic":"Motivating and Rewarding Employees","named":false}]}},{"itemId":"18df4c53-1fb8-5ed5-9e1b-744f42576d18","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"note","questionId":null,"sourceKey":"guide-topic:9","parentItemId":null,"revision":1,"payload":{"title":"Leadership and Trust, and Managing Communication and Information","body":"Leadership theories, power, trust, empowerment; the communication process, types, barriers, networks; information technology.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"Leadership theories, power, trust, empowerment; the communication process, types, barriers, networks; information technology."}],"lessons":[{"number":"9.1","title":"Leadership, leaders and traits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership:","bold":true},{"text":" an influence process that involves motivating and inspiring people to work together to achieve a common goal."}]},{"text":[{"text":"Leader:","bold":true},{"text":" someone who can influence others and who has managerial authority."}]},{"text":[{"text":"9 obligations:","bold":true},{"text":" developing and communicating a clear vision; motivating and inspiring; setting clear expectations; making informed decisions; fostering commitment and accountability; fostering a positive work environment; delegating tasks; coaching team members; conflict resolution."}]},{"text":[{"text":"Manager:","bold":true},{"text":" appointed; influence from formal authority; focus on planning, organizing, controlling. "},{"text":"Leader:","bold":true},{"text":" appointed or emerges from a group; influence can go beyond formal authority; focus on influencing and inspiring."}]},{"text":[{"text":"Trait theories:","bold":true},{"text":" research that tried to isolate the characteristics that set leaders apart from non-leaders."}]},{"text":[{"text":"7 traits:","bold":true},{"text":" drive, desire to lead, honesty and integrity, self-confidence, intelligence, job-relevant knowledge, extraversion."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ideally all managers should be leaders; not all leaders have a manager's abilities."}]},{"text":[{"text":"Supervision:","bold":true},{"text":" overseeing subordinates' work and giving instructions to ensure optimum use of resources and achievement of work targets."}]},{"text":[{"text":"Delegation:","bold":true},{"text":" match tasks to employees' skills and abilities; improves motivation and performance. The manager stays accountable."}]},{"text":[{"text":"8th trait in later lists: "},{"text":"proneness to guilt","bold":true},{"text":" (strong sense of responsibility to others). Flexibility and communication skills also mark effective leaders."}]},{"text":[{"text":"Weakness of trait theories:","bold":true},{"text":" ignored the situation and leader–group interaction. Traits only make a person more likely to be effective. Researchers then studied what leaders "},{"text":"do","bold":true},{"text":"."}]}]}]},{"number":"9.2","title":"Behavioural theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Behavioural theories:","bold":true},{"text":" identify behaviours that separate effective from ineffective leaders."}]},{"text":[{"text":"Iowa (Kurt Lewin):","bold":true},{"text":" autocratic, democratic, laissez-faire; members more satisfied under democratic leaders. Lewin's early finding: democratic gave good quantity and quality; later studies mixed on performance."}]},{"text":[{"text":"Ohio State:","bold":true},{"text":" initiating structure, consideration; high–high leaders often, not always, got good results."}]},{"text":[{"text":"Michigan:","bold":true},{"text":" employee-oriented, production-oriented; employee-oriented had higher productivity and satisfaction."}]},{"text":[{"text":"Managerial Grid (Blake and Mouton):","bold":true},{"text":" concern for people, concern for production; 9,9 best."}]},{"text":[{"text":"Autocratic:","bold":true},{"text":" centralises authority, dictates work methods, decides alone, limits participation. Best in a "},{"text":"crisis","bold":true},{"text":"."}]},{"text":[{"text":"Democratic:","bold":true},{"text":" involves employees in decisions, delegates authority, uses feedback to coach. Most participatory; suits a team whose ideas improve the decision."}]},{"text":[{"text":"Laissez-faire:","bold":true},{"text":" gives group complete freedom to decide and work. Best with "},{"text":"highly skilled, self-motivated","bold":true},{"text":" employees."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Democratic leader still takes part in the decision; laissez-faire hands it over entirely."}]},{"text":[{"text":"Initiating structure:","bold":true},{"text":" how far a leader defines his role and members' roles to reach goals. "},{"text":"Consideration:","bold":true},{"text":" mutual trust and respect for members' ideas and feelings."}]},{"text":[{"text":"Employee-oriented:","bold":true},{"text":" relationships, employees' needs. "},{"text":"Production-oriented:","bold":true},{"text":" technical or task side. People side: consideration, employee-oriented."}]},{"text":[{"text":"Grid:","bold":true},{"text":" 9 × 9 = "},{"text":"81","bold":true},{"text":" positions; first number = "},{"text":"production","bold":true},{"text":", second = "},{"text":"people","bold":true},{"text":". 1,1 impoverished; 9,1 task management; 1,9 country club (high people, low production); 5,5 middle of the road ("},{"text":"medium","bold":true},{"text":" concern for both production and people); 9,9 team management."}]},{"text":[{"text":"Weakness:","bold":true},{"text":" ignored the situation, leading to contingency theories."}]}]}]},{"number":"9.3","title":"Contingency theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contingency theory:","bold":true},{"text":" no one best style; leadership effectiveness depends on understanding employee needs and adapting leadership style to the situation, never keeping a single style regardless of context."}]},{"text":[{"text":"Fiedler:","bold":true},{"text":" performance depends on matching leader's style to how much the situation lets him control and influence. Style "},{"text":"fixed","bold":true},{"text":"."}]},{"text":[{"text":"Situational Leadership Theory (Hersey and Blanchard):","bold":true},{"text":" depends on follower "},{"text":"readiness","bold":true},{"text":" (and task demands). Style "},{"text":"can change","bold":true},{"text":"."}]},{"text":[{"text":"Path-goal (Robert House):","bold":true},{"text":" leader helps followers reach their goals with direction and support."}]},{"text":[{"text":"Fiedler's 3 factors:","bold":true},{"text":" "},{"text":"leader–member relations","bold":true},{"text":" (confidence, trust, respect for the leader); "},{"text":"task structure","bold":true},{"text":" (how formal and structured tasks are); "},{"text":"position power","bold":true},{"text":" (over hiring, firing, discipline, promotion, pay)."}]},{"text":[{"text":"Readiness:","bold":true},{"text":" followers' ability "},{"text":"and","bold":true},{"text":" willingness. R1 unable, unwilling: "},{"text":"telling","bold":true},{"text":" (high task, low relationship). R2 unable, willing: "},{"text":"selling","bold":true},{"text":" (high, high). R3 able, unwilling: "},{"text":"participating","bold":true},{"text":" (low task, high relationship). R4 able, willing: "},{"text":"delegating","bold":true},{"text":" (low, low). As readiness rises, leader cuts back both control and relationship behaviour."}]},{"text":[{"text":"4 path-goal behaviours:","bold":true},{"text":" directive, supportive, participative, achievement-oriented."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"LPC","bold":true},{"text":" (least-preferred co-worker): describing him kindly = high LPC = "},{"text":"relationship-oriented","bold":true},{"text":"; low LPC = "},{"text":"task-oriented","bold":true},{"text":"."}]},{"text":[{"text":"3 factors give "},{"text":"8","bold":true},{"text":" situations. Task-oriented do best in very favourable or very unfavourable; relationship-oriented in moderately favourable. Fix mismatch by "},{"text":"changing the leader or the situation","bold":true},{"text":"."}]},{"text":[{"text":"Directive:","bold":true},{"text":" tells what is expected, schedules work. "},{"text":"Supportive:","bold":true},{"text":" friendly, concerned for needs. "},{"text":"Participative:","bold":true},{"text":" consults, uses suggestions. "},{"text":"Achievement-oriented:","bold":true},{"text":" challenging goals, expects top performance."}]},{"text":[{"text":"Path-goal depends on "},{"text":"environment","bold":true},{"text":" (task structure, formal authority, work group) and "},{"text":"follower characteristics","bold":true},{"text":" (locus of control, experience, perceived ability)."}]},{"text":[{"text":"Leader–member exchange (LMX):","bold":true},{"text":" "},{"text":"in-group","bold":true},{"text":" and "},{"text":"out-group","bold":true},{"text":"; in-group gets more trust and attention."}]}]}]},{"number":"9.4","title":"Contemporary leadership, power, trust and empowerment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership styles:","bold":true},{"text":" autocratic, democratic, laissez-faire, transactional, transformational, charismatic, visionary. \"Functional\" is not a leadership style."}]},{"text":[{"text":"Transactional:","bold":true},{"text":" motivates by "},{"text":"exchanging rewards","bold":true},{"text":" for productivity, through clear goals."}]},{"text":[{"text":"Transformational:","bold":true},{"text":" "},{"text":"stimulates and inspires","bold":true},{"text":" followers to extraordinary outcomes; encourages innovation, creativity, personal growth. Built "},{"text":"on top of","bold":true},{"text":" transactional, not its opposite."}]},{"text":[{"text":"Charismatic:","bold":true},{"text":" enthusiastic, self-confident; personality and actions influence people; personal charm and vision."}]},{"text":[{"text":"Visionary leadership:","bold":true},{"text":" creating and expressing a realistic, credible, attractive vision of the future that improves on the present."}]},{"text":[{"text":"5 powers:","bold":true},{"text":" "},{"text":"legitimate","bold":true},{"text":" (from position); "},{"text":"coercive","bold":true},{"text":" (punish or control); "},{"text":"reward","bold":true},{"text":" (give positive rewards); "},{"text":"expert","bold":true},{"text":" (expertise, skills, knowledge); "},{"text":"referent","bold":true},{"text":" (desirable resources or personal traits; people admire him, want to be like him)."}]},{"text":[{"text":"Trust:","bold":true},{"text":" belief in the integrity, character and ability of a leader. Makes people feel secure and confident: better collaboration, engagement, success."}]},{"text":[{"text":"5 Cs (how trust is built):","bold":true},{"text":" competence (skills, expertise), communication (clear), commitment (to organization's goals), caring (about others), character (ethical, honest)."}]},{"text":[{"text":"Empowerment:","bold":true},{"text":" increasing decision-making discretion of workers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5 charismatic characteristics:","bold":true},{"text":" have a vision; express it; take risks for it; sensitive to environmental limits and followers' needs; behave out of the ordinary."}]},{"text":[{"text":"Team leadership:","bold":true},{"text":" 2 priorities: managing external boundary, helping team process. "},{"text":"4 roles:","bold":true},{"text":" liaison with outsiders, troubleshooter, conflict manager, coach."}]},{"text":[{"text":"5 dimensions of trust:","bold":true},{"text":" integrity (honesty; "},{"text":"most important","bold":true},{"text":"), competence, consistency (reliability, good judgement), loyalty (willingness to protect a person), openness."}]},{"text":[{"text":"Credibility:","bold":true},{"text":" followers see leader as honest, competent, able to inspire. "},{"text":"Honesty","bold":true},{"text":" most linked."}]},{"text":[{"text":"Empowered workers decide alone: they know the job best and act fast. Do not mix the 5 Cs (how trust is built) with the 5 dimensions (what it is made of)."}]}]}]},{"number":"9.5","title":"Communication, its process and types","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication:","bold":true},{"text":" transfer and understanding of meaning; "},{"text":"two-way","bold":true},{"text":" between sender and receiver. "},{"text":"Lifeblood","bold":true},{"text":" of organizations; enables coordination."}]},{"text":[{"text":"Effective:","bold":true},{"text":" people understand your meaning and reply in terms that move the exchange forward."}]},{"text":[{"text":"3 rules for clarity:","bold":true},{"text":" be clear in your own mind about what you want to communicate; deliver succinctly; ensure it is clearly and correctly understood."}]},{"text":[{"text":"4 functions:","bold":true},{"text":" "},{"text":"control","bold":true},{"text":" (rules, policies, reporting lines direct behaviour); "},{"text":"motivation","bold":true},{"text":" (what to do, how well, how to improve); "},{"text":"emotional expression","bold":true},{"text":" (sharing feelings, frustration, satisfaction); "},{"text":"information","bold":true},{"text":" (data for decisions)."}]},{"text":[{"text":"Process, 7 parts in order:","bold":true},{"text":" sender, encoding, message, channel, decoding, receiver, feedback. "},{"text":"Noise","bold":true},{"text":" (illegible print, phone static, inattention) can hit any stage; not one of the 7."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" sender turns message into symbols. "},{"text":"Decoding:","bold":true},{"text":" receiver translates it. "},{"text":"Channel:","bold":true},{"text":" the medium. "},{"text":"Feedback:","bold":true},{"text":" last; checks understanding."}]},{"text":[{"text":"5 types:","bold":true},{"text":" "},{"text":"written words","bold":true},{"text":" (memos, reports, proposals, contracts); "},{"text":"spoken words","bold":true},{"text":" (interviews, phone calls, debates, announcements; effective only when heard by the right people); "},{"text":"symbolic gestures","bold":true},{"text":" (facial expressions, tone of voice, silence, posture, absence; any behaviour audience can see or hear); "},{"text":"visual images","bold":true},{"text":" (photographs, charts, logos, colour schemes); "},{"text":"multimedia","bold":true},{"text":" (combines visual-image methods: television, radio, newspapers, flyers, posters, internet)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal:","bold":true},{"text":" between two or more people. "},{"text":"Organizational:","bold":true},{"text":" all patterns, networks, systems within an organization."}]},{"text":[{"text":"Nonverbal:","bold":true},{"text":" sent without words. "},{"text":"Body language:","bold":true},{"text":" gestures, facial expressions, body movements. "},{"text":"Verbal intonation:","bold":true},{"text":" emphasis on words or phrases."}]},{"text":[{"text":"Face-to-face","bold":true},{"text":" gives most immediate feedback. The sender encodes; the receiver decodes."}]}]}]},{"number":"9.6","title":"Feedback, barriers, organizational communication and information","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedback","bold":true},{"text":" checks you understood the other person's message and lets you react. Negative feedback must be given when it is the only thing to do."}]},{"text":[{"text":"5 rules for negative feedback:","bold":true},{"text":" show understanding of exactly what went wrong, and why; draw out ways to improve; use questions rather than assertions; express negative opinions honestly but positively; be objective, not emotional or personal."}]},{"text":[{"text":"Sandwich approach:","bold":true},{"text":" praise, criticism, praise."}]},{"text":[{"text":"6 barriers:","bold":true},{"text":" "},{"text":"filtering","bold":true},{"text":" (deliberately changing information to look better to receiver); "},{"text":"emotions","bold":true},{"text":" (receiver's feelings change how he reads it); "},{"text":"information overload","bold":true},{"text":" (more than a person can process); "},{"text":"defensiveness","bold":true},{"text":" (feeling threatened, reacting with attack or sarcasm); "},{"text":"language","bold":true},{"text":" (words differ by age, education, jargon); "},{"text":"national culture","bold":true},{"text":" (cultures communicate differently)."}]},{"text":[{"text":"5 remedies:","bold":true},{"text":" use feedback, simplify language, listen actively, constrain emotions, watch nonverbal cues. "},{"text":"Active listening:","bold":true},{"text":" listen for full meaning without judging early: eye contact, questions, paraphrasing, no interrupting."}]},{"text":[{"text":"Formal:","bold":true},{"text":" follows chain of command or needed to do a job. "},{"text":"Informal:","bold":true},{"text":" not defined by the hierarchy. "},{"text":"Grapevine:","bold":true},{"text":" the informal network."}]},{"text":[{"text":"4 directions:","bold":true},{"text":" "},{"text":"downward","bold":true},{"text":" (manager to employees: goals, instructions, policies); "},{"text":"upward","bold":true},{"text":" (employees to manager: reports, suggestions, complaints); "},{"text":"lateral","bold":true},{"text":" (same level, e.g. cross-functional team); "},{"text":"diagonal","bold":true},{"text":" (across both work areas and levels)."}]},{"text":[{"text":"3 networks:","bold":true},{"text":" "},{"text":"chain","bold":true},{"text":" (formal chain of command; moderate speed, high accuracy); "},{"text":"wheel","bold":true},{"text":" (all through strong central leader; fast, high accuracy, leader emerges strongly, "},{"text":"lowest","bold":true},{"text":" satisfaction); "},{"text":"all-channel","bold":true},{"text":" (everyone talks freely, as in self-managed teams; fast, moderate accuracy, no leader emerges, "},{"text":"highest","bold":true},{"text":" satisfaction)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managers cannot remove the grapevine: use it as feedback source and limit harmful rumours through open, honest communication."}]},{"text":[{"text":"Managing information:","bold":true},{"text":" first find out what people most want to know (job security, working conditions, reward, location, benefits). "},{"text":"Honesty and feedback","bold":true},{"text":" essential."}]},{"text":[{"text":"IT:","bold":true},{"text":" networked systems link staff by email, instant messaging, voice mail, fax, teleconferencing, videoconferencing, web conferencing. "},{"text":"Wireless:","bold":true},{"text":" staff need not be at desks."}]},{"text":[{"text":"Intranet:","bold":true},{"text":" internet technology inside organization, staff only. "},{"text":"Extranet:","bold":true},{"text":" links it with approved outsiders (customers, suppliers)."}]},{"text":[{"text":"IT gives managers faster, more complete information. Problems: overload, data security, less face-to-face contact."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership: influence process; 9 obligations; 7 traits; managers appointed, leaders can emerge."}]},{"text":[{"text":"Behavioural: Iowa, Ohio State, Michigan, Grid (81 positions, 9,9 best). Contingency: Fiedler (fixed), Hersey and Blanchard (readiness), House (path-goal)."}]},{"text":[{"text":"Transactional = rewards for productivity; transformational = inspires extraordinary outcomes."}]},{"text":[{"text":"5 powers; trust built by the 5 Cs."}]},{"text":[{"text":"Communication: 4 functions, 7-part process, 5 types."}]},{"text":[{"text":"6 barriers, 5 remedies, 4 directions, 3 networks."}]}]}],"theory":{"itemId":"cc2c6fa5-15c2-5c75-b5b3-06e96b7c032a","question":[{"type":"paragraph","text":[{"text":"Explain how trust is built in leadership, and discuss three barriers to effective communication in an organization."}]}]},"practice":[{"topic":"Leadership, Trust and Communication","named":false}]}}]$expected_content$::jsonb,
  'principles-management: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('fa9abff6-1f94-5735-bbd3-c9104da6df05')
  where kind = 'cbt_question'), 0,
  'principles-management: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"86688b3a-5b38-5884-a976-2640bc1b07c9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"638873b4-04c2-549c-b82c-495ea70c20af","sourceKey":"bank:AMS101:AMS101-T001","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes the people who work as managers today?","options":["Managers now come from a wider mix of ages, ethnic backgrounds and genders than at any time before.","Managers work almost only in big companies with more than 500 staff.","Managers work almost only in businesses that aim to make a profit.","Most managers today are over 60 years old."],"correctOption":0,"section":"Managers and Management","explanation":"Managers today are a far more varied group than in the past, covering all ages, both genders and many ethnic backgrounds. Options B and C are wrong because managers work in small and large organizations alike, and in non-profits as well as for-profit firms. Option D is wrong because managers come from every age group, not mainly from older people."}},{"itemId":"da289bcb-d7c3-5d3a-a71b-772b7acd965f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"803ad36a-97cc-5ff4-aa81-83feee638844","sourceKey":"bank:AMS101:AMS101-T002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these best defines an organization?","options":["the building or place where people go to work","any group of people who carry out similar tasks","people deliberately arranged to achieve a particular purpose","a set of people whose aim is to make profit for shareholders"],"correctOption":2,"section":"Managers and Management","explanation":"An organization is a deliberate arrangement of people brought together to achieve a specific purpose. Option A is wrong because an organization does not need one physical location, and option B fails because members of the same organization often do very different jobs. Option D is too narrow, since many organizations, such as clubs and charities, do not exist to make profit."}},{"itemId":"9fed5be5-7309-57b3-850f-55d307398c9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d7c94de8-9bcc-5b28-a1d0-076b31689092","sourceKey":"bank:AMS101:AMS101-T003","parentItemId":null,"revision":1,"payload":{"prompt":"Every organization has ______, which spell out its purpose and why it exists.","options":["limits","rules","structure","goals"],"correctOption":3,"section":"Managers and Management","explanation":"Goals are what tell everyone what an organization is trying to achieve, so they define its purpose and reason for existing. Rules (option B) help members work towards the goals but do not state them. Structure (option C) shapes how people work together, but structure alone does not say what the organization is for."}},{"itemId":"1d177a08-70f5-5d18-9c7d-6c8fee5e9a70","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cb18b73a-6f26-568f-9afa-a4ffddd06403","sourceKey":"bank:AMS101:AMS101-T004","parentItemId":null,"revision":1,"payload":{"prompt":"A shared feature of all organizations is a ______, which sets out the organization's rules, regulations and values.","options":["set of written bylaws","clearly stated goal","systematic structure","declared purpose"],"correctOption":2,"section":"Managers and Management","explanation":"Every organization develops a systematic structure that sets out rules, regulations and values and shapes how members behave. Options B and D describe the goal or purpose, which is a different characteristic: it says what the organization wants to achieve, not how members should conduct themselves. Option A is too narrow, because many organizations have no written bylaws at all."}},{"itemId":"a8422e0a-144d-563c-ba78-6bfac3b48686","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ed03b181-9b5b-5f0f-b076-14730191075b","sourceKey":"bank:AMS101:AMS101-T005","parentItemId":null,"revision":1,"payload":{"prompt":"A student fraternity counts as an organization because its members ______.","options":["have the same values, traditions and customs","have the same goals and values","share goals and operate within a common structure","follow the same set of rules and regulations"],"correctOption":2,"section":"Managers and Management","explanation":"To be an organization, a group needs people, a shared goal and a structure through which members work together, and option C captures that combination. Options A and B mention shared values or goals but leave out the structure. Option D mentions rules but leaves out the shared goal, so it is incomplete."}},{"itemId":"1783c2c1-de3c-520e-8774-5bafc4e0bd50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bb547b3c-25ee-52eb-a913-498f64dd436a","sourceKey":"bank:AMS101:AMS101-T006","parentItemId":null,"revision":1,"payload":{"prompt":"What mainly separates managerial employees from nonmanagerial employees?","options":["Managerial employees are paid more.","Nonmanagerial employees have less formal education.","Nonmanagerial employees do not direct or oversee other people's work.","Managerial employees work more hours."],"correctOption":2,"section":"Managers and Management","explanation":"The real dividing line is responsibility for other people's work: managers oversee and direct others, while nonmanagerial employees work directly on tasks without supervising anyone. Pay, education and working hours (options A, B and D) can vary a lot, and a nonmanagerial specialist may earn more or study longer than a manager, so none of them defines the difference."}},{"itemId":"02f1af0d-5f57-5d41-8f81-f17ca91b9219","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"007210e1-d40f-58c4-b3be-318380aa2dd9","sourceKey":"bank:AMS101:AMS101-T007","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's main job is to ______.","options":["take decisions that help the organization grow","handle tasks that are too hard for nonmanagerial staff","act as a go-between for leaders and ordinary workers","direct and oversee other people's work"],"correctOption":3,"section":"Managers and Management","explanation":"Directing and overseeing the work of others is what makes someone a manager. Managers may also make growth decisions, take on hard tasks or link leaders with staff (options A, B and C), but those are things a manager might do, not the core of the job."}},{"itemId":"5941975c-3159-5cb7-9dbf-ce21960a3683","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b35ec3a-50bd-52ec-a985-4f80900f2a7a","sourceKey":"bank:AMS101:AMS101-T008","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about a manager's work is correct?","options":["It is limited strictly to overseeing and monitoring other people.","It can include doing tasks that have nothing to do with overseeing others.","It consists only of high-level tasks needing advanced skills.","It involves no contact with nonmanagerial employees."],"correctOption":1,"section":"Managers and Management","explanation":"Although overseeing others is the main part of the job, managers can also do regular work themselves, such as a supervisor who helps serve customers during a rush. Option A is wrong for that same reason. Options C and D are also wrong, because managers handle routine tasks too and work closely with nonmanagerial staff every day."}},{"itemId":"9a26dc1f-4b39-5aad-bda7-bf76e4659cdd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0710cbc-eea7-5d31-98ed-4f7de44a98c1","sourceKey":"bank:AMS101:AMS101-T009","parentItemId":null,"revision":1,"payload":{"prompt":"Which kind of manager is also commonly called a supervisor?","options":["division manager","middle manager","first-line manager","top manager"],"correctOption":2,"section":"Managers and Management","explanation":"Supervisor is the usual title for a first-line manager, the lowest level of management that directly oversees nonmanagerial employees. Division managers and other middle managers (options A and B) sit higher up and mostly manage other managers, and top managers (option D) run the whole organization."}},{"itemId":"2fd422d2-9f5c-5fc8-98b6-6f45ebf440b8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b93c32c4-7e7e-510c-90ec-78eedbee3e4d","sourceKey":"bank:AMS101:AMS101-T010","parentItemId":null,"revision":1,"payload":{"prompt":"Which managers take decisions for the whole organization and set the plans and goals that affect everyone in it?","options":["team leader","top manager","department head","project leader"],"correctOption":1,"section":"Managers and Management","explanation":"Top managers sit at the head of the organization, so organization-wide decisions, overall plans and goals are their responsibility. Department heads and project leaders (options C and D) are middle managers who carry out those plans in their own areas. Team leaders (option A) are first-line managers who direct day-to-day work."}},{"itemId":"c97c06b1-14c4-5747-822b-4b688c9fbddb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bbfb8f18-3fa7-584e-a2d7-34718c889e9d","sourceKey":"bank:AMS101:AMS101-T011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a key responsibility of a middle manager?","options":["setting the organization's long-term goals","turning the goals set by top managers into action","assisting top managers in setting goals","doing tasks unrelated to long-term goals"],"correctOption":1,"section":"Managers and Management","explanation":"Middle managers act as the link between the top and the front line, turning goals set by top managers into specific actions that lower levels can carry out. Setting long-term goals (option A) is mainly the job of top managers. Option C may happen from time to time, but it is not the defining part of the middle manager's role."}},{"itemId":"c0ffbfe5-ccf3-54c1-ae72-de4346ee55a7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cff6141c-3cb7-5b90-8443-0af84b8dc76c","sourceKey":"bank:AMS101:AMS101-T012","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these managers would usually NOT have other managers reporting to them?","options":["unit chief","shift manager","vice president","division manager"],"correctOption":1,"section":"Managers and Management","explanation":"A shift manager is a first-line manager, overseeing nonmanagerial workers rather than other managers. A unit chief and a division manager (options A and D) are middle-level roles, and a vice president (option C) is a top-level role, so all three normally have managers under them."}},{"itemId":"6251a14b-3c32-5833-81db-32a13863d66c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fdf0d872-34ee-5183-a485-576b5100dfff","sourceKey":"bank:AMS101:AMS101-T013","parentItemId":null,"revision":1,"payload":{"prompt":"Of the positions listed below, which one is the lowest level of management?","options":["a nonmanagerial employee","a person who helps define the organization's philosophy","a vice president","a middle manager"],"correctOption":3,"section":"Managers and Management","explanation":"Among these choices, the middle manager is the lowest management position. A nonmanagerial employee (option A) is not part of management at all, and the people who define an organization's philosophy or hold vice president titles (options B and C) are top managers. Note that first-line managers sit below middle managers, but they are not among the options here."}},{"itemId":"417cb002-6d7d-58c2-94f5-4eef29c96998","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00f3ecd9-9360-57d0-8477-b68fd5d866b3","sourceKey":"bank:AMS101:AMS101-T014","parentItemId":null,"revision":1,"payload":{"prompt":"What do we call all the management levels found between the supervisory level and the top of the organization?","options":["middle managers","first-line managers","supervisors","team leaders"],"correctOption":0,"section":"Managers and Management","explanation":"Middle managers are, by definition, all the managers between the first-line (supervisory) level and top management. First-line managers, supervisors and team leaders (options B, C and D) are names for the supervisory level itself, not the levels above it."}},{"itemId":"7dbc573c-247c-5ef6-8deb-6993baf2abfd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1586a627-e87e-5b6a-9187-9067abd4f91b","sourceKey":"bank:AMS101:AMS101-T015","parentItemId":null,"revision":1,"payload":{"prompt":"Titles such as executive vice president, chief operating officer, chief executive officer and board chairperson belong to which management level?","options":["team leaders","middle managers","first-line managers","top managers"],"correctOption":3,"section":"Managers and Management","explanation":"These are all top management titles held by people who set direction for the whole organization. Middle managers (option B) carry titles like department head or regional manager, while team leaders and first-line managers (options A and C) supervise everyday work."}},{"itemId":"ad7598f7-893e-5907-aab4-32af65136a13","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9fde89b-8f58-5a4b-9bdd-d7e92c5d58fa","sourceKey":"bank:AMS101:AMS101-T016","parentItemId":null,"revision":1,"payload":{"prompt":"Efficiency is often described as ______.","options":["doing the right things","doing things right","ensuring things get done","doing things at the right time"],"correctOption":1,"section":"Managers and Management","explanation":"Efficiency is about doing things right, which means using the least resources to get the work done with as little waste as possible. Option A, doing the right things, describes effectiveness, which is about reaching the right goals. Options C and D talk about completing work or timing, not about how well resources are used."}},{"itemId":"9ec3f384-a9f6-5148-8ee1-87dba1c863c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e47699c-fce5-5950-a45f-3fb8d90d9949","sourceKey":"bank:AMS101:AMS101-T017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these would be an example of a factory becoming more efficient?","options":["reducing the amount of labour needed to make the product","reducing the selling price of the product","selling more of the product","spending more on advertising the product"],"correctOption":0,"section":"Managers and Management","explanation":"Efficiency improves when the same output is produced with fewer inputs, so cutting the labour needed per product is a clear example. Lowering the price (option B) or selling more (option C) concerns the market, not how inputs are used. Spending more on adverts (option D) actually adds inputs, so it does not make production more efficient."}},{"itemId":"8250be14-8d9c-5c4a-88a9-82c3973a31eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ceb5233-d9d7-57fc-9c19-926b54d2ba79","sourceKey":"bank:AMS101:AMS101-T018","parentItemId":null,"revision":1,"payload":{"prompt":"Effectiveness is often described as ______.","options":["doing the right things","doing things right","doing things intelligently","doing things when needed"],"correctOption":0,"section":"Managers and Management","explanation":"Effectiveness means doing the right things, so that the work actually helps the organization reach its goals. Option B, doing things right, is the usual description of efficiency, which focuses on using resources well. Options C and D are not the standard ways the idea is expressed."}},{"itemId":"3b1a5ccc-0573-5739-aead-fe9eca50af35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"072fbca5-034a-5fb6-843a-70666cdfa7ae","sourceKey":"bank:AMS101:AMS101-T019","parentItemId":null,"revision":1,"payload":{"prompt":"Being effective means the same thing as ______.","options":["keeping costs as low as possible","managing smartly","attaining goals","being efficient"],"correctOption":2,"section":"Managers and Management","explanation":"Effectiveness is about ends: getting the job done and reaching the organization's goals. Keeping costs down (option A) and efficiency (option D) are about means, or how well resources are used. Smart management (option B) is too vague to be a definition of either."}},{"itemId":"26839920-a487-5e07-8e8f-4da5443ec047","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"20b8d7bb-8a4a-5ca9-8086-fb5832df3eef","sourceKey":"bank:AMS101:AMS101-T020","parentItemId":null,"revision":1,"payload":{"prompt":"What does efficiency describe?","options":["how inputs relate to outputs","inputs and outputs added together","an inverse relationship between inputs and outputs","reducing inputs and nothing else"],"correctOption":0,"section":"Managers and Management","explanation":"Efficiency compares what goes in, such as money, time and labour, with what comes out, so it is about the relationship between inputs and outputs. Adding the two together (option B) has no meaning here. Option D is too narrow, because efficiency can also improve by producing more output from the same inputs."}},{"itemId":"61998c16-3eae-5b76-8fea-7bfa80f4b490","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e968f739-d817-5640-92de-c91f44edcc71","sourceKey":"bank:AMS101:AMS101-T021","parentItemId":null,"revision":1,"payload":{"prompt":"Good management aims for ______.","options":["low efficiency and high effectiveness","high efficiency and low effectiveness","high efficiency and high effectiveness","average efficiency and average effectiveness"],"correctOption":2,"section":"Managers and Management","explanation":"Good managers try to achieve goals (high effectiveness) while wasting as little as possible (high efficiency), so both should be high. Options A and B each give up one of the two, which means either wasted resources or missed goals. Option D settles for an average result when the aim is to do well on both."}},{"itemId":"c2177b36-8020-547c-8dc9-309c12e734e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f6fdaf54-b77d-5ac2-baad-3834e4dfed0d","sourceKey":"bank:AMS101:AMS101-T022","parentItemId":null,"revision":1,"payload":{"prompt":"A sweets manufacturer would become both more efficient and more effective by producing ______.","options":["better sweets at the same cost","better sweets at a lower cost","the same sweets at a lower cost","the same sweets at the same cost"],"correctOption":1,"section":"Managers and Management","explanation":"Lower cost reflects better use of resources (efficiency), and a better product reflects better results (effectiveness), so better sweets at a lower cost improves both. Option A improves effectiveness only, and option C improves efficiency only. Option D improves neither."}},{"itemId":"297f60b9-5db3-5006-a9c7-171905cb72ef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"50febc7a-1128-5d4c-9765-aa6067329e04","sourceKey":"bank:AMS101:AMS101-T023","parentItemId":null,"revision":1,"payload":{"prompt":"If a sweets manufacturer cut its production cost but the quality of its sweets stayed the same, it would have ______.","options":["raised effectiveness but not efficiency","raised efficiency but not effectiveness","raised both effectiveness and efficiency","lowered both effectiveness and efficiency"],"correctOption":1,"section":"Managers and Management","explanation":"Producing at lower cost means fewer inputs for the same output, which is an efficiency gain. Since the sweets are no better than before, effectiveness has not changed. Option A gets this the wrong way round, and option C would need the quality to improve as well."}},{"itemId":"de292ef6-125e-5b01-9c41-faebee4d25e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5674c969-5dda-5e7e-908d-dc8aa6d12676","sourceKey":"bank:AMS101:AMS101-T024","parentItemId":null,"revision":1,"payload":{"prompt":"Who is known as the \"father\" of scientific management?","options":["Henri Fayol","Robert L. Katz","Henry Mintzberg","Frederick Winslow Taylor"],"correctOption":3,"section":"Managers and Management","explanation":"Frederick Winslow Taylor earned this title by using careful, scientific study of work to find the best way of doing each job. Henri Fayol (option A), who lived around the same time, is known for the functions of management rather than scientific management. Katz (option B) is linked with managerial skills, and Mintzberg (option C) with managerial roles."}},{"itemId":"8cf1c1cb-401c-5ed3-90a6-de8161d74d50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"613a3d40-8f64-57d1-acb4-161d63a525ae","sourceKey":"bank:AMS101:AMS101-T025","parentItemId":null,"revision":1,"payload":{"prompt":"After watching how workers performed in steel companies, Taylor started building his theory of ______.","options":["the functions of management","ethics-based management","management skills","scientific management"],"correctOption":3,"section":"Managers and Management","explanation":"Taylor's observations of steel workers led to scientific management, which uses careful study and measurement to find the most efficient way to do each task. The functions of management (option A) are linked with Fayol, and management skills (option C) with Katz. Ethics-based management (option B) is not part of Taylor's work."}},{"itemId":"9b62cff5-bee9-57c1-9f0f-09bbe852d0c3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bec82b8c-2f93-5b71-a84d-2753ae6e96cd","sourceKey":"bank:AMS101:AMS101-T026","parentItemId":null,"revision":1,"payload":{"prompt":"One of Taylor's major contributions to management was that he ______.","options":["rated efficiency on a 4-star scale","found the one best way to do a job","found the three best ways to do a job","rated inefficiency on a 4-star scale"],"correctOption":1,"section":"Managers and Management","explanation":"Taylor studied jobs carefully and used the data to work out the \"one best way\" to perform each task. He did measure efficiency, but he did not use any star rating, so options A and D are wrong. Option C is wrong because his whole idea was a single best method, not several."}},{"itemId":"ea6e032c-4758-5980-9093-624e6f3b6cd3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf9e9f39-c96f-5b7c-860b-d62d3c1b709e","sourceKey":"bank:AMS101:AMS101-T027","parentItemId":null,"revision":1,"payload":{"prompt":"In his study of steel workers, which of the following did Taylor NOT find shocking?","options":["Workers deliberately took things easy at work.","Different workers used different methods for the same job.","Workers only took on a job if they had shown they had the ability for it.","Workers produced only about a third of what they could have produced."],"correctOption":2,"section":"Managers and Management","explanation":"Taylor's problem was the opposite of option C: workers were placed in jobs with little thought about whether their abilities fitted the work, which is why he pushed for matching the right worker to the job. The other three options describe things he did find troubling, namely workers slowing down on purpose (A), no standard methods (B) and output of only about a third of what was possible (D)."}},{"itemId":"3f748c66-2e8b-5e94-9e18-beddc8d85cca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a9ee45d-9995-5451-93ef-829ce57cd874","sourceKey":"bank:AMS101:AMS101-T028","parentItemId":null,"revision":1,"payload":{"prompt":"Today, the basic functions of management are generally taken to be ______.","options":["planning, coordinating, leading and monitoring","planning, organizing, leading and motivating","commanding, organizing, leading and decision making","planning, organizing, leading and controlling"],"correctOption":3,"section":"Managers and Management","explanation":"The four functions used today are planning, organizing, leading and controlling. Option A swaps in coordinating and monitoring, and option B swaps in motivating, which is really part of leading. Option C includes commanding, one of Fayol's original terms, and decision making, which runs through all the functions rather than being one of them."}},{"itemId":"32e57247-7f49-5311-bb47-e35b4e361ab2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d2a1d316-c9fe-5ab2-b8e4-15098befaaa1","sourceKey":"bank:AMS101:AMS101-T029","parentItemId":null,"revision":1,"payload":{"prompt":"How many management functions did Henri Fayol originally put forward?","options":["three: plan, organize, lead","four: plan, organize, lead, control","five: plan, organize, command, coordinate, control","ten: 3 interpersonal, 3 informational, 4 decisional"],"correctOption":2,"section":"Managers and Management","explanation":"Fayol's original list had five functions: plan, organize, command, coordinate and control. Option B is the modern four-function version that grew out of his work. Option D describes Mintzberg's ten managerial roles, not Fayol's functions."}},{"itemId":"39317caa-971d-582d-ac83-7ed38a5f76f8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a4b20f0-6ffc-5fd4-bb7a-0d2fe69e4273","sourceKey":"bank:AMS101:AMS101-T030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT part of a manager's planning function?","options":["setting goals","motivating","working out strategy","making decisions"],"correctOption":1,"section":"Managers and Management","explanation":"Motivating people belongs to the leading function, not planning. Setting goals and working out strategies (options A and C) are the heart of planning, and planning also involves deciding which goals and plans to pursue (option D)."}},{"itemId":"18223784-4511-5577-8239-97cc5a480b8f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a051433d-fa8f-55af-98f7-6e214a4c6550","sourceKey":"bank:AMS101:AMS101-T031","parentItemId":null,"revision":1,"payload":{"prompt":"The controlling function is mostly about ______.","options":["settling conflicts","deciding what needs to be done","monitoring to check that tasks are completed","enforcing rules on employees"],"correctOption":2,"section":"Managers and Management","explanation":"Controlling is about monitoring performance to make sure work is being done as planned, then correcting where needed. Settling conflicts (option A) belongs to leading, and deciding what needs to be done (option B) belongs to planning and organizing. Enforcing rules (option D) is at most a small part of controlling, not its main purpose."}},{"itemId":"e098ad98-56e9-5157-971c-acd0655d1ec9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf34a054-9adc-5c52-82a9-d34dd243c3a0","sourceKey":"bank:AMS101:AMS101-T032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is part of organizing?","options":["setting organizational goals","settling conflicts","motivating members of the organization","deciding who will do which tasks"],"correctOption":3,"section":"Managers and Management","explanation":"Organizing is about arranging work, which includes deciding what tasks need doing and who will do them. Setting goals (option A) is planning. Settling conflicts and motivating people (options B and C) are part of leading."}},{"itemId":"7d6c7286-d6ba-570f-8dc4-76058932d843","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c36c779b-0234-517e-a82a-0c7e6f6c564b","sourceKey":"bank:AMS101:AMS101-T033","parentItemId":null,"revision":1,"payload":{"prompt":"Under which management function would settling a conflict fall?","options":["controlling","planning","organizing","leading"],"correctOption":3,"section":"Managers and Management","explanation":"Leading covers working with and through people, which includes motivating them, communicating and settling conflicts. Controlling (option A) is about monitoring and correcting performance, and planning (option B) is about setting goals and strategies. Organizing (option C) arranges tasks and reporting lines, but handling a disagreement between people is a leading job."}},{"itemId":"c5015b88-7b85-5e60-8faf-2b9011605fbc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7b18f1ab-09ec-5d2e-9022-ba86c31cd3f0","sourceKey":"bank:AMS101:AMS101-T034","parentItemId":null,"revision":1,"payload":{"prompt":"A key part of the controlling function is ______.","options":["evaluating","structuring","coordinating","punishing"],"correctOption":0,"section":"Managers and Management","explanation":"Controlling means checking how work is going, which involves evaluating actual performance against the goals that were set and correcting any gaps. Structuring (option B) belongs to organizing. Punishing (option D) is not the purpose of controlling, which focuses on keeping work on track."}},{"itemId":"9d48a8bb-b415-5080-ba8d-1784925ca7bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b48342cf-8d32-5df4-a9e5-f0d7fc0ccd22","sourceKey":"bank:AMS101:AMS101-T035","parentItemId":null,"revision":1,"payload":{"prompt":"Who created a framework describing what managers do in terms of ten different but closely linked roles?","options":["Henri Fayol","Robert L. Katz","Henry Mintzberg","Henry Ford"],"correctOption":2,"section":"Managers and Management","explanation":"Henry Mintzberg, after watching managers at work, grouped what they do into ten roles: three interpersonal, three informational and four decisional. Fayol (option A) is known for the management functions, and Katz (option B) for managerial skills. Henry Ford (option D) was an industrialist who did not create this framework."}},{"itemId":"261be447-bb4d-5d56-9cef-72a18618602d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa84d6e8-d391-5507-99a0-4f98b9a86d47","sourceKey":"bank:AMS101:AMS101-T036","parentItemId":null,"revision":1,"payload":{"prompt":"Under Mintzberg's categories, giving a speech at a company dinner would count as which type of role?","options":["informational","interpersonal","decisional","entrepreneurial"],"correctOption":1,"section":"Managers and Management","explanation":"Speaking at a company dinner is a ceremonial, symbolic duty, which is the figurehead role, and figurehead is one of Mintzberg's interpersonal roles. Option A is tempting because speeches can share information, as the spokesperson role does, but a dinner speech is mainly symbolic. Entrepreneur (option D) is a decisional role about starting new projects."}},{"itemId":"0c7bbdee-059d-5642-b5c0-c030b31d36a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b0097cee-0b50-5370-ae77-11b390bb6010","sourceKey":"bank:AMS101:AMS101-T037","parentItemId":null,"revision":1,"payload":{"prompt":"How did Mintzberg arrive at his ten managerial roles?","options":["by mailing questionnaires to thousands of managers","by watching hundreds of managers over several years","by closely studying the work activities of five chief executives","by applying common sense to the situation"],"correctOption":2,"section":"Managers and Management","explanation":"Mintzberg based his roles on detailed observation of the actual work of five chief executives. He did not use mass questionnaires (option A) or observe hundreds of managers (option B). Option D is wrong because his conclusions came from careful study, not common sense."}},{"itemId":"2a6a829b-2d60-5cef-a7ee-bc56e007212a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"12dc9ce2-6b5e-5839-baa6-cc94d835a491","sourceKey":"bank:AMS101:AMS101-T038","parentItemId":null,"revision":1,"payload":{"prompt":"In Mintzberg's framework, why is negotiator classed as a decisional role?","options":["Negotiating involves taking a position and deciding how and when to compromise.","Negotiating requires a manager to handle money.","Only top managers, who make all decisions, negotiate.","Negotiating needs no interpersonal or informational skill."],"correctOption":0,"section":"Managers and Management","explanation":"Negotiating is mainly about making choices: what position to take, what to give up and when to compromise. That is why it sits among the decisional roles. Option D is wrong because negotiating actually needs strong people and information skills. Options B and C are wrong because negotiation is not only about money and is not limited to top managers."}},{"itemId":"78214be3-bf8a-5899-882a-0cb0ee143e93","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6cc0019e-60aa-5436-8f1f-b9452f386485","sourceKey":"bank:AMS101:AMS101-T039","parentItemId":null,"revision":1,"payload":{"prompt":"A manager from a drug company who attends a meeting of university scientists is acting in which role?","options":["informational","figurehead","liaison","decisional"],"correctOption":2,"section":"Managers and Management","explanation":"The liaison role means building and keeping contacts with people outside one's own unit or organization, and meeting outside scientists fits that well. Option B, figurehead, is about ceremonial duties, which this meeting is not. Options A and D name whole groups of roles that do not include liaison, which is an interpersonal role."}},{"itemId":"2a530901-1dd7-5695-b154-b634fa22e70a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3e0c8abd-5d90-548e-968b-53b25b589f58","sourceKey":"bank:AMS101:AMS101-T040","parentItemId":null,"revision":1,"payload":{"prompt":"A finance manager who regularly reads business newspapers to keep up with financial news is playing which role?","options":["leader","monitor","disseminator","liaison"],"correctOption":1,"section":"Managers and Management","explanation":"In the monitor role, a manager seeks out and receives information about what is happening inside and outside the organization, and following financial news does exactly that. Option C, disseminator, means passing information on to members of the organization, which simply reading does not do. Liaison (option D) is about building outside contacts, and leader (option A) is about directing staff."}},{"itemId":"5f170e9b-af8b-5688-9824-65c751eda4b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9104c95c-2dc7-5e5e-b267-6e017678a9c6","sourceKey":"bank:AMS101:AMS101-T042","parentItemId":null,"revision":1,"payload":{"prompt":"Which finding from Mintzberg's study came as a surprise?","options":["Executives were not efficient.","Managers were careful, reflective thinkers who planned strategies step by step.","Managers might spend hours on one activity in a normal day.","Managers spent only a short time on each activity."],"correctOption":3,"section":"Managers and Management","explanation":"Mintzberg found that managers jumped between many short, varied, unplanned activities and rarely spent long on any one of them. This went against the common belief in option B, that managers were reflective planners working methodically. Option C is the opposite of what he found, and option A was not his conclusion."}},{"itemId":"ce6b7c09-6412-5a3c-b6f9-11c57be45fb5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"35f085c0-a46c-5ece-abe9-04b90ca7062a","sourceKey":"bank:AMS101:AMS101-T044","parentItemId":null,"revision":1,"payload":{"prompt":"All of these are informational roles in Mintzberg's framework EXCEPT ______.","options":["entrepreneur","monitor","disseminator","spokesperson"],"correctOption":0,"section":"Managers and Management","explanation":"Entrepreneur is a decisional role, because it involves spotting opportunities and starting projects to take advantage of them. Monitor, disseminator and spokesperson (options B, C and D) are Mintzberg's three informational roles, which deal with gathering, sharing and passing on information."}},{"itemId":"3e9ae0e1-aba9-5f58-832c-854fb79a663f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"388b5e3f-1d27-5c6b-8b78-493fb5a34e3b","sourceKey":"bank:AMS101:AMS101-T045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a decisional role in Mintzberg's framework?","options":["spokesperson","entrepreneur","disturbance handler","resource allocator"],"correctOption":0,"section":"Managers and Management","explanation":"Spokesperson is an informational role, because it involves passing information to people outside the organization. Entrepreneur, disturbance handler and resource allocator (options B, C and D) are decisional roles, along with negotiator, because each requires the manager to make choices."}},{"itemId":"59537a82-39c8-55ad-a7fd-a8d34a91613d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"897f0f8c-1a8a-51d4-8578-6082366e9868","sourceKey":"bank:AMS101:AMS101-T046","parentItemId":null,"revision":1,"payload":{"prompt":"Which of Mintzberg's roles has essentially the same name as one of the four management functions?","options":["leader","resource allocator","monitor","negotiator"],"correctOption":0,"section":"Managers and Management","explanation":"The leader role is about directing and motivating people, which is exactly what the leading function covers, so the two match almost word for word. Monitor (option C) is tempting because it sounds like controlling, but it is an informational role about gathering information, not the controlling function itself. Resource allocator and negotiator (options B and D) are decisional roles that support planning rather than share a function's name."}},{"itemId":"c8b44c1d-5e29-5ee1-b7a9-e7a04ba91afa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cfa00f34-c629-5825-9f40-6759c99b91df","sourceKey":"bank:AMS101:AMS101-T048","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between non-profit and for-profit organizations?","options":["how they make decisions","how they judge success","how they motivate staff","how they recruit staff"],"correctOption":1,"section":"Managers and Management","explanation":"The big difference is how each \"keeps score\": for-profit firms judge success mainly by profit, while non-profits judge it by how well they serve their mission, such as helping a community. Decision making, motivation and hiring (options A, C and D) work in broadly similar ways in both types of organization."}},{"itemId":"5604a0ac-1a59-5336-add8-3cf4ee8a33a8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d0e05a0-e640-5950-bf65-ab174e0a94f7","sourceKey":"bank:AMS101:AMS101-T049","parentItemId":null,"revision":1,"payload":{"prompt":"Which role matters more to managers of small organizations than to managers of large companies?","options":["disseminator","spokesperson","entrepreneur","resource allocator"],"correctOption":1,"section":"Managers and Management","explanation":"In a small organization the manager is often the main face of the business, representing it to customers, bankers and the public, so the spokesperson role is especially important. Resource allocator (option D) matters more in large organizations, where managers spend much of their time deciding who gets what. Entrepreneur (option C) is important in small firms too, but spokesperson is the role singled out as most important there."}},{"itemId":"29d73026-1f0c-5e83-839d-3951efbede87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"96fc7351-7e1d-585c-9755-85c4f7627ba3","sourceKey":"bank:AMS101:AMS101-T050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is LEAST likely to describe a small organization?","options":["Planning is not likely to be an elaborate, formal ritual.","Relationships tend to be informal.","Employees are likely to be tracked by computerised monitoring systems.","The organization's design is likely to be simpler and less structured."],"correctOption":2,"section":"Managers and Management","explanation":"Small organizations usually rely on direct, personal supervision rather than formal, computerised systems to keep track of employees, so option C is the one that does not fit. Options A, B and D all describe typical features of small organizations: informal planning, informal relationships and a simple, loose structure."}},{"itemId":"18939344-96dc-52e3-bee1-01bc8206d494","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2cb8bcc6-192d-50c9-88b6-c7485a20f59a","sourceKey":"bank:AMS101:AMS101-T052","parentItemId":null,"revision":1,"payload":{"prompt":"Why might a non-profit manager seem just as worried about money as a for-profit manager?","options":["Non-profit managers are judged only on financial results.","Non-profit managers like to appear to care about the \"bottom line\".","Many non-profits run on tight budgets and must be very efficient.","Non-profits are required to make a profit."],"correctOption":2,"section":"Managers and Management","explanation":"Many non-profits work with very limited funds, so their managers must manage money carefully and get the most out of every naira. Option A is wrong because non-profits are judged mainly on how well they serve their mission. Option D is wrong because non-profits do not exist to make a profit."}},{"itemId":"54e6e255-abdb-5548-a539-60e6d89e0362","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1e1c9b0-bdce-5e4d-a5d9-dc822ac469ca","sourceKey":"bank:AMS101:AMS101-T053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT counted as a political skill for a manager?","options":["a dominant personality","networking ability","social astuteness","sincerity"],"correctOption":0,"section":"Managers and Management","explanation":"Political skill involves reading social situations well, building networks, influencing others and coming across as sincere, so a dominant personality is not one of them. Networking ability, social astuteness and sincerity (options B, C and D) are all recognised parts of political skill."}},{"itemId":"ee5128ea-999d-5cdf-a8e1-e0e2da2563ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1fecf465-c729-520d-973f-a15b5be8e08b","sourceKey":"bank:AMS101:AMS101-T054","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with someone managing a large organization, a small business manager is more likely to be a(n) ______.","options":["specialist","figurehead","generalist","information monitor"],"correctOption":2,"section":"Managers and Management","explanation":"A small business has few people, so its manager has to handle many different tasks that big firms would give to separate specialists, which makes the manager a generalist. Option A describes managers in large organizations, where work is divided into specialised jobs. Figurehead and monitor (options B and D) are roles every manager plays, not features that set small business managers apart."}},{"itemId":"c596c282-ab69-5972-98f5-ca486d865a66","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3d2edc17-d698-5d67-bc3a-ef894b3de928","sourceKey":"bank:AMS101:AMS101-T055","parentItemId":null,"revision":1,"payload":{"prompt":"Unlike a small business manager, a manager in a large organization focuses mainly on ______.","options":["external matters, especially entrepreneurial work","internal matters, especially sharing out resources","setting goals","planning ways to improve the structure"],"correctOption":1,"section":"Managers and Management","explanation":"In a large organization, deciding who gets which resources is a major and constant concern, so the manager's focus is mostly internal. Option A describes the small business manager, who looks outward and acts more as an entrepreneur and spokesperson. Setting goals and improving structure (options C and D) matter too, but they are not the main focus that separates the two kinds of manager."}},{"itemId":"e0e890e7-e9da-5536-948f-c56fd68fcc80","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"114a14b4-dded-5a1a-a547-61e3732f0d02","sourceKey":"bank:AMS101:AMS101-T056","parentItemId":null,"revision":1,"payload":{"prompt":"A business has only about 100 employees. What would stop it from being classed as a small business?","options":["It makes no profit.","It has a major influence on its industry.","It makes a large profit.","It has no influence on its industry."],"correctOption":1,"section":"Managers and Management","explanation":"A small business is one that has relatively few employees, is independently owned and has no dominant influence on its industry, so a firm with a major impact on its industry would not count as small. Profit, whether low or high (options A and C), is not part of the definition. Option D actually fits a small business rather than ruling it out."}},{"itemId":"1c06f3be-3f5c-5267-8253-ebf3f33ba2b8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"871d91f5-0b14-5cf5-9fdb-1fa2109d62c1","sourceKey":"bank:AMS101:AMS101-T057","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is networking most likely to help a manager achieve?","options":["greater efficiency","greater effectiveness","setting goals","building a power base"],"correctOption":3,"section":"Managers and Management","explanation":"Networking means building relationships with people inside and outside the organization. Those connections give a manager allies and influence, which is what a power base is, and building one is the job of political skills. Efficiency (option A) is about using resources well and effectiveness (option B) is about reaching goals, while setting goals (option C) is part of planning."}},{"itemId":"13df4904-325e-5504-9b9f-0c1e559a41e5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"11558d9c-5a7a-593d-b503-425b2a007880","sourceKey":"bank:AMS101:AMS101-T058","parentItemId":null,"revision":1,"payload":{"prompt":"Almost every managerial task involves ______.","options":["making decisions","technical skills","long-term planning","excellent political skills"],"correctOption":0,"section":"Managers and Management","explanation":"Whatever managers are doing, whether planning, organizing, leading or controlling, they are constantly making choices, so decision making runs through nearly all managerial work. Technical skills, long-term planning and political skills (options B, C and D) are needed for some tasks but not for almost all of them."}},{"itemId":"68d77e70-b371-568f-998a-016cc35fa403","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8580162b-171f-56b5-90d9-d7877d134792","sourceKey":"bank:AMS101:AMS101-T059","parentItemId":null,"revision":1,"payload":{"prompt":"In the four-skill version of Katz's framework, the critical managerial skills are ______.","options":["technical, political, conceptual and empirical","interpersonal, political, empirical and technical","technical, interpersonal, political and controlling","technical, political, interpersonal and conceptual"],"correctOption":3,"section":"Managers and Management","explanation":"The four skills are technical, interpersonal, conceptual and political. Options A and B include \"empirical\" skills, which are not part of the scheme. Option C includes \"controlling\", which is a management function, not a skill."}},{"itemId":"005fa917-e549-57c6-bb1e-f07787750cc9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e78ac841-8904-581d-9db9-ac8aabc81c47","sourceKey":"bank:AMS101:AMS101-T060","parentItemId":null,"revision":1,"payload":{"prompt":"For a building contractor, knowing the building codes would count as a(n) ______ skill.","options":["interpersonal","technical","conceptual","political"],"correctOption":1,"section":"Managers and Management","explanation":"Technical skills are the job-specific knowledge and techniques needed to do a particular kind of work, and building codes are exactly that kind of specialised knowledge for a contractor. Interpersonal and political skills (options A and D) are about dealing with people. Conceptual skills (option C) involve analysing and thinking through complex situations, not knowing specific regulations."}},{"itemId":"eb9e05f8-4e08-5582-9bd8-4d8a3852b7d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a735523f-9a7a-5537-bf2a-11cd089e4961","sourceKey":"bank:AMS101:AMS101-T061","parentItemId":null,"revision":1,"payload":{"prompt":"Being good at motivating subordinates belongs under which category of skills?","options":["interpersonal skills","conceptual skills","technical skills","political skills"],"correctOption":0,"section":"Managers and Management","explanation":"Motivating others means working well with people, which is what interpersonal skills are about. Conceptual skills (option B) involve analysing complex situations, and technical skills (option C) are specialised job knowledge. Political skills (option D) concern building power and influence, rather than inspiring staff to do their best."}},{"itemId":"cd40a810-7cb6-5497-9335-b775aac9ce04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6f01ae4a-6494-5e53-a565-40672d24e802","sourceKey":"bank:AMS101:AMS101-T063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these could be a technical skill?","options":["excellent speaking skills","skill in computer programming","outstanding writing ability","ability to make decisions"],"correctOption":1,"section":"Managers and Management","explanation":"Technical skills are specialised, job-specific abilities, and computer programming is a clear example. Speaking and writing well (options A and C) are general communication abilities that support interpersonal skills, and decision making (option D) is a broad ability that draws on conceptual skills."}},{"itemId":"0bbe8fa0-8e26-5a56-80a9-e24d7b975fc9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8147d209-06b1-584c-97a1-ff7908b01566","sourceKey":"bank:AMS101:AMS101-T064","parentItemId":null,"revision":1,"payload":{"prompt":"Strong political skills would matter most to a manager who ______.","options":["wants job security","wants fair pay for his or her level","wants to move up the organization","wants a lighter workload"],"correctOption":2,"section":"Managers and Management","explanation":"Political skills help managers build a power base and the right connections, which is what helps people rise through the ranks. Job security, fair pay and a lighter workload (options A, B and D) do not depend nearly as much on building influence and allies."}},{"itemId":"7d89ce6a-6afb-5bad-a06d-aabbd18caed6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"27285274-0a8a-5d5f-ac77-cad55a6fd64c","sourceKey":"bank:AMS101:AMS101-T065","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of skills would a country's president be least likely to need?","options":["interpersonal","political","conceptual","technical"],"correctOption":3,"section":"Managers and Management","explanation":"A president needs strong political, interpersonal and conceptual skills to lead, win support and think through complex national issues. Technical skills, meaning specialised, hands-on job knowledge, matter least at this top level, because experts and officials handle the technical details."}},{"itemId":"572e8ea4-a9fe-5bee-8b14-062d7edfbc49","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cdca065c-4add-58db-bcb7-5c0c62129f00","sourceKey":"bank:AMS101:AMS101-T067","parentItemId":null,"revision":1,"payload":{"prompt":"Who would gain the least from studying management?","options":["a professional football coach","a professional football fan","a professional football club owner","a professional football player"],"correctOption":1,"section":"Managers and Management","explanation":"A fan simply watches and supports, and is not responsible for running or working within the club, so studying management helps them least. The coach (option A) manages players directly, the owner (option C) runs the club as an organization, and the player (option D) works under managers, so all three can use management knowledge."}},{"itemId":"42efd3c1-d2b7-5812-aa22-84ebef84badc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4edfa053-eca2-5994-85a2-0cf5c4cfb2aa","sourceKey":"bank:AMS101:AMS101-T068","parentItemId":null,"revision":1,"payload":{"prompt":"Why should all of us care about how organizations are managed?","options":["We all make money from organizational profits.","We deal with organizations every day of our lives.","We all rely on organizations for jobs.","Organizations control every part of our lives."],"correctOption":1,"section":"Managers and Management","explanation":"Every day we deal with organizations, such as schools, banks, hospitals, shops and transport companies, so how well they are managed affects us all. Options A and C are not true for everyone, because some people do not earn from or work for organizations. Option D is an exaggeration."}},{"itemId":"d1fa5037-de11-5cec-917a-bb4d24846f81","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"813bcd8c-eb11-56d0-9365-f786b4be7caa","sourceKey":"bank:AMS101:AMS101-T069","parentItemId":null,"revision":1,"payload":{"prompt":"During hard economic times, well-managed companies can still prosper by relying on ______.","options":["government bailouts","filing for bankruptcy","raising their prices","a loyal customer base"],"correctOption":3,"section":"Managers and Management","explanation":"Well-managed companies build strong customer loyalty, and loyal customers keep buying even when times are hard. Bailouts and bankruptcy (options A and B) are signs of trouble, not ways to prosper. Raising prices (option C) during a downturn is more likely to drive customers away."}},{"itemId":"74cf7de9-4e95-5e05-809a-2e0c4f8a9b04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db626bbc-e3d5-5428-8ec4-9c7b27a45d24","sourceKey":"bank:AMS101:AMS101-T070","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is the hardest ethical challenge facing managers in today's business climate?","options":["being unable to hire new staff","having to dismiss staff who are not productive","having to downsize and lay off staff who are hardworking and productive","making employees pay more towards their health insurance"],"correctOption":2,"section":"Managers and Management","explanation":"Letting go of people who have worked hard and done nothing wrong is the toughest ethical position for a manager. Dismissing unproductive staff (option B) is easier to justify because it is based on performance. Being unable to hire (option A) and asking employees to pay more for health insurance (option D) are difficult, but they are not as hard ethically as laying off good workers."}},{"itemId":"2d0da4d6-7aa5-5390-9e6c-65efc6a56280","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4818d6a1-05b7-5485-9ae2-a2d336b41991","sourceKey":"bank:AMS101:AMS101-T071","parentItemId":null,"revision":1,"payload":{"prompt":"Why can studying management help even people who never plan to become managers?","options":["They are likely to be managed at some point in their careers.","Everybody ends up becoming a manager.","They need to be able to outwit their managers.","Management helps people control their emotions."],"correctOption":0,"section":"Managers and Management","explanation":"Most people work under managers at some point, so understanding how managers think and behave helps them work better with their bosses and understand the organization. Option B is not true, since not everyone becomes a manager. Options C and D are not the real reasons for studying management."}},{"itemId":"3e716c3c-aced-5ddb-84d3-45fa2bbfd13b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b26c637-a6de-5f25-97db-02b174282f63","sourceKey":"bank:AMS101:AMS101-T072","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these shows that a company is well managed?","options":["It builds a customer base quickly.","It finds ways to prosper even when the economy is hard.","It does not have to worry about customer loyalty.","It finds ways to prosper when the economy is booming."],"correctOption":1,"section":"Managers and Management","explanation":"Many companies can make money when the economy is booming (option D), so the real test of good management is doing well when times are tough. Building customers quickly (option A) does not prove the business will last. Option C is wrong because even the best-run companies must work to keep their customers loyal."}},{"itemId":"011731fa-92f8-56e1-8fa7-c1f5bafe9298","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78ee880b-ee60-5ecf-8ffa-cb48d76d0bb2","sourceKey":"bank:AMS101:AMS101-T073","parentItemId":null,"revision":1,"payload":{"prompt":"One common thread in the changes facing managers today is the need to rely on ______ to find ways of raising productivity.","options":["every member of the organization","productivity specialists","top managers alone","efficiency consultants"],"correctOption":0,"section":"Managers and Management","explanation":"Managers increasingly recognise that the people doing the work often have the best ideas for improving it, so they draw on everyone in the organization. Outside specialists and consultants (options B and D) can help, but they do not know the work as well as the people doing it. Relying only on top managers (option C) ignores most of the knowledge in the organization."}},{"itemId":"fc3e0028-6d71-5ea6-b9c4-b81f603216eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d88fd61f-b445-58bc-9803-9a2b6918b8c7","sourceKey":"bank:AMS101:AMS101-T074","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a factor that managers have to deal with in today's tough economic climate?","options":["changing technology","economic uncertainty","employees who are unwilling to work","mistrust between managers and employees"],"correctOption":2,"section":"Managers and Management","explanation":"Today's managers face fast-changing technology, an uncertain economy and strained trust between managers and employees, so options A, B and D are real challenges. Employees who are unwilling to work are not described as one of the defining pressures of the current climate, which makes C the odd one out."}},{"itemId":"ef8614e4-0160-5d55-a7bd-902d6e281dc7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f447c13-2005-547e-ba26-4ad3940e20f1","sourceKey":"bank:AMS101:AMS101-T076","parentItemId":null,"revision":1,"payload":{"prompt":"How are customers changing the job of the modern manager?","options":["Managers are starting to see customers as opponents in a fight for survival.","Managers are letting customers take charge of planning and designing new products.","Managers are placing less weight on customer satisfaction as a key goal.","Managers are increasingly making customer satisfaction a key goal."],"correctOption":3,"section":"Managers and Management","explanation":"Managers now see that organizations need customers to survive, so keeping customers satisfied has become a key goal. Option C says the opposite, and option A wrongly treats customers as enemies. Option B goes too far: customers may give input, but managers do not hand over control of product planning and design."}},{"itemId":"fb34d936-faf8-5e27-a22e-84486f1b7017","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"132d05cd-35c8-528c-a6b3-79ef3a65e0a1","sourceKey":"bank:AMS101:AMS101-T078","parentItemId":null,"revision":1,"payload":{"prompt":"When a company answers its phone promptly with a polite, helpful human operator, what does this tell the customer?","options":["The company charges high prices.","The company is wasting money on phone operators.","The company is responsive to customers' needs.","The company charges low prices."],"correctOption":2,"section":"Managers and Management","explanation":"Prompt, courteous and helpful service shows that the company takes its customers seriously and is ready to respond to their needs. It says nothing about whether prices are high or low (options A and D). Option B misses the point, because good customer service is an investment in keeping customers, not a waste."}},{"itemId":"29110840-430d-50f1-bb7a-b9eca5119983","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc0cede5-8360-593f-a1cd-8cb7f202250c","sourceKey":"bank:AMS101:AMS101-T079","parentItemId":null,"revision":1,"payload":{"prompt":"Why is innovation such an important part of a manager's job today?","options":["Innovation keeps employees alert.","Innovation gives a company a \"fresh\" image without real change.","New ways of doing things are always better than old ones.","Innovation gives an organization an advantage over its competitors."],"correctOption":3,"section":"Managers and Management","explanation":"Innovation means finding new and better ways of doing things, which helps an organization stay ahead of its competitors. Option B describes cosmetic change, not true innovation. Option C is too absolute, since not every new idea is better than the old way."}},{"itemId":"52c7493c-1b50-58dc-8999-b73ca91de1d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"17455494-14df-5c75-b67d-31aef6cd638e","sourceKey":"bank:AMS101:AMS101-T084","parentItemId":null,"revision":1,"payload":{"prompt":"Which influential business thinker introduced the term \"core competency\"?","options":["W. Edwards Deming","C.K. Prahalad","Ken Blanchard","Frederick W. Taylor"],"correctOption":1,"section":"Managers and Management","explanation":"C.K. Prahalad, writing with Gary Hamel, introduced the idea of core competencies, meaning the main strengths and capabilities that give an organization its competitive edge. Deming (option A) is known for quality management, Blanchard (option C) for leadership writing, and Taylor (option D) for scientific management."}},{"itemId":"70e4d357-d732-57dc-8839-7f6cc16b71ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"33ff6f72-dc36-5f08-8781-68afeb95b352","sourceKey":"bank:AMS101:AMS101-T085","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about managers in today's world is correct?","options":["They are all aged between 30 and 65.","They work only in large corporations.","They work only in organizations that aim to make a profit.","The quality of employees' relationship with their direct supervisor is the most important factor in employee productivity and loyalty."],"correctOption":3,"section":"Managers and Management","explanation":"Option D is correct because the way supervisors treat and relate to their people strongly shapes how productive and loyal employees are. Options A, B and C are all false: managers come in all ages, and they work in small and large organizations, non-profits as well as for-profits."}},{"itemId":"aa4d5e0c-c585-578b-9a2b-2c2489d8aba5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a466939-4de5-5620-aea3-2a2120298ccf","sourceKey":"bank:AMS101:AMS101-T087","parentItemId":null,"revision":1,"payload":{"prompt":"A person who works with and through others, coordinating their work activities so that organizational goals are achieved, is ______.","options":["a highly intelligent person","a supervisor of production work","a manager","an operations supervisor"],"correctOption":2,"section":"Managers and Management","explanation":"This is the definition of a manager: someone who coordinates and oversees other people's work so the organization reaches its goals. Options B and D describe particular kinds of managers in specific areas, so they are too narrow for a general definition. Intelligence (option A) has nothing to do with the definition."}},{"itemId":"c60ea422-46da-5296-a4b0-8027e0c1b2b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7bbc604b-62ea-575b-9a8d-1941f0ff7f53","sourceKey":"bank:AMS101:AMS101-T090","parentItemId":null,"revision":1,"payload":{"prompt":"Titles such as agency head or plant manager are most likely to belong to which management level?","options":["team leaders","middle managers","first-line managers","top managers"],"correctOption":1,"section":"Managers and Management","explanation":"Agency heads and plant managers are middle managers: they run a unit or site and sit between the top managers and the first-line supervisors. Top managers (option D) run the organization as a whole, while team leaders and first-line managers (options A and C) supervise frontline workers directly."}},{"itemId":"51d94b36-291b-539c-a99b-ab42dd5fe67f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bba2ebe3-36fc-5d54-982e-11329e1ec6ca","sourceKey":"bank:AMS101:AMS101-T091","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is the lowest level of management?","options":["a nonmanagerial employee","a research department manager","a vice president","a first-line manager"],"correctOption":3,"section":"Managers and Management","explanation":"First-line managers form the lowest level of management, directly overseeing the work of nonmanagerial staff. A nonmanagerial employee (option A) is not part of management at all. A research department manager (option B) is at the middle level, and a vice president (option C) is a top manager."}},{"itemId":"574ce0da-4eb7-5f32-9a88-d79f60a3d85e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"450ee3de-d727-59f2-97de-ad1a37c7211f","sourceKey":"bank:AMS101:AMS101-T092","parentItemId":null,"revision":1,"payload":{"prompt":"Which group of managers is also known as supervisors?","options":["team leaders","middle managers","first-line managers","top managers"],"correctOption":2,"section":"Managers and Management","explanation":"First-line managers are commonly called supervisors, since they directly oversee nonmanagerial employees' day-to-day work. Middle and top managers (options B and D) are above this level. Team leader (option A) is one first-line title, but supervisor is the general name for the whole first-line level."}},{"itemId":"be556238-c878-53d1-bba0-627e6b0d2057","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cae88782-f809-5660-ad43-3be723b5db15","sourceKey":"bank:AMS101:AMS101-T093","parentItemId":null,"revision":1,"payload":{"prompt":"Managers holding titles such as department head, project leader, plant manager or division manager are ______.","options":["first-line managers","top managers","production managers","middle managers"],"correctOption":3,"section":"Managers and Management","explanation":"These titles belong to middle managers, who sit between top management and the first-line level and manage other managers. Top managers (option B) carry titles like CEO or managing director, and first-line managers (option A) are usually called supervisors. Production manager (option C) describes a functional area, not a level of management."}},{"itemId":"07608410-2762-53a2-aec2-2cf582feed57","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e304cbc-d65c-5c77-bdc3-543f03edb74d","sourceKey":"bank:AMS101:AMS101-T094","parentItemId":null,"revision":1,"payload":{"prompt":"At which management level would you place a division manager?","options":["team leaders","middle managers","first-line managers","top managers"],"correctOption":1,"section":"Managers and Management","explanation":"A division manager runs one part of the organization and reports to top management, which makes the role a middle management position. Top managers (option D) run the whole organization, while team leaders and first-line managers (options A and C) supervise nonmanagerial staff directly."}},{"itemId":"dcd9431b-96d4-57fa-912c-dd2e1f8916e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a8d4c00-833a-549b-8dda-a5eadd24987a","sourceKey":"bank:AMS101:AMS101-T095","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the process of getting activities done efficiently and effectively with and through other people.","options":["Leading","Management","Supervision","Controlling"],"correctOption":1,"section":"Managers and Management","explanation":"This is the definition of management: coordinating and overseeing work so that it gets done efficiently and effectively through others. Leading and controlling (options A and D) are just two of the functions within management. Supervision (option C) is a narrower idea, linked mainly with first-line managers."}},{"itemId":"91deeee9-0a78-5b90-acb6-f2a4d876a61d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"35040497-f225-5a66-abf5-f2cd23427fbf","sourceKey":"bank:AMS101:AMS101-T097","parentItemId":null,"revision":1,"payload":{"prompt":"______ is what separates a managerial position from a nonmanagerial one.","options":["Manipulating other people","Concern for the law","Raising efficiency","Coordinating and integrating other people's work"],"correctOption":3,"section":"Managers and Management","explanation":"Managers are responsible for coordinating and integrating the work of others, which is exactly what nonmanagerial employees do not do. Raising efficiency (option C) is a goal for everyone in the organization, not something only managers do. Manipulating people (option A) and concern for the law (option B) are not what define a manager."}},{"itemId":"db6d22ca-7286-5d35-9945-175ff099b248","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77d48b00-4dd9-5a4e-a0b4-69179c83fcdf","sourceKey":"bank:AMS101:AMS101-T098","parentItemId":null,"revision":1,"payload":{"prompt":"A car maker that produces more cars for the same cost, but with many defects, would be ______.","options":["both efficient and effective","increasing its efficiency","increasing its effectiveness","concerned with inputs"],"correctOption":1,"section":"Managers and Management","explanation":"Producing more cars for the same cost means getting more output from the same inputs, which is an efficiency gain. But cars full of defects do not meet the goal of producing good, reliable vehicles, so effectiveness has not improved and options A and C are wrong. Option D describes only part of the efficiency idea rather than what the company achieved."}},{"itemId":"f5381a2f-fc6b-5c11-9202-a0257c8d460a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ad19987-6bff-5357-a926-39db54c43671","sourceKey":"bank:AMS101:AMS101-T099","parentItemId":null,"revision":1,"payload":{"prompt":"What is meant by efficiency?","options":["the relationship between inputs and outputs","costs and benefits added together","the exponential pattern of costs and outputs","raising outputs no matter what it costs"],"correctOption":0,"section":"Managers and Management","explanation":"Efficiency is the relationship between inputs and outputs: getting the most output from the fewest resources. Option D is the opposite of efficiency, because ignoring cost wastes resources. Options B and C are not meaningful ways of describing the idea."}},{"itemId":"163f47dc-04f4-5411-a457-2cff5de5fecb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eadb624e-6e15-53db-a0f8-63ee28fa676c","sourceKey":"bank:AMS101:AMS101-T100","parentItemId":null,"revision":1,"payload":{"prompt":"Which list gives the functions of the management process?","options":["planning, organizing, staffing and directing","planning, organizing, leading and directing","planning, organizing, leading and staffing","planning, organizing, leading and controlling"],"correctOption":3,"section":"Managers and Management","explanation":"The management process is made up of planning, organizing, leading and controlling. Options A, B and C each include staffing or directing in place of controlling, but staffing is usually treated as part of organizing and directing as part of leading, not as separate functions."}},{"itemId":"9aa4c1e0-9ae2-525d-9ec8-7ab6b6cfba88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8224f9fd-59cc-58e9-9d27-f15334dc95ab","sourceKey":"bank:AMS101:AMS101-T101","parentItemId":null,"revision":1,"payload":{"prompt":"In successful organizations, ______.","options":["low efficiency and high effectiveness go together","high efficiency and low effectiveness go together","high efficiency and high effectiveness go together","high efficiency and high equity go together"],"correctOption":2,"section":"Managers and Management","explanation":"Successful organizations both reach their goals (high effectiveness) and use their resources well (high efficiency). Options A and B each sacrifice one of the two. Option D swaps in equity, which is not part of the efficiency and effectiveness pairing."}},{"itemId":"8623e9b6-cfe1-58c9-97d8-e786cf531aa1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a0e23728-d2bf-5423-8197-3223c54d38c0","sourceKey":"bank:AMS101:AMS101-T102","parentItemId":null,"revision":1,"payload":{"prompt":"______ is about the means of getting things done, while ______ is about the ends, meaning reaching organizational goals.","options":["effectiveness; efficiency","efficiency; effectiveness","effectiveness; goal attainment","goal attainment; efficiency"],"correctOption":1,"section":"Managers and Management","explanation":"Efficiency is about means (how well resources are used) and effectiveness is about ends (whether goals are reached). Option A swaps the two terms around. Options C and D wrongly treat goal attainment as separate from effectiveness, when the two actually mean the same thing."}},{"itemId":"5c3ed073-ccff-5f31-8ed4-8f7e58aa1706","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"611e7c08-3c98-51e8-9bc3-98411ca38255","sourceKey":"bank:AMS101:AMS101-T103","parentItemId":null,"revision":1,"payload":{"prompt":"Who proposed the five management functions of planning, organizing, commanding, coordinating and controlling?","options":["Frederick W. Taylor","Henry Ford","Chester Barnard","Henri Fayol"],"correctOption":3,"section":"Managers and Management","explanation":"Henri Fayol, the French industrialist, put forward these five functions in the early 1900s, and they later became the basis of today's four functions. Taylor (option A) is known for scientific management, and Henry Ford (option B) for mass production. Chester Barnard (option C) wrote about organizations but did not propose these functions."}},{"itemId":"86e5c833-fe78-58f6-9327-0c4666f92eed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f2f63501-bbd0-5ea2-b819-5e811cf98582","sourceKey":"bank:AMS101:AMS101-T104","parentItemId":null,"revision":1,"payload":{"prompt":"Which French industrialist identified the basic functions of management?","options":["Weber","Taylor","Herzberg","Fayol"],"correctOption":3,"section":"Managers and Management","explanation":"Henri Fayol was the French industrialist who described the basic management functions. Weber (option A) was a German sociologist known for bureaucracy, Taylor (option B) was an American engineer known for scientific management, and Herzberg (option C) is known for his work on motivation."}},{"itemId":"5b8aeffc-7d6e-5821-9b13-fc4fb57d2ad5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1799517-c3af-5881-8d49-451a1d1acf38","sourceKey":"bank:AMS101:AMS101-T105","parentItemId":null,"revision":1,"payload":{"prompt":"Writing an organization's strategic plan is an example of which management function?","options":["leading","coordinating","planning","organizing"],"correctOption":2,"section":"Managers and Management","explanation":"Planning involves defining goals and working out strategies for achieving them, and a strategic plan does exactly that. Organizing (option D) comes afterwards, arranging the work and people needed to carry out the plan. Leading (option A) deals with motivating and directing people, and coordinating (option B) is not one of the four modern functions."}},{"itemId":"c7007745-6b51-533a-8cf2-b02733b554ea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9c2b2ba-c392-5f9a-b477-0bad02e59bce","sourceKey":"bank:AMS101:AMS101-T108","parentItemId":null,"revision":1,"payload":{"prompt":"What do we call the process of monitoring, comparing and correcting?","options":["controlling","coordinating","leading","organizing"],"correctOption":0,"section":"Managers and Management","explanation":"Controlling means monitoring performance, comparing it with the goals that were set and correcting any problems. Organizing (option D) is about arranging the work, and leading (option C) is about directing and motivating people. Coordinating (option B) is not the name for this process."}},{"itemId":"0b8a0476-e9d8-5ceb-9ec7-73a1a9ae7bd4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5527171e-0c7b-5d59-bea8-9f8be72a5cb5","sourceKey":"bank:AMS101:AMS101-T109","parentItemId":null,"revision":1,"payload":{"prompt":"Mentoring is mainly linked with which management function?","options":["planning","organizing","leading","controlling"],"correctOption":2,"section":"Managers and Management","explanation":"Mentoring involves guiding, supporting and developing people, which is part of leading. Planning (option A) sets goals and strategies, organizing (option B) arranges tasks and structure, and controlling (option D) monitors performance, none of which centres on developing individuals the way mentoring does."}},{"itemId":"196c3484-8119-53fa-a8ca-5f2b44d239b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ff407b1-e6ec-58ab-8bed-e86dbc855480","sourceKey":"bank:AMS101:AMS101-T110","parentItemId":null,"revision":1,"payload":{"prompt":"In Mintzberg's framework, the ______ roles involve dealing with people and carrying out duties that are ceremonial and symbolic.","options":["informational","interpersonal","technical","decisional"],"correctOption":1,"section":"Managers and Management","explanation":"Interpersonal roles, namely figurehead, leader and liaison, involve working with people and carrying out ceremonial and symbolic duties. Informational roles (option A) involve handling information, and decisional roles (option D) involve making choices. Technical (option C) is a type of skill, not one of Mintzberg's role groups."}},{"itemId":"9bcf8329-cea2-5a0c-8230-51e11e5be626","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9795d17-1fb5-568c-8d9c-6e2ddf611dc8","sourceKey":"bank:AMS101:AMS101-T111","parentItemId":null,"revision":1,"payload":{"prompt":"The disseminator, figurehead, negotiator, liaison and spokesperson roles matter more at the ______ levels of an organization.","options":["lower","middle","higher","supervisory"],"correctOption":2,"section":"Managers and Management","explanation":"These roles involve representing the organization, linking it with outsiders, negotiating and sharing important information, which are tasks that grow in importance higher up the organization. At lower and supervisory levels (options A and D), the leader role matters more because managers work closely with frontline staff."}},{"itemId":"ed293c5f-3931-5926-8d53-63c3af5d7126","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c1afff8e-c6a0-5982-a401-28792906e29f","sourceKey":"bank:AMS101:AMS101-T112","parentItemId":null,"revision":1,"payload":{"prompt":"An HR manager attending a meeting of a local professional association for human resource managers would be acting in which role?","options":["informational","leader","liaison","disseminator"],"correctOption":2,"section":"Managers and Management","explanation":"Building contacts with people outside one's own organization is the liaison role, and a meeting of fellow HR professionals is a good example. The leader role (option B) involves directing and motivating one's own staff. Disseminator (option D) means passing information on to people inside the organization, and informational (option A) is a group of roles that does not include liaison."}},{"itemId":"3d1ef927-e638-5467-84bc-376e50a51689","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94812994-bb83-5704-80ce-86601a5264db","sourceKey":"bank:AMS101:AMS101-T113","parentItemId":null,"revision":1,"payload":{"prompt":"Which role matters more for lower-level managers than for middle or top managers?","options":["leader","entrepreneur","spokesperson","disseminator"],"correctOption":0,"section":"Managers and Management","explanation":"Lower-level managers work most closely with the employees doing the work, so directing and motivating them, the leader role, matters most at this level. Spokesperson and disseminator (options C and D) become more important higher up, where managers represent the organization and share information widely. Entrepreneur (option B) is not the role that stands out at lower levels."}},{"itemId":"7c8e1fec-418a-5a46-aaf4-d5763cd76bb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e03c2c95-81ef-5dfb-b811-0cda908a1e65","sourceKey":"bank:AMS101:AMS101-T114","parentItemId":null,"revision":1,"payload":{"prompt":"Many of Mintzberg's roles fit with the basic management functions. For example, the ______ role forms part of planning.","options":["figurehead","leader","liaison","resource allocation"],"correctOption":3,"section":"Managers and Management","explanation":"Deciding how to share out money, people and time is closely tied to planning, so resource allocation fits within the planning function. Figurehead, leader and liaison (options A, B and C) are interpersonal roles, which fit with the leading function instead."}},{"itemId":"45de7e98-e5d0-50d0-a06b-a97b37ea8ce6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e1738818-6e98-5480-954a-4286134903fe","sourceKey":"bank:AMS101:AMS101-T115","parentItemId":null,"revision":1,"payload":{"prompt":"How much emphasis managers place on different roles appears to depend on their ______.","options":["level in the organization","length of service with the organization","experience in their field","personality"],"correctOption":0,"section":"Managers and Management","explanation":"Managers at different levels of the hierarchy emphasise different roles. For example, the leader role is more important at lower levels, while roles such as figurehead and spokesperson matter more at the top. Length of service, experience and personality (options B, C and D) may affect individuals, but level is the main factor."}},{"itemId":"be101d65-f235-56fb-aa55-79586c1ba821","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9f05abbe-81a2-5620-8487-74f43e25a268","sourceKey":"bank:AMS101:AMS101-T116","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of Mintzberg's interpersonal roles?","options":["figurehead","leader","liaison","spokesperson"],"correctOption":3,"section":"Managers and Management","explanation":"Spokesperson is an informational role, because it involves passing information to people outside the organization. Figurehead, leader and liaison (options A, B and C) make up the three interpersonal roles, which involve dealing with people and ceremonial duties."}},{"itemId":"cab6f5f7-0c97-5556-bd6f-878033b56862","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e7463ff-53ac-5946-bd69-d09f8f1cb770","sourceKey":"bank:AMS101:AMS101-T117","parentItemId":null,"revision":1,"payload":{"prompt":"In Mintzberg's framework, the ______ roles involve receiving, gathering and spreading information.","options":["interpersonal","informational","technical","decisional"],"correctOption":1,"section":"Managers and Management","explanation":"Informational roles, namely monitor, disseminator and spokesperson, deal with collecting, receiving and passing on information. Interpersonal roles (option A) involve dealing with people and ceremonial duties, and decisional roles (option D) involve making choices. Technical (option C) is not a group of roles in this framework."}},{"itemId":"e97608ce-ea64-57a2-adcf-121f124afe9b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc4995f1-630c-59fd-9c7e-0916fdfe7aee","sourceKey":"bank:AMS101:AMS101-T118","parentItemId":null,"revision":1,"payload":{"prompt":"Many of Mintzberg's roles fit with the basic management functions. For example, all three interpersonal roles belong to the ______ function.","options":["organizing","planning","leading","controlling"],"correctOption":2,"section":"Managers and Management","explanation":"The interpersonal roles of figurehead, leader and liaison all involve dealing with people, which fits within the leading function. Planning (option B) links more with roles like resource allocator and entrepreneur, while organizing and controlling (options A and D) are about arranging and monitoring work rather than relating to people."}},{"itemId":"ffb7ecb1-b777-5800-bc28-b1352738dafe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"273a30d5-4df4-5f6a-a1d9-7300316e63aa","sourceKey":"bank:AMS101:AMS101-T119","parentItemId":null,"revision":1,"payload":{"prompt":"All of the following managerial roles are more important at the higher levels of an organization EXCEPT ______.","options":["leader","disseminator","figurehead","negotiator"],"correctOption":0,"section":"Managers and Management","explanation":"The leader role is the exception, because it matters most for lower-level managers who work directly with frontline employees. Disseminator, figurehead and negotiator (options B, C and D) all grow in importance higher up, where managers represent the organization, share information and negotiate on its behalf."}},{"itemId":"8637fdb1-e421-520f-972d-5c072bfc4200","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"37736fba-51fb-5f02-8e8c-cbf50275d804","sourceKey":"bank:AMS101:AMS101-T120","parentItemId":null,"revision":1,"payload":{"prompt":"The three essential managerial skills identified by Katz are ______.","options":["technical, human and empirical","human, empirical and conceptual","technical, interpersonal and controlling","technical, human and conceptual"],"correctOption":3,"section":"Managers and Management","explanation":"Katz identified three essential skills: technical, human and conceptual. Options A and B include \"empirical\", which is not one of his skills. Option C includes \"controlling\", which is a management function rather than a skill."}},{"itemId":"3f29eacc-f8fe-5462-a009-35a77e0b7408","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e9121136-a40c-50d4-b39e-7c3a8321adfb","sourceKey":"bank:AMS101:AMS101-T122","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about human and technical skills is true?","options":["Human and technical skills stay equally important as managers move up.","Technical skills stay necessary while human skills decline as managers move up.","Human skills stay necessary while the need for technical skills declines as managers move up.","The need for both human and technical skills declines as managers move up."],"correctOption":2,"section":"Managers and Management","explanation":"Human skills are important at every level because all managers work with people, while technical skills matter most at lower levels and become less important higher up. Option B gets this the wrong way round. Options A and D are wrong because the two skills do not change in the same way."}},{"itemId":"f7278e4f-9ed0-531c-a258-92c33eee295b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a0c46db-a2a7-5d2e-b1c3-ed883be3a2b9","sourceKey":"bank:AMS101:AMS101-T123","parentItemId":null,"revision":1,"payload":{"prompt":"Managers who have strong ______ can bring out the best in their people.","options":["human skills","conceptual skills","technical skills","visual skills"],"correctOption":0,"section":"Managers and Management","explanation":"Human skills are the ability to work well with others, communicate, motivate and inspire, which is what gets the best out of people. Conceptual skills (option B) help with analysing complex situations, and technical skills (option C) are specialised job knowledge. Visual skills (option D) are not one of the managerial skill types."}},{"itemId":"73399230-0ecb-56c9-a42a-c7007e1bcb44","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"53897fe3-3591-575f-9a7f-b335e9bc8dad","sourceKey":"bank:AMS101:AMS101-T125","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who gets along well with people, whether one-on-one or in a team, is showing which kind of skills?","options":["technical skills","behavioural skills","planning skills","human skills"],"correctOption":3,"section":"Managers and Management","explanation":"Human skills are the abilities to work well with other people, both individually and in groups, which includes communicating, motivating and leading. Option B sounds similar, but \"behavioural skills\" is not one of Katz's three managerial skill types (technical, human and conceptual). Option A refers to job-specific know-how, not people skills."}},{"itemId":"41a079b9-b275-55bc-b8d0-ed9bd18ccda8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"95aecfa2-4250-5a1a-9f80-d5df25bb1e85","sourceKey":"bank:AMS101:AMS101-T126","parentItemId":null,"revision":1,"payload":{"prompt":"Phrases like \"thinking about abstract situations\" and \"visualising the whole\" describe which type of managerial skill?","options":["interpersonal","human","technical","conceptual"],"correctOption":3,"section":"Managers and Management","explanation":"Conceptual skills let a manager think through abstract and complex situations and picture the organisation as a whole and how its parts fit together. Options A and B are about dealing with people, while option C is about expertise in specific work methods and tools."}},{"itemId":"94fb0a1d-0424-50dd-b497-a140f8589ff9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e06833c8-3dc3-5a65-9639-cae15c93d2e1","sourceKey":"bank:AMS101:AMS101-T127","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these phrases fits best with a manager's conceptual skills?","options":["motivating subordinates","talking with customers","applying information to solve business problems","knowing the product well"],"correctOption":2,"section":"Managers and Management","explanation":"Conceptual skills are the ability to analyse and diagnose complex situations, so using information to work out solutions to business problems is the clearest match. Motivating subordinates (option A) and talking with customers (option B) rely on interpersonal skills, while knowing the product well (option D) is technical knowledge."}},{"itemId":"3d548126-5448-5c90-86a5-7d8250823a8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df780570-02ea-5352-bd46-68697dd08a12","sourceKey":"bank:AMS101:AMS101-T128","parentItemId":null,"revision":1,"payload":{"prompt":"Which managerial skill is more important for first-line managers than for top managers?","options":["human","technical","conceptual","empirical"],"correctOption":1,"section":"Managers and Management","explanation":"Technical skills, the job-specific knowledge and techniques needed to do the work, matter most at the first-line level because these managers supervise that work up close, and they become less important higher up. Human skills (option A) are tempting, but they are equally important at every level, so they are not more important at the bottom. Conceptual skills (option C) grow in importance toward the top, and empirical (option D) is not a managerial skill type."}},{"itemId":"8eb22220-258d-5bd6-8fb8-b62cad5523ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"816a13b0-e499-537c-955c-ef7c96339cdd","sourceKey":"bank:AMS101:AMS101-T129","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best defines an organisation?","options":["the physical place where people go to work","a group of people who are all employed by one company","a deliberate arrangement of people to accomplish some specific purpose","a set of people concentrating on making profit for shareholders"],"correctOption":2,"section":"Managers and Management","explanation":"An organisation is a deliberate arrangement of people brought together to accomplish a specific purpose, and it has a purpose, people and a deliberate structure. Option A confuses the organisation with its building. Option D is too narrow, since schools, hospitals and charities are organisations even though they are not profit-seekers."}},{"itemId":"80d09968-6e5d-53d6-98e3-64d66c8726bb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b4d8d271-6275-5e35-903e-27beb2af8294","sourceKey":"bank:AMS101:AMS101-T130","parentItemId":null,"revision":1,"payload":{"prompt":"All organisations share some common characteristics. Which one is usually expressed in the form of the organisation's goals?","options":["its people","its technology","its systematic structure","its purpose"],"correctOption":3,"section":"Managers and Management","explanation":"Every organisation exists for a distinct purpose, and that purpose is normally spelled out as a goal or set of goals. People (option A) and a deliberate structure (option C) are the other shared characteristics, but neither is expressed as goals. Technology (option B) is not one of the characteristics every organisation shares."}},{"itemId":"37463cad-d2d1-51b5-a727-aae493c5ebe3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a8bdfe2-044d-51bd-895f-76185d650ed6","sourceKey":"bank:AMS101:AMS101-T131","parentItemId":null,"revision":1,"payload":{"prompt":"Which shared characteristic of organisations makes clear how members relate to one another at work?","options":["its people","its goals","its deliberate structure","its purpose"],"correctOption":2,"section":"Managers and Management","explanation":"Every organisation develops a deliberate structure, such as rules, job descriptions and reporting lines, that defines and clarifies members' work relationships. Option A, its people, is another shared characteristic, but people on their own do not spell out who works with whom. Option D, its purpose, explains why the organisation exists, not how members relate."}},{"itemId":"2bf3ad14-fd40-53f1-89be-76dd07fcc52c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"561f7518-4e66-5226-bf43-ae5a2367a49d","sourceKey":"bank:AMS101:AMS101-T132","parentItemId":null,"revision":1,"payload":{"prompt":"What do we call a deliberate arrangement of people put together to achieve a specific purpose?","options":["a structure","a process","an organisation","an assembly operation"],"correctOption":2,"section":"Managers and Management","explanation":"That is the definition of an organisation: people deliberately arranged to accomplish a particular purpose. Option A, a structure, is only one feature of an organisation. Option B describes a series of activities, not a group of people."}},{"itemId":"448e535d-92e1-58c1-9e96-c12ced72eea9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"32720173-ea59-5337-b432-18ec14a50c40","sourceKey":"bank:AMS101:AMS101-T133","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with traditional organisations, newer organisations tend to be more","options":["stable.","focused on command.","focused on rules.","dynamic."],"correctOption":3,"section":"Managers and Management","explanation":"New organisations are flexible and dynamic, adjusting quickly to change instead of relying on fixed arrangements. Options A, B and C describe traditional organisations, which were stable, command-oriented and rule-oriented."}},{"itemId":"ae7f98cb-7794-559d-a222-f003e8b36e87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d8dd194f-f4c4-56a7-84b2-59467ca85b49","sourceKey":"bank:AMS101:AMS101-T134","parentItemId":null,"revision":1,"payload":{"prompt":"What does the \"universality of management\" mean?","options":["managers in every organisation carry out the four management functions","managers in every organisation can do their jobs in exactly the same way","any organisation can employ any manager to do its management work","any manager can move to any organisation and handle any management job"],"correctOption":0,"section":"Managers and Management","explanation":"Universality of management means management is needed in every kind and size of organisation, at all levels and in all work areas, so every manager plans, organises, leads and controls. Option B goes too far, because how managers carry out those functions differs from one setting to another. Options C and D wrongly suggest managers are interchangeable anywhere."}},{"itemId":"7fb54bd5-31d3-5c45-b18d-a0ddef433e34","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d7a237e6-142c-5a0b-8a26-fe89241736d2","sourceKey":"bank:AMS101:AMS101-T136","parentItemId":null,"revision":1,"payload":{"prompt":"What tends to happen to organisations that are well managed?","options":["they pick the best suppliers for their products","they compete internationally because their products are the best","they always offer the cheapest products","they build loyal customers, grow and prosper"],"correctOption":3,"section":"Managers and Management","explanation":"Well-managed organisations develop a loyal customer base, grow and prosper, even in hard times. Option C uses the word \"always\", which is too absolute, since good management does not guarantee the lowest prices. Options A and B describe things some firms do but are not the general result of good management."}},{"itemId":"87d582e2-664b-57d9-abd6-aba2c3853635","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3bc167ee-e61f-57d1-8dbe-73d3d8b37073","sourceKey":"bank:AMS101:AMS101-T137","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes the experience of managing in today's fast-changing workplace?","options":["it gives many rewards and quick promotions","it can be a hard and thankless job","it brings few challenges, short working weeks and high pay","it comes with clear rules, permanent jobs and flexible hours"],"correctOption":1,"section":"Managers and Management","explanation":"Managing today can be tough and thankless: managers face heavy workloads, must deal with difficult people and situations, and depend on others to get results. Option A overstates the rewards, and options C and D describe an easy, settled job that does not match today's dynamic workplace."}},{"itemId":"a799dae0-0282-5f94-8dba-6ffdc9a01779","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cb33e982-9902-5cb5-b1da-0d7eec3d66e9","sourceKey":"bank:AMS101:AMS101-T138","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's success usually depends on","options":["how hard the manager personally works","how closely the manager watches the employees","how skilled the manager is at the technical side of the job","how well other people perform their work"],"correctOption":3,"section":"Managers and Management","explanation":"Managers get things done through and with other people, so their success depends on how well others perform. Option A ignores the fact that a manager's own effort cannot replace the team's output. Option C describes what matters for individual workers, not mainly for managers."}},{"itemId":"b7103d3a-bfb9-5d2f-89a7-eafa523b37e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e685b702-8aa1-570a-87eb-4f5c552da7c7","sourceKey":"bank:AMS101:AMS101-T139","parentItemId":null,"revision":1,"payload":{"prompt":"Creating the right kind of work environment is the most important job in an organisation. What kind of environment is meant?","options":["one that is safe and well lit so employees can see clearly","one that is clean and friendly","one where members can work to the best of their ability and the organisation can reach its goals","one that suppliers like supplying and customers like buying from"],"correctOption":2,"section":"Managers and Management","explanation":"The main task is building an environment where organisational members can do their best work and, through that, the organisation achieves its goals. Options A and B describe pleasant physical conditions, which help but are not the main point. Option D focuses on outsiders rather than on members doing their work."}},{"itemId":"266dd2d9-da4e-5ce2-a943-3d3ca6c377fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f5db545-00a2-5ea2-8b5c-b6e6ae57a905","sourceKey":"bank:AMS101:AMS101-T140","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is commonly true of managers?","options":["they must follow the organisation's rules and cannot make their own decisions","they switch career paths during their working lives","they get the chance to think creatively and use their imagination","they rely on their employees to guide them in dealing with their own boss"],"correctOption":2,"section":"Managers and Management","explanation":"One of the rewards of being a manager is the chance to think creatively and use imagination in solving problems and creating a good work environment. Option A is wrong because making decisions is a core part of every manager's job. Options B and D are not general features of management."}},{"itemId":"7dd5bbd2-3edf-51a8-b8ce-9912dc098862","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9450c90a-7a6a-5439-b173-6df7006b6739","sourceKey":"bank:AMS101:AMS101-T141","parentItemId":null,"revision":1,"payload":{"prompt":"Management is needed in organisations of every type and size, at every level, in every work area and in every country. What is this idea called?","options":["the partiality of management","the segmentation of management","the universality of management","the cultures of management"],"correctOption":2,"section":"Managers and Management","explanation":"The universality of management is the idea that management is needed everywhere: in all types and sizes of organisations, at all levels, in all work areas and in all countries. Option A, partiality, suggests the opposite, that management applies only in some places. Options B and D are not recognised terms for this idea."}},{"itemId":"a26dd40d-20e5-5755-a08c-26e7dee1f259","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce50ce59-9dcf-5b39-a504-2614380a7e39","sourceKey":"bank:AMS101:AMS101-T145","parentItemId":null,"revision":1,"payload":{"prompt":"Adam Smith argued that division of labour boosts productivity for several reasons. Which of the following was NOT one of them?","options":["workers become more skilful and dexterous","less time is wasted switching between tasks","labour-saving inventions are created","management keeps strict control over workers' time and motion"],"correctOption":3,"section":"Managers and Management","explanation":"Smith said division of labour raises productivity by increasing workers' skill and dexterity, saving time lost in changing tasks, and encouraging labour-saving inventions and machinery. Strict control of time and motion (option D) is linked to later scientific management, not to Smith. Options A, B and C are all reasons Smith gave."}},{"itemId":"07a2411f-6ba7-5b28-b098-8a6e4950d255","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a89b10fa-f85a-5d55-8772-67aa9c94dfb2","sourceKey":"bank:AMS101:AMS101-T146","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is an early example of management functions being used in practice?","options":["the invention of gunpowder","the arsenal of Venice, where ships were built","the Artist's Revolution of 1803","the War of 1812"],"correctOption":1,"section":"Managers and Management","explanation":"At the arsenal of Venice, warships were moved along canals and fitted out at each stop, an early example of planning, organising and controlling work, much like an assembly line. Option A is an invention, not a management practice, and options C and D are not examples of organised management of work."}},{"itemId":"a9a234ed-46fa-569c-aa47-f0a1a03a7927","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d7156c8-3162-5191-97a3-6687f82469b1","sourceKey":"bank:AMS101:AMS101-T147","parentItemId":null,"revision":1,"payload":{"prompt":"In Wealth of Nations, Adam Smith wrote about splitting jobs into narrow, repetitive tasks. What did he call this?","options":["assembly lines","lowest common factor of work","division of labour","greatest common factor of work"],"correctOption":2,"section":"Managers and Management","explanation":"Division of labour is the breaking down of jobs into narrow, repetitive tasks, and Smith argued it greatly increased productivity. Option A, the assembly line, came much later as one application of the idea. Options B and D are not management terms."}},{"itemId":"8f01a9a6-9e4f-5d1b-9dc2-dc78385e327a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dee89c4e-3f52-541b-b953-b24694e74720","sourceKey":"bank:AMS101:AMS101-T148","parentItemId":null,"revision":1,"payload":{"prompt":"The biggest contribution of the Industrial Revolution was replacing human power with","options":["electricity.","water power.","machine power.","critical thinking."],"correctOption":2,"section":"Managers and Management","explanation":"The Industrial Revolution's major contribution was substituting machine power for human power, which made large factories possible and created a need for managers. Options A and B are forms of energy, but the big change was the use of machines. Option D is not a form of power at all."}},{"itemId":"d4f4aa64-6d67-5a23-b077-018314e14c3b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5658ab16-5d5a-5afb-8f91-c2d1addebbd2","sourceKey":"bank:AMS101:AMS101-T149","parentItemId":null,"revision":1,"payload":{"prompt":"What did the general administrative theorists concentrate on?","options":["making the whole organisation more effective","building mathematical models to improve management","raising the productivity and efficiency of workers","stressing the study of human behaviour in organisations"],"correctOption":0,"section":"Managers and Management","explanation":"General administrative theorists such as Fayol and Weber looked at what managers do and what makes good management, with the aim of making the overall organisation more effective. Option C describes scientific management, which focused on individual workers. Option B describes the quantitative approach, and option D describes organisational behaviour."}},{"itemId":"0bc188c6-f5fa-51db-ab2d-6de0104a2733","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a0dcce12-5228-5b6f-9124-b9e8146ec51f","sourceKey":"bank:AMS101:AMS101-T150","parentItemId":null,"revision":1,"payload":{"prompt":"Four management approaches developed during the first half of the twentieth century. Which of the following is NOT one of them?","options":["scientific management","general administrative","organisational behaviour","systems approach"],"correctOption":3,"section":"Managers and Management","explanation":"The four early approaches were scientific management, general administrative theory, the quantitative approach and organisational behaviour. The systems approach (option D) became popular later, as part of more modern thinking about management. Options A, B and C are all among the four early approaches."}},{"itemId":"a7d5fac4-01f2-5b56-bf34-cf559d543779","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"29b46ec9-777b-5aa8-bcec-2b32e87df4b4","sourceKey":"bank:AMS101:AMS101-T151","parentItemId":null,"revision":1,"payload":{"prompt":"Where did Frederick Taylor do most of his work?","options":["grape vineyards in California","steel companies in Pennsylvania","car assembly plants near Detroit","cotton gins in Alabama"],"correctOption":1,"section":"Managers and Management","explanation":"Taylor did most of his work at steel companies in Pennsylvania, where he studied how to make shop-floor work more efficient. His pig iron experiment took place in this steel setting. Option C may be tempting because of assembly lines, but those are linked with the car industry, not with Taylor's own studies."}},{"itemId":"f2bf724c-859f-5915-8366-26332e0b58fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"375d712c-50a9-55cb-837f-68ab0e7fd39b","sourceKey":"bank:AMS101:AMS101-T152","parentItemId":null,"revision":1,"payload":{"prompt":"Frank and Lillian Gilbreth's work started in which area?","options":["bricklaying","cutting timber","putting in basic electrical wiring","assembly lines"],"correctOption":0,"section":"Managers and Management","explanation":"Frank Gilbreth began by studying bricklaying, cutting the number of motions needed to lay a brick and greatly increasing output. Options B, C and D were not where the Gilbreths' work began."}},{"itemId":"488926d6-d118-535a-a57b-74373cc39c5d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"54005c8d-5482-5318-a013-3909ef20d79c","sourceKey":"bank:AMS101:AMS101-T153","parentItemId":null,"revision":1,"payload":{"prompt":"Frank and Lillian Gilbreth were the first to use motion pictures to study","options":["how workers react in group settings","hand and body motions","how workers react to pay rises","groups of workers giving each other tasks under pressure"],"correctOption":1,"section":"Managers and Management","explanation":"The Gilbreths filmed workers to study hand and body motions so they could remove wasted movements. They were interested in the efficiency of physical movements, not group behaviour (options A and D) or reactions to pay (option C)."}},{"itemId":"ab33e018-b7da-5061-82e4-a7ef199204b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"340695fe-20cd-5473-94ea-8061bffac639","sourceKey":"bank:AMS101:AMS101-T154","parentItemId":null,"revision":1,"payload":{"prompt":"Which phrase is most closely linked with scientific management?","options":["management relations","one best way","supply and demand","quality control"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management, associated with Taylor, used scientific methods to find the \"one best way\" to do a job. Option C is an economics idea, and option D is more closely linked to the later quality movement."}},{"itemId":"9846dc80-a636-53f1-890a-caad14918803","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30c0c78b-259f-57a8-a411-67e56e4cbfdc","sourceKey":"bank:AMS101:AMS101-T155","parentItemId":null,"revision":1,"payload":{"prompt":"What problem mainly pushed Taylor to develop a more scientific approach to management?","options":["worker efficiency","worker effectiveness","worker absenteeism and turnover","workplace safety"],"correctOption":0,"section":"Managers and Management","explanation":"Taylor was troubled by how inefficient workers were, since they used very different methods and often worked well below their capacity. Option B, effectiveness, is about doing the right things, while Taylor's focus was on doing the work with less waste. Options C and D were not his main concern."}},{"itemId":"a0e74405-dedb-5305-abbe-3133dfdb78dc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc0c02e5-fb4a-5fad-939b-fc5f1abe7011","sourceKey":"bank:AMS101:AMS101-T156","parentItemId":null,"revision":1,"payload":{"prompt":"Which experiment is probably the best-known example of Taylor's scientific management?","options":["horseshoe","pig iron","blue collar","fish tank"],"correctOption":1,"section":"Managers and Management","explanation":"In the pig iron experiment, Taylor matched the right worker with the right tools, methods and rest breaks, and output rose sharply. Options A, C and D are not studies linked to Taylor."}},{"itemId":"2fec80cc-5095-50f7-9cf8-7e6d6fe3d004","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"91158e54-51e5-5bb8-81e3-4b20b12315a5","sourceKey":"bank:AMS101:AMS101-T157","parentItemId":null,"revision":1,"payload":{"prompt":"Following his scientific management principles, what kind of pay did Taylor recommend?","options":["monthly salary","monthly salary plus bonus","pay based on seniority","incentive pay"],"correctOption":3,"section":"Managers and Management","explanation":"Taylor believed workers should earn more when they produce more, so he recommended incentive pay that ties pay to output. Options A and C pay people the same regardless of how much they produce, which goes against his idea. Option B is still mainly a fixed salary."}},{"itemId":"52f0e56a-7303-58eb-9d9c-4921203783d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1197c4a3-ffca-59d7-a22c-fba59abb6c8b","sourceKey":"bank:AMS101:AMS101-T158","parentItemId":null,"revision":1,"payload":{"prompt":"In scientific management, what workplace issue does a \"therblig\" deal with?","options":["the best temperature for efficient work","basic hand motions","the best speed for basic motions","the ratio of weight to movement"],"correctOption":1,"section":"Managers and Management","explanation":"The Gilbreths created therbligs, a scheme for classifying the basic hand motions used in a task, such as grasping or holding. Option C may look close, but therbligs name and classify the motions themselves, not their speed."}},{"itemId":"e4e10669-0273-54d4-9c7a-01e8a29b5694","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"354d6b52-d0d4-508b-bf8f-df36a4674c4a","sourceKey":"bank:AMS101:AMS101-T159","parentItemId":null,"revision":1,"payload":{"prompt":"What is general administrative theory mainly concerned with?","options":["the organisation as a whole","managers and administrators","measuring relationships in organisational design","mostly the accounting function"],"correctOption":0,"section":"Managers and Management","explanation":"General administrative theory looks at the entire organisation, studying what managers do and what makes the whole organisation effective. Option B is tempting because it studies managers' work, but its focus is on the overall organisation, unlike scientific management, which looks at individual workers. Option D is far too narrow."}},{"itemId":"8beea606-20ec-5b65-8051-0f759f6789e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c8556b9b-a6e9-52dd-8952-064707fd4923","sourceKey":"bank:AMS101:AMS101-T160","parentItemId":null,"revision":1,"payload":{"prompt":"Fayol studied ______ management issues, while Taylor studied ______ management issues.","options":["micro; macro","macro; micro","micro; micro","macro; macro"],"correctOption":1,"section":"Managers and Management","explanation":"Fayol looked at the big picture, the activities of all managers across the organisation (macro), while Taylor focused on first-line work and individual workers (micro). Option A reverses the two, and options C and D wrongly treat their focus as the same."}},{"itemId":"0a165534-b81d-5e21-b833-9dda31b5dcc3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"86b44742-ea56-51d1-9c25-d35b7f3e6701","sourceKey":"bank:AMS101:AMS101-T161","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of Fayol's principles of management?","options":["division of work","unity of command","discipline","equality"],"correctOption":3,"section":"Managers and Management","explanation":"Fayol's 14 principles include division of work, unity of command and discipline, so options A, B and C are on the list. Equality is not; the closest principle is equity, which means treating employees kindly and fairly, not treating everyone exactly the same."}},{"itemId":"1ba5b31e-40d7-5c3b-a64f-8cab7e0e81ec","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9dbb1404-9126-5aa5-934f-3ff1189f1251","sourceKey":"bank:AMS101:AMS101-T163","parentItemId":null,"revision":1,"payload":{"prompt":"In Weber's ideal bureaucracy, choosing people for jobs on the basis of their technical qualifications is called","options":["career orientation","authority hierarchy","impersonality","formal selection"],"correctOption":3,"section":"Managers and Management","explanation":"Formal selection means people are chosen for jobs based on technical qualifications measured through exams, training or education. Option A, career orientation, means managers are career professionals rather than owners. Option C, impersonality, means rules are applied the same way to everyone without personal favour."}},{"itemId":"ae79b261-98d5-504e-9071-c74c0aeee0bf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0c185907-f021-5b52-8ad5-b3939242039a","sourceKey":"bank:AMS101:AMS101-T164","parentItemId":null,"revision":1,"payload":{"prompt":"Bureaucracy is described as a type of organisation marked by","options":["division of labour","a clearly defined hierarchy","detailed rules and regulations","all of the above"],"correctOption":3,"section":"Managers and Management","explanation":"Weber's bureaucracy combines division of labour, a clearly defined hierarchy, detailed rules and regulations and impersonal relationships. Since A, B and C are all features of bureaucracy, D is the best answer."}},{"itemId":"6ca05db4-1178-5d1d-a3a0-5eb3aa85c6c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5860675a-d7e8-5c29-acee-93342b235cb0","sourceKey":"bank:AMS101:AMS101-T165","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach to management is also known as operations research or management science?","options":["the qualitative approach","the quantitative approach","the experimental approach","the theoretical approach"],"correctOption":1,"section":"Managers and Management","explanation":"The quantitative approach uses quantitative techniques such as statistics, optimisation models and simulations to improve decisions, and it is also called operations research or management science. Option A is the opposite in name and idea, and options C and D are not standard names for an approach to management."}},{"itemId":"c9e2825f-8afb-5feb-bf23-0075b9c66556","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16c8999d-72f0-5b46-9e12-0a616a700512","sourceKey":"bank:AMS101:AMS101-T166","parentItemId":null,"revision":1,"payload":{"prompt":"The quantitative approach grew out of mathematical and statistical solutions that were developed for","options":["queue problems at fast-food restaurants in the 1960s","military problems during World War II","overloaded telephone lines in the 1930s","production management problems in the 1950s"],"correctOption":1,"section":"Managers and Management","explanation":"The quantitative approach came from mathematical and statistical methods developed to solve military problems during World War II, which were later applied to business. Options A, C and D name other times and problems that are not where the approach began."}},{"itemId":"229ac967-ec47-5085-8bf5-3b9170f91919","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f83c5d1e-6eaf-598b-8e8b-f18eeda0f4f3","sourceKey":"bank:AMS101:AMS101-T169","parentItemId":null,"revision":1,"payload":{"prompt":"Which technique do managers use to make better decisions about allocating resources?","options":["Linear programming","Work scheduling","Economic order quantity modelling","Regression analysis"],"correctOption":0,"section":"Managers and Management","explanation":"Linear programming is a mathematical technique for allocating limited resources in the best way, for example deciding how much of each product to make. Option C is used for inventory decisions, and option D is used to find relationships between variables, not mainly to allocate resources."}},{"itemId":"e2a947da-6146-5764-82f8-d1d3e0949a6f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83521a00-fcb5-5e6a-a5e9-0e527310b331","sourceKey":"bank:AMS101:AMS101-T170","parentItemId":null,"revision":1,"payload":{"prompt":"Decisions about a company's best inventory levels have been strongly shaped by","options":["linear programming","work scheduling","economic order quantity modelling","regression analysis"],"correctOption":2,"section":"Managers and Management","explanation":"The economic order quantity (EOQ) model helps managers work out the best amount of stock to order and keep. Option A is a general tool for allocating resources, and option B deals with timing work, so neither is the main inventory tool."}},{"itemId":"db1385d5-8a50-5dfa-8218-f60df5e883a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00c6fbc2-526c-5541-9842-d9d729b4ab09","sourceKey":"bank:AMS101:AMS101-T171","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these would NOT be linked with the quantitative approach to management?","options":["information models","critical-path scheduling","systematic motivation of individuals","linear programming"],"correctOption":2,"section":"Managers and Management","explanation":"Motivating individuals is a people issue that belongs to the organisational behaviour approach, not the quantitative approach. Options A, B and D are all quantitative tools that help managers plan and decide using numbers and models."}},{"itemId":"8329b7a3-c91d-5908-b69d-c50e51e02fb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc5f7099-7ca6-52bd-8a86-9f2b31db16e6","sourceKey":"bank:AMS101:AMS101-T172","parentItemId":null,"revision":1,"payload":{"prompt":"Which management approach is most closely associated with concern for employee motivation?","options":["bureaucracy","organisational behaviour","scientific management","systems"],"correctOption":1,"section":"Managers and Management","explanation":"Organisational behaviour studies the actions of people at work, including motivation, leadership and teamwork. Option C, scientific management, cared about worker output and used incentive pay, but its main focus was efficient methods, not motivation itself. Option A is about rules and structure."}},{"itemId":"19b1668b-305e-51e2-8c6f-91c29a8a8959","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1813dc17-044b-5776-a0fc-bb1ea3c2e3d9","sourceKey":"bank:AMS101:AMS101-T173","parentItemId":null,"revision":1,"payload":{"prompt":"Which early supporter of organisational behaviour was concerned about terrible working conditions?","options":["Robert Owen","Hugo Munsterberg","Mary Parker Follett","Chester Barnard"],"correctOption":0,"section":"Managers and Management","explanation":"Robert Owen was a social reformer who was disturbed by harsh working conditions and argued that money spent improving workers' lives was a good investment. Munsterberg (option B) founded industrial psychology, Follett (option C) looked at individual and group behaviour, and Barnard (option D) saw organisations as social systems."}},{"itemId":"69039da3-dfaa-56ba-b181-48101aa26421","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f38761bb-0322-5e21-a3d7-9373103936ae","sourceKey":"bank:AMS101:AMS101-T174","parentItemId":null,"revision":1,"payload":{"prompt":"Which early supporter of organisational behaviour founded industrial psychology, the scientific study of people at work?","options":["Robert Owen","Hugo Munsterberg","Mary Parker Follett","Chester Barnard"],"correctOption":1,"section":"Managers and Management","explanation":"Hugo Munsterberg created the field of industrial psychology, which uses scientific methods to study people at work, for example in selection and training. Owen (option A) was a social reformer, while Follett (option C) and Barnard (option D) are known for ideas about groups and cooperation."}},{"itemId":"b677348e-3c77-58b2-ae61-85330fd3f2b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a2b602b4-fc52-534a-bdbd-f4f817fcc29f","sourceKey":"bank:AMS101:AMS101-T175","parentItemId":null,"revision":1,"payload":{"prompt":"Who was one of the first to see that organisations could be studied in terms of individual and group behaviour?","options":["Robert Owen","Hugo Munsterberg","Mary Parker Follett","Chester Barnard"],"correctOption":2,"section":"Managers and Management","explanation":"Mary Parker Follett was among the first to view organisations through individual and group behaviour, and she believed organisations should be based on a group ethic. Munsterberg (option B) focused on the psychology of individual workers, and Barnard (option D) is known for describing organisations as social and open systems."}},{"itemId":"9c688dee-d39a-55e4-b50f-c2f60d93547b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"64a0535f-3fac-510b-a7fa-3e4ba685a558","sourceKey":"bank:AMS101:AMS101-T176","parentItemId":null,"revision":1,"payload":{"prompt":"Which early supporter of organisational behaviour was the first to argue that organisations are open systems?","options":["Robert Owen","Hugo Munsterberg","Mary Parker Follett","Chester Barnard"],"correctOption":3,"section":"Managers and Management","explanation":"Chester Barnard saw organisations as social systems that need human cooperation, and he was the first to argue that they are open systems which interact with their environment. Follett (option C) focused on group behaviour, and Owen (option A) on working conditions."}},{"itemId":"4ccbc198-8bc5-55f4-8916-e5350a9655d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"385dc9c9-a13f-53b7-93ff-93e64fd5e7d7","sourceKey":"bank:AMS101:AMS101-T177","parentItemId":null,"revision":1,"payload":{"prompt":"Which four theorists belong to the early organisational behaviour approach?","options":["Barnard, Follett, Munsterberg and Owen","Munsterberg, Taylor, Fayol and Follett","Taylor, Fayol, Weber and Barnard","Follett, Barnard, Munsterberg and Weber"],"correctOption":0,"section":"Managers and Management","explanation":"The early advocates of organisational behaviour were Robert Owen, Hugo Munsterberg, Mary Parker Follett and Chester Barnard. Options B, C and D each include a classical theorist: Taylor belongs to scientific management, while Fayol and Weber belong to general administrative theory."}},{"itemId":"2d5f580e-7e67-5efe-8f1c-85a37f8d4879","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0b87768-b353-5a9d-b262-67083a365f62","sourceKey":"bank:AMS101:AMS101-T178","parentItemId":null,"revision":1,"payload":{"prompt":"What was Hugo Munsterberg's major contribution?","options":["He was a social reformer.","He founded the field of industrial psychology.","He was interested in individual and group behaviour.","He saw organisations as social systems that need human cooperation."],"correctOption":1,"section":"Managers and Management","explanation":"Munsterberg founded industrial psychology, the scientific study of people at work. Option A describes Robert Owen, option C describes Mary Parker Follett, and option D describes Chester Barnard."}},{"itemId":"4545ca8e-a3db-5fc1-84d0-585dd15daa7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94ed7370-faad-5b38-8cab-1fca015a12f8","sourceKey":"bank:AMS101:AMS101-T179","parentItemId":null,"revision":1,"payload":{"prompt":"Munsterberg's work in industrial psychology connects easily with which other management approach?","options":["general administrative","quantitative","systems","scientific management"],"correctOption":3,"section":"Managers and Management","explanation":"Munsterberg used scientific methods to study and select workers, which ties his industrial psychology closely to Taylor's scientific management, since both aimed to raise productivity through the scientific study of work. Option A looks at the whole organisation rather than individual workers, and option B, the quantitative approach, came later and uses mathematical models rather than the study of people. Option C is a later, broader way of viewing organisations."}},{"itemId":"2d2da320-9a53-5c6f-961d-c32f63c75d43","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f1a4dd0-4fb2-5b36-97d1-728bcba4603b","sourceKey":"bank:AMS101:AMS101-T180","parentItemId":null,"revision":1,"payload":{"prompt":"Modern management practices that use work groups to raise productivity can be traced back to which writer?","options":["Robert Owen","Mary Parker Follett","Chester Barnard","Hugo Munsterberg"],"correctOption":1,"section":"Managers and Management","explanation":"Mary Parker Follett believed organisations should be built on a group ethic, and her ideas shaped today's focus on teams and work groups. Barnard (option C) stressed cooperation in organisations, but the group emphasis is most closely linked to Follett. Munsterberg (option D) focused on individual workers' psychology."}},{"itemId":"88242ca3-4787-526a-b24b-d7d676877fff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"82f9f9c3-2066-5e23-bc83-5a27534231f0","sourceKey":"bank:AMS101:AMS101-T181","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement reflects Chester Barnard's views on management?","options":["An employee's ability and motivation are fixed in that person but differ between people.","To raise productivity, managers should focus on hiring the best employee instead of motivating current staff.","Productivity is best achieved by shielding the organisation from outside groups.","Organisations are social systems that need human cooperation."],"correctOption":3,"section":"Managers and Management","explanation":"Barnard saw organisations as social systems that depend on cooperation among people. Option C contradicts his view, since he believed managers must interact with outside groups such as investors, suppliers and customers. Options A and B do not reflect his ideas."}},{"itemId":"25ea7ea2-0ffb-5d9f-aba3-75898ad440fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5b996f41-42e0-5ef9-b709-ce6983f8ab19","sourceKey":"bank:AMS101:AMS101-T182","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of studies made the most important contribution to the growth of organisational behaviour?","options":["the Taylor studies","the Porter studies","the Parker studies","the Hawthorne studies"],"correctOption":3,"section":"Managers and Management","explanation":"The Hawthorne studies changed how people saw workers by showing that social and group factors strongly affect behaviour and productivity. Option A refers to scientific management work, which focused on efficiency rather than group behaviour. Options B and C are not the famous early studies."}},{"itemId":"9bc595a7-8369-508a-bea1-4bc0a7ed431b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af6d3a2b-aee9-557f-92fa-5f7e8f4389f5","sourceKey":"bank:AMS101:AMS101-T183","parentItemId":null,"revision":1,"payload":{"prompt":"What were the Hawthorne studies first designed to investigate?","options":["how productive groups are compared with individuals","how noise affects employee productivity","how lighting levels affect employee productivity","how cooperative versus competitive settings affect productivity"],"correctOption":2,"section":"Managers and Management","explanation":"The Hawthorne studies started as an experiment on how different lighting (illumination) levels affected workers' productivity. The surprising results led researchers to study group and social factors later, which is why option A may seem tempting, but that was not the original aim."}},{"itemId":"0585464b-f080-5b00-9c8e-6aac839fc81e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a2aa2a31-ca8a-5094-8fdb-953c4089ae36","sourceKey":"bank:AMS101:AMS101-T184","parentItemId":null,"revision":1,"payload":{"prompt":"Which scientist is most closely linked with the Hawthorne studies?","options":["Adams","Mayo","Lawler","Barnard"],"correctOption":1,"section":"Managers and Management","explanation":"Elton Mayo led the later stages of the Hawthorne studies, which highlighted the influence of social factors on productivity. Barnard (option D) was an early organisational behaviour thinker, but he did not run the Hawthorne studies."}},{"itemId":"b0255743-d06b-5476-8c0b-6a5b69ee1e5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0e55b5d-2b34-543a-8448-1abea85b90b5","sourceKey":"bank:AMS101:AMS101-T185","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement describes one finding of the Hawthorne studies?","options":["Social norms or group standards are the main drivers of individual work behaviour.","Money matters more than the group in determining individual productivity.","Employee behaviour and feelings move in opposite directions.","Security is fairly unimportant."],"correctOption":0,"section":"Managers and Management","explanation":"The Hawthorne studies found that group norms and social standards strongly shape how individuals behave at work. Option B is the opposite of the finding, since money turned out to be less important than group pressures. Option C is wrong because behaviour and sentiments were found to be closely related, not opposed."}},{"itemId":"af52ff47-c24f-5997-940f-70c4ddf37281","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e8794f85-59ce-5857-b5db-720d49062d9d","sourceKey":"bank:AMS101:AMS101-T187","parentItemId":null,"revision":1,"payload":{"prompt":"Workforce diversity covers differences among employees in","options":["gender","race","age","all of the above"],"correctOption":3,"section":"Managers and Management","explanation":"Workforce diversity means a workforce made up of people who differ in characteristics such as gender, race, ethnicity and age. Since A, B and C are all examples of these differences, D is correct."}},{"itemId":"725ed67e-e04e-5c9d-80ba-56f080469efd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9f086be-88d7-50bf-b3f4-7e1e9706b294","sourceKey":"bank:AMS101:AMS101-T189","parentItemId":null,"revision":1,"payload":{"prompt":"TQM differs from earlier management theories because, under TQM, costs can be reduced while also","options":["raising prices","raising productivity","letting special teams handle reworked output","laying employees off"],"correctOption":1,"section":"Managers and Management","explanation":"TQM holds that focusing on quality and continuous improvement lowers costs and raises productivity at the same time, because less work is wasted or done over. Letting special teams handle reworked output (option C) is exactly the kind of rework TQM tries to eliminate, and raising prices or laying employees off (options A and D) are not part of the TQM idea."}},{"itemId":"0a232fda-3b4c-5c6c-b55c-eba790084ded","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3dbec252-1a4b-5c87-9f38-2b0d62e63d93","sourceKey":"bank:AMS101:AMS101-T190","parentItemId":null,"revision":1,"payload":{"prompt":"A learning organisation builds the ability to","options":["add new training programmes even when rivals are going bankrupt","accept the usual wisdom of its industry","keep learning, adapting and changing","work in teams"],"correctOption":2,"section":"Managers and Management","explanation":"A learning organisation is one that has developed the capacity to continuously learn, adapt and change. Option D is something learning organisations often do, but teamwork alone does not define them. Option B is the opposite, since learning organisations question conventional wisdom."}},{"itemId":"80c005c9-b854-5697-a862-d0b12d5288bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab4f0921-a263-5088-8e23-3e8cc6260a10","sourceKey":"bank:AMS101:AMS101-T191","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the process of building businesses to take advantage of trends and changes that nobody else has noticed yet.","options":["Entrepreneurship","Division of labour","Evolution","E-commerce"],"correctOption":0,"section":"Managers and Management","explanation":"Entrepreneurship is about spotting opportunities, such as trends and changes others have not seen, and starting businesses to pursue them. Option D, e-commerce, is a way of selling online, not the process of creating ventures. Option B is about splitting work into tasks."}},{"itemId":"ece84600-3e98-5078-94a7-9c0e6ad370aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"acb91f2c-19c8-5d74-8f96-b4c72e072ca5","sourceKey":"bank:AMS101:AMS101-T192","parentItemId":null,"revision":1,"payload":{"prompt":"Knowledge management means encouraging organisational members to","options":["raise the education level of the average employee","create new training programmes to help newcomers learn their jobs","set up an in-house corporate university, like the one McDonald's runs","systematically collect information and share it with others"],"correctOption":3,"section":"Managers and Management","explanation":"Knowledge management builds a learning culture in which members systematically gather knowledge and share it so the organisation performs better. Options A, B and C involve training or education, which may help, but they are not the core idea of gathering and sharing knowledge."}},{"itemId":"bf2cfbef-ed72-52af-834f-75128f869922","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ec731fa0-c870-5fd3-b430-9dae35814e03","sourceKey":"bank:AMS101:AMS101-T193","parentItemId":null,"revision":1,"payload":{"prompt":"Which part of e-business covers its sales and marketing side?","options":["intranet","evolution","e-commerce","extranet"],"correctOption":2,"section":"Managers and Management","explanation":"E-commerce is the sales and marketing part of e-business, where products are bought and sold over the internet. Option A, an intranet, is an internal communication network, and option D, an extranet, links an organisation with outside partners such as suppliers."}},{"itemId":"6304f951-c5d1-5696-8edc-16e36ca61142","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85ff99a4-2589-583b-a56d-51b907ee808a","sourceKey":"bank:AMS101:AMS101-T194","parentItemId":null,"revision":1,"payload":{"prompt":"Which two people were pioneers of total quality management?","options":["Fayol; Weber","Taylor; Gilbreth","Owen; Munsterberg","Deming; Juran"],"correctOption":3,"section":"Managers and Management","explanation":"W. Edwards Deming and Joseph Juran are the best-known pioneers of total quality management. Fayol and Weber (option A) were general administrative theorists, Taylor and Gilbreth (option B) belong to scientific management, and Owen and Munsterberg (option C) were early organisational behaviour thinkers."}},{"itemId":"b4faa769-1308-5799-9bf0-5a80d4be0579","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc887d7b-fb30-540e-a880-49b992395fe1","sourceKey":"bank:AMS101:AMS101-T195","parentItemId":null,"revision":1,"payload":{"prompt":"Three key themes stand out in the definition of entrepreneurship. Which of these is NOT one of them?","options":["pursuing opportunities","innovation","the possibility of failure","growth"],"correctOption":2,"section":"Managers and Management","explanation":"The three themes in entrepreneurship are the pursuit of opportunities, innovation and growth. Failure is a real risk for new ventures, which makes option C tempting, but it is not one of the three defining themes."}},{"itemId":"c73679e2-2882-5128-aa8e-3922471e3612","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51075695-8b28-539e-bfe5-e028b77342e2","sourceKey":"bank:AMS101:AMS101-T196","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the broad term for how an organisation does its work through electronic (internet-based) links with its key constituencies so as to reach its goals efficiently and effectively.","options":["Electronic commerce","Electronic business","Virtual business","Technologically impaired"],"correctOption":1,"section":"Managers and Management","explanation":"E-business is the comprehensive term for using internet-based linkages with key groups such as customers, suppliers and employees to do the organisation's work. Option A, e-commerce, is narrower, since it covers only the sales and marketing part of e-business."}},{"itemId":"ca1781f4-69c3-5f4c-8dee-fef365cfc26a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bbf626a3-3117-54d4-9c66-e6c6c8f58909","sourceKey":"bank:AMS101:AMS101-T197","parentItemId":null,"revision":1,"payload":{"prompt":"In which category of e-business involvement does an organisation use the internet to carry out its traditional business functions better, without selling anything online?","options":["e-business enhanced organisation","e-business enabled organisation","total e-business organisation","theoretical e-business organisation"],"correctOption":1,"section":"Managers and Management","explanation":"An e-business enabled organisation uses the internet to perform its traditional functions better, for example sharing information with staff or customers, but does not sell online. Option A, e-business enhanced, describes a traditional organisation that adds e-business capabilities, usually e-commerce. Option C describes a firm whose whole existence depends on the internet."}},{"itemId":"2cee4273-1f74-5e32-a0e3-cd099f29eee2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"62327dc0-0c2b-566c-bf5b-83a90766764e","sourceKey":"bank:AMS101:AMS101-T199","parentItemId":null,"revision":1,"payload":{"prompt":"What is an internal communication system that runs on internet technology and can be used only by an organisation's employees, for example to reach staff around the world?","options":["extranet","local area network","intranet","hypernet"],"correctOption":2,"section":"Managers and Management","explanation":"An intranet is an internal network built on internet technology that only the organisation's own employees can access. Option A, an extranet, also lets approved outsiders such as suppliers and customers in. Option B, a local area network, connects computers in one location but is not defined as an internet-based company system."}},{"itemId":"667b39ba-4b7a-5c99-86fd-bc1415a9e616","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89788728-4794-5275-a37e-4eb47f1e0d67","sourceKey":"bank:AMS101:AMS101-T200","parentItemId":null,"revision":1,"payload":{"prompt":"An organisation whose whole existence depends on and revolves around the internet falls into which category of e-business involvement?","options":["e-business enhanced","e-business enabled","total e-business","theoretical e-business"],"correctOption":2,"section":"Managers and Management","explanation":"A total e-business organisation exists because of the internet and is built entirely around it, such as an online-only marketplace. Options A and B describe traditional organisations that use the internet to add to or improve what they already do."}},{"itemId":"f3df01ef-2c3b-5ec8-874f-81cecd553a35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b94a6155-b5ea-5a99-8fb1-80173e4f06a3","sourceKey":"bank:AMS101:AMS101-T201","parentItemId":null,"revision":1,"payload":{"prompt":"The second theme of entrepreneurship involves changing, revolutionising or transforming things, or introducing new products, services or ways of doing business. What is this theme?","options":["organisational structure","innovation","organisational systems","technology"],"correctOption":1,"section":"Managers and Management","explanation":"Innovation is the entrepreneurship theme about changing, revolutionising and transforming, or introducing new products, services or methods. Option D, technology, may help innovation, but it is not the name of the theme."}},{"itemId":"b2dcf708-5647-562e-bc04-5682e9168f6d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"91d3b23d-aaf4-5735-8497-359b6022c664","sourceKey":"bank:AMS101:AMS101-T203","parentItemId":null,"revision":1,"payload":{"prompt":"What general term describes the quality revolution that spread through both business and the public sector in the 1980s and 1990s?","options":["Ethno quality management","Total quality management","Hyper quality management","Partial quality management"],"correctOption":1,"section":"Managers and Management","explanation":"Total quality management (TQM) is the general term for the quality revolution of the 1980s and 1990s, built on continuous improvement and meeting customer needs. Options A, C and D are not real management terms."}},{"itemId":"1702baae-d014-597a-ad56-0844d029b707","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b043f126-7e8e-5df4-b347-a140463494c9","sourceKey":"bank:AMS101:AMS101-T206","parentItemId":null,"revision":1,"payload":{"prompt":"______ means building a learning culture where members systematically gather knowledge and share it with others so the organisation performs better.","options":["Systems management","Software management","Technical management","Knowledge management"],"correctOption":3,"section":"Managers and Management","explanation":"Knowledge management is about creating a learning culture in which people systematically collect knowledge and share it to improve performance. Options A, B and C do not describe this gathering and sharing of knowledge."}},{"itemId":"81cff890-b179-595b-a575-fe70ec9491ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f974f512-416f-5a27-b425-18d6ac7823f8","sourceKey":"bank:AMS101:AMS101-T209","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a management philosophy driven by continual improvement and by responding to what customers need and expect.","options":["Workplace religion","Workplace spirituality","Quality management","Knowledge management"],"correctOption":2,"section":"Managers and Management","explanation":"Quality management, often called TQM, is a philosophy based on continual improvement and responding to customer needs and expectations. Option D, knowledge management, is about gathering and sharing knowledge, not about customer-driven improvement. Option B concerns meaning and purpose at work."}},{"itemId":"2f1528cb-a55c-53ea-b3ce-fe4bcddca220","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5244a149-e712-503c-a3e5-dac2e3ee1614","sourceKey":"bank:AMS101:AMS101-T210","parentItemId":null,"revision":1,"payload":{"prompt":"What are the two views of how much managers affect an organisation's success or failure?","options":["omnipotent and symbolic","omnipotent and reflective","symbolic and interactive","reflective and interactive"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The two views are the omnipotent view, which says managers are directly responsible for results, and the symbolic view, which says outside forces largely decide results. Options B, C and D include terms that are not part of this debate."}},{"itemId":"00ae8f2c-49c2-5056-a768-6c6b12c329b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8857768d-022b-59bd-8659-b18a0d5f98ce","sourceKey":"bank:AMS101:AMS101-T211","parentItemId":null,"revision":1,"payload":{"prompt":"What does the omnipotent view of management say?","options":["the top manager is the only person in charge","managers are directly responsible for whether an organisation succeeds or fails","there is only one boss, who is responsible for handing out orders","managers have little or no responsibility for an organisation's success or failure"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The omnipotent view holds that managers are directly responsible for an organisation's success or failure. Option D is the opposite position, close to the symbolic view. Options A and C are about who gives orders, not about managers' impact on results."}},{"itemId":"c9e5572c-1435-5ccb-af24-12194f16b874","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d958527-5402-5915-ab55-84c58f29e874","sourceKey":"bank:AMS101:AMS101-T212","parentItemId":null,"revision":1,"payload":{"prompt":"Which view of management fits the popular image of the take-charge executive who can overcome any obstacle to achieve the organisation's objectives?","options":["omnipotent","symbolic","functional","systems"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The omnipotent view pictures managers as all-powerful, which fits the image of the take-charge executive who can overcome any obstacle. Option B, the symbolic view, sees managers as having limited influence because outside forces matter more."}},{"itemId":"4335a916-c37d-55d1-90be-558ea56c63d1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b501726-94dc-50e3-b364-e839bbf5c115","sourceKey":"bank:AMS101:AMS101-T213","parentItemId":null,"revision":1,"payload":{"prompt":"What does the symbolic view of management say?","options":["managers are directly responsible for whether an organisation succeeds or fails","shareholders are directly responsible for an organisation's success or failure","external forces are directly responsible for an organisation's success or failure","employees are directly responsible for an organisation's success or failure"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The symbolic view argues that much of an organisation's success or failure comes from external forces outside managers' control, such as the economy, competitors and government, so managers have only a limited effect on results. Option A is the opposite position, the omnipotent view. Options B and D wrongly put the responsibility on one inside group rather than on outside forces."}},{"itemId":"bb017165-5b3c-576d-99f5-6f12dab8f24f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51811074-77c8-564c-9c25-e2b62944cff6","sourceKey":"bank:AMS101:AMS101-T214","parentItemId":null,"revision":1,"payload":{"prompt":"Internal constraints that limit a manager's decision options","options":["are present in every organisation","do not exist, because managers can decide whatever they like","exist only when top management imposes them","exist only when followers refuse to do as they are told"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Every organisation has internal constraints, such as its culture, that limit what its managers can decide. Option B ignores these limits entirely, and options C and D wrongly tie them to just one cause."}},{"itemId":"3e832203-75a7-597e-b65e-e253f7d8552d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"43b4c166-ed9f-5824-bbec-26ee56239d4a","sourceKey":"bank:AMS101:AMS101-T215","parentItemId":null,"revision":1,"payload":{"prompt":"What is the dominant assumption about managers in management theory today?","options":["a balanced view of managers as both symbolic and omnipotent","that managers are symbolic","that managers are omnipotent","that both the symbolic and omnipotent views are fading"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The omnipotent view, that managers are directly responsible for organisational results, is the dominant assumption in management theory and in society. Option A describes how reality probably works, with managers neither all-powerful nor helpless, but that balance is not the dominant assumption. Option B is the minority view."}},{"itemId":"7204c170-888c-5ccc-8db2-f0ec00591d21","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8bca98f4-b695-5071-af3e-9ebb28329475","sourceKey":"bank:AMS101:AMS101-T216","parentItemId":null,"revision":1,"payload":{"prompt":"Sports coaches are often sacked when their teams lose. Which view of managerial impact helps explain this high turnover?","options":["symbolic","omnipotent","generalist","autocratic"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Under the omnipotent view, managers, here the coaches, are held directly responsible for results, so they are replaced when the team performs badly. Option A, the symbolic view, would blame outside factors instead, so it does not explain why coaches are fired."}},{"itemId":"533fadad-3dc4-5a77-902a-e712bf72ba50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98bc0a55-851a-56eb-b4f0-899eba4207c0","sourceKey":"bank:AMS101:AMS101-T217","parentItemId":null,"revision":1,"payload":{"prompt":"Under the symbolic view, managers have a(n) ______ effect on substantive organisational outcomes.","options":["substantial","moderate","limited","unlimited"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The symbolic view holds that managers have only a limited effect on substantive results, because outside forces largely determine success or failure. Options A and D fit the omnipotent view better, and option B still gives managers more influence than this view allows."}},{"itemId":"c76d2256-852d-552e-bc40-79ce66f8aad7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"666e83a3-17c5-5d1b-b19b-049389d5169d","sourceKey":"bank:AMS101:AMS101-T218","parentItemId":null,"revision":1,"payload":{"prompt":"Managers work within limits set by","options":["national and state governments","the organisation's employees","the organisation's culture and environment","the organisation's board of directors"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Managers operate within constraints from the organisation's culture (internal) and its environment (external). Options A, B and D are each only one possible origin of limits, while culture and environment together cover the full picture."}},{"itemId":"8114feea-7de4-5183-8cee-0c1b1cd76abf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"10808e58-143f-50f5-aad5-3dd4ed582b80","sourceKey":"bank:AMS101:AMS101-T219","parentItemId":null,"revision":1,"payload":{"prompt":"How might a manager widen their area of discretion?","options":["by giving employees orders","by changing and influencing the organisation's culture and environment","by voting in new government officials","by moving to a new employer and getting a new boss"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Since culture and environment are what limit managers, a manager can expand their discretion by changing and influencing them. Option A simply uses existing authority without widening it. Option D changes the setting but does not expand discretion within an organisation."}},{"itemId":"9b2d43b2-b171-5f40-9d5f-e4db3adf2977","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94c78b8c-368a-5f95-89b6-284ffea82034","sourceKey":"bank:AMS101:AMS101-T220","parentItemId":null,"revision":1,"payload":{"prompt":"______ that limit a manager's decision options are found within every organisation.","options":["Internal constraints","External constraints","Organisational external environments","Changes in the organisational environment"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Internal constraints, such as the organisation's culture, exist inside every organisation and narrow the choices managers can make. Options B and C refer to forces outside the organisation, not within it."}},{"itemId":"55d3ff37-b38d-5aca-b058-8bc2b29e0e6d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"55d9d5c7-21c7-552e-8601-eafedc901ac3","sourceKey":"bank:AMS101:AMS101-T221","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational culture is similar to which feature of an individual?","options":["skills","personality","motivation","ability"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Just as personality is a set of fairly lasting traits that shape how a person behaves, culture is a lasting set of shared values that shapes how an organisation's members behave. Options A, C and D describe what a person can do or wants to do, not their overall character."}},{"itemId":"195fb259-235f-5276-affd-8634dff92e10","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90876a82-cb24-5b5f-b4a8-402c50cbb5e5","sourceKey":"bank:AMS101:AMS101-T222","parentItemId":null,"revision":1,"payload":{"prompt":"An organisation's culture is","options":["presented at meetings by the organisation's top manager","a shared perception held by interest groups that watch the organisation","a shared perception held by the organisation's members","changed whenever new owners buy the organisation"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Culture is a perception held in common by the organisation's own members about how things are done. Option B is wrong because outsiders do not hold the culture, and option D is wrong because culture is lasting and does not automatically change with ownership."}},{"itemId":"d29ca0f6-3cc1-5080-a0fc-cfad21489f78","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2d5db5b-3023-52c6-908a-4a517744cb6b","sourceKey":"bank:AMS101:AMS101-T223","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational culture is about how members perceive the organisation, not about whether they","options":["like it","like their colleagues","like their boss","like their customers"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Culture is a descriptive term: it describes how members see the organisation, not whether they like it, which would be job satisfaction. Options B, C and D are narrower forms of liking, but the main contrast is with liking the organisation itself."}},{"itemId":"7aee0ece-e541-504d-9e1c-06ea5b2540f1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"138af32c-230a-5cfa-a922-0997224838f1","sourceKey":"bank:AMS101:AMS101-T224","parentItemId":null,"revision":1,"payload":{"prompt":"Strong cultures","options":["are found in organisations with strong leaders","have little influence on employees when they make decisions","exist in every organisation","influence employees more than weak cultures do"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Strong cultures are those in which key values are deeply held and widely shared, so they shape employees' behaviour more than weak cultures do. Option B is the opposite, and option C is wrong because not every organisation has a strong culture."}},{"itemId":"5acdf768-f457-501a-b045-97a33b343540","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dbc3ee93-8a63-57df-84b8-91b68fa68638","sourceKey":"bank:AMS101:AMS101-T225","parentItemId":null,"revision":1,"payload":{"prompt":"Employees in organisations with strong cultures","options":["are more committed to the organisation","are more likely to leave than to stay","are more willing to act illegally","are more likely to follow instructions from colleagues"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"When values are deeply held and widely shared, employees feel more committed to the organisation. Option B is the reverse, since strong cultures tend to keep people. Options C and D are not general effects of a strong culture."}},{"itemId":"a929aa90-9d29-5650-a5b2-13950e0355e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84cba443-0c1f-5c80-ac06-8f537d9ef32b","sourceKey":"bank:AMS101:AMS101-T226","parentItemId":null,"revision":1,"payload":{"prompt":"Which phrase is part of the definition of organisational culture?","options":["individual response","shared meaning","diversity of thought","explicit directions"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Organisational culture is a system of shared meaning, the common values and beliefs that shape how members act. Option A is individual rather than shared, and option D is wrong because culture is largely unwritten rather than explicit."}},{"itemId":"056d8025-9ae4-54e5-8057-7267f8dcb1df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f419cbc9-b41c-55b3-a038-ca6fbfe3bd65","sourceKey":"bank:AMS101:AMS101-T227","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a dimension of organisational culture?","options":["attention to detail","people orientation","compensation","aggressiveness"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The dimensions of culture include innovation and risk taking, attention to detail, outcome orientation, people orientation, team orientation, aggressiveness and stability. Compensation, or pay, is not one of them, so C is correct while A, B and D are all dimensions."}},{"itemId":"5b223d4f-43ee-58cf-a742-9101b4e9dfeb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8e1ec77c-6676-526c-aa3d-611fa49496c9","sourceKey":"bank:AMS101:AMS101-T229","parentItemId":null,"revision":1,"payload":{"prompt":"Corporate ______ are repeated sequences of activities that express and reinforce the organisation's values, which goals matter most, and which people are important or expendable.","options":["languages","rituals","symbols","ceremonies"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Rituals are repeated sequences of activities, such as yearly award events, that reinforce key values and show what and who matters. Option C, symbols, are objects like office size or dress, and option A is the special jargon members use. Option D is close, but the term used for these repeated sequences is rituals."}},{"itemId":"6c74d6b6-66c1-5afd-89ca-f2a774590da8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c6ed60ed-1d0f-5f7b-a2c1-875cc58906e3","sourceKey":"bank:AMS101:AMS101-T230","parentItemId":null,"revision":1,"payload":{"prompt":"What are the most important ways culture is passed on to employees?","options":["rituals, tales of woe, symbols and language","symbols, rituals, language and systems","stories, rituals, symbols and language","language, stories, rituals and rewards"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Culture is mainly transmitted through stories, rituals, material symbols and language. Each of the other options swaps one item for something that is not one of the four: tales of woe in A, systems in B and rewards in D."}},{"itemId":"25110464-2215-5f31-9422-1f46171c3e9a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f96e8d6f-b237-54a0-ad05-2033ac409843","sourceKey":"bank:AMS101:AMS101-T231","parentItemId":null,"revision":1,"payload":{"prompt":"When employees at a large software company use in-house phrases such as \"work judo\", \"eating your own dog food\" and \"flat food\", they are using organisational","options":["languages","rituals","symbols","ceremonies"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Special terms and jargon that only insiders understand are part of an organisation's language, which helps members identify with the culture. Option B, rituals, are repeated activities, and option C, symbols, are physical objects or signs, so neither fits spoken expressions."}},{"itemId":"e61711a9-244c-524e-94f1-57331b5e9cf5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6c9926a5-9039-5b61-b6c2-ee4c7c6701af","sourceKey":"bank:AMS101:AMS101-T232","parentItemId":null,"revision":1,"payload":{"prompt":"Most organisations have ______ cultures.","options":["very weak","weak to moderate","moderate","moderate to strong"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Most organisations have moderate to strong cultures, meaning there is fairly high agreement on what is important and what good behaviour looks like. Options A and B suggest little agreement, which is less common."}},{"itemId":"730dad55-642c-59d9-b678-fe2352a42be6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a82fe8fb-67f0-5a37-982f-9d077d3f54f9","sourceKey":"bank:AMS101:AMS101-T233","parentItemId":null,"revision":1,"payload":{"prompt":"Where does an organisation's culture usually come from in the first place?","options":["it is shared among the first workers the organisation hires","the board of directors formulates it when the organisation is set up","it identifies what the organisation does successfully","it reflects the vision or mission of the organisation's founder"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An organisation's culture usually begins with the vision or mission of its founder, who shapes the early values and ways of doing things. Option A is tempting, but the first workers adopt the founder's values rather than creating the culture themselves. Option B is wrong because culture is not formally written by a board."}},{"itemId":"1b06dd9e-3881-5813-99e2-e5c0bd170888","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b43487b-1694-5990-b3d5-6852b741f151","sourceKey":"bank:AMS101:AMS101-T234","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational ______ usually tell(s) of significant events or people.","options":["stories","rituals","charts","material symbols"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stories are narratives about significant events or people, such as the founders or key breakthroughs, that pass on the culture. Option B, rituals, are repeated activities, and option D, material symbols, are physical things such as office layout or dress."}},{"itemId":"eecd126d-820b-52f1-bfb6-33a7ef65daab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e157875-cf60-5d86-b782-4d68c6944f00","sourceKey":"bank:AMS101:AMS101-T235","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT an example of a material symbol?","options":["how people dress","office size","employee stock options","reserved parking spaces for certain staff"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Material symbols are visible physical signs that show who is important and what kind of behaviour is expected, such as dress, office size and reserved parking. Stock options are a form of pay, not a visible physical symbol, so C is the exception."}},{"itemId":"169d403c-cf88-5ae7-b63b-5a761571a6ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b92a5be3-4d9b-5724-bd88-3342ab9e2198","sourceKey":"bank:AMS101:AMS101-T236","parentItemId":null,"revision":1,"payload":{"prompt":"The link between organisational values and how managers behave is","options":["uncertain","fairly straightforward","loose and hard to see","unimportant"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Culture shapes what managers see as appropriate, so the connection between an organisation's values and its managers' behaviour is fairly straightforward. Options A and C suggest a weak link, and option D wrongly dismisses it."}},{"itemId":"736eb5b1-2143-56e8-a547-10d72c3f3330","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b05ebf30-f95d-5501-89bf-7c4f95edd65d","sourceKey":"bank:AMS101:AMS101-T237","parentItemId":null,"revision":1,"payload":{"prompt":"When members learn an organisation's language, they","options":["can communicate with the organisation's shareholders","know the boss will promote them to greater responsibility","show that they accept the culture and are willing to help keep it alive","can share material symbols with other members"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Learning and using the organisation's special language shows that members accept the culture and are willing to help preserve it. Option D mixes up language with material symbols, which are a different way culture is transmitted. Option B is not a guaranteed result."}},{"itemId":"03468d39-41c5-5ae8-9e99-ad02b49d08a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6e2dd642-4e30-5544-9f7b-3da70cd69dce","sourceKey":"bank:AMS101:AMS101-T239","parentItemId":null,"revision":1,"payload":{"prompt":"What does the term \"external environment\" mean?","options":["institutions outside the organisation that affect its performance","forces and institutions outside the organisation that could potentially affect its performance","forces and institutions inside the organisation that affect its performance","forces inside the organisation that affect its performance"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The external environment is made up of forces and institutions outside the organisation that can potentially affect how it performs. Option A is incomplete because it leaves out forces such as economic conditions, and it says they definitely affect performance rather than potentially. Options C and D wrongly place the environment inside the organisation."}},{"itemId":"1360c050-cf8b-5f74-b2c1-af4dbedfd85a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f1a84e3-2496-5bbd-b867-6bf4b8a9a17c","sourceKey":"bank:AMS101:AMS101-T240","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ environment consists of the constituencies that have a direct and immediate impact on managers' decisions and actions and that are directly relevant to reaching the organisation's goals.","options":["general","specific","secondary","forward"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The specific environment includes groups like customers, suppliers, competitors and pressure groups that directly and immediately affect managers' decisions. Option A, the general environment, covers broad conditions such as economic, political and sociocultural factors that may affect the organisation but less directly."}},{"itemId":"86bf704e-6ada-5f7a-96d1-d6f5be1c143b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"09f41a6b-a231-5d09-b8e5-ca1c7445743f","sourceKey":"bank:AMS101:AMS101-T241","parentItemId":null,"revision":1,"payload":{"prompt":"An organisation's specific environment","options":["is unique to it and changes as conditions change","stays the same however old the organisation is","is decided by top management","must be measured to prove that it exists"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Each organisation's specific environment is unique and shifts as conditions change, for example when new competitors or customers appear. Option B is wrong because the environment does not stay fixed, and option C is wrong because managers do not simply choose their environment."}},{"itemId":"aeb57307-5bc1-5d41-8ce3-8c33907b7528","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14e2f04d-b229-54ba-8269-d7be049bb983","sourceKey":"bank:AMS101:AMS101-T242","parentItemId":null,"revision":1,"payload":{"prompt":"The specific environment is made up of constituencies that directly affect managers' decisions and actions. Its main constituencies are customers, suppliers, competitors and","options":["lawmakers","pressure groups","employees","lawyers"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The main parts of the specific environment are customers, suppliers, competitors and pressure groups, which are special-interest groups that try to influence the organisation. Option A, lawmakers, is linked with the political and legal conditions of the general environment. Option C, employees, are inside the organisation, not part of its external environment."}},{"itemId":"8fbbf783-1f83-5195-947f-ca1113b8f6b8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8117801-e38a-5d80-91a2-c075505adeed","sourceKey":"bank:AMS101:AMS101-T243","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a constituency within the specific environment?","options":["customers","sociocultural factors","suppliers","competitors"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Sociocultural factors, such as society's values and attitudes, belong to the general environment, not the specific environment. Customers, suppliers and competitors (options A, C and D) are all part of the specific environment."}},{"itemId":"64e06855-9e68-5848-ac93-77b978723dcb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b5e9b75-501d-5687-bd28-8f4597b305e2","sourceKey":"bank:AMS101:AMS101-T244","parentItemId":null,"revision":1,"payload":{"prompt":"When people talk about an organisation's suppliers, they usually mean","options":["the organisation's main customers","the governments that pass the laws the organisation must obey","businesses located close to the buying organisation","organisations that provide materials and equipment"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Suppliers are usually thought of as organisations that provide materials and equipment, although the idea also covers providers of money and labour. Option A confuses suppliers with customers, and option C is wrong because suppliers can be located anywhere."}},{"itemId":"7c46d14b-048a-57a4-8e18-0c2ee2906b50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9f41e06c-4583-5e68-9e65-8c3238dcfbc5","sourceKey":"bank:AMS101:AMS101-T245","parentItemId":null,"revision":1,"payload":{"prompt":"Managers try to make sure there is a steady","options":["flow of cash from shareholders into the organisation","flow of the inputs it needs at the lowest available price","flow of customers into the company's outlet shop","stream of suppliers to keep competition among them as high as possible"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Managers work to secure a steady flow of needed inputs, such as materials, money and labour, at the lowest price available. Option A is too narrow, since shareholders are only one provider of funds. Option D misstates the goal, because the aim is reliable inputs, not maximum competition among suppliers."}},{"itemId":"3df91e77-4384-5124-b653-c477281a11fa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9b25cbc-9f16-588d-ba1a-eff80354d847","sourceKey":"bank:AMS101:AMS101-T247","parentItemId":null,"revision":1,"payload":{"prompt":"For a large theme park company, a bank that lends it money is which kind of factor in its specific environment?","options":["competitor","supplier","special-interest group","government agency"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Suppliers include not only firms that provide materials but also those that provide financial inputs, so a bank lending money is a supplier of capital. Option C, a special-interest group, tries to influence the organisation's actions rather than supplying it with inputs."}},{"itemId":"6039dcaf-4e49-59b1-af62-033b4175d78b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c21829e-8db9-525a-9eb8-49b45c5aece3","sourceKey":"bank:AMS101:AMS101-T249","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital depends on a steady supply of nurses. In its specific environment, how would the nurses' labour union and the local labour market both be classified?","options":["One is a special-interest group and the other is a supplier","One is a customer and the other is a special-interest group","Both of them are suppliers","One is a government agency and the other is a competitor"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Suppliers are not only firms that sell raw materials; anyone who provides an organization with inputs, including people, counts. The labour union and the local labour market both supply the hospital with nurses, so both are suppliers. Option A is tempting because unions can lobby, but here their role is providing labour, not pressuring the hospital as an outside interest group."}},{"itemId":"f26e73f0-1e9a-5e40-a465-ef2bdb8f4752","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6cabd76a-d30e-5d1a-b1fa-d2eaffe37b25","sourceKey":"bank:AMS101:AMS101-T250","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is usually treated as part of an organization's specific environment?","options":["Economic factors","Political conditions","Technological factors","Competitors"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The specific environment is made up of the outside groups that directly affect a firm's goals day to day: customers, suppliers, competitors and pressure groups. Competitors therefore belong here. Options A, B and C are broad conditions that affect all firms indirectly, so they belong to the general environment instead."}},{"itemId":"22261e8f-aa29-5f1e-b87b-077b8b4df859","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e99b21ae-c839-569a-8064-4c899556d6a9","sourceKey":"bank:AMS101:AMS101-T251","parentItemId":null,"revision":1,"payload":{"prompt":"A private courier company delivers parcels and letters nationwide. In the specific environment of the national postal service, what is this courier company?","options":["A competitor","A supplier","A customer","A government agency"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A competitor is any organization that goes after the same customers with a similar or substitute service. A private courier and a postal service are both trying to win people who want items delivered, so the courier is a competitor. It does not provide inputs to the postal service (Option B) or buy from it (Option C)."}},{"itemId":"d29f1033-c6d5-5d5a-b31f-3f0e7a2cfbc8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b7fbe1b-f839-51c6-b61c-7015ddf94385","sourceKey":"bank:AMS101:AMS101-T252","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the general economic conditions facing an organization?","options":["A new law recently passed by the national legislature","Interest rates","Changes in people's disposable income","Movements in the stock market"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Economic conditions cover things like interest rates, inflation, disposable income and stock market movements, which affect how much people and firms can spend and borrow. A newly passed law is a political/legal condition, not an economic one, so Option A is the exception. Options B, C and D are all standard economic factors."}},{"itemId":"a7d78187-8e59-5928-9c5c-32baf72ab489","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"41fac8bf-df2b-5e17-8c66-c6de0d081fb7","sourceKey":"bank:AMS101:AMS101-T253","parentItemId":null,"revision":1,"payload":{"prompt":"What do sociocultural conditions in an organization's environment refer to?","options":["The demographic make-up of the organization's suppliers","Legal matters settled by court rulings","Unemployment levels and workers' real incomes","The shifting expectations and values of the society the organization operates in"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Sociocultural conditions are about society itself: its values, attitudes, customs, tastes and what people expect from businesses. As these expectations change, managers must adapt. Option B is a legal condition and Option C describes economic conditions, so neither fits."}},{"itemId":"417cd91b-021c-5944-b731-1ef316485937","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e05bb6a-87fe-5b39-9004-188e90e8f695","sourceKey":"bank:AMS101:AMS101-T254","parentItemId":null,"revision":1,"payload":{"prompt":"A national television network earns money when people watch its broadcasts. To that network, a home video recorder that lets viewers watch recorded films instead of live programmes is best seen as a:","options":["Customer","Supplier","Special-interest group","Competitor"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Competitors include not just rival firms but anything that offers customers a substitute way of meeting the same need. A home video recorder pulls viewers' time away from the network's programmes, so it competes for the same audience. It does not buy from the network (Option A) or provide it with inputs (Option B)."}},{"itemId":"44e2f23c-bdbf-5af7-8762-39f7117faa88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4928264b-c228-54d0-b86c-2979da00fe02","sourceKey":"bank:AMS101:AMS101-T255","parentItemId":null,"revision":1,"payload":{"prompt":"Which development has changed who an organization's competitors are by practically removing geographic boundaries?","options":["Local area networks","The intranet","The Internet","Video conferencing"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The Internet lets a business sell to and compete for customers almost anywhere in the world, so a firm's rivals can now be in any country. That is why it has removed geographic limits on competition. Option B, an intranet, is a private network used inside one organization, so it does not open up new markets or rivals."}},{"itemId":"7300975a-da5a-5651-ace2-49497747f743","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94d9f708-9ed2-56c3-8137-2d3c105124c8","sourceKey":"bank:AMS101:AMS101-T256","parentItemId":null,"revision":1,"payload":{"prompt":"A consumer advocacy organization campaigns publicly for tougher product-safety laws and challenges companies over unsafe goods. In a firm's specific environment, this organization is an example of a:","options":["Competitor","Pressure group","Customer","Government agency"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Pressure groups (special-interest groups) are outside groups that try to influence how organizations behave, often through campaigns, publicity or lobbying. A consumer advocacy body pushing for safer products fits this exactly. It does not make laws itself, so it is not a government agency (Option D)."}},{"itemId":"efb6cc4b-4a79-55fd-8aca-cfa429524006","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ee2b883-ec6d-5f4a-9ca8-82e167f8c4bb","sourceKey":"bank:AMS101:AMS101-T257","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these normally forms part of an organization's general environment?","options":["Political conditions","Matters directly linked to achieving the organization's goals","Stakeholders","Suppliers"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The general environment covers broad outside conditions such as economic, political/legal, sociocultural, demographic, technological and global factors. Political conditions are one of these. Options B and D describe the specific environment, which is made up of issues and groups that directly affect a firm's goals."}},{"itemId":"9b277079-270c-5b26-bace-911b9475fdb1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"24ca0b4d-482e-54f9-b14e-8d5c83bc7fd8","sourceKey":"bank:AMS101:AMS101-T258","parentItemId":null,"revision":1,"payload":{"prompt":"How does the general environment of an organization compare with its specific environment?","options":["It has a smaller effect on the organization's operations","It has a bigger effect on the organization's operations","It has roughly the same effect on the organization's operations","It is a matter only for top management"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"General environment factors such as the economy or politics can affect a firm, but their effect is usually indirect and less immediate. The specific environment, with its customers, suppliers and competitors, has a more direct impact on daily operations. Option B reverses this, and Option D is wrong because managers at different levels can be affected by the environment."}},{"itemId":"9f6f5d33-b4d2-5e58-9073-5c838c8ac80c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf19c111-ae6b-5d46-807f-f3a62cea35f6","sourceKey":"bank:AMS101:AMS101-T259","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of something in an organization's general environment?","options":["Economic conditions","Political conditions","Social conditions","Industry conditions"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Economic, political and social conditions are broad forces that affect all organizations, so they belong to the general environment. Industry conditions, such as the competitors and suppliers in a particular industry, are part of the specific environment because they affect the firm directly. That makes Option D the exception."}},{"itemId":"34360847-f119-58ec-9a20-f143098a1b23","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c4fab60-7944-5686-a881-4bdba2845cff","sourceKey":"bank:AMS101:AMS101-T260","parentItemId":null,"revision":1,"payload":{"prompt":"Interest rates, inflation and stock market indexes are examples of which general environment factor?","options":["Economic","Political","Social","Technological"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Interest rates, inflation and stock market performance all describe the state of the economy and affect how much money firms and consumers have to borrow, save and spend. They are therefore economic factors. Option B would cover things like laws and government stability, which these are not."}},{"itemId":"3b13c86f-cf7a-5633-b4aa-874742db6590","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3bf99831-2e64-53fb-9d5b-7a2272191594","sourceKey":"bank:AMS101:AMS101-T261","parentItemId":null,"revision":1,"payload":{"prompt":"A country passes a law requiring employers to make reasonable accommodations for workers with disabilities. This law is an example of a:","options":["Sociolegal condition","Political/legal condition","Political/sociological condition","Sociocultural condition"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Laws and government regulations that shape what organizations may or must do fall under political/legal conditions. A disability-rights law sets legal duties for employers, so it fits here. Option D is tempting because the law reflects social values, but sociocultural conditions refer to society's values and expectations themselves, not to laws passed by government."}},{"itemId":"caed66d2-9bd7-5b0d-bb15-d659f5a62eb9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"32fd8083-4da9-5061-a4a9-69bb78835335","sourceKey":"bank:AMS101:AMS101-T262","parentItemId":null,"revision":1,"payload":{"prompt":"A charity notices that donations from the public have fallen sharply. Which general environment factor is most likely behind this drop?","options":["Political","Social","Technological","Economic"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"How much people give to charity depends largely on how much money they have to spare. When incomes fall or times are hard, donations usually drop, which is an economic effect. Option B is less likely because a fall in giving here reflects people's ability to give rather than a change in social values."}},{"itemId":"22bd1ca6-c9d3-5a5c-a69b-7beb6bc698e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"02746531-f4c8-5fc1-875b-89657f7a48b5","sourceKey":"bank:AMS101:AMS101-T263","parentItemId":null,"revision":1,"payload":{"prompt":"Which group is made up of people born between 1946 and 1964?","options":["The Depression group","The World War II group","The baby boomers","Generation X"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The baby boomers are the large generation born after the Second World War, roughly from 1946 to 1964. The Depression and World War II groups (Options A and B) were born earlier. Generation X (Option D) came after the boomers."}},{"itemId":"906488e0-9241-59f9-b76a-d2239f89a485","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d31f43d6-d0eb-5f1a-af84-4499d1494f9d","sourceKey":"bank:AMS101:AMS101-T264","parentItemId":null,"revision":1,"payload":{"prompt":"Members of which group are said to be thinking, learning, creating, shopping and playing in fundamentally new ways that will strongly affect organizations and managers?","options":["The Depression group","The World War II group","The baby boomers","Generation Y"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Generation Y grew up with computers, the Internet and digital technology, which has shaped how they learn, work, shop and relax. As they enter the workforce and become key customers, organizations must adapt to them. The older groups in Options A, B and C did not grow up with this technology, so they are not the group described."}},{"itemId":"9e2f9219-e88a-56f1-a007-bb2e6f0d4a2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1fd1a399-fce7-5884-9862-0ff47576dcec","sourceKey":"bank:AMS101:AMS101-T266","parentItemId":null,"revision":1,"payload":{"prompt":"Over the past twenty-five years or so, which part of an organization's general environment has changed the fastest?","options":["Global","Economic","Social","Technological"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Technology has changed faster than any other general environment factor, with computers, the Internet, mobile phones and automation transforming how organizations work. Global, economic and social conditions (Options A, B and C) have also changed, but not at the same speed."}},{"itemId":"452fbf3c-7b38-5ab4-aa4e-c7ab34be1c20","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"28a9097f-0230-5cd6-8d0b-82796d40fceb","sourceKey":"bank:AMS101:AMS101-T267","parentItemId":null,"revision":1,"payload":{"prompt":"An integrated office system helps managers make decisions faster and better. This is an example of the influence of which general environment factor?","options":["Global","Social","Political","Technological"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An integrated office system is a technological tool, so the improvement in decision speed and quality comes from technology. Technological conditions cover new tools, machines and information systems that change how work is done. Options A, B and C have nothing to do with office systems."}},{"itemId":"f2b3202b-3f68-56ac-ae5b-e09b393f61ef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"59166a79-8fe9-5b6f-ad19-4d27432ed269","sourceKey":"bank:AMS101:AMS101-T268","parentItemId":null,"revision":1,"payload":{"prompt":"What are the two dimensions used to describe environmental uncertainty?","options":["Degree of change and degree of complexity","Degree of change and degree of volume","Degree of complexity and degree of impact","Degree of impact and degree of timing"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Environmental uncertainty is measured along two dimensions: how much and how fast the environment changes (degree of change) and how many components it has and how well the firm understands them (degree of complexity). Options B, C and D each include a dimension, such as volume, impact or timing, that is not part of this model."}},{"itemId":"32ddaa23-a15a-5d1d-95bc-8eeee2d4cda0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"82c196e6-9613-54ee-81eb-0861a0a6eacd","sourceKey":"bank:AMS101:AMS101-T269","parentItemId":null,"revision":1,"payload":{"prompt":"When the parts of an organization's environment change often, the environment is described as:","options":["Moving","Diverse","Dynamic","Difficult"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A dynamic environment is one whose components change frequently, while a stable environment changes very little. 'Dynamic' is the term used for degree of change. Option B, diverse, relates more to how many components there are, which is about complexity, not change."}},{"itemId":"5199b31b-0568-55e3-8d07-3b2d5eafa1d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4715a690-36b1-5f70-ae1f-17d1ccb6f4ba","sourceKey":"bank:AMS101:AMS101-T270","parentItemId":null,"revision":1,"payload":{"prompt":"Managers try to keep __________ as low as possible because it threatens how effective an organization is.","options":["Product development","Uncertainty","Price changes","The number of suppliers"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Uncertainty makes it hard for managers to predict what will happen, which makes planning and decision making less effective. That is why managers try to reduce it, for example by gathering information. Option A, product development, is something firms usually want, not something they try to minimize."}},{"itemId":"7f62594b-fe5f-5e7e-93e4-f28d1ec07459","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d790acc-b773-5dfc-8a6e-85caa8520452","sourceKey":"bank:AMS101:AMS101-T271","parentItemId":null,"revision":1,"payload":{"prompt":"What term describes any group in an organization's environment that is affected by the organization's decisions and actions?","options":["Stockholders","Pressure groups","Suppliers","Stakeholders"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stakeholders are all the groups affected by what an organization does, such as employees, customers, suppliers, communities and government. Option A, stockholders, are only one type of stakeholder, and Option B, pressure groups, are just one other type, so neither covers the full definition."}},{"itemId":"f1125271-0bd2-5683-9b31-17437c3110a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"027a1d56-1969-50c7-b2e3-a6b9e442e54a","sourceKey":"bank:AMS101:AMS101-T272","parentItemId":null,"revision":1,"payload":{"prompt":"Which term refers to how many components are in an organization's environment and how much the organization knows about them?","options":["Degree of stability","Openness","Degree of complexity","Change"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Degree of complexity looks at the number of components in the environment and the extent of the organization's knowledge about them. Few components that are well understood means low complexity. Options A and D relate to the other dimension, degree of change, which is about how often things shift."}},{"itemId":"295fc776-6980-559d-971c-3ca9f73bd6a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d17488e-1188-5a05-86fb-34e236be9591","sourceKey":"bank:AMS101:AMS101-T273","parentItemId":null,"revision":1,"payload":{"prompt":"When managing relationships with external stakeholders, managers first identify who the stakeholders are. What should they do next?","options":["Decide which specific approach to use in managing each relationship","Work out what the courts might decide if a stakeholder sues the organization","Find out what particular interests or concerns these stakeholders may have","Count how many stakeholders belong to each stakeholder group"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"After identifying stakeholders, managers need to understand what each group cares about, since this shapes how the relationship should be handled. Only then can they judge how important each group is and choose an approach. Option A is a later step, which is why it may look right but comes too early here."}},{"itemId":"7b9c9ac0-96ae-55b5-b7ec-fbdf8a63d3bc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c1d2124-af4b-5ba8-a6b0-7f0fc042cfe0","sourceKey":"bank:AMS101:AMS101-T274","parentItemId":null,"revision":1,"payload":{"prompt":"As part of a culture change, a manager is asked to promote the belief that managers are directly responsible for whether the organization succeeds or fails, rather than forces beyond their control. This fits a culture that holds which view of management?","options":["Traditional","Omnipotent","Standard","Symbolic"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The omnipotent view says managers are directly responsible for an organization's success or failure. It is the belief that good managers can overcome obstacles. Option D, the symbolic view, is the opposite: it says outside forces largely decide results and managers have limited influence."}},{"itemId":"93e550f1-00e5-58b8-8cf6-4c0e187c6d9b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e5eba43-0af5-5c54-b5af-c29293f38b92","sourceKey":"bank:AMS101:AMS101-T275","parentItemId":null,"revision":1,"payload":{"prompt":"A company wants to adopt a new view of management, but this will be hard because staff have long believed that results are mostly beyond management's control. What is this older belief called?","options":["Traditional","Omnipotent","Standard","Symbolic"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The symbolic view holds that much of an organization's success or failure is caused by outside forces that managers cannot control. Managers mainly influence results by creating meaning and symbols. Option B, the omnipotent view, is the opposite belief that managers are directly responsible for outcomes."}},{"itemId":"bedd47bf-6081-5fac-b423-81d477ab500b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78c566d7-f9b2-5029-a752-22d6b1c90b6e","sourceKey":"bank:AMS101:AMS101-T276","parentItemId":null,"revision":1,"payload":{"prompt":"Members of an organization act on a set of shared values, beliefs and perceptions about how things should be done there. What is this shared perception called?","options":["The omnipotent view of management","Organizational culture","An internal constraint","An external constraint"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Organizational culture is the shared values, principles, traditions and ways of doing things that influence how members behave. When people act on a common perception within the organization, they are acting on its culture. Option A is a view about how much control managers have, not a shared perception among members."}},{"itemId":"3bfc75cd-74b7-5ce8-912e-5ef2351dd46b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a5d83ee8-ce91-5278-8cd5-e95e1a21c4bd","sourceKey":"bank:AMS101:AMS101-T277","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing manager wants to launch a new medical product, but her own marketing staff resist the idea. For this manager, the staff's resistance is best described as:","options":["The omnipotent view of management","Organizational culture","An external constraint","An internal constraint"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Constraints are forces that limit what managers can do. Resistance from the manager's own staff comes from inside the organization, so it is an internal constraint. Option C would apply if the limit came from outside, such as from customers, competitors or government."}},{"itemId":"75efacdc-b221-5b55-8f48-585cd0c7a390","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eda1bd55-d81f-5f91-bb3c-8cf237d861a0","sourceKey":"bank:AMS101:AMS101-T278","parentItemId":null,"revision":1,"payload":{"prompt":"Suppose the marketing and research and development departments of a company held the same values and views about a new product. This would suggest that the organization probably has a:","options":["Strong culture","Weak culture","Specific internal environment","Specific internal constraint"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A strong culture is one where key values are deeply held and widely shared across the organization. If different departments agree in their values and views, that wide sharing points to a strong culture. Option B, a weak culture, is one where values are not widely shared, which would show up as disagreement between departments."}},{"itemId":"3841fcaf-1df8-5a66-a75a-90613257b612","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d35c0adb-a482-51ab-95ba-32b1d7f75129","sourceKey":"bank:AMS101:AMS101-T279","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is true of a global marketplace?","options":["The whole world becomes a marketplace","National borders become increasingly irrelevant","Organizations' opportunities to grow increase greatly","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In a global marketplace, firms can sell almost anywhere, so the whole world becomes the market, borders matter much less, and the chance to grow expands a lot. Since A, B and C are all true, D is the best answer."}},{"itemId":"e48abe13-a671-5513-8563-51cc6682f7d3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"63c912dd-ff16-5003-8945-c77396912880","sourceKey":"bank:AMS101:AMS101-T280","parentItemId":null,"revision":1,"payload":{"prompt":"In a global marketplace, what must managers do?","options":["Handle economic, political and cultural differences","Be ready for competitors to appear suddenly from anywhere at any time","Ignore the particular differences of each local environment","Both A and B"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Managers in a global market must deal with economic, political and cultural differences between countries, and they must expect new competitors to appear from anywhere. So A and B are both correct. Option C is wrong because successful global managers pay close attention to local differences rather than ignoring them."}},{"itemId":"836fa9d0-82ca-57b3-ac8d-698d566e872d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"711d0787-1460-52ab-9116-0fe722464bd0","sourceKey":"bank:AMS101:AMS101-T283","parentItemId":null,"revision":1,"payload":{"prompt":"An ethnocentric view focuses mainly on the:","options":["Home country","Host country","World as a whole","Racial background of people"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An ethnocentric attitude is the belief that the best work approaches and practices are those of the home country, the country where the company is based. Option B describes the polycentric view, which trusts the host country's ways, and Option C describes the geocentric, world-oriented view."}},{"itemId":"bcc48319-a2ff-51a4-9e20-cb6343983a05","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"99e3413a-a0a1-591f-83a9-99b7a76fcd8b","sourceKey":"bank:AMS101:AMS101-T284","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a typical sign that managers from a particular country suffer from parochialism?","options":["Multinationalism","Monolingualism","Geocentrism","Polycentrism"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Parochialism means seeing the world only through your own eyes and perspective. Speaking only one language (monolingualism) is a common sign of this, because it limits a person's understanding of other cultures. Options C and D are attitudes that actually value other countries' ways, which is the opposite of parochialism."}},{"itemId":"ffa22a5e-4666-515e-a9ae-28a1b8ad5a7a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e180d3e2-9ccb-50cf-b5e7-169db84f3386","sourceKey":"bank:AMS101:AMS101-T285","parentItemId":null,"revision":1,"payload":{"prompt":"What does parochialism mean?","options":["Accepting a variety of viewpoints","Wanting to leave your own culture for a foreign one","Tending to see the world from only one perspective","Recognizing a variety of religious beliefs"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Parochialism is a narrow view of the world in which people see things only through their own perspective and fail to recognize that others may live and work differently. Option A is the opposite of parochialism, since it means being open to different points of view."}},{"itemId":"ac78883b-bb5c-5a18-b551-ffa3246ef9ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1dae95a-d13f-557b-a535-7d6be59bf6c5","sourceKey":"bank:AMS101:AMS101-T286","parentItemId":null,"revision":1,"payload":{"prompt":"Which advice would best help a company succeed in global management?","options":["Keep insisting that only English be used","Stick strictly to your own customs so as to avoid embarrassment","Make sure foreign business partners know where you are from so they will speak English to you","Build an understanding of cultural differences"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Successful global managers need to understand and respect the different cultures they work in, since customs, values and ways of doing business vary across countries. Options A, B and C all show parochialism, expecting others to adjust to you, which can damage relationships abroad."}},{"itemId":"0549eb28-dc51-5df4-a325-215139b35b5c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c91a438e-1c11-56d3-b16c-667db0612d4d","sourceKey":"bank:AMS101:AMS101-T287","parentItemId":null,"revision":1,"payload":{"prompt":"Which attitude is the least helpful for a manager who wants to succeed in international business?","options":["Multicultural","Multicountry","Ethnocentric","Polycentric"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An ethnocentric manager believes the home country's ways are best and that foreigners lack the skills and knowledge to make good decisions. This attitude makes it hard to work well with people in other countries. Option D, polycentric, may not be ideal either, but it at least respects host-country practices, so ethnocentric is the least favourable."}},{"itemId":"7b24ed60-21ef-5ab6-a8a8-44e4b5f395ac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8da7937a-d497-5349-8bdd-d64e90f5b07e","sourceKey":"bank:AMS101:AMS101-T289","parentItemId":null,"revision":1,"payload":{"prompt":"Which attitude best describes what is needed for successful global management?","options":["Ethnocentric","Parochial","Polycentric","Geocentric"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A geocentric attitude is world-oriented: it looks for the best approaches and the best people from anywhere in the world, regardless of country. This is the attitude successful global management needs. Option C, polycentric, respects host countries but tends to treat each one separately, which falls short of a truly global view."}},{"itemId":"c74f8d07-07d0-50f9-bfc8-155e574b28ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0cb448a-8d32-585a-b243-2dd19eec5b75","sourceKey":"bank:AMS101:AMS101-T290","parentItemId":null,"revision":1,"payload":{"prompt":"Parochialism is a feature of which attitude?","options":["Geocentric","Nonlinguistic","Selfless","Ethnocentric"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An ethnocentric attitude assumes the home country's ways are best, which is a narrow, single-perspective way of seeing the world. That narrowness is exactly what parochialism means. Option A, geocentric, is the opposite because it takes a world view and draws on the best ideas from everywhere."}},{"itemId":"b827fc2b-2f8e-556b-99ac-9d17bfcd1a66","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4732b0f-364a-5e5d-ba9b-df3a590faaf8","sourceKey":"bank:AMS101:AMS101-T291","parentItemId":null,"revision":1,"payload":{"prompt":"Which attitude holds that managers in the host country know the best ways to run their operations?","options":["Ethnocentric","Polycentric","Geocentric","International"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A polycentric attitude is the belief that managers in the host country understand local conditions best, so they should decide how to run the operations there. Option A, ethnocentric, is the opposite because it trusts home-country practices. Option C, geocentric, looks for the best approach anywhere in the world rather than favouring the host country."}},{"itemId":"f5fc3428-809c-5efd-a762-0d8c724ca722","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6f3271b2-069f-56b8-98b5-b9040e46943b","sourceKey":"bank:AMS101:AMS101-T292","parentItemId":null,"revision":1,"payload":{"prompt":"What kind of view does the geocentric attitude represent?","options":["A national view","A world view","A culture-bound view","A narrow view"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The geocentric attitude is world-oriented: it seeks the best approaches and people from all over the globe, regardless of nationality. Options A, C and D describe narrow or home-centred views, which are closer to ethnocentrism and parochialism."}},{"itemId":"0b277c35-f87f-5660-815d-b24149d0231a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"838b49c7-78db-57c0-b606-ee2410343ab8","sourceKey":"bank:AMS101:AMS101-T293","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of management calls for greater sensitivity to differences in national customs and practices?","options":["Ethnocentric","Polycentric","Global","Parochial"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Global management means operating across many countries, and to do this well managers must be highly sensitive to differences in customs and practices. Options A and D describe narrow, home-focused attitudes that ignore these differences, so they are the opposite of what is needed."}},{"itemId":"158775ec-de66-5bb7-b8fa-5ca15208f5c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"467c0c28-c731-54c8-915c-7c9d20db15a9","sourceKey":"bank:AMS101:AMS101-T294","parentItemId":null,"revision":1,"payload":{"prompt":"What does successful global management require?","options":["Strictly applying home-country practices","Greater sensitivity to differences in national customs and practices","Making foreign managers adopt American ways","Teaching English to foreign nationals"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Managing successfully across borders depends on understanding and respecting how customs and practices differ from country to country. Options A, C and D all involve pushing one's own ways onto others, which reflects an ethnocentric or parochial attitude rather than global sensitivity."}},{"itemId":"ffa79ebb-0c6d-5bf4-976c-c0f8f2f6d5f1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"45e1410c-e062-50c9-867c-9595ae2236c3","sourceKey":"bank:AMS101:AMS101-T295","parentItemId":null,"revision":1,"payload":{"prompt":"Which body was formed when 12 European countries came together as a single union?","options":["The European Common Market","The European Union","The Western European Alliance","The Trans-European Market (TEM)"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The European Union (EU) was created when 12 European countries united to form one economic and political union, and it has grown since then. Option A, the European Common Market, is an older and narrower trading arrangement, while Options C and D are not the name of this union."}},{"itemId":"aaee3b55-e5c4-54db-8344-93861e1900c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d7e57b40-a91a-5581-bd7f-ab90a83e06c9","sourceKey":"bank:AMS101:AMS101-T296","parentItemId":null,"revision":1,"payload":{"prompt":"Which grouping is made up of countries that share a single currency?","options":["The European Common Market","The European Union","The Western European Alliance","The Economic and Monetary Union (EMU)"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The Economic and Monetary Union (EMU) is the group of countries that have adopted a common currency, the euro. Option B is tempting, but not every European Union member uses the euro, so the EU as a whole is not defined by a shared currency. Options A and C are not groupings built around one currency."}},{"itemId":"50d1bb77-466d-5fec-b015-3a2c70d4b7d7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"28f98a40-ff5c-5cba-a6dc-0bca3edce068","sourceKey":"bank:AMS101:AMS101-T297","parentItemId":null,"revision":1,"payload":{"prompt":"The main reason European countries formed a regional trading alliance was to counter the economic power of the United States and:","options":["Canada","Mexico","Japan","Russia"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"European countries joined together so that, as one bloc, they could compete better with the strongest economies of the time, the United States and Japan. Options A, B and D were not the main economic powers Europe was trying to match."}},{"itemId":"9919143f-a0dc-5387-859f-a7e05d931ab0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf24ae1d-ae52-5f21-acd6-4f2f1a4ca34d","sourceKey":"bank:AMS101:AMS101-T298","parentItemId":null,"revision":1,"payload":{"prompt":"Before the European Union was formed, member countries had barriers that held back their firms. Which of the following did these barriers involve?","options":["Border controls, taxes and subsidies","Nationalist policies and travel","Employment, investment and trade","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Before the EU, each country kept its own border controls, taxes and subsidies, nationalist policies and protected industries, and these barriers limited travel, employment, investment and trade across Europe. Removing them was a key aim of the union. Since A, B and C all describe parts of these barriers, D is the correct choice."}},{"itemId":"d5a0dcc1-74bc-579a-8bef-28569f1ea355","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e5a58e6-5878-5fde-9e5e-8b12c55b027b","sourceKey":"bank:AMS101:AMS101-T299","parentItemId":null,"revision":1,"payload":{"prompt":"What is the name of the single currency used across the European Union's common-currency area?","options":["Franc","Franc-mark","Pound","Euro"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The euro is the shared currency adopted by the EU countries in the common-currency area. The franc (Option A) was a former national currency, and the pound (Option C) is the currency of Britain, which never adopted the euro."}},{"itemId":"504e3b26-b5a9-562d-9ede-fbadea6379ef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"87d3d13a-bd24-5687-b35d-7aa266520c64","sourceKey":"bank:AMS101:AMS101-T302","parentItemId":null,"revision":1,"payload":{"prompt":"What was the main motivation for European countries to join the European Union?","options":["To lower their economic competitiveness with other parts of the world","To boost European countries' political power in global peace talks","To control tax exemptions in Europe and help members catch tax evaders","To regain their economic strength relative to America and Japan"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The European Union was formed mainly so that member countries, acting together, could reassert their economic position against the United States and Japan. Option A is the opposite of the real aim, since they wanted to become more competitive, not less. Options B and C name side issues rather than the main motivation."}},{"itemId":"1161b29f-d082-5e86-981d-086642d4225e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0b45fb66-9597-5b17-bf60-2df3ab7f05af","sourceKey":"bank:AMS101:AMS101-T303","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about the North American Free Trade Agreement is correct?","options":["Its members are Mexico, Canada and the United States","Its members are Mexico, Brazil and Colombia","It cut down trade between the United States and Canada","It weakened the economies of Canada and the United States while strengthening Mexico"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The North American Free Trade Agreement (NAFTA) was a regional trading alliance between Mexico, Canada and the United States, designed to remove trade barriers among them. Option B is wrong because Brazil and Colombia are in South America and were not members. Option C is wrong because the aim was to increase, not reduce, trade."}},{"itemId":"e81a46c5-d1e8-5b58-8a28-a2f83de1f3f2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d2d8040c-2c52-5a10-a7ae-c468889826a3","sourceKey":"bank:AMS101:AMS101-T307","parentItemId":null,"revision":1,"payload":{"prompt":"From about when did multinational corporations (MNCs) become common?","options":["The mid-1960s","The mid-1970s","1945","The mid-1980s"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"International business has a long history, but multinational corporations only became common from around the mid-1960s, as more firms set up major operations in several countries. Option C, 1945, is the end of the Second World War, which is earlier than MNCs became widespread."}},{"itemId":"4dc28d0c-98e9-5ac1-b17d-0e32d7ee4d9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ea66b476-0dd6-5730-87ba-449f1cdf0733","sourceKey":"bank:AMS101:AMS101-T308","parentItemId":null,"revision":1,"payload":{"prompt":"Which countries belong to the Association of Southeast Asian Nations (ASEAN)?","options":["The European Union members plus India","The members of the North American Free Trade Agreement and of the European Union","The former Soviet Union countries","None of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"ASEAN is a trading alliance of countries in Southeast Asia, such as Singapore, Malaysia, Indonesia, Thailand and the Philippines. None of the groups in Options A, B and C are Southeast Asian nations, so D is correct."}},{"itemId":"0e4291c7-dbe8-50a3-bfa7-99c6fd63e779","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2cf9faa6-e92f-5d59-b519-79703955586a","sourceKey":"bank:AMS101:AMS101-T309","parentItemId":null,"revision":1,"payload":{"prompt":"Multinational corporations are usually associated with which of the following?","options":["Ethnocentric attitudes","Polycentric attitudes","Multicentric attitudes","Holding all their operations in a single country"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A multinational corporation has major operations in several countries but is managed from a base in its home country, with key decisions made there. This home-country focus reflects an ethnocentric attitude. Option B fits transnational corporations better, since they let local managers decide, and Option D contradicts the very idea of a multinational."}},{"itemId":"88404574-1e19-5fb2-aa22-10a51373eda3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cee01311-9ded-52f1-ad2b-dc4692f5054b","sourceKey":"bank:AMS101:AMS101-T311","parentItemId":null,"revision":1,"payload":{"prompt":"A company scraps its structure based on countries and reorganizes itself around industries instead. What type of global organization is it becoming?","options":["Ethnocentrism","Polycentrism","A borderless organization","A multinational organization"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A borderless organization removes structural divisions based on geography, such as country divisions, and organizes in other ways, for example by industry. This is done to operate more efficiently worldwide. Options A and B are attitudes, not ways of organizing, and Option D still keeps operations managed from a home base."}},{"itemId":"f611b477-d082-5c57-9c97-e5de34045953","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"672f2e48-0af7-54e1-a3f0-b8b8de4c6043","sourceKey":"bank:AMS101:AMS101-T312","parentItemId":null,"revision":1,"payload":{"prompt":"Why are borderless organizations created?","options":["To raise efficiency","To raise effectiveness","To compete more aggressively in international sales","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Firms become borderless to remove artificial geographic barriers, which helps them work more efficiently, more effectively and compete harder in global markets. Since A, B and C are all reasons, D is the correct answer."}},{"itemId":"14fe0aae-b9a1-590c-878d-dbcc373ad5e8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a502161-e96f-52e6-ae37-ea2823a18f01","sourceKey":"bank:AMS101:AMS101-T313","parentItemId":null,"revision":1,"payload":{"prompt":"What does a borderless organization do?","options":["It relies on ethnocentrism","It concentrates on a polycentric attitude","It goes global by removing structural divisions that create artificial geographic barriers","It is simply another form of multinational organization"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A borderless organization gets rid of structures based on geography, such as country divisions, which can act as artificial barriers. This lets it operate as one global company. Option D is wrong because a multinational still manages its operations from a home-country base."}},{"itemId":"4933ff78-d22e-5676-8a22-fdac12283955","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7cc9059b-6b38-5306-b649-b9fe0b0c8fe2","sourceKey":"bank:AMS101:AMS101-T316","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a feature of a transnational corporation?","options":["Decisions are made at the local level","Local nationals are usually hired to run operations in each country","Marketing strategies are adapted to each country's culture","Products are made only in the local country"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Transnational corporations decentralize decisions, hire local nationals to run each country's operations and tailor marketing to local cultures, so Options A, B and C are all features. They do not have to manufacture only in the local country, which makes Option D the exception."}},{"itemId":"f0824d52-b4be-5f01-831d-e4f6e5c07b9f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4f48b62b-c561-5ed9-a614-322d7e2d2a87","sourceKey":"bank:AMS101:AMS101-T318","parentItemId":null,"revision":1,"payload":{"prompt":"How many stages does an organization usually pass through on its way to becoming global?","options":["One","Two","Three","Five"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Organizations typically go global in three stages: Stage I involves passive exporting and importing, Stage II involves openly going after foreign markets with representatives or salespeople, and Stage III involves a strong international presence through licensing, franchising, alliances, joint ventures or subsidiaries."}},{"itemId":"32ca0177-2c29-5fb6-8f59-65b67b53fa32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c5e8285-8e9a-59f1-a018-1f7205e92467","sourceKey":"bank:AMS101:AMS101-T319","parentItemId":null,"revision":1,"payload":{"prompt":"A company takes its first step toward global business by exporting its products to other countries and importing goods from abroad. This is known as:","options":["Stage I of doing business globally","Stage II of doing business in a polycentric way","Stage III of business incorporation","An unusual operation for a geocentric organization"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stage I of going global is when a company starts exporting its products and importing goods, with little direct presence abroad. Options B and C attach stage numbers to unrelated terms, and Stage II is the later step of sending employees abroad as salespeople or hiring foreign agents. Option D is wrong because exporting and importing are ordinary activities for firms going global."}},{"itemId":"90a6e846-6f4c-59ad-ae1b-acbe23e9bb0a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a487c82-3f6a-5475-a483-b1307880932c","sourceKey":"bank:AMS101:AMS101-T320","parentItemId":null,"revision":1,"payload":{"prompt":"In Stage II of doing business globally, an organization would:","options":["Start importing and exporting","Start importing but not exporting goods","Send employees abroad as salespeople or hire agents in other countries","Keep all its employees in the home country"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In Stage II, the organization makes a bigger commitment by sending its own employees abroad to sell, or by hiring foreign agents or brokers to represent its products. Option A describes Stage I, and Option D is the opposite of what happens in Stage II."}},{"itemId":"62ce1578-c674-5d7d-9bd8-7f41071078af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65812a59-0c98-541c-aaf7-40a93d5b76c2","sourceKey":"bank:AMS101:AMS101-T321","parentItemId":null,"revision":1,"payload":{"prompt":"In Stage III of doing business globally, an organization would make use of:","options":["Licensing and franchising","Strategic alliances","Joint ventures","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stage III is where a company becomes strongly committed abroad, using licensing and franchising, strategic alliances, joint ventures or even foreign subsidiaries. Since A, B and C all belong to this stage, D is correct."}},{"itemId":"1306795c-4f49-5cd1-8c69-30b9576efa00","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"206dc02b-0600-5bbe-9e4d-97bb696bae8e","sourceKey":"bank:AMS101:AMS101-T322","parentItemId":null,"revision":1,"payload":{"prompt":"What marks the first stage of an organization's move to global operations?","options":["Exporting its products to other countries","Giving its managers cross-cultural training","Hiring foreign agents to represent its products","Sending home-country staff on regular business trips abroad"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The first stage of going global involves exporting products to other countries (and importing), with little else in the way of foreign presence. Options C and D describe Stage II, where the company starts sending people abroad or hiring foreign representatives."}},{"itemId":"764e7844-9853-5f14-bb0f-7945d6678bad","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab2f6172-7146-5b3c-ba7f-10fd75b63d48","sourceKey":"bank:AMS101:AMS101-T323","parentItemId":null,"revision":1,"payload":{"prompt":"What marks Stage II of an organization's move to global operations?","options":["Exporting its products to other countries","Giving its managers cross-cultural training","Hiring people abroad to represent the organization","Licensing another firm to use its brand name"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In Stage II, the organization takes a more active approach by hiring foreign representatives or sending its own salespeople abroad. Option A belongs to Stage I, and Option D, licensing, is part of Stage III."}},{"itemId":"096bc302-490a-5fa7-aef1-394bec55b308","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0f863e8a-b98b-53d1-aa6a-fe8dc396b9e7","sourceKey":"bank:AMS101:AMS101-T324","parentItemId":null,"revision":1,"payload":{"prompt":"A joint venture is a specific type of:","options":["Licences","Franchises","Foreign subsidiaries","Strategic alliances"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A joint venture is a specific type of strategic alliance in which partners agree to work together on a business purpose, sharing resources and knowledge. Options A and B are arrangements where one firm sells another the right to use its brand, technology or methods, and Option C is a facility wholly owned by the company itself, so none of them involves partners combining efforts."}},{"itemId":"df8e883f-621b-5028-9a57-8769227a42aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c6b4ee8-d3c5-5acd-991f-e3d0449d2709","sourceKey":"bank:AMS101:AMS101-T325","parentItemId":null,"revision":1,"payload":{"prompt":"During which stage of going global does an organization form a strategic alliance?","options":["I","II","III","IV"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Strategic alliances are part of Stage III, when an organization commits strongly to international markets through arrangements such as licensing, franchising, alliances, joint ventures and subsidiaries. Stage I is exporting and importing, Stage II is hiring foreign representatives, and there is no Stage IV in this model."}},{"itemId":"c804d5d0-4662-5ed8-86c1-568442f940ea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d56abac-cc86-5ee5-ad94-e1666d6cdc30","sourceKey":"bank:AMS101:AMS101-T326","parentItemId":null,"revision":1,"payload":{"prompt":"A home-country firm and a foreign firm split the cost of developing new products or building production plants in a foreign country. This arrangement is called a:","options":["Franchising agreement","Joint venture","Foreign subsidiary","Brokering agreement"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"When a local firm and a foreign partner share costs and resources to develop products or build facilities together, they are forming a strategic alliance, and a joint venture is the specific form of this among the options. Option C is wrong because a foreign subsidiary is fully owned by one company, so no costs are shared."}},{"itemId":"07427114-4c19-56cf-9202-e68db11e1828","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf6952a9-c6fe-5f33-b8ba-8d6e5fac3a51","sourceKey":"bank:AMS101:AMS101-T327","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following marks Stage III of an organization's move to global operations?","options":["Giving its managers cross-cultural training","Sending home-country staff on regular business trips abroad","Hiring foreign agents to represent its products","Management setting up a joint venture"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stage III involves a strong commitment to foreign markets through options like licensing, franchising, strategic alliances, joint ventures and subsidiaries. Setting up a joint venture fits here. Options B and C describe Stage II activities."}},{"itemId":"561869dc-da95-5e03-abc1-8c79b50fdbb5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"afa42bf6-13e1-5dac-9f31-9d70d73a79b5","sourceKey":"bank:AMS101:AMS101-T328","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these carries the greatest risk for an organization going international?","options":["Joint ventures","Strategic alliances","Licensing","Foreign subsidiaries"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A foreign subsidiary is a separate facility or office set up and fully owned by the company in another country, so the company bears all the cost and risk itself. Options A and B share costs with a partner, and Option C, licensing, requires little investment, which makes them less risky."}},{"itemId":"2e7081fb-0b6f-5f90-a3bd-e98a54513b70","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b7b7b350-0f3d-55d7-8c27-a87a28a3c1da","sourceKey":"bank:AMS101:AMS101-T329","parentItemId":null,"revision":1,"payload":{"prompt":"Managers working in a foreign country usually face major challenges from three environments. Which of the following is NOT one of them?","options":["Legal environment","Economic environment","Cultural environment","Religious environment"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The main challenges in managing abroad are usually grouped as the legal-political, economic and cultural environments. Religion matters, but it is treated as part of the cultural environment rather than a separate one, so Option D is the one not listed."}},{"itemId":"8935e5b6-0348-56bd-9326-486527e0eea8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"49a198f5-e4b2-5345-932d-f94771524c81","sourceKey":"bank:AMS101:AMS101-T330","parentItemId":null,"revision":1,"payload":{"prompt":"From an economic point of view, which of these is a threat to a global manager?","options":["Widely changing inflation rates in foreign countries","Marginal revenue being higher than marginal cost","Stable exchange rates between countries' currencies","All of the above"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Inflation rates that swing widely make it hard to predict costs, prices and profits, which is a real economic risk for managers working abroad. Option B is actually good news, since earning more than it costs is profitable, and Option C, stable exchange rates, reduces risk. So D cannot be right."}},{"itemId":"0a4b187f-1115-5dff-83b9-78089b435173","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bfdf78a6-3907-5968-96cb-3bf0e6a652d3","sourceKey":"bank:AMS101:AMS101-T333","parentItemId":null,"revision":1,"payload":{"prompt":"Why is information about a nation's cultural differences the hardest to obtain?","options":["People are usually sensitive about their own culture","Sharing such information with foreign firms reduces a competitive advantage","Little has been written on the subject","Natives are the least able to explain what is unique about their own culture"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Culture is so much a part of people's daily lives that they take it for granted and rarely notice what makes it different. As a result, natives find it hard to explain their own culture to outsiders. Option A sounds reasonable, but sensitivity is not the main reason; the problem is that people are too close to their own culture to see it."}},{"itemId":"c851bd3d-b549-5984-bd81-cef1412e59af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4341880e-11c9-5ec6-a5a8-67e3970bdf90","sourceKey":"bank:AMS101:AMS101-T334","parentItemId":null,"revision":1,"payload":{"prompt":"Which researcher developed a widely used framework that helps managers understand differences between national cultures?","options":["Milton Friedman","Michael Porter","Geert Hofstede","Abraham Maslow"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Geert Hofstede studied employees in many countries and identified dimensions of national culture, such as power distance, individualism versus collectivism and uncertainty avoidance. Option A, Milton Friedman, is known for the classical view of social responsibility, and Option B, Michael Porter, for work on competitive strategy."}},{"itemId":"812d6d4f-daa0-5dc4-a8d7-1d0b36b5608d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4c394eff-748f-5274-be2a-02f5e29f9960","sourceKey":"bank:AMS101:AMS101-T335","parentItemId":null,"revision":1,"payload":{"prompt":"Which cultural dimension describes people who expect others in their group to look after and protect them when they are in difficulty?","options":["Power distance","Collectivism","Quantity of life","Uncertainty avoidance"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Collectivism is a cultural dimension in which people see themselves as part of a close group and expect group members to care for and protect them in times of trouble. Option A, power distance, is about how much people accept unequal power in society, which is a different idea."}},{"itemId":"271c16de-535b-5864-8183-6db30bfa9a97","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"11caba87-4a0e-5f4e-9e80-bba2501ceaf4","sourceKey":"bank:AMS101:AMS101-T336","parentItemId":null,"revision":1,"payload":{"prompt":"What would you expect to see in a country with high power distance?","options":["Society accepts only small differences in organizations","Titles carry little power, but status power is high","People show little respect for those in authority","At meetings, organizational representatives have very different status and titles"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"High power distance means society accepts large differences in power and status, so titles, rank and status carry great weight. Meetings would therefore include people of widely different status and titles. Options A and C describe low power distance, where differences are small and authority is respected less."}},{"itemId":"1536b57c-fc72-524e-961b-bf33f1a69a73","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8e4fee6b-7e37-51e2-b781-645967f45c67","sourceKey":"bank:AMS101:AMS101-T337","parentItemId":null,"revision":1,"payload":{"prompt":"Which cultural measure shows how far people will tolerate risk and unconventional behaviour?","options":["Power distance","Uncertainty avoidance","Quantity of life","Quality of life"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Uncertainty avoidance measures how comfortable people are with risk and the unknown, and how much they accept unconventional behaviour. High uncertainty avoidance means people prefer rules and certainty. Option A, power distance, is about acceptance of unequal power, not risk."}},{"itemId":"839da7ac-f9de-5596-ac3b-916e55d81b18","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd837353-9b73-59ef-b63b-e410e0baffc3","sourceKey":"bank:AMS101:AMS101-T338","parentItemId":null,"revision":1,"payload":{"prompt":"In which kind of culture are organizations most likely to have formal rules and little tolerance for unusual ideas and behaviour?","options":["High power distance","Low power distance","High uncertainty avoidance","Low uncertainty avoidance"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In cultures high in uncertainty avoidance, people feel uneasy about risk and ambiguity, so organizations rely on formal rules and are less accepting of unusual ideas or behaviour. Option D is the opposite, since low uncertainty avoidance means people are comfortable with risk and difference. Option A relates to status, not rules about behaviour."}},{"itemId":"4e021aeb-569d-572e-829d-9edadfa094c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b0e19b66-126f-51e2-8f53-40c407b9f69b","sourceKey":"bank:AMS101:AMS101-T339","parentItemId":null,"revision":1,"payload":{"prompt":"In a society with high ______________, titles, rank and status count for a great deal.","options":["Collectivism","Power distance","Compassionate conservatism","Uncertainty avoidance"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Power distance is the degree to which people accept that power in organizations and society is shared unequally. When it is high, titles, rank and status carry a lot of weight. Option A, collectivism, is about group loyalty, and Option D is about tolerance of risk, so neither fits."}},{"itemId":"f8e49563-1dcb-5bdc-8b44-9f0644b14a55","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f4026db-fd68-544f-b8d8-40ba9657ec81","sourceKey":"bank:AMS101:AMS101-T340","parentItemId":null,"revision":1,"payload":{"prompt":"Which national culture dimension describes how far a society's values stress assertiveness and material things?","options":["Power distance","Uncertainty avoidance","Quantity of life","Quality of life"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Quantity of life describes a culture that values assertiveness, acquiring money and material goods, and competition. Option D, quality of life, is the opposite, stressing relationships and concern for others' well-being."}},{"itemId":"bb98856f-01bf-5932-9227-2709b6fa79af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"550d2dfa-9a64-5714-967f-c9d7ea5704d7","sourceKey":"bank:AMS101:AMS101-T341","parentItemId":null,"revision":1,"payload":{"prompt":"Which national culture dimension reflects how much emphasis is placed on relationships and caring for others?","options":["Power distance","Uncertainty avoidance","Quantity of life","Quality of life"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Quality of life describes a culture that values relationships, sensitivity and concern for the welfare of others. Option C, quantity of life, is the opposite, emphasizing assertiveness, money and material things."}},{"itemId":"a951ecd8-625c-5176-a4d8-f2edb0cc4036","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b50d3061-5f15-5a9a-b384-8145b1f0ed39","sourceKey":"bank:AMS101:AMS101-T343","parentItemId":null,"revision":1,"payload":{"prompt":"Employee relations, charitable giving, pricing, conserving resources, product quality and safety, and trading in countries that abuse human rights are clear examples of:","options":["Social responsibility ethics that managers must settle every day","Social responsibility issues that employees face at work","Areas of social responsibility that affect managers but not employees","Decisions managers face that carry a social responsibility dimension"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Each item listed is a choice managers have to make, and each one affects society as well as the firm, so it has a social responsibility side to it. Option B shifts the focus to employees, and Option C wrongly claims employees are unaffected; the point is about managerial decisions with a social dimension."}},{"itemId":"bec3a4d0-2b12-5659-ac03-b0d44365bd94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d5055817-4a84-5030-b52c-d101a46413b5","sourceKey":"bank:AMS101:AMS101-T344","parentItemId":null,"revision":1,"payload":{"prompt":"According to the classical view of social responsibility, management's only social responsibility is to:","options":["Maximize profits for the organization's stockholders","Maximize compliance with the law for stockholders","Maximize profits for the organization's stakeholders","Minimize compliance with the law for stockholders"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The classical view holds that a business meets its social duty by maximizing profits for its stockholders, the owners. Option C is tempting, but stakeholders is a wider group including employees and the community; serving that wider group is the idea behind the socioeconomic view, not the classical one."}},{"itemId":"2098720d-a99b-5650-8d87-ba31d07abdb2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"513020ee-9ae9-5719-98e6-46b96fd9c344","sourceKey":"bank:AMS101:AMS101-T345","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is linked with the classical view of social responsibility?","options":["Economist Robert Reich","Concern for social welfare","Financial returns to stockholders","Voluntary activities"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The classical view says management's main responsibility is to earn financial returns for stockholders. Options B and D, concern for social welfare and voluntary activities, belong to the socioeconomic view, which says business should also protect and improve society."}},{"itemId":"bad0f6a4-8cab-5ab3-9fd2-c53afb32619d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c390a8b-8bdb-53f4-9e9b-53a4dd8ff9b5","sourceKey":"bank:AMS101:AMS101-T346","parentItemId":null,"revision":1,"payload":{"prompt":"Supporters of the socioeconomic view of social responsibility believe that businesses are:","options":["More than just economic institutions","Nothing more than economic institutions","Meant to be leaders in social responsibility","Not meant to be involved in social responsibility, only in maximizing profits for stakeholders"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The socioeconomic view holds that businesses are not only economic institutions; they also have duties to protect and improve society's welfare. Option B states the classical view instead. Option C overstates the idea, since the view says business has social responsibilities, not that it must lead society."}},{"itemId":"15aaf019-dc9d-5bc2-80bf-42fb210ed545","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"52f18958-bc55-50db-8270-0de702ad9f38","sourceKey":"bank:AMS101:AMS101-T347","parentItemId":null,"revision":1,"payload":{"prompt":"What term describes using social criteria when making investment decisions?","options":["Socioeconomic view","Social responsiveness","Social responsibility","Social screening"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social screening means applying social standards, such as how a company treats workers or the environment, when choosing where to invest. Option B, social responsiveness, is about a firm adapting to changing social conditions, and Option C, social responsibility, is the firm's broader duty to do good for society."}},{"itemId":"e6e7bf4d-3cc0-5997-95cd-c4ade1080e22","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e04dac8d-bdf0-5cdb-81cc-18dcb75bc38d","sourceKey":"bank:AMS101:AMS101-T348","parentItemId":null,"revision":1,"payload":{"prompt":"Which term refers to a business firm's obligation, over and above what law and economics require, to pursue long-term goals that benefit society?","options":["Social obligation","Social responsibility","Social screening","Values-based management"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social responsibility goes beyond what the law and economics demand and asks the firm to pursue long-term goals that are good for society. Option A, social obligation, is only doing what the law and economic duties require, which is less than social responsibility."}},{"itemId":"d00290d5-6927-57fd-99c9-f4f268c29e2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc58a128-ba66-5f8a-9e24-78a2c95f4205","sourceKey":"bank:AMS101:AMS101-T349","parentItemId":null,"revision":1,"payload":{"prompt":"Who is the best-known advocate of the classical view of social responsibility, an economist and Nobel prize winner?","options":["Carnegie Milton","Charles Darwin","Milton Freeman","Milton Friedman"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Milton Friedman, a Nobel prize-winning economist, argued that the main social responsibility of business is to make profits for its owners. Option C, Milton Freeman, is a misspelt look-alike name, and Option B, Charles Darwin, was a naturalist known for the theory of evolution."}},{"itemId":"88b28096-9692-5c52-88fb-bbfa826a0685","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a33108d-10f1-525d-936b-24b6c6d9026c","sourceKey":"bank:AMS101:AMS101-T350","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument for social responsibility says businesses should act responsibly simply because it is the right thing to do?","options":["Public expectations","Ethical obligation","Public image","Discouraging further government regulation"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The ethical obligation argument says businesses should be socially responsible because responsible actions are right in themselves. Option C, public image, is about gaining a better reputation, and Option D is about avoiding new laws, so both are self-interested reasons rather than doing right for its own sake."}},{"itemId":"ccd517e2-b0ce-5011-aa3c-a86c7a20d45e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"49365e55-8f16-5b2a-9ade-ba833f866b18","sourceKey":"bank:AMS101:AMS101-T351","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument for social responsibility says that businesses that help solve hard social problems create a better community, which helps them attract and keep skilled workers?","options":["Ethical obligation","Public image","Better environment","Possession of resources"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The better environment argument says that when business helps solve social problems, it improves the community, making it a more attractive place to live and work for skilled employees. Option B, public image, focuses on how the firm is seen, not on improving the community itself."}},{"itemId":"fd7055fe-a896-5fb7-9a6e-a388451c1888","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d4bbc147-50ea-56b2-8ea3-601df67d6e26","sourceKey":"bank:AMS101:AMS101-T352","parentItemId":null,"revision":1,"payload":{"prompt":"A leading supporter of the classical view argues that whenever managers choose on their own to spend company resources for the 'social good', they are:","options":["Providing social benefits for the sake of goodwill","Simply doing what government requires of them","Helping make society better for everyone","Adding to the costs of doing business"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Under the classical view, spending company money on social causes raises costs, which must be paid for through lower profits, lower wages or higher prices. That is why supporters see it as adding to business costs. Options A and C reflect the socioeconomic view, which sees such spending as positive."}},{"itemId":"fb2c0587-17b2-5468-a641-875be85a225f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c52a009a-32e8-5c6e-863e-e85c25bec96a","sourceKey":"bank:AMS101:AMS101-T353","parentItemId":null,"revision":1,"payload":{"prompt":"The socioeconomic view says management's social responsibility goes beyond making profit to include:","options":["Putting members of society on welfare","Protecting and improving society's welfare","Reducing society's welfare in exchange for profits","Protecting and improving the organization's profits"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The socioeconomic view holds that managers must also protect and improve the welfare of society, not just make money. Option D is about profit, which is what the view says responsibility goes beyond, and Option C is the opposite of the idea."}},{"itemId":"d1ecd856-d8d9-5544-891b-ba45632da562","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a270cc8-ecfd-5ba1-adbe-6852f96b8b42","sourceKey":"bank:AMS101:AMS101-T354","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument for social responsibility says that if businesses act responsibly, they can expect less government regulation?","options":["Discouraging further government regulation","Stockholder interests","Public expectations","Public image"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"This argument says that when businesses behave responsibly on their own, government has less reason to make new rules for them. That makes it the 'discouraging further government regulation' argument. Option C, public expectations, is about what society wants from business, not about avoiding regulation."}},{"itemId":"408f466d-6334-56d7-9888-57b24b05c399","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc12f32a-c462-5bd1-986d-02d27241f910","sourceKey":"bank:AMS101:AMS101-T355","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument for social responsibility says that a mismatch between the great power firms hold and the responsibility they accept harms the public good?","options":["Public expectations","Ethical obligation","Public image","Balance of responsibility and power"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The balance of responsibility and power argument says that businesses have a lot of power in society, so they should accept a matching level of responsibility. Power without responsibility can harm the public. Option B is about doing right for its own sake, which is a different reason."}},{"itemId":"e5e3d1f5-05df-5bdd-9397-ca2f98dd5bb3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0f8dbf8f-c428-50a4-9aa1-a59e873097e8","sourceKey":"bank:AMS101:AMS101-T356","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument says businesses have the money, technical skills and management ability to support needed public and charitable projects?","options":["Public expectations","Ethical obligations","Public image","Possession of resources"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The possession of resources argument says businesses have financial, technical and managerial resources that they can use to support public and charity projects. Options A and C are about what the public wants and how the firm looks, not about the resources a business has."}},{"itemId":"b62efd64-0c0d-5715-aa55-bd818dbc9524","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2de6b87b-92a3-5e88-8324-ab3060586bf1","sourceKey":"bank:AMS101:AMS101-T357","parentItemId":null,"revision":1,"payload":{"prompt":"Social obligation is a business's duty to fulfil its:","options":["Social and technological responsibilities","Economic and social responsibilities","Technological and economic responsibilities","Economic and legal responsibilities"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social obligation means a firm does what it is required to do, meeting its economic and legal responsibilities and no more. Option B is tempting, but going beyond economic and legal duties to serve society is what social responsibility, not social obligation, involves."}},{"itemId":"450871b5-b4b8-5090-8576-f76f4bf64b50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2dd3e4e8-cdb1-5701-8544-ecf2f3c406be","sourceKey":"bank:AMS101:AMS101-T358","parentItemId":null,"revision":1,"payload":{"prompt":"Social responsiveness is a firm's ability to adapt to changing:","options":["Societal conditions","Organizational conditions","Societal leaders","Organizational managers"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social responsiveness means a business adjusts its actions as conditions in society change, responding to what society needs or expects. Option B focuses on conditions inside the organization, which is not what the term is about."}},{"itemId":"601e020e-0d03-5271-b9fc-28f890a42737","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"194989bd-332b-5171-be85-90858ae244a2","sourceKey":"bank:AMS101:AMS101-T359","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument against social responsibility says businesses are acting responsibly when they attend only to their economic interests?","options":["Dilution of purpose","Violation of profit maximization","Costs","Too much power"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The violation of profit maximization argument says a business is being socially responsible only when it pursues its own economic interests, so other social activities go against its purpose. Option A, dilution of purpose, says social goals distract from the main goal of productivity, which is a related but different argument."}},{"itemId":"03a1e7fb-9b8f-5898-9a83-f876381a1309","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a57c4b8-9fb2-5181-bc7c-ee0279cf44aa","sourceKey":"bank:AMS101:AMS101-T360","parentItemId":null,"revision":1,"payload":{"prompt":"A company meets government pollution-control standards and does not discriminate in hiring, promotion and pay. This company:","options":["Is meeting its social obligation and more, because it is trying to be a good citizen","Is not even meeting its social obligation, although there are laws in some of these areas","Is meeting its social obligation and nothing more, because the law requires these actions","Is showing social responsiveness and nothing more, because society demands these actions"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Meeting pollution standards and avoiding discrimination are things the law requires, so the company is meeting its social obligation and nothing more. Option A is wrong because going beyond the law would be social responsibility, and Option D is wrong because these actions come from legal requirements, not from adapting to social pressure."}},{"itemId":"a33cf7d0-fbc7-5918-a564-7fcc3ae4e748","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1aeb8184-3c6c-523b-96bf-357114474eb4","sourceKey":"bank:AMS101:AMS101-T361","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument against social responsibility says the cost of social activities is passed on to consumers as higher prices?","options":["Violation of profit maximization","Dilution of purpose","Costs","Lack of skills"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The costs argument says that social activities cost money, and businesses will pass those costs on to customers as higher prices. Option A is about social actions going against the profit goal, and Option D is about managers lacking the skills to handle social issues."}},{"itemId":"7650a0ea-ad7e-5aa5-85fc-4b565bf88fb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8e4e61ea-7693-5498-be21-8efd22f9a263","sourceKey":"bank:AMS101:AMS101-T362","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument against social responsibility says that pursuing social goals would give firms too much power?","options":["Costs","Lack of skills","Lack of broad public support","Too much power"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The too much power argument says businesses are already very powerful, and pursuing social goals as well would give them even more power over society. Option C is about the public not agreeing that business should get involved in social issues, which is a different objection."}},{"itemId":"24032e54-52b6-50e2-9d9a-2837b3cff463","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83fa4448-42d8-51a8-8f57-7ac239578554","sourceKey":"bank:AMS101:AMS101-T363","parentItemId":null,"revision":1,"payload":{"prompt":"Which argument against social responsibility says business leaders should not shape social policy because they are not directly answerable to the public?","options":["Dilution of purpose","Costs","Too much power","Lack of accountability"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The lack of accountability argument says politicians answer to voters, but business leaders do not, so they should not set social policy. Option C, too much power, focuses on the size of business influence rather than on who it answers to."}},{"itemId":"a7313217-9c02-5337-b082-9c451358c64e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ed3ae9b-513b-5c7a-a9cb-cede659708e5","sourceKey":"bank:AMS101:AMS101-T365","parentItemId":null,"revision":1,"payload":{"prompt":"A firm advertises that it uses only recycled paper products. In doing so, it is:","options":["Meeting its social obligation","Meeting its social responsibilities","Being socially responsive","Focusing on the bottom line"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Using only recycled paper and advertising it is a response to society's growing concern for the environment, so the firm is adapting to changing social conditions, which is social responsiveness. Option A is wrong because no law requires this. Option B is partly tempting, but this action is best described as responding to public preferences rather than pursuing a deeper ethical duty."}},{"itemId":"27af53fd-9fb0-559d-bc48-4cc27acb9235","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71a3329a-89b0-5681-8d9b-5cc8f5367002","sourceKey":"bank:AMS101:AMS101-T366","parentItemId":null,"revision":1,"payload":{"prompt":"Results should be read with care, but what do more than a dozen studies on the link between corporate social responsibility and economic performance conclude?","options":["Being socially responsible causes good economic performance","Good economic performance allows firms to be socially responsible","There is a positive relationship between corporate social involvement and economic performance","Corporate social involvement tends to lower share prices in the long run"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Most studies find a positive relationship between social involvement and economic performance. However, a relationship is not proof of cause, which is why Options A and B go too far: they claim one causes the other, which the research cannot show. Option D contradicts the findings."}},{"itemId":"ca9e9556-40c8-5e34-8705-350166caf9d3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a227284-c734-575b-a8c9-b2f249e61fa6","sourceKey":"bank:AMS101:AMS101-T367","parentItemId":null,"revision":1,"payload":{"prompt":"On the whole, does the evidence suggest that socially responsible behaviour lowers a firm's economic performance?","options":["Yes","No","There is not yet enough evidence to be sure","It depends on the activity the organization is involved in"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Overall, research has found little evidence that socially responsible actions hurt a firm's long-term economic performance. So the answer is no. Option C may seem cautious, but the evidence is clear enough to say such behaviour does not significantly lower performance."}},{"itemId":"f17e6af9-1794-5df4-90b4-2d222598baaa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e169c96e-2fb2-5ddb-808f-d5950729a3fa","sourceKey":"bank:AMS101:AMS101-T369","parentItemId":null,"revision":1,"payload":{"prompt":"Under the idea of social obligation, an organization:","options":["Does what it can to obey the law, plus a little extra for stakeholders","Meets its duties to the law and to its stakeholders","Meets its duties to stakeholders, which also makes it obey the law","Does only the minimum the law requires"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social obligation means a firm does only what it is legally and economically required to do, nothing more. Options A, B and C all suggest going beyond the law for stakeholders, which moves towards social responsiveness or social responsibility instead."}},{"itemId":"70455242-e2a3-5943-ab2b-ffc46105739f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be747e0a-a4b7-5913-8f26-683e4d721d92","sourceKey":"bank:AMS101:AMS101-T370","parentItemId":null,"revision":1,"payload":{"prompt":"There is __________ that a company's socially responsible actions seriously harm its long-term economic performance.","options":["No evidence at all","Little evidence","A great deal of evidence","Growing evidence"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Research shows little evidence that socially responsible actions significantly hurt a company's long-term economic results. Option A goes too far, since saying there is no evidence at all is stronger than the research supports, while Options C and D say the opposite of the findings."}},{"itemId":"cc09ce91-b8b0-5abe-aead-ba072ee962b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"38bb9785-263a-52ad-8aa9-0f50d44c6450","sourceKey":"bank:AMS101:AMS101-T371","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach to managing involves managers setting up, promoting and practising what the organization stands for and believes in?","options":["Cause-related marketing","Values-based management","Ethical marketing","Belief management"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Values-based management is when managers establish, promote and practise the organization's shared values. These values guide how people behave and make decisions. Option A, cause-related marketing, links a product to a charitable cause to boost sales, which is different."}},{"itemId":"474472a0-c567-522f-aa25-a0ba242b5312","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b4a97142-24c8-54ff-9f4a-3169dc2c5bad","sourceKey":"bank:AMS101:AMS101-T372","parentItemId":null,"revision":1,"payload":{"prompt":"Values that are shared by members of an organization can act as:","options":["A reason to obey national and regional environmental laws","A guide for managers' decisions to invest in new technology","A way of shaping managers' decisions to invest in economic conditions","A guide for managerial decisions and actions"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Shared values act as a guide for all managerial decisions and actions, shaping how people behave across the organization. Option B is too narrow, since values guide all decisions, not just technology investments. Option A is also limited, since obeying the law is required whether or not values are shared."}},{"itemId":"dd0f3b4b-8208-5d4b-b0ab-39d824e8b612","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d76c9937-ef68-53b8-9997-6de35e2d7d1f","sourceKey":"bank:AMS101:AMS101-T374","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about shared corporate values is correct?","options":["People find it easy to adjust to shared corporate values.","Shared corporate values are simply imposed by top management.","Building shared corporate values is not an easy task.","Most companies will fail to build shared corporate values."],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Creating values that everyone in a company truly holds takes time and effort, so it is not easy. Option B is tempting, but values cannot just be ordered from the top; people have to accept them. Option D goes too far, because difficult does not mean most companies will fail."}},{"itemId":"b677c2ee-f9e6-5293-a838-85688ce9027c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8122d218-51b8-5ff2-99d2-4ea5aee1d6fb","sourceKey":"bank:AMS101:AMS101-T375","parentItemId":null,"revision":1,"payload":{"prompt":"What term describes the awareness that an organization's decisions and activities are closely tied to its effect on the natural environment?","options":["corporate social responsibility","social responsiveness","shared corporate values","greening of management"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The greening of management is the recognition that what an organization decides and does has a direct effect on the natural environment. Corporate social responsibility (A) and social responsiveness (B) are broader ideas about a firm's duties to society, not specifically its environmental impact. Shared corporate values (C) are the beliefs that guide a company's behaviour."}},{"itemId":"c7143132-4b12-5503-a93b-90144646f6e8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"018cd19f-43d8-5311-a635-e56d3cf0546b","sourceKey":"bank:AMS101:AMS101-T376","parentItemId":null,"revision":1,"payload":{"prompt":"Pollution, toxic waste, global warming and the using up of natural resources are all examples of _______.","options":["social problems","global environmental problems","social responsiveness","competitive strategies"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"These issues affect the natural environment across the whole world, so they are global environmental problems. Option A is too general, since these are specifically environmental issues. Social responsiveness (C) is how a firm reacts to social needs, and competitive strategies (D) are about beating rivals."}},{"itemId":"f6aeb1f3-6010-5333-bf4d-3034c0ccaafa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e6cfec6c-9a0f-58b1-a3d4-2d90d6d1e374","sourceKey":"bank:AMS101:AMS101-T377","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of the approaches an organization can adopt toward environmental issues?","options":["legal","market","stakeholder","responsibility"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The four approaches firms take to environmental issues are legal, market, stakeholder and activist. There is no separate 'responsibility' approach, so D is the odd one out. Options A, B and C are all genuine approaches, moving from doing only what the law requires to responding to customers and then to several stakeholder groups."}},{"itemId":"83cdfdbb-085a-548a-ab22-b3a685037adb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d5c59eb-504f-5309-8fb5-5af9190ede6f","sourceKey":"bank:AMS101:AMS101-T378","parentItemId":null,"revision":1,"payload":{"prompt":"An organization that follows the stakeholder approach to environmental issues responds to _______.","options":["the demands of its most powerful stakeholders only","many demands from social stakeholders","the demands of government stakeholders","many demands from its stakeholders"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Under the stakeholder approach, the firm tries to meet the environmental demands of several stakeholder groups, such as employees, suppliers and the community. Option A is wrong because it is not limited to the strongest group. Option B narrows it to social stakeholders only, and option C to government, which is closer to the legal approach."}},{"itemId":"9d8bedb9-07fa-547b-a6ba-98deb39e0b3f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb612286-72a4-55f8-a1a0-22749c18edc4","sourceKey":"bank:AMS101:AMS101-T379","parentItemId":null,"revision":1,"payload":{"prompt":"When an organization responds to the environmental preferences of its customers, it is using the _______ approach.","options":["legal","market","stakeholder","responsibility"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The market approach means the firm acts on the environmental wishes of its customers, for example by offering eco-friendly products because buyers want them. The legal approach (A) does only what the law demands. The stakeholder approach (C) responds to many groups, not just customers, and 'responsibility' (D) is not one of the approaches."}},{"itemId":"c3da433f-6884-5f82-af83-56be55a50c5b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9dda2d52-eb20-589d-8f4b-29e069ec10ac","sourceKey":"bank:AMS101:AMS101-T380","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach to environmental issues shows the greatest environmental sensitivity and best illustrates social responsibility?","options":["legal approach","market approach","stakeholder approach","activist approach"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In the activist approach, the firm actively looks for ways to protect the earth's resources, going beyond what laws, customers or stakeholders require. This makes it the most environmentally sensitive and the clearest example of social responsibility. The legal approach (A) is the least sensitive, while market (B) and stakeholder (C) approaches respond to outside demands rather than leading."}},{"itemId":"a6d3b368-30b0-5951-b00c-b12f1ea3b3fd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f542550-f394-55cf-9162-c8cb0fb25a93","sourceKey":"bank:AMS101:AMS101-T381","parentItemId":null,"revision":1,"payload":{"prompt":"In the model showing how an organization's social responsibility expands, what new concern is added at Stage 2?","options":["stockholders","human resource concerns","safe products","fair prices"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"At Stage 2, managers widen their focus from owners to their employees, so human resource concerns are added. Stockholders (A) are the focus of Stage 1. Safe products (C) and fair prices (D) relate to customers, who come in at Stage 3."}},{"itemId":"50e0fc20-73ca-5042-9513-9e704f066b32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0849d5bb-06ce-5d12-b6db-81f873df98a1","sourceKey":"bank:AMS101:AMS101-T382","parentItemId":null,"revision":1,"payload":{"prompt":"In the model of expanding social responsibility, Stage 3 is marked by added concern for _______.","options":["stockholders","human resource concerns","owners","customers/suppliers"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stage 3 extends responsibility to groups in the firm's specific environment, such as customers and suppliers. Stockholders (A) and owners (C) are the focus of Stage 1. Human resource concerns (B) are added at Stage 2."}},{"itemId":"aa8f30ca-bd02-588b-b1fe-cf320bc57cf0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa08e273-4019-585a-a7ee-68fa03db3a59","sourceKey":"bank:AMS101:AMS101-T383","parentItemId":null,"revision":1,"payload":{"prompt":"Which option gives a basic definition of ethics?","options":["moral guidelines for behaviour","rules for respecting the spirit of the law","rules or principles that define right and wrong conduct","principles for legal and moral development"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Ethics refers to the rules or principles that define what conduct is right and what is wrong. Option A sounds close, but it is vague and does not state the right-versus-wrong standard. Options B and D bring in the law, but ethics is about right and wrong, not legal rules."}},{"itemId":"6573da96-b0ae-5382-97b5-f52fad6b6a52","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4e7f6d83-d338-5359-98b4-91775605d77b","sourceKey":"bank:AMS101:AMS101-T384","parentItemId":null,"revision":1,"payload":{"prompt":"Which ethical view focuses on respecting and protecting individual liberties and privileges, such as the rights to privacy, free speech, freedom of conscience, life and safety, and due process?","options":["utilitarian view","rights view","theory of justice view","integrative social contracts theory view"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The rights view says decisions should respect and protect basic individual liberties like privacy and free speech. The utilitarian view (A) judges decisions by their outcomes for the greatest number. The theory of justice view (C) is about fair and impartial rules, and integrative social contracts theory (D) is about existing norms in industries and companies."}},{"itemId":"41a6ad8a-1c80-509e-ac0c-5a5480e4e61e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf01a018-96f3-548a-b721-ebcfe857463f","sourceKey":"bank:AMS101:AMS101-T385","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of the four main views of business ethics?","options":["utilitarian view","principled view","rights view","theory of justice view"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The four views of business ethics are the utilitarian view, the rights view, the theory of justice view and the integrative social contracts theory view. A 'principled view' is not one of them, so B is correct. 'Principled' is actually a level of moral development, which may make it look familiar."}},{"itemId":"2694a055-83f9-56c0-afc4-1aa55468edbe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d290a500-32d8-54d7-a953-663bd5feaeb1","sourceKey":"bank:AMS101:AMS101-T386","parentItemId":null,"revision":1,"payload":{"prompt":"How many stages does the model of an organization's social responsibility progression have?","options":["one","two","three","four"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The model has four stages: Stage 1 focuses on owners and management, Stage 2 adds employees, Stage 3 adds customers and suppliers, and Stage 4 extends to society as a whole. Option C is tempting if you forget the final stage about broader society."}},{"itemId":"3dde0925-8ac5-5a78-8350-31612a2d44e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0617adc-c85c-5aa3-b200-9951938275df","sourceKey":"bank:AMS101:AMS101-T387","parentItemId":null,"revision":1,"payload":{"prompt":"Under the theory of justice view of ethics, managers should _______.","options":["treat stockholders fairly by making sure they earn an equitable return on their investment","apply and enforce rules fairly and impartially, even if this means breaking a legal rule or regulation","apply and enforce rules fairly and impartially while obeying all legal rules and regulations","apply and enforce rules fairly and impartially as decided by a government official"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The theory of justice view asks managers to set and enforce rules in a fair and impartial way while staying within the law. Option B is wrong because this view does not permit breaking laws. Option A is about investor returns, and option D wrongly hands the decision to a government official."}},{"itemId":"0b947e52-a294-57db-afcc-57a7168ad2f7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6db56dea-935b-5dc9-b809-800767aab5a4","sourceKey":"bank:AMS101:AMS101-T388","parentItemId":null,"revision":1,"payload":{"prompt":"Which ethical view promotes efficiency and productivity and fits well with the goal of maximizing profit?","options":["utilitarian view","principled view","rights view","theory of justice view"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The utilitarian view judges decisions by their results, aiming for the greatest good for the greatest number, so it supports efficiency, productivity and profit. The rights view (C) and theory of justice view (D) focus on liberties and fairness, which can sometimes slow down efficiency. A 'principled view' (B) is not one of the ethics views."}},{"itemId":"be361e9e-815b-5e6c-8ed5-75287f131c53","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e81b1cf-3ea2-5e73-9cbc-e53ec49706ba","sourceKey":"bank:AMS101:AMS101-T389","parentItemId":null,"revision":1,"payload":{"prompt":"What is the rights view of ethics based on?","options":["judging decisions by their outcomes or consequences","setting and enforcing fair and impartial rules","respecting and protecting individual liberties and freedoms","the process used to share out resources"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The rights view rests on respecting and protecting individual liberties such as privacy and free speech. Option A describes the utilitarian view, which looks at outcomes. Option B describes the theory of justice view."}},{"itemId":"0f326295-1718-5610-9b55-226f1d4d42b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd6bdc38-28e5-5b1b-8057-a461cfa9cd69","sourceKey":"bank:AMS101:AMS101-T390","parentItemId":null,"revision":1,"payload":{"prompt":"What is the integrative social contracts theory of ethics based on?","options":["the process used to share out resources","judging decisions by their outcomes or consequences","setting and enforcing fair and impartial rules","the ethical norms that already exist in industries and companies"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Integrative social contracts theory says ethical decisions should be based on the existing ethical norms in industries and companies. Option B describes the utilitarian view, and option C describes the theory of justice view."}},{"itemId":"c29231db-a746-56fb-8b70-aefb8b77aff0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"629aca7a-1e26-548c-afc6-a88c8e4d0c66","sourceKey":"bank:AMS101:AMS101-T391","parentItemId":null,"revision":1,"payload":{"prompt":"Research shows that most business people tend to hold which view of ethical behaviour?","options":["the utilitarian view","the rights view","the theory of justice view","the integrative social contracts theory view"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Most business people lean toward the utilitarian view, which judges decisions by their outcomes and fits naturally with efficiency and profit goals. The rights view (B) and theory of justice view (C) are focused on liberties and fairness. Integrative social contracts theory (D) is less widely held."}},{"itemId":"8920d80c-4fd3-5c0a-95cf-96c541ae1f5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"776e9ad0-440c-5507-a9c8-b21a3477ce6d","sourceKey":"bank:AMS101:AMS101-T392","parentItemId":null,"revision":1,"payload":{"prompt":"At which level of moral development do people believe moral values lie in maintaining the conventional order and meeting the expectations of others?","options":["preconventional","conventional","principled","arrival"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"At the conventional level, a person's sense of right and wrong comes from keeping the expected order and living up to what others expect. The preconventional level (A) is driven by personal consequences like punishment or reward. The principled level (C) is based on a person's own ethical principles, and 'arrival' (D) is not a level."}},{"itemId":"f7881c35-4a2e-5cd7-8148-ca1bae801381","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"700d95cc-189c-5dfa-922e-2e9c67d0fd59","sourceKey":"bank:AMS101:AMS101-T393","parentItemId":null,"revision":1,"payload":{"prompt":"Which personality measure reflects the strength of a person's convictions?","options":["moral development","ego strength","locus of control","social desirability"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Ego strength measures how strongly a person holds to their convictions; people high in it are more likely to do what they think is right. Locus of control (C) is about how far people believe they control their own fate. Moral development (A) is a stage of moral reasoning, not a personality measure of conviction."}},{"itemId":"e063d965-d871-5895-a405-661f0bb73132","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b6dc515a-9d9a-543d-a180-6032b223ea56","sourceKey":"bank:AMS101:AMS101-T394","parentItemId":null,"revision":1,"payload":{"prompt":"Which personality attribute measures how far people believe they control their own fate?","options":["Ego strength","Locus of control","Social responsibility","Social obligation"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Locus of control is the degree to which people believe they control their own destiny. Those with an internal locus believe their actions shape what happens to them. Ego strength (A) is about the strength of one's convictions, while C and D are about an organization's duties to society."}},{"itemId":"f33e9aa5-dba6-52fc-a5d6-7146143f9342","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"12ca184f-dd31-5361-a640-c40dda93e9ac","sourceKey":"bank:AMS101:AMS101-T395","parentItemId":null,"revision":1,"payload":{"prompt":"A manager says, \"I worked hard and hit my productivity targets even with the bad weather.\" Which individual characteristic is she showing?","options":["a strong self-image","a high level of moral development","low impression management","an internal locus of control"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"She credits her own effort for the result, which shows an internal locus of control, the belief that you control your own outcomes. Option A is tempting, but self-image is not the concept being measured. Option B is about ethical reasoning, which the statement does not show."}},{"itemId":"05e403d9-acf6-598c-a0e6-789353b18c42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5176d2ad-afa7-5fc7-a68c-bf1e57c6698d","sourceKey":"bank:AMS101:AMS101-T396","parentItemId":null,"revision":1,"payload":{"prompt":"Which feature of an organization's structure is most likely to lead to ethical behaviour by managers?","options":["few job descriptions","formal rules","mixed messages from people in authority","appraisal systems that look only at outcomes"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Formal rules and regulations reduce ambiguity, so managers know clearly what is expected and are more likely to behave ethically. Few job descriptions (A) and mixed messages from authority (C) create confusion. Appraisals that focus only on outcomes (D) can push people to reach results by any means."}},{"itemId":"8340aa46-d576-5340-bae2-36d99cdbbed5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4ca5000b-ec90-530e-9dda-fc10030dbcf2","sourceKey":"bank:AMS101:AMS101-T397","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about how organizational culture affects ethical behaviour is correct?","options":["Low tolerance for conflict leads to ethical behaviour.","A strong culture that values high ethical standards will support ethical behaviour.","Tolerance for conflict is linked to unethical behaviour.","A culture high in control tends to encourage unethical behaviour."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A strong culture has a big influence on how people act, so when that culture holds high ethical standards it pushes managers and employees toward ethical behaviour. Options A, C and D get the link backwards, because cultures that support ethics tend to be high, not low, in tolerance for conflict, and high control does not push people toward unethical acts."}},{"itemId":"632e9bb9-4378-521f-bd10-0aea1563d666","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"382735d8-cedc-5aae-bada-b24b665b851c","sourceKey":"bank:AMS101:AMS101-T398","parentItemId":null,"revision":1,"payload":{"prompt":"As one of the factors that affect ethical behaviour, what does issue intensity refer to?","options":["the characteristics of the ethical issue itself","how much control and influence a person has over the event","how strong the organization's culture is","the structure of the organization"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Issue intensity is about the ethical issue itself, such as how much harm it causes and how many people agree it is wrong. Option B is closer to locus of control. Culture (C) and structure (D) are separate factors that also affect ethical behaviour, not issue intensity."}},{"itemId":"d2c0f105-3f59-55a1-b01d-74359c53ed22","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d7ba79c7-5fda-50ba-b677-37e6bf608e30","sourceKey":"bank:AMS101:AMS101-T399","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of the six factors used to judge issue intensity?","options":["How much harm (or benefit) does the act cause its victims (or beneficiaries)?","How likely is it that your act will be found out?","How much agreement is there that the act is evil (or good)?","How much time passes between the act and its expected consequences?"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The six factors of issue intensity are the size of the harm, the consensus that the act is wrong, the probability that harm will occur, how soon the consequences follow, how close you are to the victims, and how concentrated the effect is. Whether you will be caught is not one of them, so B is correct. Options A, C and D all describe genuine factors."}},{"itemId":"94f9e304-c7a6-534c-a077-06da71b5bd1e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f907163-6bc1-5997-90c6-3c9de8cb0d77","sourceKey":"bank:AMS101:AMS101-T401","parentItemId":null,"revision":1,"payload":{"prompt":"So that employees know what is expected of them when working in a foreign country, global organizations need to _______ their ethical guidelines.","options":["clarify","loosen","keep confidential","abandon"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Staff working abroad may meet local customs that differ from the company's standards, so global organizations need to clarify their ethical guidelines and spell out what is expected in the foreign setting. Option B, loosening the guidelines, would make expectations less clear, not more. Options C and D are wrong because guidelines that are hidden or dropped cannot tell employees anything."}},{"itemId":"3f6cfedf-e652-5e2c-aa1a-19b2f2cc4c01","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e8b7c34-1e2f-5504-a45a-7f2821705529","sourceKey":"bank:AMS101:AMS101-T403","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a way for management to reduce unethical behaviour?","options":["hiring people with high ethical standards","setting up codes of conduct","offering ethics training","listening in on employees' phone calls"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Monitoring employees' phone calls is not one of the recognised ways of encouraging ethics, and it can raise its own privacy concerns. Hiring people with high ethical standards (A), creating codes of conduct (B) and running ethics training (C) are all standard ways managers reduce unethical behaviour."}},{"itemId":"515f66d3-04d8-51f5-a8bc-e0849c394eda","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ff0ff905-0a30-5b36-b054-6a0fe821ce21","sourceKey":"bank:AMS101:AMS101-T404","parentItemId":null,"revision":1,"payload":{"prompt":"What do we call a formal document that sets out an organization's main values and the ethical rules it expects employees to follow?","options":["mission statement","statement of purpose","code of ethics","vision statement"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A code of ethics is a formal statement of an organization's primary values and the ethical rules employees are expected to follow. A mission statement (A) and statement of purpose (B) describe what the organization exists to do. A vision statement (D) describes what it wants to become."}},{"itemId":"006e1009-7d66-50cd-9fdf-b5af034510bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4b843bb-3e88-5ad1-b8d6-3a5591191fe9","sourceKey":"bank:AMS101:AMS101-T406","parentItemId":null,"revision":1,"payload":{"prompt":"In its simplest form, decision making is usually described as _______.","options":["deciding what is right","writing preferences down","making a choice among alternatives","processing information until it is complete"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"At its simplest, decision making means choosing from among two or more alternatives. Option A is tempting, but decisions are not always about right and wrong. Options B and D describe parts of thinking, not the act of deciding."}},{"itemId":"56d30248-6c5e-573f-91d9-1a4907583b47","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"923496fe-b19f-57ce-9e23-6957c4146b8c","sourceKey":"bank:AMS101:AMS101-T407","parentItemId":null,"revision":1,"payload":{"prompt":"Identifying a problem and decision criteria, weighting those criteria, developing, analysing and selecting an alternative, implementing it, and finally evaluating how effective the decision was: these eight steps make up the _______.","options":["decision-making process","managerial process","maximin style","bounded rationality approach"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"These eight steps, from identifying the problem to evaluating the decision's effectiveness, form the decision-making process. The managerial process (B) refers to functions like planning, organizing, leading and controlling. Maximin (C) is a choice under uncertainty, and bounded rationality (D) describes limits on rational decision making."}},{"itemId":"1c9dae77-8d37-5eac-834d-8c942afd1e03","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"adaeedd9-461b-5731-99d6-6ef1c5cc6102","sourceKey":"bank:AMS101:AMS101-T408","parentItemId":null,"revision":1,"payload":{"prompt":"A gap between the current state of affairs and the desired state of affairs is called a(n) _______.","options":["opportunity","solution","weakness","problem"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A problem is a discrepancy between where things are and where you want them to be. An opportunity (A) is a favourable situation to take advantage of, not a gap to close. A weakness (C) is an internal shortcoming, and a solution (B) is what fixes a problem."}},{"itemId":"32b248d7-9bc3-56b2-9416-4b3dc531c09f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d221d49-6ef0-5668-a45e-b17c1db2340c","sourceKey":"bank:AMS101:AMS101-T409","parentItemId":null,"revision":1,"payload":{"prompt":"Which step comes first in the decision-making process?","options":["developing decision criteria","allocating weights to the criteria","analysing alternatives","identifying a problem"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The process starts with identifying a problem, because you cannot make a decision until you know what needs solving. Developing criteria (A) is the second step, and weighting them (B) is the third. Analysing alternatives (C) comes later."}},{"itemId":"464ac62e-8a83-5a26-9db3-cc4589087a9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c623b0f6-fe0f-5e92-98a5-a2822723a03d","sourceKey":"bank:AMS101:AMS101-T410","parentItemId":null,"revision":1,"payload":{"prompt":"When identifying a problem, a manager _______.","options":["compares the current situation with the situation they want","waits for problems to be announced by flashing neon lights","searches for gaps that can be put off till later","does not act when under pressure to decide"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Identifying a problem means comparing the current state of affairs with some standard, such as past performance or goals, to see if there is a gap. Option B is wrong because problems rarely announce themselves clearly. Option D is backwards, since pressure to act is what turns a gap into a problem."}},{"itemId":"a0de7d91-81a5-57c6-8c0b-993088ae0a40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"489485f1-d0e2-52a2-b52e-0c89077de770","sourceKey":"bank:AMS101:AMS101-T411","parentItemId":null,"revision":1,"payload":{"prompt":"How are decision criteria selected?","options":["by twisting the data to support a chosen decision","by tossing a coin for a 50-50 chance of being right","by working out what is relevant to the decision","by looking at the differences between available opportunities"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Decision criteria are the factors that are relevant or important in making the decision, so selecting them means deciding what matters. Options A and B describe poor or random approaches. Option D is about comparing opportunities, not choosing criteria."}},{"itemId":"faecd18d-33e0-5b6d-9b08-540366c5e4dd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"606543c2-0ef9-5313-84dd-dbd2bd9bbec4","sourceKey":"bank:AMS101:AMS101-T413","parentItemId":null,"revision":1,"payload":{"prompt":"If all decision criteria are equally important, then weighting them _______.","options":["improves decisions when there are many criteria","is not needed","produces excellent decisions","improves the criteria"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Weighting is used to show that some criteria matter more than others. If every criterion is equally important, there is nothing to rank, so weighting is unnecessary. Options A, C and D assume weighting adds value even when all criteria are equal, which it does not."}},{"itemId":"aa86c34d-af1e-5238-a847-2b57a4e3ef6e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d26105f3-0625-5449-80b3-becdf7065e83","sourceKey":"bank:AMS101:AMS101-T415","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these must exist before the decision-making process can begin?","options":["plenty of time","pressure to act","a lack of authority","a lack of resources"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"For a gap to become a problem that starts the decision process, there must be pressure to act. Plenty of time (A) is not required. Options C and D are the opposite of what is needed, since managers need authority and resources to act."}},{"itemId":"5eebfc36-7dad-56e0-9086-9262a9fc028e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c02ac717-e8e8-51fb-b105-da2c89fcbbf6","sourceKey":"bank:AMS101:AMS101-T416","parentItemId":null,"revision":1,"payload":{"prompt":"To work out the _______, a manager has to decide what is relevant or important for solving the problem.","options":["geocentric behaviour required","number of alternatives allowed","weighting of decision criteria","decision criteria"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Decision criteria are the factors relevant or important to resolving the problem, so identifying them means deciding what matters. Weighting the criteria (C) is the next step, where you rank how important each criterion is. Options A and B are not about deciding what is relevant."}},{"itemId":"8c71848c-d876-5dae-b00c-7e19ba27e325","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"afe5f9eb-40dd-5662-a663-a9f4adccaf18","sourceKey":"bank:AMS101:AMS101-T417","parentItemId":null,"revision":1,"payload":{"prompt":"Which step of the decision-making process comes right after identifying the problem and the decision criteria?","options":["allocating weights to the criteria","analysing the alternatives","selecting the best alternative","implementing the alternative"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"After identifying the problem and the decision criteria, the next step is allocating weights to the criteria to show their relative importance. Analysing (B), selecting (C) and implementing (D) alternatives all come later in the process."}},{"itemId":"9d470570-265f-5049-9cc5-9b5b271780a0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6ea5852e-d7ff-5ac1-8a85-7786e4993f5e","sourceKey":"bank:AMS101:AMS101-T418","parentItemId":null,"revision":1,"payload":{"prompt":"What is a useful thing to remember when allocating weights to decision criteria?","options":["Every weight must be the same.","The weights must add up to 1.0.","Every criterion, whatever its importance, must get some weight.","Give the most important criterion a score, then weight the others against that standard."],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A simple method is to give the most important criterion a score, such as 10, and then weight the other criteria relative to it. Option A defeats the purpose of weighting. Option B is not required by this method, and option C is unnecessary since the criteria chosen are already the relevant ones."}},{"itemId":"f060a591-35ab-5adb-90e2-e701c0b77abe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc4b6921-36e1-5e7c-b8ee-3a0e84d376c9","sourceKey":"bank:AMS101:AMS101-T419","parentItemId":null,"revision":1,"payload":{"prompt":"When analysing alternatives in the decision-making process, each alternative is appraised against the _______.","options":["personal goals of the decision maker","criteria","assessed values","implementation plan"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Each alternative is judged against the decision criteria set earlier, using the weights given to them. Option A is wrong because the analysis is meant to use the agreed criteria, not personal goals. The implementation plan (D) comes after an alternative is chosen."}},{"itemId":"4ce5f2b4-5dba-555b-94e9-00d3ed3802aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"41c3598f-a265-5543-8f3a-0823c79b0249","sourceKey":"bank:AMS101:AMS101-T420","parentItemId":null,"revision":1,"payload":{"prompt":"How is an alternative selected in the decision-making process?","options":["by picking the alternative with the highest score","by picking the one you like most","by picking the alternative with the lowest price","by picking the most reliable alternative"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"After the alternatives are scored against the weighted criteria, you choose the one with the highest total score. Option B relies on personal liking rather than analysis. Price (C) and reliability (D) may be criteria, but each is only one factor, not the whole basis for choosing."}},{"itemId":"c9b7aa3f-8d1e-5e3c-8f34-34db3d55ff55","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dafce21f-f490-53f0-b04d-95f4e47660fc","sourceKey":"bank:AMS101:AMS101-T421","parentItemId":null,"revision":1,"payload":{"prompt":"_______ involves communicating a decision to the people affected by it and winning their commitment to it.","options":["Selecting an alternative","Evaluating decision effectiveness","Implementing the alternative","Analysing alternatives"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Implementation means putting the decision into action, which includes telling those affected and getting them committed to it. Selecting an alternative (A) is the choice itself, before anyone is told. Evaluation (B) happens after implementation, and analysis (D) happens before the choice."}},{"itemId":"619e11da-c925-5f4d-aedc-4bde73342a8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"35b936b8-fcc4-5775-a500-332b185d1c36","sourceKey":"bank:AMS101:AMS101-T422","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these helps a manager implement a chosen alternative effectively?","options":["keeping the decision from those affected until it takes effect","double-checking the analysis for mistakes","letting the people affected by the outcome take part in the process","ignoring criticism of the chosen alternative"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"People who take part in making a decision are more likely to support it, so involving those affected makes implementation smoother. Option A does the opposite, because implementation means communicating the decision and winning commitment, which secrecy prevents. Double-checking the analysis (B) belongs before the choice, and ignoring criticism (D) weakens commitment."}},{"itemId":"cd533b65-ee75-5887-b5dd-5b003263e3fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a62a035e-1b03-597e-b4bc-6552e0d8526e","sourceKey":"bank:AMS101:AMS101-T423","parentItemId":null,"revision":1,"payload":{"prompt":"What is the final step of the decision-making process?","options":["identifying the problem","evaluating how effective the decision was","identifying decision criteria","selecting an alternative that can solve the problem"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The process ends by evaluating the decision's effectiveness, checking whether it solved the problem. Identifying the problem (A) is the first step and identifying criteria (C) is the second. Selecting an alternative (D) happens before implementation and evaluation."}},{"itemId":"7856b6ad-3f63-5a1a-a88a-164ac3dec0f5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c7d943a-e59f-59f5-b2a3-4131fc636e1c","sourceKey":"bank:AMS101:AMS101-T424","parentItemId":null,"revision":1,"payload":{"prompt":"When evaluating the effectiveness of a decision, what is important to keep in mind?","options":["ignore any criticism of the decision process","you may need to go back and start the whole process again","restart the process if the decision is under 50 percent effective","ninety percent of decision problems happen at the implementation step"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"If the evaluation shows the problem still exists, the manager may need to go back through the steps, even starting over. Option A is unhelpful, because criticism can show what went wrong. Options C and D state made-up rules and figures that are not part of the process."}},{"itemId":"47139fbf-9ac3-5914-861f-88339f1d240e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bbb57119-93f3-5efa-94de-ff424b1b37ae","sourceKey":"bank:AMS101:AMS101-T425","parentItemId":null,"revision":1,"payload":{"prompt":"Managers are assumed to be _______, meaning they make consistent choices that maximize value within set limits.","options":["rational","leaders","organized","satisficers"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Rational decision making means making consistent, value-maximizing choices within given constraints. Satisficers (D) are the opposite, since they accept a 'good enough' choice instead of the best one. Being leaders (B) or organized (C) does not describe this kind of choice."}},{"itemId":"b46723dd-c171-5685-ae79-b198223a339c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3c916449-a103-5c67-b404-ce17c8e11db6","sourceKey":"bank:AMS101:AMS101-T426","parentItemId":null,"revision":1,"payload":{"prompt":"A perfectly rational decision maker is assumed to _______.","options":["not follow rational assumptions","not aim to maximize value","make inconsistent decisions","be objective and logical"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A perfectly rational decision maker is fully objective and logical, defining the problem carefully and choosing the alternative that gives the best result. Options A, B and C all describe the opposite of rationality."}},{"itemId":"c0a34a23-5a0b-54fe-a1d5-5f5051355157","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"41cd6dca-4140-5d66-94da-6a8ef4cd5d8a","sourceKey":"bank:AMS101:AMS101-T427","parentItemId":null,"revision":1,"payload":{"prompt":"Rational decision making assumes managers make decisions in the organization's best _______ interests.","options":["economic","pay-off","statistical","budgetary"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Rationality assumes decisions are made in the best economic interests of the organization, not the manager's personal interests. Budgetary (D) is narrower, covering only the budget. Pay-off (B) and statistical (C) do not describe the interests being served."}},{"itemId":"daad100b-3516-59c7-8b9c-4e2eda8fdfdc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"884c2d19-c005-5e4e-a04b-b409d6b91a6e","sourceKey":"bank:AMS101:AMS101-T428","parentItemId":null,"revision":1,"payload":{"prompt":"Managers are able to make rational decisions when _______.","options":["the problem is simple","the goals are clear","there are only a few alternatives","all of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Rational decision making is realistic when the problem is simple, the goals are clear, and the alternatives are few, among other conditions. Since A, B and C are all such conditions, D is the correct answer."}},{"itemId":"b3dac4f1-e9e7-5d47-a724-b0d7b167d96c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9374419-b0fa-54b8-acd2-a594af5ecf21","sourceKey":"bank:AMS101:AMS101-T429","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT a valid assumption of rationality?","options":["The problem is clear and unambiguous.","There is a single, well-defined goal to achieve.","Preferences are clear.","Preferences keep changing."],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Rational decision making assumes preferences are clear and constant, so preferences that keep changing do not fit. Options A, B and C are all genuine assumptions of rationality."}},{"itemId":"cb39a35c-dc24-5e63-9038-e7c57c9c77f8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89ff1bc0-d533-5693-ba40-3dbee66ad54b","sourceKey":"bank:AMS101:AMS101-T430","parentItemId":null,"revision":1,"payload":{"prompt":"Under bounded rationality, managers build _______ models that capture the essential features of a problem.","options":["multiple","binding","interactive","simplified"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Because managers cannot process all the information about a problem, they build simplified models that keep only its key features. That is the core idea of bounded rationality. Multiple (A), binding (B) and interactive (C) models do not describe this simplifying."}},{"itemId":"d2e51edb-e094-56cd-ba06-94e66acc5762","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b95193fe-781f-5834-8062-cb2d69806138","sourceKey":"bank:AMS101:AMS101-T431","parentItemId":null,"revision":1,"payload":{"prompt":"Since managers cannot possibly analyse every piece of information about every alternative, they _______ instead of _______.","options":["maximize; satisfice","maximize; minimize","satisfice; minimize","satisfice; maximize"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Managers satisfice, accepting a solution that is good enough, instead of maximizing, which would mean finding the best possible solution. Option A reverses the two. Minimizing (B and C) is not the contrast being made."}},{"itemId":"9bdf7acd-a0aa-5ebf-a90c-839d6cd3da4f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ed91f64a-8d93-572d-a35a-9f8742722c6d","sourceKey":"bank:AMS101:AMS101-T432","parentItemId":null,"revision":1,"payload":{"prompt":"When managers step away from the full rational model and look for satisficing solutions, they are following the idea of _______.","options":["jurisprudence","bounded rationality","least-squared exemptions","self-motivated decisions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Bounded rationality means making decisions that are rational but limited by a person's ability to process information, which leads to satisficing. Jurisprudence (A) relates to law. Options C and D are not decision-making concepts."}},{"itemId":"32e9f782-8cb8-56d9-841d-96a41b7284af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4da74d71-f937-5d3f-b4d9-e57b682dbb25","sourceKey":"bank:AMS101:AMS101-T433","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of decision making settles for a solution that is 'good enough'?","options":["intuition","rationalization","maximizing","satisficing"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Satisficing means accepting a solution that is good enough rather than searching for the best one. Maximizing (C) is the opposite, aiming for the best possible choice. Intuition (A) is deciding from experience and feelings, which is a different idea."}},{"itemId":"5ca3f711-5fab-58d5-ba93-956e1336ad7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"38e6cf7a-1ea8-5a69-b6ff-ca591d59fe9e","sourceKey":"bank:AMS101:AMS101-T434","parentItemId":null,"revision":1,"payload":{"prompt":"Under perfect rationality a decision maker makes a _______ choice, while under bounded rationality she makes a _______ choice.","options":["minimizing; satisficing","satisficing; maximizing","maximizing; satisficing","maximizing; minimizing"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Perfect rationality aims for the best possible result, which is maximizing, while bounded rationality settles for good enough, which is satisficing. Option B reverses the two. Minimizing (A and D) is not part of this contrast."}},{"itemId":"525f85fb-893f-55db-a6f4-4fadcc72b254","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a800e902-7933-5062-a5b3-c90002f2c7f6","sourceKey":"bank:AMS101:AMS101-T435","parentItemId":null,"revision":1,"payload":{"prompt":"What is it called when a person increases their commitment to an earlier decision even though there is evidence it may have been wrong?","options":["economies of commitment","escalation of commitment","dimensional commitment","expansion of commitment"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Escalation of commitment is sticking with, and even increasing support for, a decision despite evidence that it was a mistake. Expansion of commitment (D) sounds similar but is not the recognised term. Options A and C are not decision-making concepts."}},{"itemId":"3e63edd3-16e2-5bd4-8d2a-8d3189339f81","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"36cda430-43b9-51b5-8f16-15916a01a314","sourceKey":"bank:AMS101:AMS101-T436","parentItemId":null,"revision":1,"payload":{"prompt":"Managers' decisions are strongly shaped by _______.","options":["the culture of the organization","internal politics","power considerations","all of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Real-world decisions are influenced by the organization's culture, its internal politics and considerations of power. Since A, B and C all apply, D is the correct answer."}},{"itemId":"e45e3a3b-5efc-5022-b6e1-c8b93a96168a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce8e651b-f8fe-5e22-bf50-231435e4b0b6","sourceKey":"bank:AMS101:AMS101-T437","parentItemId":null,"revision":1,"payload":{"prompt":"What is intuitive decision making?","options":["something not used in organizations","a conscious process based on accumulated judgment","making decisions based on experience, feelings and accumulated judgment","an important support for escalation of commitment"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Intuitive decision making means deciding on the basis of experience, feelings and accumulated judgment. Option B is close, but intuition is a subconscious process, not a conscious one. Option A is false because managers regularly use intuition."}},{"itemId":"329e65c2-e755-5112-9c38-48e9de0517b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1bdb406e-6307-57a4-bb84-6eb7d3e31002","sourceKey":"bank:AMS101:AMS101-T438","parentItemId":null,"revision":1,"payload":{"prompt":"Research on intuitive decision making has found that _______.","options":["managers do not make decisions based on feelings or emotions","managers use information from their subconscious mind to help them decide","rational thinking always works better than intuition","accumulated experience does not support intuitive decisions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Research shows managers draw on data from their subconscious mind when making decisions. Option A is wrong because feelings do play a part, and option D is wrong because experience is a key source of intuition. Option C overstates things, since intuition can complement rational analysis."}},{"itemId":"f78aa8d4-af6f-5d38-8744-1b43b1805e05","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78f3fecd-3e3c-51e9-8963-9f806330dae0","sourceKey":"bank:AMS101:AMS101-T439","parentItemId":null,"revision":1,"payload":{"prompt":"All of these are aspects of intuition EXCEPT _______.","options":["experience-based decisions","affect-initiated decisions","cognitive-based decisions","programmed decisions"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions are repetitive decisions handled by routine approaches like rules and procedures, so they are not a form of intuition. Experience-based (A), affect-initiated or feelings-based (B) and cognitive-based (C) decisions are all aspects of intuition."}},{"itemId":"4399d5a5-149e-5d4c-a19f-ccf3301a1700","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df23a179-936c-5f86-b6cd-35d5b8b1e69a","sourceKey":"bank:AMS101:AMS101-T440","parentItemId":null,"revision":1,"payload":{"prompt":"_______ are straightforward and familiar problems that are easy to define.","options":["Poorly structured problems","Structured problems","Unique problems","Nonprogrammed problems"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Structured problems are straightforward, familiar and easily defined, like a customer returning a faulty item. Poorly structured problems (A) are new or unusual, with incomplete information. Unique (C) and nonprogrammed (D) both describe the unfamiliar kind of situation."}},{"itemId":"b83a7cc4-c575-5014-8f5d-1fd428a9ecd8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b7265bc8-ff91-54fb-a9bd-78abd6b8e110","sourceKey":"bank:AMS101:AMS101-T441","parentItemId":null,"revision":1,"payload":{"prompt":"Structured problems go best with which type of decision making?","options":["programmed","satisficing","intuition","gut feeling"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Structured problems are familiar and repeat often, so they suit programmed decisions, which use routine approaches. Satisficing (B) is about settling for good enough. Intuition (C) and gut feeling (D) are more useful for unfamiliar situations."}},{"itemId":"f3b64aa8-ad15-591c-92f6-6f98c11190be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ec32c37-76fa-57cc-9222-24f7fc2f51af","sourceKey":"bank:AMS101:AMS101-T442","parentItemId":null,"revision":1,"payload":{"prompt":"The most efficient way of handling structured problems is through _______ decision making.","options":["linear","unique","focused","programmed"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions use routine solutions such as procedures, rules and policies, which makes them the most efficient way to deal with familiar, structured problems. Unique (B) describes nonprogrammed situations. Linear (A) and focused (C) are not types of decisions."}},{"itemId":"3395c8f2-6710-5a86-920a-319419e39bb6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a57561c7-c12b-5bd8-9ed9-ccf7c70051f6","sourceKey":"bank:AMS101:AMS101-T443","parentItemId":null,"revision":1,"payload":{"prompt":"_______ decision making is fairly simple and depends heavily on solutions used before.","options":["Nonprogrammed","Linear","Satisficing","Programmed"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions are repetitive and can be handled by a routine approach, so they rely heavily on previous solutions. Nonprogrammed decisions (A) are unique and need custom solutions. Satisficing (C) is about accepting a good-enough choice, not repeating past solutions."}},{"itemId":"859377f7-94bd-5e26-8006-b1b46e141830","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"23306781-b9d6-5886-a771-da35cc6a2444","sourceKey":"bank:AMS101:AMS101-T445","parentItemId":null,"revision":1,"payload":{"prompt":"A procedure _______.","options":["is an explicit statement of what a manager can or cannot do","is a series of related, sequential steps for responding to a structured problem","is a set of guidelines that channels a manager's thinking about a problem","gives a manager broad authority to make decisions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A procedure is a series of interrelated, sequential steps a manager follows to deal with a structured problem. Option A is the definition of a rule, which states what can or cannot be done. Option C describes a policy, which guides thinking but leaves room for judgment."}},{"itemId":"f63cf0b1-adcd-53e8-ada1-220cf830aff7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"040dfec4-b9a7-5553-b6bc-9cb2d5932964","sourceKey":"bank:AMS101:AMS101-T446","parentItemId":null,"revision":1,"payload":{"prompt":"A _______ is an explicit statement telling a manager what he or she may or may not do.","options":["procedure","policy","rule","solution"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A rule is an explicit statement of what a manager can or cannot do, such as 'no smoking in the warehouse'. A procedure (A) is a series of steps. A policy (B) is a general guideline that leaves room for interpretation."}},{"itemId":"9a52a5a1-a851-5831-9f08-1f03c4412a96","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39aa3c79-af95-52e6-9dcf-e0388d11e939","sourceKey":"bank:AMS101:AMS101-T448","parentItemId":null,"revision":1,"payload":{"prompt":"Which point shows the difference between a policy and a rule?","options":["a policy sets parameters","a rule sets parameters","a policy is more explicit","a rule is more ambiguous"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A policy sets general parameters for the decision maker, while a rule says exactly what to do. Option B gives this feature to the wrong one. Options C and D are also reversed, because rules are more explicit and policies are more ambiguous."}},{"itemId":"b16e98b6-d507-5686-bd12-2fa78deacda9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f579fe0c-7a9f-5b7f-aa32-48406b0c7005","sourceKey":"bank:AMS101:AMS101-T449","parentItemId":null,"revision":1,"payload":{"prompt":"A _______ usually contains an ambiguous term that leaves interpretation to the decision maker.","options":["system","rule","solution","policy"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A policy uses general terms, such as 'reasonable' or 'competitive', so the person applying it must interpret what they mean. A rule (B) is explicit and leaves little room for interpretation. A system (A) and solution (C) are not decision guidelines of this kind."}},{"itemId":"162bc6cc-ccbf-599b-b376-eeee4778c99e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a7ea4b32-9968-50ec-b076-44187b564ebe","sourceKey":"bank:AMS101:AMS101-T450","parentItemId":null,"revision":1,"payload":{"prompt":"A business school states that it \"aims to build productive relationships with organizations in its community.\" This statement is an example of a _______.","options":["rule","policy","procedure","commitment"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"This statement gives general direction but contains an open term, 'productive', that leaves interpretation to the decision maker, which is typical of a policy. A rule (A) would state exactly what can or cannot be done. A procedure (C) would list steps to follow."}},{"itemId":"815b1505-ff87-5cff-b8d6-d1430c411737","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9dd1abf-b364-5f5b-8bca-daba4ca1fa69","sourceKey":"bank:AMS101:AMS101-T451","parentItemId":null,"revision":1,"payload":{"prompt":"Poorly structured problems _______.","options":["are easy to solve","involve new or unusual circumstances","make managers work with incomplete or ambiguous information","b and c"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Poorly structured problems are new or unusual, and the information about them is often incomplete or unclear. Since both B and C are true, D is the correct answer. Option A is false, because these problems are harder, not easier."}},{"itemId":"9352cbec-9e2e-5772-ba05-c4d79b336c64","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9fdabc86-85f5-5f12-bb40-6fc66cba5fbf","sourceKey":"bank:AMS101:AMS101-T452","parentItemId":null,"revision":1,"payload":{"prompt":"Nonprogrammed decisions are best described as _______.","options":["recurring but hard to make","very similar to problems elsewhere in the organization","requiring more aggressive effort from the decision maker's thinking","unique and nonrecurring"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Nonprogrammed decisions are unique and nonrecurring, so they need a custom-made solution. Option A is wrong because recurring problems are handled with programmed decisions. Option B is also wrong, since familiar, similar problems are the structured kind."}},{"itemId":"4eb33679-8af3-599e-8cf3-52885ce3cfc2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"daf80157-cd1e-50d9-865e-832df94f12a1","sourceKey":"bank:AMS101:AMS101-T453","parentItemId":null,"revision":1,"payload":{"prompt":"When problems are _______, managers have to rely on _______ to come up with unique solutions.","options":["well structured; nonprogrammed decision making","well structured; pure intuition","poorly structured; nonprogrammed decision making","poorly structured; programmed decision making"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Poorly structured problems are new and unusual, so managers use nonprogrammed decision making to create unique solutions. Options A and B pair the wrong problem type, since well-structured problems are handled with programmed decisions. Option D pairs poorly structured problems with routine solutions, which does not work."}},{"itemId":"c1803639-e360-52bd-aa16-4a056caf68a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"019a733a-ddda-5572-be1c-93175b742b80","sourceKey":"bank:AMS101:AMS101-T454","parentItemId":null,"revision":1,"payload":{"prompt":"Which word is linked with nonprogrammed decisions?","options":["unique","recurring","routine","repetitive"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Nonprogrammed decisions deal with unique situations that need custom solutions. Recurring (B), routine (C) and repetitive (D) all describe programmed decisions."}},{"itemId":"bb8794eb-814e-5689-99c8-1bcfdd340bc6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c5ab253-a3f7-5d48-9b8f-b2b53a5eb775","sourceKey":"bank:AMS101:AMS101-T455","parentItemId":null,"revision":1,"payload":{"prompt":"What kind of decisions do lower-level managers usually face?","options":["unique","nonroutine","programmed","nonprogrammed"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Lower-level managers mostly deal with familiar, repeating problems, which they handle with programmed decisions. Unique (A), nonroutine (B) and nonprogrammed (D) decisions are more typical at top management, where problems are less structured."}},{"itemId":"3f5094ec-98df-5422-b489-88a82bfe9da4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7afd8606-3dc9-56bf-a9da-25a5096087c2","sourceKey":"bank:AMS101:AMS101-T456","parentItemId":null,"revision":1,"payload":{"prompt":"Lower-level managers handle well-structured problems using rules and procedures. What is this relationship between problem types, decision types and organizational level called?","options":["preprogramming","focused decision making","integration","separation"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The way problem type, decision type and management level fit together is described as integration: well-structured problems and programmed decisions sit mostly at lower levels, while poorly structured problems and nonprogrammed decisions sit at the top. Separation (D) suggests they are unrelated, which is the opposite idea. Preprogramming (A) and focused decision making (B) are not the term used for this relationship."}},{"itemId":"919e1b50-6759-5850-ba4f-6e7aed29ec90","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83ab5b2f-183d-5c16-9937-ffb973446304","sourceKey":"bank:AMS101:AMS101-T457","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these people is likely to make the most programmed decisions?","options":["the chief executive of a multinational beverage company","the vice president of a car manufacturer's luxury division","the head of the juice division of a large soft drinks company","the manager of a single local fast-food outlet"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The manager of one fast-food outlet is a lower-level manager who deals with routine, repeating problems, so most of their decisions are programmed. The chief executive (A) faces the most unique, nonprogrammed decisions. Division heads (B and C) are senior managers who also deal with many unstructured problems."}},{"itemId":"92e591bc-c8b4-5a79-b6dd-56a838a6275a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f1b6b180-cfa1-5358-8620-a530d6cfffae","sourceKey":"bank:AMS101:AMS101-T458","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly describes how programmed decisions affect organizations?","options":["They maximize managers' need to use discretion.","They reduce the need for costly managerial talent.","They increase how much judgment managers must use.","They reduce organizational efficiency."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Because programmed decisions use set rules and procedures, they reduce the need for expensive, highly skilled managers to handle every decision. Options A and C are reversed, since programmed decisions reduce discretion and judgment. Option D is wrong because they actually improve efficiency."}},{"itemId":"d2c0c851-857d-5c06-93b2-045f24c8bf2e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"955f9158-6efb-5538-ab20-9069bd1d9c2b","sourceKey":"bank:AMS101:AMS101-T460","parentItemId":null,"revision":1,"payload":{"prompt":"Someone who knows the price of three similar cars at three different dealers is deciding under which condition?","options":["risk","uncertainty","certainty","factual"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Since the prices of all three cars are known, the outcome of each choice is known, which is a condition of certainty. Risk (A) would mean only probabilities could be estimated. Uncertainty (B) would mean not even probabilities are known, and 'factual' (D) is not a decision condition."}},{"itemId":"fdbcab2f-ad37-560a-89f3-c69fbc93a717","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c699fde9-7a57-5959-b164-34e0ee813600","sourceKey":"bank:AMS101:AMS101-T461","parentItemId":null,"revision":1,"payload":{"prompt":"Nonprogrammed decisions are usually made under conditions of _______.","options":["certainty","low levels of risk","uncertainty","reliability"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Nonprogrammed decisions deal with new and unusual problems, where outcomes and even probabilities are often unknown, which is uncertainty. Certainty (A) and low risk (B) fit familiar, structured problems better. Reliability (D) is not a decision condition."}},{"itemId":"ea5c7f76-4998-5682-9c67-a5bf73c7bd12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa40755c-3fe0-5f09-b005-6de520dd060e","sourceKey":"bank:AMS101:AMS101-T462","parentItemId":null,"revision":1,"payload":{"prompt":"The use of _______ improves organizational efficiency.","options":["programmed decisions","nonprogrammed decisions","less planning","lower expectations and demands from top managers"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions apply ready-made rules and procedures, which saves time and effort and so improves efficiency. Nonprogrammed decisions (B) take more time because each solution is custom-made. Less planning (C) and lower expectations (D) do not improve efficiency."}},{"itemId":"0b8be257-57c6-5465-81fe-c734af51ff00","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc61a6d1-fd65-5c45-9bf2-a9b1dbf734e4","sourceKey":"bank:AMS101:AMS101-T463","parentItemId":null,"revision":1,"payload":{"prompt":"A manager of a clothing shop in Lagos uses last rainy season's sales to estimate how much stock to order for this rainy season. Which decision-making condition is she operating under?","options":["seasonal","risk","uncertainty","certainty"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Risk is a condition where the decision maker can estimate the likelihood of outcomes, often from past data, as this manager does with last season's sales. Certainty (D) would require knowing exactly how much will sell. Uncertainty (C) would mean having no reasonable probability estimates, and 'seasonal' (A) is not a decision condition."}},{"itemId":"be40181a-3696-5f83-9e67-5dab47817e82","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4c38439a-bd7d-5d81-8fac-9bf19cdf28d1","sourceKey":"bank:AMS101:AMS101-T464","parentItemId":null,"revision":1,"payload":{"prompt":"_______ is a situation in which the decision maker has neither certainty nor reasonable probability estimates.","options":["Certainty","Risk","Uncertainty","Maximax"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Under uncertainty, the decision maker does not know the outcomes and cannot even estimate their probabilities. Risk (B) is different because probabilities can be estimated. Maximax (D) is a choice approach used under uncertainty, not the condition itself."}},{"itemId":"522ca7ce-9fa7-5cec-b56a-04a03aa05144","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f95eb8dc-d317-508f-a1f6-d4942cb7565e","sourceKey":"bank:AMS101:AMS101-T465","parentItemId":null,"revision":1,"payload":{"prompt":"A person puts all their money on the long-shot option in a betting game because it offers the biggest possible win. What kind of choice is this?","options":["maximax","maximin","minimax","minimin"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A maximax choice goes for the alternative with the largest possible payoff, which is exactly what betting everything on the long shot does. Maximin (B) would choose the option with the best worst-case result. Minimax (C) aims to reduce the maximum regret."}},{"itemId":"61c44927-fc0b-552d-83ce-b9115571d0c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab3c2463-49ad-5e42-9675-71c7315b163d","sourceKey":"bank:AMS101:AMS101-T466","parentItemId":null,"revision":1,"payload":{"prompt":"Which term describes 'maximizing the minimum possible payoff'?","options":["maximax","maximin","minimax","minimin"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Maximin means looking at the worst possible payoff of each option and choosing the one whose worst case is best. Maximax (A) chooses the largest possible payoff. Minimax (C) minimizes the maximum regret."}},{"itemId":"3c881cbd-4f4a-5aa2-80f4-0c40cc9239b0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0c8f3fa-8c2a-5106-9f6a-9e22fff3f82a","sourceKey":"bank:AMS101:AMS101-T467","parentItemId":null,"revision":1,"payload":{"prompt":"A person who makes a 'maximin' choice under uncertainty has what kind of psychological orientation?","options":["optimist","realist","pessimist","satisficer"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A maximin chooser focuses on the worst outcomes and tries to make them as good as possible, which reflects a pessimistic outlook. An optimist (A) would use maximax. A satisficer (D) is someone who accepts a good-enough solution, which is a different idea."}},{"itemId":"59c754e6-b6d3-5579-9bbc-8cef7ecdf1e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d28aa3e7-a566-5327-877f-2f1880e71923","sourceKey":"bank:AMS101:AMS101-T468","parentItemId":null,"revision":1,"payload":{"prompt":"Which psychological orientation best fits a person making a 'maximax' choice?","options":["optimist","realist","pessimist","satisficer"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A maximax chooser picks the option with the highest possible payoff, expecting the best to happen, which is an optimistic outlook. A pessimist (C) would use maximin instead, protecting against the worst outcome. A satisficer (D) is someone who accepts a good-enough solution, which is not a choice rule under uncertainty."}},{"itemId":"4dd7fdf6-988e-5af8-afac-1cea04b1d88d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f5c4eeab-6d2d-5c87-ae2c-bb5df7caf750","sourceKey":"bank:AMS101:AMS101-T469","parentItemId":null,"revision":1,"payload":{"prompt":"An optimistic manager using a maximax approach will _______.","options":["maximize the maximum payoff","maximize the minimum payoff","minimize the maximum regret","minimize the minimum regret"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Maximax means choosing the option that offers the highest possible payoff, which suits an optimist. Option B describes maximin, the pessimist's choice. Option C describes minimax, which aims to reduce regret."}},{"itemId":"90877198-3392-5bfa-af04-8102b262a2a2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"44ea5ddc-1304-5612-9495-62847178043d","sourceKey":"bank:AMS101:AMS101-T470","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who wants to minimize his or her maximum 'regret' will make a _______ choice.","options":["maximax","maximin","minimax","minimin"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A minimax choice aims to minimize the maximum regret, the amount you would lose by not picking the best option. Maximax (A) chases the biggest payoff, and maximin (B) protects against the worst payoff."}},{"itemId":"80b256f6-dd10-586f-9bd7-24821a9948f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d16e9c53-4611-57aa-8f4c-36ff1c03754e","sourceKey":"bank:AMS101:AMS101-T471","parentItemId":null,"revision":1,"payload":{"prompt":"All of these are decision-making styles EXCEPT _______.","options":["directive","egotistical","analytic","conceptual"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The four decision-making styles are directive, analytic, conceptual and behavioural. 'Egotistical' is not one of them, so B is correct. Directive (A), analytic (C) and conceptual (D) are all genuine styles."}},{"itemId":"65058f85-5ef6-5d52-8721-d89790b17f39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5c5353b3-8a9f-55db-a474-4c301a2a3df1","sourceKey":"bank:AMS101:AMS101-T472","parentItemId":null,"revision":1,"payload":{"prompt":"Planning means defining the organization's goals, setting an overall strategy for reaching them, and developing a full set of plans _______.","options":["showing which shift will do which tasks","to decide which manager will head which department","to integrate and coordinate the organization's work","to set the quality and quantity of work to be done"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The full set of plans exists to integrate and coordinate the work of the organization so everyone moves toward the same goals. Option A is a scheduling detail, and option B is an organizing decision about who heads what. Option D is closer to setting standards for controlling."}},{"itemId":"3da13933-50a0-549d-af9b-6906309716da","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5223c957-5539-5be7-8036-de22deffcc68","sourceKey":"bank:AMS101:AMS101-T473","parentItemId":null,"revision":1,"payload":{"prompt":"Informal planning is _______.","options":["carried out at the lowest level of the organization","general and lacking in continuity","worked out in casual meetings at a holiday resort","specific and developed by middle managers for their units"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Informal planning is general and lacks continuity, often existing only in the manager's head. Option D describes something specific, which is a feature of formal planning. Options A and C wrongly tie informal planning to a particular level or location."}},{"itemId":"53fe0534-005e-5ff1-bc59-4bbb8a3db7f3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"161193da-c362-5130-8ccc-381e56859f23","sourceKey":"bank:AMS101:AMS101-T474","parentItemId":null,"revision":1,"payload":{"prompt":"In formal planning, _______.","options":["specific goals covering a period of years are defined","specific goals are set but not written down","general goals are set but not written down","general goals covering an unstated number of years are defined"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Formal planning defines specific goals that cover a set period of years, and these goals are written down and shared. Options B and C are wrong because formal plans are written. Option D describes general goals over an unclear period, which is more like informal planning."}},{"itemId":"916e4406-094b-5b3d-b116-b5a38c58c2bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa7d1c19-c983-51dc-80c8-d7afa801f1c8","sourceKey":"bank:AMS101:AMS101-T475","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a feature of formal planning?","options":["setting general objectives","planning for one year or less","writing down objectives","keeping the plan only in the manager's head"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"In formal planning, objectives are written down and shared with members of the organization. Option A is wrong because formal planning sets specific objectives, not general ones. Option D describes informal planning, and option B is wrong because formal plans often cover several years."}},{"itemId":"5fa4a355-d11b-54d5-a4c4-aabf335f261e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14a20299-821d-5ed8-92bc-19339328a048","sourceKey":"bank:AMS101:AMS101-T476","parentItemId":null,"revision":1,"payload":{"prompt":"In informal planning, _______ sharing of goals with others in the organization.","options":["everything may be written down, but there is little or no","everything is written down, and there is","nothing is written down, and there is little or no","nothing is written down, so management does a lot of"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"In informal planning, nothing is written down and the goals are rarely, if ever, shared with others. Options A and B are wrong because writing things down is a feature of formal planning. Option D is wrong because informal planning does not involve much sharing."}},{"itemId":"6ecd405f-676b-52f4-9434-0f4af5698ee1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"19289b24-0374-55e4-8492-9094b5ebcc79","sourceKey":"bank:AMS101:AMS101-T477","parentItemId":null,"revision":1,"payload":{"prompt":"Planning gives direction, lessens the impact of change, reduces waste and duplication, and _______.","options":["sets the workload for each department","provides the basis for promoting individuals","removes departments the plan shows are unnecessary","sets the standards used in controlling"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Planning sets the goals and plans that become the standards managers use when controlling, by comparing actual performance against them. Option A is about scheduling work, and option B is about staffing decisions. Option C is not one of the purposes of planning."}},{"itemId":"28127e24-43e9-58b2-a334-814e871ab472","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b97f281e-870c-5a70-ad27-26af5b0861dc","sourceKey":"bank:AMS101:AMS101-T478","parentItemId":null,"revision":1,"payload":{"prompt":"Planning cannot get rid of change. Managers plan so that they can _______.","options":["be ready when the top management changes","anticipate changes and develop the most effective response to them","decide what to do after the environment changes","have the right materials ready when demand for them arises"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning helps managers look ahead, anticipate changes and work out the most effective way to respond. Option C is tempting, but deciding only after the change happens is reacting, not planning. Options A and D are too narrow to describe why managers plan."}},{"itemId":"d8596aa0-838c-5782-a8b5-6588a598e999","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c0354d1-7368-52e0-8361-9588a32875b3","sourceKey":"bank:AMS101:AMS101-T479","parentItemId":null,"revision":1,"payload":{"prompt":"Planning affects managers by forcing them to _______.","options":["react to change","think about the impact of change","respond without careful thought","build bureaucratic response models"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning makes managers look ahead and consider the impact of change before it happens. Reacting to change (A) is what happens without planning. Responding without thought (C) and building bureaucratic models (D) are not effects of planning."}},{"itemId":"daa69762-be29-5abb-a881-3582e5acdbb4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00af930c-0aa3-53bf-8a74-e1d968f7939b","sourceKey":"bank:AMS101:AMS101-T481","parentItemId":null,"revision":1,"payload":{"prompt":"Research on performance in organizations that plan has reached _______.","options":["somewhat negative conclusions about the benefits of planning","generally mixed conclusions about the benefits of planning","generally negative conclusions about the benefits of planning","generally positive conclusions about the benefits of planning"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Overall, studies have generally found that planning is linked to better performance, so the conclusions are positive. Option B is tempting because planning does not always lead to higher performance, but the overall picture is still positive. Options A and C contradict the findings."}},{"itemId":"49cbeaa7-29d1-5760-be8a-21af20d6f064","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"735442af-d144-590e-be3f-d976b57a5b4c","sourceKey":"bank:AMS101:AMS101-T482","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with the extent of planning, the quality of the planning process and proper implementation of plans probably _______.","options":["add far less to high performance than the extent of planning does","add more to high performance than the extent of planning does","add less to high performance than the extent of planning does","need more study to establish which adds the most"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Doing planning well and carrying out the plans properly matter more for high performance than simply how much planning is done. Options A and C reverse this finding. Option D ignores the conclusion that quality and implementation matter more."}},{"itemId":"b5791879-d2af-516f-8e64-c1e7d2747edf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"09f2ff88-4ac0-5740-849e-bf7f3a9f704c","sourceKey":"bank:AMS101:AMS101-T483","parentItemId":null,"revision":1,"payload":{"prompt":"Government regulations, powerful labour unions and other critical environmental forces limit managers' options and _______.","options":["reduce the impact of planning on an organization's performance","increase the impact of planning on an organization's performance","cancel out the impact of planning on an organization's performance","have no effect on the impact of planning on an organization's performance"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"When outside forces limit what managers can do, planning has less effect on how well the organization performs. Option C goes too far, since planning still has some effect. Options B and D also contradict this finding."}},{"itemId":"e7811a66-5a4f-5bc6-ab71-75382abd0f28","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"32b91da0-082c-5081-912d-c14fe3572f85","sourceKey":"bank:AMS101:AMS101-T484","parentItemId":null,"revision":1,"payload":{"prompt":"In studies where formal planning did not lead to better performance, _______.","options":["the external environment was often to blame","poor execution of plans by management was usually the cause","poor implementation by employees was the main cause","lack of communication was usually the cause"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Where formal planning did not improve performance, the external environment was often the reason, for example sudden government regulation or economic shocks. Options B, C and D point to internal causes, which were not the main reason found."}},{"itemId":"b6954c57-dd21-5fc7-8a62-2c2b273e7427","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b82000df-1364-514c-b4e9-a228d40272aa","sourceKey":"bank:AMS101:AMS101-T485","parentItemId":null,"revision":1,"payload":{"prompt":"Planning is often called the primary management function because it _______.","options":["provides some basis for future decision making","creates the vision members of the organization work toward","lays the foundation for all the other functions","sets the tone for the organization's culture"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Planning is called the primary function because organizing, leading and controlling all build on the goals and plans it sets. Option A is true in part, but it does not explain why planning comes first. Options B and D are narrower effects, not the reason it is primary."}},{"itemId":"518d5681-d572-5bb6-86a0-26b7d7cc15af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ced04456-e2b3-54d7-8f40-0efd9ca88d96","sourceKey":"bank:AMS101:AMS101-T486","parentItemId":null,"revision":1,"payload":{"prompt":"Planning involves which two key elements?","options":["goals and decisions","goals and plans","plans and decisions","goals and actions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning is built on goals, which are the desired outcomes, and plans, which are documents showing how the goals will be met. Decisions (A and C) and actions (D) are part of carrying out planning, but they are not its two core elements."}},{"itemId":"3c7de503-3760-5ea2-a64e-c50543b90384","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c920be29-6d73-522b-ac46-0a5ab78bc1bf","sourceKey":"bank:AMS101:AMS101-T488","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about an organization's stated objectives is true?","options":["They give the same objectives to all groups.","Organizations usually have one set of internal objectives and one set of external objectives.","They may give different objectives to stockholders, customers, employees and the public.","Stated objectives usually match short-term actions."],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Organizations often present different stated objectives to different groups, such as shareholders, customers, employees and the public. Option A is the opposite of this. Option D is wrong because stated objectives often do not match what the organization actually does, which is why real goals can differ."}},{"itemId":"38d28a8d-08c1-524f-bdb0-fe4498db742e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5cfa709d-b34b-58d8-a34e-bd2bec3dd7e0","sourceKey":"bank:AMS101:AMS101-T489","parentItemId":null,"revision":1,"payload":{"prompt":"What should someone do to find out an organization's real objectives?","options":["watch what members of the organization actually do","attend the shareholders' annual general meeting","read the annual report","watch news reports on television"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Real goals are revealed by what people in the organization actually do, so observing their actions is the best guide. The annual meeting (B), annual report (C) and news reports (D) mostly present stated goals, which may differ from real ones."}},{"itemId":"fe255afe-a76a-584a-bee2-53f25544672a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d6facc1-9c90-5aca-9fc8-98d016746098","sourceKey":"bank:AMS101:AMS101-T490","parentItemId":null,"revision":1,"payload":{"prompt":"Classifying plans as directional or specific means we are classifying them by _______.","options":["breadth","specificity","frequency of use","depth"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Directional versus specific is a contrast in how detailed a plan is, so it is classification by specificity. Breadth (A) is about strategic versus operational plans. Frequency of use (C) is about single-use versus standing plans."}},{"itemId":"f3c77dab-d210-521a-8d8e-dcc1bf041853","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"17424b7b-4917-578a-963d-3b8c80f8c61a","sourceKey":"bank:AMS101:AMS101-T491","parentItemId":null,"revision":1,"payload":{"prompt":"Classifying plans as single-use or standing means we are classifying them by _______.","options":["breadth","specificity","frequency of use","time frame"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Single-use plans are made for one-off situations, while standing plans are ongoing and used repeatedly, so this is classification by frequency of use. Specificity (B) is about directional versus specific plans, and time frame (D) is about long-term versus short-term plans."}},{"itemId":"34fca836-d0f4-5db0-81e4-1b7ddf7f373f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d8093d1d-d1b2-547b-835c-c8ef3b16d233","sourceKey":"bank:AMS101:AMS101-T492","parentItemId":null,"revision":1,"payload":{"prompt":"A state government plan to raise the tax on tobacco sales by 2.45 percent over the next 2 years is what type of plan?","options":["strategic","operational","specific","directional"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The plan has a clearly defined objective, an exact percentage over an exact period, with no room for interpretation, so it is a specific plan. A directional plan (D) would only give general guidelines. Strategic (A) and operational (B) describe the breadth of a plan, not how detailed it is."}},{"itemId":"f775d1ca-4cb7-501d-aa9f-3a51d6a65bb9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4e972b7-a164-55a5-849a-c052a6f8fe13","sourceKey":"bank:AMS101:AMS101-T495","parentItemId":null,"revision":1,"payload":{"prompt":"A city's policy on skateboarding on downtown pavements, which guides how police should act, is what type of plan?","options":["standing","contingency","directional","single use"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A policy like this is applied again and again whenever the situation comes up, so it is a standing plan. A single-use plan (D) is for a one-time situation. Directional (C) describes specificity, not frequency of use."}},{"itemId":"6513031a-623c-568c-967a-11fc7a48146a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0baed15-ffe6-56f3-8d0a-fd04df36bd0b","sourceKey":"bank:AMS101:AMS101-T497","parentItemId":null,"revision":1,"payload":{"prompt":"In traditional goal setting, what tends to happen to goals as they are passed from top management down to the lower levels of the organisation?","options":["They become less clear and less unified","They bring the whole workforce together","Lower-level managers have to keep revising and correcting them","They are deliberately kept vague and general"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"As goals move down the hierarchy in traditional goal setting, each level interprets them in its own way, so they lose clarity and unity by the time they reach the bottom. Option B is the opposite of what happens. Option C sounds plausible, but the problem is distortion through interpretation, not constant correction, and option D wrongly suggests the vagueness is intentional."}},{"itemId":"9dbe0ecf-0350-5121-9cd7-4a6cfd1039ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd10a7d2-815a-58a7-8559-1d6c0d2a604b","sourceKey":"bank:AMS101:AMS101-T498","parentItemId":null,"revision":1,"payload":{"prompt":"How do the terms 'goals' and 'objectives' relate to each other in management?","options":["They mean the same thing and are used interchangeably","Goals are long-term while objectives are short-term","Top management uses goals while first-level managers use objectives","Goals concern profits while objectives concern production output"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Goals and objectives both mean desired outcomes for individuals, groups or the whole organisation, so in management the two words are used interchangeably. Option B is a common everyday distinction, but the terms are not split by time horizon here. Options C and D invent differences based on management level or subject area that do not exist."}},{"itemId":"b358f425-9742-5d95-9cfd-c54b91fc528a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"142e9ae6-12e6-5d38-82ca-151df0b55164","sourceKey":"bank:AMS101:AMS101-T499","parentItemId":null,"revision":1,"payload":{"prompt":"Besides showing how goals will be met, plans are documents that ___________.","options":["state which department holds which responsibilities for reaching the goals","list the materials and processes needed to achieve the goals","show how much capital is needed to complete the goals","set out resource allocations, schedules and other actions needed to achieve the goals"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A plan explains how goals will be reached and describes the resource allocations, schedules and other actions required, so D captures the full definition. Options A, B and C each pick out one narrow detail that a plan might contain, but none of them describes what plans do as a whole."}},{"itemId":"4fe23f58-bd86-5db9-83a2-c4f3938d72a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94f86d27-f5b6-5862-bb88-c0b396c1d594","sourceKey":"bank:AMS101:AMS101-T500","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main danger when an organisation focuses on just one goal?","options":["It guarantees that the goal will be exceeded","Other goals needed for long-term success get neglected","It makes the goal easier for every member to achieve","It stops members from growing and developing"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Organisations have several goals, and putting all the emphasis on one means the others that are also needed for long-term success get ignored. Option A is wrong because focus never guarantees results. Options C and D describe effects that have nothing to do with the real risk of a single-goal focus."}},{"itemId":"cfda92eb-82dd-57d2-9b22-c1587fab2b41","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16e5ad7a-72c4-555f-a276-16294d65ccde","sourceKey":"bank:AMS101:AMS101-T501","parentItemId":null,"revision":1,"payload":{"prompt":"Why can relying on a single objective encourage unethical behaviour by managers?","options":["Managers want to please the organisation's shareholders","Managers will spread their effort evenly across every part of their job","Managers will neglect other important parts of their job just to look good on that one measure","Managers will use unreported overtime to hit that single objective"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"When performance is judged on one measure, managers are tempted to ignore other important parts of their job just so they look good on that measure, which is where unethical practice creeps in. Option B is the opposite of what a single objective encourages. Options A and D describe specific motives or tactics rather than the core problem of narrow focus."}},{"itemId":"78a344d7-917f-5ee4-882b-941611640223","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c5d506f1-baf2-5788-a63c-3074f908726f","sourceKey":"bank:AMS101:AMS101-T502","parentItemId":null,"revision":1,"payload":{"prompt":"Stated goals are the official statements of what an organisation claims its goals are, and they reflect ___________.","options":["what the organisation wants its different stakeholders to believe its goals are","the goals the organisation actually works hard to achieve","what the organisation wants its shareholders alone to believe its goals are","what the organisation itself believes its goals are"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Stated goals are what an organisation says publicly, and what it wants its many stakeholders to believe its goals are. Option B describes real goals, which are the ones an organisation actually pursues and can differ from stated ones. Option C is too narrow because stated goals speak to all stakeholders, not only shareholders."}},{"itemId":"84cc5107-f022-5aaf-9c42-58f80ed74554","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"36cca3a4-6bee-5aa9-8600-32b8dbd63ebd","sourceKey":"bank:AMS101:AMS101-T503","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational plans are most commonly described by their breadth, time frame, ___________.","options":["depth and urgency","frequency and urgency","specificity and frequency","depth and specificity"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Plans are usually classified in four ways: breadth (strategic vs operational), time frame (long-term vs short-term), specificity (specific vs directional) and frequency of use (single-use vs standing). Options A, B and D each include 'depth' or 'urgency', which are not among the standard ways of describing plans."}},{"itemId":"426a79e0-70fa-5b48-bb27-b2439df8e01e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"830f09c7-8375-5c84-8146-8483f8355b68","sourceKey":"bank:AMS101:AMS101-T504","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic plans cover the whole organisation, set its overall goals and also ___________.","options":["steer the organisation toward maximum profit for shareholders","try to meet all government regulations while maximising profit","keep the organisation's stakeholders satisfied","aim to position the organisation in relation to its environment"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Strategic plans apply to the entire organisation, establish its overall goals and seek to position the organisation within its environment. Options A and B focus on profit, which is only one possible goal, and option C on satisfying stakeholders is a general aim rather than the defining feature of strategic plans."}},{"itemId":"b02582b2-7128-5fd3-85b8-c356c24334ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"101a6a66-0b40-585f-9c53-420f8e088385","sourceKey":"bank:AMS101:AMS101-T506","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with operational plans, strategic plans usually cover a longer time period and also ___________.","options":["take a narrower view of the organisation","contain the financial forecasts for the planning period","take a broader view of the organisation","estimate the dividends shareholders can expect"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Strategic plans are long-term and take a broad view of the whole organisation, while operational plans are shorter-term and cover a narrower area. Option A reverses this. Options B and D describe financial details that are not what distinguishes strategic plans."}},{"itemId":"d02dd05d-6455-53ad-91ae-fc30ec86991f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2e8f4971-9e96-5a65-b572-38c68a7fb7f2","sourceKey":"bank:AMS101:AMS101-T507","parentItemId":null,"revision":1,"payload":{"prompt":"Specific plans are clearly defined and ___________.","options":["let managers interpret them freely for flexibility","leave no room for interpretation","give managers the authority to interpret them for their own area","keep stakeholders informed of the organisation's objectives"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Specific plans have clearly defined objectives and leave no room for interpretation, so everyone knows exactly what is expected. Options A and C describe interpretation and flexibility, which belong to directional plans. Option D has nothing to do with how specific a plan is."}},{"itemId":"1f46dc2c-bffe-5045-b462-4cffe5a5ac87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1dbd763c-804c-57ec-bbde-27f3d37e206d","sourceKey":"bank:AMS101:AMS101-T508","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes directional plans?","options":["Flexible plans that lay down general guidelines","Strict plans that give managers precise directions to follow","Formal plans explaining how to assemble the product","General plans that let workers change the production schedule"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Directional plans are flexible and set out general guidelines, giving focus without locking managers into specific actions. Option B describes specific plans instead. Options C and D take the word 'directions' too literally and describe things unrelated to the planning concept."}},{"itemId":"5ef0b6a7-ae9e-5b5f-8d70-609f96068e66","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a972381b-f3e5-5598-9a86-b5a3836ba9c7","sourceKey":"bank:AMS101:AMS101-T509","parentItemId":null,"revision":1,"payload":{"prompt":"Standing plans are ongoing plans that provide ___________.","options":["general directions on how to complete one identifiable task","stakeholders with goals the organisation will always pursue","shareholders with goals the organisation will always pursue","guidance for activities that are carried out repeatedly"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Standing plans are ongoing and guide activities that happen again and again, such as policies, rules and procedures. Option A sounds close but describes a one-off task, which is the job of a single-use plan. Options B and C confuse plans with goals."}},{"itemId":"fbebbc69-7da7-50e6-8bf3-2a77618639cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"acf7c0e4-7f5c-5019-be1a-0f450fc95a68","sourceKey":"bank:AMS101:AMS101-T510","parentItemId":null,"revision":1,"payload":{"prompt":"Goals are frequently described as ___________.","options":["the basis of every other management function","management's do-or-die targets","having many different names in different organisations","the foundation of planning"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Goals are the desired outcomes that planning works toward, which is why they are called the foundation of planning. Option A is tempting because goals do guide other functions, but the standard description ties goals specifically to planning. Options B and C are not recognised descriptions."}},{"itemId":"b4ae1b85-bfda-52ac-8aa4-431638da0e22","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"58369c8a-88c9-581b-ab68-994a38ebcabb","sourceKey":"bank:AMS101:AMS101-T511","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following can tell, on its own, whether an organisation is successful?","options":["A goal is the only measure that can tell","No single measure can tell","Plans are another measure that can tell","Only stakeholders can tell"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Organisations pursue several goals at once, so success cannot be judged by any single measure. Options A and C wrongly suggest one goal or plan is enough, and option D wrongly limits the judgement to stakeholders alone."}},{"itemId":"923f42b8-8a84-57c9-91d6-5c4bd08d5c64","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ede8404-84bf-5445-932a-6e7865e2dec0","sourceKey":"bank:AMS101:AMS101-T512","parentItemId":null,"revision":1,"payload":{"prompt":"Stated goals often seem to conflict because organisations have to respond to many different ___________.","options":["stakeholders","external environments","government regulations","shareholders"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Organisations answer to many stakeholders, such as customers, employees, government and communities, and each group cares about different things, so stated goals can appear to conflict. Option D is too narrow because shareholders are only one stakeholder group. Options B and C are not the reason given for this conflict."}},{"itemId":"9902842b-93c8-55a7-959f-14199d6b75da","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00cb0c91-8b3a-54dd-b938-85674785b8a6","sourceKey":"bank:AMS101:AMS101-T513","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic plans take a broad view of the organisation and include setting goals, while operational plans describe ways to ___________.","options":["maximise the organisation's profit","achieve the goals","reduce the number of staff laid off in hard times","provide the most efficient production methods"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Strategic plans set the goals, and operational plans give the details of how those goals will be achieved. Options A, C and D each describe a possible aim of a particular plan, but none of them is the general role of operational plans."}},{"itemId":"e62237ea-c429-549c-a960-40da0218d31e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1fd51c1a-ef84-548e-a8fe-740783160a17","sourceKey":"bank:AMS101:AMS101-T514","parentItemId":null,"revision":1,"payload":{"prompt":"The flexibility of directional plans has to be weighed against the ___________.","options":["benefit of a shorter planning period offered by specific plans","benefit of a longer planning period offered by specific plans","loss of the clarity that specific plans provide","loss of a shorter planning period offered by specific plans"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Directional plans give flexibility, but you give up the clarity and predictability that specific plans offer, so the trade-off is flexibility versus clarity. Options A, B and D talk about the length of the planning period, which is not what separates directional from specific plans."}},{"itemId":"ddfb93d3-12db-566a-892a-6ac5ac961cd1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b22231c-a75f-55f4-93e7-8d7c5d43097f","sourceKey":"bank:AMS101:AMS101-T515","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of plan is used only once and is designed for the needs of a unique situation?","options":["Multipurpose plan","Strategic plan","Operational plan","Single-use plan"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A single-use plan is a one-time plan created for a unique situation, such as organising one particular event. Options B and C classify plans by breadth, not by how often they are used, and option A is not a standard plan type."}},{"itemId":"73d972c7-b969-581b-9c2d-1862088e9947","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4d75667-339e-5982-9cee-bf78943fbd8b","sourceKey":"bank:AMS101:AMS101-T516","parentItemId":null,"revision":1,"payload":{"prompt":"At the lower levels of an organisation, managers' planning is dominated by ___________ planning.","options":["Strategic","Tactical","Operational","Functional"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Lower-level managers mostly do operational planning, dealing with the day-to-day details of reaching goals. Strategic planning, option A, dominates at the top. Tactical and functional planning, options B and D, are not the standard answer for lower levels."}},{"itemId":"4cef780f-2799-5010-986d-40d6398e0df8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c369fdeb-356f-552e-9be0-10294e7f63b6","sourceKey":"bank:AMS101:AMS101-T517","parentItemId":null,"revision":1,"payload":{"prompt":"In traditional goal setting, top management sets the goals and ___________.","options":["first-line managers then become responsible for achieving them","the goals are then broken into subgoals for each level of the organisation","top management directs every effort to make sure they are achieved","the goals are delegated to the next level down to achieve"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Traditional goal setting works top-down: top managers set broad goals, and these are broken down into subgoals for each level of the organisation. Option D is tempting but describes simply passing the same goal down rather than breaking it into subgoals. Options A and C wrongly place all responsibility at one level."}},{"itemId":"ad5ce033-b6a6-562e-af77-3dda2eda0dbc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"76c1d22f-05af-5749-8510-91049bec9288","sourceKey":"bank:AMS101:AMS101-T518","parentItemId":null,"revision":1,"payload":{"prompt":"Under traditional goal setting, employees at each level and in each work area direct their efforts toward meeting the goals ___________.","options":["so that top managers keep their jobs","so that their immediate supervisor keeps their job","that have been assigned to their own area of responsibility","in the shortest possible time"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Because goals are broken down level by level, each employee's work is geared to the goals assigned to their own area of responsibility. Options A and B suggest job protection as the motive, which is not part of the concept, and option D is about speed rather than goal alignment."}},{"itemId":"dd3aee60-61d7-5c36-8b7f-e2da30b03e49","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d898b3b9-f5d7-568a-b4b0-cd5bc81ce07b","sourceKey":"bank:AMS101:AMS101-T519","parentItemId":null,"revision":1,"payload":{"prompt":"Management by objectives (MBO) starts with setting specific performance goals that are ___________.","options":["easy to achieve","decided jointly by employees and their managers","set by top management so clearly that even the weakest employee understands them","designed so employees direct themselves and need no supervision"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The defining feature of MBO is that specific performance goals are set jointly by employees and their managers, and progress is then reviewed. Option C describes top-down goal setting, which is the opposite of MBO. Options A and D are not part of how MBO is defined."}},{"itemId":"ca9ee524-7109-57f4-9ae9-f8b8811891ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d13c9233-4c1a-5caa-95b6-3a37cfdf7c46","sourceKey":"bank:AMS101:AMS101-T520","parentItemId":null,"revision":1,"payload":{"prompt":"Research on real MBO programmes shows that MBO ___________ employee and organisational performance.","options":["depends on","is related to","reduces","increases"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Studies of actual MBO programmes have found that MBO increases both employee and organisational performance. Option B is technically true but too weak, since the research shows a positive effect, not just a link. Option C is the opposite of the findings."}},{"itemId":"9db251c0-8495-526c-b3a4-1fe3295a07b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d7849ad-5ce6-5b95-80bf-19bc6b7cd0c4","sourceKey":"bank:AMS101:AMS101-T521","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a possible weakness of MBO programmes?","options":["Too much focus on individual goal achievement without regard for others in the work unit","They may be less effective when the environment is changing rapidly","Employees may not take goal setting seriously enough","All of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"MBO can fail in fast-changing environments, can push people to focus on their own goals at the expense of teamwork, and can be weakened when employees treat goal setting as a formality. Since options A, B and C are all recognised problems, D is the best answer."}},{"itemId":"5bc356c1-3f94-5da1-b973-b8d227548769","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9e4a10ff-1711-533b-9544-7ae809757ebb","sourceKey":"bank:AMS101:AMS101-T522","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a feature of an MBO system?","options":["Management alone decides the objectives","Goals are reviewed only when they are completed","Goals are used as controls","Progress is reviewed periodically"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"In MBO, progress toward goals is reviewed periodically and feedback is given along the way. Option A is wrong because MBO goals are set jointly, and option B contradicts the idea of regular review. Option C is not how the system is described."}},{"itemId":"e54470ad-45bf-50a7-8bc0-391d91f10b4d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fed5e8f4-4343-5eee-9dc6-83473e67f2e7","sourceKey":"bank:AMS101:AMS101-T523","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a feature of a well-designed goal?","options":["It describes the activities employees should carry out","It is stated in terms of outcomes rather than actions","It can be recognised even by first-line supervisors","It leaves the time frame open so employees are not pressured"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A well-designed goal describes the desired outcome rather than the actions taken to get there, for example 'reduce complaints by 10 percent' rather than 'answer more calls'. Option A is the opposite, because it describes activities instead of results. Option D is wrong because good goals are clear about their time frame."}},{"itemId":"7be49df6-ddc8-5126-9cb2-6de041b4d072","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc44df0a-fa97-5646-bfeb-f0937e1cb892","sourceKey":"bank:AMS101:AMS101-T524","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from being measurable and having a set time frame, a well-designed goal should be ___________.","options":["put in writing","almost impossible to reach, so that even a miss still means very high performance","communicated to everyone who needs to know it","both A and C"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Well-designed goals are written down and communicated to all who need to know, along with being measurable, time-bound and challenging but attainable. Since A and C are both characteristics, D is correct. Option B is wrong because good goals are challenging yet achievable, not nearly impossible."}},{"itemId":"c504e18d-4255-5365-a73e-d0ad9d467a7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e5e3a773-5adc-532b-9cb2-69eb542b49b1","sourceKey":"bank:AMS101:AMS101-T525","parentItemId":null,"revision":1,"payload":{"prompt":"When members of an organisation take a more active part in planning, they come to see the plans as ___________.","options":["the real plans behind what is announced to stakeholders","less important than management claims","the way shareholders will judge the company","more than just something written on paper"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Involving people in planning gives them ownership, so they see plans as real guides to action rather than documents sitting on paper. Option B is the opposite effect. Options A and C describe ideas about stakeholders and shareholders that are unrelated to participation."}},{"itemId":"113433f5-850c-5884-bee6-fe840d583de8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d3d3962-dc2f-574b-9b7b-aed692475511","sourceKey":"bank:AMS101:AMS101-T526","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation's hierarchy of goals is clearly defined, it forms a connected network of goals known as a ___________.","options":["hierarchical-link chain","means-ends chain","weakest-link chain","level-level chain"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"In a means-ends chain, achieving lower-level goals is the means for reaching higher-level goals, which in turn are the ends that lower levels work toward. Options A, C and D are made-up terms that do not describe this concept."}},{"itemId":"08679008-cdaa-5ba5-a7e8-83ed2182279b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06b73c3e-5fc7-5305-a5ad-20b5b61136bb","sourceKey":"bank:AMS101:AMS101-T527","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational level and the degree of environmental uncertainty are two contingency factors that affect planning. The third is the ___________.","options":["length of future commitments","number of future commitments","frequency of future commitments","enforceability of future commitments"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"The three contingency factors in planning are organisational level, degree of environmental uncertainty and length of future commitments. The longer today's decisions commit the organisation into the future, the longer the planning horizon must be. Options B, C and D change the important word and are not recognised factors."}},{"itemId":"bb6a6ebb-82b1-5d53-a1f2-db0b53f15f7a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b0c79284-f592-59fc-8d8f-8c024d1d3807","sourceKey":"bank:AMS101:AMS101-T528","parentItemId":null,"revision":1,"payload":{"prompt":"Under the commitment concept, plans should reach far enough into the future to meet the commitments ___________.","options":["as fast as possible","while resources are still available","with stakeholders, making the organisation appear truly committed","that were made when the plans were developed"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The commitment concept says plans should extend far enough to fulfil the commitments made when the plans were drawn up. Options A and B focus on speed and resources rather than on matching the planning horizon to commitments, and option C is about appearances."}},{"itemId":"6b066a20-1819-5351-886c-705d377584b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9282bacf-91a0-5e9e-9b46-32534ebfb527","sourceKey":"bank:AMS101:AMS101-T529","parentItemId":null,"revision":1,"payload":{"prompt":"Organisational level and length of future commitments are two contingency factors affecting planning. What is the third?","options":["Management's dislike of risk","Employee satisfaction","Level of productivity","Degree of environmental uncertainty"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The three contingency factors are organisational level, length of future commitments and degree of environmental uncertainty. The more uncertain the environment, the more plans should be directional and short-term. Options A, B and C may matter to an organisation but are not among these three factors."}},{"itemId":"dceaab92-58ee-598b-8b38-020fe7cff96e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8540276a-233e-5904-ac0d-c6a42a883268","sourceKey":"bank:AMS101:AMS101-T530","parentItemId":null,"revision":1,"payload":{"prompt":"What gives the best understanding of how an organisation plans?","options":["The goals its planners set","Who carries out the planning","How flexible its plans are","None of the above"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The clearest way to understand an organisation's approach to planning is to look at who does the planning, for example a separate group of planning specialists at the top, or managers and employees throughout the organisation. Option A is tempting because goals are central to planning, but goals describe what is planned for, not how the planning is done. Option C is a feature of individual plans."}},{"itemId":"144f4652-259e-5b21-aeea-f9bf9669be9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9e226623-5989-56d0-9ad3-c1e53ff84b27","sourceKey":"bank:AMS101:AMS101-T531","parentItemId":null,"revision":1,"payload":{"prompt":"Under the traditional approach, planning was done wholly by top managers, who were often supported by ___________.","options":["business-level managers","functional-level managers","a mix of line, functional and business-level managers","a group of planning specialists"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"In the traditional approach, top managers did all the planning, usually with help from a formal planning department made up of planning specialists. Options A, B and C describe other managers getting involved, which is closer to the modern approach where planning is spread across the organisation."}},{"itemId":"b4745686-dc5a-52d2-ad4f-8abbda428755","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7e57d67e-298d-55b1-9fca-4a36106952ef","sourceKey":"bank:AMS101:AMS101-T532","parentItemId":null,"revision":1,"payload":{"prompt":"Goals give direction to all management decisions and actions, and they serve as the ___________.","options":["profit base the organisation will deliver to shareholders","rules employees must follow in their daily tasks","basis for sharing profits with employees at year end","standard against which actual results are measured"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Besides giving direction, goals are the standard against which actual accomplishments are measured, which links planning to controlling. Option B describes rules, which are a type of standing plan rather than goals. Options A and C focus on profit, which is not the general point."}},{"itemId":"c6f1ac35-a3ee-56fc-a7ea-2a39935237e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3eca0a24-b7ac-5b6e-ade9-b2e0814d714b","sourceKey":"bank:AMS101:AMS101-T533","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a commonly cited criticism of formal planning?","options":["Plans cannot be developed for a dynamic environment","Formal planning makes managers rely too much on intuition","Formal planning adds extra, often unnecessary layers of hierarchy","Formal planning only works for large, diversified companies"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A standard criticism is that formal plans cannot be developed for a dynamic environment, because conditions change faster than plans can follow. Other criticisms are that planning creates rigidity and can replace intuition and creativity. Option B gets this backwards, since the worry is that planning pushes intuition aside, and options C and D are not recognised criticisms."}},{"itemId":"743f01c7-0a0d-5455-b1a1-02a881b37326","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ccb7a983-57f1-5a6f-8b62-871f90fa9c4e","sourceKey":"bank:AMS101:AMS101-T534","parentItemId":null,"revision":1,"payload":{"prompt":"When the environment is highly uncertain, it is ___________ formal planning efforts.","options":["less important to continue","important to switch to directional planning and stop","necessary to stop","important to continue"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Even in a very uncertain environment, managers should keep planning, because planning helps them think ahead and adjust. What changes is the type of plan, which should be specific but flexible. Options A, B and C all suggest cutting back or stopping, which is the wrong response."}},{"itemId":"2ba6a39a-1757-5792-8594-9ead92bcdb32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce28fbe1-a3fc-5473-b3a1-c613418706f5","sourceKey":"bank:AMS101:AMS101-T537","parentItemId":null,"revision":1,"payload":{"prompt":"As organisations' environments have become more uncertain, ___________.","options":["organisations have to make longer-term plans","organisations must resist uncertainty to keep plans moving toward objectives","organisations must ask government for laws that limit uncertainty","what counts as 'long term' has changed"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Rapid change means planning horizons have shortened, so the meaning of 'long term' has changed. Option A is the opposite. Options B and C suggest uncertainty can be resisted or legislated away, which is unrealistic."}},{"itemId":"a1999d7d-75f9-50e1-88b3-f49f687a70a8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa94b742-9162-5f5d-8408-a99a3b386430","sourceKey":"bank:AMS101:AMS101-T538","parentItemId":null,"revision":1,"payload":{"prompt":"In an uncertain environment, the plans managers develop should be ___________.","options":["flexible but manageable","specific and long-range","directional but flexible","specific but flexible"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Uncertain environments call for plans that are specific but flexible, giving clear direction while allowing quick changes. Option B loses the flexibility, and option C loses the specificity. Option A is not the standard description."}},{"itemId":"f8897146-aad4-5a95-a366-4105c7f98978","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1c07adb-573c-5fc0-ad23-89eb0d1d2678","sourceKey":"bank:AMS101:AMS101-T539","parentItemId":null,"revision":1,"payload":{"prompt":"The organisational hierarchy becomes flatter when the responsibility for setting goals and making plans is ___________.","options":["moved to middle levels","pushed down to the lowest levels","given to a formal planning department","handed mainly to the finance department"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"When goal setting and planning are pushed down to the lowest levels, fewer layers of control are needed, so the hierarchy becomes flatter. Option C describes the traditional top-down approach, which keeps the hierarchy tall. Options A and D do not lead to flattening."}},{"itemId":"0e0f8f34-a52c-50df-8a40-ce95b8a69d67","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2cac72ad-d5fc-5855-8987-dd864df3e2cf","sourceKey":"bank:AMS101:AMS101-T540","parentItemId":null,"revision":1,"payload":{"prompt":"To manage well in a dynamic environment, managers must see planning as ___________.","options":["an ongoing process","something that cannot be renewed from one period to the next","best handled by a formal planning department","best done at the start of a new year"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"In a fast-changing environment, planning is never finished; managers keep adjusting plans as conditions change. Option D treats planning as a once-a-year event, and option C hands it to a separate department, both of which fit stable conditions better."}},{"itemId":"8176006f-34e0-5ecc-b4c0-f43133d08b3e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"70c7c557-d56c-50cc-a282-a6a363b0d8d5","sourceKey":"bank:AMS101:AMS101-T542","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly describes strategic management?","options":["It is a set of managerial decisions and actions","It focuses on an organisation's short-run performance","It works best when done quickly","All of the above"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Strategic management is the set of managerial decisions and actions that determine an organisation's long-run performance. Option B is wrong because the focus is long-run, not short-run, and option C is not part of the definition, so D cannot be correct."}},{"itemId":"7ef2b5d6-7b82-53a3-8fc3-7f1c98760e68","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51cb134c-b5d1-5dd4-a9ba-805293a093af","sourceKey":"bank:AMS101:AMS101-T543","parentItemId":null,"revision":1,"payload":{"prompt":"Which management function or functions does strategic management make use of?","options":["Planning and leading","Organising","Controlling","All of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Strategic management draws on all the basic management functions: planning, organising, leading and controlling. Each of options A, B and C names only part of the picture, so D is the best answer."}},{"itemId":"d1c8bca7-9ce9-5112-bdcc-5c9a2eeef27b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"039002cb-520b-5239-aeea-07f8fc328b73","sourceKey":"bank:AMS101:AMS101-T544","parentItemId":null,"revision":1,"payload":{"prompt":"Research into what drives organisational performance has generally found a ___________ relationship between strategic planning and performance.","options":["no","mixed","negative","positive"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Studies have generally found a positive relationship between strategic planning and performance: organisations that plan strategically tend to perform better. Options A, B and C contradict this general finding."}},{"itemId":"75f8371f-ffd0-5137-b47a-9d8ee3349312","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"10a3788f-a831-597b-9bb2-b517f2e23a92","sourceKey":"bank:AMS101:AMS101-T545","parentItemId":null,"revision":1,"payload":{"prompt":"For which kind of organisation is strategic management NOT useful today?","options":["Hospitals","Government agencies","Non-profit organisations","None of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Strategic management is useful for all kinds of organisations, including hospitals, government agencies and non-profits, not just businesses. Since none of options A, B or C is an exception, D is correct."}},{"itemId":"f9516daa-2b3b-5d69-a26f-828fc663d0fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"574f890c-6318-57a3-9937-5927e26cde05","sourceKey":"bank:AMS101:AMS101-T546","parentItemId":null,"revision":1,"payload":{"prompt":"Which term describes the set of managerial decisions and actions that determine an organisation's long-run performance?","options":["Planning","Goal-oriented management","Strategic management","Leadership"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"That is the definition of strategic management. Option A, planning, is broader and includes short-term operational planning. Options B and D do not match this definition."}},{"itemId":"e1f1d986-f7a7-5e6e-8b2b-c3569ec644bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b693b746-030c-5c8a-b40a-f0f0a188d445","sourceKey":"bank:AMS101:AMS101-T547","parentItemId":null,"revision":1,"payload":{"prompt":"In the first step of the strategic management process, the organisation's mission answers which question?","options":["How will we beat our closest competitor?","What is our reason for being in business?","Who are our customers?","Who are our creditors?"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A mission statement describes the organisation's purpose, answering 'What is our reason for being in business?'. Option A is about how to compete, which is a matter of business-level strategy formulated later in the process. Option C is something a mission may touch on, but it is not the central question, and option D is not part of the mission."}},{"itemId":"456dfc73-af11-5caf-a663-475ddf898f63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51e323fe-327b-54e5-9ee0-cce505d8d22b","sourceKey":"bank:AMS101:AMS101-T549","parentItemId":null,"revision":1,"payload":{"prompt":"When analysing the environment, what should managers know?","options":["What competitors are doing","Competitors' share prices","Pending laws that could affect the organisation","Both A and C"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Environmental analysis covers the external factors that can affect the organisation, such as competitors' actions and pending legislation. Option B is a narrow financial detail that is not central to environmental analysis, so D is the best answer."}},{"itemId":"5b52c969-cbcb-506a-9b0d-0da9b3806914","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"827f82c0-77b9-54eb-a04f-5a0cfd5d8b6b","sourceKey":"bank:AMS101:AMS101-T550","parentItemId":null,"revision":1,"payload":{"prompt":"Managers have finished the second step of strategic management, analysing the environment, when they ___________.","options":["have an accurate picture of what is happening in the external environment","have beaten a competitor's latest product to market","are aware of trends that could affect the organisation","only A and C"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Environmental analysis is complete when managers have an accurate picture of the external environment and know the important trends that could affect them. Option B describes a competitive result, not the completion of an analysis step, so D is correct."}},{"itemId":"4858fc1e-5e5e-529a-8b51-359c8277534d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f76cc80f-ef92-52fd-b079-f9ffc6ca0833","sourceKey":"bank:AMS101:AMS101-T551","parentItemId":null,"revision":1,"payload":{"prompt":"What does the fourth step of the strategic management process involve?","options":["Choosing strategies that reduce or correct organisational weaknesses","Developing and evaluating strategic alternatives","Choosing strategies that make use of organisational strengths","All of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Step 4 is formulating strategies: managers develop and evaluate alternatives and then choose strategies that build on strengths and correct weaknesses. Options A, B and C are each part of this step, so D is the best answer."}},{"itemId":"49bc4d39-409c-5329-858d-a231233f83a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"97df01cb-1c27-5c3e-9ae5-b12b8cdb8a98","sourceKey":"bank:AMS101:AMS101-T552","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a firm's core competence?","options":["Being able to meet the needs of a particular target market on a large scale","Communicating with customers worldwide in their own languages","Developing least-squared exemptions within its accounting system","Only A and B"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Core competencies are major value-creating skills and capabilities, such as serving a target market at scale or communicating with customers in their own languages. Option C is a meaningless technical phrase, not a value-creating capability, so D is correct."}},{"itemId":"63fd643a-91d1-5e10-9f20-6ffc301b2394","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"feda35bd-f434-54cf-b77a-ea5255aee73b","sourceKey":"bank:AMS101:AMS101-T553","parentItemId":null,"revision":1,"payload":{"prompt":"Which term refers to an organisation's major value-creating skills, capabilities and resources that determine its competitive weapons?","options":["Strengths","Opportunities","Core competencies","Weaknesses"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Core competencies are the major value-creating skills, capabilities and resources that form an organisation's competitive weapons. Option A, strengths, is close, but strengths are anything the organisation does well, while core competencies are the major ones that give it its competitive edge. Options B and D are not internal capabilities."}},{"itemId":"8c91cbfb-ecae-5f70-8b0c-46fb612a8b8e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e1dd96a-7c21-5e00-b73e-603657fa6ade","sourceKey":"bank:AMS101:AMS101-T554","parentItemId":null,"revision":1,"payload":{"prompt":"The third step of strategic management, identifying strengths and weaknesses, involves analysing the ___________.","options":["external environment","internal environment","alternatives the firm faces","time pressures in serving customers"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Strengths and weaknesses come from looking inside the organisation at its resources and capabilities, so this is internal analysis. Option A, the external environment, is where opportunities and threats are found. Options C and D are not what this step analyses."}},{"itemId":"6c4a7fd7-1da5-5e97-aaac-ad108b5fad25","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9e3daf22-d64a-5548-b9ce-71384a00fddd","sourceKey":"bank:AMS101:AMS101-T555","parentItemId":null,"revision":1,"payload":{"prompt":"Regarding organisational culture, what should a manager be aware of during strategic management?","options":["Strong and weak cultures affect strategy differently","The content of a culture strongly affects which strategies can be pursued","Unimportant factors can encourage escalation of commitment to strategies","Both A and B"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Culture matters in strategy because strong and weak cultures have different effects on strategy, and the content of a culture shapes which strategies are realistic. Option C is not a point about culture, so D is the best answer."}},{"itemId":"87a4378f-c5f0-5cac-8b99-cb15f2c66f12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"108a00f3-75a9-537a-b38a-31ded30bf770","sourceKey":"bank:AMS101:AMS101-T556","parentItemId":null,"revision":1,"payload":{"prompt":"What is the combined analysis of an organisation's internal and external factors called?","options":["Complete studies","Organisational behaviour and theory","Definitional analysis","SWOT analysis"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"SWOT analysis brings together internal strengths and weaknesses with external opportunities and threats. Options A, B and C are not names for this combined analysis."}},{"itemId":"0788f925-5b1e-5db8-9ab9-b3f93c0bcbb9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4e476b4-5f6b-5cfc-9abd-b86610ea62b3","sourceKey":"bank:AMS101:AMS101-T558","parentItemId":null,"revision":1,"payload":{"prompt":"The last step of the strategic management process answers which question?","options":["How effective have our strategies been?","What business have we been in?","What business should we have been in?","How much money have we lost?"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"The final step is evaluating results, which asks how effective the strategies have been and what adjustments are needed. Options B and C relate to the mission at the start of the process, and option D is too narrow a measure."}},{"itemId":"cdd05a64-2a96-5f79-8621-101f82b1b500","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5921163b-ad02-5754-a5e9-90115f4da525","sourceKey":"bank:AMS101:AMS101-T559","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation studies the supply of labour available to it, it is examining its ___________.","options":["organisational culture","internal environment","external environment","organisational structure"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The labour supply, meaning the pool of workers available in the job market, is outside the organisation, so it is part of the external environment. Option B is tempting because it concerns people, but the internal environment covers the organisation's own resources and capabilities."}},{"itemId":"97d93335-2247-5c4f-a80e-e4f8c8bee759","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a13bb825-5b1f-5406-a669-cc64420aa199","sourceKey":"bank:AMS101:AMS101-T560","parentItemId":null,"revision":1,"payload":{"prompt":"Which two outcomes come from studying the external environment?","options":["Threats and weaknesses","Strengths and weaknesses","Weights and measures","Opportunities and threats"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Analysing the external environment reveals opportunities and threats. Strengths and weaknesses, option B, come from internal analysis, and option A mixes one external and one internal outcome."}},{"itemId":"1ac128b4-f2f7-5c0c-8d90-06c410f21a65","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14630128-44cb-51e8-a8ea-a7131b845c34","sourceKey":"bank:AMS101:AMS101-T561","parentItemId":null,"revision":1,"payload":{"prompt":"A bank assesses the abilities of its training department staff before launching a new programme to change how customer service is delivered. Which step of the strategic management process is it carrying out?","options":["Identifying opportunities and threats","Identifying the organisation's current mission","Identifying strengths and weaknesses","Formulating strategy"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Assessing the abilities of its own staff is an internal analysis, which is how an organisation identifies its strengths and weaknesses. Option A concerns the external environment, and option D comes after this analysis, when strategies are chosen."}},{"itemId":"8bb44d01-16dc-5d16-9fb8-e9dd1f4f8d87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77b2e45f-637e-545b-9846-9aa530288145","sourceKey":"bank:AMS101:AMS101-T562","parentItemId":null,"revision":1,"payload":{"prompt":"In strategic management, organisational skills or resources that are exceptional or unique are the organisation's ___________.","options":["strength basis","opportunities","core competencies","skill niches"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Exceptional or unique skills and resources that create value are core competencies. Option B is wrong because opportunities are external. Options A and D are not recognised terms."}},{"itemId":"0ef47ac7-0561-582e-8b57-ebe9cadea70a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"117199c1-6d5c-5d68-ab22-63ad6c51937f","sourceKey":"bank:AMS101:AMS101-T563","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of a strong organisational culture that managers should keep in mind during strategic management?","options":["It can be harder to change","Employees understand the planning process less","Employee attitudes are strong but organisational values are weak","It wipes out any distinctive competence"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A strong culture is deeply held and widely shared, which makes it harder to change when a new strategy needs a different culture. Option C contradicts itself because strong cultures mean strongly held values. Options B and D are not recognised drawbacks."}},{"itemId":"251d3c1c-89cb-5760-ab92-5fd310461ce3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7e75f70b-eb38-5738-87c6-9f69ae9ff6ed","sourceKey":"bank:AMS101:AMS101-T564","parentItemId":null,"revision":1,"payload":{"prompt":"What does corporate-level strategy determine?","options":["Which businesses a company is in or wants to be in","Which environment a company is in or wants to be in","The role each business unit will play in the overall strategy","Only A and C"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Corporate-level strategy decides which businesses the company should be in and what role each business unit will play. Option B is not part of the definition, so D is correct."}},{"itemId":"a5238893-93e1-5796-ba7e-2bba096bf0a2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e89f1d9-7540-5a23-bc78-2c18049e2e3b","sourceKey":"bank:AMS101:AMS101-T565","parentItemId":null,"revision":1,"payload":{"prompt":"Which level of strategy decides what businesses an organisation should be in?","options":["Business-level","Organisational","Operational-level","Corporate-level"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Corporate-level strategy decides what businesses the organisation should be in. Option A, business-level strategy, decides how to compete within each business. Options B and C are not the standard name for this level."}},{"itemId":"6a7b2a70-fa60-5678-93e6-09e3a5add369","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f60970c1-5199-5002-b14f-8bb62d60f7e0","sourceKey":"bank:AMS101:AMS101-T566","parentItemId":null,"revision":1,"payload":{"prompt":"Which kind of strategy deals with organisational weaknesses, helps stabilise operations and renews organisational resources and capabilities?","options":["Unrelated diversification","Horizontal integration","Vertical integration","Retrenchment"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Retrenchment is a short-run renewal strategy used when performance is poor; it fixes weaknesses, stabilises operations and revitalises resources. Options A, B and C are all growth strategies, which expand the organisation rather than repair it."}},{"itemId":"bfe2e048-ff39-5e3c-a74c-9e87f747d812","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"53e78732-4953-5c64-ad21-ee5725beef5f","sourceKey":"bank:AMS101:AMS101-T567","parentItemId":null,"revision":1,"payload":{"prompt":"What are the three main types of growth strategy?","options":["Concentration, integration and diversification","Concentration, integration and exfoliation","Integration, diversification and infiltration","Concentration, integration and focus"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Organisations grow through concentration on their main business, through integration (vertical or horizontal) or through diversification (related or unrelated). Option D includes 'focus', which is one of Porter's competitive strategies, not a growth strategy. Options B and C include made-up terms."}},{"itemId":"6c7dd49f-4bd1-567e-9541-f71fec69a32c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e47f1618-1cd3-591f-9ca4-035e76b5aafb","sourceKey":"bank:AMS101:AMS101-T568","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation grows by combining with other organisations in the same industry, the strategy is called ___________.","options":["related diversification","horizontal integration","vertical integration","stability"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Horizontal integration means growing by combining with competitors in the same industry. Option A, related diversification, involves a different but related industry. Option C involves joining with suppliers or distributors, and option D means not growing."}},{"itemId":"a7242344-3462-5b34-b736-2b07768f90de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6f9c4b2c-276a-5d8a-857c-8939472e1bae","sourceKey":"bank:AMS101:AMS101-T569","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation combines with other organisations in different but related industries, the strategy is called ___________.","options":["unrelated diversification","horizontal integration","vertical integration","related diversification"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Related diversification means combining with firms in a different industry that is connected to the current one. Option A, unrelated diversification, involves industries with no connection at all. Option B is about the same industry, and option C is about suppliers or distributors."}},{"itemId":"dc409d71-9aaf-5aa7-bdc3-db148a2e66d2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4cd2676a-7b47-5734-b858-fc61657b5100","sourceKey":"bank:AMS101:AMS101-T570","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation combines with other organisations in different and unconnected industries, the strategy is called ___________.","options":["unrelated diversification","horizontal integration","vertical integration","stability"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Unrelated diversification means moving into industries that have no connection to the current business. Option B is the same industry, option C is along the value chain, and option D means not growing at all."}},{"itemId":"1ba637aa-33cb-54ac-970c-f330c779a733","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b1c51aa4-2a9e-5349-883f-9b970f6dd27a","sourceKey":"bank:AMS101:AMS101-T571","parentItemId":null,"revision":1,"payload":{"prompt":"A parent company tries to coordinate the strategies of its separate soft-drink and snack-food businesses. Which level of strategy is it working on?","options":["Functional","System","Management","Corporate"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Deciding how a company's different businesses fit together is corporate-level strategy. Option A, functional strategy, supports a single business through areas like marketing or finance. Options B and C are not recognised strategy levels."}},{"itemId":"07396443-9318-538a-b7fc-b440be472ec8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ef4766a-5f1c-502d-973c-7659489bd08f","sourceKey":"bank:AMS101:AMS101-T572","parentItemId":null,"revision":1,"payload":{"prompt":"An organisation that is expanding its product line through diversification is following which type of grand strategy?","options":["Stability","Retrenchment","Growth","Maintenance"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Diversification is a form of growth strategy, because the organisation is expanding what it offers. Option A means keeping things as they are, option B means cutting back, and option D is not a standard grand strategy."}},{"itemId":"4eab7a55-7262-50dd-8cc1-3069b1c7d821","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"10768507-2c67-57fa-8593-6731cb2dc38f","sourceKey":"bank:AMS101:AMS101-T573","parentItemId":null,"revision":1,"payload":{"prompt":"If two major passenger airlines merged, which type of growth strategy would this be?","options":["Horizontal integration","Acquisition","Expansion","Vertical integration"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Two companies in the same industry joining together is horizontal integration. Option D would apply if an airline joined with a supplier or distributor, such as a fuel company. Options B and C are general terms, not the named strategy."}},{"itemId":"0e95d271-f26c-5582-8774-6a429ab47f50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e21a7df6-5e0a-55a4-b85c-a8f83505a31f","sourceKey":"bank:AMS101:AMS101-T574","parentItemId":null,"revision":1,"payload":{"prompt":"Which term describes a company growing by joining with other organisations in the same industry?","options":["Forward vertical integration","Backward vertical integration","Horizontal integration","Unrelated diversification"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Horizontal integration is combining with competitors in the same industry. Forward and backward vertical integration, options A and B, involve gaining control of distributors or suppliers. Option D involves an unconnected industry."}},{"itemId":"8bb274de-503d-5bb4-ab7b-dbd18f032af7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"165e7e0a-ac9b-5a90-ab91-58492ba8d8cc","sourceKey":"bank:AMS101:AMS101-T575","parentItemId":null,"revision":1,"payload":{"prompt":"When is a stability strategy particularly appropriate?","options":["When the firm faces slow or no-growth opportunities","When the industry is going through rapid upheaval","Both A and B","Neither A nor B"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A stability strategy, where the organisation continues what it is doing without big changes, makes sense when growth opportunities are slow or absent. It can also suit a period of rapid industry upheaval, when managers prefer to hold steady until the future becomes clearer. Because both situations apply, C is the best answer."}},{"itemId":"e64fc22e-4a91-5533-8f59-906a4adea790","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2fd12fc3-bcb4-5cbb-b067-f67a8281bd0c","sourceKey":"bank:AMS101:AMS101-T576","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the principles on which strategic business units (SBUs) are built?","options":["Each unit serves at most three product-market segments","The unit's strategy is set at the corporate level","The unit's strategy may conflict with the needs of the whole organisation","Each unit serves a clearly defined product-market segment"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"An SBU is a single business, or group of related businesses, that serves a clearly defined product-market segment and develops its own strategy. Option B is wrong because SBUs form their own strategies, and option C is wrong because those strategies should fit the organisation's overall needs. Option A puts an invented limit on segments."}},{"itemId":"1f76b416-7272-5c6d-a263-0ea27d50046a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b45ec0d3-6fec-5230-a2da-367feea193c7","sourceKey":"bank:AMS101:AMS101-T577","parentItemId":null,"revision":1,"payload":{"prompt":"In the Boston Consulting Group (BCG) matrix, which business neither uses nor generates much cash and offers little prospect of better performance?","options":["Cash cow","Star","Dog","Question mark"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A dog has low market share in a low-growth market, so it neither produces nor uses much cash and holds little promise. Option A, a cash cow, generates lots of cash. Options B and D are in high-growth markets and need cash to grow."}},{"itemId":"b34df4fa-8c69-5d35-ab1a-8adb27a10973","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"73a1d581-1018-58fa-82f7-87c9035f6875","sourceKey":"bank:AMS101:AMS101-T578","parentItemId":null,"revision":1,"payload":{"prompt":"In the BCG matrix, a business unit with low expected market growth and high market share is called a ___________.","options":["cash cow","star","dog","question mark"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A cash cow combines high market share with low growth, so it brings in steady cash without needing much investment. Option B, a star, has high share but in a high-growth market. Option C, a dog, has low share and low growth."}},{"itemId":"b1a73761-8952-5d5f-8ef0-9278102f6c49","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1df74f18-389a-5ca3-8d73-003b4ec6a99c","sourceKey":"bank:AMS101:AMS101-T579","parentItemId":null,"revision":1,"payload":{"prompt":"In the BCG matrix, a business unit with high expected market growth but low market share is called a ___________.","options":["cash cow","star","dog","question mark"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A question mark sits in an attractive, fast-growing market but has only a small share, so managers must decide whether to invest in it or drop it. Option B, a star, has high share in a high-growth market. Options A and C are in low-growth markets."}},{"itemId":"a65578b2-3b39-5708-85d4-1e52f939526f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df427d46-6545-5a9b-84da-d8512099f05b","sourceKey":"bank:AMS101:AMS101-T580","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the four groups in the corporate portfolio matrix has low growth and high market share?","options":["Question marks","Dogs","Cash cows","Stars"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Cash cows have high market share in a low-growth market. Option D, stars, have high share but high growth. Option B, dogs, have low share and low growth, and option A, question marks, have low share and high growth."}},{"itemId":"fb4877c5-028a-5937-9ac1-ecadb2d109ef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a5ba781-15d9-5986-a723-1949b86f7c00","sourceKey":"bank:AMS101:AMS101-T581","parentItemId":null,"revision":1,"payload":{"prompt":"What does business-level strategy determine?","options":["Which businesses a company is in or wants to be in","Which environment a company is in or wants to be in","How the organisation should compete in each of its strategic business units","All of the above"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Business-level strategy is about how to compete within each business or SBU. Option A describes corporate-level strategy, which decides which businesses to be in. Option B is not part of either definition, so D cannot be correct."}},{"itemId":"c5f74a7b-2b5b-56e5-a9ed-238db648288b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee08a16a-4283-593e-a443-dbdff5a9a688","sourceKey":"bank:AMS101:AMS101-T582","parentItemId":null,"revision":1,"payload":{"prompt":"Which level of strategy decides how an organisation should compete in each of its businesses?","options":["Business-level","Organisational","Operational-level","Corporate-level"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Business-level strategy decides how to compete in each business. Option D, corporate-level strategy, decides which businesses to be in. Options B and C are not the standard names for this level."}},{"itemId":"7fa6e3e3-e602-5e19-bb74-42d0382685dc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4353540f-8a1d-5d8b-92b3-dd9d4b5aa4f7","sourceKey":"bank:AMS101:AMS101-T583","parentItemId":null,"revision":1,"payload":{"prompt":"Michael Porter argues that some ___________ are naturally more profitable than others.","options":["companies","industries","SBUs","individuals"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Porter's view is that some industries are inherently more profitable than others because of the competitive forces at work in them, which is why industry analysis comes first. Option A is tempting, but his argument here concerns industries, not individual firms."}},{"itemId":"0da8f73e-2ca4-5071-baf5-bf9b2c3b00e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"587e1985-8e38-5305-8bd6-99afcdadbf30","sourceKey":"bank:AMS101:AMS101-T584","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the forces in Porter's five forces model?","options":["Threat of new entrants","Threat of substitutes","Bargaining power of suppliers","Sustainable competitive advantage for customers"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Porter's five forces are threat of new entrants, threat of substitutes, bargaining power of buyers, bargaining power of suppliers and current rivalry. Options A, B and C are all on that list. Option D is not a force; competitive advantage is what a firm seeks after analysing the forces."}},{"itemId":"e61ed485-db2a-5404-bb73-84482329367a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b7db9c4-f9c4-5f69-8df4-fcc79757c26e","sourceKey":"bank:AMS101:AMS101-T585","parentItemId":null,"revision":1,"payload":{"prompt":"What does a differentiation strategy require of a firm?","options":["Aggressively seeking efficiencies to keep the lowest cost structure","Being unique in what it offers","Seeking a cost advantage in a niche market","Being similar to competitors in all operations"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Differentiation means offering something unique that customers value, so they are willing to pay for it. Option A describes cost leadership, option C describes a cost-focus strategy, and option D is the opposite of differentiation."}},{"itemId":"33a2d995-3f11-5bbe-ba79-7342e025843a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e9a6aff-aac1-5d0a-aeb5-828c111161ea","sourceKey":"bank:AMS101:AMS101-T586","parentItemId":null,"revision":1,"payload":{"prompt":"What does a cost leadership strategy require of a firm?","options":["Aggressively seeking efficiencies to keep the lowest cost structure","Being unique in what it offers","Seeking a cost advantage in a niche market","Being similar to competitors in most operations"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Cost leadership means becoming the lowest-cost producer in the industry by relentlessly cutting costs and finding efficiencies. Option B is differentiation. Option C is tempting but describes a focus strategy, which targets a narrow segment rather than the whole industry."}},{"itemId":"2d806ac8-aa75-5b48-8c7e-68724219d1fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f67c788-5b75-5dd7-8b05-1f7da26b81aa","sourceKey":"bank:AMS101:AMS101-T588","parentItemId":null,"revision":1,"payload":{"prompt":"Under Porter's competitive strategies, which strategy aims to be unique in its industry in ways that customers widely value?","options":["Cost leadership","Differentiation","Focus","Stuck in the middle"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Differentiation means being unique in ways that customers value, such as quality, design or service. Option A competes on low cost, and option C targets a narrow segment. Option D describes a firm with no clear advantage at all."}},{"itemId":"214bae29-cc42-5572-ab67-082b1fd9400d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"197046c4-93c3-5c00-8937-f1c6d5e8f54d","sourceKey":"bank:AMS101:AMS101-T589","parentItemId":null,"revision":1,"payload":{"prompt":"Porter's framework names three generic competitive strategies: cost leadership, differentiation and ___________.","options":["depth","breadth","revenue growth","focus"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Porter's three generic strategies are cost leadership, differentiation and focus, where focus means pursuing a cost or differentiation advantage in a narrow segment. Options A, B and C are not part of his framework."}},{"itemId":"952c0a61-fc05-5121-85bd-3f45aeac3431","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b654c2e-041e-51e5-b8f6-dd7b2f6c0730","sourceKey":"bank:AMS101:AMS101-T591","parentItemId":null,"revision":1,"payload":{"prompt":"In Porter's five forces model, which force depends on how high the barriers to entry are, such as economies of scale and brand loyalty?","options":["Threat of substitutes","Threat of new entrants","Bargaining power of buyers","Bargaining power of suppliers"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Barriers to entry such as economies of scale and brand loyalty decide how easily new firms can enter, which is the threat of new entrants. Option A depends on switching costs and buyer loyalty to substitutes, and options C and D depend on bargaining factors such as concentration."}},{"itemId":"bae83d4a-e905-5b3e-b213-b5f4af228596","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c2f32445-da55-584d-b998-8e4cf9c29f22","sourceKey":"bank:AMS101:AMS101-T592","parentItemId":null,"revision":1,"payload":{"prompt":"In Porter's five forces model, which force depends on how concentrated suppliers are and whether substitute inputs exist?","options":["Threat of substitutes","Threat of new entrants","Bargaining power of buyers","Bargaining power of suppliers"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"When only a few suppliers exist and there are few substitute inputs, suppliers can push up prices, so these factors decide the bargaining power of suppliers. Option C concerns customers, not suppliers. Option A is about substitute products for customers, not substitute inputs for the firm."}},{"itemId":"2cd7a751-ed30-5aa4-894e-5f241901e4c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"08f79236-7b0c-5cde-a1dc-a570ca1a5a2c","sourceKey":"bank:AMS101:AMS101-T593","parentItemId":null,"revision":1,"payload":{"prompt":"In Porter's five forces model, which force depends on the industry's growth rate, rising or falling demand and differences between products?","options":["Threat of substitutes","Threat of new entrants","Bargaining power of buyers","Existing rivalry"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Industry growth, changes in demand and product differences shape how intensely current competitors fight one another, which is existing rivalry. Options A, B and C each depend on other factors, such as switching costs, entry barriers and buyer concentration."}},{"itemId":"90765ab1-ccfc-568a-9d98-229aba0e0780","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d7a95ca-e904-532f-bae5-3dc6f036a6b3","sourceKey":"bank:AMS101:AMS101-T596","parentItemId":null,"revision":1,"payload":{"prompt":"Functional-level strategy directly supports ___________.","options":["corporate-level strategy","business-level strategy","differentiation strategy","focus strategy"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Functional strategies, such as marketing, finance or production strategies, exist to support the business-level strategy. Option A is one level higher and is supported indirectly. Options C and D are particular competitive strategies, not a level of strategy."}},{"itemId":"a640dfd1-1403-5e30-acef-5d910a2fc3a0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cdccf400-5c5d-5fb2-ba84-22e4c83697b8","sourceKey":"bank:AMS101:AMS101-T597","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation runs several different businesses that are independent and formulate their own strategies, it is said to have ___________.","options":["operational units","strategic business units","competitive advantages","legal subunits"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Strategic business units (SBUs) are independent businesses within an organisation that develop their own strategies. Option C is what each business tries to achieve, and options A and D are not the standard term."}},{"itemId":"116b3f56-649d-5346-af81-ca8f6a6a381b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bfb907f2-bd6d-5d74-873b-689841762eff","sourceKey":"bank:AMS101:AMS101-T598","parentItemId":null,"revision":1,"payload":{"prompt":"When an organisation has a feature that sets it apart from competitors and gives it a distinct edge, this is an example of ___________.","options":["core competence","competitive power","legal propriety","competitive advantage"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Competitive advantage is what sets an organisation apart and gives it a distinctive edge over rivals. Option A is tempting, but core competencies are the skills and resources that can create that advantage, not the edge itself. Options B and C are not the standard term."}},{"itemId":"5e7d7321-63c5-5439-ae8c-36a86e4d128b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4908d0bd-f65b-5b66-8df6-bc8f025b7c1b","sourceKey":"bank:AMS101:AMS101-T599","parentItemId":null,"revision":1,"payload":{"prompt":"Commitment to quality and continuous improvement can set an organisation apart, but steady improvement and reliable products or services may lead to a competitive advantage that is ___________.","options":["weighted","sustainable","conservative","uncertain"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Constant improvement and reliability are hard for rivals to copy, so they can give a sustainable competitive advantage, one that lasts over time. Option D is the opposite, and options A and C do not describe competitive advantage."}},{"itemId":"9539368f-4bda-504a-8bf2-51630f36fdba","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8bba1e8d-ca37-5350-8e3d-432c829ce789","sourceKey":"bank:AMS101:AMS101-T600","parentItemId":null,"revision":1,"payload":{"prompt":"Switching costs and buyer loyalty are strategic factors that determine the ___________.","options":["threat of substitutes","threat of new entrants","bargaining power of buyers","bargaining power of suppliers"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Switching costs and buyer loyalty decide how likely customers are to move to a substitute product, so they shape the threat of substitutes. Option B is tempting because brand loyalty can also block newcomers, but the threat of new entrants is mainly about barriers such as economies of scale and capital requirements. Options C and D depend on how much bargaining power buyers or suppliers hold."}},{"itemId":"d5f43f2b-3208-52d1-9a72-066f2d5df5be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"55216076-0f8c-5f42-b241-d0b508d6aac1","sourceKey":"bank:AMS101:AMS101-T601","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main idea behind the 'rule of three'?","options":["No industry can support more than three 'super niche players'","There are usually only three 'full-line generalists'","Three companies usually hold most of the market share","Both B and C"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The rule of three holds that in competitive markets three full-line generalists usually emerge and together control most of the market, while smaller specialist players fill niches. Option A wrongly puts the limit on niche players instead of generalists, so D is the best answer."}},{"itemId":"c62d3a68-8885-5c75-b586-5117a8f0244c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ed671a3-cd51-53a9-8101-28d02aceb741","sourceKey":"bank:AMS101:AMS101-T603","parentItemId":null,"revision":1,"payload":{"prompt":"Senior managers must decide whether their innovation efforts will concentrate on ___________.","options":["basic research","product innovation","process development","all of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Innovation strategy involves choosing where to put the emphasis: basic scientific research, developing new products, or improving work processes. Since each of A, B and C is a possible emphasis, D is correct."}},{"itemId":"ca8f4e9e-15b5-5f2f-9af3-3cba584351fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"004af448-1bbd-5205-ad1f-bfeb1d379535","sourceKey":"bank:AMS101:AMS101-T604","parentItemId":null,"revision":1,"payload":{"prompt":"How do process development strategies try to build competitive advantage?","options":["By finding ways to improve existing work processes","By making the firm more efficient","By making the firm more effective","Both A and B"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Process development looks for ways to improve and enhance existing work processes so the firm runs more efficiently, for example at lower cost. Option C is not the main aim, because process development is about efficiency rather than effectiveness, so D is the best answer."}},{"itemId":"cbb131f2-38cf-55ca-956c-2efe1c160646","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f3943ee1-ecb9-538c-98d4-405cd321b070","sourceKey":"bank:AMS101:AMS101-T605","parentItemId":null,"revision":1,"payload":{"prompt":"An internet-based knowledge management system that shortens customer response times is an e-business technique that supports the competitive advantage of a ___________.","options":["cost leader","differentiator","focuser","star"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Faster, better responses to customers make a firm stand out on service, which supports a differentiation strategy. Option A is tempting because technology can cut costs, but the benefit here is speed of service, not lower cost. Option D is a BCG matrix category, not a competitive strategy."}},{"itemId":"57bcbcf1-57d3-51ad-bb23-cf45f98260ee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dde80ba3-c8df-55fc-a321-c2a00c85e222","sourceKey":"bank:AMS101:AMS101-T606","parentItemId":null,"revision":1,"payload":{"prompt":"What is the first organisation to bring a product or service to market usually called?","options":["Prime player","Market leader","First mover","Trailblazer"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The first mover is the organisation that is first to bring a product innovation to market or use a new process innovation. Option B is tempting, but a market leader is the firm with the largest share, which may not be the first one in. Options A and D are not the standard term."}},{"itemId":"dc7413fc-508d-5067-9f6b-fdcfd118a6f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f6ed527-b358-5756-accd-c1c387a03d02","sourceKey":"bank:AMS101:AMS101-T607","parentItemId":null,"revision":1,"payload":{"prompt":"Customer service strategies involve giving customers what they want, communicating effectively and ___________.","options":["giving employees incentives and bonuses for good service","giving employees customer service training","getting commitment from top management","none of the above"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A customer service strategy rests on giving customers what they want, communicating with them well and training employees in customer service. Options A and C may help in practice, but training is the element that completes this description."}},{"itemId":"86e2e6a0-cc33-58bd-9e3a-156c128eb102","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d773b06c-1edf-5360-aeb8-377ef59a9c40","sourceKey":"bank:AMS101:AMS101-T608","parentItemId":null,"revision":1,"payload":{"prompt":"Environmental scanning means screening large amounts of information to anticipate and ___________.","options":["track new laws being passed by lawmakers","interpret changes in the environment","fix failures in pollution-control equipment","forecast climate changes that will affect materials"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Environmental scanning is sifting through lots of information to spot and interpret changes in the environment. Option A is one narrow example of something that might be scanned. Options C and D take the word 'environment' to mean the natural environment, which is not what it means here."}},{"itemId":"4af03564-ed02-50bd-87d5-09426aae743f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"428731f1-9c02-548d-96c7-9dc1d4f04499","sourceKey":"bank:AMS101:AMS101-T609","parentItemId":null,"revision":1,"payload":{"prompt":"Experts in competitor intelligence suggest that about 80 percent of what managers need to know about competitors can be learned from ___________.","options":["firms that sell business information","the competitors' employees, suppliers and customers","the competitors' products, suppliers and customers","the managers' own employees, suppliers and customers"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Most of what managers need to know about competitors can be found through their own employees, suppliers and customers, who regularly deal with the wider market. Option B is tempting but would mean collecting information from rivals' people, which raises ethical concerns. Option A is a paid source, not the main one."}},{"itemId":"3b669d4c-be3c-5740-80d7-7395fc551ddf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2fb98f5b-3485-5e28-96a3-a9c771e7e645","sourceKey":"bank:AMS101:AMS101-T610","parentItemId":null,"revision":1,"payload":{"prompt":"When collecting competitor intelligence, there is often a thin line between what is legal and ethical and what is ___________.","options":["illegal but ethical","illegal and unethical","legal but unethical","practical and legal"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The difficulty with competitor intelligence is that some methods are within the law but still unethical, such as misleading people to get information. Option B is tempting, but illegal and unethical actions are clearly wrong, so the line is not 'thin' there. Options A and D do not describe the dilemma."}},{"itemId":"c40ae731-2e2c-5d39-ab33-47ab29eff629","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf6a2ef8-d5b8-54f7-b2a1-27c92d4ecde9","sourceKey":"bank:AMS101:AMS101-T611","parentItemId":null,"revision":1,"payload":{"prompt":"Many firms routinely buy competitors' products and let their engineers study them to learn about new technical features. What is this called?","options":["Competitor engineering","Competition engineering","Strategic engineering","Reverse engineering"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Reverse engineering is taking a competitor's product apart to learn how it works and what new technology it uses. Options A, B and C are not the standard term."}},{"itemId":"d5de9336-fbf9-50e3-8071-339ca929a448","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4883819c-7d19-5e68-b6b3-b2588c385df3","sourceKey":"bank:AMS101:AMS101-T612","parentItemId":null,"revision":1,"payload":{"prompt":"The value of global scanning depends largely on the ___________.","options":["amount of foreign competition in the market","prices foreign competitors charge","level of government regulation in the foreign market","extent of the organisation's own global activities"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Global scanning is most valuable to organisations with significant global activities, because they are most affected by international developments. Options A, B and C are things global scanning might track, but they do not determine how valuable it is to the organisation."}},{"itemId":"88084ff3-19c0-5035-9212-781f00f98f37","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2935cef2-7710-5c1e-85fd-d0711bf7d0b4","sourceKey":"bank:AMS101:AMS101-T613","parentItemId":null,"revision":1,"payload":{"prompt":"Which three tools can managers use to analyse their organisation's environment?","options":["Strategic planning, environmental scanning and TQM","Forecasting, budgeting and time management","Environmental scanning, forecasting and benchmarking","Benchmarking, planning and evaluating"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Environmental scanning, forecasting and benchmarking are the main techniques for assessing the environment. Options A, B and D each include one correct tool mixed with others, such as budgeting or TQM, that are not environmental analysis tools."}},{"itemId":"25afec76-f508-58c8-987e-5d9c267529b1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f5c5112d-c1e2-503d-81ff-16d0cbe04608","sourceKey":"bank:AMS101:AMS101-T614","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the fastest-growing areas of environmental scanning?","options":["Regression analysis","Competitor intelligence","Reengineering","Forecasting"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Competitor intelligence, which gathers information about who competitors are, what they are doing and how their actions will affect the organisation, is one of the fastest-growing forms of environmental scanning. Option D is a separate planning tool, and options A and C are not types of scanning."}},{"itemId":"ee6bf992-5b7c-5394-829a-8b11604e1f80","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c5a04b35-04be-53b2-b783-d752ee64e1d0","sourceKey":"bank:AMS101:AMS101-T615","parentItemId":null,"revision":1,"payload":{"prompt":"Competitor intelligence enables managers to do which of the following?","options":["React to competitors' actions","Cut costs below competitors'","Increase market diversification","Anticipate competitors' actions"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The purpose of competitor intelligence is to anticipate what competitors will do, so managers can act ahead of them. Option A is tempting, but merely reacting means you are already behind. Options B and C are separate strategic moves."}},{"itemId":"f233ad1e-cd69-53b8-9922-8e58aecdc1fd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d8c5f764-f13e-59fb-bb6b-ca8240a901f6","sourceKey":"bank:AMS101:AMS101-T618","parentItemId":null,"revision":1,"payload":{"prompt":"Environmental scanning lays the foundation for ___________.","options":["project management","forecasts","benchmarking","budgeting"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The information gathered through environmental scanning forms the basis for forecasts, which are predictions of future outcomes. Option C, benchmarking, is a separate tool based on comparing with best performers. Options A and D are not built on scanning in this way."}},{"itemId":"9d8dba97-24d7-50f5-982c-50d597ca95bc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3d12562d-36b7-52d8-961d-7b43fb51c1af","sourceKey":"bank:AMS101:AMS101-T619","parentItemId":null,"revision":1,"payload":{"prompt":"What has research found about companies with advanced environmental scanning systems?","options":["Their profits and revenue growth increased","They gathered more data but saw little change in profits and revenue growth","They no longer needed to make forecasts","Their profits and revenue growth fell"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Research found that companies with advanced environmental scanning systems increased their profits and revenue growth. Option C is wrong because scanning is the foundation for forecasts, not a replacement for them. Options B and D contradict the research."}},{"itemId":"2fd38749-58a9-581e-82ff-df75c3576047","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"73a587d2-1074-5017-98af-314deba0f1bf","sourceKey":"bank:AMS101:AMS101-T620","parentItemId":null,"revision":1,"payload":{"prompt":"Managers need forecasts that help them predict future events effectively and ___________.","options":["accurately","efficiently","specifically","in a timely manner"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Forecasts are only useful if they predict events effectively and arrive in time for managers to act on them. Option A sounds close, but accuracy is part of being effective; the extra requirement is timeliness. Options B and C are not the stated requirement."}},{"itemId":"5e53d8f0-96c9-58aa-b615-66fe163cfdef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9e3c43d-32f9-5a37-b207-f089a32c19f3","sourceKey":"bank:AMS101:AMS101-T621","parentItemId":null,"revision":1,"payload":{"prompt":"In quantitative forecasting, mathematical rules are applied to ____________.","options":["customers' opinions so that likely outcomes can be predicted","a set of historical data so that outcomes can be predicted","past events to work out exactly when they will happen again","the number of units that should be produced at a particular time"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Quantitative forecasting takes a series of past data and runs it through mathematical rules to predict what is likely to happen next. Option A describes qualitative forecasting, which relies on opinions and judgment rather than numbers. Options C and D are too narrow or overstate what a forecast can do."}},{"itemId":"aa7308f4-2d4d-56b1-bfed-a336942658d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e5bc2682-4e58-57dd-a07d-d1d3951cadc2","sourceKey":"bank:AMS101:AMS101-T622","parentItemId":null,"revision":1,"payload":{"prompt":"What is forecasting ultimately meant to give managers?","options":["exact predictions of future trends and events","ready-made decisions about what customers will want and when","information on how the environment is changing","information that helps them make decisions"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Forecasts exist to support decision making: they give managers information that helps them choose a course of action. Option A is wrong because no forecast can promise accurate predictions. Option B is wrong because forecasts inform decisions rather than make them, and option C is part of the picture but not the end goal."}},{"itemId":"44f61000-773b-5fee-93d0-c20026215135","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4b0eb88-9627-5520-82e1-53a0f37a8e02","sourceKey":"bank:AMS101:AMS101-T623","parentItemId":null,"revision":1,"payload":{"prompt":"A forecast tends to become less accurate as the ______________.","options":["amount of data used goes up","forecasting method becomes simpler","time period being predicted gets longer","number of customers grows"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The further into the future you try to predict, the more things can change, so accuracy drops as the forecast period gets longer. This is why shortening forecasts is a common tip. Option B is wrong because simple methods often do as well as, or better than, complex ones."}},{"itemId":"ab5edd6d-6e0a-558e-8cd0-03689165ad30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e7c33b33-25e5-5779-a005-914839b47e5e","sourceKey":"bank:AMS101:AMS101-T624","parentItemId":null,"revision":1,"payload":{"prompt":"Into which two broad groups are forecasting techniques usually divided?","options":["fixed asset and human capital","predictive and confirmatory","quantitative and qualitative","empirical and conceptual"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Forecasting techniques are either quantitative, using mathematical rules on past data, or qualitative, using the judgment of knowledgeable people. Options B and D sound technical but are not the standard way forecasting methods are classified. Option A refers to types of resources, not forecasting."}},{"itemId":"8b4e6bbf-de80-5302-99c7-05f50c3a3878","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"105b41fe-0829-545d-9184-84135a696448","sourceKey":"bank:AMS101:AMS101-T625","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos-based vehicle assembler decides to change the paint colours on its pickup trucks because it expects more women to buy such vehicles in future. Which environmental analysis tool does this illustrate?","options":["scenario","forecasting","benchmarking","anticipating"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The company is predicting a future outcome (more female buyers) and planning around that prediction, which is forecasting. Option A, a scenario, would involve playing out several possible situations rather than acting on one expected trend. Option C, benchmarking, means studying others' best practices, which is not happening here."}},{"itemId":"c7237bfe-afd8-58e7-8282-27f17efe3b3a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8fcabaa6-739d-5e70-9fcf-e982b39ac80a","sourceKey":"bank:AMS101:AMS101-T626","parentItemId":null,"revision":1,"payload":{"prompt":"Which forecasting technique is built on the judgment and opinions of knowledgeable people?","options":["qualitative","short-term","confirmatory","predictive"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Qualitative forecasting uses the views of people who know the field well, such as experts, managers or sales staff, to predict outcomes. Option B describes a time frame, not a technique based on judgment. Options C and D are not recognised categories of forecasting techniques."}},{"itemId":"f4b28be8-1824-5dfb-89fb-f0d2f21c1571","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6c5dbc4d-df53-527b-817e-da0d3ae8ccfe","sourceKey":"bank:AMS101:AMS101-T627","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a recommended way to make forecasting more effective?","options":["rely on complex forecasting sequences","collect as much data as you possibly can","always use global forecasting","use simple forecasting methods"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Simple forecasting methods often perform as well as complicated ones, so keeping methods simple is a standard tip. Option A is the opposite of this advice. Option B sounds sensible, but more data does not automatically produce a better forecast."}},{"itemId":"f40fcc22-9186-553f-baad-00346bf89573","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a383fb8e-815f-58d9-a331-a850de02cde7","sourceKey":"bank:AMS101:AMS101-T628","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recommended practice for improving forecasting effectiveness?","options":["avoid using a \"no change\" scenario","make forecasts that stretch beyond the next 2 years","apply the \"half-life\" estimation model","use more than one forecasting method"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Using several forecasting methods and comparing them gives a more reliable picture than depending on one method. Option A is wrong because comparing forecasts against a \"no change\" forecast is actually recommended. Option B is wrong because longer forecasts are less accurate."}},{"itemId":"1b8949b2-8839-562c-82c8-1d672aa0ed94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"607f7f6c-b6b0-5e5a-83e1-84f1e4404c8d","sourceKey":"bank:AMS101:AMS101-T629","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recommended way to improve forecasting effectiveness?","options":["build one single, effective method","focus on spotting turning points in trends","build complex and detailed mathematical models","make forecasts cover shorter periods"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Shorter forecasts are more accurate because there is less time for unexpected change, so shortening the length of forecasts is good advice. Option B is tempting, but managers are warned not to assume they can accurately identify turning points in a trend. Options A and C go against the advice to use multiple, simple methods."}},{"itemId":"7c6064ef-00fc-5293-9763-4679fd3a27c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f9528539-586e-5a02-8ddc-630579d6896f","sourceKey":"bank:AMS101:AMS101-T631","parentItemId":null,"revision":1,"payload":{"prompt":"In qualitative forecasting, outcomes are predicted using the judgment and opinions of __________.","options":["customers and suppliers","distributors and suppliers","executives","knowledgeable individuals"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Qualitative forecasting draws on anyone with relevant knowledge, so \"knowledgeable individuals\" is the full and correct answer. Options A, B and C each name groups who might be consulted, but they are only examples and are too narrow."}},{"itemId":"6214321a-eb42-50e2-bcb2-de101704b293","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0568bb2c-92d8-51b5-8ad3-e003ecda113b","sourceKey":"bank:AMS101:AMS101-T632","parentItemId":null,"revision":1,"payload":{"prompt":"Forecasting techniques give the most accurate results when the environment is __________.","options":["changing in an inverse way","dynamic over the long term, so turning points can be seen","not changing rapidly","seasonal but not cyclical"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Forecasts rely on the past being a guide to the future, so they work best when the environment is fairly stable and not changing quickly. Option B is wrong because a dynamic environment makes forecasting harder, and turning points are hard to identify. Options A and D are not the condition that makes forecasts most accurate."}},{"itemId":"a86fe002-595b-5a72-adc4-1b6a9d56c034","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f0bc21d6-180a-575a-8b52-cf4344a547da","sourceKey":"bank:AMS101:AMS101-T633","parentItemId":null,"revision":1,"payload":{"prompt":"If every forecast is compared with a forecast that assumes no change in the environment, roughly how often does the no-change forecast turn out to be accurate?","options":["about half of the time","about three-fourths of the time","about four-thirds of the time","about 80 percent of the time"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A no-change forecast is right roughly half of the time, which is why managers are advised to compare their forecasts against it as a check. Option C is impossible since nothing can be accurate more than all of the time. Options B and D overstate how often the no-change forecast is correct."}},{"itemId":"a65f2ed9-724d-5c4e-9206-ecd8be9e8b4a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"40131a3e-886d-5b2f-983d-d41e33468101","sourceKey":"bank:AMS101:AMS101-T634","parentItemId":null,"revision":1,"payload":{"prompt":"Benchmarking means looking for the best practices of competitors or noncompetitors that result in their ____________.","options":["very large market share","ability to predict the environment so accurately","superior performance","ability to find new market niches"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Benchmarking is the search for the best practices that lead to superior performance, so an organization can learn from them and improve. Options A and D may be results of good performance, but they are narrower than what benchmarking aims at. Option B is about forecasting, not benchmarking."}},{"itemId":"c30bc251-ed1b-5b20-9f96-5053386e7e1d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a46c61a6-0687-57da-9ac3-03b997cc32fa","sourceKey":"bank:AMS101:AMS101-T635","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about benchmarking is correct?","options":["It must always involve studying a competitor.","It works best when you study firms within your own industry.","It can involve studying a company that makes a completely different product.","Foreign companies should not be benchmarked because of cultural differences."],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Benchmarking looks for best practices among competitors or noncompetitors, so a firm can learn a great deal from a company in a totally different line of business. Option A is wrong because noncompetitors can be benchmarked too. Options B and D wrongly limit where good practices can be found."}},{"itemId":"fb3984b1-ab73-5fb1-81db-9d89b926b6a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5c7e6d42-d633-56ee-b716-02606319416c","sourceKey":"bank:AMS101:AMS101-T637","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about budgets is accurate?","options":["they are not usually used for estimating time","they can only ever be financial","they can be used to plan the use of space in an organization","they are normally used for both large and small capital expenditures"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Budgets are numerical plans, and they can cover things other than money, such as time, space and material resources, so space planning is a valid use. Option B is wrong for the same reason. Option A is wrong because time budgets exist, and option D is wrong because capital expenditure budgets are mainly for large investments such as new equipment or buildings."}},{"itemId":"c1d33049-17fd-54ce-b503-4088344377ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9e176080-fe94-54e5-8cbe-3e493bc780f1","sourceKey":"bank:AMS101:AMS101-T638","parentItemId":null,"revision":1,"payload":{"prompt":"A budget is a plan, expressed in numbers, for allocating resources ____________.","options":["to specific activities","set aside for special projects","areas of production","developing new products"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A budget is a numerical plan for allocating resources to specific activities, whether those are revenues, expenses, time or materials. Options B, C and D each describe only one possible use of a budget and are too narrow to be the definition."}},{"itemId":"2abf132f-adca-5e8d-9a35-2c2fcc7e0912","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"70c4e6d5-e3e9-5c52-8cfd-ad3e299f400a","sourceKey":"bank:AMS101:AMS101-T639","parentItemId":null,"revision":1,"payload":{"prompt":"Budgets are probably so popular because they can be applied to many different kinds of organizations and to ___________.","options":["setting how much money will be spent","stating how much money the organization will receive","work activities within organizations","estimating how many units will be produced"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Budgets are widely used because they fit almost any type of organization and almost any work activity inside it. Options A, B and D are each specific things a budget can do, but they do not explain the broad appeal that makes budgets so popular."}},{"itemId":"f073a382-996e-5deb-b02e-4c6aba09550f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e62213e7-3d8c-5130-81e2-7e5dc301b5fd","sourceKey":"bank:AMS101:AMS101-T640","parentItemId":null,"revision":1,"payload":{"prompt":"Many managers dislike preparing budgets because they see the process as time-consuming, inflexible, inefficient and ____________.","options":["infallible","inflationary","insignificant","ineffective"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The common complaint about budgeting is that it takes too long, is rigid, is inefficient and does not achieve its purpose, which is what \"ineffective\" means. Option A means \"never wrong\", which would be a compliment, not a complaint. Options B and C are not the usual criticisms."}},{"itemId":"81191896-5f7d-5df1-b266-82f20f25ce9a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2076f64e-eb3c-5f1d-a1af-8bdea5a8eddb","sourceKey":"bank:AMS101:AMS101-T641","parentItemId":null,"revision":1,"payload":{"prompt":"Budgeting is an important management activity because it brings financial discipline and structure __________.","options":["to the cash side of the organization only","across the whole organization","to the parts of the organization that need it most","mainly to start-up companies"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Budgeting matters because it forces financial discipline and structure throughout the entire organization, not just in one area. Options A, C and D each limit that effect to one part of the organization or one type of firm."}},{"itemId":"6844c292-3e2c-5072-a5f2-84b1784a512b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d12ef7bf-308b-57d9-8f85-1a605d473f0e","sourceKey":"bank:AMS101:AMS101-T642","parentItemId":null,"revision":1,"payload":{"prompt":"Henry Gantt, who created the Gantt chart in the early 1900s, was an associate of which scientific management pioneer?","options":["Henri Fayol","Fredrich Traylor","Henry Ford","Frederick Taylor"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Frederick Taylor is known as the father of scientific management, and Henry Gantt worked with him before developing the Gantt chart. Option A, Henri Fayol, is linked to general administrative theory, not scientific management. Option B is a misspelt name, and option C is an industrialist, not a scientific management theorist."}},{"itemId":"66d33bf3-fedd-5608-bfce-10b8c8d7c583","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"609af469-bcba-57a5-8e1a-47872ef053ec","sourceKey":"bank:AMS101:AMS101-T643","parentItemId":null,"revision":1,"payload":{"prompt":"A Gantt chart shows visually when tasks are supposed to be done and compares this with the ____________.","options":["supervisors' estimate of when work will be finished","actual progress made on each task","scheduled delivery of materials","delivery date the customer has asked for"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A Gantt chart puts planned timing side by side with actual progress on each task, so managers can see what is ahead of or behind schedule. Options A, C and D are other pieces of information, but the chart's key comparison is planned versus actual progress."}},{"itemId":"540ff497-14c8-517f-ab86-940723d50474","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77356830-fa8e-50c8-86cb-b22db5ca7fbb","sourceKey":"bank:AMS101:AMS101-T644","parentItemId":null,"revision":1,"payload":{"prompt":"Gantt charts were created to help managers with _____________.","options":["budgeting","benchmarking","regression analysis","scheduling"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"A Gantt chart is a scheduling tool: it shows when activities should happen and tracks their progress over time. Option A deals with allocating money, option B with learning from others' best practices, and option C is a statistical forecasting method."}},{"itemId":"47d4568a-2706-574d-90b1-e9a4f62c3e44","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca60580f-e31d-5e02-9268-e5678ce48324","sourceKey":"bank:AMS101:AMS101-T645","parentItemId":null,"revision":1,"payload":{"prompt":"A Gantt chart is basically a bar graph that shows __________ axis and __________ axis.","options":["time on the vertical; the activities to be scheduled on the horizontal","time on either; the activities to be scheduled on the other","time on the vertical; project completion on the horizontal","time on the horizontal; the activities to be scheduled on the vertical"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"On a Gantt chart, time runs along the horizontal axis and the activities to be scheduled are listed down the vertical axis, with bars showing how long each takes. Option A swaps the two axes. Option B is wrong because the layout is fixed, not interchangeable."}},{"itemId":"9f449bd5-8462-5ded-8a2f-7c41a3e47a32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b9e36044-917e-5512-9d9c-9ad09c63978d","sourceKey":"bank:AMS101:AMS101-T646","parentItemId":null,"revision":1,"payload":{"prompt":"On the vertical axis, a load chart lists either departments or _____________.","options":["functional areas","specific resources","budgets","product weights"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A load chart is a modified Gantt chart that lists either whole departments or specific resources down the side, so managers can plan and control how much capacity is being used. Option A is close to \"departments\" but is not the alternative used. Options C and D have nothing to do with capacity scheduling."}},{"itemId":"0e4f800b-a451-5fc1-b371-e87e8ddc3821","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a430f14-78d6-53d3-a4ec-4ac3edc4f661","sourceKey":"bank:AMS101:AMS101-T647","parentItemId":null,"revision":1,"payload":{"prompt":"The Program Evaluation and Review Technique (PERT) is particularly helpful for scheduling _____________.","options":["projects","programs","processes","planning"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"PERT is designed for scheduling complex projects with many activities, some of which depend on others being finished first. Option B may look right because of the word \"Program\" in the name, but the technique is used for projects. Options C and D do not describe what PERT schedules."}},{"itemId":"a9daed65-3479-5cee-8159-614db1d979c1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9cd7e970-3f9f-513f-bd73-d6fd2006e98b","sourceKey":"bank:AMS101:AMS101-T648","parentItemId":null,"revision":1,"payload":{"prompt":"To build a PERT network you need four terms: events, activities, ____________ and ____________.","options":["crucial path; slack time","critical path; estimated time","crucial path; earliest date","slack time; critical path"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"The four key PERT terms are events, activities, slack time and critical path. Option B is tempting because \"critical path\" is correct, but \"estimated time\" is not one of the four terms. Options A and C use \"crucial path\", which is not the correct term."}},{"itemId":"a0a039c6-0758-5b25-92d8-ec586049d739","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2544a6f2-d191-55ea-9889-263dea7befe0","sourceKey":"bank:AMS101:AMS101-T649","parentItemId":null,"revision":1,"payload":{"prompt":"A PERT network shows the order of activities required to finish a project and the __________ each activity.","options":["estimated day of","time or costs linked to","amount of money required for","step of"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A PERT network maps out the sequence of activities and the time or costs associated with each one. Option C mentions money only, so it leaves out time, which is central to PERT. Options A and D do not capture what the network records."}},{"itemId":"e3d9736c-6b7f-5d36-9600-f106c7e1ece3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eebd5f47-64d8-58b3-bf18-38c9c5a38d57","sourceKey":"bank:AMS101:AMS101-T650","parentItemId":null,"revision":1,"payload":{"prompt":"In a PERT network, what are events?","options":["end points marking the completion of major activities","the longest, most time-consuming sequence of events in the network","how long a single activity can be delayed without delaying the whole project","every key activity needed to finish a project"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Events are the end points that show when major activities have been completed. Option B describes the critical path, option C describes slack time, and option D describes activities rather than events."}},{"itemId":"d15fae07-c08e-55cf-ae0b-d887b65cb3a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de09ad79-c66c-578f-8f24-6d67d8af28cf","sourceKey":"bank:AMS101:AMS101-T651","parentItemId":null,"revision":1,"payload":{"prompt":"In the PERT process, which element is an end point showing that a major activity has been completed?","options":["critical paths","events","checkpoints","sections"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Events are end points that mark the completion of major activities. Option A, the critical path, is the longest sequence of events and activities. Option C sounds plausible but is not one of the PERT terms."}},{"itemId":"debfee42-37c6-5b75-b29b-515e1dd6a415","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89d04af6-ede0-5bcf-86f3-62a8abe3d95c","sourceKey":"bank:AMS101:AMS101-T652","parentItemId":null,"revision":1,"payload":{"prompt":"Which PERT element represents the time or resources needed to move from one event to the next?","options":["events","critical paths","checkpoints","activities"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Activities are the time or resources required to progress from one event to another. Option A is wrong because events are the end points, not what happens between them. Option B, the critical path, is the most time-consuming chain of events and activities."}},{"itemId":"0a7355a6-31c3-5f92-bad1-c353de00b849","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fc022005-b6e5-5655-82ac-b9079b00d32c","sourceKey":"bank:AMS101:AMS101-T653","parentItemId":null,"revision":1,"payload":{"prompt":"What does the critical path refer to in the PERT process?","options":["the central line that other activities feed into","the checkpoint for comparing completion standards","the most time-consuming sequence of events and activities","the most expensive path in a schedule"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The critical path is the longest, most time-consuming sequence of events and activities, so any delay on it delays the whole project. Option D is tempting, but the critical path is defined by time, not cost. Options A and B do not describe the critical path."}},{"itemId":"a6154b29-373a-5337-8f45-e1e6edc5bf1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d95ec4a0-8007-5e43-a18e-8a3cb6e8c256","sourceKey":"bank:AMS101:AMS101-T654","parentItemId":null,"revision":1,"payload":{"prompt":"Which technique is commonly used to help managers make profit projections?","options":["factor analysis","cost accounting","breakeven analysis","PERT"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Breakeven analysis shows the point at which total revenue covers total costs, which helps managers project profits at different sales levels. Option D, PERT, is a scheduling tool. Option B records costs but is not the technique used for profit projections here."}},{"itemId":"644ca932-5745-5645-a7eb-5dcc69b63e38","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f728d1e6-c490-5efa-b6c5-99d80bf46b73","sourceKey":"bank:AMS101:AMS101-T655","parentItemId":null,"revision":1,"payload":{"prompt":"The manager of a clothing store in Ikeja wants to know how many denim jackets must be sold to hit a certain profit target. Which planning tool is the manager using?","options":["breakeven analysis","PERT","Gantt chart","cost accounting"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Working out how many units must be sold to cover costs and reach a profit goal is exactly what breakeven analysis does. Options B and C are scheduling tools that deal with time, not sales volume. Option D tracks costs but does not by itself link sales volume to profit."}},{"itemId":"a1a1db28-314a-5ec9-8692-d2746094f572","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ee88e4a-8c83-5af8-930c-c2dce378d2a3","sourceKey":"bank:AMS101:AMS101-T656","parentItemId":null,"revision":1,"payload":{"prompt":"Breakeven analysis is a popular resource allocation technique that helps managers make _____________.","options":["estimates of total project cost","projections like PERT, but in costs rather than time","profit projections","estimates of fixed and variable costs"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Breakeven analysis helps managers make profit projections by showing how many units must be sold before the organization starts making a profit. Option D is tempting because fixed and variable costs are inputs to the analysis, but estimating them is not its purpose. Option B wrongly treats it as a version of PERT."}},{"itemId":"34c8b025-4afb-53e1-b6a9-3c1ad57db34b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eb0a5ad8-03cb-5d7a-a338-6794dbe2704b","sourceKey":"bank:AMS101:AMS101-T657","parentItemId":null,"revision":1,"payload":{"prompt":"To calculate the breakeven point, a manager must know the unit selling price, the variable cost per unit and _______________.","options":["the total number of units sold","the fixed cost per unit sold","total fixed costs","none of the above"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The breakeven point is found by dividing total fixed costs by the difference between price and variable cost per unit, so total fixed costs are the missing input. Option A is what the calculation helps you find, not an input. Option B is wrong because fixed costs per unit change with volume, so the total figure is used."}},{"itemId":"fb5d9e33-205e-5c37-94fb-0a66daf2168c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c7c74e66-2365-501b-809c-2082282448c4","sourceKey":"bank:AMS101:AMS101-T658","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is an example of a fixed cost?","options":["property taxes","energy costs","labour costs","raw materials"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Fixed costs stay the same no matter how much is produced, and property taxes are a classic example, along with rent and insurance. Options B, C and D usually rise and fall with output, which makes them variable costs."}},{"itemId":"b2d63dea-5a25-58fa-9d74-3bf166f79f2a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d0a6b09-b0c4-5c77-9298-6bb989a01f1a","sourceKey":"bank:AMS101:AMS101-T659","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following are applications of linear programming?","options":["choosing transportation routes that keep shipping costs as low as possible","sharing an advertising budget among different plans","assigning personnel to projects in the best way","all of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Linear programming helps managers allocate limited resources to get the best outcome, so it applies to choosing transport routes, splitting an advertising budget and assigning staff to projects. Since options A, B and C are all valid uses, option D is correct."}},{"itemId":"13aec7c3-a5ec-58c0-836c-ed6dc46fae6c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da086c49-67de-5f65-bf7a-3e542137d3ed","sourceKey":"bank:AMS101:AMS101-T660","parentItemId":null,"revision":1,"payload":{"prompt":"Because linear programming needs limited resources and an outcome to optimize, it ____________.","options":["cannot be used for every resource allocation problem","can be used for every profit allocation problem","can be used for every resource allocation problem","works out lost time"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Linear programming only works when certain conditions are met, such as limited resources, an outcome to optimize and linear relationships between variables, so it cannot be applied to every resource allocation problem. Options B and C are wrong because they claim it works everywhere. Option D does not describe linear programming."}},{"itemId":"a52d13a8-5ee6-569a-be99-03dd68d897e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"322e1e22-f016-5264-842f-8a9c5c17f84c","sourceKey":"bank:AMS101:AMS101-T661","parentItemId":null,"revision":1,"payload":{"prompt":"When variables in a linear programming model have a linear relationship, a change in one variable must be matched by a(n) ______________.","options":["even straight line drawn between the two points","exactly proportional change in the other variable","estimated change in profit in the other","equal absolute change in the other"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A linear relationship means that when one variable changes, the other changes in exact proportion. Option D is tempting, but the change must be proportional, not necessarily the same absolute amount. Option A describes a graph rather than the relationship itself."}},{"itemId":"044ae011-5582-5632-b939-9eb5f8457a9b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"979066e9-9cae-50c7-b8fc-0312f94c5eb7","sourceKey":"bank:AMS101:AMS101-T662","parentItemId":null,"revision":1,"payload":{"prompt":"An organization breaks even at the point where its total revenue exactly equals its __________.","options":["fixed cost","breakeven costs","variable costs","total cost"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Breakeven is the point where total revenue covers total cost, meaning there is neither profit nor loss. Options A and C are each only part of total cost, so covering just one of them is not breakeven. Option B is not a real cost category."}},{"itemId":"93e6ba7a-cca8-5ee5-ba7b-f199d6999bca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"56083271-5073-5351-9acc-5168717ebe1c","sourceKey":"bank:AMS101:AMS101-T663","parentItemId":null,"revision":1,"payload":{"prompt":"Before a project can be planned, every activity in it and the resources needed to carry it out must be ____________.","options":["satisfied","on hand","identified","trained"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Project planning starts by identifying all the activities in the project and the resources each one needs, so the work can then be sequenced and scheduled. Option B is wrong because resources do not need to be physically available at the planning stage. Options A and D do not make sense for activities and resources."}},{"itemId":"d08a3375-e386-5e47-b865-095dd69a161f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6c4b4373-a8f2-5e2b-964e-5767f991cd1c","sourceKey":"bank:AMS101:AMS101-T664","parentItemId":null,"revision":1,"payload":{"prompt":"Being a project manager is still a hard role because the people being managed ______________.","options":["will make mistakes during the project","may not turn up on the day of an important presentation","lack the skills to take part in the project","are still tied to their permanent work areas"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Project team members usually keep their links to their home departments, so the project manager has limited direct authority over them. Options A, B and C describe problems that could happen anywhere, but they are not the built-in reason the role is difficult."}},{"itemId":"fe6c4e20-9198-555f-a974-561da7e980df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"881415b5-a214-5c2b-bbb9-017928aab204","sourceKey":"bank:AMS101:AMS101-T665","parentItemId":null,"revision":1,"payload":{"prompt":"A project is a one-time set of activities with _______________.","options":["clear assessment stages over time","important points to be analyzed","a definite beginning and end point in time","an estimated start and finish date"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"What makes something a project is that it happens once and has a definite start and a definite end. Option D is close, but \"estimated\" dates are weaker than the clear beginning and ending that define a project. Options A and B do not capture the definition."}},{"itemId":"256bb541-ebe4-564c-b770-1475b9ed447f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"08898574-3aca-54c1-a69b-e7c2f1fd2412","sourceKey":"bank:AMS101:AMS101-T666","parentItemId":null,"revision":1,"payload":{"prompt":"Project management means getting a project's activities completed on time, within budget and __________.","options":["by following directions","by adjusting plans","according to specifications","within the limits of city engineering"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Project management is the task of getting activities done on time, within budget and according to specifications, meaning the work meets the required standard. Option B may happen along the way, but it is not part of the definition. Options A and D are not the third element."}},{"itemId":"4e62a53d-20af-5b5f-acf5-a515ecab0018","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"81f8532a-4155-5f18-9a35-c49e532c206b","sourceKey":"bank:AMS101:AMS101-T667","parentItemId":null,"revision":1,"payload":{"prompt":"What is the only real source of influence that project managers have?","options":["their ability to keep the project moving","their communication skills and power of persuasion","the supplier's ability to deliver","insisting that the project be finished according to plan"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Because team members still report to their own departments, project managers cannot simply give orders; they rely on communication skills and persuasion to get things done. Option D assumes formal authority they usually do not have. Option C is outside the manager's control altogether."}},{"itemId":"adc55ea0-ead4-54df-a30a-9303f091b394","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3608330f-c3db-57d6-8ee8-84b13a0a92ba","sourceKey":"bank:AMS101:AMS101-T668","parentItemId":null,"revision":1,"payload":{"prompt":"Another way to describe developing scenarios is ______________.","options":["planning","thinking about what will happen","guessing what will change","contingency planning"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Developing scenarios means preparing for different possible futures, which is why it is also called contingency planning. Option A is too general, since all plans are planning. Options B and C miss the idea of preparing responses for several possible situations."}},{"itemId":"069ca10e-cd5f-53ee-9a90-25fe3cd02f02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e591e15f-0b42-5a4c-9d57-a7ed20f9fcfd","sourceKey":"bank:AMS101:AMS101-T669","parentItemId":null,"revision":1,"payload":{"prompt":"When a scenario is built on different assumptions, the result is likely to be ________________.","options":["different outcomes","the same estimates","arguments about which one is right","divergent ideas turning into results"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A scenario is a view of what the future is likely to be under certain assumptions, so changing the assumptions leads to different outcomes. Option B is the opposite of this. Option C might happen in practice, but it is not what the assumptions themselves produce."}},{"itemId":"467b9d52-6fe8-5c63-af32-17877e0b244d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7e65e8cb-095f-5f78-a43c-eae2c6c71dee","sourceKey":"bank:AMS101:AMS101-T670","parentItemId":null,"revision":1,"payload":{"prompt":"Scenario planning helps with events that can be anticipated, but it is hard to use it to ____________.","options":["set deadlines","prepare for higher sales of output","present the facts when they happen","forecast random events"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Scenario planning works for things that can be foreseen, but random, unexpected events are very difficult to forecast or plan for. Options A and B are things scenario planning can actually help with. Option C does not describe a limitation of scenario planning."}},{"itemId":"5fc0db2c-eb1a-5789-953b-ef29dcb40a35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b868bce2-9ca9-5bd5-a20e-2fd3f34b734c","sourceKey":"bank:AMS101:AMS101-T671","parentItemId":null,"revision":1,"payload":{"prompt":"What is the name for the task of completing activities on time, within budget and according to specifications?","options":["breakeven analysis","linear programming","probability analysis","project management"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Getting activities done on time, within budget and to specification is the definition of project management. Option A deals with profit projections, option B with allocating limited resources, and option C with estimating likelihoods."}},{"itemId":"2e825dcb-c754-5ea9-884d-d6b8292f8188","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a7439892-794d-508e-904b-dd0d8a7b51f5","sourceKey":"bank:AMS101:AMS101-T672","parentItemId":null,"revision":1,"payload":{"prompt":"When managers assess the environment, they are likely to uncover issues and concerns that could affect current or planned operations, and these issues __________.","options":["will not all be equally important","will not all be equally associated","will all be equally important","will be as important as each other, but not of equal value"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Environmental assessment usually reveals many issues, but they will not all be equally important, so managers must focus on the ones that matter most. Option C is the opposite. Option D contradicts itself, and option B does not describe importance at all."}},{"itemId":"82d794bc-590f-5e40-bc9f-d5620d7a68e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da2f4552-0ac2-5d69-8c61-f3f67713e2fa","sourceKey":"bank:AMS101:AMS101-T673","parentItemId":null,"revision":1,"payload":{"prompt":"Scenario planning is not meant to predict the future; instead, it reduces uncertainty by __________.","options":["working out possible profits under different conditions","pretending customer needs differ from the forecast","imagining a different market mix","playing out possible situations under different specified conditions"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Scenario planning reduces uncertainty by playing out potential situations under different specified conditions, so managers are ready for several possible futures. Option A focuses only on profit, which is too narrow. Options B and C describe single assumptions rather than the full approach."}},{"itemId":"69468842-8b4b-5341-8ffd-61ccf760d43c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0eb103f0-c775-5a2a-b1f9-3838e95ceab6","sourceKey":"bank:AMS101:AMS101-T674","parentItemId":null,"revision":1,"payload":{"prompt":"Planning tools and techniques can help managers __________.","options":["prepare confidently for the future","prepare future events","prepare better budgets","prepare larger projects"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"The purpose of planning tools and techniques is to help managers prepare confidently for the future. Option C is one benefit of budgeting, but it is too narrow. Option B does not make sense, since managers prepare for events, not the events themselves."}},{"itemId":"854a514e-45ad-58b5-b04a-a5f027774f3d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a6f28afe-1a11-5281-bf05-4891239bf6af","sourceKey":"bank:AMS101:AMS101-T675","parentItemId":null,"revision":1,"payload":{"prompt":"Planning tools and techniques can never take the place of the manager's __________ in using the information to build effective and efficient plans.","options":["formal authority and job title","skills and capabilities","motivation and leadership","time and effort"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning tools only supply information; it takes the manager's own skills and capabilities to turn that information into effective and efficient plans. Option A is wrong because a job title or formal authority does not build a plan by itself. Options C and D can help a manager, but they are not what turns the information into good plans."}},{"itemId":"a4100065-eda2-5c02-8587-1099946a03cf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"163af870-1afb-5857-b552-1963da2ad68e","sourceKey":"bank:AMS101:AMS101-T676","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational design involves decisions about ____________.","options":["work specialization and departmentalization","chain of command and span of control","centralization and decentralization","all of the above"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Organizational design is built on six key elements: work specialization, departmentalization, chain of command, span of control, centralization/decentralization and formalization. Options A, B and C each name some of these, so all of them are correct and D is the answer."}},{"itemId":"464015d5-ed92-5365-bb90-ef94ba8db501","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4295de96-dbe4-52bf-af04-729df2855630","sourceKey":"bank:AMS101:AMS101-T677","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these correctly defines work specialization?","options":["how far tasks are divided into separate jobs","each employee focuses on part of an activity rather than the whole activity","jobs are ranked only by their worth or value to the business","a and b"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Work specialization is the degree to which tasks are divided into separate jobs, which means each person does part of an activity instead of all of it. Options A and B describe the same idea from two angles, so D is correct. Option C describes job evaluation, not specialization."}},{"itemId":"6257b955-0435-529d-a547-e075ddf7d943","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0cc13ce-1110-5c01-b316-9cce1ac5d619","sourceKey":"bank:AMS101:AMS101-T678","parentItemId":null,"revision":1,"payload":{"prompt":"What is the basis by which jobs are grouped together so that organizational goals can be achieved?","options":["departmentalization","centralization","formalization","coordination"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Departmentalization is how jobs are grouped together, for example by function, product, geography, process or customer. Option B is about where decisions are made, and option C is about how standardized jobs are. Option D is a goal of grouping, not the grouping itself."}},{"itemId":"a4cb72ea-6dc0-5509-be32-2fa1e19d4100","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ac9ced1-4b70-5175-a3d0-24b8c748bb2d","sourceKey":"bank:AMS101:AMS101-T679","parentItemId":null,"revision":1,"payload":{"prompt":"A company splits its sales team into South-West, South-East, North-Central, North-West and South-South regions. What type of departmentalization is this?","options":["product","geographic","process","outcome"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Grouping jobs by territory or physical location is geographic departmentalization. Option A would group jobs by product line, and option C by the flow of products or customers. Option D is not a standard form of departmentalization."}},{"itemId":"2e1a00c6-1e99-5a14-a4ba-bd9a92b707bf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4cb10478-cbe1-5636-895a-9a64492bd2c0","sourceKey":"bank:AMS101:AMS101-T680","parentItemId":null,"revision":1,"payload":{"prompt":"When activities are grouped according to how customers flow through the organization, this is _____________.","options":["functional departmentalization","product departmentalization","geographical departmentalization","process departmentalization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Process departmentalization groups activities according to the flow of products or customers, like the different stages at a licensing office. Option A groups by function, option B by product line and option C by location."}},{"itemId":"a9265f20-3026-52fd-a65e-e8966a43ac34","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ef37b429-ef94-59a4-9059-394a584c45e0","sourceKey":"bank:AMS101:AMS101-T681","parentItemId":null,"revision":1,"payload":{"prompt":"A government agency divides its public service work into separate units for employers, children and people with disabilities. Which kind of departmentalization is this?","options":["product","geographic","outcome","customer"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Grouping work around the specific needs of different client groups is customer departmentalization. Option B would group by location, and option A by what is produced. Option C is not a standard type of departmentalization."}},{"itemId":"9f73cea0-2e39-5cf7-b5c3-085f7851cf31","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"100fdb21-0046-5370-b209-df01cfbe9f4c","sourceKey":"bank:AMS101:AMS101-T682","parentItemId":null,"revision":1,"payload":{"prompt":"In today's competitive business environment, which type of departmentalization has become much more important?","options":["geographic","customer","product","process"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Firms now focus heavily on understanding and responding to customer needs, so customer departmentalization has grown in importance. Options A, C and D are still used, but they are not the type that competition has pushed to the front."}},{"itemId":"8c352b82-4a47-542e-8c16-3c7ff6f5df42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8c266a93-04fe-584c-adea-c278a500cc34","sourceKey":"bank:AMS101:AMS101-T683","parentItemId":null,"revision":1,"payload":{"prompt":"Functional departmentalization groups jobs according to ______________.","options":["the functions or tasks they perform","the territories they cover","the products or services they make","the type of customer they serve"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Functional departmentalization puts together jobs that perform the same function, such as accounting, marketing or production. Option B describes geographic, option C product and option D customer departmentalization."}},{"itemId":"8dd85a14-27d8-5a55-b0ee-9e4e05350d87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"43fd2b99-e302-51da-925e-621135314d1b","sourceKey":"bank:AMS101:AMS101-T684","parentItemId":null,"revision":1,"payload":{"prompt":"Putting designers, production workers and salespeople into one work group to develop a new product creates a ________________ team.","options":["differentiated","product","cross-functional","weak"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A cross-functional team brings together people from different functional areas, here design, production and sales, to work on a shared task. Option B may seem right because they are working on a product, but the team is defined by mixing functions. Options A and D are not the correct term."}},{"itemId":"5a0a5477-5555-56fe-87bf-c849e686c441","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dcc97618-6d16-5425-9ebf-4c67b409a799","sourceKey":"bank:AMS101:AMS101-T685","parentItemId":null,"revision":1,"payload":{"prompt":"Which term do managers use for the degree to which tasks in an organization are divided into separate jobs?","options":["work specialization","departmentalization","chain of command","span of control"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Work specialization is the degree to which tasks are split into separate jobs. Option B is about grouping those jobs together, option C is the line of authority, and option D is the number of people a manager supervises."}},{"itemId":"2c6a198f-c15d-5df6-8285-5902f348235f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d5a3747b-aaa0-5322-9c13-34892aebf9d7","sourceKey":"bank:AMS101:AMS101-T686","parentItemId":null,"revision":1,"payload":{"prompt":"Departmentalization based on _______________ groups jobs by territory or physical location.","options":["function","product","geography","matrix"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Geographic departmentalization groups jobs according to territory or location, such as regions or countries. Option A groups by function, option B by product line, and option D is a structure that combines functions and projects."}},{"itemId":"ccd67dd1-c5a9-5173-93b4-d1d0edb64e7b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"22bcd49e-cc54-5ad3-84f6-b5c499e5a6f4","sourceKey":"bank:AMS101:AMS101-T689","parentItemId":null,"revision":1,"payload":{"prompt":"What is the unbroken line of authority running from the top levels of management down to the lowest levels of the organization called?","options":["authorized line of responsibility","unity of command","responsibility factor","chain of command"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The chain of command is the continuous line of authority from the top to the bottom of the organization, showing who reports to whom. Option B is related, but it is the principle that each person reports to only one manager. Options A and C are not standard terms."}},{"itemId":"96ee923e-8245-530c-8c95-45c1ae752633","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"371488a9-21df-5a5e-a3cb-aadcd3e39b6f","sourceKey":"bank:AMS101:AMS101-T690","parentItemId":null,"revision":1,"payload":{"prompt":"______________ is the set of rights attached to a position that lets a manager tell subordinates what to do and expect them to do it.","options":["Responsibility","Unity of command","Chain of command","Authority"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Authority is the right that comes with a managerial position to give orders and expect them to be followed. Option A is the obligation to perform a duty, which is different from the right to give instructions. Options B and C describe reporting relationships."}},{"itemId":"b9a2f568-0649-54d0-bb6c-4239d8d65732","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a846686d-5be6-5c75-8fc2-748434282670","sourceKey":"bank:AMS101:AMS101-T691","parentItemId":null,"revision":1,"payload":{"prompt":"________________ is the obligation or expectation to carry out a duty.","options":["Responsibility","Unity of command","Chain of command","Span of control"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Responsibility is the obligation or expectation to perform assigned duties. Options B and C deal with reporting relationships, and option D is the number of people a manager supervises."}},{"itemId":"463ff93d-c948-5cca-bebc-b47fae7ef1c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0635667b-30d1-5c45-aeae-0dc86645cfa9","sourceKey":"bank:AMS101:AMS101-T692","parentItemId":null,"revision":1,"payload":{"prompt":"What is the principle that each person should report to only one manager called?","options":["authorized line of responsibility","unity of command","responsibility factor","chain of command"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Unity of command says each employee should report to only one manager, which avoids conflicting instructions. Option D is the overall line of authority from top to bottom, not the one-boss rule. Options A and C are not standard terms."}},{"itemId":"01db44dc-87a4-55c1-a2b9-17c3be71cff0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce0b60fe-8a9d-5d11-ba65-7a23a5aae916","sourceKey":"bank:AMS101:AMS101-T693","parentItemId":null,"revision":1,"payload":{"prompt":"Which of Fayol's 14 principles of management helps keep the idea of a continuous line of authority intact?","options":["unity of demand","unity of command","demand structure","continuous demand"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Unity of command means each person reports to only one superior, which helps keep an unbroken line of authority running through the organisation. Option A sounds similar but is not one of Fayol's principles, and options C and D are not real principles either."}},{"itemId":"1bde975d-e37c-5494-a809-241780da4fb3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e83b7098-2e0c-579d-aeee-691b2e22cffb","sourceKey":"bank:AMS101:AMS101-T694","parentItemId":null,"revision":1,"payload":{"prompt":"Which concept describes how many subordinates report to a manager and, indirectly, how many levels of management an organization will have?","options":["authorized line of responsibility","unity of command","responsibility factor","span of control"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Span of control is the number of employees a manager can efficiently supervise, and it largely decides how many management levels an organization needs. Option B is about reporting to one boss, not about how many people report to a manager. Options A and C are not standard terms."}},{"itemId":"384861d6-240c-587a-b0fb-392aa62a0c9f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f8a083c-9d79-536e-b7ba-7cffd0100417","sourceKey":"bank:AMS101:AMS101-T695","parentItemId":null,"revision":1,"payload":{"prompt":"What has been the trend in organizations in recent years?","options":["narrower spans of control","longer chains of command","structures based on financial position","wider spans of control"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Organizations have moved toward wider spans of control, with managers supervising more people, to cut costs and speed up decisions. Option A is the opposite of the trend. Option B is also wrong, since wider spans usually mean fewer levels."}},{"itemId":"7108a052-4fab-5331-b208-da6398a0499d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"abde547e-fbb0-52a9-a599-b1de6a40b968","sourceKey":"bank:AMS101:AMS101-T696","parentItemId":null,"revision":1,"payload":{"prompt":"Other things being equal, as the span of control becomes wider, the organizational design becomes more _____________.","options":["bureaucratic","democratic","effective","efficient"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A wider span of control means fewer managers and fewer levels are needed, which lowers costs and makes the organization more efficient. Option C is tempting, but wider spans do not automatically make an organization more effective, since managers may have less time for each employee. Option A is wrong because wider spans usually reduce layers."}},{"itemId":"5e342fde-581c-5165-9ca2-f6a1893b19f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e6ac4c24-9832-5580-b1d8-34e045607a05","sourceKey":"bank:AMS101:AMS101-T699","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which decision making is concentrated at a single point in an organization is called ____________.","options":["unity of command","chain of command","span of management","centralization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Centralization describes how far decision making is kept at one point, usually at the top of the organization. Option A is the rule of reporting to one manager, and option B is the line of authority. Option C is another name for span of control."}},{"itemId":"48d219ad-e17b-5712-84ce-caddf981be8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b68e3b30-c80b-5113-b847-07438c14aceb","sourceKey":"bank:AMS101:AMS101-T700","parentItemId":null,"revision":1,"payload":{"prompt":"In recent years, organizations have tried to become more flexible and responsive through _____________.","options":["centralization","decentralization","alternative organizational structures","customer-based structures"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Decentralization pushes decision making down to the people closest to the problem, which makes organizations more flexible and responsive. Option A does the opposite by keeping decisions at the top. Options C and D are not the specific movement being described."}},{"itemId":"8728e9d9-af69-52a8-9359-4c9b39db6c02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e1e00854-d869-5ccb-bd4c-15a2165b52c2","sourceKey":"bank:AMS101:AMS101-T701","parentItemId":null,"revision":1,"payload":{"prompt":"What is the degree to which jobs are standardized and guided by rules and procedures called?","options":["work specialization","centralization","decentralization","formalization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Formalization is how far jobs are standardized and governed by rules and procedures. Option A is about dividing tasks into separate jobs. Options B and C are about where decisions are made."}},{"itemId":"27587f46-64ff-5866-b2b3-387d4a8aa1e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c3a8001e-e9c1-51cc-8ca6-9c43ece1fdec","sourceKey":"bank:AMS101:AMS101-T703","parentItemId":null,"revision":1,"payload":{"prompt":"Which kind of organization is tightly controlled and efficient?","options":["organic","horizontal","learning","mechanistic"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A mechanistic organization is rigid and tightly controlled, with high specialization, strict rules and centralized decisions, which makes it efficient. Option A, organic, is the flexible and adaptive opposite. Options B and C describe other designs, not rigid control."}},{"itemId":"41a0a8e8-8c55-50d2-b929-aa3e75b17a2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f024622-7a35-5ffd-a9c0-104dae02549a","sourceKey":"bank:AMS101:AMS101-T704","parentItemId":null,"revision":1,"payload":{"prompt":"Which kind of organization can change quickly whenever needs demand it?","options":["organic","horizontal","vertical","mechanistic"],"correctOption":0,"section":"Organization Design and Structure","explanation":"An organic organization is highly adaptive and flexible, so it can change rapidly as needs require. Option D, mechanistic, is the rigid opposite. Options B and C refer to the shape of a structure rather than its adaptability."}},{"itemId":"6e7ce841-0b8b-535d-9107-dfa372089914","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f9176835-13b8-5e6f-980a-1fc77046cc77","sourceKey":"bank:AMS101:AMS101-T705","parentItemId":null,"revision":1,"payload":{"prompt":"When managers use rules and procedures to standardize how employees behave, those jobs are becoming more _____________.","options":["diversified","formalized","vertical","horizontal"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Formalization is the use of rules and procedures to standardize jobs and behaviour, so the jobs are becoming more formalized. Option A suggests more variety, which is the opposite. Options C and D describe structure shape, not standardization."}},{"itemId":"c9bb715a-16d5-50f6-98ec-598353e16549","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a51552c-b417-56db-b8ef-b493ec21d034","sourceKey":"bank:AMS101:AMS101-T706","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes the link between structure and strategy?","options":["structure follows strategy","strategy follows structure","strategy and structure are always treated equally","strategy follows structure in smaller organizations"],"correctOption":0,"section":"Organization Design and Structure","explanation":"An organization's structure should be designed to support its strategy, so when strategy changes, structure should change too, which is what \"structure follows strategy\" means. Option B reverses the relationship. Options C and D are not the accepted view."}},{"itemId":"cecb524a-d6ab-568d-834d-e0b16eadaa38","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3be7c6c6-e088-556b-b0ca-98004fad68f8","sourceKey":"bank:AMS101:AMS101-T707","parentItemId":null,"revision":1,"payload":{"prompt":"When linking strategy to structure, most strategic frameworks focus on ______________.","options":["pursuing meaningful and unique innovation","pursuing tightly controlled costs","reducing risk and increasing profit chances by copying market leaders","all of the above"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Most strategic frameworks centre on three directions: innovation, cost minimization and imitation, which is copying market leaders to reduce risk. Options A, B and C each describe one of these, so D is correct."}},{"itemId":"8603c198-154c-5a97-88bd-f6b8989cc233","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4041838-60f9-5b8b-b790-85150ab5f781","sourceKey":"bank:AMS101:AMS101-T708","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of technology is based on large-batch production and needs a moderate level of complexity and sophistication?","options":["unit production","mass production","process production","service production"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Mass production means large-batch manufacturing with moderate technical complexity. Option A, unit production, makes items in single units or small batches, while option C, process production, involves continuous processing and is the most complex. Option D is not one of the production technologies studied."}},{"itemId":"326bf92e-8880-5a52-8f42-8e1f6e2863ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a74afc0a-9ec9-5e1d-933e-7a7b19f0bab8","sourceKey":"bank:AMS101:AMS101-T711","parentItemId":null,"revision":1,"payload":{"prompt":"Structure is linked to organizational size: larger organizations usually have more ____________.","options":["specialization","departmentalization","centralization","all of the above"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Large organizations tend to have more specialization, more departmentalization, more centralization and more rules than small ones. Since options A, B and C are all true, D is the correct answer."}},{"itemId":"6d862add-4126-5cfd-ace1-2d039a9833a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d9945bd-36d4-58ba-9494-43f1f9fbb59c","sourceKey":"bank:AMS101:AMS101-T712","parentItemId":null,"revision":1,"payload":{"prompt":"Because structure is linked to size, larger organizations tend to be more _____________.","options":["mechanistic","organic","structurally weak","decentralized"],"correctOption":0,"section":"Organization Design and Structure","explanation":"As organizations grow, they add specialization, rules and layers, which makes them more mechanistic. Option B is the opposite, and option D does not match the typical pattern for large firms. Option C is not how size and structure are linked."}},{"itemId":"665ac10e-37ca-5d2c-a76c-14afe8a4d637","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d4abfe2-e8d7-56df-9daa-565b0a38c21c","sourceKey":"bank:AMS101:AMS101-T713","parentItemId":null,"revision":1,"payload":{"prompt":"In Joan Woodward's research on technology and structure, which type of production was the most technically complex?","options":["unit production","mass production","process production","technological production"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Woodward ranked process production, which involves continuous processing, as the most technically complex. Option A, unit production, is the least complex, and option B, mass production, is in the middle. Option D was not one of her categories."}},{"itemId":"92acc219-e056-5014-9e70-0bad3cf37a92","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e21c1440-0cfb-5f4e-8df3-5014850b5652","sourceKey":"bank:AMS101:AMS101-T714","parentItemId":null,"revision":1,"payload":{"prompt":"Woodward's studies found which type of production works best with a mechanistic structure?","options":["unit","process","product","mass"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Woodward found mass production firms did best with a mechanistic structure, while unit and process production firms did best with organic structures. So options A and B are wrong, and option C is not one of her production types."}},{"itemId":"045e513a-f39d-53fc-bb60-f22b9d863e81","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90e83929-ca53-570d-b586-1ca577c70aee","sourceKey":"bank:AMS101:AMS101-T715","parentItemId":null,"revision":1,"payload":{"prompt":"Research on how structure relates to environmental uncertainty shows that organizations facing greater uncertainty tend to be more ____________.","options":["organic","mechanistic","technologically pure","supportive of technological change"],"correctOption":0,"section":"Organization Design and Structure","explanation":"When the environment is uncertain, organizations need to adapt quickly, so they do better with flexible, organic structures. Option B suits stable environments instead. Options C and D are not the structural response to uncertainty."}},{"itemId":"0c3d521c-24fb-5d81-b559-e393fbe8ae56","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d561320e-e3b4-59d0-8d4c-0dd643fb6fed","sourceKey":"bank:AMS101:AMS101-T716","parentItemId":null,"revision":1,"payload":{"prompt":"Global competition, faster product development by rivals and customers demanding better service have pushed organizations to become more _____________.","options":["organic","mechanistic","technologically pure","task oriented"],"correctOption":0,"section":"Organization Design and Structure","explanation":"These pressures create a fast-changing, uncertain environment, and organic structures are flexible enough to respond to it. Option B is the rigid design that suits stable conditions. Options C and D are not the structural shift these pressures encourage."}},{"itemId":"9665804f-cecb-52c5-b7ef-4c792147c691","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb57dc1f-6b85-5e04-8354-b38ef0cd570d","sourceKey":"bank:AMS101:AMS101-T717","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these would you most likely find in a mechanistic organization?","options":["a wide span of control","empowered employees","decentralized responsibility","standardized, specialized jobs"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Mechanistic organizations rely on high specialization and standardized jobs governed by rules. Options A, B and C, wide spans, empowerment and decentralization, are features of organic organizations."}},{"itemId":"a80602bc-a32c-59e8-a73e-be2f1f5b1a0d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0937a68a-f9ad-5870-8db8-118d8c3fde84","sourceKey":"bank:AMS101:AMS101-T718","parentItemId":null,"revision":1,"payload":{"prompt":"In its early years, a young technology company wanted very skilled, creative employees who worked with very few rules. What type of organization does this best illustrate?","options":["bureaucratic","mechanistic","volatile","organic"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Hiring highly skilled, creative people and giving them few rules is a mark of an organic organization, which relies on flexibility and trust. Options A and B describe rigid, rule-bound structures. Option C is not a standard type of structure."}},{"itemId":"30a07439-5f98-5685-9d93-d863c598f20f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dfbe99e9-3fd9-59ad-8133-cd2b90db5ade","sourceKey":"bank:AMS101:AMS101-T719","parentItemId":null,"revision":1,"payload":{"prompt":"Which environment suits mechanistic organizations best?","options":["dynamic","manufacturing","service","stable"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Mechanistic structures are efficient when conditions are stable and predictable, because rules and routines rarely need to change. Option A, a dynamic environment, calls for organic structures. Options B and C are industries, not environmental conditions."}},{"itemId":"a41a9488-bf85-558e-b7fe-df84e6d8e10d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bcf9efe8-f34c-59de-a5a0-0242607b609d","sourceKey":"bank:AMS101:AMS101-T720","parentItemId":null,"revision":1,"payload":{"prompt":"Choosing the right structure depends on four contingency variables: strategy, size, degree of environmental uncertainty and _________________.","options":["technology","history","leadership","intensity of competition"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The four contingency factors that shape structure are strategy, size, technology and environmental uncertainty. Option D may seem related, but competition is part of environmental uncertainty, not a separate factor. Options B and C are not among the four."}},{"itemId":"ad0367a8-58e5-5e91-ac60-ceedf175593c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65cf492d-131d-5e10-982b-81c26ac4a3f1","sourceKey":"bank:AMS101:AMS101-T721","parentItemId":null,"revision":1,"payload":{"prompt":"Joan Woodward's research on technology and structure was based on small manufacturing firms located in _________________.","options":["the northeastern United States","the south of Wales","France","southern England"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Woodward studied small manufacturing firms in southern England and grouped them by their production technology. Option B is also in Britain, which makes it tempting, but the firms were in England, not Wales. Options A and C are the wrong countries."}},{"itemId":"dc684bd6-314d-5e80-ba68-35e6b0b4415f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a3304ad2-04db-5be2-9bcf-1b0fa90c2b4f","sourceKey":"bank:AMS101:AMS101-T722","parentItemId":null,"revision":1,"payload":{"prompt":"Traditional organizational designs are usually more mechanistic and include _______________.","options":["simple, functional and corporate structures","simple, functional and business unit structures","functional, strategic and business unit structures","simple, functional and divisional structures"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The three traditional designs are the simple, functional and divisional structures. Options A, B and C each swap in a term, such as corporate, business unit or strategic, that is not one of the traditional designs."}},{"itemId":"5dd30836-813a-5b3b-a0b7-7c3e4f80a7cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d88aa59f-e83a-5cd9-8693-04df58b1ee8b","sourceKey":"bank:AMS101:AMS101-T723","parentItemId":null,"revision":1,"payload":{"prompt":"A small business with little departmentalization, wide spans of control, centralized authority and little formalization has a ________________ structure.","options":["simple","functional","divisional","matrix"],"correctOption":0,"section":"Organization Design and Structure","explanation":"These features describe a simple structure, typical of small businesses run by an owner-manager. Option B groups similar specialties together, option C uses self-contained units, and option D combines functions and projects."}},{"itemId":"aff6ae17-17b5-55b9-a776-89e4aaa3714d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e623b29e-347a-5a23-a152-c39b18174b5a","sourceKey":"bank:AMS101:AMS101-T724","parentItemId":null,"revision":1,"payload":{"prompt":"As an organization takes on more employees, its structure usually becomes more ______________.","options":["specialized","informal","centralized","a and b"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Growth usually brings more specialization and formalization, since more people need clearer divisions of work and more rules. Option B is wrong because structure becomes more formal, not informal, so option D is also wrong. Option C is not the pattern described here."}},{"itemId":"451632bd-425f-5ecf-b3e5-e4c6bd00ff57","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cab3a2c5-92a9-5435-9ba5-4db85f009e35","sourceKey":"bank:AMS101:AMS101-T726","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a feature of a simple organizational structure?","options":["high departmentalization","wide spans of control","decentralized authority","high formalization"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A simple structure has low departmentalization, wide spans of control, authority centralized in one person and little formalization. Options A, C and D are the opposites of those features."}},{"itemId":"f39e45ed-0500-5d2a-89ab-1236ebc607bb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7af6e4c2-f6c1-5df9-ac6d-83f8b3a97928","sourceKey":"bank:AMS101:AMS101-T727","parentItemId":null,"revision":1,"payload":{"prompt":"A divisional structure groups different sets of jobs that are linked by _______________.","options":["the product produced","the service offered","a cost advantage in a niche market","a and b"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A divisional structure is made of separate units organized around a product, service or market, so both the product produced and the service offered fit. That makes D correct. Option C is a strategy outcome, not the basis for forming divisions."}},{"itemId":"adb6cf69-5567-5793-aa79-8d5dad9c57cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab1fa9ad-d1e2-5afd-9435-ef36ed108b11","sourceKey":"bank:AMS101:AMS101-T728","parentItemId":null,"revision":1,"payload":{"prompt":"A matrix structure combines features of functional departmentalization with _______________.","options":["product departmentalization","process departmentalization","a dual chain of command","a narrow span of control"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A matrix structure blends functional departmentalization with product (or project) departmentalization, so employees work in a function and on a product or project at the same time. Option C is a result of this mix rather than the second type of grouping. Options B and D are not what is combined."}},{"itemId":"617336c6-7682-5e95-a754-a6a472499529","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ee3b2c7-c3df-5104-bb18-d38c80685e4a","sourceKey":"bank:AMS101:AMS101-T729","parentItemId":null,"revision":1,"payload":{"prompt":"Which key element of organizational design does the matrix structure break?","options":["unity of command","chain of command","span of management","decentralization"],"correctOption":0,"section":"Organization Design and Structure","explanation":"In a matrix structure, employees report to both a functional manager and a project manager, which breaks unity of command, the rule of having one boss. Option B is tempting, but a chain of command still exists; the problem is having two. Options C and D are not violated by the matrix."}},{"itemId":"5ea3b7e1-e3e0-5d70-99d9-e3f39cc1218d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9988574e-6830-53a2-a4e4-39d9d49a45a1","sourceKey":"bank:AMS101:AMS101-T730","parentItemId":null,"revision":1,"payload":{"prompt":"A __________________ organization is a small core organization that outsources major functions such as manufacturing so it can focus on what it does best.","options":["network","virtual","modular","learning"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A network organization keeps a small core and relies on outside suppliers for major functions like manufacturing, so it can concentrate on its core competencies. Option B uses temporary outside specialists for projects, and option C uses suppliers for components that it assembles. Option D is about the capacity to learn and adapt."}},{"itemId":"1d9bbf53-fa63-5798-b356-f74b4d166ba3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e1abccf7-7b30-5a39-aea6-ac16f20d5b79","sourceKey":"bank:AMS101:AMS101-T731","parentItemId":null,"revision":1,"payload":{"prompt":"A ______________ organization has a small core of full-time staff and temporarily brings in outside specialists to work on opportunities as they come up.","options":["network","virtual","modular","learning"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A virtual organization has a small core of full-time employees and hires outside specialists temporarily when opportunities arise. Option A outsources whole business functions to suppliers. Option C uses suppliers for product components."}},{"itemId":"aabc55ff-f2ea-5fb4-a294-d3582afc60e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bebfdf74-56e9-5094-beb2-270aeb5066a2","sourceKey":"bank:AMS101:AMS101-T732","parentItemId":null,"revision":1,"payload":{"prompt":"A learning organization is one that has built up its _______________.","options":["training department to keep employees skilled","capacity to keep adapting and changing","barriers that keep others out of its markets","competitive advantage that is easy to keep"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A learning organization has developed the capacity to continuously learn, adapt and change. Option A is tempting, but a training department alone does not make an organization a learning organization. Options C and D are not part of the definition."}},{"itemId":"4911cb36-d3a1-5829-9287-0dd8d5bf1b58","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ef3c45b0-a67a-5a11-9edc-9a182d006d90","sourceKey":"bank:AMS101:AMS101-T733","parentItemId":null,"revision":1,"payload":{"prompt":"A ________________ organization relies on outside suppliers for product components, which it then assembles into finished products.","options":["network","virtual","modular","learning"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A modular organization gets components or modules from outside suppliers and assembles them into final products. Option A outsources whole business functions, and option B uses temporary specialists. Option D is about adapting through learning."}},{"itemId":"0cdb3d5e-9d6b-52e6-b04f-3ada25382bfc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db494700-7d34-5b8b-adf0-ad76ce77b6bf","sourceKey":"bank:AMS101:AMS101-T734","parentItemId":null,"revision":1,"payload":{"prompt":"A _____________ design is not restricted by the horizontal, vertical or external boundaries that a conventional structure imposes.","options":["learning organization's","threatened organization's","functional","boundaryless organization's"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A boundaryless organization is designed so that it is not limited by the horizontal, vertical or external boundaries of a traditional structure. Option C, functional, is a traditional design with clear boundaries. Option A is about the capacity to learn, which is related but not the definition."}},{"itemId":"e8f29102-2fef-5d5e-b316-c3011f1c2f94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e39025eb-c0d0-5603-a7c7-4e50fdc50edc","sourceKey":"bank:AMS101:AMS101-T735","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of organization takes specialists from different functional departments and assigns them to one or more projects headed by a project manager?","options":["classical","contemporary","matrix","evolutionary"],"correctOption":2,"section":"Organization Design and Structure","explanation":"In a matrix organization, specialists from various functional departments are assigned to projects led by project managers. Option B is a broad category that includes the matrix, but it is not the specific design described. Options A and D are not types of structure."}},{"itemId":"902edd3b-1b6a-5551-b12c-b4fd310f75cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0c7d42b-011c-54cd-bcc6-a7c6a62b1e0d","sourceKey":"bank:AMS101:AMS101-T736","parentItemId":null,"revision":1,"payload":{"prompt":"An online wine shop sells and delivers hundreds of wines to customers around the world but has only six employees. Which structure is it most likely to have?","options":["bureaucratic","simple","functional","divisional"],"correctOption":1,"section":"Organization Design and Structure","explanation":"With so few employees, the business most likely has a simple structure: little departmentalization, wide spans of control and centralized authority. Options A, C and D are suited to larger organizations with more specialization and layers."}},{"itemId":"6f1ce616-6a8e-58e7-ad8d-c82eca2cd89d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"369f010b-1bd4-5cf5-bf03-cfb411e7199c","sourceKey":"bank:AMS101:AMS101-T737","parentItemId":null,"revision":1,"payload":{"prompt":"Which organizational structure is made up of autonomous, self-contained units?","options":["bureaucratic","simple","functional","divisional"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A divisional structure consists of separate, self-contained units or divisions, each run by a manager responsible for its results. Option C groups similar specialties together rather than forming independent units. Option B has almost no separate units at all."}},{"itemId":"04afb301-cc0d-559b-9465-acb3ab19ae3c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5c8b2e89-b635-5697-9895-f4084d7392f1","sourceKey":"bank:AMS101:AMS101-T738","parentItemId":null,"revision":1,"payload":{"prompt":"In which type of organizational structure is empowerment most important?","options":["bureaucratic","simple","functional","team-based"],"correctOption":3,"section":"Organization Design and Structure","explanation":"In a team-based structure, the whole organization is made up of work teams that make decisions themselves, so empowering employees is essential. Options A and C rely more on formal authority and rules. Option B keeps authority with the owner."}},{"itemId":"3b1a265b-be2e-5c6a-8496-7a3752976837","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d072a180-8703-5c64-9058-eb540944b41e","sourceKey":"bank:AMS101:AMS101-T740","parentItemId":null,"revision":1,"payload":{"prompt":"A _____________ structure's strength is its focus on results, but its weakness is that activities and resources are easily duplicated.","options":["simple","functional","divisional","matrix"],"correctOption":2,"section":"Organization Design and Structure","explanation":"In a divisional structure, each division manager is responsible for results, which is its strength, but each division often has its own staff and resources, which causes duplication. Option B is efficient precisely because it avoids duplication. Option A's weakness is dependence on one person."}},{"itemId":"2a6afdf6-c389-5e5c-b68e-d4f2c2b36230","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"744485b2-57a4-59f2-82e4-33842ab388fb","sourceKey":"bank:AMS101:AMS101-T741","parentItemId":null,"revision":1,"payload":{"prompt":"The ______________ structure is a more advanced form of the matrix in which employees work continuously on assignments aimed at completing tasks.","options":["Weighted","Functional","Conservative","Project"],"correctOption":3,"section":"Organization Design and Structure","explanation":"In a project structure, employees continuously work on projects instead of returning to functional departments, which takes the matrix idea further. Option B is a traditional structure built around functions. Options A and C are not organizational structures."}},{"itemId":"e3cab031-4a2f-5d28-a4ad-3211d0e5053b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c173dd1-5d0f-5309-b571-9fbb89589d63","sourceKey":"bank:AMS101:AMS101-T742","parentItemId":null,"revision":1,"payload":{"prompt":"Some organizational theorists argue that an organization's ability to __________ may be its only lasting source of competitive advantage.","options":["learn","apply what it learns","change","a and b"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The argument is that the ability to learn and to apply that learning may be the only sustainable competitive advantage, so both A and B are needed and D is correct. Option C, change, is related, but the claim is specifically about learning and applying it."}},{"itemId":"9c38c87b-c4fb-51b4-86fa-3ef548d698ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a0521e2-5d1f-51c9-a459-f74c7129cc2d","sourceKey":"bank:AMS101:AMS101-T743","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational learning cannot happen without ____________.","options":["motivation","goals","information","structure"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Learning depends on sharing information, so without information an organization cannot learn. Options A, B and D can support learning, but information is the essential ingredient."}},{"itemId":"20b4bffc-b7c3-51c9-b2ee-0eed40a7bcc1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a3826008-da85-5b6f-be85-72e24a0a3c37","sourceKey":"bank:AMS101:AMS101-U001","parentItemId":null,"revision":1,"payload":{"prompt":"Management is best defined as:","options":["Supervising employees only.","Coordinating resources to achieve goals.","Delegating authority effectively.","Monitoring employee behavior."],"correctOption":1,"section":"Managers and Management","explanation":"Management is the process of coordinating resources, including people, money and equipment, so that the organization reaches its goals efficiently and effectively. Option A is too narrow, because supervising people is only one part of what managers do. Options C and D are also single activities within management, not a definition of it."}},{"itemId":"c86f1558-a577-51f3-8cf5-555e76eb955d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d0fe23e-7c96-5ea4-9447-5efdce72ea28","sourceKey":"bank:AMS101:AMS101-U002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best represents 'efficiency'?","options":["Maximizing profits.","Reducing costs while achieving goals.","Expanding operations globally.","Increasing employee satisfaction."],"correctOption":1,"section":"Managers and Management","explanation":"Efficiency means \"doing things right\": getting results while wasting as few resources as possible, so reducing costs while still achieving goals fits it best. Option A, maximizing profits, is an outcome rather than a description of resource use. Options C and D describe growth and morale, not efficiency."}},{"itemId":"7f98bc32-7c6f-5994-b0f7-695298f5d1bb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8bea3d4e-7d6e-506e-a4eb-0dfb944cb96c","sourceKey":"bank:AMS101:AMS101-U003","parentItemId":null,"revision":1,"payload":{"prompt":"Effectiveness in management focuses on:","options":["Minimizing resources used.","Meeting organizational goals.","Delegating tasks.","Monitoring employee performance."],"correctOption":1,"section":"Managers and Management","explanation":"Effectiveness means \"doing the right things\", that is, carrying out the tasks that help the organization reach its goals. Option A, minimizing resources used, describes efficiency, which is about means rather than ends. Options C and D are activities, not the focus of effectiveness."}},{"itemId":"e8c55139-a1cf-551a-84dd-72b8bd562dd6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dbe4e968-babe-5ccd-9b1b-f5ddcf9ddfb2","sourceKey":"bank:AMS101:AMS101-U004","parentItemId":null,"revision":1,"payload":{"prompt":"Which term describes the process of using minimal resources to achieve goals?","options":["Effectiveness.","Coordination.","Efficiency.","Discipline."],"correctOption":2,"section":"Managers and Management","explanation":"Efficiency is getting the most output from the least input, so using minimal resources to achieve goals is exactly what it means. Option A, effectiveness, is about whether goals are achieved at all, not how few resources were used. Coordination and discipline (B and D) are separate management ideas."}},{"itemId":"6a7c6b6d-2bae-5ab6-b422-7a7e0ded69a7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b545435-0685-5617-acc7-412d3f3e88f0","sourceKey":"bank:AMS101:AMS101-U005","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an example of effective management?","options":["Delivering products before deadlines.","Cutting expenses drastically.","Hiring more employees than needed.","Increasing wages without a budget."],"correctOption":0,"section":"Managers and Management","explanation":"Effectiveness is judged by whether goals are actually met, and delivering products before deadlines shows the target was achieved. Option B, cutting expenses drastically, is about saving resources and can even hurt goal attainment. Options C and D waste resources, so they show poor management."}},{"itemId":"e6347621-40bb-56f3-b876-71aed7b63957","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b9e4a44-5f4a-55ae-a9db-e3cf43b1074a","sourceKey":"bank:AMS101:AMS101-U006","parentItemId":null,"revision":1,"payload":{"prompt":"What is the first step in management functions?","options":["Leading.","Organizing.","Controlling.","Planning."],"correctOption":3,"section":"Managers and Management","explanation":"Planning comes first because it sets the goals and the ways to achieve them; the other functions follow from the plan. Organizing (B) arranges work to carry out the plan, leading (A) directs people doing it, and controlling (C) checks performance against the plan, so none of them can come before it."}},{"itemId":"26e31b5c-8c46-55cf-92d1-990c376b15c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ac2d2a5-206b-51b7-a7f6-618466dd567c","sourceKey":"bank:AMS101:AMS101-U007","parentItemId":null,"revision":1,"payload":{"prompt":"Planning involves:","options":["Monitoring employee output.","Setting goals and deciding how to achieve them.","Organizing resources effectively.","Motivating employees."],"correctOption":1,"section":"Managers and Management","explanation":"Planning means defining what the organization wants to achieve and working out the strategies to get there. Option A, monitoring output, is controlling, while C is organizing and D is part of leading."}},{"itemId":"7c127bdc-f5c9-5034-8acd-4d122242bf1c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8485f0e5-fdd5-5e98-9f6b-7544ba3aaf39","sourceKey":"bank:AMS101:AMS101-U008","parentItemId":null,"revision":1,"payload":{"prompt":"Organizing resources includes:","options":["Allocating duties among staff.","Creating a motivating environment.","Evaluating plans periodically.","Writing daily task lists."],"correctOption":0,"section":"Managers and Management","explanation":"Organizing means arranging and structuring work, which includes dividing up duties and deciding who does what. Option B, creating a motivating environment, belongs to leading, and C, evaluating plans, belongs to controlling. Writing daily task lists (D) is too narrow to describe the function."}},{"itemId":"c1735679-ed00-596d-9932-3afd19ff234d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ae59e81-445e-57d1-b657-049972b9bc86","sourceKey":"bank:AMS101:AMS101-U009","parentItemId":null,"revision":1,"payload":{"prompt":"Leading as a management function involves:","options":["Setting measurable goals.","Directing and motivating employees.","Monitoring resources effectively.","Dividing work equally."],"correctOption":1,"section":"Managers and Management","explanation":"Leading is the function of directing, motivating and influencing people so they work toward the organization's goals. Option A, setting measurable goals, is planning, C is controlling, and D is part of organizing."}},{"itemId":"8cdb923f-da41-519d-bf15-4d3d2f2c6109","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6c4b5b39-23fc-57d8-9930-b873ebe5d8f1","sourceKey":"bank:AMS101:AMS101-U011","parentItemId":null,"revision":1,"payload":{"prompt":"Who introduced the principles of management?","options":["Peter Drucker.","Henri Fayol.","Elton Mayo.","Frederick Taylor"],"correctOption":1,"section":"Managers and Management","explanation":"Henri Fayol, a French industrialist, set out 14 principles of management and the basic functions managers perform. Frederick Taylor (D) is known for scientific management, the \"one best way\" to do a job, not for general principles of management. Elton Mayo (C) is linked to the Hawthorne studies, and Peter Drucker (A) wrote later on management by objectives."}},{"itemId":"45087183-2fcb-5f22-9f97-2ac21a108f24","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa806dc2-08eb-50f3-adef-2ff5361aa72d","sourceKey":"bank:AMS101:AMS101-U012","parentItemId":null,"revision":1,"payload":{"prompt":"Division of work ensures:","options":["Employees report to one boss only.","Resources are monitored effectively.","Tasks are assigned based on skills.","Strict discipline in the workplace."],"correctOption":2,"section":"Managers and Management","explanation":"Division of work means splitting work into smaller specialized tasks so that each person does what they are best suited to, which builds skill and output. Option A describes unity of command, and D describes the principle of discipline. Option B is about controlling, not division of work."}},{"itemId":"10823f4d-0310-5020-9b4f-37e604bcf252","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a3b9558-2fa3-5fd4-9ac4-6ea43195073e","sourceKey":"bank:AMS101:AMS101-U013","parentItemId":null,"revision":1,"payload":{"prompt":"Unity of command states that:","options":["Employees should report to one superior.","All resources must be controlled by managers.","Teamwork should be prioritized.","Employees must follow multiple leaders."],"correctOption":0,"section":"Managers and Management","explanation":"Unity of command means each employee should receive orders from, and report to, only one superior. Option D is the opposite, since multiple bosses cause confusion. Options B and C describe control and teamwork, which are different principles."}},{"itemId":"1880b520-ae80-544b-9ce0-f32b6f5a2fcb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6f93d56b-a098-54f6-8e5d-775c3e693414","sourceKey":"bank:AMS101:AMS101-U014","parentItemId":null,"revision":1,"payload":{"prompt":"Authority in management is:","options":["The right to give orders and expect them to be obeyed.","A guideline for discipline.","The foundation of team spirit.","A reward for top-performing employees."],"correctOption":0,"section":"Managers and Management","explanation":"Authority is the right attached to a manager's position to give orders and expect them to be obeyed. Because it comes with the position, it is different from power, which is the wider ability to influence others. Option B relates to the principle of discipline and C relates to esprit de corps, while D is wrong because authority is not a reward for good performance."}},{"itemId":"a5591d33-dcf7-5d32-a149-8e38c32b4e34","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c86050d2-69f5-5026-9173-dac77776cfda","sourceKey":"bank:AMS101:AMS101-U015","parentItemId":null,"revision":1,"payload":{"prompt":"Esprit de corps focuses on:","options":["Delegating authority.","Promoting team spirit.","Creating goals for employees.","Assigning tasks to workers."],"correctOption":1,"section":"Managers and Management","explanation":"Esprit de corps is Fayol's principle that promoting team spirit builds harmony and unity within the organization. Options A and D describe delegation and division of work, and C describes planning, not team spirit."}},{"itemId":"56bcf176-b259-58ce-b9b4-b0e498d35f37","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bb26efef-ee55-56fd-b6b4-bd278d3f82eb","sourceKey":"bank:AMS101:AMS101-U016","parentItemId":null,"revision":1,"payload":{"prompt":"Staffing primarily deals with:","options":["Leading employees effectively.","Recruiting, training, and retaining workers.","Controlling the use of resources.","Delegating tasks to subordinates."],"correctOption":1,"section":"Managers and Management","explanation":"Staffing is the management task of filling and keeping positions filled, which covers recruiting, training and retaining workers. Option A is leading, C is controlling, and D is delegation, which belongs to organizing."}},{"itemId":"4ec18cae-4bfc-5517-8018-eb2ccfff9ffd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"944e24ad-b383-5d8f-816e-c51151a7b064","sourceKey":"bank:AMS101:AMS101-U017","parentItemId":null,"revision":1,"payload":{"prompt":"Recruitment is the process of:","options":["Locating, identifying and attracting capable applicants.","Retaining employees through rewards.","Evaluating employee performance.","Dividing work responsibilities."],"correctOption":0,"section":"Managing Human Resources","explanation":"Recruitment is the process of locating, identifying and attracting capable applicants for a job. Choosing which applicant to hire comes next and is called selection, so recruitment stops at building a pool of candidates. Option B describes retention, C describes performance appraisal, and D describes organizing work."}},{"itemId":"33de17aa-cc87-542b-97f6-7533c8fed183","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3aee2a12-b16a-5c6a-90d5-4890adbbd962","sourceKey":"bank:AMS101:AMS101-U018","parentItemId":null,"revision":1,"payload":{"prompt":"Training helps to:","options":["Motivate employees.","Develop skills in employees.","Reduce resource usage.","Discipline workers."],"correctOption":1,"section":"Managing Human Resources","explanation":"Training builds employees' knowledge and skills so they can do their jobs better. Option A, motivation, can be a side benefit, but it is not the main purpose of training. Options C and D are unrelated to training."}},{"itemId":"594dc1c0-a7c1-5791-9a55-db21a2a2daa4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c5947d0a-a3b3-5d77-ad5f-410727033297","sourceKey":"bank:AMS101:AMS101-U020","parentItemId":null,"revision":1,"payload":{"prompt":"One key step in staffing is:","options":["Budget control.","Task allocation.","Recruitment.","Resource evaluation."],"correctOption":2,"section":"Managers and Management","explanation":"Recruitment is one of the main steps in staffing, alongside selection, training and retention. Budget control (A) and resource evaluation (D) belong to controlling, and task allocation (B) belongs to organizing."}},{"itemId":"cedf313a-aa16-5404-9743-6ebb394b04af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce33b56b-4521-5383-b63d-de6106f592fd","sourceKey":"bank:AMS101:AMS101-U024","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an example of employee retention?","options":["Providing fair salaries and benefits.","Expanding job roles unnecessarily.","Assigning excessive tasks to workers.","Conducting regular audits."],"correctOption":0,"section":"Managing Human Resources","explanation":"Paying fair salaries and benefits gives employees good reason to stay, which is what retention means. Options B and C push workers away by overloading them, and D, conducting audits, is a control activity."}},{"itemId":"b5e0c4fc-3206-5639-9970-fa1d06a196b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b716ba22-1d59-5f9e-9874-510be29cf7ab","sourceKey":"bank:AMS101:AMS101-U025","parentItemId":null,"revision":1,"payload":{"prompt":"Retention focuses on:","options":["Firing unproductive employees.","Maintaining employee satisfaction.","Reducing overall costs.","Increasing work hours."],"correctOption":1,"section":"Managing Human Resources","explanation":"Retention means keeping valued employees, and keeping them satisfied is central to that. Option A, firing employees, is the opposite of retaining them. Options C and D describe cost and workload, and longer hours usually make people want to leave."}},{"itemId":"d50a9a65-1598-5b60-848e-7a403eed3404","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9aeee664-11a7-583e-83a0-d4b14c1f92ee","sourceKey":"bank:AMS101:AMS101-U026","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation refers to:","options":["The act of punishing employees.","Encouraging employees to work effectively.","Assigning extra duties.","Monitoring the team regularly."],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Motivation is the process that energizes and directs employees to put in effort toward goals, so encouraging them to work effectively fits best. Option A, punishment, is not motivation in the management sense. Options C and D describe workload and supervision."}},{"itemId":"ee94b359-2469-57a6-9f91-14c39e9d7802","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e8fc3135-90d1-5925-aa8c-1647554464c4","sourceKey":"bank:AMS101:AMS101-U027","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow, the highest level of need is:","options":["Physiological.","Safety.","Esteem","Self-actualization."],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"In Maslow's hierarchy, self-actualization, the need to reach one's full potential, sits at the top. Physiological needs (A) are at the bottom, followed by safety (B), then social needs, then esteem (C), which is just below self-actualization."}},{"itemId":"07660348-89d3-512f-a99e-9c13ce867b2d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"625e979b-ff4c-578d-9970-103ac0c831a7","sourceKey":"bank:AMS101:AMS101-U028","parentItemId":null,"revision":1,"payload":{"prompt":"The leadership style where decisions are made by the manager is:","options":["Autocratic.","Democratic.","Laissez-faire.","Collaborative."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Autocratic leaders make decisions on their own and expect others to follow them. Democratic leadership (B) involves employees in decisions, laissez-faire leadership (C) leaves decisions to the group, and collaborative leadership (D) is a shared approach."}},{"itemId":"82d45e40-6dea-545e-8c59-d5aedc79950b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"261b4465-286a-5da9-adae-c134b4144fc3","sourceKey":"bank:AMS101:AMS101-U029","parentItemId":null,"revision":1,"payload":{"prompt":"Democratic leadership involves:","options":["Decision-making solely by managers.","Encouraging employees to participate in decisions.","Allowing employees to work without supervision.","Using strict rules to govern teams."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Democratic or participative leaders involve employees in decision-making and value their input. Option A describes autocratic leadership, C describes laissez-faire leadership, and D describes a rule-bound, bureaucratic style."}},{"itemId":"3fa7f7ea-5704-5cea-a097-26692a367b74","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5614f351-da92-5b30-af20-8f2e17f101a5","sourceKey":"bank:AMS101:AMS101-U030","parentItemId":null,"revision":1,"payload":{"prompt":"Laissez-faire leadership means:","options":["Managers make all decisions without employee input.","Employees are given independence to make decisions.","Teams operate without clear objectives.","Strictly monitoring employees' actions."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Laissez-faire leadership gives employees a lot of freedom to make their own decisions with little interference. Option C can be a risk of the style, but it is not what the style means. Option A describes autocratic leadership, and D is close supervision, the opposite of laissez-faire."}},{"itemId":"ce0d1122-2bf4-5d27-b13e-8d13c49b9466","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00006a8c-67df-5e8d-ab3d-c36ab4a7c3de","sourceKey":"bank:AMS101:AMS101-U031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of intrinsic motivation?","options":["A promotion.","A personal sense of achievement.","A salary increment.","A bonus payment."],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Intrinsic motivation comes from inside a person, such as the satisfaction of achieving something. Promotions, salary increases and bonuses (A, C and D) are all external rewards given by the organization, so they are extrinsic motivators."}},{"itemId":"75e16356-6f0f-545b-bd00-d9462e30117e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90ca6cbf-77b9-586f-bd51-7a89dc0e8c5f","sourceKey":"bank:AMS101:AMS101-U032","parentItemId":null,"revision":1,"payload":{"prompt":"Extrinsic motivation is driven by:","options":["Internal goals.","External rewards like bonuses or recognition.","Self-improvement strategies.","Team collaboration."],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Extrinsic motivation comes from outside rewards such as pay, bonuses, promotions or recognition. Options A and C describe inner drives, which are intrinsic motivation. Team collaboration (D) is a way of working, not a type of motivation."}},{"itemId":"a638bc03-f445-5aa4-a738-742d24aa8146","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cbe41244-701e-540d-80b3-bfe971507bec","sourceKey":"bank:AMS101:AMS101-U033","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership is best defined as:","options":["Delegating tasks to employees.","Guiding and inspiring employees to achieve goals.","Training employees on management principles.","Setting measurable objectives for teams."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Leadership is an influence process: motivating and inspiring people to work together toward common goals. Option A, delegating tasks, is something leaders do, but it is not leadership itself. Options C and D describe training and planning."}},{"itemId":"799ac74f-3199-5720-a127-5b2ab72e4d64","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f0b1cd29-d658-5b9b-8d95-24762c76fa92","sourceKey":"bank:AMS101:AMS101-U034","parentItemId":null,"revision":1,"payload":{"prompt":"Maslow's \"safety needs\" in motivation include:","options":["Recognition and respect.","Job security and health insurance.","Personal growth and learning.","Financial independence."],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Safety needs cover security and protection, such as a stable job and health insurance. Recognition and respect (A) are esteem needs, and personal growth (C) is self-actualization. Financial independence (D) is not one of Maslow's safety needs as such."}},{"itemId":"6439ec16-7fda-58c4-994c-c2bfb7c81910","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3f68c9d9-7576-5b1c-8960-4afe8b491212","sourceKey":"bank:AMS101:AMS101-U035","parentItemId":null,"revision":1,"payload":{"prompt":"An autocratic leadership style works best in:","options":["Crisis situations requiring quick decisions.","Creative team environments.","Organizations prioritizing employee independence.","Flexible work environments."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"An autocratic style works best in a crisis, where one person needs to decide quickly and others need clear direction. Creative teams, independent workers and flexible environments (B, C and D) do better with participative or hands-off styles."}},{"itemId":"05595397-9baa-56cd-9858-84cf8f1475fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a3abf28-6291-5a56-a909-a1b380f03223","sourceKey":"bank:AMS101:AMS101-U036","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making is defined as:","options":["Choosing the best alternative to solve a problem.","Assigning tasks to employees.","Developing long-term goals.","Monitoring team performance."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Decision-making is the process of choosing among alternatives to solve a problem or take advantage of an opportunity. Option B is delegation, C is planning, and D is controlling."}},{"itemId":"93b533ef-c1d2-5327-b5e5-33460940dd7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98a600b7-139f-5fd5-8771-7a7f2e713b6c","sourceKey":"bank:AMS101:AMS101-U037","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in decision-making is:","options":["Identifying the problem","Analyzing solutions.","Implementing the solution.","Reviewing outcomes."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Decision-making starts by identifying the problem, the gap between where things are and where they should be. Analyzing solutions (B), implementing (C) and reviewing outcomes (D) all come later, once the problem is clear."}},{"itemId":"03561557-8ac3-5fb8-8f42-28c6f2f468d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6ea12600-1cba-58f7-a25b-46e1bad78716","sourceKey":"bank:AMS101:AMS101-U038","parentItemId":null,"revision":1,"payload":{"prompt":"An example of a programmed decision is:","options":["Choosing a new market strategy.","Deciding daily office hours.","Planning a business expansion.","Launching a new product."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions are routine and repetitive, so they can be handled with a standard approach, like setting daily office hours. A new market strategy, a business expansion and a new product launch (A, C and D) are one-off, unstructured choices, which makes them nonprogrammed decisions."}},{"itemId":"bb6e4cd6-61c3-599b-86a6-43f3a394b9df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6b72c514-fdc7-5c3c-8e02-da919a9c76e6","sourceKey":"bank:AMS101:AMS101-U040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a step in decision-making?","options":["Identifying the problem","Considering all alternatives.","Implementing corrective actions.","Ignoring team feedback."],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Ignoring team feedback is not a step in decision-making, because a good process gathers information and evaluates results. Identifying the problem (A), considering alternatives (B) and implementing and correcting (C) are all part of the decision process."}},{"itemId":"abe9ae34-427c-5d1f-a882-97b7b471b04c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aaee9c3b-50e3-5e86-a5fa-9dd41750edeb","sourceKey":"bank:AMS101:AMS101-U041","parentItemId":null,"revision":1,"payload":{"prompt":"A key feature of effective decision-making is:","options":["Quick implementation.","Careful analysis of alternatives.","Avoiding employee opinions.","Delegating decisions to subordinates."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Good decisions come from carefully weighing alternatives against the decision criteria before choosing. Quick implementation (A) does not help if the choice itself is poor. Ignoring employee opinions (C) and passing decisions down (D) do not make a decision more effective."}},{"itemId":"dcef7d88-9fbd-516a-92a8-63ee4662f7e8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b1d7674-68c1-5393-9437-7e8e2a25bdf3","sourceKey":"bank:AMS101:AMS101-U042","parentItemId":null,"revision":1,"payload":{"prompt":"Reviewing the outcomes of a decision helps to:","options":["Identify areas for improvement.","Finalize the budget.","Ignore failed strategies.","Increase production."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Reviewing the outcome of a decision shows whether it worked and what should be improved, which is the last step in the decision process. Options B and D are unrelated tasks. Option C is the opposite, since reviews are meant to learn from failures rather than ignore them."}},{"itemId":"49d224ba-bbac-5918-ba02-8e1269a810ec","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a327288-28ad-57ab-8820-6c000f5ddad1","sourceKey":"bank:AMS101:AMS101-U043","parentItemId":null,"revision":1,"payload":{"prompt":"An example of group decision-making is:","options":["A CEO finalizing an acquisition.","A team brainstorming a project idea.","A manager assigning tasks.","An employee reporting progress."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A team brainstorming project ideas is a group making a decision together, and brainstorming is a well-known group decision technique. Options A and C are individual managers deciding alone, and D is just reporting, not deciding."}},{"itemId":"591568a0-47c9-5ef2-a6e2-c9d47a56c54e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8317b74a-4ec6-54ee-9939-296d720cc827","sourceKey":"bank:AMS101:AMS101-U044","parentItemId":null,"revision":1,"payload":{"prompt":"The decision-making process ensures:","options":["Efficient use of resources.","Rapid expansion of the organization.","Reduction in team size.","Minimizing communication."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A structured decision process weighs alternatives against criteria, which helps an organization use its resources wisely. Options B and C may or may not happen as a result of a decision, so the process does not guarantee them. Option D is wrong because good decisions usually need more communication, not less."}},{"itemId":"28246a00-4d0c-52e5-8c74-d585c8435b35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"198d325b-ba50-5c33-b41c-353ac7a4e545","sourceKey":"bank:AMS101:AMS101-U045","parentItemId":null,"revision":1,"payload":{"prompt":"What is a primary benefit of involving employees in decision-making?","options":["Faster decision-making.","Increased commitment to outcomes.","Reduced financial costs.","Decreased need for monitoring."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"When employees help make a decision, they are more likely to accept it and commit to making it work. Option A is wrong because group decisions usually take more time. Options C and D are not reliable benefits of participation."}},{"itemId":"868ecb4d-15a5-5112-bff8-08598f551150","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"907f53bc-523f-5331-8f0f-c463c26c63e5","sourceKey":"bank:AMS101:AMS101-U046","parentItemId":null,"revision":1,"payload":{"prompt":"One major challenge faced by Nigerian managers is:","options":["Adequate infrastructure.","Frequent power outages.","Overqualified employees.","Minimal government intervention."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Frequent power outages are a well-known problem for Nigerian businesses, raising costs and disrupting operations. Options A and C describe advantages, not challenges, and D is not typical of the Nigerian business environment."}},{"itemId":"5f0e60eb-92b8-565d-83a9-976d770ddf0e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ffabf8d7-8126-56c0-b138-83fb6413684f","sourceKey":"bank:AMS101:AMS101-U047","parentItemId":null,"revision":1,"payload":{"prompt":"Corruption affects management in Nigeria by:","options":["Promoting transparency.","Creating delays in decision-making.","Reducing operational efficiency.","Both B and C."],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Corruption slows decisions, for example through demands for bribes and favours, and it wastes resources, so both B and C are correct. Option A is wrong because corruption reduces transparency rather than promoting it."}},{"itemId":"2a899dd8-19ff-54b7-9854-63ee3d370250","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ebb2a9b9-6798-52d9-89c6-830cb367bc46","sourceKey":"bank:AMS101:AMS101-U048","parentItemId":null,"revision":1,"payload":{"prompt":"Poor infrastructure in Nigeria can lead to:","options":["Efficient resource allocation.","Delayed production and distribution.","Lower transport and energy costs.","Better financial results."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Poor roads, unreliable power and weak transport make it hard to produce goods and get them to customers on time, so delays in production and distribution follow directly. Option C is wrong because poor infrastructure raises transport and energy costs rather than lowering them. Options A and D are benefits, so poor infrastructure would not cause them."}},{"itemId":"61e7139b-ae4c-5eac-b2b3-045dae27fd1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf79e2ed-a46a-5067-954e-1b8eca44c757","sourceKey":"bank:AMS101:AMS101-U049","parentItemId":null,"revision":1,"payload":{"prompt":"A solution to the lack of skilled labor in Nigeria is:","options":["Increasing employee salaries.","Training and skill development programs.","Hiring only foreign workers.","Delaying project deadlines."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Training and skill development programs build the skills that are missing in the workforce. Option A, higher salaries, may attract workers but does not create new skills. Hiring only foreign workers (C) and delaying deadlines (D) avoid the problem without solving it."}},{"itemId":"efaa012c-7459-55af-a7f5-d444d836d9aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a25951af-bdbe-52f6-9efc-d413747d4409","sourceKey":"bank:AMS101:AMS101-U050","parentItemId":null,"revision":1,"payload":{"prompt":"Bureaucratic delays can be minimized by:","options":["Adopting technological solutions.","Ignoring government regulations.","Increasing the number of employees.","Reducing organizational budgets."],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Technology such as digital records and online processes speeds up paperwork and approvals, which cuts bureaucratic delays. Option B is unlawful and risky, and C can add more red tape. Option D does not deal with the cause of the delay."}},{"itemId":"2afb5adf-4933-5bc4-bbab-06f65b5d8c97","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0897593b-76af-5ce1-819a-6834071e7df0","sourceKey":"bank:AMS101:AMS101-U051","parentItemId":null,"revision":1,"payload":{"prompt":"Which technological solution can improve Nigerian businesses?","options":["Social media for marketing.","Manual record-keeping.","Paper-based communication.","Limiting staff access to tools."],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social media lets businesses reach many customers cheaply and quickly, which makes it a practical technological improvement. Manual record-keeping and paper-based communication (B and C) are old methods, and D would hold staff back."}},{"itemId":"19c23898-2197-5a15-8365-fb27fbf8ef3e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"512e1b5d-6ebd-5055-8cb0-b901f8e78718","sourceKey":"bank:AMS101:AMS101-U052","parentItemId":null,"revision":1,"payload":{"prompt":"An ethical approach in management promotes:","options":["Bribery and shortcuts.","Transparency and fairness.","Bureaucratic procedures.","Ignoring employee concerns."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Ethics is a set of principles that defines right and wrong conduct, and an ethical approach to management promotes transparency and fairness. Option A is unethical, C is unrelated, and D goes against the respect for employees that ethics requires."}},{"itemId":"5bdd7531-86e3-53b9-b1f4-4b41790dd1af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1110e49a-4818-5d1e-946c-501279a6c801","sourceKey":"bank:AMS101:AMS101-U053","parentItemId":null,"revision":1,"payload":{"prompt":"A key challenge in the Nigerian labor market is:","options":["High levels of worker satisfaction.","Poor educational standards.","Efficient recruitment processes.","Excessive government support."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Weak educational standards leave many job seekers without the skills employers need, which is a real challenge in the Nigerian labour market. Options A, C and D describe favourable conditions, not challenges."}},{"itemId":"82e7de6a-b4ea-52c8-9e7b-762ae0ea6ef3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8352a42c-1d0f-529d-aec4-854e788fcb9e","sourceKey":"bank:AMS101:AMS101-U054","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian government can support managers by:","options":["Increasing taxes for organizations.","Investing in infrastructure development.","Discouraging technological advancements.","Limiting access to funds."],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Government can help managers most by providing good infrastructure such as power, roads and communications, which lowers business costs. Options A, C and D would all make business harder rather than easier."}},{"itemId":"bfb2051e-4a41-59e8-8a32-0a1970063cee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f24ff3ea-7e69-5019-b90c-035635f3f1cf","sourceKey":"bank:AMS101:AMS101-U055","parentItemId":null,"revision":1,"payload":{"prompt":"Corruption can be reduced by:","options":["Promoting ethical practices.","Avoiding proper documentation.","Focusing only on profits.","Ignoring employee misconduct."],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Promoting ethical practices, through a code of ethics, ethical leadership and training, is how organizations reduce corruption. Options B, C and D create the very conditions in which corruption grows."}},{"itemId":"c874fed8-8bf4-5fa2-8351-005589aeed57","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f021b13-80c7-564d-983c-79bbb0122dfc","sourceKey":"bank:AMS101:AMS101-U056","parentItemId":null,"revision":1,"payload":{"prompt":"Which managerial skill is equally important at all levels of management?","options":["Technical skills.","Human skills.","Conceptual skills.","Leadership skills."],"correctOption":1,"section":"Managers and Management","explanation":"Human (interpersonal) skills are needed equally at every level, because all managers work with and through people. Option C, conceptual skills, matters most for top managers, and option A, technical skills, matters most for first-line managers. Leadership (D) is a function that draws on these skills rather than one of the basic skill categories."}},{"itemId":"599f53ae-64ad-53ba-aee4-a08623dcbad1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"acbf5555-c429-54bb-93e9-ca6d868af666","sourceKey":"bank:AMS101:AMS101-U057","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic management focuses on:","options":["Day-to-day operations.","Long-term goals and objectives.","Routine problem-solving.","Managing individual performance."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Strategic management is about where the organization wants to go in the long run and how it will get there. Day-to-day operations and routine problem-solving (A and C) are operational matters, and D is the job of individual supervision."}},{"itemId":"9bf607ef-f961-5062-b01b-d4129f4c39ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3b48c7bb-f606-5fc7-a591-e7e8c1a136c5","sourceKey":"bank:AMS101:AMS101-U060","parentItemId":null,"revision":1,"payload":{"prompt":"Delegation is important for managers because it","options":["Removes the manager's responsibility for results.","Improves employee motivation and performance.","Centralizes decision-making.","Limits employee independence."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Delegation gives employees the authority to carry out specific tasks, which develops their skills and raises motivation and performance. Option A is wrong because a manager who delegates still remains accountable for the results. Options C and D are the opposite of what delegation does, since it spreads decision-making and gives employees more independence."}},{"itemId":"cd8842a4-64e0-5440-99e5-c3463bd41fbd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eda311e5-60d1-5b6f-b4bb-4aee7f47487a","sourceKey":"bank:AMS101:AMS101-U061","parentItemId":null,"revision":1,"payload":{"prompt":"Management by Objectives (MBO) involves:","options":["Imposing goals on employees.","Setting mutually agreed goals.","Ignoring employee feedback.","Delegating tasks to subordinates."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"In Management by Objectives, managers and employees agree on goals together and then review progress against them. Option A is the traditional top-down approach that MBO tries to replace. Options C and D leave out the joint goal-setting that defines MBO."}},{"itemId":"14e09325-acaf-53c1-8046-05fe759c86d1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"129adefa-2d13-575b-935f-9dce47c1e23c","sourceKey":"bank:AMS101:AMS101-U063","parentItemId":null,"revision":1,"payload":{"prompt":"Innovation in management leads to:","options":["Routine decision-making.","Improved productivity and competitiveness.","Ignoring customer feedback.","Focusing only on current profits."],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Innovation means finding new and better ways of doing things, which makes an organization more productive and competitive. Options A, C and D describe staying stuck in old routines, the opposite of innovation."}},{"itemId":"27dd1055-3a92-5204-8157-8e90407cc3fd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1197e2d3-4878-5af7-89c9-c4481b370d07","sourceKey":"bank:AMS101:AMS101-U064","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is not a management principle?","options":["Unity of direction.","Discipline.","Monopoly.","Authority."],"correctOption":2,"section":"Managers and Management","explanation":"Monopoly is a market structure where one firm controls supply; it is not one of Fayol's principles of management. Unity of direction (A), discipline (B) and authority (D) are all among his 14 principles."}},{"itemId":"c7a6343e-0df5-552f-b070-53e8353bd32d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"35c82dfa-7a27-5541-9c63-d703624a4482","sourceKey":"bank:AMS101:AMS101-U065","parentItemId":null,"revision":1,"payload":{"prompt":"The success of an organization is dependent on:","options":["Strict rules and regulations.","Efficient management of resources.","Avoiding employee engagement.","Minimizing team communication."],"correctOption":1,"section":"Managers and Management","explanation":"Organizations succeed when managers use their resources efficiently and effectively to reach goals. Option A may help with order, but strict rules alone do not guarantee success. Options C and D would weaken the organization."}},{"itemId":"546b49d2-9290-561f-8e31-fc7b25d930f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25fa1126-2a30-5398-8d9e-b55dca414bcf","sourceKey":"bank:AMS101:AMS101-U066","parentItemId":null,"revision":1,"payload":{"prompt":"Division of work increases:","options":["Employee workload.","Efficiency and productivity.","Communication gaps.","Organizational costs."],"correctOption":1,"section":"Managers and Management","explanation":"When work is divided into specialized tasks, people get better at them and output rises, so efficiency and productivity increase. Options A, C and D are not the purpose of dividing work; the principle aims to cut wasted effort."}},{"itemId":"7bd68ceb-494c-56a7-89f4-621e7b277737","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d9cc5ab-6ad1-5aaa-a928-11a55e1dddc1","sourceKey":"bank:AMS101:AMS101-U067","parentItemId":null,"revision":1,"payload":{"prompt":"Unity of command ensures:","options":["Each employee reports to multiple managers.","Clear lines of authority and reduced confusion.","Managers delegate all responsibilities.","Employees can bypass authority when needed."],"correctOption":1,"section":"Managers and Management","explanation":"When each employee has only one boss, lines of authority are clear and there are no conflicting orders. Option A is the opposite of unity of command. Options C and D would weaken the chain of authority."}},{"itemId":"431121c2-aef5-5146-b895-bba61a71ce60","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5fccf4ea-7cd1-5c60-b534-df3f659f54a3","sourceKey":"bank:AMS101:AMS101-U068","parentItemId":null,"revision":1,"payload":{"prompt":"Authority and responsibility must:","options":["Be in balance for effective management.","Be transferred to lower-level employees.","Be focused only on the senior management.","Be ignored to encourage flexibility."],"correctOption":0,"section":"Managers and Management","explanation":"Authority and responsibility should go together: a person given responsibility for a task needs enough authority to carry it out. Option B confuses this with delegation, and C is too narrow. Ignoring both (D) would cause confusion."}},{"itemId":"f7101990-f874-51e5-8020-75993e4e49b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e8771933-5220-5dfb-a9b3-63c752aa204f","sourceKey":"bank:AMS101:AMS101-U069","parentItemId":null,"revision":1,"payload":{"prompt":"Which principle emphasizes team spirit?","options":["Unity of direction.","Discipline.","Esprit de corps.","Centralization."],"correctOption":2,"section":"Managers and Management","explanation":"Esprit de corps literally means \"team spirit\", and Fayol used it for the principle of promoting harmony and unity. Unity of direction (A) is about common objectives, discipline (B) is about obeying rules, and centralization (D) is about where decisions are made."}},{"itemId":"908c1b92-ac06-5873-9d58-83680faa0580","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5c7e76b6-d66b-5528-b7d9-00d001d5ecff","sourceKey":"bank:AMS101:AMS101-U070","parentItemId":null,"revision":1,"payload":{"prompt":"A key characteristic of discipline in management is:","options":["Employee freedom to ignore policies.","Respect for agreements and organizational rules.","Reducing the role of authority.","Avoiding structured systems."],"correctOption":1,"section":"Managers and Management","explanation":"In Fayol's terms, discipline means employees obey and respect the rules and agreements of the organization. Options A, C and D all weaken order and authority, which is the opposite of discipline."}},{"itemId":"dbd56d9f-38fb-567b-b934-6363baa3bf88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8a583f8a-4481-5a3c-b95c-adbb51d5e844","sourceKey":"bank:AMS101:AMS101-U071","parentItemId":null,"revision":1,"payload":{"prompt":"Unity of direction ensures:","options":["Teams work toward a common objective.","Employees can pursue personal goals.","Managers handle unrelated projects.","Resources are used inefficiently."],"correctOption":0,"section":"Managers and Management","explanation":"Unity of direction means activities with the same objective should follow one plan under one manager, so teams work toward a common goal. Option B puts personal goals first, and options C and D go against coordinated effort."}},{"itemId":"ad2494fc-07d0-51ee-9fe9-efcc97bb2b3b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"518d4a6f-8d08-513d-b4c8-1e6af8b934ff","sourceKey":"bank:AMS101:AMS101-U072","parentItemId":null,"revision":1,"payload":{"prompt":"Centralization in an organization means:","options":["Decision-making is concentrated at the top levels.","Employees make all organizational decisions.","Resources are scattered across departments.","Team leaders avoid taking responsibility."],"correctOption":0,"section":"Organization Design and Structure","explanation":"Centralization means decision-making is kept at the upper levels of the organization. Option B is closer to decentralization, where lower levels provide input or make decisions. Options C and D are unrelated to the term."}},{"itemId":"8f38c084-2748-588e-aac8-01f2129b725f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"348085b4-2666-54e1-9256-b0b06f6425da","sourceKey":"bank:AMS101:AMS101-U073","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is true about decentralization?","options":["It reduces employee involvement in decision-making.","It empowers lower-level managers to make decisions.","It ignores the principle of authority.","It discourages teamwork."],"correctOption":1,"section":"Organization Design and Structure","explanation":"Decentralization pushes decision-making down so that lower-level managers give input or make decisions themselves. Option A describes centralization. Options C and D are false, because decentralization still works within the authority structure and often supports teamwork."}},{"itemId":"2ebcb958-c487-51de-bd44-d1013fff8c52","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"01955fb7-5598-5e87-92e7-fe43e489b12f","sourceKey":"bank:AMS101:AMS101-U074","parentItemId":null,"revision":1,"payload":{"prompt":"Scalar chain refers to:","options":["Breaking communication protocols.","A clear line of authority from top to bottom.","Employees reporting to multiple bosses.","Managers avoiding employee communication."],"correctOption":1,"section":"Managers and Management","explanation":"Scalar chain is the unbroken line of authority running from the top of the organization to the bottom, which communication normally follows. Option C breaks unity of command, and A and D describe poor communication rather than the principle."}},{"itemId":"b0b5530e-c573-5147-bf92-c5b30cc77e46","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ca8f863-f09d-5753-a1cd-0a953ed3dd65","sourceKey":"bank:AMS101:AMS101-U075","parentItemId":null,"revision":1,"payload":{"prompt":"The principle of remuneration focuses on:","options":["Providing fair and equitable pay to employees.","Reducing overall operational costs.","Avoiding employee incentives.","Increasing employee workload."],"correctOption":0,"section":"Managers and Management","explanation":"Fayol's principle of remuneration says workers should receive fair pay for their services. Options B, C and D all work against fair reward, so they do not describe the principle."}},{"itemId":"7a6f72d5-6f06-5a7d-8c33-0523aa3e1d3a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"49ef9635-9f90-51da-8ae1-e4bb93d6987b","sourceKey":"bank:AMS101:AMS101-U076","parentItemId":null,"revision":1,"payload":{"prompt":"Maslow's theory is important in management because it:","options":["Ignores employee needs.","Helps managers understand employee motivation.","Focuses only on financial benefits.","Promotes strict organizational policies."],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Maslow's hierarchy shows that people are driven by different levels of needs, which helps managers understand what motivates each employee. Option C is wrong because the theory covers social, esteem and growth needs as well as money. Options A and D contradict the theory."}},{"itemId":"cdc119de-6ece-5d7d-ab28-ad3df36528d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"949cdc14-7112-55e4-9970-6ba71a961447","sourceKey":"bank:AMS101:AMS101-U077","parentItemId":null,"revision":1,"payload":{"prompt":"A leader who involves employees in decision-making is using:","options":["Autocratic leadership.","Laissez-faire leadership.","Democratic leadership.","Bureaucratic leadership."],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Democratic leadership means involving employees in decisions and taking their input seriously. Autocratic leaders (A) decide alone, laissez-faire leaders (B) leave decisions to the group, and bureaucratic leaders (D) rely on rules and procedures."}},{"itemId":"ba547124-dd92-53cf-a4f1-6ecea59555f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47eba576-6297-5166-a939-0b2266534b1e","sourceKey":"bank:AMS101:AMS101-U078","parentItemId":null,"revision":1,"payload":{"prompt":"Transformational leadership inspires employees by:","options":["Strictly enforcing policies.","Encouraging innovation and personal growth.","Limiting employee independence.","Focusing only on immediate tasks."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Transformational leaders inspire people to go beyond their own interests, encouraging innovation, growth and commitment to a shared vision. Options A, C and D describe controlling or narrow task-focused behaviour, which is closer to transactional or autocratic styles."}},{"itemId":"b8b29fba-0f1f-5939-b454-365de22a9078","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a9817e6-cdf4-5867-9618-610e419514ee","sourceKey":"bank:AMS101:AMS101-U079","parentItemId":null,"revision":1,"payload":{"prompt":"Motivating employees effectively requires:","options":["Understanding their individual needs and goals.","Ignoring feedback from teams.","Promoting a one-size-fits-all approach.","Eliminating performance evaluations."],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"People are motivated by different things, so managers need to understand each employee's needs and goals. Option C, a one-size-fits-all approach, ignores those differences. Options B and D remove the feedback that helps managers motivate staff."}},{"itemId":"1028b282-7ac1-5e10-b624-25b756a2a2bc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d4566de6-c4da-5d0b-b627-d68ef2bd9c9d","sourceKey":"bank:AMS101:AMS101-U080","parentItemId":null,"revision":1,"payload":{"prompt":"Leaders who delegate decision-making to employees practice:","options":["Autocratic leadership.","Laissez-faire leadership.","Directive leadership.","Transformational leadership."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Laissez-faire leaders hand decision-making over to employees and give them a lot of freedom. Option D is tempting because transformational leaders also empower people, but they actively inspire and guide them rather than stepping back. Autocratic and directive leaders (A and C) keep decisions to themselves."}},{"itemId":"d9869c90-b361-5fe7-9cd3-889f8490356d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"270b935b-7e1e-59ac-9e07-bfb99714c10d","sourceKey":"bank:AMS101:AMS101-U081","parentItemId":null,"revision":1,"payload":{"prompt":"The primary goal of decision-making is to:","options":["Resolve organizational issues efficiently.","Reduce employee workload.","Focus only on management-level problems.","Avoid evaluating alternatives."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Decisions exist to solve problems, closing the gap between the current and desired state, ideally in an efficient way. Option B may happen but is not the goal. Option C is wrong because employees at all levels make decisions, and D goes against good decision-making."}},{"itemId":"bb1cdccd-f183-54a8-a87e-63a72d94183b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ecf03537-645c-5daa-8aa8-f02038db6480","sourceKey":"bank:AMS101:AMS101-U082","parentItemId":null,"revision":1,"payload":{"prompt":"Brainstorming in decision-making is used to:","options":["Generate diverse ideas and solutions.","Avoid conflict among team members.","Minimize employee participation.","Encourage routine operations."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Brainstorming is a group technique for generating as many different ideas and alternatives as possible, without criticizing them at first. Option B is not its purpose, C is the opposite, since it depends on participation, and D has nothing to do with creative idea generation."}},{"itemId":"14c399c9-b838-5c06-acc3-56c1672b3c09","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c61e0418-d011-50fd-9a1a-f6fc16895bb5","sourceKey":"bank:AMS101:AMS101-U083","parentItemId":null,"revision":1,"payload":{"prompt":"Non-programmed decisions are characterized by:","options":["Structured and repetitive processes.","Unstructured, unique, and strategic issues.","Focus on daily operations.","Minimal managerial involvement."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Nonprogrammed decisions deal with new, unstructured problems and need a custom-made solution, which is typical of strategic issues. Options A and C describe programmed decisions. Option D is wrong because these decisions usually need more managerial judgement, not less."}},{"itemId":"612c1612-96ed-5c71-835f-04fb0d63a8be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71b7fc61-8854-5a8c-88c8-934059f413e5","sourceKey":"bank:AMS101:AMS101-U084","parentItemId":null,"revision":1,"payload":{"prompt":"A key feature of group decision-making is:","options":["Faster resolution of conflicts.","Increased collaboration and idea-sharing.","Ignoring employee input.","Strict implementation of pre-set rules."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Groups bring together more information and more alternatives, so collaboration and idea-sharing are the defining feature. Option A is wrong because group decisions are usually slower than individual ones. Options C and D go against the point of deciding as a group."}},{"itemId":"43eb7d32-ce3e-567d-adab-c7fdc636f62f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa4c38e0-87a5-535b-bdd7-805ce2abf7ec","sourceKey":"bank:AMS101:AMS101-U085","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making in uncertain environments requires:","options":["Relying solely on past experiences.","Adopting a flexible and adaptive approach.","Eliminating employee opinions.","Avoiding technological tools."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Under uncertainty the decision maker has no reliable probability estimates, so they must stay flexible and adapt as new information arrives. Option A is risky, because past experience may not fit a new situation. Options C and D throw away useful input and tools."}},{"itemId":"0ab0751c-0e4e-55b0-a7ee-e8d4df85f83d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d12f3c0a-51d4-5647-9687-69eb428381c5","sourceKey":"bank:AMS101:AMS101-U086","parentItemId":null,"revision":1,"payload":{"prompt":"Effective management ensures:","options":["Resources are wasted.","Organizational goals are achieved efficiently.","Employees overburdened.","Long-term objectives are ignored."],"correctOption":1,"section":"Managers and Management","explanation":"Good management means achieving goals effectively while using resources efficiently. Options A, C and D describe waste, overwork and neglect of goals, the signs of poor management."}},{"itemId":"8c43335b-7507-5cd3-ba78-6d586b84c8ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a94dd60-0efb-5eb0-bbbd-cab1b4f3d0f0","sourceKey":"bank:AMS101:AMS101-U087","parentItemId":null,"revision":1,"payload":{"prompt":"Management is both:","options":["A science and an art.","A science and a task.","An art and a challenge.","A theory and a skill."],"correctOption":0,"section":"Managers and Management","explanation":"Management is a science because it rests on organized knowledge and principles, and an art because applying them takes personal skill and judgement. Options B, C and D pair words that do not express this classic idea."}},{"itemId":"1c8010f5-34c4-57ef-9b9e-7feeee699bf2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d238720-69cb-5b64-81bf-dd9d3a1ec355","sourceKey":"bank:AMS101:AMS101-U088","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a key characteristic of a good manager?","options":["Indecisiveness.","Strong communication skills.","Resistance to change.","Ignoring employee concerns."],"correctOption":1,"section":"Managers and Management","explanation":"Managers get work done through people, so strong communication skills are essential to a good manager. Options A, C and D are weaknesses that would make a manager less effective."}},{"itemId":"8d58b5c3-f1ed-5288-bee0-1be81f5d175e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98f13928-e876-5db7-b646-ae1415ad225e","sourceKey":"bank:AMS101:AMS101-U091","parentItemId":null,"revision":1,"payload":{"prompt":"Tactical planning focuses on:","options":["Translating strategic goals into specific actions.","Focusing on daily routines.","Ignoring organizational objectives.","Eliminating employee responsibilities."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Tactical planning turns broad strategic goals into specific actions for departments, usually over the medium term. Option B, daily routines, is operational planning. Options C and D go against the purpose of planning."}},{"itemId":"639cddb3-3279-5442-9554-4bccedf8e27e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0651af4-2be3-5bf0-9edd-74e45b6df465","sourceKey":"bank:AMS101:AMS101-U092","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's primary responsibility is:","options":["Achieving organizational goals efficiently and effectively.","Supervising employees only.","Focusing on short-term profits.","Avoiding communication with teams."],"correctOption":0,"section":"Managers and Management","explanation":"A manager's main job is to get organizational goals achieved both efficiently (doing things right) and effectively (doing the right things). Option B is too narrow, C is too short-sighted, and D is poor practice."}},{"itemId":"66a39147-9894-523a-85e9-a2cfc25aef7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"97eb5d29-af2e-51e3-9931-64e50c5ffea2","sourceKey":"bank:AMS101:AMS101-U093","parentItemId":null,"revision":1,"payload":{"prompt":"A manager delegates tasks effectively by:","options":["Assigning responsibilities without instructions.","Matching tasks with employee skills and abilities.","Ignoring feedback from employees.","Focusing only on team leaders."],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Effective delegation matches each task to the person with the right skills and gives them the authority to do it. Option A, giving tasks without instructions, usually leads to mistakes. Options C and D limit the benefits of delegating."}},{"itemId":"0df50f70-e9a2-5a5f-8a1a-66eb99015a04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da099836-76d4-5767-b625-c9cda40e6031","sourceKey":"bank:AMS101:AMS101-U094","parentItemId":null,"revision":1,"payload":{"prompt":"The success of a management plan depends on:","options":["Proper planning and execution.","Rigid structures and strict enforcement.","Avoiding teamwork.","Limiting communication."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A plan only works if it is well designed and then properly carried out. Option B can create rigidity, which is a known weakness of formal planning. Options C and D weaken the teamwork and communication that execution needs."}},{"itemId":"0de05128-f644-5d20-849a-aecb4f03505d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da0340f4-df60-59f1-b165-0f4574ef5902","sourceKey":"bank:AMS101:AMS101-U095","parentItemId":null,"revision":1,"payload":{"prompt":"Management helps organizations by.","options":["Achieving goals with minimal resources.","Ignoring external factors.","Focusing only on profits.","Increasing employee workload."],"correctOption":0,"section":"Managers and Management","explanation":"Management helps organizations reach their goals while using as few resources as possible, combining effectiveness with efficiency. Option B is wrong because managers must respond to the external environment. Options C and D are too narrow or harmful."}},{"itemId":"7a535d15-8974-5d52-a2cb-87dc74dd2c1e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf06ff1a-d9af-5afa-8139-93981bdc738c","sourceKey":"bank:AMS101:AMS101-U096","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic planning primarily focuses on:","options":["Long-term goals and overall direction of the organization.","Daily routines and operations.","Individual employee tasks.","Addressing minor organizational conflicts."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Strategic planning sets the organization's long-term goals and overall direction, usually led by top managers. Options B and C describe operational planning, and D is too minor to be strategic."}},{"itemId":"90a8306f-4cbd-5ae1-b084-0a28c1ef5fb6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c6578082-de12-5dcd-a100-821c4acdb14b","sourceKey":"bank:AMS101:AMS101-U098","parentItemId":null,"revision":1,"payload":{"prompt":"Operational planning is concerned with:","options":["Strategic decision-making.","Day-to-day operations and specific tasks.","Resolving disputes among managers.","Preparing for long-term future challenges."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Operational planning deals with the day-to-day running of the organization and the specific tasks needed to meet short-term targets. Options A and D describe strategic planning, and C is about conflict resolution, not planning."}},{"itemId":"a1a4a63a-c7ee-5737-9ab0-5b83dbfa889b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"055e9030-83c3-5685-a15e-e0d9ed671593","sourceKey":"bank:AMS101:AMS101-U099","parentItemId":null,"revision":1,"payload":{"prompt":"Contingency planning involves:","options":["Preparing alternative courses of action for unexpected events.","Ignoring possible risks.","Eliminating flexibility in operations.","Assigning blame for past failures."],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Contingency planning prepares alternative courses of action so the organization can respond quickly if something unexpected happens. Option B is the opposite, since contingency plans exist because risks are taken seriously. Options C and D are unrelated to the purpose."}},{"itemId":"0f19cfbd-8181-5edb-895a-3c4c58471e39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6feca83c-8a11-553b-b9d9-161857816e13","sourceKey":"bank:AMS101:AMS101-U100","parentItemId":null,"revision":1,"payload":{"prompt":"A goal of planning is to:","options":["Eliminate uncertainty completely.","Provide direction for the organization.","Increase workload for managers.","Avoid setting measurable objectives."],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning gives the organization direction by setting goals and showing how to reach them. Option A goes too far, because planning reduces uncertainty but can never remove it completely. Options C and D are not goals of planning."}},{"itemId":"de192a21-ae3d-552f-ad59-24b8e9663028","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"372d633e-4646-5733-98f3-4cfef6290083","sourceKey":"bank:AMS101:AMS101-U101","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership differs from management in that","options":["Leadership focuses on influencing and inspiring.","Leadership emphasizes controlling and monitoring.","Leadership avoids decision-making.","Leadership operates without collaboration."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Leadership is about influencing and inspiring people toward a shared goal, while management also includes planning, organizing and controlling. Option B describes the controlling side of management rather than leadership. Options C and D are false, because leaders make decisions and work with others."}},{"itemId":"4b160f10-0a5c-53b4-9828-1c92a486aa76","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8fafa6db-9a66-511f-98cb-2aa091ead9de","sourceKey":"bank:AMS101:AMS101-U102","parentItemId":null,"revision":1,"payload":{"prompt":"A manager practicing autocratic leadership will:","options":["Make all decisions without consulting employees.","Encourage full employee participation in decision-making.","Delegate tasks entirely to team members.","Avoid setting clear objectives."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"An autocratic manager makes decisions alone without consulting employees. Option B describes democratic leadership and C describes laissez-faire leadership. Option D is not typical, since autocratic leaders usually give very clear directions."}},{"itemId":"fa7a22a7-85ac-55a4-8ffb-23ae651b8618","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d79c0487-e940-5b0f-bdf0-36aa63cc77d5","sourceKey":"bank:AMS101:AMS101-U103","parentItemId":null,"revision":1,"payload":{"prompt":"Laissez-faire leadership works best when:","options":["Employees are highly skilled and self-motivated.","Employees require constant supervision.","Organizations face frequent crises.","The manager seeks total control."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A hands-off, laissez-faire style works best when employees are skilled and self-motivated enough to manage themselves. Options B and C call for more direction and control. Option D describes an autocratic leader, not a laissez-faire one."}},{"itemId":"76fe6fda-78c4-5aa9-af67-1408901a3278","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b8cc5204-fb75-5594-9169-9a3cea755a5d","sourceKey":"bank:AMS101:AMS101-U104","parentItemId":null,"revision":1,"payload":{"prompt":"Charismatic leaders are known for:","options":["Relying on their personal charm and vision to inspire others.","Avoiding interpersonal communication.","Focusing solely on technical skills.","Strictly enforcing rules without flexibility."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Charismatic leaders inspire followers through their personal appeal, confidence and a compelling vision. Options B, C and D describe the opposite: poor communication, a narrow technical focus and rigid rule enforcement."}},{"itemId":"46c5d0e8-afc8-5aeb-b245-41ac3f407b13","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b10e6bcf-4b3e-5c7c-bc35-5552d821bcb5","sourceKey":"bank:AMS101:AMS101-U105","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership effectiveness depends on:","options":["Understanding employee needs and adapting leadership styles.","Ignoring employee feedback.","Maintaining a single leadership style regardless of context.","Prioritizing personal goals over organizational objectives."],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Effective leaders read the situation and their people's needs, then adapt their style to fit, which is the core idea of contingency or situational leadership. Option C is the opposite of this idea. Options B and D weaken trust and commitment."}},{"itemId":"7578b34d-2c49-51d9-84cf-6a5d504322c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77219643-76aa-512f-a3d9-2a0fbe8c06b2","sourceKey":"bank:AMS101:AMS101-U106","parentItemId":null,"revision":1,"payload":{"prompt":"The purpose of controlling is to:","options":["Ensure actual performance meets planned goals.","Create new policies frequently.","Overlook performance gaps.","Avoid taking corrective measures."],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Controlling compares actual performance with planned goals and corrects deviations so that goals are met. Option B, creating policies, is planning. Options C and D contradict control, which exists to close performance gaps through corrective action."}},{"itemId":"1e4e8e1e-5e05-56d5-b0f4-9835b89c7b6b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"92110c86-f096-5f0e-a54e-47b5e6061eeb","sourceKey":"bank:AMS101:AMS101-U107","parentItemId":null,"revision":1,"payload":{"prompt":"Key elements of the control process include:","options":["Setting standards, measuring performance, and taking corrective action.","Avoiding standards to maintain flexibility.","Ignoring deviations from plans.","Replacing goals with ad-hoc solutions."],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"The control process checks performance against standards: measure actual performance, compare it with the standard, and take corrective action where there is a gap. The standards themselves come from planning, so setting them is the starting point, which is why A captures the key elements. Options B, C and D remove either the standards or the follow-up that control depends on."}},{"itemId":"0bc203f1-b346-5467-81e0-5bad0392e21f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a73a07e-bd45-5f59-aa31-cb749d0b7dc8","sourceKey":"bank:AMS101:AMS101-U108","parentItemId":null,"revision":1,"payload":{"prompt":"Performance measurement in controlling involves:","options":["Comparing actual results with planned objectives.","Ignoring minor discrepancies in results.","Focusing only on employee behavior.","Eliminating performance benchmarks."],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Measuring performance means checking actual results against the planned objectives or standards to find any gaps. Option B can let small problems grow. Option C is too narrow, and D removes the benchmarks needed for comparison."}},{"itemId":"91268902-64d4-580e-b007-ce479af9846e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4cee2eff-4a4e-5be1-956b-9ceeb85803de","sourceKey":"bank:AMS101:AMS101-U109","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback control occurs:","options":["After an activity is completed.","Before an activity begins.","During the planning stage.","Without analyzing outcomes."],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Feedback control happens after an activity is finished, using performance data to judge whether goals were met. Option B describes feedforward control, which tries to prevent problems before they occur. Options C and D do not match how feedback control works."}},{"itemId":"7a0f14dd-f386-52af-96bf-49b1dc299712","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"45c2260a-ece0-59d4-bfb0-2e1f6182b56f","sourceKey":"bank:AMS101:AMS101-U110","parentItemId":null,"revision":1,"payload":{"prompt":"Feedforward control focuses on:","options":["Preventing problems before they occur.","Correcting mistakes after they happen.","Evaluating past performance only.","Avoiding risk assessments."],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Feedforward control looks ahead: it spots likely problems before they happen so action can be taken early. Option B describes feedback control, which corrects mistakes after the fact, and C is also about past results. D is wrong because feedforward control depends on assessing risks in advance."}},{"itemId":"2366888a-6a42-55b4-9bc2-814264cac5c9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"93e020f2-3b78-508b-afa9-308f3928f106","sourceKey":"bank:AMS101:AMS101-U111","parentItemId":null,"revision":1,"payload":{"prompt":"Staffing ensures:","options":["The right people are hired for the right positions.","Recruitment processes are eliminated.","Managers handle all tasks alone.","Organizations operate without structured teams."],"correctOption":0,"section":"Managers and Management","explanation":"Staffing is about filling jobs with people who have the right skills, so the right person ends up in the right position. Options B, C and D describe the opposite of staffing, since staffing relies on recruitment and builds structured teams rather than leaving managers to do everything alone."}},{"itemId":"8463d9c8-b4cb-5dea-a7d6-224c6706fc71","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"21a8685c-084d-5a3c-bc0f-2cf7f73fff8f","sourceKey":"bank:AMS101:AMS101-U112","parentItemId":null,"revision":1,"payload":{"prompt":"Recruitment involves:","options":["Identifying and attracting qualified candidates for a job.","Ignoring internal employee growth opportunities.","Hiring underqualified individuals to reduce costs.","Promoting favoritism in hiring practices."],"correctOption":0,"section":"Managing Human Resources","explanation":"Recruitment is the process of finding and attracting qualified people to apply for a job. Options B, C and D describe poor practices that weaken hiring, not what recruitment is meant to do."}},{"itemId":"83412b39-4808-5419-a4fe-ad3637373457","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c275bd81-4e00-5073-aec6-ab9177fb944b","sourceKey":"bank:AMS101:AMS101-U113","parentItemId":null,"revision":1,"payload":{"prompt":"Training employees is important because it:","options":["Enhances skills and boosts organizational performance.","Reduces employee engagement.","Eliminates the need for supervision.","Focuses only on technical skills."],"correctOption":0,"section":"Managing Human Resources","explanation":"Training builds employees' skills, and better-skilled staff improve how well the whole organization performs. Option B is the opposite, since training usually raises engagement. C and D are wrong because trained staff still need supervision, and training covers more than technical skills."}},{"itemId":"34ef41db-9529-5405-b810-cd2138d391c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48a7bd40-1985-59df-9006-f7d8c54ea15f","sourceKey":"bank:AMS101:AMS101-U114","parentItemId":null,"revision":1,"payload":{"prompt":"Retention of employees can be improved through:","options":["Fair compensation and recognition.","Ignoring employee concerns.","Increasing workload without support.","Avoiding professional development opportunities."],"correctOption":0,"section":"Managing Human Resources","explanation":"People are more likely to stay in a job when they are paid fairly and their efforts are recognised. Options B, C and D would push employees to leave rather than keep them."}},{"itemId":"f589e336-fc81-5e31-a2dc-5adf6f01f7eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"37dddebc-518f-5745-b7ee-986f9a9dd471","sourceKey":"bank:AMS101:AMS101-U115","parentItemId":null,"revision":1,"payload":{"prompt":"The purpose of staffing is to:","options":["Ensure an organization has the right number and mix of employees.","Increase employee turnover rates.","Replace recruitment processes with temporary solutions.","Focus only on senior management positions."],"correctOption":0,"section":"Managers and Management","explanation":"Staffing makes sure the organization has enough people, with the right mix of skills, to do its work. Option B is the opposite of the goal, and C and D are too narrow, because staffing covers every level and relies on proper recruitment."}},{"itemId":"db43534d-5830-530a-87e6-db62bc2a635a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5244c05b-6660-52df-a188-7eb3cc6fdf86","sourceKey":"bank:AMS101:AMS101-U116","parentItemId":null,"revision":1,"payload":{"prompt":"There are generally four (4) accepted functions of management, EXCEPT:","options":["Planning","Organising","Departmentalization","Leadership"],"correctOption":2,"section":"Managers and Management","explanation":"The four widely accepted management functions are planning, organising, leading and controlling. Departmentalization is not one of them; it is a way of grouping jobs into units, which is one part of organising. Options A, B and D are all core functions."}},{"itemId":"553dec46-0572-524c-86e7-8be64a3ffa7a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5150983d-5754-54a1-b26b-6c835dee46bf","sourceKey":"bank:AMS101:AMS101-U117","parentItemId":null,"revision":1,"payload":{"prompt":"Planning is the act or process of making or establishing goals, policies, and procedures.","options":["Maybe","None of the above","True","False"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"This is a correct definition: planning means setting goals and deciding on the policies and procedures to reach them. Option D is wrong because the statement is accurate, and A and B do not fit a true-or-false statement."}},{"itemId":"b7c83070-bf8e-5f9f-96fa-0fa0d59a2288","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98604647-5363-59c6-8d1d-1eee39c102b4","sourceKey":"bank:AMS101:AMS101-U118","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an assumption of Maslow's theory?","options":["People's behaviour is not based on their needs","A person moves to the next higher level of the hierarchy only when the lower need is satisfied","Satisfaction of such needs influences their behaviour","A satisfied need can no longer motivate a person; only the next higher-level need can motivate him"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Maslow's theory assumes that behaviour is driven by needs, so saying behaviour is NOT based on needs contradicts it. Options B, C and D are real assumptions of the theory: people move up the hierarchy as lower needs are met, needs shape behaviour, and a satisfied need stops motivating."}},{"itemId":"557bd221-adc7-5453-bba4-caee806b99d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7b4ffc74-e3f1-5d41-809c-d5f5dc0eae08","sourceKey":"bank:AMS101:AMS101-U119","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements does not represent control accurately","options":["Control is related to planning","Control focuses on results and feedback.","Control is a monitoring process.","None of the above"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"All three statements describe control correctly. Control is linked to planning because it checks progress against planned goals, it uses results and feedback, and it is a monitoring process. Since A, B and C are all accurate, 'None of the above' is the right choice."}},{"itemId":"5ccf82d8-9644-5988-bf1b-97a027b76913","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"717bdf3a-6b09-5c2a-8594-c660757ff273","sourceKey":"bank:AMS101:AMS101-U120","parentItemId":null,"revision":1,"payload":{"prompt":"Deciding in advance what is to be done, how and when it is to be done, and who is to do it, describes","options":["Planning","Organising","Directing","Staffing"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Planning means deciding in advance what is to be done, how and when it will be done, and who will do it, before any action starts. Option B, organising, is tempting because it also deals with who does what, but it comes after the plan and arranges the people and resources to carry it out. Options C and D also act on a plan that already exists."}},{"itemId":"314c9659-1292-53ad-a475-9048c13c5185","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"79b8c30b-2340-5a4f-968c-8d089528c274","sourceKey":"bank:AMS101:AMS101-U121","parentItemId":null,"revision":1,"payload":{"prompt":"Directing is a ____","options":["One-day process","Long-term process","Continuous process","Short-term process"],"correctOption":2,"section":"Managers and Management","explanation":"Directing never stops: managers keep guiding, motivating and supervising staff for as long as the organization runs. Options A, B and D wrongly suggest directing has a fixed time span."}},{"itemId":"9e13724f-1b15-5413-ac4d-e43d09aa03db","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e5299ed5-713f-540b-bf51-9257ad050b2a","sourceKey":"bank:AMS101:AMS101-U122","parentItemId":null,"revision":1,"payload":{"prompt":"The organizing principle which holds that an enterprise should be structured to reach its objectives at the lowest cost and with the least waste is....","options":["Efficiency.","Low-margin principle","Proper balance","Exception principle"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The principle of efficiency says an organization should be set up so it reaches its goals at the lowest cost and with the least waste. Option D, the exception principle, is about managers handling only unusual matters, and C, proper balance, is about keeping the parts of the structure in proportion. Option B is not a recognised organizing principle."}},{"itemId":"8134dd97-db0d-5139-8f07-114c9af4d99e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3452a249-4411-5982-a1a0-e009b94e6b70","sourceKey":"bank:AMS101:AMS101-U123","parentItemId":null,"revision":1,"payload":{"prompt":"Which view of management describes a situation in which managers are directly responsible for a company's success or failure?","options":["the structural view of management","the realistic view of management","the symbolic view of management","the omnipotent view of management"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The omnipotent view holds that managers are directly responsible for an organization's success or failure. Option C, the symbolic view, says the opposite: much of what happens is due to outside forces the manager cannot control. A and B are not recognised views of management."}},{"itemId":"935cbb08-bb1e-5f28-a8eb-6b818bde1e94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"715bb67b-5422-58f6-930b-f3bab200f3cf","sourceKey":"bank:AMS101:AMS101-U124","parentItemId":null,"revision":1,"payload":{"prompt":"Coordination mechanisms include all but","options":["Rules and procedures","Organization","Plans and goals","Management hierarchy"],"correctOption":1,"section":"Managers and Management","explanation":"Rules and procedures, plans and goals, and the management hierarchy are all standard tools for coordinating the work of different units. 'Organization' is the whole body being coordinated, not a mechanism for coordinating it, so B is the exception."}},{"itemId":"ca29e8e3-5b79-5b72-ab22-5378feec3eaf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65415740-9859-581a-82da-b535332e454d","sourceKey":"bank:AMS101:AMS101-U126","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a content theory of motivation","options":["McClelland's acquired need theory","Herzberg's two-factor theory","Maslow needs theory","Vrooms expectancy theory"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Vroom's expectancy theory is a process theory: it explains how people decide how much effort to put in, based on what they expect to get. Options A, B and C, from McClelland, Herzberg and Maslow, are content theories, because they focus on what needs motivate people."}},{"itemId":"6434aec8-afa8-5214-aac4-f83fe7a2f7b7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"66bb7a79-0385-5b85-b77d-c230fecedb19","sourceKey":"bank:AMS101:AMS101-U128","parentItemId":null,"revision":1,"payload":{"prompt":"The concept in organizing that encourages the decision-making power is placed at a proper place is","options":["Departmentalization","Delegation of authority","Flexibility.","Span of control"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Delegation of authority passes decision-making power down to the people best placed to make each decision. Option A, departmentalization, groups jobs into units, and D, span of control, is about how many people report to a manager. Neither of these decides where decisions are made."}},{"itemId":"0b97d63e-4f22-5a90-a37b-4e4d2edcc2d6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c8010f8d-9afe-53f5-a316-77449fd90296","sourceKey":"bank:AMS101:AMS101-U129","parentItemId":null,"revision":1,"payload":{"prompt":"When a firm invests in establishing coordination with stakeholders outside the firm, this is known as","options":["Internal coordination","External coordination","Integration coordination","None of the above"],"correctOption":1,"section":"Managers and Management","explanation":"Coordination with people and groups outside the firm, such as suppliers, customers or government, is called external coordination. Option A, internal coordination, is the opposite: it links the firm's own departments and units. Option C is not a recognised type, so D is wrong as well."}},{"itemId":"586bfd42-d336-592a-a4e8-34dbb6f8aa7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a3c9f59-940c-5af7-b836-dbfc5ea6e2aa","sourceKey":"bank:AMS101:AMS101-U130","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a benefit of organizing","options":["It facilitates the division of work","It creates services","It expedites administration","It motivates creativity"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Organising helps divide work, speeds up administration and can encourage creativity by making roles clear. It does not by itself create services; that is the job of the organization's operations. That is why B is the odd one out."}},{"itemId":"88fc8234-db0a-57a0-aa57-9c06704fb94a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7b19b14a-7759-5a2a-b5c3-934ac6d7f903","sourceKey":"bank:AMS101:AMS101-U131","parentItemId":null,"revision":1,"payload":{"prompt":"What is an example of an informal communication channel?","options":["Grapevine","Team meetings","Upward communication","Official memos"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The grapevine is the unofficial network that news and rumours travel through between employees. Options B and D are official channels set up by the organization, and C, upward communication, is a formal direction of flow."}},{"itemId":"ab254398-6ad2-5d69-9114-783fdb854678","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6440e74c-c33e-5ffe-bc73-4bb787007d6a","sourceKey":"bank:AMS101:AMS101-U132","parentItemId":null,"revision":1,"payload":{"prompt":"The causes of coordination problems in organizations include all but","options":["Presence of acceptable plans","Poor communication","Differences in leadership styles","Differences in formality of structure"],"correctOption":0,"section":"Managers and Management","explanation":"Good, acceptable plans help coordination, so they cannot be a cause of coordination problems. Options B, C and D, which are poor communication, clashing leadership styles and different levels of formality between units, all make coordination harder."}},{"itemId":"89c206ca-3439-5658-b678-7bd288a390aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b1f9bb3-943c-5c36-9260-bf0941d557df","sourceKey":"bank:AMS101:AMS101-U133","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an example of a financial incentive?","options":["Profit Sharing","Job Enrichment","Perquisites","Co-partnership"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Job enrichment is a non-financial incentive: it makes work more interesting by adding variety, responsibility and control. Profit sharing, perquisites (perks) and co-partnership all give employees money or money's worth, so they are financial incentives."}},{"itemId":"430a37b0-1113-5b22-85df-b65d430509ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ae891525-4a74-5049-bf87-84df20499f89","sourceKey":"bank:AMS101:AMS101-U134","parentItemId":null,"revision":1,"payload":{"prompt":"What is one of the key traits often associated with effective leadership?","options":["Arrogance","Isolation","Flexibility","Indecisiveness"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Effective leaders are flexible: they adjust their approach to fit people and situations. Options A, B and D, which are arrogance, isolation and indecisiveness, weaken a leader's influence and are not traits of good leadership."}},{"itemId":"27de426a-f1bb-5ae0-a477-c41823cccedb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc87d440-0ab1-5199-9063-4745888c34d2","sourceKey":"bank:AMS101:AMS101-U135","parentItemId":null,"revision":1,"payload":{"prompt":"One of these best describes organizing","options":["The management function that follows after planning","The management function that replaces planning","Controlling students' lectures","The management function that comes before planning"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Organising comes after planning: once goals and plans are set, managers arrange the people, tasks and resources needed to carry them out. Option D gets the order backwards, since planning is the first function. Option B is wrong because organising builds on the plan rather than taking its place."}},{"itemId":"6f2d85c1-8666-57d2-997e-009c994021b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0eff3ce9-3e47-548d-987d-107a8d1c07c2","sourceKey":"bank:AMS101:AMS101-U136","parentItemId":null,"revision":1,"payload":{"prompt":"Management functions terminate with","options":["Coordinating","Controlling","Planning","Organizing"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Controlling is the last management function: it checks actual performance against the plan and corrects any gaps. Planning, option C, is where the cycle starts, and organising comes in between. The results of controlling then feed back into the next round of planning."}},{"itemId":"d856ea1d-bb89-5124-a9f6-3a406a4088bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51d664d7-9ac3-5e35-98ac-1f1ec8d80351","sourceKey":"bank:AMS101:AMS101-U138","parentItemId":null,"revision":1,"payload":{"prompt":"At what level does planning exist?","options":["At all levels","At lower management level only","At top management level only","At middle level management only"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Planning happens at every level of management. Top managers make long-term strategic plans, middle managers make tactical plans, and lower managers plan day-to-day work. Options B, C and D each wrongly limit planning to a single level."}},{"itemId":"ab78f107-565b-5599-8491-0ed0476f5164","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"873638c2-4726-53bd-b359-125c2866c5a2","sourceKey":"bank:AMS101:AMS101-U139","parentItemId":null,"revision":1,"payload":{"prompt":"What is the \"sandwich\" approach in providing feedback?","options":["Avoiding feedback altogether","Starting with criticism, then praise, and ending with criticism","Only providing criticism","Starting with praise, then criticism, and ending with praise"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The sandwich approach puts criticism between two pieces of praise. You start positive, give the critical point, then end positive so the person stays open and motivated. Option B reverses this, and A and C are not the sandwich method."}},{"itemId":"8e3f53c1-fd3b-5274-ab11-1c3bf03c331c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"805435d6-336b-5ee4-bba1-47d54aba920d","sourceKey":"bank:AMS101:AMS101-U140","parentItemId":null,"revision":1,"payload":{"prompt":"An organisations strengths and weaknesses play __________role in corporate planning","options":["A futile","A secondary","A key","An unimportant"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Strengths and weaknesses are the internal side of a SWOT analysis, and assessing them is a key step in strategic or corporate planning. Options B and D understate their importance, and A, 'futile', is wrong because this analysis is central to planning."}},{"itemId":"f3d4383a-b1a0-5d05-9793-485497428593","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7089622f-584a-5584-9be9-883af7ef38c7","sourceKey":"bank:AMS101:AMS101-U141","parentItemId":null,"revision":1,"payload":{"prompt":"The process of synergizing the objectives and efforts of the separate units of an organization in order to achieve the predetermined goals effectively and efficiently is known as","options":["Coordinating","Controlling","Planning","Organizing"],"correctOption":0,"section":"Managers and Management","explanation":"Coordinating means bringing together the goals and efforts of separate units so they work as one towards shared goals. Option D, organising, sets up the structure, and B, controlling, checks performance, but neither is about joining efforts together in this way."}},{"itemId":"9eef87e6-4835-5ea9-9f77-f31c5209c1c1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3dd88bed-d5f9-5dc0-bd6f-19c31c110508","sourceKey":"bank:AMS101:AMS101-U143","parentItemId":null,"revision":1,"payload":{"prompt":"The need for coordination is attributed to","options":["Task specialization","Human differences","Task dependency","All of the above"],"correctOption":3,"section":"Managers and Management","explanation":"Coordination is needed because work is split among specialists, people differ in goals and attitudes, and tasks depend on one another. Since task specialization, human differences and task dependency all create the need for coordination, D is correct. Picking only A, B or C leaves out the other two causes."}},{"itemId":"c69b486e-d22f-5406-bd37-16ee85c95441","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d91913c-68a2-581f-b58b-c08a88ee0a7b","sourceKey":"bank:AMS101:AMS101-U144","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a benefit of wide span of control","options":["Improved communication among staff","Faster decision-making.","There are many people to control","Reduction in cost of managing"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Having many people to oversee is a drawback of a wide span of control, not a benefit, because each manager has less time for each subordinate. Options A, B and D are real benefits: fewer layers mean faster decisions, more direct communication and lower management costs."}},{"itemId":"2fbccdc1-2021-5fcd-bc76-19d427c52202","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ef16355f-6249-56b4-a88d-98bc036a2090","sourceKey":"bank:AMS101:AMS101-U145","parentItemId":null,"revision":1,"payload":{"prompt":"These are the principles of organizing except","options":["Unity of objectives","Simplicity","Delegation of authority","Publicity"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Unity of objectives, simplicity and delegation of authority are all principles of organizing. Publicity is a marketing and communication activity, not a principle for designing an organization's structure."}},{"itemId":"e393ad72-56f7-50ff-a057-115fbee80b4f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"986950f2-281f-5360-b73f-439a3db218c9","sourceKey":"bank:AMS101:AMS101-U146","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements is not true of coordination","options":["Effective coordination cannot be achieved without leadership","Coordination is one of the principles of organization","Coordination is related to organizing","Coordination is not a management function"],"correctOption":3,"section":"Managers and Management","explanation":"Coordination is often called the essence of management, and some writers, including Henri Fayol, list it as a management function in its own right. So saying it is NOT a management function is the untrue statement. Options A, B and C are accepted points: coordination needs leadership, is a principle of organization and is closely tied to organizing."}},{"itemId":"a818d7a8-aad2-51cc-b7e0-bb4f129a235d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d80acefb-5f49-5269-9279-d9db043d6a27","sourceKey":"bank:AMS101:AMS101-U147","parentItemId":null,"revision":1,"payload":{"prompt":"A manager directing his immediate subordinate and taking instructions from his immediate boss is an example of which characteristic of directing?","options":["Directing flows from top to bottom","Directing is a continuous process","Directing initiates action","Both b and c"],"correctOption":0,"section":"Managers and Management","explanation":"Here instructions pass from the boss to the manager and then from the manager to the subordinate. This shows that directing flows from top to bottom through the chain of command. Directing is also continuous (B) and does start action (C), but the example given best shows the downward flow."}},{"itemId":"6e8e293d-ebdb-5793-9dde-2a2bd59ffba8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"21b1efe0-b32b-5800-803c-d9909c2720c5","sourceKey":"bank:AMS101:AMS101-U148","parentItemId":null,"revision":1,"payload":{"prompt":"A common saying is to FAIL to PLAN is to","options":["Plan to fail","None of the above","Fail to succeed","Plan to succeed"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"The saying is 'If you fail to plan, you plan to fail.' Without a plan you are setting yourself up for failure. Options C and D change the wording, so they are not the saying."}},{"itemId":"04c7915d-e00a-591b-be91-87fbaed7dfb1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"38b25b32-dbe1-5296-b1c3-2c5d1e1f1a58","sourceKey":"bank:AMS101:AMS101-U149","parentItemId":null,"revision":1,"payload":{"prompt":"Span of control can be any of the following except","options":["It can be wide","It can be narrow","It can be thin","None of the above is applicable"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A span of control is described as wide, when a manager has many subordinates, or narrow, when there are few. 'Thin' is not a term used for span of control, so C is the exception. Options A and B are both valid descriptions, and since C is an exception, D is wrong too."}},{"itemId":"1199e975-7c55-589e-baaf-0e543a065f29","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a7b3dfa-e2ab-5cb1-b0c9-d760ef6f6aa9","sourceKey":"bank:AMS101:AMS101-U150","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the followings, is correct about management thought","options":["It is developed along with other socio economic development","Management theories were developed out of the practical experience of managers","It is based on the strong foundation laid down by management thinkers","All of the above"],"correctOption":3,"section":"Managers and Management","explanation":"Management thought grew alongside social and economic changes, drew on the practical experience of managers and was built on ideas from earlier thinkers. Since A, B and C are all correct, 'All of the above' is the answer."}},{"itemId":"0800feb8-ba67-5d87-89cb-891610e090e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"55b19232-4037-56e3-909c-b2bee5dd9b72","sourceKey":"bank:AMS101:AMS101-U151","parentItemId":null,"revision":1,"payload":{"prompt":"Which event triggered the recession that began in 2008?","options":["Renters were unable to find available housing","Consumers were unwilling to purchase electronic equipment","Businesses were unable to make loan payments","Homeowners were unable to make mortgage payments"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The 2008 Great Recession started in the mortgage market, when many homeowners could not keep up with their mortgage payments. That turmoil then spread to the wider credit markets and to businesses. So business loan problems, option C, came after, not first."}},{"itemId":"f805d097-9894-5765-bd8e-e76300c5ef82","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"773950ee-1946-505f-b4b3-d6934eb9cdd8","sourceKey":"bank:AMS101:AMS101-U152","parentItemId":null,"revision":1,"payload":{"prompt":"Planning and control are identical in the following respects:","options":["Planning and control utilize quantitative techniques, such as linear programming, statistical control and network analysis.","Both are concerned with identifying and qualifying standards of performance.","The measures utilized for planning are similar to those used for control (e.g. budgets and financial ratio).","All of the above"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Planning and control are twin functions that work closely together. Both can use quantitative techniques, both deal with standards of performance, and they rely on similar measures such as budgets and financial ratios. Since A, B and C are all true, D is correct, and choosing any single one leaves out the others."}},{"itemId":"9f24691e-d66e-5bef-b1f8-8ef2a6f6ed4b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3bbf2c9c-5b28-50c9-8b3d-d12468ebccb1","sourceKey":"bank:AMS101:AMS101-U154","parentItemId":null,"revision":1,"payload":{"prompt":"Identify the correct sequence of steps involved in the motivation process.","options":["Unsatisfied need, tension, drives, search behaviour, satisfied behaviour, reduction of tension","Tension, drives, search behaviour, unsatisfied need, satisfying behaviour, reduction of tension","Search behaviour, reduction of tension, unsatisfied need, tension, drives, satisfied behaviour","Drives, search behaviour, unsatisfied need, tension, satisfying behaviour, reduction of tension"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Motivation starts with an unsatisfied need. The need creates tension, the tension creates drives, and the drives lead to search behaviour. When the need is satisfied, the tension is reduced. Options B, C and D jumble this order, for example by putting tension or drives before the need that causes them."}},{"itemId":"329038d3-9592-543e-8bbc-b58fe3a1754b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5b12546f-0662-545e-a5ae-8bd67c7a9752","sourceKey":"bank:AMS101:AMS101-U156","parentItemId":null,"revision":1,"payload":{"prompt":"Planning is the ____ management function","options":["Second","First","Fourth","Third"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Planning is the first management function, because goals and plans must be set before you can organise, lead or control. The other functions all build on the plan."}},{"itemId":"b2c2ee00-8c08-5953-be00-a111204573a8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b2635d8-321b-5de3-a1ee-80f3c813af9e","sourceKey":"bank:AMS101:AMS101-U157","parentItemId":null,"revision":1,"payload":{"prompt":"A wise way to begin a planning process is by","options":["Determining how to identify customer needs and how to satisfy them","Determining how to evade government rules and regulations","Determining who will be your friends or foes in the business","Determining how much profit you want to make out of the business"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A business exists to serve customers, so a sensible plan starts by working out what customers need and how to meet those needs. Option D, profit, matters, but profit comes from satisfying customers. Option B is unethical and illegal."}},{"itemId":"68d7e71f-c80f-5139-b4f9-b91d000817ee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"97458524-486b-5f35-9984-9f472bafa72e","sourceKey":"bank:AMS101:AMS101-U158","parentItemId":null,"revision":1,"payload":{"prompt":"Organizing is to structure, as planning is to ____","options":["Motivation","Leading","A & B","Goal setting"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Organizing produces structure, and planning produces goals and the ways to reach them, so planning goes with goal setting. Options A and B, motivation and leading, belong to the leading function, not planning."}},{"itemId":"2140833c-1303-5509-855c-f1ba4c59cd0d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9718a603-099e-5e20-9e95-1849e625e433","sourceKey":"bank:AMS101:AMS101-U159","parentItemId":null,"revision":1,"payload":{"prompt":"These needs are most basic in the hierarchy of motivation theory and correspond to primary needs","options":["Basic Physiological Needs","Belonging Needs","Self Actualisation Needs","Security Needs"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Physiological needs, such as food, water, shelter and sleep, form the base of Maslow's hierarchy. They are the primary needs for survival. Option D, security needs, comes next, and B and C are higher-level needs."}},{"itemId":"2c178ea9-7c81-5946-b95b-3eaea3d1ad0a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"99a2564c-0dd3-57cd-beaf-fdfe0fa52d22","sourceKey":"bank:AMS101:AMS101-U161","parentItemId":null,"revision":1,"payload":{"prompt":"According to situational leadership theory, what does effective leadership depend on?","options":["The leader's charisma","Strict adherence to a single leadership style","The leader's inherent traits","The readiness level of followers and task demands"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Situational leadership theory says the best leadership style depends on the followers' readiness, meaning their ability and willingness, and on what the task demands. Options A and C focus on the leader alone, which is trait thinking. B is the opposite of the theory, which is all about changing style."}},{"itemId":"36849b46-3d66-5b79-8337-ff0a08f31004","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"82e8e344-0877-5fc6-af4d-6c385d40e47b","sourceKey":"bank:AMS101:AMS101-U162","parentItemId":null,"revision":1,"payload":{"prompt":"All but one of the following are included in planning","options":["Creating specific problems","Developing a course of action","Selecting a course of action","Decision-making"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Planning involves making decisions, developing possible courses of action and selecting the best one. Creating problems is not part of planning, since planning is about solving problems and reaching goals."}},{"itemId":"fbf9d272-6178-51ff-b178-6c2ea2ab357e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"10e60306-5e46-52e3-9ac4-3c4141b0dddf","sourceKey":"bank:AMS101:AMS101-U163","parentItemId":null,"revision":1,"payload":{"prompt":"What is a characteristic of transformational leaders?","options":["Relying on contingent rewards","Authoritarian decision-making","Encouraging innovation and creativity","Focus on stability and routine"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Transformational leaders inspire followers to look beyond their own interests and encourage new ideas, innovation and creativity. Option A, contingent rewards, describes transactional leaders, and D, a focus on stability and routine, also fits a transactional style."}},{"itemId":"1bbee6b2-f0c0-514e-b958-84df88e0841b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25b32965-1bfe-545f-87e1-6927f381337b","sourceKey":"bank:AMS101:AMS101-U165","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following contributed most to many companies becoming highly leveraged in the lead-up to the economic downturn in 2008?","options":["No liquidity","limited liquidity","low interest rates","high interest rates"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Low interest rates made borrowing cheap, so many companies took on large amounts of debt, becoming highly leveraged, before 2008. Option D is the reverse, since high rates discourage borrowing. A and B are wrong because credit was easy to get at the time."}},{"itemId":"769e4ae5-b9fc-5605-8319-22ae190d025d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7972ad8c-f0e6-5668-951a-87a328998502","sourceKey":"bank:AMS101:AMS101-U166","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication channel usually allows the most immediate feedback?","options":["Grapevine","Face-to-face communication","Electronic communication","Email"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Face-to-face communication happens in person, so the listener can respond right away and the speaker sees reactions immediately. Options C and D, electronic communication and email, usually involve a delay, and A, the grapevine, is an informal network, not a face-to-face channel as such."}},{"itemId":"be43acb8-768e-5145-b060-618529700878","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fbd4bfdb-25b8-5d86-a779-496d00761c2c","sourceKey":"bank:AMS101:AMS101-U167","parentItemId":null,"revision":1,"payload":{"prompt":"Organisations or/and individuals set goals and objectives they hope to achieve","options":["None of the above","True","Maybe","False"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"This is true: both organisations and individuals set goals and objectives they hope to reach, which gives them direction. Option D is wrong because goal setting is a basic part of planning for both."}},{"itemId":"91e6b613-36bb-5d3d-9004-8256297dc24d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b342b33-9bab-5d14-a3e2-d31d7735b599","sourceKey":"bank:AMS101:AMS101-U168","parentItemId":null,"revision":1,"payload":{"prompt":"While other functions prepare a setting for action, name the function that initiates the action in the organisation","options":["Directing","Organising","Staffing","Planning"],"correctOption":0,"section":"Managers and Management","explanation":"Directing is the function that starts action. It gets people working by giving instructions, guidance and motivation. Planning, organising and staffing (D, B and C) prepare the setting, but nothing actually happens until people are directed."}},{"itemId":"44ab5bd6-564a-5b8e-a3ea-2a0178ddeb8b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b03782c2-a95c-53cc-b9ab-19d63aa12822","sourceKey":"bank:AMS101:AMS101-U170","parentItemId":null,"revision":1,"payload":{"prompt":"____ refers to overseeing what is being done by subordinates and giving instructions to ensure optimum utilization of resources and achievement of work targets","options":["supervision","leadership","communication","motivation"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Supervision means watching over the work of subordinates and guiding them so that resources are used well and targets are met. Option B, leadership, is about influence and inspiration more broadly, and D, motivation, is about creating the will to work."}},{"itemId":"0437b473-7b78-5c08-abc4-843722f6c2b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca3056ed-64bb-57f5-b8e9-09012d3f8875","sourceKey":"bank:AMS101:AMS101-U172","parentItemId":null,"revision":1,"payload":{"prompt":"Which one of the following is responsible for the failure of coordinating a firm?","options":["Economic recession","Lack of funds","Lack of commitment","Economic depression"],"correctOption":2,"section":"Managers and Management","explanation":"Coordination depends on people and units being willing to work together. When there is a lack of commitment, efforts pull apart and coordination fails. Options A, B and D, recession, lack of funds and depression, can hurt a firm, but they are outside factors and not the cause of coordination failure itself."}},{"itemId":"abb1908b-c69e-5e2b-8f8f-0af8393a2af3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6f477d09-b38f-55de-b52d-bf595d2d656c","sourceKey":"bank:AMS101:AMS101-U173","parentItemId":null,"revision":1,"payload":{"prompt":"Which leadership theory emphasizes the importance of adapting leadership style to the situation?","options":["Contingency Theory","Behavioral Theory","Transformational Leadership","Transactional Leadership"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Contingency theory says there is no one best way to lead: the right style depends on the situation. Option B, behavioural theory, looks for the best behaviours of leaders, while C and D describe particular leadership styles rather than adapting to circumstances."}},{"itemId":"c9b8eed4-c4ea-5f44-8e65-431dba0903c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"325397b7-a0a0-5227-ae30-235a67d8ce91","sourceKey":"bank:AMS101:AMS101-U174","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the followings, is correct about Decision making function?","options":["It leads to performance monitoring","It involves choosing the best course of action from available alternatives","It leads to industrial harmony","All of the above"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Decision making means choosing the best course of action from the available alternatives. Options A and C may happen afterwards, but they do not define decision making. That is why D, 'All of the above', is wrong."}},{"itemId":"9a1ceb9d-eeef-56a7-b8be-59a6a07edcdb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee4e1da1-4812-5fe4-b013-2651464c2bb2","sourceKey":"bank:AMS101:AMS101-U175","parentItemId":null,"revision":1,"payload":{"prompt":"Management is the process of getting things done effectively and efficiently with and through:","options":["Money","People","Machines","Rules"],"correctOption":1,"section":"Managers and Management","explanation":"Management is about getting things done effectively and efficiently with and through people, because it is people who carry out the work. Money and machines (options A and C) are resources that people use, and rules (D) only guide what people do."}},{"itemId":"6702dcca-81f6-5635-a798-ecb14fb9d82f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e5ac689-27f0-5d45-abe4-628cf8459e48","sourceKey":"bank:AMS101:AMS101-U176","parentItemId":null,"revision":1,"payload":{"prompt":"The process of planning, organizing, leading, and controlling resources to achieve goals is known as:","options":["Administration","Management","Leadership","Coordination"],"correctOption":1,"section":"Managers and Management","explanation":"Management is the process of planning, organizing, leading and controlling resources so that goals are reached effectively and efficiently. Leadership (C) and coordination (D) are only parts of this process. Administration (A) is usually used for applying policies rather than for the full set of functions."}},{"itemId":"66dc91a5-7065-5ad6-92cc-300b01b04129","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f798cbbe-8e58-5acc-9224-d904816b0dd5","sourceKey":"bank:AMS101:AMS101-U177","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a function of management?","options":["Planning","Organizing","Innovating","Controlling"],"correctOption":2,"section":"Managers and Management","explanation":"The core management functions are planning, organizing, leading and controlling. Innovating is important for organizations, but it is not one of the basic functions. Options A, B and D are all core functions."}},{"itemId":"fde91f92-12ce-5d26-a355-4997c262bb50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05135367-d2c3-51d1-af40-9d982ef8b53c","sourceKey":"bank:AMS101:AMS101-U178","parentItemId":null,"revision":1,"payload":{"prompt":"The management function that involves setting objectives and determining a course of action is:","options":["Organizing","Controlling","Planning","Directing"],"correctOption":2,"section":"Managers and Management","explanation":"Planning means setting objectives and deciding how to achieve them. Organizing (A) arranges work and resources to carry out the plan, and controlling (B) checks progress afterwards."}},{"itemId":"bd186e31-62f7-5401-9b70-3c63c07c580c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d74be3c9-0bc4-52e0-b5fe-b1f2d9532a58","sourceKey":"bank:AMS101:AMS101-U180","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes strategic planning?","options":["Long-term planning","Short-term planning","Medium-term planning","Operational planning"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Strategic planning sets the overall direction of the whole organization and covers a long period. Option B, short-term planning, fits operational planning (D), which deals with day-to-day activities, and C, medium-term planning, fits tactical planning."}},{"itemId":"2aea4353-3880-5318-be73-e71f91759130","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"afa9664c-0078-5aa7-bc45-663a1220b917","sourceKey":"bank:AMS101:AMS101-U181","parentItemId":null,"revision":1,"payload":{"prompt":"Organizing in management refers to:","options":["Assigning responsibilities","Motivating employees","Controlling outcomes","Evaluating performance"],"correctOption":0,"section":"Managers and Management","explanation":"Organizing is about arranging and structuring work, which includes assigning tasks and responsibilities to people. Motivating employees (B) belongs to leading, while controlling outcomes (C) and evaluating performance (D) belong to controlling."}},{"itemId":"de6f8a87-e2c6-5027-b121-33b11439f6e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16aa5fd7-b7bd-5396-858f-976162f9fe06","sourceKey":"bank:AMS101:AMS101-U182","parentItemId":null,"revision":1,"payload":{"prompt":"The process of influencing others to achieve organizational goals is called:","options":["Planning","Leading","Controlling","Staffing"],"correctOption":1,"section":"Managers and Management","explanation":"Leading is the function of influencing, motivating and directing people so they work towards organizational goals. Planning (A) sets those goals, controlling (C) checks progress, and staffing (D) fills jobs."}},{"itemId":"268d5551-1bc8-558f-a6f5-559e0f871dff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"124cd6cf-9c75-536e-bd1f-8b6e7c8ece72","sourceKey":"bank:AMS101:AMS101-U183","parentItemId":null,"revision":1,"payload":{"prompt":"Which management function ensures that organizational goals are met efficiently?","options":["Planning","Organizing","Controlling","Staffing"],"correctOption":2,"section":"Managers and Management","explanation":"Controlling checks actual results against the goals and corrects deviations, so it makes sure goals are actually met and resources are not wasted. Planning (A) sets the goals but cannot by itself make sure they are reached. Organizing (B) arranges the work to be done."}},{"itemId":"1cc85965-c2bf-5a97-a35b-fe9c48510889","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9852a445-bb75-5fe2-ae4b-81f3c950c4ab","sourceKey":"bank:AMS101:AMS101-U184","parentItemId":null,"revision":1,"payload":{"prompt":"The term 'span of control' refers to:","options":["The number of employees a manager can effectively manage","The range of control systems used in an organization","The managerial hierarchy in an organization","The control measures implemented by management"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Span of control is the number of employees a manager can efficiently and effectively supervise. Option C, the hierarchy, is related but is the overall chain of levels, and B and D wrongly treat 'control' as control systems or measures."}},{"itemId":"cbbbe10c-2397-5fda-8b45-3ee3d62ce87b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16853571-0601-5405-a3d6-636f78058464","sourceKey":"bank:AMS101:AMS101-U185","parentItemId":null,"revision":1,"payload":{"prompt":"A key characteristic of management is:","options":["It is rigid","It is continuous","It is temporary","It is optional"],"correctOption":1,"section":"Managers and Management","explanation":"Management is continuous: planning, organizing, leading and controlling keep going for as long as the organization exists. Options A, C and D are wrong because management is flexible, ongoing and necessary."}},{"itemId":"d82d2ca8-47fe-524b-98a4-745415e04f23","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba6e7218-13d5-5064-9830-ac63a3ac2aff","sourceKey":"bank:AMS101:AMS101-U186","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes the term \"efficiency\"?","options":["Getting the most output from the least input","Maximizing resource wastage","Achieving objectives without concern for resources","Using maximum resources for any task"],"correctOption":0,"section":"Managers and Management","explanation":"Efficiency means 'doing things right': getting the most output from the fewest inputs, with as little waste as possible. Options B and D describe waste, and C ignores resources completely, which is the opposite of efficiency."}},{"itemId":"caf76151-df20-5709-a1d1-178a619449b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e7281396-2508-5f39-9972-86d59e212780","sourceKey":"bank:AMS101:AMS101-U187","parentItemId":null,"revision":1,"payload":{"prompt":"The process of recruiting, selecting, and training employees falls under:","options":["Planning","Staffing","Leading","Controlling"],"correctOption":1,"section":"Managers and Management","explanation":"Staffing covers recruiting, selecting, training and developing the people who fill an organization's jobs. Leading (C) is about influencing people who are already in place, and planning (A) and controlling (D) are not about filling jobs."}},{"itemId":"18c91e5b-2952-547a-8f98-917717ea6c92","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8df34c74-5ec0-528e-a0cb-4ff73bdd7505","sourceKey":"bank:AMS101:AMS101-U188","parentItemId":null,"revision":1,"payload":{"prompt":"Who proposed the 14 Principles of Management?","options":["Max Weber","Henry Fayol","Peter Drucker","Frederick Taylor"],"correctOption":1,"section":"Managers and Management","explanation":"Henri Fayol, a French industrialist, proposed the 14 principles of management, along with the management functions. Max Weber (A) described bureaucracy, and Frederick Taylor (D) developed scientific management."}},{"itemId":"554bcf3c-49d5-5e0e-863a-5501bcacaa33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7fca5834-b6ed-5799-95a6-fe3f6d5855a8","sourceKey":"bank:AMS101:AMS101-U189","parentItemId":null,"revision":1,"payload":{"prompt":"The scientific management approach focuses on:","options":["Employee relations","Work methods and productivity","Emotional intelligence","Strategic leadership"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management studies work methods to find the 'one best way' to do a job and raise productivity. Employee relations (A) were the focus of the later behavioural and human relations approaches, not scientific management."}},{"itemId":"d92d5a54-9c25-535c-8584-ba4be08642c7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eb2f0d32-2472-5d81-9d25-b23de440f3eb","sourceKey":"bank:AMS101:AMS101-U190","parentItemId":null,"revision":1,"payload":{"prompt":"Rational decision making in management involves:","options":["Random choices","Logical and rational selection","Emotional influences","Personal preferences"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Rational decision making means making logical, consistent choices that give the most value within the limits the manager faces. Option C is tempting because emotions and feelings do shape real decisions through intuition, but that is not rational decision making. Options A and D, random choices and personal preferences, are not logical selection either."}},{"itemId":"991d1b23-f32f-5369-8efc-7cafd3d01d2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"870b0af2-e172-5715-8f60-fb1251f1490e","sourceKey":"bank:AMS101:AMS101-U191","parentItemId":null,"revision":1,"payload":{"prompt":"A formal structure of authority in an organization is known as:","options":["Delegation","Hierarchy","Leadership","Empowerment"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A hierarchy is the formal structure of authority, showing who reports to whom from the top of the organization to the bottom. Delegation (A) is passing authority down, and empowerment (D) is giving employees more decision-making power. Neither is the structure itself."}},{"itemId":"54911076-2b0a-5c09-87bd-99c095fa9832","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"655bfd5d-c806-579c-9e75-82f08589615f","sourceKey":"bank:AMS101:AMS101-U192","parentItemId":null,"revision":1,"payload":{"prompt":"The management function that involves monitoring performance and making adjustments is:","options":["Planning","Organizing","Controlling","Staffing"],"correctOption":2,"section":"Managers and Management","explanation":"Controlling means monitoring, comparing and correcting work performance. Planning (A) sets the goals, and organizing (B) arranges the work, but checking results and adjusting is the job of controlling."}},{"itemId":"9c08d440-b56e-5e6d-bddd-1ff488985967","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cdeedb5d-b22c-58f8-b204-d9674a2d1106","sourceKey":"bank:AMS101:AMS101-U193","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of planning focuses on day-to-day operations?","options":["Strategic planning","Tactical planning","Operational planning","Contingency planning"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Operational planning covers day-to-day activities, telling people how routine work will be carried out. Strategic planning (A) is long-term and covers the whole organization, and tactical planning (B) is in between. Contingency planning (D) prepares for unexpected events."}},{"itemId":"f58844bf-496b-52d3-a793-cf87f2e1340f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa1c4369-f8df-5920-85c4-36bb41a68636","sourceKey":"bank:AMS101:AMS101-U194","parentItemId":null,"revision":1,"payload":{"prompt":"The study of management as a discipline began in:","options":["18th century","19th century","20th century","21st century"],"correctOption":2,"section":"Managers and Management","explanation":"Management was practised for thousands of years, but it became a formal field of study in the early 1900s, when Frederick Taylor published his work on scientific management. That places the start in the 20th century. Earlier ideas, such as Adam Smith's division of labour in the 18th century, came before management was a separate discipline."}},{"itemId":"37677f4e-32de-5b11-9ca4-7d56cd8848ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"60f6cd1d-3ff3-5a92-bde8-0df234703f07","sourceKey":"bank:AMS101:AMS101-U195","parentItemId":null,"revision":1,"payload":{"prompt":"The term 'motivation' in management refers to:","options":["Encouraging employees to work","Organizing tasks","Evaluating performance","Controlling resources"],"correctOption":0,"section":"Managers and Management","explanation":"Motivation is about encouraging employees to put effort into their work and keep it up. Organizing tasks (B) belongs to organizing, and evaluating performance (C) and controlling resources (D) belong to controlling."}},{"itemId":"72c3039b-a545-57a7-83b8-892246ca42e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"975e8a38-612c-5462-bf0a-3da591067e57","sourceKey":"bank:AMS101:AMS101-U196","parentItemId":null,"revision":1,"payload":{"prompt":"Authority in management refers to:","options":["Responsibility to complete tasks","The right to make decisions and give orders","Employee motivation","Formalized structure"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Authority is the right that comes with a manager's position to make decisions and give orders. Option A, responsibility, is the duty to carry out assigned tasks, which goes with authority but is not the same thing. Authority also differs from power, which is the wider capacity to influence decisions."}},{"itemId":"203780ce-f666-5c4c-97b0-6d786d2421b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d9233d6e-20d8-5524-999e-750a607c7f98","sourceKey":"bank:AMS101:AMS101-U197","parentItemId":null,"revision":1,"payload":{"prompt":"Effective communication in management helps in:","options":["Conflicts","Coordination","Resource wastage","Reducing efficiency"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Clear communication keeps people informed and in step with one another, which makes coordination possible. Options A, C and D, conflicts, waste and lower efficiency, are what poor communication causes."}},{"itemId":"840d773a-f640-55c9-8c63-2b213e0d2f63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"948f6bab-df87-54d0-a126-7c66a2457791","sourceKey":"bank:AMS101:AMS101-U199","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in the planning process is:","options":["Setting objectives","Evaluating alternatives","Identifying resources","Implementing the plan"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Planning starts with setting objectives, because you need to know what you want to achieve before you can choose how to get there. Evaluating alternatives (B) and identifying resources (C) come next, and implementing the plan (D) comes last."}},{"itemId":"291f6e52-4265-57e3-bc73-5806f9b94ff9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b402ddb2-f676-5cb6-8548-c6d96c468995","sourceKey":"bank:AMS101:AMS101-U200","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's primary goal is to achieve:","options":["Maximum profit","Effective teamwork","Organizational objectives","Employee satisfaction"],"correctOption":2,"section":"Managers and Management","explanation":"A manager's main job is to achieve the organization's goals effectively and efficiently. Profit (A), teamwork (B) and employee satisfaction (D) can all be part of those goals, but none of them is the full picture on its own."}},{"itemId":"103a6710-816c-5bb2-9cc4-da9807211bfd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"298bd75d-91ef-5cc0-9cff-5a5af43bf552","sourceKey":"bank:AMS101:AMS101-U201","parentItemId":null,"revision":1,"payload":{"prompt":"A decentralized organization structure involves:","options":["Decision-making at lower levels","Centralized control","No decision-making","Informal operations"],"correctOption":0,"section":"Organization Design and Structure","explanation":"In a decentralized organization, lower-level managers give input or make decisions themselves instead of everything being decided at the top. Option B, centralized control, describes centralization, the opposite approach."}},{"itemId":"520c98f4-ec27-532a-80a8-9bcde338e16a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8c71d9b9-c6c1-5c1d-9dc5-dc4cac3c8e0d","sourceKey":"bank:AMS101:AMS101-U202","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of 'delegation' means:","options":["Transferring authority to subordinates","Retaining all authority","Increasing workload","Avoiding responsibility"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Delegation means a manager passes some authority to subordinates so they can make decisions and carry out tasks. Option B is the opposite, and D is wrong because the manager stays accountable even after delegating."}},{"itemId":"3eb91127-118e-5dfd-b67d-6b4b8cad986c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e1a125f9-098b-5c41-87fe-53ab4e4e1282","sourceKey":"bank:AMS101:AMS101-U203","parentItemId":null,"revision":1,"payload":{"prompt":"Which management style is most participatory?","options":["Autocratic","Democratic","Laissez-faire","Bureaucratic"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"A democratic style involves employees in decisions and encourages them to share ideas, so it is the most participatory. Autocratic leaders (A) decide alone, laissez-faire leaders (C) mostly stay out of the way, and bureaucratic leaders (D) go by the rules."}},{"itemId":"bc87f6f1-8de3-5b7d-bb63-6f4c01ece5f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"91db946e-5a7e-53c3-9f92-42876dc2263f","sourceKey":"bank:AMS101:AMS101-U204","parentItemId":null,"revision":1,"payload":{"prompt":"The controlling function in management involves:","options":["Establishing performance standards","Planning budgets","Motivating employees","Leading teams"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Controlling begins by setting performance standards, which actual results are then measured against so deviations can be corrected. Planning budgets (B) is part of planning, and motivating employees (C) and leading teams (D) belong to leading."}},{"itemId":"639a52dd-bab5-5fab-964c-56fde6d88d7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b6bca9e0-7eb5-5d15-b3e9-74ea5e0ec394","sourceKey":"bank:AMS101:AMS101-U205","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a characteristic of bureaucracy?","options":["Flexibility","Hierarchical structure","Lack of rules","Informal decision-making"],"correctOption":1,"section":"Managers and Management","explanation":"Max Weber's bureaucracy has a clear hierarchy of authority, along with detailed rules and impersonal procedures. Flexibility (A), lack of rules (C) and informal decision-making (D) are the opposite of bureaucracy."}},{"itemId":"830687c3-a462-5f41-840e-75f80aa4a2dd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b98c1bf7-5020-5581-b692-116b411a6161","sourceKey":"bank:AMS101:AMS101-U206","parentItemId":null,"revision":1,"payload":{"prompt":"Which management level is responsible for strategic decision-making?","options":["Top-level management","Middle-level management","Operational-level management","Supervisory-level management"],"correctOption":0,"section":"Managers and Management","explanation":"Top-level managers, such as the CEO and vice-presidents, make decisions about the direction of the whole organization. These are strategic decisions. Middle managers (B) turn those decisions into tactical plans, and first-line or supervisory managers (C and D) handle daily operations."}},{"itemId":"b6951bc8-9273-5e00-9bf8-469c36996c2c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f56a6d13-bb73-5f0d-8f57-d424a0799e92","sourceKey":"bank:AMS101:AMS101-U207","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership styles include all except:","options":["Transformational","Autocratic","Transactional","Functional"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Transformational, autocratic and transactional are all recognised leadership styles. 'Functional' is not a standard leadership style, so it is the exception."}},{"itemId":"ca92ea81-1123-5bdf-af72-c7bf5b009df3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"08bcef69-162f-5e81-a116-9b5ca0205751","sourceKey":"bank:AMS101:AMS101-U208","parentItemId":null,"revision":1,"payload":{"prompt":"The principle of 'division of work' aims to:","options":["Increase specialization","Reduce workload","Improve coordination","Avoid conflicts"],"correctOption":0,"section":"Managers and Management","explanation":"Division of work splits jobs into smaller, specialised tasks, which lets workers become skilled and productive. This idea goes back to Adam Smith's division of labour. Options B, C and D may follow as side effects, but specialization is the main aim."}},{"itemId":"5249ce57-5b4a-525a-8184-274eec83e61b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"62a49ef6-1931-511f-855f-44af490c67c6","sourceKey":"bank:AMS101:AMS101-U209","parentItemId":null,"revision":1,"payload":{"prompt":"Which concept focuses on customer satisfaction and continuous improvement?","options":["Scientific management","Total quality management","Bureaucracy","Motivation theories"],"correctOption":1,"section":"Managers and Management","explanation":"Total quality management (TQM) is built around customer focus and continuous improvement of quality. Scientific management (A) focuses on efficient work methods, and bureaucracy (C) on rules and hierarchy."}},{"itemId":"8f626b65-74db-5154-800d-43ffa753019b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"801c4037-dfe7-5c7f-b634-f82cf0c8fb6b","sourceKey":"bank:AMS101:AMS101-U210","parentItemId":null,"revision":1,"payload":{"prompt":"Management by Objectives (MBO) was introduced by:","options":["Peter Drucker","Elton Mayo","Henry Mintzberg","Max Weber"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Management by Objectives was introduced by Peter Drucker. Under MBO, managers and employees agree on specific goals together and then review progress against them. Elton Mayo (B) is linked to human relations, Henry Mintzberg (C) to managerial roles and Max Weber (D) to bureaucracy."}},{"itemId":"6b7b6207-6684-596b-9a43-42ba0b1ca772","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5ad9d217-5c6a-52b5-8aec-13d646b4ae97","sourceKey":"bank:AMS101:AMS101-U212","parentItemId":null,"revision":1,"payload":{"prompt":"The Hawthorne studies focused on:","options":["Productivity and human relations","Employee pay scales","Scientific work design","Job descriptions"],"correctOption":0,"section":"Managers and Management","explanation":"The Hawthorne studies showed that social factors and group pressure strongly affect workers' productivity, which gave rise to the human relations movement. Option C, scientific work design, was Taylor's focus, and B and D were not the focus of these studies."}},{"itemId":"cd85e6f5-e886-5f62-989e-694e26b745df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05095dda-49a3-500b-8051-792564818a98","sourceKey":"bank:AMS101:AMS101-U213","parentItemId":null,"revision":1,"payload":{"prompt":"A contingency approach to management emphasizes:","options":["One-size-fits-all solutions","Flexible strategies","Fixed rules","Employee preferences"],"correctOption":1,"section":"Managers and Management","explanation":"The contingency approach says there is no one best way to manage, and the right approach depends on the situation. Managers therefore need flexible strategies. Options A and C, one-size-fits-all solutions and fixed rules, are the opposite of this idea."}},{"itemId":"5ea4b64f-dc8e-54fc-a3b5-0a0293bff0a0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c886550-4777-5b07-990e-6ec5dd06b135","sourceKey":"bank:AMS101:AMS101-U215","parentItemId":null,"revision":1,"payload":{"prompt":"The scalar chain principle in management emphasizes:","options":["Direct communication with top management","Clear lines of authority from top to bottom","Flexible communication channels","Employee empowerment"],"correctOption":1,"section":"Managers and Management","explanation":"The scalar chain is the unbroken line of authority running from the top of the organization to the bottom, which communication normally follows. Option A, direct communication with top management, would bypass the chain, and C and D are not what this principle is about."}},{"itemId":"42b71701-69cd-511d-b4e0-f5c89a05e901","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"45fb3059-4d09-53db-8cae-70765148ad6b","sourceKey":"bank:AMS101:AMS101-U216","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a type of managerial role as identified by Henry Mintzberg?","options":["Interpersonal","Informational","Decision-making","Technical"],"correctOption":3,"section":"Managers and Management","explanation":"Mintzberg grouped managerial roles into three categories: interpersonal, informational and decisional, which is decision-making. 'Technical' is a type of managerial skill, not one of Mintzberg's role categories."}},{"itemId":"79b99a07-3469-591a-b453-129d2d687513","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"29a71db2-012c-5f71-9cad-2606c1079a9a","sourceKey":"bank:AMS101:AMS101-U217","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"corporate social responsibility\" refers to:","options":["Legal compliance only","Ethical business practices towards society","Maximizing shareholder wealth","Reducing operating costs"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Corporate social responsibility means a company aims to do the right things and act in ways that are good for society. Option A, legal compliance only, is the bare minimum, and C and D focus only on the company's own financial interests."}},{"itemId":"067f0faf-8c15-5283-b474-b85ef74951d3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e54524b1-5ee8-50e0-b05a-23f1824eddb1","sourceKey":"bank:AMS101:AMS101-U218","parentItemId":null,"revision":1,"payload":{"prompt":"A mission statement typically describes:","options":["The organization's financial status","The company's long-term aspirations","The organization's purpose and direction","The organizational structure"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A mission statement says what the organization exists to do, giving its purpose and direction. Long-term aspirations (B) are the subject of a vision statement, and financial status (A) and structure (D) are not covered in a mission statement."}},{"itemId":"eb080120-6857-5c14-94fb-43a5d79407bf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c240e201-423f-59eb-a0b0-07f0cdf250e9","sourceKey":"bank:AMS101:AMS101-U219","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of decision is taken at the operational level of management?","options":["Strategic decisions","Tactical decisions","Routine decisions","Policy decisions"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Operational (first-line) managers handle everyday, repetitive problems, so their decisions are routine or programmed and can follow set procedures. Options A and D are strategic and policy decisions made by top management, while option B, tactical decisions, belongs mainly to middle managers."}},{"itemId":"3942308a-406f-5b40-bf81-c224de486bed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fcf65c58-df65-5ddd-a810-699a4686cb30","sourceKey":"bank:AMS101:AMS101-U220","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of \"unity of direction\" in management suggests:","options":["Employees should follow multiple goals simultaneously","Efforts of an organization should be focused on common objectives","Supervisors should take on multiple roles","Employees should be flexible in their roles"],"correctOption":1,"section":"Managers and Management","explanation":"Unity of direction is one of Fayol's principles: all activities with the same objective should follow one plan under one head, so the organization's efforts point toward common goals. Option A is the opposite of this idea, and options C and D describe role flexibility, which has nothing to do with unity of direction."}},{"itemId":"0346e16d-3b5a-5b0b-8f25-a6a9c60591e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d32d99f3-cb2b-5dde-9b17-97cd14bfb98e","sourceKey":"bank:AMS101:AMS101-U221","parentItemId":null,"revision":1,"payload":{"prompt":"Benchmarking is a technique used for:","options":["Cutting the number of managers","Comparing with industry best practices","Motivating employees","Reducing competition"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Benchmarking means searching for the best practices among competitors or other organizations and comparing your own performance against them so you can improve. Option A describes delayering, not benchmarking, and options C and D are not its purpose."}},{"itemId":"969bdfb8-ea51-52bb-9a86-64dcabe1d0db","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b497faad-fd76-5d59-9643-84b5e8464a16","sourceKey":"bank:AMS101:AMS101-U222","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an external factor affecting management?","options":["Employee skills","Organizational culture","Government regulations","Work processes"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The external environment is made up of forces outside the organization that affect its performance, and government regulations are a clear example. Options A, B and D (employee skills, organizational culture and work processes) all exist inside the organization, so they are internal factors."}},{"itemId":"21e8fe6a-7e7e-5b2e-b4ba-120ebb70b19d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98a59c21-9c54-5f57-b00f-55e579aabd84","sourceKey":"bank:AMS101:AMS101-U223","parentItemId":null,"revision":1,"payload":{"prompt":"In which stage of the decision-making process are alternatives evaluated?","options":["Problem identification","Alternative analysis","Implementation","Monitoring"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"After the alternatives have been developed, the decision maker analyses each one by weighing it against the decision criteria, which shows its strengths and weaknesses. Problem identification (A) comes earlier, before any alternatives exist, while implementation and monitoring (C and D) come after a choice has been made."}},{"itemId":"498d8b18-8b5a-5ee3-a996-5efc86bd75eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"389be575-d994-5815-8850-55a63c5f1845","sourceKey":"bank:AMS101:AMS101-U224","parentItemId":null,"revision":1,"payload":{"prompt":"A flat organizational structure is characterized by:","options":["Many hierarchical levels","Few levels of management","Strict chain of command","Centralized decision-making"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A flat structure has few layers between the top and the bottom, usually with wide spans of control and more decentralized decisions. Options A, C and D describe a tall, centralized structure with many levels and a strict chain of command, which is the opposite."}},{"itemId":"2c759d43-e358-544d-ba40-78d98d75416b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fed0cf47-4608-5791-ac61-6709f23d38c5","sourceKey":"bank:AMS101:AMS101-U225","parentItemId":null,"revision":1,"payload":{"prompt":"Management is considered both a science and an art because it involves:","options":["Creativity and structure","Rigidity and flexibility","Rules and regulations","None of the above"],"correctOption":0,"section":"Managers and Management","explanation":"Management is a science because it has an organized, structured body of principles, and an art because applying those principles well takes creativity and personal skill. Option B pairs opposites that do not explain the dual nature, and option C covers only the rule-based, scientific side."}},{"itemId":"25cde98b-f037-5028-ade2-81548c2d2737","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"596b6cef-ce3c-5697-ab1d-0031197ba17c","sourceKey":"bank:AMS101:AMS101-U226","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes management as a science?","options":["It relies on personal judgment","It follows systematic principles","It depends on intuition","It is based on experience only"],"correctOption":1,"section":"Managers and Management","explanation":"A science is a systematic body of knowledge built on principles that can be tested and applied, and management has such principles. Options A, C and D (personal judgment, intuition and experience) describe the art side of management, not the science side."}},{"itemId":"f6325662-592b-56fd-9d60-1977b53b603f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3edd6a52-00af-5790-af9b-29fee1061ba0","sourceKey":"bank:AMS101:AMS101-U227","parentItemId":null,"revision":1,"payload":{"prompt":"Management as an art emphasizes:","options":["Scientific methods","Creativity and intuition","Data-driven decisions","None of the above"],"correctOption":1,"section":"Managers and Management","explanation":"Treating management as an art means stressing the personal creativity, intuition and skill a manager brings to applying knowledge in real situations. Options A and C (scientific methods and data-driven decisions) belong to the science side of management."}},{"itemId":"55a63fe7-d5c4-587a-9c25-4b0b162a478c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"81a818d8-bc22-5dfd-8294-aa0046c1fa69","sourceKey":"bank:AMS101:AMS101-U228","parentItemId":null,"revision":1,"payload":{"prompt":"The scientific approach to management focuses on:","options":["Human relations","Experimentation and observation","Subjective analysis","Artistic skills"],"correctOption":1,"section":"Managers and Management","explanation":"A scientific approach builds knowledge through observation and experimentation, as Taylor did when he studied how work was actually done. Option A, human relations, is a different school of thought, and options C and D are subjective and artistic, not scientific."}},{"itemId":"0d55d4e1-29a5-5ef5-a4b9-de3daff955dd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d8098d6e-e390-5a9b-affc-4540c53fa144","sourceKey":"bank:AMS101:AMS101-U229","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic aspect of management requires:","options":["Technical skills","Experience and creativity","Statistical analysis","None of the above"],"correctOption":1,"section":"Managers and Management","explanation":"The art of management is the skillful application of knowledge, which grows through experience and calls for creativity. Option A, technical skills, and option C, statistical analysis, are tools linked more to the science side, so they do not capture what the art requires."}},{"itemId":"5f0901c2-f7b1-5cfd-ace4-8fa197e811ac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"354c11ea-5150-579e-b587-567b3223165a","sourceKey":"bank:AMS101:AMS101-U230","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following supports the idea of management being a science?","options":["Use of case studies","Universal principles","Individual skills","Innovative thinking"],"correctOption":1,"section":"Managers and Management","explanation":"A science rests on general principles that hold across many situations, and management has principles, such as Fayol's, that apply to all kinds of organizations. Options C and D (individual skills and innovative thinking) point to the art of management, while option A, case studies, is a teaching method rather than proof of science."}},{"itemId":"7c8a542a-0149-59f0-ae1f-837ab245dee4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c8c854a-ddf5-58cd-9ed3-43aa09658df9","sourceKey":"bank:AMS101:AMS101-U231","parentItemId":null,"revision":1,"payload":{"prompt":"Management as an art involves the ability to:","options":["Apply scientific theories","Make creative decisions","Follow rigid rules","Focus on technicalities"],"correctOption":1,"section":"Managers and Management","explanation":"As an art, management is about using personal skill and judgment to make creative decisions that fit each situation. Option A, applying scientific theories, belongs to the science side, and options C and D describe rigid, technical work rather than art."}},{"itemId":"54cadb82-b4c0-5009-8013-87eac70329cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e6b70cc5-5d06-5b7b-b8f0-9fd7bf1b804c","sourceKey":"bank:AMS101:AMS101-U233","parentItemId":null,"revision":1,"payload":{"prompt":"A scientific approach to management seeks to:","options":["Eliminate personal bias","Enhance flexibility","Ignore rules","Encourage subjective opinions"],"correctOption":0,"section":"Managers and Management","explanation":"The scientific approach relies on observation, measurement and facts instead of guesswork, so it tries to remove personal bias from decisions. Options C and D are the opposite of science, and option B, flexibility, is more a feature of the art of management."}},{"itemId":"8ca1142c-1e9d-5f97-b172-1e6568c32830","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a4598ae-9b54-5122-bc4c-94c06870c3ea","sourceKey":"bank:AMS101:AMS101-U234","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of management as a science?","options":["Employee motivation techniques","Decision-making based on data","Leadership style application","Conflict resolution methods"],"correctOption":1,"section":"Managers and Management","explanation":"Making decisions from data is a scientific practice because it depends on facts, measurement and analysis. Options A, C and D (motivation techniques, leadership style and conflict resolution) depend heavily on personal skill and judgment, so they show the art of management."}},{"itemId":"9f944ffa-b3f8-5170-8fe3-389960f745c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ec3c3f11-c9c0-5eb9-a51b-bfcc574f139f","sourceKey":"bank:AMS101:AMS101-U235","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic side of management allows managers to:","options":["Apply their experience","Follow standard rules","Use only technical knowledge","Avoid decision-making"],"correctOption":0,"section":"Managers and Management","explanation":"The art of management lets managers apply their personal experience and skill to the situation in front of them. Option B, following standard rules, and option C, using only technical knowledge, describe the science side, while option D is not part of management at all."}},{"itemId":"7472c96f-36eb-5717-8188-d560cc015ddb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1bbe04ad-19ed-56d1-8a00-09746e67353c","sourceKey":"bank:AMS101:AMS101-U236","parentItemId":null,"revision":1,"payload":{"prompt":"In which way is management NOT a science?","options":["It involves human behavior","It is based on universal truths","It follows fixed formulas","It lacks experimentation"],"correctOption":0,"section":"Managers and Management","explanation":"Management is not an exact science because it deals with people, and human behavior cannot be predicted or controlled as precisely as things in physics or chemistry. Option D is tempting, but management does use observation and experiments, such as Taylor's studies and the Hawthorne Studies, so lacking experimentation is not the real reason; options B and C are not true of management."}},{"itemId":"f8afa9cf-2efe-564d-aea8-5f3d71e5a44c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7e214df4-9816-56ee-9927-d2b41eb8dd98","sourceKey":"bank:AMS101:AMS101-U237","parentItemId":null,"revision":1,"payload":{"prompt":"One of the key elements of management as an art is:","options":["Personal judgment","Rigid procedures","Objective analysis","Quantitative data"],"correctOption":0,"section":"Managers and Management","explanation":"Art is about skill in application, and that depends on a manager's personal judgment in each situation. Options B, C and D (rigid procedures, objective analysis and quantitative data) belong to the scientific side of management."}},{"itemId":"52433fdc-6796-5864-9551-b7724bbcfea1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd8e08db-d11b-5668-8247-db2d1d758714","sourceKey":"bank:AMS101:AMS101-U238","parentItemId":null,"revision":1,"payload":{"prompt":"The scientific nature of management means it can be:","options":["Measured and tested","Purely creative","Emotionally driven","Based on instinct"],"correctOption":0,"section":"Managers and Management","explanation":"Calling management a science means its principles and methods can be observed, measured and tested. Options B, C and D (pure creativity, emotion and instinct) are not scientific, so they cannot describe the science side."}},{"itemId":"9b7d8a1b-f88e-50ef-bb81-1d4497881402","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03e01c49-3f4d-5f84-b380-f37fb9bb4e71","sourceKey":"bank:AMS101:AMS101-U239","parentItemId":null,"revision":1,"payload":{"prompt":"Which management approach focuses on facts and figures?","options":["Art","Science","Psychology","Sociology"],"correctOption":1,"section":"Managers and Management","explanation":"Facts and figures are the basis of science, so the scientific approach to management relies on data, measurement and analysis. Option A, art, relies more on creativity and personal judgment, while options C and D are separate fields of study."}},{"itemId":"5672db6e-b67c-5148-9511-4983c71e68ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb115686-4136-5a0c-87be-a4a704341095","sourceKey":"bank:AMS101:AMS101-U240","parentItemId":null,"revision":1,"payload":{"prompt":"Which characteristic aligns with management as an art?","options":["Precision","Creativity","Accuracy","Predictability"],"correctOption":1,"section":"Managers and Management","explanation":"Creativity is the hallmark of the art of management, because each manager applies knowledge in his or her own original way. Options A, C and D (precision, accuracy and predictability) are qualities linked to science."}},{"itemId":"f30a2bf6-b305-57c1-9e69-7d1e48b94a61","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d472cfff-b238-5bb6-b22f-3a4197b9054f","sourceKey":"bank:AMS101:AMS101-U241","parentItemId":null,"revision":1,"payload":{"prompt":"Scientific management principles are mostly concerned with:","options":["Efficiency and productivity","Employee emotions","Leadership styles","Innovation and creativity"],"correctOption":0,"section":"Managers and Management","explanation":"Scientific management, developed by Taylor, aimed to find the one best way to do each job so that workers became more efficient and productive. Option B, employee emotions, was the concern of the later human relations movement, and options C and D were not its focus."}},{"itemId":"e8922949-89df-51bf-a74e-05dab6aca0de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b85d566-3a3e-5b1c-839a-3038af779a17","sourceKey":"bank:AMS101:AMS101-U242","parentItemId":null,"revision":1,"payload":{"prompt":"The statement \"Management is an art of getting things done\" implies:","options":["It follows exact science","It requires human skills","It lacks creativity","It is based on formulas"],"correctOption":1,"section":"Managers and Management","explanation":"Getting things done through other people takes human skills such as communicating, motivating and leading, which is why management is called an art. Options A and D describe exact, formula-based science, and option C is wrong because art involves creativity."}},{"itemId":"eeaecca7-fb6a-51d6-99b4-ddfcd3fac90e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f60ac0c-f00b-5072-a491-7a34ec8dbde9","sourceKey":"bank:AMS101:AMS101-U243","parentItemId":null,"revision":1,"payload":{"prompt":"A key feature of management as an art is:","options":["Data-driven decisions","Continuous practice","Strict adherence to rules","Experimentation"],"correctOption":1,"section":"Managers and Management","explanation":"An art is perfected through constant practice, so a manager's skill keeps improving the more he or she applies it. Options A and D (data-driven decisions and experimentation) are features of science, and option C, strict adherence to rules, goes against the creative nature of art."}},{"itemId":"914f80f1-4924-5d8a-9162-fbdf4ae18518","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f173a87-afa9-55a7-921e-456ed32890b4","sourceKey":"bank:AMS101:AMS101-U244","parentItemId":null,"revision":1,"payload":{"prompt":"The primary goal of management as a science is to:","options":["Achieve consistency","Encourage flexibility","Foster intuition","Promote creativity"],"correctOption":0,"section":"Managers and Management","explanation":"Science aims to discover principles that produce similar results whenever they are applied, so management as a science seeks consistency and predictability. Options B, C and D (flexibility, intuition and creativity) are goals linked to the art of management."}},{"itemId":"cd530e8d-4e3d-57a6-a5ec-2e494550b02e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05ef9f53-4c3b-5e3d-b3d6-7147d64ecb8c","sourceKey":"bank:AMS101:AMS101-U245","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best explains the dual nature of management?","options":["It is both subjective and objective","It depends only on intuition","It focuses solely on planning","It ignores human elements"],"correctOption":0,"section":"Managers and Management","explanation":"Management is both objective, because it uses systematic principles and facts, and subjective, because applying them depends on personal judgment and creativity. Option B covers only one side, option C narrows management to one function, and option D ignores the people management works through."}},{"itemId":"d5481cbc-07d9-5a15-98af-7a8629df305d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fed387c9-6010-5353-ab77-785e11d37c2e","sourceKey":"bank:AMS101:AMS101-U246","parentItemId":null,"revision":1,"payload":{"prompt":"Management involves science because it:","options":["Uses systematic knowledge","Depends on emotions","Is purely an art","Lacks principles"],"correctOption":0,"section":"Managers and Management","explanation":"Management counts as a science because it has a systematic, organized body of knowledge and principles. Option B, emotions, is not scientific, option C contradicts the question, and option D is false because management has well-known principles."}},{"itemId":"3b7f1640-e73d-5c2c-aa88-a22338ba59fd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1dcf8904-94c8-524e-a4cd-934713c6a50f","sourceKey":"bank:AMS101:AMS101-U247","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a scientific management technique?","options":["Brainstorming","Time and motion study","Inspirational leadership","Visionary planning"],"correctOption":1,"section":"Managers and Management","explanation":"Time and motion study was the main tool of Taylor's scientific management, used to measure each part of a job and find the most efficient way to do it. Options A, C and D (brainstorming, inspirational leadership and visionary planning) are creative or leadership practices, not scientific management techniques."}},{"itemId":"d4086517-e48d-5254-8809-5e03e80a646f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bff0a88d-1969-5172-88c9-d8663ff7d2d7","sourceKey":"bank:AMS101:AMS101-U248","parentItemId":null,"revision":1,"payload":{"prompt":"In the artistic aspect of management, success depends on:","options":["Theoretical knowledge","Individual talent","Fixed procedures","Mathematical calculations"],"correctOption":1,"section":"Managers and Management","explanation":"In art, results depend on the personal talent and skill of the person practising it, and the same is true of a manager's artistic side. Options A, C and D (theoretical knowledge, fixed procedures and calculations) belong to the science of management."}},{"itemId":"210465db-d703-5bf2-aec7-35386a1f1c48","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07efb0b9-95f9-52be-bdda-afdaebbedd39","sourceKey":"bank:AMS101:AMS101-U249","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following supports management as an art?","options":["Standardized processes","Leadership qualities","Experimentation","Fixed formulas"],"correctOption":1,"section":"Managers and Management","explanation":"Leadership qualities such as inspiring and motivating people are personal skills that differ from manager to manager, which shows management as an art. Options A, C and D (standardized processes, experimentation and fixed formulas) support the science view."}},{"itemId":"76a6fe3a-6465-56b9-8d0f-cb09c13d3602","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"036894e0-23e4-5253-99ac-5382253e5928","sourceKey":"bank:AMS101:AMS101-U250","parentItemId":null,"revision":1,"payload":{"prompt":"Why is management considered an inexact science?","options":["It deals with human behavior","It has fixed principles","It is formula-based","It ignores creativity"],"correctOption":0,"section":"Managers and Management","explanation":"Management is called an inexact or soft science because it deals with human beings, whose behavior varies and cannot be predicted with full accuracy. Options B and C are wrong because management principles are flexible rather than fixed formulas, and option D is not the reason."}},{"itemId":"ec9c29f5-3169-56f4-9154-39c9097c74f2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db040e7d-1ccd-5f51-b1d1-075b0d0ccc99","sourceKey":"bank:AMS101:AMS101-U251","parentItemId":null,"revision":1,"payload":{"prompt":"Scientific management primarily focuses on:","options":["Employee motivation","Process efficiency","Flexible decision-making","Human behavior"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management focused on making work processes efficient by finding the one best way to do each task. Options A and D (motivation and human behavior) became central later with the behavioral approach, and option C, flexible decision-making, was not Taylor's concern."}},{"itemId":"ef762a53-05aa-5249-aa8a-ee9eafbf1dcb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ecdc5b2c-0fa5-5f33-8deb-2c7f0305f59f","sourceKey":"bank:AMS101:AMS101-U252","parentItemId":null,"revision":1,"payload":{"prompt":"A good manager combines:","options":["Only scientific principles","Both science and art","Pure intuition","Strict methodologies"],"correctOption":1,"section":"Managers and Management","explanation":"A good manager uses scientific principles and knowledge but applies them with creativity and judgment, so he or she combines both science and art. Options A, C and D each take only one side, which leaves the manager incomplete."}},{"itemId":"41c63291-c7fb-5d0d-afec-e6272cc8cf87","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"58bc5246-b1b6-56f1-84fd-cfb699b42fd5","sourceKey":"bank:AMS101:AMS101-U253","parentItemId":null,"revision":1,"payload":{"prompt":"Management as an art requires:","options":["Strict adherence to rules","Creative problem-solving","Mathematical modeling","Scientific experiments"],"correctOption":1,"section":"Managers and Management","explanation":"Art in management shows in creative problem-solving, where the manager finds fitting solutions for each situation. Options A, C and D (strict rules, mathematical models and experiments) describe the science side of management."}},{"itemId":"67515411-8e95-5e55-b0d3-1d58230777bc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a36272ec-dffa-5ff8-9526-d200364da3ec","sourceKey":"bank:AMS101:AMS101-U254","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a scientific management practice?","options":["Trial and error","Data analysis","Observation","Standardized work methods"],"correctOption":0,"section":"Managers and Management","explanation":"Scientific management was developed to replace rule-of-thumb and trial-and-error methods with careful, measured study of each job. Options B, C and D (data analysis, observation and standardized work methods) are all core scientific management practices, used to find and fix the one best way to do a task."}},{"itemId":"cfc1ef82-a5dc-5744-b86e-002d124ae65a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"24698780-726e-5311-ad7a-e19c92ca8574","sourceKey":"bank:AMS101:AMS101-U255","parentItemId":null,"revision":1,"payload":{"prompt":"Scientific management is criticized for being too:","options":["Focused on human behavior","Mechanistic and rigid","Subjective and emotional","Flexible and adaptable"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management is often criticized for treating workers like parts of a machine, making work mechanical and rigid. Option A is wrong because it actually paid too little attention to human behavior, and options C and D describe the opposite of its approach."}},{"itemId":"b0ed5a69-7a08-5a3b-9f17-fff1f19c557c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90dcdbe4-bcad-5c72-bc89-107b0b1aa1e4","sourceKey":"bank:AMS101:AMS101-U256","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic side of management is most important in:","options":["Strategic decision-making","Routine tasks","Process optimization","Financial analysis"],"correctOption":0,"section":"Managers and Management","explanation":"Strategic decisions deal with new, unclear and non-routine situations, so they depend most on a manager's judgment, vision and creativity. Options B, C and D (routine tasks, process optimization and financial analysis) can be handled with standard procedures and data."}},{"itemId":"c314f1ab-6b23-520a-afb0-54595a307f1b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c00ff57-c994-5f83-8db7-a3a6fd90f912","sourceKey":"bank:AMS101:AMS101-U257","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an essential skill for the art of management?","options":["Data analysis","Innovation","Experimentation","Automation"],"correctOption":1,"section":"Managers and Management","explanation":"Innovation, coming up with new ideas and fresh ways of doing things, is a creative skill and so belongs to the art of management. Options A, C and D (data analysis, experimentation and automation) are linked to the scientific and technical side."}},{"itemId":"66da572e-09c7-50da-85b4-8c30bc614bd8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f45b2848-4045-5520-9e05-0325fd384b77","sourceKey":"bank:AMS101:AMS101-U259","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic approach to management focuses on:","options":["Numbers and facts","Intuition and vision","Scientific methods","Data-driven solutions"],"correctOption":1,"section":"Managers and Management","explanation":"The artistic approach relies on a manager's intuition, vision and personal judgment. Options A, C and D (numbers and facts, scientific methods and data-driven solutions) describe the scientific approach."}},{"itemId":"989bf81e-4a8a-5be7-b891-031b1d7ec1f1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df0b3b86-6fa8-5e3c-bd9e-44a09d1aa5a5","sourceKey":"bank:AMS101:AMS101-U260","parentItemId":null,"revision":1,"payload":{"prompt":"Management as a science applies to:","options":["Only experienced managers","Any organization","Only creative industries","Small businesses only"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific principles of management are universal, meaning they can be applied in any type and size of organization. Options A, C and D wrongly limit the principles to certain managers, industries or business sizes."}},{"itemId":"fc829f99-0d4b-556a-8982-3fada8f4c4a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c5767ef6-ecad-5b83-b133-d211d49c5068","sourceKey":"bank:AMS101:AMS101-U261","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic side of management helps managers:","options":["Develop unique solutions","Follow strict methods","Use standard formulas","Avoid risks"],"correctOption":0,"section":"Managers and Management","explanation":"Because art depends on personal creativity, the artistic side of management helps managers come up with unique solutions to problems. Options B and C (strict methods and standard formulas) describe the science side, and option D is not a purpose of either."}},{"itemId":"f1fffeda-13aa-5934-9cd4-a4933d76209c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05edafb9-b543-5505-80e3-46694a0e526e","sourceKey":"bank:AMS101:AMS101-U262","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements is true?","options":["Management is only an art","Management is only a science","Management is both an art and science","Management is neither art nor science"],"correctOption":2,"section":"Managers and Management","explanation":"Management is both an art and a science: it has a systematic body of principles, and applying them well requires skill and creativity. Options A and B each give only half the picture, and option D is wrong because management clearly has features of both."}},{"itemId":"a63e7a95-4069-5e95-8515-2e1986a3cefc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a83d4ca3-b0e8-575a-b232-a581c5512cf2","sourceKey":"bank:AMS101:AMS101-U263","parentItemId":null,"revision":1,"payload":{"prompt":"One of the limitations of scientific management is:","options":["It relies too much on intuition","It ignores human aspects","It is too creative","It lacks structure"],"correctOption":1,"section":"Managers and Management","explanation":"A major criticism of scientific management is that it focused on efficiency and treated workers like machines, ignoring their social and human needs. Options A, C and D are wrong because scientific management was highly structured and not based on intuition or creativity."}},{"itemId":"8eef31c2-9d51-56d2-b3f5-16eb685507d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"31a65062-8daa-57b8-b7ef-56efd32a693a","sourceKey":"bank:AMS101:AMS101-U264","parentItemId":null,"revision":1,"payload":{"prompt":"The art of management is mainly concerned with:","options":["Creativity and personal skills","Technical efficiency","Numerical analysis","Formal procedures"],"correctOption":0,"section":"Managers and Management","explanation":"The art of management is mainly about creativity and the personal skill with which a manager applies knowledge. Options B, C and D (technical efficiency, numerical analysis and formal procedures) belong to the science side."}},{"itemId":"eba4b9c0-3873-53d9-932e-e1312bb1e2f1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f13de16-df7d-5ce4-8f9f-6108ec408328","sourceKey":"bank:AMS101:AMS101-U265","parentItemId":null,"revision":1,"payload":{"prompt":"Management as a science ensures:","options":["Flexibility in rules","Predictable outcomes","Emotional connections","Leadership development"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific principles produce similar results when applied under similar conditions, so management as a science aims for predictable outcomes. Options A, C and D (flexibility, emotional connections and leadership development) relate more to the art of management."}},{"itemId":"5cc0cc61-09c9-510e-bd82-31b2f5fd1106","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25192f65-571f-54b8-9a79-60ef9ccbc9bd","sourceKey":"bank:AMS101:AMS101-U266","parentItemId":null,"revision":1,"payload":{"prompt":"Artistic management is most visible in:","options":["Budget planning","Creative problem-solving","Performance metrics","Process automation"],"correctOption":1,"section":"Managers and Management","explanation":"The art of management shows most clearly when a manager solves problems in creative, original ways. Options A, C and D (budget planning, performance metrics and process automation) are mostly technical and data-based, so they reflect the science side."}},{"itemId":"b0c10483-75b5-5fad-9360-a771439e3dc6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65464da7-9c97-551b-80b5-f7baeeb093b2","sourceKey":"bank:AMS101:AMS101-U267","parentItemId":null,"revision":1,"payload":{"prompt":"Who among the following emphasized the artistic side of management?","options":["Max Weber","Henry Mintzberg","Frederick Taylor","Elton Mayo"],"correctOption":1,"section":"Managers and Management","explanation":"Henry Mintzberg studied what managers actually do and argued that management is a practice built on art, craft and experience rather than pure science. Option C, Frederick Taylor, stressed the scientific side, option A, Max Weber, described bureaucracy, and option D, Elton Mayo, is linked to human relations."}},{"itemId":"a20be1d9-0d54-50f6-b3cd-5a50857d618d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d227002-ecb3-5b1d-9244-5aae085f75ee","sourceKey":"bank:AMS101:AMS101-U268","parentItemId":null,"revision":1,"payload":{"prompt":"Scientific management emphasizes:","options":["Worker satisfaction","Process standardization","Leadership intuition","Team dynamics"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management stressed standardizing work, meaning tools, methods and tasks were set in the one best way for everyone to follow. Options A and D (worker satisfaction and team dynamics) were later behavioral concerns, and option C, intuition, is the opposite of a scientific approach."}},{"itemId":"9fda0f0d-738a-5c64-a2d9-7590fe1640a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"82506316-3f4a-5221-8611-145a74ffca1d","sourceKey":"bank:AMS101:AMS101-U269","parentItemId":null,"revision":1,"payload":{"prompt":"Management is considered an art when it involves:","options":["Analysis","Creativity","Rules","Experiments"],"correctOption":1,"section":"Managers and Management","explanation":"Management is seen as an art when a manager uses creativity and personal skill to handle situations. Options A, C and D (analysis, rules and experiments) are features of science."}},{"itemId":"dac8d91f-8927-5e92-b714-159e7c7f2407","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f73e7ead-9c71-549e-b74e-0db920d07764","sourceKey":"bank:AMS101:AMS101-U270","parentItemId":null,"revision":1,"payload":{"prompt":"Scientific management deals with:","options":["Human psychology","Data and statistics","Subjective opinions","Personal experience"],"correctOption":1,"section":"Managers and Management","explanation":"Scientific management relies on measurement, data and statistics, such as timing tasks and recording output, to decide the best way of working. Options A, C and D (human psychology, subjective opinions and personal experience) are not its basis."}},{"itemId":"ace697b3-5f84-5456-86a6-6e1c86311ffa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7024522b-dbc2-5906-a6c9-048672590237","sourceKey":"bank:AMS101:AMS101-U271","parentItemId":null,"revision":1,"payload":{"prompt":"Management as a science helps in:","options":["Systematic planning","Flexible leadership","Creativity enhancement","Team bonding"],"correctOption":0,"section":"Managers and Management","explanation":"Because science provides an organized body of principles and methods, it helps managers plan in a systematic, orderly way. Options B, C and D (flexible leadership, creativity and team bonding) are linked to the art side of management."}},{"itemId":"398b81e1-3439-560f-94ec-f5f5c2fa0f8f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03a70682-9f31-5b3e-bc6d-d53ae711dd40","sourceKey":"bank:AMS101:AMS101-U272","parentItemId":null,"revision":1,"payload":{"prompt":"The artistic approach in management is effective in:","options":["Decision-making","Data analysis","Process improvement","Task automation"],"correctOption":0,"section":"Managers and Management","explanation":"Decision-making, especially in new or unclear situations, depends a lot on judgment and intuition, which is where the art of management is most useful. Options B, C and D (data analysis, process improvement and task automation) depend mainly on scientific and technical methods."}},{"itemId":"70696617-0e4d-56cb-ade0-2449e6bb53a7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"663c59e4-cd28-54c9-adf0-11dc2b327f59","sourceKey":"bank:AMS101:AMS101-U273","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following highlights the artistic side of management?","options":["Budget forecasting","Conflict resolution","Financial analysis","Quality control"],"correctOption":1,"section":"Managers and Management","explanation":"Resolving conflict requires people skills such as tact, listening and judgment, which differ from manager to manager, so it shows the artistic side of management. Options A, C and D (forecasting, financial analysis and quality control) are technical and data-based."}},{"itemId":"02995c1b-4a74-5ab3-95db-3e215a16999f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d0150d6-ddd8-517f-ac64-d70f7fa8655a","sourceKey":"bank:AMS101:AMS101-U274","parentItemId":null,"revision":1,"payload":{"prompt":"The science of management provides:","options":["Clear guidelines","Flexibility","Innovation","Subjective judgment"],"correctOption":0,"section":"Managers and Management","explanation":"The science of management gives managers clear guidelines in the form of tested principles they can follow. Options B, C and D (flexibility, innovation and subjective judgment) come from the art of management."}},{"itemId":"685f042f-74b0-5dd8-bd58-548b34357e39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f650e5aa-e18f-5629-9458-5dd455514553","sourceKey":"bank:AMS101:AMS101-U276","parentItemId":null,"revision":1,"payload":{"prompt":"Who is primarily responsible for strategic decision-making in an organization?","options":["Middle-level management","Top-level management","Supervisory management","Operational staff"],"correctOption":1,"section":"Managers and Management","explanation":"Top managers, such as the CEO and president, make decisions about the direction of the whole organization, which are strategic decisions. Option A, middle managers, mainly turn those strategies into departmental plans, while options C and D focus on day-to-day work."}},{"itemId":"59fce96d-7838-55f6-8dbe-abf1faff5809","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aeff1b43-f57c-58ad-98f5-58e276c7a026","sourceKey":"bank:AMS101:AMS101-U277","parentItemId":null,"revision":1,"payload":{"prompt":"Which management level acts as a link between top-level and operational-level management?","options":["Middle-level management","Supervisory-level management","Functional-level management","Strategic management"],"correctOption":0,"section":"Managers and Management","explanation":"Middle managers sit between top managers and first-line managers and manage the activities of other managers, so they act as the link between the two. Option B is the lowest managerial level, and options C and D are not names of a linking level."}},{"itemId":"e76ed4eb-38ea-581b-9a33-f5fa8457dcb6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"44c98c17-7528-58a2-a30e-7f05336119c2","sourceKey":"bank:AMS101:AMS101-U278","parentItemId":null,"revision":1,"payload":{"prompt":"Supervisory-level management is also known as:","options":["Operational management","Executive management","Tactical management","Strategic management"],"correctOption":0,"section":"Managers and Management","explanation":"Supervisory management is the first-line or operational level, where managers directly oversee the workers doing the actual tasks. Options B and D refer to top management, and option C, tactical management, refers to middle management."}},{"itemId":"aba067dc-3e31-5742-ada1-257f410a6cb2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d2f4d6c-ccae-5378-84de-624bfb745643","sourceKey":"bank:AMS101:AMS101-U279","parentItemId":null,"revision":1,"payload":{"prompt":"Setting long-term goals and objectives is a primary function of:","options":["Top-level management","Middle-level management","Low-level management","Technical management"],"correctOption":0,"section":"Managers and Management","explanation":"Top managers decide the direction of the organization, which includes setting long-term goals and objectives. Option B, middle management, puts those goals into action, while options C and D handle shorter-term, more specific work."}},{"itemId":"a9e994aa-4be4-5984-a7ce-94b2302190d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1bb75d7f-cb15-5a84-b1a7-1a519d8aa52c","sourceKey":"bank:AMS101:AMS101-U280","parentItemId":null,"revision":1,"payload":{"prompt":"Middle-level managers are mainly responsible for:","options":["Creating strategic plans","Supervising frontline employees","Implementing policies","Setting corporate vision"],"correctOption":2,"section":"Managers and Management","explanation":"Middle managers carry out the policies and plans set by top management by turning them into departmental targets and activities. Options A and D (strategic plans and corporate vision) belong to top management, and option B, supervising frontline employees, is the job of first-line managers."}},{"itemId":"58f5249e-7836-5a2e-b037-dc67a67a128b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f6ba238d-29c7-5b9f-8043-df7fa03d5094","sourceKey":"bank:AMS101:AMS101-U281","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a typical responsibility of top-level management?","options":["Policy formulation","Coordinating departments","Setting company vision","Approving annual budgets"],"correctOption":1,"section":"Managers and Management","explanation":"Coordinating the work of departments is mainly a middle-management job, since middle managers manage other managers and link the levels together. Options A, C and D (policy formulation, setting the vision and approving annual budgets) are typical top-management duties."}},{"itemId":"da88ec3d-c6d7-5bc7-b3b3-278a03033795","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fe9b7fa6-9076-505b-bded-12cbd6e2e8a8","sourceKey":"bank:AMS101:AMS101-U282","parentItemId":null,"revision":1,"payload":{"prompt":"The role of first-line supervisors includes:","options":["Setting corporate goals","Monitoring daily operations","Developing strategic plans","Making investment decisions"],"correctOption":1,"section":"Managers and Management","explanation":"First-line supervisors direct nonmanagerial employees, so their job centers on watching and guiding daily operations. Options A, C and D (corporate goals, strategic plans and investment decisions) belong to top management."}},{"itemId":"f7ed1084-4e0f-52b7-9fad-fea18bd637e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"209d3831-010b-5f8e-bc6c-352681992092","sourceKey":"bank:AMS101:AMS101-U283","parentItemId":null,"revision":1,"payload":{"prompt":"Middle-level management includes which of the following roles?","options":["CEO","Supervisors","Department heads","Board of directors"],"correctOption":2,"section":"Managers and Management","explanation":"Department heads manage other managers and run a part of the organization, which places them at the middle level. Options A and D (CEO and board of directors) are top management, and option B, supervisors, is first-line management."}},{"itemId":"efa92dd5-3161-50e5-b209-16477a1858d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f0b1ea5c-fd94-512f-a6c0-dd3e3c0ad5ad","sourceKey":"bank:AMS101:AMS101-U284","parentItemId":null,"revision":1,"payload":{"prompt":"The top-level management is primarily concerned with:","options":["Tactical planning","Strategic planning","Operational planning","Project management"],"correctOption":1,"section":"Managers and Management","explanation":"Top management focuses on strategic planning, which covers the whole organization and its long-term direction. Option A, tactical planning, is mainly for middle managers, and option C, operational planning, is for lower-level managers."}},{"itemId":"4a4746b9-94a6-5f35-88ff-d7e7dbb9aab0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89f6f30e-ca02-5dbd-b292-0f764c593f75","sourceKey":"bank:AMS101:AMS101-U285","parentItemId":null,"revision":1,"payload":{"prompt":"Who is directly responsible for guiding and supervising workers?","options":["Top-level management","Middle-level management","Lower-level management","Shareholders"],"correctOption":2,"section":"Managers and Management","explanation":"Lower-level or first-line managers directly guide and supervise the nonmanagerial workers who do the actual tasks. Options A and B work through other managers, and option D, shareholders, own the company but do not supervise workers."}},{"itemId":"0618f8c2-2a13-51a2-aeda-e6432e52aaca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c4c61aa7-1c45-59c6-a2a6-a604830ecfe0","sourceKey":"bank:AMS101:AMS101-U286","parentItemId":null,"revision":1,"payload":{"prompt":"Which level of management implements policies and procedures set by higher authorities?","options":["Supervisory management","Middle-level management","Top-level management","Strategic management"],"correctOption":1,"section":"Managers and Management","explanation":"Middle-level managers take the policies and procedures set by top management and put them into action across their departments. Option A, supervisory management, is also involved, but it mainly directs workers on daily tasks, so B is the better answer; options C and D set policies rather than implement them."}},{"itemId":"c67f67c7-22c4-51fa-b9ab-206ef9a8772c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8666d63-056f-5276-8b33-c4e340097fc9","sourceKey":"bank:AMS101:AMS101-U287","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making at the operational level is usually:","options":["Strategic","Tactical","Routine","Complex"],"correctOption":2,"section":"Managers and Management","explanation":"At the operational level, managers face structured, repetitive problems, so their decisions are usually routine or programmed. Options A and D describe top-level, nonprogrammed decisions, and option B, tactical, describes middle-level decisions."}},{"itemId":"1eb61d0b-fa08-5c62-9182-5dce43084277","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83c6794b-6941-5b88-aa87-a9fd6e1f9958","sourceKey":"bank:AMS101:AMS101-U288","parentItemId":null,"revision":1,"payload":{"prompt":"Which management level requires strong conceptual skills?","options":["Top-level management","Middle-level management","Supervisory-level management","Operational staff"],"correctOption":0,"section":"Managers and Management","explanation":"Conceptual skills are used to analyze and diagnose complex situations and see the organization as a whole, which top managers need most. Options B and C use these skills less, and option D, operational staff, are not managers."}},{"itemId":"48225f89-75ea-580c-b538-0783aafb7ae5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca4b911d-652e-57a2-b51f-1a9e150d12ce","sourceKey":"bank:AMS101:AMS101-U289","parentItemId":null,"revision":1,"payload":{"prompt":"Frontline supervisors focus primarily on:","options":["Employee motivation","Corporate strategy","Market expansion","Financial investment"],"correctOption":0,"section":"Managers and Management","explanation":"Frontline supervisors work directly with employees every day, so keeping workers motivated and productive is central to their role. Options B, C and D (corporate strategy, market expansion and financial investment) are concerns of top management."}},{"itemId":"a62e919d-2d94-5c9d-ab20-9f50c7988a1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cde7832f-0fb8-5d3e-ac6a-d4d624f8fc19","sourceKey":"bank:AMS101:AMS101-U290","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following functions is typically handled by middle management?","options":["Developing corporate policies","Managing day-to-day operations","Interpreting top management directives","Handling shareholder relations"],"correctOption":2,"section":"Managers and Management","explanation":"Middle managers interpret the directives and plans of top management and turn them into specific actions for their units. Options A and D are top-management tasks, and option B, managing day-to-day operations, is mainly done by first-line managers."}},{"itemId":"d3be5ab4-9629-5f96-8d08-e94f1dff7e60","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"56cff4d6-2113-56a4-b57d-93481f3848e4","sourceKey":"bank:AMS101:AMS101-U291","parentItemId":null,"revision":1,"payload":{"prompt":"The Board of Directors falls under which level of management?","options":["Middle-level","Lower-level","Top-level","Operational-level"],"correctOption":2,"section":"Managers and Management","explanation":"The board of directors sits at the very top of the organization and sets its overall direction and policies, so it is part of top-level management. Options A, B and D are lower levels that carry out those decisions."}},{"itemId":"d0a74341-483c-5c43-a8bf-dd319ecca386","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4d4bb4b-8782-5ada-942e-134eec428c43","sourceKey":"bank:AMS101:AMS101-U292","parentItemId":null,"revision":1,"payload":{"prompt":"Lower-level management primarily focuses on:","options":["Policy creation","Employee performance","Business expansion","Market research"],"correctOption":1,"section":"Managers and Management","explanation":"Lower-level managers direct the people doing the work, so their focus is on how well employees perform their daily tasks. Options A, C and D (policy creation, business expansion and market research) are concerns of higher levels."}},{"itemId":"c394effa-e7b8-51ff-bb94-aeb30a2822f8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d6cddb2b-2168-56d1-995a-84d65eff7646","sourceKey":"bank:AMS101:AMS101-U293","parentItemId":null,"revision":1,"payload":{"prompt":"Coordinating departmental activities is mainly the responsibility of:","options":["Top management","Middle management","Supervisory management","External consultants"],"correctOption":1,"section":"Managers and Management","explanation":"Middle managers manage other managers and connect different units, so coordinating departmental activities is mainly their job. Option A, top management, sets overall direction, and option C, supervisory management, focuses on workers within one unit."}},{"itemId":"18e6b9ce-14e3-54bc-a7cb-2364af7dd38e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bfa915d1-571f-5585-9018-e44c09be8304","sourceKey":"bank:AMS101:AMS101-U294","parentItemId":null,"revision":1,"payload":{"prompt":"Supervisory management plays a major role in:","options":["Strategic planning","Employee training","Policy formulation","Corporate governance"],"correctOption":1,"section":"Managers and Management","explanation":"Supervisors work closely with workers and are responsible for showing them how to do their jobs, so training employees is a big part of their role. Options A, C and D (strategic planning, policy formulation and corporate governance) are top-management concerns."}},{"itemId":"4995224d-0d81-5e67-bf69-487695aa8763","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39881ea1-3954-5626-8c21-1a31c4564a83","sourceKey":"bank:AMS101:AMS101-U295","parentItemId":null,"revision":1,"payload":{"prompt":"The highest level of management is often referred to as:","options":["Tactical management","Functional management","Strategic management","Operational management"],"correctOption":2,"section":"Managers and Management","explanation":"Top management is called strategic management because it makes the decisions about the direction of the whole organization. Option A, tactical, refers to middle management, and option D, operational, refers to lower-level management."}},{"itemId":"649f18f9-038b-5ebd-9137-654a40c3f795","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c2ef6217-e3f2-509d-88b3-4159cca681a7","sourceKey":"bank:AMS101:AMS101-U296","parentItemId":null,"revision":1,"payload":{"prompt":"Supervisors usually report to:","options":["Top management","Middle management","Shareholders","External stakeholders"],"correctOption":1,"section":"Managers and Management","explanation":"In the management hierarchy, first-line supervisors report upward to middle managers, who manage the activities of other managers. Option A, top management, is usually above the middle level, and options C and D are not part of the internal chain of command."}},{"itemId":"57844b87-5068-5f0c-8890-510a3ceea6f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a988d8d-0caf-5251-9c91-fa4e8498fd34","sourceKey":"bank:AMS101:AMS101-U297","parentItemId":null,"revision":1,"payload":{"prompt":"Which level of management is most involved in decision-making related to the company's vision and mission?","options":["Top-level","Middle-level","Lower-level","Supervisory-level"],"correctOption":0,"section":"Managers and Management","explanation":"Top managers decide the direction of the organization, which includes shaping its vision and mission. Options B, C and D (middle, lower and supervisory levels) work to carry out that vision rather than set it."}},{"itemId":"de70c3ad-f8ce-54ee-bac4-ea34ffcb23af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51faba47-4b16-5841-af6a-4cbc4a044a15","sourceKey":"bank:AMS101:AMS101-U298","parentItemId":null,"revision":1,"payload":{"prompt":"Functional managers typically belong to which management level?","options":["Top management","Middle management","Operational management","Supervisory management"],"correctOption":1,"section":"Managers and Management","explanation":"Functional managers, such as the head of marketing or finance, run one functional department and manage the managers or staff under them, so they usually sit at the middle level. Option A is for organization-wide leaders, while options C and D are first-line levels."}},{"itemId":"aa9e7934-29d6-578b-9936-c6dae8332e65","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"272b62bb-1562-51f4-a7d8-6cd29de1704c","sourceKey":"bank:AMS101:AMS101-U299","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common role of top-level managers?","options":["Assigning tasks to workers","Formulating long-term strategies","Preparing daily reports","Conducting employee training"],"correctOption":1,"section":"Managers and Management","explanation":"Top-level managers make decisions about the organization's direction, which includes formulating long-term strategies. Options A, C and D (assigning tasks, daily reports and employee training) are typical of lower-level managers."}},{"itemId":"7109c84f-6ee0-5dcc-afdf-b1bc08e3aa52","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a8cc7f20-848b-54f1-8c63-fcc7ebaff3ee","sourceKey":"bank:AMS101:AMS101-U300","parentItemId":null,"revision":1,"payload":{"prompt":"Which skill is most important for lower-level managers?","options":["Conceptual skills","Technical skills","Strategic thinking","Financial analysis"],"correctOption":1,"section":"Managers and Management","explanation":"Technical skills, the job-specific knowledge needed to perform tasks, matter most for lower-level managers because they directly oversee the work. Options A and C (conceptual skills and strategic thinking) matter most at the top level, and option D is a specialist skill, not the key one."}},{"itemId":"06adad25-a145-52fb-95f3-e7fdc4d517fa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9352591-9567-567a-9534-8baec31ff583","sourceKey":"bank:AMS101:AMS101-U301","parentItemId":null,"revision":1,"payload":{"prompt":"Day-to-day administration of company policies is done by:","options":["Top management","Middle management","Operational management","External auditors"],"correctOption":2,"section":"Managers and Management","explanation":"Operational or first-line managers handle the day-to-day running of activities, so they apply company policies in daily work. Option A, top management, makes the policies, and option B, middle management, translates them into departmental plans."}},{"itemId":"50f63f49-3dc9-56f9-9746-78c785f47b25","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8291c945-ee4d-52e0-be70-46ef4dbef0b7","sourceKey":"bank:AMS101:AMS101-U302","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making that affects the entire organization is typically done at which level?","options":["Top management","Middle management","Supervisory management","Functional management"],"correctOption":0,"section":"Managers and Management","explanation":"Top managers make decisions about the direction of the whole organization, so decisions that affect everyone are taken at that level. Options B, C and D (middle, supervisory and functional managers) make decisions for their own units."}},{"itemId":"f8eb54f9-cb92-512a-bccb-67f723b7c6ee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a8a7787-d4ff-5d6a-b13d-bf79742f794b","sourceKey":"bank:AMS101:AMS101-U303","parentItemId":null,"revision":1,"payload":{"prompt":"First-line supervisors mainly focus on:","options":["Ensuring employee efficiency","Strategic decision-making","Developing business policies","Setting corporate objectives"],"correctOption":0,"section":"Managers and Management","explanation":"First-line supervisors direct nonmanagerial employees and make sure the work is done efficiently day to day. Options B, C and D (strategic decisions, business policies and corporate objectives) belong to top management."}},{"itemId":"09769437-d7a3-5035-a744-97e8b67b1df8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2cf399cd-71c6-56cc-aca9-3b5e559b64e6","sourceKey":"bank:AMS101:AMS101-U304","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about middle management is true?","options":["They focus on long-term planning","They act as a bridge between top and lower management","They set the organization's vision","They perform routine tasks"],"correctOption":1,"section":"Managers and Management","explanation":"Middle managers sit between top and lower management and pass plans down and information up, acting as a bridge. Options A and C (long-term planning and setting the vision) describe top management, and option D, routine tasks, fits lower levels."}},{"itemId":"2ed67803-3474-5e83-9d57-9c19227d067c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0269d036-939a-5cff-bf9f-282c992973fe","sourceKey":"bank:AMS101:AMS101-U306","parentItemId":null,"revision":1,"payload":{"prompt":"Which function of management is concerned with grouping tasks and allocating resources?","options":["Organizing","Leading","Planning","Staffing"],"correctOption":0,"section":"Managers and Management","explanation":"Organizing is arranging and structuring work, which includes grouping tasks and allocating resources to them. Option C, planning, decides what should be done, and option B, leading, is about directing people."}},{"itemId":"7b00d9ed-2ca5-52db-8340-e0c2e4d55844","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85ad65c6-529c-59e0-ae79-5632e8278ea1","sourceKey":"bank:AMS101:AMS101-U307","parentItemId":null,"revision":1,"payload":{"prompt":"Directing as a management function primarily involves:","options":["Budgeting","Motivating employees","Resource allocation","Goal setting"],"correctOption":1,"section":"Managers and Management","explanation":"Directing, also called leading, is about guiding and influencing people, and motivating employees is at its core. Options A, C and D (budgeting, resource allocation and goal setting) belong to planning and organizing."}},{"itemId":"d2fb801a-5fe9-5ce7-9b82-e5731391e8a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6698ead5-a11b-564c-a961-5e9cd4c3137a","sourceKey":"bank:AMS101:AMS101-U308","parentItemId":null,"revision":1,"payload":{"prompt":"The process of measuring performance and taking corrective action is called:","options":["Planning","Controlling","Organizing","Coordinating"],"correctOption":1,"section":"Managers and Management","explanation":"Controlling is the process of monitoring, comparing and correcting work performance, so it measures results and takes corrective action. Option A, planning, sets goals, and option C, organizing, structures the work."}},{"itemId":"6b6260b0-1bb8-5d47-b637-7f8007890a4d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bff26bca-10f4-5a2e-a6e4-5b46b533412d","sourceKey":"bank:AMS101:AMS101-U309","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an essential element of the planning function?","options":["Setting objectives","Motivating employees","Staffing","Supervising"],"correctOption":0,"section":"Managers and Management","explanation":"Planning starts by setting objectives and then working out how to reach them. Option B, motivating, belongs to directing, option C, staffing, is a separate function, and option D, supervising, is part of directing."}},{"itemId":"370bf06e-9e13-5248-a354-76ada169531a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"339e754a-1f03-5df8-98ea-a8f795612be0","sourceKey":"bank:AMS101:AMS101-U310","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary goal of organizing in management?","options":["Increasing control","Enhancing teamwork","Structuring work","Setting targets"],"correctOption":2,"section":"Managers and Management","explanation":"Organizing means arranging and structuring work so the organization can reach its goals. Option D, setting targets, is planning, option A, control, is the job of controlling, and option B, teamwork, is a possible result rather than the main goal."}},{"itemId":"4ae1cfa8-f07d-55dc-a7bd-285ecff7f8fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a9663bb-dfe3-516c-9260-051fdfea3ac3","sourceKey":"bank:AMS101:AMS101-U311","parentItemId":null,"revision":1,"payload":{"prompt":"Delegation of authority is most closely associated with which management function?","options":["Controlling","Organizing","Planning","Directing"],"correctOption":1,"section":"Managers and Management","explanation":"Delegation of authority is part of organizing, because organizing decides who does what and who reports to whom, including how authority is shared. Option D, directing, uses that authority to guide people, but the act of passing authority down belongs to the organization structure."}},{"itemId":"1084ac77-e93d-50a0-8390-5f755eef26e1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"31253dbe-aeef-5480-a819-e943e409f42e","sourceKey":"bank:AMS101:AMS101-U312","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following functions ensures that the organization's objectives are achieved effectively?","options":["Directing","Controlling","Planning","Staffing"],"correctOption":1,"section":"Managers and Management","explanation":"Controlling checks whether work is going according to plan and corrects deviations, which ensures that objectives are actually achieved. Option C, planning, sets the objectives but cannot guarantee they are met, and option A, directing, guides people without measuring results."}},{"itemId":"cdf2ebfb-f50b-5a37-a15b-4ff2abc15187","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4f06ca50-621b-5182-9b7d-d8704f758230","sourceKey":"bank:AMS101:AMS101-U313","parentItemId":null,"revision":1,"payload":{"prompt":"Leadership is primarily a part of which management function?","options":["Staffing","Organizing","Planning","Directing"],"correctOption":3,"section":"Managers and Management","explanation":"Leadership is a central part of directing, also called leading, which involves guiding, motivating and influencing others. Options A, B and C (staffing, organizing and planning) deal with people placement, structure and goals rather than leadership."}},{"itemId":"82001bdd-b3f9-56bf-8888-1cf0b74f7319","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a15b48b-983b-57b3-acb3-82effc5cdbce","sourceKey":"bank:AMS101:AMS101-U314","parentItemId":null,"revision":1,"payload":{"prompt":"Staffing involves:","options":["Hiring the right people","Setting goals","Supervising work","Measuring performance"],"correctOption":0,"section":"Managers and Management","explanation":"Staffing is the function of filling positions with the right people through recruitment, selection, placement and training. Option B, setting goals, is planning, option C, supervising, is directing, and option D, measuring performance, is controlling."}},{"itemId":"15e69000-f928-5530-ae18-93f7ee02380c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf06f02b-380c-5364-97c2-0e85f9012ba9","sourceKey":"bank:AMS101:AMS101-U315","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a component of staffing?","options":["Recruitment","Selection","Budgeting","Training"],"correctOption":2,"section":"Managers and Management","explanation":"Budgeting is a planning and control tool, so it is not part of staffing. Options A, B and D (recruitment, selection and training) are all key parts of the staffing process."}},{"itemId":"8c58d2ec-f125-5074-a8b2-dfeb538760e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ef5bf3d-e03e-5232-9af3-fc529822329c","sourceKey":"bank:AMS101:AMS101-U316","parentItemId":null,"revision":1,"payload":{"prompt":"The process of evaluating performance and ensuring objectives are met falls under:","options":["Controlling","Organizing","Leading","Planning"],"correctOption":0,"section":"Managers and Management","explanation":"Controlling means monitoring, comparing and correcting performance so that goals are met. Option D, planning, sets the goals in the first place, while options B and C structure the work and guide people."}},{"itemId":"32e8cdb9-bf27-56f0-8595-a4a9788684b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"72853c0b-1a6b-5b79-98fc-5e555c295df7","sourceKey":"bank:AMS101:AMS101-U317","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making is most associated with which function of management?","options":["Planning","Directing","Organizing","Staffing"],"correctOption":0,"section":"Managers and Management","explanation":"Planning involves choosing objectives and the best course of action from among alternatives, so decision-making lies at its heart. Decisions are made in all functions, so options B and C are partly true, but planning is the function most associated with decision-making."}},{"itemId":"7ad53d2e-8599-58b2-b01f-d3b987bd11e1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"abbb3321-47ef-5afb-8c6a-54ea27385655","sourceKey":"bank:AMS101:AMS101-U318","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation of employees is a key part of which function?","options":["Controlling","Directing","Organizing","Planning"],"correctOption":1,"section":"Managers and Management","explanation":"Directing, or leading, is about guiding and influencing people, so motivating employees is one of its key parts. Option A, controlling, measures performance, while options C and D deal with structure and goals."}},{"itemId":"172ed9f9-30c9-518e-bac9-af97b37fe999","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9af81506-436f-53c8-be09-09c368d8dc77","sourceKey":"bank:AMS101:AMS101-U319","parentItemId":null,"revision":1,"payload":{"prompt":"A well-structured organizational chart is a result of which function?","options":["Staffing","Planning","Organizing","Controlling"],"correctOption":2,"section":"Managers and Management","explanation":"An organizational chart shows how jobs are grouped and who reports to whom, which is the result of organizing. Option B, planning, decides goals, and option A, staffing, fills the positions that the chart shows."}},{"itemId":"0d802b25-5d11-5bc0-9796-6d86d59655b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"79aa1ea4-3ce2-56a3-8174-993c12d51089","sourceKey":"bank:AMS101:AMS101-U320","parentItemId":null,"revision":1,"payload":{"prompt":"Performance appraisal is a part of which management function?","options":["Planning","Staffing","Controlling","Directing"],"correctOption":1,"section":"Managers and Management","explanation":"Performance appraisal is usually treated as part of staffing, along with recruitment, selection, training and compensation, because it helps develop and manage the workforce. Option C, controlling, is also partly true since appraisal measures performance, but B is the best answer because appraising employees is a standard staffing activity."}},{"itemId":"8e38832b-c055-5d70-a398-53c9b7866931","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"832ab8d6-76c7-5c19-8c28-893abed06001","sourceKey":"bank:AMS101:AMS101-U321","parentItemId":null,"revision":1,"payload":{"prompt":"Which management function involves forecasting future conditions?","options":["Planning","Organizing","Controlling","Directing"],"correctOption":0,"section":"Managers and Management","explanation":"Planning looks ahead, so it involves forecasting future conditions before deciding goals and courses of action. Option C, controlling, compares present results with plans, and options B and D focus on structure and people."}},{"itemId":"8ebaa067-d0a3-5f19-896f-805834f7634b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8e8967fa-b808-5040-9bd9-28dd67709f80","sourceKey":"bank:AMS101:AMS101-U322","parentItemId":null,"revision":1,"payload":{"prompt":"The process of assigning duties and responsibilities to employees is called:","options":["Staffing","Delegation","Directing","Controlling"],"correctOption":1,"section":"Managers and Management","explanation":"Delegation is the process of assigning duties to subordinates and giving them the authority and responsibility to perform them. Option A, staffing, fills jobs with people, and option C, directing, guides people once duties are assigned."}},{"itemId":"969ea8af-41ac-5506-b3c2-1dc1f359d88b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca395643-0f70-51a7-a789-4ea0c2da6c81","sourceKey":"bank:AMS101:AMS101-U323","parentItemId":null,"revision":1,"payload":{"prompt":"The function that involves ensuring all activities are aligned with the organization's objectives is:","options":["Planning","Controlling","Staffing","Leading"],"correctOption":1,"section":"Managers and Management","explanation":"Controlling monitors activities and corrects any deviations, keeping everything in line with the organization's objectives. Option A, planning, sets the objectives, but it does not check whether ongoing activities stay aligned with them."}},{"itemId":"090c8610-0505-531d-b79b-e639308557cf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d3f23a1-9d6d-5b90-bfa9-e18076697bd1","sourceKey":"bank:AMS101:AMS101-U324","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a major component of the directing function?","options":["Motivation","Organization","Goal-setting","Resource allocation"],"correctOption":0,"section":"Managers and Management","explanation":"Motivation is a major part of directing, since directing involves guiding and inspiring people to perform. Options B and D (organization and resource allocation) belong to organizing, and option C, goal-setting, belongs to planning."}},{"itemId":"c929494a-4207-5ade-bbc1-eb8265db74f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6fdb352f-fdac-5de1-9ed6-e1b368ceaa46","sourceKey":"bank:AMS101:AMS101-U326","parentItemId":null,"revision":1,"payload":{"prompt":"Setting a timeline for achieving organizational goals is part of:","options":["Directing","Organizing","Planning","Controlling"],"correctOption":2,"section":"Managers and Management","explanation":"Planning decides what should be done and when, so setting a timeline for achieving goals is part of planning. Option D, controlling, later checks whether the timeline is being met, and options A and B deal with people and structure."}},{"itemId":"2d9c5426-8517-5a1a-b3b9-17de0b8b9fc9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"15ef9037-57b4-5ad1-90c8-3fec93c36bb4","sourceKey":"bank:AMS101:AMS101-U327","parentItemId":null,"revision":1,"payload":{"prompt":"The process of developing and maintaining a workforce is called:","options":["Staffing","Organizing","Planning","Controlling"],"correctOption":0,"section":"Managers and Management","explanation":"Staffing is the function of building and keeping a workforce through recruiting, selecting, training and retaining people. Option B, organizing, creates the job structure, and options C and D set goals and check results."}},{"itemId":"8f006ce2-5baf-5c14-baae-8bf891547387","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a84a4a12-0d7f-5d8c-a4dd-05755ebd33ca","sourceKey":"bank:AMS101:AMS101-U328","parentItemId":null,"revision":1,"payload":{"prompt":"Which management function includes communication as a core activity?","options":["Controlling","Directing","Organizing","Planning"],"correctOption":1,"section":"Managers and Management","explanation":"Directing (also called leading) is the function where a manager guides, motivates and communicates with people so the work gets done, so communication sits at its core. Controlling (A) is about checking performance against standards, while organizing (C) and planning (D) deal with arranging work and setting goals rather than day-to-day communication with staff."}},{"itemId":"43d2da08-2284-5847-a47e-0457c97d8f39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c7cac86a-fc56-5b09-9fac-92cd23cf0edd","sourceKey":"bank:AMS101:AMS101-U329","parentItemId":null,"revision":1,"payload":{"prompt":"Evaluating the impact of decisions made falls under which function?","options":["Planning","Controlling","Directing","Staffing"],"correctOption":1,"section":"Managers and Management","explanation":"Controlling means monitoring results, comparing them with what was intended and correcting where needed, so evaluating the impact of decisions belongs here. Planning (A) happens before action to set goals, directing (C) is about guiding people, and staffing (D) is about filling positions."}},{"itemId":"c4d0021e-3e87-5598-9a71-0a9903f2bbb8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ece242ed-3ca4-53ff-85e3-21e1c89227a9","sourceKey":"bank:AMS101:AMS101-U330","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a characteristic of controlling?","options":["Measuring performance","Taking corrective action","Staffing employees","Comparing actual results to goals"],"correctOption":2,"section":"Managers and Management","explanation":"Staffing employees is about recruiting and placing people, which is a separate activity from controlling. Measuring performance (A), comparing actual results with goals (D) and taking corrective action (B) are exactly the three steps that make up the control process."}},{"itemId":"9ea32164-191c-5a8f-9622-dcae7e932bca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f298f02-7664-5cac-b492-67ca997cfa6f","sourceKey":"bank:AMS101:AMS101-U332","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following ensures that tasks are done correctly and on time?","options":["Directing","Organizing","Controlling","Planning"],"correctOption":2,"section":"Managers and Management","explanation":"Controlling is the function that checks whether work is being done as planned, correctly and on schedule, and corrects any deviation. Directing (A) guides people while they work and organizing (B) arranges the tasks, but neither one is the checking-and-correcting step; planning (D) only sets the targets in advance."}},{"itemId":"1b94d31c-663e-5853-bba6-74b0c499fd4b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30f9c836-83d9-5243-9d56-c364eb7be674","sourceKey":"bank:AMS101:AMS101-U333","parentItemId":null,"revision":1,"payload":{"prompt":"Establishing a mission and vision for the organization is part of which function?","options":["Organizing","Controlling","Planning","Staffing"],"correctOption":2,"section":"Managers and Management","explanation":"Planning starts with defining the organization's purpose, which is why setting the mission and vision is the very first step of strategic planning. Organizing (A) and staffing (D) come after the direction is set, and controlling (B) checks progress against those plans."}},{"itemId":"f2bb3333-679d-59ed-bfd5-ba219dd194ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00423c02-ebc9-57ed-bd1a-8805002d2885","sourceKey":"bank:AMS101:AMS101-U334","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making is primarily concerned with:","options":["Planning","Choosing among alternatives","Organizing","Staffing"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A decision is simply a choice made from two or more alternatives, so decision-making is mainly about choosing among options. Planning (A), organizing (C) and staffing (D) are management functions that all involve decisions, but none of them is what decision-making itself means."}},{"itemId":"877353b1-582e-538d-a8ff-cc2e1f08c87f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce43e1f9-df0c-5870-b078-9534bda15b80","sourceKey":"bank:AMS101:AMS101-U335","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the first step in the decision-making process?","options":["Evaluating alternatives","Identifying the problem","Implementing the decision","Analyzing the situation"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Every decision begins with recognising a problem, meaning a gap between the current situation and the desired one. Analyzing the situation (D) and evaluating alternatives (A) can only happen once you know what problem you are solving, and implementing the decision (C) comes near the end."}},{"itemId":"d3cc7469-5e19-58c4-bc68-63d650b9ab63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"962a6ce4-5f13-5722-abf0-7325559c760a","sourceKey":"bank:AMS101:AMS101-U336","parentItemId":null,"revision":1,"payload":{"prompt":"Rational decision-making involves:","options":["Emotional bias","Logical analysis","Random selection","Intuition only"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Rational decision-making means making consistent, value-maximizing choices through careful, logical analysis of the problem and the alternatives. Emotional bias (A), random selection (C) and relying on intuition only (D) are the opposite of this structured, logical approach."}},{"itemId":"203adeb6-015f-5453-ba95-2131b8a223c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8efdeef6-3e52-5f87-a438-9098ca98616f","sourceKey":"bank:AMS101:AMS101-U337","parentItemId":null,"revision":1,"payload":{"prompt":"A programmed decision is one that:","options":["Is unique","Requires creative thinking","Is routine and repetitive","Cannot be automated"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Programmed decisions are repetitive decisions that can be handled with a routine approach, like reordering stock when it runs low. Being unique (A) and needing creative thinking (B) describe non-programmed decisions, and because programmed decisions are routine they can often be automated, so D is wrong."}},{"itemId":"ec80f8df-ceb4-57f1-89d0-1c0abbb67bb2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"75267e02-c43d-5f0e-a4b5-eedbfe507da5","sourceKey":"bank:AMS101:AMS101-U338","parentItemId":null,"revision":1,"payload":{"prompt":"Non-programmed decisions are usually made in:","options":["Structured environments","Repetitive situations","Unstructured and new situations","Well-defined problems"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Non-programmed decisions are unique, one-off choices that need a custom-made solution, so they arise in new, unstructured situations where information is incomplete. Structured environments (A), repetitive situations (B) and well-defined problems (D) are where routine, programmed decisions are used."}},{"itemId":"5fab41c3-aa28-5b1a-b55f-96ebc5a55da0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"769a1568-2681-5608-9b92-8706191c2743","sourceKey":"bank:AMS101:AMS101-U339","parentItemId":null,"revision":1,"payload":{"prompt":"A decision made under uncertainty means:","options":["The outcome is known","The risk is measurable","The outcome is unpredictable","There are no alternatives"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Under uncertainty the decision maker has neither certainty nor reasonable probability estimates, so the outcome cannot be predicted. A known outcome (A) describes certainty, measurable risk (B) describes a risk situation, and having no alternatives (D) is not what uncertainty means."}},{"itemId":"03a4ae8f-bf3a-565d-b847-a6013558ccdb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ccc5f250-086a-5ddb-ac48-9ecd4c3a89e1","sourceKey":"bank:AMS101:AMS101-U340","parentItemId":null,"revision":1,"payload":{"prompt":"What is an essential characteristic of an effective decision?","options":["Quickness","Costliness","Rationality","Complexity"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"An effective decision is a rational one, based on clear criteria and a logical comparison of alternatives so that it actually solves the problem. Speed (A) can help but a quick decision is not automatically a good one, while high cost (B) and complexity (D) are not qualities to aim for."}},{"itemId":"e748476a-17bf-51fc-9bd9-a8775fa4add2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"869416ff-0ed9-5eb0-92d4-403bb83405d4","sourceKey":"bank:AMS101:AMS101-U342","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making under risk involves:","options":["Known probabilities","Complete uncertainty","No alternatives","No information"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"A risk situation is one where the decision maker can estimate the likelihood of each outcome, meaning the probabilities are known or can be reasonably estimated. Complete uncertainty (B) and having no information (D) describe uncertainty instead, and having no alternatives (C) means there is no real decision to make."}},{"itemId":"06b3efb1-e008-55ed-8314-8e7f0ff37572","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"80df0847-2968-53d2-a78a-1c1da90e3bbe","sourceKey":"bank:AMS101:AMS101-U343","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"bounded rationality\" refers to:","options":["Unlimited cognitive ability","Decision-making with full information","Limited information and resources","Perfect knowledge"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Bounded rationality means people try to be rational but within limits, because their information, time and ability to process it are limited. Unlimited ability (A), full information (B) and perfect knowledge (D) are the assumptions of the pure rational model, which bounded rationality says are unrealistic."}},{"itemId":"3a4aa234-be03-5078-b21e-4bf772f0a662","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ec70e0e3-893a-537b-9dcb-d6804499e882","sourceKey":"bank:AMS101:AMS101-U345","parentItemId":null,"revision":1,"payload":{"prompt":"A strategic decision typically involves:","options":["Routine matters","Long-term objectives","Day-to-day operations","Employee grievances"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Strategic decisions are made by top managers and shape the long-term direction and objectives of the whole organization. Routine matters (A) and day-to-day operations (C) are handled by operational decisions, and employee grievances (D) are usually dealt with by line managers and HR."}},{"itemId":"f8200419-5ebe-5660-afaa-5d50cbb93ebf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"46d6725c-cc52-575c-bbfe-5c4f24d4da08","sourceKey":"bank:AMS101:AMS101-U346","parentItemId":null,"revision":1,"payload":{"prompt":"Tactical decisions are primarily concerned with:","options":["Top management","Medium-term planning","Long-term planning","Overall corporate strategy"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Tactical decisions are made mostly by middle managers to turn the overall strategy into medium-term plans for departments and units. Top management (A), long-term planning (C) and overall corporate strategy (D) all describe strategic decisions instead."}},{"itemId":"92e2b959-af3e-5590-9e6c-b68dc9c780b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cec3e735-fd70-55e6-b713-5fccb4cffe25","sourceKey":"bank:AMS101:AMS101-U347","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a structured problem?","options":["Market expansion","Product failure","Equipment breakdown","Ethical dilemma"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A structured problem is straightforward, familiar and easy to define, and an equipment breakdown is a common problem with a known fix such as repair or replacement. Market expansion (A) and ethical dilemmas (D) are new or ambiguous situations, and a product failure (B) usually needs investigation to find its cause, making these unstructured."}},{"itemId":"e40ce7a8-f70f-50b3-98b3-b49a69928108","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d04aaf99-078c-5f64-8ee1-0cdd5c813f4e","sourceKey":"bank:AMS101:AMS101-U348","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making is closely linked with:","options":["Planning","Leading","Controlling","Budgeting"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Planning is essentially deciding in advance what to do, how and when, so decision-making is most closely tied to it. Decisions are also made when leading (B) and controlling (C), and budgeting (D) is one planning tool, but planning is where choosing among alternatives is most central."}},{"itemId":"755c7619-8d25-5375-b3e7-b7b29dcbd6b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da734259-40eb-5082-9f9a-cf99b53deb17","sourceKey":"bank:AMS101:AMS101-U349","parentItemId":null,"revision":1,"payload":{"prompt":"An example of a heuristic decision-making approach is:","options":["Data analysis","Logical deduction","Rule of thumb","Mathematical modeling"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"A heuristic is a mental shortcut, and a rule of thumb is the classic example because it lets people decide quickly without full analysis. Data analysis (A), logical deduction (B) and mathematical modeling (D) are systematic, analytical methods rather than shortcuts."}},{"itemId":"4ea3febf-f358-5dfa-b217-69d394320a7b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d22c99bd-2acc-5d5d-9c5b-fa838ce08b50","sourceKey":"bank:AMS101:AMS101-U350","parentItemId":null,"revision":1,"payload":{"prompt":"Which decision-making style focuses on collaboration and consensus?","options":["Autocratic","Consultative","Group","Intuitive"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"In group decision-making the members discuss the problem together and work toward a choice everyone can accept, so it is built on collaboration and consensus. A consultative style (B) asks others for input but the leader still makes the final call alone, while autocratic (A) and intuitive (D) styles involve little or no shared decision."}},{"itemId":"e138a480-67b1-5313-90dc-57dc71dd8898","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c58b09af-6895-5384-a8b5-3793a65cb998","sourceKey":"bank:AMS101:AMS101-U351","parentItemId":null,"revision":1,"payload":{"prompt":"A decision tree is a tool used to:","options":["Brainstorm ideas","Evaluate choices systematically","Assign responsibility","Motivate employees"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A decision tree maps out each choice, the possible outcomes and their chances, so a manager can evaluate options systematically. Brainstorming (A) generates ideas without judging them, and assigning responsibility (C) or motivating employees (D) have nothing to do with this analytical tool."}},{"itemId":"d778a088-5dcb-5659-8f84-813c01e4c4a2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a59fbc5-ba0e-59ca-9235-f77017b51c3a","sourceKey":"bank:AMS101:AMS101-U352","parentItemId":null,"revision":1,"payload":{"prompt":"The Delphi technique is used to:","options":["Brainstorm ideas","Collect expert opinions","Rank alternatives","Automate decisions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The Delphi technique gathers the opinions of a panel of experts through several rounds of questionnaires until their views come together. Brainstorming (A) is a face-to-face idea-generation method, and Delphi does not simply rank alternatives (C) or automate decisions (D)."}},{"itemId":"8b47bbde-0dfd-5326-b742-d28cf744f6fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"68d13a41-9046-5d78-a01c-3deb062a31d4","sourceKey":"bank:AMS101:AMS101-U353","parentItemId":null,"revision":1,"payload":{"prompt":"\"Satisficing\" means choosing an option that is:","options":["The best possible","Acceptable and satisfactory","The most profitable","Time-consuming"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"To satisfice is to accept a solution that is good enough, meeting the minimum requirements, instead of searching for the perfect one. The best possible option (A) is what the pure rational model aims for, and the most profitable (C) or time-consuming (D) options are not what the term describes."}},{"itemId":"ebdcf005-87ae-53ca-b5c3-76e15287e5ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65eee474-4e92-54ee-a617-310d5ddebc38","sourceKey":"bank:AMS101:AMS101-U354","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a qualitative decision-making tool?","options":["Break-even analysis","SWOT analysis","Cost-benefit analysis","Decision tree"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"SWOT analysis is qualitative because it lists and judges strengths, weaknesses, opportunities and threats in words rather than numbers. Break-even analysis (A), cost-benefit analysis (C) and decision trees (D) are quantitative tools that rely on figures and calculations."}},{"itemId":"5dfb118e-1192-52e4-a98b-9f72ec6b3f37","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"80f4f647-de3c-57cb-bd65-3cdb3fc117a6","sourceKey":"bank:AMS101:AMS101-U355","parentItemId":null,"revision":1,"payload":{"prompt":"The PERT technique is used in decision-making to:","options":["Assign probabilities","Estimate project duration","Reduce costs","Improve communication"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"PERT (Program Evaluation and Review Technique) breaks a project into activities and estimates how long each will take, which shows the expected project duration. Assigning probabilities (A) is done with tools like decision trees, and PERT is not mainly a cost-cutting (C) or communication (D) method."}},{"itemId":"e05df5b4-a5e7-5062-a91a-10c9db431ca7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aac86cfc-37f6-5ce6-8faa-daab807ff388","sourceKey":"bank:AMS101:AMS101-U356","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following factors affects decision-making?","options":["Risk","Certainty","Time constraints","All of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"Risk, certainty and time constraints all shape how decisions are made, since they affect how much information is available and how carefully options can be weighed. Each of A, B and C is a valid factor on its own, so the full answer is all of the above."}},{"itemId":"ba9a6bbc-94a3-5556-a3be-6126719f58ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da823193-0eb2-5aa3-8da5-73cde0874948","sourceKey":"bank:AMS101:AMS101-U357","parentItemId":null,"revision":1,"payload":{"prompt":"An intuitive decision-making style relies on:","options":["Experience and gut feeling","Data and analysis","Logic only","Mathematical models"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Intuitive decision-making is making choices based on experience, feelings and accumulated judgment, often described as gut feeling. Data and analysis (B), logic only (C) and mathematical models (D) describe the rational, analytical approach instead."}},{"itemId":"c1b2c4ef-6dc6-5cca-b32f-bd3ffc86407b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c755ae4-c8a6-5974-800d-fb00a00a9a8b","sourceKey":"bank:AMS101:AMS101-U358","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making authority is concentrated at the top levels in:","options":["Decentralized organizations","Centralized organizations","Flat organizations","Matrix structures"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"In a centralized organization decision-making authority is concentrated at the upper levels, so top managers hold more of it. Decentralized organizations (A) and flat structures (C) push decisions down to lower levels, and matrix structures (D) share authority across functional and project managers."}},{"itemId":"156f9e80-bf0c-5597-b76e-a207247a7fac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da7f72df-7ccd-5524-9c8e-72c01cf88820","sourceKey":"bank:AMS101:AMS101-U359","parentItemId":null,"revision":1,"payload":{"prompt":"Which decision-making approach involves listing pros and cons?","options":["Pareto analysis","Cost-benefit analysis","Brainstorming","Grid analysis"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Cost-benefit analysis weighs the costs (the cons) of an option against its benefits (the pros), which is the formal version of listing pros and cons. Pareto analysis (A) picks out the few causes behind most problems, brainstorming (C) generates ideas, and grid analysis (D) scores options against several weighted factors."}},{"itemId":"e6a18583-6a08-578e-a3bd-780445fa8214","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6010d8f2-5912-5259-8669-1fb4a7bc91bc","sourceKey":"bank:AMS101:AMS101-U360","parentItemId":null,"revision":1,"payload":{"prompt":"Ethical decision-making involves:","options":["Personal preferences","Compliance with laws","Morality and fairness","Maximizing profits"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Ethics is about principles of right and wrong, so ethical decision-making is guided by morality and fairness. Obeying the law (B) is important but an action can be legal and still unfair, while personal preferences (A) and maximizing profit (D) are not ethical standards in themselves."}},{"itemId":"82a5ab61-5ea6-5bc6-8d31-e37f4947a54e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d96c5278-23db-51e3-bd0b-e443f0d33e19","sourceKey":"bank:AMS101:AMS101-U362","parentItemId":null,"revision":1,"payload":{"prompt":"A brainstorming session helps in:","options":["Selecting an alternative","Generating multiple ideas","Evaluating decisions","Implementing plans"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Brainstorming is an idea-generating process that encourages people to suggest as many alternatives as possible while holding back criticism. Selecting an alternative (A), evaluating decisions (C) and implementing plans (D) all come later, after the ideas have been generated."}},{"itemId":"5198a1d4-6f12-5ec1-80ba-da4059736a44","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"79eee35c-47fb-52f6-abe1-cf6eafd02168","sourceKey":"bank:AMS101:AMS101-U363","parentItemId":null,"revision":1,"payload":{"prompt":"The Vroom-Yetton model is associated with:","options":["Job design","Decision-making participation","Conflict resolution","Performance measurement"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"The Vroom-Yetton model, also called the leader-participation model, helps a leader decide how much subordinates should take part in a particular decision, so it is about decision-making participation. Job design (A) concerns how tasks are grouped into jobs, and the model does not deal with conflict resolution (C) or performance measurement (D)."}},{"itemId":"083eb205-43dd-5c97-9f9c-494a99ff6dbc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6b62862d-8beb-5fe9-b254-e468a815c204","sourceKey":"bank:AMS101:AMS101-U364","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following can hinder decision-making?","options":["Time pressure","Clear objectives","Structured processes","Available resources"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Time pressure can force people to rush, skip steps and overlook good alternatives, which hinders sound decisions. Clear objectives (B), structured processes (C) and available resources (D) all make decision-making easier rather than harder."}},{"itemId":"2317cf2b-3c50-5dd9-b2ac-c7389e6c9bb1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cab014df-3f8e-5a2e-af67-2d5500db15d2","sourceKey":"bank:AMS101:AMS101-U365","parentItemId":null,"revision":1,"payload":{"prompt":"Groupthink occurs when:","options":["Decisions are based on analysis","There is an overemphasis on consensus","Diverse opinions are considered","Risks are properly assessed"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Groupthink happens when the desire for agreement is so strong that members hold back doubts and go along with the group, overemphasizing consensus. Basing decisions on analysis (A), considering diverse opinions (C) and assessing risks properly (D) are the very things groupthink prevents."}},{"itemId":"54ddca77-41bb-5912-baca-b1f9b8dca15d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e01b76b-fe2b-5d73-b964-052b78276c94","sourceKey":"bank:AMS101:AMS101-U366","parentItemId":null,"revision":1,"payload":{"prompt":"Opportunity cost in decision-making refers to:","options":["The best alternative foregone","Financial cost only","Unrelated expenses","Fixed costs"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Opportunity cost is the value of the best alternative you give up when you make a choice. It is not limited to financial cost (B), and unrelated expenses (C) or fixed costs (D) are different cost ideas altogether."}},{"itemId":"11aee6d6-5c0e-53dc-bf68-2f66316f830e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8adac20-3b37-52ae-9b86-7e650d7dd8fa","sourceKey":"bank:AMS101:AMS101-U367","parentItemId":null,"revision":1,"payload":{"prompt":"Decision-making speed is often influenced by:","options":["Experience","Complexity","Time constraints","All of the above"],"correctOption":3,"section":"Foundations of Decision Making and Planning","explanation":"How fast a decision is made depends on the decision maker's experience, how complex the problem is and how much time is available. Since A, B and C each influence speed, all of the above is correct."}},{"itemId":"043aa454-866b-517a-9220-496dc4fd7ccb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee70e711-8544-5fad-aa41-4097da7634ba","sourceKey":"bank:AMS101:AMS101-U368","parentItemId":null,"revision":1,"payload":{"prompt":"Risk tolerance in decision-making refers to:","options":["Willingness to take risks","Avoiding risks","Measuring risk","Eliminating risk"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Risk tolerance is how willing a person or organization is to accept risk in pursuit of a goal. Avoiding risk (B) describes low tolerance, while measuring (C) and eliminating (D) risk are risk-management activities, not tolerance."}},{"itemId":"a92afcfd-10e4-5055-9d92-01b05ce1c2b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"176cd2e9-4016-5b7f-b651-0df5d6b6dfde","sourceKey":"bank:AMS101:AMS101-U370","parentItemId":null,"revision":1,"payload":{"prompt":"Delegation of decision-making is common in:","options":["Centralized organizations","Bureaucratic structures","Decentralized organizations","Start-ups only"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"Decentralized organizations push decision-making down to lower-level managers, so delegating decisions is normal there. Centralized organizations (A) and bureaucratic structures (B) keep decisions at the top, and delegation is not limited to start-ups (D)."}},{"itemId":"cd1c5c3e-b363-50bc-8d10-730ff3311761","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"188f65da-7c39-5108-916a-2de29f1ba2ec","sourceKey":"bank:AMS101:AMS101-U372","parentItemId":null,"revision":1,"payload":{"prompt":"Scenario analysis is used to:","options":["Reduce cost","Evaluate future possibilities","Set budgets","Control operations"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Scenario analysis imagines several possible futures and considers what would happen to the business in each one. It may inform budgets (C) or cost decisions (A), but its purpose is evaluating future possibilities, not controlling operations (D)."}},{"itemId":"7906e8da-1f79-55f8-81c1-7c6f187cc7d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e74d0d9c-f3d6-57f1-a142-791a8f8af3b2","sourceKey":"bank:AMS101:AMS101-U373","parentItemId":null,"revision":1,"payload":{"prompt":"The rational decision-making model assumes:","options":["Limited information","Emotional influence","Complete information and logical evaluation","Quick decision-making"],"correctOption":2,"section":"Foundations of Decision Making and Planning","explanation":"The rational model assumes the decision maker has complete information, knows all the alternatives and evaluates them logically to pick the best. Limited information (A) is the idea behind bounded rationality, and emotional influence (B) and quick decision-making (D) do not fit the rational ideal."}},{"itemId":"b5c211a2-18c7-5a67-b3cb-e7854802af9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"75d9fbc2-d151-5077-a9cc-339e80878b85","sourceKey":"bank:AMS101:AMS101-U374","parentItemId":null,"revision":1,"payload":{"prompt":"A tactical decision focuses on:","options":["Vision and mission","Short-term goals","Day-to-day operations","Industry trends"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Tactical decisions turn strategy into shorter-term goals and plans for departments, so they focus on short- to medium-term targets. Vision and mission (A) and industry trends (D) are strategic concerns, while day-to-day operations (C) belong to operational decisions."}},{"itemId":"d357d0da-5a4b-50aa-90a8-ac945cda1a25","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"359e914a-1a94-5390-abfe-5fdf1bac3296","sourceKey":"bank:AMS101:AMS101-U375","parentItemId":null,"revision":1,"payload":{"prompt":"Bias in decision-making can be reduced by:","options":["Personal judgment","Seeking expert advice","Ignoring data","Following gut feeling"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Seeking expert advice brings in outside views and facts that can challenge one's own assumptions, which helps reduce bias. Personal judgment (A) and following gut feeling (D) are where bias comes from, and ignoring data (C) makes bias worse."}},{"itemId":"07832137-75c0-5d17-9866-8cfcb16d15d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8e9f48bb-18da-586d-9519-9a526ba8e3d1","sourceKey":"bank:AMS101:AMS101-U376","parentItemId":null,"revision":1,"payload":{"prompt":"In business, a sunk cost is:","options":["Recoverable","Irrelevant to future decisions","A future expense","A potential investment"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"A sunk cost is money already spent that cannot be recovered, so it should not affect future decisions. It is therefore not recoverable (A), not a future expense (C) and not a potential investment (D)."}},{"itemId":"0252d41d-0f87-53a1-9691-2679a0c1dc93","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee689cec-fcb0-5619-9856-126251a903ad","sourceKey":"bank:AMS101:AMS101-U377","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a step in ethical decision-making?","options":["Identifying stakeholders","Increasing revenue","Outsourcing operations","Cutting costs"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Ethical decision-making starts by identifying everyone affected by a decision, the stakeholders, so their interests can be considered fairly. Increasing revenue (B), outsourcing (C) and cutting costs (D) are business actions, not steps in reasoning about right and wrong."}},{"itemId":"907069a2-5a6d-5ce1-8cdf-26d91b2a48ea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c4279184-7a93-52e4-b57d-737f3eaea200","sourceKey":"bank:AMS101:AMS101-U378","parentItemId":null,"revision":1,"payload":{"prompt":"A quick decision-making process is usually:","options":["Always accurate","Not always optimal","Never risky","Time-consuming"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Quick decisions save time but often skip careful analysis, so they are not always the best choice. They are not always accurate (A), they can be quite risky (C), and by definition they are not time-consuming (D)."}},{"itemId":"9fae6d66-95bc-51e0-9268-bedc87525f73","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f22433e2-3abe-5bd9-a924-6a7461a78326","sourceKey":"bank:AMS101:AMS101-U379","parentItemId":null,"revision":1,"payload":{"prompt":"A key element of participative decision-making is:","options":["Employee involvement","External consultants","Top-down approach","Strict deadlines"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Participative decision-making means involving employees in the decisions that affect them. External consultants (B) are outsiders, a top-down approach (C) is the opposite of participation, and strict deadlines (D) are not what defines it."}},{"itemId":"8c301959-fb2f-5a2c-af03-4b5d309f6b77","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f32babdd-6015-59fd-b21d-d15e7edb92fd","sourceKey":"bank:AMS101:AMS101-U380","parentItemId":null,"revision":1,"payload":{"prompt":"The role of feedback in decision-making is to:","options":["Evaluate effectiveness","Assign blame","Reduce risk","Delay action"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Feedback shows how well a decision has worked, so it is used to evaluate its effectiveness and guide future choices. It is not meant to assign blame (B) or delay action (D), and while it may help lower future risk (C), its main role is evaluation."}},{"itemId":"136c0525-dfdb-5f34-a518-0776a9bb7672","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4ca5deef-0626-500d-9368-14e3a6b2e7b5","sourceKey":"bank:AMS101:AMS101-U381","parentItemId":null,"revision":1,"payload":{"prompt":"The most common bias in decision-making is:","options":["Confirmation bias","Statistical bias","Logical bias","Analytical bias"],"correctOption":0,"section":"Foundations of Decision Making and Planning","explanation":"Confirmation bias is the tendency to look for information that supports what we already believe and ignore what contradicts it, and it is one of the most widespread decision errors. Statistical (B), logical (C) and analytical (D) bias are not the standard named decision-making biases."}},{"itemId":"cd8aac2c-907e-5d2f-9b1e-ba53f8658081","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be373a71-5da1-51b6-82bd-927269afd7ca","sourceKey":"bank:AMS101:AMS101-U382","parentItemId":null,"revision":1,"payload":{"prompt":"Effective decision-makers should:","options":["Avoid all risks","Be proactive and analytical","Follow their instincts only","Seek approval constantly"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Effective decision-makers anticipate problems and analyze information before choosing, so being proactive and analytical is the right answer. Avoiding all risks (A) is unrealistic, relying only on instinct (C) ignores evidence, and constantly seeking approval (D) slows decisions down."}},{"itemId":"df897c17-7fd7-5d6f-bb0f-4da0c9d54773","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"256f4771-fb30-529b-bd4d-2854bd0f39d0","sourceKey":"bank:AMS101:AMS101-U383","parentItemId":null,"revision":1,"payload":{"prompt":"Risk management in decision-making involves:","options":["Ignoring uncertainty","Assessing potential losses","Taking maximum risks","Avoiding all decisions"],"correctOption":1,"section":"Foundations of Decision Making and Planning","explanation":"Risk management means identifying what could go wrong and assessing the possible losses so they can be reduced or planned for. Ignoring uncertainty (A), taking maximum risks (C) and avoiding all decisions (D) are the opposite of managing risk."}},{"itemId":"9356a269-c3ce-550d-97da-7253d7f94040","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be94818b-5f9d-5011-b18c-eb3967b7ecec","sourceKey":"bank:AMS101:AMS101-U384","parentItemId":null,"revision":1,"payload":{"prompt":"The business environment includes which of the following factors?","options":["Internal and External","Economic and Social","Political and Technological","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The business environment includes both internal and external factors, and the external part covers economic, social, political and technological forces. Since A, B and C each name real parts of the environment, all of the above is correct."}},{"itemId":"1e012c6f-f51d-5069-8ab8-422d33720fe5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df1d44a7-7100-54f6-88d4-6a24185886a7","sourceKey":"bank:AMS101:AMS101-U385","parentItemId":null,"revision":1,"payload":{"prompt":"The external environment of a business consists of factors that are:","options":["Controllable","Uncontrollable","Predictable","Avoidable"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The external environment is made up of forces outside the organization, such as the economy and government, which managers cannot directly control. That is why they are not controllable (A), and they are often unpredictable (C) and unavoidable (D)."}},{"itemId":"3dc337ae-6b35-509b-9e1b-70c3c8d9155f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98ad4aee-7c54-5be1-96cc-7b270d0c747e","sourceKey":"bank:AMS101:AMS101-U386","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a component of the microenvironment?","options":["Customers","Suppliers","Government policies","Competitors"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Government policies are part of the macro (general) environment because they affect all businesses broadly. Customers (A), suppliers (B) and competitors (D) deal directly with the firm, which makes them part of its microenvironment."}},{"itemId":"09bff2aa-20e6-5231-9248-671d229ed393","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"706c12b4-559f-5b76-bdfc-87b99c0814e1","sourceKey":"bank:AMS101:AMS101-U387","parentItemId":null,"revision":1,"payload":{"prompt":"The legal environment of a business includes:","options":["Trade regulations","Employee relations","Production techniques","Advertising methods"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The legal environment is made up of laws and rules that govern business, such as trade regulations. Employee relations (B), production techniques (C) and advertising methods (D) are internal management matters rather than legal factors."}},{"itemId":"5fbeb856-4314-5b68-99f2-304bb00fec9b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2894a5e2-9cb1-5ab1-81a8-a3a85dbb14a6","sourceKey":"bank:AMS101:AMS101-U388","parentItemId":null,"revision":1,"payload":{"prompt":"Which factor is part of the macro environment?","options":["Suppliers","Competitors","Technological changes","Customers"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Technological change is a broad force outside the firm that affects whole industries, so it belongs to the macro environment. Suppliers (A), competitors (B) and customers (D) interact directly with the business and form its microenvironment."}},{"itemId":"26abc7bc-bf12-5cd8-a4b4-98d84157f72f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a43284a0-4feb-545f-b1c7-5869ad484c9f","sourceKey":"bank:AMS101:AMS101-U389","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of an economic factor affecting business?","options":["Interest rates","Cultural values","Political stability","Consumer preferences"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Interest rates are an economic factor because they affect the cost of borrowing and how much people spend and invest. Cultural values (B) and consumer preferences (D) are social factors, and political stability (C) is a political factor."}},{"itemId":"6c1d9f00-c7fa-5ce2-b487-64324f238610","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a61422f4-8d36-569f-bd8c-ab8b814540ed","sourceKey":"bank:AMS101:AMS101-U390","parentItemId":null,"revision":1,"payload":{"prompt":"A SWOT analysis evaluates which aspects of a business?","options":["Strengths, Weaknesses, Opportunities, Threats","Supply, Work, Output, Team","Service, Welfare, Operation, Trade","Structure, Workload, Organization, Technology"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"SWOT stands for Strengths, Weaknesses, Opportunities and Threats, combining an internal look at the firm with an external look at its environment. The other expansions in B, C and D are made-up combinations that do not describe this tool."}},{"itemId":"d6216743-9645-5504-8987-addf84d87983","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"54545535-fbe8-5a18-97f4-22f9c2d20b8d","sourceKey":"bank:AMS101:AMS101-U391","parentItemId":null,"revision":1,"payload":{"prompt":"Social factors affecting the business environment include:","options":["Tax policies","Demographics","Trade policies","Inflation rate"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Demographics, such as age, population size and education, describe the people in a society, so they are social factors. Tax policies (A) and trade policies (C) are political-legal factors, and the inflation rate (D) is an economic factor."}},{"itemId":"0d10c404-9ed4-5c62-9adc-01e833163ca0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30d6f259-3943-53f8-9ad6-02a1639c1402","sourceKey":"bank:AMS101:AMS101-U392","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an element of the political environment?","options":["Government policies","Political stability","Social values","Trade regulations"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Social values are part of the social or cultural environment, not the political one. Government policies (A), political stability (B) and trade regulations (D) all come from government and politics."}},{"itemId":"61cadb34-c021-52dc-a56d-a2e442654f77","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6bc59c92-1a2c-5f3b-a623-0589e7d8507c","sourceKey":"bank:AMS101:AMS101-U393","parentItemId":null,"revision":1,"payload":{"prompt":"Which is an example of a technological factor influencing business?","options":["Taxation laws","Automation","Inflation","Population growth"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Automation is the use of machines and technology to do work, so it is a technological factor. Taxation laws (A) are legal, inflation (C) is economic, and population growth (D) is demographic or social."}},{"itemId":"df476564-cd35-5e38-a655-9787b7528b42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"61f3bfac-6a7b-5c7d-a384-c2110cb72e1c","sourceKey":"bank:AMS101:AMS101-U394","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"globalization\" in business refers to:","options":["Expanding operations within a country","Increasing international trade and relations","Using only domestic resources","Reducing market competition"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Globalization is the growing exchange of goods, services, people and money across national borders, increasing international trade and relations. Expanding only within one country (A) or using only domestic resources (C) is the opposite, and globalization usually increases competition rather than reducing it (D)."}},{"itemId":"3ea70c87-3d62-58e5-a497-96d14faa73d1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47484c1f-0df5-564c-87a4-f50f75e37f56","sourceKey":"bank:AMS101:AMS101-U395","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these best describes the competitive environment?","options":["Market conditions","Government policies","Employee satisfaction","Social values"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The competitive environment is about market conditions such as how many rivals exist, how strong they are and how they compete for customers. Government policies (B) are political factors, employee satisfaction (C) is internal, and social values (D) are part of the social environment."}},{"itemId":"3f975c4c-449a-5263-ad9b-f0979a8c001e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5ae740dd-8a7a-5fdb-a535-7d6bb0eb5dfc","sourceKey":"bank:AMS101:AMS101-U396","parentItemId":null,"revision":1,"payload":{"prompt":"The internal environment of a business includes:","options":["Suppliers","Employees","Competitors","Government"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Employees work inside the organization, so they are part of its internal environment along with its culture and resources. Suppliers (A), competitors (C) and government (D) are outside the organization and belong to the external environment."}},{"itemId":"b856626a-18e0-56f7-875d-62a0f1885588","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1a551c6-827f-5ce5-9597-20523ea2889f","sourceKey":"bank:AMS101:AMS101-U397","parentItemId":null,"revision":1,"payload":{"prompt":"The economic environment affects businesses through:","options":["Exchange rates","Employee productivity","Corporate culture","Technological development"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Exchange rates are an economic force because they change the cost of imports and the price of exports, directly affecting a business. Employee productivity (B) and corporate culture (C) are internal factors, and technological development (D) belongs to the technological environment."}},{"itemId":"c0a915db-bdca-5248-a9e5-f9e52a55b850","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f6ee02a-41de-587f-8507-19cfd29fc263","sourceKey":"bank:AMS101:AMS101-U398","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a political-legal factor?","options":["Consumer preferences","Interest rates","Labor laws","Innovation"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Labor laws are passed by government to regulate employment, which makes them a political-legal factor. Consumer preferences (A) are social, interest rates (B) are economic, and innovation (D) is technological."}},{"itemId":"d244b65b-14bb-55c8-8594-d605fa22c4fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65c13c2b-6c77-5c3a-a737-f5160d1c17aa","sourceKey":"bank:AMS101:AMS101-U399","parentItemId":null,"revision":1,"payload":{"prompt":"The environmental factor that deals with people's attitudes, values, and lifestyles is:","options":["Economic","Social","Political","Technological"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Attitudes, values and lifestyles are part of a society's culture, so they fall under the social environment. Economic factors (A) deal with income and prices, political factors (C) with government, and technological factors (D) with new tools and methods."}},{"itemId":"bc1e30a0-6ec7-581b-926a-851524385a88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7bb24096-8ba1-5414-82cb-5f5c3ed9792f","sourceKey":"bank:AMS101:AMS101-U400","parentItemId":null,"revision":1,"payload":{"prompt":"A company's microenvironment includes:","options":["Customers and suppliers","Cultural trends","Legal regulations","Interest rates"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"The microenvironment is made up of the groups a company deals with directly, such as customers and suppliers. Cultural trends (B), legal regulations (C) and interest rates (D) are broad forces in the macro environment."}},{"itemId":"3320fff1-ef93-5f6f-82f6-f44c8dacee2b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d28f3bae-041b-5a18-a46f-0bdc3eecec06","sourceKey":"bank:AMS101:AMS101-U401","parentItemId":null,"revision":1,"payload":{"prompt":"Changes in exchange rates impact:","options":["Domestic sales","International trade","Local competition","Employee turnover"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Exchange rates decide how much one currency is worth in another, so they mainly affect the prices of imports and exports in international trade. Domestic sales (A) and local competition (C) may feel some indirect effect, but employee turnover (D) is unrelated."}},{"itemId":"1dce3b2d-de12-5a51-8c4a-1be979e3baa0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"590397b2-d8d4-5b06-97df-8d2f6c248371","sourceKey":"bank:AMS101:AMS101-U402","parentItemId":null,"revision":1,"payload":{"prompt":"Business ethics relate to:","options":["Employee benefits","Moral principles and values","Financial planning","Production techniques"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Business ethics are the moral principles and values that define right and wrong conduct in business. Employee benefits (A), financial planning (C) and production techniques (D) are business activities, not ethical standards."}},{"itemId":"4cdd30cb-c715-58f0-ad7d-584b24bc0be1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16a99c6f-b574-55de-ac59-7b88834ad376","sourceKey":"bank:AMS101:AMS101-U403","parentItemId":null,"revision":1,"payload":{"prompt":"Inflation impacts businesses by:","options":["Reducing competition","Increasing costs","Lowering taxes","Improving productivity"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Inflation is a general rise in prices, so businesses pay more for raw materials, wages and other inputs. It does not reduce competition (A), lower taxes (C) or improve productivity (D)."}},{"itemId":"2093ca72-588d-5e59-83ee-43a74c36bdea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"68504368-e6ae-5bad-b3f8-bad6fdc1bc69","sourceKey":"bank:AMS101:AMS101-U404","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an external threat to a business?","options":["Employee turnover","Technological innovation by competitors","Leadership changes","Marketing strategy"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A threat comes from outside the business, and a competitor's new technology is an external force that can take away customers. Employee turnover (A), leadership changes (C) and marketing strategy (D) are internal matters, so they would count as strengths or weaknesses instead."}},{"itemId":"b5f2ca20-a1a0-5e39-9dfd-f38bb54ece04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4f32fee5-2754-5a86-9fd5-88ac7a313ac8","sourceKey":"bank:AMS101:AMS101-U405","parentItemId":null,"revision":1,"payload":{"prompt":"A stakeholder in business refers to:","options":["Only customers","Investors, employees, and customers","Suppliers only","Competitors only"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Stakeholders are any groups affected by an organization's decisions and actions, which includes investors, employees and customers among others. Options A, C and D each name only one group, which is far too narrow."}},{"itemId":"e6453e69-82bd-504e-8117-c6cc8fb9dcd1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8938a922-4942-5c60-84e9-c4fca50e1884","sourceKey":"bank:AMS101:AMS101-U406","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"demographics\" refers to:","options":["Customer preferences","Population characteristics","Government policies","Economic fluctuations"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Demographics are the characteristics of a population, such as age, gender, income, education and size. Customer preferences (A) are tastes, government policies (C) are political, and economic fluctuations (D) are changes in the economy."}},{"itemId":"78df86dc-ed7f-5f99-99ab-88882bb088d8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"69f5db09-8791-57fa-85a5-0cefabc6afc2","sourceKey":"bank:AMS101:AMS101-U407","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a regulatory body in the business environment?","options":["Central Bank","Competitors","Suppliers","Customers"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A central bank is a government institution that regulates banks and the money supply, so it acts as a regulatory body. Competitors (B), suppliers (C) and customers (D) are market players, not regulators."}},{"itemId":"17a0dd47-7832-54c0-97dc-35924af6aabf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aff5e387-1c42-5c47-bb91-e6e310b32f4b","sourceKey":"bank:AMS101:AMS101-U408","parentItemId":null,"revision":1,"payload":{"prompt":"What does CSR stand for in business?","options":["Corporate Social Responsibility","Customer Service Relations","Company Sales Report","Consumer Safety Regulations"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"CSR stands for Corporate Social Responsibility, a company's commitment to act in ways that are good for society. The phrases in B, C and D sound business-like but are not what the abbreviation means."}},{"itemId":"f85cfb44-aa59-5062-9caf-1ca95fb7ed9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fdb2c0b6-e9c1-58fd-bce0-1b2f7aece137","sourceKey":"bank:AMS101:AMS101-U409","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is considered an environmental factor?","options":["Climate change","Employee turnover","Production techniques","Branding strategy"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Climate change concerns the natural, physical environment, so it is an environmental (ecological) factor. Employee turnover (B), production techniques (C) and branding strategy (D) are internal business matters."}},{"itemId":"2d4f8c20-0fbc-51ea-a5ca-70cea9987c64","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b306796b-c342-548a-9b66-441ec7d509e1","sourceKey":"bank:AMS101:AMS101-U411","parentItemId":null,"revision":1,"payload":{"prompt":"The term \"market structure\" refers to:","options":["Government policies","Competition levels","Technological changes","Cultural values"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Market structure describes how competitive a market is, based on things like the number of sellers and how similar their products are, for example monopoly or perfect competition. Government policies (A), technological changes (C) and cultural values (D) are other environmental factors."}},{"itemId":"fdea34ff-1302-5b63-81b7-04be6af3c1ef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"01cf06e3-8a1a-56d9-9c5a-bed647699627","sourceKey":"bank:AMS101:AMS101-U414","parentItemId":null,"revision":1,"payload":{"prompt":"Business strategy is influenced by which of the following factors?","options":["Internal resources","Economic conditions","Technological trends","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A good business strategy considers the firm's internal resources as well as external forces like economic conditions and technological trends. Since A, B and C each influence strategy, all of the above is correct."}},{"itemId":"6bf3bbfb-6751-5794-b9cd-9eb78c60093a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5fffc533-3e38-5372-9417-23d966be4387","sourceKey":"bank:AMS101:AMS101-U416","parentItemId":null,"revision":1,"payload":{"prompt":"A company's external stakeholders include:","options":["Employees","In-house sales staff","Suppliers","Management"],"correctOption":2,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Suppliers are separate firms outside the company that are affected by its decisions, so they are external stakeholders. Employees (A), in-house sales staff (B) and management (D) all work inside the organization, which makes them internal stakeholders."}},{"itemId":"9bab43a5-0d16-5e14-be5a-b38ad55aca3b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9e2d2344-d7b1-5180-8978-3149369b99f0","sourceKey":"bank:AMS101:AMS101-U417","parentItemId":null,"revision":1,"payload":{"prompt":"Government policies can impact businesses through:","options":["Taxation and regulations","Internal processes","Employee satisfaction","Product quality"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Government affects businesses mainly through taxes and regulations that set costs and the rules firms must follow. Internal processes (B), employee satisfaction (C) and product quality (D) are mainly controlled by the business itself."}},{"itemId":"63947a6f-4b65-5033-b4b1-9226820d3a51","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8087ebb7-2886-5ddf-afab-c36742f3bbad","sourceKey":"bank:AMS101:AMS101-U420","parentItemId":null,"revision":1,"payload":{"prompt":"Environmental sustainability in business means:","options":["Reducing waste and pollution","Expanding globally","Improving sales","Increasing profits"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Environmental sustainability means running a business in a way that protects the natural environment, for example by reducing waste and pollution. Expanding globally (B), improving sales (C) and increasing profits (D) are business growth goals, not environmental ones."}},{"itemId":"833dc6e4-c833-5fd9-8e56-6941ea2755cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05ee9eb5-5dac-5075-9a16-c54e9bc689c8","sourceKey":"bank:AMS101:AMS101-U421","parentItemId":null,"revision":1,"payload":{"prompt":"A growing economy usually results in:","options":["Reduced consumer spending","Increased business opportunities","Higher inflation","Lower employment"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"When the economy grows, people earn and spend more, which opens up more opportunities for businesses to sell and expand. Reduced spending (A) and lower employment (D) are signs of a weak economy, and higher inflation (C) can happen but is not the usual defining result of growth."}},{"itemId":"a60fe063-1266-5f9a-81f1-fa55cebefb8b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00f930a3-ac7b-5ae9-825e-e5f716ad58cf","sourceKey":"bank:AMS101:AMS101-U422","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a characteristic of a free-market economy?","options":["Government control","Consumer choice","Fixed prices","Limited competition"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"In a free-market economy consumers freely decide what to buy, and their choices guide what businesses produce. Government control (A) and fixed prices (C) describe a command economy, and free markets usually have strong rather than limited competition (D)."}},{"itemId":"dc5e3aa0-1ab8-5db2-8a1e-d8d41b105f2b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e3702625-a352-56ab-913b-4046021e95ee","sourceKey":"bank:AMS101:AMS101-U423","parentItemId":null,"revision":1,"payload":{"prompt":"Strategic planning in business includes:","options":["Setting long-term goals","Daily operations management","Employee training","Product pricing"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Strategic planning is about deciding the organization's long-term goals and the broad plans to achieve them. Daily operations management (B) is operational planning, while employee training (C) and product pricing (D) are narrower functional activities."}},{"itemId":"60f936e0-93fa-5c5a-a98c-68ca67dd57af","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"68159bc0-0dbe-507d-90c0-cdcd1bed4a8d","sourceKey":"bank:AMS101:AMS101-U424","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is part of corporate culture?","options":["Employee behavior","Government policies","Interest rates","Supply chain logistics"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Corporate culture is the shared values, traditions and ways of doing things that shape how employees behave, so employee behavior reflects it. Government policies (B), interest rates (C) and supply chain logistics (D) are not part of an organization's culture."}},{"itemId":"6fe7f0a4-d62c-5728-8c82-b9bb084ef68e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd47de60-2c48-5459-941b-2e2f2c9c2b00","sourceKey":"bank:AMS101:AMS101-U425","parentItemId":null,"revision":1,"payload":{"prompt":"A business can influence its environment through:","options":["Lobbying","Competitor actions","Market regulations","Cultural changes"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Lobbying is when a business tries to influence government decisions and laws, so it is a way the firm actively shapes its environment. Competitor actions (B), market regulations (C) and cultural changes (D) are forces that act on the business, not tools the business uses."}},{"itemId":"0216e7c0-923f-5d8f-bb0e-d0365afdad83","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e7818800-4c26-59f5-908c-5f0e57ea322c","sourceKey":"bank:AMS101:AMS101-U426","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is considered a legal factor?","options":["Consumer trends","Tax laws","Production processes","Employee relations"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Tax laws are rules made by government, so they are a legal factor. Consumer trends (A) are social, while production processes (C) and employee relations (D) are internal business matters."}},{"itemId":"ce94fc4e-aa03-584c-9dc4-7ef8d4eb8e30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14540b2a-d1cd-55cf-9431-4fc13124ed06","sourceKey":"bank:AMS101:AMS101-U427","parentItemId":null,"revision":1,"payload":{"prompt":"Ethical business practices promote:","options":["Long-term sustainability","Immediate profits","Market monopoly","Lower employee wages"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Ethical practices build trust with customers, employees and the community, which helps a business survive and succeed in the long run. Chasing immediate profits (B), monopolizing the market (C) or cutting wages (D) are not what ethics promote."}},{"itemId":"95df8a88-6e12-52a9-9142-2ba38167c57d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bd5ebd1a-5e9f-5875-85ec-ce044f32f264","sourceKey":"bank:AMS101:AMS101-U428","parentItemId":null,"revision":1,"payload":{"prompt":"Business growth is affected by:","options":["Market demand","Political stability","Economic policies","All of the above"],"correctOption":3,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Business growth depends on how much customers want the product, how stable the political climate is and what economic policies government follows. Since A, B and C all matter, all of the above is correct."}},{"itemId":"99e6ad7c-44fb-55e9-9c2e-f27391b469e2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a8f8a13b-8d74-5fe6-8aeb-d63b9770023e","sourceKey":"bank:AMS101:AMS101-U429","parentItemId":null,"revision":1,"payload":{"prompt":"An oligopoly market structure involves:","options":["Few sellers","Many buyers","No competition","Low demand"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"An oligopoly is a market dominated by a few large sellers, such as a handful of telecom or cement companies. Many buyers (B) can exist in any market, no competition (C) describes a monopoly, and low demand (D) is not a feature of the structure."}},{"itemId":"89929f24-5d28-5f1a-99da-46f65ea04432","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc98a237-c9c0-5fe6-ab6e-934a0bc48982","sourceKey":"bank:AMS101:AMS101-U430","parentItemId":null,"revision":1,"payload":{"prompt":"The primary objective of a business is to:","options":["Provide employment","Generate profits","Comply with laws","Expand globally"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"A business exists mainly to make a profit by providing goods or services that customers want. Providing employment (A), obeying laws (C) and expanding globally (D) can be important, but they are results or conditions of doing business rather than its main purpose."}},{"itemId":"eecf426c-312c-5f47-9d88-feab92400c7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"423418e1-50ee-5d24-bbf8-bcdd1b284600","sourceKey":"bank:AMS101:AMS101-U431","parentItemId":null,"revision":1,"payload":{"prompt":"Businesses adapt to environmental changes by:","options":["Restructuring operations","Ignoring competition","Reducing workforce","Keeping all existing practices unchanged"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"When the environment changes, businesses adapt by restructuring how they operate, for example by changing processes, structures or product lines. Ignoring competition (B) and keeping every practice unchanged (D) mean not adapting at all, and reducing the workforce (C) is only one possible step rather than the general way firms adapt."}},{"itemId":"375b024e-26ad-5542-b4c5-3dbaeb90e7e9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"496e2ab7-13f6-54be-8dc4-a336d8902cc0","sourceKey":"bank:AMS101:AMS101-U432","parentItemId":null,"revision":1,"payload":{"prompt":"Business policies are designed to:","options":["Regulate internal operations","Control competitors","Increase government influence","Limit growth"],"correctOption":0,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Business policies are guidelines that steer decisions and regulate how things are done inside the organization. A firm cannot control its competitors (B) with its policies, and increasing government influence (C) or limiting growth (D) is not their purpose."}},{"itemId":"c2689832-3e5f-5657-9da3-53cac822f507","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc0d80e9-0485-527e-b256-3289ec8d9198","sourceKey":"bank:AMS101:AMS101-U433","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key external force in the business environment?","options":["Organizational structure","Technological advancements","Employee skills","Managerial decisions"],"correctOption":1,"section":"The Management Environment and Integrative Managerial Issues","explanation":"Technological advancement is a key external force because it comes from outside the firm and can change products, methods and whole industries. Organizational structure (A), employee skills (C) and managerial decisions (D) are part of the internal environment."}},{"itemId":"00db200a-1860-5c21-a812-6a594054fd5b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"abcc6d3b-4815-5c9a-bf3f-2824f9dcc0e7","sourceKey":"bank:AMS101:M101-T10N-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of evaluating an organization's progress towards its goals through monitoring, comparing and taking corrective action is called:","options":["Controlling","Planning","Organizing","Leading"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Controlling is the management function that checks how far the organization has moved towards its goals, by monitoring work, comparing it with what was planned and correcting deviations. Option B, planning, is where the goals are set in the first place, not where progress towards them is evaluated."}},{"itemId":"93ebf673-240f-5df6-84c3-314f05dae8cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c4a7cdc6-1a25-50a4-a5ea-2382b7a39c47","sourceKey":"bank:AMS101:M101-T10N-002","parentItemId":null,"revision":1,"payload":{"prompt":"Controlling can best be described as the process of:","options":["Setting goals and deciding how to achieve them","Monitoring, comparing and correcting work performance","Arranging and structuring work to accomplish goals","Directing and motivating people to accomplish goals"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Controlling means monitoring work, comparing it with plans and correcting it, so that activities are done as planned and significant deviations are fixed. Option A describes planning, while options C and D describe organizing and leading."}},{"itemId":"6a96db6f-e8ec-545c-99c0-9816d71eb1f8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3d30b8a0-06c2-5a0b-ad56-079e54730ecd","sourceKey":"bank:AMS101:M101-T10N-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which three activities together make up controlling?","options":["Forecasting, budgeting and scheduling","Planning, organizing and leading","Monitoring, comparing and taking corrective action","Recruiting, training and retaining"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Controlling involves monitoring performance, comparing it with goals and taking corrective action to keep the organization on track. Option B lists the other three management functions, which come before controlling rather than forming part of it."}},{"itemId":"1426e066-a44e-5f39-8c7e-34a9efdab041","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c6e0181-0266-5e82-9853-c4b28e817aa6","sourceKey":"bank:AMS101:M101-T10N-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three reasons why control is important?","options":["The planning-controlling link","Protecting the workplace","Empowering employees","Centralizing all decision-making at the top"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Control matters for three reasons: the planning-controlling link, empowering employees and protecting the workplace. Centralizing decisions at the top is not one of them; in fact, good control does the opposite by making managers more comfortable delegating, as option C suggests."}},{"itemId":"590822a6-643e-56c2-bf98-0b63e864dc3f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1bdff7d-f0bc-52e9-98a1-a97dd393dc3b","sourceKey":"bank:AMS101:M101-T10N-005","parentItemId":null,"revision":1,"payload":{"prompt":"How many reasons are commonly given for why control is important to an organization?","options":["Two","Four","Five","Three"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"There are three reasons: the planning-controlling link, empowering employees and protecting the workplace. Option B is a tempting guess because there are four management functions, but that number does not apply here."}},{"itemId":"b42174be-7429-5523-9332-a665d67c6aab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"effccc16-b8e3-5c88-9c51-28669a24d955","sourceKey":"bank:AMS101:M101-T10N-006","parentItemId":null,"revision":1,"payload":{"prompt":"The branch manager of a commercial bank in Lagos has been slow to delegate loan decisions because she fears being blamed for her officers' mistakes. After a new system starts giving her regular feedback on each officer's performance, she delegates more freely. This illustrates which reason why control is important?","options":["Corporate governance","Protecting the workplace","The planning-controlling link","Empowering employees"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"A good control system gives managers information on employee performance, which reduces their fear of being blamed and lets them delegate with less worry; this is the empowering employees reason. Option C is about control feeding results back into planning, which is not what happens in this case."}},{"itemId":"d898b2ef-3528-5780-9541-86864b052f8f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84e991ea-97f8-5e6b-b300-6887788edb5d","sourceKey":"bank:AMS101:M101-T10N-007","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota sets up data back-ups and a back-up plan so that production can continue if there is a security breach or a supply chain disruption. Which reason for the importance of control does this reflect?","options":["Controlling customer interactions","Protecting the workplace","The planning-controlling link","Empowering employees"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Controls and back-up plans protect the organization and its assets from threats such as security breaches and supply chain disruptions, so work can keep going. Option D is about helping managers delegate, which has nothing to do with guarding against threats."}},{"itemId":"57a31248-98e3-54ee-86f5-1b08a811a916","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e58898cd-740c-5f07-8dc6-490dbee7e29e","sourceKey":"bank:AMS101:M101-T10N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which reason for the importance of control holds that control checks whether the goals set by managers are being met and feeds the results back into new planning?","options":["The service profit chain","Protecting the workplace","The planning-controlling link","Empowering employees"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Planning sets the goals, and control checks whether they are met and feeds back into the next round of planning; this is the planning-controlling link. Option D concerns giving managers the confidence to delegate, not linking results back to goals."}},{"itemId":"6d34a6d1-bed2-5553-a07f-1973b1f2de38","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"72ed693c-7d03-586c-b7e4-6dcc81e686e4","sourceKey":"bank:AMS101:M101-T10N-009","parentItemId":null,"revision":1,"payload":{"prompt":"Controls help protect the workplace against several threats. Which of the following is NOT one of those threats?","options":["Natural disasters","Rising customer loyalty","Financial scandals","Supply chain disruptions"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The threats that workplace controls guard against include natural disasters, financial scandals, workplace violence, supply chain disruptions, security breaches and terrorism. Rising customer loyalty is a good outcome, not a threat, so it is the odd one out; options A, C and D are all genuine threats."}},{"itemId":"0a9b3c9b-f396-5890-95a9-4563d033b481","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5fa2dc58-1d38-5fee-8bc7-edc340eac43f","sourceKey":"bank:AMS101:M101-T10N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Planning and controlling are often called twin functions. Which statement correctly shows one way in which they are alike?","options":["Both are one-off activities carried out once a year","Both are concerned only with financial results","Both take place at all levels of management","Both are performed only by top managers"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Planning and controlling both happen at every level of management, from top managers to supervisors, and both are continuous. Option D is wrong because neither function is limited to top management, and option A contradicts the fact that both are ongoing."}},{"itemId":"ed9d3593-fbfa-57a4-b3df-e0ab414cae85","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"18767daa-35dd-52af-8127-3d69a354e64c","sourceKey":"bank:AMS101:M101-T10N-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly describes the relationship between planning and controlling with respect to goals?","options":["Control sets the goals, while planning checks whether they are met","Planning deals with goals, while control has nothing to do with goals","Planning and control both set goals but never check them","Planning sets the goals, while control checks whether they are met"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Both functions look at goals, but in different ways: planning sets them and control checks whether they are being achieved. Option A is the classic swap that reverses the two roles."}},{"itemId":"1972fd4c-37ca-5297-9412-4544fdb5ea1d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"93564440-5680-5015-bafb-2b52159cc684","sourceKey":"bank:AMS101:M101-T10N-012","parentItemId":null,"revision":1,"payload":{"prompt":"Why are planning and controlling described as continuous functions?","options":["Because planning replaces the need for control","Because both are done only once when a business starts","Because control results feed the next round of planning","Because control always comes before planning"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The two functions form a cycle: control checks results against plans, and those results become input for the next round of planning, so the process never really stops. Option D is wrong because controlling is the last function and follows planning rather than coming before it."}},{"itemId":"90942071-e87b-5b19-b125-fbcbb7ca3ab1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a85f93b9-122e-52df-aeef-8cace7f548ef","sourceKey":"bank:AMS101:M101-T10N-013","parentItemId":null,"revision":1,"payload":{"prompt":"What is the real test of whether an organization's control system is effective?","options":["Whether the organization's goals are being achieved","How strictly supervisors watch their staff","Whether employees find the system easy to use","How many reports the system produces each month"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"An effective control system makes sure activities are done in ways that lead to the organization's goals, so the real test is whether those goals are being achieved. Option D confuses activity with results; many reports mean nothing if goals are missed."}},{"itemId":"cecc9e82-42db-5b49-96de-daf300c27669","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"46d1ce33-e4e3-5c83-b387-9b5b636101f8","sourceKey":"bank:AMS101:M101-T10N-014","parentItemId":null,"revision":1,"payload":{"prompt":"Control minimises deviations from standards mainly because it helps managers to:","options":["Write the organization's mission statement","Design the organization's structure","Recruit and select qualified staff","Check errors and take corrective action"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Control helps to check errors and take corrective action, which keeps deviations from standards small and ensures goals are achieved in the desired manner. Options A, C and B belong to planning, staffing and organizing respectively, not to control."}},{"itemId":"951834e6-ab74-577c-83da-25e5e7a9d021","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"512b673b-bdee-5e41-aa2d-de4c02f39375","sourceKey":"bank:AMS101:M101-T10N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about control is FALSE?","options":["Control takes place only at the top level of management","Control involves comparing actual performance with standards","Control results feed back into planning","Control helps managers delegate with less worry"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Control, like planning, takes place at all levels of management, so saying it happens only at the top is false. Options B, D and C are all accurate descriptions of control."}},{"itemId":"96cef940-90b8-57c9-9fd7-55241c7964e5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df7c581c-96ea-53cd-83f7-41154aac472a","sourceKey":"bank:AMS101:M101-T10N-016","parentItemId":null,"revision":1,"payload":{"prompt":"Many managers are slow to delegate authority to their subordinates. The main reason is that they:","options":["Want to increase the span of control","Believe employees should make all decisions","Fear being blamed for an employee's mistake","Have no goals to achieve"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Managers are often reluctant to delegate because they fear being held responsible for a subordinate's mistakes. A control system that gives feedback on performance reduces this fear; option B is wrong because it describes the opposite attitude to delegation."}},{"itemId":"fe298128-2168-59b8-9627-095dd44f9593","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"658f92e0-011c-56aa-95bb-d993f6f4e350","sourceKey":"bank:AMS101:M101-T10N-018","parentItemId":null,"revision":1,"payload":{"prompt":"What is the first step in the control process?","options":["Revising the standard","Taking managerial action to correct deviations","Measuring actual performance","Comparing actual performance against a standard"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The control process starts by measuring actual performance, because managers need to know what is actually happening before they can compare it with anything. Option D is the second step and cannot happen until performance has been measured."}},{"itemId":"e2ec2951-20f8-58e0-987a-931abdd9a136","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cfd55642-f980-55f7-a959-dab59fabd3fb","sourceKey":"bank:AMS101:M101-T10N-019","parentItemId":null,"revision":1,"payload":{"prompt":"In the three-step control process, the second step is:","options":["Taking managerial action to correct deviations","Setting the organization's mission","Comparing actual performance against a standard","Measuring actual performance"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"After performance is measured, the second step is to compare it with the standard to see how big any deviation is. Option D is the first step, and option A is the third."}},{"itemId":"4e176311-65cc-5463-ab41-092e8d14f582","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0f036ba2-620e-5e8a-a8dd-961d95fd605d","sourceKey":"bank:AMS101:M101-T10N-020","parentItemId":null,"revision":1,"payload":{"prompt":"The third and final step in the control process is:","options":["Gathering information through oral reports","Measuring actual performance","Comparing actual performance against a standard","Taking managerial action to correct deviations or inadequate standards"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"The final step is taking managerial action, which may mean doing nothing, correcting actual performance or revising an inadequate standard. Option C is the second step; action follows only after the comparison shows what needs attention."}},{"itemId":"4470bf43-0662-569b-ac2a-9a61fb1e1252","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3bb94542-f48d-545e-8abe-11beafb147fe","sourceKey":"bank:AMS101:M101-T10N-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the steps of the control process?","options":["Compare, measure, take managerial action","Measure, take managerial action, compare","Take managerial action, measure, compare","Measure, compare, take managerial action"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Managers first measure actual performance, then compare it with the standard, and finally take managerial action. Option A cannot work because there is nothing to compare until performance has been measured."}},{"itemId":"fc90a2bc-c650-5802-a88d-75d2a723d8b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c77b026c-7690-505e-8a1d-d1ed27adbe22","sourceKey":"bank:AMS101:M101-T10N-022","parentItemId":null,"revision":1,"payload":{"prompt":"The control process assumes that standards already exist. Where do these standards come from?","options":["The structure created during organizing","The specific goals set during planning","The personal preferences of employees","The motivation provided during leading"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Standards are the specific goals set during planning, which is why the full sequence is set standards, measure, compare and take corrective action. Option A is wrong because organizing arranges work and people; it does not set the goals that performance is measured against."}},{"itemId":"2105b511-2dad-5d83-833a-20264f076d50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c22672e1-9d5b-540e-b055-532d63b3d6bc","sourceKey":"bank:AMS101:M101-T10N-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four common sources of information for measuring actual performance?","options":["Oral reports","Industry and company rankings","Personal observation","Statistical reports"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The four ways managers gather information to measure performance are personal observation, statistical reports, oral reports and written reports. Industry and company rankings are a way of measuring organizational performance as a whole, not one of these four."}},{"itemId":"fea2b44f-847a-5916-95d7-2dfeebcfec5f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab2e4263-ec7a-563a-a164-89004675d092","sourceKey":"bank:AMS101:M101-T10N-024","parentItemId":null,"revision":1,"payload":{"prompt":"How many common sources of information do managers use to measure actual performance?","options":["Four","Three","Six","Two"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"There are four: personal observation, statistical reports, oral reports and written reports. Option B is tempting because the control process itself has three steps, but that is a different list."}},{"itemId":"cbefa24b-cabf-5273-9101-ddae5852ebe0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d97c8d8-441b-576a-82cc-d693824bbb2b","sourceKey":"bank:AMS101:M101-T10N-025","parentItemId":null,"revision":1,"payload":{"prompt":"Management by walking around (MBWA) is another name for which source of measurement information?","options":["Written reports","Personal observation","Statistical reports","Oral reports"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"MBWA means the manager goes into the work area to see things first-hand, which is personal observation. Option D is tempting because MBWA involves talking with staff, but oral reports are information passed on through meetings, conversations or phone calls rather than the manager's own direct observation."}},{"itemId":"0af965f5-c3fe-5e08-bf92-a78e1b2a58f5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b825e910-7961-5500-bb80-060ea2d1898f","sourceKey":"bank:AMS101:M101-T10N-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which source of measurement information gives first-hand, unfiltered information and covers small details, but is open to personal bias, takes time and can look like distrust?","options":["Statistical reports","Personal observation","Written reports","Oral reports"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Personal observation gives the manager first-hand, unfiltered information, but it is time-consuming, subject to bias and employees may see it as a sign of distrust. Option D is wrong because oral reports are filtered by the person giving them."}},{"itemId":"60f3f591-4432-58bf-8462-d74ffd4a7cff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2428a1d0-a37e-5b99-aded-5a380f99f969","sourceKey":"bank:AMS101:M101-T10N-027","parentItemId":null,"revision":1,"payload":{"prompt":"A key weakness of oral reports as a source of measurement information is that they:","options":["Can look like distrust of employees","Take more time to prepare than other sources","Ignore subjective factors","Are filtered and leave no permanent record"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Oral reports are quick and allow feedback and tone, but the information is filtered by the speaker and there is no permanent record. Option B is the weakness of written reports, option C belongs to statistical reports and option A belongs to personal observation."}},{"itemId":"8762c502-287c-5361-a4a5-221b24db427d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a6e5042-e7a7-515e-b65f-bc86bc448982","sourceKey":"bank:AMS101:M101-T10N-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which source of measurement information is comprehensive, formal and easy to file and find, but takes more time to prepare?","options":["Statistical reports","Oral reports","Personal observation","Written reports"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Written reports are comprehensive and formal, and they are easy to file and retrieve, but they take more time to prepare. Option B is the opposite case: oral reports are quick but leave no permanent record."}},{"itemId":"94a5f15f-3361-59c9-a3df-0da23b6fe09a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cab8ca45-b0f3-5764-83ae-e7c39febdc0b","sourceKey":"bank:AMS101:M101-T10N-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which source of measurement information uses graphs and charts that are easy to see and show relationships, but provides limited facts and ignores subjective factors?","options":["Statistical reports","Written reports","Oral reports","Personal observation"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Statistical reports present data visually in graphs and charts, which makes relationships easy to see, but they give limited facts and leave out subjective factors. Option B is wrong because written reports are valued for being comprehensive, not for being visual summaries."}},{"itemId":"781ca1ff-6474-5fb3-8da0-b0e558ea3eac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"76254225-24f6-561c-8ca6-6aa0452439f1","sourceKey":"bank:AMS101:M101-T10N-030","parentItemId":null,"revision":1,"payload":{"prompt":"The medical director of a teaching hospital in Ibadan walks through the wards every morning to see for herself how patients are being attended to. Which source of measurement information is she using?","options":["Statistical reports","Personal observation","Written reports","Oral reports"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Going into the work area to see things first-hand is personal observation, also called management by walking around. Option D would apply if she relied on what nurses told her in meetings or phone calls, but here she is watching directly."}},{"itemId":"70118839-7e6d-5d9c-9e8b-6b15ee76afad","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cecef30e-3cfd-54f2-8410-120749c1a08f","sourceKey":"bank:AMS101:M101-T10N-031","parentItemId":null,"revision":1,"payload":{"prompt":"The acceptable limits of variance between actual performance and the standard are known as the:","options":["Range of variation","Balanced scorecard","Benchmark","Basic corrective action"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"The range of variation is the band of acceptable difference between actual performance and the standard; deviations inside it do not need action. Option C is a standard of excellence used for comparison, not the acceptable limits around a standard."}},{"itemId":"0ec2b609-9a80-51bd-b26c-7936d3503a58","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9ba7d97-2ede-56b2-b8f1-f064660281dd","sourceKey":"bank:AMS101:M101-T10N-032","parentItemId":null,"revision":1,"payload":{"prompt":"During the comparing step of control, when should a manager take action on a deviation?","options":["Whenever there is any deviation at all","Only when performance is above the standard","Never, because comparing is a passive step","Only when the deviation falls outside the range of variation"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Some variation is normal in all activities, so managers act only when a deviation falls outside the acceptable range of variation. Option A is wrong because reacting to every small difference would waste time on normal variation."}},{"itemId":"5efd29ca-0afa-5f6c-8d70-35c80a51610a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"edf26c3d-678f-5afa-95ff-d2ca36927a20","sourceKey":"bank:AMS101:M101-T10N-033","parentItemId":null,"revision":1,"payload":{"prompt":"When comparing actual performance with a standard, managers should pay attention to:","options":["Only the direction of the deviation","Neither, only whether a standard exists","Only the size of the deviation","Both the size and the direction of the deviation"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Managers should watch both how large a deviation is and whether performance is over or under the standard. Options C and A each cover only half of what matters."}},{"itemId":"59e87fea-5e3a-59ff-a512-f9e38e301e07","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4110d868-5aa8-502d-ae86-7f18a1fc3d8f","sourceKey":"bank:AMS101:M101-T10N-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three possible managerial actions in the control process?","options":["Correct actual performance","Revise the standard","Transfer the deviation to another unit","Do nothing"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"After comparing, a manager can do nothing, correct actual performance or revise the standard. Passing the problem to another unit is not one of these options; options D, A and B are the three recognised actions."}},{"itemId":"e98a06e0-ed61-5ace-a9e9-f71b38755420","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f864279e-de85-5bd8-a417-753f00c68079","sourceKey":"bank:AMS101:M101-T10N-035","parentItemId":null,"revision":1,"payload":{"prompt":"A bank branch in Lagos sets a target of 200 new accounts per month, with an acceptable range of 190 to 210. Last month it opened 196 accounts. What should the branch manager do?","options":["Correct actual performance by changing the sales strategy","Take basic corrective action to find the cause","Do nothing, because performance is within the acceptable range","Revise the standard downward to 196 accounts"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"196 accounts falls inside the 190 to 210 range of variation, so no action is needed and the manager should do nothing. Option D is wrong because the standard is fair and being met, and managers should be careful about lowering standards."}},{"itemId":"7fa4c7e0-c12f-535a-ae10-42198cf2ffca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"34335abc-8056-5a31-b56f-5de608bab2ff","sourceKey":"bank:AMS101:M101-T10N-036","parentItemId":null,"revision":1,"payload":{"prompt":"A sales team in Abuja has worked hard but keeps missing its target. On review, management finds the target was set far too high, without regard to market conditions. What is the most appropriate managerial action?","options":["Do nothing","Revise the standard","Redesign the salespeople's jobs","Take immediate corrective action"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"When a deviation comes from an unrealistic standard rather than poor performance, the right action is to revise the standard. Option C would mean correcting actual performance, which does not make sense when the real problem is the target itself."}},{"itemId":"a44df9a6-d2d4-551e-9b35-0983cc4e548e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"838ce3ff-f254-5a86-87bd-7c322f97da8a","sourceKey":"bank:AMS101:M101-T10N-037","parentItemId":null,"revision":1,"payload":{"prompt":"Corrective action that corrects an activity at once to get performance back on track is called:","options":["Revising the standard","Immediate corrective action","Basic corrective action","Feedforward control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Immediate corrective action fixes the problem now and gets performance back on track, treating the symptom. Option C is the commonly swapped term: basic corrective action first finds out how and why performance deviated."}},{"itemId":"2df795a1-5c98-55ee-ad4e-53a397dbc4aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"424789fd-20eb-5e1e-9bb7-6f2e22f732bb","sourceKey":"bank:AMS101:M101-T10N-038","parentItemId":null,"revision":1,"payload":{"prompt":"Corrective action that looks at how and why performance deviated and then corrects the source of the deviation is called:","options":["Doing nothing","Concurrent control","Basic corrective action","Immediate corrective action"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Basic corrective action investigates how and why the deviation happened and fixes the root cause, so the problem does not come back. Option D only fixes the problem at once without looking for the cause."}},{"itemId":"b8e4760b-f324-5c7d-9c73-6248099f0ca0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"86a88282-82cb-5d43-a206-d72f1606e0df","sourceKey":"bank:AMS101:M101-T10N-039","parentItemId":null,"revision":1,"payload":{"prompt":"Output at a beverage plant in Ota falls behind schedule, and the supervisor authorises overtime that same day to catch up, without investigating why output fell. This is an example of:","options":["Immediate corrective action","Basic corrective action","Revising the standard","Feedforward control"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Authorising overtime gets performance back on track at once without looking for the cause, so it is immediate corrective action. Option B would require the supervisor to find out why output fell and correct that root cause."}},{"itemId":"1082d73d-4c91-5304-a9ed-19f79414ce30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c244e507-9f01-5adb-af2b-0be5a84bc3f5","sourceKey":"bank:AMS101:M101-T10N-040","parentItemId":null,"revision":1,"payload":{"prompt":"After repeated delays on a production line in Ota, the plant manager investigates, finds that a poorly designed machine is the cause, and replaces it so the delays do not recur. This is an example of:","options":["Immediate corrective action","Doing nothing","Basic corrective action","Revising the standard"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The manager looked at why performance deviated and corrected the root cause of the problem, which is basic corrective action. Option A would have been a quick fix, such as overtime, that leaves the faulty machine in place."}},{"itemId":"b9aeb40c-b964-5917-8990-2cf67c10d5b5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"50b38df6-9f22-51ff-a322-95dbab233648","sourceKey":"bank:AMS101:M101-T10N-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes immediate corrective action from basic corrective action?","options":["Immediate action treats the symptom; basic action treats the cause","Both treat only the cause of the deviation","Immediate action treats the cause; basic action treats the symptom","Basic action is taken before the activity begins; immediate action is taken after"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Immediate corrective action fixes the problem now, treating the symptom, while basic corrective action finds and corrects the underlying problem, treating the cause. Option C simply swaps the two, which is a common exam trap."}},{"itemId":"9c4d7de0-0e40-556b-90bc-a87706859ade","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48a8868e-ac2f-5c6a-9b3c-ac21cb9b57aa","sourceKey":"bank:AMS101:M101-T10N-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of correcting actual performance?","options":["Changing pay or training, or redesigning jobs","Collecting oral reports from supervisors","Lowering a target that proved unrealistic","Leaving things as they are because results are within range"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Correcting actual performance can involve changing strategy, structure, pay or training, or redesigning jobs. Option D is doing nothing, and option C is revising the standard, which are the other two managerial actions."}},{"itemId":"6db981aa-e609-57a1-896d-53a893527d73","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a475430d-88ce-5263-89e2-ff7345738211","sourceKey":"bank:AMS101:M101-T10N-043","parentItemId":null,"revision":1,"payload":{"prompt":"When employees miss a standard, their first reaction is often to blame the standard. What should a manager do if the standard is fair?","options":["Remove the standard altogether","Hold to the standard and explain why it is fair","Do nothing and ignore the deviation","Lower the standard immediately to restore morale"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Managers should be careful before revising a standard downward; if it is fair, they should hold to it and explain why. Option D is the tempting response, but lowering a fair standard just because employees complain weakens control."}},{"itemId":"56620c48-9155-5926-9817-c3d1232cf89f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0f444eb-55e4-509f-bcd7-a3d31de5cdec","sourceKey":"bank:AMS101:M101-T10N-044","parentItemId":null,"revision":1,"payload":{"prompt":"Why is deciding what to measure considered more critical than deciding how to measure?","options":["Because measurement methods never affect results","Because what is measured determines what employees will work hard at","Because only financial measures matter","Because employees ignore what is measured"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"What managers choose to measure sends a signal about what matters, so it decides what employees work hard at. Option D is the reverse of the truth: employees pay close attention to whatever is measured."}},{"itemId":"07f038d5-27f5-555e-b637-9a027130b7b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"81d3a09f-31c3-531d-9fce-30e12da698cc","sourceKey":"bank:AMS101:M101-T10N-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following control criteria can be applied to any work unit, whatever its job?","options":["Absenteeism rate","Units produced per shift","Number of patients treated","Sales made per month"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Some criteria fit any unit, such as employee satisfaction, turnover, absenteeism and keeping costs within budget. Options C, B and D depend on the particular job, so they apply only to units like hospitals, factories or sales teams."}},{"itemId":"cf4b8035-ccc5-5b45-87c1-db91efc922cd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"09ea830f-35fa-5130-9511-abe106fa3961","sourceKey":"bank:AMS101:M101-T10N-046","parentItemId":null,"revision":1,"payload":{"prompt":"When a unit's output is hard to count, what should managers do about setting measures?","options":["Use only financial ratios","Abandon control for that unit","Measure only the number of hours worked","Use subjective measures, which are better than no standard at all"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"When output is hard to quantify, managers should use subjective measures, because these are better than having no standard. Option B is wrong because every unit still needs some way of being controlled."}},{"itemId":"240f7c15-a3b1-5394-a111-9060686c84f1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ede5501c-4bba-599f-8f9a-028c46bd7b99","sourceKey":"bank:AMS101:M101-T10N-047","parentItemId":null,"revision":1,"payload":{"prompt":"Predictive control is another name for:","options":["Strategic control","Feedforward control","Concurrent control","Feedback control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Feedforward or predictive control helps managers foresee problems before they happen, so action can be taken in advance. Option D is the opposite: feedback control looks at data after the activity is completed."}},{"itemId":"56a69b6b-1493-5069-a54f-82d07e72d9c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8fb46223-67f7-5245-b8f4-d6e8e39ecab9","sourceKey":"bank:AMS101:M101-T10N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of control takes place while a work activity is in progress, correcting problems as they happen?","options":["Strategic control","Concurrent control","Feedback control","Feedforward control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Concurrent control happens during the activity and aims to correct problems as they occur. Option D takes place before the activity, and option C after it is completed."}},{"itemId":"1f17904e-77ec-54e8-9863-7ce8c25b53a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"68ca0b32-e519-5d5b-b56a-aa0974f44af1","sourceKey":"bank:AMS101:M101-T10N-049","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback control is best described as:","options":["Foreseeing problems and acting before they occur","Gathering performance data and using it to assess whether goals are being met","Watching employees and correcting problems as they occur","Tracking strategy as it is implemented to keep the organization on course"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Feedback control gathers performance data after an activity and uses it to judge whether goals were met, acting as a monitoring and evaluation process. Option A describes feedforward control, option C concurrent control and option D strategic control."}},{"itemId":"72bd075e-b019-565c-8121-f22fcf6c2227","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"19156067-5e3d-5453-9a72-ecaab84a2312","sourceKey":"bank:AMS101:M101-T10N-050","parentItemId":null,"revision":1,"payload":{"prompt":"A food manufacturer in Ota inspects every delivery of flour and sugar before it enters production. Which type of control is this?","options":["Feedback control","Concurrent control","Strategic control","Feedforward control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Inspecting flour and sugar deliveries before production starts is meant to prevent problems before they occur, which makes it feedforward control. Option A would apply if the firm checked the finished products after production."}},{"itemId":"b49be445-0101-585c-aa46-691ee0bfec48","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"240aba72-81df-55bd-9556-c2d063115244","sourceKey":"bank:AMS101:M101-T10N-051","parentItemId":null,"revision":1,"payload":{"prompt":"A private hospital in Abuja services its generators and theatre equipment on a fixed schedule so that they do not break down during surgery. This is an example of:","options":["Feedforward control","Immediate corrective action","Concurrent control","Feedback control"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Servicing machines before they break down is a preventive step taken before problems arise, which is feedforward control. Option D would only come into play after a breakdown had already happened."}},{"itemId":"540e81c7-ac59-5516-b777-a931ce90d9d2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ad3ab640-e940-5391-8214-4472484474c4","sourceKey":"bank:AMS101:M101-T10N-052","parentItemId":null,"revision":1,"payload":{"prompt":"In the banking hall of a Lagos bank, the operations supervisor watches the cashiers at work and corrects errors as soon as she sees them. Which type of control is she using?","options":["Feedback control","Concurrent control","Strategic control","Feedforward control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Watching employees and correcting problems as they occur is direct supervision, the best-known form of concurrent control. Option A would involve reviewing results after the day's work was finished."}},{"itemId":"841784a9-b48d-5723-866f-0b6eab156ada","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc236ac5-d269-5341-a808-053af2bfeaf7","sourceKey":"bank:AMS101:M101-T10N-053","parentItemId":null,"revision":1,"payload":{"prompt":"At the end of the semester, a university department in Lagos analyses examination results to judge whether its teaching goals were met. Which type of control is this?","options":["Concurrent control","Strategic control","Feedback control","Feedforward control"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Examination results are gathered after the activity is completed and used to assess whether goals were met, which is feedback control. Option D would mean acting before teaching starts to prevent problems."}},{"itemId":"3641e3c9-3d03-57ea-83f5-c74892ba2c48","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"788cb318-c700-5143-bdfd-b753af4837ad","sourceKey":"bank:AMS101:M101-T10N-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of feedback control?","options":["Inspecting raw materials before production","Reviewing end-of-year financial statements","Training staff before they start work","Directly supervising staff as they work"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"End-of-year financial statements look back at completed activity to judge performance, which is feedback control. Options A and C are feedforward controls, and option D is concurrent control."}},{"itemId":"c59562b1-b8c4-5c17-a740-f180daf7e41d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ec4a5e46-a7a3-5be2-b080-fe33c5d65e84","sourceKey":"bank:AMS101:M101-T10N-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of control is considered the most desirable, because it prevents damage before it happens?","options":["Strategic control","Feedback control","Concurrent control","Feedforward control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Feedforward control is the most desirable type because it stops problems before any damage is done. Option B is the most popular type, not the most desirable, and its weakness is that the damage has often already happened."}},{"itemId":"60c5ee0c-433d-5d2d-82c1-385c04c98e86","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"42db137f-b074-5fee-bd77-4d1674e92499","sourceKey":"bank:AMS101:M101-T10N-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of control is the most popular in organizations?","options":["Feedback control","Feedforward control","Strategic control","Concurrent control"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Feedback control is the most widely used type of control. Option B is tempting because it is the most desirable type, but it needs timely, accurate information that is often hard to get, so it is used less."}},{"itemId":"34b3854c-3198-590c-a84a-a80a09d3f133","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f4d5fe94-8757-5dd2-9201-bbf3651e6bab","sourceKey":"bank:AMS101:M101-T10N-057","parentItemId":null,"revision":1,"payload":{"prompt":"The best-known form of concurrent control is:","options":["Inspection of raw materials","Customer satisfaction surveys","Direct supervision","End-of-year financial statements"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Direct supervision, where managers watch employees and correct problems as they occur, is the best-known form of concurrent control. Option A is feedforward control, while options B and D are feedback controls."}},{"itemId":"732446e6-7f5b-56d9-8512-b53d3240ce43","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"41432836-dcb2-54d3-bbdb-941bac808750","sourceKey":"bank:AMS101:M101-T10N-058","parentItemId":null,"revision":1,"payload":{"prompt":"Management by walking around (MBWA), in which the manager is in the work area talking directly with employees, is a form of which type of control?","options":["Feedback control","Feedforward control","Strategic control","Concurrent control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"MBWA puts the manager in the work area while work is going on, so it is a form of concurrent control. Option A is wrong because feedback control relies on data collected after the activity is finished."}},{"itemId":"93c66c81-279e-5054-88d2-3f986b34fe0a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"882c0dfb-2c2b-5aa7-9777-3f68e91232b1","sourceKey":"bank:AMS101:M101-T10N-059","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difficulty with feedforward control?","options":["The damage is already done by the time information arrives","It reduces employee motivation","It needs timely, accurate information, which is often hard to get","It can only be used by top managers"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Feedforward control requires timely and accurate information in advance, and that is often hard to obtain. Option A is the main weakness of feedback control, not feedforward control."}},{"itemId":"0126dc68-1c6b-5370-9ea0-86de02d7f11d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"52cb224b-5bd5-5710-9262-6f531bd440d8","sourceKey":"bank:AMS101:M101-T10N-060","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main weakness of feedback control?","options":["By the time the manager has the information, the damage is already done","It needs information before the activity begins","It requires constant direct supervision","It cannot be used to assess whether goals were met"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Because feedback control works with information gathered after the activity, the damage has usually happened by the time managers learn of it. Option B describes the challenge of feedforward control instead."}},{"itemId":"2300a91d-42a6-588b-b759-ffd56111f48c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a790bb0-2c6e-542f-9bf6-c1ddb0b8342b","sourceKey":"bank:AMS101:M101-T10N-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of feedback control?","options":["It tells managers how effective their planning was","It needs no performance data","It prevents problems before they occur","It corrects problems while they are happening"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Feedback control has two advantages: it shows managers how effective their planning was, and it can raise motivation. Option C is the strength of feedforward control, and option D is concurrent control."}},{"itemId":"7de17c03-bfd4-5d14-843f-fed3c35cfcca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b8c3c671-5b6f-500b-8192-417e4b2a6bea","sourceKey":"bank:AMS101:M101-T10N-062","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback control can raise employee motivation because:","options":["It removes the need for standards","It prevents all mistakes before they happen","People want to know how well they performed","It replaces supervision entirely"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Feedback gives people information on how well they did, and they want that information, so it can raise motivation. Option B describes the aim of feedforward control, not why feedback motivates."}},{"itemId":"f66aba79-897a-5d9d-bd66-2a37e290c0be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"178e02a9-7ca6-5a51-af6f-b9bc7c57a07d","sourceKey":"bank:AMS101:M101-T10N-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of control ensures that the organization is moving in the right direction by tracking the strategy as it is being implemented?","options":["Budgetary control","Feedforward control","Strategic control","Feedback control"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Strategic control tracks strategy during implementation to detect problem areas or potential threats so that remedial action can be taken. Option D only looks back after the activity is completed, rather than tracking the strategy while it is being rolled out."}},{"itemId":"35323241-2fff-51c6-95d8-1d6e66082969","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7693095c-ff92-549e-83d9-e517ed1da814","sourceKey":"bank:AMS101:M101-T10N-064","parentItemId":null,"revision":1,"payload":{"prompt":"The board of a Lagos fintech company reviews progress on its expansion strategy every quarter while the strategy is being rolled out, looking for problem areas and threats so it can take remedial action. This is an example of:","options":["Feedforward control","Feedback control","Immediate corrective action","Strategic control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Tracking a strategy while it is being implemented to detect problems and threats is strategic control. Option B is wrong because the board is not waiting until the strategy is completed to evaluate it."}},{"itemId":"b3a711d3-93e4-547d-bcc1-1cd5af02f2d8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2109dfba-8348-5943-86cf-8f76c833d133","sourceKey":"bank:AMS101:M101-T10N-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which option correctly matches each type of control with when it happens?","options":["Feedforward: before; concurrent: during; feedback: after","Feedforward: during; concurrent: before; feedback: after","Feedforward: after; concurrent: during; feedback: before","Feedforward: before; concurrent: after; feedback: during"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Feedforward control happens before the activity, concurrent control during it and feedback control after it is completed. Option C swaps feedforward and feedback, which is the most common mix-up."}},{"itemId":"10d1ecec-f9e3-5ff5-bdfe-9296c7de72ba","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d966afe-6780-562d-b2ed-f37e031a08e4","sourceKey":"bank:AMS101:M101-T10N-066","parentItemId":null,"revision":1,"payload":{"prompt":"The total output of goods or services divided by the inputs needed to produce that output is called:","options":["Organizational effectiveness","Organizational productivity","Return on investment","Industry and company rankings"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Organizational productivity is total output divided by the inputs used to produce it. Option A is about how appropriate goals are and how well they are being met, not an output-to-input ratio."}},{"itemId":"f26542f5-edb0-5c99-940c-f1574bc7450e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"11d22808-0d19-53a8-892a-101b8abae768","sourceKey":"bank:AMS101:M101-T10N-067","parentItemId":null,"revision":1,"payload":{"prompt":"A measure of how appropriate an organization's goals are and how well those goals are being met is:","options":["Range of variation","Organizational productivity","Industry and company rankings","Organizational effectiveness"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Organizational effectiveness looks at whether the goals are the right ones and how well they are being achieved. Option B compares outputs with inputs and says nothing about whether the goals are appropriate."}},{"itemId":"fc69499b-b559-57c1-a06a-0024ac074785","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"53c3a98f-3c24-5cf0-aa9a-b52e669cbfc1","sourceKey":"bank:AMS101:M101-T10N-068","parentItemId":null,"revision":1,"payload":{"prompt":"Published lists that rank organizations on set measures are a way of measuring organizational performance known as:","options":["Organizational effectiveness","Benchmarking","Industry and company rankings","Organizational productivity"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Industry and company rankings are published lists that rank organizations on set measures. Option B is tempting, but benchmarking is a search for best practices to copy, not a published ranking."}},{"itemId":"81bcb9b7-acd1-52e6-a0c9-18602863eb54","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b659e0c-70ea-5320-9fc6-947583f956fd","sourceKey":"bank:AMS101:M101-T10N-069","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the measures of organizational performance?","options":["Range of variation","Organizational productivity","Organizational effectiveness","Industry and company rankings"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Organizational performance is measured through productivity, effectiveness and industry and company rankings. The range of variation is part of the comparing step of the control process, describing acceptable limits around a standard."}},{"itemId":"771a14c2-cb94-5015-aa76-9220f545c1f2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30096afa-fde8-50e6-8414-18cf743ea939","sourceKey":"bank:AMS101:M101-T10N-070","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational performance refers to:","options":["The combined result of all the organization's work activities","The end result of a single employee's task","The acceptable limits around a standard","The number of employees in the organization"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Performance is the end result of an activity, and organizational performance is the combined result of all the organization's work activities. Option B is too narrow because it covers only one person's task."}},{"itemId":"cd251fe3-9ba5-5fde-8859-de555a393e14","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3da662e7-853b-5395-b447-1af54b3e5121","sourceKey":"bank:AMS101:M101-T10N-071","parentItemId":null,"revision":1,"payload":{"prompt":"An organization becomes more productive when it:","options":["Hires more staff regardless of output","Produces less output with more inputs","Uses more inputs to produce the same output","Gets more output from the same or fewer inputs"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Productivity is output divided by input, so getting more output from the same or fewer inputs raises it. Option C would lower productivity because the extra inputs add nothing to output."}},{"itemId":"a7c31c2a-78c2-5f86-9600-5ba45d5a3399","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"508ce594-4bb6-5a09-b447-ecaa94e58204","sourceKey":"bank:AMS101:M101-T10N-072","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of feedforward control?","options":["Running a customer satisfaction survey after a sale","Inspecting raw materials before production","Servicing machines before they break down","Training staff before they start work"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"A survey after the sale gathers information once the activity is over, so it is feedback control. Options B, D and C all act before problems can occur, which makes them feedforward controls."}},{"itemId":"084917ad-38e4-572b-ad70-5e2f50809e3b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c5c93a86-9bc5-5383-b72c-1b94acf6beaa","sourceKey":"bank:AMS101:M101-T10N-073","parentItemId":null,"revision":1,"payload":{"prompt":"Liquidity ratios test an organization's ability to:","options":["Use its assets efficiently","Meet its current (short-term) debts","Generate profits from its assets","Use debt to finance its assets"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Liquidity ratios measure whether the organization can pay its short-term debts as they fall due. Option D is what leverage ratios test, option A is activity ratios and option C is profitability ratios."}},{"itemId":"ce8e73ea-5d80-5dbc-b0e1-5affb36c66f6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b8577c37-2c42-5405-be04-9a736bdbea56","sourceKey":"bank:AMS101:M101-T10N-074","parentItemId":null,"revision":1,"payload":{"prompt":"The current ratio is calculated as:","options":["Sales divided by inventory","Total debt divided by total assets","Current assets divided by current liabilities","Net profit after taxes divided by total sales"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The current ratio, a liquidity ratio, divides current assets by current liabilities to show whether short-term debts can be met. Option B is the debt to assets ratio, a leverage ratio."}},{"itemId":"4a07e3bc-f156-55d7-8625-b97eff870eb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1424281b-5cce-5acd-9453-3679f98886d1","sourceKey":"bank:AMS101:M101-T10N-075","parentItemId":null,"revision":1,"payload":{"prompt":"The acid test ratio, calculated as current assets minus inventories divided by current liabilities, belongs to which group of financial ratios?","options":["Activity","Profitability","Liquidity","Leverage"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The acid test is a liquidity ratio because it tests the ability to meet current debts, using current assets without inventories. Option B is about how assets generate profit, which the acid test does not measure."}},{"itemId":"b0ccbd37-fa56-592f-82c8-1c8299bef36f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d80ed97-2ee0-5604-912a-f18ac7793cea","sourceKey":"bank:AMS101:M101-T10N-076","parentItemId":null,"revision":1,"payload":{"prompt":"Leverage ratios test an organization's:","options":["Efficiency in using its assets","Use of debt to finance assets and its ability to pay interest","Ability to meet current debts","Ability to generate profits from sales"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Leverage ratios look at how far the organization uses debt to finance its assets and whether it can cover its interest charges. Option C describes liquidity ratios, which focus on short-term debts."}},{"itemId":"726c2949-37c8-53e7-8e9e-b85afed11da3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6bc7c68f-1c3a-53cc-886c-2ba7bdc7662f","sourceKey":"bank:AMS101:M101-T10N-077","parentItemId":null,"revision":1,"payload":{"prompt":"Times interest earned, calculated as profits before interest and taxes divided by total interest charges, is which type of ratio?","options":["Liquidity ratio","Activity ratio","Leverage ratio","Profitability ratio"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Times interest earned is a leverage ratio because it measures the ability to pay interest on debt. Option D is tempting because profits appear in the formula, but the purpose of the ratio is to test debt-servicing ability."}},{"itemId":"e6e1b54c-cc81-57ac-b113-1c2c22802e11","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"035a3ced-c0b5-5c7e-a923-49bfe06f3367","sourceKey":"bank:AMS101:M101-T10N-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which group of financial ratios tests how efficiently a firm uses its assets?","options":["Activity ratios","Leverage ratios","Liquidity ratios","Profitability ratios"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Activity ratios, such as inventory turnover and total asset turnover, test how efficiently the firm uses its assets. Option D is close but focuses on how assets generate profits rather than on efficient use as such."}},{"itemId":"db682921-d4ab-5e5e-a713-9bfe2fd07f80","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc358cbe-cd07-590f-99ab-cd6d39853cd9","sourceKey":"bank:AMS101:M101-T10N-079","parentItemId":null,"revision":1,"payload":{"prompt":"Inventory turnover is calculated as:","options":["Sales divided by inventory","Net profit after taxes divided by total assets","Total debt divided by total assets","Current assets divided by current liabilities"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Inventory turnover, an activity ratio, divides sales by inventory. Option B is return on investment, a profitability ratio."}},{"itemId":"5729e40e-c9f5-525c-afab-79781207b1dc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aae3eb43-9c45-5bbc-acb6-69955208fcbb","sourceKey":"bank:AMS101:M101-T10N-080","parentItemId":null,"revision":1,"payload":{"prompt":"Total asset turnover (sales divided by total assets) belongs to which group of ratios?","options":["Liquidity","Profitability","Leverage","Activity"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Total asset turnover shows how efficiently the firm uses all its assets to generate sales, so it is an activity ratio. Option B is wrong because profitability ratios use net profit, not sales, in the numerator."}},{"itemId":"2bfd282e-a3ad-5065-a2cc-e99936b26ce3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bbab4f5a-faab-5fc3-ac7a-6c00b018369e","sourceKey":"bank:AMS101:M101-T10N-081","parentItemId":null,"revision":1,"payload":{"prompt":"Return on investment is calculated as:","options":["Net profit after taxes divided by total assets","Total debt divided by total assets","Net profit after taxes divided by total sales","Sales divided by total assets"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Return on investment is a profitability ratio that divides net profit after taxes by total assets. Option C is the profit margin on sales, a different profitability ratio."}},{"itemId":"3a3413c4-83c0-52bf-8810-485d4baddebe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"01be75a5-f243-5b30-ac7b-40f9f4f8b8d8","sourceKey":"bank:AMS101:M101-T10N-082","parentItemId":null,"revision":1,"payload":{"prompt":"Profit margin on sales is calculated as:","options":["Net profit after taxes divided by total sales","Sales divided by inventory","Current assets divided by current liabilities","Net profit after taxes divided by total assets"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Profit margin on sales divides net profit after taxes by total sales and is a profitability ratio. Option D is return on investment, which uses total assets rather than total sales."}},{"itemId":"5f2558a9-c381-5ad4-82f8-b89e76ff9bef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1fdf9755-6588-5bdf-af8e-df7f1663fa2a","sourceKey":"bank:AMS101:M101-T10N-083","parentItemId":null,"revision":1,"payload":{"prompt":"How many groups of financial ratios are commonly used as control tools?","options":["Six","Three","Two","Four"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"The four groups are liquidity, leverage, activity and profitability ratios. Option B is wrong because it leaves out one of these groups."}},{"itemId":"9c175c41-2215-5146-b31b-4fa30c82be33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0add21c8-3113-549e-926e-0ce07d58ac40","sourceKey":"bank:AMS101:M101-T10N-084","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four groups of financial ratios used for control?","options":["Activity ratios","Growth ratios","Liquidity ratios","Leverage ratios"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The four groups are liquidity, leverage, activity and profitability. Growth ratios are not one of them, while options C, D and A are all part of the list."}},{"itemId":"5768d71d-17bc-59f9-aa97-7963e77eaa94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"23be4e37-f6b7-5bc2-bdfc-9ae8728619a6","sourceKey":"bank:AMS101:M101-T10N-085","parentItemId":null,"revision":1,"payload":{"prompt":"The finance manager of a manufacturing company in Ikeja wants to know whether the company can pay the suppliers whose bills are due next month. Which group of ratios should she examine?","options":["Profitability ratios","Activity ratios","Liquidity ratios","Leverage ratios"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Bills due next month are short-term debts, and liquidity ratios test the ability to meet current debts. Option D is about the use of debt to finance assets and paying interest, a longer-term concern."}},{"itemId":"af8d39ab-50bb-5998-940e-6e6f1d2d1eb6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5b555639-28cf-53a8-8e67-82d43e3d217d","sourceKey":"bank:AMS101:M101-T10N-086","parentItemId":null,"revision":1,"payload":{"prompt":"A budget is best described as:","options":["Neither a planning nor a control tool","A planning tool only","A control tool only","Both a planning tool and a control tool"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"A budget is used in planning to allocate resources and in control to provide quantitative standards against which resource use can be compared. Options B and C each describe only half of its role."}},{"itemId":"918d2cac-a0d9-5c43-af8b-4c74b738f049","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cd773c55-fa8c-5d29-a69d-3261b91cae32","sourceKey":"bank:AMS101:M101-T10N-087","parentItemId":null,"revision":1,"payload":{"prompt":"When used as a control tool, a budget mainly provides managers with:","options":["A record of employee theft","Quantitative standards to compare resource use against","A measure of customer satisfaction","A list of best practices from competitors"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"In control, a budget gives quantitative standards, so managers can compare how resources are actually used with what was planned. Option D describes benchmarking, not budgeting."}},{"itemId":"ae7683df-edaf-5b7a-97cd-2537c2352052","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d46fd6e1-885f-57f0-ba5b-daf9cd7e036c","sourceKey":"bank:AMS101:M101-T10N-088","parentItemId":null,"revision":1,"payload":{"prompt":"A system that gives managers needed information on a regular basis is called a:","options":["Management information system (MIS)","Service profit chain","Balanced scorecard","Budget"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"A management information system provides managers with the information they need on a regular basis, turning raw data into information. Option C is a performance measurement tool covering four areas, not a regular information supply system."}},{"itemId":"37199fd7-2570-5a68-887e-90ca5cfe5188","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a117242e-b640-530e-b00a-5ba01e81a08b","sourceKey":"bank:AMS101:M101-T10N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Raw, unanalysed facts are referred to as:","options":["Data","Standards","Information","Benchmarks"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Data are raw, unanalysed facts, while information is data that has been analysed and processed. Option C is the common confusion, since an MIS turns data into information."}},{"itemId":"604b5643-8709-5b52-bea0-ed303dd365a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2fd9b47d-33c9-5da1-8fce-23bd72769cb4","sourceKey":"bank:AMS101:M101-T10N-090","parentItemId":null,"revision":1,"payload":{"prompt":"Information controls work in two ways. Which pair correctly identifies them?","options":["As a liquidity ratio and as a leverage ratio","As a tool to control other activities and as an area to be controlled","As a planning tool and as a leading tool","As a feedforward control and as a strategic control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Information is a tool for controlling other activities, giving managers the right information at the right time, and it is also something that must itself be controlled and protected. Option D names types of control, not the two roles of information controls."}},{"itemId":"f7101afe-3cbc-5de5-b9fe-73edc8daa161","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cbecb34b-a782-5adb-b7c3-a6af3d2d0985","sourceKey":"bank:AMS101:M101-T10N-091","parentItemId":null,"revision":1,"payload":{"prompt":"When information is treated as an area to be controlled, which tools are used to protect it?","options":["Budgets and benchmarks","Current ratios and acid tests","Encryption, firewalls and data back-ups","Direct supervision and MBWA"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"As an area to control, information must be protected with tools such as encryption, firewalls and data back-ups. Option A lists control tools for other activities, not protections for the information itself."}},{"itemId":"ff1e025a-72b8-573e-8359-b18fe7473afe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"99ef5715-91d5-583a-a692-b74f793a6cd2","sourceKey":"bank:AMS101:M101-T10N-092","parentItemId":null,"revision":1,"payload":{"prompt":"The balanced scorecard measures performance in four areas. Which of the following is NOT one of them?","options":["Customer","Financial","Internal processes","Supplier relations"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"The four areas of the balanced scorecard are financial, customer, internal processes, and people/innovation/growth assets. Supplier relations is not one of them, while options B, A and C are."}},{"itemId":"eb87cb36-47df-5fae-a640-d62224b04b40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"160eed45-70b2-5551-8829-dba2d8fcbf47","sourceKey":"bank:AMS101:M101-T10N-093","parentItemId":null,"revision":1,"payload":{"prompt":"The balanced scorecard was developed by:","options":["W. Edwards Deming","Henri Fayol","Abraham Maslow","Robert Kaplan and David Norton"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Robert Kaplan and David Norton developed the balanced scorecard as a way of measuring performance beyond finance. Option A, Deming, is linked with quality and the 14 points, not the balanced scorecard."}},{"itemId":"69bb71d0-1426-5594-b790-c4dccfaa1173","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"816b44c5-c0b9-5e23-8ea9-e9388a3de67e","sourceKey":"bank:AMS101:M101-T10N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Why do organizations use the balanced scorecard instead of relying on financial results alone?","options":["Financial results are never accurate","Financial results alone can hide weak customer service or poor staff development","The balanced scorecard measures only profit","The balanced scorecard replaces the need for goals"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The balanced scorecard looks at more than finance, because good financial figures can hide problems in customer service or staff development. Option C is wrong because the whole point of the tool is to go beyond financial measures."}},{"itemId":"138a07d6-1e47-5d49-999f-eae65f91049b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b28c5eb-951f-5047-8f45-27c1b39f9048","sourceKey":"bank:AMS101:M101-T10N-095","parentItemId":null,"revision":1,"payload":{"prompt":"The search for the best practices among competitors or noncompetitors that lead to superior performance is known as:","options":["Total quality management","Benchmarking","Value chain management","Balanced scorecard"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Benchmarking is the search for best practices, from competitors or noncompetitors, that lead to superior performance. Option D is a multi-area performance measurement tool and does not involve searching outside for best practices."}},{"itemId":"a9a5d023-9fb4-5075-b373-123fa69096e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"57a55801-481b-5cf4-9c66-bbd3a21f0ba4","sourceKey":"bank:AMS101:M101-T10N-096","parentItemId":null,"revision":1,"payload":{"prompt":"In benchmarking, a benchmark is:","options":["A list of company rankings","The acceptable limits of variance around a standard","A budget for capital spending","The standard of excellence used for comparison"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"A benchmark is the standard of excellence against which an organization compares itself. Option B describes the range of variation, which belongs to the comparing step of control."}},{"itemId":"f7882a19-f1dd-5927-828b-5f2b52fd4e11","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03300b59-5a70-501d-af1d-98bc294af5dc","sourceKey":"bank:AMS101:M101-T10N-097","parentItemId":null,"revision":1,"payload":{"prompt":"Which company is credited with the first major benchmarking effort in the United States?","options":["General Electric","Toyota","Xerox","Ford"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Xerox is credited with the first major benchmarking effort in the United States. The other companies named are well known, but none of them is credited with this first effort."}},{"itemId":"f5d9e2ff-5e63-540c-a0f2-5ce001d4e8ad","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a5dc4d27-eebc-51d3-b3fe-d59223bfaa28","sourceKey":"bank:AMS101:M101-T10N-098","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank identifies the best practices of its top-performing branch in Victoria Island and introduces them in all its other branches. This is an example of:","options":["Feedforward control","The balanced scorecard","Corporate governance","Internal benchmarking"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Benchmarking can be done inside the organization by copying the best practices of one unit in others, which is what the bank is doing. Option B is a tool for measuring performance in four areas, not for spreading best practices between branches."}},{"itemId":"2bdca8ce-62b7-5b55-bbe5-363cf09d20e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a6d4687f-613f-5096-9ab7-60ba63191f6f","sourceKey":"bank:AMS101:M101-T10N-099","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four contemporary control issues?","options":["Workplace concerns such as privacy and employee theft","Corporate governance","Setting the organization's mission statement","Adjusting controls for cross-cultural differences"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The four contemporary control issues are cross-cultural differences and global turmoil, workplace concerns, controlling customer interactions and corporate governance. Writing a mission statement is a planning task, not a control issue."}},{"itemId":"02930a27-96e8-58fa-8cc8-ee3252287c65","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4553e79-907e-5c64-b61e-0fb74deb9d56","sourceKey":"bank:AMS101:M101-T10N-100","parentItemId":null,"revision":1,"payload":{"prompt":"Why do controls in an organization's distant global units tend to be more formal?","options":["Foreign employees are less trustworthy","Formal controls are cheaper everywhere","Managers cannot observe work directly in distant units","Global units have no standards to meet"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"In distant global units managers cannot watch work directly, so they rely on more formal controls. Option A is wrong and unfair; the reason is physical distance, not the employees themselves."}},{"itemId":"5acc953d-367d-5310-a357-a96a4bc90daf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bbbb6092-65c3-5f44-bcc7-970231606ff5","sourceKey":"bank:AMS101:M101-T10N-101","parentItemId":null,"revision":1,"payload":{"prompt":"The unauthorised taking of company property by employees for their own use is called:","options":["Workplace privacy","Corporate governance","Employee theft","Workplace violence"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Employee theft is the unauthorised taking of company property by employees for their own personal use. Option A concerns employers monitoring email and internet use, not employees taking property."}},{"itemId":"94731d99-5fb1-5c83-8acc-f86f0d3c7e1b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"75a98ea9-592e-547c-a55b-612c63d4bcbf","sourceKey":"bank:AMS101:M101-T10N-102","parentItemId":null,"revision":1,"payload":{"prompt":"To prevent theft from its drug store, a hospital in Enugu screens job applicants carefully and publishes a clear policy on who may enter the store. Which type of control is the hospital using against employee theft?","options":["Feedback control","Strategic control","Concurrent control","Feedforward control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Careful hiring and clear policies act before any theft happens, so they are feedforward controls. Option A would involve fair treatment and supervision while work is under way, and option B would be investigation after theft has occurred."}},{"itemId":"680a34fc-680a-5fd3-8648-a87790404084","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"27caa3fc-d559-59df-bf73-19b3c0bf2830","sourceKey":"bank:AMS101:M101-T10N-103","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket in Port Harcourt investigates a stock loss and follows up with the staff involved after the theft has occurred. Which type of control against employee theft is this?","options":["Feedforward control","Strategic control","Concurrent control","Feedback control"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Investigation and follow-up after a theft deal with the problem once it has happened, so they are feedback controls. Option A would mean steps like careful hiring and clear policies taken before any theft."}},{"itemId":"1c805368-2cce-5c69-b22e-0f877232083e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"862563f4-5102-5fb5-82ef-ccddc2d4df3b","sourceKey":"bank:AMS101:M101-T10N-104","parentItemId":null,"revision":1,"payload":{"prompt":"The sequence from employees to customers to profit is known as the:","options":["Supply chain","Value chain","Service profit chain","Balanced scorecard"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The service profit chain links satisfied, productive employees to better service, customer satisfaction and loyalty, and then to revenue and profit. Option B is the series of work activities that add value from raw inputs to finished product."}},{"itemId":"7fe112c3-2965-5ecc-980b-1a7e379f602a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"29d1ab9d-2cf4-5f96-adff-45d18446cb20","sourceKey":"bank:AMS101:M101-T10N-105","parentItemId":null,"revision":1,"payload":{"prompt":"According to the service profit chain, what is the correct order of links?","options":["Customer loyalty, profit, better service, satisfied employees","Better service, profit, satisfied employees, customer loyalty","Profit, customer loyalty, satisfied employees, better service","Satisfied employees, better service, customer loyalty, profit"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"The chain starts with satisfied, productive employees, who give better service, which builds customer satisfaction and loyalty, which brings revenue and profit. Option C reverses the chain by putting profit first."}},{"itemId":"bace2e11-582e-51c9-bff9-12cd15ebb32e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af4e7f89-74fd-5a07-a772-df2e6ac1f0a3","sourceKey":"bank:AMS101:M101-T10N-106","parentItemId":null,"revision":1,"payload":{"prompt":"The system used to govern a corporation so that the interests of its owners are protected is called:","options":["Value chain management","Corporate governance","Management information system","Strategic control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Corporate governance is the system used to govern a corporation in a way that protects the owners' interests. Option C supplies managers with regular information but does not govern the corporation on behalf of owners."}},{"itemId":"4ada44ac-f7dd-5aa9-b3b8-958fceb20f5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca3b191f-acbf-5300-a280-d715415682e3","sourceKey":"bank:AMS101:M101-T10N-107","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the two areas of corporate governance reform?","options":["The range of variation","The role of boards of directors","Inventory turnover","Management by walking around"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The two areas of reform are the role of boards of directors, who should be independent and actually oversee management, and financial reporting. The other options are control concepts from elsewhere and are not governance reforms."}},{"itemId":"36f6176f-e420-5ba4-8332-8ec046a1a92e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cb09e052-f12d-5521-9b16-b81bf2589218","sourceKey":"bank:AMS101:M101-T10N-108","parentItemId":null,"revision":1,"payload":{"prompt":"The Sarbanes-Oxley Act (2002) in the United States, which raised disclosure and reporting requirements, is associated with which contemporary control issue?","options":["Corporate governance","Controlling customer interactions","Workplace privacy","Cross-cultural differences"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Sarbanes-Oxley is part of the financial reporting area of corporate governance, requiring accurate and honest financial information. Option C deals with employers monitoring employees, which this law is not about."}},{"itemId":"b80a4cdb-4d84-5e05-9255-6542340e9fd6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ca3658e-d317-56ed-a973-5904616e2b4b","sourceKey":"bank:AMS101:M101-T10N-109","parentItemId":null,"revision":1,"payload":{"prompt":"The part of the organization that produces goods or services, where resources are transformed into goods and services, is the:","options":["Human resource function","Operations function","Finance function","Marketing function"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The operations function is where the organization's resources are transformed into goods and services. Option D deals with selling and promoting output, not producing it."}},{"itemId":"abee9f35-a2be-5ff3-81b6-788c972db5b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"499ee1be-77c7-5515-a914-736599a8c39b","sourceKey":"bank:AMS101:M101-T10N-110","parentItemId":null,"revision":1,"payload":{"prompt":"Operations management is defined as:","options":["The management of employees' welfare and pensions","The system used to protect the interests of a corporation's owners","The administration of business structure, practices and processes to enhance efficiency and maximise profit","The search for best practices among competitors"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Operations management is the administration of business structure, practices and processes to improve efficiency and maximise profit. Option D describes benchmarking and option B describes corporate governance."}},{"itemId":"b2e95c08-7643-58c9-b1d7-8e3bd29cdab6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"680d3e17-deb0-5907-934f-aacf89c32288","sourceKey":"bank:AMS101:M101-T10N-111","parentItemId":null,"revision":1,"payload":{"prompt":"The process that converts resources into finished goods and services is known as the:","options":["Transformation process","Control process","Service profit chain","Benchmarking process"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Operations management is also defined as the transformation process, which turns inputs such as people, equipment and information into finished goods and services. Option C is the sequence from employees to customers to profit, and option B is the measure-compare-act cycle of controlling, neither of which converts resources into output."}},{"itemId":"b0d2efde-3a23-5654-adb9-78172635a199","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39e18ed2-0dd7-5ab3-a8c7-9819173e7df9","sourceKey":"bank:AMS101:M101-T10N-112","parentItemId":null,"revision":1,"payload":{"prompt":"The goals of operations management focus on several areas. Which of the following is NOT one of them?","options":["Maximising profitability","Proper allocation of available resources","Increasing the number of management levels","Controlling costs"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Operations management goals focus on controlling costs, maximising profitability and properly allocating available resources. Adding management levels is not one of these goals; options D, A and B are."}},{"itemId":"686286c0-c7d7-5891-88c3-384ef3e5ccdd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb3ba6ea-689a-5895-903a-1362c7c27250","sourceKey":"bank:AMS101:M101-T10N-113","parentItemId":null,"revision":1,"payload":{"prompt":"Effective operations management begins and ends with:","options":["The government","The customer","The supplier","The board of directors"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Effective operations management begins and ends with the customer, whose needs shape what is produced and how. Option C matters for incoming supplies, but it is the customer, not the supplier, at both ends."}},{"itemId":"346240d4-6804-5e97-b11c-c6d087389943","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c2073ab8-e4c2-5ab9-97b8-9a6cea694c60","sourceKey":"bank:AMS101:M101-T10N-114","parentItemId":null,"revision":1,"payload":{"prompt":"In operations management, every member of an organization is said to have customers:","options":["Only at the top of the hierarchy","Only in the sales department","Only outside the organization","At the next process, where one's work goes next"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Every member of an organization has customers at the next process, meaning whoever receives their work next. Option C is wrong because internal colleagues who receive one's work also count as customers."}},{"itemId":"2c9ed5dc-92d5-5279-9746-f2c6a092e20f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0002b439-54ad-5502-a47a-ca3a5e94834c","sourceKey":"bank:AMS101:M101-T10N-115","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the main functions of operations management?","options":["Scheduling","Recruiting","Purchasing","Inventory control"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The main functions of operations management are planning, scheduling, purchasing, controlling, quality control and inventory control. Recruiting is a staffing activity, not one of these functions."}},{"itemId":"ee34908c-e0b5-56a3-9b26-cd948f434ae1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"81c49a5b-230d-5f60-9562-6a7190efe580","sourceKey":"bank:AMS101:M101-T10N-117","parentItemId":null,"revision":1,"payload":{"prompt":"How many types of operations management are there?","options":["Six","Three","Four","Two"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The four types are manufacturing, service, logistics and project management. Option A is the number of main functions of operations management, not the number of types."}},{"itemId":"1de19338-71fc-5512-8ad4-9ec4e07cbe7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0fa4869b-37bd-5756-b33f-009b09733b72","sourceKey":"bank:AMS101:M101-T10N-118","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Apapa manages warehouses and a fleet of trucks that move and store goods for other firms. Which type of operations management does this represent?","options":["Project management","Manufacturing","Service","Logistics"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Logistics is the type of operations management concerned with the movement and storage of goods. Option B is about producing goods, which this company does not do."}},{"itemId":"61c3896a-1970-5151-8aa0-6de1b28901f7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b43cd290-8c9b-56db-8307-6179e323918f","sourceKey":"bank:AMS101:M101-T10N-119","parentItemId":null,"revision":1,"payload":{"prompt":"A university in Lagos appoints a team to manage the building of a new hostel, from planning through to completion. Which type of operations management is this?","options":["Logistics","Manufacturing","Project management","Service"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Project management manages a specific one-off project from planning to completion, on time, within budget and to specification. Option A deals with moving and storing goods, not delivering a single project."}},{"itemId":"88c8cf2d-52ae-5155-98e2-aba2b4185f4e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a2b2b9ca-920f-5214-ab01-4157739b998b","sourceKey":"bank:AMS101:M101-T10N-120","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four types of operations management?","options":["Marketing","Manufacturing","Service","Logistics"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"The four types are manufacturing, service, logistics and project management. Marketing is a separate business function, while options B, C and D are all types of operations management."}},{"itemId":"3c269867-ae48-5ba7-a7d9-c30fe7559b6e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f11e1bab-e7f5-5beb-9f12-6725df09dfd9","sourceKey":"bank:AMS101:M101-T10N-121","parentItemId":null,"revision":1,"payload":{"prompt":"In the transformation process, which of the following is an input?","options":["Services","Information","Work activities","Goods"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Inputs include people, technology, capital, equipment and information, among others. Options D and A are outputs, and option C is part of the transformation process itself."}},{"itemId":"5ba8831a-0bc8-503a-9b3a-c41efc77e832","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5036794a-16b6-5253-b773-fbd15c1d0fda","sourceKey":"bank:AMS101:M101-T10N-122","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following belongs to the transformation stage of the transformation process?","options":["Materials","Capital","Operations methods","Services"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The transformation stage consists of work activities, operations methods and management activities. Options B and A are inputs, and option D is an output."}},{"itemId":"346d16b1-fc26-5871-ae11-069238288bec","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78b77879-3f5f-52ce-b780-5af8a1ffcb07","sourceKey":"bank:AMS101:M101-T10N-123","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery in Ota produces 1,200 loaves of bread using 300 labour-hours. Using productivity = outputs divided by inputs, what is its labour productivity?","options":["900 loaves per labour-hour","4 loaves per labour-hour","0.25 loaves per labour-hour","1,500 loaves per labour-hour"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Productivity is outputs divided by inputs, so 1,200 loaves divided by 300 labour-hours gives 4 loaves per labour-hour. Option C divides the wrong way round, inputs by outputs."}},{"itemId":"d6509814-6a54-50df-a283-c845115e0f86","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ac98094-bdb9-5323-8385-970023041c77","sourceKey":"bank:AMS101:M101-T10N-124","parentItemId":null,"revision":1,"payload":{"prompt":"Which characteristic distinguishes service organizations from manufacturing organizations?","options":["They include car makers and steel firms","Their output is used as it is produced","They produce physical goods","Their output can be stored"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Service organizations produce nonphysical outputs that are used as they are produced. Options D, C and A all describe manufacturing organizations."}},{"itemId":"9ece7a33-3dee-50ae-a7ff-5b5ddabae39d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ed28448-fa3e-5efd-afcd-d77827cfa163","sourceKey":"bank:AMS101:M101-T10N-125","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a service organization?","options":["A steel company in Ajaokuta","A hospital in Ibadan","A food processing factory in Kano","A car assembly plant in Lagos"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Hospitals, like banks, airlines and schools, produce nonphysical outputs, so they are service organizations. Options D, A and C produce physical goods and are manufacturing organizations."}},{"itemId":"65a98f60-db86-5b2b-991a-0616b35c8bca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71f1f99f-4b3b-54d5-9fc8-99b13aef3159","sourceKey":"bank:AMS101:M101-T10N-126","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following trends has made operations vital to every organization's success?","options":["The decline of global competition","A reduced need for efficient delivery","A shrinking service sector","The rise of the service economy"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Global competition, the rise of the service economy and the need for efficient procurement, production and delivery have made operations vital. Options A, C and B state the opposite of these trends."}},{"itemId":"8a9a2650-bb9d-5a46-ae26-40c87d3cf1f2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a35d97d5-4102-5248-a430-aca6281fb594","sourceKey":"bank:AMS101:M101-T10N-127","parentItemId":null,"revision":1,"payload":{"prompt":"Who gave 14 points for improving management's productivity?","options":["W. Edwards Deming","Henri Fayol","Robert Kaplan and David Norton","Abraham Maslow"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"W. Edwards Deming proposed 14 points for improving management's productivity and is closely linked with quality and TQM. Option C developed the balanced scorecard, not the 14 points."}},{"itemId":"8b578e40-f601-5582-9af2-a83961c0d54f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"28b2cd54-05cc-59fa-ba1c-a8887eced7f8","sourceKey":"bank:AMS101:M101-T10N-128","parentItemId":null,"revision":1,"payload":{"prompt":"How many points did W. Edwards Deming propose for improving management's productivity?","options":["6","4","14","10"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Deming gave 14 points for improving management's productivity. Option A is the number of main functions of operations management, a different list."}},{"itemId":"52b65dd1-9a9b-5657-b091-f1acfae469cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d4c10d42-1d69-5b7c-94f6-2146cef6808e","sourceKey":"bank:AMS101:M101-T10N-129","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the themes of Deming's 14 points?","options":["Plan for the short term","Break down barriers between departments","Use statistical control of processes","Drive out fear"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Deming's points stress planning for the long term, not the short term. Options D, C and B are all genuine themes of his points, along with training workers and constant improvement."}},{"itemId":"887d9510-cb03-5c5e-ab63-c042672b6a39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f7ff60b-5965-5802-85bf-29a5033fb393","sourceKey":"bank:AMS101:M101-T10N-130","parentItemId":null,"revision":1,"payload":{"prompt":"Much of W. Edwards Deming's early influence on quality was in:","options":["Nigeria","Brazil","Germany","Japan"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Deming is linked with quality and TQM, and much of his early influence was in Japan. The other countries are not where his early influence was felt."}},{"itemId":"87234bee-8a43-5a3d-8524-6a66cc194703","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"67025e00-0995-58ef-8700-ce6d1672ad70","sourceKey":"bank:AMS101:M101-T10N-131","parentItemId":null,"revision":1,"payload":{"prompt":"Productivity in an organization improves through:","options":["Both people and operations variables working together","Machines alone","Reducing the number of customers","Cutting all training programmes"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Productivity improves through both people and operations variables; machines alone are not enough because the whole system must work together. Option B is the tempting but wrong idea that technology by itself is sufficient."}},{"itemId":"6c798c99-d7e9-5747-b1b9-b10449a6b874","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa167594-939f-5fad-bb3d-574ad93138aa","sourceKey":"bank:AMS101:M101-T10N-132","parentItemId":null,"revision":1,"payload":{"prompt":"The performance features, attributes and other aspects of goods and services that customers are willing to give up resources (usually money) for are known as:","options":["Value","A benchmark","Quality","Productivity"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Value is whatever features and attributes of a product or service customers are willing to pay for with their resources, usually money. Option C is the ability of a product to reliably do what it should and satisfy customers, which is related but not the same."}},{"itemId":"7f08a802-6c50-5cb9-a3f9-06600443f9d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ec1bd4e-bf44-5c41-8d13-478aef14826b","sourceKey":"bank:AMS101:M101-T10N-133","parentItemId":null,"revision":1,"payload":{"prompt":"The entire series of work activities that add value at each step, from raw materials to finished product, is called the:","options":["Range of variation","Value chain","Service profit chain","Scalar chain"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"The value chain is the whole series of work activities that add value at each step from raw inputs to finished product. Option C links employees to customers to profit, not the steps in producing a product."}},{"itemId":"a45249f8-038c-5627-9ca5-0fde51e1e3d6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4503c112-8927-5e9c-b24e-5587c0836d35","sourceKey":"bank:AMS101:M101-T10N-134","parentItemId":null,"revision":1,"payload":{"prompt":"Value chain management is the process of:","options":["Managing the sequence of activities and information along the entire value chain","Monitoring employees' email and internet use","Managing only the flow of incoming materials","Ranking organizations on published measures"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Value chain management manages the sequence of activities and information along the entire value chain. Option C describes the narrower supply chain management, which focuses on incoming supplies."}},{"itemId":"52a0b3a4-869c-52b4-b7ae-ce7ad4f252ac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3e90207c-541a-5208-8b07-e91097354566","sourceKey":"bank:AMS101:M101-T10N-135","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly compares value chain management with supply chain management?","options":["Both are internally focused and aim at cutting costs","Value chain management covers only incoming materials","Value chain management is internally focused and aims at efficiency","Value chain management is externally focused and aims at effectiveness"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Value chain management has an external focus, covers both incoming supplies and outgoing products and aims at effectiveness, creating the most value for customers. Option C describes supply chain management instead, the swap that exams often test."}},{"itemId":"e8bc00cf-11f0-5a74-a793-bb6cec32a609","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"935165a1-94fc-5426-b76a-60b8bdd98387","sourceKey":"bank:AMS101:M101-T10N-136","parentItemId":null,"revision":1,"payload":{"prompt":"The goal of supply chain management is:","options":["Effectiveness, creating the most value for customers","Protecting the interests of owners","Reducing defects to 3.4 per million","Efficiency, cutting costs"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Supply chain management is internally focused on the efficient flow of incoming supplies, with the goal of efficiency and cutting costs. Option A is the goal of value chain management."}},{"itemId":"9df796d2-fdec-5975-8667-89724869d57d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f840a855-2cfa-57bc-9b59-27bb84c08f5a","sourceKey":"bank:AMS101:M101-T10N-137","parentItemId":null,"revision":1,"payload":{"prompt":"A food processor in Kano focuses only on getting its incoming raw materials delivered efficiently and at the lowest possible cost. This narrow internal focus is best described as:","options":["Supply chain management","Mass customisation","Total quality management","Value chain management"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"An internal focus on the efficient flow of incoming supplies to cut costs is supply chain management. Option D would also cover outgoing products and services and aim at creating the most value for customers."}},{"itemId":"2c3bcfad-55a4-57a4-93f2-f15890bbe03c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd684162-70d3-5869-838c-535d1969c112","sourceKey":"bank:AMS101:M101-T10N-138","parentItemId":null,"revision":1,"payload":{"prompt":"The goal of value chain management is to create a value chain strategy that:","options":["Cuts the cost of incoming materials only","Measures performance only in financial terms","Meets and exceeds customer needs and allows full and seamless integration of all members of the chain","Keeps information private from all partners"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"Value chain management aims for a strategy that meets and exceeds customer needs and fully, seamlessly integrates all members of the chain. Option A is the narrower cost focus of supply chain management."}},{"itemId":"d34dfec6-0c22-50cb-8b4d-68abc197d835","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8209d02a-d65e-5b2f-9ea8-bb39059025a6","sourceKey":"bank:AMS101:M101-T10N-139","parentItemId":null,"revision":1,"payload":{"prompt":"How many requirements are there for successful value chain management?","options":["Three","Four","Six","Five"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"The six requirements are coordination and collaboration, technology investment, organizational processes, leadership, employees and organizational culture and attitudes. Option B is the number of obstacles, not requirements."}},{"itemId":"f63adb9a-b00f-5ad7-b4e0-770be82accf8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a45b9eb-21ee-527f-ac6a-ec0261d37f4f","sourceKey":"bank:AMS101:M101-T10N-140","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a requirement for successful value chain management?","options":["Organizational barriers","Coordination and collaboration","Technology investment","Leadership"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Organizational barriers are an obstacle to value chain management, not a requirement. Options B, C and D are genuine requirements, along with organizational processes, employees and culture."}},{"itemId":"ced86cf0-8f91-551a-9c95-f2636db346cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eca82fed-1f0d-5727-8fd2-16d4b5a1a5d7","sourceKey":"bank:AMS101:M101-T10N-141","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an obstacle to value chain management?","options":["Required capabilities","Technology investment","Cultural attitudes","Organizational barriers"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Technology investment is one of the six requirements for value chain management, not an obstacle. The four obstacles are organizational barriers, cultural attitudes, required capabilities and people."}},{"itemId":"a9b11aeb-197f-5527-b572-5e481885e3a7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"361bf22c-ab62-5ee4-8613-be2d6c261361","sourceKey":"bank:AMS101:M101-T10N-142","parentItemId":null,"revision":1,"payload":{"prompt":"How many obstacles to value chain management are commonly identified?","options":["Four","Six","Five","Two"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"The four obstacles are organizational barriers, cultural attitudes, required capabilities and people. Option B is the number of requirements for value chain management."}},{"itemId":"14bb9827-6687-5eb0-a29b-393cc36203f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a08149b-8d42-540f-b834-c689f9f8df61","sourceKey":"bank:AMS101:M101-T10N-143","parentItemId":null,"revision":1,"payload":{"prompt":"Refusal to share information, reluctance to change the status quo and security worries are examples of which obstacle to value chain management?","options":["People","Required capabilities","Cultural attitudes","Organizational barriers"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"These are organizational barriers, which block the information sharing and change that value chain management needs. Option C refers instead to lack of trust and fear of losing intellectual property."}},{"itemId":"fd6a995a-34f5-53c5-a5d6-09b0503e5903","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"34287e41-64a8-5034-b84a-5e6e6d9cef03","sourceKey":"bank:AMS101:M101-T10N-144","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturer refuses to work closely with its distributors because it does not trust them and fears they will copy its product designs. This is an example of which obstacle to value chain management?","options":["Required capabilities","Cultural attitudes","Organizational barriers","People"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Lack of trust and fear of losing intellectual property to partners are cultural attitudes. Option C is tempting, but organizational barriers refer to refusal to share information, reluctance to change and security worries."}},{"itemId":"426a576b-cc2f-5373-a8d4-cc04e5ad312d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05b23d0c-c0eb-5721-99d5-9881707afa07","sourceKey":"bank:AMS101:M101-T10N-145","parentItemId":null,"revision":1,"payload":{"prompt":"Unwillingness to change, lack of commitment and the time and energy needed are examples of which obstacle to value chain management?","options":["Organizational barriers","Cultural attitudes","People","Required capabilities"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"These problems come from the people involved, so they are the people obstacle. Option D is about partners lacking the skills or systems needed, not about willingness or commitment."}},{"itemId":"18c91a6b-1770-5894-a38f-94c3abc7007b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"32350ba9-e17b-521f-86cc-e8b9b101564d","sourceKey":"bank:AMS101:M101-T10N-146","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ota wants to link up with its suppliers in a value chain, but several suppliers do not have the skills or computer systems needed to take part. Which obstacle is this?","options":["Cultural attitudes","Organizational barriers","People","Required capabilities"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"When partners lack the skills or systems needed, the obstacle is required capabilities. Option C would concern unwillingness to change or lack of commitment, not missing skills or systems."}},{"itemId":"21c1f7e7-eb73-563d-9ba7-7d0527c6cbc6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a063380-ef65-5ea7-9950-14b497a7f90a","sourceKey":"bank:AMS101:M101-T10N-147","parentItemId":null,"revision":1,"payload":{"prompt":"In a value chain, who has the power to decide what value is and when it is delivered?","options":["The customer","The government","The supplier","The manufacturer"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"In a value chain the customer has the power, deciding what value is and when it is delivered. Option D is tempting because the manufacturer makes the product, but it must respond to what customers value."}},{"itemId":"d772d420-2d53-5b93-82a2-0bfec54943d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df2c34fa-fafb-5717-8005-5285d4904b67","sourceKey":"bank:AMS101:M101-T10N-148","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the benefits of value chain management?","options":["Improved procurement","Enhanced customer order management","Improved logistics","Elimination of all competitors"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Value chain management brings improved procurement, logistics and product development and enhanced customer order management. It cannot eliminate competitors, so that option is the odd one out."}},{"itemId":"f2573bbd-d32a-54fd-b607-d2dd98cc7c27","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0729561-279f-5e45-af65-6c68f90791e5","sourceKey":"bank:AMS101:M101-T10N-149","parentItemId":null,"revision":1,"payload":{"prompt":"The ability of a product or service to reliably do what it is supposed to do and satisfy customer expectations is called:","options":["Quality","Effectiveness","Productivity","Value"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"Quality is the ability of a product or service to reliably do what it is supposed to do and satisfy customer expectations. Option D is what customers are willing to give up resources for, which is a different idea."}},{"itemId":"b47ebccf-96ff-588b-950f-04781dfe628f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"773c0960-d531-5db0-a653-cc4bc45a9a5a","sourceKey":"bank:AMS101:M101-T10N-150","parentItemId":null,"revision":1,"payload":{"prompt":"A philosophy of management driven by continuous improvement and responsiveness to customer needs and expectations is:","options":["ISO 9000","Six Sigma","Total quality management (TQM)","Benchmarking"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"TQM is a management philosophy built on continuous improvement and responsiveness to customer needs and expectations. Option A is a series of international quality standards, and option B is a defect-reduction programme."}},{"itemId":"dc3879bd-97f5-5ccb-861e-861879c2238b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8fd99704-097b-5784-a993-fb363108c6a0","sourceKey":"bank:AMS101:M101-T10N-151","parentItemId":null,"revision":1,"payload":{"prompt":"A series of international quality management standards that set uniform guidelines for processes, so that products conform to customer requirements, is known as:","options":["ISO 9000","The balanced scorecard","Total quality management","Six Sigma"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"ISO 9000 is a series of international quality management standards that set uniform rules for processes. Option D is a programme aimed at reducing defects to no more than 3.4 per million."}},{"itemId":"8e42121e-d492-538e-a0e5-9fc0b1b85e83","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"750257e0-0e94-5377-84e1-7d71ef503213","sourceKey":"bank:AMS101:M101-T10N-152","parentItemId":null,"revision":1,"payload":{"prompt":"The goal of the Six Sigma quality programme is no more than:","options":["6 defects per million units or procedures","3.4 defects per thousand units or procedures","34 defects per million units or procedures","3.4 defects per million units or procedures"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Six Sigma aims for no more than 3.4 defects per million units or procedures. Option B gets the number right but the scale wrong, which would allow a thousand times more defects."}},{"itemId":"e4523e9a-ec09-52f6-86f4-366530d046f5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51902d85-ed35-5451-bb6a-adbf2154d1db","sourceKey":"bank:AMS101:M101-T10N-153","parentItemId":null,"revision":1,"payload":{"prompt":"A quality programme designed to reduce defects, lower costs, save time and improve customer satisfaction is:","options":["Benchmarking","Six Sigma","Mass customisation","ISO 9000"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"Six Sigma is a quality programme to reduce defects, lower costs, save time and improve customer satisfaction. Option D is a set of international standards and certification, not a defect-reduction programme."}},{"itemId":"76cb2db7-1a5f-58c7-bde9-ad8ed2f2e026","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a1ae077-60c8-523e-a31c-a182944f1e04","sourceKey":"bank:AMS101:M101-T10N-154","parentItemId":null,"revision":1,"payload":{"prompt":"Total quality management (TQM) is most closely linked with which management thinker?","options":["Abraham Maslow","W. Edwards Deming","Henri Fayol","Robert Kaplan"],"correctOption":1,"section":"Foundations of Control and Operations Management","explanation":"TQM is linked with W. Edwards Deming, who also gave 14 points for improving productivity. Option D co-developed the balanced scorecard, a performance measurement tool rather than a quality philosophy."}},{"itemId":"c78d885d-2760-50b0-a34c-c77e8ff6247b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e03de6ab-0976-5e91-a767-94e68a3ba2e3","sourceKey":"bank:AMS101:M101-T10N-155","parentItemId":null,"revision":1,"payload":{"prompt":"A paint manufacturer in Ota seeks certification from the International Organization for Standardization to show export customers that it has proper quality processes. Which quality standard is it pursuing?","options":["ISO 9000","Total quality management","Six Sigma","The balanced scorecard"],"correctOption":0,"section":"Foundations of Control and Operations Management","explanation":"ISO 9000 is set by the International Organization for Standardization, and certification tells customers a firm has proper quality processes. Option C is an internal programme with a defect target, not a certification from that body."}},{"itemId":"2de1affc-55a9-515c-92ff-ba519c6695ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"665eeab3-d2db-54c7-a7e6-646278e18c8d","sourceKey":"bank:AMS101:M101-T10N-156","parentItemId":null,"revision":1,"payload":{"prompt":"Giving customers a product when, where and how they want it is called:","options":["Supply chain management","Mass production","Benchmarking","Mass customisation"],"correctOption":3,"section":"Foundations of Control and Operations Management","explanation":"Mass customisation means providing customers with a product when, where and how they want it. Option B is the opposite idea of producing large volumes of a standard product."}},{"itemId":"4b065c8f-d0c4-5970-8e83-a63cde928d4b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a330dcec-e96c-56e2-ba8d-4f71370395df","sourceKey":"bank:AMS101:M101-T10N-157","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a focus of total quality management (TQM)?","options":["A one-time quality inspection","Focusing only on financial results","Continuous improvement with employee involvement","Reducing the number of customers served"],"correctOption":2,"section":"Foundations of Control and Operations Management","explanation":"TQM focuses on the customer, continuous improvement, accurate measurement and employee involvement. Option A is wrong because TQM is about ongoing improvement rather than a single check."}},{"itemId":"4f441aa5-f06c-59f3-8fc2-3f50b1c578fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"849d0ccb-d725-52cd-9baa-9faeb6293eb2","sourceKey":"bank:AMS101:M101-T4N-001","parentItemId":null,"revision":1,"payload":{"prompt":"Arranging and structuring work to accomplish an organization's goals is the management function called:","options":["leading","planning","organizing","controlling"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Organizing is the function that arranges and structures work so the organization can reach its goals. Option B, planning, is about setting the goals and plans in the first place, which comes before organizing."}},{"itemId":"237861a5-70bd-5845-961c-6fa628dee3f6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"284f7a11-736d-5034-90dd-0dec2492170c","sourceKey":"bank:AMS101:M101-T4N-002","parentItemId":null,"revision":1,"payload":{"prompt":"In the sequence of management functions, organizing comes directly after:","options":["controlling","staffing","leading","planning"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Organizing follows planning: once goals and plans are set, managers arrange and structure the work needed to achieve them. Option C, leading, comes after the work has been organized, not before it."}},{"itemId":"0b5a5b8f-d20d-5d26-b62a-a6af24869ec5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8097e298-d1d7-5d2c-828d-171bbb84c40a","sourceKey":"bank:AMS101:M101-T4N-003","parentItemId":null,"revision":1,"payload":{"prompt":"The formal framework by which job tasks are divided, grouped and coordinated is known as the:","options":["organizational chart","organizational design","organizational structure","departmentalization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Organizational structure is the formal framework that divides, groups and coordinates job tasks. Option A, the organizational chart, is only the picture of that structure, not the framework itself."}},{"itemId":"8b31219c-dbc7-5a89-803c-5cadbb87ac30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f99de8fb-f48c-5f69-8b84-0ec77a203120","sourceKey":"bank:AMS101:M101-T4N-004","parentItemId":null,"revision":1,"payload":{"prompt":"The picture or diagram that shows an organization's structure is called the:","options":["organizational design","organizational chart","chain of command","organizational structure"],"correctOption":1,"section":"Organization Design and Structure","explanation":"An organizational chart is the visual picture of an organization's structure. Option A, organizational design, is the process of developing or changing the structure, not the drawing of it."}},{"itemId":"8fa71bd1-b44e-5e39-898c-7b6c4ea70357","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c919edc9-47e8-5833-ac3e-ac7d76f99531","sourceKey":"bank:AMS101:M101-T4N-005","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational design is best described as:","options":["dividing tasks into separate, narrow jobs","developing or changing an organization's structure","grouping jobs on the basis of customer needs","drawing a picture of the reporting lines"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Organizational design means developing or changing an organization's structure, and it involves decisions on all six structural elements. Option D describes the organizational chart, which only pictures the structure."}},{"itemId":"5aea5234-b3d7-5376-8770-49cb2020879f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e7d41454-fe6f-57dd-9df7-6f0e0372a77f","sourceKey":"bank:AMS101:M101-T4N-006","parentItemId":null,"revision":1,"payload":{"prompt":"Complete the analogy: organizing is to structure as planning is to:","options":["motivation","coordination","goal setting","supervision"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Just as organizing produces a structure, planning produces goals, so planning is linked to goal setting. Option B, coordination, is one of the purposes of organizing, not the output of planning."}},{"itemId":"b12e252e-1634-539f-82be-c60d5108625f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"921bd1fc-12ed-57cc-aec5-c0eaacfef094","sourceKey":"bank:AMS101:M101-T4N-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a purpose of organizing?","options":["It divides work into specific jobs and departments","It creates services","It allocates and deploys organizational resources","It establishes formal lines of authority"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Creating services is not one of the purposes of organizing. Organizing divides work, assigns tasks, coordinates activities, clusters jobs into units, sets up relationships and authority lines, and allocates resources, so options A and the others are all genuine purposes."}},{"itemId":"abd9ca08-43a3-573c-aab1-7ca41976dba4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fe565862-ed48-5985-ba6e-1eef5b714616","sourceKey":"bank:AMS101:M101-T4N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a purpose of organizing?","options":["Inspiring employees to work harder","Clustering jobs into units","Setting the organization's long-term goals","Comparing actual performance with standards"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Clustering jobs into units is one of the purposes of organizing. Option C, setting long-term goals, belongs to planning, while comparing performance with standards is controlling and inspiring employees is leading."}},{"itemId":"94c232c9-7a4f-5d0c-940a-6d594dc03b01","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ae89d752-276b-5bfc-bd48-c3f288bf81e1","sourceKey":"bank:AMS101:M101-T4N-009","parentItemId":null,"revision":1,"payload":{"prompt":"How many purposes of organizing are usually listed?","options":["Seven","Six","Five","Nine"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Seven purposes are listed: dividing work, assigning tasks, coordinating tasks, clustering jobs, establishing relationships, establishing formal lines of authority, and allocating resources. Option C, six, is easy to confuse with the six elements of organizational design."}},{"itemId":"ed0ebef8-30af-52ee-a45b-942a8d7c995b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"23e83396-5448-5a8b-b3b4-d6c0c3de882e","sourceKey":"bank:AMS101:M101-T4N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a principle of organizing?","options":["Scalar chain","Publicity","Unity of objective","Parity of authority and responsibility"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Publicity is not a principle of organizing. Unity of objective, scalar chain and parity of authority and responsibility (options C and the others) are all genuine principles that shape how a structure is built."}},{"itemId":"24896fc9-d42d-5131-aac3-9884d51837da","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b9e7ddc3-0fac-50bb-8f8f-a1db2346d063","sourceKey":"bank:AMS101:M101-T4N-011","parentItemId":null,"revision":1,"payload":{"prompt":"The principle of organizing which holds that the structure must serve the organization's goals is:","options":["scalar chain","efficiency","unity of command","unity of objective"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Unity of objective says the structure exists to serve the organization's goals. Option C, unity of command, sounds similar but means that each person has only one boss."}},{"itemId":"c4ce7862-bf14-5c3a-b77b-2e8df2923457","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a873499-bd3e-5924-adb4-df098591d02c","sourceKey":"bank:AMS101:M101-T4N-012","parentItemId":null,"revision":1,"payload":{"prompt":"A structure that reaches its objectives at the lowest cost and with the least waste satisfies the principle of:","options":["division of work","balance, flexibility and continuity","efficiency","unity of objective"],"correctOption":2,"section":"Organization Design and Structure","explanation":"The efficiency principle says a structure should achieve its objectives at the lowest cost and with the least waste. Option D, unity of objective, is about the structure serving the goals, not about cost or waste."}},{"itemId":"33445bf2-3a41-5f38-9db0-9555abf64905","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0648bf30-7b1a-5dda-82d1-06c7f7600474","sourceKey":"bank:AMS101:M101-T4N-013","parentItemId":null,"revision":1,"payload":{"prompt":"The principle of organizing that calls for a clear line of authority from the top of the organization to the bottom is the:","options":["span of control","unity of command","delegation of authority","scalar chain"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The scalar chain is the principle of a clear line of authority running from top to bottom. Option B, unity of command, is related but narrower: it says each person should have only one boss."}},{"itemId":"13239283-f492-5cf3-ad6c-d83ceb9f4d5f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd9a6de0-df91-5117-bd09-aae40258ce7d","sourceKey":"bank:AMS101:M101-T4N-014","parentItemId":null,"revision":1,"payload":{"prompt":"The principle of parity of authority and responsibility means that:","options":["authority must be held only by top managers","authority and responsibility must be in balance","a manager can supervise only a few people","each person must report to only one boss"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Parity of authority and responsibility means the two must be in balance, so a person given a duty also gets enough authority to carry it out. Option D describes unity of command, a different principle."}},{"itemId":"12b10179-1730-56d6-b581-9fb6ac053631","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d0a8b99-835f-59a2-90c2-e866deba5860","sourceKey":"bank:AMS101:M101-T4N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Work specialization is also known as:","options":["division of labour","departmentalization","delegation","formalization"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Work specialization, where each employee does part of an activity rather than the whole, is also called division of labour. Option B, departmentalization, is about grouping jobs together, not dividing tasks into jobs."}},{"itemId":"c3a5095c-36e7-5c9d-b1ab-bd2413f264a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4cbde66d-dacc-545e-91e6-c5b3f98a23b3","sourceKey":"bank:AMS101:M101-T4N-016","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a likely result of taking work specialization too far?","options":["Boredom and fatigue","Higher product quality","High employee turnover","Absenteeism"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Too much specialization leads to boredom, fatigue, stress, poor quality, absenteeism and high turnover, so higher product quality is the odd one out. Options A and the others are all listed problems of over-specialization."}},{"itemId":"184a7dc7-0a7f-562a-b3f2-475b0cd8525a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d773c15d-5779-55c8-86d7-415dca3ec39f","sourceKey":"bank:AMS101:M101-T4N-017","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota gives each machine operator a wider range of tasks instead of one repetitive step. This change is best described as:","options":["a reduction in work specialization","a move to process departmentalization","an increase in formalization","an increase in work specialization"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Giving workers more tasks means each person does more of the whole activity, which reduces work specialization. Option D is the opposite: increasing specialization would narrow each job to fewer tasks."}},{"itemId":"be31eec9-d929-5bcd-b123-c31eb41ed5cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6ce5f584-f495-55d6-9213-89ed2627473d","sourceKey":"bank:AMS101:M101-T4N-018","parentItemId":null,"revision":1,"payload":{"prompt":"Early managers viewed work specialization as:","options":["an endless source of productivity","a barrier to departmentalization","a threat to unity of command","a major cause of employee turnover"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Early managers saw work specialization as an endless way to raise productivity. Option D reflects a later realization that specialization taken too far causes problems such as high turnover."}},{"itemId":"6d47fd7d-5716-50ad-b9b5-1bceafbd7606","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d78e322-58da-59ab-8e02-628e383ecf44","sourceKey":"bank:AMS101:M101-T4N-019","parentItemId":null,"revision":1,"payload":{"prompt":"A consumer goods company in Ota sets up separate departments for beverages, snacks and detergents, each with its own staff. This is:","options":["customer departmentalization","process departmentalization","functional departmentalization","product departmentalization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Grouping jobs by product line, so each unit has everything needed for one product, is product departmentalization. Option C, functional, would group jobs by tasks such as finance, marketing and production instead."}},{"itemId":"a4662593-f8c0-57fc-8061-a731aa5f52cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab923b4f-4ec5-5440-906a-cba36008bdd7","sourceKey":"bank:AMS101:M101-T4N-020","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank organizes its staff into retail banking, corporate banking and government banking units. Which type of departmentalization is this?","options":["Customer","Geographic","Product","Functional"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Grouping jobs by the type of customer served and their needs is customer departmentalization. Option C, product, would group by product line or service, but here the units are defined by who the bank serves."}},{"itemId":"99f4131c-8e01-5418-ae08-44f817fb88a4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6388f1d3-d094-5c72-b47c-76a75616374e","sourceKey":"bank:AMS101:M101-T4N-021","parentItemId":null,"revision":1,"payload":{"prompt":"At a licensing office, applicants move from a forms section to a testing section and then to a payment section. The office is using:","options":["functional departmentalization","customer departmentalization","process departmentalization","geographic departmentalization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"When units follow the flow of customers or products through a sequence, the grouping is process departmentalization. Option A, functional, groups by the tasks performed, but the clue here is the step-by-step flow."}},{"itemId":"2d5c13c7-d9bb-54c8-8e84-a64c9f7c2895","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f04a3645-63a4-5566-bae9-ce2b00e6b462","sourceKey":"bank:AMS101:M101-T4N-023","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Ikeja has separate finance, marketing, production and human resources departments. This grouping is:","options":["product departmentalization","customer departmentalization","functional departmentalization","geographic departmentalization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Finance, marketing, production and HR are functions, so grouping jobs this way is functional departmentalization. Option A, product, would create units around product lines such as beverages or snacks."}},{"itemId":"dc80f453-4553-5e0e-a335-c11bed93f0c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78cb5d60-2828-5615-a1ab-6cdf271c3dda","sourceKey":"bank:AMS101:M101-T4N-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of departmentalization groups everything needed to make and sell one product line into a single unit?","options":["Process","Product","Functional","Customer"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Product departmentalization brings together everything needed for one product. Option C, functional, instead groups people with similar skills, such as all accountants in one department."}},{"itemId":"b537e33f-4a09-5fe7-b520-acbc12e212b5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"79479cf9-f544-53be-ab53-cb85e91aad16","sourceKey":"bank:AMS101:M101-T4N-025","parentItemId":null,"revision":1,"payload":{"prompt":"How many types of departmentalization are there?","options":["Four","Five","Three","Six"],"correctOption":1,"section":"Organization Design and Structure","explanation":"There are five types: functional, geographic, product, process and customer. Option A, four, is easy to choose by mistake because it matches the number of contingency factors."}},{"itemId":"48e39776-d351-55bb-8f39-127befad7794","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"13b32554-42b7-5c01-b907-d9bd17f11e9d","sourceKey":"bank:AMS101:M101-T4N-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a type of departmentalization?","options":["Hierarchical","Process","Geographic","Customer"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The five types of departmentalization are functional, geographic, product, process and customer, so hierarchical is not one of them. Options C and the others are all genuine bases for grouping jobs."}},{"itemId":"1302fbe7-d661-591f-a334-33bfb655b4e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"96397d9c-cf37-5aa1-9d7d-ee6c174d8c63","sourceKey":"bank:AMS101:M101-T4N-027","parentItemId":null,"revision":1,"payload":{"prompt":"A cross-functional team is best described as:","options":["a team of people drawn from different functions","a team made up only of top managers","a team set up for one geographic region","a team of staff from one functional department"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A cross-functional team brings together people from different functions, such as designers, production workers and salespeople. Option B is wrong because a team from a single department is not cross-functional."}},{"itemId":"c569bd4f-02bb-597b-85d7-104a377b452e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ae2c30e1-892e-531c-b7df-7ca46ed7342e","sourceKey":"bank:AMS101:M101-T4N-028","parentItemId":null,"revision":1,"payload":{"prompt":"Customer departmentalization has become more important today mainly because it helps firms to:","options":["strengthen unity of command","track customer needs and respond to changes in them","standardize jobs through rules","reduce the number of management levels"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Customer departmentalization helps firms keep track of what customers need and respond quickly when those needs change, which matters in a competitive environment. Option D relates to span of control, not to how jobs are grouped."}},{"itemId":"8709221a-a055-5642-baee-1416f680eb63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4aa3079e-ca93-5570-9940-f73895a5e584","sourceKey":"bank:AMS101:M101-T4N-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of organizational design shows who reports to whom?","options":["Formalization","Span of control","Work specialization","Chain of command"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The chain of command is the unbroken line of authority from top to bottom, and it shows who reports to whom. Option B, span of control, tells you how many people a manager supervises, not the reporting line itself."}},{"itemId":"cdf318d7-191b-5049-95eb-62e81b4bb4b1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b1826d95-330b-554f-a8aa-46b725bc717d","sourceKey":"bank:AMS101:M101-T4N-030","parentItemId":null,"revision":1,"payload":{"prompt":"A teller at a Lagos bank receives conflicting instructions from both the branch manager and the regional operations head. Which principle is being violated?","options":["Unity of objective","Scalar chain","Span of control","Unity of command"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Unity of command says each person should report to only one manager, so taking orders from two bosses breaks it. Option C, span of control, is about how many people one manager supervises, not how many bosses one employee has."}},{"itemId":"f811a8f0-a1fa-5766-9249-be51f2cdd34a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2583b2b5-2e98-50ee-a595-fcd095f466d1","sourceKey":"bank:AMS101:M101-T4N-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes the chain of command from span of control?","options":["Chain of command is the line of authority; span of control is how many people one boss supervises","Chain of command is a staff function; span of control is a line function","Chain of command means one boss per person; span of control means decisions are made at the top","Chain of command is how many people one boss supervises; span of control is the line of authority"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The chain of command is the line of authority, while span of control is the number of people one boss supervises. Option D simply swaps the two definitions, which is a common trap."}},{"itemId":"cc2aae3c-7ac1-582c-9527-4116aeea42d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5b64738f-3162-56e6-b6e0-198e9e097da9","sourceKey":"bank:AMS101:M101-T4N-032","parentItemId":null,"revision":1,"payload":{"prompt":"Authority that lets a manager direct the work of an employee and follows the chain of command from top to bottom is:","options":["line authority","expert power","staff authority","referent power"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Line authority entitles a manager to direct an employee's work and runs down the chain of command. Option C, staff authority, is advisory: it supports and assists line managers rather than directing work."}},{"itemId":"7ae6458a-751a-59fb-9865-b948958eb39c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03ab76bb-bd04-5851-a17d-8286bc15c813","sourceKey":"bank:AMS101:M101-T4N-033","parentItemId":null,"revision":1,"payload":{"prompt":"Authority that supports, assists, advises and reduces the load of line managers is called:","options":["legitimate power","staff authority","line authority","coercive power"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Staff authority is advisory: it supports, assists and advises line managers and lightens their load. Option C, line authority, is the right to direct the work of employees down the chain of command."}},{"itemId":"5ea6265d-6ae7-5124-aa76-8ad1481efc53","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d84b637-41ff-5b5b-a6e7-986cff89ab4e","sourceKey":"bank:AMS101:M101-T4N-034","parentItemId":null,"revision":1,"payload":{"prompt":"The legal adviser of a manufacturing company in Ota advises managers on contracts but does not direct production workers. The adviser holds:","options":["staff authority","line authority","coercive authority","unity of command"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A legal adviser supports and advises line managers, which is staff authority. Option B, line authority, would apply to someone like a production manager who directs supervisors' work."}},{"itemId":"49573ce3-2aa9-50d9-90b3-cd8f8c1c6771","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"20081e2d-36e1-5c36-af4f-105cb98d490f","sourceKey":"bank:AMS101:M101-T4N-035","parentItemId":null,"revision":1,"payload":{"prompt":"A production manager who directs the work of the supervisors under her exercises:","options":["line authority","referent power","expert power","staff authority"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Directing the work of subordinates along the chain of command is line authority. Option D, staff authority, belongs to advisers such as HR specialists who support line managers rather than direct them."}},{"itemId":"b2a4726d-632e-5e3a-ae7e-268e0adf29d2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4365b755-711c-5cd9-a021-33b3bf0e477a","sourceKey":"bank:AMS101:M101-T4N-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts authority and power?","options":["Authority comes from many bases; power comes only from position","Authority is the broader concept; power is part of authority","Authority is a capacity to influence; power is a right","Authority is a right; power is a capacity to influence decisions"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Authority is a right that comes from a position, while power is the capacity to influence decisions and can come from many places. Option C reverses the two ideas."}},{"itemId":"84819d42-61af-5441-abb8-a81481a4c87a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0977fd8e-1bb3-52d5-8168-31bd86de8ab4","sourceKey":"bank:AMS101:M101-T4N-037","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the broader concept, authority or power?","options":["Neither, because they mean exactly the same thing","Power, because authority is part of power","Authority, because it comes from many bases","Authority, because power is part of authority"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Power is the broader concept, and authority is just one part of it. Option D reverses this, but a person can have power without any formal authority."}},{"itemId":"c2901d90-884c-55b1-a41f-5403fbc829df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25773b68-7376-58a2-aa07-5fa900c4f190","sourceKey":"bank:AMS101:M101-T4N-038","parentItemId":null,"revision":1,"payload":{"prompt":"The legitimacy of a manager's authority comes from:","options":["the position the manager holds","the manager's personal charm","the manager's special knowledge","the manager's ability to punish"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Authority is legitimate because it is attached to the position. Option B, personal charm, describes referent power, and the other two options describe expert and coercive power."}},{"itemId":"901cac66-1254-5d51-8190-d8268b53959b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ed9b6fe-49c4-5dd8-82df-d3c1c3c9b3fe","sourceKey":"bank:AMS101:M101-T4N-039","parentItemId":null,"revision":1,"payload":{"prompt":"The head of procurement at a university resigns. What happens to the authority she held?","options":["It leaves the university with her","It passes automatically to the registrar","It is divided equally among her staff","It stays with the post for her successor"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Authority belongs to the position, not the person, so when a manager leaves, the authority stays with the post. Option A would only make sense if authority were personal, which it is not."}},{"itemId":"9b1116cf-640d-51a7-b719-1103b891c1b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"09f4ccdc-7273-544b-a72a-af80dbc32318","sourceKey":"bank:AMS101:M101-T4N-040","parentItemId":null,"revision":1,"payload":{"prompt":"A secretary in a Lagos firm controls who gets to see the managing director and when. She has no formal authority, yet many staff seek her favour. This shows that:","options":["staff authority is the same as line authority","authority is broader than power","authority belongs to the person, not the post","a person can have power without authority"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Controlling access to the boss's diary gives the secretary influence even though her post carries little formal authority, so she has power without authority. Option B is wrong because power, not authority, is the broader concept."}},{"itemId":"ca3ca500-9ffa-5cb0-b93c-0e9365fa2de0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ad254cf-4b23-57b0-998e-613dead3982f","sourceKey":"bank:AMS101:M101-T4N-041","parentItemId":null,"revision":1,"payload":{"prompt":"How many sources of power are commonly identified?","options":["Five","Three","Six","Four"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Five are identified: legitimate, coercive, reward, expert and referent. Option B, four, is a common slip because it matches the number of contingency factors."}},{"itemId":"4525dbb9-f209-55f6-9adc-0a3dcee3a995","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cddc4759-57a7-53be-aacf-93422394c3ae","sourceKey":"bank:AMS101:M101-T4N-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five bases of power?","options":["Coercive power","Referent power","Functional power","Expert power"],"correctOption":2,"section":"Organization Design and Structure","explanation":"The five bases of power are legitimate, coercive, reward, expert and referent, so functional power is not one of them. Options A and the others are all genuine bases."}},{"itemId":"4a67365e-52fc-5a9d-b226-66d51d6cf672","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"10263871-f55d-5af3-b094-edc91e642779","sourceKey":"bank:AMS101:M101-T4N-043","parentItemId":null,"revision":1,"payload":{"prompt":"Power that comes from the ability to punish or control is:","options":["coercive power","reward power","referent power","legitimate power"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Coercive power rests on the ability to punish or control others. Option B, reward power, is its opposite: it comes from the ability to give something people value."}},{"itemId":"287caff8-95d4-5cdf-9443-273da5deee33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4819674b-685e-50da-ab14-db6e3a30aece","sourceKey":"bank:AMS101:M101-T4N-044","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor in a Port Harcourt firm gets cooperation mainly because she can recommend bonuses and give public praise. She is using:","options":["referent power","reward power","coercive power","expert power"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Influence based on the ability to give something valued, such as pay or praise, is reward power. Option C, coercive power, would rest on the ability to punish, not to reward."}},{"itemId":"33d40fd1-df8f-52c4-b362-72212f867520","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c42112bf-fce8-58a5-ab12-a4385e64a739","sourceKey":"bank:AMS101:M101-T4N-045","parentItemId":null,"revision":1,"payload":{"prompt":"Staff in a university department always follow the advice of a junior IT officer on systems matters because of his special knowledge. His influence is:","options":["expert power","reward power","legitimate power","referent power"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Influence based on special skill or knowledge is expert power. Option C, legitimate power, comes from a formal position, and a junior officer has little of that."}},{"itemId":"f3533655-41c6-54d7-a97b-2978a2c96bb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a246d8c2-339e-5e88-a776-eb7c9b908145","sourceKey":"bank:AMS101:M101-T4N-046","parentItemId":null,"revision":1,"payload":{"prompt":"Power based on personal traits that make others like or admire a person is:","options":["legitimate power","coercive power","expert power","referent power"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Referent power comes from personal traits that make others like or admire you. Option C, expert power, rests on special skill or knowledge rather than on being liked or admired."}},{"itemId":"a3f16f38-73c2-5551-b886-79876e612584","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ad38c93f-3765-5a9c-bc02-e85245e7ea59","sourceKey":"bank:AMS101:M101-T4N-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which base of power is the same as authority?","options":["Referent power","Legitimate power","Expert power","Reward power"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Legitimate power comes from one's position, which is exactly what authority is. Option A, referent power, comes from personal traits that others admire, not from the post."}},{"itemId":"c8cd4205-cb50-52a5-a463-d0bce652b48e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d742ace1-1d0d-5fb2-a037-9eeaefab35d3","sourceKey":"bank:AMS101:M101-T4N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Assigning authority to another person to carry out specific duties is called:","options":["decentralization","delegation","departmentalization","formalization"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Delegation means assigning authority to another person to carry out specific duties. Option C, decentralization, is broader: it describes lower-level managers taking part in decisions across the organization."}},{"itemId":"2938e377-77cd-57e2-ae60-a0bbbe67610a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47130da4-4502-5d69-baf0-e85ce00edc06","sourceKey":"bank:AMS101:M101-T4N-049","parentItemId":null,"revision":1,"payload":{"prompt":"Why does the chain of command matter less in organizations today?","options":["Information technology and empowered employees","More formal rules and procedures","Growth in staff authority","Wider use of unity of command"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Information technology lets employees get information and communicate without going through each level, and empowered employees make more decisions themselves, so the chain of command matters less. Option D is wrong because unity of command is part of the traditional chain of command idea, not a reason it has weakened."}},{"itemId":"a2983c87-0e95-5829-8cb8-89652a050070","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"92c2c1c7-a0ea-5c12-a9f3-07ab649acecc","sourceKey":"bank:AMS101:M101-T4N-050","parentItemId":null,"revision":1,"payload":{"prompt":"An organization has 4,096 operative staff. With a span of control of 8, how many managers does it need?","options":["4,096","512","1,365","585"],"correctOption":3,"section":"Organization Design and Structure","explanation":"With a span of 8 the organization needs 585 managers and has 5 levels including operatives. Option C, 1,365, is the number needed with a narrower span of 4, which shows how narrow spans add managers."}},{"itemId":"508c7902-659a-580f-8f20-4482be094a03","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ab93765-4491-538c-aaca-35e9cffc402d","sourceKey":"bank:AMS101:M101-T4N-051","parentItemId":null,"revision":1,"payload":{"prompt":"An organization with 4,096 operative staff uses a span of control of 4. How many levels (including operatives) will it have?","options":["Seven","Five","Eight","Four"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A span of 4 gives 7 levels, which produces a tall structure. Option B, five levels, is what the same organization would have with a wider span of 8."}},{"itemId":"541b4887-99c6-570f-903c-2e53a8ba760b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c1b4d98b-673c-5261-8fe1-bc3b092bafa3","sourceKey":"bank:AMS101:M101-T4N-052","parentItemId":null,"revision":1,"payload":{"prompt":"A narrow span of control produces which kind of structure?","options":["Tall","Boundaryless","Flat","Thin"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A narrow span means each manager supervises few people, so more levels are needed and the structure becomes tall. Option C, flat, results from a wide span."}},{"itemId":"3a306796-c5a9-5c16-b2c4-101b58a7322e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"479a3829-9623-54d0-a292-f6f9706634c2","sourceKey":"bank:AMS101:M101-T4N-053","parentItemId":null,"revision":1,"payload":{"prompt":"If a manager's span of control becomes too wide, what is the main risk?","options":["The structure becomes taller and slower","The organization needs many more managers","Costs rise because of extra management levels","Effectiveness falls because staff get too little supervision"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A wider span is more efficient, but if it gets too wide, effectiveness falls because each employee receives too little supervision. Options B and the next one describe the effects of a narrow span, not a wide one."}},{"itemId":"7b885c0c-bc83-55d9-9e77-2fce3d7f5fbe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a538fd75-6f35-54ba-a030-3170be09af5f","sourceKey":"bank:AMS101:M101-T4N-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which situation would allow a manager in a Lagos bank to supervise more people effectively?","options":["Staff are new and inexperienced","Staff are spread across distant branches","Staff do complex and very different tasks","Staff are well trained and follow standardized procedures"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Skilled staff who follow standardized procedures need less supervision, so a wider span works. Option A, new and inexperienced staff, would call for a narrower span because they need more guidance."}},{"itemId":"c14dc24c-27e8-51d1-9513-fd4f854535a0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bd7e0e06-2abb-53bc-a095-63b0fb861480","sourceKey":"bank:AMS101:M101-T4N-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the factors that decide the right span of control?","options":["The age of the organization","Location of employees","Employee training and experience","Sophistication of the management information system"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The span of control depends on employee training and experience, similarity and complexity of tasks, location of employees, use of standardized procedures and the sophistication of the information system, so the age of the organization is not among them. Options C and the others are genuine factors."}},{"itemId":"011bab5a-0ebb-5508-b0fc-fa1c6d52e1a4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5657cfc7-9e52-5c3e-9bdc-7e0c2ede7b76","sourceKey":"bank:AMS101:M101-T4N-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of a wide span of control?","options":["The organization needs more managers","Decisions move slowly through many levels","Management costs rise sharply","The manager has many people to control"],"correctOption":3,"section":"Organization Design and Structure","explanation":"With a wide span, one manager has many people to control, which is its main weakness. Options A and the others are actually problems of a narrow span, which needs more managers and more levels."}},{"itemId":"666ebfee-5a6f-5788-84bd-8c0b8f37b54a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05efb1a1-8731-5496-91a0-aa89bfacc8c1","sourceKey":"bank:AMS101:M101-T4N-057","parentItemId":null,"revision":1,"payload":{"prompt":"Organizations have moved towards wider spans of control. Which of the following is NOT a reason for this trend?","options":["To empower employees","To cut costs","To add more levels of management","To speed up decision making"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Wider spans are used to cut costs, speed up decisions, increase flexibility and empower employees, and they reduce rather than add management levels. Options B and the others are genuine reasons for the trend."}},{"itemId":"0894a70d-79e2-5a2c-be93-58488e3feb8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d523ac04-bb26-5818-8a47-a5a295f11dee","sourceKey":"bank:AMS101:M101-T4N-058","parentItemId":null,"revision":1,"payload":{"prompt":"When lower-level managers give input or actually make decisions, the organization is practising:","options":["formalization","work specialization","decentralization","centralization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Decentralization means lower-level managers provide input or make decisions themselves. Option D, centralization, is the opposite: decision making stays at the upper levels."}},{"itemId":"726215a9-81c7-5c36-8b84-f1030c4331ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"34febcb2-3c72-5db1-856a-f98881166906","sourceKey":"bank:AMS101:M101-T4N-059","parentItemId":null,"revision":1,"payload":{"prompt":"Increasing the decision-making discretion of workers is called:","options":["employee empowerment","formalization","work specialization","line authority"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Employee empowerment means giving workers more freedom to make decisions. Option B, formalization, does the opposite by guiding jobs through rules and procedures."}},{"itemId":"eee9a61f-945f-5080-8889-cbf6ad9fc0ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dbef4ee6-6532-504a-81d5-e62bbc4f3573","sourceKey":"bank:AMS101:M101-T4N-060","parentItemId":null,"revision":1,"payload":{"prompt":"In a state hospital, every decision, however small, must be signed off by the unit head. This hospital is best described as:","options":["decentralized","organic","centralized","boundaryless"],"correctOption":2,"section":"Organization Design and Structure","explanation":"When decisions are concentrated at the top, here with the unit head, the organization is centralized. Option A, decentralized, would mean lower-level staff give input or make decisions themselves."}},{"itemId":"a8d087b6-640e-5c67-801a-00caad096461","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c031458-f5ea-5c56-af12-216e4588e769","sourceKey":"bank:AMS101:M101-T4N-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following situations favours more centralization?","options":["The organization is facing a crisis","The company is spread out geographically","The decisions to be made are minor","Lower-level managers are capable and want a say"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Centralization fits when the organization faces a crisis, as well as when the environment is stable, the company is large and decisions are significant. Option D and the remaining options are conditions that favour decentralization."}},{"itemId":"fcc359ca-25ea-5a91-a1de-ac344956a14b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"366d8be2-8e45-580a-a8b2-bb73ef2957f5","sourceKey":"bank:AMS101:M101-T4N-062","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following situations favours more decentralization?","options":["The environment is stable","The environment is complex and uncertain","The decisions are very significant","Lower-level managers lack experience"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A complex and uncertain environment calls for decisions to be made closer to the action, which favours decentralization. Option A, a stable environment, is one of the conditions that suits centralization."}},{"itemId":"be16f41b-ecc8-53a2-9427-51dde9d3c455","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e7a3fa27-44c0-53cc-9e07-e39872ae8a3f","sourceKey":"bank:AMS101:M101-T4N-063","parentItemId":null,"revision":1,"payload":{"prompt":"A bank has branches spread across many states, an open culture and capable branch managers who want a say. The design that best suits it is:","options":["more centralization","higher formalization","more decentralization","narrower spans of control"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Geographic spread, an open culture and capable lower-level managers who want input all favour decentralization. Option A, centralization, suits stable settings and less experienced lower-level managers."}},{"itemId":"15c8d924-2e3c-57b2-9809-ec4e6e3f98fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b5b9485-5572-5dc8-9c5a-2f510313e30f","sourceKey":"bank:AMS101:M101-T4N-064","parentItemId":null,"revision":1,"payload":{"prompt":"A university department requires every request to be made on a standard form and handled according to a detailed rulebook. This department has:","options":["high decentralization","low formalization","wide spans of control","high formalization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Formalization is the degree to which jobs are standardized and governed by rules and procedures, so a detailed rulebook and standard forms mean high formalization. Option B would describe a department with few rules and much employee discretion."}},{"itemId":"44c53442-05e0-5bb0-854c-54c1767bff41","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"82989a4e-e908-5a0b-a19c-9b475359cc1d","sourceKey":"bank:AMS101:M101-T4N-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of an organic organization?","options":["Free flow of information","Narrow spans of control","Low formalization","Cross-hierarchical teams"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Organic organizations have wide spans of control, so narrow spans do not fit. Options D and the others, cross-hierarchical teams, free flow of information and low formalization, are all organic features."}},{"itemId":"747ab9bf-b1d6-5fb0-a571-1b92fe7ccd89","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"24cdf0a8-dbb0-5d4a-8226-3d3dd343b78e","sourceKey":"bank:AMS101:M101-T4N-066","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair of features both describe a mechanistic organization?","options":["Cross-functional teams and low formalization","Decentralization and wide spans of control","Free flow of information and cross-hierarchical teams","Centralization and a clear chain of command"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Mechanistic organizations are centralized and have a clear chain of command, along with narrow spans and high formalization. Option B and the other options list organic features."}},{"itemId":"5b1b542a-6032-59da-b7ae-e1906f525121","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03cff3be-a4ba-5294-b4b5-ef2a56c96f26","sourceKey":"bank:AMS101:M101-T4N-067","parentItemId":null,"revision":1,"payload":{"prompt":"How many contingency factors are said to decide the right organizational structure?","options":["Six","Three","Five","Four"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The four contingency factors are strategy, size, technology and environmental uncertainty. Option B, three, may be confused with the three strategic focuses of innovation, cost minimization and imitation."}},{"itemId":"9e8a20f8-51f1-5797-9f0a-bf3db7e3447c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b82f612b-830e-5498-9e6d-f82c4f95cd85","sourceKey":"bank:AMS101:M101-T4N-068","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the contingency factors that decide the right structure?","options":["Formalization","Technology","Size","Strategy"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The contingency factors are strategy, size, technology and environmental uncertainty, while formalization is one of the six elements of design that those factors shape. Options D and the others are genuine contingency factors."}},{"itemId":"6e9ff6ab-1e4b-55c9-b2b2-34e3270b4a88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00fa92a6-731f-50a5-ba88-42b76db9afe9","sourceKey":"bank:AMS101:M101-T4N-069","parentItemId":null,"revision":1,"payload":{"prompt":"A company whose strategy is to keep bringing out meaningful and unique new products should adopt which structure?","options":["Simple","Functional","Organic","Mechanistic"],"correctOption":2,"section":"Organization Design and Structure","explanation":"An innovation strategy needs flexibility and free flow of ideas, so it fits an organic structure. Option D, mechanistic, suits a cost-minimization strategy that needs tight control."}},{"itemId":"bf292765-c784-5570-b971-fc4372d1a223","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c30db475-5b12-55c6-82ff-ac77e2456d3f","sourceKey":"bank:AMS101:M101-T4N-070","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos-based manufacturer competes mainly by keeping costs tightly controlled. Which structure best fits this strategy?","options":["Organic","Boundaryless","Team","Mechanistic"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A cost-minimization strategy needs tight control and efficiency, which a mechanistic structure provides. Option A, organic, fits an innovation strategy instead."}},{"itemId":"fb8d6b32-367e-55a9-b886-08defc78c195","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4fdb620-7118-5e86-9565-61f13eda55c8","sourceKey":"bank:AMS101:M101-T4N-071","parentItemId":null,"revision":1,"payload":{"prompt":"A firm that copies market leaders to lower its risk and gain profit is following an imitation strategy. Which structure suits it?","options":["A purely organic structure","A mix of mechanistic and organic","A virtual structure","A purely mechanistic structure"],"correctOption":1,"section":"Organization Design and Structure","explanation":"An imitation strategy combines the tight cost control of a mechanistic design with the flexibility of an organic one, so it suits a mix of both. Option A fits a pure innovation strategy."}},{"itemId":"4ef9ae8f-2f59-5431-ba89-d1f4401d4753","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eb36b7e9-c1bf-50dc-9111-ad8fc6f7fd99","sourceKey":"bank:AMS101:M101-T4N-072","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three focuses of strategic frameworks that shape structure?","options":["Diversification","Innovation","Imitation","Cost minimization"],"correctOption":0,"section":"Organization Design and Structure","explanation":"The three strategic focuses that shape structure are innovation, cost minimization and imitation. Diversification is not among them, while options B and the others are all part of the framework."}},{"itemId":"e237d401-8d2a-54ca-8a73-798efb58b27d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d78acba-4915-578b-981d-4b4bca641b09","sourceKey":"bank:AMS101:M101-T4N-073","parentItemId":null,"revision":1,"payload":{"prompt":"Larger organizations tend to have more of all of the following EXCEPT:","options":["specialization","decentralization","rules","departmentalization"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Larger organizations have more specialization, departmentalization, centralization and rules, which makes them more mechanistic. They do not tend to have more decentralization; options A and the others are features that grow with size."}},{"itemId":"51c134e5-beac-58fc-b687-ab9e0a1e0994","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a926db84-5bb1-5f34-856b-4e088b4965d9","sourceKey":"bank:AMS101:M101-T4N-074","parentItemId":null,"revision":1,"payload":{"prompt":"Who studied small manufacturing firms to find out how technology relates to structure?","options":["Frederick Taylor","Joan Woodward","Max Weber","Henri Fayol"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Joan Woodward studied small manufacturing firms in southern England and grouped them by the technology they used. Option D, Henri Fayol, is linked with principles such as unity of command, not the technology studies."}},{"itemId":"ab0c3123-02fe-5b66-b87b-6d3b8231bcfc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a3f5570-f1f4-59fc-b5b9-0755f0d88a79","sourceKey":"bank:AMS101:M101-T4N-075","parentItemId":null,"revision":1,"payload":{"prompt":"In Woodward's study, firms that produced units or small batches of custom work used:","options":["modular production","unit production","process production","mass production"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Unit production means making units or small batches, often custom work, and it is the least complex type. Option D, mass production, refers to large-batch production."}},{"itemId":"6e1db1b0-16b6-5bbb-ba37-9dcbee74699d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d7fb870-949b-59a6-b734-44ba75e83c04","sourceKey":"bank:AMS101:M101-T4N-076","parentItemId":null,"revision":1,"payload":{"prompt":"In Woodward's classification, which type of production is the least technically complex?","options":["Unit production","Process production","Mass production","Continuous production"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Unit production, which makes units or small batches, is the least complex. Option C, mass production, is moderately complex, and process production is the most complex."}},{"itemId":"f88e8a79-c2fa-5c64-a9ae-8cca284e26b1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"18d5308a-17e8-5cd5-807a-0f4e990251b2","sourceKey":"bank:AMS101:M101-T4N-077","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing of Woodward's technology type and best structure is correct?","options":["Process production - organic","Unit production - mechanistic","Mass production - organic","Process production - mechanistic"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Woodward found that unit and process production work best with organic structures, while mass production works best with a mechanistic one. Option C is the classic trap: mass production goes with mechanistic, not organic."}},{"itemId":"2a17070d-fcd8-568d-bd10-8c321ee7e482","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bae34722-07bf-5bdf-b10c-ef380c10bf7e","sourceKey":"bank:AMS101:M101-T4N-078","parentItemId":null,"revision":1,"payload":{"prompt":"A refinery in Port Harcourt runs a continuous-process operation around the clock. In Woodward's terms, its technology is:","options":["batch production","mass production","process production","unit production"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Continuous-process production is what Woodward called process production, the most technically complex type. Option B, mass production, means large-batch production, not a continuous flow."}},{"itemId":"ea7db42e-fc26-5f32-9edf-f2927cab544c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6c5a03c1-cc5f-5fa3-9bcf-d12194a57a29","sourceKey":"bank:AMS101:M101-T4N-079","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fintech firm faces rapidly changing regulation and competitors that release new products often. Which structure suits this environment?","options":["Organic","Mechanistic","Simple","Functional"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A dynamic, uncertain environment calls for a flexible, adaptive organic structure. Option B, mechanistic, suits stable environments where tight control and efficiency matter most."}},{"itemId":"24c194ad-aa15-531f-8ece-2d84bb207a5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f4f552d-f398-536b-9eab-4af368e9cabf","sourceKey":"bank:AMS101:M101-T4N-080","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the forces pushing firms to become more organic?","options":["Stable and predictable customer demand","Global competition","Customers demanding faster delivery","Faster product innovation by competitors"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Global competition, faster innovation by rivals, knowledge management and customers demanding higher quality and faster delivery all push firms towards organic designs. A stable, predictable market would favour a mechanistic design instead, while options B and the others are genuine pressures."}},{"itemId":"a0e9a8af-4cac-554f-bd1a-930ef8fa1b7f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c997004c-4844-5229-9e6a-354101c98b17","sourceKey":"bank:AMS101:M101-T4N-081","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a weakness of the simple structure?","options":["Activities and resources are duplicated","Each employee has two bosses","Relying on one person is risky","Functional specialists become isolated"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A simple structure centralizes authority in one person, which is risky, and it does not suit a growing firm. Option A, duplication of resources, is the weakness of the divisional structure."}},{"itemId":"17d993a4-162c-5bbf-8a9f-88bd44031eff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"805bb12a-9bb2-5f51-be91-071c0baf352c","sourceKey":"bank:AMS101:M101-T4N-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a strength of the simple structure?","options":["It assigns specialists to projects","It focuses division managers on results","It is fast, flexible and cheap to run","It achieves cost savings from specialization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"The simple structure is fast, flexible, cheap to run and has clear accountability. Option D, cost savings from specialization, is the strength of the functional structure."}},{"itemId":"047d6e7a-d1ec-5939-ae8f-eafd435b2ae2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03fa2eaa-1466-5eed-acf7-599d9c45acd1","sourceKey":"bank:AMS101:M101-T4N-083","parentItemId":null,"revision":1,"payload":{"prompt":"In which structure do functions chase their own goals and lose sight of the organization as a whole?","options":["Divisional","Functional","Matrix","Simple"],"correctOption":1,"section":"Organization Design and Structure","explanation":"In a functional structure, each department of related specialists can pursue its own goals and forget the bigger picture, and specialists may become isolated. Option D, divisional, has a different weakness: duplication of activities and resources."}},{"itemId":"8c984d46-5f73-5191-9839-4c658bafd854","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"304a9d18-a65d-50af-a1d7-8e4c5c170df9","sourceKey":"bank:AMS101:M101-T4N-084","parentItemId":null,"revision":1,"payload":{"prompt":"The main strength of a functional structure is:","options":["flexible teams across levels","cost savings from specialization","fast decisions by one owner","focus on results by division managers"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Grouping similar specialists together gives cost savings from specialization, and people with similar tasks work together. Option D, focus on results, is the strength of the divisional structure."}},{"itemId":"0ed1b41c-a063-547a-bfcf-c682b4a92b50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"002d304b-1a90-5590-b7bb-5888ce202c9b","sourceKey":"bank:AMS101:M101-T4N-085","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos conglomerate runs separate, self-contained units for foods, cement and sugar, each with a manager responsible for its own results. This is a:","options":["simple structure","matrix structure","divisional structure","functional structure"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Separate, autonomous business units, each responsible for its own product and results, form a divisional structure. Option D, functional, would group jobs by occupational specialty instead of by business unit."}},{"itemId":"d2096e14-567c-5a78-9c5c-210477a98d1c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"50f6a103-6c9d-505b-8552-9a82b25f50d4","sourceKey":"bank:AMS101:M101-T4N-086","parentItemId":null,"revision":1,"payload":{"prompt":"As a business grows, its structure typically moves through which sequence?","options":["Simple, then divisional, then functional","Simple, then functional, then divisional","Divisional, then functional, then simple","Functional, then simple, then divisional"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A simple structure often grows into a functional one and then into a divisional one as the firm takes on more employees. Option D wrongly places the functional structure before the simple one."}},{"itemId":"1d0701b0-1b85-5128-8cc6-9358fe1a0778","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d30cef88-d94f-5e89-a634-606bd8b9697d","sourceKey":"bank:AMS101:M101-T4N-087","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a traditional organizational design?","options":["Simple","Functional","Divisional","Matrix"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The traditional designs are simple, functional and divisional, while the matrix is a contemporary design. Options A and the others are all traditional."}},{"itemId":"a9797818-7d0b-5257-9703-41256660acbe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6b44ea24-c8a1-505d-8c25-59d5029dc32f","sourceKey":"bank:AMS101:M101-T4N-088","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a contemporary organizational design?","options":["Functional structure","Divisional structure","Project structure","Simple structure"],"correctOption":2,"section":"Organization Design and Structure","explanation":"The project structure, along with team, matrix, boundaryless and learning designs, is contemporary. Option D, the simple structure, is a traditional design together with functional and divisional."}},{"itemId":"11b1cf56-4ba3-529a-87c3-309cf64694d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"74b2ad01-2ea4-504b-98c4-ec8a76b71477","sourceKey":"bank:AMS101:M101-T4N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a weakness of the team structure?","options":["Functions lose sight of the whole","Activities and resources are duplicated","There is no clear chain of command","Authority rests in one person"],"correctOption":2,"section":"Organization Design and Structure","explanation":"In a team structure there is no clear chain of command, and teams are under heavy pressure to perform. Option B, duplication of resources, is the weakness of the divisional structure."}},{"itemId":"7e0c8842-6aed-5fd4-abf6-5b204205abd3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b977ca6b-abd7-534b-9c59-14debc4b53a5","sourceKey":"bank:AMS101:M101-T4N-090","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a strength of the team structure?","options":["Clear accountability to one owner","A clear chain of command","Fewer barriers between functional areas","Cost savings from grouping specialists"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Team structures involve and empower employees and reduce barriers between functional areas. Option A, clear accountability to one owner, is a strength of the simple structure."}},{"itemId":"f6406d31-4f76-5b75-beea-5aadbe8fc02a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84acc3db-f26e-53ae-8a19-fe7d166bccab","sourceKey":"bank:AMS101:M101-T4N-091","parentItemId":null,"revision":1,"payload":{"prompt":"In a matrix structure, each employee reports to which two bosses?","options":["The chief executive and the board chairman","The line manager and the staff adviser","The division manager and the team leader","The functional manager and the project manager"],"correctOption":3,"section":"Organization Design and Structure","explanation":"In a matrix, each employee has two bosses: the manager of their functional department and the manager of the project they are assigned to. Option A names top governance roles, not the dual reporting of a matrix."}},{"itemId":"fcb9affc-8768-5e72-9b54-187eec9e1c90","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"939eebf4-4f31-5f47-891e-96849ec626d5","sourceKey":"bank:AMS101:M101-T4N-092","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a weakness of the matrix structure?","options":["Slow decision making","Relying on one person is risky","Task and personality conflicts","Rigid design that resists change"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Matrix structures often suffer task and personality conflicts, and assigning people to projects is complex. Option D is wrong because the matrix is actually a fluid, flexible design with faster decision making."}},{"itemId":"7387f971-a115-5d70-9c9f-93fe07dd90d1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc4abd77-0191-5dda-812e-51fca6f35170","sourceKey":"bank:AMS101:M101-T4N-093","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a strength of the matrix structure?","options":["No need to assign people to projects","Strict unity of command","A fluid, flexible design that can respond to change","Very low cost of coordination"],"correctOption":2,"section":"Organization Design and Structure","explanation":"The matrix is a fluid, flexible design that can respond to change and allows faster decisions. Option B is wrong because the matrix breaks unity of command by giving employees two bosses."}},{"itemId":"88e55da3-644c-5ffd-afb4-e435684bda16","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f0530bd8-93d0-5666-83aa-626fd9eacb12","sourceKey":"bank:AMS101:M101-T4N-094","parentItemId":null,"revision":1,"payload":{"prompt":"At an engineering consultancy in Abuja, staff move from one project to the next and have no formal department to return to between projects. This is a:","options":["matrix structure","functional structure","divisional structure","project structure"],"correctOption":3,"section":"Organization Design and Structure","explanation":"In a project structure, employees work continuously on projects and carry their skills to the next one, with no formal departments to return to. Option A, matrix, is tempting, but in a matrix employees still belong to a functional department."}},{"itemId":"198df988-0d28-5a94-a9d8-2c783a62deb6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05026f0e-83e3-5f94-9e46-1557d9a7415a","sourceKey":"bank:AMS101:M101-T4N-095","parentItemId":null,"revision":1,"payload":{"prompt":"What mainly distinguishes a project structure from a matrix structure?","options":["In a project structure there are no formal departments to return to","In a project structure each employee has two bosses","In a project structure authority is held by one person","In a project structure work is grouped by function only"],"correctOption":0,"section":"Organization Design and Structure","explanation":"A project structure is an advanced form of matrix in which employees have no home department to return to after a project. Option B describes the matrix itself, where each employee has a functional boss and a project boss."}},{"itemId":"47c11a07-e45a-5c26-add7-b00015bc9d4f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ecdc33f-061f-58be-b234-a60a00283999","sourceKey":"bank:AMS101:M101-T4N-096","parentItemId":null,"revision":1,"payload":{"prompt":"In a boundaryless organization, the horizontal boundaries are those:","options":["between countries","between the firm and its suppliers","between functions","between levels"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Horizontal boundaries separate functions, while vertical boundaries separate levels. Option D describes vertical boundaries, and boundaries with suppliers and customers are external."}},{"itemId":"6ffd038b-9405-58b3-967a-b80fd4dc78fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a9abbcf-af2c-5644-8e2a-ce2d22ba9a54","sourceKey":"bank:AMS101:M101-T4N-097","parentItemId":null,"revision":1,"payload":{"prompt":"Boundaries in an organization can be minimized or removed by using:","options":["tall structures with narrow spans","simple or functional designs","functional or divisional designs","virtual or network designs"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Virtual and network designs remove or minimize boundaries by relying on outside specialists and suppliers. Option B lists traditional designs, which keep firm boundaries in place."}},{"itemId":"ba9956e2-b67a-54fb-80e6-1f0922a38c9c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d251b44-ada8-5865-ae62-6b82b6a47f4a","sourceKey":"bank:AMS101:M101-T4N-098","parentItemId":null,"revision":1,"payload":{"prompt":"How many forms of boundaryless organization are usually identified?","options":["Five","Two","Four","Three"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Three forms are identified: virtual, network and modular. Option B, two, is tempting because only virtual and network designs are often mentioned together, but the modular form is the third."}},{"itemId":"d4dd2593-cb26-5b24-b95e-c9e7da87b003","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"86374627-b8ac-5f7b-b2a4-55659044e9cd","sourceKey":"bank:AMS101:M101-T4N-099","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos logistics company keeps its own staff for core operations but outsources accounting, payroll and HR to outside firms. This is best described as a:","options":["modular organization","virtual organization","matrix organization","network organization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A network organization uses its own staff for some work and outsources major or non-core functions to outside suppliers so it can focus on what it does best. Option B, virtual, relies on outside specialists hired temporarily for opportunities as they arise, rather than ongoing outsourcing of functions."}},{"itemId":"060ee9ef-983d-5899-89f6-794866bb0020","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5ca72e25-21d0-57dd-89b8-221160c9f031","sourceKey":"bank:AMS101:M101-T4N-100","parentItemId":null,"revision":1,"payload":{"prompt":"A consulting firm in Victoria Island has five full-time staff and hires outside specialists temporarily whenever a new contract comes in. This is a:","options":["network organization","modular organization","virtual organization","project organization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A virtual organization has a small core of full-time employees and temporarily hires outside specialists for opportunities as they arise. Option A, network, outsources major functions such as manufacturing on a continuing basis."}},{"itemId":"86947f4e-0157-5574-92ec-68ae41151d6b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a56eaea-1fed-5ee7-ab0c-d9c13d5b565f","sourceKey":"bank:AMS101:M101-T4N-101","parentItemId":null,"revision":1,"payload":{"prompt":"A phone company buys screens, batteries and chips from outside suppliers and assembles them into finished handsets. It is a:","options":["divisional organization","network organization","virtual organization","modular organization"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A modular organization uses outside suppliers for product components and then assembles them into final products. Option B, network, outsources whole functions such as manufacturing, not just components for assembly."}},{"itemId":"06d5a622-0574-556d-a025-31b3d423eb41","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a5cfcac8-2245-503c-9823-b9b2e4c9a689","sourceKey":"bank:AMS101:M101-T4N-102","parentItemId":null,"revision":1,"payload":{"prompt":"Teams that work across levels and with outside agencies help an organization to:","options":["remove boundaries","narrow its spans of control","increase formalization","strengthen unity of command"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Teams across levels and work with outside agencies remove internal and external boundaries, which is the idea behind the boundaryless organization. Option D is wrong because such cross-level teams weaken, not strengthen, a single line of command."}},{"itemId":"527ac98c-4ff2-597a-9f86-67addfd3b25d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d2914567-8056-5177-ab8c-e6cd68b3c001","sourceKey":"bank:AMS101:M101-T4N-103","parentItemId":null,"revision":1,"payload":{"prompt":"How many current organizational design challenges are commonly identified?","options":["Three","Four","Six","Five"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Four challenges are identified: keeping employees connected, managing global structural issues, building a learning organization and designing flexible work arrangements. Option A, five, matches the number of flexible work arrangements, not the challenges."}},{"itemId":"5e9d998c-d1ff-5bf7-b8a5-59b637485fd0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c991d208-f220-56e6-8bb9-82cd75f3f704","sourceKey":"bank:AMS101:M101-T4N-104","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of today's organizational design challenges?","options":["Designing flexible work arrangements","Keeping employees connected","Increasing work specialization","Building a learning organization"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Today's challenges are keeping employees connected, managing global structural issues, building a learning organization and designing flexible work arrangements. Increasing work specialization is not one of them, while options B and the others are."}},{"itemId":"af382ea7-e70b-52ee-b884-e8371b5e9ea0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7837b064-1234-583e-afdf-9d1f44e73b6e","sourceKey":"bank:AMS101:M101-T4N-105","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos firm's staff are spread across sites and often on the move, so managers rely on technology to keep them in touch. This addresses the challenge of:","options":["designing a contingent workforce","building a learning organization","keeping employees connected","managing global structural issues"],"correctOption":2,"section":"Organization Design and Structure","explanation":"When staff are spread out and mobile, using technology to keep them in touch addresses the challenge of keeping employees connected. Option D, global structural issues, is about how structures differ across countries and cultures."}},{"itemId":"46b7f418-60a4-5288-87cc-7d8aaaef32c7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71890281-e2c5-5db2-a0db-2f67bba3a3d7","sourceKey":"bank:AMS101:M101-T4N-106","parentItemId":null,"revision":1,"payload":{"prompt":"Managing global structural issues mainly requires managers to:","options":["standardize jobs through strict rules","widen every manager's span of control","outsource all non-core functions","understand how culture shapes structure"],"correctOption":3,"section":"Organization Design and Structure","explanation":"Structures differ between countries and cultures, so managers must understand how culture shapes structure. Option C describes a network organization, which is a design choice rather than the global structural challenge."}},{"itemId":"02380274-e6ca-5ae2-82d9-5921663310cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d8c7e0b-3fa1-5f7f-b27f-fbd5b13c1c0c","sourceKey":"bank:AMS101:M101-T4N-107","parentItemId":null,"revision":1,"payload":{"prompt":"An employee of an Ikeja insurance company works from home and stays linked to the office through the internet and video calls. This arrangement is:","options":["job sharing","flextime","telecommuting","a compressed workweek"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Working from home while linked to the workplace by technology is telecommuting. Option B, flextime, lets staff vary their hours within limits but does not by itself mean working from home."}},{"itemId":"0fd3861d-a564-5353-9f30-060417af30a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d778f3dd-fedf-594a-9cb9-ef01c75593af","sourceKey":"bank:AMS101:M101-T4N-108","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a Lagos hospital work four 10-hour days instead of five 8-hour days. This is:","options":["job sharing","a compressed workweek","telecommuting","flextime"],"correctOption":1,"section":"Organization Design and Structure","explanation":"A compressed workweek means working longer hours each day but fewer days each week. Option D, flextime, keeps the weekly hours fixed but lets staff choose when to work within limits, without cutting the number of days."}},{"itemId":"a58c9666-ab8d-53f4-9841-3ccc1394f7e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e91b01f7-e349-57ec-92a6-147d75226623","sourceKey":"bank:AMS101:M101-T4N-109","parentItemId":null,"revision":1,"payload":{"prompt":"A bank requires 40 hours a week but lets staff choose their start and finish times within set limits. This arrangement is:","options":["a compressed workweek","job sharing","flextime","a contingent workforce"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Flextime sets a number of hours a week but allows staff to vary their hours within limits. Option A, a compressed workweek, would mean longer days and fewer working days, not flexible start and finish times."}},{"itemId":"64273c2c-338d-57f2-8b60-69f019b2de20","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3455c8b6-93cc-5c6f-b00b-906f0dc8dde1","sourceKey":"bank:AMS101:M101-T4N-110","parentItemId":null,"revision":1,"payload":{"prompt":"Two part-time lecturers in a university department split one full-time teaching post between them. This is:","options":["job sharing","a compressed workweek","flextime","telecommuting"],"correctOption":0,"section":"Organization Design and Structure","explanation":"Job sharing is when two or more people split one full-time job. Option D, telecommuting, is about where work is done, not about dividing one job between people."}},{"itemId":"ee6116bf-de99-54aa-bbe2-2616b8353257","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"001a42c5-9add-5ae0-8d94-4ad55416f7b3","sourceKey":"bank:AMS101:M101-T4N-111","parentItemId":null,"revision":1,"payload":{"prompt":"Temporary, freelance or contract workers used as demand requires make up the:","options":["project structure","job-sharing team","virtual organization","contingent workforce"],"correctOption":3,"section":"Organization Design and Structure","explanation":"The contingent workforce consists of temporary, freelance or contract workers brought in as demand requires. Option C, the virtual organization, is a whole design with a small core plus outside specialists, not a type of work arrangement."}},{"itemId":"0de48c42-58cb-5c7f-adc6-bf1bf85621a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"96fc89a2-890c-5aa2-b1fd-7c4f338c45a1","sourceKey":"bank:AMS101:M101-T4N-113","parentItemId":null,"revision":1,"payload":{"prompt":"In a learning organization, leadership is characterized by:","options":["decisions made by one owner","strict control from the top","a shared vision and collaboration","a clear and rigid chain of command"],"correctOption":2,"section":"Organization Design and Structure","explanation":"Leadership in a learning organization is built on a shared vision and collaboration. Option B, strict control from the top, describes a mechanistic approach, not a learning organization."}},{"itemId":"adcfb5a2-d3ed-5f67-8add-2d0ec2c8f2bb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"67d88b9e-d126-5135-a3ad-b4ddf0c78d79","sourceKey":"bank:AMS101:M101-T4N-114","parentItemId":null,"revision":1,"payload":{"prompt":"How is information shared in a learning organization?","options":["Only through the formal chain of command","Only among top managers","Openly, in a timely and accurate way","Only on a need-to-know basis"],"correctOption":2,"section":"Organization Design and Structure","explanation":"A learning organization shares information openly, in a timely and accurate way. Option D, need-to-know sharing, would block the learning that depends on information."}},{"itemId":"e4e79e2d-4104-5176-9ee3-8eab26bbee7b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c8bb80d-a65a-5be1-bfaf-4e60f37d7d62","sourceKey":"bank:AMS101:M101-T4N-115","parentItemId":null,"revision":1,"payload":{"prompt":"The culture of a learning organization is marked by:","options":["centralized decision making","strict rules and high formalization","competition between isolated departments","strong relationships, community, caring and trust"],"correctOption":3,"section":"Organization Design and Structure","explanation":"A learning organization's culture features strong relationships, a sense of community, caring and trust. Option B, strict rules and high formalization, describes a mechanistic organization."}},{"itemId":"0527d1f8-4405-50aa-9041-5eccbf7d9238","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f542ea53-62b6-5fb7-b8a8-fea7fa2e8904","sourceKey":"bank:AMS101:M101-T4N-116","parentItemId":null,"revision":1,"payload":{"prompt":"In terms of design, a learning organization is characterized by:","options":["tall structure and narrow spans","boundaryless structure, teams and empowerment","rigid departmentalization","high specialization and formalization"],"correctOption":1,"section":"Organization Design and Structure","explanation":"The design of a learning organization is boundaryless, team-based and built on empowerment. Option A, a tall structure with narrow spans, belongs to a mechanistic design."}},{"itemId":"f6502211-c3c0-5a6f-a773-771beed1c779","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"60b3f43b-aa94-539f-a0b9-3c991b433608","sourceKey":"bank:AMS101:M101-T4N-117","parentItemId":null,"revision":1,"payload":{"prompt":"At a Lagos bank, every employee is expected to take an active part in identifying and solving work-related problems. This is a feature of:","options":["a functional structure","a learning organization","a simple structure","a mechanistic organization"],"correctOption":1,"section":"Organization Design and Structure","explanation":"In a learning organization, every member takes an active part in identifying and solving work-related problems. Option C, a simple structure, centralizes authority in one person, so problem solving is not spread across all members."}},{"itemId":"7e444407-dc5b-51d7-a816-3decc69f7194","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"76de4bc2-1e44-564b-9b7e-4f41a15bb731","sourceKey":"bank:AMS101:M101-T4N-118","parentItemId":null,"revision":1,"payload":{"prompt":"How many elements of organizational design are there?","options":["Five","Seven","Four","Six"],"correctOption":3,"section":"Organization Design and Structure","explanation":"There are six: work specialization, departmentalization, chain of command, span of control, centralization versus decentralization, and formalization. Option C, four, is the number of contingency factors, not design elements."}},{"itemId":"e4910769-c96a-5d59-bb0b-2ab05445d6b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0d83e25-dbea-519d-a6a9-72178d6cabc8","sourceKey":"bank:AMS101:M101-T4N-119","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the six elements of organizational design?","options":["Formalization","Environmental uncertainty","Chain of command","Span of control"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Environmental uncertainty is a contingency factor that influences structure, not one of the six design elements. Options D and the others are genuine elements alongside work specialization, departmentalization and centralization."}},{"itemId":"237a5b1c-ed11-5a78-961f-f2ef72f0b30d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d9028a3-6e6f-53fa-8f37-c4eee84c1613","sourceKey":"bank:AMS101:M101-T4N-120","parentItemId":null,"revision":1,"payload":{"prompt":"Taken together, the six elements of organizational design decide whether a structure is:","options":["tall or thin","mechanistic or organic","virtual or network","line or staff"],"correctOption":1,"section":"Organization Design and Structure","explanation":"Combining the six elements, for example spans, centralization and formalization, determines whether a structure is mechanistic or organic. Option D, line or staff, refers to types of authority, not overall structure."}},{"itemId":"f4bc6d4c-1960-5bc7-9fcf-06f56f828163","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c57be29-258c-5963-bf09-8649c4635b1d","sourceKey":"bank:AMS101:M101-T5N-001","parentItemId":null,"revision":1,"payload":{"prompt":"The part of management concerned with getting, training, keeping and rewarding the right people is called:","options":["Human resource management","Strategic management","Operations management","Organizational behaviour"],"correctOption":0,"section":"Managing Human Resources","explanation":"Human resource management (HRM) is the part of management that deals with getting, training, keeping and rewarding the right people. Option C is about producing goods and services, and option B is about setting the long-term direction of the whole firm, not about managing people as such."}},{"itemId":"d06bc7c2-1d56-5bef-8c0d-55e8ee282e4f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83ced43e-2245-583c-acdf-25ac350bc200","sourceKey":"bank:AMS101:M101-T5N-002","parentItemId":null,"revision":1,"payload":{"prompt":"In the older list of management functions, human resource management is called:","options":["Directing","Coordinating","Staffing","Organizing"],"correctOption":2,"section":"Managing Human Resources","explanation":"In the older list of functions, the work of HRM appears as staffing: recruiting, selecting, training, appraising and retaining employees. Option D is about arranging tasks and structure, and option A is about guiding and instructing people already in place, not getting and keeping them."}},{"itemId":"49ea4720-9685-590e-b996-c43720438082","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6832c687-5abb-568f-b503-ed7240729012","sourceKey":"bank:AMS101:M101-T5N-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of the staffing function?","options":["Budgeting","Retaining employees","Selecting employees","Performance appraisal"],"correctOption":0,"section":"Managing Human Resources","explanation":"Budgeting is a financial planning activity, so it is not part of staffing. Staffing covers recruiting, selecting, training, appraising and retaining employees, which is why option D (performance appraisal) is part of staffing even though some students wrongly think it belongs only to controlling."}},{"itemId":"bcf8e285-e158-55ee-860c-29ebbddd7c5b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48a0b8dc-d01c-5596-9081-76a8a682a763","sourceKey":"bank:AMS101:M101-T5N-004","parentItemId":null,"revision":1,"payload":{"prompt":"Performance appraisal is part of which management function in the older list of functions?","options":["Coordinating","Staffing","Organizing","Planning"],"correctOption":1,"section":"Managing Human Resources","explanation":"Appraising employees is one of the staffing activities, alongside recruiting, selecting, training and retaining them. Option D is about setting goals and deciding how to reach them, and option C is about arranging work and resources, so neither covers appraising people."}},{"itemId":"1da3fa2f-eeb0-57be-9e72-c17b14f4ed22","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b47a3fa2-e99b-5dac-9ad7-eb43abae4245","sourceKey":"bank:AMS101:M101-T5N-005","parentItemId":null,"revision":1,"payload":{"prompt":"HRM is said to be important for how many main reasons?","options":["Five","Four","Two","Three"],"correctOption":3,"section":"Managing Human Resources","explanation":"There are three reasons: HRM can give a firm competitive advantage, it is an important part of strategy, and the way people are treated strongly affects performance. Option C leaves one of these out, while options B and A add reasons that are not part of the list."}},{"itemId":"c372f062-509f-5249-9aa5-3095555ae554","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07b4828b-c53c-54e2-be29-25649e7d4aff","sourceKey":"bank:AMS101:M101-T5N-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the reasons why HRM is important?","options":["It removes the need for managers to plan","It is an important part of an organization's strategy","The way people are treated affects performance","It can be a significant source of competitive advantage"],"correctOption":0,"section":"Managing Human Resources","explanation":"HRM does not remove the need for planning; in fact HR planning is itself one of its activities. Options B, C and D are the three real reasons HRM matters: competitive advantage, strategy and the effect of people's treatment on performance."}},{"itemId":"0be1639f-8514-5471-9a2a-3a927aed3095","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5720af7b-2e98-5527-a777-67660e6a67da","sourceKey":"bank:AMS101:M101-T5N-007","parentItemId":null,"revision":1,"payload":{"prompt":"The MD of a Lagos bank says, \"Any rival can buy our software, but they cannot copy our well-trained, motivated staff.\" Which reason for the importance of HRM is she stressing?","options":["HRM replaces collective bargaining","People can be a source of competitive advantage","HRM is required by the Labour Act","HRM reduces the need for training"],"correctOption":1,"section":"Managing Human Resources","explanation":"She is saying her people give the bank an edge rivals cannot easily copy, which is the idea that people managed well can give a firm competitive advantage. Option C is wrong because laws shape HRM practices but are not the reason given here, and options D and A are not reasons HRM matters at all."}},{"itemId":"1cabfff8-9f16-5dba-8024-2295d35414ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af2a8657-4241-5999-a2cb-3e7666971fd9","sourceKey":"bank:AMS101:M101-T5N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Work practices that lead to both high individual and high organizational performance are called:","options":["High-performance work practices","Collective bargaining agreements","Affirmative action programmes","Realistic job previews"],"correctOption":0,"section":"Managing Human Resources","explanation":"High-performance work practices are those that raise both individual and organizational performance, such as self-managed teams and performance-based pay. Option C refers to programmes that improve the position of protected groups, and option D is a job preview given to applicants during selection."}},{"itemId":"4e562608-9614-5654-a4f6-251ea8645f7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"508576ef-147a-5483-b6c9-3bfdd036005d","sourceKey":"bank:AMS101:M101-T5N-009","parentItemId":null,"revision":1,"payload":{"prompt":"Self-managed teams, decentralised decision-making and performance-based pay are all examples of:","options":["Decruitment options","Selection devices","Affirmative action programmes","High-performance work practices"],"correctOption":3,"section":"Managing Human Resources","explanation":"These are all listed examples of high-performance work practices, which lift both individual and organizational performance. Option A covers ways of reducing the workforce, such as layoffs, and option B covers tools like tests and interviews used to choose applicants."}},{"itemId":"b752a479-6f74-5c51-a7e5-d670e625808a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"992a2b22-1965-5212-985c-c6ddccf13d1f","sourceKey":"bank:AMS101:M101-T5N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of a high-performance work practice?","options":["Flexible job assignments","Hiring for a good fit between person and job","Open communication","Keeping all decisions with top management"],"correctOption":3,"section":"Managing Human Resources","explanation":"High-performance work practices include decentralised decision-making, so keeping every decision at the top is the opposite of one. Options A, B and C are all listed examples, along with self-managed teams, training and performance-based pay."}},{"itemId":"62223cf3-df75-51d3-a142-c6ba27d3e97c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b7d024a4-3500-555c-81eb-3563e37cd67c","sourceKey":"bank:AMS101:M101-T5N-011","parentItemId":null,"revision":1,"payload":{"prompt":"How many activities make up the HRM process?","options":["Seven","Eight","Ten","Six"],"correctOption":1,"section":"Managing Human Resources","explanation":"The HRM process has eight activities, running from human resource planning to career development, arranged in three groups. Option A is tempting because there are seven decruitment options and seven appraisal methods, but the HRM process itself has eight activities."}},{"itemId":"31322960-8563-5b98-b850-00ee9cf1ce95","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d7aa5c68-3b68-5e22-9d15-3389893d29d8","sourceKey":"bank:AMS101:M101-T5N-012","parentItemId":null,"revision":1,"payload":{"prompt":"The eight activities of the HRM process are arranged in how many groups?","options":["Three","Five","Two","Four"],"correctOption":0,"section":"Managing Human Resources","explanation":"The eight activities fall into three groups: identifying and selecting competent employees, giving them up-to-date skills and knowledge, and retaining competent, high-performing employees. Option C is tempting because training methods come in two groups, but the HRM process itself has three."}},{"itemId":"bd8f753d-c74f-54ab-8b2a-5252f06fb859","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"40f86e3d-d994-507f-92f6-4ba393faa4e1","sourceKey":"bank:AMS101:M101-T5N-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the first activity in the HRM process?","options":["Orientation","Selection","Human resource planning","Recruitment and decruitment"],"correctOption":2,"section":"Managing Human Resources","explanation":"The process starts with human resource planning, which works out how many and what kinds of people are needed. Option D is the second activity and option B is the third; you cannot recruit or select sensibly until you know what you need."}},{"itemId":"df2aeb5e-164d-5dba-9c85-55eebb93d01d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"95e60578-a8ce-5960-aaca-198bccbc17fa","sourceKey":"bank:AMS101:M101-T5N-014","parentItemId":null,"revision":1,"payload":{"prompt":"In the HRM process, the third activity is:","options":["Recruitment and decruitment","Human resource planning","Selection","Orientation"],"correctOption":2,"section":"Managing Human Resources","explanation":"The order is human resource planning, then recruitment and decruitment, then selection. Option A comes second, because you must attract applicants before you can choose among them, and option D comes fourth, after people have been hired."}},{"itemId":"8d42d429-b0fb-5b01-988c-71af7cf65c61","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"801d1303-4721-53e5-b286-c237eaa2478d","sourceKey":"bank:AMS101:M101-T5N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the eighth and final activity in the HRM process?","options":["Compensation and benefits","Career development","Training","Performance management"],"correctOption":1,"section":"Managing Human Resources","explanation":"Career development closes the HRM process as the last of the retention activities. Option A is seventh and option D is sixth; both also belong to the retention group, which is why they are easy to mix up."}},{"itemId":"ceda58a7-1c0d-5570-a433-0cfcf8409549","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5ebeba05-e1da-57b5-bb34-1722647c086c","sourceKey":"bank:AMS101:M101-T5N-016","parentItemId":null,"revision":1,"payload":{"prompt":"In the HRM process, orientation and training belong to the group of activities that:","options":["Retain competent, high-performing employees","Give employees up-to-date skills and knowledge","Identify and select competent employees","Respond to labour unions and laws"],"correctOption":1,"section":"Managing Human Resources","explanation":"Orientation and training are the two activities that give employees up-to-date skills and knowledge. Option C covers HR planning, recruitment and selection, and option A covers performance management, compensation and benefits, and career development."}},{"itemId":"e92fe085-62d3-5334-bb9d-357fd8e8df2c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f580f159-9d00-5172-be1d-c51d0aa7155f","sourceKey":"bank:AMS101:M101-T5N-017","parentItemId":null,"revision":1,"payload":{"prompt":"Compensation and benefits fall under which group of HRM activities?","options":["Plan future human resource needs","Identify and select competent employees","Give employees up-to-date skills and knowledge","Retain competent, high-performing employees"],"correctOption":3,"section":"Managing Human Resources","explanation":"Compensation and benefits sit in the retention group with performance management and career development, because fair pay helps keep good people. Option C contains orientation and training, and option B contains planning, recruitment and selection."}},{"itemId":"ad533cdf-59a0-5f95-aa3f-92eabfa5f81c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"86766012-8015-57c9-864e-0c2cb6b805d2","sourceKey":"bank:AMS101:M101-T5N-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of activities makes up the group \"identify and select competent employees\"?","options":["HR planning, recruitment and decruitment, selection","Performance management, compensation, career development","Orientation, training, career development","HR planning, orientation, training"],"correctOption":0,"section":"Managing Human Resources","explanation":"The first group covers the three activities that bring the right people in: HR planning, recruitment and decruitment, and selection. Option B is the retention group, and options C and D mix in orientation and training, which belong to the skills and knowledge group."}},{"itemId":"351871a2-3687-5ab9-a6e4-3b4fc94f4f68","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f2155f6-4f5a-502a-99fb-9219453740ce","sourceKey":"bank:AMS101:M101-T5N-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the eight activities of the HRM process?","options":["Orientation","Collective bargaining","Career development","Performance management"],"correctOption":1,"section":"Managing Human Resources","explanation":"Collective bargaining is how a labour union negotiates with management; unions are an external factor that affects HRM, not one of its eight activities. Options A, C and D are all among the eight activities."}},{"itemId":"b67c7c31-d99f-5682-85e8-72a6fd458282","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d1dc07d-9c7c-5c0a-ab5e-8f05003b3b89","sourceKey":"bank:AMS101:M101-T5N-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an external factor that affects HRM?","options":["Job analysis","Orientation","Demographic trends","Graphic rating scales"],"correctOption":2,"section":"Managing Human Resources","explanation":"Demographic trends, such as a more diverse and ageing workforce, come from outside the organization and shape how it recruits, trains and rewards people. Options A, B and D are things managers do inside the HRM process, not outside influences."}},{"itemId":"b89b975b-e542-5739-88cd-7e05bb3ce8b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"df3b3d78-8427-5267-ba40-17511283b1e5","sourceKey":"bank:AMS101:M101-T5N-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an external factor that affects HRM?","options":["Demographic trends","Government laws and regulations","Job specifications","Labour unions"],"correctOption":2,"section":"Managing Human Resources","explanation":"A job specification is a document managers produce from job analysis during HR planning, so it is part of the HRM process, not an outside influence. Options A, B and D are the three external factors that affect HRM."}},{"itemId":"c8fa24b5-f704-54e7-889e-e747c7e8d2a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"21290aa3-d8f5-5e89-9a02-0baa11405ad3","sourceKey":"bank:AMS101:M101-T5N-022","parentItemId":null,"revision":1,"payload":{"prompt":"An organization that represents workers and seeks to protect their interests through collective bargaining is a:","options":["Assessment centre","Labour union","Professional recruiter","Public employment agency"],"correctOption":1,"section":"Managing Human Resources","explanation":"A labour union represents workers and protects their interests by bargaining collectively with management over pay, hours and conditions. Option D helps people find jobs at little or no cost, and option C is a private headhunter that finds candidates for firms."}},{"itemId":"fa05c07b-215a-533a-b49d-42a18dd2a0ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94a7272c-e3d8-5174-a207-c25e8e84f17a","sourceKey":"bank:AMS101:M101-T5N-023","parentItemId":null,"revision":1,"payload":{"prompt":"The result of negotiations between a labour union and management, covering pay, hours and working conditions, is called a:","options":["Job specification","Performance management system","Affirmative action programme","Collective bargaining agreement"],"correctOption":3,"section":"Managing Human Resources","explanation":"Collective bargaining produces a collective bargaining agreement, which sets out terms such as pay, hours and working conditions. Option C is a programme to improve the position of protected groups, and option A lists the qualifications a jobholder needs."}},{"itemId":"a2c7dfaa-d167-5d37-a623-0f1e4b8f7995","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de81a473-dfe7-5bf1-b0a3-ea36204fb6a4","sourceKey":"bank:AMS101:M101-T5N-024","parentItemId":null,"revision":1,"payload":{"prompt":"ASUU, which represents academic staff in Nigerian universities, negotiates with government over pay and conditions. For a university's HRM, ASUU is an example of which external factor?","options":["An affirmative action programme","A government regulation","A labour union","A demographic trend"],"correctOption":2,"section":"Managing Human Resources","explanation":"ASUU is the union of university academic staff, so it is a labour union, one of the external factors that shape HRM. Option B is wrong because ASUU is not a law passed by government, and option D refers to changes in the make-up of the workforce, such as age or gender."}},{"itemId":"4c8204be-9aa9-5b49-bb9a-27002637ed7a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6cf58f3e-14ac-5d71-917f-6419c078852c","sourceKey":"bank:AMS101:M101-T5N-025","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigeria Labour Congress (NLC) is best described as:","options":["A national umbrella body for trade unions","A government employment agency","The union of university academic staff only","A law that governs hiring and dismissal"],"correctOption":0,"section":"Managing Human Resources","explanation":"The NLC is a national umbrella body that brings Nigeria's trade unions together. Option C describes ASUU, which is one specific union, and option D describes the Labour Act, which is a law rather than a workers' organization."}},{"itemId":"926c6874-c90c-5cbf-beff-2dde4530cd7d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"13a18a48-6493-5275-b49d-5977f450c56d","sourceKey":"bank:AMS101:M101-T5N-026","parentItemId":null,"revision":1,"payload":{"prompt":"In Nigeria, a key law that limits how managers hire, pay and dismiss workers is the:","options":["Nigeria Labour Congress","Affirmative action programme","Collective bargaining agreement","Labour Act"],"correctOption":3,"section":"Managing Human Resources","explanation":"The Labour Act is an important Nigerian labour law, and laws like it mean managers cannot hire, pay or fire purely as they like. Option A is a body of trade unions, not a law, and option C is an agreement negotiated between a union and management."}},{"itemId":"0282d449-f449-5ca1-818b-f353e1366179","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a86622a0-617c-5ea8-b90d-da794deb681f","sourceKey":"bank:AMS101:M101-T5N-027","parentItemId":null,"revision":1,"payload":{"prompt":"Programmes that improve the position of members of protected groups, for example in hiring and promotion, are called:","options":["Affirmative action programmes","Realistic job previews","Career development programmes","High-performance work practices"],"correctOption":0,"section":"Managing Human Resources","explanation":"Affirmative action programmes aim to improve the position of protected groups in areas like hiring and promotion. Option D refers to practices that raise individual and organizational performance, and option C helps all employees plan and grow their careers."}},{"itemId":"b2216cb2-739b-5c5f-a912-3442ba629068","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f5d5da3f-fcae-568e-b77d-3a6fe29cd9d8","sourceKey":"bank:AMS101:M101-T5N-028","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota finds that its workforce is getting older and more mixed in age, gender and ethnicity, so it changes how it recruits and trains. Which external factor is at work?","options":["Laws and regulations","High-performance work practices","Labour unions","Demographic trends"],"correctOption":3,"section":"Managing Human Resources","explanation":"Changes in the age, gender and ethnic make-up of the workforce are demographic trends, one of the external factors affecting HRM. Option C would involve a workers' organization bargaining, and option A would involve government rules; neither is described here."}},{"itemId":"1bb0b7a3-475c-5bcb-b3a1-080d1e198166","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"24b3c0a9-ab68-5fc7-b6b4-0e3d18f2f5e1","sourceKey":"bank:AMS101:M101-T5N-029","parentItemId":null,"revision":1,"payload":{"prompt":"Who is known as the father of industrial psychology and argued for the scientific selection of employees?","options":["Abraham Maslow","Henri Fayol","Hugo Munsterberg","Max Weber"],"correctOption":2,"section":"Managing Human Resources","explanation":"Hugo Munsterberg, the father of industrial psychology, argued for scientific selection, and modern selection tests build on his work. Option D is linked with bureaucracy and formal selection by qualifications, and option B is known for the principles of management."}},{"itemId":"e9b64478-9d80-5728-ba8e-0cbf7fab2c98","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c7bb17de-e040-50b0-a156-275f2e470a42","sourceKey":"bank:AMS101:M101-T5N-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes where the HRM process takes place?","options":["Only inside the HR department, cut off from outside forces","Inside the external environment, which shapes every step","Only at the selection stage, where laws apply","Only within labour union agreements"],"correctOption":1,"section":"Managing Human Resources","explanation":"The whole HRM process sits inside the external environment, so unions, laws and demographic trends shape every step, not just one. Option A is wrong because HRM is not sealed off from the outside world, and option C wrongly limits outside influence to selection."}},{"itemId":"b98e4e01-ec29-5c16-8c95-ae8a60a00b07","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"955ffaa3-a3a1-5071-be1f-aceb0844d36f","sourceKey":"bank:AMS101:M101-T5N-031","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which managers make sure they have the right number and kinds of capable people in the right places at the right times is:","options":["Selection","Recruitment","Human resource planning","Job analysis"],"correctOption":2,"section":"Managing Human Resources","explanation":"Human resource planning is about having the right number and kinds of capable people in the right places at the right times. Option D defines individual jobs and the behaviours they need, and option B is about attracting applicants once the need is known."}},{"itemId":"f5cf765d-7506-5f02-8071-64168509d313","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a9b3035f-eccd-57ee-8963-dcae5f47f77e","sourceKey":"bank:AMS101:M101-T5N-032","parentItemId":null,"revision":1,"payload":{"prompt":"Human resource planning is also known as:","options":["Employment planning","Decruitment","Career development","Job analysis"],"correctOption":0,"section":"Managing Human Resources","explanation":"Human resource planning is also called employment planning, because it plans how many and what kinds of people the organization will employ. Option D is one step within HR planning that defines jobs, and option C helps individual employees plan their own careers."}},{"itemId":"36f8cea3-bc10-5997-9a93-9061eff104d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"61eb13e3-e6e6-5e2d-9226-91a4aa8b50cd","sourceKey":"bank:AMS101:M101-T5N-033","parentItemId":null,"revision":1,"payload":{"prompt":"Human resource planning involves how many steps?","options":["Three","Eight","Two","Four"],"correctOption":2,"section":"Managing Human Resources","explanation":"HR planning has two steps: assessing current human resources and meeting future human resource needs. Option B is the number of activities in the whole HRM process, not the steps in HR planning."}},{"itemId":"02b39b49-aa2a-510c-a7b4-2aba8821a926","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2f272a4-51ed-5270-9814-09edfba29062","sourceKey":"bank:AMS101:M101-T5N-034","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in human resource planning is to:","options":["Meet future human resource needs","Write the job specification","Recruit capable applicants","Assess current human resources"],"correctOption":3,"section":"Managing Human Resources","explanation":"Managers begin by assessing the people they already have before working out what they will need. Option A is the second step, and option C belongs to recruitment, the HRM activity that comes after planning."}},{"itemId":"12110725-848d-55cb-9092-882bc8cee1c5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a185c4ef-a7c2-54e8-82c0-8970dc1018b2","sourceKey":"bank:AMS101:M101-T5N-035","parentItemId":null,"revision":1,"payload":{"prompt":"The second step in human resource planning is to:","options":["Appraise employee performance","Conduct an orientation programme","Assess current human resources","Meet future human resource needs"],"correctOption":3,"section":"Managing Human Resources","explanation":"After assessing current staff, managers move on to meeting future human resource needs. Option C is the first step, and options B and A are separate HRM activities that come later in the process."}},{"itemId":"b62d8080-061a-5cfd-a1a9-85921a134234","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3e461196-ee74-5d3d-8f7d-edad33286f3b","sourceKey":"bank:AMS101:M101-T5N-036","parentItemId":null,"revision":1,"payload":{"prompt":"A record of current employees' names, education, training, past jobs, languages and special skills is called a:","options":["Job specification","Application form","Job description","Human resource inventory"],"correctOption":3,"section":"Managing Human Resources","explanation":"A human resource inventory records what current employees bring, such as their education, languages and special skills. Option C describes a job rather than the people in it, and option B collects facts from applicants, not existing staff."}},{"itemId":"4d4147f5-b0c1-5201-b5bc-060aabd07219","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd1b75cf-5ed5-5e89-92eb-96b11c6e45f7","sourceKey":"bank:AMS101:M101-T5N-037","parentItemId":null,"revision":1,"payload":{"prompt":"The HR manager of a commercial bank in Lagos builds a database showing every staff member's education, past jobs, languages and special skills. She is preparing a:","options":["Collective bargaining agreement","Human resource inventory","Job specification","Realistic job preview"],"correctOption":1,"section":"Managing Human Resources","explanation":"A database of current employees' education, past jobs, languages and skills is a human resource inventory, used to assess current human resources. Option C sets out minimum qualifications for a job, not a record of existing staff, and option D is information given to applicants."}},{"itemId":"70936b79-f6df-58c7-bf26-630487526112","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d6a5260-e1a5-5a09-84d7-afc66036537d","sourceKey":"bank:AMS101:M101-T5N-038","parentItemId":null,"revision":1,"payload":{"prompt":"An assessment that defines jobs and the behaviours needed to perform them is called:","options":["Performance appraisal","Job specification","Job analysis","Job description"],"correctOption":2,"section":"Managing Human Resources","explanation":"Job analysis defines jobs and the behaviours needed to do them, and it comes first. Options D and B are both produced from job analysis: the description covers what the job is, and the specification covers the minimum qualifications."}},{"itemId":"785c2925-490f-5218-a519-d2fec103fd72","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0cdf16cb-e107-5ad2-981f-06188089ebb5","sourceKey":"bank:AMS101:M101-T5N-039","parentItemId":null,"revision":1,"payload":{"prompt":"The job description and job specification are both produced from:","options":["Job analysis","Selection interviews","Performance appraisal","The human resource inventory"],"correctOption":0,"section":"Managing Human Resources","explanation":"Job analysis comes first, and both the job description and the job specification are drawn from it. Option D is a record of current employees, which helps assess current staff but does not define jobs."}},{"itemId":"3f20b332-be9b-5c62-b7eb-90a97a524514","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9f68a454-0075-5ef8-a30e-9a6043ea672b","sourceKey":"bank:AMS101:M101-T5N-040","parentItemId":null,"revision":1,"payload":{"prompt":"A written statement of what the job is, what the jobholder does, how and why, is a:","options":["Job analysis","Job specification","Human resource inventory","Job description"],"correctOption":3,"section":"Managing Human Resources","explanation":"A job description is a written statement of what the job is: what the jobholder does, how and why. Option B describes the person instead, listing the minimum qualifications, while option A is the assessment both documents come from."}},{"itemId":"331766b3-7b1a-5d16-b53f-87f9cb712b95","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"31295c2b-0ae4-5f80-9324-dd761b96935b","sourceKey":"bank:AMS101:M101-T5N-041","parentItemId":null,"revision":1,"payload":{"prompt":"A statement of the minimum qualifications a person needs to do a job well is a:","options":["Job analysis","Realistic job preview","Job specification","Job description"],"correctOption":2,"section":"Managing Human Resources","explanation":"A job specification states the minimum qualifications, meaning the knowledge, skills and attitudes, a person needs to do the job well. Option D describes the job itself rather than the person, and option B gives applicants good and bad information about the job."}},{"itemId":"16aec209-c164-5f1b-ac5e-040eafc95889","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6238fdea-5ab2-51d7-a46e-819b2751ab4f","sourceKey":"bank:AMS101:M101-T5N-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes a job description from a job specification?","options":["A job description lists knowledge, skills and attitudes needed","A job description describes the job; a job specification describes the person","A job description describes the person; a job specification describes the job","Both describe the minimum qualifications of the jobholder"],"correctOption":1,"section":"Managing Human Resources","explanation":"The job description describes the job (what is done, how and why), while the job specification describes the person (the minimum knowledge, skills and attitudes needed). Option C simply reverses the two, and option A gives the job specification's content to the job description."}},{"itemId":"a0a13afd-d97c-5a0f-8879-da093ecf1359","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8cda5418-0441-58a8-bf24-b5f27b2d75ed","sourceKey":"bank:AMS101:M101-T5N-043","parentItemId":null,"revision":1,"payload":{"prompt":"A job advert from a bottling company in Ota says: \"Applicant must hold an OND in Mechanical Engineering and have good knowledge of safety procedures.\" This part of the advert comes from the:","options":["Human resource inventory","Collective bargaining agreement","Job description","Job specification"],"correctOption":3,"section":"Managing Human Resources","explanation":"Stating the qualifications and knowledge an applicant must have describes the person, which is the job specification. Option C would explain what the jobholder does on the bottling line, not what the person must bring."}},{"itemId":"2f8c37a0-8d2a-58d0-941b-25bb45013086","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ef59ae3-7bc8-572e-83bc-3dbca95cb5b8","sourceKey":"bank:AMS101:M101-T5N-044","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital document states that a ward clerk records patient admissions, updates files daily and sends reports to the matron so that care is not delayed. This document is a:","options":["Job description","Human resource inventory","Realistic job preview","Job specification"],"correctOption":0,"section":"Managing Human Resources","explanation":"The document says what the jobholder does, how and why, which makes it a job description. Option D would instead list the minimum qualifications a ward clerk needs, and option B records the skills of current employees."}},{"itemId":"dded87b1-85f7-5a4d-9758-a44508aaea2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"855001fb-6dff-57c0-b1fd-c55747de4107","sourceKey":"bank:AMS101:M101-T5N-045","parentItemId":null,"revision":1,"payload":{"prompt":"When managers work out future human resource needs, these needs come mainly from:","options":["The results of last year's orientation programme","The personal preferences of current employees","The number of applicants who apply each year","The organization's mission, goals and strategy, and demand for its products or services"],"correctOption":3,"section":"Managing Human Resources","explanation":"Future needs flow from where the organization is going (its mission, goals and strategy) and from demand for what it sells. Option C is wrong because applicant numbers reflect recruitment, not how many people the organization actually needs."}},{"itemId":"73c3293b-99c8-5fcf-ade5-6d072cfb4145","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f7cb3b85-6df8-5902-be77-c7d1cdeeb2c0","sourceKey":"bank:AMS101:M101-T5N-046","parentItemId":null,"revision":1,"payload":{"prompt":"Reducing an organization's workforce is called:","options":["Decruitment","Attrition","Recruitment","Orientation"],"correctOption":0,"section":"Managing Human Resources","explanation":"Decruitment is the general term for reducing an organization's workforce, and it covers several options. Option B is only one of those options, leaving jobs unfilled, and option C is the opposite activity of attracting applicants."}},{"itemId":"3c658e31-587e-52a4-8289-2c36053681bc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a4269f14-5ac7-5802-94ad-efccdc6e8551","sourceKey":"bank:AMS101:M101-T5N-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best contrasts recruitment with decruitment?","options":["Both refer to screening applicants to choose the best","Recruitment attracts capable applicants; decruitment reduces the workforce","Recruitment is temporary; decruitment is permanent","Recruitment reduces the workforce; decruitment attracts applicants"],"correctOption":1,"section":"Managing Human Resources","explanation":"Recruitment is about locating, identifying and attracting capable applicants, while decruitment is about reducing the workforce. Option D reverses them, and option A describes selection, which comes after recruitment."}},{"itemId":"9e218a1f-b56b-5553-ae5a-daca2dd36f61","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d0dcead-e97b-550c-a2fb-877ce0fa7baa","sourceKey":"bank:AMS101:M101-T5N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which recruitment option has the advantages of low cost, building morale, and candidates who already know the organization?","options":["Internal search","School and college recruiting","Private agencies","Employee referrals"],"correctOption":0,"section":"Managing Human Resources","explanation":"Internal search looks among current staff, so it is cheap, boosts morale, and the candidates already know the organization. Option D also uses current staff, but its stated advantage is that they know the job and stake their name on the candidate, and option C is costly."}},{"itemId":"9e200cbb-c7a5-5709-948c-2de8ec2fd21b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a3b65558-a3ce-51ee-9090-dbcf443407b8","sourceKey":"bank:AMS101:M101-T5N-049","parentItemId":null,"revision":1,"payload":{"prompt":"A main disadvantage of internal search as a recruitment option is:","options":["Mostly entry-level candidates","Limited supply of candidates","High cost","Candidates tend to be less skilled"],"correctOption":1,"section":"Managing Human Resources","explanation":"Internal search can only draw from people already in the organization, so the supply is limited and it may not add diversity. Option C is the drawback of private agencies, and option A is the drawback of school and college recruiting."}},{"itemId":"801b34db-6ff2-52b7-9e3e-ee0552a6885d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ad316041-7a34-5aa2-8932-2b6719f6d697","sourceKey":"bank:AMS101:M101-T5N-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which recruitment option has the disadvantage of bringing in many unqualified applicants?","options":["Advertisements, internet and company website","Internal search","Private agencies and headhunters","Employee referrals"],"correctOption":0,"section":"Managing Human Resources","explanation":"Adverts and online postings reach many people, but that wide reach also brings in many unqualified applicants. Option C does the opposite, because headhunters screen candidates carefully, and option D relies on staff who know the job."}},{"itemId":"87a017a4-1974-5aa2-9aa0-73792a5dcc32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"74317479-b585-5daa-9144-de7b12fa62fd","sourceKey":"bank:AMS101:M101-T5N-051","parentItemId":null,"revision":1,"payload":{"prompt":"Private agencies and professional recruiters (\"headhunters\") have which main disadvantage?","options":["High cost and little commitment to the organization","Candidates tend to be less skilled","Mostly entry-level candidates","Bring in many unqualified applicants"],"correctOption":0,"section":"Managing Human Resources","explanation":"Headhunters have wide contacts and screen carefully, but they are expensive and have little commitment to the hiring organization. Option B is the drawback of public employment agencies, and option D is the drawback of advertising widely."}},{"itemId":"8c3a4da5-5a86-5267-8efe-521b50522999","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"daf194e9-43d3-5626-9418-b3f7f3372ad1","sourceKey":"bank:AMS101:M101-T5N-052","parentItemId":null,"revision":1,"payload":{"prompt":"Public employment agencies are free or low cost. Their main disadvantage is that:","options":["They have a limited internal supply","They are very expensive","Candidates tend to be less skilled","They supply mostly entry-level graduates"],"correctOption":2,"section":"Managing Human Resources","explanation":"Public employment agencies cost little, but the candidates they supply tend to be less skilled. Option B is the drawback of private agencies and temporary help, and option D is the drawback of school and college recruiting."}},{"itemId":"9618b4d4-57a7-5aca-ab11-8cba5ed59fe0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6107ad81-3425-548b-a56e-ea95b5e5ba26","sourceKey":"bank:AMS101:M101-T5N-053","parentItemId":null,"revision":1,"payload":{"prompt":"School and college recruiting offers a large pool of candidates in one place, but its main drawback is that it provides:","options":["A very limited supply","Mostly entry-level candidates","Candidates with little commitment","Mostly highly paid senior staff"],"correctOption":1,"section":"Managing Human Resources","explanation":"Campus recruiting brings a large pool of applicants together, but they are mostly entry-level, so it suits junior roles rather than senior ones. Option A is the drawback of internal search, and option C is linked with headhunters."}},{"itemId":"2c647d81-1951-5f5a-817a-081aeb05cc99","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"757562e9-061c-5c26-ad95-855d309e57d4","sourceKey":"bank:AMS101:M101-T5N-054","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fintech firm asks its staff to recommend friends for open roles, knowing that staff understand the job and put their own reputation on the line. Which recruitment option is this?","options":["Internal search","Temporary help services","Public employment agencies","Employee referrals"],"correctOption":3,"section":"Managing Human Resources","explanation":"Asking current staff to recommend outsiders is an employee referral; staff know the job and stake their name on the candidate. Option A would mean filling the role from current employees themselves, not from people they recommend."}},{"itemId":"93f91979-4f94-5cad-85b8-94dc053dbc36","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"378684d4-a885-570b-97da-0ee44d3e0e47","sourceKey":"bank:AMS101:M101-T5N-055","parentItemId":null,"revision":1,"payload":{"prompt":"A private hospital in Ibadan needs extra records staff for three months while it moves to a new filing system. Which recruitment option best fits this short-term need, though it is expensive?","options":["Temporary help services","Internal search","Employee referrals","School and college recruiting"],"correctOption":0,"section":"Managing Human Resources","explanation":"Temporary help services exist to fill short-term needs, although they are expensive. Option D mainly brings in entry-level candidates for permanent roles, and option B draws on existing staff, who are already needed in their own jobs."}},{"itemId":"dbd0ba05-248e-5052-ba17-07759a55d281","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e610530d-153f-51a1-ad1f-04c60e43e843","sourceKey":"bank:AMS101:M101-T5N-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which two recruitment options share the disadvantage that they may not add diversity to the workforce?","options":["Internal search and employee referrals","Private agencies and advertisements","Advertisements and public employment agencies","School recruiting and temporary help services"],"correctOption":0,"section":"Managing Human Resources","explanation":"Internal search and employee referrals both rely on current staff, so they tend to bring in similar people and may not add diversity. The other pairs have different drawbacks, such as many unqualified applicants for adverts in option C and expense for temporary help in option D."}},{"itemId":"a226f399-2e53-55f6-a0a8-0e998b67f602","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"91afd580-114e-5f68-9fb3-e0cfbca274cd","sourceKey":"bank:AMS101:M101-T5N-057","parentItemId":null,"revision":1,"payload":{"prompt":"How many decruitment options are there?","options":["Six","Seven","Eight","Five"],"correctOption":1,"section":"Managing Human Resources","explanation":"There are seven decruitment options: firing, layoffs, attrition, transfers, reduced workweeks, early retirements and job sharing. Option C is the number of HRM activities, which is a common mix-up."}},{"itemId":"70067cba-97ad-5360-b71c-9fbdcdbd9f49","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"01a09509-8f08-5786-a940-dc599701fd5f","sourceKey":"bank:AMS101:M101-T5N-058","parentItemId":null,"revision":1,"payload":{"prompt":"Permanent, involuntary termination of employment is called:","options":["A layoff","Early retirement","Attrition","Firing"],"correctOption":3,"section":"Managing Human Resources","explanation":"Firing is permanent and involuntary. Option A is also involuntary but temporary, and option C forces no one out because jobs are simply left unfilled when people resign or retire."}},{"itemId":"4a075a08-af56-5d4b-b78a-c665ba68c80a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"378b090e-188b-5897-bd0a-a9520f4cbbb9","sourceKey":"bank:AMS101:M101-T5N-059","parentItemId":null,"revision":1,"payload":{"prompt":"A temporary, involuntary termination that may last days or years is a:","options":["Reduced workweek","Transfer","Layoff","Firing"],"correctOption":2,"section":"Managing Human Resources","explanation":"A layoff is involuntary but temporary, and it may last days or years. Option D is the permanent version, which is the classic trap, and option B moves people within the organization rather than ending their employment."}},{"itemId":"38148b19-2c70-5e89-9c4a-24f3ca9755a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5bb152d9-60f9-5fb5-bd53-75149c9344d9","sourceKey":"bank:AMS101:M101-T5N-060","parentItemId":null,"revision":1,"payload":{"prompt":"A state-owned bank in Abuja decides not to replace staff who resign or retire this year, so its headcount falls without anyone being forced out. This decruitment option is:","options":["Layoffs","Attrition","Job sharing","Firing"],"correctOption":1,"section":"Managing Human Resources","explanation":"Not filling jobs left open by resignations or retirements is attrition, and with attrition no one is forced out. Options A and D both involve involuntary termination, temporary and permanent respectively."}},{"itemId":"97c0a71b-83a2-5ab1-a8c2-408d6738b96c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"332057d8-0818-5fb5-ad14-4af9d1421fd7","sourceKey":"bank:AMS101:M101-T5N-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which decruitment option usually does not cut costs but helps balance supply and demand for labour inside the organization?","options":["Reduced workweeks","Transfers","Early retirements","Attrition"],"correctOption":1,"section":"Managing Human Resources","explanation":"Transfers move employees sideways or downward, so they usually do not reduce costs but they rebalance labour across units. Options A, C and D all actually reduce the hours worked or the number of people employed."}},{"itemId":"d9352699-0177-5994-81cf-cd6c6dcf8a8d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c969f801-ae8a-5aae-9aa2-e9328b87e337","sourceKey":"bank:AMS101:M101-T5N-062","parentItemId":null,"revision":1,"payload":{"prompt":"To cut its workforce, a Lagos insurance company offers attractive packages to older, senior staff who agree to leave before normal retirement age. This decruitment option is:","options":["Transfers","Attrition","Layoffs","Early retirements"],"correctOption":3,"section":"Managing Human Resources","explanation":"Offering incentives to older, senior staff to retire early is the early retirement option. Option B would involve simply not replacing people who leave on their own, without any incentive package."}},{"itemId":"e371da57-8e9f-5b2e-864f-dc6f0852e43d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b3a7544f-14e6-5f4b-9f55-7cc8b4e91e1f","sourceKey":"bank:AMS101:M101-T5N-063","parentItemId":null,"revision":1,"payload":{"prompt":"During a slow season, a textile factory in Kano asks all machine operators to work 30 hours a week instead of 40 rather than letting anyone go. This decruitment option is:","options":["Job sharing","Reduced workweeks","Attrition","Layoffs"],"correctOption":1,"section":"Managing Human Resources","explanation":"Having employees work fewer hours a week is the reduced workweek option. Option A would mean two or more people, usually part-timers, splitting one full-time job, which is not what is described."}},{"itemId":"105f1e0b-9783-5e5a-907b-cc289d6ffe02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bd7cdb2a-26b3-5289-adfe-db8d42416724","sourceKey":"bank:AMS101:M101-T5N-064","parentItemId":null,"revision":1,"payload":{"prompt":"When several employees, usually two part-timers, share one full-time job, the decruitment option is called:","options":["Job rotation","Transfers","Job sharing","Reduced workweeks"],"correctOption":2,"section":"Managing Human Resources","explanation":"Job sharing is when several employees, usually two part-timers, split one full-time job. Option A is a training method in which employees move sideways to learn several jobs, and option D cuts everyone's hours without splitting a job."}},{"itemId":"0dd54513-e3f0-5c71-a242-b73731bba282","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ed89b447-affb-5879-a9be-d3eebc979350","sourceKey":"bank:AMS101:M101-T5N-065","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a decruitment option?","options":["Attrition","Transfers","Employee referrals","Job sharing"],"correctOption":2,"section":"Managing Human Resources","explanation":"Employee referrals are a way of recruiting new people, not of reducing the workforce. Options A, B and D are all among the seven decruitment options."}},{"itemId":"be32fcfe-97fa-5329-a355-6a3c992d976a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d187da4e-d6bf-54cb-b9e1-e4c51874f5ab","sourceKey":"bank:AMS101:M101-T5N-066","parentItemId":null,"revision":1,"payload":{"prompt":"The key difference between firing and a layoff is that:","options":["A layoff leaves jobs unfilled after resignations","Firing is temporary, while a layoff is permanent","Firing is permanent, while a layoff is temporary","Firing is voluntary, while a layoff is involuntary"],"correctOption":2,"section":"Managing Human Resources","explanation":"Both are involuntary, but firing is permanent and a layoff is temporary. Option B reverses them, and option A describes attrition, where no one is forced out at all."}},{"itemId":"4e462732-8780-5674-b457-7264180f6c83","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1dcc0ec8-5079-5ec1-97b0-507314fd4afd","sourceKey":"bank:AMS101:M101-T5N-067","parentItemId":null,"revision":1,"payload":{"prompt":"Screening job applicants to make sure the most appropriate candidates are hired is called:","options":["Job analysis","Selection","Orientation","Recruitment"],"correctOption":1,"section":"Managing Human Resources","explanation":"Selection screens applicants so the most appropriate ones are hired. Option D comes before it and only attracts the pool of applicants, while option C happens after hiring, when new employees are introduced to the job."}},{"itemId":"ac4c8e28-2b7d-5bdd-8c74-686e37a96892","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c3c61374-4457-5973-8f97-f8e94f810584","sourceKey":"bank:AMS101:M101-T5N-068","parentItemId":null,"revision":1,"payload":{"prompt":"Selection is best understood as an exercise in:","options":["Bargaining","Prediction","Negotiation","Persuasion"],"correctOption":1,"section":"Managing Human Resources","explanation":"Selection is an exercise in prediction: managers try to forecast which applicant will do the job well. Options C and A describe what unions and management do in collective bargaining, not choosing among applicants."}},{"itemId":"94dcdc68-fe61-59b3-b258-12128addc9c9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"52c2353a-4344-5a6d-9773-dcef951179be","sourceKey":"bank:AMS101:M101-T5N-069","parentItemId":null,"revision":1,"payload":{"prompt":"A selection decision can have how many possible outcomes?","options":["Three","Four","Two","Six"],"correctOption":1,"section":"Managing Human Resources","explanation":"Accepting or rejecting a candidate who later succeeds or fails gives four outcomes: two correct decisions and two errors (the accept error and the reject error). Option C counts only the two errors or only the two choices, not the full set of outcomes."}},{"itemId":"364d19d2-ce81-5342-b285-f0849ff7da09","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"62a506c9-1a80-53d4-a3ce-d74c94fd5984","sourceKey":"bank:AMS101:M101-T5N-070","parentItemId":null,"revision":1,"payload":{"prompt":"Rejecting a candidate who would have done the job well is called a(n):","options":["Correct decision","Reject error","Accept error","Validity error"],"correctOption":1,"section":"Managing Human Resources","explanation":"A reject error turns away someone who would have succeeded. Option C is the opposite mistake, hiring someone who then performs poorly, and option A would apply only if the rejected person would have failed."}},{"itemId":"aaa36b4b-b10c-523b-9841-77fbc195e56c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4ebd2c24-9d31-58cd-8656-694ccf02220f","sourceKey":"bank:AMS101:M101-T5N-071","parentItemId":null,"revision":1,"payload":{"prompt":"Accepting a candidate who then performs poorly is called a(n):","options":["Correct decision","Reliability error","Accept error","Reject error"],"correctOption":2,"section":"Managing Human Resources","explanation":"An accept error hires someone who turns out to perform poorly. Option D is the opposite mistake of turning away someone who would have done well, and option A would apply only if the hired person later succeeded."}},{"itemId":"9724bcae-b537-54f1-af38-32effae11766","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a958a65-9384-55e7-a99e-be02115943bf","sourceKey":"bank:AMS101:M101-T5N-072","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank turns down an applicant for a credit analyst role. Two years later she is the best analyst at a rival bank. The first bank made a(n):","options":["Correct decision","Reject error","Accept error","Attrition decision"],"correctOption":1,"section":"Managing Human Resources","explanation":"Turning away someone who would have done the job well is a reject error, and one of its costs is losing good people to rivals. Option C would apply if the bank had hired someone who then performed poorly."}},{"itemId":"6683c766-4d6a-5a74-8116-8d922a980ac3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd2f152a-bce0-5128-aa41-1a49afcb02a1","sourceKey":"bank:AMS101:M101-T5N-073","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Enugu hires a nurse who impressed the panel, but within months her work is so poor that she must be retrained and later replaced. This is an example of a(n):","options":["Layoff","Correct decision","Accept error","Reject error"],"correctOption":2,"section":"Managing Human Resources","explanation":"Hiring someone who then performs poorly is an accept error, which brings training costs, poor work and the cost of firing and rehiring. Option D would mean the hospital had wrongly turned away a good nurse, which did not happen here."}},{"itemId":"ee59aa1f-1cc9-5630-b8c6-03528cce3232","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39c32bcd-e30f-5970-a2cc-8d13b069064c","sourceKey":"bank:AMS101:M101-T5N-074","parentItemId":null,"revision":1,"payload":{"prompt":"If an organization rejects an applicant who would later have been unsuccessful in the job, this outcome is a(n):","options":["Accept error","Reject error","Correct decision","Validity problem"],"correctOption":2,"section":"Managing Human Resources","explanation":"Rejecting someone who would have failed is the right call, so it is a correct decision. Option B applies only when the rejected person would have succeeded, and option A applies only when the person was accepted and then failed."}},{"itemId":"f9dc85ba-b191-5edd-a2c8-4ab1fd64ef97","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d63a93d3-3332-5ae0-a111-8faca62cc990","sourceKey":"bank:AMS101:M101-T5N-075","parentItemId":null,"revision":1,"payload":{"prompt":"Which cost is most closely linked with a reject error?","options":["Higher pension costs for senior staff","Poor work quality from the person who was hired","Possible discrimination claims and losing good people to rivals","Training costs and the cost of firing and rehiring"],"correctOption":2,"section":"Managing Human Resources","explanation":"A reject error turns good people away, so the firm may face discrimination claims and may lose talent to competitors. Options D and B are the costs of an accept error, where a poor performer has actually been hired."}},{"itemId":"de31277d-3d71-56b3-bec4-ddb26b7089df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c1ad0f25-ab42-5d43-9185-cf801cc988ca","sourceKey":"bank:AMS101:M101-T5N-076","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of costs is linked with an accept error?","options":["Higher fees paid to public employment agencies","Lower morale among people promoted internally","Discrimination claims and losing good people to rivals","Training costs, poor work, and the cost of firing and rehiring"],"correctOption":3,"section":"Managing Human Resources","explanation":"An accept error brings in a poor performer, which leads to training costs, poor work and finally the cost of firing and rehiring. Option C lists the costs of a reject error, where good candidates are turned away."}},{"itemId":"666957d2-4970-5758-9c37-6ac0e928ad7a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"54ab91a7-4f51-58ff-915a-71147cc1022b","sourceKey":"bank:AMS101:M101-T5N-077","parentItemId":null,"revision":1,"payload":{"prompt":"A proven relationship between a selection device and some relevant criterion, such as later job performance, is called:","options":["Attrition","Validity","Consistency","Reliability"],"correctOption":1,"section":"Managing Human Resources","explanation":"Validity means the device's results are proven to relate to something that matters, such as later job performance. Option D means the device measures the same thing consistently, which is a different quality: a test can be reliable without being valid."}},{"itemId":"086e70a7-2cb8-5452-aafc-ef12b36ddb81","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90d3a5e2-ca86-5393-a002-54b376c6bcd2","sourceKey":"bank:AMS101:M101-T5N-078","parentItemId":null,"revision":1,"payload":{"prompt":"When a selection device measures the same thing consistently, it is said to have:","options":["Formal selection","Reliability","Accuracy of prediction","Validity"],"correctOption":1,"section":"Managing Human Resources","explanation":"Reliability means consistent measurement, so the same person gets about the same score each time. Option D is about whether the scores actually predict job success, which is a separate question from consistency."}},{"itemId":"cf179d85-a64c-5b8e-bb50-04bf29b9be58","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1791a3d-1ace-5839-8be8-c9b15754b674","sourceKey":"bank:AMS101:M101-T5N-079","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota uses an aptitude test. Applicants who retake it get almost the same score each time, but the scores show no link with how well people later perform on the job. The test is:","options":["Neither valid nor reliable","Valid but not reliable","Reliable but not valid","Both valid and reliable"],"correctOption":2,"section":"Managing Human Resources","explanation":"Getting about the same score each time shows the test is reliable, but since the scores do not predict job success it is not valid. Option B reverses the two ideas, and option D is wrong because a valid test must actually predict performance."}},{"itemId":"a842694f-2a02-5594-87b9-e66e1d4c91c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca8424c6-3d0b-55b4-87cb-67c4ac11f064","sourceKey":"bank:AMS101:M101-T5N-080","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about validity and reliability is TRUE?","options":["A reliable test can still be invalid","Reliability means scores predict job success","A reliable test is always valid","Validity means scores are consistent over time"],"correctOption":0,"section":"Managing Human Resources","explanation":"Reliability is about consistency and validity is about prediction, so a test can give consistent scores that still do not predict job success. Option C is the common trap, and options D and B swap the two definitions."}},{"itemId":"bc06ec35-3fb6-59e7-b485-82fd1f89c925","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b4192077-904c-50c6-8e1b-b50ac8085544","sourceKey":"bank:AMS101:M101-T5N-081","parentItemId":null,"revision":1,"payload":{"prompt":"How many main types of selection devices are there?","options":["Six","Four","Five","Seven"],"correctOption":0,"section":"Managing Human Resources","explanation":"There are six selection devices: application forms, written tests, performance-simulation tests, interviews, background investigations and physical examinations. Option D is tempting because seven is the number of decruitment options and appraisal methods."}},{"itemId":"1121dc63-dabb-5b82-98e7-bc46e906667b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b74f9376-5eb0-540d-8d10-8c5f11f18105","sourceKey":"bank:AMS101:M101-T5N-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a selection device?","options":["Background investigations","Physical examinations","Job rotation","Application forms"],"correctOption":2,"section":"Managing Human Resources","explanation":"Job rotation is a traditional training method in which employees move sideways to learn several jobs; it is used after hiring, not to choose applicants. Options A, B and D are all selection devices."}},{"itemId":"4bc84c47-8de6-5101-8b03-57b1f59847c7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d7e3969-5a52-55fa-9b43-5e9f3b767b4e","sourceKey":"bank:AMS101:M101-T5N-083","parentItemId":null,"revision":1,"payload":{"prompt":"Work sampling and assessment centres are both types of:","options":["Written tests","Structured interviews","Performance-simulation tests","Background investigations"],"correctOption":2,"section":"Managing Human Resources","explanation":"Work sampling and assessment centres are performance-simulation tests, because they use actual job behaviour. Option A covers paper tests of intelligence, aptitude, personality and integrity, which do not ask candidates to perform the job."}},{"itemId":"dde26ef0-ae46-5831-908d-eae59f2212ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"26abd1c0-0af3-55dd-8af3-02c636c4fe79","sourceKey":"bank:AMS101:M101-T5N-084","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of selection device is based on actual job behaviour?","options":["Written tests","Application forms","Performance-simulation tests","Background investigations"],"correctOption":2,"section":"Managing Human Resources","explanation":"Performance-simulation tests ask candidates to actually perform job tasks, so they are based on real job behaviour. Option A measures traits such as aptitude or personality on paper, and option B only collects basic facts like education and past jobs."}},{"itemId":"e15feaf3-7df4-56d4-9a30-9924cb4c22be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f7813c87-3c1f-5740-ac0f-28971dba7657","sourceKey":"bank:AMS101:M101-T5N-085","parentItemId":null,"revision":1,"payload":{"prompt":"A selection device in which applicants are given a small replica of the job and asked to perform its central tasks is:","options":["Work sampling","A written test","An assessment centre","A behavioural interview"],"correctOption":0,"section":"Managing Human Resources","explanation":"Work sampling gives applicants a small replica of the job to perform its central tasks, and it suits routine, standard jobs. Option C is also a simulation, but it tests managerial potential through exercises judged by a panel."}},{"itemId":"7229e9d7-8d96-51d6-a0e4-59e779940b21","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25c0f7b2-46db-5e1f-b9db-bf23e74868e8","sourceKey":"bank:AMS101:M101-T5N-086","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos law firm hiring a typist asks each applicant to type and format a sample letter in 15 minutes. This selection device is:","options":["An assessment centre","A behavioural interview","A background investigation","Work sampling"],"correctOption":3,"section":"Managing Human Resources","explanation":"Asking applicants to perform a core task of a routine job is work sampling. Option A is meant for testing managerial potential through group exercises and problem-solving judged by a panel, not for a standard typing job."}},{"itemId":"4ba6c200-7532-58ae-8ad5-93ae71c992a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f2f8b406-97ed-57de-89be-59e117c3a64c","sourceKey":"bank:AMS101:M101-T5N-087","parentItemId":null,"revision":1,"payload":{"prompt":"Work sampling is best suited to which kind of job?","options":["Short-term temporary jobs only","Senior managerial jobs","Jobs with no clear tasks","Routine, standard jobs"],"correctOption":3,"section":"Managing Human Resources","explanation":"Work sampling copies the central tasks of a job, so it suits routine, standard jobs where those tasks are clear. Option B is better served by assessment centres, which test managerial potential."}},{"itemId":"36f111da-e7c9-54e7-bfac-60308417d049","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f817830-3948-5574-a53f-dee6d09a2ae8","sourceKey":"bank:AMS101:M101-T5N-088","parentItemId":null,"revision":1,"payload":{"prompt":"Candidates for a management trainee scheme at a Lagos conglomerate spend two days doing interviews, problem-solving tasks and group exercises while a panel judges them. This is a(n):","options":["Assessment centre","Background investigation","Structured interview","Work sampling test"],"correctOption":0,"section":"Managing Human Resources","explanation":"Simulation exercises such as interviews, problem-solving and group tasks judged by a panel make up an assessment centre, which tests managerial potential. Option D would give a small replica of one routine job rather than a range of managerial exercises."}},{"itemId":"59728477-2e33-5acd-b4b2-2d1bdad93693","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2c1b9373-1600-5c92-a870-0e6b9c57fe06","sourceKey":"bank:AMS101:M101-T5N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Assessment centres are mainly used to test a candidate's:","options":["Managerial potential","Typing speed","Physical fitness","Past employment record"],"correctOption":0,"section":"Managing Human Resources","explanation":"Assessment centres put candidates through simulation exercises, judged by a panel, to test managerial potential. Option B would be checked by work sampling, and option C by a physical examination."}},{"itemId":"d547d4ae-5d19-56ca-b5d5-0afa27caf666","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"46c428b2-8cd2-5561-82f4-878e934ef46f","sourceKey":"bank:AMS101:M101-T5N-090","parentItemId":null,"revision":1,"payload":{"prompt":"Interviews become more valid and reliable when they are:","options":["Informal, with questions changing for each candidate","Structured, with the same planned questions for every candidate","Very short and unplanned","Conducted without any written questions"],"correctOption":1,"section":"Managing Human Resources","explanation":"Structured interviews use the same planned questions for everyone, which makes them more valid and reliable. Option A is the unstructured approach, where answers cannot be compared fairly because each candidate is asked something different."}},{"itemId":"3f63a927-b40c-583b-b63f-41a721507f78","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"72f7fb0f-861b-5b6a-9293-d6ed722ff19b","sourceKey":"bank:AMS101:M101-T5N-091","parentItemId":null,"revision":1,"payload":{"prompt":"An interview that asks candidates how they handled real situations in the past is called a:","options":["Realistic job preview","Work sampling test","Assessment centre","Behavioural interview"],"correctOption":3,"section":"Managing Human Resources","explanation":"A behavioural interview asks how a candidate actually handled real situations in the past. Option C puts candidates through simulation exercises to test managerial potential, and option A gives information to the candidate rather than asking about past behaviour."}},{"itemId":"3da64631-a8a1-5a8a-9738-359ebcd0505e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4ffc11d6-74e1-531b-8ce6-2dbe6b1f980d","sourceKey":"bank:AMS101:M101-T5N-092","parentItemId":null,"revision":1,"payload":{"prompt":"References from previous employers are often of little value because:","options":["Referees tend to say only good things","They test managerial potential","They measure only physical fitness","They are too expensive to collect"],"correctOption":0,"section":"Managing Human Resources","explanation":"References are often of little value because referees tend to say only good things about the candidate. Option B describes assessment centres, and option C describes physical examinations."}},{"itemId":"27cba64d-4a12-5102-98cf-d814b1547353","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9756e59b-5fd8-5546-a151-1a05a435a445","sourceKey":"bank:AMS101:M101-T5N-093","parentItemId":null,"revision":1,"payload":{"prompt":"Background investigations involve:","options":["Testing intelligence, aptitude and personality","Rating employees on a scale of 1 to 5","Checking the facts on the application and checking references","Giving applicants a small replica of the job"],"correctOption":2,"section":"Managing Human Resources","explanation":"Background investigations verify what applicants wrote on the application and check their references. Option D is work sampling, option A describes written tests, and option B is a graphic rating scale used in appraisal."}},{"itemId":"e132092f-2630-5c01-bc54-4cbef52adb0e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9593381c-0943-5306-8277-53a0d3f48e2e","sourceKey":"bank:AMS101:M101-T5N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Application forms are most useful in selection for:","options":["Predicting honesty through integrity tests","Testing managerial potential","Giving a realistic picture of the job","Screening out unqualified applicants"],"correctOption":3,"section":"Managing Human Resources","explanation":"Application forms collect basic facts such as name, education and past jobs, which helps screen out unqualified applicants. Option B is the job of assessment centres, and option A belongs to written tests."}},{"itemId":"9f7c0d5a-e3d7-5bc8-b545-0965f3986227","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d70e13e-7066-5a4d-b9b8-97c463995b02","sourceKey":"bank:AMS101:M101-T5N-095","parentItemId":null,"revision":1,"payload":{"prompt":"Intelligence, aptitude, personality and integrity tests belong to which selection device?","options":["Background investigations","Performance-simulation tests","Application forms","Written tests"],"correctOption":3,"section":"Managing Human Resources","explanation":"Intelligence, aptitude, ability, interest, personality and integrity tests are all written tests. Option B is tempting, but performance-simulation tests use actual job behaviour, such as work sampling, rather than paper tests of traits."}},{"itemId":"4c24ed53-2f8d-59ae-b312-c8aeebc02eb4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b344fe8-c371-5173-a9f9-159ff6499f41","sourceKey":"bank:AMS101:M101-T5N-096","parentItemId":null,"revision":1,"payload":{"prompt":"Physical examinations are used in selection mainly:","options":["To check the facts on application forms","To test managerial potential","For jobs with physical demands, and sometimes for insurance purposes","To give applicants realistic job expectations"],"correctOption":2,"section":"Managing Human Resources","explanation":"Physical examinations are used for jobs with physical demands and sometimes for insurance purposes. Option A describes background investigations, and option D describes the purpose of a realistic job preview."}},{"itemId":"6c01608d-f29c-5d97-ba5f-d98c8018925d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4166a4b6-8941-5a3b-a8b9-2b7c0231a2ec","sourceKey":"bank:AMS101:M101-T5N-097","parentItemId":null,"revision":1,"payload":{"prompt":"A preview of a job that gives applicants both positive and negative information about the job and the company is a:","options":["Job description","Organization orientation","Behavioural interview","Realistic job preview"],"correctOption":3,"section":"Managing Human Resources","explanation":"A realistic job preview (RJP) deliberately shares both the good and the bad about the job and the company. Option A states what the job involves but is not designed to show its downsides, and option B happens after hiring."}},{"itemId":"68cdb6d7-6193-598e-9c34-dce361586d70","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"15c51f27-d8d9-58cc-b400-954cabf6ffd7","sourceKey":"bank:AMS101:M101-T5N-098","parentItemId":null,"revision":1,"payload":{"prompt":"Giving applicants a realistic job preview is expected to:","options":["Increase the number of accept errors","Remove the need for orientation","Raise turnover and lower satisfaction","Raise satisfaction and lower turnover"],"correctOption":3,"section":"Managing Human Resources","explanation":"An RJP gives new hires realistic expectations, which raises satisfaction and lowers turnover. Option C is the reverse of what happens, and option B is wrong because orientation is still needed to bring the newcomer into the job."}},{"itemId":"814ef2a1-a3dd-57f8-8e23-555695540a55","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"43f40774-ff8b-58fa-ac1b-32f99f5cadae","sourceKey":"bank:AMS101:M101-T5N-099","parentItemId":null,"revision":1,"payload":{"prompt":"Before hiring, a Port Harcourt oil-service firm tells applicants for offshore jobs about the good pay and also about the long weeks away from home and the harsh conditions. The firm is using a:","options":["Realistic job preview","Background investigation","Work unit orientation","Behavioural interview"],"correctOption":0,"section":"Managing Human Resources","explanation":"Sharing both the attractive and the difficult sides of a job before hiring is a realistic job preview. Option C happens after someone is hired and introduces them to their unit's goals and co-workers."}},{"itemId":"3ae06f82-c982-5d2d-998c-b40ee87935d2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9782fbf4-5b51-56f3-994e-69337b1baf0a","sourceKey":"bank:AMS101:M101-T5N-100","parentItemId":null,"revision":1,"payload":{"prompt":"In Weber's bureaucracy, choosing people on the basis of their technical qualifications is called:","options":["Scientific selection","Affirmative action","Work sampling","Formal selection"],"correctOption":3,"section":"Managing Human Resources","explanation":"Weber called the choice of people by technical qualifications formal selection. Option A is linked with Hugo Munsterberg, who argued for scientifically selecting employees, which is a different idea from Weber's."}},{"itemId":"9afd69b9-56ce-552b-aaf1-feba2125f386","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9eb1f28a-a116-5460-8b2a-9d30bacdf700","sourceKey":"bank:AMS101:M101-T5N-101","parentItemId":null,"revision":1,"payload":{"prompt":"Introducing a new employee to the job and the organization is called:","options":["Job rotation","Career development","Selection","Orientation"],"correctOption":3,"section":"Managing Human Resources","explanation":"Orientation introduces a new employee to the job and the organization, helping them move from outsider to insider. Option C happens before hiring, and option A is a training method in which existing staff move between jobs."}},{"itemId":"4c81e8e0-ab42-5140-a294-c3d9068fd5f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6055fbde-78c4-5052-aa02-55a5952e797f","sourceKey":"bank:AMS101:M101-T5N-102","parentItemId":null,"revision":1,"payload":{"prompt":"The two types of orientation are:","options":["Traditional orientation and technology-based orientation","General orientation and specific orientation","Work unit orientation and organization orientation","Internal orientation and external orientation"],"correctOption":2,"section":"Managing Human Resources","explanation":"Orientation is split into work unit orientation (the unit's goals, how the job fits, co-workers) and organization orientation (company goals, history, policies, benefits). Option A names the two groups of training methods, and option B names the two kinds of training content."}},{"itemId":"b1ff08e7-3885-5f10-a733-6c8737b55ba1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c8e32f5a-e61f-567f-b840-7f35115c3246","sourceKey":"bank:AMS101:M101-T5N-103","parentItemId":null,"revision":1,"payload":{"prompt":"Introducing a new employee to co-workers and explaining how the job adds to the unit's goals is part of:","options":["Mentoring","Job rotation","Work unit orientation","Organization orientation"],"correctOption":2,"section":"Managing Human Resources","explanation":"Work unit orientation covers the goals of the unit, how the job contributes to them, and meeting co-workers. Option D focuses on the company as a whole, such as its history, rules and HR policies."}},{"itemId":"dcb5a9ee-5f88-59b4-9246-0ca2a5f2de15","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b228c1ee-52aa-5e49-9fce-c0d2df9971e2","sourceKey":"bank:AMS101:M101-T5N-104","parentItemId":null,"revision":1,"payload":{"prompt":"Explaining the company's history, philosophy, rules, pay, overtime and fringe benefits to a new employee is part of:","options":["Organization orientation","Job analysis","A realistic job preview","Work unit orientation"],"correctOption":0,"section":"Managing Human Resources","explanation":"Organization orientation covers company-wide matters such as goals, history, philosophy, procedures, rules and HR policies on pay and benefits. Option D focuses only on the employee's own unit and co-workers, and option C is given to applicants before they are hired."}},{"itemId":"aaf91393-f36a-5035-8ae4-abfe09cdc582","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"04c536c3-c3c1-59c4-88f4-563b9b227496","sourceKey":"bank:AMS101:M101-T5N-105","parentItemId":null,"revision":1,"payload":{"prompt":"On his first day at a Lagos bank, a new graduate trainee is taken on a tour of the head office and given a talk on the bank's history and leave policy. This is:","options":["Work sampling","Job rotation","Work unit orientation","Organization orientation"],"correctOption":3,"section":"Managing Human Resources","explanation":"A facilities tour plus information on company history and HR policies such as leave is organization orientation. Option C would focus on his own department's goals and introduce him to his immediate co-workers."}},{"itemId":"96e97cd7-4cb9-5172-8a5b-5987d15db137","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a1a7f20-497b-571c-bac9-a9a86727942c","sourceKey":"bank:AMS101:M101-T5N-106","parentItemId":null,"revision":1,"payload":{"prompt":"A main purpose of orientation is to help the newcomer:","options":["Move from insider to outsider","Choose between job offers","Move from outsider to insider","Negotiate a collective agreement"],"correctOption":2,"section":"Managing Human Resources","explanation":"Orientation helps a new employee move from outsider to insider, which lowers anxiety and makes early mistakes and early quitting less likely. Option A reverses the idea, and option D belongs to unions and management, not to new staff."}},{"itemId":"56e90277-979e-5bd8-ac38-025cd1593ef2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0429376c-0d85-5434-8ca3-d045debbcc0b","sourceKey":"bank:AMS101:M101-T5N-107","parentItemId":null,"revision":1,"payload":{"prompt":"A good orientation programme is expected to:","options":["Increase reject errors in selection","Replace the need for any later training","Lower anxiety and make early quitting less likely","Raise anxiety so that newcomers work harder"],"correctOption":2,"section":"Managing Human Resources","explanation":"Good orientation lowers newcomers' anxiety and makes early mistakes and early quitting less likely. Option B is wrong because orientation does not replace training, which builds job skills over time."}},{"itemId":"5f36ba7d-468c-56a7-8bc7-02e054a4d5be","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa466db6-83cb-55ae-a424-cfc0a65fd94b","sourceKey":"bank:AMS101:M101-T5N-108","parentItemId":null,"revision":1,"payload":{"prompt":"Training methods are grouped into how many broad groups?","options":["Three","Two","Four","Six"],"correctOption":1,"section":"Managing Human Resources","explanation":"Training methods fall into two groups: traditional and technology-based. Option A is the number of groups in the HRM process, which is a common mix-up."}},{"itemId":"57f83db6-c301-55d0-bb80-9e180e1892de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb265813-c29a-5d44-8582-cd2f95d99208","sourceKey":"bank:AMS101:M101-T5N-109","parentItemId":null,"revision":1,"payload":{"prompt":"E-learning (internet-based learning) is classified as a:","options":["Traditional training method","Selection device","Technology-based training method","Performance appraisal method"],"correctOption":2,"section":"Managing Human Resources","explanation":"E-learning, along with videoconferencing and recorded media, is a technology-based training method. Option A covers methods such as on-the-job training, job rotation and classroom teaching, which do not rely on technology."}},{"itemId":"670504b1-7697-571a-88bc-639e24ef2883","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1652b8c-f354-5a2c-89d9-b54f24a220a1","sourceKey":"bank:AMS101:M101-T5N-110","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a traditional training method?","options":["Videoconferencing","Workbooks and manuals","Job rotation","Mentoring and coaching"],"correctOption":0,"section":"Managing Human Resources","explanation":"Videoconferencing is a technology-based training method. Options B, C and D are all traditional methods, together with on-the-job training, experiential exercises and classroom teaching."}},{"itemId":"4c7de522-4f72-5a9d-8474-e1d5490498d2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"80947a3c-1092-5bf1-b2a0-bd716a511eb1","sourceKey":"bank:AMS101:M101-T5N-111","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a technology-based training method?","options":["Classroom lectures","E-learning","DVDs and video recordings","Teleconferencing"],"correctOption":0,"section":"Managing Human Resources","explanation":"Teaching staff face to face in a classroom is a traditional training method. Options B, C and D all rely on technology, such as the internet, phone and video links, or recorded media."}},{"itemId":"611692ee-2c6a-5c86-a9aa-0f84537d472b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"69f7749c-aa3d-5519-8a8f-0a08851759ed","sourceKey":"bank:AMS101:M101-T5N-112","parentItemId":null,"revision":1,"payload":{"prompt":"Role play and simulations used to train staff are examples of:","options":["Performance-simulation selection tests","Behaviourally anchored rating scales","E-learning, a technology-based method","Experiential exercises, a traditional method"],"correctOption":3,"section":"Managing Human Resources","explanation":"Role play and simulations are experiential exercises, listed among traditional training methods. Option A is tempting because simulations are also used in selection, but here they are used to train existing staff, not to choose applicants."}},{"itemId":"bfdd48b1-daf6-519a-bf68-a683611cc8a7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3f5cabd0-7b54-5608-ae0b-10989b4767af","sourceKey":"bank:AMS101:M101-T5N-113","parentItemId":null,"revision":1,"payload":{"prompt":"Sideways transfers that let employees learn several different jobs are called:","options":["Job rotation","Job sharing","Transfers as decruitment","Work sampling"],"correctOption":0,"section":"Managing Human Resources","explanation":"Job rotation moves employees sideways so they learn several jobs, which makes it a training method. Option B is a decruitment option where two part-timers split one job, and option C uses transfers to balance labour supply, not to build skills."}},{"itemId":"06049500-5dcd-515d-989e-21305559dd29","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"34409f70-d0b2-527d-9064-8c0bc6ecbecf","sourceKey":"bank:AMS101:M101-T5N-114","parentItemId":null,"revision":1,"payload":{"prompt":"At a university department in Lagos, a senior administrator is paired with a newly hired officer to advise and support her through her first year. This training method is:","options":["Job rotation","Work unit orientation","Mentoring and coaching","E-learning"],"correctOption":2,"section":"Managing Human Resources","explanation":"An experienced employee advising and supporting a newer one is mentoring and coaching, a traditional training method. Option A would move the new officer between several jobs, and option B is a one-off introduction to the unit rather than ongoing support."}},{"itemId":"44c32e91-4076-5ee8-82ae-be3e2c39a040","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"610a9390-9ff1-5d20-8710-b00b551f68dd","sourceKey":"bank:AMS101:M101-T5N-115","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of SPECIFIC (rather than general) training?","options":["Safety training","Customer service","Computer skills","Communication skills"],"correctOption":0,"section":"Managing Human Resources","explanation":"Safety training is specific training, alongside leadership, diversity awareness, product knowledge and ethics. Options B, C and D are all examples of general training."}},{"itemId":"65e36367-5d8a-5d24-b129-50defb94fa1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8d316097-10a7-512c-971f-4205f41c2161","sourceKey":"bank:AMS101:M101-T5N-116","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of GENERAL (rather than specific) training?","options":["Diversity awareness","Ethics","Customer service","Product knowledge"],"correctOption":2,"section":"Managing Human Resources","explanation":"Customer service training is general, like communication and computer skills. Options A, B and D are all specific training topics, together with safety and leadership."}},{"itemId":"6240c0b9-7c88-57a3-a607-dba3ffbd9aed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3da7b4ea-850f-58a7-98e0-70116a03e445","sourceKey":"bank:AMS101:M101-T5N-117","parentItemId":null,"revision":1,"payload":{"prompt":"Training is the right answer to a performance problem when the employee:","options":["Cannot do the job","Will not do the job","Is about to retire early","Has just been laid off"],"correctOption":0,"section":"Managing Human Resources","explanation":"Training fixes a lack of ability, so it is the answer when the employee cannot do the job. Option B describes a lack of willingness, which calls for discipline or counselling rather than training."}},{"itemId":"4db47fd0-0c18-56a9-9ff1-0605ea90405a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"119cbe56-e38b-535f-aa5f-73c890602048","sourceKey":"bank:AMS101:M101-T5N-118","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a sign that managers should consider training?","options":["More workplace accidents","Lower turnover","Rising output","Fewer customer complaints"],"correctOption":0,"section":"Managing Human Resources","explanation":"More accidents is one of the signs that training may be needed, along with falling output, poorer quality and new technology. Options B, C and D all point to things going well rather than to a skills gap."}},{"itemId":"ec848bb6-c762-5720-be1c-a54ec82b51dc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47bd31c4-8b15-56cc-aff5-1de14caed547","sourceKey":"bank:AMS101:M101-T5N-119","parentItemId":null,"revision":1,"payload":{"prompt":"A process of setting performance standards and appraising employee performance to reach objective HR decisions and keep records that support them is a:","options":["Career development plan","Collective bargaining agreement","Performance management system","Human resource inventory"],"correctOption":2,"section":"Managing Human Resources","explanation":"A performance management system sets standards and appraises performance so HR decisions are objective and backed by records. Option D is simply a record of employees' skills and backgrounds, and option B is a union-management agreement on pay and conditions."}},{"itemId":"e7f5ec90-fa71-577a-9a13-37dc7bfa9f32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"880491b8-23fc-5414-9062-ca60e4a2a944","sourceKey":"bank:AMS101:M101-T5N-120","parentItemId":null,"revision":1,"payload":{"prompt":"How many performance appraisal methods are there?","options":["Eight","Seven","Five","Six"],"correctOption":1,"section":"Managing Human Resources","explanation":"There are seven appraisal methods: written essay, critical incidents, graphic rating scales, BARS, multiperson comparisons, MBO and 360-degree appraisal. Option D is the number of selection devices, and option A is the number of HRM activities."}},{"itemId":"254f4568-2e35-5b4e-be85-897c4fde7756","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"302d207b-0ed4-50e5-a525-35a697672f85","sourceKey":"bank:AMS101:M101-T5N-121","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method in which the evaluator writes about an employee's strengths, weaknesses, past performance and potential is the:","options":["Graphic rating scale","360-degree appraisal","Written essay","Critical incidents method"],"correctOption":2,"section":"Managing Human Resources","explanation":"In the written essay method the evaluator writes about strengths, weaknesses, past performance and potential. Option D is tempting because it is also written, but it records specific behaviours that separate effective from ineffective work rather than a general essay."}},{"itemId":"e76c74bf-c2d4-57ad-b4ec-05a6c3a20085","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"66be0efd-f39f-52be-a997-8a0e40e87d7c","sourceKey":"bank:AMS101:M101-T5N-122","parentItemId":null,"revision":1,"payload":{"prompt":"The main disadvantage of the written essay appraisal method is that it:","options":["Is hard to build","Gives numbers but little depth","Measures the writer's skill as much as the employee's work","Has legal concerns when ranking people"],"correctOption":2,"section":"Managing Human Resources","explanation":"A written essay may reflect how well the evaluator writes as much as how well the employee works. Option B is the drawback of graphic rating scales, and option A is a drawback of BARS."}},{"itemId":"32099d50-f92e-5a72-87b4-30f94c1c9088","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cbf55047-df4f-53dd-9428-7f60986fbebd","sourceKey":"bank:AMS101:M101-T5N-123","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method in which the evaluator records the behaviours that separate effective from ineffective job performance is the:","options":["Management by objectives","Critical incidents method","Written essay","Graphic rating scale"],"correctOption":1,"section":"Managing Human Resources","explanation":"The critical incidents method records behaviours that separate effective from ineffective work, giving rich, behaviour-based examples. Option C is a general description of the employee, and option A judges people on goals achieved, not on recorded behaviours."}},{"itemId":"658ae192-8a04-52b2-8b5d-f67ae5a841f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39216c90-9336-5ccb-ba25-ccf60cf00245","sourceKey":"bank:AMS101:M101-T5N-124","parentItemId":null,"revision":1,"payload":{"prompt":"Which appraisal method gives rich, behaviour-based examples but is time-consuming and produces no numbers?","options":["Graphic rating scales","Written essay","Multiperson comparisons","Critical incidents"],"correctOption":3,"section":"Managing Human Resources","explanation":"Critical incidents give rich, behaviour-based examples, but they take time and do not produce numbers. Option A is the reverse, giving quick numbers but little depth, and option B is simple, with its weakness being that it reflects the writer's skill."}},{"itemId":"770a01e7-5954-5fd2-8483-f4f6682db9f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30e74e00-ceea-5fea-83a3-19eef65167de","sourceKey":"bank:AMS101:M101-T5N-125","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor at a Lagos supermarket rates each cashier from 1 to 5 on quality, attendance and speed. This appraisal method is:","options":["Critical incidents","Graphic rating scales","Written essay","360-degree appraisal"],"correctOption":1,"section":"Managing Human Resources","explanation":"Rating factors such as quality and attendance on a 1 to 5 scale is the graphic rating scale method, which is quick and gives numbers. Option A would involve recording specific behaviours rather than scoring factors on a scale."}},{"itemId":"1ce0a1ed-3a6c-55ea-a404-8c034fcd2f01","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1b9499d-2c95-5889-a753-fa25f9f2e88f","sourceKey":"bank:AMS101:M101-T5N-126","parentItemId":null,"revision":1,"payload":{"prompt":"The main disadvantage of graphic rating scales is that they:","options":["Measure the writer's skill","Produce no numbers","Are hard with many people","Provide little depth"],"correctOption":3,"section":"Managing Human Resources","explanation":"Graphic rating scales are quick and numerical, but they provide little depth. Option B is the drawback of critical incidents, and option C is a drawback of multiperson comparisons."}},{"itemId":"1bd25e94-62c7-5816-a65d-02dd5141573b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f545f09b-6fa9-5ba4-9eb2-28d54f14fd90","sourceKey":"bank:AMS101:M101-T5N-127","parentItemId":null,"revision":1,"payload":{"prompt":"Behaviourally anchored rating scales (BARS) combine which two appraisal methods?","options":["Critical incidents and graphic rating scales","Written essay and MBO","Graphic rating scales and 360-degree appraisal","Multiperson comparisons and critical incidents"],"correctOption":0,"section":"Managing Human Resources","explanation":"BARS combine critical incidents with graphic rating scales, so specific job behaviours are rated on a scale. The other options pair methods that BARS do not combine; for example, option B pairs a narrative method with a goal-based one."}},{"itemId":"48a28575-07d7-5e48-9437-183cc1d34ecb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e28ac4f0-9a67-55b0-9540-0f703dc8bd18","sourceKey":"bank:AMS101:M101-T5N-128","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method that rates specific job behaviours and combines critical incidents with graphic rating scales is:","options":["MBO (management by objectives)","BARS (behaviourally anchored rating scales)","Paired comparison","360-degree appraisal"],"correctOption":1,"section":"Managing Human Resources","explanation":"BARS rate specific job behaviours by combining critical incidents and graphic rating scales. Option A judges employees on how well set goals are achieved, and option D gathers feedback from many people around the employee."}},{"itemId":"15068408-2f3f-5bae-96fa-cef413abd084","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c48a1ab8-94da-580a-9f30-8092a19c56d9","sourceKey":"bank:AMS101:M101-T5N-129","parentItemId":null,"revision":1,"payload":{"prompt":"The main disadvantage of BARS is that it is:","options":["Relative rather than absolute","Time-consuming and hard to build","Simple but shallow","Unable to measure behaviour"],"correctOption":1,"section":"Managing Human Resources","explanation":"BARS focus on specific, measurable behaviours, but they are time-consuming and hard to build. Option C fits graphic rating scales, and option A describes multiperson comparisons, which compare people with each other."}},{"itemId":"c70461ad-fd55-50fb-8357-93bd6ff3d989","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f9616ab-7d8d-5e98-94fb-c508397f191c","sourceKey":"bank:AMS101:M101-T5N-130","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method that compares one person's performance with that of others is:","options":["Written essay","Graphic rating scale","Management by objectives","Multiperson comparison"],"correctOption":3,"section":"Managing Human Resources","explanation":"Multiperson comparisons rank employees against each other rather than against a standard. Option B rates each person on fixed factors, and option C judges each person on their own goals."}},{"itemId":"4e8b5ca1-7217-5804-a484-afcd04d53b1d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78c42cad-d3db-50f4-b74a-934c130265c8","sourceKey":"bank:AMS101:M101-T5N-131","parentItemId":null,"revision":1,"payload":{"prompt":"Which appraisal method is hard to use with many people and raises legal concerns?","options":["Multiperson comparisons","Graphic rating scales","Management by objectives","Critical incidents"],"correctOption":0,"section":"Managing Human Resources","explanation":"Multiperson comparisons become difficult with large numbers of employees and can raise legal concerns. Option C is results-focused but time-consuming, and option D is time-consuming and gives no numbers."}},{"itemId":"ca6c0257-a474-5f68-8c78-11f8655f7783","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"92226274-c574-5690-a83b-c75bc2bd8675","sourceKey":"bank:AMS101:M101-T5N-132","parentItemId":null,"revision":1,"payload":{"prompt":"At a Lagos telecoms firm, each sales officer agrees targets with the manager at the start of the year and is appraised on how well those targets are achieved. This appraisal method is:","options":["BARS","Paired comparison","Management by objectives (MBO)","Graphic rating scales"],"correctOption":2,"section":"Managing Human Resources","explanation":"Judging employees on how well agreed goals are achieved is MBO, a results-focused method. Option A rates specific job behaviours rather than results, and option B compares each employee with every other one."}},{"itemId":"f02a87e8-9683-520d-8703-0c189c4284a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ead73b4-eae3-50c1-bbac-39bcd1b81451","sourceKey":"bank:AMS101:M101-T5N-133","parentItemId":null,"revision":1,"payload":{"prompt":"An appraisal method that uses feedback from supervisors, co-workers, subordinates, customers and the employee himself or herself is:","options":["360-degree appraisal","Multiperson comparison","Critical incidents","Management by objectives"],"correctOption":0,"section":"Managing Human Resources","explanation":"360-degree appraisal gathers feedback from all around the employee: supervisors, co-workers, subordinates, customers and self. It is thorough but time-consuming. Option B uses many people too, but it ranks employees against each other instead of collecting feedback about one person."}},{"itemId":"d3e43642-84b2-525c-b249-5874e30a2220","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6d5e2ea7-9b91-57c2-aef0-80b8e00532c1","sourceKey":"bank:AMS101:M101-T5N-134","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three kinds of multiperson comparison?","options":["Individual ranking","Group order ranking","Critical incidents","Paired comparison"],"correctOption":2,"section":"Managing Human Resources","explanation":"Critical incidents is a separate appraisal method that records behaviours, not a way of comparing people with each other. Options A, B and D are the three kinds of multiperson comparison."}},{"itemId":"3f229dc4-71d3-5d48-9911-593b59e037de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25262381-1858-559d-8f98-190b1b382617","sourceKey":"bank:AMS101:M101-T5N-135","parentItemId":null,"revision":1,"payload":{"prompt":"Placing employees into groups such as \"top fifth\" or \"second fifth\" is called:","options":["Group order ranking","Individual ranking","Graphic rating scale","Paired comparison"],"correctOption":0,"section":"Managing Human Resources","explanation":"Group order ranking places employees into bands such as top fifth or second fifth. Option B lists every employee from best to worst, and option D compares each employee with every other one in pairs."}},{"itemId":"05063654-14d7-59bb-9afd-6ff26ac9b6b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5a8dfdcd-403f-5aba-bbac-31fce7c9a98f","sourceKey":"bank:AMS101:M101-T5N-136","parentItemId":null,"revision":1,"payload":{"prompt":"Listing employees in order from best to worst is called:","options":["Group order ranking","Individual ranking","Paired comparison","360-degree appraisal"],"correctOption":1,"section":"Managing Human Resources","explanation":"Individual ranking lists employees one by one from best to worst. Option A puts them into broad groups such as the top fifth instead, and option C compares them two at a time."}},{"itemId":"5effd14e-50f7-5848-957d-4eb3a8ee1f82","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7176fcf0-2bd5-502f-bf61-61ce3130391d","sourceKey":"bank:AMS101:M101-T5N-137","parentItemId":null,"revision":1,"payload":{"prompt":"A branch manager at a Lagos bank takes her six tellers and compares each one with every other teller, marking who is stronger in each pair. This method is:","options":["Paired comparison","Critical incidents","Individual ranking","Group order ranking"],"correctOption":0,"section":"Managing Human Resources","explanation":"Comparing each employee with every other one and rating who is stronger in each pair is paired comparison. Option C would list the tellers straight from best to worst without working through pairs."}},{"itemId":"b1fa255c-3891-522b-a3c2-2fbdb009c512","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"32763d8c-5e4c-559c-9eab-e0a210583f35","sourceKey":"bank:AMS101:M101-T5N-138","parentItemId":null,"revision":1,"payload":{"prompt":"Multiperson comparisons differ from the other appraisal methods because they are:","options":["Based only on self-assessment","Absolute, comparing person with a standard","Concerned only with future potential","Relative, comparing person with person"],"correctOption":3,"section":"Managing Human Resources","explanation":"Multiperson comparisons are relative, measuring each person against other people, while the other methods are absolute, measuring each person against a standard. Option B describes those other methods, such as graphic rating scales and BARS."}},{"itemId":"5f6fd38f-af56-5bf2-9bfa-67706c06916b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ab003ea-0de6-5820-8d1d-41e486825d31","sourceKey":"bank:AMS101:M101-T5N-139","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following appraisal methods is RELATIVE rather than absolute?","options":["BARS","Management by objectives","Graphic rating scales","Individual ranking"],"correctOption":3,"section":"Managing Human Resources","explanation":"Individual ranking is a multiperson comparison, so it is relative, measuring employees against one another. Options A, B and C are absolute methods, measuring each person against a standard or a goal."}},{"itemId":"873af4a9-c201-5d90-aff0-2a3f05ccbbcd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a0453b98-e650-5a49-ac1a-e865e6679469","sourceKey":"bank:AMS101:M101-T5N-140","parentItemId":null,"revision":1,"payload":{"prompt":"A production supervisor in Ota finds that a machine operator's output is poor because he has never learnt to use the new equipment. The best response is to:","options":["Reduce his workweek","Train or coach him","Discipline him","Fire him at once"],"correctOption":1,"section":"Managing Human Resources","explanation":"When poor performance comes from a lack of ability, the answer is to train or coach. Option C is meant for a lack of willingness, which is not the problem here since he simply does not know how to use the equipment."}},{"itemId":"05175d77-568c-51c5-b580-ceeb5e8b91c1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c49cc0fd-b2d3-53c9-b342-017bbe0a553c","sourceKey":"bank:AMS101:M101-T5N-141","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital records officer knows exactly how to file patient records but keeps refusing to do it on time. The supervisor should respond with:","options":["Discipline or counselling","A realistic job preview","A job specification","More technical training"],"correctOption":0,"section":"Managing Human Resources","explanation":"When an employee can do the job but will not, the problem is willingness, which calls for discipline or counselling. Option D would only help if she lacked the ability to do the filing, which she does not."}},{"itemId":"c3362b7a-fdc5-50fa-9400-3038db4a17f6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5291dcb9-4cc9-514f-9720-8500354cb550","sourceKey":"bank:AMS101:M101-T5N-142","parentItemId":null,"revision":1,"payload":{"prompt":"Actions a manager takes to enforce the organization's standards and rules are called:","options":["Mentoring","Employee counselling","Discipline","Orientation"],"correctOption":2,"section":"Managing Human Resources","explanation":"Discipline means the actions a manager takes to enforce the organization's standards and rules. Option B is a process that helps employees overcome performance-related problems, which is supportive rather than enforcing."}},{"itemId":"15487131-4c13-55bc-984a-687c7d731d10","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cbf5a4e1-a9f4-5f2e-ac20-79fc83ca938d","sourceKey":"bank:AMS101:M101-T5N-143","parentItemId":null,"revision":1,"payload":{"prompt":"A process designed to help employees overcome performance-related problems is:","options":["Performance appraisal","Decruitment","Discipline","Employee counselling"],"correctOption":3,"section":"Managing Human Resources","explanation":"Employee counselling helps employees overcome performance-related problems. Option C is about enforcing rules and standards, and option A measures performance but does not by itself help the employee overcome problems."}},{"itemId":"7e31da2e-6278-5f3d-b62e-ebb4b0b55990","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"64786f8d-b9a5-55d6-8dcb-d6c7de3ee8e7","sourceKey":"bank:AMS101:M101-T5N-144","parentItemId":null,"revision":1,"payload":{"prompt":"Pay that rewards employees for the job skills they can demonstrate is called:","options":["Variable pay","Fringe benefits","Base pay","Skill-based pay"],"correctOption":3,"section":"Managing Human Resources","explanation":"Skill-based pay rewards employees for the job skills they can demonstrate. Option A ties pay to performance rather than skills, which is the classic mix-up between the two."}},{"itemId":"a87a9114-6bb7-57d3-8e14-1cb739cfc0ee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a52c715b-9e5c-5e50-9ef0-8b5901b10041","sourceKey":"bank:AMS101:M101-T5N-145","parentItemId":null,"revision":1,"payload":{"prompt":"Pay in which an individual's compensation depends on performance is called:","options":["Base pay","Variable pay","Benefits","Skill-based pay"],"correctOption":1,"section":"Managing Human Resources","explanation":"Variable pay makes an individual's compensation depend on performance. Option D rewards demonstrated skills instead, so an employee could earn more for a new skill even if results do not change."}},{"itemId":"83455a69-511c-57a2-b5bb-812c1a730384","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5375c8ba-d9f2-52a5-a1b5-f03300897fea","sourceKey":"bank:AMS101:M101-T5N-146","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos insurance agent earns a commission that rises and falls with the number of policies she sells each month. This is an example of:","options":["Variable pay","Skill-based pay","A collective bargaining agreement","A fringe benefit"],"correctOption":0,"section":"Managing Human Resources","explanation":"Pay that changes with the agent's sales results depends on performance, so it is variable pay. Option B would reward her for skills she can demonstrate, not for the number of policies sold."}},{"itemId":"59dd7d96-9d72-5684-8fba-77f90412bc63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f2257536-5744-5565-85c4-31c43e5fcb46","sourceKey":"bank:AMS101:M101-T5N-147","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos hospital raises a technician's pay after he proves he can operate both the X-ray and the ultrasound machines. This is an example of:","options":["A fringe benefit","Attrition","Skill-based pay","Variable pay"],"correctOption":2,"section":"Managing Human Resources","explanation":"Rewarding the technician for a job skill he can demonstrate is skill-based pay. Option D would tie his pay to his results or performance rather than to the skills he has shown."}},{"itemId":"dd0f7dad-9b60-5705-85b6-9bb8208912dd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4aa2a1dc-fe26-5150-853c-df8b29bf205e","sourceKey":"bank:AMS101:M101-T5N-148","parentItemId":null,"revision":1,"payload":{"prompt":"Extra, nonwage rewards such as health care, pensions and paid leave are called:","options":["Variable pay","Incentives","Base pay","Benefits"],"correctOption":3,"section":"Managing Human Resources","explanation":"Benefits are the extra, nonwage rewards in compensation, such as health care, pensions and paid leave, and some are required by law. Options C and B are the other parts of compensation, which are paid as money for the work itself or for results."}},{"itemId":"bafb0817-cce7-5c86-a1fa-f7b9e6e3bed3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07299b39-2356-5c9e-8843-d40acac71557","sourceKey":"bank:AMS101:M101-T5N-149","parentItemId":null,"revision":1,"payload":{"prompt":"Compensation is made up of:","options":["Base pay only","Benefits and pensions only","Training and career development","Base pay, incentives and benefits"],"correctOption":3,"section":"Managing Human Resources","explanation":"Compensation includes base pay, incentives and benefits. Option A leaves out incentives and benefits, and option C describes HRM activities that build skills and careers rather than rewards."}},{"itemId":"bfd477ca-1881-593b-b705-437dfbdb1e01","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84ca8f76-dfce-51cb-b21a-3b5112e4928b","sourceKey":"bank:AMS101:M101-T5N-150","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT listed as a factor that influences pay levels?","options":["Company size","Whether staff are unionised","Geographic location","The employee's marital status"],"correctOption":3,"section":"Managing Human Resources","explanation":"Marital status is not among the factors that influence pay levels. Options A, B and C are all listed, together with tenure and performance, kind of job and business, labour or capital intensity, management's pay philosophy and profitability."}},{"itemId":"ce1ef725-de46-50f1-9ae6-ab9ca2087cb4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"859515db-3e4d-5ade-beee-d028557dd094","sourceKey":"bank:AMS101:M101-T5N-151","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is listed as a factor that influences pay levels?","options":["Whether the firm is labour- or capital-intensive","The employee's state of origin","The number of co-workers' children","The employee's religion"],"correctOption":0,"section":"Managing Human Resources","explanation":"Whether a firm is labour-intensive or capital-intensive is one of the listed factors influencing pay levels. Options B, C and D have nothing to do with the job, the business or the employee's performance, so they are not pay factors."}},{"itemId":"4deded95-6869-5869-8611-06e2ea181582","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bc832861-ea20-581d-8324-7750cc334f32","sourceKey":"bank:AMS101:M101-T5N-152","parentItemId":null,"revision":1,"payload":{"prompt":"The sequence of positions a person holds over a lifetime is called a:","options":["Job rotation","Job description","Human resource inventory","Career"],"correctOption":3,"section":"Managing Human Resources","explanation":"A career is the sequence of positions a person holds over a lifetime. Option B describes a single job, and option A is a training method that moves people between jobs for a short time."}},{"itemId":"64d1893e-4c9b-5722-8dcd-6f05d2c678f8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dcef7842-6e86-5091-84f1-e97ffcaf2760","sourceKey":"bank:AMS101:M101-T5N-153","parentItemId":null,"revision":1,"payload":{"prompt":"Career development, as an HRM activity, is best described as:","options":["Comparing each employee with every other employee","Helping employees plan and grow their careers inside the organization","Reducing the workforce through early retirements","Introducing a new employee to the organization"],"correctOption":1,"section":"Managing Human Resources","explanation":"Career development is the HRM activity that helps employees plan and grow their careers inside the organization; employees are also expected to take charge of their own careers. Option D describes orientation, and option C is a decruitment option."}},{"itemId":"0adfbde9-c2b0-5636-bb3b-90c6ad5bd490","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d5080dea-6d78-5786-a4dd-43cd6b5b8f9c","sourceKey":"bank:AMS101:M101-T5N-154","parentItemId":null,"revision":1,"payload":{"prompt":"The planned elimination of jobs in an organization is called:","options":["Job sharing","Attrition","Layoff-survivor sickness","Downsizing"],"correctOption":3,"section":"Managing Human Resources","explanation":"Downsizing is the planned elimination of jobs. Option B cuts staff only by not replacing those who leave, and option C is the reaction of employees who remain after cuts, not the cuts themselves."}},{"itemId":"81e3dbb5-5f3e-5727-bd4c-dad2ccc6b4d8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a37b2b33-e41b-5d97-9efd-d27af08e80da","sourceKey":"bank:AMS101:M101-T5N-155","parentItemId":null,"revision":1,"payload":{"prompt":"The set of attitudes, perceptions and behaviours of employees who remain after involuntary staff cuts is called:","options":["Hostile environment","Layoff-survivor sickness","Attrition","Downsizing"],"correctOption":1,"section":"Managing Human Resources","explanation":"Layoff-survivor sickness describes how the employees who stay react after involuntary cuts. Option D is the planned cutting of jobs that causes it, and option A is a form of sexual harassment."}},{"itemId":"ef890638-bfcc-5573-95a7-6ad84f713b01","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d191a98-1516-501b-8adb-777a804eb8c1","sourceKey":"bank:AMS101:M101-T5N-156","parentItemId":null,"revision":1,"payload":{"prompt":"Layoff-survivor sickness affects which group of people?","options":["Employees who were laid off","Applicants rejected in selection","Employees who took early retirement","Employees who remain after the cuts"],"correctOption":3,"section":"Managing Human Resources","explanation":"Layoff-survivor sickness affects the survivors, meaning the people who stay after involuntary staff cuts. Option A is the classic trap, because the people who left are not the ones described by this term."}},{"itemId":"10919051-14e8-513d-8660-cf8324b25223","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6545af79-9ae4-5053-9360-66176ba0b339","sourceKey":"bank:AMS101:M101-T5N-157","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a sign of layoff-survivor sickness?","options":["Higher motivation","Job insecurity","A sense of unfairness","Guilt and stress"],"correctOption":0,"section":"Managing Human Resources","explanation":"Survivors tend to show lower, not higher, motivation. Options B, C and D are all listed signs, along with lower commitment."}},{"itemId":"369b1aaa-256c-5cb3-a57a-07335d6c7147","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b2255f7-c6e6-5135-b506-cf2a3798d665","sourceKey":"bank:AMS101:M101-T5N-158","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recommended way to treat employees who are leaving during downsizing?","options":["Give notice and offer severance pay and outplacement","Announce the cuts without any notice","Keep the reasons for the cuts secret","Cut all benefits immediately"],"correctOption":0,"section":"Managing Human Resources","explanation":"Departing staff should be treated with respect: open and honest communication, notice, and help such as severance pay, extended benefits and outplacement. Options B, C and D all go against that advice."}},{"itemId":"c47320f0-3c67-595b-bb0c-6c05afd2eae2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"20efc04f-58a3-50aa-9413-a83888d51c39","sourceKey":"bank:AMS101:M101-T5N-159","parentItemId":null,"revision":1,"payload":{"prompt":"To help survivors after downsizing, managers should:","options":["Avoid discussing the cuts so people forget them","Increase their workload without explanation","Let them talk about their feelings and explain the reasons for the cuts","Hold back information to prevent rumours"],"correctOption":2,"section":"Managing Human Resources","explanation":"Managers help survivors by giving them chances to talk about their feelings and by explaining the reasons for the cuts. Options A and D keep people in the dark, which tends to worsen insecurity and the sense of unfairness."}},{"itemId":"6fd73936-f28c-55f5-b1f6-53f48c8bf559","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"afcde49a-ce1f-5727-8f89-3aef962af0f2","sourceKey":"bank:AMS101:M101-T5N-160","parentItemId":null,"revision":1,"payload":{"prompt":"Any unwanted action or activity of a sexual nature that explicitly or implicitly affects a person's employment, performance or work environment is:","options":["Layoff-survivor sickness","Workplace spirituality","Discipline","Sexual harassment"],"correctOption":3,"section":"Managing Human Resources","explanation":"Sexual harassment is any unwanted sexual action or activity that affects a person's employment, performance or work environment, whether explicitly or implicitly. Option B is about meaningful work in a community, and option C is a manager's enforcement of rules."}},{"itemId":"2960d20e-805f-5ce9-a3be-3ae902b01b1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f616df2-d396-579d-ad3a-3b8598c4861b","sourceKey":"bank:AMS101:M101-T5N-161","parentItemId":null,"revision":1,"payload":{"prompt":"A manager at a Lagos firm tells a junior staff member that her promotion depends on her agreeing to sexual favours. This form of sexual harassment is:","options":["Affirmative action","Quid pro quo","Layoff-survivor sickness","Hostile environment"],"correctOption":1,"section":"Managing Human Resources","explanation":"Tying a job benefit such as promotion to sexual favours is quid pro quo harassment. Option D is the other form, where sexual conduct makes the workplace offensive or intimidating without a specific job benefit being traded."}},{"itemId":"e38f173b-2796-5611-8e9b-e8a39d0ea0b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9425cc0b-4bd9-5e30-a1c5-8d9f4e21b805","sourceKey":"bank:AMS101:M101-T5N-162","parentItemId":null,"revision":1,"payload":{"prompt":"In an Ibadan office, co-workers keep sharing sexual jokes and pictures that make a colleague feel intimidated, though no job benefit is involved. This form of sexual harassment is:","options":["Employee counselling","Hostile environment","Quid pro quo","Discipline"],"correctOption":1,"section":"Managing Human Resources","explanation":"Sexual conduct that creates an offensive or intimidating workplace is hostile environment harassment, and it can come from co-workers, not just managers. Option C needs a job benefit to be tied to sexual favours, which is not the case here."}},{"itemId":"be2c70cf-4dfa-5ffe-bfb2-e16536a25614","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"edc5d9be-bfb2-5efa-83f2-696888c57a38","sourceKey":"bank:AMS101:M101-T5N-163","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about sexual harassment at work is TRUE?","options":["It can only happen to women","It can only come from a manager","It can come from a manager or a co-worker and can happen to men or women","It counts only if a job benefit is involved"],"correctOption":2,"section":"Managing Human Resources","explanation":"Sexual harassment can come from a manager or a co-worker and can happen to men or women. Option D is wrong because hostile environment harassment involves no job benefit at all."}},{"itemId":"e39ed381-a384-528b-9be9-092328e483f7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1454d652-f4e7-5e2c-aeff-ddcef2197529","sourceKey":"bank:AMS101:M101-T5N-164","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a recommended way for managers to prevent sexual harassment?","options":["Training for staff","A clear written policy","Delaying investigation of complaints","A safe way to report"],"correctOption":2,"section":"Managing Human Resources","explanation":"Complaints should be investigated promptly, so delaying them is the opposite of good practice. Options A, B and D are all recommended steps for preventing harassment."}},{"itemId":"9cf77dfa-c14c-55d1-8257-8d9d0b1459ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e2ec61b-f882-5655-8cd3-b101017a1927","sourceKey":"bank:AMS101:M101-T5N-165","parentItemId":null,"revision":1,"payload":{"prompt":"A culture in which organizational values promote a sense of purpose through meaningful work that takes place in the context of community is called:","options":["Affirmative action","Workplace spirituality","High-performance work practices","Organization orientation"],"correctOption":1,"section":"Managing Human Resources","explanation":"Workplace spirituality is a culture where values promote purpose through meaningful work in a community setting. Option C refers to practices that raise performance, and option D introduces new employees to the company."}},{"itemId":"798c80e1-f7b4-55f2-a4c9-150c708787a8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f4a4039-df6c-5ba2-a649-0b6cd399eca2","sourceKey":"bank:AMS101:M101-T5N-166","parentItemId":null,"revision":1,"payload":{"prompt":"Workplace spirituality is mainly about:","options":["Ranking employees from best to worst","Meaning and community at work","Practising organized religion at work","Reducing pension costs"],"correctOption":1,"section":"Managing Human Resources","explanation":"Workplace spirituality is about meaning and community at work, not about organized religion. Option C is the common misunderstanding of the term."}},{"itemId":"0395b121-3595-5587-b302-73abf0cfda78","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"44fd9b0b-0b18-55ce-8c8d-2f2e708251a3","sourceKey":"bank:AMS101:M101-T5N-167","parentItemId":null,"revision":1,"payload":{"prompt":"How many features of a spiritual organization are identified?","options":["Three","Seven","Four","Five"],"correctOption":3,"section":"Managing Human Resources","explanation":"There are five features: a strong sense of purpose, focus on individual development, trust and openness, employee empowerment, and toleration of employee expression. Option B is the number of decruitment options or appraisal methods, not features of a spiritual organization."}},{"itemId":"f74af8cc-11a1-5227-8375-b9b634f1bbdc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1add77b1-bb6f-5fe2-a7b8-776bbe66c2a6","sourceKey":"bank:AMS101:M101-T5N-168","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of a spiritual organization?","options":["Strong sense of purpose","Strict control of what employees say","Trust and openness","Employee empowerment"],"correctOption":1,"section":"Managing Human Resources","explanation":"Spiritual organizations tolerate employee expression, so strict control of what employees say is the opposite. Options A, C and D are all features, along with a focus on individual development."}},{"itemId":"3ce28c4e-0449-5cc0-8a0a-fdedaf306f12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"118b79a7-e984-5f36-96c0-704328d87b48","sourceKey":"bank:AMS101:M101-T5N-169","parentItemId":null,"revision":1,"payload":{"prompt":"Which two HR costs are organizations especially trying to control?","options":["Employee health care and employee pensions","Recruitment adverts and orientation tours","Interview costs and physical examinations","Union dues and training manuals"],"correctOption":0,"section":"Managing Human Resources","explanation":"The HR costs firms are especially trying to control are employee health care and employee pensions. The other options list smaller HRM expenses that are not singled out as major cost concerns."}},{"itemId":"61a0f716-eda7-5719-9af6-d1e69419e536","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"17a7dac6-748c-559b-bf08-c688990622cf","sourceKey":"bank:AMS101:M101-T5N-170","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank runs a wellness programme and rewards staff who keep healthy habits. Its main aim, as an HR cost issue, is to:","options":["Cut health care costs","Reduce turnover through an RJP","Avoid collective bargaining","Increase variable pay"],"correctOption":0,"section":"Managing Human Resources","explanation":"Wellness programmes and rewards for healthy habits are used to cut employee health care costs. Option D is about linking pay to performance, which wellness programmes do not do."}},{"itemId":"cce4c58c-f98d-55f9-b5f1-fbdc2ad12ab1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b75528a-e6a0-54b1-b26b-532d7a83ce30","sourceKey":"bank:AMS101:M101-T5N-171","parentItemId":null,"revision":1,"payload":{"prompt":"How do organizations mainly try to control employee pension costs?","options":["By increasing job rotation","By reducing or redesigning pension plans","By running wellness programmes","By using realistic job previews"],"correctOption":1,"section":"Managing Human Resources","explanation":"Firms control pension costs by reducing or redesigning their pension plans. Option C is the method used to cut health care costs, which is the other major HR cost."}},{"itemId":"0cd470e9-30f4-56b4-84cb-bcbc176aa067","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07d561db-599b-54d2-818b-9acf1c7d5d4a","sourceKey":"bank:AMS101:M101-T5N-172","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recommended way of managing workforce diversity?","options":["Removing orientation programmes","Widening the recruiting net and using bias-free selection","Recruiting only through internal search","Recruiting only through employee referrals"],"correctOption":1,"section":"Managing Human Resources","explanation":"Managing diversity involves widening the recruiting net, using bias-free selection, and using orientation and diversity training. Options D and C are the two recruiting channels that may not add diversity, so relying on them alone works against it."}},{"itemId":"e10dde39-fa37-5e78-b372-0a52a5f0fd0d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e107b97b-01af-559c-9f9c-96e6f2c9c252","sourceKey":"bank:AMS101:M101-T6N-001","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational change is best defined as:","options":["Any alteration of people, structure or technology in an organization","A planned increase in an organization's market share","The replacement of top managers with outside consultants","The process of turning creative ideas into useful products"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Organizational change covers any alteration of people, structure or technology, so it is a broad idea, not one specific event. Option D describes innovation, which is only one kind of outcome, and Option C is just one possible change, not the definition."}},{"itemId":"c65c3667-f4e3-5c84-bc93-108632d75e76","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"40bbb0b5-1cb4-5231-b48a-b9d414651c81","sourceKey":"bank:AMS101:M101-T6N-002","parentItemId":null,"revision":1,"payload":{"prompt":"Any alteration of people, structure or technology in an organization is called:","options":["Organizational development","Organizational change","Innovation","Refreezing"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"This is the definition of organizational change. Option A, organizational development, is a set of techniques for changing people and work relationships, so it is one tool for change rather than change itself. Option D is the last step of Lewin's model."}},{"itemId":"d195c5c7-2742-50da-b8c7-30d4d139accb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7099257d-68ce-5cea-b351-7c22cc624f6d","sourceKey":"bank:AMS101:M101-T6N-003","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational change can involve which three things?","options":["Planning, organizing and controlling","Inputs, transformation and outputs","Strategy, culture and finance","People, structure and technology"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Change can touch people, structure or technology, which is easy to remember as \"PST\". Option C mixes in terms that are not the three areas of change, and Option B is the systems view of innovation."}},{"itemId":"950dc69c-74f4-5a17-a5b0-5513413d8eeb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"20a2daa2-2a44-5a04-8b25-197506dcae6b","sourceKey":"bank:AMS101:M101-T6N-004","parentItemId":null,"revision":1,"payload":{"prompt":"A change agent is:","options":["A force that pushes behaviour away from the status quo","A person who acts as a catalyst and takes responsibility for managing the change process","An employee who resists change because he or she prefers routine","An individual who actively supports new ideas and makes sure innovations are implemented"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"A change agent is the catalyst who takes charge of managing the change process. Option D describes an idea champion, who pushes innovations, and Option A describes a driving force, which is a force, not a person."}},{"itemId":"a347facb-f0f8-52c8-9196-fb76e70505b7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab7512fb-9495-5f2a-a78b-bef47c28ceb3","sourceKey":"bank:AMS101:M101-T6N-005","parentItemId":null,"revision":1,"payload":{"prompt":"A person who acts as a catalyst and assumes responsibility for managing the change process is known as a(n):","options":["Restraining force","Change agent","Driving force","Idea champion"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"That role is the change agent. Option D, an idea champion, enthusiastically backs new ideas and innovations, which is related but not the same as managing the whole change process. Option C and Option A are forces in Lewin's model, not people."}},{"itemId":"c1e9b2f2-8bff-5507-b397-a21b11d84ce0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"607f6710-47e5-51f1-93f4-e5e025927b99","sourceKey":"bank:AMS101:M101-T6N-006","parentItemId":null,"revision":1,"payload":{"prompt":"How many external forces for change are commonly identified?","options":["Four","Six","Five","Three"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"There are five external forces: the marketplace, government laws and regulations, technology, labour markets and economic changes. Option A, four, is the number of internal forces, which is why it is the easiest option to confuse."}},{"itemId":"d31522b2-b323-52be-a244-2c448059a2b3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b04e7614-3a8f-598f-a267-6c5747c72047","sourceKey":"bank:AMS101:M101-T6N-007","parentItemId":null,"revision":1,"payload":{"prompt":"How many internal forces for change are commonly identified?","options":["Five","Three","Four","Six"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"There are four internal forces: changes in strategy, changes in the workforce, new equipment and changes in employee attitudes. Option A, five, is the number of external forces."}},{"itemId":"cffeff74-47d0-50ba-a890-98e13ffba9c3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"558d0654-e5ee-5f85-b0ce-788c4bf43d2f","sourceKey":"bank:AMS101:M101-T6N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an external force for change?","options":["The marketplace","Changes in organizational strategy","Labour markets","Government laws and regulations"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"A change in strategy is decided inside the organization, so it is an internal force. The marketplace, government laws and labour markets (options A, C and D) all come from outside the organization."}},{"itemId":"a5c80fe0-542c-5d2d-b5b7-b38488b70e59","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"815ae7c1-8579-5df7-a92a-918aab6c98a5","sourceKey":"bank:AMS101:M101-T6N-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an internal force for change?","options":["New equipment","Changes in employee attitudes","Economic changes such as inflation and recession","Changes in the workforce"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Interest rates, inflation and recession come from the wider economy, so economic changes are an external force. New equipment, workforce changes and employee attitudes (options A, B and D) all start inside the organization."}},{"itemId":"bbacd587-861a-5d19-8313-da6dd347deb3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"090b99be-ec91-52a2-8223-2057545f8de3","sourceKey":"bank:AMS101:M101-T6N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an external force for change?","options":["Changes in organizational strategy","New equipment","Changes in employee attitudes","Technology"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Technology is listed among the five external forces. Option B is tempting because it sounds like technology, but buying new equipment is a decision made inside the firm, so it is an internal force."}},{"itemId":"8ca37999-fd8f-5cb7-af0f-5e70650f2d3d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"142e672e-f3af-5d0c-89aa-a84762dc0c37","sourceKey":"bank:AMS101:M101-T6N-011","parentItemId":null,"revision":1,"payload":{"prompt":"The federal government passes a new minimum wage law, and a commercial bank in Lagos must review its pay structure. This is an example of:","options":["An internal force for change from changes in employee attitudes","An external force for change from government laws and regulations","An internal force for change from changes in organizational strategy","An external force for change from the marketplace"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"A new law comes from outside the bank, so it is an external force under government laws and regulations. Option C is wrong because the bank did not choose a new strategy on its own, and Option D is wrong because the marketplace refers to competitors and customers."}},{"itemId":"3806cfa4-4263-5a72-aa3f-35b09f471847","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"406b5a04-3fca-5586-bf39-84f0495a4f70","sourceKey":"bank:AMS101:M101-T6N-012","parentItemId":null,"revision":1,"payload":{"prompt":"A soap manufacturer in Ota buys new machines for its factory. As a force for change, this is:","options":["An internal force, new equipment","An external force, technology","An external force, the marketplace","An internal force, changes in the workforce"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Buying new machines is the firm's own action, so it is the internal force called new equipment. Option B is the common trap: technology as a general trend is external, but new equipment bought by the firm is internal."}},{"itemId":"087e837e-c8f3-5bfe-b8f5-df0aea01c4fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af3ece29-bb6c-516d-911e-70e5eda381b0","sourceKey":"bank:AMS101:M101-T6N-013","parentItemId":null,"revision":1,"payload":{"prompt":"A rival beverage company launches a cheaper product, and a Lagos drinks firm is forced to rethink its prices. This force for change is:","options":["External, from the marketplace","External, from labour markets","Internal, from changes in organizational strategy","Internal, from new equipment"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"A competitor's action comes from outside the firm, so it is an external marketplace force. Option C is tempting because the firm may respond with a new strategy, but the force that triggered the change is the rival's move."}},{"itemId":"9c74fa49-8c7e-5aa8-9705-f88eb2546c94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ec5acd1-5fb1-5b10-a045-9c96ddc8c9c2","sourceKey":"bank:AMS101:M101-T6N-014","parentItemId":null,"revision":1,"payload":{"prompt":"An engineering firm in Port Harcourt cannot fill vacancies because there is a shortage of skilled engineers in the country. This force for change is:","options":["Internal, from changes in employee attitudes","Internal, from changes in the workforce","External, from economic changes","External, from labour markets"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Labour markets are about the supply of and demand for workers, and a national shortage of engineers is a shift in that supply, so it is external. Option B refers to the make-up of the firm's own staff, such as age, education or gender, which is internal."}},{"itemId":"f251bbaa-1408-58b4-9081-277ee9b38a80","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dc9b4761-1eb2-5ac0-9a05-cdd6cf6c09ff","sourceKey":"bank:AMS101:M101-T6N-015","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos food company decides to expand into a new market in East Africa. This decision is a(n):","options":["External force for change, the marketplace","External force for change, economic changes","Internal force for change, a change in organizational strategy","Internal force for change, new equipment"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Choosing to enter a new market is a strategic decision made inside the firm, so it is an internal force from strategy. Option A is tempting because markets are involved, but the marketplace force refers to outside pressures like competitors and customer needs."}},{"itemId":"d93f9c3b-a4f2-53c0-b6a8-a3409f823f8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2ec276e6-8155-51ba-bc3e-9c904ad1aa4b","sourceKey":"bank:AMS101:M101-T6N-016","parentItemId":null,"revision":1,"payload":{"prompt":"Rising interest rates and high inflation push a Nigerian microfinance bank to change how it lends. This is an example of which force for change?","options":["Labour markets","Changes in organizational strategy","Government laws and regulations","Economic changes"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Interest rates, inflation and recession are examples of economic changes, an external force. Option C would apply only if a new law or regulation caused the change, and Option B concerns the supply of and demand for workers."}},{"itemId":"4d545628-bdec-5614-8f1f-c30d0e6c2fca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f427c7b-b8ff-5f7d-baf7-4d5e21fd9907","sourceKey":"bank:AMS101:M101-T6N-017","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a teaching hospital in Ibadan have become increasingly dissatisfied with their jobs, and management sees that something must change. This force for change is:","options":["Internal, changes in the workforce","Internal, changes in employee attitudes","External, the marketplace","External, labour markets"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Job dissatisfaction is the example given for changes in employee attitudes, an internal force. Option A is close, but changes in the workforce refer to its make-up, such as age, education, gender and nationality, not how staff feel."}},{"itemId":"d3bfa27f-48f1-58fd-a806-be30f55c8ed2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8c6a8bd6-46e0-5dbb-91f1-992e84928c9f","sourceKey":"bank:AMS101:M101-T6N-018","parentItemId":null,"revision":1,"payload":{"prompt":"Over five years, a Lagos insurance firm's staff has become younger, better educated and more mixed in gender and nationality. This internal force for change is:","options":["Changes in the workforce","Changes in organizational strategy","Labour markets","Changes in employee attitudes"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Changes in the workforce refer to its make-up, such as age, education, gender and nationality. Option D is about how employees feel, such as job dissatisfaction, and Option C is an external force about the supply of workers in the wider economy."}},{"itemId":"09e8e482-3d70-5980-96e3-070968147ab8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6840cbdf-9178-5b3f-803d-e4a9326fdfcf","sourceKey":"bank:AMS101:M101-T6N-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a strength of an internal manager acting as a change agent?","options":["He or she brings an objective view that insiders lack","He or she is not tied to the organization's history and culture","He or she knows the organization and is more thoughtful because he or she must live with the results","He or she is free to push drastic change without living with the results"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"An internal manager knows the organization well and must live with the outcome, which makes him or her more thoughtful. Option A is the strength of an outside consultant, and Option D describes a risk with outsiders, not a strength of insiders."}},{"itemId":"8c8f9e5f-8add-5eb9-b3f4-56a30508086c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7814ba3f-2543-5415-b5ff-2cc18ecb5a9e","sourceKey":"bank:AMS101:M101-T6N-020","parentItemId":null,"revision":1,"payload":{"prompt":"A major weakness of an outside consultant acting as a change agent is that he or she:","options":["Lacks an objective view of the organization","May be overcautious","Must live with the results of the change","Knows little of the organization's history, culture, procedures and people"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"An outsider usually knows little of the organization's history, culture, procedures and people. Option B is the weakness of an internal manager, and Option A is wrong because objectivity is actually the outsider's main strength."}},{"itemId":"98286f8d-fa8b-5b87-b1b4-42a629332e32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"43d57fa8-a55d-5912-a175-b87a1e03cfa4","sourceKey":"bank:AMS101:M101-T6N-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about change agents is correct?","options":["Outside consultants may push more drastic change because they do not live with the results","Internal managers bring an objective view that outsiders lack","Outside consultants tend to be more cautious than internal managers","Internal managers usually know little of the organization's culture"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Because an outside consultant does not have to live with the outcome, he or she may push more drastic change. Option C is the classic trap, since it is insiders who tend to be more cautious, and Option B reverses the roles, because objectivity belongs to outsiders."}},{"itemId":"0f6f5d22-a7a7-5a9e-9075-81cd23428126","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2e1cde4c-b07c-5817-ab3c-a646ed12ee27","sourceKey":"bank:AMS101:M101-T6N-022","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with an outside consultant, an internal manager acting as a change agent is more likely to be:","options":["Drastic in the changes made","Unaware of the organization's procedures","Overcautious","Objective"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"An internal manager must live with the results, so he or she may be overcautious. Option D and Option A describe outside consultants, who bring objectivity but may push more drastic change, and Option B is also a weakness of outsiders."}},{"itemId":"04abcb7d-5f40-578a-b38d-8ce6c9c6b9b0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f1fa9979-3289-526a-8681-83000549a47d","sourceKey":"bank:AMS101:M101-T6N-023","parentItemId":null,"revision":1,"payload":{"prompt":"Change agents can come from which of the following groups?","options":["Top managers only","Outside consultants only","Members of the human resources department only","Managers, nonmanagers such as HR change specialists, or outside consultants"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Change agents can be managers, nonmanagers such as a change specialist from HR, or outside consultants. Options A, B and C each wrongly limit the role to just one group."}},{"itemId":"41b08c7b-7787-5da9-b2a1-380cb35cc760","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c3c81d07-8608-583c-93f4-d80eedb3a369","sourceKey":"bank:AMS101:M101-T6N-024","parentItemId":null,"revision":1,"payload":{"prompt":"For large, organization-wide changes, organizations often turn to which change agents for advice and help?","options":["Shop-floor supervisors","Idea champions","Outside consultants","Employee assistance programme counsellors"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"For large, organization-wide changes, firms often hire outside consultants for advice and help. Option B, idea champions, push particular innovations, and Option D deals with employees' personal problems, not leading organization-wide change."}},{"itemId":"0e63dd6b-b0da-55f4-98a7-043064fb3a33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c73661f5-bf1d-58c9-bb5b-53a5d3882114","sourceKey":"bank:AMS101:M101-T6N-025","parentItemId":null,"revision":1,"payload":{"prompt":"The main strength an outside consultant brings as a change agent is:","options":["Close friendships with long-serving staff","Greater caution because he or she must live with the results","Deep knowledge of the organization's history","An objective view that insiders lack"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"An outside consultant's key strength is objectivity, an outside view that insiders lack. Option C and Option B are strengths of an internal manager, who knows the organization and must live with the results."}},{"itemId":"8ab247c3-b4c6-5c9b-ab2f-3f39c71ec43d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"190e2700-f072-5a33-84f7-03174e54ee5e","sourceKey":"bank:AMS101:M101-T6N-026","parentItemId":null,"revision":1,"payload":{"prompt":"How many views (metaphors) of the change process are commonly described?","options":["Four","Three","Two","Five"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"There are two metaphors for the change process: the calm waters view and the white-water rapids view. Option B, three, is tempting because Lewin's model has three steps, but those are steps within one view."}},{"itemId":"aea293ae-ed17-5851-942e-c1324e87141f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"959ab3ea-9983-5047-8a58-3ca79a577257","sourceKey":"bank:AMS101:M101-T6N-027","parentItemId":null,"revision":1,"payload":{"prompt":"The calm waters metaphor pictures the organization as:","options":["A team rowing against a strong current with no end","A machine that must be redesigned every year","A small raft on a river of constant, rough rapids","A large ship crossing a calm sea that meets a storm now and then"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"In the calm waters view, the organization is like a large ship on a calm sea, with an occasional storm that breaks the normal routine. Option C is the picture used for the white-water rapids view, where change is constant."}},{"itemId":"2f82dc30-e76c-5ee9-95f5-c13778bc2766","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa186846-a19b-55a3-ab91-3488d15d5757","sourceKey":"bank:AMS101:M101-T6N-028","parentItemId":null,"revision":1,"payload":{"prompt":"The white-water rapids metaphor pictures the organization as:","options":["A small raft on a river of constant, rough rapids","A ship that is repaired once and then sails smoothly","A ship anchored safely in a harbour","A large ship crossing a calm sea that meets a storm now and then"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"In the white-water view, the organization is like a small raft on a river where the rough water never stops, so change is constant. Option D is the calm waters picture, where change is only an occasional storm."}},{"itemId":"1af40de2-1a27-57a7-97fb-103df811bf8e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"39485f29-9cc2-5755-860d-3e29bc4de3c8","sourceKey":"bank:AMS101:M101-T6N-029","parentItemId":null,"revision":1,"payload":{"prompt":"In the calm waters view of change, change is seen as:","options":["Constant uncertainty and adjustment","An occasional break in normal, stable life","A continual process that never settles","Natural and constant"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"The calm waters view treats change as an occasional disruption in an otherwise stable situation, managed once before things settle. Options A, C and D all describe the white-water rapids view, where change never stops."}},{"itemId":"b06eeb34-84ef-50eb-a0fd-cf3a7da6ae02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da6b6312-268f-5a26-9d09-40602973c0f8","sourceKey":"bank:AMS101:M101-T6N-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes managing change in the white-water rapids view?","options":["It is done once, after which things settle","It is needed only when an occasional storm disrupts stable life","It follows the steps of unfreezing, changing and refreezing","It is a continual process, because change is natural and constant"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"In the white-water view, change is natural and constant, so managing it is a continual process. Option A and Option B describe the calm waters view, and Option C is Lewin's model, which also belongs to calm waters."}},{"itemId":"61b17cb5-9dc8-57ac-9d14-bb29e2db4586","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c6f67a0-ecf7-59c1-a4b2-cc869bcb101c","sourceKey":"bank:AMS101:M101-T6N-031","parentItemId":null,"revision":1,"payload":{"prompt":"Lewin's three-step model of change belongs to which view of the change process?","options":["The calm waters view","The systems view of innovation","The organizational development view","The white-water rapids view"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Lewin's unfreeze-change-refreeze model fits the calm waters view, where change is a break in stable equilibrium. Option D is the classic trap: the white-water view sees change as constant, so there is no stable state to refreeze into."}},{"itemId":"b515c455-00c1-50a1-a142-132bb83424b1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"99852ce6-d458-5d95-98bb-6bb00ce755d4","sourceKey":"bank:AMS101:M101-T6N-032","parentItemId":null,"revision":1,"payload":{"prompt":"The three-step change process of unfreezing, changing and refreezing was proposed by:","options":["Henri Fayol","Abraham Maslow","Max Weber","Kurt Lewin"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Kurt Lewin described change as unfreezing the status quo, changing to a new state and refreezing. Option A, Fayol, is known for principles of management, and Option B, Maslow, for the hierarchy of needs, not a change model."}},{"itemId":"3b2a7ba1-61fc-5536-a1a7-d6b5391dc771","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a0b26192-83c9-58da-96e1-e92e867f355f","sourceKey":"bank:AMS101:M101-T6N-033","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in Lewin's change process is:","options":["Changing to a new state","Increasing the restraining forces","Refreezing to make the change permanent","Unfreezing the status quo"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Lewin's process starts by unfreezing the status quo, loosening the current equilibrium so change can happen. Option A, changing, is the middle step, a common trap, and Option B would actually make change harder."}},{"itemId":"d5f220bb-fae7-5ca1-bffa-aef941010203","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"413803ae-1fa7-5f48-a497-e2dab44756f6","sourceKey":"bank:AMS101:M101-T6N-034","parentItemId":null,"revision":1,"payload":{"prompt":"The second step in Lewin's three-step change process is:","options":["Changing to a new state","Unfreezing the status quo","Refreezing to make the change permanent","Balancing driving and restraining forces"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Changing to a new state is the middle step, after unfreezing and before refreezing. Option B is the first step, Option C is the last step, and Option D is how managers refreeze, so it belongs to the third step."}},{"itemId":"6591d346-7239-5d7a-9b54-ac4c6e6aa0ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f5c61c0-dfd6-5a05-9598-7e5ecc98a47f","sourceKey":"bank:AMS101:M101-T6N-035","parentItemId":null,"revision":1,"payload":{"prompt":"The final step in Lewin's change process, which makes the change permanent, is:","options":["Refreezing","Team building","Changing","Unfreezing"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Refreezing is the third step and stabilises the new situation so the change lasts. Option D is the first step and Option C the second, while Option B is an OD technique, not part of Lewin's model."}},{"itemId":"033c0f62-e36b-5661-809b-be6e8ada17e2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f0df57b3-ae0b-5634-8703-0df960733350","sourceKey":"bank:AMS101:M101-T6N-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows Lewin's change process?","options":["Refreezing, changing, unfreezing","Unfreezing, changing, refreezing","Unfreezing, refreezing, changing","Changing, unfreezing, refreezing"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Lewin's steps run unfreezing the status quo, changing to a new state, then refreezing to make the change permanent. Option D is the common error of placing changing first, when it is really the middle step."}},{"itemId":"ce4adc41-77bf-52a8-9dff-a8810f6b3977","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0b77914b-064e-581f-ade9-929c9fbc24e9","sourceKey":"bank:AMS101:M101-T6N-037","parentItemId":null,"revision":1,"payload":{"prompt":"How many steps are there in Lewin's model of the change process?","options":["Five","Two","Four","Three"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Lewin's model has three steps: unfreezing, changing and refreezing. Option B, two, is the number of change metaphors, not Lewin's steps."}},{"itemId":"454efcca-8f3b-5bdf-b2e2-d40c3bcd46f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"547632f4-2b69-58da-bf06-a43f5e6ba8e1","sourceKey":"bank:AMS101:M101-T6N-038","parentItemId":null,"revision":1,"payload":{"prompt":"In Lewin's model, the status quo is best described as:","options":["The final step of the change process","A force that pushes behaviour toward change","An equilibrium state","A period of constant change"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"The status quo is an equilibrium state, and moving away from it requires unfreezing. Option D describes the white-water view, and Option B confuses it with a driving force."}},{"itemId":"8149f298-8489-565f-ad54-3f1c4f23d1f5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cb5d3fb4-80b9-52f5-ad05-24613cf7a1b8","sourceKey":"bank:AMS101:M101-T6N-039","parentItemId":null,"revision":1,"payload":{"prompt":"Driving forces are forces that:","options":["Hold back movement away from the equilibrium","Push behaviour away from the status quo","Make a change permanent after it is introduced","Cause employees to return to old habits"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Driving forces push behaviour away from the status quo, toward change. Option A is the definition of restraining forces, which work in the opposite direction."}},{"itemId":"bb39412c-2dcb-5cfe-b26b-90827ca40fac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3e587db9-145f-5485-8f61-689dfafc0590","sourceKey":"bank:AMS101:M101-T6N-040","parentItemId":null,"revision":1,"payload":{"prompt":"Restraining forces are forces that:","options":["Push behaviour away from the status quo","Hold back movement away from the equilibrium","Encourage employees to accept change quickly","Stabilise a new situation after change"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Restraining forces hold back movement away from the equilibrium, so they resist change. Option A describes driving forces, and Option D describes the purpose of refreezing."}},{"itemId":"d3c2e369-eb1a-5230-9b8c-bb5d74f2f401","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"57664e61-d587-5ed9-87df-d5c042ff7983","sourceKey":"bank:AMS101:M101-T6N-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a way to unfreeze the status quo?","options":["Increasing the driving forces","Increasing the restraining forces","Decreasing the restraining forces","Combining an increase in driving forces with a decrease in restraining forces"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Restraining forces hold back change, so increasing them would keep the organization frozen. Unfreezing is done by increasing driving forces, decreasing restraining forces, or combining both, as in Option A, Option C and Option D."}},{"itemId":"e361010c-2114-50a9-ba33-b16072b2cc47","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d1814078-6050-5678-b3e1-853431019f65","sourceKey":"bank:AMS101:M101-T6N-042","parentItemId":null,"revision":1,"payload":{"prompt":"In how many ways can the status quo be unfrozen?","options":["Three","Five","Two","Four"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Unfreezing can be done in three ways: increase the driving forces, decrease the restraining forces, or combine both. Option C, two, misses the option of combining the first two approaches."}},{"itemId":"e58602c3-f788-5b2b-9946-3585883058d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06039a75-f2aa-5d54-885c-f4ca49d1616c","sourceKey":"bank:AMS101:M101-T6N-043","parentItemId":null,"revision":1,"payload":{"prompt":"The main purpose of refreezing is to:","options":["Increase the forces that push away from the status quo","Loosen the status quo so change can begin","Identify which employees are resisting the change","Stabilise the new situation so the change is not short-lived"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Refreezing stabilises the new situation; without it, the change is likely to be short-lived. Option B describes unfreezing, and Option A is one way to unfreeze, not to refreeze."}},{"itemId":"c468e8e3-d644-5775-b87d-3402eeec0ac0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fad50577-5d10-5a7a-b838-6ff216e1d41a","sourceKey":"bank:AMS101:M101-T6N-044","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Abuja introduced a new patient-record procedure, but within a few weeks most staff had gone back to the old way of working. Which step of Lewin's model was most likely not done well?","options":["Unfreezing","Survey feedback","Refreezing","Changing"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Refreezing stabilises a change, and without it employees may go back to the old way, which is exactly what happened. Option A is less likely because the staff did move to the new procedure for a while, and Option B is an OD technique, not a step in Lewin's model."}},{"itemId":"b46ac37a-835f-51bc-bbbb-94f39398ac12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b686bdb4-ba1e-5700-97b6-5fc66ae7a358","sourceKey":"bank:AMS101:M101-T6N-045","parentItemId":null,"revision":1,"payload":{"prompt":"How do managers refreeze a change?","options":["By hiring an outside consultant to push more drastic change","By balancing the driving and restraining forces again, for example by rewarding the new behaviour","By increasing the driving forces until the status quo breaks","By decreasing the restraining forces before the change begins"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Managers refreeze by balancing the driving and restraining forces again, for example by rewarding the new behaviour. Option C and Option D are ways of unfreezing, which happens at the start of change, not the end."}},{"itemId":"151590a2-d6c7-57f4-8e76-95fb94ec5c7c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9376b07-016e-5b77-93b8-b7024961bbbb","sourceKey":"bank:AMS101:M101-T6N-046","parentItemId":null,"revision":1,"payload":{"prompt":"Kurt Lewin's model treats change as:","options":["A natural and constant condition","A continuous flow of rough rapids","The final output of a creative process","A break in the organization's equilibrium"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Lewin saw change as a break in the organization's equilibrium, which fits the calm waters view. Option A and Option B describe the white-water rapids view, where change never stops."}},{"itemId":"f5fd9333-8b4f-5b68-9821-b58cb3b68172","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"527944ee-d8a7-5dc6-95ae-b4c26cec101e","sourceKey":"bank:AMS101:M101-T6N-047","parentItemId":null,"revision":1,"payload":{"prompt":"Imagine a course whose length, timetable and tests change without warning, so students must stay flexible and respond quickly. This illustrates which view of change?","options":["The systems view of innovation","Lewin's refreezing step","The calm waters view","The white-water rapids view"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Constant, unexpected changes that demand flexibility describe the white-water rapids view. Option C is wrong because in calm waters change is only an occasional break in stable life."}},{"itemId":"ebf8d4ea-d43d-5a9b-9529-2df04ada2005","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c95f6908-d859-51d2-9575-4c501c0ad9ea","sourceKey":"bank:AMS101:M101-T6N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which view of change best fits today's uncertain and dynamic environments?","options":["The calm waters view","The status quo view","The white-water rapids view","Lewin's three-step view"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Today's uncertain and dynamic environments match the white-water view, where change is constant. Option A and Option D are the same idea, since Lewin's model belongs to calm waters, which assumes long stable periods."}},{"itemId":"31e5784d-98b3-542e-a5c5-9af00efa0a40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06ef2151-63c4-5b2f-894f-08c696bdfe54","sourceKey":"bank:AMS101:M101-T6N-049","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational change is usually grouped into how many types?","options":["Three: structure, technology and people","Three: unfreezing, changing and refreezing","Four: structure, technology, people and finance","Two: planned and unplanned"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Change is grouped into three types: structure, technology and people. Option B lists the three steps of Lewin's model, not types of change."}},{"itemId":"3f2823cd-4bc6-5591-9073-bdcfa035f34f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"456ac97d-f289-5c4d-9d61-8af595dcfcd3","sourceKey":"bank:AMS101:M101-T6N-050","parentItemId":null,"revision":1,"payload":{"prompt":"Merging departments, widening spans of control and cutting management layers are examples of:","options":["Structural change","People change","Technological change","Organizational development"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"These actions change authority relationships, coordination and job design, so they are structural change. Option D is wrong because OD works on people's attitudes and relationships, not on the organization chart."}},{"itemId":"5ce55d1f-3437-51c6-bb15-b019c24de87c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d19aded-3631-5103-84d3-4628e1298d0f","sourceKey":"bank:AMS101:M101-T6N-051","parentItemId":null,"revision":1,"payload":{"prompt":"Automation, computerization and the introduction of new machines are examples of:","options":["People change","Structural change","Technological change","Intergroup development"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Changes to equipment, tools, work processes and methods are technological change. Option B is about authority relationships and job design, and Option A is about attitudes and behaviour."}},{"itemId":"b5f36691-a97f-5a21-afd5-d0f6da25e7f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"114a0cce-c9a1-5154-b5e8-faa3105b1713","sourceKey":"bank:AMS101:M101-T6N-052","parentItemId":null,"revision":1,"payload":{"prompt":"Training, team building and OD programmes are examples of which type of change?","options":["Technological change","People change","Calm waters change","Structural change"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Training, team building and OD programmes change attitudes, expectations, perceptions and behaviour, which is people change. Option D would involve the organization chart, and Option C is a view of the change process, not a type of change."}},{"itemId":"ce05aa35-ec20-5ae4-850b-d2e1682ea213","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c2452d88-785b-5659-a430-223eace3d2ff","sourceKey":"bank:AMS101:M101-T6N-053","parentItemId":null,"revision":1,"payload":{"prompt":"Automation is best described as:","options":["Structural change that removes layers of management","People change that trains staff to use new skills","Technological change that replaces certain tasks done by people with machines","A survey that measures employees' attitudes to new technology"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Automation is technological change in which machines take over certain tasks that people used to do. Option A is structural change, and Option B is people change, even if it involves technology training."}},{"itemId":"5e9a84f4-e800-5b55-8a08-892b181ede24","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"611e540c-b6c2-5b48-bd51-3e90749ca170","sourceKey":"bank:AMS101:M101-T6N-054","parentItemId":null,"revision":1,"payload":{"prompt":"People change focuses on changing employees':","options":["Spans of control and job design","Attitudes, expectations, perceptions and behaviour","Authority relationships and coordinating mechanisms","Equipment, tools and work methods"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"People change works on attitudes, expectations, perceptions and behaviour. Option D is the focus of technological change, while Option C and Option A are the focus of structural change."}},{"itemId":"36c8d8fe-39be-5cb0-bc42-c098acdaf0fa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d157f9cc-8573-5161-81e8-e3a060d0fa7b","sourceKey":"bank:AMS101:M101-T6N-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an element of structure that structural change works on?","options":["Employee attitudes and perceptions","Span of control","Formalization","Departmentalization"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Attitudes and perceptions are the target of people change, not structural change. Span of control, formalization and departmentalization (options B, C and D) are all elements of structure."}},{"itemId":"979d3cde-8a62-5221-b54b-4e3b596c74c3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83b0f0ef-5fe4-5733-845a-26fb06bed487","sourceKey":"bank:AMS101:M101-T6N-056","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank moves from a simple structure to a team-based structure, cuts two management layers and gives branch managers more decision-making authority. This is mainly:","options":["Technological change","Structural change","People change","Process consultation"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Changing the structural design, cutting layers and shifting centralization are all structural change. Option C is tempting because teams are involved, but the change here is to the design of the structure, not to attitudes, and Option D is an OD technique."}},{"itemId":"f11eff40-755c-5fbc-b040-8afa001826ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af4162e6-cce9-5b32-a347-c0875a98fc78","sourceKey":"bank:AMS101:M101-T6N-057","parentItemId":null,"revision":1,"payload":{"prompt":"A cement manufacturer in Ogun State installs a computerized production line that replaces several manual tasks. This is an example of:","options":["People change","Technological change","Structural change","Intergroup development"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Installing computerized equipment that takes over manual tasks is technological change, specifically automation. Option C would involve authority relationships or job design, and Option A would target attitudes and behaviour."}},{"itemId":"27204e65-2745-5d7b-8266-97bfb3172241","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a6b84aa7-6516-5e49-bf24-b877d87a38cb","sourceKey":"bank:AMS101:M101-T6N-058","parentItemId":null,"revision":1,"payload":{"prompt":"People change in organizations is usually carried out through:","options":["Automation","Organizational development","Widening spans of control","Refreezing the status quo"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"People change is usually done through organizational development, which targets attitudes and working relationships. Option A is technological change and Option C is structural change."}},{"itemId":"bd8f01d1-c05d-538c-93e2-c0ddd8b35e56","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db97653f-93a4-5782-8bf5-6147ae0e7bfd","sourceKey":"bank:AMS101:M101-T6N-059","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational development (OD) refers to:","options":["Technological change that replaces tasks done by people with machines","Changes in authority relationships, coordinating mechanisms and job design","The process of turning creative ideas into useful products","Techniques or programmes to change people and the nature and quality of interpersonal work relationships"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"OD is a set of techniques or programmes aimed at changing people and the quality of their working relationships. Option A is automation, Option B is structural change, and Option C is innovation."}},{"itemId":"64c52de1-98e3-5979-8170-22c006b05b66","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c0400489-4ca0-5683-aac5-498534b78130","sourceKey":"bank:AMS101:M101-T6N-060","parentItemId":null,"revision":1,"payload":{"prompt":"Techniques or programmes designed to change people and the nature and quality of interpersonal work relationships are known as:","options":["Co-optation","Structural change","Organizational development","Automation"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"This is the definition of organizational development (OD), the main tool for people change. Option B works on the organization chart, and Option A is a technique for reducing resistance, not a programme for improving relationships."}},{"itemId":"9de28fd4-8bff-5bac-b36d-5291c9f673d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0e546ef7-4b26-51f4-9534-b167faf2ceff","sourceKey":"bank:AMS101:M101-T6N-062","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the popular OD techniques?","options":["Intergroup development","Process consultation","Negotiation","Survey feedback"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Negotiation is a technique for reducing resistance to change, not an OD technique. Survey feedback, process consultation and intergroup development (options A, B and D) are three of the four OD techniques, along with team building."}},{"itemId":"e10ff672-c197-52e7-9801-ae28aaa9e329","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47a837c2-66a5-5c2b-a39b-afad3c087a6f","sourceKey":"bank:AMS101:M101-T6N-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the popular OD techniques?","options":["Automation","Team building","Employee selection","Coercion"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Team building is one of the four OD techniques. Option A is technological change, Option D is a way of reducing resistance, and Option C is a way of reducing stress."}},{"itemId":"1efe9202-eefe-5da7-b13f-04b3cc5dfe1c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bccded56-3f9b-568c-9597-6ec93723bd64","sourceKey":"bank:AMS101:M101-T6N-064","parentItemId":null,"revision":1,"payload":{"prompt":"Survey feedback as an OD technique involves:","options":["An outside consultant helping managers understand how interpersonal processes affect work","Activities that help a work group set goals and clarify each member's role","Changing the stereotypes that work groups hold about each other","Using a questionnaire to assess employees' attitudes and perceptions about the change, then using the results to spot and solve problems"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Survey feedback uses a questionnaire to measure how employees see the change and then uses the results to solve problems. Option A is process consultation, Option B is team building, and Option C is intergroup development."}},{"itemId":"744ccfb4-d055-5390-af5a-e783c8de130c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84df33d6-ba5e-5088-a4b2-8a6324fa9402","sourceKey":"bank:AMS101:M101-T6N-065","parentItemId":null,"revision":1,"payload":{"prompt":"Process consultation is an OD technique in which:","options":["An outside consultant helps managers understand how interpersonal processes affect the way work is done","Work groups change the attitudes and perceptions they hold about each other","A powerful group is offered something of value to accept a change","A questionnaire is used to measure employees' attitudes about a change"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"In process consultation, an outside consultant helps managers see how interpersonal processes affect the way work gets done. Option D is survey feedback, Option B is intergroup development, and Option C is negotiation, a resistance-reduction technique."}},{"itemId":"135d2159-c609-5f70-9c13-6171f2857872","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bcc638bb-7a63-5c69-bd4c-65aae9dd07fc","sourceKey":"bank:AMS101:M101-T6N-066","parentItemId":null,"revision":1,"payload":{"prompt":"Team building as an OD technique consists of:","options":["Activities that change the attitudes and stereotypes different work groups hold about each other","Merging small departments into larger teams","A questionnaire that assesses employees' attitudes toward a planned change","Activities that help work groups set goals, build good working relationships and clarify each member's role and responsibilities"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Team building helps a work group set goals, build good relationships and clarify each member's role. Option A describes intergroup development, which works between groups, and Option B is a structural change, not an OD technique."}},{"itemId":"798e1f04-15c3-5925-9fa8-8efd5a7fca94","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dc416c26-ab1e-5707-aaf6-743cfffe9d10","sourceKey":"bank:AMS101:M101-T6N-067","parentItemId":null,"revision":1,"payload":{"prompt":"An OD technique that changes the attitudes, stereotypes and perceptions that work groups hold about each other is called:","options":["Survey feedback","Process consultation","Team building","Intergroup development"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Intergroup development works on how groups see each other, changing attitudes, stereotypes and perceptions between them. Option C is tempting, but team building works within a single group rather than between groups."}},{"itemId":"b1f0861a-2c8e-5015-83bb-5e37a70095f2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"106ef83d-37b0-5b17-b923-d59b7e96efe3","sourceKey":"bank:AMS101:M101-T6N-068","parentItemId":null,"revision":1,"payload":{"prompt":"At a Lagos bank, the marketing and finance departments distrust each other and see each other badly. Which OD technique best fits this problem?","options":["Team building","Intergroup development","Survey feedback","Process consultation"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"The problem lies between two groups, so intergroup development, which changes how groups see each other, is the right fit. Option A is the most tempting, but team building works within one group, not between departments."}},{"itemId":"9f5ae41e-1030-58ff-8955-7491b8cbb0a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b3fa1c59-f59d-56f0-acb5-45c69539f39d","sourceKey":"bank:AMS101:M101-T6N-069","parentItemId":null,"revision":1,"payload":{"prompt":"A new project team at an Ota manufacturing firm is unsure who does what and has not agreed on its goals. Which OD technique should management use?","options":["Intergroup development","Survey feedback","Coercion","Team building"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Team building helps a group set goals and clarify each member's role and responsibilities, which is exactly this team's problem. Option A is for tension between different groups, and Option C is a resistance technique, not OD."}},{"itemId":"1f3300c0-605d-5eba-995c-df18803a4d74","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14f75b8c-8c3b-5a50-99e3-ba856a6217a3","sourceKey":"bank:AMS101:M101-T6N-070","parentItemId":null,"revision":1,"payload":{"prompt":"Before restructuring, a Nigerian telecom firm wants to find out how its staff feel about the planned change and uses a questionnaire to do so. This OD technique is:","options":["Survey feedback","Education and communication","Team building","Process consultation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Using a questionnaire to assess staff attitudes and then acting on the results is survey feedback. Option D uses an outside consultant to observe interpersonal processes, and Option B is a resistance technique based on explaining the change."}},{"itemId":"4fcaf53b-3dce-5101-bd48-cf4e3a16fd69","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"52ac5d01-2beb-5e0c-b4e6-3e736340d714","sourceKey":"bank:AMS101:M101-T6N-071","parentItemId":null,"revision":1,"payload":{"prompt":"A department head at a university cannot understand why staff meetings keep failing. An outsider sits in, observes and explains how the interpersonal processes are hurting the work. This is:","options":["Process consultation","Survey feedback","Participation","Intergroup development"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"An outside consultant helping a manager see how interpersonal processes affect work is process consultation. Option B relies on a questionnaire rather than observation, and Option C is a resistance technique where those affected join the decision."}},{"itemId":"e9f7c517-7760-51a2-b676-ef4cc3127553","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d4aa567d-4580-5556-a394-a8d80718709c","sourceKey":"bank:AMS101:M101-T6N-072","parentItemId":null,"revision":1,"payload":{"prompt":"What is the key difference between team building and intergroup development?","options":["Team building is used for powerful groups, while intergroup development is used for anxious employees","Team building uses questionnaires, while intergroup development uses outside consultants","Team building is structural change, while intergroup development is technological change","Team building works within one group, while intergroup development works between groups"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Team building looks within a single group, while intergroup development looks between groups, such as two departments that see each other badly. Option B confuses them with survey feedback and process consultation, and Option C is wrong because both are OD techniques for people change."}},{"itemId":"df1d31f0-3f5d-56b2-92f5-746826645260","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"42f4fc68-f646-54e5-82ee-061986649e43","sourceKey":"bank:AMS101:M101-T6N-073","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational development is the main tool for which type of change?","options":["Economic change","Structural change","People change","Technological change"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"OD is the main tool for people change because it focuses on attitudes and relationships. Option B works on the organization chart and Option D on machines and methods, which OD does not target."}},{"itemId":"1542af7c-cff0-5ca1-8d2d-fffc9c15a4d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a92194a1-b6a0-5f41-bca3-6494cd34b38a","sourceKey":"bank:AMS101:M101-T6N-074","parentItemId":null,"revision":1,"payload":{"prompt":"OD techniques focus mainly on:","options":["Organization charts and reporting lines","Machines and equipment","Prices and market share","Attitudes and relationships"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"OD focuses on attitudes and relationships, not machines or charts. Option B is the concern of technological change and Option A of structural change."}},{"itemId":"8bf52559-38c5-5fe7-96b0-74fd2eb05b9a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"900a716e-01bd-5541-904c-07afd59e4415","sourceKey":"bank:AMS101:M101-T6N-075","parentItemId":null,"revision":1,"payload":{"prompt":"How many main reasons why people resist change are commonly identified?","options":["Five","Six","Four","Three"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"There are four reasons: uncertainty, habit, concern over personal loss, and the belief that the change is not in the organization's best interest. Option B, six, is the number of techniques for reducing resistance, not the reasons for it."}},{"itemId":"821ed769-7fd8-5cf6-bec4-c0212fab5606","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a65c350b-aeec-5101-88e8-968914d62bd3","sourceKey":"bank:AMS101:M101-T6N-076","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the reasons people resist change?","options":["Uncertainty","Concern over personal loss","Habit","A high tolerance for ambiguity"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Tolerating ambiguity is a cultural variable that encourages innovation, so it would make people more open to change, not less. Uncertainty, habit and concern over personal loss (options A, B and C) are three of the four reasons for resistance."}},{"itemId":"98f8ecfa-9963-5531-85bf-d2a4bc5485e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a49e9000-48f0-56e4-b244-5acd7ce0a134","sourceKey":"bank:AMS101:M101-T6N-077","parentItemId":null,"revision":1,"payload":{"prompt":"Resistance to change caused by uncertainty arises because:","options":["People fear losing status, money or friendships","People sincerely believe the change will harm the organization","Change replaces the known with the unknown","People prefer routine"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Uncertainty means change swaps what people know for what they do not know, which makes them uneasy. Option D is habit, Option A is concern over personal loss, and Option B is the belief that the change is not in the organization's best interest."}},{"itemId":"836e6693-0074-5418-9790-ffe49436e90e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"93659581-f595-5c61-aaef-2ed539e9d0a3","sourceKey":"bank:AMS101:M101-T6N-078","parentItemId":null,"revision":1,"payload":{"prompt":"Clerks at a Lagos insurance office have filled out paper forms the same way for fifteen years and simply prefer to keep doing it that way. Their resistance to a new system is mainly due to:","options":["Uncertainty","Concern over personal loss","Habit","Belief that the change is not in the organization's best interest"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"A preference for familiar routine is resistance due to habit. Option A would apply if the clerks were worried about what the unknown new system would bring, and Option D would apply if they thought the system would hurt the firm."}},{"itemId":"8f3622ee-b0f8-5b0c-a2e4-6db19aea1a32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7cc01b47-e09f-5b94-b9b3-f36d2b378ad5","sourceKey":"bank:AMS101:M101-T6N-079","parentItemId":null,"revision":1,"payload":{"prompt":"After a merger is announced, a senior manager at a Nigerian bank resists because he fears losing his title, authority and some benefits. This resistance comes from:","options":["Uncertainty","Belief that the change is not in the organization's best interest","Habit","Concern over personal loss"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Fear of losing status, money, authority, friendships or benefits is concern over personal loss. Option A is tempting because a merger is uncertain, but this manager's worry is specifically about what he personally stands to lose."}},{"itemId":"1a3caf03-2c7f-5767-ad46-83943a250533","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"482bc9bd-8287-5bac-9f9f-68eb9d71a577","sourceKey":"bank:AMS101:M101-T6N-080","parentItemId":null,"revision":1,"payload":{"prompt":"A quality supervisor at a food processing plant in Ota sincerely thinks a new production method will lower product quality, so she resists it. Her reason for resisting is:","options":["Habit","Concern over personal loss","Uncertainty","Belief that the change is not in the organization's best interest"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"When a worker genuinely thinks a change will harm the organization, the resistance comes from the belief that the change is not in the organization's best interest. Option B would involve fear for her own status or pay, which is not her concern here."}},{"itemId":"2a4a5dce-2fd3-51d5-a418-2c619766f4b8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e9dbcdcd-1b88-59d1-860e-41e9b6688e1b","sourceKey":"bank:AMS101:M101-T6N-081","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a state hospital are nervous about a planned restructuring because nobody knows what their new roles and routines will look like. Their resistance is mainly due to:","options":["Concern over personal loss","Uncertainty","Belief that the change is not in the organization's best interest","Habit"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Not knowing what the change will bring means the known is being replaced by the unknown, which is resistance from uncertainty. Option D would mean they simply prefer their routine, and Option A would mean they fear losing something specific like status or pay."}},{"itemId":"a679c306-ff61-58f7-94f2-000afa9c06b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98ca0dac-fac1-56a8-9315-a39d14037cab","sourceKey":"bank:AMS101:M101-T6N-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which employees tend to resist change the most?","options":["Those who have a lot invested in the current system, such as long-serving staff","Outside consultants brought in to manage the change","Newly hired staff with no attachment to the current system","Employees who have nothing to lose from the change"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"People with a lot invested in the current system resist more because they have more to lose, which is often true of older or long-serving staff. Option C and Option D describe people with little at stake, who would resist less."}},{"itemId":"6701c471-ace6-52d4-8c6f-4186230b85a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7d258376-5a7b-56b7-af23-a302ad5be49c","sourceKey":"bank:AMS101:M101-T6N-083","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about resistance to change is correct?","options":["Resistance can give stability and predictability and lead to useful debate, but it slows adaptation","Resistance is always harmful and should be removed by force","Resistance only comes from employees who are poorly trained","Resistance speeds up adaptation and progress"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Resistance is not always bad: it can bring stability, predictability and useful debate about whether a change is wise, though it slows adaptation and progress. Option B ignores these benefits, and Option D reverses the downside of resistance."}},{"itemId":"5e7acc65-fce9-5dbb-9117-4f172739c940","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c050c42b-9aea-5783-8c0f-b5c0c41152bc","sourceKey":"bank:AMS101:M101-T6N-084","parentItemId":null,"revision":1,"payload":{"prompt":"How many techniques for reducing resistance to change are commonly identified?","options":["Four","Three","Five","Six"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"There are six techniques: education and communication, participation, facilitation and support, negotiation, manipulation and co-optation, and coercion. Option A, four, is the number of reasons for resistance and also the number of OD techniques."}},{"itemId":"469fc8ff-93d3-5513-9c30-45c980caa7c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7a711ed2-8bbc-59a9-8e14-b897506b8a43","sourceKey":"bank:AMS101:M101-T6N-085","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the techniques for reducing resistance to change?","options":["Negotiation","Survey feedback","Facilitation and support","Participation"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Survey feedback is an OD technique for assessing attitudes, not one of the six techniques for reducing resistance. Participation, negotiation and facilitation and support (options A, C and D) are all on that list."}},{"itemId":"5ac3e319-d6cd-537d-b4b6-4e02ec15230a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6de8aa27-82f9-5d99-ae08-26c646c04ba2","sourceKey":"bank:AMS101:M101-T6N-086","parentItemId":null,"revision":1,"payload":{"prompt":"Education and communication is the best technique for reducing resistance when:","options":["Resistance comes from a powerful group","Resisters have the expertise to contribute","Resisters are fearful and anxious","Resistance comes from misinformation"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Education and communication clears up misunderstandings, so it suits resistance caused by misinformation. Option B calls for participation, Option C for facilitation and support, and Option A for negotiation."}},{"itemId":"0fdbdd12-eac0-55e1-8126-b361905bb54d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f3420e73-2da6-5c49-8f82-aefd397a1b20","sourceKey":"bank:AMS101:M101-T6N-087","parentItemId":null,"revision":1,"payload":{"prompt":"Participation is the most appropriate technique for reducing resistance when:","options":["Resisters have the expertise to make a contribution","A powerful group's support is needed","Resistance comes from misinformation","Resisters are fearful and anxious"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Participation brings those affected into the decision, which makes sense when they have expertise to contribute. Option C is the case for education and communication, and Option B is the case for manipulation and co-optation or coercion."}},{"itemId":"7c116d3f-9223-5f27-8673-988e366646d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8e8613a-f16b-501c-840d-0e55b0cd3a34","sourceKey":"bank:AMS101:M101-T6N-088","parentItemId":null,"revision":1,"payload":{"prompt":"Facilitation and support is best used when resisters are:","options":["Misinformed","A powerful group","Fearful and anxious","Experts who can contribute"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Facilitation and support, such as counselling and skills training, helps people who are fearful and anxious make needed adjustments. Option A calls for education and communication, Option D for participation, and Option B for negotiation, manipulation or coercion."}},{"itemId":"3ca60ed4-8a60-55d2-8e44-6abbdc475cff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c3f5a944-3441-56d3-8ac8-6404dbb42820","sourceKey":"bank:AMS101:M101-T6N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Negotiation is the technique to use when resistance to change:","options":["Comes from misinformation","Comes from fearful and anxious employees","Comes from a powerful group","Comes from people with useful expertise"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Negotiation is used when resistance comes from a powerful group, because something of value can \"buy\" their commitment. Option A calls for education and communication, Option B for facilitation and support, and Option D for participation."}},{"itemId":"f297f147-1d64-5cbd-a668-385d6836cf9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dcb728c9-a698-537e-8a99-d3317c8bee0c","sourceKey":"bank:AMS101:M101-T6N-090","parentItemId":null,"revision":1,"payload":{"prompt":"Which three techniques for reducing resistance all involve a powerful group?","options":["Education and communication, negotiation, and manipulation and co-optation","Negotiation, manipulation and co-optation, and coercion","Participation, negotiation, and coercion","Education and communication, participation, and facilitation and support"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Negotiation, manipulation and co-optation, and coercion are all linked to a powerful group. Each of the other options includes participation or education and communication, which are used for resisters with expertise and for misinformation, not for powerful groups."}},{"itemId":"4ede54cd-1428-5087-9e3f-488e7c37cd9b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83b836c9-937c-5a05-ba2c-e022614969b9","sourceKey":"bank:AMS101:M101-T6N-091","parentItemId":null,"revision":1,"payload":{"prompt":"A drawback of education and communication as a way to reduce resistance is that it:","options":["May be illegal","Can be expensive and has no guarantee of success","May not work when trust and credibility are lacking","Opens the door for others to demand deals"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Education and communication depends on people believing the message, so it may fail when trust and credibility are missing. Option B is the drawback of facilitation and support, Option A of coercion, and Option D of negotiation."}},{"itemId":"e540023c-b5eb-5b2a-9dc2-fe2a18a9c5ac","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee678b7b-63e3-5e75-9f31-5244f1b7460a","sourceKey":"bank:AMS101:M101-T6N-092","parentItemId":null,"revision":1,"payload":{"prompt":"The main drawbacks of participation as a technique for reducing resistance are that it:","options":["Can be costly and invites others to demand deals","Can backfire and damage the change agent's credibility","Takes time and may produce a poor solution","May be illegal"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Involving people in the decision takes time, and the group may arrive at a poor solution. Option B is the drawback of manipulation and co-optation, and Option A is the drawback of negotiation."}},{"itemId":"63225228-d97d-568c-abfb-702d6de4025c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b97769d4-c6c9-527d-aa05-84d3aec6f6cf","sourceKey":"bank:AMS101:M101-T6N-093","parentItemId":null,"revision":1,"payload":{"prompt":"A drawback of facilitation and support as a technique for reducing resistance is that it:","options":["Can be expensive and has no guarantee of success","Takes time and may produce a poor solution","May not work when trust is lacking","May be illegal"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Counselling, training and paid leave cost money, and there is no guarantee they will work. Option B is the drawback of participation, Option C of education and communication, and Option D of coercion."}},{"itemId":"afb1b6d3-e9e1-5915-b5b7-3cf9d896b99b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ddaef55-0bd0-587f-be8c-7c0c2ade9d65","sourceKey":"bank:AMS101:M101-T6N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Negotiation as a technique for reducing resistance has which drawback?","options":["It can be costly and opens the door for others to demand deals","It takes time and may produce a poor solution","It may not work when trust and credibility are lacking","It may be illegal"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Buying commitment through negotiation can be costly, and once one group gets a deal, others may demand one too. Option D is the drawback of coercion, Option C of education and communication, and Option B of participation."}},{"itemId":"5cd2b781-3246-522f-b3fb-c4dddd5ed7ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78779db6-a4c9-5f62-a6bc-d3706eeb4b17","sourceKey":"bank:AMS101:M101-T6N-095","parentItemId":null,"revision":1,"payload":{"prompt":"Which drawback is specifically associated with coercion?","options":["It can be expensive with no guarantee of success","It takes time and may produce a poor solution","It may not work when trust is lacking","It may be illegal and may undermine the change agent's credibility"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Coercion uses threats or force, so it may be illegal and can damage the change agent's credibility. Option B is the drawback of participation, Option A of facilitation and support, and Option C of education and communication."}},{"itemId":"a5757c67-79c9-5159-af89-4a359456042b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c8200baf-b1e3-523d-a2aa-ef5dcdb34e27","sourceKey":"bank:AMS101:M101-T6N-096","parentItemId":null,"revision":1,"payload":{"prompt":"A drawback of manipulation and co-optation is that it:","options":["May not work when trust and credibility are lacking","Can backfire, and the change agent may lose credibility","Takes time and may produce a poor solution","Can be expensive with no guarantee of success"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Manipulation and co-optation rely on covert influence, so if people find out, it can backfire and the change agent may lose credibility. Option C is the drawback of participation, Option D of facilitation and support, and Option A of education and communication."}},{"itemId":"cf50f663-fba5-5494-89f5-f5b682b83266","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"50b95ca6-537f-54a2-8899-b4f8268d42d8","sourceKey":"bank:AMS101:M101-T6N-097","parentItemId":null,"revision":1,"payload":{"prompt":"Which advantage is shared by manipulation and co-optation and by coercion?","options":["They help people make needed adjustments","They clear up misunderstandings","They are a cheap and easy way to gain support","They raise involvement and acceptance"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Both manipulation and co-optation and coercion are a cheap and easy way to win a powerful group's support. Option B is the advantage of education and communication, Option D of participation, and Option A of facilitation and support."}},{"itemId":"bbb5578d-dddd-58e9-920c-282de54f3ed6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6722f11f-b020-5fa7-9f5a-2b854510e4e2","sourceKey":"bank:AMS101:M101-T6N-098","parentItemId":null,"revision":1,"payload":{"prompt":"The main advantage of participation as a way to reduce resistance is that it:","options":["Raises involvement and acceptance","Is a cheap and easy way to gain support","Can buy the commitment of a powerful group","Clears up misunderstandings"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Bringing people into the decision raises their involvement and acceptance of the change. Option D is the advantage of education and communication, Option C of negotiation, and Option B of manipulation and co-optation or coercion."}},{"itemId":"78a629b1-c881-5afe-bb00-1131e5c8108e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5385f827-e1dc-511d-ab0e-cbfbbf3a6bcc","sourceKey":"bank:AMS101:M101-T6N-099","parentItemId":null,"revision":1,"payload":{"prompt":"Co-optation as a technique for reducing resistance means:","options":["Using direct threats such as transfer or loss of promotion","Explaining the reasons for the change through meetings and memos","Exchanging something of value, such as a special pay package","\"Buying off\" resistance leaders by giving them a key role in the change decision"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Co-optation mixes manipulation and participation by giving resistance leaders a key role in the decision to win them over. Option A is coercion, Option C is negotiation, and Option B is education and communication."}},{"itemId":"0f3bbc70-aadb-5301-b12b-248e32481d72","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3897bc55-1de8-5d0f-9962-8142a746ec58","sourceKey":"bank:AMS101:M101-T6N-100","parentItemId":null,"revision":1,"payload":{"prompt":"Co-optation is best described as a combination of:","options":["Education and facilitation","Negotiation and coercion","Manipulation and participation","Participation and negotiation"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Co-optation is a mix of manipulation and participation: leaders are given a role in the decision, but mainly to buy off their resistance. Option D is tempting because co-optation involves a role in the decision, but it does not exchange something of value as negotiation does."}},{"itemId":"e4d30266-762d-5469-8068-bba1f2edc64a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06feee33-da4a-5307-9cb4-030412a86172","sourceKey":"bank:AMS101:M101-T6N-101","parentItemId":null,"revision":1,"payload":{"prompt":"Manipulation as a technique for reducing resistance refers to:","options":["Bringing those affected by the change into the decision","Offering counselling and new-skills training","Direct threats or force, such as threats of transfer","Covert attempts to influence, such as twisting facts or holding back bad information"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Manipulation is covert influence, such as twisting facts or withholding bad news. Option C is coercion, which is open and direct, Option A is participation, and Option B is facilitation and support."}},{"itemId":"ba1cabcf-f98c-5678-9316-943c36ce4e0f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e9f010df-d940-591f-a578-aed83ad1ef85","sourceKey":"bank:AMS101:M101-T6N-102","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm in Ota tells resisting staff that they will be transferred to a remote plant or get poor performance reviews unless they accept the new shift system. The firm is using:","options":["Coercion","Facilitation and support","Manipulation","Negotiation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Direct threats such as transfer, loss of promotion or bad performance reviews are coercion. Option C is tempting, but manipulation is covert, such as twisting facts, while these threats are open and direct."}},{"itemId":"2c9e1f85-6a9c-5124-a846-e6860e089728","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c436f1dd-c948-5318-9cee-9ee077f41997","sourceKey":"bank:AMS101:M101-T6N-103","parentItemId":null,"revision":1,"payload":{"prompt":"To win the support of a powerful staff union for a new branch network, a Lagos bank offers union members a special pay package. This technique is:","options":["Co-optation","Negotiation","Participation","Coercion"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Exchanging something of value, such as a special pay package, to reduce resistance is negotiation. Option A would mean giving the union's leaders a key role in the decision, not a pay deal."}},{"itemId":"addaa508-5f46-59d8-bc04-4e485d1882c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4214dd9-c944-5e30-aed2-9cf5461bcd9a","sourceKey":"bank:AMS101:M101-T6N-104","parentItemId":null,"revision":1,"payload":{"prompt":"Nurses at a Lagos hospital are anxious about a new electronic records system, so management provides counselling, new-skills training and a short paid leave. This technique is:","options":["Participation","Education and communication","Facilitation and support","Negotiation"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Counselling, therapy, skills training and short paid leave are forms of facilitation and support, used when resisters are fearful and anxious. Option B would mainly involve explaining the reasons for the change to correct misinformation."}},{"itemId":"8f836c38-55fa-559a-8a2e-cc0802b8dbc8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4da95630-59cc-5e9c-a4e2-919652d2fd87","sourceKey":"bank:AMS101:M101-T6N-105","parentItemId":null,"revision":1,"payload":{"prompt":"False rumours spread at a cement plant that a new process will lead to mass sackings. Management holds meetings and sends memos to explain the real reasons for the change. This is:","options":["Education and communication","Coercion","Facilitation and support","Manipulation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Explaining the reasons for a change through talks, memos and meetings to correct misinformation is education and communication. Option D is wrong because manipulation twists facts or hides bad news, while this management is sharing accurate information."}},{"itemId":"b1bf36d5-e6b6-5a81-a79e-151be8f07ec2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"804b28f7-471e-52d1-bb84-73d6bc0ab59b","sourceKey":"bank:AMS101:M101-T6N-106","parentItemId":null,"revision":1,"payload":{"prompt":"A university faculty plans a new curriculum and invites experienced lecturers, who know the subject well, to help design it. This approach to reducing resistance is:","options":["Participation","Education and communication","Co-optation","Negotiation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Bringing those affected into the decision, especially when they have expertise to contribute, is participation. Option C is tempting, but co-optation gives resistance leaders a role mainly to buy off their opposition, not to use their expertise."}},{"itemId":"cec578b2-a45e-522e-b832-1eef5ba01f52","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3f6d3b42-6011-515a-a680-636d09be2473","sourceKey":"bank:AMS101:M101-T6N-107","parentItemId":null,"revision":1,"payload":{"prompt":"A telecom firm in Lagos gives the most vocal opponent of a restructuring a seat on the planning committee, mainly so that he will stop opposing it. This is an example of:","options":["Co-optation","Negotiation","Process consultation","Participation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Giving a resistance leader a key role in the decision to buy off his opposition is co-optation. Option D is tempting because he joins the decision, but here the aim is to silence opposition rather than use expertise."}},{"itemId":"0a89d8a4-bfc2-5aaa-b194-3fb4f890d89b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"639bc8f4-3b81-5a9f-9d77-d00b2b96b17e","sourceKey":"bank:AMS101:M101-T6N-108","parentItemId":null,"revision":1,"payload":{"prompt":"Change often creates which reaction in employees?","options":["Refreezing","Creativity","Intergroup development","Stress"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Change often creates stress for employees, which is why managers must manage both. Option B is the ability to combine ideas, and Option A and Option C are things managers do, not employee reactions."}},{"itemId":"cda682e7-6788-56e5-8857-f342b4fc6fe7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8504ffdb-6b59-534d-8abd-8e65a886c2ca","sourceKey":"bank:AMS101:M101-T6N-109","parentItemId":null,"revision":1,"payload":{"prompt":"Stress is best defined as:","options":["Barriers that keep people from doing what they desire","A chronic sense of time urgency and an excessive competitive drive","The loss of something desired","The adverse reaction people have to excessive pressure placed on them from extraordinary demands, constraints or opportunities"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Stress is the adverse reaction to excessive pressure from extraordinary demands, constraints or opportunities. Option A defines constraints and Option C defines demands, which are sources of pressure rather than stress itself, and Option B describes a Type A personality."}},{"itemId":"c38da67b-837d-5cd8-9227-d8383c3c54fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c817f101-1d3c-5461-ab94-e570c4b4c606","sourceKey":"bank:AMS101:M101-T6N-110","parentItemId":null,"revision":1,"payload":{"prompt":"The adverse reaction people have to excessive pressure placed on them from extraordinary demands, constraints or opportunities is called:","options":["Stress","Role conflict","Resistance to change","Uncertainty"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"This is the definition of stress. Option C is opposition to a change, and Option B is one specific cause of stress, where expectations are hard to meet at the same time."}},{"itemId":"fadfacbf-5e39-56dd-9002-d69890c5260c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a9d2318-b6ee-575a-8d07-af3f7f575471","sourceKey":"bank:AMS101:M101-T6N-111","parentItemId":null,"revision":1,"payload":{"prompt":"In the study of stress, constraints are:","options":["Barriers that keep us from doing what we desire","Pressure from co-workers","The loss of something desired","Expectations that are hard to meet at the same time"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Constraints are barriers that stop us from doing what we desire. Option C is the definition of demands, Option D is role conflict, and Option B is interpersonal demands."}},{"itemId":"330cb10f-f7c6-5030-bfa6-b93f8e8d268c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dfcfc39b-b0d4-5092-8d9d-c86c4b12be85","sourceKey":"bank:AMS101:M101-T6N-112","parentItemId":null,"revision":1,"payload":{"prompt":"In the study of stress, demands are defined as:","options":["Barriers that keep us from doing what we desire","The loss of something desired","Unclear expectations about what to do","More being expected than time allows"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Demands are defined as the loss of something desired. Option A is the definition of constraints, Option D is role overload, and Option C is role ambiguity."}},{"itemId":"3e37116c-ed95-5898-8e7e-9cfb82491a02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc069a81-ec83-5e3d-8ec3-3ae4f6f6fa5f","sourceKey":"bank:AMS101:M101-T6N-113","parentItemId":null,"revision":1,"payload":{"prompt":"Stress symptoms are grouped into which three categories?","options":["Task, role and interpersonal","Organizational, personal and economic","Structural, cultural and human resource","Physical, psychological and behavioural"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Stress symptoms are physical, psychological or behavioural. Option B mixes up the causes of stress, Option C lists the variables that foster innovation, and Option A lists some job-related stressors."}},{"itemId":"acd4f554-94f3-58ad-ba6b-6cfe9348b3b8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0017f0c9-06d1-503e-ab7f-3806f01f9c89","sourceKey":"bank:AMS101:M101-T6N-114","parentItemId":null,"revision":1,"payload":{"prompt":"Headaches, higher blood pressure and faster heart and breathing rates are which type of stress symptom?","options":["Behavioural","Physical","Psychological","Interpersonal"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Changes in metabolism, heart rate, breathing and blood pressure, plus headaches, are physical symptoms. Option C covers feelings like anxiety and boredom, and Option A covers actions like absenteeism and smoking."}},{"itemId":"c9568d92-583b-5d43-a4e9-b9f770358c08","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"045410a1-7241-5f05-8cde-46c43ccebe01","sourceKey":"bank:AMS101:M101-T6N-115","parentItemId":null,"revision":1,"payload":{"prompt":"Job dissatisfaction, tension, irritability, boredom and procrastination are which type of stress symptom?","options":["Physical","Behavioural","Structural","Psychological"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"These are psychological symptoms, which affect a person's mental and emotional state. Option B, behavioural, covers observable actions such as absenteeism, turnover and changes in eating or smoking."}},{"itemId":"26778c34-2fe6-5ef7-9a34-7dc0b5d71c6d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1087e035-0394-5490-a12c-c422ba9b7de9","sourceKey":"bank:AMS101:M101-T6N-116","parentItemId":null,"revision":1,"payload":{"prompt":"Increased absenteeism, higher turnover and more smoking or drinking are which type of stress symptom?","options":["Psychological","Organizational","Physical","Behavioural"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Absenteeism, turnover and changes in smoking or drinking are actions, so they are behavioural symptoms. Option A covers feelings like tension and anxiety, and Option B is a group of causes of stress, not a symptom type."}},{"itemId":"b9f55cae-44b7-5931-a4ae-94a561421f76","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa952461-024d-5c04-9cec-1392c95d07e1","sourceKey":"bank:AMS101:M101-T6N-117","parentItemId":null,"revision":1,"payload":{"prompt":"During month-end at a Lagos bank, a teller starts fidgeting, speaking rapidly and having trouble sleeping. These are mainly:","options":["Behavioural symptoms of stress","Physical symptoms of stress","Psychological symptoms of stress","Personal causes of stress"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Rapid speech, fidgeting and sleep problems are listed as behavioural symptoms. Option B is tempting, but physical symptoms are bodily changes such as blood pressure and heart rate, and Option D describes causes rather than symptoms."}},{"itemId":"06ecd5bb-90cd-5494-bbd2-d306903128f5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cbdb7752-c5e7-5662-a5f1-8d2451c08bdf","sourceKey":"bank:AMS101:M101-T6N-118","parentItemId":null,"revision":1,"payload":{"prompt":"The causes of stress (stressors) fall into how many broad groups?","options":["Three: physical, psychological and behavioural","Three: structural, cultural and human resource","Two: organizational factors and personal factors","Two: constraints and opportunities"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Stressors fall into two groups: organizational (job-related) factors and personal factors. Option A lists the types of stress symptoms, not the causes, and Option B lists the variables that foster innovation."}},{"itemId":"6829f186-1444-589d-b955-8c90a3876d14","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bcac3b01-dc6e-5285-bd3e-f08c3e99c2ef","sourceKey":"bank:AMS101:M101-T6N-119","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an organizational (job-related) cause of stress?","options":["Personality type","Role demands","Organizational leadership","Task demands"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Personality type is a personal factor, together with family issues and personal economic problems. Role demands, task demands and organizational leadership (options B, C and D) are all job-related stressors."}},{"itemId":"ad3814ca-79d6-566d-96eb-2da448458612","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"15d3fbfb-4b60-556d-91ca-3d459e2b74a8","sourceKey":"bank:AMS101:M101-T6N-120","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a personal factor that causes stress?","options":["Interpersonal demands","Personality type","Family issues","Personal economic problems"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Interpersonal demands, pressure from co-workers, are an organizational (job-related) factor. Family issues, personal economic problems and personality type (options B, C and D) are the three personal factors."}},{"itemId":"ad65fbbb-6d92-59c6-a9f5-86c32233a04d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"97aeece9-ef9d-5247-abe8-3b2862ef2142","sourceKey":"bank:AMS101:M101-T6N-121","parentItemId":null,"revision":1,"payload":{"prompt":"As a cause of stress, task demands relate to:","options":["A management style that creates fear and anxiety","Pressure from co-workers","The job itself, including its design, working conditions and layout","Pressure from the role a person plays"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Task demands come from the job itself: its design, working conditions and physical layout. Option D is role demands, Option B is interpersonal demands, and Option A is organizational leadership."}},{"itemId":"54d00e0b-6f13-57ff-bf28-e89c502b3a33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"00956b61-f3f6-53b7-ac2b-b665fca5902d","sourceKey":"bank:AMS101:M101-T6N-122","parentItemId":null,"revision":1,"payload":{"prompt":"Role conflict refers to:","options":["Expectations that are hard to meet at the same time","Poor support from co-workers","More being expected than time allows","Expectations that are unclear"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Role conflict happens when a person faces expectations that are hard to satisfy at the same time. Option C is role overload, Option D is role ambiguity, and Option B is interpersonal demands."}},{"itemId":"f1c0af86-a76c-55f2-9672-d16ea0521c4b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aff2a7ac-7341-5d36-9ba9-4beb9a6f9dcf","sourceKey":"bank:AMS101:M101-T6N-123","parentItemId":null,"revision":1,"payload":{"prompt":"Role overload occurs when:","options":["There are too many rules and little participation","More is expected of a person than time allows","Expectations are hard to meet at the same time","Expectations are unclear"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Role overload means more is expected than the available time permits. Option D is role ambiguity, Option C is role conflict, and Option A is the organization structure stressor."}},{"itemId":"d192f7c1-3c54-5614-8f3e-a5a846f71267","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4efd4f1e-1618-50ce-b839-c1ceaef58759","sourceKey":"bank:AMS101:M101-T6N-124","parentItemId":null,"revision":1,"payload":{"prompt":"Role ambiguity exists when:","options":["A manager uses fear to push performance","Expectations are hard to meet at the same time","Expectations are unclear and the person is not sure what to do","More is expected than time allows"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Role ambiguity means the person does not clearly understand what is expected of him or her. Option D is role overload and Option B is role conflict, the other two kinds of role demands."}},{"itemId":"e1aef902-5cee-5595-8083-687e2b96954b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3312a9fa-3af4-590e-a4ff-e5df2a9472b0","sourceKey":"bank:AMS101:M101-T6N-125","parentItemId":null,"revision":1,"payload":{"prompt":"A newly hired officer at a Lagos microfinance bank has no job description and is never told what her supervisor expects of her. The stressor she faces is:","options":["Task demands","Role overload","Role ambiguity","Role conflict"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Unclear expectations about what to do are role ambiguity. Option B would mean she has too much to do in the time available, and Option D would mean she faces expectations that clash with each other."}},{"itemId":"200752fe-efda-528b-b0aa-7c022a48fe6c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7113ba94-5697-504d-936a-c53188e39e99","sourceKey":"bank:AMS101:M101-T6N-126","parentItemId":null,"revision":1,"payload":{"prompt":"A junior doctor at a Lagos hospital is expected to handle far more patients and paperwork each shift than the shift's hours allow. This stressor is:","options":["Interpersonal demands","Role ambiguity","Role overload","Role conflict"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"When more is expected than time allows, the stressor is role overload. Option B would mean the doctor does not know what is expected, and Option D would mean expectations that are hard to meet together."}},{"itemId":"b3b95a11-69e3-533e-9723-23c78c0c009b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f36f6098-a3c5-5227-88d1-d6e2ea2129c0","sourceKey":"bank:AMS101:M101-T6N-127","parentItemId":null,"revision":1,"payload":{"prompt":"A sales manager in Ibadan is told by one director to cut costs sharply and by another to expand the sales team at the same time. This stressor is best described as:","options":["Role overload","Role ambiguity","Task demands","Role conflict"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Expectations that are hard to meet at the same time are role conflict. Option A would be about having too much to do in too little time, and Option B would be about unclear expectations, while here they are clear but clash."}},{"itemId":"fda7bc2a-f0a7-5039-a98b-3ff4c4c38391","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e16a3fec-b258-5617-86a5-3aaa5f2849cf","sourceKey":"bank:AMS101:M101-T6N-128","parentItemId":null,"revision":1,"payload":{"prompt":"As a job-related cause of stress, interpersonal demands are:","options":["Pressure from the role a person plays","Pressure from co-workers, such as poor support or bad relationships","Too many rules and too little chance to take part in decisions","The job's design, working conditions and layout"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Interpersonal demands come from co-workers, such as poor support or bad relationships. Option A is role demands, Option C is the organization structure stressor, and Option D is task demands."}},{"itemId":"235864d1-f05e-53cb-a9a6-ea0fee4d2741","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4985b607-1e98-518c-a3b9-cab7e2e96b0d","sourceKey":"bank:AMS101:M101-T6N-129","parentItemId":null,"revision":1,"payload":{"prompt":"Organization structure becomes a cause of stress when there are:","options":["Too many rules and too little chance to take part in decisions","Abundant resources and minimal time pressure","Too few rules and too much freedom","Clear goals with regular feedback"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Excessive rules and little opportunity to participate in decisions make structure a stressor. Option D describes setting clear goals with feedback, which actually reduces stress, and Option B describes conditions that foster innovation."}},{"itemId":"941564b9-8f8a-5a4b-b925-f9bf86448f80","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4613b978-1ba8-53be-8023-646ef4774f91","sourceKey":"bank:AMS101:M101-T6N-130","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational leadership becomes a cause of stress when:","options":["The job's working conditions and layout are poor","Co-workers give each other poor support","Management uses a style that creates tension, fear and anxiety, with unrealistic pressure to perform","An employee faces family and money problems"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Organizational leadership is a stressor when management's style creates tension, fear and anxiety and sets unrealistic pressure to perform. Option B is interpersonal demands, Option A is task demands, and Option D describes personal factors."}},{"itemId":"a01b2dae-9618-58c5-b746-081da0ccd6f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94cb9f56-2e52-5697-a410-334f008f3a50","sourceKey":"bank:AMS101:M101-T6N-131","parentItemId":null,"revision":1,"payload":{"prompt":"A Type A personality is characterised by:","options":["High self-confidence, persistence and energy in backing new ideas","A chronic sense of time urgency, an excessive competitive drive and difficulty enjoying leisure","A relaxed manner without time urgency or impatience","A preference for routine and dislike of change"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Type A people feel constant time urgency, are excessively competitive and find it hard to enjoy leisure. Option C describes Type B, and Option A describes the traits of an idea champion."}},{"itemId":"c20b115b-7096-528c-8084-5003b0550fd5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"820674bb-47af-597f-8dfc-d9b1124beaae","sourceKey":"bank:AMS101:M101-T6N-132","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with a Type A person, a Type B person is:","options":["More likely to feel hostility and anger","More competitive and hurried","Unable to enjoy leisure","Relaxed, without time urgency or impatience"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Type B people are relaxed and do not feel time urgency or impatience. Options A, B and C all describe Type A characteristics."}},{"itemId":"567343a5-1ac7-58a4-8b04-dab6abbdc049","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e3905031-70db-5d5f-bafb-13b831e4e750","sourceKey":"bank:AMS101:M101-T6N-133","parentItemId":null,"revision":1,"payload":{"prompt":"Research suggests that the harmful part of the Type A personality is:","options":["Hostility and anger","Role ambiguity","The sense of hurry itself","The ability to relax"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Research points to hostility and anger as the damaging part of Type A behaviour, not the hurry. Option C is the tempting trap, since time urgency is a Type A trait but not the harmful element."}},{"itemId":"f10655f1-0a2b-50e9-93d7-6bc60b09a091","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aabfac5d-0607-5c28-8200-01ef58bd921d","sourceKey":"bank:AMS101:M101-T6N-134","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about stress is correct?","options":["Stress is not always bad; it can bring opportunity, and it becomes a problem when it is excessive","Stress is always harmful and should be removed completely","Stress shows only as physical symptoms","Stress comes only from personal factors, never from the job"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Stress can bring opportunity, like the push an athlete feels before a big event, and becomes a problem only when it is excessive. Option D ignores job-related causes, and Option C ignores psychological and behavioural symptoms."}},{"itemId":"633afa2e-f3ec-5ed5-bf93-7cdaec84ae2e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3dee560f-6be7-56d7-adab-08b058404dc8","sourceKey":"bank:AMS101:M101-T6N-135","parentItemId":null,"revision":1,"payload":{"prompt":"Setting clear goals with feedback, for example through MBO, helps reduce stress mainly by reducing:","options":["Abundant resources","Role ambiguity","Personal economic problems","Personality type"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Clear goals and feedback tell employees what is expected, which reduces role ambiguity. Option C and Option A are personal factors that goal-setting does not address."}},{"itemId":"8717d3ef-030f-57bf-8f85-c2f04f6281eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba4382a9-c031-5765-b728-de2a8dad5efc","sourceKey":"bank:AMS101:M101-T6N-136","parentItemId":null,"revision":1,"payload":{"prompt":"A realistic job preview, as a way to reduce stress, is given during:","options":["Refreezing","Team building","Employee selection","Intergroup development"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"A realistic job preview is given during selection so applicants know what the job really involves before they accept it. Option A is a step in Lewin's change model, and Option B and Option D are OD techniques."}},{"itemId":"49aee588-6b88-53c8-8c7e-02f1b5a89225","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c7100e23-20fc-5f9a-a988-32241839ee33","sourceKey":"bank:AMS101:M101-T6N-137","parentItemId":null,"revision":1,"payload":{"prompt":"Employee assistance programmes (EAPs) help reduce stress by:","options":["Widening managers' spans of control","Offering help such as counselling for employees' personal problems","Replacing tasks done by people with machines","Increasing the driving forces for change"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"EAPs give employees help such as counselling for personal problems, along with time-management training. Option C is automation and Option A is structural change, neither of which targets stress directly."}},{"itemId":"2262738d-fe45-5d70-9769-5575fd34cea2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"658ee33b-f164-53f9-9159-d398c1441536","sourceKey":"bank:AMS101:M101-T6N-138","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a way for managers to reduce employee stress?","options":["Redesigning jobs to give more autonomy and feedback","Raising performance targets suddenly with unrealistic pressure to perform","Improving communication during change","Running wellness programmes"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Unrealistic pressure to perform is part of the organizational leadership stressor, so it adds stress rather than reducing it. Wellness programmes, better communication and job redesign (options A, C and D) are all ways to reduce stress."}},{"itemId":"c7caa4e9-3d86-57e5-8c85-747910f04c0a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b13dc0a4-a5ea-5cf2-b4d3-cd83f7e8adb0","sourceKey":"bank:AMS101:M101-T6N-139","parentItemId":null,"revision":1,"payload":{"prompt":"Wellness programmes that help reduce stress typically focus on:","options":["Fitness, healthy eating and stopping smoking","Counselling for personal legal problems only","Merging departments to cut costs","Questionnaires about planned changes"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Wellness programmes promote fitness, healthy eating and stopping smoking. Option B sounds like an EAP, Option C is structural change, and Option D is survey feedback."}},{"itemId":"725a0a1a-c933-5cc7-9a0e-21e65df8489f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca21b8d8-f363-5adc-a937-ce52ecd97930","sourceKey":"bank:AMS101:M101-T6N-140","parentItemId":null,"revision":1,"payload":{"prompt":"Careful employee selection reduces stress mainly because it:","options":["Guarantees high job security","Increases role demands","Matches people to jobs so that their abilities fit the job","Removes the need to communicate during change"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Careful selection matches people to jobs so their abilities fit what the job requires, which lowers stress. Option D is wrong because communication still matters during change, and Option B would actually increase stress."}},{"itemId":"6e5f41ea-c5c5-5263-8334-879ff067a269","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30aef0c0-524b-51e3-8bbf-6a1dc88b51a7","sourceKey":"bank:AMS101:M101-T6N-141","parentItemId":null,"revision":1,"payload":{"prompt":"Creativity is best defined as:","options":["The ability to combine ideas in a unique way or to make unusual associations between ideas","Any alteration of people, structure or technology","Actively and enthusiastically supporting new ideas until they are implemented","Taking a creative idea and turning it into a useful product, service or method of operation"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Creativity is the ability to combine ideas uniquely or make unusual links between them. Option D is the definition of innovation, which puts the idea to use, and Option C describes what idea champions do."}},{"itemId":"733af8ba-67bf-52e3-bf5c-91cfb729c07d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ecf130a8-cf2c-5610-b6a7-7d7c1d42e38b","sourceKey":"bank:AMS101:M101-T6N-142","parentItemId":null,"revision":1,"payload":{"prompt":"Innovation is best defined as:","options":["Making unusual associations between ideas","Taking a creative idea and turning it into a useful product, service or method of operation","The ability to combine ideas in a unique way","Changing the attitudes groups hold about each other"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Innovation turns a creative idea into a useful product, service or method of operation. Option C and Option A both describe creativity, which produces the idea but does not put it to use."}},{"itemId":"a6990884-9891-57f2-839d-1ac7d6a3ecf4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8a988ed2-2283-56c8-ab2b-1e96796f7caf","sourceKey":"bank:AMS101:M101-T6N-143","parentItemId":null,"revision":1,"payload":{"prompt":"\"The ability to combine ideas in a unique way or to make unusual associations between ideas\" defines:","options":["Co-optation","Innovation","Creativity","Organizational development"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"This is the definition of creativity. Option B is the classic trap, because innovation is not the ability to combine ideas; it is turning a creative idea into something useful."}},{"itemId":"6478661d-b181-510c-b088-49971240a1df","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b052f41-21f2-553f-b5e5-601806727950","sourceKey":"bank:AMS101:M101-T6N-144","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes creativity from innovation?","options":["Creativity applies only to products, while innovation applies only to services","Creativity and innovation mean exactly the same thing","Creativity produces the idea, while innovation puts it to use","Innovation produces the idea, while creativity puts it to use"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Creativity produces the new idea, and innovation turns it into a useful product, service or method. Option D reverses the two, which is the most common mistake."}},{"itemId":"62c481ab-6288-57e5-bc69-5fd4ebe6dd3d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"14d23d3e-0273-5742-9a08-f0117a13578c","sourceKey":"bank:AMS101:M101-T6N-145","parentItemId":null,"revision":1,"payload":{"prompt":"A design team at a Lagos fintech produces dozens of original ideas every month, but none of them ever becomes a working product. The firm is:","options":["Neither creative nor innovative","Creative but not yet innovative","Both highly creative and highly innovative","Innovative but not creative"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Having many new ideas shows creativity, but innovation requires turning those ideas into results. Option D reverses this, since innovation is exactly the step this firm is missing."}},{"itemId":"19e9dcbe-6629-56c6-b042-e5b9ccfbf86b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d9c71366-ad6c-5dd3-a0c1-ed19ba9dffaa","sourceKey":"bank:AMS101:M101-T6N-146","parentItemId":null,"revision":1,"payload":{"prompt":"In the systems view of innovation, the inputs are:","options":["Innovative products and work methods","Creative people and groups","A creative environment, process and situation","Abundant resources and minimal time pressure"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"The inputs are creative people and groups. Option C is the transformation stage and Option A is the outputs stage of the same model."}},{"itemId":"7ec15b2d-bc1b-5e12-b39e-af859e683d21","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f32eb4b1-ec18-5858-b8aa-304b381590a2","sourceKey":"bank:AMS101:M101-T6N-147","parentItemId":null,"revision":1,"payload":{"prompt":"In the systems view of innovation, the transformation stage consists of:","options":["Creative people and groups","Innovative products and work methods","A creative environment, process and situation","Idea champions and change agents"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"The transformation stage is a creative environment, process and situation that turns inputs into outputs. Option A is the inputs and Option B is the outputs."}},{"itemId":"0370d993-0197-5511-a2c1-ddf731a00a97","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d2b83a17-bb8f-5fbd-b5a2-f65c4b266bb7","sourceKey":"bank:AMS101:M101-T6N-148","parentItemId":null,"revision":1,"payload":{"prompt":"In the systems view of innovation, the outputs are:","options":["A creative environment, process and situation","Creative people and groups","Refrozen behaviours","Innovative products and work methods"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"The outputs are innovative products and work methods. Option B is the inputs and Option A is the transformation stage."}},{"itemId":"4b7dab91-1675-5ee9-b9c5-822b4cda2d1f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b223433b-5287-5b96-a3f0-0c6944194719","sourceKey":"bank:AMS101:M101-T6N-149","parentItemId":null,"revision":1,"payload":{"prompt":"Which three sets of variables have been found to foster innovation?","options":["Physical, psychological and behavioural","Inputs, transformation and outputs","Task, role and interpersonal","Structural, cultural and human resource"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Innovation is fostered by structural, cultural and human resource variables. Option A lists stress symptoms, Option B is the systems view of innovation, and Option C lists job-related stressors."}},{"itemId":"663620a1-2e96-5c23-b1fc-13b493b43a53","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d6038e80-ff79-5402-b159-d9cea5c94257","sourceKey":"bank:AMS101:M101-T6N-150","parentItemId":null,"revision":1,"payload":{"prompt":"An organic structure, abundant resources and frequent communication between units are which type of variable that fosters innovation?","options":["Structural","Behavioural","Human resource","Cultural"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Organic structure, abundant resources and frequent inter-unit communication are structural variables. Option D would include things like accepting ambiguity and tolerating risk, and Option C would include training and job security."}},{"itemId":"7f5731b8-9ea4-5895-9d36-022c7ce705b2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d53a1c8-e787-5827-9877-768546af8234","sourceKey":"bank:AMS101:M101-T6N-151","parentItemId":null,"revision":1,"payload":{"prompt":"Accepting ambiguity, tolerating the impractical and tolerating risk are which type of variable that fosters innovation?","options":["Structural","Psychological","Cultural","Human resource"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"These are cultural variables, describing the values and attitudes an innovative organization holds. Option A covers design features like an organic structure and resources, and Option D covers training, job security and idea champions."}},{"itemId":"d2a65e9c-e264-5e26-a0a5-f33388ea108d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"50095120-f3c2-59b4-9f0b-b74f1ce0e092","sourceKey":"bank:AMS101:M101-T6N-152","parentItemId":null,"revision":1,"payload":{"prompt":"Offering high job security and actively promoting training and development are which type of variable that fosters innovation?","options":["Cultural","Human resource","Structural","Personal"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Training and development, high job security and encouraging idea champions are human resource variables. Option A is tempting, but cultural variables are about values such as tolerating risk and conflict."}},{"itemId":"3d6ee8e5-c95d-5958-b901-4110966932e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be26a0d1-b8e2-559e-91de-a98828f6fae7","sourceKey":"bank:AMS101:M101-T6N-153","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a structural variable that fosters innovation?","options":["Minimal time pressure","Accepting ambiguity","Organic structure","Work and nonwork support"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Accepting ambiguity is a cultural variable. Organic structure, minimal time pressure and work and nonwork support (options A, C and D) are all structural variables."}},{"itemId":"9980ba9f-5b2a-5175-a798-1ac1f73a5189","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"854df18e-0007-5482-9823-6a9459085364","sourceKey":"bank:AMS101:M101-T6N-154","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a cultural variable that fosters innovation?","options":["Abundant resources","Focusing on ends rather than means","Tolerating conflict","Giving positive feedback"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Abundant resources is a structural variable. Tolerating conflict, focusing on ends rather than means, and giving positive feedback (options B, C and D) are all cultural variables."}},{"itemId":"c133da65-29bb-568d-a38f-39bb6a0f3cae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b5cb0367-db62-5e37-b4bd-88bd4a30e2c7","sourceKey":"bank:AMS101:M101-T6N-155","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a human resource variable that fosters innovation?","options":["Encouraging people to become idea champions","Keeping external controls low","Offering high job security","Actively promoting training and development"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Keeping external controls low is a cultural variable. High job security, encouraging idea champions and promoting training and development (options A, C and D) are the three human resource variables."}},{"itemId":"5bbe7890-fdda-581a-8df4-e42867c2eee4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ca6839c-af5f-5d3a-81a9-d50415159a81","sourceKey":"bank:AMS101:M101-T6N-156","parentItemId":null,"revision":1,"payload":{"prompt":"An organic structure fosters innovation because it:","options":["Has many rules that keep everyone focused","Concentrates all decisions at the top","Is flexible and adapts quickly, with low formalization, centralization and specialization","Relies on high specialization of tasks"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"An organic structure has low formalization, centralization and specialization, so it is flexible and adapts quickly. Options A, B and D describe a mechanistic, rule-heavy structure, which stifles new ideas."}},{"itemId":"dab64dd8-5037-59bc-9295-3085c0656b36","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d0125f9-9606-5780-a680-3405a9217e35","sourceKey":"bank:AMS101:M101-T6N-157","parentItemId":null,"revision":1,"payload":{"prompt":"Why is minimal time pressure listed as a structural variable that fosters innovation?","options":["Time pressure always raises creativity","Extreme time pressure lowers creativity, even though people think it helps","Time pressure has no effect on creativity","Innovation depends only on deadlines"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Extreme time pressure actually lowers creativity, even though many people believe it helps. Option A states the popular but mistaken belief."}},{"itemId":"e21fe1be-20f9-525e-ac52-9f04a46cec8f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48575ef1-b9bf-51d2-bb1e-1c339c794653","sourceKey":"bank:AMS101:M101-T6N-158","parentItemId":null,"revision":1,"payload":{"prompt":"Abundant resources foster innovation because they allow a firm to:","options":["Avoid communicating between units","Tighten external controls","Reduce job security","Buy innovations, afford failures and try many ideas"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Plenty of resources let a firm buy innovations, afford failures and try out many ideas. Option A, Option B and Option C would all discourage innovation."}},{"itemId":"abf0023e-b691-59b6-b740-2a06648de518","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"56bc057f-8156-5296-b4c7-dd631e18b40e","sourceKey":"bank:AMS101:M101-T6N-159","parentItemId":null,"revision":1,"payload":{"prompt":"At a paint manufacturer in Ota, staff who try new ideas that fail are not punished, and mistakes are treated as chances to learn. Which variable that fosters innovation does this show?","options":["High job security, a human resource variable","Tolerating risk, a cultural variable","Abundant resources, a structural variable","Organic structure, a structural variable"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Letting staff try new things without fear of punishment, and treating mistakes as learning, is tolerating risk, a cultural variable. Option A is close, since job security also reduces fear of being fired, but the scenario is about the culture's attitude to failure."}},{"itemId":"e3f44113-e279-55ac-8f95-fb6fafa1904b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"928bd110-3f3a-50a8-a166-17cf749dab42","sourceKey":"bank:AMS101:M101-T6N-160","parentItemId":null,"revision":1,"payload":{"prompt":"High job security is listed as a human resource variable that fosters innovation because it:","options":["Reduces the fear of being fired for making mistakes","Removes the need for training","Increases time pressure on employees","Keeps the structure mechanistic"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"High job security reduces the fear of being fired for mistakes, so people are more willing to try new ideas. Option C would lower creativity, and Option D would stifle new ideas."}},{"itemId":"273d505e-e2a8-5812-a898-69da869f1f2f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"95168c2c-597f-5399-a691-4bdf80b60482","sourceKey":"bank:AMS101:M101-T6N-161","parentItemId":null,"revision":1,"payload":{"prompt":"Having an open-system focus as a cultural variable that fosters innovation means the organization:","options":["Avoids conflict at all costs","Keeps external controls high","Watches the environment closely","Focuses on means rather than ends"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"An open-system focus means watching the environment and responding to it. Option B, Option D and Option A reverse the cultural variables, which call for low external controls, a focus on ends and tolerance of conflict."}},{"itemId":"93a80f89-9d4c-566e-918a-74c92ef43f7b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0751567e-7a82-5816-8ed7-5176b18207f8","sourceKey":"bank:AMS101:M101-T6N-162","parentItemId":null,"revision":1,"payload":{"prompt":"Idea champions are individuals who:","options":["Act as catalysts and manage the whole change process","Actively and enthusiastically support new ideas, build support, overcome resistance and make sure innovations are implemented","Resist change because they have a lot invested in the current system","Use questionnaires to assess staff attitudes"],"correctOption":1,"section":"Managing Change and Innovation","explanation":"Idea champions enthusiastically back new ideas, build support, overcome resistance and see innovations through. Option A describes a change agent, who manages the change process as a whole, and Option C describes the people most likely to resist change."}},{"itemId":"34085b76-e11a-5ccb-8b8e-d0ac09f11360","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf60812a-acc7-59af-8d10-cc874bdd2569","sourceKey":"bank:AMS101:M101-T6N-163","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of traits is shared by idea champions?","options":["Low self-confidence and dependence on others","A preference for routine and caution","Time urgency, hostility and anger","Very high self-confidence, persistence, energy and a tendency to take risks"],"correctOption":3,"section":"Managing Change and Innovation","explanation":"Idea champions have very high self-confidence, persistence, energy and a tendency to take risks. Option B describes resistance through habit, and Option C describes the harmful side of the Type A personality."}},{"itemId":"cfcf48fd-aac2-506c-bfa4-c3d01df7f6f7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ff147db5-d042-563e-8b5c-92ef515dfe6f","sourceKey":"bank:AMS101:M101-T6N-164","parentItemId":null,"revision":1,"payload":{"prompt":"Encouraging people to become idea champions is which type of variable that fosters innovation?","options":["Human resource","Structural","Behavioural","Cultural"],"correctOption":0,"section":"Managing Change and Innovation","explanation":"Encouraging people to become idea champions is one of the three human resource variables, alongside training and high job security. Option D is tempting, but cultural variables are about values such as tolerating risk and ambiguity."}},{"itemId":"752c36dc-ca8b-5066-9ded-028aa890f3e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ad279889-3da3-5437-877f-91e74ac5aa68","sourceKey":"bank:AMS101:M101-T6N-165","parentItemId":null,"revision":1,"payload":{"prompt":"A software engineer at an Abuja tech firm passionately promotes a new mobile payment idea, wins support from other departments, overcomes objections and pushes until the product is launched. She is acting as a(n):","options":["Restraining force","Process consultant","Idea champion","Change agent from outside the firm"],"correctOption":2,"section":"Managing Change and Innovation","explanation":"Enthusiastically backing a new idea, building support, overcoming resistance and seeing it implemented is what an idea champion does. Option D is wrong because she is inside the firm and is pushing one innovation, and Option A is an outsider who explains interpersonal processes."}},{"itemId":"5d9ed0cd-2716-5dd4-a5fa-cd7a0a51b028","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab2e94c2-f76a-554a-a30a-4d52e9819b04","sourceKey":"bank:AMS101:M101-T7N-001","parentItemId":null,"revision":1,"payload":{"prompt":"The study of the actions of people at work is known as:","options":["Human resource management","Organizational behaviour","Organizational culture","Scientific management"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Organizational behaviour (OB) is the study of the actions of people at work, covering both individuals and groups. Option A deals with staffing activities such as recruiting and training, and Option D is about finding the one best way to do a task, so neither is the study of people's actions at work."}},{"itemId":"00829537-a52e-5b7f-8fdf-94ce0a8d57e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a14f0cf-b0e6-509e-bd4e-50d23969b481","sourceKey":"bank:AMS101:M101-T7N-002","parentItemId":null,"revision":1,"payload":{"prompt":"In organizational behaviour, the term 'behaviour' refers to:","options":["The norms shared by members of a group","The actions of people","The attitudes people hold about their jobs","The personality traits a person inherits"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Behaviour simply means the actions of people, and OB studies those actions at work. Option C describes attitudes, which are evaluative statements rather than actions, and Option A describes norms, which are shared group standards."}},{"itemId":"85863917-e64b-5544-8452-3afa2738ce35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65b26e6d-82cd-5646-bdc0-d3fdc399cf9d","sourceKey":"bank:AMS101:M101-T7N-003","parentItemId":null,"revision":1,"payload":{"prompt":"Organizational behaviour focuses on which two areas?","options":["Attitudes and personality","Individual behaviour and group behaviour","Organizational structure and technology","Planning and controlling"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"OB looks at two areas: how individuals behave at work and how groups behave. Option A names two topics studied under individual behaviour, not the two broad areas, and Option C names visible features of the organization rather than behaviour."}},{"itemId":"681d91f4-8767-5b4a-9177-4d9e67689ecd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ce3d371-7454-5154-9243-050842225b17","sourceKey":"bank:AMS101:M101-T7N-004","parentItemId":null,"revision":1,"payload":{"prompt":"The three goals of organizational behaviour are to:","options":["Measure, compare and correct performance","Plan, organize and control behaviour","Recruit, train and retain employees","Explain, predict and influence behaviour"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"OB aims to explain why people behave as they do, predict how they will behave, and influence that behaviour. Option B borrows the names of management functions, and Option A describes steps in the control process, not the goals of OB."}},{"itemId":"f82ac9a5-8a0a-5094-adc1-9427e3c6afc6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c48f7048-fa15-5f51-a0de-88d65363e53b","sourceKey":"bank:AMS101:M101-T7N-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the goals of organizational behaviour?","options":["To influence behaviour","To eliminate behaviour","To predict behaviour","To explain behaviour"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"OB has three goals: to explain, predict and influence behaviour, so eliminating behaviour is not one of them. Options D, C and A are exactly the three goals."}},{"itemId":"bf0db8c3-4d47-5e23-ba57-24f80c30e512","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d3071e1e-fde8-58ab-b1cc-e3fa4b4a258a","sourceKey":"bank:AMS101:M101-T7N-006","parentItemId":null,"revision":1,"payload":{"prompt":"How many employee behaviours do managers specifically want to explain, predict and influence?","options":["Four","Six","Five","Seven"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"There are six: employee productivity, absenteeism, turnover, organizational citizenship behaviour, job satisfaction and workplace misbehaviour. Option D is easy to confuse with the seven factors that influence individual behaviour, which is a different list."}},{"itemId":"28659a6e-a5fd-5739-8f25-59393d49c1d7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"72e15967-f58c-5bd0-aef2-f4bf4bb3c952","sourceKey":"bank:AMS101:M101-T7N-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the six employee behaviours that managers want to explain, predict and influence?","options":["Job involvement","Turnover","Absenteeism","Organizational citizenship behaviour"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Job involvement is one of the four job-related attitudes, not one of the six employee behaviours. Absenteeism, turnover and organizational citizenship behaviour (Options C, B and D) are all on the list of six, together with productivity, job satisfaction and workplace misbehaviour."}},{"itemId":"8936b1db-ee6b-56de-8fb5-edbb797c69b0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4135069a-055e-5d16-b308-951c8f017b13","sourceKey":"bank:AMS101:M101-T7N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Employee productivity is best described as:","options":["Discretionary behaviour that is not part of the formal job","An employee's general attitude towards his or her job","Failure to show up for work","A performance measure of both efficiency and effectiveness"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Productivity measures performance in terms of both efficiency and effectiveness. Option C is absenteeism, Option A is organizational citizenship behaviour and Option B is job satisfaction."}},{"itemId":"b0950a03-438a-5e1e-9627-4c75da4a01fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"62d767f8-318f-5c71-a9f9-864955e0479f","sourceKey":"bank:AMS101:M101-T7N-009","parentItemId":null,"revision":1,"payload":{"prompt":"Failure to show up for work is called:","options":["Turnover","Workplace misbehaviour","Absenteeism","Social loafing"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Absenteeism means not showing up for work. Option A, turnover, is leaving the organization for good, and the two are often swapped in exams; Option D is putting in less effort in a group, not being absent."}},{"itemId":"d0b58ec9-08da-5de9-b5c0-2802c4de9cf2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06bb2bf4-bdcd-500e-9645-4c3ea897880a","sourceKey":"bank:AMS101:M101-T7N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Voluntary and involuntary permanent withdrawal from an organization is known as:","options":["Turnover","Absenteeism","Adjourning","Low organizational commitment"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Turnover is permanent withdrawal from the organization, whether the person resigns or is let go. Option B, absenteeism, is only failing to show up, and Option C is the last stage of a temporary group, not an employee leaving the firm."}},{"itemId":"f06ea599-7a7e-50c7-90db-2d3b3bf3899c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b557a373-f3cb-5a06-9658-7c2ff25fd34c","sourceKey":"bank:AMS101:M101-T7N-011","parentItemId":null,"revision":1,"payload":{"prompt":"In one year, 40 staff of a Lagos bank resigned and left for other banks, and 10 more were dismissed. Which employee behaviour does this describe?","options":["Workplace misbehaviour","Absenteeism","Organizational citizenship behaviour","Turnover"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Turnover covers both voluntary (resigning) and involuntary (being dismissed) permanent withdrawal from the organization. Option B would apply only if the staff stayed employed but failed to show up for work."}},{"itemId":"9a33bd00-c925-51d0-8b0c-e8a13117dc29","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f7b5c6ab-31aa-518c-9928-d9bc84bbb6e5","sourceKey":"bank:AMS101:M101-T7N-012","parentItemId":null,"revision":1,"payload":{"prompt":"Discretionary behaviour that is not part of an employee's formal job requirements but helps the organization work well is called:","options":["Job involvement","Employee productivity","Organizational citizenship behaviour","Employee engagement"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Organizational citizenship behaviour (OCB) is discretionary: nobody can order it, yet it helps the organization run well. Options D and A are job-related attitudes, not behaviours, and Option B is a measure of efficiency and effectiveness."}},{"itemId":"592b3fe6-df9c-5fc3-bd5d-93be20de76d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"256fb6e4-e4fd-51a3-affd-5bf5be5968e9","sourceKey":"bank:AMS101:M101-T7N-013","parentItemId":null,"revision":1,"payload":{"prompt":"At a manufacturing plant in Ota, Bola often stays late without being asked to help a colleague finish a team task, and she speaks well of the company to outsiders. Her behaviour is an example of:","options":["Turnover","Employee productivity","Organizational citizenship behaviour","Workplace misbehaviour"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Helping a colleague, staying late to finish a team task and speaking well of the organization are classic examples of OCB, which is voluntary and not part of the formal job. Option B measures efficiency and effectiveness of performance in general, not voluntary extra-role helping."}},{"itemId":"049cf69c-c755-5de6-bd02-afd4c7b29b9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"81db0196-773e-5d28-a2d2-0702ebb94f77","sourceKey":"bank:AMS101:M101-T7N-014","parentItemId":null,"revision":1,"payload":{"prompt":"Any intentional employee behaviour that could harm the organization or people in it is called:","options":["Dysfunctional conflict","Absenteeism","Workplace misbehaviour","Social loafing"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Workplace misbehaviour is any intentional behaviour that could harm the organization or the people in it. Option A is conflict that stops a group from reaching its goals, and Option D is reduced effort in a group, which is not defined by intent to harm."}},{"itemId":"c2aae670-9975-539f-9f89-69ee7bcc6d77","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d069a899-6e4e-5589-bb26-20d644b57254","sourceKey":"bank:AMS101:M101-T7N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Workplace misbehaviour takes four forms. Which of the following is NOT one of them?","options":["Absenteeism","Deviance","Antisocial behaviour","Aggression"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The four forms of workplace misbehaviour are deviance, aggression, antisocial behaviour and violence. Absenteeism is a separate employee behaviour (failure to show up for work), not a form of misbehaviour."}},{"itemId":"63ea9975-21ce-5e07-8331-7f42081cff91","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b868b2ab-7bda-5660-aa04-f9d4856dedea","sourceKey":"bank:AMS101:M101-T7N-016","parentItemId":null,"revision":1,"payload":{"prompt":"As one of the six employee behaviours managers study, job satisfaction refers to:","options":["An employee's general attitude towards his or her job","How far an employee sees job performance as important to self-worth","Discretionary behaviour that helps the organization work well","How far an employee identifies with the organization and wants to stay"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Job satisfaction is an employee's general attitude towards his or her job. Option D describes organizational commitment and Option B describes job involvement, two other job-related attitudes."}},{"itemId":"84d0baa5-8d67-5d3f-8c57-c69ba235425e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b8edd12b-61cd-566c-88fc-c4f1b7e9ec2a","sourceKey":"bank:AMS101:M101-T7N-017","parentItemId":null,"revision":1,"payload":{"prompt":"In the 'organization as an iceberg' view, which of the following lies below the water (hidden)?","options":["Chain of command","Strategies and objectives","Group norms","Technology"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The hidden part of the iceberg holds attitudes, perceptions, group norms, informal interactions and interpersonal and intergroup conflicts. Options B, A and D are formal, visible features that sit above the water."}},{"itemId":"094de751-5352-5eb9-b558-973cef596b63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"598817b0-1ce3-548a-8763-bc03a239b608","sourceKey":"bank:AMS101:M101-T7N-018","parentItemId":null,"revision":1,"payload":{"prompt":"In the 'organization as an iceberg' view, which of the following is visible above the water?","options":["Attitudes","Formal authority","Interpersonal conflicts","Perceptions"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Formal authority is part of the visible organization, together with strategies, objectives, policies and procedures, structure, technology and chain of command. Options A, D and C are hidden below the surface and harder to see."}},{"itemId":"9e09ce7b-aacb-5683-b0a6-520b86fac6bf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8751de31-4b84-5d3d-bfc6-776f382e9e1b","sourceKey":"bank:AMS101:M101-T7N-019","parentItemId":null,"revision":1,"payload":{"prompt":"Why is organizational behaviour compared to an iceberg?","options":["Organizations are cold and impersonal places to work","Formal structure matters more than people's attitudes","Most of what drives behaviour at work lies below the surface and is harder to see","Only top managers can see the whole organization"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The iceberg image shows that the visible parts of an organization, such as structure and rules, are only a small part; attitudes, perceptions and norms sit hidden below and drive much of behaviour. Option B reverses the point, because the hidden human side is what matters most and is hardest to understand."}},{"itemId":"3af351f2-d156-5ad3-9938-22d454bcc4c7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"96c40a9c-e798-5c12-870d-662c7b210179","sourceKey":"bank:AMS101:M101-T7N-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the seven factors that influence individual behaviour?","options":["Age","Organizational structure","Societal responsibilities","Marital status"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The seven factors are personal ones: biography/demography, age, gender, societal responsibilities, marital status, personality, and values and attitudes. Organizational structure is a visible feature of the organization, not a factor of the individual."}},{"itemId":"a902a70e-33e8-56e3-9d2a-5ce5964e53c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ea9db98-9864-53b4-a803-00cc74fa52fa","sourceKey":"bank:AMS101:M101-T7N-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the five factors that change individual behaviours?","options":["Organizational structure","Group cohesiveness","Motivation","Formal authority"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The five factors that change individual behaviours are demographic/biological factors, personality, values and attitudes, motivation and learning. Options A and D are visible organizational features, and Option B is a property of groups."}},{"itemId":"c2b85bbf-3e6d-5e08-897d-7ec3db2db51a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa8cff02-3745-5f0a-a912-ca3f29eb59ca","sourceKey":"bank:AMS101:M101-T7N-023","parentItemId":null,"revision":1,"payload":{"prompt":"Who founded industrial psychology, the scientific study of people at work?","options":["Mary Parker Follett","Hugo Munsterberg","Chester Barnard","Robert Owen"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Hugo Munsterberg founded industrial psychology, and his work links easily with scientific management. Option D, Robert Owen, is remembered for his concern about terrible working conditions, not for founding a field of study."}},{"itemId":"9c517d49-6fea-5f1f-9312-0acf9be93c51","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ebc99add-9555-5e97-b7c1-47a7ebf08161","sourceKey":"bank:AMS101:M101-T7N-024","parentItemId":null,"revision":1,"payload":{"prompt":"Industrial psychology is best described as:","options":["The study of group decision making","The study of organizations as open systems","The scientific study of people at work","The study of how lighting affects productivity"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Industrial psychology, founded by Hugo Munsterberg, is the scientific study of people at work. Option D describes how the Hawthorne Studies began, and Option B relates to Chester Barnard's view of organizations."}},{"itemId":"11928c53-1ae8-5d68-a3b9-75e79723788c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a2a6008c-bc44-5d78-b1ed-51611b4c990e","sourceKey":"bank:AMS101:M101-T7N-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which early supporter of organizational behaviour is best known for his concern about terrible working conditions?","options":["Elton Mayo","Robert Owen","Chester Barnard","Hugo Munsterberg"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Robert Owen was concerned about the terrible working conditions of his time. Option D, Munsterberg, founded industrial psychology, and Option C, Barnard, saw organizations as social and open systems."}},{"itemId":"4c22f152-0f94-5822-a8ae-1eb415a5c10c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2d197a1f-c9c9-51f4-9177-5a446e4b7aa8","sourceKey":"bank:AMS101:M101-T7N-026","parentItemId":null,"revision":1,"payload":{"prompt":"Who was one of the first to see that organizations could be studied through individual and group behaviour, and to whom the modern use of work groups is traced?","options":["Mary Parker Follett","Robert Owen","Hugo Munsterberg","Chester Barnard"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Mary Parker Follett was one of the first to recognise that organizations could be viewed through individual and group behaviour, and the modern use of work groups traces back to her. Option D is tempting because Barnard also stressed human cooperation, but he is known for seeing organizations as social and open systems."}},{"itemId":"c0060d94-57c6-5873-8da2-a7c24bf9d3de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"831b3374-164c-5ab9-bc02-7f1f86abb299","sourceKey":"bank:AMS101:M101-T7N-027","parentItemId":null,"revision":1,"payload":{"prompt":"Who argued that organizations are social systems that need human cooperation and was the first to argue that they are open systems?","options":["Mary Parker Follett","Chester Barnard","Robert Owen","Hugo Munsterberg"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Chester Barnard saw organizations as social systems requiring human cooperation and was the first to argue that they are open systems. Option A, Follett, is linked with studying organizations through individual and group behaviour."}},{"itemId":"a8401a17-36b0-5265-a622-62fe64fa51d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4580d2a8-d0b0-5e32-9297-a4b6315f6f15","sourceKey":"bank:AMS101:M101-T7N-028","parentItemId":null,"revision":1,"payload":{"prompt":"The Hawthorne Studies originally began as tests of how which factor affects worker productivity?","options":["Working hours","Lighting","Group size","Pay incentives"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Hawthorne Studies started as experiments on how lighting levels affect productivity. Their famous finding about social norms came later, so Option C, group size, and the other options were not the starting point."}},{"itemId":"6e36739b-92c4-5689-814c-8ba76f3f02a1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9deffdf8-c827-50a0-9ade-55e97a691e99","sourceKey":"bank:AMS101:M101-T7N-029","parentItemId":null,"revision":1,"payload":{"prompt":"The Hawthorne Studies concluded that the main drivers of individual work behaviour are:","options":["Financial incentives","Formal rules and procedures","Social norms or group standards","Physical working conditions such as lighting"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Hawthorne Studies found that social norms or group standards are the main drivers of individual work behaviour, which is why they made the biggest contribution to OB. Option D is tempting because the studies began by testing lighting, but lighting turned out not to be the main driver."}},{"itemId":"a4a741f6-a8aa-5e9f-93a4-b6d284655d74","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6142b102-1f68-5e29-94bb-30be0c3e843d","sourceKey":"bank:AMS101:M101-T7N-030","parentItemId":null,"revision":1,"payload":{"prompt":"The Hawthorne Studies are most closely associated with:","options":["Robert Owen","Elton Mayo","Hugo Munsterberg","Chester Barnard"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Hawthorne Studies are linked with Elton Mayo and made the biggest contribution to OB of all the early efforts. Option C, Munsterberg, is linked with industrial psychology rather than the Hawthorne experiments."}},{"itemId":"822babf5-dcb3-5601-a0a5-863e4f885b56","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6473725d-5867-5e83-9811-dff12e40e5eb","sourceKey":"bank:AMS101:M101-T7N-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach to management is most closely tied to concern for employee motivation?","options":["Scientific management","Bureaucracy","The quantitative approach","Organizational behaviour"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Organizational behaviour, with its focus on people's actions at work, is the approach most closely tied to concern for employee motivation. Option A, scientific management, focused mainly on finding the best way to do a task rather than on motivation."}},{"itemId":"a2a2a253-82eb-5661-8b72-dbc137bb026c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"44401039-f755-589f-9016-f97f0b29eca4","sourceKey":"bank:AMS101:M101-T7N-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following early efforts made the biggest contribution to organizational behaviour?","options":["Chester Barnard's open systems view","Robert Owen's factory reforms","Hugo Munsterberg's industrial psychology","The Hawthorne Studies"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Hawthorne Studies made the biggest contribution to OB because they showed that social norms and group standards drive individual work behaviour. Option C founded industrial psychology, an important but smaller contribution."}},{"itemId":"dc009671-bce2-5091-8b87-b7a1d07c1b53","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b7a04bb-6259-5ae8-9dc8-c0e2f1e3af26","sourceKey":"bank:AMS101:M101-T7N-033","parentItemId":null,"revision":1,"payload":{"prompt":"Evaluative statements, either favourable or unfavourable, about objects, people or events are called:","options":["Norms","Perceptions","Values","Attitudes"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Attitudes are evaluative statements, favourable or unfavourable, that show how a person feels about something. Option B, perception, is the process of giving meaning to the environment by organizing and interpreting sensory impressions, and Option A, norms, are standards shared by a group."}},{"itemId":"0901f6a4-3448-53b0-8f7b-923671bc4bb0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"616b29a5-3a27-5ae0-b2a5-1df214383665","sourceKey":"bank:AMS101:M101-T7N-034","parentItemId":null,"revision":1,"payload":{"prompt":"Attitudes mainly show:","options":["How a person organizes sensory impressions","How a group defines its leadership","How behaviour is shaped by its consequences","How a person feels about something"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Attitudes are evaluative statements that show how a person feels about objects, people or events. Option A describes perception and Option C describes operant conditioning."}},{"itemId":"22579e6f-cf70-5a33-ac02-a1af95906b67","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca8a1213-9b53-55aa-bdf2-fd01ee9cafaf","sourceKey":"bank:AMS101:M101-T7N-035","parentItemId":null,"revision":1,"payload":{"prompt":"How many components does an attitude have?","options":["Four","Five","Three","Two"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"An attitude has three components: cognitive, affective and behavioural. Option A, four, is the number of job-related attitudes, which is a different list."}},{"itemId":"2cf7a613-eb70-5448-bafb-65cb09a65dd0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e33ff007-5671-5054-9dbd-5c947d2704ad","sourceKey":"bank:AMS101:M101-T7N-036","parentItemId":null,"revision":1,"payload":{"prompt":"The component of an attitude made up of beliefs, opinions, knowledge and information is the:","options":["Perceptual component","Behavioural component","Affective component","Cognitive component"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The cognitive component holds a person's beliefs, opinions, knowledge and information. Option C, the affective component, is about emotions and feelings, and Option B is the intention to behave in a certain way."}},{"itemId":"42a77075-6e27-50ca-bb55-a75ce5772b6d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"da6debe2-31af-55cc-84ce-a14c847d4974","sourceKey":"bank:AMS101:M101-T7N-037","parentItemId":null,"revision":1,"payload":{"prompt":"The emotional or feeling part of an attitude is called the:","options":["Cognitive component","Behavioural component","Evaluative component","Affective component"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The affective component is made up of emotions and feelings. Option A, the cognitive component, is made up of beliefs and knowledge, which is the most common mix-up."}},{"itemId":"681d70cf-cfe6-51c5-8b9c-5f3aba115662","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"91a8684d-7698-5f99-80e6-40fd90db560c","sourceKey":"bank:AMS101:M101-T7N-038","parentItemId":null,"revision":1,"payload":{"prompt":"The component of an attitude that refers to an intention to behave in a certain way is the:","options":["Behavioural component","Affective component","Motivational component","Cognitive component"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The behavioural component is the intention to act in a certain way towards someone or something. Option B, the affective component, is the feeling part that often comes before that intention."}},{"itemId":"fc8ea570-ec09-5362-8640-f78adcadc79b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7b286844-7083-5a02-a7cc-85d3ba7865a3","sourceKey":"bank:AMS101:M101-T7N-039","parentItemId":null,"revision":1,"payload":{"prompt":"The statement \"Discrimination is wrong\" reflects which component of an attitude?","options":["Behavioural","Affective","Cognitive","Normative"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"\"Discrimination is wrong\" is a belief or opinion, which belongs to the cognitive component. Option B would be a feeling such as disliking someone, and Option A would be an intention such as avoiding someone."}},{"itemId":"ae36a0cb-cacc-5816-a810-d497b42b8a97","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ada927ca-4e01-59cc-93e4-97d53515d233","sourceKey":"bank:AMS101:M101-T7N-040","parentItemId":null,"revision":1,"payload":{"prompt":"The statement \"I dislike Ade because he discriminates\" reflects which component of an attitude?","options":["Behavioural","Cognitive","Perceptual","Affective"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Disliking someone is an emotion or feeling, so it is the affective component. Option B would be a belief such as \"discrimination is wrong\", and Option A would be an intention such as \"I will avoid Ade\"."}},{"itemId":"e5dea04d-481f-56e1-914c-0a979c49c551","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2e4a6c67-7ecf-5ad6-81c0-1f21972c1add","sourceKey":"bank:AMS101:M101-T7N-041","parentItemId":null,"revision":1,"payload":{"prompt":"The statement \"I will avoid Ade\" reflects which component of an attitude?","options":["Cognitive","Behavioural","Evaluative","Affective"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"\"I will avoid Ade\" states an intention to act in a certain way, which is the behavioural component. Option D is tempting because the intention grows out of a feeling of dislike, but the affective component is the feeling itself, not the planned action."}},{"itemId":"ffab94bf-08db-5cda-a993-0c2c4243cb1f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9750ecc3-27f2-50c0-873f-297eef3a37a9","sourceKey":"bank:AMS101:M101-T7N-042","parentItemId":null,"revision":1,"payload":{"prompt":"A nurse at a teaching hospital in Lagos says, \"I feel frustrated and upset about the new night-shift roster.\" Which component of her attitude is she expressing?","options":["Behavioural","Normative","Affective","Cognitive"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Feeling frustrated and upset is an emotion, so she is expressing the affective component. Option D would be a belief or piece of information about the roster, and Option A would be a stated intention, such as planning to ask for a transfer."}},{"itemId":"d7de6785-c6f7-5281-899c-bc4ba891e979","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2d34946b-2a40-54ec-b3ef-8d6a17ba17ce","sourceKey":"bank:AMS101:M101-T7N-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a component of an attitude?","options":["Affective","Perceptual","Behavioural","Cognitive"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"An attitude has three components: cognitive, affective and behavioural. Perception is a separate process of organizing and interpreting sensory impressions, not a component of an attitude."}},{"itemId":"4da3fa37-e3b8-59e7-9048-ae1cdb94f12c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e76c4fbd-6a9e-55e3-9b5e-5b8e48fe6deb","sourceKey":"bank:AMS101:M101-T7N-044","parentItemId":null,"revision":1,"payload":{"prompt":"How many job-related attitudes are commonly identified?","options":["Four","Six","Five","Three"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"There are four job-related attitudes: job satisfaction, job involvement, organizational commitment and employee engagement. Option D, three, is the number of attitude components, and Option B, six, is the number of employee behaviours."}},{"itemId":"ee04a2d6-19dd-51dc-b6eb-25f01ce6f762","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"02cf66ec-c055-59fe-8d08-4587acdee289","sourceKey":"bank:AMS101:M101-T7N-045","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which a person identifies with his or her job, takes an active part in it and sees job performance as important to self-worth is called:","options":["Job involvement","Employee engagement","Organizational commitment","Job satisfaction"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Job involvement is about how far a person identifies with the job itself and ties self-worth to performing it well. Option C is about identifying with the organization and wanting to stay, which exams often swap with job involvement."}},{"itemId":"d9527617-0a61-58e2-8810-94af7aa09798","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0037b3f2-d93a-5a31-9a90-c36493d6892d","sourceKey":"bank:AMS101:M101-T7N-046","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which an employee identifies with a particular organization and its goals and wishes to remain a member is called:","options":["Job involvement","Job satisfaction","Group cohesiveness","Organizational commitment"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Organizational commitment is about identifying with the organization and its goals and wanting to stay a member. Option A, job involvement, is about identifying with the job rather than the organization, and Option C, cohesiveness, describes attraction to a group."}},{"itemId":"069e1611-0fd8-5f29-8a5e-356a58d5ea92","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ea75d2b2-7967-5c04-84f3-94c0f704bd99","sourceKey":"bank:AMS101:M101-T7N-047","parentItemId":null,"revision":1,"payload":{"prompt":"When employees are connected to, satisfied with and enthusiastic about their jobs, this is known as:","options":["Organizational commitment","Job involvement","Employee engagement","Organizational citizenship behaviour"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Employee engagement means being connected to, satisfied with and enthusiastic about the job. Option B focuses on identifying with the job and tying self-worth to it, while Option D is a behaviour, not an attitude."}},{"itemId":"6367e5fa-7f7f-5751-a327-2476211ed36f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be6a6ccb-8c3a-54c0-b48e-fb37526422dc","sourceKey":"bank:AMS101:M101-T7N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four job-related attitudes?","options":["Organizational commitment","Job satisfaction","Job involvement","Organizational citizenship behaviour"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Organizational citizenship behaviour is one of the six employee behaviours, not a job-related attitude. The four job-related attitudes are job satisfaction, job involvement, organizational commitment and employee engagement."}},{"itemId":"2f023013-db02-5371-a730-d9015658b5bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b767fb7f-8911-5fdc-b273-053f4c9f9140","sourceKey":"bank:AMS101:M101-T7N-049","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between job involvement and organizational commitment?","options":["Job involvement is a behaviour; organizational commitment is an attitude","Job involvement is about the organization; organizational commitment is about the job","Job involvement applies to managers; organizational commitment applies to workers","Job involvement is about identifying with the job; organizational commitment is about identifying with the organization"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Job involvement concerns the job itself, while organizational commitment concerns the organization and the wish to remain a member. Option B is the classic exam swap of the two, and Option A is wrong because both are job-related attitudes."}},{"itemId":"22247036-750e-5b3e-9f79-88364aa2ccb7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d71fa7a-e4ef-55c2-bacf-d92558ea32c9","sourceKey":"bank:AMS101:M101-T7N-050","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde, an accountant at a manufacturing firm in Ota, believes strongly in the company's goals and says he would like to stay with the firm for the rest of his career, whatever role he holds. Which job-related attitude does he show most strongly?","options":["Job involvement","Employee engagement","Job satisfaction","Organizational commitment"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Identifying with the company and its goals and wanting to stay a member, regardless of role, is organizational commitment. Option A, job involvement, would focus on his particular job and how his self-worth depends on performing it, not on loyalty to the firm."}},{"itemId":"f3016bd9-5814-5877-beb5-00ecae21ec26","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bab80b14-d6a3-51f1-88c1-18f2240a2295","sourceKey":"bank:AMS101:M101-T7N-051","parentItemId":null,"revision":1,"payload":{"prompt":"A lecturer in a university department feels that how well she teaches her courses is central to her sense of self-worth, and she takes an active part in every aspect of her job. Which job-related attitude is this?","options":["Job involvement","Organizational citizenship behaviour","Organizational commitment","Self-esteem"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Identifying with the job, taking an active part in it and seeing performance as important to self-worth is job involvement. Option C would be about identifying with the university as an organization and wanting to stay there."}},{"itemId":"5afb3509-fbf8-5a1a-b747-5d13f059d951","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"474d7af0-f6bb-50c4-8221-eceff8c0a5b2","sourceKey":"bank:AMS101:M101-T7N-052","parentItemId":null,"revision":1,"payload":{"prompt":"Any incompatibility or inconsistency between attitudes, or between behaviour and attitudes, is called:","options":["Fundamental attribution error","Self-serving bias","Role conflict","Cognitive dissonance"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Cognitive dissonance is the inconsistency a person experiences between two attitudes, or between what he believes and how he behaves. Option C, role conflict, is facing different role expectations at the same time, which is about roles rather than attitudes."}},{"itemId":"1ae9a3b8-553f-59f4-a536-16b43c559c6e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b38c980-6575-5fc9-8da0-a7f40a8bf7ea","sourceKey":"bank:AMS101:M101-T7N-053","parentItemId":null,"revision":1,"payload":{"prompt":"The theory of cognitive dissonance was proposed by:","options":["John Holland","Hugo Munsterberg","B. F. Skinner","Leon Festinger"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Leon Festinger proposed cognitive dissonance theory. Option C, Skinner, is associated with operant conditioning, and Option A, Holland, with personality-job fit."}},{"itemId":"2e42a47d-d0c7-5f02-b781-bfadbf0c15d6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2cfd0e3-0382-5c5d-8918-98173c2e1957","sourceKey":"bank:AMS101:M101-T7N-054","parentItemId":null,"revision":1,"payload":{"prompt":"The effort a person puts into reducing cognitive dissonance depends on several factors. Which of the following is NOT one of them?","options":["The person's age","The rewards involved","How important the elements causing the dissonance are","How much influence the person believes he or she has over the elements"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The three factors are the importance of the elements causing the dissonance, the influence the person believes he or she has over them, and the rewards involved. Age is not one of these factors, even though it does influence individual behaviour in general."}},{"itemId":"710f59eb-6cf9-544f-9f52-da4dd9970d07","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a48423d2-1d03-5c63-b713-f33cabac25c9","sourceKey":"bank:AMS101:M101-T7N-055","parentItemId":null,"revision":1,"payload":{"prompt":"A production manager in Ota believes firms should not pollute, but he is told to dump waste into a nearby river. He feels less uncomfortable about this because the job pays very well. Which factor is reducing his dissonance?","options":["The importance of the elements","Self-serving bias","Organizational commitment","The rewards involved"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The high pay is a reward, and rewards are one of the three factors that affect how much dissonance a person feels. Option A would apply if he saw the issue itself as unimportant, which is not what the scenario says."}},{"itemId":"d124b8ef-2a78-52b2-8f99-8d7b83b50494","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d3bc709-2123-5e0f-854b-01caf28bc15d","sourceKey":"bank:AMS101:M101-T7N-056","parentItemId":null,"revision":1,"payload":{"prompt":"When people notice an inconsistency between their attitudes and their behaviour, they typically:","options":["Always resign from the organization","Change the attitude or the behaviour, or find a reason for the gap","Ignore it, since inconsistency causes no discomfort","Ask others in the group to change their attitudes"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"People seek consistency, so when they notice inconsistency they change the attitude or the behaviour, or develop a reason for the gap. Option C contradicts the idea of dissonance, which is uncomfortable precisely because people want consistency."}},{"itemId":"cfb643f5-13e9-50a3-b6ea-1d09d0f7607c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c29be70a-bd71-51c6-9e17-0dfb04870e71","sourceKey":"bank:AMS101:M101-T7N-057","parentItemId":null,"revision":1,"payload":{"prompt":"Managers commonly measure employees' attitudes using:","options":["The Myers-Briggs Type Indicator","Attitude surveys","Performance appraisals","Attribution theory"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Attitude surveys are the tool managers use to find out how employees feel about their work. Option A, the MBTI, is a personality assessment, not an attitude measure."}},{"itemId":"4a722aef-c96e-5108-a7e3-495294f97c81","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b9ea3e26-5ec5-547f-bcab-14ee28e67e45","sourceKey":"bank:AMS101:M101-T7N-058","parentItemId":null,"revision":1,"payload":{"prompt":"Employees who are satisfied with their jobs tend to have:","options":["No difference in absenteeism or turnover","Higher absenteeism and higher turnover","Lower absenteeism but higher turnover","Lower absenteeism and lower turnover"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Satisfied employees tend to show up more and stay longer, so both their absenteeism and their turnover are lower. Option B gets the relationship backwards, and Option C is wrong because satisfaction lowers turnover as well as absenteeism."}},{"itemId":"9e19ef6a-a78c-5b51-8fbc-83d381c27d0c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"73cf273e-8f33-5268-aff5-9298c3f35bc8","sourceKey":"bank:AMS101:M101-T7N-059","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about satisfied and engaged employees is correct?","options":["They tend to give better customer service","They tend to have higher turnover","They are more likely to engage in workplace misbehaviour","They tend to put in less effort when working in groups"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Satisfied, engaged employees tend to give better customer service. Option B is wrong because satisfaction is linked with lower, not higher, turnover."}},{"itemId":"68e2819a-ad37-5380-a38c-c9904aac74b7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9d9bfe51-1b9e-52b4-bd69-44f08a767fc5","sourceKey":"bank:AMS101:M101-T7N-060","parentItemId":null,"revision":1,"payload":{"prompt":"The unique combination of emotional, thought and behavioural patterns that affect how a person reacts to situations and interacts with others is called:","options":["Attitude","Perception","Emotional intelligence","Personality"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Personality is a person's unique combination of emotional, thought and behavioural patterns. Option A, an attitude, is an evaluative statement about something, and Option C is the ability to notice and manage emotional cues."}},{"itemId":"f8517ffa-6b9d-5c52-8744-6cfdedafc997","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4c6bb903-60cf-5950-a12b-a97623e4896b","sourceKey":"bank:AMS101:M101-T7N-061","parentItemId":null,"revision":1,"payload":{"prompt":"A person's personality comes from:","options":["Both heredity and environment","Environment only","Formal training at work only","Heredity (genes) only"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Personality is shaped by both heredity (genes) and environment. Options D and B each give only half of the picture."}},{"itemId":"92f8c701-0667-5828-baab-e1559d25f79c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2e1f9c59-ce74-5970-8802-3d4e88a06d3b","sourceKey":"bank:AMS101:M101-T7N-062","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the three factors that influence personality?","options":["Perceiver, target and situation","Selection, training and rewards","Distinctiveness, consensus and consistency","Perception, emotions and religion"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Perception, emotions and religion are the three factors that influence personality. Option A lists the factors that influence perception, and Option C lists the factors used in attribution theory."}},{"itemId":"9b8d8ba6-da24-5ab1-8dc0-3ee4748b82b1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4c6266d2-0c18-5674-b41e-6ff018e0bc60","sourceKey":"bank:AMS101:M101-T7N-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the Big Five personality traits?","options":["Conscientiousness","Locus of control","Agreeableness","Openness"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Big Five are openness, conscientiousness, extraversion, agreeableness and neuroticism (OCEAN). Locus of control is an important personality trait, but it is listed among the other traits, not in the Big Five."}},{"itemId":"5053c540-6b5d-5561-b1e0-adc072b8ebfc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07d93b7d-e9b1-5d7b-83f8-4fb101dc1205","sourceKey":"bank:AMS101:M101-T7N-064","parentItemId":null,"revision":1,"payload":{"prompt":"In the Big Five model, a person who is imaginative, curious and artistically sensitive scores high on:","options":["Extraversion","Openness to experience","Agreeableness","Conscientiousness"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Openness to experience covers being imaginative, curious and artistically sensitive. Option A, extraversion, is about being sociable, talkative and assertive."}},{"itemId":"6584a75d-f9ae-5021-ab56-c9e21951796a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e05aeb62-8351-581a-90f0-afcfdfdec41d","sourceKey":"bank:AMS101:M101-T7N-065","parentItemId":null,"revision":1,"payload":{"prompt":"In the Big Five model, being responsible, dependable, persistent and achievement-oriented describes:","options":["Agreeableness","Emotional stability","Conscientiousness","Openness"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Conscientiousness describes people who are responsible, dependable, persistent and achievement-oriented. Option A, agreeableness, is about being good-natured, cooperative and trusting."}},{"itemId":"e9555f83-ca4b-5fd0-96d5-d94662810347","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89ee6d8b-4ae2-52fc-9f6a-75afc32d6dd8","sourceKey":"bank:AMS101:M101-T7N-066","parentItemId":null,"revision":1,"payload":{"prompt":"Which Big Five trait describes a person who is sociable, talkative and assertive?","options":["Conscientiousness","Openness","Agreeableness","Extraversion"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Extraversion is the Big Five trait for being sociable, talkative and assertive. Option C, agreeableness, is about being good-natured and cooperative, which is different from being outgoing and assertive."}},{"itemId":"7da1c92b-7623-5581-939d-09ea8d9159e9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98792ef1-5fd5-5516-afaf-4d5687028026","sourceKey":"bank:AMS101:M101-T7N-067","parentItemId":null,"revision":1,"payload":{"prompt":"In the Big Five model, a person who is good-natured, cooperative and trusting is high on:","options":["Agreeableness","Openness","Conscientiousness","Extraversion"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Agreeableness covers being good-natured, cooperative and trusting. Option D, extraversion, is about being sociable, talkative and assertive."}},{"itemId":"5f12be38-eb53-5f35-8e16-31329c856c32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ebd81ae3-0f8b-561f-b1b6-e2db73a611ad","sourceKey":"bank:AMS101:M101-T7N-068","parentItemId":null,"revision":1,"payload":{"prompt":"Which Big Five trait describes a person who is tense, anxious and insecure?","options":["Introversion","Neuroticism","Agreeableness","Openness"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Neuroticism describes being tense, anxious and insecure; its opposite end is emotional stability. Option A, introversion, is the opposite of extraversion on the MBTI social interaction dimension, not a Big Five trait about anxiety."}},{"itemId":"fc4e9d6e-b443-541c-9345-289adb458dff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f6d17528-1319-5a89-9e40-7f62132f5c23","sourceKey":"bank:AMS101:M101-T7N-069","parentItemId":null,"revision":1,"payload":{"prompt":"In some versions of the Big Five, neuroticism is replaced by its opposite end. That opposite is:","options":["Emotional stability","High self-esteem","Extraversion","Conscientiousness"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Emotional stability (being calm and secure) is the opposite end of neuroticism; they are the same trait seen from opposite ends. Option C, extraversion, is a separate Big Five trait about sociability."}},{"itemId":"b56bdcf1-cfe7-5328-8f80-9208a6acdce3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98a0fd04-e9c9-513c-91fd-b46870f6ab0d","sourceKey":"bank:AMS101:M101-T7N-070","parentItemId":null,"revision":1,"payload":{"prompt":"Which Big Five trait is most consistently linked to job performance?","options":["Openness","Agreeableness","Conscientiousness","Extraversion"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Conscientiousness, being responsible, dependable and achievement-oriented, is the trait most consistently linked to job performance. Option D, extraversion, may help in social jobs, but it is not the trait most consistently tied to performance."}},{"itemId":"bea900d6-d729-5c17-9294-7ad4d7ffbcbb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"becd9e48-3f15-54f3-90cc-453d926fd014","sourceKey":"bank:AMS101:M101-T7N-071","parentItemId":null,"revision":1,"payload":{"prompt":"The memory aid OCEAN is used to remember:","options":["Holland's six personality types","The Big Five personality traits","The four MBTI dimensions","The five dimensions of emotional intelligence"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"OCEAN stands for openness, conscientiousness, extraversion, agreeableness and neuroticism, the Big Five traits. Option D is tempting because emotional intelligence also has five dimensions, but they are self-awareness, self-management, self-motivation, empathy and social skills."}},{"itemId":"f76ab4c7-9579-547a-9817-86361342e3e6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2845494d-5d38-519f-b788-68fd6b7e6b4a","sourceKey":"bank:AMS101:M101-T7N-072","parentItemId":null,"revision":1,"payload":{"prompt":"How many personality types does the Myers-Briggs Type Indicator (MBTI) produce?","options":["8","16","5","4"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The MBTI combines four dimensions, each with two ends, to give 16 personality types. Option D, 4, is the number of dimensions, not the number of types."}},{"itemId":"63019760-475c-5926-b914-d71a52d7cf55","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"93840f9a-ae91-5fa4-819c-01b86c1f8aad","sourceKey":"bank:AMS101:M101-T7N-073","parentItemId":null,"revision":1,"payload":{"prompt":"How many dimensions does the Myers-Briggs Type Indicator (MBTI) use?","options":["6","16","5","4"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The MBTI uses four dimensions: social interaction, preference for gathering data, preference for decision making and style of making decisions. Option B, 16, is the number of personality types those dimensions produce, and Option C, 5, is the number of Big Five traits."}},{"itemId":"c1c777e9-6aad-521a-88df-f3aa798b0d9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"73914030-f3b3-5d8a-af27-9f279c507d68","sourceKey":"bank:AMS101:M101-T7N-074","parentItemId":null,"revision":1,"payload":{"prompt":"On the MBTI, the social interaction dimension runs between:","options":["Feeling and Thinking","Extravert and Introvert","Sensing and Intuitive","Perceptive and Judgemental"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Social interaction is the Extravert (E) versus Introvert (I) dimension. Option C is preference for gathering data, Option A is preference for decision making and Option D is style of making decisions."}},{"itemId":"522e9385-1c61-5766-bb57-326a6d9b86e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"17a63f94-ad7e-56c6-a032-67e752c920ca","sourceKey":"bank:AMS101:M101-T7N-075","parentItemId":null,"revision":1,"payload":{"prompt":"On the MBTI, the Sensing (S) versus Intuitive (N) dimension reflects a person's:","options":["Preference for decision making","Style of making decisions","Social interaction","Preference for gathering data"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Sensing versus Intuitive is about how a person prefers to gather data. Option A is the Feeling versus Thinking dimension, and Option B is the Perceptive versus Judgemental dimension."}},{"itemId":"c4627cae-5615-5bb3-8f98-46c78bcc3f9a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4788187e-ad6c-59ff-8103-639de5f8961d","sourceKey":"bank:AMS101:M101-T7N-076","parentItemId":null,"revision":1,"payload":{"prompt":"On the MBTI, a person's preference for decision making is described as:","options":["Sensing or Intuitive","Extravert or Introvert","Feeling or Thinking","Internal or External"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Preference for decision making is the Feeling (F) versus Thinking (T) dimension. Option A is preference for gathering data, and Option D describes locus of control, which is not part of the MBTI."}},{"itemId":"66243195-1ba3-5d8e-9dd3-bf92d87d5432","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c1b6ae08-a8dd-504e-ba28-ce5690747fce","sourceKey":"bank:AMS101:M101-T7N-077","parentItemId":null,"revision":1,"payload":{"prompt":"On the MBTI, the Perceptive (P) versus Judgemental (J) dimension describes a person's:","options":["Style of making decisions","Preference for gathering data","Preference for decision making","Social interaction"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Perceptive versus Judgemental is the style of making decisions. Option C is tempting because it also mentions decisions, but preference for decision making is the Feeling versus Thinking dimension."}},{"itemId":"748059b7-9bcb-5f9c-a755-cf1367cc8143","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"63ccc4a5-8ac2-56e5-ac48-ab597da29ffa","sourceKey":"bank:AMS101:M101-T7N-078","parentItemId":null,"revision":1,"payload":{"prompt":"A person who believes \"I control my own fate\" has:","options":["An external locus of control","High self-monitoring","High Machiavellianism","An internal locus of control"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"An internal locus of control is the belief that you control your own fate. Option A, an external locus, is the belief that luck, chance or other people control your fate."}},{"itemId":"bdb5d711-76c4-5729-8b7b-04faac08adf1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"309c4328-10fa-5609-a42c-8783ab76167e","sourceKey":"bank:AMS101:M101-T7N-079","parentItemId":null,"revision":1,"payload":{"prompt":"Chidi, a sales officer at a bank in Lagos, missed his target and says it was because of bad luck and his boss's unfair allocation of customers. Chidi most likely has:","options":["An internal locus of control","A proactive personality","An external locus of control","High self-esteem"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"People with an external locus of control believe luck, chance or others control their fate, and they blame bosses or luck for poor results. Option A would lead Chidi to see the missed target as the result of his own actions."}},{"itemId":"f6b1d13f-8cb4-51a1-aef6-b0ed69c47e9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb185e61-8d9a-585c-9026-baa9143bb0b2","sourceKey":"bank:AMS101:M101-T7N-080","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with people who have an external locus of control, people with an internal locus of control tend to be:","options":["More open to outside influence","More likely to behave the same way in every situation","More satisfied with their jobs and more involved in them","Less satisfied and more likely to blame others"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Internals are more satisfied with their jobs and more involved. Option D describes externals, Option A describes people with low self-esteem, and Option B describes low self-monitors."}},{"itemId":"05ee7076-787c-58b8-848b-dacc99fb3eca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48e0a000-7cc9-5592-b2e9-7337c24e1ef8","sourceKey":"bank:AMS101:M101-T7N-081","parentItemId":null,"revision":1,"payload":{"prompt":"A person who is pragmatic, keeps emotional distance and believes that ends can justify means is high in:","options":["Machiavellianism","Risk-taking","Self-monitoring","Conscientiousness"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Machiavellianism ('Mach') describes someone who is pragmatic, emotionally distant and believes the ends justify the means. Option C, self-monitoring, is the ability to adjust behaviour to the situation, which is a different trait."}},{"itemId":"c6cc42ac-7161-5848-9b1f-d2406fe6468d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"457e1c70-9bfc-5065-a010-c5d4f7c4265e","sourceKey":"bank:AMS101:M101-T7N-082","parentItemId":null,"revision":1,"payload":{"prompt":"High Machiavellians are most likely to do well in jobs that:","options":["Involve working alone with no contact with others","Require bargaining or reward winning, such as sales or negotiating","Require following fixed routines with no room for judgement","Depend mainly on cooperation and trust"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"High Machs do well in jobs that need bargaining or that reward winning, such as sales or negotiating. Option D fits agreeable people better, since High Machs keep emotional distance and are pragmatic rather than trusting."}},{"itemId":"81ca31f0-8b42-5fbd-9fbb-55600224d0e4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9f615683-b806-5766-9df0-185f8590b627","sourceKey":"bank:AMS101:M101-T7N-083","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which people like or dislike themselves is called:","options":["Locus of control","Self-awareness","Self-esteem","Self-monitoring"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Self-esteem is how much people like or dislike themselves. Option D, self-monitoring, is the ability to adjust behaviour to the situation, and Option B, self-awareness, is a dimension of emotional intelligence."}},{"itemId":"4c14c2a6-8578-5586-98ad-ce3131c92820","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f3b98337-c501-5758-b7e5-9a5d17fc6098","sourceKey":"bank:AMS101:M101-T7N-084","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about self-esteem is correct?","options":["People with low self-esteem prefer unconventional jobs","People with low self-esteem are more open to outside influence","People with high self-esteem avoid risk in their job choices","Self-esteem is the ability to adjust behaviour to the situation"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Low self-esteem people are more open to outside influence. High self-esteem people take more risks in job choice and like unconventional jobs, so Options C and A reverse the pattern, and Option D defines self-monitoring."}},{"itemId":"6d49cdb7-a16e-555b-ba85-9615e51c4fdb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d3351ffc-5654-5c67-8f47-f47f27868590","sourceKey":"bank:AMS101:M101-T7N-085","parentItemId":null,"revision":1,"payload":{"prompt":"Funmi, a marketing executive in Lagos, is formal and reserved with senior clients, lively at staff parties, and patient with junior staff, changing her behaviour to suit each situation. She is best described as:","options":["A high self-monitor","A person with an external locus of control","A low self-monitor","A high Machiavellian"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"High self-monitors adjust their behaviour to each situation and can show a different face in public. Option C, a low self-monitor, behaves the same way everywhere."}},{"itemId":"e95e742e-1f2f-5b12-a04e-3fdb998cd762","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e7e2639-24d2-5819-85c7-4f689e764c66","sourceKey":"bank:AMS101:M101-T7N-086","parentItemId":null,"revision":1,"payload":{"prompt":"A factory manager in Ota regularly makes quick decisions based on very little information. In terms of personality, he is:","options":["Low in self-esteem","A low self-monitor","A high risk-taker","Low in conscientiousness"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Managers who take quick decisions on little information are high risk-takers; risk-taking is the willingness to take chances. Option B, self-monitoring, is about adjusting behaviour to situations, not about how much information a person needs before deciding."}},{"itemId":"ddbeecc7-867d-5cd7-b25a-5629ee4df96f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fb2e479f-a0cb-538d-90d4-a07b0d909465","sourceKey":"bank:AMS101:M101-T7N-087","parentItemId":null,"revision":1,"payload":{"prompt":"A person who spots opportunities, shows initiative, takes action and keeps going until meaningful change happens has:","options":["High agreeableness","A proactive personality","An external locus of control","High self-monitoring"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A proactive personality spots opportunities, shows initiative, acts and persists until change happens. Option C is wrong because externals believe outside forces control their fate, which is the opposite of driving change yourself."}},{"itemId":"ba09fb92-9293-5328-9256-563ba25b3c4c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"517c28fb-d4b9-59b9-8f94-2e1df4f724f4","sourceKey":"bank:AMS101:M101-T7N-088","parentItemId":null,"revision":1,"payload":{"prompt":"The ability to notice and manage emotional cues and information is called:","options":["Emotional intelligence","Perception","Self-monitoring","Empathy"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Emotional intelligence (EI) is the ability to notice and manage emotional cues and information. Option D, empathy, is only one of EI's five dimensions, and Option C, self-monitoring, is about adjusting behaviour to situations."}},{"itemId":"8091b87c-bc6c-56a1-8818-cd84274b1a79","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8bb26a77-78be-50fd-bb1c-29a133aee2ed","sourceKey":"bank:AMS101:M101-T7N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a dimension of emotional intelligence?","options":["Social skills","Self-awareness","Conscientiousness","Empathy"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The five dimensions of EI are self-awareness, self-management, self-motivation, empathy and social skills. Conscientiousness is one of the Big Five personality traits, not an EI dimension."}},{"itemId":"0838606c-a8b3-5b11-a72d-66344558a9eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a06a5345-cbc0-582c-a19c-48b929e450e1","sourceKey":"bank:AMS101:M101-T7N-090","parentItemId":null,"revision":1,"payload":{"prompt":"How many dimensions of emotional intelligence are there?","options":["Five","Three","Four","Six"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Emotional intelligence has five dimensions: self-awareness, self-management, self-motivation, empathy and social skills. Option C, four, is the number of MBTI dimensions."}},{"itemId":"b55509ca-f10e-541c-bedd-11226fd22446","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fbccb4e9-5d39-516d-ace6-9e9277b9a959","sourceKey":"bank:AMS101:M101-T7N-091","parentItemId":null,"revision":1,"payload":{"prompt":"Emotional intelligence matters at all levels of an organization, but it is especially important in jobs that:","options":["Involve mainly routine machine work","Need a lot of social interaction","Require little decision making","Are done entirely alone"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"EI matters for success at all levels, especially in jobs that need a lot of social interaction, because those jobs depend on reading and managing emotions. Options A and D describe jobs with little contact with others, where EI matters less."}},{"itemId":"028a436d-cf8f-5cf2-9a00-9c3b37ef9dd2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85a25552-db77-51bb-acd5-885b2251be18","sourceKey":"bank:AMS101:M101-T7N-092","parentItemId":null,"revision":1,"payload":{"prompt":"The theory that job satisfaction is highest and turnover lowest when a person's personality matches the job is associated with:","options":["John Holland","Leon Festinger","Elton Mayo","B. F. Skinner"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Holland's personality-job fit theory holds that satisfaction is highest and turnover lowest when personality and job match. Option B, Festinger, proposed cognitive dissonance, and Option D, Skinner, is linked with operant conditioning."}},{"itemId":"c7e4ca9e-fb26-5d23-9482-3652fde0b638","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba28f67c-71c0-5f2a-8a63-31bbe9aff157","sourceKey":"bank:AMS101:M101-T7N-093","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of Holland's six personality types?","options":["Realistic","Enterprising","Investigative","Conscientious"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Holland's six types are realistic, investigative, social, conventional, enterprising and artistic. 'Conscientious' sounds similar to 'conventional', but conscientiousness is a Big Five trait, not a Holland type."}},{"itemId":"66a6eb7a-98a2-562b-9c4a-6c5c6611f37e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d6272c9c-9bd0-5f59-b351-66fee863eea2","sourceKey":"bank:AMS101:M101-T7N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about personality across cultures is correct?","options":["The Big Five appear across many cultures, while locus of control differs between cultures","Locus of control is the same in all cultures, while the Big Five differ","Personality traits have no link with culture at all","Neither the Big Five nor locus of control appears outside one culture"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The Big Five traits appear across many cultures, but locus of control differs because some cultures believe more strongly that people can control their environment. Option B reverses the two."}},{"itemId":"ab1d57f7-4aac-52c9-8a38-626f1ead52ea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b94f1fb2-214f-597f-a58b-22b804665568","sourceKey":"bank:AMS101:M101-T7N-095","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which we give meaning to our environment by organizing and interpreting sensory impressions is called:","options":["Attribution","Perception","Learning","Attitude"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Perception is the process of giving meaning to our environment by organizing and interpreting sensory impressions. Option A, attribution, is about judging the causes of people's behaviour, and Option C, learning, is a relatively permanent change in behaviour from experience."}},{"itemId":"4dee4ab3-8835-52ff-b1d5-01b83c7488a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a31e7df-95b3-5572-87eb-ca82e7fa6d64","sourceKey":"bank:AMS101:M101-T7N-096","parentItemId":null,"revision":1,"payload":{"prompt":"The three factors that influence perception are the:","options":["Perception, emotions and religion","Cognitive, affective and behavioural components","Perceiver, the target and the situation","Distinctiveness, consensus and consistency"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Perception is shaped by the perceiver, the target being perceived and the situation. Option D gives the three factors of attribution theory, and Option A gives the factors that influence personality."}},{"itemId":"cc2ef053-9439-570f-8b18-5e39361379f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c41008f7-a89a-5988-8957-138426e139f5","sourceKey":"bank:AMS101:M101-T7N-097","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three factors that influence perception?","options":["The perceiver","The situation","Consensus","The target"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Perception depends on the perceiver, the target and the situation. Consensus is one of the three factors in attribution theory, not a factor of perception."}},{"itemId":"c88cf8d9-2dec-5ce1-8212-db4342c10225","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab87062a-20d5-5ab6-b07b-ce5b34a04046","sourceKey":"bank:AMS101:M101-T7N-098","parentItemId":null,"revision":1,"payload":{"prompt":"Two supervisors at a Lagos hospital watch the same nurse handle a patient and form very different views of her performance. This is best explained by differences in:","options":["The hospital's formal structure","The nurse's locus of control","The perceivers' attitudes, interests, experience and expectations","The supervisors' organizational commitment"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Two people can see the same thing and perceive it differently because of the perceiver's attitudes, interests, experience and expectations. Option B is about the nurse's own beliefs about control, which would not explain why the two observers disagree."}},{"itemId":"78dbb157-5228-5bd2-bbd3-8ef0187bd72b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ebf2d3b1-1b37-50af-ace2-6a115f21dec2","sourceKey":"bank:AMS101:M101-T7N-099","parentItemId":null,"revision":1,"payload":{"prompt":"The theory that explains how we judge people differently depending on whether we see the cause of their behaviour as internal or external is called:","options":["Cognitive dissonance theory","Social learning theory","Personality-job fit theory","Attribution theory"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Attribution theory explains how we judge people depending on whether we attribute their behaviour to internal causes (under their control) or external causes (forced by the situation). Option B is about learning by observation and experience, and Option A is about inconsistency between attitudes and behaviour."}},{"itemId":"94716953-7021-5102-abc4-6378d331c1ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0b0ca32-b316-5492-aa2c-247840cc97ae","sourceKey":"bank:AMS101:M101-T7N-100","parentItemId":null,"revision":1,"payload":{"prompt":"Attribution theory uses which three factors to decide whether behaviour is internally or externally caused?","options":["Distinctiveness, consensus and consistency","Selectivity, stereotyping and halo effect","Perceiver, target and situation","Importance, influence and rewards"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The three attribution factors are distinctiveness, consensus and consistency. Option C lists the factors that influence perception, Option B lists shortcuts for judging others, and Option D lists factors in reducing cognitive dissonance."}},{"itemId":"c6e28dcc-f776-5c62-9544-204aaec62284","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"64a8b3d3-9e64-5bef-b6b6-16b853a4b6b6","sourceKey":"bank:AMS101:M101-T7N-101","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, asking whether a person acts differently in different situations (whether the behaviour is unusual for him or her) concerns:","options":["Selectivity","Distinctiveness","Consensus","Consistency"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Distinctiveness asks whether the behaviour is unusual for that person across different situations. Option C, consensus, compares the person with others in the same situation, and Option D, consistency, looks at the person's behaviour over time."}},{"itemId":"230584c1-f74d-5127-a8b6-5f8929bfb3fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85d293ff-3d26-5027-8e04-883ea8331c6b","sourceKey":"bank:AMS101:M101-T7N-102","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, asking whether others in the same situation behave the same way concerns:","options":["Assumed similarity","Consensus","Consistency","Distinctiveness"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Consensus asks whether other people in the same situation act the same way; if they do (high consensus), the behaviour is judged external. Option C, consistency, asks whether the same person behaves this way over time."}},{"itemId":"96fde4a9-38ef-5ec7-8b95-254a19f71b5d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89d58193-d09a-5334-b6fe-eb735ef0b74b","sourceKey":"bank:AMS101:M101-T7N-103","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, asking whether a person behaves the same way over time concerns:","options":["Consistency","Distinctiveness","Consensus","Stereotyping"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Consistency asks whether the person behaves this way regularly over time; high consistency points to an internal cause. Option C, consensus, compares the person with others in the same situation rather than with his or her own past behaviour."}},{"itemId":"bd97f4b0-1e5e-56e5-8d7c-e943618b081a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a4cfd90-0e07-5e20-87bb-52bc4e35357b","sourceKey":"bank:AMS101:M101-T7N-104","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, high consistency in a person's behaviour leads observers to judge the behaviour as:","options":["Internally caused","Caused by group norms","Externally caused","Caused by the situation"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"When a person behaves the same way over time (high consistency), observers attribute the behaviour to internal causes under the person's control. High distinctiveness and high consensus point to external causes, which is why Options C and D are wrong here."}},{"itemId":"bd7400be-0229-5e31-9ab5-cbbc9b5bee53","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1401b3e-695e-5274-95f8-1114af08f0f2","sourceKey":"bank:AMS101:M101-T7N-105","parentItemId":null,"revision":1,"payload":{"prompt":"In attribution theory, if everyone in the same situation behaves the same way (high consensus), the behaviour is likely to be judged as:","options":["A result of high consistency","Internally caused","A sign of low self-esteem","Externally caused"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"High consensus means others in the same situation act the same way, which suggests the situation, not the person, caused the behaviour, so it is judged external. Option B would follow from high consistency, not high consensus."}},{"itemId":"88130328-e8aa-5ac9-850d-361acc30361f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a4d9951-b1b2-585e-bd46-a676ddaaa733","sourceKey":"bank:AMS101:M101-T7N-106","parentItemId":null,"revision":1,"payload":{"prompt":"Emeka, a clerk at a bank in Lagos, comes in late. All his colleagues arrive on time, Emeka is late most days, and he is also late for church and social events. How is his manager likely to explain his lateness?","options":["As externally caused","As a result of high consensus","As internally caused","As a result of high distinctiveness"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Low consensus (others are on time), high consistency (often late) and low distinctiveness (late in other settings too) all point to an internal cause. Options B and D are wrong because consensus and distinctiveness are both low in this case."}},{"itemId":"b1212987-169e-5963-9ea6-12254455558c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e76b632-2708-57b7-aa54-2a209171f82c","sourceKey":"bank:AMS101:M101-T7N-107","parentItemId":null,"revision":1,"payload":{"prompt":"When judging the behaviour of others, the tendency to underestimate the influence of external factors and overestimate internal factors is called:","options":["Self-serving bias","Assumed similarity","The fundamental attribution error","The halo effect"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The fundamental attribution error is the tendency, when judging others, to give too little weight to outside factors and too much to internal ones. Option A, self-serving bias, is about how we explain our own successes and failures, not other people's behaviour."}},{"itemId":"4ae9ecc5-44b6-5ab6-989a-6eb439fa36dd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5db9cd1c-0f6d-5ff5-8637-c3225c27600a","sourceKey":"bank:AMS101:M101-T7N-108","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency to credit our own successes to internal factors such as ability and effort, while blaming our failures on external factors such as luck, is called:","options":["Fundamental attribution error","Cognitive dissonance","Halo effect","Self-serving bias"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Self-serving bias is crediting our own success to ability or effort and blaming our failures on outside factors. Option A, the fundamental attribution error, concerns how we judge other people, not ourselves."}},{"itemId":"89433971-000e-5d57-81d8-cfe8184eb6fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"338eaf5b-8c19-54ff-8528-4c73e7a623be","sourceKey":"bank:AMS101:M101-T7N-109","parentItemId":null,"revision":1,"payload":{"prompt":"When her branch beat its targets, a bank manager in Lagos said it was due to her hard work and skill. When the branch missed its targets the next year, she blamed the poor economy. This illustrates:","options":["Fundamental attribution error","Stereotyping","Self-serving bias","Selectivity"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Taking credit for success (internal factors) and blaming failure on outside conditions (external factors) is self-serving bias. Option A would involve judging someone else's behaviour, not her own results."}},{"itemId":"775ec2d1-a790-52c0-9b8c-01e865cd64fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dcb285cf-4f0b-55f8-b6e0-6c5f10e3b624","sourceKey":"bank:AMS101:M101-T7N-110","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor in Ota decides that a new worker missed a delivery deadline because he is lazy, without considering that a truck breakdown delayed the goods. The supervisor is making:","options":["The halo effect","Self-serving bias","Assumed similarity","The fundamental attribution error"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Blaming another person's poor result on internal causes (laziness) while ignoring outside factors (the truck breakdown) is the fundamental attribution error. Option B, self-serving bias, applies to explaining one's own successes and failures."}},{"itemId":"c2958824-28a0-5d7b-bfd7-f1e4d1e147d3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"57408c61-e174-5bf4-8aa5-b39ad7c5be47","sourceKey":"bank:AMS101:M101-T7N-111","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the shortcuts people use in judging others?","options":["Halo effect","Stereotyping","Selectivity","Consistency"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The four shortcuts are selectivity, assumed similarity, stereotyping and the halo effect. Consistency is one of the three factors in attribution theory, not a shortcut."}},{"itemId":"e9d5d4d4-8136-5e79-a9fa-e754a223f262","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fa76e485-d311-52b4-af12-f51f402c61bd","sourceKey":"bank:AMS101:M101-T7N-112","parentItemId":null,"revision":1,"payload":{"prompt":"Assuming that other people are like us is a judging shortcut also known as the 'like me' effect. Its formal name is:","options":["Stereotyping","Selectivity","Halo effect","Assumed similarity"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Assumed similarity, or the 'like me' effect, is assuming that others are like us. Option A, stereotyping, judges a person by our view of the group he or she belongs to, not by our own characteristics."}},{"itemId":"1c10e499-acb7-5e3a-bfff-a1bb84f38bb3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d52cb97-082b-58bd-9fde-f50cb072ea60","sourceKey":"bank:AMS101:M101-T7N-113","parentItemId":null,"revision":1,"payload":{"prompt":"During interviews at a firm in Lagos, a manager rates a candidate highly on every quality simply because the candidate is very good-looking. This is an example of:","options":["Assumed similarity","The halo effect","Stereotyping","Selectivity"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The halo effect is forming a general impression of someone from a single characteristic, such as looks or intelligence. Option C, stereotyping, would involve judging the candidate by a group he or she belongs to."}},{"itemId":"ba70d3ed-afb8-5604-82a9-009a5982d76c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9477ad26-51cb-51f1-befe-b64ff1bcefe6","sourceKey":"bank:AMS101:M101-T7N-114","parentItemId":null,"revision":1,"payload":{"prompt":"A hiring officer assumes that a candidate will be poor at numbers simply because of the group the candidate belongs to, without assessing the candidate's actual skills. This judging shortcut is:","options":["Self-serving bias","Selectivity","Halo effect","Stereotyping"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Stereotyping is judging someone on the basis of our view of the group he or she belongs to. Option C, the halo effect, forms a general impression from one personal characteristic rather than from group membership."}},{"itemId":"cdd958f4-0c93-5ec8-bfa6-5cd0b85b8ca1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"af133fbc-449e-5b54-9b9e-1bdd225be730","sourceKey":"bank:AMS101:M101-T7N-115","parentItemId":null,"revision":1,"payload":{"prompt":"Taking in only bits and pieces of what we observe, based on our interests, background and attitudes, is the judging shortcut called:","options":["Stereotyping","Halo effect","Assumed similarity","Selectivity"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Selectivity means we absorb only parts of what we observe, filtered by our interests, background and attitudes. Option C, assumed similarity, is assuming others are like us."}},{"itemId":"e1274c89-6b0e-57de-9f1a-8b6404cc6058","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"56f85e40-b670-5a88-bc5f-22a1cfcf8ebf","sourceKey":"bank:AMS101:M101-T7N-116","parentItemId":null,"revision":1,"payload":{"prompt":"Any relatively permanent change in behaviour that occurs as a result of experience is called:","options":["Perception","Learning","Shaping","Socialization"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Learning is any relatively permanent change in behaviour that results from experience. Option C, shaping, is a method managers use to build up learning in steps, not the definition of learning itself."}},{"itemId":"6a2db6c0-be76-5171-8bb4-678b721d2ed4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"69a5fe7e-c254-5de5-a260-6451f640a851","sourceKey":"bank:AMS101:M101-T7N-117","parentItemId":null,"revision":1,"payload":{"prompt":"The theory that behaviour is a function of its consequences, known as operant conditioning, is associated with:","options":["B. F. Skinner","John Holland","Leon Festinger","Hugo Munsterberg"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"B. F. Skinner developed operant conditioning, which holds that behaviour is a function of its consequences. Option C, Festinger, proposed cognitive dissonance theory."}},{"itemId":"761310a0-7b50-58be-8281-eb7975ac4bb9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a0704876-aa80-5e1e-96f5-581914125c83","sourceKey":"bank:AMS101:M101-T7N-118","parentItemId":null,"revision":1,"payload":{"prompt":"The learning theory which holds that behaviour is a function of its consequences is:","options":["Operant conditioning","Social learning theory","Cognitive dissonance theory","Attribution theory"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Operant conditioning says people behave in ways that bring desired consequences and avoid undesired ones, so behaviour is a function of its consequences. Option B, social learning theory, stresses learning by observing others and through direct experience."}},{"itemId":"fcc58f71-76b3-5ed5-9a78-71ec86fb1afb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"60059675-cbdf-5906-8326-1527321542f0","sourceKey":"bank:AMS101:M101-T7N-119","parentItemId":null,"revision":1,"payload":{"prompt":"The theory that people learn by observing others and through direct experience is called:","options":["Operant conditioning","Personality-job fit theory","Attribution theory","Social learning theory"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Social learning theory says people learn both by watching others and through their own direct experience. Option A, operant conditioning, focuses on consequences that follow a behaviour rather than on observing others."}},{"itemId":"af44babe-81a2-5e85-937b-95598f2a9df5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4f11f479-fd25-5e5e-bf3e-05f3a9ab9e30","sourceKey":"bank:AMS101:M101-T7N-120","parentItemId":null,"revision":1,"payload":{"prompt":"Social learning depends on four processes. Which of the following is NOT one of them?","options":["Attentional processes","Extinction","Motor reproduction processes","Retention processes"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The four processes of social learning are attentional, retention, motor reproduction and reinforcement. Extinction is a method of shaping behaviour by removing a reward, not a social learning process."}},{"itemId":"a9b07aab-ac30-53dd-a1e1-ad9e1558ef12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0243e7a8-b0f7-53b8-b17a-d0fe1253bb6d","sourceKey":"bank:AMS101:M101-T7N-121","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor at a manufacturing company in Ota praises a worker each time he finishes his batch ahead of schedule, and the worker does so more often. This is:","options":["Extinction","Positive reinforcement","Punishment","Negative reinforcement"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Positive reinforcement follows a behaviour with something pleasant, such as praise, which strengthens the behaviour. Option D, negative reinforcement, also strengthens behaviour, but by removing something unpleasant rather than adding something pleasant."}},{"itemId":"3a824925-0566-5f75-8692-ff0c56a82969","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4bb600b-2927-5895-af4c-c0e34f97b005","sourceKey":"bank:AMS101:M101-T7N-122","parentItemId":null,"revision":1,"payload":{"prompt":"A manager in Lagos keeps nagging an officer about late reports, and stops nagging as soon as the officer submits on time. The officer now submits on time to avoid the nagging. This is:","options":["Punishment","Positive reinforcement","Negative reinforcement","Extinction"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Negative reinforcement strengthens a behaviour by removing something unpleasant, here the nagging. Option A, punishment, would apply a penalty to weaken a behaviour, which is not what is happening."}},{"itemId":"93a05ee7-4d51-5fac-b97b-b374248a9a88","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c754b2bb-fc2f-5e98-8979-fea1a3f502b6","sourceKey":"bank:AMS101:M101-T7N-123","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes negative reinforcement from punishment?","options":["They are two names for the same method","Both weaken behaviour, but punishment is harsher","Negative reinforcement strengthens behaviour by removing something unpleasant; punishment weakens behaviour","Negative reinforcement weakens behaviour; punishment strengthens it"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Negative reinforcement is not punishment: it strengthens behaviour by taking away something unpleasant, while punishment applies a penalty to weaken behaviour. Option B is the common trap of treating negative reinforcement as a form of punishment."}},{"itemId":"f588e2b2-f58c-5a0a-a0f1-85946e08af35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b9e31540-9937-53b7-87a9-073f8932b43d","sourceKey":"bank:AMS101:M101-T7N-124","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Lagos suspends a cleaner without pay for repeatedly ignoring safety rules. Which method of shaping behaviour is being used?","options":["Extinction","Positive reinforcement","Negative reinforcement","Punishment"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Punishment applies a penalty, such as suspension without pay, to weaken an undesired behaviour. Option C is the classic trap: negative reinforcement removes something unpleasant to strengthen a behaviour."}},{"itemId":"57ee726d-bff7-5e6f-b652-833da681a86f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6591f549-2de0-575f-bc7b-96c10b8df6ab","sourceKey":"bank:AMS101:M101-T7N-125","parentItemId":null,"revision":1,"payload":{"prompt":"Removing the reward that has been keeping a behaviour going, so that the behaviour weakens, is called:","options":["Adjourning","Negative reinforcement","Punishment","Extinction"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Extinction weakens behaviour by withdrawing the reward that kept it going. Option C, punishment, also weakens behaviour, but by applying a penalty rather than removing a reward."}},{"itemId":"1ee4d95b-cb01-5419-842e-221cec47ac21","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be155d0f-e0c6-5062-81c9-c970d852759b","sourceKey":"bank:AMS101:M101-T7N-126","parentItemId":null,"revision":1,"payload":{"prompt":"Which two methods of shaping behaviour weaken behaviour?","options":["Punishment and extinction","Positive reinforcement and negative reinforcement","Negative reinforcement and punishment","Positive reinforcement and extinction"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Punishment and extinction both weaken behaviour, while positive and negative reinforcement both strengthen it. Option C is the common mistake of treating negative reinforcement as if it weakens behaviour."}},{"itemId":"1400ffc9-e0e9-5314-b69e-76c3888909d6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"18139bb3-a508-5d23-915e-8586bbecba0b","sourceKey":"bank:AMS101:M101-T7N-127","parentItemId":null,"revision":1,"payload":{"prompt":"Guiding learning in graduated steps by systematically reinforcing each step that moves a person closer to the desired behaviour is called:","options":["Social learning","Self-monitoring","Operant conditioning","Shaping behaviour"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Shaping behaviour means reinforcing each small step that brings a person closer to the desired behaviour. Option C, operant conditioning, is the broader theory that behaviour is a function of its consequences, not the step-by-step method itself."}},{"itemId":"842d8457-1538-51ea-ae28-d789dc6f6bfe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3cd59f89-c4a1-5539-9f91-788949a6cfdb","sourceKey":"bank:AMS101:M101-T7N-128","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main lesson for managers from learning theories?","options":["Focus only on what they say, since staff ignore what managers do","Rely mainly on punishment, because it changes behaviour fastest","Reward the behaviour they want and model it themselves, because staff learn from what managers do","Avoid rewards, because they weaken desired behaviour"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Managers should reward the behaviours they want and model those behaviours, because staff learn from what managers do and not only from what they say. Option A is wrong because social learning shows employees learn by observing others, including their managers."}},{"itemId":"af2b99d8-eba8-51ed-a22a-7812495f6dec","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ea6cb09-b470-542b-b049-8d4e085802fa","sourceKey":"bank:AMS101:M101-T7N-129","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following are identified as current issues in organizational behaviour?","options":["Programmed and non-programmed decisions","Generational differences at work and managing negative behaviour","Span of control and chain of command","Lighting levels and working hours"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Two current OB issues are generational differences in the workplace and managing negative behaviour such as workplace misbehaviour. Option D relates to the early Hawthorne lighting experiments, not current issues."}},{"itemId":"d6b89e41-4009-5033-baa1-a3531b4b6203","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d14f01de-bdbf-57bf-9d95-1ba0b4a4b83b","sourceKey":"bank:AMS101:M101-T7N-130","parentItemId":null,"revision":1,"payload":{"prompt":"Two or more interacting and interdependent individuals who come together to achieve specific goals form a:","options":["Command chain","Work team","Department","Group"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A group is two or more interacting and interdependent individuals who come together to achieve specific goals. Option B, a work team, goes further: its members work intensely on a common goal with positive synergy, mutual accountability and complementary skills."}},{"itemId":"4f3c6a5a-575f-5bea-8c4b-54c6abe4331f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f3892de4-5ef1-5bd3-85f4-230abaf6ff6a","sourceKey":"bank:AMS101:M101-T7N-131","parentItemId":null,"revision":1,"payload":{"prompt":"Which feature describes informal groups rather than formal groups?","options":["Members have assigned roles and responsibilities","They are officially recognised by the organization","They form spontaneously, without official designation","They have a defined hierarchy, rules and procedures"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Informal groups are spontaneous, unstructured, based on relationships and not officially recognised. Options D, A and B are all features of formal groups."}},{"itemId":"44289c2f-dcf7-5e7a-a956-66692da171c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2027df9-f416-56a8-b0b5-b27ceadf6482","sourceKey":"bank:AMS101:M101-T7N-132","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of formal groups?","options":["They are based on personal connections and social needs","They have a defined hierarchy, rules and procedures","They are formed for a specific organizational purpose","They are officially recognised by the organization"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Being based on relationships, personal connections and social needs is a feature of informal groups. Formal groups are purposeful, structured, have assigned roles and are officially recognised, as Options C, B and D state."}},{"itemId":"3dc17096-7df1-5955-be1b-ece2d3856d08","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"16d226d6-7c2f-595f-9604-0a4745b53e03","sourceKey":"bank:AMS101:M101-T7N-133","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a university department in Lagos who regularly meet for lunch and chat because they enjoy each other's company form a:","options":["Informal group","Command group","Cross-functional team","Task group"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A friendship group like this forms naturally, has no official designation and is based on personal relationships, so it is an informal group. Options B and D are the two types of formal group, which the organization sets up for its own purposes."}},{"itemId":"442de4ce-4dbf-5d0a-8fdf-b80b503029a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de017d5e-3296-5386-9379-c2ccb9d28860","sourceKey":"bank:AMS101:M101-T7N-134","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a formal group?","options":["Colleagues who meet for football after work","A friendship group of staff who eat lunch together","The finance department of a bank","A social club formed by employees"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Departments such as marketing and finance are formal groups, formed for a specific organizational purpose and officially recognised. Options B, D and A are informal groups that form spontaneously around social needs."}},{"itemId":"8684b5ab-6313-50d1-a7d8-9bea7b117f50","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"213184b1-6654-5796-bd91-05fb845ee9c6","sourceKey":"bank:AMS101:M101-T7N-135","parentItemId":null,"revision":1,"payload":{"prompt":"A formal group determined by the organization chart, made up of a supervisor and his or her direct subordinates, is a:","options":["Command group","Informal group","Self-managed team","Task group"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A command group is set by the organization's hierarchy: a supervisor and the people who report directly to him or her, following the chain of command. Option D, a task group, brings people together to complete a specific task within a set timeframe and often disbands afterwards."}},{"itemId":"cb3812e9-34d9-5921-a73b-0e3932dbf3aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5dc40219-da98-5d91-98f2-8a1716cc2c12","sourceKey":"bank:AMS101:M101-T7N-136","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Lagos brings together staff from several units to plan and complete a new patient records system within three months, after which the group will be disbanded. This is a:","options":["Task group","Command group","Informal group","Problem-solving team"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A task group is formed to complete a specific, defined task or project within a set timeframe and is often temporary. Option B, a command group, is a permanent supervisor-and-subordinates unit defined by the organization chart."}},{"itemId":"bdefb1f8-467e-5508-92d6-ce3c25357877","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"802e094f-2a53-50e3-aaf1-b288671720da","sourceKey":"bank:AMS101:M101-T7N-137","parentItemId":null,"revision":1,"payload":{"prompt":"At a manufacturing company in Ota, the production supervisor and the eight machine operators who report directly to him form a:","options":["Command group","Virtual team","Informal group","Task group"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A supervisor and his or her direct subordinates, as shown on the organization chart, make up a command group. Option D, a task group, is formed for a specific project within a set time, not by reporting lines."}},{"itemId":"580980dd-d0c0-577d-ab01-13735f742684","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a1fc529-6b29-5f56-8992-3b44fc15425b","sourceKey":"bank:AMS101:M101-T7N-138","parentItemId":null,"revision":1,"payload":{"prompt":"The two types of formal group are:","options":["Problem-solving teams and virtual teams","Command groups and task groups","Friendship groups and interest groups","Formal groups and informal groups"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Formal groups come in two types: command groups, set by the hierarchy, and task groups, formed for a specific task. Option C names informal groups, and Option A names types of work team."}},{"itemId":"776db54e-907d-523b-a5ed-c1eb008ce6b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07ec5c18-61a8-53b6-b215-211d3be3fa42","sourceKey":"bank:AMS101:M101-T7N-139","parentItemId":null,"revision":1,"payload":{"prompt":"How many stages of group development are there?","options":["Six","Four","Three","Five"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Groups develop through five stages: forming, storming, norming, performing and adjourning. Option B, four, is the number of stages a permanent group goes through, because adjourning applies only to temporary groups."}},{"itemId":"4b5d4653-84e8-5fd7-a23d-9c1347cc7158","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca79f24e-b4dc-573f-ae81-dc0de3ac1d99","sourceKey":"bank:AMS101:M101-T7N-140","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following shows the correct order of the stages of group development?","options":["Forming, storming, performing, norming, adjourning","Forming, norming, storming, performing, adjourning","Storming, forming, norming, performing, adjourning","Forming, storming, norming, performing, adjourning"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Groups first form, then go through conflict (storming), then develop cohesion (norming), then focus on the task (performing), and temporary groups finally adjourn. Option B is the most common mistake, putting norming before storming."}},{"itemId":"f3f39056-9578-5812-9593-93e14505f479","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0bc258c2-5103-538a-8dee-54e58891c3a1","sourceKey":"bank:AMS101:M101-T7N-141","parentItemId":null,"revision":1,"payload":{"prompt":"What is the third stage of group development?","options":["Norming","Performing","Storming","Forming"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The order is forming, storming, norming, performing and adjourning, so norming is the third stage. Option C, storming, is the second stage, when members fight over control."}},{"itemId":"321fd9cc-d429-53b9-9dd6-9d8c35875fdb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"83b9360c-82d7-5b98-88c7-9c3a1f77b5d2","sourceKey":"bank:AMS101:M101-T7N-142","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of group development marked by conflict over who will control the group and what it will do is:","options":["Forming","Storming","Adjourning","Norming"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Storming is the stage of intragroup conflict over who controls the group and what it does, and it ends with a clear leadership hierarchy. Option A, forming, is marked by uncertainty as people join, not by open conflict over control."}},{"itemId":"0f94e34f-0749-539d-9a09-aeb81c4092c3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a11cfe8-5e5e-51ee-a0c7-ae3694eeaf6c","sourceKey":"bank:AMS101:M101-T7N-143","parentItemId":null,"revision":1,"payload":{"prompt":"The first stage of group development, in which people join and the group defines its purpose, structure and leadership amid much uncertainty, is:","options":["Storming","Performing","Forming","Norming"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Forming is when people join the group and work out its purpose, structure and leadership, with a lot of uncertainty. Option A, storming, comes next and involves conflict over control."}},{"itemId":"09d917cc-6522-5c7b-84fc-27fd61616556","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ae72cac-be68-594b-8c8c-ca7d1fc044a6","sourceKey":"bank:AMS101:M101-T7N-144","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of group development in which close relationships and cohesiveness develop and shared expectations are set is:","options":["Forming","Norming","Storming","Performing"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"In norming, members develop close relationships and cohesiveness and agree on shared expectations. Option D, performing, follows once that structure is accepted and energy moves to the task."}},{"itemId":"593dfc18-6cbd-521e-9dca-8659292c250e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"262440ed-ac92-5d4e-acfb-de9e7d59a77c","sourceKey":"bank:AMS101:M101-T7N-145","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of group development in which the group structure is accepted and energy goes into the task is:","options":["Norming","Storming","Adjourning","Performing"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"In performing, the structure is fully functional and accepted, so members put their energy into the task. Option A, norming, is the earlier stage in which that structure and cohesion are still being built."}},{"itemId":"39b87538-1bcf-5778-b68e-661db6fa9a0a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8518670c-4c20-5736-b571-b2a8fab0e317","sourceKey":"bank:AMS101:M101-T7N-146","parentItemId":null,"revision":1,"payload":{"prompt":"The final stage of development for temporary groups, in which they wrap up activities and prepare to break up, is:","options":["Norming","Adjourning","Storming","Performing"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Adjourning is the stage in which a temporary group, such as a task force, wraps up and prepares to break up. Option D, performing, is the last stage for permanent groups, not the wrap-up stage of temporary ones."}},{"itemId":"7b5c07b6-46f9-5bed-ae3c-3b99f10f95c9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9bba58c6-d295-53de-89f8-6acb557c2907","sourceKey":"bank:AMS101:M101-T7N-147","parentItemId":null,"revision":1,"payload":{"prompt":"For a permanent work group, which stage of group development is the last stage?","options":["Performing","Norming","Storming","Adjourning"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"For permanent groups, performing is the last stage. Option D, adjourning, applies only to temporary groups such as task forces that break up when their work is done."}},{"itemId":"88a3d2d0-3105-56b6-8aff-8cd6a31b77bd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5cc67b25-4a5d-5d9e-9c15-8e3313797ec5","sourceKey":"bank:AMS101:M101-T7N-148","parentItemId":null,"revision":1,"payload":{"prompt":"The storming stage of group development ends when:","options":["A clear leadership hierarchy has emerged","Members have agreed on the task and are fully productive","The group breaks up after finishing its task","New members first join the group"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Storming ends with a relatively clear hierarchy of leadership within the group. Option B describes performing, and Option C describes adjourning."}},{"itemId":"a565e854-8535-5fc5-a810-b78bdf02d05f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6dfeb5c6-7da2-5a30-9376-ea9945a72f6d","sourceKey":"bank:AMS101:M101-T7N-149","parentItemId":null,"revision":1,"payload":{"prompt":"Behaviour patterns expected of someone occupying a given position in a social unit are called:","options":["Status","Cohesiveness","A norm","A role"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A role is the set of behaviour patterns expected of someone in a given position. Option C, norms, are standards shared by all group members, not expectations tied to one position."}},{"itemId":"af9d9cc2-8948-5572-a200-2c27115fd66a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"89afb9b7-6cc6-5e69-b68d-e740882ebc51","sourceKey":"bank:AMS101:M101-T7N-150","parentItemId":null,"revision":1,"payload":{"prompt":"A unit head at a bank in Lagos is expected by his regional manager to cut overtime, while his staff expect him to fight for more overtime pay. He is experiencing:","options":["Social loafing","Role conflict","Cognitive dissonance","Groupthink"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Role conflict happens when an individual faces different role expectations at the same time, like a manager expected to please both the boss and his staff. Option C is about inconsistency within one person's attitudes and behaviour, not clashing expectations from others."}},{"itemId":"84fa0ffc-5238-55df-840b-a4864db2f0d0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b63a5abc-3db4-5421-9e9b-c47f9e6c256a","sourceKey":"bank:AMS101:M101-T7N-151","parentItemId":null,"revision":1,"payload":{"prompt":"Standards or expectations that are accepted and shared by a group's members are called:","options":["Roles","Status","Attitudes","Norms"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Norms are standards or expectations accepted and shared by group members. Option A, roles, are expectations attached to a particular position rather than shared by the whole group."}},{"itemId":"0edb89fe-d455-5abf-a3bf-35468b109580","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1a5607e3-e084-591e-b330-cee9d0958146","sourceKey":"bank:AMS101:M101-T7N-152","parentItemId":null,"revision":1,"payload":{"prompt":"Common group norms typically cover:","options":["The organization's formal structure","Pay and promotion policies","Work effort and performance","The choice of group leader"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Common norms cover work effort and performance, as well as dress and loyalty. Option A describes the formal structure, which is set by the organization rather than shared informally by group members."}},{"itemId":"34249a42-cab9-5907-a8e2-a650b94b2abb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"78d02949-aef9-5665-a951-9543d6b782ba","sourceKey":"bank:AMS101:M101-T7N-153","parentItemId":null,"revision":1,"payload":{"prompt":"In the Asch study, people compared line lengths after others in the room deliberately gave a wrong answer, and many went along with the wrong answer. The study shows:","options":["That people credit success to their own ability","The pressure to conform to group norms","That large groups are better at problem solving","The effect of lighting on productivity"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Asch found that many people conformed to an obviously wrong group answer, showing the strong pressure to conform to group norms. Option D relates to the start of the Hawthorne Studies, and Option A describes self-serving bias."}},{"itemId":"8aa631c6-26a4-5efe-b05c-9610cb48aa02","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7499652f-d317-53d4-9036-e06d53cd828b","sourceKey":"bank:AMS101:M101-T7N-154","parentItemId":null,"revision":1,"payload":{"prompt":"A prestige grading, position or rank within a group is called:","options":["Status","Role","Norm","Authority"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Status is a prestige grading, position or rank within a group, and it can be formal or informal. Option B, a role, is the behaviour expected in a position, not the prestige attached to it."}},{"itemId":"497facb7-18b6-54a1-bcf6-63fb404ca070","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"722ae79f-88b9-5295-9cd4-972696797bd4","sourceKey":"bank:AMS101:M101-T7N-155","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of informal status in a group?","options":["A member's education, age or skill","The size of a member's office","A member's job title","A member's position on the organization chart"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Informal status comes from things like education, age or skill. Options C and B are sources of formal status, such as titles and offices."}},{"itemId":"c4712cde-82c5-5515-ae73-a17638adba49","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b1e41d2d-20a7-59b9-b313-a40cf813cf03","sourceKey":"bank:AMS101:M101-T7N-156","parentItemId":null,"revision":1,"payload":{"prompt":"For status to work well in a group, members need to believe that:","options":["Status should be kept secret","Everyone has exactly the same status","The status hierarchy is fair","Status is based only on age"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Group members need to believe the status hierarchy is fair; if they do not, it creates problems in the group. Option B is wrong because groups naturally have different status levels, formal and informal."}},{"itemId":"c295a68f-294d-5a55-8a5b-2daa28b85766","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b14667f8-1b95-5100-a0d9-ed99031cca22","sourceKey":"bank:AMS101:M101-T7N-157","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about group size is correct?","options":["Small groups finish tasks faster, while large groups are better for problem solving and diverse input","Group size has no effect on how a group performs","Large groups finish tasks faster, while small groups give more diverse input","Small groups are always better than large groups"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Small groups complete tasks faster, while large groups (about 12 or more) are better for problem solving and getting diverse input. Option C reverses the two findings."}},{"itemId":"0fea0392-9609-531e-a7a3-e16dfe6a1429","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05504cfa-d4ce-5c52-8b1e-5e006c0f6341","sourceKey":"bank:AMS101:M101-T7N-158","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency for individuals to put in less effort when working collectively than when working alone is called:","options":["Social loafing","Absenteeism","Role conflict","Groupthink"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Social loafing is reduced individual effort when working in a group compared with working alone. Option D, groupthink, is pressure on an individual to align his or her opinion with the group, not reduced effort."}},{"itemId":"bd3192e7-2ad8-50b9-a6ae-77bb483749c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4e642a4-e26e-5172-9562-feecabff1556","sourceKey":"bank:AMS101:M101-T7N-159","parentItemId":null,"revision":1,"payload":{"prompt":"A manager in a Lagos firm notices social loafing in a large project group. The best way to reduce it is to:","options":["Make each person's contribution identifiable and measurable","Reward only the group's total output","Make the group even larger","Remove all group norms"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Social loafing happens when individual effort cannot be identified, so making each person's contribution measurable reduces it. Option B would make the problem worse, because rewarding only total output hides who did what."}},{"itemId":"86ebc74d-a873-5a50-ae4e-2e2f643dbd93","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0923a9d4-6bc0-568c-96c4-651a679a5573","sourceKey":"bank:AMS101:M101-T7N-160","parentItemId":null,"revision":1,"payload":{"prompt":"The degree to which members are attracted to a group and share its goals is called:","options":["Status","Cohesiveness","Organizational commitment","Conformity"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Cohesiveness is how far members are attracted to the group and share its goals. Option C, organizational commitment, is about identifying with the whole organization, not with a particular group."}},{"itemId":"72fe5f05-d78b-54a0-b264-91166b2ce2fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"59eb6686-5c1d-53e7-a350-7d38467ea565","sourceKey":"bank:AMS101:M101-T7N-161","parentItemId":null,"revision":1,"payload":{"prompt":"A group with high cohesiveness whose goals are aligned with the organization's goals will most likely show:","options":["A strong increase in productivity","No significant effect on productivity","A moderate increase in productivity","A decrease in productivity"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"High cohesiveness combined with goals aligned to the organization produces a strong increase in productivity. Option C, a moderate increase, is the result of low cohesiveness with aligned goals."}},{"itemId":"1b5e7cfa-f852-58db-a0e3-2064ff5b3a93","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e9fd73d1-8e19-5ac7-9fd6-f621950a5578","sourceKey":"bank:AMS101:M101-T7N-162","parentItemId":null,"revision":1,"payload":{"prompt":"A highly cohesive group whose goals are NOT aligned with the organization's goals will most likely show:","options":["A strong increase in productivity","No significant effect on productivity","A moderate increase in productivity","A decrease in productivity"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"When a highly cohesive group pursues goals that conflict with the organization's, productivity falls, because the group's strength works against the organization. Option B is the result of low cohesiveness with goals not aligned."}},{"itemId":"d0f36256-b162-531d-a510-4c84537dfa6b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dae74ecd-a476-5355-bf20-2146580d58b3","sourceKey":"bank:AMS101:M101-T7N-163","parentItemId":null,"revision":1,"payload":{"prompt":"A group with low cohesiveness but goals aligned with the organization's goals will most likely show:","options":["A strong increase in productivity","A moderate increase in productivity","No significant effect on productivity","A decrease in productivity"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Low cohesiveness with aligned goals gives a moderate increase in productivity. Option A, a strong increase, needs both high cohesiveness and aligned goals."}},{"itemId":"f520174e-d8fd-523f-a3a2-5ef9e14369c3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0fafaa54-76e2-501e-83db-6ab45106c40d","sourceKey":"bank:AMS101:M101-T7N-164","parentItemId":null,"revision":1,"payload":{"prompt":"A group with low cohesiveness and goals NOT aligned with the organization's goals will most likely show:","options":["No significant effect on productivity","A strong increase in productivity","A decrease in productivity","A moderate increase in productivity"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Low cohesiveness with goals not aligned has no significant effect on productivity. Option C, a decrease, happens when cohesiveness is high but goals are not aligned."}},{"itemId":"c5ef460a-36bc-5972-937e-154a7c1cb943","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"28edcd00-8bab-59f7-9d09-79d31f3bd337","sourceKey":"bank:AMS101:M101-T7N-165","parentItemId":null,"revision":1,"payload":{"prompt":"When a group puts heavy pressure on an individual to align his or her opinion with the opinions of the others, this is called:","options":["Cohesiveness","Social loafing","Groupthink","Role conflict"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Groupthink is the heavy pressure a group places on an individual to bring his or her opinion into line with the others. Option B, social loafing, is about reduced effort, and Option A, cohesiveness, is simply attraction to the group."}},{"itemId":"56b92d97-3c94-579a-bbf3-5760dab8df69","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"133500ba-f754-51cc-b490-53892853b2b7","sourceKey":"bank:AMS101:M101-T7N-166","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of group decision making?","options":["It increases acceptance of the solution","It is time-consuming","It provides more complete information and knowledge","It generates more diverse alternatives"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Being time-consuming is a disadvantage of group decision making. Options C, D and A are advantages, together with greater legitimacy."}},{"itemId":"1f2aba97-0fbd-573a-9dac-270d2d0b80ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ecf00fe4-d154-585b-903f-620e4d243142","sourceKey":"bank:AMS101:M101-T7N-167","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of group decision making?","options":["Greater legitimacy","More diverse alternatives","Minority domination","Greater acceptance of the solution"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Minority domination, where a few members control the outcome, is a disadvantage, along with time cost, pressure to conform and ambiguous responsibility. Options A, B and D are all advantages of deciding as a group."}},{"itemId":"dd81e3fd-af68-5307-913b-1a995d84627d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9b429075-d9b7-51d1-bce5-4e16499f7b65","sourceKey":"bank:AMS101:M101-T7N-168","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of group decision making?","options":["Ambiguous responsibility","Greater legitimacy","Minority domination","Pressure to conform"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Group decisions tend to be seen as more legitimate, which is one of their advantages along with more information, more alternatives and greater acceptance. Options A, D and C are all disadvantages."}},{"itemId":"7a54192f-eccd-5823-9a9f-2e2aadb6debf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dbe21f9a-e14c-5c76-81c4-0129c1828b73","sourceKey":"bank:AMS101:M101-T7N-169","parentItemId":null,"revision":1,"payload":{"prompt":"In group decision making, 'ambiguous responsibility' means that:","options":["Members feel pressure to agree with the majority","It is unclear which member is accountable for the final decision","The group takes too long to decide","One member dominates the discussion"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Ambiguous responsibility is the disadvantage that, because the whole group decides, no single member is clearly responsible for the outcome. Option D is minority domination and Option A is pressure to conform, which are separate disadvantages."}},{"itemId":"ba546d43-adcd-51f2-b898-e7282cfa038e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b4e4e0b6-3e98-579d-b764-6d9edc9c4023","sourceKey":"bank:AMS101:M101-T7N-170","parentItemId":null,"revision":1,"payload":{"prompt":"A group whose members work intensely on a specific, common goal using positive synergy, individual and mutual accountability, and complementary skills is a:","options":["Command group","Task group","Work team","Informal group"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A work team is defined by intense work on a common goal, positive synergy, individual and mutual accountability and complementary skills. Option B, a task group, is brought together for a defined task but does not by definition have these team features."}},{"itemId":"126f2235-a975-5ae8-a1a4-7520513632ee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ffa52ed-d583-5615-a751-90d9d5c73a86","sourceKey":"bank:AMS101:M101-T7N-171","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly contrasts groups and teams?","options":["Groups have shared goals; teams have individual goals","Groups have high interdependence; teams have limited interdependence","Groups put heavy emphasis on collaboration; teams put less","Groups have individual accountability; teams have shared accountability"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"In groups accountability is individual, while in teams it is shared. Options A, B and C reverse the real differences: teams, not groups, have shared goals, high interdependence and heavy emphasis on collaboration."}},{"itemId":"21ab2695-8bd6-5430-9e80-be631bc330c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f6716d5b-4ab4-51ca-be2d-5fd3d9208ebb","sourceKey":"bank:AMS101:M101-T7N-172","parentItemId":null,"revision":1,"payload":{"prompt":"In terms of focus, groups and teams differ because:","options":["Groups focus on individual performance; teams focus on collective performance","Both focus only on collective performance","Groups focus on collective performance; teams focus on individual performance","Both focus only on individual performance"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Groups focus on individual performance, while teams focus on collective performance. Option C reverses the difference."}},{"itemId":"1aa95c85-bf6b-5a8c-99d1-a142497d11cc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e936d0a-1533-5b25-a6b8-822ebdda2168","sourceKey":"bank:AMS101:M101-T7N-173","parentItemId":null,"revision":1,"payload":{"prompt":"How many key differences between groups and teams are commonly identified?","options":["Eight","Four","Five","Three"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"There are five differences: accountability, goals, interdependence, focus and collaboration. Option A, eight, is the number of characteristics of effective teams."}},{"itemId":"505a678f-2545-5ceb-a0c4-b7c4568af8c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4f2d5b4d-ff7b-5e16-9b7c-b0abd04ce819","sourceKey":"bank:AMS101:M101-T7N-174","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the points on which groups and teams differ?","options":["Accountability","Collaboration","Interdependence","Organization size"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Groups and teams differ on accountability, goals, interdependence, focus and collaboration. Organization size is not one of these points."}},{"itemId":"9313e8f8-a06f-5616-9bac-77c3a3a05ca8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5fca1b63-4176-57f6-8653-b9b121984af1","sourceKey":"bank:AMS101:M101-T7N-175","parentItemId":null,"revision":1,"payload":{"prompt":"Teams are said to create positive synergy. This means that:","options":["Conflict is completely removed from the team","Each member works alone towards a personal goal","The whole is greater than the sum of the parts","The team needs no leader at all"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Positive synergy means the team's combined effort produces more than the members could achieve separately; the whole is greater than the sum of the parts. Groups do not create this, so Option B, which describes individual work, is the opposite idea."}},{"itemId":"0bf250e1-0eaf-56ff-9f31-32fc88545532","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"747b0dbb-2fdb-55b8-99ca-d326499ef043","sourceKey":"bank:AMS101:M101-T7N-176","parentItemId":null,"revision":1,"payload":{"prompt":"How does leadership typically differ between groups and teams?","options":["In a group leadership is shared; in a team one leader is in charge","Both always have a single leader with full control","In a team leadership is often shared; in a group one leader is clearly in charge and delegates","Neither groups nor teams have leaders"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Team leadership is often shared among members, while a group has one leader who is clearly in charge and delegates work. Option A reverses the two."}},{"itemId":"c27e17ef-4157-5e75-a05f-dd14f8c468cf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b0f3d0e-fe7e-5b73-a83f-07e17257ce94","sourceKey":"bank:AMS101:M101-T7N-177","parentItemId":null,"revision":1,"payload":{"prompt":"How many types of work team are commonly identified?","options":["Three","Six","Five","Four"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"There are four types: problem-solving, self-managed, cross-functional and virtual teams. Option C, five, is the number of differences between groups and teams."}},{"itemId":"ddfe69d7-f54e-5d4e-9b75-8b5b689cefaf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"559e727c-234c-5b06-995e-c0e9b26f74df","sourceKey":"bank:AMS101:M101-T7N-178","parentItemId":null,"revision":1,"payload":{"prompt":"A team made up of members from the same department who meet to improve work activities or solve specific problems is a:","options":["Self-managed team","Virtual team","Problem-solving team","Cross-functional team"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A problem-solving team draws members from the same department to improve work or solve problems. Option D, a cross-functional team, draws members from different specialities or departments."}},{"itemId":"96f507a8-4b2e-50b2-b02f-8d9187ee10ea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de07e53d-980e-54d1-a79c-b2a124ecc21e","sourceKey":"bank:AMS101:M101-T7N-179","parentItemId":null,"revision":1,"payload":{"prompt":"A formal group of employees with no manager, responsible for a complete work process or segment, is a:","options":["Problem-solving team","Command group","Self-managed team","Cross-functional team"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A self-managed team operates without a manager and is responsible for a complete work process or segment. Option B, a command group, is the opposite: it is built around a supervisor and his or her direct subordinates."}},{"itemId":"9ff14bc9-973b-51a2-ae50-addd449d4ee5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b6e4b60c-8643-5b72-8844-c8ab403744c5","sourceKey":"bank:AMS101:M101-T7N-180","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos sets up a team of staff from operations, IT, marketing and legal to design a new mobile banking product. This is a:","options":["Cross-functional team","Command group","Self-managed team","Problem-solving team"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A cross-functional team brings together members from different specialities or departments. Option D, a problem-solving team, draws its members from the same department."}},{"itemId":"3ce567d2-6931-5a45-a114-04b9d8ed04fd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a22506e3-e1aa-57b5-8357-98965104982c","sourceKey":"bank:AMS101:M101-T7N-181","parentItemId":null,"revision":1,"payload":{"prompt":"A software firm has developers in Lagos, Abuja and Port Harcourt who never meet in person and work together through video calls and shared online tools. They form a:","options":["Virtual team","Cross-functional team","Informal group","Self-managed team"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"A virtual team uses technology to link members who are physically apart. Option B is about members coming from different departments, not about being linked by technology across locations."}},{"itemId":"78597e71-5d92-5e1e-9b1e-cf38c4394443","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f4602c0e-055f-5c16-925f-bd078ff594ef","sourceKey":"bank:AMS101:M101-T7N-182","parentItemId":null,"revision":1,"payload":{"prompt":"What is the key difference between a problem-solving team and a self-managed team?","options":["Problem-solving teams are linked only by technology, while self-managed teams meet face to face","Problem-solving teams draw members from different departments, while self-managed teams use one department","Problem-solving teams make suggestions but usually cannot carry them out, while self-managed teams plan, schedule, assign work and decide for themselves","Problem-solving teams have no manager, while self-managed teams report to a supervisor"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Problem-solving teams can recommend improvements but usually cannot implement them, whereas self-managed teams take full responsibility for planning, scheduling, assigning work and deciding. Option D reverses the role of the manager, and Option A describes a virtual team."}},{"itemId":"cdc1944c-840c-527a-aa6b-41f7b9fb6298","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"096088e3-1aa2-522b-b12d-81eead563bc9","sourceKey":"bank:AMS101:M101-T7N-183","parentItemId":null,"revision":1,"payload":{"prompt":"How many characteristics of effective teams are commonly identified?","options":["Six","Five","Eight","Four"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Effective teams have eight characteristics: clear goals, relevant skills, mutual trust, unified commitment, good communication, negotiating skills, appropriate leadership, and internal and external support. Option B, five, is the number of differences between groups and teams."}},{"itemId":"acb26c5f-ed2d-5021-846d-0b64de791cfd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"24a8714f-673a-5f68-a712-8fd589c7c02d","sourceKey":"bank:AMS101:M101-T7N-184","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the characteristics of effective teams?","options":["Unified commitment","Clear goals","Strict individual competition among members","Mutual trust"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Effective teams have clear goals, relevant skills, mutual trust, unified commitment, good communication, negotiating skills, appropriate leadership, and internal and external support. Strict individual competition works against the shared goals and collaboration that define teams."}},{"itemId":"45bdc69c-5221-554f-b550-3ea42e4617cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cc6fc67d-9c09-5d75-a3a4-68a2cde2155a","sourceKey":"bank:AMS101:M101-T7N-185","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the characteristics of effective teams?","options":["Minority domination","Internal and external support","High social loafing","Ambiguous responsibility"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Internal and external support is one of the eight characteristics of effective teams. Options A and D are disadvantages of group decision making, and Option C reduces group effort."}},{"itemId":"34e10eb7-0ac6-5c20-a122-ad2ac32a2e77","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6aee93b9-92e0-5f38-b6f0-8681d1e30b3f","sourceKey":"bank:AMS101:M101-T7N-186","parentItemId":null,"revision":1,"payload":{"prompt":"Perceived incompatible differences that result in interference or opposition are called:","options":["Role ambiguity","Conflict","Groupthink","Cognitive dissonance"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Conflict is perceived incompatible differences that lead to interference or opposition. Option D, cognitive dissonance, is inconsistency within a person's own attitudes or between attitudes and behaviour."}},{"itemId":"ceb7364d-3a3c-59c7-ba9a-19658b54e5ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d4c76ce7-9a98-5c24-a890-34b70ecd05b9","sourceKey":"bank:AMS101:M101-T7N-187","parentItemId":null,"revision":1,"payload":{"prompt":"How many views of conflict are commonly identified?","options":["Three","Four","Two","Five"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"There are three views of conflict: traditional, human relations and interactionist. Option D, five, is the number of conflict-handling styles."}},{"itemId":"597724af-c4ff-5c41-8808-50563a0cf59c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e32d6193-dc2f-59a2-8ada-ad5076ebd2eb","sourceKey":"bank:AMS101:M101-T7N-188","parentItemId":null,"revision":1,"payload":{"prompt":"The view that conflict is bad and must be avoided is the:","options":["Traditional view","Interactionist view","Functional view","Human relations view"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The traditional view holds that conflict is bad and must be avoided. Option D, the human relations view, sees conflict as natural and inevitable and not necessarily negative."}},{"itemId":"d91533b8-4747-5dd4-a6cc-3dc5809199c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ddc374a1-56d9-5444-8493-0e942174ff90","sourceKey":"bank:AMS101:M101-T7N-189","parentItemId":null,"revision":1,"payload":{"prompt":"The view that conflict is a natural and inevitable outcome in any group and need not be negative is the:","options":["Human relations view","Traditional view","Interactionist view","Dysfunctional view"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The human relations view says conflict is natural and inevitable and need not be negative. Option C, the interactionist view, goes further by arguing that some conflict is actually necessary for a group to perform well."}},{"itemId":"6cf44277-76f9-5101-97ef-e7bdd57a47eb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dec20897-feac-51bf-8907-2237c0fedd30","sourceKey":"bank:AMS101:M101-T7N-190","parentItemId":null,"revision":1,"payload":{"prompt":"The view that some conflict is necessary for a group to perform effectively is the:","options":["Traditional view","Human relations view","Interactionist view","Classical view"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The interactionist view holds that some conflict is necessary for a group to perform well. Option B, the human relations view, accepts conflict as natural but does not argue that it is necessary for performance."}},{"itemId":"a7da89da-5ac4-5d77-9aa7-25dd5cbfd522","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"875151fe-024e-5a3f-ac7f-86bb9d0a0965","sourceKey":"bank:AMS101:M101-T7N-191","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between functional and dysfunctional conflict?","options":["Functional conflict supports group goals and improves performance; dysfunctional conflict prevents the group from reaching its goals","Functional conflict is about relationships; dysfunctional conflict is about tasks","Functional conflict is always avoided; dysfunctional conflict is encouraged","Functional conflict occurs only in teams; dysfunctional conflict occurs only in groups"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Functional conflict supports the group's goals and improves its performance, while dysfunctional conflict stops the group from reaching its goals. Option B is wrong because relationship conflict is almost always dysfunctional, not functional."}},{"itemId":"ced2a854-1b52-5148-befe-dfc679d69953","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee53ba6b-1105-5644-9b9e-d6f839a16106","sourceKey":"bank:AMS101:M101-T7N-192","parentItemId":null,"revision":1,"payload":{"prompt":"Conflict over the content and goals of the work is called:","options":["Task conflict","Role conflict","Relationship conflict","Process conflict"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Task conflict concerns the content and goals of the work. Option D, process conflict, is about how the work gets done, and Option C, relationship conflict, is about interpersonal relationships."}},{"itemId":"38c6ef66-d84e-5ff2-bd00-f7e13d404e5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b9abaceb-9b2c-56bc-9906-b7dfe8874b1b","sourceKey":"bank:AMS101:M101-T7N-193","parentItemId":null,"revision":1,"payload":{"prompt":"Conflict about how work gets done is called:","options":["Relationship conflict","Process conflict","Dysfunctional conflict","Task conflict"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Process conflict is conflict over how the work gets done, such as who does what. Option D, task conflict, is about the content and goals of the work rather than the method."}},{"itemId":"33ff8272-b439-586f-8ee6-8aa5d73d2cd5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"33ded241-704f-5e57-b87f-602cd0a7e9e4","sourceKey":"bank:AMS101:M101-T7N-194","parentItemId":null,"revision":1,"payload":{"prompt":"Two officers in a university department constantly clash because of personal dislike for each other, not because of the work itself. This type of conflict is:","options":["Relationship conflict","Process conflict","Functional conflict","Task conflict"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Relationship conflict focuses on interpersonal relationships, and it is almost always dysfunctional. Option D, task conflict, would be about the content and goals of their work."}},{"itemId":"06953733-b17a-5414-a540-f25a313b5c34","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a54ad92-8bde-5846-93ac-3d077b1ddc88","sourceKey":"bank:AMS101:M101-T7N-195","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of conflict is almost always dysfunctional?","options":["Moderate functional conflict","Low-to-moderate task conflict","Low process conflict","Relationship conflict"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Relationship conflict is almost always dysfunctional. Options C and B describe levels of conflict that can actually be functional for a group."}},{"itemId":"64f8a535-4c7c-505c-b4fe-fbc61bd094c1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3e6fc4bd-513f-501d-b6f3-17a55921df19","sourceKey":"bank:AMS101:M101-T7N-196","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five conflict-handling styles?","options":["Compromising","Delegating","Avoiding","Accommodating"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"The five conflict-handling styles are avoiding, accommodating, forcing, compromising and collaborating. Delegating is a way of assigning work, not a way of handling conflict."}},{"itemId":"576ffe17-f76d-523c-9ad9-80f9e8388795","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2bcabd8d-46c9-5f0c-bf96-100a1e83233f","sourceKey":"bank:AMS101:M101-T7N-197","parentItemId":null,"revision":1,"payload":{"prompt":"Withdrawing from or suppressing a conflict is the conflict-handling style called:","options":["Forcing","Accommodating","Avoiding","Compromising"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Avoiding means withdrawing from or suppressing the conflict. Option B, accommodating, deals with the conflict by putting the other party's needs first, rather than stepping away from it."}},{"itemId":"00c77dea-f41c-5e98-ab52-15dd3a347804","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"44f8d7cc-58a0-5757-88ac-e6f421362ecb","sourceKey":"bank:AMS101:M101-T7N-198","parentItemId":null,"revision":1,"payload":{"prompt":"In a dispute over leave dates, a nurse at a Lagos hospital lets her colleague have the dates she wanted, putting the colleague's needs above her own. Which conflict-handling style is she using?","options":["Avoiding","Compromising","Accommodating","Collaborating"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Accommodating is putting the other party's needs above your own. Option B, compromising, would require both nurses to give up something, not one side giving way completely."}},{"itemId":"3d7a108b-298e-52ee-ad08-e2b2037dd109","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"41cd83db-4b55-517b-941c-b1bedf267cb9","sourceKey":"bank:AMS101:M101-T7N-199","parentItemId":null,"revision":1,"payload":{"prompt":"Satisfying your own needs at the expense of the other party is the conflict-handling style called:","options":["Forcing","Compromising","Collaborating","Accommodating"],"correctOption":0,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Forcing means satisfying your own needs at the other party's expense. Option D, accommodating, is the opposite: putting the other party's needs above your own."}},{"itemId":"28c2e844-27fe-59ab-a2d4-99199ca4681a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"667bb7d7-cab0-56d7-9636-570205e1c11f","sourceKey":"bank:AMS101:M101-T7N-200","parentItemId":null,"revision":1,"payload":{"prompt":"Two department heads at a manufacturing firm in Ota both want the full training budget. They agree that each will take half and drop some planned courses. This is:","options":["Collaborating","Compromising","Accommodating","Forcing"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Compromising is a style in which each side gives up something. Option A, collaborating, would look for a win-win solution that fully satisfies both parties rather than each giving something up."}},{"itemId":"c2b36202-46a0-51f5-806a-aa1b608aba2e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3c10434d-e2b5-52b8-ab51-3be87bdb234c","sourceKey":"bank:AMS101:M101-T7N-201","parentItemId":null,"revision":1,"payload":{"prompt":"The conflict-handling style that seeks a win-win solution satisfying all parties is:","options":["Accommodating","Collaborating","Avoiding","Compromising"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Collaborating aims for a win-win solution that satisfies everyone involved. Option D, compromising, settles the conflict by having each side give up something, so no party is fully satisfied."}},{"itemId":"7190e1b1-a2d2-5449-835a-318ff43a2885","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"15ee1c5f-84f0-52c6-b784-65a85f652311","sourceKey":"bank:AMS101:M101-T7N-202","parentItemId":null,"revision":1,"payload":{"prompt":"What tends to happen to a group that has too little conflict?","options":["It moves straight to the adjourning stage","It becomes dull and slow to change","It reaches its highest performance","It becomes chaotic"],"correctOption":1,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Too little conflict makes a group dull and slow to change, while too much makes it chaotic. Option D describes the effect of too much conflict."}},{"itemId":"9393b13e-d6a2-5d69-a323-0d4dd0bc8d1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f5df7f2-3ed2-5048-af82-8c8519ee98c5","sourceKey":"bank:AMS101:M101-T7N-203","parentItemId":null,"revision":1,"payload":{"prompt":"The three ways managers can shape team behaviour are:","options":["Planning, organizing and controlling","Forming, storming and norming","Positive reinforcement, punishment and extinction","Selection, training and rewards"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Managers shape team behaviour by selecting people with teamwork skills, training them in areas like problem solving and conflict management, and rewarding cooperation and team results. Option B lists stages of group development, and Option C lists methods of shaping individual behaviour."}},{"itemId":"63cc03d8-4b97-5001-8db6-0d23cb1097c7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c7f1ec9-4027-5198-aab1-1d3011f6baf6","sourceKey":"bank:AMS101:M101-T7N-204","parentItemId":null,"revision":1,"payload":{"prompt":"When a manager uses rewards to shape team behaviour, the rewards should mainly recognise:","options":["Only the individual with the highest output","Members who avoid all conflict","Cooperation and team results, not only individual effort","Seniority and length of service"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"To build teamwork, rewards should recognise cooperation and team results, not only individual effort. Option A would encourage members to compete rather than work together."}},{"itemId":"33d3e982-7840-5048-bf64-cf285fae3be8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1ba18d76-0551-5f27-80a9-584881141775","sourceKey":"bank:AMS101:M101-T7N-205","parentItemId":null,"revision":1,"payload":{"prompt":"Global teams bring more ideas, but they commonly face problems of:","options":["Lack of any technology","Too little diversity of views","Too few members to share work","Language, culture and trust"],"correctOption":3,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Global teams bring more ideas but face problems of language, culture and trust. Option B is the opposite of their real strength, which is a wider range of ideas."}},{"itemId":"5aed28ad-2fe0-5cdb-a297-403a21da2249","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d123205a-96c1-5d4b-8784-4d7a0fb4e9a7","sourceKey":"bank:AMS101:M101-T7N-206","parentItemId":null,"revision":1,"payload":{"prompt":"Teams take more time and resources than individuals working alone. They are most appropriate when:","options":["The work is simple and can be done by one person","Speed matters more than anything else","The work is complex, needs different perspectives and members depend on one another","Members work on unrelated individual tasks"],"correctOption":2,"section":"Individual Behaviour, Groups and Work Teams","explanation":"Teams are worth their extra time and resources when the work is complex, needs different perspectives and requires interdependence. Options A and D describe work an individual can handle alone, where a team adds cost without benefit."}},{"itemId":"4f3aa128-0dab-54a3-a9c0-a94718053dd9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f95ad14a-f59f-592e-967e-57b700f1ff0a","sourceKey":"bank:AMS101:M101-T8N-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which a person's efforts are energized, directed and sustained toward attaining a goal is known as:","options":["Leadership","Reinforcement","Motivation","Job design"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Motivation is exactly this process: effort that is energized, directed and kept going until a goal is reached. Option A is the wider function of influencing people, of which motivating is only one part, so it is not the term defined here."}},{"itemId":"8724eb51-a21f-5619-a9b1-0b44a6fde3cb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"30b11f2a-b198-596a-a69e-3a5f44a7ef76","sourceKey":"bank:AMS101:M101-T8N-002","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation is best described as the process by which a person's efforts are:","options":["Energized, directed and sustained toward attaining a goal","Combined into tasks that form complete jobs","Rewarded or punished according to their consequences","Compared with the inputs and outcomes of relevant others"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Motivation means effort that is energized, given direction and sustained toward a goal. Option C describes reinforcement theory, which looks at consequences after behaviour rather than defining motivation itself."}},{"itemId":"6d245248-5d54-5d7a-9a7e-d6943603c2e2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ccb28564-90df-5d86-8fbf-a404386d264e","sourceKey":"bank:AMS101:M101-T8N-003","parentItemId":null,"revision":1,"payload":{"prompt":"How many key elements make up the definition of motivation?","options":["Four","Three","Five","Two"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Motivation has three elements: energy, direction and persistence. Option D is wrong because leaving out any one of these, such as persistence, gives an incomplete picture of motivated effort."}},{"itemId":"40b54817-e32b-5034-b52f-241808aced98","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"47578a0e-36ce-5af6-9658-456314ee92c6","sourceKey":"bank:AMS101:M101-T8N-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three elements of motivation?","options":["Satisfaction","Persistence","Direction","Energy"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The three elements of motivation are energy, direction and persistence, so satisfaction is the odd one out. Options B, C and D are all genuine elements: intensity of drive, effort channelled toward goals, and continued effort over time."}},{"itemId":"eccd4948-5ba4-5b07-bd8e-61fdbc98ce1c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0b420948-0544-5b6e-8882-c3b5b7d8ab0f","sourceKey":"bank:AMS101:M101-T8N-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of motivation is described as a measure of intensity or drive?","options":["Valence","Direction","Energy","Persistence"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Energy is the intensity or drive behind a person's effort. Option B is about where that effort is channelled (toward organizational goals), not how intense it is."}},{"itemId":"f12ffd5d-24e6-53e9-b935-25f451c7b2d4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2ab29c9-9aae-5994-8c16-36ef499e8c69","sourceKey":"bank:AMS101:M101-T8N-006","parentItemId":null,"revision":1,"payload":{"prompt":"The element of motivation that refers to effort being channelled toward organizational goals is:","options":["Persistence","Expectancy","Direction","Energy"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Direction means the effort is pointed toward goals the organization wants. Option D only measures how intense the effort is; intense effort aimed at the wrong things is not what organizations need."}},{"itemId":"13ba5f93-2e85-5129-8906-9dbcd203ddbc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee40211b-b1c1-571d-a521-9bb367dd8789","sourceKey":"bank:AMS101:M101-T8N-007","parentItemId":null,"revision":1,"payload":{"prompt":"Bisi, a sales officer at a bank in Lagos, keeps calling prospective customers week after week despite many rejections, until she meets her deposit target. Which element of motivation does she mainly show?","options":["Instrumentality","Persistence","Direction","Energy"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Persistence is about continuing to put in effort over time to achieve goals, which is what Bisi does despite rejections. Option D, energy, is the intensity of effort at a point in time, while her story is mainly about keeping going."}},{"itemId":"43980fd6-0589-5bb0-bc3b-3b78b82631c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c3ab3f5b-ce3f-55df-8911-07e0e5955430","sourceKey":"bank:AMS101:M101-T8N-008","parentItemId":null,"revision":1,"payload":{"prompt":"A manager notices that some very energetic employees are putting great effort into activities that do not help the organization. Which element of motivation is missing?","options":["Tension","Energy","Persistence","Direction"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"High energy alone is not enough; effort must also have the right direction, toward goals the organization wants. Option B is wrong because these employees clearly have plenty of energy already."}},{"itemId":"471ea14e-7190-5bab-b5a0-da1110f31868","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ceec7b00-817b-50e5-b162-69366d2a8177","sourceKey":"bank:AMS101:M101-T8N-009","parentItemId":null,"revision":1,"payload":{"prompt":"How many steps are there in the motivation process?","options":["Seven","Five","Four","Six"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The motivation process has six steps: unsatisfied need, tension, drives, search behaviour, satisfied need and reduction of tension. Option B misses one stage, usually the final reduction of tension."}},{"itemId":"ce1119a9-9bf4-554c-8615-86f900eeaf1b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3dec68eb-a111-5456-bcdc-63ea18b7f896","sourceKey":"bank:AMS101:M101-T8N-010","parentItemId":null,"revision":1,"payload":{"prompt":"The motivation process begins with:","options":["Search behaviour","Tension","Drives","An unsatisfied need"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Everything starts with an unsatisfied need, which then creates tension. Option B is the second step; tension is the result of the unsatisfied need, not its starting point."}},{"itemId":"718d8d9c-499f-5707-8d2b-bc54f8de8378","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c2a05d18-1935-5f2f-aba7-e228e9e5ea74","sourceKey":"bank:AMS101:M101-T8N-011","parentItemId":null,"revision":1,"payload":{"prompt":"In the motivation process, what does an unsatisfied need directly create?","options":["Reduction of tension","Search behaviour","Drives","Tension"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"An unsatisfied need creates tension, the second step of the process. Option C comes next: drives are produced by the tension, not directly by the need."}},{"itemId":"4c6ebe14-977d-5ca1-8e71-3507be02a244","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"300a9128-2aad-5a2d-a117-2ede27496cd4","sourceKey":"bank:AMS101:M101-T8N-012","parentItemId":null,"revision":1,"payload":{"prompt":"What is the third step in the motivation process?","options":["Tension","Drives","Search behaviour","Satisfied need"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"The order is unsatisfied need, tension, drives, so drives is the third step. Option A is the second step and option C is the fourth."}},{"itemId":"d7460aec-a64f-5ba7-92bd-2785b3f2a106","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c9a59bb4-3bf9-5828-bb6e-49948b60ce6e","sourceKey":"bank:AMS101:M101-T8N-013","parentItemId":null,"revision":1,"payload":{"prompt":"In the motivation process, which step immediately follows drives?","options":["Tension","Search behaviour","Reduction of tension","Satisfied need"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Drives push the person to search for ways to satisfy the need, so search behaviour comes next. Option D only comes after the search has succeeded."}},{"itemId":"a4fc0b38-7ae0-5ff2-8e18-87571880132f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b0a42e32-bc35-53c6-bf09-335b9452e5b7","sourceKey":"bank:AMS101:M101-T8N-014","parentItemId":null,"revision":1,"payload":{"prompt":"The final step in the motivation process is:","options":["Drives","Search behaviour","Reduction of tension","Satisfied need"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"When the need is met, tension falls, so reduction of tension is the sixth and last step. Option D is the fifth step; meeting the need is what causes the tension to reduce afterwards."}},{"itemId":"702a0526-b144-56a2-a96b-cd2613472ba2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eb01dc94-d838-56ce-a965-4ad354c55af3","sourceKey":"bank:AMS101:M101-T8N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation that comes from inside the person, such as enjoying the work itself, is called:","options":["Hygiene motivation","Extrinsic motivation","Reinforced motivation","Intrinsic motivation"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Intrinsic motivation comes from within, such as a personal sense of achievement or enjoying the work itself. Option B is driven by external rewards like pay, bonuses or promotion."}},{"itemId":"c878f556-7808-561e-929d-99006d2f7998","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7dc3365b-a5cd-5041-9167-c88c66eb3add","sourceKey":"bank:AMS101:M101-T8N-016","parentItemId":null,"revision":1,"payload":{"prompt":"Ngozi, a nurse at a hospital in Ibadan, takes extra shifts mainly to earn overtime bonuses and improve her chances of promotion. Her motivation is mainly:","options":["Extrinsic","Self-actualizing","Intrinsic","Affiliative"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Extrinsic motivation is driven by external rewards such as pay, bonuses and promotion, which is what Ngozi is chasing. Option C would apply if she worked the shifts mainly because she enjoys the work itself."}},{"itemId":"680b8afa-dd6d-5e4a-85d2-ffc9d38ccc32","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8b1ba556-5012-5821-bad7-1953b8fd117e","sourceKey":"bank:AMS101:M101-T8N-017","parentItemId":null,"revision":1,"payload":{"prompt":"A lecturer in a university department spends extra evenings refining her course simply because she enjoys the work itself. This is an example of:","options":["Extrinsic motivation","Job enlargement","Intrinsic motivation","Reinforcement"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Enjoying the work itself is a classic driver of intrinsic motivation, which comes from inside the person. Option A would need an external reward, such as a bonus or promotion, to be the driver."}},{"itemId":"773dd50c-248c-5fd6-9b31-c5e947525a42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3ec30dca-96e8-5a27-ac82-d202d8ccf8a0","sourceKey":"bank:AMS101:M101-T8N-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these would drive extrinsic motivation in an employee?","options":["Feeling a personal sense of achievement","Enjoying the work itself","Being promoted to a higher post","Taking pride in doing a task well"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Promotion is an external reward, so it drives extrinsic motivation. Options A and B come from inside the person and are therefore intrinsic."}},{"itemId":"770286de-6092-5463-af07-12744552e713","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e0750184-6d42-52fe-a0cc-69314f8adacd","sourceKey":"bank:AMS101:M101-T8N-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a process theory of motivation?","options":["Adams's equity theory","Herzberg's two-factor theory","Maslow's hierarchy of needs","McClelland's three-needs theory"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Process theories explain how motivation works, and Adams's equity theory is one of them, along with Vroom's expectancy and Locke and Latham's goal-setting theory. Options B, C and D are content theories, which explain what motivates people."}},{"itemId":"31d2267b-b411-5f7f-9a59-298bde376763","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2fcd3b14-a73a-5449-a0e8-6bbf48786a26","sourceKey":"bank:AMS101:M101-T8N-020","parentItemId":null,"revision":1,"payload":{"prompt":"Content theories of motivation differ from process theories in that content theories focus on:","options":["What motivates people","How people compare their rewards with others","How motivation works","The consequences that follow behaviour"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Content theories such as Maslow, Herzberg and McClelland explain what motivates people. Option C describes process theories, such as Vroom's expectancy theory, which explain how motivation works."}},{"itemId":"c9acca7e-902a-5634-95fb-bed53617fa9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"516eeb77-c423-53e0-92f3-2362b1778519","sourceKey":"bank:AMS101:M101-T8N-021","parentItemId":null,"revision":1,"payload":{"prompt":"Locke and Latham's goal-setting theory is classified as a:","options":["Needs-hierarchy theory","Content theory","Two-factor theory","Process theory"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Goal-setting theory explains how motivation works, so it sits with Vroom and Adams among the process theories. Option B is wrong because content theories, like Maslow's, explain what motivates rather than how."}},{"itemId":"0ea61590-865c-5f5d-992a-4483b3f86ede","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6e854643-e4dc-5263-a888-e42c589a7136","sourceKey":"bank:AMS101:M101-T8N-022","parentItemId":null,"revision":1,"payload":{"prompt":"Motivating employees is part of which management function?","options":["Controlling","Planning","Leading","Organizing"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Motivating employees falls under leading, also called directing. Option A is about checking performance against standards, and option B is about setting goals, so neither is where motivation sits."}},{"itemId":"33ecb785-d580-5ce1-8ffb-b715a3d118a2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b8746db-f777-5eec-83cf-7c6a36760f88","sourceKey":"bank:AMS101:M101-T8N-023","parentItemId":null,"revision":1,"payload":{"prompt":"The hierarchy of needs theory of motivation was proposed by:","options":["Douglas McGregor","Frederick Herzberg","David McClelland","Abraham Maslow"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Abraham Maslow proposed that people have five needs arranged in a hierarchy from physiological to self-actualization. Option B, Herzberg, is known for the two-factor theory of motivators and hygiene factors, not a hierarchy."}},{"itemId":"3436d2a1-593d-5d69-b703-b638a6690f26","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e47588b9-2b38-5ebc-8093-428c39a263c4","sourceKey":"bank:AMS101:M101-T8N-024","parentItemId":null,"revision":1,"payload":{"prompt":"How many levels of needs are there in Maslow's hierarchy?","options":["Six","Four","Five","Three"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Maslow's hierarchy has five levels: physiological, safety, social, esteem and self-actualization. Option D is the number of needs in McClelland's theory, which is a common mix-up."}},{"itemId":"f2ad4dbc-224b-59c3-abe6-73152835ff9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25af8e42-e482-555e-a61a-cc442a205a7f","sourceKey":"bank:AMS101:M101-T8N-025","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy, which need is at the second level, directly above physiological needs?","options":["Self-actualization","Esteem","Social","Safety"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Safety needs, such as protection from harm, job security and pensions, come second. Option C, social needs for belonging and friendship, comes third, after safety is satisfied."}},{"itemId":"8209cc0d-539a-517d-aaff-a17814f4af69","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd1005a7-743c-50b5-b472-e7b8dc34661f","sourceKey":"bank:AMS101:M101-T8N-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which need occupies the third level of Maslow's hierarchy?","options":["Physiological","Social","Esteem","Safety"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Social needs for affection, belonging, acceptance and friendship sit at level three. Option C, esteem, is the fourth level and only becomes dominant once social needs are largely met."}},{"itemId":"96ac2a96-c70e-5111-bb2f-4e96e7444813","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f721efc7-f75d-5e6b-8983-3ac6c4a1839a","sourceKey":"bank:AMS101:M101-T8N-027","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy, esteem needs are found at which level?","options":["Fourth","Third","Fifth","Second"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Esteem is the fourth level, just below self-actualization. Option C is wrong because the fifth and highest level is self-actualization, not esteem."}},{"itemId":"a7e460b7-7a19-5981-86e7-b63fb1bfbe6c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2156f722-becd-5a6f-bbbb-67891034b5aa","sourceKey":"bank:AMS101:M101-T8N-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows Maslow's needs from lowest to highest?","options":["Physiological, social, safety, esteem, self-actualization","Physiological, safety, social, esteem, self-actualization","Safety, physiological, social, esteem, self-actualization","Physiological, safety, esteem, social, self-actualization"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Maslow's order runs physiological, safety, social, esteem and then self-actualization at the top. Option A swaps safety and social, but safety needs must be met before belonging becomes the main concern."}},{"itemId":"e6c1dfbd-b2fa-5093-99e8-c470115794ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f46598f0-db64-519d-af3e-ea4b55c27e71","sourceKey":"bank:AMS101:M101-T8N-029","parentItemId":null,"revision":1,"payload":{"prompt":"Maslow's lower-order needs are:","options":["Esteem and self-actualization needs","Social and esteem needs","Physiological and social needs","Physiological and safety needs"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The lower-order needs are the first two levels, physiological and safety. Option C wrongly includes social needs, which belong with esteem and self-actualization among the higher-order needs."}},{"itemId":"e1ec70b3-35fa-587b-b54d-7adc2696d37c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a57fe55-51ec-5da6-ab04-6d6a3a8c0cf2","sourceKey":"bank:AMS101:M101-T8N-030","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow, lower-order needs are satisfied mainly:","options":["Through friendships and group acceptance","Internally, through personal growth and self-respect","Through achieving one's full potential","Externally, through things like pay, contracts and tenure"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Lower-order needs (physiological and safety) are satisfied mainly from outside the person, for example by pay, contracts and tenure. Option B describes higher-order needs, which are satisfied internally."}},{"itemId":"2b093d26-46b6-5f19-a757-ecba96294c64","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4919c2ef-9e96-5cdd-b129-b9b9800a1329","sourceKey":"bank:AMS101:M101-T8N-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a higher-order need in Maslow's hierarchy?","options":["Esteem","Safety","Self-actualization","Social"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Safety is a lower-order need, together with physiological needs. Options A, C and D are the three higher-order needs, which are satisfied internally."}},{"itemId":"d12747f3-bac0-5a8d-832c-fb79a1fcb2de","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"63d7883f-87fb-5725-aa16-291e63a2cfb5","sourceKey":"bank:AMS101:M101-T8N-032","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota introduces a pension scheme and protects workers from harm on the factory floor. Which level of Maslow's needs is it mainly addressing?","options":["Safety","Social","Esteem","Physiological"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Protection from harm and pensions are examples of safety needs at work. Option D, physiological needs, covers food, water, shelter and the basic pay needed to buy them."}},{"itemId":"3cb9e635-aabb-5fa5-979f-5ae6fc2c57d9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77a6c72e-07f7-520c-a247-55e0fc91025b","sourceKey":"bank:AMS101:M101-T8N-033","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a new branch of a Lagos bank say they mainly want to feel accepted and to make friends with their colleagues. Which of Maslow's needs is dominant for them?","options":["Social","Safety","Esteem","Self-actualization"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Social needs cover affection, belonging, acceptance and friendship. Option C, esteem, is about self-respect, status and recognition rather than simply fitting in with others."}},{"itemId":"8bb26b4f-9b23-534c-924b-d0aa62504520","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48c40dbd-2bec-56d5-a22a-04543ebd0c64","sourceKey":"bank:AMS101:M101-T8N-034","parentItemId":null,"revision":1,"payload":{"prompt":"A senior accountant in Abuja is mainly driven by wanting a respected title, status and recognition from colleagues. Which of Maslow's needs is most active?","options":["Social","Esteem","Self-actualization","Safety"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Status, recognition and attention are the external side of esteem needs. Option A, social needs, is about belonging and friendship, not being looked up to."}},{"itemId":"f040137e-19b9-501d-bbf1-447c9e66c2ab","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ac1a18c5-b6ab-5915-a514-b0a20d4a142e","sourceKey":"bank:AMS101:M101-T8N-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an EXTERNAL esteem factor in Maslow's hierarchy?","options":["Autonomy","Achievement","Self-respect","Status"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Maslow splits esteem into internal factors (self-respect, autonomy, achievement) and external factors (status, recognition, attention). Status is external because it comes from how others see you, while options C, A and B are internal."}},{"itemId":"c923a77f-9218-578e-8eb1-413f5fe90ea9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c6d4cc38-937a-5390-947e-d01f88804500","sourceKey":"bank:AMS101:M101-T8N-036","parentItemId":null,"revision":1,"payload":{"prompt":"A professor in a university department says her main aim now is to grow and achieve her full potential as a scholar. Which need is she trying to satisfy?","options":["Social","Self-actualization","Esteem","Safety"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Self-actualization is about growth, achieving one's potential and self-fulfilment. Option C, esteem, is about self-respect, status and recognition, which is close but is not the same as reaching one's full potential."}},{"itemId":"51942541-4748-52a8-8d4e-babcfc5da369","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a645745b-1a88-574d-90ba-4fdc6d7519ce","sourceKey":"bank:AMS101:M101-T8N-037","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow, what happens once a need has been substantially satisfied?","options":["It must be satisfied again before any other need can arise","It no longer motivates, and the person moves up to the next level","It becomes a stronger motivator than before","It turns into a hygiene factor that prevents dissatisfaction"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Maslow held that a substantially satisfied need stops motivating, so the person moves up to the next need. Option D borrows Herzberg's language of hygiene factors, which belongs to a different theory."}},{"itemId":"beefc671-23da-55ec-b42e-0dc253a3c956","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4740681-d9d7-5a8e-a491-b6b856e34084","sourceKey":"bank:AMS101:M101-T8N-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an assumption of Maslow's hierarchy of needs?","options":["Needs come in a fixed order","People compare their input-outcome ratios with others","Behaviour depends only on its consequences","A satisfied need continues to motivate"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Maslow assumed that behaviour is based on needs, that needs come in a fixed order and that a satisfied need stops motivating. Option C describes reinforcement theory, and option D contradicts Maslow directly."}},{"itemId":"b66d44b1-5eae-59e6-ba6e-2013f622aa18","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"56accf5d-c869-5671-a2f9-e567ca884599","sourceKey":"bank:AMS101:M101-T8N-039","parentItemId":null,"revision":1,"payload":{"prompt":"Theory X and Theory Y were proposed by:","options":["Frederick Herzberg","Douglas McGregor","Abraham Maslow","Victor Vroom"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Douglas McGregor described two sets of assumptions managers hold about workers, a negative Theory X and a positive Theory Y. Option C, Maslow, proposed the hierarchy of needs instead."}},{"itemId":"46850e11-3d82-5c2c-9a04-893dd64cef21","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"785d03e0-5e15-5529-bd0b-c08a86b037ef","sourceKey":"bank:AMS101:M101-T8N-040","parentItemId":null,"revision":1,"payload":{"prompt":"Under Theory X, managers assume that workers:","options":["Can exercise self-direction","Accept and actually seek responsibility","See work as a natural activity","Dislike work and avoid responsibility"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Theory X is the negative view: workers have little ambition, dislike work, avoid responsibility and must be closely controlled. Options A, B and C are Theory Y assumptions."}},{"itemId":"73e0c479-82b0-54cc-b0f3-2bf561626246","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce0ed20a-49a0-569d-822f-f1fde02405cf","sourceKey":"bank:AMS101:M101-T8N-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a Theory Y assumption about workers?","options":["They accept and actually seek responsibility","They must be closely controlled to work well","They see work as a natural activity","They can exercise self-direction"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Needing close control is a Theory X assumption, part of McGregor's negative view of workers. Options A, C and D all reflect the positive Theory Y view."}},{"itemId":"42f40ed3-7e18-59be-b042-110b7cb319b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7997056e-4972-5045-9b99-6cc8e45d76b0","sourceKey":"bank:AMS101:M101-T8N-042","parentItemId":null,"revision":1,"payload":{"prompt":"A production manager in an Ota factory believes his workers have little ambition, so he watches them closely all day. His view of workers reflects:","options":["Theory Y","Theory X","McClelland's need for power","Herzberg's motivators"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Believing workers lack ambition and must be closely controlled is the Theory X view. Option A, Theory Y, assumes workers can direct themselves and seek responsibility."}},{"itemId":"1747a0a9-8615-5d27-84c5-bee1a64a8091","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ae114f8b-2cc7-545f-9651-1a99228a4378","sourceKey":"bank:AMS101:M101-T8N-043","parentItemId":null,"revision":1,"payload":{"prompt":"Because he believed Theory Y assumptions were more valid, McGregor proposed:","options":["Heavier use of punishment to stop unwanted behaviour","Close supervision and strict rules","Removing responsibility from jobs to reduce stress","Participation in decisions and responsible, challenging jobs"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"McGregor favoured Theory Y and proposed participation in decisions, responsible and challenging jobs, and good group relations. Option B fits Theory X thinking, which he considered less valid."}},{"itemId":"af759aa2-48a9-55a7-8d1b-c283851640c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd34a16b-fd49-531e-a08d-4d81de9bdde2","sourceKey":"bank:AMS101:M101-T8N-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about McGregor's Theory X and Theory Y is correct?","options":["McGregor believed Theory X assumptions were more valid","Research has proved that Theory Y assumptions are valid","There is no evidence that acting on Theory Y always makes workers more motivated","Theory X represents a positive view of workers"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"There is no evidence that either set of assumptions is valid, or that acting on Theory Y always raises motivation. Option B overstates the evidence, and option A is wrong because McGregor favoured Theory Y."}},{"itemId":"c07b8d4e-09a4-59f5-8887-07895521d8a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6b560d49-59d3-5c23-a246-00a0be968984","sourceKey":"bank:AMS101:M101-T8N-045","parentItemId":null,"revision":1,"payload":{"prompt":"The motivation-hygiene theory, also called the two-factor theory, was developed by:","options":["David McClelland","Abraham Maslow","J. Stacy Adams","Frederick Herzberg"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Frederick Herzberg split work factors into motivators and hygiene factors, hence the two-factor or motivation-hygiene theory. Option A, McClelland, is linked with the needs for achievement, power and affiliation."}},{"itemId":"7a2f1d45-9b42-5062-95a6-eb6e51b2967d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c4a750c-8b4e-5ba0-bbea-1a6400183494","sourceKey":"bank:AMS101:M101-T8N-046","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's theory, hygiene factors:","options":["Are intrinsic factors linked to the work itself","Are the needs at the top of the hierarchy","Remove dissatisfaction but do not motivate","Create satisfaction and motivate"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Hygiene factors, such as pay, policy and working conditions, only remove dissatisfaction; they do not motivate. Option D describes motivators, which create satisfaction."}},{"itemId":"099f1468-ea4f-5a03-9cd2-f0a7a46d3402","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ff7bbf7c-c199-589b-a422-649601831a5e","sourceKey":"bank:AMS101:M101-T8N-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a motivator in Herzberg's two-factor theory?","options":["Company policy","Supervision","Responsibility","Working conditions"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Responsibility is one of Herzberg's motivators, along with achievement, recognition, the work itself, advancement and growth. Options A, B and D are hygiene factors that only prevent dissatisfaction."}},{"itemId":"fb732879-b8b1-5ae9-852a-0f4c185a648f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a969cda-fe51-5ad2-84ef-a5b9011582ad","sourceKey":"bank:AMS101:M101-T8N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a hygiene factor in Herzberg's theory?","options":["Supervision","Advancement","Relations with others","Job security"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Advancement is a motivator, because it relates to growth in the job itself. Options A, C and D are hygiene factors, which only stop workers from being dissatisfied."}},{"itemId":"e4577428-7d1a-5e3e-a18d-0a27edc9fe25","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3b57fee3-538f-5e8a-8ae8-999c8e68dd2f","sourceKey":"bank:AMS101:M101-T8N-049","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's two-factor theory, salary is classified as:","options":["A hygiene factor","An intrinsic factor","A motivator","A source of satisfaction"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Salary is a hygiene factor: poor pay causes dissatisfaction, but good pay alone does not motivate. Option C is the common trap, since things like recognition, not salary, are the motivators."}},{"itemId":"8995025b-1c18-571c-8684-8903d3e61ce1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e2f33ec8-21d3-5e8a-a19d-f48ca5afc656","sourceKey":"bank:AMS101:M101-T8N-050","parentItemId":null,"revision":1,"payload":{"prompt":"According to Herzberg, the opposite of satisfaction is:","options":["No dissatisfaction","Dissatisfaction","No satisfaction","Tension"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Herzberg argued that satisfaction and dissatisfaction lie on separate scales, so the opposite of satisfaction is no satisfaction. Option B is the traditional view that Herzberg rejected."}},{"itemId":"cd34ec23-c334-527f-8e47-a97c9bba6fb2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cabfac07-1388-5a9a-8e9d-ece3b8ec52c8","sourceKey":"bank:AMS101:M101-T8N-051","parentItemId":null,"revision":1,"payload":{"prompt":"On Herzberg's separate scales, the opposite of dissatisfaction is:","options":["No dissatisfaction","No satisfaction","Motivation","Satisfaction"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Herzberg's second scale runs from dissatisfaction to no dissatisfaction, which is where hygiene factors act. Option D is wrong because removing dissatisfaction does not automatically create satisfaction."}},{"itemId":"41dbba31-768f-5f25-acf5-497bf7cc9f40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c134596a-2026-58e1-acf1-357360d5d67d","sourceKey":"bank:AMS101:M101-T8N-052","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank improves its working conditions, supervision and company policies. Staff stop complaining, but they are not any more motivated. Which idea best explains this?","options":["McGregor's Theory Y","Vroom's valence","Herzberg's hygiene factors","McClelland's need for affiliation"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Working conditions, supervision and policy are hygiene factors: fixing them removes dissatisfaction and makes workers calm, not motivated. Option A, Theory Y, is about managers' positive assumptions about workers, not about which factors motivate."}},{"itemId":"d67fb904-c271-5040-a35f-307cd3ff5e1b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0f23966a-fb6a-5d1d-8895-35e3347d1a6a","sourceKey":"bank:AMS101:M101-T8N-053","parentItemId":null,"revision":1,"payload":{"prompt":"Herzberg's motivators are mainly related to:","options":["Pay and job security","The working conditions around the job","Company policy and supervision","The job itself"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Herzberg said that to motivate, managers must use the motivators, which are about the job itself, such as responsibility and achievement. Options A, B and C are hygiene factors that surround the job."}},{"itemId":"69dc0023-d28d-5c64-a76d-846bbc152461","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ab8c290-1260-5d58-85ae-127dd23920dd","sourceKey":"bank:AMS101:M101-T8N-054","parentItemId":null,"revision":1,"payload":{"prompt":"In Herzberg's theory, hygiene factors and motivators are respectively described as:","options":["Extrinsic and intrinsic","Process and content","Intrinsic and extrinsic","Higher-order and lower-order"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Hygiene factors are extrinsic, while motivators are intrinsic. Option C reverses the pair, which is a common error."}},{"itemId":"dffa10a4-3846-56f3-a97d-b89164c0dd72","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"364e3767-bbd3-5a8e-9bdb-4a3c40aeb2be","sourceKey":"bank:AMS101:M101-T8N-055","parentItemId":null,"revision":1,"payload":{"prompt":"Herzberg's work led to growing interest in which approach to job design?","options":["Job sharing","Job enlargement","Job enrichment","Telecommuting"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Herzberg's focus on motivators in the job itself drove interest in job enrichment, which adds responsibility to jobs. Option B, job enlargement, only adds more tasks of the same kind."}},{"itemId":"309ecbd4-c125-5397-ac51-79079be93005","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f99db07-1e05-57dd-af9e-005e500a7010","sourceKey":"bank:AMS101:M101-T8N-056","parentItemId":null,"revision":1,"payload":{"prompt":"The three-needs theory of motivation is associated with:","options":["David McClelland","Frederick Herzberg","Victor Vroom","Abraham Maslow"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"David McClelland identified the needs for achievement, power and affiliation. Option D, Maslow, proposed five needs arranged in a hierarchy."}},{"itemId":"47937873-edab-5db5-8b05-54ce285e99ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"213fe470-7b2b-5ded-a2f2-4c189d7c1c05","sourceKey":"bank:AMS101:M101-T8N-057","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the needs in McClelland's three-needs theory?","options":["Power","Achievement","Esteem","Affiliation"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"McClelland's three needs are achievement, power and affiliation. Esteem is a level in Maslow's hierarchy, not one of McClelland's needs."}},{"itemId":"6f53bcd3-d1d5-5cd8-b095-ff67e9fff72f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f5d6c6c-0bc0-50d0-95f2-9ba462da7d65","sourceKey":"bank:AMS101:M101-T8N-058","parentItemId":null,"revision":1,"payload":{"prompt":"In McClelland's theory, the drive to succeed and excel in relation to a set of standards is the need for:","options":["Affiliation","Power","Self-actualization","Achievement"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The need for achievement (nAch) is the drive to excel against a set of standards. Option B, power, is about making others behave in ways they would not otherwise have behaved."}},{"itemId":"bddb4875-a763-5e92-afca-8a17ad21f839","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b38ced31-cb84-5dc3-962f-5764f534c391","sourceKey":"bank:AMS101:M101-T8N-059","parentItemId":null,"revision":1,"payload":{"prompt":"The need to make others behave in a way they would not have behaved otherwise is McClelland's need for:","options":["Esteem","Affiliation","Achievement","Power"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"This is the need for power (nPow), which is about influencing others' behaviour. Option C, achievement, is about excelling against standards rather than controlling people."}},{"itemId":"f3fb09c2-4e61-53b8-a447-2907a38966ba","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ca7aadd-952c-529b-9125-66dbf2ae9300","sourceKey":"bank:AMS101:M101-T8N-060","parentItemId":null,"revision":1,"payload":{"prompt":"An administrative officer at a hospital in Enugu cares most about having friendly and close relationships with her co-workers. In McClelland's terms she is high in the need for:","options":["Power","Safety","Affiliation","Achievement"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"The need for affiliation (nAff) is the desire for friendly and close interpersonal relationships. Option B, safety, belongs to Maslow's hierarchy rather than McClelland's three needs."}},{"itemId":"2c921104-47b2-5197-bb92-d219754f75e7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8baae77e-e4a9-5ee9-8a1b-1053d33352db","sourceKey":"bank:AMS101:M101-T8N-061","parentItemId":null,"revision":1,"payload":{"prompt":"According to McClelland, high achievers prefer jobs that offer:","options":["Shared responsibility, delayed feedback and low risk","Close supervision, fast feedback and no risk","Personal responsibility, little feedback and very high risk","Personal responsibility, fast feedback and moderate risk"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"High achievers like personal responsibility, fast feedback and moderate risk, and they avoid tasks that are very easy or very hard. Option C is wrong because high achievers prefer moderate risk, not very high risk."}},{"itemId":"836423d8-55f7-567e-b218-77b9350b096d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0c1f8949-4eb2-5436-b6b7-1ab543443469","sourceKey":"bank:AMS101:M101-T8N-062","parentItemId":null,"revision":1,"payload":{"prompt":"McClelland found that the best managers tend to be:","options":["High in the need for achievement and low in the need for power","High in the needs for both affiliation and achievement","High in the need for power and low in the need for affiliation","High in the need for affiliation and low in the need for power"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"The best managers tend to be high in power and low in affiliation. Option A is tempting, but a high need to achieve does not by itself make someone a good manager."}},{"itemId":"4d43c515-6b00-556e-822b-854b3748ce04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e75d3edb-2a68-5a30-9556-57f3c3926988","sourceKey":"bank:AMS101:M101-T8N-063","parentItemId":null,"revision":1,"payload":{"prompt":"Goal-setting theory of motivation was proposed by Edwin Locke and later developed with:","options":["Victor Vroom","Gary Latham","B. F. Skinner","J. Stacy Adams"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Goal-setting theory is credited to Edwin Locke, later developed with Gary Latham. Option A, Vroom, proposed expectancy theory, which is a different process theory."}},{"itemId":"45c43802-293e-57a6-9b31-eac232c3af30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"555f9e36-4f13-5f3b-b3d7-a3b56c8c8f1a","sourceKey":"bank:AMS101:M101-T8N-064","parentItemId":null,"revision":1,"payload":{"prompt":"Goal-setting theory states that:","options":["People compare their input-outcome ratios with others","Setting specific and challenging goals motivates people","Behaviour is a function of its consequences","A satisfied need no longer motivates"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Goal-setting theory holds that specific and challenging goals motivate people. Option C is the central idea of reinforcement theory, which looks at consequences after behaviour."}},{"itemId":"c2c89fd4-2a72-509f-bd1c-382593ac81c9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2d811337-5593-59bb-88f9-04c6c3ee4987","sourceKey":"bank:AMS101:M101-T8N-065","parentItemId":null,"revision":1,"payload":{"prompt":"According to goal-setting theory, which kind of goals lead to higher performance?","options":["Very difficult goals that cannot realistically be reached","Vague, easy goals with no feedback","Clear, difficult but attainable goals accompanied by feedback","General goals such as 'do your best'"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Goals that are clear, difficult but attainable and accompanied by feedback lead to higher performance. Option D is wrong because goals that are too difficult cause discouragement."}},{"itemId":"c6a79158-6911-5ab5-b9c0-0f95fb6f6673","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c9c8f3f-1c3a-5232-b740-8f17edf2d9e1","sourceKey":"bank:AMS101:M101-T8N-066","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with a general instruction to 'do your best', specific goals:","options":["Raise performance more","Only work when the employee sets them alone","Have exactly the same effect on performance","Raise performance less"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Specific goals raise performance more than a vague 'do your best'. Option B is wrong because a goal does not need to be self-set to work; assigned goals can also be effective."}},{"itemId":"0bbd221f-45e8-56c9-8a1e-5382c75bf2ad","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9bd0271e-29a2-5ee6-a8bd-04ebc3211735","sourceKey":"bank:AMS101:M101-T8N-067","parentItemId":null,"revision":1,"payload":{"prompt":"According to goal-setting theory, difficult goals, once accepted:","options":["Only matter when combined with punishment","Always cause discouragement","Result in lower performance than easy goals","Result in higher performance than easy goals"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Once employees accept them, difficult goals produce higher performance than easy ones. Option B confuses accepted hard goals with goals that are too difficult, which are the ones that discourage people."}},{"itemId":"7e42a1ab-9964-5626-ab79-23005fad470a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"efc44652-3122-5191-b328-84870fcdd3b1","sourceKey":"bank:AMS101:M101-T8N-068","parentItemId":null,"revision":1,"payload":{"prompt":"In SMART goals, the letter S stands for:","options":["Simple","Strategic","Sustainable","Specific"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"S stands for Specific: the goal is clear and well defined, answering who, what, where, when and why. Option A sounds similar, but a goal can be simple and still vague."}},{"itemId":"666f31a3-d60e-54e7-a936-59c4d1e4f160","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"eb20e7b0-e712-5a8b-ad07-3501ccad4d10","sourceKey":"bank:AMS101:M101-T8N-069","parentItemId":null,"revision":1,"payload":{"prompt":"Which SMART element requires that progress can be tracked with numbers, percentages or other concrete indicators?","options":["Relevant","Time-bound","Specific","Measurable"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Measurable means progress can be tracked with concrete indicators such as numbers or percentages. Option C, specific, is about the goal being clear and well defined, not about how progress is tracked."}},{"itemId":"27c16695-7c39-5805-a504-e7a04048c4cd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"23eb6ec6-080e-535c-8177-dd1b43a2de81","sourceKey":"bank:AMS101:M101-T8N-070","parentItemId":null,"revision":1,"payload":{"prompt":"A SMART goal that is realistic, challenging but within reach, satisfies which element?","options":["Achievable","Relevant","Specific","Measurable"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Achievable (also called attainable) means the goal is realistic, challenging but within reach. Option B, relevant, is about how well the goal fits wider objectives and values."}},{"itemId":"94d32931-0508-57ba-b7ed-8393a3dea644","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c862cd68-e9b7-574c-9df7-90cba1dcea71","sourceKey":"bank:AMS101:M101-T8N-071","parentItemId":null,"revision":1,"payload":{"prompt":"The SMART element which requires that a goal fits the person's or organization's overall objectives and values is:","options":["Relevant","Specific","Achievable","Time-bound"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Relevant means the goal fits the overall objectives and values of the person or organization. Option C, achievable, is about whether the goal is realistic, not whether it fits the bigger picture."}},{"itemId":"6b23099f-af9b-5360-8d84-c549e4a7a04f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7f8b7c3e-fe63-56ba-815b-04039c67ee42","sourceKey":"bank:AMS101:M101-T8N-072","parentItemId":null,"revision":1,"payload":{"prompt":"A department head at a university sets the goal 'publish two research papers', but gives no date by which they must be done. Which SMART element is missing?","options":["Specific","Relevant","Time-bound","Measurable"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Time-bound goals have a specific deadline, and this goal has none. Option D is already met, because 'two papers' is a number that can be tracked."}},{"itemId":"a8efe31c-37e3-5241-936d-012f7f336d89","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3b16c161-c56b-5484-8d18-50960ca2f94a","sourceKey":"bank:AMS101:M101-T8N-073","parentItemId":null,"revision":1,"payload":{"prompt":"A branch manager at a Lagos bank changes the goal 'increase deposits' to 'increase savings deposits by 15% by the end of the third quarter'. The new goal is better mainly because it is:","options":["Set without any input from the manager","Free of any deadline pressure","Easier to achieve than the old goal","Specific, measurable and time-bound"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The rewritten goal names exactly what to increase, by how much and by when, so it is specific, measurable and time-bound. Option C is wrong because the change makes the goal clearer, not easier."}},{"itemId":"773ad602-5a75-57ed-9778-3128204db2e9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5016cef8-4f66-5731-988e-3f080933c529","sourceKey":"bank:AMS101:M101-T8N-074","parentItemId":null,"revision":1,"payload":{"prompt":"Achievable is included in SMART goals mainly because goals that are too difficult:","options":["Remove the need for feedback","Cause discouragement","Are always rejected by managers","Cannot be measured"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Goals that are too difficult discourage people, which is why SMART requires goals to be achievable. Option D mixes up two elements: a very hard goal can still be measured."}},{"itemId":"535055a0-d92a-5fad-890b-e7f38ecbd7a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"87b42958-5666-5571-a946-7f8e70206d3f","sourceKey":"bank:AMS101:M101-T8N-075","parentItemId":null,"revision":1,"payload":{"prompt":"In goal-setting, which type of feedback is considered more powerful?","options":["Feedback given after the goal has been abandoned","Feedback given by a supervisor once a year","Self-generated feedback, where the employee tracks their own progress","Feedback from co-workers only"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Self-generated feedback, where employees track their own progress, is more powerful than feedback from others. Option B is feedback from others, and coming only once a year it does little to show the gap while work is going on."}},{"itemId":"3dd74de6-0357-591c-8438-0d0784963c7b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a7d8af4-8726-5fdd-b6c1-61b082f91fb0","sourceKey":"bank:AMS101:M101-T8N-076","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main benefit of allowing employees to participate in setting their goals?","options":["It always produces higher performance than assigned goals","They are more likely to accept a hard goal","It removes the need for feedback","It makes goals easier to reach"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Participation makes people more likely to accept a difficult goal. Option A is wrong because participation does not always beat assigned goals in terms of performance."}},{"itemId":"408968dc-c330-5628-aaf0-8079e0e1cbf1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"580c7dfa-a13f-5efe-b14a-712dbb1fdfdd","sourceKey":"bank:AMS101:M101-T8N-077","parentItemId":null,"revision":1,"payload":{"prompt":"In goal-setting theory, a person's belief that they are capable of performing a task is called:","options":["Goal commitment","Self-efficacy","Valence","Instrumentality"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Self-efficacy is a person's belief that they can do the task, and it affects how well goal-setting works. Option A, goal commitment, is how determined someone is to reach the goal, not their belief in their own ability."}},{"itemId":"d1979c03-050d-5bb5-8473-a543010f7098","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7e7470af-e160-50a9-8dc5-11d753c84f55","sourceKey":"bank:AMS101:M101-T8N-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT listed as a condition that affects the results of goal-setting?","options":["Self-efficacy","Hygiene factors","National culture","Goal commitment"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Goal commitment, self-efficacy, the type of task and national culture all affect how well goals work. Hygiene factors come from Herzberg's two-factor theory and are not a condition of goal-setting."}},{"itemId":"3748ff04-ecb8-5a3d-9d41-4f306293f716","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f4733b7-564d-5452-a4be-3438d9eb2299","sourceKey":"bank:AMS101:M101-T8N-079","parentItemId":null,"revision":1,"payload":{"prompt":"Management by objectives (MBO), in which goals are agreed between manager and employee, applies the ideas of:","options":["Reinforcement theory","Equity theory","Herzberg's two-factor theory","Goal-setting theory"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"MBO uses goals agreed between manager and employee, which is the goal-setting idea in practice. Option A, reinforcement theory, focuses on consequences after behaviour rather than on goals set beforehand."}},{"itemId":"cc38e2dd-eb5f-54f9-b110-d8ce0b751bfe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a75a9be-da7c-5c5d-9805-a425b2c613a0","sourceKey":"bank:AMS101:M101-T8N-080","parentItemId":null,"revision":1,"payload":{"prompt":"The theory which holds that behaviour is a function of its consequences is:","options":["Reinforcement theory","Goal-setting theory","Expectancy theory","Equity theory"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Reinforcement theory says behaviour is a function of its consequences. Option B, goal-setting, looks at the goal before the action rather than the consequence after it."}},{"itemId":"a55ba8a8-bdc2-592d-ada0-241330c52d99","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2b43962e-d215-52f9-8624-5828cc8b7665","sourceKey":"bank:AMS101:M101-T8N-081","parentItemId":null,"revision":1,"payload":{"prompt":"Consequences that, coming immediately after a behaviour, increase the chance that the behaviour will be repeated are called:","options":["Hygiene factors","Motivators","Referents","Reinforcers"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Reinforcers are consequences that follow a behaviour straight away and make it more likely to happen again. Option B, motivators, is Herzberg's term for job factors that create satisfaction."}},{"itemId":"a2fcd06a-13a8-5ad3-bd00-9dab22b9665d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a5422929-c237-5bf7-bf4a-ce90fc2f85b6","sourceKey":"bank:AMS101:M101-T8N-082","parentItemId":null,"revision":1,"payload":{"prompt":"Reinforcement theory is most closely linked with:","options":["B. F. Skinner","Douglas McGregor","Victor Vroom","Edwin Locke"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Reinforcement theory is linked to B. F. Skinner. Option D, Edwin Locke, is the name behind goal-setting theory."}},{"itemId":"aa27eb10-c470-51a9-bf72-fffec2bfe44a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c28649b9-27b5-5f3a-85b9-fe8c32576bdc","sourceKey":"bank:AMS101:M101-T8N-083","parentItemId":null,"revision":1,"payload":{"prompt":"Reinforcement theory differs from most other motivation theories because it:","options":["Focuses mainly on the goals people set before acting","Depends on comparisons with relevant others","Is built on a fixed hierarchy of five needs","Ignores inner needs, goals and expectations and looks only at consequences"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Reinforcement theory ignores inner needs, goals and expectations and looks only at what happens after a person acts. Option A describes goal-setting theory instead."}},{"itemId":"37e82e21-51ce-5acd-8ce8-5f6a497cbcc2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c47a24bd-4792-56cc-a445-48c94c18750d","sourceKey":"bank:AMS101:M101-T8N-084","parentItemId":null,"revision":1,"payload":{"prompt":"According to reinforcement theory, how should managers deal with unwanted behaviour where possible?","options":["Reward it so it stops naturally","Ignore it rather than punish it","Set a harder goal for the employee","Punish it immediately every time"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Managers should ignore rather than punish unwanted behaviour where possible. Option D is tempting, but punishment's effect is often temporary and it can have unpleasant side effects."}},{"itemId":"f33afbe9-00aa-5a60-96cc-9c0972e867f3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"57118a91-42ef-529a-9307-28ffebb53d7c","sourceKey":"bank:AMS101:M101-T8N-085","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about punishment is correct in reinforcement theory?","options":["It is the best long-term way to change behaviour","It has no effect on behaviour at all","It increases the chance that a behaviour will be repeated","It stops behaviour faster, but the effect is often temporary and can have unpleasant side effects"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Punishment stops behaviour faster, but the effect is often temporary and can have unpleasant side effects. Option A is wrong for that reason, which is why ignoring unwanted behaviour is preferred."}},{"itemId":"ba6b2e70-f07d-5210-a7a0-de7d3e0ce5a4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9db64cca-8068-5556-b408-749dadd8e107","sourceKey":"bank:AMS101:M101-T8N-086","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor at a factory in Ota praises a machine operator immediately after he finishes a batch ahead of schedule. The operator starts finishing early more often. This is best explained by:","options":["Reinforcement theory","Goal-setting theory","Herzberg's hygiene factors","Equity theory"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Praise given right after the behaviour acted as a reinforcer, making the behaviour more likely to be repeated. Option B would apply if a target had been set before the work began; here it is the consequence after the action that matters."}},{"itemId":"41bc7c3a-756f-514e-8043-b5c50caf80ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b98464b-3bc5-5a1a-b19a-48194069b8a6","sourceKey":"bank:AMS101:M101-T8N-087","parentItemId":null,"revision":1,"payload":{"prompt":"Goal-setting theory and reinforcement theory differ in that goal-setting focuses on __________, while reinforcement focuses on __________.","options":["The goal before the action; the consequence after the action","Job design; input-outcome ratios","The consequence after the action; the goal before the action","Inner needs; fairness of rewards"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Goal-setting is about the goal before the action, while reinforcement is about the consequence after the action. Option C simply reverses the two."}},{"itemId":"95766b0a-354a-563b-9890-000e4c54c249","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5de6f5cc-faa7-51ec-9557-e6bf0bc61595","sourceKey":"bank:AMS101:M101-T8N-088","parentItemId":null,"revision":1,"payload":{"prompt":"The way tasks are combined to form complete jobs is called:","options":["Job depth","Job scope","Job design","Job sharing"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Job design is the way tasks are combined to form complete jobs. Option B, job scope, is narrower: it is just the number of tasks a job has and how often they are repeated."}},{"itemId":"82816882-8c57-5d96-ab3a-8ce4db673124","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9c5c92f8-8764-5f4d-8c6d-dfef39b2d782","sourceKey":"bank:AMS101:M101-T8N-089","parentItemId":null,"revision":1,"payload":{"prompt":"The number of different tasks a job requires and how often those tasks are repeated is known as:","options":["Job scope","Task identity","Job depth","Job design"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Job scope is the number of different tasks in a job and how often they are repeated. Option C, job depth, is the degree of control employees have over their work."}},{"itemId":"6eea2a84-447f-5276-95e8-da3a82c2a413","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"42484971-366d-5b01-a213-ef1ebd492995","sourceKey":"bank:AMS101:M101-T8N-090","parentItemId":null,"revision":1,"payload":{"prompt":"The degree of control employees have over their work is called:","options":["Job enlargement","Skill variety","Job scope","Job depth"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Job depth is the degree of control employees have over their work. Option C, job scope, counts the tasks in the job rather than the control the person has over them."}},{"itemId":"29537c3c-858c-5284-8940-6a58a0612606","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1d456a48-776a-50b7-ac55-d86b8ff3dc08","sourceKey":"bank:AMS101:M101-T8N-091","parentItemId":null,"revision":1,"payload":{"prompt":"Horizontal expansion of a job by increasing job scope is known as:","options":["Job rotation","Job enrichment","Job enlargement","Job sharing"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Job enlargement expands a job horizontally by adding more tasks of the same kind, increasing its scope. Option B, job enrichment, is vertical expansion that adds planning and evaluating responsibilities."}},{"itemId":"5ae2d0cf-1d4b-50da-9175-b099c79568f0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"67565a6f-0581-538c-9df0-9bbaebc22383","sourceKey":"bank:AMS101:M101-T8N-092","parentItemId":null,"revision":1,"payload":{"prompt":"Vertical expansion of a job by adding planning and evaluating responsibilities is known as:","options":["Job enrichment","Compressed workweek","Job enlargement","Job scope"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Job enrichment expands a job vertically by adding planning and evaluating responsibilities. Option C, job enlargement, only adds more tasks of the same kind without more control."}},{"itemId":"82bd9c01-5f12-5996-b940-1c943cf999e3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6a3bfc3b-764d-5376-9cfb-1099138869fa","sourceKey":"bank:AMS101:M101-T8N-093","parentItemId":null,"revision":1,"payload":{"prompt":"Job enlargement and job enrichment are respectively described as:","options":["Financial and non-financial incentives","Vertical and horizontal expansion of a job","Horizontal and vertical expansion of a job","Increases in job depth and job scope"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Enlargement is horizontal (more tasks) and enrichment is vertical (more responsibility). Option B reverses them, and option D reverses the link to scope and depth."}},{"itemId":"964b5423-36be-549c-a399-5f751f6b1301","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9644d0de-c813-526a-a067-fea0e9e04609","sourceKey":"bank:AMS101:M101-T8N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Job enrichment increases a job's:","options":["Hygiene factors","Depth","Number of same-level tasks","Scope only"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Job enrichment increases job depth, meaning the employee gains more control through planning and evaluating responsibilities. Option D describes job enlargement, which raises scope."}},{"itemId":"f346d303-da7c-5b54-a466-fad65ab61ce9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7b198034-878a-578d-8f44-a25ab862cddd","sourceKey":"bank:AMS101:M101-T8N-095","parentItemId":null,"revision":1,"payload":{"prompt":"A clerk at a bank in Lagos who used to only sort mail is now also asked to deliver it and copy documents. His level of control over the work is unchanged. This is an example of:","options":["Telecommuting","Job sharing","Job enlargement","Job enrichment"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Adding more tasks of the same kind without more control is job enlargement. Option D, job enrichment, would require giving him planning or evaluating responsibilities."}},{"itemId":"333f858d-346a-5070-95d9-80963d329f89","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de202e6d-9c91-5488-a183-39bfbf1d17b6","sourceKey":"bank:AMS101:M101-T8N-096","parentItemId":null,"revision":1,"payload":{"prompt":"A records officer at a hospital in Ibadan is now allowed to plan the delivery routes for files and check the quality of the work done. This is an example of:","options":["Job enlargement","Job scope reduction","Flextime","Job enrichment"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Adding planning and quality-checking duties gives the officer more control and responsibility, which is job enrichment. Option A, job enlargement, would only add more tasks at the same level."}},{"itemId":"de7f0111-e38e-5fe5-b861-c913b2ec4864","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"67354f18-c33b-5859-ab13-b5fe0f03b03b","sourceKey":"bank:AMS101:M101-T8N-097","parentItemId":null,"revision":1,"payload":{"prompt":"The job characteristics model (JCM) was developed by:","options":["Locke and Latham","Hackman and Oldham","Victor Vroom","J. Stacy Adams"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Hackman and Oldham developed the job characteristics model with its five core job dimensions. Option A, Locke and Latham, are associated with goal-setting theory."}},{"itemId":"c6586598-4ac2-57fc-be7f-81d504324aaa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"439de1e8-c87a-5fa3-b617-997ed2ea6c16","sourceKey":"bank:AMS101:M101-T8N-098","parentItemId":null,"revision":1,"payload":{"prompt":"How many core job dimensions are there in the job characteristics model?","options":["Four","Five","Six","Three"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"The JCM has five core dimensions: skill variety, task identity, task significance, autonomy and feedback. Option D, three, is the number of critical psychological states, not the dimensions."}},{"itemId":"aab73427-006a-52ad-91fb-6e0ffbb8b5fe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e34511b2-2822-5bcf-9535-55008c9fc7a6","sourceKey":"bank:AMS101:M101-T8N-099","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five core job dimensions in the job characteristics model?","options":["Growth-need strength","Autonomy","Task identity","Skill variety"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Growth-need strength is a personal trait that affects how well the model works, not a core job dimension. Options B, C and D are all among the five core dimensions."}},{"itemId":"cd3fed28-ff58-5616-8e9e-4ab4cd0415ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e56763b4-cff1-547e-8f3a-d943e646de78","sourceKey":"bank:AMS101:M101-T8N-100","parentItemId":null,"revision":1,"payload":{"prompt":"In the JCM, the degree to which a job requires a range of activities, skills and talents is called:","options":["Task identity","Task significance","Job depth","Skill variety"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Skill variety is how far a job needs a range of activities, skills and talents. Option A, task identity, is about completing a whole, identifiable piece of work."}},{"itemId":"ca632045-c5e3-55f2-bd8b-18cf43385a84","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"72b1e37f-552b-5b23-9f6d-5f41e8cf6c25","sourceKey":"bank:AMS101:M101-T8N-101","parentItemId":null,"revision":1,"payload":{"prompt":"The JCM dimension describing how far a job requires completion of a whole, identifiable piece of work is:","options":["Task significance","Feedback","Task identity","Skill variety"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Task identity is the degree to which a job involves completing a whole, identifiable piece of work. Option A, task significance, is about how much the job affects other people."}},{"itemId":"989e411a-1da0-5f5b-98cd-715e9dde764f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2fceb222-e891-59c6-a9be-dcc9bae626ad","sourceKey":"bank:AMS101:M101-T8N-102","parentItemId":null,"revision":1,"payload":{"prompt":"A nurse at a teaching hospital in Lagos knows that her work directly affects whether patients recover. Which core job dimension is high in her job?","options":["Autonomy","Task identity","Skill variety","Task significance"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Task significance is how much a job affects the lives or work of other people, which is clearly high for a nurse. Option B, task identity, is about completing a whole piece of work, not the impact on others."}},{"itemId":"ee69ef6e-1b7f-59f2-b2fc-0e10c7f97a22","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"842e810f-0f63-5e0c-b46b-184a617f9710","sourceKey":"bank:AMS101:M101-T8N-103","parentItemId":null,"revision":1,"payload":{"prompt":"In the job characteristics model, freedom and discretion in scheduling the work and choosing methods is called:","options":["Job scope","Autonomy","Feedback","Task identity"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Autonomy is the freedom and discretion a worker has over scheduling and methods. Option A, job scope, is simply the number of tasks in the job and how often they are repeated."}},{"itemId":"5aead34f-1883-56d2-a271-f7fb7e6d40b6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa693697-401e-5252-8950-dc113ab48e5a","sourceKey":"bank:AMS101:M101-T8N-104","parentItemId":null,"revision":1,"payload":{"prompt":"In the JCM, direct and clear information about how well one is performing is called:","options":["Task significance","Autonomy","Reinforcement","Feedback"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Feedback is the core dimension that gives direct, clear information on how well one is performing. Option C, reinforcement, is a separate theory about consequences that follow behaviour."}},{"itemId":"0ddcd1c5-6017-5d1f-85a5-a82074a49a40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71337e0c-3572-5fab-b957-cddfcdb7058f","sourceKey":"bank:AMS101:M101-T8N-105","parentItemId":null,"revision":1,"payload":{"prompt":"How many critical psychological states does the job characteristics model identify?","options":["Five","Two","Four","Three"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The JCM identifies three critical psychological states: experienced meaningfulness, experienced responsibility and knowledge of actual results. Option A, five, is the number of core job dimensions."}},{"itemId":"b50a6900-2978-5f37-a787-6700f00ddfd1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"843d02a8-b4f0-5c6f-826b-f54c5af0031c","sourceKey":"bank:AMS101:M101-T8N-106","parentItemId":null,"revision":1,"payload":{"prompt":"In the job characteristics model, autonomy leads to which critical psychological state?","options":["High growth-need strength","Knowledge of the actual results of the work","Experienced responsibility for outcomes","Experienced meaningfulness of the work"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Autonomy leads to experienced responsibility for outcomes. Option D, experienced meaningfulness, comes from skill variety, task identity and task significance together."}},{"itemId":"bed29a10-7a5a-57a6-be3c-552b4866347a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"60fed675-d640-56a7-805f-4a4d1dcdd3ef","sourceKey":"bank:AMS101:M101-T8N-107","parentItemId":null,"revision":1,"payload":{"prompt":"In the job characteristics model, the feedback dimension leads to:","options":["Low growth-need strength","Experienced meaningfulness of the work","Knowledge of the actual results of the work","Experienced responsibility for outcomes"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Feedback gives the worker knowledge of the actual results of the work. Option D is produced by autonomy, not feedback."}},{"itemId":"8deac1a8-8141-506f-a9c4-ef805f7026f7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5118618b-0889-5626-9277-9f9b79f956d7","sourceKey":"bank:AMS101:M101-T8N-108","parentItemId":null,"revision":1,"payload":{"prompt":"Which three core job dimensions combine to produce experienced meaningfulness of the work?","options":["Skill variety, task identity and task significance","Task significance, autonomy and feedback","Autonomy, feedback and skill variety","Task identity, autonomy and feedback"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Skill variety, task identity and task significance together create experienced meaningfulness. Option C is wrong because autonomy and feedback lead to the other two states."}},{"itemId":"d28dfbc3-1b1a-5e22-9eb6-31da386c411f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3998cb8c-da08-55ad-af64-f4b37603a194","sourceKey":"bank:AMS101:M101-T8N-109","parentItemId":null,"revision":1,"payload":{"prompt":"When the three critical psychological states are present, which of the following is NOT an expected outcome?","options":["High absenteeism and turnover","High-quality performance","High internal work motivation","High satisfaction"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The outcomes are high internal motivation, high-quality performance, high satisfaction and low absenteeism and turnover. High absenteeism is the opposite of what the model predicts."}},{"itemId":"a9a8d21a-e47e-5252-a3ba-20c989fa234c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"25b23f02-4ce2-54d3-adac-5708fa0781de","sourceKey":"bank:AMS101:M101-T8N-110","parentItemId":null,"revision":1,"payload":{"prompt":"The job characteristics model works best for employees who:","options":["Have high growth-need strength","Prefer close supervision","Are motivated mainly by pay","Have a high need for affiliation"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The model works best for people with high growth-need strength, who want to grow on the job. Option D is a McClelland need, not the condition the JCM depends on."}},{"itemId":"2e3b9da1-d0a4-5868-a698-0dc50b92c790","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f35fb681-c5f1-5383-9071-78fbae5c25da","sourceKey":"bank:AMS101:M101-T8N-111","parentItemId":null,"revision":1,"payload":{"prompt":"Equity theory of motivation was developed by:","options":["Frederick Herzberg","Victor Vroom","J. Stacy Adams","Edwin Locke"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"J. Stacy Adams developed equity theory, in which employees compare their input-outcome ratios with others. Option B, Vroom, is the name behind expectancy theory, another process theory."}},{"itemId":"7eaf7955-9bc3-5758-989f-cd87f934dd47","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa43921b-8f6a-5a2f-96d2-46a2fe17af94","sourceKey":"bank:AMS101:M101-T8N-112","parentItemId":null,"revision":1,"payload":{"prompt":"Equity theory proposes that an employee:","options":["Acts according to the expectation that effort will lead to a valued outcome","Is motivated by specific and challenging goals","Moves up a hierarchy once lower needs are satisfied","Compares their job's input-outcome ratio with that of relevant others and acts to correct any inequity"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Equity theory says employees compare their input-outcome ratio with relevant others and act to correct any unfairness. Option A describes Vroom's expectancy theory."}},{"itemId":"c195d0a6-ce5b-5bc6-af0d-362f2196c30b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a2d3225b-5bdd-5868-8c59-9a10d896855f","sourceKey":"bank:AMS101:M101-T8N-113","parentItemId":null,"revision":1,"payload":{"prompt":"In equity theory, which of the following is an INPUT?","options":["Recognition","Education","Pay","Promotion"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Inputs are what the employee brings to the job, such as effort, experience, education and skill. Options A, C and D are outcomes the employee receives."}},{"itemId":"49f46bbf-7693-5909-9eaf-2b9702290196","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bfdd8b40-9159-56ea-94c2-e999acc2c677","sourceKey":"bank:AMS101:M101-T8N-114","parentItemId":null,"revision":1,"payload":{"prompt":"In equity theory, which of the following is an OUTCOME?","options":["Effort","Skill","Experience","Promotion"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Outcomes are what the employee gets from the job, such as pay, recognition and promotion. Options A, B and C are inputs the employee contributes."}},{"itemId":"a0d65cf2-b8d2-5b7d-9b3c-fc5d8c67cc63","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ef4caed3-b6f0-5c4f-ac5b-22434e30386e","sourceKey":"bank:AMS101:M101-T8N-115","parentItemId":null,"revision":1,"payload":{"prompt":"How many referents do employees use for comparison in equity theory?","options":["Two","Five","Three","Four"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"There are three referents: other, system and self. Option A leaves one out, often the system referent of pay policies and procedures."}},{"itemId":"d074d05a-391e-50f3-b09f-15e7aafa588f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3bd47fa8-b0c3-5f40-80f9-23033d7a7c53","sourceKey":"bank:AMS101:M101-T8N-116","parentItemId":null,"revision":1,"payload":{"prompt":"In equity theory, when an employee compares themselves with the organization's pay policies and procedures, the referent being used is:","options":["Self","Valence","Other","System"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"The system referent is the organization's pay policies and procedures. Option C, other, refers to people such as colleagues in similar jobs, friends, neighbours or professional associates."}},{"itemId":"14dd2163-a70e-501c-8094-11b01dc44eae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"05ae71ff-f8a0-54d8-8f26-e8af33c55ac6","sourceKey":"bank:AMS101:M101-T8N-117","parentItemId":null,"revision":1,"payload":{"prompt":"A machinist in an Ota factory judges his present pay against what he earned in his own previous job. Which equity referent is he using?","options":["Self","Instrumentality","System","Other"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The self referent is the person's own past experience, such as an earlier job. Option D, other, would mean comparing with another person, such as a co-worker or friend."}},{"itemId":"288f4b28-b1e3-5c79-a846-8bbfaf7a6557","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3d807d96-5098-5192-9426-a1a4879b34c7","sourceKey":"bank:AMS101:M101-T8N-118","parentItemId":null,"revision":1,"payload":{"prompt":"An accountant at a Lagos bank compares her rewards with those of a friend who does a similar job at another firm. Which referent is she using?","options":["Other","Expectancy","System","Self"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The other referent includes people in similar jobs in the same organization, plus friends, neighbours or professional associates. Option D, self, would mean comparing with her own past experience."}},{"itemId":"07b08279-aa30-57f6-a7ce-df255e4f6bc5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"adfc5bb6-a203-56ce-8912-c2f00565821e","sourceKey":"bank:AMS101:M101-T8N-119","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde, a lecturer, believes he puts in the same effort and qualifications as a colleague in his department but receives far lower outcomes. In equity theory, Tunde feels:","options":["Under-rewarded","Self-actualized","Over-rewarded","Fairly treated"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"When an employee's input-outcome ratio is lower than a referent's, they feel under-rewarded. Option C applies when the employee gets more outcomes than their inputs justify compared with others."}},{"itemId":"9bc0fcd6-f239-5375-88c3-0fa83cee3997","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2801668-b3ab-5fff-8d9e-244c6d8398ce","sourceKey":"bank:AMS101:M101-T8N-120","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a likely response to perceived inequity?","options":["Moving up to the next level of Maslow's hierarchy","Choosing a different referent","Quitting the job","Changing one's own inputs, for example by working less"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Responses to inequity include distorting inputs or outcomes, getting others to change theirs, changing one's own inputs or outcomes, choosing a different referent or quitting. Moving up Maslow's hierarchy belongs to a different theory and is not a response to inequity."}},{"itemId":"61d59346-fb6e-5d06-a07b-cf3006b5f37b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"048ee32c-cc66-58d9-bd69-b6063e67fe29","sourceKey":"bank:AMS101:M101-T8N-121","parentItemId":null,"revision":1,"payload":{"prompt":"The perceived fairness of the amount and allocation of rewards among people is called:","options":["Procedural justice","Equity sensitivity","Distributive justice","Instrumentality"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Distributive justice is about the fairness of the amount and allocation of rewards. Option A, procedural justice, is about the fairness of the process used to decide those rewards."}},{"itemId":"62fc29ec-d7ea-5f6c-8f3f-f8f82c28bdde","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9aedeeaa-1e17-55dc-b6fc-209bdd911cae","sourceKey":"bank:AMS101:M101-T8N-122","parentItemId":null,"revision":1,"payload":{"prompt":"The perceived fairness of the process used to decide how rewards are shared is known as:","options":["Distributive justice","Valence","Procedural justice","Open-book management"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Procedural justice concerns the fairness of the process used to share rewards. Option A, distributive justice, concerns the fairness of the amounts people actually receive."}},{"itemId":"5e5973ce-5185-5575-944d-4ca4cd501a0e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3a638705-458e-5a0e-817b-1223e870a31a","sourceKey":"bank:AMS101:M101-T8N-123","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with procedural justice, distributive justice has a greater effect on employees':","options":["Trust in the boss","Intention to quit","Commitment to the organization","Satisfaction"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Distributive justice has more effect on satisfaction. Options A, B and C are the things procedural justice affects more: trust in the boss, commitment and intention to quit."}},{"itemId":"e139a48d-561d-5dc9-aaee-bed9a7aeae27","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"80bdfc1f-584b-57db-a5b0-0982f3908c4d","sourceKey":"bank:AMS101:M101-T8N-124","parentItemId":null,"revision":1,"payload":{"prompt":"Expectancy theory of motivation is associated with:","options":["Victor Vroom","B. F. Skinner","David McClelland","J. Stacy Adams"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Victor Vroom proposed expectancy theory, built on expectancy, instrumentality and valence. Option D, Adams, developed equity theory, which is about fairness comparisons."}},{"itemId":"964a8a6c-c49d-553f-8a1f-b8b7575f2b5e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"71b4950f-afba-5938-8d40-cb137b9edf20","sourceKey":"bank:AMS101:M101-T8N-125","parentItemId":null,"revision":1,"payload":{"prompt":"Expectancy theory states that a person acts in a certain way based on:","options":["The expectation that the act will be followed by a given outcome and how attractive that outcome is","The consequences that followed similar behaviour in the past","The lowest unsatisfied need in a hierarchy","A comparison of their input-outcome ratio with that of others"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Vroom's theory says behaviour depends on the expectation that an act leads to an outcome and on how attractive that outcome is. Option D describes equity theory instead."}},{"itemId":"0212a6cd-2ba2-5a9a-9899-4a73400b64e2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf58be0c-64c4-5d95-bd6c-fc14d5151c5e","sourceKey":"bank:AMS101:M101-T8N-126","parentItemId":null,"revision":1,"payload":{"prompt":"In expectancy theory, the effort-performance linkage ('If I work hard, will I perform well?') is called:","options":["Valence","Instrumentality","Expectancy","Equity"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Expectancy is the effort-performance linkage. Option B, instrumentality, is the next link, from performance to reward."}},{"itemId":"306f8d4f-d162-5cf9-a449-c9be72e57e3c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b6377960-e950-5f14-896a-7edffd8ffa22","sourceKey":"bank:AMS101:M101-T8N-127","parentItemId":null,"revision":1,"payload":{"prompt":"In Vroom's theory, the performance-reward linkage ('If I perform well, will I get the reward?') is known as:","options":["Reinforcement","Valence","Instrumentality","Expectancy"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Instrumentality is the belief that good performance will lead to the reward. Option D, expectancy, is the earlier link between effort and performance."}},{"itemId":"06107b88-0ad6-586b-bbe1-e9da14f60165","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2179cb6d-4733-5cf1-b609-b497fa8c407e","sourceKey":"bank:AMS101:M101-T8N-128","parentItemId":null,"revision":1,"payload":{"prompt":"In expectancy theory, the attractiveness of a reward to the worker is called:","options":["Valence","Expectancy","Self-efficacy","Instrumentality"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Valence is how much the worker values the reward. Option D, instrumentality, is whether performance will actually lead to that reward."}},{"itemId":"51d2067f-d1d4-5d94-89ef-169879381643","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"195910b7-ed17-579a-9b14-bbb4c69d8f7b","sourceKey":"bank:AMS101:M101-T8N-129","parentItemId":null,"revision":1,"payload":{"prompt":"Kemi, a teller at a bank in Lagos, believes that working hard will improve her performance, but doubts management will actually pay the promised bonus for good results. Which expectancy linkage is weak?","options":["Expectancy","Equity","Instrumentality","Valence"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Doubting that good performance will bring the reward is a weak instrumentality, the performance-reward link. Option A, expectancy, is fine here because she believes effort will lead to good performance."}},{"itemId":"250d8a52-3636-5299-a19d-f9c1f33a2381","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4af9543c-2e88-538e-88c8-306b10b63b23","sourceKey":"bank:AMS101:M101-T8N-130","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota offers top performers a free golf club membership, but most of its workers have no interest in golf. In expectancy terms, this reward is low in:","options":["Instrumentality","Task identity","Expectancy","Valence"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Valence is how attractive the reward is to the worker, and a reward people do not value has low valence. Option A, instrumentality, is about whether performance actually leads to the reward, which is not in doubt here."}},{"itemId":"35661bb1-fb5c-5dee-90f9-9f11631bbd77","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b4ef2bb-a3a0-5e51-9fc2-511e48a753a2","sourceKey":"bank:AMS101:M101-T8N-131","parentItemId":null,"revision":1,"payload":{"prompt":"According to expectancy theory, when will motivation be low?","options":["Only when the reward has no cash value","Only when the worker's referent is the system","When any one of the three linkages is weak","Only when all three linkages are weak"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Motivation is low if any one linkage is weak: effort that does not lead to results, results that are not rewarded, or rewards the worker does not value. Option D is wrong because a single weak link is enough to kill effort."}},{"itemId":"0c0bb2b7-2516-59e4-b57e-6f2687f42a1e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d02668dc-e1bd-5928-8705-35d84a11a855","sourceKey":"bank:AMS101:M101-T8N-132","parentItemId":null,"revision":1,"payload":{"prompt":"In expectancy theory, what matters most in determining a worker's effort?","options":["The organization's written policies","The worker's perception of the linkages","The manager's opinion of the worker","The actual facts about pay levels"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"What counts in expectancy theory is the worker's perception, not the facts. Option D is wrong because even real rewards will not motivate if the worker does not believe in them."}},{"itemId":"61c282ce-6e10-5f50-aaf0-a22bf3bf8d84","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"77148e29-8a9a-518b-9d5d-8fb01b1fc900","sourceKey":"bank:AMS101:M101-T8N-133","parentItemId":null,"revision":1,"payload":{"prompt":"When the motivation theories are integrated into one model, which theory forms the base?","options":["Expectancy theory","Herzberg's two-factor theory","Maslow's hierarchy of needs","Reinforcement theory"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Expectancy theory forms the base of the integrated model, linking effort, performance, rewards and goals. Option B, reinforcement, plays a part by explaining how rewards reinforce behaviour, but it is not the foundation."}},{"itemId":"0185594c-7591-5423-a392-8d08c0b46659","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e919b580-dbdb-5ed6-8c1d-93d1c03ffe30","sourceKey":"bank:AMS101:M101-T8N-134","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the core chain in the integrated model of motivation?","options":["Individual goals, organizational rewards, individual effort, individual performance","Individual effort, individual performance, organizational rewards, individual goals","Individual performance, individual effort, individual goals, organizational rewards","Organizational rewards, individual effort, individual goals, individual performance"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"The integrated model runs from individual effort to individual performance, then to organizational rewards and finally to individual goals. Option A reverses the chain, putting goals and rewards before effort."}},{"itemId":"bcc4a4a5-2328-5dca-b4dd-8e9617d80821","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"54c56413-8a71-5f13-bdb5-790b0cf5bcf8","sourceKey":"bank:AMS101:M101-T8N-135","parentItemId":null,"revision":1,"payload":{"prompt":"In the integrated model of motivation, the requirement that rewards must feel fair comes from:","options":["The job characteristics model","Goal-setting theory","Equity theory","Reinforcement theory"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Equity theory adds the idea that rewards must feel fair compared with others. Option D, reinforcement, contributes the idea that rewards strengthen behaviour, not that they must be fair."}},{"itemId":"ade5b52b-6ca5-5787-a690-d2429c16fb42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"43b399d1-0bd1-53d7-9f3b-4c0f4f9d7eed","sourceKey":"bank:AMS101:M101-T8N-136","parentItemId":null,"revision":1,"payload":{"prompt":"In the integrated model, the idea that a well-designed job raises motivation directly comes from:","options":["Reinforcement theory","The job characteristics model","Goal-setting theory","Equity theory"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"The job characteristics model contributes the idea that a well-designed job raises motivation directly. Option C, goal-setting, contributes the idea that goals direct effort."}},{"itemId":"052f6e20-833c-50b2-a19a-9d8b56333960","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9239c62a-8d87-55b2-a116-cb32cb9d33e9","sourceKey":"bank:AMS101:M101-T8N-137","parentItemId":null,"revision":1,"payload":{"prompt":"Besides individual effort, what else does the integrated model say affects individual performance?","options":["The number of hygiene factors present","The worker's need for affiliation","The opportunity to perform","The worker's referent"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"The integrated model says that the opportunity to perform also affects performance. Option D, the referent, belongs to equity theory and concerns fairness comparisons, not performance itself."}},{"itemId":"2a3a0497-f13e-59a9-a028-2496677131c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"807d4e77-dc5c-5d28-88f7-e296b67864c7","sourceKey":"bank:AMS101:M101-T8N-138","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing of motivation theory and theorist is correct?","options":["Reinforcement theory - B. F. Skinner","Goal-setting theory - Hackman and Oldham","Three-needs theory - Frederick Herzberg","Equity theory - Victor Vroom"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Reinforcement theory is linked to B. F. Skinner. Option D is wrong because equity theory belongs to J. Stacy Adams, while Vroom proposed expectancy theory."}},{"itemId":"de51537a-192a-525d-819d-f3c9c8c09a3e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f224a609-2fcc-5d7f-acd2-5c36ef8be54b","sourceKey":"bank:AMS101:M101-T8N-139","parentItemId":null,"revision":1,"payload":{"prompt":"Why do most motivation theories face cross-cultural challenges?","options":["They were mostly developed in the United States, so they do not fit every culture","They apply only to contingent workers","They were developed only for low-skilled workers","They ignore the role of pay entirely"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Most motivation theories were developed in the United States, so they do not fit every culture. Option B is wrong because pay plays a role in several theories, for example as a hygiene factor."}},{"itemId":"ed37248d-c4aa-5f8d-bd5b-b71a2bc1c03c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5f2dbcb6-2b65-5fde-9eb7-7e85050517d2","sourceKey":"bank:AMS101:M101-T8N-140","parentItemId":null,"revision":1,"payload":{"prompt":"In cultures where people strongly avoid uncertainty, which of Maslow's needs may sit at the top of the hierarchy?","options":["Social","Physiological","Safety","Esteem"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Where people strongly avoid uncertainty, safety needs can sit at the top. Option A, social needs, rise to the top in cultures that value caring and relationships most."}},{"itemId":"fc8a5cd4-6a26-52cb-b512-87326d8fb3ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"350c3900-9aaa-51e4-9546-166a0790ded6","sourceKey":"bank:AMS101:M101-T8N-141","parentItemId":null,"revision":1,"payload":{"prompt":"In cultures where caring and relationships are valued most, which of Maslow's needs may sit at the top?","options":["Safety","Social","Esteem","Self-actualization"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"In cultures that value caring and relationships most, social needs can sit at the top. Option A, safety, tends to move to the top where people strongly avoid uncertainty."}},{"itemId":"ab945fce-d4b5-563d-a619-97f1dce8e2f9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"19f61e32-7eec-5318-ab53-86ac9ce74a0c","sourceKey":"bank:AMS101:M101-T8N-142","parentItemId":null,"revision":1,"payload":{"prompt":"Which motivating factors appear to be desired across cultures?","options":["Interesting work, growth and achievement","High pay, job security and company policy","Status, power and close control","Close supervision and fixed hours"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"The desire for interesting work, growth and achievement appears across cultures, and these are Herzberg's motivators. Option B lists mainly hygiene factors, which only prevent dissatisfaction."}},{"itemId":"ae1ff9cf-f5f4-587c-8f4d-aedede13c488","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"713a24da-6d93-5a7c-8840-0bebd4540a46","sourceKey":"bank:AMS101:M101-T8N-143","parentItemId":null,"revision":1,"payload":{"prompt":"McClelland's high achiever, who accepts moderate risk and cares about performance, fits best in cultures like that of:","options":["Every culture equally","Cultures that strongly avoid uncertainty","The United States","Cultures that value relationships above performance"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"McClelland's high achiever fits cultures like the United States. Option A is wrong because this profile does not fit every culture equally, which is exactly the cross-cultural challenge."}},{"itemId":"f62b9bd1-3122-5d41-ab65-bd8e21e29c6a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8bf49726-d410-5ffc-a6d4-61497796a817","sourceKey":"bank:AMS101:M101-T8N-144","parentItemId":null,"revision":1,"payload":{"prompt":"A work arrangement in which employees work longer hours per day but fewer days per week, such as four 10-hour days, is called:","options":["Flextime","Compressed workweek","Job sharing","Telecommuting"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"A compressed workweek squeezes the week into fewer, longer days. Option A, flextime, keeps a set number of weekly hours but lets workers vary their start and end times around core hours."}},{"itemId":"26362446-0618-5031-8306-9ae44ed7412f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5b81eb26-96d1-505c-a925-5d40927315aa","sourceKey":"bank:AMS101:M101-T8N-145","parentItemId":null,"revision":1,"payload":{"prompt":"At a Lagos bank, staff must work 40 hours a week and be present between 10 a.m. and 3 p.m., but each person chooses when to start and finish within limits. This arrangement is:","options":["Flextime","Telecommuting","Job sharing","Compressed workweek"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Flextime sets a number of hours per week but lets workers vary start and end times within limits, around common core hours. Option D, a compressed workweek, means fewer but longer days."}},{"itemId":"5835385d-f802-5c05-a167-abb3a709eda4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3d7c9bbb-699d-59cb-8e8f-565ed125f3eb","sourceKey":"bank:AMS101:M101-T8N-146","parentItemId":null,"revision":1,"payload":{"prompt":"Two part-time administrators at a university department split one full-time position between them. This is an example of:","options":["Job enlargement","Job sharing","Compressed workweek","Flextime"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Job sharing is when two or more people split one full-time job. Option A, job enlargement, means adding more tasks to one person's job, not dividing a job between people."}},{"itemId":"fa04c265-68fc-5f76-9e7d-ebbf111019ed","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b19601e3-1736-515b-be76-4af6a892eba2","sourceKey":"bank:AMS101:M101-T8N-147","parentItemId":null,"revision":1,"payload":{"prompt":"Working from home while linked to the workplace by computer is known as:","options":["Job sharing","Telecommuting","Open-book management","Flextime"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Telecommuting means working from home, connected to the workplace by computer. Option D, flextime, is about choosing start and end times, not working from a different place."}},{"itemId":"a9cf2520-20b1-5f6c-87f8-5cd2c1bd4ac7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8be6a6e0-ad9a-55e5-af86-1d015de5fdcf","sourceKey":"bank:AMS101:M101-T8N-148","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a flexible work arrangement?","options":["Telecommuting","Job sharing","Compressed workweek","Profit-sharing"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Profit-sharing is a pay-for-performance programme, not a flexible work arrangement. Options A, B and C, together with flextime, are the flexible arrangements used for a diverse workforce."}},{"itemId":"6e9145ef-9881-50d7-88ab-a3ccd915862e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98458bc4-885b-5053-9ada-a0cd38c403f9","sourceKey":"bank:AMS101:M101-T8N-149","parentItemId":null,"revision":1,"payload":{"prompt":"Professionals are typically motivated most by:","options":["Money and promotion above all else","Job challenge, keeping up with their field, support and recognition","Employee recognition programmes alone because pay is limited","A chance to become permanent employees"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Professionals are motivated by job challenge, keeping up with their field, and support and recognition; money and promotion usually rank low. Option D describes what motivates contingent workers."}},{"itemId":"61f5f98a-97e9-59de-abde-656aabb5e69a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a20dba23-74f2-5750-9fcb-ca26532b95fc","sourceKey":"bank:AMS101:M101-T8N-150","parentItemId":null,"revision":1,"payload":{"prompt":"The loyalty of professional employees is often directed more to:","options":["Their profession than their employer","Their immediate supervisor","Their employer than their profession","Their trade union"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Professionals' loyalty is often to their profession more than to their employer, and their work is often a central life interest. Option C reverses this relationship."}},{"itemId":"aad14089-f688-5494-a7c1-f46d39f09b37","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"632df5a0-9efe-5e01-b9dc-c44e1f0187e1","sourceKey":"bank:AMS101:M101-T8N-151","parentItemId":null,"revision":1,"payload":{"prompt":"Contingent workers are most likely to be motivated by:","options":["Job challenge and keeping up with their field","Telecommuting and job sharing","A chance to become permanent and training opportunities","Profit-sharing and lump-sum bonuses"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Contingent workers are motivated by the chance to become permanent and by training opportunities. Option A describes what motivates professionals."}},{"itemId":"f933bf1a-ea86-55c5-93fc-3496f184501e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4627e175-59a6-50fe-acc6-b8e3d291e6f9","sourceKey":"bank:AMS101:M101-T8N-152","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Port Harcourt employs temporary staff who work beside permanent staff earning more and receiving benefits. Which motivation issue should managers watch most closely?","options":["Weak need for power","Equity problems","Low task significance","Excessive job depth"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"When contingent workers work beside better-paid permanent staff with benefits, managers must watch for equity problems. Option C is not the main issue, since the concern here is the comparison of rewards between groups."}},{"itemId":"6558f3fb-6853-5aa6-b692-3b9bfa648a73","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de8d58b1-c1b2-5afd-b5e9-80f41dd0468b","sourceKey":"bank:AMS101:M101-T8N-153","parentItemId":null,"revision":1,"payload":{"prompt":"For low-skilled, minimum-wage workers, managers with limited money should rely mainly on:","options":["Employee recognition programmes and sincere praise","Large lump-sum bonuses","Open-book management alone","Long-term career development in their profession"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"With money limited, managers lean on employee recognition programmes and sincere praise for low-skilled workers. Option B is wrong because large cash rewards are exactly what limited budgets cannot provide."}},{"itemId":"cff33887-f866-518e-809f-612e3bf7f578","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"48c39717-e692-547f-824f-d8749891c2eb","sourceKey":"bank:AMS101:M101-T8N-154","parentItemId":null,"revision":1,"payload":{"prompt":"A reward approach in which an organization's financial statements are shared with all employees, who learn to read them and see how their work affects results, is:","options":["Employee recognition programme","Management by objectives","Pay-for-performance programme","Open-book management"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"Open-book management shares the financial statements with all employees so they understand how their work affects results. Option A, a recognition programme, is about personal attention and appreciation for a job well done."}},{"itemId":"6bb9a8e7-932c-562c-baff-4e9b6a7cce57","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d1b531b-3595-591d-b057-8f415d024d33","sourceKey":"bank:AMS101:M101-T8N-155","parentItemId":null,"revision":1,"payload":{"prompt":"Giving personal attention and expressing interest, approval and appreciation for a job well done describes:","options":["Job enlargement","Employee recognition programmes","Pay-for-performance programmes","Open-book management"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Employee recognition programmes involve personal attention and showing interest, approval and appreciation for good work. Option C, pay-for-performance, ties variable pay to a measure of performance instead."}},{"itemId":"314705f5-6918-57d1-aa59-66076d16ede8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a1eaea13-3488-5461-9225-407bc1c005ca","sourceKey":"bank:AMS101:M101-T8N-156","parentItemId":null,"revision":1,"payload":{"prompt":"Variable compensation plans that pay employees on the basis of some performance measure are called:","options":["Employee recognition programmes","Pay-for-performance programmes","Flexible work arrangements","Open-book management"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Pay-for-performance programmes use variable pay based on some measure of performance, such as piece-rate pay or profit-sharing. Option A, recognition programmes, rewards with attention and appreciation rather than pay."}},{"itemId":"78686dd4-4bae-55d6-a48f-c72dc61afb99","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b8c69215-ad96-5949-b5d3-ecc00c682953","sourceKey":"bank:AMS101:M101-T8N-157","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of a pay-for-performance programme?","options":["Flextime","Piece-rate pay","Profit-sharing","Lump-sum bonuses"],"correctOption":0,"section":"Motivating and Rewarding Employees","explanation":"Flextime is a flexible work arrangement, not a pay plan. Options B, C and D, together with wage incentive plans, are examples of pay-for-performance."}},{"itemId":"55dc4254-b2d1-5be5-863c-bad17cfe5525","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d73558f5-3e66-58af-99b6-de0157c1a029","sourceKey":"bank:AMS101:M101-T8N-158","parentItemId":null,"revision":1,"payload":{"prompt":"Pay-for-performance programmes are most consistent with which motivation theory?","options":["Herzberg's two-factor theory","McGregor's Theory X","Expectancy theory","Maslow's hierarchy of needs"],"correctOption":2,"section":"Motivating and Rewarding Employees","explanation":"Pay-for-performance fits expectancy theory because it ties rewards clearly to performance, strengthening the performance-reward link. Option A is less fitting, because Herzberg treats pay as a hygiene factor rather than a motivator."}},{"itemId":"879bd861-8df2-557a-bd84-57fd7e29b7a3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1339a88b-a29a-5c5d-8265-4952cb6b7982","sourceKey":"bank:AMS101:M101-T8N-159","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a NON-financial incentive?","options":["Profit-sharing","Praise","Piece-rate pay","A pay rise"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"Praise is a non-financial incentive, like recognition, job enrichment and flexible hours. Options A, C and D are all financial incentives."}},{"itemId":"833ae113-7a88-59f4-a74e-e3bb5bba5a19","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4849ec6f-a046-5b3e-bdaa-9ac397ddfbb1","sourceKey":"bank:AMS101:M101-T8N-160","parentItemId":null,"revision":1,"payload":{"prompt":"How many main ways of designing appropriate rewards to motivate employees are there?","options":["Two","Three","Five","Four"],"correctOption":1,"section":"Motivating and Rewarding Employees","explanation":"There are three approaches: open-book management, employee recognition programmes and pay-for-performance programmes. Option D is tempting if flexible work arrangements are mistakenly counted, but those are a separate issue."}},{"itemId":"0cbc9b21-de36-570e-a819-b7fa3f11eabe","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7ce2356e-e9d9-5e19-bd19-7a11bc046987","sourceKey":"bank:AMS101:M101-T8N-161","parentItemId":null,"revision":1,"payload":{"prompt":"When motivating employees in tough economic times, managers must:","options":["Rely only on punishment to maintain output","Stop all forms of recognition until conditions improve","Replace all permanent staff with contingent workers","Find creative ways to keep employees' efforts energized, directed and sustained toward goals"],"correctOption":3,"section":"Motivating and Rewarding Employees","explanation":"In tough economic times managers must find creative ways to keep employees' efforts energized, directed and sustained toward goals. Option B is wrong because recognition is low-cost and especially useful when money is tight."}},{"itemId":"cc607891-aa13-57e9-8183-9ae356bdae84","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"deb121ea-2c05-5a02-9521-b686f4d76696","sourceKey":"bank:AMS101:M101-T9N-001","parentItemId":null,"revision":1,"payload":{"prompt":"An influence process that involves motivating and inspiring people to work together to achieve a common goal is called:","options":["Delegation","Supervision","Empowerment","Leadership"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Leadership is an influence process: it motivates and inspires people so they work together towards a shared goal. Option B is overseeing subordinates' work and giving instructions, and option C is increasing workers' decision-making discretion, so neither is the influence process itself."}},{"itemId":"b23efb3b-90d4-564b-8f9f-b2fe6993551d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7950ef8a-1762-564a-9410-dae5acf17845","sourceKey":"bank:AMS101:M101-T9N-002","parentItemId":null,"revision":1,"payload":{"prompt":"A leader is best described as someone who:","options":["Can influence others and who has managerial authority","Has formal authority only over machines and materials","Holds a senior position but has no influence over others","Works alone without directing or influencing anyone"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A leader combines two things: the ability to influence others and managerial authority. Option C fails because a position without influence does not make someone a leader."}},{"itemId":"657d66a5-8e27-5d86-8a50-a1cfd7cedd78","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"486bda15-9d5a-5ce3-b670-db1d681cc973","sourceKey":"bank:AMS101:M101-T9N-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the obligations of leadership?","options":["Preparing the organization's annual financial statements","Setting clear expectations","Conflict resolution","Coaching team members"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The obligations of leadership run from developing a clear vision through motivating, setting expectations, decisions, commitment, a positive environment, delegating and coaching to conflict resolution. Preparing financial statements is an accounting task, not a leadership obligation, while options B, D and C are all on the list."}},{"itemId":"6d7a7bbe-1589-5de2-9e3d-a4b7efcedd7e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b347cbec-0f10-5e58-a40c-61bdf6a715e0","sourceKey":"bank:AMS101:M101-T9N-004","parentItemId":null,"revision":1,"payload":{"prompt":"How many obligations of leadership are commonly listed, starting with developing a clear vision and ending with conflict resolution?","options":["Five","Nine","Seven","Six"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"There are nine obligations of leadership, from developing and communicating a clear vision to conflict resolution. Option C is easy to confuse because seven is the number of traits linked with leadership, not the number of obligations."}},{"itemId":"b3ef1c83-5970-5c55-852c-581c167c152e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8f40fe1e-b285-54c5-8b7b-2b7ef8a66bec","sourceKey":"bank:AMS101:M101-T9N-005","parentItemId":null,"revision":1,"payload":{"prompt":"The head of a department at UNILAG calls two lecturers who have been quarrelling over teaching schedules and helps them reach an agreement. Which obligation of leadership is she performing?","options":["Conflict resolution","Setting clear expectations","Delegating tasks","Coaching team members"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Settling a dispute between team members so they can work together again is conflict resolution, one of the nine obligations of leadership. Option D would involve helping a member build skills, not ending a quarrel."}},{"itemId":"10f94284-9098-5c8a-b6f8-72cf91be18a5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fe026c92-29b5-572b-991b-23093390e2a7","sourceKey":"bank:AMS101:M101-T9N-006","parentItemId":null,"revision":1,"payload":{"prompt":"A branch manager at a bank in Lagos meets a new credit officer every week to help him improve how he analyses loan applications. This is an example of which leadership obligation?","options":["Making informed decisions","Delegating tasks","Conflict resolution","Coaching team members"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Working with a team member over time to improve his skills is coaching, one of the obligations of leadership. Option B would mean handing a task over to him, not developing how he does it."}},{"itemId":"b538141c-c281-58f2-bd9f-7e63b2f5bfa5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ba7280d-6a2a-59fb-846d-c2e20bd7e133","sourceKey":"bank:AMS101:M101-T9N-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following IS one of the obligations of leadership?","options":["Limiting team members' participation","Centralizing all authority in the leader","Avoiding all delegation of tasks","Fostering commitment and accountability"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Fostering commitment and accountability is one of the nine obligations of leadership. Options B and A describe autocratic behaviour, and option C is the opposite of the obligation to delegate tasks."}},{"itemId":"0234f776-6cb1-5c3b-8bd8-5da685149cc9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d9ecc1d7-c561-5d15-aff9-78f3aa65e162","sourceKey":"bank:AMS101:M101-T9N-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes a leader from a manager?","options":["A manager's influence goes beyond formal authority, while a leader's does not","A leader can be appointed or can emerge from a group, while a manager is appointed to a position","A leader focuses on planning, organizing and controlling, while a manager inspires","A manager can emerge from a group, while a leader must be appointed"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Managers are appointed, but leaders may be appointed or may simply emerge from within a group. Option A reverses the truth, because it is the leader whose influence can go beyond formal authority."}},{"itemId":"de42cfff-aa33-5cc7-bcbc-61cc9f0067d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"be7170df-1738-5ff7-b064-d02ab799ed0b","sourceKey":"bank:AMS101:M101-T9N-009","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's influence over subordinates comes mainly from:","options":["Formal authority","The readiness of followers","Emerging informally from the group","Personal charm alone"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A manager's influence comes from the formal authority of the position he is appointed to. Option D fits a leader better, since a leader's influence can go beyond formal authority."}},{"itemId":"22c9812f-1bc6-5186-9097-89ffb56c28c6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"28f0cef2-20b4-51a6-87f3-5e6d088a3bc0","sourceKey":"bank:AMS101:M101-T9N-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the main focus of a manager rather than a leader?","options":["Emerging as the voice of an informal group","Planning, organizing and controlling","Influencing and inspiring people","Inspiring followers beyond formal authority"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Managers focus on planning, organizing and controlling. Option C is the focus of a leader, which is exactly what separates leadership from management."}},{"itemId":"c89bcf75-a5e7-5a17-a343-3402bc29cd08","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"060000dd-ea2f-52c2-9fa3-f6fd8451b85f","sourceKey":"bank:AMS101:M101-T9N-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about managers and leaders is correct?","options":["A manager and a leader are always the same person","Ideally all managers should be leaders, but not all leaders have the abilities of a manager","All leaders automatically have the abilities of a manager","Managers should avoid acting as leaders"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Ideally every manager should also lead, but a person can lead without having a manager's abilities. Option C reverses this point, since leading others does not guarantee managerial ability."}},{"itemId":"344991e8-3cdd-5ece-9ce4-07a07d710e12","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e444f30-745b-5c61-a7b2-0c96b31a2cad","sourceKey":"bank:AMS101:M101-T9N-012","parentItemId":null,"revision":1,"payload":{"prompt":"Research that tried to isolate the characteristics that set leaders apart from non-leaders is known as:","options":["Path-goal theory","Contingency theories","Trait theories","Behavioural theories"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Trait theories looked for the personal characteristics that set leaders apart from non-leaders. Option D studied what leaders do rather than what they are like."}},{"itemId":"cacf32f9-6bf7-50e8-9069-bfd2585bbd30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8667c9c7-3dd5-5297-8d73-94a807588618","sourceKey":"bank:AMS101:M101-T9N-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the seven traits linked with leadership?","options":["Job-relevant knowledge","Drive","Initiating structure","Self-confidence"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Initiating structure is a leader behaviour dimension from the Ohio State studies, not a personal trait. Options B, D and A are all among the seven traits linked with leadership."}},{"itemId":"678bc377-b7b0-5693-9fff-3cedd65918a9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ddecc15-eff0-587c-ba48-64430c3499ef","sourceKey":"bank:AMS101:M101-T9N-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following IS one of the seven traits linked with leadership?","options":["Follower readiness","Position power","Consideration","Desire to lead"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Desire to lead is one of the seven leadership traits. Option C is an Ohio State behaviour dimension, option B is one of Fiedler's situational factors and option A comes from Situational Leadership Theory."}},{"itemId":"5944e22e-e273-58ec-9c38-6cc0da9e048a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b6b15bf9-6850-5b12-9e08-9a66b921ebba","sourceKey":"bank:AMS101:M101-T9N-016","parentItemId":null,"revision":1,"payload":{"prompt":"Some later lists add an eighth trait to the seven traits linked with leadership. This trait is:","options":["Proneness to guilt","Consideration","Charisma","Expert power"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Later lists add proneness to guilt, meaning a strong sense of responsibility to others. Option B is a behaviour dimension from the Ohio State studies, not a trait."}},{"itemId":"6ebbb75d-228e-5b7b-8deb-224816b10670","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a22d5c7b-499e-5655-b03d-cc03135dacad","sourceKey":"bank:AMS101:M101-T9N-017","parentItemId":null,"revision":1,"payload":{"prompt":"As a leadership trait, proneness to guilt refers to:","options":["A tendency to blame subordinates for failure","A habit of avoiding criticism from superiors","A strong sense of responsibility to others","Fear of taking any decisions"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Proneness to guilt describes a leader who feels a strong sense of responsibility to others. Option A describes the opposite, because blaming subordinates shows a lack of responsibility to them."}},{"itemId":"ebbe7630-ca21-5ae9-b800-dd017ce57893","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"11868858-0ae3-5c0c-a8bb-22878082eeac","sourceKey":"bank:AMS101:M101-T9N-018","parentItemId":null,"revision":1,"payload":{"prompt":"Staff of a hospital in Ibadan admire their medical director because she always tells the truth and keeps her promises. Which leadership trait does she show most clearly?","options":["Extraversion","Honesty and integrity","Job-relevant knowledge","Drive"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Telling the truth and keeping promises reflect honesty and integrity, one of the seven leadership traits. Option A is about being outgoing and sociable, which says nothing about truthfulness."}},{"itemId":"b2150df5-8e7e-50b1-80ff-e39e35f2ba5f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c6b29462-fff7-5772-be69-da3cca3e5815","sourceKey":"bank:AMS101:M101-T9N-019","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from the traits identified in trait research, which two qualities are also described as marks of an effective leader?","options":["Flexibility and strong communication skills","Coercive power and strict discipline","Rigidity and secrecy","Formal authority and a high job title"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Flexibility and strong communication skills are also marks of an effective leader. Option D describes things a manager gets from his position, not personal qualities that make a leader effective."}},{"itemId":"7bac5c39-9937-5356-9f4b-c0a0e260be1a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"329dbe8e-713c-5646-89d6-c8e4680846a3","sourceKey":"bank:AMS101:M101-T9N-020","parentItemId":null,"revision":1,"payload":{"prompt":"What was the main weakness of trait theories of leadership?","options":["They focused only on what leaders do rather than who they are","They studied followers' readiness instead of the leader","They insisted that a leader's style can never change","They ignored the situation and the interaction between leader and group"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Traits alone could not explain leadership, because trait theories ignored the situation and how the leader and group interact. Option A describes behavioural theories, which came after trait theories."}},{"itemId":"fd5306d0-1fa0-55b3-9430-fe03e2088818","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"04b5c780-fcc3-5610-a464-0b72a4aa9ee3","sourceKey":"bank:AMS101:M101-T9N-021","parentItemId":null,"revision":1,"payload":{"prompt":"What do trait theories conclude about a person who has the traits linked with leadership?","options":["The person is only more likely to be an effective leader","The person no longer needs managerial authority","The person is certain to become an effective leader","The person will be effective in every situation"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Having the traits only makes a person more likely to be an effective leader. It does not guarantee success, so options C and D claim too much, since the situation also matters."}},{"itemId":"6232a1a2-404d-5386-8665-afb0dc68398f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"42edc996-9590-5945-a848-f1080990384e","sourceKey":"bank:AMS101:M101-T9N-022","parentItemId":null,"revision":1,"payload":{"prompt":"The failure of trait theories to fully explain leadership pushed researchers to study:","options":["The readiness of followers","The power that comes from a leader's position","What leaders do (their behaviour)","The communication networks of the organization"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Since traits alone could not explain leadership, researchers turned to what leaders actually do, which gave rise to behavioural theories. Option A came later, in contingency thinking such as Situational Leadership Theory."}},{"itemId":"a75c5e8d-1e3c-5043-9f75-e5f4db01baa5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4a79c18a-87b1-5eb7-a04c-384a636f1ff8","sourceKey":"bank:AMS101:M101-T9N-023","parentItemId":null,"revision":1,"payload":{"prompt":"Theories that identify the behaviours separating effective leaders from ineffective ones are called:","options":["Contingency theories","Trait theories","Leader-member exchange theories","Behavioural theories"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Behavioural theories focus on what effective leaders do that ineffective leaders do not. Option B looks at personal characteristics rather than behaviour."}},{"itemId":"1a1da709-7123-5013-91aa-5b77bea62c07","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b2b24ed-bb2d-5708-bac5-90c3d065fab9","sourceKey":"bank:AMS101:M101-T9N-024","parentItemId":null,"revision":1,"payload":{"prompt":"The University of Iowa leadership studies are associated with:","options":["Fred Fiedler","Robert House","Blake and Mouton","Kurt Lewin"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Kurt Lewin led the University of Iowa studies that identified the autocratic, democratic and laissez-faire styles. Option C developed the Managerial Grid instead."}},{"itemId":"5382e242-4bf1-5788-a8bb-97e2137ec96c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c169bced-6c68-5c7d-aad5-99547e199c83","sourceKey":"bank:AMS101:M101-T9N-025","parentItemId":null,"revision":1,"payload":{"prompt":"The Managerial Grid was developed by:","options":["Kurt Lewin","Hersey and Blanchard","Robert House","Blake and Mouton"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Blake and Mouton developed the Managerial Grid, built on concern for people and concern for production. Option B developed Situational Leadership Theory, which is a contingency theory."}},{"itemId":"764fee3c-aa01-5878-8e9c-58353db4e157","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"383b35e2-ba05-5bad-911c-450c0196ab4b","sourceKey":"bank:AMS101:M101-T9N-026","parentItemId":null,"revision":1,"payload":{"prompt":"The three leadership styles identified by the University of Iowa studies are:","options":["Transactional, transformational and charismatic","Telling, selling and delegating","Autocratic, democratic and laissez-faire","Directive, supportive and participative"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The Iowa studies identified the autocratic, democratic and laissez-faire styles. Option B lists Hersey and Blanchard styles, and option D lists path-goal behaviours."}},{"itemId":"2d0498f9-d606-57e3-8774-23edcff8c777","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6519ed80-26f9-52f4-8aa7-cf8558fcd846","sourceKey":"bank:AMS101:M101-T9N-027","parentItemId":null,"revision":1,"payload":{"prompt":"What was the main finding of the University of Iowa studies?","options":["Employee-oriented leaders had the lowest productivity","High-high leaders always produced the best results","Group members were more satisfied under democratic leaders","Laissez-faire leaders produced the highest satisfaction"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The Iowa studies found that group members were more satisfied under democratic leaders. Option B misstates the Ohio State finding, which said high-high leaders often but not always got good results."}},{"itemId":"e36764af-f578-5940-b940-37c6828073cd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8055e8d-933f-5d30-b555-be5ce3afbf9a","sourceKey":"bank:AMS101:M101-T9N-028","parentItemId":null,"revision":1,"payload":{"prompt":"The two dimensions of leader behaviour identified in the Ohio State studies are:","options":["Initiating structure and consideration","Employee-oriented and production-oriented","Concern for people and concern for production","Task structure and position power"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Ohio State described leader behaviour in terms of initiating structure and consideration. Option B is the Michigan pair, and option C is the basis of the Managerial Grid."}},{"itemId":"00153753-c657-5741-8028-698b772c5550","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d909d808-f0a9-5e4d-a4a1-d33eae062853","sourceKey":"bank:AMS101:M101-T9N-029","parentItemId":null,"revision":1,"payload":{"prompt":"The two dimensions of leader behaviour identified in the University of Michigan studies are:","options":["Autocratic and democratic","Initiating structure and consideration","Leader-member relations and task structure","Employee-oriented and production-oriented"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The Michigan studies described leaders as employee-oriented or production-oriented. Option B is the Ohio State pair, which is easy to mix up with Michigan."}},{"itemId":"1fac5a47-83e1-5f89-a864-5089c13c3f7f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"792272f8-e322-542e-9b18-7ea65b740e9c","sourceKey":"bank:AMS101:M101-T9N-030","parentItemId":null,"revision":1,"payload":{"prompt":"The University of Michigan studies concluded that:","options":["Group members were most satisfied under autocratic leaders","Leaders who were high on both dimensions always succeeded","Production-oriented leaders had higher productivity and satisfaction","Employee-oriented leaders had higher productivity and satisfaction"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Michigan found that employee-oriented leaders were linked with higher productivity and higher satisfaction. Option C reverses this, since production-oriented leaders were not the ones favoured."}},{"itemId":"fce86557-2436-5310-b4fd-90dde11fcd33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aea13802-fcb9-5eb4-ad96-74c1b7702a82","sourceKey":"bank:AMS101:M101-T9N-031","parentItemId":null,"revision":1,"payload":{"prompt":"What did the Ohio State studies find about leaders who were high in both initiating structure and consideration?","options":["They consistently produced the lowest satisfaction","They always achieved the best results","They were found to be ineffective in all situations","They often got good results, but not always"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Ohio State found that high-high leaders often achieved good results, but there were exceptions. Option B overstates the finding, and those exceptions are part of why researchers later turned to the situation."}},{"itemId":"cb48c079-4526-58d2-88df-7cef81f607b5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"07602a67-dae1-5333-ab89-979e42bff92e","sourceKey":"bank:AMS101:M101-T9N-032","parentItemId":null,"revision":1,"payload":{"prompt":"The two dimensions of the Managerial Grid are:","options":["Leader-member relations and position power","Concern for people and concern for production","Ability and willingness of followers","Initiating structure and consideration"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"The Managerial Grid plots concern for people against concern for production. Option D belongs to the Ohio State studies, and option C is the meaning of readiness in Situational Leadership Theory."}},{"itemId":"c79b3f2e-ea54-5238-bf90-326109b88de9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba0ee332-1ca7-528c-a9b5-9c3f94fd0c87","sourceKey":"bank:AMS101:M101-T9N-033","parentItemId":null,"revision":1,"payload":{"prompt":"On the Managerial Grid, which style is considered the best?","options":["9,9 team management","9,1 task management","5,5 middle of the road","1,9 country club management"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The 9,9 position, team management, is high on both concern for production and concern for people and is seen as the best style. Option C is only medium on both dimensions."}},{"itemId":"22134898-9b43-5f75-8cc3-59421b5ed2e9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"980e2be9-8f4f-5caf-b5b8-2f8f67cbb740","sourceKey":"bank:AMS101:M101-T9N-034","parentItemId":null,"revision":1,"payload":{"prompt":"How many positions are there on the Managerial Grid?","options":["25","9","18","81"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The grid has 9 points on each of its two dimensions, giving 9 x 9 = 81 positions. Option B is the number of points on just one dimension."}},{"itemId":"aa75c8ca-ecb3-5e4c-ad0b-840ac1f73c3a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba7556dc-c7e3-50c1-b870-c7698d6255b0","sourceKey":"bank:AMS101:M101-T9N-035","parentItemId":null,"revision":1,"payload":{"prompt":"On the Managerial Grid, the first number in a position such as 9,1 stands for:","options":["Follower readiness","Concern for people","Position power","Concern for production"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The first number is concern for production and the second is concern for people. Option B is the second number, so 9,1 means high production and low people."}},{"itemId":"23863b11-1684-5859-815e-ada0ed1615b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3c84b6af-f854-5811-8fbd-7dba95bef0a0","sourceKey":"bank:AMS101:M101-T9N-036","parentItemId":null,"revision":1,"payload":{"prompt":"On the Managerial Grid, 'impoverished' management is found at which position?","options":["9,1","1,9","1,1","5,5"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Impoverished management, at 1,1, shows little concern for either people or production. Option B is country club management, which is high on people."}},{"itemId":"4a4bd7d3-75c6-5f32-bc0c-54d5f3e875aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0e7302b-de4c-5575-b965-a328ed69c3f0","sourceKey":"bank:AMS101:M101-T9N-037","parentItemId":null,"revision":1,"payload":{"prompt":"On the Managerial Grid, country club management (1,9) means:","options":["High concern for production and low concern for people","Medium concern for both people and production","Little concern for either people or production","High concern for people and low concern for production"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Country club management sits at 1,9, which means low production but high concern for people. Option A is task management at 9,1."}},{"itemId":"76fd2a36-01aa-53b5-ac75-84f10adc32e0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b2979603-40dd-5506-b46d-87a53476f0ad","sourceKey":"bank:AMS101:M101-T9N-038","parentItemId":null,"revision":1,"payload":{"prompt":"The production manager of a manufacturing firm in Ota pushes hard for output targets but shows little interest in his workers' needs or feelings. On the Managerial Grid, his style is closest to:","options":["Impoverished management (1,1)","Task management (9,1)","Team management (9,9)","Country club management (1,9)"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"High concern for production with low concern for people is task management, placed at 9,1. Option D is the reverse, with high concern for people and low concern for production."}},{"itemId":"4ad35328-f146-52f6-a552-d0667d7df5d5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e4afce01-acbb-56f8-ba66-80e2d2b22343","sourceKey":"bank:AMS101:M101-T9N-039","parentItemId":null,"revision":1,"payload":{"prompt":"On the Managerial Grid, 'middle of the road' management describes a leader who is:","options":["High on people but low on production","Medium on both concern for people and concern for production","High on both concern for people and concern for production","Low on both concern for people and concern for production"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Middle of the road management sits at 5,5, with medium concern for both people and production. Option C describes team management at 9,9."}},{"itemId":"a6f79cb9-2be0-5e66-b39d-d420de20a50b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c1147da9-44fb-53f1-90ee-b5233ed9cd60","sourceKey":"bank:AMS101:M101-T9N-040","parentItemId":null,"revision":1,"payload":{"prompt":"The medical director of a hospital in Lagos sets the theatre roster alone, tells each nurse exactly how to do the work and does not invite suggestions. Which Iowa leadership style is this?","options":["Participative","Laissez-faire","Democratic","Autocratic"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"An autocratic leader centralizes authority, dictates work methods, makes decisions alone and limits participation. Option C would involve staff in decisions, which this director does not do."}},{"itemId":"cd001e0e-6501-547b-b3f5-d0337983f70d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a3d8da7f-789b-53ad-886d-2aada312a62b","sourceKey":"bank:AMS101:M101-T9N-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which behaviour is typical of a democratic leader in the Iowa studies?","options":["Giving the group complete freedom to work as it sees fit","Making decisions alone and limiting participation","Dictating work methods to employees","Using feedback as an opportunity to coach employees"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"A democratic leader involves employees in decisions, delegates authority and uses feedback to coach. Option A describes laissez-faire leadership, where the leader stays out of the decision entirely."}},{"itemId":"d0b8708c-26ee-5e46-a6cb-73b836dfdbdf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"820715ec-f128-5124-b07b-6fc3ad8df034","sourceKey":"bank:AMS101:M101-T9N-042","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between a democratic leader and a laissez-faire leader?","options":["The laissez-faire leader dictates work methods, while the democratic leader does not","The democratic leader still takes part in the decision, while the laissez-faire leader hands it over entirely","There is no difference, as both give the group complete freedom","The democratic leader makes all decisions alone, while the laissez-faire leader consults"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Both styles involve employees, but a democratic leader still takes part in the decision, while a laissez-faire leader gives the group complete freedom. Option C is the common mistake of treating the two styles as the same."}},{"itemId":"fb33bdfd-fadb-5298-b8f0-62d11e303424","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"27abe2dc-cf48-51e5-b705-95f916c0db68","sourceKey":"bank:AMS101:M101-T9N-043","parentItemId":null,"revision":1,"payload":{"prompt":"The head of a university department wants to redesign a course and knows that his lecturers' ideas will make the final plan better. Which Iowa style suits this situation best?","options":["Task management","Autocratic","Laissez-faire","Democratic"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Democratic leadership suits a team whose ideas improve the decision, because the leader involves members while still taking part. Option B fits a crisis needing quick decisions, which this is not."}},{"itemId":"8368c46e-40a8-5d89-a28c-f46064b12b29","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f8575fa-5548-5e76-97de-9c5b0d7e576e","sourceKey":"bank:AMS101:M101-T9N-044","parentItemId":null,"revision":1,"payload":{"prompt":"Lewin's early finding about democratic leadership was that it produced:","options":["Poor quantity and poor quality of work","Both good quantity and good quality of work","Good quality only when the leader was absent","High quantity but very poor quality of work"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Lewin's early finding was that democratic leadership gave both good quantity and good quality of work. Later studies were more mixed on performance, but option D does not describe his early finding."}},{"itemId":"5443626d-4b29-5469-bed9-9f5df3893047","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4b16ae60-925b-5b7d-9dd8-0b96106eeb32","sourceKey":"bank:AMS101:M101-T9N-045","parentItemId":null,"revision":1,"payload":{"prompt":"What did later studies of the Iowa styles find?","options":["Results on performance were mixed, but satisfaction stayed higher under democratic leaders","Autocratic leaders always produced the highest satisfaction","Laissez-faire leaders consistently produced the best performance","Democratic leaders produced lower satisfaction than autocratic leaders"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Later studies gave mixed results on performance, but group members stayed more satisfied under democratic leaders. Options B and D contradict the steady finding on satisfaction."}},{"itemId":"097b53d6-7887-5083-b412-4a4c53590c46","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce95a475-01b8-57cd-8d1f-f072b3e27e77","sourceKey":"bank:AMS101:M101-T9N-046","parentItemId":null,"revision":1,"payload":{"prompt":"In the Ohio State studies, the extent to which a leader defines his role and group members' roles to reach goals, including organizing work, work relationships and goals, is called:","options":["Initiating structure","Consideration","Production-oriented leadership","Task structure"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Initiating structure is how far a leader defines his own role and members' roles in reaching goals. Option D is one of Fiedler's situational factors, describing how structured the job tasks are, not a leader behaviour."}},{"itemId":"5e1841bb-c096-5b1f-81f4-9dea7c184411","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d7c8471-aa3a-576c-9d45-c8aee6edd43e","sourceKey":"bank:AMS101:M101-T9N-047","parentItemId":null,"revision":1,"payload":{"prompt":"In the Ohio State studies, the extent to which a leader has work relationships marked by mutual trust and respect for members' ideas and feelings is called:","options":["Employee-oriented leadership","Consideration","Initiating structure","Leader-member relations"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Consideration is the Ohio State dimension about mutual trust and respect for members' ideas and feelings. Option A is the similar people-side dimension, but it belongs to the Michigan studies."}},{"itemId":"ccfdc999-fab0-5fb9-8026-10ea41544a82","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c262fa92-e9ef-5a7a-9365-0d66db6ef168","sourceKey":"bank:AMS101:M101-T9N-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair of leader behaviour dimensions both represent the 'people side' of leadership?","options":["Initiating structure and employee-oriented","Consideration and employee-oriented","Initiating structure and production-oriented","Consideration and production-oriented"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Consideration (Ohio State) and employee-oriented (Michigan) are both about people. Option C is the task-side pair, and options D and A mix one people dimension with one task dimension."}},{"itemId":"6a163a1b-112a-5d6a-b235-28d6f8913ee7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5c557572-c55c-590a-9061-e0e8cb1b099b","sourceKey":"bank:AMS101:M101-T9N-049","parentItemId":null,"revision":1,"payload":{"prompt":"In the Michigan studies, a production-oriented leader is one who stresses:","options":["Giving the group complete freedom","Mutual trust and respect for members' feelings","The technical or task side of the job","Interpersonal relationships and employees' needs"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"A production-oriented leader stresses the technical or task side of the job. Option D describes the employee-oriented leader, the other Michigan dimension."}},{"itemId":"5e200baf-77ea-5dd5-910f-adb4726e7508","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e92caa34-683c-5545-8bb1-c28840d11296","sourceKey":"bank:AMS101:M101-T9N-050","parentItemId":null,"revision":1,"payload":{"prompt":"'Initiating structure' as a dimension of leader behaviour comes from which study?","options":["The Managerial Grid","Ohio State studies","University of Michigan studies","University of Iowa studies"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Initiating structure, together with consideration, comes from the Ohio State studies. Option C used employee-oriented and production-oriented instead."}},{"itemId":"e7e80d10-56b1-51d8-9fd3-51710958a9d3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bf22e895-f697-5c30-9908-bf523624f224","sourceKey":"bank:AMS101:M101-T9N-051","parentItemId":null,"revision":1,"payload":{"prompt":"What weakness of behavioural theories led to the development of contingency theories?","options":["They focused too much on personal traits","They ignored the leader's behaviour","They did not consider the situation","They claimed leadership style is fixed"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Behavioural theories looked at what leaders do but ignored the situation, which led to contingency theories. Option B is wrong because behaviour was exactly what these theories studied."}},{"itemId":"50c64579-6b01-55cf-b907-20e22501f136","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"65b8e119-8303-5958-aba6-fc9218bc2802","sourceKey":"bank:AMS101:M101-T9N-052","parentItemId":null,"revision":1,"payload":{"prompt":"The central idea of contingency theories of leadership is that:","options":["Effective leaders are born with a fixed set of traits","The 9,9 style works best in every organization","There is no one best leadership style, so the leader must adapt to the situation","The democratic style is the best in every situation"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Contingency theories hold that no single style is best, and the right style depends on the situation. Option B reflects the Managerial Grid's single best style, which is exactly the kind of universal answer contingency theories reject."}},{"itemId":"e7e6ac8e-cd0b-5ce6-bfc4-a47f6fe6f821","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d5de1db5-ff77-5a6e-a52f-ded6537fa521","sourceKey":"bank:AMS101:M101-T9N-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which contingency theory holds that a leader's style is fixed and cannot easily change?","options":["Fiedler model","Leader-member exchange theory","Situational Leadership Theory","Path-goal theory"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The Fiedler model treats a leader's style as fixed, so the match between leader and situation is what matters. Option C says the opposite, because the style changes with the readiness of followers."}},{"itemId":"f1e7d03d-e102-59e6-a13e-4f1409ab7c3d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c42da95e-d136-5c82-8c78-64b677129e08","sourceKey":"bank:AMS101:M101-T9N-054","parentItemId":null,"revision":1,"payload":{"prompt":"According to the Fiedler model, group performance depends on:","options":["The readiness of followers to do a task","Matching the leader's style to how much the situation lets the leader control and influence","The leader helping followers reach their own goals","Forming an in-group and an out-group of followers"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Fiedler argued that performance depends on the right match between the leader's fixed style and how much control and influence the situation gives. Option A is the basis of Situational Leadership Theory instead."}},{"itemId":"fe9efad4-784b-56a0-affa-fc64d362136d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2713b12f-796e-5d40-a966-2d5732a2b0b6","sourceKey":"bank:AMS101:M101-T9N-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of Fiedler's three situational factors?","options":["Task structure","Position power","Leader-member relations","Follower readiness"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Fiedler's three situational factors are leader-member relations, task structure and position power. Follower readiness belongs to Hersey and Blanchard's Situational Leadership Theory, not the Fiedler model."}},{"itemId":"136c79ff-4fe2-5bfe-b5dd-95dfd38e7f43","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"98b2a70a-5e0b-5070-add8-aabb53395880","sourceKey":"bank:AMS101:M101-T9N-056","parentItemId":null,"revision":1,"payload":{"prompt":"In the Fiedler model, the degree of confidence, trust and respect followers have for their leader is called:","options":["Consideration","Leader-member relations","Position power","Task structure"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Leader-member relations measures the confidence, trust and respect followers have for the leader. Option A sounds similar but is an Ohio State behaviour dimension, not one of Fiedler's situational factors."}},{"itemId":"68eaefea-d1f9-5a0a-bd14-954445aebe6e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d986dd53-605f-5d45-811b-7c9e9847316e","sourceKey":"bank:AMS101:M101-T9N-057","parentItemId":null,"revision":1,"payload":{"prompt":"In the Fiedler model, the degree to which job tasks are formal and structured is called:","options":["Initiating structure","Leader-member relations","Task structure","Position power"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Task structure describes how formal and structured job tasks are. Option A is a trap because it is a leader behaviour from the Ohio State studies, not a feature of the situation."}},{"itemId":"b0846f3f-36c0-573a-97dc-db628dbbf7ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"15ef3ab5-4bf5-5a89-ba1c-22f79721da78","sourceKey":"bank:AMS101:M101-T9N-058","parentItemId":null,"revision":1,"payload":{"prompt":"The new plant manager at a manufacturer in Ota has full power to hire, fire, discipline, promote and set the pay of his staff. In the Fiedler model, this situational factor is:","options":["Task structure","Leader-member relations","Position power","Referent power"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Position power is the leader's power over hiring, firing, discipline, promotions and pay. Option D is one of the five types of power, which comes from personal traits people admire, not from control over pay and discipline."}},{"itemId":"9966b478-7fad-5617-aa8e-15aaac654e46","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"aa8938fc-283e-5ac0-9cd1-b83006077705","sourceKey":"bank:AMS101:M101-T9N-059","parentItemId":null,"revision":1,"payload":{"prompt":"Combining Fiedler's three situational factors produces how many possible situations?","options":["Four","Nine","Three","Eight"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Mixing the three factors gives eight situations, ranging from very favourable to very unfavourable. Option C is the number of factors, not the number of situations they produce."}},{"itemId":"a802f519-a26d-50fa-92e4-1684e76265da","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a8bd9e13-3568-5f38-9b6f-4908a5be49d5","sourceKey":"bank:AMS101:M101-T9N-060","parentItemId":null,"revision":1,"payload":{"prompt":"In the Fiedler model, the LPC questionnaire stands for:","options":["Lowest performance criterion","Least-preferred co-worker","Leader participation chart","Leader position control"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"LPC means least-preferred co-worker: the leader describes the co-worker he liked least using pairs of opposite adjectives. Options D, C and A are invented expansions."}},{"itemId":"58f93aa2-2c68-574c-b9fb-df99056e17f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2f58c22c-5235-5360-9dba-3ff0e7c75cd9","sourceKey":"bank:AMS101:M101-T9N-061","parentItemId":null,"revision":1,"payload":{"prompt":"On Fiedler's LPC questionnaire, a supervisor describes the co-worker he liked least in kind and favourable terms. Fiedler would classify him as:","options":["Relationship-oriented","Task-oriented","Laissez-faire","Production-oriented"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A high LPC score, from describing the least-preferred co-worker kindly, shows a relationship-oriented leader. Option B is the low-LPC leader, who describes that co-worker in harsh terms."}},{"itemId":"0ab8c524-10f1-5fc2-a826-c19d058ce57c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b4762e37-de28-55db-8838-193a16edf9b8","sourceKey":"bank:AMS101:M101-T9N-062","parentItemId":null,"revision":1,"payload":{"prompt":"A leader who gets a low score on Fiedler's LPC questionnaire is classified as:","options":["Relationship-oriented","Employee-oriented","Supportive","Task-oriented"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"A low LPC score marks a task-oriented leader in the Fiedler model. Option A is the high-LPC leader."}},{"itemId":"7adcae9f-cb2c-59f6-be7d-8671437484c0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e2840244-a716-5f30-89f5-930ddc519fb4","sourceKey":"bank:AMS101:M101-T9N-063","parentItemId":null,"revision":1,"payload":{"prompt":"According to the Fiedler model, task-oriented leaders perform best in situations that are:","options":["Neither favourable nor unfavourable","Moderately favourable only","Very favourable or very unfavourable","Highly structured but with weak leader-member relations only"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Fiedler found that task-oriented leaders do best at the two extremes, very favourable or very unfavourable situations. Option B is where relationship-oriented leaders do best."}},{"itemId":"a0bf5aa1-fd9a-51c5-98f6-086c1b3c9ce6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cf8925a1-dc47-5907-b267-cecb62868c42","sourceKey":"bank:AMS101:M101-T9N-064","parentItemId":null,"revision":1,"payload":{"prompt":"According to the Fiedler model, relationship-oriented leaders perform best in situations that are:","options":["Very favourable","Either very favourable or very unfavourable","Very unfavourable","Moderately favourable"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Relationship-oriented leaders do best in moderately favourable situations. Option B describes where task-oriented leaders do best."}},{"itemId":"61df3018-5342-506b-86cb-cc10b6689983","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7a58f2dc-e0d6-58ab-ac3d-af4171c87435","sourceKey":"bank:AMS101:M101-T9N-065","parentItemId":null,"revision":1,"payload":{"prompt":"Because the Fiedler model treats leadership style as fixed, how can a mismatch between leader and situation be corrected?","options":["Change the leader or change the situation","Ask the leader to become laissez-faire","Let followers choose a new style for the leader","Train the leader to switch styles as followers mature"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"If style cannot change, the only options are to replace the leader or change the situation to fit him. Option D assumes style can change, which is the view of Situational Leadership Theory, not Fiedler."}},{"itemId":"9f1c2ed1-5231-572c-b3fb-aee41fcf50b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d55bc49-195a-5e69-9a24-b03d1cc90f5f","sourceKey":"bank:AMS101:M101-T9N-066","parentItemId":null,"revision":1,"payload":{"prompt":"Situational Leadership Theory was developed by:","options":["Kurt Lewin","Hersey and Blanchard","Robert House","Blake and Mouton"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Hersey and Blanchard developed Situational Leadership Theory, which ties style to the readiness of followers. Option D developed the Managerial Grid, a behavioural theory."}},{"itemId":"ff889a30-5941-598d-81ec-a9632a4a5ffb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"46b9db20-58ed-5e1d-94d1-926a162bf7ac","sourceKey":"bank:AMS101:M101-T9N-067","parentItemId":null,"revision":1,"payload":{"prompt":"In Situational Leadership Theory, 'readiness' refers to:","options":["How far people have the ability and willingness to do a task","How much power the leader has over pay and promotion","How much followers like and respect the leader","How structured and formal the job tasks are"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Readiness is the extent to which followers have both the ability and the willingness to do a task. Option C is closer to Fiedler's leader-member relations, not readiness."}},{"itemId":"6d8231dc-6042-5fdb-bdef-f1c7b5e59811","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b0088eaa-7a90-5989-b8ae-1a1dd7e9e02d","sourceKey":"bank:AMS101:M101-T9N-068","parentItemId":null,"revision":1,"payload":{"prompt":"In Situational Leadership Theory, which style fits followers who are unable and unwilling to do a task (R1)?","options":["Telling","Participating","Delegating","Selling"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Followers at R1 are unable and unwilling, so the leader uses telling: high task and low relationship behaviour. Option D is for followers who are unable but willing."}},{"itemId":"a221b254-467e-5f72-a541-ab9a81e5c6c2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d2bb2764-f3a0-5e5b-b5fc-242ec6dc9324","sourceKey":"bank:AMS101:M101-T9N-069","parentItemId":null,"revision":1,"payload":{"prompt":"A new team of graduate trainees at a bank in Lagos is very eager to work but does not yet have the skills for the job. Under Situational Leadership Theory, the manager should use:","options":["Participating","Telling","Selling","Delegating"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Followers who are unable but willing (R2) need selling, which is high task and high relationship. Option B suits followers who are both unable and unwilling, but these trainees are eager."}},{"itemId":"90ec1705-7ad7-5959-b31d-8ec24750bc72","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"240176f9-3f71-5bbe-85c5-bb2e0d0f7f3c","sourceKey":"bank:AMS101:M101-T9N-070","parentItemId":null,"revision":1,"payload":{"prompt":"Experienced engineers at a firm in Ota have all the skills needed for a project but are unwilling to commit to it. Under Situational Leadership Theory, which style should their manager use?","options":["Selling","Participating","Telling","Delegating"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Followers who are able but unwilling (R3) call for participating: low task and high relationship behaviour. Option D suits followers who are both able and willing."}},{"itemId":"4be4e4b4-37ea-5ad6-8a28-0043b4060ec8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0ae5edaa-ec19-5e46-8156-c1ec9e71453a","sourceKey":"bank:AMS101:M101-T9N-071","parentItemId":null,"revision":1,"payload":{"prompt":"In Situational Leadership Theory, which style combines high task behaviour with high relationship behaviour?","options":["Delegating","Participating","Selling","Telling"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Selling is high task and high relationship, used with followers who are unable but willing. Option D is high task but low relationship."}},{"itemId":"b0a3b894-b46c-5faa-855c-5ddc0e6e7069","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1e066a0f-3b2e-5389-93ff-5e770698167f","sourceKey":"bank:AMS101:M101-T9N-072","parentItemId":null,"revision":1,"payload":{"prompt":"In Situational Leadership Theory, the delegating style is described as:","options":["Low task and high relationship behaviour","Low task and low relationship behaviour","High task and high relationship behaviour","High task and low relationship behaviour"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Delegating is low task and low relationship, used when followers are able and willing (R4). Option A describes participating."}},{"itemId":"96cf8850-f167-5769-87d2-644227d48917","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"560a87c1-4f74-5fe7-96ec-7720e3c5229a","sourceKey":"bank:AMS101:M101-T9N-073","parentItemId":null,"revision":1,"payload":{"prompt":"According to Situational Leadership Theory, as followers become more ready, the leader should:","options":["Increase both control and relationship behaviour","Cut back on both control and relationship behaviour","Keep the same style regardless of readiness","Increase control but reduce relationship behaviour"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"As readiness grows, the leader cuts back on both control and relationship behaviour, moving towards delegating. Option C reflects Fiedler's fixed style, not Situational Leadership Theory."}},{"itemId":"ea12c5cd-ff2b-58b5-90bd-9175d0128e15","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0a4b9fad-d1ea-5041-ae65-9fd20881d0f3","sourceKey":"bank:AMS101:M101-T9N-074","parentItemId":null,"revision":1,"payload":{"prompt":"How does Situational Leadership Theory differ from the Fiedler model on leadership style?","options":["Situational Leadership Theory says style can change, while Fiedler says style is fixed","Situational Leadership Theory says style is fixed, while Fiedler says style can change","Both say performance depends only on the leader's traits","Both say the leader's style can never change"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Hersey and Blanchard allow the leader to change style as follower readiness changes, while Fiedler treats style as fixed. Option B reverses the two theories."}},{"itemId":"097fada3-caf0-5db3-8a4b-192b204477c4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"18a8b645-0632-55a9-9343-f702ad8ecfb5","sourceKey":"bank:AMS101:M101-T9N-075","parentItemId":null,"revision":1,"payload":{"prompt":"Path-goal theory of leadership was proposed by:","options":["Robert House","Fred Fiedler","Kurt Lewin","Hersey and Blanchard"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Robert House proposed path-goal theory, in which the leader helps followers reach their goals. Option B is linked to the model with a fixed leadership style."}},{"itemId":"5841f99a-99b9-53dc-8389-bb907a2926e2","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fe210032-abbc-55ce-acbb-697a0af8f2a7","sourceKey":"bank:AMS101:M101-T9N-076","parentItemId":null,"revision":1,"payload":{"prompt":"Path-goal theory states that the leader's job is to:","options":["Help followers reach their goals by giving direction and support","Match a fixed style to the favourableness of the situation","Hand all decisions to followers who are able and willing","Form an in-group and an out-group among followers"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"In path-goal theory the leader helps followers reach their goals and provides the direction and support they need. Option B describes the Fiedler model."}},{"itemId":"5d2366d6-0b23-589a-8180-fcf91299104a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f008eb25-fb3f-57ad-8406-306006b8ca9f","sourceKey":"bank:AMS101:M101-T9N-077","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four path-goal leader behaviours?","options":["Delegating","Supportive","Directive","Achievement-oriented"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The four path-goal behaviours are directive, supportive, participative and achievement-oriented. Delegating is one of Hersey and Blanchard's styles, not a path-goal behaviour."}},{"itemId":"5ec05fc7-876f-5afe-af88-a46fef842324","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ea8bfc20-dde0-555c-8cf8-4e9526081893","sourceKey":"bank:AMS101:M101-T9N-078","parentItemId":null,"revision":1,"payload":{"prompt":"In path-goal theory, a leader who tells followers what is expected of them, schedules work and gives specific direction is showing which behaviour?","options":["Achievement-oriented","Participative","Directive","Supportive"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Directive leadership tells followers what is expected, schedules work and directs how to do it. Option B consults followers and uses their suggestions instead."}},{"itemId":"48780e0e-2aa1-5ebd-a971-bd9c7a969ffd","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ee6496a2-2b0f-5504-b07e-25e0bc3293cc","sourceKey":"bank:AMS101:M101-T9N-079","parentItemId":null,"revision":1,"payload":{"prompt":"A ward sister at a hospital in Enugu is friendly with her nurses and shows real concern for their needs. In path-goal theory, this is which leader behaviour?","options":["Participative","Directive","Supportive","Achievement-oriented"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"A supportive leader is friendly and shows concern for followers' needs. Option A would involve consulting the nurses and using their suggestions in decisions."}},{"itemId":"01745696-456f-54dd-ad38-13f34bbf3696","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"74d19c6d-466f-5be4-8c89-8be0f17853b9","sourceKey":"bank:AMS101:M101-T9N-080","parentItemId":null,"revision":1,"payload":{"prompt":"A sales manager at a telecom company in Lagos sets very challenging targets for her team and makes clear she expects top performance. In path-goal theory, this is which behaviour?","options":["Achievement-oriented","Participative","Directive","Supportive"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Setting challenging goals and expecting top performance is achievement-oriented leadership. Option C is about telling followers what to do and scheduling work, not setting stretching goals."}},{"itemId":"675d05b1-bfb9-5b8f-bdba-ddccf124f1ca","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"84e07d33-90c6-5ed7-9375-b4940e863bd9","sourceKey":"bank:AMS101:M101-T9N-081","parentItemId":null,"revision":1,"payload":{"prompt":"In path-goal theory, a leader who consults followers and uses their suggestions is showing which behaviour?","options":["Directive","Participative","Delegating","Supportive"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"A participative leader consults followers and uses their suggestions. Option C is a Situational Leadership style and not one of the path-goal behaviours."}},{"itemId":"edd18be5-b3cb-52ec-9425-acbc8fdc9a0c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06f6f0a0-0e42-56ee-8657-445ef0faabfe","sourceKey":"bank:AMS101:M101-T9N-082","parentItemId":null,"revision":1,"payload":{"prompt":"In path-goal theory, which of the following is NOT a follower characteristic that affects the right leader behaviour?","options":["Task structure","Locus of control","Perceived ability","Experience"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Follower characteristics are locus of control, experience and perceived ability. Task structure is part of the environment, the other group of factors in path-goal theory."}},{"itemId":"55c90aaa-94b3-5646-bd50-b3c81b585853","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0b9e26cf-b7fb-55a1-af8b-2f110a8c19c0","sourceKey":"bank:AMS101:M101-T9N-083","parentItemId":null,"revision":1,"payload":{"prompt":"Leader-member exchange (LMX) theory states that leaders:","options":["Form an in-group and an out-group, and in-group members get more trust and attention","Should give every follower exactly the same treatment","Change style only according to the task structure","Must keep one fixed style for all followers"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"LMX theory says leaders create an in-group and an out-group, and in-group members receive more trust and attention and tend to perform better. Option B is the opposite of what LMX describes."}},{"itemId":"77e6717d-da3d-5588-bec7-1203fce0c3ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"21ce2622-d70b-5eca-b4bc-c694f93e4426","sourceKey":"bank:AMS101:M101-T9N-084","parentItemId":null,"revision":1,"payload":{"prompt":"A leader who motivates followers mainly by exchanging rewards for productivity is called a:","options":["Transformational leader","Visionary leader","Transactional leader","Charismatic leader"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"A transactional leader works through clear goals and exchanges rewards for productivity. Option A goes further by stimulating and inspiring followers to achieve extraordinary outcomes."}},{"itemId":"71beac08-0049-511e-90c6-c3daabedef37","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b36aa8c6-7ff8-576f-aecb-f0d9aca232fd","sourceKey":"bank:AMS101:M101-T9N-085","parentItemId":null,"revision":1,"payload":{"prompt":"A leader who stimulates and inspires followers to achieve extraordinary outcomes is known as a:","options":["Laissez-faire leader","Production-oriented leader","Transactional leader","Transformational leader"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Transformational leaders stimulate and inspire followers to achieve extraordinary outcomes. Option C relies on exchanging rewards for productivity rather than inspiring beyond normal results."}},{"itemId":"d77759d7-1c33-53d8-8de3-64cba5c25299","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ca465fa3-efa9-53f2-9f9e-44c8bc2309b4","sourceKey":"bank:AMS101:M101-T9N-086","parentItemId":null,"revision":1,"payload":{"prompt":"The manager of a bottling plant in Ota tells workers exactly what output is expected and pays a bonus to every worker who meets the weekly target. This is an example of:","options":["Laissez-faire leadership","Charismatic leadership","Transactional leadership","Transformational leadership"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Setting clear goals and exchanging rewards for productivity is transactional leadership. Option D would involve inspiring workers towards extraordinary outcomes, innovation and personal growth, not just a bonus for meeting targets."}},{"itemId":"bdd44749-4afd-51e5-b5fa-e0740101bc33","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"53e07b6b-9c62-51b5-8078-b6833ec1f21f","sourceKey":"bank:AMS101:M101-T9N-087","parentItemId":null,"revision":1,"payload":{"prompt":"How is transformational leadership related to transactional leadership?","options":["Transactional leadership is built on top of transformational leadership","Transformational leadership is built on top of transactional leadership","The two have no connection with each other","Transformational leadership is the exact opposite of transactional leadership"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Transformational leadership builds on top of transactional leadership rather than replacing it. Option D is the common mistake of treating them as opposites."}},{"itemId":"ca5e6fd5-6b13-5768-959e-e07442c89f09","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7fa83b2e-8f2d-599e-b641-601b6286e91d","sourceKey":"bank:AMS101:M101-T9N-088","parentItemId":null,"revision":1,"payload":{"prompt":"An enthusiastic, self-confident leader whose personality and actions influence people to behave in certain ways is called a:","options":["Charismatic leader","Transactional leader","Autocratic leader","Task-oriented leader"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A charismatic leader is enthusiastic and self-confident, and his personality and actions shape how people behave. Option B influences people through rewards rather than personality."}},{"itemId":"73019bc1-68af-5d87-833f-414d39bee75f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9979213c-3851-5a5b-aa3c-e61dd972b979","sourceKey":"bank:AMS101:M101-T9N-089","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of charismatic leaders?","options":["They can express that vision","They avoid taking risks to achieve their vision","They behave in ways that are out of the ordinary","They have a vision"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Charismatic leaders are willing to take risks to achieve their vision, so avoiding risk does not fit them. Options D, A and C are all among the five characteristics of charismatic leaders."}},{"itemId":"792cae6f-1347-5867-99a6-83d369b4fe0f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b73bbde7-aecc-57f8-bf47-4f43192ccccf","sourceKey":"bank:AMS101:M101-T9N-090","parentItemId":null,"revision":1,"payload":{"prompt":"How many characteristics of charismatic leaders are commonly identified?","options":["Three","Seven","Five","Four"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Five characteristics are identified: having a vision, expressing it, taking risks for it, being sensitive to the environment and followers' needs, and behaving out of the ordinary. Option B is the number of traits linked with leadership."}},{"itemId":"5c19e1bc-6e60-5686-8128-7ee9ad33adf5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"161da239-f7da-5491-9361-4a5c29777d70","sourceKey":"bank:AMS101:M101-T9N-091","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following IS a characteristic of charismatic leaders?","options":["Behaving in conventional, predictable ways","Keeping a fixed style regardless of the situation","Strict reliance on exchanging rewards for output","Sensitivity to limits in the environment and to followers' needs"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Charismatic leaders are sensitive to environmental limits and to followers' needs. Option A is wrong because charismatic leaders behave in ways that are out of the ordinary."}},{"itemId":"73f24151-4a6c-52c7-951f-1aedd73be654","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5d566238-4561-506f-ab1b-de1cd806da8a","sourceKey":"bank:AMS101:M101-T9N-092","parentItemId":null,"revision":1,"payload":{"prompt":"The ability to create and express a realistic, credible and attractive vision of the future that improves on the present is called:","options":["Transactional leadership","Legitimate power","Initiating structure","Visionary leadership"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Visionary leadership is creating and expressing a realistic, credible and attractive vision of a better future. Option C is about defining roles and organizing work, not painting a picture of the future."}},{"itemId":"2bb0f257-9f13-580b-a0d3-10d4a75d2dfb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ab7c2a07-d2e3-5683-a87c-bb24242b83c1","sourceKey":"bank:AMS101:M101-T9N-093","parentItemId":null,"revision":1,"payload":{"prompt":"The two priorities of team leadership are:","options":["Filtering information and limiting participation","Hiring team members and setting their pay","Managing the team's external boundary and helping the team process","Planning the budget and controlling costs"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Team leadership has two priorities: managing the team's external boundary and helping the team process. Option A describes a communication barrier and autocratic behaviour, not team leadership."}},{"itemId":"04bb52fd-f4f2-5bae-b27c-4f326df6b249","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"138cf822-ddd5-566c-9c81-d689f10ac0f5","sourceKey":"bank:AMS101:M101-T9N-094","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four roles of a team leader?","options":["Liaison with outsiders","Coach","Troubleshooter","Sole decision maker"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The four roles of a team leader are liaison with outsiders, troubleshooter, conflict manager and coach. Acting as the sole decision maker is not one of them, while options A, C and B are."}},{"itemId":"3ff991ae-00e4-5c41-aa82-29a4226ced42","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e23761cf-c916-5e82-b901-d35680e59703","sourceKey":"bank:AMS101:M101-T9N-095","parentItemId":null,"revision":1,"payload":{"prompt":"The leader of a project team at a Lagos fintech firm represents the team in meetings with other departments and outside partners. Which team leader role is this?","options":["Coach","Liaison with outsiders","Conflict manager","Troubleshooter"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Representing the team to people outside it is the liaison with outsiders role. Option C would mean settling disagreements inside the team."}},{"itemId":"e98e2d0e-7d1b-5e7b-9282-64d9a1240fe8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8a40d817-6927-51ce-812f-f70219c2a5b3","sourceKey":"bank:AMS101:M101-T9N-096","parentItemId":null,"revision":1,"payload":{"prompt":"How many sources of power can a leader draw on?","options":["Five","Four","Three","Six"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"A leader can draw on five types of power: legitimate, coercive, reward, expert and referent. Option D adds one too many, while options C and B leave some out."}},{"itemId":"92a8a30f-7581-51a5-a6f5-27372b434683","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1f17dc4d-e8fa-5792-b514-fe126a666f75","sourceKey":"bank:AMS101:M101-T9N-097","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five sources of power?","options":["Legitimate power","Referent power","Situational power","Expert power"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The five types are legitimate, coercive, reward, expert and referent power. Situational power is not one of them, while options A, D and B are on the list."}},{"itemId":"02c83e11-4e97-59b9-b20e-4c234193534e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85a8ca29-0c12-55ec-ac62-7eb8c19bb008","sourceKey":"bank:AMS101:M101-T9N-098","parentItemId":null,"revision":1,"payload":{"prompt":"A new head of department at a federal ministry in Abuja is obeyed mainly because of the official post she holds. Which type of power is she using?","options":["Expert power","Legitimate power","Reward power","Referent power"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Legitimate power comes from the leader's position in the organization. Option D would mean people obey because they admire her and want to be like her, not because of her post."}},{"itemId":"9aca86ce-d5db-5b49-816f-77e7b9502492","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9ced6199-5017-5668-97a1-3efa3abeb442","sourceKey":"bank:AMS101:M101-T9N-099","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor in a factory in Ota threatens to suspend workers who arrive late. Which type of power is he using?","options":["Reward power","Referent power","Legitimate power","Coercive power"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Coercive power is the power to punish or control, as with the threat of suspension. Option A works the other way, through positive rewards."}},{"itemId":"911d4dd3-e1d3-5281-a95e-af5e5cf4ad35","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fd120081-d48a-5b62-b130-239e1c7b7a4b","sourceKey":"bank:AMS101:M101-T9N-100","parentItemId":null,"revision":1,"payload":{"prompt":"A bank manager in Lagos influences her staff by giving bonuses, praise and recommendations for promotion to those who perform well. Which type of power is this?","options":["Expert power","Coercive power","Legitimate power","Reward power"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Reward power is the power to give positive rewards such as bonuses and praise. Option B is the power to punish, the opposite approach."}},{"itemId":"3b07b1ea-997e-5f67-9875-1184cfe4217f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7798737a-db6d-5983-9f29-d38e7d920c06","sourceKey":"bank:AMS101:M101-T9N-101","parentItemId":null,"revision":1,"payload":{"prompt":"Colleagues at a hospital in Ibadan follow the advice of a junior doctor on a rare condition because she has special knowledge of it. Which type of power does she have?","options":["Expert power","Legitimate power","Coercive power","Referent power"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Expert power comes from expertise, special skills or knowledge, so even a junior doctor can have it. Option B would depend on a senior position, which she does not hold."}},{"itemId":"a9c3e034-4f85-5eeb-8577-a49eef4273ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"11228e49-61be-5b9d-8033-6df7d596821a","sourceKey":"bank:AMS101:M101-T9N-102","parentItemId":null,"revision":1,"payload":{"prompt":"Power that comes from a person's desirable resources or personal traits, so that others admire him and want to be like him, is called:","options":["Referent power","Expert power","Reward power","Legitimate power"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Referent power rests on admiration: people want to be like the person because of his desirable resources or personal traits. Option B comes from skills or knowledge rather than admiration."}},{"itemId":"53763c07-1d38-5901-8945-f32da379dd13","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"06caccd2-f5da-58fb-90c4-318880db59ca","sourceKey":"bank:AMS101:M101-T9N-103","parentItemId":null,"revision":1,"payload":{"prompt":"Trust, in the context of leadership, is best defined as:","options":["The belief in the integrity, character and ability of a leader","The power to punish or control followers","Increasing the decision-making discretion of workers","The formal authority attached to a leader's position"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Trust is the belief in a leader's integrity, character and ability. Option C is empowerment, and option B is coercive power."}},{"itemId":"edfa20c7-7551-5027-ae34-9086fa8713f6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dc5eff5b-86be-52b5-afe1-c4b116813a1e","sourceKey":"bank:AMS101:M101-T9N-104","parentItemId":null,"revision":1,"payload":{"prompt":"Trust in leadership is important mainly because it:","options":["Allows leaders to avoid communicating with staff","Removes the need for any rewards or recognition","Helps people feel secure and confident, leading to better collaboration, engagement and success","Makes followers depend fully on coercive power"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Trust helps people feel secure and confident in their organization, which leads to better collaboration, engagement and success. Option A is wrong because communication is one of the ways trust is built."}},{"itemId":"be933248-040e-5fdc-88c3-d2b527cdb078","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b68c79d1-7984-53b2-8fa6-162aad8e2880","sourceKey":"bank:AMS101:M101-T9N-105","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the 5 Cs of how trust is built?","options":["Competence","Consistency","Character","Caring"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"The 5 Cs for building trust are competence, communication, commitment, caring and character. Consistency is a dimension of what trust is made of, which is the classic trap between the two sets of five."}},{"itemId":"9415e8c0-05b8-57b5-9912-b217ff207212","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cd8395c4-0c53-56ea-b39c-fa18c6143534","sourceKey":"bank:AMS101:M101-T9N-106","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five dimensions of trust?","options":["Openness","Caring","Loyalty","Integrity"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"The five dimensions of trust are integrity, competence, consistency, loyalty and openness. Caring is one of the 5 Cs for building trust, not a dimension of what trust is made of."}},{"itemId":"4b54c7e2-df95-55ef-ba73-8751f5fa2d25","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b115390f-63c2-5e1c-9bed-8d4e6912c7c9","sourceKey":"bank:AMS101:M101-T9N-107","parentItemId":null,"revision":1,"payload":{"prompt":"Which dimension of trust is considered the most important?","options":["Openness","Integrity","Competence","Loyalty"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Integrity, meaning honesty and truthfulness, is the most important dimension of trust. Option C matters too, but it is not ranked first."}},{"itemId":"de984b96-99fe-5290-9feb-bb778a555375","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db8c5f66-0ff2-5a73-aba7-61cc28eac0aa","sourceKey":"bank:AMS101:M101-T9N-108","parentItemId":null,"revision":1,"payload":{"prompt":"The dimension of trust that refers to reliability and good judgement in handling situations is:","options":["Integrity","Loyalty","Openness","Consistency"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Consistency is the dimension of trust about reliability and good judgement. Option A is about honesty and truthfulness instead."}},{"itemId":"6e9690cf-e5fb-55da-b535-43345cf1e3ce","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d25862aa-ee52-508d-bcc5-6f2d0a6786f8","sourceKey":"bank:AMS101:M101-T9N-109","parentItemId":null,"revision":1,"payload":{"prompt":"The dimension of trust that refers to a willingness to protect a person is:","options":["Loyalty","Integrity","Competence","Consistency"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Loyalty is the willingness to protect a person, one of the five dimensions of trust. Option D is about reliability and good judgement."}},{"itemId":"b02b4bda-b376-593d-8344-a30ba1246ea6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ba592eab-a865-574f-a35c-38c67b5e05d0","sourceKey":"bank:AMS101:M101-T9N-110","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital administrator in Lagos earns her staff's trust because she always acts ethically and honestly, even when no one is watching. Which of the 5 Cs of building trust does this show?","options":["Communication","Character","Commitment","Competence"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Character means reflecting ethical and honest behaviour, which builds trust. Option D is about having the necessary skills and expertise, not ethics."}},{"itemId":"800a71b3-d5c7-514f-b1e4-ffac835da889","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a0f9497-b032-52da-9276-c965bce311b9","sourceKey":"bank:AMS101:M101-T9N-111","parentItemId":null,"revision":1,"payload":{"prompt":"A university registrar builds trust with staff by showing that he is fully devoted to the goals and success of the institution. Which of the 5 Cs is this?","options":["Caring","Character","Commitment","Competence"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Commitment means being committed to the goals and success of the organization. Option A is about truly caring for other people rather than devotion to the institution's goals."}},{"itemId":"062f1c52-c58a-5894-9e0e-3eba339e58ae","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"315a7566-4102-560c-830e-41130cd7a628","sourceKey":"bank:AMS101:M101-T9N-112","parentItemId":null,"revision":1,"payload":{"prompt":"Credibility, in leadership, refers to:","options":["How far followers see a leader as honest, competent and able to inspire","The leader's power to give rewards","How formal and structured the leader's tasks are","The power that comes from a leader's official position"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Credibility is how far followers see a leader as honest, competent and able to inspire. Option D is legitimate power, which comes from position, not from how followers judge the leader."}},{"itemId":"1eeb1a23-9762-5765-975d-8699b2b75ead","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b44db0eb-7487-5451-ae2d-a486facbf3ca","sourceKey":"bank:AMS101:M101-T9N-113","parentItemId":null,"revision":1,"payload":{"prompt":"Which trait is most closely linked with a leader's credibility?","options":["Honesty","Extraversion","Intelligence","Desire to lead"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Honesty is the trait most closely linked with credibility. Options B, C and D are leadership traits, but none is singled out as the trait most tied to credibility."}},{"itemId":"cc4242c3-0af4-56bb-b7ef-4cafb4489924","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1fd5a4f5-0a5d-5660-91f5-9406b68a2cee","sourceKey":"bank:AMS101:M101-T9N-114","parentItemId":null,"revision":1,"payload":{"prompt":"Increasing the decision-making discretion of workers is known as:","options":["Initiating structure","Filtering","Empowerment","Centralization"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Empowerment means increasing workers' decision-making discretion. Option D does the opposite by keeping decisions at the top."}},{"itemId":"b321a592-b38e-531f-aaaf-e3f74540e02e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bccb5c35-1c83-5350-a231-714ece451b1a","sourceKey":"bank:AMS101:M101-T9N-115","parentItemId":null,"revision":1,"payload":{"prompt":"Why are empowered workers allowed to make decisions on their own?","options":["They are in the leader's out-group","They hold the highest formal positions in the organization","They have the power to hire and fire","They know the job best and can act fast"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Empowered workers decide for themselves because they know the job best and can act quickly. Option B is wrong because empowerment gives discretion to workers, not to people at the top."}},{"itemId":"5668e39c-5884-5df6-bce2-f73a000f8a30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a11cc7ed-8b16-5ce5-b561-078abef36779","sourceKey":"bank:AMS101:M101-T9N-116","parentItemId":null,"revision":1,"payload":{"prompt":"The transfer and understanding of meaning is the definition of:","options":["Encoding","Communication","Feedback","Information overload"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Communication is the transfer and understanding of meaning, a two-way process between sender and receiver. Option A is only one stage of the process, turning a message into symbols."}},{"itemId":"4ca10879-4d6b-591b-88a1-8da6dd2659d1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4d9b59e5-cccb-5af2-a939-523ff22d4254","sourceKey":"bank:AMS101:M101-T9N-117","parentItemId":null,"revision":1,"payload":{"prompt":"Communication is described as a two-way process between:","options":["A channel and a noise","An encoder and a filter","A manager and the board of directors only","A sender and a receiver"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Communication is a two-way process between a sender and a receiver, with feedback closing the loop. Option A mixes up parts of the process: the channel carries the message and noise disturbs it."}},{"itemId":"7bfcaae3-bde0-5e55-8124-2bebbe24ca62","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"612246c8-6451-596e-94bb-efbd452bdf36","sourceKey":"bank:AMS101:M101-T9N-118","parentItemId":null,"revision":1,"payload":{"prompt":"Good communication is often described as the ____ of organizations.","options":["Final stage","Lifeblood","Chain of command","Backbone"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Good communication is called the lifeblood of organizations because it keeps everything else working. Option C is an official reporting line, which formal communication follows, not a description of communication itself."}},{"itemId":"31c930af-44cd-5bac-82cf-6563c496354f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"62c3f51a-2bb2-5877-8bc6-7047ea23b888","sourceKey":"bank:AMS101:M101-T9N-119","parentItemId":null,"revision":1,"payload":{"prompt":"Communication is said to be effective when:","options":["The receiver receives as much information as possible","The message is sent through the longest channel","People understand your meaning and reply in terms that move the exchange forward","The sender speaks for as long as possible"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Effective communication means people understand your meaning and respond in ways that move the exchange forward. Option A risks information overload, which is a barrier rather than a sign of effectiveness."}},{"itemId":"37dbe30a-e137-5036-bd35-aaab7cf1bfb3","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c656b4dc-0603-517c-b91b-22369de8d1f7","sourceKey":"bank:AMS101:M101-T9N-120","parentItemId":null,"revision":1,"payload":{"prompt":"How many rules for achieving clarity in communication are commonly given?","options":["Seven","Five","Three","Four"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"There are three rules for clarity: be clear in your own mind, deliver the message succinctly, and make sure it has been correctly understood. Option D is the number of functions of communication."}},{"itemId":"fb550c20-1508-5946-82ee-590e5dc20403","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"299f3bd1-8836-52d6-ad3c-657b6df88481","sourceKey":"bank:AMS101:M101-T9N-121","parentItemId":null,"revision":1,"payload":{"prompt":"The first rule for achieving clarity in communication is to:","options":["Ensure the message has been clearly and correctly understood","Be clear in your own mind about what you want to communicate","Choose the most expensive channel available","Deliver the message succinctly"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Clarity starts with the sender: first be clear in your own mind about what you want to say. Option D is the second rule and option A is the third."}},{"itemId":"f621cc8e-f50a-58f0-a656-7a82118ad09c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"845e7e3f-600a-5d51-afdb-3c28d230215a","sourceKey":"bank:AMS101:M101-T9N-122","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the rules for achieving clarity in communication?","options":["Include as much detail as possible in every message","Ensure the message has been clearly and correctly understood","Be clear in your own mind about what you want to communicate","Deliver the message succinctly"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The rules for clarity are to be clear in your own mind, deliver the message succinctly and check it was understood. Packing in as much detail as possible goes against delivering succinctly, while options C, D and B are the actual rules."}},{"itemId":"220b3450-a4ad-5da9-a368-740bf55d1eb4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9df8adba-24f4-5657-9531-6dad6a644d5c","sourceKey":"bank:AMS101:M101-T9N-123","parentItemId":null,"revision":1,"payload":{"prompt":"How many functions of communication are there?","options":["Three","Six","Five","Four"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Communication has four functions: control, motivation, emotional expression and information. Option B is the number of barriers to communication."}},{"itemId":"e3909ec5-84e0-5097-96a5-9925b55abfa4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d325d3e4-0d53-585b-8f73-0b207433288c","sourceKey":"bank:AMS101:M101-T9N-124","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four functions of communication?","options":["Control","Filtering","Emotional expression","Motivation"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"The four functions are control, motivation, emotional expression and information. Filtering is a barrier to communication, not one of its functions."}},{"itemId":"d03fdd81-66ab-58e3-9cd0-762ee1644e75","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db95c73c-f091-5ff6-8768-a34d3af4481c","sourceKey":"bank:AMS101:M101-T9N-125","parentItemId":null,"revision":1,"payload":{"prompt":"A hospital in Lagos requires all nurses to follow written policies and to report through set lines to the matron. Which function of communication is at work here?","options":["Control","Information","Motivation","Emotional expression"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Rules, policies and reporting lines that direct behaviour show the control function of communication. Option B is about giving data needed for decisions, not directing behaviour."}},{"itemId":"98e6cfc0-4244-5f6d-914a-e1460a98b698","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0b5c99ee-5fda-5cfa-99fa-accb1565dbc7","sourceKey":"bank:AMS101:M101-T9N-126","parentItemId":null,"revision":1,"payload":{"prompt":"A sales manager in Ikeja tells each sales officer what to do, how well he is doing against target and how he can improve. Which function of communication does this serve?","options":["Emotional expression","Control","Motivation","Information"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Telling staff what to do, how well they are doing and how to improve is the motivation function. Option B is about rules, policies and reporting lines that direct behaviour."}},{"itemId":"eaab355c-71d6-552c-abea-ee116c583f20","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"720973eb-2d8b-5665-a891-a250b9814db4","sourceKey":"bank:AMS101:M101-T9N-127","parentItemId":null,"revision":1,"payload":{"prompt":"In a weekly meeting, staff of a university department share their frustration over heavy workloads and their satisfaction with a new timetable. Which function of communication is this?","options":["Motivation","Information","Emotional expression","Control"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Sharing feelings, frustration and satisfaction is the emotional expression function. Option A is about guiding effort and improvement, not airing feelings."}},{"itemId":"9aa8f2ef-89b5-5555-92c6-f24c050a3b08","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b267477-a5e0-5616-a942-da4c904e2174","sourceKey":"bank:AMS101:M101-T9N-128","parentItemId":null,"revision":1,"payload":{"prompt":"The information function of communication is about:","options":["Sharing feelings of frustration and satisfaction","Directing behaviour through rules and policies","Giving the data needed to make decisions","Telling staff how they can improve"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The information function provides the data people need to make decisions. Option B is the control function and option A is emotional expression."}},{"itemId":"ee403fbe-d617-5842-b90c-469e9d8a472a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e3505674-fa01-5005-b657-a545a8cd6936","sourceKey":"bank:AMS101:M101-T9N-129","parentItemId":null,"revision":1,"payload":{"prompt":"How many parts make up the communication process, from sender to feedback?","options":["Six","Four","Seven","Five"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The process has seven parts: sender, encoding, message, channel, decoding, receiver and feedback. Noise can disturb any stage but is not counted as one of the seven parts."}},{"itemId":"f55709cc-7f0e-5c76-b5db-a48441725258","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"85b0f706-44b8-5e84-8ec9-d20eba7bd76f","sourceKey":"bank:AMS101:M101-T9N-130","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the correct order of the communication process?","options":["Sender, encoding, message, channel, decoding, receiver, feedback","Sender, message, encoding, channel, receiver, decoding, feedback","Sender, encoding, channel, message, decoding, feedback, receiver","Receiver, decoding, message, channel, encoding, sender, feedback"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The process runs sender, encoding, message, channel, decoding, receiver and finally feedback. Option B wrongly puts the message before encoding, when the sender must first encode it."}},{"itemId":"56a414a9-0f96-58b1-ac38-3bfae56a388a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"dd23e451-5bbb-5f66-abb6-c47b6621d5ee","sourceKey":"bank:AMS101:M101-T9N-131","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, which part comes immediately after encoding?","options":["Message","Channel","Decoding","Receiver"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"After the sender encodes the idea into symbols, the result is the message, which then travels along a channel. Option B comes next, after the message."}},{"itemId":"d83d09c6-c21a-5f61-9f2f-59cffe70747a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9059f541-0c65-5002-8ac4-c21fd57db393","sourceKey":"bank:AMS101:M101-T9N-132","parentItemId":null,"revision":1,"payload":{"prompt":"What is the last part of the communication process?","options":["Decoding","Noise","Receiver","Feedback"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Feedback is the last part, and it checks whether the message was understood. Option B is not a final stage because noise can disturb any stage."}},{"itemId":"c988dd56-c03f-572b-ae57-7cead38fd881","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"26726f35-a819-5329-87f5-0c09239f286d","sourceKey":"bank:AMS101:M101-T9N-133","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, who does the decoding?","options":["The receiver","The noise","The channel","The sender"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The receiver decodes, translating the message, while the sender encodes it. Option D reverses these roles, which is a common exam trap."}},{"itemId":"4f3292dd-20ff-53b3-95bd-7ab09ad0ad30","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ec56c596-e728-5964-9e42-9848e3c288a4","sourceKey":"bank:AMS101:M101-T9N-134","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, turning a message into symbols is called:","options":["Feedback","Decoding","Encoding","Channel"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Encoding is turning the message into symbols, done by the sender. Option B is the receiver translating those symbols back into meaning."}},{"itemId":"14036b1d-f49e-56e2-a231-52e3aff5c60f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"12303f10-5496-5fbc-9c53-969ef5da5df5","sourceKey":"bank:AMS101:M101-T9N-135","parentItemId":null,"revision":1,"payload":{"prompt":"The medium along which a message travels in the communication process is called the:","options":["Noise","Receiver","Encoding","Channel"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The channel is the medium the message travels along, such as a memo, email or phone call. Option A is anything that disturbs the message, not the medium itself."}},{"itemId":"6b3ec1c0-f86d-535a-9244-c712ff452d03","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d05c4d4c-dc40-54f7-bf93-d76679d7ddc9","sourceKey":"bank:AMS101:M101-T9N-136","parentItemId":null,"revision":1,"payload":{"prompt":"Illegible print, static on a phone line and inattention by the listener are all examples of:","options":["Noise","Feedback","Channel","Encoding"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Noise is anything that disturbs the message, such as illegible print, phone static or inattention. Option C is the medium the message travels along, which noise can disturb."}},{"itemId":"37bf0f22-0b5a-59d7-a8e8-40b2b12e3f0f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"035066fb-0210-55c8-b1bb-33cca07043f2","sourceKey":"bank:AMS101:M101-T9N-137","parentItemId":null,"revision":1,"payload":{"prompt":"At which stage of the communication process can noise occur?","options":["Only at the encoding stage","Only at the decoding stage","Only at the feedback stage","At any stage"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Noise can disturb any stage of the communication process, not just one. Options A, C and B wrongly limit it to a single stage."}},{"itemId":"fd5321fb-d5dc-5ea4-953f-a60feb001ced","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bcf6ae1d-a438-5ba3-95f7-084ce5ea4a40","sourceKey":"bank:AMS101:M101-T9N-138","parentItemId":null,"revision":1,"payload":{"prompt":"How many types of communication are commonly identified?","options":["Three","Six","Four","Five"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"There are five types: written words, spoken words, symbolic gestures, visual images and multimedia. Option C is the number of functions of communication."}},{"itemId":"9c11c81c-b320-5906-8c40-0f14aadddc1b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f7e4c4f3-bd13-5cf0-99f5-ad2a944b0536","sourceKey":"bank:AMS101:M101-T9N-139","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five types of communication?","options":["Written words","Multimedia","Symbolic gestures","Grapevine"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The five types are written words, spoken words, symbolic gestures, visual images and multimedia. The grapevine is an informal communication network, not a type of communication."}},{"itemId":"005b8afc-fc2d-5869-bb42-15087558361a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db8fc7ef-0a41-5146-9e17-59ccbbc40f31","sourceKey":"bank:AMS101:M101-T9N-140","parentItemId":null,"revision":1,"payload":{"prompt":"Memos, reports, proposals and contracts belong to which type of communication?","options":["Multimedia","Visual images","Written words","Spoken words"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Letters, memos, reports, proposals, notices and contracts are written words. Option B covers things like charts, photographs and logos."}},{"itemId":"443536ce-fdaf-5c53-9468-e07ef3bed6b0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0923b492-4ea0-5259-a97d-be6b745eee74","sourceKey":"bank:AMS101:M101-T9N-141","parentItemId":null,"revision":1,"payload":{"prompt":"Interviews, phone calls, debates and announcements belong to which type of communication?","options":["Written words","Multimedia","Spoken words","Symbolic gestures"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Conversations, interviews, meetings, phone calls, debates, speeches and announcements are spoken words. Option D covers things the audience sees, such as gestures and posture."}},{"itemId":"b249bb8a-473a-5db9-9afd-7a0962f9b404","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"922b1db4-1390-5bf7-98b6-56eadd6fc6ed","sourceKey":"bank:AMS101:M101-T9N-142","parentItemId":null,"revision":1,"payload":{"prompt":"Silence, posture, tone of voice and a manager's absence from an event are examples of which type of communication?","options":["Spoken words","Symbolic gestures","Written words","Visual images"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Symbolic gestures include facial expressions, tone of voice, silence, posture, absence and presence, any behaviour the audience can see or hear. Option A is wrong because silence and absence involve no words at all."}},{"itemId":"e8e7e657-40f3-5cb0-b260-dc1a45afe57e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"783c0939-c444-56d1-ab71-e89c0fdbf364","sourceKey":"bank:AMS101:M101-T9N-143","parentItemId":null,"revision":1,"payload":{"prompt":"A company's logo, colour scheme, charts and photographs are examples of which type of communication?","options":["Symbolic gestures","Visual images","Written words","Multimedia"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Logos, colour schemes, charts, graphs and photographs are visual images. Option D is a combination of these methods delivered through media such as television, radio and the internet."}},{"itemId":"3f54f67b-eb39-5da6-b0e0-3723bc1c85fb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"66ce132a-6474-564c-be1d-dbf82da7faa5","sourceKey":"bank:AMS101:M101-T9N-144","parentItemId":null,"revision":1,"payload":{"prompt":"Television, radio, newspapers, flyers and posters belong to which type of communication?","options":["Spoken words","Multimedia","Written words","Visual images"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Television, newspapers, radio, flyers, posters and the internet are multimedia. Option D is easy to confuse, but multimedia is a combination of the methods under visual images."}},{"itemId":"8d1b83fe-a182-5311-a8fc-53f69a5cea9d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4165ebd9-b7b4-521d-a1f9-c24485cbd4d4","sourceKey":"bank:AMS101:M101-T9N-145","parentItemId":null,"revision":1,"payload":{"prompt":"Multimedia as a type of communication is best described as:","options":["A combination of the various methods described under visual images","Any behaviour the audience can see or hear","Words written in any language or medium","Words that are effective only when heard by the right people"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Multimedia combines the various methods described under visual images. Option B describes symbolic gestures and option D describes spoken words."}},{"itemId":"cce4c388-5b72-5223-a72f-982278da8eef","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"63b29f86-d2a2-5336-a144-a9e672322fe0","sourceKey":"bank:AMS101:M101-T9N-146","parentItemId":null,"revision":1,"payload":{"prompt":"Spoken words as a type of communication are effective only when:","options":["They are heard by the right people","They are spoken in a foreign language","They are written down in a memo","They are combined with television and radio"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Spoken words work only when they are heard by the right people. Option C turns them into written words, a different type of communication."}},{"itemId":"aa5f3887-2fba-5167-b34a-0d5a5d9fd49f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1b64e786-2325-5bc0-8d9a-191f46f07b36","sourceKey":"bank:AMS101:M101-T9N-147","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between interpersonal communication and organizational communication?","options":["Interpersonal covers all networks in an organization; organizational is between two people","Interpersonal is always written; organizational is always spoken","Interpersonal is between two or more people; organizational covers all the patterns, networks and systems within an organization","There is no difference between the two terms"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Interpersonal communication takes place between two or more people, while organizational communication covers all the patterns, networks and systems of communication in an organization. Option A swaps the two meanings."}},{"itemId":"0f5320e1-eda7-57e8-8af4-0c8fad1478a6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"6873c8b3-eee9-5eab-bd4f-083dbaffb630","sourceKey":"bank:AMS101:M101-T9N-148","parentItemId":null,"revision":1,"payload":{"prompt":"Gestures, facial expressions and other body movements that convey meaning are known as:","options":["Encoding","Filtering","Body language","Verbal intonation"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Body language covers gestures, facial expressions and body movements, a form of nonverbal communication. Option D is the emphasis given to words or phrases, which is about the voice, not the body."}},{"itemId":"106f3aa8-da2c-51dd-898b-c3a68fa51b51","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3999004a-1b4c-5876-8011-5fe60e58b4b2","sourceKey":"bank:AMS101:M101-T9N-149","parentItemId":null,"revision":1,"payload":{"prompt":"The emphasis a speaker gives to particular words or phrases, which can change the meaning of the same words, is called:","options":["Body language","Decoding","Information overload","Verbal intonation"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Verbal intonation is the emphasis given to words or phrases, and tone can change the meaning of identical words. Option A concerns gestures and facial expressions rather than how words are said."}},{"itemId":"f0e18734-5c4c-5696-b03e-3fa233c4add0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"7c068b3c-2aa5-5a7f-af6d-caeec8a4f6fe","sourceKey":"bank:AMS101:M101-T9N-150","parentItemId":null,"revision":1,"payload":{"prompt":"Nonverbal communication is communication that is:","options":["Sent only through multimedia","Sent without words","Limited to telephone calls","Always written down"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Nonverbal communication is sent without words, for example through body language. Option D still uses words, just written instead of spoken."}},{"itemId":"72c0f212-023b-51df-92cc-981a3ee1a5e1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"0d806a39-4c5a-5bc0-b6cf-9c28fa6c6369","sourceKey":"bank:AMS101:M101-T9N-151","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback is essential to communication because it:","options":["Carries the message from sender to receiver","Turns the sender's idea into symbols","Checks that you have understood the other person's message and lets you react to it","Deliberately changes information to please the receiver"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Feedback checks that you have understood the other person and lets you react to what they said and did. Option B is encoding and option A is the channel."}},{"itemId":"991faa9e-6f70-5ad5-8543-38f87b5d44f6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"726a3f99-111a-5e2a-b6e3-2795fa1a50b9","sourceKey":"bank:AMS101:M101-T9N-152","parentItemId":null,"revision":1,"payload":{"prompt":"How many rules for giving negative feedback without causing antagonism are commonly given?","options":["Three","Four","Six","Five"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"There are five rules for giving negative feedback without antagonism. Option A is the number of rules for achieving clarity, and option C is the number of barriers."}},{"itemId":"3e36186f-cb28-5044-af38-7aeca89a38da","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"db63b309-e0c5-5668-8c37-08698093df24","sourceKey":"bank:AMS101:M101-T9N-153","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following IS a rule for giving negative feedback without causing antagonism?","options":["Show your anger so the person knows how serious it is","Avoid explaining what went wrong","Use questions rather than assertions to let the person know what you mean","Use assertions rather than questions to make your point firmly"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"One rule is to use questions rather than assertions to get your meaning across. Option D reverses that rule, and option A breaks the rule to be objective and not emotional."}},{"itemId":"e5cfd00a-e885-5449-97b6-9b6dedc4ff39","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"5e23e07b-44d3-5b1c-98d9-5eae618ce88c","sourceKey":"bank:AMS101:M101-T9N-154","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a rule for giving negative feedback?","options":["Make the criticism personal so it is remembered","Draw out ways in which poor performance can improve","Show an understanding of exactly what went wrong, and why","Express your negative opinions honestly, but in a positive manner"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Negative feedback should be objective and should avoid being emotional or personal, so making it personal breaks the rules. Options C, B and D are all genuine rules for giving negative feedback."}},{"itemId":"147354c2-c997-58a0-95e9-90c86ed937fa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cdb2a445-74a4-5c93-98ff-f596ac714ad1","sourceKey":"bank:AMS101:M101-T9N-155","parentItemId":null,"revision":1,"payload":{"prompt":"A supervisor at a Lagos bank must tell a teller that his cash counts have often been wrong. Which approach follows the rules for giving negative feedback?","options":["Criticize him loudly in front of customers","Hint vaguely at a problem without naming it","Explain exactly what went wrong and why, and stay objective rather than emotional","Avoid the issue, because negative feedback should never be given"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The rules say to show exactly what went wrong and why, and to be objective rather than emotional or personal. Option D is wrong because negative feedback has to be given when it is the only thing to do."}},{"itemId":"ecb3d616-1a74-5812-a7a9-3815ef6fb206","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"03ab2b78-b332-5fd8-99b9-d87670e7df92","sourceKey":"bank:AMS101:M101-T9N-156","parentItemId":null,"revision":1,"payload":{"prompt":"When should negative feedback be given?","options":["Only after an employee resigns","Only in writing, never face to face","Never, because it always causes antagonism","When it is the only thing to do, even though it can be difficult"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Negative feedback can be hard to give, but it must be given when it is the only thing to do. Option C is wrong because following the rules helps avoid antagonism."}},{"itemId":"745f5265-b085-5ecd-a208-dd3b4fdf497b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"26112cd3-f413-5e01-a5c4-1fcf82431f34","sourceKey":"bank:AMS101:M101-T9N-157","parentItemId":null,"revision":1,"payload":{"prompt":"How many barriers to communication are commonly identified?","options":["Six","Five","Four","Seven"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Six barriers are identified: filtering, emotions, information overload, defensiveness, language and national culture. Option B is the number of ways to overcome barriers."}},{"itemId":"8cdd0a4e-9065-5e8a-aabe-93228178086e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ae12cc34-4a07-5dca-8653-e7ce0f32f348","sourceKey":"bank:AMS101:M101-T9N-158","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a barrier to communication?","options":["Defensiveness","Active listening","National culture","Filtering"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Active listening is one of the ways to overcome barriers, not a barrier itself. Options D, A and C are all among the six barriers."}},{"itemId":"802c7243-3f5c-5aa0-be00-bf8372f6dd40","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f7bc57fd-e0bd-5bbc-a56b-277503c9ff48","sourceKey":"bank:AMS101:M101-T9N-159","parentItemId":null,"revision":1,"payload":{"prompt":"Deliberately changing information so that it looks better to the receiver is the communication barrier called:","options":["Information overload","Defensiveness","Encoding","Filtering"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Filtering is deliberately changing information so it looks more favourable to the receiver. Option B is reacting in threatened ways that block understanding, not altering information."}},{"itemId":"1dd92dcc-f3c9-5468-8246-43d25ddd602a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"59e5b3b6-bd92-533f-97a2-6d27b92f34bd","sourceKey":"bank:AMS101:M101-T9N-160","parentItemId":null,"revision":1,"payload":{"prompt":"An accountant at a manufacturing firm in Ota tells the managing director only the good news about quarterly sales because he knows that is what the MD wants to hear. Which barrier to communication is this?","options":["National culture","Language","Filtering","Emotions"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Telling the boss what he wants to hear is a classic example of filtering. Option D is about how the receiver's feelings shape how he reads a message."}},{"itemId":"cf3f60e1-bcdf-5eab-a348-286af16de62c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f69655b4-b803-5f4a-a81f-663ce1d23d29","sourceKey":"bank:AMS101:M101-T9N-161","parentItemId":null,"revision":1,"payload":{"prompt":"A new manager at a bank in Lagos receives hundreds of emails and reports every day and cannot process them all. Which barrier to communication is she facing?","options":["Language","Information overload","Filtering","Defensiveness"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Information overload happens when the information is more than a person can process. Option C involves someone deliberately changing information, which is not happening here."}},{"itemId":"15e21199-879d-5912-b898-94b40e05dcc0","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"fdfd3b4a-e795-5851-8332-38627db19fc2","sourceKey":"bank:AMS101:M101-T9N-162","parentItemId":null,"revision":1,"payload":{"prompt":"When a nurse at a hospital is questioned about a mistake, she feels threatened and responds with sarcasm and attacks on her colleague. Which barrier to communication is this?","options":["Filtering","Defensiveness","Information overload","Emotions"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Defensiveness is when a person who feels threatened reacts in ways that block understanding, such as attacking or sarcasm. Option D is close, but it refers to how the receiver's mood colours his reading of the message, not to reactions to feeling threatened."}},{"itemId":"0cdb82f8-601f-567f-9412-10b5fb9a0fcf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"80b34ee4-c5f7-5112-b69c-2d42ab92064f","sourceKey":"bank:AMS101:M101-T9N-163","parentItemId":null,"revision":1,"payload":{"prompt":"An IT officer at a university uses technical jargon when briefing older administrative staff, who do not understand him. Which barrier to communication is this?","options":["National culture","Language","Defensiveness","Filtering"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Language is a barrier because words mean different things to different people, and age, education and jargon all matter. Option A concerns differences in how whole cultures communicate."}},{"itemId":"90f73254-35e3-5aa5-8280-7b4e5b6d6857","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"1c570b6a-172f-5762-8c2c-de3fb7c30739","sourceKey":"bank:AMS101:M101-T9N-164","parentItemId":null,"revision":1,"payload":{"prompt":"As a barrier to communication, 'emotions' refers to:","options":["The sender deliberately changes information","Cultures differ in how they communicate","The information is more than a person can process","How the receiver feels changes how he reads the message"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The emotions barrier means the receiver's feelings at the time change how he interprets the message. Option A is filtering and option C is information overload."}},{"itemId":"020790c5-ab2c-5d51-a3dd-b8f28a605430","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c7658424-777e-5b36-9929-045f8dd1bb50","sourceKey":"bank:AMS101:M101-T9N-165","parentItemId":null,"revision":1,"payload":{"prompt":"The barrier to communication called national culture refers to the fact that:","options":["Cultures differ in how they communicate","Words mean different things to people of different ages","Information is changed to look better to the receiver","A person who feels threatened reacts badly"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"National culture is a barrier because cultures differ in how they communicate. Option B describes the language barrier."}},{"itemId":"83b94b73-a156-51df-9605-122016a9d59f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"d0e0c03f-75bd-5eb3-b7f8-a5bd23873aa9","sourceKey":"bank:AMS101:M101-T9N-166","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the ways to overcome barriers to communication?","options":["Filter information before passing it on","Simplify language","Use feedback","Watch nonverbal cues"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"The ways to overcome barriers are to use feedback, simplify language, listen actively, constrain emotions and watch nonverbal cues. Filtering is itself a barrier, so it cannot be a way to overcome barriers."}},{"itemId":"18afc9ad-1c85-50cf-ae1d-6544b8a10f8c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"8df13fb4-f84f-5a82-9cff-db204c47dac4","sourceKey":"bank:AMS101:M101-T9N-167","parentItemId":null,"revision":1,"payload":{"prompt":"How many ways of overcoming barriers to communication are commonly listed?","options":["Four","Six","Five","Three"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Five ways are listed: use feedback, simplify language, listen actively, constrain emotions and watch nonverbal cues. Option B is the number of barriers, not the number of remedies."}},{"itemId":"3b0bd759-60e1-591a-b327-9532f89ceda7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"40d65a9d-beff-59fc-b90b-2dbc7dd92411","sourceKey":"bank:AMS101:M101-T9N-168","parentItemId":null,"revision":1,"payload":{"prompt":"Listening for full meaning without judging too early, by making eye contact, asking questions and paraphrasing, is called:","options":["Filtering","Decoding","Constraining emotions","Active listening"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Active listening means listening for full meaning without judging too early, using eye contact, questions and paraphrasing. Option B is just the receiver translating the message, not a deliberate listening skill."}},{"itemId":"e040f4be-ff94-51b4-b808-72c8ac2ff48e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f8a00cb4-85a4-5fef-a98c-9042ab6509e6","sourceKey":"bank:AMS101:M101-T9N-169","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of active listening?","options":["Interrupting the speaker to correct him quickly","Paraphrasing","Asking questions","Making eye contact"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Active listening involves eye contact, asking questions and paraphrasing, and it avoids interrupting. Options D, C and B are all part of active listening."}},{"itemId":"8931567b-1325-5dea-8b88-b56baf01bdff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"601719b7-dc33-52e7-b67b-6179c987e748","sourceKey":"bank:AMS101:M101-T9N-170","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between formal and informal communication?","options":["Formal communication is always spoken; informal communication is always written","Formal communication follows the official chain of command or is needed to do a job; informal communication is not defined by the hierarchy","Formal communication flows only upward; informal communication flows only downward","Formal communication is not defined by the hierarchy; informal communication follows the chain of command"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Formal communication follows the official chain of command or is required to do a job, while informal communication is not defined by the hierarchy. Option D swaps the two definitions."}},{"itemId":"166a632e-95e3-585e-8652-117d515bc302","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"de372daa-2256-5069-91ab-c502d7d696b6","sourceKey":"bank:AMS101:M101-T9N-171","parentItemId":null,"revision":1,"payload":{"prompt":"In how many directions can communication flow in an organization?","options":["Two","Five","Four","Three"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Communication can flow downward, upward, laterally and diagonally, which makes four directions. Option D is the number of communication networks."}},{"itemId":"484e0601-039a-5cc8-a8c6-17854824329d","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"a3639258-91c3-5562-9c24-277bfd45fc27","sourceKey":"bank:AMS101:M101-T9N-172","parentItemId":null,"revision":1,"payload":{"prompt":"A manager at a bank in Lagos sends goals, instructions and new policies to the employees in her unit. In which direction is this communication flowing?","options":["Downward","Upward","Diagonal","Lateral"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Communication from a manager to employees, such as goals, instructions and policies, flows downward. Option B is the reverse, from employees to the manager."}},{"itemId":"e6aac439-f7ce-5b78-b668-4b04b98e1bbf","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"575b856b-cd47-5af1-b889-98f2f3c89bd9","sourceKey":"bank:AMS101:M101-T9N-173","parentItemId":null,"revision":1,"payload":{"prompt":"Staff at a factory in Ota send their supervisor progress reports, suggestions and complaints. In which direction is this communication flowing?","options":["Downward","Lateral","Diagonal","Upward"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Reports, suggestions and complaints from employees to their manager flow upward. Option A runs from manager to employees instead."}},{"itemId":"a724c3c3-7dd3-50b0-8d5f-3fd3799efa1e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"ce23094b-58d4-5a3c-8fea-6a3ffb460a22","sourceKey":"bank:AMS101:M101-T9N-174","parentItemId":null,"revision":1,"payload":{"prompt":"Members of a cross-functional team at the same level, drawn from marketing and finance in a Lagos company, share information with one another. This is which direction of communication?","options":["Diagonal","Downward","Lateral","Upward"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"Communication among employees at the same level, as in a cross-functional team, is lateral. Option A requires a difference in both work area and level."}},{"itemId":"70411136-ae10-53aa-8eac-5055634dd6c8","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"b011a1df-aa45-5457-a482-2c19d88aef11","sourceKey":"bank:AMS101:M101-T9N-175","parentItemId":null,"revision":1,"payload":{"prompt":"A junior analyst in the finance department of a hospital emails the head of the pharmacy department directly. In which direction is this communication flowing?","options":["Diagonal","Upward","Lateral","Downward"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Diagonal communication cuts across both work areas and levels, as when an analyst emails a manager in another department. Option C is only for people at the same level."}},{"itemId":"b67788ef-4098-5f64-a289-d36318b17dc6","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"e6ffba4c-28dd-5a02-930f-115f011219bd","sourceKey":"bank:AMS101:M101-T9N-176","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between lateral and diagonal communication?","options":["Lateral crosses different levels; diagonal is among people at the same level","Lateral is among people at the same level; diagonal crosses both different levels and different departments","Lateral is from manager to employee; diagonal is from employee to manager","Both mean exactly the same thing"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Lateral communication flows among employees at the same level, while diagonal communication crosses both work areas and levels. Option A swaps the two meanings."}},{"itemId":"6a85c79e-65a7-54ff-8b59-6e738e8ab936","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"c382ddea-ebe7-5649-b379-d1680ad558ba","sourceKey":"bank:AMS101:M101-T9N-177","parentItemId":null,"revision":1,"payload":{"prompt":"The three common communication networks are:","options":["Chain, grapevine and matrix","Wheel, circle and pyramid","Chain, wheel and all-channel","Upward, downward and lateral"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The three communication networks are the chain, the wheel and the all-channel. Option D lists directions of communication flow, not networks."}},{"itemId":"b47586c5-da8f-5a49-ae72-6ce0d4f79bff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"3c728515-4fe8-5ef7-81b0-8019be0fa680","sourceKey":"bank:AMS101:M101-T9N-178","parentItemId":null,"revision":1,"payload":{"prompt":"In which communication network does all communication pass through a strong central leader?","options":["Chain","All-channel","Wheel","Grapevine"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"In the wheel network every message passes through a strong central leader. Option B is the opposite, with everyone talking freely to everyone."}},{"itemId":"c0b26b14-42d0-54a7-b005-17f4adfbdbf5","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"4e525d62-0472-59c1-92c0-36a89dd2c428","sourceKey":"bank:AMS101:M101-T9N-179","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication network follows the formal chain of command?","options":["All-channel","Wheel","Grapevine","Chain"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The chain network follows the formal chain of command, with moderate speed and high accuracy. Option C is informal and not defined by the hierarchy."}},{"itemId":"008b2722-4d03-545e-8832-10d8688edbe1","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"94b1ad70-bdce-5b74-bf10-0c081c96816c","sourceKey":"bank:AMS101:M101-T9N-180","parentItemId":null,"revision":1,"payload":{"prompt":"In a self-managed team at a software firm in Yaba, every member talks freely with every other member and no single leader emerges. This is which communication network?","options":["Chain","All-channel","Wheel","Lateral"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"In the all-channel network everyone talks freely to everyone, as in self-managed teams, and no leader emerges. Option C is built around a strong central leader."}},{"itemId":"febc861e-c774-5e70-bba7-87a60c79286b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"51582f12-3d18-5109-894a-56133dc03d23","sourceKey":"bank:AMS101:M101-T9N-181","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication network gives the LOWEST member satisfaction?","options":["None of the networks differ in satisfaction","All-channel","Chain","Wheel"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"The wheel network is fast and accurate, but member satisfaction is low because everything passes through one central leader. Option B gives the highest satisfaction."}},{"itemId":"fbb77645-9a9a-549d-9aa1-f314658d416e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"90d5be5b-3b6a-530b-8224-467e952ccb94","sourceKey":"bank:AMS101:M101-T9N-182","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication network gives the HIGHEST member satisfaction?","options":["None of the networks differ in satisfaction","Chain","All-channel","Wheel"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The all-channel network gives high member satisfaction because everyone can talk freely to everyone. Option D has low satisfaction despite its speed."}},{"itemId":"dc2a9324-fdc7-5552-bca6-2a4431f8a99b","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"21390fa3-2060-5ee1-88c6-7f5f36db0386","sourceKey":"bank:AMS101:M101-T9N-183","parentItemId":null,"revision":1,"payload":{"prompt":"In which communication network does a leader emerge most strongly?","options":["Chain","Grapevine","All-channel","Wheel"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Leader emergence is high in the wheel network because everything flows through a central leader. Option C is the network where no leader emerges at all."}},{"itemId":"0f2a3bfe-9a5d-51a2-8c70-2415adffbaea","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"679f048a-6ef0-5040-971b-dc143b734b2e","sourceKey":"bank:AMS101:M101-T9N-184","parentItemId":null,"revision":1,"payload":{"prompt":"The grapevine is best defined as:","options":["A network that links an organization with its suppliers","A barrier caused by too much information","The informal organizational communication network","The formal chain of command in an organization"],"correctOption":2,"section":"Leadership, Trust and Communication","explanation":"The grapevine is the informal communication network of an organization. Option D is the formal route, and option A describes an extranet."}},{"itemId":"11834a82-07bb-53e1-8a83-9db837dd67fc","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"540dcc6d-a759-5a7b-a35d-97227f9276ea","sourceKey":"bank:AMS101:M101-T9N-185","parentItemId":null,"revision":1,"payload":{"prompt":"How should managers deal with the grapevine?","options":["Eliminate it completely by banning informal conversations","Use it as a source of feedback and limit harmful rumours through open, honest communication","Ignore it, since it never affects employees","Replace it with the wheel network"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Managers cannot remove the grapevine, so they should use it to pick up feedback and limit harmful rumours through open and honest communication. Option A is wrong because the grapevine cannot be eliminated."}},{"itemId":"64db956c-8a68-519e-899d-e88a4de8fffa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"cee421a5-ea1f-56be-b841-47e4c714fd7e","sourceKey":"bank:AMS101:M101-T9N-186","parentItemId":null,"revision":1,"payload":{"prompt":"A communication network inside an organization that uses internet technology and is open only to staff is called:","options":["A wheel network","An intranet","An extranet","The grapevine"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"An intranet uses internet technology inside the organization and is open only to staff. Option C also uses internet technology but links the organization with approved outsiders."}},{"itemId":"2e5f74c0-6bfe-5131-8ebd-fd8266a718ff","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"2a1bbc83-2990-5fd6-92d2-0531e7547bbc","sourceKey":"bank:AMS101:M101-T9N-187","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer in Ota sets up a secure network using internet technology so that its approved suppliers and major customers can check orders and deliveries. This network is:","options":["An intranet","An extranet","The grapevine","An all-channel network"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"An extranet uses internet technology to link an organization with approved outsiders such as customers and suppliers. Option A is open only to staff, not to outsiders."}},{"itemId":"3cc913d0-7199-5f0b-95b1-883653ff891e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"9a90c215-8659-5ced-8416-ad2558fe0242","sourceKey":"bank:AMS101:M101-T9N-188","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a problem that information technology can create for communication?","options":["Security of data","Less face-to-face contact","Information overload","Slower and less complete information for managers"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Information technology gives managers faster and more complete information, so slower, less complete information is not one of its problems. Options C, A and B are the problems it can raise."}},{"itemId":"27b2f3c6-40c7-53bc-a589-6ce95a67892c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"075020e0-16d0-5d75-bb8c-01086d78d1d1","sourceKey":"bank:AMS101:M101-T9N-189","parentItemId":null,"revision":1,"payload":{"prompt":"How has wireless technology changed workplace communication?","options":["Staff can now communicate only through the grapevine","Staff no longer need to be at their desks to communicate","It has removed the need for any feedback","It allows only downward communication"],"correctOption":1,"section":"Leadership, Trust and Communication","explanation":"Wireless technology means staff no longer need to be at their desks to communicate. Option C is wrong because feedback is still the part that checks whether a message was understood."}},{"itemId":"b852d8f7-9b34-50cd-b6dd-6ca44bed864f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"f4f240e3-453c-50fb-8586-dcc9f748a72b","sourceKey":"bank:AMS101:M101-T9N-190","parentItemId":null,"revision":1,"payload":{"prompt":"When managing information for employees, a manager should start by finding out:","options":["What people most want to know about, such as job security, working conditions and reward","Which rumours on the grapevine are false","Which employees can be kept uninformed","How to filter bad news before it reaches staff"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Good information management starts by finding out what people most want to know about, such as job security, working conditions, reward, location and other benefits. Option D describes filtering, a barrier that undermines honest communication."}},{"itemId":"4aa0b6c9-79ea-54bf-9723-ed3a2a2d9640","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"bba6142b-1fd0-5280-a7e4-e5f159c44db5","sourceKey":"bank:AMS101:M101-T9N-191","parentItemId":null,"revision":1,"payload":{"prompt":"Which two things are described as essential for good information management?","options":["Jargon and speed","Filtering and secrecy","Coercion and control","Honesty and feedback"],"correctOption":3,"section":"Leadership, Trust and Communication","explanation":"Honesty and feedback are both essential for good information management. Option B lists a barrier and a habit that would damage trust and understanding."}},{"itemId":"b5b3ef81-6397-5c36-a086-7582acce3a9e","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"cbt_question","questionId":"476bfbd3-7f49-59d8-866e-9782bb013470","sourceKey":"bank:AMS101:M101-T9N-192","parentItemId":null,"revision":1,"payload":{"prompt":"Networked computer systems link staff through all of the following, EXCEPT:","options":["The grapevine","Voice mail","Instant messaging","Videoconferencing"],"correctOption":0,"section":"Leadership, Trust and Communication","explanation":"Networked computer systems link staff by email, instant messaging, voice mail, fax, teleconferencing, videoconferencing and web conferencing. The grapevine is the informal communication network, not a networked computer tool."}}]$expected_content$::jsonb,
  'principles-management: cbt_question published payload and identity match source');
