  from public.read_published_managed_content('fa9abff6-1f94-5735-bbd3-c9104da6df05')
  where kind = 'theory_question') = $expected_content$[{"itemId":"18575d93-235d-5ae2-971c-dc04634c2596","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Define management and explain its four functions."}},{"itemId":"6d50cf35-2fa6-5b75-87ec-b821597a8811","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:10","parentItemId":null,"revision":1,"payload":{"prompt":"Define controlling and explain the steps in the control process."}},{"itemId":"860e6a6e-f521-5acc-9133-ca48c349ee04","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between the classical and socioeconomic views of social responsibility, and explain social obligation, social responsiveness and social responsibility."}},{"itemId":"b1536dbc-f454-5dad-8fa7-0dae17d04b05","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the steps in the strategic management process. Distinguish between growth, stability and renewal strategies."}},{"itemId":"829a57bc-6a83-58b7-8f63-2b5338a3a853","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the six key elements of organizational design."}},{"itemId":"07639d6e-7ae4-5601-b110-361c95df96aa","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the HRM process and describe four methods of appraising performance."}},{"itemId":"9c690f6d-55fa-51be-9dca-8e0f4183c11f","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"Explain why employees resist organizational change and discuss the techniques managers can use to reduce resistance."}},{"itemId":"42bbfaf2-990f-56e5-b3bd-ae66a546c271","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between a group and a team, and explain the five stages of group development."}},{"itemId":"a46fb73b-a0ea-527f-8974-fb4bb16711f4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"Explain Herzberg's two-factor theory and state its implications for managers."}},{"itemId":"cc2c6fa5-15c2-5c75-b5b3-06e96b7c032a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:9","parentItemId":null,"revision":1,"payload":{"prompt":"Explain how trust is built in leadership, and discuss three barriers to effective communication in an organization."}}]$expected_content$::jsonb,
  'principles-management: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('fa9abff6-1f94-5735-bbd3-c9104da6df05')
  where kind = 'model_answer') = $expected_content$[{"itemId":"d0e7d3fa-6302-5e8c-9a3e-4b6553b8bbd7","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"18575d93-235d-5ae2-971c-dc04634c2596","revision":1,"payload":{"body":"Define management. Then 1-2 lines each: planning (goals and how to reach them), organizing (structuring work), leading (directing and motivating), controlling (monitoring, comparing, correcting)."}},{"itemId":"854b201f-015d-53b2-94b2-5e5490980683","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:10","parentItemId":"6d50cf35-2fa6-5b75-87ec-b821597a8811","revision":1,"payload":{"body":"Define controlling; standards come from planning. (1) Measure, 4 sources; (2) compare, range of variation; (3) act: do nothing, correct (immediate or basic) or revise the standard."}},{"itemId":"55d09d3d-b557-5a5e-9faf-2de5c99feedb","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"860e6a6e-f521-5acc-9133-ca48c349ee04","revision":1,"payload":{"body":"Classical: stockholder profit (Friedman). Socioeconomic: society's welfare. Obligation: legal and economic duties only. Responsiveness: adapting to societal conditions. Responsibility: ethical commitment beyond law."}},{"itemId":"3d4abb28-c91f-558e-ae7f-a1058afe4665","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"b1536dbc-f454-5dad-8fa7-0dae17d04b05","revision":1,"payload":{"body":"Define strategic management. Explain the 6 steps, noting SWOT. Define growth, stability and renewal (retrenchment, turnaround), with an example each."}},{"itemId":"161cbd1a-07b0-5169-93ce-fd07e66d01b4","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"829a57bc-6a83-58b7-8f63-2b5338a3a853","revision":1,"payload":{"body":"Define organizational design; explain each element in a line or two (departmentalization: five types); conclude: together they decide mechanistic or organic."}},{"itemId":"244a858f-8785-547c-95a7-92c0d54272b9","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"07639d6e-7ae4-5601-b110-361c95df96aa","revision":1,"payload":{"body":"Define HRM; the 8 activities in 3 groups; external factors; four methods."}},{"itemId":"7992673e-7de6-5c77-9adb-6888a0ec601a","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"9c690f6d-55fa-51be-9dca-8e0f4183c11f","revision":1,"payload":{"body":"Define organizational change. Give the 4 reasons for resistance. Explain the 6 techniques with when used and one drawback."}},{"itemId":"e0adef81-b4e3-51bc-bdb0-7c25e40f6cee","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"42bbfaf2-990f-56e5-b3bd-ae66a546c271","revision":1,"payload":{"body":"Define each. Give the five differences. Explain each stage in a line."}},{"itemId":"efb45b36-741d-558b-895a-ac1e0c8da136","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:8","parentItemId":"a46fb73b-a0ea-527f-8974-fb4bb16711f4","revision":1,"payload":{"body":"Hygiene factors (extrinsic: salary, policy, supervision) prevent dissatisfaction only. Motivators (intrinsic: achievement, recognition, responsibility, growth) create satisfaction. Opposite of satisfaction is no satisfaction. Implication: enrich jobs to motivate."}},{"itemId":"0379796a-5c19-5543-923b-453d77eeff0c","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:9","parentItemId":"cc2c6fa5-15c2-5c75-b5b3-06e96b7c032a","revision":1,"payload":{"body":"Define trust and why it matters. Give the 5 Cs in one line each. Define communication. Pick three barriers (e.g. filtering, information overload, defensiveness), define each with a workplace example. End with remedies: feedback, simple language, active listening."}}]$expected_content$::jsonb,
  'principles-management: model_answer published payload and identity match source');
