  where kind = 'note') = $expected_content$[{"itemId":"2a804fab-aee0-517a-89aa-ecf04894aabe","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"The Nature and Scope of Accounting","body":"The history of accounting; what accounting, financial accounting and bookkeeping mean and how they differ; the objectives of financial accounting and the accounting cycle; the elements of financial statements; the users and the qualitative characteristics of accounting information; types of organisation; the branches of accounting; manual and electronic recording.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The history of accounting; what accounting, financial accounting and bookkeeping mean and how they differ; the objectives of financial accounting and the accounting cycle; the elements of financial statements; the users and the qualitative characteristics of accounting information; types of organisation; the branches of accounting; manual and electronic recording."}],"lessons":[{"number":"1.1","title":"History, definitions and bookkeeping vs accounting","mustKnow":[{"type":"paragraph","text":[{"text":"History in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Babylon:","bold":true},{"text":" money served as a medium of exchange; businessmen recorded sales and lending on "},{"text":"clay tablets","bold":true},{"text":". As trade grew, servants found it hard to give a report of "},{"text":"stewardship","bold":true},{"text":", so records became necessary."}]},{"text":[{"text":"Egypt:","bold":true},{"text":" used "},{"text":"papyrus","bold":true},{"text":" to show tax collection."}]},{"text":[{"text":"Greece:","bold":true},{"text":" accounts were "},{"text":"engraved on stones","bold":true},{"text":" and displayed in public."}]},{"text":[{"text":"Luca Pacioli","bold":true},{"text":" (Italian mathematician), the "},{"text":"father of accounting","bold":true},{"text":": his 1494 book, known as the "},{"text":"Treatise of Book Keeping","italic":true},{"text":", was the first documented work describing double entry."}]},{"text":[{"text":"Industrial Revolution (Great Britain):","bold":true},{"text":" professional bodies such as the "},{"text":"Institute of Chartered Accountants of England and Wales (ICAEW)","bold":true},{"text":" developed accounting theory, methods and practice. The basic rule of double entry "},{"text":"remained unchanged","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" the "},{"text":"Institute of Chartered Accountants of Nigeria (ICAN)","bold":true},{"text":" was set up by "},{"text":"Act of Parliament No. 15 of 1965","bold":true},{"text":"; it sets the code of ethics and regulates the profession. After the "},{"text":"indigenisation decrees of 1975 and 1979","bold":true},{"text":", ICAN members ran most enterprises, so the "},{"text":"Nigerian Accounting Standards Board (NASB)","bold":true},{"text":" was set up in "},{"text":"1982","bold":true},{"text":" to standardise practice. It is now the "},{"text":"Financial Reporting Council of Nigeria (FRCN)","bold":true},{"text":"."}]},{"text":[{"text":"Today:","bold":true},{"text":" information technology has improved the speed and quality of accounting, still using double entry."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting:","bold":true},{"text":" identifying, collecting, "},{"text":"recording","bold":true},{"text":", classifying, analysing, summarising, "},{"text":"interpreting","bold":true},{"text":" and "},{"text":"communicating","bold":true},{"text":" financial transactions to users for decisions. Three aspects: "},{"text":"recording, reporting and forecasting","bold":true},{"text":". Every definition must include "},{"text":"identifying and recording the transactions","bold":true},{"text":" of a business."}]},{"text":[{"text":"Financial accounting:","bold":true},{"text":" the process of "},{"text":"collecting, recording, analysing and summarising","bold":true},{"text":" financial transactions of a business and "},{"text":"interpreting","bold":true},{"text":" the information for the various users of financial statements. Transactions are recorded in the "},{"text":"books of original entry","bold":true},{"text":", analysed and "},{"text":"posted to the ledgers","bold":true},{"text":", then summarised in the "},{"text":"financial statements","bold":true},{"text":", in line with accounting concepts, standards and the law."}]},{"text":[{"text":"Bookkeeping:","bold":true},{"text":" the aspect of accounting that covers the "},{"text":"collection and accurate recording","bold":true},{"text":" of financial transactions. It is a "},{"text":"recording","bold":true},{"text":" activity."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Bookkeeping"}],[{"text":"Accounting"}]],"rows":[[[{"text":"Scope"}],[{"text":"Narrow; one part of accounting"}],[{"text":"Wider; includes bookkeeping"}]],[[{"text":"Main task"}],[{"text":"Collecting and recording"}],[{"text":"Analysing, summarising, interpreting, preparing financial statements"}]],[[{"text":"Stage"}],[{"text":"Comes first"}],[{"text":"Starts where bookkeeping ends"}]],[[{"text":"Judgement"}],[{"text":"Routine, little judgement"}],[{"text":"Needs judgement (e.g. when to recognise a transaction)"}]],[[{"text":"End product"}],[{"text":"Books of prime entry, ledgers, trial balance"}],[{"text":"Financial statements and their interpretation"}]],[[{"text":"Done by"}],[{"text":"Bookkeeper (clerical)"}],[{"text":"Accountant (professional)"}]]]},{"type":"paragraph","text":[{"text":"Similarities:","bold":true},{"text":" both deal with "},{"text":"financial transactions measured in money","bold":true},{"text":"; both follow "},{"text":"double entry","bold":true},{"text":" and the same accounting concepts; both rely on the "},{"text":"same source documents and records","bold":true},{"text":"; both aim at "},{"text":"accurate","bold":true},{"text":" financial information; both serve the "},{"text":"same business entity","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Bookkeeping is a ____ activity\" = "},{"text":"recording","bold":true},{"text":". Interpreting, reporting and analysing belong to accounting."}]},{"text":[{"text":"Trap:","bold":true},{"text":" accounting serves "},{"text":"many users","bold":true},{"text":", not \"management only\", and deals mainly with "},{"text":"quantitative","bold":true},{"text":" (money) data, not only qualitative data."}]},{"text":[{"text":"Financial accounting "},{"text":"does record","bold":true},{"text":" transactions, is "},{"text":"historical","bold":true},{"text":" (past events), "},{"text":"reports on a business entity","bold":true},{"text":" and treats the business as "},{"text":"separate","bold":true},{"text":" from its owner. \"It does not record financial transactions\" is false."}]},{"text":[{"text":"Leonardo da Vinci and Adam Smith (an economist) are "},{"text":"not","bold":true},{"text":" the father of accounting."}]}]}]},{"number":"1.2","title":"Objectives, the accounting cycle and the elements","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Two primary objectives of a business:","bold":true},{"text":" to "},{"text":"earn a profit","bold":true},{"text":" and to "},{"text":"remain solvent","bold":true},{"text":" (able to pay debts as they fall due)."}]},{"text":[{"text":"Main objective of financial statements:","bold":true},{"text":" to provide information about the "},{"text":"financial position","bold":true},{"text":", performance and changes in position of an enterprise that is "},{"text":"useful to a wide range of users in making economic decisions","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Objectives of financial accounting:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Keep a "},{"text":"systematic record","bold":true},{"text":" of all transactions."}]},{"text":[{"text":"Find the "},{"text":"profit or loss","bold":true},{"text":" for a period (income statement)."}]},{"text":[{"text":"Show the "},{"text":"financial position","bold":true},{"text":" at a date (balance sheet)."}]},{"text":[{"text":"Provide "},{"text":"information to users","bold":true},{"text":" for economic decisions."}]},{"text":[{"text":"Show "},{"text":"stewardship","bold":true},{"text":": how well managers have used the owners' resources."}]},{"text":[{"text":"Protect and "},{"text":"control","bold":true},{"text":" the business's assets."}]},{"text":[{"text":"Meet "},{"text":"legal","bold":true},{"text":" and tax requirements."}]}]},{"type":"paragraph","text":[{"text":"The financial accounting cycle (in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Transaction occurs; "},{"text":"source document","bold":true},{"text":" raised (invoice, receipt, cheque counterfoil)."}]},{"text":[{"text":"Record in the "},{"text":"books of original (prime) entry","bold":true},{"text":" (day books, cash book, journal)."}]},{"text":[{"text":"Post","bold":true},{"text":" to the "},{"text":"ledger","bold":true},{"text":" accounts."}]},{"text":[{"text":"Balance","bold":true},{"text":" the accounts and extract a "},{"text":"trial balance","bold":true},{"text":"."}]},{"text":[{"text":"Make "},{"text":"end-of-year adjustments","bold":true},{"text":" (accruals, prepayments, depreciation, bad debts)."}]},{"text":[{"text":"Prepare the "},{"text":"financial statements","bold":true},{"text":"."}]},{"text":[{"text":"Close","bold":true},{"text":" the income and expense accounts; the cycle starts again for the next period."}]}]},{"type":"paragraph","text":[{"text":"Five elements of financial statements:","bold":true}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Meaning"}],[{"text":"Where shown"}]],"rows":[[[{"text":"Assets"}],[{"text":"Resources the business owns"}],[{"text":"Balance sheet"}]],[[{"text":"Liabilities"}],[{"text":"Amounts owed to outsiders"}],[{"text":"Balance sheet"}]],[[{"text":"Capital (owner's equity)"}],[{"text":"Owner's interest in the business"}],[{"text":"Balance sheet"}]],[[{"text":"Revenue (income)"}],[{"text":"Earnings from sales and services"}],[{"text":"Income statement"}]],[[{"text":"Expenses"}],[{"text":"Costs used up in earning revenue"}],[{"text":"Income statement"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Balance sheet accounts","bold":true},{"text":" = asset, "},{"text":"liability","bold":true},{"text":" and capital (stockholders' or owner's equity) accounts."}]},{"text":[{"text":"Main financial statements:","bold":true},{"text":" (1) "},{"text":"income statement","bold":true},{"text":" (profit or loss account), (2) "},{"text":"statement of owner's equity","bold":true},{"text":" (changes in equity), (3) "},{"text":"balance sheet","bold":true},{"text":" (statement of financial position), (4) "},{"text":"statement of cash flows","bold":true},{"text":". They let users judge "},{"text":"profitability","bold":true},{"text":" and "},{"text":"solvency","bold":true},{"text":". There is "},{"text":"no","bold":true},{"text":" \"expenditure statement\"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"One transaction through the cycle.","bold":true},{"text":" Tolu sells goods on credit to Bayo for ₦80,000."}]},{"type":"table","header":[[{"text":"Step"}],[{"text":"What happens"}]],"rows":[[[{"text":"Source document"}],[{"text":"Tolu issues sales invoice No. 041 for ₦80,000"}]],[[{"text":"Book of prime entry"}],[{"text":"Entered in the sales day book"}]],[[{"text":"Ledger"}],[{"text":"Debit Bayo's account ₦80,000; credit sales account ₦80,000"}]],[[{"text":"Trial balance"}],[{"text":"Bayo ₦80,000 in the debit column; sales ₦80,000 in the credit column"}]],[[{"text":"Financial statements"}],[{"text":"Sales in the income statement; Bayo as a receivable (debtor) in the balance sheet"}]]]},{"type":"paragraph","text":[{"text":"Elements in the statements.","bold":true},{"text":" Ada Stores, year to 31 December 2025:"}]},{"type":"table","header":[[{"text":"Income statement"}],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Revenue (sales)"}],[],[{"text":"850,000"}]],[[{"text":"Less expenses: rent"}],[{"text":"120,000"}],[]],[[{"text":"wages"}],[{"text":"230,000"}],[{"text":"350,000"}]],[[{"text":"Net profit"}],[],[{"text":"500,000"}]]]},{"type":"table","header":[[{"text":"Balance sheet as at 31 December 2025"}],[{"text":"₦"}]],"rows":[[[{"text":"Equipment"}],[{"text":"600,000"}]],[[{"text":"Inventory"}],[{"text":"150,000"}]],[[{"text":"Cash"}],[{"text":"400,000"}]],[[{"text":"Total assets","bold":true}],[{"text":"1,150,000","bold":true}]],[[{"text":"Capital at start"}],[{"text":"500,000"}]],[[{"text":"Add net profit"}],[{"text":"500,000"}]],[[{"text":"Capital at end"}],[{"text":"1,000,000"}]],[[{"text":"Trade payables (creditors)"}],[{"text":"150,000"}]],[[{"text":"Capital and liabilities","bold":true}],[{"text":"1,150,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit (revenue less expenses) increases capital."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"earn a profit and "},{"text":"create wealth","bold":true},{"text":"\" or \"earn a profit and "},{"text":"prepare financial statements","bold":true},{"text":"\" are wrong pairs. Preparing statements is an accounting task that "},{"text":"measures","italic":true},{"text":" the objectives."}]}]}]},{"number":"1.3","title":"Users and qualitative characteristics","mustKnow":[{"type":"paragraph","text":[{"text":"Nine users of accounting information:","bold":true}]},{"type":"table","header":[[{"text":"User"}],[{"text":"What they want to know"}]],"rows":[[[{"text":"1. Managers"}],[{"text":"Current and expected position, to manage efficiently and make effective decisions"}]],[[{"text":"2. Shareholders (owners)"}],[{"text":"How well management performs; profitability; how much profit can be withdrawn"}]],[[{"text":"3. Trade contacts"}],[{"text":"Suppliers: ability to pay debts. Customers: a secure source of supply, no danger of closing down"}]],[[{"text":"4. Providers of finance (banks, lenders)"}],[{"text":"Ability to pay interest and repay loans and overdrafts"}]],[[{"text":"5. Taxation authorities"}],[{"text":"Profit, to assess tax payable"}]],[[{"text":"6. Employees"}],[{"text":"Job security, wages and salaries, future careers"}]],[[{"text":"7. Financial analysts and advisers"}],[{"text":"Information for clients: stockbrokers advise investors, credit agencies advise suppliers, journalists inform readers"}]],[[{"text":"8. Government and agencies"}],[{"text":"Allocation of resources; national statistics"}]],[[{"text":"9. The public"}],[{"text":"Employment, use of local suppliers, effect on the environment (pollution)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal user:","bold":true},{"text":" management (three levels: "},{"text":"strategic","bold":true},{"text":" = board, long-term decisions; "},{"text":"tactical","bold":true},{"text":" = middle managers, short to medium-term targets; "},{"text":"operational","bold":true},{"text":" = day-to-day, often non-money units such as hours worked). "},{"text":"External users:","bold":true},{"text":" everyone else."}]}]},{"type":"paragraph","text":[{"text":"Qualitative characteristics","bold":true},{"text":" (qualities information must have before users can rely on it):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relevance:","bold":true},{"text":" enough facts to meet users' needs and the decision in hand."}]},{"text":[{"text":"Reliability:","bold":true},{"text":" source verifiable; one source of evidence corroborates another."}]},{"text":[{"text":"Comparability:","bold":true},{"text":" no change in the basis of preparation from period to period, so results can be compared."}]},{"text":[{"text":"Timeliness:","bold":true},{"text":" available early enough to use; late information is useless."}]},{"text":[{"text":"Objectivity:","bold":true},{"text":" no bias, window dressing or subjective judgement; traceable to documents; complies with regulations."}]},{"text":[{"text":"Comprehensiveness:","bold":true},{"text":" just enough detail, neither too little nor too much."}]},{"text":[{"text":"Title:","bold":true},{"text":" clearly named so the user knows the report, the entity and the period it covers."}]},{"text":[{"text":"Volume:","bold":true},{"text":" a manageable quantity of information for the user."}]},{"text":[{"text":"Channel of communication:","bold":true},{"text":" sent through a suitable medium to the person who will act on it."}]}]},{"type":"paragraph","text":[{"text":"The international framework also lists "},{"text":"understandability","bold":true},{"text":" (easily understood by users) and "},{"text":"completeness","bold":true},{"text":"; reports should also be "},{"text":"fair","bold":true},{"text":" (not favour any user group)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \""},{"text":"Monetary","bold":true},{"text":"\" is "},{"text":"not","bold":true},{"text":" a quality of financial reports. It belongs to the money measurement concept (Topic 4), which decides what is recorded. Understandable, relevant, reliable, fair, comparable and timely "},{"text":"are","bold":true},{"text":" qualities."}]},{"text":[{"text":"Match the user to the need: interest and loan repayment = "},{"text":"lender","bold":true},{"text":"; ability to pay for goods supplied = "},{"text":"supplier","bold":true},{"text":"; tax = "},{"text":"tax authorities","bold":true},{"text":"; pollution = "},{"text":"public","bold":true},{"text":"; dividends and profitability = "},{"text":"shareholders","bold":true},{"text":"."}]}]}]},{"number":"1.4","title":"Types of organisation and branches of accounting","mustKnow":[{"type":"paragraph","text":[{"text":"Two types of organisation:","bold":true}]},{"type":"paragraph","text":[{"text":"A. Profit-making","bold":true},{"text":" (primary aim: profit on goods and services):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sole proprietorship:","bold":true},{"text":" one-man business; the owner is "},{"text":"fully liable","bold":true},{"text":" for debts and takes "},{"text":"all the profit","bold":true},{"text":"."}]},{"text":[{"text":"Partnership:","bold":true},{"text":" "},{"text":"two or more","bold":true},{"text":" persons, "},{"text":"jointly and fully liable","bold":true},{"text":"; profit shared in "},{"text":"agreed ratios","bold":true},{"text":"."}]},{"text":[{"text":"Company:","bold":true},{"text":" a "},{"text":"legal entity","bold":true},{"text":", an "},{"text":"artificial person","bold":true},{"text":" distinct from its owners. The "},{"text":"company","bold":true},{"text":" is liable for its debts; owners act on its behalf and all transactions are in the company's name. Private (Ltd) or public (Plc)."}]}]},{"type":"paragraph","text":[{"text":"B. Non-profit-making","bold":true},{"text":" (services at affordable cost, not for profit):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Government ministries"}]},{"text":[{"text":"Non-governmental organisations (NGOs)"}]},{"text":[{"text":"Clubs and societies"}]},{"text":[{"text":"Charity organisations"}]}]},{"type":"paragraph","text":[{"text":"Branches of accounting:","bold":true}]},{"type":"table","header":[[{"text":"Branch"}],[{"text":"What it does"}]],"rows":[[[{"text":"Financial accounting"}],[{"text":"Records transactions and prepares financial statements, mainly for "},{"text":"external","bold":true},{"text":" users, by set rules, at set intervals"}]],[[{"text":"Cost accounting"}],[{"text":"Finds and controls the cost of products, jobs and services"}]],[[{"text":"Management accounting"}],[{"text":"Information for "},{"text":"managers","bold":true},{"text":" to plan, evaluate and control; format chosen by management"}]],[[{"text":"Financial management"}],[{"text":"Raising funds and deciding how to invest and use them"}]],[[{"text":"Taxation"}],[{"text":"Computing tax liabilities and tax planning"}]],[[{"text":"Auditing"}],[{"text":"Independent examination to confirm the statements give a "},{"text":"true and fair","bold":true},{"text":" view"}]]]},{"type":"paragraph","text":[{"text":"Other branches you may meet: "},{"text":"public sector (government) accounting","bold":true},{"text":" and "},{"text":"forensic accounting","bold":true},{"text":" (investigating fraud)."}]}],"explainMore":[{"type":"table","header":[[{"text":"Point"}],[{"text":"Financial accounting"}],[{"text":"Management accounting"}]],"rows":[[[{"text":"Users"}],[{"text":"Mainly external"}],[{"text":"Internal (managers)"}]],[[{"text":"Frequency"}],[{"text":"Usually annual"}],[{"text":"Usually monthly or more often"}]],[[{"text":"Rules"}],[{"text":"Must follow standards and law"}],[{"text":"No set format"}]],[[{"text":"Detail"}],[{"text":"Summarised"}],[{"text":"Detailed (e.g. manufacturing costs)"}]],[[{"text":"Audit"}],[{"text":"Audited externally"}],[{"text":"Not externally audited"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" financial statements are "},{"text":"not","bold":true},{"text":" \"more accurate\" than management accounts; that is not the difference."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a sole proprietor is "},{"text":"fully","bold":true},{"text":" liable for business debts; in a company the "},{"text":"company itself","bold":true},{"text":" is liable."}]}]}]},{"number":"1.5","title":"Manual and electronic recording","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Manual recording:","bold":true},{"text":" transactions are written by hand in "},{"text":"bound books, loose-leaf binders or cards","bold":true},{"text":" (day books, cash book, journal, ledgers)."}]},{"text":[{"text":"Electronic (computerised) recording:","bold":true},{"text":" accounting software keeps the books "},{"text":"in computer memory","bold":true},{"text":", not printed form. It performs the "},{"text":"same bookkeeping tasks","bold":true},{"text":"; the "},{"text":"double entry system must still be kept","bold":true},{"text":" and controls are still needed."}]}]},{"type":"paragraph","text":[{"text":"Benefits of computerised accounting:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Speed","bold":true},{"text":" of input and processing."}]},{"text":[{"text":"Speed and "},{"text":"flexibility","bold":true},{"text":" in producing information."}]},{"text":[{"text":"Handles "},{"text":"large numbers","bold":true},{"text":" of accounts and transactions."}]},{"text":[{"text":"Improved accuracy.","bold":true}]},{"text":[{"text":"Automatic update","bold":true},{"text":" of all related accounts from a single entry."}]},{"text":[{"text":"Less storage space.","bold":true}]},{"text":[{"text":"Input checks","bold":true},{"text":" on data: dates (31 November rejected), limits, ranges."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Biggest drawback:","bold":true},{"text":" the user "},{"text":"cannot physically see","bold":true},{"text":" what is happening, so errors and omissions are not readily spotted. A \"self-balancing\" system can make users assume everything is right."}]},{"text":[{"text":"Configurations:","bold":true},{"text":" (1) "},{"text":"mainframe","bold":true},{"text":" with minicomputer and PCs; (2) "},{"text":"networked","bold":true},{"text":" computers, files held centrally; (3) "},{"text":"stand-alone","bold":true},{"text":" computers. All need security and "},{"text":"segregation of duties","bold":true},{"text":"."}]},{"text":[{"text":"Coding:","bold":true},{"text":" each account gets a unique code. Good codes are "},{"text":"unique, useful, compact, meaningful, self-checking, expandable, of standard size","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Manual"}],[{"text":"Computerised"}]],"rows":[[[{"text":"Speed"}],[{"text":"Slow"}],[{"text":"Fast"}]],[[{"text":"Arithmetic errors"}],[{"text":"Common"}],[{"text":"Rare"}]],[[{"text":"Posting"}],[{"text":"Each entry posted by hand"}],[{"text":"One entry updates all related records"}]],[[{"text":"Storage"}],[{"text":"Bulky books"}],[{"text":"Little space"}]],[[{"text":"Visibility"}],[{"text":"Entries can be seen and traced"}],[{"text":"Hard to see what happened"}]],[[{"text":"Cost"}],[{"text":"Cheap to start"}],[{"text":"Hardware, software, training"}]],[[{"text":"Risks"}],[{"text":"Loss, fire, damage"}],[{"text":"Viruses, power failure, unauthorised access"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Account coding example.","bold":true},{"text":" Main codes: assets 1, liabilities 2, capital 3, expenses 4, revenues 5. Current assets = 13. A six-digit expense code: digit 1 = function (1 production), digits 2-3 = cost centre (10 machining), digits 4-6 = expense (202 unskilled wages). So "},{"text":"110202","bold":true},{"text":" means unskilled-labour wages in the machining centre of production."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The trial balance must still agree, and adjustments still go "},{"text":"through the journal","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" computers do "},{"text":"not","bold":true},{"text":" remove the need for double entry or for checking. In exam questions, assume a "},{"text":"manual","bold":true},{"text":" system unless told otherwise."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"History: clay tablets, papyrus, stones; Pacioli 1494; ICAN 1965; NASB 1982, now FRCN."}]},{"text":[{"text":"Bookkeeping = collecting and recording; accounting is wider: analyses, summarises, interprets, reports."}]},{"text":[{"text":"Business aims: earn a profit and remain solvent. Financial statements give useful information for economic decisions."}]},{"text":[{"text":"Cycle: source document, prime entry, ledger, trial balance, adjustments, financial statements, closing."}]},{"text":[{"text":"Five elements: assets, liabilities, capital, revenue, expenses. Balance sheet accounts = assets, liabilities, equity. No \"expenditure statement\"."}]},{"text":[{"text":"Nine users, from managers to the public; management is the internal user."}]},{"text":[{"text":"Nine qualities: relevance, reliability, comparability, timeliness, objectivity, comprehensiveness, title, volume, channel; plus understandability and fairness. \"Monetary\" is not one."}]},{"text":[{"text":"Profit-making: sole proprietor, partnership, company. Non-profit: ministries, NGOs, clubs, charities."}]},{"text":[{"text":"Branches: financial, cost, management accounting, financial management, taxation, auditing."}]},{"text":[{"text":"Computers are faster and more accurate but still use double entry; errors are harder to see."}]}]}],"theory":{"itemId":"3b826be6-ed6b-554a-ad2e-32f911efb6e0","question":[{"type":"paragraph","text":[{"text":"Distinguish between bookkeeping and accounting, and state three similarities between them."}]}]},"practice":[{"topic":"Nature, scope and objectives of accounting","named":true},{"topic":"Users and qualitative characteristics","named":true},{"topic":"Branches of accounting","named":true}]}},{"itemId":"a8a9f8be-971c-547d-8aad-6f5427b9820d","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Double entry and the accounting equation","body":"The five elements; A = C + L and its expanded forms; the dual-aspect rule; the double entry matrix; posting to T accounts; balancing and closing off accounts; capital vs revenue receipts and expenditure.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The five elements; A = C + L and its expanded forms; the dual-aspect rule; the double entry matrix; posting to T accounts; balancing and closing off accounts; capital vs revenue receipts and expenditure."}],"lessons":[{"number":"2.1","title":"The five elements and the accounting equation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Assets:","bold":true},{"text":" the resources a business owns. "},{"text":"Non-current assets","bold":true},{"text":" are kept for use, not for sale, for more than one accounting period (motor vehicles, plant and machinery, land and building, fixtures and fittings). "},{"text":"Current assets","bold":true},{"text":" are cash or items meant to turn into cash within the period (inventory, receivables (debtors), cash in hand, cash at bank, prepayments). Non-current + current = total assets."}]},{"text":[{"text":"Capital (owner's equity):","bold":true},{"text":" finance provided by the owners, not meant to be repaid in the ordinary course of business. Because the business is separate from its owner (entity concept), capital is the "},{"text":"indebtedness of the business to the proprietor","bold":true},{"text":"."}]},{"text":[{"text":"Liabilities:","bold":true},{"text":" the part of the assets provided by outsiders (loans, credit purchases, bank overdraft). "},{"text":"Non-current:","bold":true},{"text":" not due within 12 months (long-term bank loan, debentures). "},{"text":"Current:","bold":true},{"text":" due within the year (trade payables (creditors), accrued expenses, income received in advance, bank overdraft)."}]},{"text":[{"text":"Revenue:","bold":true},{"text":" income earned (sales, commission received, rent received, interest received, discount received)."}]},{"text":[{"text":"Expenses:","bold":true},{"text":" costs used up in earning revenue (purchases of goods, wages, rent, electricity)."}]}]},{"type":"paragraph","text":[{"text":"The equation and its forms","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"At the start, if only the owner supplies assets: "},{"text":"Assets = Capital","bold":true},{"text":"."}]},{"text":[{"text":"Basic form: "},{"text":"Assets = Capital + Liabilities","bold":true},{"text":" (A = C + L), also written Assets = Liabilities + Owner's Equity."}]},{"text":[{"text":"Assets − Liabilities = Capital","bold":true},{"text":", i.e. "},{"text":"Net assets = Owner's equity","bold":true},{"text":"."}]},{"text":[{"text":"Capital = original contribution + profit, and profit = revenue − expenses, so "},{"text":"Assets = Original contribution + Revenue − Expenses + Liabilities","bold":true},{"text":"."}]},{"text":[{"text":"Final form: "},{"text":"Assets + Expenses = Capital + Revenue + Liabilities","bold":true},{"text":" (A + E = C + R + L)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Closing (current) capital = opening capital + further owner investment + revenue − expenses − drawings.","bold":true}]},{"text":[{"text":"So "},{"text":"Assets = Liabilities + opening capital + further investment + (revenue − expenses) − drawings.","bold":true}]},{"text":[{"text":"Raise capital:","bold":true},{"text":" revenue (profit) and new investment. "},{"text":"Reduce capital:","bold":true},{"text":" expenses (losses) and drawings."}]},{"text":[{"text":"The equation holds "},{"text":"at all times","bold":true},{"text":", for every organisation, whatever its size or the number of transactions."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Finding the missing figure","bold":true},{"text":" (use A = C + L):"}]},{"type":"table","header":[[{"text":"Assets ₦"}],[{"text":"Liabilities ₦"}],[{"text":"Capital ₦"}]],"rows":[[[{"text":"55,000"}],[{"text":"16,900"}],[{"text":"38,100","bold":true}]],[[{"text":"41,600","bold":true}],[{"text":"17,200"}],[{"text":"24,400"}]],[[{"text":"36,100"}],[{"text":"7,600","bold":true}],[{"text":"28,500"}]]]},{"type":"paragraph","text":[{"text":"Capital from a list:","bold":true},{"text":" premises ₦20,000, closing stock ₦8,000, cash ₦100, creditors ₦3,000, loan ₦4,000. Assets = ₦28,100; liabilities = ₦7,000; capital = ₦28,100 − ₦7,000 = "},{"text":"₦21,100","bold":true},{"text":". Trap: deduct "},{"text":"both","bold":true},{"text":" the creditors and the loan."}]},{"type":"paragraph","text":[{"text":"Closing capital:","bold":true},{"text":" started with ₦50,000, borrowed ₦5,000 from a relative, profit ₦10,000, drawings ₦9,000. Closing capital = 50,000 + 10,000 − 9,000 = "},{"text":"₦51,000","bold":true},{"text":". Trap: the loan is a "},{"text":"liability","bold":true},{"text":", not capital, so ₦56,000 is wrong; forgetting drawings gives ₦60,000."}]},{"type":"paragraph","text":[{"text":"How transactions move the equation","bold":true}]},{"type":"table","header":[[{"text":"Transaction"}],[{"text":"Effect"}]],"rows":[[[{"text":"Owner brings in cash"}],[{"text":"Asset up, capital up"}]],[[{"text":"Loan received"}],[{"text":"Asset up, liability up"}]],[[{"text":"Goods bought on credit"}],[{"text":"Asset/expense up, liability up"}]],[[{"text":"Goods or assets bought for cash"}],[{"text":"One asset up, another asset down (no change in total)"}]],[[{"text":"Cash paid to a creditor"}],[{"text":"Asset down, liability down"}]],[[{"text":"Goods sold on credit"}],[{"text":"Asset (receivable) up, revenue (so capital) up"}]],[[{"text":"Owner takes cash (drawings)"}],[{"text":"Asset down, capital down"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"liability","bold":true},{"text":" is owed to outsiders; it never increases owner's equity."}]},{"text":[{"text":"Dividends","bold":true},{"text":" in a company are like drawings: a distribution of profit to shareholders. They reduce retained earnings and so shareholders' equity, but they are "},{"text":"not an expense","bold":true},{"text":", so they do not reduce net profit."}]}]}]},{"number":"2.2","title":"The dual aspect and the debit and credit rules","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Duality concept:","bold":true},{"text":" every transaction has a dual effect, so it is recorded twice: "},{"text":"for every debit entry there must be a corresponding credit entry of equal value, and vice versa","bold":true},{"text":" (a receiver and a giver). It applies to "},{"text":"every transaction","bold":true},{"text":", which is why the equation always balances."}]},{"text":[{"text":"Every transaction affects "},{"text":"two or more","bold":true},{"text":" accounts. Total debits always equal total credits."}]},{"text":[{"text":"Debit (Dr)","bold":true},{"text":" and "},{"text":"credit (Cr)","bold":true},{"text":" describe the direction of change in an account. In a ledger (T) account the "},{"text":"left side is debit","bold":true},{"text":" and the "},{"text":"right side is credit","bold":true},{"text":"."}]},{"text":[{"text":"Rule:","bold":true},{"text":" items on the "},{"text":"left","bold":true},{"text":" of A + E = C + R + L (assets, expenses) are "},{"text":"debit in nature","bold":true},{"text":"; items on the "},{"text":"right","bold":true},{"text":" (capital, revenue, liabilities) are "},{"text":"credit in nature","bold":true},{"text":". To "},{"text":"increase","bold":true},{"text":" an account, enter it on its nature side; to "},{"text":"decrease","bold":true},{"text":" it, do the opposite."}]}]},{"type":"paragraph","text":[{"text":"The double entry matrix","bold":true}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Nature (normal balance)"}],[{"text":"Increase"}],[{"text":"Decrease"}]],"rows":[[[{"text":"Assets"}],[{"text":"Debit"}],[{"text":"Debit"}],[{"text":"Credit"}]],[[{"text":"Expenses"}],[{"text":"Debit"}],[{"text":"Debit"}],[{"text":"Credit"}]],[[{"text":"Capital"}],[{"text":"Credit"}],[{"text":"Credit"}],[{"text":"Debit"}]],[[{"text":"Revenue"}],[{"text":"Credit"}],[{"text":"Credit"}],[{"text":"Debit"}]],[[{"text":"Liabilities"}],[{"text":"Credit"}],[{"text":"Credit"}],[{"text":"Debit"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Drawings","bold":true},{"text":" reduce capital, so the drawings account is "},{"text":"debited","bold":true},{"text":"."}]},{"text":[{"text":"Debit does "},{"text":"not","bold":true},{"text":" mean reduce and credit does "},{"text":"not","bold":true},{"text":" mean increase. The nature of the account and the transaction decide."}]}]},{"type":"paragraph","text":[{"text":"4 steps to record a transaction","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Make sure a transaction has taken place: at least two parties, measurable in money."}]},{"text":[{"text":"Identify the two (or more) accounts involved."}]},{"text":[{"text":"Classify each account: asset, expense, capital, revenue or liability."}]},{"text":[{"text":"Decide whether each account increases or decreases, then apply the matrix."}]}]}],"explainMore":[{"type":"table","header":[[{"text":"Transaction"}],[{"text":"Debit"}],[{"text":"Credit"}]],"rows":[[[{"text":"Motimo puts ₦250,000 cash into his business"}],[{"text":"Cash"}],[{"text":"Capital"}]],[[{"text":"Bought motor car for ₦7,500,000 cash"}],[{"text":"Motor vehicle"}],[{"text":"Cash"}]],[[{"text":"Sold goods ₦500,000 on credit to Sola & Co"}],[{"text":"Sola & Co (receivable)"}],[{"text":"Sales"}]],[[{"text":"Bought motor vehicle ₦1.5m on credit from Biafra Ltd"}],[{"text":"Motor vehicle"}],[{"text":"Biafra Ltd (payable)"}]],[[{"text":"Paid wages ₦75,000 by cash"}],[{"text":"Wages"}],[{"text":"Cash"}]],[[{"text":"Wrote a cheque to pay a supplier"}],[{"text":"Supplier (payable)"}],[{"text":"Bank (cash at bank, so the cash account is credited)"}]],[[{"text":"Owner took ₦75,000 from the bank for his son's hospital bill"}],[{"text":"Drawings"}],[{"text":"Bank"}]]]},{"type":"paragraph","text":[{"text":"Account types exams test","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interest receivable, fees receivable, rent receivable: "},{"text":"assets","bold":true},{"text":" (owed "},{"text":"to","bold":true},{"text":" the business). Debiting rent receivable "},{"text":"increases","bold":true},{"text":" it."}]},{"text":[{"text":"Accrued expenses (owed at the year end): "},{"text":"liability","bold":true},{"text":", increased by a "},{"text":"credit","bold":true},{"text":"."}]},{"text":[{"text":"Unearned (deferred) revenue, income received in advance: "},{"text":"liability","bold":true},{"text":", decreased by a "},{"text":"debit","bold":true},{"text":" when the income is earned."}]},{"text":[{"text":"Electricity, insurance, interest, repairs expense: increased by a "},{"text":"debit","bold":true},{"text":". Service revenue: increased by a "},{"text":"credit","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Compound entry (three accounts):","bold":true},{"text":" you owe Kola ₦50,000 and pay by cheque, taking a 10% cash discount. Dr Kola ₦50,000; Cr Bank ₦45,000; Cr Discount received ₦5,000. Debits (₦50,000) = credits (₦45,000 + ₦5,000)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" trade discount is never recorded. Goods listed at ₦45,700 less 8% trade discount are recorded at ₦42,044. A cash discount offered is not recorded until it is actually taken on payment."}]}]}]},{"number":"2.3","title":"Recording transactions in T accounts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"ledger account","bold":true},{"text":" records all transactions on one item. Each has a debit side (left) and a credit side (right), with date, details (the name of the "},{"text":"other","bold":true},{"text":" account) and amount."}]},{"text":[{"text":"Each transaction is posted "},{"text":"twice","bold":true},{"text":": once on the debit side of one account and once on the credit side of another."}]},{"text":[{"text":"Cash sales and credit sales both go to "},{"text":"sales","bold":true},{"text":"; goods bought for resale go to "},{"text":"purchases","bold":true},{"text":", never to the asset account."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Ada starts trading in March:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Starts business with ₦800,000 in the bank."}]},{"text":[{"text":"Buys furniture ₦150,000 by cheque."}]},{"text":[{"text":"Buys goods ₦200,000 on credit from Kola."}]},{"text":[{"text":"Sells goods for cash ₦120,000."}]},{"text":[{"text":"Sells goods ₦90,000 on credit to Bisi."}]},{"text":[{"text":"Pays rent ₦40,000 by cheque."}]},{"text":[{"text":"Pays Kola ₦150,000 by cheque."}]},{"text":[{"text":"Takes ₦20,000 cash for personal use."}]}]},{"type":"table","header":[[{"text":"No."}],[{"text":"Debit"}],[{"text":"Credit"}],[{"text":"₦"}]],"rows":[[[{"text":"1"}],[{"text":"Bank"}],[{"text":"Capital"}],[{"text":"800,000"}]],[[{"text":"2"}],[{"text":"Furniture"}],[{"text":"Bank"}],[{"text":"150,000"}]],[[{"text":"3"}],[{"text":"Purchases"}],[{"text":"Kola"}],[{"text":"200,000"}]],[[{"text":"4"}],[{"text":"Cash"}],[{"text":"Sales"}],[{"text":"120,000"}]],[[{"text":"5"}],[{"text":"Bisi"}],[{"text":"Sales"}],[{"text":"90,000"}]],[[{"text":"6"}],[{"text":"Rent"}],[{"text":"Bank"}],[{"text":"40,000"}]],[[{"text":"7"}],[{"text":"Kola"}],[{"text":"Bank"}],[{"text":"150,000"}]],[[{"text":"8"}],[{"text":"Drawings"}],[{"text":"Cash"}],[{"text":"20,000"}]]]},{"type":"paragraph","text":[{"text":"Bank account","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Capital"}],[{"text":"800,000"}],[{"text":"Furniture"}],[{"text":"150,000"}]],[[],[],[{"text":"Rent"}],[{"text":"40,000"}]],[[],[],[{"text":"Kola"}],[{"text":"150,000"}]]]},{"type":"paragraph","text":[{"text":"Kola account","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Bank"}],[{"text":"150,000"}],[{"text":"Purchases"}],[{"text":"200,000"}]]]},{"type":"paragraph","text":[{"text":"Sales account","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[],[],[{"text":"Cash"}],[{"text":"120,000"}]],[[],[],[{"text":"Bisi"}],[{"text":"90,000"}]]]},{"type":"paragraph","text":[{"text":"Equation check","bold":true},{"text":" (A + E + drawings = C + R + L):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Left: bank 460,000 + furniture 150,000 + cash 100,000 + Bisi 90,000 + purchases 200,000 + rent 40,000 + drawings 20,000 = "},{"text":"₦1,060,000","bold":true},{"text":"."}]},{"text":[{"text":"Right: capital 800,000 + sales 210,000 + Kola 50,000 = "},{"text":"₦1,060,000","bold":true},{"text":"."}]}]}]},{"number":"2.4","title":"Balancing and closing off accounts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Closing off","bold":true},{"text":" summarises each account at the period end before a trial balance is extracted. The steps depend on the account type."}]},{"text":[{"text":"Statement of financial position (balance sheet) accounts","bold":true},{"text":" (assets, capital, liabilities) are perpetual: the closing balance becomes next period's opening balance."}]},{"text":[{"text":"Profit or loss accounts","bold":true},{"text":" (revenue, expenses) end with the year: their balances are "},{"text":"not","bold":true},{"text":" carried forward."}]}]},{"type":"paragraph","text":[{"text":"Steps for statement of financial position accounts","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Add up both sides."}]},{"text":[{"text":"Find the greater side."}]},{"text":[{"text":"Put the greater total on "},{"text":"both","bold":true},{"text":" sides."}]},{"text":[{"text":"Insert the balancing figure on the "},{"text":"lower","bold":true},{"text":" side as "},{"text":"\"balance carried down\" (bal c/d)","bold":true},{"text":": the closing balance."}]},{"text":[{"text":"Carry it to the "},{"text":"opposite","bold":true},{"text":" side below the totals as "},{"text":"\"balance brought down\" (bal b/d)","bold":true},{"text":": the opening balance of the next period."}]}]},{"type":"paragraph","text":[{"text":"Steps for revenue and expense accounts:","bold":true},{"text":" steps 1 to 3 as above; then insert the balancing figure on the lower side as "},{"text":"\"transfer to profit/loss account\"","bold":true},{"text":": the revenue earned or expense incurred for the year. (To extract a trial balance first, these accounts are balanced with c/d and b/d like the others.)"}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Bank account (balanced)","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Capital"}],[{"text":"800,000"}],[{"text":"Furniture"}],[{"text":"150,000"}]],[[],[],[{"text":"Rent"}],[{"text":"40,000"}]],[[],[],[{"text":"Kola"}],[{"text":"150,000"}]],[[],[],[{"text":"Balance c/d"}],[{"text":"460,000"}]],[[],[{"text":"800,000","bold":true}],[],[{"text":"800,000","bold":true}]],[[{"text":"Balance b/d"}],[{"text":"460,000"}],[],[]]]},{"type":"paragraph","text":[{"text":"A "},{"text":"debit","bold":true},{"text":" balance b/d on an asset is normal: the business has ₦460,000 in the bank."}]},{"type":"paragraph","text":[{"text":"Kola account (balanced)","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Bank"}],[{"text":"150,000"}],[{"text":"Purchases"}],[{"text":"200,000"}]],[[{"text":"Balance c/d"}],[{"text":"50,000"}],[],[]],[[],[{"text":"200,000","bold":true}],[],[{"text":"200,000","bold":true}]],[[],[],[{"text":"Balance b/d"}],[{"text":"50,000"}]]]},{"type":"paragraph","text":[{"text":"A "},{"text":"credit","bold":true},{"text":" balance b/d on a creditor means the business still owes ₦50,000."}]},{"type":"paragraph","text":[{"text":"Sales account (closed off)","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Profit/loss"}],[{"text":"210,000"}],[{"text":"Cash"}],[{"text":"120,000"}]],[[],[],[{"text":"Bisi"}],[{"text":"90,000"}]],[[],[{"text":"210,000","bold":true}],[],[{"text":"210,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The balance is "},{"text":"whichever side is short","bold":true},{"text":", and it is named after where it goes, not what it is. Sales has a credit balance even though \"Profit/loss\" is written on the debit side."}]}]}]},{"number":"2.5","title":"Capital and revenue receipts and expenditure","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital expenditure:","bold":true},{"text":" spending on acquiring or improving non-current assets, kept to earn profit over several periods; it increases the future earning capability of the business. It goes to the statement of financial position and is charged to profit gradually through "},{"text":"depreciation","bold":true},{"text":"."}]},{"text":[{"text":"Revenue (recurrent) expenditure:","bold":true},{"text":" spending on items consumed in the period or bought for resale; it maintains present earning capability. It is charged "},{"text":"in full","bold":true},{"text":" to the profit or loss account of the period."}]},{"text":[{"text":"Capital receipts:","bold":true},{"text":" capital introduced by the owner, long-term loans received, proceeds from selling non-current assets. They are not income and do not enter profit."}]},{"text":[{"text":"Revenue receipts:","bold":true},{"text":" sales, commission, rent and interest received, dividends on the business's own investments, discount received. (The owner paying his personal dividend into the business is capital introduced.) They are income in the profit or loss account."}]},{"text":[{"text":"The "},{"text":"expired (used-up) portion of capital expenditure is an expense","bold":true},{"text":" (depreciation); the unexpired portion remains an "},{"text":"asset","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Capital expenditure"}],[{"text":"Revenue expenditure"}]],"rows":[[[{"text":"Buying land, buildings, vehicles, new equipment"}],[{"text":"Wages and salaries (e.g. teachers' salaries in a school)"}]],[[{"text":"Carriage and installation of a new machine"}],[{"text":"Rent, electricity, insurance"}]],[[{"text":"Improvements that extend useful life or add capacity"}],[{"text":"Repairs and maintenance that keep the original condition"}]],[[{"text":"Adding a new feature (e.g. automatic control fitted to a vehicle)"}],[{"text":"Purchases of goods for resale; depreciation"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The test for repairs:","bold":true},{"text":" compare with the asset's condition "},{"text":"before","bold":true},{"text":" it needed repair. Spending that only restores or keeps the original useful life is "},{"text":"revenue","bold":true},{"text":". Spending that improves it (longer life, more capacity, a new function) is "},{"text":"capital","bold":true},{"text":". ₦7,000 spent overhauling an engine to add 30 months to its life is capital; repairing a vehicle just to keep its original estimated life is revenue."}]},{"text":[{"text":"Where one bill is part repair and part improvement, split it: the like-for-like part is revenue, the upgrade is capital."}]},{"text":[{"text":"Why it matters:","bold":true},{"text":" treating capital expenditure as revenue "},{"text":"understates","bold":true},{"text":" profit and assets; treating revenue expenditure as capital "},{"text":"overstates","bold":true},{"text":" both."}]},{"text":[{"text":"\"Recurrent expenditure\" is the public-sector name for revenue expenditure: costs that keep coming back to keep the organisation running."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Five elements: assets, liabilities, capital, revenue, expenses."}]},{"text":[{"text":"A = C + L; A − L = C (net assets = owner's equity); A + E = C + R + L."}]},{"text":[{"text":"Closing capital = opening capital + investment + revenue − expenses − drawings. Loans are liabilities, never capital."}]},{"text":[{"text":"Every transaction: a debit and an equal credit, in two or more accounts, so the equation always balances."}]},{"text":[{"text":"Assets and expenses (and drawings): debit to increase. Capital, revenue, liabilities: credit to increase."}]},{"text":[{"text":"Left side of a T account = debit; right side = credit."}]},{"text":[{"text":"Statement of financial position accounts: bal c/d and bal b/d. Revenue and expense accounts: transfer to profit/loss."}]},{"text":[{"text":"Capital expenditure → asset (then depreciation); revenue expenditure → expense in full. Repairs that only maintain are revenue."}]}]}],"theory":{"itemId":"dd0ea6f1-f5ac-57be-aaf9-41d68ca7b529","question":[{"type":"paragraph","text":[{"text":"Tunde's opening capital was ₦400,000. During the year he introduced a further ₦50,000, made a profit of ₦120,000 and took drawings of ₦35,000. His liabilities at the year end were ₦90,000. Calculate his closing capital and total assets, and give the double entry for the drawings if taken in cash."}]}]},"practice":[{"topic":"Elements and the accounting equation","named":true},{"topic":"Double-entry principles","named":true},{"topic":"Capital and revenue classification","named":true}]}},{"itemId":"86195c45-0598-564f-88d3-847b3f4976f3","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"The accounting process","body":"The accounting sequence; source documents and what each records (especially credit and debit notes); the books of original entry and how their totals are posted; the journal's layout and uses; the ledger, the three types of account and the four types of ledger.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The accounting sequence; source documents and what each records (especially credit and debit notes); the books of original entry and how their totals are posted; the journal's layout and uses; the ledger, the three types of account and the four types of ledger."}],"lessons":[{"number":"3.1","title":"The accounting sequence and source documents","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The accounting sequence (5 stages):","bold":true},{"text":" business transaction (source document) → books of original entry (journal entries) → ledger → trial balance → financial statements."}]},{"text":[{"text":"Source documents (accounting documents):","bold":true},{"text":" the source of all original information on a business's financial transactions. No transaction is recorded in the books unless a source document evidences it."}]}]},{"type":"paragraph","text":[{"text":"Need for source documents (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"They serve as evidence of financial transactions, guarding against fraud."}]},{"text":[{"text":"They serve as evidence of financial transactions, making audit possible."}]},{"text":[{"text":"They are usually signed by the parties, so the transaction cannot easily be denied."}]},{"text":[{"text":"Because they are signed by the parties, it is almost impossible to alter them or collude to defraud."}]}]},{"type":"paragraph","text":[{"text":"Main source documents (11):","bold":true}]},{"type":"table","header":[[{"text":"Document"}],[{"text":"Issued by / purpose"}],[{"text":"Recorded in"}]],"rows":[[[{"text":"Sales invoice","bold":true}],[{"text":"Seller to buyer (usually credit sales), asking for payment for goods"}],[{"text":"Sales day book"}]],[[{"text":"Purchase invoice","bold":true}],[{"text":"The same invoice, received by the buyer (same details)"}],[{"text":"Purchases day book"}]],[[{"text":"Credit note","bold":true}],[{"text":"Seller to buyer, reducing what the buyer owes (goods returned or overcharge); made out in "},{"text":"red","bold":true}],[{"text":"Returns inward book (issued) / returns outward book (received)"}]],[[{"text":"Debit note","bold":true}],[{"text":"Buyer to supplier asking for a credit note (goods returned); or seller to customer to "},{"text":"increase","bold":true},{"text":" the amount owed (undercharge)"}],[{"text":"Returns outward book (buyer's returns)"}]],[[{"text":"Bills","bold":true}],[{"text":"Issued for "},{"text":"services","bold":true},{"text":" rendered on credit (electricity, water rate, telephone)"}],[{"text":"The expense concerned"}]],[[{"text":"Payment voucher","bold":true}],[{"text":"Authorises payment of an expense; must be authorised before cash is paid"}],[{"text":"Cash book (credit)"}]],[[{"text":"Bank pay-in slip","bold":true}],[{"text":"Evidence of cash and cheques paid into the bank"}],[{"text":"Cash book, bank column (debit)"}]],[[{"text":"Cheque counterfoil (stub)","bold":true}],[{"text":"Evidence of payments to creditors by cheque and withdrawals"}],[{"text":"Cash book, bank column (credit)"}]],[[{"text":"Receipt","bold":true}],[{"text":"Issued for cash received; original to buyer, duplicate kept by seller"}],[{"text":"Cash book"}]],[[{"text":"Bank statement","bold":true}],[{"text":"Sent by the bank, showing the customer's account and balance"}],[{"text":"Checking the cash book"}]],[[{"text":"Store issue voucher","bold":true}],[{"text":"Storekeeper's evidence of items issued from store"}],[{"text":"Store ledger"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit note:","bold":true},{"text":" issued because goods were damaged before delivery, were of the wrong specification, or the buyer was "},{"text":"overcharged","bold":true},{"text":". Credit note issued = returns on "},{"text":"sales","bold":true},{"text":"; credit note received = returns on "},{"text":"purchases","bold":true},{"text":". If returned goods are "},{"text":"replaced","bold":true},{"text":", no credit note is needed."}]},{"text":[{"text":"Debit note:","bold":true},{"text":" goods returned to a supplier go with a debit note, telling the supplier you have charged (debited) their account in your books; the supplier's credit note then confirms it. A seller who "},{"text":"undercharged","bold":true},{"text":" a customer, or left an expense off the invoice, also sends a debit note."}]},{"text":[{"text":"Trap:","bold":true},{"text":" overcharge = "},{"text":"credit note","bold":true},{"text":"; undercharge = "},{"text":"debit note","bold":true},{"text":". A "},{"text":"remittance advice","bold":true},{"text":" goes with a payment, a "},{"text":"proforma invoice","bold":true},{"text":" is a quotation-style invoice sent before a sale, and a "},{"text":"promissory note","bold":true},{"text":" is a written promise to pay."}]},{"text":[{"text":"Trade discount","bold":true},{"text":" is a reduction in the list price given to trade customers. It appears "},{"text":"only on the invoice","bold":true},{"text":"; the books record the net amount. It is never posted to any account, so there is no \"trade discount account\"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example: goods listed at ₦1,700,000 less 3.5% trade discount. Discount = ₦59,500; net amount recorded and paid = ₦1,640,500."}]}]}]},{"text":[{"text":"Cash discount","bold":true},{"text":" (for prompt payment) is different: it is recorded in the cash book as discount allowed or received (Topic 5)."}]}]}]},{"number":"3.2","title":"Books of original entry (day books)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Books of original entry:","bold":true},{"text":" also called "},{"text":"day books, journals, books of prime entry","bold":true},{"text":" and "},{"text":"subsidiary books","bold":true},{"text":". Transactions are first recorded here daily, then transferred (posted) to the ledger periodically: weekly, fortnightly or monthly, depending on the nature and volume of transactions. Ledger entries are posted "},{"text":"from the subsidiary books","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Need for books of original entry (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"They record the total of transactions in one place rather than in individual accounts."}]},{"text":[{"text":"They give an explanation of each transaction (the complete story in one place)."}]},{"text":[{"text":"They record transactions in chronological order."}]},{"text":[{"text":"They help to prevent error: the book's total can be reconciled with the individual accounts."}]}]},{"type":"paragraph","text":[{"text":"Main books of original entry (7):","bold":true}]},{"type":"table","header":[[{"text":"Book"}],[{"text":"Records"}],[{"text":"Source document"}],[{"text":"Posting"}]],"rows":[[[{"text":"Sales day book","bold":true}],[{"text":"Credit sales"}],[{"text":"Sales invoice (duplicate)"}],[{"text":"Dr each customer (sales ledger); Cr "},{"text":"total","bold":true},{"text":" to sales account"}]],[[{"text":"Purchases day book","bold":true}],[{"text":"Credit purchases of goods"}],[{"text":"Purchase invoice (incoming)"}],[{"text":"Cr each supplier (purchases ledger); Dr "},{"text":"total","bold":true},{"text":" to purchases account"}]],[[{"text":"Returns inward (sales returns) book","bold":true}],[{"text":"Goods returned by customers"}],[{"text":"Credit note issued"}],[{"text":"Dr total to returns inward account; Cr each customer"}]],[[{"text":"Returns outward (purchases returns) book","bold":true}],[{"text":"Goods returned to suppliers"}],[{"text":"Credit note received (with the debit note sent)"}],[{"text":"Cr total to returns outward account; Dr each supplier"}]],[[{"text":"General journal (journal proper)","bold":true}],[{"text":"Items that are not credit sales or purchases"}],[{"text":"Various"}],[{"text":"See Lesson 3.3"}]],[[{"text":"Cash book","bold":true}],[{"text":"Cash and bank transactions"}],[{"text":"Receipts, pay-in slips, cheque stubs"}],[{"text":"Itself part of the ledger"}]],[[{"text":"Petty cash book","bold":true}],[{"text":"Small cash payments"}],[{"text":"Petty cash vouchers"}],[{"text":"Itself part of the ledger"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"cash book","bold":true},{"text":" (and petty cash book) has a "},{"text":"dual role","bold":true},{"text":": it is a book of prime entry "},{"text":"and","bold":true},{"text":" part of the ledger. Its cash and bank columns are the cash and bank accounts themselves, so it is the one subsidiary book where entries are already one side of the double entry."}]},{"text":[{"text":"The purchases day book is for "},{"text":"goods bought for resale","bold":true},{"text":". Furniture bought on credit "},{"text":"for resale","bold":true},{"text":" (a furniture dealer's stock) goes to the purchases day book; furniture bought on credit "},{"text":"for use","bold":true},{"text":" goes to the journal proper."}]},{"text":[{"text":"The sales day book does not describe the goods (the invoice does); the sales returns book does analyse what came back. In a computerised system the books may be stored in computer memory."}]}]},{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" Tola Stores, March 2026:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Mar 2: Sold goods on credit to Ade Ventures, list price ₦400,000 less 10% trade discount (invoice 101)."}]},{"text":[{"text":"Mar 4: Sold goods on credit to Bisi Ltd ₦250,000 (invoice 102)."}]},{"text":[{"text":"Mar 5: Bought goods on credit from Kalu & Sons ₦300,000 (invoice K45)."}]},{"text":[{"text":"Mar 8: Bisi Ltd returned goods ₦30,000 (credit note CN01 issued)."}]},{"text":[{"text":"Mar 10: Returned goods to Kalu & Sons ₦20,000 (credit note KC7 received)."}]},{"text":[{"text":"Mar 12: Bought goods on credit from Femi Ltd ₦180,000 (invoice F09)."}]}]},{"type":"table","header":[[{"text":"Sales day book"}],[{"text":"Inv."}],[{"text":"Customer"}],[{"text":"₦"}]],"rows":[[[{"text":"Mar 2"}],[{"text":"101"}],[{"text":"Ade Ventures"}],[{"text":"360,000"}]],[[{"text":"Mar 4"}],[{"text":"102"}],[{"text":"Bisi Ltd"}],[{"text":"250,000"}]],[[],[],[{"text":"Total (Cr sales account)","bold":true}],[{"text":"610,000","bold":true}]]]},{"type":"table","header":[[{"text":"Purchases day book"}],[{"text":"Inv."}],[{"text":"Supplier"}],[{"text":"₦"}]],"rows":[[[{"text":"Mar 5"}],[{"text":"K45"}],[{"text":"Kalu & Sons"}],[{"text":"300,000"}]],[[{"text":"Mar 12"}],[{"text":"F09"}],[{"text":"Femi Ltd"}],[{"text":"180,000"}]],[[],[],[{"text":"Total (Dr purchases account)","bold":true}],[{"text":"480,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Returns inward book: Mar 8, CN01, Bisi Ltd ₦30,000. Returns outward book: Mar 10, KC7, Kalu & Sons ₦20,000."}]},{"type":"paragraph","text":[{"text":"Postings: Ade Ventures Dr ₦360,000; Bisi Ltd Dr ₦250,000, Cr ₦30,000 (balance ₦220,000 Dr); Kalu & Sons Cr ₦300,000, Dr ₦20,000 (balance ₦280,000 Cr); Femi Ltd Cr ₦180,000. Sales Cr ₦610,000; purchases Dr ₦480,000; returns inward Dr ₦30,000; returns outward Cr ₦20,000. Debits ₦1,140,000 = credits ₦1,140,000."}]},{"type":"paragraph","text":[{"text":"Trap:","bold":true},{"text":" the ₦40,000 trade discount on Mar 2 appears nowhere in the books."}]}]},{"number":"3.3","title":"The general journal","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"General journal (journal proper):","bold":true},{"text":" records transactions that do not fit the other subsidiary books. Each entry shows (1) the "},{"text":"date","bold":true},{"text":", (2) the "},{"text":"accounts debited and credited","bold":true},{"text":" with amounts, (3) a "},{"text":"narration","bold":true},{"text":" (brief explanation giving the purpose and authority of the transaction)."}]},{"text":[{"text":"Layout:","bold":true},{"text":" Date | Particulars | Dr | Cr. The account "},{"text":"debited is written first","bold":true},{"text":", the account credited below it (often \"To: …\"), then the narration (\"Being …\"). Leave a blank line after each entry."}]}]},{"type":"paragraph","text":[{"text":"Uses of the journal (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Opening and closing entries."}]},{"text":[{"text":"Transfers from one account to another."}]},{"text":[{"text":"Purchases and sales of fixed (non-current) assets on credit."}]},{"text":[{"text":"End of period adjustments (Topic 7)."}]},{"text":[{"text":"Correction of errors (Topic 6)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Opening entries","bold":true},{"text":" find the opening capital: A = C + L, so "},{"text":"C = A − L","bold":true},{"text":". Seyi's business on 1 January 2026: cash ₦50,000, bank ₦420,000, inventory ₦300,000, furniture ₦230,000, payables ₦120,000."}]},{"type":"table","header":[[{"text":"Date"}],[{"text":"Particulars"}],[{"text":"Dr ₦"}],[{"text":"Cr ₦"}]],"rows":[[[{"text":"1/1/26"}],[{"text":"Cash in hand"}],[{"text":"50,000"}],[]],[[],[{"text":"Cash at bank"}],[{"text":"420,000"}],[]],[[],[{"text":"Inventory"}],[{"text":"300,000"}],[]],[[],[{"text":"Furniture and fittings"}],[{"text":"230,000"}],[]],[[],[{"text":"Payables"}],[],[{"text":"120,000"}]],[[],[{"text":"Capital"}],[],[{"text":"880,000"}]],[[],[{"text":"Being opening capital","italic":true}],[{"text":"1,000,000","bold":true}],[{"text":"1,000,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Other uses","bold":true},{"text":" (Orire Ltd, June 2026):"}]},{"type":"table","header":[[{"text":"Date"}],[{"text":"Particulars"}],[{"text":"Dr ₦"}],[{"text":"Cr ₦"}]],"rows":[[[{"text":"1/6"}],[{"text":"Machinery"}],[{"text":"186,000"}],[]],[[],[{"text":"To: Jerry Enterprises (payable)"}],[],[{"text":"186,000"}]],[[],[{"text":"Being machinery bought on credit","italic":true}],[],[]],[[{"text":"8/6"}],[{"text":"Jebeleje (receivable)"}],[{"text":"360,000"}],[]],[[],[{"text":"To: Motor vehicle"}],[],[{"text":"360,000"}]],[[],[{"text":"Being motor vehicle sold on credit","italic":true}],[],[]],[[{"text":"16/6"}],[{"text":"Motor car"}],[{"text":"160,000"}],[]],[[],[{"text":"To: Bobo T. (receivable)"}],[],[{"text":"160,000"}]],[[],[{"text":"Being motor car accepted in full settlement of debt","italic":true}],[],[]],[[{"text":"25/6"}],[{"text":"Ilemobayo (payable)"}],[{"text":"45,000"}],[]],[[],[{"text":"To: Prospect Ventures (payable)"}],[],[{"text":"45,000"}]],[[],[{"text":"Being debt transferred to Prospect Ventures, which took over Ilemobayo's business","italic":true}],[],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reasoning: asset up = Dr, asset down = Cr; liability up = Cr, liability down = Dr."}]},{"text":[{"text":"Debt transferred between customers:","bold":true},{"text":" Okunade owes ₦600,000 and Bature takes it over: "},{"text":"Dr Bature, Cr Okunade","bold":true},{"text":" ₦600,000. Only the journal's narration explains such a transfer clearly."}]},{"text":[{"text":"Trap:","bold":true},{"text":" equipment bought "},{"text":"on credit","bold":true},{"text":" goes to the journal proper, not the purchases day book (not goods for resale) and not the cash book (no cash moved)."}]}]}]},{"number":"3.4","title":"The ledger, types of account and types of ledger","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ledger:","bold":true},{"text":" the book containing a group of accounts; the permanent record of the assets, liabilities, income, expenses and capital of a business. Entries are posted to it from the subsidiary books. Also called the "},{"text":"principal book of account","bold":true},{"text":" (book of final entry)."}]},{"text":[{"text":"Account:","bold":true},{"text":" a record of increases and decreases in one item, in T form: "},{"text":"title","bold":true},{"text":", "},{"text":"debit (left) side","bold":true},{"text":", "},{"text":"credit (right) side","bold":true},{"text":". Each side has columns for Date, Particulars (the other account), "},{"text":"Folio","bold":true},{"text":" and Amount."}]},{"text":[{"text":"Folio column:","bold":true},{"text":" for "},{"text":"reference","bold":true},{"text":": it shows the page or account where the other side of the entry is found."}]},{"text":[{"text":"Chart of accounts:","bold":true},{"text":" the list of all accounts (names and code numbers) available for posting transactions."}]}]},{"type":"paragraph","text":[{"text":"Importance of the ledger (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It keeps permanent records of assets, liabilities, income and expenses."}]},{"text":[{"text":"It provides the information needed to prepare the income statement and the balance sheet (statement of financial position)."}]},{"text":[{"text":"It gives the origin of every transaction and the parties involved."}]},{"text":[{"text":"It shows the details of movements in each account (e.g. what was deposited in or withdrawn from the bank, and why)."}]},{"text":[{"text":"The trial balance is extracted from it at the end of the period."}]}]},{"type":"paragraph","text":[{"text":"Types of account (3):","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Relates to"}],[{"text":"Examples"}],[{"text":"Group"}]],"rows":[[[{"text":"Real","bold":true}],[{"text":"Tangible things that can be seen, touched and moved (assets)"}],[{"text":"Cash, motor vehicles, goods, buildings"}],[{"text":"Impersonal"}]],[[{"text":"Personal","bold":true}],[{"text":"Persons, companies, partnerships"}],[{"text":"Debtors (receivables), creditors (payables)"}],[{"text":"Personal"}]],[[{"text":"Nominal","bold":true}],[{"text":"Gains, losses, incomes and expenses"}],[{"text":"Rent, salaries, electricity, discounts, drawings, sales"}],[{"text":"Impersonal"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Principally, accounts are "},{"text":"personal","bold":true},{"text":" or "},{"text":"impersonal","bold":true},{"text":"; impersonal accounts are "},{"text":"real","bold":true},{"text":" or "},{"text":"nominal","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Types of ledger (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sales ledger (receivables or debtors ledger):","bold":true},{"text":" personal accounts of credit customers."}]},{"text":[{"text":"Purchases ledger (payables or creditors ledger):","bold":true},{"text":" personal accounts of credit suppliers."}]},{"text":[{"text":"General ledger (nominal ledger):","bold":true},{"text":" all remaining accounts: nominal accounts (wages, rent, sales, purchases, bad debts, income) and real accounts (land and buildings, motor vehicles, inventory, plant and machinery). The trial balance is extracted from it."}]},{"text":[{"text":"Cash book and petty cash book.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Real accounts:","bold":true},{"text":" debit when more of the item is acquired; credit when it is disposed of (sold, damaged beyond use, given away). Real accounts arise from cash and credit transactions; personal accounts exist only where there are "},{"text":"credit","bold":true},{"text":" transactions."}]},{"text":[{"text":"Salary account = nominal, impersonal.","bold":true},{"text":" Motor vehicle account = real, impersonal. Debtors and creditors = personal."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the sales "},{"text":"ledger","bold":true},{"text":" holds customers' accounts; the sales "},{"text":"journal","bold":true},{"text":" (day book) only lists credit sales first. The sales and purchases "},{"text":"accounts","bold":true},{"text":" themselves are in the general ledger, not the sales and purchases ledgers."}]},{"text":[{"text":"Balancing an account:","bold":true},{"text":" the balance is the difference between the debit and credit totals. Write it on the smaller side as \"balance c/d\", then on the opposite side as \"balance b/d\" for the next period. Example, Bisi Ltd:"}]}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"Folio"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"Folio"}],[{"text":"₦"}]],"rows":[[[{"text":"Mar 4 Sales"}],[{"text":"SDB1"}],[{"text":"250,000"}],[{"text":"Mar 8 Returns inward"}],[{"text":"RIB1"}],[{"text":"30,000"}]],[[],[],[],[{"text":"Mar 31 Balance c/d"}],[],[{"text":"220,000"}]],[[],[],[{"text":"250,000","bold":true}],[],[],[{"text":"250,000","bold":true}]],[[{"text":"Apr 1 Balance b/d"}],[],[{"text":"220,000"}],[],[],[]]]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sequence: source document → books of original entry → ledger → trial balance → financial statements. No entry without a source document."}]},{"text":[{"text":"Credit note = goods returned or overcharge (red); debit note = sent with goods returned to a supplier, or for an undercharge."}]},{"text":[{"text":"Trade discount appears only on the invoice and is never posted; cash discount goes to the cash book."}]},{"text":[{"text":"7 books of original entry: sales, purchases, returns inward, returns outward, general journal, cash book, petty cash book."}]},{"text":[{"text":"Day book totals go to the general ledger (sales Cr, purchases Dr, returns inward Dr, returns outward Cr); individual items go to personal accounts."}]},{"text":[{"text":"Journal: debit first, credit second, narration; 5 uses including credit purchases and sales of non-current assets."}]},{"text":[{"text":"Cash book is both a book of prime entry and part of the ledger."}]},{"text":[{"text":"Accounts: real, personal, nominal (personal vs impersonal). Ledgers: sales, purchases, general, cash book."}]},{"text":[{"text":"Folio = cross-reference column; chart of accounts = list of accounts available for posting."}]}]}],"theory":{"itemId":"4ce45e99-da86-5da6-b297-bdedc23f7d28","question":[{"type":"paragraph","text":[{"text":"On 1 May 2026, Dupe Enterprises (a provisions trader) (a) bought goods for resale on credit from Musa Ltd, list price ₦500,000 less 4% trade discount, and (b) bought a delivery van on credit from Lagos Motors for ₦900,000. State the book of original entry for each and the double entry."}]}]},"practice":[{"topic":"Source documents and books of prime entry","named":true},{"topic":"Ledger accounts and types of accounts","named":true}]}},{"itemId":"dd24d5e7-0295-5d95-9e09-5d5401408d2c","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Accounting Concepts, Conventions and Limitations","body":"What concepts and conventions are and why they exist (GAAP); all 16 concepts and conventions with their other names; which concept explains a given treatment; and the limitations of financial accounting.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What concepts and conventions are and why they exist (GAAP); all 16 concepts and conventions with their other names; which concept explains a given treatment; and the limitations of financial accounting."}],"lessons":[{"number":"4.1","title":"Meaning, objectives and GAAP","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting concepts:","bold":true},{"text":" the fundamental assumptions made by accountants in preparing financial statements; the "},{"text":"basic points of agreement","bold":true},{"text":" on which financial accounting theory and practice are founded. They are the backbone of financial reporting."}]},{"text":[{"text":"Accounting conventions:","bold":true},{"text":" generally accepted practices that guide accountants where transactions are complicated or unclear. They are "},{"text":"not legally binding","bold":true},{"text":", but they keep financial statements consistent and comparable."}]},{"text":[{"text":"GAAP (Generally Accepted Accounting Principles):","bold":true},{"text":" the widely accepted rules and standards used to prepare financial statements so that they report performance fairly and consistently. Concepts and conventions together make up GAAP."}]},{"text":[{"text":"Objectives of accounting concepts:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To keep "},{"text":"uniformity and regularity","bold":true},{"text":" in preparing accounting statements."}]},{"text":[{"text":"To act as underlying principles that help accountants prepare and maintain business records."}]},{"text":[{"text":"To set out the rules all business entities must follow, giving "},{"text":"detailed and comparable","bold":true},{"text":" financial information."}]}]}]}]},{"type":"paragraph","text":[{"text":"The 16 concepts and conventions","bold":true},{"text":" (learn the other names; exams use them interchangeably):"}]},{"type":"table","header":[[{"text":"#"}],[{"text":"Name"}],[{"text":"Other names in questions"}]],"rows":[[[{"text":"1"}],[{"text":"Business entity"}],[{"text":"Entity, economic entity"}]],[[{"text":"2"}],[{"text":"Dual aspect"}],[{"text":"Duality, double entry"}]],[[{"text":"3"}],[{"text":"Money measurement"}],[{"text":"Monetary unit, stable monetary unit"}]],[[{"text":"4"}],[{"text":"Historical cost"}],[{"text":"Cost, accounting cost"}]],[[{"text":"5"}],[{"text":"Objectivity"}],[]],[[{"text":"6"}],[{"text":"Fairness"}],[]],[[{"text":"7"}],[{"text":"Going concern"}],[{"text":"Continuity"}]],[[{"text":"8"}],[{"text":"Periodicity"}],[{"text":"Accounting period, time period"}]],[[{"text":"9"}],[{"text":"Accrual"}],[{"text":"Accruals"}]],[[{"text":"10"}],[{"text":"Realisation"}],[{"text":"Revenue recognition"}]],[[{"text":"11"}],[{"text":"Matching"}],[]],[[{"text":"12"}],[{"text":"Substance over form"}],[]],[[{"text":"13"}],[{"text":"Conservatism"}],[{"text":"Prudence"}]],[[{"text":"14"}],[{"text":"Consistency"}],[]],[[{"text":"15"}],[{"text":"Full disclosure"}],[]],[[{"text":"16"}],[{"text":"Materiality"}],[]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Concepts 1 to 12 are usually called "},{"text":"concepts","bold":true},{"text":" (assumptions). Conservatism, consistency, full disclosure and materiality are the "},{"text":"four conventions","bold":true},{"text":". Many questions say \"principle/guideline\" for either; treat the words as the same thing."}]},{"text":[{"text":"Trap: the spelling is \"Generally "},{"text":"Accepted","bold":true},{"text":" Accounting "},{"text":"Principles","bold":true},{"text":"\" (plural). \"Acceptable\" or \"Principle\" is wrong."}]},{"text":[{"text":"Trap: the basic points of agreement are "},{"text":"accounting concepts","bold":true},{"text":", not \"accounting theory\". Theory is built on the concepts."}]}]}]},{"number":"4.2","title":"Entity, dual aspect, money measurement, cost, objectivity and fairness","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business entity:","bold":true},{"text":" the business is a separate entity, distinct from its owners or managers, for sole traders, partnerships and companies alike. Only transactions that affect the business are recorded, from the business's point of view."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital the owner puts in is owed by the business to the owner."}]},{"text":[{"text":"Cash or goods the owner takes for personal use are "},{"text":"drawings","bold":true},{"text":", not business expenses. Drawings "},{"text":"reduce","bold":true},{"text":" the owner's capital."}]},{"text":[{"text":"The owner's "},{"text":"private assets must not appear","bold":true},{"text":" in the business balance sheet."}]}]}]},{"text":[{"text":"Dual aspect (duality):","bold":true},{"text":" the basis of double entry. Every transaction has two aspects, a receiver and a giver, and affects two accounts on opposite sides: every debit has a corresponding credit. Hence "},{"text":"Assets = Liabilities + Capital","bold":true},{"text":" always holds."}]},{"text":[{"text":"Money measurement:","bold":true},{"text":" only transactions that can be expressed in money (in Nigeria, the Naira) are recorded. Money is the common denominator for measuring assets and liabilities. "},{"text":"Stable monetary unit:","bold":true},{"text":" money is assumed to keep a stable value, so no adjustment is made for inflation (changes in purchasing power)."}]},{"text":[{"text":"Historical cost:","bold":true},{"text":" assets are recorded at the price paid to acquire them, "},{"text":"including acquisition and installation costs","bold":true},{"text":", not at market or selling value. Cost is kept throughout, except for allocating part of it to expense (depreciation) as the asset is used. Its justification is "},{"text":"objectivity","bold":true},{"text":": cost can be traced to a source document."}]},{"text":[{"text":"Objectivity:","bold":true},{"text":" accounting statements should not be influenced by the personal bias of management. Figures should be backed by vouchers, invoices, cheques and bills."}]},{"text":[{"text":"Fairness:","bold":true},{"text":" an extension of objectivity. Reports should be prepared so as "},{"text":"not to favour","bold":true},{"text":" any group or segment of users or society."}]},{"text":[{"text":"Substance over form:","bold":true},{"text":" transactions are accounted for and presented according to their financial "},{"text":"substance and reality","bold":true},{"text":", not merely their "},{"text":"legal form","bold":true},{"text":" (e.g. a lease contract). Where the legal form differs from the economic substance, the economic substance is used, so that assets and liabilities are accounted for accurately."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Entity example.","italic":true},{"text":" Ade starts business with ₦100,000 in his business bank account and brings in his own furniture worth ₦25,000. He pays ₦5,600 business expenses from the business account and ₦4,300 for his son's school fees from his "},{"text":"personal","bold":true},{"text":" account."}]},{"type":"table","header":[[{"text":"Business bank account"}],[{"text":"₦"}]],"rows":[[[{"text":"Capital introduced"}],[{"text":"100,000"}]],[[{"text":"Less business expenses"}],[{"text":"(5,600)"}]],[[{"text":"Balance","bold":true}],[{"text":"94,400","bold":true}]]]},{"type":"paragraph","text":[{"text":"The furniture adds ₦25,000 to assets and capital but never passed through the bank. The school fees are a private transaction and are ignored. (Had Ade paid the fees from the "},{"text":"business","bold":true},{"text":" account, it would be drawings of ₦4,300, reducing both bank and capital.)"}]},{"type":"paragraph","text":[{"text":"Cost example.","italic":true},{"text":" A machine is bought for ₦1,000,000, with ₦2,000 transport to the factory and ₦2,000 installation."}]},{"type":"table","header":[[{"text":"Machine at cost"}],[{"text":"₦"}]],"rows":[[[{"text":"Purchase price"}],[{"text":"1,000,000"}]],[[{"text":"Transport to site"}],[{"text":"2,000"}]],[[{"text":"Installation"}],[{"text":"2,000"}]],[[{"text":"Recorded cost","bold":true}],[{"text":"1,004,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Land bought for ₦5,000,000 stays at ₦5,000,000 in the balance sheet even if it could now sell for ₦8,000,000 (cost). Showing inventory at its "},{"text":"retail (selling) value","bold":true},{"text":" breaks the cost concept."}]},{"text":[{"text":"A talented chief executive is not shown as an asset: no measurable price was paid for the talent ("},{"text":"cost","bold":true},{"text":"), and it cannot be measured reliably in money ("},{"text":"money measurement","bold":true},{"text":"). Pick whichever of the two is offered."}]},{"text":[{"text":"Trap: ignoring inflation is the "},{"text":"monetary unit","bold":true},{"text":" concept, not cost."}]},{"text":[{"text":"Trap: owner's private assets in the balance sheet violate "},{"text":"entity","bold":true},{"text":", not materiality or consistency. \"Limited liability\" and \"can sue and be sued\" describe companies, not the entity concept for a sole trader."}]}]}]},{"number":"4.3","title":"Going concern, periodicity, accrual, realisation and matching","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Going concern:","bold":true},{"text":" the business will continue in operation for the foreseeable future (in principle indefinitely, in perpetuity) and will not be liquidated soon; long enough to carry out its objectives and commitments. A business is a going concern if it can earn a reasonable net income and there is no intention or threat to curtail its business significantly. This is why assets are shown at cost less depreciation, not at break-up (forced-sale) value."}]},{"text":[{"text":"Periodicity (accounting period):","bold":true},{"text":" the business's indefinite life is divided into accounting periods, and the profit and loss account and balance sheet are prepared at regular intervals (one month, three months, six months; usually "},{"text":"one year","bold":true},{"text":"). Needed for measuring profit, tax and financial position, and for comparing periods. Limited liability companies must present financial statements to members "},{"text":"annually","bold":true},{"text":". The year may be a "},{"text":"calendar year","bold":true},{"text":" (1 January to 31 December) or any other 12-month "},{"text":"financial year","bold":true},{"text":" (e.g. 1 April to 31 March)."}]},{"text":[{"text":"Accrual:","bold":true},{"text":" income is recognised when "},{"text":"earned","bold":true},{"text":", not when received; expenses when "},{"text":"incurred","bold":true},{"text":", not when paid. Both are recorded in the period to which they relate. It gives rise to "},{"text":"accrued expenses","bold":true},{"text":" (incurred, not yet paid) and "},{"text":"prepayments","bold":true},{"text":" (paid, benefit not yet received)."}]},{"text":[{"text":"Realisation (revenue recognition):","bold":true},{"text":" decides "},{"text":"when","bold":true},{"text":" revenue is earned: when goods are sold or services rendered, the point at which the customer incurs a liability and a legal right to receive money is created. Receiving an "},{"text":"order","bold":true},{"text":" is not realisation; waiting for "},{"text":"cash","bold":true},{"text":" is not required."}]},{"text":[{"text":"Matching:","bold":true},{"text":" revenue for a period is matched with the costs incurred to earn it, whether paid or not. Costs relating to revenue of a later period are carried forward. "},{"text":"Accrual accounting","bold":true},{"text":" and "},{"text":"end-of-year adjustments","bold":true},{"text":" (accruals, prepayments, depreciation, provisions) rest on matching. "},{"text":"Depreciation","bold":true},{"text":" follows the matching concept."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Matching example.","italic":true},{"text":" A trader buys 50 pairs of shoes for ₦50,000 and sells 35 pairs for ₦70,000."}]},{"type":"table","header":[[],[{"text":"₦"}]],"rows":[[[{"text":"Sales"}],[{"text":"70,000"}]],[[{"text":"Cost of goods sold (35/50 × ₦50,000)"}],[{"text":"35,000"}]],[[{"text":"Gross profit","bold":true}],[{"text":"35,000","bold":true}]],[[{"text":"Cost of 15 unsold pairs carried forward (closing inventory)"}],[{"text":"15,000"}]]]},{"type":"paragraph","text":[{"text":"Which concept? (quick drill)","italic":true}]},{"type":"table","header":[[{"text":"Situation"}],[{"text":"Concept"}]],"rows":[[[{"text":"₦600,000 borrowed in December; ₦36,000 interest for 6 months paid at the end; ₦6,000 charged as December expense (₦36,000 ÷ 6)"}],[{"text":"Matching"}]],[[{"text":"Property rates of ₦120,000 paid once a year; ₦10,000 charged each month"}],[{"text":"Matching"}]],[[{"text":"Machine costing ₦1,200,000 depreciated over 10 years (₦120,000 a year) instead of expensed at once"}],[{"text":"Matching"}]],[[{"text":"Goods sold on credit for ₦80,000 in December, paid in January; included in December sales"}],[{"text":"Realisation (revenue recognition)"}]],[[{"text":"₦2,000,000 customer deposit for work starting next year shown as a liability, not income"}],[{"text":"Realisation (revenue recognition)"}]],[[{"text":"Plant costing ₦10,000,000 with a 10-year life: ₦1,000,000 expensed in year 1, ₦9,000,000 shown as an asset"}],[{"text":"Going concern (and matching)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Large businesses report revenue when it is "},{"text":"earned","bold":true},{"text":", not when cash is received (cash basis)."}]},{"text":[{"text":"Trap: \"revenue recognition\" only deals with income. A question about "},{"text":"expenses","bold":true},{"text":" related to revenue, paid or not, is "},{"text":"matching","bold":true},{"text":"."}]},{"text":[{"text":"Trap: there is no \"adjustment concept\"; year-end adjustments satisfy "},{"text":"matching","bold":true},{"text":"."}]}]}]},{"number":"4.4","title":"The conventions: conservatism, consistency, full disclosure, materiality","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conservatism (prudence):","bold":true},{"text":" be cautious with estimates. Do not recognise income until it is earned (reasonably certain); recognise expenses and losses as soon as they are "},{"text":"reasonably possible (probable)","bold":true},{"text":" and make provision for all losses. Where two acceptable values exist, choose the one giving "},{"text":"lower profit, lower assets or higher liabilities","bold":true},{"text":". Purpose: profit and net worth are not "},{"text":"overstated","bold":true},{"text":"."}]},{"text":[{"text":"Consistency:","bold":true},{"text":" once a method is adopted for an item, use it from period to period, and treat like items in the same way. Example: if straight-line depreciation is chosen (rather than reducing balance or sum of the digits), keep using straight line. It allows comparison of the business's statements over time."}]},{"text":[{"text":"Full disclosure:","bold":true},{"text":" all information that is potentially significant and relevant to users must be disclosed, even if unfavourable to the business, often in "},{"text":"notes (footnotes)","bold":true},{"text":" to the accounts."}]},{"text":[{"text":"Materiality:","bold":true},{"text":" items significant enough to affect users' evaluation or decisions must be disclosed separately; immaterial items may be treated in the simplest way or combined. Materiality is "},{"text":"relative","bold":true},{"text":" and needs judgement: what is material to a sole trader may be immaterial to a large firm."}]},{"text":[{"text":"Industry practice:","bold":true},{"text":" an industry may depart from normal presentation where its special nature makes another approach more useful (e.g. public utilities list plant assets before current assets)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conservatism in action:","bold":true},{"text":" inventory costing ₦400,000 that can now sell for only ₦300,000 is written "},{"text":"down","bold":true},{"text":" to ₦300,000. Inventory costing ₦400,000 that could sell for ₦550,000 stays at ₦400,000: never written "},{"text":"up","bold":true},{"text":". Losses are recognised; gains wait until realised."}]},{"text":[{"text":"Changing a method (consistency):","bold":true},{"text":" allowed only if the new method gives a fairer view, and "},{"text":"users must be informed","bold":true},{"text":" of the change and its effect on profit. Frequent changes or changes to manipulate profit break consistency."}]},{"text":[{"text":"Trap: consistency does "},{"text":"not","bold":true},{"text":" mean all companies in the same industry must use the same methods. It applies within one business over time."}]},{"text":[{"text":"Materiality in action:","bold":true},{"text":" a large company expenses a ₦250,000 camera at once instead of depreciating it; a big company rounds figures to the nearest ₦1,000. Both are acceptable because the amounts would not change any user's decision. Materiality is the convention that "},{"text":"justifies departing","bold":true},{"text":" from a strict rule for immaterial amounts."}]},{"text":[{"text":"Trap: full disclosure asks for "},{"text":"more","bold":true},{"text":" information; materiality allows "},{"text":"less","bold":true},{"text":" detail for small items."}]}]}]},{"number":"4.5","title":"Limitations of financial accounting","mustKnow":[{"type":"paragraph","text":[{"text":"Financial accounting is like a "},{"text":"post-mortem report","bold":true},{"text":": it shows what has happened but cannot control past events. Its 15 limitations:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It records only "},{"text":"quantitative","bold":true},{"text":" information."}]},{"text":[{"text":"It records only "},{"text":"historical cost","bold":true},{"text":"; future uncertainties have no place."}]},{"text":[{"text":"It ignores "},{"text":"price level changes","bold":true},{"text":" (inflation)."}]},{"text":[{"text":"It gives information on the "},{"text":"whole concern","bold":true},{"text":" only, not by product, process or department."}]},{"text":[{"text":"Cost figures are not known in advance, so prices cannot be fixed in advance; it gives no guide to raising or cutting selling price."}]},{"text":[{"text":"It has no technique for comparing actual performance with "},{"text":"budgeted","bold":true},{"text":" targets, so performance cannot be evaluated."}]},{"text":[{"text":"It does not show whether profit is optimum or how to increase it."}]},{"text":[{"text":"In a loss, it does not show whether cost control and cost reduction can reduce the loss or turn it into profit."}]},{"text":[{"text":"It does not reveal which departments perform well or which make losses, and how much."}]},{"text":[{"text":"It does not provide the "},{"text":"cost of products","bold":true},{"text":" manufactured."}]},{"text":[{"text":"It provides no means to reduce "},{"text":"wastage","bold":true},{"text":"."}]},{"text":[{"text":"It does not show whether, how and how far expenses can be cut to reduce product cost."}]},{"text":[{"text":"It does not help management in "},{"text":"strategic decisions","bold":true},{"text":" (replacing assets, new products, dropping a line, expanding capacity)."}]},{"text":[{"text":"It gives scope for "},{"text":"manipulation","bold":true},{"text":" (overvaluation or undervaluation), reducing reliability."}]},{"text":[{"text":"It is "},{"text":"technical","bold":true},{"text":": a person not conversant with accounting gets little use from it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In short form, accounting "},{"text":"lacks qualitative analysis","bold":true},{"text":", is "},{"text":"not free from bias","bold":true},{"text":" (judgement and possible manipulation), and shows only an "},{"text":"estimated position","bold":true},{"text":" (depreciation and provisions are estimates)."}]},{"text":[{"text":"Trap: \"it is value free\" is "},{"text":"not","bold":true},{"text":" a limitation. Accounting is never value free; it depends on judgement."}]},{"text":[{"text":"Link to concepts: limitations 2 and 3 come from the "},{"text":"historical cost","bold":true},{"text":" and "},{"text":"stable monetary unit","bold":true},{"text":" concepts; limitation 1 from "},{"text":"money measurement","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Concepts = basic assumptions; conventions = accepted practices; together = GAAP (Generally Accepted Accounting Principles)."}]},{"text":[{"text":"Entity: business separate from owner; drawings reduce capital; private assets stay out."}]},{"text":[{"text":"Dual aspect: every debit has a credit; A = L + C."}]},{"text":[{"text":"Money measurement: only money items; stable monetary unit ignores inflation."}]},{"text":[{"text":"Historical cost: price paid plus transport and installation; land stays at cost."}]},{"text":[{"text":"Going concern: business continues; periodicity: life split into periods, usually a year."}]},{"text":[{"text":"Accrual: earned/incurred, not received/paid. Realisation: revenue when goods sold, not order or cash."}]},{"text":[{"text":"Matching: costs matched with the revenue they earn; depreciation and year-end adjustments."}]},{"text":[{"text":"Conventions: conservatism (lower profit/assets), consistency (same method, disclose changes), full disclosure (notes), materiality (small items, judgement)."}]},{"text":[{"text":"Financial accounting is a post-mortem: 15 limitations, mainly quantitative, historical, whole-concern only."}]}]}],"theory":{"itemId":"53434749-726b-5e0b-be5e-34804c05c538","question":[{"type":"paragraph","text":[{"text":"Bola, a sole trader, buys 40 bags of rice for ₦800,000 and sells 30 bags on credit for ₦900,000 in December; the customer pays in January. In December she also takes one bag home for her family. Calculate gross profit for December and name the concept that applies to (i) the credit sale, (ii) the cost charged, (iii) the bag taken home."}]}]},"practice":[{"topic":"Accounting concepts, conventions and limitations","named":false}]}},{"itemId":"711e3167-751d-502e-aab0-73b6b9929c6f","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Cash book and bank reconciliation","body":"What the cash book is and its types (single, two-column, three-column, petty cash) and the imprest system; contra entries; discounts allowed and received; the bank statement; the causes of differences between the two; the adjusted cash book; and both layouts of the bank reconciliation statement.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"What the cash book is and its types (single, two-column, three-column, petty cash) and the imprest system; contra entries; discounts allowed and received; the bank statement; the causes of differences between the two; the adjusted cash book; and both layouts of the bank reconciliation statement."}],"lessons":[{"number":"5.1","title":"The cash book and its types","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash book:","bold":true},{"text":" an asset account that keeps records of transactions through cash or through the bank. It is both a "},{"text":"journal","bold":true},{"text":" (book of original entry, recording transactions as they occur) and a "},{"text":"ledger","bold":true},{"text":" account (entries follow the double entry principle). It is "},{"text":"the book that shows receipts, payments and the balances of cash and bank","bold":true},{"text":"."}]},{"text":[{"text":"Debit side","bold":true},{"text":" = receipts of money (increases). "},{"text":"Credit side","bold":true},{"text":" = payments of money (decreases)."}]},{"text":[{"text":"Contra entry:","bold":true},{"text":" an entry that appears on "},{"text":"both","bold":true},{"text":" the debit and credit sides of the cash book, so the whole double entry is completed inside the cash book. Examples: cash paid into the bank (Dr bank column, Cr cash column); cash withdrawn from the bank for office use (Dr cash, Cr bank). Marked \"C\" in the folio column."}]}]},{"type":"paragraph","text":[{"text":"Types of cash book","bold":true},{"text":" (types 1 to 3 are the classification by the number of money columns on each side; the petty cash book is kept alongside them):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Single column:","bold":true},{"text":" one column; a simple cash account or bank account."}]},{"text":[{"text":"Double (two-column):","bold":true},{"text":" two columns, "},{"text":"cash","bold":true},{"text":" and "},{"text":"bank","bold":true},{"text":"."}]},{"text":[{"text":"Three-column:","bold":true},{"text":" an extension of the two-column book with a "},{"text":"discount","bold":true},{"text":" column on each side."}]},{"text":[{"text":"Petty cash book:","bold":true},{"text":" for small cash payments, usually run on the "},{"text":"imprest","bold":true},{"text":" system (Lesson 5.2)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Balances:","bold":true},{"text":" the cash column can only have a debit balance (you cannot pay out more notes than you hold). A "},{"text":"debit","bold":true},{"text":" balance in the bank column = money in the bank. A "},{"text":"credit","bold":true},{"text":" balance in the bank column = a "},{"text":"bank overdraft","bold":true},{"text":"."}]},{"text":[{"text":"Cash discount:","bold":true},{"text":" a reduction in the sum paid if payment is made "},{"text":"within an agreed period","bold":true},{"text":", to encourage early settlement. Given to customers = "},{"text":"discount allowed","bold":true},{"text":" (an expense; debit side of the cash book). Received from suppliers = "},{"text":"discount received","bold":true},{"text":" (income; credit side)."}]},{"text":[{"text":"Trade discount:","bold":true},{"text":" a reduction in list price for trade or bulk buying. It is never entered in the cash book or any account."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The discount columns are "},{"text":"memorandum","bold":true},{"text":" columns: they are not balanced. At an agreed period their totals are "},{"text":"transferred","bold":true},{"text":" to the ledger: total of the debit-side column → Dr discount allowed account; total of the credit-side column → Cr discount received account."}]},{"text":[{"text":"Not","bold":true},{"text":" recorded in the cash book: anything with no movement of money, such as "},{"text":"depreciation","bold":true},{"text":", credit sales and purchases, or goods taken as drawings. Bank charges, salaries and receipts from debtors are recorded because money moves."}]},{"text":[{"text":"Discount calculation trap:","bold":true},{"text":" list price ₦50,000, 2.5% trade discount, 5% cash discount. Trade discount comes off first: ₦50,000 − ₦1,250 = ₦48,750 (invoice amount). Cash discount = 5% × ₦48,750 = "},{"text":"₦2,437.50","bold":true},{"text":". Amount paid = "},{"text":"₦46,312.50","bold":true},{"text":". ₦1,250 is the trade discount, not the cash discount."}]},{"text":[{"text":"Worked example: Femi Stores, three-column cash book, May 2026.","bold":true},{"text":" 1 May balances: cash ₦20,000, bank ₦150,000. 3 May: received a cheque from Ade ₦47,500 in full settlement of ₦50,000. 6 May: cash sales ₦35,000. 8 May: paid ₦30,000 cash into the bank. 10 May: paid Bello by cheque ₦76,000 in full settlement of ₦80,000. 12 May: paid wages in cash ₦12,000. 14 May: withdrew ₦10,000 from the bank for office use."}]}]},{"type":"table","header":[[{"text":"Date"}],[{"text":"Details"}],[{"text":"Disc ₦"}],[{"text":"Cash ₦"}],[{"text":"Bank ₦"}],[{"text":"Date"}],[{"text":"Details"}],[{"text":"Disc ₦"}],[{"text":"Cash ₦"}],[{"text":"Bank ₦"}]],"rows":[[[{"text":"1 May"}],[{"text":"Balance b/d"}],[],[{"text":"20,000"}],[{"text":"150,000"}],[{"text":"8 May"}],[{"text":"Bank (C)"}],[],[{"text":"30,000"}],[]],[[{"text":"3 May"}],[{"text":"Ade"}],[{"text":"2,500"}],[],[{"text":"47,500"}],[{"text":"10 May"}],[{"text":"Bello"}],[{"text":"4,000"}],[],[{"text":"76,000"}]],[[{"text":"6 May"}],[{"text":"Sales"}],[],[{"text":"35,000"}],[],[{"text":"12 May"}],[{"text":"Wages"}],[],[{"text":"12,000"}],[]],[[{"text":"8 May"}],[{"text":"Cash (C)"}],[],[],[{"text":"30,000"}],[{"text":"14 May"}],[{"text":"Cash (C)"}],[],[],[{"text":"10,000"}]],[[{"text":"14 May"}],[{"text":"Bank (C)"}],[],[{"text":"10,000"}],[],[{"text":"14 May"}],[{"text":"Balance c/d"}],[],[{"text":"23,000"}],[{"text":"141,500"}]],[[],[],[{"text":"2,500","bold":true}],[{"text":"65,000","bold":true}],[{"text":"227,500","bold":true}],[],[],[{"text":"4,000","bold":true}],[{"text":"65,000","bold":true}],[{"text":"227,500","bold":true}]],[[{"text":"15 May"}],[{"text":"Balance b/d"}],[],[{"text":"23,000"}],[{"text":"141,500"}],[],[],[],[],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Ade is credited ₦50,000 and Bello debited ₦80,000; then Dr discount allowed ₦2,500, Cr discount received ₦4,000."}]}]}]},{"number":"5.2","title":"Petty cash book and the imprest system","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Petty cash book:","bold":true},{"text":" records "},{"text":"small payments made in cash","bold":true},{"text":" (postage, transport, cleaning, refreshments, stationery). It is kept by a "},{"text":"petty cashier","bold":true},{"text":", often a junior member of staff, and has a total column plus "},{"text":"analysis columns","bold":true},{"text":" for each type of expense."}]},{"text":[{"text":"Imprest system:","bold":true},{"text":" the petty cashier starts each period with an agreed "},{"text":"float","bold":true},{"text":" (the imprest). Each payment is supported by a signed "},{"text":"petty cash voucher","bold":true},{"text":". At the end of the period (or when cash runs low) the main cashier "},{"text":"reimburses exactly the amount spent","bold":true},{"text":", restoring the float to its agreed level."}]},{"text":[{"text":"Petty cash account is debited","bold":true},{"text":" when the fund is first "},{"text":"established","bold":true},{"text":" and every time it is "},{"text":"replenished","bold":true},{"text":" (reimbursed). It is "},{"text":"credited","bold":true},{"text":" each time money is spent, and when the float is reduced."}]},{"text":[{"text":"At the end of the period the analysis column totals are "},{"text":"debited","bold":true},{"text":" to the expense accounts in the general (nominal) ledger."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash in hand + vouchers always equals the imprest, so a spot count quickly detects theft."}]},{"text":[{"text":"Example:","bold":true},{"text":" imprest ₦20,000. During the week: stamps ₦1,500, transport ₦3,200, cleaning ₦2,000, refreshments ₦4,800, stationery ₦2,500."}]}]},{"type":"table","header":[[{"text":"Receipts ₦"}],[{"text":"Details"}],[{"text":"Total ₦"}],[{"text":"Postage ₦"}],[{"text":"Travel ₦"}],[{"text":"Cleaning ₦"}],[{"text":"Refresh. ₦"}],[{"text":"Stat'y ₦"}]],"rows":[[[{"text":"20,000"}],[{"text":"Cash book (float)"}],[],[],[],[],[],[]],[[],[{"text":"Stamps"}],[{"text":"1,500"}],[{"text":"1,500"}],[],[],[],[]],[[],[{"text":"Transport"}],[{"text":"3,200"}],[],[{"text":"3,200"}],[],[],[]],[[],[{"text":"Cleaning"}],[{"text":"2,000"}],[],[],[{"text":"2,000"}],[],[]],[[],[{"text":"Refreshments"}],[{"text":"4,800"}],[],[],[],[{"text":"4,800"}],[]],[[],[{"text":"Stationery"}],[{"text":"2,500"}],[],[],[],[],[{"text":"2,500"}]],[[],[],[{"text":"14,000","bold":true}],[{"text":"1,500","bold":true}],[{"text":"3,200","bold":true}],[{"text":"2,000","bold":true}],[{"text":"4,800","bold":true}],[{"text":"2,500","bold":true}]],[[{"text":"14,000"}],[{"text":"Cash book (reimbursement)"}],[],[],[],[],[],[]],[[],[{"text":"Balance c/d"}],[{"text":"20,000"}],[],[],[],[],[]],[[{"text":"34,000","bold":true}],[],[{"text":"34,000","bold":true}],[],[],[],[],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Before reimbursement, cash in hand = ₦20,000 − ₦14,000 = ₦6,000. Reimbursement = amount spent = ₦14,000, restoring the float to ₦20,000."}]},{"text":[{"text":"Trap:","bold":true},{"text":" if the petty cashier also received money (say staff paid ₦1,000 for photocopying), the reimbursement is spending less that receipt."}]},{"text":[{"text":"Trap:","bold":true},{"text":" petty cash is cash, not bank. Errors in the petty cash book can "},{"text":"never","bold":true},{"text":" cause a difference between the cash book (bank column) and the bank statement."}]}]}]},{"number":"5.3","title":"The bank statement and causes of differences","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bank statement:","bold":true},{"text":" the record kept by the bank of its transactions with the customer; a summary of the account for the period. To the bank, the customer's money is a "},{"text":"liability","bold":true},{"text":" (the bank owes it), so the statement is the mirror image of the cash book:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit","bold":true},{"text":" side = receipts into the account (lodgements, direct credits, dividends)."}]},{"text":[{"text":"Debit","bold":true},{"text":" side = payments out (cheques paid, standing orders, direct debits, bank charges, dishonoured cheques)."}]}]}]},{"text":[{"text":"A credit balance on the statement (\"in favour\") = money in the bank. A debit balance on the statement = overdraft."}]},{"text":[{"text":"Bank reconciliation statement (BRS):","bold":true},{"text":" a schedule that accounts for the differences between the balance in the "},{"text":"bank column of the cash book","bold":true},{"text":" and the balance on the "},{"text":"bank statement","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Reasons for bank reconciliation (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It affords the opportunity to update the cash book."}]},{"text":[{"text":"It serves as a means of correcting errors."}]},{"text":[{"text":"Fraud can be detected and prevented."}]},{"text":[{"text":"It enables the business to highlight errors committed by the bankers."}]}]},{"type":"paragraph","text":[{"text":"Causes of differences (3 groups):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"In the cash book but not on the bank statement (timing differences):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Uncredited cheques (uncredited lodgements):","bold":true},{"text":" cheques received and paid in, debited in the cash book, not yet credited by the bank."}]},{"text":[{"text":"Unpresented cheques:","bold":true},{"text":" cheques issued by the business and credited in the cash book, not yet presented to the bank for payment."}]}]}]},{"text":[{"text":"On the bank statement but not in the cash book:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct debits:","bold":true},{"text":" standing orders, bank charges, interest on overdraft, dishonoured cheques."}]},{"text":[{"text":"Direct credits:","bold":true},{"text":" credit transfers from customers, dividends received, interest received."}]}]}]},{"text":[{"text":"Errors:","bold":true},{"text":" in the cash book, in the bank statement, or in both."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standing order:","bold":true},{"text":" a written instruction by a customer to the bank to pay a fixed sum regularly to a named payee (rent, insurance premium, club subscription). "},{"text":"Bank charges","bold":true},{"text":" (service charges, commission): the bank's fee for running a current account. "},{"text":"Credit (direct) transfer:","bold":true},{"text":" money paid by a payer straight into the business's account."}]},{"text":[{"text":"Dishonoured cheque","bold":true},{"text":" (\"returned\", \"refer to drawer\"): a cheque the paying bank refuses to honour. It is returned, so the bank debits the account to reverse the amount it had credited. Reasons (5):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insufficient funds in the drawer's account."}]},{"text":[{"text":"Irregular signature, or no signature."}]},{"text":[{"text":"Amounts in figures and in words do not agree."}]},{"text":[{"text":"No date, or the cheque is post-dated."}]},{"text":[{"text":"An alteration not endorsed by the drawer."}]}]}]},{"text":[{"text":"Other names:","bold":true},{"text":" unpresented = outstanding cheques; uncredited cheques = outstanding lodgements (deposits in transit)."}]},{"text":[{"text":"Procedure (ticking):","bold":true},{"text":" check the casting of both. Tick cash book "},{"text":"debits","bold":true},{"text":" against statement "},{"text":"credits","bold":true},{"text":", and cash book "},{"text":"credits","bold":true},{"text":" against statement "},{"text":"debits","bold":true},{"text":". Then:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unticked on the "},{"text":"credit","bold":true},{"text":" side of the cash book = "},{"text":"unpresented cheques","bold":true},{"text":"."}]},{"text":[{"text":"Unticked on the "},{"text":"debit","bold":true},{"text":" side of the cash book = "},{"text":"uncredited cheques","bold":true},{"text":"."}]},{"text":[{"text":"Unticked on the "},{"text":"credit","bold":true},{"text":" side of the statement = "},{"text":"direct credits","bold":true},{"text":" (debit them to the cash book)."}]},{"text":[{"text":"Unticked on the "},{"text":"debit","bold":true},{"text":" side of the statement = "},{"text":"standing orders, bank charges, dishonoured cheques","bold":true},{"text":" (credit them to the cash book). A direct transfer is never here."}]}]}]},{"text":[{"text":"If the opening balances of the two records differ, reconcile last period's outstanding items first. Unpresented cheques and lodgements from last period that clear this month are already explained."}]},{"text":[{"text":"Reasoning trap:","bold":true},{"text":" cash book debit balance ₦1,000, statement credit balance ₦900. The bank figure is lower, so the bank has taken out something not yet in the cash book (e.g. a "},{"text":"standing order","bold":true},{"text":"). Unpresented cheques, bank interest received and direct credits would all make the bank figure "},{"text":"higher","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Adjusted cash book and the bank reconciliation statement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The BRS can be prepared "},{"text":"straightaway","bold":true},{"text":" (from the original cash book balance) or after an "},{"text":"adjusted cash book","bold":true},{"text":". Exams usually ask for both."}]},{"text":[{"text":"Adjusted cash book (5 kinds of items):","bold":true},{"text":" bank charges, standing orders (direct debits), credit transfers and direct receipts (dividend, interest), dishonoured cheques, errors made by the business."}]}]},{"type":"table","header":[[{"text":"Debit (increase balance)"}],[{"text":"Credit (reduce balance)"}]],"rows":[[[{"text":"Balance b/d (if favourable)"}],[{"text":"Balance b/d (if overdraft)"}]],[[{"text":"Direct credits: credit transfers, dividends, interest received"}],[{"text":"Direct debits: standing orders, bank charges, dishonoured cheques"}]],[[{"text":"Errors that reduced the cash book balance"}],[{"text":"Errors that increased the cash book balance"}]],[[],[{"text":"Balance c/d"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"BRS after an adjusted cash book (3 items only):","bold":true},{"text":" uncredited cheques, unpresented cheques, errors in the bank statement."}]}]},{"type":"table","header":[[{"text":"Starting from bank statement balance"}],[{"text":"Starting from (adjusted) cash book balance"}]],"rows":[[[{"text":"Add","bold":true},{"text":" uncredited cheques"}],[{"text":"Add","bold":true},{"text":" unpresented cheques"}]],[[{"text":"Less","bold":true},{"text":" unpresented cheques"}],[{"text":"Less","bold":true},{"text":" uncredited cheques"}]],[[{"text":"Add/less bank errors"}],[{"text":"Less/add bank errors (reversed)"}]],[[{"text":"= Balance as per (adjusted) cash book"}],[{"text":"= Balance as per bank statement"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Straightaway BRS from the bank statement:","bold":true},{"text":" add uncredited cheques, direct debits and errors; less unpresented cheques, direct credits and errors; = balance as per cash book. From the cash book, every sign is reversed."}]},{"text":[{"text":"Rules: use the balance the question gives; a balance that is not normal (credit in the cash book, debit on the statement) is an "},{"text":"overdraft","bold":true},{"text":", shown in brackets; compare only the "},{"text":"bank column","bold":true},{"text":" with the statement."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example: Kemi Stores, 30 June 2026.","bold":true},{"text":" Cash book (bank column) shows a debit balance of ₦84,500; the bank statement shows ₦93,900 in favour. On comparison:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cheques issued not yet presented: Bello ₦23,000, Oni ₦12,500."}]},{"text":[{"text":"A cheque of ₦18,000 paid in on 30 June not yet credited by the bank."}]},{"text":[{"text":"Bank charges ₦1,500 and a standing order for insurance ₦6,000 appear only on the statement."}]},{"text":[{"text":"A dividend of ₦9,000 was received directly by the bank."}]},{"text":[{"text":"A cheque of ₦4,000 from Tunde, a customer, was dishonoured."}]},{"text":[{"text":"A cheque payment of ₦7,300 to a supplier was entered in the cash book as ₦3,700."}]},{"text":[{"text":"The bank debited a cheque of ₦2,000 belonging to another customer to Kemi's account in error."}]}]}]}]},{"type":"paragraph","text":[{"text":"Adjusted cash book (bank column)","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Balance b/d"}],[{"text":"84,500"}],[{"text":"Bank charges"}],[{"text":"1,500"}]],[[{"text":"Dividend (direct credit)"}],[{"text":"9,000"}],[{"text":"Standing order: insurance"}],[{"text":"6,000"}]],[[],[],[{"text":"Dishonoured cheque: Tunde"}],[{"text":"4,000"}]],[[],[],[{"text":"Error: payment understated (₦7,300 − ₦3,700)"}],[{"text":"3,600"}]],[[],[],[{"text":"Balance c/d"}],[{"text":"78,400"}]],[[],[{"text":"93,500","bold":true}],[],[{"text":"93,500","bold":true}]],[[{"text":"Balance b/d"}],[{"text":"78,400"}],[],[]]]},{"type":"paragraph","text":[{"text":"BRS as at 30 June 2026: layout 1, from the bank statement","bold":true}]},{"type":"table","header":[[],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Balance as per bank statement"}],[],[{"text":"93,900"}]],[[{"text":"Add: uncredited cheque"}],[{"text":"18,000"}],[]],[[{"text":"Add: bank error (cheque wrongly debited)"}],[{"text":"2,000"}],[{"text":"20,000"}]],[[],[],[{"text":"113,900"}]],[[{"text":"Less: unpresented cheques: Bello"}],[{"text":"23,000"}],[]],[[{"text":"Oni"}],[{"text":"12,500"}],[{"text":"(35,500)"}]],[[{"text":"Balance as per adjusted cash book"}],[],[{"text":"78,400","bold":true}]]]},{"type":"paragraph","text":[{"text":"BRS as at 30 June 2026: layout 2, from the adjusted cash book","bold":true}]},{"type":"table","header":[[],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Balance as per adjusted cash book"}],[],[{"text":"78,400"}]],[[{"text":"Add: unpresented cheques (₦23,000 + ₦12,500)"}],[],[{"text":"35,500"}]],[[],[],[{"text":"113,900"}]],[[{"text":"Less: uncredited cheque"}],[{"text":"18,000"}],[]],[[{"text":"Less: bank error"}],[{"text":"2,000"}],[{"text":"(20,000)"}]],[[{"text":"Balance as per bank statement"}],[],[{"text":"93,900","bold":true}]]]},{"type":"paragraph","text":[{"text":"The same done straightaway, from the original cash book balance:","bold":true},{"text":" ₦84,500 + unpresented ₦35,500 + dividend ₦9,000 = ₦129,000; less uncredited ₦18,000, bank charges ₦1,500, standing order ₦6,000, dishonoured ₦4,000, cash book error ₦3,600, bank error ₦2,000 (total ₦35,100) = "},{"text":"₦93,900","bold":true},{"text":", the bank statement balance."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Why the bank error is added to the bank balance:","bold":true},{"text":" the bank wrongly took ₦2,000 out, so the true bank figure is higher. A bank error is corrected only in the BRS, never in the cash book."}]},{"text":[{"text":"Overdraft example:","bold":true},{"text":" adjusted cash book overdraft ₦32,500, unpresented ₦65,900, uncredited ₦18,500. From the cash book: (₦32,500) + ₦65,900 = ₦33,400; − ₦18,500 = "},{"text":"₦14,900","bold":true},{"text":" in favour per bank statement. The overdraft b/d sits on the "},{"text":"credit","bold":true},{"text":" side of the adjusted cash book."}]},{"text":[{"text":"Traps:","bold":true},{"text":" a direct transfer goes to the "},{"text":"debit","bold":true},{"text":" side of the adjusted cash book; bank charges always "},{"text":"reduce","bold":true},{"text":" its balance. Items needing an adjusting entry in the cash book are those the bank has recorded first (interest, charges, standing orders, direct credits). Unpresented and uncredited cheques correct themselves when the bank processes them."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash book: asset account, both journal and ledger; debit = receipts, credit = payments; contra entries appear on both sides."}]},{"text":[{"text":"Types by number of columns (3): single column, two-column (cash and bank), three-column (adds discount); plus the petty cash book."}]},{"text":[{"text":"Credit balance in the bank column = overdraft. Depreciation never passes through the cash book."}]},{"text":[{"text":"Cash discount is for paying within an agreed period: discount allowed (debit side) and discount received (credit side), totals transferred to the ledger. Trade discount comes off first and is never recorded."}]},{"text":[{"text":"Imprest: fixed float, vouchers, reimburse exactly what was spent; petty cash is debited when set up and when replenished."}]},{"text":[{"text":"Bank statement is the mirror image: credit = lodgements, debit = withdrawals."}]},{"text":[{"text":"Causes: uncredited and unpresented cheques; direct debits and direct credits; errors."}]},{"text":[{"text":"Adjusted cash book takes bank charges, standing orders, direct credits, dishonoured cheques and cash book errors."}]},{"text":[{"text":"BRS after adjustment takes only uncredited cheques, unpresented cheques and bank errors."}]},{"text":[{"text":"From the bank statement: add uncredited, less unpresented. From the cash book: add unpresented, less uncredited."}]}]}],"theory":{"itemId":"36fbc19d-4693-51d1-80e3-2a350929ed49","question":[{"type":"paragraph","text":[{"text":"On 31 March 2026 Tola's cash book shows an overdraft of ₦25,000. Bank charges of ₦2,000 are not in the cash book, and the bank received a dividend of ₦10,000 for Tola. Unpresented cheques total ₦30,000 and a lodgement of ₦12,000 is not yet credited. Prepare the adjusted cash book balance and a BRS starting from it."}]}]},"practice":[{"topic":"Cash book and bank reconciliation","named":false}]}},{"itemId":"9a9e3d06-07d4-57a9-a121-bea5452ac962","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"The Trial Balance and Correction of Errors","body":"What a trial balance is, its purpose, uses, importance and limits; how to prepare one; the six errors that do not affect its agreement; the errors that do; the suspense account; and how to correct errors with journal entries.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What a trial balance is, its purpose, uses, importance and limits; how to prepare one; the six errors that do not affect its agreement; the errors that do; the suspense account; and how to correct errors with journal entries."}],"lessons":[{"number":"6.1","title":"What a trial balance is and why we prepare it","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trial balance:","bold":true},{"text":" a list or schedule of all the debit and credit balances extracted from the ledger accounts. It is also called a "},{"text":"summary of ledger balances","bold":true},{"text":". It is prepared at the "},{"text":"end of an accounting period","bold":true},{"text":". Debit balances go in the debit column, credit balances in the credit column, and "},{"text":"the totals of both columns must agree","bold":true},{"text":"."}]},{"text":[{"text":"Purpose:","bold":true},{"text":" to ensure that all entries made in the general ledger are properly balanced, that is, that total debits equal total credits. It lists the ending balance on each general ledger account."}]}]},{"type":"paragraph","text":[{"text":"5 uses of a trial balance","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ensures accuracy in postings:","bold":true},{"text":" helps the accountant verify that the balances from the ledger (the principal book of account) were extracted accurately."}]},{"text":[{"text":"Provides an overview:","bold":true},{"text":" a summary sheet giving a bird's eye view of the business's transactions."}]},{"text":[{"text":"Aids auditors:","bold":true},{"text":" auditors analyse the trial balance before scrutinising the ledgers further."}]},{"text":[{"text":"Basis for preparing the final accounts:","bold":true},{"text":" the income statement (profit and loss account) and the balance sheet (statement of financial position) are prepared from it."}]},{"text":[{"text":"Offers confidence in the ledger:","bold":true},{"text":" a trial balance that agrees shows the ledger balances can be relied upon."}]}]},{"type":"paragraph","text":[{"text":"6 points on the importance of a trial balance","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It helps in checking the "},{"text":"arithmetical accuracy","bold":true},{"text":" of the ledger accounts."}]},{"text":[{"text":"It makes the preparation of the final accounts easy."}]},{"text":[{"text":"It helps in rectifying errors in the ledger accounts."}]},{"text":[{"text":"It helps in the preparation of the audit report."}]},{"text":[{"text":"It aids the preparation of budgets and decision making."}]},{"text":[{"text":"It helps the organisation make comparative analysis."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"If the totals do "},{"text":"not","bold":true},{"text":" agree, an error was made in one of three places: (1) "},{"text":"posting","bold":true},{"text":" transactions to the ledger, (2) "},{"text":"balancing","bold":true},{"text":" the ledger accounts, or (3) "},{"text":"transferring","bold":true},{"text":" the balances from the ledger to the trial balance (or adding up its columns)."}]},{"text":[{"text":"Limit:","bold":true},{"text":" a trial balance that agrees does "},{"text":"not","bold":true},{"text":" prove the books are free of errors. Six kinds of error leave it in agreement (Lesson 6.3)."}]},{"text":[{"text":"Trap: the best answer to \"a trial balance is used to...\" is "},{"text":"check the accuracy of postings to the ledger","bold":true},{"text":" (its arithmetical accuracy). It does "},{"text":"not correct","bold":true},{"text":" errors by itself, it does "},{"text":"not give details of transactions","bold":true},{"text":" (the journal and ledger do), and it detects only "},{"text":"some","bold":true},{"text":" errors."}]},{"text":[{"text":"Trap: a trial balance is a "},{"text":"list (statement)","bold":true},{"text":", not an account. Do not confuse it with the "},{"text":"journal","bold":true},{"text":" (a book of original entry), the "},{"text":"balance sheet","bold":true},{"text":" (reports financial position), a "},{"text":"chart of accounts","bold":true},{"text":" (a list of account names only), the "},{"text":"suspense account","bold":true},{"text":" (holds a difference temporarily) or the "},{"text":"trading","bold":true},{"text":" and "},{"text":"profit and loss accounts","bold":true},{"text":" (use some of the balances to work out profit)."}]},{"text":[{"text":"It is dated "},{"text":"\"as at\"","bold":true},{"text":" one day, because balances are taken at a point in time."}]}]}]},{"number":"6.2","title":"Preparing a trial balance","mustKnow":[{"type":"paragraph","text":[{"text":"Posting rules","bold":true},{"text":" (where each balance goes):"}]},{"type":"table","header":[[{"text":"Debit side"}],[{"text":"Credit side"}]],"rows":[[[{"text":"Assets","bold":true},{"text":" (cash, bank, plant, trade receivables (debtors), prepayments)"}],[{"text":"Liabilities","bold":true},{"text":" (trade payables (creditors), loans, accrued expenses)"}]],[[{"text":"Expenses","bold":true},{"text":" (all of them, e.g. salaries, rent, repairs)"}],[{"text":"Income","bold":true},{"text":" (sales, revenue, commission received, interest received)"}]],[[{"text":"Drawings","bold":true}],[{"text":"Capital","bold":true}]],[[{"text":"Purchases, returns inwards, discount allowed, opening inventory"}],[{"text":"Returns outwards, discount received, accumulated depreciation, provision for bad and doubtful debts"}]]]},{"type":"paragraph","text":[{"text":"Steps","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Balance off every ledger account; the figure you use is the "},{"text":"balance brought down (b/d)","bold":true},{"text":"."}]},{"text":[{"text":"List each account with a debit balance in the debit column and each with a credit balance in the credit column."}]},{"text":[{"text":"Total both columns. They must agree."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" Prepare an unadjusted trial balance from these ledger balances at 31 December 2023: cash ₦5,000; accounts receivable ₦8,000; accounts payable ₦7,000; salary payable ₦3,000; revenue ₦12,000; advertising expenses ₦11,000; plant ₦20,000; prepaid insurance ₦4,000; capital ₦27,500; repair expenses ₦1,500."}]},{"type":"paragraph","text":[{"text":"Trial balance as at 31 December 2023","bold":true}]},{"type":"table","header":[[{"text":"Account"}],[{"text":"Debit (₦)"}],[{"text":"Credit (₦)"}]],"rows":[[[{"text":"Capital"}],[],[{"text":"27,500"}]],[[{"text":"Cash"}],[{"text":"5,000"}],[]],[[{"text":"Accounts receivable"}],[{"text":"8,000"}],[]],[[{"text":"Accounts payable"}],[],[{"text":"7,000"}]],[[{"text":"Salary payable"}],[],[{"text":"3,000"}]],[[{"text":"Revenue"}],[],[{"text":"12,000"}]],[[{"text":"Advertising expenses"}],[{"text":"11,000"}],[]],[[{"text":"Plant"}],[{"text":"20,000"}],[]],[[{"text":"Prepaid insurance"}],[{"text":"4,000"}],[]],[[{"text":"Repair expenses"}],[{"text":"1,500"}],[]],[[{"text":"Total","bold":true}],[{"text":"49,500","bold":true}],[{"text":"49,500","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Why each goes where it does: cash, receivables, plant and prepaid insurance are "},{"text":"assets","bold":true},{"text":" (debit); advertising and repairs are "},{"text":"expenses","bold":true},{"text":" (debit); payables and salary payable are "},{"text":"liabilities","bold":true},{"text":" (credit); revenue is "},{"text":"income","bold":true},{"text":" (credit); capital is "},{"text":"credit","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"salary payable\" is a liability (credit), but \"salary expenses\" is an expense (debit). Read the word after the account name. Likewise \"accumulated depreciation\" is a credit, but \"depreciation expense\" is a debit; \"dividend\" (like drawings) is a debit."}]},{"text":[{"text":"Trap: "},{"text":"all expenses","bold":true},{"text":" sit on the "},{"text":"debit side","bold":true},{"text":", never on both sides."}]}]}]},{"number":"6.3","title":"The six errors that do not affect the agreement of the trial balance","mustKnow":[{"type":"paragraph","text":[{"text":"In each of these errors an equal debit and credit were still made, so the trial balance still agrees. It cannot reveal them."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Error of omission:","bold":true},{"text":" a transaction is "},{"text":"completely left out","bold":true},{"text":" of the books (neither side recorded)."}]},{"text":[{"text":"Error of commission:","bold":true},{"text":" an entry is made in the "},{"text":"wrong account of the same class","bold":true},{"text":", e.g. the wrong customer's account or the wrong expense account."}]},{"text":[{"text":"Error of principle:","bold":true},{"text":" an entry is made in the "},{"text":"wrong class of account","bold":true},{"text":", e.g. capital expenditure treated as revenue expenditure (a non-current asset debited to an expense or to purchases)."}]},{"text":[{"text":"Error of original entry:","bold":true},{"text":" the "},{"text":"wrong amount","bold":true},{"text":" is recorded in the book of original entry, so "},{"text":"both","bold":true},{"text":" the debit and the credit use the same wrong figure."}]},{"text":[{"text":"Error of complete reversal:","bold":true},{"text":" the correct accounts and amount are used, but the account that should be debited is "},{"text":"credited","bold":true},{"text":" and vice versa."}]},{"text":[{"text":"Compensating error:","bold":true},{"text":" two or more errors of the "},{"text":"same amount on opposite sides","bold":true},{"text":" cancel each other out."}]}]}],"explainMore":[{"type":"table","header":[[{"text":"Error"}],[{"text":"Example"}],[{"text":"Correcting journal entry"}]],"rows":[[[{"text":"Omission"}],[{"text":"Credit sale of ₦20,000 to Tunde not recorded at all"}],[{"text":"Dr Tunde ₦20,000; Cr Sales ₦20,000"}]],[[{"text":"Commission"}],[{"text":"₦15,000 received from Ade credited to Adams' account"}],[{"text":"Dr Adams ₦15,000; Cr Ade ₦15,000"}]],[[{"text":"Principle"}],[{"text":"Motor van bought for ₦500,000 debited to motor expenses"}],[{"text":"Dr Motor van ₦500,000; Cr Motor expenses ₦500,000"}]],[[{"text":"Original entry"}],[{"text":"Sales invoice to Kemi for ₦8,400 entered in the sales day book as ₦4,800"}],[{"text":"Dr Kemi ₦3,600; Cr Sales ₦3,600"}]],[[{"text":"Complete reversal"}],[{"text":"₦7,000 cash paid to supplier Musa: debited cash, credited Musa"}],[{"text":"Dr Musa ₦14,000; Cr Cash ₦14,000"}]],[[{"text":"Compensating"}],[{"text":"Rent account overcast by ₦1,000 and sales account overcast by ₦1,000"}],[{"text":"Dr Sales ₦1,000; Cr Rent ₦1,000"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap (reversal): the correction is "},{"text":"double","bold":true},{"text":" the amount. ₦7,000 must first cancel the wrong entry, then ₦7,000 more makes the right one."}]},{"text":[{"text":"Trap (original entry): correct only the "},{"text":"difference","bold":true},{"text":" (₦8,400 − ₦4,800 = ₦3,600). A "},{"text":"transposition","bold":true},{"text":" of digits (84 to 48) that is made in the day book and carried to both sides is an error of original entry."}]},{"text":[{"text":"Commission vs principle:","bold":true},{"text":" same class of account (customer to customer, expense to expense) = commission; different class (asset to expense) = principle. Commission does not change profit; principle does (the van wrongly made profit ₦500,000 lower)."}]},{"text":[{"text":"Posting the "},{"text":"same transaction twice","bold":true},{"text":" to both accounts (duplication) also leaves the trial balance in agreement."}]},{"text":[{"text":"None of these errors involve the suspense account when corrected."}]}]}]},{"number":"6.4","title":"Errors that affect agreement, and the suspense account","mustKnow":[{"type":"paragraph","text":[{"text":"These errors make the debit and credit totals "},{"text":"differ","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Single entry:","bold":true},{"text":" only one side of a transaction is posted."}]},{"text":[{"text":"Two debits or two credits:","bold":true},{"text":" both entries are posted to the same side."}]},{"text":[{"text":"Unequal amounts:","bold":true},{"text":" the debit and credit are posted with different figures (e.g. a transposition in one account only)."}]},{"text":[{"text":"Casting errors:","bold":true},{"text":" a ledger account is "},{"text":"undercast","bold":true},{"text":" (added too low) or "},{"text":"overcast","bold":true},{"text":" (added too high)."}]},{"text":[{"text":"Wrong balance:","bold":true},{"text":" an account is balanced off wrongly."}]},{"text":[{"text":"Trial balance errors:","bold":true},{"text":" a balance is left out of the trial balance, copied wrongly, put on the wrong side, or the trial balance columns are added wrongly."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Suspense account:","bold":true},{"text":" a temporary account opened to hold the difference on a trial balance that does not agree, until the errors are found and corrected."}]},{"text":[{"text":"Which side?","bold":true},{"text":" Put the difference on the "},{"text":"smaller","bold":true},{"text":" side. Debit total short = "},{"text":"debit","bold":true},{"text":" balance on suspense; credit total short = "},{"text":"credit","bold":true},{"text":" balance on suspense."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The suspense account lets work continue, but every effort must be made to find the errors. When all of them are corrected, the suspense account closes with "},{"text":"no balance","bold":true},{"text":"."}]},{"text":[{"text":"The test:","bold":true},{"text":" if an error affected the agreement of the trial balance, its correction "},{"text":"involves the suspense account","bold":true},{"text":"; if it did not (the six errors in Lesson 6.3), suspense is "},{"text":"not","bold":true},{"text":" used."}]},{"text":[{"text":"Example: debit total ₦77 less than credit total. Open suspense with a "},{"text":"debit","bold":true},{"text":" of ₦77 so both totals agree."}]},{"text":[{"text":"Trap: the suspense account is not an error type, and it does not list all balances. It only holds a difference."}]}]}]},{"number":"6.5","title":"Correcting errors with journal entries","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Errors are corrected "},{"text":"through the journal first","bold":true},{"text":", then posted to the ledger. Correction of errors is one of the uses of the (general) journal."}]},{"text":[{"text":"Each journal entry shows the date, the account debited, the account credited, the amounts and a "},{"text":"narration","bold":true},{"text":" explaining the error."}]},{"text":[{"text":"3-step method:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"What "},{"text":"was","bold":true},{"text":" recorded?"}]},{"text":[{"text":"What "},{"text":"should","bold":true},{"text":" have been recorded?"}]},{"text":[{"text":"Write the entry that turns step 1 into step 2. If only "},{"text":"one","bold":true},{"text":" account is wrong, the other side of the entry is "},{"text":"suspense","bold":true},{"text":"."}]}]}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" The trial balance of Adaeze Stores at 31 December 2025 had debit total ₦1,056,800 and credit total ₦1,050,000. The difference of ₦6,800 was credited to a suspense account (credit side was short). These errors were then found:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The purchases day book total of ₦63,500 was posted to the purchases account as ₦65,300."}]},{"text":[{"text":"The sales account was undercast by ₦10,000."}]},{"text":[{"text":"₦5,000 paid to Bayo, a supplier, was entered in the cash book but not in Bayo's account."}]},{"text":[{"text":"Repairs to the motor van, ₦8,000, were debited to the motor van account."}]},{"text":[{"text":"₦6,000 taken by the owner for private use was debited to wages."}]},{"text":[{"text":"A credit sale of ₦12,000 to Chika was omitted from the books."}]}]},{"type":"paragraph","text":[{"text":"Journal","bold":true}]},{"type":"table","header":[[{"text":"#"}],[{"text":"Account"}],[{"text":"Dr (₦)"}],[{"text":"Cr (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"Suspense"}],[{"text":"1,800"}],[]],[[],[{"text":"Purchases"}],[],[{"text":"1,800"}]],[[],[{"text":"(Purchases overstated by transposition; one side wrong)","italic":true}],[],[]],[[{"text":"2"}],[{"text":"Suspense"}],[{"text":"10,000"}],[]],[[],[{"text":"Sales"}],[],[{"text":"10,000"}]],[[],[{"text":"(Sales account undercast)","italic":true}],[],[]],[[{"text":"3"}],[{"text":"Trade payables (Bayo)"}],[{"text":"5,000"}],[]],[[],[{"text":"Suspense"}],[],[{"text":"5,000"}]],[[],[{"text":"(Payment to Bayo posted to cash book only)","italic":true}],[],[]],[[{"text":"4"}],[{"text":"Repairs"}],[{"text":"8,000"}],[]],[[],[{"text":"Motor van"}],[],[{"text":"8,000"}]],[[],[{"text":"(Error of principle: revenue expense debited to an asset)","italic":true}],[],[]],[[{"text":"5"}],[{"text":"Drawings"}],[{"text":"6,000"}],[]],[[],[{"text":"Wages"}],[],[{"text":"6,000"}]],[[],[{"text":"(Error of principle: private withdrawal debited to wages)","italic":true}],[],[]],[[{"text":"6"}],[{"text":"Trade receivables (Chika)"}],[{"text":"12,000"}],[]],[[],[{"text":"Sales"}],[],[{"text":"12,000"}]],[[],[{"text":"(Error of omission)","italic":true}],[],[]]]},{"type":"paragraph","text":[{"text":"Suspense account","bold":true}]},{"type":"table","header":[[{"text":"Dr"}],[{"text":"₦"}],[{"text":"Cr"}],[{"text":"₦"}]],"rows":[[[{"text":"Purchases"}],[{"text":"1,800"}],[{"text":"Difference per trial balance"}],[{"text":"6,800"}]],[[{"text":"Sales"}],[{"text":"10,000"}],[{"text":"Trade payables (Bayo)"}],[{"text":"5,000"}]],[[],[{"text":"11,800","bold":true}],[],[{"text":"11,800","bold":true}]]]},{"type":"paragraph","text":[{"text":"The suspense account clears to nil. Errors 4, 5 and 6 did not touch it because they did not affect agreement."}]},{"type":"paragraph","text":[{"text":"Corrected trial balance as at 31 December 2025","bold":true}]},{"type":"table","header":[[{"text":"Account"}],[{"text":"Before (₦)"}],[{"text":"Correction (₦)"}],[{"text":"Debit (₦)"}],[{"text":"Credit (₦)"}]],"rows":[[[{"text":"Premises"}],[{"text":"400,000 Dr"}],[],[{"text":"400,000"}],[]],[[{"text":"Motor van"}],[{"text":"158,000 Dr"}],[{"text":"−8,000"}],[{"text":"150,000"}],[]],[[{"text":"Trade receivables"}],[{"text":"48,000 Dr"}],[{"text":"+12,000"}],[{"text":"60,000"}],[]],[[{"text":"Purchases"}],[{"text":"301,800 Dr"}],[{"text":"−1,800"}],[{"text":"300,000"}],[]],[[{"text":"Wages"}],[{"text":"86,000 Dr"}],[{"text":"−6,000"}],[{"text":"80,000"}],[]],[[{"text":"Repairs"}],[{"text":"4,000 Dr"}],[{"text":"+8,000"}],[{"text":"12,000"}],[]],[[{"text":"Drawings"}],[{"text":"14,000 Dr"}],[{"text":"+6,000"}],[{"text":"20,000"}],[]],[[{"text":"Bank"}],[{"text":"45,000 Dr"}],[],[{"text":"45,000"}],[]],[[{"text":"Capital"}],[{"text":"532,000 Cr"}],[],[],[{"text":"532,000"}]],[[{"text":"Sales"}],[{"text":"458,000 Cr"}],[{"text":"+22,000"}],[],[{"text":"480,000"}]],[[{"text":"Trade payables"}],[{"text":"60,000 Cr"}],[{"text":"−5,000"}],[],[{"text":"55,000"}]],[[{"text":"Total","bold":true}],[],[],[{"text":"1,067,000","bold":true}],[{"text":"1,067,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Effect on net profit:","bold":true},{"text":" purchases down ₦1,800 (+), sales up ₦10,000 and ₦12,000 (+), repairs up ₦8,000 (−), wages down ₦6,000 (+). Net profit rises by "},{"text":"₦21,800","bold":true},{"text":". Error 3 affects only the balance sheet (payables); in error 5 only the wages side affects profit, while drawings reduce capital."}]},{"text":[{"text":"Trap: never \"correct\" by rubbing out or changing the wrong figure. Always make a new journal entry with a narration."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A trial balance is a list of all debit and credit balances from the ledger at a date; its totals must agree."}]},{"text":[{"text":"Main use: to check the arithmetical accuracy of postings to the ledger; it is also the basis of the final accounts."}]},{"text":[{"text":"Debit: assets, expenses, drawings. Credit: liabilities, income, capital."}]},{"text":[{"text":"Agreement does not prove accuracy: omission, commission, principle, original entry, complete reversal and compensating errors stay hidden."}]},{"text":[{"text":"Complete reversal is corrected at double the amount; original entry by the difference only."}]},{"text":[{"text":"One-sided errors, unequal amounts, casting errors and trial balance slips cause disagreement."}]},{"text":[{"text":"A suspense account holds the difference on the smaller side until the errors are found."}]},{"text":[{"text":"Correct errors by journal first; only errors that affected agreement involve suspense."}]}]}],"theory":{"itemId":"9337c72e-7039-5a1b-bae4-f70ef92747f3","question":[{"type":"paragraph","text":[{"text":"The debit total of a trial balance exceeds the credit total by ₦900. Two errors are found: (i) electricity of ₦2,100, correctly entered in the cash book, was posted to the electricity account as ₦1,200; (ii) discount received of ₦1,800 was entered in the supplier's account but omitted from the discount received account. Give the correcting journal entries and the suspense account."}]}]},"practice":[{"topic":"Trial balance and correction of errors","named":false}]}},{"itemId":"50c79096-4689-5593-9c8c-fc0eb33434cb","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"End-of-Year Adjustments","body":"What year-end adjustments are and why they are made; closing stock and drawings; accrued and prepaid expenses; accrued and prepaid (deferred) income; depreciation by straight-line, reducing-balance and sum-of-the-years'-digits methods, and disposal; bad debts, provision for bad and doubtful debts and provision for discount on debtors.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What year-end adjustments are and why they are made; closing stock and drawings; accrued and prepaid expenses; accrued and prepaid (deferred) income; depreciation by straight-line, reducing-balance and sum-of-the-years'-digits methods, and disposal; bad debts, provision for bad and doubtful debts and provision for discount on debtors."}],"lessons":[{"number":"7.1","title":"Meaning, reasons, types; closing stock and drawings","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"End-of-year adjustments:","bold":true},{"text":" amendments made in the books of account at the end of each financial period, affecting the profit and loss account (income statement) and the balance sheet (statement of financial position), so that the accounts show a "},{"text":"true view","bold":true},{"text":" of the organisation's transactions."}]},{"text":[{"text":"Reasons:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To provide for stock valuation at the year end."}]},{"text":[{"text":"To prepare the accounts in line with generally accepted accounting principles or concepts (accrual, matching, prudence)."}]},{"text":[{"text":"To record properly all income earned during the year."}]},{"text":[{"text":"To provide for depreciation of the organisation's fixed (non-current) assets."}]},{"text":[{"text":"To apply the double entry principle properly."}]}]}]},{"text":[{"text":"7 types of adjustment:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Closing stock."}]},{"text":[{"text":"Depreciation of assets."}]},{"text":[{"text":"Accrued and prepaid income."}]},{"text":[{"text":"Accrued and prepaid expenses."}]},{"text":[{"text":"Drawings by the owner."}]},{"text":[{"text":"Provision for discounts (on debtors and on creditors)."}]},{"text":[{"text":"Bad debts and provision for doubtful debts."}]}]}]},{"text":[{"text":"Closing stock (inventory):","bold":true},{"text":" unsold goods at the year end, valued at the lower of cost and net realisable value. Entry: "},{"text":"Dr Stock (inventory) account, Cr Trading account / cost of sales.","bold":true},{"text":" It reduces cost of sales and appears as a "},{"text":"current asset","bold":true},{"text":"."}]},{"text":[{"text":"Drawings:","bold":true},{"text":" anything the owner takes from the business for "},{"text":"personal","bold":true},{"text":" use: cash, goods, or a \"salary\" paid to a sole trader."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash: "},{"text":"Dr Drawings, Cr Cash/Bank.","bold":true}]},{"text":[{"text":"Goods at cost: "},{"text":"Dr Drawings, Cr Purchases.","bold":true}]},{"text":[{"text":"Drawings are deducted from capital in the balance sheet; they are "},{"text":"never","bold":true},{"text":" an expense."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: when options give both \"Dr inventory, Cr profit and loss\" and \"Dr inventory, Cr cost of sales\", choose "},{"text":"cost of sales","bold":true},{"text":": it names the exact figure reduced."}]},{"text":[{"text":"Worked example: during the year the owner took a ₦100,000 \"salary\", drew ₦10,000 cash for school fees and took goods costing ₦2,400; half the goods went to his children, half were gifts to long-standing customers."}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Drawings (₦)"}],[{"text":"Business expense (₦)"}]],"rows":[[[{"text":"Owner's salary"}],[{"text":"100,000"}],[]],[[{"text":"School fees"}],[{"text":"10,000"}],[]],[[{"text":"Goods for children"}],[{"text":"1,200"}],[]],[[{"text":"Gifts to customers"}],[],[{"text":"1,200"}]],[[{"text":"Total","bold":true}],[{"text":"111,200","bold":true}],[{"text":"1,200","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gifts to customers serve the business (advertising), so they are an expense; everything for the owner's private benefit is drawings."}]}]}]},{"number":"7.2","title":"Accrued and prepaid expenses","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accrual concept:","bold":true},{"text":" revenue and expenses are recognised when earned or incurred and shown in the profit and loss account of the period to which they relate, "},{"text":"not","bold":true},{"text":" when cash is paid or received."}]},{"text":[{"text":"Accrued expense (expense owing):","bold":true},{"text":" incurred but not yet paid at the year end. "},{"text":"Current liability.","bold":true},{"text":" Adjustment: "},{"text":"Dr Expense, Cr Accrued expense (liability).","bold":true},{"text":" No cash moves."}]},{"text":[{"text":"Prepaid expense (payment in advance):","bold":true},{"text":" paid this year for a future period. "},{"text":"Current asset","bold":true},{"text":" (a deferred expense). Adjustment: "},{"text":"Dr Prepaid expense (asset), Cr Expense.","bold":true}]},{"text":[{"text":"Formula (charge to profit and loss):","bold":true}],"blocks":[{"type":"paragraph","text":[{"text":"Expense = cash paid − opening accrual + closing accrual + opening prepayment − closing prepayment"}]}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Effect on P&L charge"}],[{"text":"Balance sheet"}]],"rows":[[[{"text":"Closing accrual"}],[{"text":"Add"}],[{"text":"Current liability"}]],[[{"text":"Closing prepayment"}],[{"text":"Deduct"}],[{"text":"Current asset"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order of events:","bold":true},{"text":" accrued expense: "},{"text":"incurred first","bold":true},{"text":", paid later. Prepaid (deferred) expense: "},{"text":"paid first","bold":true},{"text":", incurred later as the benefit is used."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 1 (accrual): motor expenses paid ₦108,000; owing at the start ₦30,000; owing at the end ₦20,700. Charge = 108,000 − 30,000 + 20,700 = "},{"text":"₦98,700","bold":true},{"text":"."}],"blocks":[{"type":"table","header":[[{"text":"Motor expenses a/c"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Cash"}],[{"text":"108,000"}],[{"text":"Balance b/d (owing)"}],[{"text":"30,000"}]],[[{"text":"Balance c/d (owing)"}],[{"text":"20,700"}],[{"text":"Profit and loss"}],[{"text":"98,700"}]],[[],[{"text":"128,700","bold":true}],[],[{"text":"128,700","bold":true}]]]},{"type":"paragraph","text":[{"text":"The ₦20,700 comes down as a "},{"text":"credit","bold":true},{"text":" balance: a current liability."}]}]},{"text":[{"text":"Worked example 2 (prepayment): insurance prepaid at the start ₦7,400; paid ₦50,000; prepaid at the end ₦25,000. Charge = 7,400 + 50,000 − 25,000 = "},{"text":"₦32,400","bold":true},{"text":"."}],"blocks":[{"type":"table","header":[[{"text":"Insurance a/c"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Balance b/d (prepaid)"}],[{"text":"7,400"}],[{"text":"Profit and loss"}],[{"text":"32,400"}]],[[{"text":"Cash"}],[{"text":"50,000"}],[{"text":"Balance c/d (prepaid)"}],[{"text":"25,000"}]],[[],[{"text":"57,400","bold":true}],[],[{"text":"57,400","bold":true}]]]},{"type":"paragraph","text":[{"text":"The ₦25,000 comes down as a "},{"text":"debit","bold":true},{"text":" balance: a current asset. It is the "},{"text":"unexpired","bold":true},{"text":" portion of the premium; the expired portion is the expense."}]}]},{"text":[{"text":"Quick check: rent prepaid at the start ₦1,000, paid ₦8,000, owing at the end ₦600: rent for the year = 1,000 + 8,000 + 600 = "},{"text":"₦9,600","bold":true},{"text":". Rent ₦6,000 with ₦500 more to accrue = ₦6,500; insurance ₦1,500 with ₦250 prepaid = ₦1,250."}]},{"text":[{"text":"Effect of omitting an accrual:","bold":true},{"text":" expenses too low, so "},{"text":"profit overstated","bold":true},{"text":" and "},{"text":"liabilities understated","bold":true},{"text":" by the same amount (₦1,800 of unpaid wages left out overstates profit by ₦1,800)."}]},{"text":[{"text":"Using up a prepayment: "},{"text":"Dr Insurance expense, Cr Prepaid insurance.","bold":true},{"text":" Prepaid assets and expenses both have "},{"text":"debit","bold":true},{"text":" normal balances, so a "},{"text":"credit","bold":true},{"text":" decreases them. Cash is never part of an accrual or prepayment adjustment."}]},{"text":[{"text":"Reversing entry:","bold":true},{"text":" made on the first day of the new period to cancel an accrual-type adjustment from the previous period, so the later payment or receipt can be recorded in the normal way. (A reconciliation compares two records; it removes nothing.)"}]},{"text":[{"text":"Trap: prepaid rent in a trial balance is an "},{"text":"asset (deferred expense)","bold":true},{"text":", not deferred income."}]}]}]},{"number":"7.3","title":"Accrued and prepaid income","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accrued income (outstanding income, income receivable):","bold":true},{"text":" earned during the period but not received by the year end, e.g. rent receivable, commission receivable, interest receivable. "},{"text":"Current asset.","bold":true},{"text":" Adjustment: "},{"text":"Dr Income receivable (asset), Cr Income account.","bold":true}]},{"text":[{"text":"Prepaid income (income received in advance; deferred or unearned revenue):","bold":true},{"text":" received this period but relating to the next, e.g. rent received in advance, fees received before the work is done. "},{"text":"Current liability","bold":true},{"text":": the business owes the customer goods or services. Adjustment: "},{"text":"Dr Income account, Cr Income received in advance (liability).","bold":true}]},{"text":[{"text":"Formula (income credited to profit and loss):","bold":true}],"blocks":[{"type":"paragraph","text":[{"text":"Income = cash received − opening accrued + closing accrued + opening in advance − closing in advance"}]}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Effect on income"}],[{"text":"Balance sheet"}]],"rows":[[[{"text":"Closing accrued income"}],[{"text":"Add"}],[{"text":"Current asset"}]],[[{"text":"Closing income in advance"}],[{"text":"Deduct"}],[{"text":"Current liability"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order of events:","bold":true},{"text":" accrued income: "},{"text":"earned first","bold":true},{"text":", received later. Deferred (unearned) income: "},{"text":"cash received first","bold":true},{"text":", earned later."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 3 (accrued income): commission received ₦58,000; owing to the business at the start ₦18,000; owing at the end ₦10,450. Income = 58,000 − 18,000 + 10,450 = "},{"text":"₦50,450","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Commission receivable a/c"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Balance b/d (owing)"}],[{"text":"18,000"}],[{"text":"Cash"}],[{"text":"58,000"}]],[[{"text":"Profit and loss"}],[{"text":"50,450"}],[{"text":"Balance c/d (owing)"}],[{"text":"10,450"}]],[[],[{"text":"68,450","bold":true}],[],[{"text":"68,450","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 4 (income in advance): rent received in cash ₦120,000; received in advance at the start ₦10,000; received in advance at the end ₦25,000. Income = 120,000 + 10,000 − 25,000 = "},{"text":"₦105,000","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Rent received a/c"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Profit and loss"}],[{"text":"105,000"}],[{"text":"Balance b/d (in advance)"}],[{"text":"10,000"}]],[[{"text":"Balance c/d (in advance)"}],[{"text":"25,000"}],[{"text":"Bank"}],[{"text":"120,000"}]],[[],[{"text":"130,000","bold":true}],[],[{"text":"130,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"When unearned revenue is later earned: "},{"text":"Dr Unearned (deferred) revenue, Cr Fees earned (revenue).","bold":true},{"text":" No cash; the cash came in earlier."}]},{"text":[{"text":"A bank's accrued interest: "},{"text":"Dr Interest receivable, Cr Interest income.","bold":true},{"text":" The borrower's accrued interest: "},{"text":"Dr Interest expense, Cr Interest payable.","bold":true}]},{"text":[{"text":"Trap: \"rent received in advance\" is the only "},{"text":"liability","bold":true},{"text":" among prepaid rent, prepaid insurance, rent received in advance and accrued rent received; the other three are assets."}]}]}]},{"number":"7.4","title":"Depreciation and disposal of fixed assets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Depreciation:","bold":true},{"text":" the systematic allocation of the cost of a fixed (non-current) asset, less its residual value, over its useful life, charged as an expense each year. It is "},{"text":"not","bold":true},{"text":" a fund for replacing the asset."}]},{"text":[{"text":"Three factors used:","bold":true},{"text":" (1) "},{"text":"cost","bold":true},{"text":", (2) estimated "},{"text":"residual (salvage, scrap) value","bold":true},{"text":", (3) expected "},{"text":"useful life","bold":true},{"text":". "},{"text":"Repairs are ignored","bold":true},{"text":": they are revenue expenditure charged straight to profit and loss."}]},{"text":[{"text":"Formulas:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Straight-line:","bold":true},{"text":" annual charge = (cost − residual value) ÷ useful life. Same charge every year. When a question gives cost, residual value and useful life but "},{"text":"names no method, use straight-line","bold":true},{"text":". Rearranged: useful life = (cost − residual value) ÷ annual charge."}]},{"text":[{"text":"Reducing balance:","bold":true},{"text":" annual charge = rate % × net book value at the start of the year. Charge falls each year. The rate is applied to NBV; residual value is not deducted first (it only sets the rate: rate = 1 − (residual ÷ cost)^(1/n))."}]},{"text":[{"text":"Sum of the years' digits:","bold":true},{"text":" sum of digits for n years = n(n + 1) ÷ 2. Year charge = (remaining years ÷ sum of digits) × (cost − residual)."}]}]}]},{"text":[{"text":"Net book value (NBV, carrying amount)","bold":true},{"text":" = cost − accumulated depreciation (provision for depreciation)."}]},{"text":[{"text":"Entry each year:","bold":true},{"text":" "},{"text":"Dr Depreciation (profit and loss), Cr Provision for (accumulated) depreciation.","bold":true}]},{"text":[{"text":"Yearly method:","bold":true},{"text":" a full year's depreciation in the year of purchase and "},{"text":"none","bold":true},{"text":" in the year of sale. (The alternative is time-apportioning by months.)"}]},{"text":[{"text":"Disposal:","bold":true},{"text":" profit or loss = proceeds − NBV at disposal. A "},{"text":"gain","bold":true},{"text":" is credited to the income statement; a "},{"text":"loss","bold":true},{"text":" is debited."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 5 (straight-line): vehicle cost ₦170,000, residual ₦20,000, life 5 years. Charge = 150,000 ÷ 5 = ₦30,000 a year; accumulated depreciation after 3 years = "},{"text":"₦90,000","bold":true},{"text":"; NBV = ₦80,000. (₦102,000 forgets the residual; ₦150,000 is all 5 years.) Check: cost ₦360,000, residual ₦12,000, charge ₦69,600: life = 348,000 ÷ 69,600 = "},{"text":"5 years","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 6 (reducing balance, 20%): cost ₦200,000."}],"blocks":[{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening NBV (₦)"}],[{"text":"Charge 20% (₦)"}],[{"text":"Closing NBV (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"200,000"}],[{"text":"40,000"}],[{"text":"160,000"}]],[[{"text":"2"}],[{"text":"160,000"}],[{"text":"32,000"}],[{"text":"128,000"}]],[[{"text":"3"}],[{"text":"128,000"}],[{"text":"25,600"}],[{"text":"102,400"}]]]},{"type":"paragraph","text":[{"text":"Accumulated depreciation after 3 years = ₦97,600."}]}]},{"text":[{"text":"Worked example 7 (sum of the years' digits): cost ₦100,000, life 5 years, residual nil. Sum = 5 × 6 ÷ 2 = 15. Charges: 5/15 = "},{"text":"₦33,333.33","bold":true},{"text":", 4/15 = ₦26,666.67, 3/15 = ₦20,000, 2/15 = ₦13,333.33, 1/15 = ₦6,666.67; total ₦100,000. (₦20,000 a year would be straight-line.)"}]},{"text":[{"text":"Disposal entries:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Transfer cost: "},{"text":"Dr Disposal, Cr Asset account.","bold":true}]},{"text":[{"text":"Transfer accumulated depreciation: "},{"text":"Dr Provision for depreciation, Cr Disposal.","bold":true}]},{"text":[{"text":"Proceeds: "},{"text":"Dr Bank, Cr Disposal.","bold":true}]},{"text":[{"text":"Balance = gain (Dr Disposal, Cr P&L) or loss (Dr P&L, Cr Disposal)."}]}]}]},{"text":[{"text":"Worked example 8: machine cost ₦500,000, accumulated depreciation ₦300,000 (NBV ₦200,000), sold for a cheque of ₦150,000. Loss = 150,000 − 200,000 = "},{"text":"₦50,000","bold":true},{"text":"."}],"blocks":[{"type":"table","header":[[{"text":"Machinery disposal a/c"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Machinery (cost)"}],[{"text":"500,000"}],[{"text":"Provision for depreciation"}],[{"text":"300,000"}]],[[],[],[{"text":"Bank (proceeds)"}],[{"text":"150,000"}]],[[],[],[{"text":"Profit and loss (loss)"}],[{"text":"50,000"}]],[[],[{"text":"500,000","bold":true}],[],[{"text":"500,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Had the proceeds been ₦230,000, the gain of ₦30,000 would be debited in the disposal account and "},{"text":"credited","bold":true},{"text":" to the income statement."}]}]},{"text":[{"text":"Working backwards: cost ₦100,000 with NBV ₦40,000 means depreciation provided on the asset sold = "},{"text":"₦60,000","bold":true},{"text":"."}]},{"text":[{"text":"Trap: if a trial balance shows cost ₦100,000 and provision ₦20,000, and this year's charge is ₦2,000, the balance sheet NBV = 100,000 − 20,000 − 2,000 = "},{"text":"₦78,000","bold":true},{"text":". The trial balance provision is "},{"text":"before","bold":true},{"text":" this year's charge."}]},{"text":[{"text":"Reducing balance on disposal: van cost ₦20,000, 20% for 3 years: NBV = 20,000 × 0.8³ = ₦10,240; sold for ₦18,000, profit = "},{"text":"₦7,760","bold":true},{"text":"."}]},{"text":[{"text":"Provision for depreciation is a "},{"text":"contra asset","bold":true},{"text":": a credit balance deducted from cost, increased by a "},{"text":"credit","bold":true},{"text":"."}]}]}]},{"number":"7.5","title":"Bad debts and provisions on debtors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bad debt:","bold":true},{"text":" a debt that will not be paid. Write it off: "},{"text":"Dr Bad debts (P&L), Cr Debtor.","bold":true}]},{"text":[{"text":"Bad debt recovered:","bold":true},{"text":" reinstate the debt ("},{"text":"Dr Debtor, Cr Bad debts recovered/Bad debts","bold":true},{"text":"), then record the cash ("},{"text":"Dr Bank, Cr Debtor","bold":true},{"text":"). The recovery is income."}]},{"text":[{"text":"Provision for bad and doubtful debts (allowance for receivables):","bold":true},{"text":" an estimate of debts that "},{"text":"may","bold":true},{"text":" not be paid, usually a % of debtors "},{"text":"after","bold":true},{"text":" writing off bad debts. Based on "},{"text":"prudence","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Only the "},{"text":"change","bold":true},{"text":" goes to profit and loss. Increase: "},{"text":"Dr P&L, Cr Provision.","bold":true},{"text":" Decrease: "},{"text":"Dr Provision, Cr P&L","bold":true},{"text":" (a gain)."}]},{"text":[{"text":"P&L charge","bold":true},{"text":" = bad debts written off + (new provision − old provision)."}]},{"text":[{"text":"Balance sheet:","bold":true},{"text":" debtors − provision = net debtors (net realisable value)."}]}]}]},{"text":[{"text":"Provision for discount on debtors:","bold":true},{"text":" a % of debtors "},{"text":"after","bold":true},{"text":" deducting the provision for doubtful debts. Recorded like the doubtful-debts provision. (A provision for discount on creditors is the mirror image: it reduces creditors and is a gain.)"}]},{"text":[{"text":"Provisions for doubtful debts and accumulated depreciation are "},{"text":"contra asset","bold":true},{"text":" accounts with normal "},{"text":"credit","bold":true},{"text":" balances; a "},{"text":"credit","bold":true},{"text":" increases them. They are not liabilities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 9: debtors in the trial balance ₦410,000; bad debts to write off ₦10,000; old provision ₦15,000; new provision 5% of debtors; provision for discount 2%."}]}]},{"type":"table","header":[[{"text":"Step"}],[{"text":"Working"}],[{"text":"₦"}]],"rows":[[[{"text":"Debtors after write-off"}],[{"text":"410,000 − 10,000"}],[{"text":"400,000"}]],[[{"text":"New provision (5%)"}],[{"text":"5% × 400,000"}],[{"text":"20,000"}]],[[{"text":"Increase in provision"}],[{"text":"20,000 − 15,000"}],[{"text":"5,000"}]],[[{"text":"P&L charge (bad and doubtful)"}],[{"text":"10,000 + 5,000"}],[{"text":"15,000"}]],[[{"text":"Provision for discount (2%)"}],[{"text":"2% × (400,000 − 20,000)"}],[{"text":"7,600"}]],[[{"text":"Net debtors in balance sheet"}],[{"text":"400,000 − 20,000 − 7,600"}],[{"text":"372,400"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Quick checks:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Debtors ₦2,500,000, provision rising from ₦500,000 to ₦750,000: P&L charge = "},{"text":"₦250,000","bold":true},{"text":", not ₦750,000."}]},{"text":[{"text":"Bad debts ₦3,000, provision rising from ₦3,500 to ₦4,000: P&L debit = 3,000 + 500 = "},{"text":"₦3,500","bold":true},{"text":"."}]},{"text":[{"text":"Debtors ₦100,000, provision ₦70,000: net = "},{"text":"₦30,000","bold":true},{"text":"."}]},{"text":[{"text":"Debtors ₦30,000; 5% doubtful = ₦1,500; 2% discount on ₦28,500 = ₦570; net = "},{"text":"₦27,930","bold":true},{"text":" (₦27,900 wrongly takes 2% of the full ₦30,000)."}]}]}]},{"text":[{"text":"Trap: never charge the whole new provision; the old balance was charged in earlier years."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjustments make the accounts show a true view; 7 types: closing stock, depreciation, accrued/prepaid income, accrued/prepaid expenses, drawings, provision for discounts, bad debts and provisions."}]},{"text":[{"text":"Closing stock: Dr Stock, Cr cost of sales (trading account). Goods taken by the owner: Dr Drawings, Cr Purchases."}]},{"text":[{"text":"Accrued expense = current liability (add to expense); prepaid expense = current asset (deduct)."}]},{"text":[{"text":"Accrued income = current asset (add to income); income in advance (deferred/unearned revenue) = current liability (deduct)."}]},{"text":[{"text":"Expense = paid − opening accrual + closing accrual + opening prepayment − closing prepayment."}]},{"text":[{"text":"Straight-line = (cost − residual) ÷ life; reducing balance = rate × NBV; SYD year 1 = n ÷ [n(n+1)/2] × (cost − residual)."}]},{"text":[{"text":"NBV = cost − accumulated depreciation; disposal gain = proceeds − NBV, credited to the income statement."}]},{"text":[{"text":"P&L charge for debts = bad debts + increase in provision; discount provision is on debtors after the doubtful-debts provision."}]}]}],"theory":{"itemId":"3a084f8a-6765-5889-bce3-75ecfebfe436","question":[{"type":"paragraph","text":[{"text":"On 1 January rates prepaid were ₦4,000. During the year ₦30,000 was paid. At 31 December rates of ₦6,000 were owing. Calculate the rates charge for the year and state how the ₦6,000 appears in the balance sheet."}]}]},"practice":[{"topic":"Accruals, prepayments and other adjustments","named":true},{"topic":"Depreciation of non-current assets","named":true},{"topic":"Bad debts and doubtful debt provisions","named":true}]}},{"itemId":"42fd2a99-51e2-580d-9bf7-d7ca043cffec","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Final accounts of a sole trader","body":"The trading account, profit and loss account (income statement) and balance sheet (statement of financial position); cost of sales, gross profit and net profit; carriage, returns and drawings; current and non-current items; working capital; preparing final accounts from a trial balance with adjustments.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The trading account, profit and loss account (income statement) and balance sheet (statement of financial position); cost of sales, gross profit and net profit; carriage, returns and drawings; current and non-current items; working capital; preparing final accounts from a trial balance with adjustments."}],"lessons":[{"number":"8.1","title":"The final accounts and what each one shows","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Final accounts:","bold":true},{"text":" the statements prepared at the end of a period from the trial balance (after end-of-year adjustments) to show the result and position of the business."}]},{"text":[{"text":"3 final accounts of a sole trader:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Trading account:","bold":true},{"text":" compares net sales with the cost of the goods sold to find "},{"text":"gross profit","bold":true},{"text":"."}]},{"text":[{"text":"Profit and loss account (income statement):","bold":true},{"text":" takes gross profit, adds other income, deducts expenses to find "},{"text":"net profit","bold":true},{"text":" (or net loss). It reports the part of the change in owner's equity that comes from "},{"text":"revenues and expenses","bold":true},{"text":" in the period."}]},{"text":[{"text":"Balance sheet (statement of financial position):","bold":true},{"text":" lists assets, liabilities and capital to show the "},{"text":"financial position at a date","bold":true},{"text":". Its structure follows the accounting equation "},{"text":"Assets = Liabilities + Capital (equity)","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Trading, profit and loss account"}],[{"text":"Balance sheet"}]],"rows":[[[{"text":"Covers"}],[{"text":"A "},{"text":"period","bold":true},{"text":" (\"for the year ended 31 December\")"}],[{"text":"One "},{"text":"date","bold":true},{"text":" (\"as at 31 December\")"}]],[[{"text":"Shows"}],[{"text":"Performance: gross and net profit"}],[{"text":"Position: assets, liabilities, capital"}]],[[{"text":"Items"}],[{"text":"Revenue and expense (nominal) accounts"}],[{"text":"Asset, liability and capital (real and personal) accounts"}]],[[{"text":"After posting"}],[{"text":"Accounts are closed off"}],[{"text":"Balances are carried forward"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The trading account and the profit and loss account are usually presented together as one statement: the "},{"text":"trading, profit and loss account for the year ended ...","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the trial balance also balances, but it lists every ledger balance, including income and expenses. It is a check on arithmetic, "},{"text":"not","bold":true},{"text":" a final account. A cash flow statement shows cash movements, not the equation."}]},{"text":[{"text":"Income statement headings:","bold":true},{"text":" revenue (sales), cost of sales, gross profit, distribution (selling) costs, administrative expenses, operating profit or loss. \"Trading account\" is the bookkeeping account used to find gross profit; it is "},{"text":"not","bold":true},{"text":" a reporting heading of the statement."}]},{"text":[{"text":"Where net profit goes:","bold":true},{"text":" in a sole trader's books, net profit is added to "},{"text":"capital","bold":true},{"text":" (a net loss is deducted). In a company (corporation), net income is closed to "},{"text":"retained earnings","bold":true},{"text":", the part of shareholders' (stockholders') equity that holds profits kept in the business; dividends are paid out of it."}]}]}]},{"number":"8.2","title":"The trading account, cost of sales and gross profit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net sales (turnover)","bold":true},{"text":" = sales − returns inwards (sales returns)."}]},{"text":[{"text":"Net purchases","bold":true},{"text":" = purchases + carriage inwards − returns outwards (purchases returns)."}]},{"text":[{"text":"Cost of sales (cost of goods sold)","bold":true},{"text":" = opening stock + net purchases − closing stock."}]},{"text":[{"text":"Cost of goods available for sale","bold":true},{"text":" = opening stock + net purchases."}]},{"text":[{"text":"Gross profit","bold":true},{"text":" = net sales − cost of sales. If cost of sales is bigger, the result is a "},{"text":"gross loss","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Where the trading items go","bold":true}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Treatment"}]],"rows":[[[{"text":"Returns inwards (sales returns)"}],[{"text":"Deduct from "},{"text":"sales","bold":true}]],[[{"text":"Returns outwards (purchases returns)"}],[{"text":"Deduct from "},{"text":"purchases","bold":true}]],[[{"text":"Carriage inwards (on goods bought)"}],[{"text":"Add","bold":true},{"text":" to purchases (part of cost of sales)"}]],[[{"text":"Carriage outwards (on goods sold)"}],[{"text":"Expense","bold":true},{"text":" in the profit and loss account (selling cost)"}]],[[{"text":"Wages to get goods ready for sale (direct wages)"}],[{"text":"Add to cost of sales when the question places them there"}]],[[{"text":"Goods taken by the owner"}],[{"text":"Dr Drawings, Cr Purchases (at "},{"text":"cost","bold":true},{"text":"); never a sale"}]],[[{"text":"Closing stock"}],[{"text":"Deduct in cost of sales; current asset in the balance sheet"}]]]},{"type":"paragraph","text":[{"text":"Gross profit percentages","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Margin","bold":true},{"text":" = gross profit ÷ sales × 100. "},{"text":"Mark-up","bold":true},{"text":" = gross profit ÷ cost of sales × 100."}]},{"text":[{"text":"A 25% margin means cost is 75% of sales, so mark-up = 25/75 = 33⅓%."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Layout (vertical)","bold":true},{"text":": Kola's trading account for the year ended 31 December 2025"}]},{"type":"table","header":[[],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Sales"}],[],[{"text":"820,000"}]],[[{"text":"Less: returns inwards"}],[],[{"text":"(20,000)"}]],[[{"text":"Net sales"}],[],[{"text":"800,000"}]],[[{"text":"Opening stock"}],[{"text":"90,000"}],[]],[[{"text":"Purchases"}],[{"text":"500,000"}],[]],[[{"text":"Add: carriage inwards"}],[{"text":"15,000"}],[]],[[{"text":"Less: returns outwards"}],[{"text":"(25,000)"}],[]],[[{"text":"Cost of goods available for sale"}],[{"text":"580,000"}],[]],[[{"text":"Less: closing stock"}],[{"text":"(100,000)"}],[]],[[{"text":"Cost of sales"}],[],[{"text":"(480,000)"}]],[[{"text":"Gross profit","bold":true}],[],[{"text":"320,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Margin = 320,000 ÷ 800,000 = 40%; mark-up = 320,000 ÷ 480,000 = 66⅔%."}]},{"type":"paragraph","text":[{"text":"In the horizontal (T) form, opening stock, purchases, carriage inwards and gross profit sit on the "},{"text":"debit","bold":true},{"text":" side; sales and closing stock on the "},{"text":"credit","bold":true},{"text":" side, with returns shown as deductions from purchases and sales."}]},{"type":"paragraph","text":[{"text":"Quick computations exams set","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Opening stock ₦340,000, purchases ₦900,000, carriage inwards ₦100,000, carriage outwards ₦150,000, closing stock ₦420,000. Cost of goods sold = 340,000 + 900,000 + 100,000 − 420,000 = "},{"text":"₦920,000","bold":true},{"text":". Carriage outwards is ignored (it is a P&L expense)."}]},{"text":[{"text":"Sales ₦8,200, opening stock ₦1,300, purchases ₦6,400, carriage inwards ₦200, closing stock ₦900. Cost of goods sold = 1,300 + 6,400 + 200 − 900 = "},{"text":"₦7,000","bold":true},{"text":". Sales never enter cost of goods sold."}]},{"text":[{"text":"Opening stock ₦8,500, purchases ₦30,700, wages ₦4,800, returns inwards ₦5,200, closing stock ₦9,000. Cost of goods sold = 8,500 + 30,700 + 4,800 − 9,000 = "},{"text":"₦35,000","bold":true},{"text":". Returns inwards belong to sales, not cost of goods sold."}]},{"text":[{"text":"Purchases ₦90,000, freight on them ₦6,000, unsold goods ₦12,000, sales ₦120,000. Cost of goods sold = ₦84,000; gross profit = "},{"text":"₦36,000","bold":true},{"text":". Freight inwards is carriage inwards."}]},{"text":[{"text":"Closing stock ₦1,000 higher than opening, net sales ₦25,000, purchases ₦14,000. Cost of goods sold = 14,000 − 1,000 = ₦13,000; gross profit = ₦12,000 = "},{"text":"48%","bold":true},{"text":" of net sales."}]}]},{"type":"paragraph","text":[{"text":"Working backwards","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Margin 20% of sales, cost of goods ₦120,000: sales = 120,000 ÷ 0.8 = ₦150,000; gross profit = "},{"text":"₦30,000","bold":true},{"text":" (not 20% of cost)."}]},{"text":[{"text":"Find closing stock: opening ₦990,000, purchases ₦3,740,000, carriage inwards ₦22,000, sales ₦5,280,000, margin 25%. Cost of sales = 75% × 5,280,000 = ₦3,960,000. Closing stock = 990,000 + 3,740,000 + 22,000 − 3,960,000 = "},{"text":"₦792,000","bold":true},{"text":"."}]},{"text":[{"text":"Sales ₦300,000, margin 20%, purchases ₦240,000, opening stock ₦20,000. Cost of sales = ₦240,000, so closing stock = 20,000 + 240,000 − 240,000 = "},{"text":"₦20,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Errors and gross profit","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Closing stock "},{"text":"overstated","bold":true},{"text":" → cost of sales too low → gross profit "},{"text":"overstated","bold":true},{"text":"."}]},{"text":[{"text":"Opening stock, purchases or carriage inwards "},{"text":"overstated","bold":true},{"text":" → cost of sales too high → gross profit "},{"text":"understated","bold":true},{"text":"."}]},{"text":[{"text":"Contra (reduction) accounts:","bold":true},{"text":" returns inwards reduce sales; returns outwards reduce purchases; accumulated depreciation and provision for bad and doubtful debts reduce assets. "},{"text":"Carriage inwards is not","bold":true},{"text":" a contra account; it adds to cost."}]}]}]},{"number":"8.3","title":"The profit and loss account and net profit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net profit","bold":true},{"text":" = gross profit + other income − expenses. If expenses exceed gross profit plus other income, the result is a "},{"text":"net loss","bold":true},{"text":"."}]},{"text":[{"text":"Other income (credit side):","bold":true},{"text":" discount received, commission received, rent received, interest received, profit on disposal, decrease in provision for bad debts."}]},{"text":[{"text":"Expenses (debit side):","bold":true},{"text":" salaries and wages, rent and rates, insurance, lighting and heating, carriage outwards, advertising, postage, stationery, general expenses, discount allowed, bad debts, increase in provision for bad debts, provision for discount on debtors, depreciation, loan interest, loss on disposal."}]},{"text":[{"text":"Drawings are not an expense.","bold":true},{"text":" Cash or goods taken by the owner are deducted from "},{"text":"capital","bold":true},{"text":" in the balance sheet, so they never reduce net profit."}]}]},{"type":"paragraph","text":[{"text":"How each adjustment hits both statements","bold":true}]},{"type":"table","header":[[{"text":"Adjustment"}],[{"text":"Profit and loss account"}],[{"text":"Balance sheet"}]],"rows":[[[{"text":"Closing stock"}],[{"text":"Deducted in cost of sales"}],[{"text":"Current asset"}]],[[{"text":"Accrued (owing) expense"}],[{"text":"Add to the expense"}],[{"text":"Current liability"}]],[[{"text":"Prepaid expense"}],[{"text":"Deduct from the expense"}],[{"text":"Current asset"}]],[[{"text":"Accrued income (in arrears)"}],[{"text":"Add to the income"}],[{"text":"Current asset"}]],[[{"text":"Income received in advance"}],[{"text":"Deduct from the income"}],[{"text":"Current liability"}]],[[{"text":"Depreciation for the year"}],[{"text":"Expense"}],[{"text":"Added to accumulated depreciation; NBV = cost − accumulated depreciation"}]],[[{"text":"Bad debts written off"}],[{"text":"Expense"}],[{"text":"Deduct from debtors"}]],[[{"text":"Provision for bad debts"}],[{"text":"Only the "},{"text":"increase","bold":true},{"text":" is an expense (a decrease is income)"}],[{"text":"Full new provision deducted from debtors"}]],[[{"text":"Goods taken by owner"}],[{"text":"Reduce purchases"}],[{"text":"Add to drawings"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Increase in provision:","bold":true},{"text":" debtors after write-off ₦400,000, provision 5% = ₦20,000, old provision ₦15,000. Charge only ₦5,000 to profit and loss; show debtors ₦400,000 − ₦20,000 = ₦380,000."}]},{"text":[{"text":"Provision for discount on debtors","bold":true},{"text":" is worked on debtors "},{"text":"after","bold":true},{"text":" deducting the provision for bad debts; it is charged to profit and loss and also deducted from debtors."}]},{"text":[{"text":"Drawings of goods:","bold":true},{"text":" the owner takes goods costing ₦15,000. Dr Drawings ₦15,000, Cr Purchases ₦15,000. Purchases in the trading account fall by ₦15,000 and drawings in the balance sheet rise by ₦15,000."}]},{"text":[{"text":"Trap:","bold":true},{"text":" carriage outwards, discount allowed and bad debts are profit and loss expenses, not trading items. Discount received is income, not a reduction of purchases."}]}]}]},{"number":"8.4","title":"The balance sheet","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Non-current (fixed) assets:","bold":true},{"text":" held for use over more than one year, not for resale."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tangible:","bold":true},{"text":" land and buildings, plant and machinery, motor vehicles, furniture and fittings, equipment. Shown at cost less accumulated depreciation (net book value)."}]},{"text":[{"text":"Intangible:","bold":true},{"text":" long-term assets with "},{"text":"no physical existence","bold":true},{"text":" whose value lies in rights: goodwill, patents, trademarks, brands."}]},{"text":[{"text":"Long-term investments","bold":true},{"text":" are shown separately."}]}]}]},{"text":[{"text":"Current assets:","bold":true},{"text":" cash or items expected to be turned into cash or used "},{"text":"within one year","bold":true},{"text":": stock (inventory), debtors less provision (trade receivables), prepayments, accrued income, cash at bank, cash in hand."}]},{"text":[{"text":"Current liabilities:","bold":true},{"text":" due within one year: creditors (trade payables), accrued expenses, income received in advance, bank overdraft."}]},{"text":[{"text":"Non-current (long-term) liabilities:","bold":true},{"text":" due after one year: long-term bank loan, debentures."}]},{"text":[{"text":"Capital section:","bold":true},{"text":" opening capital + net profit (− net loss) + further capital − drawings = "},{"text":"closing capital","bold":true},{"text":"."}]},{"text":[{"text":"Working capital (net current assets)","bold":true},{"text":" = current assets − current liabilities."}]},{"text":[{"text":"Balance check:","bold":true},{"text":" net assets (total assets − all liabilities) = closing capital."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Layout (vertical)","bold":true},{"text":": the order of the headings"}]},{"type":"table","header":[[{"text":"Section"}],[{"text":"Contents"}]],"rows":[[[{"text":"Non-current assets"}],[{"text":"Each at cost, accumulated depreciation, net book value"}]],[[{"text":"Current assets"}],[{"text":"Stock, debtors less provision, prepayments, bank, cash"}]],[[{"text":"Less: current liabilities"}],[{"text":"Creditors, accruals, bank overdraft"}]],[[{"text":"Working capital"}],[{"text":"Current assets − current liabilities"}]],[[{"text":"Less: non-current liabilities"}],[{"text":"Long-term loan"}]],[[{"text":"Net assets","bold":true}],[{"text":"Must equal the capital total below"}]],[[{"text":"Financed by: capital"}],[{"text":"Opening capital + net profit − drawings"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" working capital uses only current items. \"Current assets over fixed assets\" or \"fixed assets over current liabilities\" are wrong."}]},{"text":[{"text":"Missing figure:","bold":true},{"text":" fixed assets are double current assets (₦300,000) and half of capital; investments ₦400,000; no other items. Fixed assets = ₦600,000; capital = ₦1,200,000; total assets = 600,000 + 300,000 + 400,000 = ₦1,300,000; current liabilities = 1,300,000 − 1,200,000 = "},{"text":"₦100,000","bold":true},{"text":"."}]}]}]},{"number":"8.5","title":"Final accounts from a trial balance with adjustments","mustKnow":[{"type":"paragraph","text":[{"text":"Steps","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Read every adjustment and note its "},{"text":"two","bold":true},{"text":" effects (Lesson 8.3 table)."}]},{"text":[{"text":"Trading account: net sales less cost of sales = gross profit."}]},{"text":[{"text":"Profit and loss account: gross profit + other income − adjusted expenses = net profit."}]},{"text":[{"text":"Balance sheet: adjusted assets and liabilities; capital + net profit − drawings."}]},{"text":[{"text":"Check that net assets equal closing capital."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Trial balance of Adaeze Stores as at 31 December 2025","bold":true}]},{"type":"table","header":[[{"text":"Account"}],[{"text":"Dr ₦"}],[{"text":"Cr ₦"}]],"rows":[[[{"text":"Capital"}],[],[{"text":"1,258,000"}]],[[{"text":"Drawings"}],[{"text":"300,000"}],[]],[[{"text":"Sales"}],[],[{"text":"3,200,000"}]],[[{"text":"Purchases"}],[{"text":"1,850,000"}],[]],[[{"text":"Returns inwards / returns outwards"}],[{"text":"50,000"}],[{"text":"30,000"}]],[[{"text":"Stock (1 January 2025)"}],[{"text":"320,000"}],[]],[[{"text":"Carriage inwards"}],[{"text":"40,000"}],[]],[[{"text":"Carriage outwards"}],[{"text":"35,000"}],[]],[[{"text":"Wages and salaries"}],[{"text":"410,000"}],[]],[[{"text":"Rent"}],[{"text":"240,000"}],[]],[[{"text":"Insurance"}],[{"text":"60,000"}],[]],[[{"text":"General expenses"}],[{"text":"45,000"}],[]],[[{"text":"Discount allowed / discount received"}],[{"text":"15,000"}],[{"text":"12,000"}]],[[{"text":"Bad debts"}],[{"text":"10,000"}],[]],[[{"text":"Provision for bad debts"}],[],[{"text":"15,000"}]],[[{"text":"Equipment at cost / accumulated depreciation"}],[{"text":"600,000"}],[{"text":"120,000"}]],[[{"text":"Motor van at cost / accumulated depreciation"}],[{"text":"800,000"}],[{"text":"160,000"}]],[[{"text":"Debtors / creditors"}],[{"text":"410,000"}],[{"text":"290,000"}]],[[{"text":"Cash at bank"}],[{"text":"186,000"}],[]],[[{"text":"Cash in hand"}],[{"text":"14,000"}],[]],[[{"text":"Bank loan (repayable 2030)"}],[],[{"text":"300,000"}]],[[{"text":"Totals","bold":true}],[{"text":"5,385,000","bold":true}],[{"text":"5,385,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Adjustments","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Closing stock ₦380,000."}]},{"text":[{"text":"Wages owing ₦30,000."}]},{"text":[{"text":"Insurance prepaid ₦12,000."}]},{"text":[{"text":"Depreciation: equipment 10% straight line on cost (₦60,000); motor van 20% reducing balance: 20% × (800,000 − 160,000) = ₦128,000."}]},{"text":[{"text":"Write off a further bad debt of ₦10,000 and adjust the provision for bad debts to 5% of the remaining debtors: 5% × 400,000 = ₦20,000, an increase of ₦5,000."}]}]},{"type":"paragraph","text":[{"text":"Trading, profit and loss account of Adaeze Stores for the year ended 31 December 2025","bold":true}]},{"type":"table","header":[[],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Sales"}],[],[{"text":"3,200,000"}]],[[{"text":"Less: returns inwards"}],[],[{"text":"(50,000)"}]],[[{"text":"Net sales"}],[],[{"text":"3,150,000"}]],[[{"text":"Opening stock"}],[{"text":"320,000"}],[]],[[{"text":"Purchases 1,850,000 + carriage inwards 40,000 − returns outwards 30,000"}],[{"text":"1,860,000"}],[]],[[{"text":"Cost of goods available for sale"}],[{"text":"2,180,000"}],[]],[[{"text":"Less: closing stock"}],[{"text":"(380,000)"}],[]],[[{"text":"Cost of sales"}],[],[{"text":"(1,800,000)"}]],[[{"text":"Gross profit","bold":true}],[],[{"text":"1,350,000","bold":true}]],[[{"text":"Add: discount received"}],[],[{"text":"12,000"}]],[[],[],[{"text":"1,362,000"}]],[[{"text":"Wages and salaries (410,000 + 30,000)"}],[{"text":"440,000"}],[]],[[{"text":"Rent"}],[{"text":"240,000"}],[]],[[{"text":"Insurance (60,000 − 12,000)"}],[{"text":"48,000"}],[]],[[{"text":"Carriage outwards"}],[{"text":"35,000"}],[]],[[{"text":"General expenses"}],[{"text":"45,000"}],[]],[[{"text":"Discount allowed"}],[{"text":"15,000"}],[]],[[{"text":"Bad debts (10,000 + 10,000)"}],[{"text":"20,000"}],[]],[[{"text":"Increase in provision for bad debts"}],[{"text":"5,000"}],[]],[[{"text":"Depreciation: equipment"}],[{"text":"60,000"}],[]],[[{"text":"Depreciation: motor van"}],[{"text":"128,000"}],[]],[[{"text":"Total expenses"}],[],[{"text":"(1,036,000)"}]],[[{"text":"Net profit","bold":true}],[],[{"text":"326,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Balance sheet of Adaeze Stores as at 31 December 2025","bold":true}]},{"type":"table","header":[[{"text":"Non-current assets"}],[{"text":"Cost ₦"}],[{"text":"Acc. depreciation ₦"}],[{"text":"NBV ₦"}]],"rows":[[[{"text":"Equipment"}],[{"text":"600,000"}],[{"text":"180,000"}],[{"text":"420,000"}]],[[{"text":"Motor van"}],[{"text":"800,000"}],[{"text":"288,000"}],[{"text":"512,000"}]],[[],[{"text":"1,400,000"}],[{"text":"468,000"}],[{"text":"932,000","bold":true}]]]},{"type":"table","header":[[],[{"text":"₦"}],[{"text":"₦"}]],"rows":[[[{"text":"Current assets","bold":true}],[],[]],[[{"text":"Stock"}],[{"text":"380,000"}],[]],[[{"text":"Debtors 400,000 less provision 20,000"}],[{"text":"380,000"}],[]],[[{"text":"Prepaid insurance"}],[{"text":"12,000"}],[]],[[{"text":"Cash at bank"}],[{"text":"186,000"}],[]],[[{"text":"Cash in hand"}],[{"text":"14,000"}],[]],[[],[{"text":"972,000"}],[]],[[{"text":"Less: current liabilities","bold":true}],[],[]],[[{"text":"Creditors"}],[{"text":"290,000"}],[]],[[{"text":"Wages owing (accrued)"}],[{"text":"30,000"}],[]],[[],[{"text":"(320,000)"}],[]],[[{"text":"Working capital"}],[],[{"text":"652,000"}]],[[{"text":"Non-current assets + working capital"}],[],[{"text":"1,584,000"}]],[[{"text":"Less: bank loan (non-current liability)"}],[],[{"text":"(300,000)"}]],[[{"text":"Net assets","bold":true}],[],[{"text":"1,284,000","bold":true}]],[[{"text":"Financed by","bold":true}],[],[]],[[{"text":"Capital at 1 January 2025"}],[],[{"text":"1,258,000"}]],[[{"text":"Add: net profit"}],[],[{"text":"326,000"}]],[[],[],[{"text":"1,584,000"}]],[[{"text":"Less: drawings"}],[],[{"text":"(300,000)"}]],[[{"text":"Closing capital","bold":true}],[],[{"text":"1,284,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Net assets ₦1,284,000 = closing capital ₦1,284,000, so the balance sheet balances. In the equation form: total assets ₦1,904,000 (932,000 + 972,000) = capital ₦1,284,000 + loan ₦300,000 + current liabilities ₦320,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" each adjustment appears "},{"text":"twice","bold":true},{"text":" (once in profit and loss, once in the balance sheet). Depreciation on reducing balance is worked on NBV (cost − opening accumulated depreciation), not cost. Only the ₦5,000 increase in provision is charged, but the full ₦20,000 is deducted from debtors. Drawings go against capital, never into expenses."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Three final accounts: trading account (gross profit), profit and loss account (net profit), balance sheet (position at a date, built on Assets = Liabilities + Capital)."}]},{"text":[{"text":"Cost of sales = opening stock + purchases + carriage inwards − returns outwards − closing stock."}]},{"text":[{"text":"Gross profit = net sales (sales − returns inwards) − cost of sales."}]},{"text":[{"text":"Carriage inwards adds to cost of sales; carriage outwards is a P&L expense."}]},{"text":[{"text":"Net profit = gross profit + other income − expenses; drawings are deducted from capital, not expenses."}]},{"text":[{"text":"Overstated closing stock overstates gross profit."}]},{"text":[{"text":"Current assets turn into cash within a year; intangible assets have no physical form."}]},{"text":[{"text":"Working capital = current assets − current liabilities."}]},{"text":[{"text":"Every adjustment has two effects: one in profit and loss, one in the balance sheet."}]},{"text":[{"text":"Closing capital = opening capital + net profit − drawings, and it equals net assets."}]}]}],"theory":{"itemId":"0cc6c0e3-721d-51f2-9873-a355d6fd11c4","question":[{"type":"paragraph","text":[{"text":"Distinguish between gross profit and net profit. Then compute both from: sales ₦500,000, returns inwards ₦20,000, opening stock ₦60,000, purchases ₦300,000, carriage inwards ₦10,000, carriage outwards ₦8,000, closing stock ₦70,000, rent ₦40,000, drawings ₦25,000."}]}]},"practice":[{"topic":"Final accounts of a sole trader","named":false}]}}]$expected_content$::jsonb,
  'introduction-financial-accounting-1: note published payload and identity match source');
