  where kind = 'course_overview') = $expected_content$[{"itemId":"f041360f-0ed4-5d49-87f5-ea47e587979f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Business I","body":"Every topic is examinable.","outcomes":["Explain what businesses do, the environments they operate in and their major functional areas.","Describe economic systems, demand and supply, and how government and economic measures affect business.","Explain international trade, trade barriers and the forms of international business.","Apply ethics and corporate social responsibility to business decisions.","Compare the forms of business ownership and explain corporate governance, mergers and alliances.","Explain entrepreneurship, small-business start-up and financing, and franchising.","Describe the roles, functions and skills of managers.","Explain production systems, value chains, supply chains and quality.","Apply the main theories of employee motivation.","Describe e-business models and the business communication process."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, Nigerian institutions and examples."]}}]$expected_content$::jsonb,
  'introduction-business-1: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
