  from public.read_published_managed_content('3377fae6-5ab9-5742-95e3-75b94650a294')
  where kind = 'note') = $expected_content$[{"itemId":"323e5369-3db7-5f26-a4fc-c4f2d02fbd8c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Developing a Business Mindset","body":"What a business is and how it adds value; types of business and stakeholders; making the leap from buyer to seller; the business environments (internal, external, general, task) and Nigerian regulators; the functional areas; careers in business; the seven traits of professionalism.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What a business is and how it adds value; types of business and stakeholders; making the leap from buyer to seller; the business environments (internal, external, general, task) and Nigerian regulators; the functional areas; careers in business; the seven traits of professionalism."}],"lessons":[{"number":"1.1","title":"What businesses do","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business:","bold":true},{"text":" any profit-seeking organisation that provides goods and services designed to satisfy customers' needs. Another definition: purposeful or deliberate activities concerned with the provision of goods and services which are distributed through an organised system (distribution)."}]},{"text":[{"text":"Primary purpose of a business:","bold":true},{"text":" to generate and provide "},{"text":"customer value","bold":true},{"text":". Profit is the reward for doing this well."}]},{"text":[{"text":"Adding value:","bold":true},{"text":" a business is a system that transforms "},{"text":"lower-value inputs","bold":true},{"text":" into "},{"text":"higher-value outputs","bold":true},{"text":". At every stage it adds value to make the product appealing to the next customer in the chain."}]},{"text":[{"text":"Business model:","bold":true},{"text":" a concise description of how a business intends to "},{"text":"generate revenue","bold":true},{"text":"."}]},{"text":[{"text":"Revenue","bold":true},{"text":" = money brought in from sales. "},{"text":"Profit","bold":true},{"text":" = revenue minus costs."}]}]},{"type":"paragraph","text":[{"text":"3 major types of organisation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Not-for-profit (nonprofit):","bold":true},{"text":" provides goods and services "},{"text":"without a profit motive","bold":true},{"text":", e.g. the World Health Organization (WHO), the Red Cross, a mosque or church charity."}]},{"text":[{"text":"Goods-producing:","bold":true},{"text":" creates value by making \"things\", mostly "},{"text":"tangible","bold":true},{"text":" (digital products such as software are the notable exception)."}]},{"text":[{"text":"Service:","bold":true},{"text":" creates value by "},{"text":"performing activities","bold":true},{"text":" that deliver a benefit, e.g. banks, hairdressers, consultants, MTN's call and data services."}]}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"What it does"}],[{"text":"Example"}]],"rows":[[[{"text":"Manufacturing"}],[{"text":"Makes a product and sells it"}],[{"text":"Dangote Cement"}]],[[{"text":"Wholesale"}],[{"text":"Sells goods in "},{"text":"large quantities to retailers","bold":true}],[{"text":"A distributor supplying shops"}]],[[{"text":"Retail"}],[{"text":"Sells to "},{"text":"final consumers","bold":true}],[{"text":"Shoprite, a corner shop"}]],[[{"text":"Service-based"}],[{"text":"Profits by providing services, not goods"}],[{"text":"Bank, salon, software developer"}]]]},{"type":"paragraph","text":[{"text":"Stakeholders and what they receive","bold":true}]},{"type":"table","header":[[{"text":"Stakeholder"}],[{"text":"Gives the business"}],[{"text":"Receives"}]],"rows":[[[{"text":"Shareholders (owners)"}],[{"text":"Capital"}],[{"text":"Dividends","bold":true}]],[[{"text":"Employees"}],[{"text":"Labour"}],[{"text":"Wages and salaries","bold":true}]],[[{"text":"Customers"}],[{"text":"Payment"}],[{"text":"Goods and services (value)"}]],[[{"text":"Government"}],[{"text":"Infrastructure","bold":true},{"text":", law and order"}],[{"text":"Taxes","bold":true}]],[[{"text":"Community"}],[{"text":"Location, goodwill"}],[{"text":"Community services","bold":true},{"text":", jobs"}]],[[{"text":"Suppliers"}],[{"text":"Inputs"}],[{"text":"Payment"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"software development company","bold":true},{"text":" that builds systems for clients sells its expertise, so it is a "},{"text":"service business","bold":true},{"text":". A car dealership, bakery or furniture store deals in physical goods."}]},{"text":[{"text":"McDonald's, Apple and Tesla are profit-seeking; WHO is not-for-profit. Nonprofits still need money and good management; they simply do not distribute profit to owners."}]},{"text":[{"text":"Understanding what businesses do means recognising their "},{"text":"creation of products and services","bold":true},{"text":", not tax avoidance or isolation from competition."}]},{"text":[{"text":"Trap: "},{"text":"dividends","bold":true},{"text":" go to shareholders; "},{"text":"wages","bold":true},{"text":" go to employees. \"Provision of infrastructure\" is what government gives, not what shareholders receive."}]}]}]},{"number":"1.2","title":"Making the leap from buyer to seller","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"As a consumer you already know a lot: the impact of poor customer service, product value, and the whole experience of searching for, buying and owning products."}]},{"text":[{"text":"3 steps to make the leap from consumer to business professional:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Seeing business from the inside out:","bold":true},{"text":" think about the cost of making, promoting and distributing a product, not just buying it; see business as an integrated system of "},{"text":"inputs, processes and outputs","bold":true},{"text":"."}]},{"text":[{"text":"Appreciating the role of business in society.","bold":true}]},{"text":[{"text":"Using this course to jump-start your career.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 ways business benefits society:","bold":true},{"text":" (1) offering valuable goods and services; (2) providing employment; (3) paying taxes; (4) contributing to national growth, stability and security."}]},{"text":[{"text":"4 negative effects:","bold":true},{"text":" (1) generating pollution and creating waste; (2) creating health and safety risks; (3) disrupting communities; (4) causing financial instability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Making the leap begins with "},{"text":"grasping customer preferences","bold":true},{"text":": what customers want and value. Ignoring market shifts or chasing profit margins alone is the opposite."}]},{"text":[{"text":"A "},{"text":"business mindset","bold":true},{"text":" means "},{"text":"comprehending operational success factors","bold":true},{"text":": the many decisions and challenges a company must handle before it can deliver products that satisfy customers. It is not targeting only quick wins or shunning all uncertainty."}]},{"text":[{"text":"The course builds a business vocabulary, introduces jobs (accounting, economics, HR, management, finance, marketing) and shows the legal and ethical questions managers face."}]}]}]},{"number":"1.3","title":"The environments of business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No business operates in a vacuum. "},{"text":"Business environment:","bold":true},{"text":" all the forces, inside and outside a firm, that affect and are affected by it."}]},{"text":[{"text":"2 types:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" and "},{"text":"external","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Internal environment"}],[{"text":"External environment"}]],"rows":[[[{"text":"Inside the firm; "},{"text":"controllable","bold":true}],[{"text":"Outside the firm; "},{"text":"uncontrollable","bold":true}]],[[{"text":"Staff, structure, resources, management, "},{"text":"organisational (workplace) culture","bold":true},{"text":", values, operational procedures"}],[{"text":"Economy, technology, politics, law, society, competitors, customers"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The external environment splits into:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"General (macro) forces:","bold":true},{"text":" affect all firms: "},{"text":"political-legal, economic, socio-cultural, technological","bold":true},{"text":" (PESTLE adds legal and environmental/ecological)."}]},{"text":[{"text":"Task (micro, operating) forces:","bold":true},{"text":" close to the firm: customers, competitors, suppliers, investors."}]}]}]}]},{"type":"paragraph","text":[{"text":"The 5 environments every business operates in:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Social:","bold":true},{"text":" trends and forces in society at large."}]},{"text":[{"text":"Technological:","bold":true},{"text":" forces from the practical application of science to innovations, products and processes."}]},{"text":[{"text":"Economic:","bold":true},{"text":" conditions and forces that affect the cost and availability of goods, services and labour, and so shape the behaviour of buyers and sellers."}]},{"text":[{"text":"Legal and regulatory:","bold":true},{"text":" laws and regulations at local, state, national and international levels."}]},{"text":[{"text":"Market:","bold":true},{"text":" target customers, the buying influences that shape their behaviour, and competitors marketing similar products."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Features of the business environment:","bold":true},{"text":" "},{"text":"dynamic","bold":true},{"text":" (always changing), "},{"text":"uncertain","bold":true},{"text":", "},{"text":"relative","bold":true},{"text":" (differs by place and firm), complex, multi-faceted. "},{"text":"Certainty is not a feature.","bold":true}]},{"text":[{"text":"Importance:","bold":true},{"text":" identifying opportunities and threats, improving performance, coping with rapid changes, better planning. (\"All of these\" is the answer.)"}]},{"text":[{"text":"Environmental scanning:","bold":true},{"text":" careful monitoring of the internal and external environments to detect early signs of opportunities and threats that may influence current and future plans."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Political-legal environment","bold":true},{"text":" = the relationship between "},{"text":"business and government","bold":true},{"text":". Customs, values, attitudes and demographics are the "},{"text":"socio-cultural","bold":true},{"text":" environment; intensity of competition is the "},{"text":"market/competitive","bold":true},{"text":" environment."}]},{"text":[{"text":"Technological conditions are a "},{"text":"general","bold":true},{"text":" force; customers, competitors and investors are task forces."}]},{"text":[{"text":"Emerging technology and political change are "},{"text":"external","bold":true},{"text":"; staff dynamics, corporate values and operating protocols are "},{"text":"internal","bold":true},{"text":"."}]},{"text":[{"text":"Traps: SWOT analysis uses scanning results (strengths, weaknesses, opportunities, threats) but is not the definition of scanning. PESTLE covers only the external macro environment."}]}]}]},{"number":"1.4","title":"Regulators and the Nigerian legal environment","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Full name"}],[{"text":"Main job"}]],"rows":[[[{"text":"CAC","bold":true}],[{"text":"Corporate Affairs Commission"}],[{"text":"Established by the "},{"text":"Companies and Allied Matters Act","bold":true},{"text":" (first 1990; now "},{"text":"CAMA 2020","bold":true},{"text":") and "},{"text":"implements its provisions","bold":true},{"text":": registers companies, business names and incorporated trustees; regulates their formation, management and winding up"}]],[[{"text":"SON","bold":true}],[{"text":"Standards Organisation of Nigeria"}],[{"text":"Sets and enforces "},{"text":"product standards","bold":true}]],[[{"text":"SEC","bold":true}],[{"text":"Securities and Exchange Commission"}],[{"text":"Apex regulator of the Nigerian capital market","bold":true}]],[[{"text":"NEPC","bold":true}],[{"text":"Nigerian Export Promotion Council"}],[{"text":"Promotes "},{"text":"non-oil exports","bold":true}]],[[{"text":"NAFDAC","bold":true}],[{"text":"National Agency for Food and Drug Administration and Control"}],[{"text":"Regulates food, drugs, cosmetics, chemicals and packaged water"}]]]},{"type":"paragraph","text":[{"text":"Functions of SON:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Organises "},{"text":"tests","bold":true},{"text":" and does what is necessary to ensure compliance with approved standards."}]},{"text":[{"text":"Investigates the "},{"text":"quality of facilities, materials and products","bold":true},{"text":" used in production."}]},{"text":[{"text":"Registers and regulates standard marks and specifications.","bold":true}]},{"text":[{"text":"Certifies products","bold":true},{"text":" in commerce and industry (also factories and laboratories)."}]},{"text":[{"text":"Advises government","bold":true},{"text":" on problems relating to standards specification."}]}]},{"type":"paragraph","text":[{"text":"Functions of NEPC:","bold":true},{"text":" provides "},{"text":"grants and incentives","bold":true},{"text":" to exporters, provides "},{"text":"information on products","bold":true},{"text":" and markets, provides "},{"text":"lists of exportable products","bold":true},{"text":", and trains exporters."}]},{"type":"paragraph","text":[{"text":"Functions of SEC:","bold":true},{"text":" registers securities and capital market operators, protects investors, "},{"text":"disseminates information to investors on securities","bold":true},{"text":", and keeps the market fair and transparent."}]},{"type":"paragraph","text":[{"text":"Challenges of complying with government regulations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Corruption.","bold":true}]},{"text":[{"text":"Costs of compliance","bold":true},{"text":" (fees, paperwork, staff time, upgrades)."}]},{"text":[{"text":"Complexity of regulations.","bold":true}]},{"text":[{"text":"Political "},{"text":"instability","bold":true},{"text":" and frequent policy changes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: "},{"text":"political stability","bold":true},{"text":" is not a compliance challenge; it helps business."}]},{"text":[{"text":"The stock exchange (Nigerian Exchange, NGX, formerly the Nigerian Stock Exchange, NSE) is a market "},{"text":"regulated by SEC","bold":true},{"text":"; it is not the apex regulator."}]},{"text":[{"text":"\"Providing opportunities for businesses to raise funds\" is a capital market role, "},{"text":"not","bold":true},{"text":" SON's. \"Disseminating information on securities\" is SEC's, "},{"text":"not","bold":true},{"text":" NEPC's."}]},{"text":[{"text":"Testing the "},{"text":"quality of materials and facilities","bold":true},{"text":" points to "},{"text":"SON","bold":true},{"text":", not NAFDAC; NAFDAC is about food, drugs and similar regulated products."}]}]}]},{"number":"1.5","title":"The major functional areas","mustKnow":[{"type":"paragraph","text":[{"text":"The 6 major functional areas:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Research and development (R&D):","bold":true},{"text":" conceiving and designing new products."}]},{"text":[{"text":"Manufacturing, production and operations:","bold":true},{"text":" where the company makes what it makes, or does what it does (service firms)."}]},{"text":[{"text":"Marketing, sales, distribution and customer support:","bold":true},{"text":" marketing identifies opportunities and customer wants, works with R&D to develop products, creates branding and advertising, and sets prices; sales builds relationships and persuades customers to buy; distribution moves products, before and after the sale; customer support helps buyers after purchase."}]},{"text":[{"text":"Finance and accounting:","bold":true},{"text":" ensures the company has the funds it needs, monitors and controls spending, and drafts reports for management, investors and government regulators."}]},{"text":[{"text":"Human resources (HR):","bold":true},{"text":" recruiting, hiring, developing and supporting employees."}]},{"text":[{"text":"Business services:","bold":true},{"text":" law, banking, real estate and similar, done in-house, by outside firms or both."}]}]},{"type":"paragraph","text":[{"text":"Other functions you will meet in options:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Employment relations and HRM:","bold":true},{"text":" puts the "},{"text":"right people in the right posts under the right conditions","bold":true},{"text":"; handles "},{"text":"remuneration","bold":true},{"text":" (pay and benefits)."}]},{"text":[{"text":"Insurance and risk management:","bold":true},{"text":" identifies risks such as "},{"text":"safety issues that could lead to lawsuits","bold":true},{"text":", and "},{"text":"implements plans and strategies to minimise business losses","bold":true},{"text":" (avoid, reduce, retain or transfer risk, e.g. by buying insurance)."}]},{"text":[{"text":"Information technology (IT):","bold":true},{"text":" systems that deliver the right information to the right people at the right time; supports every other area."}]},{"text":[{"text":"Reasons for separating operations into functional areas:","bold":true},{"text":" "},{"text":"efficiency, expertise, effectiveness","bold":true},{"text":" (through specialisation). "},{"text":"Increased costs is not a reason.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HR activities:","bold":true},{"text":" "},{"text":"acquisition","bold":true},{"text":" (getting staff, made up of "},{"text":"recruitment","bold":true},{"text":" then "},{"text":"selection","bold":true},{"text":"), development (training), compensation, maintenance. "},{"text":"Recruitment","bold":true},{"text":" = advertising to attract a "},{"text":"pool of candidates","bold":true},{"text":"; "},{"text":"selection","bold":true},{"text":" = choosing from that pool."}]},{"text":[{"text":"Marketing "},{"text":"identifies customer wants and develops products","bold":true},{"text":" to satisfy them, and covers "},{"text":"advertising, selling and distributing","bold":true},{"text":"; \"market outreach\" (promoting products) is marketing. Process optimisation is operations; fiscal planning is finance; product innovation is R&D."}]},{"text":[{"text":"Mining","bold":true},{"text":" is an industry, not a functional area."}]},{"text":[{"text":"Production, R&D and HR together aid business processes toward profit and essential services. Dividends, wages and regular orders are not functions."}]},{"text":[{"text":"Not every company has a formal R&D function; many service firms and small businesses do not, though most still need to improve their offerings."}]}]}]},{"number":"1.6","title":"Careers in business and professionalism","mustKnow":[{"type":"paragraph","text":[{"text":"7 important business professions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Operations manager:","bold":true},{"text":" all people and processes that create the goods and perform the services a company sells."}]},{"text":[{"text":"Human resources specialist:","bold":true},{"text":" recruiting, training and development, compensation and benefits, employee and labour relations, health and safety."}]},{"text":[{"text":"Information technology manager:","bold":true},{"text":" designs, implements and maintains information systems."}]},{"text":[{"text":"Marketing specialist:","bold":true},{"text":" branding, e-commerce, advertising, public relations, social media."}]},{"text":[{"text":"Sales professional:","bold":true},{"text":" suits people who thrive on competition, enjoy solving problems and like working with many people."}]},{"text":[{"text":"Accountant:","bold":true},{"text":" management accountants "},{"text":"collect, analyse and report","bold":true},{"text":" on financial matters."}]},{"text":[{"text":"Financial manager:","bold":true},{"text":" "},{"text":"controllers","bold":true},{"text":" oversee financial reports and often manage accounting; "},{"text":"treasurers and finance officers","bold":true},{"text":" set long-term financial goals and budgets, "},{"text":"invest the firm's funds and raise capital","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Professionalism:","bold":true},{"text":" the quality of performing at a high level and conducting oneself with "},{"text":"purpose and pride","bold":true},{"text":"."}]},{"text":[{"text":"7 traits:","bold":true},{"text":" (1) striving to excel; (2) being dependable and accountable; (3) being a team player; (4) communicating effectively; (5) demonstrating etiquette; (6) making ethical decisions; (7) maintaining a confident, positive outlook."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accountant vs financial manager: the accountant "},{"text":"records and reports","bold":true},{"text":"; the financial manager "},{"text":"plans and acts","bold":true},{"text":" on the numbers. A \"financial resource director\" manages a company's financial resources."}]},{"text":[{"text":"Logistics and distribution","bold":true},{"text":" is a business career; structural engineering, clinical healthcare and crop cultivation are not."}]},{"text":[{"text":"Dependable:","bold":true},{"text":" meet commitments, on schedule and within budget. "},{"text":"Team player:","bold":true},{"text":" pull your own weight while watching the team's success. "},{"text":"Etiquette:","bold":true},{"text":" expected norms of behaviour in a situation. "},{"text":"Ethical decisions:","bold":true},{"text":" avoid ethical lapses; weigh options carefully in ethical dilemmas."}]},{"text":[{"text":"7 guidelines for communicating effectively:","bold":true},{"text":" listen actively; provide practical information; give facts rather than vague impressions; do not present opinions as facts; be concise and efficient; clarify expectations and responsibilities; offer compelling, persuasive arguments and recommendations."}]},{"text":[{"text":"Trap: professionalism is "},{"text":"not","bold":true},{"text":" holding a degree, wearing formal clothes or obeying without question."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business = profit-seeking provider of goods and services; purpose = customer value; it adds value by turning inputs into higher-value outputs."}]},{"text":[{"text":"Business model = how a business intends to generate revenue."}]},{"text":[{"text":"Types: not-for-profit, goods-producing, service; also manufacturing, wholesale (to retailers), retail (to consumers)."}]},{"text":[{"text":"Shareholders get dividends, employees wages, government taxes."}]},{"text":[{"text":"Leap from buyer to seller: inside-out view, role in society, jump-start your career."}]},{"text":[{"text":"Environments: internal (controllable) vs external (uncontrollable); general vs task; five environments: social, technological, economic, legal-regulatory, market."}]},{"text":[{"text":"CAC (CAMA), SON (standards), SEC (apex capital market regulator), NEPC (exports)."}]},{"text":[{"text":"Six functional areas: R&D, production/operations, marketing, finance and accounting, HR, business services; plus insurance and risk management."}]},{"text":[{"text":"Seven professions; professionalism has seven traits."}]}]}],"theory":{"itemId":"673bffa2-543e-5b27-b905-4445464c011f","question":[{"type":"paragraph","text":[{"text":"Explain the five environments in which every business operates, and state two ways business benefits society."}]}]},"practice":[{"topic":"Developing a Business Mindset","named":false}]}},{"itemId":"74c39a6d-d5d9-5f48-865a-bc7ac7cfe7d5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:10","parentItemId":null,"revision":1,"payload":{"title":"E-business and Business Communication","body":"E-commerce vs e-business and the perspectives on e-commerce; the EC framework; click-only, click-and-mortar and brick-and-mortar firms; B2B, B2C, C2C, B2E and the other transaction types, including m-commerce; business models and online auctions (forward and reverse); benefits and limitations; the communication process model, ways of receiving information and channels; formal communication, the grapevine and barriers.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"E-commerce vs e-business and the perspectives on e-commerce; the EC framework; click-only, click-and-mortar and brick-and-mortar firms; B2B, B2C, C2C, B2E and the other transaction types, including m-commerce; business models and online auctions (forward and reverse); benefits and limitations; the communication process model, ways of receiving information and channels; formal communication, the grapevine and barriers."}],"lessons":[{"number":"10.1","title":"E-commerce and e-business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic commerce (EC or e-commerce):","bold":true},{"text":" the online exchange of goods, services and money between firms, and between firms and their customers. In short, buying, selling, transferring or exchanging products, services and information over computer networks, mostly the internet."}]},{"text":[{"text":"E-business (electronic business):","bold":true},{"text":" the conducting of business on the internet. It is a broader term: the use of electronic communications for "},{"text":"all business processes","bold":true},{"text":", not just buying and selling. It covers sales, purchasing and services on the internet, plus serving customers, collaborating with business partners, e-learning and transactions inside the organisation."}]},{"text":[{"text":"E-commerce goes beyond the sale itself: it can involve the events "},{"text":"leading to a purchase","bold":true},{"text":" (searching, comparing, advertising) as well as "},{"text":"customer service after the sale","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Perspectives on e-commerce:","bold":true},{"text":" e-commerce is often seen simply as buying and selling on the internet, but all these perspectives apply:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Communications:","bold":true},{"text":" delivering information, products, services or payments over telephone lines, computer networks or other electronic means."}]},{"text":[{"text":"Business process:","bold":true},{"text":" applying technology to automate business transactions and workflows."}]},{"text":[{"text":"Service:","bold":true},{"text":" a tool that helps firms, consumers and management cut service costs while improving the quality and speed of service."}]},{"text":[{"text":"Online:","bold":true},{"text":" buying and selling products and information on the internet and other online services."}]}]},{"type":"paragraph","text":[{"text":"The EC framework:","bold":true},{"text":" EC "},{"text":"applications","bold":true},{"text":" (online shopping, auctions, banking, e-government and so on) rest on "},{"text":"infrastructure","bold":true},{"text":" (hardware, software, networks) and on "},{"text":"five support areas","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"People","bold":true},{"text":" (buyers, sellers, intermediaries, IT staff)"}]},{"text":[{"text":"Public policy","bold":true},{"text":" (laws, regulation, taxation, privacy)"}]},{"text":[{"text":"Marketing and advertisement","bold":true}]},{"text":[{"text":"Support services","bold":true},{"text":" (payments, logistics/delivery, security)"}]},{"text":[{"text":"Business partnerships","bold":true},{"text":" (joint ventures, partners along the supply chain)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Competitors\" is "},{"text":"not","bold":true},{"text":" a support area of EC. If asked which is the exception, pick competitors."}]},{"text":[{"text":"Trap:","bold":true},{"text":" when e-commerce and e-business appear together, e-business is the "},{"text":"wider","bold":true},{"text":" term. \"An organisation selling direct to its customers online\" or \"buying from its suppliers online\" describes only part of e-business. \"Electronic communications for all business processes\" is the full definition."}]},{"text":[{"text":"When a question asks what is exchanged in EC and offers money, goods, services and \"all of the above\", choose "},{"text":"all of the above","bold":true},{"text":". The same goes for sales, purchasing and services as examples of e-business."}]},{"text":[{"text":"The internet and Web technologies together created a "},{"text":"global platform","bold":true},{"text":" where firms across the world compete for customers and gain access to "},{"text":"new markets","bold":true},{"text":". A Lagos fashion brand can sell to buyers in Accra or London through its website and Instagram page."}]}]}]},{"number":"10.2","title":"Types of e-commerce organisations and transactions","mustKnow":[{"type":"table","header":[[{"text":"Type of organisation"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Brick-and-mortar","bold":true}],[{"text":"Old-economy firm doing business only offline, through physical premises"}],[{"text":"A neighbourhood provision shop"}]],[[{"text":"Click-and-mortar","bold":true},{"text":" (click-and-brick)"}],[{"text":"Keeps its physical locations but has added an "},{"text":"EC (electronic commerce)","bold":true},{"text":" component"}],[{"text":"A supermarket chain with shops plus an online store"}]],[[{"text":"Click-only","bold":true},{"text":" (virtual, pure-play)"}],[{"text":"Does business entirely online; has "},{"text":"no physical storefronts","bold":true}],[{"text":"Jiji, Jumia"}]]]},{"type":"paragraph","text":[{"text":"Transaction types (by who trades with whom):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"B2B (business-to-business):","bold":true},{"text":" transactions between businesses, e.g. a manufacturer buying raw materials from a supplier online. The largest type of EC by value."}]},{"text":[{"text":"B2C (business-to-consumer):","bold":true},{"text":" a business selling to individual shoppers (e-tailing), e.g. Jumia and Konga selling phones and household goods."}]},{"text":[{"text":"C2C (consumer-to-consumer):","bold":true},{"text":" individuals selling to individuals, e.g. a student listing a used laptop on "},{"text":"Jiji","bold":true},{"text":" and another person buying it."}]},{"text":[{"text":"B2E (business-to-employee):","bold":true},{"text":" an organisation delivering information or services to its own employees, usually through its "},{"text":"intranet","bold":true},{"text":", e.g. HR posting a Sales Department vacancy on the company intranet."}]},{"text":[{"text":"C2B (consumer-to-business):","bold":true},{"text":" individuals sell products or services to firms, or name what they will pay and firms compete to supply."}]},{"text":[{"text":"B2B2C:","bold":true},{"text":" a business sells to another business, which delivers to consumers."}]},{"text":[{"text":"Intrabusiness EC:","bold":true},{"text":" EC activities inside one organisation (B2E is part of it)."}]},{"text":[{"text":"E-government:","bold":true},{"text":" government using EC to deal with citizens (G2C) and businesses (G2B), e.g. online tax filing or paying fees and levies online."}]},{"text":[{"text":"Collaborative commerce (c-commerce):","bold":true},{"text":" business partners working together electronically, e.g. "},{"text":"Boeing designing a product together with its business partners","bold":true},{"text":"."}]},{"text":[{"text":"Nonbusiness EC:","bold":true},{"text":" non-profit bodies (universities, religious groups, NGOs, government agencies) using EC to cut costs or improve service."}]},{"text":[{"text":"M-commerce (mobile commerce):","bold":true},{"text":" EC carried out through "},{"text":"mobile","bold":true},{"text":" devices (smartphones, tablets) over wireless networks. The \"m\" means "},{"text":"mobile","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" click-only firms still have employees and supply chains, and many keep warehouses to store goods. What they lack is a "},{"text":"storefront","bold":true},{"text":" customers walk into."}]},{"text":[{"text":"Trap:","bold":true},{"text":" posting a job on the intranet is "},{"text":"B2E","bold":true},{"text":", not B2B. \"B2S\" and \"E2C\" are not standard categories."}]},{"text":[{"text":"Jiji's typical transaction is "},{"text":"C2C","bold":true},{"text":": Jiji provides the website, but buyer and seller are both individuals. Jumia also runs a marketplace where independent sellers list goods, but its typical transaction (a shop selling to you) is classed as "},{"text":"B2C","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria is a mobile-first market, so m-commerce is huge here: ordering on a shopping app, buying airtime and data, and "},{"text":"mobile money","bold":true},{"text":" (sending, receiving and paying money from a phone through mobile money operators and payment apps)."}]}]}]},{"number":"10.3","title":"EC business models and online auctions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business model:","bold":true},{"text":" the method by which a firm generates revenue to sustain itself."}]}]},{"type":"paragraph","text":[{"text":"Common EC business models:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Online direct marketing:","bold":true},{"text":" manufacturers or retailers selling straight to customers online, cutting out middlemen."}]},{"text":[{"text":"Electronic tendering systems:","bold":true},{"text":" large buyers invite sellers to bid (reverse auctions; see below)."}]},{"text":[{"text":"Name-your-own-price:","bold":true},{"text":" the buyer states the price he is willing to pay and the system looks for a seller willing to accept it."}]},{"text":[{"text":"Find-the-best-price:","bold":true},{"text":" the customer states a need and a search engine compares sellers to find the lowest price."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" a firm pays partners a commission for customers they refer from their own websites or pages."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" people pass a marketing message on to their friends and contacts (word of mouth online)."}]},{"text":[{"text":"Group purchasing:","bold":true},{"text":" pooling many small buyers' orders to get a volume discount."}]},{"text":[{"text":"Online auctions.","bold":true}]},{"text":[{"text":"Product and service customisation:","bold":true},{"text":" the buyer configures the product online to suit himself."}]},{"text":[{"text":"Electronic marketplaces and exchanges:","bold":true},{"text":" online meeting places where many buyers and many sellers trade."}]}]},{"type":"paragraph","text":[{"text":"Online auctions:","bold":true}]},{"type":"table","header":[[],[{"text":"Forward auction"}],[{"text":"Reverse auction"}]],"rows":[[[{"text":"Who sells, who bids"}],[{"text":"One seller","bold":true},{"text":", many buyers bid"}],[{"text":"One buyer","bold":true},{"text":", many sellers bid"}]],[[{"text":"Price movement"}],[{"text":"Goes "},{"text":"up","bold":true}],[{"text":"Goes "},{"text":"down","bold":true}]],[[{"text":"Status"}],[{"text":"The "},{"text":"most common, traditional","bold":true},{"text":" form of auction"}],[{"text":"Also called "},{"text":"electronic tendering","bold":true}]],[[{"text":"Typical user"}],[{"text":"A seller clearing goods to the highest bidder"}],[{"text":"Large private organisational buyers and "},{"text":"government agencies","bold":true},{"text":" making large-volume or large-value purchases"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Reverse auction\" and \"electronic tendering system\" mean the same thing. Online direct marketing, name-your-own-price and viral marketing are other models, not reverse auctions."}]},{"text":[{"text":"A tendering system is buyer-led, so it can never be the answer for \"one seller, many buyers\". That is a "},{"text":"forward","bold":true},{"text":" auction."}]},{"text":[{"text":"A ministry inviting online bids for a supply contract, lowest acceptable bid winning, is a reverse auction."}]}]}]},{"number":"10.4","title":"Benefits and limitations of e-commerce","mustKnow":[{"type":"paragraph","text":[{"text":"Benefits to organisations:","bold":true},{"text":" wider (national and global) market reach at low cost · lower costs of creating, processing and storing information · lower inventory and overheads · 24-hour trading · customisation of products · faster communication with customers and partners · new business models."}]},{"type":"paragraph","text":[{"text":"Benefits to consumers:","bold":true},{"text":" shopping any time, anywhere · more choice of products and sellers · price comparison and often lower prices · quick delivery of digital products · participation in auctions · interaction with other consumers (reviews)."}]},{"type":"paragraph","text":[{"text":"Benefits to society:","bold":true},{"text":" people can work and shop from home, reducing travel and traffic · lower prices help the less well-off · access to services (education, health information, government services) in remote areas."}]},{"type":"table","header":[[{"text":"Limitations"}],[{"text":"Examples"}]],"rows":[[[{"text":"Technological","bold":true}],[{"text":"Poor or expensive internet access in some areas · limited bandwidth · weak security standards · difficulty integrating EC with existing systems"}]],[[{"text":"Non-technological","bold":true}],[{"text":"Fear of "},{"text":"fraud","bold":true},{"text":" and doubts about "},{"text":"security and privacy","bold":true},{"text":" · lack of "},{"text":"trust","bold":true},{"text":" in unseen sellers · customers wanting to touch and inspect goods · unclear legal issues · delivery (logistics) problems · not enough buyers and sellers for some markets"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Many Nigerian shoppers prefer to pay on delivery because they are wary of paying in advance to a seller they cannot see. That is a "},{"text":"trust","bold":true},{"text":" limitation, not a technological one."}]},{"text":[{"text":"Personal data collected online is protected under the "},{"text":"Nigeria Data Protection Act 2023","bold":true},{"text":", an example of public policy as a support area."}]},{"text":[{"text":"Physical delivery in congested cities and to rural areas is a logistics limitation, solved partly by pick-up stations."}]}]}]},{"number":"10.5","title":"The communication process and channels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication:","bold":true},{"text":" the process of transferring "},{"text":"information and understanding","bold":true},{"text":" from one person (or group) to another. It has happened only when the receiver "},{"text":"understands","bold":true},{"text":" the message as the sender intended."}]}]},{"type":"paragraph","text":[{"text":"The basic communication model:","bold":true},{"text":" "},{"text":"sender, the message, channel, receiver and feedback.","bold":true},{"text":" In full, the process runs:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender","bold":true},{"text":" has an idea and "},{"text":"encodes","bold":true},{"text":" it (puts it into words, symbols or gestures)."}]},{"text":[{"text":"Message:","bold":true},{"text":" the encoded idea."}]},{"text":[{"text":"Channel (medium):","bold":true},{"text":" the means used to carry it (face-to-face, phone, email, letter)."}]},{"text":[{"text":"Receiver","bold":true},{"text":" "},{"text":"decodes","bold":true},{"text":" (interprets) it."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the receiver's response, which tells the sender whether the message was understood. It makes communication "},{"text":"two-way","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise:","bold":true},{"text":" anything that distorts or interrupts the message at any stage (a loud generator, a bad network, jargon, distraction)."}]}]},{"type":"paragraph","text":[{"text":"Ways of receiving information:","bold":true},{"text":" "},{"text":"visual","bold":true},{"text":" (seeing), "},{"text":"auditory","bold":true},{"text":" (hearing) and "},{"text":"kinesthetic","bold":true},{"text":" (doing, touching, feeling)."}]},{"type":"paragraph","text":[{"text":"Channels of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Oral (verbal):","bold":true},{"text":" face-to-face talk, meetings, phone calls. Fast, with instant feedback, but leaves no permanent record."}]},{"text":[{"text":"Written:","bold":true},{"text":" letters, memos, reports, emails, notices. A permanent record, but slower and with delayed feedback."}]},{"text":[{"text":"Non-verbal:","bold":true},{"text":" body language, facial expression, gestures, tone of voice, posture."}]},{"text":[{"text":"Electronic/digital:","bold":true},{"text":" email, video calls, intranet, instant messaging, social media."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" noise and barriers are "},{"text":"not","bold":true},{"text":" elements of the basic model; they are what disturb it. Any option listing \"noise\", \"barriers\", \"data\" or \"para-verbal\" as core elements is wrong."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"shouting\" is not a way of receiving information, and \"auditory and visual only\" leaves out "},{"text":"kinesthetic","bold":true},{"text":"."}]},{"text":[{"text":"Channel richness:","bold":true},{"text":" face-to-face is the "},{"text":"richest","bold":true},{"text":" channel (voice, body language and instant feedback together); a printed notice is among the leanest. Use rich channels for sensitive or complex messages, such as telling a staff member he is being transferred."}]}]}]},{"number":"10.6","title":"Formal and informal communication; barriers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Formal communication:","bold":true},{"text":" flows through the "},{"text":"official","bold":true},{"text":" lines of authority laid down by the organisation's structure."}]}]},{"type":"paragraph","text":[{"text":"Directions of formal communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Downward:","bold":true},{"text":" superior to subordinate (instructions, policies, feedback on performance)."}]},{"text":[{"text":"Upward:","bold":true},{"text":" subordinate to superior (reports, suggestions, complaints)."}]},{"text":[{"text":"Horizontal (lateral):","bold":true},{"text":" between people at the "},{"text":"same level","bold":true},{"text":", often across departments, for coordination."}]},{"text":[{"text":"Diagonal (cross-wise):","bold":true},{"text":" between people at "},{"text":"different levels in different departments","bold":true},{"text":", e.g. a sales officer contacting the finance manager directly."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Informal communication (the grapevine):","bold":true},{"text":" the unofficial network that grows from social relationships among staff and does not follow the chain of command. It is fast and can carry rumours."}]}]},{"type":"paragraph","text":[{"text":"Uses of the grapevine:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Acts as a "},{"text":"safety valve","bold":true},{"text":": employees let off steam and express feelings."}]},{"text":[{"text":"Helps employees enjoy "},{"text":"friendly relationships","bold":true},{"text":" and builds group unity."}]},{"text":[{"text":"Helps the organisation "},{"text":"discover gaps","bold":true},{"text":": problems and attitudes management did not know about."}]},{"text":[{"text":"Spreads information "},{"text":"quickly","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Barriers to effective communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical:","bold":true},{"text":" noise, distance, poor network or equipment."}]},{"text":[{"text":"Semantic (language):","bold":true},{"text":" jargon, words with different meanings, poor translation."}]},{"text":[{"text":"Perceptual:","bold":true},{"text":" people interpret the same message differently."}]},{"text":[{"text":"Emotional/psychological:","bold":true},{"text":" anger, fear, distrust, prejudice."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" different customs, values and gestures."}]},{"text":[{"text":"Organisational:","bold":true},{"text":" too many levels, rigid rules, status differences between boss and staff."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" more messages than the receiver can handle."}]},{"text":[{"text":"Poor listening","bold":true},{"text":" and lack of feedback."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the grapevine is "},{"text":"informal","bold":true},{"text":". Horizontal, diagonal, upward and downward are all "},{"text":"formal","bold":true},{"text":" directions. The question about a \"safety valve\" that \"helps organisations discover gaps\" always points to the grapevine."}]},{"text":[{"text":"Drawbacks of the grapevine: rumours, distortion, half-truths and leaks. Managers cannot abolish it, so they should feed it accurate information early."}]},{"text":[{"text":"Overcoming barriers:","bold":true},{"text":" use simple language, choose the right channel, listen actively, seek feedback, be aware of cultural differences, keep messages concise and factual, and cut unnecessary levels."}]},{"text":[{"text":"Good professional communication means: listen actively, give practical information, give facts rather than vague impressions, do not present opinions as facts, be concise, clarify expectations and responsibilities, and make persuasive, well-supported recommendations."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"E-commerce = online exchange of goods, services and money; it includes pre-purchase events and after-sale customer service."}]},{"text":[{"text":"E-business = conducting business on the internet; electronic communications for "},{"text":"all","bold":true},{"text":" business processes (wider than e-commerce)."}]},{"text":[{"text":"Perspectives on EC: communications, business process, service, online."}]},{"text":[{"text":"EC framework: infrastructure + 5 support areas (people, public policy, marketing and advertisement, support services, business partnerships). Competitors are not one."}]},{"text":[{"text":"Click-only = no storefronts; click-and-mortar = physical shops plus an EC component."}]},{"text":[{"text":"B2B, B2C, C2C (Jiji), B2E (intranet job posting), c-commerce (Boeing), m-commerce (m = mobile)."}]},{"text":[{"text":"Forward auction = one seller, many buyers (most common); reverse auction = electronic tendering, one buyer, many sellers."}]},{"text":[{"text":"Communication model: sender, message, channel, receiver, feedback; noise disturbs it."}]},{"text":[{"text":"Receiving information: visual, auditory, kinesthetic."}]},{"text":[{"text":"Grapevine = informal; safety valve, friendly relationships, discovers gaps."}]}]}],"theory":{"itemId":"45748893-ca91-51ce-974f-4428998bdbb0","question":[{"type":"paragraph","text":[{"text":"Distinguish between e-commerce and e-business, and explain four types of e-commerce transactions with examples."}]}]}}},{"itemId":"b9f822a9-93cf-51c1-8461-5cef9fa94f0b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Understanding Basic Economics","body":"What an economy is and its levels; scarcity and the factors of production; the economic systems (market, command, mixed, with socialism and communism); demand, supply and equilibrium; the macro view (competition, business cycles, unemployment, inflation); government's role in a free market; the economic measures and monitors (GDP, GNP, CPI, PPI and others).","noteType":"guide_topic","number":2,"mustKnow":[{"text":"What an economy is and its levels; scarcity and the factors of production; the economic systems (market, command, mixed, with socialism and communism); demand, supply and equilibrium; the macro view (competition, business cycles, unemployment, inflation); government's role in a free market; the economic measures and monitors (GDP, GNP, CPI, PPI and others)."}],"lessons":[{"number":"2.1","title":"The economy and the factors of production","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economics:","bold":true},{"text":" the study of how a society uses scarce resources to produce and distribute goods and services."}]},{"text":[{"text":"Economy:","bold":true},{"text":" the system (framework) through which a society produces, distributes, exchanges and consumes goods and services. More fully: the management of national, regional or household resources in terms of production capacity, monetary system, distribution of resources, and the principles or ideology that govern how resources are shared. It sums up a society's economic activities as they affect individuals and businesses."}]},{"text":[{"text":"5 levels at which we speak of \"an economy\":","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Nation:","bold":true},{"text":" e.g. the Nigerian, Ghanaian, US or Cuban economy."}]},{"text":[{"text":"State or region:","bold":true},{"text":" e.g. the Lagos State economy, the Northern region economy."}]},{"text":[{"text":"Industry:","bold":true},{"text":" e.g. the oil and gas economy, the agricultural economy of Nigeria."}]},{"text":[{"text":"Household or family:","bold":true},{"text":" e.g. a family's income and spending."}]},{"text":[{"text":"Institution:","bold":true},{"text":" e.g. the Unilag economy, the volume and size of all business activity around the campus."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Microeconomics:","bold":true},{"text":" the study of individual units: a consumer, a household, a firm, a single market (a firm's earnings, a worker's salary, a company's overheads)."}]},{"text":[{"text":"Macroeconomics:","bold":true},{"text":" the study of the economy as a whole: total output (GDP), inflation, unemployment, growth."}]},{"text":[{"text":"4 traditional factors of production:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Land","bold":true},{"text":" (natural resources): land, water, minerals, forests, crude oil."}]},{"text":[{"text":"Labour","bold":true},{"text":" (human resources): the physical and mental effort of people."}]},{"text":[{"text":"Capital:","bold":true},{"text":" man-made aids to production: machines, tools, buildings, and the money used to buy them."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" the willingness to take risks to combine the other factors into a business."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Scarcity","bold":true},{"text":" is the basic economic problem: unlimited wants, limited resources. Every choice is a "},{"text":"trade-off","bold":true},{"text":"; the best alternative given up is the "},{"text":"opportunity cost","bold":true},{"text":" (spend ₦20,000 on a phone accessory and the textbooks you could have bought are the opportunity cost)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" technology, information and knowledge improve how the factors work, and "},{"text":"knowledge","bold":true},{"text":" is sometimes added as a fifth factor. But when a question asks for the "},{"text":"four traditional","bold":true},{"text":" factors, the answer is land, labour, capital and entrepreneurship. \"Technology\", \"money supply\" or \"government\" are not among the four."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Economy\" is not a tax mechanism, an advertising system or a staff-control tool. It is the whole framework for producing and exchanging goods and services."}]}]}]},{"number":"2.2","title":"Economic systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economic system:","bold":true},{"text":" the policies that define how a society distributes its resources to satisfy its people's needs. Every system must answer: "},{"text":"what","bold":true},{"text":" to produce, "},{"text":"how","bold":true},{"text":" to produce it, and "},{"text":"for whom","bold":true},{"text":"."}]},{"text":[{"text":"3 broad systems:","bold":true},{"text":" market, command (planned), mixed."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Market (free-market, capitalism)"}],[{"text":"Command (planned)"}],[{"text":"Mixed"}]],"rows":[[[{"text":"Who owns resources"}],[{"text":"Private individuals and firms"}],[{"text":"Government owns key businesses"}],[{"text":"Private, public and joint sectors co-exist"}]],[[{"text":"Who decides what to produce"}],[{"text":"Demand and supply (price mechanism)"}],[{"text":"Central government planning"}],[{"text":"Both market forces and government"}]],[[{"text":"Competition"}],[{"text":"Strong"}],[{"text":"Lacking"}],[{"text":"Present, but regulated"}]],[[{"text":"Consumer choice"}],[{"text":"Freedom of choice"}],[{"text":"Limited"}],[{"text":"Economic freedom with social welfare"}]],[[{"text":"Government role"}],[{"text":"Limited intervention"}],[{"text":"Controls wages, means of production, what and how to produce"}],[{"text":"Regulates, redistributes; regulatory bodies prominent"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market economy characteristics:","bold":true},{"text":" competition, private ownership of resources, freedom of choice, price mechanism, limited government intervention, efficient allocation of resources (at the equilibrium point)."}]},{"text":[{"text":"Command economy characteristics:","bold":true},{"text":" government ownership of key businesses, government intervention, government control of wages and means of production, centralised economic planning, lack of competition, limited consumer choice, government decides what and how to produce. Resources are allocated by "},{"text":"central government authority","bold":true},{"text":"."}]},{"text":[{"text":"Mixed economy characteristics:","bold":true},{"text":" social welfare, mixed ownership of property, economic freedom, co-existence of private, public and joint sectors, resources allocated by both government and market forces, prominent government-owned regulatory bodies, redistribution of resources to achieve economic and social goals. Also called a "},{"text":"welfarist state","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capitalism","bold":true},{"text":" is the market system: private owners and the profit motive drive the economy. "},{"text":"Pure capitalism","bold":true},{"text":" (no government role at all) does not exist anywhere."}]},{"text":[{"text":"Planned systems come in two forms:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communism:","bold":true},{"text":" the government owns and operates all productive resources; private property is largely eliminated. The state decides all production and prices. Cuba and North Korea are the usual examples."}]},{"text":[{"text":"Socialism:","bold":true},{"text":" the government owns and runs "},{"text":"selected major industries","bold":true},{"text":" (e.g. power, transport, banking), while private businesses operate in the rest. It stresses social welfare and equal distribution."}]}]}]},{"text":[{"text":"Mixed economy","bold":true},{"text":" = market freedom "},{"text":"plus","bold":true},{"text":" state control. Nigeria is a mixed economy: private firms such as Dangote, MTN and the banks operate alongside government agencies and regulators such as the Central Bank of Nigeria (CBN), SEC and SON. Most countries today are mixed."}]},{"text":[{"text":"Privatisation","bold":true},{"text":" moves businesses from government to private ownership; "},{"text":"nationalisation","bold":true},{"text":" is the reverse. "},{"text":"Deregulation","bold":true},{"text":" removes or relaxes government rules on an industry (e.g. Nigeria's telecoms deregulation, which let private mobile operators in)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a mixed economy combines market and command features. It is not a mix of \"tradition and customs\" (that is a "},{"text":"traditional economy","bold":true},{"text":", based on custom), and it is not \"all economic systems\"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" state production quotas, absence of competition and uniform allocation describe a command economy, never a free market."}]}]}]},{"number":"2.3","title":"Demand, supply and equilibrium","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand:","bold":true},{"text":" the quantity of a good or service buyers are willing and able to buy at various prices."}]},{"text":[{"text":"Law of demand:","bold":true},{"text":" other things being equal, as price "},{"text":"falls","bold":true},{"text":", quantity demanded "},{"text":"rises","bold":true},{"text":"; as price rises, quantity demanded falls. Lower prices spur demand. The demand curve slopes "},{"text":"downward","bold":true},{"text":"."}]},{"text":[{"text":"Supply:","bold":true},{"text":" the quantity sellers are willing and able to offer for sale at various prices."}]},{"text":[{"text":"Law of supply:","bold":true},{"text":" other things being equal, as price "},{"text":"rises","bold":true},{"text":", quantity supplied "},{"text":"rises","bold":true},{"text":"; rising prices lift supply. The supply curve slopes "},{"text":"upward","bold":true},{"text":"."}]},{"text":[{"text":"Equilibrium price (market price):","bold":true},{"text":" the price at which the demand curve and supply curve intersect, where quantity demanded equals quantity supplied. It is the optimal price for allocating resources or goods."}]},{"text":[{"text":"Relevance of demand and supply (price mechanism) in a market economy:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It determines the distribution of goods and the allocation of resources."}]},{"text":[{"text":"It reduces, if not eliminates, government intervention in resource allocation in many sectors."}]},{"text":[{"text":"It determines the production of goods and their prices."}]},{"text":[{"text":"The equilibrium price stands as the optimal price to allocate resources or goods."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand shifters:","bold":true},{"text":" income, prices of substitutes and complements, tastes, expectations, number of buyers. "},{"text":"Supply shifters:","bold":true},{"text":" input costs, technology, expectations, number of producers, prices of other goods the producer could make. Dearer diesel cuts the supply of bread at every price."}]},{"text":[{"text":"A change in the good's "},{"text":"own price","bold":true},{"text":" moves you "},{"text":"along","bold":true},{"text":" the curve (change in quantity demanded or supplied). A change in any other factor "},{"text":"shifts","bold":true},{"text":" the curve."}]},{"text":[{"text":"Surplus:","bold":true},{"text":" price above equilibrium, so supply exceeds demand; sellers cut prices. "},{"text":"Shortage:","bold":true},{"text":" price below equilibrium, so demand exceeds supply; prices rise. Both push the market back to equilibrium."}]}]}]},{"number":"2.4","title":"The macro view: competition, business cycles, unemployment and inflation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Competition:","bold":true},{"text":" rivalry among businesses for the same customers. "},{"text":"4 market structures:","bold":true}]}]},{"type":"table","header":[[{"text":"Structure"}],[{"text":"Number of sellers"}],[{"text":"Products"}],[{"text":"Example"}]],"rows":[[[{"text":"Pure (perfect) competition","bold":true}],[{"text":"Very many"}],[{"text":"Identical; no seller controls price"}],[{"text":"Farm produce such as maize or tomatoes in an open market"}]],[[{"text":"Monopolistic competition","bold":true}],[{"text":"Many"}],[{"text":"Slightly different (branding, quality)"}],[{"text":"Restaurants, fast food, hair salons, clothing"}]],[[{"text":"Oligopoly","bold":true}],[{"text":"Few large firms"}],[{"text":"Similar or differentiated; high entry barriers"}],[{"text":"Telecoms (MTN, Airtel, Glo, 9mobile), cement, airlines"}]],[[{"text":"Monopoly","bold":true}],[{"text":"One"}],[{"text":"No close substitute"}],[{"text":"Electricity transmission, water utilities"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business cycle:","bold":true},{"text":" the rise and fall of economic activity over time. Phases: "},{"text":"expansion","bold":true},{"text":" (growth) → "},{"text":"peak","bold":true},{"text":" → "},{"text":"contraction","bold":true},{"text":" (recession) → "},{"text":"trough","bold":true},{"text":" → recovery."}]},{"text":[{"text":"Recession:","bold":true},{"text":" a period of falling economic activity; commonly, two consecutive quarters of falling GDP. "},{"text":"Depression:","bold":true},{"text":" a deep, prolonged recession."}]},{"text":[{"text":"Unemployment:","bold":true},{"text":" people actively seeking work who cannot find it. "},{"text":"4 types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Frictional:","bold":true},{"text":" temporarily between jobs (e.g. a new graduate searching)."}]},{"text":[{"text":"Structural:","bold":true},{"text":" skills do not match available jobs, often from technology or industry change."}]},{"text":[{"text":"Cyclical:","bold":true},{"text":" caused by a downturn in the business cycle."}]},{"text":[{"text":"Seasonal:","bold":true},{"text":" tied to seasons (e.g. farm labour after harvest)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" a steady, general rise in the prices of goods and services over time; it reduces the purchasing power of money. "},{"text":"Deflation:","bold":true},{"text":" a sustained fall in general prices. Inflation is a measure of the condition of the economy."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopolies often arise in utilities because building power or water networks is so costly that one supplier serving an area is more efficient. Electric utilities are the standard example; fast food, online retail and smartphones face many competitors."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a "},{"text":"recession","bold":true},{"text":" is the contraction phase; the "},{"text":"trough","bold":true},{"text":" is its lowest point, not the start."}]}]}]},{"number":"2.5","title":"Government's role in a free-market system","mustKnow":[{"type":"paragraph","text":[{"text":"6 roles of government in a free-market system:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provide the legal and social framework","bold":true},{"text":" and enforce the rules of fair play: protecting property rights, enforcing contracts, protecting consumers."}]},{"text":[{"text":"Ensure economic stability","bold":true},{"text":" through different models and frameworks, including "},{"text":"monetary","bold":true},{"text":" decisions."}]},{"text":[{"text":"Maintain competition","bold":true},{"text":" in the marketplace, with an "},{"text":"anti-trust","bold":true},{"text":" body to monitor abuse."}]},{"text":[{"text":"Provide public goods and services","bold":true},{"text":", e.g. postal system, water, education, health."}]},{"text":[{"text":"Redistribute income","bold":true},{"text":" to cater for the weak and under-privileged and reduce the income gap."}]},{"text":[{"text":"Deal with the international community and economic blocs","bold":true},{"text":" to determine trade and economic relationships."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Monetary policy:","bold":true},{"text":" the central bank's control of the "},{"text":"money supply and interest rates","bold":true},{"text":" to stabilise the economy. In Nigeria this is done by the "},{"text":"Central Bank of Nigeria (CBN)","bold":true},{"text":"."}]},{"text":[{"text":"Fiscal policy:","bold":true},{"text":" the government's use of "},{"text":"taxation and public spending","bold":true},{"text":" to influence the economy."}]},{"text":[{"text":"Taxes:","bold":true},{"text":" a major source of government revenue (income tax, companies income tax, value added tax (VAT), customs duties)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In a free market the government "},{"text":"sets and enforces the rules","bold":true},{"text":"; it does not fix all prices, direct all firms or cancel market forces (those describe a command economy)."}]},{"text":[{"text":"Regulation","bold":true},{"text":" protects stakeholders. Nigerian examples: the "},{"text":"Federal Competition and Consumer Protection Commission (FCCPC)","bold":true},{"text":" fights unfair competition and protects consumers; "},{"text":"SON","bold":true},{"text":" (Standards Organisation of Nigeria) sets product standards; "},{"text":"NAFDAC","bold":true},{"text":" regulates food and drugs; "},{"text":"SEC","bold":true},{"text":" regulates the capital market; "},{"text":"CAC","bold":true},{"text":" (Corporate Affairs Commission) registers businesses under the Companies and Allied Matters Act (CAMA) 2020."}]},{"text":[{"text":"Monetary tools:","bold":true},{"text":" raising interest rates and reducing money supply to fight inflation (tight policy); lowering rates to boost borrowing and growth (loose policy)."}]},{"text":[{"text":"Fiscal tools:","bold":true},{"text":" cutting taxes or raising spending to stimulate a slow economy; raising taxes or cutting spending to cool an overheating one."}]},{"text":[{"text":"Trap:","bold":true},{"text":" monetary = central bank, money and interest rates. Fiscal = government, taxes and spending. Exams swap them."}]}]}]},{"number":"2.6","title":"Economic measures and monitors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gross Domestic Product (GDP):","bold":true},{"text":" the total value of all final goods and services produced "},{"text":"within a country's borders","bold":true},{"text":" in a given period (usually a year), whoever owns the producers. It is the main measure of "},{"text":"economic growth","bold":true},{"text":" and a key macroeconomic indicator."}]},{"text":[{"text":"Gross National Product (GNP):","bold":true},{"text":" the total value of goods and services produced by a country's "},{"text":"citizens and businesses","bold":true},{"text":", wherever in the world they are located."}]},{"text":[{"text":"Per capita income:","bold":true},{"text":" national income divided by population; average income per person."}]},{"text":[{"text":"Consumer Price Index (CPI):","bold":true},{"text":" measures changes over time in the prices of a \"basket\" of goods and services typically bought by consumers; the main measure of "},{"text":"inflation","bold":true},{"text":"."}]},{"text":[{"text":"Producer Price Index (PPI):","bold":true},{"text":" measures changes over time in the prices producers receive for their goods (wholesale prices); it often signals future consumer price changes."}]},{"text":[{"text":"Unemployment rate:","bold":true},{"text":" the percentage of the labour force actively seeking work but without a job."}]}]},{"type":"paragraph","text":[{"text":"Measures and monitors of an economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"GDP and per capita income."}]},{"text":[{"text":"Level of investment (e.g. foreign direct investment, FDI) and volume of international trade (export trade, and non-oil exports in Nigeria)."}]},{"text":[{"text":"Inflation rate and CPI; consumption level and the purchasing power of the currency (e.g. the naira)."}]},{"text":[{"text":"National employment figures and the unemployment level or rate."}]},{"text":[{"text":"Level of infrastructural development."}]},{"text":[{"text":"Non-economic metrics: life expectancy, poverty rate, literacy rate, political stability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"GDP vs GNP:","bold":true},{"text":" profits made in Nigeria by a foreign-owned company count in Nigeria's "},{"text":"GDP","bold":true},{"text":" but in its home country's "},{"text":"GNP","bold":true},{"text":". Income earned abroad by Nigerian firms counts in Nigeria's GNP, not its GDP."}]},{"text":[{"text":"In Nigeria, GDP, CPI and unemployment figures are published by the "},{"text":"National Bureau of Statistics (NBS)","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" GDP measures growth; CPI measures the price level (inflation); the unemployment rate measures joblessness; interest rates measure the cost of borrowing. Only GDP measures growth directly."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a firm's quarterly earnings, a worker's salary or a company's overheads are "},{"text":"micro","bold":true},{"text":" figures, not macroeconomic indicators."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economy = framework for producing, distributing and exchanging goods and services; can be national, regional, industry, household or institutional."}]},{"text":[{"text":"Scarcity forces trade-offs; the 4 traditional factors are land, labour, capital, entrepreneurship (not technology)."}]},{"text":[{"text":"Market = price mechanism and private ownership; command = central government allocates; mixed = market freedom plus state control."}]},{"text":[{"text":"Communism: state owns all productive resources; socialism: state owns selected major industries."}]},{"text":[{"text":"Law of demand: lower price, more demanded. Law of supply: higher price, more supplied. Equilibrium where the curves meet."}]},{"text":[{"text":"Market structures: pure competition, monopolistic competition, oligopoly, monopoly (utilities)."}]},{"text":[{"text":"Business cycle: expansion, peak, contraction, trough. Unemployment: frictional, structural, cyclical, seasonal. Inflation = general rise in prices."}]},{"text":[{"text":"Government in a free market enforces fair-play rules, keeps competition, provides public goods, redistributes income, stabilises via monetary (CBN) and fiscal (tax and spending) policy."}]},{"text":[{"text":"GDP measures growth (within borders); GNP counts citizens' output anywhere; CPI tracks consumer prices; PPI tracks producer prices."}]}]}],"theory":{"itemId":"a920fd06-e86d-5415-ba0d-9a989c7f7d21","question":[{"type":"paragraph","text":[{"text":"Distinguish between a market economy and a command economy, and explain the role of government in a free-market system."}]}]},"practice":[{"topic":"Understanding Basic Economics","named":false}]}},{"itemId":"d03011c7-23bf-530b-8fb1-301f792707a2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"The Global Marketplace","body":"Why nations trade; absolute and comparative advantage; balance of trade and balance of payments; exchange rates; free trade vs protectionism and the trade barriers; the WTO, IMF, World Bank and the trading blocs; cultural, legal, political and economic differences abroad; the forms of international business; multidomestic, global and transnational strategies.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"Why nations trade; absolute and comparative advantage; balance of trade and balance of payments; exchange rates; free trade vs protectionism and the trade barriers; the WTO, IMF, World Bank and the trading blocs; cultural, legal, political and economic differences abroad; the forms of international business; multidomestic, global and transnational strategies."}],"lessons":[{"number":"3.1","title":"What international trade is and why nations trade","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade:","bold":true},{"text":" the exchange of goods and services across national borders. Trade inside one country is "},{"text":"domestic trade","bold":true},{"text":"."}]},{"text":[{"text":"Global (international) business:","bold":true},{"text":" a business that operates in several countries. A "},{"text":"domestic business","bold":true},{"text":" operates in one country only."}]},{"text":[{"text":"Multinational corporation (MNC):","bold":true},{"text":" a company with operations (offices, factories, sales units) in several national markets, e.g. MTN, Nestlé, Unilever."}]},{"text":[{"text":"Importing:","bold":true},{"text":" buying goods or services from another country. "},{"text":"Exporting:","bold":true},{"text":" producing in one country and selling to buyers in another. Both are forms of global business engagement."}]},{"text":[{"text":"Why nations and firms trade:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To focus on their "},{"text":"strengths","bold":true},{"text":" (what they produce best)."}]},{"text":[{"text":"To "},{"text":"expand markets","bold":true},{"text":": broader market access and more customers."}]},{"text":[{"text":"To pursue "},{"text":"economies of scale","bold":true},{"text":" (lower cost per unit from larger output)."}]},{"text":[{"text":"To "},{"text":"acquire","bold":true},{"text":" materials, goods and services they lack or cannot make cheaply."}]},{"text":[{"text":"To "},{"text":"keep up with customers","bold":true},{"text":" who have gone international."}]},{"text":[{"text":"To "},{"text":"keep up with competitors","bold":true},{"text":" already abroad."}]}]}]}]},{"type":"table","header":[[{"text":"Term"}],[{"text":"Meaning"}],[{"text":"Credited to"}]],"rows":[[[{"text":"Absolute advantage","bold":true}],[{"text":"A country can produce a good "},{"text":"more efficiently","bold":true},{"text":" (with fewer resources) than any other country"}],[{"text":"Adam Smith"}]],[[{"text":"Comparative advantage","bold":true}],[{"text":"A country produces the goods it makes "},{"text":"relatively","bold":true},{"text":" most efficiently (lowest opportunity cost) and trades for the rest, even if it is not the best at anything"}],[{"text":"David Ricardo"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade is "},{"text":"driven by comparative advantage","bold":true},{"text":". Nigeria exports crude oil and imports machinery because each country gains by specialising where its opportunity cost is lowest."}]},{"text":[{"text":"Example of comparative advantage: suppose Country A can make both cloth and cocoa faster than Country B, but its lead is much bigger in cloth. A should specialise in cloth and B in cocoa; both end up with more by trading."}]},{"text":[{"text":"Benefits of trade:","bold":true},{"text":" broader market access, lower costs through scale, wider choice of products, access to resources and technology. "},{"text":"Trap:","bold":true},{"text":" \"higher production costs\" and \"narrower product range\" are not benefits; trade tends to lower costs and widen choice."}]},{"text":[{"text":"A franchise or a partnership is a form of ownership or arrangement; neither term by itself means a firm operates in several countries."}]}]}]},{"number":"3.2","title":"Measuring trade and exchange rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Balance of trade:","bold":true},{"text":" the difference between the value of a country's "},{"text":"exports","bold":true},{"text":" and the value of its "},{"text":"imports","bold":true},{"text":" over a period (goods and services)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trade surplus (favourable balance):","bold":true},{"text":" exports > imports."}]},{"text":[{"text":"Trade deficit (unfavourable balance):","bold":true},{"text":" imports > exports."}]}]}]},{"text":[{"text":"Balance of payments:","bold":true},{"text":" the "},{"text":"total","bold":true},{"text":" of all money flowing into and out of a country over a period. It includes the balance of trade "},{"text":"plus","bold":true},{"text":" investment flows, foreign aid, loans, interest, dividends and transfers (e.g. remittances). It is the broader measure."}]},{"text":[{"text":"Exchange rate:","bold":true},{"text":" the rate at which one country's currency can be exchanged for another's, e.g. ₦ per US dollar."}]},{"text":[{"text":"Floating exchange rate:","bold":true},{"text":" set mainly by demand and supply in the currency market. "},{"text":"Fixed (pegged) rate:","bold":true},{"text":" held by the government or central bank at a set level."}]}]},{"type":"table","header":[[{"text":"If the naira"}],[{"text":"Nigerian exports become"}],[{"text":"Imports into Nigeria become"}]],"rows":[[[{"text":"Weakens","bold":true},{"text":" (more ₦ per $; depreciation or devaluation)"}],[{"text":"Cheaper to foreigners (helps exporters)"}],[{"text":"Dearer (hurts importers)"}]],[[{"text":"Strengthens","bold":true},{"text":" (fewer ₦ per $)"}],[{"text":"Dearer to foreigners"}],[{"text":"Cheaper"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" balance of trade is "},{"text":"not","bold":true},{"text":" GDP (total output), employment levels or inflation (price increases). It is only the export-import difference."}]},{"text":[{"text":"Trap:","bold":true},{"text":" balance of trade covers trade only; balance of payments covers trade "},{"text":"and","bold":true},{"text":" all other money flows. A country can have a trade deficit but still receive large inflows, e.g. foreign investment or diaspora remittances."}]},{"text":[{"text":"In Nigeria the Central Bank of Nigeria (CBN) manages monetary and exchange-rate policy. Exchange-rate movements are part of the economic environment of global business: a firm that buys raw materials in dollars and sells in naira is hurt when the naira falls."}]}]}]},{"number":"3.3","title":"Conflicts in international trade","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Free trade:","bold":true},{"text":" international trade with no government barriers. Supported because it raises efficiency, lowers prices and widens choice."}]},{"text":[{"text":"Protectionism:","bold":true},{"text":" government policies that restrict imports to protect domestic industries and jobs."}]},{"text":[{"text":"Trade conflicts","bold":true},{"text":" arise mainly from "},{"text":"barriers like import duties","bold":true},{"text":", tariffs and quotas, which can trigger retaliation (a "},{"text":"trade war","bold":true},{"text":"), e.g. the US-China trade tensions in which each side raised tariffs on the other's goods."}]}]},{"type":"paragraph","text":[{"text":"Main trade barriers and restrictions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Tariff:","bold":true},{"text":" a tax or levy on "},{"text":"imported","bold":true},{"text":" (inbound) goods. Raises the price of foreign products and protects local producers; also earns government revenue."}]},{"text":[{"text":"Import quota:","bold":true},{"text":" a limit on the "},{"text":"quantity","bold":true},{"text":" of a product that may be imported."}]},{"text":[{"text":"Embargo:","bold":true},{"text":" a total "},{"text":"ban","bold":true},{"text":" on trade in a product or with a country (often for political reasons)."}]},{"text":[{"text":"Restrictive import standards:","bold":true},{"text":" strict rules on quality, health, safety or labelling that make importing harder."}]},{"text":[{"text":"Export subsidy:","bold":true},{"text":" government payment or aid to domestic exporters so they can sell more cheaply abroad."}]},{"text":[{"text":"Sanctions:","bold":true},{"text":" politically motivated restrictions on trade with a country."}]},{"text":[{"text":"Anti-dumping measures:","bold":true},{"text":" actions against "},{"text":"dumping","bold":true},{"text":", i.e. selling goods abroad below cost or below the price charged at home, often to drive out local competitors."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" a tariff is "},{"text":"not","bold":true},{"text":" an export incentive payment (that is a subsidy), not a type of money (currency) and not a trade agreement."}]},{"text":[{"text":"Tariff vs quota:","bold":true},{"text":" a tariff works through "},{"text":"price","bold":true},{"text":"; a quota works through "},{"text":"quantity","bold":true},{"text":". An embargo is the extreme case: quantity is zero."}]},{"text":[{"text":"In Nigeria, import duties are collected by the Nigeria Customs Service. Restrictive standards are applied through bodies such as the Standards Organisation of Nigeria (SON)."}]},{"text":[{"text":"Arguments for protection: protect infant industries, save jobs, national security, fight unfair practices like dumping. Arguments against: higher prices for consumers, less choice, inefficient local firms and retaliation. Open policies, cooperative alliances and stable exchange rates tend to "},{"text":"reduce","bold":true},{"text":" conflict, not cause it."}]}]}]},{"number":"3.4","title":"International trade organisations and trading blocs","mustKnow":[{"type":"table","header":[[{"text":"Organisation"}],[{"text":"Main role"}]],"rows":[[[{"text":"WTO","bold":true},{"text":" (World Trade Organization), 1995, Geneva; replaced GATT"}],[{"text":"Promotes free and fair trade globally","bold":true},{"text":": sets trade rules, negotiates trade agreements, settles trade disputes"}]],[[{"text":"IMF","bold":true},{"text":" (International Monetary Fund)"}],[{"text":"Promotes "},{"text":"financial and exchange-rate stability","bold":true},{"text":"; lends to countries with balance-of-payments problems"}]],[[{"text":"World Bank","bold":true}],[{"text":"Lends and gives aid for "},{"text":"long-term development","bold":true},{"text":" projects (roads, power, health, education) in developing countries"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trading bloc:","bold":true},{"text":" a group of countries that reduce trade barriers among themselves and often act together on trade."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"ECOWAS","bold":true},{"text":" (Economic Community of West African States): founded 1975 by the Treaty of Lagos; promotes economic integration and free movement of people and goods in West Africa. Nigeria is a member."}]},{"text":[{"text":"AU","bold":true},{"text":" (African Union): replaced the Organisation of African Unity (OAU) in 2002; HQ Addis Ababa. Its "},{"text":"AfCFTA","bold":true},{"text":" (African Continental Free Trade Area) aims at a single African market."}]},{"text":[{"text":"EU","bold":true},{"text":" (European Union): European states with a single market; many share one currency, the "},{"text":"euro","bold":true},{"text":"."}]},{"text":[{"text":"NAFTA / USMCA:","bold":true},{"text":" the North American Free Trade Agreement (USA, Canada, Mexico) was replaced in 2020 by the "},{"text":"United States-Mexico-Canada Agreement (USMCA)","bold":true},{"text":"."}]},{"text":[{"text":"APEC","bold":true},{"text":" (Asia-Pacific Economic Cooperation): Pacific Rim economies (including the USA, China, Japan and Australia) promoting freer trade in the region."}]},{"text":[{"text":"ASEAN","bold":true},{"text":" (Association of Southeast Asian Nations)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the question \"which organisation promotes free trade globally?\" is the "},{"text":"WTO","bold":true},{"text":", not the IMF (finance), the UN (peace and security) or the WHO (health)."}]},{"text":[{"text":"IMF vs World Bank:","bold":true},{"text":" IMF = short-term financial stability and currency problems; World Bank = long-term development projects. Both were created at Bretton Woods in 1944 and are based in Washington, DC."}]},{"text":[{"text":"Blocs encourage trade "},{"text":"inside","bold":true},{"text":" the bloc but can make it harder for outsiders. ECOWAS, for instance, has a common external tariff applied to goods from outside the region."}]}]}]},{"number":"3.5","title":"The global business environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Global business environment:","bold":true},{"text":" the many forces that affect how a firm operates abroad, especially "},{"text":"cultural, political (legal) and economic","bold":true},{"text":" differences between countries. It is never just one factor (only money, only technology or only regulation)."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cultural differences:","bold":true},{"text":" language, religion, values, customs, social behaviour, attitudes to time, gift-giving, negotiation styles and body language. "},{"text":"Ethnocentrism","bold":true},{"text":" (judging others by your own culture) and "},{"text":"stereotyping","bold":true},{"text":" cause failure abroad."}]},{"text":[{"text":"Legal and political differences:","bold":true},{"text":" each country has its own laws on contracts, tax, ownership, labour and product standards; political stability and government attitudes to foreign firms vary. "},{"text":"Bribery","bold":true},{"text":" is illegal in most countries, e.g. the US Foreign Corrupt Practices Act forbids US firms to bribe foreign officials."}]},{"text":[{"text":"Economic differences:","bold":true},{"text":" level of development, income, infrastructure, inflation and "},{"text":"currency exchange rates","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A firm entering a new country must research its culture: a product name, colour or advert that works in Lagos may offend or confuse buyers elsewhere."}]},{"text":[{"text":"Trap:","bold":true},{"text":" ignoring local customs is a common reason firms fail abroad; it is never a sound strategy."}]},{"text":[{"text":"Political risk includes sudden policy changes, import bans, nationalisation of foreign assets and unrest."}]}]}]},{"number":"3.6","title":"Forms of international business and strategic approaches","mustKnow":[{"type":"paragraph","text":[{"text":"Forms of international business activity","bold":true},{"text":" (roughly from least to most commitment and risk):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Importing and exporting:","bold":true},{"text":" buying from and selling to other countries; the simplest entry."}]},{"text":[{"text":"International licensing:","bold":true},{"text":" a firm lets a foreign company use its patent, trademark, technology or brand for a fee ("},{"text":"royalty","bold":true},{"text":")."}]},{"text":[{"text":"International franchising:","bold":true},{"text":" a franchisor lets a foreign franchisee run a business under its name and system for fees, e.g. fast-food chains."}]},{"text":[{"text":"Contract manufacturing:","bold":true},{"text":" a firm pays a foreign producer to make its goods, which it then sells under its own name."}]},{"text":[{"text":"Strategic alliance:","bold":true},{"text":" a long-term partnership between firms to share resources or knowledge, "},{"text":"without","bold":true},{"text":" creating a new company."}]},{"text":[{"text":"Joint venture:","bold":true},{"text":" two or more firms (often a foreign and a local one) jointly "},{"text":"create and own","bold":true},{"text":" a new business, sharing costs, risks and profits."}]},{"text":[{"text":"Foreign direct investment (FDI):","bold":true},{"text":" owning physical assets in another country, e.g. building a factory or buying a local firm, often run as a "},{"text":"subsidiary","bold":true},{"text":". Firms that do this widely become "},{"text":"multinational corporations","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Strategic approaches to international markets:","bold":true}]},{"type":"table","header":[[{"text":"Approach"}],[{"text":"Product and marketing"}],[{"text":"Also called"}]],"rows":[[[{"text":"Multidomestic","bold":true}],[{"text":"Each country unit operates fairly independently; offerings "},{"text":"tailored","bold":true},{"text":" to each local market"}],[{"text":"Adaptation"}]],[[{"text":"Global","bold":true}],[{"text":"Same","bold":true},{"text":" product and marketing worldwide, controlled from headquarters; lowest cost"}],[{"text":"Standardisation"}]],[[{"text":"Transnational","bold":true}],[{"text":"Mix: global efficiency where possible, local adaptation where needed (\"think globally, act locally\")"}],[]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sound international strategy usually involves "},{"text":"tailoring offerings to regions","bold":true},{"text":" (adaptation) to suit local tastes, culture and needs. Overlooking local customs, shunning rivals or cutting exports are not strategies."}]},{"text":[{"text":"Standardisation vs adaptation:","bold":true},{"text":" standardisation gives economies of scale and one brand image; adaptation fits local markets better but costs more."}]},{"text":[{"text":"Licensing vs franchising:","bold":true},{"text":" licensing transfers the right to use a patent, trademark or technology; franchising transfers a whole way of running the business."}]},{"text":[{"text":"Strategic alliance vs joint venture:","bold":true},{"text":" both are partnerships; only a joint venture creates a "},{"text":"new jointly owned entity","bold":true},{"text":"."}]},{"text":[{"text":"Exporting, licensing and franchising need little investment and carry low risk, but give less control. FDI gives most control and profit but carries most risk."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade = cross-border exchange of goods and services, driven by comparative advantage."}]},{"text":[{"text":"Absolute advantage (Smith) = most efficient producer; comparative advantage (Ricardo) = lowest opportunity cost."}]},{"text":[{"text":"Balance of trade = exports minus imports; balance of payments = all money flows in and out."}]},{"text":[{"text":"A weaker naira makes exports cheaper and imports dearer."}]},{"text":[{"text":"Barriers: tariffs (levy on imports), quotas, embargoes, standards, subsidies, sanctions, anti-dumping; barriers like import duties cause trade conflicts."}]},{"text":[{"text":"WTO = free trade; IMF = financial stability; World Bank = development. Blocs: ECOWAS, AU, EU, USMCA, APEC, ASEAN."}]},{"text":[{"text":"Global environment = cultural, political/legal and economic differences."}]},{"text":[{"text":"Forms: import/export, licensing, franchising, contract manufacturing, alliances, joint ventures, FDI; an MNC operates in several national markets."}]},{"text":[{"text":"Strategies: multidomestic (adapt), global (standardise), transnational (mix)."}]}]}],"theory":{"itemId":"f4adf133-ee00-5bcd-a52b-549479b7fd84","question":[{"type":"paragraph","text":[{"text":"Explain four forms of international business activity a Nigerian firm could use to enter a foreign market."}]}]},"practice":[{"topic":"The Global Marketplace","named":false}]}},{"itemId":"a2b5c425-5cbd-5484-9cc8-9ccaa7ac9fbf","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Business Ethics and Corporate Social Responsibility","body":"What ethics and business ethics mean; unethical behaviour and what shapes behaviour; ethical dilemmas versus ethical lapses and how to make ethical decisions; CSR and its four perspectives; CSR towards the natural environment, consumers, employees and the community.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What ethics and business ethics mean; unethical behaviour and what shapes behaviour; ethical dilemmas versus ethical lapses and how to make ethical decisions; CSR and its four perspectives; CSR towards the natural environment, consumers, employees and the community."}],"lessons":[{"number":"4.1","title":"Ethics and ethical behaviour in business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ethics:","bold":true},{"text":" the rules or standards of right and wrong that govern the conduct of a person or a group."}]},{"text":[{"text":"Business ethics:","bold":true},{"text":" the standards of right and wrong (moral principles such as "},{"text":"honesty","bold":true},{"text":" and "},{"text":"fairness","bold":true},{"text":") that guide the decisions and behaviour of a business and its people."}]},{"text":[{"text":"Ethical company:","bold":true},{"text":" one that holds itself to standards that consider the needs of all its "},{"text":"stakeholders","bold":true},{"text":", not only its owners."}]},{"text":[{"text":"Stakeholders:","bold":true},{"text":" groups affected by, or able to affect, a business: owners/shareholders, employees, customers, suppliers, the community, government and society at large."}]}]},{"type":"paragraph","text":[{"text":"Three marks of unethical behaviour:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Competing unfairly and dishonestly:","bold":true},{"text":" bribery, fixing prices with rivals, stealing trade secrets, "},{"text":"insider trading","bold":true},{"text":" (using confidential company information to buy or sell shares)."}]},{"text":[{"text":"Communicating untruthfully:","bold":true},{"text":" false or misleading advertising, hiding product defects, falsifying financial records."}]},{"text":[{"text":"Causing harm to others:","bold":true},{"text":" selling unsafe products, polluting, exploiting workers, cheating investors."}]}]},{"type":"paragraph","text":[{"text":"Factors that influence ethical behaviour:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cultural differences:","bold":true},{"text":" what is acceptable (gifts, payments, hiring relatives) varies between countries and communities."}]},{"text":[{"text":"Knowledge:","bold":true},{"text":" people sometimes act wrongly because they do not know the facts, the law or the consequences."}]},{"text":[{"text":"Organisational behaviour:","bold":true},{"text":" the company's culture, leadership example, rewards and pressures."}]}]},{"type":"paragraph","text":[{"text":"Tools firms use to promote ethics:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Code of ethics:","bold":true},{"text":" a written statement of the principles that guide an organisation's decisions."}]},{"text":[{"text":"Ethics training","bold":true},{"text":" and ethics officers or hotlines."}]},{"text":[{"text":"Whistle-blowing:","bold":true},{"text":" disclosure by an insider of illegal or unethical conduct by others in the organisation."}]}]},{"type":"paragraph","text":[{"text":"Benefits of ethical practice:","bold":true},{"text":" enhanced "},{"text":"brand reputation","bold":true},{"text":", customer trust and loyalty, higher staff morale and retention, investor confidence, fewer fines and lawsuits."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal is not the same as ethical.","bold":true},{"text":" The law sets the minimum. An act can be legal yet unethical (charging desperate customers outrageous prices during a fuel scarcity), so ethics usually asks more than the law does."}]},{"text":[{"text":"Top managers "},{"text":"set the tone","bold":true},{"text":". A strong code of ethics means little if leaders reward results \"by any means\". In companies, the board of directors also sets the tone for ethical behaviour and can remove managers who behave unethically."}]},{"text":[{"text":"Unethical behaviour produces the opposite of the benefits: eroded consumer confidence, increased litigation costs, lower staff morale, regulatory sanctions and a damaged name."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"profit pursuit above all\", \"neglecting worker rights\" and \"bypassing legal oversight\" describe unethical conduct; they are never definitions of business ethics."}]}]}]},{"number":"4.2","title":"Ethical dilemmas, ethical lapses and making ethical decisions","mustKnow":[{"type":"table","header":[[],[{"text":"Ethical dilemma"}],[{"text":"Ethical lapse"}]],"rows":[[[{"text":"Meaning"}],[{"text":"A situation where "},{"text":"more than one side","bold":true},{"text":" of an issue can be supported with "},{"text":"valid arguments","bold":true}],[{"text":"A situation where an individual or group makes a decision that is clearly "},{"text":"wrong, illegal or unethical","bold":true}]],[[{"text":"Is the right answer clear?"}],[{"text":"No; it is a choice between competing goods or interests"}],[{"text":"Yes; the person knows (or should know) it is wrong"}]],[[{"text":"Example"}],[{"text":"Closing a loss-making plant to save the company, which costs local jobs"}],[{"text":"Inflating expense claims; selling expired drugs"}]]]},{"type":"paragraph","text":[{"text":"Four questions for making an ethical decision:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Is it legal?","bold":true},{"text":" Does it break any law or company policy?"}]},{"text":[{"text":"Is it balanced?","bold":true},{"text":" Is it fair to everyone affected in the short and long term?"}]},{"text":[{"text":"Can you live with it?","bold":true},{"text":" Would you be comfortable if your family or the newspapers knew about it?"}]},{"text":[{"text":"Is it feasible?","bold":true},{"text":" Can it actually work in the real world?"}]}]},{"type":"paragraph","text":[{"text":"Common ways of judging right and wrong:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Utilitarianism:","bold":true},{"text":" choose the action that gives the greatest good to the greatest number of people."}]},{"text":[{"text":"Individual rights:","bold":true},{"text":" respect people's basic rights (life, privacy, free speech, fair treatment)."}]},{"text":[{"text":"Justice:","bold":true},{"text":" treat people fairly and consistently, distributing benefits and burdens fairly."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In a "},{"text":"dilemma","bold":true},{"text":", both choices can be defended: a manager may be torn between loyalty to a long-serving supplier and a cheaper new one. The difficulty is not knowing the rule but weighing interests."}]},{"text":[{"text":"In a "},{"text":"lapse","bold":true},{"text":", the right choice is obvious and the person simply fails to make it, often under pressure to meet targets."}]},{"text":[{"text":"Trap:","bold":true},{"text":" exams swap the two definitions. \"Valid arguments on more than one side\" = "},{"text":"dilemma","bold":true},{"text":". \"Clearly wrong decision\" = "},{"text":"lapse","bold":true},{"text":"."}]},{"text":[{"text":"True professionals avoid committing ethical lapses and carefully weigh all the options when facing ethical dilemmas."}]}]}]},{"number":"4.3","title":"Corporate social responsibility and its perspectives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate social responsibility (CSR):","bold":true},{"text":" the idea that a business has obligations to society "},{"text":"beyond","bold":true},{"text":" its obligation to its owners or shareholders; a "},{"text":"duty to contribute to the well-being of society","bold":true},{"text":", not only to make profit."}]},{"text":[{"text":"CSR covers four broad groups: the "},{"text":"natural environment","bold":true},{"text":", "},{"text":"consumers","bold":true},{"text":", "},{"text":"employees","bold":true},{"text":" and the "},{"text":"community","bold":true},{"text":" (plus investors)."}]}]},{"type":"paragraph","text":[{"text":"Four perspectives on CSR:","bold":true}]},{"type":"table","header":[[{"text":"Perspective"}],[{"text":"Core view"}]],"rows":[[[{"text":"1. Minimalist","bold":true}],[{"text":"A firm's only social responsibility is to make "},{"text":"profits for its owners within the law","bold":true},{"text":" (obey laws, pay taxes)."}]],[[{"text":"2. Defensive","bold":true}],[{"text":"Firms engage in CSR mainly to "},{"text":"protect themselves","bold":true},{"text":": to avoid criticism, boycotts or tougher regulation."}]],[[{"text":"3. Cynical","bold":true}],[{"text":"CSR is a "},{"text":"public-relations or marketing tool","bold":true},{"text":"; firms adopt it only because it pays, often doing little real good."}]],[[{"text":"4. Proactive","bold":true}],[{"text":"CSR is a "},{"text":"moral obligation","bold":true},{"text":"; businesses have a duty to contribute to society because it is right, and see it as part of doing business."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Philanthropy:","bold":true},{"text":" donating money, staff time or other resources to social causes "},{"text":"without expecting a direct business benefit","bold":true},{"text":"."}]},{"text":[{"text":"Strategic CSR:","bold":true},{"text":" social contributions "},{"text":"aligned with the company's overall business strategy","bold":true},{"text":", so that both society and the company benefit."}]}]},{"type":"paragraph","text":[{"text":"Carroll's four responsibilities","bold":true},{"text":" (bottom to top of the pyramid):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economic:","bold":true},{"text":" be profitable (the base on which everything else rests)."}]},{"text":[{"text":"Legal:","bold":true},{"text":" obey the law."}]},{"text":[{"text":"Ethical:","bold":true},{"text":" do what is right and fair, beyond what the law requires."}]},{"text":[{"text":"Philanthropic:","bold":true},{"text":" be a good corporate citizen; give back to the community."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"minimalist","bold":true},{"text":" view is the "},{"text":"economic perspective","bold":true},{"text":", linked with the economist Milton Friedman: the business of business is to make profit, staying within the rules. Note that it does "},{"text":"not","bold":true},{"text":" say \"ignore society\" or \"exclude stakeholders\"; it says the firm serves society by making lawful profit, paying taxes and providing jobs."}]},{"text":[{"text":"The "},{"text":"proactive","bold":true},{"text":" view is the "},{"text":"duty-based (ethical) stance","bold":true},{"text":": CSR is done because it is morally right. A "},{"text":"compliance-focused","bold":true},{"text":" lens matches the defensive view; a "},{"text":"profit-driven","bold":true},{"text":" lens matches the minimalist or cynical view; a "},{"text":"charitable-giving","bold":true},{"text":" angle is philanthropy only."}]},{"text":[{"text":"Greenwashing","bold":true},{"text":" (exaggerating how environmentally friendly a firm is) is typical of the cynical view."}]},{"text":[{"text":"Strategic CSR example:","bold":true},{"text":" a telecoms company funding digital-skills training for young people builds future customers and staff while helping society. "},{"text":"Philanthropy example:","bold":true},{"text":" a bank donating to flood victims with no link to its business."}]},{"text":[{"text":"CSR towards the community","bold":true},{"text":" includes backing local nonprofits and charities, funding schools, scholarships, health centres and roads, employing local people and buying from local suppliers. Many large Nigerian firms, such as Dangote, MTN and the banks, run foundations for this purpose."}]},{"text":[{"text":"Remember the positive role of business in society: offering valuable goods and services, providing employment, paying taxes and contributing to national growth, stability and security. Its potential negative effects: generating pollution and waste, creating health and safety risks, disrupting communities and causing financial instability. CSR aims to increase the first and reduce the second."}]}]}]},{"number":"4.4","title":"CSR towards the natural environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pollution:","bold":true},{"text":" damage to the air, water or land caused by waste, chemicals, smoke, noise and other harmful releases."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Air pollution:","bold":true},{"text":" factory and generator fumes, vehicle exhaust, "},{"text":"gas flaring","bold":true},{"text":"."}]},{"text":[{"text":"Water pollution:","bold":true},{"text":" oil spills, untreated industrial waste discharged into rivers and lagoons."}]},{"text":[{"text":"Land pollution:","bold":true},{"text":" dumping of solid and toxic waste, plastics."}]}]}]},{"text":[{"text":"Carbon footprint:","bold":true},{"text":" the total greenhouse gases (mainly carbon dioxide) produced by an organisation's activities."}]},{"text":[{"text":"Sustainability (sustainable development):","bold":true},{"text":" meeting the needs of the present "},{"text":"without compromising the ability of future generations to meet their own needs","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Responsible environmental actions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Lowering carbon footprints","bold":true},{"text":" (cleaner energy, efficient machines and transport)."}]},{"text":[{"text":"Proper "},{"text":"waste management","bold":true},{"text":": reduce, reuse, recycle."}]},{"text":[{"text":"Conserving natural resources","bold":true},{"text":" (water, forests, energy) rather than depleting them."}]},{"text":[{"text":"Obeying environmental regulations","bold":true},{"text":" and cleaning up damage caused."}]},{"text":[{"text":"Designing greener products and packaging."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In Nigeria, the "},{"text":"National Environmental Standards and Regulations Enforcement Agency (NESREA)","bold":true},{"text":" enforces environmental standards, and oil spills and gas flaring in the Niger Delta are the best-known local examples of corporate environmental harm."}]},{"text":[{"text":"Trade-offs:","bold":true},{"text":" going green can raise costs in the short run, which is why some firms resist. Proactive firms see sustainability as a long-term saving and a source of reputation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"boosting emissions\", \"disregarding regulations\" and \"depleting natural reserves\" are the opposite of environmental CSR. The correct answer is always the one that "},{"text":"reduces harm","bold":true},{"text":", such as lowering carbon footprints."}]}]}]},{"number":"4.5","title":"CSR towards consumers and employees","mustKnow":[{"type":"paragraph","text":[{"text":"Consumer rights","bold":true},{"text":" (first set out by US President John F. Kennedy in 1962):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The right to safety:","bold":true},{"text":" to buy products that are safe to use."}]},{"text":[{"text":"The right to be informed:","bold":true},{"text":" to honest, clear information (labels, prices, ingredients, risks)."}]},{"text":[{"text":"The right to choose:","bold":true},{"text":" to choose freely among competing products at fair prices."}]},{"text":[{"text":"The right to be heard:","bold":true},{"text":" to have complaints listened to and handled."}]}]},{"type":"paragraph","text":[{"text":"Later additions: the right to "},{"text":"redress","bold":true},{"text":" (compensation for faulty goods), to "},{"text":"consumer education","bold":true},{"text":", to "},{"text":"privacy","bold":true},{"text":" of personal data and to a "},{"text":"healthy environment","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CSR towards consumers","bold":true},{"text":" means "},{"text":"ensuring product safety and clarity","bold":true},{"text":": safe products, honest advertising, clear labels, fair pricing, good quality and listening to customer complaints."}]}]},{"type":"paragraph","text":[{"text":"CSR towards employees:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Equality:","bold":true},{"text":" equal opportunity in hiring, pay and promotion regardless of sex, religion, ethnicity or disability; no discrimination or harassment."}]},{"text":[{"text":"Fair (equitable) pay","bold":true},{"text":" and benefits."}]},{"text":[{"text":"Occupational safety and health:","bold":true},{"text":" a safe, healthy workplace, protective equipment and training."}]},{"text":[{"text":"Respect for "},{"text":"workers' rights","bold":true},{"text":", reasonable hours and paid overtime."}]},{"text":[{"text":"Training and career development."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian consumer bodies: the "},{"text":"Federal Competition and Consumer Protection Commission (FCCPC)","bold":true},{"text":", set up under the Federal Competition and Consumer Protection Act 2018; "},{"text":"NAFDAC","bold":true},{"text":" (food and drugs); the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":" (product standards)."}]},{"text":[{"text":"Breaching consumer CSR: selling fake or expired drugs, short-measuring goods, hidden charges, ignoring complaints, lowering quality while keeping the price."}]},{"text":[{"text":"Equality","bold":true},{"text":" at work also means valuing "},{"text":"diversity","bold":true},{"text":": a workforce of different backgrounds, ages, sexes and abilities, with reasonable accommodation for people with disabilities."}]},{"text":[{"text":"Safety:","bold":true},{"text":" construction, mining, manufacturing and oil firms carry the highest risks. Skimping on safety measures, overlooking worker rights and extending unpaid hours are clear failures of CSR towards employees; "},{"text":"offering equitable pay","bold":true},{"text":" is a clear example of meeting it."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fair treatment of employees is "},{"text":"not","bold":true},{"text":" charity; it is part of a firm's basic ethical and legal responsibility."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business ethics = standards of right and wrong (honesty, fairness) guiding business conduct."}]},{"text":[{"text":"Unethical behaviour: competing unfairly, communicating untruthfully, causing harm. Influences: culture, knowledge, organisational behaviour."}]},{"text":[{"text":"Ethical behaviour builds brand reputation, trust and morale; code of ethics and whistle-blowing support it."}]},{"text":[{"text":"Dilemma = valid arguments on more than one side; lapse = a clearly wrong decision."}]},{"text":[{"text":"Four questions: legal? balanced? can you live with it? feasible?"}]},{"text":[{"text":"CSR = duty to society's well-being beyond profit. Perspectives: minimalist (profit within the law), defensive, cynical, proactive (moral obligation)."}]},{"text":[{"text":"Philanthropy (giving, no direct benefit) vs strategic CSR (aligned with business strategy)."}]},{"text":[{"text":"Environment: cut pollution and carbon footprint, manage waste, practise sustainability."}]},{"text":[{"text":"Consumers: safety, information, choice, being heard. Employees: equality, fair pay, safety. Community: support local causes."}]}]}],"theory":{"itemId":"63ce438b-49e2-5b06-8a85-df5c773c3a39","question":[{"type":"paragraph","text":[{"text":"Define corporate social responsibility and explain the four perspectives on CSR."}]}]},"practice":[{"topic":"Business Ethics and Corporate Social Responsibility","named":false}]}},{"itemId":"a90608d7-39fa-5c67-b58b-1238ac3fd96d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Forms of Business Ownership","body":"Sole proprietorship, partnership (types of agreement and partner), companies (private vs public, memorandum and articles, corporation pros and cons), cooperatives, public enterprises and privatisation; corporate governance (principles, actors, board duties, three models); mergers and acquisitions, strategic alliances and joint ventures.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Sole proprietorship, partnership (types of agreement and partner), companies (private vs public, memorandum and articles, corporation pros and cons), cooperatives, public enterprises and privatisation; corporate governance (principles, actors, board duties, three models); mergers and acquisitions, strategic alliances and joint ventures."}],"lessons":[{"number":"5.1","title":"Forms of ownership and the sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Form of business ownership:","bold":true},{"text":" the category a business is registered under with government. It decides how much ownership and managerial control the owner has, how the business pays tax and how far the owner is personally liable if the business fails."}]},{"text":[{"text":"Liability:","bold":true},{"text":" "},{"text":"unlimited","bold":true},{"text":" = the owner's personal property (house, car, savings) can be taken to pay business debts, so he can lose everything; "},{"text":"limited","bold":true},{"text":" = owners lose at most what they invested."}]},{"text":[{"text":"Sole proprietorship:","bold":true},{"text":" a business in which a "},{"text":"single person owns, finances, manages and controls","bold":true},{"text":" all its activities, with all the authority, responsibility and risk. It is the "},{"text":"most common (numerous)","bold":true},{"text":" form of business."}]}]},{"type":"paragraph","text":[{"text":"Features:","bold":true},{"text":" no separation of ownership and management · easy set-up (minimal formalities) · owner keeps all profit · unlimited liability · single ownership · profit taxed "},{"text":"once","bold":true},{"text":", as the owner's personal income."}]},{"type":"table","header":[[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Independence and full control (the single most important advantage)"}],[{"text":"Unlimited liability"}]],[[{"text":"Quick decisions (no hierarchy)"}],[{"text":"Limited capital"}]],[[{"text":"Possible tax benefits (losses offset personal income)"}],[{"text":"Limited managerial expertise"}]],[[{"text":"Flexibility; easy to form and wind up"}],[{"text":"Uncertain continuity (depends on owner's life and health)"}]],[[{"text":"Owner keeps all profit"}],[{"text":"Not suitable for large-scale operations"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sole proprietor "},{"text":"cannot issue or sell stock (shares)","bold":true},{"text":"; only companies can. \"Profits taxed twice\" is a "},{"text":"company","bold":true},{"text":" feature, never a sole proprietorship one."}]},{"text":[{"text":"A sole trader who registers a business name with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" still has "},{"text":"unlimited","bold":true},{"text":" liability: a business name is not a company."}]},{"text":[{"text":"Examples: a provision shop, a tailor, a barber or a phone-repair stand on campus."}]}]}]},{"number":"5.2","title":"Partnerships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" a business relation between "},{"text":"two or more persons","bold":true},{"text":" who join hands, finance and skills to form a business with the objective of a profitable return. Partners "},{"text":"divide the profits","bold":true},{"text":" among themselves, usually by their agreement."}]},{"text":[{"text":"In a "},{"text":"general partnership","bold":true},{"text":" liability is "},{"text":"unlimited","bold":true},{"text":" and "},{"text":"each partner","bold":true},{"text":" can be held liable for the business's "},{"text":"entire","bold":true},{"text":" debt. Partners have "},{"text":"joint authority","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Features (5):","bold":true},{"text":" agreement between partners · shared ownership · sharing of profit (and, implicitly, loss) · mutual business (each partner is owner "},{"text":"and agent","bold":true},{"text":"; one partner's act binds all, the test of partnership) · unlimited liability."}]},{"type":"table","header":[[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Shared responsibility"}],[{"text":"Unlimited (full personal) liability in general partnerships"}]],[[{"text":"Complementary skills"}],[{"text":"Conflict between partners"}]],[[{"text":"Easier capital access than a sole trader"}],[{"text":"Shared profits can cause disputes"}]],[[{"text":"Profits taxed as personal income"}],[{"text":"Limited life span (withdrawal, death or bankruptcy of a partner)"}]],[[{"text":"Limited government regulation; low start-up costs"}],[]]]},{"type":"paragraph","text":[{"text":"Partnership deed:","bold":true},{"text":" the legal document founding the firm: names of partners, capital contributions, profit-sharing ratios, decision-making, admission and retirement of partners, dispute resolution, duration, commencement date."}]},{"type":"paragraph","text":[{"text":"Partnership agreement (Articles of Partnership):","bold":true},{"text":" internal contract on management, ownership, investment, profits and losses."}]},{"type":"paragraph","text":[{"text":"3 types:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"General:","bold":true},{"text":" all partners share liabilities, profits and assets equally and can manage."}]},{"text":[{"text":"Limited:","bold":true},{"text":" at least one "},{"text":"general partner","bold":true},{"text":" (unlimited liability, manages) plus "},{"text":"limited partners","bold":true},{"text":" (liability limited to their investment, no day-to-day role; they invest and take a profit share)."}]},{"text":[{"text":"Limited liability partnership (LLP):","bold":true},{"text":" works like a general partnership but protects each partner from "},{"text":"malpractice or negligence claims","bold":true},{"text":" arising from other partners; common in professions such as law and accounting."}]}]},{"type":"paragraph","text":[{"text":"Types of partner:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active:","bold":true},{"text":" manages; unlimited liability."}]},{"text":[{"text":"Sleeping (dormant):","bold":true},{"text":" contributes capital and shares profit, does not manage; still unlimited liability."}]},{"text":[{"text":"Secret:","bold":true},{"text":" connection hidden from outsiders; contributes capital, manages; unlimited liability."}]},{"text":[{"text":"Nominal:","bold":true},{"text":" lends only name and reputation; no capital, no management, no profit share; liable to outsiders who lent believing he was a partner. Two kinds: by "},{"text":"estoppel","bold":true},{"text":" (he says or acts as if he is a partner) and by "},{"text":"holding out","bold":true},{"text":" (he does not deny it when others call him one)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship vs partnership:","bold":true},{"text":" both have low start-up costs and unlimited liability, and profits pass through to the owners' personal tax. One owner vs two or more; one keeps all profit vs shared profit; one decides vs shared decisions."}]},{"text":[{"text":"Trap: a "},{"text":"sleeping","bold":true},{"text":" partner is not a "},{"text":"limited","bold":true},{"text":" partner. Only a limited partner's liability stops at his investment. Limited partnerships and LLPs are now recognised in Nigeria under the "},{"text":"Companies and Allied Matters Act (CAMA) 2020","bold":true},{"text":"."}]},{"text":[{"text":"Elements of an agreement: business name and purpose, partners' details, capital contributed, ownership percentage, profit and loss distribution, management and voting, adding or removing partners."}]}]}]},{"number":"5.3","title":"Companies and corporations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporation (company):","bold":true},{"text":" a business recognised by the state as a "},{"text":"legal entity separate from its owners (shareholders)","bold":true},{"text":". It can own property, sue and be sued in its own name. It is \"an artificial being, invisible, intangible, existing only in contemplation of law\". "},{"text":"Limited liability results from this separate legal existence.","bold":true}]},{"text":[{"text":"Ownership is by shareholders","bold":true},{"text":"; it is transferable by buying and selling shares."}]},{"text":[{"text":"Board of directors:","bold":true},{"text":" elected by shareholders to represent them, set the company's direction and select top executives. "},{"text":"Management","bold":true},{"text":" (CEO and officers) runs day-to-day operations."}]},{"text":[{"text":"In Nigeria a company is registered with the CAC and needs "},{"text":"both a Memorandum and Articles of Association","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memorandum:","bold":true},{"text":" regulates the company's "},{"text":"external","bold":true},{"text":" relationship (name, objects)."}]},{"text":[{"text":"Articles:","bold":true},{"text":" regulate "},{"text":"internal","bold":true},{"text":" relationships between the company and its members."}]}]}]}]},{"type":"paragraph","text":[{"text":"Private vs public limited company","bold":true}]},{"type":"table","header":[[{"text":"Private (Ltd, \"unquoted\")"}],[{"text":"Public (Plc, \"quoted\", joint stock company)"}]],"rows":[[[{"text":"Articles restrict share transfer"}],[{"text":"Public may subscribe; shares freely transferable"}]],[[{"text":"2 to 50 shareholders"}],[{"text":"Minimum 7, no maximum"}]],[[{"text":"Small, limited capital"}],[{"text":"Large capital"}]],[[{"text":"Accounts not published"}],[{"text":"Annual accounts must be published"}]],[[{"text":"Does not issue debentures to the public"}],[{"text":"Issues debentures"}]],[[{"text":"Cannot be quoted on the stock exchange"}],[{"text":"Can be quoted on the stock exchange"}]],[[{"text":"Name ends \"Limited\"/\"Ltd\" (e.g. AGRO Nigeria Limited)"}],[{"text":"Name ends \"Plc\" (e.g. GTBank Plc, Vitafoam Nigeria Plc)"}]]]},{"type":"paragraph","text":[{"text":"Owned by shareholders but "},{"text":"controlled by the board","bold":true},{"text":" (public)."}]},{"type":"paragraph","text":[{"text":"Corporation: advantages (6)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Limited liability protection"}]},{"text":[{"text":"Credibility and trust"}]},{"text":[{"text":"Access to investment (issue shares; easier loans)"}]},{"text":[{"text":"Tax benefits and incentives"}]},{"text":[{"text":"Perpetual life","bold":true},{"text":" (continues across generations of owners)"}]},{"text":[{"text":"Easy ownership transfer"}]}]},{"type":"paragraph","text":[{"text":"Disadvantages (5)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Administrative responsibilities (records, annual returns, company law)"}]},{"text":[{"text":"Set-up and maintenance costs"}]},{"text":[{"text":"Public disclosure requirements"}]},{"text":[{"text":"Additional tax burden, including "},{"text":"double taxation","bold":true},{"text":": profit is taxed as company income, then dividends are taxed again as shareholders' personal income"}]},{"text":[{"text":"Lack of control for shareholders (ownership separated from management)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managers' power is "},{"text":"not","bold":true},{"text":" complete: shareholders can vote out directors, and the board can remove managers."}]},{"text":[{"text":"Plc means "},{"text":"public limited company","bold":true},{"text":"; \"public liability company\" is a wrong expansion. Nigeria also allows companies limited by "},{"text":"guarantee","bold":true},{"text":" (often non-profits) and "},{"text":"unlimited","bold":true},{"text":" companies. Under CAMA 2020, a "},{"text":"single person","bold":true},{"text":" may now form a private company; for this course, keep 2 to 50 as the private range and a minimum of 7 for a public company."}]},{"text":[{"text":"Limited liability company (LLC)","bold":true},{"text":" in the American sense is a hybrid: members get "},{"text":"limited liability","bold":true},{"text":" plus "},{"text":"flexibility in management and tax treatment","bold":true},{"text":" (taxed like a sole proprietorship, partnership or corporation; pass-through avoids double taxation). Drawbacks: more paperwork than a partnership, differing state rules, harder to attract investors, uncertain continuity when members change. An LLC can have one or many members and is not identical to a corporation. In Nigerian usage \"limited liability company\" usually just means a private limited company."}]},{"text":[{"text":"Other company words: "},{"text":"parent/holding company","bold":true},{"text":" controls a "},{"text":"subsidiary","bold":true},{"text":"; a "},{"text":"mutual company","bold":true},{"text":" is owned by its customers or policyholders (a rare, specialised form)."}]}]}]},{"number":"5.4","title":"Cooperatives, public enterprises and privatisation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative society:","bold":true},{"text":" a voluntary association of persons united by a common bond who venture into business "},{"text":"with the sole purpose of providing service to members in the most efficient and affordable manner","bold":true},{"text":". It is a registered body corporate (owns property, contracts, sues)."}]},{"text":[{"text":"Features:","bold":true},{"text":" owned and democratically run by members · voluntary membership · "},{"text":"one member, one vote","bold":true},{"text":" · profits shared among members or reinvested · separate legal identity."}]},{"text":[{"text":"5 types:","bold":true},{"text":" producer, consumer, credit unions (thrift and credit), marketing, housing."}]}]},{"type":"table","header":[[{"text":"Advantages (7)"}],[{"text":"Disadvantages (6)"}]],"rows":[[[{"text":"Shared benefits"}],[{"text":"Slow, conflict-prone decisions"}]],[[{"text":"Democratic structure"}],[{"text":"Limited capital"}]],[[{"text":"Risk sharing"}],[{"text":"Limited growth"}]],[[{"text":"Stability"}],[{"text":"Inequality in contribution"}]],[[{"text":"Economy in operations (no middlemen)"}],[{"text":"Inefficient management (unpaid, inexperienced)"}]],[[{"text":"Government support (cheap loans, subsidies, lower tax)"}],[{"text":"Excessive government control"}]],[[{"text":"Social utility (stops concentration of economic power)"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Public enterprise:","bold":true},{"text":" a business "},{"text":"owned (wholly or mainly) and controlled by government","bold":true},{"text":" to provide essential services in the public interest. Also called "},{"text":"government parastatals, public corporations, state-owned enterprises","bold":true},{"text":" and government-owned companies."}]},{"text":[{"text":"Objectives:","bold":true},{"text":" provide essential services (power, water, transport), control strategic sectors, prevent private monopoly exploitation, create jobs, earn revenue, develop neglected areas."}]},{"text":[{"text":"2 sources of finance:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" (revenue from operations, retained surplus) and "},{"text":"external","bold":true},{"text":" (government grants and subventions, loans, bonds)."}]},{"text":[{"text":"Privatisation:","bold":true},{"text":" transfer of ownership of a public enterprise, "},{"text":"partly or wholly","bold":true},{"text":", to private investors. It may be "},{"text":"partial or full","bold":true},{"text":"."}]},{"text":[{"text":"Commercialisation:","bold":true},{"text":" government keeps ownership but the enterprise must run on commercial, profit-making lines (also partial or full)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"government sectors\" is "},{"text":"not","bold":true},{"text":" a name for public enterprises."}]},{"text":[{"text":"Nigerian public enterprises have included the Nigerian Ports Authority and the Nigerian Railway Corporation. Problems: political interference, overstaffing, inefficiency, corruption and dependence on subsidies, which led to privatisation."}]},{"text":[{"text":"Nigeria's programme is run by the "},{"text":"Bureau of Public Enterprises (BPE)","bold":true},{"text":" under the "},{"text":"National Council on Privatisation","bold":true},{"text":", guided by the Public Enterprises (Privatisation and Commercialisation) Act 1999. The best-known example is the 2013 sale of the power generation and distribution companies created from PHCN."}]},{"text":[{"text":"For privatisation:","bold":true},{"text":" efficiency, less burden on the budget, revenue for government, new investment, wider share ownership. "},{"text":"Against:","bold":true},{"text":" job losses, higher prices, private monopoly, foreign domination."}]}]}]},{"number":"5.5","title":"Corporate governance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate governance:","bold":true},{"text":" the system of rules, practices and processes by which a company is "},{"text":"directed and controlled","bold":true},{"text":", ensuring accountability to stakeholders, transparency and ethical behaviour (oversight and management systems). The "},{"text":"board of directors","bold":true},{"text":" is the primary force in it."}]},{"text":[{"text":"5 principles:","bold":true},{"text":" accountability, transparency, fairness, responsibility, risk management."}]},{"text":[{"text":"4 key actors:","bold":true},{"text":" board of directors, management, shareholders, audit committee (within the board; checks financial reports, compliance and audits)."}]},{"text":[{"text":"Stakeholders considered (7):","bold":true},{"text":" shareholders, management, board, employees, customers, suppliers, community."}]},{"text":[{"text":"6 board responsibilities:","bold":true},{"text":" set corporate strategy · oversee management (appoint, evaluate, remove the CEO) · ensure compliance · risk management · financial reporting (with the audit committee) · succession planning."}]}]},{"type":"paragraph","text":[{"text":"3 governance models","bold":true}]},{"type":"table","header":[[{"text":"Model"}],[{"text":"Who controls"}],[{"text":"Key marks"}]],"rows":[[[{"text":"Anglo-American","bold":true}],[{"text":"Board and shareholders"}],[{"text":"Shareholder Model is principal (others: Stewardship, Political). Management maximises shareholder interest; insiders plus independent directors; chairperson and CEO ideally different people; big decisions put to shareholder vote"}]],[[{"text":"Continental","bold":true}],[{"text":"Two-tier:","bold":true},{"text":" supervisory board (outsiders: shareholders, unions, banks) and management board (insiders)"}],[{"text":"Boards entirely separate; supervisory board size set by national law; companies align with government objectives; values stakeholders"}]],[[{"text":"Japanese","bold":true}],[{"text":"Banks, affiliated entities ("},{"text":"keiretsu","bold":true},{"text":"), management, government"}],[{"text":"Board mostly insiders; keiretsu can remove directors if profits fall; small shareholders have no voice; low transparency"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Benefits of good governance:","bold":true},{"text":" trust, clear direction, long-term viability, investor confidence and capital raising, rising share prices, better reputation and customer retention, less loss, waste, risk and corruption. Bad governance does the opposite and can collapse profitability."}]},{"text":[{"text":"Assessing governance (9 areas):","bold":true},{"text":" disclosure practices, executive pay structure, risk management, conflict-of-interest policies, board members, contractual and social obligations, vendor relationships, complaints, audits."}]},{"text":[{"text":"Institutional investors (pension and mutual funds) are especially influential shareholders. In Nigeria the "},{"text":"Nigerian Code of Corporate Governance 2018","bold":true},{"text":" is issued by the Financial Reporting Council of Nigeria, and the "},{"text":"Securities and Exchange Commission (SEC)","bold":true},{"text":" regulates public companies."}]},{"text":[{"text":"Trap: the board does "},{"text":"not","bold":true},{"text":" run day-to-day operations; management does."}]}]}]},{"number":"5.6","title":"Mergers, acquisitions, strategic alliances and joint ventures","mustKnow":[{"type":"table","header":[[{"text":"Merger"}],[{"text":"Acquisition"}]],"rows":[[[{"text":"Two or more firms "},{"text":"unite into one","bold":true},{"text":" new entity"}],[{"text":"One firm buys part or all of another"}]],[[{"text":"Mutual; usually equals"}],[{"text":"Larger, stronger firm buys a smaller one; need not be mutual"}]],[[{"text":"New shares issued to both sets of shareholders; usually no cash"}],[{"text":"No new shares; buyer needs at least "},{"text":"51%","bold":true},{"text":" for control"}]],[[{"text":"New name and joint management usually"}],[{"text":"Target operates under the buyer's name"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"horizontal","bold":true},{"text":" (competitors at the same stage in the same industry) · "},{"text":"vertical","bold":true},{"text":" (firms at different stages of one supply chain, e.g. a manufacturer and its supplier) · "},{"text":"conglomerate","bold":true},{"text":" (unrelated industries)."}]},{"text":[{"text":"Acquisition forms:","bold":true},{"text":" "},{"text":"stock sale","bold":true},{"text":" (buy the whole entity, assets and liabilities) and "},{"text":"asset sale","bold":true},{"text":" (buy particular assets). Selling a whole segment = "},{"text":"divestiture (carve-out)","bold":true},{"text":"."}]},{"text":[{"text":"3 reasons for acquisition:","bold":true},{"text":" expansion (Apple buying Beats, 2014) · defensive play (Facebook buying WhatsApp, 2014) · capability acquisition (technology or talent)."}]},{"text":[{"text":"Friendly","bold":true},{"text":" acquisition: target's board and shareholders approve. "},{"text":"Hostile takeover:","bold":true},{"text":" one company buys a "},{"text":"controlling interest in the voting stock","bold":true},{"text":" of another "},{"text":"against the wishes of its management","bold":true},{"text":"."}]},{"text":[{"text":"Strategic alliance:","bold":true},{"text":" a cooperative, often "},{"text":"long-term","bold":true},{"text":" agreement between separate businesses to share resources for mutually beneficial projects (production, R&D, marketing, distribution) while "},{"text":"each keeps its independence","bold":true},{"text":". Main advantage: "},{"text":"less risk and work than permanently integrating two companies","bold":true},{"text":"."}]},{"text":[{"text":"4 Cs:","bold":true},{"text":" complementarities, congruence of goals, compatibility of organisations, change."}]},{"text":[{"text":"3 types:","bold":true},{"text":" joint venture, "},{"text":"equity","bold":true},{"text":" alliance (one buys an equity stake in the other, e.g. 40%), "},{"text":"non-equity","bold":true},{"text":" alliance (each brings core competencies; "},{"text":"most common","bold":true},{"text":")."}]},{"text":[{"text":"Joint venture (JV):","bold":true},{"text":" two or more parents create a "},{"text":"new, separate child company","bold":true},{"text":" for a specific goal or project. "},{"text":"50-50 JV","bold":true},{"text":" or "},{"text":"majority-owned venture","bold":true},{"text":" (e.g. 70/30). Types: "},{"text":"equity","bold":true},{"text":" and "},{"text":"contractual","bold":true},{"text":". Example: Sony Ericsson."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leveraged buyout:","bold":true},{"text":" buying a company mostly with borrowed money. Not the same as a hostile takeover."}]},{"text":[{"text":"Merger motives: market share, new markets, lower operating costs, more revenue, wider margins. In Nigeria, Access Bank's 2019 merger with Diamond Bank grew its customer base. Oil joint ventures between NNPC and international oil companies are well-known JVs."}]},{"text":[{"text":"Product life cycles and alliances:","bold":true},{"text":" slow cycle (medicine: access restricted markets, keep stability), standard cycle (pool resources, scale, market share), fast cycle (software: speed innovation, share R&D cost)."}]},{"text":[{"text":"How alliances create value (5):","bold":true},{"text":" short-term finances, removing entry barriers, business insight, shared financial risk, innovating beyond current capabilities."}]},{"text":[{"text":"7 steps to a small-business alliance:","bold":true},{"text":" put your house in order, set goals, identify partners, due diligence, get to know each other, make it win-win, keep clear communication."}]},{"text":[{"text":"Alliance advantages:","bold":true},{"text":" shared resources and expertise, innovation, competitive advantage, new-market penetration, economies of scale, revenue growth, risk mitigation, brand awareness. "},{"text":"Cons:","bold":true},{"text":" more coordination work, one side may gain more, conflict over strategy, possible damage to image."}]},{"text":[{"text":"JV steps (7):","bold":true},{"text":" purpose and goals → structure and ownership → resources → governance (board, management) → finances and profit sharing → risks and exit → monitoring. "},{"text":"Benefits:","bold":true},{"text":" new markets, shared costs and risks, combined expertise. "},{"text":"Challenges:","bold":true},{"text":" conflict of interest, cultural difference, shared control."}]},{"text":[{"text":"Traps: alliance = cooperative pact, "},{"text":"not","bold":true},{"text":" a permanent consolidation; JV = a new entity for a defined purpose, often limited in time; merger = one entity; acquisition = controlling interest."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship: one owner, full control, independence, unlimited liability, most common, cannot sell shares."}]},{"text":[{"text":"Partnership: 2+ owners, shared profits, joint authority, unlimited liability (general); general, limited, LLP; active, sleeping, secret, nominal partners."}]},{"text":[{"text":"Company: separate legal entity, shareholders, limited liability, perpetual life, double taxation; memorandum (external) and articles (internal)."}]},{"text":[{"text":"Private Ltd 2-50, no public shares; Plc 7+, quoted, publishes accounts."}]},{"text":[{"text":"Cooperative: serves members, one member one vote; 5 types."}]},{"text":[{"text":"Public enterprises (parastatals, public corporations, SOEs) finance internally and externally; privatisation is partial or full."}]},{"text":[{"text":"Governance: 5 principles, 4 actors, 6 board duties; Anglo-American, Continental (two-tier), Japanese (keiretsu)."}]},{"text":[{"text":"M&A: horizontal, vertical, conglomerate; hostile takeover against management's wishes; alliance keeps independence; JV creates a new child company."}]}]}],"theory":{"itemId":"e59886c4-52f7-5e2c-8f64-a9ea1e460c27","question":[{"type":"paragraph","text":[{"text":"Distinguish between a private limited company and a public limited company, and state two advantages and two disadvantages of the corporate form."}]}]},"practice":[{"topic":"Forms of Business Ownership","named":false}]}},{"itemId":"38dd1187-cac0-5a05-9c01-4614cec71a8c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Entrepreneurship and Small-Business Ownership","body":"What a small business is and why it matters to the economy; who entrepreneurs are and the entrepreneurial spirit; the start-up phase (three routes to ownership, the business plan); the growth phase and why small businesses fail; financing options (debt and equity, bank loans, microfinance, angel investors, venture capital, crowdfunding, bootstrapping); the franchise alternative (franchisor, franchisee, advantages and disadvantages).","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What a small business is and why it matters to the economy; who entrepreneurs are and the entrepreneurial spirit; the start-up phase (three routes to ownership, the business plan); the growth phase and why small businesses fail; financing options (debt and equity, bank loans, microfinance, angel investors, venture capital, crowdfunding, bootstrapping); the franchise alternative (franchisor, franchisee, advantages and disadvantages)."}],"lessons":[{"number":"6.1","title":"The big world of small business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Small business:","bold":true},{"text":" a firm that is "},{"text":"independently owned and operated","bold":true},{"text":", is "},{"text":"not dominant in its field","bold":true},{"text":" (market), and is small by number of employees or annual sales. In the United States the usual cut-off is "},{"text":"fewer than 500 employees","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria (MSMEs):","bold":true},{"text":" micro, small and medium enterprises are grouped by size. By employees: "},{"text":"micro","bold":true},{"text":" under 10, "},{"text":"small","bold":true},{"text":" 10 to 49, "},{"text":"medium","bold":true},{"text":" 50 to 199. The government agency that promotes and supports them is "},{"text":"SMEDAN","bold":true},{"text":" (Small and Medium Enterprises Development Agency of Nigeria)."}]}]},{"type":"paragraph","text":[{"text":"Typical characteristics of a small business:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Small employee count","bold":true},{"text":" (the feature most often examined)."}]},{"text":[{"text":"Owned and usually "},{"text":"managed by the owner","bold":true},{"text":" (owner-manager business)."}]},{"text":[{"text":"Limited capital","bold":true},{"text":" and resources."}]},{"text":[{"text":"Narrow focus","bold":true},{"text":": few products, often one location or a local market."}]},{"text":[{"text":"Close, personal contact","bold":true},{"text":" with customers and staff; quick, flexible decisions."}]}]},{"type":"paragraph","text":[{"text":"Role (importance) of small businesses in the economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Create jobs","bold":true},{"text":": together they employ a very large share of workers."}]},{"text":[{"text":"Drive innovation","bold":true},{"text":": introduce new products, services and ideas."}]},{"text":[{"text":"Give an outlet for entrepreneurs","bold":true},{"text":": a route for people to turn ideas into businesses."}]},{"text":[{"text":"Provide specialist support to larger companies","bold":true},{"text":": as suppliers, distributors and service providers."}]},{"text":[{"text":"Meet specialised needs of consumers","bold":true},{"text":" that big firms ignore."}]},{"text":[{"text":"Inject competition","bold":true},{"text":", which keeps prices and quality in check."}]},{"text":[{"text":"Support local economies","bold":true},{"text":" and spread income and opportunity."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When a question asks why small businesses are important and offers several true reasons plus \"all the above\", the answer is "},{"text":"all the above","bold":true},{"text":": outlet for entrepreneurs, specialist support to big firms and innovation are all correct."}]},{"text":[{"text":"Trap:","bold":true},{"text":" small businesses do "},{"text":"not","bold":true},{"text":" cut employment, raise tax burdens or curb competition. They "},{"text":"foster jobs and innovation","bold":true},{"text":". \"Massive scale\", \"worldwide reach\" and \"heavy capital needs\" describe large corporations, not small businesses."}]},{"text":[{"text":"Lifestyle business vs high-growth venture:","bold":true},{"text":" a lifestyle business aims to give its owner a comfortable living and independence (a provision shop, a hair salon, a campus printing stand). A high-growth venture aims to grow quickly into a large firm (many tech start-ups in Yaba, Lagos)."}]},{"text":[{"text":"Most businesses in Nigeria are micro and small enterprises, many of them informal: market traders, tailors, mechanics, food sellers."}]}]}]},{"number":"6.2","title":"The entrepreneurial spirit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Entrepreneur:","bold":true},{"text":" a person who "},{"text":"spots a business opportunity","bold":true},{"text":" and "},{"text":"assumes the risk","bold":true},{"text":" of starting and running a new business, in the hope of profit."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" the "},{"text":"process of designing, creating and running a new business","bold":true},{"text":", accepting the risks involved."}]},{"text":[{"text":"Entrepreneurial spirit:","bold":true},{"text":" the positive, forward-thinking desire to create profitable, innovative business solutions. It involves "},{"text":"creativity, problem-solving and embracing risk","bold":true},{"text":"."}]},{"text":[{"text":"Intrapreneurship:","bold":true},{"text":" showing entrepreneurial behaviour (innovating, taking initiative) "},{"text":"inside an existing organisation","bold":true},{"text":" as an employee."}]}]},{"type":"paragraph","text":[{"text":"What entrepreneurship involves:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Spotting a business opportunity."}]},{"text":[{"text":"Developing an idea for a business."}]},{"text":[{"text":"Satisfying the needs of customers."}]},{"text":[{"text":"Taking (calculated) risks and organising resources."}]}]},{"type":"paragraph","text":[{"text":"Common traits of entrepreneurs:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Risk-taking","bold":true},{"text":" (willing to accept calculated risk)."}]},{"text":[{"text":"Creativity and innovation","bold":true},{"text":"."}]},{"text":[{"text":"Problem-solving","bold":true},{"text":" ability."}]},{"text":[{"text":"Self-confidence","bold":true},{"text":" and a desire to control their own destiny (independence)."}]},{"text":[{"text":"Drive, discipline and hard work","bold":true},{"text":"."}]},{"text":[{"text":"Optimism and persistence","bold":true},{"text":"; tolerance of failure and uncertainty."}]},{"text":[{"text":"Eagerness to learn","bold":true},{"text":" and ability to relate well to people."}]}]},{"type":"paragraph","text":[{"text":"Why people start businesses:","bold":true},{"text":" independence (being your own boss), financial rewards, personal satisfaction and achievement, passion for an idea, and lack of (or dissatisfaction with) paid employment."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Who is who:","bold":true},{"text":" an "},{"text":"investor","bold":true},{"text":" only supplies money; a "},{"text":"manager","bold":true},{"text":" runs a business that may belong to someone else; a "},{"text":"stakeholder","bold":true},{"text":" is anyone affected by the business. The person who "},{"text":"assumes the risk of starting","bold":true},{"text":" the business is the "},{"text":"entrepreneur","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"managing large businesses\" or \"managing a corporation\" is "},{"text":"management","bold":true},{"text":", not entrepreneurship. Entrepreneurship is about "},{"text":"creating new","bold":true},{"text":" businesses."}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"applying for a job","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" associated with entrepreneurship, because it means working for someone else."}]},{"text":[{"text":"Entrepreneurs are "},{"text":"not","bold":true},{"text":" risk-averse and do "},{"text":"not","bold":true},{"text":" stick to old ways or ignore market cues. Those are the opposite of the entrepreneurial spirit."}]},{"text":[{"text":"Challenges entrepreneurs face:","bold":true},{"text":" "},{"text":"navigating risks and unknowns","bold":true},{"text":" (uncertainty), limited funds, competition, long hours and heavy personal responsibility. They do not enjoy \"unlimited funding\" or \"zero competition\"."}]},{"text":[{"text":"Nigerian examples: Aliko Dangote built the Dangote Group from a trading business; many young founders build fintech firms in Lagos."}]}]}]},{"number":"6.3","title":"The start-up phase: planning and launching","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Start-up phase","bold":true},{"text":" (also called the "},{"text":"initiation stage","bold":true},{"text":"): getting the business off the ground. It includes "},{"text":"idea generation, writing the business plan, raising funds (for example loans and investors) and launching","bold":true},{"text":"."}]},{"text":[{"text":"3 routes to small-business ownership:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Start a new business from scratch","bold":true},{"text":" (a start-up)."}]},{"text":[{"text":"Buy an existing business","bold":true},{"text":"."}]},{"text":[{"text":"Buy a franchise","bold":true},{"text":"."}]}]}]}]},{"type":"table","header":[[{"text":"Route"}],[{"text":"Main advantage"}],[{"text":"Main disadvantage"}]],"rows":[[[{"text":"Start from scratch"}],[{"text":"Full freedom to shape the business"}],[{"text":"High failure rate","bold":true},{"text":"; no customers or track record"}]],[[{"text":"Buy an existing business"}],[{"text":"Customers, suppliers, staff and a track record already exist"}],[{"text":"Higher purchase cost; you may inherit hidden problems"}]],[[{"text":"Buy a franchise"}],[{"text":"Known brand and proven system; support"}],[{"text":"Fees and royalties; loss of independence"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business plan:","bold":true},{"text":" a written document that sets out the business idea, its goals, the strategy for reaching them, and the resources (especially money) needed. It is prepared in the "},{"text":"initiation (start-up) stage","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Why a business plan is significant:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Persuades others","bold":true},{"text":" (lenders, investors) "},{"text":"to commit funding","bold":true},{"text":"."}]},{"text":[{"text":"Demonstrates the viability","bold":true},{"text":" of the venture (that it can succeed)."}]},{"text":[{"text":"Guides business activities by defining objectives","bold":true},{"text":"."}]},{"text":[{"text":"Forces the founder to think through every part of the business and spot problems early."}]}]},{"type":"paragraph","text":[{"text":"Typical contents of a business plan:","bold":true},{"text":" executive summary; mission and objectives; company overview; management team; target market and market analysis; competition and competitive advantage; marketing strategy; operations plan; financial plan (start-up costs, projected sales, cash flow, funding needed); critical risks."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When \"all the above\" follows persuading funders, showing viability and guiding activities, choose "},{"text":"all the above","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the "},{"text":"high failure rate","bold":true},{"text":" is the recognised disadvantage of a start-up compared with buying a business or a franchise. A start-up does not usually need "},{"text":"more","bold":true},{"text":" funds than other routes; buying an established business or franchise often costs more."}]},{"text":[{"text":"Trap:","bold":true},{"text":" global expansion and maintaining growth belong to the "},{"text":"growth","bold":true},{"text":" stage; shutting down belongs to closure. A business plan is not written in the expansion, stability or downturn stage."}]},{"text":[{"text":"Before launch, the founder also chooses a form of ownership and registers it, in Nigeria with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":"."}]}]}]},{"number":"6.4","title":"The growth phase and why small businesses fail","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Growth phase:","bold":true},{"text":" "},{"text":"nurturing and sustaining a young business","bold":true},{"text":", that is "},{"text":"building and sustaining progress","bold":true},{"text":". It focuses on "},{"text":"scaling operations, managing cash flow and building a customer base","bold":true},{"text":"."}]},{"text":[{"text":"Stages of a business (life cycle):","bold":true},{"text":" initiation (start-up) → growth (expansion) → maturity (stability) → possible decline (downturn)."}]}]},{"type":"paragraph","text":[{"text":"Tasks in the growth phase:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Scale up operations to meet rising demand."}]},{"text":[{"text":"Manage cash flow carefully."}]},{"text":[{"text":"Build and keep a customer base."}]},{"text":[{"text":"Hire staff and "},{"text":"delegate","bold":true},{"text":": the owner can no longer do everything."}]},{"text":[{"text":"Seek advice and further finance."}]}]},{"type":"paragraph","text":[{"text":"Why small businesses fail:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Management incompetence or inexperience","bold":true},{"text":"."}]},{"text":[{"text":"Inadequate financing","bold":true},{"text":" (undercapitalisation) and "},{"text":"poor cash-flow management","bold":true},{"text":"."}]},{"text":[{"text":"Poor planning","bold":true},{"text":", including no proper business plan."}]},{"text":[{"text":"Weak marketing","bold":true},{"text":" or not enough customers (poor market research)."}]},{"text":[{"text":"Uncontrolled (too rapid) growth","bold":true},{"text":"."}]},{"text":[{"text":"Poor location","bold":true},{"text":", poor stock (inventory) control, failure to adapt to change."}]}]},{"type":"paragraph","text":[{"text":"Sources of help and advice:","bold":true},{"text":" mentors, advisory boards, networking, business incubators (which give new firms low-cost space and support services) and government agencies such as "},{"text":"SMEDAN","bold":true},{"text":" in Nigeria."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the growth phase is not about terminating, shrinking or dodging competitors. It is about building on early success."}]},{"text":[{"text":"A business can fail "},{"text":"while growing","bold":true},{"text":": fast sales growth can use up cash faster than it comes in, so cash-flow management is vital."}]},{"text":[{"text":"Many owners struggle to move from doing every job themselves to managing others. Learning to delegate is a key growth-phase skill."}]}]}]},{"number":"6.5","title":"Financing options for small businesses","mustKnow":[{"type":"table","header":[[],[{"text":"Debt financing","bold":true}],[{"text":"Equity financing","bold":true}]],"rows":[[[{"text":"Meaning"}],[{"text":"Borrowing money"}],[{"text":"Selling part-ownership (shares) in the business"}]],[[{"text":"Repayment"}],[{"text":"Must be repaid "},{"text":"with interest","bold":true}],[{"text":"No repayment"}]],[[{"text":"Control"}],[{"text":"Owner keeps ownership"}],[{"text":"Investors gain ownership and a share of profit, often a say"}]],[[{"text":"Examples"}],[{"text":"Bank loans, microfinance loans, supplier credit"}],[{"text":"Angel investors, venture capital, partners"}]]]},{"type":"paragraph","text":[{"text":"Main financing options:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal savings","bold":true},{"text":" and "},{"text":"family and friends","bold":true},{"text":": the most common first source."}]},{"text":[{"text":"Bootstrapping","bold":true},{"text":": funding the business from the owner's own resources and its own revenue, keeping costs low."}]},{"text":[{"text":"Commercial bank loans","bold":true},{"text":": a common source; banks usually want a business plan and collateral."}]},{"text":[{"text":"Microfinance","bold":true},{"text":": small loans to micro and small businesses that banks often turn down. In Nigeria "},{"text":"microfinance banks","bold":true},{"text":" are licensed and regulated by the "},{"text":"Central Bank of Nigeria (CBN)","bold":true},{"text":". The "},{"text":"Bank of Industry (BOI)","bold":true},{"text":" is a government development bank that also funds small businesses."}]},{"text":[{"text":"Angel investors","bold":true},{"text":": wealthy individuals who invest their "},{"text":"own money","bold":true},{"text":" in early-stage businesses in exchange for equity."}]},{"text":[{"text":"Venture capital","bold":true},{"text":": funding from firms (venture capitalists) that invest pooled money in "},{"text":"high-technology, high-risk, perceived high-reward","bold":true},{"text":" businesses in exchange for equity, expecting large returns."}]},{"text":[{"text":"Crowdfunding","bold":true},{"text":": raising small amounts from "},{"text":"many people","bold":true},{"text":", usually online."}]},{"text":[{"text":"Seed capital","bold":true},{"text":": the first small sum used to test an idea and set up the business."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Venture capital vs angel investors:","bold":true},{"text":" angels are "},{"text":"individuals","bold":true},{"text":" using their own money, usually earlier and in smaller sums. Venture capitalists are "},{"text":"firms","bold":true},{"text":", usually investing larger sums at a later stage, and they expect to exit by selling their stake (for example when the company lists on a stock exchange or is bought)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fixed capital and current (working) capital describe "},{"text":"how","bold":true},{"text":" funds are used (long-term assets vs day-to-day running), not a source of funds. Seed capital is the first funding, not the high-risk, high-tech finance; that is "},{"text":"venture capital","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" tax revenue is government income, staff wages are money owed to workers, and client opinions are feedback. None is a financing option for a small business. "},{"text":"Commercial bank loans","bold":true},{"text":" are."}]},{"text":[{"text":"Informal sources are also common in Nigeria, such as rotating savings groups (esusu or ajo) and trade credit from suppliers."}]}]}]},{"number":"6.6","title":"The franchise alternative","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Franchise:","bold":true},{"text":" a business arrangement in which one party (the "},{"text":"franchisor","bold":true},{"text":") allows another (the "},{"text":"franchisee","bold":true},{"text":") to "},{"text":"use its business name, brand and system to sell its products or services","bold":true},{"text":", in return for fees. In short, "},{"text":"a licensed brand operation","bold":true},{"text":"."}]},{"text":[{"text":"Franchisor:","bold":true},{"text":" the company that owns the brand and system and grants the right."}]},{"text":[{"text":"Franchisee:","bold":true},{"text":" the person or firm that buys the right and runs the outlet."}]},{"text":[{"text":"Franchise agreement:","bold":true},{"text":" the contract setting out rights, duties, fees and rules. The franchisee usually pays an "},{"text":"initial franchise fee","bold":true},{"text":" plus continuing "},{"text":"royalties","bold":true},{"text":" (a share of sales)."}]},{"text":[{"text":"2 types:","bold":true},{"text":" (1) "},{"text":"product (trade-name) franchise","bold":true},{"text":": the right to sell the franchisor's products, e.g. car dealerships and soft-drink bottlers; (2) "},{"text":"business-format franchise","bold":true},{"text":": the whole way of running the business (name, layout, methods, training), e.g. fast-food chains."}]}]},{"type":"table","header":[[{"text":"Advantages to the franchisee"}],[{"text":"Disadvantages to the franchisee"}]],"rows":[[[{"text":"Pre-existing brand fame","bold":true},{"text":" (known name attracts customers)"}],[{"text":"High start-up cost","bold":true},{"text":" (franchise fee, equipment)"}]],[[{"text":"Proven business system; "},{"text":"lower risk of failure","bold":true}],[{"text":"Continuing "},{"text":"royalties","bold":true},{"text":" reduce profit"}]],[[{"text":"Training and support","bold":true},{"text":" from the franchisor"}],[{"text":"Loss of independence","bold":true},{"text":": strict rules on products, prices, layout"}]],[[{"text":"National advertising and group buying power"}],[{"text":"Franchisor's problems or bad publicity hurt every outlet"}]],[[{"text":"Easier to obtain finance"}],[{"text":"Agreement may limit selling the outlet and can be ended"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages to the franchisor:","bold":true},{"text":" rapid expansion using franchisees' money, steady fee and royalty income, motivated owner-managers at each outlet."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" high risk, minimal franchisor support and steep initial investment are "},{"text":"not","bold":true},{"text":" advantages. The headline advantage is "},{"text":"pre-existing brand fame","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a franchise is not a state-owned operation (that is a public enterprise), a merger, a cooperative (owned by its members) or a solo-owner venture (sole proprietorship)."}]},{"text":[{"text":"Franchising is also a way to enter foreign markets (Topic 3). In Nigeria, the Nigerian Bottling Company bottles Coca-Cola products, an example of a product franchise, and international fast-food brands operate here through franchise arrangements."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Small business = independently owned, not dominant in its field, small employee count; Nigeria groups MSMEs by size and supports them through SMEDAN."}]},{"text":[{"text":"Small businesses create jobs, drive innovation, give entrepreneurs an outlet and support large firms."}]},{"text":[{"text":"Entrepreneur = assumes the risk of starting a business; entrepreneurship = designing and creating new businesses."}]},{"text":[{"text":"Entrepreneurial spirit = creativity, problem-solving and embracing risk; applying for a job is not entrepreneurship."}]},{"text":[{"text":"3 routes: start from scratch (high failure rate), buy an existing business, buy a franchise."}]},{"text":[{"text":"Business plan, written at the initiation stage: persuades funders, shows viability, guides by objectives."}]},{"text":[{"text":"Growth phase = building and sustaining progress: scaling, cash flow, customers."}]},{"text":[{"text":"Failure causes: poor management, too little finance, poor planning, weak marketing, uncontrolled growth."}]},{"text":[{"text":"Debt is repaid with interest; equity sells ownership. Venture capital funds high-tech, high-risk, high-reward projects."}]},{"text":[{"text":"Franchise = licensed brand operation; key advantage is brand fame, key drawbacks are fees, royalties and lost independence."}]}]}],"theory":{"itemId":"9957e3ea-8b1f-5d53-a98f-e88cdf2ae4ca","question":[{"type":"paragraph","text":[{"text":"Explain the franchise alternative and state three advantages and three disadvantages of franchising to the franchisee."}]}]},"practice":[{"topic":"Entrepreneurship and Small-Business Ownership","named":false}]}},{"itemId":"cb2abec1-e0e3-57e8-ae9f-1194b000e5fd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Management Roles, Functions and Skills","body":"What management is and the manager's main job; the three groups of managerial roles; the three levels of management; the four functions (planning with vision, mission, goals, objectives and SWOT; organising with structure and teams; leading with leadership styles; controlling); and the four essential skills (technical, interpersonal, conceptual, decision-making).","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What management is and the manager's main job; the three groups of managerial roles; the three levels of management; the four functions (planning with vision, mission, goals, objectives and SWOT; organising with structure and teams; leading with leadership styles; controlling); and the four essential skills (technical, interpersonal, conceptual, decision-making)."}],"lessons":[{"number":"7.1","title":"What managers do: roles and levels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management:","bold":true},{"text":" the process of planning, organising, leading and controlling an organisation's resources (people, money, materials, information) to reach its goals effectively and efficiently."}]},{"text":[{"text":"Primary role of a manager:","bold":true},{"text":" to "},{"text":"drive organisational objectives","bold":true},{"text":", that is, to get the organisation's goals achieved through the work of others. It is not doing routine technical work, chasing promotion or avoiding choices."}]},{"text":[{"text":"Efficiency","bold":true},{"text":" = doing things right (least waste of resources). "},{"text":"Effectiveness","bold":true},{"text":" = doing the right things (reaching the goal)."}]}]},{"type":"paragraph","text":[{"text":"The three groups of managerial roles (10 roles in all):","bold":true}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Meaning"}],[{"text":"Roles inside it"}]],"rows":[[[{"text":"Interpersonal","bold":true},{"text":" (relationship-building)"}],[{"text":"dealing with people inside and outside the firm"}],[{"text":"figurehead, "},{"text":"leader","bold":true},{"text":", liaison"}]],[[{"text":"Informational","bold":true},{"text":" (information-sharing)"}],[{"text":"receiving, gathering and passing on information"}],[{"text":"monitor, disseminator, "},{"text":"spokesperson","bold":true}]],[[{"text":"Decisional","bold":true},{"text":" (decision-making)"}],[{"text":"making choices and solving problems"}],[{"text":"entrepreneur, "},{"text":"disturbance handler","bold":true},{"text":", resource allocator, negotiator"}]]]},{"type":"paragraph","text":[{"text":"The three levels of management (the management pyramid):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Top managers:","bold":true},{"text":" the highest level (CEO, managing director, chief financial officer). Set long-term direction and strategic plans, and represent the firm to outsiders."}]},{"text":[{"text":"Middle managers:","bold":true},{"text":" heads of departments, divisions or plants. Turn top management's strategy into departmental plans and link top and first-line managers."}]},{"text":[{"text":"First-line (supervisory) managers:","bold":true},{"text":" supervisors, team leaders, shift managers. Oversee the people who do the work and handle day-to-day operations."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal:","bold":true},{"text":" the "},{"text":"figurehead","bold":true},{"text":" performs ceremonial duties (cutting the tape at a new branch); the "},{"text":"leader","bold":true},{"text":" guides and motivates staff; the "},{"text":"liaison","bold":true},{"text":" builds networks with people outside his unit."}]},{"text":[{"text":"Informational:","bold":true},{"text":" the "},{"text":"monitor","bold":true},{"text":" scans for information (reading business news, market reports); the "},{"text":"disseminator","bold":true},{"text":" passes information to staff; the "},{"text":"spokesperson","bold":true},{"text":" speaks for the organisation to outsiders such as the press, regulators or investors. When MTN Nigeria's CEO addresses journalists about a policy, he is a spokesperson, an "},{"text":"informational","bold":true},{"text":" role."}]},{"text":[{"text":"Decisional:","bold":true},{"text":" the "},{"text":"entrepreneur","bold":true},{"text":" starts improvements and new projects; the "},{"text":"disturbance handler","bold":true},{"text":" resolves conflicts and crises, acting as a "},{"text":"mediator","bold":true},{"text":"; the "},{"text":"resource allocator","bold":true},{"text":" decides who gets money, people and time; the "},{"text":"negotiator","bold":true},{"text":" bargains with unions, suppliers or partners."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"spokesperson\" sounds like talking to people, so students pick interpersonal. It is "},{"text":"informational","bold":true},{"text":". Resolving a conflict is decisional (disturbance handler), not interpersonal. \"Skill-based role\" or \"technical role\" is not one of the groups."}]},{"text":[{"text":"All managers perform all roles, but the mix changes with level: top managers spend more time as figurehead, spokesperson and negotiator; the leader role matters most for first-line managers on the shop floor."}]}]}]},{"number":"7.2","title":"The planning function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning:","bold":true},{"text":" the function of "},{"text":"defining objectives (goals) and the strategies and tactics","bold":true},{"text":" to reach them. It is the first function; the others depend on it."}]},{"text":[{"text":"Vision statement:","bold":true},{"text":" a brief, inspiring statement of what the organisation wants to become in the future."}]},{"text":[{"text":"Mission statement:","bold":true},{"text":" a statement of the organisation's purpose: what it does, whom it serves and its basic values."}]},{"text":[{"text":"Goal:","bold":true},{"text":" a broad, long-range target. "},{"text":"Objective:","bold":true},{"text":" a specific, measurable, shorter-range target that helps reach a goal."}]},{"text":[{"text":"SWOT analysis:","bold":true},{"text":" "},{"text":"Strengths, Weaknesses, Opportunities and Threats","bold":true},{"text":". Strengths and weaknesses are "},{"text":"internal","bold":true},{"text":"; opportunities and threats are "},{"text":"external","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Types of plans:","bold":true}]},{"type":"table","header":[[{"text":"Plan"}],[{"text":"Made by"}],[{"text":"Time frame"}],[{"text":"Example"}]],"rows":[[[{"text":"Strategic","bold":true}],[{"text":"top managers"}],[{"text":"long term (several years)"}],[{"text":"enter West African markets under ECOWAS"}]],[[{"text":"Tactical","bold":true}],[{"text":"middle managers"}],[{"text":"medium term"}],[{"text":"a region's sales plan for the year"}]],[[{"text":"Operational","bold":true}],[{"text":"first-line managers"}],[{"text":"short term (days, weeks, months)"}],[{"text":"this week's production schedule"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategic planning steps:","bold":true},{"text":" (1) define the mission, vision and values; (2) assess the organisation's strengths, weaknesses, opportunities and threats (SWOT); (3) develop forecasts; (4) analyse the competition; (5) establish goals and objectives; (6) develop action plans (strategies and tactics) to reach them."}]},{"text":[{"text":"SWOT example (a Nigerian cement maker):","bold":true},{"text":" strength = large plant and strong brand; weakness = high diesel and power costs; opportunity = growing housing demand; threat = cheap imports or a sharp fall in the naira. Internal factors are within the firm's control; external ones are not."}]},{"text":[{"text":"Good objectives are "},{"text":"SMART","bold":true},{"text":": Specific, Measurable, Achievable, Relevant, Time-bound. \"Increase sales\" is a goal; \"increase sales in Lagos by 10% by December\" is an objective."}]},{"text":[{"text":"Crisis management (contingency planning):","bold":true},{"text":" planning ahead for emergencies such as fire, product recalls or system failure, so the firm can respond quickly and protect people and its reputation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" budget goal-setting and fiscal forecasting are "},{"text":"planning","bold":true},{"text":", not organising or controlling. Tracking staff output is "},{"text":"controlling","bold":true},{"text":"; recruiting is "},{"text":"staffing/HR","bold":true},{"text":"; mediating disputes is "},{"text":"leading","bold":true},{"text":"."}]}]}]},{"number":"7.3","title":"The organising function: structure and teams","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organising:","bold":true},{"text":" arranging resources, "},{"text":"assigning tasks, duties and roles","bold":true},{"text":", grouping people into departments and "},{"text":"delegating","bold":true},{"text":" authority so that plans can be carried out."}]},{"text":[{"text":"Organisation structure:","bold":true},{"text":" the framework that defines roles, "},{"text":"who does what and who reports to whom","bold":true},{"text":". An effective structure gives "},{"text":"clearly defined duties and roles","bold":true},{"text":", smooth communication and good output."}]},{"text":[{"text":"Chain of command:","bold":true},{"text":" the line of authority from the top to the bottom. "},{"text":"Span of control:","bold":true},{"text":" the number of people who report directly to one manager. "},{"text":"Delegation:","bold":true},{"text":" giving a subordinate authority and responsibility for a task."}]}]},{"type":"table","header":[[{"text":"Tall (hierarchical) structure"}],[{"text":"Flat structure"}]],"rows":[[[{"text":"many layers (tiers) of management"}],[{"text":"few (minimal)","bold":true},{"text":" layers of management"}]],[[{"text":"narrow span of control"}],[{"text":"wide span of control"}]],[[{"text":"slower decisions and communication"}],[{"text":"faster decisions, more staff freedom"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Other structures: "},{"text":"functional","bold":true},{"text":" (departments by function: marketing, finance, HR), "},{"text":"divisional","bold":true},{"text":" (by product or region), "},{"text":"matrix","bold":true},{"text":" (staff report to both a functional manager and a project manager)."}]},{"text":[{"text":"Unstructured (flexible) organisation:","bold":true},{"text":" few formal rules, loose roles, "},{"text":"adaptability and fluidity","bold":true},{"text":"; common in tech start-ups. Managing it requires "},{"text":"flexibility and ingenuity (creativity)","bold":true},{"text":", not tight oversight."}]},{"text":[{"text":"Team:","bold":true},{"text":" a group of people working together toward a "},{"text":"common goal","bold":true},{"text":", sharing responsibility for the result."}]}]},{"type":"paragraph","text":[{"text":"Benefits of organising in teams:","bold":true},{"text":" higher output (enhanced productivity) · quicker problem-solving · more ideas and creativity · better coordination · greater commitment and morale."}]},{"type":"paragraph","text":[{"text":"What makes teams productive (4):","bold":true},{"text":" clear (precise) goals · the tools and resources needed · open and clear communication · trust and unity among members."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Types of teams:","bold":true},{"text":" "},{"text":"functional","bold":true},{"text":" (people from one department), "},{"text":"cross-functional","bold":true},{"text":" (people from different departments, such as product launch teams), "},{"text":"problem-solving","bold":true},{"text":" (formed to fix a specific issue), "},{"text":"self-managed","bold":true},{"text":" (manage themselves with little supervision), "},{"text":"virtual","bold":true},{"text":" (members in different locations linked by technology, e.g. on Zoom or WhatsApp)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a flat structure still has authority levels; it simply has fewer of them. \"No authority levels\" is wrong."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fixed chain of command and rigid rules describe a "},{"text":"highly structured","bold":true},{"text":" firm, not an unstructured one."}]},{"text":[{"text":"Team problems such as distrust, unclear targets, persistent disputes, slow decisions and stifled ideas are the result of "},{"text":"poorly managed","bold":true},{"text":" teams, never benefits. To foster teamwork, a manager builds trust, keeps everyone focused on shared objectives and invites every member's input; setting members against each other destroys it."}]}]}]},{"number":"7.4","title":"The leading function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leading:","bold":true},{"text":" guiding, "},{"text":"motivating and inspiring","bold":true},{"text":" people (raising team morale) so they work willingly toward the organisation's goals. It includes communicating, directing, coaching and resolving conflicts."}]},{"text":[{"text":"Leadership:","bold":true},{"text":" the ability to influence others to achieve goals. Managers plan and control; leaders inspire and set direction. Good managers do both."}]}]},{"type":"paragraph","text":[{"text":"Leadership styles:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Autocratic:","bold":true},{"text":" the leader makes decisions alone and expects obedience. Fast; useful in emergencies; can lower morale."}]},{"text":[{"text":"Democratic (participative):","bold":true},{"text":" the leader involves staff in decisions; final decision often by the leader or the group. Builds commitment; slower."}]},{"text":[{"text":"Laissez-faire (free-rein):","bold":true},{"text":" the leader gives broad goals and leaves employees to decide how to work. Suits skilled, self-motivated staff."}]},{"text":[{"text":"Situational (contingency) leadership:","bold":true},{"text":" no single best style; the leader adapts to the people, the task and the situation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Coaching","bold":true},{"text":" is helping employees build skills and confidence through guidance and feedback. "},{"text":"Mentoring","bold":true},{"text":" is an experienced manager or employee guiding a less experienced colleague's career."}]},{"text":[{"text":"Leaders also "},{"text":"manage change","bold":true},{"text":" (helping staff accept new systems) and build "},{"text":"organisational culture","bold":true},{"text":": the shared values, beliefs and norms of the firm."}]},{"text":[{"text":"An autocratic style may suit a factory fire drill; a laissez-faire style suits a team of experienced software engineers."}]},{"text":[{"text":"Trap:","bold":true},{"text":" output oversight is controlling, not leading; fiscal forecasting is planning; product development is an operational activity, not a management function."}]}]}]},{"number":"7.5","title":"The controlling function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling:","bold":true},{"text":" "},{"text":"monitoring performance, comparing it with targets and taking corrective action","bold":true},{"text":" so that goals are met. It is the last function and feeds back into planning."}]}]},{"type":"paragraph","text":[{"text":"The control cycle (4 steps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set standards","bold":true},{"text":" (targets drawn from the plan's objectives)."}]},{"text":[{"text":"Measure","bold":true},{"text":" actual performance."}]},{"text":[{"text":"Compare","bold":true},{"text":" performance with the standards."}]},{"text":[{"text":"Take corrective action","bold":true},{"text":" where there is a gap (or reward good results)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example: a bank branch sets a target of opening 500 new accounts in a quarter. At mid-quarter it has opened 150, so the manager investigates and adds staff to the account-opening desk. That is controlling."}]},{"text":[{"text":"Balanced scorecard:","bold":true},{"text":" a control tool that measures performance from four perspectives (financial, customer, internal business processes, and learning and growth), not money alone."}]},{"text":[{"text":"Quality checks, budgets compared with actual spending, and performance reviews are all control tools. Performance reviews belong to "},{"text":"controlling","bold":true},{"text":", not organising."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"finances are overlooked\" is the opposite of control. Onboarding staff is staffing (HR); advertising goods is marketing."}]}]}]},{"number":"7.6","title":"Essential management skills","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Technical skills:","bold":true},{"text":" the knowledge and ability to perform the specific tasks of a job (hands-on expertise), such as accounting, coding or operating machinery. Most needed by "},{"text":"first-line","bold":true},{"text":" managers."}]},{"text":[{"text":"Interpersonal (human) skills:","bold":true},{"text":" the ability to communicate with, understand, motivate and work with people (teamwork aptitude). Includes "},{"text":"communication","bold":true},{"text":". Needed at "},{"text":"all levels","bold":true},{"text":"."}]},{"text":[{"text":"Conceptual skills:","bold":true},{"text":" the ability to see the organisation as a whole, think "},{"text":"strategically","bold":true},{"text":" and understand how its parts relate (big-picture or visionary capability). Most needed by "},{"text":"top","bold":true},{"text":" managers."}]},{"text":[{"text":"Decision-making skills:","bold":true},{"text":" the ability to define problems, weigh options and choose the best course of action (problem-solving, issue resolution)."}]}]},{"type":"paragraph","text":[{"text":"Steps in decision-making:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Recognise and define the problem or opportunity."}]},{"text":[{"text":"Identify and develop options."}]},{"text":[{"text":"Analyse the options."}]},{"text":[{"text":"Select the best option."}]},{"text":[{"text":"Implement the decision."}]},{"text":[{"text":"Monitor the results and adjust."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dialogue (communication) and issue resolution (problem-solving)","bold":true},{"text":" are the essential management skills an exam expects. Dismissing input, shunning collaboration and a profit-only focus are weaknesses."}]},{"text":[{"text":"As a manager rises, technical skill matters less and conceptual skill matters more; interpersonal skill stays important throughout."}]},{"text":[{"text":"Programmed decisions","bold":true},{"text":" are routine and follow set rules (reordering stock when it falls to a set level). "},{"text":"Non-programmed decisions","bold":true},{"text":" are new, one-off and complex (entering a new country)."}]},{"text":[{"text":"Time management","bold":true},{"text":" (prioritising and delegating) supports all four skills."}]},{"text":[{"text":"Trap:","bold":true},{"text":" strategic thinking is "},{"text":"conceptual","bold":true},{"text":" skill, not technical (hands-on) or human (teamwork) skill."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A manager's primary role is to drive organisational objectives through planning, organising, leading and controlling."}]},{"text":[{"text":"10 roles in 3 groups: interpersonal (figurehead, leader, liaison), informational (monitor, disseminator, spokesperson), decisional (entrepreneur, disturbance handler, resource allocator, negotiator)."}]},{"text":[{"text":"Spokesperson = informational; resolving conflict = disturbance handler (mediator), decisional."}]},{"text":[{"text":"Levels: top (strategic), middle (tactical), first-line (operational)."}]},{"text":[{"text":"Planning = objectives and tactics; vision, mission, goals, objectives; SWOT = Strengths, Weaknesses, Opportunities, Threats."}]},{"text":[{"text":"Organising = assigning tasks and roles; flat structure = few management tiers; unstructured firm = adaptable and fluid, managed with flexibility and ingenuity."}]},{"text":[{"text":"Teams raise output and fix issues faster; they need clear goals, tools, open communication and trust."}]},{"text":[{"text":"Leading = inspiring and motivating; styles: autocratic, democratic, laissez-faire, situational."}]},{"text":[{"text":"Controlling = set standards, measure, compare, correct."}]},{"text":[{"text":"Skills: technical, interpersonal, conceptual (strategic thinking), decision-making."}]}]}],"theory":{"itemId":"453584a8-5d88-577a-b936-3903f3c291a1","question":[{"type":"paragraph","text":[{"text":"Explain the four functions of management, giving one example of each."}]}]},"practice":[{"topic":"Management Roles, Functions and Skills","named":true},{"topic":"Organization and Teamwork","named":true}]}},{"itemId":"8314272c-90fd-529a-a3c8-08685cb4adac","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Production Systems and Operations","body":"The systems view of business (open systems, boundaries, input-process-output, feedback); value chains and value webs; supply chain management; production and operations management and the types of production; the distinctive challenges of service delivery; product quality and process quality.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The systems view of business (open systems, boundaries, input-process-output, feedback); value chains and value webs; supply chain management; production and operations management and the types of production; the distinctive challenges of service delivery; product quality and process quality."}],"lessons":[{"number":"8.1","title":"The systems view of business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"System:","bold":true},{"text":" a series of related parts that are dependent on one another; a group of interacting or interrelated elements that act according to a set of rules to form a "},{"text":"unified whole","bold":true},{"text":"."}]},{"text":[{"text":"Business system:","bold":true},{"text":" a defined set of principles, practices and procedures applied to specific activities to achieve a specific result."}]},{"text":[{"text":"Systems view of business:","bold":true},{"text":" sees a company as a complex, "},{"text":"interconnected","bold":true},{"text":" system of "},{"text":"interdependent parts","bold":true},{"text":" (departments or functions). Each part contributes to the organisation's overall goals, and a change in one area can affect the entire system. It views the business "},{"text":"as a whole rather than as isolated parts","bold":true},{"text":", and takes account of its interactions with the external environment."}]},{"text":[{"text":"Organisational boundary:","bold":true},{"text":" the line that "},{"text":"separates the organisation (the system) from its environment","bold":true},{"text":". Inputs cross it coming in; outputs cross it going out."}]}]},{"type":"paragraph","text":[{"text":"4 basic points of the systems view:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Interdependence:","bold":true},{"text":" each component (marketing, finance, operations and so on) relies on the others, so a change in one area has ripple effects throughout the organisation."}]},{"text":[{"text":"Open system:","bold":true},{"text":" most businesses constantly interact with, and are influenced by, factors outside the organisation: market trends, customer needs, economic conditions."}]},{"text":[{"text":"Input-process-output:","bold":true},{"text":" inputs (resources, information) are transformed through processes into outputs (products, services)."}]},{"text":[{"text":"Feedback loop:","bold":true},{"text":" the system continuously monitors its performance and adjusts its processes based on feedback from the environment and from internal operations."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Open vs closed:","bold":true},{"text":" an open system interacts with its environment (inputs in, outputs out, feedback back); a closed system is cut off from it. Almost every real business is open."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A business transforms "},{"text":"lower-value inputs into higher-value outputs","bold":true},{"text":", adding value at every stage. A bakery takes in flour, labour, ovens and electricity (inputs), bakes (transformation) and sells bread (output). Complaints about stale bread are "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"Interdependence: if marketing runs a big promotion without telling production, stock runs out and finance loses revenue."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the systems view focuses on "},{"text":"interconnected business parts","bold":true},{"text":", not on isolated job functions, promotion alone or budgeting alone."}]},{"text":[{"text":"Trap:","bold":true},{"text":" an "},{"text":"organisational","italic":true},{"text":" boundary surrounds the whole organisation; a "},{"text":"process","italic":true},{"text":" boundary marks the limits of a single process. Exams ask for the first."}]}]}]},{"number":"8.2","title":"Value chains and value webs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value chain:","bold":true},{"text":" a "},{"text":"linear sequence of activities within a company","bold":true},{"text":" that add value to a product or service at each stage, from raw materials to the final customer. In short, the steps that enhance a product's worth."}]},{"text":[{"text":"Value chain analysis:","bold":true},{"text":" a framework (Michael "},{"text":"Porter","bold":true},{"text":") for analysing a company's activities and identifying areas of "},{"text":"competitive advantage","bold":true},{"text":". It breaks operations into activities classified into "},{"text":"2 basic sets","bold":true},{"text":": "},{"text":"primary","bold":true},{"text":" and "},{"text":"support","bold":true},{"text":" activities."}]}]},{"type":"paragraph","text":[{"text":"5 primary activities","bold":true},{"text":" (directly make, sell and support the product):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inbound logistics:","bold":true},{"text":" receiving, storing and handling raw materials and inputs coming in."}]},{"text":[{"text":"Operations:","bold":true},{"text":" turning inputs into the finished product."}]},{"text":[{"text":"Outbound logistics:","bold":true},{"text":" storing and "},{"text":"distributing finished goods (inventory)","bold":true},{"text":" to customers."}]},{"text":[{"text":"Marketing and sales:","bold":true},{"text":" persuading customers to buy; pricing, advertising, selling."}]},{"text":[{"text":"Service:","bold":true},{"text":" after-sales support: installation, repairs, customer care."}]}]},{"type":"paragraph","text":[{"text":"4 support activities","bold":true},{"text":" (help the primary activities work):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Procurement:","bold":true},{"text":" buying inputs."}]},{"text":[{"text":"Technology development:","bold":true},{"text":" research, design, process improvement, IT."}]},{"text":[{"text":"Human resource management:","bold":true},{"text":" recruiting, training, rewarding staff."}]},{"text":[{"text":"Firm infrastructure:","bold":true},{"text":" general management, planning, finance, legal, quality systems."}]}]},{"type":"paragraph","text":[{"text":"3 steps in value chain analysis:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the primary activities."}]},{"text":[{"text":"Identify the support activities."}]},{"text":[{"text":"Analyse the linkages between these activities."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Value web:","bold":true},{"text":" a more complex "},{"text":"network of interconnected value chains across different companies","bold":true},{"text":", often involving collaborations and partnerships, where value is created through multiple interactions between stakeholders in a "},{"text":"less linear","bold":true},{"text":" fashion. Essentially, a value web is a "},{"text":"network of value chains","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Value chain"}],[{"text":"Value web"}]],"rows":[[[{"text":"Linear (straight-line)"}],[{"text":"Network, less linear"}]],[[{"text":"Within one company"}],[{"text":"Across many companies and partners"}]],[[{"text":"One firm does most steps itself"}],[{"text":"Firms specialise and link their chains together"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Count traps: "},{"text":"2","bold":true},{"text":" basic sets, "},{"text":"5","bold":true},{"text":" primary activities, "},{"text":"4","bold":true},{"text":" support activities, "},{"text":"3","bold":true},{"text":" steps of analysis. Read the question carefully to see which count it wants."}]},{"text":[{"text":"Trap:","bold":true},{"text":" technology development, procurement, HR management and firm infrastructure are "},{"text":"support","bold":true},{"text":", never primary. Marketing and sales and service are "},{"text":"primary","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" inbound logistics = materials coming "},{"text":"in","bold":true},{"text":"; outbound logistics = finished goods going "},{"text":"out","bold":true},{"text":" (distribution of inventory)."}]},{"text":[{"text":"Example: a bottling company receives sugar (inbound), bottles drinks (operations), trucks crates to distributors (outbound), advertises (marketing and sales) and fixes shop coolers (service); its HR and IT are support."}]},{"text":[{"text":"Value webs arise when firms "},{"text":"outsource","bold":true},{"text":" and partner: a phone brand designs phones, buys chips from one firm, has another assemble them and sells bundles through MTN. Each firm runs its own chain; together they form a web, giving flexibility but less control."}]}]}]},{"number":"8.3","title":"Supply chain management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Supply chain:","bold":true},{"text":" the set of firms and activities that bring a product from its raw materials to the end consumer."}]},{"text":[{"text":"Supply chain management (SCM):","bold":true},{"text":" coordinating and "},{"text":"overseeing","bold":true},{"text":" the activities involved in producing, distributing and delivering goods or services from their "},{"text":"source to the end consumer","bold":true},{"text":"; everything from sourcing raw components to delivering the final result. In short, managing the "},{"text":"flow of goods","bold":true},{"text":"."}]},{"text":[{"text":"Key activities:","bold":true},{"text":" sourcing, design, production, warehousing, shipping, distribution, order management."}]},{"text":[{"text":"Goal:","bold":true},{"text":" to improve "},{"text":"efficiency, quality, productivity and customer satisfaction","bold":true},{"text":"."}]},{"text":[{"text":"Scope:","bold":true},{"text":" managing internal resources, operations management, and coordinating with external partners: suppliers, manufacturers, distributors, retailers and customers."}]},{"text":[{"text":"Importance:","bold":true},{"text":" ensures products are available "},{"text":"when and where needed","bold":true},{"text":", minimising costs and maximising profits."}]}]},{"type":"paragraph","text":[{"text":"5 components of SCM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Procurement:","bold":true},{"text":" sourcing raw materials and other components."}]},{"text":[{"text":"Production:","bold":true},{"text":" manufacturing the product."}]},{"text":[{"text":"Logistics:","bold":true},{"text":" managing the movement and storage of goods."}]},{"text":[{"text":"Distribution:","bold":true},{"text":" getting the finished product to the end customer."}]},{"text":[{"text":"Order management:","bold":true},{"text":" handling customer orders and ensuring timely fulfilment."}]}]},{"type":"paragraph","text":[{"text":"5 stages in the concept of SCM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Planning the supply chain network:","bold":true},{"text":" plan each \"link\" so steps join smoothly and every stakeholder knows its responsibilities."}]},{"text":[{"text":"Sourcing materials:","bold":true},{"text":" choose suppliers, decide how much to order, track supplies, pay suppliers."}]},{"text":[{"text":"Organising manufacturers:","bold":true},{"text":" find the right manufacturer to turn raw materials into the end product."}]},{"text":[{"text":"Delivery of the product:","bold":true},{"text":" reliable logistics; damaged goods, late delivery or wrong orders hurt reputation and lose customers."}]},{"text":[{"text":"Managing return services:","bold":true},{"text":" convenient returns and exchanges; reduces waste, since returned items can go to other customers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SCM involves the flow of "},{"text":"goods, information and money","bold":true},{"text":" among all the partners. It is about overseeing and coordinating flow, never halting production, ignoring vendors or restricting delivery."}]},{"text":[{"text":"Supply chain vs value chain:","bold":true},{"text":" the supply chain looks at how materials and products "},{"text":"move","bold":true},{"text":" from source to consumer; the value chain looks at how each activity "},{"text":"adds value","bold":true},{"text":". They overlap heavily, and SCM is how a firm manages its part of the value web."}]},{"text":[{"text":"Example: a Lagos supermarket chain orders from manufacturers, warehouses stock, trucks it to branches and handles returns; a break at any link (a port backlog, fuel scarcity) leaves empty shelves."}]},{"text":[{"text":"Inventory:","bold":true},{"text":" too much ties up money and space; too little loses sales. "},{"text":"Just-in-time (JIT)","bold":true},{"text":" delivers materials only as needed, cutting storage costs but exposing the firm to late suppliers."}]}]}]},{"number":"8.4","title":"Production and operations management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production system:","bold":true},{"text":" a system used to produce goods or services, often with multiple steps that must be completed to produce the final product. In operations management, it is the "},{"text":"organised set of activities, processes and resources involved in transforming inputs into finished goods or services","bold":true},{"text":"."}]},{"text":[{"text":"Production and operations management (POM):","bold":true},{"text":" the process of using (turning) an organisation's resources to "},{"text":"create and deliver goods and services","bold":true},{"text":". It involves "},{"text":"planning, scheduling and controlling","bold":true},{"text":" production so that products are made and delivered "},{"text":"on time and in line with customer demand","bold":true},{"text":"."}]},{"text":[{"text":"Production management","bold":true},{"text":" relates to the activities around "},{"text":"creating products","bold":true},{"text":". "},{"text":"Operations management","bold":true},{"text":" concerns the "},{"text":"production and delivery","bold":true},{"text":" of products and services."}]},{"text":[{"text":"Aim of operations management:","bold":true},{"text":" produce efficiently, "},{"text":"boosting quality and output","bold":true},{"text":" while using resources well and cutting waste."}]}]},{"type":"paragraph","text":[{"text":"Scope of production management","bold":true},{"text":" (planning, organising, directing and controlling production; it starts with input and ends with output, the finished good):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Location of facilities:","bold":true},{"text":" a key decision because large investment goes into land, buildings and machinery."}]},{"text":[{"text":"Plant layout and material handling:","bold":true},{"text":" layout = physical arrangement of facilities; material handling = moving materials from the storeroom to the machine and from one machine to the next."}]},{"text":[{"text":"Product design:","bold":true},{"text":" converting ideas about the product into reality."}]},{"text":[{"text":"Process design:","bold":true},{"text":" deciding the overall process route for converting raw materials into finished goods."}]}]},{"type":"table","header":[[{"text":"Production management"}],[{"text":"Operations management"}]],"rows":[[[{"text":"Manages all production activities"}],[{"text":"Manages complete overall business operations, including production and post-production stages"}]],[[{"text":"Limited scope: design, pricing, quality and quantity of goods"}],[{"text":"Broader scope: routine activities such as workforce and inventory management"}]],[[{"text":"High initial capital requirement"}],[{"text":"Lower capital requirement"}]],[[{"text":"Only where products are manufactured"}],[{"text":"All organisations, including banks and hospitals"}]]]},{"type":"paragraph","text":[{"text":"Types of production:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Mass production:","bold":true},{"text":" large quantities of "},{"text":"identical","bold":true},{"text":" (standardised) goods, usually on assembly lines, at low unit cost. Example: bottled water, cement."}]},{"text":[{"text":"Customised production:","bold":true},{"text":" goods or services made to "},{"text":"each customer's individual order","bold":true},{"text":" (also called job production when one-off). Example: a tailor sewing an agbada, a building contractor."}]},{"text":[{"text":"Mass customisation:","bold":true},{"text":" a blend: standard parts mass-produced, then combined to suit individual customers. Example: choosing a laptop's memory and storage when ordering."}]},{"text":[{"text":"Batch production:","bold":true},{"text":" a set quantity (batch) of one product is made, then the equipment is switched to the next batch. Example: a bakery baking batches of different breads."}]},{"text":[{"text":"Continuous production:","bold":true},{"text":" operations run "},{"text":"non-stop","bold":true},{"text":", often 24 hours a day, turning out a constant flow of standard output. Example: oil refining, cement and flour milling."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" POM focuses on "},{"text":"streamlined (efficient) goods creation","bold":true},{"text":", not advertising (marketing), recruitment (HR) or financial targets (finance)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" operations management is the "},{"text":"broader","bold":true},{"text":" term and applies to service firms too; production management applies only where goods are manufactured."}]},{"text":[{"text":"Other POM decisions: "},{"text":"forecasting","bold":true},{"text":" demand, "},{"text":"capacity planning","bold":true},{"text":" (how much a plant, e.g. a Dangote cement plant, can produce), "},{"text":"scheduling","bold":true},{"text":" (what is done when) and "},{"text":"inventory control","bold":true},{"text":"."}]},{"text":[{"text":"Lean production:","bold":true},{"text":" maximum output with minimum waste; JIT is one lean tool."}]},{"text":[{"text":"Higher volume and standardisation lower unit cost but reduce flexibility; customised production is flexible but costly per unit."}]}]}]},{"number":"8.5","title":"Service delivery and quality","mustKnow":[{"type":"paragraph","text":[{"text":"Distinctive challenges of service delivery:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Intangibility:","bold":true},{"text":" services cannot be seen, touched or stored before purchase, so quality is hard to judge."}]},{"text":[{"text":"Perishability:","bold":true},{"text":" an unsold service is lost for ever (an empty seat on a flight, an unused hour of a barber's time); it cannot be stored as inventory."}]},{"text":[{"text":"Customer participation (involvement):","bold":true},{"text":" many services are produced while the customer is present and taking part (salon, clinic, classroom), so the customer's own input affects the result."}]},{"text":[{"text":"Variability (performance variability):","bold":true},{"text":" services are performed by people, so quality varies from one provider, customer or day to the next; "},{"text":"quality control is variable","bold":true},{"text":" and hard."}]},{"text":[{"text":"Location constraints and scalability:","bold":true},{"text":" many services must be delivered where the customer is, and grow only by adding people, so expanding is harder than running a factory extra hours."}]},{"text":[{"text":"Management difficulties:","bold":true},{"text":" service delivery needs planning and many management skills: "},{"text":"time management","bold":true},{"text":" (several jobs at once), "},{"text":"managing other people's work","bold":true},{"text":" (one of the biggest challenges) and "},{"text":"coordination","bold":true},{"text":": "},{"text":"poor coordination between departments leads to poor service quality","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Product quality vs process quality:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Product quality:","bold":true},{"text":" the inherent characteristics of the "},{"text":"final product","bold":true},{"text":", judged by whether it "},{"text":"meets customer expectations (standards)","bold":true},{"text":" in functionality, durability and other attributes."}]},{"text":[{"text":"Process quality:","bold":true},{"text":" how well a production "},{"text":"process","bold":true},{"text":" adheres to established standards and procedures, ensuring "},{"text":"consistency and minimising defects","bold":true},{"text":" at each step; the efficiency of the production method."}]},{"text":[{"text":"Link:","bold":true},{"text":" good process quality directly contributes to high product quality."}]},{"text":[{"text":"Process vs product:","bold":true},{"text":" a process is a set of steps that guides the work to a good product; a product is the result."}]}]},{"type":"table","header":[[{"text":"Product"}],[{"text":"Process"}]],"rows":[[[{"text":"The final output"}],[{"text":"A sequence of steps to create the output"}]],[[{"text":"Focuses on the final result"}],[{"text":"Focuses on completing each step"}]],[[{"text":"Follows firm guidelines"}],[{"text":"Consistently follows guidelines"}]],[[{"text":"Tends to be short-term"}],[{"text":"Tends to be long-term"}]],[[{"text":"Goal: complete the work successfully"}],[{"text":"Goal: make the quality better"}]],[[{"text":"Created from customers' needs and expectations"}],[{"text":"A model for producing various goods in a similar way"}]],[[{"text":"Product layout:","bold":true},{"text":" materials placed in a single line in the order of operations"}],[{"text":"Process layout:","bold":true},{"text":" resources with similar processes or functions grouped together"}]],[[{"text":"Product patents give greater protection"}],[{"text":"Process patents give only limited protection"}]]]},{"type":"paragraph","text":[{"text":"Quality tools:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statistical process control (SPC):","bold":true},{"text":" sampling output and charting results to spot when a process drifts from its standard."}]},{"text":[{"text":"Continuous improvement (kaizen):","bold":true},{"text":" constant small improvements by everyone."}]},{"text":[{"text":"Total quality management (TQM):","bold":true},{"text":" an organisation-wide commitment to quality and customer satisfaction."}]},{"text":[{"text":"Six Sigma:","bold":true},{"text":" a data-driven method aiming at no more than "},{"text":"3.4 defects per million","bold":true},{"text":" opportunities."}]},{"text":[{"text":"ISO 9000 family:","bold":true},{"text":" international quality management standards; firms are certified under "},{"text":"ISO 9001","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the challenges of services are "},{"text":"variable quality control","bold":true},{"text":" and "},{"text":"client participation","bold":true},{"text":". \"Tangible consistency\", \"uniform execution\", \"low variation\" and \"minimal client contact\" describe physical goods, the opposite."}]},{"text":[{"text":"Trap:","bold":true},{"text":" product quality is about "},{"text":"meeting customer standards","bold":true},{"text":", not production cost, promotion, or looks alone. Process quality is about "},{"text":"production method efficiency","bold":true},{"text":", not costs, promotion or staff onboarding."}]},{"text":[{"text":"In Nigeria, the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":" sets and enforces standards for products. ISO 9001 certification signals that a firm's processes meet an international standard."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A system is interdependent parts forming a unified whole; the systems view sees a business as interconnected parts, not isolated functions."}]},{"text":[{"text":"Systems view: interdependence, open system, input-process-output, feedback loop. The organisational boundary separates the organisation from its environment."}]},{"text":[{"text":"Value chain = linear steps adding value inside one firm (Porter): 2 sets, 5 primary, 4 support activities, 3 steps of analysis."}]},{"text":[{"text":"Primary: inbound logistics, operations, outbound logistics (distribution of inventory), marketing and sales, service. Support: procurement, technology development, HRM, firm infrastructure."}]},{"text":[{"text":"Value web = a network of linked value chains across firms."}]},{"text":[{"text":"SCM oversees the flow of goods from source to end consumer: procurement, production, logistics, distribution, order management."}]},{"text":[{"text":"POM = planning, scheduling and controlling the turning of resources into goods and services; operations management is broader than production management."}]},{"text":[{"text":"Types of production: mass, customised, mass customisation, batch, continuous."}]},{"text":[{"text":"Service challenges: intangibility, perishability, customer participation, variability, coordination."}]},{"text":[{"text":"Product quality = meeting customer expectations; process quality = consistent, efficient production method."}]}]}],"theory":{"itemId":"b84670c8-cb91-50a2-a46c-3ca12b27c710","question":[{"type":"paragraph","text":[{"text":"Explain the value chain and identify its primary and support activities. How does a value web differ from a value chain?"}]}]},"practice":[{"topic":"Production Systems","named":false}]}},{"itemId":"2e86475e-0eb9-5cf3-a8b8-8397743dbcd4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"note","questionId":null,"sourceKey":"guide-topic:9","parentItemId":null,"revision":1,"payload":{"title":"Employee Motivation","body":"What motivation is and why it matters; what motivates employees (intrinsic vs extrinsic, financial vs non-financial); classical and human relations views (Taylor, Hawthorne); McGregor's Theory X and Y and Ouchi's Theory Z; Maslow's hierarchy and Herzberg's two-factor theory; equity, expectancy and goal-setting theories; redesigning jobs (enrichment, enlargement, rotation); reinforcing high-performance behaviour; motivational strategies.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What motivation is and why it matters; what motivates employees (intrinsic vs extrinsic, financial vs non-financial); classical and human relations views (Taylor, Hawthorne); McGregor's Theory X and Y and Ouchi's Theory Z; Maslow's hierarchy and Herzberg's two-factor theory; equity, expectancy and goal-setting theories; redesigning jobs (enrichment, enlargement, rotation); reinforcing high-performance behaviour; motivational strategies."}],"lessons":[{"number":"9.1","title":"What motivation is and why it matters","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation:","bold":true},{"text":" a process of stimulating people to accomplish desired goals. In business, it is what makes employees put effort, energy and care into their work and keep at it."}]},{"text":[{"text":"Importance of motivation (3 core points):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Improves employee involvement."}]},{"text":[{"text":"Promotes job satisfaction."}]},{"text":[{"text":"Promotes interpersonal cooperation."}]}]}]},{"text":[{"text":"Motivation also "},{"text":"enhances job performance","bold":true},{"text":" and productivity, encourages creativity and "},{"text":"reduces staff turnover","bold":true},{"text":" (people leaving)."}]}]},{"type":"paragraph","text":[{"text":"Factors that motivate employees to improve performance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Meaningful work"}]},{"text":[{"text":"Clear goals and expectations"}]},{"text":[{"text":"Regular feedback, recognition and appreciation"}]},{"text":[{"text":"Opportunities for growth and development"}]},{"text":[{"text":"A positive work environment and strong leadership"}]},{"text":[{"text":"A sense of belonging"}]},{"text":[{"text":"Alignment with company values (feeling valued, challenged and empowered)"}]},{"text":[{"text":"Autonomy (freedom to decide how to do the work)"}]}]},{"type":"table","header":[[{"text":"Intrinsic motivation"}],[{"text":"Extrinsic motivation"}]],"rows":[[[{"text":"Comes from "},{"text":"inside","bold":true},{"text":" the person"}],[{"text":"Comes from "},{"text":"outside","bold":true},{"text":" the person"}]],[[{"text":"Satisfaction from the work itself: personal growth, interest, achievement"}],[{"text":"Rewards given by others: pay, bonuses, praise, promotion"}]]]},{"type":"table","header":[[{"text":"Financial motivators"}],[{"text":"Non-financial motivators"}]],"rows":[[[{"text":"Salary, wages, bonuses, overtime pay, commission, profit sharing"}],[{"text":"Recognition, praise, "},{"text":"promotion","bold":true},{"text":" (status and responsibility), training, job security, flexible hours, a pleasant work environment"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Employee choices:","bold":true},{"text":" the decisions employees make about their jobs and the benefits they receive, such as the design of welfare programmes, the benefits they take up and the development opportunities they pursue. Each choice is driven by intrinsic or extrinsic motivation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Low motivation shows up as lateness, absenteeism, poor-quality work, low output and people resigning. Lower productivity, higher turnover and less creativity are "},{"text":"results of poor motivation","bold":true},{"text":", never reasons why motivation is important."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a bonus, salary and overtime pay are all money, so they are financial. A promotion is classed as "},{"text":"non-financial","bold":true},{"text":" because its key value is higher status, more responsibility and growth, even though it often comes with a pay rise."}]},{"text":[{"text":"A bank officer in Lagos who stays late because she enjoys solving clients' problems is intrinsically motivated; one who stays only for overtime pay is extrinsically motivated. Most people are driven by a mix of both."}]}]}]},{"number":"9.2","title":"Early views: Taylor, Hawthorne, McGregor and Ouchi","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frederick W. Taylor (scientific management, early 1900s):","bold":true},{"text":" studied work scientifically (time-and-motion studies) to find the \"one best way\" to do each task. He believed workers are motivated mainly by "},{"text":"money","bold":true},{"text":", so he used "},{"text":"piece-rate pay","bold":true},{"text":" (paying per unit produced)."}]},{"text":[{"text":"The Hawthorne studies (human relations movement):","bold":true},{"text":" carried out from the 1920s at Western Electric's Hawthorne plant near Chicago; "},{"text":"Elton Mayo","bold":true},{"text":" is the name linked with them. Productivity rose whatever the researchers changed (for example, lighting), because workers felt "},{"text":"noticed and valued","bold":true},{"text":" and belonged to a group."}]},{"text":[{"text":"Hawthorne effect:","bold":true},{"text":" people change (usually improve) their behaviour when they know they are being observed or given attention."}]},{"text":[{"text":"Douglas McGregor (1960)","bold":true},{"text":" described two sets of managerial assumptions:"}]}]},{"type":"table","header":[[{"text":"Theory X"}],[{"text":"Theory Y"}]],"rows":[[[{"text":"Workers dislike work and avoid it"}],[{"text":"Work is as natural as play or rest"}]],[[{"text":"Must be controlled, directed, threatened"}],[{"text":"Workers exercise self-direction and self-control"}]],[[{"text":"Avoid responsibility, have little ambition"}],[{"text":"Accept and seek responsibility"}]],[[{"text":"Want security above all"}],[{"text":"Are creative and committed to goals they value"}]],[[{"text":"Leads to an "},{"text":"authoritarian","bold":true},{"text":", close-control style"}],[{"text":"Leads to a "},{"text":"participative","bold":true},{"text":", trusting style"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"William Ouchi's Theory Z (1981):","bold":true},{"text":" blends Japanese and American practices: long-term employment, "},{"text":"collective (consensus) decision-making","bold":true},{"text":", individual responsibility, slow evaluation and promotion, and concern for the "},{"text":"whole person","bold":true},{"text":" and their family."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The shift in thinking: Taylor treated workers as \"economic beings\" moved by pay; Hawthorne showed that "},{"text":"social and psychological factors","bold":true},{"text":" (attention, group belonging, morale) also drive output. This gave birth to the human relations approach."}]},{"text":[{"text":"Trap:","bold":true},{"text":" Theory X and Y are assumptions "},{"text":"managers","bold":true},{"text":" hold about workers, not two types of worker. A manager who clocks staff in and out and threatens query letters for every mistake is acting on Theory X; one who sets goals and lets the team decide how to meet them is acting on Theory Y."}]},{"text":[{"text":"Theory Z is by "},{"text":"Ouchi","bold":true},{"text":", not McGregor."}]}]}]},{"number":"9.3","title":"Needs theories: Maslow and Herzberg","mustKnow":[{"type":"paragraph","text":[{"text":"Abraham Maslow's hierarchy of needs","bold":true},{"text":" (from the base upwards, 5 levels):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological:","bold":true},{"text":" survival essentials: food, water, shelter, sleep. The "},{"text":"most basic","bold":true},{"text":" need. At work: a wage that pays for them."}]},{"text":[{"text":"Safety (security):","bold":true},{"text":" protection from harm, stable income. At work: job security, safe conditions, pension, health insurance."}]},{"text":[{"text":"Social (belongingness, love):","bold":true},{"text":" friendship, acceptance, being part of a group. At work: teamwork, friendly colleagues."}]},{"text":[{"text":"Esteem:","bold":true},{"text":" recognition, respect, status, self-respect. At work: titles, praise, awards, promotion."}]},{"text":[{"text":"Self-actualisation:","bold":true},{"text":" becoming all one is capable of; personal fulfilment. The "},{"text":"highest","bold":true},{"text":" need. At work: challenging, creative work and growth."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lower needs must be largely met before higher needs motivate. A "},{"text":"satisfied need no longer motivates","bold":true},{"text":"."}]},{"text":[{"text":"Physiological and safety = lower-order needs; social, esteem and self-actualisation = higher-order needs."}]}]},{"type":"paragraph","text":[{"text":"Frederick Herzberg's two-factor theory","bold":true},{"text":" (also called motivation-hygiene theory):"}]},{"type":"table","header":[[{"text":"Motivators (satisfiers)"}],[{"text":"Hygiene factors (maintenance factors)"}]],"rows":[[[{"text":"Linked to the "},{"text":"content","bold":true},{"text":" of the job"}],[{"text":"Linked to the "},{"text":"context","bold":true},{"text":" (surroundings) of the job"}]],[[{"text":"Achievement, recognition, the work itself, responsibility, advancement, growth"}],[{"text":"Salary, company policy, supervision, working conditions, relationships with colleagues, job security, status"}]],[[{"text":"Present: "},{"text":"motivate","bold":true},{"text":" and satisfy"}],[{"text":"Absent: cause "},{"text":"dissatisfaction","bold":true},{"text":". Present: only prevent dissatisfaction, they do "},{"text":"not","bold":true},{"text":" motivate"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Herzberg's key point: the opposite of satisfaction is "},{"text":"no satisfaction","bold":true},{"text":", and the opposite of dissatisfaction is "},{"text":"no dissatisfaction","bold":true},{"text":". Raising pay may stop complaints, but lasting motivation comes from motivators such as responsibility and recognition."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the two factors are \"motivation and maintenance (hygiene)\", never \"financial and relational\" or \"intrinsic and short-term\". Salary is a "},{"text":"hygiene","bold":true},{"text":" factor in Herzberg; recognition is a "},{"text":"motivator","bold":true},{"text":"."}]},{"text":[{"text":"Linking the two: Herzberg's hygiene factors roughly match Maslow's lower needs; his motivators match the higher needs (esteem, self-actualisation)."}]},{"text":[{"text":"Other needs-based ideas","bold":true},{"text":" you may meet: "},{"text":"David McClelland","bold":true},{"text":" (needs for achievement, affiliation and power) and "},{"text":"Lawrence and Nohria's four drives","bold":true},{"text":" (to acquire, to bond, to comprehend or learn, and to defend)."}]}]}]},{"number":"9.4","title":"Process theories: equity, expectancy and goal-setting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equity theory (J. Stacy Adams):","bold":true},{"text":" employees compare the ratio of their "},{"text":"inputs","bold":true},{"text":" (effort, skill, time, qualifications) to their "},{"text":"outcomes","bold":true},{"text":" (pay, recognition, promotion) with that of other people (a "},{"text":"referent","bold":true},{"text":"). They act based on whether the rewards seem "},{"text":"fair","bold":true},{"text":"."}]},{"text":[{"text":"If they feel under-rewarded they may: reduce effort, ask for a raise, cut quality, change who they compare with, or quit."}]},{"text":[{"text":"Expectancy theory (Victor Vroom):","bold":true},{"text":" people are motivated when they believe effort will lead to good performance, performance will bring a reward, and the reward is one they value. Three links:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Expectancy:","bold":true},{"text":" effort → performance (\"If I try, can I do it?\")"}]},{"text":[{"text":"Instrumentality:","bold":true},{"text":" performance → reward (\"If I do it, will I be rewarded?\")"}]},{"text":[{"text":"Valence:","bold":true},{"text":" value of the reward (\"Do I want that reward?\")"}]}]}]},{"text":[{"text":"If any link is zero, motivation collapses (Motivation = Expectancy × Instrumentality × Valence)."}]},{"text":[{"text":"Goal-setting theory (Edwin Locke):","bold":true},{"text":" "},{"text":"specific, challenging but attainable","bold":true},{"text":" goals produce higher performance than vague or easy goals (\"do your best\"), especially with "},{"text":"feedback","bold":true},{"text":" and when employees "},{"text":"accept","bold":true},{"text":" the goals."}]},{"text":[{"text":"Motivating with challenging goals:","bold":true},{"text":" setting goals that push people outside their comfort zone, so overcoming the difficulty brings a sense of accomplishment and personal growth, which raises motivation and engagement."}]},{"text":[{"text":"SMART goals:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific, "},{"text":"M","bold":true},{"text":"easurable, "},{"text":"A","bold":true},{"text":"chievable, "},{"text":"R","bold":true},{"text":"elevant, "},{"text":"T","bold":true},{"text":"ime-bound."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management by objectives (MBO):","bold":true},{"text":" manager and employee agree goals together, the employee works towards them, and progress is reviewed and rewarded. Participation increases goal acceptance."}]},{"text":[{"text":"A good challenging goal is "},{"text":"precise and trackable","bold":true},{"text":": \"raise sales in Ikeja by 10% by December\" beats \"sell more\". Goals that are "},{"text":"beyond realistic reach","bold":true},{"text":" discourage people; vague, simple targets or lowered expectations fail to stretch them; goals must stay "},{"text":"linked to results","bold":true},{"text":"."}]},{"text":[{"text":"Equity is about "},{"text":"perceived","bold":true},{"text":" fairness. If two graduates join an MTN office on the same grade and one learns the other earns ₦50,000 more, the first may feel inequity even if her own pay is good."}]},{"text":[{"text":"Equity and expectancy are called "},{"text":"process","bold":true},{"text":" theories because they explain "},{"text":"how","bold":true},{"text":" people choose their behaviour; Maslow and Herzberg are "},{"text":"content (needs)","bold":true},{"text":" theories because they explain "},{"text":"what","bold":true},{"text":" motivates."}]}]}]},{"number":"9.5","title":"Redesigning jobs and reinforcing high-performance behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job redesign:","bold":true},{"text":" a strategic process of reshaping jobs to fit business needs and the employee's skills and interests, so performance and satisfaction rise and roles stay relevant and engaging."}]},{"text":[{"text":"3 common types:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Job enrichment:","bold":true},{"text":" adds more tasks "},{"text":"and gives more authority","bold":true},{"text":" (responsibility, control, decision-making) to the job holder. Vertical expansion."}]},{"text":[{"text":"Job enlargement:","bold":true},{"text":" adds "},{"text":"more tasks at the same level","bold":true},{"text":" of difficulty and responsibility. Horizontal expansion; widens the range of tasks."}]},{"text":[{"text":"Job rotation:","bold":true},{"text":" moves employees "},{"text":"from one job to another","bold":true},{"text":" at intervals, giving variety and new skills (cross-training)."}]}]}]},{"text":[{"text":"Benefits of job redesign:","bold":true},{"text":" more control over work and more meaningful tasks; reduced stress; improved job satisfaction; reduced turnover."}]},{"text":[{"text":"Job characteristics model (Hackman and Oldham), 5 core dimensions:","bold":true},{"text":" skill variety, task identity, task significance, autonomy, feedback."}]},{"text":[{"text":"High-performance behaviours:","bold":true},{"text":" actions and attitudes that consistently lead to exceptional results and go beyond the job requirements: excellence, initiative, commitment."}]},{"text":[{"text":"Reinforcement theory:","bold":true},{"text":" behaviour that is followed by a pleasant consequence tends to be "},{"text":"repeated","bold":true},{"text":"; behaviour followed by an unpleasant consequence or no consequence tends to fade."}]}]},{"type":"table","header":[[{"text":"Method"}],[{"text":"What happens"}],[{"text":"Effect on behaviour"}]],"rows":[[[{"text":"Positive reinforcement","bold":true}],[{"text":"A reward is given (praise, bonus, extra days off)"}],[{"text":"Increases it"}]],[[{"text":"Negative reinforcement","bold":true}],[{"text":"Something unpleasant is removed when the right behaviour occurs"}],[{"text":"Increases it"}]],[[{"text":"Punishment","bold":true}],[{"text":"Something unpleasant is applied (query, fine)"}],[{"text":"Decreases it"}]],[[{"text":"Extinction","bold":true}],[{"text":"No response at all; behaviour is ignored"}],[{"text":"Decreases it"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" enrichment = "},{"text":"deeper","bold":true},{"text":" job (more authority); enlargement = "},{"text":"wider","bold":true},{"text":" job (more tasks, same level); rotation = "},{"text":"different","bold":true},{"text":" jobs in turn. Shrinking duties, narrowing tasks or limiting control is the opposite of good redesign."}]},{"text":[{"text":"Example: a cashier at a supermarket who now also orders stock and handles customer complaints with power to issue refunds has an "},{"text":"enriched","bold":true},{"text":" job. One who also packs bags and arranges shelves has an "},{"text":"enlarged","bold":true},{"text":" job. A trainee at Dangote moved through production, sales and logistics over a year is on "},{"text":"job rotation","bold":true},{"text":"."}]},{"text":[{"text":"Negative reinforcement is not punishment.","bold":true},{"text":" It "},{"text":"increases","bold":true},{"text":" good behaviour by removing something unpleasant, for example excusing a team that meets its targets from a tedious daily reporting requirement, or removing obstacles in their way."}]},{"text":[{"text":"Reinforcing high performance means "},{"text":"offering praise and rewards","bold":true},{"text":" promptly and specifically. Overlooking successes, cutting incentives or giving no feedback weakens the behaviour."}]}]}]},{"number":"9.6","title":"Motivational strategies","mustKnow":[{"type":"paragraph","text":[{"text":"Motivational strategies help employees feel more productive and engaged at work. They include:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Setting goals:","bold":true},{"text":" measurable and achievable, linked to the company's objectives."}]},{"text":[{"text":"Providing feedback:","bold":true},{"text":" frequent, meaningful feedback that highlights progress."}]},{"text":[{"text":"Rewarding accomplishments:","bold":true},{"text":" bonuses, gift cards or public recognition."}]},{"text":[{"text":"Offering career development:","bold":true},{"text":" opportunities to learn and advance."}]},{"text":[{"text":"Creating a positive work environment:","bold":true},{"text":" inclusive and welcoming, so employees feel a sense of belonging."}]},{"text":[{"text":"Offering flexible work arrangements:","bold":true},{"text":" remote work or flexible hours, for work-life balance."}]}]},{"type":"paragraph","text":[{"text":"Also: a positive work culture, competitive pay, job security, recognising achievements and aligning personal and company goals build a motivated, high-performing team."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Good strategies "},{"text":"adapt to the individual","bold":true},{"text":" (a young graduate may value training; a parent may value flexible hours) and are "},{"text":"fair","bold":true},{"text":", which links back to equity theory."}]},{"text":[{"text":"Strategies that "},{"text":"lower","bold":true},{"text":" motivation: slashing perks, ignoring staff needs, piling on workloads, favouritism, delayed or no rewards."}]},{"text":[{"text":"Each strategy rests on a theory: goals (goal-setting), feedback and rewards (reinforcement, expectancy), career development (Maslow's esteem and self-actualisation, Herzberg's motivators), positive environment (Hawthorne, Maslow's social needs), fairness (equity)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation = a process of stimulating people to accomplish desired goals; it improves involvement, job satisfaction, cooperation and performance."}]},{"text":[{"text":"Intrinsic (from within) vs extrinsic (rewards); financial (pay, bonus, overtime) vs non-financial (recognition, promotion)."}]},{"text":[{"text":"Taylor: money and piece-rate pay. Hawthorne (Mayo): attention and social factors raise output."}]},{"text":[{"text":"McGregor: Theory X (control) vs Theory Y (self-direction). Ouchi: Theory Z (Japanese-style, consensus, long-term)."}]},{"text":[{"text":"Maslow: physiological, safety, social, esteem, self-actualisation; physiological is the most basic."}]},{"text":[{"text":"Herzberg: motivators (job content) vs hygiene/maintenance factors (job context, including salary)."}]},{"text":[{"text":"Equity = perceived fairness of rewards; expectancy = expectancy × instrumentality × valence; goal-setting = specific, challenging, attainable (SMART)."}]},{"text":[{"text":"Job redesign: enrichment (more authority), enlargement (more tasks), rotation (moving between jobs)."}]},{"text":[{"text":"Reinforcement: positive and negative increase behaviour; punishment and extinction decrease it."}]},{"text":[{"text":"Strategies: goals, feedback, rewards, career development, positive environment, flexible work."}]}]}],"theory":{"itemId":"b377583e-94c9-51ac-9e48-c9fdebfc90dc","question":[{"type":"paragraph","text":[{"text":"Explain Herzberg's two-factor theory and state three ways a manager can redesign jobs to motivate employees."}]}]},"practice":[{"topic":"Employee Motivation","named":false}]}}]$expected_content$::jsonb,
  'introduction-business-1: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('3377fae6-5ab9-5742-95e3-75b94650a294')
  where kind = 'cbt_question'), 0,
  'introduction-business-1: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '3377fae6-5ab9-5742-95e3-75b94650a294' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"43c0d7d9-c8b3-5a72-8185-80297c3bf7a6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fb2fcbeb-8009-5a3e-8d0a-61e36f4e9dc1","sourceKey":"bank:BUA101:B101N1-001","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ikeja studies its target customers, the buying influences on those customers and the competitors who sell similar products to them. Which environment of business is the firm examining?","options":["Social environment","Market environment","Economic environment","Technological environment"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The market environment is made up of target customers, the influences on their buying, and the competitors who market similar products to them. The social environment is the tempting choice, but it covers trends and forces in society at large, not a firm's own customers and rivals."}},{"itemId":"3d3db4a9-87aa-5c36-abb5-388a79fbe4b0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f1daf63e-dad7-5e4f-bc8f-4510f64a40d9","sourceKey":"bank:BUA101:B101N1-002","parentItemId":null,"revision":1,"payload":{"prompt":"In the finance department of a bank in Lagos, which officer sets long-term financial goals and budgets, invests the firm's funds and raises capital?","options":["Management accountant","Treasurer","Controller","Operations manager"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Treasurers and finance officers look forward: they set long-term financial goals and budgets, invest the firm's funds and raise capital. A controller is the closest wrong answer, but controllers oversee financial reports and often run the accounting department rather than raise and invest funds."}},{"itemId":"2394d353-6d24-5c19-901f-2b0c2f4cdc67","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e45009bc-3b6b-59b9-abd1-957bf1b44d59","sourceKey":"bank:BUA101:B101N1-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a potential NEGATIVE effect of business on society?","options":["Disrupting communities","Contributing to national growth and stability","Paying taxes","Providing employment"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"Disrupting communities is one of the four potential negative effects of business, alongside pollution and waste, health and safety risks, and financial instability. Paying taxes, providing employment and contributing to national growth and stability are all positive contributions business makes to society."}},{"itemId":"92392c6a-115d-5048-b3e5-6754ed0a7f89","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"177bb343-8255-53f2-bcb7-8ffc0a8cdae6","sourceKey":"bank:BUA101:B101N1-004","parentItemId":null,"revision":1,"payload":{"prompt":"The \"Unilag economy\", meaning all the business activity that goes on around the UNILAG campus, is an example of an economy at which level?","options":["A household","An institution","An industry","A state or region"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"An economy can be described at the level of a single institution, and all the business activity around the UNILAG campus is the standard example of this. It is not an industry economy, because an industry economy covers one sector such as oil and gas across the country."}},{"itemId":"2d7a2807-c6ff-5605-9cac-cd8712c14e8c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"37ea714f-4d53-52e7-b239-b75b63bce8e8","sourceKey":"bank:BUA101:B101N1-005","parentItemId":null,"revision":1,"payload":{"prompt":"When an analyst talks about Nigeria's oil and gas economy, the economy is being described at which level?","options":["An institution","A nation","An industry","A household"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"The oil and gas economy refers to one sector of activity, so it is an economy at the level of an industry. It is not a national economy, because the national economy would cover all sectors of Nigeria together, not just oil and gas."}},{"itemId":"294381e2-016b-5cef-9261-4fd05995164a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f684288f-7184-5735-8dda-6304829c6fb8","sourceKey":"bank:BUA101:B101N1-006","parentItemId":null,"revision":1,"payload":{"prompt":"An economy run on competition, private ownership and freedom of choice would NOT normally feature which of these?","options":["Competition","Private ownership of resources","Centralised economic planning","Freedom of choice"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"Centralised economic planning belongs to a command economy, where government decides what and how to produce. Competition, private ownership of resources and freedom of choice are all characteristics of a market economy, where demand and supply decide what is produced and consumed."}},{"itemId":"d68a791c-15d0-5915-b0fc-225dedf14a49","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f4b7f304-083f-5942-b301-c47e4541186c","sourceKey":"bank:BUA101:B101N1-007","parentItemId":null,"revision":1,"payload":{"prompt":"Under a command economy, where government owns key businesses and plans production centrally, consumers usually experience","options":["very little government intervention","limited consumer choice","prices set freely by demand and supply","a wide range of competing private brands"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"In a command economy government owns key businesses, plans centrally and decides what to produce, so consumers have limited choice. Prices set freely by demand and supply is the tempting wrong answer, but that price mechanism is the hallmark of a market economy, not a command one."}},{"itemId":"f4c6d7cc-5579-5a92-a859-cb06f8b1f1ee","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cbab6826-f49e-53d5-bfa6-b87f7e576a99","sourceKey":"bank:BUA101:B101N1-008","parentItemId":null,"revision":1,"payload":{"prompt":"A mixed economy, with its emphasis on social welfare and redistribution of resources, is also called a","options":["monopoly state","free-enterprise system","welfarist state","planned system"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"A mixed economy is also described as a welfarist state, because government uses it to provide social welfare and redistribute resources alongside market forces. A planned system is a different thing: it is another name for the command type, where government controls production."}},{"itemId":"ca6ed25a-71a9-56c1-b0c6-6f1bbe11013d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bddfdd3b-666d-547e-8e44-2ec6608b7a86","sourceKey":"bank:BUA101:B101N1-009","parentItemId":null,"revision":1,"payload":{"prompt":"Mixed ownership of property and the co-existence of private, public and joint sectors are features of","options":["a mixed economy","a command economy","an oligopoly","a market economy"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"A mixed economy has mixed ownership of property, with private, public and joint sectors existing side by side and resources allocated by both government and market forces. A command economy is the tempting wrong answer, but there government owns key businesses and plans centrally, with little room for private enterprise."}},{"itemId":"9a8f7646-d63d-5dd7-bbde-fcd7dda78e6a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2efc6b86-f394-5a68-8538-6f0f0bf6ccf1","sourceKey":"bank:BUA101:B101N1-010","parentItemId":null,"revision":1,"payload":{"prompt":"In a free-market economy, resources are said to be allocated most efficiently at the","options":["point of maximum supply","price set by government","point of maximum demand","equilibrium point"],"correctOption":3,"section":"Understanding Basic Economics","explanation":"A market economy allocates resources efficiently at the equilibrium point, where the quantity demanded meets the quantity supplied. The point of maximum supply is wrong because producing the most possible does not mean buyers want that much at that price."}},{"itemId":"bd89a05b-2f54-55b6-97be-37fe89288f56","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"83dcee6b-c6df-518e-98a0-c283b40ea9e2","sourceKey":"bank:BUA101:B101N1-011","parentItemId":null,"revision":1,"payload":{"prompt":"The price at which the quantity demanded equals the quantity supplied is called the","options":["reserve price","ceiling price","equilibrium price","floor price"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"The equilibrium price is where demand meets supply, and it is the optimal price for allocating resources or goods in a free market. A ceiling price is a tempting distractor, but it is a limit placed on price, not the point where the two curves cross."}},{"itemId":"22f92a32-4487-58de-b3c9-6d600ce76521","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"90869c60-3970-5821-8e75-9d2bf62ec993","sourceKey":"bank:BUA101:B101N1-012","parentItemId":null,"revision":1,"payload":{"prompt":"The Federal Government sells a state-owned enterprise to private investors. This process is called","options":["privatisation","liberalisation","nationalisation","centralised planning"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"Privatisation moves state-owned firms into private ownership, and it can be partial or full. Nationalisation is the tempting wrong answer, but it is the reverse process, where government takes over privately owned firms."}},{"itemId":"75dd68e5-9e99-5c8f-82db-32c5a04ed347","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0af5c450-0bc6-5aa7-9cab-65f843354b57","sourceKey":"bank:BUA101:B101N1-013","parentItemId":null,"revision":1,"payload":{"prompt":"A government takes over a privately owned oil company and runs it as a state enterprise. This is an example of","options":["nationalisation","deregulation","privatisation","commercial licensing"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"Nationalisation is the transfer of a privately owned firm into state ownership. Privatisation is the opposite movement, from state ownership to private ownership, so it does not describe a government takeover."}},{"itemId":"b2e0782c-ad8b-56a5-b18b-488eb755fa88","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"37d192e4-6a7f-510e-9f18-51ebe5969a56","sourceKey":"bank:BUA101:B101N1-014","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Balogun market notices that the price of Ankara fabric has fallen sharply. According to the law of demand, what should happen to the quantity of Ankara demanded?","options":["It should stay the same","It should fall and then rise","It should rise","It should fall"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"The law of demand states an inverse relationship: as price falls, quantity demanded rises. Saying it should fall confuses demand with supply, because it is quantity supplied that moves in the same direction as price."}},{"itemId":"f54a3785-d377-58d8-9131-290bb18f1a35","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f23dcc30-601f-5d1c-bd94-0c882bd6b757","sourceKey":"bank:BUA101:B101N1-015","parentItemId":null,"revision":1,"payload":{"prompt":"Besides land, labour, capital and entrepreneurship, which fifth factor of production do some modern business texts add?","options":["Money","Technology","Government","Knowledge"],"correctOption":3,"section":"Understanding Basic Economics","explanation":"The four classic factors of production are land, labour, capital and entrepreneurship, and knowledge is added as a fifth in some modern texts. Technology is the tempting choice, but it is not a traditional factor of production."}},{"itemId":"a09348a8-3630-581e-9fce-479ca85e1135","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a3470d83-90e1-5bd2-b36a-e8cc475fab3d","sourceKey":"bank:BUA101:B101N1-016","parentItemId":null,"revision":1,"payload":{"prompt":"The crude oil deposits in the Niger Delta belong to which factor of production?","options":["Entrepreneurship","Land (natural resources)","Labour","Capital"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"Land covers natural resources, so mineral deposits such as crude oil are part of the land factor. Capital is wrong because it refers to man-made resources used in production, not resources found in nature."}},{"itemId":"cb04dfae-ab2b-5a33-b303-664602ba08e6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"10f5446a-30a0-51de-9494-a9da6c77298c","sourceKey":"bank:BUA101:B101N1-017","parentItemId":null,"revision":1,"payload":{"prompt":"The branch of economics that studies the behaviour of individual consumers and firms is","options":["microeconomics","monetary policy","fiscal policy","macroeconomics"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"Microeconomics looks at individual consumers and firms. Macroeconomics is the tempting wrong answer, but it studies the economy as a whole, including GDP, inflation and unemployment."}},{"itemId":"edfe5fdb-15c8-543f-b357-0f05222149dc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1f73e188-8922-53ad-a447-1631ac383af7","sourceKey":"bank:BUA101:B101N1-018","parentItemId":null,"revision":1,"payload":{"prompt":"When the Central Bank of Nigeria changes interest rates to control the money supply, it is using","options":["income redistribution","trade policy","fiscal policy","monetary policy"],"correctOption":3,"section":"Understanding Basic Economics","explanation":"Monetary policy deals with the money supply and interest rates and is run by the central bank. Fiscal policy is the tempting wrong answer, but it refers to government taxes and spending, not interest rates."}},{"itemId":"846c6410-059f-5c53-b50b-5ba34ede590d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5d961e36-8c2e-5f9a-a326-412124204759","sourceKey":"bank:BUA101:B101N1-019","parentItemId":null,"revision":1,"payload":{"prompt":"The Federal Government raises taxes and cuts its spending to cool down the economy. Which tool is it using?","options":["Price mechanism","Fiscal policy","Monetary policy","Privatisation"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"Fiscal policy is government's use of taxes and spending to influence the economy. Monetary policy is wrong here because it works through the money supply and interest rates set by the central bank, not through taxes and government spending."}},{"itemId":"d3d55ea8-d6fb-5e85-8ae1-116f3af4c197","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1aa99fb7-349e-5f74-904c-fbd1ff871165","sourceKey":"bank:BUA101:B101N1-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a market structure?","options":["Mixed economy","Monopolistic competition","Oligopoly","Pure competition"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"A mixed economy is an economic system, not a market structure. The four market structures are pure (perfect) competition, monopolistic competition, oligopoly and monopoly, so the other three options are all market structures."}},{"itemId":"a62116e0-9e64-5aa8-a3eb-229c1e6bd2ce","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"318a9ab1-459d-585d-877c-3b93317532d9","sourceKey":"bank:BUA101:B101N1-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of government's roles in a free-market system?","options":["Providing public goods and services","Maintaining competition in the marketplace","Fixing the prices of all goods produced","Redistributing income to the under-privileged"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"In a free market, prices are set by demand and supply, so fixing the prices of all goods is not government's role there. Maintaining competition, providing public goods such as water and education, and redistributing income to reduce the income gap are all roles government plays in a free-market system."}},{"itemId":"088b723c-423c-5b6b-b7e2-208d163db717","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3499da64-93c0-5f5f-aee4-ef074a1d443f","sourceKey":"bank:BUA101:B101N1-022","parentItemId":null,"revision":1,"payload":{"prompt":"The government sets up an anti-trust body to monitor abuse of market power by large firms. Which of government's roles in a free-market system is this?","options":["Dealing with international economic blocs","Maintaining competition in the marketplace","Providing public goods and services","Redistributing income"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"An anti-trust body exists to watch for abuse and keep markets competitive, so it serves government's role of maintaining competition. Redistributing income is a different role, aimed at caring for the weak and under-privileged and reducing the income gap."}},{"itemId":"70c49870-b6fe-5434-be53-4e5bd0c08795","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b34521d6-d7f8-50f9-99e1-90ec6a3c098c","sourceKey":"bank:BUA101:B101N1-023","parentItemId":null,"revision":1,"payload":{"prompt":"When government provides the postal system, water, education and health services, which role in a free-market system is it performing?","options":["Maintaining competition in the marketplace","Providing public goods and services","Providing the legal and social framework","Dealing with international communities"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"The postal system, water, education and health are examples of public goods and services that government provides. Providing the legal and social framework is a separate role, concerned with laws, stability and monetary decisions rather than delivering services."}},{"itemId":"d8bc6bb3-04f9-5f73-9bba-60ff82687192","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6095e287-58bf-55f3-bd1f-672b906b0f8c","sourceKey":"bank:BUA101:B101N1-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a NON-economic metric used to monitor a country's development?","options":["Consumer Price Index","Per-capita income","Literacy rate","Foreign direct investment"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"Literacy rate is a non-economic metric, listed with life expectancy, poverty rate and political stability. The Consumer Price Index, foreign direct investment and per-capita income are all economic measures, tracking prices, investment and income."}},{"itemId":"e906aef8-5f6d-5357-bbda-948772ab86f4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3422f105-a038-51dc-ae3e-5ee7c377b1cf","sourceKey":"bank:BUA101:B101N1-025","parentItemId":null,"revision":1,"payload":{"prompt":"Foreign direct investment (FDI) into Nigeria is used as a measure of the","options":["inflation rate","volume of international trade","unemployment rate","level of investment"],"correctOption":3,"section":"Understanding Basic Economics","explanation":"FDI is the example given for the level of investment in an economy. Volume of international trade is a tempting choice, but it is measured by export trade, such as Nigeria's non-oil exports, not by investment flows."}},{"itemId":"be40563b-4ce2-5c0f-ab0a-f927e83138fd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8fb0b75e-5cde-51bf-9b6b-7182f1778470","sourceKey":"bank:BUA101:B101N1-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which measure tracks the prices of a basket of consumer goods over time?","options":["Consumer Price Index (CPI)","Per-capita income","Gross National Product (GNP)","Gross Domestic Product (GDP)"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"The CPI tracks the prices of a basket of consumer goods, which is why it is used alongside the inflation rate. GDP is wrong because it measures the value of final goods and services produced, not the price level of a consumer basket."}},{"itemId":"fab3dba0-9df8-50fc-8f1e-d4843206b3ba","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cf59b9f2-1c50-50c3-806a-26e186a75327","sourceKey":"bank:BUA101:B101N1-027","parentItemId":null,"revision":1,"payload":{"prompt":"The value of output produced by a country's residents and firms, wherever in the world they are located, is called","options":["Gross National Product (GNP)","Per-capita income","Balance of payments","Gross Domestic Product (GDP)"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"GNP counts what a country's residents and firms produce, whether at home or abroad. GDP is the tempting wrong answer, but it counts only what is produced within the country's borders, whoever produces it."}},{"itemId":"f87b0e2d-26c3-590b-9645-deb6225a3da3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"485497a0-c736-5b3d-b804-cd2cd2005c07","sourceKey":"bank:BUA101:B101N1-028","parentItemId":null,"revision":1,"payload":{"prompt":"A sustained fall in the general price level is called","options":["unemployment","inflation","deflation","devaluation"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"Deflation is a sustained fall in the general price level. Inflation is the opposite, a sustained rise in the general price level."}},{"itemId":"48f626f2-0026-5b1c-b206-7e73582659f7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"201d851d-7716-52ee-800a-b9be88043b6f","sourceKey":"bank:BUA101:B101N1-029","parentItemId":null,"revision":1,"payload":{"prompt":"Yam harvesters in a farming community are out of work every year once the harvest season ends. This is an example of","options":["structural unemployment","cyclical unemployment","seasonal unemployment","frictional unemployment"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"Seasonal unemployment occurs when work disappears at certain times of the year, as with harvesters after the harvest. Frictional unemployment is the tempting wrong answer, but it describes the short gap while people move between jobs, not a yearly seasonal pattern."}},{"itemId":"0889d889-ead2-50a1-9aea-ebce92f48b7b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dec39093-57a9-5e5e-9d89-741cd74a8383","sourceKey":"bank:BUA101:B101N1-030","parentItemId":null,"revision":1,"payload":{"prompt":"\"Idera's family income\" is an example of an economy at which level?","options":["An institution","A household or family","A nation","An industry"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"An economy can be described at the level of a household or family, and Idera's family income is the example used for this level. An institution is a different level, such as all business activity around the UNILAG campus."}},{"itemId":"6f88df9f-3cc7-59db-b6ad-e32e5b081728","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"25f331ab-6206-5ff4-8075-5ee90ffd66ee","sourceKey":"bank:BUA101:B101N1-031","parentItemId":null,"revision":1,"payload":{"prompt":"When a country can produce a good more efficiently than any other country, it has","options":["an absolute advantage","a comparative advantage","a balance of trade surplus","a trade embargo"],"correctOption":0,"section":"The Global Marketplace","explanation":"Absolute advantage means producing a good more efficiently than any other country. Comparative advantage is the tempting wrong answer, but it is about specialising where a country's opportunity cost is lowest, not about being the most efficient producer."}},{"itemId":"5446bc59-52ac-5181-8d5d-604db2f2678d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b4db7b0e-fe53-5378-a20e-6dd6b4b1a4fb","sourceKey":"bank:BUA101:B101N1-032","parentItemId":null,"revision":1,"payload":{"prompt":"The principle that a country should specialise in producing goods for which its opportunity cost is lowest is known as","options":["standardisation","absolute advantage","protectionism","comparative advantage"],"correctOption":3,"section":"The Global Marketplace","explanation":"Comparative advantage is specialisation where a country's opportunity cost is lowest, and it is the main driver of international trade. Absolute advantage is wrong because it only asks who produces a good most efficiently, ignoring opportunity cost."}},{"itemId":"18576700-0c79-5d20-899a-6c4326a5bc10","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4ae9ca02-fced-5bec-87f2-1409afc1a77d","sourceKey":"bank:BUA101:B101N1-033","parentItemId":null,"revision":1,"payload":{"prompt":"Nigeria can produce both cocoa and textiles, but it gives up the least by producing cocoa, so it specialises in cocoa and imports textiles. This illustrates","options":["comparative advantage","an embargo","absolute advantage","dumping"],"correctOption":0,"section":"The Global Marketplace","explanation":"Specialising in the good with the lowest opportunity cost is comparative advantage. Absolute advantage is the tempting wrong answer, but the scenario is about what Nigeria gives up, which is opportunity cost, not about being the world's most efficient producer."}},{"itemId":"7848f32e-fb05-5564-b0de-0735784b7188","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6b7a7faa-11df-53e3-8d9a-623a7242360d","sourceKey":"bank:BUA101:B101N1-034","parentItemId":null,"revision":1,"payload":{"prompt":"In one year a country exports goods worth N12 trillion and imports goods worth N15 trillion. What is its balance of trade?","options":["A trade surplus of N27 trillion","A trade deficit of N27 trillion","A trade surplus of N3 trillion","A trade deficit of N3 trillion"],"correctOption":3,"section":"The Global Marketplace","explanation":"Balance of trade is exports minus imports: N12 trillion - N15 trillion = -N3 trillion. A negative figure is a trade deficit. Calling it a surplus of N3 trillion reverses the subtraction, and N27 trillion wrongly adds the two figures."}},{"itemId":"1c7c8747-b9e0-5cad-a806-f615b65c6a43","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5f2e384e-9206-56cb-ba2c-057315cb3306","sourceKey":"bank:BUA101:B101N1-035","parentItemId":null,"revision":1,"payload":{"prompt":"A country exports $45 billion of goods and imports $38 billion in a year. Its balance of trade is","options":["a trade surplus of $83 billion","a trade deficit of $7 billion","a trade deficit of $83 billion","a trade surplus of $7 billion"],"correctOption":3,"section":"The Global Marketplace","explanation":"Balance of trade is exports minus imports: $45 billion - $38 billion = $7 billion. A positive figure is a trade surplus. Calling it a deficit of $7 billion subtracts the wrong way round, and $83 billion comes from adding the two figures."}},{"itemId":"a60a3eb9-d934-5d76-8a22-fcad7f5fc383","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9589acad-b982-5c63-8b30-a0be7631847d","sourceKey":"bank:BUA101:B101N1-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which measure records ALL international money flows into and out of a country, making it broader than the balance of trade?","options":["Gross Domestic Product","Balance of payments","Exchange rate","Balance of trade"],"correctOption":1,"section":"The Global Marketplace","explanation":"The balance of payments covers all international money flows, so it is a broader measure. The balance of trade is the tempting wrong answer, but it only measures exports minus imports."}},{"itemId":"b3472eb7-07e7-5ced-aae5-8edf4461a6b8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"52aa2e03-b503-5d65-991f-1ecb3022f0d4","sourceKey":"bank:BUA101:B101N1-037","parentItemId":null,"revision":1,"payload":{"prompt":"The rate at which the naira converts into the US dollar is called the","options":["balance of trade","exchange rate","inflation rate","tariff rate"],"correctOption":1,"section":"The Global Marketplace","explanation":"The exchange rate is the rate at which one currency converts to another, such as naira to dollars. A tariff rate is wrong because a tariff is a tax on imports, not the price of one currency in another."}},{"itemId":"b340d40a-fdae-5d0f-82b2-19a5160189ee","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"85f40e86-ef43-5fb1-b6b9-f82518287efd","sourceKey":"bank:BUA101:B101N1-038","parentItemId":null,"revision":1,"payload":{"prompt":"A government that limits the number of foreign cars allowed into the country each year is using","options":["an embargo","a quota","a tariff","dumping"],"correctOption":1,"section":"The Global Marketplace","explanation":"A quota is a limit on the quantity of a good that can be imported. A tariff is the tempting wrong answer, but a tariff is a tax on imports rather than a limit on how many can come in."}},{"itemId":"449d9241-766d-55e6-bad9-fae854c40eaa","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"30d83b20-10bd-5e4a-aefb-e3d465f8551a","sourceKey":"bank:BUA101:B101N1-039","parentItemId":null,"revision":1,"payload":{"prompt":"A total ban on trade in a particular product or with a particular country is called","options":["an export subsidy","an embargo","a quota","a tariff"],"correctOption":1,"section":"The Global Marketplace","explanation":"An embargo is a total ban. A quota is the tempting wrong answer, but a quota only limits the quantity imported instead of stopping the trade completely."}},{"itemId":"ee72f032-2ce1-5c5c-875f-c07af72660e1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b9e5b2ba-aadc-5f32-bc00-c05bae85fe32","sourceKey":"bank:BUA101:B101N1-040","parentItemId":null,"revision":1,"payload":{"prompt":"A foreign manufacturer sells its steel in Nigeria at a price below what it charges in its home market. This practice is called","options":["licensing","dumping","a quota","an embargo"],"correctOption":1,"section":"The Global Marketplace","explanation":"Dumping is selling abroad below the home price or below cost. An embargo is wrong because it is a total ban on trade, which is a government measure, not a pricing practice by a seller."}},{"itemId":"2fc195d7-b793-5cce-a2a9-051d0218472d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2ba5574b-bf23-59fd-80ae-b57cb8f4cf57","sourceKey":"bank:BUA101:B101N1-041","parentItemId":null,"revision":1,"payload":{"prompt":"What is the usual government response when foreign firms are found to be dumping goods in its market?","options":["Removing all tariffs","Granting export subsidies","Lowering the exchange rate","Imposing anti-dumping duties"],"correctOption":3,"section":"The Global Marketplace","explanation":"Anti-dumping duties are the response to dumping: they raise the price of the dumped goods to offset the unfairly low price. Granting export subsidies is the tempting wrong answer, but subsidies help a country's own exporters and do not protect against cheap imports."}},{"itemId":"1313e36a-fb84-5cdf-ab85-e6c0c3ee25c3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"65560d82-e61e-5f69-b1d0-7e97fec9d677","sourceKey":"bank:BUA101:B101N1-042","parentItemId":null,"revision":1,"payload":{"prompt":"Free trade is the opposite of","options":["protectionism","globalisation","comparative advantage","standardisation"],"correctOption":0,"section":"The Global Marketplace","explanation":"Free trade means trading without barriers, which is the opposite of protectionism, the use of tariffs, quotas, embargoes and similar measures. Comparative advantage is wrong because it is the reason countries gain from trade, so it supports free trade rather than opposing it."}},{"itemId":"18be09d7-518f-5399-9f98-7a18a91f0aed","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f4f0cf7c-76fd-597a-80a7-0ff48f7a48f2","sourceKey":"bank:BUA101:B101N1-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a protectionist measure?","options":["Imposing a tariff","Setting an import quota","Removing all import duties","Granting export subsidies"],"correctOption":2,"section":"The Global Marketplace","explanation":"Removing all import duties opens a market to foreign goods, which moves towards free trade, not protectionism. Tariffs, quotas and export subsidies are all protectionist measures used to shield local producers."}},{"itemId":"c9e5a792-4f84-5a6c-83e8-4a8701362e9f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e4cf7f9c-d857-518b-91a9-5cd76dc4ad78","sourceKey":"bank:BUA101:B101N1-044","parentItemId":null,"revision":1,"payload":{"prompt":"In what year was the World Trade Organization (WTO) founded?","options":["1995","1985","1947","1962"],"correctOption":0,"section":"The Global Marketplace","explanation":"The WTO was founded in 1995 to promote free trade and settle trade disputes. 1947 is the tempting wrong answer because that is the year of GATT, the agreement the WTO succeeded."}},{"itemId":"ed472c3c-d93c-58d8-9343-5251acf710e5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1b87194e-b4ea-5dd6-bce0-9db84620fd69","sourceKey":"bank:BUA101:B101N1-045","parentItemId":null,"revision":1,"payload":{"prompt":"The World Trade Organization (WTO) succeeded which earlier arrangement?","options":["ECOWAS","The World Bank","The IMF","GATT"],"correctOption":3,"section":"The Global Marketplace","explanation":"The WTO, founded in 1995, succeeded GATT, which dated from 1947. The IMF is wrong because it still exists separately and focuses on currency stability and short-term lending, not on trade rules."}},{"itemId":"40db6a81-b882-513a-9985-8db1d24b0860","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"509dca9d-c27e-5d66-9b01-08bf85528b85","sourceKey":"bank:BUA101:B101N1-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which international organisation is mainly concerned with currency stability and short-term lending to countries?","options":["The World Bank","The World Trade Organization (WTO)","The International Monetary Fund (IMF)","ECOWAS"],"correctOption":2,"section":"The Global Marketplace","explanation":"The IMF works on currency stability and provides short-term lending. The World Bank is the tempting wrong answer, but it focuses on development loans rather than short-term currency support."}},{"itemId":"e99283b7-6794-5424-b249-f38edff72fef","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c357fd89-7fe8-56ca-8c36-7281ac09bbb8","sourceKey":"bank:BUA101:B101N1-047","parentItemId":null,"revision":1,"payload":{"prompt":"A country seeking a loan to build roads and power plants for long-term development would most likely approach the","options":["World Bank","European Union","International Monetary Fund","World Trade Organization"],"correctOption":0,"section":"The Global Marketplace","explanation":"The World Bank provides development loans, which suit long-term projects such as roads and power plants. The IMF is the tempting wrong answer, but its focus is currency stability and short-term lending."}},{"itemId":"b16096c9-428b-5a31-aeee-2ab2fe3c767e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e48c4849-7964-597a-ad21-761114836c44","sourceKey":"bank:BUA101:B101N1-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following trading blocs is Nigeria a member of?","options":["APEC","ECOWAS","USMCA","The European Union (EU)"],"correctOption":1,"section":"The Global Marketplace","explanation":"Nigeria belongs to ECOWAS, the West African trading bloc, and to the continent-wide AfCFTA. The EU, APEC and USMCA are trading blocs in other regions of the world."}},{"itemId":"3a44eed2-f5ea-54e2-9f2b-05f49b98fcd9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d52b29fd-a4a6-5d79-9034-e0a3200acc9f","sourceKey":"bank:BUA101:B101N1-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which form of international business activity involves the LOWEST level of commitment?","options":["Foreign direct investment","International franchising","Importing and exporting","International joint ventures"],"correctOption":2,"section":"The Global Marketplace","explanation":"Importing and exporting sit at the bottom of the scale of commitment, because the firm does not need to set up operations abroad. Foreign direct investment is the opposite end, where the firm owns operations such as subsidiaries in the foreign country."}},{"itemId":"9b297100-443e-5d2c-b705-51546ad71041","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b4fae6a5-b7c4-54b8-b594-0b8b93885a11","sourceKey":"bank:BUA101:B101N1-050","parentItemId":null,"revision":1,"payload":{"prompt":"A firm wanting the greatest control over its foreign operations, and willing to make the biggest commitment, would choose which form of international business activity?","options":["International franchising","International licensing","Importing and exporting","Foreign direct investment, such as a wholly owned subsidiary"],"correctOption":3,"section":"The Global Marketplace","explanation":"Foreign direct investment, for example setting up a wholly owned subsidiary, demands the greatest commitment of money and control. International franchising is a tempting answer, but it sits lower on the scale because the foreign business is run by a local franchisee."}},{"itemId":"f18cb045-56d2-576e-8f4b-dbbad166f33f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"91c03b5d-0ae7-519f-ab4c-43183cc3e75d","sourceKey":"bank:BUA101:B101N1-051","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence arranges forms of international business activity in rising order of commitment?","options":["Exporting, licensing, franchising, joint ventures, foreign direct investment","Exporting, franchising, foreign direct investment, licensing, joint ventures","Foreign direct investment, joint ventures, franchising, licensing, exporting","Licensing, exporting, joint ventures, franchising, foreign direct investment"],"correctOption":0,"section":"The Global Marketplace","explanation":"Commitment rises from importing and exporting, through international licensing and franchising, to strategic alliances and joint ventures, and finally foreign direct investment. The sequence starting with foreign direct investment lists the same forms but in falling, not rising, order."}},{"itemId":"3eaf1028-e61c-585c-90f3-9f91bd5e404c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4df462b3-de7f-5b4b-95e3-b2c4b9f13f82","sourceKey":"bank:BUA101:B101N1-052","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank sets up a wholly owned subsidiary in Ghana. Which form of international business activity is this?","options":["Importing and exporting","International licensing","Foreign direct investment","International franchising"],"correctOption":2,"section":"The Global Marketplace","explanation":"A wholly owned subsidiary abroad is a form of foreign direct investment, the highest level of international commitment. International licensing is wrong because the bank is not just letting another firm use its rights; it owns and runs the foreign operation itself."}},{"itemId":"c01130c7-226e-57bf-a56c-e711a9eb7bb7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"181970e2-9a66-5c48-b76a-856e97c97f51","sourceKey":"bank:BUA101:B101N1-053","parentItemId":null,"revision":1,"payload":{"prompt":"A company that adapts its products and approach separately to suit each country it operates in is following a","options":["transnational strategy","protectionist strategy","multidomestic strategy","global strategy"],"correctOption":2,"section":"The Global Marketplace","explanation":"A multidomestic strategy adapts to each country. A global strategy is the tempting wrong answer, but it takes a standardised, integrated approach across all markets."}},{"itemId":"d498e357-4174-54f9-830e-864135510106","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3f55bc43-b800-5fda-84d9-aac66a88e842","sourceKey":"bank:BUA101:B101N1-054","parentItemId":null,"revision":1,"payload":{"prompt":"A firm that uses one standardised, integrated approach across all its international markets is following a","options":["licensing strategy","multidomestic strategy","global strategy","transnational strategy"],"correctOption":2,"section":"The Global Marketplace","explanation":"A global strategy is a standardised, integrated approach across markets. A transnational strategy is wrong because it blends standardisation with adaptation to each country."}},{"itemId":"667402e1-ea92-53f6-96ef-8c422f283029","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4a0f52be-2f1a-58f9-b8fb-521882cb63a4","sourceKey":"bank:BUA101:B101N1-055","parentItemId":null,"revision":1,"payload":{"prompt":"A strategic approach to international markets that blends standardisation with adaptation to each country is called a","options":["transnational strategy","global strategy","protectionist strategy","multidomestic strategy"],"correctOption":0,"section":"The Global Marketplace","explanation":"A transnational strategy is a blend of the multidomestic and global approaches. A multidomestic strategy is wrong because it only adapts to each country, without the standardised, integrated element."}},{"itemId":"2f806b93-4fbc-5ea1-8d51-057a059577c8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f9a8f34d-ffa9-5700-9cda-2d5eb6558c53","sourceKey":"bank:BUA101:B101N1-056","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos beverage company sells exactly the same drink, with the same recipe and packaging, in every country it enters. This strategy is","options":["dumping","adaptation","licensing","standardisation"],"correctOption":3,"section":"The Global Marketplace","explanation":"Standardisation means offering the same product globally. Adaptation is the opposite choice, where the product is tailored to suit each local market."}},{"itemId":"9021c0a9-47dd-5dd7-85c6-89c529523f42","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9352ad6c-e60c-55e5-9f7f-e45c1e9d766e","sourceKey":"bank:BUA101:B101N1-057","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a government trade restriction rather than a way for a firm to do business abroad?","options":["Embargo","Licensing","Joint ventures","Exporting"],"correctOption":0,"section":"The Global Marketplace","explanation":"An embargo is a total trade ban, a protectionist measure used by governments, not a way for a firm to do business abroad. Exporting, licensing and joint ventures are all forms of international business, along with franchising and subsidiaries."}},{"itemId":"208211ed-e86b-5fce-ad2f-7c55d1945a07","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ca70e546-829e-5aa6-8ab2-71d29d5be483","sourceKey":"bank:BUA101:B101N1-058","parentItemId":null,"revision":1,"payload":{"prompt":"A government sets unusually strict technical rules that imported goods must meet, mainly to keep foreign products out. This protectionist measure is known as","options":["dumping","restrictive import standards","a tariff","an embargo"],"correctOption":1,"section":"The Global Marketplace","explanation":"Restrictive import standards protect local producers by making it hard for foreign goods to qualify for sale. A tariff is wrong because it is a tax on imports, not a set of technical rules."}},{"itemId":"e1b102ec-63a0-5f39-ae0e-80403b840148","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c33050ca-85dd-5129-bae1-d06fce7553e8","sourceKey":"bank:BUA101:B101N1-059","parentItemId":null,"revision":1,"payload":{"prompt":"A government pays local manufacturers so that they can sell their goods more cheaply in foreign markets. This protectionist measure is called","options":["a tariff","export subsidies","a quota","an embargo"],"correctOption":1,"section":"The Global Marketplace","explanation":"Export subsidies are payments that help a country's own producers compete abroad, and they are a protectionist measure. A tariff is the tempting wrong answer, but it is a tax on imports coming in, not support for exports going out."}},{"itemId":"f2913046-1f8a-5914-9c90-6c6115e22abc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"55658e0f-3529-572c-b87b-87b9313db2c9","sourceKey":"bank:BUA101:B101N1-060","parentItemId":null,"revision":1,"payload":{"prompt":"A sales manager at a firm in Ikeja falsifies sales figures to win a bonus. This is an example of","options":["corporate social responsibility","a stakeholder view","an ethical dilemma","an ethical lapse"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical lapse is a clearly wrong choice, and falsifying figures for personal gain is clearly wrong. It is not an ethical dilemma, because a dilemma is a choice between options that are each acceptable but conflict with one another."}},{"itemId":"998162ec-3907-51cb-9c32-b7ab09b8f22e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"36ab94ab-d277-5893-8d87-a80214694b89","sourceKey":"bank:BUA101:B101N1-061","parentItemId":null,"revision":1,"payload":{"prompt":"A choice between two or more acceptable but conflicting options is called","options":["a minimalist view","a conflict of interest","an ethical lapse","an ethical dilemma"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical dilemma involves weighing options that are each acceptable but conflict with one another. An ethical lapse is the tempting wrong answer, but it is a clearly wrong choice, not a hard choice between acceptable options."}},{"itemId":"45a88677-51ae-535a-9210-15adf672dad1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"be09a82f-7b4a-5faf-9ea2-e68f8aa94929","sourceKey":"bank:BUA101:B101N1-062","parentItemId":null,"revision":1,"payload":{"prompt":"The manager of a small firm in Yaba must decide between keeping all staff on full pay and cutting salaries to keep the business alive. Both choices can be justified. This is","options":["a minimalist decision","an ethical lapse","an ethical dilemma","a breach of consumer rights"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"When each option is acceptable but they pull in different directions, the manager faces an ethical dilemma. It is not an ethical lapse, because a lapse is a clearly wrong choice, and neither option here is clearly wrong."}},{"itemId":"f61aaefd-6a58-5123-bc2c-292b26e50948","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7e303105-e284-5e2a-9320-18a7452a2aba","sourceKey":"bank:BUA101:B101N1-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes an ethical lapse from an ethical dilemma?","options":["A lapse is a choice between acceptable options; a dilemma is a clearly wrong choice","A lapse is always illegal; a dilemma is always legal","A lapse is a clearly wrong choice; a dilemma is a choice between acceptable but conflicting options","A lapse affects only employees; a dilemma affects only customers"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"An ethical lapse is a clearly wrong choice, while an ethical dilemma is a choice between options that are each acceptable but conflict. The reversed statement simply swaps the two definitions, so it is wrong."}},{"itemId":"62af1a42-78a5-50ac-8b44-4a238100e4c7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"74438bf8-9d28-541d-a966-a0e003ef1f7f","sourceKey":"bank:BUA101:B101N1-064","parentItemId":null,"revision":1,"payload":{"prompt":"Corporate social responsibility (CSR) is a business's responsibility to society that goes beyond","options":["paying dividends to shareholders","meeting its sales targets","making a profit","obeying its own internal rules"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"CSR is a business's responsibility to society beyond profit, shown in things like sustainability and community support. Paying dividends to shareholders is wrong because that is part of the profit motive itself, not a responsibility that goes beyond it."}},{"itemId":"cd00c252-c028-5f89-b0a6-e354f4bef214","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f3986a5e-aee4-568c-969d-53870c08c71a","sourceKey":"bank:BUA101:B101N1-065","parentItemId":null,"revision":1,"payload":{"prompt":"A factory in Agbara sets up a waste management programme to reduce the waste it dumps. This is CSR toward","options":["shareholders","employees","consumers","the environment"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Waste management and reducing the carbon footprint are CSR toward the environment. CSR toward consumers is a tempting wrong answer, but it covers fair pricing and product safety, not how a factory handles its waste."}},{"itemId":"f765a726-0cc6-51b9-9e98-3dafd6dec7ff","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"97e46af3-75c2-5482-a998-31d018142d7a","sourceKey":"bank:BUA101:B101N1-066","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket in Surulere commits to fair pricing and to selling only safe products. This is CSR toward","options":["the environment","employees","competitors","consumers"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Fair pricing and product safety are CSR toward consumers. CSR toward employees is wrong because it covers fair wages and safe working conditions for staff, not the prices and safety of goods sold to customers."}},{"itemId":"d1d95a8d-d380-5426-8f17-68dcc22057dc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9a53e3d0-9335-54a3-b4e6-1fb156b32474","sourceKey":"bank:BUA101:B101N1-067","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Lagos pays fair wages and provides safe working conditions for its staff. This is CSR toward","options":["the government","the environment","consumers","employees"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Fair wages and safe working conditions are CSR toward employees. CSR toward consumers is the tempting wrong answer, but it concerns fair pricing and product safety for customers."}},{"itemId":"43ecda12-79a3-5648-90d9-c12d13d5f2c0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"843a231b-383a-5bc5-9d86-3c0aca45b4a2","sourceKey":"bank:BUA101:B101N1-068","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of CSR toward employees?","options":["Fair pay","Product safety","Equal opportunity","Workplace safety"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Product safety is CSR toward consumers, because it protects the people who buy and use the product. Equal opportunity, workplace safety and fair pay are all CSR toward employees."}},{"itemId":"2adf1b5b-a310-5032-aa23-701618d1fd07","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e426d7a4-4f6c-563b-a89a-2dbed6e49dda","sourceKey":"bank:BUA101:B101N1-069","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturer lists its CSR projects for the environment. Which one has been wrongly placed on that list?","options":["Reducing carbon footprint","Sustainable development","Paying fair wages","Pollution control"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Paying fair wages is CSR toward employees. Pollution control, sustainable development and reducing the carbon footprint are all CSR toward the environment."}},{"itemId":"046e6431-d7e2-5cef-ba20-fdf825098719","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1d0d4357-c20d-5403-83ee-f9a666f2818b","sourceKey":"bank:BUA101:B101N1-070","parentItemId":null,"revision":1,"payload":{"prompt":"The view that a business's only social responsibility is to make a profit within the law is the","options":["stakeholder view","proactive perspective","minimalist perspective","philanthropic view"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The minimalist perspective holds that a firm meets its responsibility by making a profit within the law. The stakeholder view is the opposite kind of position, because it asks the firm to balance the interests of all its stakeholders."}},{"itemId":"2ccaef0e-0e03-5640-996a-a69d98def227","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bf8dc953-b3cc-501c-b967-807b3437083c","sourceKey":"bank:BUA101:B101N1-071","parentItemId":null,"revision":1,"payload":{"prompt":"Milton Friedman is associated with which perspective on corporate social responsibility?","options":["The minimalist perspective","The cynical perspective","The proactive perspective","The stakeholder view"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Milton Friedman is linked to the minimalist perspective, which sees a firm's social responsibility as making a profit within the law. The stakeholder view is wrong because it asks firms to balance the interests of all stakeholders, which goes well beyond Friedman's position."}},{"itemId":"d82b18cf-25eb-5753-b41f-1812d1708579","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b47f2fc0-a1ab-5762-947f-2e82f0630812","sourceKey":"bank:BUA101:B101N1-072","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos tries to balance the interests of its shareholders, employees, customers and community. Which CSR perspective is it following?","options":["The defensive perspective","The stakeholder view","The minimalist perspective","The cynical perspective"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The stakeholder view asks a business to balance the interests of all its stakeholders. The minimalist perspective is wrong because it limits responsibility to making a profit within the law."}},{"itemId":"f0c55b3c-4f91-51e3-bc25-a583ae13f0b0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f3f20ca3-9f5f-5e41-af03-870050e591eb","sourceKey":"bank:BUA101:B101N1-073","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the perspectives on corporate social responsibility?","options":["Proactive","Autocratic","Defensive","Minimalist"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Autocratic is a leadership style in which a manager decides alone; it is not a CSR perspective. Minimalist, defensive and proactive are all perspectives on CSR, along with the cynical perspective and the stakeholder view."}},{"itemId":"b8acd7b2-771d-5f77-8f86-fce9d8708565","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8fbf31f6-f785-56ba-8d4e-c3a24f1908e9","sourceKey":"bank:BUA101:B101N1-074","parentItemId":null,"revision":1,"payload":{"prompt":"The four-level pyramid of corporate social responsibility made up of economic, legal, ethical and philanthropic responsibilities is associated with","options":["Robert Katz","Milton Friedman","Mintzberg","Carroll"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Carroll's pyramid sets out economic, legal, ethical and philanthropic responsibilities. Milton Friedman is the tempting wrong answer, but he is associated with the minimalist view that a firm's job is profit within the law."}},{"itemId":"0953e3f1-a147-5ce2-8ace-bcdfac3b65e4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c99197af-7d06-5c32-aed9-e42ce8cbc887","sourceKey":"bank:BUA101:B101N1-075","parentItemId":null,"revision":1,"payload":{"prompt":"Carroll's CSR pyramid is made up of four levels. Which of these is not among them?","options":["Philanthropic","Economic","Legal","Political"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Carroll's pyramid has four levels: economic, legal, ethical and philanthropic, so political is not one of them. Economic, legal and philanthropic are all levels of the pyramid."}},{"itemId":"f3b715c0-c5ec-5e68-8ccb-830c100bb590","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6f547056-45bc-5573-9b20-5c6e3eaf6221","sourceKey":"bank:BUA101:B101N1-076","parentItemId":null,"revision":1,"payload":{"prompt":"The four basic consumer rights (safety, to be informed, to choose and to be heard) were set out by","options":["John F. Kennedy","Mintzberg","Carroll","Milton Friedman"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The four consumer rights were set out by US President John F. Kennedy in 1962. Milton Friedman is wrong because he is associated with the minimalist view of CSR, not with consumer rights."}},{"itemId":"3a46e08e-0daf-556f-94f2-873905600605","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4ad10789-ecff-5de4-ab00-318a747294c1","sourceKey":"bank:BUA101:B101N1-077","parentItemId":null,"revision":1,"payload":{"prompt":"In what year were the four basic consumer rights set out by John F. Kennedy?","options":["1962","1975","1995","1947"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"John F. Kennedy set out the four consumer rights in 1962: the rights to safety, to be informed, to choose and to be heard. The other years are not linked to these rights."}},{"itemId":"c5b2a75e-f3bf-5788-8bb0-e609bafbfbfd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dcbe4611-3ebd-55dc-a743-a36e6a4190b8","sourceKey":"bank:BUA101:B101N1-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four consumer rights set out by John F. Kennedy?","options":["The right to safety","The right to be heard","The right to be informed","The right to a discount"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The four rights are the rights to safety, to be informed, to choose and to be heard; there is no right to a discount. The other three options are all among the four rights."}},{"itemId":"cf83ba0c-fb3d-583b-b540-492c4bd4c949","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"abfe36a2-1e07-5987-b439-aae35777a572","sourceKey":"bank:BUA101:B101N1-079","parentItemId":null,"revision":1,"payload":{"prompt":"A food company in Ikeja prints the full ingredients and expiry date clearly on every pack. Which consumer right is it respecting?","options":["The right to be informed","The right to safety","The right to choose","The right to be heard"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Giving buyers clear facts about a product respects their right to be informed. The right to safety is the tempting wrong answer, but it is about the product not harming the user, not about the information printed on it."}},{"itemId":"d9c657d3-a86f-5443-971d-be309265efd1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a94b51a5-540c-5bcd-aad4-e9e77455186f","sourceKey":"bank:BUA101:B101N1-080","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos sets up a hotline and a complaints desk so that customers can register grievances and get a response. Which consumer right does this support?","options":["The right to safety","The right to be heard","The right to be informed","The right to choose"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A channel for complaints lets customers' voices reach the firm, which supports the right to be heard. The right to be informed is a tempting wrong answer, but it is about the firm giving information to buyers, not buyers giving feedback to the firm."}},{"itemId":"229c6a7b-61f6-5173-b0f1-daeaf253e577","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f02051c9-99dd-5cba-8e61-a9e9da991670","sourceKey":"bank:BUA101:B101N1-081","parentItemId":null,"revision":1,"payload":{"prompt":"Government action that keeps several competing brands of a product available, so buyers are not forced to accept one supplier, protects which consumer right?","options":["The right to be informed","The right to choose","The right to safety","The right to be heard"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Having several competing brands available protects the right to choose. The right to be heard is wrong because it concerns consumers' complaints and views reaching the firm, not the range of products on offer."}},{"itemId":"acccf414-4538-5816-b69c-b5443992e846","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8b75a6e5-94bc-5fe0-8799-b5b0c3da4afc","sourceKey":"bank:BUA101:B101N1-082","parentItemId":null,"revision":1,"payload":{"prompt":"A drug manufacturer tests its products thoroughly so that they do not harm the people who use them. Which consumer right is it protecting?","options":["The right to safety","The right to be informed","The right to be heard","The right to choose"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Making sure a product does not harm its users protects the right to safety. The right to be informed is the tempting wrong answer, but it is about giving consumers accurate information, not about the product itself being safe."}},{"itemId":"65caa309-a8ee-5e9e-9664-14f5d1e8c4f4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"354e379c-2b51-59d6-b6ad-5fcfd877f55a","sourceKey":"bank:BUA101:B101N1-083","parentItemId":null,"revision":1,"payload":{"prompt":"Sustainability and support for the local community are typical examples of","options":["an ethical lapse","the minimalist perspective","an ethical dilemma","corporate social responsibility"],"correctOption":3,"section":"Business Ethics and Corporate Social Responsibility","explanation":"CSR is responsibility to society beyond profit, and sustainability and community support are its typical examples. The minimalist perspective is wrong because it limits a firm's responsibility to profit within the law."}},{"itemId":"ea2f59d1-5271-581d-bc5b-336c8cd30960","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"607c1d42-f4bc-5d89-bd74-aac9262822b5","sourceKey":"bank:BUA101:B101N1-084","parentItemId":null,"revision":1,"payload":{"prompt":"A partner who contributes capital and shares in profits but takes no part in managing the business, while still having unlimited liability, is a","options":["active partner","secret partner","sleeping (dormant) partner","nominal partner"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A sleeping or dormant partner puts in capital and shares profit without managing, yet still has unlimited liability. A nominal partner is the tempting wrong answer, but a nominal partner only lends a name and reputation and brings no capital and takes no profit share."}},{"itemId":"996e436b-3ccf-5b7a-b024-d95a58eaf588","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"35ae4bcd-9522-5d52-98f9-570ad7047ff0","sourceKey":"bank:BUA101:B101N1-086","parentItemId":null,"revision":1,"payload":{"prompt":"Which feature of a partnership, under which each partner is both an owner and an agent so that one partner's act binds the others, is described as \"the test of partnership\"?","options":["Unlimited liability","Mutual agency","Shared ownership","Sharing of profit"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Mutual agency means each partner acts as both owner and agent, so one partner's act binds the others, and it is called the test of partnership. Unlimited liability is a feature of general partnerships too, but it is not the one described as the test of partnership."}},{"itemId":"ecaa0636-c39d-568f-86b4-499bf5dcd1c2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"14f8a518-0e71-54be-8015-c6ee875debdd","sourceKey":"bank:BUA101:B101N1-087","parentItemId":null,"revision":1,"payload":{"prompt":"In which corporate governance model are the major affiliated shareholders known as keiretsu?","options":["The Anglo-American model","The Japanese model","The Stewardship model","The Continental model"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"In the Japanese model the key players are banks, affiliated entities called keiretsu, management and government, and keiretsu may remove directors when profits fall. The Continental model is wrong because it is known for its two-tier system of a management board and a supervisory board."}},{"itemId":"5bd5df22-80c9-5d5a-be47-72a382f14e71","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fbd7557b-a50c-5a0b-bc44-9cf096ff4299","sourceKey":"bank:BUA101:B101N1-088","parentItemId":null,"revision":1,"payload":{"prompt":"A governance model has a management board of insiders and a separate supervisory board of outsiders such as shareholders, union representatives and banks. Which model is this?","options":["The Shareholder model","The Continental model","The Japanese model","The Anglo-American model"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"The Continental model is a two-tier system with a management board of insiders and an entirely separate supervisory board of outsiders. The Anglo-American model is wrong because it uses a single board mixing insiders and independents, with the shareholder model as its principal form."}},{"itemId":"74d759dc-220e-522c-8432-b6132bf35058","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bd60c3f7-bafb-518a-bc9e-18ba902f7ee0","sourceKey":"bank:BUA101:B101N1-089","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four C's of a strategic alliance?","options":["Complementarities","Congruence of goals","Compatibility of organisations","Competition"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"The four C's are complementarities, congruence of goals, compatibility of organisations and change, so competition is not one of them. The other three options are all among the four C's."}},{"itemId":"50245e3f-34f5-57e3-a054-858d21ecce82","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dd99ba2a-c200-5a55-af17-739bacec5812","sourceKey":"bank:BUA101:B101N1-090","parentItemId":null,"revision":1,"payload":{"prompt":"Under Nigeria's SMEDAN classification, a small enterprise has how many employees?","options":["10 to 49","50 to 199","Fewer than 500","Fewer than 10"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"SMEDAN classes a small enterprise as one with 10 to 49 employees. Fewer than 10 is the micro category, and 50 to 199 is the medium category."}},{"itemId":"ff6b5290-f71c-55bd-a209-0bd73e223390","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"46247e35-1f66-50b1-8453-a2cfda8bcf40","sourceKey":"bank:BUA101:B101N1-091","parentItemId":null,"revision":1,"payload":{"prompt":"A hairdresser in Yaba runs her salon with 4 employees. Under Nigeria's SMEDAN classification, the business is a","options":["medium enterprise","micro enterprise","small enterprise","large enterprise"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A business with fewer than 10 employees is a micro enterprise under SMEDAN. It is not a small enterprise, because that category starts at 10 employees."}},{"itemId":"a8f5805e-a470-56b3-98f9-57ff16f49dff","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f64b024b-1d7d-55f9-93a3-1e21946fba9e","sourceKey":"bank:BUA101:B101N1-092","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm in Ikeja employs 120 people. Under Nigeria's SMEDAN classification, it is a","options":["small enterprise","large enterprise","micro enterprise","medium enterprise"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"SMEDAN classes a firm with 50 to 199 employees as medium, so 120 employees puts it in the medium category. It is not small, because a small enterprise has only 10 to 49 employees."}},{"itemId":"98493504-e915-532d-9b2b-69745ef7dca2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"72abc307-552f-538f-b808-1c46c673328f","sourceKey":"bank:BUA101:B101N1-093","parentItemId":null,"revision":1,"payload":{"prompt":"With a staff of 35, a printing business in Lagos falls into which SMEDAN size category?","options":["large enterprise","small enterprise","medium enterprise","micro enterprise"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"With 35 employees the business falls in the 10 to 49 range, which SMEDAN classes as small. It is not medium, because the medium category starts at 50 employees."}},{"itemId":"3ef9ce64-45d9-51af-b669-bf7017e2baa9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1a24e5d7-ea0b-566b-81b8-aa2552823604","sourceKey":"bank:BUA101:B101N1-094","parentItemId":null,"revision":1,"payload":{"prompt":"For its size thresholds, the US Small Business Administration generally treats a business as small if it has fewer than","options":["1,000 employees","500 employees","200 employees","50 employees"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The US SBA uses fewer than 500 employees as its usual threshold for a small business. 200 is a tempting distractor because Nigeria's SMEDAN medium category ends just below 200, but that is a different classification."}},{"itemId":"9e7adea8-5988-52f1-a476-b4b200fa0b62","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cc0149cc-fb9f-5820-8c66-4acc71aa75a0","sourceKey":"bank:BUA101:B101N1-095","parentItemId":null,"revision":1,"payload":{"prompt":"A small business is best described as one that is","options":["listed on the stock exchange","dominant in its market but owned by one person","owned by the government and run for profit","independently owned and not dominant in its market"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A small business is independently owned and does not dominate its market. The option saying it is dominant in its market is wrong, because market dominance is exactly what a small business lacks."}},{"itemId":"e0789cb3-b21e-5cf7-9656-eb0cceed6fcc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"463f0549-6d19-52d8-a181-3beffebb9569","sourceKey":"bank:BUA101:B101N1-096","parentItemId":null,"revision":1,"payload":{"prompt":"Raising money for a business by selling part of its ownership to investors is called","options":["a franchise fee","equity financing","bootstrapping","debt financing"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Equity financing means selling ownership in the business. Debt financing is the tempting wrong answer, but it means borrowing through loans, so the owner keeps full ownership while owing repayment."}},{"itemId":"58ef7fe4-b0b3-5bab-8a05-e7df4ee6f061","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f2dd2545-47fa-53c8-bbb0-8bafe2e6aa18","sourceKey":"bank:BUA101:B101N1-097","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Balogun market takes a loan from a microfinance bank to buy more stock. This is an example of","options":["debt financing","angel investment","venture capital","equity financing"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A loan from a bank or microfinance institution is debt financing. Equity financing is wrong because the trader is not selling any ownership of the business to the lender."}},{"itemId":"58c2968b-a3ce-5f7d-aa44-6d329cd0d1f6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8e1e081c-92a2-5ca8-863c-55c9015c9b99","sourceKey":"bank:BUA101:B101N1-098","parentItemId":null,"revision":1,"payload":{"prompt":"Individuals who invest their own money in new businesses are known as","options":["microfinance banks","venture capitalists","angel investors","franchisors"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Angel investors are individuals who invest in new ventures. Venture capitalists are the tempting wrong answer, but they are firms that invest pooled funds in high-growth ventures rather than individuals investing their own money."}},{"itemId":"15d2ce40-702d-5e03-9647-2247c8075bfc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"35c62145-3c51-5f1b-a76d-b9b0a591a154","sourceKey":"bank:BUA101:B101N1-099","parentItemId":null,"revision":1,"payload":{"prompt":"Firms that invest pooled funds in high-growth ventures in exchange for equity are called","options":["commercial banks","angel investors","venture capitalists","franchisees"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Venture capitalists are firms that invest pooled funds in high-growth ventures and take equity in return. Angel investors are wrong because they are individuals investing their own money, not firms managing pooled funds."}},{"itemId":"757d6732-2074-52cb-a377-a127c1ee923b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1dcc459b-e315-5b07-ace7-e7af47f327fa","sourceKey":"bank:BUA101:B101N1-100","parentItemId":null,"revision":1,"payload":{"prompt":"A start-up founder in Lekki sells a 20% ownership stake in her company to an investor in return for funds. Which kind of financing is this?","options":["Debt financing","Equity financing","A microfinance loan","Bootstrapping"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Selling part of the ownership of a business in return for money is equity financing. Debt financing is the tempting wrong answer, but it involves borrowing that must be repaid, not giving up ownership."}},{"itemId":"d3866a76-86eb-5f34-b3dd-dc460d8c881f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0363abea-3075-52cf-877b-cd1774b1b218","sourceKey":"bank:BUA101:B101N1-101","parentItemId":null,"revision":1,"payload":{"prompt":"In a franchise arrangement, the owner of the brand or business system is called the","options":["franchisee","angel investor","franchisor","licensee"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The franchisor owns the brand or business system and sells the right to use it. The franchisee is the tempting wrong answer, because it is the buyer of that right, not the owner of the brand."}},{"itemId":"7329aac0-adc1-5f4d-a10e-009fb9571246","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9e257754-6868-5d5e-97ce-45081994a167","sourceKey":"bank:BUA101:B101N1-102","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG graduate buys the right to run an outlet of a well-known fast-food brand in Surulere. In this arrangement, she is the","options":["venture capitalist","franchisor","sole licensor","franchisee"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The franchisee is the person who buys the right to use another firm's brand and system. The franchisor is wrong because it is the owner of the brand that sells the right, not the buyer."}},{"itemId":"168e6063-20a9-5a1e-8a2f-8119131ec2ce","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a467d5a6-0202-52a4-9ade-1097cf8ea697","sourceKey":"bank:BUA101:B101N1-103","parentItemId":null,"revision":1,"payload":{"prompt":"In return for the right to use a franchise, the franchisee usually pays","options":["only a one-time fee","nothing, as the franchisor bears all costs","a share of the franchisor's dividends","an initial fee plus ongoing royalties"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A franchisee normally pays an initial fee and then ongoing royalties. A one-time fee alone is wrong because the royalties continue for as long as the franchise runs."}},{"itemId":"320ad2f2-7e72-541a-85ae-3a81fc1f1412","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"191cb358-9946-5e9f-9457-1e96ddc3c581","sourceKey":"bank:BUA101:B101N1-104","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a DISADVANTAGE of buying a franchise?","options":["Training and support","A proven business model","Brand recognition","Loss of control"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Franchisees must follow the franchisor's system, so loss of control is a disadvantage, along with cost and shared profits. A proven model, brand recognition, and training and support are all advantages of franchising."}},{"itemId":"fcd53e54-ba32-50e4-99a6-aa019cbe9f8e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fc77fdcf-5499-5281-8444-69236a8a7e86","sourceKey":"bank:BUA101:B101N1-105","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a common reason small businesses fail?","options":["Poor planning","Lack of capital","Strong cash flow","Poor management"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Strong cash flow helps a business survive; it is poor cash flow that causes failure. Poor management, lack of capital and poor planning are all common reasons small businesses fail."}},{"itemId":"4b523821-a221-5f92-9bde-733931536bb6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"031f4f08-1288-5c16-9307-0e6c2153c8a0","sourceKey":"bank:BUA101:B101N1-106","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of the entrepreneurial spirit?","options":["Problem-solving","Risk-taking","Creativity","Risk avoidance"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The entrepreneurial spirit is marked by risk-taking, creativity and problem-solving, so risk avoidance runs against it. The other three options are all part of the entrepreneurial spirit."}},{"itemId":"4dd84e80-b8b7-528e-b5e6-423cef2ad9db","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8d215855-8738-5346-946a-f3f8cc355cab","sourceKey":"bank:BUA101:B101N1-107","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG student's food delivery business has launched and is now focused on scaling operations, managing cash flow and building a customer base. Which phase is the business in?","options":["The business-planning stage","The start-up phase","The growth phase","The idea-generation stage"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Scaling operations, managing cash flow and building a customer base are the tasks of the growth phase. The start-up phase is the tempting wrong answer, but it covers idea generation, the business plan and raising funds, which come before this."}},{"itemId":"7b0d3569-9812-563b-a14e-8addb1d5f190","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"811b47a6-5167-506b-b591-5c1084f18379","sourceKey":"bank:BUA101:B101N1-108","parentItemId":null,"revision":1,"payload":{"prompt":"The purpose of a small-business strategy is to","options":["copy the strategy of larger firms","remove all business risk","avoid paying taxes","achieve the firm's stated objectives"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A small-business strategy exists to achieve the firm's stated objectives. Removing all business risk is wrong because risk-taking is part of running a business and no strategy can remove it entirely."}},{"itemId":"50632c50-2ec5-503f-8ca5-45ad6f9d7ca1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9ff99c9e-be90-5760-953d-37e04d7a0888","sourceKey":"bank:BUA101:B101N1-109","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from creating jobs and driving innovation, small businesses matter to the economy because they","options":["are always more profitable than large firms","remove the need for large firms","are free from all government regulation","provide specialist support to larger firms"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Small businesses give entrepreneurs an outlet, innovate and provide specialist support to larger firms. Saying they remove the need for large firms is wrong, because small firms often work alongside and supply larger ones."}},{"itemId":"072274d5-8394-535d-8fc3-c626caef5fbe","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"19c88619-e97a-54c2-8e86-bbc52226c2ec","sourceKey":"bank:BUA101:B101N1-110","parentItemId":null,"revision":1,"payload":{"prompt":"A business plan can do many things for a new venture. Which of the following can it NOT do?","options":["Guaranteeing that the business will make a profit","Persuading funders to invest","Demonstrating the venture's viability","Defining objectives to direct activities"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"No plan can guarantee profit, especially since start-ups have a high failure rate. A business plan does persuade funders, demonstrate viability and define objectives that direct the firm's activities."}},{"itemId":"a750506e-42e1-5e92-ba8a-685a26d26289","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"50d73dcc-50d9-5b21-b803-6bd803a527a8","sourceKey":"bank:BUA101:B101N1-111","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recognised disadvantage of franchising for the franchisee?","options":["Brand recognition","Training from the franchisor","Sharing profits with the franchisor","A proven business model"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Franchisees share their profits with the franchisor, which is one of the disadvantages of franchising alongside cost and loss of control. Brand recognition, a proven model and training are advantages, not disadvantages."}},{"itemId":"becd4e73-0892-5124-8e96-d113ef634b29","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2c61cc1e-69c0-5ca3-b749-6181e42db6b8","sourceKey":"bank:BUA101:B101N1-112","parentItemId":null,"revision":1,"payload":{"prompt":"Who identified the ten managerial roles grouped into interpersonal, informational and decisional roles?","options":["Robert Katz","Milton Friedman","Carroll","Mintzberg"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"Mintzberg grouped ten managerial roles into interpersonal, informational and decisional groups. Robert Katz is the tempting wrong answer, but he is known for the three-skill model of technical, human and conceptual skills."}},{"itemId":"4b8c5e89-800c-5e9e-a34d-758519d7e9d4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a3a98b94-4af5-58cc-ad6f-27921cf8981f","sourceKey":"bank:BUA101:B101N1-113","parentItemId":null,"revision":1,"payload":{"prompt":"How many managerial roles did Mintzberg identify, and into how many groups?","options":["3 roles in 10 groups","4 roles in 3 groups","10 roles in 4 groups","10 roles in 3 groups"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"Mintzberg identified 10 managerial roles grouped into 3 categories: interpersonal, informational and decisional. Four groups is wrong because there are only three groups of roles; four is the number of management functions."}},{"itemId":"dd4e8dd0-93d6-5b82-bb09-5d3897622165","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"08e3d1e3-7e0d-52ce-ad1a-59ea02ac59ef","sourceKey":"bank:BUA101:B101N1-114","parentItemId":null,"revision":1,"payload":{"prompt":"The managing director of a bank in Lagos cuts the ribbon to open a new branch and represents the bank at ceremonies. Which managerial role is this?","options":["Negotiator","Figurehead","Liaison","Spokesperson"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"The figurehead role is an interpersonal role in which the manager acts as the symbolic head at ceremonies. Spokesperson is the tempting wrong answer, but it is an informational role about passing the firm's information to outsiders, not ceremonial duties."}},{"itemId":"3065ddcc-84bf-5889-b70f-7cac8af913ed","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"79c41939-46ca-5555-907b-07c8c7cd5bb3","sourceKey":"bank:BUA101:B101N1-115","parentItemId":null,"revision":1,"payload":{"prompt":"A manager at a firm in Ikeja builds a network of contacts with managers in other companies and agencies. Which managerial role is this?","options":["Resource allocator","Liaison","Disseminator","Figurehead"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Building relationships with people outside one's own unit is the liaison role, one of the interpersonal roles. Disseminator is wrong because it is an informational role concerned with passing information to people inside the organisation."}},{"itemId":"5642d19a-41ba-5c9c-93af-31de99253531","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e227b8b9-cf47-5f35-89c9-b0ff40d26ac5","sourceKey":"bank:BUA101:B101N1-116","parentItemId":null,"revision":1,"payload":{"prompt":"A manager regularly reads industry reports and tracks competitors to gather information about the business environment. Which managerial role is this?","options":["Entrepreneur","Spokesperson","Monitor","Disseminator"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Seeking and collecting information is the monitor role, one of the informational roles. Disseminator is the tempting wrong answer, but it involves passing information on to others rather than gathering it."}},{"itemId":"ad674ebc-2460-5aee-bb06-2333bb506330","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8c564be8-1a53-5fae-a860-4792fda6735a","sourceKey":"bank:BUA101:B101N1-117","parentItemId":null,"revision":1,"payload":{"prompt":"A department head at UNILAG passes important information from the university management on to the staff in her department. Which managerial role is this?","options":["Spokesperson","Disseminator","Monitor","Liaison"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Passing information to members of one's own unit is the disseminator role, an informational role. Spokesperson is wrong because it involves speaking for the unit to outsiders, not sharing information with people inside it."}},{"itemId":"ba4170ef-0b52-5207-91bb-c65fc2fea584","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0045b09e-a779-5377-8bdc-1b33945d3181","sourceKey":"bank:BUA101:B101N1-118","parentItemId":null,"revision":1,"payload":{"prompt":"A factory manager steps in to settle a sudden quarrel between two production teams that has stopped work. Which of Mintzberg's roles is this?","options":["Disturbance handler","Monitor","Negotiator","Liaison"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Dealing with conflicts and unexpected problems is the disturbance handler role, one of the decisional roles. Negotiator is the tempting wrong answer, but it refers to bargaining on the firm's behalf, such as with unions or suppliers, not settling an internal crisis."}},{"itemId":"5d69e5ff-1cdd-5e6b-8d56-69503270dce0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5ad2741e-7117-5e25-8b3d-e393da4467a5","sourceKey":"bank:BUA101:B101N1-119","parentItemId":null,"revision":1,"payload":{"prompt":"A manager decides how the year's budget will be shared among the marketing, production and HR departments. Which managerial role is this?","options":["Resource allocator","Disseminator","Figurehead","Monitor"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Deciding who gets the organisation's money, people and time is the resource allocator role, one of the decisional roles. Disseminator is wrong because it is about passing information to staff, not dividing up resources."}},{"itemId":"512a1940-bc00-5948-ab02-1f4f1f04d6a7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"89d8948e-3519-56ad-9483-9c8333c1a40c","sourceKey":"bank:BUA101:B101N1-120","parentItemId":null,"revision":1,"payload":{"prompt":"A manager represents the company in bargaining with the workers' union over a new wage agreement. Which managerial role is this?","options":["Spokesperson","Liaison","Negotiator","Disturbance handler"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Bargaining on behalf of the organisation is the negotiator role, a decisional role. Spokesperson is the tempting wrong answer, but it involves giving out information on the firm's behalf rather than bargaining over terms."}},{"itemId":"0539fab6-c7f0-594e-ab77-989503da0dc2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"528ec802-e482-5170-b445-911b18aa3578","sourceKey":"bank:BUA101:B101N1-121","parentItemId":null,"revision":1,"payload":{"prompt":"In Mintzberg's framework, to which group does the entrepreneur role belong?","options":["Interpersonal roles","Informational roles","Decisional roles","Conceptual roles"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"The entrepreneur role is a decisional role, grouped with disturbance handler, resource allocator and negotiator. Conceptual roles is wrong because conceptual is a type of management skill, not one of Mintzberg's groups of roles."}},{"itemId":"8ae1140c-69f9-5bbd-ae9a-1dcdaa597acf","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"61647abf-cff6-5cda-aeea-35340eeafe51","sourceKey":"bank:BUA101:B101N1-122","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of Mintzberg's informational roles?","options":["Negotiator","Monitor","Spokesperson","Disseminator"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Negotiator is a decisional role. The informational roles are monitor, disseminator and spokesperson."}},{"itemId":"8a5d0264-7c6f-56eb-a68c-df308ed5f635","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0b574afe-f663-5a3c-93e7-ecb3ab2a2d47","sourceKey":"bank:BUA101:B101N1-123","parentItemId":null,"revision":1,"payload":{"prompt":"The three-skill model of management made up of technical, human and conceptual skills was proposed by","options":["Carroll","Mintzberg","Robert Katz","Milton Friedman"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Robert Katz proposed the model of technical, human and conceptual skills. Mintzberg is the tempting wrong answer, but he is known for the ten managerial roles, not the three skills."}},{"itemId":"052b88b1-dc2a-5a16-a03a-5cfccbe1e8c2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b8bc7fb2-c10e-59cf-b598-2991d690f8a3","sourceKey":"bank:BUA101:B101N1-124","parentItemId":null,"revision":1,"payload":{"prompt":"A manager's job-specific skill, such as knowing how to operate the machines in a factory, is","options":["human skill","decision-making skill","technical skill","conceptual skill"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Technical skill is job-specific knowledge and ability. Conceptual skill is wrong because it is the ability to see the big picture, not the ability to perform specific tasks."}},{"itemId":"4cee628b-c98d-59bd-8917-98f79391f500","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5894dc80-c6d8-5522-9b9b-f52d79deb98e","sourceKey":"bank:BUA101:B101N1-125","parentItemId":null,"revision":1,"payload":{"prompt":"At which level of the management pyramid does conceptual skill matter most?","options":["Middle managers","First-line managers","It matters equally at all levels","Top managers"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"Conceptual skill, the ability to see the big picture, matters most for top managers. First-line managers are the wrong choice, because technical skill is what matters most at that level."}},{"itemId":"f768c3a6-32e2-594a-b234-c4fda91095fe","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b43db1dc-3db4-553f-b2ce-2d4c81a97d77","sourceKey":"bank:BUA101:B101N1-126","parentItemId":null,"revision":1,"payload":{"prompt":"Technical skill is most important for managers at which level of the pyramid?","options":["First-line (supervisory) managers","Top managers","Middle managers","Board of directors"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"First-line or supervisory managers work closest to the actual tasks, so technical skill matters most for them. Top managers are wrong because conceptual skill is what matters most at the top."}},{"itemId":"72812daf-4802-5b83-8a8e-2a4334ac93d5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9d27ee34-7a46-5f71-8731-1f909cc4e53a","sourceKey":"bank:BUA101:B101N1-127","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a level of the management pyramid?","options":["Shop-floor workers","Middle managers","First-line managers","Top managers"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"The management pyramid has three levels: top, middle and first-line (supervisory) managers. Shop-floor workers are the people managers supervise, not a level of management."}},{"itemId":"d6bf412c-ac25-5675-bcf8-c77d07be577f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1a209adb-8640-53cd-a3f9-36eb8cc9f5e4","sourceKey":"bank:BUA101:B101N1-128","parentItemId":null,"revision":1,"payload":{"prompt":"In the four-skill-group view of management skills, which skill group is listed together with interpersonal, technical and conceptual skills?","options":["Selling skills","Decision-making skills","Negotiating skills","Financial skills"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"The four skill groups are interpersonal, technical, conceptual and decision-making. Negotiating is wrong because it is one of Mintzberg's decisional roles, not a skill group."}},{"itemId":"b2848725-d241-59bb-947c-d214709c08ad","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"366b0165-0b4a-519d-8e50-48499e6f29c6","sourceKey":"bank:BUA101:B101N1-129","parentItemId":null,"revision":1,"payload":{"prompt":"A statement that describes what a firm does and for whom it does it is the","options":["operational plan","tactical plan","mission statement","vision statement"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"A mission statement says what the firm does and for whom. A vision statement is the tempting wrong answer, but it describes what the firm aspires to become in the future."}},{"itemId":"55133075-1fec-5d06-84f9-19cfcbcb7437","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3611be97-8789-5fd4-a7f4-c83d2c84faa8","sourceKey":"bank:BUA101:B101N1-130","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fintech declares, \"We aim to become Africa's most trusted digital bank.\" This is an example of a","options":["vision statement","control standard","mission statement","operational plan"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"A vision statement describes what a firm aspires to become, as this statement does. A mission statement is wrong because it describes what the firm does now and for whom, not what it hopes to become."}},{"itemId":"19faffbe-a9ac-5571-a873-9f50e0c706d6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"929641ed-1f9d-54d9-ad38-194a77fb78dd","sourceKey":"bank:BUA101:B101N1-131","parentItemId":null,"revision":1,"payload":{"prompt":"Long-term plans drawn up by top managers for the whole organisation are","options":["strategic plans","operational plans","tactical plans","contingency plans"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Strategic plans are long-term and made at the top level. Tactical plans are the tempting wrong answer, but they are made by middle managers to carry out the strategy."}},{"itemId":"06466cf0-1604-5350-bbf4-43e36cd8cd69","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c0ac23ff-bfa8-5383-b277-a5ee30dfdc13","sourceKey":"bank:BUA101:B101N1-132","parentItemId":null,"revision":1,"payload":{"prompt":"The short-term plans that set out the day-to-day work of a unit are","options":["strategic plans","tactical plans","vision statements","operational plans"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"Operational plans are short-term plans for day-to-day work. Strategic plans are wrong because they are long-term plans made at the top level of the organisation."}},{"itemId":"e7f66071-bd82-5bd4-80c0-75bb91a72cc0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0a534cc9-67ed-522f-9222-a152c463458b","sourceKey":"bank:BUA101:B101N1-133","parentItemId":null,"revision":1,"payload":{"prompt":"Plans made by middle managers to put the organisation's strategy into action are","options":["tactical plans","operational plans","strategic plans","mission statements"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Tactical plans sit at the middle level, between long-term strategic plans and short-term operational plans. Strategic plans are wrong because they are set by top managers for the long term."}},{"itemId":"1bfd20ca-9650-525c-bfbe-f145abb871d8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d9ea0797-2130-53f1-b4e0-c22c263279b3","sourceKey":"bank:BUA101:B101N1-134","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes goals from objectives?","options":["Goals are short-term; objectives have no time limit","Goals are broad; objectives are specific and measurable","Goals are specific and measurable; objectives are broad","Goals are set by supervisors; objectives are set only by the board"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Goals are broad statements of what the firm wants, while objectives are specific and measurable targets. The reversed option swaps the two, so it is wrong."}},{"itemId":"a26ce259-6be0-54ac-8cb7-b538530dbd38","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"42e1eacb-9e8f-5f2d-8d70-1d27a88e9909","sourceKey":"bank:BUA101:B101N1-135","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who makes decisions alone without consulting employees is using which leadership style?","options":["Autocratic","Laissez-faire","Coaching","Democratic"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"An autocratic leader decides alone. Democratic is wrong because a democratic or participative leader involves employees in decisions."}},{"itemId":"2bf76c79-0fa4-5ed3-be24-ba0d4ef6838e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f5d281a0-cfd0-5135-8a0c-9f6b33b8c706","sourceKey":"bank:BUA101:B101N1-136","parentItemId":null,"revision":1,"payload":{"prompt":"The head of a design team in Yaba gives team members almost complete freedom to set their own work methods and make their own decisions. Which leadership style is this?","options":["Democratic","Coaching","Laissez-faire (free-rein)","Autocratic"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Laissez-faire, or free-rein, leadership leaves decisions largely to the team. Democratic is the tempting wrong answer, but a democratic leader still takes part in decisions and shares them with the team rather than stepping back."}},{"itemId":"1c9d8e57-8046-57e3-9eed-33eefa5849f7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"103d7610-02d1-50d7-a697-23a85faa7dd4","sourceKey":"bank:BUA101:B101N1-137","parentItemId":null,"revision":1,"payload":{"prompt":"A manager who invites employees to take part in decision-making is using which leadership style?","options":["Democratic (participative)","Figurehead","Autocratic","Laissez-faire"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Democratic or participative leadership involves employees in decisions. Laissez-faire is the tempting wrong answer, but it hands decisions over to employees almost entirely instead of making them together."}},{"itemId":"577cef26-be70-5bc0-b49d-c63a048d056b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"38853779-8c23-517e-ba61-4f197f0cf2d2","sourceKey":"bank:BUA101:B101N1-138","parentItemId":null,"revision":1,"payload":{"prompt":"What is the FIRST step in the management control cycle?","options":["Set standards","Compare performance against standards","Measure performance","Take corrective action"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"The control cycle begins by setting standards, because performance cannot be judged without a target. Measuring performance is the second step and only makes sense once standards exist."}},{"itemId":"ece9ca47-fc69-591e-bf0d-f4b172496bed","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"871e8072-43c3-51ac-85bb-3d039203f3c4","sourceKey":"bank:BUA101:B101N1-139","parentItemId":null,"revision":1,"payload":{"prompt":"In the control cycle, which step comes immediately after measuring performance?","options":["Setting standards","Drawing up a mission statement","Taking corrective action","Comparing performance against standards"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"After performance is measured, it is compared against the standards that were set. Taking corrective action is the tempting wrong answer, but it comes last, after the comparison shows a gap."}},{"itemId":"b00920d2-aa23-52db-b48d-ed2b0bf71b34","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0fe2aa3a-418d-5cb1-96c4-57201b47fdab","sourceKey":"bank:BUA101:B101N1-140","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the correct order of the management control cycle?","options":["Take corrective action, set standards, measure performance, compare against standards","Measure performance, set standards, take corrective action, compare against standards","Set standards, compare against standards, measure performance, take corrective action","Set standards, measure performance, compare against standards, take corrective action"],"correctOption":3,"section":"Management Roles, Functions and Skills","explanation":"The cycle runs from setting standards, to measuring performance, to comparing performance against the standards, and finally to taking corrective action. Comparing before measuring is wrong because there is nothing to compare until performance has been measured."}},{"itemId":"dc5d61c7-9de5-5f93-ab7c-b55abbf2cfc9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"90b1ff04-11ae-5636-842e-04b4c4b0270a","sourceKey":"bank:BUA101:B101N1-141","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four functions of management?","options":["Organizing","Controlling","Negotiating","Planning"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"The four functions of management are planning, organizing, leading and controlling. Negotiating is not a function; it is one of Mintzberg's decisional roles."}},{"itemId":"0e844ed2-cfe8-52bd-9c82-5b93887cb524","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f10b0df3-0ca7-5893-870d-653d98fc8409","sourceKey":"bank:BUA101:B101N1-142","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Lagos carries out a SWOT analysis while setting its goals and strategies for the coming year. Which management function is it performing?","options":["Controlling","Planning","Leading","Organizing"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Planning is setting goals and strategies, and SWOT analysis is a typical planning tool. Controlling is wrong because it is about monitoring performance and adjusting after plans are in action."}},{"itemId":"ce0e419e-3f54-50d6-9410-229098799cc8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"926dca5b-2a27-55e0-b79b-40d8e1e74524","sourceKey":"bank:BUA101:B101N2-001","parentItemId":null,"revision":1,"payload":{"prompt":"The number of people who report directly to one manager is known as the","options":["chain of command","line of delegation","organization chart","span of management"],"correctOption":3,"section":"Organization and Teamwork","explanation":"Span of management, also called span of control, counts how many subordinates report directly to a single manager. The chain of command is a different idea: it is the line of authority running from the top of the organization to the bottom, not a count of direct reports."}},{"itemId":"ead48417-7266-5301-8a22-c8cf21163e9d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"533ae589-45e2-5db9-bb0f-75e5d8fd8492","sourceKey":"bank:BUA101:B101N2-002","parentItemId":null,"revision":1,"payload":{"prompt":"When managers in a firm each supervise a large number of subordinates (a wide span of management), the organization tends to have a","options":["functional structure","tall structure","matrix structure","flat structure"],"correctOption":3,"section":"Organization and Teamwork","explanation":"A wide span means each manager handles many people, so fewer management levels are needed and the structure becomes flat. A tall structure is the opposite result, produced by narrow spans where each manager supervises only a few people."}},{"itemId":"1b95a00e-36a3-50b2-a0d9-3dc5beea4ed5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"13c2e87d-9132-5ff8-b735-00ba52684603","sourceKey":"bank:BUA101:B101N2-003","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ikeja has many management levels, and each manager supervises only three or four people. This firm is best described as having","options":["a wide span and a flat structure","a narrow span and a flat structure","a narrow span and a tall structure","a wide span and a tall structure"],"correctOption":2,"section":"Organization and Teamwork","explanation":"Few subordinates per manager is a narrow span, and narrow spans create many layers of management, which is a tall structure. Pairing a narrow span with a flat structure mixes up the relationship, because flat structures come from wide spans."}},{"itemId":"ee80be31-12b7-58f9-ba4d-8eee3faee6ce","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"42d1e532-0ac5-5524-b1d8-6604fc28c366","sourceKey":"bank:BUA101:B101N2-004","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG department has a Head of Department who directly supervises 25 academic staff, with very few levels in between. This arrangement reflects","options":["a wide span of management","a tall hierarchy","a narrow span of management","a long chain of command"],"correctOption":0,"section":"Organization and Teamwork","explanation":"One head supervising 25 people directly is a wide span of management, which keeps the structure flat with few levels. A tall hierarchy or a long chain of command would mean many layers between the top and the staff, which is not the case here."}},{"itemId":"cb7fb6fb-e957-5fea-a58c-d132d0ded424","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3f67bfe0-74c2-50a4-805e-8286006e74ec","sourceKey":"bank:BUA101:B101N2-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which organization structure is built on dual reporting, in which an employee answers to both a functional manager and a project manager?","options":["Functional structure","Matrix structure","Divisional structure","Network structure"],"correctOption":1,"section":"Organization and Teamwork","explanation":"A matrix structure combines the functional line with a project line, so staff have two bosses at once. A functional structure groups people only by their specialist function and keeps a single reporting line to the head of that function."}},{"itemId":"3cf2b5dc-46d0-54ec-800d-72eb9e0eb114","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9a73cf80-04ff-5bee-a1cc-3fcbca7f13f5","sourceKey":"bank:BUA101:B101N2-006","parentItemId":null,"revision":1,"payload":{"prompt":"An engineer at a Lagos construction company reports to the Head of Engineering and, at the same time, to the manager of the Lekki bridge project. The company is using a","options":["matrix structure","divisional structure","flat structure","network structure"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Reporting to a functional head and a project manager at the same time is the dual reporting that defines a matrix structure. A divisional structure would group the company into self-contained units by product, customer or region, each with its own single line of authority."}},{"itemId":"96396210-5b4e-5502-b1bd-18d2657e194d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"636ff8c3-4f0f-5671-9f8e-e0b56be14c7a","sourceKey":"bank:BUA101:B101N2-007","parentItemId":null,"revision":1,"payload":{"prompt":"A company that keeps a small core team and outsources core functions such as manufacturing, logistics and customer support to other firms is using a","options":["functional structure","matrix structure","divisional structure","network structure"],"correctOption":3,"section":"Organization and Teamwork","explanation":"A network structure relies on outside firms to perform core functions, linking them together around a small central organization. A matrix structure is about dual reporting inside one firm, not about handing work to other companies."}},{"itemId":"d46613eb-1341-5c64-b229-10ce65a007d4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7baea3d2-2535-5d63-b55f-2a804f13ffd9","sourceKey":"bank:BUA101:B101N2-008","parentItemId":null,"revision":1,"payload":{"prompt":"The term 'virtual organization' is most closely associated with which organization structure?","options":["Hierarchical structure","Network structure","Matrix structure","Functional structure"],"correctOption":1,"section":"Organization and Teamwork","explanation":"The virtual organization is another way of describing the network structure, where core functions are outsourced and the firm coordinates a web of partners. A matrix structure still keeps the work in-house and simply gives employees two reporting lines."}},{"itemId":"5205f76f-cf57-52d3-8067-88500ee0d276","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b06acfd5-c06a-554a-8e90-813c6b9e66d9","sourceKey":"bank:BUA101:B101N2-009","parentItemId":null,"revision":1,"payload":{"prompt":"A divisional structure may group a firm's activities on any of the following bases EXCEPT","options":["dual reporting lines","product lines","geographic regions","customer groups"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Divisional structures create separate divisions based on product, customer or geography. Dual reporting to a functional manager and a project manager is the defining feature of the matrix structure, not a basis for divisions."}},{"itemId":"81122248-04d4-5980-8c80-a4ea6c84c323","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f3dd879a-023f-5734-894b-545c6c7cdea1","sourceKey":"bank:BUA101:B101N2-010","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos organises itself into a Lagos Division, an Abuja Division and a Port Harcourt Division, each with its own management. This is a","options":["network structure based on outsourcing","divisional structure based on geography","matrix structure based on projects","divisional structure based on product"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Grouping operations by region is a divisional structure organised by geography. It is not divided by product, because each division serves a location rather than offering a separate product line."}},{"itemId":"555a9b23-e217-5c6d-bc44-1820f7480809","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d883ffbc-9587-5933-8cb1-2a70b49c5a3e","sourceKey":"bank:BUA101:B101N2-011","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos sets up separate Retail Banking, Corporate Banking and SME Banking divisions, each serving a different group of clients. This structure is","options":["divisional by customer","functional by department","divisional by geography","network by outsourcing"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Each division here is built around a type of client, so this is a divisional structure organised by customer. A divisional structure by geography would split the bank by region, such as Lagos and Abuja, rather than by client group."}},{"itemId":"905bef8e-eaf8-5014-8b09-48ce66798f4b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"01041d40-a6b4-5551-9114-e79e5aedc687","sourceKey":"bank:BUA101:B101N2-012","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm in Ikeja is organised into a Production department, a Marketing department and a Finance department, each led by a specialist head. This is an example of a","options":["functional structure","matrix structure","network structure","divisional structure"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Grouping people by the specialist work they do, such as production, marketing and finance, is a functional structure. A divisional structure would instead group the firm into units by product, customer or geography."}},{"itemId":"50b3fadf-b0aa-5f23-a943-e25fa9454e1f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"068a3c89-3e2b-5ab7-9070-0c58774c1498","sourceKey":"bank:BUA101:B101N2-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a type of organization structure rather than a type of team?","options":["Cross-functional","Divisional","Self-managed","Problem-solving"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Divisional is a way of structuring the whole organization by product, customer or geography. Self-managed, problem-solving and cross-functional are all types of teams, so they describe how groups of workers are formed, not how the whole firm is structured."}},{"itemId":"dc4bce96-52fc-56c5-a5ce-bef58bfe98be","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cf4a5aee-811d-5195-ac1b-6ece8664e65a","sourceKey":"bank:BUA101:B101N2-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a type of organization structure?","options":["Flat","Matrix","Hierarchical","Self-managed"],"correctOption":3,"section":"Organization and Teamwork","explanation":"Self-managed describes a type of team that runs its own work, not a structure for the whole organization. Hierarchical, flat and matrix are all ways of arranging roles and reporting lines across an organization."}},{"itemId":"30e0c1ba-dc3e-576e-af1b-d65fdeda32b3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"935a8a22-a9af-5f3c-9f5d-376e305b3f0e","sourceKey":"bank:BUA101:B101N2-015","parentItemId":null,"revision":1,"payload":{"prompt":"The main purpose of an organization structure is to","options":["replace the need for managers","define roles and reporting lines","set the prices of products","measure employee motivation"],"correctOption":1,"section":"Organization and Teamwork","explanation":"An organization structure spells out who does what and who reports to whom. It does not set prices or measure motivation; those are marketing and human resource concerns."}},{"itemId":"dbb1e3b6-4e07-5acf-9af9-584d76e6370f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"85ad4c14-1caa-583e-8663-ef359adbdaac","sourceKey":"bank:BUA101:B101N2-016","parentItemId":null,"revision":1,"payload":{"prompt":"A team made up of members drawn from different functional areas, such as marketing, finance and production, working on one goal is a","options":["virtual team","cross-functional team","self-managed team","functional team"],"correctOption":1,"section":"Organization and Teamwork","explanation":"A cross-functional team brings together people from several departments to work on a shared goal. A functional team is the tempting wrong answer, but it is made up of people from the same function or department."}},{"itemId":"84b59912-8c19-5864-bcf4-838bf1ced8d3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"41569c2c-c56e-569f-9cd1-011e7a6b2971","sourceKey":"bank:BUA101:B101N2-017","parentItemId":null,"revision":1,"payload":{"prompt":"Staff of a Lagos fintech firm work together on a project from Lagos, Abuja and Accra, meeting only through video calls and shared online tools. This is best described as a","options":["functional team","virtual team","problem-solving team","matrix team"],"correctOption":1,"section":"Organization and Teamwork","explanation":"A virtual team works together across distance, relying on technology rather than meeting face to face. A problem-solving team is defined by its task of tackling a specific problem, not by its members being in different locations."}},{"itemId":"f5eb8252-4da2-52c2-ba99-ae3a7ff0c776","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c33d6089-c955-50ec-8861-35cc6064e7ad","sourceKey":"bank:BUA101:B101N2-018","parentItemId":null,"revision":1,"payload":{"prompt":"In business, a team is best defined as","options":["a department headed by one manager","any group of workers in one building","a group working toward a common goal","staff who share the same job title"],"correctOption":2,"section":"Organization and Teamwork","explanation":"A team is a group of people working together toward a common goal. Simply sharing a building or a job title does not make people a team if they are not pursuing a shared goal together."}},{"itemId":"37e37931-5a52-5955-9222-2158d3a2d1ce","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8b1e0168-df01-5dcc-b8cf-699d083631d6","sourceKey":"bank:BUA101:B101N2-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the conditions for team productivity?","options":["Strict secrecy among members","Open communication","Clear goals for the team","Trust among members"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Teams are productive when they have clear goals, communicate well and trust one another. Strict secrecy works against communication and trust, so it harms team productivity rather than supporting it."}},{"itemId":"9580e802-dfbd-5030-9a2f-ae5e57ff34f0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1bf1647e-86d3-541c-8197-71aa8f784ecd","sourceKey":"bank:BUA101:B101N2-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of organization is described as flexible and adaptive, with a typical example being a tech start-up?","options":["Tall hierarchical organization","Functional organization","Unstructured organization","Divisional organization"],"correctOption":2,"section":"Organization and Teamwork","explanation":"An unstructured organization is flexible and adaptive, which is why tech start-ups are the usual example. A tall hierarchical organization is the opposite, with many fixed levels and formal reporting lines."}},{"itemId":"e8c236d4-de2e-59ce-bb3b-abe61b5a90f8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f45498c8-751e-5923-920d-17d6afc92abb","sourceKey":"bank:BUA101:B101N2-021","parentItemId":null,"revision":1,"payload":{"prompt":"Tuckman's model of team development begins with which stage?","options":["Norming","Performing","Storming","Forming"],"correctOption":3,"section":"Organization and Teamwork","explanation":"Forming is the first of Tuckman's five stages, when the team first comes together. Storming comes second, after the group has formed."}},{"itemId":"f7109e4c-e183-5ee4-a03d-387844b0cd00","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b4b2bc96-f521-52b5-b24b-1c11a163cc6f","sourceKey":"bank:BUA101:B101N2-022","parentItemId":null,"revision":1,"payload":{"prompt":"In Tuckman's model, the stage that comes immediately after storming is","options":["forming","adjourning","norming","performing"],"correctOption":2,"section":"Organization and Teamwork","explanation":"The sequence is forming, storming, norming, performing and adjourning, so norming follows storming. Performing is a step later, after the team has passed through norming."}},{"itemId":"4cecdb0e-1586-5e05-8552-bb743cac1a4c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d5c23576-032a-5f16-be71-0dd98cecc2b1","sourceKey":"bank:BUA101:B101N2-023","parentItemId":null,"revision":1,"payload":{"prompt":"The final stage in Tuckman's stages of team development is","options":["performing","adjourning","storming","norming"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Adjourning is the fifth and last stage in Tuckman's model. Performing is often mistaken for the end, but it is the fourth stage, coming just before adjourning."}},{"itemId":"d0c6d05d-20a5-5704-a518-2a7b5df8cd06","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1c6eabc0-c506-5462-9c85-4d6c451df838","sourceKey":"bank:BUA101:B101N2-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows Tuckman's stages of team development?","options":["Forming, norming, storming, performing, adjourning","Forming, storming, performing, norming, adjourning","Storming, forming, norming, performing, adjourning","Forming, storming, norming, performing, adjourning"],"correctOption":3,"section":"Organization and Teamwork","explanation":"Tuckman's stages run forming, storming, norming, performing and then adjourning. Placing norming before storming is the most common slip, but the team storms before it settles into agreed norms."}},{"itemId":"5967b0e1-1b71-5fe6-acac-9da69432958c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"564dfe41-356e-5472-a2f0-525ca6293547","sourceKey":"bank:BUA101:B101N2-025","parentItemId":null,"revision":1,"payload":{"prompt":"How many stages are there in Tuckman's model of team development, including adjourning?","options":["Six","Four","Five","Three"],"correctOption":2,"section":"Organization and Teamwork","explanation":"Tuckman's model has five stages: forming, storming, norming, performing and adjourning. Four is the tempting answer because adjourning is sometimes left out, but the full model counts it as the fifth stage."}},{"itemId":"e4290395-35a8-5a22-961a-d9ac9fdb796e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"408dbee6-2144-5c53-b7d3-9eb0424ba460","sourceKey":"bank:BUA101:B101N2-026","parentItemId":null,"revision":1,"payload":{"prompt":"The forming, storming, norming, performing and adjourning stages of team development are associated with","options":["Frederick Herzberg","Abraham Maslow","Bruce Tuckman","Michael Porter"],"correctOption":2,"section":"Organization and Teamwork","explanation":"These five stages of team development form Tuckman's model. Herzberg is linked with the two-factor theory of motivation, not with stages of team development."}},{"itemId":"cad2a2ed-d9c9-593f-b269-7ff8149320cc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c2a39f4c-9325-5b54-ae14-8624365c23ce","sourceKey":"bank:BUA101:B101N2-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of working in teams?","options":["Groupthink","Faster problem solving","Higher performance","Creativity"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Groupthink is a drawback of teams, where the pressure to agree crowds out critical thinking. Creativity, faster problem solving and higher performance are all advantages of teams, not disadvantages."}},{"itemId":"7dea1736-77a9-5941-a7a5-77fc468c0851","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3c8deed1-91f5-5e19-8463-f0d845ea272d","sourceKey":"bank:BUA101:B101N2-028","parentItemId":null,"revision":1,"payload":{"prompt":"In a group assignment at UNILAG, one member contributes almost nothing but still shares the team's grade. This illustrates which disadvantage of teams?","options":["Storming","Delegation","Groupthink","Free-riding"],"correctOption":3,"section":"Organization and Teamwork","explanation":"Free-riding happens when a member benefits from the team's output without contributing a fair share. Groupthink is a different problem, where members go along with the group instead of thinking critically."}},{"itemId":"1a5627a4-4191-5229-b6d5-c6ba3a3b233e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f68ea7ac-af06-5610-9fc1-6a5f418bd477","sourceKey":"bank:BUA101:B101N2-029","parentItemId":null,"revision":1,"payload":{"prompt":"Working in teams has drawbacks as well as benefits. Which of these is a benefit of teams?","options":["Conflict","Groupthink","Creativity","Free-riding"],"correctOption":2,"section":"Organization and Teamwork","explanation":"Creativity is an advantage of teams, because people with different ideas can build on one another. Groupthink, free-riding and conflict are all disadvantages of teams."}},{"itemId":"5c58c134-a53f-54e9-8e58-ed69905fec37","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1f973cfe-9e67-5c4e-894d-e69616fb8fa3","sourceKey":"bank:BUA101:B101N2-030","parentItemId":null,"revision":1,"payload":{"prompt":"Concentrating decision-making authority at the top level of an organization is known as","options":["centralization","delegation","span of management","decentralization"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Centralization keeps decision-making authority with top management. Decentralization is its opposite, spreading decision-making authority down to lower levels of the organization."}},{"itemId":"3fbf8583-1810-5658-8650-60137a2754cd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d6cb6f8c-3a5a-58a6-a4f2-eb1c737fff87","sourceKey":"bank:BUA101:B101N2-031","parentItemId":null,"revision":1,"payload":{"prompt":"A group of interacting elements that act according to rules to form a unified whole is called a","options":["supply chain","business process","value chain","system"],"correctOption":3,"section":"Production Systems","explanation":"A system is a series of related, interdependent parts, or a group of interacting elements acting by rules to form a unified whole. A value chain is narrower: it is a linear sequence of value-adding activities within one company."}},{"itemId":"d48ddccc-b591-5999-856a-f3948a87f4a1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c536e83c-5200-56da-93c8-6e08c23d7979","sourceKey":"bank:BUA101:B101N2-032","parentItemId":null,"revision":1,"payload":{"prompt":"A defined set of principles, practices and procedures applied to specific activities to achieve a specific result is a","options":["value web","production system","business system","supply chain"],"correctOption":2,"section":"Production Systems","explanation":"A business system is a defined set of principles, practices and procedures applied to specific activities to reach a specific result. A production system is more specific: it is the set of activities, processes and resources used to turn inputs into goods or services."}},{"itemId":"856ebd68-2208-500a-a3f9-6a6f6eef0352","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cd932f83-4bd7-55c2-848f-4cafae2084df","sourceKey":"bank:BUA101:B101N2-033","parentItemId":null,"revision":1,"payload":{"prompt":"In operations management, the organised set of activities, processes and resources that turn inputs into finished goods or services is the","options":["business system","organisational boundary","production system","value web"],"correctOption":2,"section":"Production Systems","explanation":"A production system is the organised set of activities, processes and resources that transforms inputs into finished goods or services. A business system is broader, referring to the principles, practices and procedures applied to activities to achieve a result."}},{"itemId":"ac7fbaec-cb24-5206-90ee-fef31e45aaaf","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b4d5422e-9cd5-5522-beca-37b80aa64d55","sourceKey":"bank:BUA101:B101N2-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four basic points of the systems view of business?","options":["Feedback loop","Interdependence","Open system","Centralisation"],"correctOption":3,"section":"Production Systems","explanation":"The four basic points are interdependence, open system, input-process-output and feedback loop. Centralisation is about where decision-making authority sits in an organization, not part of the systems view."}},{"itemId":"2b66b87d-f7c4-5a6e-848d-1e1340c17782","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d1afe0c8-09c8-5092-a2c1-47e575c04483","sourceKey":"bank:BUA101:B101N2-035","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos manufacturer's procurement unit delays buying raw materials, and soon production slows and sales fall. Which point of the systems view does this best illustrate?","options":["Feedback loop","Interdependence","Open system","Input-process-output"],"correctOption":1,"section":"Production Systems","explanation":"Interdependence means each component relies on the others, so a change in one area ripples through the organisation. Open system is tempting, but it is about the firm interacting with outside factors such as the market and economy, not about internal departments affecting one another."}},{"itemId":"9f8e4868-947e-547b-b990-f534c58f5bd2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cddc96fd-a0d8-52eb-b7fa-4d838d0a3f90","sourceKey":"bank:BUA101:B101N2-037","parentItemId":null,"revision":1,"payload":{"prompt":"A company regularly monitors its performance and adjusts its operations based on what it finds. This reflects which point of the systems view?","options":["Open system","Interdependence","Input-process-output","Feedback loop"],"correctOption":3,"section":"Production Systems","explanation":"A feedback loop is the system monitoring its own performance and making adjustments. Input-process-output describes how inputs are transformed into outputs, but it does not by itself involve checking results and correcting course."}},{"itemId":"f9993c34-6a21-55a3-baa2-c6323c780116","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c028d44f-4868-5f10-9e13-625b9726595f","sourceKey":"bank:BUA101:B101N2-038","parentItemId":null,"revision":1,"payload":{"prompt":"In the input-process-output view of a business, resources and information are classified as","options":["inputs","feedback","support activities","outputs"],"correctOption":0,"section":"Production Systems","explanation":"Resources and information are the inputs that the business transforms into outputs. Outputs are the products and services that come out at the end of the process."}},{"itemId":"42de8680-e4f6-5154-a392-726b10333e72","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"48386621-aa67-55e6-96d3-40ff265d1ee9","sourceKey":"bank:BUA101:B101N2-039","parentItemId":null,"revision":1,"payload":{"prompt":"How many primary activities are there in Porter's value chain?","options":["Seven","Four","Two","Five"],"correctOption":3,"section":"Production Systems","explanation":"The primary activities are inbound logistics, operations, outbound logistics, marketing and sales, and service, which makes five. Four is the number of support activities, not primary ones."}},{"itemId":"98547ad6-6366-5524-ad87-4e4ccccfb4c2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e8ad5480-b710-57d0-946b-fd86e25323b6","sourceKey":"bank:BUA101:B101N2-040","parentItemId":null,"revision":1,"payload":{"prompt":"Procurement and technology development are examples of support activities. How many support activities make up Porter's value chain in total?","options":["Four","Two","Five","Three"],"correctOption":0,"section":"Production Systems","explanation":"The support activities are procurement, technology development, human resource management and firm infrastructure, which makes four. Five is the count of primary activities."}},{"itemId":"9fd19f34-43a8-55c6-a0b0-6111efc4caf9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3b9f491f-69f0-56a9-8370-35d6d9d3ac9b","sourceKey":"bank:BUA101:B101N2-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a support activity in Porter's value chain?","options":["Procurement","Inbound logistics","Service","Operations"],"correctOption":0,"section":"Production Systems","explanation":"Procurement is one of the four support activities, along with technology development, human resource management and firm infrastructure. Inbound logistics, operations and service are all primary activities."}},{"itemId":"db2228eb-9e7e-50fd-85ef-3d72f95cf5f0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7f4f552f-c158-51f1-9fe5-e78e613f84cc","sourceKey":"bank:BUA101:B101N2-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these activities belongs to the primary activities, not the support activities, of Porter's value chain?","options":["Firm infrastructure","Service","Technology development","Human resource management"],"correctOption":1,"section":"Production Systems","explanation":"Service is the last of the five primary activities, covering support for customers after the sale. Firm infrastructure, human resource management and technology development are all support activities, even though technology development can feel like core work."}},{"itemId":"5879df16-3ecc-5920-8787-1a050b4631fc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"112e86c8-ff36-5881-9378-487f98fe6103","sourceKey":"bank:BUA101:B101N2-043","parentItemId":null,"revision":1,"payload":{"prompt":"Value chain analysis, which splits a firm's operations into primary and support activities to identify competitive advantage, was proposed by","options":["Victor Vroom","Bruce Tuckman","Michael Porter","Frederick Herzberg"],"correctOption":2,"section":"Production Systems","explanation":"Michael Porter proposed value chain analysis in 1985. Tuckman is linked with the stages of team development, not with analysing a firm's activities."}},{"itemId":"bd2be8a6-e267-5902-9abc-95b5395069a2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f8e2eaff-446d-594e-8a2c-3e98ccc80282","sourceKey":"bank:BUA101:B101N2-045","parentItemId":null,"revision":1,"payload":{"prompt":"After identifying the primary and support activities, the final step in value chain analysis is to","options":["remove all primary activities","analyse the linkages between them","calculate the firm's total profit","outsource the support activities"],"correctOption":1,"section":"Production Systems","explanation":"Value chain analysis ends by analysing the linkages between primary and support activities, since that is where competitive advantage is found. Outsourcing support activities is a business decision that may follow from the analysis, but it is not one of its steps."}},{"itemId":"c4476714-a550-53ed-bd61-b148cfdf4f1a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a22b343e-a020-5007-8fae-418eb1abefb6","sourceKey":"bank:BUA101:B101N2-046","parentItemId":null,"revision":1,"payload":{"prompt":"A linear sequence of activities within one company that adds value at each stage, from raw materials to the final customer, is a","options":["value chain","value web","supply network","business system"],"correctOption":0,"section":"Production Systems","explanation":"A value chain is linear and sits within one company, adding value at each stage. A value web is the tempting alternative, but it is a more complex, less linear network of value chains across several companies."}},{"itemId":"eba78e7d-f112-5259-b10c-b7818d1b9516","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"02043dfe-00a1-5b7b-b5c4-68f035293c8e","sourceKey":"bank:BUA101:B101N2-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the key activities of supply chain management?","options":["Warehousing","Recruitment","Sourcing","Order management"],"correctOption":1,"section":"Production Systems","explanation":"The seven key activities are sourcing, design, production, warehousing, shipping, distribution and order management. Recruitment is a human resource activity, not part of moving goods from supplier to consumer."}},{"itemId":"99e1859a-b5fa-58a8-8714-e2501d82df95","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e4491734-2b35-541e-ae31-45371748e4ee","sourceKey":"bank:BUA101:B101N2-048","parentItemId":null,"revision":1,"payload":{"prompt":"Supply chain management involves how many key activities?","options":["Four","Three","Seven","Five"],"correctOption":2,"section":"Production Systems","explanation":"The seven key activities are sourcing, design, production, warehousing, shipping, distribution and order management. Five is a tempting answer because supply chain management also has five components and five concept steps, but the key activities number seven."}},{"itemId":"f06bfbd7-4770-5529-bece-9c4c49d21601","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"07a770e4-d07e-55ef-b50f-a07490094bcb","sourceKey":"bank:BUA101:B101N2-049","parentItemId":null,"revision":1,"payload":{"prompt":"Among the five components of supply chain management, the component concerned with the movement and storage of goods is","options":["order management","procurement","logistics","production"],"correctOption":2,"section":"Production Systems","explanation":"Logistics covers the movement and storage of goods. Procurement is a different component, concerned with sourcing raw materials."}},{"itemId":"2ca485b0-c379-5985-bbea-61b7131874b9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b61b1d12-36bb-5c4d-8259-faabeded3663","sourceKey":"bank:BUA101:B101N2-050","parentItemId":null,"revision":1,"payload":{"prompt":"The first step in the supply chain management concept is","options":["organising manufacturers","managing return services","sourcing materials","planning the supply chain network"],"correctOption":3,"section":"Production Systems","explanation":"The five steps begin with planning the supply chain network, then sourcing materials, organising manufacturers, delivering the product and managing returns. Sourcing materials is the second step, carried out once the network has been planned."}},{"itemId":"9b32f4d1-f0dc-58fd-9c41-a61a8589586b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5d06b68a-ad54-5dc3-8875-dbfcd30ba052","sourceKey":"bank:BUA101:B101N2-051","parentItemId":null,"revision":1,"payload":{"prompt":"In the supply chain management concept, which step is described as helping to reduce waste?","options":["Managing return services","Planning the supply chain network","Sourcing materials","Organising manufacturers"],"correctOption":0,"section":"Production Systems","explanation":"Managing return services is the last step, and it helps reduce waste. Planning the supply chain network is the first step, concerned with designing the network rather than handling returned goods."}},{"itemId":"a523a4cc-6027-585c-ac5c-6bab2a8b96ca","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"acf4949e-de5a-5ba8-9014-6a7aea1f7fcb","sourceKey":"bank:BUA101:B101N2-052","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Balogun market loses customers because goods ordered from her warehouse often arrive damaged, late or wrong. Which supply chain management step is she handling poorly?","options":["Sourcing materials","Planning the supply chain network","Delivery of the product","Managing return services"],"correctOption":2,"section":"Production Systems","explanation":"Delivery of the product is the logistics step, and damaged, delayed or incorrect orders at this step hurt a firm's reputation. Managing return services deals with goods coming back after delivery, not with getting orders to customers correctly in the first place."}},{"itemId":"f3bd8e80-2c21-5229-bf9f-eefec1b03b54","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4c790cce-233c-54d2-b6c5-aeac75440ff1","sourceKey":"bank:BUA101:B101N2-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following applies to all organisations, including banks and hospitals, rather than only to places where products are manufactured?","options":["Product design","Operations management","Plant layout","Production management"],"correctOption":1,"section":"Production Systems","explanation":"Operations management covers the overall business operations of all organisations, including banks and hospitals. Production management is limited to places where products are manufactured."}},{"itemId":"18c89bd3-cf9f-5468-97bc-3272495fe70e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"97762f5e-4c4b-5b4e-8798-b20d9b3908d8","sourceKey":"bank:BUA101:B101N2-054","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with operations management, production management typically has","options":["a high initial capital requirement","a lower capital requirement","a broader scope of activities","a focus on post-production stages"],"correctOption":0,"section":"Production Systems","explanation":"Production management needs heavy initial capital because it involves manufacturing facilities. A lower capital requirement and a broader scope, including post-production stages, are features of operations management."}},{"itemId":"dbd06616-a666-543b-9e44-80d55a136720","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8b08941f-8eca-51ee-b29e-2a155dd9686d","sourceKey":"bank:BUA101:B101N2-055","parentItemId":null,"revision":1,"payload":{"prompt":"Within the scope of production management, moving material from the storeroom to the machine and from one machine to another is called","options":["material handling","process design","product design","plant layout"],"correctOption":0,"section":"Production Systems","explanation":"Material handling is the movement of material from the storeroom to the machine and between machines. Plant layout is closely related but refers to the physical arrangement of facilities, not the movement of material."}},{"itemId":"0e39526d-275a-5641-9ae7-990f5ac340a3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"86643bb1-062e-5621-a672-df0680e32434","sourceKey":"bank:BUA101:B101N2-056","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation is best defined as","options":["a system for paying workers their salaries","a rule for assigning staff to departments","a process of stimulating people to accomplish desired goals","a method of measuring employee output"],"correctOption":2,"section":"Employee Motivation","explanation":"Motivation is the process of stimulating people to accomplish desired goals. Paying salaries can be one way to motivate, but a pay system is not the same thing as the motivation process itself."}},{"itemId":"ea155c9f-2c15-58e0-a31f-f7c96d291c7b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c9afd64c-578e-5cf4-9a69-36eb8f97f952","sourceKey":"bank:BUA101:B101N2-057","parentItemId":null,"revision":1,"payload":{"prompt":"Employee motivation is important for all of the following reasons EXCEPT that it","options":["removes the need for supervision","promotes job satisfaction","promotes interpersonal cooperation","improves employee involvement"],"correctOption":0,"section":"Employee Motivation","explanation":"Motivation improves employee involvement, promotes job satisfaction and promotes interpersonal cooperation. It does not remove the need for supervision; motivated staff still work within a managed organization."}},{"itemId":"a02b3243-291f-56b7-9e8c-d03fc96d6195","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c1872f87-c2f1-501b-851b-591481c47c95","sourceKey":"bank:BUA101:B101N2-058","parentItemId":null,"revision":1,"payload":{"prompt":"In employee motivation, 'employee choices' refers to","options":["the choice of which manager supervises each worker","the decisions employees make about their jobs and the benefits they receive","the order in which a worker completes daily tasks","the selection of new employees by the HR department"],"correctOption":1,"section":"Employee Motivation","explanation":"Employee choices are the decisions employees make about their jobs and the benefits they receive, including welfare programmes, benefits and development opportunities. Selecting new employees is a recruitment task done by the firm, not a choice made by employees."}},{"itemId":"e85110c9-0d3c-5f17-ad2d-e3459f8d4f5e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d78dbce0-3705-5349-980e-f3ef4ca5ca69","sourceKey":"bank:BUA101:B101N2-059","parentItemId":null,"revision":1,"payload":{"prompt":"Expectancy theory, which links effort to performance and performance to a valued reward, is associated with","options":["Victor Vroom","B. F. Skinner","J. Stacy Adams","Edwin Locke"],"correctOption":0,"section":"Employee Motivation","explanation":"Vroom's expectancy theory says people are motivated when they believe effort leads to performance and performance leads to a reward they value. Adams is linked with equity theory, which is about the perceived fairness of rewards compared with others."}},{"itemId":"3255133d-c0ec-5c38-978e-cb90adb7be3a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"525613f4-ca6e-5f5b-a65b-f6db39ebb4f5","sourceKey":"bank:BUA101:B101N2-060","parentItemId":null,"revision":1,"payload":{"prompt":"Equity theory, which focuses on employees' perceived fairness of their rewards relative to others, is associated with","options":["J. Stacy Adams","Frederick Herzberg","Abraham Maslow","Victor Vroom"],"correctOption":0,"section":"Employee Motivation","explanation":"Adams developed equity theory, which explains motivation through how fairly people think they are rewarded compared with others. Vroom developed expectancy theory, which is about the link between effort, performance and valued rewards."}},{"itemId":"8d7aeeb7-003a-5a9b-8439-314d99e91f8d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d76a6957-9daf-5ae0-9f1f-f5a747fd3704","sourceKey":"bank:BUA101:B101N2-061","parentItemId":null,"revision":1,"payload":{"prompt":"A cashier at a bank in Lagos loses motivation after learning that a colleague doing the same job earns much more. Which theory best explains her reaction?","options":["Equity theory","Reinforcement theory","Expectancy theory","Goal-setting theory"],"correctOption":0,"section":"Employee Motivation","explanation":"Equity theory explains motivation through how fairly people feel they are rewarded compared with others, which is exactly what upsets the cashier. Expectancy theory is about whether effort leads to performance and a valued reward, not about comparing pay with a colleague."}},{"itemId":"628c41b7-f243-52c0-8114-aff9818b0474","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"685c13b1-2ab3-5eef-909a-fe87a45cfa7e","sourceKey":"bank:BUA101:B101N2-062","parentItemId":null,"revision":1,"payload":{"prompt":"Which motivation theory holds that people are motivated when they believe their effort will lead to performance and that performance will lead to a reward they value?","options":["Reinforcement theory","Two-factor theory","Equity theory","Expectancy theory"],"correctOption":3,"section":"Employee Motivation","explanation":"Expectancy theory rests on the chain from effort to performance to a valued reward. Equity theory is the tempting alternative, but it is concerned with whether rewards seem fair compared with what others receive."}},{"itemId":"a24712e8-39a9-54f3-aa8e-0bf0d6df0072","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f260c75c-d2dd-5c70-ae92-de0111c30077","sourceKey":"bank:BUA101:B101N2-063","parentItemId":null,"revision":1,"payload":{"prompt":"In SMART goals, the letter 'T' stands for","options":["Targeted","Time-bound","Tested","Tangible"],"correctOption":1,"section":"Employee Motivation","explanation":"SMART goals are Specific, Measurable, Achievable, Relevant and Time-bound, so 'T' means the goal has a deadline. Targeted or tangible may sound sensible, but they are not part of the SMART formula."}},{"itemId":"0e8c3749-8050-5550-aee0-5877a0eaf9e2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a9a11133-52b7-5c4b-b0b0-9040bbc27d49","sourceKey":"bank:BUA101:B101N2-064","parentItemId":null,"revision":1,"payload":{"prompt":"Specific, ____, Achievable, Relevant, Time-bound. Which word completes the SMART goal acronym?","options":["Manageable","Monitored","Motivating","Measurable"],"correctOption":3,"section":"Employee Motivation","explanation":"The 'M' in SMART stands for Measurable, meaning progress toward the goal can be tracked. Motivating is a hoped-for effect of good goals, but it is not what the letter stands for."}},{"itemId":"ff3bb193-c27e-55a6-b3ef-5a9279351ff1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b909c6d0-18e0-5cbb-a78d-d535d0d1aaba","sourceKey":"bank:BUA101:B101N2-065","parentItemId":null,"revision":1,"payload":{"prompt":"Motivating employees with challenging goals is linked to goal-setting theory, which is associated with","options":["Elton Mayo","Edwin Locke","Douglas McGregor","David McClelland"],"correctOption":1,"section":"Employee Motivation","explanation":"Goal-setting theory, the basis for motivating with challenging goals, is associated with Edwin Locke. Elton Mayo is linked with the Hawthorne studies, not with goal-setting."}},{"itemId":"334e5c11-e08e-5dff-a98b-03f9f62f2cd8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"66fbda0d-61da-5936-8ce4-48e8f3342cfb","sourceKey":"bank:BUA101:B101N2-066","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three common types of job redesign?","options":["Job rotation","Job enlargement","Job enrichment","Job evaluation"],"correctOption":3,"section":"Employee Motivation","explanation":"The three common types of job redesign are job enrichment, job enlargement and job rotation. Job evaluation is used to compare jobs for pay purposes, not to reshape the work itself."}},{"itemId":"2ca54500-b743-548b-ace8-8daa49962fd3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d70633b4-8604-5de2-9de8-2ea432d219d1","sourceKey":"bank:BUA101:B101N2-067","parentItemId":null,"revision":1,"payload":{"prompt":"Adding more tasks to a job at the same level of responsibility, a horizontal expansion of the job, is called","options":["job enlargement","job rotation","job specialisation","job enrichment"],"correctOption":0,"section":"Employee Motivation","explanation":"Job enlargement expands a job horizontally by adding more tasks at the same level. Job enrichment is the tempting alternative, but it expands the job vertically by adding responsibility and autonomy."}},{"itemId":"42811669-f830-5d79-8006-b7e3f4763faf","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"eb4216d7-4a23-58c9-94ee-7ab5b6b811f9","sourceKey":"bank:BUA101:B101N2-068","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ikeja allows an accounts clerk to plan her own work schedule and approve small customer refunds without asking her supervisor. This is an example of","options":["extinction","job rotation","job enrichment","job enlargement"],"correctOption":2,"section":"Employee Motivation","explanation":"Giving a worker more responsibility and autonomy over decisions is job enrichment, a vertical expansion of the job. Job enlargement would only add more tasks at the same level, without the extra authority she has been given."}},{"itemId":"68303611-659a-5ad3-83cf-f3fb091612c0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cbeff9d8-7f11-54f6-98c6-985ecf04f3b9","sourceKey":"bank:BUA101:B101N2-069","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos moves its graduate trainees through customer service, operations and credit units, spending a few months in each. This practice is called","options":["job evaluation","job enlargement","job rotation","job enrichment"],"correctOption":2,"section":"Employee Motivation","explanation":"Moving employees between different jobs over time is job rotation. Job enlargement is different because the employee stays in one job that is given more tasks."}},{"itemId":"3439029a-fec9-5918-962b-eec39578cc91","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"91105e28-63a6-5bfa-bd23-10cebab0c19e","sourceKey":"bank:BUA101:B101N2-070","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the core characteristics in Hackman and Oldham's job characteristics model?","options":["Job security","Task identity","Skill variety","Autonomy"],"correctOption":0,"section":"Employee Motivation","explanation":"The five core characteristics are skill variety, task identity, task significance, autonomy and feedback. Job security is a condition of employment, not a characteristic of the work itself in this model."}},{"itemId":"1747751c-c5bc-5469-9435-b3b6a662824e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"670bbcc2-d176-55ee-8b75-ab1ce1acc695","sourceKey":"bank:BUA101:B101N2-071","parentItemId":null,"revision":1,"payload":{"prompt":"The job characteristics model, made up of skill variety, task identity, task significance, autonomy and feedback, was developed by","options":["Vroom and Adams","Maslow and Herzberg","Taylor and Mayo","Hackman and Oldham"],"correctOption":3,"section":"Employee Motivation","explanation":"Hackman and Oldham developed the job characteristics model with these five core characteristics. Vroom and Adams are linked with expectancy and equity theories, which explain motivation through beliefs and fairness rather than job features."}},{"itemId":"cf6c5b3f-d66d-54ed-a233-ff8ff83220c4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"eed1dd2a-baeb-56a4-8a0f-28a31ba257e0","sourceKey":"bank:BUA101:B101N2-072","parentItemId":null,"revision":1,"payload":{"prompt":"Reinforcement theory, which uses rewards to strengthen desired behaviour, is associated with","options":["Edwin Locke","Douglas McGregor","B. F. Skinner","Victor Vroom"],"correctOption":2,"section":"Employee Motivation","explanation":"Reinforcement theory is B. F. Skinner's, and it explains how the consequences of behaviour shape whether it is repeated. Vroom is linked with expectancy theory, which focuses on people's beliefs about effort, performance and rewards."}},{"itemId":"8ae321f3-4f8f-5004-8d26-4e3b1270d2b8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a4893b80-7f5a-5f1e-bbbc-570c2ea9e68a","sourceKey":"bank:BUA101:B101N2-073","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ikeja gives employees extra days off whenever they perform well. This is an example of","options":["extinction","positive reinforcement","punishment","negative reinforcement"],"correctOption":1,"section":"Employee Motivation","explanation":"Adding a reward such as extra days off after good performance is positive reinforcement. Negative reinforcement also encourages good behaviour, but it does so by removing an unpleasant condition rather than adding a reward."}},{"itemId":"d615dc82-352e-57d8-af8e-97ba4aaf076f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"38f00d2e-fff3-52e7-bebf-bcd2463f1aa9","sourceKey":"bank:BUA101:B101N2-074","parentItemId":null,"revision":1,"payload":{"prompt":"In reinforcement theory, removing an unpleasant condition when the desired behaviour occurs is called","options":["positive reinforcement","punishment","extinction","negative reinforcement"],"correctOption":3,"section":"Employee Motivation","explanation":"Negative reinforcement strengthens a desired behaviour by taking away something unpleasant when the behaviour occurs. It is often confused with punishment, but punishment aims to discourage behaviour, while negative reinforcement encourages it."}},{"itemId":"41c79ea0-346f-50b1-9d79-8208fac0e4e5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f0fc308e-fe37-596d-b469-84fbae4d6676","sourceKey":"bank:BUA101:B101N2-075","parentItemId":null,"revision":1,"payload":{"prompt":"In reinforcement theory, withdrawing reinforcement so that a behaviour fades away is called","options":["punishment","positive reinforcement","extinction","negative reinforcement"],"correctOption":2,"section":"Employee Motivation","explanation":"Extinction means withdrawing reinforcement, so a behaviour that is no longer rewarded tends to fade. Punishment is different because it applies an unpleasant consequence instead of simply removing the reward."}},{"itemId":"a7179741-bd35-5e3f-95d8-17d1136b023b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f4ead8f0-34fc-5f46-b521-9938c54df043","sourceKey":"bank:BUA101:B101N2-076","parentItemId":null,"revision":1,"payload":{"prompt":"Actions and attitudes that consistently produce exceptional results and go beyond job requirements are known as","options":["employee choices","job enlargement","high-performance behaviours","hygiene factors"],"correctOption":2,"section":"Employee Motivation","explanation":"High-performance behaviours are actions and attitudes, such as excellence, initiative and commitment, that consistently give exceptional results beyond what the job requires. Hygiene factors are Herzberg's maintenance factors, such as pay and working conditions, that prevent dissatisfaction."}},{"itemId":"2265f4f5-e7b1-50c5-8ada-c92028a61175","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1c213dda-cd04-5e4d-9030-05f8ad74fbfb","sourceKey":"bank:BUA101:B101N2-077","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the six motivational strategies?","options":["Providing frequent, meaningful feedback","Increasing close supervision of staff","Offering flexible work arrangements","Offering career development"],"correctOption":1,"section":"Employee Motivation","explanation":"The six strategies are setting goals, giving frequent feedback, rewarding accomplishments, offering career development, creating a positive and inclusive environment, and offering flexible work arrangements. Increasing close supervision is not among them and tends to reduce the autonomy that motivates staff."}},{"itemId":"fac2b684-8045-57a1-a54f-9f7f79862229","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"26a25e72-e50f-5946-96cd-4498e9ceb8db","sourceKey":"bank:BUA101:B101N2-078","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Lagos introduces remote work and flexible hours to motivate its staff. Which motivational strategy is it using?","options":["Offering career development","Setting goals","Offering flexible work arrangements","Rewarding accomplishments"],"correctOption":2,"section":"Employee Motivation","explanation":"Remote work and flexible hours are the examples given for offering flexible work arrangements. Rewarding accomplishments is a separate strategy that uses bonuses, gift cards and public recognition."}},{"itemId":"3b29c4fa-71f3-51b0-bb91-2d4857023b9f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"29bf6ed1-0864-5689-9c88-2ac4645b34c6","sourceKey":"bank:BUA101:B101N2-079","parentItemId":null,"revision":1,"payload":{"prompt":"Giving bonuses, gift cards and public recognition to staff who meet their targets is the motivational strategy of","options":["rewarding accomplishments","creating a positive environment","providing frequent feedback","offering career development"],"correctOption":0,"section":"Employee Motivation","explanation":"Bonuses, gift cards and public recognition are the tools of rewarding accomplishments. Providing feedback is a separate strategy about telling staff how they are doing, not about giving them rewards."}},{"itemId":"56a80a0d-8714-59bd-88cc-d0b0717574d2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"29143cd2-2a13-5ea4-a72a-003627c4f14e","sourceKey":"bank:BUA101:B101N2-080","parentItemId":null,"revision":1,"payload":{"prompt":"In Maslow's hierarchy of needs, the highest level is","options":["safety","esteem","social (belonging)","self-actualisation"],"correctOption":3,"section":"Employee Motivation","explanation":"Self-actualisation is the fifth and highest level of Maslow's hierarchy. Esteem is the level just below it, so it is a common wrong choice for the top."}},{"itemId":"ddd202cf-bd0f-5e2c-839d-6c1c6f94dd6f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8d1dba2b-e576-5158-a627-4450cb29d2a7","sourceKey":"bank:BUA101:B101N2-081","parentItemId":null,"revision":1,"payload":{"prompt":"Which option lists Maslow's hierarchy of needs correctly, from the lowest level to the highest?","options":["Physiological, safety, social, esteem, self-actualisation","Safety, physiological, social, esteem, self-actualisation","Physiological, safety, esteem, social, self-actualisation","Physiological, social, safety, esteem, self-actualisation"],"correctOption":0,"section":"Employee Motivation","explanation":"Maslow's order from the bottom is physiological, safety, social (belonging), esteem and self-actualisation. Swapping social and esteem is a common slip, but the need to belong comes before the need for esteem."}},{"itemId":"701e07c4-26fe-5d71-9d6b-1eeb4e8524dd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ab191b8f-8f2d-5d01-8744-ad770f9e667f","sourceKey":"bank:BUA101:B101N2-082","parentItemId":null,"revision":1,"payload":{"prompt":"Under Herzberg's two-factor theory, which of the following is a hygiene (maintenance) factor?","options":["Achievement","Advancement","Recognition","Working conditions"],"correctOption":3,"section":"Employee Motivation","explanation":"Working conditions are a hygiene factor, along with pay, supervision and company policy, and they prevent dissatisfaction. Achievement, recognition and advancement are motivators that create satisfaction."}},{"itemId":"80858d9f-db82-5ff4-bdfe-e516ee15b80e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"341d18b7-4e69-5775-b39a-8758be162c54","sourceKey":"bank:BUA101:B101N2-083","parentItemId":null,"revision":1,"payload":{"prompt":"According to Herzberg's two-factor theory, hygiene factors such as pay and supervision mainly","options":["measure performance","prevent dissatisfaction","replace motivators","create job satisfaction"],"correctOption":1,"section":"Employee Motivation","explanation":"Hygiene factors prevent dissatisfaction, but improving them does not by itself create satisfaction. Creating satisfaction is the role of motivators such as achievement, recognition and responsibility."}},{"itemId":"886e5a09-83f2-58f8-9f9f-1823300c6857","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e8c199fc-506b-51f1-b899-643bf202f44d","sourceKey":"bank:BUA101:B101N2-084","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three needs in McClelland's theory?","options":["Achievement","Safety","Power","Affiliation"],"correctOption":1,"section":"Employee Motivation","explanation":"McClelland's three needs are achievement, affiliation and power. Safety belongs to Maslow's hierarchy of needs, not to McClelland's theory."}},{"itemId":"4e1c5755-c2c5-5cb6-9c49-08aa47e35b13","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3a5c22cb-db45-5272-8216-2b7ac9e74dc9","sourceKey":"bank:BUA101:BUA-0001","parentItemId":null,"revision":1,"payload":{"prompt":"Shareholders as a business stakeholder receive","options":["Dividends","Wages and salaries","Provision of infrastructure","Community services"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"Shareholders are the owners of a company, and their reward for investing is a share of the profit paid out as dividends. Option B, wages and salaries, goes to employees, while C and D describe what government and the community expect from a business."}},{"itemId":"4eaf8362-dd13-5800-b432-7f3d3dff9c99","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9bf7b6e9-e5ce-5057-861d-b4c542098f8f","sourceKey":"bank:BUA101:BUA-0003","parentItemId":null,"revision":1,"payload":{"prompt":"All BUT the following are major reasons for separating business operations into functional areas","options":["efficiency","expertise","increased costs","effectiveness"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Firms split work into functional areas such as marketing, finance and production so that people can specialise, which brings expertise, efficiency and effectiveness. Increased costs are not a goal of this arrangement, so C is the exception. Options A, B and D are all genuine benefits of dividing work by function."}},{"itemId":"7ab70d5b-e7ca-5c09-a7ea-1d75e96c35c3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d6f90fe7-b9f1-5f37-83c0-4bb7172d1c0b","sourceKey":"bank:BUA101:BUA-0005","parentItemId":null,"revision":1,"payload":{"prompt":"What was established by the Companies and Allied Matters Act and is in charge of implementing its provisions?","options":["CAC","NEPC","SEC","NSE"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"The Corporate Affairs Commission (CAC) was set up under the Companies and Allied Matters Act to register companies and enforce the Act's provisions. NEPC promotes exports, SEC regulates the capital market, and NSE is the stock exchange, so none of them administers company registration."}},{"itemId":"fe9f7867-1f5c-5404-9f01-00dbd37b4b1f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"75f0e025-b59c-5375-9a24-c0c2272aac2e","sourceKey":"bank:BUA101:BUA-0006","parentItemId":null,"revision":1,"payload":{"prompt":"Distribution of Inventory is a primary activity related to___________","options":["Outbound logistics","Operations","Services","Inbound logistics"],"correctOption":0,"section":"Production Systems","explanation":"Outbound logistics covers getting finished products from the firm to its customers, including storing and distributing inventory. Inbound logistics (D) deals with receiving raw materials coming in, while operations (B) is the stage where inputs are turned into the product."}},{"itemId":"d97f22c8-9c04-5cd0-bb3f-603b21472cc7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8cd4866b-ddcc-5200-8470-5ebbdb8562c1","sourceKey":"bank:BUA101:BUA-0008","parentItemId":null,"revision":1,"payload":{"prompt":"Privatization exercise may be _________ or __________","options":["Partial or Full","Sector or Activity based","Local or Foreign","Major or Minor"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"Privatisation can be partial, where government sells only part of its shares in an enterprise, or full, where it sells off all of its interest. Option B, sector or activity based, and option C, local or foreign, describe other ways of grouping businesses, and D, major or minor, is not a recognised type of privatisation."}},{"itemId":"690e9b56-64dc-51cd-91f0-c7d9ea9e1c71","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f027ade5-e92f-57af-92c2-d4d55a31c909","sourceKey":"bank:BUA101:BUA-0009","parentItemId":null,"revision":1,"payload":{"prompt":"________ are form of organizations which venture into business activities with the sole purpose of providing service to the members in the most efficient and affordable manner","options":["Limited liability company","Partnership","Sole proprietorship","Cooperative societies"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Cooperative societies are owned by their members and run mainly to serve those members efficiently and affordably, rather than to make profit for outside investors. A sole proprietorship (C) is owned by one person for his or her own profit, and partnerships and limited liability companies also aim at returns for their owners."}},{"itemId":"bac9f7ed-0497-527e-925d-1b2d13b169b8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ee032b14-ae65-5af2-88c9-356510bcbbd9","sourceKey":"bank:BUA101:BUA-0010","parentItemId":null,"revision":1,"payload":{"prompt":"Primary Activities within the basic value chain consists of all except","options":["Inbound logistics","Outbound logistics","Operations","Technological development"],"correctOption":3,"section":"Production Systems","explanation":"Porter's primary activities are inbound logistics, operations, outbound logistics, marketing and sales, and service. Technology development is a support activity, alongside procurement, human resource management and firm infrastructure, so D is the exception. Options A, B and C are all primary activities."}},{"itemId":"40269240-633d-5f01-8c2d-6b3992e13165","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a22e37fc-289e-5f90-928e-d0b1f11f30a1","sourceKey":"bank:BUA101:BUA-0013","parentItemId":null,"revision":1,"payload":{"prompt":"There are ____ basic set of activities within the value chain as propounded by Porter","options":["2","4","5","3"],"correctOption":0,"section":"Production Systems","explanation":"Porter grouped value chain activities into two basic sets: primary activities, which directly create and deliver the product, and support activities, which help the primary ones work. The numbers 5 and 4 in options C and B match the count of primary and support activities respectively, not the number of basic sets, and 3 in option D is the number of steps in value chain analysis, not the number of activity sets."}},{"itemId":"c4c08a6e-a284-5ccf-bcaa-3297d766395d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a248ef84-1f9c-5ddd-b50c-7af6dec236ec","sourceKey":"bank:BUA101:BUA-0016","parentItemId":null,"revision":1,"payload":{"prompt":"Within an organisation's value chain, marketing and sales belong to the ________","options":["primary activities","support activities","firm infrastructure activities","procurement activities"],"correctOption":0,"section":"Production Systems","explanation":"Marketing and sales is one of Porter's primary activities, because it directly persuades customers to buy the product. Option B is wrong because the support activities are procurement, technology development, human resource management and firm infrastructure, and options C and D name two of those support activities, not the group marketing belongs to."}},{"itemId":"3a2c9ed5-295f-5367-aed3-d85b6e867c0e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fb3560fb-9ea9-5805-8962-7f8379ef9e3c","sourceKey":"bank:BUA101:BUA-0017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a general force?","options":["Technological conditions","Customers","Competitors","Investors"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"General (macro) forces are broad conditions that affect all organisations, such as technological, economic, political-legal and socio-cultural conditions. Customers, competitors and investors (B, C and D) are specific forces in a firm's task environment that it deals with directly."}},{"itemId":"6d3d9934-da10-597f-a1cb-f467455a71e1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e6eed4ef-28d5-5ff8-834b-bd81ddcb141f","sourceKey":"bank:BUA101:BUA-0018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following business functions is responsible for identifying customer wants and developing products that satisfy these wants?","options":["Accounting and finance","Production and operations","Marketing","Employment relation and human resources management function"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Marketing finds out what customers want and works to develop and offer products that satisfy those wants. Production and operations (B) makes the product, while accounting and finance (A) and HR (D) manage money and people rather than customer needs."}},{"itemId":"f668aecb-9299-5677-9350-4878a97d1351","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1ed080eb-ef39-5c7d-abe7-7f4f369bb2d7","sourceKey":"bank:BUA101:BUA-0020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of this business environment is controllable?","options":["Internal environment","Both internal and external environments","Neither environment","External environment"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"The internal environment, made up of things like the firm's staff, resources, structure and culture, is within management's control. The external environment (D) includes forces such as the economy, government and competitors, which a business can respond to but cannot control. That rules out B, and C is wrong because management clearly does control its internal environment."}},{"itemId":"94d1deca-5b49-5c0e-83dc-b61b2d660257","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bb488462-bf2c-50ec-89a1-1a7d69f60ac6","sourceKey":"bank:BUA101:BUA-0024","parentItemId":null,"revision":1,"payload":{"prompt":"When a business advertises for staff to develop a pool of job candidates, which employment relations activity is it using?","options":["Acquisition","Development","Recruitment","Selection"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Recruitment is the process of attracting people to apply for jobs, for example by advertising vacancies to build a pool of candidates. Selection (D) comes after this, when the firm chooses the best person from that pool, and development (B) concerns training staff who are already employed."}},{"itemId":"aa596280-ffec-57cf-990f-db48a52a7ad9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8e9b3b49-57be-53f8-a8d8-2c1d79b175e8","sourceKey":"bank:BUA101:BUA-0025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the under listed is not a functional area of business?","options":["Mining","Production","Human Resources","Finance and Accounts"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"Functional areas are the internal departments found in most businesses, such as production, human resources, finance and accounts, and marketing. Mining is an industry or type of business activity, not a function within a business, so A is the odd one out."}},{"itemId":"32dafe0d-eefa-5548-9d69-dd1a05e5879c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0e1ede1e-fbdd-5821-97c7-56ab4528e998","sourceKey":"bank:BUA101:BUA-0027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following business functions is responsible for ensuring that the right people are put in the right posts under the right conditions?","options":["Employment relation and human resources management function","Marketing","Accounting and finance","Production and operations"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"The human resources (employment relations) function recruits, selects, places and supports staff, making sure the right people are in the right jobs under the right conditions. Marketing (B) focuses on customers, accounting and finance (C) on money, and production (D) on making the product."}},{"itemId":"95578dfd-7da0-5347-8102-e6470be134d3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e446124f-8178-51fb-9f5f-051852845dfa","sourceKey":"bank:BUA101:BUA-0028","parentItemId":null,"revision":1,"payload":{"prompt":"_______ is a form of business in which a single person or individual owns, finances, manages and controls all the activities of the business with all authority, responsibility and risk","options":["Sole proprietorship","Cooperative society","Partnership","Limited liability company"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A sole proprietorship is owned, financed, managed and controlled by one person, who takes all the profit and bears all the risk. A partnership (C) has two or more owners, while cooperatives (B) and limited liability companies (D) have many members or shareholders."}},{"itemId":"6517bc53-ea02-5224-91da-28006cdfc1c5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6d9f11d5-404b-516a-a23c-8f5d3a079fdb","sourceKey":"bank:BUA101:BUA-0030","parentItemId":null,"revision":1,"payload":{"prompt":"The challenges faced by businesses in complying with government regulations are all of the following but _________","options":["corruption","costs of compliance","political stability","complexity of regulations"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Firms struggle to obey government rules because of corruption, the costs of compliance and how complex regulations can be. Political stability is not a challenge; a stable political environment actually makes rules more predictable and easier to follow, so C is the exception."}},{"itemId":"968ec4ee-e659-5cbc-ae87-4bda7fb8e5a0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"00f4d8e4-429a-5db2-a99c-6a9e2449eb66","sourceKey":"bank:BUA101:BUA-0039","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the business functions is responsible for remuneration of employees?","options":["Production and Operations","Finance and accounting","Marketing","Employment relations"],"correctOption":3,"section":"Developing a Business Mindset","explanation":"Deciding pay, benefits and other rewards for staff is part of the employment relations (human resources) function, which handles compensation. Finance and accounting (B) processes the payments and keeps records, but it does not set or manage employee remuneration."}},{"itemId":"db6f644c-7cbe-54cb-88cc-1ac114b4626f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a5adfe25-a359-5630-a66f-d5f7360d84b8","sourceKey":"bank:BUA101:BUA-0040","parentItemId":null,"revision":1,"payload":{"prompt":"The political-legal environment describes","options":["the relationship between business and government","the customs, values, attitudes, and demographic characteristics of the society in which the organization function","the relationship between government and unions","the intensity of the competition in an industry"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"The political-legal environment is about how business relates to government, including laws, regulations and political stability. Option B describes the socio-cultural environment, and option D describes competition within an industry."}},{"itemId":"8e38b70a-6a07-50e7-9b37-a6da810c5fa1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"aa524352-42ce-54d3-8a61-736067eeddc4","sourceKey":"bank:BUA101:BUA-0042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a feature of the business environment?","options":["Uncertainty","Certainty","Relativity","Dynamic nature"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The business environment is dynamic, uncertain and relative (it differs from place to place and firm to firm). Certainty is not a feature, because firms can never be sure how the environment will change, which is why it is described as uncertain in option A."}},{"itemId":"b6e5487a-5ae0-517a-a091-7a6baeb65fa8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cdae0f86-2741-50ae-81a3-879783328dc3","sourceKey":"bank:BUA101:BUA-0043","parentItemId":null,"revision":1,"payload":{"prompt":"An individual who assumes the risk of starting a business is known as ___________","options":["Investor","Manager","Stakeholder","Entrepreneur"],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"An entrepreneur spots an opportunity and takes on the risk of starting and running a new business. An investor (A) only supplies money, a manager (B) runs a business that may belong to someone else, and a stakeholder (C) is anyone affected by the business."}},{"itemId":"c55c33ba-e243-53f7-a2ee-ddcc64d8aa54","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dd6ae19e-d61f-58a0-ba88-e457a3c5becd","sourceKey":"bank:BUA101:BUA-0046","parentItemId":null,"revision":1,"payload":{"prompt":"_________ is the creation of a business relation between two or more persons who join hands, finance, and skills among others to form a business organization with the objective of realizing a profitable return on investment","options":["Limited liability company","Partnership","Cooperative society","Sole proprietorship"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A partnership is formed when two or more people pool their money, skills and effort to run a business together for profit. A sole proprietorship (D) has only one owner, while a cooperative (C) serves its members and a limited liability company (A) is a separate legal entity owned by shareholders."}},{"itemId":"fe5fec1b-8767-502a-b818-fbbbe78bc8a8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4729c143-7d7f-526f-950e-f82d51642539","sourceKey":"bank:BUA101:BUA-0047","parentItemId":null,"revision":1,"payload":{"prompt":"Both the _______ and the ________ are required for a company formed in Nigeria","options":["Income and revenue statement","Trading and revenue","Memorandum and articles of association","Membership and articles"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"To register a company in Nigeria, the founders must file a memorandum of association, which sets out the company's name and objects, and articles of association, which contain its internal rules. The other options name financial statements or invented terms, not registration documents."}},{"itemId":"a5018b89-050a-5197-8892-b6a32066022b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"165222be-0601-5957-8990-9375d9b624a9","sourceKey":"bank:BUA101:BUA-0051","parentItemId":null,"revision":1,"payload":{"prompt":"A(n) ______ separates the organization from its environment?","options":["Enterprise resource","Organisational boundary","Aggregate output","Process boundary"],"correctOption":1,"section":"Production Systems","explanation":"An organisational boundary is the line that separates what is inside the organisation from its external environment. The other terms do not describe that dividing line: a process boundary marks the limits of a single process, not of the whole organisation."}},{"itemId":"3a233d45-c045-550a-8e0c-584e46a06248","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c0391314-5d43-5e46-8b17-732bc5a37dc3","sourceKey":"bank:BUA101:BUA-0054","parentItemId":null,"revision":1,"payload":{"prompt":"In business, there are several types of business environment, what are these?","options":["External environment","Internal environment and external environment","Internal, external, and economical environment","Economical and internal environment"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The business environment is usually divided into two types: the internal environment inside the firm and the external environment outside it. The economic environment in C and D is one part of the external environment, not a separate type."}},{"itemId":"38350999-316e-5f88-b200-ab9c7b79ceb0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c2c4b395-42ac-5340-9ac1-ab24988b8200","sourceKey":"bank:BUA101:BUA-0059","parentItemId":null,"revision":1,"payload":{"prompt":"The careful monitoring of an organisation's internal and external environments for detecting early signs of opportunities and threats that may influence its current and future plans means","options":["Environment Scanning","PESTLE Analysis","SWOT Analysis","Market Analysis"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"Environmental scanning means continuously watching the internal and external environments to catch early signs of opportunities and threats. Market analysis (D) looks only at a particular market, while PESTLE and SWOT (B and C) are tools used to organise what scanning finds."}},{"itemId":"7adeaf6c-f61d-5acc-92c3-bc7ff040ba01","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b9370522-c70c-5f39-997f-d1dcb30cd8df","sourceKey":"bank:BUA101:BUA-0061","parentItemId":null,"revision":1,"payload":{"prompt":"_______ means purposeful or deliberate activities concerned with the provision of goods and services which are distributed through organized system (called distribution)","options":["Retainership","Business","Dealership","Distribution"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Business is the purposeful, organised activity of providing goods and services that are distributed to customers. Distribution (D) is only the part that moves goods to buyers, while retainership and dealership (A and C) are specific trading arrangements, not the general idea."}},{"itemId":"ceedcc94-6e2e-5d03-abc7-d156274badd7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"98ac6e98-de7e-504f-b881-cdd7621d4e89","sourceKey":"bank:BUA101:BUA-0064","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following indicates the importance of business environment?","options":["Improvement of performance","All of these","Identification of opportunities and threats","Coping with rapid changes"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Studying the business environment helps a firm identify opportunities and threats, improve its performance and cope with rapid changes. Since A, C and D are all genuine benefits, B (all of these) is the best answer."}},{"itemId":"c39389e1-62e0-5c0f-86f5-041c2b998303","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d3e43bd3-ed97-53f5-8458-60d0c654aa3a","sourceKey":"bank:BUA101:BUA-0069","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these combinations of mechanisms aid organisational business processes toward profit making and provision of essential services?","options":["logistics and distribution, regular order, and suppliers","production, finance and accounts, and dividends","human resources, wages, and marketing","production, research and development, and human resources"],"correctOption":3,"section":"Developing a Business Mindset","explanation":"Production, research and development, and human resources are all functional areas that work together to make products and deliver services. The other options mix in items that are not business functions, such as dividends, wages or suppliers."}},{"itemId":"5d131431-5fe4-5cfe-b2c7-1031df0b2103","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"625f3276-adaf-58da-ad33-2824cd0be577","sourceKey":"bank:BUA101:BUA-0093","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a non-financial motivator?","options":["Bonus","Salary","Public recognition","Overtime pay"],"correctOption":2,"section":"Employee Motivation","explanation":"A non-financial motivator encourages effort through praise, status or growth rather than cash, and public recognition of good work does exactly that. A bonus (A), a salary (B) and overtime pay (D) are all money payments, so they are financial motivators."}},{"itemId":"db4c7d60-3f4f-5a6d-b6a8-04476ed60b78","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"845c4264-3f5a-5718-babc-3d742d1ec6a6","sourceKey":"bank:BUA101:BUA-0120","parentItemId":null,"revision":1,"payload":{"prompt":"In a general partnership, liability is _______________ and __________ partner can be held liable for the business's entire debt.","options":["limited; neither","limited; each","high; all","unlimited; each"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"In a general partnership, the partners have unlimited liability, and each partner can be held personally responsible for all of the business's debts, not just a share of them. Options A and B wrongly say liability is limited, and C uses 'high', which is not the legal term."}},{"itemId":"0c86fdf3-0a9b-51f4-bad1-e03e11330727","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"eff3b681-d7d7-5e45-95ef-6d5f65869d60","sourceKey":"bank:BUA101:BUA-0121","parentItemId":null,"revision":1,"payload":{"prompt":"One disadvantage to the corporate form of business organization is that","options":["corporate dividends are taxed twice, once as corporate income and once as personal income","decision making is complicated by the large number of shareholders","the threat of a takeover looms large most of the time","bondholders have first claim to a corporation's profits"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Double taxation is the classic disadvantage of a corporation: profits are taxed as corporate income, and then shareholders pay personal tax again on the dividends they receive. Option C overstates things, since most corporations are not under constant takeover threat, and Option D is false because bondholders are creditors with a claim on interest and assets, not on profits."}},{"itemId":"ebda9a4d-e405-5401-8a23-54852ef889a6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c478526a-70b6-5147-aaef-6acbfc9cab96","sourceKey":"bank:BUA101:BUA-0122","parentItemId":null,"revision":1,"payload":{"prompt":"The single most important advantage of a sole proprietorship is","options":["the independence it affords the owner","the ability to finance expansion through stock sales","limited liability","unlimited liability"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"The biggest attraction of a sole proprietorship is independence: the owner is their own boss and makes all the decisions. Option B is wrong because a sole proprietor cannot sell stock, Option C is wrong because liability is unlimited, and Option D (unlimited liability) is a disadvantage, not an advantage."}},{"itemId":"0ae66858-fa97-5cc3-a3ed-13f82953a0f1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f0a6c43a-bbd5-5ef9-89c5-27b61c847dd3","sourceKey":"bank:BUA101:BUA-0123","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is considered a non-profit organization?","options":["McDonald's","World Health Organization (WHO)","Apple Inc.","Tesla"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The World Health Organization exists to promote public health, not to make profits for owners, so it is a non-profit organisation. McDonald's (A), Apple (C) and Tesla (D) are all profit-seeking companies owned by shareholders."}},{"itemId":"c1cf70fc-e727-567f-9136-ec34484fcdf8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f30b02b9-b803-5f64-82f7-a4dcc30bf869","sourceKey":"bank:BUA101:BUA-0124","parentItemId":null,"revision":1,"payload":{"prompt":"A sole proprietorship is a business where all of the following are true except that","options":["the owner has complete control over decision-making","the proprietor is liable for losses to the extent of his or her assets","the proprietorship is the most numerous type of business","the proprietor can sell stock to increase its capital resources"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"A sole proprietorship has no shares, so the owner cannot sell stock to raise capital; that is only possible for a company. Options A, B and C are true: the owner has full control, is personally liable for losses, and this is the most common form of business."}},{"itemId":"3c476324-fffc-5241-af6f-ae2d33f5e8de","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"061ccc47-45c7-5537-8256-35d0f5cb50cf","sourceKey":"bank:BUA101:BUA-0125","parentItemId":null,"revision":1,"payload":{"prompt":"Unlimited liability for sole proprietors means that","options":["they can lose everything they own if their businesses fail","they should form corporations instead","proprietors are liable for the value of all the shares they own in a business","a partnership appears relatively more attractive"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Unlimited liability means the owner's personal assets, such as savings, car or house, can be taken to pay the business's debts, so they could lose everything if the business fails. Option C describes shareholders, while Options B and D are opinions about other forms of business rather than what the term means."}},{"itemId":"f9c88a7d-ce4c-5865-8ee0-673ac2609d0e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b30e08b0-be64-54e3-8f8c-4494af518958","sourceKey":"bank:BUA101:BUA-0126","parentItemId":null,"revision":1,"payload":{"prompt":"The limited liability associated with the corporate form of ownership results from","options":["corporations existing as legal entities, separate and apart from their owners","corporations being much less likely to experience losses","banks that offer loans to corporations at low interest rates","lower taxes on dividends"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A corporation is a separate legal entity from its owners, so its debts belong to the corporation and shareholders can lose only what they invested. Options B, C and D are not the source of limited liability; corporations can still make losses, and loan rates or dividend taxes have nothing to do with it."}},{"itemId":"a2b878b2-500e-5cc8-b611-ca1df209fcc2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d263e2da-b686-5722-884f-f9064ae2b12e","sourceKey":"bank:BUA101:BUA-0127","parentItemId":null,"revision":1,"payload":{"prompt":"All of the following are characteristics of corporations except that","options":["the power of corporate managers is complete and cannot be challenged by stockholders","liability is limited","the corporation is a separate legal entity","the corporation may gain access to funds by issuing more stock"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Corporate managers are answerable to the board and, through it, to shareholders, who can vote out directors, so their power is not complete or beyond challenge. Options B, C and D are genuine features of a corporation: limited liability, separate legal status and the ability to raise funds by issuing stock."}},{"itemId":"4d6004c0-3807-59c2-95bb-49929a7a9a0c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"74660a6e-5a63-5aae-83ed-5c89342702a7","sourceKey":"bank:BUA101:BUA-0128","parentItemId":null,"revision":1,"payload":{"prompt":"All of the following are characteristics of sole proprietorships except that","options":["there is a single owner","profits are taxed twice","liability is unlimited","they are the most numerous type of business"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Being taxed twice applies to corporations, whose profits are taxed and then dividends are taxed again; a sole proprietor's profit is simply taxed once as the owner's income. Options A, C and D are true of sole proprietorships: one owner, unlimited liability, and they are the most common type of business."}},{"itemId":"7f4d3644-78b0-5356-9998-4cfe58ca42d3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7b4b2b00-b887-5427-808a-997e3dd498b2","sourceKey":"bank:BUA101:BUA-0130","parentItemId":null,"revision":1,"payload":{"prompt":"A business that makes a product and sells it to customers is known as a:","options":["Service business","Retail business","Manufacturing business","Franchise business"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"A manufacturing business makes (produces) physical products and then sells them. A retail business (B) sells goods made by others, a service business (A) sells services rather than products, and a franchise (D) is a way of owning and running a business, not a type of activity."}},{"itemId":"e892665a-1d3c-54f2-91f9-f7af4c8fb793","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"82daea03-c914-5474-87c4-7f301e57ad1e","sourceKey":"bank:BUA101:BUA-0131","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a service business?","options":["A car assembly plant","A barbershop","A bakery","A furniture factory"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"A barbershop performs an activity, cutting and styling hair, that gives customers a benefit without handing them a physical product, which makes it a service business. A car assembly plant (A), a bakery (C) and a furniture factory (D) all make tangible products, so they are goods-producing businesses."}},{"itemId":"753bc218-32a4-5c58-bd09-fddea4451bb1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"df008a0d-c909-5dbd-a344-d58aa667c5dc","sourceKey":"bank:BUA101:BUA-0132","parentItemId":null,"revision":1,"payload":{"prompt":"What is a characteristic of a sole proprietorship?","options":["can issue stock to raise capital","Provides limited liability to the owner","Owned by a single person","Requires multiple partners"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A sole proprietorship is owned by one person, who takes all the profits and bears all the risks. It cannot issue stock (A), it does not give limited liability (B), and it needs no partners (D)."}},{"itemId":"cc28f334-4cb9-56de-8b4a-c54613b86491","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9a6c34ee-f19c-5f22-a000-08d2950e1e19","sourceKey":"bank:BUA101:BUA-0133","parentItemId":null,"revision":1,"payload":{"prompt":"What is a distinguishing feature of a corporation?","options":["Restriction on raising capital","Ownership by shareholders","No limited liability protection","Joint authority of partners"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A corporation is owned by shareholders, who buy shares (stock) in it. Option A is wrong because corporations raise capital more easily than other forms, Option C is wrong because they give limited liability, and Option D describes a partnership."}},{"itemId":"8309705a-97ff-56b5-ad1d-586523fd6e3a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dd9df730-a9af-52ae-b87f-503994646134","sourceKey":"bank:BUA101:BUA-0134","parentItemId":null,"revision":1,"payload":{"prompt":"What is the benefit of a limited liability company (LLC)?","options":["Limited liability for its owners","Finite life span","Mutual agency among all owners","Unlimited liability for all members"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"The main benefit of a limited liability company is that its owners can lose only what they invested, so their personal assets are protected from the business's debts. A finite life span (B) is a drawback, mutual agency (C) is a partnership feature in which one partner's act binds the others, and D is the opposite of what the company offers."}},{"itemId":"4569811d-65c6-509c-b273-7c6c77b14ed2","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"90c0df1c-d990-596f-aa9f-0106d4202f5c","sourceKey":"bank:BUA101:BUA-0135","parentItemId":null,"revision":1,"payload":{"prompt":"What is meant by the term \"entrepreneurship\"?","options":["The ability to manage large businesses","The process of designing and creating new businesses","The study of global economics","The act of managing a corporation"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Entrepreneurship is the process of spotting an opportunity and designing, creating and running a new business, accepting the risk involved. Managing large businesses or corporations (A and D) is management, and studying global economics (C) is a field of study, not entrepreneurship."}},{"itemId":"0a4647c6-d0d2-5cd8-ac54-a4344cc22159","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f0b9f733-990f-5730-b7de-450ba8631251","sourceKey":"bank:BUA101:BUA-0137","parentItemId":null,"revision":1,"payload":{"prompt":"What is the role of the board of directors in a corporation?","options":["They are responsible for mergers and acquisitions.","They own stock and present the coming year's plans and the previous year's results.","They are elected by shareholders as representatives for the company's direction and selection of top executives.","They manage the day-to-day operations of the company."],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Shareholders elect the board of directors to represent their interests, set the company's overall direction and choose top executives such as the CEO. Option D describes management, not the board, and Option B mixes up shareholders with the annual report presented to them."}},{"itemId":"600f43f7-aff6-5031-906b-172490fa665c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"cf2c5a5b-e2cc-51a6-9c77-fd878c20de26","sourceKey":"bank:BUA101:BUA-0138","parentItemId":null,"revision":1,"payload":{"prompt":"What is a hostile takeover?","options":["An action taken by one company to buy a controlling interest in the voting stock of another company against the wishes of management.","Acquiring a company's publicly traded stock using borrowed funds.","A long-term partnership between companies to develop, sell, and produce.","An action when two companies combine in a single entity."],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A hostile takeover happens when one company buys a controlling stake in another company's voting shares even though the target's management opposes it. Option B describes a leveraged buyout, Option C describes a strategic alliance, and Option D describes a merger."}},{"itemId":"bf61e39a-708e-5a95-ac41-85a0ac98b0b0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ad90555d-8659-5d4d-8a38-247d19129b16","sourceKey":"bank:BUA101:BUA-0140","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four traditional factors of production?","options":["Land","Labor","Technology","Capital"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"The classic factors of production are land, labour, capital and entrepreneurship. Technology helps these factors work better, but it is not one of the basic factors, while land (A), labour (B) and capital (D) are."}},{"itemId":"f850aad2-a94e-5cb7-b66b-6db5afe23b44","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ea0fac49-6059-5b50-957d-ac1b792bb0ff","sourceKey":"bank:BUA101:BUA-0141","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main advantage of a strategic alliance?","options":["It creates long-term partnerships between companies to develop, sell, and produce.","It has less risk and work than permanently integrating two companies.","It gives one firm full ownership of the other firm's assets.","It combines two companies into a single entity."],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A strategic alliance lets two firms work together on shared goals while staying independent, which involves less risk and effort than permanently joining the companies. Option A only describes what an alliance does rather than its advantage, and C and D describe an acquisition and a merger."}},{"itemId":"9e9ea549-a076-5c2f-9b6a-be0812467f3a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"214d8785-44ea-5b9c-8706-0a82aef08b49","sourceKey":"bank:BUA101:BUA-0142","parentItemId":null,"revision":1,"payload":{"prompt":"Which business structure offers joint authority and unlimited liability?","options":["Sole proprietorship","Partnership","Limited liability company (LLC)","Corporation"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"In a general partnership, the partners share authority over the business and each has unlimited personal liability for its debts. A sole proprietorship (A) has one owner, so there is no joint authority, while an LLC (C) and a corporation (D) give limited liability."}},{"itemId":"f8cfca13-ce80-5d61-b53a-e392f76cd9f7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"32be6dcf-fdfd-50aa-9ad7-acbd49fca969","sourceKey":"bank:BUA101:BUA-0143","parentItemId":null,"revision":1,"payload":{"prompt":"A business that focuses on making a profit by providing services rather than goods is called a:","options":["Product-based business","Service-based business","Retail business","Wholesale business"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"A service-based business earns profit by performing work for customers, such as banking, hairdressing or consulting, rather than selling physical products. A product-based business (A) sells goods, and retail (C) and wholesale (D) businesses sell goods to consumers or to other businesses."}},{"itemId":"c5d7ce42-1124-537a-bfba-a0baaf8dac0f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"901c8ce6-d6e9-5b92-94a0-9c6f956e3dc2","sourceKey":"bank:BUA101:BUA-0144","parentItemId":null,"revision":1,"payload":{"prompt":"What does SWOT stand for in business analysis?","options":["Strategic Wealth Opportunities and Tactics","Strengths, Weaknesses, Opportunities, and Threats","Success, Work, Opportunities, and Target","Sales, Workforce, Operations, and Technology"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"SWOT stands for Strengths, Weaknesses, Opportunities and Threats; it looks at a firm's internal strong and weak points and at the external opportunities and threats it faces. The other options are made-up expansions of the letters."}},{"itemId":"e93835e9-d489-536c-82d1-1fd4acff0ee7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"04d1b705-0245-5d8c-9927-ad31f3008b59","sourceKey":"bank:BUA101:BUA-0145","parentItemId":null,"revision":1,"payload":{"prompt":"What is a distinguishing feature of a limited liability partnership (LLP)?","options":["Ability to raise capital","Joint authority","Ownership by shareholders","Limited liability for individual partners in certain professions"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"An LLP gives partners limited liability, usually in professions such as law or accounting, so one partner is not personally liable for another partner's negligence. Joint authority (B) is found in ordinary partnerships too, and ownership by shareholders (C) belongs to corporations."}},{"itemId":"b08ac31a-1d9f-5c8e-8f5c-e763f1ae82d5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1f5b876d-9a33-5eb6-896e-75e5d9ec7eb3","sourceKey":"bank:BUA101:BUA-0146","parentItemId":null,"revision":1,"payload":{"prompt":"What is a potential disadvantage of a sole proprietorship?","options":["Joint authority","Unlimited liability","Limited liability","Ability to raise capital"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Unlimited liability is a major drawback of a sole proprietorship, because the owner's personal property can be used to pay business debts. Joint authority (A) belongs to partnerships, and Options C and D are not features of a sole proprietorship at all."}},{"itemId":"9d7159dc-7cd2-5f2a-be59-2c1d3e170f15","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"aef86e49-44e6-5152-b4e0-ddaff52ab31f","sourceKey":"bank:BUA101:BUA-0147","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common type of business ownership?","options":["Sole proprietorship","Exchange partnership","Limited corporation","Mutual company"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"The sole proprietorship, a business owned and run by one person, is the most common form of business ownership. 'Exchange partnership' (B) and 'limited corporation' (C) are not standard forms, and mutual companies (D) are a rare, specialised type."}},{"itemId":"d109f07a-f0d5-5d17-81a3-1b0691a449ff","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ee1a3547-1b76-5857-a9fb-07e998f62b83","sourceKey":"bank:BUA101:BUA-0149","parentItemId":null,"revision":1,"payload":{"prompt":"A business that sells goods in large quantities to retailers is called a:","options":["Wholesale business","Retail business","Manufacturing business","Service business"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"A wholesale business buys goods in large quantities and resells them to retailers or other businesses, not to final consumers. A retail business (B) sells to final consumers, while manufacturing (C) and service (D) businesses describe what a firm makes or does."}},{"itemId":"a0a13182-f18b-5501-80f5-9bc7ab415b88","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"208944f3-5d9f-5dc1-b32a-9683fd8ddc1e","sourceKey":"bank:BUA101:BUA-0150","parentItemId":null,"revision":1,"payload":{"prompt":"What is a distinguishing feature of a strategic alliance?","options":["The partner firms collaborate on shared goals while each remains independent","It typically consists of acquiring a controlling interest in another company","It allows for complete control over the partner company","It results in the creation of a single entity from two companies"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A strategic alliance is an agreement in which two or more businesses work together on mutually beneficial goals while each keeps its independence, and it can be short-term or long-term. Gaining a controlling interest (B), having full control (C) or forming a single entity (D) describe acquisitions and mergers instead."}},{"itemId":"2722e78d-0434-5bae-a756-b2adedff71bc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"afb656bd-cbfc-5a04-96f2-086fafbedbab","sourceKey":"bank:BUA101:BUA-0153","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a business that is most likely to operate in a monopoly market?","options":["Fast food chains","Electric utility companies","Online retail platforms","Smartphone manufacturers"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"Electric utilities often operate as monopolies because the cost of building power networks is so high that one supplier usually serves an area. Fast food chains (A), online retailers (C) and smartphone makers (D) face many competitors."}},{"itemId":"570e71a0-8047-5824-9d36-542e12cdcda9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a0e7c662-7e3f-5366-93f5-7846f5463928","sourceKey":"bank:BUA101:BUA-0154","parentItemId":null,"revision":1,"payload":{"prompt":"Why are small businesses important to a country's economy?","options":["They give an outlet for entrepreneurs.","They can provide specialist support to larger companies.","They can be innovators of new products.","All the above."],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Small businesses matter to an economy in several ways: they give entrepreneurs an outlet, supply specialist goods and services to larger firms, and introduce new products and ideas. Since Options A, B and C are all true, D is the best answer."}},{"itemId":"541fe35d-558d-5d08-bd9f-0c46d3ab05a7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bfd4111d-399d-5d7a-887a-462e8be2446a","sourceKey":"bank:BUA101:BUA-0155","parentItemId":null,"revision":1,"payload":{"prompt":"A business arrangement where one party allows another party to use a business name and sell its products or services is known as ______.","options":["A cooperative.","A franchise.","An owner-manager business.","A limited company."],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"In a franchise, the franchisor allows the franchisee to use its business name, brand and system to sell its products or services, usually in return for fees. A cooperative (A) is owned by its members, and Options C and D are forms of ownership that do not involve licensing another firm's name."}},{"itemId":"741e3842-c452-596e-bfbf-9be78cc700c0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0203399d-c6c8-50a9-9653-36a8c09e5e03","sourceKey":"bank:BUA101:BUA-0156","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following describes the role of marketing in business?","options":["It focuses on producing products and services","It helps increase employee productivity","It involves advertising, selling, and distributing products to customers","It ensures the business complies with legal requirements"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Marketing identifies customer needs and handles promoting, selling and distributing products to customers. Producing products (A) is the operations function, employee productivity (B) relates to HR and management, and legal compliance (D) is not marketing's role."}},{"itemId":"6ca0bb48-8705-5e3e-8a42-b90e6cf135e3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7fc272b0-ad17-5273-be3c-71e4d41b0019","sourceKey":"bank:BUA101:BUA-0157","parentItemId":null,"revision":1,"payload":{"prompt":"Which one of the following is not associated with entrepreneurship?","options":["Applying for a job","Developing an idea for a business","Satisfying the needs of customers","Spotting a business opportunity"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Applying for a job means working for someone else, so it is not part of entrepreneurship. Developing a business idea (B), satisfying customer needs (C) and spotting opportunities (D) are all things entrepreneurs do."}},{"itemId":"f71e4152-d9cb-5018-b6c8-2820b728be0c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a2dd63ab-fe43-56ca-9f8a-31f453b0d8ca","sourceKey":"bank:BUA101:BUA-0158","parentItemId":null,"revision":1,"payload":{"prompt":"A new venture's business plan is significant because","options":["It helps to persuade others to commit funding to the venture.","Can help demonstrate the viability of the venture.","Provides a guide for business activities by defining objectives.","All the above."],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A business plan does several jobs: it persuades lenders and investors to commit funds, shows that the venture can succeed, and guides activities by setting out objectives. Since Options A, B and C are all true, D is the best answer."}},{"itemId":"c3643c2e-ca4d-52ad-9a14-3ed949c57b14","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"463db064-6d92-5399-a517-e1a3fee4b97d","sourceKey":"bank:BUA101:BUA-0159","parentItemId":null,"revision":1,"payload":{"prompt":"A company that operates in several countries is known as a:","options":["Domestic business","Multinational corporation","Franchise","Partnership"],"correctOption":1,"section":"The Global Marketplace","explanation":"A multinational corporation is a company that operates in several national markets, for example with offices or factories in more than one country. A domestic business (A) works within one country, while a franchise (C) and a partnership (D) are business arrangements that say nothing about how many countries a firm operates in."}},{"itemId":"d19fcf90-72d3-5a07-a268-27b8de7fa376","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f297b8e6-dfe5-56aa-b231-a27e2d42a481","sourceKey":"bank:BUA101:BUA-0161","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recognized disadvantage of setting up as a start-up as compared with other routes to market entry?","options":["there is a high failure rate.","less help from various agencies.","there are more funds required.","less satisfaction of the owners"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A big recognised drawback of starting a brand-new business is the high failure rate, since the idea, market and owner are all untested. Options B, C and D are not standard disadvantages; buying a franchise or an existing business, for example, often costs more money, not less."}},{"itemId":"8daef0ec-6934-50fa-be66-ee750fb3f5c8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2cdc7e97-c16a-5e69-bf06-a32b98d5f498","sourceKey":"bank:BUA101:BUA-0162","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a form of financing especially for funding high technology, high-risk and perceived high-reward projects","options":["Fixed capital.","Current capital.","Seed capital.","Venture capital."],"correctOption":3,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Venture capital is money invested in new, often high-technology businesses that carry high risk but may bring high rewards, usually in exchange for part ownership. Seed capital (C) is the small first funding used to test an idea, while fixed (A) and current (B) capital describe how funds are used, not their source."}},{"itemId":"114943e7-ca77-55b2-83aa-21f82b6f2e34","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e2d8f8b3-e0c7-50dc-9f1b-91c024951c61","sourceKey":"bank:BUA101:BUA-0164","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a characteristic of a limited liability company (LLC)?","options":["The owners have unlimited personal liability","Its owners enjoy limited liability and flexible management","It can only be owned by a single person","It cannot own property in its own name"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A limited liability company protects its owners, who can lose only what they invested, and it allows flexible arrangements for how it is managed. Option A is wrong because liability is limited, C is wrong because it can have several owners, and D is wrong because it is a separate legal entity that can own property and sue in its own name."}},{"itemId":"a10f5851-d619-5593-90be-c4642076e9f6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"edf6a42e-4e8b-5be8-86e0-69426305dce7","sourceKey":"bank:BUA101:BUA-0165","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary purpose of a business?","options":["To entertain its stakeholders","To generate and provide customer value","To suppress market rivals","To minimize tax obligations"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Businesses exist to create value for customers by offering goods and services that meet their needs; profit is the reward for doing this well. Options A, C and D are not the purpose of a business, and suppressing rivals or dodging tax can even be unethical or illegal."}},{"itemId":"c96a36fa-31c8-5fc1-afba-4b2cb9c861b6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b4fd2ee2-0c22-59b4-914c-2e69cb206ff3","sourceKey":"bank:BUA101:BUA-0166","parentItemId":null,"revision":1,"payload":{"prompt":"Making the leap from buyer to seller involves:","options":["Grasping customer preferences","Overlooking market shifts","Prioritizing profit margins alone","Evading competitive pressures"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"Moving from buyer to seller means starting to think like a business owner, which begins with understanding what customers want and value. Ignoring market changes (B), focusing only on margins (C) or avoiding competition (D) would make a new seller fail."}},{"itemId":"d385bffc-be83-5b4f-9c46-821b1a70c341","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"844162d0-619e-53a4-b8ef-430030ef270a","sourceKey":"bank:BUA101:BUA-0167","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is part of the external business environment?","options":["Internal staff dynamics","Emerging technological advances","Corporate value systems","Operational protocols"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The external environment is made up of forces outside the firm that it cannot directly control, such as new technology, the economy, laws and competitors. Staff dynamics (A), company values (C) and operating procedures (D) are all inside the firm."}},{"itemId":"8f33be6f-c846-5cb2-8453-73ab8efac1a9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2e78ceec-59f0-59bc-bdfb-69989bc1bb13","sourceKey":"bank:BUA101:BUA-0169","parentItemId":null,"revision":1,"payload":{"prompt":"Which career path focuses on managing a company's financial resources?","options":["Brand promotion specialist","Financial resource director","Production coordinator","Personnel supervisor"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Finance careers deal with getting, managing and controlling a firm's money, so a financial resource director fits. Brand promotion (A) is marketing, production coordination (C) is operations, and personnel supervision (D) is human resources."}},{"itemId":"f58d9abc-5356-57e5-9b49-249c1ad764aa","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5b16f87b-58a6-5a1f-8f50-38e1ecd4dc33","sourceKey":"bank:BUA101:BUA-0170","parentItemId":null,"revision":1,"payload":{"prompt":"Understanding what businesses do involves recognizing:","options":["Their creation of products and services","Their tax avoidance strategies","Their sole focus on employee morale","Their isolation from competition"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"At its core, a business creates and sells goods and services that meet customers' needs, earning profit in return. Options B, C and D are wrong because tax avoidance is not a business's purpose, employee morale is only one concern, and businesses face competition rather than being isolated from it."}},{"itemId":"871c953d-7c84-5b72-9103-7e4124fee1f5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"004876bd-c921-58b2-9ee6-6ce7d8beb947","sourceKey":"bank:BUA101:BUA-0171","parentItemId":null,"revision":1,"payload":{"prompt":"The internal environment of a business includes:","options":["Regulatory frameworks","Workplace culture","Macroeconomic conditions","Rival firms"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"The internal environment covers things inside the organisation, such as its culture, staff, structure and resources. Regulations (A), macroeconomic conditions (C) and rival firms (D) are all external forces."}},{"itemId":"05ed6302-b57e-56d5-806c-d77bf95a7533","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bb44ddfe-3e17-5e1e-8e95-b8da62498b2d","sourceKey":"bank:BUA101:BUA-0172","parentItemId":null,"revision":1,"payload":{"prompt":"Which functional area is responsible for promoting a company's products?","options":["Process optimization","Market outreach","Fiscal planning","Product innovation"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Marketing (market outreach) is the functional area that communicates with customers and promotes the company's products. Process optimisation (A) belongs to operations, fiscal planning (C) to finance, and product innovation (D) to research and development."}},{"itemId":"b0e90697-d244-5902-a469-f3b5f7547813","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2d9bfc35-4e0e-5811-98a4-bd5e1a756134","sourceKey":"bank:BUA101:BUA-0173","parentItemId":null,"revision":1,"payload":{"prompt":"A business mindset involves:","options":["Targeting only immediate wins","Comprehending operational success factors","Shunning all uncertainties","Dismissing client insights"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"A business mindset means understanding the whole picture of what makes a business succeed, including customers, operations, finances and competition. Focusing only on quick wins (A), avoiding all risk (C) or ignoring customers (D) are attitudes that undermine success."}},{"itemId":"710a9c74-d6bd-5d7d-ba4c-18b2aaa675bd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c1863f79-e4f3-5e00-b77c-725b83584132","sourceKey":"bank:BUA101:BUA-0174","parentItemId":null,"revision":1,"payload":{"prompt":"Exploring careers in business can lead to roles in:","options":["Structural engineering","Logistics and distribution","Clinical healthcare","Crop cultivation"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"Logistics and distribution, which means moving goods efficiently from suppliers to customers, is a core business career area. Structural engineering (A), clinical healthcare (C) and crop cultivation (D) are careers in other professional fields."}},{"itemId":"2c49ec24-c96d-53e7-a5cf-cbd54576c33f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c7b7a10e-02b0-5190-be93-b0aa468eeb68","sourceKey":"bank:BUA101:BUA-0175","parentItemId":null,"revision":1,"payload":{"prompt":"The economy is best defined as:","options":["A framework for goods and services exchange","A tax reduction mechanism","An employee oversight tool","A product advertising system"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"An economy is the system through which a society produces, distributes and exchanges goods and services. Options B, C and D describe narrow tools for tax, staff or advertising, not an economy."}},{"itemId":"c204a456-b1a5-5ddf-bf1a-8a27956eb373","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c1c80e39-52c7-5635-83a5-f23b76aeb612","sourceKey":"bank:BUA101:BUA-0176","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a characteristic of a free-market economic system?","options":["State-managed production quotas","Pricing driven by supply and demand","Absence of competitive forces","Uniform resource allocation"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"In a free-market system, prices are set mainly by the interaction of supply and demand, and private firms compete to satisfy buyers. Government production quotas (A) belong to a planned economy, and lack of competition (C) and uniform allocation (D) are not features of free markets."}},{"itemId":"06b3ee4d-7329-512a-a4e3-8efff9c1a8ea","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dd1371fe-0b0f-511b-bb49-08943e86e77c","sourceKey":"bank:BUA101:BUA-0177","parentItemId":null,"revision":1,"payload":{"prompt":"The law of demand states that:","options":["Higher prices boost demand","Lower prices spur demand","Price shifts don't affect demand","Demand remains static always"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"The law of demand says that, other things being equal, quantity demanded rises as price falls (and falls as price rises), so lower prices encourage people to buy more. Option A states the opposite, and Options C and D ignore the link between price and demand."}},{"itemId":"c35aa353-2adb-5e3d-8b92-fde49bea1ecd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7e74ee6c-57e3-558e-b971-60503c07f409","sourceKey":"bank:BUA101:BUA-0178","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a macroeconomic indicator?","options":["A firm's quarterly earnings","National GDP figures","A worker's salary","A company's overhead costs"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"Macroeconomic indicators measure the performance of the whole economy, and GDP, the total value of goods and services produced in a country, is the most widely used one. A firm's earnings (A), a worker's salary (C) and a company's overheads (D) are microeconomic, individual-level figures."}},{"itemId":"a3165dac-ace6-5f2c-8a5f-4f938170abc0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c33bf977-9a0c-5db8-a2df-739a99a5d061","sourceKey":"bank:BUA101:BUA-0179","parentItemId":null,"revision":1,"payload":{"prompt":"The government's role in a free-market system includes:","options":["Fixing all market prices","Enforcing rules for fair play","Directing all enterprises","Nullifying market dynamics"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"In a free-market system, government mainly sets and enforces the rules, such as protecting property rights, enforcing contracts and preventing unfair competition. Fixing all prices (A), directing all firms (C) or cancelling market forces (D) would describe a planned economy instead."}},{"itemId":"dbdd6578-7e31-5a3d-8dff-04c3f8007a42","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c9f32861-56d1-5721-a36b-2514c4885c90","sourceKey":"bank:BUA101:BUA-0180","parentItemId":null,"revision":1,"payload":{"prompt":"Inflation is an example of:","options":["An economic condition metric","A promotional campaign tactic","A corporate operational role","A business structure type"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"Inflation, the general rise in prices over time, is one of the key measures used to track the condition of an economy, alongside GDP and unemployment. It is not a promotion tactic (B), a role in a company (C) or a type of business structure (D)."}},{"itemId":"5e093845-5484-5095-9800-b5521cd8eaa9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2289ecbc-9edf-5a1d-be4b-43dc56004da3","sourceKey":"bank:BUA101:BUA-0181","parentItemId":null,"revision":1,"payload":{"prompt":"In a command economy, resources are allocated by:","options":["Market-driven forces","Central government authority","Private company decisions","Consumer purchasing power"],"correctOption":1,"section":"Understanding Basic Economics","explanation":"In a command economy, the central government decides what is produced, how it is produced and who gets it, so resources are allocated by state authority. Options A and D describe how a market economy works, where prices and consumer spending guide resources, and option C describes private firms deciding, which is also a market feature."}},{"itemId":"e9e98af7-1454-57f7-af3e-4485a978ea3c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"02b298f8-1f14-521d-97c5-652a5d051cdc","sourceKey":"bank:BUA101:BUA-0182","parentItemId":null,"revision":1,"payload":{"prompt":"The law of supply states that:","options":["Rising prices cut supply","Falling prices boost supply","Rising prices lift supply","Supply ignores price changes"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"The law of supply says that as the price of a good rises, sellers are willing to offer more of it, because higher prices make production more profitable. Options A and B state the relationship backwards, and option D wrongly suggests supply does not respond to price at all."}},{"itemId":"d78968c6-2188-59b5-96d9-d76f37b5444e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f3859ac5-8e00-5710-90d4-6b5b70a3d7bc","sourceKey":"bank:BUA101:BUA-0183","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following measures economic growth?","options":["Joblessness statistics","Price level index","Total national output (GDP)","Borrowing cost rates"],"correctOption":2,"section":"Understanding Basic Economics","explanation":"Economic growth is measured by the increase in a country's total output of goods and services, which is captured by Gross Domestic Product (GDP). Option A measures unemployment, option B measures the price level (used for inflation) and option D refers to interest rates, so none of these directly measures growth."}},{"itemId":"ce53d14f-f100-5f74-b680-e3bc89a90115","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ae667687-5925-5eee-987c-0758214fb6ba","sourceKey":"bank:BUA101:BUA-0184","parentItemId":null,"revision":1,"payload":{"prompt":"A mixed economy combines elements of:","options":["Market freedom and state control","Tradition and market dynamics","State planning and customs","All economic systems"],"correctOption":0,"section":"Understanding Basic Economics","explanation":"A mixed economy blends free-market activity with government control, so private firms operate alongside state regulation and some public ownership. Options B and C bring in tradition and customs, which are features of a traditional economy, and option D overstates it, since a mixed economy is mainly a mix of market and command features."}},{"itemId":"32d06b6f-b18d-5dbc-963c-5cef9a0bc69a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d1a4996a-bb27-5ae6-9283-13cc30044f31","sourceKey":"bank:BUA101:BUA-0185","parentItemId":null,"revision":1,"payload":{"prompt":"International trade involves:","options":["Domestic goods circulation","Cross-border goods exchange","Non-export production focus","Global rivalry avoidance"],"correctOption":1,"section":"The Global Marketplace","explanation":"International trade is the exchange of goods and services across national borders, for example a Nigerian firm selling to buyers in Ghana. Option A describes domestic trade within one country, while options C and D describe avoiding exports and global competition, which is the opposite of trading internationally."}},{"itemId":"8b697a61-d14a-5375-ae3d-23318c753179","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d48d1750-b454-5127-9ff0-0a000308c5db","sourceKey":"bank:BUA101:BUA-0186","parentItemId":null,"revision":1,"payload":{"prompt":"A tariff is:","options":["A levy on inbound goods","An export incentive payment","A monetary unit type","A bilateral trade pact"],"correctOption":0,"section":"The Global Marketplace","explanation":"A tariff is a tax or duty placed on imported goods, which makes foreign products more expensive and protects local producers. Option B describes an export subsidy, option C describes a currency and option D describes a trade agreement, none of which is a tariff."}},{"itemId":"24559ac6-58d7-5e6e-a4d5-06488b27092c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6b2951a3-0b53-5f49-83e7-62cebc8f7d2d","sourceKey":"bank:BUA101:BUA-0187","parentItemId":null,"revision":1,"payload":{"prompt":"Which organization promotes free trade globally?","options":["UN peacekeeping body","WTO trade facilitators","IMF financial stabilizers","WHO health advocates"],"correctOption":1,"section":"The Global Marketplace","explanation":"The World Trade Organization (WTO) exists to promote free and fair trade among countries by setting trade rules and settling trade disputes. The IMF in option C deals with financial and exchange-rate stability, the UN body in option A handles peace and security, and the WHO in option D focuses on health."}},{"itemId":"161c8295-c7af-59e7-a436-f87618fb7379","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"2c3b5579-8ddb-581e-9330-c274e929c596","sourceKey":"bank:BUA101:BUA-0188","parentItemId":null,"revision":1,"payload":{"prompt":"The global business environment includes:","options":["Just fiscal considerations","Cultural, political, and economic aspects","Only tech developments","Solely regulatory factors"],"correctOption":1,"section":"The Global Marketplace","explanation":"The global business environment is made up of many forces, especially cultural, political and economic differences between countries that affect how firms operate abroad. Options A, C and D each limit it to a single factor (only money, only technology or only regulation), which is too narrow."}},{"itemId":"ca99b318-ed5c-59f7-a117-2ad904a1f5f7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c00137a6-3ac8-532c-806e-c5864b854ba7","sourceKey":"bank:BUA101:BUA-0189","parentItemId":null,"revision":1,"payload":{"prompt":"Exporting is a form of:","options":["Local trade activity","Global business engagement","Regional marketing effort","Internal commerce"],"correctOption":1,"section":"The Global Marketplace","explanation":"Exporting means producing goods in one country and selling them to buyers in another, so it is one of the basic forms of international (global) business. Options A, C and D all describe trade that stays within one country or region, which is not what exporting is."}},{"itemId":"0626bd8f-a85d-5d99-a05f-d78e0e1cb0f3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"98622536-f10e-53f9-acb2-a97abceb059d","sourceKey":"bank:BUA101:BUA-0190","parentItemId":null,"revision":1,"payload":{"prompt":"A conflict in international trade can arise due to:","options":["Open trade policies","Barriers like import duties","Cooperative alliances","Stable exchange rates"],"correctOption":1,"section":"The Global Marketplace","explanation":"Trade conflicts often arise when countries put up barriers such as tariffs, import duties and quotas, which can lead other countries to retaliate. Options A, C and D describe open policies, cooperation and stable currencies, which tend to reduce conflict rather than cause it."}},{"itemId":"d67471b1-f1d4-5c0e-b9df-a687db081b3a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4c700351-8734-52e9-b0ee-1a6434d585a9","sourceKey":"bank:BUA101:BUA-0191","parentItemId":null,"revision":1,"payload":{"prompt":"A strategic approach to international markets includes:","options":["Overlooking local customs","Tailoring offerings to regions","Shunning market rivals","Cutting export volumes"],"correctOption":1,"section":"The Global Marketplace","explanation":"A sound strategy for entering foreign markets often involves adapting products and marketing to suit local tastes, culture and needs. Option A ignores local customs, which usually leads to failure abroad, while options C and D (avoiding rivals and cutting exports) are not strategies for growing in international markets."}},{"itemId":"4eb1df1f-4f58-533e-aec5-68d35d32808f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"743ff7f5-d30e-5870-97d3-98fdd7d009fb","sourceKey":"bank:BUA101:BUA-0192","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a benefit of international trade?","options":["Loss of foreign buyers","Broader market access","Elevated production expenses","Narrowed product range"],"correctOption":1,"section":"The Global Marketplace","explanation":"International trade lets firms sell beyond their home country, giving them access to larger markets and more customers. Option A is the opposite of what trade does, since it adds foreign buyers rather than losing them, and options C and D are wrong because trade usually lowers costs and widens product choice."}},{"itemId":"40e9fc30-baa4-5fa7-ae1d-f8a3a09a49ef","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"f5bd3dc9-fec3-5f38-ba68-d896325b8f0e","sourceKey":"bank:BUA101:BUA-0193","parentItemId":null,"revision":1,"payload":{"prompt":"A multinational corporation operates in:","options":["A single national market","Several national markets","One geographic zone","A lone urban center"],"correctOption":1,"section":"The Global Marketplace","explanation":"A multinational corporation is a company that operates in several countries, for example with offices, factories or sales operations in more than one nation. Options A, C and D all limit the firm to one country, zone or city, which describes a domestic or local business."}},{"itemId":"2c064e4f-5910-57f6-95be-e5d90cef80a8","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"bf1bd588-8091-5aff-94a7-895d34a734bb","sourceKey":"bank:BUA101:BUA-0194","parentItemId":null,"revision":1,"payload":{"prompt":"The balance of trade measures:","options":["Export-import differential","Total economic output","Employment levels","Price escalation rates"],"correctOption":0,"section":"The Global Marketplace","explanation":"The balance of trade is the difference between the value of a country's exports and the value of its imports over a period. Option B describes GDP, option C refers to employment statistics and option D refers to inflation, which are different economic measures."}},{"itemId":"2bd0e929-2acd-55c2-a79a-df47d3abd729","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3ec10b27-d276-5834-a473-7b225310f5f1","sourceKey":"bank:BUA101:BUA-0195","parentItemId":null,"revision":1,"payload":{"prompt":"Business ethics refers to:","options":["Profit pursuit above all","Standards of right and wrong","Neglecting worker rights","Bypassing legal oversight"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Business ethics refers to the standards of right and wrong, such as honesty and fairness, that guide how a business and its people behave. Options A, C and D describe putting profit first, ignoring workers and avoiding the law, which are examples of unethical behaviour rather than definitions of ethics."}},{"itemId":"b4fc508d-37c5-5c67-965c-0dce4d765c28","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b7ebe6cc-ca75-5bda-b607-152ac0addccf","sourceKey":"bank:BUA101:BUA-0196","parentItemId":null,"revision":1,"payload":{"prompt":"Corporate Social Responsibility (CSR) involves:","options":["Profit-only orientation","Duty to societal well-being","Cutting staff benefits","Ignoring ecological impact"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Corporate Social Responsibility (CSR) is the idea that a business has a duty to contribute to the well-being of society, beyond simply making profit. Options A, C and D describe profit-only thinking, cutting staff benefits and ignoring the environment, which go against CSR."}},{"itemId":"d74101e6-bc60-59ac-95ae-f7e012746b5d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"82b2c694-a186-56d8-997b-984d9ce346e9","sourceKey":"bank:BUA101:BUA-0197","parentItemId":null,"revision":1,"payload":{"prompt":"Which perspective views CSR as a moral obligation?","options":["Profit-driven viewpoint","Compliance-focused lens","Duty-based ethical stance","Charitable giving angle"],"correctOption":2,"section":"Business Ethics and Corporate Social Responsibility","explanation":"A duty-based (ethical) view sees CSR as something a firm must do because it is morally right, not just because it pays. Option A treats CSR as a tool for profit, option B sees it as merely obeying rules, and option D reduces it to charity, so none of these treats it as a moral duty."}},{"itemId":"66835c91-8d0a-5b5a-8678-5aec90170a4e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"351d2a33-2c75-5820-a7a6-b37d871623a5","sourceKey":"bank:BUA101:BUA-0198","parentItemId":null,"revision":1,"payload":{"prompt":"CSR toward the natural environment includes:","options":["Boosting emissions output","Lowering carbon footprints","Disregarding regulations","Depleting natural reserves"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Being responsible toward the natural environment means reducing harm, for example by lowering carbon emissions and managing waste properly. Options A, C and D (more emissions, ignoring regulations and using up natural resources) are the opposite of environmental responsibility."}},{"itemId":"23cde3bf-5858-57d7-acd2-600df4ae8e8f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1507aa16-5750-5f22-979c-6fc40157514e","sourceKey":"bank:BUA101:BUA-0199","parentItemId":null,"revision":1,"payload":{"prompt":"CSR toward consumers focuses on:","options":["Delivering risky goods","Ensuring safety and clarity","Lowering quality standards","Dismissing client input"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"CSR toward consumers means providing safe products and clear, honest information so buyers can make good choices. Options A, C and D (risky goods, lower quality and ignoring customer feedback) all harm consumers rather than protect them."}},{"itemId":"98a61fdc-07ed-579c-85ac-2157f22a4595","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e09900ca-34a5-5602-be21-e1d02986949e","sourceKey":"bank:BUA101:BUA-0200","parentItemId":null,"revision":1,"payload":{"prompt":"An example of CSR toward employees is:","options":["Offering equitable pay","Skimping on safety measures","Overlooking worker rights","Extending unpaid hours"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Responsibility toward employees includes paying fair wages and providing safe, decent working conditions. Options B, C and D (poor safety, ignoring worker rights and unpaid extra hours) are examples of treating employees badly."}},{"itemId":"fc036cfa-c91d-5b01-8fd3-5922592fea91","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ffd95b8c-3bf5-583e-b89c-0521069bbe8d","sourceKey":"bank:BUA101:BUA-0202","parentItemId":null,"revision":1,"payload":{"prompt":"The economic perspective on CSR emphasizes:","options":["Profits within legal bounds","Ignoring societal duties","Charity as the sole focus","Excluding stakeholders"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"The economic perspective on CSR holds that a firm's main social responsibility is to make profits for its owners while staying within the law. Options B and D go further than this view by ignoring society and stakeholders entirely, and option C, charity as the only focus, is the opposite of an economic view."}},{"itemId":"0725dc97-60b3-579c-a646-837c9fc1ebc5","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1f50df85-be67-51f7-8946-a0c708f97303","sourceKey":"bank:BUA101:BUA-0203","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a benefit of ethical business practices?","options":["Eroded consumer confidence","Enhanced brand reputation","Increased litigation expenses","Lowered staff morale"],"correctOption":1,"section":"Business Ethics and Corporate Social Responsibility","explanation":"Behaving ethically builds trust with customers, employees and the public, which strengthens a company's brand reputation over time. Options A, C and D (lost confidence, more lawsuits and lower morale) are the usual results of unethical behaviour, not ethical behaviour."}},{"itemId":"dee4f2fd-fba3-543e-b066-33524f598286","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b6cad60c-ead0-5cc0-b644-b62c43c5b31e","sourceKey":"bank:BUA101:BUA-0204","parentItemId":null,"revision":1,"payload":{"prompt":"CSR toward the community includes:","options":["Backing local nonprofits","Degrading the environment","Flouting local statutes","Withdrawing community ties"],"correctOption":0,"section":"Business Ethics and Corporate Social Responsibility","explanation":"CSR toward the community includes supporting local causes, such as funding local charities, schools or development projects. Options B, C and D (harming the environment, breaking local laws and cutting community ties) are irresponsible actions."}},{"itemId":"bba67e39-0683-5ba0-b2a3-0161d5f7788f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0b96b36e-d360-517d-a7a7-ec7783dc6f35","sourceKey":"bank:BUA101:BUA-0206","parentItemId":null,"revision":1,"payload":{"prompt":"A disadvantage of a partnership is:","options":["Protected personal assets","Complementary partner skills","Full personal liability","Broad funding access"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"In a general partnership, the partners have unlimited liability, so their personal property can be used to pay the business's debts. Option A (protected assets) is a feature of a limited company, and options B and D, complementary skills and wider access to funds, are advantages of a partnership."}},{"itemId":"ed682ac3-bc16-5fd7-89cd-5444a598cbca","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7857e147-45c0-5ee9-a359-57ed0b47fea7","sourceKey":"bank:BUA101:BUA-0207","parentItemId":null,"revision":1,"payload":{"prompt":"A corporation is:","options":["A solo-owner enterprise","A distinct legal entity","An unlimited liability outfit","A shareholder-free setup"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A corporation (company) is a separate legal entity from its owners, so it can own property, sue and be sued in its own name. Option A describes a sole proprietorship, option C is wrong because shareholders usually enjoy limited liability, and option D is wrong because a corporation is owned by shareholders."}},{"itemId":"e082e336-6b34-5c01-befa-cb34bbf8017a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0c9b0e54-d98f-5908-b4f6-6668a220b3e5","sourceKey":"bank:BUA101:BUA-0208","parentItemId":null,"revision":1,"payload":{"prompt":"Corporate governance refers to:","options":["Staff recruitment processes","Oversight and management systems","Goods manufacturing","Product promotion"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Corporate governance is the system of rules, processes and oversight, often led by a board of directors, through which a company is directed and controlled. Options A, C and D describe specific business activities (recruitment, production and promotion), not how the company as a whole is governed."}},{"itemId":"1cae953a-5d3a-50cf-a922-5b4a0d7cf775","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b2102ae1-8287-59f7-ad3d-2561760d2b98","sourceKey":"bank:BUA101:BUA-0209","parentItemId":null,"revision":1,"payload":{"prompt":"A merger occurs when:","options":["Two firms unite into one","A firm divides in two","A firm faces insolvency","A firm expands staff"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A merger takes place when two companies combine to form a single business. Option B describes a split or divestiture, option C describes insolvency, and option D is simply growth in staff numbers, none of which is a merger."}},{"itemId":"621c430e-704e-51ad-8277-7d584b074216","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d5818a67-daaf-5fdb-9388-fffe41b3553a","sourceKey":"bank:BUA101:BUA-0210","parentItemId":null,"revision":1,"payload":{"prompt":"A joint venture is:","options":["A lasting company fusion","A new, separate company jointly owned by two parent firms","A single-owner model","A state-run entity"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A joint venture is formed when two companies create a new, separate company that they jointly own, pooling resources and expertise for a specific goal, as Sony Ericsson was. Option A describes a merger, where the firms themselves combine into one, while options C and D describe a sole proprietorship and a state enterprise."}},{"itemId":"5e5586a0-565f-598b-8ff3-7e3465d71790","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"d438bb6f-f649-53b2-98d6-161ec977cfdc","sourceKey":"bank:BUA101:BUA-0211","parentItemId":null,"revision":1,"payload":{"prompt":"An advantage of a sole proprietorship is:","options":["Asset liability shield","Swift decision autonomy","Vast capital resources","Divided accountability"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A sole proprietor is the only owner, so he or she can make decisions quickly without consulting partners or a board. Options A and C are features of companies (limited liability and large capital), and option D, shared responsibility, describes a partnership rather than a one-owner business."}},{"itemId":"aa5c78f4-2f81-582c-9412-2de47f8cd326","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5bc7add3-8ada-590a-a7cb-5ee77630bf65","sourceKey":"bank:BUA101:BUA-0213","parentItemId":null,"revision":1,"payload":{"prompt":"A strategic alliance is:","options":["A permanent consolidation","A cooperative business pact","A lone-owner structure","A regulatory mandate"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A strategic alliance is a cooperative agreement between businesses to work together toward shared goals while each stays independent. Option A describes a merger, option C describes a sole proprietorship and option D describes a government requirement, not an agreement between firms."}},{"itemId":"80695053-0663-51e0-ba54-545b74eaca9b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3c9b71f3-b666-5fc1-a589-d0c3a4c18950","sourceKey":"bank:BUA101:BUA-0214","parentItemId":null,"revision":1,"payload":{"prompt":"In a partnership, profits are:","options":["Hoarded by one partner","Divided among partners","Given to charity","State-controlled"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"In a partnership, profits are shared among the partners, usually according to the terms of their partnership agreement. Options A, C and D are wrong because no single partner keeps everything, profits are not automatically given away, and the state does not control them."}},{"itemId":"0895c056-5a32-5757-bb24-1efe34541fcb","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1c7cd2c0-0c0b-5147-9f73-e4b1df223a97","sourceKey":"bank:BUA101:BUA-0215","parentItemId":null,"revision":1,"payload":{"prompt":"A small business is typically characterized by:","options":["Massive operational scale","Small employee count","Worldwide reach","Heavy capital needs"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Small businesses usually have a small number of employees and operate on a limited scale, often serving a local market. Options A, C and D (huge scale, worldwide reach and heavy capital needs) describe large corporations instead."}},{"itemId":"346a667d-43ed-577a-8a42-1a6598249078","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e01f9719-0527-5213-b60d-f971f472053d","sourceKey":"bank:BUA101:BUA-0216","parentItemId":null,"revision":1,"payload":{"prompt":"The entrepreneurial spirit involves:","options":["Risk aversion","Creativity and risk embrace","Sticking to old ways","Ignoring market cues"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The entrepreneurial spirit is about creativity, problem-solving and a willingness to take risks to turn ideas into businesses. Options A, C and D (avoiding risk, sticking to old ways and ignoring the market) are the opposite of how entrepreneurs think."}},{"itemId":"a2294be6-8b21-54aa-9fbf-a8de546fff41","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7cbb37be-30e8-5266-98e7-b0479faab30c","sourceKey":"bank:BUA101:BUA-0217","parentItemId":null,"revision":1,"payload":{"prompt":"The start-up phase of a business includes:","options":["Global market expansion","Business planning and launch","Maintaining growth momentum","Shutting down operations"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The start-up phase covers getting the business off the ground: generating the idea, writing a business plan, raising funds and launching. Options A and C belong to the later growth stage, and option D describes closing the business."}},{"itemId":"b47b59d7-7687-53fc-96ff-4195cbff85e4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"4b51be84-c2ee-5d2c-90e6-6d815d474452","sourceKey":"bank:BUA101:BUA-0219","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a financing option for small businesses?","options":["Commercial bank loans","Tax revenue streams","Staff wage pools","Client opinions"],"correctOption":0,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Bank loans are one of the most common ways small businesses raise money, alongside personal savings, investors and other sources. Option B is government income, option C is money already owed to staff, and option D, customer opinions, is feedback rather than finance."}},{"itemId":"735c142b-4d80-5b4f-94c9-ffcf17efc61d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e9633e22-cce8-5e95-bb2d-d0e715d2abec","sourceKey":"bank:BUA101:BUA-0220","parentItemId":null,"revision":1,"payload":{"prompt":"A franchise is:","options":["A state-owned operation","A licensed brand operation","A company merger type","A solo-owner venture"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A franchise is an arrangement where a business (the franchisee) is licensed to operate under another company's brand name and system in return for fees. Option A describes a public enterprise, option C describes a merger and option D describes a sole proprietorship."}},{"itemId":"eb714d44-9075-5a8e-907b-ed90e01e5901","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1f56f2f9-0a7f-533a-bf8e-8535e1455623","sourceKey":"bank:BUA101:BUA-0221","parentItemId":null,"revision":1,"payload":{"prompt":"The growth phase of a small business focuses on:","options":["Terminating the venture","Building and sustaining progress","Shrinking operations","Dodging competitors"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"The growth phase is about building on early success: scaling operations, managing cash flow and growing the customer base. Options A and C describe closing or shrinking the business, and option D, avoiding competitors, is not what the growth stage is about."}},{"itemId":"8516adbf-fb54-5ce0-aaa1-908691eeeb98","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b974f4c2-7026-5b38-9ca3-21b748f69545","sourceKey":"bank:BUA101:BUA-0222","parentItemId":null,"revision":1,"payload":{"prompt":"An advantage of a franchise is:","options":["Elevated risk exposure","Pre-existing brand fame","Minimal franchisor aid","Steep initial investment"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"A key advantage of buying a franchise is that you start with a known brand name and proven system, which helps attract customers quickly. Options A, C and D are wrong because franchising usually lowers risk, comes with support from the franchisor, and a high start-up cost is a disadvantage, not an advantage."}},{"itemId":"65e01d2f-09eb-5b0e-a171-a7cdacc2ba31","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"e47cd5bf-4adc-5c65-9892-342cf72314fc","sourceKey":"bank:BUA101:BUA-0223","parentItemId":null,"revision":1,"payload":{"prompt":"Entrepreneurs often face the challenge of:","options":["Zero competitive pressure","Unlimited funding access","Navigating risks and unknowns","Stifling new ideas"],"correctOption":2,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Entrepreneurs regularly face risk and uncertainty, since a new business may not succeed and conditions can change quickly. Options A and B are wrong because entrepreneurs usually face competition and limited funds, and option D is not a challenge they face but something they work against."}},{"itemId":"76aef17d-4a08-55fd-bde1-b176135ebabe","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c62e4a35-16bd-5c43-af14-3d0c00779e3f","sourceKey":"bank:BUA101:BUA-0224","parentItemId":null,"revision":1,"payload":{"prompt":"A small business contributes to the economy by:","options":["Cutting employment options","Fostering jobs and innovation","Raising tax burdens","Curbing competition"],"correctOption":1,"section":"Entrepreneurship and Small-Business Ownership","explanation":"Small businesses help the economy by creating jobs and introducing new ideas, products and services. Options A, C and D (fewer jobs, higher taxes and less competition) describe the opposite of what small firms usually contribute."}},{"itemId":"10bd122f-ea50-55f5-b589-be1f1078c4d6","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"80dab6be-dfec-5761-92d9-e13c47c1eedb","sourceKey":"bank:BUA101:BUA-0225","parentItemId":null,"revision":1,"payload":{"prompt":"The primary role of a manager is to:","options":["Handle routine technical work","Drive organizational objectives","Focus solely on promotion","Avoid making choices"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"A manager's main job is to achieve the organisation's goals by planning, organising, leading and controlling the work of others. Option A describes the work of operative or technical staff, while options C and D are not management roles at all."}},{"itemId":"79781954-efdd-5086-8190-754cadc4c77a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7e8bdeb2-98e0-561e-a7e1-96ba74bd8b0e","sourceKey":"bank:BUA101:BUA-0226","parentItemId":null,"revision":1,"payload":{"prompt":"The planning function of management involves:","options":["Defining objectives and tactics","Tracking staff output","Recruiting new hires","Mediating disputes"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Planning is the management function of setting goals and deciding the strategies and actions needed to reach them. Option B describes controlling, option C relates to staffing or HR work, and option D is part of leading."}},{"itemId":"40da81e2-5d09-5ca2-9ba8-685add667fea","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ff2f6b6b-7d1d-52c6-bc82-378908cebfec","sourceKey":"bank:BUA101:BUA-0227","parentItemId":null,"revision":1,"payload":{"prompt":"The organizing function of management includes:","options":["Budget goal-setting","Task and resource assignment","Employee encouragement","Performance reviews"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Organizing means arranging tasks, people and resources so that plans can be carried out, for example by assigning duties and setting up departments. Option A belongs to planning, option C belongs to leading, and option D belongs to controlling."}},{"itemId":"d3f9f57e-408f-5773-b494-8d2f6b2caeef","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"dba6aea9-09ff-57c8-ba8a-36c8430c15e7","sourceKey":"bank:BUA101:BUA-0228","parentItemId":null,"revision":1,"payload":{"prompt":"The leading function of management focuses on:","options":["Output oversight","Inspiring team morale","Fiscal forecasting","Product development"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"Leading is the function of guiding, motivating and inspiring people so they work willingly toward the organisation's goals. Option A is controlling, option C is part of planning, and option D is an operational activity rather than a management function."}},{"itemId":"07c34e55-678a-5d19-a48c-a1edbc64aa22","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6231be70-f1d3-5a2a-b4b0-198e2d1268a1","sourceKey":"bank:BUA101:BUA-0229","parentItemId":null,"revision":1,"payload":{"prompt":"The controlling function ensures that:","options":["Targets are met via oversight","Staff are onboarded","Goods are advertised","Finances are overlooked"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Controlling involves monitoring performance, comparing it with targets and taking corrective action so that goals are met. Option B is part of staffing, option C is a marketing activity, and option D is the opposite of control."}},{"itemId":"8182ff31-f2b6-53b1-85db-9cf076ee0000","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"45c76799-9bd6-5c4d-a87f-2f53dff4db56","sourceKey":"bank:BUA101:BUA-0231","parentItemId":null,"revision":1,"payload":{"prompt":"A manager acting as a spokesperson is performing which role?","options":["Relationship-building role","Information-sharing role","Decision-making role","Skill-based role"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"When a manager speaks on behalf of the organisation to outsiders, such as the press or government, he or she is playing an informational role. Option A covers interpersonal roles like figurehead and leader, and option C covers decisional roles like resolving problems and allocating resources."}},{"itemId":"02af3153-5ebd-530d-b867-c5466723da33","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"8bec4a15-0283-502f-a87b-bf8d6c2f4ba0","sourceKey":"bank:BUA101:BUA-0232","parentItemId":null,"revision":1,"payload":{"prompt":"The ability to think strategically is an example of:","options":["Hands-on expertise","Teamwork aptitude","Visionary capability","Task execution skill"],"correctOption":2,"section":"Management Roles, Functions and Skills","explanation":"Strategic, big-picture thinking is what is called conceptual skill, the ability to see the organisation as a whole and plan for the future, which is the visionary capability in option C. Option A refers to technical skill and option B refers to human (people) skill, which are different management skills."}},{"itemId":"798b71e8-8a7e-5eb8-a49c-b6f186565390","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7cd01335-0f08-5493-a0a3-fee85343a0f5","sourceKey":"bank:BUA101:BUA-0233","parentItemId":null,"revision":1,"payload":{"prompt":"A manager resolving a conflict is performing which role?","options":["Observer","Mediator","Guide","Innovator"],"correctOption":1,"section":"Management Roles, Functions and Skills","explanation":"When a manager settles a conflict between people or units, he or she acts as a mediator, handling the disturbance so work can continue. Option A, observer, only watches without acting, while options C and D (guide and innovator) describe leading and introducing change rather than resolving disputes."}},{"itemId":"37dd4c10-d26c-5e97-aaa9-85b17f016056","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c97b15ba-212a-5d5d-86ae-06a06c8010b0","sourceKey":"bank:BUA101:BUA-0234","parentItemId":null,"revision":1,"payload":{"prompt":"Essential management skills include:","options":["Dialogue and issue resolution","Dismissing input","Shunning collaboration","Profit-only focus"],"correctOption":0,"section":"Management Roles, Functions and Skills","explanation":"Good managers need strong communication and problem-solving skills to work with people and handle challenges. Options B, C and D (ignoring input, avoiding teamwork and focusing only on profit) are weaknesses, not essential skills."}},{"itemId":"a89c4ce5-7e5a-5c1e-b9ea-4e399de91bd9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"64485bf6-dc0e-52ff-ade1-193d74c109f4","sourceKey":"bank:BUA101:BUA-0235","parentItemId":null,"revision":1,"payload":{"prompt":"An effective organization structure ensures:","options":["Defined duties and roles","Heightened disputes","Lowered output","Blocked communication"],"correctOption":0,"section":"Organization and Teamwork","explanation":"A good organisation structure makes clear who does what and who reports to whom, so duties and roles are well defined. Options B, C and D (more conflict, lower output and blocked communication) are signs of a poor structure."}},{"itemId":"e32e7215-e772-5196-9dba-a2031c225d44","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b22cf1cd-6444-53f4-b45b-5714c7e1137d","sourceKey":"bank:BUA101:BUA-0236","parentItemId":null,"revision":1,"payload":{"prompt":"Organizing the workforce involves:","options":["Crafting budget targets","Assigning duties and roles","Promoting merchandise","Employing clients"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Organizing the workforce means dividing the work, assigning duties and roles, and delegating responsibility to the right people. Option A is part of planning, option C is a marketing task, and option D makes no sense, since customers are served rather than employed."}},{"itemId":"f793dcf5-1074-51d2-8523-1b88c89965d4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"923d4d01-d3e6-5860-a155-075fcdf60333","sourceKey":"bank:BUA101:BUA-0237","parentItemId":null,"revision":1,"payload":{"prompt":"A benefit of organizing in teams is:","options":["Lessened teamwork","Enhanced output rates","Stifled dialogue","Increased friction"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Working in teams allows people to combine their skills and effort, which often raises productivity and output. Options A, C and D (less teamwork, less communication and more friction) are problems that badly managed teams can face, not benefits."}},{"itemId":"32050ec1-93f2-5dcc-b66e-1e93eb3450cf","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"1be9ae07-d632-566b-ad60-c61d850be960","sourceKey":"bank:BUA101:BUA-0238","parentItemId":null,"revision":1,"payload":{"prompt":"Ensuring team productivity requires:","options":["Precise goals and tools","Ignoring team input","Blocking interaction","Cutting collaboration"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Teams are most productive when they have clear goals and the tools and resources they need to do the job. Options B, C and D (ignoring input, blocking interaction and cutting collaboration) would reduce team productivity."}},{"itemId":"96504fcd-0b32-5fe3-8327-4f5eab3ce7d9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"07d9d7da-d886-5ac9-b940-56b5c7e26ff0","sourceKey":"bank:BUA101:BUA-0239","parentItemId":null,"revision":1,"payload":{"prompt":"Fostering teamwork involves:","options":["Building trust and unity","Pitting members against each other","Silencing exchanges","Overlooking objectives"],"correctOption":0,"section":"Organization and Teamwork","explanation":"Teamwork grows when members trust one another and feel united around a shared goal. Options B, C and D (setting members against each other, silencing communication and ignoring objectives) would damage teamwork."}},{"itemId":"76e16c73-be20-553a-8047-fec02f3316b3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5b7ca210-d88a-53ec-9567-da8bf53d1262","sourceKey":"bank:BUA101:BUA-0240","parentItemId":null,"revision":1,"payload":{"prompt":"An unstructured organization is characterized by:","options":["Fixed chain of command","Adaptability and fluidity","Rigid guidelines","Stunted creativity"],"correctOption":1,"section":"Organization and Teamwork","explanation":"An unstructured organisation is flexible and adaptable, with loose roles and fewer formal rules, as is common in many start-ups. Options A and C (fixed chain of command and rigid rules) describe a highly structured organisation, and option D is not a defining feature of unstructured firms."}},{"itemId":"dcfefc37-2596-5fc3-bf7b-b68d2e7b3f6c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"206d2d19-1320-57d2-963b-27e7318ba2cb","sourceKey":"bank:BUA101:BUA-0241","parentItemId":null,"revision":1,"payload":{"prompt":"A flat organization structure has:","options":["Numerous management tiers","Minimal management tiers","No authority levels","A single unit"],"correctOption":1,"section":"Organization and Teamwork","explanation":"A flat structure has few layers of management between the top and the front-line employees, which gives managers a wider span of control. Option A describes a tall structure, option C is wrong because a flat structure still has some authority levels, and option D is too extreme."}},{"itemId":"0b42b3d0-b82a-5aaf-a6b7-1553fcf5b95d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ee5f8c93-62a1-59f4-abe8-c718717a0795","sourceKey":"bank:BUA101:BUA-0242","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following improves team performance?","options":["Distrust among members","Open and clear dialogue","Ambiguous targets","Persistent disputes"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Open and clear communication helps team members share ideas, solve problems and coordinate their work, which improves performance. Options A, C and D (distrust, unclear targets and constant disputes) all weaken team performance."}},{"itemId":"672c504d-f8d0-5844-a962-f6e7be5c085e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"9d9b57dd-88d2-5fd5-ada4-d356c7e0c4b7","sourceKey":"bank:BUA101:BUA-0243","parentItemId":null,"revision":1,"payload":{"prompt":"Organizing in teams can lead to:","options":["Delayed resolutions","Quicker issue fixes","Stifled innovation","Curtailed creativity"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Teams bring together different skills and viewpoints, which can help problems get solved faster. Options A, C and D (slower decisions and less innovation or creativity) are possible drawbacks of poorly run teams, not what teams are meant to achieve."}},{"itemId":"37d153cf-51a5-5446-b105-9d1729a4272b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"5c81c6b5-4274-5779-b6ed-eef62ae082bd","sourceKey":"bank:BUA101:BUA-0244","parentItemId":null,"revision":1,"payload":{"prompt":"Managing an unstructured organization requires:","options":["Tight oversight","Flexibility and ingenuity","Resistance to change","Reduced teamwork"],"correctOption":1,"section":"Organization and Teamwork","explanation":"Because unstructured organisations have loose roles and change quickly, managing them requires flexibility and creativity. Option A, tight oversight, suits a rigid structure, while options C and D (resisting change and reducing teamwork) would work against an adaptable organisation."}},{"itemId":"b4aac620-a78e-54de-8577-86359754ab27","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"562e1cc1-e18b-5363-bfb9-25ac935722d1","sourceKey":"bank:BUA101:BUA-0245","parentItemId":null,"revision":1,"payload":{"prompt":"The systems view of business focuses on:","options":["Isolated job functions","Interconnected business parts","Solely promotional efforts","Budgetary planning"],"correctOption":1,"section":"Production Systems","explanation":"The systems view sees a business as a set of connected parts (inputs, processes and outputs, and departments) that work together, so a change in one part affects the others. Option A is the opposite, treating functions in isolation, and options C and D each focus on just one activity."}},{"itemId":"9f11e402-3d15-5edf-837f-7d0d0f1ce6c4","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"29176944-a60d-5314-b57d-a9a52a31cbb6","sourceKey":"bank:BUA101:BUA-0246","parentItemId":null,"revision":1,"payload":{"prompt":"A value chain includes:","options":["Steps enhancing product worth","Cost-cutting measures only","Advertising campaigns","Staff development"],"correctOption":0,"section":"Production Systems","explanation":"A value chain is the series of activities, from sourcing materials through production to sales and service, that add value to a product. Option B is too narrow, and options C and D are only single activities that may form part of the chain."}},{"itemId":"dae73b75-4f6e-5fe5-9ea5-34065d8d9311","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"079b847a-286c-5890-8029-29743584ea66","sourceKey":"bank:BUA101:BUA-0247","parentItemId":null,"revision":1,"payload":{"prompt":"Supply chain management involves:","options":["Overseeing goods flow","Halting production","Ignoring vendors","Restricting delivery"],"correctOption":0,"section":"Production Systems","explanation":"Supply chain management is the coordination of the flow of goods, information and money from suppliers through production to the final customer. Options B, C and D (halting production, ignoring suppliers and restricting deliveries) are the opposite of managing a supply chain."}},{"itemId":"ae7c07b3-5c3a-5b19-906f-4b2333b3d36e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"a29d4a14-18bc-5f45-87d4-dc7f8b801887","sourceKey":"bank:BUA101:BUA-0248","parentItemId":null,"revision":1,"payload":{"prompt":"Production and operations management focuses on:","options":["Product advertising","Streamlined goods creation","Staff recruitment","Financial targets"],"correctOption":1,"section":"Production Systems","explanation":"Production and operations management is concerned with turning inputs into goods and services efficiently, keeping the production process running smoothly. Option A is marketing, option C is human resource management and option D is financial management."}},{"itemId":"ea30e579-4973-5669-a200-0e5df0f1721b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7b9139d4-4290-5c33-85b0-5180717a1ea4","sourceKey":"bank:BUA101:BUA-0249","parentItemId":null,"revision":1,"payload":{"prompt":"A challenge of service delivery is:","options":["Physical product consistency","Variable quality control","Simple quality metrics","Minimal client contact"],"correctOption":1,"section":"Production Systems","explanation":"Services are performed by people, so their quality can vary from one customer or occasion to the next, which makes quality hard to control. Option A refers to physical products, and options C and D are wrong because service quality is hard to measure and services usually involve a lot of customer contact."}},{"itemId":"dec5f668-e476-5995-82fa-b5890f55962b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"31d42639-517d-5f69-8c53-ba66f34b14f4","sourceKey":"bank:BUA101:BUA-0250","parentItemId":null,"revision":1,"payload":{"prompt":"Product quality refers to:","options":["Meeting customer standards","Production expense levels","Promotional efforts","Aesthetic design"],"correctOption":0,"section":"Production Systems","explanation":"Product quality is the degree to which a product meets customers' needs and expectations. Option B is about cost, option C is about marketing, and option D, appearance, is only one small part of quality."}},{"itemId":"83842fbc-5906-5a57-b464-d8fa29c271a9","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fa707088-1a68-5b68-af9c-b61779be4151","sourceKey":"bank:BUA101:BUA-0251","parentItemId":null,"revision":1,"payload":{"prompt":"A value web is:","options":["A straight-line process","A linked value network","A sales strategy","A fiscal blueprint"],"correctOption":1,"section":"Production Systems","explanation":"A value web is a network of linked value chains across different firms, such as suppliers and partners, that work together to create value. Option A describes a simple, straight-line value chain, while options C and D are a sales plan and a financial plan."}},{"itemId":"b0df1c16-729d-53af-8982-df3cc6cb14fd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"7b5a61fe-fd0d-5203-a5df-ecf21422ade1","sourceKey":"bank:BUA101:BUA-0252","parentItemId":null,"revision":1,"payload":{"prompt":"Operations management aims to:","options":["Lower efficiency rates","Boost quality and output","Increase resource waste","Curb innovation"],"correctOption":1,"section":"Production Systems","explanation":"Operations management aims to produce goods and services efficiently, improving both quality and output while making good use of resources. Options A, C and D (less efficiency, more waste and less innovation) are the opposite of its goals."}},{"itemId":"cf618bc9-69ba-5efe-9f29-66df1d8f1f23","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"fe90eb12-6619-5f82-b0d1-a9bdc9002d74","sourceKey":"bank:BUA101:BUA-0253","parentItemId":null,"revision":1,"payload":{"prompt":"The unique challenge of service delivery includes:","options":["Tangible consistency","Client participation","Uniform execution","Low variation"],"correctOption":1,"section":"Production Systems","explanation":"Many services are produced while the customer is present and involved, for example at a salon or clinic, so customer participation affects how the service turns out. Options A, C and D (tangible consistency, uniform execution and low variation) describe physical goods, not the challenges of services."}},{"itemId":"3c797e77-9ff4-5004-b07b-3ca8f939c4da","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"b06cec3e-c416-5a3a-89c0-9a12b357c0c3","sourceKey":"bank:BUA101:BUA-0254","parentItemId":null,"revision":1,"payload":{"prompt":"Process quality focuses on:","options":["How well the production method follows set standards","Manufacturing costs","Product promotion","Staff onboarding"],"correctOption":0,"section":"Production Systems","explanation":"Process quality is about how well the production process follows set standards and procedures, so each step is consistent and produces few defects. Option B is about cost, and options C and D (promotion and onboarding staff) are not about the production process at all."}},{"itemId":"3eafaf9a-4127-5dda-89c4-51e69e89d6da","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"0ee2fd69-633e-507a-b252-17bd27ad111a","sourceKey":"bank:BUA101:BUA-0255","parentItemId":null,"revision":1,"payload":{"prompt":"Employee motivation is important because it:","options":["Cuts productivity levels","Enhances job performance","Boosts staff turnover","Limits creative output"],"correctOption":1,"section":"Employee Motivation","explanation":"Motivated employees put in more effort and care, so motivation improves job performance and productivity. Options A, C and D (lower productivity, higher staff turnover and less creativity) are the results of poor motivation, not good motivation."}},{"itemId":"c1213326-96a0-5664-a32f-d05a5611db8f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"719c41fa-c265-54e0-b1e6-2ef45c19ec31","sourceKey":"bank:BUA101:BUA-0256","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow's hierarchy, the most basic need is:","options":["Personal fulfillment","Recognition and respect","Survival essentials","Social connections"],"correctOption":2,"section":"Employee Motivation","explanation":"In Maslow's hierarchy, physiological needs such as food, water and shelter (survival essentials) form the base and must be met first. Option D (social needs), option B (esteem needs) and option A (self-actualization) sit higher up the hierarchy."}},{"itemId":"edcd4246-cad1-5e5a-a9fe-9634226d52c7","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"ca400060-c61a-5947-8489-542aa13afc0c","sourceKey":"bank:BUA101:BUA-0257","parentItemId":null,"revision":1,"payload":{"prompt":"Motivating with challenging goals involves:","options":["Vague, simple targets","Clear, attainable objectives","Ignoring staff opinions","Lowering expectations"],"correctOption":1,"section":"Employee Motivation","explanation":"Goal-setting motivates best when goals are clear and specific, and challenging but still achievable, as in the SMART approach. Option A is wrong because vague, easy targets do not stretch people, while options C and D (ignoring staff and lowering expectations) weaken motivation."}},{"itemId":"f2c2acf1-f0a9-524e-964f-bf8395057e0c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3fa1ff88-101d-5a7d-b304-1d730779d842","sourceKey":"bank:BUA101:BUA-0258","parentItemId":null,"revision":1,"payload":{"prompt":"Redesigning jobs to stimulate performance can include:","options":["Shrinking duties","Enriching job scope","Narrowing tasks","Dismissing feedback"],"correctOption":1,"section":"Employee Motivation","explanation":"Job enrichment redesigns a job to give the worker more responsibility, variety and control, which makes the work more meaningful. Options A and C shrink the job, which tends to make work dull, and option D, ignoring feedback, does not redesign the job at all."}},{"itemId":"3eaecd2c-9930-5435-b5fd-8ecbbd2f5463","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6a763855-5152-54c2-ab73-15722dfbd1ff","sourceKey":"bank:BUA101:BUA-0259","parentItemId":null,"revision":1,"payload":{"prompt":"Reinforcing high-performance behavior involves:","options":["Overlooking successes","Offering praise and rewards","Cutting incentives","Withholding critiques"],"correctOption":1,"section":"Employee Motivation","explanation":"Reinforcement theory says behaviour that is rewarded tends to be repeated, so praising and rewarding good performance encourages more of it. Options A and C remove the rewards that sustain good behaviour, and option D is not a way of reinforcing performance."}},{"itemId":"1ce226b6-e9e5-5214-9319-3cef3757f23e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"6740f198-3677-5cf6-9080-e0a81d65300d","sourceKey":"bank:BUA101:BUA-0260","parentItemId":null,"revision":1,"payload":{"prompt":"A motivational strategy includes:","options":["Nurturing a positive workplace","Slashing worker perks","Ignoring staff needs","Piling on workloads"],"correctOption":0,"section":"Employee Motivation","explanation":"Creating a positive, supportive work environment is a common way to keep employees motivated. Options B, C and D (cutting perks, ignoring needs and overloading staff) tend to lower morale and motivation."}},{"itemId":"a7ddd81b-d49f-5ef3-a8d2-dbed8c3383ea","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"c206f9d7-e665-5f72-b472-0245ba55cdb5","sourceKey":"bank:BUA101:BUA-0261","parentItemId":null,"revision":1,"payload":{"prompt":"Herzberg's two-factor theory includes:","options":["Motivation and maintenance factors","Fiscal and relational factors","Price and quality factors","Brief and enduring factors"],"correctOption":0,"section":"Employee Motivation","explanation":"Herzberg divided workplace factors into motivators, such as recognition and achievement, and hygiene factors, also called maintenance factors, such as salary and working conditions. Options B, C and D (fiscal and relational, price and quality, brief and enduring) are not the two groups in his theory."}},{"itemId":"aa987c03-ca2f-5ed9-b06b-379fccb9ab3c","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"73edcf3c-e307-5a9d-9a6d-2e9a8e648bae","sourceKey":"bank:BUA101:BUA-0262","parentItemId":null,"revision":1,"payload":{"prompt":"Equity theory explains employee choices based on:","options":["Perceived reward fairness","Job stability assurance","Shift scheduling","Workplace proximity"],"correctOption":0,"section":"Employee Motivation","explanation":"Equity theory says employees compare what they put in and get out of a job with what others receive, and they act based on whether the rewards seem fair. Options B, C and D (job security, scheduling and distance to work) are not what the theory is about."}},{"itemId":"98206a3e-26c8-5e39-92c5-972fbd79b52e","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"72617761-84a8-5e16-9d13-09624b25cd3b","sourceKey":"bank:BUA101:BUA-0263","parentItemId":null,"revision":1,"payload":{"prompt":"A challenging goal should be:","options":["Beyond realistic reach","Precise and trackable","Broad and undefined","Detached from results"],"correctOption":1,"section":"Employee Motivation","explanation":"A good challenging goal is specific and measurable, so employees know exactly what to aim for and can track their progress. Option A is wrong because unrealistic goals discourage people, option C is too vague to guide effort, and option D is wrong because goals should be linked to results."}},{"itemId":"662e77c6-fe46-5d61-a7d4-1cc574720561","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"463139ed-6050-54e7-b391-b0f964ab0be8","sourceKey":"bank:BUA101:BUA-0264","parentItemId":null,"revision":1,"payload":{"prompt":"Job redesign can improve motivation by:","options":["Limiting worker control","Diversifying task range","Reducing duty scope","Overlooking skills"],"correctOption":1,"section":"Employee Motivation","explanation":"Job redesign, for example through job rotation or enlargement, can make work more interesting by giving employees a wider range of tasks. Options A, C and D (less control, fewer duties and ignoring skills) tend to make work duller and reduce motivation."}},{"itemId":"d51ed347-a7e0-5187-b5cb-52ca2f0f42c3","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"33ce43f5-4cef-50ec-903f-c1dd08216fb9","sourceKey":"bank:BUA101:BUA-0265","parentItemId":null,"revision":1,"payload":{"prompt":"What is a business model?","options":["A legal document that registers a company","A concise description of how a business intends to generate revenue","A chart showing a firm's reporting relationships","A list of a company's products and their prices"],"correctOption":1,"section":"Developing a Business Mindset","explanation":"A business model is a short description of how a company plans to make money, for example who its customers are, what it offers them and how it earns revenue. Option A describes a registration or incorporation document, option C describes an organisation chart, and option D is just a product price list."}},{"itemId":"ebb79576-eadf-5116-b451-dbd4ecadcf16","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"10a7c97c-b9be-54c6-b199-40758592fcd6","sourceKey":"bank:BUA101:BUA-0268","parentItemId":null,"revision":1,"payload":{"prompt":"How does the role of a financial manager differ from that of an accountant?","options":["The accountant raises capital for the firm, while the financial manager only records transactions","The two roles are identical and the titles are used interchangeably","The accountant collects, analyzes and reports financial information, while the financial manager sets financial goals, budgets, invests funds and raises capital","The financial manager handles recruitment and pay, while the accountant handles advertising budgets"],"correctOption":2,"section":"Developing a Business Mindset","explanation":"Accountants focus on recording and reporting the firm's financial information, while financial managers use that information to plan, set budgets, invest the firm's money and raise capital. Option A reverses the two roles, option B ignores the real difference between them, and option D mixes in HR and marketing tasks."}},{"itemId":"d54f5ee4-21b1-553a-a561-fd7aa30fdc22","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"533574c0-06b5-5e59-a6db-0848b954b152","sourceKey":"bank:BUA101:BUA-0269","parentItemId":null,"revision":1,"payload":{"prompt":"What is professionalism?","options":["Holding a university degree in a specialised field","Following orders from superiors without question","Wearing formal clothes to work every day","The quality of performing at a high level and conducting oneself with purpose and pride"],"correctOption":3,"section":"Developing a Business Mindset","explanation":"Professionalism means performing at a high level and conducting yourself with purpose and pride, shown through traits like striving to excel, being dependable, communicating well and making ethical decisions. Option A is about qualifications, option B is obedience rather than professionalism, and option C is about appearance only."}},{"itemId":"06d07003-301d-50e3-932e-68bf2ea94cd0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"db0094d1-61f3-5f9d-a4f6-236e0a80b4c2","sourceKey":"bank:BUA101:BUA-0514","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an element of the external business environment?","options":["Political environment","Motivation","Organizational culture","Management structure"],"correctOption":0,"section":"Developing a Business Mindset","explanation":"The external environment is made up of forces outside the firm that it cannot control directly, such as political, economic, social and technological conditions. Options B, C and D, motivation, organisational culture and management structure, all exist inside the firm, so they belong to the internal environment."}},{"itemId":"c2af89ae-e17e-5863-8ad8-5a224152699d","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"cbt_question","questionId":"3605f5c1-c1f8-5ff4-bb6e-5440de50c6db","sourceKey":"bank:BUA101:BUA-0518","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of business ownership provides limited liability to owners?","options":["Sole proprietorship","Limited liability company","Partnership","Sole trader with a registered business name"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A limited liability company is a separate legal person, so its owners can lose only what they invested and their personal property is protected from the company's debts. A sole proprietorship (A), an ordinary partnership (C) and a sole trader operating under a registered business name (D) all leave the owners personally liable for the business's debts."}}]$expected_content$::jsonb,
  'introduction-business-1: cbt_question published payload and identity match source');
