select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('3377fae6-5ab9-5742-95e3-75b94650a294')
  where kind = 'theory_question') = $expected_content$[{"itemId":"673bffa2-543e-5b27-b905-4445464c011f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the five environments in which every business operates, and state two ways business benefits society."}},{"itemId":"45748893-ca91-51ce-974f-4428998bdbb0","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:10","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between e-commerce and e-business, and explain four types of e-commerce transactions with examples."}},{"itemId":"a920fd06-e86d-5415-ba0d-9a989c7f7d21","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between a market economy and a command economy, and explain the role of government in a free-market system."}},{"itemId":"f4adf133-ee00-5bcd-a52b-549479b7fd84","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"Explain four forms of international business activity a Nigerian firm could use to enter a foreign market."}},{"itemId":"63ce438b-49e2-5b06-8a85-df5c773c3a39","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Define corporate social responsibility and explain the four perspectives on CSR."}},{"itemId":"e59886c4-52f7-5e2c-8f64-a9ea1e460c27","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish between a private limited company and a public limited company, and state two advantages and two disadvantages of the corporate form."}},{"itemId":"9957e3ea-8b1f-5d53-a98f-e88cdf2ae4ca","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the franchise alternative and state three advantages and three disadvantages of franchising to the franchisee."}},{"itemId":"453584a8-5d88-577a-b936-3903f3c291a1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the four functions of management, giving one example of each."}},{"itemId":"b84670c8-cb91-50a2-a46c-3ca12b27c710","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"Explain the value chain and identify its primary and support activities. How does a value web differ from a value chain?"}},{"itemId":"b377583e-94c9-51ac-9e48-c9fdebfc90dc","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:9","parentItemId":null,"revision":1,"payload":{"prompt":"Explain Herzberg's two-factor theory and state three ways a manager can redesign jobs to motivate employees."}}]$expected_content$::jsonb,
  'introduction-business-1: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('3377fae6-5ab9-5742-95e3-75b94650a294')
  where kind = 'model_answer') = $expected_content$[{"itemId":"51b76e5f-0c95-52dc-9ccc-d491e48ece22","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"673bffa2-543e-5b27-b905-4445464c011f","revision":1,"payload":{"body":"Define business environment (forces that affect and are affected by business). Then 1-2 lines each, with a Nigerian example: social (trends in society), technological (application of science), economic (cost and availability of goods, services, labour), legal and regulatory (laws, e.g. CAMA 2020 administered by CAC), market (customers, buying influences, competitors). Close with two benefits: goods and services, employment, taxes, national growth and stability."}},{"itemId":"2f398e99-5b70-5354-a637-3a9afa6fd47a","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:10","parentItemId":"45748893-ca91-51ce-974f-4428998bdbb0","revision":1,"payload":{"body":"Define e-commerce (online exchange of goods, services and money between firms and between firms and customers) and e-business (conducting business on the internet; electronic communications for all business processes, including serving customers and collaborating with partners). State that e-business is the wider term. Then 2 lines each, with an example: B2B (firm buying supplies from another firm online), B2C (Jumia or Konga selling to shoppers), C2C (individuals trading on Jiji), B2E (HR posting a vacancy on the intranet). M-commerce or c-commerce may replace any one of these."}},{"itemId":"f82f9081-8c6b-5897-ad96-bba4ff1ec54f","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"a920fd06-e86d-5415-ba0d-9a989c7f7d21","revision":1,"payload":{"body":"Define an economic system. Market economy: demand and supply decide production and prices; private ownership, competition, freedom of choice, limited government intervention. Command economy: central government planning, government ownership of key businesses, control of wages and means of production, little competition and limited choice. Then list and explain government's roles in a free market: legal and social framework (fair-play rules), economic stability (monetary and fiscal policy), maintaining competition (anti-trust body), public goods, income redistribution, international relations. Give a Nigerian example for at least two (e.g. CBN, FCCPC)."}},{"itemId":"b9bb2d13-e876-53bb-8eee-aab7f8279640","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"f4adf133-ee00-5bcd-a52b-549479b7fd84","revision":1,"payload":{"body":"Define international business. Then 2-3 lines each on any four: exporting (sell abroad from home, low risk); licensing (foreign firm uses your brand or technology for royalties); franchising (foreign franchisee runs your business system for fees); joint venture (new firm co-owned with a local partner, shared risk); FDI (own a factory or subsidiary abroad, most control and risk). Close by noting that commitment, control and risk rise from exporting to FDI."}},{"itemId":"f03b068c-ba2a-50ba-a119-14be13182eec","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"63ce438b-49e2-5b06-8a85-df5c773c3a39","revision":1,"payload":{"body":"Define CSR (duty to society beyond profit). Then 1-2 lines each: minimalist (only profit within the law), defensive (CSR to avoid criticism and regulation), cynical (CSR as a PR tool), proactive (CSR as a moral obligation). Close with one example of CSR towards the environment, consumers or employees."}},{"itemId":"b28044fe-70c1-56ac-ac95-567cecc8d881","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"e59886c4-52f7-5e2c-8f64-a9ea1e460c27","revision":1,"payload":{"body":"Define a company as a separate legal entity owned by shareholders. Give four differences: membership (2-50 vs 7+), share transfer and public subscription, publication of accounts, stock-exchange quotation (or debentures, Ltd vs Plc). Advantages: limited liability, perpetual life, access to capital. Disadvantages: double taxation, cost and disclosure requirements."}},{"itemId":"5e11f8df-9553-51b5-8eaa-c496c40825bd","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"9957e3ea-8b1f-5d53-a98f-e88cdf2ae4ca","revision":1,"payload":{"body":"Define a franchise; name franchisor and franchisee; mention the fee and royalties. Advantages: pre-existing brand fame, proven system with lower failure risk, training and support. Disadvantages: high start-up cost, continuing royalties, loss of independence under strict rules."}},{"itemId":"f8559c1a-a8a1-5528-80c1-7e0805cb276b","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"453584a8-5d88-577a-b936-3903f3c291a1","revision":1,"payload":{"body":"Define management. Planning: setting objectives and strategies (e.g. SWOT, mission statement). Organising: assigning tasks, roles and resources (e.g. forming a cross-functional team). Leading: motivating and guiding people (e.g. a democratic manager involving staff). Controlling: setting standards, measuring, comparing and correcting (e.g. comparing monthly sales with target). Conclude that the functions form a continuous cycle."}},{"itemId":"4487c4d0-aec5-59b6-a6e5-663489b27f49","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:8","parentItemId":"b84670c8-cb91-50a2-a46c-3ca12b27c710","revision":1,"payload":{"body":"Define the value chain (linear sequence of value-adding activities within a firm; Porter). List the 5 primary activities with a line each, then the 4 support activities. Mention the 3 steps of value chain analysis. Define the value web (network of interconnected value chains across companies, less linear, built on partnerships) and contrast it with the value chain in two or three points."}},{"itemId":"b2fc1d06-ed01-50e6-a6eb-3ab9307635b1","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:9","parentItemId":"b377583e-94c9-51ac-9e48-c9fdebfc90dc","revision":1,"payload":{"body":"Define motivation. Herzberg: motivators (achievement, recognition, responsibility, the work itself, advancement) relate to job content and create satisfaction; hygiene or maintenance factors (salary, policy, supervision, working conditions, job security) relate to job context and only prevent dissatisfaction. Job redesign: enrichment (more tasks and authority), enlargement (more tasks at the same level), rotation (moving between jobs for variety), each with a short example and one benefit (satisfaction, less turnover)."}}]$expected_content$::jsonb,
  'introduction-business-1: model_answer published payload and identity match source');
