  from public.read_published_managed_content('203d7e61-c829-5419-a664-5a478e05a8a6')
  where kind = 'course_overview') = $expected_content$[{"itemId":"f1def905-4500-5685-805b-a989083ec232","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Finance","body":"Every topic is examinable.","outcomes":["Explain the meaning and scope of finance, the finance function (investment, financing and dividend decisions) and financial management as a tool for planning and control.","Compare profit maximisation and wealth maximisation, and explain stakeholders, the agency problem and agency costs.","Distinguish risk from uncertainty, name the types of risk, and measure risk with expected value, standard deviation and the coefficient of variation.","Calculate simple and compound interest, present and terminal values, annuities and perpetuities, and work with arithmetic and geometric progressions.","Calculate and interpret liquidity, activity, profitability, gearing and market ratios, and state the limits of ratio analysis.","Describe the money and capital markets, primary and secondary markets, the stock market, financial institutions and the sources of finance.","Compare the forms of business firm and explain limited liability."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, calculations and Nigerian institutions.","Calculations come from Topics 3, 4 and 5. Practise the formulas until you can do them quickly."]}}]$expected_content$::jsonb,
  'introduction-finance: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('203d7e61-c829-5419-a664-5a478e05a8a6')
  where kind = 'note') = $expected_content$[{"itemId":"4ad8d8de-4062-5819-ae27-9f8b499aaccf","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Overview of Finance","body":"The meaning and scope of finance; how finance differs from economics and accounting; the branches of finance; the four finance decisions and their other names; the financial manager's role; financial management as a tool for planning and control; the limited liability company and the risks of finance.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The meaning and scope of finance; how finance differs from economics and accounting; the branches of finance; the four finance decisions and their other names; the financial manager's role; financial management as a tool for planning and control; the limited liability company and the risks of finance."}],"lessons":[{"number":"1.1","title":"Meaning and scope of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance:","bold":true},{"text":" the management of money and the process of acquiring the needed funds to achieve a set objective. Put more shortly, finance is the "},{"text":"management of money and money claims","bold":true},{"text":": finance is money, and availability of finance is availability of money."}]},{"text":[{"text":"Finance deals with the "},{"text":"inflows (sources)","bold":true},{"text":" and "},{"text":"outflows (uses)","bold":true},{"text":" of money (funds) within the firm. It serves as a "},{"text":"link","bold":true},{"text":" that makes business interrelationships possible."}]},{"text":[{"text":"Activities of finance (6):","bold":true},{"text":" saving, borrowing, lending, investing, budgeting, forecasting."}]},{"text":[{"text":"Money is important to "},{"text":"individuals","bold":true},{"text":", "},{"text":"businesses","bold":true},{"text":" and "},{"text":"government","bold":true},{"text":", to finance their activities and achieve their targets."}]},{"text":[{"text":"Finance functions of the firm:","bold":true},{"text":" raising capital funds, using them to generate returns, and paying returns to the suppliers of funds (interest to lenders, dividends to shareholders)."}]}]},{"type":"paragraph","text":[{"text":"Importance (characteristics) of finance in a business firm (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Finance "},{"text":"enhances business growth","bold":true},{"text":"."}]},{"text":[{"text":"Finance serves as a "},{"text":"standard (stand) upon which business performance can be measured","bold":true},{"text":"."}]},{"text":[{"text":"Finance "},{"text":"links all other activities together","bold":true},{"text":": marketing, purchasing, production, selling and distribution."}]},{"text":[{"text":"Finance is a "},{"text":"new discipline which has grown rapidly","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Finance"}],[{"text":"Economics"}],[{"text":"Accounting"}]],"rows":[[[{"text":"Main concern"}],[{"text":"Managing money: raising, investing, returning funds"}],[{"text":"How society allocates scarce resources (micro and macro)"}],[{"text":"Recording, classifying and reporting transactions"}]],[[{"text":"Basis"}],[{"text":"Cash flows, time value of money, risk and return"}],[{"text":"Theory of demand, supply, prices, national income"}],[{"text":"Accrual basis (income when earned, expense when incurred)"}]],[[{"text":"Output"}],[{"text":"Decisions (invest, finance, pay dividends)"}],[{"text":"Theories and policies"}],[{"text":"Financial statements"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance is primarily concerned with "},{"text":"managing monetary resources and investments","bold":true},{"text":". If an option says workforce productivity, promoting goods, organisational hierarchy, product pricing or employee welfare, it belongs to human resources, marketing or management, not finance."}]},{"text":[{"text":"Studying finance helps you "},{"text":"optimise resource allocation decisions","bold":true},{"text":": putting scarce funds where they earn the best return for the risk taken. It also "},{"text":"enables informed strategic choices","bold":true},{"text":". Options claiming finance \"eliminates planning\", \"neglects risk\" or \"centres solely on profit\" are traps: finance needs planning, treats risk as central, and looks beyond profit to value."}]},{"text":[{"text":"The field of finance "},{"text":"includes investments and financial market dynamics","bold":true},{"text":". Watch for words like \"exclusively\", \"solely\" and \"purely\" (ledger keeping, promotion, manufacturing); they mark wrong options."}]},{"text":[{"text":"Finance and economics:","bold":true},{"text":" finance borrows from economics. Microeconomics gives the firm marginal analysis (go ahead only if extra benefit exceeds extra cost); macroeconomics gives the setting: interest rates, inflation and CBN monetary policy all shape a Nigerian firm's cost of funds."}]},{"text":[{"text":"Finance and accounting:","bold":true},{"text":" the accountant records that a sale of ₦2,000,000 on credit is revenue today; the finance person asks when the ₦2,000,000 cash will actually arrive, because a firm can show profit and still run out of cash. Accounting provides the data; finance uses it to decide."}]}]}]},{"number":"1.2","title":"Branches of finance and financial management","mustKnow":[{"type":"paragraph","text":[{"text":"Three categories of finance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal finance:","bold":true},{"text":" how an individual or household handles income, savings, spending, borrowing and investments (an individual's financial assets)."}]},{"text":[{"text":"Business (corporate) finance:","bold":true},{"text":" how a firm raises and uses funds; overseeing a firm's financial operations: raising capital, choosing investments, paying dividends."}]},{"text":[{"text":"Public finance:","bold":true},{"text":" how government raises revenue (taxes, borrowing) and spends it; administering public sector budgets and tax policy."}]}]},{"type":"paragraph","text":[{"text":"A fourth branch is often added:"}]},{"type":"list","ordered":true,"start":4,"items":[{"text":[{"text":"International finance:","bold":true},{"text":" financial dealings across borders: exchange rates, foreign trade and investment, global trade deals."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial management:","bold":true},{"text":" the management of the finances of individuals, business or government in order to achieve set objectives."}]},{"text":[{"text":"The focus of this course is "},{"text":"business (corporate) finance","bold":true},{"text":", so financial management is "},{"text":"the study of how firms make their investment and financing decisions","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the description to the branch. \"Managing individual savings accounts\" = personal. \"Directing corporate cash flows\" or \"overseeing a firm's financial operations\" = corporate. \"Administering public sector budgets\" or \"administering tax policies\" = public. \"Facilitating global trade deals\" = international."}]},{"text":[{"text":"Nigerian examples: a student saving pocket money in a bank account and buying treasury bills is personal finance; Dangote Cement raising funds on the Nigerian Exchange (NGX) is corporate finance; the Federal Government's annual budget and federal tax collection are public finance; a Nigerian importer paying a Chinese supplier in yuan is international finance."}]},{"text":[{"text":"Corporate finance for business funding","bold":true},{"text":" is a key area of finance; product design, staff development and consumer behaviour are not."}]}]}]},{"number":"1.3","title":"The finance function: the four decisions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance functions:","bold":true},{"text":" practices and activities focused on managing a business's financial resources to generate profits. They cover "},{"text":"investment, dividend, financing and liquidity","bold":true},{"text":" decisions, among others. They keep the firm financially stable and support growth and profitability."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment (capital budgeting) decision:","bold":true},{"text":" the allocation of the firm's capital funds to investment proposals that yield future benefits meeting the expectations of all investors, i.e. how much to invest in physical assets or financial assets (securities). Also called the "},{"text":"capital budgeting decision","bold":true},{"text":". Planning capital expenditure is an investment decision."}]},{"text":[{"text":"Financing decision:","bold":true},{"text":" determining the "},{"text":"best financing mix (capital structure)","bold":true},{"text":": sourcing funds at the "},{"text":"cheapest cost","bold":true},{"text":", with the "},{"text":"most favourable tax","bold":true},{"text":", at the "},{"text":"best mix","bold":true},{"text":", to "},{"text":"maximise the market price per share (MPS)","bold":true},{"text":". Also called the "},{"text":"capital mix decision","bold":true},{"text":"."}]},{"text":[{"text":"Dividend decision:","bold":true},{"text":" determining the proportion of earnings to "},{"text":"pay out as dividend","bold":true},{"text":" or "},{"text":"retain","bold":true},{"text":" in the firm, bearing in mind the need to maximise shareholders' (owners') wealth. Also called the "},{"text":"profit allocation decision","bold":true},{"text":"."}]},{"text":[{"text":"Liquidity decision:","bold":true},{"text":" the "},{"text":"working capital decision","bold":true},{"text":": managing current assets and current liabilities (cash, inventory, receivables, payables) so the firm can pay its way day to day."}]}]},{"type":"paragraph","text":[{"text":"Other finance functions:","bold":true},{"text":" managing cash flows, risk management, financial planning, financial analysis, financial control."}]},{"type":"paragraph","text":[{"text":"Key terms:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital budgeting:","bold":true},{"text":" making "},{"text":"long-term investment decisions","bold":true},{"text":" (new machinery, a new factory) that bring returns over many years."}]},{"text":[{"text":"Capital budgeting techniques:","bold":true},{"text":" net present value (NPV), "},{"text":"internal rate of return (IRR)","bold":true},{"text":", payback period, accounting rate of return (ARR), profitability index."}]},{"text":[{"text":"Internal rate of return (IRR):","bold":true},{"text":" the discount rate at which a project's NPV equals zero. Accept the project if IRR is greater than the cost of capital."}]},{"text":[{"text":"Cost of capital:","bold":true},{"text":" the "},{"text":"cost of obtaining funds","bold":true},{"text":": the return a firm must pay suppliers of funds (interest to lenders, the return shareholders expect)."}]},{"text":[{"text":"Dividend:","bold":true},{"text":" a "},{"text":"portion of a company's profit distributed to shareholders","bold":true},{"text":"."}]},{"text":[{"text":"Retained earnings","bold":true},{"text":" = profit after tax − dividends paid."}]}]},{"type":"table","header":[[{"text":"Decision"}],[{"text":"Other name"}],[{"text":"Question it answers"}]],"rows":[[[{"text":"Investment"}],[{"text":"Capital budgeting"}],[{"text":"Where should funds go?"}]],[[{"text":"Financing"}],[{"text":"Capital mix (capital structure)"}],[{"text":"Where should funds come from?"}]],[[{"text":"Dividend"}],[{"text":"Profit allocation"}],[{"text":"How much profit to pay out or keep?"}]],[[{"text":"Liquidity"}],[{"text":"Working capital"}],[{"text":"Can we meet short-term obligations?"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap on names:","bold":true},{"text":" capital mix = financing; profit allocation = dividend; capital budgeting = investment. \"Capital project decision\" and \"capital rating decision\" are not the standard names. "},{"text":"Capital rationing","bold":true},{"text":" is only a special case within the investment decision (when funds are too few for all good projects), so it is not another name for any of the decisions."}]},{"text":[{"text":"Not finance functions:","bold":true},{"text":" "},{"text":"financial forensics","bold":true},{"text":" (investigating fraud, a specialist audit and legal activity) and an "},{"text":"acquisition decision","bold":true},{"text":" (a specific strategic choice). The three major managerial finance decisions of a limited liability company are investment, financing and dividend."}]},{"text":[{"text":"Ratios such as debt-to-equity and current ratio, and the cash conversion cycle, are "},{"text":"not","bold":true},{"text":" capital budgeting techniques. Managing daily expenses is working capital, not capital budgeting."}]}]},{"type":"paragraph","text":[{"text":"Worked example (dividend decision):","bold":true},{"text":" Ade Foods plc earns profit after tax of ₦50,000,000 and decides to pay out 40% as dividend."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Dividend paid = 40% × ₦50,000,000 = ₦20,000,000."}]},{"text":[{"text":"Retained = ₦50,000,000 − ₦20,000,000 = ₦30,000,000 (60%), available to finance new investment."}]}]},{"type":"paragraph","text":[{"text":"Worked example (cost of capital and IRR):","bold":true},{"text":" A project costs ₦1,000,000 today and returns a single ₦1,210,000 in two years. The firm's cost of capital is 8%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"NPV at 8% = 1,210,000 ÷ (1.08)^2 − 1,000,000 = 1,210,000 ÷ 1.1664 − 1,000,000 = ₦37,380 (to the nearest naira). Positive, so accept."}]},{"text":[{"text":"IRR: find r where 1,000,000 × (1 + r)^2 = 1,210,000. (1 + r)^2 = 1.21, so 1 + r = 1.1 and IRR = 10%."}]},{"text":[{"text":"IRR (10%) > cost of capital (8%), so accept. Both methods agree."}]}]}]},{"number":"1.4","title":"The financial manager; planning and control","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial manager:","bold":true},{"text":" the finance employee who "},{"text":"manages the funds of an organisation","bold":true},{"text":" and undertakes financial management roles. The primary role is to "},{"text":"manage the firm's finances and maximise its value","bold":true},{"text":" (shareholders' wealth)."}]}]},{"type":"paragraph","text":[{"text":"Roles of the financial manager:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Estimating the funds needed (financial planning and forecasting)."}]},{"text":[{"text":"Raising funds from the best sources at the lowest cost (financing decision)."}]},{"text":[{"text":"Evaluating investment opportunities","bold":true},{"text":" and allocating funds (investment decision)."}]},{"text":[{"text":"Recommending dividend and retention policy (dividend decision)."}]},{"text":[{"text":"Managing working capital and cash flows (liquidity decision)."}]},{"text":[{"text":"Managing financial risk."}]},{"text":[{"text":"Financial analysis, reporting and control."}]},{"text":[{"text":"Dealing with banks, investors and the capital market."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial planning:","bold":true},{"text":" deciding in advance the firm's financial goals and how to reach them. Components: "},{"text":"defining monetary (financial) objectives","bold":true},{"text":", estimating funds needed, choosing sources, budgeting, forecasting."}]},{"text":[{"text":"Financial control:","bold":true},{"text":" checking that actual results match the plan and correcting deviations."}]}]},{"type":"paragraph","text":[{"text":"Financial management as a tool for planning and control:","bold":true},{"text":" budgets turn plans into figures; actual results are measured and compared with budget; variances are investigated; corrective action is taken. This cycle is "},{"text":"plan → act → measure → compare → correct","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Principles for planning and control:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clear objectives:","bold":true},{"text":" plans start from defined financial goals."}]},{"text":[{"text":"Realistic forecasting:","bold":true},{"text":" based on reliable information."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" plans can be adjusted when conditions change."}]},{"text":[{"text":"Participation:","bold":true},{"text":" those who carry out the plan help set it."}]},{"text":[{"text":"Responsibility:","bold":true},{"text":" each budget item is assigned to a named manager."}]},{"text":[{"text":"Timely measurement and feedback:","bold":true},{"text":" results are reported quickly enough to act on."}]},{"text":[{"text":"Management by exception:","bold":true},{"text":" attention goes to significant variances."}]},{"text":[{"text":"Cost-benefit:","bold":true},{"text":" controls should cost less than the benefit they bring."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"financial analyst","bold":true},{"text":" studies and reports on financial data; a "},{"text":"financial planner","bold":true},{"text":" usually advises individuals; a "},{"text":"financial controller","bold":true},{"text":" mainly oversees accounting and reporting. The one who manages the organisation's funds and makes the finance decisions is the "},{"text":"financial manager","bold":true},{"text":"."}]},{"text":[{"text":"Recruiting staff, crafting product prototypes, analysing market demographics, ensuring customer satisfaction and preparing legal documents are not the financial manager's job."}]},{"text":[{"text":"Worked example (control):","bold":true},{"text":" A firm budgets ₦8,000,000 for transport in a year but spends ₦9,200,000. Variance = ₦9,200,000 − ₦8,000,000 = ₦1,200,000 adverse, i.e. 1,200,000 ÷ 8,000,000 × 100 = 15% over budget. Under management by exception, the manager investigates this large overspend (perhaps a fuel price rise) and corrects it."}]}]}]},{"number":"1.5","title":"The limited liability company and the nature and risks of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability company:","bold":true},{"text":" a business registered (in Nigeria with the Corporate Affairs Commission, CAC) as a separate legal person, owned by shareholders whose liability is "},{"text":"limited to the amount unpaid on their shares","bold":true},{"text":"."}]},{"text":[{"text":"Features:","bold":true},{"text":" separate legal entity; limited liability; perpetual succession (continues when owners die or sell); transferable shares; "},{"text":"ownership separate from control","bold":true},{"text":" (shareholders own, directors and managers run it); can raise large funds by issuing shares and debentures."}]},{"text":[{"text":"Private (Ltd)","bold":true},{"text":" cannot invite the public to buy its shares; "},{"text":"public (plc)","bold":true},{"text":" can, and may list on the NGX under SEC regulation."}]}]},{"type":"paragraph","text":[{"text":"Nature of finance:","bold":true},{"text":" finance is about money over "},{"text":"time","bold":true},{"text":" and under "},{"text":"risk","bold":true},{"text":". A naira today is worth more than a naira later, and future returns are uncertain, so every finance decision weighs "},{"text":"risk against return","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Risks of finance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business risk:","bold":true},{"text":" variability of operating profit from the nature of the business."}]},{"text":[{"text":"Financial risk:","bold":true},{"text":" extra risk from using debt; interest must be paid even in bad years."}]},{"text":[{"text":"Liquidity risk:","bold":true},{"text":" inability to meet short-term obligations."}]},{"text":[{"text":"Interest-rate and inflation risk:","bold":true},{"text":" rising rates raise the cost of funds; inflation erodes the value of returns."}]},{"text":[{"text":"Credit (default) risk:","bold":true},{"text":" customers or borrowers fail to pay."}]},{"text":[{"text":"Exchange-rate risk:","bold":true},{"text":" naira movements change the value of foreign payments and receipts."}]}]},{"type":"paragraph","text":[{"text":"Objectives of business firms (studied fully in Topic 2):","bold":true},{"text":" (A) profit maximisation (increased revenue with lower cost); (B) wealth maximisation (shareholders' wealth); (C) satisfaction (satisfied customers stay loyal, recommend and repeat purchase); (D) social responsibility; (E) increase in market share (to be market leader). Others: growth, improved productivity, diversification, technical leadership, a contented workforce, highest quality service to customers."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability is why people will buy shares in a company they do not run: the most a shareholder can lose is what he paid (or still owes) for his shares. If Kunle buys 10,000 shares at ₦5 fully paid (₦50,000) and the company fails owing ₦100,000,000, Kunle loses at most ₦50,000; creditors cannot take his house."}]},{"text":[{"text":"Separation of ownership and control means managers may not always act for shareholders; the financial manager's task of maximising value is meant to align the firm's decisions with the owners' wealth."}]},{"text":[{"text":"Worked example (financial risk):","bold":true},{"text":" Two firms each earn operating profit of ₦10,000,000. Firm A has no debt; Firm B pays interest of ₦6,000,000. If operating profit falls by 40% to ₦6,000,000, Firm A still has ₦6,000,000 before tax, while Firm B has ₦6,000,000 − ₦6,000,000 = ₦0. Debt magnifies the effect of a fall; that is financial risk."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance = management of money and money claims; inflows (sources) and outflows (uses) of funds."}]},{"text":[{"text":"Activities: saving, borrowing, lending, investing, budgeting, forecasting."}]},{"text":[{"text":"Importance: enhances growth, standard for measuring performance, links all activities, a new and fast-growing discipline."}]},{"text":[{"text":"Branches: personal, business (corporate), public, plus international."}]},{"text":[{"text":"Financial management = how firms make investment and financing decisions."}]},{"text":[{"text":"Four decisions: investment (capital budgeting), financing (capital mix), dividend (profit allocation), liquidity (working capital)."}]},{"text":[{"text":"Cost of capital = cost of obtaining funds; IRR = rate where NPV = 0, a capital budgeting technique; dividend = profit paid to shareholders."}]},{"text":[{"text":"Financial manager manages the organisation's funds to maximise value; financial forensics and acquisition decisions are not core finance functions."}]},{"text":[{"text":"Planning and control: plan, act, measure, compare, correct."}]},{"text":[{"text":"Limited liability company: separate legal entity, liability limited to unpaid shares, ownership separate from control."}]}]}],"theory":{"itemId":"b463c843-3c57-55e1-97b1-e602e2108f20","question":[{"type":"paragraph","text":[{"text":"Zenith Agro plc earns profit after tax of ₦80,000,000 and pays a dividend of 25%. (a) How much is retained? (b) Which finance decision is this, and what is its other name?"}]}]},"practice":[{"topic":"Overview of Finance","named":false}]}},{"itemId":"1f2e020f-ff48-513f-860a-5823772973b2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Objective of a Firm","body":"Profit maximisation and its criticisms; shareholders' wealth maximisation, NPV and why it is superior; the other objectives (satisfaction, social responsibility, survival, market share, growth and the rest); stakeholders; the agency problem and agency costs; the objectives of financial decisions.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Profit maximisation and its criticisms; shareholders' wealth maximisation, NPV and why it is superior; the other objectives (satisfaction, social responsibility, survival, market share, growth and the rest); stakeholders; the agency problem and agency costs; the objectives of financial decisions."}],"lessons":[{"number":"2.1","title":"Profit maximisation objective","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximisation:","bold":true},{"text":" the firm aims to make as much profit as possible by "},{"text":"maximising revenue","bold":true},{"text":" from the sale of its output while "},{"text":"minimising the cost","bold":true},{"text":" of producing that output (increased revenue with lower cost)."}]},{"text":[{"text":"It is regarded as the "},{"text":"primary (traditional) objective","bold":true},{"text":" of a firm. It was developed in the "},{"text":"early 19th century","bold":true},{"text":", when firms were mainly "},{"text":"sole proprietorships","bold":true},{"text":" and "},{"text":"self-financing","bold":true},{"text":" (owner and manager were the same person)."}]},{"text":[{"text":"Merit:","bold":true},{"text":" it is "},{"text":"very easy to measure","bold":true},{"text":". It requires the firm to be efficient in its use of resources and focuses its effort on making money."}]},{"text":[{"text":"Profit maximisation is the objective that has been "},{"text":"attacked by all and sundry","bold":true},{"text":", for these "},{"text":"5 reasons","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It does "},{"text":"not recognise the time value of money","bold":true},{"text":" (₦1 received today is treated the same as ₦1 received in five years)."}]},{"text":[{"text":"It does "},{"text":"not consider risk or uncertainty","bold":true},{"text":" of future earnings."}]},{"text":[{"text":"Profit has no clear definition:","bold":true},{"text":" it does not state whether it means profit before tax or after tax, short-term or long-term profit."}]},{"text":[{"text":"It does "},{"text":"not consider the quality aspect","bold":true},{"text":" of the firm's future activities."}]},{"text":[{"text":"It does "},{"text":"not give all participants or interest groups","bold":true},{"text":" (customers, creditors, shareholders, government, employees, competitors) a "},{"text":"satisfactory return","bold":true},{"text":" for their inputs or efforts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Because it ignores timing, profit maximisation "},{"text":"focuses on immediate (short-term) financial gains","bold":true},{"text":". A manager chasing this year's profit may cut anything whose benefit comes later."}]},{"text":[{"text":"What conflicts with profit maximisation?","bold":true},{"text":" Spending that raises cost today but pays off only later, such as "},{"text":"funding staff skill development (training)","bold":true},{"text":", research or community projects. By contrast, streamlining production, trimming operating expenses and broadening market reach all "},{"text":"support","bold":true},{"text":" profit maximisation, because they cut cost or raise sales."}]},{"text":[{"text":"Exam cue words: \""},{"text":"primary","bold":true},{"text":" objective of a business firm\" or \""},{"text":"main objective of a business","bold":true},{"text":"\" with profit among the options → "},{"text":"maximise profits for its owners","bold":true},{"text":". Contrast with Lesson 2.2: \"main goal of "},{"text":"financial management","bold":true},{"text":"\" → "},{"text":"maximise shareholder wealth","bold":true},{"text":"."}]},{"text":[{"text":"Trap: profit maximisation is easy to "},{"text":"measure","bold":true},{"text":"; its weakness is not measurement but timing, risk, vagueness, quality and fairness to other groups."}]}]}]},{"number":"2.2","title":"Shareholders' wealth maximisation objective","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shareholders' wealth maximisation (SWM):","bold":true},{"text":" widely accepted as the "},{"text":"best means of maximising the economic welfare of shareholders","bold":true},{"text":" of a firm. It is the "},{"text":"main goal of financial management","bold":true},{"text":": to "},{"text":"maximise shareholder wealth over time","bold":true},{"text":"."}]},{"text":[{"text":"It simply means "},{"text":"maximising the Net Present Value (NPV)","bold":true},{"text":" of a course of action."}]},{"text":[{"text":"NPV:","bold":true},{"text":" the difference between the "},{"text":"present value of the benefits","bold":true},{"text":" of an action and the "},{"text":"initial investment","bold":true},{"text":" required to achieve those benefits."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NPV = PV of future cash inflows − initial investment"}]},{"text":[{"text":"PV of a cash flow C received in year n = C / (1 + r)^n, where r is the required rate of return."}]},{"text":[{"text":"Accept actions with NPV > 0; they add to shareholders' wealth."}]}]}]},{"text":[{"text":"Shareholder wealth is represented by the market price per share","bold":true},{"text":" of the firm's ordinary (common) shares. So the financial objective of a firm is to "},{"text":"maximise the market value of its shares","bold":true},{"text":"."}]},{"text":[{"text":"Share value is set by the price at which the shares trade in the market place, such as the "},{"text":"Nigerian Exchange (NGX)","bold":true},{"text":" in Lagos."}]},{"text":[{"text":"The market price reflects the firm's managerial decisions: "},{"text":"investment, financing and dividend decisions","bold":true},{"text":"."}]},{"text":[{"text":"Maximising shareholder wealth means "},{"text":"enhancing share value and payouts","bold":true},{"text":" (rising share price plus dividends). It aligns with "},{"text":"building enduring (long-term) value","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Superiority of SWM over profit maximisation (8 points):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It "},{"text":"recognises the time value of money","bold":true},{"text":"."}]},{"text":[{"text":"It "},{"text":"considers the effect of risk","bold":true},{"text":" or uncertainty of future earnings."}]},{"text":[{"text":"It "},{"text":"balances short-term and long-term profit","bold":true},{"text":" in a way profit maximisation cannot."}]},{"text":[{"text":"It "},{"text":"considers the quality aspect","bold":true},{"text":" of the firm's future activities."}]},{"text":[{"text":"It gives "},{"text":"all participants or interest groups","bold":true},{"text":" a satisfactory return for their inputs or efforts."}]},{"text":[{"text":"It is a "},{"text":"yardstick for measuring the overall performance","bold":true},{"text":" of a firm; share performance on the stock market has a direct relationship with shareholder wealth."}]},{"text":[{"text":"It is the "},{"text":"best factor in wooing further investors","bold":true},{"text":" into a firm."}]},{"text":[{"text":"It provides "},{"text":"appropriate and operationally feasible criteria","bold":true},{"text":" for choosing between alternative courses of action."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Profit maximisation"}],[{"text":"Shareholders' wealth maximisation"}]],"rows":[[[{"text":"Time value of money"}],[{"text":"Ignored"}],[{"text":"Recognised (discounting, NPV)"}]],[[{"text":"Risk"}],[{"text":"Ignored"}],[{"text":"Considered"}]],[[{"text":"Time horizon"}],[{"text":"Short term, immediate gains"}],[{"text":"Long term, enduring value"}]],[[{"text":"Definition"}],[{"text":"Vague (before/after tax? short/long?)"}],[{"text":"Clear: market price per share"}]],[[{"text":"Shareholders' view"}],[{"text":"Not reflected"}],[{"text":"Reflected in the share price"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (why timing matters).","bold":true},{"text":" Discount rate 10%. Each project costs ₦1,000,000 now."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Project A pays ₦600,000 at the end of year 1 and ₦600,000 at the end of year 2. Total profit = ₦1,200,000 − ₦1,000,000 = ₦200,000."}]},{"text":[{"text":"Project B pays ₦200,000 in year 1 and ₦1,000,000 in year 2. Total profit = ₦200,000 as well."}]},{"text":[{"text":"Profit maximisation sees no difference. Now find the NPV."}]},{"text":[{"text":"A: 600,000 / 1.1 = ₦545,454.55; 600,000 / 1.1^2 = ₦495,867.77. PV = ₦1,041,322.31. NPV = 1,041,322.31 − 1,000,000 = "},{"text":"₦41,322.31","bold":true},{"text":"."}]},{"text":[{"text":"B: 200,000 / 1.1 = ₦181,818.18; 1,000,000 / 1.1^2 = ₦826,446.28. PV = ₦1,008,264.46. NPV = "},{"text":"₦8,264.46","bold":true},{"text":"."}]},{"text":[{"text":"A adds more wealth because its money arrives sooner. (Figures rounded to the nearest kobo.)"}]}]}]},{"text":[{"text":"Worked example (what wealth is).","bold":true},{"text":" You hold 2,000 shares in an NGX-listed bank. The price rises from ₦25 to ₦30 over the year and the bank pays a dividend of ₦2 per share. Gain in wealth = 2,000 × (30 − 25 + 2) = "},{"text":"₦14,000","bold":true},{"text":". Wealth comes from "},{"text":"share price and dividends","bold":true},{"text":", not from the firm's reported profit as such."}]},{"text":[{"text":"Traps:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shareholder wealth is the "},{"text":"market price","bold":true},{"text":" per share, "},{"text":"not","bold":true},{"text":" book value (assets less liabilities at historical cost), the number of employees or salaries paid."}]},{"text":[{"text":"\"Which is "},{"text":"not","bold":true},{"text":" a reason SWM is superior?\" Look for the option that "},{"text":"reverses","bold":true},{"text":" a true point: \"wealth maximisation does "},{"text":"not","bold":true},{"text":" consider the timing of returns while profit maximisation does\" is false, so it is the answer. Likewise \"recognition of the prospects of a firm "},{"text":"in the short run","bold":true},{"text":"\" is not a reason; SWM is about the "},{"text":"long run","bold":true},{"text":"."}]},{"text":[{"text":"Genuine reasons include: explicit consideration of risk, consideration of the time value of money, recognition of shareholders' perception of returns from investment (through the share price), and long-term prospects."}]},{"text":[{"text":"\"Most appropriate objective of a business organisation\" → "},{"text":"maximise shareholder wealth","bold":true},{"text":". Long-term earnings growth ignores risk; efficient use of resources and minimising input costs are means, not the goal."}]}]}]}]}]},{"number":"2.3","title":"Other objectives of a firm","mustKnow":[{"type":"paragraph","text":[{"text":"The "},{"text":"6 objectives","bold":true},{"text":" of a business firm:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Profit maximisation","bold":true},{"text":" (Lesson 2.1)."}]},{"text":[{"text":"Shareholders' wealth maximisation","bold":true},{"text":" (Lesson 2.2)."}]},{"text":[{"text":"Satisfaction objective:","bold":true},{"text":" giving "},{"text":"all participants (stakeholders) a satisfactory return","bold":true},{"text":" for their inputs or efforts: customers, shareholders, government, employees, competitors and creditors. Satisfying these interest groups makes a modern firm grow or remain afloat. Satisfied customers stay loyal, recommend the firm and bring repeat business."}]},{"text":[{"text":"Social responsibility objective:","bold":true},{"text":" firms not only make money but also "},{"text":"improve the environment","bold":true},{"text":" they operate in through "},{"text":"community development","bold":true},{"text":": rural electrification, pipe-borne water, good roads, hospitals, scholarships and jobs for indigenes. This objective "},{"text":"enhances a good business environment","bold":true},{"text":"."}]},{"text":[{"text":"Survival objective:","bold":true},{"text":" "},{"text":"staying in business continuously","bold":true},{"text":" rather than making profit this year and packing up next year. In an economic downturn it is the "},{"text":"most important","bold":true},{"text":" objective; keen competition and high inflation in Nigeria make it crucial."}]},{"text":[{"text":"Increase in market share objective:","bold":true},{"text":" "},{"text":"capturing more of the market demand","bold":true},{"text":" for the firm's products or services in the industry, so as to maintain a "},{"text":"leadership position","bold":true},{"text":" (be a market leader)."}]}]},{"type":"paragraph","text":[{"text":"Other objectives of business firms (6):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To seek "},{"text":"growth","bold":true},{"text":" of the firm."}]},{"text":[{"text":"To improve "},{"text":"productivity","bold":true},{"text":"."}]},{"text":[{"text":"To seek "},{"text":"diversification","bold":true},{"text":"."}]},{"text":[{"text":"To be a "},{"text":"technical leader","bold":true},{"text":" in their field."}]},{"text":[{"text":"To maintain a "},{"text":"contented workforce","bold":true},{"text":"."}]},{"text":[{"text":"To give the "},{"text":"highest quality services","bold":true},{"text":" to customers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Satisficing:","bold":true},{"text":" aiming for results that are \"good enough\" for every group rather than the maximum for one group. Managers balance owners, workers, lenders, suppliers and government. This is the same idea as the satisfaction objective."}]},{"text":[{"text":"Sales (revenue) maximisation:","bold":true},{"text":" managers may push sales volume, since their status and pay often rise with the size of the firm, even when profit does not rise as fast."}]},{"text":[{"text":"Growth:","bold":true},{"text":" getting bigger, for example by "},{"text":"entering untapped markets","bold":true},{"text":", launching products or adding capacity. "},{"text":"Expanding market presence","bold":true},{"text":" is a "},{"text":"long-term","bold":true},{"text":" objective; covering daily operating costs and hiring short-term workers are short-run matters."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" "},{"text":"ensuring cash for short-term needs","bold":true},{"text":" (wages, supplier bills) as they fall due."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" "},{"text":"lowering costs and boosting output","bold":true},{"text":"."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" leads to "},{"text":"greater market penetration","bold":true},{"text":" and also "},{"text":"higher short-term expenses","bold":true},{"text":" (research and development), so \"both\" is the answer when both appear."}]},{"text":[{"text":"Ethical objective:","bold":true},{"text":" "},{"text":"adhering to equitable (fair) practices","bold":true},{"text":", obeying the law and being transparent."}]},{"text":[{"text":"Secondary objectives:","bold":true},{"text":" beside profit or wealth, a firm may pursue "},{"text":"corporate social responsibility","bold":true},{"text":" initiatives. A "},{"text":"social objective","bold":true},{"text":" is one like "},{"text":"enhancing community welfare","bold":true},{"text":"; boosting margins is a profit objective, not a social one."}]},{"text":[{"text":"Economic vs social objectives:","bold":true},{"text":" economic analysis of a firm looks at commercial performance: "},{"text":"sales growth, market share, profits and return on investment","bold":true},{"text":". "},{"text":"Conservation of natural resources","bold":true},{"text":" is a social or environmental concern, "},{"text":"not","bold":true},{"text":" an economic analysis."}]},{"text":[{"text":"Matching cues: \"good business environment\" → social responsibility; \"staying afloat in a downturn\" → survival; \"satisfactory returns to all for their inputs\" → satisfaction; \"capturing more market demand\" → increase in market share."}]}]}]},{"number":"2.4","title":"Stakeholders, the agency problem and objectives of financial decisions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stakeholders (interest groups):","bold":true},{"text":" everyone with an interest in the firm: "},{"text":"shareholders, employees, customers, creditors (lenders, suppliers), government, competitors, management","bold":true},{"text":" and the "},{"text":"community","bold":true},{"text":"."}]},{"text":[{"text":"Agency relationship:","bold":true},{"text":" shareholders ("},{"text":"principals","bold":true},{"text":") appoint managers ("},{"text":"agents","bold":true},{"text":") to run the firm for them. This separation of ownership from control comes with the limited liability company."}]},{"text":[{"text":"Agency problem:","bold":true},{"text":" the conflict that arises when managers pursue "},{"text":"their own interests","bold":true},{"text":" (high pay, perks, job security, a bigger firm) instead of maximising shareholders' wealth."}]},{"text":[{"text":"Agency costs:","bold":true},{"text":" costs borne by shareholders to reduce or live with the agency problem:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Monitoring costs:","bold":true},{"text":" external audit, board oversight, reports."}]},{"text":[{"text":"Bonding and incentive costs:","bold":true},{"text":" costs of tying managers to owners' interests, such as contractual guarantees, bonuses, share options and performance-linked pay."}]},{"text":[{"text":"Residual loss:","bold":true},{"text":" value still lost because managers' and owners' interests are never perfectly aligned."}]}]}]},{"text":[{"text":"Objectives of financial decisions","bold":true},{"text":" (all aim to maximise the "},{"text":"market price per share","bold":true},{"text":"):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment decision:","bold":true},{"text":" allocate capital to proposals that yield future benefits (positive NPV) meeting investors' expectations."}]},{"text":[{"text":"Financing decision:","bold":true},{"text":" find the best financing mix (capital structure): funds at the "},{"text":"cheapest cost","bold":true},{"text":", most favourable tax, best mix."}]},{"text":[{"text":"Dividend decision:","bold":true},{"text":" the proportion of earnings to "},{"text":"pay out","bold":true},{"text":" or "},{"text":"retain","bold":true},{"text":", bearing in mind shareholders' wealth."}]},{"text":[{"text":"Liquidity (working capital) decision:","bold":true},{"text":" keep enough liquid resources for day-to-day needs."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Signs of the agency problem:","bold":true},{"text":" lavish offices and cars, empire building (growth for its own sake), avoiding good but risky projects to protect jobs, short-termism to hit bonus targets."}]},{"text":[{"text":"Ways to reduce it:","bold":true},{"text":" performance-linked pay and share options; independent non-executive directors; shareholders' votes at the "},{"text":"annual general meeting (AGM)","bold":true},{"text":"; the threat of takeover; the market for managers; and corporate governance rules. In Nigeria, listed firms follow the "},{"text":"Nigerian Code of Corporate Governance 2018","bold":true},{"text":" (issued by the Financial Reporting Council of Nigeria) and "},{"text":"SEC","bold":true},{"text":" rules for public companies."}]},{"text":[{"text":"A second agency conflict exists between "},{"text":"shareholders and creditors","bold":true},{"text":": owners may push managers into very risky projects funded by lenders' money. Lenders protect themselves with loan covenants."}]},{"text":[{"text":"Stakeholder interests can clash: higher wages please employees but cut dividends. SWM, done properly over the long run, still requires treating customers, staff and the community fairly, which is why it is said to give all groups a satisfactory return."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximisation: maximise revenue, minimise cost; the primary, traditional objective from the early 19th century; easy to measure."}]},{"text":[{"text":"It is attacked by all and sundry: ignores time value of money, ignores risk, profit is undefined, ignores quality, unfair to other interest groups."}]},{"text":[{"text":"SWM = maximise NPV = maximise the market price per share; the main goal of financial management."}]},{"text":[{"text":"NPV = PV of benefits − initial investment; PV = C / (1 + r)^n."}]},{"text":[{"text":"SWM is superior on 8 counts: time value, risk, short/long balance, quality, all groups, yardstick, wooing investors, feasible criteria."}]},{"text":[{"text":"Other objectives: satisfaction, social responsibility (good business environment), survival (most important in a downturn), market share (market leader)."}]},{"text":[{"text":"Also: growth, productivity, diversification, technical leadership, contented workforce, highest quality service; liquidity, efficiency, innovation, ethics."}]},{"text":[{"text":"Agency problem: managers (agents) vs shareholders (principals); agency costs = monitoring, bonding, residual loss."}]},{"text":[{"text":"Investment, financing, dividend and liquidity decisions all aim to maximise market price per share."}]}]}],"theory":{"itemId":"1df01bce-1f01-5a69-a6a6-1c45816fa063","question":[{"type":"paragraph","text":[{"text":"A firm can invest ₦700,000 today in a project that returns ₦300,000 at the end of each of the next 3 years. The required return is 10%. (a) What is the accounting profit? (b) What is the NPV? (c) Does the project increase shareholders' wealth?"}]}]},"practice":[{"topic":"Objectives of a Business Firm","named":false}]}},{"itemId":"05c43d68-0057-5441-bafb-52f92863e0ee","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"Analysis of Risk in Financial Decisions","body":"Risk vs uncertainty; the types of risk; the probability method (expected value, variance, standard deviation, coefficient of variation) and the non-probability methods; choosing between securities for a risk-averse or risk-taking investor; the risk-return trade-off; diversification and risk management.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"Risk vs uncertainty; the types of risk; the probability method (expected value, variance, standard deviation, coefficient of variation) and the non-probability methods; choosing between securities for a risk-averse or risk-taking investor; the risk-return trade-off; diversification and risk management."}],"lessons":[{"number":"3.1","title":"Risk, uncertainty and the risk-return trade-off","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk:","bold":true},{"text":" the situation in which the future outcome is unknown but the likelihood of its occurrence can be estimated or determined. In other words, the "},{"text":"probability","bold":true},{"text":" of future occurrence "},{"text":"can","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" the situation in which the future outcome is unknown and the likelihood of its occurrence "},{"text":"cannot","bold":true},{"text":" be estimated or determined. The probability "},{"text":"cannot","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Risk in finance:","bold":true},{"text":" uncertainty in expected returns; the chance that the actual return differs from the expected return."}]},{"text":[{"text":"Risk-return trade-off:","bold":true},{"text":" higher risk offers higher potential reward; investors take on more risk only if they expect a higher return. A financial manager must balance "},{"text":"risk exposure and potential returns","bold":true},{"text":"."}]},{"text":[{"text":"Risk premium:","bold":true},{"text":" the extra return investors demand, above the risk-free rate, for accepting risk."}]}]},{"type":"table","header":[[],[{"text":"Risk"}],[{"text":"Uncertainty"}]],"rows":[[[{"text":"Outcome known?"}],[{"text":"No"}],[{"text":"No"}]],[[{"text":"Probability can be estimated?"}],[{"text":"Yes","bold":true}],[{"text":"No","bold":true}]],[[{"text":"Can be measured with EV, SD, CV?"}],[{"text":"Yes"}],[{"text":"No"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The difference is only about the "},{"text":"probability","bold":true},{"text":". In both cases you do not know the outcome. If an option says \"the outcome is known\", it describes certainty, not risk."}]},{"text":[{"text":"A Federal Government of Nigeria treasury bill issued through the CBN is treated as almost risk-free. A share on the NGX is risky, so investors expect a higher return on it. If treasury bills pay 18% and an investor wants 25% from a share, the risk premium is 25% − 18% = 7%."}]},{"text":[{"text":"Traps: \"greater risk yields lower gains\" reverses the trade-off; \"minimal risk ensures big returns\" is false. Risk and return are "},{"text":"connected","bold":true},{"text":", not disconnected."}]}]}]},{"number":"3.2","title":"Types of risk","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business risk:","bold":true},{"text":" concerned with the future uncertainty about a company's operating prospects (sales, costs, profits), even with no debt."}]},{"text":[{"text":"Financial risk:","bold":true},{"text":" concerned with the introduction of "},{"text":"debt","bold":true},{"text":" into a company's capital structure."}]},{"text":[{"text":"Economic risk:","bold":true},{"text":" the risk an organisation faces due to shifts in macroeconomic variables or forces."}]},{"text":[{"text":"Interest rate risk:","bold":true},{"text":" the exposure of a bank's current or future earnings and capital to adverse changes in market rates. It mainly affects "},{"text":"fixed-income assets","bold":true},{"text":" (bonds): when rates rise, bond prices fall."}]},{"text":[{"text":"Market risk:","bold":true},{"text":" the potential for losses arising from factors influencing the overall performance of financial markets. Also called "},{"text":"systematic risk","bold":true},{"text":"."}]},{"text":[{"text":"Liquidity risk:","bold":true},{"text":" the risk of loss from the inability to meet payment obligations in full and on time when they become due; also, difficulty turning assets into cash quickly without losing value."}]}]},{"type":"paragraph","text":[{"text":"Other types you must also know:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit (default) risk:","bold":true},{"text":" a borrower fails to repay a loan or interest."}]},{"text":[{"text":"Inflation (purchasing power) risk:","bold":true},{"text":" inflation reduces the purchasing power of returns."}]},{"text":[{"text":"Exchange-rate risk:","bold":true},{"text":" losses from changes in exchange rates on foreign dealings."}]},{"text":[{"text":"Operational risk:","bold":true},{"text":" loss from internal failures (human error, technology breakdown)."}]},{"text":[{"text":"Reinvestment risk:","bold":true},{"text":" cash flows must be reinvested at a lower rate."}]},{"text":[{"text":"Systemic risk:","bold":true},{"text":" collapse of an entire market or financial system."}]}]},{"type":"table","header":[[],[{"text":"Systematic (market) risk"}],[{"text":"Unsystematic risk"}]],"rows":[[[{"text":"Affects"}],[{"text":"All firms, the whole market"}],[{"text":"One firm or one sector"}]],[[{"text":"Causes"}],[{"text":"Recession, inflation, interest rate changes"}],[{"text":"Poor leadership, strike, defective product"}]],[[{"text":"Removed by diversification?"}],[{"text":"No","bold":true},{"text":" (non-diversifiable)"}],[{"text":"Yes","bold":true},{"text":" (diversifiable)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business risk vs financial risk: a debt-free firm still has business risk. Once it borrows, the fixed interest must be paid whatever happens, which adds financial risk."}]},{"text":[{"text":"A market-wide economic downturn, a CBN rise in the monetary policy rate or high inflation hits nearly every firm: systematic. A strike at one company is unsystematic."}]},{"text":[{"text":"Naira depreciation hurts a Lagos importer paying suppliers in dollars: exchange-rate risk."}]},{"text":[{"text":"Do not confuse "},{"text":"systematic","bold":true},{"text":" (market-wide) with "},{"text":"systemic","bold":true},{"text":" (the whole system collapsing). Market risk is never \"diversifiable\" or \"firm-specific\"."}]}]}]},{"number":"3.3","title":"Measuring risk: the probability method","mustKnow":[{"type":"paragraph","text":[{"text":"2 ways of treating risk:","bold":true},{"text":" (1) probability method, (2) non-probability method."}]},{"type":"paragraph","text":[{"text":"Probability method (4 measures):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Expected return (mean, expected value)"}]},{"text":[{"text":"Variance"}]},{"text":[{"text":"Standard deviation"}]},{"text":[{"text":"Coefficient of variation"}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true},{"text":" (P = probability, R = return or cash flow):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expected return: ER = Σ (P × R)"}]},{"text":[{"text":"Variance = Σ P × (R − ER)^2"}]},{"text":[{"text":"Standard deviation (SD) = square root of variance"}]},{"text":[{"text":"Coefficient of variation (CV) = SD / ER × 100 (in %)"}]},{"text":[{"text":"Check: the probabilities must add up to 1. The returns with their probabilities form a "},{"text":"probability distribution","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Decision rules:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The higher the variance, SD and CV, the higher the risk, and vice versa."}]},{"text":[{"text":"Risk-averse","bold":true},{"text":" investor: selects the security with the "},{"text":"lowest","bold":true},{"text":" risk (variance, SD or CV)."}]},{"text":[{"text":"Risk-taker (risk-seeking)","bold":true},{"text":" investor: selects the security with the "},{"text":"highest","bold":true},{"text":" risk."}]},{"text":[{"text":"Risk-neutral","bold":true},{"text":" investor: ignores risk and looks only at expected return."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" James is considering two securities."}]},{"type":"paragraph","text":[{"text":"Security A: ₦4,000 (0.4), ₦5,000 (0.5), ₦6,000 (0.1)."}]},{"type":"paragraph","text":[{"text":"Security B: ₦6,000 (0.7), ₦4,000 (0.2), ₦3,000 (0.1)."}]},{"type":"paragraph","text":[{"text":"Step 1: P × R, summed, gives ER. Step 2: subtract ER from each return. Step 3: square and multiply by P, summed, gives the variance.","italic":true}]},{"type":"paragraph","text":[{"text":"Security A","bold":true}]},{"type":"table","header":[[{"text":"Return (R)"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"(R − ER)^2"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"4,000"}],[{"text":"0.4"}],[{"text":"1,600"}],[{"text":"−700"}],[{"text":"490,000"}],[{"text":"196,000"}]],[[{"text":"5,000"}],[{"text":"0.5"}],[{"text":"2,500"}],[{"text":"300"}],[{"text":"90,000"}],[{"text":"45,000"}]],[[{"text":"6,000"}],[{"text":"0.1"}],[{"text":"600"}],[{"text":"1,300"}],[{"text":"1,690,000"}],[{"text":"169,000"}]],[[{"text":"Total"}],[{"text":"1.0"}],[{"text":"ER = 4,700","bold":true}],[],[],[{"text":"Variance = 410,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SD = square root of 410,000 = ₦640.31 (₦640 to the nearest naira)"}]},{"text":[{"text":"CV = 640.31 / 4,700 × 100 = 13.62%, about "},{"text":"14%","bold":true}]}]},{"type":"paragraph","text":[{"text":"Security B","bold":true}]},{"type":"table","header":[[{"text":"Return (R)"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"(R − ER)^2"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"6,000"}],[{"text":"0.7"}],[{"text":"4,200"}],[{"text":"700"}],[{"text":"490,000"}],[{"text":"343,000"}]],[[{"text":"4,000"}],[{"text":"0.2"}],[{"text":"800"}],[{"text":"−1,300"}],[{"text":"1,690,000"}],[{"text":"338,000"}]],[[{"text":"3,000"}],[{"text":"0.1"}],[{"text":"300"}],[{"text":"−2,300"}],[{"text":"5,290,000"}],[{"text":"529,000"}]],[[{"text":"Total"}],[{"text":"1.0"}],[{"text":"ER = 5,300","bold":true}],[],[],[{"text":"Variance = 1,210,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SD = square root of 1,210,000 = ₦1,100"}]},{"text":[{"text":"CV = 1,100 / 5,300 × 100 = 20.75%, about "},{"text":"21%","bold":true}]}]},{"type":"paragraph","text":[{"text":"Recommendation:","bold":true},{"text":" James is risk averse, so recommend "},{"text":"Security A","bold":true},{"text":": its variance, SD and CV are all lower than B's (lower risk)."}]},{"type":"paragraph","text":[{"text":"Shortcut check for the variance:","bold":true},{"text":" Variance = Σ (P × R^2) − ER^2. For A: 0.4(16,000,000) + 0.5(25,000,000) + 0.1(36,000,000) = 22,500,000; 22,500,000 − 4,700^2 = 22,500,000 − 22,090,000 = 410,000. Same answer."}]},{"type":"paragraph","text":[{"text":"Traps:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Variance is in squared units and is huge (e.g. 44,000,000); SD is its square root (e.g. 6,633.25). Options often place both side by side. Read which one is asked."}]},{"text":[{"text":"Options also list the separate terms of a sum (e.g. 15,000, 18,000, 28,000) as distractors. Always add the whole column."}]},{"text":[{"text":"\"Nearest whole percent\": "},{"text":"round","bold":true},{"text":", do not cut off. 13.7% becomes 14%, not 13%. Keep SD to 2 decimal places before dividing."}]},{"text":[{"text":"\"Expected value\", \"expected return\", \"mean\" and \"expected cash flow\" all mean ER."}]}]}]},{"number":"3.4","title":"Comparing securities and the coefficient of variation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CV = risk per naira of expected return.","bold":true},{"text":" When expected returns differ, the CV is the fairest comparison."}]},{"text":[{"text":"If SD and CV point to different securities, a risk-averse investor goes by the "},{"text":"lowest CV","bold":true},{"text":"."}]},{"text":[{"text":"Reversing the order of the probabilities on equally spaced returns changes ER and CV but leaves variance and SD "},{"text":"unchanged","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1: a risk taker.","bold":true},{"text":" Willy is a risk taker."}]},{"type":"paragraph","text":[{"text":"Security X: ₦5,000 (0.1), ₦6,000 (0.3), ₦7,000 (0.6)."}]},{"type":"paragraph","text":[{"text":"Security Y: ₦8,000 (0.2), ₦7,000 (0.4), ₦6,000 (0.4)."}]},{"type":"table","header":[[{"text":"Security X"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"5,000"}],[{"text":"0.1"}],[{"text":"500"}],[{"text":"−1,500"}],[{"text":"225,000"}]],[[{"text":"6,000"}],[{"text":"0.3"}],[{"text":"1,800"}],[{"text":"−500"}],[{"text":"75,000"}]],[[{"text":"7,000"}],[{"text":"0.6"}],[{"text":"4,200"}],[{"text":"500"}],[{"text":"150,000"}]],[[{"text":"Total"}],[],[{"text":"6,500","bold":true}],[],[{"text":"450,000","bold":true}]]]},{"type":"table","header":[[{"text":"Security Y"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"8,000"}],[{"text":"0.2"}],[{"text":"1,600"}],[{"text":"1,200"}],[{"text":"288,000"}]],[[{"text":"7,000"}],[{"text":"0.4"}],[{"text":"2,800"}],[{"text":"200"}],[{"text":"16,000"}]],[[{"text":"6,000"}],[{"text":"0.4"}],[{"text":"2,400"}],[{"text":"−800"}],[{"text":"256,000"}]],[[{"text":"Total"}],[],[{"text":"6,800","bold":true}],[],[{"text":"560,000","bold":true}]]]},{"type":"table","header":[[],[{"text":"ER"}],[{"text":"Variance"}],[{"text":"SD"}],[{"text":"CV"}]],"rows":[[[{"text":"X"}],[{"text":"₦6,500"}],[{"text":"450,000"}],[{"text":"₦670.82"}],[{"text":"10.32% (about 10%)"}]],[[{"text":"Y"}],[{"text":"₦6,800"}],[{"text":"560,000"}],[{"text":"₦748.33"}],[{"text":"11.01% (about 11%)"}]]]},{"type":"paragraph","text":[{"text":"Willy is a risk taker, so recommend "},{"text":"Security Y","bold":true},{"text":": its variance, SD and CV are the highest."}]},{"type":"paragraph","text":[{"text":"Worked example 2: SD and CV disagree.","bold":true},{"text":" Security P has ER ₦10,000 and SD ₦1,500. Security Q has ER ₦40,000 and SD ₦4,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CV of P = 1,500 / 10,000 × 100 = 15%"}]},{"text":[{"text":"CV of Q = 4,000 / 40,000 × 100 = 10%"}]}]},{"type":"paragraph","text":[{"text":"Q has the larger SD but carries less risk per naira, so a risk-averse investor chooses "},{"text":"Q","bold":true},{"text":" (lowest CV). The same thing happens with three or four securities: compute the CV of each and pick the lowest. A four-outcome table is worked exactly like a three-outcome table, with one more row."}]},{"type":"paragraph","text":[{"text":"Worked example 3: reversed probabilities.","bold":true},{"text":" Returns ₦10,000, ₦20,000, ₦30,000."}]},{"type":"table","header":[[{"text":"Probabilities"}],[{"text":"ER"}],[{"text":"Variance"}],[{"text":"SD"}],[{"text":"CV"}]],"rows":[[[{"text":"0.2, 0.3, 0.5"}],[{"text":"₦23,000"}],[{"text":"61,000,000"}],[{"text":"₦7,810.25"}],[{"text":"33.96% (about 34%)"}]],[[{"text":"0.5, 0.3, 0.2"}],[{"text":"₦17,000"}],[{"text":"61,000,000"}],[{"text":"₦7,810.25"}],[{"text":"45.94% (about 46%)"}]]]},{"type":"paragraph","text":[{"text":"The spread is a mirror image, so variance and SD are identical, but ER moves, so CV changes. Do not reuse a CV from one version for the other."}]}]},{"number":"3.5","title":"Non-probability methods, diversification and risk management","mustKnow":[{"type":"paragraph","text":[{"text":"Non-probability methods (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sensitivity analysis"}]},{"text":[{"text":"Payback period"}]},{"text":[{"text":"Risk-adjusted method (risk-adjusted discount rate)"}]},{"text":[{"text":"Certainty equivalent factor"}]},{"text":[{"text":"Simulation"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Portfolio:","bold":true},{"text":" a combination (collection) of financial investments, such as shares and bonds, held by one investor."}]},{"text":[{"text":"Diversification:","bold":true},{"text":" spreading investments across different assets or industries to reduce risk. It reduces "},{"text":"unsystematic","bold":true},{"text":" risk only."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying, assessing and reducing (or controlling) risks. It never eliminates all uncertainty."}]}]},{"type":"paragraph","text":[{"text":"6 steps in risk analysis:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify risks (brainstorming, expert consultation, checklists)"}]},{"text":[{"text":"Measure risks (sensitivity analysis, scenario analysis, Monte Carlo simulation)"}]},{"text":[{"text":"Assess risk tolerance"}]},{"text":[{"text":"Evaluate the risk-return trade-off (metrics such as risk-adjusted return, e.g. the Sharpe ratio, plus NPV and IRR)"}]},{"text":[{"text":"Develop risk mitigation strategies"}]},{"text":[{"text":"Monitor and review risks"}]}]},{"type":"paragraph","text":[{"text":"Mitigation strategies:","bold":true},{"text":" "},{"text":"hedging","bold":true},{"text":" (with derivatives such as options, futures, forwards), "},{"text":"diversification","bold":true},{"text":", "},{"text":"insurance","bold":true},{"text":" (transferring risk to an insurer). Risk can be reduced, transferred or managed."}]},{"type":"paragraph","text":[{"text":"Other tools:","bold":true},{"text":" ratio analysis (debt-to-equity, interest cover), Value at Risk (VaR), scenario and sensitivity analysis, risk mapping (heat maps), Monte Carlo simulation, stress testing."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sensitivity analysis","bold":true},{"text":" tests how changes in one key variable (say, selling price) affect the outcome; "},{"text":"scenario analysis","bold":true},{"text":" changes several at once (best, likely, worst case); "},{"text":"simulation","bold":true},{"text":" (Monte Carlo) uses computer models and probability distributions to generate many possible outcomes."}]},{"text":[{"text":"Payback period","bold":true},{"text":" treats risk by preferring projects that return their cost faster. "},{"text":"Certainty equivalent","bold":true},{"text":" converts risky cash flows into the certain amounts the investor would accept instead. "},{"text":"Risk-adjusted discount rate","bold":true},{"text":" adds a risk premium to the discount rate for riskier projects."}]},{"text":[{"text":"VaR","bold":true},{"text":" measures the possible loss in value of an investment over a period under normal conditions. "},{"text":"Stress testing","bold":true},{"text":" simulates extreme conditions. A "},{"text":"heat map","bold":true},{"text":" plots risks by probability and impact."}]},{"text":[{"text":"Diversification in practice: an investor holding only one bank's shares on the NGX loses heavily if that bank has a fraud scandal. Holding bank, telecom, consumer goods and oil shares plus treasury bills means one loss can be offset by gains elsewhere. A recession still hurts all of them: systematic risk remains."}]},{"text":[{"text":"Traps: concentrating funds in one asset, raising debt (leverage) and narrowing the investment scope "},{"text":"increase","bold":true},{"text":" risk. Avoiding all investments is not risk management; it gives up return."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk: outcome unknown, probability "},{"text":"can","bold":true},{"text":" be estimated. Uncertainty: probability "},{"text":"cannot","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Business risk = operating prospects; financial risk = debt in the capital structure; market risk = systematic risk."}]},{"text":[{"text":"Probability method: ER = Σ(P × R); variance = Σ P(R − ER)^2; SD = square root of variance; CV = SD / ER × 100."}]},{"text":[{"text":"Higher variance, SD, CV = higher risk. Risk averse picks the lowest; risk taker picks the highest; use CV when expected returns differ."}]},{"text":[{"text":"Round CV to the nearest percent; never mix up variance (huge) and SD (its square root)."}]},{"text":[{"text":"Non-probability methods: sensitivity analysis, payback period, risk-adjusted method, certainty equivalent, simulation."}]},{"text":[{"text":"Higher risk, higher potential return; the risk premium is the extra return for bearing risk."}]},{"text":[{"text":"Diversification removes unsystematic risk only; hedging, diversification and insurance manage risk."}]}]}],"theory":{"itemId":"8d2a2b51-0d6b-55e6-8a93-ea787c2b13d8","question":[{"type":"paragraph","text":[{"text":"A project's cash flows and probabilities are ₦10,000 (0.2), ₦15,000 (0.3), ₦20,000 (0.4) and ₦30,000 (0.1). Calculate the expected value, variance, standard deviation and coefficient of variation."}]}]},"practice":[{"topic":"Analysis of Risk in Financial Decisions","named":false}]}},{"itemId":"1ce084b9-4f97-5cc2-8271-1e50075f3483","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Foundation of Financial Mathematics","body":"Time value of money; simple and compound interest; future and present value of a lump sum (including intra-year and continuous compounding); effective vs nominal rates; solving for time and rate; annuities (ordinary, due, deferred), perpetuities, sinking funds and loan amortisation; arithmetic and geometric progressions; investment, consumption and exchange.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"Time value of money; simple and compound interest; future and present value of a lump sum (including intra-year and continuous compounding); effective vs nominal rates; solving for time and rate; annuities (ordinary, due, deferred), perpetuities, sinking funds and loan amortisation; arithmetic and geometric progressions; investment, consumption and exchange."}],"lessons":[{"number":"4.1","title":"Time value of money, simple and compound interest","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time value of money (TVM):","bold":true},{"text":" money has different values at different times. A naira today is worth "},{"text":"more","bold":true},{"text":" than a naira tomorrow (present funds outvalue future funds). TVM is a fundamental concept in "},{"text":"finance and investment decisions","bold":true},{"text":", because the "},{"text":"timing","bold":true},{"text":" of cash flows affects which choice is best. Its key components are "},{"text":"future value","bold":true},{"text":" and "},{"text":"present value","bold":true},{"text":"."}]},{"text":[{"text":"Interest:","bold":true},{"text":" the payment made for the use of money."}]},{"text":[{"text":"Why a naira today is worth more:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"People prefer to consume now rather than later."}]},{"text":[{"text":"Money held today can be invested to earn interest."}]},{"text":[{"text":"Inflation reduces what money will buy later."}]},{"text":[{"text":"A future receipt is uncertain (risk)."}]}]}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" interest earned on the "},{"text":"original amount invested (principal)","bold":true},{"text":" only. The principal and the yearly interest stay the same from period to period."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SI = P × R × T (P = principal, R = rate per year as a decimal, T = time in years)"}]},{"text":[{"text":"A = P + PRT = P(1 + RT) (A = total amount at the end)"}]},{"text":[{"text":"P = A ÷ (1 + RT)"}]}]}]},{"text":[{"text":"Compound interest:","bold":true},{"text":" interest earned on the "},{"text":"principal plus previously earned interest","bold":true},{"text":". Interest can be compounded daily, monthly, quarterly, semi-annually or annually."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" the arithmetic process of finding the "},{"text":"final value","bold":true},{"text":" of a payment or series of payments when interest is known."}]},{"text":[{"text":"Banker's (ordinary) interest:","bold":true},{"text":" simple interest worked on a 360-day year; exact interest uses 365 days."}]}]},{"type":"table","header":[[],[{"text":"Simple interest"}],[{"text":"Compound interest"}]],"rows":[[[{"text":"Interest earned on"}],[{"text":"Principal only"}],[{"text":"Principal + past interest"}]],[[{"text":"Yearly interest"}],[{"text":"Constant"}],[{"text":"Rises each year"}]],[[{"text":"Amounts over time"}],[{"text":"Arithmetic progression"}],[{"text":"Geometric progression"}]],[[{"text":"Result"}],[{"text":"Lower"}],[{"text":"Higher (same rate and time)"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (simple interest):","italic":true},{"text":" Betty invests ₦100,000 for 3 years at 10% simple interest. SI = 100,000 × 0.1 × 3 = "},{"text":"₦30,000","bold":true},{"text":". For 4 years it is ₦40,000 and for 5 years ₦50,000: the interest rises by the same ₦10,000 each year."}]},{"type":"paragraph","text":[{"text":"Example (amount):","italic":true},{"text":" ₦10,000,000 saved for 3 years at 10% simple interest: A = 10,000,000 + 10,000,000 × 0.1 × 3 = "},{"text":"₦13,000,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (finding the principal):","italic":true},{"text":" How much must be invested now at 12.5% simple interest to have ₦150,000 in 4 years? P = 150,000 ÷ (1 + 0.125 × 4) = 150,000 ÷ 1.5 = "},{"text":"₦100,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (compound interest, same ₦100,000 at 10% for 3 years):","italic":true}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening (₦)"}],[{"text":"Interest at 10% (₦)"}],[{"text":"Closing (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"100,000"}],[{"text":"10,000"}],[{"text":"110,000"}]],[[{"text":"2"}],[{"text":"110,000"}],[{"text":"11,000"}],[{"text":"121,000"}]],[[{"text":"3"}],[{"text":"121,000"}],[{"text":"12,100"}],[{"text":"133,100"}]]]},{"type":"paragraph","text":[{"text":"Total interest = "},{"text":"₦33,100","bold":true},{"text":", compared with ₦30,000 under simple interest."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Interest accrues solely on the initial amount\" describes simple, not compound, interest. The simple interest formula is I = P × R × T, not P × R ÷ T."}]},{"text":[{"text":"Trap:","bold":true},{"text":" when an option gives the interest only and another gives principal plus interest, read whether the question asks \"how much interest\" or \"how much will he have\"."}]}]}]},{"number":"4.2","title":"Future value, present value and effective rates of a lump sum","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lump sum:","bold":true},{"text":" a single amount invested for a specified period at a specified rate."}]},{"text":[{"text":"Future (terminal) value:","bold":true},{"text":" what a sum today grows to. It takes into account the "},{"text":"impact of time on value","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"FV = PV × (1 + r)^n"}]},{"text":[{"text":"Compounding m times a year: FV = PV × (1 + r/m)^(n × m). Semi-annual m = 2; every four months m = 3; quarterly m = 4; twice a quarter m = 8; monthly m = 12; twice a month m = 24; weekly m = 52; daily m = 365."}]},{"text":[{"text":"Continuous compounding: FV = PV × e^(r × n), e = 2.71828"}]}]}]},{"text":[{"text":"Present value:","bold":true},{"text":" today's worth of a future cash flow. "},{"text":"Discounting","bold":true},{"text":" is the process of finding it; the "},{"text":"discount rate","bold":true},{"text":" is used to find current value."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = FV ÷ (1 + r)^n = FV × (1 + r)^-n"}]},{"text":[{"text":"With m periods: PV = FV ÷ (1 + r/m)^(n × m); continuous: PV = FV × e^(-r × n)"}]}]}]},{"text":[{"text":"A "},{"text":"higher","bold":true},{"text":" interest rate gives a "},{"text":"lower","bold":true},{"text":" present value; a longer time also lowers PV."}]},{"text":[{"text":"Nominal rate:","bold":true},{"text":" the quoted annual rate. "},{"text":"Effective annual rate (EAR):","bold":true},{"text":" the true yearly rate once the "},{"text":"frequency of compounding","bold":true},{"text":" is allowed for."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"EAR = (1 + r/m)^m - 1; continuous: EAR = e^r - 1"}]}]}]},{"text":[{"text":"Solving for time:","bold":true},{"text":" n = log(FV/PV) ÷ log(1 + r) (log base 10 or ln, both work)"}]},{"text":[{"text":"Solving for the rate:","bold":true},{"text":" r = (FV/PV)^(1/n) - 1; with m periods, r = m × [(FV/PV)^(1/(n × m)) - 1]"}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (FV):","italic":true},{"text":" ₦10,000,000 at 10% compounded annually for 3 years: FV = 10,000,000 × 1.1^3 = 10,000,000 × 1.331 = "},{"text":"₦13,310,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (fractional years):","italic":true},{"text":" ₦800,000 for 4½ years at 12%: FV = 800,000 × 1.12^4.5 = "},{"text":"₦1,332,205","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (quarterly):","italic":true},{"text":" ₦20,000,000 for 5 years at 24% compounded quarterly: rate per quarter = 0.24 ÷ 4 = 0.06, periods = 5 × 4 = 20. FV = 20,000,000 × 1.06^20 = 20,000,000 × 3.2071 = "},{"text":"₦64,142,709","bold":true},{"text":" (to the nearest naira)."}]},{"type":"paragraph","text":[{"text":"Example (twice a quarter):","italic":true},{"text":" ₦100,000 at 24% payable eight times a year for 3 years: 0.24 ÷ 8 = 0.03, 3 × 8 = 24 periods. FV = 100,000 × 1.03^24 = "},{"text":"₦203,279.41","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (continuous):","italic":true},{"text":" ₦15,000,000 at 16% for 2 years: FV = 15,000,000 × e^(0.32) = 15,000,000 × 1.3771 = "},{"text":"₦20,656,916","bold":true},{"text":" (₦20,656,500 if you round e^0.32 to 1.3771 first). Effective rate = e^0.16 - 1 = 0.1735 = "},{"text":"17.35%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (PV):","italic":true},{"text":" ₦14,400,000 due in 2 years at 20%: PV = 14,400,000 ÷ 1.2^2 = 14,400,000 ÷ 1.44 = "},{"text":"₦10,000,000","bold":true},{"text":". ₦7,500,000 due in 5 years at 20% compounded continuously: PV = 7,500,000 × e^(-1) = "},{"text":"₦2,759,096","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (PV, semi-annual):","italic":true},{"text":" ₦10m due in 5 years at 10% payable semi-annually: 5% for 10 periods. PV = 10m ÷ 1.05^10 = 10m ÷ 1.6289 = "},{"text":"₦6.14m","bold":true},{"text":". Using 10% annually (₦6.21m) is the trap."}]},{"type":"paragraph","text":[{"text":"Example (EAR):","italic":true},{"text":" 24% compounded quarterly: EAR = 1.06^4 - 1 = "},{"text":"26.25%","bold":true},{"text":". The more often interest is compounded, the higher the EAR: annual < quarterly < monthly < continuous."}]},{"type":"paragraph","text":[{"text":"Example (time):","italic":true},{"text":" How long for ₦3.5m to reach ₦45m at 25%? 1.25^n = 45 ÷ 3.5 = 12.8571. n = log 12.8571 ÷ log 1.25 = 1.1091 ÷ 0.0969 = "},{"text":"11.45 years, 11 years to the nearest year","bold":true},{"text":". Round as the question says: \"to the nearest year\" means normal rounding."}]},{"type":"paragraph","text":[{"text":"Example (doubling, tripling, quadrupling):","italic":true},{"text":" the PV cancels. To quadruple at 12%: 1.12^n = 4, n = log 4 ÷ log 1.12 = 0.6021 ÷ 0.0492 = "},{"text":"12.23 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (time with quarterly compounding):","italic":true},{"text":" ₦2m to ₦3m at 12% compounded quarterly: 1.03^k = 1.5, k = log 1.5 ÷ log 1.03 = 13.72 quarters, so n = 13.72 ÷ 4 = "},{"text":"3.43 years","bold":true},{"text":". Trap: 13.72 is quarters, not years."}]},{"type":"paragraph","text":[{"text":"Example (rate):","italic":true},{"text":" ₦100,000 grows to ₦133,100 in 3 years: (1 + r)^3 = 1.331, 1 + r = 1.331^(1/3) = 1.1, "},{"text":"r = 10%","bold":true},{"text":". With quarterly compounding, ₦10,000 to ₦20,000 in 5 years: (1 + r/4)^20 = 2, r/4 = 2^(0.05) - 1 = 0.03526, "},{"text":"r = 14.10%","bold":true},{"text":" (rounded). Trap: 3.53% is only the quarterly rate."}]}]},{"number":"4.3","title":"Annuities and perpetuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity:","bold":true},{"text":" a series of "},{"text":"equal","bold":true},{"text":", regular, periodic payments or receipts for a specified number of periods. It need not be annual: weekly, monthly or any regular interval counts."}]},{"text":[{"text":"Types of annuity (3):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ordinary annuity:","bold":true},{"text":" payments at the "},{"text":"end","bold":true},{"text":" of each period."}]},{"text":[{"text":"Annuity due:","bold":true},{"text":" payments at the "},{"text":"beginning","bold":true},{"text":" of each period."}]},{"text":[{"text":"Perpetual annuity (perpetuity):","bold":true},{"text":" equal payments expected "},{"text":"indefinitely","bold":true},{"text":"."}]}]}]},{"text":[{"text":"The "},{"text":"two major types","bold":true},{"text":" are ordinary annuity and annuity due."}]},{"text":[{"text":"FV of ordinary annuity","bold":true},{"text":" (sum of all payments plus compound interest on each): FV = A × [(1 + r)^n - 1] ÷ r"}]},{"text":[{"text":"PV of ordinary annuity","bold":true},{"text":" (amount to invest today to fund the series): PV = A × [1 - (1 + r)^-n] ÷ r"}]},{"text":[{"text":"FV of annuity due:","bold":true},{"text":" FV = A × [(1 + r)^(n+1) - (1 + r)] ÷ r = ordinary FV × (1 + r)"}]},{"text":[{"text":"PV of annuity due:","bold":true},{"text":" PV = A × [(1 + r) - (1 + r)^-(n-1)] ÷ r = ordinary PV × (1 + r)"}]},{"text":[{"text":"PV of perpetuity:","bold":true},{"text":" PV = A ÷ r"}]},{"text":[{"text":"Deferred annuity","bold":true},{"text":" (first payment later than one period away): PV = A × [1 - (1 + r)^-n] ÷ r × (1 + r)^-k, where k = periods of delay before the ordinary annuity starts."}]},{"text":[{"text":"Net present value:","bold":true},{"text":" NPV = PV of inflows - initial cost. Accept if NPV is positive."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (FV ordinary):","italic":true},{"text":" ₦20,000,000 deposited at the end of each of 3 years at 20%. Year by year: end of year 1 ₦20m; year 2: 20m + 4m interest + 20m = ₦44m; year 3: 44m + 8.8m + 20m = ₦72.8m. By formula: 20,000,000 × (1.2^3 - 1) ÷ 0.2 = 20,000,000 × 3.64 = "},{"text":"₦72,800,000","bold":true},{"text":". Only two years of interest are earned, because the last payment earns none."}]},{"type":"paragraph","text":[{"text":"Example (FV due):","italic":true},{"text":" the same deposits at the beginning of each year: 20,000,000 × (1.2^4 - 1.2) ÷ 0.2 = "},{"text":"₦87,360,000","bold":true},{"text":", which is 72,800,000 × 1.2."}]},{"type":"paragraph","text":[{"text":"Example (PV ordinary):","italic":true},{"text":" Joshua must pay ₦120,000 at the end of each of 3 years; money earns 12%. PV = 120,000 × [1 - 1.12^-3] ÷ 0.12 = 120,000 × 2.4018 = "},{"text":"₦288,219.75","bold":true},{"text":". Proof: 288,219.75 earns ₦34,586.37 in year 1, leaving 202,806.12 after paying 120,000; then 24,336.73 interest leaves 107,142.85; then 12,857.14 interest leaves 0."}]},{"type":"paragraph","text":[{"text":"Example (PV due):","italic":true},{"text":" the same ₦120,000 at the beginning of each year: PV = 120,000 × [1.12 - 1.12^-2] ÷ 0.12 = "},{"text":"₦322,806.12","bold":true},{"text":" (= 288,219.75 × 1.12)."}]},{"type":"paragraph","text":[{"text":"Example (perpetuity):","italic":true},{"text":" Chukwu expects ₦250,000 a year forever at 20%: PV = 250,000 ÷ 0.2 = "},{"text":"₦1,250,000","bold":true},{"text":". A bond paying ₦1,200,000 a year in perpetuity at 10% is worth ₦12,000,000."}]},{"type":"paragraph","text":[{"text":"Example (deferred):","italic":true},{"text":" ₦200,000 a year for 5 years, first payment at the end of year 4, at 10%. Value at end of year 3 = 200,000 × 3.7908 = ₦758,157.35. Discount 3 years: 758,157.35 ÷ 1.331 = "},{"text":"₦569,614.84","bold":true},{"text":". Trap: stopping at ₦758,157.35."}]},{"type":"paragraph","text":[{"text":"Example (solving n, ordinary):","italic":true},{"text":" ₦50,000 at the end of each year at 10% to reach ₦500,000: (1.1^n - 1) ÷ 0.1 = 10, so 1.1^n = 2, n = log 2 ÷ log 1.1 = "},{"text":"7.27 years","bold":true},{"text":". For an annuity due, divide by (1 + r) first: 1.1^n = 1 + 500,000 × 0.1 ÷ (50,000 × 1.1) = 1.9091, n = "},{"text":"6.78 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (NPV):","italic":true},{"text":" a project costs ₦100,000 and returns ₦30,000 a year for 4 years at 8%. PV of inflows = 30,000 × 3.3121 = ₦99,363.81; NPV = 99,363.81 - 100,000 = "},{"text":"-₦636.19","bold":true},{"text":", so reject. Trap: an option showing only the PV of inflows."}]},{"type":"paragraph","text":[{"text":"Mixed streams:","italic":true},{"text":" value each stream at its own rate and add. A monthly salary uses the monthly rate and number of months (3 years = 36 months); a yearly bonus uses the yearly rate and 3 years."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" an annuity due is always worth more than the ordinary annuity by the factor (1 + r), for both PV and FV."}]}]}]},{"number":"4.4","title":"Sinking funds and loan amortisation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sinking fund:","bold":true},{"text":" equal periodic deposits made to accumulate a target sum at a future date (an FV-of-annuity problem). Deposit A = FV × r ÷ [(1 + r)^n - 1]"}]},{"text":[{"text":"Loan amortisation:","bold":true},{"text":" repaying a loan by equal instalments that cover interest and part of the principal (a PV-of-annuity problem). Instalment A = Loan × r ÷ [1 - (1 + r)^-n]"}]},{"text":[{"text":"In each instalment, "},{"text":"interest","bold":true},{"text":" = opening balance × r; "},{"text":"principal repaid","bold":true},{"text":" = instalment - interest; closing balance = opening balance - principal repaid."}]},{"text":[{"text":"Outstanding balance","bold":true},{"text":" after k instalments = PV of the instalments still to be paid."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (sinking fund):","italic":true},{"text":" a school wants ₦1,000,000 in 4 years, saving at the end of each year at 10%. A = 1,000,000 × 0.1 ÷ (1.1^4 - 1) = 100,000 ÷ 0.4641 = "},{"text":"₦215,470.80","bold":true},{"text":". Fund after 2 years = 215,470.80 × 1.1 + 215,470.80 = 215,470.80 × 2.1 = "},{"text":"₦452,488.69","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (amortisation):","italic":true},{"text":" ₦500,000 borrowed at 12% for 3 years. A = 500,000 × 0.12 ÷ (1 - 1.12^-3) = "},{"text":"₦208,174.49","bold":true},{"text":"."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening (₦)"}],[{"text":"Interest 12% (₦)"}],[{"text":"Principal repaid (₦)"}],[{"text":"Closing (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"500,000.00"}],[{"text":"60,000.00"}],[{"text":"148,174.49"}],[{"text":"351,825.51"}]],[[{"text":"2"}],[{"text":"351,825.51"}],[{"text":"42,219.06"}],[{"text":"165,955.43"}],[{"text":"185,870.08"}]],[[{"text":"3"}],[{"text":"185,870.08"}],[{"text":"22,304.41"}],[{"text":"185,870.08"}],[{"text":"0.00"}]]]},{"type":"paragraph","text":[{"text":"Shortcut: balance after year 2 = one instalment left = 208,174.49 ÷ 1.12 = ₦185,870.08. Interest falls and principal repaid rises each year."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the instalment is not the balance; and a sinking-fund deposit is not the fund balance."}]}]}]},{"number":"4.5","title":"Arithmetic and geometric progressions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Arithmetic progression (AP):","bold":true},{"text":" each term differs from the one before by a constant "},{"text":"common difference d","bold":true},{"text":". First term a."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"nth term: Tn = a + (n - 1)d"}]},{"text":[{"text":"Sum of n terms: Sn = n/2 × [2a + (n - 1)d] = n/2 × (a + l), l = last term"}]},{"text":[{"text":"Number of terms: n = (l - a) ÷ d + 1"}]}]}]},{"text":[{"text":"Geometric progression (GP):","bold":true},{"text":" each term is the one before multiplied by a constant "},{"text":"common ratio r","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"nth term: Tn = a × r^(n-1)"}]},{"text":[{"text":"Sum of n terms: Sn = a × (r^n - 1) ÷ (r - 1) when r > 1, or a × (1 - r^n) ÷ (1 - r) when r < 1"}]},{"text":[{"text":"Sum to infinity (only when -1 < r < 1): S∞ = a ÷ (1 - r)"}]}]}]},{"text":[{"text":"Simple-interest amounts form an AP (d = PR); compound amounts form a GP (ratio 1 + r); annuity formulas are GP sums."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (AP):","italic":true},{"text":" 5, 8, 11, ...: a = 5, d = 3. T20 = 5 + 19 × 3 = "},{"text":"62","bold":true},{"text":"; S20 = 20/2 × (5 + 62) = "},{"text":"670","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (AP in naira):","italic":true},{"text":" a salary of ₦600,000 rising by ₦50,000 a year. Year 10 salary = 600,000 + 9 × 50,000 = "},{"text":"₦1,050,000","bold":true},{"text":"; total over 10 years = 10/2 × (600,000 + 1,050,000) = "},{"text":"₦8,250,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (GP):","italic":true},{"text":" 2, 6, 18, ...: a = 2, r = 3. T6 = 2 × 3^5 = "},{"text":"486","bold":true},{"text":"; S6 = 2 × (3^6 - 1) ÷ (3 - 1) = "},{"text":"728","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (sum to infinity):","italic":true},{"text":" ₦100,000 + ₦80,000 + ₦64,000 + ...: r = 0.8, S∞ = 100,000 ÷ (1 - 0.8) = "},{"text":"₦500,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Why annuity formulas work:","italic":true},{"text":" the end-year deposits of ₦20m at 20% grow to 20m, 24m and 28.8m: a GP with a = 20m, r = 1.2, n = 3. S3 = 20m × (1.2^3 - 1) ÷ 0.2 = ₦72.8m, the FV of the annuity. A perpetuity is a GP sum to infinity with a = A ÷ (1 + r) and ratio 1 ÷ (1 + r), which simplifies to A ÷ r."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the nth term uses n - 1, not n. Sum to infinity exists only when -1 < r < 1."}]}]}]},{"number":"4.6","title":"Investment, consumption and exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Each person has income now (Y0) and next period (Y1) and chooses consumption now (C0) and later (C1)."}]},{"text":[{"text":"Lending:","bold":true},{"text":" giving up ₦1 of consumption today gets ₦(1 + r) next period."}]},{"text":[{"text":"Borrowing:","bold":true},{"text":" ₦1 of next period's income can be spent today as ₦1 ÷ (1 + r)."}]},{"text":[{"text":"The interest rate is the "},{"text":"price of exchanging present for future consumption","bold":true},{"text":"."}]},{"text":[{"text":"Present value of wealth:","bold":true},{"text":" W0 = Y0 + Y1 ÷ (1 + r). Maximum future consumption = W0 × (1 + r)."}]},{"text":[{"text":"Budget line:","bold":true},{"text":" C1 = Y1 + (Y0 - C0) × (1 + r); slope = -(1 + r)."}]},{"text":[{"text":"Productive investment:","bold":true},{"text":" invest while the project's return exceeds the market rate (positive NPV). This raises wealth, and every person then borrows or lends to reach the consumption pattern they like."}]},{"text":[{"text":"Separation:","bold":true},{"text":" because people can borrow and lend at r, the investment decision (maximise NPV) is separate from consumption preferences."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example:","italic":true},{"text":" Ada earns ₦100,000 now and ₦110,000 next year; the rate is 10%. W0 = 100,000 + 110,000 ÷ 1.1 = "},{"text":"₦200,000","bold":true},{"text":"; maximum next-year consumption = 200,000 × 1.1 = ₦220,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"To spend ₦150,000 now, she borrows ₦50,000 and repays 50,000 × 1.1 = ₦55,000, leaving C1 = 110,000 - 55,000 = "},{"text":"₦55,000","bold":true},{"text":"."}]},{"text":[{"text":"To spend only ₦60,000 now, she lends ₦40,000 and gets back ₦44,000, so C1 = 110,000 + 44,000 = "},{"text":"₦154,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Investment:","italic":true},{"text":" a project costs ₦40,000 now and pays ₦50,000 next year (a 25% return, above 10%). NPV = 50,000 ÷ 1.1 - 40,000 = "},{"text":"₦5,454.55","bold":true},{"text":", so her wealth rises to ₦205,454.55 whatever her tastes. Exchange through banks or treasury bills lets savers (lenders) and spenders (borrowers) both gain."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A naira today is worth more than a naira tomorrow; compounding moves value forward, discounting moves it back."}]},{"text":[{"text":"SI = PRT and A = P(1 + RT); compound FV = PV(1 + r)^n, or PV(1 + r/m)^(nm), or PV × e^(rn)."}]},{"text":[{"text":"PV = FV(1 + r)^-n; higher rate means lower PV."}]},{"text":[{"text":"EAR = (1 + r/m)^m - 1; continuous EAR = e^r - 1."}]},{"text":[{"text":"n = log(FV/PV) ÷ log(1 + r); r = (FV/PV)^(1/n) - 1."}]},{"text":[{"text":"Ordinary annuity: FV = A[(1 + r)^n - 1]/r, PV = A[1 - (1 + r)^-n]/r; annuity due = ordinary × (1 + r); perpetuity = A/r."}]},{"text":[{"text":"Sinking fund deposit = FV × r/[(1 + r)^n - 1]; loan instalment = Loan × r/[1 - (1 + r)^-n]."}]},{"text":[{"text":"AP: a + (n - 1)d and n/2[2a + (n - 1)d]; GP: ar^(n-1), a(r^n - 1)/(r - 1), a/(1 - r)."}]},{"text":[{"text":"Borrowing and lending at r let people trade present for future consumption; invest when NPV is positive."}]}]}],"theory":{"itemId":"3a6f4bbb-2379-5802-a128-1abedf801b3c","question":[{"type":"paragraph","text":[{"text":"Unilag Ventures deposits ₦150,000 at the end of each year for 4 years at 15% per annum. How much will be in the fund at the end of year 4, and how much if each deposit were made at the beginning of the year?"}]}]},"practice":[{"topic":"Foundation of Financial Mathematics","named":false}]}},{"itemId":"bb3b0b44-2a82-5623-a29f-2c05092a6e5e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Financial Statement Analysis","body":"The three financial statements and what goes in each; users of financial statements and ratios; methods and limitations of analysis; the four groups of ratios with their other names; every formula for liquidity, activity, profitability, gearing and stock market ratios; ideal benchmarks; how to compute every ratio from one set of statements.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The three financial statements and what goes in each; users of financial statements and ratios; methods and limitations of analysis; the four groups of ratios with their other names; every formula for liquidity, activity, profitability, gearing and stock market ratios; ideal benchmarks; how to compute every ratio from one set of statements."}],"lessons":[{"number":"5.1","title":"Financial statements, users and methods of analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial statement analysis:","bold":true},{"text":" the process of examining a company's financial reports to assess its performance, stability and future prospects, so that stakeholders can make informed decisions."}]},{"text":[{"text":"3 main financial statements:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statement of financial position (balance sheet):","bold":true},{"text":" assets, liabilities and equity at a "},{"text":"specific point in time","bold":true},{"text":" (one date)."}]},{"text":[{"text":"Income statement (profit and loss account):","bold":true},{"text":" revenue, expenses and net income (profit) "},{"text":"over a period","bold":true},{"text":"; it shows "},{"text":"performance","bold":true},{"text":". Liabilities do "},{"text":"not","bold":true},{"text":" appear in it."}]},{"text":[{"text":"Statement of cash flows:","bold":true},{"text":" actual cash "},{"text":"inflows and outflows","bold":true},{"text":" over a period, in "},{"text":"3 sections:","bold":true},{"text":" operating, investing and financing activities."}]}]}]},{"text":[{"text":"A "},{"text":"trial balance","bold":true},{"text":" is a bookkeeping check (a list of ledger balances), "},{"text":"not","bold":true},{"text":" a financial statement."}]},{"text":[{"text":"Non-current (fixed) assets:","bold":true},{"text":" held for long-term use, not for sale, e.g. "},{"text":"land","bold":true},{"text":", buildings, plant, machinery."}]},{"text":[{"text":"Current assets:","bold":true},{"text":" cash or items that become cash within a year: inventory (stock), accounts receivable (debtors), bank, cash."}]},{"text":[{"text":"Current liabilities:","bold":true},{"text":" obligations to be settled "},{"text":"within 1 year","bold":true},{"text":": trade creditors (accounts payable), bank overdraft, accrued expenses, tax payable."}]},{"text":[{"text":"Shareholders' equity:","bold":true},{"text":" ordinary share capital (common stock), share premium (additional paid-in capital), reserves, retained earnings. Accounts payable is a "},{"text":"liability","bold":true},{"text":", not equity."}]},{"text":[{"text":"Working capital = current assets - current liabilities.","bold":true},{"text":" Its components are current assets and current liabilities; fixed assets, long-term debt and share capital are not part of it. A rise in working capital usually means "},{"text":"higher liquidity","bold":true},{"text":"."}]},{"text":[{"text":"Net profit = total revenue - total expenses.","bold":true},{"text":" Gross profit = sales - cost of goods sold. Operating profit = gross profit - operating expenses."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" the ease of converting assets to cash. "},{"text":"Leverage:","bold":true},{"text":" using "},{"text":"debt","bold":true},{"text":" to finance investments."}]},{"text":[{"text":"Users of financial ratio analysis (10):","bold":true},{"text":" 1. company management, 2. shareholders, 3. employees, 4. creditors, 5. government, 6. rational investors, 7. competitors, 8. customers, 9. financial analysts, 10. financial institutions."}]},{"text":[{"text":"Internal user:","bold":true},{"text":" management. "},{"text":"External users:","bold":true},{"text":" investors, shareholders, creditors, government and the rest."}]},{"text":[{"text":"5 objectives of analysis:","bold":true},{"text":" assess profitability; evaluate liquidity; measure solvency; understand operational efficiency; support decision-making."}]},{"text":[{"text":"5 methods of analysis:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Horizontal (trend) analysis:","bold":true},{"text":" compares figures across periods. Percentage change = (current year value - base year value) ÷ base year value × 100."}]},{"text":[{"text":"Vertical (common-size) analysis:","bold":true},{"text":" each item as a percentage of a base figure (revenue or total assets)."}]},{"text":[{"text":"Ratio analysis.","bold":true}]},{"text":[{"text":"Cash flow analysis:","bold":true},{"text":" evaluating and comparing cash inflows and outflows from operating, investing and financing activities."}]},{"text":[{"text":"Comparative analysis:","bold":true},{"text":" against industry benchmarks or competitors."}]}]}]},{"text":[{"text":"5 steps:","bold":true},{"text":" understand the business; review the statements; perform trend and ratio analysis; interpret results; make recommendations."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Horizontal example:","italic":true},{"text":" sales rose from ₦800,000 to ₦900,000. Change = (900,000 - 800,000) ÷ 800,000 × 100 = "},{"text":"12.5%","bold":true},{"text":"."}]},{"text":[{"text":"Vertical example:","italic":true},{"text":" cost of sales ₦540,000 on sales ₦900,000 is 540,000 ÷ 900,000 × 100 = "},{"text":"60%","bold":true},{"text":" of sales."}]},{"text":[{"text":"Debtors","bold":true},{"text":" (customers who owe the firm) are "},{"text":"not","bold":true},{"text":" listed as users of ratio analysis; "},{"text":"creditors","bold":true},{"text":" are. Do not confuse them. Customers are users, because they care whether a supplier will survive."}]},{"text":[{"text":"A "},{"text":"financial analyst","bold":true},{"text":" is the user who studies statements in order to "},{"text":"advise clients","bold":true},{"text":". Researchers study them for academic work."}]},{"text":[{"text":"ROI","bold":true},{"text":" stands for "},{"text":"Return on Investment","bold":true},{"text":": gain from an investment relative to its cost, × 100."}]},{"text":[{"text":"Nigerian listed companies publish audited statements and file them with the SEC and the Nigerian Exchange (NGX), which is where investors find the figures for ratios."}]}]}]},{"number":"5.2","title":"Ratio analysis and liquidity ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial ratio analysis:","bold":true},{"text":" the relationship between financial data in the financial statements that aids the evaluation of the financial condition and performance of a company. It is used to gauge a firm's operational success and to track performance trends."}]},{"text":[{"text":"Advantages (5):","bold":true},{"text":" 1. very easy to understand; 2. very simple to calculate; 3. allows comparison between two similar companies; 4. allows comparison with the industry average; 5. useful for identifying problem areas of the company."}]},{"text":[{"text":"Disadvantages (4):","bold":true},{"text":" 1. taken by itself, a ratio gives little useful information; 2. ratios are easily misinterpreted; 3. ratios do not identify the causes of a company's problems; 4. problems of definition."}]},{"text":[{"text":"Limitations of financial statement analysis (5):","bold":true},{"text":" historical data; differing accounting policies reduce comparability; non-financial factors (management quality, market conditions) are left out; window dressing; inflation."}]},{"text":[{"text":"4 groups of ratios:","bold":true}]}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Other names"}],[{"text":"Measures"}]],"rows":[[[{"text":"1. Short-term solvency"}],[{"text":"Liquidity","bold":true},{"text":", working capital ratios"}],[{"text":"Ability to meet current obligations from current assets"}]],[[{"text":"2. Efficiency and profitability"}],[{"text":"Performance ratios"}],[{"text":"Performance in relative terms"}]],[[{"text":"3. Long-term solvency"}],[{"text":"Stability","bold":true},{"text":" ratios, gearing"}],[{"text":"Ability to meet long-term obligations"}]],[[{"text":"4. Stock market"}],[{"text":"Investor interest, actual growth and potential, valuation, market value ratios"}],[{"text":"Help investors make investment decisions"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Liquidity formulas:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current ratio = current assets ÷ current liabilities (written as x : 1). "},{"text":"Ideal 2:1.","bold":true}]},{"text":[{"text":"Quick (acid-test) ratio = (current assets - inventory) ÷ current liabilities. "},{"text":"Ideal 1:1.","bold":true},{"text":" Inventory is excluded because it is the least liquid current asset."}]},{"text":[{"text":"Cash ratio = cash and cash equivalents ÷ current liabilities."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"current ratio","bold":true},{"text":" shows how far the claims of short-term creditors are covered by assets that will become cash within a year. Above 1 suggests good liquidity; far too high suggests idle assets. A "},{"text":"low quick ratio","bold":true},{"text":" warns of difficulty paying short-term debts. A very high cash ratio may mean underused cash."}]},{"text":[{"text":"Example 1:","italic":true},{"text":" stock ₦5,000; trade creditors ₦2,000; debtors ₦3,000; bank overdraft ₦1,600; bank ₦1,500; accrued expenses ₦400; cash ₦500."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current assets = 5,000 + 3,000 + 1,500 + 500 = ₦10,000. Current liabilities = 2,000 + 1,600 + 400 = ₦4,000."}]},{"text":[{"text":"Current ratio = 10,000 ÷ 4,000 = "},{"text":"2.5:1","bold":true},{"text":". Quick ratio = (10,000 - 5,000) ÷ 4,000 = "},{"text":"1.25:1","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Example 2:","italic":true},{"text":" inventories ₦3,100; receivables ₦8,000; payables ₦4,000; cash ₦6,260; taxation ₦2,250."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current assets = ₦17,360. Current liabilities = 4,000 + 2,250 = ₦6,250 (tax payable is due within the year, so include it)."}]},{"text":[{"text":"Current ratio = 17,360 ÷ 6,250 = "},{"text":"2.78:1","bold":true},{"text":". Quick = 14,260 ÷ 6,250 = "},{"text":"2.28:1","bold":true},{"text":" (both to 2 d.p.)."}]}]}]},{"text":[{"text":"Example 3:","italic":true},{"text":" stock ₦3,000, cash ₦7,000, debtors ₦10,000, trade creditors ₦5,900. Current ratio = 20,000 ÷ 5,900 = "},{"text":"3.4:1","bold":true},{"text":"; acid test = 17,000 ÷ 5,900 = "},{"text":"2.9:1","bold":true},{"text":" (1 d.p.)."}]},{"text":[{"text":"Traps:","bold":true},{"text":" a bank overdraft is a current liability, but money "},{"text":"in","bold":true},{"text":" the bank is a current asset. Options often list the ideal (2:1 or 1:1) beside the firm's actual figure; compute, do not guess the ideal."}]}]}]},{"number":"5.3","title":"Activity (efficiency) ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Activity ratios","bold":true},{"text":" measure how efficiently a firm uses its resources (stock, debtors, assets)."}]},{"text":[{"text":"Inventory (stock) turnover = cost of sales ÷ average stock (in "},{"text":"times","bold":true},{"text":")."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Average stock = (opening stock + closing stock) ÷ 2."}]},{"text":[{"text":"Inventory days = 365 ÷ inventory turnover."}]}]}]},{"text":[{"text":"Average collection period (receivables days) = trade debtors ÷ credit sales × 365 days."}]},{"text":[{"text":"Receivables turnover = credit sales ÷ average receivables (times)."}]},{"text":[{"text":"Average payment period (payables days) = trade creditors ÷ credit purchases × 365 days."}]},{"text":[{"text":"Credit purchases (if not given) = cost of sales + closing stock - opening stock."}]},{"text":[{"text":"Asset turnover = sales ÷ total assets (times)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stock turnover, the payment period and the collection period are also grouped with the "},{"text":"short-term (working capital) ratios","bold":true},{"text":", because they show how fast stock and debtors turn into cash. Accept either grouping."}]},{"text":[{"text":"Inventory turnover measures the "},{"text":"speed of inventory sales","bold":true},{"text":". A "},{"text":"high receivables turnover","bold":true},{"text":" means "},{"text":"swift collection","bold":true},{"text":" from customers; a low one means slow payment. A long payment period means the firm takes longer to pay suppliers."}]},{"text":[{"text":"Example:","italic":true},{"text":" opening stock ₦13,000, closing stock ₦9,000, cost of sales ₦77,000. Average stock = 0.5 × (13,000 + 9,000) = ₦11,000. Turnover = 77,000 ÷ 11,000 = "},{"text":"7 times","bold":true},{"text":"; inventory days = 365 ÷ 7 = "},{"text":"52.1 days","bold":true},{"text":" (1 d.p.)."}]},{"text":[{"text":"Example:","italic":true},{"text":" credit sales ₦40,000,000; average debtors ₦10,000,000. Receivables turnover = "},{"text":"4 times","bold":true},{"text":"; collection period = 10,000,000 ÷ 40,000,000 × 365 = "},{"text":"91.25 days","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" stock turnover uses "},{"text":"cost of sales","bold":true},{"text":", not sales; the collection period uses "},{"text":"credit sales","bold":true},{"text":"; the payment period uses "},{"text":"credit purchases","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Profitability ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profitability ratios","bold":true},{"text":" show a firm's ability to generate profit relative to revenue, assets or equity. All are × 100 (%)."}]},{"text":[{"text":"Gross profit margin = gross profit ÷ sales × 100."}]},{"text":[{"text":"Operating profit margin = operating profit (EBIT) ÷ sales × 100."}]},{"text":[{"text":"Net profit margin = net profit ÷ sales × 100 (profit after "},{"text":"all","bold":true},{"text":" costs, including interest and tax). The core formula also allows EBIT as the numerator; follow what the question says."}]},{"text":[{"text":"Return on total assets (ROTA) = EBIT ÷ total assets × 100."}]},{"text":[{"text":"Return on assets (ROA), net-income version = net income ÷ total assets × 100."}]},{"text":[{"text":"Return on capital employed (ROCE) = EBIT ÷ capital employed × 100."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital employed = total assets - current liabilities = equity + preference capital + long-term debt."}]}]}]},{"text":[{"text":"Return on shareholders' equity (ROSE or ROE) = EAIT (earnings after interest and tax) ÷ shareholders' equity × 100."}]}]},{"type":"table","header":[[{"text":"Abbreviation"}],[{"text":"Meaning"}]],"rows":[[[{"text":"EBIT"}],[{"text":"Earnings (profit) before interest and tax"}]],[[{"text":"EBT / PBT"}],[{"text":"Earnings (profit) before tax"}]],[[{"text":"EAIT / PAT"}],[{"text":"Earnings after interest and tax / profit after tax"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moving between profit lines:","bold":true},{"text":" EBIT = PBT + interest. PAT = PBT × (1 - tax rate)."}]},{"text":[{"text":"Example (₦'000):","italic":true},{"text":" credit sales 40,000; PBT 6,000; interest on loan 8,000; total assets 54,000; tax rate 35%; shareholders' funds 160,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PAT = 6,000 × 0.65 = 3,900. ROSE = 3,900 ÷ 160,000 × 100 = 2.44% = "},{"text":"2%","bold":true},{"text":" to the nearest whole number. (Using PBT wrongly gives 3.75%, about 4%.)"}]},{"text":[{"text":"EBIT = 6,000 + 8,000 = 14,000. ROTA = 14,000 ÷ 54,000 × 100 = 25.93% = "},{"text":"26%","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Example:","italic":true},{"text":" sales ₦40,000, EBIT ₦9,000, total assets ₦54,900. ROTA = 9,000 ÷ 54,900 × 100 = "},{"text":"16.4%","bold":true},{"text":". With capital employed ₦100,900, ROCE = 9,000 ÷ 100,900 × 100 = "},{"text":"8.9%","bold":true},{"text":", about 9%."}]},{"text":[{"text":"Example:","italic":true},{"text":" sales ₦108,700, cost of sales ₦91,000. Gross profit = ₦17,700; margin = 17,700 ÷ 108,700 × 100 = "},{"text":"16.3%","bold":true},{"text":"."}]},{"text":[{"text":"A higher gross margin means efficient production and cost control; a higher ROA means better asset use; ROE measures "},{"text":"profit from shareholders' funds","bold":true},{"text":", so it is a profitability ratio (unlike the debt, current and quick ratios)."}]}]}]},{"number":"5.5","title":"Gearing (long-term solvency) and stock market ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gearing ratio = fixed interest capital ÷ equity capital","bold":true},{"text":" (x : 1)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed interest capital = debt capital + preference share capital."}]},{"text":[{"text":"Equity capital = ordinary share capital + share premium + revenue reserves + retained earnings."}]}]}]},{"text":[{"text":"Debt-to-equity ratio = total debt (or total liabilities) ÷ shareholders' equity."}]},{"text":[{"text":"Debt ratio = total debt ÷ total assets × 100, where total debt = current liabilities + long-term debt."}]},{"text":[{"text":"Fixed interest cover (interest coverage, times interest earned) = EBIT ÷ annual fixed interest charged on debt (times)."}]},{"text":[{"text":"Proprietary ratio = shareholders' equity ÷ total tangible assets × 100."}]},{"text":[{"text":"Stock market ratios:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dividend per share (DPS) = gross (ordinary) dividend ÷ number of ordinary shares issued and fully paid."}]},{"text":[{"text":"Earnings per share (EPS) = earnings after interest and tax (less preference dividend) ÷ number of ordinary shares issued and fully paid."}]},{"text":[{"text":"Dividend yield = DPS ÷ market price per share × 100."}]},{"text":[{"text":"Earnings yield = EPS ÷ market price per share × 100."}]},{"text":[{"text":"Price/earnings (P/E) ratio = market price per share ÷ EPS (times)."}]},{"text":[{"text":"Dividend cover = earnings available to ordinary shareholders ÷ ordinary dividend = EPS ÷ DPS","bold":true},{"text":" (times)."}]},{"text":[{"text":"Dividend payout ratio = DPS ÷ EPS × 100 (the reciprocal of dividend cover)."}]},{"text":[{"text":"Price-to-book (P/B) = market price per share ÷ book value per share (book value per share = ordinary equity ÷ number of shares)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"high debt-to-equity","bold":true},{"text":" (or gearing) ratio means "},{"text":"significant leverage","bold":true},{"text":": heavy reliance on debt, so higher financial risk. A lower debt ratio means a stronger position; a higher interest cover means interest is paid more easily."}]},{"text":[{"text":"Gearing example:","italic":true},{"text":" debt capital ₦130,000; preference capital ₦90,000; equity ₦658,700. Gearing = 220,000 ÷ 658,700 = "},{"text":"0.33:1","bold":true},{"text":"."}]},{"text":[{"text":"Debt ratio example:","italic":true},{"text":" current liabilities ₦13,650; long-term debt ₦5,400; total assets ₦87,000. Debt ratio = 19,050 ÷ 87,000 × 100 = "},{"text":"21.9%","bold":true},{"text":". Trap: add "},{"text":"both","bold":true},{"text":" kinds of debt; using current liabilities alone gives 15.7%."}]},{"text":[{"text":"DPS example:","italic":true},{"text":" gross dividend ₦108,700 on 900,000 shares. DPS = "},{"text":"₦0.12 (12 kobo)","bold":true},{"text":", to the nearest kobo."}]},{"text":[{"text":"Dividend yield example:","italic":true},{"text":" DPS ₦1.70, market price ₦11.45. Yield = 1.70 ÷ 11.45 × 100 = 14.8%, about "},{"text":"15%","bold":true},{"text":"."}]},{"text":[{"text":"EPS and P/E are inversely related:","bold":true},{"text":" for a given price, higher EPS means lower P/E. Earnings yield is P/E turned upside down. A "},{"text":"high P/E","bold":true},{"text":" signals "},{"text":"potential overvaluation","bold":true},{"text":", or strong growth expectations; a low P/E may mean undervaluation."}]},{"text":[{"text":"Dividend cover","bold":true},{"text":" shows how many times the ordinary dividend could be paid out of the year's earnings. Cover of 2 times means half of earnings is paid out and half retained; cover below 1 means part of the dividend comes from past reserves."}]},{"text":[{"text":"Earnings yield and dividend yield use the "},{"text":"market price","bold":true},{"text":", so they are "},{"text":"market value ratios","bold":true},{"text":"; gross profit margin and times interest earned are not."}]}]}]},{"number":"5.6","title":"One full worked set","mustKnow":[{"type":"paragraph","text":[{"text":"Adebayo Ltd, figures in ₦'000. Ordinary shares: 200,000 of ₦1 each. Market price per share ₦3.60. All sales are on credit. Opening inventory ₦40,000."}]},{"type":"table","header":[[{"text":"Statement of financial position at 31 December"}],[{"text":"₦'000"}]],"rows":[[[{"text":"Land and buildings"}],[{"text":"300"}]],[[{"text":"Plant and machinery"}],[{"text":"150"}]],[[{"text":"Non-current assets","bold":true}],[{"text":"450","bold":true}]],[[{"text":"Inventory"}],[{"text":"60"}]],[[{"text":"Trade receivables"}],[{"text":"50"}]],[[{"text":"Cash"}],[{"text":"40"}]],[[{"text":"Current assets","bold":true}],[{"text":"150","bold":true}]],[[{"text":"Total assets","bold":true}],[{"text":"600","bold":true}]],[[{"text":"Ordinary share capital"}],[{"text":"200"}]],[[{"text":"Share premium"}],[{"text":"50"}]],[[{"text":"Retained earnings"}],[{"text":"100"}]],[[{"text":"Ordinary shareholders' equity","bold":true}],[{"text":"350","bold":true}]],[[{"text":"10% preference share capital"}],[{"text":"50"}]],[[{"text":"10% debenture (long-term debt)"}],[{"text":"100"}]],[[{"text":"Trade payables"}],[{"text":"70"}]],[[{"text":"Tax payable"}],[{"text":"30"}]],[[{"text":"Current liabilities","bold":true}],[{"text":"100","bold":true}]],[[{"text":"Total equity and liabilities","bold":true}],[{"text":"600","bold":true}]]]},{"type":"table","header":[[{"text":"Income statement for the year"}],[{"text":"₦'000"}]],"rows":[[[{"text":"Sales"}],[{"text":"900"}]],[[{"text":"Cost of sales"}],[{"text":"(540)"}]],[[{"text":"Gross profit","bold":true}],[{"text":"360","bold":true}]],[[{"text":"Operating expenses"}],[{"text":"(240)"}]],[[{"text":"EBIT","bold":true}],[{"text":"120","bold":true}]],[[{"text":"Interest (10% × 100)"}],[{"text":"(10)"}]],[[{"text":"Profit before tax","bold":true}],[{"text":"110","bold":true}]],[[{"text":"Tax at 30%"}],[{"text":"(33)"}]],[[{"text":"Profit after tax (EAIT)","bold":true}],[{"text":"77","bold":true}]],[[{"text":"Preference dividend (10% × 50)"}],[{"text":"(5)"}]],[[{"text":"Earnings for ordinary shareholders","bold":true}],[{"text":"72","bold":true}]],[[{"text":"Ordinary dividend"}],[{"text":"(36)"}]],[[{"text":"Retained for the year","bold":true}],[{"text":"36","bold":true}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Supporting figures: capital employed = 600 - 100 = 500 (also 350 + 50 + 100). Total debt = 100 + 100 = 200. Average inventory = (40 + 60) ÷ 2 = 50. Credit purchases = 540 + 60 - 40 = 560. Only closing receivables (50) are given, so they stand in for average receivables."}]},{"type":"table","header":[[{"text":"Ratio"}],[{"text":"Working"}],[{"text":"Result"}]],"rows":[[[{"text":"Current ratio"}],[{"text":"150 ÷ 100"}],[{"text":"1.5:1"}]],[[{"text":"Quick ratio"}],[{"text":"(150 - 60) ÷ 100"}],[{"text":"0.9:1"}]],[[{"text":"Cash ratio"}],[{"text":"40 ÷ 100"}],[{"text":"0.4:1"}]],[[{"text":"Working capital"}],[{"text":"150 - 100"}],[{"text":"₦50,000"}]],[[{"text":"Inventory turnover"}],[{"text":"540 ÷ 50"}],[{"text":"10.8 times"}]],[[{"text":"Inventory days"}],[{"text":"365 ÷ 10.8"}],[{"text":"33.8 days"}]],[[{"text":"Receivables turnover"}],[{"text":"900 ÷ 50"}],[{"text":"18 times"}]],[[{"text":"Collection period"}],[{"text":"50 ÷ 900 × 365"}],[{"text":"20.3 days"}]],[[{"text":"Payment period"}],[{"text":"70 ÷ 560 × 365"}],[{"text":"45.6 days"}]],[[{"text":"Asset turnover"}],[{"text":"900 ÷ 600"}],[{"text":"1.5 times"}]],[[{"text":"Gross profit margin"}],[{"text":"360 ÷ 900 × 100"}],[{"text":"40%"}]],[[{"text":"Operating (EBIT) margin"}],[{"text":"120 ÷ 900 × 100"}],[{"text":"13.3%"}]],[[{"text":"Net profit margin"}],[{"text":"77 ÷ 900 × 100"}],[{"text":"8.6%"}]],[[{"text":"ROTA"}],[{"text":"120 ÷ 600 × 100"}],[{"text":"20%"}]],[[{"text":"ROA (net income)"}],[{"text":"77 ÷ 600 × 100"}],[{"text":"12.8%"}]],[[{"text":"ROCE"}],[{"text":"120 ÷ 500 × 100"}],[{"text":"24%"}]],[[{"text":"ROSE / ROE"}],[{"text":"77 ÷ 350 × 100"}],[{"text":"22%"}]],[[{"text":"Gearing"}],[{"text":"(100 + 50) ÷ 350"}],[{"text":"0.43:1"}]],[[{"text":"Debt-to-equity"}],[{"text":"200 ÷ 350"}],[{"text":"0.57:1"}]],[[{"text":"Debt ratio"}],[{"text":"200 ÷ 600 × 100"}],[{"text":"33.3%"}]],[[{"text":"Interest cover"}],[{"text":"120 ÷ 10"}],[{"text":"12 times"}]],[[{"text":"Proprietary ratio"}],[{"text":"350 ÷ 600 × 100"}],[{"text":"58.3%"}]],[[{"text":"EPS"}],[{"text":"₦72,000 ÷ 200,000"}],[{"text":"₦0.36"}]],[[{"text":"DPS"}],[{"text":"₦36,000 ÷ 200,000"}],[{"text":"₦0.18"}]],[[{"text":"P/E ratio"}],[{"text":"3.60 ÷ 0.36"}],[{"text":"10 times"}]],[[{"text":"Earnings yield"}],[{"text":"0.36 ÷ 3.60 × 100"}],[{"text":"10%"}]],[[{"text":"Dividend yield"}],[{"text":"0.18 ÷ 3.60 × 100"}],[{"text":"5%"}]],[[{"text":"Dividend cover"}],[{"text":"72 ÷ 36 (= 0.36 ÷ 0.18)"}],[{"text":"2 times"}]],[[{"text":"Payout ratio"}],[{"text":"0.18 ÷ 0.36 × 100"}],[{"text":"50%"}]],[[{"text":"Book value per share"}],[{"text":"₦350,000 ÷ 200,000"}],[{"text":"₦1.75"}]],[[{"text":"P/B ratio"}],[{"text":"3.60 ÷ 1.75"}],[{"text":"2.06 times"}]]]},{"type":"paragraph","text":[{"text":"Rounding: days and percentages to 1 d.p., P/B, gearing and debt-to-equity to 2 d.p."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading the results:","bold":true},{"text":" the current ratio (1.5:1) and quick ratio (0.9:1) are below the 2:1 and 1:1 ideals, so liquidity is a little tight. Interest cover of 12 times and gearing of 0.43:1 show modest borrowing. ROCE of 24% is healthy."}]},{"text":[{"text":"Traps in this set:","bold":true},{"text":" EPS uses earnings "},{"text":"after","bold":true},{"text":" the preference dividend (72, not 77). Dividend cover uses the "},{"text":"ordinary","bold":true},{"text":" dividend only. ROCE uses capital employed (500), ROTA uses total assets (600). If a question says \"total debt ÷ equity\" use 200; if it says \"long-term debt ÷ equity\" use 100 ÷ 350 = 0.29:1. Some questions compute ROE from earnings for ordinary shareholders: 72 ÷ 350 × 100 = 20.6%. Always follow the formula the question states."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Statement of financial position = one date; income statement = performance over a period; cash flow statement = 3 sections (operating, investing, financing)."}]},{"text":[{"text":"Current liabilities fall due within 1 year; land is a fixed asset; working capital = CA - CL."}]},{"text":[{"text":"10 users of ratios; management is internal; debtors are not users; analysts advise clients."}]},{"text":[{"text":"4 groups: liquidity (short-term solvency), efficiency and profitability, stability (long-term solvency), stock market."}]},{"text":[{"text":"Current ratio ideal 2:1; quick ratio ideal 1:1 and excludes inventory."}]},{"text":[{"text":"Stock turnover = cost of sales ÷ average stock; collection period = debtors ÷ credit sales × 365; payment period = creditors ÷ credit purchases × 365."}]},{"text":[{"text":"ROTA = EBIT ÷ total assets; ROCE = EBIT ÷ capital employed; ROSE = EAIT ÷ equity."}]},{"text":[{"text":"Gearing = (debt + preference capital) ÷ equity; debt ratio = (CL + long-term debt) ÷ total assets; interest cover = EBIT ÷ interest."}]},{"text":[{"text":"EPS, DPS, dividend yield, earnings yield, P/E (inverse of EPS), dividend cover = EPS ÷ DPS."}]},{"text":[{"text":"Ratios are easy and comparable, but alone tell little, are easily misread and do not show causes."}]}]}],"theory":{"itemId":"58b6d20d-4ef2-5fc4-b6eb-9cbf882aaaa7","question":[{"type":"paragraph","text":[{"text":"Bode Plc earned profit after tax of ₦4,800,000 and paid a preference dividend of ₦800,000 and an ordinary dividend of ₦1,600,000. It has 10,000,000 ordinary shares priced at ₦4.00 each. Calculate EPS, DPS, dividend cover, P/E ratio and dividend yield."}]}]},"practice":[{"topic":"Financial Statement and Ratio Analysis","named":false}]}},{"itemId":"51fe3ef0-f55f-5398-8aa8-ef58bb70fe89","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Financial Markets","body":"The financial system and the meaning, functions and types of financial markets; money market vs capital market and their instruments; primary vs secondary markets; the Nigerian stock market; participants, institutions and regulators (CBN, SEC, NGX); short-, medium- and long-term sources of finance with their merits and demerits.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The financial system and the meaning, functions and types of financial markets; money market vs capital market and their instruments; primary vs secondary markets; the Nigerian stock market; participants, institutions and regulators (CBN, SEC, NGX); short-, medium- and long-term sources of finance with their merits and demerits."}],"lessons":[{"number":"6.1","title":"The financial system and financial markets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial system:","bold":true},{"text":" a complex of "},{"text":"institutions, instruments, rules and regulations","bold":true},{"text":" that facilitates the "},{"text":"mobilisation and transfer of resources from savings-surplus units to deficit units","bold":true},{"text":"."}]},{"text":[{"text":"Financial market:","bold":true},{"text":" a marketplace where buyers and sellers "},{"text":"trade financial assets","bold":true},{"text":" such as stocks, bonds, currencies, derivatives and commodities. It facilitates the flow of funds between investors, businesses and governments, mobilising capital, managing risk and allocating resources efficiently."}]},{"text":[{"text":"Other definitions: any system or structure that makes it possible to trade in different kinds of financial securities; markets where debt, debentures and equities are traded; markets where funds can be raised."}]},{"text":[{"text":"A financial market brings together "},{"text":"those who have money","bold":true},{"text":" (lenders, buyers of financial instruments) and "},{"text":"those who need money","bold":true},{"text":" (borrowers, sellers of financial instruments). Without it, borrowers would find it difficult to locate lenders."}]},{"text":[{"text":"Financial security (instrument):","bold":true},{"text":" the receipt the borrower issues to the lender as a promise or evidence to pay back the capital. It is a tradeable claim to money or ownership: a share, bond, treasury bill."}]},{"text":[{"text":"Financial asset:","bold":true},{"text":" a claim to money: "},{"text":"cash","bold":true},{"text":", shares, bonds, deposits. "},{"text":"Real (physical) assets:","bold":true},{"text":" machinery, buildings, factories, inventory."}]}]},{"type":"paragraph","text":[{"text":"7 functions of financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital formation:","bold":true},{"text":" raising capital by issuing stocks and bonds."}]},{"text":[{"text":"Liquidity provision:","bold":true},{"text":" assets can be converted to cash without significant loss in value."}]},{"text":[{"text":"Efficient price discovery:","bold":true},{"text":" prices are set by "},{"text":"supply and demand","bold":true},{"text":", reflecting available information."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" derivatives hedge price, interest-rate and currency risks."}]},{"text":[{"text":"Facilitating savings and investment.","bold":true}]},{"text":[{"text":"Economic growth:","bold":true},{"text":" capital flows to the projects with the highest potential."}]},{"text":[{"text":"Reducing transaction costs:","bold":true},{"text":" trading is centralised."}]}]},{"type":"paragraph","text":[{"text":"6 types of financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital markets:","bold":true},{"text":" long-term instruments (stocks, bonds); split into primary and secondary."}]},{"text":[{"text":"Money markets:","bold":true},{"text":" short-term instruments (maturity "},{"text":"less than one year","bold":true},{"text":")."}]},{"text":[{"text":"Foreign exchange (forex) markets:","bold":true},{"text":" trading currencies."}]},{"text":[{"text":"Derivatives markets:","bold":true},{"text":" futures, options, swaps."}]},{"text":[{"text":"Commodity markets:","bold":true},{"text":" metals, energy, agricultural products."}]},{"text":[{"text":"Cryptocurrency markets:","bold":true},{"text":" Bitcoin, Ethereum and others."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In short: financial markets "},{"text":"enable funds to move efficiently","bold":true},{"text":" from savers to users. They do not curtail competition, raise production costs or restrict investment choice."}]},{"text":[{"text":"Trap: a factory, machine or office building is a "},{"text":"real asset","bold":true},{"text":", not a financial instrument. "},{"text":"Accounts payable","bold":true},{"text":" is a liability, not an asset. Cash "},{"text":"is","bold":true},{"text":" a financial asset."}]},{"text":[{"text":"Trap: \"savings market\" or \"economic system\" are distractors for the definition of the "},{"text":"financial system","bold":true},{"text":"."}]},{"text":[{"text":"The narrow two-way split (money market and capital market) is the one most questions use; the six-way list adds forex, derivatives, commodity and crypto markets."}]}]}]},{"number":"6.2","title":"Money market vs capital market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money market:","bold":true},{"text":" where "},{"text":"short-term","bold":true},{"text":" financial securities are bought and sold. Funds raised can be used for a "},{"text":"maximum of one year or less","bold":true},{"text":"."}]},{"text":[{"text":"Capital market:","bold":true},{"text":" where securities with a life span of "},{"text":"more than one year","bold":true},{"text":" are bought and sold; the market for "},{"text":"medium- and long-term","bold":true},{"text":" funds (long-term borrowing and lending)."}]}]},{"type":"paragraph","text":[{"text":"Functions of the money market (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Promotes economic growth by making money available to different sectors."}]},{"text":[{"text":"Platform for effective implementation of "},{"text":"monetary policy","bold":true},{"text":"."}]},{"text":[{"text":"Stabilises demand and supply of money for short-term transactions."}]},{"text":[{"text":"Avenue for short-term investment."}]},{"text":[{"text":"Generates savings and investment in the economy."}]}]},{"type":"paragraph","text":[{"text":"Money market instruments:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Treasury bills:","bold":true},{"text":" used by government to borrow for a short time; issued by the "},{"text":"Central Bank","bold":true},{"text":" (on behalf of government); maturity under one year."}]},{"text":[{"text":"Repurchase agreements (repos):","bold":true},{"text":" the seller sells a security to the buyer and agrees to "},{"text":"buy the same security back","bold":true},{"text":" later."}]},{"text":[{"text":"Certificate of deposit:","bold":true},{"text":" a promissory note issued by a "},{"text":"bank","bold":true},{"text":" giving the bearer the right to receive interest."}]},{"text":[{"text":"Banker's acceptance:","bold":true},{"text":" a promise by the buyer to pay the seller, with the "},{"text":"buyer's bank standing as guarantor","bold":true},{"text":"."}]},{"text":[{"text":"Commercial paper:","bold":true},{"text":" short-term "},{"text":"unsecured promissory note","bold":true},{"text":" issued by large, creditworthy ("},{"text":"blue-chip","bold":true},{"text":") companies, backed only by the issuer's promise to pay the face value at maturity."}]},{"text":[{"text":"Call money:","bold":true},{"text":" very short-term lending between banks, repayable on call. "},{"text":"Bank deposits","bold":true},{"text":" are also money market instruments."}]}]},{"type":"paragraph","text":[{"text":"Capital market instruments:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ordinary shares (equities, common stock):","bold":true},{"text":" part ownership; each member is a fractional owner bearing the maximum entrepreneurial risk; voting rights and dividends."}]},{"text":[{"text":"Preference shares:","bold":true},{"text":" fixed dividends, usually no voting rights."}]},{"text":[{"text":"Bonds:","bold":true},{"text":" long-term debt issued by companies or governments, paying fixed interest and "},{"text":"redeemable","bold":true},{"text":" at maturity."}]},{"text":[{"text":"Debentures (debenture stock):","bold":true},{"text":" debt instruments issued by companies to raise capital. The basic (naked) debenture is "},{"text":"not secured","bold":true},{"text":" by physical assets; it promises interest and principal, and holders become "},{"text":"creditors","bold":true},{"text":" of the company."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Money market"}],[{"text":"Capital market"}]],"rows":[[[{"text":"Maturity"}],[{"text":"One year or less"}],[{"text":"More than one year"}]],[[{"text":"Purpose"}],[{"text":"Working capital, short-term needs"}],[{"text":"Long-term investment"}]],[[{"text":"Instruments"}],[{"text":"T-bills, CP, CDs, BAs, repos, call money"}],[{"text":"Shares, bonds, debentures"}]],[[{"text":"Apex regulator in Nigeria"}],[{"text":"CBN","bold":true}],[{"text":"SEC","bold":true}]]]},{"type":"paragraph","text":[{"text":"Other instruments:","bold":true},{"text":" derivatives ("},{"text":"futures","bold":true},{"text":": agreement to buy or sell at a set price on a future date; "},{"text":"options","bold":true},{"text":": the right but not the obligation to buy or sell before expiry; "},{"text":"swaps","bold":true},{"text":": exchange of cash flows); forex (spot, forward, currency swaps); commodity contracts; cryptocurrencies."}]},{"type":"paragraph","text":[{"text":"Treasury bill pricing (discount basis, 365-day year):","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = Face value × discount rate × days / 365"}]},{"text":[{"text":"Price = Face value − Discount"}]},{"text":[{"text":"Yield = (Discount / Price) × (365 / days)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example.","bold":true},{"text":" A 91-day treasury bill has a face value of ₦1,000,000 and a discount rate of 18% a year."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = 1,000,000 × 0.18 × 91 / 365 = "},{"text":"₦44,876.71","bold":true}]},{"text":[{"text":"Price = 1,000,000 − 44,876.71 = "},{"text":"₦955,123.29","bold":true}]},{"text":[{"text":"Yield = (44,876.71 / 955,123.29) × (365 / 91) = "},{"text":"18.85%","bold":true},{"text":" (to 2 d.p.). The yield is above the discount rate because you earn the discount on ₦955,123.29, not on ₦1,000,000."}]}]}]},{"text":[{"text":"Nigerian T-bills run for 91, 182 or 364 days. They pay no coupon; you buy below face value and receive the full face value at maturity."}]},{"text":[{"text":"Traps: \"the stock market\" is a "},{"text":"long-term capital market","bold":true},{"text":", not a short-term lending market. Debenture stock and preference shares are "},{"text":"capital market","bold":true},{"text":"; bankers' acceptances, commercial paper and bank deposits are "},{"text":"money market","bold":true},{"text":"."}]},{"text":[{"text":"A "},{"text":"bond","bold":true},{"text":" is debt (you lend); a "},{"text":"stock","bold":true},{"text":" is ownership (you own). A certificate of deposit and a loan are also debt."}]}]}]},{"number":"6.3","title":"Primary vs secondary markets and the stock market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary market:","bold":true},{"text":" where "},{"text":"new","bold":true},{"text":" securities are issued and sold to investors "},{"text":"for the first time","bold":true},{"text":" (e.g. IPOs). Transactions are between the "},{"text":"issuing company and investors","bold":true},{"text":"; the issuer gets the money."}]},{"text":[{"text":"Secondary market:","bold":true},{"text":" where "},{"text":"already issued","bold":true},{"text":" securities are traded among investors. The "},{"text":"issuing company is not involved","bold":true},{"text":"."}]},{"text":[{"text":"Stock market:","bold":true},{"text":" the segment of the financial market where equities and other securities are issued, bought and sold. In Nigeria it is regulated by the "},{"text":"SEC","bold":true},{"text":" and facilitated by the "},{"text":"Nigerian Exchange Group (NGX)","bold":true},{"text":", formerly the Nigerian Stock Exchange (NSE)."}]},{"text":[{"text":"Stock exchange:","bold":true},{"text":" its major role is to "},{"text":"facilitate the trading of securities","bold":true},{"text":" in an organised market."}]}]},{"type":"paragraph","text":[{"text":"Primary market functions in Nigeria (7):","bold":true},{"text":" capital formation; facilitates economic growth; investment opportunities; promotes industrialisation; government fundraising (FGN bonds); encourages entrepreneurship; price determination (sets the initial price). "},{"text":"Importance:","bold":true},{"text":" boosts financial inclusion; supports public-private partnerships; stimulates foreign investment."}]},{"type":"paragraph","text":[{"text":"Secondary market functions (8):","bold":true},{"text":" liquidity provision; continuous price discovery; portfolio diversification; encourages investment; capital reallocation; wealth creation (capital gains, dividends, interest); supports the primary market (assures buyers they can sell later); regulatory oversight by SEC and NGX. "},{"text":"Importance:","bold":true},{"text":" market confidence; foreign participation; stimulates economic growth; wealth redistribution; enables corporate governance."}]},{"type":"paragraph","text":[{"text":"Importance of the stock market in Nigeria (10):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital formation"}]},{"text":[{"text":"Economic growth (adds to GDP)"}]},{"text":[{"text":"Wealth creation"}]},{"text":[{"text":"Encourages savings and investment"}]},{"text":[{"text":"Liquidity provision"}]},{"text":[{"text":"Promotes corporate governance"}]},{"text":[{"text":"Employment generation (brokers, analysts, fund managers)"}]},{"text":[{"text":"Attracts foreign investment"}]},{"text":[{"text":"Supports government financing"}]},{"text":[{"text":"Risk diversification"}]}]},{"type":"paragraph","text":[{"text":"Functions of the stock market (9):","bold":true},{"text":" mobilisation of savings; facilitating capital raising (IPOs, bonds); providing liquidity; price discovery; enhancing corporate governance; "},{"text":"economic indicator","bold":true},{"text":" (barometer of economic health); risk management; wealth redistribution; investment opportunities."}]},{"type":"paragraph","text":[{"text":"Instruments traded on the Nigerian stock market (8):","bold":true},{"text":" equities (ordinary and preference shares); debt (corporate and government bonds); "},{"text":"ETFs","bold":true},{"text":"; derivatives; "},{"text":"mutual funds","bold":true},{"text":"; "},{"text":"REITs","bold":true},{"text":" (returns from real estate); commercial papers; "},{"text":"GDRs","bold":true},{"text":" (let Nigerian companies trade shares on foreign exchanges)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"primary = first sale, money to the company; secondary = resale, money between investors.","bold":true},{"text":" \"Tertiary market\" is a distractor. Where \"primary market\" is an option, pick it over the broader \"capital market\" for new issues."}]},{"text":[{"text":"Share prices are set by "},{"text":"market supply and demand","bold":true},{"text":", not by government, wages or production costs."}]},{"text":[{"text":"Mutual fund:","bold":true},{"text":" a "},{"text":"collective investment pool","bold":true},{"text":" of many investors' money, professionally managed and spread over many securities."}]},{"text":[{"text":"In 2021 the Nigerian Stock Exchange was demutualised into the Nigerian Exchange Group; questions may still say \"NSE\"."}]}]}]},{"number":"6.4","title":"Participants, institutions and regulators","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial intermediary:","bold":true},{"text":" a "},{"text":"link between lenders and borrowers","bold":true},{"text":" (savers and users of funds): banks, mutual funds, hedge funds, investment firms."}]},{"text":[{"text":"Financial institutions","bold":true},{"text":" deal in money and financial services: commercial (deposit money) banks, stock exchanges, insurance companies, pension funds. A "},{"text":"supermarket is not one","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"10 participants in financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investors:","bold":true},{"text":" supply funds to earn returns (pension funds, insurers)."}]},{"text":[{"text":"Issuers:","bold":true},{"text":" governments and corporations raising capital."}]},{"text":[{"text":"Brokers and dealers:","bold":true},{"text":" brokers act for others for a commission; dealers trade on their own account."}]},{"text":[{"text":"Regulatory bodies:","bold":true},{"text":" e.g. SEC (US), RBI (India), FCA (UK)."}]},{"text":[{"text":"Financial intermediaries.","bold":true}]},{"text":[{"text":"Speculators:","bold":true},{"text":" profit from price movements."}]},{"text":[{"text":"Hedgers:","bold":true},{"text":" use instruments to manage risk."}]},{"text":[{"text":"Arbitrageurs:","bold":true},{"text":" exploit price differences for risk-free profit."}]},{"text":[{"text":"Central banks:","bold":true},{"text":" monetary policy, liquidity, interest rates."}]},{"text":[{"text":"Rating agencies:","bold":true},{"text":" S&P, Moody's, Fitch rate creditworthiness."}]}]},{"type":"paragraph","text":[{"text":"Participants in the Nigerian stock market (10):","bold":true},{"text":" investors (retail, mutual funds, pension funds); issuers; "},{"text":"stockbrokers","bold":true},{"text":" (licensed agents); "},{"text":"NGX","bold":true},{"text":" (platform for listing and trading); "},{"text":"SEC","bold":true},{"text":" (regulator); "},{"text":"market makers","bold":true},{"text":" (keep liquidity, stabilise prices); "},{"text":"investment banks","bold":true},{"text":" (issuing houses: help issue securities, advise); fund managers; foreign investors; clearing and settlement institutions ("},{"text":"CSCS","bold":true},{"text":", Central Securities Clearing System)."}]},{"type":"table","header":[[{"text":"Body"}],[{"text":"Role"}]],"rows":[[[{"text":"CBN","bold":true}],[{"text":"Apex regulator of the "},{"text":"money market","bold":true},{"text":" and banks; monetary policy; issues T-bills"}]],[[{"text":"SEC","bold":true}],[{"text":"Apex regulator of the "},{"text":"capital market","bold":true}]],[[{"text":"NGX","bold":true}],[{"text":"Exchange where securities are listed and traded"}]],[[{"text":"NDIC","bold":true}],[{"text":"Insures bank deposits"}]],[[{"text":"NAICOM","bold":true}],[{"text":"Regulates insurance"}]],[[{"text":"PenCom","bold":true}],[{"text":"Regulates pensions"}]],[[{"text":"Deposit money banks","bold":true}],[{"text":"Take deposits, lend, run overdrafts"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: CBN vs SEC is the most swapped pair. "},{"text":"Money market → CBN; capital market → SEC.","bold":true},{"text":" The NGX is a market, not the apex regulator; issuing houses help companies raise capital."}]},{"text":[{"text":"Insurance companies and pension funds are major "},{"text":"institutional investors","bold":true},{"text":": they collect premiums and contributions and invest them in bonds, shares and T-bills."}]},{"text":[{"text":"Factories, shops and workers belong to goods and labour markets; "},{"text":"investors","bold":true},{"text":" are the financial market participants."}]}]}]},{"number":"6.5","title":"Sources of finance and financing business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify by "},{"text":"how long","bold":true},{"text":" the funds are kept: "},{"text":"short-term","bold":true},{"text":" (within one year), "},{"text":"medium-term","bold":true},{"text":" (about one to five years), "},{"text":"long-term","bold":true},{"text":" (beyond five years, or permanent)."}]},{"text":[{"text":"Internal source:","bold":true},{"text":" "},{"text":"retained earnings","bold":true},{"text":" (net income reinvested in the business instead of being paid as dividends). Everything else here is "},{"text":"external","bold":true},{"text":"."}]},{"text":[{"text":"Equity finance","bold":true},{"text":" = "},{"text":"ownership capital","bold":true},{"text":" (from owners: shares, retained earnings). "},{"text":"Debt finance","bold":true},{"text":" = loan capital (borrowed: loans, debentures, bonds)."}]},{"text":[{"text":"Matching principle:","bold":true},{"text":" finance short-term needs (working capital) with short-term sources and long-term assets with long-term sources."}]}]},{"type":"table","header":[[{"text":"Term"}],[{"text":"Source"}],[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Short"}],[{"text":"Trade credit:","bold":true},{"text":" buy now, pay suppliers later"}],[{"text":"Easy, usually no interest"}],[{"text":"Lose cash discounts; supplier goodwill at risk"}]],[[{"text":"Short"}],[{"text":"Bank overdraft:","bold":true},{"text":" draw beyond the current account balance up to a limit"}],[{"text":"Flexible; interest only on amount used"}],[{"text":"Repayable on demand; high interest"}]],[[{"text":"Short"}],[{"text":"Factoring:","bold":true},{"text":" sell receivables to a factor for immediate cash"}],[{"text":"Quick cash; factor collects debts"}],[{"text":"Fees; customers may see it as weakness"}]],[[{"text":"Short"}],[{"text":"Commercial paper","bold":true}],[{"text":"Cheaper than bank loans; unsecured"}],[{"text":"Only for blue-chip firms"}]],[[{"text":"Short"}],[{"text":"Bill finance:","bold":true},{"text":" discounting bills of exchange, bankers' acceptances"}],[{"text":"Cash before the bill matures"}],[{"text":"Discount cost"}]],[[{"text":"Medium"}],[{"text":"Term loan:","bold":true},{"text":" fixed amount, fixed period, scheduled repayment"}],[{"text":"Certain, planned; interest is tax-deductible"}],[{"text":"Interest must be paid; often secured"}]],[[{"text":"Medium"}],[{"text":"Hire purchase:","bold":true},{"text":" pay by instalments; ownership passes after the "},{"text":"last","bold":true},{"text":" instalment"}],[{"text":"Use the asset at once"}],[{"text":"Costly; asset repossessed if you default"}]],[[{"text":"Medium"}],[{"text":"Leasing:","bold":true},{"text":" pay rentals to use an asset owned by the "},{"text":"lessor","bold":true}],[{"text":"No large outlay; rentals tax-deductible"}],[{"text":"No ownership; total cost high"}]],[[{"text":"Long"}],[{"text":"Ordinary shares","bold":true}],[{"text":"No obligation to repay; no fixed dividend"}],[{"text":"Dilutes control","bold":true},{"text":"; dividends not tax-deductible; issue costs"}]],[[{"text":"Long"}],[{"text":"Preference shares:","bold":true},{"text":" fixed dividend, priority over ordinary shares"}],[{"text":"No vote, so no loss of control"}],[{"text":"Fixed dividend, not tax-deductible"}]],[[{"text":"Long"}],[{"text":"Debentures","bold":true}],[{"text":"No loss of control; interest tax-deductible"}],[{"text":"Fixed interest and repayment; raises gearing"}]],[[{"text":"Long"}],[{"text":"Retained earnings","bold":true}],[{"text":"No issue cost, no dilution, no interest"}],[{"text":"Limited by profit; shareholders forgo dividends"}]]]},{"type":"paragraph","text":[{"text":"Equity vs debt:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Equity"}],[{"text":"Debt"}]],"rows":[[[{"text":"Holder is"}],[{"text":"Owner"}],[{"text":"Creditor (lender)"}]],[[{"text":"Return"}],[{"text":"Dividend (not compulsory)"}],[{"text":"Interest (legal obligation)"}]],[[{"text":"Repayment"}],[{"text":"None"}],[{"text":"At maturity"}]],[[{"text":"Tax"}],[{"text":"Dividends not deductible"}],[{"text":"Interest "},{"text":"tax-deductible","bold":true}]],[[{"text":"Control"}],[{"text":"Dilutes control"}],[{"text":"No dilution"}]]]},{"type":"paragraph","text":[{"text":"Factors in choosing a source:","bold":true},{"text":" cost, period (purpose) of need, control, risk and gearing, security available, flexibility, size of the firm."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Factoring example.","bold":true},{"text":" A firm has ₦2,000,000 of receivables. The factor advances 80% at once and charges a 2% fee. Advance = 0.80 × 2,000,000 = "},{"text":"₦1,600,000","bold":true},{"text":". Fee = 0.02 × 2,000,000 = "},{"text":"₦40,000","bold":true},{"text":". The firm gets cash today instead of waiting for customers."}]},{"text":[{"text":"Leasing","bold":true},{"text":" is medium- to long-term, not short-term: it is the odd one out among factoring, bill finance and trade credit."}]},{"text":[{"text":"Bonds","bold":true},{"text":" and debentures are long-term; a "},{"text":"bank loan","bold":true},{"text":" is usually short- or medium-term. Where \"debenture\" is an option for long-term finance, it is the safe choice."}]},{"text":[{"text":"Advantage of equity: "},{"text":"no obligation to repay","bold":true},{"text":". Tax-deductible interest is an advantage of "},{"text":"debt","bold":true},{"text":"; diluting control is a "},{"text":"disadvantage","bold":true},{"text":" of equity."}]},{"text":[{"text":"Equity security","bold":true},{"text":" = "},{"text":"ordinary share","bold":true},{"text":". Preference shares and convertibles are hybrids; debenture stock is pure debt."}]},{"text":[{"text":"Hire purchase vs leasing:","bold":true},{"text":" under HP you eventually "},{"text":"own","bold":true},{"text":" the asset; under a lease the lessor keeps ownership."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial system = institutions, instruments, rules and regulations moving funds from surplus to deficit units."}]},{"text":[{"text":"Financial markets: capital formation, liquidity, price discovery, risk management, savings, growth, lower transaction costs."}]},{"text":[{"text":"Money market: one year or less (T-bills, CP, CDs, BAs, repos); capital market: over one year (shares, bonds, debentures)."}]},{"text":[{"text":"Primary = new issues, money to the issuer; secondary = existing securities between investors."}]},{"text":[{"text":"CBN = apex money market regulator; SEC = apex capital market regulator; NGX = the exchange."}]},{"text":[{"text":"Financial intermediary links lenders and borrowers; mutual fund = collective investment pool."}]},{"text":[{"text":"Short-term: trade credit, overdraft, factoring, CP, bill finance. Medium: term loans, HP, leasing. Long: ordinary and preference shares, debentures, retained earnings."}]},{"text":[{"text":"Equity = ownership capital, never repaid; debt interest is tax-deductible."}]}]}],"theory":{"itemId":"f744b4e0-a23a-576b-aef7-06a24f544785","question":[{"type":"paragraph","text":[{"text":"A supplier invoices ₦500,000 on terms of 2% discount if paid within 10 days, otherwise full payment in 30 days. What is the approximate annual cost of using the trade credit (giving up the discount)?"}]}]},"practice":[{"topic":"Introduction to Financial Markets","named":false}]}},{"itemId":"b7fdd21a-6dd9-531f-8144-8540051558b5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Forms of Business Firm","body":"The sole proprietorship, partnership, limited liability company (private and public), cooperative and public corporation: the definition, types, advantages, disadvantages and sources of funds of each; limited liability and the corporate form; how to choose a form of business.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The sole proprietorship, partnership, limited liability company (private and public), cooperative and public corporation: the definition, types, advantages, disadvantages and sources of funds of each; limited liability and the corporate form; how to choose a form of business."}],"lessons":[{"number":"7.1","title":"Sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietor:","bold":true},{"text":" someone who owns an "},{"text":"unincorporated","bold":true},{"text":" business by himself or herself. A sole proprietorship is the type of business organisation "},{"text":"owned, managed and controlled by a single owner","bold":true},{"text":". \"Sole\" means "},{"text":"only","bold":true},{"text":"; \"proprietor\" means "},{"text":"owner","bold":true},{"text":". Also called a "},{"text":"sole trader","bold":true},{"text":"."}]},{"text":[{"text":"Key features:","bold":true},{"text":" one owner; "},{"text":"unlimited liability","bold":true},{"text":"; "},{"text":"no separate legal personality","bold":true},{"text":"; few formalities; owner takes all profit and bears all loss; profit taxed as the owner's "},{"text":"personal income","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 types of sole proprietorship:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Service-based"}]},{"text":[{"text":"Retail-based"}]},{"text":[{"text":"Technology"}]},{"text":[{"text":"Manufacturing-based"}]},{"text":[{"text":"Consulting-based"}]}]},{"type":"paragraph","text":[{"text":"8 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complete control and greater flexibility"}]},{"text":[{"text":"Easy set-up"}]},{"text":[{"text":"Low registration and start-up costs"}]},{"text":[{"text":"Lower accounting fees"}]},{"text":[{"text":"Greater privacy"}]},{"text":[{"text":"No sharing of profits (although the owner also carries any debt alone)"}]},{"text":[{"text":"Less paperwork"}]},{"text":[{"text":"Simplified taxes"}]}]},{"type":"paragraph","text":[{"text":"7 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unlimited liability"}]},{"text":[{"text":"Potential credibility issues"}]},{"text":[{"text":"Sole responsibility"}]},{"text":[{"text":"Fewer tax planning opportunities"}]},{"text":[{"text":"Barriers to finance"}]},{"text":[{"text":"Sale limitations"}]},{"text":[{"text":"Limited expertise"}]}]},{"type":"paragraph","text":[{"text":"Sources of funds:","bold":true},{"text":" owner's personal savings; loans from family and friends; bank loans and overdrafts; microfinance bank and cooperative loans; trade (suppliers') credit; hire purchase; equipment leasing; ploughed-back profits. "},{"text":"Not","bold":true},{"text":" issue of shares or debentures."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unlimited liability","bold":true},{"text":" means the owner's personal property (house, car, savings) can be taken to pay business debts. If Bisi's provision shop owes ₦8,000,000 and the shop's assets fetch only ₦5,000,000, creditors can recover the shortfall of 8,000,000 − 5,000,000 = "},{"text":"₦3,000,000","bold":true},{"text":" from Bisi personally."}]},{"text":[{"text":"Easy to form because it has few legal hurdles.","bold":true},{"text":" In Nigeria the owner usually just registers a "},{"text":"business name","bold":true},{"text":" with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" and starts trading. No state charter, co-owners or shares are needed."}]},{"text":[{"text":"It ends when the owner dies or shuts it down.","bold":true},{"text":" Having no separate legal existence, it has no perpetual succession. Rapid growth does not end it; selling shares to the public or admitting partners would turn it into a different form."}]},{"text":[{"text":"Total owner control","bold":true},{"text":" is the classic advantage; "},{"text":"unlimited liability","bold":true},{"text":" is the classic disadvantage and the classic characteristic. Limited liability, legal personality and separate taxation belong to companies, not to sole traders."}]},{"text":[{"text":"\"Sale limitations\": the business is hard to sell, as its value is tied to the owner. \"Credibility issues\": banks and big customers may trust a one-person firm less."}]}]}]},{"number":"7.2","title":"Partnership","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" a legal arrangement that allows "},{"text":"two or more people","bold":true},{"text":" to share responsibility for a business. Partners share the ownership and profits, and also the work, responsibility and potential losses."}]},{"text":[{"text":"Legal definition:","bold":true},{"text":" the relation between persons who have agreed to share the profits of a business carried on by all or any of them acting for all."}]},{"text":[{"text":"The law does "},{"text":"not","bold":true},{"text":" require a written partnership agreement to form a partnership (it may be oral or implied by conduct). An ordinary partnership usually has "},{"text":"2 to 20 partners","bold":true},{"text":"; professional firms such as lawyers and accountants may be larger."}]},{"text":[{"text":"Partnership agreement (deed):","bold":true},{"text":" sets out "},{"text":"how profits and losses are shared","bold":true},{"text":", capital contributions, interest on capital and drawings, partners' salaries, rights and duties, admission and retirement of partners, and settling disputes."}]},{"text":[{"text":"Where there is no agreement","bold":true},{"text":", the usual rules are: profits and losses are shared "},{"text":"equally","bold":true},{"text":"; no interest on capital; no salary for any partner; interest at 5% a year on a partner's loan to the firm (over and above agreed capital)."}]}]},{"type":"paragraph","text":[{"text":"4 types of partnerships (business alliances):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Strategic alliances between non-competitors"}]},{"text":[{"text":"Strategic partnerships between competitors (called "},{"text":"coopetition","bold":true},{"text":")"}]},{"text":[{"text":"Joint ventures to develop new business"}]},{"text":[{"text":"Buyer-supplier relationships to assure reliable supplies"}]}]},{"type":"paragraph","text":[{"text":"8 types of partners:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active or managing partner:","bold":true},{"text":" takes part in the firm's management."}]},{"text":[{"text":"Inactive or sleeping (dormant) partner:","bold":true},{"text":" contributes capital and shares profit but does not manage."}]},{"text":[{"text":"Nominal partner:","bold":true},{"text":" lends only his name, yet is liable to outsiders."}]},{"text":[{"text":"Partner by estoppel or holding out:","bold":true},{"text":" lets himself be presented as a partner, so is liable to those who relied on it."}]},{"text":[{"text":"Partner in profits only:","bold":true},{"text":" shares profits but not losses."}]},{"text":[{"text":"Minor as a partner:","bold":true},{"text":" admitted to the benefits only; not personally liable for losses."}]},{"text":[{"text":"Secret partner:","bold":true},{"text":" active, but hidden from the public."}]},{"text":[{"text":"Sub-partner:","bold":true},{"text":" an outsider sharing one partner's profit share; no rights against the firm."}]}]},{"type":"paragraph","text":[{"text":"7 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bridging the gap in expertise and knowledge"}]},{"text":[{"text":"Additional capital"}]},{"text":[{"text":"Cost savings"}]},{"text":[{"text":"More business opportunities"}]},{"text":[{"text":"Responsibilities can be shared"}]},{"text":[{"text":"Emotional support"}]},{"text":[{"text":"New perspective"}]}]},{"type":"paragraph","text":[{"text":"8 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Potential liabilities"}]},{"text":[{"text":"Loss of autonomy"}]},{"text":[{"text":"Emotional issues"}]},{"text":[{"text":"Conflict and disagreements"}]},{"text":[{"text":"Future selling complications"}]},{"text":[{"text":"Lack of stability"}]},{"text":[{"text":"Higher taxes"}]},{"text":[{"text":"Splitting profits"}]}]},{"type":"paragraph","text":[{"text":"Sources of funds:","bold":true},{"text":" partners' capital contributions; admitting a new partner; partners' loans; ploughed-back profits; bank loans and overdrafts; suppliers' credit; equipment leasing; hire purchase. "},{"text":"Not","bold":true},{"text":" issue of shares."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unlimited personal liability","bold":true},{"text":" (\"potential liabilities\") is the main disadvantage of an ordinary partnership: each partner is liable for all the firm's debts, even those caused by another partner."}]},{"text":[{"text":"Pooled skills and resources","bold":true},{"text":" is the main advantage."}]},{"text":[{"text":"Decision-making is distributed (shared) among partners.","bold":true},{"text":" Control by one person describes a sole proprietor; voting by equity holders describes a company."}]},{"text":[{"text":"Lack of stability:","bold":true},{"text":" death, retirement or bankruptcy of a partner dissolves an ordinary partnership unless the agreement says otherwise."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a partnership "},{"text":"cannot issue shares","bold":true},{"text":", because only companies have share capital. Suppliers' credit, leasing and hire purchase are all open to it."}]},{"text":[{"text":"CAMA 2020","bold":true},{"text":" (Companies and Allied Matters Act 2020) also allows a "},{"text":"Limited Liability Partnership (LLP)","bold":true},{"text":" and a "},{"text":"Limited Partnership (LP)","bold":true},{"text":", registered with the CAC. In an LP at least one general partner keeps unlimited liability."}]}]},{"type":"paragraph","text":[{"text":"Worked example (sharing profit):","bold":true},{"text":" Ade (capital ₦6,000,000) and Ngozi (capital ₦4,000,000) make a profit of ₦3,000,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"(a) Agreement: share in capital ratio 6:4 = 3:2. Ade = 3/5 × 3,000,000 = "},{"text":"₦1,800,000","bold":true},{"text":"; Ngozi = 2/5 × 3,000,000 = "},{"text":"₦1,200,000","bold":true},{"text":"."}]},{"text":[{"text":"(b) Agreement: 10% interest on capital, Ngozi gets a salary of ₦400,000, remainder shared equally. Interest: Ade ₦600,000, Ngozi ₦400,000. Remainder = 3,000,000 − 600,000 − 400,000 − 400,000 = ₦1,600,000, so ₦800,000 each. Ade = "},{"text":"₦1,400,000","bold":true},{"text":"; Ngozi = 400,000 + 400,000 + 800,000 = "},{"text":"₦1,600,000","bold":true},{"text":" (total ₦3,000,000)."}]},{"text":[{"text":"(c) No agreement: equal shares, no interest or salary: "},{"text":"₦1,500,000 each","bold":true},{"text":"."}]}]}]},{"number":"7.3","title":"The limited liability company (private and public)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited company:","bold":true},{"text":" a general form of incorporation that "},{"text":"limits the amount of liability","bold":true},{"text":" undertaken by the company's shareholders. It is a legal structure that ensures the liability of members or subscribers is "},{"text":"limited to their stake","bold":true},{"text":" in the company (their investments or commitments)."}]},{"text":[{"text":"Limited liability company (LLC):","bold":true},{"text":" a business structure where owners are "},{"text":"not held personally liable","bold":true},{"text":" for the debts or other liabilities the business may incur."}]},{"text":[{"text":"Corporation / company:","bold":true},{"text":" a "},{"text":"distinct (separate) legal entity","bold":true},{"text":" from its owners; it can own property, sue and be sued in its own name. It is "},{"text":"owned by shareholders","bold":true},{"text":", each holding a stake."}]},{"text":[{"text":"Features of the corporate form:","bold":true},{"text":" separate legal entity; limited liability; "},{"text":"perpetual succession","bold":true},{"text":" (it continues when owners die or sell); transferable shares; separation of ownership (shareholders) from control (directors); raises capital by "},{"text":"issuing equity shares","bold":true},{"text":" and debentures."}]}]},{"type":"paragraph","text":[{"text":"2 types (by number of members):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Single-member LLC:","bold":true},{"text":" operates like a sole proprietorship but with the protection of the law on the liability of the business."}]},{"text":[{"text":"Multi-member LLC:","bold":true},{"text":" two or more members form and own the business."}]}]},{"type":"paragraph","text":[{"text":"LLC vs other forms:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Enterprise / sole proprietor"}],[{"text":"Company (LLC)"}]],"rows":[[[{"text":"Legal entity"}],[{"text":"Not separate from owner"}],[{"text":"Separate legal entity"}]],[[{"text":"Liability"}],[{"text":"Owner personally liable for all debts"}],[{"text":"Members not personally liable (limited)"}]],[[{"text":"Owners"}],[{"text":"Always one person (sole proprietor)"}],[{"text":"One or more members"}]]]},{"type":"paragraph","text":[{"text":"6 advantages of LLC:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Limited personal liability for the company's business debts."}]},{"text":[{"text":"Fairly easy to organise and get running."}]},{"text":[{"text":"Many business expenses can be written off as deductions, lowering taxable income."}]},{"text":[{"text":"Can be run by its members, or members can hire a manager for day-to-day affairs; members choose how involved to be."}]},{"text":[{"text":"The LLC designation lends greater credibility to a sole proprietorship or partnership."}]},{"text":[{"text":"Less record-keeping than corporations, so more focus on business goals."}]}]},{"type":"paragraph","text":[{"text":"4 disadvantages of LLC:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Depending on state law, it may have to be dissolved on the death or bankruptcy of a member (a corporation can exist in perpetuity)."}]},{"text":[{"text":"Under pass-through taxation, members pay self-employment taxes on top of personal income tax."}]},{"text":[{"text":"Unless the Operating Agreement is properly conceived, executed and understood, roles and responsibilities may be unclear."}]},{"text":[{"text":"Penalties, stated in the Operating Agreement, for failing to make capital contributions."}]}]},{"type":"paragraph","text":[{"text":"Private vs public company:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Private company (Ltd)"}],[{"text":"Public company (Plc)"}]],"rows":[[[{"text":"Name ends in"}],[{"text":"\"Limited\" (Ltd)"}],[{"text":"\"Public Limited Company\" (Plc)"}]],[[{"text":"Members"}],[{"text":"One person upwards; at most 50 (excluding employees)"}],[{"text":"No maximum"}]],[[{"text":"Offer of shares"}],[{"text":"Cannot invite the public to buy its shares"}],[{"text":"Can offer shares to the public"}]],[[{"text":"Share transfer"}],[{"text":"Restricted by its articles"}],[{"text":"Freely transferable; may be listed on the NGX"}]],[[{"text":"Regulation"}],[{"text":"Less"}],[{"text":"Heavier: SEC rules, published accounts"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability is the "},{"text":"advantage","bold":true},{"text":" that exam options call \"limited owner liability\" or \"limited liability for investors\": a shareholder loses at most what he paid, or still owes, for his shares. If Bisi's shop (Lesson 7.1) had been Bisi Stores Ltd, the ₦3,000,000 shortfall would fall on creditors, not on Bisi's house."}]},{"text":[{"text":"Double taxation","bold":true},{"text":" is the classic disadvantage of a corporation: profit is taxed once as company income tax and again when dividends are taxed in shareholders' hands. "},{"text":"Worked example (illustrative rates):","bold":true},{"text":" profit ₦10,000,000; company tax at 30% = ₦3,000,000; profit after tax ₦7,000,000 paid as dividend; withholding tax at 10% = ₦700,000; shareholders receive ₦6,300,000. Total tax = 3,000,000 + 700,000 = ₦3,700,000, which is "},{"text":"37%","bold":true},{"text":" of the original profit."}]},{"text":[{"text":"Other corporate disadvantages: complex, costly formation; heavy regulation; agency conflict."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" companies are formed under "},{"text":"CAMA 2020","bold":true},{"text":" by registering with the "},{"text":"CAC","bold":true},{"text":". CAMA 2020 lets "},{"text":"one person","bold":true},{"text":" form a private company. Companies may be limited by shares, limited by guarantee (often non-profit bodies) or unlimited."}]},{"text":[{"text":"The LLC disadvantages use United States terms (\"state law\", \"Operating Agreement\"); learn them as listed. The Nigerian counterpart of the Operating Agreement is the articles of association."}]},{"text":[{"text":"Trap:","bold":true},{"text":" only "},{"text":"public","bold":true},{"text":" companies can trade shares on a public market. \"Public market trading\" is not a feature of every LLC."}]}]}]},{"number":"7.4","title":"Public corporations and cooperatives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public corporation:","bold":true},{"text":" a corporation "},{"text":"owned and operated by a government","bold":true},{"text":", established for the administration of certain public programmes. It is set up by an "},{"text":"act of parliament","bold":true},{"text":" (in Nigeria, the National Assembly or a state House of Assembly), owned and managed by government to provide "},{"text":"essential services to the public at affordable cost","bold":true},{"text":". Also called a public enterprise or statutory corporation."}]}]},{"type":"paragraph","text":[{"text":"2 types of public corporation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Those providing "},{"text":"essential services","bold":true},{"text":": water corporations, the National Electric Power Authority (NEPA), Federal Housing Authority."}]},{"text":[{"text":"Those of a "},{"text":"commercial nature","bold":true},{"text":": state-owned banks, hotels, textile mills, transport services."}]}]},{"type":"paragraph","text":[{"text":"Public corporation vs public company:","bold":true},{"text":" a "},{"text":"public corporation","bold":true},{"text":" is owned and controlled by "},{"text":"government","bold":true},{"text":" and provides essential services. A "},{"text":"public limited company","bold":true},{"text":" is a "},{"text":"privately owned","bold":true},{"text":" business that "},{"text":"offers shares to the public","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"8 examples of public enterprises in Nigeria:","bold":true},{"text":" Nigerian Railway Corporation (NRC); Central Bank of Nigeria (CBN); water corporations across the country; Nigerian Postal Service; Defence Industries Corporation of Nigeria; National Universities Commission (NUC); NAFDAC; NDLEA."}]},{"type":"paragraph","text":[{"text":"4 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Flexibility and independence retained"}]},{"text":[{"text":"Governmental review promotes public interest"}]},{"text":[{"text":"Recruitment power"}]},{"text":[{"text":"Debt shared by more investors"}]}]},{"type":"paragraph","text":[{"text":"4 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complex legal requirements"}]},{"text":[{"text":"Increased governmental oversight"}]},{"text":[{"text":"Many company records are public"}]},{"text":[{"text":"Ownership and management are split"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative society:","bold":true},{"text":" a business "},{"text":"owned and controlled by its members","bold":true},{"text":", formed voluntarily to "},{"text":"serve the needs of its member-owners","bold":true},{"text":", not to maximise profit for outside shareholders."}]},{"text":[{"text":"Principles:","bold":true},{"text":" voluntary and open membership; "},{"text":"democratic control (one member, one vote","bold":true},{"text":", however many shares held); members contribute capital and share any surplus; autonomy; education and training of members; cooperation among cooperatives; concern for the community."}]},{"text":[{"text":"Types:","bold":true},{"text":" consumer (retail); producer and agricultural; marketing; "},{"text":"credit and thrift","bold":true},{"text":" (savings and loans); housing; multipurpose."}]},{"text":[{"text":"Sources of funds:","bold":true},{"text":" members' shares, entrance fees and savings; retained surplus; loans; grants."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A public corporation keeps flexibility because it is a "},{"text":"separate legal body","bold":true},{"text":" with its own board, while government review keeps it serving the public. \"Ownership and management split\": government owns it, a board runs it."}]},{"text":[{"text":"Sources of funds for public corporations:","bold":true},{"text":" government grants, subventions and budget allocations; government loans; internally generated revenue (fees and charges); bonds; local and foreign loans, often guaranteed by government."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"public\" in "},{"text":"public corporation","bold":true},{"text":" means government-owned; \"public\" in "},{"text":"public limited company","bold":true},{"text":" means its shares are offered to the public. Dangote Cement Plc is a public company, not a public corporation."}]},{"text":[{"text":"Many public enterprises have since been privatised; NEPA was unbundled into separate electricity companies."}]},{"text":[{"text":"Cooperative surplus","bold":true},{"text":" is usually returned as a "},{"text":"patronage dividend","bold":true},{"text":", in proportion to each member's dealings with the society, and interest on members' capital is limited. "},{"text":"Worked example:","bold":true},{"text":" a consumer cooperative earns a surplus of ₦1,200,000; members bought goods worth ₦24,000,000 from it. Rate = 1,200,000 / 24,000,000 = "},{"text":"5 kobo per naira (5%)","bold":true},{"text":". Mrs Okon bought ₦600,000, so she receives 600,000 × 0.05 = "},{"text":"₦30,000","bold":true},{"text":"."}]},{"text":[{"text":"A staff cooperative that takes monthly savings and gives members cheap loans is a credit and thrift cooperative. Liability is "},{"text":"not","bold":true},{"text":" what defines a cooperative; serving its members is."}]}]}]},{"number":"7.5","title":"Choosing a form of business","mustKnow":[{"type":"paragraph","text":[{"text":"Factors to consider in choosing a form:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital required","bold":true},{"text":" and ease of raising it (shares are open only to companies; a public offer only to a Plc)"}]},{"text":[{"text":"Liability","bold":true},{"text":" of owners (limited or unlimited)"}]},{"text":[{"text":"Control","bold":true},{"text":" and management (how much the owner wants to keep)"}]},{"text":[{"text":"Ease and cost of formation","bold":true},{"text":" and legal formalities"}]},{"text":[{"text":"Continuity","bold":true},{"text":" (perpetual succession or ending with the owner)"}]},{"text":[{"text":"Taxation","bold":true},{"text":" (personal income tax, or company tax plus tax on dividends)"}]},{"text":[{"text":"Nature and size","bold":true},{"text":" of the business and its risk"}]},{"text":[{"text":"Profit sharing","bold":true},{"text":" (kept by one owner or split)"}]},{"text":[{"text":"Privacy","bold":true},{"text":" (how much must be disclosed publicly)"}]},{"text":[{"text":"Government regulation","bold":true}]},{"text":[{"text":"Transferability","bold":true},{"text":" of ownership interest"}]}]},{"type":"paragraph","text":[{"text":"Comparison:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Sole proprietor"}],[{"text":"Partnership"}],[{"text":"Company"}],[{"text":"Cooperative"}],[{"text":"Public corporation"}]],"rows":[[[{"text":"Owners"}],[{"text":"One"}],[{"text":"2 or more partners"}],[{"text":"Shareholders"}],[{"text":"Members"}],[{"text":"Government"}]],[[{"text":"Liability"}],[{"text":"Unlimited"}],[{"text":"Unlimited (ordinary)"}],[{"text":"Limited"}],[{"text":"Usually limited"}],[{"text":"Government bears"}]],[[{"text":"Legal entity"}],[{"text":"No"}],[{"text":"No (ordinary)"}],[{"text":"Yes"}],[{"text":"Yes, once registered"}],[{"text":"Yes"}]],[[{"text":"Continuity"}],[{"text":"Ends with owner"}],[{"text":"Unstable"}],[{"text":"Perpetual"}],[{"text":"Continues"}],[{"text":"Perpetual"}]],[[{"text":"Main aim"}],[{"text":"Profit"}],[{"text":"Profit"}],[{"text":"Profit"}],[{"text":"Serve members"}],[{"text":"Public service"}]],[[{"text":"Raises funds by"}],[{"text":"Savings, loans"}],[{"text":"Partners' capital, loans"}],[{"text":"Shares, debentures, loans"}],[{"text":"Members' shares, savings"}],[{"text":"Government funds, bonds"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match form to need: a small barbing salon suits a sole proprietorship; professionals sharing skills, a partnership; a manufacturer needing billions of naira, a public company selling shares on the NGX; market women wanting cheap loans, a cooperative; essential services, a public corporation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the forms of business ownership are sole proprietorship, partnership, company (corporation), cooperative and public enterprise. Financial contracts such as an "},{"text":"interest rate swap","bold":true},{"text":" (exchanging interest payments), a bond or a lease are "},{"text":"not","bold":true},{"text":" forms of business ownership."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietor: one owner, unlimited liability, total control, easy to form, ends when the owner dies or closes it."}]},{"text":[{"text":"Partnership: 2 or more share profits and losses; no written agreement needed; no agreement = share equally; pooled skills but unlimited liability; cannot issue shares."}]},{"text":[{"text":"8 partners: active, sleeping, nominal, estoppel, profits only, minor, secret, sub-partner."}]},{"text":[{"text":"Company: separate legal entity owned by shareholders, limited liability, perpetual succession, raises capital by issuing shares; double taxation is its classic drawback."}]},{"text":[{"text":"Private (Ltd) cannot offer shares to the public; public (Plc) can and may list on the NGX. In Nigeria, CAMA 2020 and the CAC."}]},{"text":[{"text":"Public corporation: government-owned by statute for essential services; two types, essential and commercial; not the same as a public company."}]},{"text":[{"text":"Cooperative: owned and controlled by members to serve members; one member, one vote; surplus shared by patronage."}]},{"text":[{"text":"Choose by capital, liability, control, formation cost, continuity, tax, size, privacy, regulation."}]}]}],"theory":{"itemId":"284bd3a0-7fda-51d7-a7e6-2dcf4eab1916","question":[{"type":"paragraph","text":[{"text":"Tunde and Amaka are partners with capitals of ₦5,000,000 and ₦3,000,000. Profit for the year is ₦2,400,000. (a) The deed allows 5% interest on capital and shares the remainder 3:1. Find each partner's share. (b) What would each get if there were no partnership agreement?"}]}]},"practice":[{"topic":"Forms of Business Firm","named":false}]}}]$expected_content$::jsonb,
  'introduction-finance: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('203d7e61-c829-5419-a664-5a478e05a8a6')
  where kind = 'cbt_question'), 0,
  'introduction-finance: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '203d7e61-c829-5419-a664-5a478e05a8a6' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"8f13135a-1c58-5e40-9229-3e6cb52d3bfb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eb7df00e-9d32-51c5-952e-0cbf2a8d292b","sourceKey":"bank:FIN101:F101N1-001","parentItemId":null,"revision":1,"payload":{"prompt":"Finance is defined as the management of money and ------","options":["human resources","money claims","production inputs","physical assets"],"correctOption":1,"section":"Overview of Finance","explanation":"Finance is the management of money and money claims, which is why it is often summed up as 'finance is money'. Physical assets and production inputs are things money is used to acquire, but managing them is not what defines finance."}},{"itemId":"152cf78d-a72d-5585-92f0-6a550a4ecad4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"43f16ab7-301a-5da6-8862-39691d2df608","sourceKey":"bank:FIN101:F101N1-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes what finance deals with in a business firm?","options":["The design and promotion of the firm's products","The recruitment and training of the firm's staff","The physical movement of goods from factory to customer","The inflows and outflows of money (funds) within the firm"],"correctOption":3,"section":"Overview of Finance","explanation":"Finance deals with money (funds) coming into the firm and money going out of it, and this is what links all the other business activities together. Moving goods to customers is distribution, and recruiting staff is a personnel matter, so neither describes the focus of finance."}},{"itemId":"76436ddc-5e5a-56a6-a948-7378a7aa5346","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2ef74add-7874-5268-9c03-0a902591a6c0","sourceKey":"bank:FIN101:F101N1-003","parentItemId":null,"revision":1,"payload":{"prompt":"The three branches of finance are","options":["personal finance, business finance and public finance","business finance, public finance and behavioural finance","public finance, international finance and personal finance","personal finance, business finance and international finance"],"correctOption":0,"section":"Overview of Finance","explanation":"Finance is grouped into three branches: personal finance for individuals, business finance for firms and public finance for government. Each of the other options swaps one of these for a field that is not among the three branches, such as international finance."}},{"itemId":"e93e0e46-24ba-523e-907a-1d53a3fe2d1f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7713ee94-26f7-5207-a641-c135a41352c0","sourceKey":"bank:FIN101:F101N1-004","parentItemId":null,"revision":1,"payload":{"prompt":"The Federal Government of Nigeria planning how to raise tax revenue and spend it on roads and hospitals is an example of which branch of finance?","options":["Personal finance","Corporate finance","Business finance","Public finance"],"correctOption":3,"section":"Overview of Finance","explanation":"Public finance is the branch that deals with the finances of government, such as raising revenue and deciding on public spending. Business (corporate) finance is about how firms raise and use funds, not how government does it."}},{"itemId":"8019c5fe-befc-55b3-8891-931632357ee3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"dc7a5be0-f5eb-575e-949b-41c1bdeb3fb8","sourceKey":"bank:FIN101:F101N1-005","parentItemId":null,"revision":1,"payload":{"prompt":"Finance includes six activities: saving, borrowing, lending, investing, budgeting and forecasting. Which of the following is NOT one of them?","options":["Forecasting","Budgeting","Lending","Auditing"],"correctOption":3,"section":"Overview of Finance","explanation":"The six activities included in finance are saving, borrowing, lending, investing, budgeting and forecasting, so auditing is the odd one out. Budgeting and forecasting may look less like 'money' activities, but both are part of planning how funds will be raised and used."}},{"itemId":"d2b08f14-24e1-592e-9c25-1c6a2ce67805","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"48c08d72-3498-50fc-99e9-631e68ca195d","sourceKey":"bank:FIN101:F101N1-006","parentItemId":null,"revision":1,"payload":{"prompt":"Business (corporate) finance is mainly concerned with how firms make which two decisions?","options":["Recruitment and promotion decisions","Marketing and production decisions","Pricing and distribution decisions","Investment and financing decisions"],"correctOption":3,"section":"Overview of Finance","explanation":"Business or corporate finance focuses on how firms decide what to invest in and how to finance those investments. Marketing, production and pricing decisions are handled by other functions, even though finance links them together."}},{"itemId":"e0a3c358-2bc1-569e-9bf6-a84e3c6be963","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"24b3abf6-f18d-5e15-9a7e-ec90ce98fcdd","sourceKey":"bank:FIN101:F101N1-007","parentItemId":null,"revision":1,"payload":{"prompt":"A student lists reasons why finance is important to a business firm. Which item on her list is wrong?","options":["It guarantees that the firm will never make a loss","It enhances business growth","It is a new discipline which has grown rapidly","It links all other activities of the business together"],"correctOption":0,"section":"Overview of Finance","explanation":"Finance enhances business growth, serves as a standard for measuring performance, links all other activities together and is a fast-growing new discipline. No amount of good financial management can guarantee that a firm will never make a loss."}},{"itemId":"4e68d464-7936-5afe-8c25-64d1f7de0fdc","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eb46e55f-32b3-51c1-ac38-c6c077aa7da2","sourceKey":"bank:FIN101:F101N1-008","parentItemId":null,"revision":1,"payload":{"prompt":"The liquidity decision of a firm is otherwise known as the","options":["working capital decision","capital mix decision","profit allocation decision","capital budgeting decision"],"correctOption":0,"section":"Overview of Finance","explanation":"The liquidity decision is about managing the firm's short-term assets and liabilities, which is why it is also called the working capital decision. Capital budgeting is the other name for the investment decision, while capital mix refers to the financing decision."}},{"itemId":"0f8e2ea7-f83d-59f2-bffb-11b6d72e5660","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"391d2c4c-b4ac-545e-a541-2c54fc90de4f","sourceKey":"bank:FIN101:F101N1-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the four finance decisions (functions) of a firm?","options":["Production, financing, dividend and liquidity decisions","Investment, marketing, dividend and liquidity decisions","Investment, financing, dividend and liquidity decisions","Investment, financing, dividend and acquisition decisions"],"correctOption":2,"section":"Overview of Finance","explanation":"The four finance decisions are investment (capital budgeting), financing (capital mix), dividend and liquidity (working capital) decisions. Acquisition is the tempting extra item, but it is not one of the four finance functions."}},{"itemId":"792ceb1a-2d1e-5f0f-bc61-09495cfd5a60","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"504e37a7-7988-57b5-ab53-dd4f8048a294","sourceKey":"bank:FIN101:F101N1-010","parentItemId":null,"revision":1,"payload":{"prompt":"The financing decision seeks the best mix of funds at the cheapest cost and most favourable tax position. Its ultimate aim is to maximise the firm's","options":["total amount of debt","market price per share","number of employees","total sales revenue"],"correctOption":1,"section":"Overview of Finance","explanation":"The financing decision chooses the best capital structure so as to maximise the market price per share (MPS), which reflects shareholders' wealth. Taking on more debt is not the goal in itself; debt is only part of the mix chosen to achieve a higher share price."}},{"itemId":"1fbcd736-42ec-5cd3-8aeb-c442a9f8ca68","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c399197e-a3c4-54a7-9509-aa59f5b64094","sourceKey":"bank:FIN101:F101N1-011","parentItemId":null,"revision":1,"payload":{"prompt":"The board of a company in Lagos is deciding whether to pay out 40% of this year's earnings to shareholders and retain the remaining 60%. This is a","options":["liquidity decision","dividend decision","financing decision","investment decision"],"correctOption":1,"section":"Overview of Finance","explanation":"Deciding what proportion of earnings to pay out as dividends and what proportion to retain is the dividend decision. It is not the financing decision, which is about choosing the mix of debt and equity used to fund the firm."}},{"itemId":"8888d706-fa2d-5687-b011-026ca58c40ad","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eb3f65a4-e184-5f55-8891-dd6189e3c272","sourceKey":"bank:FIN101:F101N1-012","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturing firm in Ikeja is deciding whether to commit N50 million to a new machine expected to yield benefits over the next five years. This is an example of the","options":["dividend decision","financing (capital mix) decision","investment (capital budgeting) decision","liquidity (working capital) decision"],"correctOption":2,"section":"Overview of Finance","explanation":"Allocating capital funds to a proposal that will yield benefits in future years is the investment, or capital budgeting, decision. The financing decision would come in only when the firm decides how to raise the N50 million, not whether to buy the machine."}},{"itemId":"a367268a-b1d3-5887-8ef5-bdecae79a209","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"90bf1a53-bedd-52cb-a315-49f3cee2d36f","sourceKey":"bank:FIN101:F101N1-013","parentItemId":null,"revision":1,"payload":{"prompt":"The profit maximisation objective was developed in the early 19th century, when most firms were","options":["sole proprietorships that were self-financed","large public companies financed by issuing shares","multinational partnerships financed by bank loans","government-owned corporations financed by taxes"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Profit maximisation arose in the early 19th century when firms were mostly sole proprietorships financing themselves, so the owner and the business were effectively the same. Large public companies financed by shares came later, and their wider ownership is part of why wealth maximisation became preferred."}},{"itemId":"b7793505-b365-524b-ac1e-4be0249da18d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f2c4dce5-12b6-582d-a97f-69dee390a4e1","sourceKey":"bank:FIN101:F101N1-014","parentItemId":null,"revision":1,"payload":{"prompt":"Under the profit maximisation objective, a firm aims to","options":["maximise dividends paid while minimising retained earnings","minimise its sales revenue while maximising its market share","maximise revenue from sales of output while minimising the cost of producing that output","maximise both its sales revenue and its cost of production"],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"Profit is revenue minus cost, so profit maximisation means earning as much revenue as possible from sales while keeping the cost of production as low as possible. Maximising both revenue and cost would not necessarily increase profit at all."}},{"itemId":"6e8f99ba-0068-506d-a2b2-aeeba9d0d5c9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0db1a0a8-80da-5833-9fc7-e0702400fb9d","sourceKey":"bank:FIN101:F101N1-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a criticism of the profit maximisation objective?","options":["It is difficult to measure as an objective","Profit has no clear definition","It ignores the time value of money","It ignores the risk or uncertainty of future earnings"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Profit maximisation is actually easy to measure, which is one of its attractions. Its weaknesses are that it ignores the time value of money, ignores risk, has no clear definition of profit, ignores the quality of future activities and does not give all participants a satisfactory return."}},{"itemId":"938c1b4a-077e-54b0-964d-3d0a4ca20536","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c7e882b2-85c9-53df-a95b-53d0b0c5b5b1","sourceKey":"bank:FIN101:F101N1-016","parentItemId":null,"revision":1,"payload":{"prompt":"A critic of profit maximisation asks: 'Is it profit before tax or after tax? Short-term or long-term profit?' Which weakness of the objective is being pointed out?","options":["It ignores the quality of future activities","It ignores the time value of money","Profit has no clear definition","It ignores the risk of future earnings"],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"Questions about whether profit means before-tax or after-tax, short-term or long-term, show that profit has no clear definition. The time value of money criticism is about when returns are received, not about how profit is defined."}},{"itemId":"ed05fb5c-917e-5536-a8d5-78836a3e2566","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"70c147b9-306a-55dc-9374-31141c293e87","sourceKey":"bank:FIN101:F101N1-017","parentItemId":null,"revision":1,"payload":{"prompt":"Project P is expected to earn a total profit of N10 million in its first year, while Project Q is expected to earn the same N10 million but only in its fifth year. A firm pursuing profit maximisation would rank them equally. This shows that profit maximisation","options":["has no clear definition of profit","ignores the time value of money","ignores the risk of future earnings","ignores the quality of future activities"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"A naira received in year 1 is worth more than a naira received in year 5, yet profit maximisation treats the two projects as equal, so it ignores the time value of money. The risk criticism would apply if the projects differed in how certain their profits were, not in when the profits arrive."}},{"itemId":"91405572-1d81-53be-8cdb-7c7450a1a62f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b2f8fc8b-416f-5c4a-b4c0-7ef5e52de6f5","sourceKey":"bank:FIN101:F101N1-018","parentItemId":null,"revision":1,"payload":{"prompt":"Two projects are each expected to earn N8 million profit next year. The first project's profit is almost certain, while the second could range widely from a loss to a large gain. Profit maximisation would treat them as equally attractive. This shows that profit maximisation","options":["ignores the risk or uncertainty of future earnings","has no clear definition of profit","ignores the time value of money","ignores the satisfaction of employees"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Both projects give the same expected profit, but one is far more uncertain, and profit maximisation does not distinguish between them, so it ignores risk. The time value of money is not the issue here, because both profits are expected at the same time."}},{"itemId":"0ce1291b-f76b-5f23-b9fa-ab367c494c1e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"52445cdf-22bf-5a0a-a746-338e232468c2","sourceKey":"bank:FIN101:F101N1-019","parentItemId":null,"revision":1,"payload":{"prompt":"Shareholders' wealth maximisation is defined as the maximisation of the","options":["total sales revenue of the firm","accounting profit for the current year","book value of the firm's total assets","Net Present Value (NPV) of a course of action"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Wealth maximisation means maximising the Net Present Value of a course of action, that is, the present value of its benefits minus the initial investment needed. Current-year accounting profit is the focus of profit maximisation, which ignores timing and risk."}},{"itemId":"ebfe1ac9-07da-5759-9bb7-28e1d33e5140","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"625050fb-04e4-5390-a08e-16e9db46e602","sourceKey":"bank:FIN101:F101N1-020","parentItemId":null,"revision":1,"payload":{"prompt":"A firm in Ikeja estimates that the present value of the benefits of a proposed project is N12,500,000, and the initial investment required is N9,800,000. What is the Net Present Value of the project?","options":["-N2,700,000","N22,300,000","N12,500,000","N2,700,000"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"NPV is the present value of benefits minus the initial investment: N12,500,000 - N9,800,000 = N2,700,000. Adding the two figures to get N22,300,000 is a common slip, and N12,500,000 ignores the investment altogether."}},{"itemId":"0726e5c1-4f43-5e3a-819a-095465a79cc4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5f0d45a4-e810-5b13-856e-7c0f5daed1b1","sourceKey":"bank:FIN101:F101N1-021","parentItemId":null,"revision":1,"payload":{"prompt":"The market price of a firm's shares, which determines shareholders' wealth, reflects which managerial decisions?","options":["Recruitment, training and promotion decisions","Marketing, production and sales decisions","Investment, financing and dividend decisions","Pricing, advertising and distribution decisions"],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"The share price reflects the quality of management's investment, financing and dividend decisions, which is why wealth maximisation ties these decisions together. Marketing and production choices affect the firm, but they are not the managerial finance decisions said to be reflected in market price."}},{"itemId":"0d8b608a-f556-5d82-9651-092b27327a31","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6a1ff03e-82dc-51bb-8eaa-690dc1bf8a0e","sourceKey":"bank:FIN101:F101N1-022","parentItemId":null,"revision":1,"payload":{"prompt":"A manager is asked to name the goals a business firm may pursue. Which of these would be wrong to include?","options":["Satisfaction objective","Increase in market share","Maximisation of managers' personal salaries","Survival objective"],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"The objectives of a business firm include profit maximisation, shareholders' wealth maximisation, satisfaction, social responsibility, survival and increase in market share. Maximising managers' own salaries is not among them; the satisfaction objective concerns giving all interest groups a fair return, not enriching managers."}},{"itemId":"0053e93e-1055-54c5-84c6-26df52a179be","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7fde5f58-9043-5ee6-bda8-c81dfa9a5908","sourceKey":"bank:FIN101:F101N1-023","parentItemId":null,"revision":1,"payload":{"prompt":"During a period of keen competition and high inflation, the managers of a firm in Ikeja decide that their main goal is simply to stay in business continuously rather than make a big profit this year and close down next year. Which objective are they pursuing?","options":["Social responsibility objective","Profit maximisation","Increase in market share","Survival objective"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Staying in business continuously, especially in an economic downturn with keen competition and inflation, is the survival objective, described as the most important one for modern managers in such times. Profit maximisation is the very thing they are setting aside in favour of simply staying afloat."}},{"itemId":"c19482ed-ed96-51ee-8988-5eed49e4ec26","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c9c4cd86-0ffc-50ab-977a-7926af4879b6","sourceKey":"bank:FIN101:F101N1-024","parentItemId":null,"revision":1,"payload":{"prompt":"A company operating in a rural community provides pipe-borne water, builds roads and awards scholarships to indigenes of its host community. Which objective is the company pursuing?","options":["Survival objective","Increase in market share","Satisfaction objective","Social responsibility objective"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Improving the operating environment through community development, such as water, roads and scholarships for indigenes, is the social responsibility objective. The satisfaction objective is about giving interest groups like customers and creditors a satisfactory return for their inputs, not about developing the host community."}},{"itemId":"d058449d-20b4-547f-a2eb-d22f91859157","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f0b5037d-e7cd-5988-b2f6-d65df7ab3bea","sourceKey":"bank:FIN101:F101N1-025","parentItemId":null,"revision":1,"payload":{"prompt":"Profit maximisation is criticised for not giving all participants, such as customers, creditors, employees and government, a satisfactory return. Which objective of a firm directly addresses this weakness?","options":["Survival objective","Profit maximisation","Satisfaction objective","Increase in market share"],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"The satisfaction objective is an attempt to give all participants a satisfactory return for their inputs or efforts, which is exactly what profit maximisation fails to do. Increasing market share is about capturing more of market demand, not about rewarding all interest groups."}},{"itemId":"1c0f6b48-491c-57bb-b294-781f59c1365d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"da922c5f-2305-5a31-9c53-955d31f52e77","sourceKey":"bank:FIN101:F101N1-026","parentItemId":null,"revision":1,"payload":{"prompt":"A situation in which the future outcome is unknown and the probability of its occurrence cannot be estimated is described as","options":["liquidity risk","uncertainty","risk","business risk"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Uncertainty exists when the outcome is unknown and its probability cannot be estimated. Risk is the tempting choice, but under risk the outcome is unknown while the likelihood of each outcome can be estimated."}},{"itemId":"354d13e2-49ea-5be5-946a-6416f49a59fd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"bf08997c-81de-5048-8633-ffd6f2ad7aec","sourceKey":"bank:FIN101:F101N1-027","parentItemId":null,"revision":1,"payload":{"prompt":"The receipt a borrower issues to a lender as evidence of the promise to repay the capital is known as a","options":["financial market","financial security","financial system","financial intermediary"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A financial security (or instrument) is the receipt the borrower gives the lender as evidence of the promise to repay. The financial market is the place or system where such securities are traded, not the receipt itself."}},{"itemId":"451ccee5-b7b2-53f0-a600-1eea87aa93e4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"89fe7ccf-2432-5a01-864f-9797676c03a8","sourceKey":"bank:FIN101:F101N1-028","parentItemId":null,"revision":1,"payload":{"prompt":"The maximum period of funds dealt with in the money market is","options":["more than one year","one year or less","ten years","five years"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The money market deals only in short-period funds with a maximum period of one year or less. Securities with a life span of more than one year belong to the capital market."}},{"itemId":"fcf424fa-661a-5951-9783-0bc99a232547","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d3b59940-9653-5448-9af3-ffe7f71d7491","sourceKey":"bank:FIN101:F101N1-029","parentItemId":null,"revision":1,"payload":{"prompt":"Treasury bills, used for short-term government borrowing in Nigeria, are usually issued by the","options":["Nigerian Exchange Group","Corporate Affairs Commission","Central Bank of Nigeria","Securities and Exchange Commission"],"correctOption":2,"section":"Introduction to Financial Markets","explanation":"Treasury bills are short-term government borrowing instruments usually issued by the Central Bank, which is also the apex regulator of the money market. The Securities and Exchange Commission regulates the capital market rather than issuing government bills."}},{"itemId":"716013e9-f686-5014-926c-658edcd42023","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c2720e31-91c7-5c60-921e-19c7d0e7dd78","sourceKey":"bank:FIN101:F101N1-030","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos sells government securities to another bank and agrees to buy back the same securities next week at a set price. This money market instrument is a","options":["repurchase agreement","treasury bill","banker's acceptance","certificate of deposit"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"Selling a security and later buying back the same security is a repurchase agreement. A treasury bill is the security that may be sold under such an arrangement, but the sell-and-buy-back deal itself is the repurchase agreement."}},{"itemId":"5357e4b7-552f-5359-bca7-41702e57cf1b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3540b695-9bd3-5b70-a596-2e06062ddbea","sourceKey":"bank:FIN101:F101N1-031","parentItemId":null,"revision":1,"payload":{"prompt":"A Balogun market importer promises to pay a foreign seller for goods, and the importer's bank guarantees that promise. This money market instrument is a","options":["commercial paper","banker's acceptance","repurchase agreement","certificate of deposit"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A banker's acceptance is a buyer's promise to pay the seller that is guaranteed by the buyer's bank. Commercial paper is also a promise to pay, but it is backed only by the issuing company's own promise, not by a bank's guarantee."}},{"itemId":"197d75ac-4a96-5e3b-a86a-4a61c06ba361","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eb478193-8ec4-5d1f-9a92-73af00176675","sourceKey":"bank:FIN101:F101N1-032","parentItemId":null,"revision":1,"payload":{"prompt":"A money market instrument issued by a bank as a written promise that gives the bearer the right to interest is a","options":["certificate of deposit","repurchase agreement","treasury bill","banker's acceptance"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"A certificate of deposit is issued by a bank and entitles its bearer to interest on the deposit. A banker's acceptance also involves a bank, but there the bank is guaranteeing a buyer's promise to pay a seller."}},{"itemId":"01ced825-6424-5743-a4a4-4e381c8e085c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8ab57a0e-b366-5818-a4fe-71b4f2ba3e54","sourceKey":"bank:FIN101:F101N1-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a function of the money market?","options":["Serving as a platform for monetary policy","Stabilising the demand and supply of money for short-term transactions","Providing funds for periods of more than one year for long-term capital projects","Providing an avenue for short-term investments"],"correctOption":2,"section":"Introduction to Financial Markets","explanation":"The money market deals only in short-term funds, so providing finance for more than one year is a capital market role. Serving as a platform for monetary policy, offering short-term investments and stabilising short-term money supply are all money market functions."}},{"itemId":"1f96c843-f0b2-5495-be94-82bea9efdd69","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cf58939e-1c6b-5b17-b0cf-32a76044b817","sourceKey":"bank:FIN101:F101N1-034","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Ikeja sells newly issued shares directly to investors through an initial public offering (IPO). This transaction takes place in the","options":["foreign exchange market","secondary market","money market","primary market"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"Newly issued securities sold by the issuing company to investors are traded in the primary market, and IPOs are the typical example. The secondary market deals only in existing securities traded between investors."}},{"itemId":"b2d6530d-0462-58b5-b09a-f143c49f9243","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3f56d6f4-210e-5b19-83aa-d91784c52171","sourceKey":"bank:FIN101:F101N1-035","parentItemId":null,"revision":1,"payload":{"prompt":"In which type of capital market is the issuing company NOT a party to the transaction?","options":["Secondary market","New issues market","Money market","Primary market"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"In the secondary market, existing securities change hands between investors, so the issuing company is not involved. In the primary (new issues) market, the transaction is directly between the issuing company and investors."}},{"itemId":"fcdbbc11-5505-57f2-b062-2a650932b096","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d86e4a86-3c02-56d4-8e61-379d2824006f","sourceKey":"bank:FIN101:F101N1-036","parentItemId":null,"revision":1,"payload":{"prompt":"A financial market participant who buys and sells securities on its own account, rather than for clients in return for a commission, is a","options":["broker","regulator","dealer","rating agency"],"correctOption":2,"section":"Introduction to Financial Markets","explanation":"Dealers trade securities on their own account, taking positions for themselves. Brokers are the tempting choice, but brokers act for clients and earn a commission instead of trading for themselves."}},{"itemId":"2c815c19-f038-5c9d-9660-bb0daac75771","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"aca53777-0c58-54f2-97f3-87526d8ec24b","sourceKey":"bank:FIN101:F101N1-037","parentItemId":null,"revision":1,"payload":{"prompt":"In the Nigerian stock market, the clearing and settlement of trades is handled by the","options":["Central Bank of Nigeria (CBN)","Central Securities Clearing System (CSCS)","Nigeria Deposit Insurance Corporation (NDIC)","Securities and Exchange Commission (SEC)"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The Central Securities Clearing System (CSCS) handles clearing and settlement on the Nigerian stock market. The SEC is the market's regulator; it supervises the market but does not clear and settle trades."}},{"itemId":"35f8eaf2-255f-50ed-8834-22e5e0126ad4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"502de1c2-da0b-5631-87ea-eb2e04977962","sourceKey":"bank:FIN101:F101N1-038","parentItemId":null,"revision":1,"payload":{"prompt":"An instrument on the Nigerian stock market that pays fixed dividends but carries no voting rights is the","options":["preference share","commercial paper","exchange-traded fund","ordinary share"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"Preference shares pay fixed dividends but carry no voting rights. Ordinary shares are the opposite case: they carry voting rights, and their dividends are not fixed."}},{"itemId":"17732985-003f-565d-a05d-712e51b98444","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1114287c-3548-547f-9709-1e5fc60bfc89","sourceKey":"bank:FIN101:F101N1-039","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian stock market is often described as a 'barometer' of the economy. This refers to its role as","options":["the issuer of treasury bills","a clearing and settlement system","the regulator of the capital market","an economic indicator"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"Calling the stock market a barometer means its performance indicates the health of the economy, so it serves as an economic indicator. Regulation is the job of the SEC, not a description of what the market itself signals."}},{"itemId":"05007318-876a-5a7e-bae2-3233977fd8cf","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"50bced91-2db5-5d79-aa35-d549024f25f0","sourceKey":"bank:FIN101:F101N1-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly lists the forms of business firm?","options":["Sole trader, partnership, trade union and public corporation","Sole trader, partnership, limited liability company and public corporation","Sole trader, cooperative society, limited liability company and stock exchange","Partnership, limited liability company, pressure group and public corporation"],"correctOption":1,"section":"Forms of Business Firm","explanation":"The forms of business firm are the sole trader, the partnership, the limited liability company (public and private) and the public corporation. Trade unions, pressure groups and stock exchanges are organisations, but none of them is a form of business firm."}},{"itemId":"c913ae9f-fb68-5bd1-a2d5-7286b28ec7bb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1e9dc5b7-dffb-57cc-ad5a-f098097f5f6e","sourceKey":"bank:FIN101:F101N1-041","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Balogun market buys fabrics in bulk and resells them to customers in small quantities. She owns and runs the business alone. Which type of sole proprietorship is this?","options":["Technology","Retail-based","Consulting-based","Manufacturing-based"],"correctOption":1,"section":"Forms of Business Firm","explanation":"Buying goods and reselling them to customers is retailing, so this is a retail-based sole proprietorship. It is not manufacturing-based, because she does not make the fabrics herself."}},{"itemId":"04fcf576-673a-558a-aa53-d07e99c9c3d4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"aa2b84a2-ca80-547c-8a64-92780c0ae73a","sourceKey":"bank:FIN101:F101N1-042","parentItemId":null,"revision":1,"payload":{"prompt":"Ada runs a hair salon in Yaba as a sole proprietor. Which of the following is NOT a benefit she enjoys from this form of business?","options":["Low start-up costs","Easy set-up","Limited liability for her personal assets","Greater privacy"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A sole proprietor has unlimited liability, so her personal assets can be used to settle business debts. Easy set-up, low start-up costs and greater privacy are genuine benefits of sole proprietorship."}},{"itemId":"e041cbc1-7904-5ca2-b023-f86e4a5a7709","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"731c44bd-7fc6-5321-86ee-778718ceb2ff","sourceKey":"bank:FIN101:F101N1-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of a sole proprietorship?","options":["Barriers to finance","Complete control and flexibility","Simplified taxes","Less paperwork"],"correctOption":0,"section":"Forms of Business Firm","explanation":"A sole proprietor often finds it hard to raise funds, so barriers to finance are a disadvantage. Complete control, simplified taxes and less paperwork are all advantages of this form of business."}},{"itemId":"df9f96b0-1612-56e2-b477-987057fcb298","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3308786b-9d05-5d10-a6ab-970c6a8bd607","sourceKey":"bank:FIN101:F101N1-044","parentItemId":null,"revision":1,"payload":{"prompt":"Emeka runs a printing shop in Surulere alone. At the end of the year he keeps all the profit the business made without giving any part of it to anyone else. Which advantage of a sole proprietorship does this illustrate?","options":["Easy set-up","Greater privacy","Lower accounting fees","No sharing of profits"],"correctOption":3,"section":"Forms of Business Firm","explanation":"Because he is the only owner, Emeka keeps all the profit, which is the advantage of no sharing of profits. Greater privacy relates to not having to disclose business affairs, not to who receives the profit."}},{"itemId":"d9349e31-0e05-5d4e-9a17-47992c3fa9d6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a79f7cf7-5a42-55dc-ba49-5849fba0a9b4","sourceKey":"bank:FIN101:F101N1-045","parentItemId":null,"revision":1,"payload":{"prompt":"'The relation between persons who have agreed to share the profits of a business carried on by all or any of them acting for all' is the legal definition of a","options":["partnership","public corporation","sole proprietorship","single-member limited liability company"],"correctOption":0,"section":"Forms of Business Firm","explanation":"This is the legal definition of a partnership, which involves two or more persons sharing the profits of a business run by all or any of them acting for all. A single-member company or a sole proprietorship has only one owner, so there is no one to share profits with."}},{"itemId":"3662b40d-e041-5e20-913e-50c30850bedf","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"79e08443-d9dc-5960-ab03-3bce7c0c21b1","sourceKey":"bank:FIN101:F101N1-046","parentItemId":null,"revision":1,"payload":{"prompt":"What is the minimum number of people required to form a partnership?","options":["One","Seven","Two","Twenty"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A partnership is an arrangement for two or more people to share responsibility, ownership, profits and losses, so the minimum is two. One person running a business alone is a sole proprietorship, not a partnership."}},{"itemId":"3e4446e1-65b8-58bc-a164-5e3c2818e3ad","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e3de29d8-83d5-5caa-b45e-fb3fd0f021d6","sourceKey":"bank:FIN101:F101N1-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about a partnership agreement is correct?","options":["It must be registered with the Securities and Exchange Commission before trading starts","The law does not require the agreement to be in writing","It is valid only if the partnership has at least seven partners","It is valid only if it is signed before a magistrate"],"correctOption":1,"section":"Forms of Business Firm","explanation":"The law does not require a written partnership agreement, so a partnership can exist on an oral or implied agreement. The other options add formal conditions, such as SEC registration or signing before a magistrate, that are not requirements for a partnership."}},{"itemId":"5719d677-66a5-5018-bcd2-c79e9705ba5d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ad9abf3c-6e3a-5b5b-bd33-e27a1b4299cf","sourceKey":"bank:FIN101:F101N1-048","parentItemId":null,"revision":1,"payload":{"prompt":"Mrs. Adeyemi contributes capital to a partnership in Yaba but takes no part in running the business. She is best described as a","options":["sub-partner","sleeping partner","nominal partner","active partner"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A partner who puts in capital but is inactive in the running of the business is a sleeping (inactive) partner. An active or managing partner is the opposite, because he or she takes part in managing the business."}},{"itemId":"5166ec3e-dc93-5b85-a346-58cd76ddcafd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d83aad57-f593-58c4-ba3a-bdf1b5f104ad","sourceKey":"bank:FIN101:F101N1-049","parentItemId":null,"revision":1,"payload":{"prompt":"A partner by estoppel is also described as a partner by","options":["secret agreement","profits only","nomination","holding out"],"correctOption":3,"section":"Forms of Business Firm","explanation":"A partner by estoppel is also called a partner by holding out. 'Partner in profits only' and 'secret partner' are separate types of partners, not other names for a partner by estoppel."}},{"itemId":"eb022ab0-f917-577b-bc67-56a85555357c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d9d179c5-6820-5ef5-94f4-78481b7bc275","sourceKey":"bank:FIN101:F101N1-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a recognised type of partner?","options":["Nominal partner","Sub-partner","Preference partner","Secret partner"],"correctOption":2,"section":"Forms of Business Firm","explanation":"The types of partners are active (managing), inactive (sleeping), nominal, partner by estoppel, partner in profits only, minor as partner, secret partner and sub-partner. 'Preference' describes a class of shares in a company, not a type of partner."}},{"itemId":"2069cd44-13fa-53f3-b26f-673ab6e9f2d1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4d13fb17-0c20-53de-ae0f-867e4eb758f9","sourceKey":"bank:FIN101:F101N1-051","parentItemId":null,"revision":1,"payload":{"prompt":"The term 'coopetition' describes","options":["a buyer-supplier relationship","a strategic partnership between competitors","a partnership in which one partner is a minor","a strategic alliance between non-competitors"],"correctOption":1,"section":"Forms of Business Firm","explanation":"Coopetition combines cooperation and competition: it is a strategic partnership between firms that compete with each other. A strategic alliance between non-competitors is a separate type of partnership."}},{"itemId":"6cf5d5e2-e50d-52b9-a5b7-69b4af929632","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0da3ca00-257a-5453-a487-f45c0452342b","sourceKey":"bank:FIN101:F101N1-052","parentItemId":null,"revision":1,"payload":{"prompt":"Partnership arrangements between firms take four forms. Which of the following is NOT one of those forms?","options":["Partnership by estoppel","Buyer-supplier relationships","Joint ventures","Strategic alliances between non-competitors"],"correctOption":0,"section":"Forms of Business Firm","explanation":"The four types of partnerships are strategic alliances between non-competitors, strategic partnerships between competitors, joint ventures and buyer-supplier relationships. 'Estoppel' is used for a type of partner (a partner by estoppel or holding out), not for a type of partnership."}},{"itemId":"291864bb-bfc3-50c5-84dd-2cb590816365","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"25a2d3c9-600e-5182-973e-b1d816ee2577","sourceKey":"bank:FIN101:F101N1-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a drawback, rather than a benefit, of forming a partnership?","options":["Loss of autonomy","Additional capital","New perspective","Shared responsibilities"],"correctOption":0,"section":"Forms of Business Firm","explanation":"In a partnership each partner must consult the others, so loss of autonomy is a disadvantage. Additional capital, shared responsibilities and a new perspective are all advantages of bringing in partners."}},{"itemId":"526bb72f-d2d0-5576-b622-a8f81e804770","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fff286cb-5ffd-5212-8a55-708ab7d40623","sourceKey":"bank:FIN101:F101N1-054","parentItemId":null,"revision":1,"payload":{"prompt":"Each of the following is a disadvantage of a partnership EXCEPT","options":["conflict among partners","splitting of profits","lack of stability","emotional support"],"correctOption":3,"section":"Forms of Business Firm","explanation":"Emotional support from partners is an advantage of a partnership. Conflict, lack of stability and having to split profits are all disadvantages."}},{"itemId":"921e0dec-f9b6-5b5b-a9e5-0d6c5aaeb35a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a50cd109-a84f-5677-9b93-e2534cf26562","sourceKey":"bank:FIN101:F101N1-055","parentItemId":null,"revision":1,"payload":{"prompt":"Funke invested N2,000,000 in the shares of a limited liability company in Ikeja. The company later collapsed owing creditors N50,000,000. What is the maximum amount Funke can lose?","options":["N50,000,000","N25,000,000","N2,000,000","Nothing at all"],"correctOption":2,"section":"Forms of Business Firm","explanation":"Limited liability restricts a shareholder's loss to her stake in the company, so the most Funke can lose is the N2,000,000 she invested. She is not personally liable for the company's N50,000,000 debts; that would only happen under unlimited liability, as in a sole proprietorship."}},{"itemId":"5ef954fe-b3bb-5f01-a6b2-35c0e344e595","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c0feea89-5276-501c-87a0-ccdbb4af4837","sourceKey":"bank:FIN101:F101N1-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes a business enterprise (business name) from a limited liability company?","options":["Both are separate legal entities, but only the enterprise has limited liability","A company is a separate legal entity with limited liability, while an enterprise is not a separate legal entity and its owner is personally liable","Neither is a separate legal entity, so both owners are personally liable","An enterprise is a separate legal entity with limited liability, while a company's owners are personally liable"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A limited liability company is a separate legal entity, so its owners have limited liability, while an enterprise is not separate from its owner, who is personally liable. The most tempting wrong statement simply reverses the two forms."}},{"itemId":"76300153-d9c1-58fd-a3a4-e1b019c34a51","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"20c95c03-5d93-5af6-87c3-75512c797ba6","sourceKey":"bank:FIN101:F101N1-057","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of a limited liability company (LLC)?","options":["Roles can be unclear without a proper operating agreement","Limited personal liability","Added credibility","Less record-keeping than corporations"],"correctOption":0,"section":"Forms of Business Firm","explanation":"Without a proper operating agreement, members' roles in an LLC can be unclear, which is a disadvantage. Limited personal liability, added credibility and less record-keeping are all advantages of the LLC form."}},{"itemId":"23cae683-bd02-5009-b472-d9b6968b08cb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"275a11b2-d12d-59e4-97cb-194092d820eb","sourceKey":"bank:FIN101:F101N1-058","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde runs a printing business alone and wants to remain the only owner, but he also wants his personal house protected from the business's debts. Which form of business best meets both needs?","options":["Multi-member limited liability company","Sole proprietorship","Single-member limited liability company","Partnership"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A single-member LLC has one owner, like a sole proprietorship, but gives that owner liability protection. A sole proprietorship would keep him as the only owner but expose his house to unlimited liability."}},{"itemId":"f1cfb969-595c-51fe-8451-a7e2d169accb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"987e37be-e069-5db5-b631-1098a43b3a96","sourceKey":"bank:FIN101:F101N1-059","parentItemId":null,"revision":1,"payload":{"prompt":"A business set up by an Act of Parliament, owned and managed by government to provide essential services at affordable cost, is a","options":["public limited company","partnership","private limited company","public corporation"],"correctOption":3,"section":"Forms of Business Firm","explanation":"A public corporation is created by an Act of Parliament and is owned and managed by government to provide essential services at affordable cost. A public limited company sounds similar, but it is privately owned and offers its shares to the public."}},{"itemId":"5401f01a-9ae8-5adf-8803-d66618f696b6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ce642714-71ba-5c37-b5bc-116f379796f6","sourceKey":"bank:FIN101:F101N1-060","parentItemId":null,"revision":1,"payload":{"prompt":"The main difference between a public corporation and a public limited company (PLC) is that","options":["both are privately owned, but only a public corporation offers shares to the public","a PLC is government-owned and provides essential services, while a public corporation is privately owned","a public corporation is government-owned and provides essential services, while a PLC is privately owned and offers shares to the public","both are government-owned, but only a PLC provides essential services"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A public corporation is owned by government to provide essential services, while a PLC is privately owned and sells its shares to the public. The word 'public' in both names misleads many students into swapping the two, as in the reversed statement."}},{"itemId":"3a7075de-a23a-5c57-8042-50b32cc197f1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"403e3767-34a7-5288-b009-b09a711b5821","sourceKey":"bank:FIN101:F101N1-061","parentItemId":null,"revision":1,"payload":{"prompt":"A state government owns and runs a hotel and a textile mill. These are examples of which type of public corporation?","options":["Multi-member limited liability companies","Commercial public corporations","Essential services public corporations","Private limited companies"],"correctOption":1,"section":"Forms of Business Firm","explanation":"State-owned hotels, textile mills, banks and transport services are commercial public corporations. Essential services public corporations provide basic services such as water and housing."}},{"itemId":"64575809-0fe8-503c-9b44-2944221ff64b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8b6c7710-cdf6-595d-9a0b-b8427e160850","sourceKey":"bank:FIN101:F101N1-062","parentItemId":null,"revision":1,"payload":{"prompt":"A state water corporation and the Federal Housing Authority are examples of which type of public corporation?","options":["Essential services public corporations","Public limited companies","Commercial public corporations","Partnerships"],"correctOption":0,"section":"Forms of Business Firm","explanation":"Water corporations and the Federal Housing Authority provide basic services to the public, so they are essential services public corporations. Commercial public corporations run business-type activities such as hotels, textile mills and state-owned banks."}},{"itemId":"e019e9aa-4af4-59bd-87a1-918d12cfa5f9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"60dd6792-8f63-5fd0-85a0-392224d1c95e","sourceKey":"bank:FIN101:F101N1-063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following qualifies as a Nigerian public corporation?","options":["A provision shop owned by one trader in Balogun market","A family-owned private limited company in Ikeja","A two-partner law firm in Yaba","Nigerian Railway Corporation (NRC)"],"correctOption":3,"section":"Forms of Business Firm","explanation":"The Nigerian Railway Corporation is government-owned and provides an essential service, so it is a public corporation. The provision shop is a sole proprietorship, the law firm is a partnership and the family company is a private limited company."}},{"itemId":"45839dcb-8a85-5dba-89d5-f37b77e803ec","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2367c363-1425-5723-b00b-7e6ed6943fd7","sourceKey":"bank:FIN101:FIN-0001","parentItemId":null,"revision":1,"payload":{"prompt":"Finance is primarily concerned with:","options":["Overseeing workforce productivity","Managing monetary resources and investments","Promoting goods to consumers","Structuring organizational hierarchies"],"correctOption":1,"section":"Overview of Finance","explanation":"Finance is the study and management of money: how funds are raised, invested and used, so B is correct. Options A and D describe human resources and organisation design, while C is marketing, so none of them is the core of finance."}},{"itemId":"26e3a2a5-166c-559d-aedf-370fcd73ae30","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ae85c203-9704-5509-b803-ed4ede155b20","sourceKey":"bank:FIN101:FIN-0002","parentItemId":null,"revision":1,"payload":{"prompt":"The main goal of financial management is to:","options":["Limit company earnings","Maximize shareholder wealth over time","Cut employee compensation costs","Evade fiscal obligations"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Financial managers aim to maximise shareholder wealth, which means increasing the long-run value of the owners' investment, usually seen in the share price. Option C (cutting staff pay) and D (evading taxes) are not goals, and evading taxes is illegal; limiting earnings in A works against the owners."}},{"itemId":"d2907f88-fc2a-5f29-aa86-f4d7b44a5bb5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f19b069d-e06f-550f-85e1-4ff5d0a89ff2","sourceKey":"bank:FIN101:FIN-0003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key area of finance?","options":["Corporate finance for business funding","Product innovation and design","Staff development programs","Consumer behavior analysis"],"correctOption":0,"section":"Overview of Finance","explanation":"Corporate finance, which deals with how businesses raise and use funds, is one of the main areas of finance alongside personal and public finance. Options B, C and D belong to production, human resources and marketing respectively."}},{"itemId":"027b2bd1-8bf6-5832-b45d-618d0c7c70d2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"000612e3-1a04-58d0-96de-2e916ec12703","sourceKey":"bank:FIN101:FIN-0004","parentItemId":null,"revision":1,"payload":{"prompt":"Personal finance focuses on:","options":["Directing corporate cash flows","Handling an individual's financial assets","Administering public sector budgets","Facilitating global trade deals"],"correctOption":1,"section":"Overview of Finance","explanation":"Personal finance is about how an individual or household manages income, savings, spending and investments, so B fits. Option A is corporate finance, C is public finance, and D is international trade."}},{"itemId":"e4c9bcad-9acd-5efc-a4f3-3e11b24d2a24","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f20ae0bf-a5ac-5362-b2c8-c5d61829ee2b","sourceKey":"bank:FIN101:FIN-0005","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money is a fundamental concept in:","options":["Market segmentation strategies","Finance and investment decisions","Employee relations management","Production process optimization"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"The time value of money says that money available now is worth more than the same amount later because it can earn a return, which makes it central to finance and investment decisions (B). Options A, C and D are marketing, human resources and production topics that do not rely on this idea."}},{"itemId":"590a3426-083e-5fe0-a62a-a0b7f6b2566f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5d516941-f63d-559b-9a3c-84aeea260926","sourceKey":"bank:FIN101:FIN-0006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a role of a financial manager?","options":["Recruiting new team members","Evaluating investment opportunities","Crafting product prototypes","Analyzing market demographics"],"correctOption":1,"section":"Overview of Finance","explanation":"A main job of the financial manager is the investment decision: assessing which projects or assets are worth putting money into. Recruiting staff (A) is human resources, prototypes (C) is production, and demographics (D) is marketing research."}},{"itemId":"bf692b05-4e27-5db5-affa-fe1edbaedb35","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3d0887e4-8819-5a27-9d7d-6a6097b9d79e","sourceKey":"bank:FIN101:FIN-0007","parentItemId":null,"revision":1,"payload":{"prompt":"The study of finance helps in:","options":["Optimizing resource allocation decisions","Minimizing competitive pressures","Sidestepping financial foresight","Disregarding economic indicators"],"correctOption":0,"section":"Overview of Finance","explanation":"Finance helps decision makers allocate scarce funds to the uses that give the best return for the risk taken, so A is correct. Options C and D are the opposite of what finance teaches, and B is not something studying finance achieves."}},{"itemId":"e3f4893c-b9e6-552a-8fa2-009a2fb7e0a0","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a73f2eaf-dd74-5783-8d3a-7d8f6a6d1752","sourceKey":"bank:FIN101:FIN-0008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a type of financial decision?","options":["Setting product price points","Planning capital expenditures","Selecting new hires","Developing ad campaigns"],"correctOption":1,"section":"Overview of Finance","explanation":"Planning capital expenditure is an investment decision, one of the core financial decisions alongside financing and dividend decisions. Pricing (A) and advertising (D) are marketing choices, and hiring (C) is a human resources choice."}},{"itemId":"2119dfb0-2c9a-5788-9ca8-a01f8810f773","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2e9b6a21-7903-55da-a0b1-ab243d02dcd5","sourceKey":"bank:FIN101:FIN-0009","parentItemId":null,"revision":1,"payload":{"prompt":"The field of finance includes:","options":["Investments and financial market dynamics","Exclusively ledger maintenance","Solely promotional activities","Purely manufacturing processes"],"correctOption":0,"section":"Overview of Finance","explanation":"Finance covers investments and the workings of financial markets, among other areas. Options B, C and D use words like \"exclusively\", \"solely\" and \"purely\", and they describe bookkeeping, promotion and manufacturing rather than the broad field of finance."}},{"itemId":"fc437e3e-f6ad-57ab-af2d-032a00acf095","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f8fb67ab-068e-528e-8934-201f7f321657","sourceKey":"bank:FIN101:FIN-0010","parentItemId":null,"revision":1,"payload":{"prompt":"A financial manager must balance:","options":["Risk exposure and potential returns","Staff morale and output levels","Advertising and revenue goals","Design quality and innovation"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Every financial decision involves a risk-return trade-off: higher expected returns usually come with higher risk, so the financial manager must balance the two. Options B, C and D are concerns of human resources, marketing and product design."}},{"itemId":"b0c82c34-2025-5b5a-92f8-f02ec8ea82d2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3ff13c56-a111-5849-aa30-9d797cbdb904","sourceKey":"bank:FIN101:FIN-0011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a component of financial planning?","options":["Defining monetary objectives","Engineering a new product","Onboarding personnel","Surveying market trends"],"correctOption":0,"section":"Overview of Finance","explanation":"Financial planning starts with setting financial goals, such as how much to save, invest or raise, and then planning how to reach them. Options B, C and D are product development, human resources and market research tasks."}},{"itemId":"d8b5f568-e8a5-56a3-8a5a-2548165ce51a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4d4096d2-9bc3-5a6b-a401-f0ae9ea67342","sourceKey":"bank:FIN101:FIN-0012","parentItemId":null,"revision":1,"payload":{"prompt":"The primary focus of corporate finance is:","options":["Managing individual savings accounts","Overseeing a firm's financial operations","Administering tax policies","Boosting workforce motivation"],"correctOption":1,"section":"Overview of Finance","explanation":"Corporate finance deals with the financial activities of a firm, such as raising capital, choosing investments and paying dividends. Option A is personal finance and C relates to public finance, while D is a human resources issue."}},{"itemId":"edd91980-ccdf-5c66-9170-929fc65df989","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b0814ffb-a0f2-5f11-90ea-db4a716ea709","sourceKey":"bank:FIN101:FIN-0013","parentItemId":null,"revision":1,"payload":{"prompt":"Finance is important because it:","options":["Enables informed strategic choices","Eliminates planning requirements","Centers solely on profit gains","Neglects risk considerations"],"correctOption":0,"section":"Overview of Finance","explanation":"Finance gives managers the information and tools to make well-informed strategic choices about funds, risk and return. Option B is wrong because finance requires planning, D is wrong because risk is central to finance, and C is too narrow since finance looks at more than profit."}},{"itemId":"50e75751-088f-52a0-a51f-7ed8c3905847","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cc338ba5-2dc5-5441-9c7c-9ee3f03243d6","sourceKey":"bank:FIN101:FIN-0014","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of diversification in finance refers to:","options":["Concentrating funds in one asset","Spreading investments to mitigate risk","Amplifying borrowing levels","Curtailing profit margins"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Diversification means spreading money across different investments so that a loss on one can be offset by gains on others, reducing overall risk. Option A, putting all funds in one asset, is the opposite and increases risk."}},{"itemId":"fec2cac8-3d01-502e-b3c2-695b5104265b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3b1969d3-abaa-5c55-b080-f08143e9362a","sourceKey":"bank:FIN101:FIN-0015","parentItemId":null,"revision":1,"payload":{"prompt":"The primary objective of a business firm is often to:","options":["Maximize profits for its owners","Limit employee well-being","Evade market rivalry","Scale back output"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Traditionally, a business firm's main objective is taken to be profit maximisation, earning as much profit as possible for its owners. Options B, C and D would harm the business, so none of them can be its objective."}},{"itemId":"b0af323a-395e-5e1b-af6e-b2943eb818d7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4003e3d7-b038-5123-af44-4537cd0c0d14","sourceKey":"bank:FIN101:FIN-0016","parentItemId":null,"revision":1,"payload":{"prompt":"Maximizing shareholder wealth means:","options":["Enhancing stock value and payouts","Lowering staff remuneration","Overlooking client demands","Bypassing financial strategies"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Shareholder wealth maximisation means increasing the value of the owners' stake, shown through a rising share price and dividends. Options B, C and D would tend to damage the firm and reduce shareholder value over time."}},{"itemId":"5df9aef6-58fb-5a3c-a863-efaac63775a2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8c06f5ea-ba32-55d3-8633-af5b2730cc23","sourceKey":"bank:FIN101:FIN-0017","parentItemId":null,"revision":1,"payload":{"prompt":"A secondary objective of a business firm might be:","options":["Corporate social responsibility initiatives","Escalating debt levels","Shrinking revenue streams","Dodging tax responsibilities"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Besides profit or wealth, firms often pursue secondary goals such as corporate social responsibility, for example supporting the community or protecting the environment. Options B, C and D are harmful outcomes or illegal behaviour, not objectives."}},{"itemId":"62decaa0-22f7-5b2a-8951-8b77ae4d7303","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2a889015-61c1-5d50-8c18-85cb06b018ec","sourceKey":"bank:FIN101:FIN-0018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a long-term objective of a firm?","options":["Covering daily operational costs","Expanding market presence","Employing short-term workers","Depleting stock reserves"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Expanding market presence is a long-term goal because it takes years of investment and planning to achieve. Covering daily costs (A) and using short-term workers (C) are short-run matters, and running down stock (D) is not an objective."}},{"itemId":"986c8931-991a-5c4e-a86b-bbe3b2b8a76b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"47ed2b6d-6bbc-5760-b455-52c4f36454b5","sourceKey":"bank:FIN101:FIN-0019","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of profit maximization focuses on:","options":["Immediate financial gains","Sustained operational viability","Worker contentment","Customer retention"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Profit maximisation is often criticised for focusing on short-term, immediate profits while ignoring timing and risk. Sustained viability (B) is closer to wealth maximisation, and worker contentment (C) and customer retention (D) are separate goals."}},{"itemId":"ceba12ac-39c0-514e-a777-3b1381a67036","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7ca4acdb-b851-5508-9cec-3f51e7ad6efb","sourceKey":"bank:FIN101:FIN-0020","parentItemId":null,"revision":1,"payload":{"prompt":"A business firm's objective to survive in the market is:","options":["A growth-driven goal","A survival-focused goal","A profit-centric goal","A community-oriented goal"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Staying in business, especially in tough or competitive conditions, is a survival objective, so B is correct. Growth (A) is about expanding, profit (C) is about earnings, and community goals (D) are social objectives."}},{"itemId":"b6feccaa-2698-59d3-b685-aa05f851696d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a99d607f-6f82-5205-96a6-23ecbc39e19e","sourceKey":"bank:FIN101:FIN-0021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following conflicts with profit maximization?","options":["Funding staff skill development","Streamlining production processes","Trimming operational expenses","Broadening market reach"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Spending on staff training raises costs today while its benefits only come later, so it can conflict with maximising current profit. Options B and C cut costs, and D aims to raise sales, so all three support profit maximisation rather than conflict with it."}},{"itemId":"134a2a73-fe86-5c4b-81c4-61d447ed352c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"623dd668-4f78-5f59-9364-deea9ad05295","sourceKey":"bank:FIN101:FIN-0022","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of a firm to maintain liquidity means:","options":["Ensuring cash for short-term needs","Growing long-term liabilities","Cutting sales volumes","Halting investment activities"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"A liquidity objective means the firm keeps enough cash or near-cash assets to meet short-term obligations such as wages and supplier bills as they fall due. Growing long-term liabilities (B) does not provide liquidity, and cutting sales (C) or halting investment (D) are not what liquidity means."}},{"itemId":"42601246-b02b-5b67-8b8d-dd15bc975e7a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"272ab10b-3775-54bc-8a0e-81a7d60f7015","sourceKey":"bank:FIN101:FIN-0023","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to grow often involves:","options":["Shrinking business operations","Entering untapped markets","Limiting profit potential","Avoiding competitive threats"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Growth usually means getting bigger, for example by entering new markets, launching products or expanding capacity. Shrinking operations (A) and limiting profit (C) are the opposite of growth, and avoiding competition (D) does not grow the business."}},{"itemId":"413a2267-621e-5afd-9fbb-f45a6436fb2f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"38ccc8b5-cd17-54c4-b92d-3b37d41a093d","sourceKey":"bank:FIN101:FIN-0024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a social objective of a business firm?","options":["Boosting profit margins","Enhancing community welfare","Reducing staff perks","Increasing leverage"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Social objectives are about the firm's responsibility to society, such as improving community welfare. Boosting margins (A) is a profit objective, while cutting staff perks (C) and increasing leverage (D) are not social goals."}},{"itemId":"9eaca253-8cf5-52e0-94b4-fa0d5903b339","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d01a09ed-2db7-57fa-87e1-1bb4dec3fc13","sourceKey":"bank:FIN101:FIN-0025","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of maximizing shareholder wealth aligns with:","options":["Building enduring value","Short-term expense cuts","Lowering dividend payouts","Shunning capital investments"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Wealth maximisation looks at the long run, aiming to build lasting value for shareholders. Short-term cost cuts (B) relate more to short-run profit, and cutting dividends (C) or avoiding investment (D) do not by themselves build value."}},{"itemId":"4acc32ac-1caf-56ca-bf30-cc9ae2720a06","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"df508341-1e64-5a75-b688-63daf70865f1","sourceKey":"bank:FIN101:FIN-0026","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to innovate can lead to:","options":["Diminished market competition","Greater market penetration","Elevated short-term expenses","Both B and C"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Innovation can help a firm reach more customers and gain market share (B), but research and development also raise costs in the short term (C), so both are true and D is correct. Option A is wrong because innovation usually increases competition rather than reducing it."}},{"itemId":"32557f77-3238-5652-919c-18e3d5e65298","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"742aeb1f-4308-5a30-ab60-0929aa611e24","sourceKey":"bank:FIN101:FIN-0027","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of a firm to be ethical involves:","options":["Disregarding legal standards","Adhering to equitable practices","Prioritizing profits above all","Limiting transparency efforts"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Ethical behaviour means acting fairly and honestly, following fair practices in dealing with customers, staff and society. Ignoring the law (A), putting profit above everything (C) and reducing transparency (D) are all unethical."}},{"itemId":"b7a2711d-80e6-5305-8f8e-0775ca1e669e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3636a32e-4c61-5e38-afec-2125c218f1bb","sourceKey":"bank:FIN101:FIN-0028","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's objective to increase efficiency focuses on:","options":["Lowering costs and boosting output","Raising debt obligations","Decreasing revenue targets","Stifling innovative efforts"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Efficiency means getting more output from the same or fewer resources, which means lower costs and higher output. Raising debt (B), lowering revenue targets (C) and blocking innovation (D) do not improve efficiency."}},{"itemId":"bb65d101-62aa-5220-b6ff-f105f1cfe6f8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"af68ed5a-5a40-5212-88d1-03b75a51e662","sourceKey":"bank:FIN101:FIN-0029","parentItemId":null,"revision":1,"payload":{"prompt":"The concept of compound interest means:","options":["Interest accrues solely on the initial amount","Interest builds on principal and prior interest","No interest is generated","Interest is disbursed once only"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"With compound interest, each period's interest is added to the principal, so later interest is earned on both the principal and the interest already earned. Option A describes simple interest, where interest is only calculated on the original amount."}},{"itemId":"1a8f3aa2-f3aa-5d45-b947-c9faf78c702b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6559dc5c-e084-5be2-ac87-211a59a79067","sourceKey":"bank:FIN101:FIN-0030","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for simple interest is:","options":["I = P x R x T","I = P x (1 + R x T)","I = P x R / T","I = P + R x T"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Simple interest is I = P x R x T, where P is the principal, R the rate per year and T the time in years. Option B gives the total amount (principal plus interest), not the interest alone, and C and D are not valid formulas."}},{"itemId":"e2956bf6-8e5b-523f-9a46-7d980ad9fe0a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b24b74b8-2405-5958-a3d5-8ab7fe05cb0a","sourceKey":"bank:FIN101:FIN-0031","parentItemId":null,"revision":1,"payload":{"prompt":"If N1,000 is invested at 5% simple interest per annum for 2 years, what is the simple interest earned?","options":["N50","N100","N102.50","N1,100"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Simple interest is I = P x R x T = 1,000 x 0.05 x 2 = N100. Option D (N1,100) is the total amount after 2 years, principal plus interest, not the interest alone. Option C (N102.50) is what compound interest would give, and option A is only one year of interest."}},{"itemId":"e5f5c713-f349-5f66-a75a-7283e6d8c6f7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d5941810-531c-5e61-8623-117660500bdf","sourceKey":"bank:FIN101:FIN-0032","parentItemId":null,"revision":1,"payload":{"prompt":"The future value of money takes into account:","options":["The impact of time on value","Just the original principal","Only the applied interest rate","Merely the duration"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Future value shows what money today will grow to after earning interest over time, so it brings in the principal, the rate and the time together. Options B, C and D each look at only one of these parts."}},{"itemId":"54c04a17-8df2-5c24-a2ee-17c9ef7683ca","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8aaa2d2e-15bf-50fb-a6e9-6af9339f4330","sourceKey":"bank:FIN101:FIN-0033","parentItemId":null,"revision":1,"payload":{"prompt":"The present value of money is:","options":["Today's worth of future cash flows","Historical value of past earnings","Future worth of current funds","Value ignoring interest effects"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Present value is what a future amount of money is worth today after discounting it at an appropriate interest rate. Option C describes future value, B looks at the past, and D is wrong because present value depends on interest."}},{"itemId":"c46c8555-c79f-5e8b-b0ac-12d9f30f0539","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c527d0b9-1c33-51c4-83a4-e8f2f67827bc","sourceKey":"bank:FIN101:FIN-0034","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for compound interest is:","options":["A = P x (1 + R/n)^(n x t)","A = P x R x T","A = P + R x T","A = P x (1 + R)"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"The compound amount is A = P x (1 + R/n)^(n x t), where n is the number of compounding periods per year and t is the number of years. Option B is the simple interest formula, and D only covers one period."}},{"itemId":"17524ffc-8a8f-57c6-bd1d-41693ad77dc6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eb01883b-f399-50b4-a093-684ebee1609c","sourceKey":"bank:FIN101:FIN-0035","parentItemId":null,"revision":1,"payload":{"prompt":"If N500 is invested at 4% compounded annually for 3 years, what is the future value?","options":["N560.00","N562.43","N584.93","N62.43"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"With annual compounding, FV = 500 x (1.04)^3 = 500 x 1.124864 = N562.43. Option A (N560) is what simple interest would give, 500 + 500 x 0.04 x 3. Option C compounds for 4 years instead of 3, and option D is only the interest earned, not the future value."}},{"itemId":"28730ab9-d83b-5620-9142-8ce45ca8f659","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"75ad27f1-edf4-505b-869e-4b892caaf8d3","sourceKey":"bank:FIN101:FIN-0036","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money concept states that:","options":["Present funds outvalue future funds","Future funds outvalue present funds","Money retains static value","Money's worth is unchanging"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Money received today is worth more than the same amount in the future because it can be invested to earn interest, and inflation reduces its buying power over time. Option B reverses this, and C and D ignore the time value of money entirely."}},{"itemId":"e0c1206f-5c89-5ce0-b6c0-8372424ed2ef","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"308222a4-a24b-555f-8478-38251521a923","sourceKey":"bank:FIN101:FIN-0037","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity is:","options":["A one-time lump sum","A sequence of regular payments","A borrowing agreement","An equity investment"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"An annuity is a series of equal payments made at regular intervals for a fixed period, such as monthly rent or loan repayments. Option A is a single lump sum, which is the opposite of an annuity."}},{"itemId":"a2c9e200-a5c1-5c3d-85b5-3260710b9c7a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ce5b6b86-544f-54cf-917d-af4168e8068b","sourceKey":"bank:FIN101:FIN-0038","parentItemId":null,"revision":1,"payload":{"prompt":"The discount rate is used to:","options":["Project future cash growth","Determine current cash value","Elevate interest charges","Shrink principal amounts"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"A discount rate is used to convert future cash flows into their present value, that is, their value today. Option A describes compounding toward a future value, while C and D are not what discounting does."}},{"itemId":"7af36087-b740-57af-a606-511c280b78c4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1e8a1380-5e10-5cb1-affc-3d47113f321f","sourceKey":"bank:FIN101:FIN-0039","parentItemId":null,"revision":1,"payload":{"prompt":"If the interest rate increases, the present value of a future cash flow:","options":["Rises due to higher returns","Falls due to discounting","Stays constant regardless","Drops to zero entirely"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Present value is PV = FV / (1 + r)^n, so a higher interest rate makes the denominator bigger and the present value smaller. Option A gets the direction wrong, and D is wrong because PV falls but does not become zero."}},{"itemId":"d69034c8-1ffd-5750-9879-aa0dca2af415","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"23d2267e-f95b-51ed-a43b-e957091bc584","sourceKey":"bank:FIN101:FIN-0040","parentItemId":null,"revision":1,"payload":{"prompt":"The effective annual rate (EAR) takes into account:","options":["Basic interest without compounding","Frequency of interest compounding","Principal amount alone","Duration without adjustments"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"The effective annual rate shows the true yearly return once compounding more than once a year is taken into account: EAR = (1 + r/m)^m - 1, where m is the number of compounding periods. Option A describes the nominal rate, which ignores compounding."}},{"itemId":"f7a3b01a-c207-5d71-94e7-582582d580f3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"61049954-4e77-5d05-9c25-30b81656c627","sourceKey":"bank:FIN101:FIN-0041","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity is:","options":["A limited payment series","An endless stream of equal payments","A solitary cash disbursement","A financed debt obligation"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"A perpetuity is a stream of equal payments that continues forever, and its present value is PV = payment / r. Option A describes an ordinary annuity, which ends after a fixed number of payments."}},{"itemId":"5514aa95-e4c7-565e-9dd5-c43d744b8a69","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3472d0c9-ac0e-5abd-b70d-211c521a7765","sourceKey":"bank:FIN101:FIN-0042","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for the future value of an annuity is used to:","options":["Assess a one-off payment's worth","Compute a payment series' total","Calculate basic interest gains","Estimate discounted present value"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"The future value of an annuity formula adds up a series of regular payments plus the interest they earn, giving their total value at the end. Option A is for a single sum, and D describes the present value of an annuity."}},{"itemId":"483edd85-7bb2-562b-a7f0-3447cda404ff","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cdfc7ad4-381f-5d89-b3a1-7b89e03262ed","sourceKey":"bank:FIN101:FIN-0043","parentItemId":null,"revision":1,"payload":{"prompt":"A financial market is a place where:","options":["Physical goods are manufactured","Financial instruments are exchanged","Workers are recruited","Products are advertised"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A financial market is where financial assets such as shares, bonds and treasury bills are bought and sold. Options A, C and D describe factories, labour markets and advertising, which do not trade financial instruments."}},{"itemId":"2c69bc97-bb65-506e-b942-d696e7795793","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"dd69af9d-d632-540b-887e-cf86c5018579","sourceKey":"bank:FIN101:FIN-0045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a financial instrument?","options":["A production facility","An equity share in a firm","A piece of machinery","A corporate office building"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A financial instrument is a tradeable claim to money or ownership, such as a share or a bond, so an equity share is correct. Options A, C and D are physical (real) assets, not financial instruments."}},{"itemId":"6ec94693-60c7-5848-9f08-3e8201e677ad","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5204dc5d-c29c-5f16-be1a-249a60c6980c","sourceKey":"bank:FIN101:FIN-0046","parentItemId":null,"revision":1,"payload":{"prompt":"The primary market is where:","options":["Investors trade existing assets","New securities are first offered","Used securities are resold","Commodities are swapped"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The primary market is where new securities are sold for the first time, for example in an initial public offering, so the issuing company gets the money. Options A and C describe the secondary market, where existing securities change hands between investors."}},{"itemId":"389cd579-605e-5fee-8196-eb289db4c3fa","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c0ac2c35-0fa3-5505-bd8a-b694027e2e22","sourceKey":"bank:FIN101:FIN-0047","parentItemId":null,"revision":1,"payload":{"prompt":"The secondary market allows investors to:","options":["Purchase freshly issued stocks","Exchange previously issued securities","Launch new debt offerings","Generate fresh equity shares"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"In the secondary market, investors buy and sell securities that have already been issued, as happens daily on a stock exchange. Options A, C and D describe new issues, which take place in the primary market."}},{"itemId":"9900e348-2204-5caa-9d75-995413fadd7e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"40ab3546-21ab-5b0f-80b7-4ca5698fe179","sourceKey":"bank:FIN101:FIN-0048","parentItemId":null,"revision":1,"payload":{"prompt":"A bond is:","options":["A stake in company ownership","A debt instrument issued by a borrower","An equity-based security","A traded physical asset"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A bond is a debt instrument: the issuer borrows money from investors and promises to pay interest and repay the principal at maturity. Options A and C describe shares (equity), which give ownership rather than a loan, and D describes a commodity, not a security."}},{"itemId":"77eda3cf-d9cd-5339-af34-50059b7dd174","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9d783db5-58b6-56da-9fc0-fc5669df41b2","sourceKey":"bank:FIN101:FIN-0050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a role of financial markets?","options":["Curtailing competitive forces","Enabling fund transfers efficiently","Raising production expenses","Restricting investment options"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"Financial markets move funds efficiently from savers who have surplus money to borrowers and firms that need it. Options A, C and D are the opposite of what well-functioning financial markets do."}},{"itemId":"e8836d18-5f0d-5f32-bb43-3e4c7507dae5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1050c207-f689-531e-8ddb-1ac28f2d648b","sourceKey":"bank:FIN101:FIN-0051","parentItemId":null,"revision":1,"payload":{"prompt":"The Nigerian Stock Exchange (NSE) is an example of:","options":["A liquidity-focused money market","An equity-driven capital market","A goods-trading commodity market","An employment labor market"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The Nigerian Stock Exchange, now the Nigerian Exchange, is where long-term securities such as shares are traded, so it is part of the capital market. Option A is wrong because the money market deals with short-term instruments, not shares."}},{"itemId":"ec53640e-6815-5301-9a7c-fc050a5e6903","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"93afe465-cf45-549d-9be4-0c97eff6a811","sourceKey":"bank:FIN101:FIN-0052","parentItemId":null,"revision":1,"payload":{"prompt":"A mutual fund is:","options":["A standalone stock investment","A collective investment pool","A fixed-income debt security","A personal loan product"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A mutual fund pools money from many investors and invests it in a spread of securities managed by professionals. Option A is a single share, C is a bond, and D is a loan."}},{"itemId":"e2b775e1-b82b-5e9f-a6ba-019191e6ac00","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cf3d2c4b-7d10-555e-aacf-bef7494ee505","sourceKey":"bank:FIN101:FIN-0054","parentItemId":null,"revision":1,"payload":{"prompt":"A financial intermediary is:","options":["A producer of tangible goods","A link between lenders and borrowers","An equity security type","A debt issuance tool"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A financial intermediary, such as a bank, stands between savers (lenders) and borrowers, collecting funds from one group and lending to the other. Option A describes a manufacturer, and C and D are instruments rather than institutions."}},{"itemId":"42e150d0-9458-56fd-8b88-9fc19ba11eb8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a230119b-8e97-5816-aa0f-2ba2d2adc10b","sourceKey":"bank:FIN101:FIN-0055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a participant in financial markets?","options":["Investors seeking returns","Factories producing goods","Stores selling products","Workers in operations"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"Investors who supply funds hoping to earn a return are key participants in financial markets. Factories, shops and workers (B, C and D) are part of the goods and labour markets, not financial markets."}},{"itemId":"8011ee43-50ae-5a6f-ad68-dd7ce6a5a300","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"03a1ef2f-0696-5af4-9707-f8f88d0227f3","sourceKey":"bank:FIN101:FIN-0056","parentItemId":null,"revision":1,"payload":{"prompt":"The price of a stock is determined by:","options":["Government-set price controls","Market supply and demand forces","Employee wage levels","Manufacturing cost structures"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"Share prices in an open market are set by the forces of supply and demand, as buyers and sellers react to news about the company and the economy. Option A is wrong because share prices are not fixed by government, and C and D affect a company indirectly at most."}},{"itemId":"48e7ca3e-357d-5f47-b6bd-bf41caa9cfa4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a5342c7f-44c3-5529-a936-ddeb16dd4df6","sourceKey":"bank:FIN101:FIN-0057","parentItemId":null,"revision":1,"payload":{"prompt":"Risk in finance refers to:","options":["Assured investment outcomes","Uncertainty in expected returns","Guaranteed profit margins","Rejection of investment plans"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Risk in finance is the uncertainty about returns: actual returns may differ from what was expected. Options A and C describe certainty, the opposite of risk, and D has nothing to do with risk."}},{"itemId":"cc98ba0d-eea7-5dc7-bd1d-ac02cc1db66c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2c1a4ec8-3a29-52e9-8632-04d7304ae87c","sourceKey":"bank:FIN101:FIN-0058","parentItemId":null,"revision":1,"payload":{"prompt":"Systematic risk is:","options":["Unique to a specific firm","Broad market risk impacting all","Mitigated by portfolio variety","Confined to one sector"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Systematic risk is market-wide risk, from factors such as recessions, inflation or interest rate changes, that affects all firms. Options A and D describe unsystematic risk, and C is wrong because diversification cannot remove systematic risk."}},{"itemId":"ba6cda07-0ceb-50bd-aac0-227809f93408","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ad2a548f-25ef-5eec-a62c-69ecb51b1e83","sourceKey":"bank:FIN101:FIN-0059","parentItemId":null,"revision":1,"payload":{"prompt":"Unsystematic risk can be reduced by:","options":["Focusing on one stock holding","Diversifying across assets","Raising debt exposure","Avoiding all investments"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Unsystematic risk is specific to individual firms, so holding many different assets lets losses on some be offset by gains on others. Option A increases this risk, and D avoids risk only by giving up any return."}},{"itemId":"ccc0e76b-2f85-5c00-9110-5174d23390f7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b97b4342-250c-54c7-bf8a-84e5f08eb34e","sourceKey":"bank:FIN101:FIN-0060","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of systematic risk?","options":["A firm's ineffective leadership","An economic downturn market-wide","A defective product launch","A company-specific strike"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"An economic downturn hits almost all firms at once, so it is a systematic (market) risk. Poor leadership (A), a faulty product (C) and a strike at one company (D) are firm-specific, unsystematic risks."}},{"itemId":"dade2dd3-eb0d-5b48-bf6b-c8911f082510","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"70f9be0b-cb05-5b73-8fea-781379a85b10","sourceKey":"bank:FIN101:FIN-0061","parentItemId":null,"revision":1,"payload":{"prompt":"The risk-return tradeoff means:","options":["Greater risk yields lower gains","Higher risk offers higher potential rewards","Risk and reward are disconnected","Minimal risk ensures big returns"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"The risk-return trade-off says investors will only take on more risk if they expect a higher return, so riskier investments offer higher potential rewards. Option A reverses the relationship, and D is wrong because low-risk assets usually give modest returns."}},{"itemId":"0d28f360-7fc6-5b37-b60b-54da1bf245b5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cebef370-8de0-5faa-a033-66af8ae13b50","sourceKey":"bank:FIN101:FIN-0062","parentItemId":null,"revision":1,"payload":{"prompt":"A risk-averse investor prefers:","options":["Volatile high-stakes ventures","Stable low-risk options","Complete investment abstention","Speculative high-return bets"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"A risk-averse investor dislikes uncertainty and will choose safer, lower-risk investments, accepting lower returns. Options A and D describe a risk seeker, and C is wrong because being risk averse does not mean refusing to invest."}},{"itemId":"a62cb49a-9353-5004-a672-9ec1cc872297","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"91eb6be5-be99-5489-bc6e-88bc62c0d5e4","sourceKey":"bank:FIN101:FIN-0063","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a tool for analyzing risk?","options":["Income and expense reports","Standard deviation of returns","Promotional campaign plans","Factory output timelines"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Standard deviation measures how widely returns spread around the expected return, so a larger figure means more risk. Income and expense reports (A) show performance rather than risk, and C and D are marketing and production plans."}},{"itemId":"0d1ae2d8-bb96-5ac3-98d2-4958fcf3cbd1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"73a5b202-dd74-5a0f-9a66-f1f16c3d3915","sourceKey":"bank:FIN101:FIN-0064","parentItemId":null,"revision":1,"payload":{"prompt":"Credit risk refers to:","options":["A debtor failing to repay a loan","Market price volatility","Rising inflation pressures","Internal mismanagement"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Credit risk, or default risk, is the chance that a borrower will not repay a loan or interest on time. Price swings (B) are market risk, inflation (C) is purchasing power risk, and mismanagement (D) is a business risk."}},{"itemId":"b054a609-70a9-5c27-b2eb-82ed03d64791","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"08c188f7-81c8-57ff-bc30-4b42d5852ffd","sourceKey":"bank:FIN101:FIN-0065","parentItemId":null,"revision":1,"payload":{"prompt":"Market risk is also known as:","options":["Firm-specific unsystematic risk","Economy-wide systematic risk","Isolated company risk","Diversifiable portfolio risk"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Market risk is another name for systematic risk, the risk that affects the whole economy and cannot be removed by diversification. Options A, C and D all describe unsystematic, firm-specific risk."}},{"itemId":"c3577739-1883-5111-aca3-f8a1cba1bd96","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ef8a8555-0740-555f-96b6-1f74f775d34f","sourceKey":"bank:FIN101:FIN-0066","parentItemId":null,"revision":1,"payload":{"prompt":"A risk management strategy includes:","options":["Eliminating all uncertainties","Assessing and reducing risks","Amplifying risk exposure","Overlooking potential threats"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Risk management means identifying and assessing risks, then taking steps to reduce or control them. Option A is impossible because no business can remove all uncertainty, and C and D make things worse."}},{"itemId":"a826cdb8-e3ff-54e4-a41f-68429e4f8c71","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3a6d915d-785a-515a-ba41-42dfc34efd1a","sourceKey":"bank:FIN101:FIN-0067","parentItemId":null,"revision":1,"payload":{"prompt":"Liquidity risk refers to:","options":["Inability to meet payment obligations when due","Inflation eroding value","Leadership errors in strategy","Market expansion challenges"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Liquidity risk is the danger that a firm cannot meet its payment obligations in full and on time because it does not have enough cash or assets it can quickly turn into cash. Option B describes inflation risk, which is about loss of purchasing power, and C is a management or operational risk."}},{"itemId":"f31bada8-0ecc-554b-a6e8-2eb2b6c2d2b6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4557da22-048e-5cad-9734-76068b10eafc","sourceKey":"bank:FIN101:FIN-0068","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a method to manage financial risk?","options":["Hedging with derivatives","Increasing leverage levels","Narrowing investment scope","Halting all funding activities"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Hedging means taking a position, often through contracts such as forwards or options, that offsets possible losses on another position, so it is a way to manage risk. Increasing leverage (B) and narrowing investments (C) raise risk, and D stops the business working."}},{"itemId":"24e35e7f-ecc1-5109-8b3b-2b77c368a98d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ef4f53fc-fad0-5d13-8a90-7555d09e9720","sourceKey":"bank:FIN101:FIN-0069","parentItemId":null,"revision":1,"payload":{"prompt":"Interest rate risk affects:","options":["Fixed-income asset valuations","Equity prices exclusively","Commodity market trends","Real estate appreciation"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"When interest rates rise, the prices of fixed-income assets such as bonds fall, and the reverse is also true, so interest rate risk mainly affects them. Option B is wrong because the effect is not limited to shares, and C and D are not mainly driven by this risk."}},{"itemId":"687a097b-ddc4-56c8-af7d-6d5010e5a371","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5b97426d-f6a6-5fe6-82ef-0e00aa78516f","sourceKey":"bank:FIN101:FIN-0070","parentItemId":null,"revision":1,"payload":{"prompt":"A risk premium is:","options":["Extra return for risk acceptance","Assured gain on investments","Cost of securing loans","Reduction in uncertainty"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"A risk premium is the extra return investors demand above a risk-free rate for accepting extra risk. Option B is the opposite, since a premium exists because returns are not guaranteed, and C describes the cost of borrowing."}},{"itemId":"70e41c4a-f086-5c41-9933-19e4db769521","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1eb10731-e024-50cf-8121-12f7c9f63791","sourceKey":"bank:FIN101:FIN-0071","parentItemId":null,"revision":1,"payload":{"prompt":"Financial ratio analysis is used to:","options":["Gauge a firm's operational success","Innovate product offerings","Recruit new staff members","Promote company services"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Ratio analysis compares figures from financial statements to judge a firm's performance, such as its liquidity, profitability and efficiency. Options B, C and D are product, staffing and marketing activities."}},{"itemId":"dd521ce8-14f4-5a0d-be6b-83cfa328d6bc","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ec51b4f6-57d5-5034-a81f-f6ac823048d4","sourceKey":"bank:FIN101:FIN-0072","parentItemId":null,"revision":1,"payload":{"prompt":"The current ratio measures:","options":["Profit generation capacity","Short-term liquidity strength","Debt financing reliance","Process efficiency levels"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The current ratio (current assets / current liabilities) shows whether a firm can meet its short-term debts, so it is a liquidity ratio. Option A is a profitability ratio, C is a leverage ratio, and D is an activity ratio."}},{"itemId":"38e268ee-ca5c-5a89-af7c-be8ba798f105","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e3a002db-f6d8-5440-9057-2fe85366de3e","sourceKey":"bank:FIN101:FIN-0073","parentItemId":null,"revision":1,"payload":{"prompt":"A high debt-to-equity ratio indicates:","options":["Minimal financial exposure","Significant leverage usage","Strong profit margins","Reduced borrowing"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Debt-to-equity compares borrowed funds with owners' funds, so a high figure means the firm relies heavily on debt (high leverage). Options A and D say the opposite, and C is wrong because this ratio does not measure profit."}},{"itemId":"2c52c974-ffa2-59a8-8c4a-1f47c703e0fc","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c7a1d085-0549-5259-9d07-fc725e3273d9","sourceKey":"bank:FIN101:FIN-0074","parentItemId":null,"revision":1,"payload":{"prompt":"The formula for the current ratio is:","options":["Current assets / Current liabilities","Total assets / Total liabilities","Net income / Revenue","Total debt / Equity"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"The current ratio = Current assets / Current liabilities, for example 200,000 / 100,000 = 2:1. Option C is the net profit margin and D is the debt-to-equity ratio."}},{"itemId":"93492a82-9dd7-5c0e-9598-1dbdaa63fbe0","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4db76b4f-ac3e-50e7-b468-5410e2547873","sourceKey":"bank:FIN101:FIN-0075","parentItemId":null,"revision":1,"payload":{"prompt":"The return on equity (ROE) measures:","options":["Profit from shareholder funds","Cash flow availability","Operational streamlining","Market dominance"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Return on equity (net profit / shareholders' equity) shows how much profit a company earns on the funds invested by its owners. Option B is about liquidity, and C and D are not measured by ROE."}},{"itemId":"4c207a0e-91a2-5d3d-8907-31c9d07b3e79","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d90570e1-a5f2-5015-8f09-9a4dce81d18f","sourceKey":"bank:FIN101:FIN-0076","parentItemId":null,"revision":1,"payload":{"prompt":"A low quick ratio suggests:","options":["Robust liquidity reserves","Challenges meeting short-term debts","High earnings potential","Minimal leverage"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The quick ratio compares the most liquid assets (current assets minus inventory) with current liabilities, so a low figure warns that the firm may struggle to pay short-term debts. Option A is the opposite, and C and D are not measured by liquidity ratios."}},{"itemId":"cfb3d796-a4cb-5011-9da5-d63abdf95372","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"65d8afc4-04a2-593a-af81-d2e1d0b19c0d","sourceKey":"bank:FIN101:FIN-0077","parentItemId":null,"revision":1,"payload":{"prompt":"The gross profit margin is calculated as:","options":["Gross profit / Sales revenue","Net profit / Sales revenue","Sales revenue / Gross profit","Net profit / Equity"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"The gross profit margin = Gross profit / Sales revenue, showing what share of each naira of sales is left after cost of sales. Option B is the net profit margin, and C turns the ratio upside down."}},{"itemId":"23106d77-0d1e-5a7b-bee8-ef2567078af0","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f7208b49-7eaa-5ec5-91a6-cd5813ea13af","sourceKey":"bank:FIN101:FIN-0078","parentItemId":null,"revision":1,"payload":{"prompt":"The inventory turnover ratio measures:","options":["Speed of inventory sales","Overall profit levels","Cash flow readiness","Debt repayment capacity"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Inventory turnover (cost of sales / average inventory) shows how quickly a firm sells and replaces its stock, so it is an activity ratio. Options B, C and D are measured by profitability, liquidity and leverage ratios."}},{"itemId":"465df106-e3a6-5be5-a992-37ec7cac67bf","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cbaa9c43-9175-5d7f-928b-ac572f3cfcfd","sourceKey":"bank:FIN101:FIN-0079","parentItemId":null,"revision":1,"payload":{"prompt":"A high price-to-earnings (P/E) ratio indicates:","options":["Strong expected earnings growth","Stock undervaluation signal","Low company profitability","Excessive borrowing"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"A high P/E means investors are willing to pay many naira for each naira of current earnings, usually because they expect the company's earnings to grow strongly. Option B is the wrong way round, since it is a low P/E that may point to an undervalued share, and C and D are not measured by the P/E ratio."}},{"itemId":"a7440463-465a-54ba-8b2f-d59120118958","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"15d7a0aa-8f60-510c-89d7-9b0e6d6fe60c","sourceKey":"bank:FIN101:FIN-0080","parentItemId":null,"revision":1,"payload":{"prompt":"The debt ratio is calculated as:","options":["Total debt / Total assets","Total assets / Total debt","Net income / Total debt","Equity / Total debt"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"The debt ratio = Total debt / Total assets, showing what share of the firm's assets is financed by borrowing. Option B turns the ratio upside down, and D is the inverse of the debt-to-equity ratio."}},{"itemId":"c2648ecd-fb86-5ea6-ab05-d03fb3bbb4c6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9b7d4188-807b-5315-95c5-6c771df3c3d1","sourceKey":"bank:FIN101:FIN-0081","parentItemId":null,"revision":1,"payload":{"prompt":"The net profit margin measures:","options":["Operational cost efficiency","Profit after all costs","Liquidity position","Stock rotation speed"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Net profit margin = Net profit / Sales, so it shows how much profit remains from each naira of sales after all expenses, including interest and tax. Option C is measured by liquidity ratios and D by inventory turnover."}},{"itemId":"a57c17af-9547-537c-b6c0-29fd0197f18d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"267c821e-8a25-5736-b88d-fbcff8a1520f","sourceKey":"bank:FIN101:FIN-0082","parentItemId":null,"revision":1,"payload":{"prompt":"A high accounts receivable turnover ratio indicates:","options":["Delayed payment collection","Swift receivable recovery","Excessive debt levels","Reduced sales volume"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Receivables turnover (credit sales / average receivables) is high when customers pay quickly, so the firm collects its debts fast. Option A describes a low turnover, and C and D are not shown by this ratio."}},{"itemId":"d30b381d-bd95-5920-b5d1-597a8c794e31","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e91bfbbd-27c0-5808-ac6f-6a1c77823fb1","sourceKey":"bank:FIN101:FIN-0083","parentItemId":null,"revision":1,"payload":{"prompt":"The quick ratio excludes:","options":["Cash on hand","Inventory from calculations","Receivables due soon","Short-term obligations"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The quick (acid-test) ratio = (Current assets - Inventory) / Current liabilities, so inventory is left out because it is the hardest current asset to turn into cash quickly. Cash (A) and receivables (C) are included, and short-term obligations (D) are the denominator."}},{"itemId":"491af7ef-1662-57a8-902d-ef7ca474779d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0be0d74c-04a1-5fd2-ae4c-e944e05523ad","sourceKey":"bank:FIN101:FIN-0084","parentItemId":null,"revision":1,"payload":{"prompt":"Financial ratios are useful for:","options":["Tracking performance trends","Engineering new products","Staffing decisions","Advertising plans"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Ratios let managers and investors compare a firm's results over several years or against other firms, showing trends in performance. Options B, C and D are product, staffing and marketing decisions that ratios do not directly guide."}},{"itemId":"89959751-975d-5bfc-8bf9-85e4dd6a721a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b530fbe6-a78a-5fe3-85b8-a839cc2b0e9d","sourceKey":"bank:FIN101:FIN-0085","parentItemId":null,"revision":1,"payload":{"prompt":"A sole proprietorship is characterized by:","options":["Multiple stakeholder ownership","One individual owner","Protected liability limits","Public stock offerings"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A sole proprietorship is owned and run by one person, who takes all the profits and bears all the risks. Option A describes partnerships or companies, C describes a limited company, and D applies only to public companies."}},{"itemId":"8b6fa06f-2428-5b47-8ea6-a04138277041","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"26e5bc5e-7dc2-5b10-a190-231359727306","sourceKey":"bank:FIN101:FIN-0086","parentItemId":null,"revision":1,"payload":{"prompt":"A disadvantage of a partnership is:","options":["Shielded personal assets","Unlimited personal liability","Broad capital availability","Sole decision authority"],"correctOption":1,"section":"Forms of Business Firm","explanation":"In an ordinary partnership, partners have unlimited liability, so their personal assets can be used to pay the firm's debts. Option A describes limited liability, and D describes a sole proprietorship."}},{"itemId":"6c803b67-1a73-586d-8c08-ac6f4e19421a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d84d27bd-adaf-5fb0-8532-f6c64bd6f174","sourceKey":"bank:FIN101:FIN-0087","parentItemId":null,"revision":1,"payload":{"prompt":"A corporation is:","options":["A solo-owned enterprise","A distinct legal entity","An unlimited liability structure","A non-shareholder entity"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A corporation, or limited liability company, is a separate legal person from its owners, so it can own property, sue and be sued in its own name. Option A describes a sole proprietorship, and C is wrong because shareholders' liability is limited."}},{"itemId":"1298c333-8933-55c5-be12-fc770fc060e5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"654a4880-d4f1-57d4-b4db-9fffb87db5f1","sourceKey":"bank:FIN101:FIN-0088","parentItemId":null,"revision":1,"payload":{"prompt":"An advantage of a sole proprietorship is:","options":["Vast funding resources","Liability protection","Total owner control","Divided responsibilities"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A sole proprietor makes every decision alone, giving total control over the business. Options A and B are wrong because sole proprietors usually have limited funds and unlimited liability, and D describes a partnership."}},{"itemId":"da23d468-303d-5640-855b-88f5b5c3a781","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2ce13063-2df2-5af1-9c03-c911f3e82253","sourceKey":"bank:FIN101:FIN-0089","parentItemId":null,"revision":1,"payload":{"prompt":"A partnership agreement typically includes:","options":["Profit and loss allocations","Marketing strategy outlines","Production timelines","Employee policy manuals"],"correctOption":0,"section":"Forms of Business Firm","explanation":"A partnership agreement (deed) usually sets out how profits and losses are shared, along with capital contributions and partners' rights. Options B, C and D are operational matters, not the terms of the partnership itself."}},{"itemId":"fb095fde-0a0e-594e-a5bc-74de0739fc98","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"da7f713e-e3b3-5d6d-a4a4-5e90874795e0","sourceKey":"bank:FIN101:FIN-0090","parentItemId":null,"revision":1,"payload":{"prompt":"A disadvantage of a corporation is:","options":["Limited owner liability","Complex legal and reporting requirements","Simple setup process","Lone ownership model"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A corporation has to meet many more legal formalities than a sole trader or partnership, such as formal registration and regular filing of accounts, so complex legal requirements are a disadvantage. Limited liability (A) is an advantage, while C and D are wrong because forming a corporation is not simple and its ownership is spread among shareholders."}},{"itemId":"578361f1-2902-5a78-9fc2-827c7e5b72d2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fbc1d950-bc8c-5792-a59c-e29607ced78a","sourceKey":"bank:FIN101:FIN-0091","parentItemId":null,"revision":1,"payload":{"prompt":"A limited liability company (LLC) offers:","options":["Full personal liability","Limited owner liability","No tax advantages","Public market trading"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A limited liability company protects its owners, whose losses are limited to the amount they invested. Option A is the opposite, and D is wrong because only public companies trade their shares on an exchange."}},{"itemId":"00f38eac-ba64-512a-afa7-7908fad697d4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"10dd4392-31e4-5da6-afd6-d9425555b7a7","sourceKey":"bank:FIN101:FIN-0092","parentItemId":null,"revision":1,"payload":{"prompt":"In a partnership, decision-making is:","options":["Controlled by one partner","Distributed among partners","Regulated by authorities","Voted by equity holders"],"correctOption":1,"section":"Forms of Business Firm","explanation":"In a partnership, management and decisions are usually shared among the partners. Option A describes a sole proprietorship, and D describes shareholders voting in a company."}},{"itemId":"9c8bc788-8f12-5a27-ad25-aec51744e2a6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c73aa117-0014-5508-b0c2-d217cef960b6","sourceKey":"bank:FIN101:FIN-0093","parentItemId":null,"revision":1,"payload":{"prompt":"A corporation can raise capital by:","options":["Issuing equity shares","Cutting profit margins","Avoiding investment growth","Shrinking operational scope"],"correctOption":0,"section":"Forms of Business Firm","explanation":"A company raises long-term capital by selling shares to investors, who become part-owners. Options B, C and D would reduce the business rather than raise funds."}},{"itemId":"40c2a99d-40fb-56cd-a905-38152f640bfd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"20cf0a90-a599-56bd-953a-cd8ad9b63bfe","sourceKey":"bank:FIN101:FIN-0094","parentItemId":null,"revision":1,"payload":{"prompt":"A sole proprietorship is easy to form because:","options":["It needs state authorization","It has few legal hurdles","It involves co-owners","It requires stock issuance"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A sole proprietorship has few legal formalities, so it can often be set up just by registering a business name and starting to trade. Options A, C and D describe partnerships or companies, which need more formal steps."}},{"itemId":"3a438ed9-ea76-5d6d-bfe1-227190def696","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cc73ec4f-7d4c-5ffc-ad4e-3b62baba7c7f","sourceKey":"bank:FIN101:FIN-0097","parentItemId":null,"revision":1,"payload":{"prompt":"A corporation is owned by:","options":["A single proprietor","Collaborative partners","Shareholders with stakes","Public regulators"],"correctOption":2,"section":"Forms of Business Firm","explanation":"A corporation (company) is owned by its shareholders, each holding a stake through the shares they buy. Option A describes a sole proprietorship, and B describes a partnership."}},{"itemId":"81086c09-7b25-5750-ac4a-c07a94258026","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"379a87b3-78ef-5463-84a3-52c60761a962","sourceKey":"bank:FIN101:FIN-0098","parentItemId":null,"revision":1,"payload":{"prompt":"An advantage of a partnership is:","options":["Liability caps for owners","Pooled skills and resources","Sole proprietor control","Dual tax burdens"],"correctOption":1,"section":"Forms of Business Firm","explanation":"Partners bring together their money, skills and experience, so the business has more resources than one person could provide. Option A is wrong because ordinary partners have unlimited liability, and C describes a sole proprietorship."}},{"itemId":"686eb773-aac0-524b-8170-2f65ee661769","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c49eee64-5602-5a6c-bc20-0634dd9ad0e8","sourceKey":"bank:FIN101:FIN-0099","parentItemId":null,"revision":1,"payload":{"prompt":"A sole proprietorship ends when:","options":["The owner passes or shuts down","The firm expands rapidly","Shares are publicly sold","Partners join the venture"],"correctOption":0,"section":"Forms of Business Firm","explanation":"A sole proprietorship has no separate legal existence, so it usually ends when the owner dies or decides to close the business. Fast expansion (B) does not end it, and C and D would change it into a company or partnership."}},{"itemId":"dc3b7a82-d783-5288-9bf0-816d4a1b57e5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"78dcfbef-ffb9-5e53-8f67-e9827352ad20","sourceKey":"bank:FIN101:FIN-0101","parentItemId":null,"revision":1,"payload":{"prompt":"What is finance primarily concerned with?","options":["Marketing strategies","Management of money and investments","Product pricing","Employee welfare"],"correctOption":1,"section":"Overview of Finance","explanation":"Finance deals with managing money: raising funds, investing them and managing risk and return. Marketing (A), pricing (C) and employee welfare (D) belong to other business functions."}},{"itemId":"7a0aff11-bdcc-5fbb-a44b-ce5931373263","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3bc9cea9-6934-50e7-bc55-ba5cd7710777","sourceKey":"bank:FIN101:FIN-0102","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a long-term source of finance?","options":["Trade credit","Commercial paper","Bank overdraft","Debenture"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"A debenture is a long-term debt instrument a company issues to raise loan capital, often repayable over many years, so it is a long-term source of finance. Trade credit (A), commercial paper (B) and a bank overdraft (C) are short-term sources that are usually repaid within a year."}},{"itemId":"6271ca75-f8f1-536b-a2b4-786218f9b68c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"05864263-28ad-580d-afd5-f211f60756ce","sourceKey":"bank:FIN101:FIN-0103","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main goal of financial management?","options":["Maximizing shareholder wealth","Reducing taxes","Increasing market share","Minimizing costs"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Financial management aims to maximise shareholder wealth, which means increasing the value of the owners' investment over the long run. Reducing taxes (B), increasing market share (C) and minimising costs (D) can help, but they are means to an end rather than the main goal."}},{"itemId":"ebb616b8-972c-53fc-81bb-09a92b409514","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"01f68ecf-0157-5dbe-b532-7aa5bd920b7a","sourceKey":"bank:FIN101:FIN-0104","parentItemId":null,"revision":1,"payload":{"prompt":"What is the capital market used for?","options":["Short-term borrowing","Long-term borrowing and lending","Currency exchange","Day-to-day business expenses"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The capital market is where long-term funds are borrowed and lent, through instruments such as shares, bonds and debentures. Option A describes the money market, and C describes the foreign exchange market."}},{"itemId":"546af195-28ef-5ee7-9e78-8dfdec6f61a9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"687c9598-1b39-5969-8e4c-848cca67a86c","sourceKey":"bank:FIN101:FIN-0105","parentItemId":null,"revision":1,"payload":{"prompt":"A financial statement that shows a company's performance over time is called:","options":["Balance sheet","Income statement","Statement of cash flows","Trial balance"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The income statement (profit and loss account) shows revenue, expenses and profit over a period, so it reports performance. The balance sheet (A) shows position at one date, and the trial balance (D) is just a bookkeeping check, not a financial statement."}},{"itemId":"7a20e5e4-8df8-560f-8514-d750f834af49","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8f939537-f613-50c5-bfbf-331ea1f27947","sourceKey":"bank:FIN101:FIN-0106","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a financial institution?","options":["Commercial banks","Stock exchange","Insurance companies","Supermarkets"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"Financial institutions deal in money and financial services, such as banks, insurance companies and stock exchanges. A supermarket sells goods to consumers, so it is not a financial institution."}},{"itemId":"11118945-592b-5cf4-8cd1-9148c79e03eb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9a471d59-a9f8-5fe9-af75-b0b7a82c8c15","sourceKey":"bank:FIN101:FIN-0107","parentItemId":null,"revision":1,"payload":{"prompt":"Liquidity refers to:","options":["The profitability of a company","The ease of converting assets to cash","The total liabilities of a company","The long-term growth of a company"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Liquidity is how easily and quickly an asset can be turned into cash without losing much value. Profitability (A), total liabilities (C) and growth (D) are different measures of a business."}},{"itemId":"9db119ee-2651-56f2-a32b-f6e9050b5af9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"dd657e59-f92d-5f79-b56f-7c6b139f2096","sourceKey":"bank:FIN101:FIN-0108","parentItemId":null,"revision":1,"payload":{"prompt":"The time value of money concept implies:","options":["A naira today is worth less than a naira tomorrow","A naira today is worth more than a naira tomorrow","Money has no value over time","Money value remains constant"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Money today is worth more than the same amount tomorrow because it can be invested to earn interest. Option A reverses this, and C and D ignore the time value of money."}},{"itemId":"6cb4e735-882c-5ce1-a601-24bd9545e066","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4b525aa3-c973-50a2-bb4a-b807143b3413","sourceKey":"bank:FIN101:FIN-0109","parentItemId":null,"revision":1,"payload":{"prompt":"What is another name for equity financing?","options":["Loan capital","Ownership capital","Fixed capital","Debt capital"],"correctOption":1,"section":"Overview of Finance","explanation":"Equity finance comes from the owners, for example by issuing shares, so it is also called ownership capital. Loan capital (A) and debt capital (D) are borrowed funds, which are the opposite of equity."}},{"itemId":"ea3e23df-db74-51fb-88ef-8501a5a9ec51","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3d9c2af5-b6a2-5794-bf63-49e464cf9f44","sourceKey":"bank:FIN101:FIN-0110","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial ratio measures a company's ability to pay short-term liabilities?","options":["Profit margin ratio","Quick ratio","Debt-to-equity ratio","Inventory turnover"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The quick (acid-test) ratio compares liquid assets with current liabilities, so it measures the ability to pay short-term debts. Profit margin (A) measures profitability, debt-to-equity (C) measures leverage, and inventory turnover (D) measures activity."}},{"itemId":"79f0834f-3c15-5542-8e13-74ede9a96867","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"098b1efe-465f-5c85-9a71-05549b1ccbe1","sourceKey":"bank:FIN101:FIN-0111","parentItemId":null,"revision":1,"payload":{"prompt":"What is a dividend?","options":["A company's net profit","Interest paid on debt","A portion of a company's profit distributed to shareholders","An expense on the balance sheet"],"correctOption":2,"section":"Overview of Finance","explanation":"A dividend is the part of a company's profit paid out to its shareholders as a return on their investment. Option A is total profit, and B describes interest paid to lenders, not owners."}},{"itemId":"8f597286-8582-5731-a57f-864e742ec2bd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d9e0c9ae-9f45-5c0d-b218-faecb200a3a6","sourceKey":"bank:FIN101:FIN-0113","parentItemId":null,"revision":1,"payload":{"prompt":"The cost of capital refers to:","options":["The cost of operating a business","The cost of obtaining funds","The cost of goods sold","The cost of management"],"correctOption":1,"section":"Overview of Finance","explanation":"The cost of capital is the return a firm must pay to obtain funds, such as interest on debt or the return shareholders expect. Option A is general operating cost, and C is the cost of the goods a firm sells."}},{"itemId":"20a034d8-77d3-59d7-96ae-36f626fb107f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3d7e9356-bb23-5ede-91f8-1bb3309eeddd","sourceKey":"bank:FIN101:FIN-0114","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of a financial asset?","options":["Machinery","Cash","Inventory","Accounts payable"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A financial asset is a claim to money, such as cash, shares or bonds. Machinery (A) and inventory (C) are physical assets, and accounts payable (D) is a liability, not an asset."}},{"itemId":"0ec5c283-9dfd-5582-a105-3342ed435496","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4917e375-a19b-5029-883d-b2207632fab3","sourceKey":"bank:FIN101:FIN-0115","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial statement shows a company's financial position at a specific point in time?","options":["Balance sheet","Income statement","Cash flow statement","Profit and loss statement"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"The balance sheet (statement of financial position) shows assets, liabilities and equity at a single date. The income statement (B) and profit and loss statement (D) cover a period, as does the cash flow statement (C)."}},{"itemId":"56556694-5aae-5b71-8510-f1bf05b5e3e3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ba4bc841-8e12-520a-80db-341997146677","sourceKey":"bank:FIN101:FIN-0116","parentItemId":null,"revision":1,"payload":{"prompt":"What does ROI stand for?","options":["Return on Interest","Rate of Investment","Return on Investment","Return of Income"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"ROI stands for Return on Investment, which measures the gain from an investment relative to its cost. Options A, B and D are not the correct expansion of the abbreviation."}},{"itemId":"c33238f4-0a36-51e9-9169-9469060a2606","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8f3b3e28-3359-5339-83f6-31a4176e82f4","sourceKey":"bank:FIN101:FIN-0117","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a component of working capital?","options":["Long-term debt","Fixed assets","Current liabilities","Share capital"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Working capital = Current assets - Current liabilities, so current liabilities are a component of it. Long-term debt (A), fixed assets (B) and share capital (D) are long-term items, not part of working capital."}},{"itemId":"2809533b-e11d-5f8f-a931-581c4ebfb95f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e0580f67-e663-5b90-823d-727be5aeb5ea","sourceKey":"bank:FIN101:FIN-0119","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial market deals with short-term securities?","options":["Capital market","Money market","Commodity market","Forex market"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The money market is where short-term securities, usually maturing within a year, such as treasury bills and commercial paper, are traded. The capital market (A) deals in long-term securities, the commodity market (C) trades physical goods, and the forex market (D) trades currencies."}},{"itemId":"5ced735e-a06d-5c36-9c4f-61eb587f148e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"819ed785-c798-5388-a1be-3e7758182e0c","sourceKey":"bank:FIN101:FIN-0120","parentItemId":null,"revision":1,"payload":{"prompt":"Capital budgeting is primarily concerned with:","options":["Managing daily expenses","Making long-term investment decisions","Setting up marketing plans","Managing human resources"],"correctOption":1,"section":"Overview of Finance","explanation":"Capital budgeting is the process of evaluating and choosing long-term investments, such as new machinery or a new factory, that will bring returns over many years. Managing daily expenses (A) is working capital management, and C and D belong to marketing and human resources."}},{"itemId":"ed942fce-addc-5ccf-8e88-80b02f58e4e8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5e0a1ce8-3f29-54d7-ae28-2fb31c1bc440","sourceKey":"bank:FIN101:FIN-0122","parentItemId":null,"revision":1,"payload":{"prompt":"Retained earnings refer to:","options":["Dividends paid to shareholders","Net income reinvested in the business","Operating expenses","Short-term liabilities"],"correctOption":1,"section":"Overview of Finance","explanation":"Retained earnings are the part of a company's net income that is kept and ploughed back into the business instead of being paid out. Option A, dividends, is the part of profit that is paid out, which is the opposite of retaining it. Operating expenses (C) and short-term liabilities (D) are costs and obligations, not reinvested profit."}},{"itemId":"457b82ff-6897-57cc-b331-4bc9cc113784","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d9b3147b-cb1a-5551-b89b-6efc3b50de70","sourceKey":"bank:FIN101:FIN-0123","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following represents ownership in a company?","options":["Bond","Stock","Loan","Certificate of deposit"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A stock (share) makes the holder a part-owner of the company, with a claim on its profits and assets. Bonds (A), loans (C) and certificates of deposit (D) are all debt instruments, so the holder is a lender to the issuer, not an owner."}},{"itemId":"c81b0541-ade2-5345-a8b1-65f0fcff3522","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"498a4407-57b3-5794-8b6a-1a3b2b62813b","sourceKey":"bank:FIN101:FIN-0124","parentItemId":null,"revision":1,"payload":{"prompt":"Which method of financial statement analysis examines a firm's cash inflows and outflows from operating, investing and financing activities?","options":["Horizontal (trend) analysis","Vertical (common-size) analysis","Cash flow analysis","Ratio analysis"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Cash flow analysis looks at the money coming into and going out of a business, grouped into operating, investing and financing activities, to judge whether the firm generates enough cash. Horizontal analysis (A) tracks changes in items from year to year, vertical analysis (B) shows each item as a percentage of a base figure, and ratio analysis (D) relates figures in the statements to one another."}},{"itemId":"b8c9129f-aacc-57bc-81e0-a0704f8cd412","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7d441daa-be26-5778-a882-5950d910fa52","sourceKey":"bank:FIN101:FIN-0125","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an example of current assets?","options":["Inventory","Accounts receivable","Land","Cash"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Land is a fixed (non-current) asset because it is held for long-term use and is not expected to be turned into cash within a year. Inventory (A), accounts receivable (B) and cash (D) are all current assets, since they are cash or will become cash within the normal operating cycle."}},{"itemId":"32dad1cf-9010-539f-bb6f-a6826d9765c4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"084297bd-5f08-5d65-af32-dd9a2012b298","sourceKey":"bank:FIN101:FIN-0126","parentItemId":null,"revision":1,"payload":{"prompt":"What does the term \"leverage\" refer to in finance?","options":["Using equity only for financing","Using debt to finance investments","Reducing operational expenses","Increasing dividends"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Leverage means using borrowed money (debt) to finance investments, with the aim of boosting returns to the owners. Option A is the opposite, since using equity only means there is no leverage at all. Cutting expenses (C) or raising dividends (D) have nothing to do with how the business is financed."}},{"itemId":"5df7c352-10d0-5920-85ea-76c88d0cafe3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"bf44854b-dea6-5b81-9a50-dd1bb1530dc1","sourceKey":"bank:FIN101:FIN-0128","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow statement is divided into how many sections?","options":["2","3","4","5"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The cash flow statement has three sections: operating activities, investing activities and financing activities. Option A leaves one of these out, while C and D add sections that the statement does not have."}},{"itemId":"44523b95-c5e3-506e-b0fc-99d3e19b8562","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1e7b82b5-ecaf-58d1-be6e-badc06a935a2","sourceKey":"bank:FIN101:FIN-0129","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is not a source of short-term finance?","options":["Bank overdraft","Trade credit","Commercial paper","Bonds"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"Bonds are long-term debt, usually running for many years, so they are not a source of short-term finance. Bank overdrafts (A), trade credit (B) and commercial paper (C) are all repaid within a year, which is why they are classed as short-term finance."}},{"itemId":"3a266d06-5fae-5905-9a5c-1c0335d1b198","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7c020b9c-26bb-5d90-a505-b6cf7cf61e9a","sourceKey":"bank:FIN101:FIN-0130","parentItemId":null,"revision":1,"payload":{"prompt":"The process of determining the present value of future cash flows is called:","options":["Compounding","Discounting","Budgeting","Hedging"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Discounting converts a future amount back into its value today by removing the interest it could have earned, for example PV = FV / (1 + r)^n. Compounding (A) works the other way, growing a present amount into a future value. Budgeting (C) and hedging (D) are unrelated activities."}},{"itemId":"c17b81a1-e19d-5620-8367-c795a274f0b4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7b84e78b-6b7d-5ee6-9c90-ea50a7c3f9c5","sourceKey":"bank:FIN101:FIN-0131","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a characteristic of a sole proprietorship?","options":["Limited liability","Unlimited liability","Legal personality","Separate taxation"],"correctOption":1,"section":"Forms of Business Firm","explanation":"A sole proprietor has unlimited liability, meaning the owner's personal property can be used to pay the business's debts. Limited liability (A) and separate legal personality (C) belong to registered companies, not sole proprietorships. Separate taxation (D) is also a company feature, since a sole trader's profit is taxed as the owner's personal income."}},{"itemId":"565544fb-054c-54bc-9acf-907830f118d8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8f9a9c7b-c608-5bdc-916f-b98568b9d781","sourceKey":"bank:FIN101:FIN-0132","parentItemId":null,"revision":1,"payload":{"prompt":"A portfolio is:","options":["A collection of financial statements","A combination of financial investments","A cash management strategy","A tax-saving plan"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"A portfolio is a collection or combination of investments, such as shares and bonds, held by one investor. Option A confuses it with a set of financial statements, while C and D describe a cash management strategy and a tax plan, not a group of investments."}},{"itemId":"172f6e16-086f-5309-bf34-da4541446bcd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"49181cd5-4e7b-5366-ae48-5d18fccdb788","sourceKey":"bank:FIN101:FIN-0133","parentItemId":null,"revision":1,"payload":{"prompt":"What is the major role of a stock exchange?","options":["Lend money to businesses","Facilitate the trading of securities","Manage national debts","Control interest rates"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"A stock exchange provides an organised market where existing securities such as shares and bonds are bought and sold. It does not lend money to businesses (A); that is what banks do. Managing national debt (C) and controlling interest rates (D) are central bank and government roles."}},{"itemId":"e65648b5-bf08-51ca-8989-ceb6fcaa6a57","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9ed47d83-a135-5a91-9888-57b9092f691f","sourceKey":"bank:FIN101:FIN-0134","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a capital budgeting technique?","options":["Internal Rate of Return (IRR)","Debt-to-equity ratio","Current ratio","Cash conversion cycle"],"correctOption":0,"section":"Overview of Finance","explanation":"Internal Rate of Return (IRR) is used to evaluate long-term investment projects, which makes it a capital budgeting technique. The debt-to-equity ratio (B) and current ratio (C) are financial ratios, and the cash conversion cycle (D) is a working capital measure, so none of them are used to appraise projects."}},{"itemId":"cd446033-25b6-504a-8325-2e9c9dacdde5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9bfb7448-8e87-5734-bda8-279bf802bb86","sourceKey":"bank:FIN101:FIN-0135","parentItemId":null,"revision":1,"payload":{"prompt":"Which financial statement shows cash inflows and outflows?","options":["Balance sheet","Income statement","Statement of cash flows","Trial balance"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"The statement of cash flows records the actual cash coming into and going out of a business over a period. The balance sheet (A) shows assets and liabilities at a single date, and the income statement (B) shows revenue and expenses, which can differ from cash movements. A trial balance (D) is just a list of ledger balances used to check the books."}},{"itemId":"2d3b6cb3-d788-5b54-b269-bd0e442b028a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a8e11a13-c5d3-5f97-a2ed-4737ec7f67e9","sourceKey":"bank:FIN101:FIN-0136","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these has traditionally been regarded as the primary objective of a business firm?","options":["Maximizing profits","Customer satisfaction","Employee welfare","Reducing liabilities"],"correctOption":0,"section":"Objectives of a Business Firm","explanation":"Profit maximisation, earning as much revenue as possible while keeping the cost of output low, has traditionally been regarded as the primary objective of a firm. Customer satisfaction (B) and employee welfare (C) are important, but they support the business rather than being its traditional main goal. Reducing liabilities (D) is a financial management choice, not the overall objective."}},{"itemId":"6d6e5ecb-7669-5319-ac01-cfdfa8b841ab","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0cfd3f59-519e-564b-bbbd-4af505d18969","sourceKey":"bank:FIN101:FIN-0137","parentItemId":null,"revision":1,"payload":{"prompt":"Market risk is also known as:","options":["Diversifiable risk","Systematic risk","Unsystematic risk","Credit risk"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Market risk is the risk that affects the whole market, for example from inflation or interest rate changes, and it is also called systematic risk. It cannot be removed by diversification, so options A and C (diversifiable or unsystematic risk) describe the opposite type. Credit risk (D) is the risk that a borrower fails to repay."}},{"itemId":"598cc2b2-4bfe-51c8-83fb-a2d29b9bf5f1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"272ed73d-6f6a-587e-bf29-2cbd2662dae0","sourceKey":"bank:FIN101:FIN-0138","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not a form of business ownership?","options":["Sole proprietorship","Partnership","Corporation","Interest rate swap"],"correctOption":3,"section":"Forms of Business Firm","explanation":"An interest rate swap is a financial contract for exchanging interest payments, not a way of owning a business. Sole proprietorship (A), partnership (B) and corporation (C) are the main forms of business ownership."}},{"itemId":"a4b1e7cd-e693-52f3-8771-f51f6445789d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5e3f249c-fa55-53f6-9287-b8fb838f1723","sourceKey":"bank:FIN101:FIN-0139","parentItemId":null,"revision":1,"payload":{"prompt":"Current liabilities are obligations that are expected to be settled within:","options":["6 months","1 year","2 years","5 years"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Current liabilities are debts due for settlement within one year (or within the normal operating cycle), such as trade creditors and overdrafts. Six months (A) is too short a cut-off, while two or five years (C and D) would cover long-term liabilities."}},{"itemId":"f9fc917b-a35b-516f-ac23-eadc01ad31f1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"617c2641-4743-5f3f-9030-7ae3840fd9f5","sourceKey":"bank:FIN101:FIN-0140","parentItemId":null,"revision":1,"payload":{"prompt":"What is the formula for calculating net profit?","options":["Gross profit - Operating expenses","Total revenue - Total expenses","Sales - Cost of goods sold","Operating income + Tax"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Net profit is what remains after all expenses are taken away from total revenue. Option A gives operating profit, which is before items such as interest and tax are deducted. Option C is gross profit, and option D adds tax back instead of removing it."}},{"itemId":"81c0d6d8-de1e-5834-90aa-ae2b7a373b43","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9159f153-964b-5d34-b6d0-af583c999386","sourceKey":"bank:FIN101:FIN-0141","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not part of shareholders' equity?","options":["Common stock","Retained earnings","Accounts payable","Additional paid-in capital"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Accounts payable is money the business owes to suppliers, so it is a liability, not part of the owners' equity. Common stock (A), retained earnings (B) and additional paid-in capital (D) all belong to the shareholders and form shareholders' equity."}},{"itemId":"e12adfb1-42f4-50e0-adff-d0e4a7fa113e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c61f31e8-5214-5bf8-b8a0-e81fa5d0755f","sourceKey":"bank:FIN101:FIN-0142","parentItemId":null,"revision":1,"payload":{"prompt":"A financial ratio that measures profitability is:","options":["Debt ratio","Current ratio","Return on equity (ROE)","Quick ratio"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Return on equity (ROE) measures how much profit a company earns for each naira of shareholders' funds, so it is a profitability ratio. The debt ratio (A) is a leverage ratio, while the current ratio (B) and quick ratio (D) measure liquidity."}},{"itemId":"3e9ad93b-0631-5405-bff2-3578a43e5e0f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f9c718e4-1b50-5b12-b44e-c987839e4a17","sourceKey":"bank:FIN101:FIN-0143","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is not an external user of financial statements?","options":["Investors","Creditors","Management","Government"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Management prepares and uses financial statements from inside the business, so it is an internal user. Investors (A), creditors (B) and government (D) are outside the business and rely on published statements to make decisions, which makes them external users."}},{"itemId":"7f6016a2-aa35-5e8f-b966-08344dcdb674","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"eecdd9f9-d8a9-50b1-9b6f-dfda8b7d4312","sourceKey":"bank:FIN101:FIN-0145","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an advantage of equity financing?","options":["No obligation to repay","Interest payments are tax-deductible","Reduces ownership control","Short-term funding"],"correctOption":0,"section":"Overview of Finance","explanation":"Equity finance does not have to be repaid, and dividends are not a fixed legal obligation, which reduces the pressure on the firm. Tax-deductible interest (B) is an advantage of debt, not equity. Diluting ownership control (C) is actually a disadvantage of issuing shares, and equity is long-term, not short-term funding (D)."}},{"itemId":"80053b27-3310-5c02-b41c-4324580ac5b0","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e4d7f778-1cef-53e1-827c-5ee8097986c9","sourceKey":"bank:FIN101:FIN-0146","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is not a component of the income statement?","options":["Revenue","Expenses","Liabilities","Net income"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"The income statement reports revenue, expenses and the resulting net income for a period. Liabilities are amounts the business owes at a point in time, so they appear on the balance sheet, not the income statement. Options A, B and D are all core parts of the income statement."}},{"itemId":"25405aae-0549-5717-b61d-5bff84c07f7e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"58a88789-c4dc-5c3d-a79e-ae1169e3aece","sourceKey":"bank:FIN101:FIN-0147","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not part of working capital?","options":["Cash","Inventory","Fixed assets","Accounts receivable"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Working capital is current assets minus current liabilities, so it covers short-term items like cash, inventory and receivables. Fixed assets such as buildings and machinery are long-term, so they are not part of working capital. Options A, B and D are all current assets."}},{"itemId":"3576b043-bce2-53e2-8196-8557aa76a381","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"def3cd40-dce5-50af-84f3-ed2c61f41be7","sourceKey":"bank:FIN101:FIN-0148","parentItemId":null,"revision":1,"payload":{"prompt":"A debt instrument that pays interest and is redeemable at a future date is a:","options":["Bond","Stock","Mutual fund","Derivative"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"A bond is a debt instrument: the issuer borrows money, pays interest over the life of the bond and repays the principal on the redemption date. Stock (B) represents ownership, not debt. A mutual fund (C) is a pooled investment, and a derivative (D) gets its value from another asset."}},{"itemId":"498561f7-9884-5dcb-b264-4e567feaf63c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f16818af-efeb-5f25-a692-835339cdc96f","sourceKey":"bank:FIN101:FIN-0149","parentItemId":null,"revision":1,"payload":{"prompt":"An increase in working capital usually indicates:","options":["Higher liquidity","Higher debt levels","Lower profitability","Lower liquidity"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Working capital is current assets minus current liabilities, so a rise usually means the business has more short-term resources to cover its short-term debts, which is higher liquidity. Option D says the opposite. Working capital does not directly measure debt levels (B) or profitability (C)."}},{"itemId":"b273dede-97cb-5516-af91-c7727b447443","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8442db7c-63a7-5eb4-ab58-e8305460b7b7","sourceKey":"bank:FIN101:FIN-0150","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary role of a financial manager?","options":["Manage marketing activities","Ensure customer satisfaction","Manage a firm's finances and maximize value","Prepare legal documents"],"correctOption":2,"section":"Overview of Finance","explanation":"A financial manager looks after the firm's finances, deciding how funds are raised, invested and distributed so as to maximise the value of the firm. Marketing (A), customer satisfaction (B) and legal documents (D) belong to other departments."}},{"itemId":"f2e7ecc9-f0bd-5c99-b0c3-d89a51d7aeaa","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3502e572-fa6b-5c6b-be14-7d39dfe7e49e","sourceKey":"bank:FIN101:FIN-0151","parentItemId":null,"revision":1,"payload":{"prompt":"Find the present value of N7,500 promised to be paid in 5 years time. Interest is compounded continuously at 20%.","options":["N2,759","N6,500","N7,900","N5,800"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"With continuous compounding, PV = FV x e^(-rt). Here PV = 7,500 x e^(-0.20 x 5) = 7,500 x e^(-1) = 7,500 x 0.3679 = N2,759. Options B, C and D are far too high; discounting over 5 years at 20% must reduce the amount sharply, and C is even more than the future amount."}},{"itemId":"4048a62b-3877-547e-95d7-04475a016edc","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"ef2f9f9f-f0cd-522e-af6b-12aa4474b9b4","sourceKey":"bank:FIN101:FIN-0152","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take N5,000 invested now to accumulate to N30,000 if the interest rate is 20% per annum compounded annually?","options":["10 years","11 years","9 years","8 years"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Solve 5,000 x (1.20)^n = 30,000, so (1.20)^n = 6 and n = ln 6 / ln 1.20 = 9.83 years, which is 10 years to the nearest year. Nine years (C) is not enough, since 5,000 x (1.20)^9 = N25,799, short of N30,000. Eleven years (B) and eight years (D) are further from the exact figure."}},{"itemId":"57a0632d-db4e-5849-98f4-ba23ad8aee7f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5394d4c9-77b5-5edb-9314-6d538730f618","sourceKey":"bank:FIN101:FIN-0154","parentItemId":null,"revision":1,"payload":{"prompt":"What will be the total amount receivable from an investment of N800,000 made for 4 and half years at 12% compounded annual interest?","options":["N1,332,205","N1,258,815","N1,258,816","N896,000"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Compound value = 800,000 x (1.12)^4.5 = 800,000 x 1.6653 = N1,332,205. Option D, N896,000, is just one year of 12% interest added (800,000 x 1.12). Options B and C are close to each other but do not match the compounding of 12% for 4.5 years."}},{"itemId":"d64deede-aa80-55a1-be02-67c7abb0d63a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"bf7d6fb5-7a8c-5b0b-9f8a-a1bcefeb0a86","sourceKey":"bank:FIN101:FIN-0155","parentItemId":null,"revision":1,"payload":{"prompt":"Kenny wishes to determine how much depositing N15,000 at the end of each year will amount to in the next five years. If the annual interest rate is 12%, how much will be in his account?","options":["N26,435","N106,728","N95,293","N54,072"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"This is the future value of an ordinary annuity: FV = 15,000 x [(1.12)^5 - 1] / 0.12 = 15,000 x 6.3528 = N95,293. Option B, N106,728, is what you get if each deposit is made at the start of the year (an annuity due). Option A is the future value of just one N15,000 deposit, and D is the present value of the five deposits, not their future value."}},{"itemId":"54c80fd2-9229-58a5-b24c-4084e89f911a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"bbcb4c0a-8378-575e-9b01-5ca8893de953","sourceKey":"bank:FIN101:FIN-0156","parentItemId":null,"revision":1,"payload":{"prompt":"Goodluck Plc. Has been offered an opportunity to receive N350,000 in 6 years time from now. If the firm can earn 10% on its money, how much is it worth today?","options":["N197,566","N620,046","N177,566","N217,322"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"PV = 350,000 / (1.10)^6 = 350,000 / 1.7716 = N197,566. Option B, N620,046, is the future value, which compounds forward instead of discounting back. Options C and D are close in size but do not match the correct discount factor."}},{"itemId":"14963ba6-7463-5787-844c-562ff74a2ff6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"017865b9-987c-595e-99d0-361637e0dedd","sourceKey":"bank:FIN101:FIN-0157","parentItemId":null,"revision":1,"payload":{"prompt":"An account holder deposits N8,500 in savings account paying 8% interest compounded quarterly. How much will be in the account at the end of the five years.","options":["N12,600","N12,631","N12,489","N39,618"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"With quarterly compounding, use a rate of 8% / 4 = 2% per quarter for 5 x 4 = 20 quarters. FV = 8,500 x (1.02)^20 = 8,500 x 1.4859 = N12,631. Option C uses annual instead of quarterly compounding, giving 8,500 x (1.08)^5 = N12,489. Option A (N12,600) and D (N39,618) do not match the calculation."}},{"itemId":"d831cd4a-a10b-5841-a7b6-ec109e42d859","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5d45e40e-880e-5aef-b7f0-35f11a51041d","sourceKey":"bank:FIN101:FIN-0159","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nWhat is the expected value of Security X","options":["N25,000","N31,000","N28,500","N31,500"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected value = sum of each return x its probability: E(X) = 27,000(0.5) + 30,000(0.2) + 35,000(0.1) + 40,000(0.2) = 13,500 + 6,000 + 3,500 + 8,000 = N31,000. Option D, N31,500, comes from an arithmetic slip, and N25,000 (A) is too low, since every return of X is at least N27,000."}},{"itemId":"73c3e92c-c88c-5987-85dc-9f1a91df492e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2cfd1367-c5b1-5a98-88ba-18bd84024996","sourceKey":"bank:FIN101:FIN-0161","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe variance of Security Y is","options":["N23,250,000","N27,500,000","N23,500,000","none of the above"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Variance = sum of p x (return - expected value)^2. With E(Y) = N25,500: 0.1(15,000-25,500)^2 + 0.3(22,000-25,500)^2 + 0.2(27,000-25,500)^2 + 0.4(30,000-25,500)^2 = 11,025,000 + 3,675,000 + 450,000 + 8,100,000 = 23,250,000. Options B and C are close but do not match this total, so D (none of the above) is also wrong."}},{"itemId":"23e24d01-4328-5772-96f2-65a81a0f7412","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6b2863c4-d518-5c63-9c95-720a7bdf41a9","sourceKey":"bank:FIN101:FIN-0162","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe standard deviation of Security X is","options":["N5,099","N4,822","N5,220","none of the above"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"First find the variance of X around E(X) = N31,000: 0.5(-4,000)^2 + 0.2(-1,000)^2 + 0.1(4,000)^2 + 0.2(9,000)^2 = 8,000,000 + 200,000 + 1,600,000 + 16,200,000 = 26,000,000. Standard deviation = square root of 26,000,000 = N5,099. Option B (N4,822) is the standard deviation of Y and option C (N5,220) is that of Z."}},{"itemId":"c969f894-5a6a-5af1-ba69-0d7ac2c1c767","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6c2b227b-7254-5ba5-b2c8-a4b7d642c47f","sourceKey":"bank:FIN101:FIN-0163","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security Z is","options":["16%","18%","20%","19%"],"correctOption":2,"section":"Analysis of Risk in Financial Decisions","explanation":"Coefficient of variation = standard deviation / expected value. For Z, E(Z) = N25,500 and variance = 27,250,000, so SD = N5,220 and CV = 5,220 / 25,500 = 0.205, about 20%. Options A (16%) and D (19%) are roughly the CVs of X and Y, not Z."}},{"itemId":"716efc3b-6869-5971-91c1-c0065e4f506a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"40285e9f-b80b-5547-b17a-c941706d58aa","sourceKey":"bank:FIN101:FIN-0165","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security Y is","options":["16%","18%","20%","19%"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"For Y, E(Y) = N25,500 and variance = 23,250,000, so SD = square root of 23,250,000 = N4,822. CV = 4,822 / 25,500 = 0.189, which is about 19%. Option B (18%) is slightly too low, and A (16%) belongs to Security X."}},{"itemId":"8238f730-282a-51a5-91b1-eac039e5a022","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"829cf44c-94b8-5e10-b21c-9e6fb35d5098","sourceKey":"bank:FIN101:FIN-0166","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nThe coefficient of variation of Security X is","options":["16%","18%","20%","19%"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"For X, E(X) = N31,000 and SD = square root of 26,000,000 = N5,099. CV = 5,099 / 31,000 = 0.164, about 16%. Options C (20%) and D (19%) are roughly the CVs of Z and Y."}},{"itemId":"d6d6b9fe-7520-5388-b8ef-9cb9bed9b03c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fee24193-582d-5176-bdc2-3e0848b2338c","sourceKey":"bank:FIN101:FIN-0167","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] James is considering investment in the following securities whose random returns are given below:\nSecurity X - Return (Probability): 27,000 (0.5); 30,000 (0.2); 35,000 (0.1); 40,000 (0.2)\nSecurity Y - Return (Probability): 15,000 (0.1); 22,000 (0.3); 27,000 (0.2); 30,000 (0.4)\nSecurity Z - Return (Probability): 20,000 (0.4); 25,000 (0.2); 30,000 (0.3); 35,000 (0.1)\nIf James is a risk averse investor and risk is measured by the coefficient of variation, which security would you recommend to him?","options":["Security X","Security Y","None, because all three securities carry the same risk","Security Z"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"The coefficient of variation measures risk per naira of expected return, and a risk-averse investor picks the lowest one. X has a CV of about 16% (5,099 / 31,000), against about 19% for Y and 20% for Z, so X is the choice. Option B is tempting because Y has the lowest standard deviation, but its expected return is also lower, so its risk per naira of return is higher."}},{"itemId":"dae8735f-dde9-5fb0-b02f-0247238fb948","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"586b363a-2466-5c94-8b7c-61d2ce70c3c8","sourceKey":"bank:FIN101:FIN-0170","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] DATA (N000): Credit Sales 40,000; Average Debtors 10,000; Profit before Tax 6,000; Total Assets 54,000; Interest on Loan 8,000; Stock 3,000; Cash 7,600; Trade Creditors 3,900; Tax rate 35%; Shareholder funds 160,000; Long term debt 10,000\nThe Return on Shareholder equity (profit after tax / shareholder funds) to the nearest whole number is","options":["2%","3%","4%","5%"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"Return on shareholders' equity here is profit after tax divided by shareholders' funds. Profit after tax = 6,000 x (1 - 0.35) = 3,900, so the return = 3,900 / 160,000 = 2.44%, which is 2% to the nearest whole number. Option C (4%) comes from using profit before tax (6,000 / 160,000 = 3.75%), which ignores the tax the firm must pay."}},{"itemId":"e4dbc400-3b27-5da7-bbd5-9f01b1ba267a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"57411b6c-3668-5589-8c1a-1c022be228e6","sourceKey":"bank:FIN101:FIN-0171","parentItemId":null,"revision":1,"payload":{"prompt":"[Table] DATA (N000): Credit Sales 40,000; Average Debtors 10,000; Profit before Tax 6,000; Total Assets 54,000; Interest on Loan 8,000; Stock 3,000; Cash 7,600; Trade Creditors 3,900; Tax rate 35%; Shareholder funds 160,000; Long term debt 10,000\nThe Return on total assets (profit before interest and tax / total assets) to the nearest whole percent is","options":["25%","26%","27%","28%"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Return on total assets here compares profit before interest and tax with total assets. Profit before interest and tax = 6,000 + 8,000 = 14,000, so the return = 14,000 / 54,000 = 25.9%, which is 26% to the nearest whole percent. Option A (25%) rounds down incorrectly, and C and D overstate the return."}},{"itemId":"bd50777e-f546-5a68-bdb7-a716fef7f702","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"778d87e7-a6b0-5c79-9796-58a10b0e6dfe","sourceKey":"bank:FIN101:FIN-0175","parentItemId":null,"revision":1,"payload":{"prompt":"Long-term solvency ratio is also known as","options":["Efficiency ratio.","Stability ratio","Working capital ratio","Actual growth ratio"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Long-term solvency ratios show whether a firm can meet its long-term obligations and remain stable, so they are also called stability ratios. Efficiency ratios (A) measure performance in relative terms, and the working capital ratio (C) is another name for the short-term liquidity group. Actual growth ratio (D) is another name for the stock market or investor interest ratios, not long-term solvency."}},{"itemId":"dab73054-91cb-5490-afe0-94683f3d2fc9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c0a43de9-eb19-589b-8e89-e84b777df8d4","sourceKey":"bank:FIN101:FIN-0176","parentItemId":null,"revision":1,"payload":{"prompt":"Financing decision is otherwise known as","options":["Capital budgeting decision","Capital rating decision","Capital project decision","Capital mix decision"],"correctOption":3,"section":"Overview of Finance","explanation":"The financing decision is about choosing the right combination of debt and equity to fund the firm, which is why it is called the capital mix (capital structure) decision. Capital budgeting (A) and capital project decisions (C) belong to the investment decision. Option B is not a recognised term."}},{"itemId":"a628261a-e59d-5cde-ade0-303c628afafe","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0c59aadf-f542-54c1-abbc-ee8e3bd1119b","sourceKey":"bank:FIN101:FIN-0178","parentItemId":null,"revision":1,"payload":{"prompt":"N950 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N2,109","N2,709","N2,700","N2,797"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"For continuous compounding, FV = PV x e^(rt) = 950 x e^(0.135 x 8) = 950 x e^1.08 = 950 x 2.9447 = N2,797. Options B (N2,709) and C (N2,700) understate the growth, and A (N2,109) is far too low."}},{"itemId":"8f64c728-dceb-5bff-80ea-23b9d12c4795","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"75fa8311-5b0b-5e03-bd49-8b7133c55815","sourceKey":"bank:FIN101:FIN-0179","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N290,000 received in 5 years' times, if such fund yields 15% per annum?","options":["N583,294","N144,181","N144,153","N145,153"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"PV = 290,000 / (1.15)^5 = 290,000 / 2.0114 = N144,181. Option A (N583,294) is the future value, which compounds forward instead of discounting. Options C and D are close but do not match the correct discount factor."}},{"itemId":"ae72682f-ca83-573f-b7fb-3050cd7f4df3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0e372d19-325f-51f5-9483-8ca022bdac62","sourceKey":"bank:FIN101:FIN-0180","parentItemId":null,"revision":1,"payload":{"prompt":"N9,000 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N26,109","N26,509","N26,000","N26,502"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"For continuous compounding, FV = PV x e^(rt) = 9,000 x e^(0.135 x 8) = 9,000 x e^1.08 = 9,000 x 2.9447 = N26,502. Options A, B and C are close but do not match this result."}},{"itemId":"b8d041f2-4d21-54bc-9562-771ccd866271","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e48dec40-b49a-5893-be64-1667f27a16c2","sourceKey":"bank:FIN101:FIN-0183","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a finance function.","options":["Financial control","Financial forensics","Financial analysis","Financial planning"],"correctOption":1,"section":"Overview of Finance","explanation":"The finance function covers planning, raising, analysing and controlling a firm's funds, so financial control (A), financial analysis (C) and financial planning (D) are all finance functions. Financial forensics is the investigation of fraud and financial crime, which is a specialist audit and legal activity rather than a routine finance function."}},{"itemId":"eb59ccd4-2072-5e74-bf72-da8bc716ac4d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"319087d6-6c22-54b3-baf3-61eade50ce16","sourceKey":"bank:FIN101:FIN-0185","parentItemId":null,"revision":1,"payload":{"prompt":"The following are example of user of financial ratio analysis except","options":["Shareholders","Company management","Debtors","Creditors"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Users of ratio analysis are people with a stake in the firm's performance, such as shareholders (A), management (B) and creditors (D), who use ratios to judge returns, efficiency and ability to repay. Debtors are customers who owe the firm money, so they have no strong need to analyse its ratios."}},{"itemId":"bdc41d95-2861-55d2-9cc9-10ffb2b93acd","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b027f022-2a1a-5163-9bac-027ac7a29f10","sourceKey":"bank:FIN101:FIN-0186","parentItemId":null,"revision":1,"payload":{"prompt":"......... is a finance employee who manages the funds of an organization and undertakes financial management roles","options":["Financial manager","Financial analyst","Financial controller","Financial planner"],"correctOption":0,"section":"Overview of Finance","explanation":"A financial manager is responsible for managing an organisation's funds, making the investment, financing and dividend decisions. A financial analyst (B) studies and reports on financial data, and a financial planner (D) usually advises individuals. A financial controller (C) mainly oversees accounting and reporting rather than the whole finance function."}},{"itemId":"9a10f7f7-8ae7-5fc3-96b0-33d49a8f8c74","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2ac147c9-a452-5ebd-b8ae-da546c156c33","sourceKey":"bank:FIN101:FIN-0187","parentItemId":null,"revision":1,"payload":{"prompt":"......... is an example of money market instrument","options":["Preference share stock","Debenture stock","Bank deposit","Common stock"],"correctOption":2,"section":"Introduction to Financial Markets","explanation":"The money market deals in short-term funds, usually under a year, and bank deposits are a typical money market instrument. Preference shares (A), debenture stock (B) and common stock (D) are long-term securities traded in the capital market."}},{"itemId":"7e002181-4370-5910-9e88-f724ee077c8b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"16290492-f02e-5caf-876e-9bc7a0c9b5eb","sourceKey":"bank:FIN101:FIN-0190","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take an investment to triple itself if the interest rate is 15% per annum compounded annually?","options":["8 years","7 years","9 years","10 years"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Tripling means (1.15)^n = 3, so n = ln 3 / ln 1.15 = 1.0986 / 0.1398 = 7.86 years, which is 8 years to the nearest year. Seven years (B) is not enough, since (1.15)^7 = 2.66, and 9 or 10 years (C, D) are further from the exact figure."}},{"itemId":"9fff992e-ee8a-5471-b836-d14369ccdde1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3be22ad4-993c-5bfb-909f-d11a9264eaa2","sourceKey":"bank:FIN101:FIN-0191","parentItemId":null,"revision":1,"payload":{"prompt":"......... is an example of Capital market instrument","options":["Debenture stock","Banker acceptance","Bank deposit","Commercial paper"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"The capital market deals in long-term funds, and debenture stock is long-term debt, so it is a capital market instrument. Bankers' acceptances (B), bank deposits (C) and commercial paper (D) are short-term, so they belong to the money market."}},{"itemId":"e87d9a21-51c9-5df8-9685-01504f979494","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"288d9b34-7e30-56dc-bdef-ff9c1f08e89f","sourceKey":"bank:FIN101:FIN-0192","parentItemId":null,"revision":1,"payload":{"prompt":"Dividend decision is otherwise known as","options":["Capital mix decision","Capital rationing decision","Capital budgeting decision","Profit allocation decision"],"correctOption":3,"section":"Overview of Finance","explanation":"The dividend decision is about how much of the profit is paid out to shareholders and how much is retained in the business, so it is also called the profit allocation decision. The capital mix decision (A) is the financing decision, while capital budgeting (C) and capital rationing (B) belong to the investment decision."}},{"itemId":"acc7b609-f560-5f0a-94f1-0593903bc77e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b1d9fdbb-30bf-58d6-afb8-42fcef456523","sourceKey":"bank:FIN101:FIN-0193","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is not a reason why shareholders' wealth maximization objective is superior to the profit maximization objective.","options":["Wealth maximization provides a yardstick for overall firm performance, since it is reflected in the performance of the firm's shares on the stock market.","Shareholders' wealth maximization considers the inherent risk associated with an investment project while profit maximization does not","Wealth maximization does not consider the timing of returns while profit maximization considers.","Wealth maximization objective considers the long term prospects of the firm while profit maximization objective only consider the short-term objectives of the firm."],"correctOption":2,"section":"Objectives of a Business Firm","explanation":"Wealth maximisation is preferred precisely because it does consider the timing of returns through the time value of money, while profit maximisation ignores it, so option C states the reverse and is not a valid reason. Options A, B and D are genuine advantages: wealth maximisation gives a yardstick for overall performance through the share price, accounts for risk, and looks at the firm's long-term prospects."}},{"itemId":"4734744b-dc83-5e40-aa4f-74eb5f5f4c4f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"efda3b2c-cb29-59d2-a0a0-4e1665077308","sourceKey":"bank:FIN101:FIN-0194","parentItemId":null,"revision":1,"payload":{"prompt":"......... can be described as a complex of institutions, instruments, rules and regulations that facilitates the mobilization and transfer of resources from savings surplus to deficit economic units","options":["Savings market","Economic system","Financial system","Savings system"],"correctOption":2,"section":"Introduction to Financial Markets","explanation":"A financial system is the network of institutions, instruments, rules and regulations that moves funds from surplus (saving) units to deficit (borrowing) units. Options A and D describe only the saving side, and an economic system (B) is the wider way a whole economy is organised, not just its financial arrangements."}},{"itemId":"781b8e04-1beb-5ca2-8994-2e78d9c40524","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"921f9f05-3a01-5c0b-bdba-a9d666bd4246","sourceKey":"bank:FIN101:FIN-0197","parentItemId":null,"revision":1,"payload":{"prompt":"Equity security is also known as","options":["Preference share stock","Ordinary share stock","Convertible security","Debenture stock"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"Equity securities are ordinary shares, which give the holder ownership and a residual claim on the firm's profits and assets. Preference shares (A) and convertibles (C) are often treated as hybrids of debt and equity, and debenture stock (D) is pure debt."}},{"itemId":"1c7d5851-bc44-51f6-94fb-274315ec347f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9bc16938-787c-5efe-86a1-4f0c729e0000","sourceKey":"bank:FIN101:FIN-0198","parentItemId":null,"revision":1,"payload":{"prompt":"N7,000 is compounding continuously at 14.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N22,330","N22,309","N22,000","N21,329"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"For continuous compounding, FV = PV x e^(rt) = 7,000 x e^(0.145 x 8) = 7,000 x e^1.16 = 7,000 x 3.1899 = N22,330. Option B (N22,309) and D (N21,329) are close but do not match, and C (N22,000) is a rounded figure that does not match."}},{"itemId":"c7f9c6f1-0d45-5e79-81a5-a1e86988666f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"95ce7da8-8bdf-5d15-8bda-fa539a3785db","sourceKey":"bank:FIN101:FIN-0200","parentItemId":null,"revision":1,"payload":{"prompt":"What annual interest rate, compounded quarterly and to the nearest whole percent, will make N5,000 accumulate to N20,000 in 4 years?","options":["24%","36%","37%","9%"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Solve 5,000 x (1 + r/4)^16 = 20,000, so (1 + r/4)^16 = 4 and 1 + r/4 = 4^(1/16) = 1.0905. The quarterly rate is about 9.05%, so the annual rate compounded quarterly is 4 x 9.05% = 36.2%, which is 36% to the nearest whole percent. Option D (9%) is only the rate per quarter, and 24% (A) would only turn N5,000 into about N12,700."}},{"itemId":"9fe23b8f-2513-5da6-a408-09258e981689","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"85d3c0d5-e8ca-5773-ba69-da29f537d990","sourceKey":"bank:FIN101:FIN-0201","parentItemId":null,"revision":1,"payload":{"prompt":"......... Is the apex of money market regulatory agency.","options":["Central bank of Nigeria","Nigeria stock exchange","Issuing Houses","Securities and Exchange Commission"],"correctOption":0,"section":"Introduction to Financial Markets","explanation":"The Central Bank of Nigeria is the apex regulator of the money market and of banks. The Securities and Exchange Commission (D) is the apex regulator of the capital market, the Nigerian Stock Exchange (B) is a market operated for trading securities, and issuing houses (C) help companies raise capital."}},{"itemId":"d9cb7bae-f00a-53e0-8d33-4a4cd9b66719","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0afd89b4-796e-56ab-a398-f06afa683576","sourceKey":"bank:FIN101:FIN-0203","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N400,000 received in 5 years' time, if such fund yields 15% per annum?","options":["N198,153","N198,871","N193,149","N197,153"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"PV = 400,000 / (1.15)^5 = 400,000 / 2.0114 = N198,871. Options A, C and D are close in size but do not match the correct discount factor of 1 / 2.0114."}},{"itemId":"e603033a-33db-545f-846e-8c91247b5637","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a53ea100-f578-5c72-aea9-4e488f5ad35e","sourceKey":"bank:FIN101:FIN-0205","parentItemId":null,"revision":1,"payload":{"prompt":"The ideal minimum ratio for quick ratio is","options":["2.5:1","1:1","2:1","1.5:1"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The quick (acid-test) ratio excludes inventory, and the commonly accepted ideal is 1:1, meaning quick assets just cover current liabilities. Option D (1.5:1) and A (2.5:1) are higher than the accepted norm, and 2:1 (C) is the standard for the current ratio, not the quick ratio."}},{"itemId":"6a463057-97ba-5112-9bb9-461779d68cd9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"4b27571f-af93-53ff-b972-d4c4cc6bc842","sourceKey":"bank:FIN101:FIN-0206","parentItemId":null,"revision":1,"payload":{"prompt":"Investment decision is otherwise known as","options":["Capital project decision","Capital mix decision","Capital budgeting decision","Capital rationing decision"],"correctOption":2,"section":"Overview of Finance","explanation":"The investment decision is about choosing which long-term assets or projects to put money into, which is why it is called the capital budgeting decision. The capital mix decision (B) is the financing decision. Capital rationing (D) is only a special situation within investment, when funds are limited."}},{"itemId":"b2157e3d-564d-5f53-b6e8-5bbf72e10a87","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8c152569-b3a1-58e6-8a5a-d94ae6e39121","sourceKey":"bank:FIN101:FIN-0207","parentItemId":null,"revision":1,"payload":{"prompt":"The ideal minimum ratio for current ratio","options":["2.5:1","2:1","1.5:1","1:1"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The commonly accepted ideal current ratio is 2:1, meaning current assets are twice current liabilities, giving a comfortable safety margin. Option D (1:1) is the norm for the quick ratio, while 1.5:1 and 2.5:1 (C and A) are not the standard benchmarks."}},{"itemId":"805944c7-4ad4-52f9-ac61-4fe14a5fb69c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"075e1982-4f96-5045-b1e4-f83293dbd4fc","sourceKey":"bank:FIN101:FIN-0210","parentItemId":null,"revision":1,"payload":{"prompt":"A financial market instrument sold by blue-chip companies to meet short-term financial obligations and its backed only by an issuing bank or company promise to pay the face value on the maturity date specified on the instrument is called?","options":["Debenture","Corporate bond","Call money","Commercial paper"],"correctOption":3,"section":"Introduction to Financial Markets","explanation":"Commercial paper is a short-term, unsecured promissory note issued by large, creditworthy (blue-chip) companies and backed only by the issuer's promise to pay the face value at maturity. Debentures (A) and corporate bonds (B) are long-term debt, and call money (C) is very short-term lending between banks."}},{"itemId":"6f28c66b-a24f-531a-bb4f-04582449eab8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f96631d0-c3f3-5318-b635-3d1a24bfead6","sourceKey":"bank:FIN101:FIN-0211","parentItemId":null,"revision":1,"payload":{"prompt":"N770 is compounding continuously at 13.5% for 8 years. What is the value of the investment at the end of 8 years?","options":["N2,207","N2,109","N2,267","N2,200"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"For continuous compounding, FV = PV x e^(rt) = 770 x e^(0.135 x 8) = 770 x e^1.08 = 770 x 2.9447 = N2,267. Option B (N2,109) understates the growth, and A and D do not match the calculation."}},{"itemId":"ca2ba823-4011-5bd6-aece-d0aa8c3dd206","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b3cfdbfc-fe19-5f7d-91f8-6c143d136c9b","sourceKey":"bank:FIN101:FIN-0212","parentItemId":null,"revision":1,"payload":{"prompt":"If I invest N120,000 at the end of each year for 'n' years at 10% interest per annum to accumulate N1,000,000, find 'n'.","options":["6.36yrs","6.20yrs","6.0yrs","7yrs"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"This is the future value of an annuity: 120,000 x [(1.10)^n - 1] / 0.10 = 1,000,000. So (1.10)^n - 1 = 0.8333, giving (1.10)^n = 1.8333 and n = ln 1.8333 / ln 1.10 = 6.36 years. Seven years (D) would give more than N1,000,000, and 6.0 years (C) falls short."}},{"itemId":"8fe3be8e-9550-5c3c-8bad-a5eba9576ce1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"412389f4-892b-51a3-9665-09d441cc4667","sourceKey":"bank:FIN101:FIN-0213","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N250,000 received in 5 years' time, if such fund yields 15% per annum?","options":["N124,153","N124,253","N124,294","N153,149"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"PV = 250,000 / (1.15)^5 = 250,000 / 2.0114 = N124,294. Options A and B are close but do not match the discount factor, and D (N153,149) is far off."}},{"itemId":"02e20c50-569f-5502-a6c5-92df5cfaa2b4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"74b26787-0440-5f18-bab5-6bb00ac22700","sourceKey":"bank:FIN101:FIN-0216","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N260,000 received in 5 years' time, if such fund yields 15% per annum?","options":["N129,153","N153,149","N148,153","N129,266"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"PV = 260,000 / (1.15)^5 = 260,000 / 2.0114 = N129,266. Option A (N129,153) is close but does not match, and B and C are too high for a sum discounted at 15% over 5 years."}},{"itemId":"74195cf6-af02-54d3-87e7-cf70a1eadf9e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"f33af55c-f386-58aa-8f7b-9fca8255457c","sourceKey":"bank:FIN101:FIN-0218","parentItemId":null,"revision":1,"payload":{"prompt":"One of these require financial statement to advice clients","options":["Shareholder","Management","Analyst","Researcher"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Financial analysts study companies' financial statements so they can advise their clients on whether to invest. Shareholders (A) and management (B) use statements for their own decisions, not to advise clients, and a researcher (D) studies them for academic purposes."}},{"itemId":"bca34f7a-68b8-5fc0-93ab-83d66930c44f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"61ba222f-ce03-5b6f-ab8b-0c36008f556a","sourceKey":"bank:FIN101:FIN-0219","parentItemId":null,"revision":1,"payload":{"prompt":"State the relationship between EPS and P/E ratio","options":["Direct","Complementary","Inverse","Regular"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"The P/E ratio is market price per share divided by EPS, so for a given share price a higher EPS gives a lower P/E. That makes the relationship inverse. Option A (direct) would mean they rise together, which is not what the formula shows."}},{"itemId":"ddbaf1f8-ad4b-53d3-a4c6-ea148b83191d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e8488585-9ffb-518d-aea2-a536da508a3f","sourceKey":"bank:FIN101:FIN-0220","parentItemId":null,"revision":1,"payload":{"prompt":"This is a market value ratio","options":["Gross Profit Margin","Time interest earned","Earning yield","None"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Earnings yield (EPS divided by market price per share) uses the share's market price, so it is a market value ratio. Gross profit margin (A) is a profitability ratio, and times interest earned (B) is a leverage or coverage ratio, which is why D is also wrong."}},{"itemId":"669d7431-ea98-538a-b53e-0603001d3389","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"acfe5183-9075-5b8d-9476-6735ae4a304c","sourceKey":"bank:FIN101:FIN-0222","parentItemId":null,"revision":1,"payload":{"prompt":"One of these is not a fund raising source for a partnership business","options":["Issues of shares","Suppliers' credits","Equipment leasing","Hire purchase"],"correctOption":0,"section":"Forms of Business Firm","explanation":"A partnership cannot raise money by issuing shares, because only companies have share capital to offer. Suppliers' credit (B), equipment leasing (C) and hire purchase (D) are all available to partnerships as ways of financing the business."}},{"itemId":"1523b45e-2f71-58b3-9de2-6001a3c69d30","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"581aeec0-65ec-51a3-aa67-9d692fc2a6c5","sourceKey":"bank:FIN101:FIN-0223","parentItemId":null,"revision":1,"payload":{"prompt":"I have an annual receipt of N250,000 to make for 4-years, find the present worth of the period interest rate is 10%","options":["N792,456.36","N792,406.36","N792,466.36","N782,466.36"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"This is the present value of an ordinary annuity: PV = 250,000 x [1 - (1.10)^-4] / 0.10 = 250,000 x 3.1699 = N792,466.36. Options A and B differ only in small digits, and D (N782,466.36) is N10,000 too low."}},{"itemId":"4ea1ec5c-74e7-5e33-9f0f-a8e5fe5c356f","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e58be978-3e00-5ab2-8591-4d153e1f770d","sourceKey":"bank:FIN101:FIN-0224","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is not an economic objective of a business firm?","options":["Growth in sales","Improvement in market share","Profits and return on investment","Conservation of natural resources"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Conserving natural resources is part of a firm's social responsibility to its environment, not an economic objective. Sales growth (A), a bigger market share (B), and profits and return on investment (C) all measure the firm's commercial performance, which is what economic objectives are about."}},{"itemId":"5a74043d-6a11-5062-98b2-8ffadb0865d6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"59aa4733-dc13-5ac4-ace5-fdae5bf83f1b","sourceKey":"bank:FIN101:FIN-0225","parentItemId":null,"revision":1,"payload":{"prompt":"The ratio that shows the extent to which claims of short terms creditors are covered by assets that will be converted to within a year is called?","options":["Current ratio","Quick ratio","Debit ratio","Creditor ratio"],"correctOption":0,"section":"Financial Statement and Ratio Analysis","explanation":"The current ratio (current assets / current liabilities) shows how far short-term creditors' claims are covered by assets expected to become cash within a year. The quick ratio (B) is stricter, because it leaves out inventory. Options C and D are not standard liquidity ratios with this meaning."}},{"itemId":"55cf8afd-328a-5311-8948-3f799a8320c6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"11b4665c-3e74-56a4-8a48-2d3d5aee662d","sourceKey":"bank:FIN101:FIN-0226","parentItemId":null,"revision":1,"payload":{"prompt":"The major managerial function of a financial manager in a limited liability company are among others except","options":["Investment decision","Dividend decision","Financial decision","Acquisition decision."],"correctOption":3,"section":"Overview of Finance","explanation":"The three major finance decisions of a financial manager are the investment decision (A), the dividend decision (B) and the financing decision (C). An acquisition decision is a specific strategic choice, not one of the three core finance functions."}},{"itemId":"caa9c8a8-7033-59bd-a41b-5f83e06207df","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8d6d3621-76a0-5486-96c7-0d63a75629fc","sourceKey":"bank:FIN101:FIN-0228","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is most appropriate as an Objective of a business organization?","options":["To achieve long term growth in earnings","To maximize shareholder wealth","To make efficient use of resources","To minimize input costs"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Maximising shareholder wealth is the most appropriate overall objective because it takes account of risk, the timing of returns and long-term value. Long-term earnings growth (A) is also partly true, but it ignores risk, and efficient use of resources (C) and cost minimisation (D) are ways of reaching the main goal rather than the goal itself."}},{"itemId":"30cf4068-d2c9-564e-996d-4b2fba71f59c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9de9959a-32a6-5d60-8a5e-5d5d0f70570a","sourceKey":"bank:FIN101:FIN-0229","parentItemId":null,"revision":1,"payload":{"prompt":"Shareholder wealth\" in a firm is represented by:","options":["the number of people employed in the firm","the book value of the firm's assets less the book value of its liabilities","the amount of salary paid to its employees.","the market price per share of the firm's common stock."],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Shareholder wealth is reflected in the market price of the firm's shares, because the share price captures expected future returns, their timing and their risk. Book value (B) is based on historical accounting figures, not market value. The number of employees (A) and salaries paid (C) have nothing to do with owners' wealth."}},{"itemId":"3ed7b06b-ca38-5746-991b-a89fc02442b2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b3053fa9-236c-5ecb-856a-ed8a900aa941","sourceKey":"bank:FIN101:FIN-0230","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following reasons is not why wealth maximization is better than profit maximization as an objective of a business firm?","options":["Explicit consideration of risks in investments","Recognition of the prospects of a firms in the short-run","Recognition of the perception of shareholders. about the returns realizable from investment","Consideration of time value of money concept"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Wealth maximisation is better because it focuses on the firm's long-term prospects, not the short run, so option B is not a valid reason. Options A, C and D are genuine reasons: wealth maximisation considers risk, shareholders' view of expected returns through the share price, and the time value of money."}},{"itemId":"302801a7-63f3-5084-9608-05f80d1d894d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"9d81507b-e521-5a18-9116-900f311d94e8","sourceKey":"bank:FIN101:FIN-0234","parentItemId":null,"revision":1,"payload":{"prompt":"At the end of each year for the next ten years. You will receive cash flows of N50. If the appropriate discount rate is 5.5 percent, how much would you pay for this annuity?","options":["N259.82","N299.02","N338.99","N376.88"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"The price of the annuity is its present value: PV = 50 x [1 - (1.055)^-10] / 0.055 = 50 x 7.5376 = N376.88. Options A, B and C are all too low, since ten payments of N50 total N500 and discounting at 5.5% should not cut that by as much as they suggest."}},{"itemId":"4ab4c028-9f24-5b90-b9f8-68bfe10c6e66","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"109c0b31-cff7-51bc-af57-08d4de16fa60","sourceKey":"bank:FIN101:FIN-0235","parentItemId":null,"revision":1,"payload":{"prompt":"Assuming N100,000 is paid in a fixed deposit account with a bank that offers the depositor 24% Interest per annum payable once in a quarter. Calculate the compounding value of the Investment if it made for 2years","options":["N160,470.64","N159,384.81","N190,662.40","N201.219.65"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"With quarterly compounding, the rate per quarter is 24% / 4 = 6% for 2 x 4 = 8 quarters. FV = 100,000 x (1.06)^8 = 100,000 x 1.5938 = N159,384.81. Option C (N190,662.40) and D are too high, and A (N160,470.64) does not match this calculation."}},{"itemId":"1f14c8cd-3121-5566-bc80-3ea6fbe79049","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d746a9ca-cdc7-5b7f-9eb8-aa6014f12c6c","sourceKey":"bank:FIN101:FIN-0236","parentItemId":null,"revision":1,"payload":{"prompt":"A project has a cost o N53,500 and its expected net cash inflows are N11,500 per annum for 6 years. If the cost of capital is 5%, The project's Net Present Value (NPV) is","options":["N78,221.46","N81,087.46","N58,370.46","N4,870.46"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"NPV = PV of inflows - cost. PV of inflows = 11,500 x [1 - (1.05)^-6] / 0.05 = 11,500 x 5.0757 = N58,370.46, so NPV = 58,370.46 - 53,500 = N4,870.46. Option C (N58,370.46) is only the present value of the inflows before subtracting the cost, and A and B are wrong totals."}},{"itemId":"58156d50-03ff-508e-818d-1320b2600739","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"80b3d80b-9f23-5b33-acf8-24d8d5ae22a2","sourceKey":"bank:FIN101:FIN-0237","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The expected value of the project is","options":["N15,000","N18,000","N28,000","N61,000"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected value = sum of each cash flow x its probability: 50,000(0.3) + 60,000(0.3) + 70,000(0.4) = 15,000 + 18,000 + 28,000 = N61,000. Options A, B and C are just the separate parts of this sum, not the full expected value."}},{"itemId":"96dd11df-85ba-5b3c-b228-688d373da10b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"846e40a1-fb80-58f3-b396-da1b1d840c89","sourceKey":"bank:FIN101:FIN-0238","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The variance of the project is","options":["N36,300,000","N300,000","N32,400,000","N69,000,000"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"With expected value N61,000, variance = 0.3(50,000-61,000)^2 + 0.3(60,000-61,000)^2 + 0.4(70,000-61,000)^2 = 36,300,000 + 300,000 + 32,400,000 = 69,000,000. Options A, B and C are only the individual terms of this sum, not the total variance."}},{"itemId":"3e22e300-9ceb-5d0e-a9c4-ec83a0a72137","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fd561fa4-1c2b-5693-941d-52afb54a2515","sourceKey":"bank:FIN101:FIN-0239","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project is given as follow N50,000(0.3), N60,000(0.3) and N70,000(0.4). The standard deviation of the project is","options":["N7,810.25","N8,306.62","N69,000,000","N57,000"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Standard deviation is the square root of the variance. Variance = 69,000,000, so SD = square root of 69,000,000 = N8,306.62. Option C (69,000,000) is the variance itself, not its square root, and A and D do not match the calculation."}},{"itemId":"f8ba0c71-5b89-5f91-8560-05f293c78534","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7062a163-7720-5906-8572-c1df835c795d","sourceKey":"bank:FIN101:FIN-0240","parentItemId":null,"revision":1,"payload":{"prompt":"The cash flow and probability for a project are given as follows: N50,000 (0.3), N60,000 (0.3) and N70,000 (0.4). The coefficient of variation of the project, to the nearest whole percent, is","options":["14%","34%","24%","13%"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected cash flow = 0.3(50,000) + 0.3(60,000) + 0.4(70,000) = N61,000, and the standard deviation is the square root of 69,000,000 = N8,306.62. Coefficient of variation = 8,306.62 / 61,000 = 13.6%, which is 14% to the nearest whole percent. Option D (13%) truncates the figure instead of rounding it, and B and C are far too high."}},{"itemId":"52fb28a2-fb34-591c-b22b-28644fd86463","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"226bd923-0082-5de7-9193-0c659cf55b25","sourceKey":"bank:FIN101:FIN-0242","parentItemId":null,"revision":1,"payload":{"prompt":"The two major types of annuity are......... and.........","options":["ordinary annuity, annuity due","Regular , irregular annuity","Perpetual, deferred annuity","All of the above"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"The two main types of annuity are the ordinary annuity, where payments come at the end of each period, and the annuity due, where payments come at the start. Perpetuities and deferred annuities (C) are special cases, and B is not a standard classification, so D is also wrong."}},{"itemId":"21ecf831-99ae-5bba-a821-f869a2f9b824","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"7588d116-4d3c-5519-8c36-1d5fb2943900","sourceKey":"bank:FIN101:FIN-0301","parentItemId":null,"revision":1,"payload":{"prompt":"The arithmetic process of determining the final value of a payment or a series of payments when interest is known is called ------","options":["Time value of money","Compounding","Simple interest","Banker's interest"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Compounding is the process of moving a present amount forward in time by adding interest on both the principal and the interest already earned, which gives its final (future) value. Time value of money (A) is the broad idea that money today is worth more than money later, not the arithmetic process itself. Simple interest (C) and banker's interest (D) are particular ways of charging interest, not the name of the process."}},{"itemId":"f4268a40-7c34-5223-8325-bd6ed8fae5f4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"123ff98a-1369-5db9-9b5a-b313de7c5832","sourceKey":"bank:FIN101:FIN-0304","parentItemId":null,"revision":1,"payload":{"prompt":"How much will an investor have after 5 years if he invests N20,000 at 10% simple interest per annum?","options":["N25,000","N30,000","N100,000","N200,000"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Simple interest is P x R x T = 20,000 x 0.10 x 5 = N10,000, so the investor will have 20,000 + 10,000 = N30,000. Option A adds only 2.5 years of interest. Options C and D come from multiplying the principal by 5 or by 10 instead of applying the rate."}},{"itemId":"f57c77e5-649b-575a-b49b-7b0a97d45dfe","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"46479a2f-9dc3-539a-a505-77e89fc6d501","sourceKey":"bank:FIN101:FIN-0306","parentItemId":null,"revision":1,"payload":{"prompt":"One of the following is NOT a major source of short-term finance.","options":["Factoring","Bill finance","Leasing","Trade credit"],"correctOption":2,"section":"Overview of Finance","explanation":"Leasing is a medium- to long-term source of finance, because it lets a firm use an asset such as a vehicle or machine over several years without buying it. Factoring (A), bill finance (B) and trade credit (D) all provide funds for a few months at most, so they are short-term sources."}},{"itemId":"5f7f2450-dc88-5fac-bbff-1cc750f170b7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6d8b8815-3380-50e7-b973-a6d8aa77fe0a","sourceKey":"bank:FIN101:FIN-0307","parentItemId":null,"revision":1,"payload":{"prompt":"At what annual rate of compound interest will N2,000 grow to N2,721 after 4 years?","options":["5%","6%","9%","8%"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"Solve 2,000(1 + r)^4 = 2,721: (1 + r)^4 = 1.3605, so 1 + r = 1.3605^(1/4) = 1.08, giving r = 8%. Check: 2,000 x 1.08^4 = N2,720.98. At 6% (B) the amount would be only about N2,525, and at 9% (C) about N2,823."}},{"itemId":"82e13538-6bd2-58da-a836-ba3fac6ba4f2","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"25cc79f7-770d-5ddc-9d4e-bef35eda8911","sourceKey":"bank:FIN101:FIN-0308","parentItemId":null,"revision":1,"payload":{"prompt":"What amount should be invested now at 20% simple interest per annum to accumulate N184,000 in 3 years?","options":["N52,500","N306.66","N115,000","N305.50"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"With simple interest, A = P(1 + RT), so 184,000 = P(1 + 0.20 x 3) = 1.6P, giving P = 184,000 / 1.6 = N115,000. Check: interest is 115,000 x 0.2 x 3 = N69,000, and 115,000 + 69,000 = N184,000. Options A, B and D do not satisfy this equation."}},{"itemId":"9a810727-598b-5aa1-8a74-55969656174b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"b3c43e1f-2117-5b7d-b70e-86a39d157421","sourceKey":"bank:FIN101:FIN-0310","parentItemId":null,"revision":1,"payload":{"prompt":"The raising of capital funds and using them to generate returns, and paying returns to the suppliers of funds, are known as ------ functions of the firm.","options":["Marketing","Accounting","Finance","Production"],"correctOption":2,"section":"Overview of Finance","explanation":"The finance function covers obtaining funds, investing them to earn returns, and rewarding those who supplied the funds through interest and dividends. Marketing (A) deals with selling the firm's products, accounting (B) with recording and reporting transactions, and production (D) with turning inputs into goods."}},{"itemId":"e0633af9-8a72-5f54-ae6f-df3e5f500c85","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"79a3d460-4fb1-5b34-b5d6-1a24325d9886","sourceKey":"bank:FIN101:FIN-0321","parentItemId":null,"revision":1,"payload":{"prompt":"Princess received an endowment of N5.0 million and decided to deposit it in a bank that pays an interest rate of 15% compounded quarterly. In how many years will she be able to accumulate N6.0 million to enable her to implement her desired project?","options":["4.95 yrs","1.24 yrs","1.20 yrs","1.08 yrs"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"The quarterly rate is 15%/4 = 3.75%, so 5(1.0375)^(4n) = 6, giving 4n = log 1.2 / log 1.0375 = 4.95 quarters and n = 4.95 / 4 = 1.24 years. Option A is the number of quarters, not years. Options C and D are too short; after 1.20 years the deposit would be below N6 million."}},{"itemId":"56c1b6b8-5415-5819-b796-5a11b32e206d","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"bb76e6de-722f-57ba-b477-f61599d87207","sourceKey":"bank:FIN101:FIN-0322","parentItemId":null,"revision":1,"payload":{"prompt":"Kenny is entitled to a cash payment of N10 million in 5 years. If the opportunity interest rate is 10% payable semi-annually, what is the minimum amount he would be comfortable with if he is to receive the entitlement today?","options":["N6.21m","N6.86m","N6.14m","N3.86m"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"With semi-annual compounding there are 10 periods at 5% each, so PV = 10m / 1.05^10 = 10m / 1.6289 = N6.14m. Option A (N6.21m) uses annual compounding at 10%, which ignores the twice-yearly interest. Option D (N3.86m) is the interest portion, 10m - 6.14m, not the present value."}},{"itemId":"491fd7a5-2a50-5bc1-b284-9ea47a9815a5","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"6a2bd286-3cf0-5c8a-8653-e5e3feaa96f8","sourceKey":"bank:FIN101:FIN-0323","parentItemId":null,"revision":1,"payload":{"prompt":"Precious plans to retire in two years, after which she will be entitled to an annual payment of N100,000 for the next 10 years, the first payment coming one year after she retires. If her normal interest rate is 10%, what is the equivalent value today of the payments?","options":["N614,456","N507,815","N492,185","N641,456"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"This is a deferred annuity. At retirement (year 2) the 10 payments are worth 100,000 x [1 - 1.1^-10] / 0.1 = N614,457; discounting that back 2 years gives 614,457 / 1.21 = N507,815. Option A stops at the value on the retirement date and forgets to discount the last two years. Options C and D do not match the calculation."}},{"itemId":"6ff18e79-5194-5d34-a7fd-5772fd3ac9e4","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"554a1f86-a492-5c55-8440-71176d331ef5","sourceKey":"bank:FIN101:FIN-0324","parentItemId":null,"revision":1,"payload":{"prompt":"Unilag Ventures borrowed N100,000 at an interest rate of 10% per annum with a maturity of 3 years, amortized annually in equal instalments. How much is the principal outstanding at the end of the second year?","options":["N33,232.63","N40,211.48","N63,444.89","N36,555.89"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"The equal instalment is 100,000 x 0.1 / (1 - 1.1^-3) = N40,211.48. After year 1 the balance is 110,000 - 40,211.48 = N69,788.52; after year 2 it is 69,788.52 x 1.1 - 40,211.48 = N36,555.89, which the final instalment exactly clears. Option B is the instalment itself, not the balance."}},{"itemId":"1adf3c86-51b4-52e3-af9d-b70c9f073a61","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"2e636a38-27f8-55c4-8c50-5e41629d2afa","sourceKey":"bank:FIN101:FIN-0325","parentItemId":null,"revision":1,"payload":{"prompt":"The Department of Finance desires to accumulate N100,000 in 3 years by making equal deposits at the end of each year into a special fund, which it plans to use to acquire a set of learning aids. How much would be in the fund at the end of 2 years if the interest rate is 10% per annum?","options":["N63,444.11","N36,555.89","N30,211.48","N69,788.52"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"The yearly deposit is 100,000 x 0.1 / (1.1^3 - 1) = N30,211.48. By the end of year 2 the first deposit has grown to 30,211.48 x 1.1 and the second has just been made, so the fund holds 30,211.48 x 2.1 = N63,444.11. Option C is a single deposit, and option B is what is still missing from the N100,000 target."}},{"itemId":"e30ed8bf-e347-510b-a077-1d4630c0ff23","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a01af4c6-4083-5710-94d9-b63c0162d678","sourceKey":"bank:FIN101:FIN-0326","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take for an amount to quadruple itself if the interest rate is 12% compounded annually?","options":["13.5 yrs","11.2 yrs","12.23 yrs","None of the above"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"Quadrupling means (1.12)^n = 4, so n = log 4 / log 1.12 = 0.6021 / 0.0492 = 12.23 years. Option B (11.2) is too short; 1.12^11.2 is only about 3.56. Since C matches the calculation exactly, D is wrong."}},{"itemId":"fd444a6d-77da-508c-b428-2416bc7fc3c1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"750a4a55-2923-5af6-b891-bd9ffc215b3a","sourceKey":"bank:FIN101:FIN-0327","parentItemId":null,"revision":1,"payload":{"prompt":"At what interest rate, compounded annually, will an investment of N150,000 yield N500,000 in 5 years?","options":["26.30%","27.10%","28.0%","27.23%"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"Solve 150,000(1 + r)^5 = 500,000: (1 + r)^5 = 3.3333, so 1 + r = 3.3333^(1/5) = 1.2723 and r = 27.23%. The nearby options are close distractors: at 27.10% (B) the investment would reach only about N497,500, and at 28% (C) it would overshoot to about N515,400."}},{"itemId":"a32a43cf-40d2-5b9d-a7c5-6033aa6612a1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"91798422-5452-5a28-a7cf-5e4842500c6e","sourceKey":"bank:FIN101:FIN-0329","parentItemId":null,"revision":1,"payload":{"prompt":"Chike will invest an annual sum of N200,000 at the end of each year for 5 years. If the interest rate is 20% per annum, find how much will be realized at the end of the period.","options":["N1,888,320","N1,488,320","N1,428,320","N1,488,120"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"This is the future value of an ordinary annuity: 200,000 x [(1.2^5 - 1) / 0.2] = 200,000 x 7.4416 = N1,488,320. Option D differs only in the hundreds, and options A and C do not match the annuity factor of 7.4416. Option B is also the right figure before the extra year of interest that an annuity due would add."}},{"itemId":"7d54f1a4-98ae-513b-b235-0d2a1d5f1dae","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d52c0fa7-f2a2-5d9b-a164-d2b28d09a30b","sourceKey":"bank:FIN101:FIN-0330","parentItemId":null,"revision":1,"payload":{"prompt":"If Chibuzor will invest an annuity of N200,000 for 5 years at an interest rate of 20% per annum, find how much he will realize at the end of the period, assuming the first instalment is made now.","options":["N1,785,984","N1,783,984","N1,782,984","N1,781,984"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Paying at the start of each year makes this an annuity due, so each payment earns one extra year of interest: 1,488,320 x 1.2 = N1,785,984. The other options differ from this by a few thousand naira and do not match the calculation."}},{"itemId":"89cd8c9b-699d-5146-ac27-74188802192a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"244f68d5-0bfd-5d12-93e6-f6b797f19dac","sourceKey":"bank:FIN101:FIN-0332","parentItemId":null,"revision":1,"payload":{"prompt":"From the following figures: Stock N5,000; Trade creditors N2,000; Debtors N3,000; Bank overdraft N1,600; Bank N1,500; Accrued expenses N400; Cash N500. Calculate the current ratio.","options":["1:1","2:1","2.5:1","1.5:1"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Current assets are stock + debtors + bank + cash = 5,000 + 3,000 + 1,500 + 500 = N10,000. Current liabilities are trade creditors + bank overdraft + accrued expenses = 2,000 + 1,600 + 400 = N4,000. The current ratio is 10,000 : 4,000 = 2.5:1. Option B (2:1) is the textbook ideal, not this firm's figure."}},{"itemId":"a95f56b7-db8c-5a9e-8062-5a255a7edc99","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"0a47c4e5-2238-56e5-97e4-8ac1c0145054","sourceKey":"bank:FIN101:FIN-0333","parentItemId":null,"revision":1,"payload":{"prompt":"From the following figures: Stock N5,000; Trade creditors N2,000; Debtors N3,000; Bank overdraft N1,600; Bank N1,500; Accrued expenses N400; Cash N500. Calculate the quick (acid-test) ratio.","options":["0.75:1","1:1","1.5:1","1.25:1"],"correctOption":3,"section":"Financial Statement and Ratio Analysis","explanation":"The quick ratio leaves out stock because it is the least liquid current asset: (10,000 - 5,000) / 4,000 = 5,000 / 4,000 = 1.25:1. Option B (1:1) is the usual ideal benchmark, not this firm's ratio. Option A (0.75:1) and option C (1.5:1) do not match liquid assets divided by current liabilities."}},{"itemId":"8446fae9-ab75-58a6-9f2c-bceb04b15e73","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"8377691d-8b1a-5d15-bcf7-5cb688643ac5","sourceKey":"bank:FIN101:FIN-0334","parentItemId":null,"revision":1,"payload":{"prompt":"Given that Inventories are N3,100; Accounts receivable N8,000; Accounts payable N4,000; Cash and cash equivalents N6,260; and Taxation N2,250, calculate the current ratio.","options":["1.78:1","2.78:1","3.78:1","4.78:1"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"Current assets are 3,100 + 8,000 + 6,260 = N17,360. Current liabilities, accounts payable plus taxation, are 4,000 + 2,250 = N6,250. The current ratio is 17,360 / 6,250 = 2.78:1. Taxation must be included in current liabilities because tax payable is due within the year; leaving it out would give 17,360 / 4,000 = 4.34, which is not an option."}},{"itemId":"8f197b4b-5a50-5687-a8a2-909734c5856b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"c9ed44a9-7f95-5f0e-a437-b6d79d909d48","sourceKey":"bank:FIN101:FIN-0335","parentItemId":null,"revision":1,"payload":{"prompt":"Given that Inventories are N3,100; Accounts receivable N8,000; Accounts payable N4,000; Cash and cash equivalents N6,260; and Taxation N2,250, calculate the quick ratio.","options":["1.28:1","2.28:1","3.28:1","4.28:1"],"correctOption":1,"section":"Financial Statement and Ratio Analysis","explanation":"The quick ratio excludes inventories: (17,360 - 3,100) / 6,250 = 14,260 / 6,250 = 2.28:1. Option A (1.28) is one whole unit too low, and options C and D are too high. Only B matches liquid assets divided by current liabilities."}},{"itemId":"69ab35d3-31f9-5adb-aee9-44d2a9693152","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"aee362a8-37dc-5de6-a083-79989477a98d","sourceKey":"bank:FIN101:FIN-0339","parentItemId":null,"revision":1,"payload":{"prompt":"Short-term solvency ratio is also known as ------","options":["Stock market ratio","Efficiency ratio","Liquidity ratio","Stability ratio"],"correctOption":2,"section":"Financial Statement and Ratio Analysis","explanation":"Short-term solvency ratios, such as the current ratio and quick ratio, measure a firm's ability to meet obligations falling due within a year, which is what liquidity means. Stability ratio (D) is the other name for long-term solvency ratios. Efficiency ratios (B) measure how well assets are used, and stock market ratios (A) relate to share prices."}},{"itemId":"475cc76e-7a14-5a7d-8040-2a11240436b6","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"af4c004e-305b-5a2e-b999-ea21ff396f8b","sourceKey":"bank:FIN101:FIN-0341","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the apex regulatory agency in the Nigerian capital market.","options":["NDIC","SEC","NICOM","CBN"],"correctOption":1,"section":"Introduction to Financial Markets","explanation":"The Securities and Exchange Commission (SEC) is the apex regulator of the Nigerian capital market, overseeing securities issues, the exchanges and market operators. The CBN (D) is the apex regulator of the money market and banking system. NDIC (A) insures bank deposits, and NICOM (C) is not the capital market regulator."}},{"itemId":"68c2ebba-b085-527a-a84d-45727bbcec99","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fe92faa0-d2ac-5b6e-936d-53ef6c3a3a60","sourceKey":"bank:FIN101:FIN-0342","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.5), N60,000 (0.3) and N70,000 (0.2). To the nearest whole percent, the coefficient of variation of the security is","options":["20%","13%","14%","16%"],"correctOption":2,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected return = 0.5(50,000) + 0.3(60,000) + 0.2(70,000) = N57,000. Variance = 0.5(7,000)^2 + 0.3(3,000)^2 + 0.2(13,000)^2 = 61,000,000, so the standard deviation is N7,810.25. CV = 7,810.25 / 57,000 = 13.7%, which rounds to 14%. Option B (13%) truncates instead of rounding."}},{"itemId":"8aa12ec8-fae6-5c34-92a8-823ee4d6458a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"fb6b3881-70dc-50fc-a066-0898a6ca2310","sourceKey":"bank:FIN101:FIN-0344","parentItemId":null,"revision":1,"payload":{"prompt":"One of the characteristics of finance is that ------","options":["It hinders business growth","It serves as a standard upon which business can be measured","It distorts the expansion of business","It does not link the other activities of a business together"],"correctOption":1,"section":"Overview of Finance","explanation":"Finance provides a common money measure for every part of a business, so performance, costs and growth can all be judged in financial terms. Options A and C describe the opposite of what finance does, since funds make growth and expansion possible. Option D is also false, because finance links production, marketing and other activities through budgets and funds."}},{"itemId":"bafbd03c-3939-5cc3-afa7-32a234233609","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"905711b2-178e-563d-bad0-f38cf63764d1","sourceKey":"bank:FIN101:FIN-0346","parentItemId":null,"revision":1,"payload":{"prompt":"------ objective enhances a good business environment.","options":["Survival","Social responsibility","Profit maximization","Increase in market share"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"The social responsibility objective commits the firm to caring for its community, employees, customers and the environment, which builds goodwill and a healthier environment for business. Survival (A) is about staying in operation, profit maximization (C) focuses on the firm's own earnings, and increase in market share (D) is about beating competitors."}},{"itemId":"348ccbb9-b3df-5a4a-bad5-ddcdc0a2a5b7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"d94381d1-d124-5d64-b518-8b91e30cf913","sourceKey":"bank:FIN101:FIN-0347","parentItemId":null,"revision":1,"payload":{"prompt":"Which firm objective has been attacked by all and sundry?","options":["Increase in market share","Survival","Social responsibility","Profit maximization"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Profit maximization is the most widely criticised objective. It ignores the timing of returns and risk, the term 'profit' is vague, and pursuing it can lead firms to neglect workers, customers and society. Survival (B) and social responsibility (C) are generally seen as reasonable goals, and market share (A) has not drawn the same broad criticism."}},{"itemId":"70294369-d130-529d-ab39-b161bf69d495","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"96680163-da8a-5967-9b5b-ad6a650d1c26","sourceKey":"bank:FIN101:FIN-0348","parentItemId":null,"revision":1,"payload":{"prompt":"------ objective has been widely accepted as the best means of maximizing the economic welfare of the shareholders of a firm.","options":["Increase in market share","Survival","Social responsibility","Shareholders' wealth maximization"],"correctOption":3,"section":"Objectives of a Business Firm","explanation":"Shareholders' wealth maximization aims to raise the market value of the owners' shares, taking account of the timing and risk of returns, so it is accepted as the best measure of shareholders' economic welfare. Market share (A), survival (B) and social responsibility (C) may support the firm, but none of them directly measures what owners gain."}},{"itemId":"0f277ce9-70de-5dde-a7e8-de470be7dab0","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"efff3988-d198-5162-af30-86f5dac195f1","sourceKey":"bank:FIN101:FIN-0349","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of the firm that has to do with giving all stakeholders satisfactory returns for their inputs is ------","options":["Increase in market share","Satisfaction","Survival","Social responsibility"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"The satisfaction (satisficing) objective means the firm aims for results that are good enough to satisfy every stakeholder group: owners, workers, lenders and suppliers. It does not maximize for one group. Social responsibility (D) focuses on society and the environment rather than rewarding each contributor's input, and survival (C) is only about staying in business."}},{"itemId":"a0bc00b9-62d0-5171-be98-027149982fb1","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"5adfebec-cd30-5670-a338-eb6c77ff8a7b","sourceKey":"bank:FIN101:FIN-0350","parentItemId":null,"revision":1,"payload":{"prompt":"The objective of capturing more of the market demand for their product in an industry is known as ------","options":["Shareholders' wealth maximization","Increase in market share","Survival","Social responsibility"],"correctOption":1,"section":"Objectives of a Business Firm","explanation":"Market share is the portion of total industry demand that a firm captures, so aiming to capture more of it is the increase-in-market-share objective. Shareholders' wealth maximization (A) concerns share value, survival (C) is about continuing to exist, and social responsibility (D) concerns society."}},{"itemId":"aa2e6243-3812-5e18-b139-ae06b673efb3","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"38275725-951c-5eb4-bf39-061fd3cdbfce","sourceKey":"bank:FIN101:FIN-0351","parentItemId":null,"revision":1,"payload":{"prompt":"How long, to the nearest year, will it take N35,000 deposited into an account to accumulate to N450,000 at a 25% annual compound interest rate?","options":["11 years","12 years","13 years","10 years"],"correctOption":0,"section":"Foundation of Financial Mathematics","explanation":"Solve 35,000(1.25)^n = 450,000: 1.25^n = 12.857, so n = log 12.857 / log 1.25 = 1.1091 / 0.0969 = 11.45 years, which is 11 years to the nearest year. Option B (12) would be the first whole year in which the target is passed, but the question asks for the nearest year. Option D (10) is too short."}},{"itemId":"a19a68fa-dffb-5dcc-b204-77c5e4933f45","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1c14e4f9-5aae-51c5-ba86-0f41d9e35642","sourceKey":"bank:FIN101:FIN-0355","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N300,000 received in 5 years' time if such funds yield 15% per annum?","options":["N149,000","N603.41","N149,153.02","N603,407.17"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"PV = 300,000 / 1.15^5 = 300,000 / 2.011357 = N149,153.02. Option A is a rounded figure that does not match the discount factor. Option D (N603,407.17) is the future value, 300,000 x 1.15^5, rather than the present value."}},{"itemId":"97f15b9a-a3a1-5c9a-b93f-89d4322412af","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"54f1643c-f78d-5210-9c81-22f28013c76d","sourceKey":"bank:FIN101:FIN-0356","parentItemId":null,"revision":1,"payload":{"prompt":"Assuming N100,000 is put in a fixed deposit account with a bank that offers the depositor 24% interest per annum payable twice in a quarter (eight times a year), calculate the compounded value of the investment if it is made for 4 years.","options":["N160,470.64","N160,470.46","N160,469","N257,508.28"],"correctOption":3,"section":"Foundation of Financial Mathematics","explanation":"Twice a quarter means 8 compounding periods a year, so each period earns 24%/8 = 3% and there are 4 x 8 = 32 periods. The value is 100,000 x 1.03^32 = N257,508.28. Options A, B and C, about N160,470, come from 1.03^16, which counts only 16 periods (two years)."}},{"itemId":"9044b05d-d0d5-53f5-9d03-78dab76ca02a","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a589d25b-cb74-5df8-aa05-65cd2d634b0a","sourceKey":"bank:FIN101:FIN-0358","parentItemId":null,"revision":1,"payload":{"prompt":"FLAKKY has just secured a job with CHEVROME Oil Plc on a 3-year contract with a monthly salary of N800,000, paid at the end of each month, and an annual bonus of N2.5 million, paid at the end of each year. What is the present value of FLAKKY's job contract if the discount rate is 15% per annum (1.25% per month for the salary)?","options":["N23,077,813.90","N5,708,062.79","N28,785,876.69","None of the above"],"correctOption":2,"section":"Foundation of Financial Mathematics","explanation":"Salary PV = 800,000 x [1 - 1.0125^-36] / 0.0125 = N23,077,813.90, and bonus PV = 2,500,000 x [1 - 1.15^-3] / 0.15 = N5,708,062.79. The contract is worth the sum, N28,785,876.69. Options A and B are each only one part of the contract."}},{"itemId":"73d2a3bd-17c8-5fd3-94a1-08f2c0e5d9af","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e283e14a-7730-5c81-ab5f-82b3b3ae8c41","sourceKey":"bank:FIN101:FIN-0360","parentItemId":null,"revision":1,"payload":{"prompt":"Blessing has just been promised a lump sum payment of N2,000,000 in the future if she agrees to deposit N50,000 at the beginning of every year starting from now. How many years will it take Blessing to earn the lump sum if any deposit she makes attracts interest at the rate of 21% per annum?","options":["10 yrs","11 yrs","12 yrs","13 yrs"],"correctOption":1,"section":"Foundation of Financial Mathematics","explanation":"Deposits at the start of each year form an annuity due: 50,000 x 1.21 x [(1.21^n - 1) / 0.21] = 2,000,000, so 1.21^n = 7.942 and n = log 7.942 / log 1.21 = 10.87, which means 11 years. After 10 years (A) the fund is only about N1.65 million, short of the target, while 12 or 13 years (C, D) are more than needed."}},{"itemId":"f9b411da-46f4-5afd-a6d7-5e9c40e35044","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a1a3e8b8-acf0-5fbe-bd15-d1bb79c43294","sourceKey":"bank:FIN101:FIN-0361","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The expected return of the security is","options":["N56,000","N66,000","N68,000","N61,000"],"correctOption":1,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected return is the probability-weighted average: 0.1(50,000) + 0.2(60,000) + 0.7(70,000) = 5,000 + 12,000 + 49,000 = N66,000. Option D (N61,000) is the expected value when the probabilities are 0.3, 0.3 and 0.4."}},{"itemId":"b10a62a1-d90f-5a22-b295-eb1b81b144a8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"1f824782-597a-5efd-9bd2-4001f7699620","sourceKey":"bank:FIN101:FIN-0362","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The variance of the security is","options":["N44,000,000","N44,300,000","N6,633.25","N69,000,000"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"With an expected return of N66,000, the variance is 0.1(-16,000)^2 + 0.2(-6,000)^2 + 0.7(4,000)^2 = 25,600,000 + 7,200,000 + 11,200,000 = 44,000,000. Option C (N6,633.25) is the standard deviation, the square root of the variance. Option B is a near-miss figure."}},{"itemId":"636c9017-b8ea-5098-9f42-c46fc1573ffb","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a4686f4d-254b-5f64-806a-e7cd2dc00119","sourceKey":"bank:FIN101:FIN-0363","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). The standard deviation of the security is","options":["N6,633.25","N8,306.62","N44,000,000","N44,000"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"The standard deviation is the square root of the variance: square root of 44,000,000 = N6,633.25. Option C is the variance itself. Option B (N8,306.62) is the standard deviation for probabilities of 0.3, 0.3 and 0.4, not these."}},{"itemId":"1fb5b856-cbde-59c9-85b1-eb6c5dd5be35","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"3d306358-33b5-5b9d-a865-adb1b197b5e7","sourceKey":"bank:FIN101:FIN-0365","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.1), N60,000 (0.2) and N70,000 (0.7). To the nearest whole percent, the coefficient of variation of the security is","options":["14%","12%","11%","10%"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"The coefficient of variation is standard deviation divided by expected return: 6,633.25 / 66,000 = 0.1005, or 10%. Option B (12%) is the CV of the same returns with the probabilities reversed, where the expected return is only N54,000."}},{"itemId":"87d9f260-ca15-547e-942b-05727ed70e1e","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"a876c490-8793-5af7-967f-33fdb8adc181","sourceKey":"bank:FIN101:FIN-0366","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). The expected value of the security is","options":["N66,000","N7,810.25","N61,000,000","N54,000"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"Expected value = 0.7(50,000) + 0.2(60,000) + 0.1(70,000) = 35,000 + 12,000 + 7,000 = N54,000. Option A (N66,000) is the result when the 0.7 probability sits on N70,000 instead of N50,000. Option B is a standard deviation figure, not an expected value."}},{"itemId":"078e0dfb-8e5c-5387-af23-9fb4631cffe8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"308542af-0fae-53a3-8d07-aabbf90ae68a","sourceKey":"bank:FIN101:FIN-0367","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). The variance of the security is","options":["N44,000","N7,810.25","N44,000,000","N57,000"],"correctOption":2,"section":"Analysis of Risk in Financial Decisions","explanation":"Around the expected value of N54,000, the variance is 0.7(4,000)^2 + 0.2(6,000)^2 + 0.1(16,000)^2 = 11,200,000 + 7,200,000 + 25,600,000 = 44,000,000. Option A drops three zeros. Option B is a standard deviation, and option D is an expected value."}},{"itemId":"bfa3d7a7-eca0-5e08-8728-a0ce263fb958","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"e592fb62-bf5e-5eae-ae65-fde0ccaca346","sourceKey":"bank:FIN101:FIN-0368","parentItemId":null,"revision":1,"payload":{"prompt":"The returns and probabilities for a security are given as follows: N50,000 (0.7), N60,000 (0.2) and N70,000 (0.1). To the nearest whole percent, the coefficient of variation of the security is","options":["13%","11%","12%","N54,000"],"correctOption":2,"section":"Analysis of Risk in Financial Decisions","explanation":"CV = standard deviation / expected value = 6,633.25 / 54,000 = 0.1228, or 12%. Option D (N54,000) is the expected value, not a ratio. Option A (13%) and option B (11%) do not match the calculation."}},{"itemId":"baebb4cf-bfa3-5535-9e53-26ef4b0687ee","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"cdd91bdf-e9bd-5b5e-a71c-aa86ce18e58e","sourceKey":"bank:FIN101:FIN-0369","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the risk concerned with the introduction of debt into a firm's capital structure.","options":["Business risk","Economic risk","Investment risk","Financial risk"],"correctOption":3,"section":"Analysis of Risk in Financial Decisions","explanation":"Financial risk arises when a firm uses debt. The fixed interest and repayments must be met whatever happens, which raises the chance that shareholders' returns will swing or that the firm will default. Business risk (A) comes from the uncertainty of operations themselves, even with no debt at all."}},{"itemId":"9e9a89d9-48fc-54db-8303-01910f0c0da7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"cbt_question","questionId":"df017174-b90f-575d-818c-3bf523553f13","sourceKey":"bank:FIN101:FIN-0370","parentItemId":null,"revision":1,"payload":{"prompt":"------ is the risk concerned with the uncertainty of the future prospects of a firm.","options":["Business risk","Economic risk","Investment risk","Financial risk"],"correctOption":0,"section":"Analysis of Risk in Financial Decisions","explanation":"Business risk is the uncertainty about a firm's future operating results, such as sales, costs and profits, that comes from the nature of its business and its market. Financial risk (D) is the additional risk created by using debt. Economic risk (B) refers to the wider economy rather than the firm's own prospects."}}]$expected_content$::jsonb,
  'introduction-finance: cbt_question published payload and identity match source');
set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('203d7e61-c829-5419-a664-5a478e05a8a6')
  where kind = 'theory_question') = $expected_content$[{"itemId":"b463c843-3c57-55e1-97b1-e602e2108f20","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Zenith Agro plc earns profit after tax of ₦80,000,000 and pays a dividend of 25%. (a) How much is retained? (b) Which finance decision is this, and what is its other name?"}},{"itemId":"1df01bce-1f01-5a69-a6a6-1c45816fa063","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"A firm can invest ₦700,000 today in a project that returns ₦300,000 at the end of each of the next 3 years. The required return is 10%. (a) What is the accounting profit? (b) What is the NPV? (c) Does the project increase shareholders' wealth?"}},{"itemId":"8d2a2b51-0d6b-55e6-8a93-ea787c2b13d8","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"A project's cash flows and probabilities are ₦10,000 (0.2), ₦15,000 (0.3), ₦20,000 (0.4) and ₦30,000 (0.1). Calculate the expected value, variance, standard deviation and coefficient of variation."}},{"itemId":"3a6f4bbb-2379-5802-a128-1abedf801b3c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Unilag Ventures deposits ₦150,000 at the end of each year for 4 years at 15% per annum. How much will be in the fund at the end of year 4, and how much if each deposit were made at the beginning of the year?"}},{"itemId":"58b6d20d-4ef2-5fc4-b6eb-9cbf882aaaa7","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Bode Plc earned profit after tax of ₦4,800,000 and paid a preference dividend of ₦800,000 and an ordinary dividend of ₦1,600,000. It has 10,000,000 ordinary shares priced at ₦4.00 each. Calculate EPS, DPS, dividend cover, P/E ratio and dividend yield."}},{"itemId":"f744b4e0-a23a-576b-aef7-06a24f544785","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier invoices ₦500,000 on terms of 2% discount if paid within 10 days, otherwise full payment in 30 days. What is the approximate annual cost of using the trade credit (giving up the discount)?"}},{"itemId":"284bd3a0-7fda-51d7-a7e6-2dcf4eab1916","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde and Amaka are partners with capitals of ₦5,000,000 and ₦3,000,000. Profit for the year is ₦2,400,000. (a) The deed allows 5% interest on capital and shares the remainder 3:1. Find each partner's share. (b) What would each get if there were no partnership agreement?"}}]$expected_content$::jsonb,
  'introduction-finance: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('203d7e61-c829-5419-a664-5a478e05a8a6')
  where kind = 'model_answer') = $expected_content$[{"itemId":"4021c226-7a18-5905-91cd-3c0817fa9d5c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"b463c843-3c57-55e1-97b1-e602e2108f20","revision":1,"payload":{"body":"(a) Dividend = 25% × ₦80,000,000 = ₦20,000,000. Retained = ₦80,000,000 − ₦20,000,000 = ₦60,000,000. (b) It is the dividend decision, also called the profit allocation decision: choosing how much profit to pay out and how much to keep, with the aim of maximising shareholders' wealth."}},{"itemId":"7d7a7f51-52e1-5023-94a6-49919fce8b6c","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"1df01bce-1f01-5a69-a6a6-1c45816fa063","revision":1,"payload":{"body":"• (a) Profit = 3 × 300,000 − 700,000 = ₦200,000.\n• (b) PV year 1 = 300,000 / 1.1 = ₦272,727.27; year 2 = 300,000 / 1.1^2 = ₦247,933.88; year 3 = 300,000 / 1.1^3 = ₦225,394.44. Total PV = ₦746,055.60. NPV = 746,055.60 − 700,000 = ₦46,055.60 (rounded to the nearest kobo).\n• (c) Yes. NPV is positive, so the project adds about ₦46,056 of value for shareholders. Note that the wealth gain is smaller than the ₦200,000 profit, because NPV allows for the time value of money and profit does not."}},{"itemId":"89eb1599-dab4-5854-9f7b-6ec59a31583b","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"8d2a2b51-0d6b-55e6-8a93-ea787c2b13d8","revision":1,"payload":{"body":"R | P | P × R | R − ER | (R − ER)^2 | P × (R − ER)^2\n10,000 | 0.2 | 2,000 | −7,500 | 56,250,000 | 11,250,000\n15,000 | 0.3 | 4,500 | −2,500 | 6,250,000 | 1,875,000\n20,000 | 0.4 | 8,000 | 2,500 | 6,250,000 | 2,500,000\n30,000 | 0.1 | 3,000 | 12,500 | 156,250,000 | 15,625,000\nTotal | 1.0 | 17,500 |  |  | 31,250,000\n• Expected value = ₦17,500\n• Variance = 31,250,000\n• SD = square root of 31,250,000 = ₦5,590.17\n• CV = 5,590.17 / 17,500 × 100 = 31.94%, about 32%"}},{"itemId":"dad68fa3-6efb-5445-a66d-53778b291e19","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"3a6f4bbb-2379-5802-a128-1abedf801b3c","revision":1,"payload":{"body":"Ordinary annuity: FV = 150,000 × (1.15^4 - 1) ÷ 0.15 = 150,000 × (1.74901 - 1) ÷ 0.15 = 150,000 × 4.99337 = ₦749,006.25. Annuity due: 749,006.25 × 1.15 = ₦861,357.19."}},{"itemId":"d88239ef-6037-5373-b7cc-c83d5a5d8e61","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"58b6d20d-4ef2-5fc4-b6eb-9cbf882aaaa7","revision":1,"payload":{"body":"Earnings for ordinary shareholders = 4,800,000 - 800,000 = ₦4,000,000. EPS = 4,000,000 ÷ 10,000,000 = ₦0.40. DPS = 1,600,000 ÷ 10,000,000 = ₦0.16. Dividend cover = 4,000,000 ÷ 1,600,000 = 2.5 times. P/E = 4.00 ÷ 0.40 = 10 times. Dividend yield = 0.16 ÷ 4.00 × 100 = 4%."}},{"itemId":"c760b622-a5c5-5bef-9b54-bc35a7bcafc9","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"f744b4e0-a23a-576b-aef7-06a24f544785","revision":1,"payload":{"body":"• Pay on day 10: 500,000 × 0.98 = ₦490,000. Pay on day 30: ₦500,000.\n• Giving up the discount costs ₦10,000 for the use of ₦490,000 for 20 extra days.\n• Annual cost = (10,000 / 490,000) × (365 / 20) = 37.24% (to 2 d.p.). Trade credit is \"free\" only within the discount period; after that it can be dearer than a bank overdraft."}},{"itemId":"5b61c735-6363-52fa-9e65-2b294d517389","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"284bd3a0-7fda-51d7-a7e6-2dcf4eab1916","revision":1,"payload":{"body":"• (a) Interest: Tunde 5% × 5,000,000 = ₦250,000; Amaka 5% × 3,000,000 = ₦150,000. Remainder = 2,400,000 − 250,000 − 150,000 = ₦2,000,000. Tunde 3/4 × 2,000,000 = ₦1,500,000; Amaka 1/4 × 2,000,000 = ₦500,000. Totals: Tunde = ₦1,750,000; Amaka = ₦650,000 (check: ₦2,400,000).\n• (b) No agreement: no interest on capital, profit shared equally: 2,400,000 / 2 = ₦1,200,000 each."}}]$expected_content$::jsonb,
  'introduction-finance: model_answer published payload and identity match source');
