  where kind = 'course_overview') = $expected_content$[{"itemId":"6551688f-134a-5749-ae36-c57db4119ee8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Actuarial Science","body":"Every topic is examinable.","outcomes":["Describe the relationship between actuarial science and insurance.","Define the various actuarial symbols.","Explain the dynamic role of actuarial science as a discipline.","Identify the various career choices for an actuary.","Solve simple and compound interest problems.","Explain the different features of a life table.","Define the different types of annuities and state their formulae."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, history, actuarial symbols, life-table values and calculations.","Calculations come from Topics 3, 5, 6 and 7. Practise the formulas until you can do them quickly."]}}]$expected_content$::jsonb,
