  from public.read_published_managed_content('d1b6b70d-037b-5e9e-a4d4-17103525cc56')
  where kind = 'note') = $expected_content$[{"itemId":"379e87b6-544b-566a-ba52-5342f8b2a19d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Nature of Actuarial Science and the Actuary","body":"The definitions of actuarial science and an actuary; risk, uncertainty and contingent events; probability, expected value, the law of large numbers and pooling; what actuaries do and how they model; where actuaries work; the skills needed; how actuaries differ from accountants, statisticians and CFAs.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The definitions of actuarial science and an actuary; risk, uncertainty and contingent events; probability, expected value, the law of large numbers and pooling; what actuaries do and how they model; where actuaries work; the skills needed; how actuaries differ from accountants, statisticians and CFAs."}],"lessons":[{"number":"1.1","title":"What actuarial science is and who an actuary is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science:","bold":true},{"text":" deals with evaluating risks and maintaining the "},{"text":"economic stability","bold":true},{"text":" of insurance or financial organisations. Graduates learn to use "},{"text":"mathematics, statistics and probability","bold":true},{"text":" principles to "},{"text":"anticipate future events and take preventive measures","bold":true},{"text":". In short, it is concerned with the "},{"text":"financial consequences of uncertain future events","bold":true},{"text":"."}]},{"text":[{"text":"Main goal of actuarial studies:","bold":true},{"text":" to build the knowledge needed to do an actuary's job and to prepare students to pass their actuarial exams faster."}]},{"text":[{"text":"Actuary (standard definition):","bold":true},{"text":" a person who applies "},{"text":"mathematical approaches to anticipate, measure and manage risk","bold":true},{"text":"."}]},{"text":[{"text":"Other definitions you must recognise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A business professional who manages "},{"text":"financial risk","bold":true},{"text":" related to insurance product design, pensions and other financial corporate planning."}]},{"text":[{"text":"By applying probability, statistics, risk theory and financial principles, an actuary is able to "},{"text":"quantify","bold":true},{"text":" future risk in insurance, annuity and pension programmes."}]}]}]},{"text":[{"text":"An actuary:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Analyses, manages and measures the financial implications of future risk."}]},{"text":[{"text":"Develops and validates financial models to guide decision making."}]},{"text":[{"text":"Serves as the "},{"text":"analytical backbone","bold":true},{"text":" of society's financial security programmes ("},{"text":"insurance, social security, pensions","bold":true},{"text":")."}]}]}]},{"text":[{"text":"Disciplines drawn on:","bold":true},{"text":" probability, statistics, economics, finance and computer science."}]},{"text":[{"text":"Origin of the word:","bold":true},{"text":" Latin "},{"text":"actuarius","bold":true},{"text":", a Roman clerk who kept records and accounts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Part super-hero, part fortune-teller, part trusted advisor.\"","bold":true},{"text":" The fortune-teller part is evaluating the likelihood of future events "},{"text":"using numbers, not crystal balls","bold":true},{"text":". Actuaries are experts in three things:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluating the likelihood of future events."}]},{"text":[{"text":"Designing creative ways to reduce the likelihood of undesirable events."}]},{"text":[{"text":"Decreasing the impact of undesirable events that do occur."}]}]},{"type":"paragraph","text":[{"text":"\"Guaranteeing that undesirable events never occur\" is "},{"text":"not","bold":true},{"text":" one of them: no one can promise that."}]}]},{"text":[{"text":"As "},{"text":"problem solvers and strategic thinkers","bold":true},{"text":", actuaries measure the probability and risk of future events and predict their financial impact on a business and its clients."}]},{"text":[{"text":"Rear-view mirror:","bold":true},{"text":" an actuary typically uses "},{"text":"data from the past to predict the future","bold":true},{"text":", like driving by looking in the rear-view mirror, so must also "},{"text":"quantify how the future will be different from the past","bold":true},{"text":". A sharp rise in petrol prices changes motor insurance costs, so last year's claims are not simply copied forward."}]},{"text":[{"text":"Main challenge:","bold":true},{"text":" there is "},{"text":"no past data","bold":true},{"text":", or the data is "},{"text":"no longer relevant","bold":true},{"text":" because of policy or other changes."}]},{"text":[{"text":"Match the discipline to the task: estimating death rates from past records is "},{"text":"statistics","bold":true},{"text":"; processing two million records and running simulations is "},{"text":"computer science","bold":true},{"text":"; asking how Nigerian inflation, interest rates and unemployment affect claims and returns is "},{"text":"economics","bold":true},{"text":"."}]}]}]},{"number":"1.2","title":"Risk, uncertainty and contingent events","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk:","bold":true},{"text":" (1) the "},{"text":"possibility of failing to meet objectives","bold":true},{"text":"; (2) it "},{"text":"can only be defined in context","bold":true},{"text":": a risk to one person or entity may not be a risk to another."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" a situation that involves "},{"text":"imperfect or unknown information","bold":true},{"text":". It applies to predictions of future events, to measurements already made, or to the unknown. It is also called "},{"text":"unmeasurable risk","bold":true},{"text":"."}]},{"text":[{"text":"Actuarial risk:","bold":true},{"text":" a phenomenon subject to uncertainty in one or more of "},{"text":"3 variables: occurrence, timing and severity","bold":true},{"text":"."}]},{"text":[{"text":"Contingency:","bold":true},{"text":" an "},{"text":"event that may or may not occur","bold":true},{"text":". (It can also mean cash held for emergencies, or a condition that must be met for a contract to be binding.)"}]},{"text":[{"text":"Contingent:","bold":true},{"text":" an economic benefit that depends on an event whose occurrence or timing is not certain."}]},{"text":[{"text":"Hazard:","bold":true},{"text":" a condition that "},{"text":"increases the probability or expected size","bold":true},{"text":" of a loss."}]},{"text":[{"text":"Peril:","bold":true},{"text":" the "},{"text":"probable cause","bold":true},{"text":" (fire, flood, earthquake, theft) that exposes a person or property to loss, and against which insurance is bought."}]},{"text":[{"text":"Risk factor:","bold":true},{"text":" any attribute, characteristic or exposure that increases the likelihood of a future loss."}]},{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of "},{"text":"death","bold":true},{"text":" in a population, often measured by the probability that a randomly selected person "},{"text":"dies","bold":true},{"text":" within a period."}]},{"text":[{"text":"Morbidity:","bold":true},{"text":" the rate of "},{"text":"disease","bold":true},{"text":" in a population, often measured by the probability that a randomly selected person "},{"text":"becomes seriously ill","bold":true},{"text":" within a period."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk versus uncertainty:","bold":true},{"text":" under risk, the chances of outcomes "},{"text":"can be measured","bold":true},{"text":"; under uncertainty they "},{"text":"cannot","bold":true},{"text":"."}]},{"text":[{"text":"Risk in context:","bold":true},{"text":" heavy rain threatens a Benue farmer's crops but is no concern to a Lagos software company."}]},{"text":[{"text":"Which variable is uncertain?","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Whole life policy paying ₦2,000,000 whenever Mr Okonkwo dies: death is certain and the amount is fixed, so only the "},{"text":"timing","bold":true},{"text":" is uncertain."}]},{"text":[{"text":"Motor cover in Abuja: the insurer does not know whether the car will crash ("},{"text":"occurrence","bold":true},{"text":") or how much repairs would cost ("},{"text":"severity","bold":true},{"text":")."}]},{"text":[{"text":"\"Ownership\" is "},{"text":"not","bold":true},{"text":" an actuarial risk variable."}]}]}]},{"text":[{"text":"A policy paying ₦1,000,000 only if Mrs Adebayo dies within 10 years is "},{"text":"contingent","bold":true},{"text":": it depends on an uncertain event. A fixed amount does not make it certain."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fire is the "},{"text":"peril","bold":true},{"text":"; the faulty wiring in a Kano warehouse is the "},{"text":"hazard","bold":true},{"text":". Do not swap them."}]},{"text":[{"text":"Trap:","bold":true},{"text":" mortality is death; morbidity is illness."}]}]}]},{"number":"1.3","title":"Probability, expected value, pooling and insurance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Probability","bold":true},{"text":" measures the likelihood that an event occurs. It always lies "},{"text":"from 0 to 1","bold":true},{"text":" inclusive (0 = impossible, 1 = certain). A value such as 1.2 or a negative value can "},{"text":"never","bold":true},{"text":" be a probability."}]},{"text":[{"text":"Expected value:","bold":true},{"text":" the "},{"text":"probability-weighted average","bold":true},{"text":" of the values taken by a random variable."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"E(X) = x_1 × p_1 + x_2 × p_2 + ... + x_k × p_k"}]},{"text":[{"text":"Expected claim cost per policy = probability of a claim × average claim amount"}]},{"text":[{"text":"Total expected claims = number of policies × expected claim cost per policy"}]}]}]},{"text":[{"text":"Law of large numbers:","bold":true},{"text":" as the number of independent, similar trials increases, the observed proportion of an event becomes "},{"text":"more stable","bold":true},{"text":". Larger groups give more certain predictions."}]},{"text":[{"text":"Statistical regularity:","bold":true},{"text":" random events show regular patterns when repeated enough times, or when there are enough similar events. It is an umbrella term covering the law of large numbers."}]},{"text":[{"text":"Pooling:","bold":true},{"text":" forming a group of policies with "},{"text":"similar characteristics","bold":true},{"text":", so that an insurer can manage individual risks by "},{"text":"reducing the variability (variance)","bold":true},{"text":" of total outcomes. A good pool is (1) "},{"text":"large","bold":true},{"text":", (2) "},{"text":"similar (homogeneous)","bold":true},{"text":", (3) with losses "},{"text":"reasonably independent","bold":true},{"text":"."}]},{"text":[{"text":"Risk aversion:","bold":true},{"text":" preferring a "},{"text":"small certain loss","bold":true},{"text":" (the premium) to a "},{"text":"large uncertain one","bold":true},{"text":". Because risk-averse people will pay "},{"text":"above their expected loss","bold":true},{"text":", the insurer can "},{"text":"cover its expenses and make a profit","bold":true},{"text":"."}]},{"text":[{"text":"Insurable risk","bold":true},{"text":" has:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A potential loss"}]},{"text":[{"text":"that is significant and important;"}]},{"text":[{"text":"a loss and economic value that are well defined and "},{"text":"out of the policyholder's complete control","bold":true},{"text":";"}]},{"text":[{"text":"covered losses that are reasonably independent."}]}]},{"type":"paragraph","text":[{"text":"It must also not be so large that no insurer could pay for it."}]}]},{"text":[{"text":"Financial security system:","bold":true},{"text":" an arrangement in which one party assumes the obligation to provide benefits that offset undesirable economic consequences suffered by a second party, in return for payments called "},{"text":"considerations","bold":true},{"text":". Examples: insurance products and retirement plans."}]},{"text":[{"text":"Experience:","bold":true},{"text":" the data obtained from the actual operation of an insurance or pension scheme."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 1 (expected loss).","bold":true},{"text":" An Onitsha shop has a 0.4% chance of a fire in a year, with a loss of ₦5,000,000 if it happens, and nil otherwise."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1: 0.4% = 0.004."}]},{"text":[{"text":"Step 2: E(loss) = 0.004 × ₦5,000,000 + 0.996 × ₦0 = "},{"text":"₦20,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example 2 (expected claim per policy).","bold":true},{"text":" An insurer covers 10,000 buses; 3% have an accident each year; the average claim is ₦400,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Per bus: 0.03 × ₦400,000 = "},{"text":"₦12,000","bold":true},{"text":"."}]},{"text":[{"text":"Whole portfolio: 10,000 × ₦12,000 = ₦120,000,000. \"Per bus\" wants ₦12,000."}]}]}]},{"text":[{"text":"Risk aversion in figures.","bold":true},{"text":" An Aba trader faces a 0.5% chance of losing ₦3,000,000. Her expected loss is 0.005 × ₦3,000,000 = ₦15,000, yet she gladly pays a ₦30,000 premium. The extra ₦15,000 is what lets the insurer cover expenses and earn a profit."}]},{"text":[{"text":"Law of large numbers in practice.","bold":true},{"text":" Insurer B with 50,000 similar okada riders predicts total claims more reliably than Insurer A with 50, because larger similar groups give more stable proportions."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a pool whose members are \"as different as possible\" is "},{"text":"not","bold":true},{"text":" desirable. "},{"text":"Trap:","bold":true},{"text":" a loss fully under the policyholder's control is "},{"text":"not","bold":true},{"text":" insurable."}]}]}]},{"number":"1.4","title":"What actuaries do and how they work","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The actuary","bold":true},{"text":" identifies, analyses and documents risks; monitors risk areas; defines problems and generates ideas; develops recommendations that lead to implemented solutions; and "},{"text":"continuously monitors results","bold":true},{"text":"."}]},{"text":[{"text":"An actuary's work is based on "},{"text":"theory, data and experience","bold":true},{"text":" and is performed with "},{"text":"professional judgement","bold":true},{"text":", which is needed because tasks affect "},{"text":"several stakeholders with different, sometimes conflicting, needs","bold":true},{"text":"."}]},{"text":[{"text":"What actuaries do:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluate the likelihood of future events:","bold":true},{"text":" forecast the impact of catastrophes; calculate the expected lifetime of a retiree receiving a pension."}]},{"text":[{"text":"Design ways to reduce the likelihood of undesirable events:","bold":true},{"text":" life insurance policies, annuities; promote safety (seat belts)."}]},{"text":[{"text":"Decrease the impact of undesirable events that occur:","bold":true},{"text":" death benefits, retirement benefits, indemnity benefits."}]},{"text":[{"text":"Participate in corporate planning:","bold":true},{"text":" mergers and acquisitions; evaluating investment programmes."}]},{"text":[{"text":"Help insurance companies:","bold":true},{"text":" calculate rates for new products; forecast and interpret underwriting results; maintain databases for analysing pricing issues."}]}]}]},{"text":[{"text":"Further value:","bold":true},{"text":" products meeting customers' needs "},{"text":"now and in the future","bold":true},{"text":"; expertise in "},{"text":"data quality and analytics","bold":true},{"text":"; "},{"text":"predictive modelling and optimisation","bold":true},{"text":" for smarter risk decisions in digital businesses; supporting "},{"text":"marketing","bold":true},{"text":" (modelling demand for a new product), "},{"text":"accounting","bold":true},{"text":" (models and assumptions for "},{"text":"budgeting and forecasting","bold":true},{"text":"), "},{"text":"product development","bold":true},{"text":", and "},{"text":"identifying and managing risk","bold":true},{"text":"."}]},{"text":[{"text":"Key terms:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial model:","bold":true},{"text":" a "},{"text":"simplified representation","bold":true},{"text":" of real-world relationships, used to explain a system, derive estimates and guide decisions."}]},{"text":[{"text":"3 components:","bold":true},{"text":" "},{"text":"input","bold":true},{"text":" (delivers assumptions, parameters and data), "},{"text":"processing","bold":true},{"text":" (transforms inputs into estimates), "},{"text":"output","bold":true},{"text":" (translates estimates into useful business information)."}]},{"text":[{"text":"Life cycle, 3 phases:","bold":true},{"text":" "},{"text":"specification","bold":true},{"text":", "},{"text":"implementation","bold":true},{"text":", "},{"text":"production","bold":true},{"text":" (one or more model runs)."}]},{"text":[{"text":"Actuarial assumption:","bold":true},{"text":" an estimate of an uncertain variable fed into a model, normally to calculate premiums or benefits."}]},{"text":[{"text":"Deterministic model:","bold":true},{"text":" one fixed set of assumptions, events assumed to happen with certainty, giving a single result."}]},{"text":[{"text":"Stochastic model:","bold":true},{"text":" estimates "},{"text":"probability distributions","bold":true},{"text":" of outcomes by letting one or more inputs vary randomly."}]},{"text":[{"text":"Best estimate:","bold":true},{"text":" neither optimistic nor conservative."}]},{"text":[{"text":"Scenario:","bold":true},{"text":" a set of assumptions about future conditions, based on professional judgement or prescribed by law."}]},{"text":[{"text":"Actuarial control cycle:","bold":true},{"text":" "},{"text":"define the problem → design the solution → monitor the results","bold":true},{"text":"."}]},{"text":[{"text":"Pricing:","bold":true},{"text":" developing premiums to cover losses from underwritten risks and future benefits, using probabilities of loss."}]},{"text":[{"text":"Reserve:","bold":true},{"text":" a liability set aside to pay "},{"text":"future claims","bold":true},{"text":"."}]},{"text":[{"text":"In short, actuaries "},{"text":"analyse past data","bold":true},{"text":" to work out how much money should be "},{"text":"set aside to cover financial losses that could occur in the future","bold":true},{"text":"."}]},{"text":[{"text":"Valuation:","bold":true},{"text":" placing a value on an insurer's assets and/or liabilities."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying and measuring risk, then developing strategies to minimise, monitor and control it. Handle first the risks with the "},{"text":"greatest loss and greatest probability","bold":true},{"text":"."}]},{"text":[{"text":"Risk transfer:","bold":true},{"text":" shifting risk to another party (for example, paying an insurer a premium). "},{"text":"Risk retention:","bold":true},{"text":" keeping the risk yourself (self-insurance, deductibles)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Matching tasks to categories:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Seat-belt campaign by a Lagos motor insurer's actuary: "},{"text":"reducing the likelihood","bold":true},{"text":" of undesirable events."}]},{"text":[{"text":"Monthly pension to a retired Ibadan civil servant, death benefit to a family: "},{"text":"decreasing the impact","bold":true},{"text":" of events that occur."}]},{"text":[{"text":"Estimating how long a pensioner will draw a pension, forecasting flood costs: "},{"text":"evaluating the likelihood","bold":true},{"text":" of future events."}]},{"text":[{"text":"Assessing a bank merger and investment programmes: "},{"text":"corporate planning","bold":true},{"text":"."}]},{"text":[{"text":"Acting as the insurer's lawyer is "},{"text":"not","bold":true},{"text":" an actuarial task; nor is ignoring results after a solution is in place."}]}]}]},{"text":[{"text":"The Lagos car-accident method.","bold":true},{"text":" To predict accidents in Lagos this November, the actuary first looks at the "},{"text":"percentage of people involved in accidents in previous years","bold":true},{"text":", identifies a "},{"text":"trend","bold":true},{"text":", predicts this year's percentage, then sets how much each person should pay."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example: 2.0%, 2.2%, 2.4% in the last three years. The rise is 0.2 percentage points a year, so this year = 2.4% + 0.2% = "},{"text":"2.6%","bold":true},{"text":"."}]},{"text":[{"text":"If the average claim is ₦500,000, the expected claim cost per driver = 0.026 × ₦500,000 = "},{"text":"₦13,000","bold":true},{"text":" (before expenses and profit)."}]}]}]},{"text":[{"text":"Pricing versus reserving:","bold":true},{"text":" deciding what to charge new motor customers next year is "},{"text":"pricing","bold":true},{"text":"; estimating what to hold now for claims on policies already sold is "},{"text":"reserving","bold":true},{"text":"."}]},{"text":[{"text":"Deterministic versus stochastic:","bold":true},{"text":" one fixed 10% interest assumption giving one answer is deterministic; 10,000 random simulations giving a distribution of profits is stochastic."}]}]}]},{"number":"1.5","title":"Where actuaries work, skills, and how they differ from others","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Typical areas of actuarial work:","bold":true},{"text":" insurance (general, health, life); finance (banking, corporate, investment, pensions); data science and analytics; technology; enterprise risk; resource and environment (climate change)."}]},{"text":[{"text":"8 specialisations:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"text":[{"text":"Enterprise Risk Management"}]}]}]},{"text":[{"text":"Most common industries:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insurance:","bold":true},{"text":" property (home) and casualty (auto); life and annuities."}]},{"text":[{"text":"Employee benefits:","bold":true},{"text":" retirement benefits, health benefits, social security."}]},{"text":[{"text":"Financial services:","bold":true},{"text":" banks, investing, risk management, mergers and acquisitions."}]}]}]},{"text":[{"text":"Actuaries are largely employed by "},{"text":"insurance companies and consulting firms","bold":true},{"text":", in "},{"text":"4 areas","bold":true},{"text":": life, annuities and mutual funds; health; pensions; property and casualty."}]},{"text":[{"text":"Skills needed:","bold":true},{"text":" mathematical and analytical skills; project management and problem-solving skills; excellent "},{"text":"communication","bold":true},{"text":" skills (oral and written); strong business sense and commercial awareness; "},{"text":"self-motivation","bold":true},{"text":"; ambition and ability to work in a team. Also: business acumen, computer skills, work ethic, creativity, independence, collaboration."}]},{"text":[{"text":"Besides mathematics, "},{"text":"self-motivation and good communication skills","bold":true},{"text":" are equally important."}]}]},{"type":"table","header":[[],[{"text":"Actuary"}],[{"text":"Accountant"}],[{"text":"CFA"}]],"rows":[[[{"text":"Business focus"}],[{"text":"Financial impact of events that "},{"text":"may or may not occur in the future","bold":true}],[{"text":"Financial impact of events that "},{"text":"have already happened","bold":true}],[{"text":"Analyse financial reports and investments"}]],[[{"text":"How"}],[{"text":"Uses large amounts of data to calculate the probability and impact of future events and what to do"}],[{"text":"Works with "},{"text":"known","bold":true},{"text":" numbers; creates or audits balance sheets and income statements"}],[{"text":"Uses analysis to recommend investments"}]],[[{"text":"Assets and liabilities"}],[{"text":"Both","bold":true},{"text":", specially trained in complicated "},{"text":"liabilities","bold":true}],[{"text":"Reports on both"}],[{"text":"Geared towards "},{"text":"assets","bold":true}]],[[{"text":"Product focus"}],[{"text":"Understands products and how they make money"}],[{"text":"Reports cost, revenue and profit of a product"}],[{"text":"Which products or companies to invest in"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuary vs statistician:","bold":true},{"text":" a statistician collects, analyses and interprets data in any field. An actuary uses statistics and probability "},{"text":"together with financial mathematics and business knowledge","bold":true},{"text":" to put a "},{"text":"money value","bold":true},{"text":" on future risk, mainly in insurance, pensions and finance."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Life:","bold":true},{"text":" term and permanent death-benefit products. "},{"text":"Annuities:","bold":true},{"text":" a lump sum or payments now for periodic payments starting immediately or later. "},{"text":"Mutual fund:","bold":true},{"text":" pools investors' assets to buy securities for a common goal."}]},{"text":[{"text":"Health:","bold":true},{"text":" products for individuals, families and sole proprietors, and plans for employers by size: small group 2 to 50 employees, middle market 51 to 3,000, national accounts 3,001 or more."}]},{"text":[{"text":"Pensions","bold":true},{"text":" give steady income, usually a guaranteed annuity, to retired or disabled employees. "},{"text":"Defined benefit:","bold":true},{"text":" based on pay, years of service, retirement age and other factors. "},{"text":"Defined contribution:","bold":true},{"text":" the employee defers part of salary into the plan and "},{"text":"bears the investment risk","bold":true},{"text":". Nigeria's Contributory Pension Scheme, regulated by "},{"text":"PenCom","bold":true},{"text":", is a defined contribution scheme."}]},{"text":[{"text":"Property and casualty:","bold":true},{"text":" business, personal (auto, homeowners), and financial, professional and international insurance."}]},{"text":[{"text":"Typical projects:","bold":true},{"text":" pricing life products (impact of AIDS on mortality tables); costing motor or home cover in an area (impact of global warming); setting HMO premium rates; pricing increased retirement benefits. In Nigeria, insurers are supervised by "},{"text":"NAICOM","bold":true},{"text":"."}]},{"text":[{"text":"Why self-motivation:","bold":true},{"text":" trainees must "},{"text":"pass professional exams while working full time","bold":true},{"text":"."}]},{"text":[{"text":"Communication in action:","bold":true},{"text":" explaining to a non-mathematical board why premiums must rise."}]},{"text":[{"text":"Applying the table:","bold":true},{"text":" setting aside money today for 30 years of pension promises that depend on how long workers live is an "},{"text":"actuary's","bold":true},{"text":" job. All three professions are prestigious and should work together."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science evaluates risks and maintains the economic stability of insurance and financial organisations."}]},{"text":[{"text":"An actuary applies mathematical approaches to anticipate, measure and manage risk; Latin actuarius."}]},{"text":[{"text":"Risk = possibility of failing to meet objectives, defined in context; uncertainty = unmeasurable risk."}]},{"text":[{"text":"Actuarial risk variables: occurrence, timing, severity. Contingency = an event that may or may not occur."}]},{"text":[{"text":"Probability is from 0 to 1; expected claim = probability × average claim; large, similar, independent pools reduce variability."}]},{"text":[{"text":"Model: input, processing, output; phases specification, implementation, production; control cycle: define, design, monitor."}]},{"text":[{"text":"Pricing sets future premiums; reserving holds money for claims on policies already sold."}]},{"text":[{"text":"Actuaries look forward and specialise in liabilities; accountants look back; CFAs focus on assets."}]}]}],"theory":{"itemId":"1871811f-78c9-57e1-980e-e0e29fb463ab","question":[{"type":"paragraph","text":[{"text":"An insurer covers 20,000 similar okada riders in Lagos. Past experience shows 1.5% of riders make a claim each year, with an average claim of ₦250,000. Ignoring expenses and profit, find (a) the expected claim cost per rider and (b) the total expected claims. (c) Why is this prediction reliable?"}]}]},"practice":[{"topic":"Nature of Actuarial Science and the Actuary","named":false}]}},{"itemId":"2b31ed30-4ca0-5a79-b2d8-7db48adcbd26","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"History and Professional Structure of Actuarial Science","body":"The people, works and dates that built actuarial science (1654 to 1825); the Equitable Society and the first use of the title \"actuary\"; the world's actuarial bodies and when they began; the Nigerian bodies and what each does; the student, associate and fellow grades and the IFoA, SOA and CAS exam pathways; professional standards and ethics; career outlook, supply and demand.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The people, works and dates that built actuarial science (1654 to 1825); the Equitable Society and the first use of the title \"actuary\"; the world's actuarial bodies and when they began; the Nigerian bodies and what each does; the student, associate and fellow grades and the IFoA, SOA and CAS exam pathways; professional standards and ethics; career outlook, supply and demand."}],"lessons":[{"number":"2.1","title":"Probability and the first mortality tables","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1654, Blaise Pascal and Pierre de Fermat:","bold":true},{"text":" letters on the gambler's \"problem of points\". Treated as the start of "},{"text":"modern probability theory","bold":true},{"text":"."}]},{"text":[{"text":"1662, John Graunt:","bold":true},{"text":" a London draper (cloth tradesman). Published "},{"text":"Natural and Political Observations ... upon the Bills of Mortality","italic":true},{"text":", based on the "},{"text":"weekly London Bills of Mortality","bold":true},{"text":". Showed deaths follow predictable patterns in a population. Main contribution: the "},{"text":"first attempt at a life table","bold":true},{"text":" from death records."}]},{"text":[{"text":"1693, Edmond Halley:","bold":true},{"text":" the astronomer famous for predicting the return of the comet named after him. Built a life table from the "},{"text":"parish records of Breslau","bold":true},{"text":" and showed how to "},{"text":"price a life annuity","bold":true},{"text":" from it. Practical use: life annuities sold by the British government should be priced "},{"text":"according to the buyer's age","bold":true},{"text":"."}]},{"text":[{"text":"1713, Jacob Bernoulli:","bold":true},{"text":" "},{"text":"Ars Conjectandi","italic":true},{"text":", published after his death. Contains an early version of the "},{"text":"law of large numbers","bold":true},{"text":"."}]},{"text":[{"text":"1725, Abraham de Moivre:","bold":true},{"text":" "},{"text":"Annuities upon Lives","italic":true},{"text":" (London). Methods for valuing annuities on one or more lives, using a "},{"text":"postulated uniform rate of mortality","bold":true},{"text":" together with a "},{"text":"constant rate of interest","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Law of large numbers / statistical regularity:","bold":true},{"text":" if similar independent trials are repeated under the same conditions, the proportion of times an event happens settles down (stabilises) as the number of trials grows. Pooling many similar risks makes the insurer's results predictable."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not swap the cities: "},{"text":"Graunt = London","bold":true},{"text":" (Bills of Mortality); "},{"text":"Halley = Breslau","bold":true},{"text":". Northampton belongs to Richard Price (Lesson 2.2); Equitable records belong to neither."}]},{"text":[{"text":"Halley's table showed that a young buyer of a life annuity should pay more than an old buyer, because the young buyer is expected to collect payments for longer. A flat price for all ages is wrong."}]},{"text":[{"text":"Law of large numbers in ₦ terms: a Lagos motor insurer with only 200 policies may see 4 accidents one year (2%) and 14 the next (7%). With 50,000 similar policies the yearly rate stays close to 4%, about 2,000 accidents. The insurer can then set a premium with confidence. This is "},{"text":"statistical regularity","bold":true},{"text":", not adverse selection or the time value of money."}]}]}]},{"number":"2.2","title":"The birth of the profession, 1750s to 1825","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"James Dodson","bold":true},{"text":" (died "},{"text":"1757","bold":true},{"text":"): pioneered the "},{"text":"level premium system","bold":true},{"text":" for long-term life assurance. His work led to the founding of the Equitable."}]},{"text":[{"text":"1762, the Society for Equitable Assurances on Lives and Survivorships","bold":true},{"text":" (the "},{"text":"Equitable","bold":true},{"text":", London): the first life office to charge "},{"text":"scientifically calculated premiums","bold":true},{"text":" on long-term policies."}]},{"text":[{"text":"Edward Rowe Mores","bold":true},{"text":", a founder of the Equitable, specified around 1762 that its chief official be called the "},{"text":"actuary","bold":true},{"text":": the first use of the title for a business position. Before then, an actuary (Latin "},{"text":"actuarius","italic":true},{"text":") was a "},{"text":"clerk who kept the records of a court or senate","bold":true},{"text":"."}]},{"text":[{"text":"William Morgan:","bold":true},{"text":" appointed actuary of the Equitable in "},{"text":"1775","bold":true},{"text":", held the post until "},{"text":"1830","bold":true},{"text":"; often called the "},{"text":"father of the actuarial profession","bold":true},{"text":"."}]},{"text":[{"text":"Richard Price:","bold":true},{"text":" "},{"text":"Observations on Reversionary Payments","italic":true},{"text":" ("},{"text":"1771","bold":true},{"text":"); compiled the "},{"text":"Northampton mortality table","bold":true},{"text":", a British standard for about a century. Weakness: it "},{"text":"overstated mortality","bold":true},{"text":", so "},{"text":"annuities priced on it were sold too cheaply","bold":true},{"text":" (and life cover was overpriced)."}]},{"text":[{"text":"1825, Benjamin Gompertz:","bold":true},{"text":" law of mortality based on the idea that a person's "},{"text":"resistance to death declines","bold":true},{"text":" with age, so the force of mortality rises geometrically: μ_x = B × c^x (B > 0, c > 1)."}]}]},{"type":"table","header":[[{"text":"Premium type"}],[{"text":"What it is"}]],"rows":[[[{"text":"Level premium","bold":true}],[{"text":"The same premium every year for the policy's life; early years overpay, later years underpay"}]],[[{"text":"Natural (yearly risk) premium","bold":true}],[{"text":"Each year's premium matches that year's risk, so it rises with age"}]],[[{"text":"Single premium","bold":true}],[{"text":"One payment at the start covers the whole policy"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Level premium example:","bold":true},{"text":" Bola, aged 30, pays ₦60,000 every year on a whole life policy, and still pays ₦60,000 at 60 although her death risk is now far higher. This is a "},{"text":"level premium","bold":true},{"text":". Her early overpayments build a reserve that meets the shortfall in later years."}]},{"text":[{"text":"Trap: "},{"text":"Gompertz is not linked with the level premium","bold":true},{"text":"; that is Dodson. Gompertz = 1825 law of mortality."}]},{"text":[{"text":"Trap: Mores named the post; "},{"text":"Morgan held it","bold":true},{"text":" for 55 years. Price was Morgan's uncle and adviser."}]}]},{"type":"paragraph","text":[{"text":"Timeline to memorise:","bold":true},{"text":" 1654 Pascal and Fermat · 1662 Graunt · 1693 Halley · 1713 Bernoulli · 1725 de Moivre · 1757 Dodson dies · 1762 Equitable and \"actuary\" · 1771 Price · 1775 to 1830 Morgan · 1825 Gompertz · 1848 Institute of Actuaries."}]}]},{"number":"2.3","title":"Actuarial bodies around the world","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Key facts"}]],"rows":[[[{"text":"Institute of Actuaries","bold":true}],[{"text":"Founded "},{"text":"1848","bold":true},{"text":", London"}]],[[{"text":"Faculty of Actuaries","bold":true}],[{"text":"Founded "},{"text":"1856","bold":true},{"text":", Scotland (Edinburgh); Royal Charter "},{"text":"1868","bold":true},{"text":", the "},{"text":"first actuarial body granted one","bold":true}]],[[{"text":"Institute and Faculty of Actuaries (IFoA)","bold":true}],[{"text":"The two merged on "},{"text":"1 August 2010","bold":true},{"text":"; offices in London, Oxford, Edinburgh, Beijing, Malaysia and Singapore"}]],[[{"text":"Society of Actuaries (SOA)","bold":true}],[{"text":"Formed "},{"text":"1949","bold":true},{"text":" by merging the "},{"text":"Actuarial Society of America","bold":true},{"text":" (1889) and the "},{"text":"American Institute of Actuaries","bold":true},{"text":" (1909); Chicago, Illinois area"}]],[[{"text":"Casualty Actuarial Society (CAS)","bold":true}],[{"text":"Founded "},{"text":"November 1914","bold":true},{"text":" as the "},{"text":"Casualty Actuarial and Statistical Society of America","bold":true},{"text":"; present name "},{"text":"1921","bold":true},{"text":"; Arlington, Virginia (Washington, DC area). Began with "},{"text":"workers' compensation","bold":true},{"text":" insurance"}]],[[{"text":"International Actuarial Association (IAA)","bold":true}],[{"text":"Origin: committee of "},{"text":"1895","bold":true},{"text":", when the first "},{"text":"International Congress of Actuaries","bold":true},{"text":" met in "},{"text":"Brussels","bold":true},{"text":". Restructured in "},{"text":"1998","bold":true},{"text":" at the Congress in "},{"text":"Birmingham","bold":true},{"text":": its full members are "},{"text":"national actuarial associations","bold":true},{"text":" (an association of associations)"}]],[[{"text":"Actuarial Society of South Africa (ASSA)","bold":true}],[{"text":"Cape Town"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Letters: "},{"text":"FIA","bold":true},{"text":" / "},{"text":"FFA","bold":true},{"text":" = Fellow of the Institute / "},{"text":"Fellow of the Faculty of Actuaries","bold":true},{"text":"; "},{"text":"AIA","bold":true},{"text":" = Associate of the Institute. "},{"text":"ASA / FSA","bold":true},{"text":" = SOA; "},{"text":"ACAS / FCAS","bold":true},{"text":" = CAS."}]},{"text":[{"text":"The IAA's "},{"text":"International Standards of Actuarial Practice (ISAPs)","bold":true},{"text":" are "},{"text":"model standards","bold":true},{"text":": member associations are encouraged to align their own standards with them. They are not binding world rules."}]}]},{"type":"paragraph","text":[{"text":"United States professional bodies","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"American Academy of Actuaries","bold":true},{"text":" (1965): its "},{"text":"MAAA","bold":true},{"text":" designation must be held to "},{"text":"sign statements of actuarial opinion","bold":true},{"text":" in the US."}]},{"text":[{"text":"Actuarial Standards Board (ASB):","bold":true},{"text":" promulgates the "},{"text":"Actuarial Standards of Practice (ASOPs)","bold":true},{"text":", which say what an actuary should "},{"text":"consider, document and disclose","bold":true},{"text":" on an assignment."}]},{"text":[{"text":"Actuarial Board for Counseling and Discipline (ABCD):","bold":true},{"text":" reviews complaints that an actuary breached the code of conduct and can recommend discipline."}]}]},{"type":"paragraph","text":[{"text":"Practice areas by body","bold":true}]},{"type":"table","header":[[{"text":"Area"}],[{"text":"IFoA"}],[{"text":"SOA"}],[{"text":"CAS"}],[{"text":"ASSA"}]],"rows":[[[{"text":"Life"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Pensions/retirement"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Health"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"General insurance (P&C)"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}],[{"text":"Yes"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CAS = property and casualty only","bold":true},{"text":": motor (auto) pricing, liability ratemaking and property reserving are CAS work; "},{"text":"life assurance and annuities are not","bold":true},{"text":"."}]},{"text":[{"text":"Chinedu, a general insurance actuary in Lagos, completing CAS Associate requirements writes "},{"text":"ACAS","bold":true},{"text":" (not ASA, which is SOA, and not FCAS, which is Fellow)."}]},{"text":[{"text":"Year traps: 1848 Institute; 1856 Faculty; 1868 Faculty's charter; 1889 Actuarial Society of America; 1762 Equitable."}]},{"text":[{"text":"When these bodies were founded in the mid-19th century, one main purpose besides supporting actuaries was "},{"text":"protecting the public","bold":true},{"text":" by ensuring members' competence and ethical standards. They never set every insurer's premiums, collected taxes or sold policies."}]},{"text":[{"text":"All bodies' syllabuses cover financial mathematics, probability, statistics, accounting, corporate finance, loss and mortality models, reserving, data ethics and model validation. Banking, ERM and microinsurance are notable exclusions from the practice areas above."}]}]}]},{"number":"2.4","title":"The profession and regulators in Nigeria","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Role"}]],"rows":[[[{"text":"Nigerian Actuarial Society (NAS)","bold":true}],[{"text":"Professional body for actuaries","bold":true},{"text":" in Nigeria"}]],[[{"text":"National Insurance Commission (NAICOM)","bold":true}],[{"text":"Government agency established under the "},{"text":"National Insurance Commission Act 1997","bold":true},{"text":"; "},{"text":"regulates and supervises insurers","bold":true}]],[[{"text":"National Pension Commission (PenCom)","bold":true}],[{"text":"Established by the "},{"text":"Pension Reform Act 2004","bold":true},{"text":"; "},{"text":"regulates and supervises pensions","bold":true}]],[[{"text":"Chartered Insurance Institute of Nigeria (CIIN)","bold":true}],[{"text":"Professional body for insurance practitioners (not for actuaries)"}]],[[{"text":"Securities and Exchange Commission (SEC)","bold":true}],[{"text":"Regulates the capital market (not insurance)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"January 2024:","bold":true},{"text":" the University of Lagos MSc Actuarial Science programme was accredited by the "},{"text":"IFoA","bold":true},{"text":", earning its graduates exam exemptions."}]}]},{"type":"paragraph","text":[{"text":"Current landscape in Nigeria (2022 figures)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Supply:","bold":true},{"text":" 19 Fellows, 8 Associates, 70+ students; 5 universities, including UNILAG."}]},{"text":[{"text":"Demand:","bold":true},{"text":" 56 insurance companies, life and non-life (limited in pensions); requirement soon to keep an actuarial function in-house; IFRS 17 and innovations."}]},{"text":[{"text":"Public policy and regulation:","bold":true},{"text":" 3 actuarial staff within NAICOM but no qualified actuaries; no clarity on whether an appointed actuary must be an associate or a fellow; "},{"text":"no local actuarial (mortality) tables","bold":true},{"text":"; plans for risk-based capital requirements and IFRS 17."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"N","bold":true},{"text":"AICOM = i"},{"text":"N","bold":true},{"text":"surance regulator; "},{"text":"P","bold":true},{"text":"enCom = "},{"text":"P","bold":true},{"text":"ensions regulator; NAS = the actuaries' own society. Exams love swapping these three."}]},{"text":[{"text":"The figures show demand far ahead of supply: 56 insurers but only 19 Fellows in the whole country. That gap is the career opportunity for a UNILAG actuarial student."}]}]}]},{"number":"2.5","title":"Professional structure and how to qualify","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grades:","bold":true},{"text":" "},{"text":"Student → Associate → Fellow","bold":true},{"text":"."}]},{"text":[{"text":"You qualify by passing a "},{"text":"series of professional exams, usually while working","bold":true},{"text":" (\"earn while you learn\"). Exams are held several times a year. A degree alone does not qualify you."}]},{"text":[{"text":"SOA/CAS:","bold":true},{"text":" "},{"text":"Associate (ASA, ACAS)","bold":true},{"text":" and "},{"text":"Fellow (FSA, FCAS)","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ASA:","bold":true},{"text":" has shown knowledge of the fundamental concepts and techniques for modelling and managing risk through required exams and learning modules, and completed a professionalism course."}]},{"text":[{"text":"FSA:","bold":true},{"text":" has shown knowledge in "},{"text":"all major practice areas","bold":true},{"text":", with "},{"text":"further concentration in one or more","bold":true},{"text":" of them, plus further professionalism education."}]}]}]},{"text":[{"text":"SOA/CAS joint preliminary exams:","bold":true},{"text":" "},{"text":"P/1","bold":true},{"text":" Probability; "},{"text":"FM/2","bold":true},{"text":" Financial Mathematics; "},{"text":"MFE/3F","bold":true},{"text":" Financial Economics; "},{"text":"C/4","bold":true},{"text":" Actuarial Models. Then SOA's "},{"text":"MLC","bold":true},{"text":" (Life Contingencies) or CAS's "},{"text":"3L","bold":true},{"text":" (Life Contingencies and Statistics)."}]},{"text":[{"text":"SOA upper-level areas:","bold":true},{"text":" Retirement Benefits; Group and Health; Individual Life and Annuities; Investments. "},{"text":"CAS:","bold":true},{"text":" P&C insurance/pricing; reserving; accounting/annual statement; advanced financial management; advanced pricing."}]}]},{"type":"paragraph","text":[{"text":"IFoA pathway","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Core Principles (7):","bold":true},{"text":" CS1, CS2 Actuarial Statistics; CM1, CM2 Actuarial Mathematics; CB1 Business Finance; CB2 Business Economics; CB3 Business Management (Professional Skills Stage 1 needed before CB3)."}]},{"text":[{"text":"Core Practices (3):","bold":true},{"text":" "},{"text":"CP1 Actuarial Practice","bold":true},{"text":", CP2 Modelling Practice, CP3 Communication Practice."}]},{"text":[{"text":"Associate","bold":true},{"text":" = Core Principles + Core Practices + "},{"text":"2 years of PPD","bold":true},{"text":" (Personal and Professional Development) + "},{"text":"Professional Skills Stages 1 and 2","bold":true},{"text":"."}]},{"text":[{"text":"Specialist Principles (choose 2 of 8):","bold":true},{"text":" SP1 Health and Care, SP2 Life Insurance, SP4 Pensions and Other Benefits, SP5 Investment and Finance, SP6 Financial Derivatives, SP7 General Insurance Reserving and Capital Modelling, SP8 General Insurance Pricing, SP9 Enterprise Risk Management."}]},{"text":[{"text":"Specialist Advanced (choose 1, the final exam):","bold":true},{"text":" SA1 Health and Care, SA2 Life Insurance, SA3 General Insurance, SA4 Pensions and Other Benefits, SA7 Investment and Finance."}]},{"text":[{"text":"Fellow","bold":true},{"text":" = 2 SP + 1 SA + "},{"text":"3 years of PPD in total","bold":true},{"text":" (one more year after Associate)."}]}]},{"type":"paragraph","text":[{"text":"Ethics and standards","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Code of Professional Conduct:","bold":true},{"text":" sets out what it means for an actuary to act as a professional; responsibilities to "},{"text":"the public","bold":true},{"text":", to "},{"text":"clients and employers","bold":true},{"text":", and to "},{"text":"the actuarial profession","bold":true},{"text":". It brings accountability, responsibility and trust."}]},{"text":[{"text":"Professionalism:","bold":true},{"text":" professional status, methods, character or standards; adherence to the Code."}]},{"text":[{"text":"Continuing professional development (CPD):","bold":true},{"text":" qualified members keep learning and record it each year to stay competent."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: competing firms are "},{"text":"not","bold":true},{"text":" among the groups the Code protects."}]},{"text":[{"text":"Trap: \"Associate\" needs all Core exams but "},{"text":"no","bold":true},{"text":" Specialist exams; \"Fellow\" adds 2 SP, 1 SA and the third PPD year. CP1 is Core Practices; CM1 and CB2 are Core Principles; SP2 is Specialist."}]},{"text":[{"text":"Tax Auditing is not","bold":true},{"text":" an IFoA Specialist Principles subject."}]},{"text":[{"text":"Skills needed:","bold":true},{"text":" mathematical and analytical skill, project management and problem solving, communication (oral and written), business sense, self-motivation (you pass exams while working), teamwork, creativity and independence."}]}]}]},{"number":"2.6","title":"Specialisations and career outlook","mustKnow":[{"type":"paragraph","text":[{"text":"8 specialisations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"text":[{"text":"Enterprise Risk Management"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Career outlook:","bold":true},{"text":" the "},{"text":"2002 Jobs Rated Almanac","bold":true},{"text":" ranked actuary "},{"text":"number 2","bold":true},{"text":" in America (number 1 biologist, 3 financial planner, 5 accountant, 9 statistician)."}]},{"text":[{"text":"Pay:","bold":true},{"text":" US starting salaries of about 46,000 to 65,000 US dollars (one exam passed, 0 to 0.5 years' experience; base pay only, 2009 survey), rising with merit, with "},{"text":"each exam passed","bold":true},{"text":" and on reaching each designation."}]}]},{"type":"paragraph","text":[{"text":"10 reasons to become an actuary:","bold":true},{"text":" (1) competitive salary and benefits; (2) suits the self-motivated with strong maths and communication; (3) a choice of job offers; (4) earn while you learn; (5) job security through economic cycles; (6) skills transferable across industries; (7) early advancement is largely exam-based, so you control it; (8) dynamic, challenging work; (9) a professional title without being a doctor, lawyer or accountant; (10) continual learning. Also: international opportunities and globally recognised qualifications."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pensions example:","bold":true},{"text":" Ngozi, at an Abuja consulting firm, projects staff salaries and retirement ages and estimates how much to set aside today for future retirement benefits. That is "},{"text":"pensions","bold":true},{"text":" work. If the fund's benefits are ₦500 million due in 10 years and the fund can earn 10% a year, the amount to set aside now is ₦500,000,000 × (1.10)^-10 = ₦192,771,645 (to the nearest naira)."}]},{"text":[{"text":"Health and care prices medical cover (for example HMO premiums); financial derivatives values options; general insurance pricing sets motor and home premiums."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1654 Pascal and Fermat (probability); 1662 Graunt, London Bills (first life table attempt); 1693 Halley, Breslau (annuity price by age)."}]},{"text":[{"text":"1713 Bernoulli (law of large numbers); 1725 de Moivre (uniform mortality plus constant interest)."}]},{"text":[{"text":"Dodson (died 1757) = level premium; 1762 Equitable = first scientific premiums; Mores named the \"actuary\" (once a court clerk); Morgan, actuary 1775 to 1830, father of the profession."}]},{"text":[{"text":"Price's Northampton table overstated mortality, so annuities were too cheap; Gompertz 1825 law of mortality."}]},{"text":[{"text":"Institute 1848; Faculty 1856, charter 1868; IFoA 1 August 2010; SOA 1949; CAS 1914 (named 1921); IAA from 1895 Brussels, association of associations since 1998."}]},{"text":[{"text":"NAS = actuaries; NAICOM (1997 Act) = insurers; PenCom (Pension Reform Act 2004) = pensions."}]},{"text":[{"text":"Student → Associate → Fellow, by exams while working; IFoA Associate needs 2 years PPD, Fellow 3."}]},{"text":[{"text":"Code: duties to the public, clients and employers, and the profession."}]}]}],"theory":{"itemId":"09606d73-a9a7-537f-8892-586f175d7f31","question":[{"type":"paragraph","text":[{"text":"Arrange in time order, earliest first: founding of the Institute of Actuaries; Halley's Breslau table; Graunt's observations; founding of the Equitable Society. Give the year of each."}]}]},"practice":[{"topic":"History and Professional Structure of Actuarial Science","named":false}]}},{"itemId":"0cd5f33d-3cbd-586f-8811-b995c1dbb3b4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"Actuarial Symbols, Notations and Life Tables","body":"The general principles of the international actuarial notation (the four spaces around a symbol); the interest symbols i, i^(m), d, d^(m), v, δ and how they link; the mortality, annuity and assurance letters and their marks; the life table columns l_x, d_x, q_x, p_x and their properties; multi-year probabilities _np_x, _nq_x, m|q_x; survival functions; expectation of life; select and ultimate tables.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The general principles of the international actuarial notation (the four spaces around a symbol); the interest symbols i, i^(m), d, d^(m), v, δ and how they link; the mortality, annuity and assurance letters and their marks; the life table columns l_x, d_x, q_x, p_x and their properties; multi-year probabilities _np_x, _nq_x, m|q_x; survival functions; expectation of life; select and ultimate tables."}],"lessons":[{"number":"3.1","title":"How the international actuarial notation is built","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" based on George King's \"Key to the Notation\"; set out in an explanatory statement adopted "},{"text":"unanimously","bold":true},{"text":" at the "},{"text":"Second International Actuarial Congress, London, May 1898","bold":true},{"text":". Dr Sprague's rearranged statement followed at the "},{"text":"Third Congress, Paris, 1900","bold":true},{"text":" (no real change to the symbols beyond two slight additions). The "},{"text":"Eleventh Congress, Paris, 1937","bold":true},{"text":" appointed a committee (met Brussels 1938 and 1939); the planned 1940 Lucerne adoption was stopped by the war, so the "},{"text":"Institute of Actuaries and the Faculty of Actuaries","bold":true},{"text":" adopted the agreed changes in "},{"text":"1949","bold":true},{"text":", effective from the May 1950 examinations."}]},{"text":[{"text":"General principle:","bold":true},{"text":" each principal (fundamental) letter carries signs in four positions:"}]}]},{"type":"table","header":[[{"text":"Position"}],[{"text":"Reserved for"}],[{"text":"Example"}]],"rows":[[[{"text":"Lower "},{"text":"left","bold":true}],[{"text":"duration","bold":true},{"text":" of the operation and its "},{"text":"position in time","bold":true}],[{"text":"n in _np_x; m| in m|a_x (deferment)"}]],[[{"text":"Lower "},{"text":"right","bold":true}],[{"text":"ages","bold":true},{"text":" of the lives and the "},{"text":"order of succession","bold":true},{"text":" of events"}],[{"text":"x in q_x, l_x, a_x"}]],[[{"text":"Upper "},{"text":"right","bold":true}],[{"text":"periodicity","bold":true},{"text":" (frequency) of events"}],[{"text":"(m) in i^(m), a^(m)_x"}]],[[{"text":"Upper "},{"text":"left","bold":true}],[{"text":"free","bold":true},{"text":": signs for any other notion"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Two conventions:","bold":true},{"text":" (x) in brackets = "},{"text":"a person aged x","bold":true},{"text":". A number in a right angle, n| or 15|, = a "},{"text":"term-certain","bold":true},{"text":" of n years."}]},{"text":[{"text":"Deferment:","bold":true},{"text":" m| in the lower left means \"deferred m years\", e.g. m|a_x = life annuity on (x) deferred m years; m|q_x = probability (x) survives m years then dies in the next year."}]}]},{"type":"paragraph","text":[{"text":"The 1949 changes","bold":true},{"text":" (know them, and know what was "},{"text":"not","bold":true},{"text":" adopted):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"i^(m) replaced j(m) for the nominal rate of interest convertible m times a year (local use of j(m) still allowed)."}]},{"text":[{"text":"ä (trema) adopted for the annuity-due (first payment at once); this allowed the new symbol s̈_n| for the accumulated amount of an annuity-due at the end of the term."}]},{"text":[{"text":"Q (probability of dying within more than 1 year) was dropped."}]},{"text":[{"text":"D introduced in compound symbols for "},{"text":"decreasing","bold":true},{"text":" benefits."}]},{"text":[{"text":"Old commutation-column definitions abolished."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"U for surrender value was NOT adopted","bold":true},{"text":" as an international symbol (only agreed that U should be chosen if a symbol were needed)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In _5p_30 the 5 (lower left) is a duration and the 30 (lower right) an age; in i^(12) the 12 (upper right) is how often interest is convertible."}]},{"text":[{"text":"Trap: options swap \"lower left\" (duration/time) and \"lower right\" (ages/order). Memory aid: "},{"text":"left = length of time, right = the life","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the 1898 Congress was in "},{"text":"London","bold":true},{"text":"; 1900 and 1937 were in "},{"text":"Paris","bold":true},{"text":"; no Lucerne congress took place in 1940."}]}]}]},{"number":"3.2","title":"Interest symbols and their relationships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"i:","bold":true},{"text":" the "},{"text":"effective rate of interest","bold":true},{"text":": the total interest earned on 1 in a year, assuming any interest received more often than yearly is reinvested at once on the same terms as the original principal."}]},{"text":[{"text":"i^(m):","bold":true},{"text":" the "},{"text":"nominal rate of interest convertible m times a year","bold":true},{"text":" (m-thly)."}]},{"text":[{"text":"d:","bold":true},{"text":" the "},{"text":"effective rate of discount","bold":true},{"text":": the discount on 1 due a year hence."}]},{"text":[{"text":"d^(m):","bold":true},{"text":" the "},{"text":"nominal rate of discount convertible m times a year","bold":true},{"text":"."}]},{"text":[{"text":"v:","bold":true},{"text":" the "},{"text":"present value of 1 due a year hence","bold":true},{"text":" (discount factor)."}]},{"text":[{"text":"δ (delta):","bold":true},{"text":" the "},{"text":"force of interest","bold":true},{"text":": the instantaneous rate of growth, like a nominal rate compounded continuously; δ = lim i^(m) as m → ∞."}]}]},{"type":"paragraph","text":[{"text":"Relationships (all equivalent at the same rate):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"v = 1/(1 + i) = (1 + i)^-1"}]},{"text":[{"text":"d = i/(1 + i) = iv = 1 - v"}]},{"text":[{"text":"i = d/(1 - d)"}]},{"text":[{"text":"1 + i = (1 + i^(m)/m)^m, so i^(m) = m[(1 + i)^(1/m) - 1]"}]},{"text":[{"text":"1 - d = (1 - d^(m)/m)^m"}]},{"text":[{"text":"1 + i = e^δ, δ = ln(1 + i), v = e^-δ"}]},{"text":[{"text":"Present value of 1 due in n years = v^n; 1 grows to (1 + i)^n."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example at i = 8% (rounded to 5 decimal places):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"v = 1/1.08 = "},{"text":"0.92593","bold":true}]},{"text":[{"text":"d = 0.08/1.08 = "},{"text":"0.07407","bold":true},{"text":" (check: 1 - v = 0.07407, iv = 0.08 × 0.92593 = 0.07407)"}]},{"text":[{"text":"δ = ln 1.08 = "},{"text":"0.07696","bold":true}]},{"text":[{"text":"i^(12) = 12 × (1.08^(1/12) - 1) = "},{"text":"0.07721","bold":true}]},{"text":[{"text":"v^5 = 1.08^-5 = "},{"text":"0.68058","bold":true},{"text":", so ₦1,000,000 due in 5 years is worth ₦680,583.20 now."}]}]},{"type":"paragraph","text":[{"text":"More conversions:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal i^(4) = 10% convertible quarterly: i = (1 + 0.10/4)^4 - 1 = 1.025^4 - 1 = "},{"text":"0.10381","bold":true},{"text":" (10.381%)."}]},{"text":[{"text":"d = 6%: i = 0.06/0.94 = "},{"text":"0.06383","bold":true},{"text":"."}]},{"text":[{"text":"δ = 0.05: v = e^-0.05 = "},{"text":"0.95123","bold":true},{"text":"."}]},{"text":[{"text":"A Lagos bank quoting \"12% per annum convertible monthly\" is quoting "},{"text":"i^(12) = 0.12","bold":true},{"text":", not i = 0.12 and not δ. Its effective rate is higher: 1.01^12 - 1 = 12.683%."}]},{"text":[{"text":"Ordering at any positive rate: d < d^(m) < δ < i^(m) < i. Discount rates are always smaller than the matching interest rates."}]},{"text":[{"text":"Trap: d (interest) is the discount on 1 due a year hence; d_x (life table) is the number dying."}]}]}]},{"number":"3.3","title":"Mortality, annuity and assurance symbols","mustKnow":[{"type":"paragraph","text":[{"text":"Fundamental letters (mortality tables):","bold":true}]},{"type":"table","header":[[{"text":"Letter"}],[{"text":"Meaning"}],[{"text":"Letter"}],[{"text":"Meaning"}]],"rows":[[[{"text":"l"}],[{"text":"number living"}],[{"text":"a"}],[{"text":"present value of an annuity"}]],[[{"text":"d"}],[{"text":"number dying"}],[{"text":"s"}],[{"text":"amount","bold":true},{"text":" (accumulated value) of an annuity"}]],[[{"text":"p"}],[{"text":"probability of living"}],[{"text":"e"}],[{"text":"expectation of life"}]],[[{"text":"q"}],[{"text":"probability of dying"}],[{"text":"A"}],[{"text":"present value of an assurance"}]],[[{"text":"µ (mu)"}],[{"text":"force of mortality"}],[{"text":"E"}],[{"text":"present value of an endowment"}]],[[{"text":"m"}],[{"text":"central death rate"}],[{"text":"P"}],[{"text":"premium per annum (net premium)"}]],[[{"text":"V"}],[{"text":"policy value"}],[{"text":"W"}],[{"text":"paid-up policy"}]]]},{"type":"paragraph","text":[{"text":"Life-table symbols:","bold":true},{"text":" l_x = number who attain age x; d_x = l_x - l_(x+1) = number who die between x and x + 1; p_x = probability (x) lives 1 year; q_x = probability (x) dies within 1 year; µ_x = force of mortality at age x; m_x = central death rate for the year of age x to x + 1; e_x = "},{"text":"curtate","bold":true},{"text":" expectation of life (average after-lifetime) of (x)."}]},{"type":"paragraph","text":[{"text":"Annuities-certain (term n|):","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}],[{"text":"Formula"}]],"rows":[[[{"text":"a_n|"}],[{"text":"PV of 1 a year for n years, paid at "},{"text":"end","bold":true},{"text":" of each year (annuity-immediate)"}],[{"text":"(1 - v^n)/i"}]],[[{"text":"ä_n|"}],[{"text":"PV of the same, paid at the "},{"text":"beginning","bold":true},{"text":" of each year (annuity-due)"}],[{"text":"(1 - v^n)/d = (1 + i)a_n| = 1 + a_(n-1)|"}]],[[{"text":"s_n|"}],[{"text":"amount","bold":true},{"text":" (accumulated value at end of term), payments at end of year"}],[{"text":"((1 + i)^n - 1)/i"}]],[[{"text":"s̈_n|"}],[{"text":"amount at end of term of the annuity-due"}],[{"text":"(1 + i)s_n|"}]]]},{"type":"paragraph","text":[{"text":"Life contingency symbols on (x):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A_x:","bold":true},{"text":" whole life assurance (paid at end of year of death)."}]},{"text":[{"text":"A^1_x:n|","bold":true},{"text":" (1 over the x): n-year "},{"text":"term","bold":true},{"text":" assurance; pays only if (x) dies within n years."}]},{"text":[{"text":"A_x:n|:","bold":true},{"text":" n-year "},{"text":"endowment assurance","bold":true},{"text":": pays at end of year of death within n years, or at end of n years if (x) is alive."}]},{"text":[{"text":"_nE_x","bold":true},{"text":" (also A_x:n| with 1 over the n|): pure endowment; pays only if (x) survives n years."}]},{"text":[{"text":"a_x:","bold":true},{"text":" whole life annuity, payments at end of each year while (x) lives."}]},{"text":[{"text":"a_x:n|:","bold":true},{"text":" "},{"text":"temporary","bold":true},{"text":" life annuity on (x) for n years. "},{"text":"ä_x:n|:","bold":true},{"text":" the same as an annuity-due."}]}]},{"type":"paragraph","text":[{"text":"Marks on the principal letter:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Bar","bold":true},{"text":" (ā_x, Ā_x): "},{"text":"continuous","bold":true},{"text":" (momently) annuity, or assurance payable at the "},{"text":"moment of death","bold":true},{"text":"."}]},{"text":[{"text":"Small circle","bold":true},{"text":" (e̊_x): "},{"text":"complete","bold":true},{"text":" rather than curtate."}]},{"text":[{"text":"Diaeresis or trema","bold":true},{"text":" (ä, s̈): "},{"text":"acceleration","bold":true},{"text":" of payments (paid at the beginning)."}]},{"text":[{"text":"Square brackets","bold":true},{"text":" on the age, l_[x]+t: "},{"text":"selection","bold":true},{"text":"; selected at age x, t years ago, now aged x + t. a_[x] = annuity on a life now aged x and select now; a_[x-n]+n = annuity on a life now aged x, selected n years ago at age x - n."}]}]},{"type":"paragraph","text":[{"text":"Several lives in the suffix:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Letters with no mark (a_xyz): "},{"text":"joint lives","bold":true},{"text":"; lasts while "},{"text":"all","bold":true},{"text":" survive."}]},{"text":[{"text":"Colon","bold":true},{"text":" (a_x:n|) separates items to avoid confusion with "},{"text":"decimals","bold":true},{"text":" when numbers are involved."}]},{"text":[{"text":"Vertical bar","bold":true},{"text":" (a_y|x): status after the bar follows the one before; "},{"text":"reversionary annuity","bold":true},{"text":" to (x) after the death of (y)."}]},{"text":[{"text":"Horizontal bar over the suffix:","bold":true},{"text":" last "},{"text":"survivor","bold":true},{"text":". A number r above it = "},{"text":"at least r","bold":true},{"text":" survivors; "},{"text":"[r]","bold":true},{"text":" = "},{"text":"exactly r","bold":true},{"text":"; no number = at least one."}]},{"text":[{"text":"Numerals over or under","bold":true},{"text":" a life give the "},{"text":"order of failure","bold":true},{"text":": A^1_xy (1 over x) pays on death of (x) only if (x) dies "},{"text":"first","bold":true},{"text":"; A^2_xyz (2 over x) pays if (x) dies second."}]}]},{"type":"paragraph","text":[{"text":"Premiums and compound symbols:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"P = net premium; "},{"text":"P'","bold":true},{"text":" = a "},{"text":"valuation premium","bold":true},{"text":" other than the net premium (policy value V'); "},{"text":"P''","bold":true},{"text":" = the "},{"text":"office (commercial) premium","bold":true},{"text":" (paid-up policy W''). P^[m] = m-thly premium continuing to the end of the year of death."}]},{"text":[{"text":"(Ia)","bold":true},{"text":" = annuity starting at 1 and "},{"text":"increasing by 1","bold":true},{"text":" a year; (IA) = increasing assurance; "},{"text":"D","bold":true},{"text":" = decreasing (e.g. starting at n, falling by 1 a year); "},{"text":"v","bold":true},{"text":" in (va) = varying."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"e_x and a_x:","bold":true},{"text":" a_x = Σ v^k × _kp_x, and e_x = Σ _kp_x. So e_x is a_x valued at "},{"text":"i = 0","bold":true},{"text":"; likewise e̊_x is ā_x at i = 0."}]},{"text":[{"text":"Nigerian example:","bold":true},{"text":" a 15-year policy for a 35-year-old paying ₦2,000,000 at the end of the year of death within 15 years, or at the end of 15 years if alive, is an endowment assurance: "},{"text":"A_35:15|","bold":true},{"text":". If it paid only on death within 15 years it would be A^1_35:15|; only on survival, _15E_35."}]},{"text":[{"text":"Annuity example","bold":true},{"text":" at i = 8%, n = 5 (rounded to 4 dp): v^5 = 0.68058; a_5| = (1 - 0.68058)/0.08 = "},{"text":"3.9927","bold":true},{"text":"; ä_5| = 1.08 × 3.9927 = "},{"text":"4.3121","bold":true},{"text":" (check: 1 + a_4| = 1 + 3.3121 = 4.3121); s_5| = (1.08^5 - 1)/0.08 = "},{"text":"5.8666","bold":true},{"text":"; s̈_5| = 1.08 × 5.8666 = "},{"text":"6.3359","bold":true},{"text":". So ₦50,000 at the end of each year for 5 years is worth 50,000 × 3.99271 = ₦199,635.50 now; paid at the start of each year, 50,000 × 4.31213 = ₦215,606.34."}]},{"text":[{"text":"Using ä_n| = 1 + a_(n-1)|:","bold":true},{"text":" if a_9| = 7.1078, then ä_10| = 1 + 7.1078 = "},{"text":"8.1078","bold":true},{"text":"."}]},{"text":[{"text":"Trap: s is the "},{"text":"amount","bold":true},{"text":" (accumulated value) of an annuity, never its present value; a is the present value."}]}]}]},{"number":"3.4","title":"The life table and its characteristics","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of death in a population, often measured by the probability that a randomly selected individual would die in some period of time."}]},{"text":[{"text":"Life (mortality) table:","bold":true},{"text":" a table showing, for each age x, how many of a starting group are still alive (l_x) and how many die (d_x), with the probabilities q_x and p_x. It is used for "},{"text":"analysing mortality and survival patterns","bold":true},{"text":"."}]},{"text":[{"text":"Radix:","bold":true},{"text":" the starting number l_0 (or l at the youngest age), a convenient round figure such as 100,000 or 1,000."}]},{"text":[{"text":"Limiting age (ω):","bold":true},{"text":" the age beyond which no one survives; l_ω = 0."}]}]},{"type":"paragraph","text":[{"text":"Formulas:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"d_x = l_x - l_(x+1)"}]},{"text":[{"text":"q_x = d_x/l_x"}]},{"text":[{"text":"p_x = l_(x+1)/l_x = 1 - q_x"}]},{"text":[{"text":"p_x + q_x = 1"}]},{"text":[{"text":"l_(x+1) = l_x × p_x = l_x × (1 - q_x); d_x = l_x × q_x"}]},{"text":[{"text":"Expected survivors or deaths in a group = group size × probability."}]}]},{"type":"paragraph","text":[{"text":"Characteristics of a standard life table:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"l_x "},{"text":"decreases","bold":true},{"text":" (never increases) as age rises."}]},{"text":[{"text":"d_x = l_x - l_(x+1) at every age."}]},{"text":[{"text":"p_x + q_x = 1 at every age; both lie between 0 and 1."}]},{"text":[{"text":"The sum of d_x from age x to the end of the table equals l_x (everyone eventually dies)."}]},{"text":[{"text":"It starts from a radix and ends at the limiting age."}]}]},{"type":"paragraph","text":[{"text":"Select and ultimate:","bold":true},{"text":" newly accepted (medically selected) lives die at lower rates than others of the same age. A "},{"text":"select table","bold":true},{"text":" shows mortality by age at selection [x] and duration since selection; after the "},{"text":"select period","bold":true},{"text":" the effect wears off and "},{"text":"ultimate","bold":true},{"text":" rates (depending on attained age only) apply. A table without selection is an aggregate table. "},{"text":"Selection","bold":true},{"text":" is also the process by which an insurer decides whether to accept a risk and which set of probabilities to assign it."}]},{"type":"paragraph","text":[{"text":"Uses:","bold":true},{"text":" pricing life assurance and annuities (premiums), reserves and policy values, pension and social security costs, demographic study of a population."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Construction:","bold":true},{"text":" observe a large group (a national population from census and death registration, or an insurer's own policyholders), count exposed lives and deaths at each age to get crude q_x, smooth them (graduation), then start from the radix and apply l_(x+1) = l_x × (1 - q_x)."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" a 2022 review of the Nigerian actuarial market noted there are "},{"text":"no local actuarial tables","bold":true},{"text":". Nigerian life insurers (supervised by NAICOM) and pension schemes (supervised by PenCom) therefore base their q_x and l_x on tables built from "},{"text":"other populations","bold":true},{"text":"."}]},{"text":[{"text":"The actuary pricing a one-year term assurance for a 45-year-old needs "},{"text":"q_45","bold":true},{"text":" directly."}]},{"text":[{"text":"Trap: l_x is the "},{"text":"number alive at exact age x","bold":true},{"text":", not a probability and not the number dying."}]}]}]},{"number":"3.5","title":"Worked life table and multi-year probabilities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"_np_x","bold":true},{"text":" (often printed npx or 3p50): probability (x) survives n years = l_(x+n)/l_x."}]},{"text":[{"text":"_nq_x:","bold":true},{"text":" probability (x) dies within n years = 1 - _np_x = (l_x - l_(x+n))/l_x."}]},{"text":[{"text":"m|q_x:","bold":true},{"text":" (x) survives m years then dies in the next year = d_(x+m)/l_x = (l_(x+m) - l_(x+m+1))/l_x."}]},{"text":[{"text":"m|nq_x:","bold":true},{"text":" (x) survives m years then dies within the next n years = (l_(x+m) - l_(x+m+n))/l_x."}]},{"text":[{"text":"Chain rule:","bold":true},{"text":" _np_x = p_x × p_(x+1) × ... × p_(x+n-1) = (1 - q_x)(1 - q_(x+1))...(1 - q_(x+n-1))."}]},{"text":[{"text":"Deaths between x and x + n = l_x - l_(x+n) = d_x + d_(x+1) + ... + d_(x+n-1)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example","bold":true},{"text":" (probabilities rounded to 5 dp):"}]},{"type":"table","header":[[{"text":"x"}],[{"text":"l_x"}],[{"text":"d_x = l_x - l_(x+1)"}],[{"text":"q_x = d_x/l_x"}],[{"text":"p_x = l_(x+1)/l_x"}]],"rows":[[[{"text":"30"}],[{"text":"95,000"}],[{"text":"190"}],[{"text":"0.00200"}],[{"text":"0.99800"}]],[[{"text":"31"}],[{"text":"94,810"}],[{"text":"200"}],[{"text":"0.00211"}],[{"text":"0.99789"}]],[[{"text":"32"}],[{"text":"94,610"}],[{"text":"215"}],[{"text":"0.00227"}],[{"text":"0.99773"}]],[[{"text":"33"}],[{"text":"94,395"}],[{"text":"235"}],[{"text":"0.00249"}],[{"text":"0.99751"}]],[[{"text":"34"}],[{"text":"94,160"}],[{"text":"260"}],[{"text":"0.00276"}],[{"text":"0.99724"}]],[[{"text":"35"}],[{"text":"93,900"}],[],[],[]]]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"_3p_30 = l_33/l_30 = 94,395/95,000 = "},{"text":"0.99363","bold":true},{"text":"."}]},{"text":[{"text":"_5p_30 = 93,900/95,000 = "},{"text":"0.98842","bold":true},{"text":"; _5q_30 = 1 - 0.98842 = 0.01158. Check: 190 + 200 + 215 + 235 + 260 = 1,100 = 95,000 - 93,900."}]},{"text":[{"text":"_2q_31 = 1 - l_33/l_31 = 1 - 94,395/94,810 = 415/94,810 = "},{"text":"0.00438","bold":true},{"text":"."}]},{"text":[{"text":"2|q_30 = d_32/l_30 = 215/95,000 = "},{"text":"0.00226","bold":true},{"text":"."}]},{"text":[{"text":"1|2q_30 = (l_31 - l_33)/l_30 = (94,810 - 94,395)/95,000 = 415/95,000 = "},{"text":"0.00437","bold":true},{"text":". Note the divisor is l_30, not l_31: that is why it differs from _2q_31."}]},{"text":[{"text":"500 lives aged exactly 30: expected alive at 35 = 500 × 0.988421 = "},{"text":"494.21","bold":true},{"text":", about 494."}]},{"text":[{"text":"A Lagos insurer covers 2,000 lives aged 32, each for ₦1,000,000 for one year: expected deaths = 2,000 × 215/94,610 = "},{"text":"4.54","bold":true},{"text":"; expected claims = 4.54497 × ₦1,000,000 ≈ "},{"text":"₦4,544,974","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Building a table from q_x:","bold":true},{"text":" radix l_50 = 20,000, q_50 = 0.010, q_51 = 0.012, q_52 = 0.015."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"d_50 = 20,000 × 0.010 = 200; l_51 = 19,800."}]},{"text":[{"text":"d_51 = 19,800 × 0.012 = 237.6; l_52 = 19,562.4."}]},{"text":[{"text":"d_52 = 19,562.4 × 0.015 = 293.436; l_53 = "},{"text":"19,268.964","bold":true},{"text":" (19,268.96 to 2 dp)."}]},{"text":[{"text":"_3p_50 = 0.990 × 0.988 × 0.985 = "},{"text":"0.96345","bold":true},{"text":" = 19,268.964/20,000. Check: _3q_50 = 0.03655."}]},{"text":[{"text":"From d_x alone: if l_70 = 5,000 and d_70, d_71, d_72 are given, l_73 = 5,000 - (d_70 + d_71 + d_72); then q_71 = d_71/l_71 with l_71 = 5,000 - d_70."}]},{"text":[{"text":"Trap: _nq_x is "},{"text":"not","bold":true},{"text":" the sum of the q's, and _np_x is "},{"text":"not","bold":true},{"text":" l_(x+n) alone. Always divide by l at the "},{"text":"starting","bold":true},{"text":" age."}]}]}]},{"number":"3.6","title":"Survival functions and expectation of life","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Survival function s(x):","bold":true},{"text":" probability a newborn survives to age x; s(x) = l_x/l_0, s(0) = 1, falls to 0 at the limiting age."}]},{"text":[{"text":"l_x = l_0 × s(x)."}]},{"text":[{"text":"_np_x = s(x + n)/s(x); _nq_x = 1 - s(x + n)/s(x)."}]},{"text":[{"text":"Probability a "},{"text":"newborn","bold":true},{"text":" dies between ages a and b = s(a) - s(b)."}]},{"text":[{"text":"Curtate expectation of life:","bold":true},{"text":" e_x = (l_(x+1) + l_(x+2) + ... )/l_x = Σ _kp_x (k = 1, 2, ...): average number of "},{"text":"complete","bold":true},{"text":" future years lived by (x)."}]},{"text":[{"text":"Complete expectation of life e̊_x:","bold":true},{"text":" average total future lifetime including fractions; approximately e̊_x ≈ e_x + 0.5 (deaths spread evenly over each year)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example:","bold":true},{"text":" s(x) = 1 - x/100, 0 ≤ x ≤ 100."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Newborn survives to 25: s(25) = 1 - 0.25 = "},{"text":"0.75","bold":true},{"text":"."}]},{"text":[{"text":"_25p_40 = s(65)/s(40) = 0.35/0.60 = "},{"text":"0.5833","bold":true},{"text":" (4 dp)."}]},{"text":[{"text":"_30q_40 = 1 - s(70)/s(40) = 1 - 0.30/0.60 = "},{"text":"0.50","bold":true},{"text":"."}]},{"text":[{"text":"Newborn dies between 20 and 50: s(20) - s(50) = 0.80 - 0.50 = "},{"text":"0.30","bold":true},{"text":"."}]},{"text":[{"text":"Radix l_0 = 10,000: l_60 = 10,000 × 0.40 = "},{"text":"4,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Square-root example:","bold":true},{"text":" s(x) = √(1 - x/100). s(19) = √0.81 = 0.9; s(51) = √0.49 = 0.7; a life aged 19 survives to 51 with probability 0.7/0.9 = 7/9 = "},{"text":"0.7778","bold":true},{"text":". The same method works for any s(x), such as (1 - x/100)^2: divide s at the later age by s at the current age."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"a life aged 0 dies between 16 and 43\" uses s(16) - s(43); \"a life aged 16 survives to 43\" uses s(43)/s(16). Watch who the life is now."}]}]},{"type":"paragraph","text":[{"text":"Expectation example:","bold":true},{"text":" l_90 = 500, l_91 = 300, l_92 = 150, l_93 = 60, l_94 = 15, l_95 = 0."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"e_90 = (300 + 150 + 60 + 15)/500 = 525/500 = "},{"text":"1.05","bold":true},{"text":" years."}]},{"text":[{"text":"e_92 = (60 + 15)/150 = "},{"text":"0.50","bold":true},{"text":" years."}]},{"text":[{"text":"e̊_90 ≈ 1.05 + 0.5 = "},{"text":"1.55","bold":true},{"text":" years."}]},{"text":[{"text":"Trap: the sum starts at l_(x+1), "},{"text":"not","bold":true},{"text":" l_x. Including l_x adds exactly 1."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corners of a symbol: lower left = duration/time (and deferment m|), lower right = ages and order, upper right = periodicity, upper left = free. (x) = a person aged x; n| = term-certain."}]},{"text":[{"text":"Adopted London 1898; revised 1949 (i^(m), ä and s̈, D, Q dropped); U not adopted."}]},{"text":[{"text":"v = 1/(1 + i), d = iv = 1 - v, i = d/(1 - d), 1 + i = (1 + i^(m)/m)^m = e^δ."}]},{"text":[{"text":"a = PV of annuity, s = amount, A = assurance, E = endowment, P' valuation premium, P'' office premium, W paid-up."}]},{"text":[{"text":"Bar = continuous, circle = complete, trema = acceleration (due), [x] = select."}]},{"text":[{"text":"A_x whole life, A^1_x:n| term, A_x:n| endowment assurance, a_x:n| temporary annuity, ä_x:n| its annuity-due."}]},{"text":[{"text":"d_x = l_x - l_(x+1); q_x = d_x/l_x; p_x = 1 - q_x; l_x always falls; radix = l_0."}]},{"text":[{"text":"_np_x = l_(x+n)/l_x; m|q_x = d_(x+m)/l_x; s(x) = l_x/l_0."}]},{"text":[{"text":"e_x = (l_(x+1) + l_(x+2) + ...)/l_x = a_x at i = 0; e̊_x ≈ e_x + 0.5."}]},{"text":[{"text":"Nigeria has no local actuarial tables; insurers rely on foreign-population tables."}]}]}],"theory":{"itemId":"91ec30ca-0cb2-5a01-be7f-30fc2372ece4","question":[{"type":"paragraph","text":[{"text":"In a life table l_40 = 90,000, q_40 = 0.003 and q_41 = 0.004. Find l_41, d_41, l_42 and _2p_40."}]}]},"practice":[{"topic":"Actuarial Symbols, Notations and Life Tables","named":false}]}},{"itemId":"9a105d12-37e6-5be3-b0d1-70ac3d7c1996","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Actuarial Science, Insurance and the Role of Actuaries in Society","body":"What actuaries do for insurers and for society; the key insurance ideas (pooling, underwriting, hazards, reinsurance, risk management); pricing, reserving and solvency with their simple calculations; the branches, products and pension arrangements actuaries work on; where actuaries work and their career choices.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What actuaries do for insurers and for society; the key insurance ideas (pooling, underwriting, hazards, reinsurance, risk management); pricing, reserving and solvency with their simple calculations; the branches, products and pension arrangements actuaries work on; where actuaries work and their career choices."}],"lessons":[{"number":"4.1","title":"What actuaries do for insurers and for society","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science:","bold":true},{"text":" deals with evaluating risks and maintaining the economic stability of insurance or financial organisations, using "},{"text":"mathematics, statistics and probability","bold":true},{"text":" to anticipate future events and take preventive measures."}]},{"text":[{"text":"An actuary","bold":true},{"text":" analyses, manages and measures the financial implications of future risk; develops and validates financial models to guide decisions; and is the analytical backbone of society's financial security programmes (insurance, social security, pensions)."}]},{"text":[{"text":"Method:","bold":true},{"text":" analyse "},{"text":"past data","bold":true},{"text":", identify a "},{"text":"trend","bold":true},{"text":", predict the future, then decide how much money to set aside for future losses. Using the past is like \"driving a car by looking in the rear-view mirror\", so the actuary must also "},{"text":"quantify how the future will be different from the past","bold":true},{"text":" (e.g. the effect of a big rise in petrol prices on motor insurance costs)."}]},{"text":[{"text":"Main challenge:","bold":true},{"text":" when there is "},{"text":"no past data","bold":true},{"text":", or the data is no longer relevant because of policy or other changes (e.g. a brand-new product)."}]}]},{"type":"paragraph","text":[{"text":"What actuaries do (list):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluate the likelihood of future events:","bold":true},{"text":" forecast the impact of catastrophes; calculate the expected lifetime of a retiree on a pension."}]},{"text":[{"text":"Design creative ways to reduce the likelihood of undesirable events:","bold":true},{"text":" life insurance policies, annuities, promoting safety (seat belts)."}]},{"text":[{"text":"Decrease the impact of undesirable events that do occur:","bold":true},{"text":" death benefits, retirement benefits, indemnity benefits."}]},{"text":[{"text":"Participate in corporate planning:","bold":true},{"text":" mergers and acquisitions; evaluating investment programmes."}]},{"text":[{"text":"Help insurance companies:","bold":true},{"text":" calculate rates for new insurance products; forecast and interpret underwriting results; maintain databases suited to the analysis of pricing issues."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Typical areas of actuarial work:","bold":true},{"text":" insurance (general, health, life); finance (banking, corporate, investment, pensions); data science and analytics; technology; enterprise risk; resource and environment ("},{"text":"climate change","bold":true},{"text":")."}]},{"text":[{"text":"Where else actuaries add value:","bold":true},{"text":" supporting "},{"text":"marketing teams by modelling demand","bold":true},{"text":" for a new product; supporting accounting teams with models; budgeting and forecasting; product development; managing risk."}]},{"text":[{"text":"In digital ecosystems:","bold":true},{"text":" expertise in "},{"text":"predictive modelling and optimisation","bold":true},{"text":" for quicker, smarter business risk decisions."}]}]},{"type":"table","header":[[],[{"text":"Actuary"}],[{"text":"Accountant"}],[{"text":"CFA charterholder"}]],"rows":[[[{"text":"Focus"}],[{"text":"Future events that may or may not occur"}],[{"text":"Events that have already happened"}],[{"text":"Financial reports and investments"}]],[[{"text":"Assets/liabilities"}],[{"text":"Both; "},{"text":"uniquely trained to understand liabilities","bold":true},{"text":" (they are complicated)"}],[{"text":"Reports on both"}],[{"text":"Geared towards "},{"text":"assets","bold":true}]],[[{"text":"Products"}],[{"text":"How products make money"}],[{"text":"Cost, revenue, profit"}],[{"text":"Which products or companies to "},{"text":"invest in","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lagos example:","bold":true},{"text":" to predict crashes next November, the actuary studies the percentage of people in accidents in previous years, finds a trend, then "},{"text":"establishes how much each person should pay","bold":true},{"text":" so premiums cover the damages."}]},{"text":[{"text":"A death benefit paid to a family "},{"text":"decreases the impact","italic":true},{"text":" of an event that has happened; a seat-belt campaign "},{"text":"reduces the likelihood or effect","italic":true},{"text":" of the event. Exams swap these two."}]},{"text":[{"text":"Valuing an insurer's long-term liabilities before a bank buys it is "},{"text":"corporate planning (mergers and acquisitions)","bold":true},{"text":"."}]},{"text":[{"text":"Actuaries do "},{"text":"not","bold":true},{"text":" decide court cases, sell door to door or repair vehicles."}]}]}]},{"number":"4.2","title":"Core insurance ideas","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Insurance company:","bold":true},{"text":" an institution that, by contract, binds itself to "},{"text":"indemnify","bold":true},{"text":" another party against specified loss in return for premiums. "},{"text":"Indemnity:","bold":true},{"text":" compensation for damages or loss."}]},{"text":[{"text":"Financial security system:","bold":true},{"text":" an arrangement in which one person takes on the obligation to provide benefits to offset undesirable economic consequences suffered by a second person, in return for payments called "},{"text":"considerations","bold":true},{"text":" (e.g. insurance products, retirement plans). It is "},{"text":"mandatory","bold":true},{"text":" if everyone in the group must take part; otherwise "},{"text":"voluntary","bold":true},{"text":"."}]},{"text":[{"text":"Insurable risk","bold":true},{"text":" criteria: (1) a potential loss; (2) that is significant; (3) loss and its economic value well defined and out of the policyholder's complete control; (4) covered losses reasonably independent. The risk must not be so large that no insurer could pay."}]},{"text":[{"text":"Peril:","bold":true},{"text":" the cause of loss (fire, flood, theft) against which cover is bought. "},{"text":"Hazard:","bold":true},{"text":" a condition that increases the probability or size of a loss."}]},{"text":[{"text":"Moral hazard:","bold":true},{"text":" an insured takes more risk knowing he will be compensated. "},{"text":"Adverse selection (antiselection):","bold":true},{"text":" people with above-average likelihood of loss are more likely to apply for or keep insurance."}]},{"text":[{"text":"Pooling:","bold":true},{"text":" forming a group of policies with similar characteristics (e.g. group size, benefit structure) to protect the insurer, based on the "},{"text":"law of large numbers","bold":true},{"text":": the larger and more homogeneous the group, the more certain the predictions. "},{"text":"Risk pool:","bold":true},{"text":" such a group of policies. "},{"text":"Risk subject:","bold":true},{"text":" the person or object involved in the insured event."}]},{"text":[{"text":"Underwriting:","bold":true},{"text":" the process by which an insurer decides "},{"text":"which people to accept and on what terms","bold":true},{"text":". "},{"text":"Underwriting factors:","bold":true},{"text":" what the insurer considers before issuing a policy and setting the premium (age, health history, occupation)."}]},{"text":[{"text":"Risk classification:","bold":true},{"text":" grouping insureds with similar underwriting factors so each group pays a fair premium."}]},{"text":[{"text":"Reinsurance:","bold":true},{"text":" another licensed (re)insurer agrees to cover all or part of a primary insurer's losses for a premium. "},{"text":"Catastrophe reinsurance:","bold":true},{"text":" pays when losses from a "},{"text":"single event","bold":true},{"text":" exceed the buyer's retention."}]},{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of "},{"text":"death","bold":true},{"text":" in a population. "},{"text":"Morbidity:","bold":true},{"text":" the rate of "},{"text":"disease","bold":true},{"text":"."}]},{"text":[{"text":"Frequency distribution:","bold":true},{"text":" how "},{"text":"many","bold":true},{"text":" claims occur. "},{"text":"Severity distribution:","bold":true},{"text":" how "},{"text":"large","bold":true},{"text":" each claim is."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying and assessing risk, then developing strategies to minimise, monitor and control it. "},{"text":"Ideal prioritisation:","bold":true},{"text":" greatest loss "},{"text":"and","bold":true},{"text":" greatest probability first; lower loss and lower probability later."}]},{"text":[{"text":"Risk management system","bold":true},{"text":" activities: risk identification, risk assessment, risk control, risk reporting and monitoring, risk financing. (\"Risk concealment\" is not one.)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fire vs petrol:","bold":true},{"text":" an Onitsha shop insured against fire stores petrol beside wiring. Fire = "},{"text":"peril","bold":true},{"text":"; the stored petrol = "},{"text":"hazard","bold":true},{"text":"."}]},{"text":[{"text":"Leaving an insured car unlocked","bold":true},{"text":" = moral hazard (behaviour changes "},{"text":"after","italic":true},{"text":" cover). "},{"text":"More sick people applying for a flat-premium health plan","bold":true},{"text":" = adverse selection (who joins)."}]},{"text":[{"text":"Law of large numbers:","bold":true},{"text":" 5,000 similar traders give far more reliable predictions than 20; size and similarity, not honesty, matter."}]},{"text":[{"text":"A state that requires every employee to join its health scheme runs a "},{"text":"mandatory","bold":true},{"text":" system; a club where joining is optional runs a "},{"text":"voluntary","bold":true},{"text":" one."}]},{"text":[{"text":"Risks ranked (I) high loss, high probability; (II) low, low; (III) high loss, low probability; (IV) low loss, high probability: handle "},{"text":"I first","bold":true},{"text":", II last."}]}]}]},{"number":"4.3","title":"Pricing, reserving and solvency","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial pricing:","bold":true},{"text":" pricing risk on probabilities of loss occurrence, to develop premiums that cover losses from underwritten risks and future benefits."}]},{"text":[{"text":"Expected claim cost per policy = probability of claim × average claim"}]},{"text":[{"text":"Expected total claims = number of policies × probability × average claim"}]},{"text":[{"text":"Premium with loading = expected claim cost × (1 + loading %)"}]},{"text":[{"text":"Gross (office) premium","bold":true},{"text":" components: (1) risk premium; (2) commission; (3) allowance for other expenses; (4) allowance for premium tax; (5) profit loading. Surrender value is "},{"text":"not","bold":true},{"text":" a part."}]},{"text":[{"text":"Reserves","bold":true},{"text":" (life insurance): money held to cover "},{"text":"future policyholder benefits and claims","bold":true},{"text":" on policies already sold."}]},{"text":[{"text":"IBNR reserve:","bold":true},{"text":" estimate owed for covered losses that have occurred but "},{"text":"not yet been reported","bold":true},{"text":"."}]},{"text":[{"text":"Earned premium:","bold":true},{"text":" the part for cover already given. "},{"text":"Unearned premium:","bold":true},{"text":" premium paid for cover "},{"text":"not yet provided","bold":true},{"text":"; held in the "},{"text":"unearned premium reserve (UPR)","bold":true},{"text":"."}]},{"text":[{"text":"Unearned premium = annual premium × months of cover remaining / 12"}]},{"text":[{"text":"Loss ratio = claims incurred / premiums earned"}]},{"text":[{"text":"Solvency:","bold":true},{"text":" assets greater than the sum of debt obligations. Solvency margin = assets − liabilities"}]},{"text":[{"text":"Risk-based capital (RBC):","bold":true},{"text":" theoretical capital needed to absorb a business's risks so that it has an acceptably low chance of insolvency. "},{"text":"Capital requirement:","bold":true},{"text":" capital a bank or financial institution must hold as set by its regulator."}]},{"text":[{"text":"Experience rating:","bold":true},{"text":" adjusting a client's premium using the part of its own claims experience judged credible. "},{"text":"Credibility:","bold":true},{"text":" the relative weight given to one of two or more estimates (e.g. the group's own data versus manual rates)."}]}]},{"type":"table","header":[[{"text":"Actuary"}],[{"text":"Main job"}]],"rows":[[[{"text":"Pricing actuary","bold":true}],[{"text":"Sets the premium: decides the appropriate \"just a little more\" (loading) and validates the expected number and amount of claims"}]],[[{"text":"Valuation actuary","bold":true}],[{"text":"Calculates reserves (liabilities) for policies already sold"}]],[[{"text":"Pension actuary","bold":true}],[{"text":"Projects members' benefits from ages and salaries, allowing for leavers and pay rises"}]],[[{"text":"Consulting actuary","bold":true}],[{"text":"Advises client organisations from outside, often on pensions"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Simulation:","bold":true},{"text":" used to "},{"text":"model potential outcomes under uncertainty","bold":true},{"text":". A "},{"text":"single projection","bold":true},{"text":" uses one set of assumptions, so it "},{"text":"may not capture the full range of scenarios","bold":true},{"text":". Extra scenarios show the "},{"text":"range of outcomes under different conditions","bold":true},{"text":". The "},{"text":"mean","bold":true},{"text":" measures central tendency of the output; range, variance and standard deviation measure spread."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (pricing).","italic":true},{"text":" An insurer covers 1,000 keke drivers. Probability of a claim = 0.05, average claim = ₦300,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expected cost per driver = 0.05 × ₦300,000 = "},{"text":"₦15,000","bold":true},{"text":"."}]},{"text":[{"text":"Expected total claims = 1,000 × ₦15,000 = "},{"text":"₦15,000,000","bold":true},{"text":"."}]},{"text":[{"text":"With a 25% loading: ₦15,000 × 1.25 = "},{"text":"₦18,750","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the total (₦15,000,000) or the loading alone (₦3,750) appear as wrong options."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (unearned premium).","italic":true},{"text":" Premium ₦240,000 paid on 1 April 2025 for 12 months; year-end 31 December 2025."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Months elapsed = 9 (April to December). Earned = ₦240,000 × 9/12 = ₦180,000."}]},{"text":[{"text":"Months remaining = 3. Unearned = ₦240,000 × 3/12 = "},{"text":"₦60,000","bold":true},{"text":"."}]},{"text":[{"text":"Count the months "},{"text":"left","italic":true},{"text":", not the months gone."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (loss ratio and solvency).","italic":true},{"text":" Claims incurred ₦30m, premiums earned ₦48m: loss ratio = 30/48 = "},{"text":"62.5%","bold":true},{"text":". Assets ₦5.0bn, liabilities ₦4.2bn: solvency margin = "},{"text":"₦0.8bn","bold":true},{"text":" (solvent, since assets exceed liabilities). Never divide premiums by claims."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"IBNR case:","bold":true},{"text":" floods on 29 December, year-end 31 December, losses not yet reported: the provision is IBNR, not UPR."}]},{"text":[{"text":"Ten years of reliable bank data earns high "},{"text":"credibility","bold":true},{"text":"; a tiny start-up relies on manual rates."}]}]}]},{"number":"4.4","title":"Branches, products and where actuaries work","mustKnow":[{"type":"paragraph","text":[{"text":"8 specialisations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"text":[{"text":"Enterprise Risk Management"}]}]},{"type":"paragraph","text":[{"text":"Most common industries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insurance:","bold":true},{"text":" property (home) and casualty (auto); life and annuities."}]},{"text":[{"text":"Employee benefits:","bold":true},{"text":" retirement benefits, health benefits, social security."}]},{"text":[{"text":"Financial services:","bold":true},{"text":" banks, investing, risk management, mergers and acquisitions."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuaries are largely employed by "},{"text":"insurance companies and consulting firms","bold":true},{"text":", in: life, annuities and mutual funds; health; pensions; property and casualty."}]},{"text":[{"text":"Life insurance:","bold":true},{"text":" term and permanent products giving "},{"text":"death benefit protection","bold":true},{"text":"."}]},{"text":[{"text":"Annuity:","bold":true},{"text":" fixed or variable products; customer pays a lump sum or series of payments now for "},{"text":"periodic payments beginning immediately or in the future","bold":true},{"text":"."}]},{"text":[{"text":"Mutual fund:","bold":true},{"text":" "},{"text":"pools the assets of multiple investors","bold":true},{"text":" and buys securities towards a common, pre-defined goal."}]},{"text":[{"text":"Pension:","bold":true},{"text":" "},{"text":"steady income","bold":true},{"text":", typically a guaranteed annuity, to a "},{"text":"retired or disabled employee","bold":true},{"text":" under legal or contractual terms."}]},{"text":[{"text":"Term life:","bold":true},{"text":" pays only if death occurs within a set period. "},{"text":"Whole life:","bold":true},{"text":" set death benefit, level premium, guaranteed cash values. "},{"text":"Key person insurance:","bold":true},{"text":" life cover on a key employee or owner; the "},{"text":"business is the beneficiary","bold":true},{"text":"."}]},{"text":[{"text":"Casualty insurance:","bold":true},{"text":" broad non-life, non-health cover against loss of property, damage or liabilities (motor, liability, theft)."}]},{"text":[{"text":"Lapse:","bold":true},{"text":" policy ends because the renewal premium is not paid within the grace period. "},{"text":"Surrender value:","bold":true},{"text":" what the policyholder receives on choosing to stop the policy."}]},{"text":[{"text":"Health segments (employers):","bold":true},{"text":" small group 2 to 50 employees; middle market 51 to 3,000; national accounts 3,001+."}]}]},{"type":"paragraph","text":[{"text":"Typical projects:","bold":true}]},{"type":"table","header":[[{"text":"Area"}],[{"text":"Project"}]],"rows":[[[{"text":"Life insurance"}],[{"text":"Designing and pricing products; impact of a disease (e.g. AIDS) on mortality tables"}]],[[{"text":"Property and casualty"}],[{"text":"Cost of personal auto or homeowners cover in an area; impact of global warming"}]],[[{"text":"Health benefits"}],[{"text":"Setting HMO premium rates"}]],[[{"text":"Retirement systems"}],[{"text":"Pricing the cost of increasing retirement benefits"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Branch by task:","bold":true},{"text":" 10-year term assurance priced on mortality = "},{"text":"life actuary","bold":true},{"text":"; HMO premiums for employers = "},{"text":"health actuary","bold":true},{"text":"; employer's yearly payments into a DB scheme = "},{"text":"pension actuary","bold":true},{"text":"; matching assets to annuity payment timing = "},{"text":"investment actuary","bold":true},{"text":"; reserves for motor and fire claims not yet settled = "},{"text":"general insurance reserving","bold":true},{"text":"."}]},{"text":[{"text":"Motor insurance on a commercial bus is "},{"text":"general (non-life)","bold":true},{"text":"; whole life, term life and annuities are life business."}]},{"text":[{"text":"A company with 120 staff is "},{"text":"middle market","bold":true},{"text":"."}]},{"text":[{"text":"A retiree paying ₦10,000,000 once for monthly income for life has bought an "},{"text":"annuity","bold":true},{"text":"."}]}]}]},{"number":"4.5","title":"Pensions, social security and government","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Defined benefit (DB):","bold":true},{"text":" benefit set by scheme rules from "},{"text":"pay, years of service, age at retirement","bold":true},{"text":", independently of contributions; the "},{"text":"employer","bold":true},{"text":" bears the investment risk."}]},{"text":[{"text":"Defined contribution (DC):","bold":true},{"text":" benefit depends on contributions paid plus investment return; the "},{"text":"employee","bold":true},{"text":" bears the investment risk."}]},{"text":[{"text":"DB pension = accrual rate × years of service × final salary"}]},{"text":[{"text":"DC yearly payment in = (employee + employer monthly contribution) × 12"}]},{"text":[{"text":"Pay-as-you-go:","bold":true},{"text":" benefits paid out of current revenue, with "},{"text":"no funding","bold":true},{"text":" for future liabilities."}]},{"text":[{"text":"Funding objective:","bold":true},{"text":" assesses the level of funding a pension plan needs to provide its members' benefits."}]},{"text":[{"text":"Active member:","bold":true},{"text":" still contributing and building benefits. "},{"text":"Deferred member:","bold":true},{"text":" has left before pension age with preserved benefits paid at retirement."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" the "},{"text":"Contributory Pension Scheme","bold":true},{"text":" (Pension Reform Act 2014) is "},{"text":"DC","bold":true},{"text":": each worker has a "},{"text":"Retirement Savings Account (RSA)","bold":true},{"text":"; minimum contributions are 8% (employee) and 10% (employer) of monthly emoluments. It is regulated by "},{"text":"PenCom","bold":true},{"text":". Insurance is regulated by "},{"text":"NAICOM","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Roles in government, social security, banking and regulation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Costing social security and public-service pensions (e.g. a 10% rise in civil servants' benefits = "},{"text":"retirement systems","bold":true},{"text":" work)."}]},{"text":[{"text":"Supporting the regulator ("},{"text":"NAICOM","bold":true},{"text":") in setting and reviewing "},{"text":"capital and reserving requirements","bold":true},{"text":"."}]},{"text":[{"text":"In banking, measuring the risks behind regulatory "},{"text":"capital requirements","bold":true},{"text":"."}]},{"text":[{"text":"Measuring insurance liabilities under "},{"text":"IFRS 17","bold":true},{"text":", which "},{"text":"increases demand","bold":true},{"text":" for actuaries."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (DB).","italic":true},{"text":" Accrual 1.5% per year, 30 years' service, final salary ₦3,600,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Pension = 0.015 × 30 × ₦3,600,000 = "},{"text":"₦1,620,000 a year","bold":true},{"text":"."}]},{"text":[{"text":"Trap: forgetting years of service gives ₦54,000."}]}]},{"type":"paragraph","text":[{"text":"Worked example 5 (DC).","italic":true},{"text":" Monthly pay ₦300,000; employee 8% = ₦24,000; employer 10% = ₦30,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Monthly total = ₦54,000; yearly = ₦54,000 × 12 = "},{"text":"₦648,000","bold":true},{"text":" (ignoring returns and charges)."}]},{"text":[{"text":"Trap: giving only one month, or only one side's contribution."}]},{"text":[{"text":"Nigeria (2022):","bold":true},{"text":" few qualified actuaries (about 19 Fellows) against 56 insurers, no local actuarial tables, and plans for risk-based capital and IFRS 17: demand exceeds supply."}]}]}]},{"number":"4.6","title":"Career choices for an actuary","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 main bodies:","bold":true},{"text":" "},{"text":"Institute and Faculty of Actuaries (IFoA)","bold":true},{"text":", "},{"text":"Society of Actuaries (SOA)","bold":true},{"text":", "},{"text":"Casualty Actuarial Society (CAS)","bold":true},{"text":". ASSA (South Africa) is another."}]},{"text":[{"text":"CAS covers property and casualty (general) only","bold":true},{"text":"; SOA covers life, pensions and health; IFoA and ASSA cover all four."}]},{"text":[{"text":"Two levels","bold":true},{"text":" (SOA, CAS): "},{"text":"Associate","bold":true},{"text":" (ASA, ACAS) first, then "},{"text":"Fellow","bold":true},{"text":" (FSA, FCAS); both by examinations taken while working."}]},{"text":[{"text":"IFoA specialist principles:","bold":true},{"text":" SP1 Health and Care; SP2 Life Insurance; SP4 Pensions and Other Benefits; SP5 Investment and Finance; SP6 Financial Derivatives; "},{"text":"SP7 General Insurance Reserving and Capital Modelling","bold":true},{"text":"; SP8 General Insurance Pricing; SP9 Enterprise Risk Management."}]}]},{"type":"paragraph","text":[{"text":"Skills needed:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Mathematical and analytical skills"}]},{"text":[{"text":"Project management and problem-solving skills"}]},{"text":[{"text":"Excellent communication skills (oral and written)"}]},{"text":[{"text":"Strong business sense and commercial awareness"}]},{"text":[{"text":"Self-motivation (exams while working)"}]},{"text":[{"text":"Ambition and ability to work in a team"}]}]},{"type":"paragraph","text":[{"text":"Reasons to become an actuary:","bold":true},{"text":" job security; good pay; recognised qualifications; "},{"text":"highly transferable skills","bold":true},{"text":"; "},{"text":"international opportunities","bold":true},{"text":"; \""},{"text":"earn while you learn","bold":true},{"text":"\"; early advancement is largely "},{"text":"exam-based","bold":true},{"text":"; dynamic work."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Working alone and avoiding communication is "},{"text":"not","bold":true},{"text":" a required skill. Advancement does "},{"text":"not","bold":true},{"text":" depend only on length of service."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science evaluates risk with mathematics, statistics and probability; actuaries use past data but must quantify how the future will differ."}]},{"text":[{"text":"Actuaries evaluate likelihood, reduce likelihood, decrease impact, join corporate planning, and help insurers price and forecast."}]},{"text":[{"text":"Peril causes loss, hazard increases it; moral hazard is behaviour after cover, adverse selection is who applies."}]},{"text":[{"text":"Pooling relies on the law of large numbers; underwriting decides who to accept and on what terms."}]},{"text":[{"text":"Expected claim cost = probability × average claim; premium = cost × (1 + loading)."}]},{"text":[{"text":"Unearned premium = premium × months left / 12; loss ratio = claims incurred / premiums earned; solvency margin = assets − liabilities."}]},{"text":[{"text":"DB: employer bears risk; DC (Nigeria's CPS, PenCom): employee bears risk."}]},{"text":[{"text":"Bodies: IFoA, SOA, CAS (P&C only); Associate then Fellow."}]}]}],"theory":{"itemId":"8368a089-9a1b-5585-8838-55f0fc3e0e42","question":[{"type":"paragraph","text":[{"text":"An insurer covers 400 Lagos shop owners against burglary for one year. The probability of a claim is 0.02 per shop and the average claim is ₦500,000 (at most one claim each). It adds a 30% loading. Find (a) the risk premium per shop, (b) the gross premium per shop, (c) the expected loss ratio if claims come in as expected."}]}]},"practice":[{"topic":"Actuarial Science, Insurance and the Role of Actuaries","named":false}]}},{"itemId":"0a04d483-78ba-5a05-8218-8a4b5def9d21","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Time Value of Money: Compound Interest and Discounting","body":"The time value of money; simple interest and simple discount; compound interest, accumulation and discounting with v; the effective rate of discount d; nominal rates i^(m) and d^(m); the force of interest δ; the relationships among i, d, v and δ; changing rates; equations of value; solving for time and rate.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The time value of money; simple interest and simple discount; compound interest, accumulation and discounting with v; the effective rate of discount d; nominal rates i^(m) and d^(m); the force of interest δ; the relationships among i, d, v and δ; changing rates; equations of value; solving for time and rate."}],"lessons":[{"number":"5.1","title":"Time value of money, simple interest and simple discount","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time value of money (TVM):","bold":true},{"text":" money available today is worth more than the same amount in the future, because money received now can be invested to earn interest. So ₦100 today is worth more than ₦100 a year from now."}]},{"text":[{"text":"Principal (P):","bold":true},{"text":" the amount originally invested, which attracts interest."}]},{"text":[{"text":"Accumulation (compounding):","bold":true},{"text":" moving money forward in time (finding a future or accumulated value). "},{"text":"Discounting:","bold":true},{"text":" moving money back in time (finding the present value of future cash flows)."}]},{"text":[{"text":"The future value of an investment depends on "},{"text":"all three","bold":true},{"text":": the principal, the interest rate and the time."}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" interest is earned only on the original principal, so the interest is the "},{"text":"same every year","bold":true},{"text":". At rate r per annum, 1 grows to "},{"text":"1 + rt","bold":true},{"text":" after t years."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A = P(1 + rt) and interest I = Prt."}]},{"text":[{"text":"Present value under simple interest: P = A/(1 + rt)."}]},{"text":[{"text":"Time in months: t = months/12."}]}]}]},{"text":[{"text":"Simple discount:","bold":true},{"text":" at rate of simple discount d per annum, the value now of an amount A payable at time t is "},{"text":"P = A(1 − dt)","bold":true},{"text":". So an amount P invested now accumulates to "},{"text":"A = P/(1 − dt)","bold":true},{"text":", and 1 invested for one year accumulates to "},{"text":"1/(1 − d)","bold":true},{"text":"."}]},{"text":[{"text":"Solving simple interest for the rate: r = (A/P − 1)/t. For the time: t = (A/P − 1)/r."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple interest, worked:","bold":true},{"text":" ₦50,000 at 12% simple interest for 3 years. I = 50,000 × 0.12 × 3 = ₦18,000; A = ₦68,000. Equally, ₦1,000 at 8% simple for 5 years: A = 1,000(1 + 0.08 × 5) = ₦1,400."}]},{"text":[{"text":"Part of a year:","bold":true},{"text":" ₦60,000 at 10% for 8 months: I = 60,000 × 0.10 × 8/12 = ₦4,000."}]},{"text":[{"text":"Finding the rate:","bold":true},{"text":" ₦30,000 grows to ₦39,000 in 4 years. r = (39,000/30,000 − 1)/4 = 0.30/4 = "},{"text":"7.5%","bold":true},{"text":"."}]},{"text":[{"text":"Finding the time:","bold":true},{"text":" ₦40,000 grows to ₦52,000 at 6%. t = (1.3 − 1)/0.06 = "},{"text":"5 years","bold":true},{"text":"."}]},{"text":[{"text":"Present value at simple interest:","bold":true},{"text":" a debt of ₦20,000 is due in 4 years and you can invest at 5% simple. Invest 20,000/(1 + 0.05 × 4) = 20,000/1.2 = "},{"text":"₦16,666.67","bold":true},{"text":" now."}]},{"text":[{"text":"Simple discount, present value:","bold":true},{"text":" a bill of ₦80,000 due in 1.5 years at 8% simple discount: P = 80,000(1 − 0.08 × 1.5) = 80,000 × 0.88 = "},{"text":"₦70,400","bold":true},{"text":"."}]},{"text":[{"text":"Simple discount, accumulation:","bold":true},{"text":" ₦1,000 invested for 5 years at 8% simple discount accumulates to 1,000/(1 − 0.4) = "},{"text":"₦1,666.67","bold":true},{"text":" (2 d.p.). ₦5,000 for 2 years at 10% gives 5,000/0.8 = ₦6,250. One naira for one year at 10% simple discount gives 1/0.9 = 1.1111."}]},{"text":[{"text":"Trap:","bold":true},{"text":" under simple discount you "},{"text":"divide","bold":true},{"text":" by (1 − dt) to accumulate and "},{"text":"multiply","bold":true},{"text":" by (1 − dt) to find the value now. Do not use 1 + dt."}]},{"text":[{"text":"Nigerian Treasury Bills are sold at a discount to their face value, so the buyer pays less now and receives the full face value at maturity."}]}]}]},{"number":"5.2","title":"Compound interest, accumulation and the discount factor v","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Compound interest:","bold":true},{"text":" interest is earned on the principal "},{"text":"and","bold":true},{"text":" on interest already earned (interest is added and itself earns interest)."}]},{"text":[{"text":"Effective rate of interest i:","bold":true},{"text":" the total interest earned on 1 in a period (usually a year), assuming interest is reinvested as it falls due."}]},{"text":[{"text":"Accumulation factor:","bold":true},{"text":" (1 + i)^n = the accumulated value at time n of 1 invested at time 0."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"AV = P(1 + i)^n","bold":true},{"text":"; interest earned = P(1 + i)^n − P."}]}]}]},{"text":[{"text":"Discount factor:","bold":true},{"text":" "},{"text":"v = (1 + i)^−1 = 1/(1 + i)","bold":true},{"text":", the present value of 1 due one period hence."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"v^n = (1 + i)^−n","bold":true},{"text":" = the present value of 1 due at the end of n years."}]},{"text":[{"text":"PV = FV/(1 + i)^n = FV × v^n","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Moving a payment:","bold":true},{"text":" value at time t of X due at time s = X(1 + i)^(t − s). If t is earlier than s, this is X × v^(s − t). E.g. value at time 3 of a payment due at time 7 = payment × v^4."}]},{"text":[{"text":"The later a payment, the "},{"text":"smaller","bold":true},{"text":" its present value, because v^n falls as n increases."}]},{"text":[{"text":"n need not be whole: 2 years 6 months means n = 2.5."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Simple interest"}],[{"text":"Compound interest"}]],"rows":[[[{"text":"Interest earned on"}],[{"text":"principal only"}],[{"text":"principal and past interest"}]],[[{"text":"1 grows to"}],[{"text":"1 + rt"}],[{"text":"(1 + i)^t"}]],[[{"text":"Growth pattern"}],[{"text":"linear (straight line)"}],[{"text":"geometric (exponential)"}]],[[{"text":"Interest each year"}],[{"text":"the same"}],[{"text":"rises every year"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"At the same rate: "},{"text":"t = 1 year","bold":true},{"text":", both give 1 + i (equal); "},{"text":"t > 1","bold":true},{"text":", compound gives more; "},{"text":"t < 1","bold":true},{"text":", compound gives "},{"text":"less","bold":true},{"text":" than simple."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Year-by-year table:","bold":true},{"text":" ₦100 at 5% compound for 3 years (2 d.p.)."}]}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Principal at start"}],[{"text":"Interest at end"}],[{"text":"Accumulation at end"}]],"rows":[[[{"text":"1"}],[{"text":"100.00"}],[{"text":"5.00"}],[{"text":"105.00"}]],[[{"text":"2"}],[{"text":"105.00"}],[{"text":"5.25"}],[{"text":"110.25"}]],[[{"text":"3"}],[{"text":"110.25"}],[{"text":"5.51"}],[{"text":"115.76"}]]]},{"type":"paragraph","text":[{"text":"Check: 100 × 1.05^3 = 115.7625 = ₦115.76. Interest rises each year because it is earned on a growing balance. A thrift cooperative that credits interest yearly and lets it earn interest is using compound interest."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accumulated value:","bold":true},{"text":" ₦120,000 at 9% effective for 5 years. 1.09^5 = 1.53862395; AV = "},{"text":"₦184,634.87","bold":true},{"text":"; interest earned = ₦64,634.87."}]},{"text":[{"text":"Present value:","bold":true},{"text":" how much must be invested now to accumulate ₦200 in 3 years at 5%? X × 1.05^3 = 200, so X = 200/1.157625 = "},{"text":"₦172.77","bold":true},{"text":"."}]},{"text":[{"text":"Value at an intermediate date:","bold":true},{"text":" ₦400,000 is due at the end of year 6; at 8%, its value at the end of year 2 is 400,000 × v^4 = 400,000 × 0.73502985 = "},{"text":"₦294,011.94","bold":true},{"text":"."}]},{"text":[{"text":"Fractional period:","bold":true},{"text":" ₦20,000 for 3 years 9 months at 10%: 20,000 × 1.1^3.75 = "},{"text":"₦28,592.53","bold":true},{"text":"."}]},{"text":[{"text":"Compound versus simple over 2 years:","bold":true},{"text":" ₦200,000 at 15%. Compound interest = 200,000(1.15^2 − 1) = ₦64,500; simple interest = ₦60,000. Compound exceeds simple by ₦4,500 (= P × i^2 for 2 years)."}]},{"text":[{"text":"Under one year simple wins:","bold":true},{"text":" ₦100,000 for 3 months at 20%. Simple: 100,000(1 + 0.2 × 0.25) = ₦105,000. Compound: 100,000 × 1.2^0.25 = ₦104,663.51. Simple gives ₦336.49 more."}]},{"text":[{"text":"Interest-table values","bold":true},{"text":" (learn to get these on your calculator): at 6%, (1.06)^10 = 1.79085 and v^10 = 0.55839; at 3.5%, (1.035)^10 = 1.41060."}]},{"text":[{"text":"Trap:","bold":true},{"text":" PV = FV(1 + i)^n is accumulation, not discounting; PV = FV/(1 + ni) is simple interest. The compound-interest PV is FV/(1 + i)^n."}]},{"text":[{"text":"Actuaries valuing pension liabilities (supervised by PenCom) and insurance reserves (supervised by NAICOM) discount the future payments to today with v^n."}]}]}]},{"number":"5.3","title":"The effective rate of discount d and the links among i, d and v","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Effective rate of discount d:","bold":true},{"text":" the discount on 1 due a year hence; that is, interest for the year paid at the "},{"text":"start","bold":true},{"text":" of the year. (i is interest paid at the "},{"text":"end","bold":true},{"text":" of the year.)"}]},{"text":[{"text":"Correct formulae (learn all of them):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"d = i/(1 + i)","bold":true}]},{"text":[{"text":"d = iv","bold":true}]},{"text":[{"text":"d = 1 − v","bold":true},{"text":", so "},{"text":"v = 1 − d","bold":true}]},{"text":[{"text":"i = d/(1 − d)","bold":true}]}]}]},{"text":[{"text":"d < i","bold":true},{"text":" whenever i > 0."}]},{"text":[{"text":"PV of X due in n years at discount rate d: "},{"text":"X(1 − d)^n = X v^n","bold":true},{"text":"."}]},{"text":[{"text":"Amount of discount","bold":true},{"text":" on a bill of face value X due in one year = X − Xv = "},{"text":"X × d","bold":true},{"text":"."}]},{"text":[{"text":"Not","bold":true},{"text":" correct: d = i/(1 − i); v = 1 + d."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"From i to d:","bold":true},{"text":" i = 8%. d = 0.08/1.08 = 0.074074 = "},{"text":"7.41%","bold":true},{"text":" (2 d.p.). Likewise i = 5% gives d = 0.047619 and i = 2.5% gives d = 2.44%."}]},{"text":[{"text":"From d to i:","bold":true},{"text":" d = 6%. i = 0.06/0.94 = 0.063830 = "},{"text":"6.38%","bold":true},{"text":"."}]},{"text":[{"text":"PV using d:","bold":true},{"text":" ₦300,000 due in 3 years at d = 4%: 300,000 × 0.96^3 = "},{"text":"₦265,420.80","bold":true},{"text":"."}]},{"text":[{"text":"Discount on a bill:","bold":true},{"text":" a bill of ₦250,000 due in one year, i = 10%. d = 0.1/1.1 = 0.090909; discount = 250,000 × 0.1/1.1 = "},{"text":"₦22,727.27","bold":true},{"text":"; present value = 250,000/1.1 = ₦227,272.73. Check: 227,272.73 + 22,727.27 = 250,000."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the amount of discount is face × d, not face × i (₦25,000 here would be wrong)."}]}]}]},{"number":"5.4","title":"Nominal rates of interest and discount; equivalent rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal rate of interest i^(m):","bold":true},{"text":" a rate per annum "},{"text":"convertible (compounded, payable) m times a year","bold":true},{"text":". The effective rate per m-th of a year is "},{"text":"i^(m)/m","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"m = 2 half-yearly, 4 quarterly, 12 monthly, 365 daily."}]}]}]},{"text":[{"text":"Equivalent rates:","bold":true},{"text":" two rates are equivalent when they give the "},{"text":"same accumulated value","bold":true},{"text":" from the same principal over the same period."}]},{"text":[{"text":"Key equation: "},{"text":"1 + i = (1 + i^(m)/m)^m","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal to effective: "},{"text":"i = (1 + i^(m)/m)^m − 1","bold":true}]},{"text":[{"text":"Effective to nominal: "},{"text":"i^(m) = m[(1 + i)^(1/m) − 1]","bold":true}]}]}]},{"text":[{"text":"AV with a nominal rate:","bold":true},{"text":" A = P(1 + i^(m)/m)^(mn), n in years. "},{"text":"PV:","bold":true},{"text":" P = A(1 + i^(m)/m)^−(mn)."}]},{"text":[{"text":"Effective rate per sub-period","bold":true},{"text":" from an annual effective rate: (1 + i)^(1/m) − 1. From one period to a longer one: e.g. monthly j to quarterly = (1 + j)^3 − 1."}]},{"text":[{"text":"Nominal rate of discount d^(m):","bold":true},{"text":" discount convertible m times a year; "},{"text":"1 − d = (1 − d^(m)/m)^m = v","bold":true},{"text":"."}]},{"text":[{"text":"For a fixed nominal rate, the effective rate "},{"text":"rises","bold":true},{"text":" as m rises, towards a limit e^(i^(m)) − 1."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal to effective:","bold":true},{"text":" 6% p.a. payable half-yearly. ₦1,000 after 2 years: 1,000(1 + 0.06/2)^4 = 1,000 × 1.03^4 = "},{"text":"₦1,125.51","bold":true},{"text":". Effective annual rate: (1.03)^2 − 1 = "},{"text":"0.0609 = 6.09%","bold":true},{"text":"."}]},{"text":[{"text":"12% convertible quarterly: i = 1.03^4 − 1 = "},{"text":"12.55%","bold":true},{"text":". 24% convertible monthly: 2% per month, i = 1.02^12 − 1 = "},{"text":"26.82%","bold":true},{"text":" (not 24%)."}]},{"text":[{"text":"Table for 10%","bold":true},{"text":" (5 d.p.):"}]}]},{"type":"table","header":[[{"text":"m"}],[{"text":"Effective i when i^(m) = 10%"}],[{"text":"Nominal i^(m) when i = 10%"}]],"rows":[[[{"text":"1"}],[{"text":"0.10000"}],[{"text":"0.10000"}]],[[{"text":"2"}],[{"text":"0.10250"}],[{"text":"0.09762"}]],[[{"text":"4"}],[{"text":"0.10381"}],[{"text":"0.09645"}]],[[{"text":"6"}],[{"text":"0.10426"}],[{"text":"0.09607"}]],[[{"text":"12"}],[{"text":"0.10471"}],[{"text":"0.09569"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"More frequent compounding, same nominal 6%:","bold":true},{"text":" ₦10,000 for 10 years (to the nearest kobo): m = 1: ₦17,908.48; m = 2: ₦18,061.11; m = 4: ₦18,140.18; m = 12: ₦18,193.97; m = 365: ₦18,220.29. Note 6% \"compounded annually\" is just 1.06^10."}]},{"text":[{"text":"Effective to nominal:","bold":true},{"text":" i = 21% gives i^(2) = 2(1.21^0.5 − 1) = 2(0.1) = "},{"text":"20%","bold":true},{"text":"."}]},{"text":[{"text":"Sub-period rates:","bold":true},{"text":" i = 12% a year gives (1.12)^(1/12) − 1 = 0.9489% ≈ "},{"text":"0.95% per month","bold":true},{"text":". 2% per month gives 1.02^3 − 1 = "},{"text":"6.12% per quarter","bold":true},{"text":"."}]},{"text":[{"text":"Nominal to nominal:","bold":true},{"text":" i^(4) = 8% means 2% a quarter. Half-yearly: (1.02)^2 = 1.0404, so i^(2) = 2 × 0.0404 = "},{"text":"8.08%","bold":true},{"text":"."}]},{"text":[{"text":"AV:","bold":true},{"text":" ₦150,000 for 2 years at 12% convertible monthly: 150,000 × 1.01^24 = "},{"text":"₦190,460.20","bold":true},{"text":". 18 months would be 1.01^18."}]},{"text":[{"text":"PV:","bold":true},{"text":" ₦600,000 due in 3 years at 8% convertible quarterly: 600,000 × 1.02^−12 = "},{"text":"₦473,095.91","bold":true},{"text":"."}]},{"text":[{"text":"Nominal discount:","bold":true},{"text":" d^(2) = 10% means 5% each half-year. PV of ₦400,000 due in a year = 400,000 × 0.95^2 = "},{"text":"₦361,000","bold":true},{"text":". d^(4) = 8% gives d = 1 − 0.98^4 = "},{"text":"7.76%","bold":true},{"text":" (lower than 8%)."}]},{"text":[{"text":"Solving for a nominal rate:","bold":true},{"text":" ₦60,000 grows to ₦75,000 in 3 years, monthly compounding. (1 + j)^36 = 1.25, so j = 1.25^(1/36) − 1 and i^(12) = 12j = "},{"text":"7.46%","bold":true},{"text":"."}]},{"text":[{"text":"Comparing offers:","bold":true},{"text":" Bank A pays 12% convertible monthly, i = 1.01^12 − 1 = 12.68%; Bank B pays 12.5% effective. Bank A is better. Always compare "},{"text":"effective","bold":true},{"text":" rates."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"24% per annum convertible monthly\" is i^(12) = 24%, 2% per month. It is not an effective 24%, a force of interest, or a discount rate."}]}]}]},{"number":"5.5","title":"The force of interest δ","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Force of interest δ (delta):","bold":true},{"text":" the instantaneous rate of growth; the limit of the nominal rate i^(m) as m tends to infinity, i.e. a nominal rate compounding continuously (\"compounded continuously\" means a force of interest)."}]},{"text":[{"text":"In international actuarial notation the Greek letter "},{"text":"δ","bold":true},{"text":" denotes the force of interest."}]},{"text":[{"text":"Relationships:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"1 + i = e^δ","bold":true}]},{"text":[{"text":"δ = ln(1 + i)","bold":true}]},{"text":[{"text":"v = e^−δ","bold":true}]},{"text":[{"text":"d = 1 − e^−δ","bold":true}]},{"text":[{"text":"i^(m) = m(e^(δ/m) − 1)"}]}]}]},{"text":[{"text":"AV = P e^(δn)","bold":true},{"text":"; "},{"text":"PV = A e^−(δn)","bold":true},{"text":"."}]},{"text":[{"text":"Not","bold":true},{"text":" correct: δ = e^i − 1."}]},{"text":[{"text":"Ordering","bold":true},{"text":" for any positive i: "},{"text":"d < d^(m) < δ < i^(m) < i","bold":true},{"text":"; in detail d < d^(2) < d^(12) < δ < i^(12) < i^(2) < i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Effective to force:","bold":true},{"text":" i = 10%: δ = ln 1.1 = "},{"text":"0.09531","bold":true},{"text":". Half-yearly nominal 10%: (1.05)^2 = 1.1025, δ = ln 1.1025 = 0.09758. 10% effective per half-year: (1.1)^2 = 1.21, δ = ln 1.21 = 0.19062 p.a. Similarly 8% effective gives δ = 0.0770, and 5% per quarter gives δ = 4 ln 1.05 = 0.1952 p.a."}]},{"text":[{"text":"Force to others:","bold":true},{"text":" δ = 8%. i = e^0.08 − 1 = "},{"text":"8.33%","bold":true},{"text":"; v = e^−0.08 = 0.9231; d = 1 − 0.9231 = 7.69%. δ = 10% gives i^(12) = 12(e^(0.1/12) − 1) = 10.04%."}]},{"text":[{"text":"AV:","bold":true},{"text":" ₦300,000 for 3 years at δ = 10% (or 10% compounded continuously): 300,000 e^0.3 = "},{"text":"₦404,957.64","bold":true},{"text":"."}]},{"text":[{"text":"PV:","bold":true},{"text":" ₦500,000 due in 4 years at δ = 6%: 500,000 e^−0.24 = "},{"text":"₦393,313.93","bold":true},{"text":"."}]},{"text":[{"text":"Dates:","bold":true},{"text":" a loan from 1 March 2020 to 1 March 2025 runs exactly 5 years, so use n = 5."}]},{"text":[{"text":"Ordering check at i = 10%:","bold":true},{"text":" d 0.09091 < d^(2) 0.09307 < d^(12) 0.09493 < δ 0.09531 < i^(12) 0.09569 < i^(2) 0.09762 < i 0.10000."}]},{"text":[{"text":"A fixed nominal 10% with m rising gives effective rates rising towards e^0.1 − 1 = 10.52%."}]},{"text":[{"text":"Trap:","bold":true},{"text":" δ is the natural log (ln) of 1 + i, not of i, and it is always below i."}]}]}]},{"number":"5.6","title":"Changing rates, equations of value, solving for time and rate","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Changing rates:","bold":true},{"text":" multiply the accumulation factors for each period. 1 invested for 3 years at i_1 then 2 years at i_2 grows to (1 + i_1)^3(1 + i_2)^2. Discount by dividing by the same factors."}]},{"text":[{"text":"For a "},{"text":"single sum","bold":true},{"text":", the "},{"text":"order","bold":true},{"text":" of the rates does not matter (multiplication). With "},{"text":"further payments","bold":true},{"text":" at later dates, the order matters."}]},{"text":[{"text":"Equation of value:","bold":true},{"text":" set the value of what is paid in equal to the value of what is paid out, "},{"text":"with every payment valued at the same date","bold":true},{"text":". Under compound interest "},{"text":"any comparison date","bold":true},{"text":" gives the same answer."}]},{"text":[{"text":"Equivalent single payment","bold":true},{"text":" at time t: accumulate earlier payments to t and discount later ones to t."}]},{"text":[{"text":"Solving for time:","bold":true},{"text":" n = ln(A/P)/ln(1 + i). Under a force δ: n = ln(A/P)/δ. Doubling time: n = ln 2/ln(1 + i), or ln 2/δ."}]},{"text":[{"text":"Solving for the rate (one payment):","bold":true},{"text":" i = (A/P)^(1/n) − 1. With two payments a year apart, solve a "},{"text":"quadratic","bold":true},{"text":" in x = 1 + i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Changing rates, two investments:","bold":true},{"text":" ₦100 now and ₦100 at time 3, accumulated to time 10."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5% for 3 years, 6% for 3, 7% for 4: (100 × 1.05^3 + 100) × 1.06^3 × 1.07^4 = "},{"text":"₦336.84","bold":true},{"text":"."}]},{"text":[{"text":"6%, then 5%, then 7%: (100 × 1.06^3 + 100) × 1.05^3 × 1.07^4 = "},{"text":"₦332.47","bold":true},{"text":". Different, because the second ₦100 only meets the later rates."}]}]}]},{"text":[{"text":"Single sum:","bold":true},{"text":" ₦50,000 for 5 years at 5% for 2 years then 8% for 3: 50,000 × 1.05^2 = 55,125; × 1.08^3 = "},{"text":"₦69,441.62","bold":true},{"text":". Reversing the rates gives the same answer."}]},{"text":[{"text":"PV with changing rates:","bold":true},{"text":" ₦80,000 due at year 5; 10% for years 1 and 2, 9% for years 3 to 5. PV = 80,000/(1.1^2 × 1.09^3) = 80,000/1.566985 = "},{"text":"₦51,053.45","bold":true},{"text":"."}]},{"text":[{"text":"Loan cleared by a final payment:","bold":true},{"text":" Ngozi borrows ₦300,000 at 12%, repays ₦150,000 at the end of year 1. Balance after year 1: 336,000 − 150,000 = 186,000; final payment at year 3 = 186,000 × 1.12^2 = "},{"text":"₦233,318.40","bold":true},{"text":"."}]},{"text":[{"text":"Two equal repayments:","bold":true},{"text":" a ₦400,000 loan repaid by X at the end of years 1 and 2 at 8%: 400,000 = X(v + v^2) = X × 1.78326475, so X = "},{"text":"₦224,307.69","bold":true},{"text":"."}]},{"text":[{"text":"Equivalent single payment:","bold":true},{"text":" ₦40,000 due at year 1 and ₦90,000 at year 6; at 10%, the single payment at year 3 is 40,000 × 1.1^2 + 90,000 × 1.1^−3 = 48,400 + 67,618.33 = "},{"text":"₦116,018.33","bold":true},{"text":"."}]},{"text":[{"text":"Present value of several payments:","bold":true},{"text":" add each payment × v^n. At 10% half-yearly nominal, use 5% per half-year: ₦100,000 at year 1 and year 2 has PV 100,000(1.05^−2 + 1.05^−4) = 90,702.95 + 82,270.25 = "},{"text":"₦172,973.20","bold":true},{"text":"."}]},{"text":[{"text":"Rate, one payment:","bold":true},{"text":" ₦25,000 grows to ₦40,000 in 5 years. i = 1.6^(1/5) − 1 = "},{"text":"9.86%","bold":true},{"text":"."}]},{"text":[{"text":"Rate, quadratic:","bold":true},{"text":" ₦50,000 now and ₦50,000 in a year; the account holds ₦112,320 at the end of year 2. 50,000x^2 + 50,000x = 112,320, so x^2 + x − 2.2464 = 0. x = (−1 + √(1 + 8.9856))/2 = (−1 + 3.16)/2 = 1.08, so "},{"text":"i = 8%","bold":true},{"text":"."}]},{"text":[{"text":"Time:","bold":true},{"text":" ₦60,000 to ₦100,000 at 7%: n = ln(5/3)/ln 1.07 = "},{"text":"7.55 years","bold":true},{"text":". Doubling at 8%: ln 2/ln 1.08 = 9.01 years; at δ = 8%: ln 2/0.08 = 8.66 years."}]},{"text":[{"text":"Trap:","bold":true},{"text":" never add payments at different dates at face value; move them to one date first."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"TVM: money now is worth more because it can earn interest; discounting finds present values."}]},{"text":[{"text":"Simple interest: A = P(1 + rt), the same interest each year; simple discount: P = A(1 − dt)."}]},{"text":[{"text":"Compound: AV = P(1 + i)^n; PV = FV v^n; v = 1/(1 + i) is the discount factor."}]},{"text":[{"text":"Under one year simple beats compound; at one year they are equal; beyond one year compound wins."}]},{"text":[{"text":"d = i/(1 + i) = iv = 1 − v; i = d/(1 − d)."}]},{"text":[{"text":"Nominal: 1 + i = (1 + i^(m)/m)^m; compare effective rates; 1 − d = (1 − d^(m)/m)^m."}]},{"text":[{"text":"Force: 1 + i = e^δ, δ = ln(1 + i), v = e^−δ; δ is the limit of i^(m)."}]},{"text":[{"text":"Ordering: d < d^(m) < δ < i^(m) < i."}]},{"text":[{"text":"Equations of value: value everything at one date; any date gives the same answer."}]},{"text":[{"text":"Time: n = ln(A/P)/ln(1 + i); rate: i = (A/P)^(1/n) − 1."}]}]}],"theory":{"itemId":"9a35d314-f734-5003-9bae-9f1da719e5c9","question":[{"type":"paragraph","text":[{"text":"A nominal rate of interest is 8% per annum convertible quarterly. Find (a) the equivalent effective annual rate of interest, (b) the force of interest, and (c) the accumulated value of ₦100,000 after 3 years. Give rates to 4 decimal places and money to the nearest kobo."}]}]},"practice":[{"topic":"Time Value of Money: Compound Interest and Discounting","named":false}]}},{"itemId":"9547b537-1d3f-5af0-b87f-dbac7dc05f27","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Present and Accumulated Values of Payment Streams","body":"The cash flows of common securities; present value and accumulated value of a stream of equal or unequal payments; moving a value to any date; equations of value (unknown payment, time or rate); changing rates of interest; net present value, internal rate of return (yield) and discounted payback.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The cash flows of common securities; present value and accumulated value of a stream of equal or unequal payments; moving a value to any date; equations of value (unknown payment, time or rate); changing rates of interest; net present value, internal rate of return (yield) and discounted payback."}],"lessons":[{"number":"6.1","title":"Cash flows and the securities that produce them","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash flow:","bold":true},{"text":" a payment (in or out) at a stated time. Valuing a contract means listing its cash flows and their times, then applying interest."}]},{"text":[{"text":"Bond:","bold":true},{"text":" a certificate of debt issued by a government or company, promising periodic interest payments and the return of the original amount on a stated date."}]},{"text":[{"text":"Coupon:","bold":true},{"text":" the interest payment on a bond. "},{"text":"Redemption:","bold":true},{"text":" the return of the investor's capital at the end."}]},{"text":[{"text":"Zero-coupon bond:","bold":true},{"text":" pays "},{"text":"no coupons","bold":true},{"text":"; makes a "},{"text":"single payment at maturity","bold":true},{"text":" whose money amount is known in advance."}]},{"text":[{"text":"Fixed-interest security:","bold":true},{"text":" pays regular "},{"text":"fixed coupons plus a redemption payment","bold":true},{"text":". Ignoring default, the money amounts and dates are fixed at issue. In actuarial and UK usage it is also called "},{"text":"loan stock","bold":true},{"text":" (or simply "},{"text":"stock","bold":true},{"text":"); a UK government bond is a "},{"text":"gilt","bold":true},{"text":". "},{"text":"Unsecured loan stock:","bold":true},{"text":" long-term company debt not secured on any specific assets."}]},{"text":[{"text":"Index-linked security:","bold":true},{"text":" coupons and redemption are "},{"text":"adjusted in line with an index","bold":true},{"text":" (usually inflation), so the money amounts are "},{"text":"not","bold":true},{"text":" known in advance; the dates are."}]},{"text":[{"text":"Call deposit:","bold":true},{"text":" money in a bank account that can be withdrawn on demand; the interest rate can change."}]},{"text":[{"text":"Equity (ordinary share):","bold":true},{"text":" pays dividends that depend on the company's profits and the directors' decisions; no redemption date."}]}]},{"type":"table","header":[[{"text":"Contract"}],[{"text":"Amount known in advance?"}],[{"text":"Timing known in advance?"}]],"rows":[[[{"text":"Zero-coupon bond"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Fixed-interest security"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Index-linked security"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Call deposit"}],[{"text":"No"}],[{"text":"No"}]],[[{"text":"Equity"}],[{"text":"No"}],[{"text":"No"}]]]},{"type":"paragraph","text":[{"text":"Index-linked payment formula:","bold":true}]},{"type":"paragraph","text":[{"text":"Payment actually received = nominal payment × (index at payment date ÷ index at purchase date)"}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","italic":true},{"text":" An investor buys a two-year index-linked security on 1.1.2021. Without inflation it would pay ₦10,000 at the end of each year and ₦200,000 on redemption at 1.1.2023. Index: 1.1.2020 = 100; 1.1.2021 = 150; 1.1.2022 = 165; 1.1.2023 = 180."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Base is the index on the "},{"text":"purchase date","bold":true},{"text":", 150 (not 100)."}]},{"text":[{"text":"Payment on 1.1.2022 = 10,000 × 165/150 = "},{"text":"₦11,000","bold":true},{"text":"."}]},{"text":[{"text":"Payment on 1.1.2023 = 10,000 × 180/150 = "},{"text":"₦12,000","bold":true},{"text":"."}]},{"text":[{"text":"Redemption on 1.1.2023 = 200,000 × 180/150 = "},{"text":"₦240,000","bold":true},{"text":"."}]},{"text":[{"text":"If the index falls below the purchase value, the payment falls below the nominal amount (for example an index of 135 would give 10,000 × 135/150 = ₦9,000)."}]}]},{"type":"paragraph","text":[{"text":"Traps: a zero-coupon bond "},{"text":"does","bold":true},{"text":" pay something (once, at maturity); \"regular coupons plus redemption\" describes a fixed-interest security. For an equity, the dividend amount is never known in advance; dividends are usually paid at regular intervals but neither the date nor the amount is guaranteed. In Nigeria, FGN bonds are fixed-interest securities and Nigerian Treasury Bills work like zero-coupon instruments; pension funds supervised by PenCom and insurers supervised by NAICOM hold both."}]}]},{"number":"6.2","title":"Present value and accumulated value of a stream","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Present value (PV) of a payment stream:","bold":true},{"text":" the single value at time 0 found by discounting every payment to time 0 at a given rate of interest and adding the results."}]},{"text":[{"text":"Accumulated value (AV) at time n:","bold":true},{"text":" the total of all payments rolled forward with interest to time n."}]},{"text":[{"text":"Value at time t:","bold":true},{"text":" every payment is moved to time t (accumulated if it is earlier, discounted if it is later) and the results are added."}]}]},{"type":"paragraph","text":[{"text":"With payments C_1, C_2, ..., C_n at times t_1, t_2, ..., t_n and v = 1/(1 + i):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = C_1 v^(t_1) + C_2 v^(t_2) + ... + C_n v^(t_n)"}]},{"text":[{"text":"AV at time n = sum of C_k (1 + i)^(n − t_k)"}]},{"text":[{"text":"Moving a value:","bold":true},{"text":" value at time t = PV × (1 + i)^t; PV = (value at time t) × v^t. So AV at n = PV × (1 + i)^n."}]},{"text":[{"text":"Times need not be whole numbers: v^0.5 = (1 + i)^(−0.5)."}]}]},{"type":"paragraph","text":[{"text":"Discount factor for each way of quoting interest:","bold":true}]},{"type":"table","header":[[{"text":"Basis given"}],[{"text":"Discount factor for time t"}]],"rows":[[[{"text":"Effective rate i per year"}],[{"text":"v^t = (1 + i)^(−t)"}]],[[{"text":"Nominal rate i^(m) convertible m-thly"}],[{"text":"(1 + i^(m)/m)^(−mt); use i^(m)/m per period and count periods"}]],[[{"text":"Force of interest δ"}],[{"text":"v^t = e^(−δt)"}]],[[{"text":"Effective rate of discount d"}],[{"text":"v = 1 − d, so v^t = (1 − d)^t"}]],[[{"text":"Simple interest at r"}],[{"text":"1/(1 + rt)"}]]]},{"type":"paragraph","text":[{"text":"Level payments","bold":true},{"text":" (from Topic 7, restated): ₦1 at the end of each year for n years has PV a_n| = (1 − v^n)/i and AV s_n| = ((1 + i)^n − 1)/i. Paid at the start of each year: ä_n| = (1 + i) a_n| and s̈_n| = (1 + i) s_n|."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (unequal payments).","italic":true},{"text":" ₦30,000 at time 1, ₦40,000 at time 2 and ₦50,000 at time 4, at 8% effective."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = 30,000 × 1.08^(−1) + 40,000 × 1.08^(−2) + 50,000 × 1.08^(−4)"}]},{"text":[{"text":"= 27,777.78 + 34,293.55 + 36,751.49 = "},{"text":"₦98,822.82","bold":true}]},{"text":[{"text":"AV at time 4 = 30,000 × 1.08^3 + 40,000 × 1.08^2 + 50,000 = 37,791.36 + 46,656 + 50,000 = "},{"text":"₦134,447.36","bold":true}]},{"text":[{"text":"Check: 98,822.82 × 1.08^4 = ₦134,447.36."}]},{"text":[{"text":"Value at time 2 = 30,000 × 1.08 + 40,000 + 50,000 × 1.08^(−2) = 32,400 + 40,000 + 42,866.94 = "},{"text":"₦115,266.94","bold":true},{"text":" (also 98,822.82 × 1.08^2)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (other bases).","italic":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Fractional time: ₦50,000 at time 0.5 at 10% effective: 50,000 × 1.1^(−0.5) = 50,000 × 0.953463 = "},{"text":"₦47,673","bold":true},{"text":" (nearest naira)."}]},{"text":[{"text":"Nominal rate: ₦20,000 at 6 months and ₦20,000 at 18 months, at 10% convertible half-yearly. Rate per half-year = 5%; the payments are 1 and 3 half-years away: 20,000/1.05 + 20,000/1.05^3 = 19,047.62 + 17,276.75 = "},{"text":"₦36,324.37","bold":true},{"text":"."}]},{"text":[{"text":"Force: ₦100,000 at time 2 with δ = 0.1: 100,000 × e^(−0.2) = "},{"text":"₦81,873","bold":true},{"text":" (nearest naira)."}]},{"text":[{"text":"Discount rate: ₦40,000 at times 1 and 2 with d = 10%: v = 0.9, PV = 40,000 × 0.9 + 40,000 × 0.81 = "},{"text":"₦68,400","bold":true},{"text":"."}]},{"text":[{"text":"Simple interest at 10%: ₦22,000 at time 1 and ₦24,000 at time 2: 22,000/1.1 + 24,000/1.2 = 20,000 + 20,000 = "},{"text":"₦40,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (level payments).","italic":true},{"text":" ₦10,000 at the end of each year for 5 years at 8%: a_5| = (1 − 1.08^(−5))/0.08 = 3.99271, so PV = "},{"text":"₦39,927","bold":true},{"text":"; s_5| = 5.86660, so AV at the time of the 5th payment = "},{"text":"₦58,666","bold":true},{"text":". Paid at the start of each year (times 0 to 4): PV = 39,927.10 × 1.08 = "},{"text":"₦43,121","bold":true},{"text":", and AV at time 5 = 58,666.01 × 1.08 = "},{"text":"₦63,359","bold":true},{"text":". If a question gives you a table value, such as a_4| = 3.2397 at 9%, simply multiply: ₦40,000 × 3.2397 = ₦129,588."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (gaps and growth).","italic":true},{"text":" ₦10,000 at the ends of years 3, 4 and 5 only, at 8%: 10,000 × (1.08^(−3) + 1.08^(−4) + 1.08^(−5)) = "},{"text":"₦22,094","bold":true},{"text":", equal to 10,000 × (a_5| − a_2|). A year with no payment simply contributes nothing. Payments of ₦50,000, ₦55,000 and ₦60,500 (growing 10% a year) at times 1, 2, 3 at 10%: each discounts to ₦45,454.55, so PV = "},{"text":"₦136,364","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Traps: the AV of an end-of-year series is measured \"at the time of the last payment\" (so the last payment earns no interest); for start-of-year deposits valued one year after the last deposit, every deposit earns interest. The PV is always less than the plain total of future positive payments, and the PV does "},{"text":"not","bold":true},{"text":" equal the AV at the last date (they differ by the factor (1 + i)^n)."}]}]},{"number":"6.3","title":"Equations of value","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equation of value:","bold":true},{"text":" an equation stating that, at a chosen date (the "},{"text":"comparison date","bold":true},{"text":" or focal date), the total value of money paid out equals the total value of money received, at a given rate of interest."}]},{"text":[{"text":"General form: sum of (outgo values) = sum of (income values), all at the same date. At time 0: sum of C_t v^t = 0 with outflows negative."}]},{"text":[{"text":"Under "},{"text":"compound interest","bold":true},{"text":" any comparison date gives the "},{"text":"same answer","bold":true},{"text":", because moving from time 0 to time T multiplies every term by (1 + i)^T. Time 0 or the date of the unknown payment is usually easiest."}]},{"text":[{"text":"Uses: (1) find an unknown payment; (2) replace debts by one payment at a new date; (3) find an unknown time; (4) find an unknown rate (yield); (5) loan repayments and saving targets."}]},{"text":[{"text":"Equal loan repayment: loan = R × a_n|, so R = loan ÷ a_n|. Saving target: target = D × s_n| (end of year) or D × s̈_n| (start of year)."}]},{"text":[{"text":"Unknown time: rearrange to (1 + i)^t = k, then t = ln k ÷ ln(1 + i)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Replacing debts.","italic":true},{"text":" Debts of ₦80,000 due at time 1 and ₦120,000 due at time 4 are replaced by one payment at time 2, at 10%. At time 2: X = 80,000 × 1.1 + 120,000 × 1.1^(−2) = 88,000 + 99,173.55 = "},{"text":"₦187,174","bold":true},{"text":" (nearest naira). The earlier debt is accumulated, the later one discounted. A Kano debtor and creditor are equally well off because both sides are valued at the same date and rate."}]},{"type":"paragraph","text":[{"text":"Unknown final payment.","italic":true},{"text":" A loan of ₦300,000 is repaid by ₦100,000 at time 1 and X at time 2, at 12%. At time 2: 300,000 × 1.12^2 = 100,000 × 1.12 + X, so X = 376,320 − 112,000 = "},{"text":"₦264,320","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Payments in a ratio.","italic":true},{"text":" A loan of ₦300,000 is repaid by X at time 1 and 2X at time 3, at 8%: 300,000 = X(1.08^(−1) + 2 × 1.08^(−3)) = X × 2.513590, so X = "},{"text":"₦119,351","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Two equal payments.","italic":true},{"text":" A debt of ₦400,000 due at time 3 is replaced by X at time 1 and X at time 5, at 10%: X(1.1^(−1) + 1.1^(−5)) = 400,000 × 1.1^(−3), so X × 1.530012 = 300,525.92 and X = "},{"text":"₦196,421","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Loan and saving.","italic":true},{"text":" ₦500,000 borrowed, repaid by 4 equal year-end payments at 10%: R = 500,000 ÷ 3.169865 = "},{"text":"₦157,735","bold":true},{"text":". To have ₦600,000 at time 5 by 5 equal deposits at 7%: end of each year, D = 600,000 ÷ s_5| = 600,000 ÷ 5.750739 = "},{"text":"₦104,334","bold":true},{"text":"; start of each year, D = 600,000 ÷ 6.153291 = "},{"text":"₦97,509","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Unknown time (equated time).","italic":true},{"text":" ₦60,000 due at time 1 and ₦60,000 at time 5 are replaced by ₦120,000 at time t, at 6%:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"120,000 v^t = 60,000(v + v^5), so v^t = (0.943396 + 0.747258)/2 = 0.845327"}]},{"text":[{"text":"(1.06)^t = 1.182974, t = ln 1.182974 ÷ ln 1.06 = 0.168032 ÷ 0.058269 = "},{"text":"2.88 years","bold":true},{"text":" (2 d.p.), earlier than the simple average of 3 years."}]}]},{"type":"paragraph","text":[{"text":"Time to reach a target.","italic":true},{"text":" ₦50,000 now and ₦50,000 at time 1, at 10%: when is the fund ₦150,000? 50,000(1.1)^t + 50,000(1.1)^(t − 1) = 150,000, so (1.1)^t × (1 + 1/1.1) = 3, (1.1)^t = 1.571429, t = 0.451985 ÷ 0.095310 = "},{"text":"4.74 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Unknown rate.","italic":true},{"text":" ₦100,000 deposited at times 0 and 1 gives ₦231,000 at time 2. Let x = 1 + i: 100,000x^2 + 100,000x = 231,000, so x^2 + x − 2.31 = 0, x = (−1 + √10.24)/2 = (−1 + 3.2)/2 = 1.1, so "},{"text":"i = 10%","bold":true},{"text":". With answer options, you can also test each rate."}]}]},{"number":"6.4","title":"Changing rates and sensitivity to the rate","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When the rate changes over time, accumulate (or discount) "},{"text":"period by period","bold":true},{"text":", using the rate in force in each period: AV of ₦1 over two years at i_1 then i_2 = (1 + i_1)(1 + i_2)."}]},{"text":[{"text":"Discount factor to time 2 when year 1 is at i_1 and year 2 at i_2: 1/[(1 + i_1)(1 + i_2)]."}]},{"text":[{"text":"A later deposit earns only the rates that apply "},{"text":"after","bold":true},{"text":" it is made."}]},{"text":[{"text":"Higher rate, lower PV:","bold":true},{"text":" each v^t gets smaller, so the PV of fixed positive future payments "},{"text":"falls","bold":true},{"text":" when i rises (and the AV rises)."}]},{"text":[{"text":"Payments due "},{"text":"later","bold":true},{"text":" are hit harder: long-dated streams lose more value than short-dated ones when rates rise."}]},{"text":[{"text":"A naira due later adds less to the PV than a naira due sooner."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Changing rates, accumulation.","italic":true},{"text":" ₦100 for ten years at 5% for 3 years, 6% for 3 years and 7% for 4 years: 100 × 1.05^3 × 1.06^3 × 1.07^4 = "},{"text":"₦180.73","bold":true},{"text":". With a second deposit: ₦200,000 now and ₦100,000 at time 2; 6% for years 1-2, then 9% for years 3-5. Value at time 2 = 200,000 × 1.06^2 + 100,000 = 224,720 + 100,000 = 324,720. At time 5: 324,720 × 1.09^3 = 324,720 × 1.295029 = "},{"text":"₦420,522","bold":true},{"text":". Order matters: swapping which rate applies first changes the answer when deposits are made in between."}]},{"type":"paragraph","text":[{"text":"Changing rates, discounting.","italic":true},{"text":" 10% in year 1 and 12% in year 2; ₦100,000 at times 1 and 2: PV = 100,000/1.1 + 100,000/(1.1 × 1.12) = 90,909.09 + 81,168.83 = "},{"text":"₦172,078","bold":true},{"text":" (nearest naira). Do "},{"text":"not","bold":true},{"text":" discount the second payment at 1.12^2."}]},{"type":"paragraph","text":[{"text":"Withdrawals.","italic":true},{"text":" ₦100,000 deposited now, ₦30,000 withdrawn at time 2, 9%: balance at time 4 = 100,000 × 1.09^4 − 30,000 × 1.09^2 = "},{"text":"₦105,515","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Choice depends on the rate.","italic":true},{"text":" ₦100,000 at time 1 against ₦130,000 at time 4:"}]},{"type":"table","header":[[{"text":"Rate"}],[{"text":"PV of ₦100,000 at time 1"}],[{"text":"PV of ₦130,000 at time 4"}],[{"text":"Better"}]],"rows":[[[{"text":"5%"}],[{"text":"₦95,238"}],[{"text":"₦106,951"}],[{"text":"later sum"}]],[[{"text":"10%"}],[{"text":"₦90,909"}],[{"text":"₦88,792"}],[{"text":"earlier sum"}]]]},{"type":"paragraph","text":[{"text":"Sensitivity.","italic":true},{"text":" ₦100,000 at the end of each of 3 years: PV is 100,000 a_3| = ₦267,301 at 6% but ₦240,183 at 12%, a fall of ₦27,118. Two streams equal in value at one rate are no longer equal at a higher rate: the one paying mostly later now has the "},{"text":"lower","bold":true},{"text":" PV. Comparing values at a later date: if two streams have PVs of P_1 and P_2, their values at time t differ by (P_1 − P_2)(1 + i)^t."}]}]},{"number":"6.5","title":"Net present value, internal rate of return and payback","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net present value (NPV):","bold":true},{"text":" PV of inflows minus PV of outflows at a chosen rate: NPV = C_0 + C_1 v + C_2 v^2 + ... + C_n v^n, outflows negative."}]},{"text":[{"text":"Decision rule:","bold":true},{"text":" NPV > 0, accept (it earns more than the required rate); NPV < 0, reject (it earns less than the required rate); NPV = 0, it earns exactly that rate."}]},{"text":[{"text":"Internal rate of return (IRR), or yield:","bold":true},{"text":" the discount rate at which NPV = 0 (the equation of value is satisfied). For a bond, the yield to redemption (redemption yield) is the IRR of buying it."}]},{"text":[{"text":"Hurdle rate:","bold":true},{"text":" the minimum IRR required on a project to compensate for its risk. Accept if IRR exceeds the hurdle rate."}]},{"text":[{"text":"If NPV is positive at i_1 and negative at i_2, the IRR lies "},{"text":"between","bold":true},{"text":" i_1 and i_2. Estimate by linear interpolation: IRR ≈ i_1 + (i_2 − i_1) × NPV_1 ÷ (NPV_1 − NPV_2)."}]},{"text":[{"text":"Payback period:","bold":true},{"text":" time needed to recover the cost from undiscounted cash flows; it ignores the time value of money."}]},{"text":[{"text":"Discounted payback period:","bold":true},{"text":" the number of years needed to recover the initial outlay after each cash flow has been discounted; the first year in which the cumulative discounted cash flow becomes positive."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"NPV.","italic":true},{"text":" A Lagos firm considers a machine costing ₦800,000 that returns ₦300,000 at the end of each of 3 years. At 10%: NPV = −800,000 + 300,000 × a_3| = −800,000 + 300,000 × 2.486852 = "},{"text":"−₦53,944","bold":true},{"text":". Reject: the project earns less than 10%, even though plain inflows (₦900,000) exceed the cost. With mixed flows, for example −₦300,000 at time 0 and −₦100,000 at time 1, discount every outflow too; an outflow at time 1 becomes −100,000/1.1."}]},{"type":"paragraph","text":[{"text":"IRR by quadratic.","italic":true},{"text":" A project costs ₦100,000 and returns ₦60,000 at time 1 and ₦72,000 at time 2. NPV = 0 gives 72,000v^2 + 60,000v − 100,000 = 0. Divide by 4,000: 18v^2 + 15v − 25 = 0. v = (−15 + √(225 + 1,800))/36 = (−15 + 45)/36 = 0.833333 (take the positive root). i = 1/v − 1 = "},{"text":"20%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"IRR by testing options.","italic":true},{"text":" If ₦100,000 now buys ₦55,000 at time 1 and ₦60,500 at time 2, test 10%: 55,000/1.1 + 60,500/1.21 = 50,000 + 50,000 = 100,000. NPV = 0, so the IRR is "},{"text":"10%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"IRR by bracketing.","italic":true},{"text":" Cost ₦400,000; returns ₦150,000, ₦200,000 and ₦120,000 at times 1, 2, 3. NPV at 8% = +₦5,617; at 10% = −₦8,189. So the IRR lies between 8% and 10%. Interpolation: 8% + 2% × 5,617/(5,617 + 8,189) = "},{"text":"8.81%","bold":true},{"text":" (true value 8.80%)."}]},{"type":"paragraph","text":[{"text":"Discounted payback.","italic":true},{"text":" Cost ₦600,000; ₦250,000 at the end of each year; 12%."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Discounted inflow"}],[{"text":"Cumulative"}]],"rows":[[[{"text":"1"}],[{"text":"223,214"}],[{"text":"−376,786"}]],[[{"text":"2"}],[{"text":"199,298"}],[{"text":"−177,487"}]],[[{"text":"3"}],[{"text":"177,945"}],[{"text":"+458"}]]]},{"type":"paragraph","text":[{"text":"Discounted payback = "},{"text":"year 3","bold":true},{"text":" (first positive cumulative). The ordinary payback is 600,000/250,000 = 2.4 years, shorter, because it ignores interest."}]},{"type":"paragraph","text":[{"text":"Largest loan.","italic":true},{"text":" A Nigerian microfinance bank charging 18% will lend at most the PV of what the borrower can repay. A borrower who can pay ₦100,000 at each of times 1 and 2 can be lent 100,000 × (1.18^(−1) + 1.18^(−2)) = "},{"text":"₦156,564","bold":true},{"text":" (nearest naira)."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Zero-coupon: one known payment at maturity. Fixed-interest (loan stock): known coupons plus redemption. Index-linked: amounts move with an index (base = index at purchase)."}]},{"text":[{"text":"PV = sum of C_t v^t; AV at n = sum of C_t (1 + i)^(n − t); value at t = PV × (1 + i)^t."}]},{"text":[{"text":"Convert the rate to the payment period, or use e^(−δt), (1 − d)^t or 1/(1 + rt) as given."}]},{"text":[{"text":"Equation of value: outgo = income at one date; under compound interest any date gives the same answer."}]},{"text":[{"text":"Solve for X directly, for t with logs, for i by quadratic or by testing options."}]},{"text":[{"text":"Changing rates: multiply period by period; later deposits earn only later rates."}]},{"text":[{"text":"Higher rate, lower PV; long-dated streams fall most."}]},{"text":[{"text":"NPV > 0 accept; IRR = yield = rate making NPV zero; NPV changing sign brackets the IRR."}]},{"text":[{"text":"Discounted payback: first year cumulative discounted cash flow is positive."}]}]}],"theory":{"itemId":"9183b89f-38d6-54e3-a6cf-d7d739aac07b","question":[{"type":"paragraph","text":[{"text":"A debt of ₦200,000 is due at time 3. It is to be settled by X at time 1 and X at time 2. At 10% per annum effective, find X."}]}]},"practice":[{"topic":"Present and Accumulated Values of Payment Streams","named":false}]}},{"itemId":"76212540-e7ee-5580-b2e3-490e47a81996","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Annuities and Annuity Functions","body":"The types of annuity and their symbols; a_n|, s_n|, ä_n|, s̈_n| and how they are linked; loans and savings funds; deferred annuities and perpetuities; m-thly and continuous annuities; increasing, decreasing and geometric annuities.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The types of annuity and their symbols; a_n|, s_n|, ä_n|, s̈_n| and how they are linked; loans and savings funds; deferred annuities and perpetuities; m-thly and continuous annuities; increasing, decreasing and geometric annuities."}],"lessons":[{"number":"7.1","title":"Types of annuity and their symbols","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity:","bold":true},{"text":" a series of payments made at regular intervals of time. As a contract, an annuity is an agreement with an insurance company that provides a series of payments at regular intervals for a number of years or over a lifetime."}]},{"text":[{"text":"Annuity-immediate:","bold":true},{"text":" payments at the "},{"text":"end","bold":true},{"text":" of each period (times 1, 2, ..., n). Also called an "},{"text":"ordinary annuity","bold":true},{"text":" or an "},{"text":"annuity in arrears","bold":true},{"text":"."}]},{"text":[{"text":"Annuity-due:","bold":true},{"text":" payments at the "},{"text":"start","bold":true},{"text":" of each period (times 0, 1, ..., n - 1). Also called an "},{"text":"annuity in advance","bold":true},{"text":"."}]},{"text":[{"text":"Deferred annuity:","bold":true},{"text":" payments do not begin immediately, or in the first period, but only after a period of postponement. Deferred m periods: payments at times m + 1, ..., m + n."}]},{"text":[{"text":"Perpetuity:","bold":true},{"text":" an annuity payable for an unlimited term; payments continue for ever, with no termination date."}]},{"text":[{"text":"Annuity-certain:","bold":true},{"text":" pays for a fixed term whatever happens."}]},{"text":[{"text":"Life (contingent) annuity:","bold":true},{"text":" pays only while a named life survives."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Whole-life annuity:","bold":true},{"text":" pays for as long as the person lives; payments stop at death."}]},{"text":[{"text":"Temporary life annuity for n years:","bold":true},{"text":" continues during the joint duration of the life of (x) and a term of n years certain, so it stops at death or after n years, whichever comes first."}]},{"text":[{"text":"Reversionary annuity:","bold":true},{"text":" an annuity on the life of (x) after the death of (y)."}]}]}]}]},{"type":"paragraph","text":[{"text":"The symbols (International Actuarial Notation)","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}]],"rows":[[[{"text":"a_n|"}],[{"text":"present value of an annuity-immediate of 1 per period for n periods"}]],[[{"text":"s_n|"}],[{"text":"accumulated value (amount) at time n of that annuity-immediate"}]],[[{"text":"ä_n| (a-double-dot)"}],[{"text":"present value of an annuity-due"}]],[[{"text":"s̈_n| (s-double-dot)"}],[{"text":"accumulated value at time n of an annuity-due"}]],[[{"text":"ā_n| (a-bar)"}],[{"text":"present value of a continuous annuity (payable continuously)"}]],[[{"text":"m|a_n|"}],[{"text":"present value of an annuity deferred m periods"}]],[[{"text":"a_∞| , ä_∞|"}],[{"text":"perpetuity-immediate, perpetuity-due"}]],[[{"text":"a^(m)_n| , ä^(m)_n|"}],[{"text":"annuity of 1 per period paid m-thly, in arrears or in advance"}]],[[{"text":"(Ia)_n| , (Da)_n| , (va)"}],[{"text":"increasing, decreasing and varying annuities"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a","bold":true},{"text":" = present value of an annuity; "},{"text":"s","bold":true},{"text":" = amount of an annuity; "},{"text":"A","bold":true},{"text":" = present value of an assurance (not an annuity)."}]},{"text":[{"text":"The "},{"text":"diaeresis","bold":true},{"text":" (two dots) over a or s is the symbol of "},{"text":"acceleration of payments","bold":true},{"text":": payments at the beginning of each period."}]},{"text":[{"text":"A "},{"text":"bar","bold":true},{"text":" over the principal symbol means "},{"text":"continuous","bold":true},{"text":" (momently) payment."}]},{"text":[{"text":"Sometimes the rate is shown as a subscript: a_n|i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"annuity-due\" is the odd one out. Annuity in arrears, ordinary annuity and annuity-immediate all mean end-of-period payments."}]},{"text":[{"text":"A tenant in Yaba paying rent of ₦400,000 at the beginning of each year for 3 years, starting today, is a 3-year annuity-due from the landlord's side."}]},{"text":[{"text":"Preference shares paying a fixed dividend every year with no redemption date are valued as a "},{"text":"perpetuity","bold":true},{"text":"."}]},{"text":[{"text":"A retiree's pension of ₦150,000 every month until death is a "},{"text":"whole-life (contingent) annuity","bold":true},{"text":". Under the Nigerian Contributory Pension Scheme, regulated by PenCom, a retiree can use the balance in a Retirement Savings Account to buy a life annuity from a life insurer."}]}]}]},{"number":"7.2","title":"Annuity-immediate: a_n| and s_n|","mustKnow":[{"type":"paragraph","text":[{"text":"With v = 1/(1 + i):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a_n| = v + v^2 + ... + v^n = (1 - v^n)/i = [1 - (1 + i)^-n]/i"}]},{"text":[{"text":"s_n| = (1 + i)^(n-1) + ... + (1 + i) + 1 = [(1 + i)^n - 1]/i"}]},{"text":[{"text":"s_n| = (1 + i)^n × a_n|"}]},{"text":[{"text":"Level payment P: PV = P × a_n|, FV (future value) = P × s_n| = P[(1 + i)^n - 1]/i."}]},{"text":[{"text":"Loan instalment","bold":true},{"text":" (first payment one period after the loan): X = Loan / a_n|."}]},{"text":[{"text":"Savings (sinking) fund","bold":true},{"text":" target F, deposits in arrears: X = F / s_n|."}]},{"text":[{"text":"Value at time t","bold":true},{"text":" (0 ≤ t ≤ n, just after the t-th payment) = s_t| + a_(n-t)| = (1 + i)^t a_n|."}]},{"text":[{"text":"Outstanding loan","bold":true},{"text":" just after the t-th instalment = X × a_(n-t)| (PV of the remaining instalments)."}]},{"text":[{"text":"Total interest","bold":true},{"text":" on a loan = n × X - Loan."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1 (PV and FV).","bold":true},{"text":" ₦100,000 at the end of each year for 5 years at 9%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"v^5 = 1.09^-5 = 0.649931, so a_5| = (1 - 0.649931)/0.09 = 3.8897 (4 d.p.)."}]},{"text":[{"text":"PV = 100,000 × 3.889651 = "},{"text":"₦388,965","bold":true},{"text":"."}]},{"text":[{"text":"s_5| = (1.538624 - 1)/0.09 = 5.9847; FV = "},{"text":"₦598,471","bold":true},{"text":". Check: 388,965 × 1.09^5 = 598,471."}]}]},{"type":"paragraph","text":[{"text":"Example 2 (loan).","bold":true},{"text":" A loan of ₦2,000,000 is repaid by 4 equal annual instalments in arrears at 12%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a_4| = (1 - 1.12^-4)/0.12 = (1 - 0.635518)/0.12 = 3.0373."}]},{"text":[{"text":"X = 2,000,000/3.037349 = "},{"text":"₦658,469","bold":true},{"text":"."}]},{"text":[{"text":"Just after the 1st instalment, the outstanding loan = X × a_3| = 658,468.87 × 2.401831 = "},{"text":"₦1,581,531","bold":true},{"text":"."}]},{"text":[{"text":"Total interest = 4 × 658,468.87 - 2,000,000 = "},{"text":"₦633,875","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Example 3 (savings fund).","bold":true},{"text":" A firm wants ₦1,000,000 in 6 years, depositing at the end of each year at 8%. s_6| = (1.586874 - 1)/0.08 = 7.3359. Deposit = 1,000,000/7.335929 = "},{"text":"₦136,315","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (how many payments).","bold":true},{"text":" ₦300,000 pays ₦40,000 at the end of each year for as long as possible at 6%. Need a_n| = 300,000/40,000 = 7.5. At 6%, a_10| = 7.3601 and a_11| = 7.8869, so "},{"text":"10 full payments","bold":true},{"text":" (a_11| is too big). The fund left at time 0 is 300,000 - 40,000 × 7.360087 = 5,596.52; at time 10 this is 5,596.52 × 1.06^10 = 5,596.52 × 1.790848 = "},{"text":"₦10,023","bold":true},{"text":", the extra amount paid with the 10th payment."}]},{"type":"paragraph","text":[{"text":"Example 5 (finding the rate).","bold":true},{"text":" a_10| = 7.3601 at some rate. Try values: at 6%, a_10| = 7.3601. So i = "},{"text":"6%","bold":true},{"text":". In a CBT, test each option in (1 - (1 + i)^-n)/i; a higher rate gives a smaller a_n|."}]},{"type":"paragraph","text":[{"text":"Example 6 (value at an intermediate time).","bold":true},{"text":" A 5-year annuity-immediate of 1 at 9%, valued just after the 2nd payment: s_2| + a_3| = 2.0900 + 2.5313 = "},{"text":"4.6213","bold":true},{"text":" (equal to 1.09^2 × 3.889651)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If a_n| is given, v^n = 1 - i × a_n|, and s_n| = (1 + i)^n × a_n| = a_n|/v^n. Example: a_n| = 10.5631 at 4% gives v^n = 1 - 0.04 × 10.5631 = 0.5775."}]},{"text":[{"text":"If only v is given, a_n| = v + v^2 + ... + v^n. With v = 0.95: a_4| = 0.95 + 0.9025 + 0.857375 + 0.814506 = "},{"text":"3.5244","bold":true},{"text":"."}]},{"text":[{"text":"Trap: [1 - (1 + i)^-n]/i is a PV; [(1 + i)^n - 1]/i is an FV. Expressions with (1 + i)^n in place of (1 + i)^-n in a PV are wrong."}]}]}]},{"number":"7.3","title":"Annuity-due and the key relationships","mustKnow":[{"type":"paragraph","text":[{"text":"With d = i/(1 + i) = 1 - v:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"ä_n| = 1 + v + ... + v^(n-1) = (1 - v^n)/d"}]},{"text":[{"text":"s̈_n| = [(1 + i)^n - 1]/d = (1 + i)^n × ä_n|"}]},{"text":[{"text":"ä_n| = (1 + i) × a_n|  and  s̈_n| = (1 + i) × s_n| (each payment is one period earlier)"}]},{"text":[{"text":"ä_n| = 1 + a_(n-1)| (a payment now plus an (n - 1)-payment annuity-immediate)"}]},{"text":[{"text":"s_(n+1)| = s̈_n| + 1 (an n-payment annuity-due from time 1 plus a final 1 at time n + 1)"}]},{"text":[{"text":"ä_n| - a_n| = 1 - v^n"}]},{"text":[{"text":"Splitting a term:","bold":true},{"text":" a_(m+n)| = a_m| + v^m a_n|;  s_(m+n)| = (1 + i)^n s_m| + s_n|."}]},{"text":[{"text":"For a positive rate, "},{"text":"ä_n| > a_n|","bold":true},{"text":" because each payment is received one period earlier; likewise s̈_n| > s_n|."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" At 5%, a_5| = 4.3295, so ä_6| = 1 + a_5| = "},{"text":"5.3295","bold":true},{"text":". Check: (1 - 1.05^-6)/d with d = 0.05/1.05 = 0.047619 gives 5.3295."}]},{"type":"paragraph","text":[{"text":"Example 2.","bold":true},{"text":" At 5%, s̈_6| = (1.340096 - 1)/0.047619 = 7.1420, so s_7| = s̈_6| + 1 = "},{"text":"8.1420","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (rent in advance).","bold":true},{"text":" A shop is let for 6 years at ₦250,000 at the beginning of each year, 5%. PV = 250,000 × 5.329477 = "},{"text":"₦1,332,369","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (d given).","bold":true},{"text":" d = 5%, so v = 0.95. ä_4| = (1 - 0.95^4)/0.05 = (1 - 0.814506)/0.05 = "},{"text":"3.7099","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (lease or deposit in advance).","bold":true},{"text":" Equal instalments at the start of each year: X = PV / ä_n|. A fund target F with deposits at the start of each year: X = F / s̈_n|, where s̈_n| measures the balance at time n, one year after the last deposit."}]},{"type":"paragraph","text":[{"text":"Example 6 (splitting).","bold":true},{"text":" At 10%, a_2| = 1.7355, a_3| = 2.4869, v^2 = 0.826446: a_5| = a_2| + v^2 a_3| = 1.7355 + 0.826446 × 2.4869 = "},{"text":"3.7908","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: s̈_n| = s_n|/(1 + i) is "},{"text":"wrong","bold":true},{"text":" (it is multiplied, not divided). ä_n| = 1 + a_n| is wrong (it is 1 + a_(n-1)|). a_(m+n)| = a_m| + a_n| is wrong (the second block must be discounted by v^m)."}]},{"text":[{"text":"Difference between due and immediate for ₦100,000 a year for 5 years at 10%: 100,000 × (1 - 1.1^-5) = 100,000 × 0.379079 = "},{"text":"₦37,908","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Deferred annuities and perpetuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Deferred annuity-immediate","bold":true},{"text":" (payments at m + 1, ..., m + n):"}],"blocks":[{"type":"paragraph","text":[{"text":"m|a_n| = v^m a_n| = a_(m+n)| - a_m| = (v^m - v^(m+n))/i."}]}]},{"text":[{"text":"Deferred annuity-due","bold":true},{"text":" (payments at m, ..., m + n - 1): m|ä_n| = v^m ä_n|."}]},{"text":[{"text":"If the first payment is at time k (in arrears), the deferment is m = k - 1."}]},{"text":[{"text":"Perpetuity-immediate:","bold":true},{"text":" a_∞| = 1/i. Reason: v < 1, so v^n tends to 0 as n tends to infinity in a_n| = (1 - v^n)/i."}]},{"text":[{"text":"Perpetuity-due:","bold":true},{"text":" ä_∞| = 1/d = (1 + i)/i = 1 + 1/i."}]},{"text":[{"text":"Deferred perpetuity","bold":true},{"text":" (first payment at time m + 1): v^m/i."}]},{"text":[{"text":"Payments from time n + 1 onwards: 1/i - a_n| = v^n/i."}]},{"text":[{"text":"Rate from a perpetuity:","bold":true},{"text":" i = payment / price (in arrears). If in advance, price = X + X/i, so i = X/(price - X)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" 2|a_3| at 10% (payments at times 3, 4, 5): v^2 a_3| = 0.826446 × 2.4869 = "},{"text":"2.0552","bold":true},{"text":". Check: a_5| - a_2| = 3.7908 - 1.7355 = 2.0553 (difference from rounding; 2.0552 to 4 d.p.)."}]},{"type":"paragraph","text":[{"text":"Example 2 (gift).","bold":true},{"text":" ₦100,000 at the end of each year for 3 years, the first at the end of year 3, at 10%: deferment m = 2, PV = 100,000 × 2.055250 = "},{"text":"₦205,525","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (perpetuities at 12%, ₦90,000 a year).","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"In arrears: 90,000/0.12 = "},{"text":"₦750,000","bold":true},{"text":"."}]},{"text":[{"text":"In advance (first payment today): 90,000 × 1.12/0.12 = "},{"text":"₦840,000","bold":true},{"text":"."}]},{"text":[{"text":"First payment at the end of year 5 (m = 4): 750,000 × 1.12^-4 = 750,000 × 0.635518 = "},{"text":"₦476,639","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Example 4 (rate).","bold":true},{"text":" ₦600,000 buys ₦45,000 a year in arrears for ever: i = 45,000/600,000 = "},{"text":"7.5%","bold":true},{"text":". ₦1,500,000 buys ₦100,000 a year with the first payment today: i = 100,000/1,400,000 = "},{"text":"7.14%","bold":true},{"text":" (2 d.p.)."}]},{"type":"paragraph","text":[{"text":"Example 5.","bold":true},{"text":" At 10%, payments of 1 from year 9 onwards: 1/0.1 - a_8| = 10 - 5.3349 = "},{"text":"4.6651","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If d is given, perpetuity-due = 1/d and perpetuity-immediate = 1/i = 1/d - 1. With d = 0.04: 25 and 24."}]},{"text":[{"text":"Trap: a_(m+n)| + a_m| is "},{"text":"not","bold":true},{"text":" a deferred annuity value; the correct form subtracts."}]}]}]},{"number":"7.5","title":"Annuities payable m-thly and continuously","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Payment period = interest period:","bold":true},{"text":" use the rate per payment period and the number of payments. 24% convertible monthly gives 2% a month."}]},{"text":[{"text":"Periods differ:","bold":true},{"text":" first find the "},{"text":"effective rate j per payment period","bold":true},{"text":", then use a_n|j."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Payments less often than interest (e.g. half-yearly payments, interest quarterly): j = (1 + i^(4)/4)^2 - 1."}]},{"text":[{"text":"Payments more often than interest (e.g. quarterly payments, interest half-yearly): j = (1 + i^(2)/2)^(1/2) - 1."}]}]}]},{"text":[{"text":"m-thly formulae","bold":true},{"text":" (1/m paid every 1/m of a year, total 1 a year, i effective annual):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"a^(m)_n| = (1 - v^n)/i^(m), where i^(m) = m[(1 + i)^(1/m) - 1]"}]},{"text":[{"text":"ä^(m)_n| = (1 - v^n)/d^(m), where d^(m) = m[1 - (1 + i)^(-1/m)]"}]},{"text":[{"text":"s^(m)_n| = [(1 + i)^n - 1]/i^(m); a^(m)_n| = (i/i^(m)) a_n|."}]}]}]},{"text":[{"text":"Continuous annuity:","bold":true},{"text":" ā_n| = (1 - v^n)/δ, with δ = ln(1 + i)."}]},{"text":[{"text":"Order for the same i > 0 and 1 a year: a_n| < a^(m)_n| < ā_n| < ä^(m)_n| < ä_n|."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1 (monthly).","bold":true},{"text":" ₦8,000 at the end of each month for 2 years at 12% convertible monthly. j = 1% a month, 24 payments: a_24| = (1 - 1.01^-24)/0.01 = 21.2434. PV = "},{"text":"₦169,947","bold":true},{"text":". Monthly loan instalments work the same way: X = Loan / a_(12n)| at the monthly rate."}]},{"type":"paragraph","text":[{"text":"Example 2 (payments less often).","bold":true},{"text":" ₦50,000 at the end of each half-year for 3 years at 12% convertible monthly. j = 1.01^6 - 1 = 0.061520 per half-year. PV = 50,000 × a_6|j = 50,000 × 4.8939 = "},{"text":"₦244,696","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (payments more often).","bold":true},{"text":" ₦30,000 at the end of each quarter for 2 years at 12% convertible half-yearly. j = 1.06^(1/2) - 1 = 0.029563 per quarter. PV = 30,000 × a_8|j = 30,000 × 7.0327 = "},{"text":"₦210,980","bold":true},{"text":" (to the nearest naira, using unrounded factors)."}]},{"type":"paragraph","text":[{"text":"Example 4 (formula).","bold":true},{"text":" ₦60,000 a year paid as ₦5,000 at the end of each month for 5 years, 8% effective. i^(12) = 12(1.08^(1/12) - 1) = 0.077208; 1 - v^5 = 0.319417. a^(12)_5| = 0.319417/0.077208 = 4.1371. PV = 60,000 × 4.137075 = "},{"text":"₦248,225","bold":true},{"text":". Paid at the "},{"text":"start","bold":true},{"text":" of each month: d^(12) = 12(1 - 1.08^(-1/12)) = 0.076715, ä^(12)_5| = 4.1637, PV = "},{"text":"₦249,822","bold":true},{"text":". Note: multiply by the "},{"text":"annual","bold":true},{"text":" amount."}]},{"type":"paragraph","text":[{"text":"Example 5 (continuous).","bold":true},{"text":" ā_5| at 8%: δ = ln 1.08 = 0.076961, ā_5| = 0.319417/0.076961 = "},{"text":"4.1504","bold":true},{"text":". It lies between a_5| = 3.9927 and ä_5| = 4.3121."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: a^(m)_n| uses v^n (years) on top, not v^(mn), and i^(m) underneath, not i."}]}]}]},{"number":"7.6","title":"Increasing, decreasing, geometric and simple-interest annuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Increasing annuity-immediate","bold":true},{"text":" (1 at time 1, 2 at time 2, ..., n at time n):"}],"blocks":[{"type":"paragraph","text":[{"text":"(Ia)_n| = (ä_n| - n v^n)/i.  Increasing annuity-due: (Iä)_n| = (1 + i)(Ia)_n|."}]}]},{"text":[{"text":"Decreasing annuity-immediate","bold":true},{"text":" (n at time 1, n - 1 at time 2, ..., 1 at time n):"}],"blocks":[{"type":"paragraph","text":[{"text":"(Da)_n| = (n - a_n|)/i."}]}]},{"text":[{"text":"Arithmetic","bold":true},{"text":" (P at time 1, rising by D each period): PV = P a_n| + D(a_n| - n v^n)/i."}]},{"text":[{"text":"Geometric","bold":true},{"text":" (1 at time 1, rising by k each period, k ≠ i): PV = [1 - ((1 + k)/(1 + i))^n]/(i - k). Multiply by the first payment."}]},{"text":[{"text":"Varying annuity","bold":true},{"text":" (va): payments of any amounts; value each payment separately."}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" PV of 1 due at t is 1/(1 + rt), so a_n| = sum of 1/(1 + rt) for t = 1 to n. There is no neat formula. At the same rate it is "},{"text":"higher","bold":true},{"text":" than the compound value, because simple interest discounts later payments less."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" ₦10,000, ₦20,000, ₦30,000, ₦40,000 at the ends of years 1 to 4, at 10%. ä_4| = 3.4869, 4v^4 = 2.7321. (Ia)_4| = (3.4869 - 2.7321)/0.1 = 7.5480. PV = "},{"text":"₦75,480","bold":true},{"text":". Check: 10,000(1 × 0.9091 + 2 × 0.8264 + 3 × 0.7513 + 4 × 0.6830) agrees."}]},{"type":"paragraph","text":[{"text":"Example 2.","bold":true},{"text":" ₦40,000, ₦30,000, ₦20,000, ₦10,000 at 10%: (Da)_4| = (4 - 3.1699)/0.1 = 8.3013. PV = "},{"text":"₦83,013","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (arithmetic).","bold":true},{"text":" ₦50,000 at time 1, rising by ₦10,000 a year, 4 payments, 10%: 50,000 × 3.1699 + 10,000 × (3.1699 - 2.7321)/0.1 = 158,493 + 43,781 = "},{"text":"₦202,274","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (geometric).","bold":true},{"text":" ₦200,000 at time 1, rising 4% a year, 5 payments, 10%: (1.04/1.1)^5 = 0.755446; PV = 200,000 × (1 - 0.755446)/0.06 = "},{"text":"₦815,181","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (simple interest).","bold":true},{"text":" a_3| at 10% simple: 1/1.1 + 1/1.2 + 1/1.3 = 0.9091 + 0.8333 + 0.7692 = "},{"text":"2.5117","bold":true},{"text":"; at 10% compound a_3| = 2.4869, so the simple value is higher."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: (Ia)_n| has ä_n| (the due factor) in its formula; (Da)_n| has a_n| and n. Do not swap them."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity = regular payments. Immediate (ordinary, in arrears) pays at period ends; due (in advance) pays at period starts."}]},{"text":[{"text":"a_n| = (1 - v^n)/i; s_n| = [(1 + i)^n - 1]/i; ä_n| = (1 - v^n)/d; s̈_n| = [(1 + i)^n - 1]/d."}]},{"text":[{"text":"ä_n| = (1 + i)a_n| = 1 + a_(n-1)|; s_(n+1)| = s̈_n| + 1; ä_n| > a_n|."}]},{"text":[{"text":"Two dots = acceleration (in advance); bar = continuous; m| = deferred m periods."}]},{"text":[{"text":"Loan instalment = Loan/a_n|; fund deposit = Target/s_n|; outstanding loan = X × a_(remaining)|."}]},{"text":[{"text":"m|a_n| = v^m a_n| = a_(m+n)| - a_m|; perpetuity 1/i in arrears, 1/d in advance."}]},{"text":[{"text":"Different payment and interest periods: find the effective rate per payment period first."}]},{"text":[{"text":"a^(m)_n| = (1 - v^n)/i^(m); ā_n| = (1 - v^n)/δ."}]},{"text":[{"text":"(Ia)_n| = (ä_n| - n v^n)/i; (Da)_n| = (n - a_n|)/i; geometric [1 - ((1 + k)/(1 + i))^n]/(i - k)."}]},{"text":[{"text":"Certain annuities run a fixed term; life (contingent) annuities stop at death."}]}]}],"theory":{"itemId":"6c7131aa-8859-5ab1-853e-11d82c02ed25","question":[{"type":"paragraph","text":[{"text":"A company promises a manager ₦400,000 at the end of each year for 12 years, the first payment one year after she retires in 5 years' time. It funds this with 5 equal payments at the "},{"text":"beginning","bold":true},{"text":" of each year over the 5 years before retirement. At 7% effective, find the annual funding payment."}]}]},"practice":[{"topic":"Annuities and Annuity Functions","named":false}]}}]$expected_content$::jsonb,
  'introduction-actuarial-science: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('d1b6b70d-037b-5e9e-a4d4-17103525cc56')
  where kind = 'cbt_question'), 0,
  'introduction-actuarial-science: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = 'd1b6b70d-037b-5e9e-a4d4-17103525cc56' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"12dff160-d8f4-58c7-a4b0-6bd075efca19","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ba5baddc-773a-5e3d-8b0a-c9bdc7ba1ffa","sourceKey":"bank:ACS101:ANN-001","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial and financial mathematics, an annuity is best described as","options":["a payment made only when an insured event such as death occurs","a series of payments made at regular intervals of time","an irregular stream of cash flows of varying size and timing","a single lump sum paid at the end of a fixed term"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"An annuity is a series of payments made at regular intervals, for a fixed number of years or over a lifetime. Option D is a single payment, not a series. Option A describes an insurance (assurance) benefit, and option C misses the regular intervals that define an annuity."}},{"itemId":"f1b8aa86-7960-5a3c-a7f1-d88d281fe86f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e2f7f3fb-3dc2-5ac4-8d9a-dd726e0468fb","sourceKey":"bank:ACS101:ANN-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT another name for an annuity whose payments are made at the END of each period?","options":["Annuity in arrears","Annuity-due","Ordinary annuity","Annuity-immediate"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"An annuity-due pays at the BEGINNING of each period, so it is not a name for end-of-period payments. Annuity-immediate, ordinary annuity and annuity in arrears (options D, C and A) all mean the same thing: payments at the end of each period."}},{"itemId":"2393f798-71b7-5b54-ae65-21de163e63e7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9c82b42f-698b-5c8e-b0ed-e49daa618178","sourceKey":"bank:ACS101:ANN-003","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity of n level payments has its first payment at time 0 and its last payment at time n - 1 (time measured in payment periods). This annuity is called","options":["an annuity-immediate","an annuity-due","a deferred annuity","a perpetuity"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Payments at the beginning of each period, from time 0 to time n - 1, make an annuity-due. An annuity-immediate (option A) would pay at times 1 to n. A deferred annuity (option C) starts later than the first period, and a perpetuity (option D) never ends."}},{"itemId":"01ce03d2-b870-552e-ae39-78ab0e0054a8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"07924cd5-6c17-51bf-bef6-f6d9bd3781cc","sourceKey":"bank:ACS101:ANN-004","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity whose first payment is postponed so that the n payments fall at times m + 1, m + 2, ..., m + n is called","options":["an increasing annuity, with present value written (Ia)_n|","a perpetuity, with present value written a_inf|","a deferred annuity, with present value written m|a_n|","an annuity-due, with present value written a-double-dot_n|"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"When the first payment starts some time in the future, the annuity is deferred; with payments at m + 1 to m + n its present value is m|a_n| = v^m a_n|. Option D pays from time 0, option B has no end date, and option A is about payments that grow, not about postponement."}},{"itemId":"30a61cd6-88cf-50ea-86fa-d4d9a8ec65b9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d90cbc95-5693-5df0-a8ef-17cde5190e15","sourceKey":"bank:ACS101:ANN-005","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity is","options":["an annuity whose first payment is postponed for several periods","an annuity whose payments continue only while a named person is alive","an annuity whose payments increase by a fixed amount each period","an annuity whose payments continue for ever, with no termination date"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"A perpetuity has no termination date: the number of payments n tends to infinity. Option B describes a life annuity, option A a deferred annuity, and option C an increasing (varying) annuity."}},{"itemId":"8a1b3f4c-2be2-5a17-817f-05f4e8b83de9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5deddbc1-24be-5cf8-9715-7b247a291ae6","sourceKey":"bank:ACS101:ANN-006","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company has preference shares that pay a fixed dividend of N5 per share at the end of every year with no redemption date. For valuation, this dividend stream is best treated as","options":["a perpetuity","an annuity-due for n years","a temporary annuity","a life annuity"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Fixed dividends on a preference (preferred) share with no end date are the classic example of a stream that resembles a perpetuity. A temporary annuity or an n-year annuity-due (options C and B) would stop after a fixed term, and a life annuity (option D) depends on someone staying alive."}},{"itemId":"21b5ddaf-eacc-508c-9eb5-d7b66b8c1021","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"01f37b2e-1c3b-58ed-81d6-11d4e4a03a72","sourceKey":"bank:ACS101:ANN-007","parentItemId":null,"revision":1,"payload":{"prompt":"What is the key difference between an annuity-certain and a life (contingent) annuity?","options":["An annuity-certain uses compound interest; a life annuity uses simple interest","An annuity-certain pays for a fixed term whatever happens; a life annuity pays only while a named life survives","An annuity-certain has no end date; a life annuity always has a fixed end date","An annuity-certain pays at the start of each year; a life annuity pays at the end of each year"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"An annuity-certain pays for a fixed term of n years no matter what, while a life (contingent) annuity's payments depend on the survival of a person, written (x). Option D confuses this with arrears versus advance timing, which applies to both kinds. Options C and A are not true distinctions."}},{"itemId":"75292b98-2832-559f-bc2e-e22e72b0f6a0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"22136324-29af-5fbf-ac3d-b86d8f4ebbde","sourceKey":"bank:ACS101:ANN-008","parentItemId":null,"revision":1,"payload":{"prompt":"A retired civil servant in Ibadan buys a contract that pays her N150,000 at the end of every month for as long as she lives, and payments stop at her death. This is","options":["a perpetuity","a deferred annuity-certain","an annuity-certain","a whole-life annuity (a contingent annuity)"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Payments that run for the rest of her lifetime and stop at death form a whole-life annuity, which is contingent on survival. Option C is wrong because an annuity-certain pays for a fixed term regardless of death. A perpetuity (option A) never stops, and nothing here is postponed or fixed-term as option B suggests."}},{"itemId":"979c34d9-00ec-5ba3-b628-b4f606b7201f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"72a16042-5b32-5fa4-8208-5257aa00d020","sourceKey":"bank:ACS101:ANN-009","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity payable to a life aged x that continues during the joint duration of the life of (x) and a term of n years certain (that is, payments stop at death or after n years, whichever comes first) is called","options":["a reversionary annuity","a temporary life annuity for n years","an n-year annuity-certain","a whole-life annuity"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Payments that last for n years at most and stop earlier if (x) dies form a temporary life annuity. A whole-life annuity (option D) has no n-year limit, and an annuity-certain (option C) ignores death. A reversionary annuity (option A) starts on the death of another life."}},{"itemId":"35a43767-534c-5d37-9c92-72b99ec5913a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bdbda56f-8a75-5183-977a-9e7a107537a0","sourceKey":"bank:ACS101:ANN-010","parentItemId":null,"revision":1,"payload":{"prompt":"In International Actuarial Notation, the diaeresis (two dots) placed over the letter a or s, as in the annuity-due symbol a-double-dot_n|, indicates","options":["that payments are made continuously throughout the period","acceleration of payments, i.e. payments made at the beginning of each period","that the payments increase by 1 each period","that the annuity depends on the survival of a life"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"The two dots (trema) symbolise acceleration of payments: each payment is brought forward to the start of the period, giving the annuity-due. Option A is shown by a bar over the symbol, option D by an age suffix such as x, and option C by the prefix I in (Ia)."}},{"itemId":"0fb43eaf-1e60-5dd2-b77a-ea02aaf4afec","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bfcf4b8a-a402-5428-9125-dd83754b88cf","sourceKey":"bank:ACS101:ANN-011","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation, a_n| and s_n| (interest effective per period, payments of 1 at the end of each period) stand for","options":["the present value and the accumulated value (amount) of the annuity respectively","the present value of an annuity and the present value of an assurance respectively","the annual payment and the number of payments respectively","the accumulated value and the present value of the annuity respectively"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The letter a stands for the present value of an annuity, valued at the start, and s stands for its amount, the accumulated value at the end of the term. Option D reverses the two. Option B confuses s with A, the symbol for an assurance, and option C mixes the symbols up with the inputs of the formula."}},{"itemId":"5cbaed50-a58e-50f7-bc96-4d52ada8cd7f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6dc4a6af-143f-55aa-aca9-78f720da7e7e","sourceKey":"bank:ACS101:ANN-012","parentItemId":null,"revision":1,"payload":{"prompt":"With v = 1/(1 + i), the expression (1 - v^n)/i gives","options":["the present value of an n-period annuity-immediate of 1 per period","the accumulated value of an n-period annuity-immediate of 1 per period","the present value of an n-period annuity-due of 1 per period","the present value of a perpetuity of 1 per period"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"(1 - v^n)/i = v + v^2 + ... + v^n, the sum of the present values of payments of 1 at times 1 to n, which is a_n|. Option B is ((1 + i)^n - 1)/i. Option C would use d instead of i in the denominator, and option D is 1/i."}},{"itemId":"06671321-be63-528b-8b85-c23fd5ee4424","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d11b55d4-18c8-5fb6-9030-b2a126a5adcc","sourceKey":"bank:ACS101:ANN-013","parentItemId":null,"revision":1,"payload":{"prompt":"With d = i/(1 + i), the expression ((1 + i)^n - 1)/d gives","options":["the accumulated value at time n of an n-period annuity-due of 1 per period","the present value at time 0 of an n-period deferred annuity","the accumulated value at time n of an n-period annuity-immediate of 1 per period","the present value at time 0 of an n-period annuity-due of 1 per period"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Dividing ((1 + i)^n - 1) by d instead of by i gives s-double-dot_n|, the accumulated value of an annuity-due, which is (1 + i) times s_n|. Option C is the same numerator over i. Option D is (1 - v^n)/d, a present value, and option B is v^m a_n|."}},{"itemId":"85577c2d-154c-51d8-9dff-7e539895fa8c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f669586f-82eb-52c3-bac6-1891d984cd51","sourceKey":"bank:ACS101:ANN-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following relationships between annuity functions (rate i per period, v = 1/(1 + i)) is NOT correct?","options":["a-double-dot_n| (annuity-due) = 1 + a_(n-1)|","s_n| = (1 + i)^n a_n|","a-double-dot_n| (annuity-due) = (1 + i) a_n|","s-double-dot_n| (annuity-due) = s_n| / (1 + i)"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Each annuity-due payment is made one period earlier than the matching annuity-immediate payment, so it earns one extra period of interest: s-double-dot_n| = (1 + i) s_n|, not s_n| divided by (1 + i). Options C, B and A are all correct relationships."}},{"itemId":"1f6ffa6a-a5e9-5020-bda1-9b4f98c184e1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dc7926f2-d1b9-5512-9e33-13b9c2c7d91e","sourceKey":"bank:ACS101:ANN-015","parentItemId":null,"revision":1,"payload":{"prompt":"An n-payment annuity-due can be split into a payment of 1 at time 0 plus an annuity-immediate of n - 1 payments. Which identity follows from this?","options":["a-double-dot_n| = 1 + a_n|","a-double-dot_n| = a_(n+1)| - 1","a-double-dot_n| = 1 + a_(n-1)|","a-double-dot_n| = a_(n-1)| - 1"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Payment at time 0 is worth 1, and the remaining n - 1 payments at times 1 to n - 1 are worth a_(n-1)|, so a-double-dot_n| = 1 + a_(n-1)|. Option A counts n + 1 payments. Option B borrows the accumulated-value identity s-double-dot_n| = s_(n+1)| - 1, which does not carry over to present values, and option D subtracts the time-0 payment instead of adding it."}},{"itemId":"09899aac-b4ae-5e7d-a50c-12ea07440141","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5feb067d-e4d4-53ec-8e92-d7424affdcfb","sourceKey":"bank:ACS101:ANN-016","parentItemId":null,"revision":1,"payload":{"prompt":"Viewing an (n + 1)-payment annuity-immediate as an n-payment annuity-due starting at time 1 plus a final payment of 1 at time n + 1 gives which accumulated-value identity?","options":["s_(n+1)| = (1 + i) s_n|","s_(n+1)| = s_n| + 1","s_(n+1)| = s-double-dot_n| - 1","s_(n+1)| = s-double-dot_n| + 1"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Valued at time n + 1, the first n payments accumulate to s-double-dot_n| and the last payment adds exactly 1, so s_(n+1)| = s-double-dot_n| + 1. Option C has the wrong sign. Option B forgets the extra interest on the earlier payments, and option A is the formula for s-double-dot_n|, not for s_(n+1)|."}},{"itemId":"90ad16db-ffac-597e-9986-a8698266d874","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4315bee7-557f-5c80-bb57-503aa2331143","sourceKey":"bank:ACS101:ANN-017","parentItemId":null,"revision":1,"payload":{"prompt":"For a deferred annuity of 1 per period with payments at times m + 1, ..., m + n (interest i per period), which expression is NOT equal to its present value m|a_n|?","options":["(v^m - v^(m+n))/i","a_(m+n)| + a_m|","a_(m+n)| - a_m|","v^m a_n|"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"The deferred annuity is an (m + n)-payment annuity with the first m payments removed, so m|a_n| = a_(m+n)| - a_m| = v^m a_n| = (v^m - v^(m+n))/i. Adding a_m| instead of subtracting it counts the missing payments twice. Options D, C and A are all valid forms."}},{"itemId":"0cea7059-4394-5058-b2ad-a83b908f4190","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"88b2d9df-0e71-583c-8888-11d6f9d7ea86","sourceKey":"bank:ACS101:ANN-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which identity correctly splits an (m + n)-period annuity-immediate (interest i per period) into two parts?","options":["a_(m+n)| = v^m a_m| + a_n|","a_(m+n)| = a_m| + v^m a_n|","a_(m+n)| = a_m| + a_n|","a_(m+n)| = a_m| + (1 + i)^m a_n|"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"The first m payments are worth a_m|, and the last n payments form an annuity starting at time m, worth a_n| at time m and v^m a_n| at time 0. Option C forgets to discount the second block. Option D accumulates instead of discounting, and option A discounts the wrong block."}},{"itemId":"c7b300fb-bccc-5d6e-9703-581165e26aa4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fa3a0594-7959-5d6e-9941-1e49917262f0","sourceKey":"bank:ACS101:ANN-019","parentItemId":null,"revision":1,"payload":{"prompt":"Why is the present value of a perpetuity-immediate of 1 per period equal to 1/i (for i > 0)?","options":["Because the last payment is ignored when there are many payments","Because (1 + i)^n tends to 1 as n tends to infinity","Because v < 1, so v^n tends to 0 as n tends to infinity in a_n| = (1 - v^n)/i","Because the payments become smaller each period"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Since v = 1/(1 + i) is less than 1, v^n shrinks to 0 as n grows, so a_n| = (1 - v^n)/i approaches 1/i. Option B is false since (1 + i)^n grows without limit. The payments stay level (option D), and a perpetuity has no last payment (option A)."}},{"itemId":"0b58223e-0f07-5680-a1bd-657b2de81313","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a1fd578a-b53d-5913-b97e-8b33f46762d2","sourceKey":"bank:ACS101:ANN-020","parentItemId":null,"revision":1,"payload":{"prompt":"The present value of a perpetuity-due of 1 per period (first payment immediately, interest i per period, d = i/(1 + i)) is","options":["1/d","1/i","1/(1 + i)","i/d"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Letting n tend to infinity in a-double-dot_n| = (1 - v^n)/d gives a-double-dot_inf| = 1/d. Option B, 1/i, is the perpetuity-immediate. Option C is just v, and option D equals 1 + i, which is not a present value of an infinite stream."}},{"itemId":"f5c34eda-77e2-51a0-9fc6-5b0f668bf645","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0a4299f7-2dc6-5a3a-8a6e-5cf5a8f2fca8","sourceKey":"bank:ACS101:ANN-021","parentItemId":null,"revision":1,"payload":{"prompt":"For the same positive rate of interest and the same number of level payments, which statement is correct?","options":["a_n| and a-double-dot_n| (annuity-due) are always equal, because they have the same number of payments","a-double-dot_n| (annuity-due) is greater than a_n|, because each payment is received one period earlier","a-double-dot_n| (annuity-due) is smaller than a_n|, because d is smaller than i","a_n| is greater than a-double-dot_n| (annuity-due), because each payment earns one more period of interest"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Each annuity-due payment comes one period sooner, so it is discounted less and a-double-dot_n| = (1 + i) a_n| is larger. Option D reverses the logic, option A ignores timing, and option C draws the wrong conclusion: dividing by the smaller d makes the annuity-due value larger, not smaller."}},{"itemId":"c11217c6-e093-5aa7-8f47-5ece0b44b9bc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"256ae0bb-2138-530b-951d-9169c6c2ad56","sourceKey":"bank:ACS101:ANN-022","parentItemId":null,"revision":1,"payload":{"prompt":"A tenant in Yaba pays rent of N400,000 at the beginning of each year for 3 years, starting today. Viewed from the landlord's side today, this stream is","options":["a perpetuity","a 3-year annuity-immediate","a 3-year annuity-due","a 3-year deferred annuity"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Rent paid at the start of each period, beginning today, is a standard annuity-due, valued with a-double-dot_3|. An annuity-immediate (option B) would start at the end of the first year. Nothing is postponed, so option D is wrong, and the stream ends after 3 years, unlike option A."}},{"itemId":"033a36dc-20e1-55d8-bf9f-4ad3c8b4a38e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b312dc19-10d2-5104-a95d-93ca93acb0f5","sourceKey":"bank:ACS101:ANN-023","parentItemId":null,"revision":1,"payload":{"prompt":"Let i^(m) be the nominal annual rate convertible m times a year equivalent to an effective annual rate i. The present value of an n-year annuity paying 1/m at the end of every 1/m of a year (a total of 1 per year) is","options":["a^(m)_n| = (1 - v^(mn))/i^(m)","a^(m)_n| = (1 - v^n)/d^(m)","a^(m)_n| = (1 - v^n)/i^(m)","a^(m)_n| = (1 - v^n)/i"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Paying m times a year in arrears gives a^(m)_n| = (1 - v^n)/i^(m) = (i/i^(m)) a_n|. Option D is the annual-payment a_n|. Option A wrongly raises v to mn even though v is the annual discount factor, and option B, with d^(m), is the m-thly annuity-due."}},{"itemId":"7341222d-b12f-5cd9-aa76-dd6b03991977","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e2f4cb96-5f16-5fef-8989-0587f61f3c98","sourceKey":"bank:ACS101:ANN-024","parentItemId":null,"revision":1,"payload":{"prompt":"With delta = ln(1 + i) the force of interest, the expression (1 - v^n)/delta gives the present value of","options":["an n-year annuity-due of 1 per year","an n-year annuity-immediate of 1 per year","an n-year annuity paid monthly in advance, 1 per year","an n-year annuity paid continuously at the rate of 1 per year"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Letting the payment frequency m tend to infinity makes i^(m) approach delta, giving the continuous annuity a-bar_n| = (1 - v^n)/delta = (i/delta) a_n|. Options A and B use d and i in the denominator respectively. Option C would use d^(12)."}},{"itemId":"0407ee28-e9ab-5508-bcce-04d38d35a530","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7a90db6e-51c3-5e5e-b5dc-a5e4ae089ef2","sourceKey":"bank:ACS101:ANN-025","parentItemId":null,"revision":1,"payload":{"prompt":"An n-year increasing annuity-immediate (Ia)_n| (interest i per year, v = 1/(1 + i)) pays","options":["n at time 1, n - 1 at time 2, ..., 1 at time n, with value (n - a_n|)/i","1 at time 0, 2 at time 1, ..., n at time n - 1, with value (n - a_n|)/i","1 at each of times 1, 2, ..., n, with value (1 - v^n)/i","1 at time 1, 2 at time 2, ..., n at time n, with value (a-double-dot_n| - n v^n)/i"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"The increasing annuity-immediate pays 1, 2, ..., n at the end of years 1 to n, and its present value is (Ia)_n| = (a-double-dot_n| - n v^n)/i. Option A is the decreasing annuity (Da)_n|. Option B describes the increasing annuity-due timing but attaches the (Da) formula, and option C is a level annuity."}},{"itemId":"a9a74a06-2d4f-5905-8e1e-d30559cff682","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1eaafd4-b1e2-5695-9a1b-d67ad8a616f0","sourceKey":"bank:ACS101:ANN-026","parentItemId":null,"revision":1,"payload":{"prompt":"At the same nominal rate r per year, how does the value of a_3| under SIMPLE interest compare with a_3| under COMPOUND interest (payments of 1 at the end of each year)?","options":["The two present values are always equal for any n","The simple-interest present value is lower, because simple interest discounts later payments more","The comparison depends only on whether payments are in advance or in arrears","The simple-interest present value is higher, because simple interest discounts later payments less"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"At the same nominal rate, compound interest grows faster than simple interest after the first year, so compound discounting makes later payments smaller and the compound a_3| is lower. For example, at 5% the simple-interest value is 2.731 against 2.723 under compound interest. Options B and A are wrong for n > 1, and the timing in option C is not the cause."}},{"itemId":"7d9e0ce3-0b2b-5c67-88a8-8bbaa70d76d8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7fc96e1d-8c62-504e-baef-555d2bf82b47","sourceKey":"bank:ACS101:ANN-027","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate a_8| at an effective rate of interest of 6% per annum (payments of 1 at the end of each year). Give your answer to 4 decimal places.","options":["5.5824","6.5824","6.2098","9.8975"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"a_8| = (1 - (1.06)^-8)/0.06 = 6.2098. Option B is the annuity-due value, (1.06) x a_8|, which treats the payments as made in advance. Option D is s_8|, the accumulated value, and option A uses only 7 payments."}},{"itemId":"164da524-ea36-5443-9d21-bbc479928565","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2062d360-2969-5d4a-ad07-193a7a511b8f","sourceKey":"bank:ACS101:ANN-028","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate s_6| at an effective rate of interest of 7% per annum (payments of 1 at the end of each year, value at time 6). Give your answer to 4 decimal places.","options":["4.7665","7.0500","7.6540","7.1533"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"s_6| = ((1.07)^6 - 1)/0.07 = 7.1533. Option A is a_6|, the present value rather than the accumulated value. Option C is s-double-dot_6|, the annuity-due amount, and option B uses simple interest on the average payment."}},{"itemId":"c1251a15-26a4-5a27-b4c6-be6bf62282cb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"aacc71f6-2f60-5d5f-bae5-46c290171509","sourceKey":"bank:ACS101:ANN-029","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate the annuity-due factor a-double-dot_10| (payments of 1 at the beginning of each year for 10 years) at an effective rate of 5% per annum. Give your answer to 4 decimal places.","options":["8.7217","7.7217","7.3540","8.1078"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"a-double-dot_10| = (1 - v^10)/d = (1.05) a_10| = 1.05 x 7.7217 = 8.1078. Option B is a_10|, the annuity-immediate. Option A uses 1 + a_10| instead of 1 + a_9|, counting 11 payments. Option C discounts one extra period instead of one fewer."}},{"itemId":"5a16e826-684b-562f-8b56-2f1dbc8f81ef","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"47e73386-6dfc-54ed-88f3-6fcbbdc2e5b9","sourceKey":"bank:ACS101:ANN-030","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate s-double-dot_5| (the accumulated value at time 5 of an annuity-due of 1 per year for 5 years) at an effective rate of 8% per annum. Give your answer to 4 decimal places.","options":["5.8666","7.3359","6.3359","4.3121"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"s-double-dot_5| = ((1.08)^5 - 1)/d with d = 0.08/1.08, which equals (1.08) s_5| = 1.08 x 5.8666 = 6.3359. Option A is s_5|, which treats the payments as made in arrears. Option B is s_6|, which equals s-double-dot_5| + 1, and option D is the present value a-double-dot_5|."}},{"itemId":"72b60cac-f01b-58e1-a670-0eba8f32440e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f52859fa-5c76-5e7b-bd2d-07908ab93f35","sourceKey":"bank:ACS101:ANN-031","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund will pay N50,000 at the end of each year for 6 years. Using an effective interest rate of 10% per annum, find the present value of these payments to the nearest naira.","options":["N217,763","N385,781","N239,539","N169,342"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"PV = 50,000 a_6| = 50,000 x (1 - (1.1)^-6)/0.1 = 50,000 x 4.35526 = N217,763. Option C values the payments in advance (annuity-due). Option D discounts all six payments as if they were paid at time 6, and option B is the accumulated value."}},{"itemId":"f063e523-6eed-597b-a7f0-7e404e2a0021","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3be3a8d3-be76-52aa-b43b-04257c24a60b","sourceKey":"bank:ACS101:ANN-032","parentItemId":null,"revision":1,"payload":{"prompt":"A worker saves N20,000 at the end of each year for 8 years in an account paying 9% effective per annum. What is the accumulated value immediately after the 8th deposit, to the nearest naira?","options":["N184,009","N210,400","N220,569","N240,421"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"AV = 20,000 s_8| = 20,000 x ((1.09)^8 - 1)/0.09 = 20,000 x 11.02847 = N220,569. Option D treats the deposits as made at the start of each year (s-double-dot_8|). Option B uses simple interest on the average deposit, and option A counts only 7 deposits."}},{"itemId":"f749f898-ec7c-58bb-970d-2d7dbbe17e84","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9995017d-1882-579e-8a45-527c9f138c8e","sourceKey":"bank:ACS101:ANN-033","parentItemId":null,"revision":1,"payload":{"prompt":"A shop in Surulere is let for 5 years at a rent of N300,000 payable at the beginning of each year. At an effective rate of 12% per annum, find the present value of the rent at the start of the lease, to the nearest naira.","options":["N1,081,433","N1,211,205","N911,205","N1,500,000"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Rent in advance is an annuity-due: PV = 300,000 a-double-dot_5| = 300,000 x 1.12 x a_5| = 300,000 x 4.03735 = N1,211,205. Option A values the rent in arrears (a_5|). Option D ignores interest altogether, and option C values only the last four payments and forgets the one paid today."}},{"itemId":"9f021175-5aad-5320-bfc1-9163096693c6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"70566efb-9a69-557d-a0d9-663119880e10","sourceKey":"bank:ACS101:ANN-034","parentItemId":null,"revision":1,"payload":{"prompt":"A student deposits N10,000 at the beginning of each year for 6 years into an account earning 8% effective per annum. What is the balance at the end of the 6th year (one year after the last deposit), to the nearest naira?","options":["N73,359","N89,228","N79,228","N49,927"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Deposits in advance accumulate as an annuity-due: AV = 10,000 s-double-dot_6| = 10,000 x 1.08 x s_6| = 10,000 x 7.9228 = N79,228. Option A is s_6|, which assumes end-of-year deposits. Option D is the present value, and option B is s_7|, which equals s-double-dot_6| + 1 and so wrongly adds one more deposit."}},{"itemId":"7972c38e-6025-5dfa-a56f-08cd6bfc51c1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"597c9e3f-7d8d-54e1-8983-d1b601834bae","sourceKey":"bank:ACS101:ANN-035","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N1,000,000 is to be repaid by 5 equal annual instalments, the first one year after the loan is taken. Interest is 15% effective per annum. Find the annual instalment to the nearest naira.","options":["N298,316","N230,000","N259,405","N148,316"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Instalments in arrears: P = 1,000,000/a_5| = 1,000,000/3.35216 = N298,316. Option C divides by a-double-dot_5|, which treats the first instalment as due immediately. Option B adds one year of simple interest to one-fifth of the loan, and option D divides by s_5|, which gives a sinking-fund deposit, not a loan repayment."}},{"itemId":"5727998e-06b5-5ac2-9141-d3235513cd8e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"91e08984-2613-5523-b06a-deaa21d7fbcf","sourceKey":"bank:ACS101:ANN-036","parentItemId":null,"revision":1,"payload":{"prompt":"A trader borrows N600,000 at a nominal rate of 24% per annum convertible monthly. She repays it with 12 equal monthly instalments, the first one month after the loan. Find the monthly instalment to the nearest naira.","options":["N62,000","N155,789","N56,736","N55,623"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The monthly rate is 24%/12 = 2%, so P = 600,000/a_12| at 2% = 600,000/10.5753 = N56,736. Option B wrongly uses 24% as the monthly rate. Option A adds a year of simple interest and divides by 12, and option D treats the instalments as paid in advance."}},{"itemId":"2aa3328e-ad6e-577e-9497-66de123f0304","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9b65c1c2-5f0a-52d1-bd8e-5587ec21fefe","sourceKey":"bank:ACS101:ANN-037","parentItemId":null,"revision":1,"payload":{"prompt":"A company wants N2,000,000 in a fund in 5 years' time to replace a generator. It will make equal deposits at the end of each year into a fund earning 10% effective per annum. Find the annual deposit to the nearest naira.","options":["N297,814","N527,595","N400,000","N327,595"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Target = P s_5|, so P = 2,000,000/s_5| = 2,000,000/6.1051 = N327,595. Option B divides by a_5|, which gives the instalment that repays a loan of N2,000,000 today. Option A assumes deposits at the start of each year, and option C ignores interest."}},{"itemId":"35de13bc-ebda-5f34-b22f-a77b88bc62ef","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1d3965e-4cea-559a-9d45-0cf09be63c73","sourceKey":"bank:ACS101:ANN-038","parentItemId":null,"revision":1,"payload":{"prompt":"Parents want N500,000 available at the end of 4 years for school fees. They will deposit a level amount at the BEGINNING of each year for 4 years in an account earning 9% effective per annum. Find the annual deposit to the nearest naira.","options":["N141,591","N114,679","N109,334","N100,307"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Deposits in advance accumulate as an annuity-due: s-double-dot_4| = 1.09 x s_4| = 1.09 x 4.57313 = 4.98471, so P = 500,000/4.98471 = N100,307. Option C uses s_4|, which treats the deposits as made at year-end. Option A uses a present-value factor, and option B spreads the target equally and discounts it for one year only."}},{"itemId":"242496bf-f7a1-544b-8742-0123f5a16eb4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c2d07946-6d16-5f7a-aeff-5dfa74000969","sourceKey":"bank:ACS101:ANN-039","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate the deferred annuity factor 3|a_5| at an effective rate of 6% per annum (payments of 1 at times 4, 5, 6, 7 and 8). Give your answer to 4 decimal places.","options":["4.2124","3.5368","3.3366","8.8828"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"3|a_5| = v^3 a_5| = (1.06)^-3 x 4.2124 = 3.5368, which also equals a_8| - a_3|. Option C discounts for 4 years, as if the first payment were at time 5 rather than one year after the deferment. Option A ignores the deferment, and option D adds a_3| instead of subtracting it."}},{"itemId":"cfbb8acd-a089-575a-b261-afb17b716960","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"97baea82-dd14-56e0-a6f6-196806886c3f","sourceKey":"bank:ACS101:ANN-040","parentItemId":null,"revision":1,"payload":{"prompt":"A father arranges for his daughter to receive N100,000 at the end of each year for 4 years, with the first payment at the end of year 6. At 10% effective per annum, find the present value today to the nearest naira.","options":["N216,506","N196,824","N316,987","N178,931"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"The first payment is at time 6, so this is 5|a_4|: PV = 100,000 x (1.1)^-5 x a_4| = 100,000 x 0.62092 x 3.16987 = N196,824. Option D defers 6 years, treating time 6 as the start of the deferred period. Option C ignores the deferment, and option A defers only 4 years, which would put the first payment at time 5."}},{"itemId":"48155588-5be3-5b2c-a199-21fdd937444b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"79485acc-b24d-5db2-ab23-b2866bb3220e","sourceKey":"bank:ACS101:ANN-041","parentItemId":null,"revision":1,"payload":{"prompt":"At 6% effective per annum, a_10| = 7.3601 and a_4| = 3.4651. Using these values, find 4|a_6| (an annuity of 1 per year for 6 years, first payment at time 5). Give your answer to 4 decimal places.","options":["3.0852","4.9173","10.8252","3.8950"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Removing the first 4 payments from a 10-year annuity leaves payments at times 5 to 10, so 4|a_6| = a_10| - a_4| = 7.3601 - 3.4651 = 3.8950. Option C adds instead of subtracts. Option B is a_6| with no deferment, and option A discounts the difference a second time, even though a_10| - a_4| is already a value at time 0."}},{"itemId":"adaa916d-805e-5369-8159-108209a7bacf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0ff15a78-d5da-57ba-950c-18ab3fe95f83","sourceKey":"bank:ACS101:ANN-042","parentItemId":null,"revision":1,"payload":{"prompt":"An endowment fund will pay a prize of N80,000 at the end of every year for ever. At an effective rate of 8% per annum, how much must be invested today, to the nearest naira?","options":["N925,926","N86,400","N1,080,000","N1,000,000"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"A perpetuity-immediate is worth payment/i = 80,000/0.08 = N1,000,000. Option C is 80,000/d, which is the value if the first prize were paid today. Option B is just one payment with a year's interest, and option A discounts the perpetuity one extra year."}},{"itemId":"c9caef6b-ed69-5093-a155-513cfcc1a9ba","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ea17604a-08ff-56a7-be7f-00b28b379dfa","sourceKey":"bank:ACS101:ANN-043","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG alumni association wants to fund a scholarship of N250,000 per year for ever, with the first award paid today. At an effective rate of 10% per annum, how much must the fund hold today, to the nearest naira?","options":["N2,272,727","N2,500,000","N3,000,000","N2,750,000"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Payments starting now form a perpetuity-due: PV = 250,000/d with d = 0.1/1.1, giving 250,000 x 11 = N2,750,000. Option B is the perpetuity-immediate value 250,000/0.1, which misses today's award. Option A discounts a further year, and option C counts today's award twice."}},{"itemId":"88615f14-2e30-57d7-90f4-5e6372934fb0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"efbc20e0-ee8a-5f86-a7b0-2b6f0ea3e693","sourceKey":"bank:ACS101:ANN-044","parentItemId":null,"revision":1,"payload":{"prompt":"A trust invests N5,000,000 today to pay N400,000 at the end of every year for ever. What effective annual rate of interest is the trust assuming?","options":["7.41%","12.50%","8.33%","8.00%"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"For a perpetuity-immediate, PV = P/i, so i = 400,000/5,000,000 = 8%. Option A is 0.08/1.08, which confuses the interest rate i with the discount rate d. Option B inverts the ratio as 5,000,000/400,000 = 12.5, and option C divides by 4,800,000, which assumes the first payment is made today."}},{"itemId":"271d3376-d9bc-56a4-8d16-3cfbed3b6a18","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ed4d27d0-5504-524b-8b3b-69d1ac68babe","sourceKey":"bank:ACS101:ANN-045","parentItemId":null,"revision":1,"payload":{"prompt":"A perpetuity pays N60,000 at the end of each year, but the first payment is made at the end of year 4. At 10% effective per annum, find its present value today to the nearest naira.","options":["N600,000","N450,789","N409,808","N495,868"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"The perpetuity is worth 60,000/0.1 = 600,000 at time 3 (one year before the first payment), so PV = 600,000 x (1.1)^-3 = N450,789. Option C discounts 4 years, treating 600,000 as a value at time 4. Option A ignores the deferment, and option D uses 1/d, which treats the perpetuity as starting at time 3 instead of time 4."}},{"itemId":"104dc09f-3101-53e9-9499-2d5d86a3d04c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ff7fadcc-0694-56e2-9a36-0941c3c0efc7","sourceKey":"bank:ACS101:ANN-046","parentItemId":null,"revision":1,"payload":{"prompt":"The rate of discount is d = 0.05 per annum, so that the present value of a perpetuity-due of 1 per year is 1/d = 20. What is the present value of a perpetuity-immediate of 1 per year at the same rate?","options":["19.00","19.05","20.00","21.00"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The perpetuity-due is the perpetuity-immediate plus a payment of 1 now, so a_inf| = a-double-dot_inf| - 1 = 20 - 1 = 19. Check: i = d/(1 - d) = 0.05/0.95 and 1/i = 19. Option D adds the extra payment instead of removing it, option C ignores timing, and option B uses i = 0.05 (which is d) and then divides by 1.05."}},{"itemId":"938a079f-a612-5ad1-ab55-1c32b177864d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f2ac5569-abe7-5860-a5c3-3cdabee94313","sourceKey":"bank:ACS101:ANN-047","parentItemId":null,"revision":1,"payload":{"prompt":"At 7% effective per annum, a_9| = 6.5152. Using this value, find a-double-dot_10| (an annuity-due of 1 per year for 10 years) to 4 decimal places.","options":["7.5152","6.9713","7.9713","7.5852"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"An annuity-due of 10 payments is a payment of 1 now plus an annuity-immediate of 9 payments: a-double-dot_10| = 1 + a_9| = 1 + 6.5152 = 7.5152. Option B gives a-double-dot_9|, which has the wrong number of payments. Option C wrongly converts a_9| to a due basis before adding 1, and option D adds 1.07 instead of 1."}},{"itemId":"9541f859-db1e-54b2-be1c-d83196609fde","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4e50ae72-4d55-5f83-9ef6-5875f2f1a5e5","sourceKey":"bank:ACS101:ANN-048","parentItemId":null,"revision":1,"payload":{"prompt":"At 5% effective per annum, s-double-dot_7| (annuity-due) = 8.5491. Find s_8| to 4 decimal places.","options":["7.5491","9.5491","8.1420","8.9766"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Using s_(n+1)| = s-double-dot_n| + 1, s_8| = 8.5491 + 1 = 9.5491. Option A subtracts 1. Option D accumulates s-double-dot_7| one more year, which misses the final payment of 1 at time 8. Option C is s_7|."}},{"itemId":"c34d6c60-de9d-5067-a1a6-f001910fa39c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3de2a1b-ae46-5451-a3f8-a68ba95c0235","sourceKey":"bank:ACS101:ANN-049","parentItemId":null,"revision":1,"payload":{"prompt":"At 4% effective per annum, a_12| = 9.3851. Find s_12| to 4 decimal places.","options":["15.0258","9.7605","5.8619","13.8899"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"s_12| = (1 + i)^12 a_12| = (1.04)^12 x 9.3851 = 15.0258. Option B accumulates for only one year, which gives a-double-dot_12|. Option C discounts instead of accumulating, and option D uses simple interest for 12 years."}},{"itemId":"df61cc4b-bf6a-5473-9bff-cab4a07c2b02","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"15961cf1-be8e-569e-9dec-8cd58a051255","sourceKey":"bank:ACS101:ANN-050","parentItemId":null,"revision":1,"payload":{"prompt":"At 4% effective per annum, a_n| = 10.5631 for some whole number n. Find v^n to 4 decimal places.","options":["0.5937","0.5775","0.7030","0.4225"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"From a_n| = (1 - v^n)/i, v^n = 1 - i a_n| = 1 - 0.04 x 10.5631 = 0.5775. Option D is i a_n| itself, which equals 1 - v^n. Option C wrongly inverts, and option A uses d = 0.04/1.04 in place of i."}},{"itemId":"a1f8f096-6184-5133-93fa-33b6c74aeff2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1312aaee-b4e1-5530-a392-5decbf2c8c55","sourceKey":"bank:ACS101:ANN-051","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N400,000 is used to pay N50,000 at the end of each year for as long as possible at 5% effective per annum. How many full payments of N50,000 can be made? (a_10| = 7.7217 and a_11| = 8.3064 at 5%.)","options":["9 payments","8 payments","10 payments","11 payments"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The equation of value 50,000 a_n| = 400,000 gives a_n| = 8, which lies between a_10| = 7.7217 and a_11| = 8.3064, so only 10 full payments are possible (a smaller final payment settles the rest). Option D needs a_11| = 8.3064, which is more than the N400,000 available. Option B ignores interest (400,000/50,000), and option A is one payment too few."}},{"itemId":"ae62403b-7537-5f2c-9be7-a5177836493a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f0139287-962d-5785-9026-918509294b43","sourceKey":"bank:ACS101:ANN-052","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N400,000 pays N50,000 at the end of each year for 10 years at 5% effective per annum. To exhaust the fund exactly, what EXTRA amount must be paid together with the 10th payment at the end of year 10? Give the answer to the nearest naira.","options":["N22,663","N72,663","N23,796","N13,913"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Extra amount = 400,000(1.05)^10 - 50,000 s_10| = 651,558 - 628,895 = N22,663. Option C is that amount carried one more year, which is the smaller final payment if it were paid alone at the end of year 11. Option D is the shortfall measured at time 0 (400,000 - 50,000 a_10|), not carried forward to time 10, and option B is the whole final payment (the regular N50,000 plus the extra), not the extra amount alone."}},{"itemId":"c9da78f0-c33a-5d9a-82a7-75fbed60d86d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"578ebb6e-dbd0-5244-a453-301b71ac3813","sourceKey":"bank:ACS101:ANN-053","parentItemId":null,"revision":1,"payload":{"prompt":"A 10-year annuity-immediate of N1 per year has a present value of 7.0236. At which effective annual rate of interest was it valued?","options":["8.00%","9.00%","6.00%","7.00%"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"At 7%, a_10| = (1 - (1.07)^-10)/0.07 = 7.0236, which matches. At 6% (option C) a_10| = 7.3601, at 8% (option A) it is 6.7101 and at 9% (option B) it is 6.4177. A higher rate always gives a lower present value."}},{"itemId":"0175ae5f-fbca-5abe-82f7-3a54c5452be0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b59dee88-d45f-5f99-812e-19e6edd96bd6","sourceKey":"bank:ACS101:ANN-054","parentItemId":null,"revision":1,"payload":{"prompt":"A contract pays N25,000 at the end of every quarter for 3 years. Interest is 12% per annum convertible quarterly. Find the present value at the start, to the nearest naira.","options":["N248,850","N240,183","N256,316","N154,859"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The quarterly rate is 12%/4 = 3% and there are 12 payments, so PV = 25,000 a_12| at 3% = 25,000 x 9.95400 = N248,850. Option B values annual payments of N100,000 at 12% effective, which is a different rate basis. Option C treats the payments as made in advance, and option D uses 12% as the quarterly rate."}},{"itemId":"bdde3cd1-d37c-50b8-a64a-97d3d6eacaa9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b62cb5ba-284c-589f-9f55-48c077b55925","sourceKey":"bank:ACS101:ANN-055","parentItemId":null,"revision":1,"payload":{"prompt":"A civil servant saves N5,000 at the end of each month for 2 years in a cooperative account paying 18% per annum convertible monthly. Find the accumulated value after the last deposit, to the nearest naira.","options":["N1,447,472","N141,600","N143,168","N145,315"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The monthly rate is 1.5% and there are 24 deposits: AV = 5,000 s_24| at 1.5% = 5,000 x 28.6335 = N143,168. Option A uses 18% as the monthly rate, option B applies simple interest of 18% to all deposits, and option D treats the deposits as made at the start of each month."}},{"itemId":"31ca35cc-2ee5-5727-bd6f-336522ef6b4d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3c1a7163-252b-500e-9836-47cfe649b8ba","sourceKey":"bank:ACS101:ANN-056","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity pays N100,000 at the end of every half-year for 3 years. Interest is 12% per annum convertible quarterly. Find the present value to the nearest naira. (First find the effective rate per half-year.)","options":["N995,400","N491,732","N490,345","N541,719"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Payments are half-yearly but interest is converted quarterly, so the effective half-yearly rate is (1.03)^2 - 1 = 6.09%, and PV = 100,000 a_6| at 6.09% = N490,345. Option B uses 6%, which is the nominal half-yearly rate, not the effective one. Option D uses the 3% quarterly rate with half-yearly payments, and option A counts 12 payments."}},{"itemId":"813b2b75-a649-587f-a05a-0652e8068a8d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a477b22c-8444-5c6a-8e87-c7ef7185f11c","sourceKey":"bank:ACS101:ANN-057","parentItemId":null,"revision":1,"payload":{"prompt":"A tenant pays N20,000 at the end of every quarter for 2 years. Interest is 10% per annum convertible half-yearly. Find the present value of the payments to the nearest naira.","options":["N143,589","N141,838","N143,403","N129,264"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The effective quarterly rate is (1.05)^0.5 - 1 = 2.4695%, so PV = 20,000 a_8| at that rate = N143,589. Option C uses 2.5%, which simply halves the half-yearly rate. Option D uses the half-yearly rate of 5% per quarter, and option B treats the stream as 4 half-yearly payments of N20,000 and doubles the result."}},{"itemId":"9f8ff7b4-69c0-53d7-b806-89042513a415","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2b95dd19-1a55-5339-b05e-744d773a4ce1","sourceKey":"bank:ACS101:ANN-058","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity of N120,000 per year is payable in monthly instalments of N10,000 at the end of each month for 5 years. Interest is 10% effective per annum. Using a^(12)_5| = (1 - v^5)/i^(12), where i^(12) is the equivalent nominal rate convertible monthly, find the present value to the nearest naira.","options":["N479,176","N470,654","N454,894","N475,385"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Here i^(12) = 12[(1.1)^(1/12) - 1] = 0.095690, so a^(12)_5| = (1 - (1.1)^-5)/0.095690 = 3.96154 and PV = 120,000 x 3.96154 = N475,385. Option C treats the payments as annual in arrears (120,000 a_5|). Option B treats 10% as a nominal rate convertible monthly, and option A uses d^(12), which gives the monthly annuity-due."}},{"itemId":"ed15f81e-ba27-5cdd-8afa-66a21d0f1e16","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"86bb3486-1dcc-5f24-ba97-0c3d39fa2f7b","sourceKey":"bank:ACS101:ANN-059","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity of N240,000 per year is paid in quarterly instalments of N60,000 at the BEGINNING of each quarter for 3 years. Interest is 8% effective per annum. Using a-double-dot^(4)_3| = (1 - v^3)/d^(4) (annuity-due payable quarterly), find the present value to the nearest naira.","options":["N667,984","N636,761","N649,131","N618,503"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Here d^(4) = 4[1 - (1.08)^(-1/4)] = 0.076225, so PV = 240,000 x (1 - (1.08)^-3)/0.076225 = N649,131. Option B uses i^(4), which gives quarterly payments in arrears. Option A treats the payments as annual in advance, and option D as annual in arrears."}},{"itemId":"c1c75d5a-f4df-5415-a785-400d1d483e71","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a36659e2-d805-5e3c-beb6-fa8b4ed73181","sourceKey":"bank:ACS101:ANN-060","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate a-bar_10|, the present value of an annuity paid continuously at the rate of 1 per year for 10 years, at an effective rate of 6% per annum. Give your answer to 4 decimal places.","options":["0.4289","7.5787","7.8017","7.3601"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"a-bar_10| = (1 - v^10)/delta with delta = ln(1.06) = 0.058269, giving 0.441605/0.058269 = 7.5787. Option D is a_10| (end-year payments) and option C is a-double-dot_10| (start-year payments); the continuous value lies between the two. Option A multiplies by delta instead of dividing."}},{"itemId":"6a549b77-149c-5277-8849-aa31e1bb70d2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9392be42-bd2c-5258-b779-29cce278d728","sourceKey":"bank:ACS101:ANN-061","parentItemId":null,"revision":1,"payload":{"prompt":"A company in Port Harcourt promises an employee N500,000 at the end of each year for 10 years starting one year after her retirement. It funds this with 8 equal payments made at the BEGINNING of each year over the 8 years before retirement. At 8% effective per annum, find the annual funding payment to the nearest naira.","options":["N315,423","N435,254","N540,580","N292,059"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"PV at retirement = 500,000 a_10| = 500,000 x 6.71008 = 3,355,041. This must equal P s-double-dot_8| = P x 11.48756, so P = N292,059. Option A uses s_8|, which treats the payments as made in arrears. Option C wrongly divides by a present-value factor, and option B ignores discounting of the pension."}},{"itemId":"a11a2ac7-f38b-58ad-9a3f-45b1cca942db","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ea25f0be-ef08-5687-8094-6d99d92ac4e8","sourceKey":"bank:ACS101:ANN-062","parentItemId":null,"revision":1,"payload":{"prompt":"An investment pays N10,000 at the end of year 1, N20,000 at the end of year 2, and so on up to N50,000 at the end of year 5. At 10% effective per annum, find the present value to the nearest naira, using (Ia)_5| = (a-double-dot_5| - 5v^5)/i.","options":["N117,178","N106,526","N68,618","N120,921"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"(Ia)_5| = (4.1699 - 5 x 0.62092)/0.1 = 10.6526, so PV = 10,000 x 10.6526 = N106,526. Option C uses a_5| instead of a-double-dot_5| in the formula. Option A values the payments in advance, and option D is the decreasing annuity (Da)_5|, which pays 50,000 first."}},{"itemId":"4d7dc536-390e-5090-a000-7cbe130efbc3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d81c5a40-ff28-52b0-b583-d05a5f8b2fe2","sourceKey":"bank:ACS101:ANN-063","parentItemId":null,"revision":1,"payload":{"prompt":"A machine's maintenance savings are N50,000 at the end of year 1, N40,000 at the end of year 2, and so on down to N10,000 at the end of year 5. At 10% effective per annum, find the present value to the nearest naira, using (Da)_5| = (5 - a_5|)/i.","options":["N113,724","N106,526","N120,921","N83,013"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"(Da)_5| = (5 - 3.7908)/0.1 = 12.0921, so PV = 10,000 x 12.0921 = N120,921. Option B is the increasing annuity (Ia)_5|, which reverses the order. Option D uses a-double-dot_5| in the formula, and option A values the average payment of N30,000 as a level annuity."}},{"itemId":"298c18df-9af0-545e-89d8-1a46b4adc704","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"59cb99af-8951-523b-8ed8-f1728412649d","sourceKey":"bank:ACS101:ANN-064","parentItemId":null,"revision":1,"payload":{"prompt":"A business receives N100,000 at the end of year 1, and each later payment is N20,000 more than the previous one, for 6 payments in all. At 8% effective per annum, find the present value using P a_n| + D (a_n| - n v^n)/i, to the nearest naira.","options":["N693,432","N830,296","N672,753","N765,211"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"PV = 100,000 a_6| + 20,000 (a_6| - 6v^6)/0.08 = 462,288 + 20,000 x 10.5233 = N672,753. Option D uses a-double-dot_6| instead of a_6| inside the increasing part, which overstates it. Option B uses 5v^6 instead of 6v^6, and option A values the average payment of N150,000 as level."}},{"itemId":"d5022c39-a872-53b0-80f9-50b1eddec3b7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"910922e4-3e80-5deb-8930-215db908ab12","sourceKey":"bank:ACS101:ANN-065","parentItemId":null,"revision":1,"payload":{"prompt":"A franchise pays N100,000 at the end of year 1, and each later payment is 5% higher than the one before, for 10 payments. At 10% effective per annum, find the present value to the nearest naira, using (1 - ((1 + k)/(1 + i))^n)/(i - k).","options":["N743,981","N614,457","N247,994","N818,379"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"With k = 0.05 and i = 0.10, PV = 100,000 x (1 - (1.05/1.10)^10)/0.05 = 100,000 x 7.43981 = N743,981. Option C uses i + k in the denominator instead of i - k. Option B ignores the 5% growth, and option D values the stream as if paid in advance."}},{"itemId":"35605c11-402b-5f39-a04d-a73f5323c995","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2e4b228e-f2af-5ea5-90a8-aad73fbf5914","sourceKey":"bank:ACS101:ANN-066","parentItemId":null,"revision":1,"payload":{"prompt":"Under SIMPLE interest at 6% per annum, the present value of 1 due at time t is 1/(1 + 0.06t). Find a_4| (payments of 1 at the end of each year for 4 years) under simple interest, to 4 decimal places.","options":["3.4000","3.4902","3.4651","3.2258"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"a_4| = 1/1.06 + 1/1.12 + 1/1.18 + 1/1.24 = 0.9434 + 0.8929 + 0.8475 + 0.8065 = 3.4902. Option C is the compound-interest value (1 - (1.06)^-4)/0.06 = 3.4651, which is slightly lower. Option A uses simple discount (1 - 0.06t) instead, and option D discounts all four payments from time 4."}},{"itemId":"25e48413-b71e-5d53-814b-acd7b4373be8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5e5cb55b-ef93-58b9-868a-f38b755d9913","sourceKey":"bank:ACS101:ANN-067","parentItemId":null,"revision":1,"payload":{"prompt":"A 7-year annuity-immediate pays N1 at the end of each year (5% effective per annum). What is the value of the whole annuity at time 3, just after the 3rd payment? Give your answer to 4 decimal places.","options":["6.6985","5.7864","8.1420","6.5296"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"At time 3, the 3 payments already made are worth s_3| = 3.1525 and the 4 still to come are worth a_4| = 3.5460, so the value is 6.6985, which is also (1.05)^3 a_7|. Option B is the value at time 0 and option C is the value at time 7. Option D discounts the future payments by one extra year."}},{"itemId":"1d21fe42-cf4d-5334-93ad-6c3df0d2497f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"52846255-5095-5202-a9fd-b91e4529fd8b","sourceKey":"bank:ACS101:ANN-068","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N1,000,000 is repaid by 5 equal annual instalments in arrears at 15% effective per annum. Just after the 2nd instalment is paid, what is the present value of the remaining instalments (the outstanding loan), to the nearest naira?","options":["N600,000","N403,369","N681,122","N484,974"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The instalment is P = 1,000,000/a_5| = 298,316, and 3 instalments remain, so the outstanding loan = P a_3| = 298,315.55 x 2.283225 = N681,122. Option B subtracts the instalments without allowing for interest. Option D values only 2 remaining instalments, and option A assumes 2/5 of the loan has been repaid."}},{"itemId":"afeac981-b6c5-5a70-9e6b-524724467339","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"24040b6a-dbe2-527e-8b11-aa5f9c252021","sourceKey":"bank:ACS101:ANN-069","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N1,000,000 is repaid by 5 equal annual instalments in arrears at 15% effective per annum (instalment = 1,000,000/a_5|). What is the total interest paid over the life of the loan, to the nearest naira?","options":["N491,578","N297,024","N750,000","N1,491,578"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Total paid = 5 x 298,316 = 1,491,578, so the total interest is 1,491,578 - 1,000,000 = N491,578. Option D is the total paid, not the interest. Option C charges 15% simple interest on the full loan every year, and option B uses annuity-due instalments."}},{"itemId":"6a7fc01d-39f1-5dd1-98f5-bb4099f1f71e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"08c60c43-0984-53ee-8b54-46f457a7fc9a","sourceKey":"bank:ACS101:ANN-070","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity pays N100,000 per year for 5 years at 10% effective per annum. By how much does the present value of the annuity-due exceed the present value of the annuity-immediate? Give the answer to the nearest naira. (Hint: a-double-dot_n| - a_n| = 1 - v^n.)","options":["N41,699","N62,092","N37,908","N50,000"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"a-double-dot_5| - a_5| = 1 - v^5 = 1 - 0.62092 = 0.37908, so the difference is N37,908 (the payment at time 0 gained minus the payment at time 5 lost, in PV terms). Option A is 1.1 x i x a_5|, which mixes two formulas. Option B is only v^5, and option D adds simple interest of N10,000 a year."}},{"itemId":"88512806-c804-5bce-84c9-5c83f8463933","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5040e8bc-e1ea-5248-a2c6-2b27b8562d99","sourceKey":"bank:ACS101:ANN-071","parentItemId":null,"revision":1,"payload":{"prompt":"The annual effective rate of discount is d = 8%, so v = 0.92. Calculate a-double-dot_4| = (1 - v^4)/d (annuity-due of 1 per year for 4 years) to 4 decimal places.","options":["3.5451","3.8534","3.5771","3.2615"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"a-double-dot_4| = (1 - (0.92)^4)/0.08 = (1 - 0.716393)/0.08 = 3.5451. Option D divides by i = d/(1 - d) = 0.086957, which gives a_4|. Option C wrongly treats 8% as the interest rate i, and option B accumulates the answer by one extra year."}},{"itemId":"e09afb30-a873-5d30-b0b7-26642c767e58","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"01978998-f6aa-51e3-813e-ceb04cedd07e","sourceKey":"bank:ACS101:ANN-072","parentItemId":null,"revision":1,"payload":{"prompt":"The discount factor is v = 0.9 per year. Calculate a_5| (payments of 1 at the end of each year for 5 years) to 4 decimal places.","options":["3.6856","3.0951","2.9525","4.0951"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"v = 0.9 means 1 + i = 1/0.9, so i = 1/9, and a_5| = (1 - 0.59049)/(1/9) = 3.6856, the same as 0.9 + 0.81 + ... + 0.59049. Option D divides by 0.1, which is d, and so gives a-double-dot_5|. Option B is a_4|, one payment too few, and option C discounts all payments from time 5."}},{"itemId":"68cfcb7f-1aa3-510c-a5b9-69f4c247ace0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e56239a1-7432-57f3-9181-676f17bd528c","sourceKey":"bank:ACS101:ANN-073","parentItemId":null,"revision":1,"payload":{"prompt":"At 6% effective per annum, s_5| = 5.6371 and s_3| = 3.1836. Using s_(m+n)| = (1 + i)^n s_m| + s_n|, find s_8| to 4 decimal places.","options":["10.5056","8.8207","10.7273","9.8975"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"The first 5 payments are worth s_5| at time 5 and earn 3 more years of interest, while the last 3 payments add s_3|: s_8| = (1.06)^3 x 5.6371 + 3.1836 = 9.8975. Option B forgets the 3 years of extra interest. Option C accumulates for 5 years instead of 3, and option A also accumulates s_3|, which is already a time-8 value."}},{"itemId":"c6a618c7-a0ad-50c4-8ea0-a3feb7b35b73","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4a009ec4-1a2c-5cf8-af56-f2b832e75ad8","sourceKey":"bank:ACS101:ANN-074","parentItemId":null,"revision":1,"payload":{"prompt":"At 8% effective per annum, a_6| = 4.6229 and a_4| = 3.3121. Using a_(m+n)| = a_n| + v^n a_m|, find a_10| to 4 decimal places.","options":["6.7101","7.0574","7.9350","9.8788"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The last 4 payments are worth a_4| at time 6, i.e. v^6 a_4| at time 0, so a_10| = 4.6229 + (1.08)^-6 x 3.3121 = 6.7101. Option C adds the two factors with no discounting. Option B discounts for 4 years instead of 6, and option D accumulates instead of discounting."}},{"itemId":"d08f0ad0-b818-557f-b05d-5a2f099988da","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9bb88843-3025-5b40-9220-caa797522f94","sourceKey":"bank:ACS101:ANN-075","parentItemId":null,"revision":1,"payload":{"prompt":"An investor pays N2,100,000 for a perpetuity of N100,000 per year with the first payment made immediately. What effective annual rate of interest does this imply?","options":["5.26%","4.55%","5.00%","4.76%"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"For a perpetuity-due, price = payment/d, so d = 100,000/2,100,000 = 1/21, and i = d/(1 - d) = (1/21)/(20/21) = 1/20 = 5%. Option D, 4.76%, is d itself, which treats the stream as a perpetuity-immediate. Option A deducts the immediate payment twice (100,000/1,900,000), and option B computes d/(1 + d) instead of d/(1 - d)."}},{"itemId":"a0c01201-42f6-559c-8082-ebadcddad743","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"831801d1-c380-5a00-adad-b8fc21c69140","sourceKey":"bank:ACS101:ANN-076","parentItemId":null,"revision":1,"payload":{"prompt":"A landlord grants a 10-year lease on a property in Abuja for N3,000,000 today, to be paid by 10 equal annual instalments with the first instalment due immediately. At 12% effective per annum, find each instalment to the nearest naira.","options":["N300,000","N530,952","N152,636","N474,065"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"Instalments starting now form an annuity-due: P = 3,000,000/a-double-dot_10| = 3,000,000/6.32825 = N474,065. Option B divides by a_10|, which treats the instalments as paid in arrears. Option A ignores interest, and option C divides by an accumulated-value factor."}},{"itemId":"bd66a3f8-72ea-50a7-a91d-31c0fcfab1ed","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b99999bc-f570-586e-b0d8-96ce01235f5a","sourceKey":"bank:ACS101:ANN-077","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate the deferred annuity-due factor 2|a-double-dot_4| (payments of 1 at times 2, 3, 4 and 5) at 9% effective per annum, using m|a-double-dot_n| = v^m a-double-dot_n|. Give your answer to 4 decimal places.","options":["3.5313","2.9722","3.2397","2.7268"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"2|a-double-dot_4| = (1.09)^-2 x a-double-dot_4| = 0.84168 x 3.5313 = 2.9722, which also equals 3|a_4| because the payments fall at times 2 to 5. Option D uses a_4|, which moves every payment one year later. Option A ignores the deferment, and option C discounts for only 1 year."}},{"itemId":"24f9cfe8-fbd1-5939-83f7-76be865996ef","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"44938958-63c8-5b61-880b-63f3326c6815","sourceKey":"bank:ACS101:ANN-078","parentItemId":null,"revision":1,"payload":{"prompt":"At 10% effective per annum, what is the present value of a perpetuity-immediate of N1 per year minus a 10-year annuity-immediate of N1 per year (that is, the value of payments from year 11 onwards)? Give your answer to 4 decimal places.","options":["3.5049","3.8554","3.2410","4.8554"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Payments from time 11 onwards form 10|a_inf| = v^10/i = 1/i - a_10| = 10 - 6.1446 = 3.8554. Option C subtracts the annuity-due, which removes the wrong payments. Option D starts from the perpetuity-due 1/d, and option A discounts one year too many."}},{"itemId":"0da41a72-06c6-5172-8ee7-7c6d5388e263","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c1123872-51e7-5442-9d2a-2b0b83a4748b","sourceKey":"bank:ACS101:ANN-079","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N800,000 is repaid by level instalments at the end of each year for 6 years, but the first instalment is made at the end of year 3 (a 2-year grace period). At 7% effective per annum, find the instalment to the nearest naira.","options":["N192,156","N205,607","N152,653","N167,837"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"Payments at times 3 to 8 form 2|a_6| = v^2 a_6| = 0.873439 x 4.766540 = 4.163280, so P = 800,000/4.163280 = N192,156. Option D ignores the grace period. Option B defers 3 years instead of 2, and option C adds 2 years of interest and then ignores further interest."}},{"itemId":"1061cc37-6617-526e-a6d9-be929fa759f9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b6575fd0-4f32-52b0-9ccc-09908487e907","sourceKey":"bank:ACS101:ANN-080","parentItemId":null,"revision":1,"payload":{"prompt":"An insurance company in Lagos buys an annuity-certain paying N1,000,000 at the beginning of each year for 15 years. At 6% effective per annum, find its purchase price (present value) to the nearest naira.","options":["N10,712,249","N9,712,249","N10,294,984","N9,852,683"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"Payments in advance give PV = 1,000,000 a-double-dot_15| = 1,000,000 x 1.06 x 9.7122 = N10,294,984. Option B values the payments in arrears. Option A uses 1 + a_15|, which counts 16 payments, and option D counts only 14 payments."}},{"itemId":"7d96bdae-ce58-525b-bbf0-9aa605eb590a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e8ba67d4-58c2-5c42-8802-8b3bcd3954ca","sourceKey":"bank:ACS101:HIS-001","parentItemId":null,"revision":1,"payload":{"prompt":"In 1662 a London draper published 'Natural and Political Observations on the London Bills of Mortality', which showed predictable patterns of death in a population. Who was he?","options":["Edmond Halley","William Morgan","James Dodson","John Graunt"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"John Graunt, a London draper, studied the weekly London Bills of Mortality and in 1662 produced the first attempt at a life table. Option A (Halley) built the Breslau table later, in 1693, while C (Dodson) and B (Morgan) belong to the 18th-century life assurance story."}},{"itemId":"b5992445-8b96-56da-b486-f4d550ec3882","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ee9277ad-ff09-5878-ad28-d2cf71d7457c","sourceKey":"bank:ACS101:HIS-002","parentItemId":null,"revision":1,"payload":{"prompt":"John Graunt's 1662 study of mortality was based mainly on which data?","options":["Policy records of the Equitable Society","Parish records from the city of Breslau","The weekly London Bills of Mortality","Census returns of the Northampton parishes"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"Graunt worked from the London Bills of Mortality, weekly reports of deaths in London. Option B describes the data Halley used in 1693, A could not exist yet because the Equitable was founded in 1762, and D points to the Northampton table of Richard Price in the 1770s."}},{"itemId":"35052623-f28c-512c-804b-8118c0f5c421","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5d837298-cafe-5a87-baae-fbf11fc591d4","sourceKey":"bank:ACS101:HIS-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes John Graunt's main contribution (1662) to the foundations of actuarial science?","options":["He introduced the level premium system for whole life cover","He made the first attempt at a life table from death records","He proposed that mortality rises geometrically with age","He founded the first professional body for actuaries"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Graunt is remembered for the first attempt at a life table and the first treatise on vital statistics. The level premium idea in option A came from James Dodson in the 1750s, the first professional body in D was founded in 1848, and the law in C is Gompertz's from 1825."}},{"itemId":"6e406267-375c-5d29-aab3-c9b8793e4f73","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d3fc3116-ab46-5f4c-add3-2c72e929427a","sourceKey":"bank:ACS101:HIS-004","parentItemId":null,"revision":1,"payload":{"prompt":"In 1693 Edmond Halley published a life table built from the parish records of which city?","options":["London","Breslau","Northampton","Edinburgh"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Halley's 1693 table used mortality records from Breslau supplied by Caspar Neumann. London (option A) produced the Bills of Mortality that Graunt used earlier, while C (Northampton) is linked with Richard Price's later table and D (Edinburgh) with the Faculty of Actuaries."}},{"itemId":"e8a00c4a-3969-573d-a47c-bd1ae0c5a3f6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e7eb5062-1d25-5edd-81f3-fc67fe854b99","sourceKey":"bank:ACS101:HIS-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which scientist, best known for predicting the return of a famous comet, also produced a life table in 1693 and showed how to price a life annuity from it?","options":["Abraham de Moivre","Edmond Halley","Richard Price","Benjamin Gompertz"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Edmond Halley, of Halley's Comet, published his Breslau life table in 1693 and used it to show how a life annuity should be priced. Option A (de Moivre) later built annuity formulas on Halley's data in 1725, D (Gompertz) proposed a mortality law in 1825, and C (Price) compiled the Northampton table."}},{"itemId":"d54edc9d-37e8-5dbe-849d-be225d3665a4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d71c5327-7280-51fa-9950-501d6a190077","sourceKey":"bank:ACS101:HIS-006","parentItemId":null,"revision":1,"payload":{"prompt":"Halley's 1693 life table had an immediate practical use for the British government. What was it?","options":["Selling life annuities at prices that depended on the buyer's age","Calculating fire insurance rates for London houses","Setting premium rates for marine cargo insurance","Fixing the tax payable on inherited estates"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"Halley's table showed that a life annuity is worth less to an older buyer, so annuities could be sold at prices matched to the purchaser's age. Options C, D and B are other financial matters that do not depend on a table of survival by age, which is what Halley produced."}},{"itemId":"5724c30a-6e0a-5c0b-b79a-9ffcb26a8a2f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f2da1795-c1f4-5d4e-9bfa-42fdc16af3b0","sourceKey":"bank:ACS101:HIS-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following lists these events in the correct time order, earliest first?","options":["Halley's Breslau table, Graunt's observations, founding of the Equitable, founding of the Institute of Actuaries","Graunt's observations, founding of the Equitable, Halley's Breslau table, founding of the Institute of Actuaries","Graunt's observations, Halley's Breslau table, founding of the Institute of Actuaries, founding of the Equitable","Graunt's observations, Halley's Breslau table, founding of the Equitable, founding of the Institute of Actuaries"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"The order is Graunt (1662), Halley (1693), the Equitable Society (1762) and the Institute of Actuaries (1848). Option A puts Halley before Graunt, B puts the Equitable before Halley, and C places the 1848 Institute before the 1762 Equitable."}},{"itemId":"c3373861-2526-56db-b965-fc6aba28ca7b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c2ef2de8-e176-5f23-8dd7-921088e865dc","sourceKey":"bank:ACS101:HIS-008","parentItemId":null,"revision":1,"payload":{"prompt":"'Annuities upon Lives', published in London in 1725 and giving methods for valuing annuities on one or more lives, was written by whom?","options":["Benjamin Gompertz","Abraham de Moivre","John Graunt","James Dodson"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Abraham de Moivre published 'Annuities upon Lives' in 1725, building his formulas on mortality data collected by Halley. Option C (Graunt) died long before 1725, D (Dodson) is known for the level premium system of the 1750s, and A (Gompertz) worked a century later."}},{"itemId":"36ee5128-59ff-52de-9394-9b9bc56510e6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ea7411db-8b41-5ecc-adde-8c396a0c26f5","sourceKey":"bank:ACS101:HIS-009","parentItemId":null,"revision":1,"payload":{"prompt":"In 'Annuities upon Lives' (1725), what simplifying mortality assumption did Abraham de Moivre use to derive his annuity formulas?","options":["Mortality that rises geometrically with age, as in Gompertz's law","A postulated uniform rate of mortality, together with a constant rate of interest","Mortality taken from the claims experience of the Equitable Society","No allowance for mortality at all, only for interest"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"De Moivre simplified the calculations by assuming a uniform rate of mortality and a constant interest rate. Option A is Gompertz's 1825 law, which came much later; D would make it an annuity-certain rather than a life annuity; and C is impossible because the Equitable was founded in 1762."}},{"itemId":"5aca720d-6f3d-52e8-8174-6335e7ca99e5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"399e96a2-b9b5-5edf-9ec9-c89b365936ff","sourceKey":"bank:ACS101:HIS-010","parentItemId":null,"revision":1,"payload":{"prompt":"In 1654 Blaise Pascal and Pierre de Fermat exchanged letters about the 'problem of points' raised by a gambler. Historians often treat this correspondence as the start of which subject used by actuaries?","options":["Insurance regulation","Compound interest","Modern probability theory","The life table"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The 1654 Pascal-Fermat letters on dividing stakes in an unfinished game are usually cited as the beginning of modern probability theory, one of the mathematical pillars of actuarial work. The first life table (D) came from Graunt in 1662, compound interest (B) is far older commercial practice, and A has nothing to do with the problem of points."}},{"itemId":"8b26de36-a68d-50ad-ace6-f46a339ea691","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c331769e-4793-52dd-9016-12449812e742","sourceKey":"bank:ACS101:HIS-011","parentItemId":null,"revision":1,"payload":{"prompt":"Jacob Bernoulli's 'Ars Conjectandi', published after his death in 1713, contains an early version of which result that underpins insurance?","options":["The central limit theorem in its modern form","The law of large numbers","The present value formula v^n = (1 + i)^-n","The Gompertz law of mortality"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Bernoulli's 'golden theorem', now called the weak law of large numbers, says observed proportions settle down to the true probability as the number of trials grows. Option D is from 1825, A was developed by later mathematicians, and C is a financial mathematics formula rather than a probability result."}},{"itemId":"ae9e1ad2-ca87-5050-ab00-2de58d059601","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"168e378a-9411-5181-8e5d-51fe8fa0c071","sourceKey":"bank:ACS101:HIS-012","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer in Lagos finds that among 200 motor policies the yearly accident rate jumps around a lot, but among 50,000 similar policies it stays close to 4% every year. Which principle explains this?","options":["The level premium principle","The time value of money","Adverse selection by policyholders","Statistical regularity, as described by the law of large numbers"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"Statistical regularity says that when many similar independent trials are observed, the proportion of occurrences stabilises as the number grows; this is the law of large numbers that makes pooling work. Option A is about keeping premiums constant over a policy's life, B is about interest, and C would make the experience worse, not more stable."}},{"itemId":"34f50d4b-c855-5573-ade8-f1477d8b30ae","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b054ae39-66ef-5831-bb82-157ba945fb54","sourceKey":"bank:ACS101:HIS-013","parentItemId":null,"revision":1,"payload":{"prompt":"James Dodson, who died in 1757, is remembered in actuarial history mainly for pioneering work on which idea?","options":["The International Congress of Actuaries","The law of mortality named after Gompertz","The level premium system for long-term life assurance","The first life table based on Breslau data"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"Dodson's pioneering work on level premiums, where the same premium is charged each year of a long-term policy, became the basis of the Equitable Society founded in 1762. Option D belongs to Halley (1693), B to Gompertz (1825) and A began only in 1895."}},{"itemId":"8f09a23a-e0d2-5c52-a709-e161d6c8b5f1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f62c8ccd-2270-516e-a0df-d20cea35bbb9","sourceKey":"bank:ACS101:HIS-014","parentItemId":null,"revision":1,"payload":{"prompt":"Bola, aged 30, buys a whole life policy and pays N60,000 every year; at age 60 she still pays N60,000 even though her risk of death is now much higher. What premium arrangement is this?","options":["A single premium","A level premium","A natural (yearly risk) premium","An index-linked premium"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"A level premium stays the same every year, so early payments exceed the yearly cost of cover and the excess is held to meet the higher cost in later years; this was Dodson's key idea. A natural premium (C) would rise each year with the risk, a single premium (A) is paid once, and an index-linked premium (D) changes with an index."}},{"itemId":"ffa163b5-3659-5876-9fdf-3ad8d6f5916a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"307d6540-f799-5eac-8f3a-bf1c4e0ad603","sourceKey":"bank:ACS101:HIS-015","parentItemId":null,"revision":1,"payload":{"prompt":"The life office founded in London in 1762, often described as the first to use scientifically calculated premiums for long-term life policies, was known as what?","options":["The Society for Equitable Assurances on Lives and Survivorships","The Scottish Widows' Fund","The Institute of Actuaries","The Alliance Assurance Company"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"The Society for Equitable Assurances (the Equitable) was set up in 1762 on Dodson's principles. Option C is a professional body founded in 1848, not an insurer, while B and D are later life offices (Gompertz became actuary of the Alliance in 1824)."}},{"itemId":"c422336f-8c95-5175-80f1-eef1dd4506b6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"36fda8a1-0fbe-5267-9e9c-39dd79fb6af1","sourceKey":"bank:ACS101:HIS-016","parentItemId":null,"revision":1,"payload":{"prompt":"Why is the founding of the Equitable Society in 1762 a landmark in actuarial history?","options":["It was the first body to set professional examinations for actuaries","It published the first life table, based on the London Bills of Mortality","It was the first insurer to be regulated by a national insurance commission","It was the first life insurer to charge scientifically calculated premiums on long-term policies"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"The Equitable was the first life office to base long-term premiums on mortality data and calculation rather than guesswork. Professional examinations (A) came with the professional bodies of the 19th century, the first life table (B) was Graunt's in 1662, and C describes modern regulation, not the 1760s."}},{"itemId":"2389a9d4-ed75-5647-9fb6-8a473ede3e12","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8405e054-cb04-5ae7-ba09-479909c67bc5","sourceKey":"bank:ACS101:HIS-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which founder of the Equitable Society specified, around 1762, that its chief official should be called the 'actuary', the first use of the title for a business position?","options":["James Dodson","William Morgan","Richard Price","Edward Rowe Mores"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"Edward Rowe Mores led the group that formed the Equitable and specified that the chief official be called an actuary. William Morgan (B) later made the post famous from 1775, Richard Price (C) was an adviser, and James Dodson (A) had died in 1757 before the Society opened."}},{"itemId":"2f8ff352-1234-5ba3-bc77-a52da506e21b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"62902df3-4d9e-5cee-955c-dfba9bfa0263","sourceKey":"bank:ACS101:HIS-018","parentItemId":null,"revision":1,"payload":{"prompt":"Before Edward Rowe Mores used it for the Equitable's chief official in 1762, the word 'actuary' was used for what kind of person?","options":["A physician who certified causes of death","A ship's officer who calculated the vessel's position","A collector of customs duties at a port","A clerk who kept the records of a court or senate"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"Earlier the term described a record-keeper or registrar of a court or senate; Mores borrowed it for the officer who kept the Society's records and calculations. Options B, C and A are other old occupations with no link to the word."}},{"itemId":"f6f41fb6-a555-5476-bce6-42d7d9b25c9b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"37b17351-a28e-5a82-905a-5f259648f40e","sourceKey":"bank:ACS101:HIS-019","parentItemId":null,"revision":1,"payload":{"prompt":"Who was appointed actuary of the Equitable Society in 1775, held the post until 1830, and is often called the father of the actuarial profession?","options":["Benjamin Gompertz","Edmond Halley","William Morgan","Edward Rowe Mores"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"William Morgan served as the Equitable's actuary from 1775 to 1830, 55 years, and is described as the pre-eminent actuary of his time. Mores (D) founded the Society and named the post, Halley (B) was a 17th-century astronomer known for his 1693 life table, and Gompertz (A) was actuary of the Alliance from 1824."}},{"itemId":"edd8b22c-68aa-5a65-95cf-0e970a5851cb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"77d50e8b-0594-53de-8fb0-fcaf63905647","sourceKey":"bank:ACS101:HIS-020","parentItemId":null,"revision":1,"payload":{"prompt":"The Northampton mortality table, used as a standard in British actuarial work for about a century, was compiled by which 18th-century writer, author of 'Observations on Reversionary Payments' (1771)?","options":["William Morgan","Richard Price","John Graunt","Abraham de Moivre"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Richard Price compiled the Northampton table and published 'Observations on Reversionary Payments' in 1771. William Morgan (A) was his nephew and later edited his works, Graunt (C) worked with London data in 1662, and de Moivre (D) used Halley's data in 1725."}},{"itemId":"0fc12e5a-c997-5067-a23f-a73951a464b9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"43979711-b3bf-54be-b1da-0af6235f4fe2","sourceKey":"bank:ACS101:HIS-021","parentItemId":null,"revision":1,"payload":{"prompt":"Richard Price's Northampton table (1770s) was widely used but had a well-known weakness. What was it?","options":["It ignored interest, so its premiums were all undiscounted","It understated mortality, so life offices charged too little for life cover","It overstated mortality, so annuities priced on it were sold too cheaply","It covered only infants, so it could not price adult policies"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The Northampton table showed people dying sooner than they really did. Overstated mortality makes life cover look dearer, which is safe for an insurer, but makes annuities look cheaper, so offices that sold annuities on it lost money. Option B is the reverse error, and A and D misdescribe what a mortality table contains."}},{"itemId":"ac9cb985-4e87-570d-a6a3-cc95a13cc71e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1c624a9d-46de-5e9d-9f5a-6e857e87a8cb","sourceKey":"bank:ACS101:HIS-022","parentItemId":null,"revision":1,"payload":{"prompt":"In 1825 an actuary proposed a law of mortality based on the idea that a person's resistance to death declines as they get older. Who was he?","options":["Abraham de Moivre","Edmond Halley","Richard Price","Benjamin Gompertz"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"Benjamin Gompertz published his law of mortality in 1825, and it was later extended into the Gompertz-Makeham law. De Moivre (A) had earlier assumed a uniform rate of mortality, while Halley (B) and Price (C) built life tables from data rather than proposing this law."}},{"itemId":"5a0be755-3315-5e55-9bbe-8842438a9a7d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9f9de65e-3336-552f-9229-8270eb3e2760","sourceKey":"bank:ACS101:HIS-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following pairings of a historical figure with a contribution is NOT correct?","options":["Edmond Halley - Breslau life table (1693)","John Graunt - first attempt at a life table (1662)","Benjamin Gompertz - pioneering work on the level premium system","Richard Price - Northampton mortality table (1770s)"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The level premium system is credited to James Dodson in the 1750s; Gompertz is known for his 1825 law of mortality, so this pairing is wrong. Options B, A and D correctly match Graunt, Halley and Price with their work."}},{"itemId":"4e788ba9-cd04-5d0e-a9b1-6a92f5cd1096","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d3a3a657-3370-5faf-a847-1542e3f4822b","sourceKey":"bank:ACS101:HIS-024","parentItemId":null,"revision":1,"payload":{"prompt":"The Institute of Actuaries, one of the two bodies that later formed the Institute and Faculty of Actuaries, was founded in London in which year?","options":["1856","1848","1762","1889"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"The Institute of Actuaries was founded in London on 8 July 1848 by actuaries of several life offices. 1762 (option C) is the founding of the Equitable Society, 1856 (A) is the Faculty of Actuaries in Scotland, and 1889 (D) is the Actuarial Society of America."}},{"itemId":"ad75cc3d-491e-565f-99dc-6b4ca9160ce1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2e2ac5c3-beba-582c-bf7e-44310286b57d","sourceKey":"bank:ACS101:HIS-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which actuarial body was founded in Scotland in 1856 and later merged with the Institute of Actuaries?","options":["The American Institute of Actuaries","The Actuarial Society of South Africa","The Faculty of Actuaries","The Casualty Actuarial Society"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The Faculty of Actuaries was founded by Scottish actuaries on 4 January 1856 and merged with the Institute in 2010. The CAS (D) is an American body from 1914, ASSA (B) is South African, and the American Institute of Actuaries (A) was a Chicago body that helped form the SOA."}},{"itemId":"03675dc2-2e80-52d2-bede-ed123b732e22","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dbeb9fe9-dcef-590b-aa10-430ad7289593","sourceKey":"bank:ACS101:HIS-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which body, receiving its Royal Charter in 1868, was the first actuarial organisation to be granted one?","options":["The International Actuarial Association","The Institute of Actuaries","The Society of Actuaries","The Faculty of Actuaries"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"The Faculty of Actuaries received its Royal Charter in September 1868, the first actuarial body to do so. The Institute of Actuaries (B) received its charter later, in 1884, while the SOA (C) and the IAA (A) are not chartered British bodies."}},{"itemId":"f6db64a1-a8f5-56df-bfb3-280fa743d8b9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dabe5db6-80c3-5967-b8b9-59ede18d497d","sourceKey":"bank:ACS101:HIS-027","parentItemId":null,"revision":1,"payload":{"prompt":"On 1 August 2010 the Institute of Actuaries and the Faculty of Actuaries merged. What is the name of the merged UK body?","options":["The Society of Actuaries (SOA)","The Royal Society of Actuaries (RSA)","The Institute and Faculty of Actuaries (IFoA)","The British Actuarial Association (BAA)"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The merger created the Institute and Faculty of Actuaries, which kept both historic names. The SOA (A) is the North American body formed in 1949, and options D and B are not real actuarial bodies."}},{"itemId":"1c19147d-bc07-5b42-b8c1-8e9d283867f7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c2d41f5e-7e37-50f1-bd47-751cb5332e70","sourceKey":"bank:ACS101:HIS-028","parentItemId":null,"revision":1,"payload":{"prompt":"Before the 2010 UK merger, what did the letters FFA after an actuary's name indicate?","options":["Fellow of the Faculty of Actuaries","Full Financial Actuary","Fellow of the Federation of Actuaries","Fellow of the Financial Analysts"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"FFA stood for Fellow of the Faculty of Actuaries, the Scottish body, just as FIA stood for Fellow of the Institute of Actuaries. Options C, B and D expand the letters into bodies or titles that do not exist."}},{"itemId":"6fe7eca2-f8cd-574e-a381-112afb580c20","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"739e6319-1183-5c4a-94af-760d53c081c3","sourceKey":"bank:ACS101:HIS-029","parentItemId":null,"revision":1,"payload":{"prompt":"The Society of Actuaries (SOA) was formed in 1949 by merging which two organisations?","options":["The Casualty Actuarial Society and the American Academy of Actuaries","The Institute of Actuaries and the Faculty of Actuaries","The Actuarial Society of America and the American Institute of Actuaries","The Actuarial Society of America and the Casualty Actuarial Society"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The SOA came from the 1949 merger of the Actuarial Society of America (founded 1889) and the American Institute of Actuaries (founded 1909). Option B describes the UK merger of 2010, and the CAS in A and D still exists as a separate body."}},{"itemId":"7796a45e-b7fe-5d12-a67c-e5297e297ed8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"84af48ef-787b-5e63-b0e8-d2669d50c126","sourceKey":"bank:ACS101:HIS-031","parentItemId":null,"revision":1,"payload":{"prompt":"The Casualty Actuarial Society was founded in November 1914 under a different name and took its present name in 1921. What was its original name?","options":["The Casualty Actuarial and Statistical Society of America","The Actuarial Society of America","The American Institute of Actuaries","The Property Insurance Actuarial Association"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"The CAS began in 1914 as the Casualty Actuarial and Statistical Society and shortened its name in 1921. Options C and B are the two bodies that merged into the SOA in 1949, and D is not a real historical body."}},{"itemId":"00ec50f4-5a73-52f2-8921-b32d42dc8d0a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c6f7c035-5c84-5e30-86b7-22ccad156868","sourceKey":"bank:ACS101:HIS-032","parentItemId":null,"revision":1,"payload":{"prompt":"When the Casualty Actuarial Society was founded in 1914, it was mainly concerned with which newly introduced line of insurance in the United States?","options":["Private health insurance","Defined benefit pension plans","Workers' compensation insurance","Individual whole life assurance"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The CAS was set up chiefly to handle the actuarial problems of workers' compensation, which had just been introduced in the US in the early 20th century. Life assurance (D), pensions (B) and health cover (A) are mainly SOA areas rather than casualty lines."}},{"itemId":"ce704ddd-9d8d-5646-b2e7-4c4eec302327","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8247267d-5e2e-5f73-9425-e541c6ba81c9","sourceKey":"bank:ACS101:HIS-033","parentItemId":null,"revision":1,"payload":{"prompt":"The Casualty Actuarial Society qualifies actuaries for one main practice area. Which of the following is NOT a CAS practice area?","options":["Motor (auto) insurance pricing","Liability insurance ratemaking","Life assurance and annuities","Property insurance reserving"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The CAS covers general insurance, also called property and casualty (P&C), such as motor, property and liability business; it does not qualify actuaries in life, pensions or health. Options A, D and B are all P&C work and so fall within the CAS's area."}},{"itemId":"72501417-e983-583d-9866-2d4c0d7cc404","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b22ecafb-2b38-519b-a466-fc2bcf639807","sourceKey":"bank:ACS101:HIS-034","parentItemId":null,"revision":1,"payload":{"prompt":"Chinedu, a general insurance actuary in Lagos, completes the Associate requirements of the Casualty Actuarial Society. Which letters may he now use after his name?","options":["AIA","ASA","ACAS","FCAS"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"An Associate of the Casualty Actuarial Society uses ACAS; the Fellow designation FCAS (D) needs further exams after associateship. ASA (B) is the Society of Actuaries' associate title and AIA (A) was the old Institute of Actuaries' associate title."}},{"itemId":"119c3a10-ac4c-5246-9adb-9a375a46dfbb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f18dab7d-fef9-5817-bf4c-6a9b573ba65d","sourceKey":"bank:ACS101:HIS-035","parentItemId":null,"revision":1,"payload":{"prompt":"The International Actuarial Association traces its origin to a committee set up in 1895 to organise international meetings of actuaries. Where was the first International Congress of Actuaries held that year?","options":["Ottawa, Canada","Brussels, Belgium","London, England","Edinburgh, Scotland"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"The first International Congress of Actuaries met in Brussels in 1895, and the permanent committee formed then (the Comite Permanent des Congres d'Actuaires) later became the IAA. Ottawa (A) is where the IAA is now headquartered, while London (C) and Edinburgh (D) are home to the IFoA's offices."}},{"itemId":"0e06e4c8-5297-5d91-a7ed-8944789dad00","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b5c88021-baee-50ff-9724-72d6f6ec9fea","sourceKey":"bank:ACS101:HIS-036","parentItemId":null,"revision":1,"payload":{"prompt":"Following its 1998 restructuring at the International Congress in Birmingham, who are the full members of the International Actuarial Association?","options":["Insurance companies that employ actuaries","Government insurance regulators of each country","National actuarial associations, so it is an association of associations","Individual actuaries who have passed its own examinations"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"Since 1998 the IAA has been an association of national actuarial associations; individual actuaries take part through their national bodies and IAA sections. It sets no qualifying examinations of its own (D), and insurers (A) and regulators (B) are not its members."}},{"itemId":"737a4906-e85d-55b9-a184-2cec9217342f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1075d1b5-c08f-547d-b904-2c47c34e6495","sourceKey":"bank:ACS101:HIS-038","parentItemId":null,"revision":1,"payload":{"prompt":"The International Actuarial Association publishes International Standards of Actuarial Practice (ISAPs). How are these standards described?","options":["Model standards that member associations are encouraged to align their own standards with","Accounting standards that insurers must use in their financial statements","Binding rules that every actuary in the world must follow","Examination syllabuses that replace national qualifications"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"ISAPs are model standards of practice: they are not binding on any actuary, but national associations are encouraged to set standards that closely match them. Option C overstates their force, D confuses standards with exams, and B describes accounting standards such as IFRS."}},{"itemId":"a88c535c-c72f-5b84-8ec7-9b50cd396d1d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"82fc54ac-631a-53e6-ba69-eba91506ce0a","sourceKey":"bank:ACS101:HIS-039","parentItemId":null,"revision":1,"payload":{"prompt":"Which actuarial body, with offices in Cape Town, offers actuarial qualifications for South Africa?","options":["The Actuarial Society of South Africa (ASSA)","The Nigerian Actuarial Society (NAS)","The Society of Actuaries (SOA)","The Casualty Actuarial Society (CAS)"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"ASSA is the South African actuarial society, based in Cape Town, and covers life, pensions, health and general insurance. The CAS (D) is based in Arlington, Virginia, NAS (B) is the Nigerian body, and the SOA (C) is based in the Chicago area."}},{"itemId":"3529b102-b332-5d14-9210-3e95ab0d7977","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4db793aa-2e23-533b-9623-59d8adba1d1c","sourceKey":"bank:ACS101:HIS-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the professional body for actuaries in Nigeria?","options":["The National Pension Commission (PenCom)","The Nigerian Actuarial Society (NAS)","The Chartered Insurance Institute of Nigeria (CIIN)","The National Insurance Commission (NAICOM)"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"The Nigerian Actuarial Society is the professional association of actuaries and actuarial students practising in Nigeria. NAICOM (D) and PenCom (A) are government regulators of insurance and pensions, and the CIIN (C) is the professional body for insurance practitioners in general."}},{"itemId":"a20bd128-aced-5d5d-94a5-cdf8bc06b31d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"66864e64-7193-5414-be45-95e533324b8d","sourceKey":"bank:ACS101:HIS-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which Nigerian government agency, established under an Act of 1997, regulates and supervises the insurance industry?","options":["The National Insurance Commission (NAICOM)","The Nigerian Actuarial Society (NAS)","The National Pension Commission (PenCom)","The Securities and Exchange Commission (SEC)"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"NAICOM was established by the National Insurance Commission Act 1997 to regulate insurance business and protect policyholders. PenCom (C) regulates pensions, NAS (B) is a professional association rather than a regulator, and the SEC (D) regulates the capital market."}},{"itemId":"cc458838-ae2d-5191-8372-a7035c144b6c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"88e638c6-2140-55bb-b211-f5a1de4e11c9","sourceKey":"bank:ACS101:HIS-043","parentItemId":null,"revision":1,"payload":{"prompt":"The National Pension Commission (PenCom), which regulates and supervises Nigeria's pension system, was established by which law?","options":["The Pension Reform Act 2004","The National Insurance Commission Act 1997","The Companies and Allied Matters Act","The Friendly Societies Act"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"PenCom was created by the Pension Reform Act 2004 to regulate and supervise pensions and license pension fund administrators and custodians. The 1997 Act in option B created NAICOM, C governs company registration, and D is an old British law, not a Nigerian pension statute."}},{"itemId":"3875fbea-befb-5647-b47f-b5935cd9f577","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"de1f0294-5c32-50dc-825d-13cadca3ec5f","sourceKey":"bank:ACS101:HIS-044","parentItemId":null,"revision":1,"payload":{"prompt":"In January 2024, the University of Lagos obtained accreditation for its MSc Actuarial Science programme, earning graduates exam exemptions. Which body granted the accreditation?","options":["The Casualty Actuarial Society (CAS)","The Society of Actuaries (SOA)","The National Insurance Commission (NAICOM)","The Institute and Faculty of Actuaries (IFoA)"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"The IFoA accredited UNILAG's postgraduate MSc in Actuarial Science, giving successful graduates exam exemptions; the programme was developed with the Nigerian Actuarial Society. The SOA (B) and CAS (A) are North American bodies, and NAICOM (C) regulates insurers rather than accrediting degrees."}},{"itemId":"5944859e-9e8c-5295-bbf9-74bf08b95bab","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f33558cb-b922-508a-83be-a75ae9a74c36","sourceKey":"bank:ACS101:HIS-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly matches each Nigerian body with its main role?","options":["NAICOM - professional body of actuaries; PenCom - regulates insurers; NAS - regulates pensions","NAICOM - regulates insurers; PenCom - regulates pensions; NAS - professional body of actuaries","NAICOM - regulates pensions; PenCom - regulates insurers; NAS - professional body of actuaries","NAICOM - regulates insurers; PenCom - professional body of actuaries; NAS - regulates pensions"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"NAICOM supervises the insurance industry, PenCom supervises pensions, and the Nigerian Actuarial Society represents the actuarial profession. Option C swaps the two regulators, while A and D wrongly turn a regulator into a professional body."}},{"itemId":"147ed4c8-1a2f-5eeb-94e2-4ef245132f33","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6a591e8a-feef-56ff-aeb9-5750c8255f90","sourceKey":"bank:ACS101:HIS-046","parentItemId":null,"revision":1,"payload":{"prompt":"Under the IFoA qualification pathway, what must a student complete to become an Associate?","options":["The Core Principles exams only, with no work experience requirement","Two Specialist Principles exams and one Specialist Advanced exam","All exams including Specialist Advanced, plus 3 years of PPD","The Core Principles and Core Practices exams, 2 years of PPD and Professional Skills Stages 1 and 2"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"IFoA associateship comes after the Core Principles (CS, CM, CB) and Core Practices (CP) exams together with 2 years of Personal and Professional Development and Professional Skills Stages 1 and 2. Option A leaves out the practice exams and experience, while B and C describe the further steps needed for fellowship."}},{"itemId":"5b7d0813-acf5-528c-9616-babd51ccb5cd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"edc25054-c92d-5f75-90a1-30eb3c90fcce","sourceKey":"bank:ACS101:HIS-047","parentItemId":null,"revision":1,"payload":{"prompt":"After becoming an IFoA Associate, what further requirements lead to Fellowship?","options":["Two Specialist Principles exams, one Specialist Advanced exam and a total of 3 years of PPD","A Specialist Advanced exam only, with 2 years of PPD in total","One Core Practices exam and one further year of study leave","All eight Specialist Principles exams with no PPD requirement"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"To become a Fellow, an Associate passes two Specialist Principles (SP) subjects and one Specialist Advanced (SA) subject, which is the final exam, and completes 3 years of PPD, one more than at Associate level. Option D overstates the SP requirement, B drops the SP exams and gives the Associate PPD total, and C confuses the stages."}},{"itemId":"35e9f93e-1782-543e-ab27-388d0a97e0ad","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6d563fb6-1ab5-51dd-bf5c-024b54e2d36a","sourceKey":"bank:ACS101:HIS-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following IFoA subjects belongs to the Core Practices stage?","options":["CM1 Actuarial Mathematics 1","CP1 Actuarial Practice","SP2 Life Insurance","CB2 Business Economics"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"The Core Practices stage consists of CP1 Actuarial Practice, CP2 Modelling Practice and CP3 Communication Practice. CM1 (A) and CB2 (D) are Core Principles subjects taken earlier, and SP2 (C) is a Specialist Principles subject taken on the way to Fellowship."}},{"itemId":"5ae3114a-4ae3-55cd-81b7-62d3fbe29596","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ff545dae-37af-56c2-b7b1-a76f99a4bbf1","sourceKey":"bank:ACS101:HIS-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the usual progression of membership grades in an actuarial professional body?","options":["Associate, then Student, then Fellow","Student, then Associate, then Fellow","Fellow, then Associate, then Student","Student, then Fellow, then Associate"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"A person joins as a student while sitting exams, qualifies as an Associate after the earlier stages, and becomes a Fellow, the highest qualified grade, after the final exams and experience. Options A, D and C put the grades in the wrong order."}},{"itemId":"99e974c6-8199-510d-af28-2b3c87565d88","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a2792bd1-0f95-5926-9ab3-8bf716e501c6","sourceKey":"bank:ACS101:HIS-050","parentItemId":null,"revision":1,"payload":{"prompt":"Exam FM is one of the preliminary exams recognised by both the SOA and the CAS. What subject does it cover?","options":["Financial Mathematics","Fundamental Mortality","Fire and Marine insurance","Financial Management of insurers"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"Exam FM (formerly Exam 2) is Financial Mathematics, covering interest, annuities and the time value of money; Exam P is Probability. Options D, B and C are guesses at the letters that do not match the actual exam."}},{"itemId":"1cdf6acc-c6dd-5d05-8086-f60342aadda3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a772bb4d-816d-5ea5-b281-21b98d2ff12c","sourceKey":"bank:ACS101:HIS-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes a Fellow of the Society of Actuaries (FSA)?","options":["Has passed only the preliminary probability and financial mathematics exams","Has registered as a student but has not yet passed any exams","Has been elected for services to the profession without passing exams","Has shown knowledge in all major practice areas, with further concentration in one or more of them"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"An FSA has demonstrated knowledge across all major practice areas, concentrated further in one or more, and received further education in professionalism. Option A describes an early-stage student, B a new student, and C sounds like honorary membership rather than fellowship."}},{"itemId":"18ab3558-09bd-547c-956a-bde801875bc1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a65268e1-d44d-5509-8aab-cc903ab043e4","sourceKey":"bank:ACS101:HIS-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about how actuaries usually qualify is correct?","options":["They must stop working until every professional exam has been passed","They qualify by passing one final exam set by the national insurance regulator","They qualify automatically on completing a first degree in actuarial science","They pass a series of professional exams, usually while working, so they earn while they learn"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"Professional designation comes from passing a series of exams, and most candidates work and study at the same time. A degree (C) may give exemptions but does not qualify anyone by itself, regulators (B) do not set the qualifying exams, and A is the opposite of the usual earn-while-you-learn path."}},{"itemId":"5d511af8-84a8-5d54-b067-0b316abc1a7e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fa600672-6dac-5537-ac04-ecc8fb974d78","sourceKey":"bank:ACS101:HIS-054","parentItemId":null,"revision":1,"payload":{"prompt":"A Code of Professional Conduct sets out the responsibilities of actuaries. Which of the following is NOT one of the groups the Code says actuaries have responsibilities to?","options":["The public","Their clients and employers","Competing actuarial firms seeking their clients","The actuarial profession"],"correctOption":2,"section":"History and Professional Structure of Actuarial Science","explanation":"The Code identifies responsibilities to the public, to clients and employers, and to the actuarial profession. Options A, B and D are exactly those groups, so the odd one out is competing firms, which the Code does not list."}},{"itemId":"2b7bf50d-2ad9-5504-98f1-388bad2d4863","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5b2ece69-dd47-5f99-a763-a2136f03d604","sourceKey":"bank:ACS101:HIS-055","parentItemId":null,"revision":1,"payload":{"prompt":"In the United States, which body promulgates the Actuarial Standards of Practice (ASOPs) that say what an actuary should consider, document and disclose on an assignment?","options":["The Actuarial Standards Board (ASB)","The Casualty Actuarial Society (CAS)","The International Actuarial Association (IAA)","The Institute and Faculty of Actuaries (IFoA)"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"The ASB issues the ASOPs used by actuaries working in the United States. The IAA (C) issues model international standards (ISAPs), the CAS (B) is a qualifying body, and the IFoA (D) is a UK body."}},{"itemId":"dce768af-fa7e-590a-9121-60f9ba34711a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"24274005-dba7-508a-a519-afbfef36e9d5","sourceKey":"bank:ACS101:HIS-056","parentItemId":null,"revision":1,"payload":{"prompt":"The American Academy of Actuaries was established in 1965. What is the significance of its MAAA designation for actuaries working in the United States?","options":["It must be held to sign statements of actuarial opinion","It is the first exam a student must pass to start actuarial training","It is given only to actuaries who work for the US government","It replaces the need to hold an SOA or CAS qualification"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"MAAA (Member, American Academy of Actuaries) is required before a US actuary can sign statements of actuarial opinion. It is not an exam (B), it does not replace SOA or CAS credentials (D), and it is not limited to government actuaries (C)."}},{"itemId":"a08eae5c-bae0-5214-924d-b9ace8af6438","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3c1e5d8-ab39-5bd6-98f4-2c84eaf9b903","sourceKey":"bank:ACS101:HIS-057","parentItemId":null,"revision":1,"payload":{"prompt":"A client in the United States complains that an actuary breached the professional code of conduct. Which body reviews such complaints and can recommend discipline?","options":["The Actuarial Board for Counseling and Discipline (ABCD)","The National Insurance Commission (NAICOM)","The International Actuarial Association (IAA)","The Actuarial Standards Board (ASB)"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"The ABCD reviews complaints about possible breaches of the Code, advises actuaries on professional conduct and can recommend discipline. The ASB (D) writes standards rather than hearing complaints, the IAA (C) is an international association of associations, and NAICOM (B) is a Nigerian insurance regulator."}},{"itemId":"bcc823b9-6f6b-5be0-a205-3562991b41c7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"23bc7fe0-b237-5653-825a-1411726999ac","sourceKey":"bank:ACS101:HIS-058","parentItemId":null,"revision":1,"payload":{"prompt":"When actuarial professional bodies were founded in the mid-19th century, what was one of their main purposes besides supporting actuaries?","options":["Protecting the public by ensuring members' competence and ethical standards","Setting the premium rates that every insurer had to charge","Collecting taxes on insurance premiums for the government","Selling life policies directly to the public"],"correctOption":0,"section":"History and Professional Structure of Actuarial Science","explanation":"Professional bodies were created to support actuaries and to protect the public by making sure members are competent and ethical, through exams, codes and standards. Options D and B are insurers' commercial activities, and C is a government function."}},{"itemId":"81b067a9-22cb-5207-a1c4-ba59e95921c3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3fda5af-952b-5eb5-bc62-f2438471ce8f","sourceKey":"bank:ACS101:HIS-059","parentItemId":null,"revision":1,"payload":{"prompt":"IFoA Specialist Principles subjects reflect the main career areas of actuaries. Which of the following is NOT one of them?","options":["Enterprise Risk Management","Health and Care","Pensions and Other Benefits","Tax Auditing"],"correctOption":3,"section":"History and Professional Structure of Actuarial Science","explanation":"The Specialist Principles cover Health and Care, Life Insurance, Pensions and Other Benefits, Investment and Finance, Financial Derivatives, General Insurance Reserving, General Insurance Pricing and Enterprise Risk Management. Options B, C and A are on that list, but tax auditing is accounting work, not an actuarial specialism."}},{"itemId":"7c6052d3-9141-5222-9ac7-443b343bea49","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1b08dd4-0ae1-531e-9772-ba2e9b998cf5","sourceKey":"bank:ACS101:HIS-060","parentItemId":null,"revision":1,"payload":{"prompt":"Ngozi works for a consulting firm in Abuja. Her job is to project the salaries and retirement ages of a company's staff and estimate how much must be set aside to pay their future retirement benefits. Which actuarial specialisation is this?","options":["Health and care","Pensions","Financial derivatives","General insurance pricing"],"correctOption":1,"section":"History and Professional Structure of Actuarial Science","explanation":"Projecting members' salaries and retirement benefits and the funding needed for them is pensions work. General insurance pricing (D) sets rates for cover such as motor or fire, financial derivatives (C) values options and similar contracts, and health and care (A) deals with medical and care costs."}},{"itemId":"ae886a9e-fb16-55c3-8713-dd28b40bfdd3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0faef3cb-7701-5aa5-9487-c61bd7645510","sourceKey":"bank:ACS101:LIF-001","parentItemId":null,"revision":1,"payload":{"prompt":"In the international actuarial notation, the lower space to the RIGHT of a principal symbol (as in q_x) is reserved for signs indicating which of the following?","options":["The ages of the lives and the order of succession of events","Any other notion the user wishes to add","The periodicity (frequency) of the payments","The duration of the operation and its position in time"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The lower right space carries the age conditions, which is why the age x sits there in l_x, q_x and A_x, and it also shows the order in which lives fail. Option D describes the lower left space, Option C the upper right space and Option B the upper left space."}},{"itemId":"8f3f480e-6dd8-5d75-89de-0249635b4b20","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7e220a80-44d9-59b6-969e-7116c5c78439","sourceKey":"bank:ACS101:LIF-002","parentItemId":null,"revision":1,"payload":{"prompt":"Under the general principles of the international actuarial notation, which position around a principal symbol is reserved for signs showing the duration of the operation and its position with regard to time?","options":["The upper space to the right","The lower space to the left","The lower space to the right","The upper space to the left"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Duration and timing conditions go in the lower left, which is why the n in a term such as 5p_x or the deferment m in m|q_x is written before the main letter. Option C is for ages, Option A is for periodicity and Option D is left free for other notions."}},{"itemId":"5cf91c4c-82eb-53ea-af5e-311482e8b481","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5bb309a0-6f11-5d22-bccd-4f07ef315517","sourceKey":"bank:ACS101:LIF-003","parentItemId":null,"revision":1,"payload":{"prompt":"In the symbol i^(m), the m is written in the upper space to the right of i. In the international actuarial notation this position indicates which of the following?","options":["The length of the term-certain in years","The age of the life involved","The order in which the lives are to fail","The periodicity of the events, for example how often interest is convertible"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The upper right space is reserved for periodicity, so i^(m) means a nominal rate convertible m times a year. Option B belongs in the lower right space, Option A is shown by the angle n| and Option C is shown by numerals over or under the suffix."}},{"itemId":"574ef9fe-ae75-5e10-aef3-0adf987c0a9c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"44111cf8-37aa-5193-9870-bf9190434c42","sourceKey":"bank:ACS101:LIF-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about the upper space to the LEFT of a principal symbol in the international actuarial notation is correct?","options":["It is reserved for the duration of the operation","It is reserved for the frequency of payment","It is free, and signs for other notions can be placed in it","It is reserved for the ages of the lives involved"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The upper left space is the one position the system leaves free, so other notions can be placed there when needed. Option D is the lower right space, Option B is the upper right space and Option A is the lower left space."}},{"itemId":"e82bb41e-8f6f-5fa2-bbad-e2b32ae8b8da","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cffb3175-d182-5abe-a967-8a391b79e06e","sourceKey":"bank:ACS101:LIF-005","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation, what does the symbol (x), a letter enclosed in brackets, denote?","options":["The probability of dying at age x","A term-certain of x years","The number of persons living at age x","A person aged x"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A letter in round brackets, such as (x) or (40), stands for a life of that age, so (x) is read as 'a person aged x'. Option C is l_x, Option A is q_x, and Option B would be shown by an angle, as in n|."}},{"itemId":"c96e3a71-1229-530f-98c4-f03b01814b15","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1b970129-fc6b-538c-bca5-771a66d72373","sourceKey":"bank:ACS101:LIF-006","parentItemId":null,"revision":1,"payload":{"prompt":"In the symbols a_n| and s_n|, the n written inside a right-angle mark (n|) indicates which of the following?","options":["A deferment of n years after death","Payments made n times a year","A person aged n","A term-certain of n years"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The right-angle mark around n shows a fixed term of n years that does not depend on anyone being alive, so a_n| is an annuity-certain for n years. Option C would be written (n), and Option B is a periodicity sign that goes in the upper right space."}},{"itemId":"e511e875-e8ad-5c5e-9d35-76f728a2575a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"54f5b2eb-f1b1-5a6e-822e-4169fe0da189","sourceKey":"bank:ACS101:LIF-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which actuarial symbol denotes the total interest earned on 1 in a year, assuming any interest received more often than yearly is reinvested immediately on the same terms as the original principal?","options":["d","delta","i","v"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"This is the definition of i, the effective rate of interest per year. Option A, d, is the discount on 1 due a year hence, Option D, v, is the present value of 1 due a year hence, and Option B, delta, is the force of interest."}},{"itemId":"ceb8f263-b722-50b3-9ef0-89db351254f0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2a4ed4a9-d6ef-52eb-a1d3-be376f95db11","sourceKey":"bank:ACS101:LIF-008","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation, what does the symbol v represent?","options":["The present value of 1 due a year hence","The accumulated value of 1 after one year","The nominal rate of interest convertible m times a year","The discount on 1 due a year hence"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"v is the discount factor, v = 1/(1+i): the amount needed now to have 1 in one year's time. Option D is d = 1 - v, Option B is 1 + i, and Option C is i^(m)."}},{"itemId":"76dd70b8-96b5-5fa4-8dfa-847dea6d30a0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"25e12e4e-a2d1-5bfe-87da-dfbb8d58d079","sourceKey":"bank:ACS101:LIF-009","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation, the symbol d (when used with interest) stands for which of the following?","options":["The discount on 1 due a year hence","The present value of 1 due a year hence","The number of persons dying at age x","The force of interest"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"In interest theory, d is the effective rate of discount: the discount allowed when 1 due in a year is paid now, so d = 1 - v. Option B is v. Option C is also written with the letter d, but in the mortality table it carries an age suffix, as in d_x."}},{"itemId":"d61f70d6-4332-51b4-b7aa-4ab828bc0cab","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1403bc46-1838-53c3-ae85-a73168646362","sourceKey":"bank:ACS101:LIF-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which symbol is used in actuarial notation for the force of interest, the instantaneous rate of growth that acts like a nominal rate compounded continuously?","options":["m","delta","mu","i^(m)"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The force of interest is written delta, and it satisfies 1 + i = e^delta. Option C, mu, is the force of mortality, Option D is a nominal rate convertible m times a year, and Option A, m, is the central death rate."}},{"itemId":"a4682d5c-be44-59a8-bacb-48eadbf1a225","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ac9f8243-cf39-55cf-8872-e071a1fbce84","sourceKey":"bank:ACS101:LIF-011","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank quotes a savings product at '12% per annum convertible monthly'. Written in standard actuarial notation, this quoted rate is","options":["delta = 0.12","d^(12) = 0.12","i = 0.12","i^(12) = 0.12"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A rate convertible m times a year is a nominal rate, written i^(m), so monthly conversion gives i^(12) = 0.12. Option C would mean 12% effective a year, which is lower than the true effective rate here, and Option A would mean continuous compounding."}},{"itemId":"4165fbc5-3e8e-5b6a-98a9-c044f12df40e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"19807ae7-a994-5f05-b8e9-d592def1556c","sourceKey":"bank:ACS101:LIF-012","parentItemId":null,"revision":1,"payload":{"prompt":"In a mortality table, which symbol gives the number of persons who attain exact age x?","options":["d_x","p_x","l_x","e_x"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_x (l for 'living') is the number of the original group who survive to exact age x. Option A counts those who die between ages x and x+1, Option B is a probability rather than a number, and Option D is the expectation of life."}},{"itemId":"108ec943-a913-542e-bf38-d3f5b00e0050","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3e10443c-e14f-50bf-9568-3689105bb75f","sourceKey":"bank:ACS101:LIF-013","parentItemId":null,"revision":1,"payload":{"prompt":"In a mortality table, d_x = l_x - l_(x+1). What does d_x measure?","options":["The number of persons who die between ages x and x+1","The present value of an assurance on a life aged x","The number of persons alive at age x+1","The probability that a person aged x dies within one year"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"d_x is a count: the people alive at age x minus those still alive at x+1, which gives the number who die during that year of age. Option D is q_x = d_x / l_x, a probability rather than a count, and Option C is l_(x+1)."}},{"itemId":"809587c9-b34f-546d-9987-1971b15dbdc0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"676dc759-2ad4-529b-b5f6-45b0fe81346e","sourceKey":"bank:ACS101:LIF-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which symbol denotes the probability that a person aged x will die within one year?","options":["mu_x","d_x","p_x","q_x"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"q_x is the one-year probability of dying for (x), and it equals d_x / l_x. Option C is the probability of surviving the year, Option B is the number who die, not a probability, and Option A is the force of mortality."}},{"itemId":"4985c157-c38d-5768-b0e2-bb798618a994","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a868c610-5cad-5213-9eb9-4ec80135bf2c","sourceKey":"bank:ACS101:LIF-015","parentItemId":null,"revision":1,"payload":{"prompt":"For a life aged x, which relationship between p_x and q_x always holds?","options":["p_x + q_x = 1","p_x x q_x = 1","p_x = q_x / l_x","p_x - q_x = 1"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Within one year a life aged x either survives (probability p_x) or dies (probability q_x), so the two probabilities add up to 1. Option D would force p_x to be greater than 1, which is impossible for a probability, and Options C and B do not describe how survival and death share the year."}},{"itemId":"776e30d9-9d88-5168-bfcb-e57a9fdd73d2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8d0501eb-541f-562b-863f-6b249ee58aed","sourceKey":"bank:ACS101:LIF-016","parentItemId":null,"revision":1,"payload":{"prompt":"Among the fundamental symbolic letters for mortality tables, which letter stands for the force of mortality?","options":["delta","m","q","mu"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The Greek letter mu (written mu_x at age x) is the force of mortality, the instantaneous rate of dying. Option B, m, is the central death rate, Option C, q, is the probability of dying, and Option A, delta, is the force of interest."}},{"itemId":"51623620-df68-55c3-a8c9-9558882332f0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c5c17f96-d2ad-5eb6-9194-78a5f631cbe9","sourceKey":"bank:ACS101:LIF-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following pairs of fundamental actuarial letters and meanings is NOT correctly matched?","options":["A = present value of an assurance","V = policy value","W = paid-up policy","s = present value of an annuity"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"In the notation, s is the amount (accumulated value) of an annuity, and a is the present value of an annuity, so the pairing in this option is wrong. Options A, B and C are all correct pairings from the list of fundamental symbols."}},{"itemId":"273742a9-1c0a-5a98-9ab5-f8b2b2e76ee9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"844e86a3-085a-5710-af69-41598153ffe4","sourceKey":"bank:ACS101:LIF-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which fundamental actuarial letter denotes the present value of an endowment, that is, a sum paid only if the life survives to the end of a stated period?","options":["e","E","P","A"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"E stands for the present value of a pure endowment. Option D, A, is the present value of an assurance (paid on death), Option A, small e, is the expectation of life, and Option C, P, is a premium."}},{"itemId":"0745c571-ee4a-5c09-a0cb-fda51a0b2312","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"07a0cbf3-b4bc-5f4a-9d5d-de06d5260b8a","sourceKey":"bank:ACS101:LIF-019","parentItemId":null,"revision":1,"payload":{"prompt":"In the international actuarial notation, the symbol e_x (with no mark above the e) denotes which of the following?","options":["The curtate expectation of life (average after-lifetime) of (x)","The number of persons who die at age x","The complete expectation of life of (x)","The present value of an endowment on (x)"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"e_x without a mark is the curtate expectation of life, which counts only complete future years lived by (x). Option C is shown by a small circle over the e, Option D is capital E, and Option B is d_x."}},{"itemId":"115b1ffe-461f-5203-b2fd-7ae03c2c5ed3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a8b24336-4cd9-575a-b927-b0fb393e0dca","sourceKey":"bank:ACS101:LIF-020","parentItemId":null,"revision":1,"payload":{"prompt":"When a small circle is placed over the letter e in the expectation-of-life symbol, what does the circle indicate?","options":["That the life is a select life","That payments are made at the beginning of each year","That the expectation is complete rather than curtate","That payments are made continuously"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A small circle over a principal symbol means the benefit is complete, so e with a circle is the complete expectation of life. Option D is shown by a bar over the symbol, Option A by square brackets around the age, and Option B by the trema (two dots)."}},{"itemId":"477f4556-cc2f-5ac5-886c-b1e77f91a112","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f5f91b8d-16ab-5db2-9585-7cc4d436b265","sourceKey":"bank:ACS101:LIF-021","parentItemId":null,"revision":1,"payload":{"prompt":"A horizontal bar placed over a principal symbol, as in A-bar_x, indicates which of the following?","options":["The benefit is complete rather than curtate","The benefit is payable at the beginning of each year","The benefit is continuous or payable at the moment of death","The benefit is on the last survivor of several lives"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A bar over the main letter means the payments are continuous (momently), so A-bar_x is an assurance payable at the moment of death. Option A is shown by a small circle, Option B by the trema (two dots), and Option D by a bar over the suffix, not over the main letter."}},{"itemId":"e1ec5527-7256-5784-b60b-295efcdabe05","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"90b97866-894e-5792-8b27-4901917aa8bc","sourceKey":"bank:ACS101:LIF-022","parentItemId":null,"revision":1,"payload":{"prompt":"The diaeresis or trema (two dots) placed above a or s, as in a-double-dot_n| (the annuity-due), is a symbol of","options":["continuous payment","a complete benefit","a select life","acceleration of payments"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The two dots show that each payment is brought forward by one period, so an annuity-due pays at the start of each year instead of the end. Option A is shown by a bar, Option B by a small circle and Option C by square brackets around the age."}},{"itemId":"5eb79615-41bf-5d4b-9ba7-6243bb86def0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8a3460cc-5ca7-5754-98e4-2bd45701b5ca","sourceKey":"bank:ACS101:LIF-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which symbol denotes the amount (accumulated value at the end of the term) of an annuity-certain of 1 per annum for n years, payments made at the END of each year?","options":["s-double-dot_n| (annuity-due)","s_n|","a_n|","a-double-dot_n| (annuity-due)"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"s_n| is the accumulated value at time n of payments of 1 made at the end of each year for n years. Option C, a_n|, is the present value of the same annuity, and Options A and D are for annuities-due, which pay at the beginning of each year."}},{"itemId":"bd60b7d8-4ffb-5de9-b4c0-caa4c0c0aaed","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"30e5ab9e-7772-5541-928a-319bed0e8399","sourceKey":"bank:ACS101:LIF-024","parentItemId":null,"revision":1,"payload":{"prompt":"The 1949 revision of the international actuarial notation introduced the symbol s-double-dot_n|. What does it represent?","options":["The present value of a continuous annuity","The present value of an annuity-due","The accumulated amount of an annuity paid at the end of each year","The accumulated amount at the end of the term of an annuity-due"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Adopting the trema for annuities-due made room for s-double-dot_n|, the accumulated amount of an annuity-due at the end of the term, which previously had no symbol. Option B is a-double-dot_n|, Option C is s_n| and Option A is a-bar_n|."}},{"itemId":"39c39980-4a39-5109-bfe1-297c27881431","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a76e4d25-bf7b-5492-b8ac-58613c1cd5e2","sourceKey":"bank:ACS101:LIF-025","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation, two or more letters written in a suffix without any distinguishing mark, as in a_xyz, indicate which of the following?","options":["The last survivor of the lives","Joint lives, so the status lasts while all the lives survive","The order in which the lives must die","A reversionary benefit after the first death"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Letters placed side by side in the suffix mean joint lives, so a_xyz is paid at the end of each year while (x), (y) and (z) are all alive. Option A needs a horizontal bar over the suffix, Option D uses a perpendicular bar, and Option C uses numerals over or under the suffix."}},{"itemId":"c9f2c180-f56b-5271-ad34-3011278454d7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3247d11-7311-5c5c-8098-d0834c51417b","sourceKey":"bank:ACS101:LIF-026","parentItemId":null,"revision":1,"payload":{"prompt":"Why is a colon, rather than a point or a comma, used to separate items in a suffix such as a_(x:n|)?","options":["To show that the benefit is deferred","To show that the lives are last survivors","To show that the life was select at entry","To avoid confusion with decimals when numbers are involved"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The colon only separates the items in the suffix. A point or comma could be misread as a decimal point when the ages are numbers, as in a_(40:10|). The other options describe marks with other jobs: a horizontal bar for survivors, a vertical bar or left subscript for deferment, and square brackets for selection."}},{"itemId":"074d751b-2689-5797-8180-bb0402b0aac0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"153cc8a8-3a11-5a0a-9370-2c3027a9db2c","sourceKey":"bank:ACS101:LIF-027","parentItemId":null,"revision":1,"payload":{"prompt":"What does the symbol a_(x:n|) represent?","options":["An annuity-certain for n years","A whole-life annuity on (x) deferred n years","A temporary life annuity on (x) for n years","An endowment assurance on (x) for n years"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The status x:n| lasts for the joint duration of the life of (x) and a term of n years, so the annuity stops at death or after n years, whichever comes first. This is a temporary annuity. Option A ignores the life, Option B would need a deferment sign on the left, and Option D is A_(x:n|)."}},{"itemId":"d6b339dc-c8cf-5584-8196-a37a70f88108","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"46ce0f95-c7a3-536a-9bd4-ba6d7b8e3fda","sourceKey":"bank:ACS101:LIF-028","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian life office sells a 15-year policy to a 35-year-old: N2,000,000 is paid at the end of the year of death if death occurs within 15 years, or at the end of 15 years if the policyholder is then alive. Ignoring the sum assured, the actuarial symbol for this benefit is","options":["A_(35:15|)","E_35","A_35","a_(35:15|)"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The policy pays on death within the term OR on survival to the end of it, which is an endowment assurance, A_(x:n|), here with x = 35 and n = 15. Option C is a whole-life assurance with no term, Option D is a temporary annuity, and Option B has no term shown and covers survival only."}},{"itemId":"ba6bfe6e-b672-5ae7-af91-0ed29e7744e6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"594c21bd-0bf6-55e9-aaa1-3231d145819d","sourceKey":"bank:ACS101:LIF-029","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial notation a perpendicular (vertical) bar separating the lives in a suffix, as in a_(y|x), means that the status after the bar follows the status before it. a_(y|x) is therefore","options":["an annuity to (y) payable after the death of (x)","an annuity payable while at least one of (x) and (y) is alive","a reversionary annuity to (x) payable after the death of (y)","a joint-life annuity on (x) and (y)"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"With a vertical bar, the status after the bar (x) takes over when the status before it (y) fails, so payments to (x) begin after (y) dies. Option D would be written a_xy, Option B needs a horizontal bar over xy, and Option A reverses the order."}},{"itemId":"fd7e45bf-9abe-527d-9f27-29f2fc1c06d7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ba480c6f-972d-56ea-85a5-bf74f9f102d7","sourceKey":"bank:ACS101:LIF-030","parentItemId":null,"revision":1,"payload":{"prompt":"A horizontal bar over the suffix with a number above it shows how many survivors are needed. What is the difference between writing 2 and writing [2] above the bar for three lives (x), (y) and (z)?","options":["2 means exactly two survivors; [2] means at least two survivors","There is no difference; the brackets are optional","2 means at least two survivors; [2] means exactly two survivors","2 means two joint lives; [2] means two reversionary lives"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A plain number r over the bar means at least r survivors, while the same number in square brackets means exactly r survivors. If no number is shown, at least one survivor is meant. Option A swaps the two meanings, and Option B is wrong because the brackets change the meaning."}},{"itemId":"9ff1bb4d-c996-5437-96d2-f86ba5403830","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"abe03d43-10d5-53c7-913b-7507fdd0a286","sourceKey":"bank:ACS101:LIF-031","parentItemId":null,"revision":1,"payload":{"prompt":"In the symbol A^1_(xy), with the numeral 1 placed over the x, what does the numeral show?","options":["The assurance is paid on the first death of either life","The assurance is paid at the end of the year of death of (x) only if (x) dies first of the two lives","The assurance is paid if exactly one life survives","The assurance covers one year only"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Numerals over or under the suffix give the order in which the lives must fail, so 1 over x means the benefit is paid on (x)'s death only if (x) dies before (y). Option A would be a joint-life assurance A_xy, Option D confuses the numeral with a term, and Option C is a survivorship symbol with [1] over a bar."}},{"itemId":"eb8a9282-2ef4-5ca5-bf82-71d189af9bd3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"31abe99d-43a2-5d6f-83e2-37f3483c9c68","sourceKey":"bank:ACS101:LIF-032","parentItemId":null,"revision":1,"payload":{"prompt":"If the age suffix of an actuarial symbol is enclosed in square brackets, as in l_[x]+t, what does this indicate?","options":["The benefit is payable continuously","The life is one of several joint lives","The age has been rounded to the nearest birthday","Selection: the life was selected at age x and t years have passed since selection"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Square brackets around the age mark the age at selection, and the number outside the brackets is the time since selection. So l_[x]+t is the number in the select table, selected at age x, who have reached age x + t. Option B uses plain letters in the suffix and Option A uses a bar over the main letter."}},{"itemId":"e0f766ec-d5c3-5f2b-9f07-b2abff3c6a31","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"495f437b-cd71-5244-bf61-4ef12e58d450","sourceKey":"bank:ACS101:LIF-033","parentItemId":null,"revision":1,"payload":{"prompt":"In select-table notation, a_[x-n]+n denotes the value of an annuity on a life","options":["now aged x who is select today","now aged x who was selected n years ago at age x - n","now aged x - n who will be selected in n years","aged x + n who was selected at age x"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The age inside the brackets is the age at selection (x - n), and adding n gives the present age x. Option A describes a_[x], a life aged x who is select now, and Option C turns the time order around."}},{"itemId":"72dab0d2-4ba3-5a4d-9e0c-1c6b71823587","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"23bace35-4c69-5deb-9999-c81e2a78832f","sourceKey":"bank:ACS101:LIF-034","parentItemId":null,"revision":1,"payload":{"prompt":"In the international actuarial notation, a single accent and a double accent on the premium symbol (P' and P'') are used to denote, respectively,","options":["a premium paid monthly, and a premium paid quarterly","the office premium, and the net premium","a valuation premium other than the net premium, and the office (commercial) premium","a single premium, and an annual premium"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Accents mark modified premiums: P' is a premium other than the net premium used in a valuation, and P'' is the office (commercial) premium. Option B gets the pairs wrong, and Option A confuses accents with periodicity, which is written in the upper right space."}},{"itemId":"71dedde9-b7be-57d6-821f-0c86bf4fd8b6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"df161c0f-bd63-545b-8c7d-9c810ddbbd1a","sourceKey":"bank:ACS101:LIF-035","parentItemId":null,"revision":1,"payload":{"prompt":"In compound actuarial symbols, (Ia) denotes","options":["an annuity whose payments vary irregularly","an annuity starting at 1 and increasing by 1 per annum","an annuity paid at the beginning of each year","an annuity starting at n and decreasing by 1 per annum"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The letter I in front of a symbol means an increasing benefit, so (Ia) pays 1, 2, 3 and so on. Option D uses D for decreasing, Option A uses the varying symbol, and Option C is shown by the trema, not by I."}},{"itemId":"a43fed8b-cc3e-5c55-83b2-7bef0a18095e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ef774132-9140-568d-89ea-baa0f73d7f9b","sourceKey":"bank:ACS101:LIF-036","parentItemId":null,"revision":1,"payload":{"prompt":"The 1949 revision of the international actuarial notation brought in several changes. Which of the following was NOT one of them?","options":["Adopting a-double-dot for an annuity-due (first payment made at once)","Replacing j(m) with i^(m) for the nominal rate of interest","Adopting U as the official international symbol for a surrender value","Introducing D in compound symbols for decreasing benefits"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A proposal to make U the official symbol for the surrender value was not adopted. It was only agreed that U should be chosen if a symbol were ever needed. Options B, A and D were all listed among the changes introduced."}},{"itemId":"198dcb5f-7cd2-5faf-9fec-9afad092dc13","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9d00f224-2076-5535-a5b9-0ce884ae615c","sourceKey":"bank:ACS101:LIF-037","parentItemId":null,"revision":1,"payload":{"prompt":"The existing international actuarial notation was set out in an explanatory statement that was unanimously adopted at which gathering?","options":["A Lucerne congress held in 1940","The Second International Actuarial Congress, London, 1898","The Eleventh International Actuarial Congress, Paris, 1937","The Third International Actuarial Congress, Paris, 1900"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The notation, based on George King's 'Key to the Notation', was adopted unanimously at the Second International Actuarial Congress in London in May 1898. Option D was where Dr Sprague's rearranged statement was submitted, Option C only appointed a committee on notation, and Option A never took place because of the war."}},{"itemId":"212b0629-9862-5284-b81f-1faf9af65419","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"230bd4a0-e8b9-5f3a-b341-66e745dd4a5a","sourceKey":"bank:ACS101:LIF-038","parentItemId":null,"revision":1,"payload":{"prompt":"In the context of life tables, mortality is best described as","options":["the process of deciding whether to accept a risk for insurance","the number of persons alive at each exact age","the average number of years a newborn is expected to live","the incidence of death in a population, often measured by the probability that an individual dies within a period"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Mortality is the incidence of death in a population. It is usually measured by probabilities of dying such as q_x, which is exactly what a mortality (life) table gives. Option C is the expectation of life, Option B is the l_x column, and Option A is selection."}},{"itemId":"85752fd3-dfe9-5c6a-9cd4-f5e77ab4fa4b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"047b3ef1-bfda-57c0-87d5-04917a4a5324","sourceKey":"bank:ACS101:LIF-039","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary at a Lagos life insurer is pricing a new term assurance and needs the probability that a 45-year-old policyholder dies within the next year. Which column of a life table gives this directly?","options":["q_x","e_x","d_x","l_x"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The q_x column gives the one-year probability of death for a life aged x, which is the key mortality input for pricing term cover. Option D gives numbers alive and Option C gives numbers dying, which must be divided by l_x to get a probability. Option B gives the average future lifetime."}},{"itemId":"4b4cedef-cba8-56b5-b693-72b2c31c810c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"feb6656e-b0b7-5233-8acf-6b261b367289","sourceKey":"bank:ACS101:LIF-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of a standard life (mortality) table built from a radix l_0?","options":["p_x + q_x = 1 at each age","d_x = l_x - l_(x+1) for each age","The l_x column increases as age increases","The sum of d_x from age x to the end of the table equals l_x"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Nobody joins the group after birth and people leave it only by dying, so l_x can only stay the same or fall as x rises. Options B and A are basic relations of the table, and Option D holds because everyone alive at age x must die at some later age."}},{"itemId":"711f88db-2e18-521c-a826-28dcd48402f8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d9f2590b-aa78-52b4-bea8-d341b857c82c","sourceKey":"bank:ACS101:LIF-041","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, the starting number l_0, chosen as a convenient round figure such as 100,000, is called the","options":["central death rate","force of mortality","limiting age of the table","radix of the table"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The radix is the arbitrary starting size of the group at age 0, from which every later l_x is worked out. Option A, m_x, and Option B, mu_x, are measures of mortality, and Option C is the age by which nobody is left (l_x = 0)."}},{"itemId":"d1aeec42-e80b-55e7-bdc0-27b1914ead60","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4cabbede-5695-59db-8611-43aa45c4a0ed","sourceKey":"bank:ACS101:LIF-042","parentItemId":null,"revision":1,"payload":{"prompt":"The curtate expectation of life e_x can be described as the value of a life annuity a_x (payments of 1 at the end of each year while (x) is alive) when it is valued at which rate of interest?","options":["The force of mortality mu_x","i = 0","i = 1","The rate d = i/(1+i)"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"If i = 0, every payment of 1 is worth exactly 1 today, so a_x just counts the expected number of future anniversaries survived, which is e_x. The other options do not reduce a_x to a simple count of years survived."}},{"itemId":"4033bbf8-1980-527c-b769-4cbabffbad32","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1341e9d5-8c3a-5984-9390-0e89129d74da","sourceKey":"bank:ACS101:LIF-043","parentItemId":null,"revision":1,"payload":{"prompt":"A 2022 review of the Nigerian actuarial market noted that there were 'no local actuarial tables'. What is the main practical consequence for Nigerian life insurers?","options":["Their q_x and l_x values must be based on mortality tables built from other populations","Their annuities must all be annuities-due","They must price all life policies without interest","They cannot use the symbol l_x in their calculations"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Without a local life table, insurers have to use or adapt foreign mortality tables, which may not reflect Nigerian mortality, for their survival and death probabilities. The other options do not follow, because notation, interest and payment timing do not depend on whether a local table exists."}},{"itemId":"1a1734ed-feff-504c-bbc4-2ed21eaed5aa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6c70f52c-5065-5535-ad73-0c3e82d56123","sourceKey":"bank:ACS101:LIF-044","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate d_52, the number of persons dying between exact ages 52 and 53.","options":["168","211","188","506"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"d_52 = l_52 - l_53 = 9,682 - 9,494 = 188. Option A is d_51 (the wrong year), Option B is d_53, and Option D counts all the deaths from age 50 to 53."}},{"itemId":"c6b759e9-18f0-5bde-a89e-4b3701f0844a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1201b04-8743-53a2-8292-d8a6562ea9f5","sourceKey":"bank:ACS101:LIF-045","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate q_51, correct to 5 decimal places.","options":["0.01735","0.01523","0.01706","0.98294"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"q_51 = d_51 / l_51 = (9,850 - 9,682)/9,850 = 168/9,850 = 0.01706. Option A divides by l_52 instead of l_51, Option D is p_51, and Option B uses the deaths at age 50."}},{"itemId":"7fff8e58-a965-50b0-8ec2-3846e7cb0d66","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"07b59b67-0698-502c-8799-69c277f1e3e9","sourceKey":"bank:ACS101:LIF-046","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate p_53, the probability that a life aged 53 survives one year, correct to 5 decimal places.","options":["0.02222","0.97778","0.98058","0.92830"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"p_53 = l_54 / l_53 = 9,283/9,494 = 0.97778. Option A is q_53 = 1 - p_53, Option C is p_52 (one year too early), and Option D wrongly divides by the radix of this extract, l_50."}},{"itemId":"a0f40333-81f6-5652-b768-977bbcd4ed8a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1cbed183-1ea1-51b7-a967-4591a439913c","sourceKey":"bank:ACS101:LIF-047","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate 3p50, the probability that a life aged 50 survives to age 53, correct to 4 decimal places.","options":["0.0506","0.9494","0.9283","0.9682"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"3p50 = l_53 / l_50 = 9,494/10,000 = 0.9494. Option D uses l_52 (only 2 years), Option C uses l_54 (4 years), and Option A is 3q50, the probability of dying instead."}},{"itemId":"7174c0be-811e-502d-b6e7-7ca88a92ccdd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4549fefa-4f02-5658-8cd6-f5260fbb4c69","sourceKey":"bank:ACS101:LIF-048","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate 2q51, the probability that a life aged 51 dies before age 53, correct to 4 decimal places.","options":["0.0361","0.9639","0.0356","0.0171"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"2q51 = (l_51 - l_53)/l_51 = (9,850 - 9,494)/9,850 = 356/9,850 = 0.0361. Option D counts only one year of deaths (q_51), Option C divides by l_50 instead of l_51, and Option B is 2p51."}},{"itemId":"d92d3cd6-5238-57f4-ac2b-c0ce520ec2d9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"10254d1e-3ca6-5120-97c5-a3a3503ea992","sourceKey":"bank:ACS101:LIF-049","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate 2|q50, the probability that a life aged 50 survives 2 years and then dies in the following year (between ages 52 and 53), correct to 5 decimal places.","options":["0.01680","0.01880","0.01942","0.05060"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"2|q50 = d_52 / l_50 = (9,682 - 9,494)/10,000 = 188/10,000 = 0.01880. Option C is q_52, which divides by l_52 and so ignores the need to survive from 50 to 52. Option D is 3q50 (death at any time in 3 years), and Option A uses the deaths in the wrong year."}},{"itemId":"80838681-abfd-50dd-aada-63b1a0633aa7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"821662a8-aa22-5155-b758-511f03bcb502","sourceKey":"bank:ACS101:LIF-050","parentItemId":null,"revision":1,"payload":{"prompt":"An extract from a life table gives: l_50 = 10,000; l_51 = 9,850; l_52 = 9,682; l_53 = 9,494; l_54 = 9,283; l_55 = 9,046. Calculate 1|3q50, the probability that a life aged 50 survives to age 51 and then dies before age 54, correct to 4 decimal places.","options":["0.0717","0.0804","0.0576","0.0567"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"1|3q50 = (l_51 - l_54)/l_50 = (9,850 - 9,283)/10,000 = 0.0567. Option C divides by l_51 and so ignores surviving the first year, Option A counts deaths from age 50, and Option B runs the 3-year death window one year too long."}},{"itemId":"cfaed796-e603-509a-8aaf-b7918a6e4f4e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fb01bfc1-6eac-5f8b-a054-6d5cd06596bb","sourceKey":"bank:ACS101:LIF-051","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. A Lagos firm employs 2,500 people, all aged exactly 20. Using the table, how many of them are expected to be alive at age 24 (to the nearest whole number)?","options":["2,486","2,475","20","2,480"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Expected survivors = 2,500 x 4p20 = 2,500 x 99,213/100,000 = 2480.32, about 2,480. Option A uses l_23 (3 years), Option B uses l_25 (5 years), and Option C is the expected number of deaths."}},{"itemId":"c24b5088-4238-5630-b9f1-6a56bb333898","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e205fa89-c615-5c59-b326-8f38ab67f60a","sourceKey":"bank:ACS101:LIF-052","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. A group of 4,000 lives are all aged exactly 22. Calculate the expected number of deaths among them before age 23, correct to 2 decimal places.","options":["7.61","8.08","8.65","8.11"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Expected deaths = 4,000 x q_22 = 4,000 x (99,630 - 99,428)/99,630 = 4,000 x 202/99,630 = 8.11. Option A uses q_21, Option B divides by l_20 instead of l_22, and Option C uses q_23."}},{"itemId":"1672da7c-77f5-51ed-ac86-37d30c45be95","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0f5b49dc-7958-51e9-b7df-554db8ed57f1","sourceKey":"bank:ACS101:LIF-053","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. Calculate 4p21, correct to 5 decimal places.","options":["0.00837","0.99392","0.98985","0.99163"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"4p21 = l_25 / l_21 = 98,985/99,820 = 0.99163. Option B uses l_24 (3 years only), Option C starts from the wrong age (l_20), and Option A is 4q21."}},{"itemId":"a76df1ce-49be-543d-b920-70ee4feb165d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"54b2ef45-b571-555e-80c9-69201f46542d","sourceKey":"bank:ACS101:LIF-054","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. Calculate 1|2q20, the probability that a life aged 20 survives one year and then dies within the next 2 years, correct to 5 decimal places.","options":["0.00572","0.00190","0.00392","0.00370"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"1|2q20 = (l_21 - l_23)/l_20 = (99,820 - 99,428)/100,000 = 392/100,000 = 0.00392. Option B counts only one year of deaths (1|q20), Option D is 2q20 with no deferment, and Option A is 3q20."}},{"itemId":"c4d6e95c-888e-5517-a8de-f078f356ea62","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"51ef732a-ecc5-5960-a4ff-ab99c60ca256","sourceKey":"bank:ACS101:LIF-055","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. How many of the lives alive at age 20 in this table die between exact ages 20 and 23?","options":["392","787","370","572"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Deaths between 20 and 23 = d_20 + d_21 + d_22 = l_20 - l_23 = 100,000 - 99,428 = 572. Option C stops at age 22, Option B runs to age 24, and Option A starts counting from age 21."}},{"itemId":"2b9b6a49-559d-5523-91a6-7d9d52984946","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cc59c736-16d1-58af-af71-ad42526e0469","sourceKey":"bank:ACS101:LIF-056","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_60 = 80,000; l_61 = 78,400; l_62 = 76,560; l_63 = 74,480; l_64 = 72,100; l_65 = 69,450. Calculate q_62, correct to 4 decimal places.","options":["0.0235","0.0272","0.0279","0.0260"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"q_62 = d_62 / l_62 = (76,560 - 74,480)/76,560 = 2,080/76,560 = 0.0272. Option C divides by l_63, Option A is q_61, and Option D divides by l_60, which gives 2|q60 instead."}},{"itemId":"251e1fe1-fa25-555a-987c-32fedbb9ad06","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9831ff4b-1bb1-50a1-a37b-aa4927ec1b71","sourceKey":"bank:ACS101:LIF-057","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_60 = 80,000; l_61 = 78,400; l_62 = 76,560; l_63 = 74,480; l_64 = 72,100; l_65 = 69,450. Calculate 5p60, correct to 4 decimal places.","options":["0.8858","0.1319","0.8681","0.9012"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"5p60 = l_65 / l_60 = 69,450/80,000 = 0.8681. Option D uses l_64 (4 years), Option B is 5q60, and Option A starts at age 61."}},{"itemId":"94ac57e6-4652-5dd3-a3ec-08a4df1930e1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8681a80b-7915-5492-9446-f7a07736d51e","sourceKey":"bank:ACS101:LIF-058","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_60 = 80,000; l_61 = 78,400; l_62 = 76,560; l_63 = 74,480; l_64 = 72,100; l_65 = 69,450. Calculate 2|q61, the probability that a life aged 61 dies between exact ages 63 and 64, correct to 5 decimal places.","options":["0.03036","0.03195","0.08036","0.02653"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"2|q61 = d_63 / l_61 = (74,480 - 72,100)/78,400 = 2,380/78,400 = 0.03036. Option B is q_63 (it ignores the 2-year deferment), Option D uses d_62, and Option C is 3q61 (death at any time before 64)."}},{"itemId":"23b6e179-c5c3-5cc0-a602-e1be06b6863c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"031fcf33-2cd3-5639-bcc2-a8803165e583","sourceKey":"bank:ACS101:LIF-059","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_60 = 80,000; l_61 = 78,400; l_62 = 76,560; l_63 = 74,480; l_64 = 72,100; l_65 = 69,450. Calculate the probability that a life now aged 60 dies between exact ages 63 and 65 (that is, 3|2q60), correct to 4 decimal places.","options":["0.1319","0.0629","0.0675","0.0331"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"3|2q60 = (l_63 - l_65)/l_60 = (74,480 - 69,450)/80,000 = 5,030/80,000 = 0.0629. Option C divides by l_63, Option A is 5q60, and Option D counts only one year of deaths."}},{"itemId":"cb58be2c-7951-5fec-96d9-8b58d6072168","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6ec98ad2-681f-537a-a12e-d6fbfe3afbbe","sourceKey":"bank:ACS101:LIF-060","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_60 = 80,000; l_61 = 78,400; l_62 = 76,560; l_63 = 74,480; l_64 = 72,100; l_65 = 69,450. A Nigerian pension scheme has 1,200 pensioners, all aged exactly 61. How many deaths are expected among them before age 62 (to the nearest whole number)?","options":["60","28","24","1,172"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Expected deaths = 1,200 x q_61 = 1,200 x (78,400 - 76,560)/78,400 = 1,200 x 1,840/78,400 = 28.16, about 28. Option C uses q_60, Option D is the expected number of survivors, and Option A uses 2q61."}},{"itemId":"ad26ea89-1332-500d-83cf-76b9c603240f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1e4eae2-8b78-5fa4-868d-3595dd099b1e","sourceKey":"bank:ACS101:LIF-061","parentItemId":null,"revision":1,"payload":{"prompt":"The last rows of a life table are: l_95 = 1,000; l_96 = 620; l_97 = 340; l_98 = 150; l_99 = 45; l_100 = 0 (no one survives beyond age 100). The curtate expectation of life is e_x = (l_(x+1) + l_(x+2) + ...)/l_x. Calculate e_95, correct to 2 decimal places.","options":["1.86","1.16","1.66","2.16"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"e_95 = (620 + 340 + 150 + 45 + 0)/1,000 = 1,155/1,000 = 1.16. Option D wrongly includes l_95 in the sum, Option C adds half a year, which gives the approximate complete expectation, and Option A divides by l_96 instead of l_95."}},{"itemId":"ba9c2df3-b445-5080-84af-99d456875edb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"898eb87c-bd4a-57e9-a17f-44b7dc41bdc6","sourceKey":"bank:ACS101:LIF-062","parentItemId":null,"revision":1,"payload":{"prompt":"The last rows of a life table are: l_95 = 1,000; l_96 = 620; l_97 = 340; l_98 = 150; l_99 = 45; l_100 = 0 (no one survives beyond age 100). Using e_x = (l_(x+1) + l_(x+2) + ...)/l_x, calculate the curtate expectation of life e_97, correct to 2 decimal places.","options":["0.44","1.57","0.57","0.20"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"e_97 = (150 + 45 + 0)/340 = 195/340 = 0.57. Option B wrongly includes l_97 in the numerator, Option A counts only the first future year (p_97), and Option D divides by l_95 instead of l_97."}},{"itemId":"238017c5-2bab-5ee3-9db6-b9dfd334d77c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1f96d46-4631-5811-8da0-22f12711e8a1","sourceKey":"bank:ACS101:LIF-063","parentItemId":null,"revision":1,"payload":{"prompt":"The last rows of a life table are: l_95 = 1,000; l_96 = 620; l_97 = 340; l_98 = 150; l_99 = 45; l_100 = 0 (no one survives beyond age 100). Calculate the probability that a life now aged 95 dies between exact ages 97 and 98, correct to 2 decimal places.","options":["0.19","0.85","0.56","0.28"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"2|q95 = d_97 / l_95 = (340 - 150)/1,000 = 0.19. Option C is q_97 (it ignores surviving from 95 to 97), Option B is 3q95, and Option D uses d_96."}},{"itemId":"5b67cd96-cda1-5a5a-b4e9-4d05fcb6c16c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cbc2215e-d08f-5e01-8502-fbf89e97fd93","sourceKey":"bank:ACS101:LIF-064","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_70 = 5,000, d_70 = 150, d_71 = 170, d_72 = 195 and d_73 = 220. Find l_73.","options":["4,680","4,265","4,485","5,515"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Since l_(x+1) = l_x - d_x, l_73 = 5,000 - 150 - 170 - 195 = 4,485. Option A is l_72 (one subtraction short), Option B is l_74 (it also subtracts d_73), and Option D adds the deaths instead of subtracting them."}},{"itemId":"2d1f4b2e-a063-51fb-89b2-cc3c9af3a77d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"58361414-b16d-5679-9e75-d415b89e810f","sourceKey":"bank:ACS101:LIF-065","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_70 = 5,000, d_70 = 150, d_71 = 170, d_72 = 195 and d_73 = 220. Calculate q_71, correct to 5 decimal places.","options":["0.96495","0.03505","0.03400","0.03632"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"First l_71 = 5,000 - 150 = 4,850, so q_71 = d_71 / l_71 = 170/4,850 = 0.03505. Option C divides by l_70 (the step of finding l_71 is missed), Option D divides by l_72, and Option A is p_71."}},{"itemId":"9e7c5680-4ab6-5813-a179-0095cb05a03e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f864fde3-898e-5301-949b-1759d66f2622","sourceKey":"bank:ACS101:LIF-066","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_70 = 5,000, d_70 = 150, d_71 = 170, d_72 = 195 and d_73 = 220. Calculate 3p70, correct to 4 decimal places.","options":["0.8970","0.1030","0.8530","0.9360"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"3p70 = l_73 / l_70 = (5,000 - 150 - 170 - 195)/5,000 = 4,485/5,000 = 0.8970. Option D covers only 2 years, Option C covers 4 years, and Option B is 3q70."}},{"itemId":"22dfa878-4aa2-5ce3-a0e5-1f291b01d76d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bc1e640b-0f38-5a9e-b76d-5d30f1ee4b67","sourceKey":"bank:ACS101:LIF-067","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_70 = 5,000, d_70 = 150, d_71 = 170, d_72 = 195 and d_73 = 220. Calculate 3|q70, the probability that a life aged 70 dies between exact ages 73 and 74, correct to 4 decimal places.","options":["0.0440","0.0491","0.1470","0.0390"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"3|q70 = d_73 / l_70 = 220/5,000 = 0.0440. Option B is q_73 = 220/4,485, which ignores surviving from 70 to 73, Option C is 4q70, and Option D uses d_72."}},{"itemId":"84a1bcfe-7b5a-5ad7-a2c6-a636f71039a9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"93705307-b990-5e5b-b369-d61a08becd34","sourceKey":"bank:ACS101:LIF-068","parentItemId":null,"revision":1,"payload":{"prompt":"A mortality table gives l_40 = 50,000, q_40 = 0.002, q_41 = 0.0025 and q_42 = 0.003. Calculate d_40, the expected number dying between ages 40 and 41.","options":["1,000","49,900","100","125"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"d_40 = l_40 x q_40 = 50,000 x 0.002 = 100. Option D uses q_41, Option B is l_41 (the survivors), and Option A misreads 0.002 as 2%."}},{"itemId":"734a2c3f-4b03-5b10-9f61-26b6b9bfd91c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b68eee8c-c9b3-5e22-a6ce-a14bd84190b2","sourceKey":"bank:ACS101:LIF-069","parentItemId":null,"revision":1,"payload":{"prompt":"A mortality table gives l_40 = 50,000, q_40 = 0.002, q_41 = 0.0025 and q_42 = 0.003. Calculate l_43, correct to 2 decimal places.","options":["49,625.92","49,625.00","49,477.05","49,775.25"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_43 = l_40 x p_40 x p_41 x p_42 = 50,000 x 0.998 x 0.9975 x 0.997 = 49,625.92. Option D is l_42 (one year short), Option B subtracts the three q's from 1 instead of multiplying the p's, and Option C applies one extra year of mortality."}},{"itemId":"ac542c9f-c96b-5e76-adb4-4f0d0ea6674c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"814d4f86-67bb-583f-9c19-64cd6996c8c6","sourceKey":"bank:ACS101:LIF-070","parentItemId":null,"revision":1,"payload":{"prompt":"For a life aged 40, q_40 = 0.002, q_41 = 0.0025 and q_42 = 0.003. Calculate 3p40, correct to 5 decimal places.","options":["0.00748","0.99250","0.99551","0.99252"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"3p40 = p_40 x p_41 x p_42 = 0.998 x 0.9975 x 0.997 = 0.99252. Option B subtracts the q's from 1 (a close but wrong shortcut), Option C covers only 2 years, and Option A is 3q40."}},{"itemId":"b89b6d41-3892-5762-9a76-70f562969762","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"187e666d-98dc-5fe3-9756-b4d6bbec1ad5","sourceKey":"bank:ACS101:LIF-071","parentItemId":null,"revision":1,"payload":{"prompt":"For a life aged 30, q_30 = 0.004 and q_31 = 0.0045. Calculate 2q30, the probability of dying within 2 years, correct to 6 decimal places.","options":["0.000018","0.008500","0.991518","0.008482"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"2q30 = 1 - p_30 x p_31 = 1 - 0.996 x 0.9955 = 0.008482. Option B just adds the q's, which counts some lives twice, Option A multiplies the q's (that would be dying in both years, which is impossible), and Option C is 2p30."}},{"itemId":"a0c560c3-228a-584f-ac76-4e45b9af507e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"50ba3172-4487-59f8-aaf5-5d6969065b75","sourceKey":"bank:ACS101:LIF-072","parentItemId":null,"revision":1,"payload":{"prompt":"A life table has radix l_0 = 1,000, with q_0 = 0.05, q_1 = 0.02 and q_2 = 0.01. Calculate l_3, correct to 2 decimal places.","options":["921.69","931.00","0.01","920.00"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_3 = l_0 x p_0 x p_1 x p_2 = 1,000 x 0.95 x 0.98 x 0.99 = 921.69. Option D subtracts the q's from 1 instead of multiplying the p's, Option B is l_2, and Option C multiplies the q's."}},{"itemId":"f6ac7149-c67f-5065-94d6-d4e5f5a65f7c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5e4f4b60-39c1-5a78-bf63-d251f5ddfaa8","sourceKey":"bank:ACS101:LIF-073","parentItemId":null,"revision":1,"payload":{"prompt":"A life table has radix l_0 = 1,000, with q_0 = 0.05 and q_1 = 0.02. Calculate d_1, the number dying between exact ages 1 and 2, correct to 1 decimal place.","options":["50.0","19.0","20.0","931.0"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"First l_1 = 1,000 x 0.95 = 950, so d_1 = l_1 x q_1 = 950 x 0.02 = 19.0. Option C applies q_1 to the radix instead of l_1, Option A is d_0, and Option D is l_2."}},{"itemId":"41b733ad-6918-5c64-ae46-df330f432a18","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ce4b7241-1b66-51d8-b300-fe1d6f8733dd","sourceKey":"bank:ACS101:LIF-074","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = 1 - x/120 for 0 <= x <= 120, where s(x) = l_x / l_0. What is the probability that a newborn survives to age 30?","options":["0.75","0.80","0.70","0.25"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The probability of surviving from birth to age 30 is s(30) = 1 - 30/120 = 0.75. Option D is the probability of dying before 30, while Options B and C come from using the wrong limiting age (150 and 100)."}},{"itemId":"a65622e4-a08d-5093-ad34-d1fadf0002be","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9408732b-471c-5fe2-a3fb-eca8ba3822c9","sourceKey":"bank:ACS101:LIF-075","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = 1 - x/120 for 0 <= x <= 120, where s(x) = l_x / l_0. Calculate 20p40, the probability that a life aged 40 survives to age 60, correct to 4 decimal places.","options":["0.2500","0.7500","0.5000","0.8333"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"20p40 = s(60)/s(40) = (60/120)/(80/120) = 60/80 = 0.7500. Option C is s(60) alone (survival from birth), Option D is s(20), and Option A is 20q40."}},{"itemId":"fc702070-0f75-5f71-a552-3db522ff5fbc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"22733c92-91b5-5564-be6e-540516d5f1da","sourceKey":"bank:ACS101:LIF-076","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = 1 - x/120 for 0 <= x <= 120, where s(x) = l_x / l_0. Calculate the probability that a newborn dies between ages 30 and 60, correct to 2 decimal places.","options":["0.25","0.50","0.75","0.33"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"P(newborn dies between 30 and 60) = s(30) - s(60) = 0.75 - 0.50 = 0.25. Option D is the probability for a life already aged 30 (it divides by s(30)), Option B is s(60), and Option C is s(30)."}},{"itemId":"e0daf3f5-9ed1-53be-a0e5-33d06b64cd5d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0376c6d8-a4e9-55d0-9239-680c721d4e72","sourceKey":"bank:ACS101:LIF-077","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = 1 - x/120 for 0 <= x <= 120, where s(x) = l_x / l_0. If the life table is built with radix l_0 = 100,000, find l_48.","options":["52,000","40,000","60,000","59,167"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_48 = l_0 x s(48) = 100,000 x (1 - 48/120) = 60,000. Option B is the number who have died by age 48, Option A uses 100 as the limiting age, and Option D is l_49."}},{"itemId":"7c9dde9a-e568-5ef5-9983-4168a1c83fb1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6d8310b8-e90a-5f56-96d9-d595f6c1177f","sourceKey":"bank:ACS101:LIF-078","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = (1 - x/100)^2 for 0 <= x <= 100, where s(x) = l_x / l_0. Calculate 20p30, the probability that a life aged 30 survives to age 50, correct to 4 decimal places.","options":["0.2500","0.4898","0.5102","0.7143"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"20p30 = s(50)/s(30) = (0.5)^2/(0.7)^2 = 0.25/0.49 = 0.5102. Option D forgets to square, Option A is s(50) (survival from birth), and Option B is 20q30."}},{"itemId":"34ddf76a-b8a1-5e84-81e9-f4a95c2841f0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e0fea033-e999-5833-86d5-110b9edf8a64","sourceKey":"bank:ACS101:LIF-079","parentItemId":null,"revision":1,"payload":{"prompt":"The survival function of a population is s(x) = (1 - x/100)^2 for 0 <= x <= 100, where s(x) = l_x / l_0. Calculate 20q50, the probability that a life aged 50 dies before age 70, correct to 2 decimal places.","options":["0.16","0.40","0.64","0.36"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"20q50 = 1 - s(70)/s(50) = 1 - 0.09/0.25 = 0.64. Option B forgets the square, Option D is 20p50, and Option A is the unconditional probability for a newborn (it does not divide by s(50))."}},{"itemId":"054bd006-be6e-582d-adcd-4d327b62e2c5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3b101c5d-eef5-549f-857f-e8d21c0ff24d","sourceKey":"bank:ACS101:LIF-081","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 6% per annum. Calculate the equivalent force of interest delta, correct to 5 decimal places.","options":["0.05827","0.06184","0.05841","0.05660"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Since 1 + i = e^delta, delta = ln(1.06) = 0.05827. Option D is d = 0.06/1.06, Option B treats 6% as the force and finds the effective rate e^0.06 - 1, and Option C is the nominal rate i^(12)."}},{"itemId":"a4df92e0-b641-5b0b-b435-ed9acea0cfb2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"85973a9f-7e36-5317-8eb5-d10615d8feaa","sourceKey":"bank:ACS101:LIF-082","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of discount is d = 5% per annum. Calculate the equivalent effective rate of interest i = d/(1-d), correct to 5 decimal places.","options":["0.95000","0.05263","0.05250","0.04762"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"i = d/(1-d) = 0.05/0.95 = 0.05263. Option D uses the formula for d in terms of i, Option A is v = 1 - d, and Option C is d(1+d), which is also wrong."}},{"itemId":"04cd1a25-cdec-5355-9970-fbf183291836","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6e0240cd-7f38-58a8-aeae-ed51f3d19a05","sourceKey":"bank:ACS101:LIF-083","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest of 10% per annum, calculate v^4, correct to 5 decimal places.","options":["0.62092","1.46410","0.60000","0.68301"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"v^4 = (1.1)^-4 = 1/1.4641 = 0.68301. Option B is the accumulation factor (1.1)^4, Option C uses simple discount 1 - 4i, and Option A is v^5."}},{"itemId":"69261c10-da54-5ac3-a9b8-b49c2689aebc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"583a1b8e-6337-5c4d-bdf4-46db4737b571","sourceKey":"bank:ACS101:LIF-084","parentItemId":null,"revision":1,"payload":{"prompt":"A nominal rate of interest i^(4) = 8% per annum is convertible quarterly. Calculate the equivalent effective annual rate i, correct to 5 decimal places.","options":["0.08243","0.08000","0.17166","0.01943"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"1 + i = (1 + i^(4)/4)^4 = (1.02)^4, so i = 0.08243. Option B treats the nominal rate as if it were effective, Option D finds a quarterly effective rate from 8% effective, and Option C compounds for 8 quarters."}},{"itemId":"8ef5c85f-3f0e-51a4-8f97-e44ac7f36303","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"92004f21-7c2b-5333-85cd-c68777620d96","sourceKey":"bank:ACS101:LIF-085","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 12% per annum. Calculate the equivalent nominal rate i^(12), convertible monthly, correct to 5 decimal places.","options":["0.11387","0.00949","0.12683","0.12000"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"i^(12) = 12[(1.12)^(1/12) - 1] = 0.11387. Option D assumes i^(12) equals i, Option B is the monthly effective rate before multiplying by 12, and Option C goes the wrong way and treats 12% as the nominal rate."}},{"itemId":"0d514bbf-4cf5-5c02-ba92-442b8f9ece55","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"98274f94-aa7d-5833-aa01-2b60101e1021","sourceKey":"bank:ACS101:LIF-086","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest is delta = 0.07 per annum. Calculate the discount factor v, correct to 5 decimal places.","options":["0.93000","1.07251","0.93239","0.93458"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Since v = e^(-delta), v = e^(-0.07) = 0.93239. Option D treats 7% as an effective rate (1/1.07), Option B is 1 + i = e^0.07, and Option A treats 0.07 as d."}},{"itemId":"7fdf19aa-5962-5bcd-bdd0-ef0ccbc9d2d0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d33ae3b8-c25e-5303-9132-eb4dcd1b79af","sourceKey":"bank:ACS101:LIF-087","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest of 5% per annum, calculate a_4|, the present value of an annuity-certain of 1 per annum for 4 years with payments at the END of each year, correct to 4 decimal places.","options":["4.3101","3.7232","3.2908","3.5460"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"a_4| = (1 - v^4)/i = (1 - (1.05)^-4)/0.05 = 3.5460. Option B is the annuity-due value a-double-dot_4| = (1.05)a_4|, Option A is s_4|, the accumulated value, and Option C discounts all four payments from time 4."}},{"itemId":"99676dc7-8c6e-59d9-98d5-6d1526d4e9ae","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f6e8d517-130b-543d-b433-c8c2fe3b1d8e","sourceKey":"bank:ACS101:LIF-088","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest of 10% per annum, calculate s_3|, the accumulated value at time 3 of payments of 1 at the END of each year for 3 years, correct to 3 decimal places.","options":["3.993","3.310","2.487","3.641"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"s_3| = ((1.1)^3 - 1)/0.1 = 0.331/0.1 = 3.310. Option D is s-double-dot_3| for an annuity-due, Option C is the present value a_3|, and Option A accumulates every payment for the full 3 years."}},{"itemId":"69e8ef3d-d668-5038-8f05-2cba5ff981d7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"31cd5fa9-d1a4-5d12-b986-5eef6a750ebb","sourceKey":"bank:ACS101:LIF-089","parentItemId":null,"revision":1,"payload":{"prompt":"At a certain rate of interest, a_9| = 7.1078 for payments made at the end of each year. Using a-double-dot_n| = 1 + a_(n-1)|, find a-double-dot_10|, the value of an annuity-due of 1 per annum for 10 years with payments at the BEGINNING of each year.","options":["7.8976","8.1078","7.1078","6.1078"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"An annuity-due of 10 payments is a payment of 1 now plus an annuity-immediate of the remaining 9, so a-double-dot_10| = 1 + 7.1078 = 8.1078. Option C forgets the payment at time 0, Option D subtracts it instead of adding it, and Option A wrongly scales a_9| up in proportion."}},{"itemId":"1c4664f6-82b7-5d2e-8226-92cd83060b20","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"541fc75a-f663-5e48-a9e4-0e3b3d3e1cc1","sourceKey":"bank:ACS101:LIF-090","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table l_45 = 92,000 and q_45 = 0.0035. Calculate l_46, correct to 1 decimal place.","options":["91,678.0","92,000.0","92,322.0","322.0"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_46 = l_45 x p_45 = 92,000 x (1 - 0.0035) = 91,678.0. Option D is d_45, the number dying, Option C adds the deaths instead of subtracting them, and Option B subtracts the probability itself rather than the number of deaths."}},{"itemId":"0f6af038-eccf-5209-b460-ababb8bb05b2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b21d255e-b091-5be6-9667-9fa82382f306","sourceKey":"bank:ACS101:LIF-091","parentItemId":null,"revision":1,"payload":{"prompt":"A life table gives: l_20 = 100,000; l_21 = 99,820; l_22 = 99,630; l_23 = 99,428; l_24 = 99,213; l_25 = 98,985. Calculate p_23, correct to 5 decimal places.","options":["0.99797","0.00216","0.99784","0.99213"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"p_23 = l_24 / l_23 = 99,213/99,428 = 0.99784. Option A is p_22, Option B is q_23, and Option D is 4p20, which divides by the radix."}},{"itemId":"909108ff-2cf4-5952-9f2b-800db45ab013","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3d4b903f-14b6-5c22-8bdc-deb59f46c7bd","sourceKey":"bank:ACS101:NAT-001","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes actuarial science?","options":["The discipline that evaluates risks and maintains the economic stability of insurance and financial organisations using mathematics, statistics and probability","The discipline that designs and sells insurance policies to customers through agents and brokers","The discipline that records past business transactions and prepares balance sheets and income statements from them","The discipline that studies stock market prices in order to recommend which shares an investor should buy"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial science is about evaluating risks and keeping insurance and financial organisations economically stable, using mathematics, statistics and probability to anticipate future events. Option C describes accounting, which deals with events that have already happened. Option D describes investment analysis, and option B describes insurance selling, neither of which is the core of actuarial science."}},{"itemId":"41112efc-8734-5e53-bd3b-98b6a4f7fa8b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dde5cd61-7549-59a2-ab26-28f5c5e478c3","sourceKey":"bank:ACS101:NAT-002","parentItemId":null,"revision":1,"payload":{"prompt":"The discipline that uses mathematical, statistical and probability principles to anticipate future events and take preventive measures, mainly in insurance and other financial organisations, is called","options":["Bookkeeping","Actuarial science","Marketing research","Auditing"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Using mathematics, statistics and probability to anticipate future events and take preventive measures is exactly what actuarial science does. Auditing (D) and bookkeeping (A) deal with records of past transactions, while marketing research (C) studies customer demand rather than risk."}},{"itemId":"1f4899d9-6ff2-5469-b71f-a63378798238","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0d6558ce-f1d4-5db5-a3e6-527ccfe335ac","sourceKey":"bank:ACS101:NAT-003","parentItemId":null,"revision":1,"payload":{"prompt":"The main goal of actuarial studies (a degree programme in actuarial science) is to","options":["prepare students mainly for careers as external auditors of public companies","teach students to forecast the weather for insurance companies","train students to become licensed insurance agents who sell policies on commission","build the knowledge for an actuary's job and prepare students for actuarial exams"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial studies aim to build the knowledge an actuary needs on the job and to help students pass the professional actuarial exams faster. Selling policies (C) and auditing (A) are different careers, and weather forecasting (B) is the work of meteorologists, even though actuaries may use weather data."}},{"itemId":"6c6a02e3-e08c-5262-907e-d53ffa6c249b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"09a30948-fb54-5e3f-b5e3-cd318dfedec6","sourceKey":"bank:ACS101:NAT-004","parentItemId":null,"revision":1,"payload":{"prompt":"Actuarial science is best described as being concerned mainly with","options":["the recording of financial events that have already taken place","the physical and engineering causes of accidents","the financial consequences of uncertain future events","the legal drafting of insurance contracts"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"At its core, actuarial science measures and manages the financial impact of future events whose occurrence, timing or size is uncertain. Recording past events (A) is accounting, studying physical causes of accidents (B) is engineering, and drafting contracts (D) is legal work."}},{"itemId":"0ee1cb07-500b-5efd-8f46-03333a158acb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5e35f122-c3fb-5525-a74f-ca8991fd79b6","sourceKey":"bank:ACS101:NAT-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the best definition of an actuary?","options":["A person who inspects damaged property to agree the amount of a claim","A person who prepares and audits a company's financial statements for past years","A person who sells insurance policies to the public on behalf of an insurer","A person who applies mathematical approaches to anticipate, measure and manage risk"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuary applies mathematical approaches to anticipate, measure and manage risk. Option B describes an accountant or auditor, option C an insurance agent, and option A a loss adjuster; all of these work with insurance or finance but none is the definition of an actuary."}},{"itemId":"da49d6a0-101b-537b-a96a-bf5bc1505059","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"953c5d31-8e8c-5a52-8088-1a61975810a0","sourceKey":"bank:ACS101:NAT-006","parentItemId":null,"revision":1,"payload":{"prompt":"A professional who analyses, manages and measures the financial implications of future risk, and who develops and validates financial models to guide decision making, is called","options":["a loss adjuster","an insurance broker","an actuary","an auditor"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Measuring the financial implications of future risk and building financial models to guide decisions is the work of an actuary. An auditor (D) checks past financial records, a broker (B) arranges insurance for clients, and a loss adjuster (A) assesses claims after a loss has happened."}},{"itemId":"09aab689-023c-5e33-9959-dadb2078b210","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9c8cba59-8ca6-571d-bb8b-729a2fe02385","sourceKey":"bank:ACS101:NAT-007","parentItemId":null,"revision":1,"payload":{"prompt":"Actuaries are often described as the analytical backbone of society's financial security programmes. Which of the following are examples of such programmes?","options":["Insurance, social security and pensions","Football clubs, cinemas and music festivals","Road construction, housing estates and railways","Primary schools, universities and libraries"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Financial security programmes are arrangements that protect people from the money consequences of undesirable events, such as insurance, social security and pensions, and actuaries supply the analysis behind them. The other options (C, D, B) are infrastructure, education and entertainment, which are not financial security programmes."}},{"itemId":"54790367-1c24-5608-b472-96332a841fa8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f13e1328-ca4e-5e15-9515-57702c1f3899","sourceKey":"bank:ACS101:NAT-008","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary is sometimes described as 'part super-hero, part fortune-teller, part trusted advisor'. The 'fortune-teller' part refers to the actuary's skill in","options":["guaranteeing that no undesirable event will ever happen to a client","evaluating the likelihood of future events using numbers and data rather than guesswork","keeping accurate records of every transaction a company has made","predicting a client's personal future through intuition and dreams"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries are experts in evaluating the likelihood of future events using numbers, not crystal balls, which is what the playful 'fortune-teller' label points to. Option D is real fortune-telling, which actuaries do not do. No one can guarantee events never happen (A), and record-keeping (C) looks backward rather than forward."}},{"itemId":"16a315a3-c01a-5448-8330-338a08b0ff61","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"66d3f218-cd71-5ae7-b922-2e21a3e8e68f","sourceKey":"bank:ACS101:NAT-009","parentItemId":null,"revision":1,"payload":{"prompt":"Actuaries are described as experts in three broad things. Which of the following is NOT one of them?","options":["Designing creative ways to reduce the likelihood of undesirable events","Evaluating the likelihood of future events","Guaranteeing that undesirable events will never occur","Decreasing the impact of undesirable events that do occur"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries evaluate how likely future events are, design ways to reduce the chance of undesirable events, and reduce the impact of those that still happen. They can never guarantee that bad events will not occur, because the future is uncertain. Options B, A and D are the three genuine areas of expertise."}},{"itemId":"d0b10590-b3c3-5923-ae88-2dd11fd6459e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"52b801e3-f374-57f6-b812-94137cec3c7a","sourceKey":"bank:ACS101:NAT-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best describes how actuaries work, as problem solvers and strategic thinkers?","options":["They use engineering skills to inspect and repair buildings and vehicles damaged by fire and flood","They use mathematics to measure the probability and risk of future events and predict their financial impact on a business and its clients","They use selling skills to persuade customers to buy as many insurance policies as possible","They use legal skills to defend insurance companies when customers dispute claims in court"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries are problem solvers who use mathematics to measure the probability and risk of future events and then predict the financial impact of those events on a business and its clients. Options D, C and A describe lawyers, salespeople and engineers, whose work may touch insurance but is not actuarial."}},{"itemId":"e12ebfbb-ddc7-5618-87aa-80f8a866a613","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bb52e410-158e-5145-8a37-e63075e88f83","sourceKey":"bank:ACS101:NAT-011","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary working with a Lagos motor insurer recommends a road-safety campaign encouraging drivers to wear seat belts. This is an example of an actuary","options":["decreasing the impact of undesirable events after they occur","participating in corporate planning such as mergers and acquisitions","maintaining databases for the analysis of pricing issues","designing ways to reduce the likelihood of undesirable events"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Promoting safety, such as seat-belt use, is a way of reducing the chance or seriousness of accidents before they happen, so it falls under designing ways to reduce the likelihood of undesirable events. Option A refers to benefits paid after the event, such as death or indemnity benefits. Options B and C are other actuarial activities that have nothing to do with a safety campaign."}},{"itemId":"9823f058-e8df-59d9-b4f1-4e7185b23820","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1f8afa3f-7ef1-51f1-a4f3-dc27c903dd82","sourceKey":"bank:ACS101:NAT-012","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund pays a monthly retirement benefit to a retired civil servant in Ibadan, and an insurer pays a death benefit to the family of a policyholder who died. Both payments are examples of actuaries helping to","options":["evaluate the likelihood of future events","decrease the impact of undesirable events that do occur","reduce the likelihood that undesirable events will occur","participate in mergers and acquisitions"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Death benefits, retirement benefits and indemnity benefits do not stop the event from happening; they soften its financial impact once it has happened. Option C would be something like a safety campaign, option A is the measuring step that comes before, and option D is corporate planning."}},{"itemId":"a6f87f99-9607-5af8-9351-7037a4407fd2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2b481dea-5895-549f-b22c-1465b238a9b3","sourceKey":"bank:ACS101:NAT-013","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary estimates how many years, on average, a newly retired pensioner is expected to keep receiving pension payments, and forecasts the potential cost of a major flood. Both tasks belong to which actuarial activity?","options":["Evaluating the likelihood of future events","Maintaining accounting records of past claims","Decreasing the impact of undesirable events that do occur","Promoting safety to prevent undesirable events"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Calculating the expected lifetime of a retiree and forecasting the impact of catastrophes are both ways of evaluating the likelihood and effect of future events. Option C refers to paying benefits after an event, option D to safety measures such as seat belts, and option B is backward-looking record-keeping."}},{"itemId":"7acf5b2a-fe85-5172-97d7-0933605dd37e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"05347e06-b5fe-54c2-825a-1e186bb8dfcd","sourceKey":"bank:ACS101:NAT-014","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank asks its actuaries to help assess a proposed merger with a smaller bank and to evaluate its investment programmes. This is an example of actuaries","options":["calculating rates for new insurance products","decreasing the impact of undesirable events through death benefits","participating in corporate planning","promoting safety to reduce accidents"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Mergers and acquisitions and the evaluation of investment programmes are listed under actuaries participating in corporate planning. Option A is pricing work for insurers, option B is about benefits paid after an event, and option D is about preventing accidents."}},{"itemId":"657475f3-a04d-5551-9998-96fb5a538ea5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9e30fd4c-d72c-5307-bd86-0cc51ac3584d","sourceKey":"bank:ACS101:NAT-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the ways in which actuaries typically help insurance companies?","options":["Forecasting and interpreting underwriting results","Calculating rates for new insurance products","Representing the insurer as its lawyer when a claim dispute goes to court","Maintaining databases suited to the analysis of pricing issues"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries help insurers by calculating rates for new products, forecasting and interpreting underwriting results, and keeping databases that support pricing analysis. Representing the insurer in court is the job of a lawyer, not an actuary. Options B, A and D are all genuine actuarial tasks."}},{"itemId":"47d3c549-1e3e-50ea-8da1-2753e7015a57","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"329e9d69-74df-526a-abce-09d2171a9a39","sourceKey":"bank:ACS101:NAT-016","parentItemId":null,"revision":1,"payload":{"prompt":"The work of an actuary is often compared to 'driving a car by looking in the rear-view mirror'. This comparison means that an actuary","options":["works only on motor insurance policies","typically uses data from the past to predict the future","ignores past data and relies only on intuition about the future","is mainly interested in recording what has already happened"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"The rear-view mirror shows where you have been, and an actuary typically uses past data to predict what will happen next, which is why they must also judge how the future may differ from the past. Option C is the opposite of the actuarial approach. Option D describes accounting, and option A takes the car image too literally."}},{"itemId":"9856e64c-5ac3-59ef-b2ac-2c62ad5540b8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"faeb6bf5-1ba5-582c-9fd8-5a401cae35d8","sourceKey":"bank:ACS101:NAT-017","parentItemId":null,"revision":1,"payload":{"prompt":"After a sharp rise in petrol prices in Nigeria, an actuary pricing motor insurance does not simply assume that next year's claims will match last year's. Which principle of actuarial work does this illustrate?","options":["Motor insurance prices are fixed by law and cannot change","Past data is always a perfect guide to the future","The actuary needs to quantify how the future will be different from the past","Actuaries should ignore economic changes when setting prices"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Because actuaries rely on past data, they must also measure how changed conditions, such as a large rise in fuel prices, will make the future different from the past. Option B is wrong because past data is never a perfect guide. Option D is the very mistake the actuary is avoiding, and option A is not a principle of actuarial work."}},{"itemId":"d3b659b4-ab0a-5660-9b24-0a25cbe95d14","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fbcc5b25-74ee-596f-b1c5-e3af38fe2894","sourceKey":"bank:ACS101:NAT-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is described as one of the main challenges an actuary faces?","options":["Having insurance customers who never make claims","Having too many qualified actuaries in every country","Being unable to use computers in any part of actuarial work","Having no past data, or past data made irrelevant by policy changes"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Since actuaries use past data to predict the future, a major challenge arises when there is no past data or when it is no longer relevant because of policy or other changes. Option B is not true, especially in Nigeria where actuaries are scarce. Computers are central to actuarial work (C), and customers who never claim (A) are not a challenge to measurement."}},{"itemId":"a34ca10a-6042-579a-af32-4cbe51a0380f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"97f50d0c-bddf-5e7a-b49f-1a565adc0343","sourceKey":"bank:ACS101:NAT-019","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary wants to predict how many people in Lagos will be involved in a car accident this November. What is the first thing the actuary would typically do?","options":["Set the insurance premium first and then collect accident data","Look at the percentage of people involved in accidents in previous years","Ask each driver to guess whether they will have an accident","Assume that no accidents will happen because roads have improved"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"The actuary starts with past experience: the percentage of people involved in accidents in previous years. From that data a trend is identified, used to predict this year's percentage, and then used to set how much each person should pay. Option A reverses the steps, while options C and D replace data with guesses."}},{"itemId":"631c07de-6f72-5750-b6ac-b1b9522583b0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"590b583e-13e4-5066-935e-34c9370ee0bd","sourceKey":"bank:ACS101:NAT-020","parentItemId":null,"revision":1,"payload":{"prompt":"In predicting car accidents, an actuary identifies a trend in past accident percentages. What is this trend then used for?","options":["To decide which drivers should be arrested by the police","To predict this year's accident percentage and set how much each insured person should pay","To record last year's accidents in the company's accounts","To prove that past accident data is irrelevant to the future"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"The trend is projected forward to predict this year's accident percentage, and that prediction is used to work out how much each insured person should pay so that premiums cover the cost of crashes. Option A is a police matter, option D contradicts the use of the data, and option C is accounting rather than prediction."}},{"itemId":"66697092-b109-5421-b264-a7bed510bcd4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"51054562-cc21-5b51-8e68-64477cdeb0d1","sourceKey":"bank:ACS101:NAT-021","parentItemId":null,"revision":1,"payload":{"prompt":"The percentage of insured drivers in a city involved in an accident was 2.0% three years ago, 2.2% two years ago and 2.4% last year. If an actuary assumes this steady trend continues, what accident percentage would be predicted for this year?","options":["2.8%","2.6%","2.2%","2.4%"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"The percentage has risen by 0.2 percentage points each year (2.0, 2.2, 2.4), so continuing the trend gives 2.4 + 0.2 = 2.6%. Option D simply repeats last year's figure and ignores the trend, option C is the three-year average, and option A adds the increase twice."}},{"itemId":"9fb337ed-dff7-54cf-8500-e2688a4df5a8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"93216850-b88d-5259-815d-35ca95498982","sourceKey":"bank:ACS101:NAT-022","parentItemId":null,"revision":1,"payload":{"prompt":"When designing products, actuaries consider the value of the customer. Which statement best captures this?","options":["They design products and solutions that meet customers' needs both now and in the future","They design products that meet only the insurer's needs today","They design products that guarantee customers will never suffer a loss","They avoid any contact with customer needs and focus only on formulas"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries understand the importance and value of a customer and the need to design products and solutions that meet customer needs both now and in the future. Option B ignores the customer, option D wrongly pictures actuaries as cut off from business needs, and option C promises something no product can deliver."}},{"itemId":"16e37af4-4816-5e70-bbdf-0db51c817115","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"708fe680-ee87-59bc-8bda-45aac64110e8","sourceKey":"bank:ACS101:NAT-023","parentItemId":null,"revision":1,"payload":{"prompt":"In modern digital businesses, actuaries add value mainly by providing expertise in","options":["physical security guarding of data centres","predictive modelling and optimisation for smarter risk decisions","hardware repair of company computers","graphic design for company websites and mobile apps"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"In digital ecosystems actuaries contribute expertise in predictive modelling and optimisation, helping businesses in all industries make quicker and smarter risk decisions. They also provide quality assurance through expertise in data quality and analytics. Options D, A and C are design, security and technical support roles."}},{"itemId":"7fe97768-4dae-5e86-9282-560dbccc8c39","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"da851d64-e95f-5962-99ac-04b9217dc5cd","sourceKey":"bank:ACS101:NAT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Outside traditional actuarial roles, actuaries can add value to other parts of a business. Which of the following is NOT one of these ways?","options":["Supporting marketing teams by modelling demand when a new product is launched","Running the company's staff canteen","Identifying and managing risk","Supporting accounting teams with models and assumptions for budgeting and forecasting"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries can support marketing by modelling demand for new products, support accounting with models and assumptions for budgeting and forecasting, help with product development, and identify and manage risk. Running a canteen uses none of these modelling skills. Options A, D and C are genuine areas where actuaries add value."}},{"itemId":"4821a860-f591-5580-b82a-da658dec4913","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"79ec8223-8e16-536c-9534-0912f11c9ce2","sourceKey":"bank:ACS101:NAT-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts the business focus of an actuary with that of an accountant?","options":["An actuary focuses on events that have already happened, while an accountant predicts future events","An actuary focuses only on assets, while an accountant focuses only on liabilities","Both focus only on the financial impact of events that have already happened","An actuary predicts the financial impact of possible future events, while an accountant focuses on events that have already happened"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"The main difference is the direction in time: actuaries look forward at events that may or may not happen, while accountants report on the financial effect of events that have already taken place. Option A reverses the two roles, option C ignores the forward-looking nature of actuarial work, and option B misstates how each treats assets and liabilities."}},{"itemId":"406d4b0a-f886-5268-8172-c3e8b9659384","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"149e3de1-3611-5e6e-a945-4dc81ca502d9","sourceKey":"bank:ACS101:NAT-026","parentItemId":null,"revision":1,"payload":{"prompt":"With respect to assets and liabilities, which of the following is true?","options":["Actuaries deal only with assets, while CFA charterholders deal only with liabilities","Accountants are the only professionals trained to understand complicated liabilities","Actuaries cover both assets and liabilities and are specially trained in liabilities, while CFA charterholders focus on assets","Neither actuaries nor accountants deal with liabilities in their work"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries work on both sides of the balance sheet and are especially trained to understand liabilities, such as future insurance claims and pension promises, which are complicated. CFA charterholders are geared toward assets and investments. Option A reverses this, option B overlooks the actuary's special training, and option D is false because accountants report on both."}},{"itemId":"5a48fac1-eabc-5a82-a5de-c1a16cae5e63","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2e75e57b-156f-566b-9e61-af258a0ec75c","sourceKey":"bank:ACS101:NAT-027","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company wants to know how much it should set aside today to pay pension promises that will fall due to its workers over the next 30 years, depending on how long they live. Which professional is best suited to this task?","options":["A CFA charterholder selecting shares","An actuary","An external auditor","A tax consultant"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Estimating the present cost of uncertain future obligations, such as pensions that depend on how long people live, is classic actuarial work because it involves future events and complicated liabilities. An auditor (C) checks records of past events, a CFA charterholder (A) focuses on choosing investments, and a tax consultant (D) advises on tax."}},{"itemId":"cfca6879-e245-5088-8338-bfa5bcec8bd6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3d18c3bc-b809-551f-bebb-9891a4be3f01","sourceKey":"bank:ACS101:NAT-028","parentItemId":null,"revision":1,"payload":{"prompt":"How does an accountant's way of working differ from an actuary's?","options":["There is no real difference, because the two titles mean exactly the same thing","An accountant recommends investments, while an actuary prepares income statements","An accountant reports on known figures, while an actuary uses data to estimate the probability and impact of future events","An accountant calculates probabilities of future events, while an actuary audits balance sheets"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Accountants work with known figures and create or audit financial reports such as balance sheets and income statements, while actuaries use thousands of pieces of data to calculate how likely a future event is, what its impact would be and what to do about it. Option D swaps the roles, option B describes a CFA's investment work, and option A ignores clear differences."}},{"itemId":"97a8814b-4a05-5747-9c8b-00eba587b0c3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a8735e72-082b-50d2-93f9-51a74253662d","sourceKey":"bank:ACS101:NAT-029","parentItemId":null,"revision":1,"payload":{"prompt":"Actuarial science draws mainly on which group of disciplines?","options":["Chemistry, botany, geology and zoology","Law, sociology, history and literature","Architecture, fine art, music and theatre","Probability, statistics, economics, finance and computer science"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial science combines mathematics with probability and statistics to measure uncertainty, economics and finance to value money over time, and computer science to handle data and build models. The other groups (B, A, C) are useful fields in their own right but are not the foundation of actuarial work."}},{"itemId":"50c3780c-5929-5530-bc21-093fd8a0f207","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f5b788f8-febd-5647-ad3b-08f3773248fc","sourceKey":"bank:ACS101:NAT-030","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary estimates the proportion of 40-year-old policyholders who die within a year by analysing records of past deaths among thousands of similar policyholders. Which discipline is the actuary mainly drawing on?","options":["Law","Statistics","Accounting","Marketing"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Estimating a rate such as the chance of dying within a year from past observations is a statistical task: drawing conclusions about a population from data. Accounting (C) records financial transactions, marketing (D) studies customer demand, and law (A) deals with legal rights and duties."}},{"itemId":"178bfb2e-5de4-517b-8e86-3ee740fc26f9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fd848393-3e9c-5dc2-8ed7-8b894ce9be53","sourceKey":"bank:ACS101:NAT-031","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary writes a computer program that processes the records of two million policyholders and runs thousands of simulated outcomes. Which discipline is the actuary mainly drawing on here?","options":["Accounting","Economics","Sociology","Computer science"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Handling millions of records and running thousands of simulations requires programming and computing, so the actuary is drawing on computer science. Economics (B) and sociology (C) study how economies and societies behave, and accounting (A) records transactions; none of them is the main tool for building such a program."}},{"itemId":"f3272262-d75c-5297-ac1c-36bb64009ca5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bbd157e5-d9a2-5ed9-8fa4-36eda5e41c80","sourceKey":"bank:ACS101:NAT-032","parentItemId":null,"revision":1,"payload":{"prompt":"When an actuary considers how inflation, interest rates and unemployment in Nigeria might affect future claims and investment returns, the actuary is mainly drawing on","options":["economics","botany","linguistics","civil engineering"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Inflation, interest rates and unemployment are economic variables, so studying their effect on claims and investment returns draws on economics. Botany (B), civil engineering (D) and linguistics (C) do not study these variables."}},{"itemId":"8848db39-e30b-5633-a661-da257d82341a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"72dc17a8-06ed-5561-b81a-3aa1add53a6a","sourceKey":"bank:ACS101:NAT-033","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial work, risk is defined as the","options":["possibility of failing to meet objectives","profit an insurer makes in a year","certainty that a loss will occur","amount of premium paid for an insurance policy"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Risk is the possibility of failing to meet objectives, and it can only be defined in context. Option C is wrong because risk is about possibility, not certainty. Options D and B are financial quantities, not risk itself."}},{"itemId":"77730e15-75e0-5afb-8c98-60770bc06d57","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bd625caa-c80d-5b0b-8255-1dcd3baff146","sourceKey":"bank:ACS101:NAT-034","parentItemId":null,"revision":1,"payload":{"prompt":"A heavy rainfall that threatens the crops of a farmer in Benue State is not a concern to a software company in Lagos. This illustrates that risk","options":["can always be removed completely","exists only for insurance companies and banks","is the same for every person and every organisation","can only be defined in context of the entity involved"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Risk depends on the situation and the entity involved: the rainfall is a risk to the farmer's objectives but not to the software company. Option C contradicts this, option B is too narrow because individuals and firms of all kinds face risk, and option A is false since risk can be managed but rarely eliminated."}},{"itemId":"c2746dac-8c95-526e-bd63-ffc6e4fa7127","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"512abd3f-ccb9-5339-a276-4f6e9d0223f7","sourceKey":"bank:ACS101:NAT-035","parentItemId":null,"revision":1,"payload":{"prompt":"A situation that involves imperfect or unknown information, and which applies to predictions of future events, is called","options":["indemnity","liquidity","solvency","uncertainty"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Uncertainty is a situation involving imperfect or unknown information, such as not knowing exactly what will happen in the future. Solvency (C) is the ability to pay long-term debts, liquidity (B) is how easily assets turn into cash, and indemnity (A) is compensation for a loss."}},{"itemId":"333d2162-22e0-51e4-90a3-41bcfac8ed11","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2be801ba-a1cc-5af2-88d3-16ce077210c1","sourceKey":"bank:ACS101:NAT-036","parentItemId":null,"revision":1,"payload":{"prompt":"Uncertainty is sometimes described as 'unmeasurable risk'. In this sense, how does uncertainty differ from (measurable) risk?","options":["Under uncertainty the outcome is known in advance, while under risk it is not","Uncertainty affects only individuals, while risk affects only companies","Under uncertainty the chances of outcomes cannot be measured, while under risk they can","Uncertainty always produces a gain, while risk always produces a loss"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Describing uncertainty as unmeasurable risk means that its chances cannot be reliably measured, whereas risk in the measurable sense can be quantified with probabilities. Option A is wrong because under uncertainty the outcome is not known. Options B and D invent distinctions that do not exist."}},{"itemId":"388523e3-9106-50e1-a52b-680fd2b3ed5c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f610201d-1b47-5f91-b792-56554d466fb4","sourceKey":"bank:ACS101:NAT-037","parentItemId":null,"revision":1,"payload":{"prompt":"An actuarial risk is a phenomenon subject to uncertainty with respect to which variables?","options":["Price, quantity and quality","Occurrence, timing and severity","Age, sex and occupation only","Ownership, location and colour"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuarial risk is uncertain in one or more of three ways: whether the event happens (occurrence), when it happens (timing) and how big its financial effect is (severity). Options D and A are not the defining variables, and option C lists risk characteristics that may help classify risks but do not define an actuarial risk."}},{"itemId":"5898412f-d430-5ff5-bc7b-eb2e573df52e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b552c780-c5a5-5fc7-8e3c-24a238f29eeb","sourceKey":"bank:ACS101:NAT-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the variables whose uncertainty makes a phenomenon an actuarial risk?","options":["Severity","Ownership","Occurrence","Timing"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuarial risk is defined by uncertainty in occurrence (whether it happens), timing (when) and severity (how large). Ownership of property is not one of these variables. Options C, D and A are the three defining variables."}},{"itemId":"b0db5781-bdf9-52ab-bbad-e0650a4e5665","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5df4543d-4986-5b22-89f2-7bd4f4abbb7e","sourceKey":"bank:ACS101:NAT-039","parentItemId":null,"revision":1,"payload":{"prompt":"Mr Okonkwo buys a whole life policy that pays N2,000,000 whenever he dies. Since everyone dies eventually, the main uncertainty the actuary faces on this policy is about","options":["whether the event will ever occur","who owns the policy","the severity of the payment, which is unknown","the timing of the event"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Death is certain and the payment is fixed at N2,000,000, so what remains uncertain is when the death will occur, which matters because money paid later is worth less today. Option A is wrong because death will certainly happen, option C is wrong because the amount is fixed, and option B is not an actuarial risk variable."}},{"itemId":"73b66a67-3f57-5af8-8a4f-719c9a7ac4db","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ee0e3380-fcb9-5d4a-9a69-605725428a17","sourceKey":"bank:ACS101:NAT-040","parentItemId":null,"revision":1,"payload":{"prompt":"A motor insurer in Abuja does not know whether an insured car will crash this year, nor how much the repairs would cost if it did. Which actuarial risk variables are uncertain here?","options":["Ownership and colour","None, because motor accidents are certain","Timing only","Occurrence and severity"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Not knowing whether a crash will happen is uncertainty about occurrence, and not knowing the repair cost is uncertainty about severity. Option C ignores both of these, option A lists things that are not risk variables, and option B is wrong because accidents are not certain."}},{"itemId":"c9beb985-58f3-5c15-8b57-fccfbd750870","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b4b9a9b0-f116-519c-bd24-b6978907fbda","sourceKey":"bank:ACS101:NAT-041","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial science, an event that may or may not occur is called a","options":["contingency","dividend","certainty","liability"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A contingency is an event that may or may not occur, which is why the mathematics of such events is called life contingencies in life insurance. A certainty (C) is the opposite, a dividend (B) is a share of profits, and a liability (D) is an obligation owed."}},{"itemId":"6c56cd4d-5805-5c41-a9ef-17bd23ece5bd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"92f07d76-3e0e-5db9-bfe0-f3e31e4fd004","sourceKey":"bank:ACS101:NAT-042","parentItemId":null,"revision":1,"payload":{"prompt":"A policy promises to pay N1,000,000 to Mrs Adebayo's family only if she dies within the next 10 years. Such a payment is described as","options":["a simple interest payment","a dividend paid out of the insurer's profits","contingent, because it depends on an uncertain event","certain, because the amount of N1,000,000 is fixed"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"An economic benefit that depends on an uncertain event, here death within 10 years, is contingent. Option D confuses a fixed amount with a certain payment; the amount is known but whether it is paid is not. Options A and B describe interest and profit distributions, which are different things."}},{"itemId":"47cbafcf-83c3-58fd-9f73-38f7fc83498e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d7432709-fa06-5d66-8c60-a2cff09796e4","sourceKey":"bank:ACS101:NAT-043","parentItemId":null,"revision":1,"payload":{"prompt":"An old electrical installation in a warehouse in Kano makes a fire more likely and could make any fire spread faster. In risk language, the faulty wiring is","options":["a peril","a reserve","a hazard","a premium"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"A hazard is a condition that increases the probability or expected size of a loss, which is what faulty wiring does. The fire itself would be the peril (A), the cause of loss that is insured against. A premium (D) is the price of cover and a reserve (B) is money set aside for claims."}},{"itemId":"fc3a8333-9bce-537b-938c-f34c90d99338","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"073637b4-07d2-5fc5-a122-8259f0778cd9","sourceKey":"bank:ACS101:NAT-044","parentItemId":null,"revision":1,"payload":{"prompt":"The probable cause, such as fire, flood or theft, that exposes a person or property to loss and against which insurance cover is bought is called a","options":["hazard","benefit","risk factor","peril"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"A peril is the actual cause of loss, such as fire, flood or theft, that an insurance policy covers. A hazard (A) is a condition that makes the peril more likely or more costly, and a risk factor (C) is an attribute that increases the likelihood of loss. A benefit (B) is the payment received."}},{"itemId":"3f0b1d7e-c9af-546b-a7db-e0d509b815b2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4c46b109-f7c1-5bf4-853a-840c42feda09","sourceKey":"bank:ACS101:NAT-045","parentItemId":null,"revision":1,"payload":{"prompt":"The incidence of death in a population, often measured by the probability that a randomly selected person dies within a given period, is called","options":["morbidity","mortality","fertility","longevity risk"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Mortality is the incidence of death in a population. Morbidity (A) is the rate of disease or serious illness, fertility (C) refers to births, and longevity risk (D) is the risk that people live longer than expected."}},{"itemId":"d9156532-8a91-5cf6-8146-eae5971ebe9c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9fc7da4c-318d-5fe9-87c0-e70d8d55b688","sourceKey":"bank:ACS101:NAT-046","parentItemId":null,"revision":1,"payload":{"prompt":"The rate of disease in a population, often measured by the probability that a randomly selected person becomes seriously ill within a given period, is called","options":["morbidity","mortality","inflation","solvency"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Morbidity is the rate of disease in a population and is central to health insurance work. Mortality (B) is about deaths rather than illness, solvency (D) is the ability to pay long-term debts, and inflation (C) is a rise in the general price level."}},{"itemId":"804402ab-d753-57a5-ae51-b4d2b6b4388c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4190ccf9-9e87-5870-9200-44560481c726","sourceKey":"bank:ACS101:NAT-047","parentItemId":null,"revision":1,"payload":{"prompt":"Probability measures the likelihood that an event occurs. Which of the following can NOT be the probability of an event?","options":["1.2","0","1","0.35"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A probability always lies between zero and one inclusive, so 1.2 is impossible. A probability of 0 (B) means the event cannot happen, 1 (C) means it is certain, and 0.35 (D) is an ordinary in-between value."}},{"itemId":"be6b7d0d-b014-5596-99c2-3f77002144aa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1bb615c2-6897-5232-ac59-02da02e93fac","sourceKey":"bank:ACS101:NAT-048","parentItemId":null,"revision":1,"payload":{"prompt":"The probability-weighted average of the values taken by a random variable is called its","options":["range","median","expected value","mode"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"The expected value multiplies each possible value by its probability and adds the results, giving a probability-weighted average. The mode (D) is the most likely value, the range (A) is the spread between the largest and smallest values, and the median (B) is the middle value."}},{"itemId":"a215808c-b92a-5942-9a64-72fd382edccf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d3f1d45a-336d-5c7f-a371-cd28de7dcc8d","sourceKey":"bank:ACS101:NAT-049","parentItemId":null,"revision":1,"payload":{"prompt":"A shop in Onitsha has a 0.4% chance of a fire in a year. If a fire occurs, the loss will be N5,000,000; otherwise the loss is nil. What is the expected loss for the year?","options":["N20,000","N200,000","N2,000","N5,000,000"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Expected loss = probability x loss = 0.004 x 5,000,000 = N20,000. Option B comes from using 0.04 instead of 0.004 (misreading the percentage), option C from using 0.0004, and option D ignores the probability altogether."}},{"itemId":"7ce22759-b5d5-580a-aedf-bf4d1ca25815","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"754ec2cb-4f10-584d-9e8c-387c10a8074a","sourceKey":"bank:ACS101:NAT-050","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer covers 10,000 similar commercial buses. Past experience shows that 3% of buses have an accident each year and the average claim per accident is N400,000. Ignoring expenses and profit, what is the expected claim cost per bus for the year?","options":["N120,000,000","N12,000","N400,000","N1,200"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Expected total claims = 10,000 x 0.03 x 400,000 = N120,000,000, so the cost per bus is 120,000,000 / 10,000 = N12,000 (equivalently 0.03 x 400,000). Option A is the total for all buses rather than per bus, option C ignores the 3% probability, and option D uses 0.3% instead of 3%."}},{"itemId":"d4d5c661-8456-5d82-b184-80039cab116f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a7f3f571-7e0e-5887-9c51-cae5d7a04456","sourceKey":"bank:ACS101:NAT-051","parentItemId":null,"revision":1,"payload":{"prompt":"The law of large numbers, as used in actuarial science, states in simple terms that","options":["as the number of independent, similar trials increases, the observed proportion of an event becomes more stable","the larger a single loss is, the more likely it is to occur","large insurance companies always make larger profits than small ones","an event that has happened many times in the past is unlikely to happen again"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"The law of large numbers says that when many independent, similar experiments are observed under the same conditions, the proportion of times an event occurs settles down and becomes predictable. That is why insurers can predict claims for a large group even though no one knows what will happen to one person. Options C, B and D are misunderstandings of the idea."}},{"itemId":"d80f1915-cfbf-55f4-b607-1e334595b7e2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"46600aa7-5cb4-5768-947a-201a0f2ed9b9","sourceKey":"bank:ACS101:NAT-052","parentItemId":null,"revision":1,"payload":{"prompt":"Insurer A covers 50 okada riders and Insurer B covers 50,000 okada riders with similar characteristics. Why can Insurer B predict its total claims more reliably?","options":["Because each of Insurer B's riders is guaranteed not to have an accident","Because small groups always produce more claims per person than large groups","Because Insurer B charges a higher premium per rider","Because, by the law of large numbers, larger similar groups give more certain predictions"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Pooling relies on the law of large numbers: the larger and more homogeneous the group, the more stable the proportion of claims and so the more certain the predictions. Option A is false because no individual is guaranteed to be safe. Options C and B do not explain predictability."}},{"itemId":"7d1202bb-9072-56b3-a6d5-1f8ec8f065c2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"49dc362a-a8e4-5580-ac0f-a0b47b61804c","sourceKey":"bank:ACS101:NAT-053","parentItemId":null,"revision":1,"payload":{"prompt":"For pooling of risks to give reliable predictions, which of the following is NOT desirable?","options":["The policies should have similar characteristics","The pool should be large","Losses of the members should be reasonably independent","Members of the pool should be as different from one another as possible"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Pooling works best when the group is large, homogeneous (similar policies) and the losses are reasonably independent, so that the law of large numbers applies. Making the members as different as possible works against homogeneity and makes predictions less certain. Options B, A and C are all features of a good pool."}},{"itemId":"e5518cbc-5edc-549f-842d-6d48b4d4eeea","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"64014622-c29b-53c2-a457-17972eaa3c86","sourceKey":"bank:ACS101:NAT-054","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main purpose of pooling many individual risks together in insurance?","options":["To let an insurer manage individual risks by reducing the variability of total outcomes","To avoid using any past data when setting premiums","To increase the uncertainty faced by the insurer","To make sure every member of the pool suffers a loss"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Pooling is the root of insurance: individuals transfer their risks to an entity that groups them together, which reduces the variance of the total outcome to an acceptable level. Option D is absurd, option C is the opposite of what pooling does, and option B is wrong because pooled experience is exactly the data actuaries use."}},{"itemId":"e59d557c-69a7-5c55-8f8a-f134d9eeea07","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6a9ac2e9-1d1a-574a-bfc4-ccc6e5cead05","sourceKey":"bank:ACS101:NAT-055","parentItemId":null,"revision":1,"payload":{"prompt":"Statistical regularity refers to the idea that","options":["every random event happens at regular fixed intervals, such as once a year","random events never show any pattern at all","random events show regular patterns when they are repeated enough times or when there are enough similar events","statistics can predict exactly what will happen to each individual"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Statistical regularity means that random events display regularity when repeated often enough or when there are enough similar events; it is an umbrella term covering the law of large numbers and central limit theorems. Option A confuses it with a timetable, option D overstates it because individual outcomes remain uncertain, and option B contradicts it."}},{"itemId":"ee324eae-e1e8-5522-bb1a-7cb798282053","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"df0155f7-c22a-5970-8e31-9846a5eba1a6","sourceKey":"bank:ACS101:NAT-056","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Aba pays a fixed premium of N30,000 a year to insure her shop instead of facing a small chance of losing N3,000,000 in a fire. Which principle explains her choice?","options":["Risk aversion: preferring a small certain loss to a large uncertain one","Risk seeking: preferring a large uncertain loss to a small certain one","Simple interest accumulation","The law of diminishing returns in production"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Risk-averse people prefer a small but certain loss (the premium) to a large uncertain one (the fire loss), and this principle underlies insurance. Option B describes the opposite attitude. Options D and C are unrelated economic and financial ideas."}},{"itemId":"f318d3c1-229a-5187-b9a3-1558bf81939a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8cad7d8a-168e-5468-926c-7e9e74a74630","sourceKey":"bank:ACS101:NAT-057","parentItemId":null,"revision":1,"payload":{"prompt":"Risk-averse people are often willing to pay an insurance premium that is higher than their expected loss. What does this extra amount allow an insurer to do?","options":["Guarantee that no claims will ever be made","Charge every customer exactly the same premium","Cover its expenses and make a profit","Avoid holding any reserves"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"The willingness of risk-averse customers to pay above their expected loss gives the insurer room to cover its expenses and earn a profit. It does not stop claims (A), remove the need for reserves (D) or force a single premium for everyone (B)."}},{"itemId":"b4d531ad-176e-5e5f-adbe-95e6a89904b6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7054ef40-c273-503a-9e8f-b790308f06d9","sourceKey":"bank:ACS101:NAT-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of an insurable risk?","options":["There is a potential loss that is significant and important","The loss is fully under the policyholder's control","The loss and its economic value are well defined","Covered losses are reasonably independent of one another"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"An insurable risk involves a significant potential loss whose size is well defined and which is outside the policyholder's complete control, with losses reasonably independent. If the loss were fully under the policyholder's control, they could cause it deliberately, so it would not be insurable. Options A, C and D are genuine features."}},{"itemId":"c8c96556-d94d-5b9c-8222-fe42224e8426","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c51538ea-694b-52c3-a69a-1572298269f6","sourceKey":"bank:ACS101:NAT-059","parentItemId":null,"revision":1,"payload":{"prompt":"An actuarial model is best described as","options":["a simplified representation of real-world relationships used to estimate and guide decisions","an exact copy of the real world that removes all uncertainty from decisions","a physical scale model of an insured building or vehicle","a complete list of the names and addresses of all policyholders"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuarial model is a simplified representation of how real-world variables relate, built from statistical, financial, economic and mathematical ideas, and used to explain a system, derive estimates and guide decisions. No model is an exact copy that removes uncertainty (B). Options C and D are a physical replica and a database, not models in the actuarial sense."}},{"itemId":"3a424d60-7c27-5494-83ca-e1c9eceb85b1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a4cdffd6-1faa-524d-bf9d-a37aace4f4ad","sourceKey":"bank:ACS101:NAT-060","parentItemId":null,"revision":1,"payload":{"prompt":"An actuarial model has an input component, a processing component and an output component. What does the processing component do?","options":["It transforms the inputs into estimates","It translates estimates into useful business information","It collects premiums from policyholders","It delivers assumptions, parameters and data to the model"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"The processing component is the engine of the model: it takes the inputs and transforms them into estimates. Delivering assumptions, parameters and data (D) is the input component, and turning estimates into business information (B) is the output component. Collecting premiums (C) is not part of a model."}},{"itemId":"88c11dbd-c8c8-5c2f-9f7f-cfe93e7dfa09","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7d9c69b3-3542-5859-88b7-bbebda138ac5","sourceKey":"bank:ACS101:NAT-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which component of an actuarial model delivers assumptions, parameters and data to the model?","options":["The input component","The production phase","The processing component","The output component"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"The information input component feeds the model with its assumptions, parameters and data. The processing component (C) turns those inputs into estimates, and the output component (D) turns estimates into business information. The production phase (B) is a stage in the model's life cycle, not a component."}},{"itemId":"26bf1cb7-5c4f-5227-a51d-22950730b1a0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d20716ee-ed92-5203-a925-058593edb834","sourceKey":"bank:ACS101:NAT-062","parentItemId":null,"revision":1,"payload":{"prompt":"An actuarial model evolves through a life cycle. Which of the following is NOT one of its phases?","options":["Liquidation phase","Implementation phase","Production phase","Specification phase"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A model's life cycle runs from specification (deciding what it should do), to implementation (building it), to production (running it one or more times). There is no liquidation phase; liquidation is a term for winding up a company. Options D, B and C are the genuine phases."}},{"itemId":"fcc3bc72-46c2-5f91-963f-99e952ca1559","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"99346313-1df3-5ed9-a8d6-a10b374eceaf","sourceKey":"bank:ACS101:NAT-063","parentItemId":null,"revision":1,"payload":{"prompt":"An estimate of an uncertain variable that is fed into a financial model, normally for calculating premiums or benefits, is called an actuarial","options":["claim","assumption","dividend","audit"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuarial assumption is an estimate of an uncertain input, such as a future interest, inflation or mortality rate, used in a model to calculate premiums or benefits. An audit (D) checks past records, a dividend (C) is a share of profits, and a claim (A) is a request for payment under a policy."}},{"itemId":"c6290db5-a937-5390-97f4-85b03542dca2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d3005b3d-13de-5d69-aa88-d68fdb063a82","sourceKey":"bank:ACS101:NAT-064","parentItemId":null,"revision":1,"payload":{"prompt":"In pricing a new savings plan, an actuary in Lagos uses one fixed set of assumptions (for example, 10% interest every year) and produces a single projected result. This type of model is","options":["deterministic","stochastic","experimental","random"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A deterministic model treats events as occurring with certainty, so one fixed set of assumptions gives one projected result. A stochastic model (B) allows inputs to vary randomly and produces a range of outcomes with probabilities. Options D and C are not the standard names for this kind of model."}},{"itemId":"14bb983c-24e8-598c-ada4-69df522147ba","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ddbda000-4bea-57eb-b252-e3eb716d8ef3","sourceKey":"bank:ACS101:NAT-065","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary runs 10,000 simulations in which future interest rates and claim amounts vary randomly, and reports the probability distribution of the insurer's possible profits. This is an example of","options":["a stochastic model","a single best-estimate projection","an accounting audit","a deterministic model"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A stochastic model estimates the probability distribution of possible outcomes by allowing random variation in one or more inputs, which is what the 10,000 simulations do. A deterministic model (D) and a single projection (B) give just one result, and an audit (C) checks past records rather than modelling the future."}},{"itemId":"969a34a7-977e-5119-be76-07c17e458d65","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b6743504-3c7c-5be6-984f-0108c59bc2fa","sourceKey":"bank:ACS101:NAT-066","parentItemId":null,"revision":1,"payload":{"prompt":"An estimate of an assumption or a liability that is intended to be neither optimistic nor conservative is called a","options":["best estimate","prudent margin","guaranteed value","worst-case estimate"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"A best estimate aims at the most realistic value, leaning neither towards optimism nor towards caution. A worst-case estimate (D) and a prudent margin (B) are deliberately cautious, and a guaranteed value (C) is a contractual promise rather than an estimate."}},{"itemId":"854bcd68-5263-50cb-85b6-c32cbe59057d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b60d4372-49b2-54d8-a6d6-2f2dd109a6a1","sourceKey":"bank:ACS101:NAT-067","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial modelling, a set of assumptions about future conditions, representing expectations or possibilities based on professional judgment or prescribed by law, is called a","options":["premium","scenario","ledger","policy"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"A scenario is a set of assumptions about future conditions used in a model, for example a 'high inflation' scenario. A premium (A) is the price of insurance, a policy (D) is the insurance contract, and a ledger (C) is an accounting record."}},{"itemId":"ee14ee25-c3b7-5b21-8247-15c96cbe65e5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"25b9ff9a-cf68-54b3-a20d-4dcaf67c6c22","sourceKey":"bank:ACS101:NAT-068","parentItemId":null,"revision":1,"payload":{"prompt":"The actuarial control cycle is a problem-solving framework for managing a financial product or scheme. Which sequence correctly describes it?","options":["Define the problem, design the solution, monitor the results","Monitor the results, define the problem, sell the product","Design the solution, audit the accounts, close the scheme","Collect premiums, pay claims, declare dividends"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"The control cycle starts by defining the problem, then designing a solution, and then monitoring the results, which feeds back into redefining the problem. Option B puts monitoring first and adds selling, option C includes auditing and closing, and option D lists routine insurance operations rather than the cycle."}},{"itemId":"43589c33-f68d-5d43-bd01-96aabb392a5f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3c2b3735-c364-5868-9ac1-8cd314a13d20","sourceKey":"bank:ACS101:NAT-069","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary's work is based on which of the following, and performed with professional judgment?","options":["Rumour, opinion and guesswork","Advertising, sales targets and branding","Luck, intuition and tradition","Theory, data and experience"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuary's work rests on theory, data and experience, and is carried out with professional judgment. Options A and C replace evidence with guesswork or chance, and option B describes marketing priorities rather than the basis of actuarial work."}},{"itemId":"c0d5e749-3419-5b76-b7a4-b81093f1a166","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"98bd25cf-c491-531b-9624-f98a076c15dd","sourceKey":"bank:ACS101:NAT-070","parentItemId":null,"revision":1,"payload":{"prompt":"Why is professional judgment required in an actuary's work?","options":["Because actuaries are not allowed to use data","Because all actuarial results are already fixed by law","Because their tasks affect several stakeholders with conflicting needs","Because actuaries work only for one person at a time"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial work affects many stakeholders, such as policyholders, shareholders, regulators and employees, whose needs can differ or conflict, so the actuary must exercise professional judgment in balancing them. Option A is false because data is central, option B overstates the role of law, and option D contradicts the many-stakeholder nature of the work."}},{"itemId":"bbc1b754-9dfc-5246-b3ed-2ea3181c664f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cda62f77-5816-53f6-932f-e66a6e211cb1","sourceKey":"bank:ACS101:NAT-071","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT part of the standard description of what an actuary does?","options":["Identifying, analysing and documenting risks","Ignoring results once a recommended solution has been put in place","Developing recommendations that lead to implemented solutions","Defining problems and generating ideas"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuary identifies, analyses and documents risks, defines problems, generates ideas, develops recommendations and then continuously monitors results. Ignoring results after implementation contradicts that last step. Options A, D and C are all part of the role."}},{"itemId":"550a744d-7420-5975-b679-0208a81f5d87","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d4795ce1-e1c2-55b6-bebb-c25604477834","sourceKey":"bank:ACS101:NAT-072","parentItemId":null,"revision":1,"payload":{"prompt":"Developing premiums intended to cover losses from underwritten risks and to provide future benefits payable to beneficiaries, using probabilities of loss, is called actuarial","options":["liquidation","pricing","marketing","auditing"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial pricing uses probabilities of loss to set premiums that cover losses from the risks written and provide the future benefits promised. Auditing (D) checks past records, marketing (C) promotes products, and liquidation (A) is the winding up of a company."}},{"itemId":"fce4f0eb-53c5-53f6-a86b-57f5562624db","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0ad4343d-67f0-58a7-a0b1-37f0d6f576b8","sourceKey":"bank:ACS101:NAT-073","parentItemId":null,"revision":1,"payload":{"prompt":"A liability that an insurer sets aside to pay future claims is called a","options":["dividend","premium","reserve","commission"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Reserves are amounts an insurer holds as a liability so that it can pay future claims on the policies it has written. A premium (B) is what the customer pays for cover, a commission (D) is paid to intermediaries, and a dividend (A) is a distribution of profit to owners."}},{"itemId":"e62ed06a-9018-5f0a-9c3f-8a34262faac1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7ae172be-eb14-5d87-8a8d-1d267935e4d1","sourceKey":"bank:ACS101:NAT-074","parentItemId":null,"revision":1,"payload":{"prompt":"At a Nigerian general insurer, one actuary decides how much to charge new customers for motor cover next year, while another estimates how much the company must hold now to pay claims on policies already sold. These two tasks are, respectively,","options":["underwriting and marketing","auditing and pricing","pricing and reserving","reserving and pricing"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Setting the charge for new customers is pricing, while estimating the money needed now for claims on existing policies is reserving. Option D swaps the two, option A names non-actuarial functions, and option B wrongly calls the second task an audit."}},{"itemId":"755bb787-5e54-5b18-b526-456bb691c101","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c1717639-8ffd-5f4a-9822-f85428e138cc","sourceKey":"bank:ACS101:NAT-075","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which an insurance company places a value on its assets and/or its liabilities is called","options":["underwriting","reinsurance","valuation","selection"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Valuation is the process of placing a value on an insurer's assets and liabilities, for example to check that it holds enough to meet its promises. Underwriting (A) and selection (D) concern deciding whether to accept a risk, and reinsurance (B) is insurance bought by an insurer."}},{"itemId":"484b754e-9089-5f4c-87c0-be01e20d769b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f545bf6a-13e8-5b4f-81b9-7af7fd56202f","sourceKey":"bank:ACS101:NAT-077","parentItemId":null,"revision":1,"payload":{"prompt":"In ideal risk management, which risks should be handled first?","options":["Risks that affect competitors rather than the firm itself","Whichever risks were identified most recently","Risks with the greatest loss and the greatest probability of occurring","Risks with the smallest loss and the lowest probability"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Ideal risk management follows a prioritisation process in which risks with the greatest loss and the greatest probability are handled first, and smaller, less likely risks later. Option D reverses the order, option B ignores size and likelihood, and option A is not about the firm's own risks."}},{"itemId":"f3d7bf18-fc4a-5a5c-a9e9-6d2528fe163c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b897b81f-033a-5930-b7c0-992fcbf37b83","sourceKey":"bank:ACS101:NAT-078","parentItemId":null,"revision":1,"payload":{"prompt":"A logistics company in Port Harcourt pays a premium to an insurer so that the insurer, rather than the company, bears the cost if its trucks are stolen. This is an example of","options":["risk retention","risk identification","risk transfer","statistical regularity"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Shifting the financial burden of a risk from one party (the company) to another (the insurer) is risk transfer. Risk retention (A) would mean the company keeps the risk itself, risk identification (B) is only recognising the risk, and statistical regularity (D) is a property of repeated random events."}},{"itemId":"633d3396-eac8-5a76-be3f-fafebfb5264c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"230d9cf5-c7f8-5027-8dca-c2e7d80a3235","sourceKey":"bank:ACS101:NAT-079","parentItemId":null,"revision":1,"payload":{"prompt":"An arrangement in which one party assumes the obligation to provide benefits that offset undesirable economic consequences suffered by a second party, in return for payments called considerations, is called a","options":["sinking fund","credit rating","stock exchange","financial security system"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"A financial security system, such as an insurance product or retirement plan, has one party promising benefits to offset another party's undesirable economic consequences in return for considerations (premiums or contributions). A stock exchange (C) is a market for shares, a credit rating (B) assesses creditworthiness, and a sinking fund (A) saves to repay a debt."}},{"itemId":"21d60c94-1f4b-5a69-a51f-2e6d0065d27a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d26ea003-a132-584d-b097-5ac2c535998e","sourceKey":"bank:ACS101:NAT-080","parentItemId":null,"revision":1,"payload":{"prompt":"The data obtained from the actual operation of an insurance or pension scheme, which actuaries use to estimate rates of occurrence and amounts of payment, is called","options":["speculation","depreciation","experience","goodwill"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"Experience is the data obtained in the operation of a risk management system, and estimates based on it are called experience rates. Speculation (A) is guessing for profit, goodwill (D) is an intangible business asset, and depreciation (B) is the fall in value of fixed assets."}},{"itemId":"408036bc-19fb-50ce-86f3-82dca039af47","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e51d32ca-9ae8-57da-b0dd-e1a7976510af","sourceKey":"bank:ACS101:NAT-081","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT usually listed among the main skills needed to become an actuary?","options":["Excellent oral and written communication skills","Mathematical and analytical skills","Strong business sense and commercial awareness","Medical surgical training"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuaries need mathematical and analytical skills, strong communication, business sense, problem-solving, project management, self-motivation and teamwork. Surgical training belongs to medicine and is not an actuarial skill. Options B, A and C are all standard requirements."}},{"itemId":"c79878b2-df16-595d-b43f-ac6dacec30f6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"191411af-7b76-5828-8b07-ab26fd91878d","sourceKey":"bank:ACS101:NAT-082","parentItemId":null,"revision":1,"payload":{"prompt":"Why is self-motivation considered an especially important quality for someone training to be an actuary?","options":["Because actuaries are not allowed to work in teams","Because actuaries must sell their own insurance policies","Because actuarial work requires no supervision or training","Because trainees must pass professional exams while working full time"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial qualification comes from passing a series of professional exams, and trainees normally study for them while working, so self-motivation and a strong work ethic are vital. Option A is wrong because teamwork is itself a required skill, option C ignores the long training, and option B confuses actuaries with salespeople."}},{"itemId":"48ac62fa-dc6c-5815-b9e9-4676d3f8c181","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4939f162-18ef-5abd-aab1-ebbe0e8948db","sourceKey":"bank:ACS101:NAT-083","parentItemId":null,"revision":1,"payload":{"prompt":"Besides a solid background in mathematics, which two qualities do qualified actuaries say are equally important?","options":["Self-motivation and good communication skills","Physical strength and speed","Artistic talent and musical ability","Fluency in Latin and Greek"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Qualified actuaries stress that self-motivation, for getting through the exams, and good communication skills, for explaining technical results to non-specialists, matter as much as mathematics. Options B, C and D are not listed as actuarial requirements."}},{"itemId":"7c34f79c-8bcd-5207-8c02-9cd92c85cc16","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a716b448-0f04-5ca1-896d-61aa914205ae","sourceKey":"bank:ACS101:NAT-084","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary must explain to the board of a Nigerian insurer, most of whom are not mathematicians, why premiums need to rise next year. Which skill is most directly being used?","options":["Computer hardware repair","Physical fitness","Creative writing of fiction","Communication skills"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Explaining technical findings clearly to non-specialists, such as a board of directors, is a matter of oral and written communication, which is listed as an essential actuarial skill. Hardware repair (A), fiction writing (C) and physical fitness (B) are not what this task needs."}},{"itemId":"6f37745c-25ba-5fb0-b749-47bd7291b345","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"db8bae7a-c6d1-5564-91c8-f27a7414900e","sourceKey":"bank:ACS101:NAT-085","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of qualities is most typical of a successful actuary?","options":["Strong salesmanship with little interest in analysis","A preference for avoiding numbers, data and computers","A dislike of continual learning and examinations","Analytical skill, business acumen, creativity and teamwork"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Successful actuaries combine keen analytical and problem-solving skills with business acumen, creativity, independence and the ability to collaborate. Option B rules out the core tools of the job, option A puts selling above analysis, and option C clashes with an exam-based career that rewards continual learning."}},{"itemId":"ba744411-dfea-5759-bfa7-626e207b6aa3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"115416fd-2eec-5bd7-ab86-cc5356d7a513","sourceKey":"bank:ACS101:PAV-001","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos landlord will receive rent of N20,000 at the end of year 1, N30,000 at the end of year 2 and N50,000 at the end of year 3. Using compound interest at an effective rate of 10% per annum, what is the present value of these receipts at time 0, to the nearest naira?","options":["N75,131","N80,541","N81,643","N107,200"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"The present value of a stream is the sum of each payment times v^t: 20,000(1.1)^-1 + 30,000(1.1)^-2 + 50,000(1.1)^-3 = N80,541. Option D is the accumulated value at time 3, not the value today. Option C discounts with simple interest (dividing by 1 + 0.1t), and option A wrongly discounts the whole N100,000 for 3 years."}},{"itemId":"d2c153dd-4428-59ab-ad2c-73e9a88aaa00","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4613bb96-33e1-5f26-a0b4-27276540d120","sourceKey":"bank:ACS101:PAV-002","parentItemId":null,"revision":1,"payload":{"prompt":"A trader deposits N10,000 now (time 0), N15,000 at time 2 years and N25,000 at time 3 years into an account earning compound interest at 8% per annum effective. What is the accumulated value of the account at time 4 years, to the nearest naira?","options":["N42,706","N68,024","N58,989","N58,101"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Each deposit grows for the time left until year 4: 10,000(1.08)^4 + 15,000(1.08)^2 + 25,000(1.08)^1 = N58,101. Option B accumulates all N50,000 for the full 4 years, ignoring the later deposit dates. Option C uses each deposit's own time t as the exponent instead of 4 - t, and option A is the present value at time 0."}},{"itemId":"4d81c308-6085-5101-addd-796e4a689758","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b9f1753e-8f5c-50d5-a657-ce3b6913b602","sourceKey":"bank:ACS101:PAV-003","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund expects N60,000 at the end of year 2 and N80,000 at the end of year 5. At an effective rate of compound interest of 6% per annum, what is the present value of the two amounts, to the nearest naira?","options":["N115,110","N104,616","N113,180","N116,035"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV = 60,000v^2 + 80,000v^5 with v = 1/1.06, giving 53,400.50 + 59,781.85 = N113,180. Option D swaps the discount periods of the two amounts, option B discounts the total for 5 years, and option A uses simple-interest discounting."}},{"itemId":"af1297c8-07ce-544e-89ff-1e38730dd84c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"182ffa51-fdae-5d57-a595-0ae3920b3b90","sourceKey":"bank:ACS101:PAV-004","parentItemId":null,"revision":1,"payload":{"prompt":"Payments of N40,000 each are due at times 1, 3 and 5 years. Using compound interest at 5% per annum effective, what is the value of the three payments at time 3 years, to the nearest naira?","options":["N103,990","N122,195","N132,720","N120,381"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"At time 3 the first payment is accumulated for 2 years, the second is taken at face value and the third is discounted for 2 years: 40,000(1.05)^2 + 40,000 + 40,000(1.05)^-2 = N120,381. Option B discounts the last payment for only 1 year, while options A and C are the values at time 0 and time 5."}},{"itemId":"7acb30d6-afc6-595d-b5e0-b372a4173c29","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0b8e624d-05f2-5895-9e30-e6cbc8707206","sourceKey":"bank:ACS101:PAV-005","parentItemId":null,"revision":1,"payload":{"prompt":"A school owner pays a supplier N25,000 now, N25,000 at the end of year 1, N30,000 at the end of year 2 and N45,000 at the end of year 4. At 12% per annum effective compound interest, what is the present value of all the payments, to the nearest naira?","options":["N89,139","N99,836","N125,000","N74,836"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"The payment now is not discounted, so PV = 25,000 + 25,000(1.12)^-1 + 30,000(1.12)^-2 + 45,000(1.12)^-4 = N99,836. Option A discounts every payment by one extra year, treating the first one as if it were due at time 1. Option D leaves out the payment made now, and option C simply adds the payments without discounting."}},{"itemId":"4d7897dc-3570-5968-b2c9-84d031ec3bba","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d6c61350-bb4c-5bef-a408-add0a975c2c2","sourceKey":"bank:ACS101:PAV-006","parentItemId":null,"revision":1,"payload":{"prompt":"Payments of N50,000 at the end of quarter 1, N50,000 at the end of quarter 2 and N100,000 at the end of quarter 4 are valued at a nominal rate of interest of 12% per annum convertible quarterly (i^(4) = 0.12). What is their present value, to the nearest naira?","options":["N185,135","N179,785","N184,522","N148,054"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The rate per quarter is 0.12/4 = 3%, so PV = 50,000(1.03)^-1 + 50,000(1.03)^-2 + 100,000(1.03)^-4 = N184,522. Option D wrongly uses 12% per quarter, option A treats 12% as an effective annual rate, and option B divides 12% by 3 instead of 4."}},{"itemId":"5e379872-e671-5ca2-b017-2a2d8f3e517f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c08d1358-7006-5f00-8fc6-76f1f611b5c2","sourceKey":"bank:ACS101:PAV-007","parentItemId":null,"revision":1,"payload":{"prompt":"A company must pay N200,000 at the end of year 1 and N300,000 at the end of year 2. Interest is at a nominal rate of 8% per annum convertible half-yearly. What is the present value of the two payments, to the nearest naira?","options":["N442,387","N469,675","N448,328","N441,352"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"With 4% per half-year, year 1 is 2 half-years and year 2 is 4 half-years: 200,000(1.04)^-2 + 300,000(1.04)^-4 = N441,352. Option A treats 8% as effective annual, option B counts years instead of half-years, and option C attaches the discount factors to the wrong payments."}},{"itemId":"6abcb28a-1ae3-530c-b126-b864b135e045","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8950bf36-5d58-5609-8721-d6ced5133fc2","sourceKey":"bank:ACS101:PAV-008","parentItemId":null,"revision":1,"payload":{"prompt":"Using a constant force of interest delta = 0.08 per annum (so that v^t = e^(-delta t)), find the present value of N100,000 due at time 1 year and N150,000 due at time 3 years, to the nearest naira.","options":["N196,657","N210,306","N299,016","N211,667"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"With a force of interest, PV = 100,000e^(-0.08) + 150,000e^(-0.24) = 92,311.63 + 117,994.17 = N210,306. Option D treats 8% as an effective annual rate; with delta = 0.08 the effective rate is e^0.08 - 1 = 8.33%, so the correct discounting is slightly heavier and the true PV is lower. Option C accumulates instead of discounting, and option A discounts the total for 3 years."}},{"itemId":"6ed4f37a-d29d-59b2-9c40-e8db045a54b1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"65f7977c-4db7-5c36-9a07-c3c20fbd2bf1","sourceKey":"bank:ACS101:PAV-009","parentItemId":null,"revision":1,"payload":{"prompt":"An investment pays N50,000 at the end of each year for 4 years. At an effective rate of compound interest of 10% per annum, what is its present value, to the nearest naira?","options":["N174,343","N136,603","N158,493","N232,050"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The PV is 50,000(v + v^2 + v^3 + v^4) = 50,000 x a_4| = 50,000 x 3.1699 = N158,493. Option A treats the payments as made at the start of each year (annuity-due), option D is the accumulated value at time 4, and option B discounts the total of N200,000 for 4 years."}},{"itemId":"c27bbff5-8936-5660-82d7-8cb6dc57952c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5b3195d6-bb12-5c01-b168-fc6e1f195116","sourceKey":"bank:ACS101:PAV-010","parentItemId":null,"revision":1,"payload":{"prompt":"A student saves N20,000 at the START of each year for 3 years (times 0, 1 and 2) in an account paying 7% per annum effective compound interest. How much is in the account at the end of year 3 (time 3), to the nearest naira?","options":["N68,799","N72,600","N64,298","N73,503"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"The deposits earn interest for 3, 2 and 1 years: 20,000[(1.07)^3 + (1.07)^2 + (1.07)] = N68,799. Option C assumes the deposits are made at the end of each year, so the last one earns no interest. Option D accumulates all N60,000 for 3 years, and option B applies simple interest to the total."}},{"itemId":"ab402771-3be1-5d2a-88c3-f2738ba4a76d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ece8ffe2-d8e6-5858-b193-705143cbec18","sourceKey":"bank:ACS101:PAV-011","parentItemId":null,"revision":1,"payload":{"prompt":"An artisan deposits N12,000 at the end of every year for 5 years into a cooperative fund earning compound interest at 6% per annum effective. What is the accumulated value at the time of the 5th deposit, to the nearest naira?","options":["N80,294","N67,645","N50,548","N71,704"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"The accumulated value is 12,000 x s_5| = 12,000[(1.06)^5 - 1]/0.06 = 12,000 x 5.6371 = N67,645. Option D treats the deposits as made at the start of each year (one extra year of interest each), option A accumulates the total for 5 years, and option C is the present value."}},{"itemId":"4b70a0a0-5ea3-56a4-b80e-886a43ebab63","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5604a81a-f2da-5cc2-8cd5-dcd98de6be8f","sourceKey":"bank:ACS101:PAV-012","parentItemId":null,"revision":1,"payload":{"prompt":"At 9% per annum effective, a_4| = 3.2397 and s_4| = 4.5731. What is the present value of N40,000 payable at the end of each year for 4 years, to the nearest naira?","options":["N146,789","N182,925","N129,588","N141,252"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"For level payments P in arrears, PV = P x a_4| = 40,000 x 3.2397 = N129,588. Option B uses s_4|, which gives the accumulated value at time 4. Option D multiplies by (1.09), which would value payments made at the start of each year, and option A discounts the total for only one year."}},{"itemId":"d8d9a5b5-0e7f-50aa-bb46-1d4b27024c75","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0c81b3ee-d453-50ec-8013-0b19f01ba66d","sourceKey":"bank:ACS101:PAV-013","parentItemId":null,"revision":1,"payload":{"prompt":"A borrower owes N100,000 due at time 2 years and N150,000 due at time 5 years. The lender agrees to accept one payment at time 3 years instead. Using compound interest at 8% per annum effective, what single payment at time 3 is equivalent, to the nearest naira?","options":["N187,821","N250,000","N267,553","N236,601"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Valuing both debts at time 3: 100,000(1.08)^1 + 150,000(1.08)^-2 = 108,000 + 128,600.82 = N236,601. Option C moves each debt in the wrong direction (discounting the earlier one and accumulating the later one). Option B ignores interest, and option A is the value of the debts at time 0, not time 3."}},{"itemId":"5a635ee3-caf3-5cce-963d-9c6521428c1e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2826ecdd-30bd-5838-a61a-7c4dc37f1123","sourceKey":"bank:ACS101:PAV-014","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N500,000 is repaid by N200,000 at the end of year 1, N200,000 at the end of year 2 and a final payment X at the end of year 3. Interest is at 10% per annum effective. Find X to the nearest naira.","options":["N100,000","N152,893","N203,500","N265,500"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The equation of value at time 0 is 500,000 = 200,000v + 200,000v^2 + Xv^3, so X = (500,000 - 181,818.18 - 165,289.26)(1.1)^3 = N203,500. Option B is the outstanding present value but forgets to accumulate it to time 3. Option A ignores interest altogether, and option D accumulates the loan but subtracts the repayments without interest."}},{"itemId":"2a0ae1ef-1454-5a53-839a-dd7668554e00","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dd887171-302f-5acc-a31d-37d20fafb279","sourceKey":"bank:ACS101:PAV-015","parentItemId":null,"revision":1,"payload":{"prompt":"Two debts of N50,000 each are due at times 2 years and 6 years. They are to be replaced by one payment of N100,000 at time t years. Using compound interest at 8% per annum effective, find t to 2 decimal places.","options":["3.70 years","1.67 years","3.85 years","4.00 years"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The equation of value is 100,000v^t = 50,000v^2 + 50,000v^6 = 74,375.42, so t = ln(100,000/74,375.42)/ln(1.08) = 3.85 years. Option D is the simple average of the two dates, which is close but not exact under compound interest. Option A divides by 0.08 instead of ln(1.08), and option B mixes a base-10 logarithm on top with a natural logarithm underneath."}},{"itemId":"678a5c19-0721-5192-93e5-43159ca301d3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"75c36dfd-6178-5d68-bd77-82bf5b5156e7","sourceKey":"bank:ACS101:PAV-016","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery is considering an oven costing N1,000,000 now. It is expected to generate net cash inflows of N400,000 at the end of each of the next 3 years. Using a discount rate of 12% per annum effective, what is the net present value of the project, to the nearest naira?","options":["N67,875","-N39,267","N39,267","N200,000"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"NPV = PV of inflows - PV of outflows = 400,000(v + v^2 + v^3) - 1,000,000 = 960,732.69 - 1,000,000 = -N39,267. Option D ignores discounting and wrongly suggests a profit, option C has the sign reversed, and option A discounts the initial cost even though it is paid now."}},{"itemId":"aa32b0f6-23a6-5ce5-9646-299043488f96","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bdef4a36-18b8-51d4-a8db-08e3f8564da0","sourceKey":"bank:ACS101:PAV-017","parentItemId":null,"revision":1,"payload":{"prompt":"A poultry project requires N300,000 now and a further N100,000 at the end of year 1. It returns N250,000 at the end of year 2 and N300,000 at the end of year 3. At 10% per annum effective, what is the net present value, to the nearest naira?","options":["N132,006","N41,097","N222,915","N150,000"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"NPV = -300,000 - 100,000(1.1)^-1 + 250,000(1.1)^-2 + 300,000(1.1)^-3 = N41,097. Option A forgets the second outlay at year 1, option C treats that outlay as an inflow, and option D adds the cash flows without discounting."}},{"itemId":"b4f4a8b7-31c1-5cd6-9983-17015dddf1ad","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cb05392b-ffdb-585c-94bd-8f8584ddd03b","sourceKey":"bank:ACS101:PAV-018","parentItemId":null,"revision":1,"payload":{"prompt":"An investor in Ibadan can buy a business for N2,000,000 now. It will produce N800,000 at the end of year 1, N900,000 at the end of year 2 and N700,000 at the end of year 3. Her required return is 15% per annum effective. Based on NPV, what should she conclude?","options":["NPV is about -N163,557; accept, as NPV is close to zero","NPV is about N400,000; accept, as inflows exceed the cost","NPV is about N182,918; accept, as NPV is positive","NPV is about -N163,557; reject, as it earns less than 15%"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"NPV at 15% = -2,000,000 + 800,000(1.15)^-1 + 900,000(1.15)^-2 + 700,000(1.15)^-3 = -N163,557, which is negative, so the business returns less than 15% and should be rejected. Option B ignores discounting, option C discounts at 5% instead of the required 15%, and option A gets the right figure but the wrong decision."}},{"itemId":"0c552f2a-5118-5628-ae3c-fcace13f0f53","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3bc7d7b2-72a8-58f1-84e8-2dab1f386a0b","sourceKey":"bank:ACS101:PAV-019","parentItemId":null,"revision":1,"payload":{"prompt":"An investor pays N100,000 now and receives N55,000 at the end of year 1 and N60,500 at the end of year 2. At which effective annual rate of compound interest is the net present value of this transaction exactly zero?","options":["7.75%","10%","15.5%","12%"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"At 10%, 55,000/1.1 = 50,000 and 60,500/(1.1)^2 = 50,000, so the inflows are worth exactly N100,000 and the NPV is zero; this rate is the internal rate of return. Option C is the total gain of N15,500 as a percentage of the outlay, ignoring timing, and option A spreads that gain evenly over 2 years. At 12% (option D) the inflows are worth less than N100,000, so the NPV is negative."}},{"itemId":"f5c2e711-b64f-5bda-88f8-87b83eea6fd6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"29689335-923e-5bd1-88b7-d2eb75c6be26","sourceKey":"bank:ACS101:PAV-020","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N100,000 now and returns N60,000 at the end of each of years 1 and 2. Setting the NPV to zero gives 60,000v^2 + 60,000v - 100,000 = 0. What is the internal rate of return (effective per annum), to 2 decimal places?","options":["9.54%","10.00%","20.00%","13.07%"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Solving the quadratic gives v = 0.88444, so i = 1/v - 1 = 13.07%. Option C is the undiscounted gain of N20,000 as a percentage of the cost, and option B spreads that gain over 2 years; both ignore the timing of the payments. Option A treats the whole N120,000 as received at the end of year 2."}},{"itemId":"76424aa8-1622-5e0e-bbdd-2021fa5c84c7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6f83364f-cd99-5870-8e0a-db1656a9853c","sourceKey":"bank:ACS101:PAV-021","parentItemId":null,"revision":1,"payload":{"prompt":"At 10% per annum effective compound interest, compare Stream A (N60,000 at the end of year 1 and N60,000 at the end of year 3) with Stream B (N122,000 at the end of year 2). Which statement is correct?","options":["A is worth more, since its first payment comes a year sooner","A is worth more by about N1,202 in present value","They are of equal value, since both are centred on year 2","B is worth more by about N1,202 in present value"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV(A) = 60,000(1.1)^-1 + 60,000(1.1)^-3 = N99,624 and PV(B) = 122,000(1.1)^-2 = N100,826, so B is worth N1,202 more. Option A looks only at the first payment date instead of valuing all the payments, option B has the right gap but the wrong stream, and option C assumes payments placed symmetrically around a date are worth the same as one payment at that date, which is not true under compound interest."}},{"itemId":"bb10a13a-e6bd-53f8-a082-3d730920c0ed","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ebe906f8-ae71-5618-acd9-431539fe9f4b","sourceKey":"bank:ACS101:PAV-022","parentItemId":null,"revision":1,"payload":{"prompt":"Option A pays N100,000 at the end of year 1. Option B pays N120,000 at the end of year 3. Using compound interest, which option has the higher present value at 5% per annum effective, and which at 12% per annum effective?","options":["B at 5%, A at 12%","B at both rates","A at both rates","A at 5%, B at 12%"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"At 5%, PV(A) = N95,238 and PV(B) = N103,661, so B wins; at 12%, PV(A) = N89,286 and PV(B) = N85,414, so A wins. A higher rate penalises the later, larger payment more heavily, so the preference switches. Option B ignores the effect of the higher rate, and option D reverses the effect."}},{"itemId":"ff335d85-9a0f-52c9-b136-4bfa1c51ee5f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1d61edb1-9270-56e1-8b67-db529b7fc382","sourceKey":"bank:ACS101:PAV-023","parentItemId":null,"revision":1,"payload":{"prompt":"Payments of N100,000 are due at the end of each of years 1, 2 and 3. By how much does their present value FALL when the effective annual rate of compound interest rises from 5% to 10%, to the nearest naira?","options":["N23,640","N4,329","N15,750","N33,757"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV at 5% = N272,325 and PV at 10% = N248,685, so the PV falls by N23,640. Option B looks only at the first payment, option D discounts the total as if it were all due at year 3, and option C is the rise in accumulated value at time 3, which moves the other way."}},{"itemId":"298757d9-d819-5703-9a56-a1910e7abe7e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e86c7b11-1ccd-50bc-8d96-2bce75dbb907","sourceKey":"bank:ACS101:PAV-024","parentItemId":null,"revision":1,"payload":{"prompt":"N50,000 is invested now and a further N50,000 two years from now. The account earns 6% per annum effective for the first 2 years and 8% per annum effective after that. What is the total accumulated at the end of year 6, to the nearest naira?","options":["N144,457","N136,752","N152,865","N147,368"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"The first deposit grows to 50,000(1.06)^2 by year 2, the second deposit joins it, and the total grows at 8% for 4 years: (50,000(1.06)^2 + 50,000)(1.08)^4 = N144,457. Option B applies the two rates in the wrong order, option C accumulates both deposits from time 0, and option D uses 8% for the whole period."}},{"itemId":"ab0eb6c0-c010-5ddd-a994-6035c660ec0a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6d5eaa4b-b163-58c7-84bd-5cecef2cb8f7","sourceKey":"bank:ACS101:PAV-025","parentItemId":null,"revision":1,"payload":{"prompt":"Interest is 8% per annum effective during year 1 and 10% per annum effective during year 2. What is the present value at time 0 of N100,000 due at the end of year 1 and N100,000 due at the end of year 2, to the nearest naira?","options":["N178,326","N175,237","N176,768","N175,084"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The year-2 payment is discounted through year 2 at 10% and through year 1 at 8%: 100,000/1.08 + 100,000/(1.08 x 1.10) = N176,768. Option B uses 10% for both years of the second payment, option A uses 8% throughout, and option D discounts the first payment at the year-2 rate."}},{"itemId":"d3b11e2b-b9e5-5f9c-b643-1af067bd659c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b7353ff8-ac42-50c9-a7c7-04532e9c2942","sourceKey":"bank:ACS101:PAV-026","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde deposits N100,000 now and withdraws N30,000 at the end of year 2. The account earns 9% per annum effective compound interest. What is the balance at the end of year 4, to the nearest naira?","options":["N111,158","N115,908","N105,515","N98,811"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"Balance at year 4 = 100,000(1.09)^4 - 30,000(1.09)^2 = N105,515, because the withdrawn money would have earned interest for 2 more years. Option D acts as if the withdrawal happened at time 0, option A ignores the interest lost on the withdrawal, and option B discounts the withdrawal instead of accumulating it."}},{"itemId":"6d21b859-931c-5c71-9af8-ded33b734e1d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"942e85b1-b9c2-5d4e-9a39-c0b0cb7d6ba6","sourceKey":"bank:ACS101:PAV-027","parentItemId":null,"revision":1,"payload":{"prompt":"A firm wants N1,000,000 at the end of year 3 to replace a generator. It will make 3 equal deposits at the end of each year into an account earning 8% per annum effective. What is each deposit, to the nearest naira?","options":["N285,216","N264,611","N308,034","N333,333"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The equation of value at time 3 is X s_3| = 1,000,000, with s_3| = (1.08)^2 + 1.08 + 1 = 3.2464, so X = N308,034. Option D ignores interest, option A is the deposit that would work if deposits were made at the start of each year, and option B wrongly spreads the present value of the target over 3 years."}},{"itemId":"0cca0624-2fba-559b-8f7e-4a4017039254","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c90e38f1-4642-5700-ba27-a15180a39b30","sourceKey":"bank:ACS101:PAV-028","parentItemId":null,"revision":1,"payload":{"prompt":"Amaka wants N500,000 at the end of year 4. She makes 4 equal deposits at the START of each year (times 0, 1, 2 and 3) into an account paying 6% per annum effective. What is each deposit, to the nearest naira?","options":["N125,000","N99,012","N107,826","N114,296"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"Each deposit earns 4, 3, 2 and 1 years of interest, so X[(1.06)^4 + (1.06)^3 + (1.06)^2 + 1.06] = 500,000, giving X = 500,000/4.6371 = N107,826. Option D assumes end-of-year deposits, which need a larger amount, option A ignores interest, and option B spreads the present value of the target."}},{"itemId":"90dc98b2-6b2a-5ebc-81f1-2179234adcbb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ed4302d0-8f00-514d-81b4-3a6f1c0c3a5e","sourceKey":"bank:ACS101:PAV-029","parentItemId":null,"revision":1,"payload":{"prompt":"A trader borrows N800,000 and repays it with 3 equal payments at the end of each year. Interest is 15% per annum effective. Find each payment to the nearest naira.","options":["N266,667","N350,382","N405,567","N386,667"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"The equation of value is 800,000 = X(v + v^2 + v^3) = X a_3|, with a_3| = 2.2832 at 15%, so X = N350,382. Option C accumulates the loan for 3 years and divides by 3, which overcharges because the earlier payments reduce the debt sooner. Option D uses simple interest on the full loan, and option A ignores interest."}},{"itemId":"994a5fdc-974c-54e1-a1de-06109f60fec4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c1898744-a945-5bb2-9325-e22b75d43586","sourceKey":"bank:ACS101:PAV-030","parentItemId":null,"revision":1,"payload":{"prompt":"A debt of N300,000 due at time 2 years is to be settled instead by two equal payments X, one at time 1 year and one at time 4 years. Using compound interest at 10% per annum effective, find X to the nearest naira.","options":["N150,000","N155,727","N149,321","N123,967"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Equating present values: X(v + v^4) = 300,000v^2, so X = 247,933.88/(0.909091 + 0.683013) = N155,727. Option A ignores interest, option D halves the present value of the debt without discounting the payments, and option C places the second payment at time 3 instead of time 4."}},{"itemId":"fd8586a4-d4eb-51d7-ac20-12e3be0362e4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e6258e86-3f71-5511-aa88-dc4c8e3d5c5a","sourceKey":"bank:ACS101:PAV-031","parentItemId":null,"revision":1,"payload":{"prompt":"The present value at time 0 of a series of future payments is N250,000, using compound interest at 8% per annum effective. What is the value of the same series at time 3 years, to the nearest naira?","options":["N314,928","N291,600","N310,000","N198,458"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Under compound interest the value of a whole stream at time t equals its PV times (1 + i)^t, so 250,000(1.08)^3 = N314,928. Option D discounts instead of accumulating, option C uses simple interest, and option B accumulates for only 2 years."}},{"itemId":"ff2e4146-7028-5acc-b9d0-a6e095a98d73","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"004bec8d-c8c2-54e0-87a0-0c8f67ece9e3","sourceKey":"bank:ACS101:PAV-032","parentItemId":null,"revision":1,"payload":{"prompt":"The accumulated value at time 4 years of a series of deposits is N500,000, at 10% per annum effective compound interest. What is the value of the same series at time 0, to the nearest naira?","options":["N357,143","N328,050","N732,050","N341,507"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV = AV x v^4 = 500,000(1.1)^-4 = N341,507. Option A uses simple interest (dividing by 1.4), option B multiplies by (0.9)^4, which uses 1 - i instead of v = 1/(1 + i), and option C accumulates further instead of discounting."}},{"itemId":"b12c9a1e-24b7-5a2d-bf87-2b4cfe332bfd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"962efb25-0904-51f3-b602-dfd193160239","sourceKey":"bank:ACS101:PAV-033","parentItemId":null,"revision":1,"payload":{"prompt":"A machine costs N500,000 now and produces N200,000 at the end of each year. Using a discount rate of 10% per annum effective, in which year does the cumulative discounted cash flow first become positive (the discounted payback period)?","options":["Year 4","Year 5","Year 3","Year 2"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Cumulative discounted cash flows are -N318,182, -N152,893, -N2,630, N133,973 at the ends of years 1 to 4, so the project first breaks even in year 4. Option D is the ordinary (undiscounted) payback, since 2.5 years of N200,000 recovers N500,000. Option C is wrong because the discounted total after 3 years is still just below N500,000."}},{"itemId":"6ed59275-0495-528f-a63d-bc898497048f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"314a5c00-7bff-55ed-9aa5-f6a8e1b4d585","sourceKey":"bank:ACS101:PAV-034","parentItemId":null,"revision":1,"payload":{"prompt":"Payments of N40,000 at time 0.5 years and N60,000 at time 1.5 years are valued at an effective rate of compound interest of 10% per annum. What is their present value, to the nearest naira?","options":["N90,146","N90,269","N89,925","N85,950"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"With compound interest the discount factor for t years is (1.1)^-t even for fractional t: 40,000(1.1)^-0.5 + 60,000(1.1)^-1.5 = N90,146. Option B uses simple interest for the part-years, option D rounds the times up to whole years, and option C treats 10% as a nominal half-yearly rate (5% per half-year)."}},{"itemId":"e66afb53-628d-594f-8764-340104eec087","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d50800d9-9040-5190-8e9d-5eaff7d41a38","sourceKey":"bank:ACS101:PAV-035","parentItemId":null,"revision":1,"payload":{"prompt":"A contract pays N10,000 at the end of year 1, N20,000 at the end of year 2 and N30,000 at the end of year 3. At 5% per annum effective compound interest, what is the present value, to the nearest naira?","options":["N53,580","N55,350","N62,025","N54,422"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV = 10,000(1.05)^-1 + 20,000(1.05)^-2 + 30,000(1.05)^-3 = N53,580. Option B reverses the order of the payments, which gives a higher value because the big payment would come first. Option D discounts the total from the middle year, and option C is the accumulated value at time 3."}},{"itemId":"ee24691a-1b45-5756-91bc-d321e8525f27","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b63e00cc-836a-5b78-b1b6-ff7b596d9932","sourceKey":"bank:ACS101:PAV-036","parentItemId":null,"revision":1,"payload":{"prompt":"Deposits of N10,000, N20,000 and N30,000 are made at the ends of years 1, 2 and 3 respectively into an account paying 5% per annum effective. What is the balance immediately after the year-3 deposit, to the nearest naira?","options":["N63,525","N69,458","N62,025","N64,075"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"AV at time 3 = 10,000(1.05)^2 + 20,000(1.05) + 30,000 = N62,025. Option A also gives the last deposit a year of interest, even though it has just been made. Option D reverses the order of the deposits, and option B accumulates all N60,000 for 3 years."}},{"itemId":"5602190e-0063-5f30-bd8f-13c7132b2b2c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4949ddb6-1281-5e0a-9153-46d5824fa56f","sourceKey":"bank:ACS101:PAV-037","parentItemId":null,"revision":1,"payload":{"prompt":"A clinic buys equipment priced at N2,000,000. It pays N500,000 now, N800,000 at the end of year 1 and a final amount X at the end of year 2. The supplier charges 12% per annum effective compound interest. Find X to the nearest naira.","options":["N985,600","N785,714","N700,000","N1,081,600"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"From the equation of value 2,000,000 = 500,000 + 800,000v + Xv^2, X = (1,500,000 - 714,285.71)(1.12)^2 = N985,600. Option C ignores interest, option B is the outstanding amount at time 0 without accumulating it to year 2, and option D forgets to give the year-1 payment one year of interest."}},{"itemId":"5e3b34c6-c088-593d-9f5e-eaac8dc0826a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6d3fe8cb-2077-5cea-bc0d-0af25c3f3556","sourceKey":"bank:ACS101:PAV-038","parentItemId":null,"revision":1,"payload":{"prompt":"How much must be deposited now so that, together with a further deposit of N50,000 at the end of year 2, the account holds N200,000 at the end of year 4? Interest is 7% per annum effective compound.","options":["N108,907","N111,527","N102,579","N114,434"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"At time 4: X(1.07)^4 + 50,000(1.07)^2 = 200,000, so X = (200,000 - 57,245)(1.07)^-4 = N108,907. Option D ignores the interest on the year-2 deposit, option C subtracts the N50,000 without discounting it to time 0, and option B discounts with simple interest."}},{"itemId":"bc38baf8-f8df-5441-8f94-6751f0c25ae6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"58146901-e41d-5050-ba5a-4df0f893972c","sourceKey":"bank:ACS101:PAV-039","parentItemId":null,"revision":1,"payload":{"prompt":"N80,000 is deposited now and another N80,000 one year later, at 9% per annum effective compound interest. After how many years from now (time t, to 2 decimal places) will the fund first reach N200,000?","options":["2.59 years","2.08 years","3.08 years","2.95 years"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"For t of at least 1, the equation is 80,000(1.09)^t + 80,000(1.09)^(t-1) = 200,000, so (1.09)^t = 200,000/(80,000 + 73,394.50) and t = 3.08 years. Option A assumes both deposits are made now, option B measures the time from the second deposit instead of from now, and option D divides by 0.09 instead of ln(1.09)."}},{"itemId":"d15e59d9-bcd6-579d-92ed-92286cd3a3d3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9c1a35c6-8e32-5037-a47e-2bf4b0c42ccb","sourceKey":"bank:ACS101:PAV-040","parentItemId":null,"revision":1,"payload":{"prompt":"Using SIMPLE interest at 10% per annum (so N1 at time 0 grows to 1 + 0.1t at time t), find the present value at time 0 of N11,000 due at time 1 year and N12,000 due at time 2 years, to the nearest naira.","options":["N20,000","N23,000","N19,167","N19,917"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Under simple interest each payment is divided by (1 + it): 11,000/1.1 + 12,000/1.2 = 10,000 + 10,000 = N20,000. Option D switches to compound discounting for the second payment, option C discounts the total for 2 years, and option B ignores discounting."}},{"itemId":"1761c1d8-5a5c-57ea-a84e-9185c3116e6f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d70aa362-ff5d-5da7-9a6e-303fc2a7c5ce","sourceKey":"bank:ACS101:PAV-041","parentItemId":null,"revision":1,"payload":{"prompt":"A rental contract pays N100,000 at the end of year 1, and each later annual payment is 5% more than the one before, with 3 payments in all (at the ends of years 1, 2 and 3). At 10% per annum effective compound interest, what is the present value, to the nearest naira?","options":["N272,727","N248,685","N285,714","N260,518"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"The payments are 100,000, 105,000 and 110,250, so PV = 100,000(1.1)^-1 + 105,000(1.1)^-2 + 110,250(1.1)^-3 = N260,518. Option B ignores the 5% growth, option A grows the payments at 10% instead of 5% (the PV then equals 3 x 100,000/1.1), and option C discounts at the growth rate instead of the interest rate."}},{"itemId":"53a6b94c-23a8-544b-8aea-733fca0c0144","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f156d000-6a39-582f-98e2-20edb1fc5eb7","sourceKey":"bank:ACS101:PAV-042","parentItemId":null,"revision":1,"payload":{"prompt":"A seller of land in Abuja is offered either N1,000,000 now or N620,000 at the end of each of the next 2 years. At 14% per annum effective compound interest, which offer is better and what is the present value of the instalment offer?","options":["Lump sum; PV of instalments about N954,140","Instalments; PV about N1,020,930","Lump sum; PV of instalments about N543,860","Instalments; PV about N1,240,000"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV of the instalments = 620,000(1.14)^-1 + 620,000(1.14)^-2 = N1,020,930, which exceeds N1,000,000, so the instalments are better. Option A discounts the whole N1,240,000 for 2 years, option D ignores discounting, and option C counts only the first instalment."}},{"itemId":"e0cd8955-7e74-5c8e-a621-be06db199eaf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"510774ba-9de7-5cfd-a82f-8b40cdc1e955","sourceKey":"bank:ACS101:PAV-043","parentItemId":null,"revision":1,"payload":{"prompt":"N25,000 is paid at the end of every half-year for 2 years (4 payments). Interest is at a nominal rate of 10% per annum convertible half-yearly. What is the present value of the payments, to the nearest naira?","options":["N88,649","N79,247","N107,753","N43,388"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Work per half-year at 5%: PV = 25,000[(1.05)^-1 + (1.05)^-2 + (1.05)^-3 + (1.05)^-4] = 25,000 x a_4| at 5% = N88,649. Option B uses 10% per half-year, option D counts only 2 payments at 10%, and option C is the accumulated value after 2 years."}},{"itemId":"b9f560c5-4830-5ad2-a2d8-f522e761c31d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"61da8b3a-8b99-5d3c-a844-e1aacf9610fa","sourceKey":"bank:ACS101:PAV-044","parentItemId":null,"revision":1,"payload":{"prompt":"N30,000 is payable at the end of years 3, 4 and 5 only. At 8% per annum effective compound interest, what is the present value at time 0, to the nearest naira?","options":["N66,283","N71,445","N61,373","N77,313"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV = 30,000(v^3 + v^4 + v^5) at 8% = N66,283; equivalently 30,000 x a_3| x v^2. Option D values payments at years 1 to 3, forgetting the delay, option C delays them one year too many, and option B discounts the total for 3 years."}},{"itemId":"f77b22b2-65e7-5a65-83f7-cde2c3b14267","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2fb1328f-3dc0-57bd-82c6-a077fae67d5f","sourceKey":"bank:ACS101:PAV-045","parentItemId":null,"revision":1,"payload":{"prompt":"A project costs N500,000 now and returns N200,000, N250,000 and N150,000 at the ends of years 1, 2 and 3. Its NPV is N1,127 at 10% and -N15,363 at 12% (both effective per annum). Which statement about its internal rate of return is correct?","options":["It is exactly 11%","It lies between 10% and 12%","It lies between 12% and 15%","It is below 10%"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"NPV falls as the rate rises; it is positive at 10% and negative at 12%, so the rate giving NPV = 0 must lie between them (about 10.13%). Option D is wrong because NPV is still positive at 10%, option C is wrong because NPV is already negative at 12%, and option A assumes the IRR is exactly the midpoint, which is not guaranteed."}},{"itemId":"a2aded36-190e-5fc7-b0b6-ed8cb6701b83","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6bc80312-1fb4-5413-a58b-badb3bb3a558","sourceKey":"bank:ACS101:PAV-046","parentItemId":null,"revision":1,"payload":{"prompt":"A trader deposits N30,000 now and N40,000 in 6 months' time. Interest is at a nominal rate of 12% per annum convertible monthly. What is the balance at the end of 12 months from now, to the nearest naira?","options":["N76,266","N76,000","N75,932","N78,878"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"The monthly rate is 1%, so the balance is 30,000(1.01)^12 + 40,000(1.01)^6 = N76,266. Option B uses simple interest, option C treats 12% as an effective annual rate, and option D gives the second deposit a full 12 months of interest."}},{"itemId":"61ce768f-7e9c-53e4-9d15-72a456a0afc9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f05e6135-e698-5c86-aac7-ba5a0ca7347f","sourceKey":"bank:ACS101:PAV-047","parentItemId":null,"revision":1,"payload":{"prompt":"A microfinance bank charges 18% per annum effective compound interest. A borrower can repay N150,000, N200,000 and N250,000 at the ends of years 1, 2 and 3. What is the largest loan the bank should grant today, to the nearest naira?","options":["N365,179","N600,000","N422,913","N499,038"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"The loan must equal the present value of the repayments: 150,000(1.18)^-1 + 200,000(1.18)^-2 + 250,000(1.18)^-3 = N422,913. Option B ignores interest, option D treats the repayments as made at the start of each year, and option A discounts the total for 3 years."}},{"itemId":"711e93a8-48a7-57a3-bc72-1efd2df9b222","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a952610a-a97a-5864-ab8b-ef6b2e1f369f","sourceKey":"bank:ACS101:PAV-048","parentItemId":null,"revision":1,"payload":{"prompt":"A franchise pays N5,000 at the end of year 1, N8,000 at the end of year 2, nothing in year 3, N12,000 at the end of year 4 and N15,000 at the end of year 5. At 7% per annum effective compound interest, find the present value to the nearest naira.","options":["N44,194","N31,510","N32,652","N32,899"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"PV = 5,000v + 8,000v^2 + 12,000v^4 + 15,000v^5 at 7% = N31,510. Option D closes the gap and treats the last two payments as due at years 3 and 4, option A is the accumulated value at year 5, and option C discounts the total from year 3."}},{"itemId":"19899930-ce65-5724-b278-17a6062a4914","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fda47d03-8b01-5a76-b89e-7628f98a3078","sourceKey":"bank:ACS101:PAV-049","parentItemId":null,"revision":1,"payload":{"prompt":"An esusu-style savings scheme credits N70,000 at time 1, N50,000 at time 2, N60,000 at time 4 and N90,000 at time 5 (in years). At 9% per annum effective compound interest, what is the accumulated value at time 5, to the nearest naira?","options":["N347,669","N318,962","N330,750","N207,304"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"AV at time 5 = 70,000(1.09)^4 + 50,000(1.09)^3 + 60,000(1.09) + 90,000 = N318,962. Option A is the value one year later at time 6, option D is the value at time 0, and option C uses a rough simple-interest average."}},{"itemId":"df6bc06d-d2b1-5395-afcf-fd0ae2dea098","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fcb2626c-3987-52f8-ab62-547478ec6e8b","sourceKey":"bank:ACS101:PAV-050","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N200,000 made now is repaid by X at the end of year 2 and 2X at the end of year 4. At 5% per annum effective compound interest, find X to the nearest naira.","options":["N75,851","N78,357","N66,667","N115,625"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Equation of value at time 0: X(1.05)^-2 + 2X(1.05)^-4 = 200,000, so X = 200,000/(0.907029 + 1.645405) = N78,357. Option C ignores interest, option D forgets that the second payment is double, and option A doubles the wrong payment."}},{"itemId":"aa7c5c0a-eeac-5db5-bc43-ffdcf61d4691","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bfddea84-63fa-58b2-a921-3520dba0e8cd","sourceKey":"bank:ACS101:PAV-051","parentItemId":null,"revision":1,"payload":{"prompt":"At 6% per annum effective compound interest, Stream P pays N100,000 at times 1 and 4 years and Stream Q pays N95,000 at time 2 and N100,000 at time 3. The present values are N173,549 for P and N168,512 for Q. What is the difference between their values at time 5 (value of P minus value of Q), to the nearest naira?","options":["N3,764","N5,037","N6,549","N6,741"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Under compound interest every payment's value at time 5 is its PV times (1.06)^5, so the difference is (N173,549 - N168,512)(1.06)^5 = N6,741; the ranking never changes with the valuation date. Option B is the difference at time 0, option A discounts instead of accumulating, and option C uses simple interest."}},{"itemId":"78ae9042-1113-5573-a335-a552f1577748","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"107f1490-3093-5f93-9836-0a3dd8490852","sourceKey":"bank:ACS101:PAV-052","parentItemId":null,"revision":1,"payload":{"prompt":"Deposits of N100,000 are made at time 0 and at time 1 year, and the balance at time 2 years is exactly N215,250. Which effective annual rate of compound interest was earned?","options":["5%","10.5%","7.625%","3.8%"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"At 5%, 100,000(1.05)^2 + 100,000(1.05) = 110,250 + 105,000 = 215,250, which matches the balance. Option C divides the N15,250 interest by the N200,000 deposited and spreads it over 1 year, ignoring that the deposits are invested for different lengths of time, and the other rates do not satisfy the equation of value."}},{"itemId":"1fc94ed1-020d-55e5-b897-e9e9b2570bf5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5acfd51e-e514-5cb8-834a-8427d5959899","sourceKey":"bank:ACS101:PAV-053","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is deposited at time 0 and N100,000 at time 1 year. By how much is the balance at time 3 years HIGHER at 10% per annum effective than at 5% per annum effective, to the nearest naira?","options":["N28,088","N17,338","N4,329","N30,000"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"At 5% the balance is 100,000[(1.05)^3 + (1.05)^2] = N226,012; at 10% it is 100,000[(1.1)^3 + (1.1)^2] = N254,100; the difference is N28,088. A higher rate raises accumulated values, unlike present values. Option B compares only the first deposit, option D is simple interest of 5% on the total for 3 years, and option C is the fall in present value, which is a different quantity."}},{"itemId":"24e7266a-eaed-5971-a012-5c3dd1d2d909","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"412e042f-3a55-59a2-ab20-2382057b44b8","sourceKey":"bank:ACS101:PAV-054","parentItemId":null,"revision":1,"payload":{"prompt":"Using an effective rate of DISCOUNT of d = 8% per annum (so that v = 1 - d), find the present value of N50,000 due at the end of year 1 and N50,000 due at the end of year 2, to the nearest naira.","options":["N89,163","N84,640","N88,320","N88,296"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"With v = 1 - d = 0.92, PV = 50,000(0.92) + 50,000(0.92)^2 = 46,000 + 42,320 = N88,320. Option A treats 8% as a rate of interest, which gives a higher value because v = 1/1.08 = 0.9259. Option B discounts the total for 2 years, and option D mixes compound and simple discounting."}},{"itemId":"454dca65-f8e5-55a1-b840-7a0fa4868bd3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"156ea739-961b-59ce-ac86-09aa5dd23995","sourceKey":"bank:ACS101:PAV-055","parentItemId":null,"revision":1,"payload":{"prompt":"The single value at time 0 obtained by discounting every payment in a series to time 0 at a given rate of interest and adding the results is called the","options":["accumulated value of the payment stream","nominal value of the payment stream","internal rate of return of the payments","present value of the payment stream"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Discounting each payment back to time 0 with v^t and summing gives the present value of the stream. Option A, the accumulated value, is found by rolling every payment forward to a later date. Option C is a rate of interest, not an amount of money."}},{"itemId":"b10732bf-e384-597a-8f1e-fb4d7b43eaa7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5edc4581-c9c9-5775-aec7-3fa8a6733e07","sourceKey":"bank:ACS101:PAV-056","parentItemId":null,"revision":1,"payload":{"prompt":"The accumulated value of a series of payments at time n means","options":["the total of all payments discounted back to time 0","the total of all payments rolled forward with interest to time n","the interest earned on the last payment only","the simple sum of the payments with no interest added"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"The accumulated (future) value at time n is found by multiplying each payment by (1 + i)^(n - t) and adding, so every payment carries the interest it earns up to time n. Option A describes the present value, and option D ignores the time value of money completely."}},{"itemId":"0952bc11-40b0-5d13-a22f-ae813b6d13d8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"aa91db41-c85d-5321-a1b5-287110c90554","sourceKey":"bank:ACS101:PAV-057","parentItemId":null,"revision":1,"payload":{"prompt":"An equation stating that, at a chosen date, the total value of the money paid out equals the total value of the money received, using a given rate of interest, is called","options":["a discount factor","a nominal rate equation","an equation of value","a life table"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"An equation of value balances the values of incoming and outgoing payments at a common date; it is used to find an unknown payment, time or rate. A discount factor (option A) is just the value v^t of one naira due at time t, and option B relates nominal and effective rates rather than two sets of payments."}},{"itemId":"8cf91fc4-9c37-526f-b14b-1e148fddf764","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"55baa5c6-761a-524f-a747-cbbee58b9eb2","sourceKey":"bank:ACS101:PAV-058","parentItemId":null,"revision":1,"payload":{"prompt":"Under compound interest, an equation of value is set up for two payment streams at time 0 and again at time 5 years. Which statement is correct?","options":["The answers differ unless the rate is zero","Both give the same answer, because every term is multiplied by (1+i)^5","Only the time-0 version is valid","Only a date when a payment falls due can be used"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Moving from time 0 to time 5 multiplies every term on both sides by the same factor (1 + i)^5, so the balance and any unknown solved from it are unchanged; any comparison date works under compound interest. Options C and D wrongly restrict the comparison date, and option A would only be a concern under simple interest."}},{"itemId":"3dd94691-460d-5b21-954a-53c645a55287","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1ffe5bba-ed34-5378-99a0-a1fe98e5838d","sourceKey":"bank:ACS101:PAV-059","parentItemId":null,"revision":1,"payload":{"prompt":"The discount rate at which the net present value of a project's cash flows equals zero is called the","options":["hurdle rate","nominal rate of interest","force of interest","internal rate of return"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"The internal rate of return is the rate that makes the present value of inflows exactly equal to the present value of outflows. The hurdle rate (option A) is the minimum return a project must reach to be accepted, and the force of interest (option C) is a measure of instantaneous growth."}},{"itemId":"f7661354-794d-5670-b06a-67168b05af88","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"687b5e95-53ff-5c0b-b987-8f9ea5c1e9f6","sourceKey":"bank:ACS101:PAV-060","parentItemId":null,"revision":1,"payload":{"prompt":"For a project with cash flows C_t at times t = 0, 1, ..., n (outflows negative), the expression C_0 + C_1 v + C_2 v^2 + ... + C_n v^n measures the","options":["accumulated value of the inflows only","simple payback period","average annual cash flow","net present value of the project"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Multiplying each net cash flow by v^t and adding gives the net present value, which is the PV of inflows minus the PV of outflows. Option A would need factors (1 + i)^(n - t) and only positive flows, and option B is a length of time, not a sum of discounted amounts."}},{"itemId":"65be4a42-2bd3-5007-9316-a334c4d979c2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1e734289-8df2-561e-b9c4-e6a0501e092f","sourceKey":"bank:ACS101:PAV-061","parentItemId":null,"revision":1,"payload":{"prompt":"For a stream of positive payments due at future dates, with a positive effective rate of compound interest, which statement is NOT true?","options":["The present value falls when the rate of interest rises","The present value is less than the simple total of the payments","The present value equals the accumulated value at the last payment date","A naira due later adds less to the present value than a naira due sooner"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"With i > 0 the accumulated value at the last date is the PV multiplied by (1 + i)^n, which is larger than the PV, so the two are not equal. The other statements are true: discounting makes the PV smaller than the plain total (option B), a higher rate shrinks every v^t (option A), and v^t gets smaller as t grows (option D)."}},{"itemId":"6b21e412-18f9-5db4-a842-275e853a5500","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6f7b5653-f08d-54b4-8ded-99e14c9400cf","sourceKey":"bank:ACS101:PAV-062","parentItemId":null,"revision":1,"payload":{"prompt":"If the effective rate of interest used to value a fixed stream of future receipts rises, what happens to the stream's present value?","options":["It rises, because more interest is earned","It falls only for payments due within one year","It is unchanged, since the payments are fixed","It falls, because each discount factor v^t becomes smaller"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Every discount factor v^t = (1 + i)^-t shrinks as i rises, so the present value of a fixed stream falls. Option A confuses present value with accumulated value, which rises with the rate, and option B is wrong because later payments are affected even more strongly."}},{"itemId":"31becdce-39f1-5cd7-8b4a-aba6da0268e9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e0d9d748-79b3-5434-a621-91beb588a62b","sourceKey":"bank:ACS101:PAV-063","parentItemId":null,"revision":1,"payload":{"prompt":"Two streams have the same present value at 8%. Stream X pays mostly in years 1-2; Stream Y pays mostly in years 8-10. If both are revalued at 12% per annum effective, which is true?","options":["Stream Y now has the lower present value","Both still have equal present values","Stream X now has the lower present value","Both present values rise"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"A higher rate cuts the value of distant payments much more than near ones, because v^t is raised to a larger power. So the later-paying Stream Y loses more and ends up with the lower present value. Option B ignores timing, and option D is wrong because a higher rate lowers present values."}},{"itemId":"5de19635-c0d8-5773-b3f5-2a2c702d0847","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"148d15b3-df5d-5498-a14c-37cc6ed3baf0","sourceKey":"bank:ACS101:PAV-064","parentItemId":null,"revision":1,"payload":{"prompt":"A debtor and creditor in Kano agree to replace two debts due at different dates with one payment at a new date, with both sides being equally well off at 10% interest. The calculation they need is","options":["the nominal rate convertible monthly","the sum of the two debts with no interest","a simple average of the two due dates","an equation of value at a chosen comparison date"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"Replacing payments fairly means the new payment must have the same value as the old debts at a common date, which is exactly an equation of value. An average of dates (option C) is only an approximation, and adding the debts with no interest (option B) ignores the time value of money."}},{"itemId":"a8a6f12f-b667-51ba-aa4c-1362cad10385","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"31f2ba67-1a56-547c-9028-628b63295dd2","sourceKey":"bank:ACS101:PAV-065","parentItemId":null,"revision":1,"payload":{"prompt":"The number of years needed to recover an initial outlay from a project's cash flows after each cash flow has been discounted for the time value of money is called the","options":["internal rate of return","hurdle rate","term of an annuity","discounted payback period"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"The discounted payback period counts how long it takes for cumulative discounted cash flows to cover the initial cost. The internal rate of return (option A) is a rate, not a length of time, and the hurdle rate (option B) is the minimum acceptable return."}},{"itemId":"5d9672ab-0625-5e01-98a3-57569884fe7e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6d0f39de-6187-5ba8-a371-49893b3c807a","sourceKey":"bank:ACS101:PQ-001","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary is a business professional who manages ________ related to insurance product design, pensions and other financial corporate planning.","options":["financial risk","equipment","management account","financial account"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"An actuary analyses, measures and manages the financial implications of future risk, so financial risk is what the job is built around. Options B, C and D are not the focus: an actuary does not manage equipment, and management or financial accounts belong to the work of accountants rather than actuaries."}},{"itemId":"c9d756c2-86bf-578d-bcdd-a701c457fe9d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1eac8539-7a84-5d34-9d9e-20d3f05fc9a9","sourceKey":"bank:ACS101:PQ-002","parentItemId":null,"revision":1,"payload":{"prompt":"By applying knowledge of probability, statistics, risk theory and financial principles, an actuary is able to ________ future risk with respect to insurance, annuity and pension programmes.","options":["initiate","decide","quantify","digitalize"],"correctOption":2,"section":"Nature of Actuarial Science and the Actuary","explanation":"To quantify a risk means to put a number on it, such as the expected cost of claims or the probability of death, and that measurement is the core of actuarial work. Option B (decide) does not fit because the tools measure the risk rather than decide it, while A (initiate) and D (digitalize) have nothing to do with measuring uncertainty."}},{"itemId":"44cfbe31-87ea-5a3d-9398-ccf6bfe88852","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f72b5466-250b-50f8-8bff-9f8a7d0eb95e","sourceKey":"bank:ACS101:PQ-003","parentItemId":null,"revision":1,"payload":{"prompt":"Actuarial science deals with evaluating risks and maintaining the ________ of insurance or financial organisations.","options":["economic stability","advertising budget","office buildings","staff uniforms"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarial science evaluates risks so that insurers and other financial organisations stay financially sound, which is what maintaining their economic stability means. Options B, C and D are everyday business matters that have nothing to do with measuring and managing financial risk."}},{"itemId":"119f1748-35c1-573a-b1f2-2f89e21fe1f5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"429e665b-faf7-569c-a568-a1ad53110aba","sourceKey":"bank:ACS101:PQ-004","parentItemId":null,"revision":1,"payload":{"prompt":"Actuarial studies graduates learn how to use mathematics, statistics and probability principles to anticipate future events and take ________ measures.","options":["subjective","preventive","retroactive","adjective"],"correctOption":1,"section":"Nature of Actuarial Science and the Actuary","explanation":"Preventive measures are steps taken in advance to reduce the chance or the impact of an unwanted event, which is exactly why actuaries try to anticipate the future. Option C (retroactive) means acting on something that has already happened, which is the opposite idea, and A and D do not describe any kind of measure here."}},{"itemId":"a6fed24f-8c28-5ea9-9648-d8369f7fd9b2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cab42560-79d3-5a1c-a154-d2132223814f","sourceKey":"bank:ACS101:PQ-005","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary serves as the analytical ________ of society's financial security programmes, such as insurance, social security and pensions.","options":["backbone","legislator","customer","competitor"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Calling the actuary the analytical backbone means that these programmes rely on actuarial calculations to set premiums, contributions and reserves so they can keep their promises. Option B is wrong because laws are made by legislatures, not actuaries, and options C and D describe outsiders rather than the people whose analysis supports the programmes."}},{"itemId":"08cc877b-3e41-55e4-ae33-1f4db62bbff9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d57b852c-5ef8-5d63-9ba6-e1be37334ff0","sourceKey":"bank:ACS101:PQ-006","parentItemId":null,"revision":1,"payload":{"prompt":"Actuarial studies graduates learn how to use each of the following to anticipate future events and take preventive measures EXCEPT","options":["Mathematics","Statistics","Probability","Fine Art"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Fine art is a creative discipline and is not one of the quantitative tools an actuary uses to forecast and measure risk. Mathematics, statistics and probability (options A, B and C) are the core subjects that let actuaries estimate how likely and how costly future events will be."}},{"itemId":"3d6cb7d0-d5cc-5575-83c9-efd1cdc6acea","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3b39947-9896-5b74-9358-692e0e0f1dca","sourceKey":"bank:ACS101:PQ-007","parentItemId":null,"revision":1,"payload":{"prompt":"Actuaries analyse past data and use that information to determine how much money should be set aside to cover the ________ which could occur in the future.","options":["financial losses","past profits","dividends already paid","share price gains"],"correctOption":0,"section":"Nature of Actuarial Science and the Actuary","explanation":"Money is set aside, as reserves, to meet financial losses such as claims that may arise later, and actuaries estimate how large those losses could be from past experience. Options B, C and D are gains or events that have already happened, so nobody needs to reserve money to cover them."}},{"itemId":"9f2941db-8e36-5547-8160-fab80dcaf716","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a9737f18-1474-5ec9-98b8-c42da4b88416","sourceKey":"bank:ACS101:PQ-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is among the most common industries or areas where actuaries work?","options":["Property (home) and casualty (auto)","Life and annuities","Retirement benefits","All of the above"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries work across insurance (property and casualty as well as life and annuities) and in the employee benefits industry (retirement benefits), so every listed option is a common area. Choosing only A, B or C would leave out other areas that are equally typical, which is why All of the above is the best answer."}},{"itemId":"179e3a1d-b40b-50e7-8885-e7cf7db1df71","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e50e62e1-6062-55de-85a0-620a982b8325","sourceKey":"bank:ACS101:PQ-009","parentItemId":null,"revision":1,"payload":{"prompt":"________ offers several term and permanent insurance products to provide death benefit protection to its customers.","options":["Life Insurance","Annuity","Mutual Funds","Pension"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Life insurance pays a benefit when the insured person dies, and it comes in term (cover for a fixed period) and permanent (lifelong) forms. Option B (annuity) pays income while a person is alive, C (mutual funds) is a pooled investment, and D (pension) provides retirement income rather than death cover."}},{"itemId":"993f47c5-9a27-5684-81fc-8777b85abc31","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a6fde6e2-1b6b-5df6-bbf8-78eee09560c1","sourceKey":"bank:ACS101:PQ-010","parentItemId":null,"revision":1,"payload":{"prompt":"Fixed and variable ________ products allow customers to make a lump-sum payment or a series of payments today in return for periodic payments beginning immediately or in the future.","options":["Life Insurance","Annuity","Mutual Funds","Pension"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"An annuity turns a lump sum or a series of contributions into a stream of regular payments, starting either at once or at a later date. Option D (pension) often uses an annuity to pay benefits, but the product described here, bought with payments today in exchange for periodic income, is the annuity itself; A and C are death cover and pooled investment respectively."}},{"itemId":"2f5c3dd1-33c9-5a32-b6d0-ed1c3e6ddbd6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"eee7cab1-5bd5-5f98-bf77-d0196115ce02","sourceKey":"bank:ACS101:PQ-011","parentItemId":null,"revision":1,"payload":{"prompt":"A ________ pools the assets of multiple investors and purchases securities to achieve a common, pre-defined goal.","options":["Life Insurance","Annuity","Mutual Funds","Pension"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A mutual fund collects money from many investors and buys a portfolio of securities for them, giving each investor diversification they could not easily get alone. Options A, B and D are insurance and retirement-income arrangements, not pooled investment vehicles that buy securities for a stated goal."}},{"itemId":"2fc603e9-19fd-5ae7-93b1-527f1405565b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1ff17e83-bdbb-509b-bd7b-5f57b7f3be50","sourceKey":"bank:ACS101:PQ-012","parentItemId":null,"revision":1,"payload":{"prompt":"A ________ provides steady income, typically in the form of a guaranteed annuity, to a retired or disabled employee under pre-determined legal and/or contractual terms.","options":["Life Insurance","Annuity","Mutual Funds","Pension"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A pension plan is set up for employees and pays them a steady income after retirement or disability under agreed rules. Option B (annuity) is the form the payments often take, but the arrangement for retired or disabled employees is the pension; A and C are death cover and a pooled investment."}},{"itemId":"46f78f49-3d8f-5639-80de-f7fbdfe27c40","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"18723793-af46-51d8-a591-cf2ccc1a5f81","sourceKey":"bank:ACS101:PQ-014","parentItemId":null,"revision":1,"payload":{"prompt":"The role of ________ is to determine the appropriate \"just a little more\" and to validate the expected number and amount of claims to be taken into account when setting the price of insurance.","options":["Valuation Actuaries","Consulting Actuaries","Pricing Actuaries","Pension Actuaries"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Pricing actuaries set the price of an insurance product: they estimate expected claims and then add the extra margin, the \"just a little more\", needed for expenses, profit and safety. Option A (valuation actuaries) work on reserves for policies already sold, while B and D focus on advising clients and on pension schemes rather than setting premiums."}},{"itemId":"61f0e1d2-cd8b-5cca-84c9-087b23d452b9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dceaf5e0-57ae-5506-96c2-a7f9e96512b1","sourceKey":"bank:ACS101:PQ-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which actuaries are mainly responsible for calculating the reserves (liabilities) an insurer must hold to meet future claims on policies it has already sold?","options":["Pricing actuaries","Consulting actuaries","Pension actuaries","Valuation actuaries"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Valuation actuaries measure an insurer's liabilities, working out how much money must be held in reserve today to pay future claims on existing policies. Option A (pricing actuaries) deal with setting premiums for products before they are sold, while consulting and pension actuaries mainly advise clients and pension schemes."}},{"itemId":"34dd06c2-03ae-55a8-a153-043d0afd2b30","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2bbd9e9c-5e73-5392-a83e-42397ecafe3f","sourceKey":"bank:ACS101:PQ-016","parentItemId":null,"revision":1,"payload":{"prompt":"________ look at the ages and salaries of all members of a pension plan, and project how much each would receive at retirement on average, allowing for future events such as some members leaving before retirement and some getting salary increases.","options":["Valuation Actuaries","Consulting Actuaries","Pricing Actuaries","Pension Actuaries"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Pension actuaries work on retirement schemes, projecting each member's benefit from age, salary and expected events such as withdrawals and pay rises. Option A (valuation actuaries) is more general reserve work for insurers, and C (pricing actuaries) set insurance premiums, so neither describes this pension-plan projection."}},{"itemId":"d9522673-8796-527b-b329-14cc7f1a3f40","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2df23092-d86b-5d74-a35c-f26c96344f20","sourceKey":"bank:ACS101:PQ-017","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i = 3.5% per annum, what is the value of (1 + i)^10? (Give your answer to 3 decimal places.)","options":["1.381","1.411","1.488","1.451"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"(1 + i)^10 = 1.035^10 = 1.4106, which rounds to 1.411; it is the amount that 1 grows to after 10 years at compound interest. Options A, C and D do not equal 1.035^10; a quick check is that 1.035^5 = 1.1877, and squaring that gives 1.411."}},{"itemId":"4b12304c-2e74-54ac-a1d6-c7b593d04501","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"35957a36-690f-5cd5-8b12-43c6b767b609","sourceKey":"bank:ACS101:PQ-018","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i = 3.5% per annum, what is the value of v^5, where v = 1/(1 + i)? (Give your answer to 3 decimal places.)","options":["1.855","0.851","0.842","0.882"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"v^5 = 1/1.035^5 = 1/1.18769 = 0.842, the present value of 1 due in 5 years. Option A (1.855) cannot be right because a discount factor is always less than 1, and B (0.851) and D (0.882) are not equal to 1.035 raised to the power -5."}},{"itemId":"591851bd-a22a-5952-9d5b-69f1daddbf71","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2145b1b8-fd59-59f0-82d9-a2ccf775e5ef","sourceKey":"bank:ACS101:PQ-019","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i = 3% per annum, what is the value of a_12| (the present value of an annuity-immediate of 1 per year for 12 years)? (3 decimal places.)","options":["9.954","10.257","14.192","10.959"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"a_12| = (1 - v^12)/i = (1 - 1.03^-12)/0.03 = 9.954. Option C (14.192) is s_12|, the accumulated value at the end of the term rather than the present value, and B and D do not match the formula."}},{"itemId":"a1ea8899-4af9-5d09-ab59-dd7921ce941d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"47224eec-74d6-5a20-98ce-f6e44ca149bd","sourceKey":"bank:ACS101:PQ-020","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i = 3% per annum, what is the value of s_12| (the accumulated value of an annuity-immediate of 1 per year for 12 years)? (3 decimal places.)","options":["9.954","14.192","9.268","10.959"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"s_12| = ((1 + i)^12 - 1)/i = (1.03^12 - 1)/0.03 = 14.192. Option A (9.954) is a_12|, the present value at the start, and it must be smaller than s_12| because it is not accumulated with interest; C and D do not fit the formula."}},{"itemId":"c82043c2-3724-57ff-9a05-7efa641dccd8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"debe4650-f579-5101-9674-963d6e196bd6","sourceKey":"bank:ACS101:PQ-021","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i = 2.5% per annum, what is the effective rate of discount d? (Rounded to 2 decimal places.)","options":["2.50%","2.45%","2.44%","2%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The effective rate of discount is d = i/(1 + i) = 0.025/1.025 = 0.02439, which is 2.44%. Option A (2.50%) simply repeats the interest rate, but d is always smaller than i because it is interest measured against the end-of-year amount, and B and D are not equal to i/(1 + i)."}},{"itemId":"8f56074f-5cc9-5503-93aa-301f2e28f8ae","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2d535d5a-1854-5205-a3d6-d5701c2930db","sourceKey":"bank:ACS101:PQ-022","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N5,000 is invested at a nominal rate of 6% per annum. Find the amount after 10 years if the interest is compounded annually. (Answer to the nearest kobo.)","options":["N9,030.56","N9,070.09","N9,096.98","N8,954.24"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding annually gives 5,000 x 1.06^10 = N8,954.24. Option A (N9,030.56) is the amount for compounding semi-annually, so it uses the wrong number of conversions per year; remember that the more often interest is compounded, the larger the final amount."}},{"itemId":"c1f6d4ad-247b-58c4-9e54-281147ce1e27","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"85442e97-d7ac-532b-b1e6-55577dc98163","sourceKey":"bank:ACS101:PQ-023","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N5,000 is invested at a nominal rate of 6% per annum. Find the amount after 10 years if the interest is compounded semi-annually. (Answer to the nearest kobo.)","options":["N8,954.24","N9,070.09","N9,030.56","N9,096.98"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding semi-annually gives 5,000 x 1.03^20 = N9,030.56. Option A (N8,954.24) is the amount for compounding annually, so it uses the wrong number of conversions per year; remember that the more often interest is compounded, the larger the final amount."}},{"itemId":"862b87a0-78e2-567e-9f62-1c98e21f58fa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bd3f4490-5779-5188-b6f2-b4fa01ab283f","sourceKey":"bank:ACS101:PQ-024","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N5,000 is invested at a nominal rate of 6% per annum. Find the amount after 10 years if the interest is compounded quarterly. (Answer to the nearest kobo.)","options":["N9,030.56","N9,070.09","N9,096.98","N8,954.24"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding quarterly gives 5,000 x 1.015^40 = N9,070.09. Option A (N9,030.56) is the amount for compounding semi-annually, so it uses the wrong number of conversions per year; remember that the more often interest is compounded, the larger the final amount."}},{"itemId":"c89adeef-5df8-54a5-b0eb-2daca9497c6b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b8da31d9-4624-52d1-bac2-292e939c82fd","sourceKey":"bank:ACS101:PQ-025","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N5,000 is invested at a nominal rate of 6% per annum. Find the amount after 10 years if the interest is compounded monthly. (Answer to the nearest kobo.)","options":["N9,070.09","N9,096.98","N9,110.14","N9,030.56"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding monthly gives 5,000 x 1.005^120 = N9,096.98. Option A (N9,070.09) is the amount for compounding quarterly, so it uses the wrong number of conversions per year; remember that the more often interest is compounded, the larger the final amount."}},{"itemId":"6d517ca9-013e-57ed-9724-6831ed338ee8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2d34ba09-7bc0-50f2-8eae-9f9ebc139ddf","sourceKey":"bank:ACS101:PQ-026","parentItemId":null,"revision":1,"payload":{"prompt":"A principal of N5,000 is invested at a nominal rate of 6% per annum. Find the amount after 10 years if the interest is compounded daily (365 days a year). (Answer to the nearest kobo.)","options":["N9,110.14","N9,096.98","N9,070.09","N9,030.56"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding daily gives 5,000 x (1 + 0.06/365)^3650 = N9,110.14. Option B (N9,096.98) is the amount for compounding monthly, so it uses the wrong number of conversions per year; remember that the more often interest is compounded, the larger the final amount."}},{"itemId":"14012ad5-e2ff-5a68-b958-827fe13df9e6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"460b2a75-902a-5f18-936a-b2644ae01ad2","sourceKey":"bank:ACS101:PQ-027","parentItemId":null,"revision":1,"payload":{"prompt":"Ade invests N4,600 for eight years. The investment earns 5% per annum simple interest. How much interest will Ade earn on the investment?","options":["N6,440","N1,840","N4,600","N2,196.30"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Simple interest is I = P x r x t = 4,600 x 0.05 x 8 = N1,840. Option A (N6,440) is the total accumulated amount, principal plus interest, not the interest alone, and option D (N2,196.30) is the interest Ade would earn under compound interest instead."}},{"itemId":"8c4cba70-025c-557d-ad4f-56c651311a65","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5b64d4d7-b1fa-559b-aea2-1d919de87a5e","sourceKey":"bank:ACS101:PQ-028","parentItemId":null,"revision":1,"payload":{"prompt":"A sum of money amounts to N1,352 in two years at 4% per annum compound interest. What is the sum invested?","options":["N1,300.00","N1,246.00","N1,251.85","N1,250.00"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Discount the amount back two years: 1,352/1.04^2 = 1,352/1.0816 = N1,250.00 (check: 1,250 x 1.0816 = 1,352). Option A (N1,300.00) discounts for only one year, and option C (N1,251.85) treats the growth as simple interest, dividing by 1.08 instead of 1.04^2."}},{"itemId":"94d38233-8f79-5ceb-891e-6039a936b4be","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"098cdbfd-9a2e-5d41-ae28-b5012b722882","sourceKey":"bank:ACS101:PQ-029","parentItemId":null,"revision":1,"payload":{"prompt":"Under simple interest, the amount of interest earned on an investment each year","options":["increases every year","stays the same every year","decreases every year","doubles every year"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Simple interest is always calculated on the original principal only, so each year earns the same amount, P x r, giving a constant annual return. Option A describes compound interest, where interest is earned on earlier interest as well, and options C and D do not happen under either method."}},{"itemId":"9875ea4e-9dca-5b79-9ef1-e02dc1c35171","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"976a5f93-6bc4-58b0-b3e0-34104b281648","sourceKey":"bank:ACS101:PQ-030","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N1,000 is invested at a rate of simple discount of 8% per annum. How much has this accumulated to at the end of one year?","options":["N1,080.00","N1,096.80","N1,086.96","N1,068.90"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Under simple discount, 1 accumulates to 1/(1 - dt), so the amount is 1,000/(1 - 0.08) = 1,000/0.92 = N1,086.96. Option A (N1,080.00) treats 8% as a simple interest rate, which gives a smaller figure because a discount rate of 8% is equivalent to an interest rate above 8%."}},{"itemId":"c6560d95-1dd3-5bc9-9382-ee29ea8be47b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"df67054d-48de-58d7-9284-54035b1d824c","sourceKey":"bank:ACS101:PQ-031","parentItemId":null,"revision":1,"payload":{"prompt":"At the same rate, compound interest will give a lower future value than simple interest when the period of investment is","options":["One year","Greater than one year","Less than one year","None of the above"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"For 0 < t < 1, (1 + i)^t is less than 1 + it, so compound interest grows more slowly than simple interest over periods shorter than a year. Option A is wrong because at exactly one year both give 1 + i and are equal, and B is the opposite case, where compound interest gives the higher value."}},{"itemId":"f11f71ad-a975-5cad-88ca-16107e58411f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"66b59b7c-2f8f-575e-916f-d67ba2b393a8","sourceKey":"bank:ACS101:PQ-032","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the effective rate of interest is ________","options":["i","i^(m)","d","d^(m)"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The plain letter i stands for the effective rate of interest per unit time, the actual interest earned on 1 over one period. Option B, i^(m), is the nominal rate convertible m times a year, while C and D are discount rates rather than interest rates."}},{"itemId":"1ea23157-623b-5ee8-9f2e-0d2131cebfdb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4f934dae-958e-51d5-a330-80dd293bbf40","sourceKey":"bank:ACS101:PQ-033","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the nominal rate of interest convertible m times a year is ________","options":["i","i^(m)","d","d^(m)"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"i^(m) is the nominal rate of interest payable m-thly, meaning interest of i^(m)/m is added every 1/m of a year. Option A (i) is the effective rate, and C and D are the effective and nominal rates of discount."}},{"itemId":"fd215d17-738e-59c1-b43e-4ff3b5e0a62b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"07f173d3-784c-5359-8664-a3b878b5b35c","sourceKey":"bank:ACS101:PQ-034","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the effective rate of discount is ________","options":["i","i^(m)","d","d^(m)"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"d is the effective rate of discount, interest measured against the amount at the end of the period, with d = i/(1 + i). Option D, d^(m), is the nominal rate of discount convertible m times a year, and A and B are interest rates."}},{"itemId":"1246766d-3064-5559-8de9-eec2c6e0b1b5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"872beaa8-5542-5325-8468-aadd8b9f624f","sourceKey":"bank:ACS101:PQ-035","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the nominal rate of discount convertible m times a year is ________","options":["i","i^(m)","d","d^(m)"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"d^(m) is the nominal rate of discount payable m-thly, the discount version of i^(m). Option C (d) is the effective annual rate of discount, while A and B are rates of interest."}},{"itemId":"8f9d0d3d-54e5-5d96-af90-c724f96937cf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7bfd48cf-9741-5f75-afde-d5719f5797ea","sourceKey":"bank:ACS101:PQ-036","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of an ordinary annuity (annuity-immediate, payments at the end of each period) for n periods is ________","options":["a_n|","a-double-dot_n| (a with two dots)","a-bar_n| (a with a bar)","A_n|"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"The plain a_n| is the present value of an annuity-immediate, with payments of 1 at the end of each of n periods. Option B (two dots) is the annuity-due, paid at the start of each period, and C (bar) is the continuous annuity."}},{"itemId":"81031515-92cb-5d01-8f6d-e1c6dc37b9a2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d518ab0e-6785-5b4b-b1cd-6935b86e43c0","sourceKey":"bank:ACS101:PQ-037","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of a continuous annuity (payable continuously) for n periods is ________","options":["a_n|","a-double-dot_n| (a with two dots)","a-bar_n| (a with a bar)","A_n|"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The bar over the a, written a-bar_n|, shows that payments are made continuously at a rate of 1 per period. Option A is the annuity-immediate (end-of-period payments) and B, with two dots, is the annuity-due (start-of-period payments)."}},{"itemId":"0679712a-65e1-5b10-8e98-3483b4a92dc6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"eb4a918e-97a0-5568-b2ce-bc3608b35504","sourceKey":"bank:ACS101:PQ-038","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of an annuity-due for n periods is ________","options":["a_n|","a-double-dot_n| (a with two dots)","a-bar_n| (a with a bar)","A_n|"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"Two dots over the a, written a-double-dot_n|, mark an annuity-due, where each payment of 1 is made at the start of the period. Option A is the annuity-immediate, paid at the end of each period, and C (bar) is the continuously payable annuity."}},{"itemId":"3dc097a9-2e15-55d7-95b0-ad7f4d55714d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a6204f0d-8181-5cb1-9e37-a69d56963c41","sourceKey":"bank:ACS101:PQ-039","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of a whole life assurance on a life aged x is ________","options":["A_x","A_x:n|","A^1_x:n| (a 1 over the x)","a-double-dot_x:n|"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A_x is the present value of 1 paid at the end of the year of death of (x), whenever death happens, which is whole life assurance. Option B adds a term n, making it an endowment assurance, and C, with the 1 over the x, is a term assurance that pays only on death within n years."}},{"itemId":"ebd08643-482c-5408-8df1-2bd9e9815736","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"76cc7029-7a2b-56b0-a4af-804af6af042e","sourceKey":"bank:ACS101:PQ-040","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of an n-year term assurance on a life aged x is ________","options":["A_x","A_x:n|","A^1_x:n| (a 1 over the x)","a-double-dot_x:n|"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A^1_x:n|, with the 1 over the x, means the benefit is paid only if (x) dies before the n-year term ends, which is term assurance. Option A (A_x) pays on death at any time, and B (A_x:n|) also pays if the life survives to the end of the term, which makes it an endowment."}},{"itemId":"218b2e5c-fc23-5d4b-9dd0-7c58e2828411","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3305a3cc-7bd2-5adb-9520-6b74508b5d9d","sourceKey":"bank:ACS101:PQ-041","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of an n-year endowment assurance on a life aged x is ________","options":["A_x","A_x:n|","A^1_x:n| (a 1 over the x)","a-double-dot_x:n|"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A_x:n| pays 1 on death within n years or on survival to the end of the n years, which is an endowment assurance. Option C covers only the death part (term assurance), and A is whole life assurance with no fixed term."}},{"itemId":"5c2bc355-d175-5e74-b9e5-ac42edd5176b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"782a330e-2b19-5a95-a669-333c24ec2a36","sourceKey":"bank:ACS101:PQ-042","parentItemId":null,"revision":1,"payload":{"prompt":"The international actuarial symbol for the present value of an n-year temporary life annuity-due on a life aged x (payments at the start of each year while (x) is alive, for at most n years) is ________","options":["A_x","A_x:n|","A^1_x:n| (a 1 over the x)","a-double-dot_x:n|"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"a-double-dot_x:n| is a life annuity: payments of 1 are made at the start of each year while (x) survives, for at most n years, and the two dots show it is paid in advance. Options A, B and C begin with a capital A, which is the symbol for assurances that pay a lump sum on death or maturity rather than a regular income."}},{"itemId":"9315079c-4a0f-5cad-bb4f-3e29345efd1b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1d88806b-df9f-5e4e-abb0-2be364f2472f","sourceKey":"bank:ACS101:PQ-043","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N3,000 is taken out on 23 June 2007. If the force of interest is 14% per annum, find the value of the loan on 23 June 2012. (Nearest kobo.)","options":["N5,041.26","N6,041.26","N5,100.00","N5,776.24"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With a constant force of interest delta, the amount is 3,000 x e^(delta x t) = 3,000 x e^(0.14 x 5) = 3,000 x e^0.7 = N6,041.26. Option C (N5,100.00) uses simple interest at 14%, and option D (N5,776.24) treats 14% as an effective annual rate, 3,000 x 1.14^5, which is smaller than continuous compounding."}},{"itemId":"bdac6729-edea-551b-a643-fb95114cf122","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b2a4d6df-4423-5112-b2ca-a7f22e85eedc","sourceKey":"bank:ACS101:PQ-044","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate the force of interest per annum which is equivalent to an effective rate of interest of 10% per annum. (5 decimal places.)","options":["0.10000","0.10517","1.09531","0.09531"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The force of interest satisfies e^delta = 1 + i, so delta = ln(1.10) = 0.09531. Option A (0.10000) just repeats the effective rate, but delta is always a little smaller than i, and option B (0.10517) is e^0.1 - 1, the effective rate that a force of 10% would give."}},{"itemId":"ae390353-5bd6-5872-a349-a2c67a4ba421","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b3576b0e-5bf3-5223-b685-23bbf2363878","sourceKey":"bank:ACS101:PQ-045","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N100 is invested now and accumulated for ten years at an effective rate of interest of 5% p.a. for the first three years, 6% p.a. effective for the next three years, and 7% p.a. effective for the remaining four years. Calculate the accumulated amount at the end of the ten-year period. (2 decimal places.)","options":["N168.90","N180.73","N196.72","N179.08"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Accumulate each period in turn: 100 x 1.05^3 x 1.06^3 x 1.07^4 = 100 x 1.157625 x 1.191016 x 1.310796 = N180.73. Option A (N168.90) applies 7% for only three years instead of four, and options C and D wrongly use a single rate (7% or 6%) for all ten years."}},{"itemId":"b27072cd-5550-580d-984c-e8c02248b2a5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"91944ce5-9dd0-5e74-bbe9-3cb17ac57432","sourceKey":"bank:ACS101:PQ-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly describes the payments from a zero-coupon bond?","options":["Regular coupons that rise and fall with an inflation index","Regular fixed coupons plus a redemption payment","No payment is ever made to the holder","A single payment at maturity whose money amount is known in advance"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"A zero-coupon bond pays no coupons at all; the investor buys it at a price below face value and receives one known payment at maturity. Option B describes a fixed-interest security that pays coupons, and option A describes an index-linked security whose payments are not known in advance."}},{"itemId":"3cc1c290-6eb0-5250-a23b-fed3721d3a3b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"edbd77f8-1437-5418-811b-5f73bca10013","sourceKey":"bank:ACS101:PQ-047","parentItemId":null,"revision":1,"payload":{"prompt":"For a fixed-interest security (ignoring the risk of default), are the money amounts of the coupon and redemption payments known in advance?","options":["Yes, the amounts and dates are fixed at issue","No, they depend on an inflation index","Only the first coupon is known in advance","No, they depend on the issuer's profits each year"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"A fixed-interest security pays coupons at a stated rate and a stated redemption amount on stated dates, so the cash amounts are known from the start (provided the issuer does not default). Option B describes an index-linked security, and option D describes something closer to equity dividends, which vary with profits."}},{"itemId":"1759c08b-4166-5579-be01-8912aa17fcfd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"47574be5-8975-5807-9a92-cc0c04604d2e","sourceKey":"bank:ACS101:PQ-048","parentItemId":null,"revision":1,"payload":{"prompt":"For an index-linked security, are the absolute (money) amounts of the payments known in advance?","options":["Yes, they are fixed at issue","Yes, but only for the redemption payment","No, because the security never makes any payments","No, because the payments are adjusted in line with an index such as inflation"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"An index-linked security links its payments to an index, commonly an inflation index, so the money amounts depend on future index values that are not yet known. Option A is true of zero-coupon and fixed-interest securities, not index-linked ones, and the redemption payment is also index-linked, so option B is wrong."}},{"itemId":"def73c07-03ac-5cb4-805b-2f406722326b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"922bb96c-2be6-5649-916d-fdee904b9f1a","sourceKey":"bank:ACS101:PQ-049","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = 1 - x/105, 0 <= x <= 105, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 0 will survive to age 16?","options":["86/107","89/105","62/89","27/105"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The probability of surviving from birth to age 16 is s(16) = 1 - 16/105 = 89/105. Option D (27/105) is the probability of dying between 16 and 43, and C (62/89) is a conditional survival probability for a life already aged 16."}},{"itemId":"1171845f-a2d8-58e3-bf23-5f81d7617bf5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"934b0e67-14d6-53dc-b07c-7b87b2fc9c50","sourceKey":"bank:ACS101:PQ-050","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = 1 - x/105, 0 <= x <= 105, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 0 will survive to age 43?","options":["62/105","89/105","62/89","27/105"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Survival from birth to 43 is s(43) = 1 - 43/105 = 62/105. Option C (62/89) is the probability of reaching 43 given survival to 16, so it uses the wrong starting point, and B (89/105) is survival to age 16 only."}},{"itemId":"b901263d-35fa-575f-b389-43af4fb6d511","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a2828be7-cc36-5d7f-9cd4-477bf7913d01","sourceKey":"bank:ACS101:PQ-051","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = 1 - x/105, 0 <= x <= 105, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 0 will die between ages 16 and 43?","options":["62/105","89/105","62/89","27/105"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Dying between 16 and 43 means surviving to 16 but not to 43, so the probability is s(16) - s(43) = 89/105 - 62/105 = 27/105. Options A and B are the probabilities of surviving to 43 and to 16, not of dying in between."}},{"itemId":"b6cb9e2c-96b2-5da7-9874-73628c7dd16b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3648bb70-59ae-5fed-8464-03abf3fb8f80","sourceKey":"bank:ACS101:PQ-052","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = 1 - x/105, 0 <= x <= 105, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 16 will survive to age 43?","options":["62/105","89/105","62/89","27/105"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"Since the life has already reached 16, divide: s(43)/s(16) = (62/105)/(89/105) = 62/89. Option A (62/105) is the probability measured from birth and ignores the fact that the life has already survived to 16."}},{"itemId":"84e78caa-6ec8-510f-8fd1-c75a8d61177d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4a602ef7-304b-5259-803d-025affca40d8","sourceKey":"bank:ACS101:PQ-053","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = sqrt(100 - x)/10, 0 <= x <= 100, where s(x) is the probability that a newborn survives to age x. What is the probability of surviving from birth to age 64?","options":["3/5","4/5","9/10","5/10"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"s(64) = sqrt(100 - 64)/10 = sqrt(36)/10 = 6/10 = 3/5. Option B (4/5) is s(36), survival to age 36, so it uses the wrong age."}},{"itemId":"485b837f-7005-5a1b-8361-2f9583ead62e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"91988fe3-2706-52a1-8231-903951f2d2ba","sourceKey":"bank:ACS101:PQ-054","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = sqrt(100 - x)/10, 0 <= x <= 100, where s(x) is the probability that a newborn survives to age x. What is the probability of surviving from birth to age 36?","options":["3/5","4/5","9/10","5/10"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"s(36) = sqrt(100 - 36)/10 = sqrt(64)/10 = 8/10 = 4/5. Option A (3/5) is s(64), survival to the older age of 64."}},{"itemId":"03004c5f-43cb-59c4-b15c-414e3852a49f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b1d65f66-2c71-5531-b384-cad4ba92e664","sourceKey":"bank:ACS101:PQ-055","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = sqrt(100 - x)/10, 0 <= x <= 100, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 36 will survive to age 64?","options":["2/10","9/10","3/4","7/10"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"For a life already aged 36, the probability is s(64)/s(36) = (6/10)/(8/10) = 3/4. Option A (2/10) is the difference s(36) - s(64), which is the chance that a newborn dies between 36 and 64, not a conditional survival probability."}},{"itemId":"5c7cba11-7997-586f-b89c-5ae69e49c8e4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6259a593-3a58-5b9a-81dc-727dabb12840","sourceKey":"bank:ACS101:PQ-056","parentItemId":null,"revision":1,"payload":{"prompt":"Use the survival function s(x) = sqrt(100 - x)/10, 0 <= x <= 100, where s(x) is the probability that a newborn survives to age x. What is the probability that a life aged 0 will die between ages 36 and 64?","options":["3/5","4/5","9/10","1/5"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A newborn dies between 36 and 64 if it reaches 36 but not 64, so the probability is s(36) - s(64) = 4/5 - 3/5 = 1/5. Options A and B are the probabilities of surviving to 64 and to 36, not of dying between them."}},{"itemId":"9d9d0e2e-24e6-5d53-9fb2-bb42d6a0ae07","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"76961fb6-f979-5044-b2f4-e0325aca546b","sourceKey":"bank:ACS101:PQ-057","parentItemId":null,"revision":1,"payload":{"prompt":"Use this extract from a hypothetical life table: age x = 0, 1, 2, 3, 4, 5, 6 with l_x = 100,000; 99,499; 98,995; 98,489; 97,980; 97,468; 96,954 and d_x = 501; 504; 506; 509; 512; 514; 517. What is the value of p_4, the probability that a life aged 4 survives one year? (4 decimal places.)","options":["0.9948","0.9848","0.9984","0.9985"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"p_4 = l_5/l_4 = 97,468/97,980 = 0.99477, which rounds to 0.9948. Option C (0.9984) and D (0.9985) swap or misplace digits, and B (0.9848) would imply far more deaths than the 512 shown in the table."}},{"itemId":"4860725c-125c-5084-9f9e-8343e114d950","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4e5ca170-adf7-55f9-8060-7d5f3bba63f7","sourceKey":"bank:ACS101:PQ-058","parentItemId":null,"revision":1,"payload":{"prompt":"Use this extract from a hypothetical life table: age x = 0, 1, 2, 3, 4, 5, 6 with l_x = 100,000; 99,499; 98,995; 98,489; 97,980; 97,468; 96,954 and d_x = 501; 504; 506; 509; 512; 514; 517. What is the value of q_4, the probability that a life aged 4 dies within one year? (5 decimal places.)","options":["0.00525","0.00517","0.00523","0.99477"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"q_4 = d_4/l_4 = 512/97,980 = 0.005226, which rounds to 0.00523. Option A (0.00525) wrongly divides by l_5 instead of l_4, option B (0.00517) uses the age-3 figures, and option D is p_4, the probability of surviving rather than dying."}},{"itemId":"220feeb4-5807-5f93-8af3-af5deea8c066","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ecda7e3c-934c-5c4c-8634-b2fe635a0395","sourceKey":"bank:ACS101:PQ-059","parentItemId":null,"revision":1,"payload":{"prompt":"Use this extract from a hypothetical life table: age x = 0, 1, 2, 3, 4, 5, 6 with l_x = 100,000; 99,499; 98,995; 98,489; 97,980; 97,468; 96,954 and d_x = 501; 504; 506; 509; 512; 514; 517. What is the value of _2p_3, the probability that a life aged 3 survives 2 years to age 5? (4 decimal places.)","options":["0.9986","0.9896","0.9996","0.8996"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"_2p_3 = l_5/l_3 = 97,468/98,489 = 0.98963, which rounds to 0.9896. Options A (0.9986) and C (0.9996) are too close to 1 for two years of survival given more than 1,000 deaths, and D (0.8996) is far too low."}},{"itemId":"f1b3f09e-6b1e-5980-bca5-129883398e2f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0cddb3df-1705-57e2-8eba-ace0e3f7c7d7","sourceKey":"bank:ACS101:PQ-060","parentItemId":null,"revision":1,"payload":{"prompt":"Use this extract from a hypothetical life table: age x = 0, 1, 2, 3, 4, 5, 6 with l_x = 100,000; 99,499; 98,995; 98,489; 97,980; 97,468; 96,954 and d_x = 501; 504; 506; 509; 512; 514; 517. What is the value of _2q_2, the probability that a life aged 2 dies within 2 years? (5 decimal places.)","options":["0.10250","0.00125","0.01025","0.11025"],"correctOption":2,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"_2q_2 = (l_2 - l_4)/l_2 = (98,995 - 97,980)/98,995 = 1,015/98,995 = 0.01025. Option A (0.10250) and B (0.00125) misplace the decimal point, and D (0.11025) is far too large for a two-year death probability when only about 1,000 of nearly 99,000 lives die."}},{"itemId":"f7fcf79c-b627-59c3-be93-81bcaab2d97f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"682f64de-1275-57d5-8ce5-83619e7ee661","sourceKey":"bank:ACS101:PQ-061","parentItemId":null,"revision":1,"payload":{"prompt":"Consider an investment of N100 made for three years at a compound rate of interest of 5% p.a., with interest added at the end of each year. The table shows: Year 1 - principal at start N100, 5% interest at end N5, accumulation at end ?; Year 2 - principal at start ?, interest ?, accumulation ?; Year 3 - principal at start ?, interest ?, accumulation ?. (Round answers to 2 decimal places.) What is the value of this investment at the end of year one?","options":["105","110","106","111"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"At the end of year one the investment is the principal plus one year's interest: 100 + 5 = N105, which is the same as 100 x 1.05. Option B (110) would need 10% interest, and options C and D do not match a 5% rate at all."}},{"itemId":"ed4d770a-3347-598d-afce-22624376f065","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7fc5441d-c07a-5c9d-956b-83b918c8a046","sourceKey":"bank:ACS101:PQ-062","parentItemId":null,"revision":1,"payload":{"prompt":"Consider an investment of N100 made for three years at a compound rate of interest of 5% p.a., with interest added at the end of each year. The table shows: Year 1 - principal at start N100, 5% interest at end N5, accumulation at end ?; Year 2 - principal at start ?, interest ?, accumulation ?; Year 3 - principal at start ?, interest ?, accumulation ?. (Round answers to 2 decimal places.) What is the value of the interest earned at the end of year two?","options":["5","5.25","5.55","5.05"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Under compound interest, year two's interest is earned on the new balance of N105, so it is 105 x 0.05 = N5.25. Option A (5) is the simple-interest answer, which wrongly ignores the interest already added in year one."}},{"itemId":"d3dc73b2-675f-51ea-9018-a9146c787ef9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"075926d7-1674-5556-9470-8ecc51f018a9","sourceKey":"bank:ACS101:PQ-063","parentItemId":null,"revision":1,"payload":{"prompt":"Consider an investment of N100 made for three years at a compound rate of interest of 5% p.a., with interest added at the end of each year. The table shows: Year 1 - principal at start N100, 5% interest at end N5, accumulation at end ?; Year 2 - principal at start ?, interest ?, accumulation ?; Year 3 - principal at start ?, interest ?, accumulation ?. (Round answers to 2 decimal places.) What is the value of this investment at the end of year two?","options":["110","112.25","110.25","115.25"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The balance at the end of year two is 105 + 5.25 = N110.25, or directly 100 x 1.05^2 = 110.25. Option A (110) is what simple interest would give, because it leaves out the interest earned on year one's interest."}},{"itemId":"6aa5f166-8536-56c1-86bb-6852e2314854","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a5dc540e-980d-59a7-8b6a-7fa9607a9c97","sourceKey":"bank:ACS101:PQ-064","parentItemId":null,"revision":1,"payload":{"prompt":"Consider an investment of N100 made for three years at a compound rate of interest of 5% p.a., with interest added at the end of each year. The table shows: Year 1 - principal at start N100, 5% interest at end N5, accumulation at end ?; Year 2 - principal at start ?, interest ?, accumulation ?; Year 3 - principal at start ?, interest ?, accumulation ?. (Round answers to 2 decimal places.) What is the value of the interest earned at the end of year three (to 2 decimal places)?","options":["5.50","5.51","5.52","5.53"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Year three's interest is earned on N110.25, giving 110.25 x 0.05 = 5.5125, which rounds to N5.51. Option A (5.50) is a near miss from rounding too early or using the wrong balance."}},{"itemId":"d1f8428e-9e30-5a1d-91ad-cc7d491cf59d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f757a409-bc98-5d5d-a24a-66e5a5911b98","sourceKey":"bank:ACS101:PQ-065","parentItemId":null,"revision":1,"payload":{"prompt":"Consider an investment of N100 made for three years at a compound rate of interest of 5% p.a., with interest added at the end of each year. The table shows: Year 1 - principal at start N100, 5% interest at end N5, accumulation at end ?; Year 2 - principal at start ?, interest ?, accumulation ?; Year 3 - principal at start ?, interest ?, accumulation ?. (Round answers to 2 decimal places.) What is the accumulation at the end of year three (to 2 decimal places)?","options":["115","115.25","115.51","115.76"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The accumulation after three years is 100 x 1.05^3 = 115.7625, which rounds to N115.76 (that is, 110.25 + 5.5125). Option A (115) is the simple-interest answer, and option C adds the wrong amount of interest to the year-two balance."}},{"itemId":"b4369583-b002-5de9-b26a-17a5d85cabe4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"463691e8-ea7b-55c4-8c30-e215d71e7d8e","sourceKey":"bank:ACS101:PQ-066","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity payable at the start of each period is known as?","options":["Annuity-immediate","Annuity in arrears","Annuity-due","Annuity certain"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"An annuity-due makes each payment at the beginning of the period, like rent paid in advance. Options A and B are two names for the same thing, an annuity whose payments come at the end of each period."}},{"itemId":"eb03dda9-c383-509e-b4db-97c016184f24","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5be7a4be-5347-597d-8a30-16227805a005","sourceKey":"bank:ACS101:PQ-067","parentItemId":null,"revision":1,"payload":{"prompt":"A series of payments which does not begin immediately, or in the first period, but only after a period of postponement is called?","options":["Annuity","Immediate annuity","Deferred annuity","Annuity in advance"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"A deferred annuity is one whose first payment is postponed for some periods, so payments start only after the deferment period. Option B starts paying from the first period, and option D (annuity-due) pays at the start of each period from the outset."}},{"itemId":"b2dead0e-8072-53a9-b327-773902bed17e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"10bcfe06-cc02-542f-a89a-d8d8c8e501ff","sourceKey":"bank:ACS101:PQ-068","parentItemId":null,"revision":1,"payload":{"prompt":"An investor invests N1000 for ten years at 6% p.a. simple interest. Find the accumulated value of this investment.","options":["1628","1600","1650","1628.89"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With simple interest the accumulated value is P(1 + rt) = 1000 x (1 + 0.06 x 10) = N1600, because interest is earned only on the original principal. Option D is a compound-interest style figure, which does not apply here."}},{"itemId":"bdd01739-87ae-5cff-b06d-f33077ad9203","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3b95f04e-8a0c-5121-8a93-d1dc7c50556a","sourceKey":"bank:ACS101:PQ-069","parentItemId":null,"revision":1,"payload":{"prompt":"What is the accumulated value of an investment of N1000 for ten years at 6% p.a. effective (compound) interest? (Round to 2 decimal places.)","options":["1790.85","1060","1628.89","1600"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"At an effective rate the money compounds every year, so the value is 1000 x 1.06^10 = 1000 x 1.790848 = N1790.85. Option D (1600) is the simple-interest answer, and option C is what 5% (not 6%) compound interest would give over ten years."}},{"itemId":"ea7ab886-f746-54f9-8cf9-a25bd484fe0a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"57471234-9d53-566a-9303-cce0c3feeea5","sourceKey":"bank:ACS101:PQ-070","parentItemId":null,"revision":1,"payload":{"prompt":"The nominal rate of interest is 6% p.a. payable half-yearly. What is the accumulated value of N1000 after two years? (Round to 2 decimal places.)","options":["1125.51","1215.51","1521.51","1512.51"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"A nominal 6% payable half-yearly means 3% per half-year, and two years contain four half-years, so the value is 1000 x 1.03^4 = N1125.51. Option B has the right digits in the wrong order, so it overstates the growth."}},{"itemId":"63ee3cbe-d435-5450-9b09-4a7c69f6402e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7233dc80-e07d-5531-bc9c-5e43a651cba6","sourceKey":"bank:ACS101:PQ-078","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'actuary' comes from the Latin word ________","options":["Actuarial","Acturios","Actuarios","Actuarius"],"correctOption":3,"section":"Nature of Actuarial Science and the Actuary","explanation":"Actuarius was the Latin term for a clerk or record keeper who wrote down accounts, and the English word actuary grew from it. Options C and B are misspellings, and option A is an English adjective, not the Latin root."}},{"itemId":"1b0ee0d0-4f05-55ff-b12e-b92b50abba1e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c4396ca1-27a9-58d2-a938-5df2a8908af4","sourceKey":"bank:ACS101:PQ-081","parentItemId":null,"revision":1,"payload":{"prompt":"What does the 'time value of money' imply?","options":["Money should be spent as soon as received","Money available today is worth more than the same amount in the future","Money has a fixed value over time","Money should always be invested in stock"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Money available today is worth more than the same amount later, because today's money can be invested to earn interest. Option C is the very idea the concept rejects, since interest makes a sum grow over time."}},{"itemId":"b10d4a1a-04ed-57d2-8864-8f62cd2fc38e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"83934240-6cb8-56fd-819d-e561d804ed72","sourceKey":"bank:ACS101:PQ-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which factor influences the future value of an investment?","options":["Time","Principal amount","Interest rate","All of the above"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Future value is P(1 + i)^n, so it depends on the principal P, the interest rate i and the time n. Picking a single factor, such as option C, ignores the other two, which change the result just as much."}},{"itemId":"ba1bce83-cd35-5a86-a68b-7f7f52d064bc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6b715ed6-97dc-56cc-b9d2-92aa44930728","sourceKey":"bank:ACS101:PQ-083","parentItemId":null,"revision":1,"payload":{"prompt":"What is the process of determining the present value of future cash flows called?","options":["Compounding","Discounting","Amortization","Accumulation"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Discounting moves money backwards in time, multiplying a future amount by v^n = (1 + i)^-n to get its value today. Options A and D move money forwards in time, finding a future value from a present one."}},{"itemId":"02b90240-544e-5d82-9049-be708ea29b63","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a9913b72-1604-5bd9-a51b-ea36e1939e48","sourceKey":"bank:ACS101:PQ-084","parentItemId":null,"revision":1,"payload":{"prompt":"What is an ordinary annuity?","options":["A series of regular cash flows occurring at the beginning of each period","A series of regular cash flows occurring at the end of each period","A one-time lump sum payment","A series of irregular cash flows"],"correctOption":1,"section":"Annuities and Annuity Functions","explanation":"An ordinary annuity, also called an annuity-immediate or annuity in arrears, pays equal amounts at the end of each period. Option A describes an annuity-due, where each payment is made at the start of the period."}},{"itemId":"5e07981a-f435-5031-9afc-98dbca044a41","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"df6f2621-f7c7-5a9a-82a0-dd9fe70283b3","sourceKey":"bank:ACS101:PQ-085","parentItemId":null,"revision":1,"payload":{"prompt":"What is the formula for calculating the future value of an ordinary annuity of P per period for n periods at rate i?","options":["FV = P[1-(1+i)^-n]/i","FV = P[1-(1+i)^n]/i","FV = P[(1+i)^n - 1]/i","FV = P[(1+i)^-n - 1]/i"],"correctOption":2,"section":"Annuities and Annuity Functions","explanation":"The accumulated value of an ordinary annuity is P[(1 + i)^n - 1]/i, which is P times s_n|. Option A is the present value formula, P times a_n|, which gives the value today rather than at the end."}},{"itemId":"ec74f5ee-0660-50ab-86ca-850cca02026e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dd546faf-51d3-5afb-9298-be6acd1c449c","sourceKey":"bank:ACS101:PQ-086","parentItemId":null,"revision":1,"payload":{"prompt":"Under compound interest at effective rate i per year, which equation correctly gives the present value PV of an amount FV due in n years?","options":["PV = FV x (1 - i)/n","PV = FV/(1 + i)^n","PV = FV/(1 + n x i)","PV = FV x (1 + i)^n"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"To find a present value you discount, dividing the future amount by (1 + i)^n, which is the same as multiplying by v^n. Option D accumulates instead of discounting, so it makes the value bigger, and option C is the simple-interest version, not compound interest."}},{"itemId":"e4fefef8-94f4-586e-b481-0b5e1d839386","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5782f002-9268-5e90-883f-707681ac02dd","sourceKey":"bank:ACS101:PQ-087","parentItemId":null,"revision":1,"payload":{"prompt":"What is the life table used for?","options":["Valuing cash flows","Calculating probabilities of state transitions","Predicting the future value of an investment","Analysing mortality and survival patterns"],"correctOption":3,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"A life table shows how a group of lives shrinks with age, so it is used to analyse mortality and survival patterns, such as the chance of living from one age to the next. Option B is a general description of multi-state models, and option A is done with interest rates and discount factors, not the life table alone."}},{"itemId":"d517380f-1692-5fc3-bd4b-aa1ce4ce326f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b76dac09-d3ea-51cb-bb32-698f1894ce4f","sourceKey":"bank:ACS101:PQ-088","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, what does the l_x column represent?","options":["Number of individuals alive at exact age x","Probability of surviving to age x","Number of individuals who died at age x","Cumulative survival probability up to age x"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"l_x is the number of lives still alive at exact age x out of the starting group. Option B is l_x divided by l_0, a probability rather than a count, and option C is d_x, the number dying between ages x and x+1."}},{"itemId":"a97277cb-3f5e-5b73-967d-c6f249a83373","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"70fab8df-247d-5fc5-8d36-54559948b37e","sourceKey":"bank:ACS101:PQ-089","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_0 = 1,000 and l_1 = 900. What is the probability of surviving from age 0 to age 1, p_0?","options":["0.1","0.9","0.10%","0.9%"],"correctOption":1,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"The survival probability is p_0 = l_1/l_0 = 900/1000 = 0.9. Option A is q_0, the probability of dying in the first year, and option D wrongly treats 0.9 as a percentage, which would be 100 times too small."}},{"itemId":"877a77d2-97a6-522f-8254-de807cd666c3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c004e954-380d-57b9-b765-7f343f86cfed","sourceKey":"bank:ACS101:PQ-089-b","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table, l_0 = 1,000 and l_1 = 900. What is the probability that a life aged 0 dies before reaching age 1, q_0?","options":["0.1","0.9","0.01","100"],"correctOption":0,"section":"Actuarial Symbols, Notations and Life Tables","explanation":"First find d_0 = l_0 - l_1 = 1000 - 900 = 100 deaths, then q_0 = d_0/l_0 = 100/1000 = 0.1. Option B is p_0, the survival probability, and option D is d_0, the number of deaths rather than a probability."}},{"itemId":"d201c1a5-e89e-5f0d-81c0-370b3bfaecbc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"77968d18-58be-5fa6-97c8-9a270fab108e","sourceKey":"bank:ACS101:PQ-092","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary purpose of conducting simulation in the context of life insurance scenarios?","options":["To estimate accumulated value with certainty","To analyse mortality and survival patterns","To model potential outcomes under uncertainty","To calculate the Expected Present Value (EPV)"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Simulation runs many possible futures with random inputs, so its main job is to model the range of potential outcomes under uncertainty. Option A is impossible, since simulation exists because outcomes are uncertain, and option D can be one output of a simulation but is not its main purpose."}},{"itemId":"1fb5b1d7-2db1-5d03-8559-87d2b8889671","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5e86c3dd-d58f-5399-93fe-073888a349c3","sourceKey":"bank:ACS101:PQ-093","parentItemId":null,"revision":1,"payload":{"prompt":"In a single projection simulation, what is the primary limitation of considering only one set of assumptions?","options":["It makes the simulation too complex to analyse","It leads to multiple outcomes with high variability","It may not capture the full range of potential scenarios","It ensures accurate prediction of future events"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A single projection gives one answer from one set of assumptions, so it may miss the full range of scenarios that could actually happen. Option D is the opposite of the truth, and option B describes running many scenarios, not just one."}},{"itemId":"f524a6ed-c21c-567c-af6a-f1bfbfb261ef","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"37695704-0968-55eb-bd97-cb34fc19dda7","sourceKey":"bank:ACS101:PQ-094","parentItemId":null,"revision":1,"payload":{"prompt":"In analysing simulation output, which measure is commonly used to assess the central tendency of the results?","options":["Range","Variance","Standard deviation","Mean"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The mean (average) is the standard measure of central tendency, telling you where the results cluster. Options B and C, like range, measure how spread out the results are, not their centre."}},{"itemId":"ece222e0-c480-5c09-8656-181d0bdc4201","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"247756f4-35bc-58f7-a6c5-bb65b39dca0d","sourceKey":"bank:ACS101:PQ-095","parentItemId":null,"revision":1,"payload":{"prompt":"In life insurance, what are reserves used for?","options":["To compensate policyholders for policy lapse","To pay commissions to insurance agents","To cover future policyholder benefits and claims","To invest in high-return assets"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Reserves are funds an insurer sets aside so it can meet future benefits and claims owed to policyholders. Option D confuses how reserve money may be invested with what it is for, and option B is an expense, not the purpose of reserves."}},{"itemId":"fffd1470-ec0c-5c58-bca0-03f744a7b987","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7be8f56a-bfde-545d-862b-c41e0ce5c7aa","sourceKey":"bank:ACS101:PQ-096","parentItemId":null,"revision":1,"payload":{"prompt":"Why is it important to consider additional scenarios in life insurance analysis?","options":["To determine the single most likely outcome","To understand the range of possible outcomes under different conditions","To reduce the complexity of the analysis","To eliminate uncertainty entirely"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Looking at several scenarios shows the range of possible outcomes under different conditions, which helps an insurer prepare for good and bad experience. Option D is impossible, since scenarios measure uncertainty rather than remove it, and option A is what a single best-estimate projection does."}},{"itemId":"af62abc6-ca91-5da5-9aa2-c6bd94aad79a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"40fbe79f-ad03-5953-af92-73aa73d8e85d","sourceKey":"bank:ACS101:PQ-097","parentItemId":null,"revision":1,"payload":{"prompt":"An investor purchased a three-year index-linked security on 1.1.2001. In return the investor received payments at the end of each year plus a final redemption amount on 1.1.2004, all increased in line with the index below, relative to its value on the purchase date (1.1.2001). Without inflation the payments would have been GBP 1,200 each year and GBP 21,000 on redemption. Index values: 1.1.2000 = 100; 1.1.2001 = 120; 1.1.2002 = 110; 1.1.2003 = 130; 1.1.2004 = 105. Calculate the annual payment actually received by the investor on 1.1.2002.","options":["1100","1200","21000","22200"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Each payment is scaled by the index on the payment date divided by the index at purchase, so 1200 x 110/120 = GBP 1,100. Option B is the unadjusted payment, which ignores that the index fell from 120 to 110."}},{"itemId":"1d9c6f47-56a5-587e-b2f7-d595beb11455","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8eca4119-7630-50f9-8949-b2e2ebdc1c67","sourceKey":"bank:ACS101:PQ-098","parentItemId":null,"revision":1,"payload":{"prompt":"An investor purchased a three-year index-linked security on 1.1.2001. In return the investor received payments at the end of each year plus a final redemption amount on 1.1.2004, all increased in line with the index below, relative to its value on the purchase date (1.1.2001). Without inflation the payments would have been GBP 1,200 each year and GBP 21,000 on redemption. Index values: 1.1.2000 = 100; 1.1.2001 = 120; 1.1.2002 = 110; 1.1.2003 = 130; 1.1.2004 = 105. Calculate the annual payment actually received by the investor on 1.1.2003.","options":["1100","1300","10500","1200"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Scaling by the index gives 1200 x 130/120 = GBP 1,300, since the index rose from 120 at purchase to 130. Option A uses the 1.1.2002 index value, and option D ignores indexation altogether."}},{"itemId":"0f60b3e0-6ff2-54c0-b076-462ad99d0978","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b017db0a-bec5-51a9-bb70-2319fd73dbf8","sourceKey":"bank:ACS101:PQ-099","parentItemId":null,"revision":1,"payload":{"prompt":"An investor purchased a three-year index-linked security on 1.1.2001. In return the investor received payments at the end of each year plus a final redemption amount on 1.1.2004, all increased in line with the index below, relative to its value on the purchase date (1.1.2001). Without inflation the payments would have been GBP 1,200 each year and GBP 21,000 on redemption. Index values: 1.1.2000 = 100; 1.1.2001 = 120; 1.1.2002 = 110; 1.1.2003 = 130; 1.1.2004 = 105. Calculate the annual payment (excluding the redemption amount) actually received by the investor on 1.1.2004.","options":["1300","1100","1200","1050"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"The 1.1.2004 payment is 1200 x 105/120 = GBP 1,050, because the index has fallen to 105 compared with 120 at purchase. Option C ignores indexation, and option A uses the earlier index value of 130."}},{"itemId":"377c5d82-d820-59e9-bd01-d608dd7b7e28","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fd42f72d-57f4-5c5d-ac64-381217582bac","sourceKey":"bank:ACS101:PQ-100","parentItemId":null,"revision":1,"payload":{"prompt":"An investor purchased a three-year index-linked security on 1.1.2001. In return the investor received payments at the end of each year plus a final redemption amount on 1.1.2004, all increased in line with the index below, relative to its value on the purchase date (1.1.2001). Without inflation the payments would have been GBP 1,200 each year and GBP 21,000 on redemption. Index values: 1.1.2000 = 100; 1.1.2001 = 120; 1.1.2002 = 110; 1.1.2003 = 130; 1.1.2004 = 105. Calculate the redemption amount actually received by the investor on 1.1.2004.","options":["22050","21000","19425","18375"],"correctOption":3,"section":"Present and Accumulated Values of Payment Streams","explanation":"The redemption amount is indexed the same way as the annual payments: 21000 x 105/120 = GBP 18,375. Option B ignores indexation, and option C adds the final annual payment of 1,050 to the redemption amount, which is the total received that day rather than the redemption alone."}},{"itemId":"388b9b16-8492-5f0e-8527-be4cb424936c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ac348b5d-42a1-578c-aa44-d091a3c8e2a6","sourceKey":"bank:ACS101:PQ-101","parentItemId":null,"revision":1,"payload":{"prompt":"The table describes whether, for different financial securities, the absolute amount of payments and the timing of payments are known in advance, using letters A - J, each of which is 'yes', 'no' or 'sometimes'. Contract (amount known in advance? / timing known in advance?): Zero-coupon bond (A / J); Fixed-interest security (B / I); Index-linked security (C / H); Call deposit (D / G); Equity (E / F). For the zero-coupon bond, which best describes A (is the absolute amount of payments known in advance)?","options":["yes","no","sometimes","none"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"A zero-coupon bond makes a single payment of a stated amount at maturity, so the amount is known in advance. Option C would suit a security whose payments can change, which is not the case here."}},{"itemId":"b86b8d85-5a39-538b-ae11-1448f86f68e6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1dbad906-de4c-5d9f-8fec-12d72e1bc2ca","sourceKey":"bank:ACS101:PQ-103","parentItemId":null,"revision":1,"payload":{"prompt":"The table describes whether, for different financial securities, the absolute amount of payments and the timing of payments are known in advance, using letters A - J, each of which is 'yes', 'no' or 'sometimes'. Contract (amount known in advance? / timing known in advance?): Zero-coupon bond (A / J); Fixed-interest security (B / I); Index-linked security (C / H); Call deposit (D / G); Equity (E / F). For equity, which best describes E (is the absolute amount of payments known in advance)?","options":["yes","no","sometimes","none"],"correctOption":1,"section":"Present and Accumulated Values of Payment Streams","explanation":"Equity dividends are decided by the company each time, depending on its profits, so the amount is not known in advance. Option A fits bonds with fixed coupons, and option C overstates how much shareholders can rely on a set dividend."}},{"itemId":"f1a02cfc-a227-52e5-a40d-6f04bbf47346","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"522ab88b-55f2-5987-9a5d-e08da1fdcd85","sourceKey":"bank:ACS101:PQ-104","parentItemId":null,"revision":1,"payload":{"prompt":"The table describes whether, for different financial securities, the absolute amount of payments and the timing of payments are known in advance, using letters A - J, each of which is 'yes', 'no' or 'sometimes'. Contract (amount known in advance? / timing known in advance?): Zero-coupon bond (A / J); Fixed-interest security (B / I); Index-linked security (C / H); Call deposit (D / G); Equity (E / F). For the fixed-interest security, which best describes B (is the absolute amount of payments known in advance)?","options":["yes","no","sometimes","none"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"A fixed-interest security pays coupons and a redemption amount that are stated in money terms when it is issued, so the amounts are known in advance. Option B fits an index-linked security, whose payments move with an index."}},{"itemId":"52b9379b-a602-5641-adc2-4774d0f417b5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9e62c3ac-2fc5-512b-8c15-5a8274e46892","sourceKey":"bank:ACS101:PQ-105","parentItemId":null,"revision":1,"payload":{"prompt":"The table describes whether, for different financial securities, the absolute amount of payments and the timing of payments are known in advance, using letters A - J, each of which is 'yes', 'no' or 'sometimes'. Contract (amount known in advance? / timing known in advance?): Zero-coupon bond (A / J); Fixed-interest security (B / I); Index-linked security (C / H); Call deposit (D / G); Equity (E / F). For the fixed-interest security, which best describes I (is the timing of payments known in advance)?","options":["yes","no","sometimes","none"],"correctOption":0,"section":"Present and Accumulated Values of Payment Streams","explanation":"Coupons on a fixed-interest security are paid on set dates and the redemption date is fixed, so the timing is known in advance. Option C would describe a contract where payment dates can vary, such as one the issuer can redeem early."}},{"itemId":"3b8f1013-97d8-5e2a-b064-eba4a4b899dd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7c73021f-edfa-5f68-b6e0-e46a3c076380","sourceKey":"bank:ACS101:PQ-106","parentItemId":null,"revision":1,"payload":{"prompt":"Calculate the future value of USD 15,000 invested for 5 years at 8% p.a. interest compounded annually. (Round to 2 decimal places.)","options":["USD 22,039.92","USD 21,000.00","USD 15,000.00","USD 16,200.00"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compounding annually gives 15000 x 1.08^5 = 15000 x 1.469328 = USD 22,039.92. Option B is the simple-interest answer, 15000 x (1 + 0.08 x 5), and option C ignores interest altogether."}},{"itemId":"9b30c8d6-1f55-5821-870b-663be4a013ca","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"75fb5a84-cf57-5b5e-ad10-1b3c70240986","sourceKey":"bank:ACS101:PQ-107","parentItemId":null,"revision":1,"payload":{"prompt":"Obtain the value of v^5 at 6% (to 5 decimal places), where v = 1/(1 + i).","options":["1.06000","0.74726","0.94340","0.047619"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"v^5 = 1/1.06^5 = 0.74726, the present value of 1 due in five years at 6%. Option C is v for just one year, and option A is 1 + i, an accumulation factor, not a discount factor."}},{"itemId":"8558ee92-f292-5f98-9f12-313f51396af9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b862335c-b899-5f3e-809f-cd9ad4ecc436","sourceKey":"bank:ACS101:PQ-108","parentItemId":null,"revision":1,"payload":{"prompt":"Obtain the value of d, the effective rate of discount, at i = 5% (to 6 decimal places).","options":["0.9524","0.040000","0.047619","3.5460"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The rate of discount is d = i/(1 + i) = 0.05/1.05 = 0.047619. Option A (0.9524) is v = 1/1.05, and option B does not come from any standard formula at 5%."}},{"itemId":"ee9a86b2-0816-570f-a65e-cb86dfbdaddd","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7cf180a3-f774-506a-b3bb-d526e15767b9","sourceKey":"bank:ACS101:PQ-109","parentItemId":null,"revision":1,"payload":{"prompt":"Obtain the value of a_5| at 4% (to 4 decimal places).","options":["0.9524","13.0065","3.5460","4.4518"],"correctOption":3,"section":"Annuities and Annuity Functions","explanation":"a_5| = (1 - v^5)/i = (1 - 1.04^-5)/0.04 = 4.4518, the present value of 1 paid at the end of each year for five years. A five-payment annuity must be worth a bit less than 5, so option C is far too low, and option A is a single discount factor at 5%."}},{"itemId":"38079a6f-938e-5e5e-b088-d3be633fc803","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"455ceed3-28f7-52fb-a5d3-bcca9d0c0f5f","sourceKey":"bank:ACS101:PQ-110","parentItemId":null,"revision":1,"payload":{"prompt":"Obtain the value of (1 + i)^10 at 6% (to 5 decimal places).","options":["1.33823","1.79085","0.9524","13.0065"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The accumulation factor is 1.06^10 = 1.79085, the amount 1 grows to after ten years at 6%. Option A is 1.06^5, which covers only five years."}},{"itemId":"a9ea4cf9-eb47-504c-aa1a-dd30b1b340c3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"03922bf0-0cb3-5b24-9685-78557effff7a","sourceKey":"bank:ACS101:PQ-111","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N1000 is invested for 1 year at a rate of interest of 8% per annum. How much has it accumulated to at the end of the year?","options":["1800","1080","1008","1006"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Over one year, 8% interest adds 1000 x 0.08 = N80, giving N1080 (simple and compound interest agree for a single year). Option C treats 8% as 0.8%, and option A treats it as 80%."}},{"itemId":"e498d642-df7b-5bf6-b338-40799dcc6783","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"42a383a7-7fed-571c-8e6c-b6ff82e87514","sourceKey":"bank:ACS101:PQ-112","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N1000 is invested for five years at a rate of simple interest of 8% per annum. How much has it accumulated to at the end of the five years?","options":["1400","1004","1040","1380"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With simple interest A = P(1 + rt) = 1000 x (1 + 0.08 x 5) = N1400. Option D is not produced by any correct method, and option C treats each year's interest as N8 instead of N80."}},{"itemId":"8e881e79-54a9-56db-8025-8d00f2c2d93f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"142f2080-7c25-517c-8edd-c6bdeda673b7","sourceKey":"bank:ACS101:PQ-114","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N1000 is invested for five years at a rate of simple discount of 8% per annum, so that it accumulates to 1000/(1 - dt). How much has it accumulated to at the end of the five years? (Round to 2 decimal places.)","options":["1666.67","1676.67","1667.67","1767.67"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Using A = P/(1 - dt) gives 1000/(1 - 0.08 x 5) = 1000/0.6 = N1666.67. Option B and the other choices are digit slips around this figure, so check the division carefully."}},{"itemId":"cf7cca38-2644-551d-b3e0-f78ad22edcda","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"59e84ae8-97d8-5fe9-8e43-af4887196d61","sourceKey":"bank:ACS101:PQ-115","parentItemId":null,"revision":1,"payload":{"prompt":"In actuarial and UK usage, a fixed-interest bond is also referred to as (loan) ________","options":["Derivative","Hedge","Stock","Interest"],"correctOption":2,"section":"Present and Accumulated Values of Payment Streams","explanation":"Fixed-interest bonds are often called stocks or loan stocks, as in UK government gilt-edged stock, because the holder owns a slice of a loan that pays fixed coupons. Option A is a contract whose value depends on another asset, and option D is the payment itself, not the security."}},{"itemId":"7e071295-39ca-544a-8def-9c7a0787faf8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"777271dd-8471-5433-a2ae-cb45d066e52f","sourceKey":"bank:ACS101:PQ-116","parentItemId":null,"revision":1,"payload":{"prompt":"An annuity payable for an unlimited term is called?","options":["Perpetuity","Endowment","Life assurance","Term assurance"],"correctOption":0,"section":"Annuities and Annuity Functions","explanation":"A perpetuity has no end date, so its payments go on forever; a perpetuity of 1 paid at the end of each period has present value 1/i. Option B is an insurance contract that pays at the end of a fixed term or on earlier death, so it is limited in time."}},{"itemId":"b7446f3a-3c18-5bb5-923a-fc41bc3c0d29","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"71340d34-5e61-57d0-8a98-40147e05df7d","sourceKey":"bank:ACS101:PQ-117","parentItemId":null,"revision":1,"payload":{"prompt":"The amount of money originally invested, and which attracts interest, is called the?","options":["Share","Principal","Discount factor","Currency"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The principal is the original sum invested, the P in formulas like P(1 + i)^n. Option C is v = 1/(1 + i), a multiplier rather than an amount of money, and option A is a unit of ownership in a company."}},{"itemId":"f70cd05b-1f33-5794-8eee-8a98c1373dab","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8985047c-b65b-5435-b57a-8c3c7b4aa6b5","sourceKey":"bank:ACS101:PQ-118","parentItemId":null,"revision":1,"payload":{"prompt":"We must pay a debt of N10,000 at the end of two years, and may invest money at a rate of simple interest of 7% per annum. How much must we invest now in order to be able to repay the debt? (Round to 2 decimal places.)","options":["8177.93","8717.93","8771.93","8717.39"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With simple interest we need P(1 + 0.07 x 2) = 10000, so P = 10000/1.14 = N8771.93. Option B has the digits mixed up, so it does not repay the debt exactly; compounding is not used here because the rate is simple interest."}},{"itemId":"f570268a-3e80-5b23-8afd-2dfed95c24c8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a6c65afc-3f00-5b9a-9af5-26c5490cb00b","sourceKey":"bank:ACS101:PQ-119","parentItemId":null,"revision":1,"payload":{"prompt":"The term v = (1 + i)^-1 is called the?","options":["Accumulation factor","Discount factor","Decreasing factor","Increasing factor"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"v is the discount factor, the present value of 1 due one period from now. Option A is (1 + i), the reverse operation that grows money forward in time."}},{"itemId":"e573be4d-413a-530c-b359-ece5a5a3857a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7e34304f-84b2-57a9-810b-d15ab5a3d7d0","sourceKey":"bank:ACS101:PQ-120","parentItemId":null,"revision":1,"payload":{"prompt":"How much must be invested now in order to accumulate an amount of N200 at the end of three years, given a compound rate of interest of 5% p.a.? (Round to 2 decimal places.)","options":["177.72","127.77","172.77","172.72"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"We need X x 1.05^3 = 200, so X = 200/1.157625 = N172.77, or 200 x v^3. Option D is a near miss from rounding the discount factor too early."}},{"itemId":"f6dd0ec7-e6f0-55a0-ac69-e721f760c474","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ffcdcdb0-44d0-5f96-a101-b0658ef8e0b3","sourceKey":"bank:ACS101:ROL-001","parentItemId":null,"revision":1,"payload":{"prompt":"Which branch of study deals with evaluating risks and maintaining the economic stability of insurance or financial organisations, using mathematics, statistics and probability to anticipate future events?","options":["Auditing","Insurance brokerage","Actuarial science","Financial accounting"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuarial science uses mathematics, statistics and probability to anticipate future events and keep insurers and other financial organisations economically stable. Option D and option A deal with recording and checking events that have already happened, while option B is about arranging cover between clients and insurers, not measuring the risk itself."}},{"itemId":"fe9d1074-3fa6-529d-82a9-3971a38128fc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b6d6d36a-c02e-5920-b028-1516f526a4c2","sourceKey":"bank:ACS101:ROL-002","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary at a Lagos motor insurer wants to know how many policyholders are likely to have a car accident next November. Which approach best describes what the actuary will do first?","options":["Wait until November ends and then count the accidents that happened","Study the percentage of people involved in accidents in previous years and identify a trend","Ask each policyholder to guess whether they will crash next November","Set the premium equal to last year's premium without looking at any data"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries look at past accident percentages, identify a trend and use it to predict this year's rate, which then tells them how much each person should pay. Option D ignores the data entirely, and option A only counts losses after the fact, which is too late to set a premium."}},{"itemId":"462eea49-fc4e-5454-ae7f-95adabfca392","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7c89299f-176e-5c5e-939a-3e024b0757f0","sourceKey":"bank:ACS101:ROL-003","parentItemId":null,"revision":1,"payload":{"prompt":"Once an actuary has predicted the accident rate for the coming year, the main use of that prediction for a motor insurer is to","options":["audit the insurer's balance sheet for the previous year","decide which car brands should be sold in Nigeria","set the interest rate on the insurer's bank loans","establish how much each person should pay for their insurance so that it covers the damages"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The predicted accident rate is turned into a premium that each policyholder pays so that together the premiums cover expected crash damages. Option A is the accountant's work on past results, and options B and C have nothing to do with pricing cover."}},{"itemId":"0f19344f-ba22-5761-9218-7633ed02ea0f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"eb9a2267-d4a7-5339-bf52-9980d4d314e8","sourceKey":"bank:ACS101:ROL-004","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian insurer plans to launch cover for delivery drones, a product no one in the market has sold before. What is the main challenge the actuary faces in pricing it?","options":["Past data is always too large to analyse","Drone owners cannot be charged a premium","Actuaries are not allowed to price new products","There is little or no relevant past data on which to base the predictions"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries normally use past experience to predict the future, so one of their main difficulties is when there is no past data or the data is no longer relevant. Option C is false because pricing new products is a core actuarial task, and option A reverses the real problem, which is too little data, not too much."}},{"itemId":"fd9b8550-7648-52ab-83b6-5959bea67b3b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6a5a510c-0701-5660-8a2f-3c7badb6cd0f","sourceKey":"bank:ACS101:ROL-005","parentItemId":null,"revision":1,"payload":{"prompt":"Using data from the past to predict the future has been compared to 'driving a car by looking in the rear view mirror'. What extra step does this comparison suggest an actuary must take?","options":["Ignore past data completely","Quantify how the future will be different from the past","Assume the future will be exactly like the past","Use only data from the current month"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The rear-view-mirror picture warns that past data alone is not enough, so the actuary must also measure how conditions will change, such as a big rise in petrol prices affecting motor insurance costs. Option D is the opposite mistake of trusting the past blindly, and option A throws away the actuary's main evidence."}},{"itemId":"4f6d2146-b733-5f82-bcaa-79b771d8484b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d7862993-d17f-5fc5-a3ee-54cc157b1574","sourceKey":"bank:ACS101:ROL-006","parentItemId":null,"revision":1,"payload":{"prompt":"Petrol prices in Nigeria rise sharply and an actuary adjusts the expected cost of motor insurance claims for next year. This is an example of an actuary","options":["auditing the insurer's income statement","quantifying how the future will differ from the past","recording claims that have already been paid","choosing which shares a mutual fund should buy"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Large increases in fuel prices change driving behaviour and repair costs, so the actuary measures how next year will differ from past experience. Option C and option A are backward-looking accounting tasks, and option D is investment selection, not insurance pricing."}},{"itemId":"14baeecf-3665-57a4-b0cb-bbe201c29436","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"967a89ed-5d56-5fcc-8af0-2b7c337533c9","sourceKey":"bank:ACS101:ROL-007","parentItemId":null,"revision":1,"payload":{"prompt":"The process of pricing risk based on probabilities of loss occurrence, used to develop premiums that cover losses from underwritten risks and future benefits, is called","options":["actuarial pricing","reinsurance","claims settlement","underwriting"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuarial pricing turns probabilities of loss into premiums intended to cover losses and future benefits. Option D is deciding whom to accept and on what terms, option B is an insurer buying cover from another insurer, and option C is paying claims after they occur."}},{"itemId":"269365de-cf2c-5600-a774-dd4737566e3d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8f4ed122-2ed1-5878-b720-5a02bd0651bd","sourceKey":"bank:ACS101:ROL-008","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos insurer covers 2,000 commercial motorcycle riders for one year. The probability that a rider makes a claim in the year is 0.03 and the average claim is N400,000. Assuming at most one claim per rider, what is the expected claim cost per rider (before expenses and profit)?","options":["N120,000","N1,200","N24,000,000","N12,000"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Expected loss = probability x amount = 0.03 x 400,000 = N12,000 per rider. Option A uses 0.3 instead of 0.03, option B uses 0.003, and option C is the expected claims for the whole group of 2,000 riders rather than for one rider."}},{"itemId":"3aa91c4f-e9d9-5d1a-8c59-2ad14200c586","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"762b5e9b-640d-5aed-81ac-a23749301006","sourceKey":"bank:ACS101:ROL-009","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer covers 5,000 shops in a Lagos market against fire for one year. Each shop has a probability of 0.004 of a fire claim in the year and the average loss is N2,500,000. Assuming at most one claim per shop, what are the expected total fire claims for the whole group?","options":["N5,000,000","N10,000","N50,000,000","N500,000,000"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Expected loss per shop = 0.004 x 2,500,000 = N10,000, so total expected claims = 5,000 x 10,000 = N50,000,000. Option B stops at the per-shop figure, while options A and D come from misplacing the decimal point in the probability."}},{"itemId":"9aef4d73-d7e0-565d-af91-ca3c2d8b9ee2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2127b6ab-5a4f-5fd2-a2f3-f25b33643ffa","sourceKey":"bank:ACS101:ROL-010","parentItemId":null,"revision":1,"payload":{"prompt":"A motor insurer's expected claim cost for a policy is N15,000. It adds a loading equal to 20% of the expected claim cost to cover expenses and profit. What premium does it charge?","options":["N3,000","N18,000","N18,750","N15,000"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Premium = expected claim cost + loading = 15,000 + 0.20 x 15,000 = N18,000. Option D forgets the loading, option A is the loading alone, and option C wrongly treats the 20% as a share of the premium (15,000 / 0.8) rather than of the claim cost."}},{"itemId":"86b5dd78-9423-51bb-aa61-94fff7ae0c06","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e50c6e9d-6af4-530f-b8cd-d1418ce497aa","sourceKey":"bank:ACS101:ROL-011","parentItemId":null,"revision":1,"payload":{"prompt":"The gross (office) premium for a period of cover is built up from several parts. Which of the following is NOT one of those parts?","options":["Commission and an allowance for other expenses","A profit loading","The policyholder's surrender value","The risk premium"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The gross premium contains the risk premium, commission, an allowance for other expenses, any premium tax and a profit loading. The surrender value is money paid out to a policyholder who stops a life policy, so it is not something added into the premium charged. Options D, A and B are all genuine building blocks of the gross premium."}},{"itemId":"04159f92-57c7-5d63-a92f-1e91c3b3f23a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6ae0331d-e60b-569f-883c-54aa22b4fb44","sourceKey":"bank:ACS101:ROL-013","parentItemId":null,"revision":1,"payload":{"prompt":"Heavy flooding hits parts of Lagos on 29 December. By 31 December, the insurer's year-end, many homeowners with valid flood cover have suffered losses but have not yet reported them. The estimate the insurer sets aside for these losses is the","options":["incurred but not reported (IBNR) reserve","unearned premium reserve","surrender value","deposit premium"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"IBNR is the estimated amount owed to valid claimants who have had a covered loss but have not yet reported it, and because the insurer does not know how many such losses there are it must be estimated, usually by actuaries. Option B relates to cover not yet provided, not losses already incurred, and options C and D are not claims reserves at all."}},{"itemId":"eec12fe9-ab06-556a-8ce2-90530c916e46","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b124b634-ffa9-59c6-80af-59e711555195","sourceKey":"bank:ACS101:ROL-014","parentItemId":null,"revision":1,"payload":{"prompt":"Unearned premium is best described as","options":["premium already paid for which the insurer has not yet provided the cover","premium that the policyholder has failed to pay","the part of a claim the policyholder must pay first","premium returned to a policyholder after a claim-free year"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Unearned premium is premium paid for the period of cover still remaining on the policy, so the insurer holds it as a reserve. Option B describes unpaid premium, which is a different problem, and option C describes a deductible."}},{"itemId":"19bd57bf-5de2-594c-a98e-eaff59ce0aa4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a82089d0-6620-594f-930b-885883432a4b","sourceKey":"bank:ACS101:ROL-015","parentItemId":null,"revision":1,"payload":{"prompt":"A car owner in Ibadan pays an annual motor premium of N120,000 on 1 October 2025 for cover until 30 September 2026. Assuming the premium is earned evenly month by month, what is the unearned premium at the insurer's year-end of 31 December 2025?","options":["N60,000","N120,000","N30,000","N90,000"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"By 31 December, 3 of the 12 months of cover have passed, so 9 months remain: unearned premium = 120,000 x 9/12 = N90,000. Option C is the earned premium for the 3 months already covered, and option B wrongly treats the whole premium as unearned."}},{"itemId":"f3498696-5104-504c-82bf-9e1d72ff64ac","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8c7c4cb1-8625-549a-a838-668ba5b00796","sourceKey":"bank:ACS101:ROL-016","parentItemId":null,"revision":1,"payload":{"prompt":"In 2025 a Nigerian general insurer earned premiums of N72 million and incurred claims of N54 million. Using loss ratio = claims incurred / premiums earned, what is its loss ratio?","options":["133.33%","75%","42.86%","25%"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Loss ratio = 54 / 72 = 0.75 = 75%, meaning 75 kobo of every naira of premium went on claims. Option A divides the wrong way round (72 / 54), option D is the share left over for expenses and profit, and option C divides claims by the sum of claims and premiums."}},{"itemId":"674aaafc-daf0-5e3e-b471-6cbb4f5b00e4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9b253b07-a5b4-5e6d-9a9a-6600fda3b8e0","sourceKey":"bank:ACS101:ROL-017","parentItemId":null,"revision":1,"payload":{"prompt":"An insurance company is said to be solvent when","options":["its liabilities are greater than its assets","it collects more premiums this year than last year","the value of its assets is greater than the sum of its debt obligations","it pays every claim within one week"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Solvency is the ability to meet long-term debts and other commitments, and to be considered solvent an entity's assets must exceed its debt obligations. Option A describes insolvency, while options B and D describe growth and service speed, which do not by themselves show solvency."}},{"itemId":"5dfd13ff-cc7f-5254-9b4d-fed0877f1649","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f4e18cd5-2ccf-533e-af51-2230e4895fa4","sourceKey":"bank:ACS101:ROL-018","parentItemId":null,"revision":1,"payload":{"prompt":"At its year-end a Nigerian insurer has total assets of N8.4 billion and total liabilities of N7.0 billion. Taking the solvency margin as assets minus liabilities, what is its solvency margin?","options":["N15.4 billion","-N1.4 billion","N1.4 billion","N1.2 billion"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Solvency margin = assets - liabilities = 8.4 - 7.0 = N1.4 billion, so the insurer is solvent. Option A adds instead of subtracting, option D is the ratio 8.4 / 7.0 = 1.2 wrongly read as naira, and option B subtracts the wrong way round."}},{"itemId":"32c21e83-87ed-5232-b599-045f930ae5e5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bd105d04-bcac-5807-8581-e6360f79c91c","sourceKey":"bank:ACS101:ROL-019","parentItemId":null,"revision":1,"payload":{"prompt":"The theoretical amount of capital needed to absorb the risks of a business with obligations to customers, so that it has an acceptably low chance of becoming insolvent, is called","options":["risk-based capital","unearned premium","surrender value","gross premium"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Risk-based capital is sized to the risks a business carries so that the chance of insolvency stays acceptably low, and plans for risk-based capital rules are part of insurance regulation in Nigeria. Options B and D are premium amounts, and option C is a payment to a policyholder who cancels a life policy."}},{"itemId":"98af6a3d-8619-5edc-814a-9d7c6d2aee84","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"23023bf6-e405-55fb-9e3a-673c881266a5","sourceKey":"bank:ACS101:ROL-020","parentItemId":null,"revision":1,"payload":{"prompt":"Forming a group of policies with similar characteristics so that the insurer is protected against risk, relying on the law of large numbers, is known as","options":["pooling","underwriting","lapsing","indemnity"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Pooling groups similar policies together, and the law of large numbers means that the larger and more alike the group, the more certain the predictions. Option B is deciding whom to accept, option C is a policy ending through non-payment, and option D is compensation for loss."}},{"itemId":"80e2799d-085c-5c84-a93c-d2c794882e83","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f8fcf93c-0a98-5500-9297-9203c820548f","sourceKey":"bank:ACS101:ROL-021","parentItemId":null,"revision":1,"payload":{"prompt":"Insurer A covers 20 market traders against theft, while Insurer B covers 5,000 traders with similar shops and stock. Other things being equal, why can Insurer B predict its total claims more reliably?","options":["Traders in large groups are always more honest","A larger, more similar group makes predictions more certain (law of large numbers)","Larger groups never make any claims","Small groups are not allowed to buy insurance"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The law of large numbers says that the larger and more homogeneous the insured group, the more certain the predictions, which is the basis of risk pooling. Option C is false because large groups still make claims, just more predictably, and option A confuses statistics with behaviour."}},{"itemId":"55cfe6ec-3421-5c3b-a4bc-ed8d55578f08","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2bf1ae27-ea38-5fac-9657-099e543104eb","sourceKey":"bank:ACS101:ROL-022","parentItemId":null,"revision":1,"payload":{"prompt":"A group of policies with similar characteristics, such as group size and benefit structure, is called a","options":["risk pool","reinsurer","mutual fund","risk subject"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A risk pool is a collection of similar policies whose combined experience is more predictable than any single policy. Option D is the person or object involved in an insured event, option C pools investors' money to buy securities, and option B is an insurer for insurance companies."}},{"itemId":"8d6fffea-e438-5d65-b64a-0a29e72c280f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"313e12b8-3bb5-5471-a71f-600c6b170e83","sourceKey":"bank:ACS101:ROL-023","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which an insurance company decides which people to accept for insurance and on what terms is called","options":["lapsation","reinsurance","underwriting","valuation"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Underwriting is the accept-or-decline and set-the-terms decision made for each applicant, and actuaries support it by building the rating tables underwriters use. Option B is an insurer passing risk to another insurer, option A is policies ending through non-payment, and option D would be placing a value on assets or liabilities."}},{"itemId":"c0640bca-a661-5ab3-a1d2-2267d1071ded","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c9f26b02-2597-5188-920a-c2682494636c","sourceKey":"bank:ACS101:ROL-024","parentItemId":null,"revision":1,"payload":{"prompt":"Before issuing a life policy, an insurer in Abuja considers the applicant's age, health history and occupation to decide the premium. These items are best described as","options":["unearned premiums","underwriting factors","solvency margins","reinsurance treaties"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Underwriting factors are what an insurer considers before issuing a policy and deciding how much the premium should be. Option D is a contract between insurers, option A is premium for cover not yet given, and option C is surplus assets over liabilities."}},{"itemId":"9b35df65-dc46-5027-b2b2-6c61f47864d0","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c96bc58b-8325-5c5f-bd1b-252574bdf4fe","sourceKey":"bank:ACS101:ROL-025","parentItemId":null,"revision":1,"payload":{"prompt":"After a health insurer in Port Harcourt advertises a plan at one flat premium, a much larger share of people with existing illnesses apply than in the general population. This tendency is called","options":["pooling","moral hazard","adverse selection","indemnity"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Adverse selection (antiselection) is the greater tendency of people with above-average likelihood of loss to buy or keep insurance. Option B is about insured people taking more risk because they are covered, which happens after buying, not when choosing to apply, and option A is the grouping of similar risks."}},{"itemId":"93a46e1b-c213-5491-873a-f6547e9764b9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cfd2db9a-0274-56ec-a34e-a3c3cbf25362","sourceKey":"bank:ACS101:ROL-026","parentItemId":null,"revision":1,"payload":{"prompt":"After insuring his car fully, a Lagos driver starts leaving it unlocked on the street because 'the insurer will pay anyway'. This behaviour is an example of","options":["adverse selection","experience rating","a peril","moral hazard"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Moral hazard is the tendency of an insured person to take more risk knowing they will be compensated if the loss happens. Option A concerns who chooses to buy insurance in the first place, and option B is the cause of loss itself, such as theft, not the careless behaviour."}},{"itemId":"272003d9-43b4-5787-90ad-e7f8003df723","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2a5d519d-b702-53f5-b0fc-1d261afe1c02","sourceKey":"bank:ACS101:ROL-027","parentItemId":null,"revision":1,"payload":{"prompt":"A shop owner in Onitsha stores jerrycans of petrol beside electrical wiring, and her shop is insured against fire. In insurance terms, the fire is the ______ and the stored petrol is a ______.","options":["peril; premium","claim; peril","peril; hazard","hazard; peril"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A peril is the cause of loss, such as fire, earthquake or theft, while a hazard is a condition that increases the probability or size of a loss, like petrol stored near wiring. Option D reverses the two terms, and option A confuses a hazard with the price of cover."}},{"itemId":"0693f95d-74b4-5a86-92e5-2b17dbd5a0fa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ada07950-123f-5fdb-a70e-b3e58d87f1e0","sourceKey":"bank:ACS101:ROL-029","parentItemId":null,"revision":1,"payload":{"prompt":"A transaction in which another licensed insurer agrees to cover all or part of a primary insurer's losses in return for a premium is called","options":["indemnity","underwriting","reinsurance","co-payment"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Reinsurance is insurance for insurance companies: the reinsurer takes on part of the primary insurer's risk for a premium. Option D is a fixed amount a patient pays for a health service, option B is the accept-and-price decision, and option A is compensation for loss in general."}},{"itemId":"c11088af-eb5c-5c95-b2a8-646a13f28186","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"605487bb-c565-5bcc-8fa0-1d12be4e732b","sourceKey":"bank:ACS101:ROL-030","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian property insurer worries that one major flood could produce claims far above what it can bear. It buys cover that pays when losses from a single event exceed a set retention. This is","options":["a mutual fund","a defined contribution plan","an unearned premium reserve","catastrophe reinsurance"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Catastrophe reinsurance protects an insurer when losses from a single event such as a flood or earthquake exceed its chosen retention. Option A is an investment vehicle, option B is a pension arrangement, and option C is a reserve for cover not yet provided."}},{"itemId":"c80b8bfd-953e-57b5-82f7-f4e0318130ff","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"365d2d04-2f2b-5223-a704-b9cd00bf0047","sourceKey":"bank:ACS101:ROL-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a way actuaries help insurance companies?","options":["Auditing staff attendance records","Calculating rates for new insurance products","Selling policies door to door","Repairing vehicles after accidents"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries help insurers calculate rates for new products, forecast and interpret underwriting results, and maintain databases suited to pricing analysis. Option C is the job of sales agents, option D is done by mechanics, and option A is an administrative task."}},{"itemId":"ea69b104-f1ab-5f9c-83a8-bc18c13f3f98","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"27b9126a-3dd4-58bc-9856-78944bc22873","sourceKey":"bank:ACS101:ROL-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the ways actuaries help insurance companies?","options":["Deciding the outcome of court cases between policyholders and insurers","Maintaining databases suited to the analysis of pricing issues","Calculating rates for new insurance products","Forecasting and interpreting underwriting results"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries forecast and interpret underwriting results, maintain pricing databases and calculate rates for new products. Deciding court cases is the work of judges, not actuaries. Options D, B and C are all genuine actuarial contributions to insurers."}},{"itemId":"b8c82ce8-32bf-572c-8912-d3da97025033","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"519322bd-00f5-5c9f-97aa-5c6f7aa3153a","sourceKey":"bank:ACS101:ROL-033","parentItemId":null,"revision":1,"payload":{"prompt":"Adjusting a client's premium rates based on the part of their own claims experience that is judged credible is called","options":["adverse selection","moral hazard","experience rating","pay-as-you-go"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Experience rating uses a client's own credible claims history to adjust their premiums; a group with little credible data is priced mainly on manual rates. Option A is about high-risk people seeking cover, option D is a pension funding method, and option B is careless behaviour by the insured."}},{"itemId":"c5d38049-98e9-5155-b113-761fc09270aa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ec75b115-fe76-5321-a2d7-73fb6b0d4bc4","sourceKey":"bank:ACS101:ROL-034","parentItemId":null,"revision":1,"payload":{"prompt":"A large Lagos bank has 10 years of reliable staff health-claims data, while a new 15-person start-up has almost none. In setting each group's health premium, the actuary gives much more weight to the bank's own claims history. The weight given to a group's own data is known as","options":["surrender value","solvency","credibility","indemnity"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Credibility is the relative weight given to one estimate, such as a group's own experience, when combining it with another to get a better estimate. Large groups with long records earn high credibility, while tiny groups rely more on manual rates. Option B is about assets exceeding liabilities and option D is compensation for loss."}},{"itemId":"fb014d94-457c-5056-b7e7-9e22bb0c6173","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6f4b6143-b609-51a5-a0c1-510e5c091f06","sourceKey":"bank:ACS101:ROL-036","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian state government requires every one of its employees to belong to a staff health scheme, while a private club lets members choose whether to join its welfare fund. The state scheme and the club fund are respectively","options":["both mandatory financial security systems","voluntary and mandatory financial security systems","mandatory and voluntary financial security systems","both voluntary financial security systems"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A financial security system is mandatory if everyone in the group must take part, and voluntary otherwise. The state scheme forces all employees to join, so it is mandatory, while the club lets members choose, so it is voluntary. Option B reverses them."}},{"itemId":"9ce8ed52-d89d-52c2-9ae6-8cc5f4c6157d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"72926cbf-17b5-557f-94db-627b14ee87cc","sourceKey":"bank:ACS101:ROL-038","parentItemId":null,"revision":1,"payload":{"prompt":"A general insurance actuary models both how many motor claims will arrive in a year and how large each claim will be. These two are described respectively by the","options":["severity distribution and the frequency distribution","lapse rate and the surrender value","loss ratio and the solvency ratio","frequency distribution and the severity distribution"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Claim frequency describes the number of claims in a period, while the severity distribution is the probability distribution for the amount of each loss. Option A reverses them, and options C and B are business ratios and life-policy terms rather than claim models."}},{"itemId":"0308475b-a465-58c3-ab20-aade9286f4ef","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bca40910-fcaa-538e-aa65-fb1626340777","sourceKey":"bank:ACS101:ROL-039","parentItemId":null,"revision":1,"payload":{"prompt":"An institution that, by a contract, binds itself to indemnify another party against specified loss in return for premiums paid is","options":["a mutual fund","a stock exchange","an insurance company","a pension regulator"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"An insurance company promises to compensate (indemnify) policyholders for specified losses in exchange for premiums. Option A invests pooled money in securities, option B is a market for trading shares, and option D supervises pension schemes rather than selling cover."}},{"itemId":"c8358e3a-025b-55ad-b11e-4c949c7ae07e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"14bd7b98-d18d-55e3-aa04-3ffafdbaa0d5","sourceKey":"bank:ACS101:ROL-040","parentItemId":null,"revision":1,"payload":{"prompt":"A life policy that pays a stated benefit only if the insured dies within a specified period, such as 10 years, is","options":["term life insurance","whole life insurance","property insurance","an annuity"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Term life insurance pays the death benefit only if death occurs within the stated period and is not from an excluded cause. Option B covers death whenever it happens and builds cash value, while option D pays a regular income rather than a death benefit."}},{"itemId":"e98251d5-3da5-5689-8976-dab0bf6f12be","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b41cdf08-5759-51d1-a7bf-2f40ad889c41","sourceKey":"bank:ACS101:ROL-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of features describes whole life insurance?","options":["A set death benefit, level premium and guaranteed cash values","Cover for a fixed number of years with no cash value","A series of payments to the policyholder for a fixed term","Cover against fire and burglary at business premises"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Whole life insurance has a set face amount, level premium and a guaranteed cash value table, with a guaranteed death benefit. Option B describes term insurance, option D is general (property) insurance, and option C describes an annuity certain."}},{"itemId":"a6ab26a8-bf5e-5826-a172-ea6b8319746c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6e2f3eaa-0ace-5e2f-9fd8-d5f9cc4b64f0","sourceKey":"bank:ACS101:ROL-042","parentItemId":null,"revision":1,"payload":{"prompt":"A broad category of non-life, non-health cover against loss of property, damage or other liabilities is","options":["casualty insurance","a defined benefit pension","term life insurance","an annuity"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Casualty insurance is non-life, non-health cover for property loss, damage and liabilities, the work of property and casualty (general insurance) actuaries. Options C and D are life products, and option B is a retirement arrangement."}},{"itemId":"47a4feba-5de1-5c9b-aeed-df81bc4fbd4d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fa300b0c-958c-51d8-b0e8-e26c99de8ac9","sourceKey":"bank:ACS101:ROL-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following Nigerian insurance products belongs to general (non-life) insurance?","options":["Whole life insurance on a trader","A retirement annuity bought by a civil servant","Term life insurance on a bank employee","Motor insurance on a commercial bus"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"General (non-life) insurance includes property and casualty covers such as motor, home and business property. Options A, B and C all depend on a person's life or death, which places them in life insurance and annuities."}},{"itemId":"47ec5041-7b08-56a3-9cb8-7df69941b130","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"358fb6c7-2d72-5d31-ab1a-2feba3d48e33","sourceKey":"bank:ACS101:ROL-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which pair correctly matches the measure to what it describes?","options":["Mortality: the incidence of death; morbidity: the rate of disease","Mortality: the rate of disease; morbidity: the incidence of death","Mortality: the rate of car accidents; morbidity: the rate of fire","Mortality: the rate of policy lapses; morbidity: the rate of claims paid"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Mortality measures death in a population and morbidity measures disease, often as the chance a person becomes seriously ill in a period. Life actuaries focus mainly on mortality, while health actuaries focus heavily on morbidity. Option B swaps the two terms."}},{"itemId":"0706a708-0f62-5b5f-8d30-f27b416606bb","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5f8b70b8-ff50-52fe-88c2-e890bf47120a","sourceKey":"bank:ACS101:ROL-045","parentItemId":null,"revision":1,"payload":{"prompt":"A policyholder in Enugu stops paying the renewal premiums on her life policy and the grace period passes, so the policy terminates. This termination is called a","options":["surrender","claim","reinsurance","lapse"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A lapse is the end of a policy because the owner failed to pay the renewal premium within the grace period. Option A, surrender, is when the owner actively chooses to end the policy and receives its surrender value, and option B is a request for payment after an insured event."}},{"itemId":"d4ab9fca-cb44-5877-bac1-89a505ce8043","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f94b5eec-7633-54b2-b5b2-9274375d4b6f","sourceKey":"bank:ACS101:ROL-046","parentItemId":null,"revision":1,"payload":{"prompt":"The surrender value of a life insurance policy is","options":["the amount the policyholder receives on choosing to stop the policy","the death benefit paid to the beneficiary","the commission paid to the agent who sold the policy","the premium paid in the first year only"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The surrender value is what you receive if you decide you no longer want to continue with a life policy. Option B is paid on death, not on cancelling, and options D and C are costs, not amounts paid to the policyholder."}},{"itemId":"15754445-f070-58d9-a54b-42ba65ce81fc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"eac904e1-f262-5557-b754-77601c87c442","sourceKey":"bank:ACS101:ROL-047","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos company buys a life policy on its founder and managing director, on whom the success of the business depends, with the company as beneficiary. This is","options":["casualty insurance","key person insurance","catastrophe reinsurance","a defined contribution plan"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Key person insurance is life cover on a key employee, partner or owner whose death would hurt the business, with the business as beneficiary. Option C protects insurers against big single events, option A is non-life cover, and option D is a pension arrangement."}},{"itemId":"bf599953-1dd4-53fd-8ad1-9b603b6f168f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3788b21e-6ea7-5ee5-bcf7-24454962f208","sourceKey":"bank:ACS101:ROL-048","parentItemId":null,"revision":1,"payload":{"prompt":"A retiring civil servant in Ibadan pays N10,000,000 to a life insurer in one lump sum and in return receives a fixed payment every month for as long as she lives. What product has she bought?","options":["An annuity","A casualty policy","A reinsurance treaty","A term life policy"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"An annuity turns a lump sum or a series of payments into regular income that starts now or later, and a life annuity keeps paying while the annuitant is alive. Option D pays only on death within a set period, while options C and B cover insurers' or property losses rather than providing an income."}},{"itemId":"bc5d720b-0bd7-50cf-ae0d-6fedda272774","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"880cadd2-afb7-51a7-bcc8-ef8b543a18e8","sourceKey":"bank:ACS101:ROL-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing of a typical actuarial project with its area is correct?","options":["Setting HMO premium rates: life insurance","Pricing the cost of increasing retirement benefits: health benefits","Estimating the cost of personal auto insurance in a particular area: property and casualty","Studying the impact of a disease on mortality tables: property and casualty"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Estimating motor or homeowners insurance costs in an area is property and casualty work. Option A belongs to health benefits, option D belongs to life insurance, and option B belongs to retirement systems."}},{"itemId":"fcd1fb86-a093-5836-a43f-27af730886f4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"cc6a70e8-820c-55bb-96ff-0457f2948aff","sourceKey":"bank:ACS101:ROL-050","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary studies how a rise in deaths from a particular disease in Nigeria should change the mortality tables used to price life policies. This project belongs mainly to","options":["property and casualty insurance","financial derivatives","health benefits","life insurance"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Designing and pricing life products, including updating mortality tables for the impact of a disease, is life insurance work. Option A deals with property and liability losses, and option C sets premiums for medical cover rather than death benefits."}},{"itemId":"ed56426c-96d3-532d-8cb7-4193b6ac1096","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f8214869-53de-5709-9807-536651c723fb","sourceKey":"bank:ACS101:ROL-051","parentItemId":null,"revision":1,"payload":{"prompt":"A factory worker in Kano becomes permanently disabled and, under his employer's scheme rules, starts receiving a steady monthly income for life. Which arrangement is paying him?","options":["A motor insurance policy","A pension","A fire insurance policy","A mutual fund"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A pension provides steady income, typically a guaranteed annuity, to a retired or disabled employee under legal or contractual terms, so disability as well as old age can trigger it. Option A and option C pay for damaged property, and option D is an investment vehicle with no promise of lifetime income."}},{"itemId":"c09ce783-2f69-5179-b61e-3fd4588c0082","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"caab128d-054f-54ba-993d-f5796aa31565","sourceKey":"bank:ACS101:ROL-052","parentItemId":null,"revision":1,"payload":{"prompt":"A pension plan in which the benefit is calculated using factors such as the employee's pay, years of employment and age at retirement, independently of the contributions paid, is a","options":["defined contribution plan","mutual fund","defined benefit plan","pay-as-you-go health scheme"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"In a defined benefit plan the rules fix the benefit using pay, service and retirement age, and the benefit is not directly tied to the scheme's investments. In option A the benefit depends on contributions and investment returns instead."}},{"itemId":"eaf8679c-b924-5de9-83b9-622a317e054c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"931e508d-f9e5-5fe7-9236-4f0d16ddcf7f","sourceKey":"bank:ACS101:ROL-053","parentItemId":null,"revision":1,"payload":{"prompt":"In a defined contribution pension plan, who bears the investment risk?","options":["The employer alone","The employee","The insurance regulator","The government treasury"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"In a defined contribution plan the employee's pension depends on contributions plus investment returns, so the employee bears the investment risk. Option A describes the usual position in a defined benefit plan, where the employer must make good any shortfall."}},{"itemId":"d022287e-c35b-5dbe-a20c-3efeaf055e72","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1b5558b8-844d-50f7-8f70-6518fa66ee87","sourceKey":"bank:ACS101:ROL-054","parentItemId":null,"revision":1,"payload":{"prompt":"A company's defined benefit plan pays an annual pension of 2% of final salary for each year of service. An employee retires after 25 years with a final salary of N4,800,000 a year. What is her annual pension?","options":["N2,400,000","N4,800,000","N96,000","N120,000,000"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Annual pension = 2% x 25 x 4,800,000 = 0.5 x 4,800,000 = N2,400,000. Option C takes 2% of salary but forgets to multiply by the 25 years of service, option D multiplies salary by 25 without the 2%, and option B assumes the full salary is paid."}},{"itemId":"a2f2124e-1faa-5e8e-ac0e-9cf6caf36471","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"20c85300-b010-505c-9abd-628ec8e4b8c4","sourceKey":"bank:ACS101:ROL-055","parentItemId":null,"revision":1,"payload":{"prompt":"Under a defined contribution scheme, Tunde contributes N20,000 a month and his employer contributes N25,000 a month into his retirement savings account. Ignoring investment returns and charges, how much is paid into the account in one year?","options":["N300,000","N45,000","N240,000","N540,000"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Total yearly contribution = 12 x (20,000 + 25,000) = 12 x 45,000 = N540,000. Option C counts only Tunde's share, option A only the employer's share, and option B is a single month's total."}},{"itemId":"9aec651d-fb3e-589b-95f6-6fe839db4a46","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7a2752bd-7e53-5fc3-841b-48cd728765ea","sourceKey":"bank:ACS101:ROL-056","parentItemId":null,"revision":1,"payload":{"prompt":"Under Nigeria's Contributory Pension Scheme, a worker's pension depends on the money paid into her Retirement Savings Account plus the investment returns on it. This makes the scheme a","options":["reinsurance treaty","defined contribution arrangement","defined benefit arrangement","general insurance policy"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"When the pension is determined by contributions paid in plus the investment return earned, the arrangement is defined contribution. Option C would fix the benefit by a formula based on salary and service regardless of the account balance."}},{"itemId":"141da196-33f1-5a56-9835-c965a5edec85","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"02f22e3a-093e-574e-ab0c-bdb5f1418f85","sourceKey":"bank:ACS101:ROL-057","parentItemId":null,"revision":1,"payload":{"prompt":"An arrangement under which pension or social security benefits are paid out of current revenue, with no funding set aside for future liabilities, is called","options":["pay-as-you-go","an unearned premium reserve","reinsurance","a funded defined contribution plan"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Under pay-as-you-go, today's benefits come from today's income and nothing is built up for future liabilities, which is why actuaries project how many contributors and beneficiaries there will be over time. Option D builds individual funds in advance, and option B is an insurance reserve."}},{"itemId":"1d3cc710-3be7-5e2c-b9e8-7d9acf6cc82b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"86634568-e8e8-5f6a-9352-ff1e9d5f86ba","sourceKey":"bank:ACS101:ROL-059","parentItemId":null,"revision":1,"payload":{"prompt":"An assessment of the level of funding a pension plan needs in order to provide benefits for its members is the plan's","options":["surrender value","underwriting ratio","funding objective","loss ratio"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A funding objective states the funding a pension plan requires to pay its members' benefits, which actuaries assess when valuing the plan. Options D and B are insurance ratios linking claims or expenses to premiums, and option A is paid on cancelling a life policy."}},{"itemId":"1340f1ae-667c-5526-bee8-f9fef91a5177","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9eb3cb2c-c161-5c67-a04a-e0c61eb9da7a","sourceKey":"bank:ACS101:ROL-060","parentItemId":null,"revision":1,"payload":{"prompt":"Amaka leaves her employer at age 40 after earning benefits in its occupational pension scheme, and will receive those preserved benefits only at retirement. In the scheme she is a","options":["policyholder in default","deferred member","active member","reinsurer"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A deferred member has stopped being an active member before normal pension age but keeps preserved benefits that will be paid at retirement. Option C describes someone still working and contributing, and option A wrongly suggests she owes the scheme something."}},{"itemId":"ce2e9a61-9f1a-558c-bb56-063d6cacfa62","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ea30ef53-7bdb-527d-a4aa-e89d7c67104e","sourceKey":"bank:ACS101:ROL-062","parentItemId":null,"revision":1,"payload":{"prompt":"A state government asks an actuary to estimate how much extra it will cost if its civil servants' retirement benefits are increased by 10%. This is typical actuarial work in","options":["property and casualty insurance","retirement systems","financial derivatives","marine insurance"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Pricing the cost of increasing retirement benefits is a standard retirement-systems (pension) project. Option A and option D deal with damage and liability losses, and option C deals with pricing contracts like options and swaps."}},{"itemId":"6e646cbe-8bdb-5fdc-9171-7ca024333081","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7e01c84c-2b50-5b88-b59d-8ef469846879","sourceKey":"bank:ACS101:ROL-064","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian insurer pays a lump sum to a family after the breadwinner dies. In terms of what actuaries do, this death benefit is a way of","options":["reducing the likelihood that the event will happen","decreasing the impact of an undesirable event that has occurred","forecasting the potential impact of a catastrophe","participating in a merger or acquisition"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Death, retirement and indemnity benefits do not stop the event from happening; they soften its financial impact once it happens. Option A would be something like promoting safety to prevent the event, and option C is a forecasting task done before any event."}},{"itemId":"54762267-b2b0-590c-a3a1-5d6921b30750","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2da911d8-5fb7-5b2f-ad31-667fce62fd17","sourceKey":"bank:ACS101:ROL-065","parentItemId":null,"revision":1,"payload":{"prompt":"A motor insurer in Lagos runs a campaign urging customers to always wear seat belts. In terms of what actuaries do, this is an example of","options":["decreasing the impact of events through death benefits","designing ways to reduce the likelihood or effect of undesirable events","evaluating investment programmes","maintaining pricing databases"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Promoting safety, such as seat belt use, is listed as a creative way of reducing undesirable events before they cause harm. Option A pays money after the event instead of trying to prevent harm, and options D and C are internal analysis tasks."}},{"itemId":"5bed3a83-7b41-5ffc-a90c-f0e9ccc8b54d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4ca17a2a-853c-506f-b547-6f4954e9d95c","sourceKey":"bank:ACS101:ROL-066","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank plans to buy a smaller insurance company and asks an actuary to value the insurer's long-term policy liabilities before the deal. This is actuarial work in","options":["selling motor policies","corporate planning (mergers and acquisitions)","health care administration","setting HMO premium rates"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries take part in corporate planning, including mergers and acquisitions and evaluating investment programmes, where valuing the target's liabilities is essential. Option D is health pricing, and option A is a sales task rather than an analytical one."}},{"itemId":"ad1d1c7e-8f8f-5b57-b13b-ebdb0ae6a98d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4ebed86d-e2af-5b10-a729-9b06e9880f96","sourceKey":"bank:ACS101:ROL-068","parentItemId":null,"revision":1,"payload":{"prompt":"When it comes to assets and liabilities, which professional is described as uniquely trained to understand liabilities, especially because they are complicated?","options":["The insurance sales agent","The actuary","The accountant","The CFA charterholder"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries deal with both assets and liabilities but are uniquely trained to understand complicated liabilities such as future claims and pension promises. Option C reports on assets and liabilities, and option D is geared mainly towards assets and investments."}},{"itemId":"178daaea-e889-5850-9c80-ee05ae82190c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8b6eb6af-9ba0-58b8-91d8-e662e4709e0c","sourceKey":"bank:ACS101:ROL-069","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos investment firm wants someone to analyse financial reports and recommend which companies' shares to invest in. Whose core focus best matches this task?","options":["The actuary","The CFA charterholder","The accountant","The underwriter"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"CFA charterholders analyse financial reports and investments and use that analysis to recommend what to invest in. Option A focuses on predicting the impact of uncertain future events, and option C creates and audits financial reports such as balance sheets."}},{"itemId":"727fbc48-4cc3-5313-8697-8bfcb0fd4e26","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"22ae78e7-7f47-5caf-9866-eccfd841d992","sourceKey":"bank:ACS101:ROL-070","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from insurance and finance, which of the following is listed as a typical area of actuarial work?","options":["Climate change and the environment","Criminal law practice","Civil engineering design","Primary school teaching"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Typical areas of actuarial work include insurance, finance, data science and analytics, technology, enterprise risk, and climate change and the environment. Options C, B and D belong to other professions."}},{"itemId":"71b770b7-cb8e-56a2-a0d4-e642c7d3c69d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"80143a49-b77c-50dc-b01f-8fb64e53ab20","sourceKey":"bank:ACS101:ROL-071","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian fintech is launching a new savings product and asks an actuary to model likely customer demand under different scenarios. This shows actuaries adding value by","options":["supporting marketing teams by modelling demand for a new product","recruiting new sales staff","repairing the company's IT systems","auditing the company's tax returns"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries can support marketing teams by modelling demand and setting scenarios when a new product is launched. They can also support accounting teams with models and assumptions, budgeting and forecasting. Options D, C and B are tasks for tax, IT and HR staff."}},{"itemId":"74f23671-c5c7-5c11-b92b-a7993fdcac53","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5cc8eed1-e70a-57a5-a78e-fe6a862d1622","sourceKey":"bank:ACS101:ROL-072","parentItemId":null,"revision":1,"payload":{"prompt":"The process of identifying and assessing risks, then developing strategies to minimise, monitor and control them, is called","options":["risk management","underwriting","reinsurance","indemnity"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Risk management identifies and measures risks and then builds strategies to minimise, monitor and control them, and applying it across a whole organisation is enterprise risk management. Option B is limited to accepting and pricing individual applicants, and option C is one particular way an insurer transfers risk."}},{"itemId":"9adacd90-1588-527f-98ec-32e4d334c123","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b6efab8f-ec15-5844-93af-5fb23eae6c20","sourceKey":"bank:ACS101:ROL-073","parentItemId":null,"revision":1,"payload":{"prompt":"An enterprise risk actuary at a Lagos manufacturer lists four risks: (I) high loss, high probability; (II) low loss, low probability; (III) high loss, low probability; (IV) low loss, high probability. Under ideal risk management prioritisation, which should be handled first?","options":["Risk IV","Risk III","Risk II","Risk I"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"In ideal risk management, risks with the greatest loss and the greatest probability of occurring are handled first, while those with lower loss and lower probability are handled later. Risk I has both high loss and high probability, so it comes first. Option C (Risk II) is the one handled last."}},{"itemId":"2b4b9768-8135-5635-8de5-2aff79dad5ad","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bd474890-5346-5128-971f-5425cf9a916a","sourceKey":"bank:ACS101:ROL-074","parentItemId":null,"revision":1,"payload":{"prompt":"A risk management system is an arrangement involving several activities. Which of the following is NOT one of them?","options":["Risk concealment","Risk identification","Risk reporting and monitoring","Risk assessment"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A risk management system involves risk identification, risk assessment, risk control, risk reporting and monitoring, and risk financing. Hiding risks is the opposite of what such a system aims to do. Options B, D and C are genuine components."}},{"itemId":"a84dd7d4-1b50-5039-8f9a-3631e2cd4084","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"135e85e3-3dbb-589f-8807-4800cc2de3ab","sourceKey":"bank:ACS101:ROL-075","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank must hold a minimum amount of capital set by its financial regulator. Actuaries working in banking may help measure the risks this capital protects against. This required amount is called the","options":["surrender value","unearned premium","loss ratio","capital requirement"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A capital requirement is the amount of capital a bank or other financial institution must hold as required by its regulator, often expressed as a capital adequacy ratio. Options B and A are insurance policy amounts, and option C compares claims with premiums."}},{"itemId":"ccc36146-e18a-5824-9905-fa250b844b81","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0df8e2d6-d66b-5b25-b090-f17838840bf7","sourceKey":"bank:ACS101:ROL-076","parentItemId":null,"revision":1,"payload":{"prompt":"Thousands of small savers in Nigeria each put money into one professionally managed vehicle, which uses the combined money to buy shares and bonds towards a stated goal that no single small saver could reach alone. This vehicle is a","options":["mutual fund","reinsurance treaty","risk pool of motor policies","defined benefit plan"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"A mutual fund pools many investors' money and buys securities towards a shared goal, giving advantages that a single small investor could not get. Option C also involves pooling, but of insurance policies rather than investment money."}},{"itemId":"8c0ce975-00c7-5921-a778-736710e62d88","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b94b85da-c19f-54f2-a270-61224b43f42d","sourceKey":"bank:ACS101:ROL-077","parentItemId":null,"revision":1,"payload":{"prompt":"A health insurer in Nigeria classifies employer clients by size, with 2 to 50 employees as small group, 51 to 3,000 as middle market and 3,001 or more as national accounts. A company with 120 employees asks for a staff health plan. In which segment does it fall?","options":["Small group","National accounts","Individual","Middle market"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"With 120 employees the company sits between 51 and 3,000, so it is middle market. Option A stops at 50 employees, option B starts at 3,001, and option C is for individuals and families, not employer plans."}},{"itemId":"aa6d66c0-939a-5791-847f-e8b6af6477af","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"644419f2-b03e-53f9-9507-3b307a48f757","sourceKey":"bank:ACS101:ROL-078","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a recognised role for actuaries in the regulation of the Nigerian insurance industry?","options":["Issuing Nigeria's currency notes","Licensing medical doctors to practise","Supporting the regulator (NAICOM) in setting and reviewing capital and reserving requirements","Deciding the outcome of national elections"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The National Insurance Commission (NAICOM) regulates insurance in Nigeria, and actuarial expertise is needed for rules on reserves, solvency and risk-based capital. Option A is the central bank's job, and options D and B belong to the electoral commission and medical council."}},{"itemId":"a78c3c11-dddd-52a9-8e09-a8640c6b3b7b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3dec6275-a1c4-5b79-8079-379d33466439","sourceKey":"bank:ACS101:ROL-079","parentItemId":null,"revision":1,"payload":{"prompt":"Many Nigerian insurers have been moving to the IFRS 17 standard for reporting insurance contracts, which requires detailed measurement of future cash flows from policies. What effect is this expected to have on the demand for actuaries?","options":["It affects only banks and has no link to insurers","It increases demand, because the measurement of insurance liabilities needs actuarial skills","It removes the need for actuaries entirely","It requires insurers to stop holding reserves"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"IFRS 17 requires insurers to measure their insurance contract liabilities from projected future cash flows, which is core actuarial work, so it is listed as a driver of demand for actuaries in Nigeria. Option C reverses the effect, and option D is wrong because the standard is about measuring liabilities properly, not dropping them."}},{"itemId":"9ad71303-0323-547c-adc2-03499db5d8e8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"496b8efb-5b8d-5a00-bcc6-79506ac45ec7","sourceKey":"bank:ACS101:ROL-080","parentItemId":null,"revision":1,"payload":{"prompt":"In the digital economy, actuaries contribute expertise mainly in which area to support quicker and smarter business risk decisions?","options":["Graphic design for websites","Predictive modelling and optimisation","Hardware repair","Manual bookkeeping"],"correctOption":1,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"In digital ecosystems actuaries provide expertise in predictive modelling and optimisation, building on their deep skills in data quality and analytics. Options A, D and C are unrelated to measuring and managing risk."}},{"itemId":"b5829d0e-e53f-535f-a2de-7272260024ea","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ec682f27-a627-5b0d-94ba-576d08b3ada6","sourceKey":"bank:ACS101:ROL-081","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the specialisations in actuarial science?","options":["Health and Care Specialisation","General Insurance: Reserving Specialisation","Criminal Justice Specialisation","Enterprise Risk Management Specialisation"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuarial specialisations include health and care, life insurance, pensions, investment and finance, financial derivatives, general insurance reserving, general insurance pricing and enterprise risk management. Criminal justice is not an actuarial specialisation. Options A, B and D are all on the list."}},{"itemId":"90b32555-3da8-54aa-b0ec-07975922b153","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b4c09f18-ece2-5a62-8598-487059751541","sourceKey":"bank:ACS101:ROL-082","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary at a Lagos non-life insurer spends most of her time estimating how much should be held for motor and fire claims that have occurred but are not yet settled. Her specialisation is best described as","options":["life insurance pricing","financial derivatives","pensions","general insurance reserving"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Estimating amounts to hold for outstanding and unreported claims on non-life business is general insurance reserving. Option A concerns death benefits, option C concerns retirement benefits, and option B concerns contracts such as options and swaps."}},{"itemId":"7c31f60f-857d-5c43-a091-55d1a2f40fe7","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"db5bda14-0d63-5ef7-a53b-61bbf06e7943","sourceKey":"bank:ACS101:ROL-083","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary works out the premiums an HMO should charge employers for staff medical cover in Abuja. She is working as a","options":["general (casualty) actuary","investment actuary","health actuary","pension actuary"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Setting HMO premium rates is a typical health-benefits project, so this is the work of a health actuary. Option D would value retirement benefits, option A deals with property and liability losses, and option B manages assets and investment strategy."}},{"itemId":"503a1f2e-d3d6-5f26-a6d7-c38e4c9cd67c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"6afb8a5c-9dc7-51c2-9d3f-ad435a9b4070","sourceKey":"bank:ACS101:ROL-084","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary at an Abuja consulting firm advises a manufacturing company on how much it must pay into its defined benefit scheme each year so that the pensions promised to its members can be met. He is working as a","options":["life underwriter","health actuary","pension actuary","general (casualty) actuary"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Valuing defined benefit liabilities and setting the employer's funding contributions is the core work of a pension (retirement) actuary. Option B deals with medical cover, option D with property and liability insurance, and option A is an underwriter deciding whether to accept individual life applications."}},{"itemId":"1818455b-df9d-5d41-9b68-9e584564b45c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fb3859e6-3323-5e33-b0d3-33a52d681061","sourceKey":"bank:ACS101:ROL-085","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary at a Nigerian life insurer decides how the insurer's assets should be invested so that they match the timing of the long-term annuity payments it has promised. This is the work of an","options":["claims adjuster","general (casualty) actuary","health actuary","investment actuary"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Investment and finance actuaries manage assets with the liabilities in mind, for example matching asset cash flows to long-term annuity payments. Option B focuses on non-life claims, option C on medical cover, and option A settles individual claims rather than setting investment strategy."}},{"itemId":"9207d40b-8160-5e85-a975-5ffa6cf6901e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"df15de06-2021-503e-a262-e0db5baa4e70","sourceKey":"bank:ACS101:ROL-086","parentItemId":null,"revision":1,"payload":{"prompt":"An actuary designs and prices a 10-year term assurance product for young professionals in Lagos, using mortality rates by age. She is working as a","options":["pension actuary","general (casualty) actuary","life actuary","health actuary"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Designing and pricing life insurance products using mortality rates is the work of a life actuary. Option B prices non-life covers like motor and fire, option D prices medical cover, and option A values retirement benefits."}},{"itemId":"3cb5593c-bf4e-52a5-961c-bcd7bf60d170","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a948ecaa-ee60-57ee-b194-d9e388372479","sourceKey":"bank:ACS101:ROL-087","parentItemId":null,"revision":1,"payload":{"prompt":"Which three organisations are commonly identified as the main professional bodies whose exams lead to actuarial qualification?","options":["Institute of Chartered Accountants, CFA Institute, Society of Actuaries","Chartered Insurance Institute, CFA Institute, Institute of Chartered Accountants","National Insurance Commission, Casualty Actuarial Society, Central Bank","Institute and Faculty of Actuaries, Society of Actuaries, Casualty Actuarial Society"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The three actuarial organisations commonly named are the Institute and Faculty of Actuaries (IFoA), the Society of Actuaries (SOA) and the Casualty Actuarial Society (CAS). The other options mix in accounting, investment or insurance bodies and regulators that do not award actuarial qualifications."}},{"itemId":"d1742b13-7465-52bf-ba54-27aa80ea5b23","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bf8dbe3e-cbf4-5042-8560-9eba82f4315d","sourceKey":"bank:ACS101:ROL-088","parentItemId":null,"revision":1,"payload":{"prompt":"A student wants to specialise only in property and casualty (general) insurance, and not in life, pensions or health. Which professional body focuses on that area alone?","options":["Society of Actuaries (SOA)","Institute and Faculty of Actuaries (IFoA)","Actuarial Society of South Africa (ASSA)","Casualty Actuarial Society (CAS)"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The CAS covers general insurance/P&C but not life, pension or health practice areas. The SOA covers life, pension and health but not P&C, while the IFoA and ASSA cover all four, so options B and C are not limited to general insurance."}},{"itemId":"56dd4864-d4d6-5536-bba1-657fe55ad5f3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4664ecad-a316-592f-a890-56613fb9eb1d","sourceKey":"bank:ACS101:ROL-089","parentItemId":null,"revision":1,"payload":{"prompt":"Under the IFoA route, which specialist principles subject would suit a student who wants to work on general insurance reserving and capital modelling?","options":["SP4","SP2","SP7","SP9"],"correctOption":2,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"SP7 is General Insurance Reserving and Capital Modelling. Option B (SP2) is Life Insurance, option A (SP4) is Pensions and Other Benefits, and option D (SP9) is Enterprise Risk Management."}},{"itemId":"e0073ecf-1b79-5247-ac7b-dfad3da6ce71","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fd3c60c4-48d1-52af-b4ac-57f5a2249e26","sourceKey":"bank:ACS101:ROL-090","parentItemId":null,"revision":1,"payload":{"prompt":"In both the Society of Actuaries and the Casualty Actuarial Society, which statement about the two levels of membership is correct?","options":["Both levels are awarded without any examinations","Fellow is the first level and Associate is the higher level","Associate and Fellow are the same level with different names","Associate (ASA or ACAS) is the first level and Fellow (FSA or FCAS) is the higher level"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Each society has two membership levels reached by passing exams: Associate first (ASA or ACAS), then Fellow (FSA or FCAS). Option B reverses the order, and option A is wrong because the designations are earned by passing a series of examinations."}},{"itemId":"fa3dd571-cf60-5fb1-9799-77700dbfa6f4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b9d7078a-c1c3-5e0c-bf7b-39c0dff678d9","sourceKey":"bank:ACS101:ROL-091","parentItemId":null,"revision":1,"payload":{"prompt":"A UNILAG actuarial graduate joins an insurer in Lagos and studies for professional exams while being paid. This feature of the actuarial career is described as","options":["earning while you learn","deferred membership","moral hazard","pay-as-you-go"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuarial trainees usually work and take exams at the same time, which is described as 'earn while you learn', and early career advancement is largely exam-based. Option D is a pension funding method, and options C and B are insurance and pension terms unrelated to careers."}},{"itemId":"f7e3265c-8e4c-53bc-8159-90c739cac280","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"969d5d07-8196-584b-b3c5-ec9ce3896535","sourceKey":"bank:ACS101:ROL-092","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT listed among the skills needed to become an actuary?","options":["Mathematical and analytical skills","Excellent oral and written communication skills","Strong business sense and commercial awareness","Ability to work strictly alone and avoid communicating with others"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries need mathematical and analytical skills, project management and problem solving, excellent communication, business sense, self-motivation, and the ability to work in a team. Avoiding communication is the opposite of what the role demands. Options A, B and C are all required skills."}},{"itemId":"7c2a93c8-8a43-5829-9d4e-74f88a4d9b27","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dab82de5-7c77-5e39-9578-b2d245509ebf","sourceKey":"bank:ACS101:ROL-093","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a reason commonly given for choosing a career as an actuary?","options":["Highly transferable skills and international opportunities","Advancement depends only on length of service","The work involves no mathematics","No examinations are needed to qualify"],"correctOption":0,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Reasons to become an actuary include job security, internationally recognised qualifications, solid career progression, good pay, highly transferable skills and international opportunities. Option D is false because qualifying requires exams, and option B is wrong because early advancement is largely exam-based."}},{"itemId":"39100ae1-b59e-5c2e-b84a-e7d8683027d5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2f15c848-309b-587f-a5d2-356c87324e8c","sourceKey":"bank:ACS101:ROL-094","parentItemId":null,"revision":1,"payload":{"prompt":"Actuaries are largely employed by which two kinds of organisations?","options":["Construction companies and farms","Hospitals and schools","Newspapers and television stations","Insurance companies and consulting firms"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"Actuaries are mainly employed by insurance companies and consulting firms, working in areas such as life and annuities, health, pensions and property and casualty. Consulting actuaries advise many clients, for example on pension schemes. Options B, A and C are not the main employers of actuaries."}},{"itemId":"6e002c73-adf0-5cc3-8edb-3bb6818f2f70","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8e1cf11d-019e-58a4-845e-0bf0979fdf3f","sourceKey":"bank:ACS101:ROL-095","parentItemId":null,"revision":1,"payload":{"prompt":"The employee benefit industry is one of the common industries where actuaries work. Which list gives examples of what it covers?","options":["Mergers, acquisitions and banking","Shares, bonds and derivatives trading","Motor, marine and aviation insurance","Retirement benefits, health benefits and social security"],"correctOption":3,"section":"Actuarial Science, Insurance and the Role of Actuaries","explanation":"The employee benefit industry covers retirement benefits, health benefits and social security. Option C lists general insurance lines in the insurance industry, and options A and B belong to the financial services industry."}},{"itemId":"38af8a6f-1e62-5435-aae2-2a848b08b7d6","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d08c1a26-1274-5d7f-a294-61607d3e45d3","sourceKey":"bank:ACS101:TVM-001","parentItemId":null,"revision":1,"payload":{"prompt":"The principle that N100 received today is worth more than N100 received a year from now, because the money received today can be invested to earn interest, is called","options":["the time value of money","simple discount","the nominal value of money","the payback period"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The time value of money is the idea that money available now is worth more than the same amount in the future because of its potential earning capacity. Option C refers to the stated face value of a security, not its value over time. Option D is a capital-budgeting measure that actually ignores the time value of money, and option B is one method of calculating present values."}},{"itemId":"bd619938-73c3-56f6-9ef2-f166aba5b3af","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e744126a-fd09-5f35-911a-718a8527f603","sourceKey":"bank:ACS101:TVM-002","parentItemId":null,"revision":1,"payload":{"prompt":"Why is a naira received today worth more than a naira received in the future, under the time value of money?","options":["Because future payments are certain while present payments are not","Because money received now can be invested to earn interest","Because interest is charged only on loans and never paid on deposits","Because the face value of naira notes falls every year"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The time value of money rests on earning capacity: provided money can earn interest, any amount is worth more the sooner it is received. Option D confuses face value, which does not change, with value over time. Option A has certainty the wrong way round, and option C is simply false since deposits earn interest."}},{"itemId":"afbb3d7a-c923-53ae-8411-0828c4cfde6d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9276cf5d-c7b8-5e1b-a33f-ebf1a511e559","sourceKey":"bank:ACS101:TVM-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly describes simple interest at rate r per annum?","options":["Interest is deducted in advance, so the value now of 1 due at time t is (1 - r)^t","Interest is added continuously, so 1 grows to e^(rt) after t years","Interest is earned on the principal and on interest already earned, so 1 grows to (1 + r)^t","Interest is earned only on the original principal, so 1 grows to 1 + rt after t years"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Simple interest is calculated on the original principal only, so a unit investment grows linearly to 1 + rt and in general A = P(1 + rt). Option C describes compound interest, where interest also earns interest. Option A describes compound discounting, and option B describes continuous compounding at force of interest r."}},{"itemId":"32cec13a-9cf3-5e80-8bd2-a00f231c1072","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b6376b96-d5f9-5a2a-89b8-46185dba069c","sourceKey":"bank:ACS101:TVM-004","parentItemId":null,"revision":1,"payload":{"prompt":"A thrift cooperative in Ibadan credits interest to each member's savings at the end of every year, and the credited interest itself earns interest in the following years. This arrangement is an example of","options":["simple interest","simple discount","compound interest","a nominal rate of discount"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"When interest is added to the balance and then earns interest itself, the account grows by compound interest, so P accumulates to P(1 + i)^n. Option A would pay interest on the original savings only. Options B and D describe interest deducted in advance, which is not what happens here."}},{"itemId":"d8c2171c-685a-53ed-bc16-72c202651a04","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ba79e1a0-1ebd-59f4-b688-854c5946f68c","sourceKey":"bank:ACS101:TVM-005","parentItemId":null,"revision":1,"payload":{"prompt":"How does the growth of an investment under simple interest differ from its growth under compound interest at the same positive rate?","options":["Both grow geometrically, but simple interest uses a lower rate","Simple interest grows geometrically, while compound interest grows linearly","Both grow linearly, but compound interest has a steeper line","Simple interest grows linearly (1 + rt), while compound interest grows geometrically ((1 + i)^t)"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Under simple interest the same amount of interest is added each year, so the value 1 + rt is a straight line in t, while under compound interest each year's growth is a fixed percentage of a rising balance, giving the geometric curve (1 + i)^t. Option B swaps the two, and options C and A wrongly give both methods the same shape."}},{"itemId":"a3fd68b5-80ab-5728-b9cd-10a649ae41ee","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0b502e11-c4e6-555c-b365-09063d5066c3","sourceKey":"bank:ACS101:TVM-006","parentItemId":null,"revision":1,"payload":{"prompt":"For the same positive annual rate r, how do the accumulated values of 1 under simple interest, 1 + rt, and compound interest, (1 + r)^t, compare at exactly t = 1 year?","options":["It depends on whether r is above or below 10%","Simple interest gives more, because it is not reduced by compounding","They are equal, both being 1 + r","Compound interest gives more, because interest earns interest"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"At t = 1, (1 + r)^1 = 1 + r x 1, so the two methods give exactly the same accumulation; compounding only makes a difference once interest has been credited and starts earning interest. Option D is true for t greater than 1, and option B is true for t less than 1. Option A is wrong because the equality at t = 1 holds for every rate."}},{"itemId":"fa6da708-4a51-5e8d-905d-0d455cc4930e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"88b2fbde-254c-5d4d-94ac-1201fc058dad","sourceKey":"bank:ACS101:TVM-007","parentItemId":null,"revision":1,"payload":{"prompt":"A trader in Yaba invests N25,000 at a simple interest rate of 9% per annum. What is the accumulated value at the end of 4 years, to the nearest naira?","options":["N34,000","N9,000","N35,290","N31,750"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Under simple interest A = P(1 + rt) = 25,000(1 + 0.09 x 4) = 25,000 x 1.36 = N34,000. Option C compounds the interest as 25,000(1.09)^4, which is wrong because simple interest is earned on the principal only. Option D uses 3 years instead of 4, and option B is just the interest, not the accumulated value."}},{"itemId":"cbbe91ca-a008-53ec-b492-bae590225490","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"70a704d1-2770-5b64-adc3-0d624cc8148b","sourceKey":"bank:ACS101:TVM-008","parentItemId":null,"revision":1,"payload":{"prompt":"Amaka deposits N40,000 in a savings scheme that pays simple interest at 12% per annum. How much interest does she earn in 9 months, to the nearest naira?","options":["N3,549","N3,600","N4,320","N4,800"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Time must be in years, so t = 9/12 = 0.75 and interest = Prt = 40,000 x 0.12 x 0.75 = N3,600. Option D charges a full year's interest, option C wrongly writes 9 months as 0.9 of a year, and option A uses compound growth 40,000[(1.12)^0.75 - 1] instead of simple interest."}},{"itemId":"06548c60-bc09-5774-bf8a-3e8e455eba2b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"22890cbd-7fa6-5d10-92c1-e39fa3d3d260","sourceKey":"bank:ACS101:TVM-009","parentItemId":null,"revision":1,"payload":{"prompt":"A sum of N20,000 invested at simple interest grows to N26,000 after 5 years. What is the annual rate of simple interest?","options":["4.62%","5.39%","6.00%","30.00%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"From A = P(1 + rt): 26,000 = 20,000(1 + 5r), so 1 + 5r = 1.3 and r = 0.3/5 = 6.00%. Option B solves (1 + r)^5 = 1.3, which is the compound interest rate, not the simple rate. Option D is the total growth over 5 years without dividing by the time, and option A wrongly divides the interest by the final amount instead of the principal."}},{"itemId":"522c1e3d-4cc0-54ce-befa-e1f0f062ec3d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"5458aa8f-ddb9-5a5f-95dc-39060a5f57d7","sourceKey":"bank:ACS101:TVM-010","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take N15,000 to grow to N21,000 at a simple interest rate of 8% per annum?","options":["17.50 years","5.00 years","3.57 years","4.37 years"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Simple interest gives 21,000 = 15,000(1 + 0.08t), so 0.08t = 0.4 and t = 0.4/0.08 = 5.00 years. Option D solves (1.08)^t = 1.4, which assumes compound interest. Options C and A mix up which amount goes in the numerator and denominator."}},{"itemId":"bd9836d9-2360-5d76-86b5-aa6376e1c293","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3b7e87be-56e6-50ce-a74a-252e9e01e58d","sourceKey":"bank:ACS101:TVM-011","parentItemId":null,"revision":1,"payload":{"prompt":"A company must pay a debt of N50,000 in 3 years' time and can invest money now at a simple interest rate of 10% per annum. How much must it invest now (to 2 decimal places)?","options":["N35,000.00","N37,565.74","N45,454.55","N38,461.54"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Rearranging A = P(1 + rt) gives P = A/(1 + rt) = 50,000/(1 + 0.10 x 3) = 50,000/1.3 = N38,461.54. Option A treats 10% as a simple discount rate, 50,000(1 - 0.3). Option B discounts at compound interest, 50,000/(1.1)^3, and option C discounts for only one year."}},{"itemId":"3ee08733-b432-5fc0-a2f6-4b184bbf31af","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"fc5a65cc-8b14-56e8-8f02-267a56422679","sourceKey":"bank:ACS101:TVM-012","parentItemId":null,"revision":1,"payload":{"prompt":"Under a rate of simple discount d per annum, the value now, P, of an amount A payable at time t years is","options":["P = A(1 - d)^t","P = A(1 - dt)","P = A/(1 + dt)","P = A(1 + dt)"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Simple discount deducts d per year of the amount due, in proportion to time, so P = A(1 - dt). Option C is present value under simple interest, and option A is compound discounting at an effective discount rate. Option D is an accumulation, not a present value."}},{"itemId":"f720562f-1522-5417-bbc6-2b4e3b6dac41","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a1e3cab3-09f5-571c-9f35-8be2d6cd86b4","sourceKey":"bank:ACS101:TVM-013","parentItemId":null,"revision":1,"payload":{"prompt":"A bill of N60,000 is payable in 2 years. Using a rate of simple discount of 7% per annum, what is its present value (to 2 decimal places)?","options":["N51,600.00","N55,800.00","N52,631.58","N51,894.00"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"At simple discount the present value is P = A(1 - dt) = 60,000(1 - 0.07 x 2) = 60,000 x 0.86 = N51,600.00. Option C treats 7% as simple interest, 60,000/1.14, and option D applies the discount in compound form, 60,000(0.93)^2. Option B discounts for only one year."}},{"itemId":"f7252db0-8127-51a8-89f7-710c51d99439","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f75d8918-a1d9-52dd-aaa5-b391135665fa","sourceKey":"bank:ACS101:TVM-014","parentItemId":null,"revision":1,"payload":{"prompt":"An amount of N2,000 is invested for 3 years at a rate of simple discount of 6% per annum. To what amount does it accumulate at the end of the 3 years (to 2 decimal places)?","options":["N2,360.00","N1,640.00","N2,439.02","N2,407.94"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Under simple discount P = A(1 - dt), so the accumulated value is A = P/(1 - dt) = 2,000/(1 - 0.06 x 3) = 2,000/0.82 = N2,439.02. Option A treats 6% as simple interest, 2,000 x 1.18. Option B multiplies by (1 - dt) instead of dividing, which gives a present value, and option D uses the compound form 2,000/(0.94)^3."}},{"itemId":"61a0dfc0-8e4c-5e91-864e-bb9e81870b1f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"abd94a40-5d88-57c0-835a-6a5406430ebc","sourceKey":"bank:ACS101:TVM-015","parentItemId":null,"revision":1,"payload":{"prompt":"To 4 decimal places, to what amount does N1 accumulate in one year at a rate of simple discount of 5% per annum?","options":["0.9500","1.0500","1.0526","1.0476"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"A unit invested for one period at simple discount d accumulates to 1/(1 - d) = 1/0.95 = 1.0526. Option B treats 5% as an interest rate, giving 1.05. Option A is 1 - d, which is the present value of 1 due in a year, not an accumulation."}},{"itemId":"caf113e8-efc5-5f35-aea2-897093ddea99","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9d7fde1d-176b-5d88-b5eb-413a592349bc","sourceKey":"bank:ACS101:TVM-016","parentItemId":null,"revision":1,"payload":{"prompt":"Under compound interest at an effective rate i per period, what does the expression (1 + i)^n measure?","options":["The effective rate of discount over n periods","The accumulated value at time n of 1 invested at time 0","The present value at time 0 of 1 due at time n","The total interest earned on 1 over n periods"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"(1 + i)^n is the accumulation factor: it tells you what a unit investment grows to after n periods, so P grows to P(1 + i)^n. Option C describes the discount factor v^n = (1 + i)^-n, the reverse operation. Option D is (1 + i)^n - 1, which excludes the original unit."}},{"itemId":"5b2b3fb2-85cc-5a51-9462-4683740b2a3b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"795c4d85-066b-5d03-99c7-0d4c91347e62","sourceKey":"bank:ACS101:TVM-017","parentItemId":null,"revision":1,"payload":{"prompt":"N80,000 is invested at an effective rate of compound interest of 7% per annum. What is the accumulated value after 6 years, to the nearest naira?","options":["N53,307","N113,600","N120,058","N112,204"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The accumulated value is P(1 + i)^n = 80,000(1.07)^6 = N120,058. Option B uses simple interest, 80,000(1 + 0.07 x 6). Option D accumulates for only 5 years, and option A discounts instead of accumulating."}},{"itemId":"4aeaedf2-3c3f-54b2-8db2-1f54ba590cff","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7458617e-0ae0-534f-8f76-afd800535f89","sourceKey":"bank:ACS101:TVM-018","parentItemId":null,"revision":1,"payload":{"prompt":"A cooperative society invests N50,000 at an effective compound interest rate of 10% per annum for 3 years. How much interest does it earn over the 3 years, to the nearest naira?","options":["N10,500","N15,000","N66,550","N16,550"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compound interest earned is P[(1 + i)^n - 1] = 50,000[(1.1)^3 - 1] = 50,000 x 0.331 = N16,550. Option B is the simple interest 50,000 x 0.1 x 3, which ignores interest on interest. Option C is the full accumulated value rather than the interest, and option A uses only 2 years."}},{"itemId":"153e0960-c08c-5f43-8a8a-1e8895dd6454","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"589217d1-9d13-5e6a-bc28-6900b1bb2c11","sourceKey":"bank:ACS101:TVM-019","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N500,000 due in 5 years at an effective rate of compound interest of 8% per annum, to the nearest naira?","options":["N300,000","N340,292","N357,143","N329,541"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Present value = A(1 + i)^-n = 500,000(1.08)^-5 = N340,292. Option C discounts at simple interest, 500,000/(1 + 0.4), and option A uses simple discount, 500,000(1 - 0.4). Option D wrongly takes the discount factor as 1 - i = 0.92 instead of 1/1.08."}},{"itemId":"bee7f1ca-f90d-5fc3-8b4d-94ef26ae8576","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3177666f-36af-5d92-8dd8-06a46ce7fc77","sourceKey":"bank:ACS101:TVM-020","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest of 6% per annum, what is the value of the discount factor v^10, to 4 decimal places?","options":["1.7908","0.5584","0.4000","0.5386"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"v = (1.06)^-1, so v^10 = (1.06)^-10 = 0.5584, the present value of 1 due in 10 years. Option A is the accumulation factor (1.06)^10, the reverse operation. Option D wrongly uses 0.94 for v, and option C is the simple-discount style value 1 - 10(0.06)."}},{"itemId":"10c18090-b11c-50c9-89d8-94ac7a6c46b4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dcae9c75-b7a1-5aff-b258-2c1362c6a71d","sourceKey":"bank:ACS101:TVM-021","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is invested for 2 years at 10% per annum. By how much does the interest earned at compound interest (compounded annually) exceed the interest earned at simple interest?","options":["N10,000","N1,000","N20,000","N21,000"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compound interest = 100,000[(1.1)^2 - 1] = N21,000 and simple interest = 100,000 x 0.1 x 2 = N20,000, so the difference is N1,000, which is interest earned on the first year's interest. Options D and C are the two interest amounts themselves, not their difference, and option A is one year's interest."}},{"itemId":"7fde2fd9-6ecf-576d-a246-134c6d7674d4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4f1690fb-ecfd-5d8b-b1fb-861d9acdef90","sourceKey":"bank:ACS101:TVM-022","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of N10,000 grows to N14,641 in 4 years under compound interest. What is the effective annual rate of interest?","options":["10.00%","11.60%","46.41%","9.09%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Solve 10,000(1 + i)^4 = 14,641, so 1 + i = (1.4641)^(1/4) = 1.1 and i = 10.00%. Option B averages the growth as if it were simple interest (46.41%/4), and option C is the total growth over 4 years. Option D is 1 - (1.4641)^(-1/4), which is the equivalent rate of discount d, not i."}},{"itemId":"13c13b97-05de-59f3-bb5c-b976fc243dca","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bc5dbbc6-0802-538d-a4c4-c6e8d27afa66","sourceKey":"bank:ACS101:TVM-023","parentItemId":null,"revision":1,"payload":{"prompt":"How long does it take a sum of money to double at an effective compound interest rate of 9% per annum (to 2 decimal places)?","options":["7.70 years","8.04 years","22.22 years","11.11 years"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Solve (1.09)^n = 2, giving n = ln 2/ln 1.09 = 8.04 years. Option D is the doubling time under simple interest (1/0.09), and option A divides ln 2 by 0.09 as if 9% were the force of interest. Option C wrongly divides 2 by the rate."}},{"itemId":"a81b1e82-9c93-50dd-a253-c48b56efc26a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a81960e6-dc63-59f7-9bc3-81eda026cb5c","sourceKey":"bank:ACS101:TVM-024","parentItemId":null,"revision":1,"payload":{"prompt":"How long will it take N30,000 to accumulate to N45,000 at an effective compound interest rate of 6% per annum (to 2 decimal places)?","options":["8.33 years","6.96 years","25.00 years","6.76 years"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Solve 30,000(1.06)^n = 45,000, so (1.06)^n = 1.5 and n = ln 1.5/ln 1.06 = 6.96 years. Option A is the simple interest answer 0.5/0.06, and option D divides ln 1.5 by 0.06, treating 6% as a force of interest. Option C divides the ratio by the rate."}},{"itemId":"f0fff725-913b-5d79-9451-c138d4c1a7d5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"0cfe866a-a2a2-5792-b8f1-a02a3bc89c9a","sourceKey":"bank:ACS101:TVM-025","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fintech fund turns N50,000 into N80,000 over 6 years with interest compounded annually. What effective annual rate of interest did it earn (to 2 decimal places)?","options":["10.00%","9.86%","7.83%","8.15%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Solve 50,000(1 + i)^6 = 80,000, so i = (1.6)^(1/6) - 1 = 8.15%. Option A is the simple interest rate 60%/6. Option C is ln 1.6/6, which is the force of interest, not the effective rate, and option B uses 5 years instead of 6."}},{"itemId":"038685aa-2340-536b-b7a5-b0e46eead0fe","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"3b47f233-00c3-5381-8ee8-30b332a49022","sourceKey":"bank:ACS101:TVM-026","parentItemId":null,"revision":1,"payload":{"prompt":"A sum of money amounts to N24,200 in 2 years at an effective compound interest rate of 10% per annum. What was the original sum (to 2 decimal places)?","options":["N20,166.67","N19,360.00","N20,000.00","N22,000.00"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The principal is 24,200(1.1)^-2 = 24,200/1.21 = N20,000.00. Option A discounts at simple interest, 24,200/1.2. Option B subtracts 20% of the final amount, and option D discounts for only one year."}},{"itemId":"40d04d95-2382-515d-bf47-2a28f05b725e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"46914ab3-2eb8-5dc9-b1b5-8e6f4a903bb0","sourceKey":"bank:ACS101:TVM-027","parentItemId":null,"revision":1,"payload":{"prompt":"A payment of N300,000 is due at the end of year 7. Using an effective rate of interest of 5% per annum, what is its value at the end of year 2, to the nearest naira?","options":["N272,109","N235,058","N213,204","N193,383"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Moving a payment back from time 7 to time 2 means discounting for 5 years: 300,000 v^5 = 300,000(1.05)^-5 = N235,058. Option C discounts all the way to time 0 (7 years), and option A discounts for only 2 years. Option D adds the two times together and discounts for 9 years."}},{"itemId":"471d02bf-84af-50bf-a089-851813caea81","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2dcd6f2c-36fa-5395-b33e-d49bec0eaa1e","sourceKey":"bank:ACS101:TVM-028","parentItemId":null,"revision":1,"payload":{"prompt":"N10,000 is invested for 2 years and 6 months at an effective compound interest rate of 12% per annum. What is the accumulated value (to 2 decimal places)?","options":["N13,382.26","N12,544.00","N13,275.32","N13,000.00"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Compound interest works for non-integer time, so A = 10,000(1.12)^2.5 = N13,275.32. Option D uses simple interest, option B ignores the extra 6 months, and option A wrongly treats 12% as a nominal rate convertible half-yearly, 10,000(1.06)^5."}},{"itemId":"ba071038-f5ef-5220-9187-74b07c13c013","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bd5063cd-7a97-5e6b-9d4d-46e91dd939f4","sourceKey":"bank:ACS101:TVM-029","parentItemId":null,"revision":1,"payload":{"prompt":"At an effective rate of interest i per annum, what does v^n = (1 + i)^-n represent?","options":["The interest earned in the nth year on 1 invested now","The accumulated value after n years of 1 invested now","The nominal rate of interest convertible n times a year","The present value of 1 due at the end of n years"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"v = (1 + i)^-1 is the present value of a unit payment due in one period, so v^n is the present value of 1 due in n periods; multiplying by v^n is how we discount. Option B is the accumulation factor (1 + i)^n. Option C confuses a rate convertible n times a year with a discount factor."}},{"itemId":"70a19736-f9ee-5814-b36d-1e3be01cb75f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"578fc3e3-54a8-5a85-95b8-672a8b40db60","sourceKey":"bank:ACS101:TVM-030","parentItemId":null,"revision":1,"payload":{"prompt":"Under compound interest at an effective rate i per annum, to find the value at time 3 of a payment due at time 7 you should multiply the payment by","options":["v^3","v^4","(1 + i)^4","v^7"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The payment is moved 4 years earlier, from time 7 back to time 3, so it is discounted by v^4 = (1 + i)^-4. Option C would move it 4 years later instead. Option D discounts all the way to time 0, and option A uses the wrong number of years."}},{"itemId":"cabeab23-c8d8-5f04-9b22-aa2b0c621944","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"989aed8b-0edd-5cab-a0c6-a5dcec068108","sourceKey":"bank:ACS101:TVM-031","parentItemId":null,"revision":1,"payload":{"prompt":"A pension fund in Abuja values two liabilities of N1,000,000 each, one due in 10 years and one due in 20 years, at the same positive effective rate of interest. Which statement is correct?","options":["The liability due in 20 years has the larger present value, because it accumulates more interest","Both liabilities have the same present value, because the amounts are equal","The liability due in 10 years has the smaller present value, because it is paid sooner","The liability due in 20 years has the smaller present value, because v^n falls as n increases"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The present value of 1,000,000 due at time n is 1,000,000v^n, and since 0 < v < 1 the factor v^n gets smaller as n grows, so the later liability is worth less today. Option B ignores the time value of money, while options A and C confuse discounting with accumulation."}},{"itemId":"3e8f8a0c-51fe-5611-acd2-8b290796b96e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"97ac481b-c50a-578a-b9bb-26708e30daf8","sourceKey":"bank:ACS101:TVM-032","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of discount d per annum is best described as","options":["the discount on 1 due a year hence, i.e. interest for the year paid at the start of the year","the interest on 1 for a year, paid at the end of the year","the instantaneous rate of growth of a fund under continuous compounding","the annual rate of interest convertible m times a year"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"In international actuarial notation d is the discount on 1 due a year hence: the year's interest charged at the start, so d = 1 - v = i/(1 + i). Option B describes the effective rate of interest i. Option D describes a nominal rate i^(m), and option C describes the force of interest delta."}},{"itemId":"5e36543c-6c8f-562e-b6a3-03db012c08c9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ceb2e6ca-a533-5780-8c95-0e215e60085a","sourceKey":"bank:ACS101:TVM-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a correct expression for the effective rate of discount d in terms of the effective rate of interest i (with v = 1/(1 + i))?","options":["d = i/(1 - i)","d = 1 - v","d = i/(1 + i)","d = iv"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The discount on 1 due a year hence is 1 - v, and since 1 - 1/(1 + i) = i/(1 + i) = iv, options C, D and B are all the same correct quantity. The expression i/(1 - i) is wrong; it would make d larger than i, whereas d is always smaller than i when i > 0."}},{"itemId":"114aa68c-24fb-5da9-a4ff-f4e572607e70","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"60cd6aed-f8ea-50ff-a569-8b902c4007d7","sourceKey":"bank:ACS101:TVM-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a correct expression for the discount factor v?","options":["v = e^-delta","v = 1 - d","v = 1/(1 + i)","v = 1 + d"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The discount factor is the present value of 1 due in a year, so v = (1 + i)^-1, which equals 1 - d because d is the discount on that unit, and equals e^-delta because 1 + i = e^delta. Options C, B and A are therefore all correct. 1 + d is greater than 1, so it cannot be a present value of 1 due in the future."}},{"itemId":"e39a723b-d9d7-5517-85af-8bb90a45ecd8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8419a9a0-0701-5aeb-bef6-1fde076e6e34","sourceKey":"bank:ACS101:TVM-035","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 8% per annum. What is the equivalent effective rate of discount d per annum (to 2 decimal places)?","options":["92.59%","7.70%","8.70%","7.41%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"d = i/(1 + i) = 0.08/1.08 = 7.41%, the interest on 1 for a year when it is paid at the start of the year. Option C uses i/(1 - i), which is the wrong way round. Option B is ln 1.08, the force of interest, and option A is v = 1/1.08, the discount factor rather than the discount rate."}},{"itemId":"65d91c57-1d34-539f-8bbc-a741fc44ca9c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f52fff2e-0530-5534-804c-9c32744f63d7","sourceKey":"bank:ACS101:TVM-036","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of discount is 6% per annum. What is the equivalent effective rate of interest i per annum (to 2 decimal places)?","options":["5.66%","6.00%","6.38%","6.18%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Since v = 1 - d = 0.94 and 1 + i = 1/v, i = d/(1 - d) = 0.06/0.94 = 6.38%. Option A uses d/(1 + d), which converts in the wrong direction, and option B assumes i equals d. Option D is e^0.06 - 1, which treats 6% as a force of interest."}},{"itemId":"1049de67-f808-5f42-b177-7501f81b9c2f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"14e5b70e-a92b-515e-b4fe-0ffda3417237","sourceKey":"bank:ACS101:TVM-037","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N200,000 due in 3 years at an effective rate of discount of 5% per annum (to 2 decimal places)?","options":["N170,000.00","N171,475.00","N180,500.00","N172,767.52"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With an effective discount rate, v = 1 - d = 0.95, so the present value is 200,000(0.95)^3 = N171,475.00. Option D treats 5% as an interest rate, 200,000/(1.05)^3. Option A uses simple discount 200,000(1 - 0.15), and option C discounts for only 2 years."}},{"itemId":"3ba091c8-cda2-5409-9bb6-7bb8e44a64e5","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9bc666c2-7b21-56a1-8f42-e1ab4a258ed5","sourceKey":"bank:ACS101:TVM-038","parentItemId":null,"revision":1,"payload":{"prompt":"A bill of exchange for N100,000 is due in one year. If the effective rate of interest is 12% per annum, what is the amount of discount on the bill, i.e. the difference between its face value and its present value (to 2 decimal places)?","options":["N13,636.36","N10,714.29","N12,000.00","N89,285.71"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The discount on 1 due a year hence is d = i/(1 + i) = 0.12/1.12, so the discount is 100,000 x 0.12/1.12 = N10,714.29. Option C is the interest 12% of face value, which is paid at the end, not deducted at the start. Option D is the present value of the bill itself, and option A uses i/(1 - i)."}},{"itemId":"c354b526-4385-5c75-bce2-dad90ec89e8e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d0b14a33-ad8f-50a7-b9f4-f6b8567f243d","sourceKey":"bank:ACS101:TVM-039","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer must pay N1,000,000 in 4 years. Using an effective rate of discount of 10% per annum, what is the present value of the payment (to 2 decimal places)?","options":["N683,013.46","N729,000.00","N600,000.00","N656,100.00"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Here v = 1 - d = 0.9, so present value = 1,000,000(0.9)^4 = N656,100.00. Option A treats 10% as an interest rate, 1,000,000/(1.1)^4. Option C applies simple discount for 4 years, and option B discounts for only 3 years."}},{"itemId":"cbd48827-779b-5a59-b136-1318c7595767","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"1757fa45-c4fc-56bc-b468-695297464ac5","sourceKey":"bank:ACS101:TVM-040","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian bank advertises a savings rate of 24% per annum convertible monthly. Which statement about this rate is correct?","options":["It is a force of interest of 24%, so N100 grows to 100e^0.24 in a year","It is a nominal rate of discount d^(12) = 24%, deducted at the start of each month","It is an effective annual rate, so N100 grows to exactly N124 in a year","It is a nominal rate i^(12) = 24%, so the effective rate per month is 2%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"A rate quoted 'convertible monthly' is a nominal rate i^(12); dividing by 12 gives the effective monthly rate of 2%, and a unit grows to (1 + 0.24/12)^12 in a year. Option C ignores the monthly conversion, which makes the effective annual rate higher than 24%. Option A describes continuous compounding, and option B describes a discount rate, not an interest rate."}},{"itemId":"5c716456-922f-5588-8ac0-0f3c08471c99","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bfc88483-2b73-52f7-9370-39b452cabfef","sourceKey":"bank:ACS101:TVM-041","parentItemId":null,"revision":1,"payload":{"prompt":"Two interest rates (for example a nominal rate convertible quarterly and an effective annual rate) are said to be equivalent when","options":["they produce the same accumulated value from the same principal over the same period","they are quoted by the same bank for the same product","they have the same numerical value","they are both expressed per annum"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Equivalent rates describe the same growth: for example i^(m) and i are equivalent when (1 + i^(m)/m)^m = 1 + i, so one naira grows to the same amount over a year under either. Option C is wrong because equivalent rates usually have different numbers, such as 10% effective and 9.569% convertible monthly. Options B and D say nothing about growth."}},{"itemId":"15256a74-4e73-5776-a293-e91dd3beec4c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"079c0799-32f8-52e0-81d2-92809f89461b","sourceKey":"bank:ACS101:TVM-042","parentItemId":null,"revision":1,"payload":{"prompt":"A bank quotes a nominal rate of interest of 12% per annum convertible quarterly, i^(4) = 12%. What is the equivalent effective annual rate of interest (to 2 decimal places)?","options":["12.36%","12.75%","12.55%","12.00%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The quarterly effective rate is i^(4)/4 = 3%, so 1 + i = (1.03)^4 and i = 12.55%. Option D wrongly takes the nominal rate as the effective rate. Option A compounds 6% twice, as if interest were convertible half-yearly, and option B is e^0.12 - 1, which treats 12% as a force of interest."}},{"itemId":"b1288220-3858-5649-82f6-7c0acce2b9f1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"25431979-1bf6-5ed4-9b72-cac2dbc277ba","sourceKey":"bank:ACS101:TVM-043","parentItemId":null,"revision":1,"payload":{"prompt":"A microfinance bank charges a nominal rate of interest of 18% per annum convertible monthly. What is the equivalent effective annual rate of interest (to 2 decimal places)?","options":["18.00%","19.72%","19.56%","19.25%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The monthly effective rate is 18%/12 = 1.5%, so i = (1.015)^12 - 1 = 19.56%. Option A ignores the monthly compounding. Option D compounds quarterly at 4.5% instead of monthly, and option B is continuous compounding e^0.18 - 1."}},{"itemId":"ddc372be-a5ed-54b3-b6f5-6df973b2b9d9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"8589b2f4-74af-520f-b620-c64ada9df7ff","sourceKey":"bank:ACS101:TVM-044","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 21% per annum. What is the equivalent nominal rate of interest per annum convertible half-yearly, i^(2) (to 2 decimal places)?","options":["10.00%","19.06%","21.00%","20.00%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Set (1 + i^(2)/2)^2 = 1.21, so i^(2)/2 = (1.21)^(1/2) - 1 = 0.10 and i^(2) = 20.00%. Option A is the effective rate per half-year, which must be multiplied by 2 to give the nominal annual rate. Option C assumes nominal and effective rates are equal, and option B is ln 1.21, the force of interest."}},{"itemId":"244e4912-9b5b-511d-b847-6db2081aa734","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2539ee90-4e79-57c8-9513-0ff038d776c8","sourceKey":"bank:ACS101:TVM-045","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 15% per annum. What is the equivalent nominal rate of interest convertible monthly, i^(12) (to 2 decimal places)?","options":["1.17%","14.06%","13.98%","15.00%"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"i^(12) = 12[(1.15)^(1/12) - 1] = 14.06%. Option A is the monthly effective rate (1.15)^(1/12) - 1, which has not been multiplied by 12. Option C is ln 1.15, the force of interest, which is the limit as m grows without bound, and option D ignores the conversion entirely."}},{"itemId":"08ae38dd-a69e-5123-bc6d-f40e7ce83897","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c1a5857e-53da-5be5-8dcc-3300b91a42e6","sourceKey":"bank:ACS101:TVM-046","parentItemId":null,"revision":1,"payload":{"prompt":"N200,000 is invested for 3 years at a nominal rate of interest of 8% per annum convertible quarterly. What is the accumulated value, to the nearest naira?","options":["N253,648","N251,942","N254,250","N248,000"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With i^(4) = 8%, the quarterly rate is 2% and there are 12 quarters, so A = 200,000(1.02)^12 = N253,648. Option B treats 8% as an effective annual rate, 200,000(1.08)^3, and option D uses simple interest. Option C compounds continuously, 200,000e^0.24."}},{"itemId":"13d7daa7-a768-587d-9974-46f18e951e7c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7fc4a6ff-b1da-5fc7-a436-f994f819aeac","sourceKey":"bank:ACS101:TVM-047","parentItemId":null,"revision":1,"payload":{"prompt":"N50,000 is deposited for 18 months at a nominal rate of interest of 12% per annum convertible monthly. What is the accumulated value (to 2 decimal places)?","options":["N59,807.37","N59,264.83","N56,341.25","N59,000.00"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The monthly rate is 12%/12 = 1% over 18 months, so A = 50,000(1.01)^18 = N59,807.37. Option B treats 12% as effective annual, 50,000(1.12)^1.5. Option D uses simple interest, and option C counts only 12 months."}},{"itemId":"b1f25443-d686-5fc6-9fc9-9a0e87fc6c0d","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c5331343-75c9-54cb-86d2-7dc5d8e8c8af","sourceKey":"bank:ACS101:TVM-048","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N1,000,000 due in 2 years at a nominal rate of interest of 10% per annum convertible half-yearly, to the nearest naira?","options":["N907,029","N814,506","N822,702","N826,446"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The half-yearly rate is 5% for 4 half-years, so PV = 1,000,000(1.05)^-4 = N822,702. Option D treats 10% as an effective annual rate, and option A uses only 2 half-years. Option B wrongly takes the discount factor per half-year as 0.95 instead of 1/1.05."}},{"itemId":"90f311a4-7fb3-5f98-832a-9a4cba102b2f","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7c2613df-a3a6-5480-bc43-4c494e6457d3","sourceKey":"bank:ACS101:TVM-049","parentItemId":null,"revision":1,"payload":{"prompt":"The effective rate of interest is 12% per annum. What is the equivalent effective rate of interest per month (to 2 decimal places)?","options":["0.95%","1.00%","2.87%","5.83%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Equivalent rates give the same growth over a year, so (1 + j)^12 = 1.12 and j = (1.12)^(1/12) - 1 = 0.95% per month. Option B simply divides 12% by 12, which would give more than 12% a year once compounded. Options C and D are the equivalent quarterly and half-yearly rates, not the monthly rate."}},{"itemId":"dce18858-6748-5783-8b28-b4ed2090440e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7f2e61aa-8fc0-51ed-b548-239f1fa765ef","sourceKey":"bank:ACS101:TVM-050","parentItemId":null,"revision":1,"payload":{"prompt":"A savings account earns an effective rate of 1% per month. What is the equivalent effective rate of interest per quarter (to 2 decimal places)?","options":["3.00%","3.03%","12.68%","4.06%"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"A quarter has 3 months, so the quarterly rate is (1.01)^3 - 1 = 3.03%. Option A adds the three monthly rates and ignores interest on interest. Option C is the annual rate (1.01)^12 - 1, and option D compounds for 4 months instead of 3."}},{"itemId":"09f2d996-dc12-506e-adff-e0aab99eea7e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"78dfc83b-6d9e-5f36-aa18-4074328f7b9a","sourceKey":"bank:ACS101:TVM-051","parentItemId":null,"revision":1,"payload":{"prompt":"A nominal rate of interest of 8% per annum is convertible quarterly. What is the equivalent nominal rate of interest per annum convertible half-yearly, i^(2) (to 2 decimal places)?","options":["8.08%","8.24%","8.00%","4.04%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The quarterly rate is 2%, so the half-yearly rate is (1.02)^2 - 1 = 4.04% and i^(2) = 2 x 4.04% = 8.08%. Option C assumes nominal rates with different conversion frequencies are equal. Option B is the effective annual rate (1.02)^4 - 1, and option D is the half-yearly rate that has not been multiplied by 2."}},{"itemId":"1797eb79-97c7-5ff4-8d3f-ebf1bc46ceec","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2a4bfd59-6d5c-5265-8c65-cb8ab2c1b056","sourceKey":"bank:ACS101:TVM-052","parentItemId":null,"revision":1,"payload":{"prompt":"Bank A offers 12% per annum convertible monthly and Bank B offers an effective rate of 12.5% per annum. Which bank gives the higher return on a one-year deposit, and why?","options":["Bank B, because 12.5% is higher than 12%","Neither, because both rates are equivalent effective annual rates","Bank B, because Bank A's effective annual rate is exactly 12.00%","Bank A, because its effective annual rate is about 12.68%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Rates with different conversion frequencies must be compared as effective annual rates: Bank A gives (1 + 0.12/12)^12 - 1 = (1.01)^12 - 1 = 12.68%, which beats Bank B's 12.5%. Options A and C compare a nominal rate directly with an effective rate, forgetting that monthly conversion adds interest on interest. Option B is wrong because the two rates are not equivalent."}},{"itemId":"e84062d2-1a72-5ae2-b059-9685fcd40af3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"e0430235-f6da-556c-9cb0-89496e7adabc","sourceKey":"bank:ACS101:TVM-053","parentItemId":null,"revision":1,"payload":{"prompt":"A bill of N500,000 is due in one year. Using a nominal rate of discount of 8% per annum convertible half-yearly, d^(2) = 8%, what is its present value, to the nearest naira?","options":["N462,278","N460,000","N480,000","N460,800"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With d^(2) = 8%, the discount per half-year is 4%, so PV = 500,000(1 - 0.04)^2 = 500,000 x 0.9216 = N460,800. Option B treats 8% as an effective annual discount rate, option A treats it as a nominal interest rate i^(2), and option C discounts for only one half-year."}},{"itemId":"fbc43883-b1df-5548-bdf7-654014496110","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"101dad71-4cf9-56a9-becc-c675cae0b451","sourceKey":"bank:ACS101:TVM-054","parentItemId":null,"revision":1,"payload":{"prompt":"The nominal rate of discount is 12% per annum convertible quarterly, d^(4) = 12%. What is the equivalent effective annual rate of discount d (to 2 decimal places)?","options":["11.47%","11.31%","12.55%","12.00%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The quarterly discount rate is 3%, so 1 - d = (1 - 0.03)^4 = 0.8853 and d = 11.47%. Option D wrongly takes the nominal rate as the effective rate. Option C treats 12% as a nominal interest rate i^(4) and finds the effective interest rate, and option B is 1 - e^-0.12, which treats 12% as a force of interest."}},{"itemId":"e9114816-312f-59c3-a599-ca99045afb67","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"41bd571a-4032-51c1-bddf-88db67f946f7","sourceKey":"bank:ACS101:TVM-055","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest delta is best defined as","options":["the effective rate of interest earned over one complete year","the nominal rate of interest convertible twelve times a year","the limit of the nominal rate i^(m) as m tends to infinity, i.e. the instantaneous rate of growth","the interest on 1 for a year paid at the start of the year"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The force of interest is the instantaneous rate of growth of a fund, like a nominal rate compounded continuously, so delta = lim i^(m) as m tends to infinity and 1 + i = e^delta. Option A is the effective rate i, option D is the rate of discount d, and option B is i^(12)."}},{"itemId":"c8102c3f-cbde-554e-a1ef-da1acf54c0f2","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"80d5b1d0-9fad-5386-948f-2b47f73ae406","sourceKey":"bank:ACS101:TVM-056","parentItemId":null,"revision":1,"payload":{"prompt":"For a given positive effective annual rate of interest i, which ordering of the equivalent rates is correct?","options":["delta < i^(12) < i^(2) < i","i < i^(2) < i^(12) < delta","delta = i^(12) = i^(2) = i","i^(2) < i^(12) < delta < i"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"To produce the same effective rate i, a rate that is converted more often needs a smaller nominal value, so i^(m) falls as m rises and the force of interest, the limit as m grows without bound, is the smallest; for i = 10%, i^(2) = 9.762%, i^(12) = 9.569% and delta = 9.531%. Option B reverses the order, and option C wrongly treats equivalent rates as numerically equal."}},{"itemId":"83af7b58-fe86-536c-a436-ec32d59d8563","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7aee5983-9dda-5c94-aebc-0bfe11e6521a","sourceKey":"bank:ACS101:TVM-057","parentItemId":null,"revision":1,"payload":{"prompt":"A nominal rate of interest is fixed at 10% per annum. As the number of conversions per year m increases (m = 1, 2, 4, 12, ...), the equivalent effective annual rate of interest","options":["decreases, approaching ln 1.1 = 9.53%","increases without limit as m grows","increases, approaching e^0.1 - 1 = 10.52%","stays at 10% for every value of m"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The effective rate (1 + 0.1/m)^m - 1 rises with m, from 10% at m = 1 to 10.25% at m = 2 and 10.471% at m = 12, but it is bounded by continuous compounding at e^0.1 - 1 = 10.52%. Option A describes what happens to the equivalent nominal rate when the effective rate is fixed instead. Option B is wrong because the growth levels off at the continuous limit."}},{"itemId":"4e217d68-791a-5a0d-82f9-65a2cf6b08ae","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"38204b39-4d39-5ff3-bea0-306595847392","sourceKey":"bank:ACS101:TVM-058","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following relationships involving the force of interest delta is NOT correct?","options":["1 + i = e^delta","delta = e^i - 1","delta = ln(1 + i)","v = e^-delta"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Because the limit of (1 + i^(m)/m)^m is e^delta, we get 1 + i = e^delta, which can be written delta = ln(1 + i), and taking reciprocals gives v = e^-delta; options A, C and D are all correct. The expression e^i - 1 mixes up the roles of i and delta; the correct direction is i = e^delta - 1."}},{"itemId":"0aab1b9b-d796-52b9-9f47-30ce693893a1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4e2da466-58d9-5a8b-8a64-f2e52d831b0f","sourceKey":"bank:ACS101:TVM-059","parentItemId":null,"revision":1,"payload":{"prompt":"In international actuarial notation, the Greek letter delta denotes","options":["the force of interest","the effective rate of discount","the nominal rate of discount","the force of mortality"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Delta is the force of interest, the instantaneous rate of growth under continuous compounding, linked to the effective rate by 1 + i = e^delta. Option B is denoted d, option C is denoted d^(m), and option D is denoted by the Greek letter mu."}},{"itemId":"4312166e-a8f7-5cc5-afe9-181266785a88","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f3b908f0-9068-5c73-b0ed-b68bbb591fbc","sourceKey":"bank:ACS101:TVM-060","parentItemId":null,"revision":1,"payload":{"prompt":"What is the force of interest delta per annum equivalent to an effective rate of interest of 8% per annum (to 4 decimal places)?","options":["0.0770","0.0741","0.0833","0.0800"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Since 1 + i = e^delta, delta = ln(1.08) = 0.0770. Option D assumes delta equals i, but the force of interest is always a little less than i when i > 0. Option B is the rate of discount d = i/(1 + i), and option C is e^0.08 - 1, which applies the formula in the wrong direction."}},{"itemId":"dcbfb754-a97a-5e32-a545-d93aa9749c85","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ab3cd0e6-749a-5eaf-84a9-2df68c6b255b","sourceKey":"bank:ACS101:TVM-061","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest is 6% per annum. What is the equivalent effective annual rate of interest (to 2 decimal places)?","options":["6.18%","6.38%","6.00%","5.83%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"From 1 + i = e^delta, i = e^0.06 - 1 = 6.18%. Option C assumes i equals delta, which ignores continuous compounding. Option D is ln 1.06, which converts in the wrong direction, and option B treats 6% as a discount rate."}},{"itemId":"0b2d89c7-101d-5be4-8323-80190adc94c3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"f1ed38f8-42dd-5e39-beda-b9d56154d956","sourceKey":"bank:ACS101:TVM-062","parentItemId":null,"revision":1,"payload":{"prompt":"N250,000 is invested for 4 years at a constant force of interest of 9% per annum. What is the accumulated value, to the nearest naira?","options":["N358,332","N340,000","N327,491","N352,895"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With a constant force of interest A = P e^(delta t) = 250,000 e^(0.09 x 4) = 250,000 e^0.36 = N358,332. Option D treats 9% as an effective annual rate, 250,000(1.09)^4. Option B uses simple interest, and option C accumulates for only 3 years."}},{"itemId":"65b59113-b949-5923-a203-7784aeaa2f41","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"7118e133-9dd2-56a2-aa19-17f76b779838","sourceKey":"bank:ACS101:TVM-063","parentItemId":null,"revision":1,"payload":{"prompt":"What is the present value of N1,000,000 due in 5 years at a constant force of interest of 10% per annum, to the nearest naira?","options":["N666,667","N606,531","N500,000","N620,921"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With v = e^-delta, the present value is 1,000,000 e^(-0.1 x 5) = 1,000,000 e^-0.5 = N606,531. Option D treats 10% as an effective rate, 1,000,000(1.1)^-5. Options C and A use simple discount and simple interest respectively."}},{"itemId":"304f6bcc-5aa7-5044-af12-5333d383190a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"2daaca56-6faa-5b71-b6bb-2812114e328b","sourceKey":"bank:ACS101:TVM-064","parentItemId":null,"revision":1,"payload":{"prompt":"What is the force of interest delta per annum equivalent to a nominal rate of interest of 8% per annum convertible quarterly (to 4 decimal places)?","options":["0.0792","0.0800","0.0824","0.0198"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Since (1 + i^(4)/4)^4 = e^delta, delta = 4 ln(1.02) = 0.0792. Option B assumes delta equals the nominal rate, and option D is ln(1.02), the force for one quarter that has not been converted to an annual figure. Option C is the effective annual rate (1.02)^4 - 1, not the force of interest."}},{"itemId":"6083fa56-1335-5385-9f9d-ed5c20ce1344","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4bed7720-7f69-5488-9e16-7621c309209e","sourceKey":"bank:ACS101:TVM-065","parentItemId":null,"revision":1,"payload":{"prompt":"An investment earns an effective rate of interest of 5% per quarter. What is the equivalent force of interest delta per annum (to 4 decimal places)?","options":["0.1952","0.2155","0.2000","0.0488"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"One year is 4 quarters, so e^delta = (1.05)^4 and delta = 4 ln(1.05) = 0.1952 per annum. Option D is the force per quarter, ln 1.05, not per annum. Option C multiplies 5% by 4, and option B is the effective annual rate (1.05)^4 - 1."}},{"itemId":"b2f729b1-fecb-54cb-8c2c-50d605420813","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"b596cd8c-c076-5b92-a04b-23ab1950ee02","sourceKey":"bank:ACS101:TVM-066","parentItemId":null,"revision":1,"payload":{"prompt":"How long does it take a sum of money to double at a constant force of interest of 7% per annum (to 2 decimal places)?","options":["9.90 years","10.24 years","28.57 years","14.29 years"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Solve e^(0.07t) = 2, so t = ln 2/0.07 = 9.90 years. Option D is the simple interest doubling time 1/0.07. Option B is ln 2/ln 1.07, which treats 7% as an effective annual rate, and option C wrongly divides 2 by the rate."}},{"itemId":"a9107936-12e0-5d0f-8cb5-0d509ecb99e1","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c61c347f-2857-534e-b60b-28bb034984ad","sourceKey":"bank:ACS101:TVM-067","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest is 5% per annum. What is the annual discount factor v (to 4 decimal places)?","options":["0.9524","0.9512","1.0513","0.9500"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Since v = e^-delta, v = e^-0.05 = 0.9512. Option A is 1/1.05, which treats 5% as an effective rate of interest. Option D is 1 - 0.05, which treats it as an effective rate of discount, and option C is e^0.05, the accumulation factor."}},{"itemId":"06d30282-95de-521b-a52f-5968f869f590","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"75836417-3408-5447-96ad-9429e379264a","sourceKey":"bank:ACS101:TVM-068","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest is 10% per annum. What is the equivalent effective annual rate of discount d (to 2 decimal places)?","options":["9.52%","10.00%","10.52%","9.09%"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Since v = e^-delta and d = 1 - v, d = 1 - e^-0.1 = 9.52%. Option B assumes d equals delta, and option C is e^0.1 - 1, which is the effective rate of interest i, not d. Option D treats 10% as an effective interest rate and computes 0.1/1.1."}},{"itemId":"9658a023-099c-5545-a767-5851bf12f84b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"9dedfc43-ebb4-58cd-99b6-9fb349b3293c","sourceKey":"bank:ACS101:TVM-069","parentItemId":null,"revision":1,"payload":{"prompt":"A bank pays interest at 15% per annum compounded continuously. What does a deposit of N40,000 accumulate to after 2 years (to 2 decimal places)?","options":["N52,900.00","N46,473.37","N52,000.00","N53,994.35"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Continuous compounding at 15% means a force of interest delta = 0.15, so A = 40,000 e^(0.15 x 2) = 40,000 e^0.3 = N53,994.35. Option A compounds annually, 40,000(1.15)^2, which gives less than continuous compounding. Option C uses simple interest, and option B accumulates for only one year."}},{"itemId":"e31a6413-08e0-5bfc-bc5f-b4defd4750b8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"4f490d93-1cc7-50e5-ad88-0a42aa8d3abb","sourceKey":"bank:ACS101:TVM-070","parentItemId":null,"revision":1,"payload":{"prompt":"The force of interest is 12% per annum. What is the equivalent nominal rate of interest per annum convertible monthly, i^(12) (to 2 decimal places)?","options":["12.00%","12.75%","12.06%","11.39%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Set (1 + i^(12)/12)^12 = e^0.12, so i^(12) = 12(e^0.01 - 1) = 12.06%. Option A assumes i^(12) equals delta, but i^(12) must be slightly larger than delta. Option B is the effective annual rate e^0.12 - 1, and option D wrongly treats 12% as the effective annual rate before converting to monthly."}},{"itemId":"9397f174-2663-59e3-9ee3-4eabd7b6fdba","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"dd9ae060-ae31-5758-be86-5742aae19ed9","sourceKey":"bank:ACS101:TVM-071","parentItemId":null,"revision":1,"payload":{"prompt":"A single sum is invested for 6 years at 5% for 3 years and then 7% for 3 years, compared with 7% for 3 years and then 5% for 3 years. Which statement is correct?","options":["The first order gives more, because the higher rate is applied to a larger balance","The final amounts are equal, because the accumulation factors (1.05)^3 and (1.07)^3 are simply multiplied","The final amounts cannot be compared without knowing the principal","The second order gives more, because the higher rate is earned first"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"For one payment, the accumulation over consecutive periods is the product of the factors, (1.05)^3(1.07)^3, and multiplication does not depend on order. The order of rates matters only when further payments are made part-way, as with a second deposit at time 3. Options A and D wrongly assume order matters for a single sum, and option C fails because the principal scales both results equally."}},{"itemId":"21668aec-7cd4-5922-ae0f-82c59208512a","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"a422aea3-233a-5bf4-81cc-0a4de1d5ae7b","sourceKey":"bank:ACS101:TVM-072","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is invested for 5 years. The effective rate of interest is 6% per annum for the first 2 years and 9% per annum for the next 3 years. What is the accumulated value at the end of 5 years, to the nearest naira?","options":["N139,000","N145,509","N141,505","N143,563"],"correctOption":1,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"With changing rates the accumulation factors for consecutive periods are multiplied: 100,000(1.06)^2(1.09)^3 = N145,509. Option D uses the simple average rate 7.5% for all 5 years, which is not equivalent. Option C applies 6% for 3 years and 9% for 2 years, swapping the periods, and option A adds the interest as if it were simple."}},{"itemId":"e0eed49f-40b3-5f08-8c54-6c5d5aba8b25","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"557b76a6-782a-5fff-8925-ee890367f2c0","sourceKey":"bank:ACS101:TVM-073","parentItemId":null,"revision":1,"payload":{"prompt":"A payment of N500,000 is due at the end of year 4. The effective rate of interest is 10% per annum for years 1 and 2 and 12% per annum for years 3 and 4. What is the present value of the payment at time 0, to the nearest naira?","options":["N313,632","N317,759","N329,419","N341,507"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Discount through each period at its own rate: PV = 500,000/[(1.1)^2(1.12)^2] = 500,000/1.517824 = N329,419. Options B and D use only one of the two rates for all 4 years. Option A wrongly uses 1 - i as the discount factor in each year."}},{"itemId":"f14dd19e-8cf1-5a39-901c-0eeea86f20dc","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c39d36c7-f439-5e29-af57-899a44e3f422","sourceKey":"bank:ACS101:TVM-074","parentItemId":null,"revision":1,"payload":{"prompt":"Investments of N50,000 now and a further N50,000 two years from now are accumulated to the end of year 5. The effective rate of interest is 8% per annum for the first 2 years and 10% per annum thereafter. What is the total accumulation at the end of year 5, to the nearest naira?","options":["N147,076","N136,452","N144,174","N127,624"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The first deposit grows to 50,000(1.08)^2 = 58,320 at time 2; adding the second deposit gives 108,320, which then grows at 10% for 3 years: 108,320(1.1)^3 = N144,174. Option D forgets that the second N50,000 also earns interest for 3 years. Options A and B apply a single rate (10% or 8%) to the whole term instead of switching rates at time 2."}},{"itemId":"77c5bbdd-81c8-5796-89e1-b6db2d33a166","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"53f7aaa5-e926-5f40-a8f9-f0211fee8b9f","sourceKey":"bank:ACS101:TVM-075","parentItemId":null,"revision":1,"payload":{"prompt":"In setting up an equation of value for payments made at different dates under compound interest, which statement is correct?","options":["Payments can be added directly at their face values, whatever their dates","The comparison date must always be time 0, otherwise the answer changes","All payments must be valued at the same date, and any comparison date gives the same solution","Only payments made after the comparison date need to be adjusted for interest"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Money at different dates can only be compared after moving every payment to one common date, accumulating earlier payments and discounting later ones. Under compound interest, moving the whole equation to another date multiplies both sides by the same factor (1 + i)^k, so the solution does not change. Option A ignores the time value of money, and option B is wrong because time 0 is only a convenient choice."}},{"itemId":"118af8c3-d1ce-55b1-9007-ede7062715c4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"c0f818d6-c430-5d0d-b7d4-305e5efa4415","sourceKey":"bank:ACS101:TVM-076","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde borrows N200,000 now at an effective rate of interest of 10% per annum. He repays N100,000 at the end of year 1 and clears the loan with a single payment at the end of year 3. What is the final payment?","options":["N133,100","N166,200","N140,000","N145,200"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The equation of value at time 3 is 200,000(1.1)^3 = 100,000(1.1)^2 + X, so X = 266,200 - 121,000 = N145,200. Option B forgets to accumulate the N100,000 repayment from time 1 to time 3. Option A subtracts the repayment without allowing for its timing, and option C uses simple interest."}},{"itemId":"50534e5b-9a6d-51e8-8de8-501878543d2e","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"02cc40c1-db4f-59b0-9dc8-0ed7d29bfa34","sourceKey":"bank:ACS101:TVM-077","parentItemId":null,"revision":1,"payload":{"prompt":"Using an effective rate of interest of 9% per annum, what is the present value of N60,000 due in 2 years plus N80,000 due in 5 years, to the nearest naira?","options":["N99,609","N112,275","N102,495","N90,990"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Discount each payment from its own date: 60,000(1.09)^-2 + 80,000(1.09)^-5 = 50,501 + 51,994 = N102,495. Option D discounts the combined N140,000 for 5 years, ignoring that N60,000 is paid earlier. Option B discounts the second payment for 3 years instead of 5, and option A uses 0.91 instead of 1/1.09 as the discount factor."}},{"itemId":"8b88438c-df8d-526e-9b10-31358e1140f9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ca67923c-09b8-5da9-86f3-2cd96f463102","sourceKey":"bank:ACS101:TVM-078","parentItemId":null,"revision":1,"payload":{"prompt":"Using an effective rate of interest of 7% per annum, what is the accumulated value at the end of year 4 of N30,000 paid now and N40,000 paid at the end of year 2, to the nearest naira?","options":["N91,756","N79,324","N85,120","N84,000"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"Each payment accumulates for the time it is invested: 30,000(1.07)^4 + 40,000(1.07)^2 = 39,324 + 45,796 = N85,120. Option A accumulates both payments for 4 years, and option B forgets to accumulate the second payment at all. Option D uses simple interest for both."}},{"itemId":"ba78d963-2fd3-5f2b-bea5-82dea727b827","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"536653df-ff88-5118-8654-84155efb08b3","sourceKey":"bank:ACS101:TVM-079","parentItemId":null,"revision":1,"payload":{"prompt":"A payment of N50,000 is due at the end of year 1 and N70,000 at the end of year 5. At an effective rate of interest of 8% per annum, what single payment at the end of year 3 is equivalent to the two payments, to the nearest naira?","options":["N120,000","N102,881","N139,968","N118,334"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"At the comparison date of time 3, the earlier payment is accumulated 2 years and the later one discounted 2 years: 50,000(1.08)^2 + 70,000(1.08)^-2 = 58,320 + 60,014 = N118,334. Option C accumulates both payments, option B discounts both, and option A ignores interest altogether."}},{"itemId":"fcada40e-1b54-5e27-831e-adfe64c61042","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"bea08ff5-8986-5c66-acee-6ea88130e95e","sourceKey":"bank:ACS101:TVM-080","parentItemId":null,"revision":1,"payload":{"prompt":"An investor deposits N100,000 now and another N100,000 one year from now. At the end of year 2 the account holds N231,000. What effective annual rate of compound interest was earned?","options":["15.50%","7.47%","10.00%","7.75%"],"correctOption":2,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The equation of value at time 2 is 100,000(1 + i)^2 + 100,000(1 + i) = 231,000, i.e. x^2 + x - 2.31 = 0 with x = 1 + i, giving x = 1.1 and i = 10.00%. Option A divides the total interest of N31,000 by N200,000, ignoring timing. Option D halves that figure, and option B wrongly assumes the full N200,000 was invested for both years."}},{"itemId":"a86af576-57c0-5548-96d3-8b4c87ad20a8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"33158371-8a53-58ed-8ecc-62ac1cdf2537","sourceKey":"bank:ACS101:TVM-081","parentItemId":null,"revision":1,"payload":{"prompt":"Using an effective rate of interest of 6% per annum, what single payment at the end of year 4 is equivalent to N100,000 paid now and N100,000 paid at the end of year 2, to the nearest naira?","options":["N226,248","N252,495","N236,000","N238,608"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The equivalent payment equals the accumulated value at time 4: 100,000(1.06)^4 + 100,000(1.06)^2 = 126,248 + 112,360 = N238,608. Option B accumulates both payments for 4 years, option A does not accumulate the second payment, and option C uses simple interest."}},{"itemId":"2b1220dc-4750-5198-85d8-a622a3bda5d8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"62be335e-9a29-5d94-859d-b76bbacc25e5","sourceKey":"bank:ACS101:TVM-082","parentItemId":null,"revision":1,"payload":{"prompt":"Payments of N200,000 are due at the end of year 1 and at the end of year 2. At a nominal rate of interest of 10% per annum convertible half-yearly, what is their total present value, to the nearest naira?","options":["N347,107","N329,081","N371,882","N345,946"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The half-yearly rate is 5%, so year 1 is 2 periods and year 2 is 4 periods: PV = 200,000(1.05)^-2 + 200,000(1.05)^-4 = N345,946. Option A treats 10% as an effective annual rate. Option C uses 1 and 2 half-years instead of 2 and 4, and option B discounts both payments for 2 years."}},{"itemId":"38b3ac78-4bc9-5f5e-9427-132b462ee2fa","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"ed4d57a1-9d6e-58ba-9017-efb791214011","sourceKey":"bank:ACS101:TVM-083","parentItemId":null,"revision":1,"payload":{"prompt":"A loan of N500,000 is to be repaid by two equal payments at the end of year 1 and the end of year 2, at an effective rate of interest of 10% per annum. What is each payment (to 2 decimal places)?","options":["N288,095.24","N275,000.00","N302,500.00","N250,000.00"],"correctOption":0,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"The equation of value at time 0 is X(v + v^2) = 500,000 with v = 1/1.1, so X = 500,000/(0.909091 + 0.826446) = N288,095.24. Option B accumulates half the loan for one year, and option C accumulates the whole loan for 2 years and halves it, both ignoring that the payments are made at different times. Option D ignores interest."}},{"itemId":"5072a35e-841f-51d3-a7df-985c3cd343e3","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"91fdf508-c7c9-5c53-8f45-43b5d10ae024","sourceKey":"bank:ACS101:TVM-084","parentItemId":null,"revision":1,"payload":{"prompt":"N100,000 is invested for 6 months at 20% per annum. Compare simple interest with compound interest (effective 20% per annum). Which statement is correct (to 2 decimal places)?","options":["Compound interest gives N455.49 more than simple interest","Both give the same amount, N110,000.00","Compound interest gives N500.00 more than simple interest","Simple interest gives N455.49 more than compound interest"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"For a period shorter than one year, simple interest gives more: 100,000(1 + 0.2 x 0.5) = N110,000.00 while 100,000(1.2)^0.5 = N109,544.51, a difference of N455.49. Option A reverses the direction; compound interest only overtakes simple interest after one full period. Option B is wrong because the two methods agree only at exactly one period."}},{"itemId":"0728db99-a30c-5856-884a-28ddb5a8f9c8","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"cbt_question","questionId":"d0f601f3-eca5-5c1c-a193-2c51d341db05","sourceKey":"bank:ACS101:TVM-085","parentItemId":null,"revision":1,"payload":{"prompt":"N80,000 grows to N100,000 in 2 years with interest compounded quarterly. What nominal rate of interest per annum convertible quarterly, i^(4), was earned (to 2 decimal places)?","options":["12.50%","11.80%","2.83%","11.31%"],"correctOption":3,"section":"Time Value of Money: Compound Interest and Discounting","explanation":"There are 8 quarters, so (1 + i^(4)/4)^8 = 1.25, giving i^(4)/4 = (1.25)^(1/8) - 1 = 2.83% and i^(4) = 11.31%. Option B is the effective annual rate (1.25)^(1/2) - 1, not the nominal quarterly rate. Option A is a simple-interest average, and option C is the quarterly rate that has not been multiplied by 4."}}]$expected_content$::jsonb,
  'introduction-actuarial-science: cbt_question published payload and identity match source');
set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('d1b6b70d-037b-5e9e-a4d4-17103525cc56')
  where kind = 'theory_question') = $expected_content$[{"itemId":"1871811f-78c9-57e1-980e-e0e29fb463ab","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer covers 20,000 similar okada riders in Lagos. Past experience shows 1.5% of riders make a claim each year, with an average claim of ₦250,000. Ignoring expenses and profit, find (a) the expected claim cost per rider and (b) the total expected claims. (c) Why is this prediction reliable?"}},{"itemId":"09606d73-a9a7-537f-8892-586f175d7f31","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"Arrange in time order, earliest first: founding of the Institute of Actuaries; Halley's Breslau table; Graunt's observations; founding of the Equitable Society. Give the year of each."}},{"itemId":"91ec30ca-0cb2-5a01-be7f-30fc2372ece4","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"In a life table l_40 = 90,000, q_40 = 0.003 and q_41 = 0.004. Find l_41, d_41, l_42 and _2p_40."}},{"itemId":"8368a089-9a1b-5585-8838-55f0fc3e0e42","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"An insurer covers 400 Lagos shop owners against burglary for one year. The probability of a claim is 0.02 per shop and the average claim is ₦500,000 (at most one claim each). It adds a 30% loading. Find (a) the risk premium per shop, (b) the gross premium per shop, (c) the expected loss ratio if claims come in as expected."}},{"itemId":"9a35d314-f734-5003-9bae-9f1da719e5c9","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"A nominal rate of interest is 8% per annum convertible quarterly. Find (a) the equivalent effective annual rate of interest, (b) the force of interest, and (c) the accumulated value of ₦100,000 after 3 years. Give rates to 4 decimal places and money to the nearest kobo."}},{"itemId":"9183b89f-38d6-54e3-a6cf-d7d739aac07b","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"A debt of ₦200,000 is due at time 3. It is to be settled by X at time 1 and X at time 2. At 10% per annum effective, find X."}},{"itemId":"6c7131aa-8859-5ab1-853e-11d82c02ed25","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"A company promises a manager ₦400,000 at the end of each year for 12 years, the first payment one year after she retires in 5 years' time. It funds this with 5 equal payments at the beginning of each year over the 5 years before retirement. At 7% effective, find the annual funding payment."}}]$expected_content$::jsonb,
  'introduction-actuarial-science: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('d1b6b70d-037b-5e9e-a4d4-17103525cc56')
  where kind = 'model_answer') = $expected_content$[{"itemId":"6ca95bfe-82d0-5b9b-bc3c-2421e556581c","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"1871811f-78c9-57e1-980e-e0e29fb463ab","revision":1,"payload":{"body":"• (a) 1.5% = 0.015. Expected cost per rider = 0.015 × ₦250,000 = ₦3,750.\n• (b) Total = 20,000 × ₦3,750 = ₦75,000,000.\n• (c) By the law of large numbers, a large pool of similar, independent risks gives a stable claim proportion, so total claims are predictable."}},{"itemId":"23d25f93-c231-58a2-b91b-83da1bcda394","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"09606d73-a9a7-537f-8892-586f175d7f31","revision":1,"payload":{"body":"Graunt's observations (1662), Halley's Breslau table (1693), Equitable Society (1762), Institute of Actuaries (1848). Check each pair: 1662 < 1693 < 1762 < 1848."}},{"itemId":"9e0ec73a-457d-57c3-8e96-eba0d9fedf83","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"91ec30ca-0cb2-5a01-be7f-30fc2372ece4","revision":1,"payload":{"body":"• l_41 = 90,000 × (1 - 0.003) = 90,000 × 0.997 = 89,730.\n• d_41 = l_41 × q_41 = 89,730 × 0.004 = 358.92.\n• l_42 = 89,730 - 358.92 = 89,371.08.\n• _2p_40 = 89,371.08/90,000 = 0.993012 (check: 0.997 × 0.996 = 0.993012). So _2q_40 = 0.006988."}},{"itemId":"3efc60c8-0f4e-5452-97bf-11ec780a3e85","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"8368a089-9a1b-5585-8838-55f0fc3e0e42","revision":1,"payload":{"body":"• (a) 0.02 × ₦500,000 = ₦10,000.\n• (b) ₦10,000 × 1.30 = ₦13,000.\n• (c) Expected claims = 400 × ₦10,000 = ₦4,000,000; premiums = 400 × ₦13,000 = ₦5,200,000; loss ratio = 4,000,000 / 5,200,000 = 76.92% (to 2 decimal places)."}},{"itemId":"a9213c87-8d73-59cd-876b-c82c5544b569","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"9a35d314-f734-5003-9bae-9f1da719e5c9","revision":1,"payload":{"body":"(a) Quarterly rate = 0.08/4 = 0.02. i = (1.02)^4 − 1 = 1.082432 − 1 = 0.0824 (8.24%).\n(b) δ = ln(1 + i) = ln 1.082432 = 4 ln 1.02 = 0.0792.\n(c) 3 years = 12 quarters: 100,000 × 1.02^12 = 100,000 × 1.26824179 = ₦126,824.18."}},{"itemId":"fa271e96-df30-53f0-b45b-2f5955a97cdf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"9183b89f-38d6-54e3-a6cf-d7d739aac07b","revision":1,"payload":{"body":"Equation of value at time 0: X(1.1^(−1) + 1.1^(−2)) = 200,000 × 1.1^(−3). Left factor = 0.909091 + 0.826446 = 1.735537. Right side = 200,000 × 0.751315 = 150,262.96. X = 150,262.96 ÷ 1.735537 = ₦86,580 (nearest naira)."}},{"itemId":"c2ea8925-31e6-5f1f-9f1b-a8f2b48ddadf","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"6c7131aa-8859-5ab1-853e-11d82c02ed25","revision":1,"payload":{"body":"1. Value of the pension at retirement (time 5): 400,000 × a_12| = 400,000 × 7.942686 = ₦3,177,075.\n2. Bring it to today: 3,177,075 × 1.07^-5 = 3,177,075 × 0.712986 = ₦2,265,210.\n3. Funding is an annuity-due of 5 payments: ä_5| = (1 - 1.07^-5)/d = 4.387211.\n4. X = 2,265,210/4.387211 = ₦516,321 (to the nearest naira, using unrounded factors)."}}]$expected_content$::jsonb,
  'introduction-actuarial-science: model_answer published payload and identity match source');
