  where kind = 'course_overview') = $expected_content$[{"itemId":"2c52224a-5802-5a5e-b84b-2638dbcb39b0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Principles of Marketing","body":"Every topic is examinable.","outcomes":["Define marketing and the marketing mix elements.","Explain the marketing concepts and how they are practised.","Identify the key forces in the marketing environment.","Explain how consumers and organisations make buying decisions.","Explain the marketing system and the marketing management process.","Design and apply a market segmentation, targeting and positioning approach.","Measure market demand and prepare simple sales forecasts.","Explain the place of digital and social media in modern marketing.","Apply marketing concepts, principles and theories to solve marketing problems."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, classifications and short applications to Nigerian businesses.","A few questions need simple calculations: market potential, market share, forecasts, channel contacts and digital marketing metrics (Topics 6 to 10)."]}}]$expected_content$::jsonb,
  'principles-marketing: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('0d6682a1-b7b0-5109-b86a-2fabbfbea8b4')
  where kind = 'note') = $expected_content$[{"itemId":"a0a46b7e-747c-5977-8eff-cf3cab6b52d9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Meaning, Exchange Process and Functions of Marketing","body":"The main definitions of marketing and who gave them; needs, wants and demands; value and satisfaction; exchange, its five conditions, transactions, transfers and relationships; markets; the eight functions of marketing in three groups; utility; the importance of marketing to consumers, firms and society.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The main definitions of marketing and who gave them; needs, wants and demands; value and satisfaction; exchange, its five conditions, transactions, transfers and relationships; markets; the eight functions of marketing in three groups; utility; the importance of marketing to consumers, firms and society."}],"lessons":[{"number":"1.1","title":"What marketing means","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The ultimate goal of any business is to "},{"text":"identify and satisfy customers","bold":true},{"text":"; that goal is reached only through effective "},{"text":"marketing","bold":true},{"text":" activities. Marketing is not merely selling, and it is not confined to one department: it is an attitude of mind and a business philosophy for the whole organisation."}]},{"text":[{"text":"There is "},{"text":"no single, universally accepted definition","bold":true},{"text":". Learn these:"}]}]},{"type":"table","header":[[{"text":"Defined by"}],[{"text":"Definition (key words)"}]],"rows":[[[{"text":"Stanton (1981)"}],[{"text":"Societal sense:","bold":true},{"text":" any exchange activity intended to satisfy human wants. "},{"text":"Business sense:","bold":true},{"text":" a system of business action designed to plan, price, promote and distribute want-satisfying goods and services to markets"}]],[[{"text":"Kotler (1988)"}],[{"text":"A "},{"text":"social and managerial process","bold":true},{"text":" by which individuals and groups obtain what they need and want through creating and exchanging products and value with others"}]],[[{"text":"Kotler and Armstrong"}],[{"text":"The process by which companies "},{"text":"create value for customers and build strong customer relationships","bold":true},{"text":" in order to "},{"text":"capture value from customers in return","bold":true}]],[[{"text":"Kotler and Keller (shortest)"}],[{"text":"Meeting needs profitably","bold":true}]],[[{"text":"Chartered Institute of Marketing (CIM, UK)"}],[{"text":"The management process responsible for "},{"text":"identifying, anticipating and satisfying customer requirements profitably","bold":true}]],[[{"text":"AMA (current)"}],[{"text":"The activity, set of institutions and processes for "},{"text":"creating, communicating, delivering and exchanging offerings","bold":true},{"text":" that have value for "},{"text":"customers, clients, partners and society at large","bold":true}]],[[{"text":"AMA (1985)"}],[{"text":"The process of planning and executing the conception, pricing, promotion and distribution of ideas, goods and services to create exchanges that satisfy individual and organisational objectives"}]],[[{"text":"AMA (early, 1960)"}],[{"text":"The performance of business activities that "},{"text":"direct the flow of goods and services from producer to consumer or user","bold":true}]],[[{"text":"Working definition"}],[{"text":"All activities aimed at "},{"text":"identifying and satisfying customer needs through beneficial exchanges with target markets","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The working definition requires 4 things: (1) finding out what customers need; (2) developing a product or service to satisfy those needs; (3) positioning it to satisfy the needs; (4) deciding the marketing mix to price, promote and distribute it."}]},{"text":[{"text":"Peter Drucker:","bold":true},{"text":" \"the aim of marketing is to make selling superfluous\", i.e. know the customer so well that the product fits and sells itself."}]},{"text":[{"text":"Definitions fall into "},{"text":"3 groups","bold":true},{"text":": marketing as a "},{"text":"process","bold":true},{"text":"; as a "},{"text":"concept or philosophy","bold":true},{"text":" of business; as an "},{"text":"orientation","bold":true},{"text":"."}]},{"text":[{"text":"Marketing is "},{"text":"both a functional area of management and an overall business philosophy","bold":true},{"text":" which recognises that identifying, satisfying and retaining customers is the key to success. It "},{"text":"focuses the firm's or individual's attention on the needs and wants of the marketplace","bold":true},{"text":"."}]},{"text":[{"text":"Micromarketing (micro definition):","bold":true},{"text":" firm-oriented, narrow view: marketing activities from the point of view of the individual organisation (e.g. identifying, anticipating and satisfying needs profitably for the firm)."}]},{"text":[{"text":"Macromarketing (macro definition):","bold":true},{"text":" broad, societal view: exchange activities and exchange systems in society, and how marketing systems relate to the rest of society."}]},{"text":[{"text":"Nonbusiness marketing:","bold":true},{"text":" marketing carried out by "},{"text":"non-profit organisations","bold":true},{"text":"."}]},{"text":[{"text":"What can be marketed:","bold":true},{"text":" goods, services, events, experiences, persons, places, properties, organisations, information and "},{"text":"ideas","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Narrow (traditional) concept:","bold":true},{"text":" physical transfer of goods from producer to consumer; product-oriented, exchange of goods for money. "},{"text":"Broad (modern) concept:","bold":true},{"text":" everything from before production to after-sales service; customer-oriented, earning profit through customer satisfaction."}]},{"text":[{"text":"Weakness of the early AMA (1960) definition:","bold":true},{"text":" it treats marketing as starting "},{"text":"only after production","bold":true},{"text":", ignoring the study of customer needs. Marketing actually "},{"text":"starts before production","bold":true},{"text":" (finding out what customers need) and "},{"text":"continues after the sale","bold":true},{"text":" (customer service, relationship building). So \"marketing begins after production and ends at the sale\" is "},{"text":"false","bold":true},{"text":". Selling and advertising are "},{"text":"only part","bold":true},{"text":" of marketing."}]},{"text":[{"text":"Stanton's \""},{"text":"total system","bold":true},{"text":" of business activities designed to plan, price, promote and distribute want-satisfying products to target markets to achieve organisational objectives\" stresses that marketing is "},{"text":"a set of related activities that work together","bold":true},{"text":", not one activity."}]},{"text":[{"text":"Kotler's \""},{"text":"societal process","bold":true},{"text":" by which individuals and groups obtain what they need and want through creating, offering and freely exchanging products and services of value\" is a "},{"text":"social","bold":true},{"text":" definition. \"Meeting needs profitably\" and the CIM version are "},{"text":"managerial","bold":true},{"text":" definitions."}]},{"text":[{"text":"The 2004 change to the AMA definition moved the emphasis from the 4Ps to "},{"text":"customers and customer relationships","bold":true},{"text":". The current AMA wording, \"creating, communicating, delivering and exchanging offerings with value\", is the modern view that goes beyond a mere sale. The CIM definition is often called the most concise."}]},{"text":[{"text":"The essence of every modern definition: "},{"text":"delivering superior value to customers while balancing profitability","bold":true},{"text":". The scope of marketing covers ideation, value creation and strategic distribution, orchestrating value creation, delivery and customer engagement, not advertising alone. "},{"text":"Market segmentation and research","bold":true},{"text":" need the deepest understanding of consumer insights."}]},{"text":[{"text":"A Lagos State ministry of health jingle urging handwashing to prevent cholera sells nothing, yet it "},{"text":"is","bold":true},{"text":" marketing: marketing applies to ideas and non-profit causes. Commercialised bodies such as NIPOST now also market actively."}]}]}]},{"number":"1.2","title":"Needs, wants, demands, value and satisfaction","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Needs:","bold":true},{"text":" states of "},{"text":"felt deprivation","bold":true},{"text":" (hunger, thirst, the desire to belong). They are a basic part of human make-up; "},{"text":"marketers do not create needs","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical needs:","bold":true},{"text":" food, clothing, warmth, "},{"text":"safety","bold":true},{"text":"."}]},{"text":[{"text":"Social needs:","bold":true},{"text":" "},{"text":"belonging and affection","bold":true},{"text":"."}]},{"text":[{"text":"Individual needs:","bold":true},{"text":" "},{"text":"knowledge and self-expression","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Wants:","bold":true},{"text":" the form a need takes as it is "},{"text":"shaped by culture and individual personality","bold":true},{"text":"."}]},{"text":[{"text":"Demands:","bold":true},{"text":" wants "},{"text":"backed by buying power","bold":true},{"text":". (The quantity of goods people are willing and able to buy in a given period.)"}]},{"text":[{"text":"Market offering:","bold":true},{"text":" a combination of products, services, information or experiences offered to satisfy a need or want."}]},{"text":[{"text":"Customer perceived value:","bold":true},{"text":" the customer's evaluation of the difference between "},{"text":"all the benefits and all the costs","bold":true},{"text":" of an offering compared with competing offers."}],"blocks":[{"type":"paragraph","text":[{"text":"Customer perceived value = total customer benefit − total customer cost"}]}]},{"text":[{"text":"Customer satisfaction:","bold":true},{"text":" depends on product "},{"text":"performance relative to expectations","bold":true},{"text":":"}]}]},{"type":"table","header":[[{"text":"Performance vs expectations"}],[{"text":"Result"}]],"rows":[[[{"text":"Falls short"}],[{"text":"Dissatisfied"}]],[[{"text":"Matches"}],[{"text":"Satisfied"}]],[[{"text":"Exceeds"}],[{"text":"Highly satisfied (delighted)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tunde at UNILAG is hungry ("},{"text":"need","bold":true},{"text":"). He specifically wants jollof rice with chicken ("},{"text":"want","bold":true},{"text":"). With ₦2,000 in his pocket and the willingness to buy, the want becomes a "},{"text":"demand","bold":true},{"text":"."}]},{"text":[{"text":"One need, different wants: a hungry person in Ibadan wants amala and ewedu; one in Enugu wants abacha. Culture shapes the want."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a desire with no money is still only a "},{"text":"want","bold":true},{"text":". Ada earns ₦250,000 a month with no savings or loan access and desires an ₦80 million SUV. ₦80,000,000 ÷ ₦250,000 = 320 months of her "},{"text":"entire","bold":true},{"text":" pay (about 26.7 years, rounded). Her desire is "},{"text":"a want that is not yet a demand","bold":true},{"text":"."}]},{"text":[{"text":"Worked value example: Bisi values the benefits of Phone A at ₦420,000; its total cost is ₦350,000 price + ₦20,000 transport and set-up = ₦370,000, so value = ₦420,000 − ₦370,000 = ₦50,000. Phone B: benefits ₦380,000, cost ₦300,000 + ₦10,000 = ₦310,000, so value = ₦380,000 − ₦310,000 = ₦70,000. She picks "},{"text":"Phone B","bold":true},{"text":", which gives more value even though Phone A has more benefits."}]},{"text":[{"text":"Chika expected her generator to run quietly for ten hours; it is noisy and stops after four. Performance fell short, so she is "},{"text":"dissatisfied","bold":true},{"text":"."}]}]}]},{"number":"1.3","title":"Exchange, transactions, relationships and markets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"4 ways to obtain a product:","bold":true},{"text":" self-production, coercion, begging, "},{"text":"exchange","bold":true},{"text":". Marketing is based on "},{"text":"exchange","bold":true},{"text":"."}]},{"text":[{"text":"Exchange:","bold":true},{"text":" the act of obtaining a desired object from someone by "},{"text":"offering something in return","bold":true},{"text":". It is the process through which transfer of ownership and rights takes place. "},{"text":"5 conditions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"There are "},{"text":"at least two parties","bold":true},{"text":"."}]},{"text":[{"text":"Each party has "},{"text":"something that might be of value","bold":true},{"text":" to the other."}]},{"text":[{"text":"Each party is "},{"text":"capable of communication and delivery","bold":true},{"text":"."}]},{"text":[{"text":"Each party is "},{"text":"free to accept or reject","bold":true},{"text":" the offer."}]},{"text":[{"text":"Each party believes it is "},{"text":"appropriate or desirable","bold":true},{"text":" to deal with the other."}]}]}]},{"text":[{"text":"Money is "},{"text":"not","bold":true},{"text":" a condition. Exchange is "},{"text":"value-creating","bold":true},{"text":": it normally leaves "},{"text":"both parties better off","bold":true},{"text":"."}]},{"text":[{"text":"Exchange is a "},{"text":"process","bold":true},{"text":" (parties negotiating towards agreement). When agreement is reached, a "},{"text":"transaction","bold":true},{"text":" takes place."}]},{"text":[{"text":"Transaction:","bold":true},{"text":" a "},{"text":"trade of values between two parties","bold":true},{"text":"; the basic unit of exchange. Elements: (1) at least two things of value; (2) agreed-upon conditions; (3) a time of agreement; (4) a place of agreement. No intermediary is required."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monetary transaction:","bold":true},{"text":" goods for money. "},{"text":"Barter transaction:","bold":true},{"text":" goods or services for other goods or services."}]}]}]},{"text":[{"text":"Transfer:","bold":true},{"text":" A gives to B but receives "},{"text":"nothing tangible in return","bold":true},{"text":" (gifts, donations, subsidies)."}]},{"text":[{"text":"Relationship marketing:","bold":true},{"text":" building, maintaining and enhancing "},{"text":"long-term, mutually satisfying relationships","bold":true},{"text":" with customers, rather than single sales (transaction marketing)."}]},{"text":[{"text":"Market:","bold":true},{"text":" the set of "},{"text":"all actual and potential buyers","bold":true},{"text":" of a product. (Traditionally also a physical place where buyers and sellers meet to exchange.)"}]},{"text":[{"text":"Marketer:","bold":true},{"text":" one who seeks a response (attention, purchase, vote, donation) from another party, the "},{"text":"prospect","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Robbers who take a traveller's phone and leave him some cash have not made an exchange: he was "},{"text":"not free to reject","bold":true},{"text":" the offer (coercion)."}]},{"text":[{"text":"A Kano tomato farmer and a Lagos restaurant owner who do not know of each other, with no way to send goods, lack condition 3, "},{"text":"communication and delivery","bold":true},{"text":"."}]},{"text":[{"text":"Benue farmer gives ten tubers of yam for a bag of fertiliser: "},{"text":"barter","bold":true},{"text":". Mrs Okafor pays ₦75,000 at Mile 12 for a bag of rice: "},{"text":"monetary transaction","bold":true},{"text":". A company donates food to flood victims in Kogi State: "},{"text":"transfer","bold":true},{"text":"."}]},{"text":[{"text":"Evolution of marketing (6 stages):","bold":true},{"text":" (1) "},{"text":"self-sufficient","bold":true},{"text":" stage (people produced what they consumed); (2) "},{"text":"barter","bold":true},{"text":" stage (goods for goods, before money); (3) "},{"text":"marketing system","bold":true},{"text":" stage (a fixed place for exchange, to save travelling); (4) "},{"text":"monetary","bold":true},{"text":" stage (currency, first metal, solved barter's problems); (5) "},{"text":"town marketing","bold":true},{"text":" (transport, communication and industry grew); (6) "},{"text":"international marketing","bold":true},{"text":" (worldwide trade, supported by bodies such as GATT, now the WTO, UNCTAD and ITC)."}]},{"text":[{"text":"Relationship marketing builds the long-term customer base that keeps firms like MTN and GTBank growing in a dynamic economy."}]}]}]},{"number":"1.4","title":"Functions of marketing and utility","mustKnow":[{"type":"paragraph","text":[{"text":"The traditional classification groups "},{"text":"8 functions","bold":true},{"text":" into "},{"text":"3","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Functions"}]],"rows":[[[{"text":"Exchange functions"}],[{"text":"1. Buying 2. Selling"}]],[[{"text":"Physical supply (physical distribution) functions"}],[{"text":"3. Transportation 4. Storage"}]],[[{"text":"Facilitating functions"}],[{"text":"5. Financing 6. Risk bearing 7. Standardisation and grading 8. Market information"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buying:","bold":true},{"text":" deciding what to buy, choosing suppliers and placing orders. "},{"text":"Selling:","bold":true},{"text":" finding buyers and persuading them to buy; transfers ownership."}]},{"text":[{"text":"Transportation:","bold":true},{"text":" moving goods from where they are produced to where they are wanted. "},{"text":"Storage:","bold":true},{"text":" holding goods from when they are produced until they are wanted."}]},{"text":[{"text":"Financing:","bold":true},{"text":" providing funds or credit to carry out marketing. "},{"text":"Risk bearing:","bold":true},{"text":" carrying the risk of loss (damage, theft, price falls), often through insurance. "},{"text":"Standardisation and grading:","bold":true},{"text":" setting standards and sorting products into classes by quality and size. "},{"text":"Market information:","bold":true},{"text":" gathering and analysing information on customers, competitors and the market (marketing research)."}]},{"text":[{"text":"Utility","bold":true},{"text":" (want-satisfying power) created:"}]}]},{"type":"table","header":[[{"text":"Utility"}],[{"text":"Created by"}]],"rows":[[[{"text":"Form"}],[{"text":"Production","bold":true},{"text":" (marketing guides it through product planning and development)"}]],[[{"text":"Place"}],[{"text":"Transportation"}]],[[{"text":"Time"}],[{"text":"Storage"}]],[[{"text":"Possession"}],[{"text":"Exchange (selling, credit and instalment terms)"}]],[[{"text":"Information"}],[{"text":"Research and promotion"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Kebbi miller buys paddy at harvest and sells in the lean season: "},{"text":"storage","bold":true},{"text":" (time utility). Trucks moving tomatoes from Kano to Lagos: "},{"text":"transportation","bold":true},{"text":" (place utility)."}]},{"text":[{"text":"Ondo cocoa sorted into Grade I and Grade II before export: "},{"text":"standardisation and grading","bold":true},{"text":". Lagos importer buying marine insurance: "},{"text":"risk bearing","bold":true},{"text":". Distributor letting supermarkets pay in 30 days: "},{"text":"financing","bold":true},{"text":". A noodles maker surveying Abuja shoppers and tracking rivals' prices: "},{"text":"market information","bold":true},{"text":". Supermarket choosing soap brands and placing orders: "},{"text":"buying","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" transportation is a "},{"text":"physical supply","bold":true},{"text":" function, not facilitating. Financing and risk bearing are facilitating, not exchange functions."}]},{"text":[{"text":"An Ikeja shop letting customers take home a ₦450,000 sofa today and pay monthly creates "},{"text":"possession utility","bold":true},{"text":". Form utility is the one mainly created by production, not marketing."}]}]}]},{"number":"1.5","title":"Importance of marketing","mustKnow":[{"type":"paragraph","text":[{"text":"The basic role of marketing is to "},{"text":"enhance the growth of economies and the standard of living of individuals","bold":true},{"text":". Marketing has been called \"the creation and delivery of a standard of living to society\"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To consumers (4):","bold":true},{"text":" customer satisfaction; selection facility (wider choice); product information; higher standard of living."}]},{"text":[{"text":"To the firm (4):","bold":true},{"text":" revenue generation (for survival and growth, by attracting and keeping customers); information for planning and decision-making; mass distribution; increase in goodwill (loyal, long-term customers)."}]},{"text":[{"text":"To society and the economy (5):","bold":true},{"text":" employment generation; poverty eradication; rise in standard of living; creation of utility; optimum utilisation of resources."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Jobs come from buying, selling, retailing, transport, advertising, warehousing and distribution. Good distribution systems for raw materials and finished goods speed up growth in developing countries."}]},{"text":[{"text":"Marketing "},{"text":"bridges the gap between consumer needs and available solutions","bold":true},{"text":", and creates societal value by aligning offerings with consumer needs and social welfare."}]},{"text":[{"text":"Marketing does "},{"text":"not","bold":true},{"text":" guarantee a monopoly, remove all business risk, end the need for production planning, or fix one price everywhere."}]},{"text":[{"text":"Firms such as Cadbury Nigeria and Nestlé Nigeria have stepped up marketing; formerly non-profit bodies such as NIPOST, once commercialised, now market to earn profit."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No single definition; know Stanton, Kotler, Kotler and Armstrong, CIM, AMA and \"meeting needs profitably\"."}]},{"text":[{"text":"Micromarketing = firm view; macromarketing = societal view; nonbusiness marketing = non-profits."}]},{"text":[{"text":"Needs (physical, social, individual) are not created by marketers; wants are shaped by culture; demands are wants plus buying power."}]},{"text":[{"text":"Perceived value = total benefits − total costs; satisfaction = performance vs expectations."}]},{"text":[{"text":"Exchange: 5 conditions, money not one; transaction = trade of values (barter or monetary); transfer = nothing tangible back."}]},{"text":[{"text":"Market = all actual and potential buyers; marketer seeks a response from a prospect."}]},{"text":[{"text":"8 functions: exchange (buying, selling), physical supply (transportation, storage), facilitating (financing, risk bearing, standardisation and grading, market information)."}]},{"text":[{"text":"Form utility comes mainly from production; marketing adds place, time, possession, information."}]},{"text":[{"text":"Marketing benefits consumers, firms and society; its basic role is economic growth and a higher standard of living."}]}]}],"theory":{"itemId":"332e0367-626a-5b48-8fc3-ecc4d2116468","question":[{"type":"paragraph","text":[{"text":"Classify each activity into its marketing function and group: (i) a warehouse holds yam until the lean season; (ii) a bank gives a distributor a 60-day trade loan; (iii) a trader negotiates and hands over goods to a buyer; (iv) eggs are sorted by size into crates."}]}]},"practice":[{"topic":"Meaning, Exchange Process and Functions of Marketing","named":false}]}},{"itemId":"e137ffa6-cdbd-5588-a055-332b8b33a255","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:10","parentItemId":null,"revision":1,"payload":{"title":"Marketing in the Digital and Social Media Era","body":"The meaning of digital marketing and e-marketing and how they differ from traditional marketing; the main digital channels (search, SEO and PPC, display, retargeting, content, email, mobile, affiliate, influencer, viral); social media marketing, its platforms, social commerce and e-commerce; paid, owned and earned media, user-generated content and eWOM; the advantages and challenges of digital marketing in Nigeria; and the six campaign metrics with their formulas.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"The meaning of digital marketing and e-marketing and how they differ from traditional marketing; the main digital channels (search, SEO and PPC, display, retargeting, content, email, mobile, affiliate, influencer, viral); social media marketing, its platforms, social commerce and e-commerce; paid, owned and earned media, user-generated content and eWOM; the advantages and challenges of digital marketing in Nigeria; and the six campaign metrics with their formulas."}],"lessons":[{"number":"10.1","title":"Meaning of digital marketing and how it differs from traditional marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing:","bold":true},{"text":" the use of digital channels and technologies, such as websites, search engines, social media, email and mobile apps, to promote products and engage customers."}]},{"text":[{"text":"E-marketing (internet or online marketing):","bold":true},{"text":" marketing products and services over the internet, through websites, online ads, email and similar tools. In an exam, treat it as the internet side of digital marketing."}]},{"text":[{"text":"Social media marketing:","bold":true},{"text":" using platforms such as Facebook, Instagram, TikTok, X (Twitter) and LinkedIn to build brand awareness, interact with customers and promote offers."}]},{"text":[{"text":"E-commerce:","bold":true},{"text":" buying and selling goods and services over the internet (e.g. Jumia, Konga, Jiji)."}]},{"text":[{"text":"Online advertising:","bold":true},{"text":" paid messages shown on the internet, e.g. a banner ad for a hotel on a Nigerian news website."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Traditional marketing"}],[{"text":"Digital marketing"}]],"rows":[[[{"text":"Media"}],[{"text":"Print, radio, TV, billboards, handbills"}],[{"text":"Websites, search, social media, email, mobile"}]],[[{"text":"Direction"}],[{"text":"Mostly one-way mass communication"}],[{"text":"Two-way and interactive: customers reply, comment, share"}]],[[{"text":"Targeting"}],[{"text":"Broad, by medium and location"}],[{"text":"Precise: by location, age, interests, behaviour"}]],[[{"text":"Measurement"}],[{"text":"Slow and approximate"}],[{"text":"Precise and real-time: views, clicks, sales"}]],[[{"text":"Cost"}],[{"text":"Often high entry cost"}],[{"text":"Can start small; low cost per person reached"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Is it digital or not?","bold":true},{"text":" A sponsored Instagram post, optimising a website to rank higher on search engines and an email newsletter are all digital marketing. Painting a shop's name on a roadside wall, a handbill at a bus stop, a jingle on a market loudspeaker and a billboard on Third Mainland Bridge are "},{"text":"not","bold":true},{"text":"; they are traditional (outdoor or print) methods."}]},{"text":[{"text":"The single feature that most clearly separates social media marketing from newspaper or TV advertising is "},{"text":"two-way, interactive communication","bold":true},{"text":". Options saying social media is \"one-way\", \"cannot be measured\" or \"cannot be targeted\" are always wrong."}]},{"text":[{"text":"Technology is a fast-changing force in the marketing environment: it creates opportunities to win market share and makes older products obsolete. Electronic banking cut banks' costs and made services more convenient; GTBank now serves many customers through apps and USSD."}]},{"text":[{"text":"New business models:","bold":true},{"text":" technology firms such as Uber, Airbnb and Amazon (in Nigeria, Bolt, Jumia and Paystack) have reshaped whole industries. Marketers should think in terms of the value delivered to the client and experiment with new pricing structures."}]},{"text":[{"text":"360-degree marketing:","bold":true},{"text":" be present wherever customers look for help, which is increasingly online. Firms that blend online and offline methods grow fastest and are most profitable; assuming \"my customers don't go online\" is risky."}]}]}]},{"number":"10.2","title":"The main digital marketing channels","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Search engine optimisation (SEO):","bold":true},{"text":" improving a website so it ranks higher in the "},{"text":"free (organic)","bold":true},{"text":" search results. The firm does not pay per click."}]},{"text":[{"text":"Pay-per-click (PPC) search advertising:","bold":true},{"text":" buying "},{"text":"sponsored listings","bold":true},{"text":" by bidding on keywords; the advertiser "},{"text":"pays each time the ad is clicked","bold":true},{"text":". SEO plus paid search together are broadly called "},{"text":"search engine marketing (SEM)","bold":true},{"text":", though some use SEM for paid search alone."}]},{"text":[{"text":"Display (banner) advertising:","bold":true},{"text":" image or video ads on other websites and apps."}]},{"text":[{"text":"Retargeting (remarketing):","bold":true},{"text":" showing ads to people who visited a site or viewed a product but left without buying, as they browse other websites and social media."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing valuable, relevant material (blog posts, how-to videos, infographics) to attract and engage a clearly defined audience "},{"text":"rather than directly pushing a sales message","bold":true},{"text":"."}]},{"text":[{"text":"Email marketing:","bold":true},{"text":" sending newsletters and offers by email. It should be "},{"text":"permission-based","bold":true},{"text":"."}]},{"text":[{"text":"Mobile marketing:","bold":true},{"text":" messages, promotions and content delivered through mobile phones: "},{"text":"SMS","bold":true},{"text":", in-app ads, mobile websites, and "},{"text":"location-based (geo-targeted)","bold":true},{"text":" offers sent when the phone is near a place."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" paying a "},{"text":"commission","bold":true},{"text":" to bloggers or website owners for "},{"text":"each sale","bold":true},{"text":" made through their special link or code."}]},{"text":[{"text":"Influencer marketing:","bold":true},{"text":" partnering with people who have a large or highly engaged online following (content creators, celebrities) so they recommend the brand to their followers."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" a message so entertaining or useful that people pass it on rapidly online; the "},{"text":"digital version of word-of-mouth","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Permission-based marketing:","bold":true},{"text":" sending messages only to people who have agreed ("},{"text":"opted in","bold":true},{"text":"), e.g. by subscribing to a newsletter."}]},{"text":[{"text":"Spam:","bold":true},{"text":" unsolicited, unwanted commercial messages sent in bulk to people who did not ask for them."}]},{"text":[{"text":"Micro-influencers:","bold":true},{"text":" smaller, more focused audiences that often show "},{"text":"higher engagement and trust","bold":true},{"text":" than celebrity (\"mega\") influencers."}]},{"text":[{"text":"Marketing automation:","bold":true},{"text":" software that automates large parts of marketing, such as follow-up emails, lead generation and lead nurturing."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SEO versus PPC","bold":true},{"text":" is the favourite trap. SEO = organic, earned over time, no fee per click. PPC = paid, instant, charged per click. An option saying \"SEO is paid per click\" or \"PPC is always free\" is reversed. A Lagos furniture store bidding on \"office chairs Lagos\" so its sponsored link sits at the top, paying only when someone clicks, is "},{"text":"PPC","bold":true},{"text":", not SEO."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" a Nigerian skincare brand posting free weekly videos on caring for skin in hot, humid weather, without asking viewers to buy, is content marketing. The sale comes later, from trust."}]},{"text":[{"text":"Mobile marketing in practice:","bold":true},{"text":" a supermarket texting customers who gave their numbers at checkout about a weekend discount is "},{"text":"SMS (mobile) marketing","bold":true},{"text":". A restaurant in Ikeja whose app sends an offer only when the customer is within 1 km is "},{"text":"location-based (geo-targeted) mobile marketing","bold":true},{"text":". MTN, Airtel and Glo also push offers by SMS and USSD."}]},{"text":[{"text":"Retargeting:","bold":true},{"text":" a student views a laptop on Jumia, leaves, and then sees the same laptop in ads on other sites for days. That is retargeting, not viral marketing or market testing."}]},{"text":[{"text":"Affiliate versus influencer:","bold":true},{"text":" the affiliate is paid "},{"text":"per sale","bold":true},{"text":" through a tracked link or code; the influencer is usually paid to "},{"text":"recommend","bold":true},{"text":". \"Commission per sale through a link\" means affiliate."}]},{"text":[{"text":"Hyper-targeted advertising:","bold":true},{"text":" online ads can now reach specific companies, job roles or niche interests, and link to downloadable content that proves expertise. This suits professional service firms that traditional mass advertising served poorly."}]},{"text":[{"text":"Permission versus spam:","bold":true},{"text":" opt-in lists get better responses; spam damages trust. In Nigeria, personal data is protected by the Nigeria Data Protection Act 2023."}]}]}]},{"number":"10.3","title":"Social media marketing, social commerce and types of media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Main platforms:","bold":true},{"text":" Facebook, Instagram, TikTok, X (Twitter), LinkedIn (professional and B2B), YouTube, WhatsApp."}]},{"text":[{"text":"Social commerce:","bold":true},{"text":" buying and selling directly within social media platforms, e.g. a vendor showing products in a "},{"text":"WhatsApp Business catalogue","bold":true},{"text":" and taking orders in the chat, or selling through Instagram shops."}]},{"text":[{"text":"User-generated content (UGC):","bold":true},{"text":" photos, videos, reviews and posts about a brand "},{"text":"created and shared by customers","bold":true},{"text":", not by the company."}]},{"text":[{"text":"Electronic word-of-mouth (eWOM):","bold":true},{"text":" positive or negative comments about products and brands that consumers share with each other through reviews, social media posts and online forums."}]}]},{"type":"paragraph","text":[{"text":"The three types of media (POE):","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Paid","bold":true}],[{"text":"Exposure the brand pays for"}],[{"text":"Boosted (sponsored) Instagram post, PPC ads, banner ads, paid influencer posts"}]],[[{"text":"Owned","bold":true}],[{"text":"Channels the brand itself controls"}],[{"text":"Its own website, Instagram page, company blog, app, email list"}]],[[{"text":"Earned","bold":true}],[{"text":"Free exposure others give the brand"}],[{"text":"An unpaid blogger's review, shares, mentions, press coverage, eWOM"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify carefully.","bold":true},{"text":" A fashion brand paying to \"boost\" its Instagram post into the feeds of 50,000 targeted users = "},{"text":"paid","bold":true},{"text":". The same brand's Instagram page itself = "},{"text":"owned","bold":true},{"text":". A food blogger, "},{"text":"not paid","bold":true},{"text":", posting a glowing review of a new Lekki restaurant that thousands share = "},{"text":"earned","bold":true},{"text":" for the restaurant. If money changes hands for the exposure, it is paid; if the brand runs the channel, it is owned; if others give it freely, it is earned."}]},{"text":[{"text":"Hashtag challenges:","bold":true},{"text":" a Nigerian telecoms brand that creates a branded hashtag and invites customers to post short dance videos, with data bundles as prizes, is aiming to "},{"text":"generate engagement and user-generated content that spreads the brand message","bold":true},{"text":". It does not replace distribution channels or set sales quotas."}]},{"text":[{"text":"Why UGC and eWOM matter:","bold":true},{"text":" buyers trust fellow customers more than the firm's adverts, so reviews and posts shape the information-search stage of buying."}]},{"text":[{"text":"Social commerce is huge in Nigeria:","bold":true},{"text":" many small vendors run their whole business through Instagram and WhatsApp, taking payment by bank transfer or through Paystack or Flutterwave links and delivering by dispatch rider."}]},{"text":[{"text":"E-commerce","bold":true},{"text":" is all online buying and selling (Jumia, Konga, a brand's own store); social commerce is the part that happens "},{"text":"inside","bold":true},{"text":" social platforms."}]}]}]},{"number":"10.4","title":"Advantages and challenges of digital marketing in Nigeria","mustKnow":[{"type":"paragraph","text":[{"text":"Advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Wide reach at relatively low cost;","bold":true},{"text":" a small business can start with a small budget."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" by location, age, interests and behaviour."}]},{"text":[{"text":"Measurable results:","bold":true},{"text":" clicks, views and sales can be measured precisely and quickly (real time)."}]},{"text":[{"text":"Two-way interaction:","bold":true},{"text":" quick conversation with customers; feedback and complaints are heard fast."}]},{"text":[{"text":"Always on:","bold":true},{"text":" customers can see offers and buy 24 hours a day, from anywhere."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" campaigns can be changed or stopped quickly based on results."}]},{"text":[{"text":"Relationship building:","bold":true},{"text":" regular contact through email, social media and content builds loyalty."}]}]},{"type":"paragraph","text":[{"text":"Challenges:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost of mobile data and unreliable power supply","bold":true},{"text":" limit how often some customers go online."}]},{"text":[{"text":"Online fraud and lack of trust:","bold":true},{"text":" some consumers fear being scammed and hesitate to pay online or share personal details, which slows online sales."}]},{"text":[{"text":"Negative messages spread fast","bold":true},{"text":" and are difficult for the firm to control."}]},{"text":[{"text":"Ad clutter and ad avoidance:","bold":true},{"text":" too many ads lead people to install ad blockers or ignore banner ads."}]},{"text":[{"text":"Uneven internet access and digital literacy,","bold":true},{"text":" especially in rural areas."}]},{"text":[{"text":"Privacy and data protection concerns,","bold":true},{"text":" and spam annoying customers."}]},{"text":[{"text":"Fast-changing platforms and algorithms,","bold":true},{"text":" which demand constant skills and effort; delivery and logistics problems for online orders."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT an advantage trap:","bold":true},{"text":" \"it guarantees that no customer will ever post a negative comment\" is false. Social media gives customers a public voice, so firms must manage complaints. Reach, targeting and two-way interaction are real advantages."}]},{"text":[{"text":"Spread of bad news:","bold":true},{"text":" a customer posts a video complaint about a Lagos bakery's spoiled cake and within hours it is shared thousands of times. This shows that negative messages spread quickly and are hard to control. The right response is fast, polite, public handling of the complaint."}]},{"text":[{"text":"Trust and payment:","bold":true},{"text":" cash on delivery is common on Jumia and in social commerce because many buyers fear online fraud; trusted payment gateways and clear return policies build confidence."}]},{"text":[{"text":"Ad avoidance","bold":true},{"text":" is not price discrimination or segmentation; it is consumers tuning out because of too many ads."}]},{"text":[{"text":"Options such as \"online results can never be measured\" or \"no Nigerians use mobile phones\" are false challenges."}]}]}]},{"number":"10.5","title":"Digital marketing metrics and computations","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Click-through rate (CTR)","bold":true},{"text":" = clicks / impressions x 100"}]},{"text":[{"text":"Cost per thousand impressions (CPM)","bold":true},{"text":" = total cost / impressions x 1,000"}]},{"text":[{"text":"Cost per click (CPC)","bold":true},{"text":" = total ad spend / number of clicks"}]},{"text":[{"text":"Conversion rate","bold":true},{"text":" = orders (conversions) / visitors (or clicks) x 100"}]},{"text":[{"text":"Engagement rate","bold":true},{"text":" = (likes + comments + shares) / followers x 100"}]},{"text":[{"text":"Return on ad spend (ROAS)","bold":true},{"text":" = revenue from ads / ad spend"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Impression:","bold":true},{"text":" one showing of an ad on a screen. "},{"text":"Click:","bold":true},{"text":" one tap or click on it. "},{"text":"Conversion:","bold":true},{"text":" the visitor does what you want (buys, signs up)."}]},{"text":[{"text":"Cost per acquisition (CPA)","bold":true},{"text":" = ad spend / number of orders: the cost of winning one customer."}]},{"text":[{"text":"Other things firms track: reach, website traffic, followers, likes, shares, comments."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example (one campaign, every metric).","bold":true},{"text":" A Lagos shoe store spends ₦60,000 on Instagram ads. The ads get 200,000 impressions and 1,500 clicks. 45 of the people who clicked place an order, at an average of ₦8,000 each."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CPM = 60,000 / 200,000 x 1,000 = 0.3 x 1,000 = "},{"text":"₦300","bold":true},{"text":" per thousand impressions."}]},{"text":[{"text":"CTR = 1,500 / 200,000 x 100 = 0.0075 x 100 = "},{"text":"0.75%","bold":true},{"text":"."}]},{"text":[{"text":"CPC = 60,000 / 1,500 = "},{"text":"₦40","bold":true},{"text":" per click."}]},{"text":[{"text":"Conversion rate = 45 / 1,500 x 100 = 0.03 x 100 = "},{"text":"3%","bold":true},{"text":"."}]},{"text":[{"text":"CPA = 60,000 / 45 = "},{"text":"₦1,333.33","bold":true},{"text":" per order (rounded to the nearest kobo)."}]},{"text":[{"text":"Revenue = 45 x 8,000 = ₦360,000. ROAS = 360,000 / 60,000 = "},{"text":"6","bold":true},{"text":" (₦6 of sales for every ₦1 of ads)."}]}]},{"type":"paragraph","text":[{"text":"Engagement rate example.","bold":true},{"text":" A Nigerian creator with 40,000 followers gets 1,200 likes, 300 comments and 100 shares on a sponsored post. Total engagements = 1,200 + 300 + 100 = 1,600. Engagement rate = 1,600 / 40,000 x 100 = 0.04 x 100 = "},{"text":"4%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Traps to avoid:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CTR","bold":true},{"text":" divides clicks by "},{"text":"impressions","bold":true},{"text":", never impressions by clicks. With 1,200 clicks from 80,000 impressions, CTR = 1,200 / 80,000 x 100 = "},{"text":"1.5%","bold":true},{"text":"; 66.67 is the upside-down answer and 0.015 forgets to multiply by 100."}]},{"text":[{"text":"CPM","bold":true},{"text":" must be multiplied by "},{"text":"1,000","bold":true},{"text":". ₦90,000 for 600,000 impressions: 90,000 / 600,000 = ₦0.15 per impression, x 1,000 = "},{"text":"₦150","bold":true},{"text":". ₦0.15 is the cost of one impression, not a thousand."}]},{"text":[{"text":"CPC","bold":true},{"text":" divides spend by clicks: ₦75,000 / 2,500 = "},{"text":"₦30","bold":true},{"text":". Clicks / spend gives 0.033, which is meaningless."}]},{"text":[{"text":"Conversion rate:","bold":true},{"text":" 120 orders from 4,000 visitors = 120 / 4,000 x 100 = "},{"text":"3%","bold":true},{"text":" (not 30% or 0.03%)."}]},{"text":[{"text":"Engagement rate","bold":true},{"text":" adds all three actions before dividing: (900 + 250 + 350) / 25,000 x 100 = 1,500 / 25,000 x 100 = "},{"text":"6%","bold":true},{"text":". Using likes alone (3.6%) is wrong."}]},{"text":[{"text":"ROAS","bold":true},{"text":" is a ratio, not a percentage: ₦1,800,000 / ₦400,000 = "},{"text":"4.5","bold":true},{"text":", meaning ₦4.50 of sales per ₦1 spent. The upside-down 0.22 is wrong, and 450 is not the ratio."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing = digital channels and technologies (websites, search, social media, email, mobile apps) to promote and engage; e-marketing = marketing over the internet."}]},{"text":[{"text":"Digital beats traditional on targeting, real-time measurement and two-way interaction; a painted wall, billboard or handbill is not digital."}]},{"text":[{"text":"SEO = free organic ranking; PPC = sponsored listing, pay per click; SEO + paid search = SEM."}]},{"text":[{"text":"Content (value, not hard sell), email (permission, not spam), mobile (SMS, geo-targeted), affiliate (commission per sale), influencer (micro = higher engagement), viral (digital word-of-mouth), retargeting (follows people who left)."}]},{"text":[{"text":"Social commerce = selling inside social platforms (WhatsApp Business catalogue); UGC = customer-made content; eWOM = consumers sharing opinions online."}]},{"text":[{"text":"Paid (boosted post), owned (own website, page, blog), earned (unpaid review, shares)."}]},{"text":[{"text":"Advantages: low cost, targeting, measurement, interaction. Challenges: data cost and power, fraud and trust, fast-spreading complaints, ad clutter and avoidance."}]},{"text":[{"text":"CTR = clicks / impressions x 100; CPM = cost / impressions x 1,000; CPC = spend / clicks; conversion = orders / visitors x 100; engagement = (likes + comments + shares) / followers x 100; ROAS = revenue / ad spend."}]}]}],"theory":{"itemId":"8c974dc1-db1b-54a4-b759-12161523332f","question":[{"type":"paragraph","text":[{"text":"An online store in Abuja spends ₦150,000 on a display campaign that delivers 500,000 impressions and 2,000 clicks. 80 of those visitors buy, producing ₦600,000 in sales. Calculate the CPM, CTR, CPC, conversion rate and ROAS."}]}]},"practice":[{"topic":"Marketing in the Digital and Social Media Era","named":false}]}},{"itemId":"2a99914d-dc35-5d15-872e-bb9950ba0689","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Marketing Management","body":"The definitions of marketing management and why it is called demand management; the eight demand states and the marketing task that matches each; the marketing management process (analysis, planning, implementation, control); the marketing plan, marketing control and the marketing audit; appraising the marketing effort; the importance of marketing management.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The definitions of marketing management and why it is called demand management; the eight demand states and the marketing task that matches each; the marketing management process (analysis, planning, implementation, control); the marketing plan, marketing control and the marketing audit; appraising the marketing effort; the importance of marketing management."}],"lessons":[{"number":"2.1","title":"Meaning of marketing management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management (Kotler and Keller):","bold":true},{"text":" the art and science of choosing target markets and "},{"text":"getting, keeping and growing customers","bold":true},{"text":" through creating, delivering and communicating superior customer value."}]},{"text":[{"text":"Marketing management (Kotler and Armstrong):","bold":true},{"text":" the art and science of choosing target markets and "},{"text":"building profitable relationships","bold":true},{"text":" with them."}]},{"text":[{"text":"Process definition:","bold":true},{"text":" the process of planning and executing the conception, pricing, promotion and distribution of ideas, goods and services "},{"text":"to create exchanges that satisfy individual and organisational objectives","bold":true},{"text":". Note the four elements inside it: conception (product), pricing (price), promotion (promotion), distribution (place)."}]},{"text":[{"text":"Demand management:","bold":true},{"text":" marketing management is described as demand management because the marketing manager's task is to "},{"text":"influence the level, timing and composition of demand","bold":true},{"text":" so that the firm meets its objectives. It is not only about pushing demand up."}]},{"text":[{"text":"Two basic questions","bold":true},{"text":" every marketing manager must answer:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"\"What customers will we serve?\" The answer is the "},{"text":"target market","bold":true},{"text":"."}]},{"text":[{"text":"\"How can we serve these customers best?\" The answer is the "},{"text":"value proposition","bold":true},{"text":": the set of benefits or values the firm promises to deliver to satisfy customer needs."}]}]}]},{"text":[{"text":"Art and science:","bold":true},{"text":" it uses systematic research and analysis (science) as well as creativity and judgement (art)."}]},{"text":[{"text":"Scope:","bold":true},{"text":" relevant to "},{"text":"both profit-seeking businesses and non-profit organisations","bold":true},{"text":", to goods and services, small and large firms, local and export markets."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Read the definitions carefully in the exam. If a gap follows \"choosing target markets and ____ through creating, delivering and communicating superior customer value\", the answer is \"getting, keeping and growing customers\". If the stem says \"choosing target markets and building ____ with them\", the answer is \"profitable relationships\"."}]},{"text":[{"text":"In the process definition, the purpose is "},{"text":"to create exchanges that satisfy individual and organisational objectives","bold":true},{"text":". It is not about reducing government control, hiring more staff or manufacturing at the lowest cost."}]},{"text":[{"text":"Trap on demand management: \"always push demand up to the highest possible level\" is wrong. Sometimes the manager must reduce demand (demarketing) or shift it in time (synchromarketing). \"Leave demand to market forces\" and \"fix national prices\" are also wrong."}]},{"text":[{"text":"Example: MTN deciding to serve students (target market) with cheap night data bundles and fast campus coverage (value proposition) has answered both questions."}]},{"text":[{"text":"Non-profit use: NAFDAC campaigns against fake drugs, a church growing its membership or a state immunisation drive all use marketing management."}]}]}]},{"number":"2.2","title":"Demand states and the types of marketing management","mustKnow":[{"type":"paragraph","text":[{"text":"A firm can face any of "},{"text":"eight demand states","bold":true},{"text":". Each has its own marketing task, and the task gives its name to a "},{"text":"type of marketing management","bold":true},{"text":"."}]},{"type":"table","header":[[{"text":"Demand state"}],[{"text":"What it means"}],[{"text":"Marketing task (type)"}]],"rows":[[[{"text":"1. Negative demand"}],[{"text":"A large part of the market dislikes the product and may even pay to avoid it"}],[{"text":"Conversional marketing","bold":true},{"text":": find out why people dislike it and change their attitude"}]],[[{"text":"2. No demand"}],[{"text":"Target consumers are unaware of, or uninterested in, the product"}],[{"text":"Stimulational marketing","bold":true},{"text":": create awareness and interest; link the product to a need"}]],[[{"text":"3. Latent demand"}],[{"text":"Many consumers share a strong need that no existing product satisfies"}],[{"text":"Developmental marketing","bold":true},{"text":": measure the potential market and develop products that satisfy the unmet need"}]],[[{"text":"4. Falling (faltering, declining) demand"}],[{"text":"Demand for a product is dropping"}],[{"text":"Remarketing","bold":true},{"text":": revive demand by re-targeting, changing the product or the communication"}]],[[{"text":"5. Irregular demand"}],[{"text":"Demand varies by season, day or even hour, causing idle or overworked capacity"}],[{"text":"Synchromarketing","bold":true},{"text":": match the timing of demand to supply through flexible pricing, promotion and incentives"}]],[[{"text":"6. Full demand"}],[{"text":"The firm is satisfied with its current volume of business"}],[{"text":"Maintenance marketing","bold":true},{"text":": keep demand at that level despite changing preferences and rising competition"}]],[[{"text":"7. Overfull demand"}],[{"text":"Demand is higher than the firm can or wants to handle"}],[{"text":"Demarketing","bold":true},{"text":": reduce demand temporarily or permanently, e.g. raise prices, cut promotion and service"}]],[[{"text":"8. Unwholesome demand"}],[{"text":"Demand for products considered harmful (hard drugs, cigarettes, illegal guns)"}],[{"text":"Countermarketing","bold":true},{"text":": try to destroy the demand entirely"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demarketing vs countermarketing:","bold":true},{"text":" demarketing "},{"text":"reduces","bold":true},{"text":" demand for an "},{"text":"acceptable","bold":true},{"text":" product; countermarketing tries to "},{"text":"destroy","bold":true},{"text":" demand for a "},{"text":"harmful","bold":true},{"text":" product."}]},{"text":[{"text":"Not demand states:","bold":true},{"text":" elastic, inelastic, derived, joint demand. These are economics or business-buying terms, not the eight demand states."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory chain (state, then task): Negative, Convert; No demand, Stimulate; Latent, Develop; Falling, Remarket; Irregular, Synchronise; Full, Maintain; Overfull, Demarket; Unwholesome, Counter."}]},{"text":[{"text":"Negative demand / conversional:","bold":true},{"text":" parents in a rural community avoid free immunisation because they fear side effects. The task is to learn the reason (fear) and change the attitude, e.g. through trusted community and religious leaders."}]},{"text":[{"text":"No demand / stimulational:","bold":true},{"text":" farmers who have never heard of a solar-powered irrigation pump show no interest. The task is to create awareness: demonstrations, free trials, extension workers."}]},{"text":[{"text":"Latent demand / developmental:","bold":true},{"text":" Lagos commuters want a fast, safe, affordable way to beat traffic that no service satisfies. The firm that measures this need and builds a fitting service (as the Lagos rail lines and ride-hailing firms tried) is doing developmental marketing."}]},{"text":[{"text":"Falling demand / remarketing:","bold":true},{"text":" a once-popular malt drink sees sales fall for three years; the company changes the packaging, adds a new flavour and targets new age groups. That is remarketing."}]},{"text":[{"text":"Irregular demand / synchromarketing:","bold":true},{"text":" a Lekki cinema is packed on Friday and Saturday nights but empty on weekday afternoons, so it sells half-price weekday tickets. Calabar hotels are full in December (carnival season) but empty the rest of the year: that state is "},{"text":"irregular demand","bold":true},{"text":", not overfull or latent."}]},{"text":[{"text":"Full demand / maintenance:","bold":true},{"text":" a market leader such as Indomie keeps quality steady, keeps distribution wide and keeps advertising to hold its position."}]},{"text":[{"text":"Overfull demand / demarketing:","bold":true},{"text":" in a severe dry season a state water corporation asks residents to cut water use and charges more for very high use. The product (water) is good; the firm simply cannot meet all the demand."}]},{"text":[{"text":"Unwholesome demand / countermarketing:","bold":true},{"text":" a national agency (for example the NDLEA) runs school campaigns on the dangers of hard drugs to stop young people wanting them at all."}]},{"text":[{"text":"Trap: in a \"NOT correctly matched\" question, look for a swap such as \"Irregular demand: remarketing\". Irregular goes with synchromarketing; remarketing goes with falling demand."}]},{"text":[{"text":"Trap: conversional marketing is about "},{"text":"changing a negative attitude","bold":true},{"text":", while stimulational marketing is about "},{"text":"creating awareness among people who have never heard of the product","bold":true},{"text":". Reviving falling sales is remarketing; shifting demand between busy and quiet periods is synchromarketing."}]}]}]},{"number":"2.3","title":"The marketing management process: analysis and planning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The marketing management process (4 stages, in order):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Marketing analysis","bold":true}]},{"text":[{"text":"Marketing planning","bold":true}]},{"text":[{"text":"Marketing implementation","bold":true}]},{"text":[{"text":"Marketing control","bold":true}]}]}]},{"text":[{"text":"The same process is also written as: (1) analysing marketing opportunities, (2) selecting (researching and choosing) target markets, (3) developing the marketing mix (designing strategy and the 4Ps programme), (4) managing the marketing effort, which itself means "},{"text":"planning, implementation and control","bold":true},{"text":". Both versions start with analysis and end with control."}]},{"text":[{"text":"Marketing analysis:","bold":true},{"text":" the "},{"text":"first","bold":true},{"text":" stage; a complete study of the company's situation: customers, competitors, the economy and the wider environment, and the firm's own strengths and weaknesses."}]},{"text":[{"text":"SWOT analysis:","bold":true},{"text":" the main tool of marketing analysis."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Strengths and weaknesses:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" capabilities and limitations within the firm."}]},{"text":[{"text":"Opportunities and threats:","bold":true},{"text":" "},{"text":"external","bold":true},{"text":" factors the firm may exploit (opportunities) or must guard against (threats)."}]}]}]},{"text":[{"text":"Marketing planning:","bold":true},{"text":" the process by which "},{"text":"marketing plans are developed for products","bold":true},{"text":" (brands, product lines). It decides marketing objectives and strategies and prepares the marketing plan."}]},{"text":[{"text":"Sections of a marketing plan (8):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Executive summary"}]},{"text":[{"text":"Current marketing situation"}]},{"text":[{"text":"Threats and opportunities analysis (with strengths and weaknesses)"}]},{"text":[{"text":"Objectives and issues"}]},{"text":[{"text":"Marketing strategy"}]},{"text":[{"text":"Action programmes"}]},{"text":[{"text":"Budgets"}]},{"text":[{"text":"Controls"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not confuse the levels of planning. "},{"text":"Strategic planning","bold":true},{"text":" is company-wide and long-term: it sets the mission, objectives and business portfolio of the whole firm. "},{"text":"Marketing planning","bold":true},{"text":" works inside it and produces plans for each product, brand or market. Short-term and medium-term planning describe time spans, not the process of producing product plans."}]},{"text":[{"text":"SWOT example: a Surulere bakery hears that a well-funded rival will soon open nearby selling cheaper bread. That rival is outside the bakery, so it is a "},{"text":"threat","bold":true},{"text":". The bakery's loyal customers would be a strength; its old oven a weakness; a new estate opening next door an opportunity."}]},{"text":[{"text":"Analysis example: before next year's plan, a telecom firm studies its customers, competitors and the economy and lists its strengths and weaknesses. That is "},{"text":"marketing analysis","bold":true},{"text":", the first stage."}]},{"text":[{"text":"Planning example: a drinks company decides it will launch a new juice in Abuja, aiming for 10% market share, positioned as a healthy school-lunch drink. Deciding the objective and strategy is planning."}]},{"text":[{"text":"A marketing plan never contains things like each employee's personal tax records; that is not a marketing matter."}]}]}]},{"number":"2.4","title":"Implementation, control and the marketing audit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing implementation:","bold":true},{"text":" the process that "},{"text":"turns marketing strategies and plans into marketing actions","bold":true},{"text":" in order to accomplish marketing objectives."}]},{"text":[{"text":"Planning vs implementation:","bold":true},{"text":" planning addresses the "},{"text":"what","bold":true},{"text":" and "},{"text":"why","bold":true},{"text":" of marketing activities; implementation addresses the "},{"text":"who, where, when and how","bold":true},{"text":"."}]},{"text":[{"text":"A brilliant marketing strategy counts for little if the company fails to implement it properly. Results do not follow automatically from a written plan."}]},{"text":[{"text":"Marketing control:","bold":true},{"text":" measuring and evaluating the results of marketing strategies and plans and "},{"text":"taking corrective action","bold":true},{"text":" to ensure that objectives are achieved."}]},{"text":[{"text":"The control process (4 steps, in order):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set goals","bold":true},{"text":" (what the firm wants to achieve)"}]},{"text":[{"text":"Measure performance","bold":true},{"text":" in the market"}]},{"text":[{"text":"Evaluate the causes","bold":true},{"text":" of any gap between expected and actual performance"}]},{"text":[{"text":"Take corrective action","bold":true},{"text":" to close the gap (this may mean changing the action programmes or even the goals)"}]}]}]},{"text":[{"text":"Operating control:","bold":true},{"text":" checks ongoing performance "},{"text":"against the annual plan","bold":true},{"text":" and takes corrective action when needed (sales, market share, costs)."}]},{"text":[{"text":"Strategic control:","bold":true},{"text":" checks whether the company's "},{"text":"basic strategies still fit its opportunities","bold":true},{"text":" in a changing environment."}]},{"text":[{"text":"Four types of marketing control:","bold":true},{"text":" annual-plan control, profitability control, efficiency control, strategic control."}]},{"text":[{"text":"Marketing audit:","bold":true},{"text":" a "},{"text":"comprehensive, systematic, independent and periodic","bold":true},{"text":" examination of a company's environment, objectives, strategies and activities to determine problem areas and opportunities and to recommend a plan of action. It is the main tool of strategic control."}]},{"text":[{"text":"Formula (control variance):","bold":true},{"text":" Variance = Target - Actual; Variance % = (Target - Actual) / Target x 100; Achievement % = Actual / Target x 100."}]}]},{"type":"paragraph","text":[{"text":"Appraising the marketing effort","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing effort:","bold":true},{"text":" the total resources a firm commits to its marketing mix to stimulate demand for its product. Appraisal checks how well the marketing mix was implemented."}]},{"text":[{"text":"2 ways to appraise:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Subjective evaluation:","bold":true},{"text":" based on rules of thumb and experience, not a set standard; inaccurate and biased, so not advisable."}]},{"text":[{"text":"Objective evaluation:","bold":true},{"text":" uses the scientific (systematic) approach, grouped into 3 processes: problem identification, modelling (representing a real-life situation), implementation."}]}]}]},{"text":[{"text":"6 steps in objective appraisal:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set the standard"}]},{"text":[{"text":"Collect information on performance in each marketing-mix area"}]},{"text":[{"text":"Collate the performance information"}]},{"text":[{"text":"Analyse the collated information"}]},{"text":[{"text":"Compare the results with the standard"}]},{"text":[{"text":"Take corrective action if needed"}]}]}]},{"text":[{"text":"Effective objective appraisal needs an efficient "},{"text":"marketing information system","bold":true},{"text":" giving authentic, adequate and timely feedback from all marketing-mix components."}]},{"text":[{"text":"2 appraisal strategies:","bold":true},{"text":" periodic marketing effort appraisal ("},{"text":"PMEA","bold":true},{"text":") and continuous marketing effort appraisal ("},{"text":"CMEA","bold":true},{"text":")."}]},{"text":[{"text":"2 difficulties in appraisal:","bold":true},{"text":" it is hard to isolate and measure the impact of environmental forces; it is hard to measure intangible aspects such as consumer satisfaction, attitude and brand image."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Implementation example: a drinks company has approved its plan to launch a juice in Abuja. The team now assigns staff, books the launch venue, schedules radio adverts and arranges delivery to retailers. That is "},{"text":"implementation","bold":true},{"text":" (who, where, when, how)."}]},{"text":[{"text":"Control example: halfway through the year, a paint company's sales manager finds northern sales well below target (measure), discovers the cause is weak distributor support (evaluate), and adds distributor incentives (correct). That is "},{"text":"control","bold":true},{"text":"."}]},{"text":[{"text":"Worked computation: a paint company's northern target for the half-year is ₦60,000,000; actual sales are ₦51,000,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Variance = ₦60,000,000 - ₦51,000,000 = ₦9,000,000 shortfall."}]},{"text":[{"text":"Variance % = 9,000,000 / 60,000,000 x 100 = 15%."}]},{"text":[{"text":"Achievement % = 51,000,000 / 60,000,000 x 100 = 85%."}]},{"text":[{"text":"The manager now finds the cause of the 15% gap and corrects it."}]}]}]},{"text":[{"text":"Trap: the order of control is goals, measure, evaluate, correct. Any option starting with \"measure\" or \"take corrective action\" is wrong."}]},{"text":[{"text":"Trap: operating control is about this year's plan; strategic control is about whether the whole strategy still fits. A marketing audit is not a SWOT analysis (SWOT is one part of analysis), not a sales forecast and not the marketing plan itself."}]},{"text":[{"text":"Objective appraisal steps mirror the control steps: standard first, corrective action last."}]}]}]},{"number":"2.5","title":"Importance of marketing management","mustKnow":[{"type":"paragraph","text":[{"text":"To the organisation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coordinates product, price, promotion and distribution decisions towards the firm's objectives."}]},{"text":[{"text":"Helps the firm match its offerings to market demand."}]},{"text":[{"text":"Guides decisions on target markets and the marketing mix."}]},{"text":[{"text":"Helps the firm identify and respond to changes in customer needs and the environment."}]},{"text":[{"text":"Generates revenue and profit and supports growth and survival."}]},{"text":[{"text":"Builds customer satisfaction, loyalty and long-term relationships."}]},{"text":[{"text":"Provides information for planning and decision-making."}]},{"text":[{"text":"Helps the firm meet competition."}]}]},{"type":"paragraph","text":[{"text":"To society and the economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Helps direct scarce resources towards the goods and services people want."}]},{"text":[{"text":"Raises the standard of living by making a wide variety of products available."}]},{"text":[{"text":"Creates employment in selling, advertising, distribution and research."}]},{"text":[{"text":"Supports economic growth by matching production with consumption."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management does "},{"text":"not","bold":true},{"text":" guarantee that a firm will never make a loss, that rivals will leave the market or that all firms will charge the same price. It does not remove the need for finance or production departments, nor for consumer protection laws such as the Federal Competition and Consumer Protection Act 2018 enforced by the FCCPC."}]},{"text":[{"text":"It does not reduce product variety or let a firm ignore customer needs; those options describe the opposite of good marketing management."}]},{"text":[{"text":"Example: Dangote Cement uses research on housing demand to plan where to build plants and depots, so resources flow to where cement is needed. That is resource direction (a benefit to society) and matching supply to demand (a benefit to the firm)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management: the art and science of choosing target markets and getting, keeping and growing customers through superior customer value."}]},{"text":[{"text":"It is demand management: influencing the level, timing and composition of demand."}]},{"text":[{"text":"Two questions: whom to serve (target market) and how best to serve them (value proposition)."}]},{"text":[{"text":"Eight states and tasks: negative-conversional, no-stimulational, latent-developmental, falling-remarketing, irregular-synchromarketing, full-maintenance, overfull-demarketing, unwholesome-countermarketing."}]},{"text":[{"text":"Demarketing reduces demand for a good product; countermarketing destroys demand for a harmful one."}]},{"text":[{"text":"Process: analysis, planning, implementation, control."}]},{"text":[{"text":"SWOT: strengths and weaknesses internal; opportunities and threats external."}]},{"text":[{"text":"Planning is what and why; implementation is who, where, when and how."}]},{"text":[{"text":"Control: set goals, measure, evaluate causes, correct. Marketing audit: comprehensive, systematic, independent, periodic."}]},{"text":[{"text":"Marketing management serves profit and non-profit organisations alike."}]}]}],"theory":{"itemId":"66f699b8-e513-5bcb-ac28-6a033edfb3ae","question":[{"type":"paragraph","text":[{"text":"A Lagos ferry operator's target for the first quarter was ₦12,000,000 in fares, but actual fares were ₦9,600,000. Boats are full at rush hours but nearly empty at midday. (a) Compute the shortfall and the achievement rate. (b) Name the demand state and the matching marketing task, and say which stage of the marketing management process the computation belongs to."}]}]},"practice":[{"topic":"Marketing Management","named":false}]}},{"itemId":"786335a6-6560-586f-b91b-955c4f65ac61","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"Marketing Concepts and Market Orientation","body":"What a marketing concept (philosophy) is; the five competing concepts in order (production, product, selling, marketing, societal) plus holistic/relationship marketing; each concept's core assumption, focus, strengths and dangers; the selling versus marketing contrast; and market orientation with its three behavioural components and two decision criteria.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a marketing concept (philosophy) is; the five competing concepts in order (production, product, selling, marketing, societal) plus holistic/relationship marketing; each concept's core assumption, focus, strengths and dangers; the selling versus marketing contrast; and market orientation with its three behavioural components and two decision criteria."}],"lessons":[{"number":"3.1","title":"Meaning of a marketing concept and the order of evolution","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing concept (broad sense) / marketing management philosophy:","bold":true},{"text":" the guiding idea about what should drive a firm's marketing activities, and how much weight to give the interests of the "},{"text":"organisation","bold":true},{"text":", "},{"text":"customers","bold":true},{"text":" and "},{"text":"society","bold":true},{"text":". It is a business philosophy and an attitude of mind that the whole organisation must adopt, not just the marketing department."}]},{"text":[{"text":"5 major competing concepts","bold":true},{"text":" of marketing activities in organisations:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production concept"}]},{"text":[{"text":"Product concept"}]},{"text":[{"text":"Selling (sales) concept"}]},{"text":[{"text":"Marketing concept"}]},{"text":[{"text":"Societal marketing concept"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Newer thinking adds the "},{"text":"holistic marketing concept","bold":true},{"text":" (with relationship marketing inside it)."}]},{"text":[{"text":"Order of development:","bold":true},{"text":" production → selling → marketing → societal marketing. (The product concept is usually left out of this four-step sequence.)"}]},{"text":[{"text":"Direction of the shift:","bold":true},{"text":" from product-centric efficiency towards "},{"text":"customer-centric value creation","bold":true},{"text":", with an increasing emphasis on customer "},{"text":"and","bold":true},{"text":" societal needs."}]}]},{"type":"table","header":[[{"text":"Concept"}],[{"text":"Consumers will favour..."}],[{"text":"So the firm should..."}]],"rows":[[[{"text":"Production"}],[{"text":"products widely available and low in price"}],[{"text":"improve production and distribution efficiency"}]],[[{"text":"Product"}],[{"text":"products of the highest quality, performance, features"}],[{"text":"keep improving the product"}]],[[{"text":"Selling"}],[{"text":"not buy enough unless persuaded"}],[{"text":"sell and promote aggressively"}]],[[{"text":"Marketing"}],[{"text":"products that meet their needs better than rivals'"}],[{"text":"find needs, then satisfy them"}]],[[{"text":"Societal marketing"}],[{"text":"the above, done in a way that protects long-run welfare"}],[{"text":"balance profit, wants and society's interests"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inside-out:","bold":true},{"text":" starts from the factory and the firm's existing products (production, product, selling)."}]},{"text":[{"text":"Outside-in:","bold":true},{"text":" starts from the market and customer needs, then coordinates the firm to satisfy them (marketing, societal)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"You will also meet the older split between the "},{"text":"traditional concept","bold":true},{"text":" of marketing (narrow, product oriented: the physical transfer of goods for money) and the "},{"text":"modern concept","bold":true},{"text":" (broad, customer oriented: earning profit through customer satisfaction). The traditional view lines up with the production, product and selling concepts; the modern view with the marketing and societal concepts."}]},{"text":[{"text":"Never put the marketing concept before the selling concept: firms turned to customer needs only after aggressive selling stopped working. Later concepts did not wipe out earlier ones; many Nigerian firms still think in production or selling terms today."}]}]}]},{"number":"3.2","title":"The production and product concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production concept:","bold":true},{"text":" consumers will buy (favour) products that are "},{"text":"widely available","bold":true},{"text":" and "},{"text":"low in price","bold":true},{"text":". Management should concentrate on "},{"text":"high production efficiency","bold":true},{"text":" and "},{"text":"widespread distribution","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"earliest","bold":true},{"text":" philosophy; it describes business in the "},{"text":"late 1800s","bold":true},{"text":" and early industrial era."}]},{"text":[{"text":"Emerged in response to "},{"text":"industrial advancements enabling mass production","bold":true},{"text":", when "},{"text":"demand for goods was greater than supply","bold":true},{"text":"."}]},{"text":[{"text":"Primary objective: "},{"text":"maximising output and distribution efficiency","bold":true},{"text":"; firms succeeded through "},{"text":"economies of scale and broad distribution","bold":true},{"text":"."}]},{"text":[{"text":"Still useful when (1) "},{"text":"demand exceeds supply","bold":true},{"text":", or (2) the product's "},{"text":"cost is too high","bold":true},{"text":" and must be brought down."}]},{"text":[{"text":"Its assumption is challenged when consumers "},{"text":"prioritise quality and differentiation over price","bold":true},{"text":"."}]},{"text":[{"text":"Main danger:","bold":true},{"text":" the firm becomes so focused on its own operations and efficiency that it "},{"text":"loses sight of satisfying customers' needs","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Product concept:","bold":true},{"text":" consumers will buy (favour) products of the "},{"text":"highest quality","bold":true},{"text":", most "},{"text":"performance","bold":true},{"text":" and most "},{"text":"innovative features","bold":true},{"text":". Management should make continuous product improvements."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Based on the "},{"text":"\"technology-push\"","bold":true},{"text":" model of innovation: products designed by engineers and scientists for consumers to use."}]},{"text":[{"text":"Trap: \"build a better mousetrap and customers will beat a path to your door\", while ignoring what customers actually want."}]},{"text":[{"text":"Leads to "},{"text":"marketing myopia","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Marketing myopia","bold":true},{"text":" (Theodore Levitt, 1960): an undue concentration on the "},{"text":"product","bold":true},{"text":" rather than on the "},{"text":"customer need or benefit","bold":true},{"text":" it provides."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production example:","bold":true},{"text":" a Kano noodle maker facing demand far above supply adds production lines, cuts unit costs and spreads distribution so more homes can afford a ₦250 pack. That is the production concept. Dangote Cement pushing scale and low cost per bag uses the same logic."}]},{"text":[{"text":"Hyundai (cars) and Goldstar, Sharp and Sanyo (electronics) succeeded with low-cost production abroad. So the production concept \"has a place\" today, but focusing on production while ignoring customers is as faulty as focusing on customers while ignoring production efficiency."}]},{"text":[{"text":"Product example:","bold":true},{"text":" a Lagos electronics firm keeps adding ports, a torch and a radio to its power bank because managers believe buyers always choose the most advanced model, but never asks what buyers need. That is the product concept. The slogan \"good thinking, good product\" in a car advertisement in Nigeria reflected the same product orientation."}]},{"text":[{"text":"Myopia examples:","bold":true},{"text":" railway managers thought users wanted "},{"text":"trains","bold":true},{"text":" rather than "},{"text":"transportation","bold":true},{"text":" and missed the threat from airlines, buses, trucks and cars. Slide-rule makers thought engineers wanted slide rules rather than "},{"text":"calculating capacity","bold":true},{"text":" and lost to pocket calculators. Such firms are \"looking into a mirror when they should be looking out of the window\"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"widely available and low in price\" = production; \"highest quality\" = product. Options often swap these two."}]}]}]},{"number":"3.3","title":"The selling concept and the marketing concept","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selling (sales) concept:","bold":true},{"text":" consumers will not buy enough of the firm's products unless it undertakes a "},{"text":"large-scale selling and promotion effort","bold":true},{"text":". Put another way: the firm "},{"text":"produces what it wants","bold":true},{"text":" and then makes great efforts to "},{"text":"convince consumers","bold":true},{"text":" to buy."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Became dominant mainly because of "},{"text":"overproduction","bold":true},{"text":" and the need to "},{"text":"clear inventory","bold":true},{"text":"; it thrives where consumers need convincing because of "},{"text":"surplus goods","bold":true},{"text":" (supply exceeds demand)."}]},{"text":[{"text":"Gained traction when firms needed to "},{"text":"overcome consumer resistance through persuasion","bold":true},{"text":"."}]},{"text":[{"text":"Goes hand in hand with "},{"text":"high-pressure selling","bold":true},{"text":"; the "},{"text":"\"sales-push\"","bold":true},{"text":" model, pushing unwanted products through the channel."}]},{"text":[{"text":"Typically practised with "},{"text":"unsought goods","bold":true},{"text":" (goods buyers do not normally think of buying, such as insurance or burial plots)."}]},{"text":[{"text":"Risky assumption:","bold":true},{"text":" customers coaxed into buying will like the product, or if not, will forget their disappointment and buy again."}]},{"text":[{"text":"Major limitation:","bold":true},{"text":" focuses on "},{"text":"short-term sales","bold":true},{"text":" over long-term customer loyalty; aims at making the sale, not building relationships."}]}]}]},{"text":[{"text":"Marketing concept:","bold":true},{"text":" achieving organisational goals depends on "},{"text":"knowing the needs and wants of target markets","bold":true},{"text":" and "},{"text":"delivering the desired satisfactions better than competitors","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic form: the identification and satisfaction of customers' needs and wants. "},{"text":"Broadened form:","bold":true},{"text":" doing so "},{"text":"more effectively and efficiently than competitors","bold":true},{"text":"."}]},{"text":[{"text":"Origin: Drucker (1954), McKitterick (1958) and Levitt (1960); all agree the purpose of business is to "},{"text":"create a satisfied customer","bold":true},{"text":"."}]},{"text":[{"text":"Emerged as a response to "},{"text":"heightened competition and evolving consumer expectations","bold":true},{"text":"."}]},{"text":[{"text":"Hinges on "},{"text":"aligning offerings with customer needs and desires","bold":true},{"text":"; success = "},{"text":"delivering what customers value, profitably","bold":true},{"text":"; customer satisfaction drives profitability."}]},{"text":[{"text":"Slogans: "},{"text":"\"sense and respond\"","bold":true},{"text":", not \"make and sell\"; find the "},{"text":"right products for your customers","bold":true},{"text":", not the right customers for your products."}]},{"text":[{"text":"4 pillars:","bold":true},{"text":" (1) target market, (2) customer needs, (3) integrated marketing, (4) profitability."}]},{"text":[{"text":"Integrated marketing:","bold":true},{"text":" all the firm's departments and marketing activities work together to serve the customer's interests."}]}]}]}]},{"type":"table","header":[[],[{"text":"Starting point"}],[{"text":"Focus"}],[{"text":"Means"}],[{"text":"Ends"}]],"rows":[[[{"text":"Selling concept"}],[{"text":"Factory"}],[{"text":"Existing products"}],[{"text":"Selling and promoting"}],[{"text":"Profits through sales volume"}]],[[{"text":"Marketing concept"}],[{"text":"Market"}],[{"text":"Customer needs"}],[{"text":"Integrated marketing"}],[{"text":"Profits through customer satisfaction"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Levitt's contrast:","bold":true},{"text":" \"Selling focuses on the needs of the "},{"text":"seller","bold":true},{"text":"; marketing on the needs of the "},{"text":"buyer","bold":true},{"text":".\" Selling is preoccupied with converting the product into cash; marketing with satisfying the customer through the product and everything associated with creating, delivering and consuming it."}]},{"text":[{"text":"Bell and Emory's 3 elements of the marketing concept:","bold":true},{"text":" (1) "},{"text":"customer orientation","bold":true},{"text":", (2) "},{"text":"integrated effort","bold":true},{"text":", (3) "},{"text":"profit direction","bold":true},{"text":" (profit, not sales volume)."}]},{"text":[{"text":"Barksdale and Darden's 2 notions:","bold":true},{"text":" (1) the consumer is the focal point of all business activity; (2) "},{"text":"profit, rather than sales volume","bold":true},{"text":", is the criterion for evaluating marketing activities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selling example:","bold":true},{"text":" an Abuja insurer recruits a big team of agents to pitch people in markets and offices because few people seek out life insurance. Selling concept. As a long-term strategy it is weak: it may help meet short-term sales targets or survive hard times, but it fails against rivals who serve customers with products they really want."}]},{"text":[{"text":"Marketing example:","bold":true},{"text":" a restaurant near the University of Ibadan surveys students, learns they want affordable, healthy meals delivered fast, and designs its menu, prices and delivery around that, aiming to profit from repeat customers. Marketing concept."}]},{"text":[{"text":"Customer-driven vs customer-driving marketing:","bold":true},{"text":" customer-driven marketing finds out what customers want now and serves it. "},{"text":"Customer-driving marketing","bold":true},{"text":" studies customers so closely that it anticipates "},{"text":"latent needs","bold":true},{"text":" they have not yet expressed and creates products before they ask (think of how mobile money apps such as OPay and Moniepoint met needs many traders had never voiced)."}]},{"text":[{"text":"Customer orientation does not rule out stimulating needs or using aggressive selling for goods created for customers."}]},{"text":[{"text":"Criticisms of the marketing concept:","bold":true},{"text":" it shifted attention from long-term product development and quality to short-term advertising, selling and promotion; implementing it has caused organisational stress, excessive costs and high product-failure rates; and relations between business, the public and government deteriorated ("},{"text":"consumerism","bold":true},{"text":"). Most failures are blamed on "},{"text":"implementation","bold":true},{"text":", not on the concept itself. Today it is often called "},{"text":"customer-centricity","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the selling concept starts at the "},{"text":"factory","bold":true},{"text":", not the market; the marketing concept's means is "},{"text":"integrated marketing","bold":true},{"text":", not selling and promoting. \"Mass production\" is never one of the four pillars."}]}]}]},{"number":"3.4","title":"The societal and holistic marketing concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Societal marketing concept:","bold":true},{"text":" the organisation's task is to determine the needs, wants and interests of customers and to satisfy them "},{"text":"more effectively and efficiently than competitors","bold":true},{"text":", in a way that "},{"text":"preserves or enhances the welfare of the consumer and society","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Evolved from "},{"text":"criticisms of the marketing concept","bold":true},{"text":", chiefly that it ignores "},{"text":"long-run societal welfare","bold":true},{"text":" and overlooks conflicts between consumers' "},{"text":"short-run wants","bold":true},{"text":" and "},{"text":"long-run welfare","bold":true},{"text":"."}]},{"text":[{"text":"Gained prominence through growing concern over "},{"text":"sustainability and ethics","bold":true},{"text":"."}]},{"text":[{"text":"It "},{"text":"integrates ethical considerations and societal welfare","bold":true},{"text":" into the marketing concept."}]},{"text":[{"text":"3 considerations to balance:","bold":true},{"text":" (1) "},{"text":"company profit","bold":true},{"text":", (2) "},{"text":"consumer satisfaction (wants)","bold":true},{"text":", (3) "},{"text":"interests of society (the public)","bold":true},{"text":". In the four-way version: consumers' wants, the company's requirements, consumers' long-run interests, society's long-run interests."}]},{"text":[{"text":"It does "},{"text":"not","bold":true},{"text":" ask the firm to give up profit."}]}]}]},{"text":[{"text":"Holistic marketing concept:","bold":true},{"text":" \"everything matters\" in marketing, so a broad, integrated perspective is needed in developing, designing and carrying out marketing programmes. "},{"text":"4 components:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relationship marketing:","bold":true},{"text":" building mutually satisfying long-term relationships with customers, suppliers, distributors and other partners to earn and keep their business."}]},{"text":[{"text":"Integrated marketing:","bold":true},{"text":" all marketing activities and departments combined to create, communicate and deliver value."}]},{"text":[{"text":"Internal marketing:","bold":true},{"text":" hiring, training and motivating able employees who want to serve customers well."}]},{"text":[{"text":"Performance marketing","bold":true},{"text":" (earlier called "},{"text":"socially responsible marketing","bold":true},{"text":"): understanding the financial and non-financial returns to the business and society, including ethical, legal and environmental effects."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Societal example:","bold":true},{"text":" a Nigerian soft-drink maker cuts sugar, moves to recyclable bottles and funds clearing of drains blocked by plastic, while still aiming to satisfy customers and earn a profit. Societal marketing concept."}]},{"text":[{"text":"Short-run wants vs long-run welfare:","bold":true},{"text":" a Port Harcourt fast-food chain sells cheap, tasty fried meals customers love; a critic says it satisfies short-run wants but ignores long-run health (obesity). That critic reasons from the "},{"text":"societal","bold":true},{"text":" concept. The pure marketing concept would see no problem, because customers are satisfied."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"It requires the firm to give up profit for social welfare\" is "},{"text":"false","bold":true},{"text":"; societal marketing balances profit with welfare."}]},{"text":[{"text":"\"Production marketing\" and \"mass marketing\" are "},{"text":"not","bold":true},{"text":" components of holistic marketing."}]},{"text":[{"text":"Internal marketing: a GTBank or MTN service promise means nothing unless staff are trained and motivated to keep it."}]}]}]},{"number":"3.5","title":"Market orientation and its components","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market orientation:","bold":true},{"text":" the organisation-wide putting into practice of the marketing concept. The firm "},{"text":"continuously gathers information about customers and competitors","bold":true},{"text":" and "},{"text":"coordinates all departments","bold":true},{"text":" to create "},{"text":"superior customer value","bold":true},{"text":"."}]},{"text":[{"text":"Marketing concept vs market orientation:","bold":true},{"text":" the marketing concept is the "},{"text":"philosophy","bold":true},{"text":"; market orientation is the "},{"text":"set of behaviours that puts it into practice","bold":true},{"text":"."}]},{"text":[{"text":"3 behavioural components","bold":true},{"text":" (Narver and Slater):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customer orientation:","bold":true},{"text":" understanding target buyers well enough to create superior value for them continuously."}]},{"text":[{"text":"Competitor orientation:","bold":true},{"text":" understanding the short-term strengths and weaknesses and long-term capabilities and strategies of "},{"text":"current and potential","bold":true},{"text":" competitors."}]},{"text":[{"text":"Inter-functional coordination:","bold":true},{"text":" the coordinated use of the company's resources "},{"text":"across all departments","bold":true},{"text":" to create superior value for target customers."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"2 decision criteria:","bold":true},{"text":" (1) "},{"text":"long-term focus","bold":true},{"text":", (2) "},{"text":"profitability","bold":true},{"text":"."}]},{"text":[{"text":"Information-processing view","bold":true},{"text":" (Kohli and Jaworski): market orientation is the organisation-wide (1) "},{"text":"generation","bold":true},{"text":" of market intelligence, (2) "},{"text":"dissemination","bold":true},{"text":" of that intelligence across departments, and (3) organisation-wide "},{"text":"responsiveness","bold":true},{"text":" to it."}]},{"text":[{"text":"Market-oriented definition of the business:","bold":true},{"text":" define the business by the customer need it serves, not by the product it makes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer orientation:","bold":true},{"text":" a Lagos fintech holds monthly focus groups with Balogun Market traders, tracks every complaint and redesigns its app around what users need. Other signs: measuring satisfaction regularly, researching target customers' needs, following up after sales."}]},{"text":[{"text":"Competitor orientation:","bold":true},{"text":" a Nigerian paint firm's managers meet weekly to review rivals' price changes and launches, and to assess a foreign firm planning to enter. Studying a rival's "},{"text":"cost structure","bold":true},{"text":" is competitor orientation, so it is the activity "},{"text":"least","bold":true},{"text":" associated with customer orientation."}]},{"text":[{"text":"Inter-functional coordination:","bold":true},{"text":" at an Aba shoe company, production, finance, R&D and sales staff share customer feedback and jointly plan a new school-shoe range."}]},{"text":[{"text":"\"Production orientation\" and \"selling orientation\" are "},{"text":"not","bold":true},{"text":" components of market orientation."}]},{"text":[{"text":"Business definitions:","bold":true},{"text":" a bank that says it is in the business of \"helping Nigerians move and keep money safely and cheaply\" (not \"operating bank branches\") has a "},{"text":"market-oriented","bold":true},{"text":" definition. \"We run bank branches\" or \"we make trains\" is "},{"text":"product-oriented","bold":true},{"text":" and invites myopia."}]},{"text":[{"text":"Market orientation does "},{"text":"not","bold":true},{"text":" replace customers with competitors as the main focus; it watches both."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A marketing concept is the guiding philosophy that weighs the interests of the firm, customers and society."}]},{"text":[{"text":"Five concepts: production, product, selling, marketing, societal; order of evolution production → selling → marketing → societal."}]},{"text":[{"text":"Production = available and cheap; demand > supply; efficiency and distribution; danger is forgetting customers."}]},{"text":[{"text":"Product = highest quality and features; technology-push; leads to marketing myopia (product, not need)."}]},{"text":[{"text":"Selling = consumers must be persuaded; overproduction, unsought goods; factory, existing products, selling and promoting, profit through volume."}]},{"text":[{"text":"Marketing = market, customer needs, integrated marketing, profit through satisfaction; \"sense and respond\"; four pillars."}]},{"text":[{"text":"Societal = marketing concept plus consumer and society welfare; balance profit, wants and public interest; profit is not given up."}]},{"text":[{"text":"Holistic = relationship, integrated, internal and performance (socially responsible) marketing."}]},{"text":[{"text":"Market orientation puts the marketing concept into practice: customer orientation, competitor orientation, inter-functional coordination; long-term focus and profitability."}]}]}],"theory":{"itemId":"fb555ddc-45af-569f-a0c9-b63d7a28d44a","question":[{"type":"paragraph","text":[{"text":"Distinguish the selling concept from the marketing concept, and state the three behavioural components of market orientation."}]}]},"practice":[{"topic":"Marketing Concepts and Market Orientation","named":false}]}},{"itemId":"def16f0a-7f1d-5c21-8a02-43088dcc5f77","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Marketing Environment","body":"The meaning of the marketing environment and its five features; internal versus external, micro versus macro; every micro force (company, suppliers, intermediaries, customers, competitors, publics) with its sub-types; the six macro forces and their factors; PESTLE, SWOT and environmental scanning; why studying the environment matters; strategic windows and megamarketing.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The meaning of the marketing environment and its five features; internal versus external, micro versus macro; every micro force (company, suppliers, intermediaries, customers, competitors, publics) with its sub-types; the six macro forces and their factors; PESTLE, SWOT and environmental scanning; why studying the environment matters; strategic windows and megamarketing."}],"lessons":[{"number":"4.1","title":"Meaning, types and features of the marketing environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing environment:","bold":true},{"text":" all the internal and external factors that directly or indirectly influence an organisation's decisions on its marketing activities. Put more simply: the factors and forces that influence the marketing function of an organisation. It is the mix of forces that affect a firm's ability to build relationships with and serve its customers."}]},{"text":[{"text":"Internal environment:","bold":true},{"text":" the internal forces and factors that influence the marketing function. Internal factors are "},{"text":"within the organisation's control","bold":true},{"text":" (e.g. its own strengths, weaknesses and competencies)."}]},{"text":[{"text":"External environment:","bold":true},{"text":" the external forces and factors that influence the marketing function. External factors are "},{"text":"not within its control","bold":true},{"text":" (e.g. government, technology, economy, society, competitors)."}]},{"text":[{"text":"The environment is usually divided into "},{"text":"2 main types:","bold":true},{"text":" the "},{"text":"micro environment","bold":true},{"text":" and the "},{"text":"macro environment","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Micro environment"}],[{"text":"Macro environment"}]],"rows":[[[{"text":"Other names"}],[{"text":"Task environment; immediate environment"}],[{"text":"Broad environment"}]],[[{"text":"Meaning"}],[{"text":"Forces closely linked to the firm that "},{"text":"directly","bold":true},{"text":" affect its activities"}],[{"text":"Larger societal forces, "},{"text":"beyond the firm's control","bold":true},{"text":", that affect it (and all actors in its immediate environment) to a significant extent and are subject to constant change"}]],[[{"text":"Members"}],[{"text":"Company, suppliers, marketing intermediaries, customers, competitors, publics"}],[{"text":"Demographic, economic, natural, technological, political-legal, socio-cultural"}]]]},{"type":"paragraph","text":[{"text":"5 features of the marketing environment:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Specific and general forces:","bold":true},{"text":" specific forces "},{"text":"directly","bold":true},{"text":" affect the organisation (e.g. customers, investors); general forces affect it "},{"text":"indirectly","bold":true},{"text":" (e.g. social, political, legal, technological factors)."}]},{"text":[{"text":"Complexity:","bold":true},{"text":" the environment contains many factors, conditions and influences, and their "},{"text":"interaction","bold":true},{"text":" makes it complex."}]},{"text":[{"text":"Vibrancy:","bold":true},{"text":" the environment is "},{"text":"dynamic","bold":true},{"text":"; it does not stay stable but "},{"text":"changes over time","bold":true},{"text":". Marketers can control some forces but never all."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" market forces are "},{"text":"unpredictable","bold":true},{"text":"; some changes are hard to predict (e.g. tastes in clothes)."}]},{"text":[{"text":"Relativity:","bold":true},{"text":" explains why "},{"text":"demand differs","bold":true},{"text":" from country to country, region to region or culture to culture."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Stability\" is "},{"text":"not","bold":true},{"text":" a feature; the environment is the opposite of stable. That is exactly why it demands "},{"text":"constant monitoring","bold":true},{"text":": so the firm can adapt to unpredictable shifts in external and internal conditions, rather than keep static strategies."}]},{"text":[{"text":"Uncertainty","bold":true},{"text":" example: a Lagos fashion house sells out an ankara style one month and cannot move it the next. A fashion may last a few days or a few years."}]},{"text":[{"text":"Relativity","bold":true},{"text":" example: aso-oke caps are always in demand in south-west Nigeria because they are traditional dress, yet demand abroad may be almost zero."}]},{"text":[{"text":"Vibrancy","bold":true},{"text":" sounds like \"lively\"; in the exam it means "},{"text":"dynamic, always changing","bold":true},{"text":". Do not confuse it with complexity (many interacting factors)."}]},{"text":[{"text":"A complete environmental analysis must cover "},{"text":"both micro","bold":true},{"text":" (e.g. suppliers) "},{"text":"and macro","bold":true},{"text":" (e.g. economic trends) forces, not customers or competitors alone."}]},{"text":[{"text":"Marketers monitor the environment to predict changes, because changes create "},{"text":"threats and opportunities","bold":true},{"text":", and plans are modified to match."}]}]}]},{"number":"4.2","title":"The internal environment and the supply side of the micro environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal environment (the company):","bold":true},{"text":" the firm's own departments (top management, finance, research and development (R&D), purchasing, operations/production, personnel/HR, accounting) whose relationships affect marketing decisions. Marketing plans need "},{"text":"top management approval","bold":true},{"text":" before they are implemented."}]},{"text":[{"text":"4 organic business functions:","bold":true},{"text":" marketing, personnel, production, finance."}]},{"text":[{"text":"Five Ms","bold":true},{"text":" of the internal environment: "},{"text":"Men, Money, Machinery, Materials, Markets.","bold":true},{"text":" Internal forces are "},{"text":"controllable","bold":true},{"text":" and can be adjusted to external change."}]},{"text":[{"text":"The micro environment has a "},{"text":"supply side","bold":true},{"text":" (suppliers, marketing intermediaries, competitors) and a "},{"text":"demand side","bold":true},{"text":" (customers)."}]},{"text":[{"text":"Suppliers:","bold":true},{"text":" other firms and individuals that provide the resources (raw materials and other inputs) a company needs to produce its goods and services."}]},{"text":[{"text":"Make-or-buy decision:","bold":true},{"text":" the purchasing department's decision on which resources to make itself and which to buy from outside. "},{"text":"3 options:","bold":true},{"text":" (i) make everything and assemble or process it; (ii) buy everything and confine the firm to assembly; (iii) make the complicated parts and buy the less complicated ones."}]},{"text":[{"text":"Marketing intermediaries:","bold":true},{"text":" independent businesses that perform the activities needed to move products from manufacturers to ultimate consumers; they link the firm with customers by "},{"text":"promoting, selling and distributing","bold":true},{"text":" its products. They include wholesalers, retailers, agents and distributors."}]}]},{"type":"paragraph","text":[{"text":"4 types of marketing intermediaries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resellers:","bold":true},{"text":" buy from the firm and sell to customers (wholesalers, retailers)."}]},{"text":[{"text":"Distribution centres:","bold":true},{"text":" store goods (e.g. a warehouse)."}]},{"text":[{"text":"Marketing agencies:","bold":true},{"text":" promote the products by making customers aware of their benefits (e.g. an advertising agency)."}]},{"text":[{"text":"Financial intermediaries:","bold":true},{"text":" finance or insure business transactions (banks, credit organisations, insurance companies)."}]}]},{"type":"paragraph","text":[{"text":"5 utilities created by intermediaries (middlemen):","bold":true}]},{"type":"table","header":[[{"text":"Utility"}],[{"text":"How it is created"}]],"rows":[[[{"text":"Place"}],[{"text":"Stocking","bold":true},{"text":" products where customers are located"}]],[[{"text":"Time"}],[{"text":"Opening "},{"text":"long hours","bold":true},{"text":" so customers buy at their convenience"}]],[[{"text":"Quantity"}],[{"text":"Making products available in "},{"text":"quantities customers can afford","bold":true}]],[[{"text":"Assortment"}],[{"text":"Gathering different products at one point","bold":true},{"text":" so customers buy them on one shopping trip"}]],[[{"text":"Possession"}],[{"text":"Transferring","bold":true},{"text":" products to customers through successful transactions"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suppliers affect "},{"text":"profit","bold":true},{"text":", because the price of raw materials determines the final price. Firms monitor suppliers regularly for "},{"text":"supply shortages","bold":true},{"text":" and "},{"text":"input price changes","bold":true},{"text":", and check reliability, delivery, stock availability, credit facilities and servicing."}]},{"text":[{"text":"Worked example (supplier force):","bold":true},{"text":" a Lagos bakery pays ₦60,000 for a bag of flour. Its miller raises the price by 30%. Increase = 30% × ₦60,000 = ₦18,000. New price = ₦60,000 + ₦18,000 = ₦78,000 a bag. The bakery raises the price of its bread. The force at work is the "},{"text":"supplier","bold":true},{"text":"."}]},{"text":[{"text":"Car assemblers buy windscreens, tyres, headlamps and steel sheet from many suppliers; those suppliers in turn have their own suppliers. Firms also buy specialist marketing services (advertising, consulting, market research) from outside."}]},{"text":[{"text":"Intermediary examples: a Kano warehouse company storing a beverage maker's cartons = "},{"text":"distribution centre","bold":true},{"text":"; an Ikeja agency making radio jingles and billboards = "},{"text":"marketing agency","bold":true},{"text":"; a bank financing a distributor's stock = "},{"text":"financial intermediary","bold":true},{"text":". A raw-material supplier is "},{"text":"not","bold":true},{"text":" an intermediary."}]},{"text":[{"text":"Trap: in the supply chain the firm collaborates most closely with "},{"text":"suppliers and intermediaries","bold":true},{"text":"."}]},{"text":[{"text":"Some lists call agencies, research firms, banks, insurers, transport companies and brokers the firm's "},{"text":"partners","bold":true},{"text":": separate entities doing business with it."}]},{"text":[{"text":"Channels change slowly but constantly, like the hour hand of a watch; the firm must manage and satisfy its intermediaries."}]}]}]},{"number":"4.3","title":"Customers, competitors and publics (the rest of the micro environment)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customers:","bold":true},{"text":" those who buy the organisation's products for final consumption; their "},{"text":"satisfaction is the organisation's main goal","bold":true},{"text":". They form the "},{"text":"demand side","bold":true},{"text":" of the micro environment. Firms do R&D to analyse customer needs and make products to match."}]}]},{"type":"paragraph","text":[{"text":"5 types of customer markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Consumer markets:","bold":true},{"text":" individuals and households buying for personal consumption."}]},{"text":[{"text":"Industrial (business) markets:","bold":true},{"text":" organisations buying goods and services to produce other products and services, for profit or other objectives."}]},{"text":[{"text":"Reseller markets:","bold":true},{"text":" organisations buying goods and services to resell at a profit."}]},{"text":[{"text":"Government and nonprofit markets:","bold":true},{"text":" agencies buying to produce public services or to transfer goods to those who need them."}]},{"text":[{"text":"International markets:","bold":true},{"text":" buyers abroad (foreign consumers, producers, resellers, governments)."}]}]},{"type":"paragraph","text":[{"text":"4 types of organisational buyers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Industrial buyers:","bold":true},{"text":" procure products or services for use in manufacturing other products or for operating their own businesses."}]},{"text":[{"text":"Resellers:","bold":true},{"text":" intermediaries that buy products in order to resell them."}]},{"text":[{"text":"Government agencies:","bold":true},{"text":" Federal, State and local government units that procure products and services to perform their social functions."}]},{"text":[{"text":"Institutional buyers:","bold":true},{"text":" buy for organisations that render services, such as museums, hospitals, schools and churches."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business-to-business (B2B) marketers:","bold":true},{"text":" marketers who sell to business organisations rather than to individual consumers (B2C)."}]},{"text":[{"text":"Competition:","bold":true},{"text":" a situation in which various organisations offer similar products and try to gain market share by adopting different marketing strategies. Competitors push a firm to "},{"text":"differentiate","bold":true},{"text":" its product to maintain its position in the market."}]},{"text":[{"text":"Intratype competition:","bold":true},{"text":" between organisations that engage in the "},{"text":"same basic activity","bold":true},{"text":"."}]},{"text":[{"text":"Intertype competition:","bold":true},{"text":" between "},{"text":"different types","bold":true},{"text":" of organisations."}]},{"text":[{"text":"Public:","bold":true},{"text":" any group that has an actual or potential interest in, or impact on, an organisation's ability to achieve its objectives (serve its customers)."}]}]},{"type":"paragraph","text":[{"text":"7 publics:","bold":true},{"text":" financial (banks, investors), media (newspapers, radio, TV, blogs), government, citizen-action (consumer and environmental groups), local (community), general public, internal (employees, managers, board)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"market segments\" is "},{"text":"not","bold":true},{"text":" a type of customer market; \"individual buyers\" are "},{"text":"not","bold":true},{"text":" organisational buyers (they are consumers)."}]},{"text":[{"text":"Intratype examples: Coca-Cola's bottler against Seven-Up Bottling Company for soft-drink buyers; First Bank, UBA, Zenith and GTBank against each other for savings and loans. Intertype examples: finance houses or fintech apps against banks for savings customers."}]},{"text":[{"text":"Competitors","bold":true},{"text":" are the micro force that most directly challenges a firm's strategy (rivals' pricing and innovation tactics), and "},{"text":"competitor pricing and positioning","bold":true},{"text":" is the external factor that most directly affects a firm's own pricing."}]},{"text":[{"text":"Media public example: newspapers, radio stations and online blogs writing about a Lagos bank. Financial public: the bank's shareholders and lenders."}]}]}]},{"number":"4.4","title":"The macro environment","mustKnow":[{"type":"paragraph","text":[{"text":"6 macro forces:","bold":true},{"text":" demographic, economic, natural (physical), technological, political-legal, socio-cultural. Suppliers, intermediaries, customers, competitors and the company are "},{"text":"micro","bold":true},{"text":", never macro. Some lists add the "},{"text":"international situation","bold":true},{"text":"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Demographic:","bold":true},{"text":" the scientific study of human population by age, gender, education, occupation, income, location, size, density, race, marriage and death rates (the "},{"text":"demographic variables","bold":true},{"text":"). Also covers the rising role of women. It explains variation in tastes and buying patterns. Prices are "},{"text":"not","bold":true},{"text":" demographic."}]},{"text":[{"text":"Economic:","bold":true},{"text":" affects the firm's "},{"text":"cost structure","bold":true},{"text":" and customers' "},{"text":"purchasing power","bold":true},{"text":". Purchasing power depends on "},{"text":"current income, prices of products, savings and availability of credit","bold":true},{"text":". Factors:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" affects demand (higher petrol prices lead to a fall in demand for cars)."}]},{"text":[{"text":"Interest rates:","bold":true},{"text":" determine borrowing; higher rates may make firms cut important activities."}]},{"text":[{"text":"Unemployment:","bold":true},{"text":" a no-income state that reduces purchasing power."}]},{"text":[{"text":"Customer income:","bold":true},{"text":" changes spending patterns (e.g. on food and clothing)."}]},{"text":[{"text":"Monetary policy:","bold":true},{"text":" stabilises the economy by controlling "},{"text":"interest rates and money supply","bold":true},{"text":". "},{"text":"Fiscal policy:","bold":true},{"text":" government "},{"text":"spending","bold":true},{"text":", financed by revenue from "},{"text":"taxes","bold":true},{"text":"."}]},{"text":[{"text":"Others: economic growth (GDP, GNP), exchange rates, employment level, raw-material scarcity, energy costs, import duties, balance of trade, income distribution, savings, subsidies. Ethnic structure is "},{"text":"not","bold":true},{"text":" economic."}]}]}]},{"text":[{"text":"Natural (physical):","bold":true},{"text":" natural resources used as raw materials, plus natural conditions. Factors: "},{"text":"natural resources","bold":true},{"text":" (depletion leads some firms to "},{"text":"de-marketing","bold":true},{"text":"), "},{"text":"weather","bold":true},{"text":", "},{"text":"pollution","bold":true},{"text":" (air, water, noise). Also climate, floods, extreme heat, natural disasters, access to water."}]},{"text":[{"text":"Technological:","bold":true},{"text":" a rapidly changing force creating new opportunities and threats. "},{"text":"3 trends:","bold":true},{"text":" "},{"text":"pace of technological change","bold":true},{"text":" (fast change makes products obsolete quickly, so firms modify products often); "},{"text":"research and development","bold":true},{"text":" (raises growth opportunities); "},{"text":"increased regulation","bold":true},{"text":" (government guidelines that ban unsafe products, which marketers must know and obey)."}]},{"text":[{"text":"Political and legal:","bold":true},{"text":" legal bodies and government agencies that influence and limit organisations and individuals, plus laws, policies and pressure groups. "},{"text":"2 kinds of law:","bold":true},{"text":" "},{"text":"anti-pollution laws","bold":true},{"text":" (affect production) and "},{"text":"customer (consumer) legislation","bold":true},{"text":" (protects customers' interests)."}]},{"text":[{"text":"Socio-cultural:","bold":true},{"text":" society's basic "},{"text":"values, attitudes, perceptions and behaviour","bold":true},{"text":", lifestyles, beliefs and culture. It shapes what people buy, which brand, and when."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demographic:","bold":true},{"text":" a telecoms firm sees that a very large share of Nigerians are under 30 and launches cheap student data bundles. Nigeria's large population makes it one of the biggest single markets in Africa."}]},{"text":[{"text":"Economic:","bold":true},{"text":" during a recession, watch economic conditions affecting purchasing power. Nigeria shows developing-economy traits: low incomes, low literacy and technology know-how, high unemployment, inadequate roads, power and telecoms. A weak naira raises the cost of imported raw materials, causing "},{"text":"low capacity utilisation","bold":true},{"text":". Poor infrastructure is a threat (traffic, higher costs) but also an opportunity for firms supplying it."}]},{"text":[{"text":"Worked example (interest rates):","bold":true},{"text":" a Nnewi auto-parts maker owes ₦50,000,000. At 20% a year, interest = 0.20 × ₦50,000,000 = ₦10,000,000. At 28%, interest = 0.28 × ₦50,000,000 = ₦14,000,000. Extra yearly cost = ₦4,000,000, so it postpones expansion. In Nigeria, monetary policy is set by the "},{"text":"Central Bank of Nigeria","bold":true},{"text":" (e.g. its policy rate); raising VAT to spend more on roads is "},{"text":"fiscal","bold":true},{"text":" policy."}]},{"text":[{"text":"Natural:","bold":true},{"text":" harmattan raises sales of body lotion, lip balm and petroleum jelly; the rainy season raises umbrella sales; hot months raise fans and cold drinks. Plastic waste blocking Lagos drains pushes supermarkets towards paper bags. "},{"text":"De-marketing:","bold":true},{"text":" a petroleum marketer urging the public to use less of its own fuel."}]},{"text":[{"text":"Technology:","bold":true},{"text":" smartphones and instant transfers let a Yaba vendor sell on Instagram and take transfers instead of cash. Technology can be a constraint when equipment is lacking; firms that ignore it struggle to survive. In Nigeria, drugs and foods must be registered with "},{"text":"NAFDAC","bold":true},{"text":", and product standards are set by the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":"."}]},{"text":[{"text":"Political-legal (Nigeria):","bold":true},{"text":" the "},{"text":"Federal Competition and Consumer Protection Act 2018","bold":true},{"text":" (enforced by the "},{"text":"FCCPC","bold":true},{"text":") protects consumers; "},{"text":"ARCON","bold":true},{"text":" (formerly APCON) regulates advertising; "},{"text":"NESREA","bold":true},{"text":" enforces environmental standards; tobacco packs must carry a health warning. Lagos State banned styrofoam food packs, forcing eateries to switch packaging. Government also "},{"text":"facilitates","bold":true},{"text":": tax incentives for growth industries, development-bank loans, research institutes such as FIIRO. Political stability attracts business; instability hurts the economy."}]},{"text":[{"text":"Socio-cultural:","bold":true},{"text":" with husbands and wives both working full-time, families have less time to shop, so supermarkets and malls with everything under one roof grow. Nigerian values include respect for age and extended-family responsibility; Yoruba, Hausa and Igbo "},{"text":"sub-cultures","bold":true},{"text":" can be treated as segments. Values also cover attitudes to health and nutrition, materialism, self-expression, product safety and ecology."}]},{"text":[{"text":"International situation:","bold":true},{"text":" easier shipping and communication widen markets, but trade barriers (quotas, duties) and different economies, cultures and politics add risk."}]}]}]},{"number":"4.5","title":"PESTLE, SWOT, environmental scanning and why the environment matters","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PESTLE:","bold":true},{"text":" a checklist for the macro environment: "},{"text":"P","bold":true},{"text":"olitical, "},{"text":"E","bold":true},{"text":"conomic, "},{"text":"S","bold":true},{"text":"ocial, "},{"text":"T","bold":true},{"text":"echnological, "},{"text":"L","bold":true},{"text":"egal, "},{"text":"E","bold":true},{"text":"nvironmental (natural). PEST is the shorter version."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"trengths and "},{"text":"W","bold":true},{"text":"eaknesses (internal, controllable); "},{"text":"O","bold":true},{"text":"pportunities and "},{"text":"T","bold":true},{"text":"hreats (external)."}]},{"text":[{"text":"Environmental scanning:","bold":true},{"text":" the systematic process of gathering and monitoring information about a company's external events and relationships, to detect trends, opportunities and threats early enough to respond and to help top management decide its future course."}]},{"text":[{"text":"3 phases of scanning:","bold":true},{"text":" data gathering; environmental interpretation (analysis); strategy formulation."}]},{"text":[{"text":"Sources:","bold":true},{"text":" company reports, industry reports, magazines, newspapers, government reports, marketing-intelligence reports, personal networking (e.g. trade fairs)."}]},{"text":[{"text":"Controllable variables:","bold":true},{"text":" the internal factors and the marketing mix (the firm's own "},{"text":"product, price, place, promotion","bold":true},{"text":"). "},{"text":"Uncontrollable:","bold":true},{"text":" macro forces such as inflation, population growth and competitors' decisions."}]},{"text":[{"text":"Strategic window:","bold":true},{"text":" a short period in which a company must adjust its strategic marketing approach to new market realities, or quit the market if it fails to adjust. "},{"text":"4 changes create it:","bold":true},{"text":" new primary demand (growth in the overall market); new technology; market redefinition through competitive activity; changes in distribution channels."}]},{"text":[{"text":"Megamarketing:","bold":true},{"text":" the use of "},{"text":"power and public relations","bold":true},{"text":" (also lobbying and lawsuits) to penetrate "},{"text":"blocked or protected markets","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"3 importances of studying the marketing environment:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identification of opportunities","bold":true},{"text":" (e.g. exploiting customer preference with discounts)."}]},{"text":[{"text":"Identification of threats","bold":true},{"text":" (warning signals before it is too late)."}]},{"text":[{"text":"Managing changes","bold":true},{"text":" (adapting to survive in the long run)."}]}]},{"type":"paragraph","text":[{"text":"Environmental analysis also helps the marketer to:","bold":true},{"text":" know the changes; gain quality information for strategy; understand market needs and modify products; handle government-legal-regulatory policies; allocate resources and diversify; identify threats (new competitors, price wars, rival products); identify opportunities (new markets, mergers, joint ventures, alliances, a vacuum left by an exiting competitor); identify weaknesses (low-quality goods, lack of marketing expertise, no unique products) and turn them into strengths; identify and exploit strengths. It also aids planning, understanding customers and competitors, and "},{"text":"first-mover advantage","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Threat: a juice maker hears a foreign multinational is entering and prepares price cuts and heavy promotion. Opportunity: a rival paint brand exits and a local maker wins its retailers. Weakness: an Ibadan cosmetics firm finds poor packaging and no marketing expertise."}]},{"text":[{"text":"\"Eliminating all competition\" is "},{"text":"never","bold":true},{"text":" a benefit of environmental study."}]},{"text":[{"text":"Environmental analysis comes first in the situation analysis, so that "},{"text":"positioning","bold":true},{"text":" (target-market choice) and the "},{"text":"marketing mix","bold":true},{"text":" can be adjusted. Example: more working mothers make day-care a more attractive segment."}]},{"text":[{"text":"Megamarketing is not guaranteed: it is costly, decided by top management and uncertain. Do not confuse it with "},{"text":"demarketing","bold":true},{"text":" (reducing demand) or "},{"text":"synchromarketing","bold":true},{"text":" (smoothing irregular demand)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing environment = all internal and external factors that directly or indirectly influence marketing decisions; internal is controllable, external is not."}]},{"text":[{"text":"5 features: specific and general forces, complexity, vibrancy (dynamic), uncertainty (unpredictable), relativity (demand differs by place)."}]},{"text":[{"text":"Micro (immediate, direct): company, suppliers, intermediaries, customers, competitors, publics; supply side vs demand side (customers)."}]},{"text":[{"text":"4 intermediaries: resellers, distribution centres, marketing agencies, financial intermediaries; 5 utilities: place, time, quantity, assortment, possession."}]},{"text":[{"text":"5 customer markets; 4 organisational buyers (industrial, resellers, government, institutional); intratype vs intertype competition; make-or-buy."}]},{"text":[{"text":"Macro (broad, uncontrollable): demographic, economic, natural, technological, political-legal, socio-cultural."}]},{"text":[{"text":"Purchasing power = income, prices, savings, credit; monetary = interest rates and money supply; fiscal = spending and taxes."}]},{"text":[{"text":"PESTLE, SWOT, scanning (3 phases); importance: opportunities, threats, managing change."}]},{"text":[{"text":"Strategic window = short time to adjust or quit; megamarketing = power and PR to enter blocked markets."}]}]}],"theory":{"itemId":"5b9e7ccf-c51f-5566-a2aa-618ec4cf7099","question":[{"type":"paragraph","text":[{"text":"Distinguish the micro environment from the macro environment and give three forces in each."}]}]},"practice":[{"topic":"Marketing Environment","named":false}]}},{"itemId":"409cb076-fc9e-55ab-a382-4058d9adb132","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Consumer and Organisational Buying Behaviour","body":"The meaning of buying behaviour; the six stages of the consumer buying decision process and cognitive dissonance; involvement, perceived risk and the types of buying behaviour; the three categories of factors (personal, psychological, social) and everything inside each; family buying roles and reference groups; organisational markets, the buying centre, the three buy classes and the buy phases.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The meaning of buying behaviour; the six stages of the consumer buying decision process and cognitive dissonance; involvement, perceived risk and the types of buying behaviour; the three categories of factors (personal, psychological, social) and everything inside each; family buying roles and reference groups; organisational markets, the buying centre, the three buy classes and the buy phases."}],"lessons":[{"number":"5.1","title":"Meaning of buying behaviour and the buying decision process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Buying behaviour:","bold":true},{"text":" the decisions and actions of people involved in buying and using products."}]},{"text":[{"text":"Consumer buying behaviour:","bold":true},{"text":" the buying behaviour of the "},{"text":"ultimate (final) consumer","bold":true},{"text":", who buys for personal or household use."}]},{"text":[{"text":"Consumer behaviour as a field","bold":true},{"text":" is multidisciplinary: it covers the "},{"text":"psychological, social and cultural influences","bold":true},{"text":" on purchase decisions."}]},{"text":[{"text":"Why study it:","bold":true},{"text":" studying what, where, when and how people buy lets marketers "},{"text":"predict how buyers are likely to respond to marketing stimuli","bold":true},{"text":" and build a marketing mix that gives customers satisfaction (utility)."}]}]},{"type":"paragraph","text":[{"text":"The 6 stages of the consumer buying decision process (complex decision):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Problem recognition","bold":true},{"text":" (need awareness): the buyer becomes aware of a "},{"text":"gap between a desired state and an actual state","bold":true},{"text":". Always the "},{"text":"first","bold":true},{"text":" step."}]},{"text":[{"text":"Information search:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" (the buyer's own memory of past purchases) and "},{"text":"external","bold":true},{"text":" (word of mouth from friends and relatives, marketer-controlled sources such as adverts and salespeople, comparison shopping, public sources such as consumer reports). The result is a short list of alternatives called the "},{"text":"evoked set","bold":true},{"text":" (consideration set)."}]},{"text":[{"text":"Evaluation of alternatives:","bold":true},{"text":" the buyer sets "},{"text":"criteria","bold":true},{"text":" (wanted and unwanted features), then "},{"text":"ranks or weights","bold":true},{"text":" the options, or goes back to search."}]},{"text":[{"text":"Purchase decision:","bold":true},{"text":" choosing the alternative: product, package, store, method of payment."}]},{"text":[{"text":"Purchase:","bold":true},{"text":" the actual buying. It "},{"text":"can differ","bold":true},{"text":" from the decision (time gap, out of stock)."}]},{"text":[{"text":"Post-purchase evaluation:","bold":true},{"text":" outcome is "},{"text":"satisfaction or dissatisfaction","bold":true},{"text":". Always the "},{"text":"last","bold":true},{"text":" step."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cognitive dissonance:","bold":true},{"text":" doubt felt by a buyer, "},{"text":"after","bold":true},{"text":" a purchase, about whether the right choice was made. Reduced by "},{"text":"warranties, after-sales communication","bold":true},{"text":", and channels for customers to contact the firm."}]},{"text":[{"text":"A shorter "},{"text":"four-step","bold":true},{"text":" version of the complex process: (1) problem recognition, (2) information search and brand evaluation, (3) product choice and purchase, (4) post-purchase evaluation (satisfaction or dissatisfaction). First and last steps are the same in both versions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"Problem, Search, Evaluate, Decide, Buy, Review","bold":true},{"text":". Traps swap \"purchase decision\" and \"purchase\", or put evaluation before search."}]},{"text":[{"text":"Marketers can trigger problem recognition.","bold":true},{"text":" Tunde had not thought about sneakers until a billboard for a new design made him notice his old pair was worn out."}]},{"text":[{"text":"Internal versus external search:","bold":true},{"text":" Amaka recalling how last year's hair dryer performed is "},{"text":"internal","bold":true},{"text":" search. Asking friends, reading Jumia reviews or touring Computer Village is "},{"text":"external","bold":true},{"text":"; memory is "},{"text":"never","bold":true},{"text":" external."}]},{"text":[{"text":"Evoked set:","bold":true},{"text":" a student who ends up seriously considering only Tecno, Infinix and Samsung has those three as the evoked set. Marketers influence evaluation by \"framing\" alternatives (stressing the criteria their brand wins on)."}]},{"text":[{"text":"Decision versus purchase:","bold":true},{"text":" Funmi chose one phone brand, found it out of stock, and bought another."}]},{"text":[{"text":"Not every process ends in a purchase","bold":true},{"text":", and only complex (extensive) decisions pass through all six stages."}]},{"text":[{"text":"Dissonance:","bold":true},{"text":" a new-car buyer who fears the rival model was better is reassured by the dealer's warranty, thank-you call and helpline. Removing contact channels makes dissonance "},{"text":"worse","bold":true},{"text":"."}]}]}]},{"number":"5.2","title":"Involvement, perceived risk and types of buying behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Level of involvement:","bold":true},{"text":" the "},{"text":"importance and intensity of interest","bold":true},{"text":" in a product in a particular situation. It "},{"text":"determines the type of buying behaviour","bold":true},{"text":"."}]},{"text":[{"text":"High-involvement purchases:","bold":true},{"text":" purchases that are "},{"text":"important","bold":true},{"text":" to the consumer: high-priced, risky or publicly visible goods (a Honda motorbike, a car, a house)."}]},{"text":[{"text":"Low-involvement purchases:","bold":true},{"text":" made when consumers do "},{"text":"not","bold":true},{"text":" consider the product important or risky enough to give it much thought and deliberation."}]},{"text":[{"text":"As perceived risk rises, involvement "},{"text":"increases","bold":true},{"text":"."}]},{"text":[{"text":"Types of perceived risk:","bold":true},{"text":" "},{"text":"personal","bold":true},{"text":", "},{"text":"social","bold":true},{"text":" (fear of what others will think), "},{"text":"economic","bold":true},{"text":" (losing money). Extensive (expensive, unfamiliar) purchases also carry high "},{"text":"performance","bold":true},{"text":" and "},{"text":"psychological","bold":true},{"text":" risk."}]}]},{"type":"paragraph","text":[{"text":"4 types of consumer buying behaviour:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Involvement"}],[{"text":"Features"}],[{"text":"Examples"}]],"rows":[[[{"text":"1. "},{"text":"Routine response","bold":true},{"text":" (programmed) behaviour"}],[{"text":"Low"}],[{"text":"Frequent, low-cost, little search or effort, almost automatic"}],[{"text":"Soft drinks, snacks, milk, Indomie"}]],[[{"text":"2. "},{"text":"Limited decision making","bold":true}],[{"text":"Moderate"}],[{"text":"Occasional purchase; familiar product category but "},{"text":"unfamiliar brand","bold":true},{"text":"; moderate search time"}],[{"text":"A new brand of jeans"}]],[[{"text":"3. "},{"text":"Extensive decision making","bold":true},{"text":" (complex, high involvement)"}],[{"text":"High"}],[{"text":"Unfamiliar, expensive, bought rarely, high perceived risk, a lot of search; passes through all 6 stages"}],[{"text":"Cars, homes, computers, education"}]],[[{"text":"4. "},{"text":"Impulse buying","bold":true}],[{"text":"Low"}],[{"text":"No conscious planning","bold":true},{"text":"; a sudden urge to buy"}],[{"text":"Chocolate at the fuel-station counter"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Complex decision making","bold":true},{"text":" (= extensive) is a high-involvement purchase that requires a great deal of thought."}]},{"text":[{"text":"Inertia:","bold":true},{"text":" repeatedly buying the same brand mainly because it "},{"text":"saves effort","bold":true},{"text":", not because of strong commitment. "},{"text":"Brand loyalty","bold":true},{"text":" is repeat buying "},{"text":"with","bold":true},{"text":" strong commitment."}]}]},{"type":"paragraph","text":[{"text":"Kotler's 4 types (involvement plus differences between brands):","bold":true}]},{"type":"table","header":[[],[{"text":"High involvement"}],[{"text":"Low involvement"}]],"rows":[[[{"text":"Significant differences between brands","bold":true}],[{"text":"Complex buying behaviour"}],[{"text":"Variety-seeking buying behaviour"}]],[[{"text":"Few differences between brands","bold":true}],[{"text":"Dissonance-reducing buying behaviour"}],[{"text":"Habitual buying behaviour"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited:","bold":true},{"text":" Bola buys clothes often but asks friends before trying a jeans brand she has never used. "},{"text":"Extensive:","bold":true},{"text":" a couple buying their first house consult friends, relatives and estate agents for weeks. "},{"text":"Impulse:","bold":true},{"text":" Ngozi stops for fuel and buys an unplanned chocolate bar. \"Frequent purchase of low-cost items\" is "},{"text":"routine response","bold":true},{"text":", never extensive."}]},{"text":[{"text":"Risk examples:","bold":true},{"text":" Chioma avoids a cheap-looking dress because classmates may laugh at her: "},{"text":"social risk","bold":true},{"text":". Emeka hesitates over a ₦2,500,000 used car because he could lose a lot of money if it is faulty: "},{"text":"economic risk","bold":true},{"text":"."}]},{"text":[{"text":"The same product can trigger different behaviour.","bold":true},{"text":" Dinner out is extensive for someone who rarely eats out and limited for a regular; an anniversary dinner gets more thought than a casual one."}]},{"text":[{"text":"Kotler's grid:","bold":true},{"text":" complex = a laptop; dissonance-reducing = floor tiles (costly, brands look alike, so the buyer later seeks reassurance); habitual = salt (often inertia); variety-seeking = biscuits (switching for change, not dissatisfaction)."}]},{"text":[{"text":"Impulse buying","bold":true},{"text":" is driven mainly by "},{"text":"motivation tied to immediate gratification","bold":true},{"text":", a psychological factor. About 60% of purchases are unplanned, so sweets sit at the checkout."}]}]}]},{"number":"5.3","title":"Factors influencing consumer behaviour and psychological factors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 categories of factors","bold":true},{"text":" affecting the consumer buying decision process: "},{"text":"personal, psychological and social","bold":true},{"text":". Kotler splits "},{"text":"cultural","bold":true},{"text":" out of social, giving "},{"text":"4","bold":true},{"text":": cultural, social, personal, psychological."}]}]},{"type":"table","header":[[{"text":"Category"}],[{"text":"What it covers"}]],"rows":[[[{"text":"Personal","bold":true},{"text":" influences"}],[{"text":"The "},{"text":"personal characteristics","bold":true},{"text":" of the consumer: age and life-cycle stage, occupation, economic situation, demographics (sex, race), lifestyle, who in the family decides"}]],[[{"text":"Psychological","bold":true},{"text":" influences"}],[{"text":"Motives (motivation), "},{"text":"perception, learning (ability and knowledge), attitudes","bold":true},{"text":", personality and self-concept"}]],[[{"text":"Social","bold":true},{"text":" influences"}],[{"text":"Roles and family, "},{"text":"reference groups","bold":true},{"text":", social class, "},{"text":"culture and subculture","bold":true}]]]},{"type":"paragraph","text":[{"text":"Psychological factors:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Motive:","bold":true},{"text":" an "},{"text":"internal energising force","bold":true},{"text":" that directs a person's activities towards satisfying a need or achieving a goal. Behaviour is usually driven by several motives at once."}]},{"text":[{"text":"Maslow's hierarchy of needs (5 levels, lowest to highest):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological","bold":true},{"text":" (food, water, shelter)"}]},{"text":[{"text":"Safety","bold":true},{"text":" (security, protection)"}]},{"text":[{"text":"Love and belonging","bold":true},{"text":" (social acceptance, affection)"}]},{"text":[{"text":"Esteem","bold":true},{"text":" (status, recognition, respect)"}]},{"text":[{"text":"Self-actualisation","bold":true},{"text":" (reaching one's full potential)"}]}]}]},{"text":[{"text":"Perception:","bold":true},{"text":" the process of "},{"text":"selecting, organising and interpreting","bold":true},{"text":" information inputs received through the senses (sight, taste, hearing, smell, touch) to produce meaning."}]},{"text":[{"text":"3 selective processes","bold":true},{"text":" of perception:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selective exposure:","bold":true},{"text":" choosing which inputs reach awareness (we notice what meets current needs, or a sharp change such as a big price cut)."}]},{"text":[{"text":"Selective distortion:","bold":true},{"text":" changing or twisting information that conflicts with what we already believe."}]},{"text":[{"text":"Selective retention:","bold":true},{"text":" remembering information that supports our beliefs and forgetting what does not."}]}]}]},{"text":[{"text":"Learning:","bold":true},{"text":" a "},{"text":"relatively permanent change in behaviour","bold":true},{"text":" that results from the consequences of past behaviour and experience."}]},{"text":[{"text":"Knowledge:","bold":true},{"text":" familiarity with or expertise in a product. Buyers with little knowledge or experience tend to "},{"text":"use price as an indicator of quality","bold":true},{"text":"."}]},{"text":[{"text":"Attitude:","bold":true},{"text":" a person's "},{"text":"knowledge and positive or negative feelings","bold":true},{"text":" about an object or activity (tangible or intangible, living or not). Attitudes are "},{"text":"learned","bold":true},{"text":" through experience and interaction, and they shape perception."}]},{"text":[{"text":"Personality:","bold":true},{"text":" all the "},{"text":"internal traits and behaviours","bold":true},{"text":" that make a person unique, arising from "},{"text":"heredity and experience","bold":true},{"text":". Traits: workaholism, compulsiveness, self-confidence, friendliness, adaptability, ambitiousness, dogmatism, authoritarianism, introversion, extroversion, aggressiveness."}]},{"text":[{"text":"Self-concept","bold":true},{"text":" is also known as "},{"text":"self-image","bold":true},{"text":": the way a person sees himself or herself. People buy brands that match that image."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maslow in action:","bold":true},{"text":" a newly promoted bank manager buys a designer watch so colleagues admire his status: "},{"text":"esteem","bold":true},{"text":". A nutritional drink was marketed to fitness and energy-conscious buyers (belonging or esteem level), but research showed low-income inner-city buyers used it as a "},{"text":"meal substitute","bold":true},{"text":": "},{"text":"physiological","bold":true},{"text":". Motives are often subconscious and hard to measure. Order trap: safety comes "},{"text":"before","bold":true},{"text":" love and belonging; esteem comes "},{"text":"after","bold":true},{"text":" it."}]},{"text":[{"text":"Selective exposure:","bold":true},{"text":" of about 1,500 adverts Kemi sees daily, she notices the one announcing a big price cut on the laptop she needs. "},{"text":"Selective distortion:","bold":true},{"text":" an MTN advert compares its data plans with a rival's, and viewers who favour the rival remember it as the rival's advert. This is the danger of comparative adverts. "},{"text":"Selective retention:","bold":true},{"text":" Seyi remembers praise for his favourite boot brand and forgets last week's bad review."}]},{"text":[{"text":"\"Selective motivation\" is "},{"text":"not","bold":true},{"text":" a selective process; there are only three (exposure, distortion, retention)."}]},{"text":[{"text":"Learning:","bold":true},{"text":" to change behaviour, give new product information and experience, e.g. "},{"text":"free samples","bold":true},{"text":". "},{"text":"Price as quality cue:","bold":true},{"text":" buyers new to non-alcoholic beer picked the dearest six-pack."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" a favourable attitude does "},{"text":"not","bold":true},{"text":" always mean the person intends to buy or is able to buy. A student may love the newest iPhone yet be unable to afford it. "},{"text":"Social class is not a personality trait","bold":true},{"text":"; it is a social factor."}]}]}]},{"number":"5.4","title":"Personal and social factors","mustKnow":[{"type":"paragraph","text":[{"text":"Family life cycle stages","bold":true},{"text":" (part of the personal factor \"life-cycle stage\"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bachelor stage (young, single)"}]},{"text":[{"text":"Newly married, no children"}]},{"text":[{"text":"Full nest I (youngest child under 6)"}]},{"text":[{"text":"Full nest II (youngest child 6 or over)"}]},{"text":[{"text":"Full nest III (older couple, dependent children)"}]},{"text":[{"text":"Empty nest I:","bold":true},{"text":" older married, no children at home, head "},{"text":"still working","bold":true}]},{"text":[{"text":"Empty nest II:","bold":true},{"text":" older married, no children at home, head "},{"text":"retired","bold":true}]},{"text":[{"text":"Solitary survivor, in the labour force"}]},{"text":[{"text":"Solitary survivor, retired"}]}]},{"type":"paragraph","text":[{"text":"The "},{"text":"modernised","bold":true},{"text":" family life cycle adds divorced and childless households."}]},{"type":"paragraph","text":[{"text":"Family decision-making roles:","bold":true}]},{"type":"table","header":[[{"text":"Role"}],[{"text":"What the person does"}]],"rows":[[[{"text":"Initiator","bold":true}],[{"text":"Recognises the problem and "},{"text":"begins","bold":true},{"text":" the decision-making process"}]],[[{"text":"Influencer","bold":true}],[{"text":"Exerts "},{"text":"personal influence","bold":true},{"text":" on the decision"}]],[[{"text":"Information gatherer","bold":true}],[{"text":"Seeks information","bold":true},{"text":" about available products and their characteristics"}]],[[{"text":"Decision maker","bold":true},{"text":" (decider)"}],[{"text":"Makes the "},{"text":"final decision","bold":true}]],[[{"text":"Purchaser","bold":true},{"text":" (buyer)"}],[{"text":"Actually buys the product"}]],[[{"text":"User","bold":true}],[{"text":"Consumes or uses the product"}]]]},{"type":"paragraph","text":[{"text":"Kotler's general "},{"text":"buying roles","bold":true},{"text":" (5): initiator, influencer, decider, buyer, user."}]},{"type":"paragraph","text":[{"text":"Reference group:","bold":true},{"text":" a group whose values, attitudes or behaviour a person adopts and uses as a guide (family, friends, associations, civic and professional bodies). It can influence positively or negatively."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"membership","bold":true},{"text":" group (you belong to it), "},{"text":"aspiration","bold":true},{"text":" group (you want to belong to it), "},{"text":"disassociative","bold":true},{"text":" group (you do not want to belong to it)."}]},{"text":[{"text":"The "},{"text":"family","bold":true},{"text":" is the most important "},{"text":"primary","bold":true},{"text":" reference group."}]},{"text":[{"text":"3 kinds of influence","bold":true},{"text":" a reference group exerts:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Informational influence:","bold":true},{"text":" it is a source of "},{"text":"believable information","bold":true},{"text":" about brands and companies."}]},{"text":[{"text":"Comparative influence:","bold":true},{"text":" it gives members something to "},{"text":"compare","bold":true},{"text":" their beliefs, attitudes and behaviour "},{"text":"against","bold":true},{"text":"."}]},{"text":[{"text":"Normative influence:","bold":true},{"text":" it persuades members to "},{"text":"conform to its norms","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Affinity marketing:","bold":true},{"text":" marketing aimed at members of a reference group, with the group endorsing the product to its members (e.g. a credit card endorsed by an alumni association)."}]},{"text":[{"text":"A group's influence depends on the person's "},{"text":"susceptibility","bold":true},{"text":" and "},{"text":"strength of involvement","bold":true},{"text":" with the group."}]}]},{"type":"paragraph","text":[{"text":"Social class:","bold":true},{"text":" an "},{"text":"open","bold":true},{"text":" group of people with "},{"text":"similar social rank","bold":true},{"text":", based on occupation, education, income, wealth, race, ethnicity and possessions. It shapes the type, quality and quantity of products bought."}]},{"type":"paragraph","text":[{"text":"Culture:","bold":true},{"text":" the values, ideas and attitudes accepted by a "},{"text":"homogeneous","bold":true},{"text":" group of people and "},{"text":"passed down from one generation to the next","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Subculture:","bold":true},{"text":" a sub-group within a culture with its own "},{"text":"distinguishing modes of behaviour","bold":true},{"text":", based on geographic region or human characteristics such as age and ethnic background. In Nigeria: "},{"text":"Yoruba, Hausa and Igbo","bold":true},{"text":" subcultures, among others."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: \"age and life-cycle stage\" is "},{"text":"personal","bold":true},{"text":"; \"social status\", \"peer influence\" and \"cultural heritage\" are "},{"text":"social","bold":true},{"text":". \"Head still working\" = "},{"text":"Empty nest I","bold":true},{"text":"; \"head retired\" = "},{"text":"Empty nest II","bold":true},{"text":"."}]},{"text":[{"text":"Family roles at home:","bold":true},{"text":" a child says the family needs a new television (initiator); the mother compares prices online at Slot and Jumia (information gatherer); the eldest son argues for a smart TV (influencer); the father decides (decision maker); the mother pays at the shop (purchaser); everyone watches (users). In dual-income homes children influence more purchases."}]},{"text":[{"text":"Reference groups:","bold":true},{"text":" Kunle, a 200L accounting student, copies the suits and briefcases of a professional accounting body he hopes to join: an "},{"text":"aspiration group","bold":true},{"text":". A friend's honest phone review: informational influence. Classmates who mock anyone not wearing a certain sneaker brand: normative influence. Reference group endorsements are a "},{"text":"social","bold":true},{"text":" factor shaping brand loyalty among young adults."}]},{"text":[{"text":"Social class:","bold":true},{"text":" upper-middle-class buyers lean towards brands like Mercedes; lower-class shoppers tend to shop near home and do little information search. Stores project class images (a Lekki boutique versus a Balogun stall). \"Open\" means people can move between classes."}]},{"text":[{"text":"Culture in Nigeria:","bold":true},{"text":" respect for age and duty to the extended family shape buying. Culture also decides which adverts are acceptable: drinking beer in the open is normal in Lagos but may be frowned upon in parts of the North. Wise firms treat subcultures as separate market segments."}]},{"text":[{"text":"Family, reference groups and social class are all social influences operating "},{"text":"inside","bold":true},{"text":" a wider culture. So \"culture, subculture and reference groups\" are correctly called social influences in the three-category scheme."}]}]}]},{"number":"5.5","title":"Organisational markets and organisational buying behaviour","mustKnow":[{"type":"paragraph","text":[{"text":"Kotler's 5 customer markets:","bold":true},{"text":" "},{"text":"consumer","bold":true},{"text":" (individuals and households buying for personal use) plus four "},{"text":"organisational","bold":true},{"text":" markets:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Industrial (producer):","bold":true},{"text":" buy to produce other goods and services for profit or other objectives."}]},{"text":[{"text":"Reseller:","bold":true},{"text":" buy goods and services "},{"text":"in order to resell them at a profit","bold":true},{"text":" (wholesalers, retailers)."}]},{"text":[{"text":"Government and non-profit:","bold":true},{"text":" buy to produce public services or pass goods to those who need them."}]},{"text":[{"text":"International:","bold":true},{"text":" buyers abroad (consumers, producers, resellers, governments)."}]}]},{"type":"paragraph","text":[{"text":"Organisational versus consumer markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fewer but larger buyers.","bold":true}]},{"text":[{"text":"Geographically concentrated","bold":true},{"text":"; consumer markets comprise many thousands of scattered consumers."}]},{"text":[{"text":"Derived demand:","bold":true},{"text":" comes from the demand for consumer goods."}]},{"text":[{"text":"Demand is fairly "},{"text":"inelastic","bold":true},{"text":" and "},{"text":"fluctuates","bold":true},{"text":" more."}]},{"text":[{"text":"More "},{"text":"formal","bold":true},{"text":" buying by "},{"text":"trained, professional","bold":true},{"text":" buyers, with "},{"text":"many people","bold":true},{"text":" involved."}]},{"text":[{"text":"Close buyer-seller relationships","bold":true},{"text":"; direct buying, reciprocity, leasing."}]},{"text":[{"text":"Industrial products are "},{"text":"more technical and complex","bold":true},{"text":" than consumer products."}]}]},{"type":"paragraph","text":[{"text":"Buying centre:","bold":true},{"text":" the "},{"text":"decision-making unit","bold":true},{"text":" of a buying organisation: all the individuals and groups who participate in its purchasing decision process."}]},{"type":"table","header":[[{"text":"Buying centre role"}],[{"text":"What they do"}]],"rows":[[[{"text":"Users","bold":true}],[{"text":"Will "},{"text":"use","bold":true},{"text":" the product or service"}]],[[{"text":"Influencers","bold":true}],[{"text":"Provide "},{"text":"information","bold":true},{"text":" that influences the decision (often technical staff who draw up specifications)"}]],[[{"text":"Buyers","bold":true}],[{"text":"Have "},{"text":"formal authority","bold":true},{"text":" to select the supplier and arrange the terms of purchase"}]],[[{"text":"Deciders","bold":true}],[{"text":"Make the "},{"text":"final decision","bold":true}]],[[{"text":"Approvers","bold":true}],[{"text":"Authorise","bold":true},{"text":" the actions proposed by deciders or buyers"}]],[[{"text":"Gatekeepers","bold":true}],[{"text":"Control the flow of information","bold":true},{"text":" into the organisation (and access to members)"}]]]},{"type":"paragraph","text":[{"text":"Kotler adds "},{"text":"initiators","bold":true},{"text":" (those who first request the purchase). \"Promoter\" is "},{"text":"not","bold":true},{"text":" a buying centre role."}]},{"type":"paragraph","text":[{"text":"Buy classes:","bold":true},{"text":" organisational buying situations are divided into "},{"text":"3 classes","bold":true},{"text":", called "},{"text":"buy classes","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Straight rebuy:","bold":true},{"text":" a routine reorder; the company has "},{"text":"extensive experience","bold":true},{"text":", the process is simple and routine, nothing changes."}]},{"text":[{"text":"Modified rebuy:","bold":true},{"text":" a "},{"text":"recurring purchase that is less routine","bold":true},{"text":"; the buyer changes specifications, prices, terms or suppliers."}]},{"text":[{"text":"New task:","bold":true},{"text":" buying something "},{"text":"for the first time","bold":true},{"text":"; requires the buyer to undertake a new purchasing task, with the most information search and the most people involved."}]}]},{"type":"paragraph","text":[{"text":"\"Limited decision making\" is a "},{"text":"consumer","bold":true},{"text":" behaviour type, "},{"text":"not","bold":true},{"text":" a buy class."}]},{"type":"paragraph","text":[{"text":"Buy phases:","bold":true},{"text":" the stages of the organisational buying decision process (Kotler's 8):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Problem recognition:","bold":true},{"text":" someone in the company recognises an "},{"text":"unmet need","bold":true},{"text":" that can be met by acquiring a good or service"}]},{"text":[{"text":"General need description"}]},{"text":[{"text":"Product specification"}]},{"text":[{"text":"Supplier search"}]},{"text":[{"text":"Proposal solicitation"}]},{"text":[{"text":"Supplier selection"}]},{"text":[{"text":"Order-routine specification"}]},{"text":[{"text":"Performance review"}]}]},{"type":"paragraph","text":[{"text":"4 major influences on organisational buying:","bold":true},{"text":" "},{"text":"environmental","bold":true},{"text":" (economy, technology, politics, competition), "},{"text":"organisational","bold":true},{"text":" (objectives, policies, procedures, structure), "},{"text":"interpersonal","bold":true},{"text":" (the "},{"text":"buying centre","bold":true},{"text":"), "},{"text":"individual","bold":true},{"text":" (each buyer's age, education, position, personality, attitude to risk). Market segmentation is "},{"text":"not","bold":true},{"text":" one."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Derived demand:","bold":true},{"text":" when more households build houses, demand for cement rises, so a cement maker's demand for "},{"text":"limestone","bold":true},{"text":" rises."}]},{"text":[{"text":"Buying centre in action:","bold":true},{"text":" at an oil-servicing firm in Port Harcourt, the manager's secretary decides which sales representatives see him and which brochures reach his desk: "},{"text":"gatekeeper","bold":true},{"text":". At a bottling company, operators who will run a new filling machine every day: "},{"text":"users","bold":true},{"text":". Engineers who write crane specifications but do not place the order: "},{"text":"influencers","bold":true},{"text":". A purchasing officer with formal authority to pick the supplier and negotiate terms: "},{"text":"buyer","bold":true},{"text":". A ₦15,000,000 generator recommended by the purchasing team cannot go ahead until the managing director signs: "},{"text":"approver","bold":true},{"text":"."}]},{"text":[{"text":"Buy classes in action:","bold":true},{"text":" a Lagos school reorders the same A4 paper from the same supplier every month with no changes: "},{"text":"straight rebuy","bold":true},{"text":". A hotel changes the fabric specification for bed sheets and invites two new suppliers to quote alongside its current one: "},{"text":"modified rebuy","bold":true},{"text":". A Kano textile company buys a solar power system for the first time after gathering a great deal of information: "},{"text":"new task","bold":true},{"text":"."}]},{"text":[{"text":"Performance review","bold":true},{"text":" is the "},{"text":"last","bold":true},{"text":" buy phase: the firm checks how well the chosen supplier performed."}]},{"text":[{"text":"Do not confuse the "},{"text":"family roles","bold":true},{"text":" (initiator, influencer, information gatherer, decision maker, purchaser, user) with the "},{"text":"buying centre roles","bold":true},{"text":" (users, influencers, buyers, deciders, approvers, gatekeepers)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"6 stages: problem recognition, information search (internal, external; evoked set), evaluation of alternatives, purchase decision, purchase, post-purchase evaluation. Cognitive dissonance = post-purchase doubt, cut by warranties and after-sales contact."}]},{"text":[{"text":"Involvement = importance and intensity of interest; higher risk means higher involvement. Risks: personal, social, economic."}]},{"text":[{"text":"4 types: routine response, limited, extensive (complex), impulse. Inertia = repeat buying to save effort."}]},{"text":[{"text":"3 factor categories: personal (age, life-cycle stage, occupation, income), psychological (motives, perception, learning, attitudes, personality), social (family, reference groups, social class, culture, subculture). Kotler adds cultural as a fourth."}]},{"text":[{"text":"Maslow: physiological, safety, love and belonging, esteem, self-actualisation. Perception: selective exposure, distortion, retention."}]},{"text":[{"text":"Reference groups: membership, aspiration, disassociative; influence is informational, comparative, normative. Family is the most important primary reference group."}]},{"text":[{"text":"Buying centre: users, influencers, buyers, deciders, approvers, gatekeepers. 3 buy classes: straight rebuy, modified rebuy, new task. Process stages = buy phases, starting with problem recognition."}]}]}],"theory":{"itemId":"72cecbbf-ccbc-54ba-b26e-59ad73fff229","question":[{"type":"paragraph","text":[{"text":"A Lagos bakery that has always bought flour from one miller decides to test a new flour blend and asks two other millers to quote. Name the buy class, and explain how it differs from the other two buy classes."}]}]},"practice":[{"topic":"Consumer and Organisational Buying Behaviour","named":false}]}},{"itemId":"40d1a9f8-f5b1-5c8c-940e-c76e047c1f38","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Marketing Mix and Product Life Cycle","body":"The meaning and importance of the marketing mix; the 4Ps (McCarthy, 1960s), the 7Ps of services and the 4Cs (1990s); product levels, classes, branding and packaging; pricing objectives, methods and strategies (skimming, penetration); distribution strategies and channels; the promotion tools; people, process, physical evidence and the features of services; the product life cycle stages, their features and strategies; market share.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The meaning and importance of the marketing mix; the 4Ps (McCarthy, 1960s), the 7Ps of services and the 4Cs (1990s); product levels, classes, branding and packaging; pricing objectives, methods and strategies (skimming, penetration); distribution strategies and channels; the promotion tools; people, process, physical evidence and the features of services; the product life cycle stages, their features and strategies; market share."}],"lessons":[{"number":"6.1","title":"Meaning and importance of the marketing mix","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing mix (simple meaning):","bold":true},{"text":" putting the "},{"text":"right product","bold":true},{"text":", or a combination of products, in the "},{"text":"right place","bold":true},{"text":", at the "},{"text":"right time","bold":true},{"text":" and at the "},{"text":"right price","bold":true},{"text":". The difficult part is doing it well: you must know every aspect of your business plan."}]},{"text":[{"text":"Marketing mix (formal):","bold":true},{"text":" the set of "},{"text":"controllable marketing tools","bold":true},{"text":" a firm "},{"text":"blends","bold":true},{"text":" to produce the response it wants in its "},{"text":"target market","bold":true},{"text":". It is the set of actions a firm uses to build and market its offering."}]},{"text":[{"text":"It is a programme of marketing elements designed for a specific product in response to the marketing forces (consumer behaviour, competitors, government) that affect it. The mix is "},{"text":"controllable","bold":true},{"text":"; the environment is "},{"text":"uncontrollable","bold":true},{"text":"."}]},{"text":[{"text":"Three frameworks:","bold":true}]}]},{"type":"table","header":[[{"text":"Framework"}],[{"text":"Elements"}],[{"text":"Origin"}]],"rows":[[[{"text":"4Ps","bold":true},{"text":" (marketing mix)"}],[{"text":"Product, Price, Place, Promotion"}],[{"text":"E. Jerome McCarthy","bold":true},{"text":", "},{"text":"1960s","bold":true}]],[[{"text":"7Ps","bold":true},{"text":" (services marketing mix)"}],[{"text":"4Ps + "},{"text":"People, Process, Physical evidence","bold":true}],[{"text":"Extension of the 4Ps, used mostly for services"}]],[[{"text":"4Cs","bold":true},{"text":" (customer's view)"}],[{"text":"Customer solution (wants and needs), Cost, "},{"text":"Convenience","bold":true},{"text":", Communication"}],[{"text":"Developed in the "},{"text":"1990s","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4Ps to 4Cs:","bold":true},{"text":" product → customer solution; price → customer cost; "},{"text":"place → convenience","bold":true},{"text":"; promotion → communication."}]}]},{"type":"paragraph","text":[{"text":"8 points of importance of the marketing mix.","bold":true},{"text":" It:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clarifies what the offering gives customers."}]},{"text":[{"text":"Helps plan a successful product offering."}]},{"text":[{"text":"Helps plan, develop and execute effective strategies."}]},{"text":[{"text":"Helps leverage strengths and avoid unnecessary costs."}]},{"text":[{"text":"Helps the firm be proactive about risks."}]},{"text":[{"text":"Shows whether the offering suits customers."}]},{"text":[{"text":"Identifies customer requirements."}]},{"text":[{"text":"Shows when and how to promote."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Purpose:","bold":true},{"text":" to combine the controllable tools to respond to the target market, "},{"text":"balancing customer value with organisational goals","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Using the mix:","bold":true},{"text":" all 7Ps "},{"text":"work together","bold":true},{"text":", and they also affect "},{"text":"segmentation, targeting and positioning","bold":true},{"text":" decisions. Never plan one element alone, and the mix is not fixed: it changes over the product's life."}]},{"text":[{"text":"Traps: \"4 Cs model\", \"4 Es\" and \"4 Ms\" are not the name of the marketing mix; the mix is the "},{"text":"4 Ps framework","bold":true},{"text":". People is "},{"text":"not","bold":true},{"text":" one of McCarthy's original 4Ps, and "},{"text":"positioning","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" one of the 7Ps. The 4Ps were created by McCarthy, not Kotler, Porter or Drucker."}]},{"text":[{"text":"Example: Indomie gets the mix right with a product children like (product), a low pack price (price), presence in every kiosk (place) and catchy TV and school campaigns (promotion)."}]}]}]},{"number":"6.2","title":"Product: levels, classes, branding and packaging","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Product:","bold":true},{"text":" anything that can be offered to a market for "},{"text":"attention, acquisition, use or consumption","bold":true},{"text":" that might satisfy a want or need. It is a "},{"text":"bundle of tangible and intangible benefits","bold":true},{"text":": a good (shoes) or a service (hotel, airline) that solves a customer need. A mix "},{"text":"always begins with a product","bold":true},{"text":" to sell."}]},{"text":[{"text":"Product decisions:","bold":true},{"text":" designing offerings that meet customer expectations: "},{"text":"features, quality, design, branding, packaging, labelling, support services","bold":true},{"text":" and planning across the product's "},{"text":"life cycle","bold":true},{"text":"."}]},{"text":[{"text":"Key questions:","bold":true},{"text":" What does the client want from the product? How, where and why does the client use it? Is it better than competitors'?"}]}]},{"type":"paragraph","text":[{"text":"3 product levels:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Core customer value (core benefit):","bold":true},{"text":" what the buyer is "},{"text":"really","bold":true},{"text":" buying, the problem solved."}]},{"text":[{"text":"Actual product:","bold":true},{"text":" "},{"text":"brand name, features, design, quality level and packaging","bold":true},{"text":"."}]},{"text":[{"text":"Augmented product:","bold":true},{"text":" extra services and benefits: "},{"text":"delivery, installation, warranty, after-sales service, credit","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 classes of consumer products:","bold":true}]},{"type":"table","header":[[{"text":"Class"}],[{"text":"How it is bought"}],[{"text":"Examples"}]],"rows":[[[{"text":"Convenience","bold":true}],[{"text":"Frequently, immediately, little comparison or effort"}],[{"text":"Bread, sachet water, toothpaste"}]],[[{"text":"Shopping","bold":true}],[{"text":"Less often; buyer "},{"text":"compares","bold":true},{"text":" quality, price, style"}],[{"text":"Furniture, clothes, phones"}]],[[{"text":"Specialty","bold":true}],[{"text":"Strong brand preference; buyer makes a "},{"text":"special effort","bold":true},{"text":", will not accept substitutes"}],[{"text":"A particular luxury watch or car"}]],[[{"text":"Unsought","bold":true}],[{"text":"Buyer does not know of it or does not normally think of buying it until a need arises"}],[{"text":"Life insurance, funeral services, blood donation"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Industrial (business) products:","bold":true},{"text":" materials and parts, capital items, supplies and services."}]},{"text":[{"text":"Brand:","bold":true},{"text":" a name, term, sign, symbol or design (or a combination) that identifies one seller's product and differentiates it from competitors. A "},{"text":"trademark","bold":true},{"text":" is a legally protected brand. "},{"text":"Sub-branding","bold":true},{"text":" creates a separate but related brand for a new segment without diluting the parent brand."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" designing and producing the container or wrapper. Functions: "},{"text":"contain and protect, inform (label), promote, give convenience","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example of levels: a trader pays ₦850,000 for a generator in Ibadan. Keeping his shop running during power cuts is the "},{"text":"core benefit","bold":true},{"text":"; the brand, the kVA rating, design and the box are the "},{"text":"actual product","bold":true},{"text":"; free delivery, installation and a two-year warranty are the "},{"text":"augmented product","bold":true},{"text":"."}]},{"text":[{"text":"Convenience products include "},{"text":"staples","bold":true},{"text":" (bread), "},{"text":"impulse","bold":true},{"text":" goods (sweets at the till) and "},{"text":"emergency","bold":true},{"text":" goods (umbrellas in a downpour)."}]},{"text":[{"text":"A collector in Abuja who travels to Lagos for the only authorised dealer of one watch brand treats it as a "},{"text":"specialty","bold":true},{"text":" product. The same watch could be a shopping product for someone comparing several brands: classification depends on "},{"text":"how the buyer buys","bold":true},{"text":"."}]},{"text":[{"text":"Product mix:","bold":true},{"text":" all the product lines a firm sells (Dangote sells cement, sugar and salt lines). Do not confuse it with the marketing mix."}]},{"text":[{"text":"Branding and packaging also count as "},{"text":"physical evidence","bold":true},{"text":" (Lesson 6.5). In Nigeria, food and drug labels carry a "},{"text":"NAFDAC","bold":true},{"text":" registration number. Tamper-proof packaging was one firm response to consumer fears and legal pressure."}]}]}]},{"number":"6.3","title":"Price: objectives, methods and strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Price:","bold":true},{"text":" the amount customers pay for a product. "},{"text":"Price is the only element that produces revenue","bold":true},{"text":"; the others mainly represent costs. It determines "},{"text":"profit","bold":true},{"text":", and changing it affects the whole strategy, sales and demand."}]},{"text":[{"text":"3 things price is set against:","bold":true},{"text":" "},{"text":"production cost","bold":true},{"text":", "},{"text":"competitors' price ranges","bold":true},{"text":", "},{"text":"customers' perceived value","bold":true},{"text":". Pricing must balance "},{"text":"customer perceived value and competitive positioning","bold":true},{"text":"."}]},{"text":[{"text":"Price signals quality:","bold":true},{"text":" buyers often judge a higher-priced product as better quality."}]}]},{"type":"paragraph","text":[{"text":"Pricing objectives:","bold":true},{"text":" survival; current profit maximisation; market-share leadership; product-quality leadership; target return on investment; meeting or matching competition."}]},{"type":"paragraph","text":[{"text":"Pricing methods:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost-based (cost-plus / mark-up):","bold":true},{"text":" add a standard mark-up to unit cost."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit cost = variable cost + (fixed cost ÷ unit sales)"}]},{"text":[{"text":"Mark-up on cost: price = unit cost × (1 + mark-up)"}]},{"text":[{"text":"Mark-up on selling price: price = unit cost ÷ (1 − desired return on sales)"}]},{"text":[{"text":"Break-even volume = fixed cost ÷ (price − variable cost)"}]}]}]},{"text":[{"text":"Value-based:","bold":true},{"text":" price set on buyers' perceived value."}]},{"text":[{"text":"Competition-based (going-rate / competitive parity):","bold":true},{"text":" price in line with competitors' prices."}]}]},{"type":"paragraph","text":[{"text":"Pricing strategies:","bold":true}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Price skimming","bold":true}],[{"text":"High price at launch to earn "},{"text":"high margins on innovative products","bold":true},{"text":" in the early period, then lower step by step"}]],[[{"text":"Penetration pricing","bold":true}],[{"text":"Low entry price","bold":true},{"text":" to win a "},{"text":"large market share rapidly","bold":true}]],[[{"text":"Competitive pricing","bold":true}],[{"text":"Prices "},{"text":"in line with competitors","bold":true}]],[[{"text":"Psychological pricing","bold":true}],[{"text":"₦999 instead of ₦1,000"}]],[[{"text":"Prestige (premium) pricing","bold":true}],[{"text":"Deliberately high price to signal status"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked cost-plus example.","bold":true},{"text":" Variable cost ₦400 per unit, fixed cost ₦2,000,000, expected sales 50,000 units."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit cost = 400 + (2,000,000 ÷ 50,000) = 400 + 40 = "},{"text":"₦440","bold":true},{"text":"."}]},{"text":[{"text":"25% mark-up on cost: 440 × 1.25 = "},{"text":"₦550","bold":true},{"text":"."}]},{"text":[{"text":"20% return on selling price: 440 ÷ (1 − 0.20) = 440 ÷ 0.80 = "},{"text":"₦550","bold":true},{"text":"."}]},{"text":[{"text":"Break-even at ₦550: 2,000,000 ÷ (550 − 400) = 13,333.3, so "},{"text":"13,334 units","bold":true},{"text":" (rounded up to whole units)."}]}]}]},{"text":[{"text":"Skimming:","bold":true},{"text":" a phone launched in Lagos at ₦1,200,000 for buyers who want the newest model, then cut step by step. "},{"text":"Penetration:","bold":true},{"text":" a new mobile network entering with call rates far below established networks, to win many subscribers quickly."}]},{"text":[{"text":"Why a newcomer cannot charge very high prices:","bold":true},{"text":" the brand is only starting out, so customers do not yet "},{"text":"recognise or trust","bold":true},{"text":" it; trust comes with time. Skimming suits a genuinely innovative product with buyers willing to pay, not an unknown brand of an ordinary product."}]},{"text":[{"text":"Perceived quality:","bold":true},{"text":" a shopper who assumes a ₦28,000 perfume is better than a ₦3,500 one without trying either shows that price "},{"text":"shapes perceived quality","bold":true},{"text":". Inexperienced buyers lean on price most."}]},{"text":[{"text":"Traps: penetration is a "},{"text":"pricing","bold":true},{"text":" strategy, not a distribution strategy. Skimming does "},{"text":"not","bold":true},{"text":" aim at mass-market penetration, and cost-plus ignores demand and competition."}]}]}]},{"number":"6.4","title":"Place and promotion","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Place:","bold":true},{"text":" the "},{"text":"position and distribution","bold":true},{"text":" of the product so it is "},{"text":"accessible to the target audience","bold":true},{"text":": the right location at the right time (a shop, an online store, mail order, an easy-to-navigate website). It covers "},{"text":"supply-chain logistics and channel management","bold":true},{"text":"."}]},{"text":[{"text":"Distribution:","bold":true},{"text":" moving products from the point of production to the point of consumption. "},{"text":"Intermediaries","bold":true},{"text":" (wholesalers, retailers, agents) create "},{"text":"place, time and possession utility","bold":true},{"text":"."}]},{"text":[{"text":"Place questions:","bold":true},{"text":" Where do clients look for my product? Where do clients usually shop? Should I sell online?"}]}]},{"type":"paragraph","text":[{"text":"4 distribution strategies:","bold":true}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Intensive","bold":true}],[{"text":"As many outlets as possible"}],[{"text":"Soft drinks in every supermarket, kiosk, filling station and roadside stall"}]],[[{"text":"Selective","bold":true}],[{"text":"A few carefully chosen outlets per area"}],[{"text":"A home-appliance maker using chosen retailers in each city"}]],[[{"text":"Exclusive","bold":true}],[{"text":"One (or very few) dealers per area"}],[{"text":"A luxury car maker with one dealer in Lagos State"}]],[[{"text":"Franchising","bold":true}],[{"text":"Independent owners use the brand's name, recipes and systems for fees"}],[{"text":"Fast-food outlets in Port Harcourt and Enugu"}]]]},{"type":"paragraph","text":[{"text":"Channel levels:","bold":true},{"text":" zero-level (direct: producer → consumer); one-level (producer → retailer → consumer); two-level (producer → wholesaler → retailer → consumer); three-level (adds an agent or jobber)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Promotion:","bold":true},{"text":" methods to win attention, "},{"text":"build awareness and persuade","bold":true},{"text":" the target audience, driving "},{"text":"brand visibility, purchase intent, sales and brand recognition","bold":true},{"text":"."}]},{"text":[{"text":"Promotion tools (promotion mix):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Advertising:","bold":true},{"text":" paid, non-personal presentation through media."}]},{"text":[{"text":"Sales promotion:","bold":true},{"text":" short-term incentives (buy two, get one free; coupons; samples)."}]},{"text":[{"text":"Personal selling","bold":true},{"text":" (sales organisation): face-to-face selling that "},{"text":"builds direct customer relationships","bold":true},{"text":"."}]},{"text":[{"text":"Public relations:","bold":true},{"text":" building goodwill and a positive image (sponsorships, press releases)."}]},{"text":[{"text":"Direct and digital marketing","bold":true},{"text":", and "},{"text":"customer service","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Promotion questions:","bold":true},{"text":" When is the best time to promote? What strategy are competitors using? Should I use social media? How can I send messages to my audience? Which channel is best for my audience?"}]},{"text":[{"text":"The promotion choice depends on "},{"text":"budget, communication goals and target market","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MTN recharge cards and Coca-Cola use "},{"text":"intensive","bold":true},{"text":" distribution; luxury car brands use "},{"text":"exclusive","bold":true},{"text":" dealers; Jumia is an online channel (place), not a promotion tool."}]},{"text":[{"text":"A Surulere supermarket's \"buy two tins of milk, get one free\" for two weeks = "},{"text":"sales promotion","bold":true},{"text":". A beverage firm sponsoring a free health walk in Ibadan and sending a press release = "},{"text":"public relations","bold":true},{"text":"."}]},{"text":[{"text":"Traps: "},{"text":"franchising","bold":true},{"text":" is a distribution strategy, not a promotion tool; "},{"text":"penetration","bold":true},{"text":" is pricing, not distribution. \"Place\" in the mix is not the customer's home region and not the shop's physical surroundings (that is physical evidence)."}]},{"text":[{"text":"Services usually use a "},{"text":"direct channel","bold":true},{"text":" (bank, hotel, doctor) and widen reach through "},{"text":"franchising","bold":true},{"text":"."}]}]}]},{"number":"6.5","title":"People, process, physical evidence and services","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"People:","bold":true},{"text":" everyone tied to the offering: "},{"text":"customers","bold":true},{"text":" (is the target audience and demand large enough?) and "},{"text":"employees","bold":true},{"text":" who deliver it. Staff must be "},{"text":"fully trained","bold":true},{"text":" (customer service assistants, copywriters, designers, sales representatives)."}]},{"text":[{"text":"Process:","bold":true},{"text":" the systems and steps for delivering the service. Be "},{"text":"easy to do business with: efficient, helpful and timely","bold":true},{"text":". A good process "},{"text":"saves time and money","bold":true},{"text":" and keeps the "},{"text":"standard of service consistent","bold":true},{"text":", building reputation and loyalty. Remove bottlenecks; use process maps."}]},{"text":[{"text":"Physical evidence:","bold":true},{"text":" "},{"text":"everything a customer sees or hears","bold":true},{"text":" when interacting with the business: "},{"text":"branding, packaging, physical space (shop) and even the way staff and sales representatives act and dress","bold":true},{"text":". It must reflect brand values and can raise or lower sales."}]}]},{"type":"paragraph","text":[{"text":"4 characteristics of services:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Intangibility:","bold":true},{"text":" cannot be seen or touched in advance."}]},{"text":[{"text":"Inseparability:","bold":true},{"text":" produced and consumed at the same time; cannot be separated from the provider."}]},{"text":[{"text":"Heterogeneity (variability):","bold":true},{"text":" quality differs from one provider or occasion to another."}]},{"text":[{"text":"Perishability:","bold":true},{"text":" cannot be stored; unused capacity is lost forever."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Other features: "},{"text":"fluctuating (seasonal) demand","bold":true},{"text":"; prices set by "},{"text":"demand and competition","bold":true},{"text":"; a "},{"text":"direct channel","bold":true},{"text":", widened by franchising."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A hotel in Victoria Island training front-desk staff for two weeks strengthens "},{"text":"people","bold":true},{"text":". A bank branch in Ikeja cutting account opening from two days to 30 minutes improves "},{"text":"process","bold":true},{"text":". A Lekki restaurant repainting, relighting, reprinting menus and replacing its signboard changes "},{"text":"physical evidence","bold":true},{"text":"."}]},{"text":[{"text":"Trap: training staff is "},{"text":"people","bold":true},{"text":"; how staff look and dress as the customer sees them is part of "},{"text":"physical evidence","bold":true},{"text":". If asked what physical evidence includes among branding, packaging, shop space and staff dress, choose "},{"text":"all of them","bold":true},{"text":"."}]},{"text":[{"text":"Why physical evidence matters:","bold":true},{"text":" services are "},{"text":"intangible","bold":true},{"text":", so customers look for "},{"text":"visible cues","bold":true},{"text":" to judge quality (a clean banking hall, smart uniforms)."}]},{"text":[{"text":"Empty seats on a half-full Lagos-Abuja flight cannot be sold tomorrow: "},{"text":"perishability","bold":true},{"text":". Customers waiting for one particular barber in Yaba because haircuts differ: "},{"text":"variability","bold":true},{"text":". Variability is reduced by training and standards but never removed."}]}]}]},{"number":"6.6","title":"The product life cycle and market share","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Product life cycle (PLC):","bold":true},{"text":" the course of a product's "},{"text":"sales and profits over its lifetime","bold":true},{"text":". Before launch there is "},{"text":"product development","bold":true},{"text":" (no sales, rising costs). After launch: "},{"text":"Introduction → Growth → Maturity → Decline","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Introduction"}],[{"text":"Growth"}],[{"text":"Maturity"}],[{"text":"Decline"}]],"rows":[[[{"text":"Sales"}],[{"text":"Low"}],[{"text":"Rising rapidly"}],[{"text":"Peak","bold":true}],[{"text":"Declining"}]],[[{"text":"Cost per customer"}],[{"text":"Highest","bold":true}],[{"text":"Average"}],[{"text":"Low"}],[{"text":"Low"}]],[[{"text":"Profits"}],[{"text":"Low or negative"}],[{"text":"Rising"}],[{"text":"High"}],[{"text":"Declining"}]],[[{"text":"Customers"}],[{"text":"Innovators"}],[{"text":"Early adopters"}],[{"text":"Middle majority"}],[{"text":"Laggards","bold":true}]],[[{"text":"Competitors"}],[{"text":"Few"}],[{"text":"Growing number"}],[{"text":"Stable, beginning to decline"}],[{"text":"Declining"}]],[[{"text":"Objective"}],[{"text":"Awareness and trial"}],[{"text":"Maximise market share"}],[{"text":"Maximise profit, defend share"}],[{"text":"Cut spending, milk the brand"}]],[[{"text":"Price"}],[{"text":"Cost-plus (or skim or penetrate)"}],[{"text":"Price to penetrate; lower prices"}],[{"text":"Match or beat competitors"}],[{"text":"Cut price"}]],[[{"text":"Distribution"}],[{"text":"Selective"}],[{"text":"Intensive"}],[{"text":"More intensive"}],[{"text":"Selective; close unprofitable outlets"}]],[[{"text":"Advertising"}],[{"text":"Awareness among "},{"text":"early adopters and dealers","bold":true}],[{"text":"Awareness and interest in mass market"}],[{"text":"Stress brand differences and benefits","bold":true}],[{"text":"Reduce to level that keeps "},{"text":"hard-core loyals","bold":true}]],[[{"text":"Sales promotion"}],[{"text":"Heavy, to entice trial","bold":true}],[{"text":"Reduce"}],[{"text":"Increase to encourage brand switching","bold":true}],[{"text":"Reduce to minimum"}]],[[{"text":"Product"}],[{"text":"Basic product"}],[{"text":"Extensions, service, warranty"}],[{"text":"Diversify brands and models"}],[{"text":"Phase out weak items","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Maturity","bold":true},{"text":" usually "},{"text":"lasts longest","bold":true},{"text":". Its strategies: "},{"text":"modify the market","bold":true},{"text":" (new users, new uses, new segments), "},{"text":"modify the product","bold":true},{"text":" (quality, features, style, variants), "},{"text":"modify the marketing mix","bold":true},{"text":"."}]},{"text":[{"text":"Decline","bold":true},{"text":" is triggered by "},{"text":"new technology or shifts in consumer preferences","bold":true},{"text":" (and competition). Options: "},{"text":"maintain","bold":true},{"text":" (reposition or revitalise, find new uses or markets), "},{"text":"harvest","bold":true},{"text":" (cut R&D and advertising, milk short-run cash), "},{"text":"drop","bold":true},{"text":" (discontinue or sell). Marketers must "},{"text":"find new ways to increase sales again","bold":true},{"text":" or reinvent the product."}]},{"text":[{"text":"Style:","bold":true},{"text":" a basic, distinctive mode of expression, lasting generations. "},{"text":"Fashion:","bold":true},{"text":" a currently accepted, popular style. "},{"text":"Fad:","bold":true},{"text":" a short period of unusually high sales driven by consumer enthusiasm and immediate popularity, then a quick fade."}]},{"text":[{"text":"Market share","bold":true},{"text":" = (firm's sales ÷ total industry sales of that product type) × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value of the PLC:","bold":true},{"text":" a dynamic tool to tailor strategy to each stage and to help forecast performance. It is not a fixed roadmap."}]},{"text":[{"text":"Spotting the stage:","bold":true},{"text":" a plantain-chip brand six months old, slow sales, few aware, almost no rivals, heavy awareness spending = "},{"text":"introduction","bold":true},{"text":". A bottled-water brand going ₦10m → ₦25m → ₦60m (up 150% then 140%) while rivals enter = "},{"text":"growth","bold":true},{"text":". A detergent ad stressing brand differences plus promotions to make rivals' customers switch = "},{"text":"maturity","bold":true},{"text":"."}]},{"text":[{"text":"A mature tea brand pushing iced tea to young non-drinkers = "},{"text":"modifying the market","bold":true},{"text":". A declining noodles brand cutting research and advertising to earn short-run cash = "},{"text":"harvesting","bold":true},{"text":"."}]},{"text":[{"text":"Introduction: high costs, low sales, low or negative profits, overcoming "},{"text":"consumer unfamiliarity","bold":true},{"text":". Growth: rising acceptance, competitors enter, so "},{"text":"differentiate","bold":true},{"text":". Maturity: slowing growth, intense competition, sustained promotion, new variants or segments."}]},{"text":[{"text":"Traps: relaunching an unchanged product does not return it to introduction; raising prices for exclusivity and aggressive expansion are not decline strategies."}]},{"text":[{"text":"Market share example:","bold":true},{"text":" industry sales of bottled water in a state are ₦800 million; one brand sells ₦120 million. Share = (120 ÷ 800) × 100 = "},{"text":"15%","bold":true},{"text":". Not 85% (the rest of the market) and not 6.67% (800 ÷ 120, upside down)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing mix = controllable tools blended for the target market: right product, place, time, price."}]},{"text":[{"text":"4Ps by McCarthy (1960s); 7Ps add people, process, physical evidence; 4Cs (1990s): place = convenience."}]},{"text":[{"text":"Product levels: core benefit, actual, augmented. Consumer products: convenience, shopping, specialty, unsought."}]},{"text":[{"text":"Price is the only revenue element and signals quality. Skimming = high launch price; penetration = low price for quick share."}]},{"text":[{"text":"Distribution: intensive, selective, exclusive, franchising. Promotion: advertising, sales promotion, personal selling, PR."}]},{"text":[{"text":"Services: intangible, inseparable, variable, perishable; physical evidence gives visible cues."}]},{"text":[{"text":"PLC: introduction, growth, maturity (peak, longest), decline (laggards; maintain, harvest, drop)."}]},{"text":[{"text":"Market share = firm's sales ÷ industry sales × 100."}]}]}],"theory":{"itemId":"e1dcb7c5-e773-5f9c-9c3d-921f683a9199","question":[{"type":"paragraph","text":[{"text":"Industry sales of packaged juice in Lagos were ₦2,500 million last year and ₦2,600 million this year. Brand A sold ₦400 million last year and ₦390 million this year. Find Brand A's market share each year, the industry growth rate, and the likely PLC stage of the category. Suggest two strategies."}]}]},"practice":[{"topic":"Marketing Mix and Product Life Cycle","named":false}]}},{"itemId":"7179f3be-8cc7-5b2f-a412-b9fcb926fc19","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Market Segmentation","body":"The meaning and origin of segmentation; the nature of a good segment and preference patterns; the bases (geographic, demographic, psychographic, behavioural, plus business markets) and every variable under each; the five requirements for effective segmentation; benefits and disadvantages; targeting strategies; positioning; simple segment-size and market-share sums.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The meaning and origin of segmentation; the nature of a good segment and preference patterns; the bases (geographic, demographic, psychographic, behavioural, plus business markets) and every variable under each; the five requirements for effective segmentation; benefits and disadvantages; targeting strategies; positioning; simple segment-size and market-share sums."}],"lessons":[{"number":"7.1","title":"Meaning, origin and the nature of a segment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market segmentation:","bold":true},{"text":" the process of dividing a broad market into smaller groups of customers who share meaningful characteristics, such as demographics, geography, psychographics or behaviour. Put another way, it is dividing the market of potential customers into smaller, more defined segments by shared characteristics such as demographics, interests, needs or location."}]},{"text":[{"text":"Market segment:","bold":true},{"text":" one of those groups. Its members have one or more things in common, so the marketer can craft one message for the whole group."}]},{"text":[{"text":"Major reason for segmenting:","bold":true},{"text":" to create a "},{"text":"custom marketing mix for each segment","bold":true},{"text":" and cater to it accordingly."}]},{"text":[{"text":"Strategic goal:","bold":true},{"text":" to meet diverse customer needs more precisely, so the firm can customise offerings for distinct groups and focus effort on solutions tailored to each group."}]},{"text":[{"text":"Origin:","bold":true},{"text":" the concept was introduced by "},{"text":"Wendell R. Smith","bold":true},{"text":" in his 1956 article \"Product Differentiation and Market Segmentation as Alternative Marketing Strategies\". Marketers have practised it since the late 1900s."}]},{"text":[{"text":"Opposite of segmentation:","bold":true},{"text":" "},{"text":"mass marketing","bold":true},{"text":" (one product, one programme, for everyone)."}]},{"text":[{"text":"Segmentation vs product differentiation:","bold":true},{"text":" segmentation focuses on the "},{"text":"market","bold":true},{"text":" (the buyers); product differentiation focuses on "},{"text":"product differences","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Nature of a good segment","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Internally homogeneous:","bold":true},{"text":" members share something the marketer can use."}]},{"text":[{"text":"Externally heterogeneous:","bold":true},{"text":" each segment differs clearly from other segments."}]},{"text":[{"text":"Members "},{"text":"respond in a similar way","bold":true},{"text":" to the marketing activities aimed at them (similar features alone are not enough)."}]}]},{"type":"paragraph","text":[{"text":"Memorise the rule: "},{"text":"a good segment is internally homogeneous and externally heterogeneous.","bold":true}]},{"type":"paragraph","text":[{"text":"Preference patterns","bold":true},{"text":" (how buyers' preferences spread out)"}]},{"type":"table","header":[[{"text":"Pattern"}],[{"text":"What it looks like"}],[{"text":"What it means"}]],"rows":[[[{"text":"Homogeneous"}],[{"text":"All buyers want roughly the same thing"}],[{"text":"Treat the whole market as one segment (e.g. table salt)"}]],[[{"text":"Diffused"}],[{"text":"Preferences scattered everywhere"}],[{"text":"In the extreme, each consumer is a separate segment"}]],[[{"text":"Clustered"}],[{"text":"Groups of buyers with similar preferences"}],[{"text":"Natural segments form (clusters)"}]]]},{"type":"paragraph","text":[{"text":"Customer-driven marketing strategy (STP), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Segmentation:","bold":true},{"text":" divide the market."}]},{"text":[{"text":"Targeting:","bold":true},{"text":" choose which segment(s) to serve."}]},{"text":[{"text":"Positioning:","bold":true},{"text":" create a clear, distinctive place in target customers' minds (then differentiate the offer to deliver it)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentation makes it easier to personalise campaigns, focus on what is necessary and group similar consumers so they can be reached cost-effectively. Today its main purpose is to get more "},{"text":"conversions","bold":true},{"text":" (sales) through personalised campaigns."}]},{"text":[{"text":"Wrong options in exams: \"treating all customers the same\", \"ignoring consumer diversity\", \"standardising marketing efforts\", \"reducing product diversity\", \"escalating costs\". These describe mass marketing or nonsense, never segmentation."}]},{"text":[{"text":"\"Concentrated preference pattern\" is "},{"text":"not","bold":true},{"text":" one of the three patterns; it is a distractor borrowed from \"concentrated marketing\". Products where tastes hardly vary (salt, sugar, petrol) show homogeneous preferences; fashion clothing, perfume and cars show scattered or clustered preferences."}]},{"text":[{"text":"Order trap: segmentation always comes first, positioning last. \"Targeting, segmentation, positioning\" is wrong."}]},{"text":[{"text":"Example:","bold":true},{"text":" Indomie does not sell one pack to everyone. It offers small single packs, bigger \"hungry man\" sizes and multipacks for families. Each pack serves a group with similar needs (internally alike) that differs from the others (externally different)."}]}]}]},{"number":"7.2","title":"Bases of segmentation, demographic and geographic","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basis (base) of segmentation:","bold":true},{"text":" the characteristic used to split the market. The four major consumer bases: "},{"text":"geographic, demographic, psychographic, behavioural","bold":true},{"text":"."}]},{"text":[{"text":"Two ways to group bases:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Descriptive bases:","bold":true},{"text":" dimensions that simply "},{"text":"describe","bold":true},{"text":" consumers in a segment, e.g. age, income, location."}]},{"text":[{"text":"Causal bases:","bold":true},{"text":" dimensions that explain "},{"text":"why","bold":true},{"text":" customers respond to marketing mixes, e.g. benefits sought."}]}]}]},{"text":[{"text":"Segmentation by consumer characteristics","bold":true},{"text":" uses who the consumer is: geographic, demographic and psychographic variables (age, sex, income). "},{"text":"Segmentation by consumer responses","bold":true},{"text":" uses what consumers do or want: benefits, usage, occasions, loyalty (behavioural)."}]},{"text":[{"text":"Simple bases listed one by one: "},{"text":"gender, age group, income, place, occupation, usage, lifestyle","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Demographic segmentation:","bold":true},{"text":" groups people by population characteristics. Variables: "},{"text":"age, gender (sex), marital status, family size, income, religion, race, occupation, nationality","bold":true},{"text":" (also education). It is the "},{"text":"most common","bold":true},{"text":" type, the one most people think of when they hear \"market segmentation\". Its key strength: it uses "},{"text":"measurable, easily available data","bold":true},{"text":". It assumes buying behaviour is strongly influenced by demographics."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gender:","bold":true},{"text":" simple but important; male and female needs differ (cosmetics, clothing, jewellery)."}]},{"text":[{"text":"Age group:","bold":true},{"text":" most products do not suit all ages; age targeting improves strategy and conversion."}]},{"text":[{"text":"Income:","bold":true},{"text":" decides "},{"text":"purchasing power","bold":true},{"text":" and whether to market the product as a "},{"text":"need, a want or a luxury","bold":true},{"text":". Three groups: "},{"text":"high income, mid income, low income","bold":true},{"text":" (the split varies with product, use and area)."}]},{"text":[{"text":"Occupation:","bold":true},{"text":" like income, it shapes purchases; a need for an entrepreneur may be a luxury for a civil servant."}]},{"text":[{"text":"Generational segmentation:","bold":true},{"text":" grouping by period of birth (Generation Z, millennials, Generation X, baby boomers)."}]},{"text":[{"text":"Life stage segmentation:","bold":true},{"text":" grouping by where people are in life now: finished school or not, earning or not, married or not, children (and their ages), home owner or not."}]},{"text":[{"text":"Generational and life stage segmentation are a "},{"text":"subset of demographic","bold":true},{"text":" segmentation."}]}]},{"type":"paragraph","text":[{"text":"Geographic segmentation:","bold":true},{"text":" groups people by the region where they live or work (country, state, city, neighbourhood). It is the base most sensitive to "},{"text":"regional preferences","bold":true},{"text":": use it when needs, tastes or climates differ by region. Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Location:","bold":true},{"text":" solely where customers live or work, ignoring language or culture."}]},{"text":[{"text":"Time zone.","bold":true}]},{"text":[{"text":"Climate and season.","bold":true}]},{"text":[{"text":"Cultural preferences.","bold":true}]},{"text":[{"text":"Language","bold":true},{"text":" (including slang and colloquialisms)."}]},{"text":[{"text":"Urbanicity:","bold":true},{"text":" how urban an area is (urban, suburban, rural)."}]}]},{"type":"paragraph","text":[{"text":"Business (industrial) markets","bold":true},{"text":" are segmented by variables such as "},{"text":"industry type, company size and location","bold":true},{"text":", plus operating variables (technology, user status, customer capabilities), purchasing approaches, situational factors (urgency, order size) and personal characteristics of buyers."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Millennials with disposable income","bold":true},{"text":" = demographic (age generation plus income). "},{"text":"Coastal residents","bold":true},{"text":" = geographic."}]},{"text":[{"text":"Income example:","bold":true},{"text":" a car maker treats a Toyota Corolla as a need for mid-income buyers and a Lexus as a luxury for high-income buyers."}]},{"text":[{"text":"Occupation example:","bold":true},{"text":" a heavy-duty phone power bank may be a necessity for a self-employed trader in Onitsha who is out all day, but a luxury for a salaried civil servant who sits near a socket."}]},{"text":[{"text":"Generational example:","bold":true},{"text":" a social media app such as Snapchat markets itself to Generation Z rather than Generation X."}]},{"text":[{"text":"Life stage example:","bold":true},{"text":" two 30-year-old men grew up in the same Ibadan neighbourhood. One is married with a child; the other is single and lives with his parents. Same generation, different needs: a marketer who separates them is using life stage segmentation. Combining generation and life stage gives deeper insight."}]},{"text":[{"text":"Climate and season:","bold":true},{"text":" a clothing retailer pushes raincoats and umbrellas in Port Harcourt in the rainy season and warm wear in Jos during harmattan. Bottled water sells strongly where water is scarce and weakly where it is plentiful."}]},{"text":[{"text":"Cultural preferences:","bold":true},{"text":" drinking beer in the open is almost normal in Lagos but may be frowned upon in parts of Northern Nigeria, so a beer brand markets differently in each. Nigeria's Yoruba, Hausa and Igbo sub-cultures can be treated as distinct segments."}]},{"text":[{"text":"Urbanicity:","bold":true},{"text":" a dealer promotes small saloon cars in cities and pick-up trucks that handle rough roads and haul farm inputs in rural areas."}]},{"text":[{"text":"Place (geographic):","bold":true},{"text":" a snack brand sells a big ₦4,500 party pack in cities where teenagers buy snacks for parties and small ₦200 packs in rural areas where people spend little on snacks."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"spending habits\" and \"customer journey stage\" are behavioural, not geographic. \"Personality\" is psychographic, not demographic."}]}]}]},{"number":"7.3","title":"Psychographic and behavioural segmentation","mustKnow":[{"type":"paragraph","text":[{"text":"Psychographic segmentation:","bold":true},{"text":" groups people by psychological traits: "},{"text":"personality, lifestyle and attitude","bold":true},{"text":" (also values, interests, opinions). It uncovers "},{"text":"intangible","bold":true},{"text":" factors and explains consumer motivations, so it is very useful for understanding "},{"text":"why","bold":true},{"text":" consumers choose certain brands. Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inner beliefs.","bold":true}]},{"text":[{"text":"Likes and dislikes.","bold":true}]},{"text":[{"text":"Lifestyle.","bold":true}]},{"text":[{"text":"Attitudes and values.","bold":true}]},{"text":[{"text":"Priorities and motivations.","bold":true}]},{"text":[{"text":"Personality.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" the combination of characteristics forming a person's distinctive character (habits, traits, attitude, temperament): introverted, extroverted, sociable, optimistic, creative, emotional."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" how a person lives; measured by "},{"text":"activities, interests and opinions (AIO)","bold":true},{"text":". Lifestyle also covers marital status, hobbies, religion and values (but asked on their own, religion and marital status are demographic variables)."}]},{"text":[{"text":"Social status:","bold":true},{"text":" how highly society views a person; people buy to enhance it."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" people's perceptions of the world, usually shaped by upbringing and cultural and religious background."}]}]},{"type":"paragraph","text":[{"text":"Behavioural segmentation:","bold":true},{"text":" groups people by how they behave towards the product or business: "},{"text":"usage, loyalty, purchase occasions","bold":true},{"text":", preference, choices, decision making, product knowledge. It is reported as the "},{"text":"most effective","bold":true},{"text":" method: "},{"text":"91%","bold":true},{"text":" of marketers said so (2019 Marketing Week survey). Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Spending habits.","bold":true}]},{"text":[{"text":"Purchasing habits.","bold":true}]},{"text":[{"text":"Brand interactions.","bold":true}]},{"text":[{"text":"Customer journey stage.","bold":true}]},{"text":[{"text":"User status.","bold":true}]},{"text":[{"text":"Benefits sought.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Purchasing habits, 4 groups:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complex buyers:","bold":true},{"text":" do not yet know which product or brand to buy; still researching."}]},{"text":[{"text":"Variety-seeking:","bold":true},{"text":" happy with their current brand but open to trying other brands and varieties."}]},{"text":[{"text":"Dissonance-reducing:","bold":true},{"text":" happy with their current brand but think other brands could offer better."}]},{"text":[{"text":"Habitual:","bold":true},{"text":" loyal to their brand and unlikely to switch."}]}]}]},{"text":[{"text":"User status:","bold":true},{"text":" those who know or do not know the product, "},{"text":"ex-users, potential users, current users, first-time users","bold":true},{"text":"."}]},{"text":[{"text":"Usage rate:","bold":true},{"text":" "},{"text":"heavy, medium, light","bold":true},{"text":" users."}]},{"text":[{"text":"Loyalty status:","bold":true},{"text":" "},{"text":"brand loyal, brand-neutral, competitor loyal","bold":true},{"text":"."}]},{"text":[{"text":"Benefit segmentation:","bold":true},{"text":" segments formed by "},{"text":"what consumers want from the product","bold":true},{"text":" (the benefit sought)."}]},{"text":[{"text":"Other behavioural variables: occasions (when they buy or use), buyer readiness, attitude towards the product."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" an events company tells introverts the concert lets them choose quiet activities, and tells extroverts it is full of socialising. Same event, two personality segments."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" an online sneaker store in Lagos runs one campaign for joggers and gym users and another for buyers who want sneakers as a fashion statement."}]},{"text":[{"text":"Social status:","bold":true},{"text":" a five-star hotel in Abuja sells luxury and quality service; a budget hotel in the same city sells affordability."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" some gym users train to avoid health problems; others train for a sense of accomplishment."}]},{"text":[{"text":"Lifestyle example:","bold":true},{"text":" a person with a lavish lifestyle sees an air conditioner in every room as a need; a conservative person in the same city sees it as a luxury."}]},{"text":[{"text":"Purchasing habits:","bold":true},{"text":" Ada is buying her first laptop, does not know which brand, and is reading reviews and asking friends: a "},{"text":"complex buyer","bold":true},{"text":". \"Impulse buyers\" is "},{"text":"not","bold":true},{"text":" one of the four groups."}]},{"text":[{"text":"User status:","bold":true},{"text":" MTN or Airtel can send ex-users a \"come back\" bonus, first-time users a welcome bundle and current users a loyalty reward."}]},{"text":[{"text":"Usage rate:","bold":true},{"text":" an athlete is a heavy user of an energy drink; a non-sporty person who buys it for the taste is a light or medium user."}]},{"text":[{"text":"Behavioural targets:","bold":true},{"text":" frequent flyers (usage), brand-loyal customers for retention campaigns (loyalty). Benefit segmentation for toothpaste: one group wants white teeth, another wants cavity protection, another wants sensitivity relief."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"values and lifestyles\" or \"attitudes, interests and opinions\" means psychographic. \"How heavily they use the product\", \"purchase frequency\" and \"loyalty\" mean behavioural. Behavioural looks at what people "},{"text":"do","bold":true},{"text":"; psychographic looks at who they "},{"text":"are inside","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Requirements, benefits and disadvantages, and segment sums","mustKnow":[{"type":"paragraph","text":[{"text":"5 requirements for effective segmentation","bold":true},{"text":" (segments must be):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Measurable:","bold":true},{"text":" the size, purchasing power and profiles of the segment can be measured."}]},{"text":[{"text":"Accessible:","bold":true},{"text":" the segment can be effectively reached and served."}]},{"text":[{"text":"Substantial:","bold":true},{"text":" the segment is large and/or profitable enough to serve."}]},{"text":[{"text":"Differentiable:","bold":true},{"text":" segments are conceptually distinguishable and respond differently to different marketing mix elements and programmes."}]},{"text":[{"text":"Actionable:","bold":true},{"text":" effective programmes can be formulated for attracting and serving the segment."}]}]},{"type":"paragraph","text":[{"text":"\"Ability\" and \"inexpensive\" are "},{"text":"not","bold":true},{"text":" requirements."}]},{"type":"paragraph","text":[{"text":"Benefits of market segmentation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Better matching of customer needs.","bold":true}]},{"text":[{"text":"Identification of gaps in the market.","bold":true}]},{"text":[{"text":"Increased ROI","bold":true},{"text":" (less wasted spending, more repeat sales, referrals and word of mouth)."}]},{"text":[{"text":"Customer retention.","bold":true}]},{"text":[{"text":"Increased market share.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Also: better allocation of resources (directing them to high-potential segments), greater customer satisfaction, better spotting of opportunities, lower costs, higher conversions, more specific planning, and reaching niche users through smaller segments."}]},{"type":"paragraph","text":[{"text":"Disadvantages (limitations):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Extensive research and development","bold":true},{"text":" is needed, which some businesses cannot afford."}]},{"text":[{"text":"Expensive process","bold":true},{"text":" in both time and money."}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Segment size = Total market (buyers or units) x Segment percentage"}]},{"text":[{"text":"Market share (%) = Firm's sales / Total market sales x 100"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Failing requirements:","bold":true},{"text":" left-handed golfers in Owerri, too few to be profitable, fail "},{"text":"substantial","bold":true},{"text":". A large, profitable group that no media or channel the firm uses can reach fails "},{"text":"accessible","bold":true},{"text":". A small airline with seven attractive segments but too few staff and too little money to run seven programmes fails "},{"text":"actionable","bold":true},{"text":". Two \"segments\" that react the same way to every offer fail "},{"text":"differentiable","bold":true},{"text":"."}]},{"text":[{"text":"Gap example:","bold":true},{"text":" after segmenting the Lagos food market, a start-up finds nobody serves healthy ready-to-eat lunches for night-shift workers and launches for them: identification of gaps in the market."}]},{"text":[{"text":"Not benefits:","bold":true},{"text":" \"using one identical marketing mix for everyone\" and \"removing the need for market research\". Segmentation needs "},{"text":"more","bold":true},{"text":" research, not less."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1: segment size","bold":true}]},{"type":"paragraph","text":[{"text":"A study finds 200,000 potential buyers of a new study app in a city; 35% are aged 16 to 24."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Segment size = 200,000 x 35% = 200,000 x 0.35 = "},{"text":"70,000 buyers","bold":true},{"text":"."}]},{"text":[{"text":"Trap answers: 7,000 (decimal slip), 130,000 (the other 65%)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2: market share","bold":true}]},{"type":"paragraph","text":[{"text":"A town buys 300,000 sachet-water units in a month; one brand sells 45,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market share = 45,000 / 300,000 x 100 = "},{"text":"15%","bold":true},{"text":". Competitors together hold 255,000 units (85%)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3: is the segment substantial?","bold":true}]},{"type":"paragraph","text":[{"text":"Of those 70,000 young buyers, 20% are expected to pay ₦2,000 a year."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buyers = 70,000 x 0.20 = 14,000. Revenue = 14,000 x ₦2,000 = "},{"text":"₦28,000,000","bold":true},{"text":" a year: substantial."}]},{"text":[{"text":"The golf segment: 120 buyers x ₦50,000 = "},{"text":"₦6,000,000","bold":true},{"text":", against ₦15,000,000 needed to serve them: not substantial."}]}]}]},{"number":"7.5","title":"Targeting strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Target market:","bold":true},{"text":" a set of buyers sharing common needs or characteristics that a company decides to serve."}]},{"text":[{"text":"Market targeting:","bold":true},{"text":" evaluating each segment's attractiveness and selecting one or more to enter. Evaluate segments on (1) "},{"text":"size and growth","bold":true},{"text":", (2) "},{"text":"structural attractiveness","bold":true},{"text":" (competitors, substitutes, buyer and supplier power), (3) "},{"text":"company objectives and resources","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"What the firm does"}],[{"text":"Example"}]],"rows":[[[{"text":"Undifferentiated (mass)"}],[{"text":"Ignores segment differences; one offer, one programme for the whole market"}],[{"text":"A salt producer selling one product nationwide"}]],[[{"text":"Differentiated (segmented)"}],[{"text":"Targets several segments with a separate offer and programme for each"}],[{"text":"A drinks firm with a low-sugar drink, an energy drink and a malt drink, each with its own ads"}]],[[{"text":"Concentrated (niche)"}],[{"text":"Goes after a large share of one (or a few) small segments; suits limited resources"}],[{"text":"A small Lagos firm making only handmade shoes for very large feet"}]],[[{"text":"Micromarketing"}],[{"text":"Tailors products and programmes to specific individuals and local customer groups"}],[{"text":"See below"}]]]},{"type":"paragraph","text":[{"text":"Micromarketing, 2 forms:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Local marketing:","bold":true},{"text":" tailoring to cities, neighbourhoods or specific stores."}]},{"text":[{"text":"Individual (one-to-one, customised) marketing:","bold":true},{"text":" tailoring to one customer's needs and preferences."}]}]},{"type":"paragraph","text":[{"text":"Factors in choosing a strategy:","bold":true},{"text":" company resources, product variability, product life-cycle stage, market variability, competitors' strategies."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The strategies run from broad to narrow: undifferentiated, then differentiated, then concentrated, then micromarketing."}]},{"text":[{"text":"Undifferentiated","bold":true},{"text":" keeps costs low but struggles where tastes differ. It suits homogeneous products such as salt or sugar."}]},{"text":[{"text":"Differentiated","bold":true},{"text":" usually raises total sales but also costs (separate products, research, advertising). Nestlé Nigeria (Milo, Golden Morn, Maggi) and Dangote's different pack sizes of sugar and salt serve different segments."}]},{"text":[{"text":"Concentrated","bold":true},{"text":" gives deep knowledge of the niche and a strong position, but it is risky if that one segment shrinks or a big rival enters."}]},{"text":[{"text":"Local marketing:","bold":true},{"text":" a supermarket chain stocking different goods in its Lekki and Ikorodu branches. "},{"text":"Individual marketing:","bold":true},{"text":" a tailor in Abeokuta who takes each customer's measurements and sews to that one order."}]}]}]},{"number":"7.6","title":"Positioning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positioning:","bold":true},{"text":" arranging for a product to occupy a "},{"text":"clear, distinctive and desirable place","bold":true},{"text":" relative to competing products in the minds of target consumers."}]},{"text":[{"text":"Product position:","bold":true},{"text":" the way consumers define the product on important attributes, compared with competitors."}]},{"text":[{"text":"Differentiation:","bold":true},{"text":" actually making the offer different (product, services, channels, people, image) so the firm can deliver the position it claims."}]},{"text":[{"text":"Value proposition:","bold":true},{"text":" the full mix of benefits on which a brand is positioned."}]},{"text":[{"text":"Perceptual (positioning) map:","bold":true},{"text":" a chart of how consumers see competing brands on key buying attributes such as price and quality."}]},{"text":[{"text":"Positioning statement:","bold":true},{"text":" To (target segment and need), our (brand) is (concept) that (point of difference)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positioning is the "},{"text":"last","bold":true},{"text":" step of STP; the marketing mix must then deliver it (product, price, place and promotion all support one position)."}]},{"text":[{"text":"Examples:","bold":true},{"text":" GTBank positions on modern, convenient banking; Dangote Cement on strength and reliability for builders; Jumia on wide choice and home delivery. Each place is fixed relative to rivals, in buyers' minds."}]},{"text":[{"text":"Trap:","bold":true},{"text":" positioning is about the "},{"text":"mind","bold":true},{"text":" of the target customer. Choosing which group to serve is targeting; splitting the market is segmentation; the 4Ps are the marketing mix."}]},{"text":[{"text":"Industry examples of STP:","bold":true},{"text":" a beauty brand ran an \"Age Defying\" range for mature adults and a \"Clearly Clean\" range for teens and young adults (age). Fast-food chains give toys with kids' meals but promise fast service and free Wi-Fi to working adults. Sports brands such as Nike and Adidas segment by the sport played."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentation divides a broad market into groups with shared characteristics, so each gets its own marketing mix; opposite = mass marketing; Wendell Smith, 1956."}]},{"text":[{"text":"Good segment: internally homogeneous, externally heterogeneous; members respond alike. Preference patterns: homogeneous, diffused, clustered."}]},{"text":[{"text":"STP order: segmentation, targeting, positioning."}]},{"text":[{"text":"Demographic (most common; age, sex, income, occupation, religion; generational and life stage are subsets). Geographic: location, time zone, climate and season, cultural preferences, language, urbanicity."}]},{"text":[{"text":"Psychographic: personality, lifestyle (AIO), attitudes, values, social status. Behavioural (91% say most effective): spending and purchasing habits, brand interactions, journey stage, user status, benefits sought, usage rate, loyalty."}]},{"text":[{"text":"Descriptive bases describe; causal bases explain why. Business markets: industry type, company size, location."}]},{"text":[{"text":"Requirements: measurable, accessible, substantial, differentiable, actionable."}]},{"text":[{"text":"Benefits: needs matched, gaps found, ROI, retention, market share. Disadvantages: extensive research, expensive."}]},{"text":[{"text":"Targeting: undifferentiated, differentiated, concentrated, micromarketing (local, individual). Positioning = a clear, distinctive, desirable place in consumers' minds."}]},{"text":[{"text":"Segment size = total x %; market share = firm's sales / market sales x 100."}]}]}],"theory":{"itemId":"be825d80-15e4-575d-ba66-de4e51851e7b","question":[{"type":"paragraph","text":[{"text":"A noodle maker finds 480,000 noodle buyers in Ibadan, of whom 25% are students. It sells to 18,000 students. (a) How large is the student segment? (b) What share of that segment does the firm hold? (c) Which segmentation base is \"students\" and which targeting strategy would the firm use if it served only this group?"}]}]},"practice":[{"topic":"Market Segmentation","named":false}]}},{"itemId":"2d97598e-669d-59f5-9124-deefe92ce89f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Marketing System","body":"The meaning of a marketing system and a market system; the components of the marketing system; the simplest marketing system and its two flows; the simple versus the complex (modern) system and the five markets of a modern exchange economy; the actors (suppliers, intermediaries and their types, competitors, customers) and the utilities intermediaries create; marketing channels, channel levels, the contact computation, channel flows and channel functions; vertical, horizontal and multichannel systems and channel conflict; the systems view.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The meaning of a marketing system and a market system; the components of the marketing system; the simplest marketing system and its two flows; the simple versus the complex (modern) system and the five markets of a modern exchange economy; the actors (suppliers, intermediaries and their types, competitors, customers) and the utilities intermediaries create; marketing channels, channel levels, the contact computation, channel flows and channel functions; vertical, horizontal and multichannel systems and channel conflict; the systems view."}],"lessons":[{"number":"8.1","title":"Meaning, components and the systems view","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing system:","bold":true},{"text":" an integrative set of "},{"text":"institutions, flows and activities","bold":true},{"text":" affecting the ability of an organisation to develop and maintain successful transactions with its market."}]},{"text":[{"text":"Exam-style definition:","bold":true},{"text":" a set of "},{"text":"interacting and interdependent","bold":true},{"text":" individuals and institutions (producers, suppliers, intermediaries and customers) linked together by "},{"text":"flows of goods, money and information","bold":true},{"text":". Put another way, it is the "},{"text":"network of firms, suppliers, intermediaries and customers","bold":true},{"text":" linked by these flows."}]},{"text":[{"text":"Market system:","bold":true},{"text":" the network of buyers, sellers and other actors that come together to trade in a given product or service."}]}]},{"type":"paragraph","text":[{"text":"3 groups of participants in a market system:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct market players:","bold":true},{"text":" producers, buyers and consumers who drive economic activity in the market."}]},{"text":[{"text":"Suppliers of supporting goods and services:","bold":true},{"text":" finance, equipment, business consulting."}]},{"text":[{"text":"Entities that influence the business environment:","bold":true},{"text":" regulatory agencies, infrastructure providers, business associations."}]}]},{"type":"paragraph","text":[{"text":"Components of the marketing system","bold":true},{"text":" (the \"integrative set of institutions, flows and activities\"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The marketing organisation:","bold":true},{"text":" an organisation that places customers and the satisfaction of their needs and wants at the centre of its corporate thinking."}]},{"text":[{"text":"The controllable elements of the marketing mix:","bold":true},{"text":" product, price, distribution, advertising and others."}]},{"text":[{"text":"The target market.","bold":true}]},{"text":[{"text":"The facilitating institutions:","bold":true},{"text":" wholesalers, retailers, agents and others for the "},{"text":"distribution","bold":true},{"text":" function; advertising agencies and media for "},{"text":"communication","bold":true},{"text":"; marketing research for "},{"text":"marketing information","bold":true},{"text":"."}]},{"text":[{"text":"The uncontrollable environmental variables:","bold":true},{"text":" economic conditions, demographics, social and cultural values, competition, legal forces, technology, trade barriers and sources of raw materials."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Viewed as actors, the firm's marketing system is: the "},{"text":"company","bold":true},{"text":", "},{"text":"suppliers","bold":true},{"text":", "},{"text":"marketing intermediaries","bold":true},{"text":", "},{"text":"competitors","bold":true},{"text":" and "},{"text":"customers","bold":true},{"text":" (the end-user market), all operating inside the wider "},{"text":"environment","bold":true},{"text":", and linked by flows of "},{"text":"goods, money and information","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Picture the system as rings.","bold":true},{"text":" At the centre sits the marketing organisation with its mix (product, price, distribution, sales promotion and personal selling, advertising). Around it is a ring of functions: "},{"text":"marketing information","bold":true},{"text":", "},{"text":"communication","bold":true},{"text":", "},{"text":"distribution","bold":true},{"text":", and social-cultural value. The outer ring is the environment: physical, legal environment and competition, the economy and the international environment."}]},{"text":[{"text":"The systems idea:","bold":true},{"text":" the parts are "},{"text":"interdependent","bold":true},{"text":", so a change in one part affects the others. If a supplier of wheat flour raises its price, the noodle maker's costs rise, the wholesaler's margin is squeezed, and the shop price paid by the student goes up. The system is not fixed; it changes over time. No participant operates in isolation, and the firm cannot ignore suppliers or intermediaries."}]},{"text":[{"text":"Glaser's view:","bold":true},{"text":" the marketing system covers a narrow, limited range of organisational activities; it is only a "},{"text":"sub-system","bold":true},{"text":" of a larger organisation and is joined to other organisational sub-systems (production, finance, personnel) and to the environment."}]},{"text":[{"text":"The effectiveness of a firm's marketing activities "},{"text":"increases substantially","bold":true},{"text":" through proper "},{"text":"co-ordination","bold":true},{"text":" of the different parts to form a system."}]},{"text":[{"text":"Marketing systems of developing countries (LDCs):","bold":true},{"text":" one view (Sorenson; Bhandari and Vora) is that they are "},{"text":"resilient, adaptive","bold":true},{"text":" to economic conditions and fairly "},{"text":"low-cost","bold":true},{"text":". The opposing view (Dholakia) is that they have been generally "},{"text":"incapable of major innovations","bold":true},{"text":" in products, customer services, marketing methods, communications media or research techniques, and have not produced market-expansion strategies at home or abroad. So the typical LDC marketing system merely performs a "},{"text":"system maintenance function","bold":true},{"text":": it can neither spur rapid economic development nor generate products that benefit the mass of the population."}]},{"text":[{"text":"Traps:","bold":true},{"text":" \"the uncontrollable forces outside the firm\" describes the "},{"text":"environment","bold":true},{"text":", not the marketing system. \"The controllable variables blended to satisfy the target market\" is the "},{"text":"marketing mix","bold":true},{"text":". \"Dividing a market into distinct groups\" is "},{"text":"segmentation","bold":true},{"text":". A firm's internal accounting depreciation method is "},{"text":"not","bold":true},{"text":" a component of its marketing system."}]},{"text":[{"text":"In the evolution of marketing, the "},{"text":"stage of marketing system","bold":true},{"text":" came after barter: people tired of travelling to different places to exchange goods, so they began to use a particular place for exchange."}]}]}]},{"number":"8.2","title":"Simple and complex (modern) marketing systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The simplest marketing system","bold":true},{"text":" has "},{"text":"two interacting elements:","bold":true},{"text":" the "},{"text":"marketing organisation","bold":true},{"text":" and its "},{"text":"target market","bold":true},{"text":". They are connected by "},{"text":"two sets of flows:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product and payment flow:","bold":true},{"text":" the company distributes a product or service to customers in exchange for some kind of payment."}]},{"text":[{"text":"Information flow:","bold":true},{"text":" the company communicates with its market (sales force, advertising); the market returns "},{"text":"informational feedback","bold":true},{"text":" to the firm."}]}]}]}]},{"type":"table","header":[[{"text":"Flow"}],[{"text":"Direction"}]],"rows":[[[{"text":"Goods/services"}],[{"text":"Seller to buyer (market)"}]],[[{"text":"Communication"}],[{"text":"Seller to buyer (market)"}]],[[{"text":"Money (payment)"}],[{"text":"Buyer to seller"}]],[[{"text":"Information (feedback)"}],[{"text":"Buyer to seller"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"So "},{"text":"from seller to buyer: goods/services and communication","bold":true},{"text":". "},{"text":"From buyer to seller: money and information.","bold":true},{"text":" Information therefore flows in "},{"text":"both directions","bold":true},{"text":"."}]},{"text":[{"text":"Complex (modern) marketing system:","bold":true},{"text":" links "},{"text":"many markets","bold":true},{"text":" through flows of resources, goods, money, taxes and services, rather than just one seller and its buyers."}]}]},{"type":"paragraph","text":[{"text":"5 markets in a modern exchange economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resource markets:","bold":true},{"text":" raw materials, labour, money."}]},{"text":[{"text":"Manufacturer markets:","bold":true},{"text":" producers buy resources and turn them into goods and services."}]},{"text":[{"text":"Intermediary markets:","bold":true},{"text":" buy from manufacturers and sell to consumers."}]},{"text":[{"text":"Consumer markets:","bold":true},{"text":" households sell their labour for money, then spend it on goods and services."}]},{"text":[{"text":"Government markets:","bold":true},{"text":" buy goods from resource, manufacturer and intermediary markets and pay them; "},{"text":"collect taxes","bold":true},{"text":" from these markets and from consumers; and "},{"text":"provide public services","bold":true},{"text":" in return."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple system example:","bold":true},{"text":" a pepper seller at a village market in Ogun State sells her own produce straight to shoppers. Goods go from her to them; they pay her cash and tell her which peppers they prefer (information feedback). One seller, her buyers, two sets of flows: a "},{"text":"simple marketing system","bold":true},{"text":"."}]},{"text":[{"text":"Complex system example:","bold":true},{"text":" a Dangote factory buys gypsum, labour and bank loans in resource markets; it sells cement to distributors (intermediary market), who sell to builders and households (consumer market). Government buys cement for roads, collects companies income tax and VAT, and provides public services such as roads and security. The workers' wages go back into consumer spending. Every market depends on the others."}]},{"text":[{"text":"Traps:","bold":true},{"text":" the government is "},{"text":"inside","bold":true},{"text":" the modern system (it buys, taxes and provides services); it is not outside it and it is not just a retailer. The complex system does "},{"text":"not","bold":true},{"text":" consist only of direct sales, and it still has information flows. \"Marketing mix market\" is "},{"text":"not","bold":true},{"text":" one of the five markets."}]},{"text":[{"text":"Do not mix up \"simple marketing system\" with the channel arrangements in Lesson 8.5 (vertical, horizontal, multichannel). A single seller dealing directly with her buyers is a simple system, not a vertical or horizontal one."}]}]}]},{"number":"8.3","title":"The actors in the marketing system","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Supply side","bold":true},{"text":" of the micro environment (and of the marketing system): "},{"text":"suppliers, marketing intermediaries and competitors","bold":true},{"text":". "},{"text":"Demand side:","bold":true},{"text":" "},{"text":"customers","bold":true},{"text":"."}]},{"text":[{"text":"Suppliers:","bold":true},{"text":" firms and individuals that provide the raw materials and other resources a company needs to produce its goods and services. The price of raw materials shapes the final price, so suppliers can affect profit; firms monitor them for shortages and price changes."}]},{"text":[{"text":"Marketing intermediaries:","bold":true},{"text":" independent businesses that help a company "},{"text":"link with its customers","bold":true},{"text":" by "},{"text":"promoting, selling and distributing","bold":true},{"text":" its products; they perform the activities needed to move products from manufacturers to ultimate consumers (wholesalers, retailers, agents, distributors). They are part of the firm's distribution channels."}]}]},{"type":"paragraph","text":[{"text":"4 types of marketing intermediaries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resellers:","bold":true},{"text":" buy the products and sell them to customers (wholesalers, retailers)."}]},{"text":[{"text":"Distribution centres:","bold":true},{"text":" help the firm "},{"text":"store","bold":true},{"text":" goods (a warehouse)."}]},{"text":[{"text":"Marketing agencies:","bold":true},{"text":" promote products by making customers aware of their benefits (an advertising agency)."}]},{"text":[{"text":"Financial intermediaries:","bold":true},{"text":" finance business transactions (banks, credit organisations, insurance organisations)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Competitors:","bold":true},{"text":" organisations offering similar products and trying to win market share with different strategies; competition pushes a firm to "},{"text":"differentiate","bold":true},{"text":" its product."}]},{"text":[{"text":"Customers:","bold":true},{"text":" buy the product; customer satisfaction is the firm's main goal. "},{"text":"5 customer markets:","bold":true},{"text":" consumer, industrial (business), reseller, government and non-profit, international."}]}]},{"type":"paragraph","text":[{"text":"5 utilities intermediaries create:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Place:","bold":true},{"text":" stocking products where customers are located."}]},{"text":[{"text":"Time:","bold":true},{"text":" opening long hours so customers buy when convenient."}]},{"text":[{"text":"Quantity:","bold":true},{"text":" offering amounts customers can afford to buy."}]},{"text":[{"text":"Assortment:","bold":true},{"text":" gathering many products in one place for one shopping trip."}]},{"text":[{"text":"Possession:","bold":true},{"text":" transferring the product to the customer through a successful transaction."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a warehouse operator near the Lagos-Ibadan expressway storing a drinks maker's stock is a "},{"text":"distribution centre","bold":true},{"text":". An advertising agency running a radio campaign for a new detergent is a "},{"text":"marketing agency","bold":true},{"text":". GTBank lending to a distributor is a "},{"text":"financial intermediary","bold":true},{"text":". A Shoprite branch buying and reselling is a "},{"text":"reseller","bold":true},{"text":"."}]},{"text":[{"text":"Two noodle brands (say Indomie and a rival) chasing the same students with different packs and flavours are each other's "},{"text":"competitors","bold":true},{"text":", not suppliers or resellers."}]},{"text":[{"text":"Intratype competition:","bold":true},{"text":" between firms in the same basic activity (Nigerian Bottling Company versus Seven Up Bottling Company). "},{"text":"Intertype competition:","bold":true},{"text":" between different types of organisations (finance houses competing with banks for savers)."}]},{"text":[{"text":"\"Right place, right time, in a form they can own\" points to "},{"text":"place, time and possession utility","bold":true},{"text":". "},{"text":"Form utility","bold":true},{"text":" is created by production, not by intermediaries."}]},{"text":[{"text":"Distribution channels change slowly but constantly, like the "},{"text":"hour hand of a watch","bold":true},{"text":": each movement is too small to see, yet the change over years can be massive."}]}]}]},{"number":"8.4","title":"Marketing channels, levels, flows and functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing (distribution) channel:","bold":true},{"text":" a set of "},{"text":"interdependent organisations","bold":true},{"text":" that help make a product or service available for use or consumption by the consumer or business user."}]}]},{"type":"paragraph","text":[{"text":"Channel levels","bold":true},{"text":" (count the "},{"text":"intermediaries","bold":true},{"text":" only):"}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Structure"}]],"rows":[[[{"text":"Zero-level (direct)"}],[{"text":"Producer to consumer"}]],[[{"text":"One-level"}],[{"text":"Producer to retailer to consumer"}]],[[{"text":"Two-level"}],[{"text":"Producer to wholesaler to retailer to consumer"}]],[[{"text":"Three-level"}],[{"text":"Producer to wholesaler to jobber (sub-wholesaler) to retailer to consumer"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Contact formula","bold":true},{"text":" (each intermediary cuts the number of transactions):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct contacts = number of producers × number of buyers"}]},{"text":[{"text":"Contacts through one intermediary = number of producers + number of buyers"}]},{"text":[{"text":"Contacts saved = (producers × buyers) − (producers + buyers)"}]}]}]}]},{"type":"paragraph","text":[{"text":"Channel flows:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical flow","bold":true},{"text":" of goods: forward, producer to consumer."}]},{"text":[{"text":"Title (ownership) flow:","bold":true},{"text":" forward."}]},{"text":[{"text":"Promotion flow:","bold":true},{"text":" forward."}]},{"text":[{"text":"Payment flow:","bold":true},{"text":" backward, consumer to producer."}]},{"text":[{"text":"Information flow:","bold":true},{"text":" both directions."}]}]},{"type":"paragraph","text":[{"text":"8 channel functions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Information:","bold":true},{"text":" gathering and spreading research and intelligence about the market."}]},{"text":[{"text":"Promotion:","bold":true},{"text":" developing and spreading persuasive communication about an offer."}]},{"text":[{"text":"Contact:","bold":true},{"text":" finding and communicating with prospective buyers."}]},{"text":[{"text":"Matching:","bold":true},{"text":" shaping and fitting the offer to the buyer's needs (manufacturing, grading, assembling, packaging)."}]},{"text":[{"text":"Negotiation:","bold":true},{"text":" agreeing on price and other terms so ownership can be transferred."}]},{"text":[{"text":"Physical distribution:","bold":true},{"text":" transporting and storing goods."}]},{"text":[{"text":"Financing:","bold":true},{"text":" acquiring and using funds to cover the costs of channel work."}]},{"text":[{"text":"Risk taking:","bold":true},{"text":" bearing the risks of carrying out channel work."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Levels:","bold":true},{"text":" a Kano farmer selling yoghurt at his farm gate is "},{"text":"zero-level (direct)","bold":true},{"text":". A soap maker selling to distributors, who sell to neighbourhood shops, who sell to households, has "},{"text":"two","bold":true},{"text":" intermediaries, so it is a "},{"text":"two-level","bold":true},{"text":" channel. Count only the middlemen, never the producer or the consumer."}]},{"text":[{"text":"Worked example 1:","bold":true},{"text":" 4 textile producers, 5 clothing shops."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 4 × 5 = "},{"text":"20 contacts","bold":true},{"text":"."}]},{"text":[{"text":"Through one wholesaler: 4 + 5 = "},{"text":"9 contacts","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example 2:","bold":true},{"text":" 6 pharmaceutical producers, 8 pharmacies."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 6 × 8 = 48. Through one distributor: 6 + 8 = 14."}]},{"text":[{"text":"Fall = 48 − 14 = "},{"text":"34 contacts","bold":true},{"text":". (Options of 48 or 14 are the traps: the question asks for the fall.)"}]}]}]},{"text":[{"text":"Worked example 3 (cost):","bold":true},{"text":" 5 producers, 12 retailers, each contact costs ₦2,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 5 × 12 = 60 contacts; 60 × ₦2,000 = ₦120,000."}]},{"text":[{"text":"Through one wholesaler: 5 + 12 = 17 contacts; 17 × ₦2,000 = ₦34,000."}]},{"text":[{"text":"Saving = ₦120,000 − ₦34,000 = "},{"text":"₦86,000","bold":true},{"text":" (43 fewer contacts)."}]}]}]},{"text":[{"text":"Function applications:","bold":true},{"text":" a Lagos wholesaler that buys 5,000 cartons of tomato paste in advance and accepts losses if prices fall or stock expires is performing "},{"text":"risk taking","bold":true},{"text":". Grading and packaging rice to suit buyers is "},{"text":"matching","bold":true},{"text":". A distributor giving a retailer 30 days' credit is "},{"text":"financing","bold":true},{"text":". Setting the national interest rate is "},{"text":"not","bold":true},{"text":" a channel function; that is the Central Bank of Nigeria's job."}]},{"text":[{"text":"Information, promotion, contact, matching and negotiation help "},{"text":"complete transactions","bold":true},{"text":"; physical distribution, financing and risk taking help "},{"text":"fulfil","bold":true},{"text":" them."}]}]}]},{"number":"8.5","title":"Organising the channel: conventional, vertical, horizontal and multichannel systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conventional distribution channel:","bold":true},{"text":" an independent producer, wholesaler(s) and retailer(s), each a separate business seeking to maximise its own profit, even at the expense of the whole system; no member has much control over the others."}]},{"text":[{"text":"Vertical marketing system (VMS):","bold":true},{"text":" producers, wholesalers and retailers acting as a "},{"text":"unified system","bold":true},{"text":". One member "},{"text":"owns","bold":true},{"text":" the others, has "},{"text":"contracts","bold":true},{"text":" with them, or has so much "},{"text":"power","bold":true},{"text":" that they must cooperate."}]}]},{"type":"paragraph","text":[{"text":"3 types of VMS:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Corporate VMS:","bold":true},{"text":" successive stages of production and distribution under "},{"text":"single ownership","bold":true},{"text":"."}]},{"text":[{"text":"Contractual VMS:","bold":true},{"text":" independent firms at different levels joined by "},{"text":"contracts","bold":true},{"text":"; the "},{"text":"franchise","bold":true},{"text":" organisation is the most common form (also wholesaler-sponsored voluntary chains and retailer cooperatives)."}]},{"text":[{"text":"Administered VMS:","bold":true},{"text":" leadership comes from the "},{"text":"size and power","bold":true},{"text":" of one dominant member, not from ownership or contracts."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Horizontal marketing system:","bold":true},{"text":" two or more companies "},{"text":"at the same channel level","bold":true},{"text":" join together to follow a new marketing opportunity."}]},{"text":[{"text":"Multichannel (hybrid) distribution system:","bold":true},{"text":" one firm sets up "},{"text":"two or more channels","bold":true},{"text":" to reach one or more customer segments."}]},{"text":[{"text":"Channel conflict:","bold":true},{"text":" disagreement among channel members over goals, roles and rewards."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vertical conflict:","bold":true},{"text":" between "},{"text":"different levels","bold":true},{"text":" of the same channel (manufacturer versus its own retailers)."}]},{"text":[{"text":"Horizontal conflict:","bold":true},{"text":" between firms "},{"text":"at the same level","bold":true},{"text":" (one dealer versus another dealer of the same brand)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A food company that owns its own flour mills, delivery trucks and retail outlets is a "},{"text":"corporate VMS","bold":true},{"text":". A manufacturer tied to its dealers by franchise agreements, without owning them, is a "},{"text":"contractual VMS","bold":true},{"text":". A giant brand whose size lets it dictate shelf space and promotions to independent retailers is running an "},{"text":"administered VMS","bold":true},{"text":"."}]},{"text":[{"text":"A bank placing kiosks or ATMs inside a supermarket chain's stores is a "},{"text":"horizontal marketing system","bold":true},{"text":": the two firms sit at the same level and combine resources; neither owns the other."}]},{"text":[{"text":"A phone-accessories brand selling through its own website, Computer Village traders and supermarkets at once is a "},{"text":"multichannel (hybrid)","bold":true},{"text":" system. Many Nigerian brands add Jumia as an online channel alongside shops."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a fight between a manufacturer and its own retailers over prices and margins is "},{"text":"vertical","bold":true},{"text":" conflict (different levels), even though \"horizontal\" sounds right to some students. Two retailers undercutting each other is horizontal conflict."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"ownership\" points to corporate, \"contract or franchise\" to contractual, \"power\" to administered."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing system = interacting, interdependent producers, suppliers, intermediaries and customers linked by flows of goods, money and information."}]},{"text":[{"text":"Components: marketing organisation, controllable mix, target market, facilitating institutions, uncontrollable environment."}]},{"text":[{"text":"Simplest system = marketing organisation + target market; goods and communication go to the market, money and information come back."}]},{"text":[{"text":"Modern exchange economy: resource, manufacturer, intermediary, consumer and government markets; government buys, taxes and provides services."}]},{"text":[{"text":"Supply side = suppliers, intermediaries, competitors; demand side = customers. 4 intermediaries: resellers, distribution centres, marketing agencies, financial intermediaries."}]},{"text":[{"text":"Intermediaries create place, time, quantity, assortment and possession utility."}]},{"text":[{"text":"Channel levels count middlemen: zero, one, two, three. Contacts: direct = P × B; via one intermediary = P + B."}]},{"text":[{"text":"Goods and title flow forward, payment backward, information both ways. 8 functions: information, promotion, contact, matching, negotiation, physical distribution, financing, risk taking."}]},{"text":[{"text":"VMS: corporate (ownership), contractual (franchise), administered (power). Horizontal = same level. Multichannel = several channels. Vertical conflict = different levels."}]}]}],"theory":{"itemId":"b054ce88-2258-5fe6-ad23-e532ea5087ed","question":[{"type":"paragraph","text":[{"text":"Three paint manufacturers sell to ten hardware shops. Each sales contact costs ₦1,500. How much does the industry save if all trade passes through one wholesaler?"}]}]},"practice":[{"topic":"Marketing System","named":false}]}},{"itemId":"27c24510-6889-52b2-af78-b34d9dd569d9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"note","questionId":null,"sourceKey":"guide-topic:9","parentItemId":null,"revision":1,"payload":{"title":"Market Measurement and Forecasting","body":"What market measurement and forecasting are and why firms do them; the levels of a market; market demand, market minimum, market potential, company demand, sales forecast, quota and budget; market share, relative share and penetration; estimating current demand (n x q x p, market build-up, chain ratio, multiple-factor index); the forecasting methods; time series with moving averages and trend lines, all with computations.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What market measurement and forecasting are and why firms do them; the levels of a market; market demand, market minimum, market potential, company demand, sales forecast, quota and budget; market share, relative share and penetration; estimating current demand (n x q x p, market build-up, chain ratio, multiple-factor index); the forecasting methods; time series with moving averages and trend lines, all with computations."}],"lessons":[{"number":"9.1","title":"Meaning, importance and managing measurement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market measurement:","bold":true},{"text":" helps management understand the market and sales potential for a "},{"text":"specific area, time period, product and segment","bold":true},{"text":". "},{"text":"\"Ordinal analytics\"","bold":true},{"text":" studies market share, size and growth by customer segment and product."}]},{"text":[{"text":"Forecasting:","bold":true},{"text":" giving managers reliable, early predictive information on emerging trends and \"what if\" scenarios so they can prepare and react. It uses business requirements, industry challenges, macroeconomic factors and statistical/econometric techniques, and is "},{"text":"re-run as new data arrive","bold":true},{"text":"."}]},{"text":[{"text":"Importance:","bold":true},{"text":" the main aim is to "},{"text":"support marketing decisions","bold":true},{"text":". Decisions are only as good as their information, so measurement makes decisions more "},{"text":"objective and scientific","bold":true},{"text":", reducing risk and guesswork. For minor, low-risk decisions it may not be worth it: weigh the decision's importance and risk against the "},{"text":"cost and time","bold":true},{"text":" of gathering information."}]},{"text":[{"text":"Managing measurement and forecasting","bold":true},{"text":" = planning, implementing and controlling these activities systematically. Steps:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Describe the problem and information needs","bold":true},{"text":" (gathering information is costly, so a clear problem definition decides what data is relevant)."}]},{"text":[{"text":"Gather relevant information","bold":true},{"text":" (dual purpose: supplies data for the problem and guides the choice of method)."}]},{"text":[{"text":"Select the methods","bold":true},{"text":" of measurement and forecasting (start by checking there is enough data of the right quality, then match information needs to what each method can do)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"5 factors in choosing a method:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Nature and availability of data","bold":true},{"text":" (enough suitable data? what pattern: "},{"text":"trends, seasonal fluctuations, conjuncture patterns","bold":true},{"text":"?)"}]},{"text":[{"text":"Accuracy required","bold":true}]},{"text":[{"text":"Costs","bold":true}]},{"text":[{"text":"Time","bold":true}]},{"text":[{"text":"Application","bold":true},{"text":" (results must be usable and understandable by decision makers)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Think of Dangote Cement deciding whether to build a new plant in the north. A wrong demand estimate costs billions, so careful measurement pays. Choosing between two jingle colours does not justify an expensive study."}]},{"text":[{"text":"More reliable methods usually cost more time and money; a perfect answer that arrives after the decision is useless."}]}]}]},{"number":"9.2","title":"Levels of the market and key demand concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market:","bold":true},{"text":" the set of all actual and potential buyers of a product."}]}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Potential market"}],[{"text":"consumers who profess a sufficient level of "},{"text":"interest","bold":true},{"text":" in an offer"}]],[[{"text":"Available market"}],[{"text":"consumers with "},{"text":"interest, income and access","bold":true},{"text":" to the offer"}]],[[{"text":"Qualified available market"}],[{"text":"available market who also "},{"text":"qualify","bold":true},{"text":" (e.g. legal age)"}]],[[{"text":"Target (served) market"}],[{"text":"the part of the qualified available market the company "},{"text":"decides to pursue","bold":true}]],[[{"text":"Penetrated market"}],[{"text":"consumers who are "},{"text":"already buying","bold":true},{"text":" the product"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market demand:","bold":true},{"text":" the "},{"text":"total volume","bold":true},{"text":" of a product that would be "},{"text":"bought","bold":true},{"text":" by a defined "},{"text":"customer group","bold":true},{"text":", in a defined "},{"text":"geographical area","bold":true},{"text":", in a defined "},{"text":"time period","bold":true},{"text":", in a defined "},{"text":"marketing environment","bold":true},{"text":", under a defined "},{"text":"marketing programme","bold":true},{"text":" (8 elements: product, total volume, bought, customer group, area, time, environment, programme)."}]},{"text":[{"text":"Market demand is "},{"text":"not a fixed number","bold":true},{"text":" but a function of conditions and industry marketing spending."}]},{"text":[{"text":"Market minimum:","bold":true},{"text":" sales that would occur "},{"text":"without any marketing expenditure","bold":true},{"text":" to stimulate demand."}]},{"text":[{"text":"Market potential:","bold":true},{"text":" the "},{"text":"limit approached by market demand as industry marketing expenditure approaches infinity","bold":true},{"text":", for a given marketing environment. Also: the maximum possible demand for a "},{"text":"product type","bold":true},{"text":" in a whole market, for a given area, period and segment."}]},{"text":[{"text":"3 aspects in defining market potential:","bold":true},{"text":" (1) defined market environment, (2) marketing expenditure by the industry, (3) market demand."}]},{"text":[{"text":"Primary demand:","bold":true},{"text":" demand for the "},{"text":"product class","bold":true},{"text":" as a whole (e.g. bottled water in general). "},{"text":"Selective (brand) demand:","bold":true},{"text":" demand for "},{"text":"one brand","bold":true},{"text":" (e.g. Eva water)."}]},{"text":[{"text":"Company demand:","bold":true},{"text":" the company's "},{"text":"estimated share of market demand","bold":true},{"text":" at alternative levels of its marketing effort in a given period. Formula: Company demand = market share x total market demand."}]},{"text":[{"text":"Company sales forecast:","bold":true},{"text":" the "},{"text":"expected","bold":true},{"text":" level of company sales based on a "},{"text":"chosen marketing plan","bold":true},{"text":" and an "},{"text":"assumed marketing environment","bold":true},{"text":"."}]},{"text":[{"text":"Company sales potential (sales potential):","bold":true},{"text":" the "},{"text":"limit","bold":true},{"text":" approached by company demand as its marketing effort increases "},{"text":"relative to competitors","bold":true},{"text":"; the maximum demand for "},{"text":"one firm's brand","bold":true},{"text":", not the product type."}]},{"text":[{"text":"Sales quota:","bold":true},{"text":" a sales "},{"text":"goal","bold":true},{"text":" set for a product line, division or salesperson; usually set "},{"text":"slightly above","bold":true},{"text":" estimated sales to stretch effort."}]},{"text":[{"text":"Sales budget:","bold":true},{"text":" a "},{"text":"conservative","bold":true},{"text":" estimate of expected sales, used for purchasing, production and cash-flow decisions; usually set "},{"text":"slightly below","bold":true},{"text":" the forecast."}]},{"text":[{"text":"Potential market share:","bold":true},{"text":" the relation between market potential and sales potential; what part of the potential market the firm expects to win."}]},{"text":[{"text":"Effective demand:","bold":true},{"text":" "},{"text":"actual sales","bold":true},{"text":" of a product type in a given area, period and segment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Potential versus forecast (favourite trap):","bold":true},{"text":" sales potential is what the firm "},{"text":"could","bold":true},{"text":" reach if it pushed effort to the limit; the forecast is what it "},{"text":"expects","bold":true},{"text":" under the plan it has "},{"text":"actually chosen","bold":true},{"text":". They are not the same; potential is normally the higher figure."}]},{"text":[{"text":"Company sales potential equals market potential only if the company took "},{"text":"100%","bold":true},{"text":" of the market, which almost never happens."}]},{"text":[{"text":"Expansible market:","bold":true},{"text":" total size changes a lot with industry marketing spend (e.g. a new snack category). "},{"text":"Non-expansible:","bold":true},{"text":" spend barely changes it (e.g. salt); the gap between market minimum and market potential is small."}]},{"text":[{"text":"A \"Drink more water\" campaign from a water producers' association builds "},{"text":"primary","bold":true},{"text":" demand; \"Choose Nestlé Pure Life\" builds "},{"text":"selective","bold":true},{"text":" demand."}]},{"text":[{"text":"The forecast does "},{"text":"not","bold":true},{"text":" decide marketing spend; the plan comes first, and the forecast follows from it."}]},{"text":[{"text":"All these measures can refer to the "},{"text":"present or the future","bold":true},{"text":". Comparing them shows how well an offering does against rivals, the total market and market potential."}]}]}]},{"number":"9.3","title":"Estimating current demand and market share","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total market potential:","bold":true},{"text":" Q = n x q x p, where n = number of buyers, q = quantity bought by an average buyer per period, p = average price per unit."}]},{"text":[{"text":"Area market potential","bold":true},{"text":" (for a city, state or region), 2 main methods:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Market-buildup method:","bold":true},{"text":" identify "},{"text":"all potential buyers","bold":true},{"text":" in each market (mainly business buyers, e.g. every bakery in a state) and estimate their potential purchases, then "},{"text":"add up","bold":true},{"text":"."}]},{"text":[{"text":"Multiple-factor index method","bold":true},{"text":" (mainly consumer markets): weight several factors. The best known is the "},{"text":"buying power index (BPI)","bold":true},{"text":": BPI = 0.5(area % of national disposable income) + 0.3(area % of national retail sales) + 0.2(area % of national population). Area potential = BPI% x national potential."}]}]}]},{"text":[{"text":"Chain-ratio method:","bold":true},{"text":" start with a "},{"text":"base number","bold":true},{"text":" (e.g. population) and multiply by a "},{"text":"series of percentages","bold":true},{"text":" that narrow it to likely buyers (then by usage per buyer if needed)."}]},{"text":[{"text":"Market share","bold":true},{"text":" = (company sales / total market sales, including the company) x 100%."}]},{"text":[{"text":"Relative market share","bold":true},{"text":" = company's market share / largest competitor's share."}]},{"text":[{"text":"Market penetration index","bold":true},{"text":" = (current market demand / market potential) x 100%."}]},{"text":[{"text":"Sales forecast","bold":true},{"text":" = forecast market demand x expected market share."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (n x q x p).","bold":true},{"text":" 500,000 buyers each buy 6 tins a year at ₦800. Q = 500,000 x 6 x ₦800 = "},{"text":"₦2,400,000,000","bold":true},{"text":" a year."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (weekly data).","bold":true},{"text":" 20,000 households buy 2 tins of milk a week at ₦1,500. Weekly = 20,000 x 2 x ₦1,500 = ₦60,000,000. Annual (52 weeks) = "},{"text":"₦3,120,000,000","bold":true},{"text":". Trap: forgetting to multiply by 52 (or by 12 for monthly data)."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (market build-up).","bold":true},{"text":" A drinks distributor finds 250 restaurants in a state, each buying 30 crates a month at ₦5,000. Monthly = 250 x 30 x ₦5,000 = ₦37,500,000. Annual = x 12 = "},{"text":"₦450,000,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (chain ratio).","bold":true},{"text":" A city has 2,000,000 people; 55% are adults; 30% of adults drink yoghurt; each drinks 24 cups a year. 2,000,000 x 0.55 = 1,100,000 adults; x 0.30 = 330,000 drinkers; x 24 = "},{"text":"7,920,000 cups","bold":true},{"text":" a year."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (BPI).","bold":true},{"text":" A state has 6% of national income, 4% of retail sales, 5% of population. BPI = 0.5(6) + 0.3(4) + 0.2(5) = 3 + 1.2 + 1 = 5.2%. If national potential is ₦200 billion, state potential = 0.052 x ₦200bn = "},{"text":"₦10.4 billion","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 6 (shares).","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A paint firm sells ₦84m; the whole market (including it) sells ₦420m. Share = 84/420 x 100 = "},{"text":"20%","bold":true},{"text":". Trap: dividing by sales of rivals only (84/336 = 25%) is wrong."}]},{"text":[{"text":"Firm with 18% against a leader with 27%: relative share = 18/27 = "},{"text":"0.67","bold":true},{"text":" (2 d.p.). The leader's relative share = 27/18 = "},{"text":"1.5","bold":true},{"text":" (above 1 means you lead)."}]},{"text":[{"text":"Current demand 3m units, potential 12m: penetration = 3/12 x 100 = "},{"text":"25%","bold":true},{"text":" (a low index means room to grow)."}]},{"text":[{"text":"Market demand forecast ₦1.5 billion, expected share 8%: sales forecast = 0.08 x ₦1.5bn = "},{"text":"₦120 million","bold":true},{"text":"."}]},{"text":[{"text":"Actual industry sales come from trade associations, government statistics and research firms; comparing your growth with the industry's tells you whether you are gaining or losing share."}]}]}]},{"number":"9.4","title":"Forecasting from what buyers, salespeople and experts say, and what buyers do","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Forecasts rest on 3 information bases: what people "},{"text":"say","bold":true},{"text":" (buyers' intentions, sales-force opinion, expert opinion), what people "},{"text":"do","bold":true},{"text":" (market test), what people "},{"text":"have done","bold":true},{"text":" (time-series and statistical analysis of past sales)."}]},{"text":[{"text":"Usual sequence: macroeconomic forecast, then industry forecast, then company sales forecast."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Survey of buyers' intentions:","bold":true},{"text":" ask buyers what they plan to buy. Most useful when buyers are "},{"text":"few","bold":true},{"text":", "},{"text":"cheap to reach","bold":true},{"text":", have "},{"text":"clear intentions","bold":true},{"text":", will "},{"text":"carry them out","bold":true},{"text":" and are "},{"text":"willing to disclose","bold":true},{"text":" them (strongest for industrial buyers and durables)."}]},{"text":[{"text":"Composite of sales-force opinions (sales-force composite):","bold":true},{"text":" each salesperson estimates sales in his or her "},{"text":"territory","bold":true},{"text":"; estimates are "},{"text":"added up","bold":true},{"text":" and adjusted by management."}]},{"text":[{"text":"Expert opinion:","bold":true},{"text":" dealers, distributors, suppliers, consultants, trade associations. "},{"text":"Delphi method:","bold":true},{"text":" experts give estimates "},{"text":"anonymously","bold":true},{"text":", receive a "},{"text":"summary","bold":true},{"text":" of the group's answers, and "},{"text":"revise over several rounds","bold":true},{"text":" until a "},{"text":"consensus","bold":true},{"text":" emerges."}]},{"text":[{"text":"Market test method:","bold":true},{"text":" launch in a limited, representative area, record "},{"text":"actual purchases","bold":true},{"text":", project to the full market. Best for "},{"text":"new products","bold":true},{"text":", new channels or territories, or when buyers do not plan purchases."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sales-force composite strengths:","bold":true},{"text":" salespeople are closest to customers and spot trends; they trust quotas they helped set; estimates break down by product, territory, customer and salesperson. "},{"text":"Weaknesses:","bold":true},{"text":" bias (over-optimism or pessimism); salespeople may "},{"text":"deliberately underestimate so their quotas are set low","bold":true},{"text":"; they may not see wider economic developments."}]},{"text":[{"text":"Buyers' intentions are weak when buyers are millions of scattered consumers who rarely plan, refuse to share plans, or cannot picture a brand-new product."}]},{"text":[{"text":"An Ibadan-only launch of a new Lagos snack to project national sales is a "},{"text":"market test","bold":true},{"text":", not a survey."}]}]},{"type":"paragraph","text":[{"text":"Worked example 7 (buyers' intentions).","bold":true},{"text":" 100,000 households: 20% \"definitely buy\", 30% \"probably buy\". Past conversion: 70% of definites, 10% of probables. Definite buyers = 100,000 x 0.20 x 0.70 = 14,000. Probable buyers = 100,000 x 0.30 x 0.10 = 3,000. Expected buyers = "},{"text":"17,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 8 (sales-force composite).","bold":true},{"text":" Estimates 30,000 + 45,000 + 25,000 = 100,000 units. Management cuts 15% for over-optimism: 100,000 x 0.85 = "},{"text":"85,000 units","bold":true},{"text":". (If the team usually underestimates, management raises the total instead.)"}]},{"type":"paragraph","text":[{"text":"Worked example 9 (weighted expert opinion).","bold":true},{"text":" Forecasts ₦100m, ₦140m, ₦120m with weights 0.2, 0.5, 0.3 (weights sum to 1). Forecast = 0.2(100) + 0.5(140) + 0.3(120) = 20 + 70 + 36 = "},{"text":"₦126 million","bold":true},{"text":". A simple average would be ₦120m; adding the three (₦360m) is a trap."}]},{"type":"paragraph","text":[{"text":"Worked example 10 (market test).","bold":true},{"text":" A test city holds 3% of the target population and sells 12,000 packs. National estimate = 12,000 / 0.03 = "},{"text":"400,000 packs","bold":true},{"text":". Trap: multiplying by 3% instead of dividing."}]}]},{"number":"9.5","title":"Time-series analysis, moving averages and trend projection","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time-series analysis:","bold":true},{"text":" breaks past sales into "},{"text":"4 components","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Trend (T):","bold":true},{"text":" the long-run, underlying growth or decline (population, capital, technology)."}]},{"text":[{"text":"Cycle (C):","bold":true},{"text":" wave-like movement over "},{"text":"several years","bold":true},{"text":", from general economic activity (booms, recessions)."}]},{"text":[{"text":"Season (S):","bold":true},{"text":" a "},{"text":"recurring pattern within the year","bold":true},{"text":" (weather, holidays, festivals)."}]},{"text":[{"text":"Erratic events (E):","bold":true},{"text":" "},{"text":"unpredictable","bold":true},{"text":" one-off shocks (strikes, fuel scarcity, riots, floods)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Elasticity is not a component.","bold":true}]},{"text":[{"text":"Simple moving average (SMA)","bold":true},{"text":" = sum of sales in the last n periods / n. Purpose: "},{"text":"smooth out short-term random fluctuations","bold":true},{"text":" so the underlying level is clearer."}]},{"text":[{"text":"Weighted moving average (WMA)","bold":true},{"text":" = sum of (weight x sales) / sum of weights; gives "},{"text":"different weights","bold":true},{"text":", usually "},{"text":"more weight to recent","bold":true},{"text":" periods."}]},{"text":[{"text":"Trend projection:","bold":true},{"text":" assumes the "},{"text":"pattern of past sales will continue","bold":true},{"text":". Trend line: Y = a + bX."}]},{"text":[{"text":"Least squares (X coded to sum to zero, e.g. -2, -1, 0, 1, 2):","bold":true},{"text":" a = sum of Y / n; b = sum of XY / sum of X^2. b is the "},{"text":"average yearly increase","bold":true},{"text":"."}]},{"text":[{"text":"Straight-line growth:","bold":true},{"text":" yearly increase = (last value - first value) / number of intervals."}]},{"text":[{"text":"Compound growth:","bold":true},{"text":" forecast = current sales x (1 + g)^t."}]},{"text":[{"text":"Statistical demand analysis:","bold":true},{"text":" statistical procedures (e.g. multiple regression) that find the real factors affecting sales (price, income, population, promotion) and their relative influence."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Umbrella sales rising every April to July in Lagos = "},{"text":"seasonal","bold":true},{"text":". A two-week ticket slump from a sudden fuel scarcity = "},{"text":"erratic","bold":true},{"text":". A recession that lowers car sales for three years = "},{"text":"cyclical","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 11 (SMA).","bold":true},{"text":" Monthly sales: 30, 34, 38, 36, 41 (thousand). 3-month SMA forecast = (38 + 36 + 41) / 3 = 115 / 3 = "},{"text":"38.33 thousand","bold":true},{"text":" (2 d.p.). Use only the "},{"text":"last","bold":true},{"text":" n periods."}]},{"type":"paragraph","text":[{"text":"Worked example 12 (WMA).","bold":true},{"text":" Last three months (oldest first): 200, 220, 260; weights 1, 2, 3 (3 on the most recent). Forecast = (1x200 + 2x220 + 3x260) / (1 + 2 + 3) = (200 + 440 + 780) / 6 = 1,420 / 6 = "},{"text":"236.67 units","bold":true},{"text":" (2 d.p.). Trap: dividing by 3 instead of 6."}]},{"type":"paragraph","text":[{"text":"Worked example 13 (given trend line).","bold":true},{"text":" Y = 120 + 8X, X = 1 for 2020. For 2027, X = 8 (2027 - 2020 + 1). Y = 120 + 8 x 8 = "},{"text":"184","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 14 (least squares).","bold":true},{"text":" Sales 2021 to 2025: 10, 13, 15, 18, 19 (₦m); X = -2, -1, 0, 1, 2."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sum of Y = 75; a = 75 / 5 = 15."}]},{"text":[{"text":"XY: -20, -13, 0, 18, 38; sum = 23. Sum of X^2 = 4 + 1 + 0 + 1 + 4 = 10. b = 23 / 10 = 2.3."}]},{"text":[{"text":"2026 is X = 3: Y = 15 + 2.3 x 3 = "},{"text":"₦21.9 million","bold":true},{"text":"."}]},{"text":[{"text":"(With an even number of years, code X as -3, -1, 1, 3, so each year is 2 units of X.)"}]}]},{"type":"paragraph","text":[{"text":"Worked example 15 (straight-line growth).","bold":true},{"text":" ₦60m in 2020, ₦90m in 2025. Intervals = 5 (not 6). Increase = 30 / 5 = ₦6m a year. 2026 = 90 + 6 = "},{"text":"₦96 million","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 16 (compound growth).","bold":true},{"text":" ₦80m now, 5% a year. In two years = 80 x 1.05^2 = 80 x 1.1025 = "},{"text":"₦88.2 million","bold":true},{"text":". Trap: simple growth (80 + 4 + 4 = ₦88m) is wrong for compound growth."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market levels: potential, available (interest, income, access), qualified available, target (served), penetrated."}]},{"text":[{"text":"Market demand = total volume bought by a defined group, area, time, environment and programme; market minimum = sales with no marketing spend; market potential = limit as industry spend approaches infinity."}]},{"text":[{"text":"Primary demand = product class; selective = one brand."}]},{"text":[{"text":"Company demand = share x market demand; sales forecast = expected sales under the chosen plan; sales potential = limit as company effort rises relative to rivals."}]},{"text":[{"text":"Quota is set above, budget below, the forecast."}]},{"text":[{"text":"Q = n x q x p; market build-up adds up all buyers; chain ratio multiplies a base by percentages; BPI = 0.5 income + 0.3 retail sales + 0.2 population."}]},{"text":[{"text":"Market share = own sales / total market; relative share = own share / largest rival's; penetration = current demand / potential."}]},{"text":[{"text":"Methods: buyers' intentions, sales-force composite, expert opinion (Delphi), market test, time series, statistical demand analysis."}]},{"text":[{"text":"Time series: trend, cycle, season, erratic; SMA smooths, WMA weights recent periods more; least squares a = sum Y / n, b = sum XY / sum X^2."}]}]}],"theory":{"itemId":"d53c397c-38d8-5169-9abf-0ee638ad1991","question":[{"type":"paragraph","text":[{"text":"In a city of 800,000 adults, 25% drink yoghurt and each drinker buys 40 cups a year at ₦500. (a) What is the annual market potential in naira? (b) If a firm expects a 15% share, what is its sales forecast?"}]}]},"practice":[{"topic":"Market Measurement and Forecasting","named":false}]}}]$expected_content$::jsonb,
  'principles-marketing: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('0d6682a1-b7b0-5109-b86a-2fabbfbea8b4')
  where kind = 'cbt_question'), 0,
  'principles-marketing: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"0816b891-538e-59cd-8913-8d70176c7283","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"aa3cc46f-3c45-525c-ba2e-d61cf2a228bb","sourceKey":"bank:LAG-BUA111:CBB-001","parentItemId":null,"revision":1,"payload":{"prompt":"Buying behaviour is best defined as","options":["The movement of goods from manufacturers to wholesalers and retailers","The decisions and actions of people involved in buying and using products","The process by which a firm sets prices for the products it sells","The total amount of money households spend in a given year"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Buying behaviour covers both the decisions people make and the actions they take when they buy and use products. Option C is pricing, a marketing mix decision, and option A is distribution. Option D is a measure of spending, not behaviour."}},{"itemId":"63591ebc-84f7-55ab-b32b-14ac1ac18af3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f6c8863f-d947-5d40-a5a7-634b6143dea4","sourceKey":"bank:LAG-BUA111:CBB-002","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of the consumer buying decision process in which a person becomes aware of a gap between a desired state and an actual state is","options":["Post-purchase evaluation","Evaluation of alternatives","Information search","Problem recognition"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Problem recognition, also called need awareness, happens when a buyer notices a gap between where he is and where he wants to be, for example feeling hungry and wanting food. Information search (C) and evaluation of alternatives (B) only start after the need is felt, and post-purchase evaluation (A) comes after buying."}},{"itemId":"1e28ba3b-bae7-5d6e-8bc5-d601076dc6df","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4a83b5b3-1503-5340-a575-e3729e110616","sourceKey":"bank:LAG-BUA111:CBB-003","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde had not thought about new sneakers until he saw a billboard advert for a new design and realised his old pair was worn out. This shows that marketers can","options":["Trigger problem recognition in consumers","Remove the need for an information search","Cause cognitive dissonance before purchase","Skip the purchase decision stage for consumers"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The advert made Tunde aware of a gap between the shoes he had and the shoes he wanted, which is problem recognition; marketers can trigger this stage. Option B is wrong because he may still search for information, and option C is wrong because cognitive dissonance is doubt felt after a purchase. Option D is wrong because no stage was skipped here."}},{"itemId":"1878f8ab-e184-55bf-b586-1484a0ece325","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c0be5750-8a3f-5d0a-86b5-95ba860f1f8b","sourceKey":"bank:LAG-BUA111:CBB-004","parentItemId":null,"revision":1,"payload":{"prompt":"After searching for information, a consumer ends up with a short list of brands she will seriously consider. This set of alternatives is called the","options":["Evoked set","Reference group","Market segment","Buying centre"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The evoked set is the group of alternatives a buyer is left with after the information search. Option B is a group of people whose values a person adopts, option D is the group that makes purchase decisions in an organisation, and option C is a group of similar customers a marketer targets."}},{"itemId":"7969bcc1-b263-523b-95c7-80cae52d5065","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4959355f-a6f7-593b-bbc6-5f749dc2afef","sourceKey":"bank:LAG-BUA111:CBB-005","parentItemId":null,"revision":1,"payload":{"prompt":"Before buying a new hair dryer, Amaka first recalls from memory how the one she bought last year performed. This is an example of","options":["Post-purchase evaluation","Internal information search","Evaluation of alternatives","External information search"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"An internal search uses information already stored in the buyer's memory, which is what Amaka is doing. Option D would involve outside sources such as friends, adverts or comparison shopping. Option C comes after the search, when options are ranked, and option A happens after a purchase."}},{"itemId":"9a33e07b-c33e-5a86-983a-763c094d43be","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8f5b2dae-673a-57b7-98c9-20c8eee23a6b","sourceKey":"bank:LAG-BUA111:CBB-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an external source of information in the consumer information search stage?","options":["The buyer's own memory of past purchases","Public sources such as consumer reports","Marketer-controlled sources such as adverts and salespeople","Word of mouth from friends and relatives"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Searching one's own memory is an internal search, so it is not external. Options D, C and B all come from outside the buyer: friends and relatives, the marketer, and public bodies are all external places to look for information."}},{"itemId":"69b09235-38cb-5a82-b90d-f7cadfeee954","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2c396dfd-7be2-5931-b341-7c4f727e0610","sourceKey":"bank:LAG-BUA111:CBB-007","parentItemId":null,"revision":1,"payload":{"prompt":"At which stage of the consumer buying decision process does a buyer set criteria, such as wanted and unwanted features, and rank or weight the options?","options":["Purchase","Evaluation of alternatives","Post-purchase evaluation","Problem recognition"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"In the evaluation of alternatives, the buyer sets criteria and ranks the options, or goes back to search for more. Option D is simply becoming aware of a need. Options A and C come later, when the product is bought and then judged."}},{"itemId":"c9a28101-4ca1-5aec-a2f1-ab3e570179f7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6e310cb4-5376-517f-b039-8c885b4bcccd","sourceKey":"bank:LAG-BUA111:CBB-008","parentItemId":null,"revision":1,"payload":{"prompt":"Funmi decided to buy a particular brand of phone, but when she got to the shop it was out of stock, so she bought a different brand. This shows that","options":["Every buying process must end with the brand first chosen","The information search stage was never carried out","Funmi was experiencing selective retention","The actual purchase can differ from the purchase decision"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"The purchase decision (choosing an alternative) and the actual purchase are separate stages, and things like availability or a time gap can make them differ. Option A is the opposite of what happened. Nothing suggests she skipped the search (B), and selective retention (C) is about remembering information that supports one's beliefs."}},{"itemId":"d4574002-d4c1-55ba-886f-89b5e3bbd8e2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8ba1c02c-cf4d-5263-99a4-4e335cf6334a","sourceKey":"bank:LAG-BUA111:CBB-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following gives the correct order of the six stages of the consumer buying decision process for a complex decision?","options":["Problem recognition, evaluation of alternatives, information search, purchase decision, purchase, post-purchase evaluation","Problem recognition, information search, evaluation of alternatives, purchase decision, purchase, post-purchase evaluation","Information search, problem recognition, evaluation of alternatives, purchase decision, purchase, post-purchase evaluation","Problem recognition, information search, evaluation of alternatives, purchase, purchase decision, post-purchase evaluation"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"A buyer first recognises a need, then searches for information, evaluates the options, decides, buys, and finally evaluates the purchase. Option A evaluates before searching, which is impossible without alternatives to evaluate. Option C searches before a need is recognised, and option D buys before deciding."}},{"itemId":"89a211c6-b8aa-5276-907f-9d0bd373468f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1e2785ec-f8a8-573e-aec3-cee657310a80","sourceKey":"bank:LAG-BUA111:CBB-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following would a firm use mainly to reduce cognitive dissonance among its customers?","options":["Removing channels customers use to contact the firm","Running adverts that trigger problem recognition","Offering warranties and after-sales communication","Increasing the number of brands in each buyer's evoked set"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Warranties, after-sales communication and easy ways to contact the marketer reassure buyers that they chose correctly. Option D relates to information search and option B to the first stage, not to post-purchase doubt. Option A would make dissonance worse, because buyers would have nobody to reassure them."}},{"itemId":"7f0b3035-2296-55b7-bdef-0dab7904b4f3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a565a1bf-3a51-54e8-9bca-93ddf7f9530e","sourceKey":"bank:LAG-BUA111:CBB-012","parentItemId":null,"revision":1,"payload":{"prompt":"In consumer buying behaviour, 'level of involvement' refers to","options":["The number of brands available in a product category","The importance and intensity of interest in a product in a particular situation","The amount of money a firm spends on advertising a product","The number of people involved in an organisation's buying centre"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Level of involvement is how important a product is to a buyer and how intense his interest in it is in a given situation; it explains why buyers research some brands and ignore others. Option D describes the buying centre in organisations. Options C and A are about the firm and the market, not the buyer's interest."}},{"itemId":"d603cac9-e0f8-5edf-98fc-b591872b809e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"46e9ca20-b37c-5063-b657-aca2e2d43d57","sourceKey":"bank:LAG-BUA111:CBB-013","parentItemId":null,"revision":1,"payload":{"prompt":"As the perceived risk of a purchase increases, the buyer's level of involvement generally","options":["Increases","Becomes irrelevant to the decision","Decreases","Stays exactly the same"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Higher risk leads to higher involvement, which is why expensive or publicly visible items get more thought. Option C reverses the relationship, and options D and B ignore the link between risk and involvement altogether."}},{"itemId":"82956c95-a391-5eda-baba-13fee0e2df95","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"672df10c-d5b3-5461-8619-34317acc4f8b","sourceKey":"bank:LAG-BUA111:CBB-014","parentItemId":null,"revision":1,"payload":{"prompt":"Chioma is reluctant to buy a cheap-looking dress for a friend's party because she fears her classmates will laugh at her. The type of perceived risk she is worried about is","options":["Political risk","Social risk","Economic risk","Legal risk"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Social risk is the fear of how other people will judge us because of what we buy, which is Chioma's worry. Option C would be the fear of losing money, and options A and D are not types of purchase risk felt by a consumer."}},{"itemId":"5761ac71-3f2b-5349-8481-ab049c4a0099","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"afcd19d3-1b76-5b06-8ff8-2898dd1abc84","sourceKey":"bank:LAG-BUA111:CBB-015","parentItemId":null,"revision":1,"payload":{"prompt":"Emeka hesitates before buying a N2,500,000 used car because he could lose a large amount of money if it turns out to be faulty. The type of perceived risk involved is mainly","options":["Social risk","Cultural risk","Economic risk","Legal risk"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Economic risk is the possibility of losing money on a purchase, which is Emeka's main concern with an expensive car. Option A would be fear of what others think, while options B and D are not the purchase risks consumers weigh here."}},{"itemId":"3de78b62-2ca2-56df-955b-67f6f2e590ff","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ebc6cdcc-baa4-5c20-a9d1-09a26b0fc40f","sourceKey":"bank:LAG-BUA111:CBB-016","parentItemId":null,"revision":1,"payload":{"prompt":"Purchases of low-involvement, frequently bought, low-cost items that need very little search and effort, such as soft drinks and snacks, are made through","options":["Extensive decision making","Limited decision making","Impulse buying","Routine response behaviour"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Routine response (programmed) behaviour is almost automatic and is used for cheap, frequently bought items. Option B needs moderate search for an unfamiliar brand, and option A needs a lot of search for expensive, unfamiliar items. Option C is buying with no conscious planning, not a regular repeat purchase."}},{"itemId":"3ad2c4be-73a6-5a39-98f4-0bf04e197a42","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2c967218-13f5-57ad-b89b-87cc70fe3291","sourceKey":"bank:LAG-BUA111:CBB-017","parentItemId":null,"revision":1,"payload":{"prompt":"Bola buys clothes often, but she sees a new brand of jeans she has never tried and spends some time asking friends about it before buying. Her buying behaviour is best described as","options":["Limited decision making","Impulse buying","Routine response behaviour","Extensive decision making"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Limited decision making applies when the buyer knows the product category but needs information about an unfamiliar brand, so search time is moderate. Option C involves almost no search, option D applies to expensive, unfamiliar and infrequent purchases, and option B involves no planning at all."}},{"itemId":"30d21fa8-ad0f-56b0-95d5-8fdc698bd8a8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"06847e1e-9f20-582a-aae0-40e6f1529a0c","sourceKey":"bank:LAG-BUA111:CBB-018","parentItemId":null,"revision":1,"payload":{"prompt":"A couple buying their first house, which is unfamiliar, very expensive and bought rarely, consult friends, relatives and estate agents for weeks. This is","options":["Limited decision making","Impulse buying","Routine response behaviour","Extensive decision making"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Extensive decision making is used for unfamiliar, expensive, infrequent purchases with high risk, and it involves much information search and all six stages of the process. Options C and B involve little or no thought, and option A involves only moderate search for an unfamiliar brand in a familiar category."}},{"itemId":"2f276386-d9d3-5b42-9790-d2f7ead3fcd3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3bf7523c-0f5a-5ab9-8148-3d3644fadacd","sourceKey":"bank:LAG-BUA111:CBB-019","parentItemId":null,"revision":1,"payload":{"prompt":"While waiting to pay for fuel, Ngozi sees chocolate bars at the counter and buys one, although she had no plan to buy anything except fuel. This is an example of","options":["Extensive decision making","Routine response behaviour","Limited decision making","Impulse buying"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Impulse buying is a purchase made with no conscious planning, which fits Ngozi's sudden chocolate purchase. Option B is a planned, almost automatic repeat purchase, and options C and A both involve some deliberate search before buying."}},{"itemId":"8afc885f-75fb-58a9-b6e3-4a2ae0bbfa2f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8aa8039e-f76d-59c0-9e16-b02faa5aec46","sourceKey":"bank:LAG-BUA111:CBB-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of extensive decision making?","options":["A lot of information search","Unfamiliar and expensive products","Frequent purchase of low-cost items","High perceived risk"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Frequent, low-cost purchases are the mark of routine response behaviour, not extensive decision making. Options D, A and B are all typical of extensive decision making, which is used for unfamiliar, expensive, risky products that need much search."}},{"itemId":"ac2393c3-ffa8-57e5-b3d5-146eef83797d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"13502a06-8a51-5e43-9a78-64bca8c9e497","sourceKey":"bank:LAG-BUA111:CBB-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a personal factor influencing consumer buying behaviour?","options":["Social class","Reference groups","Age","Perception"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Personal factors are unique to the individual, such as demographic characteristics like age, sex and race. Option D is a psychological factor, while options B and A are social factors."}},{"itemId":"f0b44df6-a36d-57eb-a663-01100e3938eb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"35ff6134-f84e-5e27-bade-fb34d6e21e21","sourceKey":"bank:LAG-BUA111:CBB-023","parentItemId":null,"revision":1,"payload":{"prompt":"An internal energising force that directs a person's activities towards satisfying a need or achieving a goal is called a","options":["Perception","Motive","Attitude","Reference group"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"A motive is the inner force that pushes a person towards meeting a need or goal, and buying is often driven by several motives at once. Option C is a person's knowledge and feelings towards something, option A is how information is selected and interpreted, and option D is an outside social influence."}},{"itemId":"20805665-638d-5822-80fb-a9549d427ae1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a782d70c-7f37-56cd-bbd5-dfd4ee2fbfb1","sourceKey":"bank:LAG-BUA111:CBB-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following arranges Maslow's hierarchy of needs correctly from the lowest level to the highest?","options":["Physiological, love and belonging, safety, esteem, self-actualisation","Safety, physiological, love and belonging, esteem, self-actualisation","Physiological, safety, esteem, love and belonging, self-actualisation","Physiological, safety, love and belonging, esteem, self-actualisation"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Maslow's hierarchy starts with basic physiological needs, then safety, love and belonging, esteem, and finally self-actualisation at the top. Option A swaps safety and love, option B puts safety below physiological needs, and option C swaps esteem and love and belonging."}},{"itemId":"1d77b51b-256a-5257-8371-eb3f7ea60642","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f570593e-8991-5379-99ea-8e9fd4849f45","sourceKey":"bank:LAG-BUA111:CBB-025","parentItemId":null,"revision":1,"payload":{"prompt":"A newly promoted bank manager buys an expensive designer watch mainly so that colleagues will admire him and recognise his status. According to Maslow's hierarchy, this purchase satisfies mainly his","options":["Esteem needs","Self-actualisation needs","Physiological needs","Safety needs"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Esteem needs involve status, recognition and the respect of others, which is what the watch is meant to bring. Option C covers basics like food and water, option D covers protection from harm, and option B is about reaching one's full potential, not about impressing others."}},{"itemId":"7358e9bb-7833-5fdd-84b0-4f62ee32f2c4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"66f412b4-a4d6-5a28-a385-0b5895843f3f","sourceKey":"bank:LAG-BUA111:CBB-026","parentItemId":null,"revision":1,"payload":{"prompt":"A nutritional drink was marketed to fitness and energy-conscious buyers, but research showed it was mostly bought by low-income people in inner-city shops who used it as a meal substitute. These buyers were satisfying needs at which level of Maslow's hierarchy?","options":["Self-actualisation","Love and belonging","Physiological","Esteem"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Using a drink to replace a meal satisfies hunger, a basic physiological need. The firm had aimed at the love and belonging or esteem level (B and D), which is why its marketing mix had to be redesigned. Option A is about personal fulfilment, not food. The case shows that buyers' real motives are often hidden and must be researched."}},{"itemId":"dd6bd7f4-96bb-5e2f-a2e5-f9f76913ad48","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8840a472-b38b-56e7-a56c-66f384519a46","sourceKey":"bank:LAG-BUA111:CBB-027","parentItemId":null,"revision":1,"payload":{"prompt":"The process of selecting, organising and interpreting information inputs received through the senses in order to produce meaning is called","options":["Perception","Attitude","Motivation","Learning"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Perception is how a person selects, organises and interprets what he sees, hears, tastes, smells and touches to make sense of it. Option D is a change in behaviour from experience, option B is knowledge plus feelings about an object, and option C is the inner drive towards a goal."}},{"itemId":"01380931-5b61-5ed5-aa5b-e01525ba7d7b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9a32b2fb-a950-51d1-927c-45f431078132","sourceKey":"bank:LAG-BUA111:CBB-028","parentItemId":null,"revision":1,"payload":{"prompt":"Of the hundreds of adverts Kemi sees in a day, she notices and pays attention mainly to one announcing a sharp price cut on a laptop she currently needs. This is an example of","options":["Selective distortion","Cognitive dissonance","Selective exposure","Selective retention"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Selective exposure is choosing which inputs reach our awareness, and it is more likely when an input meets a current need or changes sharply, like a big price cut. Option A is twisting information that conflicts with beliefs, option D is remembering only what supports beliefs, and option B is doubt after a purchase."}},{"itemId":"a217b7b1-ae6c-5ed4-99ec-68267f378653","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3767cbea-530f-5a80-986d-d792b7fe1b21","sourceKey":"bank:LAG-BUA111:CBB-029","parentItemId":null,"revision":1,"payload":{"prompt":"A telecom company runs an advert comparing its data plans with a rival's. Some viewers come away believing the advert was for the rival, because they already favour the rival brand. This illustrates","options":["Selective exposure","Selective retention","Affinity marketing","Selective distortion"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Selective distortion is changing or twisting information that conflicts with what one already believes, and it is a known danger of comparative adverts because viewers may credit the competitor. Option A is about which inputs get noticed at all, and option B is about what is remembered later. Option C is marketing through reference groups."}},{"itemId":"e0d3f171-0ad5-5069-8ef9-79e9fbe10e21","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7ebe4c8e-2b10-5da7-ac25-5710a5758904","sourceKey":"bank:LAG-BUA111:CBB-030","parentItemId":null,"revision":1,"payload":{"prompt":"Seyi remembers all the good things he has heard about his favourite football boot brand but quickly forgets a negative review he read about it last week. This is an example of","options":["Selective exposure","Limited decision making","Selective distortion","Selective retention"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Selective retention means remembering information that supports one's beliefs and forgetting what does not. Option A is about which inputs are noticed in the first place, and option C is twisting the meaning of information while receiving it. Option B is a type of buying behaviour."}},{"itemId":"1a05396f-57aa-51ae-bb3a-9052f438d971","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ff04b8c2-9e49-59cf-9a6e-a2074dc08013","sourceKey":"bank:LAG-BUA111:CBB-031","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the selective processes in consumer perception?","options":["Selective motivation","Selective distortion","Selective exposure","Selective retention"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The three selective processes of perception are selective exposure, selective distortion and selective retention, so options C, B and D are all genuine. 'Selective motivation' is not one of them; motivation is a separate psychological factor."}},{"itemId":"a354d13c-0c28-55a3-b439-a3f61ac15c59","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5c1a8713-000a-5f81-82b5-3ccd42e76c57","sourceKey":"bank:LAG-BUA111:CBB-032","parentItemId":null,"revision":1,"payload":{"prompt":"A relatively permanent change in behaviour that results from the consequences of past behaviour and experience is called","options":["Learning","Personality","Culture","Perception"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Learning is a lasting change in behaviour caused by information and experience; this is why firms give free samples to change buying behaviour. Option D is interpreting information inputs, option B is a person's unique set of traits, and option C is the shared values of a society."}},{"itemId":"6af821c9-a318-5cac-bcfc-245b75dbefc2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"262671be-04ae-5742-a5b2-261293382d72","sourceKey":"bank:LAG-BUA111:CBB-033","parentItemId":null,"revision":1,"payload":{"prompt":"Consumers with little knowledge or experience of a product category tend to","options":["Always choose the cheapest brand available","Use price as an indicator of quality","Go through no information processing at all","Ignore price completely when choosing"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Inexperienced buyers who lack product knowledge often treat a higher price as a sign of higher quality, for example choosing the most expensive pack of an unfamiliar drink. Option A is the opposite tendency, option D ignores the role price plays, and option C is wrong because buyers still have to process information."}},{"itemId":"52df3051-5ecb-5865-aa22-d8481cb91f76","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3f2f6121-abc8-56af-8cff-0b8820c6279e","sourceKey":"bank:LAG-BUA111:CBB-034","parentItemId":null,"revision":1,"payload":{"prompt":"A person's knowledge and positive or negative feelings about an object or activity is known as","options":["A personality","A motive","An attitude","A perception"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"An attitude combines knowledge with positive or negative feelings towards an object or activity, and it is learned through experience and interaction. Option B is an inner drive towards a goal, option A is a person's whole set of unique traits, and option D is how information is selected and interpreted."}},{"itemId":"be77509a-e5c6-557e-8eba-c99b00e66fb2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"adf22c51-e19b-55c9-8fe6-d335966db4b7","sourceKey":"bank:LAG-BUA111:CBB-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about consumer attitudes is correct?","options":["Attitudes are inborn and cannot be learned","A favourable attitude towards a product does not always mean the person intends to buy it or is able to","Attitudes have no effect on how consumers perceive information","Attitudes can only be held towards tangible objects"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Having a positive attitude is different from having the intention or the ability to buy, so a student can love a car brand without buying it. Option A is wrong because attitudes are learned through experience and interaction, and option D is wrong because attitudes can be towards intangible things too. Option C is wrong because attitudes shape perception."}},{"itemId":"cb18020f-c4b2-57f8-bc4c-f3a69eccac07","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e3330413-208b-5217-a9c4-cfff89d63f07","sourceKey":"bank:LAG-BUA111:CBB-036","parentItemId":null,"revision":1,"payload":{"prompt":"All the internal traits and behaviours that make a person unique, arising from heredity and experience, are known as","options":["Personality","Social class","Attitude","Subculture"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Personality is the full set of internal traits and behaviours that make each person unique, shaped by both heredity and experience. Option B and option D are social groupings, not individual traits, and option C is feelings and knowledge about a particular object."}},{"itemId":"2e9b15f4-b3dc-5a59-9540-0f09f2fdb88e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ec6a381c-f9d4-5a57-8633-8445ad168ec6","sourceKey":"bank:LAG-BUA111:CBB-037","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an example of a personality trait?","options":["Introversion","Social class","Dogmatism","Self-confidence"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Social class is a social grouping based on rank, occupation, income and similar factors, not a trait inside a person. Options D, C and A are internal characteristics that make a person unique, so they are personality traits."}},{"itemId":"f91c7655-dafe-5759-a71e-0305d64f1419","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8a332ce8-4657-5bab-abd1-99736f9e1437","sourceKey":"bank:LAG-BUA111:CBB-038","parentItemId":null,"revision":1,"payload":{"prompt":"In the family life cycle, an older married couple with no children living at home and with the head of household retired is in the stage called","options":["Empty nest I","Solitary survivor, retired","Full nest I","Empty nest II"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Empty nest II describes an older married couple with no children at home whose head has retired. Option A is the same couple while the head is still working, option B is a person living alone, and option C is a young family with children at home."}},{"itemId":"f5a7681f-835c-57ff-9d8c-e04c03b398cc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"861e857e-13cb-5647-898b-b47187b7bcc7","sourceKey":"bank:LAG-BUA111:CBB-039","parentItemId":null,"revision":1,"payload":{"prompt":"A group whose values, attitudes or behaviour a person adopts and uses as a guide is called a","options":["Buying centre","Subculture","Reference group","Social class"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"A reference group is any group, such as family, friends or a professional body, whose values and behaviour a person takes on, and its influence can be positive or negative. Option D is a group of similar social rank, option B is a smaller group within a culture, and option A is the people who make purchases in an organisation."}},{"itemId":"c91807a3-d839-5f02-b9c7-4ba7a56148b9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5a04669f-8f32-5915-aa31-f525d49f1d5e","sourceKey":"bank:LAG-BUA111:CBB-040","parentItemId":null,"revision":1,"payload":{"prompt":"Kunle, a 200-level accounting student, admires members of a professional accounting body he hopes to join one day, and he already buys the same kind of suits and briefcases they use. For Kunle, this professional body is","options":["A membership group","A subculture","An aspiration group","A disassociative group"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"An aspiration group is a group a person wants to belong to, which describes Kunle and the accounting body. Option A would apply only if he already belonged, and option D is a group a person does not want to belong to. Option B is a group within a culture based on region, age or ethnicity."}},{"itemId":"6bae17d9-039f-5e4f-ae02-73827feb5074","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"421101c4-d1c4-532a-ab94-331af2e0a86e","sourceKey":"bank:LAG-BUA111:CBB-041","parentItemId":null,"revision":1,"payload":{"prompt":"A bank designs a credit card endorsed by a university's alumni association and offers it to the association's members. This approach is known as","options":["Mass marketing","Megamarketing","Affinity marketing","Comparative advertising"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Affinity marketing targets members of a reference group, with the group itself endorsing the product to its members, as with this alumni credit card. Option D compares a brand with rivals, option A uses one offer for the whole market, and option B uses power and public relations to enter blocked markets."}},{"itemId":"1f911ff7-3946-5dd9-b848-cfd9b724c78b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"64e4568a-31ea-5895-9c45-32f32afe2463","sourceKey":"bank:LAG-BUA111:CBB-042","parentItemId":null,"revision":1,"payload":{"prompt":"An open group of people who have similar social rank, often based on occupation, education, income and possessions, is called a","options":["Social class","Culture","Membership group","Subculture"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"A social class is an open group of people with similar social rank, and it influences the type, quality and quantity of products they buy. Option B is the values passed down in a whole society, option D is a smaller group within that culture, and option C is any group a person belongs to, not one defined by rank."}},{"itemId":"ad0d82f0-a6ae-5b58-8fd2-640c69628c4d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5d480778-0b8a-5eb4-9904-a88666638e68","sourceKey":"bank:LAG-BUA111:CBB-043","parentItemId":null,"revision":1,"payload":{"prompt":"The values, ideas and attitudes that are accepted by a homogeneous group of people and passed down from one generation to the next are known as","options":["Culture","Social class","Reference group","Personality"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Culture is the set of values, ideas and attitudes a society accepts and passes on through generations; it shapes what people eat, wear and buy. Options B and C are narrower social groupings, and option D belongs to one individual, not a whole group."}},{"itemId":"ec3e4424-5cb1-5ea7-9354-7d886465416d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2863cbf2-a4d4-5767-adb4-d4ba2af01fa4","sourceKey":"bank:LAG-BUA111:CBB-044","parentItemId":null,"revision":1,"payload":{"prompt":"The Yoruba, Hausa and Igbo groups within Nigeria, each with its own distinguishing modes of behaviour, are best described by a marketer as","options":["Social classes","Buying centres","Subcultures","Aspiration groups"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Subcultures are smaller groups within a culture, based on things like region and ethnic background, and culturally aware marketers treat them as distinct segments. Option A is based on rank, option D is a group a person wishes to join, and option B is an organisational purchasing unit."}},{"itemId":"614f342f-52c9-53e3-be5c-752b49ab711a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"66e267c2-ff84-5dbc-b692-d22f7ec56e98","sourceKey":"bank:LAG-BUA111:CBB-045","parentItemId":null,"revision":1,"payload":{"prompt":"Organisations that buy goods and services in order to resell them at a profit make up the","options":["Consumer market","Government market","Industrial market","Reseller market"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Reseller markets, such as wholesalers and retailers, buy goods to sell them again at a profit. Option A buys for personal consumption, option C buys to produce other goods and services, and option B buys to provide public services."}},{"itemId":"ee0b8e7b-2edd-5452-890c-1655e71876ff","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"63ff4c07-3463-53de-b9e3-0da5ce82cdd6","sourceKey":"bank:LAG-BUA111:CBB-046","parentItemId":null,"revision":1,"payload":{"prompt":"When a cement manufacturer's demand for limestone rises because more households are building houses, the demand for limestone is described as","options":["Impulse demand","Effective demand","Primary consumer demand","Derived demand"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Organisational demand is derived demand: it comes from the demand for the consumer goods the organisation helps to produce, here houses. Option A relates to unplanned consumer purchases, and option C is demand by final consumers themselves. Option B means the actual sales of a product type, not where the demand comes from."}},{"itemId":"3b3b9130-b194-5951-b415-bbaf8e3dc470","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c446dc12-e4ee-570d-837b-fa997cb57296","sourceKey":"bank:LAG-BUA111:CBB-047","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with consumer markets, organisational markets usually have","options":["Demand that does not depend on consumer demand","Less formal buying decisions made by untrained individuals","Fewer but larger buyers","Many small buyers purchasing for personal use"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Organisational markets typically consist of fewer buyers who each purchase in large quantities, using formal procedures and trained buyers. Option D describes consumer markets, option A contradicts derived demand, and option B is the opposite of the professional, formal buying found in organisations."}},{"itemId":"0803f2f8-a754-5994-ac70-c72988ee42a0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"69a57d2c-c276-5442-b9c4-f15c6889dacb","sourceKey":"bank:LAG-BUA111:CBB-048","parentItemId":null,"revision":1,"payload":{"prompt":"At an oil-servicing firm in Port Harcourt, the purchasing manager's secretary decides which visiting sales representatives get to see the manager and which brochures reach his desk. In the buying centre, the secretary is acting as a","options":["Decider","User","Gatekeeper","Approver"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"A gatekeeper controls the flow of information into the buying organisation, as the secretary does by screening salespeople and brochures. Option B will use the product, option A makes the final choice, and option D authorises proposed actions; the secretary does none of these."}},{"itemId":"83b11e13-e22d-5351-81e7-365a56002336","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e0ea7e1c-7f93-5312-8465-9eb27459f116","sourceKey":"bank:LAG-BUA111:CBB-049","parentItemId":null,"revision":1,"payload":{"prompt":"A bottling company is buying a new filling machine. The factory operators who will run the machine every day are members of the buying centre in the role of","options":["Buyers","Users","Deciders","Gatekeepers"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Users are the members of the organisation who will actually use the product, and they often start the buying process. Option D controls information flow, option A has formal authority to select suppliers and arrange terms, and option C makes the final decision."}},{"itemId":"e39ad976-162f-52e8-9050-f26509861745","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e4783cf1-7e87-567a-982a-af787e21a0b8","sourceKey":"bank:LAG-BUA111:CBB-050","parentItemId":null,"revision":1,"payload":{"prompt":"Engineers at a construction company help draw up the technical specifications for new cranes and give their opinion on which models are suitable, but they do not place the order. They are acting as","options":["Users","Buyers","Gatekeepers","Influencers"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Influencers affect the buying decision by helping to define specifications and providing information for evaluating options; technical staff are typical influencers. Option B places the order and negotiates terms, option A operates the product, and option C controls the flow of information."}},{"itemId":"a6ba7e32-3115-5cc9-a204-6fd387a2f294","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0d2f0547-147e-5c8b-a7bb-7e4355961a0b","sourceKey":"bank:LAG-BUA111:CBB-051","parentItemId":null,"revision":1,"payload":{"prompt":"In a manufacturing firm, the purchasing officer has formal authority to select the supplier, negotiate the price and arrange the terms of purchase for new equipment. In the buying centre, she is the","options":["Buyer","Influencer","User","Gatekeeper"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The buyer has formal authority to select the supplier and arrange the terms of purchase, which is exactly the purchasing officer's job here. Option B only provides information, option C operates the product, and option D controls access to information."}},{"itemId":"3f04cfc1-7442-5aee-952c-7c99eba981eb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"507ceaf2-04aa-5b59-8393-b7dd26a6a601","sourceKey":"bank:LAG-BUA111:CBB-052","parentItemId":null,"revision":1,"payload":{"prompt":"A purchasing team recommends buying a N15,000,000 generator from a particular supplier, but the purchase cannot go ahead until the managing director signs off on it. The managing director's role in the buying centre is that of","options":["User","Approver","Gatekeeper","Influencer"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Approvers authorise the actions that deciders or buyers propose, which is what the managing director does by signing off. Option A uses the product, option D supplies information that shapes the decision, and option C controls information flow."}},{"itemId":"fe4753a3-fff3-54da-b1c9-2d446196dd8f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fc86be89-0201-57fc-a63b-cffe37f5dbf9","sourceKey":"bank:LAG-BUA111:CBB-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a role in an organisation's buying centre?","options":["User","Gatekeeper","Decider","Promoter"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Buying centre roles include users, influencers, buyers, deciders, approvers and gatekeepers, so options A, B and C are all genuine roles. 'Promoter' is not a buying centre role."}},{"itemId":"90463979-76ad-5987-b0d0-38b7b1135096","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"941b563e-9247-5245-9884-d4fb1521b51e","sourceKey":"bank:LAG-BUA111:CBB-054","parentItemId":null,"revision":1,"payload":{"prompt":"Every month, the administrative office of a Lagos school reorders the same brand of A4 paper from the same supplier, without changing anything about the order. This buying situation is a","options":["Straight rebuy","New task","Modified rebuy","Extensive decision making"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"A straight rebuy is a routine reorder with no changes, usually handled by the purchasing department. Option C would involve changing the specifications, prices, terms or supplier, and option B is a first-time purchase. Option D describes consumer buying behaviour, not an organisational buy class."}},{"itemId":"6cc256b4-d379-53ef-bfa0-8f16ec415703","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cd376431-2058-53ea-9e3c-247fdf86a92b","sourceKey":"bank:LAG-BUA111:CBB-055","parentItemId":null,"revision":1,"payload":{"prompt":"A hotel that regularly buys bed sheets decides this year to change the fabric specification and invite two new suppliers to quote, alongside its current supplier. This buying situation is a","options":["Impulse buying","Modified rebuy","Straight rebuy","New task"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"A modified rebuy occurs when a firm wants to change product specifications, prices, terms or suppliers for something it already buys. Option C would be a reorder with no changes, and option D is a first-time purchase. Option A is a type of unplanned consumer purchase."}},{"itemId":"65dd5286-5237-5016-8515-7b9bdeb5b1bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6e68fc46-66e6-5bc2-a914-eb0e1f4c5b41","sourceKey":"bank:LAG-BUA111:CBB-056","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano textile company decides, for the first time ever, to buy and install a solar power system for its factory, and it gathers a great deal of information before choosing. This buying situation is a","options":["Modified rebuy","Routine response behaviour","New task","Straight rebuy"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"A new task is a first-time purchase, which carries the most risk and needs the most information and people in the decision. Options D and A apply to products the firm has bought before, and option B is a low-involvement consumer buying behaviour."}},{"itemId":"5f863a4f-79f3-59d0-aa7b-4bc352fae8b4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"afaf6b55-a9e0-551d-a20e-065cfed241c2","sourceKey":"bank:LAG-BUA111:CON-001","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing management philosophy which holds that consumers will favour products that are available and highly affordable, so that management should concentrate on improving production and distribution efficiency, is the:","options":["Product concept","Production concept","Marketing concept","Selling concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept assumes buyers mainly want goods that are easy to find and cheap, so the firm's energy goes into efficient output and wide distribution. Option A is about quality and features, not availability and low cost. Option D assumes buyers must be pushed by heavy selling, and option C starts from customer needs."}},{"itemId":"cee06eeb-eced-5942-ac86-30f26849aa1d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1973ca89-efcd-576e-af20-c08fd6bfc9cb","sourceKey":"bank:LAG-BUA111:CON-002","parentItemId":null,"revision":1,"payload":{"prompt":"The product concept holds that consumers will favour products that:","options":["Are widely available at the lowest possible prices","Are pushed hard through advertising and personal selling","Offer the most quality, performance and innovative features","Best protect the long-run welfare of society"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Under the product concept, managers believe buyers choose the best-made, most feature-rich product, so they focus on continuous product improvement. Option A describes the production concept, option B the selling concept, and option D the societal marketing concept."}},{"itemId":"9f2b7e6f-fc33-5460-a1df-6ed4a0d12f6f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"36377ca9-0553-5973-a86e-17c181f9488c","sourceKey":"bank:LAG-BUA111:CON-003","parentItemId":null,"revision":1,"payload":{"prompt":"The idea that consumers will not buy enough of an organisation's products unless the organisation undertakes a large-scale selling and promotion effort is known as the:","options":["Production concept","Societal marketing concept","Selling concept","Marketing concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept assumes buyers are reluctant, so the firm must persuade them through aggressive selling and promotion. Option A focuses on efficient production, option D on understanding and satisfying customer needs, and option B adds society's long-run welfare to the marketing concept."}},{"itemId":"eac8fb80-5a37-55d2-b68a-f0cd2f3defe0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"484bc470-312f-5e53-8eb2-41cbb57ab3d3","sourceKey":"bank:LAG-BUA111:CON-004","parentItemId":null,"revision":1,"payload":{"prompt":"The philosophy that achieving organisational goals depends on knowing the needs and wants of target markets and delivering the desired satisfactions better than competitors is the:","options":["Marketing concept","Product concept","Selling concept","Production concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"This is the marketing concept: the customer's needs are the starting point, and profit comes from satisfying them better than rivals. Option C starts from products the firm already has and pushes them, option B focuses on product features, and option D focuses on output and low cost."}},{"itemId":"01291849-2e25-5390-b74a-efda4c9b4043","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9099e468-53e3-557a-87bd-4bc925093a2b","sourceKey":"bank:LAG-BUA111:CON-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which marketing philosophy holds that a firm's marketing decisions should take into account consumers' wants, the company's requirements, consumers' long-run interests and society's long-run interests?","options":["Selling concept","Marketing concept","Societal marketing concept","Product concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept adds the long-run interests of consumers and society to the usual concern for customer wants and company profit. Option B is the closest, but the pure marketing concept focuses on satisfying customer wants profitably without explicitly weighing society's long-run welfare. Options A and D do not centre on customers or society at all."}},{"itemId":"5beb620b-6e76-500b-851b-9254b808b25f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0b0b905b-3eb8-535e-beec-7f6f39685700","sourceKey":"bank:LAG-BUA111:CON-006","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano noodle manufacturer finds that demand is far greater than it can supply. Management concentrates on adding production lines, cutting unit costs and spreading distribution so that more households can afford a pack at N250. Which philosophy is the firm following?","options":["Production concept","Selling concept","Societal marketing concept","Product concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Expanding output, cutting costs and making the product widely available and affordable is the heart of the production concept, which works best when demand exceeds supply. Option D would focus on adding quality or features, option B on persuading reluctant buyers, and option C on society's long-run welfare."}},{"itemId":"f8623709-81f0-5b36-b263-dc36db950d8d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"08cbfc53-59c0-5c19-a60a-0515db6940e0","sourceKey":"bank:LAG-BUA111:CON-007","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos electronics firm keeps adding features to its power bank (more ports, a torch, a radio) because managers believe customers will always choose the most advanced model. It never asks customers what they actually need. Which philosophy does this reflect?","options":["Product concept","Production concept","Marketing concept","Selling concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Believing that the most advanced, feature-packed product will sell itself is the product concept. Option B would focus on cheap, plentiful output, option D on aggressive selling, and option C would begin by studying what customers need, which this firm does not do."}},{"itemId":"23f3b9cd-86ba-5e96-9970-8ae2cdd30d92","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"24599d00-1f61-5575-b0c7-996bc7929cb6","sourceKey":"bank:LAG-BUA111:CON-008","parentItemId":null,"revision":1,"payload":{"prompt":"An insurance company in Abuja recruits a large team of agents to approach people in markets and offices with persuasive pitches, because few people seek out life insurance on their own. Which philosophy does this reflect?","options":["Product concept","Production concept","Marketing concept","Selling concept"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Life insurance is an unsought good, and pushing it through a large, persuasive sales force is classic selling-concept behaviour. Option B is about cheap mass output, option A about product features, and option C would start from careful study of customers' needs."}},{"itemId":"250e7754-84e9-5983-9a89-513d49f6fdd0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b95a3849-f837-506e-bb46-0417379fac37","sourceKey":"bank:LAG-BUA111:CON-009","parentItemId":null,"revision":1,"payload":{"prompt":"A restaurant near the University of Ibadan surveys students, finds that they want affordable, healthy meals delivered quickly, and then designs its menu, prices and delivery around these needs. It aims to profit from satisfied, repeat customers. Which philosophy is this?","options":["Marketing concept","Product concept","Selling concept","Production concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Starting from the target market's needs and earning profit through customer satisfaction is the marketing concept. Option C would push existing meals through heavy promotion, option D would focus on cheap mass output, and option B would improve the food without first asking what customers want."}},{"itemId":"def5fd73-263a-58ff-91cf-9416cc1b1226","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6e84880e-28f9-5321-b94f-662d60372692","sourceKey":"bank:LAG-BUA111:CON-010","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian soft-drink company cuts the sugar content of its drinks, switches to recyclable bottles and funds the clearing of drains blocked by plastic waste, while still aiming to satisfy customers and earn a profit. This best reflects the:","options":["Production concept","Societal marketing concept","Marketing concept","Selling concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"Balancing customer satisfaction and profit with the long-run welfare of consumers and society is the societal marketing concept. Option C is partly true because the firm still satisfies customers, but the deliberate attention to health and environment goes beyond the pure marketing concept. Options D and A ignore both customer needs and social welfare."}},{"itemId":"bd0bfe1f-22b4-5afe-abd5-514d027571d8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9b0cf486-0d1e-5b72-a913-a55d6e9b8970","sourceKey":"bank:LAG-BUA111:CON-011","parentItemId":null,"revision":1,"payload":{"prompt":"In the classic contrast between the selling concept and the marketing concept, the STARTING POINT of the selling concept is the:","options":["Society's long-run welfare","Target customers' needs","Market","Factory"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept takes an inside-out view: it starts from the factory and the products already made, then uses selling and promotion to move them. Options C and B are the starting point and focus of the marketing concept, which takes an outside-in view. Option A is the extra concern of the societal marketing concept."}},{"itemId":"65acb0dd-2373-539d-ac5f-bf3e003e407b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5bc78603-45c2-595b-86cb-4f5749241e2d","sourceKey":"bank:LAG-BUA111:CON-012","parentItemId":null,"revision":1,"payload":{"prompt":"Under the marketing concept, the MEANS by which a firm pursues its goals is:","options":["Integrated marketing","Selling and promoting","Mass production at low cost","Continuous product improvement"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept reaches its goals through integrated marketing, in which all marketing activities and departments work together to satisfy the customer. Option B is the means used by the selling concept, option C reflects the production concept, and option D is the focus of the product concept."}},{"itemId":"6b92e770-cad8-590e-93ee-8e27d6d16968","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"08f2fdd5-41af-56cf-bdb6-eaeba4ae0ff6","sourceKey":"bank:LAG-BUA111:CON-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly contrasts the selling concept with the marketing concept?","options":["Selling focuses on society's welfare and seeks profit through low costs; marketing focuses on the factory and seeks profit through sales volume","Selling and marketing both focus on existing products, but marketing seeks profit through lower production costs","Selling focuses on customer needs and seeks profit through customer satisfaction; marketing focuses on existing products and seeks profit through sales volume","Selling focuses on existing products and seeks profit through sales volume; marketing focuses on customer needs and seeks profit through customer satisfaction"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept begins with what the firm has made and earns profit by moving volume, while the marketing concept begins with customer needs and earns profit by satisfying customers. Option C simply swaps the two concepts. Options A and B attach production or societal ideas that belong to other philosophies."}},{"itemId":"698ba2c5-f0a4-5cf2-bc48-dfa3904f0f6f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1c99683c-f93c-5ae4-a911-e715eebc2ad9","sourceKey":"bank:LAG-BUA111:CON-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of the selling concept?","options":["It begins with a careful study of target customers' needs","It relies heavily on aggressive selling and promotion","It aims at making the sale rather than building long-term customer relationships","It takes an inside-out perspective, starting from the firm's existing products"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Beginning with a careful study of customer needs is the outside-in approach of the marketing concept, so it is not a feature of the selling concept. Options D, B and C are all true of selling: it starts from the factory, pushes products through heavy promotion, and focuses on the immediate sale."}},{"itemId":"4e436583-a68c-5dea-82ad-a08744ed72e4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f35c779d-62e3-539e-aad5-85b30cba73c7","sourceKey":"bank:LAG-BUA111:CON-015","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept is described as an 'outside-in' perspective because it:","options":["Starts with the firm's existing products and pushes them out to buyers","Starts with a well-defined market and customer needs, then coordinates the firm's activities to satisfy them","Depends mainly on selling to foreign markets outside the home country","Hands all marketing work to outside agencies"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"'Outside-in' means the thinking starts outside the firm, with the market and its needs, and works back to what the firm should do. Option A is the inside-out view of the selling concept. Options C and D take the word 'outside' literally and have nothing to do with the philosophy."}},{"itemId":"b0ad9f19-b6c2-5c7c-9a42-d7e8cdcdae5c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d6034586-4881-56a3-854a-98104ce4c8c0","sourceKey":"bank:LAG-BUA111:CON-016","parentItemId":null,"revision":1,"payload":{"prompt":"Complete the well-known contrast: 'Selling focuses on the needs of the ______; marketing focuses on the needs of the ______.'","options":["Seller; buyer","Society; company","Buyer; seller","Producer; government"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Selling is preoccupied with the seller's need to convert products into cash, while marketing is preoccupied with satisfying the buyer's needs. Option C reverses the two. Options D and B bring in parties that the contrast does not refer to."}},{"itemId":"f2b78115-ca09-5377-b7d6-6c81f8270eff","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7a2453de-8a7b-5743-be28-2c488128941e","sourceKey":"bank:LAG-BUA111:CON-017","parentItemId":null,"revision":1,"payload":{"prompt":"The selling concept is most typically practised with:","options":["Any product whose demand already exceeds supply","Staple goods that are in short supply","Unsought goods, such as insurance, that buyers do not normally think of buying","Luxury goods that have long waiting lists of buyers"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept is common with unsought goods, where firms must actively find and persuade prospects. Options B, D and A all describe situations where buyers already want more than is available, so heavy selling effort is not needed."}},{"itemId":"bcc8229b-fc43-5be7-9163-7f31f33d1237","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b0d3b8e7-6eb0-5d3d-b366-c382973562ac","sourceKey":"bank:LAG-BUA111:CON-018","parentItemId":null,"revision":1,"payload":{"prompt":"The production concept can still be a useful philosophy in situations where:","options":["Buyers resist buying and must be persuaded","Demand for a product exceeds supply, or the product's cost is too high and must be brought down","Consumers demand highly customised products","The market is crowded with competing brands"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"When buyers want more than is available, or the product is too expensive, improving production efficiency and lowering cost makes sense. Option C calls for a customer-focused approach, option D for differentiation, and option A describes the setting of the selling concept."}},{"itemId":"e40530c3-3b7f-5f28-97d9-e7821e316c5d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ecf046db-f7ff-5c78-8950-0ce44e325fd0","sourceKey":"bank:LAG-BUA111:CON-019","parentItemId":null,"revision":1,"payload":{"prompt":"A manager says, 'If we build a better product, customers will beat a path to our door,' and concentrates on improving the product while ignoring what customers actually want. This attitude is a trap most associated with the:","options":["Societal marketing concept","Product concept","Production concept","Marketing concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The 'better mousetrap' belief is the product concept's typical weakness: it assumes a better product sells itself and can lead to marketing myopia. Option C focuses on availability and cost rather than product quality. Options A and D both begin with customers, which this manager ignores."}},{"itemId":"180b9a1c-a324-521d-ad9d-e92fd9deca5a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"67b601bb-1754-5768-8f5d-8d9f1d933bc7","sourceKey":"bank:LAG-BUA111:CON-020","parentItemId":null,"revision":1,"payload":{"prompt":"'Marketing myopia' refers to the mistake of:","options":["Spending more on advertising than the firm can afford","Selling only in local markets instead of exporting","Focusing on the specific product a firm sells rather than on the customer need or benefit it provides","Ignoring production costs when setting prices"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Marketing myopia is short-sightedness: a firm sees itself as selling a product, such as drills, instead of meeting a need, such as making holes, and so misses changes in how customers meet that need. Options A, D and B are real business errors but they are not what the term means."}},{"itemId":"c7633bb6-6684-5d35-89eb-83440446990d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7e335c73-6de5-5208-a2f1-4ceaa009f766","sourceKey":"bank:LAG-BUA111:CON-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the order in which these marketing management philosophies developed?","options":["Production concept -> marketing concept -> selling concept -> societal marketing concept","Marketing concept -> production concept -> selling concept -> societal marketing concept","Production concept -> selling concept -> marketing concept -> societal marketing concept","Selling concept -> production concept -> marketing concept -> societal marketing concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Firms first concentrated on producing enough (production), then on pushing surplus output (selling), then on satisfying customer needs (marketing), and later on balancing these with society's welfare (societal marketing). Option D wrongly puts selling before production, option A puts marketing before selling, and option B starts with marketing."}},{"itemId":"c406db62-9fab-5aa1-9b5f-11c594ef3caa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4f46f53f-4917-5e6f-a029-1022c0b86735","sourceKey":"bank:LAG-BUA111:CON-022","parentItemId":null,"revision":1,"payload":{"prompt":"A fast-food chain in Port Harcourt sells cheap, tasty fried meals that customers love, but critics argue that the meals contribute to obesity. One critic says the chain satisfies customers' short-run wants but ignores their long-run welfare. The critic is reasoning from the:","options":["Selling concept","Societal marketing concept","Product concept","Production concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept questions whether the pure marketing concept overlooks conflicts between consumers' short-run wants and their long-run welfare, which is exactly the critic's point. Options A, C and D do not concern consumer or social welfare at all."}},{"itemId":"79eae802-ad10-5b3c-b498-d9e1e26f04bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b59e927b-704a-5888-b80c-a27b0a0f4be4","sourceKey":"bank:LAG-BUA111:CON-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which philosophy holds that the firm's task is not to find the right customers for its products, but to find the right products for its customers?","options":["Production concept","Product concept","Marketing concept","Selling concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Finding the right products for customers means starting from customer needs, which is the marketing concept. Option D does the opposite: it looks for buyers for the products already made. Options B and A start from product quality or production efficiency."}},{"itemId":"32757ca1-7577-5b26-8fe5-ddbf6eef5607","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0bba7daa-d932-5d90-88ef-943faa3b77e2","sourceKey":"bank:LAG-BUA111:CON-024","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept is often said to rest on four pillars. Which of the following is NOT one of them?","options":["Integrated marketing","Mass production","Target market","Customer needs"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The four pillars of the marketing concept are target market, customer needs, integrated marketing and profitability. Mass production belongs to the production concept. Options C, D and A are genuine pillars."}},{"itemId":"d4219c1b-b972-5322-9899-8f65eeef00ed","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3d7e91e3-2091-5d1d-8132-cf92042ef3a0","sourceKey":"bank:LAG-BUA111:CON-025","parentItemId":null,"revision":1,"payload":{"prompt":"Under the marketing concept, 'integrated marketing' means that:","options":["The marketing department takes over the work of all other departments","The firm merges with its competitors to control the market","The firm uses only one advertising medium for all its messages","All the firm's departments and marketing activities work together to serve the customer's interests"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Integrated marketing means the different marketing functions, and the other departments, are coordinated so that everyone works to satisfy the customer. Option B confuses integration with mergers. Option A wrongly suggests marketing replaces other departments, and option C is not what integration means."}},{"itemId":"b57bea09-d310-5077-b9c3-db64ab92a3d4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"878fbb50-63bf-5f83-aa26-8bf486baa00c","sourceKey":"bank:LAG-BUA111:CON-026","parentItemId":null,"revision":1,"payload":{"prompt":"The holistic marketing concept is based on the recognition that:","options":["'Everything matters' in marketing, so a broad, integrated perspective is needed in developing and carrying out marketing programmes","Production efficiency is the only thing that matters","Marketing is simply another name for advertising","Only the sales force determines marketing success"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Holistic marketing sees the marketing effort as a connected whole, recognising that everything matters and that an integrated perspective is needed. Option B is the narrow view of the production concept, option D is close to the selling concept, and option C confuses marketing with one promotional tool."}},{"itemId":"5ba53eb4-c139-5e7b-bcb1-0024a5ce9286","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"65a6df82-076d-53af-a327-722d90ce10c0","sourceKey":"bank:LAG-BUA111:CON-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a component of the holistic marketing concept?","options":["Integrated marketing","Internal marketing","Relationship marketing","Production marketing"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Holistic marketing brings together components such as relationship marketing, integrated marketing and internal marketing, along with responsibility for wider performance and social results. 'Production marketing' is not one of its components. Options C, B and A are recognised parts of holistic marketing."}},{"itemId":"48c2a77b-20f4-50bb-8bdc-b5c8cd3456d8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"65a941fd-92ac-57b7-aec4-815ae15d2ee5","sourceKey":"bank:LAG-BUA111:CON-028","parentItemId":null,"revision":1,"payload":{"prompt":"Within holistic marketing, 'internal marketing' refers to:","options":["Marketing only to the firm's existing customers","Promoting products only through the company's own website","Selling the firm's products only within its home country","Hiring, training and motivating able employees who want to serve customers well"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Internal marketing treats employees as an internal market: they must be hired, trained and motivated so that they serve customers well. Option C confuses 'internal' with domestic markets. Options A and B describe a narrow customer focus or a single channel."}},{"itemId":"9622ebe5-4598-5632-9d01-862f5d017c41","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9c5d250f-ad51-53a7-9840-66ea454a4768","sourceKey":"bank:LAG-BUA111:CON-029","parentItemId":null,"revision":1,"payload":{"prompt":"The part of holistic marketing that aims to build mutually satisfying long-term relationships with customers, suppliers, distributors and other partners in order to earn and keep their business is:","options":["Mass marketing","Integrated marketing","Relationship marketing","Internal marketing"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Relationship marketing focuses on long-term, mutually satisfying ties with key parties. Option D is about employees, option B is about coordinating marketing activities, and option A means selling one offer to the whole market, which is not part of holistic marketing."}},{"itemId":"dbe1fe11-a1ae-503f-a1c2-45e8389d1031","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7a0ed139-bed3-58b1-a024-8f2f3bdcaba9","sourceKey":"bank:LAG-BUA111:CON-030","parentItemId":null,"revision":1,"payload":{"prompt":"Market orientation is best described as:","options":["A firm's decision to sell its products in as many geographic markets as possible","The organisation-wide putting into practice of the marketing concept, in which the firm continuously gathers information about customers and competitors and coordinates all departments to create superior customer value","The arrangement of a factory so that it produces at the lowest possible cost","A firm's focus on the performance of its shares on the stock market"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"Market orientation is the marketing concept in action: the whole organisation gathers market information, shares it and acts on it to deliver superior value. Option A confuses it with market expansion, option D with stock markets, and option C describes a production orientation."}},{"itemId":"0d2a6fe0-33e1-5433-9bce-4fc2a3b50517","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9a3bba16-8c57-5268-a899-8773570da2bf","sourceKey":"bank:LAG-BUA111:CON-031","parentItemId":null,"revision":1,"payload":{"prompt":"The three behavioural components of market orientation are:","options":["Production, selling and promotion","Segmentation, targeting and positioning","Product, price and place","Customer orientation, competitor orientation and inter-functional coordination"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Market orientation is made up of customer orientation, competitor orientation and inter-functional coordination. Option C lists marketing mix elements, option A mixes production and selling activities, and option B lists the steps of target marketing."}},{"itemId":"77db31d7-34d9-5328-99d2-a1e73c3683d7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2d0e9a87-640f-520c-a5a4-c9412a36febb","sourceKey":"bank:LAG-BUA111:CON-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the three behavioural components of market orientation?","options":["Competitor orientation","Production orientation","Inter-functional coordination","Customer orientation"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"Production orientation, a focus on efficient output, is a different philosophy and is not a component of market orientation. Options D, A and C are the three components: understanding customers, understanding competitors, and coordinating all departments to create value."}},{"itemId":"13f6cd01-c918-5f75-953a-9cad48b8bbc3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"715fb128-f08f-520e-99b1-f05bd3f866e4","sourceKey":"bank:LAG-BUA111:CON-033","parentItemId":null,"revision":1,"payload":{"prompt":"The component of market orientation that involves understanding target buyers well enough to create superior value for them continuously is:","options":["Production orientation","Customer orientation","Competitor orientation","Inter-functional coordination"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"Customer orientation is about knowing the target buyers so well that the firm can keep creating superior value for them. Option C looks at rivals, option D is about departments working together, and option A is not a component of market orientation."}},{"itemId":"16aaf166-654d-58b7-95b5-224847a77cdf","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"11b7b2d8-63a3-5329-9bbf-6775130cf52c","sourceKey":"bank:LAG-BUA111:CON-034","parentItemId":null,"revision":1,"payload":{"prompt":"Understanding the short-term strengths and weaknesses, and the long-term capabilities and strategies, of both current and potential competitors is known as:","options":["Competitor orientation","Inter-functional coordination","Selling orientation","Customer orientation"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Competitor orientation means studying present and potential rivals, both their current strengths and weaknesses and their long-term capabilities. Option D concerns buyers, option B concerns coordination across departments, and option C is not a component of market orientation."}},{"itemId":"0bc2b26b-1719-5a3a-8942-fa1ebd16d9ca","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f4386e71-c29e-5f22-a3ec-b70a450e881c","sourceKey":"bank:LAG-BUA111:CON-035","parentItemId":null,"revision":1,"payload":{"prompt":"The coordinated use of a company's resources across all its departments to create superior value for target customers is called:","options":["Customer orientation","Competitor orientation","Vertical integration","Inter-functional coordination"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Inter-functional coordination means marketing is not left to one department; production, finance, R&D and others work together to create customer value. Options A and B are the other two components, focused on buyers and rivals. Option C is about owning stages of the supply chain."}},{"itemId":"2919a20e-267d-5a22-aec1-c81b0134366c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5ad1f499-80a5-57d3-b6bd-37a005a9fb73","sourceKey":"bank:LAG-BUA111:CON-036","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fintech firm holds monthly focus groups with traders at Balogun Market, tracks every complaint and redesigns its app based on what users say they need. Which component of market orientation is this firm mainly displaying?","options":["Competitor orientation","Customer orientation","Selling orientation","Inter-functional coordination"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"Studying users' needs and complaints in order to keep improving the value they receive is customer orientation. Option A would involve studying rival firms, and option D would involve departments working together. Option C is about pushing products, not understanding buyers."}},{"itemId":"afc9ea7d-d9a6-560a-9fee-8b6558527cb8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8c9d3eaf-e0e0-5729-983b-d9b6da326c6d","sourceKey":"bank:LAG-BUA111:CON-037","parentItemId":null,"revision":1,"payload":{"prompt":"Managers at a Nigerian paint company meet weekly to review rival brands' price changes and new launches, and to assess a foreign firm that is planning to enter the market. Which component of market orientation is this?","options":["Production orientation","Inter-functional coordination","Customer orientation","Competitor orientation"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Tracking current rivals and assessing a potential entrant is competitor orientation. Option C would focus on buyers' needs, option B on coordination across departments, and option A on efficient output."}},{"itemId":"cb24312e-2fd0-5d6a-b174-5f2b2feaaa4b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dd5b9ab1-0041-5fb2-9c0f-8be46062cd1f","sourceKey":"bank:LAG-BUA111:CON-038","parentItemId":null,"revision":1,"payload":{"prompt":"At an Aba shoe company, staff from production, finance, R&D and sales meet together, share customer feedback and jointly plan a new school-shoe range so that every department contributes to customer value. This illustrates:","options":["The selling concept","Competitor orientation","Inter-functional coordination","Production orientation"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Different departments sharing information and planning together to create customer value is inter-functional coordination. Option B would centre on rivals. Option D would centre on output efficiency, and option A on pushing existing products."}},{"itemId":"902bd77d-35a7-5e48-b1b5-73d35ac5e595","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4c99c1df-4c09-5195-89b1-2257375c88bf","sourceKey":"bank:LAG-BUA111:CON-039","parentItemId":null,"revision":1,"payload":{"prompt":"Besides its three behavioural components, market orientation is commonly linked with which two decision criteria?","options":["Short-term sales volume and cost cutting","Production capacity and inventory levels","Market share and advertising spending","Long-term focus and profitability"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Market orientation is usually described with two decision criteria: a long-term focus and profitability. Option A reflects a short-term selling mindset. Options C and B are performance measures or operational concerns, not the criteria attached to market orientation."}},{"itemId":"0c322a06-96bb-5748-92ab-7cde92d584d6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e3cb9758-30b6-5eb2-b58d-a484cfe15714","sourceKey":"bank:LAG-BUA111:CON-040","parentItemId":null,"revision":1,"payload":{"prompt":"From an information-processing point of view, market orientation is the organisation-wide generation of market intelligence, the dissemination of that intelligence across departments, and:","options":["Organisation-wide responsiveness to it","Restriction of it to top management","Storage of it in company archives only","Sale of it to competing firms"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"In this view, market orientation means generating market intelligence, spreading it across departments and responding to it throughout the organisation. Options C and B would stop the information being used, and option D has nothing to do with serving customers."}},{"itemId":"b6826cec-5e22-5ab7-8dd8-a5913a462cf8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"82dce7fe-99c9-5641-92fd-566c4a8b64c4","sourceKey":"bank:LAG-BUA111:CON-041","parentItemId":null,"revision":1,"payload":{"prompt":"The relationship between the marketing concept and market orientation is best stated as:","options":["They are opposite philosophies that cannot exist in the same firm","Market orientation replaces customers with competitors as the firm's main focus","The marketing concept is the philosophy; market orientation is the set of behaviours that puts it into practice","Market orientation is another name for the production concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept is the business philosophy, and market orientation describes the actual behaviours that carry it out. Option A is false because they go together. Option D confuses it with a production focus, and option B ignores that customer orientation is a central component."}},{"itemId":"1a71cd0c-7e9c-5118-96a4-b38b9355412e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8556016a-3c50-5fdb-b5c4-6d7c43222518","sourceKey":"bank:LAG-BUA111:CON-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following activities is LEAST associated with customer orientation?","options":["Studying a rival firm's cost structure","Measuring customer satisfaction regularly","Researching the needs of target customers","Following up after sales to learn how customers use the product"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Studying a rival's cost structure is part of competitor orientation, not customer orientation. Options B, C and D all help the firm understand its customers and create value for them."}},{"itemId":"16f90812-46d1-545b-9569-d0ae9625a40a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8c804065-4ef2-51fd-ad8e-6d7ed9d6e30b","sourceKey":"bank:LAG-BUA111:CON-043","parentItemId":null,"revision":1,"payload":{"prompt":"A bank defines its business as 'helping Nigerians move and keep money safely and cheaply' rather than 'operating bank branches'. This is an example of:","options":["The selling concept","The production concept","A market-oriented definition of the business","A product-oriented definition of the business"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Defining the business by the customer need it satisfies, rather than by the product or facility it operates, is a market-oriented definition and protects the firm from marketing myopia. Option D would be 'operating bank branches'. Options B and A do not describe how a business defines its mission."}},{"itemId":"350bbaf6-caa3-5c98-bd19-9bf7f9aaa5c8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"21e8de8a-9d68-51b1-8be6-b7757829932e","sourceKey":"bank:LAG-BUA111:CON-044","parentItemId":null,"revision":1,"payload":{"prompt":"In marketing, a 'marketing management philosophy' (or marketing concept in its broad sense) refers to:","options":["The sequence of steps used to prepare a marketing plan","The legal rules that govern advertising in a country","The full list of products a firm offers for sale","The guiding idea about what should drive a firm's marketing and how much weight to give the interests of the organisation, customers and society"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"A marketing management philosophy is the orientation that guides marketing decisions, such as whether production, selling, customers or society comes first. Option B describes regulation, option A a planning process, and option C a product mix."}},{"itemId":"31eda882-22e3-5af3-9c40-b3c1d5d0db08","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"80b77546-b860-554e-af42-b0bc18e1b672","sourceKey":"bank:LAG-BUA111:CON-045","parentItemId":null,"revision":1,"payload":{"prompt":"A key and risky assumption of the selling concept is that:","options":["Customers always prefer the cheapest product available","Customers always prefer the product with the most features","Customers who are coaxed into buying will like the product, or if they do not, will forget their disappointment and buy again","Society's interests are fully protected by government law"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept assumes that persuaded buyers will be satisfied, or will forget their disappointment, which is usually a poor assumption because unhappy buyers rarely return and may complain to others. Option A is the production concept's assumption and option B the product concept's. Option D is not part of any of these philosophies."}},{"itemId":"0d45c954-8ccf-5373-95bc-bfda7f6eaf60","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"13999f90-9d9b-5067-9ba1-4c5b8d16f8df","sourceKey":"bank:LAG-BUA111:CON-046","parentItemId":null,"revision":1,"payload":{"prompt":"The phrase 'sense and respond' rather than 'make and sell' captures the philosophy of the:","options":["Production concept","Marketing concept","Product concept","Selling concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"'Sense and respond' means first sensing what customers need and then responding with suitable offers, which is the marketing concept. 'Make and sell' is the attitude of option D. Options A and C also begin with what the firm produces rather than with the customer."}},{"itemId":"3b4db935-2a1e-57af-bf32-f01dfa42aa38","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9a789d37-bbbb-50cf-b184-d93cda0759bf","sourceKey":"bank:LAG-BUA111:CON-047","parentItemId":null,"revision":1,"payload":{"prompt":"A firm studies customers closely, anticipates needs they have not yet expressed, and creates products that meet those latent needs before customers ask for them. This approach is called:","options":["Customer-driving marketing","The selling concept","Customer-driven marketing","The production concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Customer-driving marketing means understanding customers better than they understand themselves and meeting needs they have not yet expressed. Option C works when customers already know what they want and the firm responds to stated needs. Options B and D do not start from customer needs at all."}},{"itemId":"04d6902d-dce3-546f-bc2b-9c100d8e1e79","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0b3e78c4-c9d2-53f1-a3cd-60bde06d6f69","sourceKey":"bank:LAG-BUA111:CON-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about the evolution of marketing philosophies is TRUE?","options":["The production concept places customer needs at the centre of the business","The selling concept takes the market as its starting point","The marketing concept ignores competitors and looks only at customers","The shift from the selling concept to the marketing concept moved the firm's focus from its own products to the buyer's needs"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Moving from selling to marketing changed the focus from the seller's products to the buyer's needs. Option A is false because the production concept centres on output and cost. Option B is false because selling starts from the factory, and option C is false because the marketing concept requires satisfying customers better than competitors."}},{"itemId":"44988f14-0717-5542-bc9a-e6dd865ca6e0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cb5a82a4-5881-59af-8e90-838313b1456d","sourceKey":"bank:LAG-BUA111:CON-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements is NOT true of the societal marketing concept?","options":["It requires the firm to give up profit in favour of social welfare","It questions whether the pure marketing concept overlooks conflicts between short-run wants and long-run welfare","It considers the long-run interests of society","It asks the firm to balance company profits, consumer wants and society's interests"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept does not ask firms to abandon profit; it asks them to balance profit with consumer wants and society's interests. Options C, B and D are all accurate descriptions of the concept."}},{"itemId":"06e2774b-1e36-5312-9ff9-9242273e67ad","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9db7892e-6858-50cf-a675-9ad805ed560a","sourceKey":"bank:LAG-BUA111:CON-050","parentItemId":null,"revision":1,"payload":{"prompt":"The main danger of a firm following the production concept is that it may:","options":["Spend too much money on market research","Become so focused on its own operations and efficiency that it loses sight of satisfying customers' needs","Customise its products too much for individual buyers","Neglect profit in order to pursue social causes"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept can make managers inward-looking: they concentrate on output and cost and forget what customers actually need. Option A and option C are the opposite of production-concept behaviour, and option D has nothing to do with it."}},{"itemId":"8389fab0-50a3-53ad-a3d8-cb9d64b8902b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"58c61a5f-70d2-51d7-8bfd-0f7ad5ff5d66","sourceKey":"bank:LAG-BUA111:DIG-001","parentItemId":null,"revision":1,"payload":{"prompt":"The use of digital channels and technologies, such as websites, search engines, social media, email and mobile apps, to promote products and engage customers is broadly known as","options":["outdoor advertising","digital marketing","personal selling","trade promotion"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Digital marketing covers all marketing activities carried out through digital channels and devices. Option C is face-to-face selling by a sales force, Option A uses billboards and similar physical media, and Option D targets resellers with offers such as trade allowances."}},{"itemId":"85e6c81d-68e9-5277-9902-9bf8147c62b7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5b91f17f-93cd-5fff-84cf-1c274be54f01","sourceKey":"bank:LAG-BUA111:DIG-002","parentItemId":null,"revision":1,"payload":{"prompt":"E-marketing (internet marketing) is best described as","options":["marketing products and services over the internet, through websites, online ads, email and similar tools","selling products only through door-to-door salespeople","advertising only on radio and television","distributing printed catalogues by post"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"E-marketing refers to marketing activities conducted over the internet, such as company websites, online advertising and email. Option B is personal selling, Option C is traditional broadcast advertising, and Option D is traditional direct mail."}},{"itemId":"a6d65528-7515-55d9-92e7-41d1004e5a95","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d682b09b-b51d-56fb-9162-d06a4979e017","sourceKey":"bank:LAG-BUA111:DIG-003","parentItemId":null,"revision":1,"payload":{"prompt":"Using platforms such as Facebook, Instagram, TikTok, X (Twitter) and LinkedIn to build brand awareness, interact with customers and promote offers is called","options":["direct-mail marketing","trade marketing","social media marketing","telemarketing"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"Social media marketing uses social networking platforms to reach, engage and build relationships with customers. Option D uses telephone calls, Option B is aimed at wholesalers and retailers, and Option A sends printed offers to addresses."}},{"itemId":"cd6a268b-fcb7-5f14-af6e-b967e09b7718","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6fb36afe-bb40-5b85-88cf-6e2ac281a05b","sourceKey":"bank:LAG-BUA111:DIG-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of online advertising?","options":["A handbill distributed at a bus stop","A banner ad for a hotel appearing on a Nigerian news website","A jingle played on a market loudspeaker","A billboard on Third Mainland Bridge"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Online advertising is paid promotional content shown on the internet, such as display banners, search ads, social media ads and video ads. Option D, Option A and Option C are traditional offline promotion methods that do not use the internet."}},{"itemId":"d1271642-8bd5-5dc3-9058-e9f4d786ee56","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d1b6b9f1-8b9d-544a-9bce-44812b20390b","sourceKey":"bank:LAG-BUA111:DIG-005","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main difference between search engine optimisation (SEO) and pay-per-click (PPC) search advertising?","options":["SEO is only used on television, while PPC is used online","SEO and PPC both refer to sending bulk SMS messages","SEO aims to improve a website's free (organic) ranking in search results, while PPC buys sponsored listings and pays each time the ad is clicked","SEO is paid per click, while PPC is always free"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"SEO improves a site's content and structure so it ranks higher in unpaid (organic) results, while PPC places paid ads in search results and charges the advertiser per click. Option D reverses the two, and Option A and Option B describe neither technique."}},{"itemId":"e767bf80-fb86-51d1-afa4-d02bafb08ee0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"30a168fb-d14f-5f5a-9179-50b8b5acf05d","sourceKey":"bank:LAG-BUA111:DIG-006","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos online furniture store bids on keywords such as 'office chairs Lagos' so that its sponsored link appears at the top of search results, and it pays only when someone clicks the ad. This is","options":["pay-per-click (search) advertising","search engine optimisation","affiliate marketing","content marketing"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Pay-per-click search advertising lets advertisers bid on keywords and pay only when users click the ad. Option B improves unpaid rankings rather than buying ad space, Option C pays partners commission for sales they refer, and Option D attracts customers with useful free content."}},{"itemId":"707e00ce-ad94-57a4-9cb7-60fd3bc83e55","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f47f6f15-059b-576a-a206-90d31fe78cef","sourceKey":"bank:LAG-BUA111:DIG-007","parentItemId":null,"revision":1,"payload":{"prompt":"Creating and sharing valuable, relevant material such as blog posts, how-to videos and infographics, in order to attract and engage a clearly defined audience rather than directly pushing a sales message, is called","options":["content marketing","telemarketing","sales promotion","personal selling"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Content marketing earns attention by giving the audience useful or entertaining content, which builds trust and eventually sales. Option D is face-to-face persuasion, Option C is short-term incentives such as discounts, and Option B is selling over the phone."}},{"itemId":"9f380c6d-59d0-5616-bfb3-a1e5488dd6e6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"44e67c26-f4d0-5d06-a0d4-56d4e67f051e","sourceKey":"bank:LAG-BUA111:DIG-008","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian skincare brand publishes free weekly videos on how to care for skin in hot, humid weather, without directly asking viewers to buy. The brand is mainly using","options":["content marketing","personal selling","trade promotion","price discounting"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Providing helpful, relevant content to attract and keep an audience is content marketing. Option D is a price tactic, Option B involves salespeople meeting customers, and Option C targets wholesalers and retailers rather than consumers."}},{"itemId":"8c2a2aae-8d6f-5a73-b98a-12cb905196ad","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"48129fbb-dec1-5ba2-a2d2-dba46d066048","sourceKey":"bank:LAG-BUA111:DIG-009","parentItemId":null,"revision":1,"payload":{"prompt":"Partnering with individuals who have a large or highly engaged online following, such as content creators and celebrities, so that they recommend a brand to their followers is called","options":["direct-mail marketing","telemarketing","exhibition marketing","influencer marketing"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Influencer marketing uses people whose opinions their followers trust to promote a brand. Option B uses phone calls, Option A uses printed mail, and Option C uses trade fairs and exhibitions."}},{"itemId":"a1ad3867-7d47-5e88-8918-0d447b2108e3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ceb11bce-d8e8-5781-a0de-ad14d8b89727","sourceKey":"bank:LAG-BUA111:DIG-010","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with celebrity or 'mega' influencers, micro-influencers are generally described as having","options":["no followers at all, since they only use paid ads","the largest possible audiences across many unrelated interests","audiences made up only of business buyers","smaller, more focused audiences that often show higher engagement and trust"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Micro-influencers have smaller followings, often within a specific niche, and their followers tend to engage more and trust them more. Option B describes mega or celebrity influencers. Option A and Option C do not describe influencers at all."}},{"itemId":"5ce09f5e-65cf-5113-a616-1b7f97cfaf4a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0f5ebc4c-781a-54df-8d80-42bf2dbee32f","sourceKey":"bank:LAG-BUA111:DIG-011","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing messages, promotions and other content delivered to consumers through their mobile phones, such as SMS, in-app ads and mobile websites, is called","options":["trade marketing","catalogue marketing","outdoor marketing","mobile marketing"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Mobile marketing reaches consumers on their mobile devices through text messages, apps, mobile ads and mobile web. Option C uses billboards and posters, Option B uses printed catalogues, and Option A targets resellers."}},{"itemId":"56e1da6e-25d7-52c9-a973-1f7e19c15323","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dc804542-edab-579d-bd6c-76b8f0845461","sourceKey":"bank:LAG-BUA111:DIG-012","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian supermarket sends text messages to customers' phones announcing a weekend discount, to customers who gave their numbers at checkout. This is an example of","options":["billboard advertising","SMS (mobile) marketing","personal selling","public relations"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Sending promotional text messages to customers' phones is SMS marketing, a form of mobile marketing. Option A is outdoor advertising, Option C involves a salesperson interacting with the buyer, and Option D builds goodwill and manages publicity rather than sending direct offers."}},{"itemId":"ea70e312-d28c-5cf0-8bca-f2459e559283","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ff0c5f03-5172-5e73-8475-4c8fea09468f","sourceKey":"bank:LAG-BUA111:DIG-013","parentItemId":null,"revision":1,"payload":{"prompt":"A restaurant in Ikeja sends a discount offer to customers' phones only when their app shows they are within 1 kilometre of the restaurant. This technique is known as","options":["trade promotion","direct-mail marketing","location-based (geo-targeted) mobile marketing","search engine optimisation"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"Location-based mobile marketing uses the phone's location to send relevant offers to people nearby. Option D improves website rankings in search results, Option A targets resellers, and Option B uses physical mail rather than real-time phone location."}},{"itemId":"6366127d-21f4-564c-86f0-894e3cb9c781","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4700e4c7-ee9a-5058-a041-b382fab9eb9c","sourceKey":"bank:LAG-BUA111:DIG-014","parentItemId":null,"revision":1,"payload":{"prompt":"Sending marketing messages only to consumers who have agreed (opted in) to receive them, for example by subscribing to a newsletter, is known as","options":["guerrilla marketing","permission-based marketing","cold calling","spam"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Permission-based marketing sends messages only to people who have opted in, which improves relevance and trust. Option D is unsolicited and unwanted commercial messaging, the opposite of permission. Option A uses unconventional low-cost tactics, and Option C means contacting people who have not asked to be contacted."}},{"itemId":"c9caeda7-4e53-5d96-aa71-24c18cc62e93","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9f583dc9-8c61-5855-9188-55a3e98b8783","sourceKey":"bank:LAG-BUA111:DIG-015","parentItemId":null,"revision":1,"payload":{"prompt":"Unsolicited, unwanted commercial email messages sent in bulk to people who did not ask for them are commonly called","options":["user-generated content","content marketing","earned media","spam"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Spam is unwanted bulk commercial messaging; it annoys recipients and can damage a brand's reputation. Option B is valuable content that attracts an audience, Option C is free publicity or sharing by others, and Option A is content created by customers themselves."}},{"itemId":"8f874fcd-b254-5ee4-b091-5f4058072688","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e2c21817-a42f-5fb5-bb06-7c162cf75fcf","sourceKey":"bank:LAG-BUA111:DIG-016","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing message designed to be so entertaining or useful that people pass it on to friends rapidly online, the digital version of word-of-mouth, is called","options":["trade promotion","sales quota setting","telemarketing","viral marketing"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Viral marketing creates content that people want to share, so it spreads quickly from person to person at low cost. Option A targets resellers, Option B sets sales targets for a sales force, and Option C uses telephone calls."}},{"itemId":"7998f3a3-9d8f-5081-97c9-dc8025fcafd4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b282dd5a-a6ee-5f35-a32c-e5fa60c59538","sourceKey":"bank:LAG-BUA111:DIG-017","parentItemId":null,"revision":1,"payload":{"prompt":"Photos, videos, reviews and posts about a brand that are created and shared by customers rather than by the company itself are called","options":["owned media","user-generated content","paid media","point-of-sale materials"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"User-generated content (UGC) is brand-related content produced by consumers, such as reviews or unboxing videos. Option A is created and controlled by the firm, Option C is space the firm pays for, and Option D are displays prepared by the firm for stores."}},{"itemId":"d2a4f4bc-b491-5c32-80a7-7ced26951c70","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"856d3610-0445-5254-bf8f-004ecfd2b670","sourceKey":"bank:LAG-BUA111:DIG-018","parentItemId":null,"revision":1,"payload":{"prompt":"A brand's own website, Instagram page and company blog are classified as which type of media?","options":["Paid media","Owned media","Broadcast media","Earned media"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Owned media are channels the company itself controls, such as its website and official social pages. Option A is space the brand buys, such as sponsored posts, Option D is free coverage or sharing generated by others, and Option C refers to radio and television."}},{"itemId":"48142690-b5cb-5074-9336-6e8505511e31","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4c0c54d7-1f53-5400-9aa5-bad453105f3d","sourceKey":"bank:LAG-BUA111:DIG-019","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian food blogger, without being paid, posts a glowing review of a new Lekki restaurant, and thousands of people share it. For the restaurant, this exposure is","options":["sales promotion","owned media","paid media","earned media"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Earned media is publicity the brand did not pay for or create, such as unpaid reviews, shares and mentions. Option C would require the restaurant to pay for the placement, Option B is the restaurant's own channels, and Option A is a short-term incentive such as a discount."}},{"itemId":"b4171fc8-b81f-5c37-93a0-ba53e7b30027","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c4f7b1b1-d14f-52f5-8b5f-fe645c3a3248","sourceKey":"bank:LAG-BUA111:DIG-020","parentItemId":null,"revision":1,"payload":{"prompt":"A fashion brand pays to 'boost' (sponsor) its Instagram post so that it appears in the feeds of 50,000 targeted users. This is an example of","options":["user-generated content","earned media","paid media","owned media"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"Paid media is exposure the brand buys, such as sponsored or boosted posts and online ads. Option B is free exposure from others, Option D is the brand's own channels without paying for extra reach, and Option A is content created by customers."}},{"itemId":"7a96bb6d-e226-55f4-a8d8-7e22b8c4b065","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b855a009-f10a-5ed5-a5f8-d3891f7704ca","sourceKey":"bank:LAG-BUA111:DIG-021","parentItemId":null,"revision":1,"payload":{"prompt":"Positive or negative comments about products and brands that consumers share with each other through reviews, social media posts and online forums are called","options":["personal selling","electronic word-of-mouth (eWOM)","trade allowances","sales quotas"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Electronic word-of-mouth is consumer-to-consumer talk about brands that takes place online and can spread very widely. Option A is selling by a firm's sales force, Option C is incentives given to resellers, and Option D are sales targets."}},{"itemId":"06fc6e7b-ce51-5484-bb41-30d09acff964","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f1207b0f-640a-5a05-8810-01c051b9c4fe","sourceKey":"bank:LAG-BUA111:DIG-022","parentItemId":null,"revision":1,"payload":{"prompt":"A business pays a commission to bloggers or website owners for each sale made through a special link or code they share with their audience. This is","options":["search engine optimisation","public relations","affiliate marketing","outdoor advertising"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"In affiliate marketing, partners promote a firm's products and earn a commission on each sale traced to their links or codes. Option A improves organic search rankings, Option B manages publicity and goodwill, and Option D uses billboards and posters."}},{"itemId":"f194853d-8d6d-523d-8002-cd24515c1427","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"86fda1cc-a465-57f8-86c5-68a5ee95e4f1","sourceKey":"bank:LAG-BUA111:DIG-023","parentItemId":null,"revision":1,"payload":{"prompt":"A student browses a laptop on an online store but leaves without buying. Over the next few days, ads for that same laptop keep appearing on other websites and social media she visits. This tactic is called","options":["personal selling","market testing","retargeting (remarketing)","viral marketing"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"Retargeting shows ads to people who have already visited a website or viewed a product, reminding them to return. Option D relies on people sharing content voluntarily, Option B is a forecasting method using a test area, and Option A involves direct contact with a salesperson."}},{"itemId":"01640b38-49c2-5535-bd2e-9a89d7c7f2b1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"02e7162e-9895-549c-8cfb-acdbf12e24de","sourceKey":"bank:LAG-BUA111:DIG-024","parentItemId":null,"revision":1,"payload":{"prompt":"Buying and selling directly within social media platforms, for example a vendor displaying products in a WhatsApp Business catalogue and taking orders in the chat, is known as","options":["social commerce","telemarketing","industrial marketing","trade marketing"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Social commerce is the use of social networks to sell products, so discovery, conversation and ordering all happen on the platform. Option D targets resellers, Option B uses phone calls, and Option C refers to selling to businesses rather than a selling method on social platforms."}},{"itemId":"536802b8-7a32-5993-a6a1-c086429e3b99","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0f333a0b-38dc-5973-9129-2a067685b72d","sourceKey":"bank:LAG-BUA111:DIG-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which feature most clearly distinguishes social media marketing from traditional mass-media advertising such as newspaper ads?","options":["Two-way, interactive communication in which customers can reply, comment and share","Results that cannot be measured at all","One-way communication with no customer response","Messages that can never be targeted to particular groups"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Social media allows a conversation: customers can respond, comment, share and even create content, and brands can reply in real time. Option C describes traditional mass media. Option D and Option B are wrong because social media allows precise targeting and detailed measurement."}},{"itemId":"257965fb-d52d-5bad-9005-15d6a92fe821","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c2daa820-4475-514b-a046-b642a5abf908","sourceKey":"bank:LAG-BUA111:DIG-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key ADVANTAGE of digital marketing over most traditional media?","options":["It does not allow any targeting by interest or age","Results such as clicks, views and sales can be measured precisely and quickly","Every customer must visit a physical shop to see the message","It can only reach people in one location"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Digital channels track impressions, clicks, conversions and costs in near real time, so marketers can measure performance and adjust campaigns. Option C, Option D and Option A are limitations that digital marketing actually overcomes through online reach and precise targeting."}},{"itemId":"6fcf90b3-1a46-5538-ac3c-f2a00b190402","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5821bb44-6713-5217-a4e6-4202e1a85842","sourceKey":"bank:LAG-BUA111:DIG-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of digital and social media marketing for a small business in Nigeria?","options":["It guarantees that no customer will ever post a negative comment","It allows targeting by location, age and interests","It allows quick, two-way interaction with customers","It can reach many customers at relatively low cost"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Digital marketing does not protect a business from negative comments; in fact, criticism can spread quickly online, which is one of its challenges. Option D, Option B and Option C are genuine advantages: low cost, precise targeting and interactivity."}},{"itemId":"6315a503-d887-5135-b9a5-d25008841a57","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0d1db33f-12c5-507e-9c01-d71e96be9e86","sourceKey":"bank:LAG-BUA111:DIG-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a major CHALLENGE of digital marketing in Nigeria?","options":["Online results can never be measured","Digital ads can never be targeted to particular groups","No Nigerians use mobile phones","The cost of mobile data and unreliable power supply can limit how often some customers go online"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"The cost of internet data, uneven network coverage and unreliable electricity can limit how often some consumers are online, which reduces the reach of digital campaigns. Option B and Option A are false because digital ads are targetable and measurable, and Option C is plainly untrue given widespread mobile phone use."}},{"itemId":"a56a6d31-5736-5f7a-ac78-ba92d477de8b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c403e9ab-0dd8-5796-b2b3-9be072777e69","sourceKey":"bank:LAG-BUA111:DIG-029","parentItemId":null,"revision":1,"payload":{"prompt":"Why is online fraud and lack of trust considered a challenge for e-marketing in Nigeria?","options":["It makes internet advertising completely free","Some consumers fear being scammed and hesitate to pay online or share personal details, which slows online sales","It increases the number of honest online buyers","It forces every business to stop using social media"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Fear of scams, fake vendors and misuse of personal data can make consumers reluctant to buy or pay online, so businesses must work to build trust, for example with pay-on-delivery and secure payment options. Option A, Option C and Option D do not describe genuine effects of online fraud."}},{"itemId":"b05fdef5-f3cc-59bb-a070-d6ef68fb1ac3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"78698ce8-9188-5e95-888f-b6869d207c75","sourceKey":"bank:LAG-BUA111:DIG-030","parentItemId":null,"revision":1,"payload":{"prompt":"A customer posts a video complaint about a Lagos bakery's spoiled cake, and within hours it is shared thousands of times. This illustrates which challenge of social media marketing?","options":["Social media cannot reach young people","Social media communication is strictly one-way","Negative messages can spread quickly and are difficult for the firm to control","Social media posts cannot be shared"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"On social media, consumers control much of the conversation, and a single complaint can spread rapidly and damage a brand's reputation, so firms need to monitor and respond quickly. Option A, Option B and Option D are false: social media reaches young people, is two-way, and is built for sharing."}},{"itemId":"eddca17b-b335-5361-aa69-74995b1e70e3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"065dbf38-0fa6-53c6-a07e-176184c47bcc","sourceKey":"bank:LAG-BUA111:DIG-031","parentItemId":null,"revision":1,"payload":{"prompt":"Seeing very many ads online can cause some consumers to install ad blockers or simply ignore banner ads. This problem is best described as","options":["price discrimination","market segmentation","ad clutter and ad avoidance","personal selling"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"When consumers are exposed to too many ads, they tune them out or block them, which reduces the effectiveness of online advertising. Option B is dividing a market into groups, Option D is face-to-face selling, and Option A is charging different prices to different buyers."}},{"itemId":"6e188f8a-dbc0-5ce7-b8c9-f413d6ab2fa1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4c08ce8c-5656-585e-a76b-328bc78fc16d","sourceKey":"bank:LAG-BUA111:DIG-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best compares digital marketing with traditional marketing?","options":["Digital marketing reaches fewer people than traditional marketing in every case","Traditional marketing allows customers to comment and share instantly, while digital marketing does not","There is no difference between them in targeting or measurement","Digital marketing allows more precise targeting, real-time measurement and interaction, while traditional marketing relies more on one-way mass media such as print, radio and TV"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Digital marketing is interactive, measurable and can be targeted at precise audiences, while traditional media mostly broadcast one message to a mass audience. Option A is not always true, Option B reverses the two, and Option C ignores the clear differences."}},{"itemId":"cb9b46ab-0451-5fcb-912f-90aecb5ce8ef","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f94fd13d-9cc9-5058-9cb1-0ef57ea4d233","sourceKey":"bank:LAG-BUA111:DIG-033","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian telecoms brand creates a branded hashtag and invites customers to post short dance videos using it, with the best entries winning data bundles. The main aim of this activity is to","options":["generate engagement and user-generated content that spreads the brand message","reduce the brand's need for any customers","replace all of the brand's distribution channels","set sales quotas for the brand's salespeople"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"Hashtag challenges encourage customers to participate, create content and share it, increasing engagement and reach at relatively low cost. Option B, Option C and Option D are not purposes of a social media campaign."}},{"itemId":"38798391-3efb-5ad2-86c3-24d22d4f46f1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f5715636-8f56-5f50-9d00-0c8d8c886eef","sourceKey":"bank:LAG-BUA111:DIG-034","parentItemId":null,"revision":1,"payload":{"prompt":"An online banner ad for a Lagos hotel was shown 80,000 times (impressions) and clicked 1,200 times. Click-through rate (CTR) = clicks / impressions x 100. What is the CTR?","options":["66.67%","0.015%","1.5%","15%"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"CTR = 1,200 / 80,000 x 100 = 1.5%. Option B forgets to multiply by 100, Option A divides impressions by clicks, the wrong way round, and Option D multiplies by 1,000 instead of 100."}},{"itemId":"c25869e1-96bd-5d72-bd3c-cf0720646768","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e5aaa9fe-36f9-5ccb-8677-5b622717b43f","sourceKey":"bank:LAG-BUA111:DIG-035","parentItemId":null,"revision":1,"payload":{"prompt":"A brand pays N90,000 for an online display campaign that delivers 600,000 impressions. Cost per thousand impressions (CPM) = total cost / impressions x 1,000. What is the CPM?","options":["N6,666.67","N1,500","N150","N0.15"],"correctOption":2,"section":"Marketing in the Digital and Social Media Era","explanation":"CPM = N90,000 / 600,000 x 1,000 = N150. Option D is the cost per single impression (N0.15) because it forgets the x 1,000. Option B multiplies by 10,000 instead of 1,000, and Option A divides impressions by cost, the wrong way round."}},{"itemId":"8c04c3d2-005d-5c9f-9609-444753d182d7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d105543b-0492-5d0e-a471-7c5c8f1c0d3e","sourceKey":"bank:LAG-BUA111:DIG-036","parentItemId":null,"revision":1,"payload":{"prompt":"An online fashion store spent N75,000 on pay-per-click ads in a month and received 2,500 clicks. What was the average cost per click (CPC = total ad spend / number of clicks)?","options":["N30","N3,000","N0.033","N3"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"CPC = N75,000 / 2,500 = N30 per click. Option C divides clicks by spend, the wrong way round. Option B and Option D are place-value slips of 100 and 10."}},{"itemId":"0324ce9b-a044-5c03-8838-d82e2c05bfca","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4f794b76-b2e8-5b46-9641-083b4d350abc","sourceKey":"bank:LAG-BUA111:DIG-037","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian e-commerce page received 4,000 visitors from a social media campaign, and 120 of them placed an order. Conversion rate = orders / visitors x 100. What is the conversion rate?","options":["33.33%","0.03%","30%","3%"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Conversion rate = 120 / 4,000 x 100 = 3%. Option B forgets to multiply by 100, Option A divides the wrong way round, and Option C multiplies by 1,000 instead of 100."}},{"itemId":"4d097d1b-cb7a-5297-9255-018d25083e08","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e2684b7e-d710-5a98-a033-fc52369d5a74","sourceKey":"bank:LAG-BUA111:DIG-038","parentItemId":null,"revision":1,"payload":{"prompt":"An influencer with 25,000 followers posts a sponsored video that receives 900 likes, 250 comments and 350 shares. If engagement rate = (likes + comments + shares) / followers x 100, what is the engagement rate?","options":["16.67%","6%","0.06%","3.6%"],"correctOption":1,"section":"Marketing in the Digital and Social Media Era","explanation":"Total engagements = 900 + 250 + 350 = 1,500, so engagement rate = 1,500 / 25,000 x 100 = 6%. Option D counts only likes, Option C forgets to multiply by 100, and Option A divides the wrong way round."}},{"itemId":"62220c58-ce00-55e9-af2f-262201317d2b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"360b787d-7b9a-50c6-9f41-a37c3dd90380","sourceKey":"bank:LAG-BUA111:DIG-039","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos cosmetics seller spent N400,000 on Instagram ads and traced N1,800,000 of sales revenue to those ads. Return on ad spend (ROAS) = revenue from ads / ad spend. What is the ROAS?","options":["4.5","3.5","0.22","450"],"correctOption":0,"section":"Marketing in the Digital and Social Media Era","explanation":"ROAS = N1,800,000 / N400,000 = 4.5, meaning each N1 of advertising brought in N4.50 of sales. Option C divides the wrong way round, Option B subtracts the ad spend first, which is the profit-style return rather than ROAS as defined, and Option D wrongly multiplies by 100."}},{"itemId":"12b9470a-16aa-5676-99a7-79282ab6a01f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f2fee89c-6d00-5e4c-af33-9e92c5769a51","sourceKey":"bank:LAG-BUA111:DIG-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a form of digital marketing?","options":["Running a sponsored Instagram post","Optimising a website to rank higher on search engines","Sending an email newsletter to subscribers","Painting a shop's name and products on a roadside wall"],"correctOption":3,"section":"Marketing in the Digital and Social Media Era","explanation":"Painting a roadside wall is traditional outdoor promotion and uses no digital channel. Option C is email marketing, Option A is paid social media advertising, and Option B is search engine optimisation, all of which are forms of digital marketing."}},{"itemId":"80b7b406-54ed-5f9a-9768-8fcf553671a9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"677e07c8-42bd-56e4-95f3-723e86db4ceb","sourceKey":"bank:LAG-BUA111:ENV-001","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing environment is best defined as:","options":["Only the government agencies that regulate marketing in a country","Only the firm's customers and competitors","All the internal and external factors that directly or indirectly influence an organisation's decisions on its marketing activities","The physical office where the marketing department works"],"correctOption":2,"section":"Marketing Environment","explanation":"The marketing environment covers every internal and external factor that directly or indirectly affects marketing decisions. Options A and B each pick out just one part of that environment. Option D takes 'environment' to mean a physical place."}},{"itemId":"28eb731a-d274-5364-b891-3172b5954c13","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1976ffea-9dc4-528c-992b-3ac6fbf615a5","sourceKey":"bank:LAG-BUA111:ENV-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about internal and external factors in the marketing environment is correct?","options":["Internal factors are within the organisation's control, while external factors are not","Neither internal nor external factors can be influenced by the organisation","External factors are within the organisation's control, while internal factors are not","Both internal and external factors are fully within the organisation's control"],"correctOption":0,"section":"Marketing Environment","explanation":"A firm can manage its own strengths, weaknesses and competencies (internal factors), but it cannot control forces such as government, technology or the economy (external factors). Option C reverses this. Options D and B ignore the difference between the two groups."}},{"itemId":"70768d61-41f7-54a2-bb8d-d7ad056d7531","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0809f3eb-0caf-5bd8-ba24-b61f443358a1","sourceKey":"bank:LAG-BUA111:ENV-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an INTERNAL factor in an organisation's marketing environment?","options":["Government policy","Technological change","Competitors' actions","The firm's own marketing competencies"],"correctOption":3,"section":"Marketing Environment","explanation":"The organisation's strengths, weaknesses and competencies are internal factors because they are within its control. Options A, B and C are external factors: government, technological and competitive forces lie outside the firm's control."}},{"itemId":"2fdf3290-ff77-522e-8342-e14617c0082f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"19b34f17-58a8-5dc2-82d6-a5d2ac0909b8","sourceKey":"bank:LAG-BUA111:ENV-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a feature of the marketing environment?","options":["Stability","Uncertainty","Complexity","Vibrancy"],"correctOption":0,"section":"Marketing Environment","explanation":"The marketing environment does not stay stable; it keeps changing over time. Options C, D and B are genuine features: it is made up of many interacting factors (complexity), it is dynamic (vibrancy), and it is hard to predict (uncertainty)."}},{"itemId":"2ecf9a13-c9b1-5f73-9f62-659469c558c0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6289da73-9221-5805-ac65-b0fc06b91dbb","sourceKey":"bank:LAG-BUA111:ENV-005","parentItemId":null,"revision":1,"payload":{"prompt":"Forces in the marketing environment that DIRECTLY affect the activities of an organisation, such as customers and investors, are called:","options":["General forces","Relative forces","Specific forces","Vibrant forces"],"correctOption":2,"section":"Marketing Environment","explanation":"Specific forces are those that act directly on the organisation, for example customers and investors. Option A refers to forces that act indirectly, such as social, political, legal and technological factors. Options B and D borrow the names of other features and are not types of force."}},{"itemId":"4870e81a-6fad-5a15-8f94-83ce20167a06","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1a593cbb-97f9-5d7e-afc0-ebfefed7b8b3","sourceKey":"bank:LAG-BUA111:ENV-006","parentItemId":null,"revision":1,"payload":{"prompt":"The feature of the marketing environment that arises from the interaction among its many factors, conditions and influences is:","options":["Relativity","Complexity","Uncertainty","Vibrancy"],"correctOption":1,"section":"Marketing Environment","explanation":"Complexity means the environment contains many factors, conditions and influences, and their interaction makes it complicated. Option A is about demand varying between countries or cultures, option D about the environment changing over time, and option C about forces being unpredictable."}},{"itemId":"73080625-4165-577f-b954-5d3c2bc7dd62","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"053e2b31-7f98-50b1-b8cc-93b2bd9df6a0","sourceKey":"bank:LAG-BUA111:ENV-007","parentItemId":null,"revision":1,"payload":{"prompt":"As a feature of the marketing environment, 'vibrancy' means that the environment:","options":["Produces different levels of demand in different countries","Contains forces that act directly on the firm","Is made up of many interacting factors","Is dynamic and keeps changing over time"],"correctOption":3,"section":"Marketing Environment","explanation":"Vibrancy refers to the dynamic nature of the environment: its many forces do not stay stable but change over time, and firms that understand this can gain an edge over competitors. Option A describes relativity, option C complexity, and option B specific forces."}},{"itemId":"c1d28283-0c2b-5c87-a2e4-8cbbfe692d03","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ca73a503-0786-543b-b346-83e253e84ddb","sourceKey":"bank:LAG-BUA111:ENV-008","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fashion house finds that a style of ankara gown sells out one month and is ignored the next, so it is very hard to predict what customers will want. Which feature of the marketing environment does this illustrate?","options":["Complexity","Uncertainty","Relativity","Specific forces"],"correctOption":1,"section":"Marketing Environment","explanation":"Uncertainty means market forces are unpredictable; fast-changing fashion tastes are the classic example. Option C concerns demand differing between countries or cultures, option A the interaction of many factors, and option D forces that act directly on the firm."}},{"itemId":"01ab293c-f5c3-5fb8-b4c7-76143aa75346","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"48f8c448-5832-54f6-a6ab-e110a6bde4e5","sourceKey":"bank:LAG-BUA111:ENV-009","parentItemId":null,"revision":1,"payload":{"prompt":"Aso-oke caps are in steady demand in south-west Nigeria because they are part of traditional dress, but in many foreign countries their demand is almost zero. Which feature of the marketing environment does this illustrate?","options":["Complexity","Relativity","Vibrancy","Uncertainty"],"correctOption":1,"section":"Marketing Environment","explanation":"Relativity explains why demand for a product differs between countries, regions and cultures, just as traditional dress sells in one culture and not in another. Option D is about unpredictability over time, option C about constant change, and option A about many interacting factors."}},{"itemId":"03fac06c-3484-5333-94dc-8871688c6117","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"169fbda1-5572-5eac-85ce-9fc350c654cf","sourceKey":"bank:LAG-BUA111:ENV-010","parentItemId":null,"revision":1,"payload":{"prompt":"The two main types into which the marketing environment is usually divided are the:","options":["Physical environment and digital environment","Primary environment and secondary environment","Micro environment and macro environment","Local environment and foreign environment"],"correctOption":2,"section":"Marketing Environment","explanation":"The marketing environment is mostly divided into the micro environment, the forces close to the firm, and the macro environment, the broad forces beyond its control. Options D, B and A are not the standard classification of the marketing environment."}},{"itemId":"927ed397-8fb2-5df0-922e-dee04582650b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b2008580-bf73-51c1-afa5-5196a3625b35","sourceKey":"bank:LAG-BUA111:ENV-011","parentItemId":null,"revision":1,"payload":{"prompt":"The micro environment of an organisation refers to the environment that:","options":["Is closely linked to the organisation and directly affects its activities","Consists of broad societal forces such as population and technology","Refers only to the global economy","Consists only of the firm's own internal departments"],"correctOption":0,"section":"Marketing Environment","explanation":"The micro environment is made up of forces closely linked to the firm, such as suppliers, intermediaries, customers and competitors, that directly affect its activities. Option B describes the macro environment. Option D is too narrow, and option C is a macro-economic force."}},{"itemId":"f1d63ce8-f1e3-56fb-89a9-cb219a90ad2d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"59b7078e-f5e0-5f07-b8b1-3f5224c74a1f","sourceKey":"bank:LAG-BUA111:ENV-012","parentItemId":null,"revision":1,"payload":{"prompt":"The micro environment can be divided into a supply side and a demand side. Which of the following belongs to the DEMAND side?","options":["Customers","Marketing intermediaries","Suppliers","Competitors"],"correctOption":0,"section":"Marketing Environment","explanation":"The demand side of the micro environment is made up of customers, who consume the products. Suppliers, marketing intermediaries and competitors, options C, B and D, are grouped on the supply side."}},{"itemId":"f04a4326-c013-5c3c-9587-5304ea6e61ec","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"81faf3bc-49f3-507b-924f-88245ba8953f","sourceKey":"bank:LAG-BUA111:ENV-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a force in the micro environment?","options":["Suppliers","Competitors","Marketing intermediaries","The demographic environment"],"correctOption":3,"section":"Marketing Environment","explanation":"The demographic environment, the make-up of the population, is part of the macro environment. Options A, C and B are micro-environment forces because they are closely linked to the firm and affect it directly."}},{"itemId":"43acaa04-3210-569d-91b5-6ade089bfb02","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b376ca44-6cc5-5006-9ae5-08b82363c1de","sourceKey":"bank:LAG-BUA111:ENV-014","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery is told by the miller who sells it flour that the price per bag is going up by 30%, forcing the bakery to raise the price of its bread. Which micro-environment force is directly involved?","options":["Marketing intermediaries","Customers","Suppliers","Competitors"],"correctOption":2,"section":"Marketing Environment","explanation":"Suppliers provide the raw materials, and because input prices feed into the final product price, they can affect a firm's profit. Option A refers to those who help the firm reach customers, option D to rival firms, and option B to buyers of the bread."}},{"itemId":"d7c88e3a-bc27-595d-89c6-27367d2e6c7a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9d12606c-3144-534f-b071-b85e9c88324c","sourceKey":"bank:LAG-BUA111:ENV-015","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing intermediaries help an organisation mainly by:","options":["Supplying the raw materials it needs for production","Making the laws that regulate its marketing","Studying the size and structure of the population","Linking it with customers through promoting, selling and distributing its products"],"correctOption":3,"section":"Marketing Environment","explanation":"Marketing intermediaries connect the firm with its customers and help it promote, sell and distribute its products. Option A is the role of suppliers, option B belongs to the political-legal environment, and option C is the demographic environment."}},{"itemId":"da4376b4-c791-5d33-8468-98a29b87c5cb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"13d03c16-e864-5543-abc5-f2f694f58483","sourceKey":"bank:LAG-BUA111:ENV-016","parentItemId":null,"revision":1,"payload":{"prompt":"Wholesalers and retailers that buy products from a manufacturer and sell them to customers are which type of marketing intermediary?","options":["Resellers","Distribution centres","Marketing agencies","Financial intermediaries"],"correctOption":0,"section":"Marketing Environment","explanation":"Resellers buy from the organisation and resell to customers; wholesalers and retailers are the examples. Option B stores goods, option C promotes products, and option D provides finance for transactions."}},{"itemId":"9fa92277-825e-5b54-ad52-6295203308e7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9d96be92-a76b-5fbb-b0c1-f191252e864a","sourceKey":"bank:LAG-BUA111:ENV-017","parentItemId":null,"revision":1,"payload":{"prompt":"A warehouse company in Kano stores a beverage maker's cartons until they are sent out to retailers across the North. Which type of marketing intermediary is the warehouse company?","options":["Financial intermediary","Distribution centre","Reseller","Marketing agency"],"correctOption":1,"section":"Marketing Environment","explanation":"A distribution centre helps the firm store its goods, and a warehouse is the typical example. Option C would buy and resell the drinks, option D would promote them, and option A would finance the transactions."}},{"itemId":"a2ef9371-4215-5bca-9584-20f24e25ca2d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7b3c3571-b3d9-5fa2-aa9b-a313f3ee3352","sourceKey":"bank:LAG-BUA111:ENV-018","parentItemId":null,"revision":1,"payload":{"prompt":"An Ikeja advertising agency creates radio jingles and billboards that tell consumers about the benefits of a new brand of detergent. Which type of marketing intermediary is the agency?","options":["Distribution centre","Reseller","Marketing agency","Financial intermediary"],"correctOption":2,"section":"Marketing Environment","explanation":"A marketing agency promotes the firm's products by making customers aware of their benefits; an advertising agency is the standard example. Option B buys and resells, option A stores goods, and option D provides finance or insurance."}},{"itemId":"d76653b8-5b64-5cc8-bd88-70754309a860","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"12c4e1dd-dc80-5805-a1c4-09b240cb4f02","sourceKey":"bank:LAG-BUA111:ENV-019","parentItemId":null,"revision":1,"payload":{"prompt":"Banks, credit organisations and insurance companies that provide finance for, or insure, an organisation's business transactions are classed as:","options":["Financial intermediaries","Distribution centres","Resellers","Marketing agencies"],"correctOption":0,"section":"Marketing Environment","explanation":"Financial intermediaries provide finance for business transactions, and banks, credit organisations and insurers are the examples. Option C buys and resells products, option D promotes them, and option B stores them."}},{"itemId":"54aa395a-1542-52f7-a26b-44dbbce941f6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"06b2c31f-d716-5a2b-ad28-23ef084ad2a3","sourceKey":"bank:LAG-BUA111:ENV-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the types of marketing intermediaries?","options":["Financial intermediaries","Resellers","Distribution centres","Raw-material suppliers"],"correctOption":3,"section":"Marketing Environment","explanation":"Suppliers of raw inputs are a separate micro-environment force; they provide inputs rather than helping the firm reach customers. Options B, C and A, together with marketing agencies, are the types of marketing intermediaries."}},{"itemId":"1b99cc1a-5fe9-5bf1-b1e8-b3f257da8a66","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f53767aa-cdd1-5c26-b54f-82ddb6d6ce5a","sourceKey":"bank:LAG-BUA111:ENV-021","parentItemId":null,"revision":1,"payload":{"prompt":"In the micro environment, customers are best described as those who:","options":["Store the products before they are distributed","Provide the raw materials used to make the products","Buy the organisation's products for final consumption, and whose satisfaction is the organisation's main goal","Offer similar products and compete for market share"],"correctOption":2,"section":"Marketing Environment","explanation":"Customers buy the products for final consumption, and satisfying them is the main goal, which is why firms carry out research to understand their needs. Option B describes suppliers, option D competitors, and option A distribution centres."}},{"itemId":"5eec83a6-c6f3-522e-ab70-1d1c8ce85571","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ceb2de0d-61fa-547f-bb1f-f494bc42063a","sourceKey":"bank:LAG-BUA111:ENV-022","parentItemId":null,"revision":1,"payload":{"prompt":"A situation in which various organisations offer similar products and try to gain market share by adopting different marketing strategies is called:","options":["Segmentation","Competition","Intermediation","Integration"],"correctOption":1,"section":"Marketing Environment","explanation":"Competition is the situation where several firms offer similar products and fight for market share with different strategies. Option A means dividing a market into groups, option C refers to the work of middlemen, and option D means combining activities or firms."}},{"itemId":"3dc712b6-da82-5660-9510-d9694c7f3e23","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"46d3e074-e7b2-5dcd-9c07-a6023afa3e7a","sourceKey":"bank:LAG-BUA111:ENV-023","parentItemId":null,"revision":1,"payload":{"prompt":"The presence of competitors in the micro environment benefits an organisation mainly by pushing it to:","options":["Differentiate its product in order to maintain its position in the market","Raise the prices of the raw materials it buys","Store more goods in warehouses","Reduce the amount of research it does on customers"],"correctOption":0,"section":"Marketing Environment","explanation":"Competitors push a firm to differentiate its product so that it can hold its market position. Option B confuses competitors with suppliers, option C with distribution centres, and option D is the opposite of what competition encourages."}},{"itemId":"d7ec46c9-d933-5960-9acd-962a6fb04e00","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2223600f-cb4f-5b81-8891-61404e5246a1","sourceKey":"bank:LAG-BUA111:ENV-024","parentItemId":null,"revision":1,"payload":{"prompt":"The macro environment is best described as:","options":["The internal strengths and weaknesses of the organisation","The firm's suppliers, intermediaries, customers and competitors","A stable set of factors that rarely change","A set of environmental factors beyond the organisation's control that influence its activities to a significant extent and are subject to constant change"],"correctOption":3,"section":"Marketing Environment","explanation":"The macro environment is made up of broad forces such as demographic, economic, natural, socio-cultural, technological and political-legal factors that the firm cannot control and that change constantly, bringing opportunities and threats. Option B lists micro-environment forces, option A internal factors, and option C contradicts its changing nature."}},{"itemId":"ef63b390-14bd-5aac-be30-3023ae1108ed","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"48a4fd52-843f-5d7b-a84e-ea609dd40224","sourceKey":"bank:LAG-BUA111:ENV-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a force in the macro environment?","options":["Marketing intermediaries","The demographic environment","The technological environment","The natural environment"],"correctOption":0,"section":"Marketing Environment","explanation":"Marketing intermediaries are a micro-environment force because they are closely linked to the firm. Options B, D and C are macro forces, together with the economic, socio-cultural and political-legal environments."}},{"itemId":"b26614a8-0f03-5d7a-a060-145f340e8512","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f34e11ce-faea-5614-bb82-370fe438fded","sourceKey":"bank:LAG-BUA111:ENV-026","parentItemId":null,"revision":1,"payload":{"prompt":"The scientific study of human population in terms of elements such as age, gender, education, occupation, income and location describes which environment?","options":["Economic environment","Demographic environment","Natural environment","Socio-cultural environment"],"correctOption":1,"section":"Marketing Environment","explanation":"The demographic environment studies the population through demographic variables such as age, gender, education, occupation, income and location. Option D covers values, attitudes and behaviour. Option A covers costs and purchasing power, and option C covers resources, weather and pollution."}},{"itemId":"805428c7-7ac5-5a98-b1a6-b3a79a28bed9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ee662375-f2bf-577d-a6c7-f709fc98ec1d","sourceKey":"bank:LAG-BUA111:ENV-027","parentItemId":null,"revision":1,"payload":{"prompt":"A telecoms company notes that a very large and growing share of Nigeria's population is under 30 years of age, and so launches cheap data bundles aimed at students and young workers. Which macro-environment force is the firm responding to?","options":["Political-legal environment","Technological environment","Natural environment","Demographic environment"],"correctOption":3,"section":"Marketing Environment","explanation":"The age structure and growth of the population are demographic variables, so the firm is responding to the demographic environment. Option C concerns resources and weather, option A concerns laws and government agencies, and option B concerns new technology rather than who the customers are."}},{"itemId":"f4c89a40-cb70-5256-894c-2bc5893ed7e2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d4b44fd3-faeb-5ffa-919b-7467a0b2e2e9","sourceKey":"bank:LAG-BUA111:ENV-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which macro-environment force affects an organisation's cost structure and its customers' purchasing power?","options":["Socio-cultural environment","Economic environment","Demographic environment","Natural environment"],"correctOption":1,"section":"Marketing Environment","explanation":"The economic environment shapes both what it costs the firm to operate and how much customers can afford to buy. Option C is about the make-up of the population, option A about values and lifestyles, and option D about resources, weather and pollution."}},{"itemId":"b82971af-5e4e-5108-9833-b383edc1d852","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b6d31f8f-1cb6-57e0-8ba5-bda0f7a60bff","sourceKey":"bank:LAG-BUA111:ENV-029","parentItemId":null,"revision":1,"payload":{"prompt":"A customer's purchasing power depends on:","options":["Values, attitudes and perceptions","Weather conditions and natural resources","Current income, prices of products, savings and the availability of credit","Age, gender and level of education"],"correctOption":2,"section":"Marketing Environment","explanation":"Purchasing power is determined by current income, product prices, savings and how easily credit can be obtained. Option D lists demographic variables, option A socio-cultural forces, and option B natural factors."}},{"itemId":"4bfb099e-8733-5a37-b4ef-89db250a3f72","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e3cdae93-08b6-5d25-818f-552bc90aee44","sourceKey":"bank:LAG-BUA111:ENV-030","parentItemId":null,"revision":1,"payload":{"prompt":"After a sharp rise in the pump price of petrol and in general prices, a car dealer in Abuja notices that fewer people are buying cars. Which economic factor is mainly at work?","options":["Fiscal policy","Inflation","Unemployment","Interest rates"],"correctOption":1,"section":"Marketing Environment","explanation":"Rising prices change what customers can afford and so affect demand; higher petrol prices reducing demand for cars is the typical example of inflation at work. Option D concerns the cost of borrowing, option C concerns people losing their incomes, and option A concerns government spending and taxes, none of which the scenario mentions."}},{"itemId":"07e5a6b1-f4ea-5916-b7da-2253963bafc0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"803fd3f9-bca6-5c34-8f50-1c8e114677e7","sourceKey":"bank:LAG-BUA111:ENV-031","parentItemId":null,"revision":1,"payload":{"prompt":"A Nnewi auto-parts manufacturer's bank raises the interest charged on its loans from 20% to 28% per annum, so the firm postpones its planned factory expansion. Which economic factor is directly affecting the firm?","options":["Customer income","Unemployment","Interest rates","Inflation"],"correctOption":2,"section":"Marketing Environment","explanation":"Interest rates determine the cost of borrowing, and a rise can lead firms to cut back important activities such as expansion. Option D is about rising prices of goods, option B about people without income, and option A about how much buyers earn."}},{"itemId":"5b42c04c-a04c-5c47-b980-447d5f37f3e3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"668b2148-5ac6-5c27-aca4-d32a3e688422","sourceKey":"bank:LAG-BUA111:ENV-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes monetary policy from fiscal policy?","options":["Monetary policy controls interest rates and money supply; fiscal policy concerns government spending financed by revenue from taxes","Both monetary and fiscal policy are set by individual firms to control their own costs","Monetary policy regulates pollution, while fiscal policy regulates population growth","Monetary policy concerns government spending and taxation; fiscal policy controls interest rates and money supply"],"correctOption":0,"section":"Marketing Environment","explanation":"Monetary policy stabilises the economy by managing interest rates and the money supply, while fiscal policy deals with government spending and the taxes that pay for it. Option D swaps the two policies. Option B is wrong because these are government policies, and option C attaches them to unrelated areas."}},{"itemId":"cf787c40-0756-5fb7-8c57-821c34b376b9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9f7baa9a-faa0-52ac-a161-807bd014d3fe","sourceKey":"bank:LAG-BUA111:ENV-033","parentItemId":null,"revision":1,"payload":{"prompt":"The Federal Government raises the rate of a tax on goods and services and uses the extra revenue to spend more on road construction. This is an example of:","options":["Monetary policy","Customer income","Unemployment","Fiscal policy"],"correctOption":3,"section":"Marketing Environment","explanation":"Collecting taxes and deciding how the government spends them is fiscal policy. Option A would involve interest rates and money supply. Options C and B are other economic factors, not government policy tools."}},{"itemId":"a0d1dff1-f590-586a-b9c1-46c37ee03fc4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8690a5b8-9367-5cc3-b8de-bcf49a2cc1be","sourceKey":"bank:LAG-BUA111:ENV-034","parentItemId":null,"revision":1,"payload":{"prompt":"Rising unemployment in an economy affects marketers mainly because it:","options":["Raises the interest rate on business loans","Increases the supply of natural resources","Leaves many people without income, reducing their purchasing power","Changes the age structure of the population"],"correctOption":2,"section":"Marketing Environment","explanation":"Unemployment leads to a no-income state for those affected, which cuts their ability to buy. Option A describes interest rates, option B is unrelated to unemployment, and option D is a demographic change."}},{"itemId":"faa8effc-3d64-5d5a-ab57-0ccb8c2a1f7f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"61159828-5b7c-59dc-bde3-0bcd9b8b7fd5","sourceKey":"bank:LAG-BUA111:ENV-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a factor of the NATURAL environment that affects marketing activities?","options":["Interest rates","Weather","Age distribution of the population","Customer legislation"],"correctOption":1,"section":"Marketing Environment","explanation":"The natural environment covers natural resources, weather and pollution. Option A belongs to the economic environment, option D to the political-legal environment, and option C to the demographic environment."}},{"itemId":"1b40af36-d14d-5964-819b-f83f724b653e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"68c962af-0c66-573d-a191-b1e92ce2eaef","sourceKey":"bank:LAG-BUA111:ENV-036","parentItemId":null,"revision":1,"payload":{"prompt":"Worried about the depletion of a natural resource, a petroleum marketer runs advertisements urging the public to use less of its own fuel products. This practice is known as:","options":["Telemarketing","Synchromarketing","De-marketing","Remarketing"],"correctOption":2,"section":"Marketing Environment","explanation":"De-marketing means deliberately trying to reduce demand for one's own product, here to conserve a scarce natural resource. Option D means reviving demand for a product whose demand is falling, option A is selling by telephone, and option B means smoothing out irregular demand."}},{"itemId":"fdd8dd41-133c-5960-be7e-d51afdaabb6c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c4c54607-c318-59c0-931c-5d27c6cc7597","sourceKey":"bank:LAG-BUA111:ENV-037","parentItemId":null,"revision":1,"payload":{"prompt":"Every harmattan season, sales of body lotion, lip balm and petroleum jelly rise sharply in northern Nigeria. Which macro-environment force explains this pattern?","options":["Socio-cultural environment","Demographic environment","Natural environment","Technological environment"],"correctOption":2,"section":"Marketing Environment","explanation":"Weather is part of the natural environment, and seasons create opportunities by raising demand for products suited to the conditions. Option A concerns values and lifestyles, option B the make-up of the population, and option D new technology, none of which drives this seasonal pattern."}},{"itemId":"9d57b60f-6fab-5067-b74e-087758675f39","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c4e41c85-4cdd-5b11-87c2-e606a91070ba","sourceKey":"bank:LAG-BUA111:ENV-038","parentItemId":null,"revision":1,"payload":{"prompt":"Growing environmental damage from plastic waste blocking drains in Lagos leads a supermarket chain to replace plastic shopping bags with paper bags and to promote them as environment-friendly. The supermarket is mainly responding to which environment?","options":["Demographic environment","Natural environment","Economic environment","Technological environment"],"correctOption":1,"section":"Marketing Environment","explanation":"Pollution and environmental degradation are factors of the natural environment, and firms respond by promoting environment-friendly products such as paper or jute bags instead of plastic. Option D concerns new technology, option C costs and purchasing power, and option A the make-up of the population."}},{"itemId":"942b2a25-e4a6-5cc8-8410-0b1bd9aaf9bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ca6bbc4f-dfe7-5a90-b8b3-2cbf67f33556","sourceKey":"bank:LAG-BUA111:ENV-039","parentItemId":null,"revision":1,"payload":{"prompt":"The environment made up of forces such as a society's basic values, attitudes, perceptions and behaviour is the:","options":["Socio-cultural environment","Political-legal environment","Economic environment","Demographic environment"],"correctOption":0,"section":"Marketing Environment","explanation":"Socio-cultural forces are society's values, attitudes, perceptions and behaviour, and they shape which products and brands people prefer and when they buy. Option D measures population characteristics, option B covers laws and government agencies, and option C covers costs and purchasing power."}},{"itemId":"9937ff92-b8ed-5c34-9abe-df7fe9c39a8e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3e64655f-e723-5b6e-983a-8974b87aa7fe","sourceKey":"bank:LAG-BUA111:ENV-040","parentItemId":null,"revision":1,"payload":{"prompt":"As lifestyles change and both husbands and wives in many Lagos households now work full-time, families have less time for shopping. This has encouraged the growth of supermarkets and malls where everything can be bought under one roof. Which environment does this lifestyle change belong to?","options":["Technological environment","Political-legal environment","Natural environment","Socio-cultural environment"],"correctOption":3,"section":"Marketing Environment","explanation":"Changing lifestyles and attitudes about work and family time are socio-cultural forces, and one-stop shopping centres grew in response. Option C concerns resources and weather, option A concerns new technology, and option B concerns laws and government agencies."}},{"itemId":"176cf028-0705-549e-8ed2-0fa61dadfe52","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c615bf2d-7105-503d-a227-8bf7f00789d8","sourceKey":"bank:LAG-BUA111:ENV-041","parentItemId":null,"revision":1,"payload":{"prompt":"A very rapid pace of technological change mainly affects organisations by:","options":["Making products obsolete quickly, so that firms must modify their products frequently","Making product changes unnecessary","Reducing the need for research and development","Lowering the purchasing power of customers"],"correctOption":0,"section":"Marketing Environment","explanation":"Fast technological change leads to rapid product obsolescence, so firms must keep updating their products; slow change means constant modification is unnecessary. Option B describes a slow pace of change, option C is the opposite of what fast change demands, and option D is an economic effect."}},{"itemId":"e462fb87-d267-59a9-9c6e-1e27a59a8fbb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"28764186-3a06-5584-a7f5-18674a7c220b","sourceKey":"bank:LAG-BUA111:ENV-042","parentItemId":null,"revision":1,"payload":{"prompt":"The spread of smartphones and instant bank transfers leads a Yaba fashion vendor to sell mainly through social media and to accept payment by transfer instead of cash. Which macro-environment force is the vendor responding to?","options":["Political-legal environment","Demographic environment","Natural environment","Technological environment"],"correctOption":3,"section":"Marketing Environment","explanation":"New technology creates new opportunities for marketers to reach customers and deliver products in ways that match their lifestyles. Option C concerns resources and weather, option B the make-up of the population, and option A laws and government agencies."}},{"itemId":"b9871e7b-8c89-59c2-a088-9a63783381f2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"86e06673-f7e2-500a-9eb4-9bc1f70acfe6","sourceKey":"bank:LAG-BUA111:ENV-043","parentItemId":null,"revision":1,"payload":{"prompt":"As one of the technological trends affecting marketing, 'increased regulation' refers to:","options":["Competitors agreeing among themselves to fix prices","Customers setting standards for how firms advertise","Government guidelines that ban unsafe products, which marketers must know and obey","Firms limiting the working hours of their own staff"],"correctOption":2,"section":"Marketing Environment","explanation":"Increased regulation means government guidelines that ban unsafe products, so marketers must know these rules to avoid breaking them; drug makers seeking approval from a drugs regulator is the typical example. Option D is internal management, option A is collusion among firms, and option B wrongly gives the role of regulator to customers."}},{"itemId":"35b4dd3a-9a59-53c5-8949-bb0d082f598d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a49180b4-eef7-524f-900c-79ffbd839a8e","sourceKey":"bank:LAG-BUA111:ENV-044","parentItemId":null,"revision":1,"payload":{"prompt":"The environment that consists of legal bodies and government agencies that influence and limit organisations and individuals is the:","options":["Economic environment","Socio-cultural environment","Demographic environment","Political and legal environment"],"correctOption":3,"section":"Marketing Environment","explanation":"The political-legal environment is made up of the laws, legal bodies and government agencies that influence and limit what firms and individuals can do. Option B covers values and behaviour, option A costs and purchasing power, and option C population characteristics."}},{"itemId":"1555907e-8b9a-5a8a-a6f4-e476d908d300","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0d5ea266-92fe-5285-ac56-1ba1792a4d85","sourceKey":"bank:LAG-BUA111:ENV-045","parentItemId":null,"revision":1,"payload":{"prompt":"A state government passes a law banning the use of styrofoam food packs, and a chain of eateries in the state must switch to other packaging. Which macro-environment force is directly at work?","options":["Demographic environment","Socio-cultural environment","Technological environment","Political and legal environment"],"correctOption":3,"section":"Marketing Environment","explanation":"A law made by government that limits what a firm may do is a political-legal force. Option B would involve changes in values or lifestyles, option A changes in the population, and option C new technology, but here the eateries must change because of a legal ban."}},{"itemId":"fe2aeaf3-de27-5fb1-a8e3-b2a29c4aeb47","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"35e5c493-be0f-5855-b0be-f1fb2190ace0","sourceKey":"bank:LAG-BUA111:ENV-046","parentItemId":null,"revision":1,"payload":{"prompt":"Among the laws that affect marketing are anti-pollution laws and customer legislation. Customer legislation aims mainly to:","options":["Protect the interests of customers","Set interest rates for business loans","Control the level of pollution from factories","Protect firms from competition"],"correctOption":0,"section":"Marketing Environment","explanation":"Customer legislation, such as consumer protection laws, is designed to protect customers' interests. Option D is not its purpose, option C describes anti-pollution laws, and option B is a monetary policy matter."}},{"itemId":"161a8f64-4119-5af3-95f0-4c34f1fd6d11","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"12a3a1bc-16a4-5533-8da8-c24326889aab","sourceKey":"bank:LAG-BUA111:ENV-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the reasons why the study of the marketing environment is important to an organisation?","options":["Identification of opportunities","Eliminating all competition from the market","Identification of threats","Managing changes"],"correctOption":1,"section":"Marketing Environment","explanation":"Studying the environment helps a firm identify opportunities, identify threats and manage change, but it cannot remove competition from the market. Options A, C and D are the genuine reasons it is important."}},{"itemId":"c997a51d-a0e9-539a-a687-ac12e774651e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"87527715-2f7e-5df1-a185-10f28cfaf447","sourceKey":"bank:LAG-BUA111:ENV-048","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian fruit-juice maker learns that a large foreign multinational is about to enter its market, and it prepares price cuts and an aggressive promotion campaign in advance. Which benefit of studying the marketing environment does this show?","options":["De-marketing","Identification of threats","Relativity","Identification of opportunities"],"correctOption":1,"section":"Marketing Environment","explanation":"Spotting a dangerous new entrant early and preparing a response is identifying a threat; the environment gave a warning signal before it was too late. Option D would involve a favourable chance the firm could exploit. Option A is reducing demand for one's own product, and option C is a feature of the environment, not a benefit of studying it."}},{"itemId":"165ef2ec-7a71-5527-88cf-707f681056ba","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3e52110b-e49f-5e67-a333-d515bc9a5f7b","sourceKey":"bank:LAG-BUA111:ENV-049","parentItemId":null,"revision":1,"payload":{"prompt":"A major rival paint brand leaves the Nigerian market, leaving many retailers without supply. A local paint maker quickly moves in to win those retailers and their customers. Through environmental analysis, the local firm has:","options":["Identified and exploited an opportunity","Identified an internal weakness","Practised de-marketing","Identified a threat"],"correctOption":0,"section":"Marketing Environment","explanation":"A market vacuum created by a competitor's exit is an opportunity, and the firm exploited it to its advantage. Option D would be something harmful to the firm, option B would be an internal shortcoming such as poor quality, and option C means reducing demand for one's own product."}},{"itemId":"7059a5b6-e813-5b9f-8a03-d77bff9a7251","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"869e27d4-7731-5c5e-8d1c-b8578c797aca","sourceKey":"bank:LAG-BUA111:ENV-050","parentItemId":null,"revision":1,"payload":{"prompt":"An environmental analysis shows that an Ibadan cosmetics firm has low-quality packaging and lacks marketing expertise, so management plans to turn these into strengths. The analysis has identified the firm's:","options":["General forces","Weaknesses","Threats","Opportunities"],"correctOption":1,"section":"Marketing Environment","explanation":"Lower-quality offerings and a lack of marketing expertise are internal weaknesses that the firm can work to convert into strengths. Option C refers to harmful external developments such as new competitors or price wars. Option D refers to favourable external chances, and option A to indirect external forces."}},{"itemId":"21df8ec1-ea2b-5a56-8a5c-9d1c9aba4f26","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c43000db-10c6-5b90-aa69-29b4ef37f177","sourceKey":"bank:LAG-BUA111:ENV-051","parentItemId":null,"revision":1,"payload":{"prompt":"The systematic monitoring of the external environment to detect trends, opportunities and threats early enough for the firm to respond is called:","options":["Market segmentation","Product positioning","Environmental scanning","Channel management"],"correctOption":2,"section":"Marketing Environment","explanation":"Environmental scanning means keeping watch on the environment so that changes, and the threats and opportunities they bring, are spotted in time. Option A divides a market into groups, option B shapes how a product is seen relative to rivals, and option D manages distribution channels."}},{"itemId":"1e7e1370-9de5-5a3e-9946-394e323fb9bc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"816c5f81-1f73-5eb6-9805-c69cb27930c0","sourceKey":"bank:LAG-BUA111:ENV-052","parentItemId":null,"revision":1,"payload":{"prompt":"In the micro environment, any group that has an actual or potential interest in, or impact on, an organisation's ability to achieve its objectives is called a:","options":["Public","Supplier","Reseller","Competitor"],"correctOption":0,"section":"Marketing Environment","explanation":"A public is any group with an actual or potential interest in, or impact on, the firm's ability to reach its goals, such as the media, government or local community. Option B provides inputs, option C buys to resell, and option D offers similar products to the same buyers."}},{"itemId":"9648b8f9-9687-563f-9200-254737a35b2a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6796dd1a-72b0-5e5c-bd71-116af85031e6","sourceKey":"bank:LAG-BUA111:ENV-053","parentItemId":null,"revision":1,"payload":{"prompt":"Newspapers, radio stations and online news blogs that carry news, features and opinions about a Lagos bank are which type of public?","options":["Financial publics","Internal publics","Media publics","Government publics"],"correctOption":2,"section":"Marketing Environment","explanation":"Media publics are the outlets that carry news, features and opinion about the organisation. Option A covers banks, investors and analysts that affect the firm's ability to raise funds, option D covers government bodies, and option B covers the firm's own employees and managers."}},{"itemId":"4d076f63-d090-539f-947a-1958c3032217","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"16eb7cf1-8970-5df7-b77c-5add6d12f205","sourceKey":"bank:LAG-BUA111:ENV-054","parentItemId":null,"revision":1,"payload":{"prompt":"When the 'company' itself is treated as a force in the micro environment (the internal environment), it refers to:","options":["The laws and government agencies that regulate the firm","The banks and insurers that finance the firm's transactions","The firm's rivals that sell similar products","The firm's own departments, such as top management, finance, R&D, purchasing and operations, whose relationships affect marketing decisions"],"correctOption":3,"section":"Marketing Environment","explanation":"As an internal force, the company means all its departments and top management, whose cooperation shapes marketing plans and actions. Option C describes competitors, option B financial intermediaries, and option A the political-legal environment."}},{"itemId":"a3ab0b2f-b9ad-5fd1-987b-3ac618ad38bc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fd515328-c817-59c8-a815-ba166556570c","sourceKey":"bank:LAG-BUA111:ENV-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a CONTROLLABLE variable for a marketing manager?","options":["A competitor's decision to launch a new product","The price the firm sets for its own product","The rate of inflation in the economy","The rate of population growth"],"correctOption":1,"section":"Marketing Environment","explanation":"Marketing mix decisions such as the firm's own price are controllable, because the firm decides them. Options C, D and A are external forces (economic, demographic and competitive) that the firm must adapt to but cannot control."}},{"itemId":"c1d17af3-55a5-5fc6-abf7-95df344df2ef","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5b6fcc5b-f2c0-59b1-89df-82b6cf6d8f4d","sourceKey":"bank:LAG-BUA111:FOR-001","parentItemId":null,"revision":1,"payload":{"prompt":"The total volume of a product that would be bought by a defined customer group, in a defined geographical area, in a defined time period, in a defined marketing environment and under a defined marketing programme is called","options":["sales quota","market demand","market share","company demand"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"Market demand is the total amount all buyers in a defined group and area would buy in a given period under given conditions. Option D is only one company's share of that demand, Option A is a sales target set for a salesperson or territory, and Option C is a percentage, not a volume."}},{"itemId":"209f5cb9-03ce-5fa5-b4cd-3c6e3044d5ba","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bd45e8ac-6bcf-5a95-98b7-018219d301f2","sourceKey":"bank:LAG-BUA111:FOR-002","parentItemId":null,"revision":1,"payload":{"prompt":"Market potential is best defined as","options":["the sales a company actually achieved in the last period","the level of sales that would occur with no marketing expenditure at all","a single company's expected sales under its chosen marketing plan","the limit approached by market demand as industry marketing expenditure approaches infinity, for a given marketing environment"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Market potential is the upper limit that total market demand approaches as industry marketing effort becomes very large in a given environment. Option B is the market minimum, Option A is past company sales, and Option C is the company sales forecast."}},{"itemId":"c331b411-2462-581f-b204-f3632a3c21e8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"41c8a0da-c561-5e10-b076-de56183e7e53","sourceKey":"bank:LAG-BUA111:FOR-003","parentItemId":null,"revision":1,"payload":{"prompt":"The sales level of a product that would occur even without any marketing expenditure to stimulate demand is called the","options":["market potential","company sales potential","market minimum","sales quota"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"The market minimum is the baseline volume that would be bought with zero marketing spending. Option A is the ceiling reached as marketing spending becomes very large, Option B is the ceiling for one company, and Option D is a target set for the sales force."}},{"itemId":"54a2c906-b160-5f87-86b5-4f87bc865eea","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5144bf7c-8e9b-5741-b812-2580b829608f","sourceKey":"bank:LAG-BUA111:FOR-004","parentItemId":null,"revision":1,"payload":{"prompt":"A company's estimated share of market demand at alternative levels of its marketing effort in a given time period is known as","options":["primary demand","company demand","market potential","market minimum"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"Company demand is the firm's share of total market demand, and it depends on how its marketing effort compares with competitors'. Option C and Option D refer to the whole market, not one company, and Option A is demand for the product category as a whole."}},{"itemId":"09c78578-c625-5580-b329-3eda3eeeba79","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f663f0a5-4c48-5b81-bbd4-a40637527e8d","sourceKey":"bank:LAG-BUA111:FOR-005","parentItemId":null,"revision":1,"payload":{"prompt":"The expected level of company sales based on a chosen marketing plan and an assumed marketing environment is called the","options":["company sales forecast","company sales potential","market potential","market demand"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"A sales forecast is the firm's expected sales given the specific plan it has chosen and the environment it assumes. Option B is the maximum the company could reach if its marketing effort increased relative to competitors, while Option C and Option D refer to the whole market."}},{"itemId":"6ec751b7-73ce-50c0-9bf6-ab42e6f2b870","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8cd682bc-5b8f-5f3a-9df4-39a695c13ca6","sourceKey":"bank:LAG-BUA111:FOR-006","parentItemId":null,"revision":1,"payload":{"prompt":"What is the key difference between company sales potential and the company sales forecast?","options":["There is no difference; the two terms mean exactly the same thing","Sales potential is always lower than the sales forecast","Sales potential refers to the whole industry, while the forecast refers to a single customer","Sales potential is the limit the company's sales could approach as its marketing effort increases relative to competitors, while the forecast is the sales expected under the plan actually chosen"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Company sales potential is a ceiling that the firm could approach with increasing marketing effort, while the forecast is the realistic expectation under its chosen plan. Option B is wrong because the forecast is normally at or below the potential. Option C confuses the levels of measurement, and Option A ignores the clear difference."}},{"itemId":"cb76e5ac-ad3a-551a-958c-32c24f599207","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d2b4c222-9705-5939-a5d8-92d0e227cab4","sourceKey":"bank:LAG-BUA111:FOR-007","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's sales expressed as a percentage of the total sales of all firms in the same market during the same period is the firm's","options":["market penetration index","sales quota","market potential","market share"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Market share compares the firm's sales with total market sales. Option C is the theoretical ceiling for the whole market, Option B is a sales target, and Option A compares current market demand with potential demand rather than the firm with its rivals."}},{"itemId":"300f8e27-da9c-5e37-841c-28ede68e92c3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1152d131-2ef0-5414-bf77-291f12593a39","sourceKey":"bank:LAG-BUA111:FOR-008","parentItemId":null,"revision":1,"payload":{"prompt":"A campaign that encourages more Nigerians to drink bottled water in general, rather than any particular brand, is trying to stimulate","options":["company demand only","primary demand","the market minimum","selective demand"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"Primary demand is demand for the product category as a whole. Selective demand, Option D, is demand for a particular brand. Option A concerns one firm's share, and Option C is the level of sales with no marketing at all."}},{"itemId":"a81e7067-4cb4-56ba-889a-7ff89ad62954","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7cbc20b1-79df-5a66-87c0-bb0b93813e88","sourceKey":"bank:LAG-BUA111:FOR-009","parentItemId":null,"revision":1,"payload":{"prompt":"A survey of buyers' intentions is MOST useful for forecasting when","options":["buyers are few, can be reached cheaply, have clear intentions and are likely to carry them out","buyers are unwilling to share information about their plans","buyers are millions of scattered consumers who rarely plan purchases","the product is completely new and buyers cannot describe it"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Buyer-intention surveys work best when the buyers are few, the cost of reaching them is low, and they have clear intentions that they will carry out and are willing to disclose, as is common in industrial markets. Option C, Option D and Option B describe situations where stated intentions would be unreliable or hard to obtain."}},{"itemId":"7c8995c6-abd6-5e61-8076-b299036c2527","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cc95df2e-fd94-5add-9e4e-696a270a3191","sourceKey":"bank:LAG-BUA111:FOR-010","parentItemId":null,"revision":1,"payload":{"prompt":"A forecasting method in which each salesperson estimates the likely sales in his or her territory and the estimates are added up (and adjusted by management) to give a company forecast is called","options":["the Delphi method","the market test method","the moving average method","the sales-force composite (composite of sales-force opinions)"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"The sales-force composite builds the forecast from the estimates of the people closest to customers. Option A uses a panel of experts in anonymous rounds, Option B sells the product in a test area, and Option C averages past sales figures."}},{"itemId":"fc77918a-4181-5b15-8f49-bd07daa7c438","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8eafe2d4-30e0-5e1f-916e-4333931543b1","sourceKey":"bank:LAG-BUA111:FOR-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a well-known weakness of the sales-force composite method of forecasting?","options":["Salespeople may be biased, for example deliberately underestimating so that their sales quotas are set low","It relies only on mathematical analysis of past sales","It cannot be broken down by territory or product","It ignores people who have direct contact with customers"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Sales representatives may be naturally optimistic or pessimistic, and some underestimate so that the company sets low quotas, so management usually adjusts their figures. Option C is wrong because the method gives estimates broken down by territory and product. Option B describes time-series analysis, and Option D is the opposite of the method."}},{"itemId":"f32f6f44-62e1-5726-96ca-2a82f066fe4a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1458384e-7340-5502-a60f-f76bd7f50a19","sourceKey":"bank:LAG-BUA111:FOR-012","parentItemId":null,"revision":1,"payload":{"prompt":"A forecasting technique in which a panel of experts gives estimates anonymously, receives a summary of the group's answers, and revises its estimates over several rounds until a consensus emerges is the","options":["sales-force composite","market test method","chain-ratio method","Delphi method"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"The Delphi method is a structured form of expert opinion that uses anonymous, repeated rounds of estimates and feedback. Option A uses the firm's salespeople, Option B uses real sales in a test area, and Option C multiplies a base number by a series of percentages to estimate potential."}},{"itemId":"4d23953b-d911-5eb3-9e9e-48fc1c03d961","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"50f273e2-fa8c-5f6b-b9cc-ce89f14c4efd","sourceKey":"bank:LAG-BUA111:FOR-013","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos snack company launches its new plantain chips only in Ibadan for three months, records actual purchases there, and uses the results to estimate national demand. Which forecasting method is this?","options":["Moving average","Market test method","Expert opinion","Survey of buyers' intentions"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"A market test puts the product on sale in a limited area and uses the real buying response to forecast wider demand, which is especially useful for new products. Option D relies on stated plans rather than actual purchases, Option C on expert judgement, and Option A on averaging past sales that a new product does not yet have."}},{"itemId":"c08655dd-fb23-5f6d-b6b8-e6d71688adb6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4e29beb2-6234-5d4d-809a-97c07e87b17b","sourceKey":"bank:LAG-BUA111:FOR-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the four components into which past sales (time series) are usually broken down?","options":["Trend","Erratic","Seasonal","Elasticity"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Time-series analysis splits past sales into trend, cycle, season and erratic events. Elasticity measures how demand responds to price changes; it is not a time-series component. Option A, Option C and Option B are all genuine components."}},{"itemId":"96734b4e-6591-5ddb-93f3-fdfa3f5e480b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b09848fe-cf67-5baa-bd5b-8d363e5392f6","sourceKey":"bank:LAG-BUA111:FOR-015","parentItemId":null,"revision":1,"payload":{"prompt":"Sales of umbrellas and raincoats in Lagos rise every year between April and July and fall in the dry season. In time-series analysis this repeated pattern within the year is the","options":["trend component","erratic component","seasonal component","cyclical component"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"A seasonal component is a consistent pattern of sales movements within the year, linked to weather, holidays or similar factors. Option A is the long-run basic growth or decline, Option D is the medium-term wave linked to the business cycle, and Option B covers unpredictable one-off events."}},{"itemId":"8d39a323-a0e3-5904-ab11-a07d8fb3c10d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d006d37a-cfa8-5bdf-95a4-e025d3b33791","sourceKey":"bank:LAG-BUA111:FOR-016","parentItemId":null,"revision":1,"payload":{"prompt":"A transport company's ticket sales drop sharply for two weeks because of an unexpected fuel scarcity and then recover. In time-series analysis this unusual drop is part of the","options":["erratic component","cyclical component","trend component","seasonal component"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Erratic events are unpredictable disruptions such as strikes, riots or shortages; they are removed from past data so the normal pattern can be seen. Option C is the long-term direction, Option D repeats every year, and Option B follows the wave-like movement of the general economy over several years."}},{"itemId":"f81b7493-0e48-56b8-a031-411e7d98d3e1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"74471ff4-e59a-53e1-8dc1-0ec99d5d74ce","sourceKey":"bank:LAG-BUA111:FOR-017","parentItemId":null,"revision":1,"payload":{"prompt":"What is the main purpose of using a moving average when forecasting sales?","options":["To combine the opinions of a panel of experts","To smooth out short-term, random fluctuations in past sales so the underlying level is clearer","To measure how customers respond to a change in price","To estimate the share of the market held by competitors"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"A moving average replaces individual sales figures with the average of the most recent periods, which smooths out random ups and downs. Option C describes price elasticity, Option A describes expert opinion or Delphi, and Option D describes market share analysis."}},{"itemId":"eac050c8-23a2-59cb-ba3f-fe2d8e8de7fb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9b23276-7323-5771-b58f-e1d11fa3d1f9","sourceKey":"bank:LAG-BUA111:FOR-018","parentItemId":null,"revision":1,"payload":{"prompt":"How does a weighted moving average differ from a simple moving average?","options":["It ignores past sales and uses buyers' stated intentions","It gives different weights to the periods, usually more weight to the most recent ones","It uses only the oldest period in the data","It always uses more periods than a simple moving average"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"A simple moving average gives every period equal weight, while a weighted moving average attaches larger weights to more recent periods so the forecast reacts faster to change. Option C and Option D are not what defines the weighted method, and Option A describes a survey of buyers' intentions."}},{"itemId":"3b7b5aa6-6fe1-584c-af40-3ac5effce199","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8d999f72-a3b7-5ce9-929d-cbc5392301fc","sourceKey":"bank:LAG-BUA111:FOR-019","parentItemId":null,"revision":1,"payload":{"prompt":"Trend projection as a forecasting method is based on the main assumption that","options":["experts' opinions are always more accurate than data","the pattern of past sales will continue into the future","the market is completely new and has no history","buyers will always do exactly what they say in surveys"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"Trend projection fits a line or growth rate to past data and extends it forward, so it assumes past patterns continue. It can mislead when there is a sudden change in the environment. Option D relates to buyer-intention surveys, Option C would make trend projection impossible, and Option A relates to judgement methods."}},{"itemId":"3a4bbb13-fba4-559b-a180-3f83978a585d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"44971a5f-bb50-5db0-ba61-7711e522cb44","sourceKey":"bank:LAG-BUA111:FOR-020","parentItemId":null,"revision":1,"payload":{"prompt":"A method of estimating market potential that starts with a base number (such as population) and multiplies it by a series of percentages that narrow it down to likely buyers is called the","options":["market-buildup method","Delphi method","moving average method","chain-ratio method"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"The chain-ratio method multiplies a base figure by several adjusting percentages, for example population x share of adults x share who drink the product. Option A adds up potential buyers identified market by market, Option B is an expert-opinion technique, and Option C is a time-series smoothing method."}},{"itemId":"7eede3d0-b795-5e1c-86e5-e4d76d8cfe3d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c9aa858c-f903-5642-9ae1-d241cf4c57f9","sourceKey":"bank:LAG-BUA111:FOR-021","parentItemId":null,"revision":1,"payload":{"prompt":"Identifying all the potential buyers in each market (for example, every bakery in a state) and estimating their potential purchases, then adding these up, is known as the","options":["sales-force composite","market-buildup method","chain-ratio method","market test method"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"The market-buildup method builds total potential from a list of identifiable buyers and their likely purchases; it is common in business markets. Option C works down from a base number using percentages, Option A collects salespeople's sales estimates, and Option D measures actual sales in a test area."}},{"itemId":"460b73b0-152b-552d-9b67-caa8192d92d1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6d08c2c8-e59d-5078-a1d2-5f66740e398c","sourceKey":"bank:LAG-BUA111:FOR-022","parentItemId":null,"revision":1,"payload":{"prompt":"In market measurement, the 'available market' is best described as","options":["the set of consumers who have already bought the product","the set of consumers who have interest in, income for and access to a particular offer","all consumers who profess any level of interest, regardless of income or access","the part of the market the company has decided to pursue"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"The available market consists of consumers who have interest, income and access to the offer. Option A is the penetrated market, Option D is the target (served) market, and Option C is the potential market, which ignores whether buyers can afford or reach the product."}},{"itemId":"8b5975dc-3cba-51b2-88cf-0b4c87d084c7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"469e6314-ed7f-57dc-ada3-02ddcd796cde","sourceKey":"bank:LAG-BUA111:FOR-023","parentItemId":null,"revision":1,"payload":{"prompt":"A market has 2,000,000 potential buyers. Each buyer purchases an average of 4 units of a detergent per year at an average price of N1,500 per unit. Using Q = n x q x p, what is the total market potential per year?","options":["N1,200,000,000","N8,000,000","N12,000,000,000","N3,000,000,000"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"Total market potential Q = n x q x p = 2,000,000 x 4 x N1,500 = N12,000,000,000. Option D multiplies only buyers by price and forgets the 4 units each buyer purchases. Option A is a decimal slip (one zero lost), and Option B is the number of units multiplied out without the price."}},{"itemId":"4c1ca6b7-1dbe-5e22-bb43-47bccdfe8ad3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2766d4fe-3b4d-544a-a049-4d59661b9caa","sourceKey":"bank:LAG-BUA111:FOR-024","parentItemId":null,"revision":1,"payload":{"prompt":"In a town, 50,000 households each buy 3 loaves of bread per week at N1,200 per loaf. Assuming 52 weeks in a year, what is the annual market potential for bread in naira?","options":["N9,360,000,000","N2,160,000,000","N180,000,000","N8,640,000,000"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Annual quantity per household = 3 x 52 = 156 loaves, so market potential = 50,000 x 156 x N1,200 = N9,360,000,000. Option C is only one week's spending. Option B wrongly treats 3 loaves a week as 3 loaves a month (x12), and Option D uses 48 weeks instead of the 52 stated."}},{"itemId":"230107e9-0bc1-58d0-8904-ae93b6d822f8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"99f81a7f-c0f3-54f5-9704-787a21f172fc","sourceKey":"bank:LAG-BUA111:FOR-025","parentItemId":null,"revision":1,"payload":{"prompt":"Using the market-buildup method, a flour miller identifies 400 bakeries in its state. Each bakery buys an average of 20 bags of flour a month at N60,000 per bag. What is the annual market potential in the state?","options":["N5,760,000,000","N480,000,000","N2,880,000,000","N57,600,000,000"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Annual bags = 400 x 20 x 12 = 96,000, so potential = 96,000 x N60,000 = N5,760,000,000. Option B is only one month's purchases (it forgets to multiply by 12), and Option C uses 6 months instead of 12."}},{"itemId":"cebc6b64-3cfd-58a2-bcb7-cd2961866841","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c669609d-c9e1-5698-bf36-b5b6b18303d7","sourceKey":"bank:LAG-BUA111:FOR-026","parentItemId":null,"revision":1,"payload":{"prompt":"Using the chain-ratio method: a city has 1,200,000 people; 60% are adults; 40% of adults drink malt drinks; and each malt drinker consumes 50 bottles a year. What is the estimated annual market potential in bottles?","options":["14,400,000 bottles","36,000,000 bottles","288,000 bottles","24,000,000 bottles"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Chain ratio: 1,200,000 x 0.60 x 0.40 x 50 = 14,400,000 bottles. Option D skips the 60% adult ratio, Option B skips the 40% malt-drinker ratio, and Option C gives the number of drinkers (288,000) but forgets to multiply by 50 bottles each."}},{"itemId":"b30190b3-0311-52cd-af36-b16c3d3e37b0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"06570b36-6e59-5f66-a76e-89d8b4a11b09","sourceKey":"bank:LAG-BUA111:FOR-027","parentItemId":null,"revision":1,"payload":{"prompt":"In a year, a paint company sold goods worth N45 million, while total sales of all paint companies in the same market (including this company) were N300 million. What is the company's market share?","options":["85%","13.04%","15%","6.67%"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"Market share = company sales / total market sales x 100 = 45 / 300 x 100 = 15%. Option A is the share held by all competitors together. Option B wrongly adds the company's sales to a total that already includes them, giving 45 / 345."}},{"itemId":"0a7bc9a8-9bbb-52c3-be4f-fd8f19f26e80","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a5764426-2df8-50b5-842a-2ecd036b31f7","sourceKey":"bank:LAG-BUA111:FOR-028","parentItemId":null,"revision":1,"payload":{"prompt":"A juice brand sold 42,000 cartons in a quarter. Total industry sales in the same market and quarter were 168,000 cartons (including the brand's sales). What is the brand's market share in volume terms?","options":["25%","4%","20%","75%"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Volume market share = 42,000 / 168,000 x 100 = 25%. Option D is the competitors' combined share, Option C divides by 168,000 + 42,000 and so double counts the brand, and Option B divides the wrong way round."}},{"itemId":"8ffbb20c-d6cd-5f06-8729-394bbd29df27","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a5e8b174-e2ec-5d7c-a841-965a02bafae7","sourceKey":"bank:LAG-BUA111:FOR-029","parentItemId":null,"revision":1,"payload":{"prompt":"Total market demand for cement in a region next year is forecast at N800 million. A company expects to hold a 12% market share. What is its sales forecast for the year?","options":["N96 million","N9.6 million","N704 million","N66.67 million"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Company sales forecast = market demand x expected market share = N800m x 0.12 = N96 million. Option B misplaces the decimal, Option C gives the competitors' expected sales (88%), and Option D divides by 12 instead of taking 12%."}},{"itemId":"a2389e7c-fcd0-54e5-9d1c-4da7839bae56","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9ce8314c-7d4f-5288-854e-26dac00a92e8","sourceKey":"bank:LAG-BUA111:FOR-030","parentItemId":null,"revision":1,"payload":{"prompt":"Relative market share is defined as a firm's market share divided by the market share of its largest competitor. Firm A has a 20% market share and its largest competitor has 40%. What is Firm A's relative market share?","options":["0.2","2.0","0.5","20"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"Relative market share = 20% / 40% = 0.5, meaning Firm A is half the size of the leader. Option B divides the wrong way round. Option D takes the difference between the shares instead of the ratio."}},{"itemId":"0c0ef613-ace1-5109-89fa-0b09cfa37095","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"94578f50-9d9d-57e1-8426-52f80ec778c1","sourceKey":"bank:LAG-BUA111:FOR-031","parentItemId":null,"revision":1,"payload":{"prompt":"Relative market share is defined as a firm's market share divided by that of its largest competitor. A market leader holds 36% of the market and the next-largest firm holds 24%. What is the leader's relative market share?","options":["0.67","1.5","12","0.6"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"For the leader, the largest competitor is the 24% firm, so relative share = 36 / 24 = 1.5. A value above 1 shows the firm leads the market. Option A inverts the ratio, and Option C uses the difference in percentage points instead of a ratio."}},{"itemId":"578450ba-893a-59b5-8715-3c0420575dd7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0f7ac7d1-00ad-586f-afbc-d0e0e86f3c53","sourceKey":"bank:LAG-BUA111:FOR-032","parentItemId":null,"revision":1,"payload":{"prompt":"The market penetration index is defined as current market demand divided by market potential, expressed as a percentage. If current demand for solar lanterns in a state is 6 million units and market potential is 15 million units, what is the market penetration index?","options":["9 million units","250%","40%","60%"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"Penetration index = 6 / 15 x 100 = 40%. A low index suggests large room for market growth. Option B divides the wrong way round, and Option D is the unpenetrated part of the potential (60%)."}},{"itemId":"0da8874b-a2a7-53be-a64b-329cfd37dba4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3cb5f2e2-c662-54e7-b265-20dfad3443c2","sourceKey":"bank:LAG-BUA111:FOR-033","parentItemId":null,"revision":1,"payload":{"prompt":"Monthly sales (in thousands of units) of a product for January to June were 40, 46, 48, 55, 51 and 57. Using a 3-month simple moving average, what is the sales forecast for July? (to 2 decimal places)","options":["49.50 thousand","44.67 thousand","57.00 thousand","54.33 thousand"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"A 3-month moving average forecast uses the latest three months: (55 + 51 + 57) / 3 = 54.33 thousand. Option A averages all six months, Option B averages the first three months instead of the latest three, and Option C simply repeats June's figure."}},{"itemId":"cddf9623-ebf4-593a-8bde-c70ca5daaba9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8b52ee33-6e90-5803-bd73-f209349f51e5","sourceKey":"bank:LAG-BUA111:FOR-034","parentItemId":null,"revision":1,"payload":{"prompt":"Quarterly sales (N million) for five consecutive quarters were 120, 135, 128, 142 and 150. Using a 4-quarter simple moving average, what is the forecast for the next quarter? (to 2 decimal places)","options":["N135.00 million","N111.00 million","N131.25 million","N138.75 million"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"The 4-quarter moving average uses the four most recent quarters: (135 + 128 + 142 + 150) / 4 = 138.75. Option A averages all five quarters, Option C uses the four oldest quarters, and Option B adds the right four quarters but divides by 5."}},{"itemId":"b4484dcf-f16b-5591-a5e8-21fc3dd406f4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9fd3b71f-d8dd-56d0-9e4e-9e582925f13e","sourceKey":"bank:LAG-BUA111:FOR-035","parentItemId":null,"revision":1,"payload":{"prompt":"Sales for the last three months (oldest first) were 120, 130 and 150 units. Using a weighted moving average with weights of 3 for the most recent month, 2 for the month before and 1 for the oldest month, what is next month's forecast? (to 2 decimal places)","options":["128.33 units","276.67 units","138.33 units","133.33 units"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"WMA = (3 x 150 + 2 x 130 + 1 x 120) / (3 + 2 + 1) = 830 / 6 = 138.33. Option A applies the heaviest weight to the oldest month, Option D is the simple (unweighted) average, and Option B divides by the number of months (3) instead of the sum of the weights (6)."}},{"itemId":"b40c5dca-d79f-5d97-aa3c-0cd46cef46be","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"77822731-70d7-56fa-985b-e066573a2f14","sourceKey":"bank:LAG-BUA111:FOR-036","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's trend line for annual sales is Y = 200 + 15X, where Y is sales in thousands of units and X = 1 for 2019, 2 for 2020, and so on. What is the forecast for 2026?","options":["320 thousand units","215 thousand units","305 thousand units","1,720 thousand units"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"2026 is the 8th year when 2019 is X = 1, so Y = 200 + 15(8) = 320. Option C uses X = 7 (counting the years wrongly), Option B uses X = 1, and Option D wrongly multiplies the whole of (200 + 15) by 8."}},{"itemId":"3c1d6261-345a-53d7-b3b1-a3e536471548","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e68dfd19-c123-51d7-95c5-de9864e80a76","sourceKey":"bank:LAG-BUA111:FOR-037","parentItemId":null,"revision":1,"payload":{"prompt":"Sales (N million) for 2021 to 2025 were 20, 24, 27, 31 and 33. Using the least-squares trend Y = a + bX with X coded -2, -1, 0, 1, 2 (so that sum of X = 0, a = sum of Y / n and b = sum of XY / sum of X^2), what is the forecast for 2026? (to 1 decimal place)","options":["N30.3 million","N27.0 million","N36.9 million","N43.5 million"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"a = 135 / 5 = 27; b = sum XY / sum X^2 = 33 / 10 = 3.3. 2026 is coded X = 3, so Y = 27 + 3.3(3) = 36.9. Option D uses X = 5 (forgetting the coding is centred on 2023), Option B gives only the average a, and Option A uses X = 1, which is the 2024 trend value."}},{"itemId":"c081ee85-a2d0-5600-b4ed-42ae614de3a4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"edf9116d-f212-553f-bf7f-076b1f0a7f65","sourceKey":"bank:LAG-BUA111:FOR-038","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's sales (thousand units) for five years were 50, 56, 59, 65 and 70. With the years coded X = -2, -1, 0, 1, 2, the least-squares slope is b = sum of XY / sum of X^2. What is the value of b, the average yearly increase in the trend? (to 1 decimal place)","options":["60.0","4.0","9.8","4.9"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Sum XY = -100 - 56 + 0 + 65 + 140 = 49, and sum X^2 = 4 + 1 + 0 + 1 + 4 = 10, so b = 49 / 10 = 4.9. Option C divides by n = 5 instead of sum X^2, Option B divides the total change by 5 years instead of 4 intervals, and Option A is the intercept a, not the slope."}},{"itemId":"e6f61ddc-f03b-5000-bdb5-bb408a900ea0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"67ceab12-d951-5ef9-b34e-226c1a8355a8","sourceKey":"bank:LAG-BUA111:FOR-039","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's sales were N100 million in 2021 and N140 million in 2025. Assuming sales continue to grow by the same average amount each year (a straight-line trend), what is the forecast for 2026?","options":["N148 million","N120 million","N150 million","N180 million"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"There are 4 yearly intervals from 2021 to 2025, so the average annual increase = (140 - 100) / 4 = N10 million and the 2026 forecast = 140 + 10 = N150 million. Option A wrongly divides by 5 (counting years instead of intervals). Option D adds the whole four-year increase, and Option B is just the average of the two years."}},{"itemId":"ff374620-f664-5925-b592-1a424a9e187f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fd7a0e7f-4f12-5b71-9d48-c57d925bde99","sourceKey":"bank:LAG-BUA111:FOR-040","parentItemId":null,"revision":1,"payload":{"prompt":"A company's sales this year are N50 million. If sales are expected to grow at a constant 10% per year (compound growth), what is the forecast for two years from now? (to 1 decimal place)","options":["N55.0 million","N60.0 million","N60.5 million","N66.6 million"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"Compound growth: 50 x (1.1)^2 = N60.5 million. Option B uses simple growth (10% of the original N50m each year), which ignores growth on the first year's increase. Option A is only one year ahead, and Option D is three years ahead."}},{"itemId":"7b744699-a0c0-5a58-96b6-49c3d5b927ef","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d5aa9b41-9999-5845-aa0e-93f49db936e6","sourceKey":"bank:LAG-BUA111:FOR-041","parentItemId":null,"revision":1,"payload":{"prompt":"A survey of buyers' intentions in a market of 200,000 households finds that 15% will 'definitely buy' a new water purifier next year and 25% will 'probably buy'. Past experience shows that 80% of 'definite' and 20% of 'probable' respondents actually buy. How many households are expected to buy?","options":["34,000","80,000","24,000","30,000"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Expected buying rate = 0.15 x 0.80 + 0.25 x 0.20 = 0.12 + 0.05 = 0.17, so buyers = 200,000 x 0.17 = 34,000. Option B assumes everyone who said 'definitely' or 'probably' will buy. Option D uses only the 'definite' group without adjustment, and Option C ignores the 'probable' group."}},{"itemId":"403817da-e750-594c-9c1d-0beb69b6cf16","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"057ea44d-7d2d-5955-bd7c-58354a984090","sourceKey":"bank:LAG-BUA111:FOR-042","parentItemId":null,"revision":1,"payload":{"prompt":"Three sales representatives estimate next year's sales in their territories at 40,000, 55,000 and 65,000 units. Management believes the team is usually over-optimistic and reduces the combined estimate by 10%. What is the sales-force composite forecast?","options":["144,000 units","160,000 units","176,000 units","53,333.33 units"],"correctOption":0,"section":"Market Measurement and Forecasting","explanation":"Composite = 40,000 + 55,000 + 65,000 = 160,000 units, then reduce by 10%: 160,000 x 0.90 = 144,000. Option B forgets management's adjustment, Option D averages the territories instead of adding them, and Option C increases rather than reduces the estimate."}},{"itemId":"464767a7-c27a-5d1a-beae-bf9249493cc6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a8f8911b-10c8-5578-b4e6-4d9d1c27c168","sourceKey":"bank:LAG-BUA111:FOR-043","parentItemId":null,"revision":1,"payload":{"prompt":"Three experts forecast next year's industry sales at N120 million, N150 million and N135 million. The firm gives their opinions weights of 0.5, 0.3 and 0.2 respectively based on past accuracy. What is the weighted expert-opinion forecast?","options":["N135 million","N405 million","N136.5 million","N132 million"],"correctOption":3,"section":"Market Measurement and Forecasting","explanation":"Weighted forecast = 0.5(120) + 0.3(150) + 0.2(135) = 60 + 45 + 27 = N132 million. Option A is the simple average that ignores the weights, Option B adds the forecasts without averaging, and Option C attaches the weights to the wrong experts."}},{"itemId":"23b84c1e-7dd4-5cbd-aa2a-d4aa623238a4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9ad2069-25c6-5a18-97bc-5f1552ab35da","sourceKey":"bank:LAG-BUA111:FOR-044","parentItemId":null,"revision":1,"payload":{"prompt":"In a market test, a new seasoning cube sold 30,000 packs in a test city that contains 2% of the national target population. Assuming the test city is representative, what is the estimated national sales?","options":["600 packs","1,500,000 packs","150,000 packs","15,000,000 packs"],"correctOption":1,"section":"Market Measurement and Forecasting","explanation":"If 2% of the population bought 30,000 packs, the whole population would buy 30,000 / 0.02 = 1,500,000 packs. Option A multiplies by 2% instead of dividing, Option C treats 2% as 0.2, and Option D treats 2% as 0.002."}},{"itemId":"c947cd3d-7a15-51c7-8daf-e52e278f594d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f51402bc-cab8-59d7-9c4a-cd662b7ab0df","sourceKey":"bank:LAG-BUA111:FOR-045","parentItemId":null,"revision":1,"payload":{"prompt":"A buying power index for a state is calculated as 0.5(state's % share of national disposable income) + 0.3(% share of national retail sales) + 0.2(% share of national population). A state has 4% of income, 5% of retail sales and 3% of population. If national market potential is N500 billion, what is the state's market potential?","options":["N19.0 billion","N20.0 billion","N20.5 billion","N25.0 billion"],"correctOption":2,"section":"Market Measurement and Forecasting","explanation":"BPI = 0.5(4) + 0.3(5) + 0.2(3) = 2.0 + 1.5 + 0.6 = 4.1%, so state potential = 4.1% x N500bn = N20.5 billion. Option B uses a simple unweighted average of 4%, Option D uses retail sales share alone, and Option A attaches the weights to the wrong factors (3.8%)."}},{"itemId":"02529cb1-7c44-5d10-9769-6ddc91148acd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b86bf1fe-a81d-557d-a5d4-4a219e52cff7","sourceKey":"bank:LAG-BUA111:MGT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The art and science of choosing target markets and building profitable relationships with them is called:","options":["sales management","financial management","marketing management","production management"],"correctOption":2,"section":"Marketing Management","explanation":"Marketing management is the art and science of choosing target markets and building profitable relationships with them. Sales management (option A) covers only managing the sales force, while production (D) and financial (B) management deal with other business functions."}},{"itemId":"2a7c8735-e6ed-5376-ba76-52bc5dc7e537","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8970fd20-a4af-56be-9e7b-034be7762e0b","sourceKey":"bank:LAG-BUA111:MGT-002","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing management has been defined as the art and science of choosing target markets and ____ through creating, delivering and communicating superior customer value.","options":["reducing production costs","getting, keeping and growing customers","eliminating competitors","maximising short-term sales"],"correctOption":1,"section":"Marketing Management","explanation":"The full definition is the art and science of choosing target markets and getting, keeping and growing customers through creating, delivering and communicating superior customer value. Options A, C and D are narrow goals that do not reflect this customer-focused task."}},{"itemId":"8f387226-d615-553b-b45f-2e264ac7a9e7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"142a1b50-727c-5034-a730-f7ad96f2c42e","sourceKey":"bank:LAG-BUA111:MGT-003","parentItemId":null,"revision":1,"payload":{"prompt":"One definition describes marketing management as the process of planning and executing the conception, pricing, promotion and distribution of ideas, goods and services. According to this definition, the purpose of this process is to:","options":["create exchanges that satisfy individual and organisational objectives","reduce government control of business","increase the number of employees in the firm","manufacture goods at the lowest cost"],"correctOption":0,"section":"Marketing Management","explanation":"This definition says the planning and execution of the conception, pricing, promotion and distribution of offerings is done to create exchanges that satisfy individual and organisational objectives. Options B, C and D are not the aim stated in the definition."}},{"itemId":"6c9c8a71-0f87-5ba5-bd20-e1207d9d7b9d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dcf4d6f9-43ab-5a22-a751-3911b59b91fa","sourceKey":"bank:LAG-BUA111:MGT-004","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing manager must answer two basic questions: 'What customers will we serve?' and 'How can we serve these customers best?' The answer to the second question is the firm's:","options":["sales quota","marketing audit","value proposition","target market"],"correctOption":2,"section":"Marketing Management","explanation":"The value proposition is the set of benefits or values a firm promises to deliver to customers to satisfy their needs; it answers how the firm will serve them best. The target market (option D) answers the first question, which customers to serve."}},{"itemId":"d3bf15f1-43dc-5659-8a7a-845c228048aa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e1c478e9-39b6-5399-b4fb-1bce4945ed3e","sourceKey":"bank:LAG-BUA111:MGT-005","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing management is often described as 'demand management'. This means that the marketing manager's task is to:","options":["fix the prices of all products sold in the national economy","leave the level of demand entirely to the forces of the market","always push demand up to the highest possible level, whatever the situation","influence the level, timing and composition of demand to meet the firm's objectives"],"correctOption":3,"section":"Marketing Management","explanation":"Marketing management deals with demand in whatever state it is, raising it, smoothing it, keeping it steady or even reducing it, so that it fits the organisation's objectives. Option C is wrong because sometimes the right task is to reduce demand, as in demarketing."}},{"itemId":"d3cac7af-c268-512f-ad57-b2d23d968417","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2ca3a6ac-ed3b-5fb7-a3c0-87ca5b05b48a","sourceKey":"bank:LAG-BUA111:MGT-006","parentItemId":null,"revision":1,"payload":{"prompt":"When a large part of the market dislikes a product and may even pay to avoid it, demand is negative. The marketing task in this situation is called:","options":["conversional marketing","stimulational marketing","demarketing","maintenance marketing"],"correctOption":0,"section":"Marketing Management","explanation":"Negative demand calls for conversional marketing, which tries to convert people's dislike into a positive attitude through product redesign, lower prices or better promotion. Stimulational marketing (option B) is for no demand, where people are simply unaware or uninterested."}},{"itemId":"4f8f1c70-150e-55a3-aeb8-a60699f4f6a9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3c1e43ee-0644-552e-8f81-5c90d1286a61","sourceKey":"bank:LAG-BUA111:MGT-007","parentItemId":null,"revision":1,"payload":{"prompt":"Many parents in a rural community avoid having their children immunised because they fear side effects, even though the vaccines are free. The demand state and matching marketing task are:","options":["latent demand - developmental marketing","negative demand - conversional marketing","no demand - stimulational marketing","unwholesome demand - countermarketing"],"correctOption":1,"section":"Marketing Management","explanation":"The parents actively dislike and avoid the vaccines, which is negative demand, so the task is conversional marketing to change their beliefs and attitudes. It is not no demand (option C) because they are not merely indifferent, and the vaccine is beneficial, so countermarketing (D) does not apply."}},{"itemId":"ac433a70-56e3-5ecb-8b91-8b1fac7de973","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6a740f94-ab27-5de7-8432-71b66f82a7b3","sourceKey":"bank:LAG-BUA111:MGT-008","parentItemId":null,"revision":1,"payload":{"prompt":"Farmers in a village have never heard of a new solar-powered irrigation pump and show no interest in it. The marketing task here is:","options":["conversional marketing","stimulational marketing","synchromarketing","remarketing"],"correctOption":1,"section":"Marketing Management","explanation":"When the target market is unaware of or uninterested in a product, there is no demand, and stimulational marketing is used to create interest by linking the product to a need. Conversional marketing (option A) is for people who actively dislike a product, which is not the case here."}},{"itemId":"9f7301a9-cbda-5675-89e7-47c5f3c90fda","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cd4a8898-15b1-5d3e-b381-320e6ebb2ef6","sourceKey":"bank:LAG-BUA111:MGT-009","parentItemId":null,"revision":1,"payload":{"prompt":"Many Lagos commuters share a strong desire for a fast, safe and affordable way to beat traffic that no existing transport service satisfies. This situation is called ____ demand, and the task is ____ marketing.","options":["negative; conversional","latent; developmental","full; maintenance","irregular; synchromarketing"],"correctOption":1,"section":"Marketing Management","explanation":"Latent demand exists when many consumers share a strong need that no existing product satisfies, and developmental marketing measures that potential market and develops products to meet it. Option D would describe demand that is uneven over time, not an unmet need."}},{"itemId":"07b81022-2267-508d-b2d2-f7f9e3109cfd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"76e3f4ff-7fbe-58b8-9622-468dd76ac2a0","sourceKey":"bank:LAG-BUA111:MGT-010","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing task of reviving demand for a product whose sales are declining is called:","options":["demarketing","remarketing","countermarketing","maintenance marketing"],"correctOption":1,"section":"Marketing Management","explanation":"Remarketing deals with falling demand by finding new markets, changing product features or improving communication to reverse the decline. Demarketing (option A) and countermarketing (C) aim to reduce or destroy demand, which is the opposite."}},{"itemId":"7c9f3107-7962-5f42-a02f-78191063eba6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b0d52658-e439-56bd-91f3-3bda97ef3b4d","sourceKey":"bank:LAG-BUA111:MGT-011","parentItemId":null,"revision":1,"payload":{"prompt":"Sales of a once-popular malt drink have been falling for three years. The company changes the packaging, adds a new flavour and targets new age groups to reverse the decline. This is an example of:","options":["stimulational marketing","developmental marketing","demarketing","remarketing"],"correctOption":3,"section":"Marketing Management","explanation":"Falling demand calls for remarketing, a creative effort to revive demand through new markets, changed features or fresh promotion. Stimulational marketing (option A) applies where there was no demand at all, and demarketing (C) tries to reduce demand."}},{"itemId":"546c8dd3-cfdc-50ae-8509-6fa4e3fa436c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9b08aab3-a653-5c22-a329-b53134cdb125","sourceKey":"bank:LAG-BUA111:MGT-012","parentItemId":null,"revision":1,"payload":{"prompt":"When demand varies by season, day or hour, causing problems of idle or overworked capacity, the marketing task is called:","options":["conversional marketing","maintenance marketing","remarketing","synchromarketing"],"correctOption":3,"section":"Marketing Management","explanation":"Irregular demand is handled by synchromarketing, which tries to bring the timing of demand in line with supply using flexible pricing, promotion and other incentives. Maintenance marketing (option B) is used when demand is already at the desired level."}},{"itemId":"098d39f7-2b81-5fae-a0d6-36cb4f4b6223","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"715b1842-15f1-553a-b7bb-6c515d88718f","sourceKey":"bank:LAG-BUA111:MGT-013","parentItemId":null,"revision":1,"payload":{"prompt":"A cinema in Lekki is packed on Friday and Saturday nights but nearly empty on weekday afternoons, so it offers half-price tickets on weekday afternoons. This is an example of:","options":["remarketing","synchromarketing","demarketing","countermarketing"],"correctOption":1,"section":"Marketing Management","explanation":"The cinema faces irregular demand and uses lower off-peak prices to shift some customers to quiet periods, which is synchromarketing. It is not trying to reduce total demand (option C) or revive declining demand (A)."}},{"itemId":"201d03b0-fe3f-51a2-add5-9367d14c5758","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6bf9e21f-c2a0-56f2-bf0b-927219035d5c","sourceKey":"bank:LAG-BUA111:MGT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Hotels in Calabar are fully booked in December during the carnival season but have many empty rooms for the rest of the year. Which demand state does this describe?","options":["Irregular demand","Falling demand","Overfull demand","Latent demand"],"correctOption":0,"section":"Marketing Management","explanation":"Irregular demand varies with the season, day or time, leaving capacity overused at some times and idle at others. It is not overfull demand (option C) because the problem is only at certain times, and not falling demand (B) because demand is not declining year after year."}},{"itemId":"0b08ca41-4a17-5027-be23-8867bdf96e14","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6e9430fb-007a-5cae-8b1d-04b1b74dbce4","sourceKey":"bank:LAG-BUA111:MGT-015","parentItemId":null,"revision":1,"payload":{"prompt":"When a firm is satisfied with its current volume of business, the marketing task is to keep demand at that level despite changing consumer preferences and increasing competition. This task is called:","options":["demarketing","stimulational marketing","developmental marketing","maintenance marketing"],"correctOption":3,"section":"Marketing Management","explanation":"Full demand calls for maintenance marketing: keeping quality high and continually checking customer satisfaction so demand stays at the desired level. Stimulational (option B) and developmental (C) marketing are used when demand is absent or not yet met."}},{"itemId":"96a2bb1c-f2e1-5835-9e84-600073e8cf1a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d903a005-6e12-5671-a9e6-6bea9e8b92cb","sourceKey":"bank:LAG-BUA111:MGT-016","parentItemId":null,"revision":1,"payload":{"prompt":"When demand is higher than an organisation can or wants to handle, the marketing task is called:","options":["synchromarketing","countermarketing","remarketing","demarketing"],"correctOption":3,"section":"Marketing Management","explanation":"Overfull demand calls for demarketing, which reduces demand temporarily or permanently, for example by raising prices or reducing promotion, without trying to destroy it. Countermarketing (option B) aims to destroy demand for something harmful."}},{"itemId":"9d4e711a-228d-5aa7-a7f4-e9c53f894784","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9cbe60da-1496-57a9-ba4e-022a6c9bcdde","sourceKey":"bank:LAG-BUA111:MGT-017","parentItemId":null,"revision":1,"payload":{"prompt":"During a severe dry season, a state water corporation runs adverts asking residents to reduce water use and raises charges for very high consumption. The marketing task being used is:","options":["demarketing","countermarketing","conversional marketing","maintenance marketing"],"correctOption":0,"section":"Marketing Management","explanation":"Demand for water is higher than the corporation can supply, so it uses demarketing to reduce consumption; water itself is not harmful. Countermarketing (option B) is for unwholesome products whose demand should be destroyed, and conversional marketing (C) tries to increase acceptance of a disliked product."}},{"itemId":"f2efaf0f-3b93-5875-939b-fe6988188d5a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9828988e-9f54-5e36-a598-0f258a1dd145","sourceKey":"bank:LAG-BUA111:MGT-018","parentItemId":null,"revision":1,"payload":{"prompt":"Unwholesome demand exists for products considered harmful, such as hard drugs or cigarettes. The marketing task of trying to destroy this demand is called:","options":["demarketing","conversional marketing","countermarketing","remarketing"],"correctOption":2,"section":"Marketing Management","explanation":"Countermarketing (also called unselling) aims to destroy demand for harmful products through fear appeals, higher prices and reduced availability. Demarketing (option A) only reduces demand for an acceptable product that is in short supply."}},{"itemId":"444f499f-e0af-5e17-9a85-2ecc072bfa0f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"635e527c-1f4b-5ac8-93c2-dd0464b1f8e3","sourceKey":"bank:LAG-BUA111:MGT-019","parentItemId":null,"revision":1,"payload":{"prompt":"A national agency runs campaigns in secondary schools showing the dangers of hard drugs, aiming to stop young people from wanting them at all. The demand state is:","options":["negative demand","overfull demand","unwholesome demand","irregular demand"],"correctOption":2,"section":"Marketing Management","explanation":"Hard drugs are harmful, so any demand for them is unwholesome, and the task is countermarketing to destroy that demand. Overfull demand (option B) is for good products in short supply, and negative demand (A) is when people dislike a product that is actually beneficial."}},{"itemId":"26565d57-e3ab-5106-891c-34e76aacca61","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dc3c70a1-4ec0-53d4-aca0-27b209c317d6","sourceKey":"bank:LAG-BUA111:MGT-020","parentItemId":null,"revision":1,"payload":{"prompt":"The key difference between demarketing and countermarketing is that:","options":["demarketing increases demand, while countermarketing reduces it","demarketing is used for falling demand, while countermarketing is used for irregular demand","demarketing applies only to services, while countermarketing applies only to goods","demarketing reduces demand for an acceptable product, while countermarketing tries to destroy demand for a harmful product"],"correctOption":3,"section":"Marketing Management","explanation":"Demarketing deals with overfull demand for a good product by reducing it, while countermarketing deals with unwholesome demand by trying to eliminate it. Option A is wrong because neither task increases demand, and B mixes up the tasks used for falling and irregular demand."}},{"itemId":"8220e199-0842-59ac-a381-5d388637d57f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"87e4fa61-bc41-5f5e-b81c-3b79666189ab","sourceKey":"bank:LAG-BUA111:MGT-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following demand states is NOT correctly matched with its marketing task?","options":["Latent demand - developmental marketing","Irregular demand - remarketing","Overfull demand - demarketing","Negative demand - conversional marketing"],"correctOption":1,"section":"Marketing Management","explanation":"Irregular demand is matched with synchromarketing, not remarketing; remarketing is for falling demand. Options A, C and D are all correctly matched."}},{"itemId":"4f64b97d-f7b6-54c8-9475-bcb16e57bb2c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"58f62bed-7e8c-545d-ac5d-5811eafb4686","sourceKey":"bank:LAG-BUA111:MGT-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the demand states that marketing management deals with?","options":["Irregular demand","Elastic demand","Unwholesome demand","Latent demand"],"correctOption":1,"section":"Marketing Management","explanation":"Elastic demand is an economics idea about how quantity demanded responds to price, not one of the demand states used to define marketing tasks. Latent, irregular and unwholesome demand (options A, C and D are all demand states with matching tasks."}},{"itemId":"814a5775-12a6-5a92-b96b-41fb0989aea2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e6d25af6-1deb-588c-beb0-2625e2f0885a","sourceKey":"bank:LAG-BUA111:MGT-023","parentItemId":null,"revision":1,"payload":{"prompt":"Under developmental marketing, the main task of the marketer is to:","options":["keep demand steady at its current, satisfactory level","discourage customers from buying a product that is harmful to them","measure the potential market and develop products that satisfy the unmet need","shift demand from busy periods to quiet periods using price incentives"],"correctOption":2,"section":"Marketing Management","explanation":"Developmental marketing deals with latent demand by measuring how big the potential market is and developing effective products to satisfy it. Option B describes countermarketing, A maintenance marketing and D synchromarketing."}},{"itemId":"085cc710-b4b2-510a-badc-019df33ed994","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"088a60ae-7e9e-5879-8837-69a92c4f0a8d","sourceKey":"bank:LAG-BUA111:MGT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Under conversional marketing, the marketer mainly tries to:","options":["reduce demand because the available supply is too small","revive demand for a product whose sales have been falling for years","find out why people dislike the product and change their attitude toward it","create awareness among people who have never heard of the product"],"correctOption":2,"section":"Marketing Management","explanation":"Conversional marketing deals with negative demand: the marketer analyses why the market dislikes the product and whether redesign, lower prices or more positive promotion can change beliefs and attitudes. Option D is stimulational marketing, A is demarketing and B is remarketing."}},{"itemId":"94db02e4-e3df-501b-9077-5db79bbda472","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"428e9a7f-a7fa-5677-a8f6-b593f80447a4","sourceKey":"bank:LAG-BUA111:MGT-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following shows the correct order of the marketing management process?","options":["Control, planning, analysis, implementation","Implementation, analysis, planning, control","Planning, analysis, control, implementation","Analysis, planning, implementation, control"],"correctOption":3,"section":"Marketing Management","explanation":"Marketing management starts with analysis of the firm's situation, then planning of strategies, then implementation of those plans, and finally control to check results and correct problems. Options A, B and C put the stages out of their logical order."}},{"itemId":"9b02118a-36c0-549c-a587-4d2e49dd78b3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"87090246-e52f-56ab-8aea-07561825d1ff","sourceKey":"bank:LAG-BUA111:MGT-026","parentItemId":null,"revision":1,"payload":{"prompt":"The first stage of the marketing management process, which involves a complete study of the company's situation, is:","options":["marketing audit only","marketing control","marketing analysis","marketing implementation"],"correctOption":2,"section":"Marketing Management","explanation":"Marketing analysis comes first: the firm studies its markets and environment, often using a SWOT analysis, to find opportunities and avoid threats. Implementation (option D) and control (B) come later, after plans have been made."}},{"itemId":"80de1b99-d517-54bd-b668-ac9f93b5a840","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ea1b04c4-772e-52d2-9305-632614f581bf","sourceKey":"bank:LAG-BUA111:MGT-027","parentItemId":null,"revision":1,"payload":{"prompt":"In a SWOT analysis, opportunities and threats are:","options":["the sales and profit targets the firm sets for the year","the four stages of the marketing management process","external factors the firm may exploit or must guard against","internal capabilities and limitations within the firm itself"],"correctOption":2,"section":"Marketing Management","explanation":"Opportunities and threats come from the external environment, such as changes in the economy, competitors or technology. Strengths and weaknesses are the internal factors described in option D."}},{"itemId":"b6e93510-b06f-5544-a506-47e141fdd1f0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dbd08258-9c4f-575c-b82f-85251616e672","sourceKey":"bank:LAG-BUA111:MGT-028","parentItemId":null,"revision":1,"payload":{"prompt":"A bakery in Surulere learns that a well-funded rival will soon open nearby selling bread at lower prices. In the bakery's SWOT analysis, this should be recorded as:","options":["a threat","a strength","an opportunity","a weakness"],"correctOption":0,"section":"Marketing Management","explanation":"A rival opening nearby is an external factor that could harm the bakery's performance, so it is a threat. Strengths (B) and weaknesses (D) are internal to the bakery, and this development is not favourable, so it is not an opportunity (C)."}},{"itemId":"ae5d22d4-569d-554d-b5f1-0f5e007bfa4c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"629bd3c9-5f31-5225-8220-23ed1637ea14","sourceKey":"bank:LAG-BUA111:MGT-029","parentItemId":null,"revision":1,"payload":{"prompt":"The stage of the marketing management process that involves deciding marketing objectives and strategies and preparing the marketing plan is:","options":["marketing analysis","marketing implementation","marketing control","marketing planning"],"correctOption":3,"section":"Marketing Management","explanation":"Marketing planning decides on the strategies that will help the firm reach its objectives and sets them out in a marketing plan. Analysis (option A) supplies the information for planning, while implementation (B) puts the plan into action."}},{"itemId":"064dab6c-59dd-5da2-aa5c-714e45004be3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1804f560-06e9-5c2d-aff9-e8c317094b2d","sourceKey":"bank:LAG-BUA111:MGT-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT normally a section of a marketing plan?","options":["Executive summary","Action programmes and budgets","Analysis of threats and opportunities","The personal tax records of each employee"],"correctOption":3,"section":"Marketing Management","explanation":"A marketing plan usually contains an executive summary, the current marketing situation, threats and opportunities, objectives, marketing strategy, action programmes, budgets and controls. Employees' personal tax records have nothing to do with marketing planning."}},{"itemId":"1bde1e4f-bf1f-5c8e-9aa6-438c8521dc6a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"07796c17-2823-5adb-adb9-5b7449e78c12","sourceKey":"bank:LAG-BUA111:MGT-031","parentItemId":null,"revision":1,"payload":{"prompt":"The process that turns marketing strategies and plans into marketing actions in order to accomplish marketing objectives is called:","options":["marketing implementation","marketing control","marketing analysis","marketing planning"],"correctOption":0,"section":"Marketing Management","explanation":"Marketing implementation is the stage where plans are turned into day-to-day actions. Planning (option D) decides what to do, while control (B) measures the results afterwards."}},{"itemId":"f03e9124-c6c3-5994-83dc-3069c5eedaf8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b669e911-92df-55e2-be5f-6e5d81426e2a","sourceKey":"bank:LAG-BUA111:MGT-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly contrasts marketing planning with marketing implementation?","options":["Planning addresses what and why; implementation addresses who, where, when and how","Planning addresses who and when; implementation addresses what and why","Planning is done after implementation has been completed","Implementation is only the job of top management, while planning is done by sales staff"],"correctOption":0,"section":"Marketing Management","explanation":"Planning decides what marketing activities to carry out and why, while implementation decides who will do them, where, when and how. Option B reverses the two, and C gets the order wrong since planning comes before implementation."}},{"itemId":"c4fe6e19-c16b-5e85-bde5-853e400b03fd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5a0c83b4-55d4-589d-99e6-6a6901322147","sourceKey":"bank:LAG-BUA111:MGT-033","parentItemId":null,"revision":1,"payload":{"prompt":"Measuring and evaluating the results of marketing strategies and plans and taking corrective action to ensure that objectives are achieved is called:","options":["marketing planning","marketing analysis","marketing control","marketing implementation"],"correctOption":2,"section":"Marketing Management","explanation":"Marketing control checks whether the plans are working by measuring results against goals and correcting any gaps. Implementation (option D) carries out the plan, and analysis (B) studies the situation before planning."}},{"itemId":"6b2a6c0e-ba58-58c8-bd8d-621fbfcdf0d1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"284afab8-28da-5055-ae0a-fd45b7291f27","sourceKey":"bank:LAG-BUA111:MGT-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the correct order of steps in the marketing control process?","options":["Set goals, measure performance, evaluate causes of any gaps, take corrective action","Measure performance, take corrective action, set goals, evaluate causes","Evaluate causes, set goals, take corrective action, measure performance","Take corrective action, set goals, measure performance, evaluate causes"],"correctOption":0,"section":"Marketing Management","explanation":"Control starts by setting specific goals, then measuring actual performance, then evaluating why actual and expected results differ, and finally taking corrective action to close the gap. Options B, C and D put corrective action or evaluation before there is anything to compare."}},{"itemId":"2ea5f7cc-ee8d-5eda-9e34-eb2d6ca0df21","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"74895665-ad7a-579f-9833-2c79364c8379","sourceKey":"bank:LAG-BUA111:MGT-035","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement correctly distinguishes operating control from strategic control?","options":["Operating control checks performance against the annual plan; strategic control checks whether basic strategies still fit opportunities","Operating control deals only with competitors, while strategic control deals only with the firm's employees","Operating control and strategic control are two names for exactly the same activity","Operating control is carried out once every ten years, while strategic control is carried out daily by sales staff"],"correctOption":0,"section":"Marketing Management","explanation":"Operating control compares current results with the annual plan and corrects them when needed, while strategic control looks at whether the firm's basic strategies are still well matched to its opportunities. Options B, C and D misdescribe the two types."}},{"itemId":"5022c6b3-0578-5b04-a12f-baeecfdee4a8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3b8fdccc-f87c-5d9c-a264-dbffdd29e630","sourceKey":"bank:LAG-BUA111:MGT-036","parentItemId":null,"revision":1,"payload":{"prompt":"A comprehensive, systematic, independent and periodic examination of a company's environment, objectives, strategies and activities to find problem areas and opportunities is called a:","options":["SWOT analysis","marketing audit","sales forecast","marketing plan"],"correctOption":1,"section":"Marketing Management","explanation":"A marketing audit is a full, independent check of the whole marketing operation and is a key tool of strategic control. A SWOT analysis (option A) is a simpler review of strengths, weaknesses, opportunities and threats, and a marketing plan (D) sets out what the firm intends to do."}},{"itemId":"6bb192c9-306f-5620-9ec3-9ca31be86def","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fb1e5e93-620d-5083-b8ed-a4cde5c893aa","sourceKey":"bank:LAG-BUA111:MGT-037","parentItemId":null,"revision":1,"payload":{"prompt":"Halfway through the year, the sales manager of a paint company finds that sales in the northern region are well below target, discovers the cause is weak distributor support, and adds extra incentives for distributors. Which stage of the marketing management process is this?","options":["Marketing implementation","Marketing control","Marketing planning","Marketing analysis"],"correctOption":1,"section":"Marketing Management","explanation":"Comparing actual sales with targets, finding the cause of the gap and taking corrective action are the steps of marketing control. Analysis (option D) and planning (C) happen before the plan is put into action."}},{"itemId":"8483ac93-dd0a-573e-acfc-3c259d5bbe38","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"88200b6b-5b91-5334-a199-a3621c2fa815","sourceKey":"bank:LAG-BUA111:MGT-038","parentItemId":null,"revision":1,"payload":{"prompt":"A drinks company has approved its plan to launch a new juice in Abuja. The marketing team now assigns staff to tasks, books the launch venue, schedules radio adverts and arranges delivery to retailers. Which stage is this?","options":["Marketing planning","Marketing implementation","Marketing control","Marketing analysis"],"correctOption":1,"section":"Marketing Management","explanation":"The plan has already been made, and the team is now deciding who does what, where, when and how, which is implementation. Planning (option A) is already finished, and control (C) would come later when results are measured."}},{"itemId":"9f4250ef-07f6-5d75-85fc-f620e068e97a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"99e720e0-11d6-55d9-9d54-72c9f5948b61","sourceKey":"bank:LAG-BUA111:MGT-039","parentItemId":null,"revision":1,"payload":{"prompt":"Before preparing next year's plan, a telecom firm studies its customers, competitors and the economic situation, and lists its strengths and weaknesses. Which stage of the marketing management process is this?","options":["Marketing analysis","Marketing control","Marketing implementation","Marketing audit follow-up"],"correctOption":0,"section":"Marketing Management","explanation":"Studying the market, competitors and environment and listing strengths and weaknesses before planning is marketing analysis, the first stage. Implementation (option C) and control (B) come only after a plan exists."}},{"itemId":"8f5f05a2-8ffa-53fc-a26f-6fb40a7b4be3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"75e1eeb8-02ca-5854-8b3f-7780855e5cd0","sourceKey":"bank:LAG-BUA111:MGT-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about marketing implementation is correct?","options":["Once a plan is written, results follow automatically","Implementation is less important than planning, so it can be left to chance","Implementation is only needed for new products","A brilliant marketing strategy counts for little if the company fails to implement it properly"],"correctOption":3,"section":"Marketing Management","explanation":"Many firms have good strategies but fail because they do not carry them out well, so implementation is just as important as planning. Options B and A wrongly suggest that a written plan is enough, and implementation is needed for all products, not only new ones as C claims."}},{"itemId":"6e3ff8de-697c-57e0-9b0e-9f44d0f4070e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7d6260c6-b940-5140-9bae-c52041bb87ae","sourceKey":"bank:LAG-BUA111:MGT-041","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing management is described as both an art and a science because it:","options":["applies only to artistic products such as music and films","follows fixed formulas that never change","uses systematic research and analysis as well as creativity and judgement","depends only on the personal taste of the manager"],"correctOption":2,"section":"Marketing Management","explanation":"Marketing management is a science because it uses research, data and analysis, and an art because it also needs creativity and good judgement to design offerings and messages. Option D ignores the scientific side, while B ignores the creative side."}},{"itemId":"4ad9ddad-3e83-595f-a1c7-28b1f17d651b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3954b3b0-1c8d-539b-ad59-bb6df295dc6b","sourceKey":"bank:LAG-BUA111:MGT-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of marketing management to an organisation?","options":["It coordinates product, price, promotion and distribution decisions toward the firm's objectives","It allows the firm to ignore customer needs and focus only on output","It replaces the need for separate finance and production departments","It guarantees that competing firms will eventually leave the market"],"correctOption":0,"section":"Marketing Management","explanation":"Marketing management brings the firm's marketing decisions together so that they support each other and the overall objectives. It cannot replace other departments (option C) or force competitors out (D), and it is built around customer needs, not ignoring them (B)."}},{"itemId":"87ec22cc-e996-5cf9-bdac-130c2aabf8ff","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c616c164-7760-513f-a512-36c9102d5d5e","sourceKey":"bank:LAG-BUA111:MGT-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an importance of marketing management?","options":["It guarantees that the firm will never make a loss","It helps the firm match its offerings to market demand","It guides decisions on target markets and the marketing mix","It helps the firm identify and respond to changes in customer needs"],"correctOption":0,"section":"Marketing Management","explanation":"Good marketing management improves a firm's chances of success, but no management activity can guarantee that a firm will never make a loss. Options B, C and D are real benefits of marketing management."}},{"itemId":"70e04daa-a4be-51ee-932f-0061d884d130","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8b75d7b2-9bfd-568f-87c6-b5c351c84ed9","sourceKey":"bank:LAG-BUA111:MGT-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of marketing management to society?","options":["It reduces the variety of products available to consumers","It removes the need for any consumer protection laws","It ensures that all firms in an industry charge the same prices","It helps direct scarce resources toward the goods and services people want"],"correctOption":3,"section":"Marketing Management","explanation":"By studying what consumers want and guiding production toward it, marketing management helps society use scarce resources more efficiently and raises living standards. Options A, B and C describe effects it does not have."}},{"itemId":"1c51cdfa-a6a6-52fb-b5e8-e5d7f97a6353","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5e4f160c-2a15-5292-8ce1-078bbae07d5e","sourceKey":"bank:LAG-BUA111:MGT-045","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing management is relevant to:","options":["only firms that sell consumer goods rather than services","only large manufacturing companies with national markets","both profit-seeking businesses and non-profit organisations","only firms that export goods to foreign markets"],"correctOption":2,"section":"Marketing Management","explanation":"Any organisation that needs to choose target audiences and build relationships with them, including hospitals, universities, churches and charities, can use marketing management. Options A, B and D wrongly restrict it to particular types of business."}},{"itemId":"f22ff295-e8ed-5a9f-921a-53287a684183","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7504207c-770f-570f-93f8-c7bdae05d98f","sourceKey":"bank:LAG-BUA111:MIX-001","parentItemId":null,"revision":1,"payload":{"prompt":"Putting the right product, or a combination of products, in the right place, at the right time and at the right price is a simple description of:","options":["The marketing environment","The marketing mix","The product life cycle","Market segmentation"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The marketing mix is the blend of decisions a firm makes about its product, where it is sold, when and at what price, so that it reaches customers in the right way. Option D is about dividing customers into groups, option A covers the forces around the firm, and option C tracks a product's sales over time."}},{"itemId":"c8617e78-5273-5de7-bc1e-d95bf0590a17","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b5780337-398b-5d65-a261-e8baecfc6f67","sourceKey":"bank:LAG-BUA111:MIX-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best defines the marketing mix?","options":["The stages a product passes through from launch until it is withdrawn","The uncontrollable external forces that affect a firm's marketing decisions","The process of dividing a broad market into smaller groups of similar buyers","The set of controllable marketing tools a firm blends to produce the response it wants in its target market"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"The marketing mix is made up of tools the firm itself controls, mainly product, price, place and promotion, which it combines to get the response it wants from target customers. Option B describes the marketing environment, option A describes the product life cycle, and option C describes market segmentation."}},{"itemId":"35f1a5e7-cf70-5cf0-8bb5-ee328c070f22","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bc1a4a12-eb83-5bdb-9534-7d166b63da9f","sourceKey":"bank:LAG-BUA111:MIX-003","parentItemId":null,"revision":1,"payload":{"prompt":"The 4Ps framework of the marketing mix was created by which marketing expert, and in what decade?","options":["Michael Porter, in the 1980s","E. Jerome McCarthy, in the 1960s","Philip Kotler, in the 1990s","Peter Drucker, in the 1950s"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"E. Jerome McCarthy grouped the marketing tools into product, price, place and promotion in the 1960s, and this became the foundation of the marketing mix idea. The other names in options A, C and D are well-known management writers, but none of them created the 4Ps."}},{"itemId":"2b424cba-3228-570f-9b88-3f1884726217","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9fe0e7a6-e7d6-5a2e-a6d5-c055135c45e8","sourceKey":"bank:LAG-BUA111:MIX-004","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from the 4Ps and the 7Ps of services marketing, the marketing mix is also associated with the 4Cs, which were developed in the:","options":["1960s","1950s","1990s","1980s"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"The 4Cs view the mix from the customer's side and were developed in the 1990s, long after the 4Ps. Option A is the decade of McCarthy's 4Ps, so it is the most common mix-up; options B and D are not the decades linked with the 4Cs."}},{"itemId":"7eb6a091-7360-5bef-9cf8-86952ce4eda3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"267ba0fd-1466-59f5-8e97-f012ac9a5a20","sourceKey":"bank:LAG-BUA111:MIX-005","parentItemId":null,"revision":1,"payload":{"prompt":"The 7Ps of services marketing add which three elements to the original 4Ps?","options":["Process, positioning and partnership","People, process and physical evidence","Physical evidence, publicity and performance","People, profit and packaging"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Services marketing extends the 4Ps with people, process and physical evidence, because a service is produced and delivered by staff, through procedures, in a setting customers can see. Options A, C and D each mix one correct P with words that are not part of the 7Ps."}},{"itemId":"e4066842-590f-5ab1-8c8a-83c10d715830","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"61b9f642-4653-5cef-b0c8-24a8debfb861","sourceKey":"bank:LAG-BUA111:MIX-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the 7Ps of the services marketing mix?","options":["Positioning","People","Process","Physical evidence"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Positioning is a separate strategic decision about how a brand should be seen in customers' minds; it is influenced by the mix but is not one of the 7Ps. Process (option C), physical evidence (option D) and people (option B) are the three Ps added to product, price, place and promotion."}},{"itemId":"b9a7c26c-2435-59cb-9a22-1013336fea6c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bd43f021-0aed-5038-b9d3-680b8deffddd","sourceKey":"bank:LAG-BUA111:MIX-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of McCarthy's original 4Ps?","options":["Price","People","Promotion","Place"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"People is one of the three extra Ps added for services, not one of the original four. Promotion (option C), place (option D) and price (option A) are original 4Ps together with product."}},{"itemId":"4fd66aa5-1c19-5e84-a7e6-58fab4cbd70e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ade4cf54-225a-5a18-bb35-b1204607534c","sourceKey":"bank:LAG-BUA111:MIX-008","parentItemId":null,"revision":1,"payload":{"prompt":"In marketing, a product is best defined as:","options":["Anything that can be offered to a market for attention, acquisition, use or consumption that might satisfy a want or need","Only a physical good manufactured in a factory","The activities that make a good available to target customers","The amount of money charged for a good or service"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"A product is anything offered to satisfy a want or need, so it can be a physical good, a service, an experience or even an idea. Option B is too narrow because services are products too, option D defines price, and option C defines place."}},{"itemId":"b69d1898-38d6-5587-b249-27760df3d9bb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"076872fb-e2ee-5623-a36e-617134f5e1d1","sourceKey":"bank:LAG-BUA111:MIX-009","parentItemId":null,"revision":1,"payload":{"prompt":"A buyer pays N850,000 for a generator in Ibadan. What he really wants is to keep his shop running during power cuts. In terms of product levels, 'keeping the shop running during power cuts' is the:","options":["Actual product","Augmented product","Core customer value (core benefit)","Product line"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"The core level is the basic need or benefit the customer is really buying, here reliable power for the shop. Option A is the generator itself with its brand, features and design, option B is the extra services such as warranty or installation, and option D is a group of related products, not a product level."}},{"itemId":"5347aabb-55bb-5cc7-b14f-52e071b58319","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f47189dd-c173-5514-8160-5b107bd1d104","sourceKey":"bank:LAG-BUA111:MIX-010","parentItemId":null,"revision":1,"payload":{"prompt":"A product's brand name, features, design, quality level and packaging together make up which level of the product?","options":["The product mix","The core customer value","The actual product","The augmented product"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"The actual product is the tangible offering built around the core benefit: its brand name, features, design, quality and packaging. Option B is the basic benefit the customer seeks, option D adds services like delivery and warranty, and option A is the full set of products a company sells."}},{"itemId":"c8f00416-0c6e-541f-b589-b4f571f704dc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6cb6b83b-d3ca-5497-bc45-c09d40f792ea","sourceKey":"bank:LAG-BUA111:MIX-011","parentItemId":null,"revision":1,"payload":{"prompt":"An electronics store in Ikeja sells air conditioners with free delivery, free installation and a two-year warranty. These extra services form part of the:","options":["Core customer value","Physical evidence","Actual product","Augmented product"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"The augmented product is the additional consumer services and benefits built around the actual product, such as delivery, installation, warranty and after-sales support. Option A is the basic benefit (cool air), option C is the air conditioner itself with its brand and features, and option B is the visible environment of a service business."}},{"itemId":"6053d50f-db5c-553e-bb11-95c685df6ed1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ab4340fd-8f59-549c-b3b2-357228af8812","sourceKey":"bank:LAG-BUA111:MIX-012","parentItemId":null,"revision":1,"payload":{"prompt":"Bread, sachet water and toothpaste are bought frequently, immediately and with little comparison or buying effort. They are classified as:","options":["Convenience products","Specialty products","Unsought products","Shopping products"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Convenience products are low-priced items customers buy often and with minimal effort, so they are made widely available. Option D describes goods compared carefully on price, quality and style, option B describes goods with strong brand preference that buyers make a special effort to get, and option C describes goods buyers do not normally think of buying."}},{"itemId":"39fdcfa5-3350-59a2-9f62-7afc8449421c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c8387128-b9a1-5c4c-8909-1e685ce5803f","sourceKey":"bank:LAG-BUA111:MIX-013","parentItemId":null,"revision":1,"payload":{"prompt":"Before buying furniture for her new flat in Yaba, Tolu visits several shops to compare quality, price and style. Furniture in this case is a:","options":["Shopping product","Convenience product","Unsought product","Specialty product"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Shopping products are bought less often and customers compare them carefully on suitability, quality, price and style, which is exactly what Tolu is doing. Option B is bought with little effort, option D has a strong brand following that people will travel for without comparing, and option C is something customers do not normally seek out."}},{"itemId":"ef80cb17-ea74-56ff-9f1a-c6595d763a0b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"677df885-9a20-5f38-8f1d-5cbe7fd5a729","sourceKey":"bank:LAG-BUA111:MIX-014","parentItemId":null,"revision":1,"payload":{"prompt":"A collector in Abuja will only buy one particular luxury watch brand and is willing to travel to Lagos to get it from the only authorised dealer. To him the watch is a:","options":["Specialty product","Convenience product","Unsought product","Shopping product"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Specialty products have unique characteristics or brand identification for which buyers make a special purchase effort, and they do not shop around comparing alternatives. Option D involves comparing several brands, option B involves little effort, and option C is something the buyer does not actively want."}},{"itemId":"9df73e66-27c6-54fc-9cd0-b2963af5ea16","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2db0ac60-4252-57dd-bc6c-e247d40f87f8","sourceKey":"bank:LAG-BUA111:MIX-015","parentItemId":null,"revision":1,"payload":{"prompt":"Life insurance and funeral services are products most consumers do not know about or do not normally think of buying until a need arises. They are classified as:","options":["Shopping products","Unsought products","Convenience products","Specialty products"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Unsought products are those customers either do not know about or do not normally think of buying, so they need a lot of advertising and personal selling. Option D is sought eagerly because of brand loyalty, option A is compared actively, and option C is bought routinely."}},{"itemId":"ab1f40dc-db77-5905-a695-0b1b6d1e82f1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c3534c11-36fd-5f49-a677-4ec5584f1b33","sourceKey":"bank:LAG-BUA111:MIX-016","parentItemId":null,"revision":1,"payload":{"prompt":"In the marketing mix, place refers to:","options":["The physical surroundings in which a service is delivered","The image a product holds in customers' minds","The geographic region in which customers live or work","The position and distribution of the product so that it is accessible to the target audience"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Place is about distribution: getting the product to a point where target customers can buy it, whether a high street shop, an online store or mail order. Option A describes physical evidence, option C describes geographic segmentation, and option B describes positioning."}},{"itemId":"3650bb66-42b2-5d59-98a2-decb920c434f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"80e9a4ea-ecfb-50d3-8218-3446ce3c4917","sourceKey":"bank:LAG-BUA111:MIX-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the distribution strategies under the place element of the marketing mix?","options":["Franchising","Intensive","Selective","Penetration"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Penetration is a pricing approach (setting a low price to win many buyers quickly), not a distribution strategy. Intensive (option B), selective (option C) and franchising (option A) are distribution strategies, together with exclusive distribution."}},{"itemId":"0910be66-132a-5ea1-b647-8ca376f5be5e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"145ad9fd-442a-5346-8d80-0d687dd02ba2","sourceKey":"bank:LAG-BUA111:MIX-018","parentItemId":null,"revision":1,"payload":{"prompt":"A soft drink company wants its product stocked in every supermarket, kiosk, filling station and roadside stall in Nigeria. Which distribution strategy is it using?","options":["Franchising","Exclusive distribution","Intensive distribution","Selective distribution"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Intensive distribution means stocking the product in as many outlets as possible, which suits low-priced items bought often. Option B uses one or very few dealers, option D uses a limited number of chosen outlets, and option A lets independent owners run outlets under the company's brand."}},{"itemId":"807bd26c-79ef-51d0-aeba-0777f3493cf2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d83a33f4-7614-58d7-acdb-1f2a5c2955a9","sourceKey":"bank:LAG-BUA111:MIX-019","parentItemId":null,"revision":1,"payload":{"prompt":"A luxury car maker appoints only one dealer to sell its cars in the whole of Lagos State. This is an example of:","options":["Intensive distribution","Selective distribution","Exclusive distribution","Franchising"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Exclusive distribution gives a very limited number of dealers, often one per area, the sole right to sell the brand, which protects a prestige image. Option A uses as many outlets as possible, option B uses more than one but still a limited number of outlets, and option D involves licensing others to run outlets under the brand."}},{"itemId":"42e94b96-97ca-5a4c-9509-f852cb5c5283","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3cae8f34-7fd5-5d87-a0d1-47f6b0937c4b","sourceKey":"bank:LAG-BUA111:MIX-020","parentItemId":null,"revision":1,"payload":{"prompt":"A home appliance maker sells through a few carefully chosen retailers in each Nigerian city, rather than through every shop or through only one dealer. This is:","options":["Exclusive distribution","Intensive distribution","Selective distribution","Penetration pricing"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Selective distribution uses more than one, but fewer than all, of the outlets willing to carry the product, so the firm can build good relationships with chosen dealers. Option B uses every possible outlet, option A uses only one dealer per area, and option D is a pricing strategy, not a distribution one."}},{"itemId":"16e91eb4-1df4-5810-b38b-79b93e4f2ab4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8f4187af-9ce4-5cb0-a65a-5fe2e9f9d559","sourceKey":"bank:LAG-BUA111:MIX-021","parentItemId":null,"revision":1,"payload":{"prompt":"A popular fast-food brand allows independent business owners in Port Harcourt and Enugu to open outlets using its name, recipes and systems in return for fees. Which distribution strategy is this?","options":["Intensive distribution","Franchising","Selective distribution","Exclusive distribution"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Franchising lets independent owners operate outlets under the parent brand's name and system in exchange for fees, spreading the brand quickly. Options A, C and D describe how many existing outlets carry a product, not an arrangement where others run outlets in the brand's name."}},{"itemId":"4ec04e11-38d0-569e-945e-8d50a5525ccf","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f438c8ff-0d16-5856-b44b-64877c34999f","sourceKey":"bank:LAG-BUA111:MIX-022","parentItemId":null,"revision":1,"payload":{"prompt":"'Where do clients look for my product? Where do clients usually shop? Should I sell the product online?' These questions help a marketer develop decisions on which element of the marketing mix?","options":["Promotion","Place","Price","Process"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"These questions are about where customers shop and where the product should be available, which is the place or distribution decision. Option A concerns how to communicate with customers, option C concerns how much to charge, and option D concerns how the service is delivered."}},{"itemId":"c9d17f4d-6ea0-543e-9770-8172666bf882","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fa9d80ee-d882-562c-92e7-73f92ef99cd2","sourceKey":"bank:LAG-BUA111:MIX-023","parentItemId":null,"revision":1,"payload":{"prompt":"'When is the best time to reach customers? What strategy are competitors using? Should I use social media? Which channel best carries my message to my audience?' These questions guide decisions on which element of the marketing mix?","options":["Place","Product","Physical evidence","Promotion"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"These questions are about timing, channels and messages for communicating with customers, which is promotion. Option A is about where the product is made available, option B is about what is offered, and option C is about what customers see when they deal with the business."}},{"itemId":"c1325aa4-40af-5a13-9905-0061f46492b9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5eca56b5-6315-5801-9954-4129035868d7","sourceKey":"bank:LAG-BUA111:MIX-024","parentItemId":null,"revision":1,"payload":{"prompt":"'What does the client want from the product? How, where and why does the client use it?' A marketer asks these questions mainly to get which element of the marketing mix right?","options":["Product","Promotion","Place","Price"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"These questions help the firm design a product that meets customer needs better than competitors' offerings. Option D deals with the amount charged, option C with where the product is sold, and option B with how it is communicated."}},{"itemId":"44884868-8f79-5e21-89e3-84cfb082c0f4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1132c190-a995-56de-9cc7-6e467bc839b3","sourceKey":"bank:LAG-BUA111:MIX-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a promotion tool?","options":["Advertising","Franchising","Public relations","Sales promotion"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Franchising is a way of distributing a brand through independently owned outlets, so it belongs to place. Public relations (option C), sales promotion (option D) and advertising (option A) are all tools used to communicate with customers."}},{"itemId":"94e36760-f71b-5182-9f87-c8a2ef12a8ba","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c123cad7-4423-5a25-be3f-b2b7b058a43b","sourceKey":"bank:LAG-BUA111:MIX-026","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket in Surulere runs a 'buy two tins of milk, get one free' offer for two weeks to boost sales. Which promotion tool is this?","options":["Advertising","Public relations","Personal selling","Sales promotion"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Sales promotion uses short-term incentives such as free gifts, discounts and bonus packs to encourage buying now. Option B builds goodwill and a good public image, option A is paid non-personal communication through media, and option C is face-to-face selling by sales staff."}},{"itemId":"e33d90c8-5cc8-5065-a4b8-f55a38caed1f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cac4a28e-5a75-5038-b80b-d935db5f1da4","sourceKey":"bank:LAG-BUA111:MIX-027","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage company sponsors a free community health walk in Ibadan and sends a press release about it to newspapers, to build goodwill and a positive image. Which promotion tool is this?","options":["Physical evidence","Public relations","Personal selling","Sales promotion"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Public relations aims to build good relations with the public and a favourable corporate image, often through sponsorships, events and news stories. Option D uses short-term buying incentives, option C is direct selling by sales staff, and option A is not a promotion tool at all."}},{"itemId":"ccd3ac58-422b-581c-884c-b4153d605df6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"95c1bec0-314c-5715-ba7c-7e1e199373f8","sourceKey":"bank:LAG-BUA111:MIX-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of the marketing mix produces revenue for the firm, while the other elements mainly represent costs?","options":["Promotion","Place","Price","Product"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Price is the amount customers pay, so it is the element that brings money in and determines profit. Promotion (option A), product (option D) and place (option B) all require the firm to spend money."}},{"itemId":"10dac4ba-f2c8-5b5f-9b14-b84daf0159aa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cd7ed0d9-3b5a-5de3-b890-795630c37060","sourceKey":"bank:LAG-BUA111:MIX-029","parentItemId":null,"revision":1,"payload":{"prompt":"A shopper assumes that a N28,000 perfume must be of better quality than a N3,500 perfume, without trying either. This shows that price:","options":["Shapes how consumers perceive a product's quality","Is decided only by the firm's production cost","Has no effect on demand for a product","Is part of the product's physical evidence"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Price sends a signal: consumers often see a higher-priced product as better in quality and ability than a cheaper one. Option C is wrong because price affects both sales and demand, option B ignores how customers react to price, and option D confuses price with what customers see in the business setting."}},{"itemId":"1c9a6984-aad5-56c3-bf4e-ff10a9b055c3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ade36c5d-f5c9-5731-a193-d6f43ac86d7d","sourceKey":"bank:LAG-BUA111:MIX-030","parentItemId":null,"revision":1,"payload":{"prompt":"A brand-new cosmetics company plans to charge very high prices at launch. Why is the target audience unlikely to accept these prices?","options":["A new product has no production costs to recover","Customers always choose the cheapest product available","The brand is just starting out, so customers do not yet recognise or trust it","High prices are not allowed for new products in Nigeria"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"A new brand has not yet built recognition and trust, so customers are reluctant to pay a premium for it; that comes with time. Option D is invented, option B is too extreme because many buyers pay more for trusted brands, and option A is false because new products do have costs."}},{"itemId":"f5c127c5-f943-5d77-ab74-9859c409ea06","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ed858124-6c67-5fcd-b051-31c5692d28bc","sourceKey":"bank:LAG-BUA111:MIX-031","parentItemId":null,"revision":1,"payload":{"prompt":"A technology firm launches a new smartphone in Lagos at N1,200,000, selling first to buyers who want the newest model, and then lowers the price step by step to reach more buyers. This pricing strategy is:","options":["Price skimming","Cost-plus pricing","Penetration pricing","Psychological pricing"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Price skimming sets a high initial price for a new product to collect the most revenue from buyers willing to pay it, then lowers the price over time. Option C does the opposite by starting low to win share quickly, option B adds a fixed markup to cost, and option D uses prices like N999 to influence perception."}},{"itemId":"6e7233fd-ccaf-535c-a90f-2305e6c66bb2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7c27a0ef-03a4-511b-a4dd-08f042f22bb5","sourceKey":"bank:LAG-BUA111:MIX-032","parentItemId":null,"revision":1,"payload":{"prompt":"A new mobile network enters the Nigerian market with call rates far below those of established networks, aiming to win many subscribers quickly. This is:","options":["Premium pricing","Cost-plus pricing","Price skimming","Penetration pricing"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Penetration pricing sets a low initial price to attract a large number of buyers quickly and win a large market share. Option C starts with a high price, option A keeps prices high to signal quality, and option B simply adds a markup to cost without aiming at fast share gains."}},{"itemId":"16d81360-a2ea-50a2-bdb7-5189480facb3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9a5048a-fdd7-5b75-a391-cdb16c2e0177","sourceKey":"bank:LAG-BUA111:MIX-033","parentItemId":null,"revision":1,"payload":{"prompt":"A bank branch in Ikeja simplifies its account-opening steps so that a new account now takes 30 minutes instead of two days. Which element of the services marketing mix has it improved?","options":["People","Process","Promotion","Physical evidence"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Process covers the procedures and flow by which a service is delivered; making the business efficient, helpful and timely improves it. Option A concerns the staff who deliver the service, option D concerns what customers see such as branding and premises, and option C concerns communication."}},{"itemId":"f784d4a7-f030-56cb-a850-baa184dea4eb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4a8a276f-e899-5090-96a0-84c17e0921ae","sourceKey":"bank:LAG-BUA111:MIX-034","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from making a business easy to deal with, a good process in the marketing mix also:","options":["Removes the need to train staff","Guarantees the business the highest price in the market","Saves time and money and keeps the standard of service consistent","Replaces the need for promotion"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"An efficient process saves time and money and keeps service quality consistent, which builds brand reputation and customer loyalty. Option A is wrong because staff still need training under the people element, option B overstates what process can do, and option D is wrong because promotion is still needed."}},{"itemId":"6e4ec23d-7992-5708-9b7d-61017e9d0763","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5092234f-6e2f-5e17-9e3e-ec522d1d08a8","sourceKey":"bank:LAG-BUA111:MIX-035","parentItemId":null,"revision":1,"payload":{"prompt":"A hotel in Victoria Island sends all its front-desk and customer service staff on a two-week training programme so they serve guests better. Which element of the marketing mix is it strengthening?","options":["People","Process","Place","Product"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"The people element covers those who deliver the marketing and service, and the firm needs staff who are fully trained for the job. Option B is about procedures rather than staff skills, option C is about distribution, and option D is about the offering itself."}},{"itemId":"4230c6ac-4804-569a-8127-24db4e9cdf55","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8b209794-74f1-5e31-b27a-36e85d2abf60","sourceKey":"bank:LAG-BUA111:MIX-037","parentItemId":null,"revision":1,"payload":{"prompt":"Everything a customer sees or hears when interacting with a business, such as its branding, packaging and shop space, is referred to as:","options":["Place","Promotion","Process","Physical evidence"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Physical evidence is the visible and audible side of the business, including branding, packaging, premises and how staff look and behave. Option A is distribution, option B is marketing communication, and option C is the way the service is delivered."}},{"itemId":"28c39325-e82c-54c0-9cbc-6b84b537ef1b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"017366d0-04bc-5b79-87bd-906c7353d11d","sourceKey":"bank:LAG-BUA111:MIX-038","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is part of a business's physical evidence?","options":["Its branding and product packaging","The way its staff and sales representatives act and dress","Its physical space, such as a shop","All of the above"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Physical evidence covers everything customers see or hear when dealing with the business, so it includes branding and packaging, the shop itself and how staff act and dress. Since options A, B and C are all examples, all of the above is correct."}},{"itemId":"29807cac-ac00-5392-b53c-5ea35eb8e60d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c2e9f749-3fc4-50fc-814e-15faf00f0036","sourceKey":"bank:LAG-BUA111:MIX-039","parentItemId":null,"revision":1,"payload":{"prompt":"A restaurant in Lekki repaints its dining hall, installs new lighting, reprints its menus and puts up a new signboard. Which element of the services marketing mix is it changing?","options":["Price","Physical evidence","People","Process"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The look of the premises, menus and signboard are things customers see, so they form the restaurant's physical evidence. Option D is about how orders are taken and served, option C is about staff, and option A is about how much is charged."}},{"itemId":"2e014399-5349-5cf3-a517-f259dba96584","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5581da97-b451-5776-8e5f-a355c65cf8ae","sourceKey":"bank:LAG-BUA111:MIX-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about the elements of the marketing mix is correct?","options":["The elements work together, and they also affect segmentation, targeting and positioning decisions","Each element should be planned separately without reference to the others","The mix is fixed once set and never changes over a product's life","Only the product element affects positioning"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"The Ps must work together to make the business successful, and they also shape how the firm segments, targets and positions itself. Option B contradicts this, option D wrongly limits positioning to one element, and option C is wrong because the mix is adjusted as the product moves through its life cycle."}},{"itemId":"3a010a47-36e0-5d31-9e5c-8c502db62e48","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"33684885-32fc-53be-8c3c-d5810bcf4b11","sourceKey":"bank:LAG-BUA111:MIX-041","parentItemId":null,"revision":1,"payload":{"prompt":"When the 4Ps are viewed from the customer's point of view as the 4Cs, place corresponds to:","options":["Communication","Customer solution","Convenience","Cost"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Seen from the buyer's side, place is about how easy it is to obtain the product, which is convenience. Option A matches promotion, option D matches price, and option B matches product."}},{"itemId":"3c23506e-7601-5a32-9508-ec7a93b441f8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"120c3665-a942-57f8-92e6-c5135e596c52","sourceKey":"bank:LAG-BUA111:MIX-042","parentItemId":null,"revision":1,"payload":{"prompt":"The course of a product's sales and profits over its lifetime is known as the:","options":["Marketing mix","Product life cycle","Product mix","Adoption process"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The product life cycle traces how a product's sales and profits change from launch through growth and maturity to decline. Option A is the set of marketing tools, option C is the full range of products a firm sells, and option D is the mental steps an individual goes through in accepting a new product."}},{"itemId":"00153522-72c2-50f3-b459-53e7e64ed7b6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1fbb500a-4a5b-56be-8074-374dfb2e0d1d","sourceKey":"bank:LAG-BUA111:MIX-044","parentItemId":null,"revision":1,"payload":{"prompt":"Once a product reaches the sales decline phase of its life cycle, marketers need to:","options":["Return the product to the introduction stage by relaunching it unchanged","Stop all marketing activity immediately","Raise prices to the highest level possible","Find new ways to increase sales again"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"In decline, marketers must look for new ways to lift sales, for example by repositioning, finding new uses, or deciding whether to keep, harvest or drop the product. Option B gives up without analysis, option C would usually speed up the fall in demand, and option A would not change anything customers care about."}},{"itemId":"15656237-671e-5ada-b441-a00ad2e4c333","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"26c724d5-7449-523a-bd86-4bc51602b6df","sourceKey":"bank:LAG-BUA111:MIX-045","parentItemId":null,"revision":1,"payload":{"prompt":"A new brand of plantain chips was launched six months ago. Sales are slow, few customers know it, there are almost no direct competitors, and the firm is spending heavily on making people aware of it. The product is in the:","options":["Decline stage","Growth stage","Introduction stage","Maturity stage"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Slow sales, low awareness, few competitors and heavy awareness spending are signs of the introduction stage. Option B would show rapidly rising sales and new competitors, option D would show high but levelling sales and strong competition, and option A would show falling sales."}},{"itemId":"c9d9b00b-3adb-5345-a906-165dd3436dff","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0be79715-82b1-5603-b7f6-f587bcf4fa15","sourceKey":"bank:LAG-BUA111:MIX-046","parentItemId":null,"revision":1,"payload":{"prompt":"A bottled-water brand's yearly sales rose from N10 million to N25 million and then to N60 million over three years, while several new competitors entered the market. The brand is most likely in the:","options":["Introduction stage","Maturity stage","Decline stage","Growth stage"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Sales more than doubling each year while new competitors are attracted by the opportunity is the classic picture of the growth stage. Option A would show slow sales with few rivals, option B would show sales levelling off, and option C would show sales falling."}},{"itemId":"3bac0289-0ea2-520e-b9c7-d098b982a4ec","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2e85e6e0-eac5-582f-bd24-595486bcaac0","sourceKey":"bank:LAG-BUA111:MIX-047","parentItemId":null,"revision":1,"payload":{"prompt":"In which stage of the product life cycle do sales typically reach their peak and the stage usually last longer than the others?","options":["Growth","Maturity","Decline","Introduction"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"In maturity, sales growth slows and sales peak, and this stage normally lasts longer than the others, so most products on the market are mature. Option A has rising but not yet peak sales, option D has low sales, and option C has falling sales."}},{"itemId":"4662ebc4-c956-5a1f-a872-42b33969f186","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8761e3ec-8ff8-5e42-8144-b60093dfae9e","sourceKey":"bank:LAG-BUA111:MIX-048","parentItemId":null,"revision":1,"payload":{"prompt":"In which stage of the product life cycle is the cost per customer typically highest?","options":["Introduction","Maturity","Decline","Growth"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"In the introduction stage, the firm spends heavily on distribution and promotion while only a few customers are buying, so the cost per customer is high. In growth (option D) costs per customer fall to an average level, and in maturity (option B) and decline (option C) they are low."}},{"itemId":"a757c99a-5d0e-575e-8510-cdf98ecb85e4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"28b2af47-ae2d-5911-a225-dbf810618eff","sourceKey":"bank:LAG-BUA111:MIX-049","parentItemId":null,"revision":1,"payload":{"prompt":"The customers who buy a product mainly during its decline stage are usually described as:","options":["Early adopters","Middle majority","Innovators","Laggards"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Laggards are the last to adopt and are typically the main buyers left when a product is in decline. Option C buys at introduction, option A buys during growth, and option B makes up the bulk of buyers in maturity."}},{"itemId":"031bf0e7-dee7-504c-b3c7-95125789a8c9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2c015cc3-9b3d-5f8c-9be2-765ede434913","sourceKey":"bank:LAG-BUA111:MIX-050","parentItemId":null,"revision":1,"payload":{"prompt":"'Use heavy sales promotion to entice trial' and 'build product awareness among early adopters and dealers' are recommended strategies for which stage of the product life cycle?","options":["Introduction","Decline","Maturity","Growth"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"At introduction few people know the product, so the firm promotes heavily to get people to try it and to get dealers to stock it. In growth (option D) demand is already strong so sales promotion is reduced, in maturity (option C) promotion encourages brand switching, and in decline (option B) it is cut to a minimum."}},{"itemId":"f922813f-4326-51f1-b2db-4f750daf211e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5d9cb116-4574-500b-9756-ae5fec00e9bf","sourceKey":"bank:LAG-BUA111:MIX-052","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's advertising for a well-established detergent now stresses brand differences and benefits, and it increases sales promotion to encourage customers of rival brands to switch. The detergent is in the:","options":["Growth stage","Decline stage","Introduction stage","Maturity stage"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"In maturity, the market is crowded, so firms stress how their brand differs and use promotions to win customers from competitors. Option A focuses on building mass-market awareness while demand rises, option C focuses on getting first trial, and option B cuts promotion to a minimum."}},{"itemId":"8fb60d4b-02c0-5e7e-81f9-4562d07a0ee9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b49b037f-8638-51ea-86fc-692fbe492507","sourceKey":"bank:LAG-BUA111:MIX-053","parentItemId":null,"revision":1,"payload":{"prompt":"Phasing out weak items, cutting prices, closing unprofitable outlets and reducing advertising to the level needed to keep hard-core loyal customers are strategies for which stage?","options":["Maturity","Growth","Introduction","Decline"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"In decline, sales and profits are falling, so the firm trims weak products and outlets and spends only enough to keep its most loyal buyers. Option A defends market share with strong promotion, option B expands distribution and product extensions, and option C invests to build awareness."}},{"itemId":"92d474e5-3414-5f9a-8e6e-f681a11d6909","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d7ece00f-2cdd-5a65-81ab-48896fe1f75d","sourceKey":"bank:LAG-BUA111:MIX-054","parentItemId":null,"revision":1,"payload":{"prompt":"A mature brand of tea in Nigeria starts promoting iced tea for hot afternoons to young people who never drank tea before, trying to find new users and new uses. This is an example of:","options":["Harvesting the product","Penetration pricing","Modifying the market","Modifying the product"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Modifying the market means increasing consumption by finding new users, new market segments or new uses for the product. Option D changes the product's features, quality or style, option A is a decline-stage tactic of cutting costs, and option B is a launch pricing strategy."}},{"itemId":"61e89822-4f36-549a-a828-bac89317a482","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1cdc90b4-bd2d-5e8a-a1ea-07565676e714","sourceKey":"bank:LAG-BUA111:MIX-055","parentItemId":null,"revision":1,"payload":{"prompt":"A noodles brand in decline stops spending on research and advertising and cuts other costs, hoping that sales hold up for a while so that it earns extra cash in the short run. This decline-stage strategy is called:","options":["Maintaining","Harvesting","Dropping","Modifying the market"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Harvesting means reducing costs such as research, advertising and sales force spending while hoping sales hold up, which raises short-run profit. Option A keeps the brand going without change, option C sells it off or withdraws it, and option D is a maturity-stage move to find new users."}},{"itemId":"9d3a0464-e701-5d7b-91a3-6816a5a6afa5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cb720432-2c95-5ab4-8ade-fe9b6ef33dce","sourceKey":"bank:LAG-BUA111:MIX-056","parentItemId":null,"revision":1,"payload":{"prompt":"A product that enjoys a short period of unusually high sales driven by consumer enthusiasm and immediate popularity, and then quickly fades, is called a:","options":["Fad","Fashion","Specialty product","Style"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"A fad rises quickly, is adopted with great zeal, peaks early and declines very fast. Option D is a basic, distinctive mode of expression that can last for generations, option B is a currently popular style that grows and declines slowly, and option C is a product class, not a life cycle pattern."}},{"itemId":"2645ed1f-df3a-54db-8b5f-95bb434f05cb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ba59ce96-c6c2-5372-b91c-ee1094220cce","sourceKey":"bank:LAG-BUA111:MIX-057","parentItemId":null,"revision":1,"payload":{"prompt":"In the services marketing mix, the idea of 'physical evidence' is especially important because services are:","options":["Usually stored in warehouses before sale","Always cheaper than goods","Produced without the involvement of staff","Intangible, so customers look for visible cues to judge quality"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Services cannot be seen, touched or tasted before purchase, so customers judge them by what they can see, such as the premises, branding and staff appearance. Option B is not generally true, option A is wrong because services cannot be stored, and option C is wrong because staff are usually central to service delivery."}},{"itemId":"b746b175-777e-5b1d-966c-0560ca55d08c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8aaa487f-f155-5546-b6be-74c5feef8c3b","sourceKey":"bank:LAG-BUA111:MIX-058","parentItemId":null,"revision":1,"payload":{"prompt":"Empty seats on a Lagos-Abuja flight that departs half full cannot be stored and sold the next day. This characteristic of services is called:","options":["Perishability","Intangibility","Inseparability","Variability"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Perishability means services cannot be stored for later sale or use, so unused capacity is lost. Option B means services cannot be seen or touched before purchase, option C means services are produced and consumed at the same time, and option D means quality depends on who provides the service and when."}},{"itemId":"5a5d51c6-31aa-53cc-bf63-b41f0d9c371f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a32d9cf9-9548-59e7-83a6-a80119e0c233","sourceKey":"bank:LAG-BUA111:MIX-059","parentItemId":null,"revision":1,"payload":{"prompt":"Some customers at a barbing salon in Yaba wait for one particular barber because the quality of a haircut differs from one barber to another. This characteristic of services is called:","options":["Intangibility","Variability","Inseparability","Perishability"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Variability means service quality depends on who provides it, when, where and how, which is why the people and process elements need careful management. Option D means services cannot be stored, option A means they cannot be seen before purchase, and option C means they cannot be separated from their providers."}},{"itemId":"c8bb7ee1-45e7-5213-9b37-24fe8793f6cc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7c5ed038-3b62-5d50-ad78-997790ad5e2b","sourceKey":"bank:LAG-BUA111:MIX-060","parentItemId":null,"revision":1,"payload":{"prompt":"In a year when total industry sales of bottled water in a state are N800 million, one brand sells N120 million worth. What is the brand's market share?","options":["15%","1.5%","85%","6.67%"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Market share is the firm's sales divided by total industry sales, times 100: 120 / 800 x 100 = 15%. Option C is the share held by all other brands (100 - 15), option D comes from dividing the wrong way round (800 / 120), and option B comes from misplacing the decimal point when converting 0.15 to a percentage."}},{"itemId":"0fc49de7-910a-5bbd-9704-c367ea4cc86a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"aeba8167-055d-5fee-b3ec-85541dbe410f","sourceKey":"bank:LAG-BUA111:MKT-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which companies create value for customers and build strong customer relationships in order to capture value from customers in return is best described as:","options":["Public relations","Personal selling","Marketing","Sales promotion"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing is the whole process of creating customer value and building strong customer relationships so that the firm captures value (sales, profit, loyalty) in return. Options A, B and D are narrower promotional tools that form only a small part of this process."}},{"itemId":"510ccbd9-37fe-5974-ad9b-309f0f42226a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"83a022ad-edb2-5f8b-92c2-b8df88f524c3","sourceKey":"bank:LAG-BUA111:MKT-002","parentItemId":null,"revision":1,"payload":{"prompt":"The American Marketing Association defines marketing as the activity, set of institutions and processes for creating, communicating, delivering and exchanging offerings that have value for:","options":["the producing firm and its direct competitors","shareholders, managers and employees only","customers, clients, partners and society at large","government regulators and tax authorities"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"The definition stresses that marketing offerings must have value for customers, clients, partners and society at large, not just for the firm. Option B limits value to people inside the firm, while A and D name groups that are not the main focus of marketing value."}},{"itemId":"7956223e-f9a4-5a0f-8b60-19df5ea8c2df","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d63f823e-c95e-542d-9e2d-b6fd1f7f5750","sourceKey":"bank:LAG-BUA111:MKT-003","parentItemId":null,"revision":1,"payload":{"prompt":"One of the shortest good definitions of marketing describes it as:","options":["advertising products as widely as possible","meeting needs profitably","producing goods at the lowest possible cost","selling whatever the factory produces"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"'Meeting needs profitably' captures the two sides of marketing: satisfying customer needs and doing so at a profit. Option D describes a selling mindset, A is only promotion, and C is a production focus."}},{"itemId":"dbf12639-9c30-5aed-b411-6c7a9b3b068e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8090a394-cbfb-5bd6-ba79-36c0897b03ad","sourceKey":"bank:LAG-BUA111:MKT-004","parentItemId":null,"revision":1,"payload":{"prompt":"The statement 'the aim of marketing is to make selling superfluous' means that:","options":["firms should close down their sales force and stop all forms of personal selling","the customer should be understood so well that the product fits the customer and sells itself","products should be sold only through intermediaries so the producer does no selling","heavy promotion matters more than the product, because persuasion makes any product sell"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"The idea is that when a firm truly understands its customers, it offers products that fit their needs so well that little persuasion is needed. It does not mean firms should sack their salespeople as in option A, and it argues against relying on promotion as in D."}},{"itemId":"133f6515-badc-5c1b-8816-ef5be5f1ca05","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ddc6b9e2-6e20-541f-abd4-e9d060e8f4d1","sourceKey":"bank:LAG-BUA111:MKT-005","parentItemId":null,"revision":1,"payload":{"prompt":"The Chartered Institute of Marketing (UK) defines marketing as the management process responsible for ____ customer requirements profitably.","options":["advertising, persuading and selling","identifying, anticipating and satisfying","producing, pricing and selling","buying, storing and transporting"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"In this definition marketing is the management process responsible for identifying, anticipating and satisfying customer requirements profitably. Options A, C and D list individual business activities rather than the customer-focused tasks named in the definition."}},{"itemId":"f9f4654f-8b3e-5481-833e-0fbc4b8eb639","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"116a5671-7620-5544-a9f0-41f62f8c6e60","sourceKey":"bank:LAG-BUA111:MKT-006","parentItemId":null,"revision":1,"payload":{"prompt":"Defining marketing as 'a societal process by which individuals and groups obtain what they need and want through creating, offering and freely exchanging products and services of value with others' is an example of a ____ definition of marketing.","options":["social","production-oriented","managerial","legal"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A social definition shows the role marketing plays in society: it is how people and groups get what they need and want through free exchange. A managerial definition (option C) looks at marketing from the firm's point of view, such as 'the art of selling products'."}},{"itemId":"4e59d6ee-2f83-5f87-a8bf-ad7a83501e65","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fc3381ae-4ca2-531b-8517-f05658183fd3","sourceKey":"bank:LAG-BUA111:MKT-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about marketing is NOT correct?","options":["Marketing begins after goods have been produced and ends when they are sold","Selling and advertising are only part of marketing","Marketing starts before production by finding out what customers need","Marketing continues after the sale through customer service and relationship building"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing does not start at the factory gate and stop at the sale; it starts before production by identifying needs and continues after the sale to keep customers satisfied. Options B, C and D are all correct statements about the wide scope of marketing."}},{"itemId":"0ce82471-cc77-5953-8823-1cb430526cc4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f5316119-c2f8-5a86-9c17-78ed65d093cd","sourceKey":"bank:LAG-BUA111:MKT-008","parentItemId":null,"revision":1,"payload":{"prompt":"An early definition described marketing as 'the performance of business activities that direct the flow of goods and services from producer to consumer or user'. The main weakness of this definition is that it:","options":["ignores the physical movement of goods from producers to consumers","places far too much emphasis on long-term customer satisfaction","treats marketing as starting only after production, ignoring customer needs","wrongly includes non-profit organisations within the scope of marketing"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"This definition sees marketing mainly as moving goods that already exist from producer to consumer, so it leaves out the work of finding out what customers need before anything is produced. It says nothing about non-profits (option D) or customer satisfaction (B), and the flow of goods (A) is exactly what it does cover."}},{"itemId":"45b39e25-1c3b-50a5-b6f6-8fff95ff6ff2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dc281558-086d-5090-8501-e130be8b9b57","sourceKey":"bank:LAG-BUA111:MKT-009","parentItemId":null,"revision":1,"payload":{"prompt":"Defining marketing as 'a total system of business activities designed to plan, price, promote and distribute want-satisfying products to target markets to achieve organisational objectives' emphasises that marketing:","options":["is mainly the advertising and publicity function of a firm","is a set of related activities that work together, not a single activity","is concerned only with the physical distribution of goods","applies only to manufacturing firms and not to service firms"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Calling marketing a 'total system' means that planning, pricing, promotion and distribution are linked activities that must work together toward the firm's objectives. Option A reduces marketing to advertising and C to distribution, while nothing in the definition limits it to manufacturers as D claims."}},{"itemId":"e4b4cdc3-34e4-5786-9292-90b5ab2f2649","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9228b6fb-9b45-5041-861d-814f57e6e378","sourceKey":"bank:LAG-BUA111:MKT-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about what can be marketed is correct?","options":["Goods, services, ideas, places, persons and organisations can all be marketed","Only goods and services sold for profit can be marketed","Only the products of manufacturing firms can be marketed","Only physical goods can be marketed"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing applies to anything that can be offered to satisfy a need: goods, services, events, experiences, persons, places, organisations, information and ideas. Options B, C and D wrongly restrict marketing to physical or profit-making products."}},{"itemId":"04d33e1f-2890-5578-afae-4e9933a0122d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ab94a8e2-cc22-52f0-82e3-b26393c22e72","sourceKey":"bank:LAG-BUA111:MKT-011","parentItemId":null,"revision":1,"payload":{"prompt":"A state ministry of health runs radio jingles and street campaigns in Lagos persuading residents to wash their hands regularly to prevent cholera. No product is sold. This example shows that:","options":["marketing principles can be applied to ideas and non-profit causes","marketing applies only to private businesses","only physical goods can be the subject of an exchange","the campaign is not marketing because nothing is sold for money"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing ideas and social causes uses the same principles as marketing products: the ministry seeks a response (a change in behaviour) in exchange for the benefit of better health. Option D is wrong because marketing does not require a money sale, and B and C wrongly limit marketing to businesses and goods."}},{"itemId":"277eee9f-f24c-592d-80d8-24463d45951d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d7b6b3b7-c917-577a-add9-4332aa2ce1ea","sourceKey":"bank:LAG-BUA111:MKT-012","parentItemId":null,"revision":1,"payload":{"prompt":"States of felt deprivation, such as hunger, thirst or the desire to belong, are called human:","options":["wants","demands","offerings","needs"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Needs are states of felt deprivation, for example the need for food, safety, belonging or knowledge. Wants (option A) are the particular forms these needs take, and demands (B) are wants backed by buying power."}},{"itemId":"82e087c4-5689-51d2-bb24-adb53f0f2028","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"52abccbe-5d3f-51d7-b884-3fafddde8350","sourceKey":"bank:LAG-BUA111:MKT-013","parentItemId":null,"revision":1,"payload":{"prompt":"The form a human need takes as it is shaped by culture and individual personality is called a:","options":["transaction","want","need","demand"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A want is the specific form a need takes because of a person's culture and personality; a hungry person in one place may want amala while another wants rice. A need (option C) is the basic deprivation itself, and a demand (D) is a want backed by buying power."}},{"itemId":"7b630590-8199-50b2-8771-5f9d09af670c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a85ea1cf-3418-5126-b012-f9405ed6dc19","sourceKey":"bank:LAG-BUA111:MKT-014","parentItemId":null,"revision":1,"payload":{"prompt":"Wants that are backed by buying power are called:","options":["demands","exchanges","needs","wants"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"When a person both wants a product and is able (and willing) to pay for it, the want becomes a demand. Needs (option C) and wants (D) exist whether or not the person can pay."}},{"itemId":"412045c2-9672-5d62-9fe7-2d83d2f5fa22","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"097507e4-72dc-5c1d-97ae-38be05ff7ae9","sourceKey":"bank:LAG-BUA111:MKT-015","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde, a UNILAG student, is hungry. He would like a plate of jollof rice with chicken from his favourite canteen, and he has N2,000 in his pocket to pay for it. His desire specifically for jollof rice with chicken is best described as a:","options":["transaction","need","transfer","want"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Tunde's hunger is the need; his desire for one particular meal, jollof rice with chicken, is the want, the form his need takes. Option B would be his hunger itself, and no trade has yet taken place, so it is not a transaction as in A."}},{"itemId":"3a1eaa9b-a3d1-5e25-af17-0c96723ffd49","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b93aae75-f328-5f0e-b330-459c4da7d1b3","sourceKey":"bank:LAG-BUA111:MKT-016","parentItemId":null,"revision":1,"payload":{"prompt":"Ada earns N250,000 a month, has no savings and cannot get a loan, but she strongly desires a new luxury SUV costing N80 million. In marketing terms, Ada's desire for the car is:","options":["a want that is not yet a demand","a basic physical need","an effective demand for the car","a completed transaction"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Ada clearly wants the car, but without the buying power to pay for it her want does not count as a demand. Option C is wrong because demand needs buying power, and a luxury car is not a basic physical need as B suggests."}},{"itemId":"54e369f4-4053-54b0-b426-e2fa6aa22012","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"71efa38a-86b7-5a4c-acc4-583f9fef6da8","sourceKey":"bank:LAG-BUA111:MKT-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following statements about human needs is correct?","options":["Marketers create human needs through advertising","Needs and wants mean exactly the same thing","Needs are a basic part of human make-up and are not created by marketers","Needs exist only when a person has money to spend"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Basic needs such as food, safety, belonging and self-expression are part of being human; marketers do not invent them, though they influence wants. Option A confuses needs with wants, and D confuses needs with demands."}},{"itemId":"31541b74-1493-54bb-9c4c-de353527eced","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"088de0b2-328b-5969-8f2a-3e9b7f3f6093","sourceKey":"bank:LAG-BUA111:MKT-018","parentItemId":null,"revision":1,"payload":{"prompt":"The need for belonging and affection is classified as a ____ need.","options":["individual","economic","physical","social"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Human needs are usually grouped into physical needs (food, clothing, warmth, safety), social needs (belonging and affection) and individual needs (knowledge and self-expression). Belonging and affection therefore fall under social needs, not physical (C) or individual (A) needs."}},{"itemId":"25409871-05cd-5253-934e-897e10b38b2e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9d018663-5c82-5cd8-89f1-57893006de73","sourceKey":"bank:LAG-BUA111:MKT-019","parentItemId":null,"revision":1,"payload":{"prompt":"The needs for knowledge and self-expression are classified as ____ needs.","options":["physical","individual","social","safety"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Knowledge and self-expression are individual needs because they relate to a person's own growth. Physical needs (option A) cover food, clothing, warmth and safety, while social needs (C) cover belonging and affection."}},{"itemId":"2c4c8a11-34bc-5241-862e-f0e94425492b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a3a2ad10-922e-518e-8c20-e2022341d390","sourceKey":"bank:LAG-BUA111:MKT-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a physical need?","options":["Safety","Clothing","Food","Self-expression"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Self-expression is an individual need, not a physical one. Food, clothing and safety (options A, B and C) are all physical needs linked to bodily survival and protection."}},{"itemId":"a783a079-0780-566b-a971-ce8ead987f6a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e6aa0332-8022-59e4-8be8-9896301ea478","sourceKey":"bank:LAG-BUA111:MKT-021","parentItemId":null,"revision":1,"payload":{"prompt":"A hungry person in Ibadan wants amala and ewedu, while an equally hungry person in Enugu wants abacha. This difference best illustrates that:","options":["the same need can show up as different wants depending on culture","marketers created their hunger","the two people have completely different needs","neither person has buying power"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Both people share the same need (hunger), but their culture shapes the particular food they want. Option C is wrong because the need is identical, and B is wrong because marketers do not create basic needs."}},{"itemId":"4ea39c85-e68b-5b72-8562-b5088fae022d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"67655a18-cce7-5aee-a708-e13b8d52dba8","sourceKey":"bank:LAG-BUA111:MKT-022","parentItemId":null,"revision":1,"payload":{"prompt":"The act of obtaining a desired object from someone by offering something in return is called:","options":["coercion","transfer","self-production","exchange"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Exchange means getting something you want from another party by giving something of value in return; it is the core concept of marketing. A transfer (option B) gives something without receiving anything definite back, and coercion (A) takes it by force."}},{"itemId":"9c9423bd-78eb-5832-844f-5e2219c77771","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7e3cc7d5-9e11-53f6-8ced-c78cda2cb1a7","sourceKey":"bank:LAG-BUA111:MKT-023","parentItemId":null,"revision":1,"payload":{"prompt":"People can obtain products they want through self-production, coercion, begging or exchange. Marketing is based on which of these?","options":["Exchange","Self-production","Begging","Coercion"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing emerges when people decide to satisfy their needs and wants through exchange, giving something of value to get something of value. Self-production (option B) involves no other party, while coercion (D) and begging (C) give nothing in return."}},{"itemId":"d8f8bfc9-0865-594a-b236-cbc035cb32b6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c79030ad-d69c-5ee3-af5f-bf764e1ea9d2","sourceKey":"bank:LAG-BUA111:MKT-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a condition that must be met for exchange to take place?","options":["Each party must be free to accept or reject the offer","Both parties must use money as the medium of payment","Each party must have something that might be of value to the other","There must be at least two parties"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Exchange does not require money; a barter of yams for fertiliser is still an exchange. Options A, C and D are genuine conditions for exchange, along with the ability to communicate and deliver and the belief that it is desirable to deal with the other party."}},{"itemId":"c0dea237-a997-5cfa-8f78-01d3104904d1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c331b7ed-588a-5564-8588-dc04956ea915","sourceKey":"bank:LAG-BUA111:MKT-025","parentItemId":null,"revision":1,"payload":{"prompt":"A farmer in Kano has tomatoes to sell and a restaurant owner in Lagos wants to buy tomatoes, but neither knows the other exists and there is no way to send the goods. Which condition for exchange is missing?","options":["Each party must have something of value to the other","Each party must be free to reject the offer","Each party must be capable of communication and delivery","There must be at least two parties"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Both parties exist and each has something the other values, but they cannot contact each other or move the goods, so the condition of communication and delivery is not met. Options D and A are already satisfied in the scenario, and nothing suggests either party is forced, so B is not the problem."}},{"itemId":"c7bc27b9-d34c-519e-ad86-ccd59bc1856c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7385296c-cd4a-5c07-a707-4d1302f37543","sourceKey":"bank:LAG-BUA111:MKT-026","parentItemId":null,"revision":1,"payload":{"prompt":"Armed robbers stop a traveller and take his phone, leaving him a small amount of cash. This is NOT an exchange mainly because:","options":["cash was involved, and exchange must not involve cash","the phone had no real value to either of the parties","the traveller was not free to accept or reject the offer","there were fewer than two parties involved in the deal"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A true exchange requires each party to be free to accept or reject the offer; here the traveller was forced, so it is coercion, not exchange. There were two parties (option D), the phone had value (B), and the presence of cash (A) does not make it voluntary."}},{"itemId":"e3370054-6011-53da-b17f-5ade1c7d581d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"da6265f0-bddf-5d1f-aa3c-b400a4ea9ef2","sourceKey":"bank:LAG-BUA111:MKT-027","parentItemId":null,"revision":1,"payload":{"prompt":"Exchange is described as a value-creating process because:","options":["it always makes the seller richer at the buyer's expense","it removes the need for production","it forces the buyer to pay more than the product is worth","it normally leaves both parties better off than before"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"In a free exchange each party gives up something it values less for something it values more, so both usually end up better off. Options A and C describe one party gaining at the other's expense, which is not why exchange creates value."}},{"itemId":"c2b413fa-5342-59a2-917e-9d470aa304e0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"85309dbc-9df6-5a62-95e8-4036b2f63e3f","sourceKey":"bank:LAG-BUA111:MKT-028","parentItemId":null,"revision":1,"payload":{"prompt":"A trade of values between two parties, which is the basic unit of exchange, is called a:","options":["market","relationship","transfer","transaction"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A transaction is a single trade of values between two parties, such as paying money for a product. A transfer (option C) involves giving something without receiving anything definite in return, and a market (A) is the set of buyers."}},{"itemId":"8c00d8c0-8aaf-5ca0-92bf-17519cecf8d0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"edfc4fd2-e2d4-55d6-8965-76aeb4eed0ce","sourceKey":"bank:LAG-BUA111:MKT-029","parentItemId":null,"revision":1,"payload":{"prompt":"A farmer in Benue gives a fertiliser dealer ten tubers of yam and receives a bag of fertiliser in return, with no money involved. This is an example of a:","options":["transfer","coercion","barter transaction","monetary transaction"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A barter transaction is a trade of goods or services for other goods or services without money. It is not a monetary transaction (option D) because no money changes hands, and not a transfer (A) because both sides receive something."}},{"itemId":"7f122c01-c25e-58bb-8239-74b2e39b5bb8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9f06161a-822d-501f-a1c9-00fd9f6fb8de","sourceKey":"bank:LAG-BUA111:MKT-030","parentItemId":null,"revision":1,"payload":{"prompt":"Mrs Okafor pays N75,000 to a trader at Mile 12 market for a bag of rice. This is best described as a:","options":["latent demand","monetary transaction","barter transaction","transfer"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A monetary transaction is a trade of values in which one party pays money for a product. It is not barter (option C) because money is used, and not a transfer (D) because both parties give something of value."}},{"itemId":"efd2ac8b-2e97-5db8-943b-8a2a519d3e26","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b9bce7b8-4909-5d0b-b8c5-9f02a1cd79cd","sourceKey":"bank:LAG-BUA111:MKT-031","parentItemId":null,"revision":1,"payload":{"prompt":"A company donates food and blankets to flood victims in Kogi State and receives nothing tangible in return. In marketing terms this is a:","options":["barter","demand","transfer","transaction"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"In a transfer, one party gives something to another but receives nothing tangible in return, as with gifts, donations and subsidies. It is not a transaction (option D) or barter (A) because there is no two-way trade of values."}},{"itemId":"77173c17-70f4-5524-9363-e07b36609b25","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7f92c7b0-50de-5c37-bfc5-233769a25696","sourceKey":"bank:LAG-BUA111:MKT-032","parentItemId":null,"revision":1,"payload":{"prompt":"A transaction involves several elements. Which of the following is NOT one of them?","options":["At least two things of value","Conditions that the parties agree on","An intermediary who completes the deal for the parties","A time and place of agreement"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A transaction involves at least two things of value, agreed-upon conditions, a time of agreement and a place of agreement. An intermediary is not required; buyers and sellers can deal directly, so option C is the odd one out."}},{"itemId":"fe34371a-00ad-5ad2-a6fe-e72e70e27013","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f0927357-147d-5a45-9039-cf9eeb6066f3","sourceKey":"bank:LAG-BUA111:MKT-033","parentItemId":null,"revision":1,"payload":{"prompt":"The main difference between an exchange and a transaction is that:","options":["a transaction must always involve barter, while an exchange must always involve money","in a transaction one party gives and gets nothing in return, while in an exchange both gain","an exchange involves only one party, while a transaction requires at least two parties","exchange is the process of negotiating toward agreement; a transaction is the trade once agreement is reached"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Exchange is the wider process in which parties negotiate toward an agreement; when they reach agreement and trade values, a transaction has occurred. Option A is wrong because both can involve money or barter, and B describes a transfer, not a transaction."}},{"itemId":"61f42d2b-c14f-51d2-abf7-0724360fdfde","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"235022b7-8576-582d-bf96-86302175e9e3","sourceKey":"bank:LAG-BUA111:MKT-034","parentItemId":null,"revision":1,"payload":{"prompt":"The set of all actual and potential buyers of a product or service is called a:","options":["transaction","industry","market","segment"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"In marketing, a market is the set of all actual and potential buyers of a product or service who share a need or want. A segment (option D) is only one group within a market, and an industry (B) is the group of sellers, not buyers."}},{"itemId":"4d14e856-8a2e-5039-917b-9a4c0c9037fb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ac9c675a-90eb-5afa-bbdd-94df03e4072c","sourceKey":"bank:LAG-BUA111:MKT-035","parentItemId":null,"revision":1,"payload":{"prompt":"In marketing, a 'marketer' is someone who seeks a response, such as attention, a purchase, a vote or a donation, from another party. That other party is called the:","options":["intermediary","prospect","competitor","supplier"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"A marketer is the party seeking a response, and the party from whom the response is sought is the prospect. Competitors (option C), suppliers (D) and intermediaries (A) are other actors in the marketplace, not the target of the response."}},{"itemId":"bf51aa0d-d71a-5ac2-85e7-f51fdaacb60a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bca140c6-734a-5fcf-8572-32250a516a3a","sourceKey":"bank:LAG-BUA111:MKT-036","parentItemId":null,"revision":1,"payload":{"prompt":"Building, maintaining and enhancing long-term, mutually satisfying relationships with customers, rather than focusing only on single sales, is called:","options":["transaction marketing","relationship marketing","demarketing","mass marketing"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Relationship marketing aims at long-term, mutually satisfying relationships with customers so that they keep buying. Transaction marketing (option A) focuses on individual sales, and demarketing (C) tries to reduce demand."}},{"itemId":"f3d80505-8ad0-503c-a473-c97ddd68fb95","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3de8b200-c9bf-56f4-af2f-6e51ae0625f3","sourceKey":"bank:LAG-BUA111:MKT-037","parentItemId":null,"revision":1,"payload":{"prompt":"The customer's evaluation of the difference between all the benefits and all the costs of a market offering compared with competing offers is called:","options":["market share","customer perceived value","customer satisfaction","customer demand"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Customer perceived value is the difference between the total benefits a customer expects and the total costs, judged against competing offers. Customer satisfaction (option C) is about whether performance matched expectations after purchase."}},{"itemId":"57119417-f3cf-5236-9e1b-ae8db39be16f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3653af16-d512-501a-a29d-cf411e341ebf","sourceKey":"bank:LAG-BUA111:MKT-038","parentItemId":null,"revision":1,"payload":{"prompt":"Chika bought a generator expecting it to run quietly for ten hours, but it is noisy and stops after four hours. Based on the link between performance and expectations, Chika is most likely to be:","options":["dissatisfied","satisfied","indifferent","delighted"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Customer satisfaction depends on how a product's perceived performance compares with the buyer's expectations. When performance falls short of expectations, the customer is dissatisfied; satisfaction (B) or delight (D) happens only when performance matches or exceeds expectations."}},{"itemId":"61a9fd48-b2ad-5ca6-a22a-3c77cb37e618","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bca1528b-03aa-5935-8014-254beb9a9613","sourceKey":"bank:LAG-BUA111:MKT-039","parentItemId":null,"revision":1,"payload":{"prompt":"In the traditional classification, the functions of marketing are grouped into:","options":["production, finance and personnel functions","planning, organising and controlling functions","product, price and promotion functions","exchange, physical supply and facilitating functions"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing functions are traditionally grouped into exchange functions (buying and selling), physical supply functions (transportation and storage) and facilitating functions (such as financing, risk bearing, standardisation and grading, and market information). Option A lists general business functions, B lists management functions, and C lists marketing mix elements."}},{"itemId":"49c76464-bb9e-5ed7-a975-52c34f449e6d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2f65a82e-1d91-502c-b620-4ff9ccf043c5","sourceKey":"bank:LAG-BUA111:MKT-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following pairs are the exchange functions of marketing?","options":["Standardisation and grading","Buying and selling","Financing and risk bearing","Transportation and storage"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"The exchange functions are buying and selling because they transfer ownership of goods. Transportation and storage (option D) are physical supply functions, while financing, risk bearing and grading (C and A) are facilitating functions."}},{"itemId":"67a92655-8afe-5cd2-bd3c-c688f9e8f277","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f44f115c-a8b0-59a8-9e63-2ad3db85775d","sourceKey":"bank:LAG-BUA111:MKT-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following pairs are the physical supply (physical distribution) functions of marketing?","options":["Financing and market information","Buying and selling","Risk bearing and grading","Transportation and storage"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Physical supply functions move and hold the goods themselves: transportation moves them to where they are needed and storage keeps them until they are needed. Buying and selling (option B) are exchange functions, and A and C are facilitating functions."}},{"itemId":"6b17046f-c1fc-582f-9dc8-e6ab6a46080a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"169c86f4-1b0f-543d-85a9-1f92b237169c","sourceKey":"bank:LAG-BUA111:MKT-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a facilitating function of marketing?","options":["Financing","Risk bearing","Transportation","Standardisation and grading"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Transportation is a physical supply function because it physically moves goods. Financing, risk bearing and standardisation and grading (options A, B and D are facilitating functions that help buying, selling and physical supply run smoothly."}},{"itemId":"e7a7c1a3-fd89-56d3-be4a-a42641a6a816","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5b15ad9c-0a9c-5126-8e87-d68c3ca3dbc5","sourceKey":"bank:LAG-BUA111:MKT-043","parentItemId":null,"revision":1,"payload":{"prompt":"A rice miller in Kebbi buys paddy at harvest when it is plentiful, keeps it in a warehouse, and sells it months later during the lean season. Which marketing function is mainly illustrated?","options":["Standardisation and grading","Selling","Transportation","Storage"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Storage holds goods from the time they are produced until the time they are wanted, creating time utility. Transportation (option C) would move the rice to another place, and grading (A) sorts it by quality."}},{"itemId":"c00da3b0-1240-5046-bbfe-900fe0eebbe1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3b32ee0e-da5e-59a6-bc56-710ebeb8007a","sourceKey":"bank:LAG-BUA111:MKT-044","parentItemId":null,"revision":1,"payload":{"prompt":"Traders hire trucks to move tomatoes from farms in Kano to markets in Lagos where consumers want them. Which marketing function is this?","options":["Transportation","Financing","Storage","Buying"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Transportation moves goods from where they are produced to where they are consumed, creating place utility. Storage (option C) would hold the tomatoes over time, and financing (B) provides funds rather than moving goods."}},{"itemId":"71bc54be-db0a-570a-84b7-2884245a2011","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8f874958-a39e-5fdf-844d-26800c988ee8","sourceKey":"bank:LAG-BUA111:MKT-045","parentItemId":null,"revision":1,"payload":{"prompt":"Before export, cocoa beans in Ondo State are sorted into Grade I and Grade II according to quality and size. Which marketing function is this?","options":["Storage","Risk bearing","Standardisation and grading","Selling"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Standardisation sets quality standards, and grading sorts products into classes that meet those standards, so buyers can trade without inspecting every bag. Storage (option A) and risk bearing (B) do not involve sorting goods by quality."}},{"itemId":"1aaa5fc2-2655-5145-b9ab-e54de4239877","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"245df5fa-f08c-5cf0-9657-b245a966c0c8","sourceKey":"bank:LAG-BUA111:MKT-046","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos importer buys marine insurance to cover a shipment of electronics against loss or damage at sea. Which marketing function does this best illustrate?","options":["Risk bearing","Transportation","Financing","Market information"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Risk bearing is the function of dealing with the chance of loss from damage, theft, spoilage or price changes, and buying insurance is one way of handling it. Financing (option C) provides funds, and transportation (B) is the physical movement of the goods itself."}},{"itemId":"a53a7588-312f-56b0-941f-19c6f3bdca90","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b84dae92-487a-54fc-b210-8bf533223414","sourceKey":"bank:LAG-BUA111:MKT-047","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage distributor allows supermarkets to collect stock now and pay 30 days later. Which marketing function is the distributor performing?","options":["Risk bearing","Storage","Financing","Standardisation and grading"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Financing is the provision of funds or credit to keep goods moving through the marketing system, as when a distributor gives retailers time to pay. Risk bearing (option A) is about handling possible losses, while storage (B) and grading (D) do not involve credit."}},{"itemId":"1fceb54b-2492-52a5-893b-82c240f41e4c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b7ac9711-ed12-5967-8086-92f354b2b3d1","sourceKey":"bank:LAG-BUA111:MKT-048","parentItemId":null,"revision":1,"payload":{"prompt":"A noodles producer surveys shoppers in Abuja and tracks competitors' prices before deciding on a new pack size. Which marketing function is this?","options":["Risk bearing","Selling","Transportation","Market information"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"The market information function involves collecting, analysing and using data about customers, competitors and prices to guide marketing decisions. Selling (option B) transfers ownership to buyers, and transportation (C) moves goods."}},{"itemId":"b9031368-e9fb-5a8f-bd39-87dd38565a9a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0f530219-c967-5abe-a992-fc9f14a838ac","sourceKey":"bank:LAG-BUA111:MKT-049","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket chain decides which brands of soap to stock, chooses suppliers, and places orders for the coming month. Which marketing function is mainly being performed?","options":["Financing","Storage","Buying","Selling"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Buying involves deciding what to purchase, in what quantity, from whom and on what terms. Selling (option D) is the opposite side of the exchange, where the firm finds customers and transfers ownership to them."}},{"itemId":"cd6e08de-9c12-5ac3-bc48-ba88f56c0b22","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"beba24d1-f124-5a59-b79c-8cea60d9d7e6","sourceKey":"bank:LAG-BUA111:MKT-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of utility is created mainly by production rather than by marketing?","options":["Place utility","Form utility","Possession utility","Time utility"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Form utility is created when raw inputs are turned into finished products, which is mainly a production activity. Marketing creates time utility (option D) through storage, place utility (A) through transportation and possession utility (C) by transferring ownership."}},{"itemId":"ba39f672-da1d-5f18-988c-1d33042f8b0b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"52b3dfe4-b501-5f47-b210-c7cb70b1e182","sourceKey":"bank:LAG-BUA111:MKT-051","parentItemId":null,"revision":1,"payload":{"prompt":"A furniture shop in Ikeja lets customers take home a N450,000 sofa today and pay in monthly instalments, making it easier for them to own it. Which utility does this mainly create?","options":["Possession utility","Time utility","Form utility","Place utility"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Possession utility is created when marketing makes it easier for customers to own and use a product, for example through credit or instalment payment. Form utility (option C) comes from making the sofa, and place utility (D) from moving it to where buyers are."}},{"itemId":"aa5888ff-0d82-52fd-b282-2bab1f60205b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"09f20e8d-632e-5127-a5db-353676cb8c76","sourceKey":"bank:LAG-BUA111:MKT-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key importance of marketing to a business firm?","options":["It removes the need for any production planning within the firm","It guarantees the firm a permanent monopoly in its market","It eliminates all business risk from the firm's operations","It brings in revenue for survival and growth by attracting and keeping customers"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing is the business function that attracts and keeps customers, and customers are what bring revenue and profit to a firm. Marketing cannot remove the need for production planning (option A), guarantee a monopoly (B) or remove all risk (C)."}},{"itemId":"4666efb1-5314-5535-a3b0-68c71d5ddeeb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"60ad65e9-ac86-5066-8f07-c67a0bb12da4","sourceKey":"bank:LAG-BUA111:MKT-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of marketing to consumers?","options":["It gives consumers wider choice and information about available products","It ensures every consumer pays the same price everywhere","It forces consumers to buy only local products","It removes the need for consumers to compare products"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing informs consumers about products and makes many alternatives available, so they can choose what best satisfies their needs. Options B, C and D describe outcomes marketing does not produce; in fact it encourages comparison."}},{"itemId":"dda3559c-3629-556c-b343-9d6b7a2b8198","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e16d6b56-0c1e-5971-800c-78e7e77a9247","sourceKey":"bank:LAG-BUA111:MKT-054","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an importance of marketing to the national economy?","options":["It reduces the number of firms operating in the economy","It creates jobs in retailing, transport, advertising and distribution","It ensures goods are always produced before demand is known","It restricts the flow of goods between different regions"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing activities such as retailing, wholesaling, transport, advertising and research employ many people, and they also stimulate demand and economic growth. Options A, C and D describe effects opposite to what marketing does."}},{"itemId":"619d2929-ae57-5aff-89ab-c1dffb5b9186","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f8b7bc72-7a54-5d3b-8adc-62ca558a31a4","sourceKey":"bank:LAG-BUA111:MKT-055","parentItemId":null,"revision":1,"payload":{"prompt":"Describing marketing as 'the creation and delivery of a standard of living to society' emphasises marketing's:","options":["contribution to the welfare and living standards of society","use of advertising to persuade buyers","focus on selling existing stock quickly","role in reducing a firm's production costs"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"This definition looks at marketing from society's point of view: by making goods and services available, marketing helps raise people's standard of living. Options B, C and D are narrow firm-level activities that the definition does not stress."}},{"itemId":"a78b37e2-8b59-5195-a26f-537735f42f8f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ddfe7a37-65b8-5797-af8e-b3cd13bac3b8","sourceKey":"bank:LAG-BUA111:PQ-001","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best encapsulates the modern definition of marketing beyond mere transactional exchange?","options":["Focusing solely on product distribution","Maximizing profit through aggressive sales","Creating, communicating, delivering, and exchanging offerings with value","Reducing operational costs for competitive pricing"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Modern marketing is defined as the activities and processes for creating, communicating, delivering and exchanging offerings that have value for customers and society, so option C captures it. Option B confuses marketing with hard selling, while A and D describe only one narrow part of business (distribution or cost control)."}},{"itemId":"843ff229-9c34-5f5c-b3aa-cfe5a2c3aeac","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"adfce487-52f7-5c53-b651-bf29f680e422","sourceKey":"bank:LAG-BUA111:PQ-002","parentItemId":null,"revision":1,"payload":{"prompt":"How does marketing contribute to organizational success in a dynamic economy?","options":["By prioritizing production efficiency over customer satisfaction","By limiting customer interaction to reduce costs","By fostering long-term customer relationships and adapting to market needs","By avoiding competitive analysis"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing helps a firm succeed by building lasting relationships with customers and adjusting its offerings as market needs change, which is option C. Option D puts production efficiency above customer satisfaction, which is the opposite of what marketing stands for, and B and A would leave the firm cut off from its customers and competitors."}},{"itemId":"ea176d4a-7c17-5555-8a32-b26757bb852e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"58676b14-bc63-55ed-a3b1-add6f2b8e8e0","sourceKey":"bank:LAG-BUA111:PQ-003","parentItemId":null,"revision":1,"payload":{"prompt":"The scope of marketing extends to which complex process beyond promotion?","options":["Solely advertising and branding","Manufacturing goods for internal use","Ideation, value creation, and strategic distribution of offerings","Pricing products without market research"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing is much wider than promotion: it covers generating product ideas, creating value and getting offerings to customers through the right channels, so C is correct. Option A limits marketing to advertising and branding, which are only parts of promotion, and D is poor practice because good pricing depends on market information."}},{"itemId":"b650f9b0-d0db-5c21-add4-349f0c402b39","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"098acc8e-5a08-5d08-9845-f454495c940a","sourceKey":"bank:LAG-BUA111:PQ-004","parentItemId":null,"revision":1,"payload":{"prompt":"A complete analysis of a firm's marketing environment must cover which forces?","options":["Customer preferences alone","Competitor actions without external context","Internal policies and employee performance","Micro (e.g., suppliers) and macro (e.g., economic trends) forces"],"correctOption":3,"section":"Marketing Environment","explanation":"The marketing environment is made up of the micro environment (forces close to the firm such as suppliers, intermediaries, customers and competitors) and the macro environment (wider forces such as economic, demographic and political conditions). Option D names both, so it is complete. Options A and B each look at only one force, and C is about internal management rather than the external environment."}},{"itemId":"55958f97-0b19-5aba-8763-cba9b916097a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d12846fd-b6d8-5541-96d0-3386d193eb2a","sourceKey":"bank:LAG-BUA111:PQ-005","parentItemId":null,"revision":1,"payload":{"prompt":"Consumer behaviour is best understood as a multidisciplinary field involving:","options":["Only economic decision-making","Solely the act of buying products","Pricing strategies and product availability","Psychological, social and cultural influences on purchase decisions"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Consumer behaviour draws on psychology, sociology and anthropology because what people buy is shaped by their minds, the groups around them and their culture, so option D is right. Option A reduces buying to economics alone, option B looks only at the moment of purchase, and option C describes marketing decisions made by the firm rather than the behaviour of the buyer."}},{"itemId":"65288fdc-24d2-5f21-a49f-d909f26f8e2c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1665b364-8697-5db6-ac78-030d67376e3c","sourceKey":"bank:LAG-BUA111:PQ-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a micro-environmental force that directly challenges a firm's marketing strategy in a competitive market?","options":["Rival firms' pricing and innovation tactics","Cultural shifts","Government regulations","Technological advancements"],"correctOption":0,"section":"Marketing Environment","explanation":"Competitors belong to the micro environment because they are close to the firm and directly affect its day-to-day marketing decisions, so rival firms' pricing and innovation (A) is the answer. Technological advancements (D), government regulations (C) and cultural shifts (B) are all macro-environmental forces, which are wider and outside the firm's control."}},{"itemId":"c267045e-356d-5bbb-9467-78db05cadee8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ca1190b8-dd06-5804-8039-5d378659df4a","sourceKey":"bank:LAG-BUA111:PQ-006-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a force in a firm's MACRO environment?","options":["Demographic changes in the population","Suppliers of raw materials","Wholesalers and retailers","Competing firms"],"correctOption":0,"section":"Marketing Environment","explanation":"The macro environment is made up of wide forces outside the firm's control, such as demographic, economic, political and technological conditions, so demographic changes (A) are macro. Suppliers (B), wholesalers and retailers (C) and competitors (D) are micro-environmental forces because they are closely linked to the firm and directly affect its activities."}},{"itemId":"69b3339c-f60a-55f8-a4e8-68a1ff1d95ef","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"15dfcfc9-f65b-5336-b743-89a702686c81","sourceKey":"bank:LAG-BUA111:PQ-007","parentItemId":null,"revision":1,"payload":{"prompt":"A marketer analysing the macro environment during a recession must pay closest attention to which factor?","options":["Customer loyalty programs","Intermediary efficiency","Supplier reliability","Economic conditions affecting purchasing power"],"correctOption":3,"section":"Marketing Environment","explanation":"During a recession, incomes fall and people buy less, so economic conditions affecting purchasing power (D) are the main macro-environmental factor to watch. Supplier reliability (C) and intermediary efficiency (B) are micro-environmental forces, and loyalty programmes (A) are a marketing tool rather than an environmental factor."}},{"itemId":"d16fc8bd-4e8b-51bc-adf2-9c2f889b805b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ba2f3a2f-6cd4-5e64-be2a-3b07b0545cda","sourceKey":"bank:LAG-BUA111:PQ-008","parentItemId":null,"revision":1,"payload":{"prompt":"How does marketing create societal value beyond profit generation?","options":["By focusing solely on high-income segments","By reducing innovation to cut costs","By increasing unemployment through automation","By aligning product offerings with consumer needs and social welfare"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing adds value to society when firms offer products that satisfy consumer needs while also caring for the wellbeing of society, which is option D. Options C, A and B describe practices that harm people, exclude most consumers or slow progress, so they reduce rather than create societal value."}},{"itemId":"4f6d2a5e-0014-5ee8-bd6a-0f24eda17687","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"37d1e883-cc49-598b-8c01-7ef64350a524","sourceKey":"bank:LAG-BUA111:PQ-009","parentItemId":null,"revision":1,"payload":{"prompt":"Studying consumer behaviour mainly enables marketers to predict:","options":["How buyers are likely to respond to marketing stimuli when making decisions","Production costs with precision","Employee performance in sales","Competitor pricing strategies"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Firms study what, where, when and how people buy so they can better predict how buyers will react to their marketing mix, which is option A. Options B and C are internal cost and staff matters, and option D is about competitors, not about consumers."}},{"itemId":"c54a8b25-9a3b-5fc9-8bb5-7cc2de2d4a73","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"68b68e02-f557-5973-af34-c2f8ab7a362c","sourceKey":"bank:LAG-BUA111:PQ-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which psychological factor most directly drives impulse purchases?","options":["Cultural norms","Social class affiliation","Motivation tied to immediate gratification","Peer group influence"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"An impulse purchase is made with no conscious planning, usually because an inner motive pushes the buyer to satisfy a want right away, so option C is the psychological factor at work. Options A, B and D can affect buying too, but they are cultural and social influences, not psychological ones."}},{"itemId":"9c341b21-9fe8-574c-92a2-2d518624b633","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d5dc07ac-f152-5599-b259-34f5c6d2e81f","sourceKey":"bank:LAG-BUA111:PQ-011","parentItemId":null,"revision":1,"payload":{"prompt":"Within the scope of marketing, which activity requires the deepest understanding of consumer insights?","options":["Financial forecasting","Employee recruitment","Market segmentation and research","Product assembly"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Market segmentation and marketing research both depend on understanding who customers are, what they want and how they behave, so C needs the deepest consumer insight. Employee recruitment (B), financial forecasting (A) and product assembly (D) are mainly human resource, finance and production tasks rather than marketing activities."}},{"itemId":"30f435b0-368f-589e-bb87-03939cf6668a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1321a025-4d11-5df3-8678-9ec1121491c3","sourceKey":"bank:LAG-BUA111:PQ-012","parentItemId":null,"revision":1,"payload":{"prompt":"Why does the marketing environment demand constant monitoring?","options":["To limit product diversification","To avoid customer feedback loops","To adapt to unpredictable shifts in external and internal conditions","To maintain static strategies over time"],"correctOption":2,"section":"Marketing Environment","explanation":"The marketing environment keeps changing, and those changes bring both opportunities and threats, so firms must monitor it constantly in order to adapt (C). Option D is wrong because static strategies fail in a changing environment, and B and A would cut the firm off from useful feedback and growth."}},{"itemId":"20cb85aa-ab65-5be2-af81-ec76e204940b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"52e20665-2801-5541-97d3-ab9f073ac3a2","sourceKey":"bank:LAG-BUA111:PQ-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a social factor that can shape brand loyalty among young adults?","options":["Personal perception","Cognitive learning","Reference group endorsements","Individual attitudes"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Reference groups are groups whose values and behaviour a person adopts, such as friends or groups they admire, and they are a social influence, so option C is correct. Options A, B and D (perception, learning and attitudes) all happen inside the individual's mind, which makes them psychological factors."}},{"itemId":"7f8da82f-1671-5a6b-b8ee-577fca904a25","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9fa7831-1f9b-536e-bc61-e9b5f7cf726f","sourceKey":"bank:LAG-BUA111:PQ-014","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing's societal importance is most evident in its ability to:","options":["Inflate prices for profit maximization","Bridge gaps between consumer needs and available solutions","Reduce employment opportunities through outsourcing","Stifle innovation for cost efficiency"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing serves society by linking what consumers need with the products and services that can satisfy those needs, which is option B. Options C, A and D describe harmful practices such as cutting jobs, inflating prices and blocking innovation, which are not why marketing is important to society."}},{"itemId":"4e6a4afc-cdd3-5599-824f-c8c06d9ab41e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cec6905c-d263-5c39-9de0-0793bd334c16","sourceKey":"bank:LAG-BUA111:PQ-015","parentItemId":null,"revision":1,"payload":{"prompt":"In the micro-environment, which element requires the closest collaboration for supply chain success?","options":["Political lobbying","Suppliers and intermediaries","Technological upgrades","Economic forecasting"],"correctOption":1,"section":"Marketing Environment","explanation":"Suppliers provide the raw materials, and marketing intermediaries such as wholesalers, retailers and warehouses move products to customers, so both are micro-environmental forces that the firm must work closely with (B). Economic forecasting (D) and technological upgrades (C) relate to macro forces, and political lobbying (A) is not a supply chain partner."}},{"itemId":"e1fd58f9-5410-566c-a954-6eb627fc021e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"44f6f5c3-34e3-5354-a376-bdc4c1d33476","sourceKey":"bank:LAG-BUA111:PQ-016","parentItemId":null,"revision":1,"payload":{"prompt":"The three broad categories of factors that affect the consumer buying decision process are:","options":["Price, product quality and availability","Advertising, packaging and branding","Political, legal and technological factors","Personal, psychological and social factors"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Consumer buying decisions are shaped by personal factors (such as age and demographics), psychological factors (such as motives, perception and attitudes) and social factors (such as family, reference groups, social class and culture), which is option D. Options A and B are elements the marketer controls, and option C lists parts of the wider marketing environment rather than factors acting on the individual buyer."}},{"itemId":"e31a3e73-cdf1-5daa-a482-001b5ba127c6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7afeea4d-8e78-5666-bab4-14b0d726d9b4","sourceKey":"bank:LAG-BUA111:PQ-017","parentItemId":null,"revision":1,"payload":{"prompt":"The essence of marketing's definition lies in its focus on:","options":["Short-term profit over customer value","Internal process optimization","Cost-cutting at the expense of quality","Delivering superior value while balancing profitability"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"At its core, marketing is about delivering superior value to customers while still making a profit for the firm, which is option D. Option A puts short-term profit above customer value, C sacrifices quality, and B looks inward at processes instead of at customers."}},{"itemId":"153a20fa-fdaa-55a5-8914-a5ecf624c509","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bbc77a8c-9979-5914-ac73-c83fa28bd10c","sourceKey":"bank:LAG-BUA111:PQ-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which external factor in the marketing environment most directly affects a firm's pricing strategy?","options":["Internal resource allocation","Organizational culture","Competitor pricing and market positioning","Employee morale"],"correctOption":2,"section":"Marketing Environment","explanation":"Competitors are an external force, and the prices and positions of rival products strongly limit what a firm can charge, so C is correct. Organisational culture (B), employee morale (D) and resource allocation (A) are internal factors, so they cannot be the external factor asked for."}},{"itemId":"e8edc75b-3ab5-5200-a3ea-366d79c8cfcc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a9bd1d97-6125-5ecb-abac-6fcb10cc3f21","sourceKey":"bank:LAG-BUA111:PQ-019","parentItemId":null,"revision":1,"payload":{"prompt":"The scope of marketing demands proficiency in:","options":["Distribution without promotion","Advertising as the sole focus","Pricing without consumer input","Orchestrating value creation, delivery, and customer engagement"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"The scope of marketing covers the whole job of creating value, delivering it and engaging customers, so option D is correct. Option B reduces marketing to advertising alone, while C and A leave out important parts of the marketing mix (customer input on price, and promotion)."}},{"itemId":"f9e76a48-feec-5157-a5a8-c72889b24721","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4fc3e3f9-9206-5850-9c2a-7c3db29ec9cf","sourceKey":"bank:LAG-BUA111:PQ-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a personal factor that influences consumer behaviour?","options":["Cultural heritage","Social status","Age and life-cycle stage","Peer influence"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Personal factors are those unique to the individual, such as age, stage in the family life cycle and other demographics, so option C is correct. Option A is a cultural influence, while options B and D come from the groups and class a person belongs to, which makes them social influences."}},{"itemId":"b115d03f-2709-5473-8389-e787ae2b08fe","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6c80f7e7-600f-5f47-9f37-a07be2dbcf96","sourceKey":"bank:LAG-BUA111:PQ-021","parentItemId":null,"revision":1,"payload":{"prompt":"The production concept, the earliest marketing philosophy, emerged in response to:","options":["Aggressive sales competition","Industrial advancements enabling mass production","Consumer demand for customization","Market research innovations"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept was the earliest business philosophy and arose when new industrial methods made mass production possible and demand was higher than supply, so B is right. Customisation (C), aggressive selling (A) and market research (D) belong to later philosophies such as the selling and marketing concepts."}},{"itemId":"a850ddcb-3e79-52a5-afbd-8ca9444e5df1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"162b031a-693c-53ee-9b05-f899ea219852","sourceKey":"bank:LAG-BUA111:PQ-022","parentItemId":null,"revision":1,"payload":{"prompt":"Under the production concept, consumer preference is assumed to favor:","options":["Personalized services","Heavily promoted luxury items","Low-cost, widely available goods","High-quality, niche products"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept assumes consumers will prefer products that are cheap and widely available, so firms focus on producing efficiently and distributing widely (C). High-quality products (D) relate to the product concept, while heavy promotion (B) and personalised services (A) belong to the selling and marketing concepts."}},{"itemId":"8b56cb3d-fd2d-5980-b8aa-875855d5039e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3e467ea5-06bb-51c8-ba66-470690835de0","sourceKey":"bank:LAG-BUA111:PQ-023","parentItemId":null,"revision":1,"payload":{"prompt":"The selling concept gained traction when firms needed to:","options":["Innovate product designs","Meet rising customer expectations","Overcome consumer resistance through persuasion","Conduct extensive market research"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept holds that consumers will not buy enough unless they are persuaded, so it became popular when firms had to overcome buyer resistance with aggressive selling and promotion (C). Meeting customer expectations (B) and extensive market research (D) describe the marketing concept, and innovating designs (A) is closer to the product concept."}},{"itemId":"62304d3b-8528-523b-b057-b471310d93d2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d14709bf-cd94-5ac3-bcd8-046b0a3f676c","sourceKey":"bank:LAG-BUA111:PQ-024","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept revolutionized business strategy by prioritizing:","options":["Production efficiency over customer needs","Aggressive sales tactics","Cost reduction over quality","Customer satisfaction as a driver of profitability"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept says a firm achieves its goals by finding out what customers need and satisfying them better than competitors, so customer satisfaction drives profit (D). Option A describes the production concept, B the selling concept, and C ignores quality, which customers value."}},{"itemId":"376cbb26-26c3-5e54-a33e-2ed7fc3e3060","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"75591a67-8312-557c-aff3-b31607db084c","sourceKey":"bank:LAG-BUA111:PQ-025","parentItemId":null,"revision":1,"payload":{"prompt":"The societal marketing concept extends the marketing concept by integrating:","options":["Product standardization","Production scalability","Ethical considerations and societal welfare","Profit maximization alone"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept keeps the customer focus of the marketing concept but adds concern for ethics and the long-term wellbeing of society, which is option C. Option D leaves out both customers and society, and A and B are production concerns rather than social ones."}},{"itemId":"0c12fcdb-5dc5-5d23-94cb-30e596b7ae15","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8e7dfd0c-7c47-566d-8bd7-817b2a131239","sourceKey":"bank:LAG-BUA111:PQ-026","parentItemId":null,"revision":1,"payload":{"prompt":"In the production era, firms succeeded by emphasizing:","options":["Market segmentation strategies","Customer-centric innovation","Economies of scale and broad distribution","Targeted advertising campaigns"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"In the production era, demand was high, so firms succeeded by producing in large quantities at low cost (economies of scale) and distributing widely (C). Customer-centric innovation (B), targeted advertising (D) and segmentation (A) are tools of the later marketing era."}},{"itemId":"cb86cef4-2ea4-5f25-88cb-e93d59b3817d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c0241ab5-1bc6-5575-b774-5be13602b3fa","sourceKey":"bank:LAG-BUA111:PQ-027","parentItemId":null,"revision":1,"payload":{"prompt":"The selling concept became dominant mainly because of:","options":["Limited competition","Consumer-driven demand","Overproduction and the need to clear inventory","Technological stagnation"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept became dominant when firms could produce more than people were willing to buy, so they needed hard selling to clear unsold stock (C). Limited competition (A) and consumer-driven demand (B) would make aggressive selling unnecessary, and technological stagnation (D) is not what caused the selling era."}},{"itemId":"7765e930-85f4-5183-b606-e53c485e7b27","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8b618113-7f82-59c6-88c4-7125cc24e6d7","sourceKey":"bank:LAG-BUA111:PQ-028","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept emerged as a strategic response to:","options":["Reduced market demand","Heightened competition and evolving consumer expectations","Simplified distribution channels","Declining production capabilities"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept arose as competition grew and customers became more demanding, so firms had to focus on satisfying customer needs to survive (B). Production capability was rising, not declining (D), and neither reduced demand (A) nor simpler distribution (C) explains the shift to customer focus."}},{"itemId":"b87c339f-0e73-5691-994f-b77672ab3e12","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0b843d55-ff31-5d37-bea8-f6f832588871","sourceKey":"bank:LAG-BUA111:PQ-029","parentItemId":null,"revision":1,"payload":{"prompt":"How does the societal marketing concept differ fundamentally from its predecessor?","options":["It balances customer needs with long-term societal impact","It focuses solely on product quality","It prioritizes short-term gains over sustainability","It ignores profitability"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept builds on the marketing concept by balancing customer satisfaction with the long-term wellbeing of society, so A is correct. Option C is the reverse of its aim, D is wrong because it still seeks profit, and B describes the product concept."}},{"itemId":"89509188-36fd-555a-825a-d3dfc4deaf11","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7bcdc6c2-efe2-5246-897e-29b7455eb968","sourceKey":"bank:LAG-BUA111:PQ-030","parentItemId":null,"revision":1,"payload":{"prompt":"The production concept's core assumption about consumers is challenged when:","options":["Demand exceeds supply","Advertising drives sales","Consumers prioritize quality and differentiation over price","Distribution networks expand"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept assumes buyers mainly want cheap, available products, so it breaks down when consumers start to care more about quality and distinctive features than about price (C). Demand exceeding supply (A) is actually the situation in which the production concept works best, while B and D do not contradict its assumption about consumers."}},{"itemId":"1c3f4bf4-4839-520a-befa-7128c08be386","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bae31e1e-31f6-53c4-a700-36ce2faaf35a","sourceKey":"bank:LAG-BUA111:PQ-031","parentItemId":null,"revision":1,"payload":{"prompt":"The evolution of marketing reflects a paradigm shift toward:","options":["Customer-centric value creation","Production isolationism","Product-centric efficiency","Societal indifference"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"Marketing thinking has moved from production and selling towards understanding and satisfying customers, so the shift is towards customer-centric value creation (A). Product-centric efficiency (C) and production isolationism (B) describe the early stage, not the direction of change, and societal indifference (D) is the opposite of the societal marketing concept."}},{"itemId":"ece455b0-b47d-598e-9c6a-2e41f5fa8969","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5af40799-83e4-5741-9a6c-c4c04d42cfce","sourceKey":"bank:LAG-BUA111:PQ-032","parentItemId":null,"revision":1,"payload":{"prompt":"The selling concept thrives in markets where:","options":["Consumers require convincing due to surplus goods","Demand naturally exceeds supply","Products are highly differentiated","Customer loyalty is high"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept works best when there is a surplus of goods and buyers must be persuaded to purchase, which is option A. If demand already exceeds supply (B) or customers are already loyal (D), heavy persuasion is not needed, and highly differentiated products (C) can sell on their own merits."}},{"itemId":"712e2c23-4989-5a1a-865d-52b11bea2c22","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"05dce508-20e0-55bc-a4fc-02914f548b7d","sourceKey":"bank:LAG-BUA111:PQ-033","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept hinges on the principle of:","options":["Aligning offerings with customer needs and desires","Production cost minimization","Product standardization","Sales force expansion"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept rests on finding out what customers need and want and then shaping the firm's offerings to satisfy them (A). Standardisation (C) and cost minimisation (B) reflect the production concept, while expanding the sales force (D) reflects the selling concept."}},{"itemId":"ecb88aaf-60d1-55c6-b975-7085ab63f975","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1548c568-ae82-55e6-81d7-0e2d5eab0f99","sourceKey":"bank:LAG-BUA111:PQ-034","parentItemId":null,"revision":1,"payload":{"prompt":"The societal marketing concept gained prominence due to:","options":["Growing concerns over sustainability and ethics","Reduced market competition","Declining consumer awareness","Simplified regulatory frameworks"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept became important as people grew more concerned about the environment, sustainability and business ethics, so A is correct. Consumer awareness was rising, not falling (C), and less competition (B) or simpler regulation (D) would not push firms to think about society."}},{"itemId":"8278755f-cde3-56cc-8522-edef8bc9f8a1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ff0433db-103c-5408-8e91-55b0a8b16f33","sourceKey":"bank:LAG-BUA111:PQ-035","parentItemId":null,"revision":1,"payload":{"prompt":"In the production era, the primary business objective was:","options":["Maximizing output and distribution efficiency","Customer relationship management","Market niche targeting","Brand differentiation"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"In the production era, demand was greater than supply, so the main aim was to produce as much as possible and distribute it efficiently (A). Customer relationship management (B), brand differentiation (D) and niche targeting (C) became priorities only in the later marketing era."}},{"itemId":"f73c2b64-9fef-59c4-9f75-f3b2b4f8dd3d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c2bcda20-fe34-5a34-a908-b4939787c131","sourceKey":"bank:LAG-BUA111:PQ-036","parentItemId":null,"revision":1,"payload":{"prompt":"A major limitation of the selling concept is its tendency to:","options":["Focus on short-term sales over long-term loyalty","Enhance product quality","Build lasting customer trust","Respond to market trends"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The selling concept focuses on making the sale now, often through hard selling, rather than satisfying customers over time, so it tends to sacrifice long-term loyalty (A). Building lasting trust (C), improving quality (B) and responding to market trends (D) are strengths of other philosophies, not weaknesses of the selling concept."}},{"itemId":"2b72f202-53f0-56de-a729-d7561c0b44af","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"be6bfff0-7954-5043-bd9a-cd8d627ab407","sourceKey":"bank:LAG-BUA111:PQ-037","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing concept redefines success as:","options":["Production volume","Promotional reach","Cost leadership","Delivering what customers value profitably"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Under the marketing concept, success means delivering what customers value while still making a profit (D). Production volume (A) is the yardstick of the production concept, promotional reach (B) fits the selling concept, and cost leadership (C) is a competitive strategy rather than a definition of marketing success."}},{"itemId":"ab20e33f-cda6-51b6-995c-a743756ccf6e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"95ee987f-342a-58f5-af95-793b6ab8e18a","sourceKey":"bank:LAG-BUA111:PQ-038","parentItemId":null,"revision":1,"payload":{"prompt":"The societal marketing concept requires firms to reconcile:","options":["Short-term sales and inventory turnover","Advertising and pricing tactics","Production and distribution efficiency","Profit, customer satisfaction, and societal good"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept asks firms to balance three things: company profit, customer satisfaction and the long-term good of society (D). Options C, B and A deal only with operations, promotion or short-term sales and leave out the social dimension."}},{"itemId":"958dd09d-7539-555f-bc42-d673943ef879","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fade736f-44b0-57f4-a069-8c6e1bc6a166","sourceKey":"bank:LAG-BUA111:PQ-039","parentItemId":null,"revision":1,"payload":{"prompt":"The progression of marketing philosophies indicates:","options":["A decline in customer orientation","A return to production focus","An increasing emphasis on customer and societal needs","A rejection of innovation"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"Moving from the production and selling concepts to the marketing and societal marketing concepts shows growing attention to customers and then to society as a whole (C). Options A, B and D describe a movement backwards, which is the opposite of how marketing philosophy developed."}},{"itemId":"9e18142d-d502-5614-89a8-c3e1c2b3f6d5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"87e465c9-4463-55cb-bf3e-8e0d0fbf40e0","sourceKey":"bank:LAG-BUA111:PQ-040","parentItemId":null,"revision":1,"payload":{"prompt":"The production concept dominated the early industrial era because:","options":["Demand for goods was greater than supply","Consumer demand was highly segmented","Advertising was widespread","Societal concerns were prioritized"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept dominated when demand for goods was greater than supply, so firms could sell almost anything they made (A). Segmented demand (B), widespread advertising (C) and concern for society (D) are features of later stages in the development of marketing."}},{"itemId":"fdf69961-f86f-52f0-9f98-51d282fb10ee","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2b968bc5-77de-5d5e-ac49-e873e6a1a105","sourceKey":"bank:LAG-BUA111:PQ-041","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing mix integrates which four elements to achieve strategic objectives?","options":["Product, People, Process, Performance","Product, Packaging, Promotion, Profit","Product, Price, Placement, Publicity","Product, Price, Place, Promotion"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"The four elements of the marketing mix are Product, Price, Place and Promotion, which is option D. Option C looks similar but swaps Place and Promotion for 'Placement' and 'Publicity', which are not the standard terms, and A and B mix in words such as Performance and Profit that are not elements of the mix."}},{"itemId":"6c6c291e-b79f-5727-904e-d72943021994","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ccfa4200-6640-5d41-9812-3091cb2dcf5d","sourceKey":"bank:LAG-BUA111:PQ-042","parentItemId":null,"revision":1,"payload":{"prompt":"The product element of the marketing mix requires decisions about:","options":["Designing offerings that meet customer expectations","Promotional budgets","Pricing elasticity alone","Distribution logistics only"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Product decisions are about designing goods or services, with their features, quality, branding and packaging, so that they meet customer needs and expectations (A). Pricing (C), distribution logistics (D) and promotional budgets (B) belong to the price, place and promotion elements."}},{"itemId":"feab5a9f-3884-52be-9b13-210f91e41fd9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"939cbf14-f4ef-54a7-8243-c75fd58c9fb6","sourceKey":"bank:LAG-BUA111:PQ-043","parentItemId":null,"revision":1,"payload":{"prompt":"Pricing in the marketing mix must balance:","options":["Production costs without market input","Customer perceived value and competitive positioning","Competitor avoidance","Product quality reduction"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"A good price must reflect the value customers believe they receive and the prices of competing products, which is option B. Option A is wrong because setting prices from cost alone ignores the market, and reducing quality (D) or avoiding competitors (C) is not what pricing balances."}},{"itemId":"1fde69e8-64b0-52d0-a0f0-b4317b338f39","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9515415e-fe8f-5aa7-9e24-29b50c699f47","sourceKey":"bank:LAG-BUA111:PQ-044","parentItemId":null,"revision":1,"payload":{"prompt":"The place element of the marketing mix is critical for:","options":["Designing product features","Setting premium prices","Ensuring product availability through effective channels","Crafting promotional messages"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Place (distribution) is about making the product available to customers through the right channels, such as wholesalers and retailers (C). Crafting messages (D) is promotion, setting prices (B) is price, and designing features (A) is product."}},{"itemId":"614535d4-4e84-5adb-8b61-ebd735878deb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4dada99b-0543-599d-9e62-45597c1785c4","sourceKey":"bank:LAG-BUA111:PQ-045","parentItemId":null,"revision":1,"payload":{"prompt":"Promotion within the marketing mix encompasses:","options":["Pricing adjustments","Distribution network expansion","Advertising, personal selling, and public relations","Product development timelines"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Promotion covers the tools a firm uses to communicate with customers, including advertising, personal selling, sales promotion and public relations (C). Product timelines (D), price changes (A) and distribution expansion (B) belong to the other three Ps."}},{"itemId":"222b22f4-94bf-507e-b40b-e3c18e58e69c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e5a61280-7e05-582d-9b90-b12ffd65e195","sourceKey":"bank:LAG-BUA111:PQ-046","parentItemId":null,"revision":1,"payload":{"prompt":"A penetration pricing strategy is most effective when a firm aims to:","options":["Maximize short-term profits","Match competitor pricing","Reflect production costs accurately","Gain market share rapidly with a low entry price"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Penetration pricing means entering the market with a low price to attract many buyers quickly and win market share (D). Maximising short-term profit (A) is the aim of price skimming, while matching competitors (B) and cost-based pricing (C) are different pricing approaches."}},{"itemId":"e89376ed-cbe5-5665-ae9b-ec41adc08eb5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bc58f9dd-4065-5475-a8e8-5dacee42c2e0","sourceKey":"bank:LAG-BUA111:PQ-047","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing mix is commonly referred to as:","options":["The 4 Es strategy","The 4 Ps framework","The 4 Ms approach","The 4 Cs model"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The marketing mix is popularly called the 4 Ps because its four elements, Product, Price, Place and Promotion, all start with P (B). The 4 Cs (D) is a separate customer-focused framework, and the 4 Ms and 4 Es (C, A) are not names for the marketing mix."}},{"itemId":"c9b7a72e-c4f3-5241-9162-77cccdd50414","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0e32517b-f9f1-53fa-9755-7b9a853aa530","sourceKey":"bank:LAG-BUA111:PQ-048","parentItemId":null,"revision":1,"payload":{"prompt":"In the marketing mix, a product can be defined as:","options":["A bundle of tangible and intangible benefits","Distribution pathways","Tangible goods only","Pricing mechanisms"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"A product is anything offered to satisfy a need, combining tangible features with intangible benefits such as service, brand image and after-sales support (A). Option C is too narrow because services and ideas are also products, and D and B describe price and place."}},{"itemId":"81a2062b-01e6-563d-b1fa-9a48207e2955","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d2280b7b-8c94-5868-b6e5-7ca6afe2d726","sourceKey":"bank:LAG-BUA111:PQ-049","parentItemId":null,"revision":1,"payload":{"prompt":"The place element ensures strategic success by:","options":["Delivering products to the right locations at the right time","Improving product aesthetics","Setting competitive prices","Enhancing promotional reach"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"The place element is about getting the product to the right location at the right time so customers can buy it when they need it (A). Setting prices (C), promotional reach (D) and product looks (B) belong to price, promotion and product."}},{"itemId":"ba4d8e18-4af4-5d5b-9848-e150c8857400","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4e242edc-95b5-5160-8cb2-f0b400b71374","sourceKey":"bank:LAG-BUA111:PQ-050","parentItemId":null,"revision":1,"payload":{"prompt":"The promotion element's primary objective is to:","options":["Increase production overhead","Build awareness and persuade target audiences","Limit customer access","Reduce channel efficiency"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Promotion aims to inform target customers about a product, build awareness and persuade them to buy (B). Options C, A and D describe outcomes that would hurt the firm, so none of them can be the goal of promotion."}},{"itemId":"530b7c70-019b-5e82-9fc8-a5da9a1db19c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4b7e9e6f-af51-5f97-b99e-9edbaead672c","sourceKey":"bank:LAG-BUA111:PQ-051","parentItemId":null,"revision":1,"payload":{"prompt":"A skimming pricing strategy is best suited for:","options":["Cost-based pricing","Mass-market penetration","Earning high profit margins on innovative products in the early period","Matching competitors' prices (competitive parity)"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Price skimming means launching a new, innovative product at a high price and 'skimming' the top layer of buyers who are willing to pay more, so margins are high at the start. Option B describes penetration pricing, which does the opposite by using a low price to win a mass market quickly. Options D and A are different pricing methods based on competitors' prices or on costs."}},{"itemId":"e3a738dc-6807-5b99-9f29-1d89d4981e36","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"264a47a3-d965-5326-885c-81508aaee596","sourceKey":"bank:LAG-BUA111:PQ-051-b","parentItemId":null,"revision":1,"payload":{"prompt":"A firm that launches a new product at a low price in order to win a large market share quickly is using:","options":["Penetration pricing","Price skimming","Prestige pricing","Cost-plus pricing"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Penetration pricing sets a low initial price to attract many buyers fast and build market share. Option B, skimming, is the opposite approach: a high launch price aimed at buyers willing to pay a premium. Option C uses high prices to signal quality, and option D simply adds a markup to cost without targeting market share."}},{"itemId":"53c807ce-530f-55b5-a524-5f4d85997f72","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7f607a50-08cf-5345-88dc-824d7fc8ceeb","sourceKey":"bank:LAG-BUA111:PQ-052","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing mix enables firms to:","options":["Lower quality standards","Combine their controllable marketing tools to respond to the target market","Ignore customer preferences","Escalate production expenses"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The marketing mix is the set of controllable tools (product, price, place and promotion) that a firm blends together to produce the response it wants from its target market. Options C, A and D describe things that would hurt a business and are not the purpose of the mix at all."}},{"itemId":"a0c724b2-6ff9-5392-b9ca-d81aa5450db4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c4d5795f-1728-572c-a86c-f827d50d1c89","sourceKey":"bank:LAG-BUA111:PQ-053","parentItemId":null,"revision":1,"payload":{"prompt":"Product decisions in the marketing mix involve:","options":["Branding, packaging and product features","Pricing and promotional alignment","Excluding market research","Distribution and advertising"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Product decisions cover what the firm actually offers: its features, quality, design, brand name and packaging. Option B mixes the price and promotion elements, and option D mixes place and promotion, so neither is a product decision. Option C is not a marketing mix decision at all."}},{"itemId":"8301db1f-7234-54f9-b97d-005688e8555b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7c7e1603-1aa2-55d7-9175-ecc4e0dcf703","sourceKey":"bank:LAG-BUA111:PQ-054","parentItemId":null,"revision":1,"payload":{"prompt":"The place element of the marketing mix includes considerations like:","options":["Product innovation cycles","Supply chain logistics and channel management","Media campaigns","Price elasticity"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Place is about getting the product to customers where and when they want it, so it covers distribution channels, intermediaries, transport, warehousing and logistics. Option C belongs to promotion, option D to price, and option A to the product element."}},{"itemId":"9f9b30bc-f513-5f82-b3a2-558fa68e4df4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"198c7db6-ebea-5638-9912-6b9aadd20d28","sourceKey":"bank:LAG-BUA111:PQ-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which promotional tool in the marketing mix builds direct customer relationships?","options":["Product redesign","Distribution expansion","Price discounts","Personal selling"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Personal selling is face-to-face (or person-to-person) communication between a salesperson and a customer, which makes it the promotional tool best suited to building direct, two-way relationships. Option A is a product decision and option B is a place decision. Option C, price discounts, can lift short-term sales but does not create a personal, two-way relationship."}},{"itemId":"173dbc0b-e3a6-5cc6-98e0-157fd8283dfd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7ef91ad9-c6b7-512d-934a-2997ae94c61c","sourceKey":"bank:LAG-BUA111:PQ-056","parentItemId":null,"revision":1,"payload":{"prompt":"A competitive pricing strategy requires:","options":["Premium pricing well above market rates","Pricing below cost to gain share","Setting prices in line with competitors' prices","Ignoring market trends"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Competitive (competition-based) pricing sets prices with reference to what competitors charge, at, slightly above or slightly below their level. Option A is premium pricing, which deliberately stays above the market. Option B describes predatory pricing, and option D contradicts the idea of watching the market."}},{"itemId":"26050b76-5762-542b-8b35-9cc5c1afb795","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e0f40d79-5aff-5899-b1f5-c3c05123a482","sourceKey":"bank:LAG-BUA111:PQ-057","parentItemId":null,"revision":1,"payload":{"prompt":"The ultimate purpose of the marketing mix is to:","options":["Diminish customer satisfaction","Restrict product offerings","Balance customer value with organizational goals","Avoid all competitive threats"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"The marketing mix is designed to deliver value that satisfies target customers while also helping the organization reach its own goals, such as profit and growth. Option D is not realistic, since no mix can remove competition entirely. Options A and B would work against the customer and are not purposes of marketing."}},{"itemId":"52dd6f29-da9c-5966-a43c-ebcb9bc1a24f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4acc1a0a-fce2-5f7f-bc17-a9db9c99a831","sourceKey":"bank:LAG-BUA111:PQ-059","parentItemId":null,"revision":1,"payload":{"prompt":"Effective place strategies in the marketing mix focus on:","options":["High pricing models","Optimizing distribution so the product is accessible to customers","Customer communication","Product feature enhancement"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Place (distribution) is about making the product available to target customers at the right location and time, through suitable channels. Option C is the job of promotion, option A belongs to price, and option D belongs to the product element."}},{"itemId":"c2fa14f6-f209-5528-9d04-f2671ad62f09","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1272aa51-8a06-5e6e-a2b3-4383223589f4","sourceKey":"bank:LAG-BUA111:PQ-060","parentItemId":null,"revision":1,"payload":{"prompt":"Promotion in the marketing mix drives:","options":["Customer disengagement","Brand visibility and purchase intent","Reduced product reach","Production cost increases"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Promotion covers the activities that communicate a product's merits and persuade target customers to buy, such as advertising, sales promotion, personal selling and public relations. Its job is to raise awareness and move people towards buying. Options C, A and D are negative outcomes, not goals of promotion."}},{"itemId":"90d4980d-51a3-507d-a645-ad0ac19abed4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"dddf8230-61e2-54ff-9b21-e9160f8193c5","sourceKey":"bank:LAG-BUA111:PQ-061","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the stages of the product life cycle (PLC) after a product is launched?","options":["Growth, Introduction, Maturity, Decline","Introduction, Decline, Growth, Maturity","Introduction, Growth, Maturity, Decline","Introduction, Maturity, Growth, Decline"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Once a product is launched it is introduced to the market, sales then grow, level off at maturity, and finally fall in the decline stage. Options A, D and B contain the right stage names but in the wrong order; for example, growth cannot come before introduction, and maturity follows growth rather than coming before it."}},{"itemId":"893ce73d-c126-5cd6-a440-5990ecda43e9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6fe73d4f-e789-573d-820f-a4dd306d7971","sourceKey":"bank:LAG-BUA111:PQ-062","parentItemId":null,"revision":1,"payload":{"prompt":"In the introduction stage of the PLC, a firm typically faces:","options":["Peak profitability and market saturation","Stable revenue streams","High costs and low sales as awareness builds","Declining demand and obsolescence"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"At introduction the product is new, so few customers know about it and sales are low, while spending on promotion and distribution is high. Option A describes maturity, option D describes decline, and option B fits a mature product rather than a new one."}},{"itemId":"1fd78679-87a5-5a16-9ed2-5ca50188caa0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0b05bd0e-472b-50a2-ab4f-f6963fc5b42c","sourceKey":"bank:LAG-BUA111:PQ-063","parentItemId":null,"revision":1,"payload":{"prompt":"The growth stage of the PLC is marked by:","options":["Reduced marketing investment","Rapid sales increases and the entry of competitors","Product discontinuation","Profit erosion due to saturation"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"In the growth stage the market accepts the product, sales rise quickly and profits improve, which attracts new competitors into the market. Option D is typical of late maturity, and option C happens in decline. Option A is wrong because firms usually keep investing to grab market share during growth."}},{"itemId":"26278bb7-a763-5011-b426-960bafd73f5d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"68d33229-31e3-54fe-88ef-39893193b04e","sourceKey":"bank:LAG-BUA111:PQ-064","parentItemId":null,"revision":1,"payload":{"prompt":"During the maturity stage, marketers must address:","options":["High introductory costs","Slowing sales growth and intensified competition","Falling sales as consumers lose interest","Rapid sales expansion"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Maturity is usually the longest stage: sales growth slows or levels off and competition becomes intense as many firms fight for the same customers. Option D describes the growth stage, option C describes decline, and option A belongs to the introduction stage."}},{"itemId":"94ed6e68-5793-5b07-9841-d59ebc1c61da","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cb95b92c-e3c7-55b0-a7e7-06522e1dfe23","sourceKey":"bank:LAG-BUA111:PQ-065","parentItemId":null,"revision":1,"payload":{"prompt":"In the decline stage of the PLC, a strategic option includes:","options":["Aggressive market expansion","Raising prices for exclusivity","Product discontinuation or repositioning","Building first-time awareness among early adopters"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"When sales are falling, a firm can drop the product, reposition it, or try to revive it for a new use or market. Option A is a growth-stage move and makes little sense when demand is shrinking. Option D describes the introduction stage, and option B does not address the falling demand that defines decline."}},{"itemId":"29a81fe7-d0ca-5f15-b76a-7bc1205e1cce","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9430bfe8-6955-57ec-bc6b-15217cfb9534","sourceKey":"bank:LAG-BUA111:PQ-066","parentItemId":null,"revision":1,"payload":{"prompt":"The PLC provides marketers with:","options":["A cost-reduction blueprint","A dynamic tool to adapt strategies across stages","A method to avoid innovation","A fixed product roadmap that never changes"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"The PLC shows that a product's sales and profits change over time, so marketers use it to adjust their strategy as the product moves from one stage to the next. Option D is wrong because the whole point of the PLC is change, not a fixed plan. Options C and A are not what the PLC is used for."}},{"itemId":"19e8323a-c58d-5077-94a9-e8177d87f75d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"31b3c9e6-9acd-5ac2-9b67-642a8353a1ce","sourceKey":"bank:LAG-BUA111:PQ-067","parentItemId":null,"revision":1,"payload":{"prompt":"The introduction stage of the PLC prioritizes:","options":["Building awareness and encouraging trial","Product withdrawal","Price reductions for volume","Profit maximization"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Because a new product is unknown, the main task at introduction is to make target customers aware of it and get them to try it. Option D is unrealistic since profits are low or negative at this point. Option C is more typical of growth or maturity, and option B belongs to decline."}},{"itemId":"69075f61-1e9a-5019-b1b7-0736f847396d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7ccba67e-90a4-5087-927d-f545c1ec9f71","sourceKey":"bank:LAG-BUA111:PQ-068","parentItemId":null,"revision":1,"payload":{"prompt":"In the growth stage, a key challenge is:","options":["Stable market share","Rising competition that requires differentiation","Minimal marketing effort","Declining demand"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Rising sales and profits in the growth stage attract new competitors, so a firm must differentiate its product to protect and build its share. Option D describes decline. Options A and C are not challenges, and growth actually needs strong marketing effort."}},{"itemId":"a96c2fdc-61ac-5ee2-bc35-3c10a5998ea0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8d92ca94-2033-5c4d-a239-983ad17db02d","sourceKey":"bank:LAG-BUA111:PQ-069","parentItemId":null,"revision":1,"payload":{"prompt":"The maturity stage often requires:","options":["Managing a steep fall in sales","Product termination","High launch costs","Product modification or market extension"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"To keep sales up in a crowded mature market, firms modify the product (new features, variants) or extend the market by finding new users or uses. Option C belongs to the introduction stage. Options A and B describe what happens in the decline stage."}},{"itemId":"2702d677-baa0-5561-bddf-f6c28fbd5187","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b73d2799-7c34-5d8b-ad71-bfa1c536c3d5","sourceKey":"bank:LAG-BUA111:PQ-070","parentItemId":null,"revision":1,"payload":{"prompt":"The decline stage is frequently triggered by:","options":["Market saturation alone","New technology or shifts in consumer preferences","Profit surges","Sustained consumer demand"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Products usually enter decline when a newer technology replaces them or when consumer tastes change, so demand falls. Options D and C are signs of a healthy product, not a declining one. Option A is incomplete, because saturation is a feature of maturity and does not on its own cause decline."}},{"itemId":"1700117b-eecd-5689-95a6-b07b1c44949f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3a325541-628b-531c-a086-32c2ab25263e","sourceKey":"bank:LAG-BUA111:PQ-071","parentItemId":null,"revision":1,"payload":{"prompt":"The predictive value of the PLC lies in its ability to:","options":["Limit product evolution","Help forecast product performance and guide strategy","Ignore customer trends","Minimize marketing efforts"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"By showing the typical pattern of sales and profits over time, the PLC helps marketers anticipate what is likely to happen next and plan the right strategy for each stage. Options D, C and A would weaken marketing and are not benefits of the PLC."}},{"itemId":"287b41c1-6cfd-584d-8a9b-775036742341","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"53fa5581-9505-5a36-91d8-46de5b765389","sourceKey":"bank:LAG-BUA111:PQ-072","parentItemId":null,"revision":1,"payload":{"prompt":"Profits in the introduction stage are typically:","options":["At their peak","Declining rapidly","Low or negative because of heavy investment costs","Rising steadily with fast sales growth"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"At introduction, sales are still small while spending on development, promotion and distribution is high, so profits are low or even negative. Option A fits maturity, option D describes the growth stage, and option B describes decline."}},{"itemId":"c1cbffaa-1a53-52a3-b789-0758f49fc42f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7b9890fe-3ecf-529c-b981-4b7859330d88","sourceKey":"bank:LAG-BUA111:PQ-073","parentItemId":null,"revision":1,"payload":{"prompt":"During the growth stage, firms often:","options":["Lower prices to attract more buyers","Discontinue marketing efforts","Reduce product quality","Avoid competitive analysis"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"In the growth stage, firms often lower prices at the right time to draw in more price-sensitive buyers and widen the market, while also improving the product. Options B, C and D would hand the growing market to competitors and are poor growth strategies."}},{"itemId":"51264da6-3f69-51c6-bc4d-80d5394f081f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"045fb5b8-b3cf-5c3b-b27c-27adc0320727","sourceKey":"bank:LAG-BUA111:PQ-074","parentItemId":null,"revision":1,"payload":{"prompt":"The maturity stage demands:","options":["Limited distribution","High introductory pricing","Sustained promotion to defend market position","Immediate product withdrawal"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Competition is at its strongest in maturity, so firms keep promoting the product to hold on to customers and defend their market share. Option B belongs to introduction (for example skimming), option D is a decline decision, and option A would lose ground to rivals."}},{"itemId":"a73980b3-6d19-5608-8e13-7e26a97ee9b6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"40263091-ce1d-5cc6-86b5-e05e67b78e2b","sourceKey":"bank:LAG-BUA111:PQ-075","parentItemId":null,"revision":1,"payload":{"prompt":"A decline stage strategy might involve:","options":["Ignoring market trends","Heavy introductory promotion to build awareness","Revitalizing the product or phasing it out","Expanding sales volume aggressively"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"In decline, a firm must decide whether to revive the product (for example with a new use or market) or to phase it out. Option D goes against falling demand, option B is an introduction-stage activity, and option A would leave the firm unprepared."}},{"itemId":"f0273dd4-ec3f-5860-a9ab-9011a1e09545","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3f5488ff-00d0-57e8-8fc9-63bdabb7c240","sourceKey":"bank:LAG-BUA111:PQ-076","parentItemId":null,"revision":1,"payload":{"prompt":"The introduction stage focuses on overcoming:","options":["Consumer unfamiliarity and barriers to adoption","Profit declines","Market saturation","Competitive saturation"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"A newly launched product is unknown to most buyers, so marketing at this stage works to inform people and get them to try it. Options C and D are maturity problems, when the market is full, and option B is a problem of decline."}},{"itemId":"00f8ce8d-e3d8-5f19-8fc9-40c2f19c3fb9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d366a3ab-9856-5da4-84e1-e0a4e42fd3a7","sourceKey":"bank:LAG-BUA111:PQ-077","parentItemId":null,"revision":1,"payload":{"prompt":"The growth stage signals:","options":["Rising acceptance and sales momentum","High introductory costs","Product obsolescence","Market rejection"],"correctOption":0,"section":"Marketing Mix and Product Life Cycle","explanation":"Growth means the market has accepted the product, so sales climb quickly and more customers buy. Option D is the opposite of growth, option B belongs to the introduction stage, and option C describes decline."}},{"itemId":"07b7ebf3-dcba-56d0-9822-5b47683f7efa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"285c716d-0317-552a-8acf-63bc01fe2a0d","sourceKey":"bank:LAG-BUA111:PQ-078","parentItemId":null,"revision":1,"payload":{"prompt":"In the maturity stage, firms may succeed by:","options":["Avoiding competition","Withdrawing from the market","Launching product variants or targeting new segments","Cutting all marketing budgets"],"correctOption":2,"section":"Marketing Mix and Product Life Cycle","explanation":"Mature markets are crowded, so firms keep sales going by modifying the product, adding variants, or reaching new segments and uses. Option D would lose share to rivals, option B is a decline-stage decision, and option A is not possible in a competitive mature market."}},{"itemId":"a1f35981-64cb-5431-bab7-acab20197228","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d6e8de81-6175-5b72-b514-4524bea76232","sourceKey":"bank:LAG-BUA111:PQ-079","parentItemId":null,"revision":1,"payload":{"prompt":"One way to extend a product's life when it enters the decline stage is to:","options":["Raise prices significantly","Identify new uses or new markets for it","Stop all promotion","Reduce product quality"],"correctOption":1,"section":"Marketing Mix and Product Life Cycle","explanation":"Finding new uses or new markets creates fresh demand for a product and can push back its decline. Options A and D would make the product less attractive just when demand is falling. Option C is a feature of phasing out a product, not extending its life."}},{"itemId":"c2f0b430-a3be-5908-bad6-3881fa019dd4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7c19cde8-f18b-5de7-b52b-7f2f7fbd40a5","sourceKey":"bank:LAG-BUA111:PQ-080","parentItemId":null,"revision":1,"payload":{"prompt":"The PLC empowers marketers to:","options":["Lower customer satisfaction","Increase operational costs","Avoid product evolution","Tailor strategies to the product's life cycle stage"],"correctOption":3,"section":"Marketing Mix and Product Life Cycle","explanation":"Each PLC stage has its own sales, profit and competitive conditions, so the PLC helps marketers choose the strategy that fits the current stage. Options C, A and B are not benefits of the PLC and would harm the business."}},{"itemId":"749455b6-7317-5ec3-9b44-7909363ee29a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"edc261f7-88f1-5182-9063-fd31c0e2bd00","sourceKey":"bank:LAG-BUA111:PQ-081","parentItemId":null,"revision":1,"payload":{"prompt":"Market segmentation involves:","options":["Treating all customers in exactly the same way","Ignoring consumer diversity","Reducing product offerings","Dividing a broad market into smaller groups with shared characteristics"],"correctOption":3,"section":"Market Segmentation","explanation":"Market segmentation is the process of dividing a broad market into smaller groups of customers who share meaningful characteristics such as demographics, geography, psychographics or behaviour. Options A and B describe the opposite approach, mass marketing that ignores differences. Option C is not what segmentation means."}},{"itemId":"f08b206b-c5b8-5409-adad-b9d52d845e0b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"35d65ab0-0b52-55af-bfd6-97545ec86af2","sourceKey":"bank:LAG-BUA111:PQ-082","parentItemId":null,"revision":1,"payload":{"prompt":"Which segmentation basis is most sensitive to regional product preferences?","options":["Psychographic","Behavioural","Geographic","Demographic"],"correctOption":2,"section":"Market Segmentation","explanation":"Geographic segmentation groups customers by where they live or work, such as country, state, city, climate or urban versus rural area, so it directly captures regional differences in what people buy. Option D uses population features such as age and income, option A uses personality and lifestyle, and option B uses buying and usage patterns."}},{"itemId":"4bbebc62-30fc-578c-a6fb-1960e83e67d3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"57576912-f50a-53ea-a433-b35fe61c7905","sourceKey":"bank:LAG-BUA111:PQ-083","parentItemId":null,"revision":1,"payload":{"prompt":"Demographic segmentation uses variables like:","options":["Regional climate","Personality traits","Age, income and occupation","Purchase frequency"],"correctOption":2,"section":"Market Segmentation","explanation":"Demographic segmentation groups people by population characteristics such as age, sex, religion, income and occupation. Option B is a psychographic variable, option A is geographic, and option D is a behavioural variable."}},{"itemId":"2604853f-fe1f-543f-a923-a4e23d497c53","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0c219b89-96b7-597c-8423-13d6183d5c5a","sourceKey":"bank:LAG-BUA111:PQ-084","parentItemId":null,"revision":1,"payload":{"prompt":"Psychographic segmentation uncovers:","options":["Geographic boundaries","Purchase and usage behaviour","Measurable demographics","Intangible factors such as values and lifestyles"],"correctOption":3,"section":"Market Segmentation","explanation":"Psychographic segmentation groups people by psychological traits: their values, attitudes, lifestyle, personality and motivations. Option C is the focus of demographic segmentation, option A is geographic, and option B is behavioural segmentation."}},{"itemId":"8c8ac225-9bf4-5218-9a6d-7cff230f36ef","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"321897a4-75ec-5256-b309-508bfc92452b","sourceKey":"bank:LAG-BUA111:PQ-085","parentItemId":null,"revision":1,"payload":{"prompt":"Behavioural segmentation prioritizes:","options":["Consumer usage, loyalty and purchase occasions","Location-based needs","Lifestyle preferences","Age and gender profiles"],"correctOption":0,"section":"Market Segmentation","explanation":"Behavioural segmentation groups customers by how they act towards a product: how often they use it, how loyal they are, when they buy and what benefits they seek. Option B is geographic, option D is demographic, and option C is psychographic."}},{"itemId":"c7e8d399-1061-5f03-a03e-8755fdb08181","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"805c7882-40fe-5ead-9b6e-aedb64e411b9","sourceKey":"bank:LAG-BUA111:PQ-086","parentItemId":null,"revision":1,"payload":{"prompt":"The strategic goal of market segmentation is to:","options":["Limit product innovation","Standardize marketing efforts","Avoid all competitive overlap","Meet diverse customer needs more precisely"],"correctOption":3,"section":"Market Segmentation","explanation":"Segmentation lets a firm tailor its products and marketing to each group, so it can satisfy different customer needs more precisely and profitably. Option B is the mass-marketing approach that segmentation moves away from. Options A and C are not goals of segmentation."}},{"itemId":"16a3e806-d7c3-5368-b2cb-1e0367cb1266","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"65a94eda-1b6c-5368-bddd-bff973da94f3","sourceKey":"bank:LAG-BUA111:PQ-087","parentItemId":null,"revision":1,"payload":{"prompt":"Geographic segmentation is most important when:","options":["Personality drives purchases","Consumer needs and tastes differ by region","Brand loyalty patterns emerge","Income levels vary widely"],"correctOption":1,"section":"Market Segmentation","explanation":"Geographic segmentation matters most when where people live affects what they buy, for example because of climate, culture, language or how urban an area is. Option D points to demographic segmentation, option A to psychographic segmentation, and option C to behavioural segmentation."}},{"itemId":"4ee67297-1bc2-5976-a2f9-6c6cd885d891","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"71ce5c0e-5046-505f-8e86-1bce856571f1","sourceKey":"bank:LAG-BUA111:PQ-088","parentItemId":null,"revision":1,"payload":{"prompt":"Targeting \"millennials with disposable income\" is an example of:","options":["Geographic segmentation","Psychographic segmentation","Demographic segmentation","Behavioural segmentation"],"correctOption":2,"section":"Market Segmentation","explanation":"Both parts of this target are demographic: millennials is a generation (an age group) and disposable income is an income variable. Option B would focus on lifestyle or personality, option A on location, and option D on buying or usage behaviour."}},{"itemId":"8c0bb90d-c622-5b9f-9ec7-ef5f0d813682","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7fe25898-31c8-53d9-b683-b5c2187afb8c","sourceKey":"bank:LAG-BUA111:PQ-089","parentItemId":null,"revision":1,"payload":{"prompt":"Psychographic segmentation provides insights into:","options":["Usage frequency","Demographic trends","Regional purchasing power","Consumer motivations and lifestyle choices"],"correctOption":3,"section":"Market Segmentation","explanation":"Psychographic segmentation looks at how people think and live, including their motivations, values, attitudes and lifestyles. Option C relates to geographic segmentation, option A is a behavioural variable, and option B belongs to demographic segmentation."}},{"itemId":"91b9a648-f887-5283-bb5b-55cd98750891","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6b1a525b-b26b-558d-8494-5ad7fd67619f","sourceKey":"bank:LAG-BUA111:PQ-090","parentItemId":null,"revision":1,"payload":{"prompt":"Behavioural segmentation might target:","options":["Age-specific groups","Consumers with an adventurous personality","Urban dwellers","Brand-loyal customers for retention campaigns"],"correctOption":3,"section":"Market Segmentation","explanation":"Brand loyalty is a behaviour, because it describes how customers act towards a brand, so targeting loyal customers is behavioural segmentation. Option A is demographic, option C is geographic, and option B is psychographic because it is based on personality."}},{"itemId":"ad091c16-02a6-5fb9-9d38-c4d0b644e618","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a585d8fe-1af1-579c-8151-ee66226813f2","sourceKey":"bank:LAG-BUA111:PQ-091","parentItemId":null,"revision":1,"payload":{"prompt":"Market segmentation enables firms to:","options":["Disregard consumer feedback","Customize offerings for distinct customer groups","Escalate production costs","Reduce product diversity"],"correctOption":1,"section":"Market Segmentation","explanation":"Once a market is divided into segments, a firm can design products, prices and messages that fit each group's particular needs. Options A, D and C are not benefits of segmentation."}},{"itemId":"14e5883c-be54-5402-928f-1d3cafa83bf7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"aaf268f1-f4a3-5257-a653-59ede626e13d","sourceKey":"bank:LAG-BUA111:PQ-092","parentItemId":null,"revision":1,"payload":{"prompt":"Targeting \"coastal residents\" reflects:","options":["Geographic segmentation","Demographic segmentation","Behavioural segmentation","Psychographic segmentation"],"correctOption":0,"section":"Market Segmentation","explanation":"Coastal residents are defined by where they live, which makes this geographic segmentation. Option B would use age, income or similar population features, option D would use lifestyle or personality, and option C would use buying or usage behaviour."}},{"itemId":"39e687aa-72a8-56d0-a8ad-5aa82a15aaac","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b4d5075b-c6bd-5ffc-b22f-f1cedb4c31d3","sourceKey":"bank:LAG-BUA111:PQ-093","parentItemId":null,"revision":1,"payload":{"prompt":"A key strength of demographic segmentation is:","options":["Its use of measurable, easily available data","Its emphasis on lifestyle nuances","Its insight into usage behaviour","Its geographic specificity"],"correctOption":0,"section":"Market Segmentation","explanation":"Demographic variables such as age, sex, income and occupation are easy to measure and data on them is widely available, which is why demographic segmentation is the most commonly used type. Option B describes psychographic segmentation, option D describes geographic segmentation, and option C describes behavioural segmentation."}},{"itemId":"78417d29-f8af-587b-b710-99202358d178","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d4037d38-80cf-5c22-a44e-2185f53ae1fb","sourceKey":"bank:LAG-BUA111:PQ-094","parentItemId":null,"revision":1,"payload":{"prompt":"Psychographic segmentation includes variables like:","options":["Attitudes, interests and opinions","Age and education","Purchase timing","Regional preferences"],"correctOption":0,"section":"Market Segmentation","explanation":"Attitudes, interests and opinions are psychological variables, so they belong to psychographic segmentation along with values, lifestyle and personality. Option B is demographic, option D is geographic, and option C is behavioural."}},{"itemId":"47f1a566-eefe-5161-9287-5afe980f043b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e13e5b68-073a-521d-97bc-eaca045c6fd5","sourceKey":"bank:LAG-BUA111:PQ-095","parentItemId":null,"revision":1,"payload":{"prompt":"Behavioural segmentation can segment customers by:","options":["Geographic location","How heavily they use the product","Income brackets","Personality traits"],"correctOption":1,"section":"Market Segmentation","explanation":"Usage rate (light, medium or heavy users) describes how customers behave towards a product, so it is a behavioural variable. Option A is geographic, option C is demographic, and option D is psychographic."}},{"itemId":"88d08dae-9674-51dc-9091-3ce8030153a3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a6b2560b-6ae9-518a-b6dc-8f09c53ec22f","sourceKey":"bank:LAG-BUA111:PQ-096","parentItemId":null,"revision":1,"payload":{"prompt":"Market segmentation improves efficiency by:","options":["Lowering product quality","Directing resources to high-potential segments","Broadening generic campaigns","Increasing operational costs"],"correctOption":1,"section":"Market Segmentation","explanation":"Segmentation helps a firm see which groups are most attractive and focus its money and effort on them instead of spreading resources thinly across everyone. Option C is the mass-marketing approach that wastes effort on people unlikely to buy. Options A and D are not benefits of segmentation."}},{"itemId":"eecca97e-c423-5f88-a08d-72474943c3c4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f2360a4a-a82b-5f53-b81f-f57a37f0018a","sourceKey":"bank:LAG-BUA111:PQ-097","parentItemId":null,"revision":1,"payload":{"prompt":"Targeting \"frequent flyers\" is an example of:","options":["Behavioural segmentation","Demographic segmentation","Geographic segmentation","Psychographic segmentation"],"correctOption":0,"section":"Market Segmentation","explanation":"Frequent flyers are defined by how often they use a service, which is a usage-rate variable, so this is behavioural segmentation. Option C would use location, option B would use features such as age or income, and option D would use lifestyle or personality."}},{"itemId":"e2b07c83-a77a-5196-bec6-0822d7219da8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fecc267b-e13b-5ef7-b013-93b01affee78","sourceKey":"bank:LAG-BUA111:PQ-098","parentItemId":null,"revision":1,"payload":{"prompt":"Geographic segmentation works best in markets where:","options":["Behavioural patterns are uniform","Regional tastes or climates shape demand","Universal products dominate","Pricing is standardized"],"correctOption":1,"section":"Market Segmentation","explanation":"Geographic segmentation is most useful when location changes what people want, for example when climate, season or local culture affects demand. Option C is a case where location makes little difference to demand. Options A and D say nothing about regional differences."}},{"itemId":"d7aab1a3-c1e9-5e7c-ab6c-5b0bf09aacfb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"727f8eed-b5de-53b6-ba47-990bb8a2b51b","sourceKey":"bank:LAG-BUA111:PQ-099","parentItemId":null,"revision":1,"payload":{"prompt":"Psychographic segmentation is very useful for:","options":["Mapping geographic trends","Measuring income levels","Tracking usage rates","Understanding why consumers choose certain brands"],"correctOption":3,"section":"Market Segmentation","explanation":"Psychographic segmentation looks at motivations, values, attitudes and lifestyle, so it helps explain why people prefer one brand over another. Option A is geographic, option C is behavioural, and option B is demographic."}},{"itemId":"072d6815-be50-59f6-a6f4-ca62d82618bb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ad7378f4-eff4-5433-baff-42e041369d4a","sourceKey":"bank:LAG-BUA111:PQ-100","parentItemId":null,"revision":1,"payload":{"prompt":"Market segmentation improves marketing by:","options":["Reducing product innovation","Applying uniform strategies across markets","Avoiding competitive analysis","Focusing efforts on solutions tailored to each customer group"],"correctOption":3,"section":"Market Segmentation","explanation":"Segmentation helps a firm design products and messages that fit each group's specific needs, which makes its marketing more relevant and effective. Option B describes mass marketing, the opposite of segmentation. Options A and C are not benefits of segmentation."}},{"itemId":"43ac2fa4-23b3-5599-80dd-981aed7df91b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a1e27462-b4d8-595e-802b-a9446816f8a0","sourceKey":"bank:LAG-BUA111:PQ2-001","parentItemId":null,"revision":1,"payload":{"prompt":"If the ultimate goal of any business organisation is to identify and satisfy customers, then that goal can only be realised by embarking on effective ______ activities.","options":["production","selling","marketing","managerial"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Identifying what customers need and satisfying them is exactly what marketing does, so a firm reaches this goal only through effective marketing activities. Option B is too narrow: selling is just one part of marketing and focuses on the seller's need to move goods. Options D and A describe general management and making the product, which do not by themselves find out or satisfy customer needs."}},{"itemId":"3db4e8d3-d880-51d2-971f-b4756a73a74d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"333bd0b0-3e67-5001-9f56-fe6227ade6ef","sourceKey":"bank:LAG-BUA111:PQ2-002","parentItemId":null,"revision":1,"payload":{"prompt":"In a societal sense, ______ is any exchange activity intended to satisfy human wants.","options":["financing","marketing","production","management"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Viewed from society's point of view, marketing is any exchange activity aimed at satisfying human wants; in a business sense it is the system that plans, prices, promotes and distributes want-satisfying goods and services. Option C creates goods but is not itself an exchange activity, while options D and A are general business functions rather than exchange activities."}},{"itemId":"1265a07f-6e15-5bde-b273-ba480bd44d25","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"be20ef67-f0ad-5a11-b6d4-16279d03f35d","sourceKey":"bank:LAG-BUA111:PQ2-003","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a social and managerial process by which individuals and groups obtain what they need and want through creating and exchanging products and value with others.","options":["Marketing","Production","Selling","Management"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"This is the classic definition of marketing: a social and managerial process in which people get what they need and want by creating and exchanging products and value. Option C is only one activity within marketing, and option B is about making goods, not exchanging them. Option D is far broader than this exchange process."}},{"itemId":"26b4a643-2683-592a-aded-ac6082421170","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bbab4711-8501-5086-8339-a3f7a95581e2","sourceKey":"bank:LAG-BUA111:PQ2-004","parentItemId":null,"revision":1,"payload":{"prompt":"______ focuses the firm's or individual's attention on the needs and wants of the marketplace.","options":["Marketing","Distribution","Selling","Production"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing begins with the customer: it turns the attention of a firm or individual outward to the needs and wants of the marketplace. Option C focuses on the seller's need to convert products into cash, and option D focuses on making goods efficiently. Option B only moves products to buyers and is one part of marketing."}},{"itemId":"63be81f0-8b1c-5294-a039-8ee85844a6a1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9a2918ca-4d9c-532d-83a0-f159000398dd","sourceKey":"bank:LAG-BUA111:PQ2-005","parentItemId":null,"revision":1,"payload":{"prompt":"______ is both a functional area of management and an overall business philosophy which recognises that the identification, satisfaction and retention of customers is the key to business success.","options":["Selling","Production","Finance","Marketing"],"correctOption":3,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing plays two roles at once: it is a department or function, and it is a philosophy for the whole business that puts finding, satisfying and keeping customers at the centre. Options B and C are functional areas but are not built around customer satisfaction and retention. Option A is a single marketing activity, not a whole business philosophy."}},{"itemId":"d6beb994-9753-5c1d-966f-9687c5590daa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e7b275cf-c8cc-5253-9639-269e917cceab","sourceKey":"bank:LAG-BUA111:PQ2-006","parentItemId":null,"revision":1,"payload":{"prompt":"______ consists of all activities aimed at identifying and satisfying customer needs through beneficial exchanges with target markets.","options":["Marketing","Production","Finance","Selling"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing covers every activity used to find out what customers need and satisfy those needs through exchanges that benefit both sides, from research and product development to pricing, promotion and distribution. Option D is only one of these activities, while options B and C deal with making goods and managing money rather than with exchanges with target markets."}},{"itemId":"840191ab-fac7-546c-a423-527afd00b171","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f1057efa-3295-5f1c-8324-db30da53b0fe","sourceKey":"bank:LAG-BUA111:PQ2-007","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ holds that consumers will buy those products that are widely available and low in price.","options":["product concept","production concept","selling concept","societal marketing concept"],"correctOption":1,"section":"Marketing Concepts and Market Orientation","explanation":"The production concept assumes buyers want goods that are cheap and easy to find, so the firm concentrates on efficient production and wide distribution. Option A assumes buyers want the highest quality, not the lowest price. Option C relies on aggressive promotion, and option D adds concern for society's welfare."}},{"itemId":"0fff55ac-4152-54c1-842a-83fb9e706577","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3a4b2238-d1d5-5675-a4ae-918db37d66c2","sourceKey":"bank:LAG-BUA111:PQ2-008","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ holds that consumers will buy those products that are of the highest quality in the marketplace.","options":["selling concept","marketing concept","production concept","product concept"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"Under the product concept, the firm believes buyers will choose the best-quality product, so it puts its effort into making excellent products; carried too far, this leads to marketing myopia. Option C bets on low prices and wide availability instead. Option A relies on pushing sales, and option B starts from customer needs rather than from the product."}},{"itemId":"b52858fe-6a63-5f6b-9b67-da373e1d53f3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"68f6c915-e280-58fb-90ad-1cb1c6b18ba1","sourceKey":"bank:LAG-BUA111:PQ2-009","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ holds that a business organisation should produce what it wants and then make great efforts to convince consumers to buy the products.","options":["product concept","production concept","marketing concept","selling concept"],"correctOption":3,"section":"Marketing Concepts and Market Orientation","explanation":"The selling (sales) concept is 'make it first, then push it': the firm produces what it chooses and uses aggressive promotion and high-pressure selling to get consumers to buy. Option C is the opposite, because it starts by finding out what customers need. Options A and B rely on product quality and on low price and availability, not on heavy persuasion."}},{"itemId":"2cc74baf-14fc-5f5d-a2eb-4598fe1b05bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"15f127f1-3ae0-5296-bf80-2f3270b8bbd3","sourceKey":"bank:LAG-BUA111:PQ2-010","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ involves the identification and satisfaction of customers' needs and wants by companies.","options":["marketing concept","product concept","selling concept","production concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The marketing concept puts the customer at the centre: the firm first identifies what customers need and want, then satisfies them. Option C starts from what the firm has already produced and pushes it on buyers. Options D and B focus on production efficiency and product quality rather than on customer needs."}},{"itemId":"fc383091-0c29-5e6f-9d45-2886abed890d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"59339c1c-dff0-521a-9074-f4b502b5d183","sourceKey":"bank:LAG-BUA111:PQ2-011","parentItemId":null,"revision":1,"payload":{"prompt":"In its broadened form, the ______ involves not only identifying and satisfying customers' needs and wants, but doing so more effectively and efficiently than competitors.","options":["marketing concept","product concept","selling concept","production concept"],"correctOption":0,"section":"Marketing Concepts and Market Orientation","explanation":"The broadened version of the marketing concept adds competition: it is not enough to satisfy customers, the firm must do it better and more efficiently than its rivals. Option C pushes whatever the firm makes, while options D and B focus on low cost and product quality rather than on satisfying customer needs better than competitors."}},{"itemId":"bfea9303-1dd8-5c88-b248-6730de645244","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cd145ad5-4ce0-5d87-b966-dba4fb5ed060","sourceKey":"bank:LAG-BUA111:PQ2-012","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ holds that the organisation's task is to determine the needs, wants and interests of customers and to satisfy them more effectively and efficiently than competitors, in a way that preserves or enhances the welfare of the consumer and society.","options":["production concept","selling concept","societal marketing concept","marketing concept"],"correctOption":2,"section":"Marketing Concepts and Market Orientation","explanation":"The societal marketing concept keeps everything in the marketing concept and adds long-run welfare, so marketers balance company profit, consumer satisfaction and the interests of the public. Option D is the tempting one, but it stops at satisfying customers better than competitors and says nothing about society's welfare. Options A and B do not start from customer needs at all."}},{"itemId":"41121a49-8380-58e5-94fe-5185fd7bd984","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6afff882-a520-5079-b193-967b6dc88ab9","sourceKey":"bank:LAG-BUA111:PQ2-013","parentItemId":null,"revision":1,"payload":{"prompt":"The basic role of ______ is to enhance the growth of economies as well as the standard of living of individuals.","options":["marketing","accounting","selling","planning"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Marketing helps economies grow by building effective distribution systems for raw materials and finished goods, and it raises living standards by getting want-satisfying products to people. Option C is only one activity within marketing, while options D and B are general management tasks that support a business rather than serve this wider economic role."}},{"itemId":"23d3d12d-ddbe-5209-873f-c8323e08ca09","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"741e10e8-67c8-5ce5-8b5b-742427ddb61e","sourceKey":"bank:LAG-BUA111:PQ2-014","parentItemId":null,"revision":1,"payload":{"prompt":"The simplest marketing system consists of two interacting elements, namely","options":["the marketing organisation and its target market","channel members and the marketing organisation","the marketing organisation and the marketing mix elements","the target market and channel members"],"correctOption":0,"section":"Marketing System","explanation":"At its simplest, a marketing system links the marketing organisation and its target market through two flows: products go to customers in exchange for payment, and information flows both ways through selling, advertising and customer feedback. Option C pairs the organisation with tools it controls, not with another party it interacts with. Options D and B bring in channel members, which belong to the larger system but are not part of the simplest two-element one."}},{"itemId":"a6498e51-30ca-5da1-991e-2d5fe57b324d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"31631fc8-540c-59d1-95ec-255a30c5df68","sourceKey":"bank:LAG-BUA111:PQ2-016","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing carried out by nonprofit organisations is also referred to as ______.","options":["macromarketing","megamarketing","nonbusiness marketing","demarketing"],"correctOption":2,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"When organisations whose main aim is not profit, such as charities, churches, schools or public agencies, use marketing, it is called nonbusiness (nonprofit) marketing. Option A studies marketing at the level of the whole society. Option D means deliberately reducing demand, and option B uses power and public relations to break into blocked markets."}},{"itemId":"c2e5b892-cbc2-5b02-80a3-3f2325337d39","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7600d62f-f7c8-5319-917d-1274d494d51f","sourceKey":"bank:LAG-BUA111:PQ2-017","parentItemId":null,"revision":1,"payload":{"prompt":"The aspect of marketing that can be regarded as firm-oriented, looking at marketing activities from the point of view of the individual organisation, is ______.","options":["micromarketing","megamarketing","demarketing","macromarketing"],"correctOption":0,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Micromarketing looks at marketing from the level of the individual firm: how one organisation plans and carries out its marketing activities to satisfy its customers. Option D is its opposite, because it looks at marketing from the viewpoint of the whole society. Option C is reducing demand, and option B is using power and public relations to enter protected markets."}},{"itemId":"14ae968e-a7bf-586d-a577-0bff6e585eb5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5ecd2c05-ddc7-52fc-bef4-f30a663d0b25","sourceKey":"bank:LAG-BUA111:PQ2-018","parentItemId":null,"revision":1,"payload":{"prompt":"The branch of marketing that studies exchange activities and exchange systems from a societal perspective, including the relationship between marketing systems and the rest of society, is known as ______.","options":["demarketing","macromarketing","micromarketing","megamarketing"],"correctOption":1,"section":"Meaning, Exchange Process and Functions of Marketing","explanation":"Macromarketing takes the big picture: it studies how a society's whole marketing system works and how it affects, and is affected by, the rest of society. Option C is the firm-level view of marketing. Option A means reducing demand, and option D is the use of power and public relations to enter blocked markets."}},{"itemId":"970dd856-e036-50c3-a160-73eb907f62c3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a99fe693-6ead-5ba2-94ab-9cd458f05e0f","sourceKey":"bank:LAG-BUA111:PQ2-020","parentItemId":null,"revision":1,"payload":{"prompt":"The factors and forces that influence the marketing function of an organisation constitute the ______.","options":["marketing environment","megamarketing","organisational boundary","demarketing"],"correctOption":0,"section":"Marketing Environment","explanation":"The marketing environment is made up of all the factors and forces, inside and outside the firm, that influence its marketing function. It is divided into the internal environment and the external environment. Option B is a strategy for entering protected markets and option D is reducing demand, while option C is only the dividing line between a firm and its surroundings."}},{"itemId":"2138d66b-8f6b-52b8-bb07-41414c04341b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"82eee702-0bf6-5dc6-8d79-dcb2edfec599","sourceKey":"bank:LAG-BUA111:PQ2-021","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ comprises internal forces and factors that influence the marketing function of an organisation.","options":["megamarketing","external environment","internal environment","macroenvironment"],"correctOption":2,"section":"Marketing Environment","explanation":"The internal environment consists of the forces inside the firm, such as the other departments (production, finance, personnel) that marketing must work with, and these are largely within the firm's control. Options B and D refer to forces outside the organisation that it has little control over. Option A is a strategy, not part of the environment."}},{"itemId":"806e0c55-7656-5f75-8fa7-4656dbbddf97","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7e68b011-0a15-5402-b38b-a8fd6820e85e","sourceKey":"bank:LAG-BUA111:PQ2-022","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ consists of external forces and factors influencing the marketing function of the organisation.","options":["external environment","internal environment","demarketing","micromarketing"],"correctOption":0,"section":"Marketing Environment","explanation":"The external environment is made up of forces outside the firm, such as customers, competitors, suppliers, the economy, technology and government, over which it has little or no control. Option B covers forces inside the organisation. Options C and D are kinds of marketing activity, not parts of the environment."}},{"itemId":"db79d89f-3d09-56ae-9f2c-8c6e170f22ba","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bbfda947-3d33-5a30-a1be-d4b4550a082b","sourceKey":"bank:LAG-BUA111:PQ2-023","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ consists of the forces and factors in the company's immediate environment.","options":["macromarketing","macroenvironment","micromarketing","microenvironment"],"correctOption":3,"section":"Marketing Environment","explanation":"The microenvironment, also called the task environment, is made up of the actors close to the firm that directly affect its ability to serve customers, such as suppliers, intermediaries, customers and competitors. Option B covers the wider societal forces. Option C sounds similar, but micromarketing is the firm-level view of marketing activity, not part of the environment, and option A is the society-wide study of marketing."}},{"itemId":"1a0bcd70-50bf-52be-888b-dddbadcc0546","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"96088fd2-5a32-5312-a766-44c1dd71ec5d","sourceKey":"bank:LAG-BUA111:PQ2-024","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ comprises the larger societal forces that affect the actors in the company's immediate environment.","options":["megamarketing","macromarketing","microenvironment","macroenvironment"],"correctOption":3,"section":"Marketing Environment","explanation":"The macroenvironment is the broad environment of large societal forces, such as demographic, economic, natural, technological, political-legal and socio-cultural forces, that affect the firm and every actor around it. Option C is the company's immediate environment of suppliers, intermediaries, customers and competitors. Option B sounds similar but is the society-wide study of marketing, not an environment."}},{"itemId":"05bef903-e658-5c1c-be13-783c2751f46b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c4757726-33eb-5c6e-b116-1f1ecc7b629f","sourceKey":"bank:LAG-BUA111:PQ2-025","parentItemId":null,"revision":1,"payload":{"prompt":"The microenvironment consists of the following factors except","options":["market intermediaries","economic forces","suppliers","customers"],"correctOption":1,"section":"Marketing Environment","explanation":"Economic forces such as inflation, interest rates and unemployment are part of the macroenvironment, the broad forces that affect the whole industry. Suppliers, market intermediaries and customers (options C, A and D) are actors close to the firm that directly affect its ability to serve its market, so they belong to the microenvironment."}},{"itemId":"60a5a574-7e98-5e77-9a44-9f2433186635","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3cb57f79-72c0-5801-a41d-a24ba376e1d3","sourceKey":"bank:LAG-BUA111:PQ2-026","parentItemId":null,"revision":1,"payload":{"prompt":"The macroenvironment comprises the following factors except","options":["technological forces","demographic forces","socio-cultural forces","the company"],"correctOption":3,"section":"Marketing Environment","explanation":"The company itself is not a macroenvironmental force; it is the organisation those broad forces act upon. Demographic, technological and socio-cultural forces (options B, A and C) are all large societal forces beyond the firm's control that make up the macroenvironment."}},{"itemId":"c95d79ba-fe69-5573-9d03-c87b3a93311a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0d794087-4f78-5e63-9a99-652a2c769620","sourceKey":"bank:LAG-BUA111:PQ2-027","parentItemId":null,"revision":1,"payload":{"prompt":"The demographic environment consists of the following factors except ______.","options":["age distribution","prices","marriage and death rates","population size"],"correctOption":1,"section":"Marketing Environment","explanation":"Prices are an economic matter, not a demographic one. The demographic environment describes the human population itself, such as its size, age distribution, and marriage, birth and death rates, which is why options D, A and C all belong to it."}},{"itemId":"7be2eb8d-443b-55a6-84df-567a8adc3d4b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cecf06e6-0001-598b-ae09-7660ae0f9c10","sourceKey":"bank:LAG-BUA111:PQ2-028","parentItemId":null,"revision":1,"payload":{"prompt":"The economic environment comprises the following factors except","options":["inflation","exchange rates","ethnic structure","level of employment"],"correctOption":2,"section":"Marketing Environment","explanation":"Ethnic structure describes the make-up of the population, so it is a demographic or socio-cultural factor rather than an economic one. Inflation, exchange rates and the level of employment (options A, B and D) all affect costs and buyers' purchasing power, which is what the economic environment is about."}},{"itemId":"3ba049ab-0f1b-5514-9364-3bf67e41449e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c91363b0-ac03-5c1e-9fae-6469e6b4598d","sourceKey":"bank:LAG-BUA111:PQ2-029","parentItemId":null,"revision":1,"payload":{"prompt":"The following are types of customer markets except ______.","options":["market segments","government and nonprofit markets","reseller markets","industrial markets"],"correctOption":0,"section":"Marketing Environment","explanation":"A market segment is a group of buyers that a firm creates by dividing a market, not one of the basic types of customer market. The five customer markets are consumer, industrial, reseller, government and nonprofit, and international markets, so options D, C and B are all genuine types."}},{"itemId":"b80d1c9b-4a23-55e1-b690-1c8105fdbad7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"029b45b2-3aed-5d35-8460-ae53af66a7b7","sourceKey":"bank:LAG-BUA111:PQ2-030","parentItemId":null,"revision":1,"payload":{"prompt":"______ occurs between organisations that engage in the same basic activity.","options":["Megamarketing","Demarketing","Intratype competition","Intertype competition"],"correctOption":2,"section":"Marketing Environment","explanation":"Intratype competition is rivalry between organisations doing the same basic business, for example two soft-drink bottlers or two banks competing for the same customers. Option D is competition between different types of organisations, such as finance houses competing with banks for savings. Options A and B are marketing strategies, not types of competition."}},{"itemId":"1ddf7898-bdf9-5609-9889-cb8f427e7de5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b47a8405-635a-5bca-9bb3-667577bdc4b0","sourceKey":"bank:LAG-BUA111:PQ2-031","parentItemId":null,"revision":1,"payload":{"prompt":"______ occurs between different types of organisations.","options":["Intratype competition","Macromarketing","Megamarketing","Intertype competition"],"correctOption":3,"section":"Marketing Environment","explanation":"Intertype competition takes place between different kinds of organisations that chase the same customers, such as finance houses competing with banks for savings or hospitals competing with health maintenance firms for patients. Option A is competition between organisations in the same line of business. Options C and B are not types of competition."}},{"itemId":"6e62ab30-c970-541a-b858-b388eb027803","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3498b414-ba7b-5040-95b7-99a9ba887158","sourceKey":"bank:LAG-BUA111:PQ2-032","parentItemId":null,"revision":1,"payload":{"prompt":"______ are other firms and individuals that provide the resources needed by a marketing company to produce its goods and services.","options":["Suppliers","Competitors","Intermediaries","Customers"],"correctOption":0,"section":"Marketing Environment","explanation":"Suppliers provide the inputs, such as raw materials, components and services, that a company needs in order to produce, so their prices and reliability directly affect its operations. Option D buys the firm's output rather than supplying its inputs. Option C helps move finished products to buyers, and option B competes for the same customers."}},{"itemId":"ff444dfe-b03f-5623-98dc-fb4565893bf4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"cfde3e66-f58f-5f2a-babe-bad3857db7f1","sourceKey":"bank:LAG-BUA111:PQ2-033","parentItemId":null,"revision":1,"payload":{"prompt":"When the purchasing department decides which resources to produce itself and which to buy from outside, this decision is known as the","options":["marketing mix decision","pricing decision","positioning decision","make-or-buy decision"],"correctOption":3,"section":"Marketing Environment","explanation":"Choosing between producing a resource in-house and buying it from outside suppliers is the make-or-buy decision. A firm can make everything, buy everything, or make the complicated parts and buy the simpler ones. Options A, B and C are marketing decisions about the offer to customers, not about sourcing inputs."}},{"itemId":"767f7326-fa41-5bd9-b059-27d636fc22a8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"312a8a89-cfdb-561b-b95c-527ade813eae","sourceKey":"bank:LAG-BUA111:PQ2-034","parentItemId":null,"revision":1,"payload":{"prompt":"______ are independent businesses that perform the activities necessary to move products from manufacturers to ultimate consumers.","options":["Suppliers","Intermediaries","Competitors","Customers"],"correctOption":1,"section":"Marketing Environment","explanation":"Marketing intermediaries, such as wholesalers, retailers, agents and distributors, are independent businesses in the distribution channel that move products from producers to final consumers. Option A provides inputs to the manufacturer rather than moving finished goods onward. Option D is the end buyer, and option C serves the same market."}},{"itemId":"bd9685cd-220e-537b-8fd0-c650dc4e53ed","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b21a39c9-a723-5e51-a791-2418275c199c","sourceKey":"bank:LAG-BUA111:PQ2-035","parentItemId":null,"revision":1,"payload":{"prompt":"Middlemen create place utility by ______ where customers are located.","options":["advertising products","selling products","buying products","stocking products"],"correctOption":3,"section":"Marketing Environment","explanation":"Place utility means having the product where the customer is, and middlemen create it by holding stock in shops and warehouses close to buyers. Option A makes customers aware of a product but does not put it within their reach. Options C and B describe the ownership transaction, which is linked to possession utility rather than place utility."}},{"itemId":"d6d4712d-2d28-584c-ac62-2472a0391a95","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"27d12bdc-68f7-56d8-aa36-23e05d269f11","sourceKey":"bank:LAG-BUA111:PQ2-036","parentItemId":null,"revision":1,"payload":{"prompt":"Middlemen create ______ when they open for long hours so that customers can buy products at their convenience.","options":["possession utility","quantity utility","time utility","place utility"],"correctOption":2,"section":"Marketing Environment","explanation":"Time utility means the product is available when the customer wants it, which is what long opening hours provide. Option D is about where the product is available, and option B is about offering affordable quantities. Option A comes from transferring ownership to the customer."}},{"itemId":"9cd0d7df-9585-5a00-bc70-3db95e02254c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3534f9a7-3043-53e8-b775-b029fe5a5b2d","sourceKey":"bank:LAG-BUA111:PQ2-037","parentItemId":null,"revision":1,"payload":{"prompt":"Intermediaries create ______ by making products available in quantities that customers can afford to buy.","options":["assortment utility","time utility","place utility","quantity utility"],"correctOption":3,"section":"Marketing Environment","explanation":"Quantity utility comes from breaking bulk, so that customers can buy small amounts they can afford, such as a single sachet instead of a whole carton. Option B concerns when the product is available and option C concerns where. Option A comes from bringing many different products together in one place."}},{"itemId":"ce5c96e8-e111-5b17-9a33-126303caf926","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"16e5d551-66fc-5d67-a3c2-657aceafcb75","sourceKey":"bank:LAG-BUA111:PQ2-038","parentItemId":null,"revision":1,"payload":{"prompt":"Intermediaries create ______ by gathering different products at one point so that customers may buy them on the same shopping trip.","options":["place utility","assortment utility","quantity utility","possession utility"],"correctOption":1,"section":"Marketing Environment","explanation":"Assortment utility is the convenience of finding a wide range of different products in one place, so the customer can buy them all on one shopping trip, as in a supermarket. Option C is about offering affordable amounts of a product, and option A is about locating products near customers. Option D comes from the transfer of ownership."}},{"itemId":"276cb69c-bce4-524b-bd09-51f8adf4b235","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"54dd29c0-10ca-5fe9-bf85-0cf5a24ff82f","sourceKey":"bank:LAG-BUA111:PQ2-039","parentItemId":null,"revision":1,"payload":{"prompt":"Middlemen create ______ by transferring products to customers through successful transactions with them.","options":["possession utility","assortment utility","place utility","time utility"],"correctOption":0,"section":"Marketing Environment","explanation":"Possession utility is created when ownership of the product actually passes to the customer through a completed sale. Options C and D come from having the product in the right location and at the right time. Option B comes from gathering many products in one place."}},{"itemId":"86bba19a-259d-569d-b040-2a7641ae3c3b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"60cb70e6-3d00-5c84-af8e-aee6f13d3c48","sourceKey":"bank:LAG-BUA111:PQ2-040","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a term that describes the short period of time in which a company must adjust its strategic marketing approach to new market realities, or quit the market if it fails to adjust.","options":["Synchromarketing","Megamarketing","Strategic window","Demarketing"],"correctOption":2,"section":"Marketing Environment","explanation":"A strategic window opens when the market environment changes, for example through new primary demand, new technology, market redefinition by competitors or changes in distribution channels. The firm has only a short time to adjust its strategy or leave the market. Option B uses power and public relations to enter blocked markets, option A smooths out uneven demand, and option D reduces demand."}},{"itemId":"4c66fc48-e796-507b-9a90-17179891b9d8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f79afcb7-7538-5de8-adfc-fa21636694e9","sourceKey":"bank:LAG-BUA111:PQ2-041","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a term that describes the use of power and public relations by companies to penetrate blocked or protected markets.","options":["Megamarketing","Macromarketing","Synchromarketing","Demarketing"],"correctOption":0,"section":"Marketing Environment","explanation":"Megamarketing treats the environment as something a firm can partly influence: it uses power, public relations, lobbying and even lawsuits to open up markets that are blocked or protected. Option C smooths out irregular demand, and option D reduces demand. Option B is the society-wide study of marketing systems."}},{"itemId":"eae68989-8cf6-5e22-9e9a-d76939456c72","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"38aa6272-1d95-5a1f-82d6-86e03148aeae","sourceKey":"bank:LAG-BUA111:PQ2-042","parentItemId":null,"revision":1,"payload":{"prompt":"______ comprise purchases that are important to the consumer.","options":["Low-involvement purchases","Routine response purchases","Habitual purchases","High-involvement purchases"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Involvement is how important and interesting a purchase is to the buyer, so purchases that matter a lot to the consumer are high-involvement purchases, option D. Options A, B and C all describe cheap, frequent buys that the consumer does not consider important and makes with little thought."}},{"itemId":"f9082193-c958-56ce-acbf-f433df63eb5d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6a9d2c1b-07c3-5438-a426-b370c0fe6748","sourceKey":"bank:LAG-BUA111:PQ2-043","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a high-involvement purchase that requires a great deal of thought.","options":["Habit","Demarketing","Complex decision making","Routine response behaviour"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Complex (extensive) decision making happens when a product is expensive, risky or unfamiliar, so the buyer searches widely and thinks carefully before buying, which is option C. Options A and D are low-involvement patterns where buying is almost automatic, and option B is a marketing strategy for reducing demand, not a type of purchase."}},{"itemId":"bf2b3f41-a166-5ed0-9923-39698499f2c5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4bc310e0-b83f-5c5c-8c63-5c6cc76b8c52","sourceKey":"bank:LAG-BUA111:PQ2-044","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the first step in the complex decision-making process.","options":["Information search and brand evaluation","Product choice and purchase","Problem recognition","Satisfaction"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Every complex buying decision starts with problem recognition, when the consumer notices a gap between the situation they want and the one they are in, which is option C. Option A comes next, once the need is felt, while options B and D come at the end of the process."}},{"itemId":"91bd4c25-e162-596c-9f1f-fa537d97894f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c955903e-edfb-5e32-b21f-779105f91e49","sourceKey":"bank:LAG-BUA111:PQ2-045","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the last step in the complex decision-making process.","options":["Problem recognition","Post-purchase evaluation (satisfaction or dissatisfaction)","Product choice and purchase","Information search and brand evaluation"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"After buying, the consumer judges whether the product met expectations, ending up satisfied or dissatisfied, and this post-purchase evaluation is the final step, option B. Option A is the first step, option D is an early step, and option C comes just before the evaluation, not after it."}},{"itemId":"529d2935-bf46-5fc6-8385-d89e7a544f13","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a4f6bdef-1f36-5799-ba1f-58259e3046b2","sourceKey":"bank:LAG-BUA111:PQ2-045-b","parentItemId":null,"revision":1,"payload":{"prompt":"Doubt felt by a buyer, after a purchase, about whether the right choice was made is known as:","options":["Selective exposure","Problem recognition","Cognitive dissonance","Evoked set"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Cognitive dissonance is the uneasy feeling a buyer may have after a purchase that another option might have been better, which is option C; firms reduce it with warranties and after-sales contact. Option A is about which information a person notices, option B is the first step of the buying process, and option D is the set of alternatives found during information search."}},{"itemId":"a6ece278-5121-56cc-91e9-255e71f43725","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"205377f1-2e9e-5eb7-90ce-05aba848ba19","sourceKey":"bank:LAG-BUA111:PQ2-046","parentItemId":null,"revision":1,"payload":{"prompt":"______ are made by consumers when they do not consider the products important or risky enough to give them a great deal of thought and deliberation.","options":["High-involvement purchases","Complex decisions","Extensive problem-solving decisions","Low-involvement purchases"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"When a product is cheap, familiar and low in risk, the consumer buys it with little search or thought, which is a low-involvement purchase, option D. Options A, B and C all describe the opposite situation, where the product is important or risky and the buyer deliberates carefully."}},{"itemId":"17e47353-0f0a-5469-b96b-06d394f72172","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"74f95ce5-6614-5359-92a9-dbff363e8d10","sourceKey":"bank:LAG-BUA111:PQ2-047","parentItemId":null,"revision":1,"payload":{"prompt":"Consumers who repeatedly buy the same brand mainly because it saves effort, and not because they are strongly committed to it, are buying out of:","options":["Brand loyalty","Complex decision making","Inertia","Variety seeking"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Inertia is repeat buying of the same brand simply to avoid the effort of deciding again, with little real attachment to the brand, so option C is right. Option A also involves repeat purchase, but it comes from a strong, committed preference, which the stem rules out. Option B involves careful search, and option D means deliberately switching brands."}},{"itemId":"a6526628-60ed-5244-83b8-325692fdf4c3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ed9a5470-c4a0-586b-974a-9dcdd997fff4","sourceKey":"bank:LAG-BUA111:PQ2-048","parentItemId":null,"revision":1,"payload":{"prompt":"______ consist of the consumer's perception, learning and attitudes.","options":["Personal influences","Psychological influences","Environmental influences","Economic influences"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Perception, learning and attitudes are processes that happen inside the consumer's mind, so they are psychological influences, option B. Option A covers individual characteristics such as age and life-cycle stage, while options C and D refer to forces outside the person."}},{"itemId":"1f8453e4-5589-5e78-83d4-8c96cf008ca2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e19353ab-e727-5feb-a310-99972c84f3d2","sourceKey":"bank:LAG-BUA111:PQ2-049","parentItemId":null,"revision":1,"payload":{"prompt":"______ comprise the personal characteristics of consumers.","options":["Environmental influences","Personal influences","Economic influences","Psychological influences"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Personal influences are the characteristics unique to each consumer, such as age, sex and stage in the family life cycle, which is option B. Option D refers to mental processes like perception and attitudes, while options A and C are forces outside the individual."}},{"itemId":"40f5e5eb-3c0c-5fbd-85cf-ee68239e5675","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c3db743b-66d6-50ca-8101-e01031b1325d","sourceKey":"bank:LAG-BUA111:PQ2-050","parentItemId":null,"revision":1,"payload":{"prompt":"Age, life-cycle stage, occupation and economic situation are ______ on consumer behaviour.","options":["personal influences","environmental influences","psychological influences","social influences"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Age, life-cycle stage, occupation and economic situation describe the individual buyer, so they are personal influences, option A. Option C covers mental processes such as motives, perception and attitudes, option D covers groups such as family and reference groups, and option B refers to forces in the wider marketing environment."}},{"itemId":"2c20295e-8dea-5b5d-adba-5bf33145981d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6ece2187-492f-5d8a-a21f-7aea0b9fb119","sourceKey":"bank:LAG-BUA111:PQ2-051","parentItemId":null,"revision":1,"payload":{"prompt":"______ on consumer behaviour are culture, subculture and reference groups.","options":["Social influences","Personal influences","Psychological influences","Economic influences"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Culture, subculture and reference groups all come from the people and society around the consumer, so they are social influences, option A. Option B refers to the buyer's own characteristics such as age, and option C to inner processes such as perception and attitudes. Option D is about income and prices rather than group influence."}},{"itemId":"01d17a31-e157-57e5-8836-509c4bb93844","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"921eedba-c00a-53b1-a8c9-ba35218d9b23","sourceKey":"bank:LAG-BUA111:PQ2-052","parentItemId":null,"revision":1,"payload":{"prompt":"A consumer's activities, interests and opinions (AIO) describe his or her ______, a psychographic variable used in market segmentation.","options":["age","lifestyle","usage rate","geographic location"],"correctOption":1,"section":"Market Segmentation","explanation":"Lifestyle is the pattern of how a person lives, measured by his or her activities, interests and opinions, and it is an important psychographic segmentation variable. Option A is a demographic variable, option D is a geographic one, and option C is a behavioural variable based on how much of a product a person uses."}},{"itemId":"3d553866-e404-5059-bcc9-3f31cb4ce2db","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"277b2125-b79a-5f65-9bf5-93f870ebd7e7","sourceKey":"bank:LAG-BUA111:PQ2-053","parentItemId":null,"revision":1,"payload":{"prompt":"Self-concept is also known as ______","options":["lifestyle","social class","personality","self-image"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Self-concept is the way a person sees himself or herself, which is why it is also called self-image, option D. Option B is the group a person belongs to in society, option A is the way a person lives, and option C is the set of inner traits that make a person unique."}},{"itemId":"004d42ee-8e8c-5b02-9221-af247c57651b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b456cac8-1af6-5ab5-9d5b-2056935125b8","sourceKey":"bank:LAG-BUA111:PQ2-054","parentItemId":null,"revision":1,"payload":{"prompt":"Dividing a market into groups based on variables such as age, sex, religion and income is called ______ segmentation.","options":["behavioural","psychographic","geographic","demographic"],"correctOption":3,"section":"Market Segmentation","explanation":"Demographic segmentation groups people by population characteristics such as age, sex, religion, income and occupation, and it is the most common form of segmentation. Option B uses psychological traits such as lifestyle, values and personality. Option C uses location, and option A uses how people buy or use the product."}},{"itemId":"53d2c8eb-a282-51be-8c11-cb130ea3b9c5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d381a623-d9cc-5bb7-a011-07c54df2460f","sourceKey":"bank:LAG-BUA111:PQ2-055","parentItemId":null,"revision":1,"payload":{"prompt":"Lifestyle, personality, attitudes and values are variables used in ______ segmentation.","options":["behavioural","geographic","psychographic","demographic"],"correctOption":2,"section":"Market Segmentation","explanation":"Psychographic segmentation groups customers by their psychological traits: how they live, what they value, their attitudes and their personality. Option D uses measurable population facts such as age and income, and option B uses location. Option A groups buyers by actions such as usage rate or brand loyalty rather than by inner traits."}},{"itemId":"2a88f41d-f6a0-51e1-a804-e8e99fc9088b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"590d3b5f-06e3-52c6-916c-755505b79dd5","sourceKey":"bank:LAG-BUA111:PQ2-056","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ is the most important primary reference group for consumers.","options":["family","society","peer group","religious group"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The family is the closest and most frequent group a person deals with, so it shapes values, attitudes and buying habits more than any other primary reference group, which is option A. Option C is also a primary group but usually has less lasting influence, while options B and D are wider, less personal groups."}},{"itemId":"396fe2fa-161f-5c11-aa0c-dea496c1db32","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"96fe8f36-5248-5df3-84a7-19856836a4f1","sourceKey":"bank:LAG-BUA111:PQ2-057","parentItemId":null,"revision":1,"payload":{"prompt":"In the family decision-making process, the ______ exerts personal influence on the decision.","options":["decider","initiator","user","influencer"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"The influencer is the family member who tries to sway the choice through personal opinion and persuasion, which is option D. Option A makes the final choice, option B first recognises the need, and option C is the person who will use the product."}},{"itemId":"8b6eb8c0-82b1-572e-856d-65e5538fb590","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"945210e3-02d1-5cfa-a6ad-fdc36a1e5ab7","sourceKey":"bank:LAG-BUA111:PQ2-058","parentItemId":null,"revision":1,"payload":{"prompt":"In the family decision-making process, the ______ is the one who recognises the problem and begins the decision-making process.","options":["influencer","user","initiator","decider"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"The initiator is the family member who first notices the need and starts the buying process, which is option C. Option A tries to sway the choice once it is under way, option D makes the final choice, and option B is simply the person who will use the product."}},{"itemId":"89cbef8e-4e2e-5dd4-9900-2bced08ee891","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5b752ad1-07bb-5e12-b2cb-b9db87a85183","sourceKey":"bank:LAG-BUA111:PQ2-059","parentItemId":null,"revision":1,"payload":{"prompt":"In the family decision-making process, the ______ makes the final decision.","options":["purchaser","user","initiator","decision maker"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"The decision maker has the final say on whether to buy and which option to choose, which is option D. Option A carries out the actual purchase, which may be a different person, option B uses the product, and option C only starts the process."}},{"itemId":"6fdd91cb-5dc8-5094-bb66-2323ad4802f4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e22d04fa-6562-5bae-b7d5-258afca78015","sourceKey":"bank:LAG-BUA111:PQ2-060","parentItemId":null,"revision":1,"payload":{"prompt":"In the family decision-making process, the ______ seeks information about available products and their characteristics.","options":["information gatherer","initiator","influencer","user"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"The information gatherer is the family member who looks for details on the available products and their features, which is option A. Option B starts the process by recognising the need, option C tries to sway the choice with personal opinion, and option D is the person who will use the product."}},{"itemId":"81fcc73c-59a3-52b2-aaf1-dcfe825e20c8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"584dd6d4-52e2-52bd-9f36-63fa66d14479","sourceKey":"bank:LAG-BUA111:PQ2-061","parentItemId":null,"revision":1,"payload":{"prompt":"A reference group exerts ______ on consumers because it is a source of believable information about brands and companies.","options":["informational influence","comparative influence","normative influence","coercive influence"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"When people treat a group as a trustworthy place to get facts about brands and companies, the group is exerting informational influence, option A. Option C is pressure to follow the group's norms, option B is the use of the group as a yardstick for one's own beliefs and behaviour, and option D is not a type of reference-group influence."}},{"itemId":"af08e277-3183-5feb-8a0b-0f22e60bac7a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"55af5206-a5a5-57de-b7bf-dab802a224b9","sourceKey":"bank:LAG-BUA111:PQ2-062","parentItemId":null,"revision":1,"payload":{"prompt":"A reference group can exert ______ on consumers because it gives them something to compare their beliefs, attitudes and behaviour against.","options":["informational influence","normative influence","comparative influence","coercive influence"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Comparative influence occurs when consumers use a group as a standard against which they compare their own beliefs, attitudes and behaviour, which is option C. Option A is the group acting as a provider of believable information, and option B is pressure to conform to the group's norms. Option D is not a type of reference-group influence."}},{"itemId":"d965313c-d760-5c0d-84d0-a707736612bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"5d01ed5c-1e2a-5788-b7f5-5e562c3de487","sourceKey":"bank:LAG-BUA111:PQ2-063","parentItemId":null,"revision":1,"payload":{"prompt":"A reference group can exert ______ on consumers because it persuades members to conform to its norms.","options":["normative influence","informational influence","comparative influence","coercive influence"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Normative influence is the pressure a group puts on its members to follow its norms, for example to wear or buy what the group approves of, which is option A. Option B is the group serving as a provider of believable information, and option C is the group serving as a yardstick for comparison. Option D is not a type of reference-group influence."}},{"itemId":"3e26db19-eb0a-528c-8c01-86aaa0badd6e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0b4e3b7b-863d-5a72-8879-9a915c8c7880","sourceKey":"bank:LAG-BUA111:PQ2-064","parentItemId":null,"revision":1,"payload":{"prompt":"Marketers who sell to business organisations rather than to individual consumers are referred to as","options":["International marketers","Business-to-consumer marketers","Gate crashers","Business-to-business marketers"],"correctOption":3,"section":"Marketing Environment","explanation":"Business-to-business (B2B) marketers sell goods and services to other organisations, such as manufacturers, resellers and government bodies, instead of to households. Option B is the opposite case, selling to individuals for personal use. Option A describes selling to buyers abroad, which can involve consumers or organisations."}},{"itemId":"66e78fe7-4154-53f2-a6ca-a6255db546a4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b9b0e60d-acd8-52c5-b028-85bfb6c8d5e0","sourceKey":"bank:LAG-BUA111:PQ2-065","parentItemId":null,"revision":1,"payload":{"prompt":"The following are types of organisational buyers EXCEPT:","options":["Institutional buyers","Individual buyers","Industrial buyers","Government agencies"],"correctOption":1,"section":"Marketing Environment","explanation":"Individual buyers purchase for personal or household consumption, so they make up the consumer market, not the organisational market. Industrial buyers (option C), government agencies (option D) and institutional buyers (option A) all buy on behalf of organisations."}},{"itemId":"6499960d-eb78-5a89-aa78-0752730d21e0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d6e3f452-62cd-5dbf-8fe6-d5527c610c73","sourceKey":"bank:LAG-BUA111:PQ2-066","parentItemId":null,"revision":1,"payload":{"prompt":"______ procure products or services for use in manufacturing other products or for operating their own businesses.","options":["Institutional buyers","Resellers","Government agencies","Industrial buyers"],"correctOption":3,"section":"Marketing Environment","explanation":"Industrial buyers purchase inputs such as raw materials, components and equipment to produce other goods and services or to run their businesses. Resellers (option B) buy to resell at a profit, not to use in production. Institutional buyers (option A) buy for service organisations such as hospitals and schools."}},{"itemId":"e1855b1f-35f8-5225-a30c-3be12955338f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1f25f5b7-2bfd-54cc-9327-5b1d918829bc","sourceKey":"bank:LAG-BUA111:PQ2-067","parentItemId":null,"revision":1,"payload":{"prompt":"______ buy for organisations that render services, such as museums and hospitals.","options":["Government agencies","Resellers","Institutional buyers","Industrial buyers"],"correctOption":2,"section":"Marketing Environment","explanation":"Institutional buyers purchase goods and services for service-providing organisations like hospitals, schools and museums, which often serve people in their care. Industrial buyers (option D) buy inputs for producing other products. Government agencies (option A) buy to perform public functions of the state."}},{"itemId":"6f709742-ac89-5369-9128-b038cc319634","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9ac2a0be-2e81-55b1-853b-8afe5ae84e94","sourceKey":"bank:LAG-BUA111:PQ2-068","parentItemId":null,"revision":1,"payload":{"prompt":"______ are Federal, State and local government units that procure products and services in order to perform their social functions.","options":["Institutional buyers","Government agencies","Industrial buyers","Resellers"],"correctOption":1,"section":"Marketing Environment","explanation":"Government agencies at federal, state and local levels buy goods and services so they can provide public services such as roads, security and education. Institutional buyers (option A) buy for service organisations like hospitals and museums. Resellers (option D) buy in order to resell for profit."}},{"itemId":"d13e61bb-89dd-5519-8f08-5e2f02b717df","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d505efbd-9481-5901-8df2-dd84bbebd473","sourceKey":"bank:LAG-BUA111:PQ2-069","parentItemId":null,"revision":1,"payload":{"prompt":"______ are intermediaries that buy products in order to resell them.","options":["Government agencies","Institutional buyers","Industrial buyers","Resellers"],"correctOption":3,"section":"Marketing Environment","explanation":"Resellers, such as wholesalers and retailers, buy goods and services in order to resell them at a profit. Industrial buyers (option C) use what they buy to make other products. Government agencies (option A) buy to provide public services, not to resell."}},{"itemId":"f4bff788-3de0-5f9d-9264-7745d9619a68","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1afb7b07-82e8-5d83-8795-7f2b544ef198","sourceKey":"bank:LAG-BUA111:PQ2-070","parentItemId":null,"revision":1,"payload":{"prompt":"In comparing organisational markets with consumer markets, ______ are normally concentrated in certain places, while ______ comprise many thousands of target consumers.","options":["consumer markets; organisational markets","international markets; resellers","organisational markets; consumer markets","resellers; international markets"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Organisational buyers are fewer and are often clustered in particular industrial areas, while consumer markets are made up of very many individual buyers spread widely, so option C is correct. Option A reverses the two, and options B and D mix in market types that the comparison is not about."}},{"itemId":"5179e2cc-5c1e-5055-88ac-cf17826eb133","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"632d5dae-ea96-58c3-898c-713f2ed9b141","sourceKey":"bank:LAG-BUA111:PQ2-071","parentItemId":null,"revision":1,"payload":{"prompt":"______ tend to be less technical and complex than ______.","options":["Industrial products; consumer products","Staples; impulse convenience goods","Staples; emergency convenience goods","Consumer products; industrial products"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Industrial products such as machinery and raw materials are often technical and bought to precise specifications, so consumer products are generally the simpler of the two, option D. Option A reverses the comparison, while options B and C compare two kinds of convenience goods, which are both simple consumer products."}},{"itemId":"ef18e785-da78-5c75-a00a-eadb20ee7247","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c40fc340-b5d3-596f-82be-cbd9501b6780","sourceKey":"bank:LAG-BUA111:PQ2-072","parentItemId":null,"revision":1,"payload":{"prompt":"The decision-making unit of a buying organisation is known as the ______","options":["selling centre","purchasing centre","buying centre","decision-making centre"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"The buying centre is the name given to the decision-making unit of a buying organisation: all the people who take part in a purchase decision, which is option C. Option A relates to the seller's side, and options B and D sound plausible but are not the accepted term."}},{"itemId":"1455709c-1358-5179-a564-8a953437b9e2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"24f782c8-6287-57f4-a270-692d849d5c14","sourceKey":"bank:LAG-BUA111:PQ2-073","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ consists of those individuals and groups who participate in the purchasing decision-making process of an organisation.","options":["selling centre","buying centre","purchasing centre","decision-making centre"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"The buying centre is made up of everyone who takes part in an organisation's buying decision, such as users, influencers, buyers, deciders and gatekeepers, which is option B. Option A belongs to the seller's side, and options C and D sound plausible but are not the accepted term."}},{"itemId":"bdbc44bd-27a6-5431-91ba-c0a65b97759c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"868e9ef7-d19d-5c57-8c30-d45f20fb4aed","sourceKey":"bank:LAG-BUA111:PQ2-074","parentItemId":null,"revision":1,"payload":{"prompt":"______ are members of a buying centre who will use the product or service.","options":["Influencers","Buyers","Gatekeepers","Users"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Users are the members of the buying centre who will actually work with the product or service, and they often start the purchase, which is option D. Option A shapes the decision with information, option B handles the formal purchase, and option C controls the flow of information."}},{"itemId":"a1d7fe20-8d8b-5073-9283-1a96875e7afb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8bf25627-9351-5709-ae56-dc57e5ade40a","sourceKey":"bank:LAG-BUA111:PQ2-075","parentItemId":null,"revision":1,"payload":{"prompt":"______ are members of a buying centre who provide information that will influence the buying decision.","options":["Buyers","Influencers","Users","Approvers"],"correctOption":1,"section":"Consumer and Organisational Buying Behaviour","explanation":"Influencers, often technical staff, help define specifications and supply information for judging alternatives, which shapes the buying decision, so option B is correct. Option A formally places the order, option C uses the product, and option D authorises what deciders or buyers propose."}},{"itemId":"d740a416-cd4d-5dc3-a1cd-7c57d2dff291","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9ef09cfa-8b57-5ee6-9e82-cd4c0ca052f3","sourceKey":"bank:LAG-BUA111:PQ2-076","parentItemId":null,"revision":1,"payload":{"prompt":"______ are members of a buying centre who make the final decision.","options":["Influencers","Approvers","Buyers","Deciders"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Deciders are the members of the buying centre with the power to choose the product and supplier, which is option D. Option C formally places the order, which is not the same as choosing, option B authorises what others propose, and option A only shapes the decision."}},{"itemId":"4804266d-2c2a-5b49-a01f-241cfb9013bc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9b6d535b-d663-5223-8946-314851636b66","sourceKey":"bank:LAG-BUA111:PQ2-077","parentItemId":null,"revision":1,"payload":{"prompt":"______ are members of a buying centre who authorise the actions that deciders or buyers propose.","options":["Approvers","Gatekeepers","Buyers","Users"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Approvers are the people, often senior managers, who give official authorisation to the actions that deciders or buyers propose, which is option A. Option B controls information flow, option C carries out the purchase, and option D uses the product."}},{"itemId":"6337fbb0-fb52-5a96-a16c-3b109eb8612a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"36bf6f98-e3a4-59ce-bf4d-d8b7f63541dd","sourceKey":"bank:LAG-BUA111:PQ2-078","parentItemId":null,"revision":1,"payload":{"prompt":"______ are members of a buying centre who control the flow of information into the organisation.","options":["Gatekeepers","Approvers","Users","Deciders"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"Gatekeepers, such as purchasing agents or receptionists, decide what information and which salespeople reach the other members of the buying centre, which is option A. Option B authorises proposed actions, option C uses the product, and option D makes the final choice."}},{"itemId":"c76a63ce-2479-55be-ade1-90dcb3761875","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6075098d-12f1-5d3c-b605-3ce78260aa4b","sourceKey":"bank:LAG-BUA111:PQ2-079","parentItemId":null,"revision":1,"payload":{"prompt":"Situations that can lead to organisational buying decisions can be divided into ______","options":["ten classes","five classes","three classes","two classes"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Organisational buying situations are grouped into three classes: the straight rebuy, the modified rebuy and the new task, which is option C. Options A, B and D give the wrong number of buying situations."}},{"itemId":"ada6aec9-9ac8-5b06-a2bf-0156161a60dc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"640a9eeb-b213-505a-b23b-0fa686bc1681","sourceKey":"bank:LAG-BUA111:PQ2-079-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the organisational buying situations (buy classes)?","options":["Straight rebuy","Modified rebuy","Limited decision making","New task"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"Limited decision making describes how an individual consumer buys an unfamiliar brand in a familiar product category, so it is not an organisational buy class, which makes option C the odd one. Options A, B and D are the three organisational buying situations, running from routine reorders to completely new purchases."}},{"itemId":"af645c1f-cd5e-5f16-9dae-3d7a605c7851","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"86c34acf-129c-5268-b515-8bbe388301e5","sourceKey":"bank:LAG-BUA111:PQ2-080","parentItemId":null,"revision":1,"payload":{"prompt":"The organisational buying situations are also known as ______","options":["selling classes","purchasing classes","buy classes","special classes"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"The three organisational buying situations, straight rebuy, modified rebuy and new task, are also called buy classes, option C. Options A, B and D sound plausible but are not the accepted term."}},{"itemId":"ffe2cfdb-58a8-58b9-b23a-5c2beadbe834","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"1978fc07-3ae8-5249-8d1b-fac12eee250b","sourceKey":"bank:LAG-BUA111:PQ2-081","parentItemId":null,"revision":1,"payload":{"prompt":"______ is a buying situation that requires the buyer to undertake a new purchasing task.","options":["Straight rebuy","Modified rebuy","New task","Impulse purchase"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"In a new task situation, the organisation is buying something for the first time, so it must gather a lot of information and weigh many alternatives, which is option C. Option A is a routine reorder, option B is a repeat purchase with some changes, and option D is an unplanned consumer purchase."}},{"itemId":"418f07b1-659e-5f83-8bc9-8c2145c1f27e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"13aafe64-bcae-50fd-8d28-c2f0624dff24","sourceKey":"bank:LAG-BUA111:PQ2-082","parentItemId":null,"revision":1,"payload":{"prompt":"In a ______ situation, the purchasing company has acquired extensive experience, and the purchasing process is quite simple and routine in nature.","options":["straight rebuy","new task","modified rebuy","complex buying"],"correctOption":0,"section":"Consumer and Organisational Buying Behaviour","explanation":"A straight rebuy is a routine reorder of something the company has bought many times, often from an approved supplier list, which is option A. Option B is a first-time purchase needing much research, option C involves changing specifications, prices or suppliers, and option D describes a careful, high-involvement purchase."}},{"itemId":"88afc075-37c6-5111-ad0e-b0dbccd500ae","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e476f094-c3d2-59a0-bf43-94bdbca894b9","sourceKey":"bank:LAG-BUA111:PQ2-083","parentItemId":null,"revision":1,"payload":{"prompt":"The ______ situation involves a recurring purchase that is less routine in nature.","options":["new task","straight rebuy","routine reorder","modified rebuy"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"In a modified rebuy, the organisation buys something it has bought before but wants to change the product specifications, prices, terms or suppliers, so the purchase recurs but is less routine, which is option D. Options B and C describe purchases that are fully routine, and option A is a first-time purchase rather than a recurring one."}},{"itemId":"ba24026f-7fcf-5874-af38-22f762c73821","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"04001169-3ce0-5a79-9b98-7b0e0b90264d","sourceKey":"bank:LAG-BUA111:PQ2-084","parentItemId":null,"revision":1,"payload":{"prompt":"The organisational buying decision process consists of stages known as ______","options":["selling phases","organisational phases","buy phases","buying decision phases"],"correctOption":2,"section":"Consumer and Organisational Buying Behaviour","explanation":"The stages of the organisational buying process, from problem recognition through to performance review, are called buy phases, option C. Options A, B and D sound plausible but are not the accepted term."}},{"itemId":"f00b7ccc-bc97-5700-8a9b-0186cb7f5979","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"edbdf030-56bb-5f32-8959-08299090f408","sourceKey":"bank:LAG-BUA111:PQ2-085","parentItemId":null,"revision":1,"payload":{"prompt":"In the organisational buying decision process, the problem recognition stage is triggered when:","options":["The supplier delivers the order and sends an invoice","The firm reviews how well the chosen supplier has performed","The purchasing department places a routine order","Someone in the company recognises an unmet need that can be met by acquiring a good or service"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Organisational buying begins when someone in the firm recognises a problem or unmet need that could be solved by buying a good or service, which is option D. Option A happens near the end of the process, option B is the final performance review stage, and option C describes order placement, which comes after a supplier has been chosen."}},{"itemId":"3687e926-42b4-5b3f-a5a5-ad7d32321fd5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"81782817-f3a3-5c0d-a311-7927f6be6904","sourceKey":"bank:LAG-BUA111:PQ2-086","parentItemId":null,"revision":1,"payload":{"prompt":"The following are major influences on organisational buying behaviour except ______","options":["environmental factors","the organisation itself","the buying centre","market segmentation"],"correctOption":3,"section":"Consumer and Organisational Buying Behaviour","explanation":"Market segmentation is a strategy a seller uses to divide a market into groups, not a force acting on an organisational buyer, so option D is the exception. Options A, B and C are all major influences: the economic and other environmental conditions, the organisation's own objectives and policies, and the people in the buying centre."}},{"itemId":"b6ba50d7-b2a5-5197-aaf2-30b4bf0f40e9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"867eae2e-3745-513f-b3d5-03605f087ee9","sourceKey":"bank:LAG-BUA111:PQ2-087","parentItemId":null,"revision":1,"payload":{"prompt":"Market segmentation strategy is the opposite of","options":["mass marketing","synchromarketing","telemarketing","megamarketing"],"correctOption":0,"section":"Market Segmentation","explanation":"Mass marketing treats the whole market as one and offers a single product and marketing mix to everyone, while segmentation divides the market into groups and tailors a mix to each. Option C is selling by telephone, a promotion method rather than a market coverage strategy. Option B deals with smoothing irregular demand over time."}},{"itemId":"bfbf429e-8912-5500-bd23-4c4d4e305bc3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"453d0053-9c7f-51b5-a580-79ae5f64afd5","sourceKey":"bank:LAG-BUA111:PQ2-088","parentItemId":null,"revision":1,"payload":{"prompt":"Segmentation focuses on the ______, whereas product differentiation focuses on ______.","options":["prices; product","product differences; market","product differences; price","market; product differences"],"correctOption":3,"section":"Market Segmentation","explanation":"Segmentation starts from the market: it groups buyers with similar needs and adjusts the offer to fit each group. Differentiation starts from the product: it stresses how the firm's product differs from rivals' to win buyers. Option B simply reverses the two ideas, and the price-based options do not describe either strategy."}},{"itemId":"6aff6c88-cfd8-5450-9aa5-5edaba734c77","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f362e5c5-4bb0-5821-aa05-813c8b1ef249","sourceKey":"bank:LAG-BUA111:PQ2-089","parentItemId":null,"revision":1,"payload":{"prompt":"When consumer preferences are so scattered that, in the extreme, each consumer could be treated as a separate market segment, the market shows","options":["diffused preference patterns","concentrated preference patterns","homogeneous preference patterns","clustered preference patterns"],"correctOption":0,"section":"Market Segmentation","explanation":"Diffused preferences are spread widely with no natural grouping, so at the extreme every buyer differs and could be a segment of one. Option D describes buyers falling into distinct groups that form natural segments. Option C means everyone wants roughly the same thing, so the whole market is one segment."}},{"itemId":"b6b339f2-0aa5-5773-b41b-3050d8542d59","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0f19d92e-f5ff-5ef7-bd6a-e1a8fc71e564","sourceKey":"bank:LAG-BUA111:PQ2-090","parentItemId":null,"revision":1,"payload":{"prompt":"Which preference pattern exists when groups of consumers with similar preferences form distinct market segments?","options":["Homogeneous preference patterns","Diffused preference patterns","Concentrated preference patterns","Clustered preference patterns"],"correctOption":3,"section":"Market Segmentation","explanation":"Clustered preferences occur when buyers bunch into distinct groups, each with its own shared preference, so each cluster becomes a natural segment. Option A means all consumers want roughly the same thing, giving one segment. Option B means preferences are scattered with no clear groups."}},{"itemId":"2ace8278-c2b3-535d-8a00-0db6a09d1ebe","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"29cd0232-3574-5452-ae88-ca545c9986a5","sourceKey":"bank:LAG-BUA111:PQ2-091","parentItemId":null,"revision":1,"payload":{"prompt":"Which preference pattern allows all consumers to be treated as a single market segment?","options":["Homogeneous preference patterns","Clustered preference patterns","Concentrated preference patterns","Diffused preference patterns"],"correctOption":0,"section":"Market Segmentation","explanation":"Homogeneous preferences mean consumers want roughly the same thing, so the whole market can be served as one segment with one offer. Option B gives several natural groups, each a separate segment. Option D means preferences are widely scattered."}},{"itemId":"356c3d97-ab11-5bb6-a488-f1ccb03a603f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e34f7c2c-fd33-5bc2-bea5-7c0a89729c8a","sourceKey":"bank:LAG-BUA111:PQ2-092","parentItemId":null,"revision":1,"payload":{"prompt":"In which of these markets are consumer preferences most likely to be homogeneous?","options":["Fashion clothing","Table salt","Cars","Perfume"],"correctOption":1,"section":"Market Segmentation","explanation":"Table salt is a basic product that most buyers want in much the same form, so preferences are fairly uniform or homogeneous. Fashion clothing (option A), perfume (option D) and cars (option C) attract widely different tastes in style, scent, size and price, so their preferences are far more varied."}},{"itemId":"6e4c9d54-aa87-5724-a739-5c3451016178","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6856c1ef-3ce7-5f45-8bae-be4eee6edced","sourceKey":"bank:LAG-BUA111:PQ2-095","parentItemId":null,"revision":1,"payload":{"prompt":"In benefit segmentation, market segments are identified according to","options":["the age and income of consumers","what consumers want from the product","where consumers live","how often consumers buy the product"],"correctOption":1,"section":"Market Segmentation","explanation":"Benefit segmentation groups buyers by the benefits they seek, that is, what they want the product to do for them, such as whiteness or decay protection from toothpaste. Option A describes demographic segmentation by consumer characteristics. Option D is a behavioural basis based on usage rate."}},{"itemId":"f212b7e6-c75f-54a0-a52d-236e5edb84ab","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"aba42fef-f34a-5c3b-92bd-d80e59925e67","sourceKey":"bank:LAG-BUA111:PQ2-096","parentItemId":null,"revision":1,"payload":{"prompt":"______ focuses on what consumers do, such as how often they buy and how they use the product.","options":["Benefit segmentation","Geographic segmentation","Behavioural segmentation","Segmentation by consumer characteristics"],"correctOption":2,"section":"Market Segmentation","explanation":"Behavioural segmentation groups buyers by their actions, such as purchase occasion, usage rate, loyalty and how they use the product. Option A focuses on what consumers want rather than what they do. Option D uses who consumers are, such as age, sex and income."}},{"itemId":"5cacc80c-9862-5d84-84fb-b3786193846e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6366adfb-dacb-5d80-b76d-f7a4bbda02cb","sourceKey":"bank:LAG-BUA111:PQ2-097","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach uses demographic variables such as age, sex and income to segment markets?","options":["Behavioural segmentation","Segmentation by consumer characteristics","Psychographic segmentation","Benefit segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Segmentation by consumer characteristics describes who the buyers are, using demographic variables like age, sex, income and occupation. Option C uses personality, lifestyle and attitudes instead. Option A groups buyers by what they do with the product."}},{"itemId":"8037bf53-60ab-5786-9735-4e8066f40cc0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"744342c9-0cb6-57cf-9ec7-d54bff5c58be","sourceKey":"bank:LAG-BUA111:PQ2-098","parentItemId":null,"revision":1,"payload":{"prompt":"The following are major requirements for effective segmentation EXCEPT:","options":["Accessibility","Substantiality","Ability","Measurability"],"correctOption":2,"section":"Market Segmentation","explanation":"Useful segments should be measurable, substantial, accessible and actionable, so that the firm can size them, profit from them, reach them and serve them. \"Ability\" is not one of these requirements. Options D, B and A are all standard tests of a good segment."}},{"itemId":"674f003a-59b4-5b24-81f4-59d19f14180e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8ff84b13-4414-5f12-a5b7-499c29ee2a0e","sourceKey":"bank:LAG-BUA111:PQ2-099","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the degree to which the size and purchasing power of the segments can be measured.","options":["Measurability","Accessibility","Substantiality","Actionability"],"correctOption":0,"section":"Market Segmentation","explanation":"Measurability asks whether a segment's size and buying power can actually be measured, since a firm cannot plan for a group it cannot size. Option C is about whether the segment is large or profitable enough. Option B is about whether the segment can be reached and served."}},{"itemId":"58336d13-feec-54fb-8e5d-95a0a39de0f8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d05e7ee1-e013-50f9-8141-d6a9388ded92","sourceKey":"bank:LAG-BUA111:PQ2-100","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the degree to which the segments are large and/or profitable enough to serve.","options":["Accessibility","Substantiality","Actionability","Measurability"],"correctOption":1,"section":"Market Segmentation","explanation":"Substantiality means the segment is big or profitable enough to justify a separate marketing programme. Option D is about whether its size and buying power can be measured at all. Option C is about whether the firm can design programmes to attract and serve it."}},{"itemId":"be6fcd73-60fb-50e8-8489-1a4384af5770","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ab63662d-1a0d-5787-aeba-c9a603b10ace","sourceKey":"bank:LAG-BUA111:PQ2-101","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the degree to which the segment can be effectively reached and served.","options":["Accessibility","Measurability","Substantiality","Actionability"],"correctOption":0,"section":"Market Segmentation","explanation":"Accessibility means the firm can actually reach the segment through suitable media and distribution channels and serve it. Option D is close but refers to being able to design effective programmes for the segment. Option C is about size and profitability."}},{"itemId":"0025c06e-dd4e-5547-b518-20700e908667","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d2cb4f03-ab08-575f-8eab-64f280a2394c","sourceKey":"bank:LAG-BUA111:PQ2-102","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the degree to which effective programmes can be formulated for attracting and serving the segments.","options":["Actionability","Accessibility","Measurability","Substantiality"],"correctOption":0,"section":"Market Segmentation","explanation":"Actionability asks whether the firm has the resources to design effective marketing programmes that attract and serve the segment. Option B is about whether the segment can be reached through media and channels. Option C is about sizing the segment."}},{"itemId":"40213387-03c6-566f-8adf-830c195b3c60","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"006e3961-1d3e-5d20-b5c5-08f33289a3ee","sourceKey":"bank:LAG-BUA111:PQ2-104","parentItemId":null,"revision":1,"payload":{"prompt":"Segmentation bases that use dimensions which simply define or describe the consumers in a segment, such as age, income and location, are called","options":["descriptive bases","causal bases","usage bases","benefit bases"],"correctOption":0,"section":"Market Segmentation","explanation":"Descriptive bases tell us who the consumers in a segment are, using features like demographics and geography. Option B uses dimensions that explain why customers respond to a marketing mix, such as benefits sought. Options D and C are examples of such explanatory or behavioural variables, not descriptions of who the consumer is."}},{"itemId":"3906f341-e36d-5d42-9489-ac21ec302a32","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"84f65ace-adfe-5fe6-9e52-8584b7731179","sourceKey":"bank:LAG-BUA111:PQ2-105","parentItemId":null,"revision":1,"payload":{"prompt":"Segmentation bases that use dimensions explaining WHY customers respond to marketing mixes, such as the benefits they seek, are called","options":["geographic bases","demographic bases","descriptive bases","causal bases"],"correctOption":3,"section":"Market Segmentation","explanation":"Causal bases look for the reasons behind buyers' responses, such as the benefits they seek, so they explain why a segment behaves as it does. Option C only describes who is in the segment. Options B and A are descriptive variables, not causes."}},{"itemId":"e2cbfb0c-cdd2-5d7a-9ec9-fff381821ac7","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"39035a0b-02df-5fa4-96d3-3a2d3585221c","sourceKey":"bank:LAG-BUA111:PQ2-106","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit of effective market segmentation?","options":["Using one identical marketing mix for every customer","Improved allocation of marketing resources","Greater customer satisfaction","Better identification of marketing opportunities"],"correctOption":0,"section":"Market Segmentation","explanation":"Segmentation exists precisely so a firm does not have to offer one identical mix to everyone; it tailors a mix to each group. By doing so it directs resources to the most promising groups (option B), satisfies customers better (option C) and reveals unmet needs (option D), which can raise sales and profits."}},{"itemId":"39eab9dc-d1fe-54b9-a79b-a07cd10e69e0","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b39eff89-1f68-56fa-a213-ac99f401038a","sourceKey":"bank:LAG-BUA111:PQ2-111","parentItemId":null,"revision":1,"payload":{"prompt":"______ is the process by which marketing plans are developed for products.","options":["Short-term planning","Marketing planning","Strategic planning","Medium-term planning"],"correctOption":1,"section":"Marketing Management","explanation":"Marketing planning is the process of analysing the situation, setting objectives and designing the strategies and programmes that make up a product's marketing plan. Option C works at the level of the whole organisation, setting its mission and long-run direction. Options D and A describe planning horizons, not the process itself."}},{"itemId":"488643dd-cedf-577f-93c5-184c22b92b06","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"aee05f94-70bc-5249-88b5-4fdec3503dd5","sourceKey":"bank:LAG-BUA111:SEG-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of dividing a broad market into smaller groups of customers who share meaningful characteristics such as demographics, geography, psychographics or behaviour is called:","options":["Marketing mix","Market segmentation","Market positioning","Market targeting"],"correctOption":1,"section":"Market Segmentation","explanation":"Market segmentation splits a large, mixed market into smaller groups of similar customers so the firm can tailor its offers to each group. Option C is about creating a distinct image in customers' minds, option D is choosing which segments to serve after segmenting, and option A is the set of tools (4Ps) used to serve a market."}},{"itemId":"a003c713-0058-5d34-aa56-3e88eb80f3d5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"85904c00-d33e-5c00-a59e-2d0e52c5fcd8","sourceKey":"bank:LAG-BUA111:SEG-002","parentItemId":null,"revision":1,"payload":{"prompt":"One of the major reasons marketers segment a market is that segmentation allows them to:","options":["Serve every customer in the country with one standard product","Avoid doing any market research","Create a custom marketing mix for each segment and cater to it accordingly","Use exactly the same marketing message for every customer"],"correctOption":2,"section":"Market Segmentation","explanation":"Because each segment has shared needs, the firm can design a marketing mix that fits that segment, which makes its marketing more relevant and profitable. Options D and A describe mass marketing, the opposite of segmentation, and option B is wrong because segmentation actually requires research."}},{"itemId":"70631fb4-4428-57cb-ac05-cd90d88e6c74","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"da578b5b-fff0-515c-ab92-6e7390550408","sourceKey":"bank:LAG-BUA111:SEG-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of market segmentation is described as the most common type, the one most people think of when they hear the term 'market segmentation'?","options":["Psychographic segmentation","Geographic segmentation","Behavioural segmentation","Demographic segmentation"],"correctOption":3,"section":"Market Segmentation","explanation":"Demographic segmentation, using variables such as age, sex, religion and income, is the most widely used form because the data are easy to obtain. Behavioural segmentation (option C) is reported to be the most effective, which is a different claim from being the most common; options A and B are also used but less commonly."}},{"itemId":"7b8b8ce2-4bf4-52b4-8d11-fb4ab1bbf238","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"caa0200f-c736-5d9b-b65b-9b7933a6c67a","sourceKey":"bank:LAG-BUA111:SEG-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a demographic segmentation variable?","options":["Family size","Personality","Religion","Occupation"],"correctOption":1,"section":"Market Segmentation","explanation":"Personality is a psychological trait, so it is a psychographic variable. Religion (option C), family size (option A) and occupation (option D) describe the population itself and are demographic variables."}},{"itemId":"4e5f3a94-79b9-5220-a7f3-c4d7e9597e78","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b9a346d2-812a-5f39-8f12-7e8caa806036","sourceKey":"bank:LAG-BUA111:SEG-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the variables examined under psychographic segmentation?","options":["Time zone","Priorities and motivations","Likes and dislikes","Inner beliefs"],"correctOption":0,"section":"Market Segmentation","explanation":"Time zone is a geographic variable, because it depends on where a customer is located. Inner beliefs (option D), priorities and motivations (option B) and likes and dislikes (option C) are psychographic variables, together with lifestyle, attitudes and values, and personality."}},{"itemId":"129049b0-836e-56e5-8a55-a5df9c4fe6da","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"20eb4732-f962-5efd-ae78-8f14b9f11b66","sourceKey":"bank:LAG-BUA111:SEG-006","parentItemId":null,"revision":1,"payload":{"prompt":"An events company advertises the same concert in two ways: to one group it stresses the freedom to choose quiet activities they are comfortable with, and to another it stresses meeting people and socialising. The company is segmenting by:","options":["Urbanicity","Social status","User status","Personality"],"correctOption":3,"section":"Market Segmentation","explanation":"Personality segmentation groups people by traits such as being introverted or extroverted, which affect how they respond to an offer. Option B is about how highly society views a person, option A is about how urban an area is, and option C is about whether someone is a current, ex- or potential user."}},{"itemId":"dd22d674-fa41-5dda-b52c-56ad04b2f327","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8ad6c243-bba8-5dd2-911b-b90517ee4e54","sourceKey":"bank:LAG-BUA111:SEG-007","parentItemId":null,"revision":1,"payload":{"prompt":"An online sneaker store in Lagos runs one campaign for buyers who want sneakers for jogging and gym work, and a different campaign for buyers who want sneakers as a fashion statement. This is segmentation by:","options":["Climate and season","Language","Lifestyle","Social status"],"correctOption":2,"section":"Market Segmentation","explanation":"Lifestyle segmentation groups customers by the kind of lives they lead, and products are marketed as enhancing that lifestyle, whether active or fashion-focused. Option A is a geographic variable, option D is about social class, and option B is about the words and slang used in a region."}},{"itemId":"37349671-8235-54dd-a399-4e0475e8eb62","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7060c217-0786-5670-9edf-ebebc7863a49","sourceKey":"bank:LAG-BUA111:SEG-008","parentItemId":null,"revision":1,"payload":{"prompt":"A five-star hotel in Abuja advertises luxury experiences and quality service, while a budget hotel in the same city advertises how affordable its rooms are. Each hotel is targeting customers on the basis of:","options":["Personality","Urbanicity","Social status","Brand interactions"],"correctOption":2,"section":"Market Segmentation","explanation":"Social status is how highly a person is viewed in society, and it shapes buying: upper-class customers respond to luxury, while middle and lower classes care more about affordability. Option A is about traits such as introversion, option B is about how urban an area is, and option D is a behavioural variable about how customers engage with a brand."}},{"itemId":"eaa2a300-60bf-51f0-8a33-430b4355c0b3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"70825ca0-4dd6-5b1c-a020-7eac03cfd9a1","sourceKey":"bank:LAG-BUA111:SEG-009","parentItemId":null,"revision":1,"payload":{"prompt":"In psychographic segmentation, people's perceptions of the world, usually shaped by their upbringing and their cultural and religious backgrounds, are called their:","options":["Lifestyles","Attitudes","Personalities","Social status"],"correctOption":1,"section":"Market Segmentation","explanation":"Attitudes are how people see the world, formed by upbringing, culture and religion, and customers can be grouped by them even though each person's worldview is unique. Option A is the kind of life a person leads, option C is a set of personal traits such as being sociable or creative, and option D is how highly society regards a person."}},{"itemId":"a421bfef-2948-5710-b086-c325a27cc5e6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"646531bf-c4d8-57c7-abd2-ef33be87c4f2","sourceKey":"bank:LAG-BUA111:SEG-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the six variables of geographic segmentation?","options":["Spending habits","Time zone","Cultural preferences","Urbanicity"],"correctOption":0,"section":"Market Segmentation","explanation":"Spending habits is a behavioural variable, because it describes what customers do rather than where they are. Urbanicity (option D), cultural preferences (option C) and time zone (option B) are geographic variables, along with location, climate and season, and language."}},{"itemId":"bacc3b2b-7e3e-51c3-afc9-158735114bf5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"58f9a897-caf9-5ee2-8c71-23d27763a183","sourceKey":"bank:LAG-BUA111:SEG-011","parentItemId":null,"revision":1,"payload":{"prompt":"Under geographic segmentation, the 'location' variable categorises customers:","options":["By the climate and season they experience","Solely by where they live or work, without considering language or culture","By the slang and colloquialisms they use","By how urban or rural their area is"],"correctOption":1,"section":"Market Segmentation","explanation":"Location looks only at where the customer lives or works and ignores other location-related factors like language or culture. Option D describes urbanicity, option C describes the language variable, and option A describes climate and season, each of which is a separate geographic variable."}},{"itemId":"e423fda2-8470-5bf4-823c-bde7ebe86e7a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a71e4b20-d3a6-589b-bf4b-2913c4adcd50","sourceKey":"bank:LAG-BUA111:SEG-012","parentItemId":null,"revision":1,"payload":{"prompt":"A clothing retailer promotes raincoats and umbrellas to customers in Port Harcourt during the rainy season, and heavier wear to customers in Jos during the cold harmattan months. Which geographic variable is it using?","options":["Urbanicity","Language","Cultural preferences","Climate and season"],"correctOption":3,"section":"Market Segmentation","explanation":"Different regions have different climates and experience seasons at different times, so firms target them with products relevant to that period. Option A groups areas as urban, suburban or rural, option B concerns the words used in each region, and option C concerns cultural norms."}},{"itemId":"80e515f7-2901-508d-95f0-48418f8abae6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"33e65c68-31e9-5b3a-886c-38ae6f1405d0","sourceKey":"bank:LAG-BUA111:SEG-013","parentItemId":null,"revision":1,"payload":{"prompt":"A beer brand advertises openly in Lagos but uses very different, more careful marketing in parts of Northern Nigeria where drinking in public may be frowned upon. This is segmentation by:","options":["Climate and season","Time zone","Cultural preferences","Benefits sought"],"correctOption":2,"section":"Market Segmentation","explanation":"Regions differ in culture, and culture strongly affects buying, so firms tailor marketing to each region and avoid what could be offensive there. Options A and B are other geographic variables unrelated to cultural norms, and option D is a behavioural variable about what customers want from the product."}},{"itemId":"19e22b20-54ff-5e95-83b6-d989d1bdcb63","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e3018134-8c40-5ee7-8caf-8743565dd7ab","sourceKey":"bank:LAG-BUA111:SEG-014","parentItemId":null,"revision":1,"payload":{"prompt":"A vehicle dealer promotes small saloon cars in city areas, but promotes pick-up trucks that can handle rough roads and haul farm inputs in rural areas. Which geographic variable is it using?","options":["Urbanicity","Language","Time zone","Social status"],"correctOption":0,"section":"Market Segmentation","explanation":"Urbanicity groups areas by how urban they are, such as urban, suburban and rural, because needs differ; rural buyers may need trucks for rough terrain and farm work. Options C and B are other geographic variables not related to how built-up an area is, and option D is a psychographic variable."}},{"itemId":"f98de3f9-ce77-54af-94cf-9f5dfa4509de","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8d3d9dfb-a5a8-5646-9bba-9dd46f7ab316","sourceKey":"bank:LAG-BUA111:SEG-015","parentItemId":null,"revision":1,"payload":{"prompt":"A survey of marketers found that 91% of them consider one segmentation method the most effective for their businesses. Which method is it?","options":["Geographic segmentation","Demographic segmentation","Psychographic segmentation","Behavioural segmentation"],"correctOption":3,"section":"Market Segmentation","explanation":"Behavioural segmentation is rated the most effective method because it is based on what customers actually do. Option B is the most common type, which is a different claim from being the most effective, and options A and C were not the method rated most effective."}},{"itemId":"90784843-d898-52d6-95b3-0bc758ebf48c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7509454d-a108-58b3-b25c-951953a32877","sourceKey":"bank:LAG-BUA111:SEG-016","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a behavioural segmentation variable?","options":["Inner beliefs","Urbanicity","Time zone","Customer journey stage"],"correctOption":3,"section":"Market Segmentation","explanation":"Customer journey stage is one of the behavioural variables, along with spending habits, purchasing habits, brand interactions, user status and benefits sought. Options B and C are geographic variables, and option A is a psychographic variable."}},{"itemId":"43d88478-96e6-5f50-9b73-922e6eb5930a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3959f6bc-6efb-5024-aa61-ac0661135275","sourceKey":"bank:LAG-BUA111:SEG-017","parentItemId":null,"revision":1,"payload":{"prompt":"When customers are grouped by purchasing habits, those who are loyal to their brand and are unlikely to switch to other options are called:","options":["Complex buyers","Variety-seeking buyers","Habitual buyers","Dissonance-reducing buyers"],"correctOption":2,"section":"Market Segmentation","explanation":"Habitual buyers stick with their brand and rarely switch, so marketing to them focuses on keeping them. Option B likes its brand but is open to trying others, option A is still researching which product or brand to buy, and option D is happy with its brand but thinks others could offer more."}},{"itemId":"3eae5269-9426-5e02-bf8a-a80dc3867617","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8a885772-ffad-5b42-b61a-6b118eb7b684","sourceKey":"bank:LAG-BUA111:SEG-018","parentItemId":null,"revision":1,"payload":{"prompt":"Ada wants to buy her first laptop but does not yet know which brand or model to buy, so she is reading reviews and asking friends to learn about the options. In terms of purchasing habits, she is a:","options":["Heavy user","Habitual buyer","Variety-seeking buyer","Complex buyer"],"correctOption":3,"section":"Market Segmentation","explanation":"Complex buyers do not yet know which product or brand to buy and are still researching the options. Option B is loyal to one brand, option C already has a brand it is happy with but likes trying others, and option A is a usage-rate category, not a purchasing-habit group."}},{"itemId":"8f8df40f-aecd-50ba-82d3-e19738cdcfaa","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2157f309-6c58-5562-9dfb-ad84d529480f","sourceKey":"bank:LAG-BUA111:SEG-019","parentItemId":null,"revision":1,"payload":{"prompt":"Customers can be divided into four groups based on their purchasing habits. Which of the following is NOT one of these four groups?","options":["Impulse buyers","Variety-seeking buyers","Complex buyers","Habitual buyers"],"correctOption":0,"section":"Market Segmentation","explanation":"The four purchasing-habit groups are complex, variety-seeking, dissonance-reducing and habitual buyers; impulse buying is not one of them. Options B, C and D are all in the list."}},{"itemId":"873ab1fd-81e8-5c74-9b67-c36ca3ad949e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7d2fa8f3-bcd5-5114-88f4-de94dd24f738","sourceKey":"bank:LAG-BUA111:SEG-020","parentItemId":null,"revision":1,"payload":{"prompt":"Generational and life stage segmentation can be regarded as a subset of which type of segmentation?","options":["Geographic segmentation","Psychographic segmentation","Behavioural segmentation","Demographic segmentation"],"correctOption":3,"section":"Market Segmentation","explanation":"Generational and life stage segmentation group customers by age and where they are in life, which are population characteristics, so they fall under demographic segmentation. Option A is about place, option C about actions towards the product, and option B about psychological traits."}},{"itemId":"205ad1de-01ea-5e9e-9e86-d5c36a0e702c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"39097812-8342-5e0a-9eba-0039c1bf94dd","sourceKey":"bank:LAG-BUA111:SEG-021","parentItemId":null,"revision":1,"payload":{"prompt":"A social media app markets itself mainly to Generation Z rather than to Generation X, because people born in the same period tend to share characteristics that affect their buying. This is:","options":["Life stage segmentation","Generational segmentation","Geographic segmentation","Behavioural segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Generational segmentation groups customers by the period in which they were born, such as Generation Z, millennials, Generation X and baby boomers. Option A groups people by current circumstances such as marriage or children, option C groups by location, and option D groups by actions towards the product."}},{"itemId":"3e9fd75a-19d1-5959-af40-f9feeb02ee34","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2306098c-9f13-55c1-9fed-2565ea35826b","sourceKey":"bank:LAG-BUA111:SEG-022","parentItemId":null,"revision":1,"payload":{"prompt":"Two 30-year-old men grew up in the same Ibadan neighbourhood. One is married with a child; the other is single and still lives with his parents. A marketer who treats them as different segments because of these circumstances is using:","options":["Generational segmentation","Life stage segmentation","Usage-rate segmentation","Geographic segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Life stage segmentation groups people by where they are in life at the moment, such as marriage, children, income and home ownership, so people of the same age can have different needs. Option A would group these two men together because they were born in the same period, option D would also group them together by location, and option C is based on how much of a product people use."}},{"itemId":"e661cc9a-8d90-5724-9617-5be367e8c301","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"552ba06c-6652-539d-b40b-563f051594c7","sourceKey":"bank:LAG-BUA111:SEG-023","parentItemId":null,"revision":1,"payload":{"prompt":"When segmenting by income, marketers usually divide the market into:","options":["Urban, suburban and rural groups","Brand-loyal, brand-neutral and competitor-loyal groups","High income, mid income and low income groups","Heavy, medium and light users"],"correctOption":2,"section":"Market Segmentation","explanation":"Income decides purchasing power, so marketers commonly split the market into high, mid and low income groups, adjusted to the product and area. Option D is a usage-rate split, option A is an urbanicity split, and option B is a loyalty split."}},{"itemId":"55495f38-c872-54ed-8259-3a7a0a47011b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bfaafccc-df62-56c5-8e65-036cd5d0ea4d","sourceKey":"bank:LAG-BUA111:SEG-024","parentItemId":null,"revision":1,"payload":{"prompt":"Income is an important segmentation base because it decides a target audience's purchasing power and also helps the marketer decide:","options":["Whether customers are introverted or extroverted","Whether to market the product as a need, a want or a luxury","Which time zone to advertise in","Which language to use in advertisements"],"correctOption":1,"section":"Market Segmentation","explanation":"Income determines what customers can afford, so the same product may be presented as a need to one income group and as a luxury to another. Options C and D are geographic considerations, and option A is a personality (psychographic) consideration."}},{"itemId":"a5d99eea-4e10-5eb4-8f35-4d52a4986c4a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bf18f252-836b-5291-9a22-7af6f2593f55","sourceKey":"bank:LAG-BUA111:SEG-025","parentItemId":null,"revision":1,"payload":{"prompt":"A product that is a necessity for a self-employed trader in Onitsha may be seen as a luxury by a civil servant earning a fixed salary. A marketer who segments on this basis is using:","options":["Climate and season","Gender","Usage rate","Occupation"],"correctOption":3,"section":"Market Segmentation","explanation":"Occupation, like income, influences what people see as a need or a luxury, and some products serve only people in particular jobs. Option B groups by male and female, option C by heavy, medium or light use, and option A by weather patterns in a region."}},{"itemId":"06d0e47e-b7ab-5ee2-9d7a-5b56e85810fc","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b8c45a61-cbee-58f6-93f8-abc3ef45d64b","sourceKey":"bank:LAG-BUA111:SEG-026","parentItemId":null,"revision":1,"payload":{"prompt":"A telecoms company groups its market into ex-users, potential users, first-time users and current users of its data plans, and sends each group a different offer. This is segmentation by:","options":["Urbanicity","Life stage","Benefits sought","User status"],"correctOption":3,"section":"Market Segmentation","explanation":"User status segmentation groups people by their relationship with the product: non-users, ex-users, potential users, first-time users and regular users. Option C groups by what customers want from the product, option A by how urban their area is, and option B by circumstances such as marriage or children."}},{"itemId":"7d1bc7a6-6387-57f8-afb5-0541ef023f85","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9a73ad8-d395-5cc7-884b-adebd8cae5a5","sourceKey":"bank:LAG-BUA111:SEG-027","parentItemId":null,"revision":1,"payload":{"prompt":"Under behavioural segmentation, labelling customers as brand loyal, brand-neutral or competitor loyal is segmentation by:","options":["Loyalty status","Customer journey stage","Usage rate","Social status"],"correctOption":0,"section":"Market Segmentation","explanation":"Loyalty segmentation groups customers by how attached they are to a brand: loyal to it, neutral, or loyal to a competitor. Option C is about how much of the product people use, option D is a psychographic variable, and option B is about where a customer is in the buying process."}},{"itemId":"96199cd5-6bc9-59f6-9572-4c005239a783","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"30f19758-b17d-51d5-a9bc-963fbed58ead","sourceKey":"bank:LAG-BUA111:SEG-028","parentItemId":null,"revision":1,"payload":{"prompt":"A good market segment is always:","options":["Internally and externally heterogeneous","Internally homogeneous and externally heterogeneous","Internally heterogeneous and externally homogeneous","Internally and externally homogeneous"],"correctOption":1,"section":"Market Segmentation","explanation":"Members inside a segment should be similar to one another (homogeneous), while different segments should be clearly different from one another (heterogeneous). Option C reverses the two, option D would make segments indistinguishable, and option A would mean members of a segment have nothing in common."}},{"itemId":"0a6d6141-5ba0-5151-af3c-6861dda7413f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"118b5853-e728-58be-a956-b1354fa7fc62","sourceKey":"bank:LAG-BUA111:SEG-029","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from sharing similar features, the members of a market segment must also:","options":["Live in the same street","Buy from the same competitor","Respond in a similar way to the marketing activities aimed at them","Have exactly the same income"],"correctOption":2,"section":"Market Segmentation","explanation":"Similar characteristics are not enough; members of a segment must react in a similar way to the marketing stimulus so one marketing programme works for all of them. Options A, B and D are far too strict and are not required for a segment to be useful."}},{"itemId":"d4010975-bce5-55fb-aeda-e9ac28479a84","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8467babf-bbb5-5dd5-94d6-8d295be96dee","sourceKey":"bank:LAG-BUA111:SEG-030","parentItemId":null,"revision":1,"payload":{"prompt":"A skincare company sells an anti-ageing range aimed at mature adults and a separate clear-skin range aimed at teenagers and young adults. The main segmentation base it is using is:","options":["Age","Occupation","Urbanicity","Climate and season"],"correctOption":0,"section":"Market Segmentation","explanation":"Offering different ranges to mature adults and to teens and young adults is segmentation by age group, a demographic base common in beauty products. Option D and option C are geographic bases, and option B groups people by the jobs they do."}},{"itemId":"e0d374f2-e4d3-5fe7-94b5-af4bf69ebe0e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"04b8cc37-ca2a-58a7-adc3-a1060c4b560b","sourceKey":"bank:LAG-BUA111:SEG-031","parentItemId":null,"revision":1,"payload":{"prompt":"A snack brand sells a large N4,500 party pack in cities where teenagers buy snacks for parties, and small N200 packs in rural areas where people spend little on snacks. This is mainly an example of:","options":["Geographic segmentation","Generational segmentation","Behavioural segmentation by user status","Psychographic segmentation"],"correctOption":0,"section":"Market Segmentation","explanation":"The brand changes its packs according to where customers live, cities versus the countryside, which is geographic segmentation. Option D would be based on personality or lifestyle, option B on the period people were born, and option C on whether people are new, current or ex-users."}},{"itemId":"3d1f1296-0490-5915-a08b-c1218aa44612","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"44bb241c-467f-53bd-9eff-4d7f20d0579b","sourceKey":"bank:LAG-BUA111:SEG-032","parentItemId":null,"revision":1,"payload":{"prompt":"After segmenting the Lagos food market, a start-up discovers that no firm is serving healthy, ready-to-eat lunches for night-shift workers, and it launches a service for them. Which benefit of market segmentation does this show?","options":["Increased return on investment","Customer retention","Identification of gaps in the market","Better matching of customer needs"],"correctOption":2,"section":"Market Segmentation","explanation":"Segmentation can reveal groups that are not being served well, opening opportunities a firm can exploit for profit. Option B is about keeping existing customers, option A is about earning more from marketing spending, while option D is related but describes serving known segments better rather than finding an unserved one."}},{"itemId":"2e68db89-e26d-533f-94f7-d0b7a5f4056d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"fbeaa281-5b88-5ff0-8ce7-19f3a8bf1644","sourceKey":"bank:LAG-BUA111:SEG-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit of market segmentation?","options":["It removes the need for market research","Better matching of customer needs","Increased market share","Customer retention"],"correctOption":0,"section":"Market Segmentation","explanation":"Segmentation actually requires extensive research, which is one of its main disadvantages, so it does not remove the need for it. Better matching of needs (option B), increased market share (option C) and customer retention (option D) are all listed benefits."}},{"itemId":"8b8d23d9-a58a-5268-9f93-c44b938f8964","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9d1a35de-e418-5d8d-b2f7-0f47ec93aff0","sourceKey":"bank:LAG-BUA111:SEG-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a disadvantage of market segmentation?","options":["It is an expensive process in terms of both time and money","It reduces the firm's ability to personalise messages","It always lowers the firm's market share","It makes it harder to match customer needs"],"correctOption":0,"section":"Market Segmentation","explanation":"Segmentation is costly, because identifying groups and marketing to each differently takes a lot of time and money, and it needs extensive research. Options D and B are the opposite of what segmentation does, and option C contradicts the benefit of increased market share."}},{"itemId":"3ffb3ea5-6955-51dd-b64b-81d5a0c26aa9","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4cbeae2e-2e8c-5d3a-b229-fb961c0090fe","sourceKey":"bank:LAG-BUA111:SEG-035","parentItemId":null,"revision":1,"payload":{"prompt":"For market segments to be useful, they should be measurable, accessible, substantial, differentiable and actionable. Which of the following is NOT one of these requirements?","options":["Inexpensive","Substantial","Measurable","Accessible"],"correctOption":0,"section":"Market Segmentation","explanation":"The five requirements for effective segmentation are measurable, accessible, substantial, differentiable and actionable; being cheap to serve is not one of them. Options B, C and D are all requirements."}},{"itemId":"c818b500-4565-5236-ac8f-089fdaa46018","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4726af30-9a00-5bcd-9215-72d48ef1f7b8","sourceKey":"bank:LAG-BUA111:SEG-036","parentItemId":null,"revision":1,"payload":{"prompt":"A firm finds a segment of left-handed golfers in Owerri, but the group is so small that serving it would never be profitable. Which requirement for effective segmentation does this segment fail?","options":["Differentiable","Accessible","Substantial","Measurable"],"correctOption":2,"section":"Market Segmentation","explanation":"A substantial segment is large or profitable enough to be worth pursuing with its own marketing programme. Option D is about being able to measure the segment's size and buying power, option B about being able to reach and serve it, and option A about it responding differently from other segments."}},{"itemId":"4ca34087-c2e5-5dc7-8c07-8a7ca9006cd1","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"830e4c40-599e-5d60-a354-f6114f1a1ee0","sourceKey":"bank:LAG-BUA111:SEG-037","parentItemId":null,"revision":1,"payload":{"prompt":"A marketer identifies a segment that is large and profitable, but its members cannot be reached through any media or distribution channel the firm can use. Which requirement does the segment fail?","options":["Actionable","Substantial","Accessible","Measurable"],"correctOption":2,"section":"Market Segmentation","explanation":"An accessible segment can be effectively reached and served. This one is big enough, so option B is met; option A concerns whether the firm can design programmes to attract the segment, and option D concerns whether its size and purchasing power can be measured."}},{"itemId":"c7380871-fca4-5e1c-9692-3fa3c9f65371","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b351afdb-9980-5bd6-8422-a57927af68fb","sourceKey":"bank:LAG-BUA111:SEG-038","parentItemId":null,"revision":1,"payload":{"prompt":"When segments are conceptually distinguishable and respond differently to different marketing mix elements and programmes, they are said to be:","options":["Accessible","Differentiable","Actionable","Substantial"],"correctOption":1,"section":"Market Segmentation","explanation":"Differentiable segments react differently to marketing programmes; if two groups respond the same way to every offer, they are not really separate segments. Option A is about reaching the segment, option D about its size and profitability, and option C about the firm's ability to design programmes for it."}},{"itemId":"68a7a59a-49ee-5db0-992c-b55726e9b440","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0faabde2-85df-5ca3-b14e-0dc3d0d125be","sourceKey":"bank:LAG-BUA111:SEG-039","parentItemId":null,"revision":1,"payload":{"prompt":"A small airline identifies seven attractive segments, but its staff and budget are too small to develop separate marketing programmes for each. Which requirement for effective segmentation is lacking?","options":["Differentiable","Measurable","Substantial","Actionable"],"correctOption":3,"section":"Market Segmentation","explanation":"Actionable means effective programmes can be designed to attract and serve the segments; a firm without the resources to do so cannot act on them. Option B is about measuring segment size, option A about segments responding differently, and option C about segments being large enough."}},{"itemId":"4f9c9f1d-7a99-5d90-bc90-6ac615b95808","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9735c338-ad3a-591c-b568-0c49aa3b5baf","sourceKey":"bank:LAG-BUA111:SEG-040","parentItemId":null,"revision":1,"payload":{"prompt":"A target market is best defined as:","options":["Every person in a country who has money to spend","A set of buyers sharing common needs or characteristics that a company decides to serve","The firm's competitors in a particular region","The place where a product is physically sold"],"correctOption":1,"section":"Market Segmentation","explanation":"After segmenting, the firm evaluates the segments and chooses one or more to serve; those chosen buyers are its target market. Option A is the whole population, not a chosen group, option C confuses customers with competitors, and option D describes a retail outlet."}},{"itemId":"06468a04-4838-5996-b150-c37d73870a26","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"57569257-8708-52ed-9036-779a798ab925","sourceKey":"bank:LAG-BUA111:SEG-041","parentItemId":null,"revision":1,"payload":{"prompt":"A salt producer sells one product with one marketing programme to the whole Nigerian market, ignoring differences between segments. This targeting strategy is:","options":["Micromarketing","Undifferentiated (mass) marketing","Concentrated (niche) marketing","Differentiated (segmented) marketing"],"correctOption":1,"section":"Market Segmentation","explanation":"Undifferentiated marketing treats the market as one and offers a single product and programme that appeals to what customers have in common. Option D targets several segments with separate offers, option C goes after a large share of one or a few small segments, and option A tailors offers to specific locations or individuals."}},{"itemId":"5dd67753-be75-59fa-a401-fc4eec7842ee","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9f57eb86-3bad-5d3b-91d4-dac479d105cc","sourceKey":"bank:LAG-BUA111:SEG-042","parentItemId":null,"revision":1,"payload":{"prompt":"A drinks company offers a low-sugar drink for health-conscious adults, an energy drink for students and a malt drink for families, each with its own advertising. This targeting strategy is:","options":["Undifferentiated (mass) marketing","Individual marketing","Concentrated (niche) marketing","Differentiated (segmented) marketing"],"correctOption":3,"section":"Market Segmentation","explanation":"Differentiated marketing targets several segments and designs a separate offer for each. Option A uses one offer for everyone, option C focuses on one or a few small segments, and option B tailors products to single customers."}},{"itemId":"e82ae2ab-fbb9-5769-b44a-de6671659d86","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"36072b3a-af25-5b35-bd93-5ebb94ca6c99","sourceKey":"bank:LAG-BUA111:SEG-043","parentItemId":null,"revision":1,"payload":{"prompt":"A small Lagos firm with limited resources makes only handmade shoes for people with very large feet, aiming to win a large share of this one small segment. This targeting strategy is:","options":["Differentiated (segmented) marketing","Concentrated (niche) marketing","Undifferentiated (mass) marketing","Local marketing"],"correctOption":1,"section":"Market Segmentation","explanation":"Concentrated marketing goes after a large share of one or a few small segments or niches, which suits firms with limited resources. Option A serves many segments with separate offers, option C serves the whole market with one offer, and option D tailors offers to a city or neighbourhood."}},{"itemId":"d5098c87-3e62-5464-a353-56146dab0441","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f16b636d-5ba0-5365-8099-923cf202a12b","sourceKey":"bank:LAG-BUA111:SEG-044","parentItemId":null,"revision":1,"payload":{"prompt":"Tailoring products and marketing programmes to the needs and wants of specific individuals and local customer groups is called:","options":["Mass marketing","Undifferentiated marketing","Micromarketing","Market positioning"],"correctOption":2,"section":"Market Segmentation","explanation":"Micromarketing, which includes local marketing and individual marketing, is the narrowest targeting strategy. Options A and B are the broadest, treating the whole market as one, and option D is about the image a product holds in customers' minds rather than whom it is tailored to."}},{"itemId":"6c86b829-2f5b-5002-b8d1-078402cdb4d5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9af266e6-5c21-59a6-aa21-fd46dccd5ea0","sourceKey":"bank:LAG-BUA111:SEG-045","parentItemId":null,"revision":1,"payload":{"prompt":"A tailor in Abeokuta takes each customer's measurements and preferences and makes every outfit to that one customer's order. This is the form of micromarketing called:","options":["Individual marketing","Concentrated marketing","Local marketing","Undifferentiated marketing"],"correctOption":0,"section":"Market Segmentation","explanation":"Individual marketing, also called one-to-one marketing, tailors the product and programme to the needs of single customers. Option C tailors offers to cities, neighbourhoods or stores, option B targets one small segment rather than one person, and option D offers one product to everyone."}},{"itemId":"a09c6f17-1cd7-5e26-b8c2-93b7865327de","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"eabb9119-fe69-5771-8f1f-78cbdc8a6c2f","sourceKey":"bank:LAG-BUA111:SEG-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which option gives the correct order of the main steps in designing a customer-driven marketing strategy?","options":["Positioning, segmentation, targeting","Targeting, segmentation, positioning","Segmentation, positioning, targeting","Segmentation, targeting, positioning"],"correctOption":3,"section":"Market Segmentation","explanation":"A firm first divides the market into segments, then chooses which segments to target, and finally positions its offer in the minds of the chosen customers. Options A, B and C each place a step before the one it depends on."}},{"itemId":"c4a3dfc6-d8de-5f41-b84a-d802334f29c6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"b5bb297d-54fa-54e0-96c0-cb3629d06cff","sourceKey":"bank:LAG-BUA111:SEG-047","parentItemId":null,"revision":1,"payload":{"prompt":"Arranging for a product to occupy a clear, distinctive and desirable place relative to competing products in the minds of target consumers is called:","options":["Positioning","Differentiated marketing","Segmentation","Targeting"],"correctOption":0,"section":"Market Segmentation","explanation":"Positioning is about how the target customers see the brand compared with competitors. Option C divides the market into groups, option D chooses which groups to serve, and option B is a targeting strategy that serves several segments with different offers."}},{"itemId":"4f6781ba-0686-556b-a07c-59f72133384c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"7c6f8864-983c-57f2-b2da-f99b42aa7362","sourceKey":"bank:LAG-BUA111:SEG-048","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following segmentation variables is typically used for business (industrial) markets rather than for individual consumers?","options":["Personality and lifestyle","Industry type and company size","Sex and marital status","Generation and life stage"],"correctOption":1,"section":"Market Segmentation","explanation":"Business buyers can be segmented by industry, company size, location, operating variables, purchasing approaches and similar factors. Options A, C and D describe individual people and are used mainly for consumer markets."}},{"itemId":"030aeb31-8779-5e6f-afe4-98cc3df4cbad","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d7d28311-abab-5fcd-bf7e-46ea7130e836","sourceKey":"bank:LAG-BUA111:SEG-049","parentItemId":null,"revision":1,"payload":{"prompt":"A study finds 200,000 potential buyers of a new study app in a city, of whom 35% are aged 16-24. What is the size of the 16-24 segment?","options":["7,000 buyers","130,000 buyers","70,000 buyers","57,143 buyers"],"correctOption":2,"section":"Market Segmentation","explanation":"Segment size is the total market multiplied by the segment's share: 200,000 x 0.35 = 70,000 buyers. Option B is the size of everyone outside the segment (65%), option A misplaces the decimal point, and option D comes from dividing 200,000 by 3.5 instead of multiplying."}},{"itemId":"e1a79de4-9d97-5f9c-aba9-e6c848aecc88","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ccdebf88-d20c-589e-b05e-d900270a7548","sourceKey":"bank:LAG-BUA111:SEG-050","parentItemId":null,"revision":1,"payload":{"prompt":"Out of 300,000 sachet-water units sold in a town in a month, one brand sells 45,000 units. What is the brand's market share for the month?","options":["15%","45%","85%","6.67%"],"correctOption":0,"section":"Market Segmentation","explanation":"Market share is the brand's sales divided by total market sales, times 100: 45,000 / 300,000 x 100 = 15%. Option C is the share of all other brands, option D divides the wrong way round (300,000 / 45,000), and option B wrongly treats the 45,000 figure as a percentage."}},{"itemId":"393d8963-4bf6-5e8b-bbbb-51f3daa2ef19","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"c2c22b2d-dbc6-5607-9a3a-3af10eb7897a","sourceKey":"bank:LAG-BUA111:SYS-001","parentItemId":null,"revision":1,"payload":{"prompt":"A set of interacting and interdependent individuals and institutions (producers, suppliers, intermediaries and customers) linked together by flows of goods, money and information is best described as a","options":["marketing concept","marketing mix","marketing system","market segment"],"correctOption":2,"section":"Marketing System","explanation":"A marketing system is the whole network of participants that are tied together by flows of products, payments and information so that exchange can take place. Option B is the set of controllable tools (such as the 4 Ps) a firm uses, not the network of participants. Option D is a group of similar customers, and Option A is a business philosophy."}},{"itemId":"c96ec70e-e448-5571-85f3-d8ce8c739449","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"bca9d1c7-2c02-54bd-a7d0-47c2a33bbe9b","sourceKey":"bank:LAG-BUA111:SYS-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes a marketing system?","options":["The uncontrollable forces outside the firm that affect its decisions","The set of controllable variables a firm blends to satisfy its target market","The process of dividing a market into distinct groups of buyers","The network of firms, suppliers, intermediaries and customers linked by flows of goods, money and information"],"correctOption":3,"section":"Marketing System","explanation":"A marketing system covers all the parties involved in exchange and the flows that connect them. Option B describes the marketing mix, Option C describes market segmentation, and Option A describes the macro environment, which is only one part of the bigger system."}},{"itemId":"3a501f4c-bd4a-5f89-9fdc-a3f134d89226","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"90cb5b3b-04cd-5931-ab5f-e0740aebb1f4","sourceKey":"bank:LAG-BUA111:SYS-003","parentItemId":null,"revision":1,"payload":{"prompt":"In a simple marketing system, which of the following flows from the seller to the buyer (the market)?","options":["Goods/services and communication","Money and information","Payment and orders","Money and goods"],"correctOption":0,"section":"Marketing System","explanation":"In the simple model, sellers send goods/services and communication (such as advertising) to the market, while buyers send back money and information. Option B is what moves from buyers to sellers. Option D and Option C wrongly put payment flows going towards the buyer."}},{"itemId":"e45dc8bd-9ca3-54a6-99a0-52b579ddbe45","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"a62b3731-62c9-515d-b33e-2086328beb9a","sourceKey":"bank:LAG-BUA111:SYS-004","parentItemId":null,"revision":1,"payload":{"prompt":"A pepper seller at a village market in Ogun State sells her own produce directly to shoppers, who pay her in cash and tell her which peppers they prefer. This arrangement is best described as a","options":["horizontal marketing system","simple marketing system","vertical marketing system","complex (modern) marketing system"],"correctOption":1,"section":"Marketing System","explanation":"A simple marketing system involves a direct exchange between a seller and buyers, with goods going one way and money and information coming back. Option D involves many interconnected markets, intermediaries and government. Option C and Option A are channel arrangements involving several cooperating firms, which is not the case here."}},{"itemId":"bb55d554-6aaa-5acb-b234-8c8835dfe34e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"8502617c-fe07-55d4-8cad-adc7643a343f","sourceKey":"bank:LAG-BUA111:SYS-005","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following correctly distinguishes a complex (modern) marketing system from a simple one?","options":["The complex system involves only direct sales from producers to final consumers","The complex system links many markets, such as resource, manufacturer, intermediary, consumer and government markets, rather than just one seller and its buyers","The complex system excludes the government because it does not buy or sell","The complex system has no flow of information between buyers and sellers"],"correctOption":1,"section":"Marketing System","explanation":"In a modern economy, producers buy from resource markets, sell through intermediary markets to consumers, and deal with government, all linked by flows of goods, money and information. Option D is wrong because information still flows. Option A describes a simple system, and Option C is wrong because government buys goods, collects taxes and provides services within the system."}},{"itemId":"c8a7d775-8a48-53c3-aafe-30bea7b536e8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e36eebe9-b0ef-5d70-9253-3e55efc6e353","sourceKey":"bank:LAG-BUA111:SYS-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the markets linked together in the structure of a modern exchange economy?","options":["Intermediary markets","Resource markets","Marketing mix market","Government markets"],"correctOption":2,"section":"Marketing System","explanation":"A modern marketing system links resource markets, manufacturer markets, intermediary markets, consumer markets and government markets. There is no such thing as a marketing mix market; the marketing mix is a set of tools, not a market. Option B, Option A and Option D are all genuine parts of the structure."}},{"itemId":"054223c7-f7b4-5445-8bef-91acd6d1e0f2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"ef167729-2c07-5ca9-8ba9-cb0592d67a26","sourceKey":"bank:LAG-BUA111:SYS-007","parentItemId":null,"revision":1,"payload":{"prompt":"In the flows of a modern exchange economy, which of the following best describes the role of government markets?","options":["They supply only raw materials to manufacturers","They buy goods from other markets, collect taxes and provide public services in return","They stand completely outside the marketing system","They act only as retailers selling goods to households"],"correctOption":1,"section":"Marketing System","explanation":"Governments buy goods from resource, manufacturer and intermediary markets, pay them, collect taxes from these markets and from consumers, and provide services. Option A describes resource markets, and Option D describes intermediaries. Option C is wrong because government is a key participant in the modern system."}},{"itemId":"39a3a7e3-c03d-5af6-bd4c-9e826932ee5a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e7d20074-5426-5dfa-9283-cc1080cf3e93","sourceKey":"bank:LAG-BUA111:SYS-008","parentItemId":null,"revision":1,"payload":{"prompt":"In a marketing system, in which direction does information mainly flow?","options":["Only from sellers to buyers","Only from buyers to sellers","In both directions, from sellers to buyers and from buyers to sellers","Only from government to firms"],"correctOption":2,"section":"Marketing System","explanation":"Sellers communicate with buyers through promotion, while buyers send information back through orders, feedback and market research. Option A describes communication only, and Option B describes feedback only. Option D is far too narrow, since all participants exchange information."}},{"itemId":"fb75d3a1-f74d-590b-b27d-45043a5803e2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"73e38f73-4ff6-50f1-8f4c-cab87b7eaafc","sourceKey":"bank:LAG-BUA111:SYS-009","parentItemId":null,"revision":1,"payload":{"prompt":"In a typical marketing channel, ownership (title) of goods and the physical goods themselves mainly flow","options":["forward, from the producer towards the final consumer","backward, from the consumer towards the producer","only from banks to the producer","only between competitors"],"correctOption":0,"section":"Marketing System","explanation":"Products and ownership move forward through the channel from producer to wholesaler to retailer to consumer. Payment is the flow that moves backward, so Option B is wrong. Option D and Option C do not describe channel flows of goods or title at all."}},{"itemId":"96f8c324-e8a4-51ff-b98d-8dbba1f1adfd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f7b31fd4-be20-5d31-94a7-d087fee322b6","sourceKey":"bank:LAG-BUA111:SYS-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT usually regarded as a component of a firm's marketing system?","options":["Marketing intermediaries","Suppliers","Competitors","The firm's internal accounting depreciation method"],"correctOption":3,"section":"Marketing System","explanation":"The main components of a marketing system are the firm itself, its suppliers, intermediaries, customers, competitors and the wider environment, linked by flows of goods, money and information. A depreciation method is an internal accounting choice, not a participant in the system. Option B, Option A and Option C are all genuine components."}},{"itemId":"8427bc19-e9e9-5b26-973d-69b2bef35d9a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f44d18a6-0f33-5014-bf05-52033a5c90e9","sourceKey":"bank:LAG-BUA111:SYS-011","parentItemId":null,"revision":1,"payload":{"prompt":"Within the marketing system, the firms that provide the raw materials and other inputs a company needs to produce its goods and services are called","options":["suppliers","competitors","resellers","customers"],"correctOption":0,"section":"Marketing System","explanation":"Suppliers provide the raw inputs and inputs, and the price of these inputs affects the final price of the product. Option C buy finished products and sell them on, Option B offer similar products to the same buyers, and Option D buy the product for final consumption."}},{"itemId":"cb4dba60-807e-5b5e-afe0-336667cc895f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"791c54e7-1d5c-5de3-a6b5-6b201e511e68","sourceKey":"bank:LAG-BUA111:SYS-012","parentItemId":null,"revision":1,"payload":{"prompt":"Firms that help a company establish a link with its customers by promoting, selling and distributing its products are known as","options":["competitors","publics","suppliers","marketing intermediaries"],"correctOption":3,"section":"Marketing System","explanation":"Marketing intermediaries stand between the firm and its customers and help with promotion, selling and distribution. Option C provide inputs rather than access to customers, Option A fight for the same buyers, and Option B are groups with an interest in the firm rather than channel partners."}},{"itemId":"93eb104f-13e6-5af4-a342-a1f6d8c49d96","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"58cc7edb-545d-5004-8069-77d70a1a37c0","sourceKey":"bank:LAG-BUA111:SYS-014","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage company in Ibadan rents space in a warehouse near the Lagos-Ibadan expressway to store its drinks before they are moved to dealers. The warehouse operator is acting as a","options":["marketing agency","reseller","financial intermediary","distribution centre"],"correctOption":3,"section":"Marketing System","explanation":"A distribution centre helps organisations store goods, and a warehouse is the standard example. The warehouse does not buy and resell the drinks, so Option B is wrong. Option A would promote the drinks, and Option C would provide finance."}},{"itemId":"0c8f9b7a-d172-5b03-96d4-9d89cbb057c5","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"764e1eaa-2884-5553-87e6-5dac53791a00","sourceKey":"bank:LAG-BUA111:SYS-015","parentItemId":null,"revision":1,"payload":{"prompt":"An advertising agency that designs a radio campaign to make customers aware of the benefits of a new detergent is an example of which type of marketing intermediary?","options":["Marketing agency","Financial intermediary","Reseller","Distribution centre"],"correctOption":0,"section":"Marketing System","explanation":"Marketing agencies promote a firm's products by making customers aware of their benefits, and an advertising agency is the typical example. Option C buys and sells the goods, Option D stores them, and Option B finances transactions."}},{"itemId":"631e3346-b306-50f1-9ccf-2ce6df81de97","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"9440476e-b457-5f5b-8bc0-282307f28a21","sourceKey":"bank:LAG-BUA111:SYS-018","parentItemId":null,"revision":1,"payload":{"prompt":"Within the micro environment, which components make up the supply side of the firm's marketing system?","options":["Customers only","Customers and the government","Demographic and economic forces","Suppliers, marketing intermediaries and competitors"],"correctOption":3,"section":"Marketing System","explanation":"The micro environment is divided into a supply side, made up of suppliers, marketing intermediaries and competitors, and a demand side, made up of customers. Option A is the demand side. Option B wrongly includes government, and Option C are macro environment forces."}},{"itemId":"3b6bd7c4-272f-5136-b70d-ae91e6d513d2","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"e9ffa9e7-4c43-5a6d-aa0b-0243c8944a66","sourceKey":"bank:LAG-BUA111:SYS-019","parentItemId":null,"revision":1,"payload":{"prompt":"Two Nigerian noodle brands sell similar products to the same students and each tries to differentiate its packs and flavours to win a bigger share of the market. In the marketing system, each brand is the other's","options":["reseller","financial intermediary","competitor","supplier"],"correctOption":2,"section":"Marketing System","explanation":"Competitors are organisations offering similar products and trying to gain market share through different marketing strategies, which pushes each firm to differentiate. Option D provides inputs, Option A buys to resell, and Option B provides finance; none describes a rival brand."}},{"itemId":"27fa4e34-7f31-5984-86e1-f8a82c7534df","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"da25b25c-71dd-5f8e-982d-37edf10b6ae1","sourceKey":"bank:LAG-BUA111:SYS-020","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best expresses the 'systems' idea behind the marketing system?","options":["Only the firm matters; suppliers and intermediaries are irrelevant","The system is fixed and does not change over time","Its parts are interdependent, so a change in one part (for example, a supplier's price) affects the other parts","Each participant operates in isolation, so changes in one part have no effect on others"],"correctOption":2,"section":"Marketing System","explanation":"A system is a set of interacting, interdependent parts, so a change in one component spreads to others, for instance higher input prices leading to higher retail prices and lower demand. Option D and Option A deny this interdependence, and Option B ignores the constant change in the environment."}},{"itemId":"43b1ae42-e38d-5abc-a617-d5f07def3c78","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"3b14e708-3a9b-5158-852f-6f5c2294fe9b","sourceKey":"bank:LAG-BUA111:SYS-021","parentItemId":null,"revision":1,"payload":{"prompt":"A set of interdependent organisations that help make a product or service available for use or consumption by the consumer or business user is called a","options":["market segment","supply of raw materials","promotion mix","marketing (distribution) channel"],"correctOption":3,"section":"Marketing System","explanation":"A marketing channel, also called a distribution channel, is the chain of interdependent organisations, such as wholesalers and retailers, that moves a product to the user. Option A is a group of buyers, Option B refers to inputs coming into the firm, and Option C is the set of communication tools."}},{"itemId":"43ee7cd0-eb91-5529-8174-4bea0383a512","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"191a024b-fd55-5150-92f4-a2d4bfc756f0","sourceKey":"bank:LAG-BUA111:SYS-022","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano farmer sells yoghurt directly to consumers from his farm gate with no wholesaler or retailer involved. This is an example of a","options":["three-level channel","zero-level (direct) channel","one-level channel","two-level channel"],"correctOption":1,"section":"Marketing System","explanation":"A zero-level or direct channel has no intermediary levels: the producer sells straight to the final consumer. Option C would include one intermediary such as a retailer, Option D would include a wholesaler and a retailer, and Option A would add a further level such as a jobber or agent."}},{"itemId":"0f9a13f4-2f21-5de7-96d7-02ec319c7a92","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"30222766-9093-564b-aedb-f8bee9b5ba74","sourceKey":"bank:LAG-BUA111:SYS-023","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian soap manufacturer sells to distributors (wholesalers), who sell to neighbourhood shops (retailers), who then sell to households. How many intermediary levels does this channel have?","options":["Zero (a direct channel)","Two (a two-level channel)","One (a one-level channel)","Three (a three-level channel)"],"correctOption":1,"section":"Marketing System","explanation":"Channel length is counted by the number of intermediary levels between producer and consumer, so wholesaler plus retailer makes a two-level channel. Option C would have only the retailer, Option D would need a third intermediary, and Option A would mean no intermediaries at all."}},{"itemId":"29be1bf3-3553-5c27-adda-bad538064634","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"6d66d988-564d-55bf-afba-01268afc8ec9","sourceKey":"bank:LAG-BUA111:SYS-024","parentItemId":null,"revision":1,"payload":{"prompt":"Four textile producers each want to sell to the same five clothing shops. If each producer deals directly with every shop, how many contacts are needed, and how many are needed if all of them deal through one wholesaler instead?","options":["29 contacts directly; 9 contacts through the wholesaler","9 contacts directly; 20 contacts through the wholesaler","20 contacts directly; 9 contacts through the wholesaler","20 contacts directly; 20 contacts through the wholesaler"],"correctOption":2,"section":"Marketing System","explanation":"Without an intermediary, contacts = producers x customers = 4 x 5 = 20. With one wholesaler, each producer and each shop deals only with the wholesaler, so contacts = 4 + 5 = 9. Option B swaps the two results, and Option D wrongly assumes the intermediary saves nothing; reducing the number of contacts is one of the main ways intermediaries add value."}},{"itemId":"323e91b8-4c47-5bf3-87ac-acb5f85779e6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"68e78134-b10f-5bff-933e-dce034e57661","sourceKey":"bank:LAG-BUA111:SYS-025","parentItemId":null,"revision":1,"payload":{"prompt":"Six pharmaceutical producers sell to eight pharmacies in a town. By how many does the number of contacts fall if all trade passes through a single distributor instead of each producer dealing directly with each pharmacy?","options":["14","48","34","40"],"correctOption":2,"section":"Marketing System","explanation":"Direct contacts = 6 x 8 = 48; through one distributor contacts = 6 + 8 = 14. The reduction is 48 - 14 = 34. Option B is only the direct total and Option A is only the total through the distributor, so both forget to take the difference."}},{"itemId":"190d7d6d-1bca-5b12-ac1c-8fa6f8740f2d","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f12bb96d-7484-5bd4-84aa-76c55d345a99","sourceKey":"bank:LAG-BUA111:SYS-026","parentItemId":null,"revision":1,"payload":{"prompt":"Bringing a product to customers at the right location, at the right time and in a form they can own is how intermediaries in a marketing system mainly create","options":["form utility only","place, time and possession utility","price elasticity","brand equity only"],"correctOption":1,"section":"Marketing System","explanation":"Distribution through the marketing system creates place utility (product where buyers are), time utility (available when wanted) and possession utility (transfer of ownership). Option A is created mainly by production, which changes raw inputs into finished goods. Option D and Option C are not utilities created by moving goods."}},{"itemId":"1bd52ed9-d1be-51e1-a59e-cab092712ae3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2322f025-371f-50bf-b327-1805c599d6c2","sourceKey":"bank:LAG-BUA111:SYS-027","parentItemId":null,"revision":1,"payload":{"prompt":"The channel function of shaping and fitting the offer to the buyer's needs, including activities such as manufacturing, grading, assembling and packaging, is called","options":["financing","matching","risk taking","negotiation"],"correctOption":1,"section":"Marketing System","explanation":"Matching means shaping and fitting the offer to the buyer's needs through activities such as grading, assembling and packaging. Option D is reaching agreement on price and terms so ownership can pass, Option A is getting and using funds to cover channel costs, and Option C is bearing the risks of carrying out channel work."}},{"itemId":"3526976c-70eb-5fcd-a439-fe7194d3962b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"d834583f-b085-5717-ad5c-34c69bfa85c2","sourceKey":"bank:LAG-BUA111:SYS-028","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos wholesaler buys 5,000 cartons of tomato paste in advance and stores them, accepting that it will lose money if prices fall or the goods expire before they are sold. Which channel function is the wholesaler performing?","options":["Promotion","Risk taking","Contact","Matching"],"correctOption":1,"section":"Marketing System","explanation":"Risk taking means bearing the risks of carrying out channel work, such as price falls, damage or expiry of stock held. Option A is spreading persuasive communication, Option C is finding and communicating with prospective buyers, and Option D is fitting the offer to buyers' needs."}},{"itemId":"f101d62f-a5b0-5d98-8772-eecae34cf98a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"0a87928c-9e4a-5213-b3c5-a112bb0d43d6","sourceKey":"bank:LAG-BUA111:SYS-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the key functions performed by members of a marketing channel?","options":["Negotiation","Financing","Physical distribution","Setting the national interest rate"],"correctOption":3,"section":"Marketing System","explanation":"Channel members perform functions such as information, promotion, contact, matching, negotiation, physical distribution, financing and risk taking. Setting the national interest rate is done by the central bank as part of the economic environment, not by channel members. Option C, Option B and Option A are genuine channel functions."}},{"itemId":"64bd0694-c256-5003-a3bf-26a1e282bc44","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"16e1539b-0b5f-5d6c-949d-22b30138abd5","sourceKey":"bank:LAG-BUA111:SYS-030","parentItemId":null,"revision":1,"payload":{"prompt":"A channel structure in which producers, wholesalers and retailers act as a unified system, with one member owning the others, having contracts with them or having enough power to make them cooperate, is called a","options":["simple marketing system","conventional distribution channel","vertical marketing system","horizontal marketing system"],"correctOption":2,"section":"Marketing System","explanation":"A vertical marketing system (VMS) unifies channel levels under ownership, contracts or the power of a channel leader. Option B consists of independent members each seeking its own profit, Option D joins firms at the same level, and Option A is a direct seller-buyer exchange."}},{"itemId":"5153a330-bebe-515f-a960-76f7223580bd","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"f8792ac5-4313-5702-9857-cd045bb785b9","sourceKey":"bank:LAG-BUA111:SYS-031","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer that joins with dealers through formal franchise agreements, rather than owning them, has created which type of vertical marketing system?","options":["Contractual VMS","Administered VMS","Corporate VMS","Horizontal marketing system"],"correctOption":0,"section":"Marketing System","explanation":"A contractual VMS links independent firms at different levels through contracts, and franchising is its most common form. Option C combines levels under single ownership, Option B relies on the size and power of one member rather than ownership or contract, and Option D joins firms at the same level."}},{"itemId":"faf5a2ca-6e63-5616-9506-a432e15614a8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"2df03ce1-8115-53b1-bc6d-35cf163d091e","sourceKey":"bank:LAG-BUA111:SYS-032","parentItemId":null,"revision":1,"payload":{"prompt":"A large Nigerian food company owns its own flour mills, delivery trucks and retail outlets, so it controls production and distribution under a single ownership. This is an example of a","options":["corporate vertical marketing system","contractual vertical marketing system","conventional distribution channel","administered vertical marketing system"],"correctOption":0,"section":"Marketing System","explanation":"A corporate VMS integrates successive stages of production and distribution under single ownership. Option B would rely on contracts such as franchises, Option D on the leadership power of a dominant member, and Option C on independent members with no unified control."}},{"itemId":"14d5b872-8413-54a9-8a35-add4debdabc3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"4786cd1f-024d-5067-a516-296838be6ef3","sourceKey":"bank:LAG-BUA111:SYS-033","parentItemId":null,"revision":1,"payload":{"prompt":"When two or more companies at the same channel level join together to follow a new marketing opportunity, for example a bank and a supermarket chain agreeing to place bank kiosks inside the supermarkets, the arrangement is called a","options":["simple marketing system","zero-level channel","vertical marketing system","horizontal marketing system"],"correctOption":3,"section":"Marketing System","explanation":"A horizontal marketing system is formed when firms at the same level combine resources to exploit an opportunity. Option C links different levels of the same channel, Option B refers to direct selling, and Option A is a basic seller-buyer exchange."}},{"itemId":"3156d941-23f1-5610-b115-d75629e20dc3","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"863da11e-64af-54c2-9f32-7cba01db5d99","sourceKey":"bank:LAG-BUA111:SYS-034","parentItemId":null,"revision":1,"payload":{"prompt":"A phone accessories brand sells through its own website, through market traders in Computer Village and through supermarkets at the same time. This use of several channels to reach different customer segments is called","options":["a multichannel (hybrid) distribution system","a corporate vertical marketing system","a simple marketing system","a zero-level channel"],"correctOption":0,"section":"Marketing System","explanation":"A multichannel or hybrid distribution system uses two or more marketing channels to reach one or more customer segments. Option D is only direct selling, Option B requires single ownership of all channel levels, and Option C is a basic direct exchange between one seller and its buyers."}},{"itemId":"780c4528-3a3f-51e5-a8ca-36464c2bcf7e","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"cbt_question","questionId":"80cc45bc-8d07-5d0a-8a62-4440e4b88665","sourceKey":"bank:LAG-BUA111:SYS-035","parentItemId":null,"revision":1,"payload":{"prompt":"A disagreement between a manufacturer and its own retailers over prices and margins is an example of","options":["a corporate vertical marketing system","vertical channel conflict","a horizontal marketing system","horizontal channel conflict"],"correctOption":1,"section":"Marketing System","explanation":"Vertical conflict occurs between different levels of the same channel, such as a manufacturer and its retailers. Option D occurs between firms at the same level, such as two retailers of the same brand. Option C and Option A are types of channel cooperation, not conflict."}}]$expected_content$::jsonb,
  'principles-marketing: cbt_question published payload and identity match source');
set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('0d6682a1-b7b0-5109-b86a-2fabbfbea8b4')
  where kind = 'theory_question') = $expected_content$[{"itemId":"332e0367-626a-5b48-8fc3-ecc4d2116468","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"Classify each activity into its marketing function and group: (i) a warehouse holds yam until the lean season; (ii) a bank gives a distributor a 60-day trade loan; (iii) a trader negotiates and hands over goods to a buyer; (iv) eggs are sorted by size into crates."}},{"itemId":"8c974dc1-db1b-54a4-b759-12161523332f","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:10","parentItemId":null,"revision":1,"payload":{"prompt":"An online store in Abuja spends ₦150,000 on a display campaign that delivers 500,000 impressions and 2,000 clicks. 80 of those visitors buy, producing ₦600,000 in sales. Calculate the CPM, CTR, CPC, conversion rate and ROAS."}},{"itemId":"66f699b8-e513-5bcb-ac28-6a033edfb3ae","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos ferry operator's target for the first quarter was ₦12,000,000 in fares, but actual fares were ₦9,600,000. Boats are full at rush hours but nearly empty at midday. (a) Compute the shortfall and the achievement rate. (b) Name the demand state and the matching marketing task, and say which stage of the marketing management process the computation belongs to."}},{"itemId":"fb555ddc-45af-569f-a0c9-b63d7a28d44a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish the selling concept from the marketing concept, and state the three behavioural components of market orientation."}},{"itemId":"5b9e7ccf-c51f-5566-a2aa-618ec4cf7099","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Distinguish the micro environment from the macro environment and give three forces in each."}},{"itemId":"72cecbbf-ccbc-54ba-b26e-59ad73fff229","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery that has always bought flour from one miller decides to test a new flour blend and asks two other millers to quote. Name the buy class, and explain how it differs from the other two buy classes."}},{"itemId":"e1dcb7c5-e773-5f9c-9c3d-921f683a9199","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"Industry sales of packaged juice in Lagos were ₦2,500 million last year and ₦2,600 million this year. Brand A sold ₦400 million last year and ₦390 million this year. Find Brand A's market share each year, the industry growth rate, and the likely PLC stage of the category. Suggest two strategies."}},{"itemId":"be825d80-15e4-575d-ba66-de4e51851e7b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"A noodle maker finds 480,000 noodle buyers in Ibadan, of whom 25% are students. It sells to 18,000 students. (a) How large is the student segment? (b) What share of that segment does the firm hold? (c) Which segmentation base is \"students\" and which targeting strategy would the firm use if it served only this group?"}},{"itemId":"b054ce88-2258-5fe6-ad23-e532ea5087ed","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"Three paint manufacturers sell to ten hardware shops. Each sales contact costs ₦1,500. How much does the industry save if all trade passes through one wholesaler?"}},{"itemId":"d53c397c-38d8-5169-9abf-0ee638ad1991","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:9","parentItemId":null,"revision":1,"payload":{"prompt":"In a city of 800,000 adults, 25% drink yoghurt and each drinker buys 40 cups a year at ₦500. (a) What is the annual market potential in naira? (b) If a firm expects a 15% share, what is its sales forecast?"}}]$expected_content$::jsonb,
  'principles-marketing: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('0d6682a1-b7b0-5109-b86a-2fabbfbea8b4')
  where kind = 'model_answer') = $expected_content$[{"itemId":"af141f6b-ed23-57e2-a149-5b3f3a6c98d8","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"332e0367-626a-5b48-8fc3-ecc4d2116468","revision":1,"payload":{"body":"(i) Storage, a physical supply function (time utility). (ii) Financing, a facilitating function. (iii) Selling, an exchange function (possession utility). (iv) Standardisation and grading, a facilitating function."}},{"itemId":"7e0e79bb-aed4-5dcd-adbc-9cf5177e8e4b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:10","parentItemId":"8c974dc1-db1b-54a4-b759-12161523332f","revision":1,"payload":{"body":"• CPM = 150,000 / 500,000 x 1,000 = 0.3 x 1,000 = ₦300.\n• CTR = 2,000 / 500,000 x 100 = 0.004 x 100 = 0.4%.\n• CPC = 150,000 / 2,000 = ₦75.\n• Conversion rate = 80 / 2,000 x 100 = 0.04 x 100 = 4%.\n• ROAS = 600,000 / 150,000 = 4 (₦4 of sales per ₦1 of advertising)."}},{"itemId":"ad3e1a62-158c-5439-975b-6594ab0e3851","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"66f699b8-e513-5bcb-ac28-6a033edfb3ae","revision":1,"payload":{"body":"• (a) Shortfall = ₦12,000,000 - ₦9,600,000 = ₦2,400,000. Shortfall % = 2,400,000 / 12,000,000 x 100 = 20%. Achievement = 9,600,000 / 12,000,000 x 100 = 80%.\n• (b) Demand that swings by hour is irregular demand; the task is synchromarketing, e.g. cheaper midday fares. Comparing actual results with a target and correcting the gap is marketing control."}},{"itemId":"2b37878f-2fb6-5492-b6c9-32f9ae9d439a","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"fb555ddc-45af-569f-a0c9-b63d7a28d44a","revision":1,"payload":{"body":"The selling concept holds that consumers will not buy enough unless the firm sells and promotes aggressively: it starts at the factory, focuses on existing products, uses selling and promoting, and seeks profit through sales volume (seller's needs, inside-out). The marketing concept holds that goals are reached by knowing target customers' needs and satisfying them better than competitors: it starts with the market, focuses on customer needs, uses integrated marketing, and seeks profit through customer satisfaction (buyer's needs, outside-in). Market orientation puts the marketing concept into practice through (1) customer orientation, (2) competitor orientation and (3) inter-functional coordination, guided by long-term focus and profitability."}},{"itemId":"0d9f0aca-a262-5f62-ba8f-97e1d580333c","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"5b9e7ccf-c51f-5566-a2aa-618ec4cf7099","revision":1,"payload":{"body":"The micro (task) environment is closely linked to the firm and directly affects its activities: suppliers (provide inputs), marketing intermediaries (promote, sell, distribute), customers (buy for final consumption) and also competitors and publics. The macro (broad) environment is the larger set of societal forces beyond the firm's control that change constantly and bring opportunities and threats: demographic (population variables), economic (cost structure and purchasing power), technological (pace of change, R&D, regulation), plus natural, political-legal and socio-cultural."}},{"itemId":"757fa62c-53e4-5ffe-b343-b9598f34bbfb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"72cecbbf-ccbc-54ba-b26e-59ad73fff229","revision":1,"payload":{"body":"This is a modified rebuy: a recurring purchase made less routine because the bakery is changing the specification and considering new suppliers. A straight rebuy would be a routine reorder of the same flour from the same miller with no changes, because the bakery has extensive experience. A new task would be a first-ever purchase (e.g. its first industrial oven), needing the most information search and the largest buying centre. There are three buy classes in all."}},{"itemId":"6d95bb6d-0e43-5317-b1b3-d39757cadeb4","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"e1dcb7c5-e773-5f9c-9c3d-921f683a9199","revision":1,"payload":{"body":"• Last year share = (400 ÷ 2,500) × 100 = 16%. This year share = (390 ÷ 2,600) × 100 = 15%.\n• Industry growth = (2,600 − 2,500) ÷ 2,500 × 100 = 4%. Brand A's own sales fell by (390 − 400) ÷ 400 × 100 = −2.5%.\n• Sales are near their peak with only slow growth and competitors taking share, so the category is in maturity.\n• Strategies: modify the market (new users or uses, e.g. juice for school lunches) and modify the product or mix (new flavours, smaller packs, promotions that encourage brand switching while stressing brand differences)."}},{"itemId":"f490997f-4137-515d-beb7-98de620a5c9b","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"be825d80-15e4-575d-ba66-de4e51851e7b","revision":1,"payload":{"body":"• (a) Segment size = 480,000 x 0.25 = 120,000 students.\n• (b) Share of segment = 18,000 / 120,000 x 100 = 15%.\n• (c) Students is a demographic base (occupation and age or life stage). Serving only this one segment is concentrated (niche) marketing."}},{"itemId":"f413f0fc-251b-5b98-b739-82f4ad6519d6","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:8","parentItemId":"b054ce88-2258-5fe6-ad23-e532ea5087ed","revision":1,"payload":{"body":"• Direct contacts = 3 × 10 = 30; cost = 30 × ₦1,500 = ₦45,000.\n• Contacts through one wholesaler = 3 + 10 = 13; cost = 13 × ₦1,500 = ₦19,500.\n• Saving = ₦45,000 − ₦19,500 = ₦25,500 (17 fewer contacts)."}},{"itemId":"99ab9a59-0b83-5f8a-a24f-87c86604c9eb","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:9","parentItemId":"d53c397c-38d8-5169-9abf-0ee638ad1991","revision":1,"payload":{"body":"• (a) Drinkers = 800,000 x 0.25 = 200,000. Cups = 200,000 x 40 = 8,000,000. Value = 8,000,000 x ₦500 = ₦4,000,000,000 (₦4 billion). This is the chain-ratio method combined with Q = n x q x p.\n• (b) Sales forecast = 0.15 x ₦4bn = ₦600 million."}}]$expected_content$::jsonb,
  'principles-marketing: model_answer published payload and identity match source');
