  where kind = 'course_overview') = $expected_content$[{"itemId":"9c10f95a-f53c-5ca4-b00c-223a3ba09197","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Marketing Communication","body":"Every topic is examinable.","outcomes":["Identify and evaluate marketing communication techniques, and the principles and theories behind each.","Explain the marketing communication process and its models.","Plan marketing communications and choose the right mix of advertising, sales promotion, public relations, personal selling and digital tools.","Explain the role of the source, message, receiver, medium and opinion leaders.","Explain the forms of business communication and the communication process.","Explain the place of social media, word-of-mouth and digital marketing in modern marketing communication.","Apply marketing communication concepts, principles and theories to solve marketing communication problems."],"assessment":["Assignments: 10%. Mid-term test: 20%. End-of-semester examination: 70%.","The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, models, authors and short applications to Nigerian businesses."]}}]$expected_content$::jsonb,
  'marketing-communication: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('ced55987-74eb-5998-929a-c1d5275c5a3b')
  where kind = 'note') = $expected_content$[{"itemId":"7f7f8f99-5465-5156-b798-a4be79cffdc6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:1","parentItemId":null,"revision":1,"payload":{"title":"Nature, Types, Roles and Objectives of Marketing Communication","body":"Definitions of marketing, communication and marketing communication; the four types of communication; the Seven Ps; how marketing communication emerged and gave rise to IMC; the conditions for exchange and the stages of the marketing communications process; the roles (including DRIP) and objectives of marketing communication.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Definitions of marketing, communication and marketing communication; the four types of communication; the Seven Ps; how marketing communication emerged and gave rise to IMC; the conditions for exchange and the stages of the marketing communications process; the roles (including DRIP) and objectives of marketing communication."}],"lessons":[{"number":"1.1","title":"Marketing, communication and marketing communication","mustKnow":[{"type":"paragraph","text":[{"text":"Marketing communication is made of two key words: "},{"text":"marketing","bold":true},{"text":" and "},{"text":"communication","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing (simple definition):","bold":true},{"text":" the establishment of mutually satisfying exchange relationships through the buying and selling of goods, services or ideas."}]},{"text":[{"text":"Baker (2000):","bold":true},{"text":" marketing is a way of managing profitable customer relationships."}]},{"text":[{"text":"Kotler and Armstrong (2006):","bold":true},{"text":" the process through which companies create value for customers and build strong customer relationships in order to capture value from customers in return (also worded \"to generate value in return\")."}]},{"text":[{"text":"Strydom, Jooste and Cant (2000):","bold":true},{"text":" the process of planning and executing the conception, pricing, marketing communication and distribution of ideas, products and services to create exchanges that satisfy individual and corporate goals."}]},{"text":[{"text":"Stapleton and Ali (2007): 4 commonalities","bold":true},{"text":" shared by these definitions:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"a focus on "},{"text":"customers","bold":true},{"text":";"}]},{"text":[{"text":"the provision of "},{"text":"suitable offerings","bold":true},{"text":" (goods, services or ideas) to meet customers' needs;"}]},{"text":[{"text":"suitable benefits to the organisation","bold":true},{"text":";"}]},{"text":[{"text":"the "},{"text":"relationship between the customer and the organisation","bold":true},{"text":", on the basis of which value can be created."}]}]}]},{"text":[{"text":"Communication (1):","bold":true},{"text":" the exchange of thoughts or conversations through written words, verbal conversation, electronic or digital media and social media platforms, to exchange ideas and information for a pre-planned purpose."}]},{"text":[{"text":"Communication (2):","bold":true},{"text":" the process of using "},{"text":"words, sounds or visual cues","bold":true},{"text":" to supply information to one or more people."}]},{"text":[{"text":"Marketing communications (MarCom):","bold":true},{"text":" the "},{"text":"channels and tools","bold":true},{"text":" companies use to communicate the necessary message to the target group. MarCom helps customers understand a company and its products. By conveying messages of significant value, it encourages audiences to give "},{"text":"positive attitudinal and behavioural responses","bold":true},{"text":"."}]},{"text":[{"text":"There is "},{"text":"no universal definition","bold":true},{"text":" of marketing communications, so there are many interpretations. "},{"text":"5 common definitions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"continuous interaction between buyers and sellers","bold":true},{"text":" in a marketplace."}]},{"text":[{"text":"The means companies adopt to convey messages about their products and brands, "},{"text":"directly or indirectly","bold":true},{"text":", to customers with the intention to "},{"text":"persuade them to purchase","bold":true},{"text":"."}]},{"text":[{"text":"The process of "},{"text":"creating and delivering messages that promote the interests of an organisation","bold":true},{"text":"."}]},{"text":[{"text":"The use of different marketing strategies and tools to "},{"text":"connect with a target audience","bold":true},{"text":"."}]},{"text":[{"text":"At its core, the "},{"text":"integration of all promotional tools and sources","bold":true},{"text":" within a company to "},{"text":"maximise the impact on consumers and other end-users at minimal cost","bold":true},{"text":"."}]}]}]},{"text":[{"text":"3 questions","bold":true},{"text":" marketing communication answers:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Who is the customer?"}]},{"text":[{"text":"What is being exchanged?"}]},{"text":[{"text":"What internal and external influences affect the exchange?"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A fuller, modern definition you should recognise: marketing communication is a "},{"text":"strategic process of creating, delivering and exchanging value-laden messages to shape customer perceptions and behaviours","bold":true},{"text":". Any option that calls it \"one-way\", \"price announcement only\", \"physical movement of goods\" or \"manufacturing\" is wrong."}]},{"text":[{"text":"Trap: the \"planning and executing the conception, pricing ... distribution\" wording is "},{"text":"Strydom, Jooste and Cant","bold":true},{"text":", "},{"text":"not","bold":true},{"text":" Baker."}]},{"text":[{"text":"Stapleton and Ali's commonalities never include cutting staff or costs."}]},{"text":[{"text":"All organisations","bold":true},{"text":" (commercial, government, charities, educational, not-for-profit, of any size) need to communicate with a range of stakeholders: suppliers, distribution partners, other departments and consumers, who are free to choose among competing offers."}]},{"text":[{"text":"A "},{"text":"customer's perception","bold":true},{"text":" of a company or brand is a "},{"text":"synthesis of bundles of messages","bold":true},{"text":": media advertising, "},{"text":"price","bold":true},{"text":", "},{"text":"packaging design","bold":true},{"text":", direct marketing, publicity, sales promotion and websites. The price of Indomie \"speaks\" as much as its TV advert."}]},{"text":[{"text":"Used well, MarCom generates "},{"text":"more leads, sales and loyal customers","bold":true},{"text":"; its ultimate aim is to influence "},{"text":"consumer decision-making and buying behaviour","bold":true},{"text":"."}]}]}]},{"number":"1.2","title":"Types of communication and the marketing mix","mustKnow":[{"type":"paragraph","text":[{"text":"4 types of communication","bold":true},{"text":" (by direction of flow between senders and receivers):"}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"One-to-many","bold":true}],[{"text":"The most original form; generated from a "},{"text":"single broadcast point","bold":true},{"text":", then available over airwaves or in mass print runs"}],[{"text":"News distribution, general announcements, TV and radio broadcasts"}]],[[{"text":"Many-to-one","bold":true}],[{"text":"Generally connected to one-to-many; many receivers reply to one sender"}],[{"text":"The "},{"text":"reply button","bold":true},{"text":" in an email box"}]],[[{"text":"One-to-one","bold":true}],[{"text":"The "},{"text":"most intensive and interactive","bold":true},{"text":" form"}],[{"text":"A "},{"text":"sales presentation","bold":true},{"text":" or a "},{"text":"negotiation","bold":true}]],[[{"text":"Many-to-many","bold":true}],[{"text":"Growing because of the highly developed "},{"text":"Internet","bold":true},{"text":"; everyone talks to everyone"}],[{"text":"Online chat rooms","bold":true},{"text":", blogs, websites"}]]]},{"type":"paragraph","text":[{"text":"The marketing mix: the Seven Ps (formerly the Four Ps).","bold":true},{"text":" A brand typically builds its MarCom strategy around it:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product:","bold":true},{"text":" the features of the good or service the business offers."}]},{"text":[{"text":"Price:","bold":true},{"text":" the pricing model used for the good or service."}]},{"text":[{"text":"Promotion:","bold":true},{"text":" all the ways in which the brand, product or service is communicated to the public. It also involves another P, "},{"text":"Positioning","bold":true},{"text":", to evaluate how people view and respond to the brand."}]},{"text":[{"text":"Place:","bold":true},{"text":" where the good or service is bought and sold."}]},{"text":[{"text":"People:","bold":true},{"text":" all the people who interact with a brand's customers or clients."}]},{"text":[{"text":"Process:","bold":true},{"text":" the customer experience and communication process."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" how best to attract customers in the physical and online marketplace."}]}]},{"type":"paragraph","text":[{"text":"Types of marketing communication (the tools):","bold":true},{"text":" the traditional "},{"text":"five","bold":true},{"text":" are advertising, sales promotion, personal selling, public relations and direct marketing. Others include publicity, events and experiences (sponsorship), interactive marketing and word-of-mouth marketing. Each is treated fully in Topic 3."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Count senders and receivers: GTBank emailing one newsletter to all customers is "},{"text":"one-to-many","bold":true},{"text":"; hundreds of them clicking \"reply\" is "},{"text":"many-to-one","bold":true},{"text":"; a sales pitch to one client is "},{"text":"one-to-one","bold":true},{"text":"; UNILAG students debating phone brands in a group chat is "},{"text":"many-to-many","bold":true},{"text":"."}]},{"text":[{"text":"\"Most intensive and interactive\" = one-to-one; \"most original\" = one-to-many. The count is "},{"text":"four","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the extra P inside Promotion is "},{"text":"Positioning","bold":true},{"text":". In the services-marketing version of the 7 Ps you may meet "},{"text":"physical evidence","bold":true},{"text":" in place of packaging; for this course, learn the list above."}]},{"text":[{"text":"A Lagos fashion brand training its shop attendants and delivery riders on how to treat buyers is working on "},{"text":"People","bold":true},{"text":"."}]},{"text":[{"text":"The combination most representative of MarCom is "},{"text":"advertising, sales promotion and direct marketing","bold":true},{"text":", not \"product, price and place\" or \"segmentation, targeting and positioning\". "},{"text":"Integrated advertising campaigns across multiple channels","bold":true},{"text":" are a core MarCom component; prototyping and warehousing are not."}]}]}]},{"number":"1.3","title":"The emergence of marketing communication and IMC","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communication is "},{"text":"not new","bold":true},{"text":": communication has been part of marketing "},{"text":"for as long as people have exchanged goods","bold":true},{"text":"."}]},{"text":[{"text":"Technology and research made it "},{"text":"increasingly sophisticated","bold":true},{"text":" in recent decades and gave rise to "},{"text":"integrated marketing communication (IMC)","bold":true},{"text":"."}]},{"text":[{"text":"IMC:","bold":true},{"text":" the use of "},{"text":"multiple channels to create a unified message","bold":true},{"text":"."}]},{"text":[{"text":"Consumers have changed","bold":true},{"text":" in 4 ways: their behaviour is "},{"text":"more complex","bold":true},{"text":"; their "},{"text":"media habits are different","bold":true},{"text":"; they are "},{"text":"more confident and outspoken","bold":true},{"text":"; and, most important, they have "},{"text":"more choices than ever before","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Timeline:","bold":true}]},{"type":"table","header":[[{"text":"When"}],[{"text":"Development"}],[{"text":"Significance"}]],"rows":[[[{"text":"15th century"}],[{"text":"Johannes Gutenberg's printing press","bold":true}],[{"text":"Before it, only handwritten manuscripts for the elite; marked the "},{"text":"birth of print advertising","bold":true}]],[[{"text":"17th century"}],[{"text":"First printed advertisements","bold":true},{"text":" in newspapers"}],[{"text":"Promoted medicines to real estate"}]],[[{"text":"1920s"}],[{"text":"Radio commercials","bold":true},{"text":" begin"}],[{"text":"Reached households with audio messages"}]],[[{"text":"1950s"}],[{"text":"Television","bold":true},{"text":" becomes the "},{"text":"dominant platform","bold":true}],[{"text":"Combined visuals and sound"}]],[[{"text":"1960s"}],[{"text":"Volkswagen's "},{"text":"\"Think Small\"","bold":true},{"text":" campaign"}],[{"text":"Showed TV could be used for "},{"text":"storytelling","bold":true},{"text":" and "},{"text":"emotional connections","bold":true}]],[[{"text":"Late 20th century"}],[{"text":"The Internet","bold":true}],[{"text":"Digital age: websites as "},{"text":"virtual storefronts","bold":true},{"text":", email as a "},{"text":"direct line","bold":true},{"text":" to customers"}]],[[{"text":"1996"}],[{"text":"Hotmail's viral strategy","bold":true}],[{"text":"\"Get your free email at Hotmail\" on every sent email; millions of users within months; an early "},{"text":"viral digital marketing","bold":true},{"text":" success"}]],[[{"text":"Early 2000s"}],[{"text":"MySpace, Facebook, Twitter","bold":true}],[{"text":"Turned marketing into a "},{"text":"two-way conversation","bold":true},{"text":"; brands engage directly with customers"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The lesson of the whole journey: marketing communication is "},{"text":"ever-evolving","bold":true},{"text":", so understanding its history helps firms "},{"text":"anticipate future trends","bold":true},{"text":" and craft strategies that resonate with audiences."}]},{"text":[{"text":"Trap: \"consumers now have "},{"text":"fewer","bold":true},{"text":" choices\" is false. They have more."}]},{"text":[{"text":"Trap: printing press "},{"text":"15th","bold":true},{"text":" century, but first newspaper adverts "},{"text":"17th","bold":true},{"text":" century."}]},{"text":[{"text":"Hotmail's tagline is "},{"text":"viral","bold":true},{"text":" marketing: users spread the message simply by using the product."}]},{"text":[{"text":"Social media did "},{"text":"not","bold":true},{"text":" end print and broadcast advertising; it added two-way dialogue, as when Jumia replies to customers on X and Instagram."}]},{"text":[{"text":"IMC in practice: MTN running the same slogan, colours and offer on TV, radio, billboards and social media, so every channel tells one story."}]}]}]},{"number":"1.4","title":"Marketing communication and the process of exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exchange process:","bold":true},{"text":" the act of "},{"text":"obtaining a desired object from someone by offering something of value in return","bold":true},{"text":"."}]},{"text":[{"text":"Transaction:","bold":true},{"text":" the result of an exchange between a person in need (offering money or other resources) and the company selling a good, service or idea."}]},{"text":[{"text":"5 conditions for exchange:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"There must be "},{"text":"at least two parties","bold":true},{"text":"."}]},{"text":[{"text":"Each must have "},{"text":"something that might be of value","bold":true},{"text":" to the other."}]},{"text":[{"text":"Each can "},{"text":"communicate and deliver","bold":true},{"text":" what they are offering."}]},{"text":[{"text":"Each is "},{"text":"free to accept or reject","bold":true},{"text":" what is on offer."}]},{"text":[{"text":"Each party "},{"text":"trusts/respects","bold":true},{"text":" the other sufficiently to take the exchange seriously."}]}]}]},{"text":[{"text":"Two observable types of exchange:","bold":true},{"text":" "},{"text":"market","bold":true},{"text":" exchange and "},{"text":"relational","bold":true},{"text":" exchange. There is a strong shift from one-off market exchanges to long-term "},{"text":"relationship marketing","bold":true},{"text":": \"Marketing is not just about selling products; it's about building relationships and creating value.\""}]}]},{"type":"paragraph","text":[{"text":"Process of marketing communications (steps in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the target audience:","bold":true},{"text":" focus on distinct segments; presenting to everyone does not work."}]},{"text":[{"text":"Determine the unique value (selling) proposition (UVP/USP):","bold":true},{"text":" what makes the business stand out and outperform rivals."}]},{"text":[{"text":"Bring the solution to customers' queries:","bold":true},{"text":" reach customers' pain points with the good or service."}]},{"text":[{"text":"Select channels","bold":true},{"text":" to deliver the brand message: depends on the "},{"text":"objectives","bold":true},{"text":" to be accomplished and "},{"text":"customers' preferences (choices)","bold":true},{"text":"."}]},{"text":[{"text":"Budget allocation:","bold":true},{"text":" how much to spend on each channel."}]},{"text":[{"text":"Message development:","bold":true},{"text":" crafting key messages that resonate with the audience."}]},{"text":[{"text":"Execution:","bold":true},{"text":" implementing the chosen plan."}]},{"text":[{"text":"Evaluate and measure the result:","bold":true},{"text":" track outcomes after the campaign runs."}]},{"text":[{"text":"Develop control measures:","bold":true},{"text":" measure the campaign's effectiveness "},{"text":"against objectives","bold":true},{"text":" and make necessary adjustments."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Condition 3 shows most directly "},{"text":"why marketing communication is necessary","bold":true},{"text":": a seller who cannot tell buyers what it offers cannot exchange."}]},{"text":[{"text":"Trap: \"each party must be "},{"text":"legally bound","bold":true},{"text":" to accept whatever is offered\" is "},{"text":"not","bold":true},{"text":" a condition. Freedom to accept or reject is."}]},{"text":[{"text":"Ada pays ₦4,500 to a Yaba bookshop for a book: the completed exchange is a "},{"text":"transaction","bold":true},{"text":"."}]},{"text":[{"text":"MarCom helps exchange by "},{"text":"generating awareness, fostering trust and driving purchase intent","bold":true},{"text":". Exchange is a "},{"text":"reciprocal creation of value","bold":true},{"text":" benefiting both organisation and customers. Partnerships between brands and consumers, and between firms in distribution channels, are vital to MarCom."}]},{"text":[{"text":"UVP/USP example:","bold":true},{"text":" Domino's Pizza positions itself as delivering the newest and hottest pizza faster than rivals, in only "},{"text":"30 minutes","bold":true},{"text":"."}]},{"text":[{"text":"This process is sometimes introduced as \"six stages\"; learn each step's name and job in the order above. Step 8 tracks outcomes; step 9 compares with objectives and "},{"text":"adjusts","bold":true},{"text":"."}]}]}]},{"number":"1.5","title":"Roles and objectives of marketing communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary objective:","bold":true},{"text":" to "},{"text":"increase sales volume","bold":true},{"text":" through "},{"text":"persuasive, informative and positive messages","bold":true},{"text":"."}]},{"text":[{"text":"MarCom objectives are "},{"text":"long-term goals","bold":true},{"text":" that aim to "},{"text":"boost the brand's value over time","bold":true},{"text":"."}]},{"text":[{"text":"9 specific objectives:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Increase brand awareness:","bold":true},{"text":" make people know the business and its products exist (broadcast commercials or print ads); a top priority for new and existing firms."}]},{"text":[{"text":"Change attitudes:","bold":true},{"text":" correct mistaken beliefs spread about the business or its products."}]},{"text":[{"text":"Influence purchase intent:","bold":true},{"text":" compelling ads that focus on "},{"text":"superior benefits to users compared with competitors","bold":true},{"text":"."}]},{"text":[{"text":"Stimulate trial purchase and repeat patronage:","bold":true},{"text":" free trials or samples take the risk off so customers experience the brand."}]},{"text":[{"text":"Drive brand switching:","bold":true},{"text":" get buyers of competing products to switch to your brand."}]},{"text":[{"text":"Connect companies with consumers:","bold":true},{"text":" convey messages so the brand is better known and trusted."}]},{"text":[{"text":"Build a brand image:","bold":true},{"text":" branding is not built in a short time."}]},{"text":[{"text":"Conduct research for the company:","bold":true},{"text":" connect company stakeholders with the market by "},{"text":"reading trend movements","bold":true},{"text":" in the sector."}]},{"text":[{"text":"Do direct selling:","bold":true},{"text":" market products directly into end users' hands to build trust."}]}]}]},{"text":[{"text":"5 important roles:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Building brand awareness:","bold":true},{"text":" customers know the organisation exists and what it offers."}]},{"text":[{"text":"Maintaining customer loyalty:","bold":true},{"text":" customers develop a positive bond with the company and its brands."}]},{"text":[{"text":"Creating demand for products and services:","bold":true},{"text":" improved or innovative products are not enough; people need to know they exist to buy them."}]},{"text":[{"text":"Shortening the sales cycle:","bold":true},{"text":" by better understanding customer needs, buying motivations, influences and processes, and using this insight when engaging consumers."}]},{"text":[{"text":"Highlighting a competitive edge:","bold":true},{"text":" in a crowded 21st-century marketplace, points of differentiation must be shared with the public to enhance competitive advantage."}]}]}]},{"text":[{"text":"3 other specific roles:","bold":true},{"text":" (i) influences consumer behaviour to drive sales; (ii) engages customers at various points along the buying journey; (iii) integrates all marketing tools to achieve seamless communication."}]},{"text":[{"text":"DRIP (Fill):","bold":true},{"text":" "},{"text":"D","bold":true},{"text":"ifferentiate, "},{"text":"R","bold":true},{"text":"einforce, "},{"text":"I","bold":true},{"text":"nform, "},{"text":"P","bold":true},{"text":"ersuade."}]},{"text":[{"text":"Kotler's three classic aims:","bold":true},{"text":" "},{"text":"inform, persuade, remind","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"DRIP role"}],[{"text":"What it does"}],[{"text":"Example"}]],"rows":[[[{"text":"Differentiate"}],[{"text":"Shows how the brand differs from rivals"}],[{"text":"Highlighting a unique feature"}]],[[{"text":"Reinforce"}],[{"text":"Consolidates past messages and experiences; reminds and reassures existing buyers"}],[{"text":"A well-known drink reminding loyal buyers of good times with it"}]],[[{"text":"Inform"}],[{"text":"Makes people aware of the offer"}],[{"text":"A new product launch"}]],[[{"text":"Persuade"}],[{"text":"Encourages a desired action, such as buying"}],[{"text":"\"Buy now\" offers"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Matching scenarios (the commonest question style):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A new fintech app runs radio and print ads so people know it exists: "},{"text":"increase brand awareness","bold":true},{"text":"."}]},{"text":[{"text":"A bottled-water brand hit by false rumours shows its NAFDAC approval and factory tests: "},{"text":"change attitudes","bold":true},{"text":"."}]},{"text":[{"text":"Free sample sachets of a new cream at a Lagos mall: "},{"text":"stimulate trial purchase","bold":true},{"text":"."}]},{"text":[{"text":"Bonus data for customers of rival networks who port their lines: "},{"text":"drive brand switching","bold":true},{"text":"."}]},{"text":[{"text":"Birthday messages and loyalty-point updates from an Abuja supermarket: "},{"text":"maintaining customer loyalty","bold":true},{"text":" (a role)."}]}]}]},{"text":[{"text":"Trap: a familiar brand \"reminding\" loyal buyers of good experiences is "},{"text":"Reinforce","bold":true},{"text":" under DRIP (Kotler would say "},{"text":"remind","bold":true},{"text":")."}]},{"text":[{"text":"Fixing machinery, setting the minimum wage, cutting production costs or replacing a quality product are "},{"text":"never","bold":true},{"text":" MarCom objectives or roles."}]},{"text":[{"text":"Strategically, MarCom "},{"text":"enhances brand equity, fosters loyalty and drives repeat purchases","bold":true},{"text":", and influences purchasing patterns through "},{"text":"targeted messaging","bold":true},{"text":". Its primary function is to "},{"text":"inform, persuade and remind","bold":true},{"text":" customers to sustain engagement with the brand."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing: exchange relationships; Baker = profitable customer relationships; Kotler and Armstrong = create value, capture value in return."}]},{"text":[{"text":"Communication = using words, sounds or visual cues to supply information to one or more people."}]},{"text":[{"text":"MarCom = channels and tools to communicate the necessary message to the target group; no universal definition."}]},{"text":[{"text":"4 types of communication: one-to-many (most original), many-to-one (email reply), one-to-one (most intensive), many-to-many (chat rooms, blogs)."}]},{"text":[{"text":"Seven Ps (formerly Four Ps): product, price, promotion (plus positioning), place, people, process, packaging."}]},{"text":[{"text":"Printing press (15th c.), first print ads (17th c.), radio (1920s), TV dominant (1950s), Think Small (1960s), Hotmail viral (1996), social media two-way (early 2000s); IMC = multiple channels, one unified message."}]},{"text":[{"text":"5 conditions for exchange; exchange process yields a transaction; nine-step MarCom process from target audience to control measures."}]},{"text":[{"text":"Primary objective: increase sales volume; 9 specific objectives; 5 main roles plus 3 others; DRIP = Differentiate, Reinforce, Inform, Persuade."}]}]}],"theory":{"itemId":"b1e247aa-afc5-562a-bdb7-676783d6166e","question":[{"type":"paragraph","text":[{"text":"State the five conditions for an exchange to take place and explain which of them shows why marketing communication is needed."}]}]},"practice":[{"topic":"Nature, Types, Roles and Objectives of Marketing Communication","named":false}]}},{"itemId":"73884fc6-797d-56d4-abb1-d1798a443445","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:2","parentItemId":null,"revision":1,"payload":{"title":"Models of Marketing Communication and MarCom Planning","body":"The basic communication model and its elements; linear, interactional and transactional views; one-step, two-step and multi-step flow; the response hierarchy models (AIDA, Lavidge and Steiner, innovation-adoption, information processing, DAGMAR); the process of marketing communications and SMART objectives; SOSTAC; the MCPF and its seven elements; push, pull and profile strategies; budgeting methods.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The basic communication model and its elements; linear, interactional and transactional views; one-step, two-step and multi-step flow; the response hierarchy models (AIDA, Lavidge and Steiner, innovation-adoption, information processing, DAGMAR); the process of marketing communications and SMART objectives; SOSTAC; the MCPF and its seven elements; push, pull and profile strategies; budgeting methods."}],"lessons":[{"number":"2.1","title":"The basic communication model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Model of marketing communication:","bold":true},{"text":" a simplified picture of how a persuasive message passes from a sender to a receiver. Its usefulness lies in its ability to "},{"text":"explain how persuasive messages are transmitted and received","bold":true},{"text":", so a marketer can see where communication can break down."}]},{"text":[{"text":"Basic elements:","bold":true},{"text":" "},{"text":"sender, encoded message, medium (channel), receiver and feedback","bold":true},{"text":", plus noise."}]},{"text":[{"text":"Basic sequence:","bold":true},{"text":" "},{"text":"Sender - encoding - message/medium - decoding - receiver - feedback.","bold":true}]}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Sender (source)"}],[{"text":"The person or organisation with an idea to share, e.g. the brand"}]],[[{"text":"Encoding"}],[{"text":"Turning the sender's ideas into a message made of words, pictures, symbols or sounds"}]],[[{"text":"Message"}],[{"text":"The set of symbols the sender transmits"}]],[[{"text":"Medium (channel)"}],[{"text":"The path that carries the message: TV, radio, press, social media, a salesperson"}]],[[{"text":"Decoding"}],[{"text":"The receiver interpreting the symbols in the message to give it meaning"}]],[[{"text":"Receiver"}],[{"text":"The person who gets and decodes the message (the target audience)"}]],[[{"text":"Response"}],[{"text":"What the receiver does after exposure"}]],[[{"text":"Feedback"}],[{"text":"The part of the response that goes back to the sender"}]],[[{"text":"Noise"}],[{"text":"Any unplanned interference or distortion that stops the receiver getting the message as intended"}]],[[{"text":"Field of experience"}],[{"text":"The experiences, attitudes, values and perceptions each party brings; understanding is greatest where the two fields overlap"}]]]},{"type":"paragraph","text":[{"text":"Three views of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Linear (Shannon and Weaver, 1949):","bold":true},{"text":" a "},{"text":"one-way","bold":true},{"text":" flow from sender, through encoding, message and channel, to decoding by a receiver. "},{"text":"Weakness:","bold":true},{"text":" it treats the receiver as "},{"text":"passive","bold":true},{"text":" and ignores feedback."}]},{"text":[{"text":"Interactional (Schramm):","bold":true},{"text":" two-way; sender and receiver take turns, both encode and decode; adds "},{"text":"feedback","bold":true},{"text":" and "},{"text":"field of experience","bold":true},{"text":"."}]},{"text":[{"text":"Transactional:","bold":true},{"text":" both parties send and receive "},{"text":"at the same time","bold":true},{"text":", so meaning is created jointly within a shared context."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sound model stresses "},{"text":"feedback as a way of refining the effectiveness of messages","bold":true},{"text":". Without feedback, the firm cannot tell whether its message was understood."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" after hearing a radio jingle for a new noodle brand, a listener calls the toll-free line to ask where to buy it. The call is "},{"text":"feedback","bold":true},{"text":", not the channel. Likes, comments, complaints, sales figures and survey answers are also feedback."}]},{"text":[{"text":"Noise examples:","bold":true},{"text":" a power cut during a TV advert, traffic noise drowning a radio jingle, a rival's advert in the same break, a blurred billboard, a receiver who is distracted."}]},{"text":[{"text":"Field of experience trap:","bold":true},{"text":" a Lagos bank uses slang and references its young target customers in Ibadan do not understand, so the advert fails. The cause is "},{"text":"too little overlap between the fields of experience","bold":true},{"text":" of sender and receiver, not noise. The fix is to encode in words and images the audience shares."}]},{"text":[{"text":"Exams swap encoding and decoding. Remember: the "},{"text":"sender encodes","bold":true},{"text":", the "},{"text":"receiver decodes","bold":true},{"text":". Options that put the receiver first, or decoding before the medium, are wrong."}]},{"text":[{"text":"The basic model is a "},{"text":"communication","bold":true},{"text":" model. Do not confuse it with the 4Ps (product, price, place, promotion), STP (segmentation, targeting, positioning) or SWOT."}]}]}]},{"number":"2.2","title":"Flow models: one-step, two-step and multi-step","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"One-step flow (hypodermic needle or magic bullet):","bold":true},{"text":" the mass media reach the audience "},{"text":"directly","bold":true},{"text":", with "},{"text":"no opinion leaders","bold":true},{"text":" in between. Every receiver is assumed to take in the message the same way."}]},{"text":[{"text":"Two-step flow (Lazarsfeld and colleagues; later Katz and Lazarsfeld):","bold":true},{"text":" messages flow from the "},{"text":"mass media to opinion leaders","bold":true},{"text":", who then pass them on (with their own interpretation) to "},{"text":"opinion followers","bold":true},{"text":"."}]},{"text":[{"text":"Multi-step flow:","bold":true},{"text":" develops the two-step model by recognising that information can flow "},{"text":"in several directions among the media, opinion leaders and opinion followers","bold":true},{"text":". Followers also use the media directly, and opinion leaders also seek advice from others."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Opinion leader:","bold":true},{"text":" a person within a group whose views on a product or topic others respect and copy."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Key difference:","bold":true},{"text":" in the one-step model the media reach the audience directly; in the two-step model "},{"text":"opinion leaders stand in between","bold":true},{"text":". Neither model's distinguishing feature is feedback."}]},{"text":[{"text":"Nigerian application:","bold":true},{"text":" a skincare brand sends free products to a well-known Nigerian beauty blogger, hoping her followers will copy her recommendations. This relies on the "},{"text":"two-step flow","bold":true},{"text":". Influencer marketing on Instagram and TikTok, and telecoms such as MTN or Glo using celebrity ambassadors, follow the same logic."}]},{"text":[{"text":"The two-step idea came from Lazarsfeld, Berelson and Gaudet's study of how American voters decided in the 1940 election: personal influence mattered more than media alone."}]}]}]},{"number":"2.3","title":"Response hierarchy (hierarchy-of-effects) models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hierarchy-of-effects (response hierarchy) models:","bold":true},{"text":" models that assume buyers pass through a "},{"text":"set sequence of stages, from awareness to purchase","bold":true},{"text":", in response to marketing communication."}]},{"text":[{"text":"Three components (learn, feel, do):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cognitive (thinking):","bold":true},{"text":" what the receiver "},{"text":"knows or thinks","bold":true},{"text":", e.g. awareness, knowledge."}]},{"text":[{"text":"Affective (feeling):","bold":true},{"text":" what the receiver "},{"text":"feels","bold":true},{"text":", e.g. liking, preference."}]},{"text":[{"text":"Conative (behavioural):","bold":true},{"text":" what the receiver "},{"text":"does","bold":true},{"text":", e.g. trial, purchase."}]}]}]}]},{"type":"table","header":[[{"text":"Model (author)"}],[{"text":"Cognitive"}],[{"text":"Affective"}],[{"text":"Conative (behaviour)"}]],"rows":[[[{"text":"AIDA (E. St. Elmo Lewis)"}],[{"text":"Attention"}],[{"text":"Interest, Desire"}],[{"text":"Action"}]],[[{"text":"Hierarchy of effects (Lavidge and Steiner, 1961)"}],[{"text":"Awareness, Knowledge"}],[{"text":"Liking, Preference"}],[{"text":"Conviction, Purchase"}]],[[{"text":"Innovation-adoption (Rogers)"}],[{"text":"Awareness"}],[{"text":"Interest, Evaluation"}],[{"text":"Trial, Adoption"}]],[[{"text":"Information processing (McGuire)"}],[{"text":"Presentation, Attention, Comprehension"}],[{"text":"Yielding, Retention"}],[{"text":"Behaviour"}]],[[{"text":"DAGMAR (Russell Colley, 1961)"}],[{"text":"Awareness, Comprehension"}],[{"text":"Conviction"}],[{"text":"Action"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"AIDA","bold":true},{"text":" = "},{"text":"A","bold":true},{"text":"ttention, "},{"text":"I","bold":true},{"text":"nterest, "},{"text":"D","bold":true},{"text":"esire, "},{"text":"A","bold":true},{"text":"ction (4 stages). Desire comes immediately after Interest."}]},{"text":[{"text":"Lavidge and Steiner","bold":true},{"text":" (6 stages): "},{"text":"awareness, knowledge, liking, preference, conviction, purchase.","bold":true}]},{"text":[{"text":"Innovation-adoption","bold":true},{"text":" (5 stages): "},{"text":"awareness, interest, evaluation, trial, adoption.","bold":true}]},{"text":[{"text":"Information processing","bold":true},{"text":" (6 stages): presentation, attention, comprehension, yielding, retention, behaviour."}]},{"text":[{"text":"DAGMAR","bold":true},{"text":" = "},{"text":"D","bold":true},{"text":"efining "},{"text":"A","bold":true},{"text":"dvertising "},{"text":"G","bold":true},{"text":"oals for "},{"text":"M","bold":true},{"text":"easured "},{"text":"A","bold":true},{"text":"dvertising "},{"text":"R","bold":true},{"text":"esults, by "},{"text":"Russell Colley","bold":true},{"text":" (1961). Stages (ACCA): "},{"text":"awareness, comprehension, conviction, action.","bold":true}]},{"text":[{"text":"DAGMAR principle:","bold":true},{"text":" advertising objectives must be "},{"text":"specific and measurable","bold":true},{"text":", with a defined "},{"text":"target audience","bold":true},{"text":", a "},{"text":"benchmark","bold":true},{"text":" (starting point), the "},{"text":"degree of change","bold":true},{"text":" sought and a "},{"text":"time period","bold":true},{"text":". Objectives are communication tasks, not just sales."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"AIDA in practice:","bold":true},{"text":" a poster for a new Lagos gym uses bright colours and a bold headline so passers-by stop and look: "},{"text":"Attention","bold":true},{"text":". A \"Shop now - offer ends at midnight\" button on a Jumia-style advert: "},{"text":"Action","bold":true},{"text":". Showing how tasty a new Indomie flavour is builds "},{"text":"Interest","bold":true},{"text":"; showing someone enjoying it and saying \"you deserve this\" builds "},{"text":"Desire","bold":true},{"text":"."}]},{"text":[{"text":"Kotler's buyer-readiness stages","bold":true},{"text":" are the same six as Lavidge and Steiner. Exams swap the order of liking and knowledge, or of preference and conviction: knowledge always comes before liking, and preference before conviction."}]},{"text":[{"text":"Some writers place conviction in the affective stage rather than the conative; in every version, "},{"text":"liking and preference are affective","bold":true},{"text":" and "},{"text":"purchase is conative","bold":true},{"text":"."}]},{"text":[{"text":"Do not mix up the stage lists: \"awareness, comprehension, conviction, action\" is DAGMAR; \"awareness, interest, evaluation, trial, adoption\" is innovation-adoption; \"attention, interest, desire, action\" is AIDA. \"Exposure, reception, cognitive response ... behaviour\" belongs to a different communications-response sequence, not innovation-adoption."}]},{"text":[{"text":"DAGMAR example:","bold":true},{"text":" \"Raise awareness of our new juice among Lagos undergraduates from 20% to 45% within six months.\" Target audience = Lagos undergraduates; benchmark = 20%; degree of change = 25 percentage points; time period = six months."}]},{"text":[{"text":"Criticism of hierarchy models:","bold":true},{"text":" consumers "},{"text":"do not always pass through the stages in a fixed order","bold":true},{"text":". With low-involvement or impulse buys (a sachet of Pure Water, a Gala at a traffic jam), people may buy first and form attitudes afterwards (do-feel-learn or learn-do-feel). The models also make it hard to link one advert to one stage, and they ignore the effect of other influences such as friends and price."}]}]}]},{"number":"2.4","title":"Developing a marketing communications plan","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why a plan is needed:","bold":true},{"text":" it sets out "},{"text":"in a logical order what the firm wants to achieve with communication and how","bold":true},{"text":", so activities are coordinated and can be evaluated. It does "},{"text":"not","bold":true},{"text":" replace the marketing plan or guarantee success."}]},{"text":[{"text":"An effective plan requires "},{"text":"setting measurable goals, selecting appropriate tools and evaluating outcomes","bold":true},{"text":"."}]},{"text":[{"text":"A well-executed plan ensures "},{"text":"integration and consistency across all communication touchpoints","bold":true},{"text":" (one clear message across every tool)."}]},{"text":[{"text":"A "},{"text":"foundational element","bold":true},{"text":" is formulating "},{"text":"precise, actionable and time-bound objectives","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Process of marketing communications (in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the target audience","bold":true},{"text":" (first stage): focus on distinct segments, not everybody."}]},{"text":[{"text":"Determine the company's unique value (selling) proposition (UVP or USP):","bold":true},{"text":" what makes the business stand out from rivals."}]},{"text":[{"text":"Bring the solution to customers' queries:","bold":true},{"text":" strategies that answer customers' pain points with the product."}]},{"text":[{"text":"Select channels to deliver the brand message:","bold":true},{"text":" based on objectives and customers' choices."}]},{"text":[{"text":"Budget allocation:","bold":true},{"text":" how much to spend on each channel."}]},{"text":[{"text":"Message development:","bold":true},{"text":" crafting key messages that resonate with the audience."}]},{"text":[{"text":"Execution:","bold":true},{"text":" implementing the chosen plan."}]},{"text":[{"text":"Evaluate and measure the results:","bold":true},{"text":" track outcomes after the campaign runs."}]},{"text":[{"text":"Develop control measures:","bold":true},{"text":" measure effectiveness against objectives and make adjustments."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SMART objectives:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific, "},{"text":"M","bold":true},{"text":"easurable, "},{"text":"A","bold":true},{"text":"chievable, "},{"text":"R","bold":true},{"text":"ealistic, "},{"text":"T","bold":true},{"text":"ime-bound."}]},{"text":[{"text":"SOSTAC","bold":true},{"text":" (P.R. Smith): "},{"text":"S","bold":true},{"text":"ituation, "},{"text":"O","bold":true},{"text":"bjectives, "},{"text":"S","bold":true},{"text":"trategy, "},{"text":"T","bold":true},{"text":"actics, "},{"text":"A","bold":true},{"text":"ction, "},{"text":"C","bold":true},{"text":"ontrol."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"USP example:","bold":true},{"text":" Domino's Pizza positioning itself as the business that delivers the newest and hottest pizza faster than competitors, in only 30 minutes, is its "},{"text":"unique value (selling) proposition","bold":true},{"text":". A Nigerian parallel: a bank promising account opening in five minutes on its app."}]},{"text":[{"text":"Count trap:","bold":true},{"text":" this process is often introduced as \"six stages\", yet nine steps are named above. Learn the order: the first is "},{"text":"identifying the target audience","bold":true},{"text":", and the last two are evaluating results and developing control measures."}]},{"text":[{"text":"Good objective:","bold":true},{"text":" \"Increase awareness of our new brand among undergraduates in Lagos from 20% to 45% within six months\" is well written because it is "},{"text":"specific, measurable and time-bound, with a clear target audience and benchmark","bold":true},{"text":"."}]},{"text":[{"text":"Bad planning habits","bold":true},{"text":" exams offer as distractors: choosing media first and setting objectives after the campaign; copying a competitor's plan without audience analysis; spending equally on every tool; repeating last year's plan unchanged; leaving objectives undefined; choosing the cheapest medium regardless of audience; making each tool send a different, unrelated message."}]},{"text":[{"text":"SOSTAC","bold":true},{"text":" stages: Situation = where are we now; Objectives = where do we want to be; Strategy = how do we get there overall; Tactics = the details (which tools); Action = who does what and when; Control = how we measure and adjust. Smith adds the "},{"text":"3Ms","bold":true},{"text":": men (people), money, minutes (time)."}]},{"text":[{"text":"Kotler's steps for effective communication:","bold":true},{"text":" identify the target audience; determine communication objectives (buyer-readiness stage); design the message; choose the media; select the message source; collect feedback."}]}]}]},{"number":"2.5","title":"The Marketing Communications Planning Framework (MCPF)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MCPF (Fill):","bold":true},{"text":" a "},{"text":"sequence of linked stages that guides the development of a marketing communications plan","bold":true},{"text":". It provides a "},{"text":"structured approach for aligning communication strategies with business objectives","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The seven elements in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Context analysis","bold":true},{"text":" (first): customer, business, internal and external contexts."}]},{"text":[{"text":"Communication objectives:","bold":true},{"text":" derived from the "},{"text":"corporate and marketing objectives","bold":true},{"text":"; SMART."}]},{"text":[{"text":"Marketing communications strategy:","bold":true},{"text":" the overall approach: push, pull or profile, and positioning."}]},{"text":[{"text":"Coordinated communications mix:","bold":true},{"text":" "},{"text":"choosing and combining the tools, media and messages so they work together","bold":true},{"text":"."}]},{"text":[{"text":"Resources:","bold":true},{"text":" the "},{"text":"budget, people and time","bold":true},{"text":" needed to carry out the plan."}]},{"text":[{"text":"Scheduling and implementation:","bold":true},{"text":" "},{"text":"when each activity will happen and in what order","bold":true},{"text":"."}]},{"text":[{"text":"Evaluation and control","bold":true},{"text":" (last): measuring results against objectives and adjusting."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedback:","bold":true},{"text":" results from evaluation "},{"text":"feed back into earlier stages","bold":true},{"text":" so that future plans improve."}]}]},{"type":"paragraph","text":[{"text":"Four contexts examined in context analysis:","bold":true}]},{"type":"table","header":[[{"text":"Context"}],[{"text":"What it covers"}]],"rows":[[[{"text":"Customer"}],[{"text":"Buyers' needs, behaviour, segments, how they decide"}]],[[{"text":"Business"}],[{"text":"Competitors, the market, the firm's marketing strategy"}]],[[{"text":"Internal"}],[{"text":"The firm's resources, culture, finance, skills"}]],[[{"text":"External (wider environment)"}],[{"text":"Political, economic, social, technological, legal factors (PESTEL)"}]]]},{"type":"paragraph","text":[{"text":"Three strategies (3Ps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Pull:","bold":true},{"text":" aimed at "},{"text":"end-user consumers","bold":true},{"text":", to encourage them to ask for and buy the product, so it is \"pulled\" through the channel."}]},{"text":[{"text":"Push:","bold":true},{"text":" aimed at "},{"text":"wholesalers and retailers","bold":true},{"text":" (the trade), to encourage them to stock and promote the product."}]},{"text":[{"text":"Profile:","bold":true},{"text":" aimed at "},{"text":"a wide range of stakeholders","bold":true},{"text":", to build the organisation's "},{"text":"corporate image and reputation","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Context analysis is the foundation","bold":true},{"text":" because it provides the information on which objectives, strategy and the mix are based. Final evaluation of results is "},{"text":"not","bold":true},{"text":" part of context analysis; it is the last stage."}]},{"text":[{"text":"External context example:","bold":true},{"text":" a Nigerian telecom firm studying new NCC regulations, inflation and changes in technology before a campaign is analysing the "},{"text":"external (wider environment) context","bold":true},{"text":"."}]},{"text":[{"text":"Strategy example:","bold":true},{"text":" \"Position our bank as the friendliest choice for students, using a pull strategy built mainly on social media\" is a "},{"text":"marketing communications strategy","bold":true},{"text":" statement."}]},{"text":[{"text":"Push example:","bold":true},{"text":" a detergent maker giving extra margins and display allowances to distributors and supermarkets in Kano. "},{"text":"Pull example:","bold":true},{"text":" heavy TV and social media adverts for Peak Milk so shoppers ask for it by name. "},{"text":"Profile example:","bold":true},{"text":" Dangote publicising its corporate social responsibility to investors, government and communities."}]},{"text":[{"text":"Control and evaluation example:","bold":true},{"text":" six weeks after launch, a Port Harcourt restaurant checks whether awareness rose to the target and adjusts its adverts where it fell short."}]},{"text":[{"text":"Order trap: some versions list scheduling before resources. What never changes is that "},{"text":"context analysis comes first, objectives come immediately after it, and evaluation and control come last","bold":true},{"text":". Anything such as \"recruitment of factory workers\" or \"deciding the corporate mission\" is "},{"text":"not","bold":true},{"text":" an MCPF stage."}]}]}]},{"number":"2.6","title":"Budgeting methods","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Affordable method:","bold":true},{"text":" spend whatever is left after all other costs and the profit target are covered."}]},{"text":[{"text":"Percentage-of-sales method:","bold":true},{"text":" budget = percentage x sales (past or forecast sales)."}]},{"text":[{"text":"Competitive parity method:","bold":true},{"text":" match competitors' spending, or the industry's ratio of promotion to sales."}]},{"text":[{"text":"Objective-and-task method:","bold":true},{"text":" set objectives, list the tasks needed to reach them, cost each task and add them up. Budget = sum of task costs. Considered the most logical method."}]},{"text":[{"text":"Arbitrary method:","bold":true},{"text":" management simply picks a figure."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Share of voice (SOV)","bold":true},{"text":" = brand's promotion spend / total category promotion spend x 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Percentage of sales:","bold":true},{"text":" sales ₦500 million, 4% rule. Budget = 0.04 x ₦500,000,000 = "},{"text":"₦20,000,000","bold":true},{"text":". Weakness: it treats sales as the cause of promotion rather than the result, so budgets fall when sales fall, exactly when more promotion may be needed."}]},{"text":[{"text":"Competitive parity:","bold":true},{"text":" the industry spends 5% of sales on promotion; your sales are ₦400 million. Budget = 0.05 x ₦400,000,000 = "},{"text":"₦20,000,000","bold":true},{"text":". Weakness: it assumes competitors know best and ignores your own objectives."}]},{"text":[{"text":"Objective-and-task:","bold":true},{"text":" to raise awareness from 20% to 45%, a firm needs TV ₦12m + radio ₦4.5m + social media ₦3m + campus sampling ₦2.5m. Budget = 12 + 4.5 + 3 + 2.5 = "},{"text":"₦22 million","bold":true},{"text":". Strength: spending is tied to objectives."}]},{"text":[{"text":"Affordable:","bold":true},{"text":" expected revenue ₦120m, all other costs ₦100m, profit target ₦15m. Promotion budget = 120 - 100 - 15 = "},{"text":"₦5 million","bold":true},{"text":". Weakness: promotion is treated as a leftover, not an investment."}]},{"text":[{"text":"Share of voice:","bold":true},{"text":" your brand spends ₦20m in a category where total spend is ₦80m. SOV = 20 / 80 x 100 = "},{"text":"25%","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic model: sender - encoding - message/medium - decoding - receiver - feedback, with noise; Schramm adds field of experience."}]},{"text":[{"text":"Linear model is one-way with a passive receiver; interactional adds feedback; transactional is simultaneous."}]},{"text":[{"text":"One-step: media direct to audience. Two-step: media - opinion leaders - followers. Multi-step: many directions."}]},{"text":[{"text":"AIDA: attention, interest, desire, action. Lavidge and Steiner: awareness, knowledge, liking, preference, conviction, purchase."}]},{"text":[{"text":"Innovation-adoption: awareness, interest, evaluation, trial, adoption. DAGMAR (Colley): awareness, comprehension, conviction, action."}]},{"text":[{"text":"Cognitive = think, affective = feel, conative = do."}]},{"text":[{"text":"MarCom process starts with identifying the target audience; objectives must be SMART; SOSTAC = situation, objectives, strategy, tactics, action, control."}]},{"text":[{"text":"MCPF: context analysis, objectives, strategy, coordinated mix, resources, scheduling and implementation, evaluation and control."}]},{"text":[{"text":"Pull = consumers; push = trade; profile = all stakeholders."}]},{"text":[{"text":"Budgets: affordable, percentage of sales, competitive parity, objective-and-task."}]}]}],"theory":{"itemId":"375505a3-1862-516c-b36b-c37951d4c922","question":[{"type":"paragraph","text":[{"text":"A Lagos snack maker had sales of ₦250 million last year and forecasts ₦300 million this year. It budgets 3% of sales for promotion. (a) Find the budget using past sales and using forecast sales. (b) If rivals together spend ₦36 million, what is the firm's share of voice using the forecast-based budget?"}]}]},"practice":[{"topic":"Models of Marketing Communication and MarCom Planning","named":false}]}},{"itemId":"faab1a42-3d24-5ead-bf1a-9b7dba9b0e9b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:3","parentItemId":null,"revision":1,"payload":{"title":"MarCom Context, Mix and Selection Criteria","body":"The four contexts of marketing communication; the tools and media of the marketing communications mix and what each does; strengths and weaknesses of each tool and the four comparison criteria; the four groups of factors for selecting the mix, plus push, pull and profile strategies, product life cycle and buyer readiness; market segmentation as it applies to communication.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The four contexts of marketing communication; the tools and media of the marketing communications mix and what each does; strengths and weaknesses of each tool and the four comparison criteria; the four groups of factors for selecting the mix, plus push, pull and profile strategies, product life cycle and buyer readiness; market segmentation as it applies to communication."}],"lessons":[{"number":"3.1","title":"The marketing communication context","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communication context:","bold":true},{"text":" the circumstances, inside and outside the organisation, in which communication takes place and is interpreted. It is not just the words and pictures in an advert, the size of the budget or the price."}]},{"text":[{"text":"Context is analysed "},{"text":"before","bold":true},{"text":" a campaign is planned, so that tools, messages and media fit the situation."}]},{"text":[{"text":"The 4 contexts:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customer context:","bold":true},{"text":" the needs, perceptions, attitudes and decision-making process of the target segment; who the customers are, how they buy and how they use media."}]},{"text":[{"text":"Business context:","bold":true},{"text":" the organisation's corporate and marketing strategy, its brand and market position, and its competitors and market trends in the industry."}]},{"text":[{"text":"Internal context:","bold":true},{"text":" what is inside the organisation: budget and other resources, staff skills, culture and values, internal policies and procedures."}]},{"text":[{"text":"External context:","bold":true},{"text":" forces outside the organisation's control: political, economic, social and technological ("},{"text":"PEST","bold":true},{"text":") factors and the wider stakeholders (government, media, community, investors)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal vs external trap:","bold":true},{"text":" \"company policies and procedures\", \"organisation culture and values\" and \"staff appraisals\" are "},{"text":"internal","bold":true},{"text":". \"Competitive positioning and market trends\" are "},{"text":"outside","bold":true},{"text":" the organisation: in a two-way internal/external question, they are the "},{"text":"external","bold":true},{"text":" factor. In the four-context framework they sit under the business context, while PEST and wider stakeholders are the external context."}]},{"text":[{"text":"Example: a Kano food company finds it has a small promotion budget, few staff skilled in social media and a cautious culture. All three findings concern the firm itself, so they are the "},{"text":"internal context","bold":true},{"text":"."}]},{"text":[{"text":"Example: GTBank studying how young customers choose banking apps is analysing the "},{"text":"customer context","bold":true},{"text":"; studying new regulations or rising data costs is the "},{"text":"external context","bold":true},{"text":"."}]}]}]},{"number":"3.2","title":"The marketing communications mix: tools and media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communications mix:","bold":true},{"text":" a set of tools (disciplines) that can be used in various combinations and different degrees of intensity in order to communicate with a target audience. Its purpose is to reach and persuade the intended audience effectively across channels. The whole process of marketing is executed through it."}]},{"text":[{"text":"The 5 traditional (main) tools:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Advertising"}]},{"text":[{"text":"Sales promotion"}]},{"text":[{"text":"Personal selling"}]},{"text":[{"text":"Public relations (with publicity)"}]},{"text":[{"text":"Direct marketing"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Media:","bold":true},{"text":" the other part of the mix: the channels in which "},{"text":"time and space can be bought or used","bold":true},{"text":" to deliver messages to target audiences (TV, radio, press, outdoor, internet)."}]},{"text":[{"text":"Price, product design, distribution and inventory are "},{"text":"not","bold":true},{"text":" communication tools. Do not confuse the communications mix (tools) with the marketing mix (4 Ps: product, price, place, promotion). Promotion is the one P that the communications mix fills out."}]}]},{"type":"paragraph","text":[{"text":"Definitions of each tool","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advertising:","bold":true},{"text":" an "},{"text":"indirect, paid","bold":true},{"text":" method used by firms to inform customers about goods and services via television, radio, print media and online websites. One of the most widely used tools. Main job: build brand recognition and reinforce market presence through paid media."}]},{"text":[{"text":"Sales promotion:","bold":true},{"text":" aims to stimulate sales (business revenue) through "},{"text":"incentives, short-term discounts and other promotional offers","bold":true},{"text":", boosting sales and strengthening customer satisfaction. Forms: "},{"text":"coupons, rebates, paybacks, buy-one-get-one-free","bold":true},{"text":", price-offs, free samples, contests. Role: trigger "},{"text":"immediate","bold":true},{"text":" purchase."}]},{"text":[{"text":"Public relations (PR):","bold":true},{"text":" focuses on the firm's "},{"text":"reputation","bold":true},{"text":" through "},{"text":"unpaid or earned","bold":true},{"text":" communication (traditional media, social media, in-person engagement). Activities: "},{"text":"press releases, communication campaigns, crisis management","bold":true},{"text":", building positive relationships with media figures and other stakeholders. Role: enhance reputation and credibility through earned media."}]},{"text":[{"text":"Publicity:","bold":true},{"text":" promotes to the mass market like advertising "},{"text":"except that it is free","bold":true},{"text":". It appears in the news media's "},{"text":"editorial section","bold":true},{"text":" and is about "},{"text":"newsworthy","bold":true},{"text":" events. Most common forms: "},{"text":"news (press) releases, photos and feature stories","bold":true},{"text":"."}]},{"text":[{"text":"Personal selling:","bold":true},{"text":" the traditional method in which salespeople approach prospects directly and inform them about goods and services; "},{"text":"face-to-face","bold":true},{"text":" selling in which a salesperson uses skills and techniques to build personal relationships. Regarded as one of the "},{"text":"most reliable","bold":true},{"text":" modes because it is done "},{"text":"directly","bold":true},{"text":", orally face to face or in writing (emails, text messages)."}]},{"text":[{"text":"Direct marketing:","bold":true},{"text":" a "},{"text":"more personalised","bold":true},{"text":" form of communication through direct communication or distribution to "},{"text":"individuals","bold":true},{"text":", rather than generalised messages on mass media. Examples: emails, brochures, interactive consumer websites, telemarketing, catalogues, direct mail."}]}]},{"type":"paragraph","text":[{"text":"Other tools in the wider mix","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Events and experiences (sponsorship):","bold":true},{"text":" companies sponsor sports, entertainment, non-profit or community events to "},{"text":"reinforce their brand","bold":true},{"text":" in customers' minds and create a "},{"text":"long-term association","bold":true},{"text":" for brand exposure."}]},{"text":[{"text":"Interactive marketing:","bold":true},{"text":" customers "},{"text":"interact with the firm online","bold":true},{"text":" and get queries resolved online; the firm can show each customer what they chose or ordered in the recent past (Amazon is the classic example). This is the digital/interactive tool."}]},{"text":[{"text":"Word-of-mouth marketing:","bold":true},{"text":" customers "},{"text":"share their experiences","bold":true},{"text":" of goods and services they recently bought with peers and friends. One of the most widely practised methods."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" the pack itself communicates: brand name, colours, information, claims; often the last message seen before purchase."}]},{"text":[{"text":"Point of purchase (POP):","bold":true},{"text":" displays, shelf strips, posters and stands in the shop where the buying decision is made."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advertising vs publicity:","bold":true},{"text":" both reach the mass market, but advertising is "},{"text":"paid","bold":true},{"text":" and the firm controls the message; publicity is "},{"text":"not paid for","bold":true},{"text":" and appears as "},{"text":"news","bold":true},{"text":" chosen by editors. Exams swap these constantly."}]},{"text":[{"text":"PR vs publicity:","bold":true},{"text":" PR is the broader management of reputation and relationships with all stakeholders; publicity is one output of PR (the free news coverage)."}]},{"text":[{"text":"Direct marketing vs advertising:","bold":true},{"text":" direct marketing speaks to "},{"text":"selected individuals","bold":true},{"text":" in a personalised way; advertising speaks to the general public."}]},{"text":[{"text":"Scenario practice:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos water company, after an online rumour of contamination, holds a press conference, issues a press release and invites journalists on a factory tour: "},{"text":"public relations","bold":true},{"text":" (crisis management)."}]},{"text":[{"text":"A Surulere supermarket offers \"buy two packs of noodles, get a third free, this weekend only\": "},{"text":"sales promotion","bold":true},{"text":" (short-term incentive)."}]},{"text":[{"text":"An Ikeja furniture company mails brochures, each addressed by name with a reply form, to 2,000 customers on its database: "},{"text":"direct marketing","bold":true},{"text":"."}]},{"text":[{"text":"A personalised email offer to customers on a mailing list: "},{"text":"direct marketing","bold":true},{"text":"."}]},{"text":[{"text":"A telecom company such as MTN or Glo pays to put its name, logo, jerseys and banners on a university inter-faculty football competition for the season: "},{"text":"events and experiences (sponsorship)","bold":true},{"text":"."}]},{"text":[{"text":"Jumia answering customer questions online and showing each buyer their recent orders: "},{"text":"interactive marketing","bold":true},{"text":"."}]}]}]},{"text":[{"text":"A press release is "},{"text":"not","bold":true},{"text":" sales promotion; a 30-second TV commercial is "},{"text":"advertising","bold":true},{"text":", not PR."}]}]}]},{"number":"3.3","title":"Strengths, weaknesses and the comparison criteria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tools are compared on "},{"text":"4 criteria:","bold":true},{"text":" "},{"text":"communication effectiveness, credibility, cost and control","bold":true},{"text":". (Not SWOT, not the 4 Ps, not AIDA.)"}]},{"text":[{"text":"Absolute cost:","bold":true},{"text":" the total bill paid. "},{"text":"Relative cost (cost per contact):","bold":true},{"text":" total cost divided by the number of people reached."}]},{"text":[{"text":"Formulas:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = total cost ÷ number of people reached"}]},{"text":[{"text":"Cost per thousand (CPM) = (total cost ÷ audience reached) × 1,000"}]}]}]}]},{"type":"table","header":[[{"text":"Tool"}],[{"text":"Main strengths"}],[{"text":"Main weaknesses"}]],"rows":[[[{"text":"Advertising"}],[{"text":"Reaches a large, geographically dispersed audience at a "},{"text":"low cost per contact","bold":true},{"text":"; firm controls message, timing and media; repeats message; builds image"}],[{"text":"High absolute cost","bold":true},{"text":" (TV); largely "},{"text":"one-way and impersonal","bold":true},{"text":", cannot adapt to each person's questions; low credibility (seen as biased); clutter"}]],[[{"text":"Sales promotion"}],[{"text":"Quick, measurable sales boost; encourages trial and brand switching; attracts attention"}],[{"text":"Effects mainly "},{"text":"short-term","bold":true},{"text":"; buyers may "},{"text":"wait for deals","bold":true},{"text":"; can cheapen the brand; little help in building loyalty"}]],[[{"text":"Public relations and publicity"}],[{"text":"Highest credibility","bold":true},{"text":" (third party, such as the news media, delivers it); low cost; reaches people who avoid adverts"}],[{"text":"Least control","bold":true},{"text":": editors decide whether, when and how the story appears; no guarantee of coverage or immediate sales"}]],[[{"text":"Personal selling"}],[{"text":"Two-way","bold":true},{"text":", immediate feedback; tailored to each customer's needs; can answer objections and close the sale; builds relationships"}],[{"text":"Highest cost per contact","bold":true},{"text":"; reaches relatively "},{"text":"few","bold":true},{"text":" people; depends on salesperson quality"}]],[[{"text":"Direct marketing"}],[{"text":"Personalised and targeted; responses easily "},{"text":"measured","bold":true},{"text":"; private from competitors"}],[{"text":"Seen as intrusive "},{"text":"\"junk\"","bold":true},{"text":" mail, calls or emails; needs a good database; can be costly per contact"}]],[[{"text":"Sponsorship"}],[{"text":"Long-term brand association; reaches fans emotionally"}],[{"text":"Hard to measure; little control over the event's image"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Quick-fire rules exams use:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most "},{"text":"credible","bold":true},{"text":": public relations (publicity)."}]},{"text":[{"text":"Least control","bold":true},{"text":": public relations (publicity)."}]},{"text":[{"text":"Highest cost per contact","bold":true},{"text":": personal selling."}]},{"text":[{"text":"Greatest "},{"text":"two-way interaction","bold":true},{"text":" and immediate feedback: personal selling."}]},{"text":[{"text":"Low cost per contact, wide reach","bold":true},{"text":": advertising."}]},{"text":[{"text":"Short-term sales boost","bold":true},{"text":": sales promotion."}]}]}]},{"text":[{"text":"Worked example: high absolute cost, low cost per contact.","bold":true},{"text":" A prime-time TV spot package costs ₦3,000,000 and reaches 6,000,000 viewers."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = ₦3,000,000 ÷ 6,000,000 = ₦0.50 per viewer."}]},{"text":[{"text":"CPM = ₦0.50 × 1,000 = ₦500 per thousand viewers."}]},{"text":[{"text":"The total bill (₦3m) is large, but spread across a huge audience the cost per person is tiny. That is what \"high absolute cost, low cost per contact\" means."}]}]}]},{"text":[{"text":"Worked example: personal selling.","bold":true},{"text":" A sales representative costs the firm ₦600,000 a month (salary, transport, allowances) and makes 120 calls."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = ₦600,000 ÷ 120 = ₦5,000 per call."}]},{"text":[{"text":"Each sales call costs ₦5,000 ÷ ₦0.50 = 10,000 times as much as one TV contact. In return, each call is two-way, tailored and can close a sale."}]}]}]},{"text":[{"text":"Worked example: direct marketing cost per response.","bold":true},{"text":" A firm mails 2,000 brochures at ₦750 each and 3% reply."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total cost = 2,000 × ₦750 = ₦1,500,000."}]},{"text":[{"text":"Replies = 3% × 2,000 = 60."}]},{"text":[{"text":"Cost per response = ₦1,500,000 ÷ 60 = ₦25,000. Being able to count replies like this is why direct marketing is called measurable."}]}]}]},{"text":[{"text":"Small budget, wide coverage:","bold":true},{"text":" a new Yaba fashion start-up with little money gains most cheaply by sending a "},{"text":"news release about an interesting launch event","bold":true},{"text":" to local media (publicity). National TV, league sponsorship or a large sales force are far too costly."}]},{"text":[{"text":"Trap: advertising does "},{"text":"not","bold":true},{"text":" give the firm \"no control\" (it gives high control) and does "},{"text":"not","bold":true},{"text":" have a high cost per person reached."}]}]}]},{"number":"3.4","title":"Selecting the mix: factors, strategies, PLC and buyer readiness","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selection criteria","bold":true},{"text":" are used to "},{"text":"identify and prioritise the tools that will be most effective","bold":true},{"text":" for the audience and the objectives. They do "},{"text":"not","bold":true},{"text":" mean equal budget shares, copying competitors, or dropping objectives."}]},{"text":[{"text":"Factors influencing the choice of mix (and how often each tool is used) fall into "},{"text":"4 groups:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"the amount and complexity of product information to be communicated"}]},{"text":[{"text":"the stage of the product in the product life cycle"}]},{"text":[{"text":"product type and unit price"}]}]}]},{"text":[{"text":"Customer related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"characteristics of the target market"}]},{"text":[{"text":"type of buying decision"}]}]}]},{"text":[{"text":"Organisation related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"marketing channel adopted"}]},{"text":[{"text":"branding strategies"}]},{"text":[{"text":"budget"}]}]}]},{"text":[{"text":"Competition and situation related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"visibility of the firm and its political, legal and social environment"}]},{"text":[{"text":"impact of competition"}]}]}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Push strategy:","bold":true},{"text":" communication (personal selling, trade promotions, extra margins, display allowances) is directed at "},{"text":"channel members","bold":true},{"text":" so that they stock and promote the product to end users."}]},{"text":[{"text":"Pull strategy:","bold":true},{"text":" communication (advertising, consumer promotions) is directed at "},{"text":"final consumers","bold":true},{"text":" so that they ask retailers for the product, and retailers then order from the manufacturer."}]},{"text":[{"text":"Profile strategy:","bold":true},{"text":" communication aimed at a "},{"text":"wide range of stakeholders","bold":true},{"text":" (investors, government, local community, media) to build "},{"text":"corporate reputation","bold":true},{"text":", not to move products through the channel."}]}]},{"type":"table","header":[[{"text":"PLC stage"}],[{"text":"Communication emphasis"}]],"rows":[[[{"text":"Introduction"}],[{"text":"Advertising and publicity to build "},{"text":"awareness","bold":true},{"text":"; sales promotion (samples, coupons) to encourage "},{"text":"trial","bold":true},{"text":"; personal selling to win distributors"}]],[[{"text":"Growth"}],[{"text":"Advertising and publicity continue to build preference; word of mouth spreads; less need for promotion incentives"}]],[[{"text":"Maturity"}],[{"text":"Sales promotion","bold":true},{"text":" becomes relatively more important; reminder and persuasive advertising against intense competition"}]],[[{"text":"Decline"}],[{"text":"Promotion "},{"text":"reduced to a low level","bold":true},{"text":"; some "},{"text":"reminder advertising","bold":true},{"text":" kept; publicity and selling cut back"}]]]},{"type":"paragraph","text":[{"text":"Buyer readiness stages:","bold":true}]},{"type":"table","header":[[{"text":"Stage"}],[{"text":"Most cost-effective tools"}]],"rows":[[[{"text":"Awareness and knowledge"}],[{"text":"Advertising and public relations (publicity)"}]],[[{"text":"Liking, preference and conviction"}],[{"text":"Personal selling (advertising helps less)"}]],[[{"text":"Purchase (ordering, closing)"}],[{"text":"Personal selling and sales promotion"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification traps:","bold":true},{"text":" budget is an "},{"text":"organisation","bold":true},{"text":" factor, not product. Branding strategy is an "},{"text":"organisation","bold":true},{"text":" factor, so it is "},{"text":"not","bold":true},{"text":" a product-related factor. PLC stage is a "},{"text":"product","bold":true},{"text":" factor. Type of buying decision is a "},{"text":"customer","bold":true},{"text":" factor. Impact of competition is a "},{"text":"competition and situation","bold":true},{"text":" factor, not product."}]},{"text":[{"text":"Product type and price:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Expensive, technically complex products sold to a few buyers (medical scanners for hospitals, industrial machines, Dangote Cement supply contracts with builders): rely most on "},{"text":"personal selling","bold":true},{"text":", because the information is complex and the buyer needs explanation and negotiation."}]},{"text":[{"text":"Low-priced, frequently bought consumer goods sold to millions (soft drinks, Indomie noodles, detergents): lean most on "},{"text":"advertising and sales promotion","bold":true},{"text":", because reach and low cost per contact matter."}]}]}]},{"text":[{"text":"Push example:","bold":true},{"text":" a new seasoning brand gives Idumota wholesalers extra margins, display allowances and regular visits from sales reps so they stock it and recommend it to retailers: "},{"text":"push","bold":true},{"text":"."}]},{"text":[{"text":"Pull example:","bold":true},{"text":" a manufacturer runs heavy TV adverts and consumer coupons so consumers ask retailers for the brand, and retailers then order it: "},{"text":"pull","bold":true},{"text":"."}]},{"text":[{"text":"Profile example:","bold":true},{"text":" an oil company's annual report, community-development announcements and investor briefings: "},{"text":"profile","bold":true},{"text":"."}]},{"text":[{"text":"Many firms combine push and pull: national adverts (pull) plus distributor incentives (push)."}]},{"text":[{"text":"Other selection criteria to keep in mind: cost, control, credibility, reach, target audience, budget and objectives. A firm with an awareness objective and a mass audience picks advertising; one with a closing objective and a few big buyers picks personal selling."}]}]}]},{"number":"3.5","title":"Market segmentation and communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market segmentation:","bold":true},{"text":" the grouping of consumers who are homogeneous in some way and then differentiating the products or brands to meet the groups' needs. Also: identifying specific market segments in a marketplace, then developing different marketing offerings that will be attractive to each segment. Equally: dividing the market of potential customers into groups by shared characteristics so a custom marketing mix can be built for each."}]},{"text":[{"text":"Why group at all: every consumer is unique, and tailoring products to each individual is very expensive."}]},{"text":[{"text":"The concept was introduced by "},{"text":"Wendell R. Smith","bold":true},{"text":" (1956)."}]},{"text":[{"text":"5 reasons for segmentation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It is easier to meet the needs of a group than the needs of every individual in a whole market."}]},{"text":[{"text":"Meeting a group's needs better brings greater "},{"text":"loyalty, increased trial and higher perceived quality","bold":true},{"text":"."}]},{"text":[{"text":"It gives the marketer a "},{"text":"target advertising group","bold":true},{"text":", which makes advertising more "},{"text":"cost-effective","bold":true},{"text":"."}]},{"text":[{"text":"Identifying and covering the main segment can help "},{"text":"keep competition out","bold":true},{"text":" of the market."}]},{"text":[{"text":"An identified unmet need can give "},{"text":"entry into the market","bold":true},{"text":" if its segment is large and profitable."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 bases (consumer profile):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Demographics:","bold":true},{"text":" age, income, marital status, and geography or location. This gives a focus for producing the product and communicating with consumers."}]},{"text":[{"text":"Physical needs:","bold":true},{"text":" e.g. oily or sensitive skin needing a particular cream; taste needs such as salty or sweet. Focus falls on product performance and delivery."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" found through consumer immersion, e.g. busy career woman, diet consciousness, caring parenting. Focus falls on product performance and delivery."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 effects of segmentation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"On consumers:","bold":true},{"text":" an easy, clear choice of product; consumers identify their class and buy in line with it."}]},{"text":[{"text":"On brands:","bold":true},{"text":" brands are produced for different classes, with variants such as \"mild\", \"strong\", \"smooth\" or \"extra\"."}]},{"text":[{"text":"On the marketer:","bold":true},{"text":" a focus for planning marketing activities and communication or advertising; the marketer knows the target and directs all strategies at it."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 common types:","bold":true},{"text":" geographic, demographic (most common), behavioural, psychographic."}]},{"text":[{"text":"A good segment","bold":true},{"text":" is internally "},{"text":"homogeneous","bold":true},{"text":" and externally "},{"text":"heterogeneous","bold":true},{"text":": members respond alike, and differ from other segments."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Wider bases:","bold":true},{"text":" gender, age, income (high, middle, low), place, occupation, usage (heavy, medium, light), lifestyle."}]},{"text":[{"text":"Geographic:","bold":true},{"text":" by region; bottled water sells strongly where clean water is scarce. "},{"text":"Demographic:","bold":true},{"text":" age, gender, marital status, family size, income, religion, occupation, nationality. "},{"text":"Behavioural:","bold":true},{"text":" knowledge and use of the product (non-users, ex-users, potential, first-time, current users), loyalty (brand loyal, brand-neutral, competitor loyal), usage rate. "},{"text":"Psychographic:","bold":true},{"text":" personality, lifestyle and attitude."}]},{"text":[{"text":"Why segmentation matters for communication:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It defines the "},{"text":"target audience","bold":true},{"text":", the first step in any communication plan."}]},{"text":[{"text":"It shapes the "},{"text":"message","bold":true},{"text":": a youth data plan from MTN speaks in campus slang; a premium banking product speaks of security and status."}]},{"text":[{"text":"It guides "},{"text":"media and tool choice","bold":true},{"text":": students are reached on Instagram, TikTok and campus events; older rural farmers through radio in local languages and market-day activations."}]},{"text":[{"text":"It "},{"text":"cuts waste","bold":true},{"text":": money is spent only on people likely to respond, raising conversions. That is the \"cost-effective advertising\" reason."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Context = circumstances inside and outside the firm; 4 contexts: customer, business, internal, external (PEST and stakeholders)."}]},{"text":[{"text":"The mix = tools used in combinations and intensities; 5 traditional tools: advertising, sales promotion, personal selling, PR, direct marketing; plus media (bought or used time and space)."}]},{"text":[{"text":"Advertising = indirect, paid. Publicity = free, editorial, newsworthy. PR = reputation, earned, crisis management. Sales promotion = short-term incentives. Personal selling = face-to-face, most reliable. Direct marketing = personalised to individuals."}]},{"text":[{"text":"Extra tools: events and experiences (sponsorship), interactive marketing, word of mouth, packaging, point of purchase."}]},{"text":[{"text":"Compare tools on effectiveness, credibility, cost and control. PR is most credible but least controlled; personal selling costs most per contact and gives most feedback."}]},{"text":[{"text":"4 factor groups: product, customer, organisation, competition and situation. Budget, channel and branding = organisation."}]},{"text":[{"text":"Push = at channel members; pull = at consumers; profile = at stakeholders for reputation."}]},{"text":[{"text":"Introduction = awareness plus trial; maturity = sales promotion; decline = reminder only."}]},{"text":[{"text":"Segmentation = grouping homogeneous consumers; 5 reasons, 3 bases (demographics, physical needs, lifestyle), 3 effects (consumers, brands, marketer)."}]}]}],"theory":{"itemId":"922c23bb-5130-582c-894f-f17688cfd613","question":[{"type":"paragraph","text":[{"text":"A drinks firm compares two options. A radio campaign costs ₦2,400,000 and reaches 1,600,000 listeners. A sales team costs ₦1,800,000 and makes 300 calls on supermarket buyers. Calculate the cost per contact of each, the radio CPM, and state which tool suits building awareness and which suits closing orders."}]}]},"practice":[{"topic":"MarCom Context, Mix and Selection Criteria","named":false}]}},{"itemId":"890a36ca-b6aa-5862-bef9-081f35e31b61","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:4","parentItemId":null,"revision":1,"payload":{"title":"Source, Message, Receiver and Medium; Opinion Leaders","body":"The four building blocks (source, message, receiver, medium) and how they fit the communication process; source credibility, attractiveness and power and the process each works through; message appeals, sidedness, order and conclusion drawing; the receiver's selective filters and fields of experience; personal and non-personal channels and media choice; opinion leaders, opinion formers, two-step and multi-step flow; adoption and diffusion of innovations.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The four building blocks (source, message, receiver, medium) and how they fit the communication process; source credibility, attractiveness and power and the process each works through; message appeals, sidedness, order and conclusion drawing; the receiver's selective filters and fields of experience; personal and non-personal channels and media choice; opinion leaders, opinion formers, two-step and multi-step flow; adoption and diffusion of innovations."}],"lessons":[{"number":"4.1","title":"The four building blocks and the process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Source (sender):","bold":true},{"text":" the originator of the message, such as a brand, company or spokesperson. For it to work, the audience must see the source as "},{"text":"credible, knowledgeable and relevant","bold":true},{"text":"."}]},{"text":[{"text":"Message:","bold":true},{"text":" the crafted content intended to inform, persuade or evoke a response. An effective message is "},{"text":"clear, compelling and tailored to the audience's needs and values","bold":true},{"text":"; a strategically crafted one "},{"text":"connects with the audience's aspirations, problems and motivations","bold":true},{"text":"."}]},{"text":[{"text":"Receiver (audience):","bold":true},{"text":" the intended audience that "},{"text":"decodes and responds to","bold":true},{"text":" the message. Their reaction depends on "},{"text":"their own interpretation, cultural background and how relevant the message is to them","bold":true},{"text":"."}]},{"text":[{"text":"Medium (channel):","bold":true},{"text":" the channel, such as digital platforms or broadcast media, that delivers the message. It should be "},{"text":"selected to match the target audience's media preferences and habits","bold":true},{"text":"."}]},{"text":[{"text":"The interplay of source, message, receiver and medium makes up "},{"text":"the framework of the marketing communication process","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Elements of the process (9):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender:","bold":true},{"text":" the party sending the message."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" putting thought into symbols (words, pictures, music)."}]},{"text":[{"text":"Message:","bold":true},{"text":" the set of symbols sent."}]},{"text":[{"text":"Media (channel):","bold":true},{"text":" the path the message travels."}]},{"text":[{"text":"Decoding:","bold":true},{"text":" the receiver giving meaning to the symbols."}]},{"text":[{"text":"Receiver:","bold":true},{"text":" the party getting the message."}]},{"text":[{"text":"Response:","bold":true},{"text":" the receiver's reactions after exposure (e.g. awareness, liking, buying)."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the "},{"text":"part of the receiver's response that is communicated back to the sender","bold":true},{"text":"."}]},{"text":[{"text":"Noise:","bold":true},{"text":" "},{"text":"unplanned distortion or interference","bold":true},{"text":" during the process, which can make the receiver get a different message from the one sent."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Field of experience:","bold":true},{"text":" the experiences, attitudes, values and language a person brings. Communication is most effective when the sender's and receiver's fields of experience "},{"text":"overlap","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise example:","bold":true},{"text":" a paint brand's radio jingle is drowned by generator sound in many homes, so listeners miss the brand name. The generator sound is "},{"text":"noise","bold":true},{"text":". Other noise: a poor network signal, a rival advert in the same break, a distracted viewer."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" after an advert runs, a firm tracks calls to its hotline, changes in sales and comments on its social media page. All are "},{"text":"feedback","bold":true},{"text":". Do not confuse feedback with response: response is everything the receiver does; feedback is only the part that returns to the sender."}]},{"text":[{"text":"Field of experience trap:","bold":true},{"text":" an advert full of Lagos teenage slang aimed at elderly rural farmers fails because there is "},{"text":"too little overlap","bold":true},{"text":" between the fields of experience of sender and receiver. That is why a firm advertising in the North may use Hausa, and in the South-West Yoruba."}]},{"text":[{"text":"The sender encodes; the receiver decodes. Exams often swap these two."}]}]}]},{"number":"4.2","title":"The source","mustKnow":[{"type":"paragraph","text":[{"text":"3 categories of source characteristics","bold":true},{"text":" (Kelman's model, used by Belch and Belch), each working through a different process:"}]},{"type":"table","header":[[{"text":"Source characteristic"}],[{"text":"What it is made of"}],[{"text":"Process of influence"}]],"rows":[[[{"text":"Credibility","bold":true}],[{"text":"expertise, trustworthiness"}],[{"text":"Internalisation","bold":true}]],[[{"text":"Attractiveness","bold":true}],[{"text":"similarity, familiarity, likability"}],[{"text":"Identification","bold":true}]],[[{"text":"Power","bold":true}],[{"text":"ability to reward or punish"}],[{"text":"Compliance","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expertise:","bold":true},{"text":" the knowledge, experience or skill the source is seen to have on the subject."}]},{"text":[{"text":"Trustworthiness:","bold":true},{"text":" the honesty, integrity and believability of the source; the audience's belief that the source has "},{"text":"no motive to mislead","bold":true},{"text":" them."}]},{"text":[{"text":"Internalisation:","bold":true},{"text":" the receiver accepts a credible source's view "},{"text":"because they believe the information is accurate","bold":true},{"text":", so it becomes part of their own beliefs."}]},{"text":[{"text":"Similarity:","bold":true},{"text":" the source resembles the receiver (same needs, lifestyle, background). "},{"text":"Familiarity:","bold":true},{"text":" knowing the source through exposure. "},{"text":"Likability:","bold":true},{"text":" affection for the source because of looks, behaviour or other traits."}]},{"text":[{"text":"Identification:","bold":true},{"text":" the receiver adopts the source's view because they want to be like, or relate to, the source."}]},{"text":[{"text":"Power:","bold":true},{"text":" the source can "},{"text":"administer rewards or punishments","bold":true},{"text":". The receiver goes along mainly through "},{"text":"compliance","bold":true},{"text":", which may be outward only."}]},{"text":[{"text":"Direct source:","bold":true},{"text":" a spokesperson who delivers the message or demonstrates the product. "},{"text":"Indirect source:","bold":true},{"text":" someone (e.g. a model) who delivers no message but "},{"text":"draws attention","bold":true},{"text":" to and enhances the look of the advert."}]},{"text":[{"text":"Sleeper effect:","bold":true},{"text":" the persuasive impact of a message from a "},{"text":"low-credibility","bold":true},{"text":" source "},{"text":"increases over time","bold":true},{"text":", as people forget the source but remember the message."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a qualified dentist in a clinic explaining how a toothpaste prevents decay = "},{"text":"expertise","bold":true},{"text":". An ordinary mother of three in a busy Lagos home, just like the women the brand targets, praising a detergent = "},{"text":"similarity","bold":true},{"text":". A popular Afrobeats star in a drink advert = attractiveness (familiarity and likability)."}]},{"text":[{"text":"Why power is rarely usable in mass advertising:","bold":true},{"text":" advertisers usually "},{"text":"cannot reward or punish consumers, nor check whether they comply","bold":true},{"text":". Power shows up more in settings such as a manager instructing staff or a big buyer pressing a supplier."}]},{"text":[{"text":"Risks of celebrity endorsers:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"scandal","bold":true},{"text":" involving the celebrity harms the brand's image."}]},{"text":[{"text":"Overexposure:","bold":true},{"text":" endorsing so many brands that the endorsement loses impact."}]},{"text":[{"text":"Overshadowing the product:","bold":true},{"text":" viewers remember the star but not the brand."}]},{"text":[{"text":"Mismatch","bold":true},{"text":" between the celebrity's image and the brand."}]},{"text":[{"text":"High cost","bold":true},{"text":" and loss of popularity over time."}]}]}]},{"text":[{"text":"Trap:","bold":true},{"text":" a celebrity "},{"text":"attracting attention","bold":true},{"text":" to an advert is a "},{"text":"benefit","bold":true},{"text":", not a risk."}]},{"text":[{"text":"Trust falls when the audience sees the source as paid to say it; this is why a neutral expert or a satisfied customer is often more believable than the company itself."}]}]}]},{"number":"4.3","title":"The message: appeals, sidedness and structure","mustKnow":[{"type":"paragraph","text":[{"text":"Message appeals","bold":true},{"text":" (the theme that gets the audience to respond):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Rational (informational) appeal:","bold":true},{"text":" focuses on the product's "},{"text":"features, quality, economy, value or performance","bold":true},{"text":"."}]},{"text":[{"text":"Emotional appeal:","bold":true},{"text":" stirs feelings (love, warmth, joy, pride, fear, guilt, shame) rather than giving facts."}]},{"text":[{"text":"Moral appeal:","bold":true},{"text":" directed to the audience's "},{"text":"sense of what is right and proper","bold":true},{"text":"; used for social causes (a cleaner environment, helping the needy)."}]},{"text":[{"text":"Fear appeal:","bold":true},{"text":" shows the bad consequences of not using the product or not changing behaviour."}]},{"text":[{"text":"Humour appeal:","bold":true},{"text":" uses jokes and wit to attract attention and liking."}]},{"text":[{"text":"Sex appeal:","bold":true},{"text":" uses sexual imagery or attractive models to draw attention."}]},{"text":[{"text":"Comparative advertising:","bold":true},{"text":" "},{"text":"directly or indirectly names a competitor","bold":true},{"text":" and compares the brand with it on one or more attributes."}]}]},{"type":"paragraph","text":[{"text":"Message sidedness:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"What it does"}],[{"text":"Works best when the audience"}]],"rows":[[[{"text":"One-sided","bold":true}],[{"text":"presents "},{"text":"only positive","bold":true},{"text":" points"}],[{"text":"already favours the brand, is less educated, is unlikely to hear opposing claims"}]],[[{"text":"Two-sided","bold":true}],[{"text":"presents "},{"text":"both good and bad","bold":true},{"text":" points"}],[{"text":"is "},{"text":"well educated, initially opposed, or likely to hear competitors' counter-arguments","bold":true}]],[[{"text":"Refutational appeal","bold":true}],[{"text":"presents both sides, then "},{"text":"argues against (refutes)","bold":true},{"text":" the opposing view"}],[{"text":"faces rival claims; it builds resistance to them"}]]]},{"type":"paragraph","text":[{"text":"Message structure:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primacy effect:","bold":true},{"text":" information presented "},{"text":"first","bold":true},{"text":" is learned best, so place the strongest arguments at the "},{"text":"beginning","bold":true},{"text":"."}]},{"text":[{"text":"Recency effect:","bold":true},{"text":" information presented "},{"text":"last","bold":true},{"text":" is remembered best, so place the strongest arguments at the "},{"text":"end","bold":true},{"text":"."}]},{"text":[{"text":"Conclusion drawing:","bold":true},{"text":" leave the conclusion "},{"text":"open","bold":true},{"text":" when the audience is "},{"text":"highly educated and highly involved","bold":true},{"text":"; state it clearly when the audience is less educated, less interested, sees the message only once, or the issue is complex."}]},{"text":[{"text":"Verbal vs visual:","bold":true},{"text":" pictures are often remembered better than words; the two should support each other."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a milk advert showing a mother lovingly feeding her smiling baby = "},{"text":"emotional","bold":true},{"text":". An advert saying a generator uses less fuel per hour = "},{"text":"rational","bold":true},{"text":". A campaign urging Lagosians not to dump refuse in drains = "},{"text":"moral","bold":true},{"text":"."}]},{"text":[{"text":"Fear appeals work","bold":true},{"text":" when they show the threat "},{"text":"and give a clear, easy action","bold":true},{"text":" to avoid it (e.g. a drink-driving campaign that says \"drink, do not drive; take a ride\"). Very shocking images with no solution make people switch off. Moderate fear usually works better than extreme fear."}]},{"text":[{"text":"Humour:","bold":true},{"text":" it draws attention and liking, but the joke can "},{"text":"distract attention from the brand","bold":true},{"text":" and "},{"text":"wear out with repetition","bold":true},{"text":". It may also not translate across cultures."}]},{"text":[{"text":"Sex appeal:","bold":true},{"text":" draws attention but can distract from the brand and offend, especially in a conservative society; the product must be relevant to it."}]},{"text":[{"text":"Comparative risk:","bold":true},{"text":" consumers may get confused and credit the competitor (selective distortion; see Lesson 4.4). In Nigeria such adverts must also stay truthful and fair under the advertising code enforced by ARCON (formerly APCON)."}]},{"text":[{"text":"Sidedness traps:","bold":true},{"text":" a smartphone advert listing only positives = "},{"text":"one-sided","bold":true},{"text":". \"Some say our prices are higher; here is why that is false\" = "},{"text":"refutational","bold":true},{"text":". Two-sided messages raise credibility because the source admits a weakness."}]},{"text":[{"text":"Rational and emotional appeals are often combined, e.g. a bank advert showing a happy family (emotion) and an interest rate (reason)."}]}]}]},{"number":"4.4","title":"The receiver and the medium","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Perception:","bold":true},{"text":" the process of selecting, organising and interpreting information inputs to create meaning."}]},{"text":[{"text":"Selective perception:","bold":true},{"text":" the receiver's filtering of messages. Consumers notice only some adverts, interpret them to fit what they already believe, and remember only part of them. It has these parts:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selective exposure:","bold":true},{"text":" choosing which messages to come into contact with (e.g. changing the channel during adverts)."}]},{"text":[{"text":"Selective attention:","bold":true},{"text":" noticing only some of the messages one is exposed to."}]},{"text":[{"text":"Selective distortion (comprehension):","bold":true},{"text":" twisting information that conflicts with one's beliefs."}]},{"text":[{"text":"Selective retention:","bold":true},{"text":" remembering information that supports one's beliefs and forgetting the rest."}]}]}]},{"text":[{"text":"Decoding","bold":true},{"text":" is done by the receiver, through their own field of experience, culture and needs."}]}]},{"type":"paragraph","text":[{"text":"Personal vs non-personal channels:","bold":true}]},{"type":"table","header":[[],[{"text":"Personal channels"}],[{"text":"Non-personal channels"}]],"rows":[[[{"text":"Meaning"}],[{"text":"two or more people communicate directly (face to face, phone, chat)"}],[{"text":"carry messages "},{"text":"without personal contact or feedback","bold":true}]],[[{"text":"Types"}],[{"text":"advocate","bold":true},{"text":" (company salespeople), "},{"text":"expert","bold":true},{"text":" (independent experts), "},{"text":"social","bold":true},{"text":" (neighbours, friends, family, associates)"}],[{"text":"major media","bold":true},{"text":" (print, broadcast, display, online), "},{"text":"atmospheres","bold":true},{"text":" (designed environments), "},{"text":"events","bold":true},{"text":" (staged occurrences)"}]],[[{"text":"Example"}],[{"text":"a salesperson's face-to-face talk with a customer"}],[{"text":"TV commercial, newspaper advert, roadside billboard"}]]]},{"type":"paragraph","text":[{"text":"Main media compared:","bold":true}]},{"type":"table","header":[[{"text":"Medium"}],[{"text":"Strengths"}],[{"text":"Weaknesses"}]],"rows":[[[{"text":"Television","bold":true}],[{"text":"sight, sound and motion; very wide mass reach"}],[{"text":"high absolute cost","bold":true},{"text":", clutter, short exposure"}]],[[{"text":"Radio","bold":true}],[{"text":"low cost, local, reaches people on the move, wide reach in Nigeria"}],[{"text":"audio only, fleeting, low attention"}]],[[{"text":"Newspapers","bold":true}],[{"text":"timely, local, believable"}],[{"text":"short life, poor reproduction"}]],[[{"text":"Magazines","bold":true}],[{"text":"specific audiences, good colour, long life"}],[{"text":"long lead time, high cost"}]],[[{"text":"Outdoor (billboards)","bold":true}],[{"text":"high repeat exposure, low cost per exposure"}],[{"text":"little selectivity, short message"}]],[[{"text":"Internet/digital","bold":true}],[{"text":"targeted, interactive, measurable, low cost"}],[{"text":"audience controls exposure, ad blocking"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Choose the medium "},{"text":"after","bold":true},{"text":" identifying the target audience, matching their media habits, and weighing "},{"text":"reach","bold":true},{"text":" (how many people), "},{"text":"frequency","bold":true},{"text":" (how often) and "},{"text":"impact","bold":true},{"text":" (quality of exposure) against cost."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social channel example:","bold":true},{"text":" a buyer's friends, neighbours and family talk to them about a product. A pharmacist recommending a drug is an "},{"text":"expert","bold":true},{"text":" channel; a Jumia sales agent is an "},{"text":"advocate","bold":true},{"text":" channel."}]},{"text":[{"text":"Personal channels are more persuasive because they allow two-way talk and instant feedback; non-personal channels reach far more people at a lower cost per person."}]},{"text":[{"text":"Medium trap:","bold":true},{"text":" the medium should not always be the cheapest, nor always TV. A firm targeting university students may favour Instagram and campus radio; one targeting market women may use radio in local languages."}]},{"text":[{"text":"Comparative advertising and selective distortion:","bold":true},{"text":" viewers may misremember which brand made the claim and credit the rival."}]}]}]},{"number":"4.5","title":"Opinion leaders, opinion formers and the flow of communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Opinion leader:","bold":true},{"text":" a person "},{"text":"within a reference group","bold":true},{"text":" who, because of "},{"text":"special skills, knowledge, personality or other characteristics","bold":true},{"text":", exerts social influence on others. A trusted person whose views and recommendations shape other people's attitudes and actions. Usually "},{"text":"not paid","bold":true},{"text":" and has no formal position."}]},{"text":[{"text":"Opinion former:","bold":true},{"text":" holds a "},{"text":"formal or professional position","bold":true},{"text":" (e.g. journalist, critic, doctor) that gives their views authority."}]},{"text":[{"text":"Opinion follower:","bold":true},{"text":" a person who seeks and accepts the views of opinion leaders."}]},{"text":[{"text":"Why opinion leaders matter:","bold":true},{"text":" they "},{"text":"increase a message's reach and credibility through their social influence","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Typical traits of opinion leaders:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More "},{"text":"exposed to media","bold":true},{"text":" in their area of interest than their followers."}]},{"text":[{"text":"More knowledgeable and involved in the product category."}]},{"text":[{"text":"Usually from the "},{"text":"same social class","bold":true},{"text":" as their followers."}]},{"text":[{"text":"Influential in "},{"text":"specific categories","bold":true},{"text":", not all categories."}]},{"text":[{"text":"More innovative, sociable and confident."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Two-step flow model","bold":true},{"text":" (Lazarsfeld and colleagues, 1940s): information flows "},{"text":"from the mass media to opinion leaders, who then pass it on to the wider population","bold":true},{"text":"."}]},{"text":[{"text":"Multi-step flow model:","bold":true},{"text":" improves on it by recognising that "},{"text":"media reach both leaders and followers directly, and influence flows in several directions","bold":true},{"text":" (leaders to followers, followers to leaders, follower to follower)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leader or former?","bold":true},{"text":" Tunde, unpaid, reads technology blogs and tries new phones early, so friends in his estate ask his advice = "},{"text":"opinion leader","bold":true},{"text":". A professional food critic with a weekly newspaper column = "},{"text":"opinion former","bold":true},{"text":" (her influence comes from her formal position)."}]},{"text":[{"text":"Application of two-step flow:","bold":true},{"text":" marketers "},{"text":"target opinion leaders","bold":true},{"text":", e.g. with free samples or early access, so they spread the word. Examples: giving a new phone to tech reviewers, sampling a new seasoning cube to respected caterers."}]},{"text":[{"text":"Traps:","bold":true},{"text":" opinion leaders do not remove the need for paid advertising, do not control distribution, and are not equally influential across all categories. A fashion leader may know nothing about cars."}]},{"text":[{"text":"The two-step model was criticised because followers also get information straight from the media; this led to the multi-step model."}]}]}]},{"number":"4.6","title":"Adoption and diffusion of innovations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adoption process:","bold":true},{"text":" the "},{"text":"mental process an individual goes through","bold":true},{"text":" from first hearing about an innovation to finally adopting it. Stages (Kotler): "},{"text":"awareness, interest, evaluation, trial, adoption","bold":true},{"text":"."}]},{"text":[{"text":"Diffusion of innovation:","bold":true},{"text":" the "},{"text":"spread of an innovation through a whole market over time","bold":true},{"text":" (Everett Rogers)."}]}]},{"type":"paragraph","text":[{"text":"5 adopter categories, first to last","bold":true},{"text":" (Rogers):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Innovators","bold":true},{"text":" (2.5%): venturesome, take risks."}]},{"text":[{"text":"Early adopters","bold":true},{"text":" (13.5%): guided by respect; "},{"text":"opinion leaders","bold":true},{"text":" in their community."}]},{"text":[{"text":"Early majority","bold":true},{"text":" (34%): deliberate; adopt before the average person."}]},{"text":[{"text":"Late majority","bold":true},{"text":" (34%): sceptical; adopt after most people have."}]},{"text":[{"text":"Laggards","bold":true},{"text":" (16%): "},{"text":"tradition-bound, suspicious of change","bold":true},{"text":", adopt only when the innovation has become something of a tradition itself."}]}]},{"type":"paragraph","text":[{"text":"5 characteristics affecting the rate of adoption:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relative advantage:","bold":true},{"text":" how much better it seems than what exists."}]},{"text":[{"text":"Compatibility:","bold":true},{"text":" how well it fits the values and experiences of users."}]},{"text":[{"text":"Complexity:","bold":true},{"text":" how hard it is to understand or use (more complex = slower)."}]},{"text":[{"text":"Divisibility (trialability):","bold":true},{"text":" whether it can be tried on a small scale."}]},{"text":[{"text":"Communicability (observability):","bold":true},{"text":" how easily its results can be seen or described to others."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relative advantage example:","bold":true},{"text":" mobile money spread quickly in Nigeria partly because users saw it as clearly better than queuing in banking halls to send money."}]},{"text":[{"text":"Trap:","bold":true},{"text":" adoption is about "},{"text":"one individual","bold":true},{"text":"; diffusion is about the "},{"text":"whole market","bold":true},{"text":". Grouping buyers into innovators, early adopters and so on is the adopter categorisation, not the adoption process."}]},{"text":[{"text":"Order trap:","bold":true},{"text":" innovators come "},{"text":"before","bold":true},{"text":" early adopters. Memory aid: I-E-E-L-L (Innovators, Early adopters, Early majority, Late majority, Laggards)."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" a fintech app targets 400,000 potential users. Using Rogers' percentages:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovators: 2.5% of 400,000 = 0.025 x 400,000 = 10,000"}]},{"text":[{"text":"Early adopters: 13.5% x 400,000 = 54,000"}]},{"text":[{"text":"Early majority: 34% x 400,000 = 136,000"}]},{"text":[{"text":"Late majority: 34% x 400,000 = 136,000"}]},{"text":[{"text":"Laggards: 16% x 400,000 = 64,000"}]},{"text":[{"text":"Check: 10,000 + 54,000 + 136,000 + 136,000 + 64,000 = 400,000. The first two groups together = 16% = 64,000 people, the group to win first because early adopters lead opinion."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Source, message, receiver and medium together form the framework of the marketing communication process."}]},{"text":[{"text":"Noise = unplanned interference; feedback = the part of the response sent back; overlap of fields of experience aids understanding."}]},{"text":[{"text":"Source characteristics: credibility (expertise, trustworthiness) to internalisation; attractiveness (similarity, familiarity, likability) to identification; power to compliance."}]},{"text":[{"text":"Sleeper effect: a low-credibility source's message gains impact over time."}]},{"text":[{"text":"Appeals: rational, emotional, moral, fear, humour, sex, comparative. Fear needs a clear way out."}]},{"text":[{"text":"Two-sided for educated, opposed or counter-argued audiences; refutational = both sides plus rebuttal; primacy = strongest first; open conclusion for educated, involved audiences."}]},{"text":[{"text":"Selective exposure, attention, distortion and retention make up selective perception."}]},{"text":[{"text":"Personal channels: advocate, expert, social. Non-personal: media, atmospheres, events."}]},{"text":[{"text":"Opinion leader = informal peer; opinion former = formal position. Two-step: media to leaders to others; multi-step: many directions."}]},{"text":[{"text":"Adopters: innovators, early adopters (opinion leaders), early majority, late majority, laggards."}]}]}],"theory":{"itemId":"fae777aa-140e-58e7-bab6-c1817b21c519","question":[{"type":"paragraph","text":[{"text":"Name the three categories of source characteristics and state the process through which each influences the receiver, with one example each."}]}]},"practice":[{"topic":"Source, Message, Receiver, Medium and Opinion Leaders","named":false}]}},{"itemId":"e52f06c3-d074-5d3f-b72e-271f5628d4ce","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:5","parentItemId":null,"revision":1,"payload":{"title":"Communication, Business Communication and the Communication Process","body":"The meaning, origin, importance and 7 Cs of communication; what business communication is, its purposes and examples; the forms of business communication (internal/external, formal/informal and the grapevine, upward/downward/horizontal/diagonal, verbal/non-verbal, oral/written, visual); the elements of the communication process; the Lasswell, Shannon-Weaver, Schramm and transactional models; barriers to communication and how to overcome them.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The meaning, origin, importance and 7 Cs of communication; what business communication is, its purposes and examples; the forms of business communication (internal/external, formal/informal and the grapevine, upward/downward/horizontal/diagonal, verbal/non-verbal, oral/written, visual); the elements of the communication process; the Lasswell, Shannon-Weaver, Schramm and transactional models; barriers to communication and how to overcome them."}],"lessons":[{"number":"5.1","title":"Meaning, importance and principles of communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" \"communication\" comes from the Latin word "},{"text":"communis","bold":true},{"text":", meaning "},{"text":"common","bold":true},{"text":". To communicate is to create a "},{"text":"common (shared) understanding","bold":true},{"text":" between people."}]},{"text":[{"text":"Communication:","bold":true},{"text":" the process of "},{"text":"transmitting information and shared meaning from one person or group to another person or group","bold":true},{"text":". It is also the exchange of thoughts or conversation through written words, verbal conversation, electronic or digital media and social media to exchange ideas and information for a pre-planned purpose, or the process of using words, sounds or visual cues to supply information to one or more people."}]},{"text":[{"text":"Effective communication:","bold":true},{"text":" occurs when the "},{"text":"meaning understood by the receiver matches the meaning intended by the sender","bold":true},{"text":". Sending a message is not enough; it must be understood."}]},{"text":[{"text":"One-way communication:","bold":true},{"text":" the message flows from sender to receiver with no immediate reply, e.g. a "},{"text":"roadside billboard","bold":true},{"text":", a radio jingle, a printed notice."}]},{"text":[{"text":"Two-way communication:","bold":true},{"text":" the receiver can reply, so there is feedback, e.g. a telephone call, a face-to-face sales negotiation, a question-and-answer session."}]}]},{"type":"paragraph","text":[{"text":"Importance of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Passes information and instructions."}]},{"text":[{"text":"Coordinates the work of people and departments."}]},{"text":[{"text":"Supports planning, decision-making and control."}]},{"text":[{"text":"Persuades and motivates (customers, staff, investors)."}]},{"text":[{"text":"Builds relationships and trust with stakeholders."}]},{"text":[{"text":"Is the base of all marketing: without communication a firm cannot tell buyers what it offers."}]}]},{"type":"paragraph","text":[{"text":"The 7 Cs of effective communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clarity:","bold":true},{"text":" one clear idea, plain familiar words."}]},{"text":[{"text":"Conciseness:","bold":true},{"text":" say it in as few words as needed; no repetition."}]},{"text":[{"text":"Concreteness:","bold":true},{"text":" specific facts and figures, not vague claims."}]},{"text":[{"text":"Correctness:","bold":true},{"text":" accurate facts, correct grammar and spelling, right level of language."}]},{"text":[{"text":"Completeness:","bold":true},{"text":" all the information the receiver needs to act."}]},{"text":[{"text":"Consideration:","bold":true},{"text":" see things from the receiver's side (the \"you\" attitude)."}]},{"text":[{"text":"Courtesy:","bold":true},{"text":" polite, respectful, sincere tone."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Some versions of the list replace "},{"text":"consideration","bold":true},{"text":" with "},{"text":"coherence","bold":true},{"text":" (logical, connected ideas). If an exam offers coherence as one of the 7 Cs, accept it; \"complexity\", \"cost\" or \"confusion\" are never among the 7 Cs."}]},{"text":[{"text":"Concreteness example:","bold":true},{"text":" \"Our data is cheap\" is vague; \"₦1,000 for 1.5GB, valid 30 days\" is concrete."}]},{"text":[{"text":"Effectiveness trap:","bold":true},{"text":" an option saying communication is effective \"once the sender has transmitted the message, whether or not it is understood\" is wrong. Effectiveness is judged at the receiver's end."}]},{"text":[{"text":"A billboard on the Third Mainland Bridge is one-way: drivers cannot reply to it. A customer chatting with a bank's agent on the phone is two-way."}]}]}]},{"number":"5.2","title":"Business communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business communication:","bold":true},{"text":" the "},{"text":"exchange of information between people within and outside an organisation in order to achieve the organisation's goals","bold":true},{"text":". It covers both internal (staff, departments) and external (customers, suppliers, investors, government, media) audiences, and both written and oral forms."}]}]},{"type":"paragraph","text":[{"text":"Purposes of business communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"inform","bold":true},{"text":" employees and customers about decisions, policies and offers."}]},{"text":[{"text":"To "},{"text":"persuade","bold":true},{"text":" customers and other stakeholders to take action."}]},{"text":[{"text":"To "},{"text":"coordinate","bold":true},{"text":" the work of different departments."}]},{"text":[{"text":"To "},{"text":"instruct and direct","bold":true},{"text":" staff."}]},{"text":[{"text":"To "},{"text":"build relationships and goodwill","bold":true},{"text":" with internal and external stakeholders."}]},{"text":[{"text":"To get "},{"text":"feedback","bold":true},{"text":" and information for decisions."}]}]},{"type":"paragraph","text":[{"text":"Examples of business communication:","bold":true},{"text":" analytical reports circulated to stakeholders; presentations used to align a team on its objectives; oral discussions during meetings; memos, circulars and letters; emails; press releases; staff newsletters; advertisements; non-verbal cues (body language, dress, punctuality) that shape how stakeholders see a firm."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"What is NOT business communication:","bold":true},{"text":" building a prototype, machine maintenance, counting stock, manufacturing, product design, financial forecasting, budget allocation, auditing and recruitment are business "},{"text":"activities","bold":true},{"text":", not communication. The report or presentation "},{"text":"about","bold":true},{"text":" them is communication."}]},{"text":[{"text":"Trap options:","bold":true},{"text":" \"communication only among employees\" (too narrow, ignores external), \"messages sent only to customers\" (too narrow, ignores internal), \"only written letters and memos\" (ignores oral and non-verbal). The complete definition says "},{"text":"within and outside","bold":true},{"text":" the organisation, "},{"text":"to achieve its goals","bold":true},{"text":"."}]},{"text":[{"text":"\"To remove the need for planning and organising\" is "},{"text":"not","bold":true},{"text":" a purpose. Communication supports planning; it never replaces it."}]},{"text":[{"text":"Strategic role:","bold":true},{"text":" the communication process helps a business "},{"text":"build relationships with internal and external stakeholders","bold":true},{"text":". Cutting contact with customers, lowering quality or restricting supply are not things communication supports."}]},{"text":[{"text":"Example: when GTBank announces a new feature, it informs customers (external), briefs branch staff (internal) and issues a press release to newspapers (external, through the media)."}]}]}]},{"number":"5.3","title":"Forms of business communication","mustKnow":[{"type":"paragraph","text":[{"text":"1. By audience: internal vs external","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal:","bold":true},{"text":" within the organisation, e.g. "},{"text":"staff newsletter","bold":true},{"text":", memo, circular, staff meeting, intranet notice."}]},{"text":[{"text":"External:","bold":true},{"text":" with people outside, e.g. "},{"text":"press release","bold":true},{"text":", advertisement, billboard, letter to a supplier, product launch press conference, customer email."}]}]},{"type":"paragraph","text":[{"text":"2. By official status: formal vs informal","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formal:","bold":true},{"text":" follows "},{"text":"official channels and lines of authority","bold":true},{"text":" set by the organisation (chain of command), e.g. reports, memos, official meetings."}]},{"text":[{"text":"Informal:","bold":true},{"text":" spreads through friendships and casual conversation, outside official lines. Its main network is the "},{"text":"grapevine","bold":true},{"text":"."}]},{"text":[{"text":"Grapevine:","bold":true},{"text":" the informal network through which "},{"text":"news and rumours spread among employees outside official channels","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages: spreads information "},{"text":"very quickly","bold":true},{"text":"; shows managers staff feelings; builds social bonds; fills gaps when formal communication is slow."}]},{"text":[{"text":"Disadvantages: messages are often "},{"text":"distorted","bold":true},{"text":" and can spread "},{"text":"false rumours","bold":true},{"text":"; no one controls it; leaves no official record; can damage morale."}]}]}]}]},{"type":"paragraph","text":[{"text":"3. By direction","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Downward:","bold":true},{"text":" from superiors to subordinates, e.g. MD's circular on new resumption time, a supervisor's instructions, job descriptions, policy memos."}]},{"text":[{"text":"Upward:","bold":true},{"text":" from subordinates to superiors, e.g. weekly sales reports, "},{"text":"suggestion box","bold":true},{"text":", complaints, feedback surveys, requests."}]},{"text":[{"text":"Horizontal (lateral):","bold":true},{"text":" between people "},{"text":"at the same level","bold":true},{"text":", e.g. marketing manager and production manager agreeing a launch date."}]},{"text":[{"text":"Diagonal (crosswise):","bold":true},{"text":" between people at "},{"text":"different levels in different departments","bold":true},{"text":", e.g. a sales officer contacting the finance manager directly."}]}]},{"type":"paragraph","text":[{"text":"4. By mode: verbal vs non-verbal (and visual)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Verbal","bold":true},{"text":" uses words: "},{"text":"oral","bold":true},{"text":" (spoken: meetings, phone calls, presentations, interviews) and "},{"text":"written","bold":true},{"text":" (letters, memos, reports, emails, agreements, brochures)."}]},{"text":[{"text":"Non-verbal","bold":true},{"text":" uses no words:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Kinesics:","bold":true},{"text":" body movements: gestures, posture, facial expressions, eye contact."}]},{"text":[{"text":"Paralanguage:","bold":true},{"text":" how the voice is used: tone, pitch, speed, volume."}]},{"text":[{"text":"Proxemics:","bold":true},{"text":" use of personal space and distance."}]},{"text":[{"text":"Chronemics:","bold":true},{"text":" use of time (punctuality, lateness, waiting)."}]},{"text":[{"text":"Haptics:","bold":true},{"text":" touch (handshake, pat on the back)."}]},{"text":[{"text":"Appearance and artefacts:","bold":true},{"text":" dress, grooming, office layout."}]}]}]},{"text":[{"text":"Visual:","bold":true},{"text":" charts, graphs, pictures, logos, signs, videos, infographics."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Oral"}],[{"text":"Written"}]],"rows":[[[{"text":"Feedback"}],[{"text":"Immediate, with clarification"}],[{"text":"Delayed"}]],[[{"text":"Record"}],[{"text":"None (unless recorded)"}],[{"text":"Permanent record; can serve as evidence"}]],[[{"text":"Speed"}],[{"text":"Fast"}],[{"text":"Slower to prepare"}]],[[{"text":"Editing"}],[{"text":"Little chance to edit"}],[{"text":"Can be checked and edited before sending"}]],[[{"text":"Best for"}],[{"text":"Discussion, quick decisions, sensitive talks"}],[{"text":"Contracts, policies, legal and long messages"}]],[[{"text":"Weakness"}],[{"text":"Easily forgotten or denied"}],[{"text":"Costly in time; no tone of voice"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Channel richness","bold":true},{"text":" (Daft and Lengel): a channel's ability to carry several cues at once (words, tone, face) and give immediate feedback. From richest to leanest: "},{"text":"face-to-face meeting","bold":true},{"text":", telephone or video call, personal email or letter, impersonal written notice, formal report or bulletin. Use rich channels for complex or sensitive messages and lean channels for routine ones."}]},{"text":[{"text":"Written for disputes:","bold":true},{"text":" a Kano distributor agreeing ₦5 million credit payable in 60 days should use a "},{"text":"signed written agreement","bold":true},{"text":", because it creates a permanent record that can be relied on if a dispute arises. A phone call or the grapevine gives no proof."}]},{"text":[{"text":"Non-verbal traps:","bold":true},{"text":" a smile and firm handshake are non-verbal (kinesics plus haptics); tone of voice is non-verbal (paralanguage); dress is non-verbal. A "},{"text":"memo","bold":true},{"text":" is written verbal communication, not non-verbal. A telephone conversation is oral."}]},{"text":[{"text":"Chronemics example:","bold":true},{"text":" a supplier keeps a client waiting two hours past the meeting time in Abuja. The client reads it as \"they do not value my business\". The message was sent through the use of time."}]},{"text":[{"text":"Direction trap:","bold":true},{"text":" the suggestion box is "},{"text":"upward","bold":true},{"text":", even though management set it up. A job description given to a new employee is "},{"text":"downward","bold":true},{"text":". Two managers at the same level talking is "},{"text":"horizontal","bold":true},{"text":", not diagonal."}]},{"text":[{"text":"Internal vs external trap:","bold":true},{"text":" a press release goes to newspapers and the public, so it is "},{"text":"external","bold":true},{"text":" even if staff also read it. A letter of complaint to a supplier is external."}]}]}]},{"number":"5.4","title":"The communication process and its elements","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication process:","bold":true},{"text":" an idea is "},{"text":"encoded","bold":true},{"text":" into a message, "},{"text":"transmitted through a channel","bold":true},{"text":" and "},{"text":"decoded by the receiver","bold":true},{"text":", who responds and sends feedback, with noise able to interfere at any point."}]},{"text":[{"text":"Basic business model:","bold":true},{"text":" "},{"text":"sender, message, channel, receiver and feedback","bold":true},{"text":" (with encoding, decoding and noise added in the full model)."}]}]},{"type":"paragraph","text":[{"text":"Elements of the process:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender (source):","bold":true},{"text":" the person or organisation that "},{"text":"has an idea to share and starts","bold":true},{"text":" the communication."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" "},{"text":"putting thoughts or ideas into symbolic form","bold":true},{"text":", such as words, pictures, music or sounds."}]},{"text":[{"text":"Message:","bold":true},{"text":" the "},{"text":"set of words, pictures, sounds or symbols","bold":true},{"text":" that the sender transmits."}]},{"text":[{"text":"Channel (medium):","bold":true},{"text":" the "},{"text":"means or path through which the message travels","bold":true},{"text":" from sender to receiver, e.g. radio, TV, email, SMS, a face-to-face meeting."}]},{"text":[{"text":"Decoding:","bold":true},{"text":" the process by which the "},{"text":"receiver assigns meaning to (interprets) the symbols","bold":true},{"text":" sent by the sender."}]},{"text":[{"text":"Receiver:","bold":true},{"text":" the "},{"text":"person or group the message is intended for, who decodes it","bold":true},{"text":"."}]},{"text":[{"text":"Response:","bold":true},{"text":" the "},{"text":"receiver's reaction","bold":true},{"text":" after receiving the message."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the "},{"text":"part of the receiver's response that is communicated back to the sender","bold":true},{"text":". It shows the sender how the message was received so it can be "},{"text":"corrected or refined","bold":true},{"text":"."}]},{"text":[{"text":"Noise:","bold":true},{"text":" "},{"text":"any unplanned interference or distortion","bold":true},{"text":" that prevents the message from being received as intended. It can occur at any stage."}]},{"text":[{"text":"Field of experience:","bold":true},{"text":" the background, knowledge, culture, language and experience each party brings. Communication works best when the sender's and receiver's fields of experience "},{"text":"overlap","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Full Nigerian walk-through:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos cement company ("},{"text":"sender","bold":true},{"text":") wants buyers to see its brand as strong and durable."}]},{"text":[{"text":"With an agency it turns this into a TV script showing a building standing firm in heavy rain ("},{"text":"encoding","bold":true},{"text":")."}]},{"text":[{"text":"The finished advert ("},{"text":"message","bold":true},{"text":") runs on TV ("},{"text":"channel","bold":true},{"text":")."}]},{"text":[{"text":"A viewer in Ibadan sees it and concludes \"this cement lasts\" ("},{"text":"decoding","bold":true},{"text":"); the viewer is the "},{"text":"receiver","bold":true},{"text":"."}]},{"text":[{"text":"The viewer's interest and later purchase is the "},{"text":"response","bold":true},{"text":"."}]},{"text":[{"text":"Calls to the company and rising orders reported by dealers are "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"A power cut in the middle of the advert is "},{"text":"noise","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Decoding example:","bold":true},{"text":" a viewer watches a soft drink advert of friends laughing at a party and concludes the drink is for happy social occasions. Interpreting the meaning is decoding."}]},{"text":[{"text":"Noise example:","bold":true},{"text":" a trader at Balogun Market cannot hear a bank's radio jingle because of a loud generator. The generator sound is noise. Noise is "},{"text":"not","bold":true},{"text":" the loud music inside the advert itself, and it is not the channel."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" a telecoms company sends an SMS offering a ₦1,000 data bundle. Customers who reply \"YES\" and those who call the helpline with questions are giving "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"Response vs feedback:","bold":true},{"text":" response is the receiver's whole reaction (some silent, like liking the brand); feedback is only the part that reaches the sender."}]},{"text":[{"text":"Encoding vs decoding:","bold":true},{"text":" the sender encodes, the receiver decodes. Exams swap them often."}]},{"text":[{"text":"Not an element:","bold":true},{"text":" budget, price, product, AIDA stages and the promotion mix tools are "},{"text":"not","bold":true},{"text":" elements of the communication process model. \"Product, price, place and promotion\" is the marketing mix; \"attention, interest, desire, action\" is AIDA; \"advertising, sales promotion, PR, personal selling\" is the promotion mix."}]},{"text":[{"text":"An effective process ensures messages are "},{"text":"crafted, delivered and interpreted with clarity and purpose","bold":true},{"text":". Ignoring the receiver or blocking feedback makes communication fail."}]}]}]},{"number":"5.5","title":"Models of communication","mustKnow":[{"type":"table","header":[[{"text":"Model"}],[{"text":"Author and date"}],[{"text":"Type"}],[{"text":"Key idea"}]],"rows":[[[{"text":"Lasswell's formula"}],[{"text":"Harold Lasswell, 1948","bold":true}],[{"text":"Linear"}],[{"text":"\""},{"text":"Who says what, in which channel, to whom, with what effect?","bold":true},{"text":"\""}]],[[{"text":"Shannon-Weaver"}],[{"text":"Claude Shannon and Warren Weaver, 1949","bold":true}],[{"text":"Linear (one-way)"}],[{"text":"Built from work on "},{"text":"telephone signals","bold":true},{"text":" at Bell Labs; introduced "},{"text":"noise","bold":true}]],[[{"text":"Schramm (Osgood-Schramm)"}],[{"text":"Wilbur Schramm, 1954","bold":true}],[{"text":"Interactive (circular)"}],[{"text":"Both parties encode and decode in turns; "},{"text":"feedback","bold":true},{"text":" and "},{"text":"field of experience","bold":true}]],[[{"text":"Transactional"}],[{"text":"Dean Barnlund, 1970"}],[{"text":"Transactional"}],[{"text":"Both parties "},{"text":"send and receive at the same time","bold":true},{"text":", continuously"}]]]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Linear model:","bold":true},{"text":" one-way flow from sender to a passive receiver. Elements in Shannon-Weaver: information source, transmitter (encoder), channel, receiver (decoder), destination, plus "},{"text":"noise source","bold":true},{"text":". "},{"text":"Main weakness: no feedback","bold":true},{"text":" from the receiver."}]},{"text":[{"text":"Interactive model:","bold":true},{"text":" two-way; the receiver sends feedback, so communication is a cycle. Meaning is shared only where the two "},{"text":"fields of experience overlap","bold":true},{"text":"."}]},{"text":[{"text":"Transactional model:","bold":true},{"text":" communication is a "},{"text":"continuous process in which both parties send and receive messages at the same time","bold":true},{"text":" (e.g. a speaker reads the listener's face while still talking). Both are \"communicators\"; noise and context still apply."}]}]},{"type":"paragraph","text":[{"text":"Why the communication model is useful to a business:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It "},{"text":"explains how organisational messages are sent and received","bold":true},{"text":"."}]},{"text":[{"text":"It helps "},{"text":"identify barriers","bold":true},{"text":" (noise) that can stop a message being delivered and understood."}]},{"text":[{"text":"It shows the need to "},{"text":"know the target audience","bold":true},{"text":" and its field of experience."}]},{"text":[{"text":"It stresses "},{"text":"feedback","bold":true},{"text":" for checking and refining messages."}]},{"text":[{"text":"It guides choice of "},{"text":"channel","bold":true},{"text":" and message design."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lasswell's five questions map onto the elements:","bold":true},{"text":" who = sender; says what = message; in which channel = channel; to whom = receiver; with what effect = effect/response. The quote is Lasswell's, not Kotler's, Schramm's or Shannon and Weaver's."}]},{"text":[{"text":"Shannon and Weaver trap:","bold":true},{"text":" the 1949 model came from engineering (signals on telephone lines), so \"noise\" first meant static on a line. AIDA is a response model (Topic 2), not a communication process model."}]},{"text":[{"text":"Schramm's contribution:","bold":true},{"text":" communication is two-way and depends on shared experience. A Hausa-language radio advert in Kano works because it overlaps the listeners' field of experience."}]},{"text":[{"text":"A model "},{"text":"never guarantees","bold":true},{"text":" that every message will be understood, does not fix prices and does not remove the need to know the audience."}]},{"text":[{"text":"Linear vs transactional:","bold":true},{"text":" a billboard fits the linear model; a live sales negotiation, where both sides talk, watch and react at once, fits the transactional model."}]}]}]},{"number":"5.6","title":"Barriers to communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Barrier:","bold":true},{"text":" anything that blocks, distorts or delays a message so that the receiver's meaning differs from the sender's."}]}]},{"type":"paragraph","text":[{"text":"Types of barriers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical:","bold":true},{"text":" environmental noise (generators, traffic), distance, poor network, faulty equipment, poor lighting."}]},{"text":[{"text":"Semantic (language):","bold":true},{"text":" "},{"text":"jargon","bold":true},{"text":", technical terms, ambiguous words, different languages, poor translation."}]},{"text":[{"text":"Psychological (emotional):","bold":true},{"text":" anger, fear, stress, anxiety, distrust, prejudice that stop a person listening."}]},{"text":[{"text":"Perceptual:","bold":true},{"text":" "},{"text":"selective exposure","bold":true},{"text":" (seeing only some messages), "},{"text":"selective perception","bold":true},{"text":" (noticing and interpreting messages to fit existing beliefs), "},{"text":"selective retention","bold":true},{"text":" (remembering mainly what supports existing beliefs)."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" differences in values, gestures, customs and language between groups or countries."}]},{"text":[{"text":"Organisational (status):","bold":true},{"text":" too many levels of authority, rigid rules, status gaps, poor structure; junior staff fear speaking to top management."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" receiving more messages than one can process, so important ones are missed or read late."}]},{"text":[{"text":"Poor listening and lack of feedback.","bold":true}]}]},{"type":"paragraph","text":[{"text":"How to overcome barriers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Use "},{"text":"simple, clear language","bold":true},{"text":" suited to the receiver; avoid jargon."}]},{"text":[{"text":"Encourage feedback","bold":true},{"text":" to check understanding; ask questions."}]},{"text":[{"text":"Practise "},{"text":"active listening","bold":true},{"text":"."}]},{"text":[{"text":"Choose the "},{"text":"right channel","bold":true},{"text":" and timing; use rich channels for complex messages."}]},{"text":[{"text":"Understand the receiver's "},{"text":"culture and field of experience","bold":true},{"text":"."}]},{"text":[{"text":"Reduce physical noise and fix equipment."}]},{"text":[{"text":"Cut unnecessary levels of authority; keep an open-door policy."}]},{"text":[{"text":"Prioritise and filter messages to reduce overload."}]},{"text":[{"text":"Control emotions; wait for a calm moment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Semantic:","bold":true},{"text":" an insurance agent explains a policy to market women in Aba using \"indemnity\", \"actuarial loading\" and \"subrogation\". They leave confused. Jargon is a semantic barrier."}]},{"text":[{"text":"Psychological:","bold":true},{"text":" a customer wrongly debited is so angry he does not listen to the bank officer. Emotion is the barrier."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" a foreign firm's advert uses a hand gesture friendly at home but rude to many Nigerians. This is cultural, not semantic (no jargon is involved)."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" a bank officer gets over 200 emails a day and misses her manager's messages."}]},{"text":[{"text":"Organisational:","bold":true},{"text":" junior staff of a large Lagos firm fear reporting problems to the MD because of many levels and his high status."}]},{"text":[{"text":"Selective perception vs selective retention:","bold":true},{"text":" perception is how you "},{"text":"notice and interpret","bold":true},{"text":" a message now; retention is what you "},{"text":"remember","bold":true},{"text":" later. A loyal Indomie buyer who notices only the good points of an Indomie advert shows selective perception; one who later forgets a rival noodle brand's price cut shows selective retention."}]},{"text":[{"text":"Not a barrier:","bold":true},{"text":" active listening is a cure, not a barrier. Physical noise, jargon and emotional stress are all barriers."}]},{"text":[{"text":"Best cure trap:","bold":true},{"text":" using more technical terms, avoiding the receiver's questions or blasting one message through every channel at once do not overcome barriers. Simple language plus feedback does."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication comes from Latin "},{"text":"communis","bold":true},{"text":" (common): transmitting information and shared meaning; effective when the receiver's meaning matches the sender's."}]},{"text":[{"text":"7 Cs: clarity, conciseness, concreteness, correctness, completeness, consideration, courtesy."}]},{"text":[{"text":"Business communication = exchange of information "},{"text":"within and outside","bold":true},{"text":" the organisation to achieve its goals; purposes: inform, persuade, coordinate, instruct, build relationships."}]},{"text":[{"text":"Forms: internal/external; formal/informal (grapevine: fast but distorted); downward, upward, horizontal, diagonal; oral, written, non-verbal, visual."}]},{"text":[{"text":"Non-verbal: kinesics (body), paralanguage (voice), proxemics (space), chronemics (time), haptics (touch)."}]},{"text":[{"text":"Oral gives immediate feedback; written gives a permanent record. Face-to-face is the richest channel."}]},{"text":[{"text":"Process: sender, encoding, message, channel, decoding, receiver, response, feedback, noise, field of experience."}]},{"text":[{"text":"Models: Lasswell 1948 (who says what...), Shannon-Weaver 1949 (linear, noise, no feedback), Schramm 1954 (interactive, field of experience), transactional (simultaneous sending and receiving)."}]},{"text":[{"text":"Barriers: physical, semantic, psychological, perceptual, cultural, organisational, information overload; cure with simple language and feedback."}]}]}],"theory":{"itemId":"c9a5202d-1616-506e-a213-b4b275bba75d","question":[{"type":"paragraph","text":[{"text":"Using a Nigerian example, explain the elements of the communication process and show two points at which noise can occur."}]}]},"practice":[{"topic":"Communication, Business Communication and the Communication Process","named":false}]}},{"itemId":"c4d68f51-fe6b-5f7d-b82b-5182b349591f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:6","parentItemId":null,"revision":1,"payload":{"title":"Marketing Communication in the Internet Era, Social Media and Word-of-Mouth","body":"How the internet changed marketing communication (Hotmail 1996, MySpace, Facebook and Twitter, monologue to dialogue, many-to-many, consumer power, pull); interactivity; social media marketing and the types of platforms; roles, advantages and risks of social media; reach, impressions, organic reach and engagement; paid, owned and earned media; user-generated content, influencers and brand advocates; word-of-mouth, eWOM, viral, buzz, seeding and referral marketing; managing WOM.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"How the internet changed marketing communication (Hotmail 1996, MySpace, Facebook and Twitter, monologue to dialogue, many-to-many, consumer power, pull); interactivity; social media marketing and the types of platforms; roles, advantages and risks of social media; reach, impressions, organic reach and engagement; paid, owned and earned media; user-generated content, influencers and brand advocates; word-of-mouth, eWOM, viral, buzz, seeding and referral marketing; managing WOM."}],"lessons":[{"number":"6.1","title":"How the internet changed marketing communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The road to the internet era:","bold":true},{"text":" printing press (Johannes Gutenberg, 15th century) gave print advertising; first printed adverts in "},{"text":"17th-century newspapers","bold":true},{"text":"; radio commercials from the "},{"text":"1920s","bold":true},{"text":"; television dominant by the "},{"text":"1950s","bold":true},{"text":"; the "},{"text":"Internet in the late 20th century","bold":true},{"text":" ushered in the digital age, with "},{"text":"websites as virtual storefronts","bold":true},{"text":" and "},{"text":"email as a direct line to customers","bold":true},{"text":"."}]},{"text":[{"text":"Hotmail, 1996:","bold":true},{"text":" one of the earliest successful digital marketing cases. It added "},{"text":"\"Get your free email at Hotmail\"","bold":true},{"text":" to every email its users sent and gained "},{"text":"millions of users within months","bold":true},{"text":". This is "},{"text":"viral marketing","bold":true},{"text":"."}]},{"text":[{"text":"Early 2000s:","bold":true},{"text":" "},{"text":"MySpace, Facebook and Twitter","bold":true},{"text":" rose and changed how businesses interact with audiences. "},{"text":"Social media turned marketing into a two-way conversation","bold":true},{"text":", letting brands engage directly with customers."}]},{"text":[{"text":"Many-to-many communication:","bold":true},{"text":" grown on the back of the highly developed Internet, e.g. "},{"text":"online chat rooms, blogging websites","bold":true},{"text":", discussion forums. (The other three types: one-to-many, many-to-one, one-to-one.)"}]},{"text":[{"text":"Interactivity:","bold":true},{"text":" firms and consumers can communicate "},{"text":"in both directions","bold":true},{"text":" and respond to each other's messages, often in real time."}]}]},{"type":"paragraph","text":[{"text":"The key changes","bold":true},{"text":" (what marketing communication in the internet era is distinguished by):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"From a "},{"text":"one-way monologue","bold":true},{"text":" (firm to customer) to a "},{"text":"two-way conversation","bold":true},{"text":" (dialogue). This is the most important change."}]},{"text":[{"text":"Greater interactivity, real-time engagement and integration","bold":true},{"text":" across many channels."}]},{"text":[{"text":"Speed and reach:","bold":true},{"text":" messages spread faster and reach "},{"text":"global","bold":true},{"text":" audiences."}]},{"text":[{"text":"Greater consumer power and control:","bold":true},{"text":" consumers compare prices, read reviews and share opinions publicly."}]},{"text":[{"text":"A move towards "},{"text":"pull communication:","bold":true},{"text":" consumers search, follow pages and choose what content to watch."}]},{"text":[{"text":"Measurability:","bold":true},{"text":" clicks, views and shares can be measured quickly and accurately."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" using data about the audience."}]},{"text":[{"text":"Word-of-mouth amplified","bold":true},{"text":" through online reviews, shares and influencer endorsements."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: the internet era did "},{"text":"not","bold":true},{"text":" reduce customer interaction, did "},{"text":"not","bold":true},{"text":" limit firms to traditional media, did "},{"text":"not","bold":true},{"text":" reduce feedback and did "},{"text":"not","bold":true},{"text":" reduce advertising options. Every option of that kind is wrong."}]},{"text":[{"text":"Push versus pull: a TV advert interrupts you (push); you searching \"best blender in Lagos\" and reading reviews on Jumia is pull. The internet did not remove push communication; it shifted the balance towards pull."}]},{"text":[{"text":"Audiences now have more choices than ever, are more confident and outspoken, and their media habits have changed. This is also why integrated marketing communication (IMC) matters more: many channels must carry one unified message."}]},{"text":[{"text":"Marketing communication is ever-evolving: understanding its history from the printing press to social media helps firms anticipate future trends."}]}]}]},{"number":"6.2","title":"Social media marketing and types of platforms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social media marketing:","bold":true},{"text":" using social media platforms (such as Facebook, Instagram, X (Twitter), LinkedIn, TikTok, YouTube) to "},{"text":"engage audiences, build the brand, and drive traffic and sales","bold":true},{"text":", by delivering "},{"text":"targeted, interactive content","bold":true},{"text":"."}]},{"text":[{"text":"Its effectiveness comes mainly from "},{"text":"two-way communication and real-time interaction","bold":true},{"text":" with customers."}]},{"text":[{"text":"It lets firms deliver "},{"text":"closely targeted messages based on data about their audience","bold":true},{"text":" (age, location, interests)."}]}]},{"type":"paragraph","text":[{"text":"Types of social media platforms","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Main use"}],[{"text":"Examples"}]],"rows":[[[{"text":"Social networks"}],[{"text":"Connecting with friends, family and brands"}],[{"text":"Facebook"}]],[[{"text":"Media-sharing networks"}],[{"text":"Sharing photos and videos"}],[{"text":"YouTube, Instagram, TikTok"}]],[[{"text":"Microblogging"}],[{"text":"Short, fast public posts and conversations"}],[{"text":"X (Twitter)"}]],[[{"text":"Professional networks"}],[{"text":"Careers and business contacts (strong for B2B)"}],[{"text":"LinkedIn"}]],[[{"text":"Messaging apps"}],[{"text":"Private one-to-one and group chats"}],[{"text":"WhatsApp, Telegram"}]],[[{"text":"Blogs and forums"}],[{"text":"Longer posts and many-to-many discussion"}],[{"text":"Blogs, Nairaland, Reddit"}]],[[{"text":"Review sites"}],[{"text":"Ratings and reviews of products and places"}],[{"text":"Google reviews, store review pages"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing "},{"text":"valuable, relevant content","bold":true},{"text":" (articles, videos, tips) to "},{"text":"attract and keep","bold":true},{"text":" a target audience."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search engines (Google) and online banking platforms are "},{"text":"not","bold":true},{"text":" social media. YouTube, Instagram and TikTok are media-sharing networks; LinkedIn is the professional network."}]},{"text":[{"text":"A recipe brand posting short cooking videos using its seasoning on TikTok is content marketing on a media-sharing network: the audience gets something useful, and the brand stays in mind."}]},{"text":[{"text":"Social media marketing does "},{"text":"not","bold":true},{"text":" replace all other forms of marketing communication, does not work without content, and does not mean sending one message to everyone with no targeting."}]}]}]},{"number":"6.3","title":"Roles, advantages, risks and measures of social media","mustKnow":[{"type":"paragraph","text":[{"text":"Roles of social media in marketing communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Foster dialogue, build communities and strengthen customer relationships","bold":true},{"text":" (the strategic role)."}]},{"text":[{"text":"Allow direct engagement","bold":true},{"text":" with customers."}]},{"text":[{"text":"Provide customer insights","bold":true},{"text":" (what people like, complain about, want)."}]},{"text":[{"text":"Increase brand visibility, affinity and long-term loyalty.","bold":true}]},{"text":[{"text":"Give "},{"text":"real-time feedback","bold":true},{"text":"."}]},{"text":[{"text":"Support customer service and drive traffic and sales."}]}]},{"type":"paragraph","text":[{"text":"Advantages:","bold":true},{"text":" precise targeting at relatively low cost; direct two-way interaction; quick, real-time feedback; measurable responses (clicks, shares, views); reach to large audiences."}]},{"type":"paragraph","text":[{"text":"Risks:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Loss of control over the message:","bold":true},{"text":" customers can comment, share and change its meaning. Social media never gives full control over what customers say."}]},{"text":[{"text":"Negative eWOM spreads quickly","bold":true},{"text":" and damages reputation."}]},{"text":[{"text":"Hashtag hijacking:","bold":true},{"text":" people use a brand's hashtag for complaints or mockery instead of the intended purpose."}]},{"text":[{"text":"Fake reviews and astroturfing","bold":true},{"text":" mislead customers."}]},{"text":[{"text":"Influencer scandals","bold":true},{"text":" damage the brand's image."}]}]},{"type":"paragraph","text":[{"text":"Key terms:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Community management:","bold":true},{"text":" the ongoing work of building and managing relationships with online followers (replying to comments, answering questions)."}]},{"text":[{"text":"Social listening:","bold":true},{"text":" monitoring online conversations to learn what people say about a brand, its competitors and its industry."}]},{"text":[{"text":"Engagement:","bold":true},{"text":" likes, comments, shares (and saves, clicks) on a post."}]},{"text":[{"text":"Reach:","bold":true},{"text":" the number of "},{"text":"different people","bold":true},{"text":" who saw the content."}]},{"text":[{"text":"Impressions:","bold":true},{"text":" the "},{"text":"total number of times","bold":true},{"text":" the content was displayed (one person can produce several)."}]},{"text":[{"text":"Organic reach:","bold":true},{"text":" people who see content "},{"text":"without the brand paying","bold":true},{"text":" to promote it. Because platforms decide what appears in feeds, organic reach is often low, so brands "},{"text":"pay to boost posts","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Swap trap: reach counts "},{"text":"people","bold":true},{"text":", impressions count "},{"text":"displays","bold":true},{"text":". Impressions are always equal to or greater than reach. Frequency = impressions ÷ reach."}]},{"text":[{"text":"Worked example: a Lagos fashion store boosts a post for ₦30,000. It reaches 12,000 people, records 30,000 impressions and gets 900 likes, comments and shares."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frequency = 30,000 ÷ 12,000 = 2.5 views per person."}]},{"text":[{"text":"Cost per 1,000 impressions (CPM) = (₦30,000 ÷ 30,000) × 1,000 = ₦1,000."}]},{"text":[{"text":"Engagement rate (one common method, by reach) = 900 ÷ 12,000 × 100 = 7.5%."}]},{"text":[{"text":"Cost per engagement = ₦30,000 ÷ 900 = ₦33.33 (rounded to the nearest kobo)."}]}]}]},{"text":[{"text":"Real-time feedback: a Lagos bakery posts two new cake flavours in the morning; by evening the comments show which one customers prefer, so it bakes more of that one."}]},{"text":[{"text":"\"Reaching large audiences at relatively low cost\" is an "},{"text":"advantage","bold":true},{"text":", never a risk. A firm's electricity bill or staff numbers are not social media measures."}]},{"text":[{"text":"Hashtag hijacking example: McDonald's #McDStories (2012) invited happy stories but attracted complaints."}]}]}]},{"number":"6.4","title":"UGC, influencers, advocates and paid, owned, earned media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"User-generated content (UGC):","bold":true},{"text":" content such as reviews, photos and videos about a brand "},{"text":"created by customers rather than by the brand","bold":true},{"text":"."}]},{"text":[{"text":"Social media influencer:","bold":true},{"text":" a person who has "},{"text":"built a following online","bold":true},{"text":" and can "},{"text":"affect the opinions and purchases","bold":true},{"text":" of that audience. Influencers are the online version of "},{"text":"opinion leaders","bold":true},{"text":" (two-step flow)."}]},{"text":[{"text":"Micro-influencers","bold":true},{"text":" (compared with celebrity/mega influencers): "},{"text":"smaller, more specialised audiences","bold":true},{"text":", often "},{"text":"higher engagement and trust","bold":true},{"text":", and lower fees. Mega influencers have much larger audiences and much higher fees."}]},{"text":[{"text":"Disclosure:","bold":true},{"text":" an influencer must clearly label a paid partnership "},{"text":"so that followers know it is advertising and are not misled","bold":true},{"text":"."}]},{"text":[{"text":"Brand advocates:","bold":true},{"text":" loyal customers who "},{"text":"voluntarily recommend and defend","bold":true},{"text":" a brand, "},{"text":"without being paid","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Paid, owned and earned media","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Paid"}],[{"text":"Media space the firm "},{"text":"buys","bold":true}],[{"text":"Boosted or sponsored Instagram post, Facebook ad, TV ad"}]],[[{"text":"Owned"}],[{"text":"Channels the firm "},{"text":"controls","bold":true}],[{"text":"Official website, Instagram page, company blog, app"}]],[[{"text":"Earned"}],[{"text":"Exposure gained "},{"text":"free","bold":true},{"text":" through customers, fans and the press"}],[{"text":"Shares, reviews, UGC, a free newspaper feature"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customers of a Lekki restaurant post their own photos of its jollof rice with its hashtag, unpaid: "},{"text":"UGC","bold":true},{"text":" (and earned media), not paid advertising or sales promotion."}]},{"text":[{"text":"Choosing influencers: a small Abuja skincare brand with ₦200,000 wanting believable recommendations to women who follow skincare closely should use "},{"text":"several micro-influencers who focus on skincare","bold":true},{"text":", not one celebrity musician or a TV commercial. Fit and trust beat raw follower numbers."}]},{"text":[{"text":"In Nigeria advertising, including on digital platforms, is regulated by "},{"text":"ARCON","bold":true},{"text":" (Advertising Regulatory Council of Nigeria, formerly APCON). Honest labelling protects followers and the brand's credibility."}]},{"text":[{"text":"A free newspaper story about a Lagos fintech app after customers praised it online is "},{"text":"earned","bold":true},{"text":" media. A firm's own blog is "},{"text":"owned","bold":true},{"text":". A brand advocate differs from a paid influencer: the advocate is unpaid."}]}]}]},{"number":"6.5","title":"Word-of-mouth, eWOM, viral and buzz marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Word-of-mouth (WOM):","bold":true},{"text":" informal person-to-person communication among consumers about products, services and brands; customers share their experiences with peers and friends about goods and services they bought recently. It is one of the most widely practised communication tools."}]},{"text":[{"text":"Why WOM is credible:","bold":true},{"text":" it comes from people seen as "},{"text":"independent of the firm and not paid","bold":true},{"text":" to promote the product. It "},{"text":"builds trust, credibility and purchase intent through peer influence","bold":true},{"text":"."}]},{"text":[{"text":"Electronic word-of-mouth (eWOM):","bold":true},{"text":" positive or negative statements made by "},{"text":"potential, actual or former customers","bold":true},{"text":" about a product or company, made available to "},{"text":"many people through the internet","bold":true},{"text":" (tweets, online reviews, forum posts)."}]},{"text":[{"text":"eWOM vs WOM:","bold":true},{"text":" eWOM reaches "},{"text":"many more people, faster","bold":true},{"text":", and "},{"text":"stays available online for a long time","bold":true},{"text":"; it can be positive or negative."}]},{"text":[{"text":"Online WOM is dynamic:","bold":true},{"text":" its impact can be "},{"text":"positive or negative","bold":true},{"text":" depending on customers' feelings and experiences."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" creating content so interesting that people "},{"text":"pass it on","bold":true},{"text":", spreading it rapidly online. Content goes viral when it is "},{"text":"emotional, entertaining or useful","bold":true},{"text":" enough to share. "},{"text":"Limitation:","bold":true},{"text":" firms "},{"text":"cannot guarantee","bold":true},{"text":" it will spread or "},{"text":"control how people interpret","bold":true},{"text":" it."}]},{"text":[{"text":"Buzz marketing:","bold":true},{"text":" getting "},{"text":"opinion leaders and early users talking","bold":true},{"text":" about a product so excitement spreads to others."}]},{"text":[{"text":"Seeding:","bold":true},{"text":" giving a new product or content to selected "},{"text":"well-connected people first","bold":true},{"text":" so they share it with their networks."}]},{"text":[{"text":"Referral marketing:","bold":true},{"text":" rewarding existing customers for bringing in new ones (e.g. ₦500 per friend who signs up with a personal code). It encourages WOM."}]},{"text":[{"text":"Astroturfing:","bold":true},{"text":" creating "},{"text":"fake reviews or fake \"ordinary customer\" accounts","bold":true},{"text":" to fake genuine public support. It is unethical."}]}]},{"type":"paragraph","text":[{"text":"Managing WOM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Deliver good products and service (the source of positive WOM)."}]},{"text":[{"text":"Seed and use opinion leaders, influencers and advocates; run referral schemes."}]},{"text":[{"text":"Make sharing easy (hashtags, share buttons, review requests)."}]},{"text":[{"text":"Listen (social listening) and engage (community management)."}]},{"text":[{"text":"When negative posts spread, "},{"text":"respond quickly, honestly and politely, and address the problem openly","bold":true},{"text":". Do not argue, ignore, or delete and block critics."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"WOM is "},{"text":"not","bold":true},{"text":" fully controlled by the company, is "},{"text":"not","bold":true},{"text":" free of strategy, does "},{"text":"not","bold":true},{"text":" spread only face to face and is "},{"text":"not","bold":true},{"text":" less relevant online: the internet "},{"text":"amplified","bold":true},{"text":" it."}]},{"text":[{"text":"Amaka reading 40 buyer reviews of a blender on an online store before buying: "},{"text":"eWOM","bold":true},{"text":". A company's television commercial is "},{"text":"not","bold":true},{"text":" eWOM (it is paid advertising from the firm)."}]},{"text":[{"text":"A customer's video complaint about a bank branch in Ikeja, shared thousands of times in a day, shows the risk of "},{"text":"negative eWOM spreading fast","bold":true},{"text":". The bank should reply publicly, apologise where due, and fix the issue."}]},{"text":[{"text":"Buzz and seeding often work together: a phone brand gives early units to Nigerian tech reviewers (seeding) to get people talking (buzz). Hotmail's footer is the classic case of viral spread."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internet era = monologue to dialogue, interactivity, speed, global reach, consumer power, pull, measurability, targeting."}]},{"text":[{"text":"Hotmail 1996 \"Get your free email at Hotmail\" = viral; MySpace, Facebook, Twitter (early 2000s) made marketing two-way."}]},{"text":[{"text":"Many-to-many = chat rooms, blogs, forums."}]},{"text":[{"text":"Social media marketing = engage audiences, build the brand, drive traffic and sales with targeted, interactive content."}]},{"text":[{"text":"Roles: dialogue, communities, relationships, insights, visibility and loyalty. Biggest risk: loss of control."}]},{"text":[{"text":"Reach = different people; impressions = total displays; organic = unpaid."}]},{"text":[{"text":"Paid = bought; owned = controlled; earned = free from customers, fans, press."}]},{"text":[{"text":"Influencers = online opinion leaders; micro = smaller, specialised, higher trust; disclose paid posts."}]},{"text":[{"text":"WOM credible because independent and unpaid; eWOM = online, faster, wider, lasting."}]},{"text":[{"text":"Viral = passed on; buzz = opinion leaders talking; seeding = give to connectors first; astroturfing = fake support; answer negative posts quickly, honestly, politely."}]}]}],"theory":{"itemId":"0227e2a3-f51d-5204-8306-be19cdc71765","question":[{"type":"paragraph","text":[{"text":"A brand pays ₦40,000 to boost a TikTok video. It reaches 8,000 people, each seeing it 3 times on average, and gets 360 likes, comments and shares. Find (a) impressions, (b) engagement rate by reach, (c) cost per 1,000 impressions. State whether the boost is paid, owned or earned media."}]}]},"practice":[{"topic":"MarCom in the Internet Era, Social Media and Word-of-Mouth","named":false}]}},{"itemId":"0a278429-8e6c-5cd3-b064-7439ab187940","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:7","parentItemId":null,"revision":1,"payload":{"title":"Communication in Market Relationships","body":"Market (transactional) versus relational exchange; relationship marketing, trust and commitment, retention, loyalty, churn and customer lifetime value; the role of communication in the relationship with the market; the interactional, relational (contextual) and network approaches to communication and how each differs from the linear model.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"Market (transactional) versus relational exchange; relationship marketing, trust and commitment, retention, loyalty, churn and customer lifetime value; the role of communication in the relationship with the market; the interactional, relational (contextual) and network approaches to communication and how each differs from the linear model."}],"lessons":[{"number":"7.1","title":"Market exchange and relational exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exchange process:","bold":true},{"text":" obtaining a desired object from someone by offering something of value in return. A completed exchange is a "},{"text":"transaction","bold":true},{"text":"."}]},{"text":[{"text":"5 conditions for exchange:","bold":true},{"text":" (1) at least two parties; (2) each has something that might be of value to the other; (3) each can communicate and deliver what it offers; (4) each is free to accept or reject the offer; (5) each party "},{"text":"trusts/respects","bold":true},{"text":" the other sufficiently to take the exchange seriously."}]},{"text":[{"text":"Two types of exchange most readily observed in marketing:","bold":true},{"text":" "},{"text":"market","bold":true},{"text":" exchange and "},{"text":"relational","bold":true},{"text":" exchange. Marketing communication plays roles in "},{"text":"both","bold":true},{"text":"."}]},{"text":[{"text":"Market (transactional) exchange:","bold":true},{"text":" a "},{"text":"one-off, short-term","bold":true},{"text":" exchange focused mainly on the "},{"text":"product and its price","bold":true},{"text":". The relationship "},{"text":"ends once the goods and payment have changed hands","bold":true},{"text":"."}]},{"text":[{"text":"Relational exchange:","bold":true},{"text":" an "},{"text":"ongoing","bold":true},{"text":" exchange in which buyer and seller "},{"text":"build trust and interact repeatedly over time","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Market (transactional) exchange"}],[{"text":"Relational exchange"}]],"rows":[[[{"text":"Time scale"}],[{"text":"Short, one-off"}],[{"text":"Long-term, ongoing"}]],[[{"text":"Main focus"}],[{"text":"Product and price"}],[{"text":"Relationship, customer value"}]],[[{"text":"Contact after sale"}],[{"text":"None expected"}],[{"text":"Regular, two-way"}]],[[{"text":"Basis"}],[{"text":"Bargain on the deal"}],[{"text":"Trust and commitment"}]],[[{"text":"Parties"}],[{"text":"Independent"}],[{"text":"Interdependent"}]],[[{"text":"Role of MarCom"}],[{"text":"Inform and persuade so a sale is completed"}],[{"text":"Build and maintain trust, commitment and dialogue"}]]]},{"type":"paragraph","text":[{"text":"Characteristics of relational exchange:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Long-term orientation towards keeping the customer."}]},{"text":[{"text":"Trust and commitment between buyer and seller."}]},{"text":[{"text":"Regular two-way communication and feedback over time."}]},{"text":[{"text":"Interdependence:","bold":true},{"text":" each party relies on the other and gains from continuing the relationship."}]},{"text":[{"text":"Cooperation, such as joint planning and shared problem-solving."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Chidi bargains with a hawker at a Lagos bus stop, pays ₦2,500 for a used phone charger, and neither expects to meet again: a "},{"text":"market (transactional) exchange","bold":true},{"text":"."}]},{"text":[{"text":"A cement manufacturer and an Abuja construction firm have dealt with each other for eight years, share delivery schedules, plan supply together and meet regularly to solve problems: a "},{"text":"relational exchange","bold":true},{"text":". \"Barter\" and \"spot purchase\" are wrong here."}]},{"text":[{"text":"Even a single transaction needs a "},{"text":"basic level of trust","bold":true},{"text":" (condition 5). It does not need a long-term written contract, the lowest price or television advertising."}]},{"text":[{"text":"Trap: \"focus on completing a single sale with no further contact\" is the one statement that is "},{"text":"not","bold":true},{"text":" a characteristic of relational exchange."}]},{"text":[{"text":"The shift: there is a strong "},{"text":"paradigm shift","bold":true},{"text":" away from reliance on one-off market exchanges towards a longer-term perspective that creates and maintains enduring partnerships. This approach is "},{"text":"relationship marketing","bold":true},{"text":". Partnerships between brands and consumers, and between organisations within distribution channels or networks, are a vital perspective of marketing communication."}]},{"text":[{"text":"Options that exams swap in for the two types: barter and monetary, direct and indirect, internal and external. None of these is the correct pair; the answer is "},{"text":"market and relational","bold":true},{"text":"."}]}]}]},{"number":"7.2","title":"Relationship marketing, trust and commitment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relationship marketing:","bold":true},{"text":" attracting, maintaining and enhancing "},{"text":"long-term relationships","bold":true},{"text":" with customers (Berry). The idea behind it: \"Marketing is not just about selling products; it is about building relationships and creating value.\""}]},{"text":[{"text":"Trust:","bold":true},{"text":" a customer's "},{"text":"confidence in a supplier's reliability and integrity","bold":true},{"text":" (Morgan and Hunt)."}]},{"text":[{"text":"Commitment:","bold":true},{"text":" an "},{"text":"enduring desire to maintain a valued relationship","bold":true},{"text":" (Moorman, Zaltman and Deshpande)."}]},{"text":[{"text":"Trust and commitment","bold":true},{"text":" are the "},{"text":"two variables central to the success of relationship marketing","bold":true},{"text":" (Morgan and Hunt's commitment-trust theory)."}]},{"text":[{"text":"Dialogue:","bold":true},{"text":" communication in which both parties listen, respond and build shared understanding together."}]}]},{"type":"paragraph","text":[{"text":"Transactional marketing versus relationship marketing:","bold":true}]},{"type":"table","header":[[{"text":"Transactional marketing"}],[{"text":"Relationship marketing"}]],"rows":[[[{"text":"Focus on the single sale"}],[{"text":"Focus on customer retention"}]],[[{"text":"Orientation on product features"}],[{"text":"Orientation on customer value and benefits"}]],[[{"text":"Short time scale"}],[{"text":"Long time scale"}]],[[{"text":"Little emphasis on customer service"}],[{"text":"High emphasis on customer service"}]],[[{"text":"Limited customer commitment"}],[{"text":"High customer commitment"}]],[[{"text":"Moderate customer contact"}],[{"text":"High customer contact"}]],[[{"text":"Quality is mainly a concern of production"}],[{"text":"Quality is a concern of all staff"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trust in action: for five years a Kano wholesaler has delivered rice on the agreed date, in the agreed quantity and at the agreed price, so the retailer now orders without checking every bag. That quality is "},{"text":"trust","bold":true},{"text":" (not impulse buying, cognitive dissonance or brand switching)."}]},{"text":[{"text":"Commitment in action: Aisha has banked with the same bank for ten years. A rival offers a slightly better savings rate, but she stays because she values her account officer and the bank. That is "},{"text":"commitment to the relationship","bold":true},{"text":", the opposite of price sensitivity, a transactional orientation or brand switching."}]},{"text":[{"text":"Trap: trust is about "},{"text":"confidence","bold":true},{"text":" in the partner; commitment is about the "},{"text":"desire to stay","bold":true},{"text":". Satisfaction and awareness are not the names for either."}]},{"text":[{"text":"Trap: \"high emphasis on customer service and long-term contact\" is "},{"text":"not","bold":true},{"text":" typical of a transactional approach. Compared with transactional marketing, relationship marketing focuses more on "},{"text":"customer value and benefits over a long time scale","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian example: a telecom operator such as MTN or Airtel that sends each subscriber a personalised birthday message with bonus airtime, while its care team remembers past complaints, is practising "},{"text":"relationship marketing","bold":true},{"text":" (not price skimming, mass marketing or transactional marketing)."}]}]}]},{"number":"7.3","title":"Retention, loyalty and customer lifetime value","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer retention:","bold":true},{"text":" a firm's ability to "},{"text":"keep its existing customers buying from it over time","bold":true},{"text":". Attracting first-time buyers is "},{"text":"acquisition","bold":true},{"text":", not retention."}]},{"text":[{"text":"Why retention matters:","bold":true},{"text":" keeping an existing customer "},{"text":"usually costs less than attracting a new one","bold":true},{"text":" (often quoted as up to five times less)."}]},{"text":[{"text":"Customer loyalty:","bold":true},{"text":" a customer's "},{"text":"continued preference for and repeat purchase","bold":true},{"text":" of a firm's brand over time."}]},{"text":[{"text":"Customer churn (defection):","bold":true},{"text":" the "},{"text":"rate at which customers stop doing business","bold":true},{"text":" with a firm over a period."}]},{"text":[{"text":"Customer lifetime value (CLV):","bold":true},{"text":" the "},{"text":"total value","bold":true},{"text":" a customer is expected to bring to a firm "},{"text":"over the whole relationship","bold":true},{"text":"."}]},{"text":[{"text":"Ladder of loyalty (in order):","bold":true},{"text":" prospect, customer, client, supporter, "},{"text":"advocate","bold":true},{"text":" (and, at the top in some versions, partner). An "},{"text":"advocate actively recommends","bold":true},{"text":" the firm to other people."}]}]},{"type":"paragraph","text":[{"text":"Formulas (plain text):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Churn rate (%) = customers lost during the period / customers at the start of the period x 100"}]},{"text":[{"text":"Retention rate (%) = 100 - churn rate (when no new customers are counted)"}]},{"text":[{"text":"CLV (revenue) = average spend per purchase x purchases per year x expected years of relationship"}]},{"text":[{"text":"CLV (profit) = CLV (revenue) x profit margin"}]}]},{"type":"paragraph","text":[{"text":"Benefits of strong customer relationships:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More repeat purchases."}]},{"text":[{"text":"Customers less likely to switch to rivals."}]},{"text":[{"text":"Positive word-of-mouth recommendations."}]},{"text":[{"text":"Lower cost of serving and keeping customers than of winning new ones."}]},{"text":[{"text":"Higher customer lifetime value."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"customers who buy once and never return\" is "},{"text":"not","bold":true},{"text":" a benefit of strong relationships."}]},{"text":[{"text":"A loyalty card at an Ikeja supermarket that earns points redeemable for gifts exists to "},{"text":"encourage repeat purchases and retain customers","bold":true},{"text":"."}]},{"text":[{"text":"Trap: CLV is not the value of the first purchase, nor the price of the most expensive product."}]},{"text":[{"text":"Worked example (churn):","bold":true},{"text":" a Lagos gym starts the year with 2,000 members and 150 leave."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Churn rate = 150 / 2,000 x 100 = "},{"text":"7.5%","bold":true},{"text":"."}]},{"text":[{"text":"Retention rate = 100 - 7.5 = "},{"text":"92.5%","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example (CLV):","bold":true},{"text":" a customer spends ₦6,000 per visit at a restaurant, visits 4 times a month and is expected to stay 5 years; profit margin is 20%."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Visits per year = 4 x 12 = 48."}]},{"text":[{"text":"Spend per year = ₦6,000 x 48 = ₦288,000."}]},{"text":[{"text":"CLV (revenue) = ₦288,000 x 5 = "},{"text":"₦1,440,000","bold":true},{"text":"."}]},{"text":[{"text":"CLV (profit) = ₦1,440,000 x 0.20 = "},{"text":"₦288,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"The lesson of CLV: a ₦6,000 customer is really worth ₦1,440,000 in sales over the relationship, which is why firms spend on communication that keeps people."}]}]}]},{"number":"7.4","title":"The role of communication in the relationship with the market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Role of communication in market relationships:","bold":true},{"text":" to "},{"text":"build trust, loyalty and lasting customer commitment","bold":true},{"text":"."}]},{"text":[{"text":"Fundamental aim:","bold":true},{"text":" to "},{"text":"increase customer trust, satisfaction and retention","bold":true},{"text":"."}]},{"text":[{"text":"Strategic aim:","bold":true},{"text":" to "},{"text":"strengthen customer loyalty through consistent delivery of value","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Roles of communication in a market relationship:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Builds and maintains "},{"text":"trust","bold":true},{"text":" by keeping promises visible and consistent."}]},{"text":[{"text":"Strengthens "},{"text":"commitment","bold":true},{"text":" and loyalty."}]},{"text":[{"text":"Opens "},{"text":"dialogue","bold":true},{"text":": listens to customers and responds to feedback and complaints."}]},{"text":[{"text":"Keeps customers "},{"text":"informed","bold":true},{"text":" after the sale (updates, service, new offers)."}]},{"text":[{"text":"Coordinates","bold":true},{"text":" with partners in the network (suppliers, distributors, agencies)."}]},{"text":[{"text":"Turns satisfied customers into "},{"text":"advocates","bold":true},{"text":" who spread positive word-of-mouth."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Every wrong option in this area describes the opposite of relationship building: completing a single sale with no further contact, minimising contact to save resources, avoiding customer engagement, restricting product availability to create scarcity, or chasing new customers while ignoring existing ones."}]},{"text":[{"text":"In a "},{"text":"transactional","bold":true},{"text":" exchange the main job of communication is to "},{"text":"inform and persuade","bold":true},{"text":" buyers about the offer so a sale is completed. In a "},{"text":"relational","bold":true},{"text":" exchange its job is to "},{"text":"build and maintain trust, commitment and dialogue","bold":true},{"text":"."}]},{"text":[{"text":"Example: GTBank and other Nigerian banks send transaction alerts, account statements and service updates. These messages keep the customer informed and confident, so they support retention rather than one sale."}]}]}]},{"number":"7.5","title":"Interactional and relational (contextual) approaches","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Linear model (for contrast):","bold":true},{"text":" a one-way flow of messages from a sender to a "},{"text":"passive","bold":true},{"text":" receiver who does not reply (Shannon and Weaver). The "},{"text":"hypodermic needle","bold":true},{"text":" view is a similar one-way idea."}]},{"text":[{"text":"Interactional approach:","bold":true},{"text":" views communication as a "},{"text":"two-way process","bold":true},{"text":" in which participants send messages, respond and give "},{"text":"feedback","bold":true},{"text":" to each other. It focuses on "},{"text":"two-way dialogue","bold":true},{"text":" between businesses and customers."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most central element: "},{"text":"feedback and response","bold":true},{"text":" between the parties."}]},{"text":[{"text":"Differs from the linear model because it "},{"text":"includes feedback and response, so communication flows both ways","bold":true},{"text":"."}]},{"text":[{"text":"It ensures "},{"text":"active engagement with customers and responsiveness to their needs","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Relational (contextual) approach:","bold":true},{"text":" holds that the "},{"text":"meaning of a message depends on the relationship between the participants and the context","bold":true},{"text":" of the message."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It is mainly concerned with communication that "},{"text":"develops and sustains the relationship","bold":true},{"text":" between the parties."}]},{"text":[{"text":"It is centred on "},{"text":"building lasting, value-based relationships","bold":true},{"text":" with customers, enabling firms to "},{"text":"build trust and develop long-term partnerships","bold":true},{"text":"."}]},{"text":[{"text":"It treats "},{"text":"sustained, long-term customer relationships","bold":true},{"text":" as the basis of competitive advantage."}]}]}]}]},{"type":"table","header":[[{"text":"Approach"}],[{"text":"Main focus"}]],"rows":[[[{"text":"Linear"}],[{"text":"One-way flow from sender to passive receiver"}]],[[{"text":"Interactional"}],[{"text":"Two-way message exchange with feedback"}]],[[{"text":"Relational (contextual)"}],[{"text":"Meaning shaped by the relationship and context"}]],[[{"text":"Network"}],[{"text":"Spread of messages across many connected people and organisations"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interactional example: a customer complains on social media that her data was wrongly deducted. The telecom firm replies in minutes, asks for details, she responds, the firm fixes the problem and checks back. Send, respond, feedback, follow-up: the "},{"text":"interactional approach","bold":true},{"text":". It is not the network approach because only two parties are exchanging messages."}]},{"text":[{"text":"Relational example: two suppliers send an Ibadan food processor the same message, \"Your order will arrive tomorrow.\" The processor believes the supplier it has used reliably for years but doubts the new one. Same words, different meaning, because of the "},{"text":"relationship and context","bold":true},{"text":": the "},{"text":"relational (contextual) approach","bold":true},{"text":"."}]},{"text":[{"text":"Traps: the interactional approach does not suppress feedback, keep messages one-way or stop customers replying. The relational approach does not say meaning is fixed and identical for every receiver, that only channel quality decides meaning, or that communication works best with no previous relationship."}]},{"text":[{"text":"Matching trap: interactional = "},{"text":"two-way exchange","bold":true},{"text":"; relational = "},{"text":"meaning shaped by the relationship","bold":true},{"text":". Options that swap these are wrong."}]},{"text":[{"text":"Dialogue","bold":true},{"text":" is the opposite of monologue, broadcasting and propaganda, where one party simply talks at the other."}]}]}]},{"number":"7.6","title":"The network approach to communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Network approach:","bold":true},{"text":" views communication as "},{"text":"flows of information through a web of interconnected people and organisations","bold":true},{"text":". It emphasises "},{"text":"connected exchanges among many stakeholders","bold":true},{"text":", including partners and suppliers."}]},{"text":[{"text":"Valuable for:","bold":true},{"text":" managing relationships across a "},{"text":"web of interdependent stakeholders","bold":true},{"text":"."}]},{"text":[{"text":"Supports firms by:","bold":true},{"text":" enabling "},{"text":"effective collaboration across different stakeholder groups","bold":true},{"text":"."}]},{"text":[{"text":"Well-connected members","bold":true},{"text":" (hubs, opinion leaders) matter because they "},{"text":"speed up and widen the spread","bold":true},{"text":" of messages through the network."}]},{"text":[{"text":"The network approach best explains how "},{"text":"word-of-mouth and viral messages","bold":true},{"text":" spread among consumers."}]},{"text":[{"text":"Shared feature of the three approaches:","bold":true},{"text":" interactional, relational and network approaches all treat communication as "},{"text":"more than a one-way transmission","bold":true},{"text":" from sender to receiver."}]}]},{"type":"paragraph","text":[{"text":"Stakeholders in a firm's communication network:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customers and consumers."}]},{"text":[{"text":"Suppliers."}]},{"text":[{"text":"Distributors and retailers."}]},{"text":[{"text":"Advertising and media agencies."}]},{"text":[{"text":"Regulators (for example ARCON for advertising, NCC for telecoms)."}]},{"text":[{"text":"Employees, the media and the wider community."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Viral example: a few UNILAG students share a new fintech app in class WhatsApp groups, members forward it to other groups, and within days thousands have heard. That pattern is the "},{"text":"network approach","bold":true},{"text":", not personal selling or the linear model."}]},{"text":[{"text":"Stakeholder example: a Lagos beverage company coordinates communication with suppliers, distributors, retailers, agencies and regulators, recognising that information passes among all of them: the "},{"text":"network approach","bold":true},{"text":"."}]},{"text":[{"text":"Traps: the network approach is not communication between one seller and one buyer only, not one-way mass messages, not limited to one department, and it does not remove the need to talk to suppliers."}]},{"text":[{"text":"Well-connected people do not block messages or only receive them; they pass them on to many others."}]},{"text":[{"text":"Link to Topic 6: word-of-mouth, eWOM and buzz all travel through networks, which is why firms court influencers who sit at the busy centre of a network."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Two observable types of exchange: "},{"text":"market","bold":true},{"text":" (one-off, product and price, ends at payment) and "},{"text":"relational","bold":true},{"text":" (ongoing, trust, repeated contact, interdependence)."}]},{"text":[{"text":"Relationship marketing","bold":true},{"text":" = attracting, maintaining and enhancing long-term customer relationships; it is about building relationships and creating value."}]},{"text":[{"text":"Trust","bold":true},{"text":" = confidence in reliability and integrity; "},{"text":"commitment","bold":true},{"text":" = enduring desire to maintain a valued relationship; both are central."}]},{"text":[{"text":"Retention keeps existing customers and costs less than acquisition; churn is the rate of defection; loyalty is continued preference and repeat buying; an "},{"text":"advocate","bold":true},{"text":" recommends the firm."}]},{"text":[{"text":"CLV = spend per purchase x purchases per year x years (x margin for profit)."}]},{"text":[{"text":"Communication's role: build trust, loyalty and commitment; increase satisfaction and retention."}]},{"text":[{"text":"Interactional","bold":true},{"text":" = two-way dialogue with feedback; "},{"text":"relational (contextual)","bold":true},{"text":" = meaning depends on relationship and context; "},{"text":"network","bold":true},{"text":" = flows through a web of many stakeholders; all go beyond one-way transmission."}]}]}],"theory":{"itemId":"7823aa23-a370-533f-9be6-b129116c5fc4","question":[{"type":"paragraph","text":[{"text":"Bukola buys bread worth ₦3,500 from a neighbourhood bakery twice a week, every week of the year, and is expected to stay a customer for 4 years. The bakery's profit margin is 25%. Its customer base fell from 16,000 to 15,200 over the year with no new customers counted. Calculate (a) Bukola's CLV in revenue and profit terms and (b) the bakery's churn and retention rates."}]}]},"practice":[{"topic":"Communication in Market Relationships","named":false}]}},{"itemId":"6992aa23-c414-54a4-b5a6-e91f3cc5bffd","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"note","questionId":null,"sourceKey":"guide-topic:8","parentItemId":null,"revision":1,"payload":{"title":"Online and Offline Media and Digital Marketing","body":"What offline and online media are, with examples and the merits and demerits of each; paid, owned and earned media; what digital marketing and digital marketing communication mean; how to craft a digital marketing strategy; the types of digital marketing (SEO, SEM/PPC, content, social media, email, affiliate, influencer, mobile, video, display, viral); the key digital metrics; the importance and challenges of digital marketing.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"What offline and online media are, with examples and the merits and demerits of each; paid, owned and earned media; what digital marketing and digital marketing communication mean; how to craft a digital marketing strategy; the types of digital marketing (SEO, SEM/PPC, content, social media, email, affiliate, influencer, mobile, video, display, viral); the key digital metrics; the importance and challenges of digital marketing."}],"lessons":[{"number":"8.1","title":"Offline and online communication media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication medium:","bold":true},{"text":" the channel through which a marketing message is carried to the target audience."}]},{"text":[{"text":"Offline (traditional) media:","bold":true},{"text":" established channels that do not need the internet. They are best exemplified by "},{"text":"television, radio and print advertising","bold":true},{"text":"."}]},{"text":[{"text":"Online (digital) media:","bold":true},{"text":" channels delivered through the internet and digital devices. They are best exemplified by "},{"text":"digital platforms such as social media, websites and apps","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Offline (traditional) media"}],[{"text":"Online (digital) media"}]],"rows":[[[{"text":"Television"}],[{"text":"Search engines (organic results and paid search ads)"}]],[[{"text":"Radio"}],[{"text":"Display advertising (banners on websites and apps)"}]],[[{"text":"Newspapers"}],[{"text":"Social media (Instagram, Facebook, X, TikTok, YouTube)"}]],[[{"text":"Magazines"}],[{"text":"Email marketing and newsletters"}]],[[{"text":"Outdoor (billboards, posters, transit ads on buses)"}],[{"text":"Mobile (SMS, apps, mobile sites)"}]],[[{"text":"Cinema"}],[{"text":"Company websites and blogs"}]],[[{"text":"Direct mail, flyers, brochures"}],[{"text":"Online video and podcasts"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"How the media evolved:","bold":true},{"text":" printing press (Gutenberg, 15th century) gave birth to print advertising; the first printed adverts appeared in "},{"text":"17th-century newspapers","bold":true},{"text":"; "},{"text":"radio commercials began in the 1920s","bold":true},{"text":"; by the "},{"text":"1950s television","bold":true},{"text":" became the dominant platform, combining visuals and sound; the "},{"text":"internet (late 20th century)","bold":true},{"text":" brought websites as virtual storefronts and email as a direct line to customers; the "},{"text":"early 2000s","bold":true},{"text":" brought social media (MySpace, Facebook, Twitter), turning marketing into a two-way conversation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group test trap:","bold":true},{"text":" exam options mix the two lists. \"Television, radio, newspapers and billboards\" is entirely offline. \"Websites, search engines, social media and email\" is entirely online. Any option with even one item from the other side (for example \"radio, social media, magazines and websites\") is wrong."}]},{"text":[{"text":"Odd-one-out:","bold":true},{"text":" a sponsored search engine advert is "},{"text":"not","bold":true},{"text":" offline; a painted advert on the side of a "},{"text":"danfo bus","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" online (it is outdoor, transit advertising). A banner on a news website and an email newsletter are online."}]},{"text":[{"text":"Streaming services and podcasts are online, so they never describe offline media."}]},{"text":[{"text":"One of the earliest successful pieces of digital marketing was "},{"text":"Hotmail's viral strategy in 1996","bold":true},{"text":": it added \"Get your free email at Hotmail\" to every email sent and gained millions of users within months."}]}]}]},{"number":"8.2","title":"Merits and demerits of offline and online media","mustKnow":[{"type":"table","header":[[{"text":"Medium"}],[{"text":"Merits"}],[{"text":"Demerits"}]],"rows":[[[{"text":"Television"}],[{"text":"Combines "},{"text":"sight, sound and motion","bold":true},{"text":"; reaches a "},{"text":"large mass audience","bold":true},{"text":"; strong for storytelling and emotion"}],[{"text":"High absolute cost; short exposure; clutter; viewers can switch channel"}]],[[{"text":"Radio"}],[{"text":"Low cost","bold":true},{"text":", "},{"text":"locally targeted","bold":true},{"text":", reaches people in local languages, rural and mobile listeners"}],[{"text":"Audio only","bold":true},{"text":"; fleeting message; low attention"}]],[[{"text":"Newspapers"}],[{"text":"Timeliness","bold":true},{"text":", "},{"text":"local coverage","bold":true},{"text":", broad acceptance, flexible"}],[{"text":"Short life","bold":true},{"text":"; poor reproduction quality; many ads compete on a page"}]],[[{"text":"Magazines"}],[{"text":"Long life","bold":true},{"text":", "},{"text":"high-quality colour reproduction","bold":true},{"text":", "},{"text":"selective readership","bold":true},{"text":" with specific interests, pass-along readers"}],[{"text":"Long lead time; higher cost; less timely"}]],[[{"text":"Outdoor (billboards, posters, transit)"}],[{"text":"Repeated exposure","bold":true},{"text":" to passers-by; low cost per exposure; good location selection"}],[{"text":"Carries only "},{"text":"brief messages","bold":true},{"text":"; cannot target individuals; creative limits"}]],[[{"text":"Cinema"}],[{"text":"Captive audience; big screen, sound and motion"}],[{"text":"Limited reach; expensive production"}]],[[{"text":"Online media (overall)"}],[{"text":"Interactive (two-way)","bold":true},{"text":"; "},{"text":"precise targeting","bold":true},{"text":"; "},{"text":"measurable","bold":true},{"text":" (clicks, views tracked quickly, real-time); data-driven; relatively low cost; global reach; messages can be changed fast"}],[{"text":"Does not reach people "},{"text":"without internet","bold":true},{"text":"; audiences can "},{"text":"block or skip","bold":true},{"text":" ads; heavy "},{"text":"clutter","bold":true},{"text":"; privacy concerns; negative posts spread fast"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Offline media remain relevant","bold":true},{"text":" because they reach audiences, including local ones, through established traditional channels and strengthen brand presence through "},{"text":"tangible, traditional touchpoints","bold":true},{"text":"."}]},{"text":[{"text":"Online media stand out","bold":true},{"text":" for "},{"text":"precise, interactive and data-driven","bold":true},{"text":" interaction with audiences."}]},{"text":[{"text":"Integration:","bold":true},{"text":" online and offline media can be "},{"text":"combined so that each supports the other","bold":true},{"text":" in an integrated campaign."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Choosing for the audience:","bold":true},{"text":" an agro-chemical firm reaching farmers in remote Benue villages, with poor internet but wide listening to local-language programmes, should use "},{"text":"local radio","bold":true},{"text":". Email, Instagram influencers and search ads all need the internet."}]},{"text":[{"text":"Swap traps:","bold":true},{"text":" \"Long life, colour, selective readership\" is "},{"text":"magazines","bold":true},{"text":", not newspapers. \"Timeliness and local coverage but short life\" is "},{"text":"newspapers","bold":true},{"text":". \"Repeated exposure but brief messages\" is "},{"text":"outdoor","bold":true},{"text":". \"Low cost, local and audio only\" is "},{"text":"radio","bold":true},{"text":". \"Sight, sound and motion to a mass audience\" is "},{"text":"television","bold":true},{"text":"."}]},{"text":[{"text":"NOT a limitation of online media:","bold":true},{"text":" \"results can be tracked in detail\". That is a strength."}]},{"text":[{"text":"Online media do not stop people blocking or skipping ads, do not always cost more than national TV, and cannot reach people with no internet."}]},{"text":[{"text":"Integration example:","bold":true},{"text":" a Lagos fashion brand puts a "},{"text":"QR code","bold":true},{"text":" on billboards on Third Mainland Bridge which takes viewers straight to its online store. The billboard (offline) drives traffic to the store (online): this is "},{"text":"integrating offline and online media","bold":true},{"text":". Online media have not fully replaced offline media in every market, and both channels may carry the same core message (IMC)."}]}]}]},{"number":"8.3","title":"Digital marketing, digital marketing communication and paid, owned, earned media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing:","bold":true},{"text":" the use of the "},{"text":"internet and digital channels","bold":true},{"text":" (websites, search engines, social media, email and mobile devices) to "},{"text":"promote products and engage customers","bold":true},{"text":" (build customer relationships)."}]},{"text":[{"text":"Digital marketing communication:","bold":true},{"text":" marketing messages delivered through digital channels, for example "},{"text":"targeted email campaigns and social media advertising","bold":true},{"text":". It is distinguished by "},{"text":"interactivity, measurability and adaptability","bold":true},{"text":" to audience needs, and it lets businesses "},{"text":"monitor and analyse campaign performance with real-time metrics","bold":true},{"text":"."}]},{"text":[{"text":"The 3 media types (POE):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Paid media:","bold":true},{"text":" advertising space the firm "},{"text":"buys","bold":true},{"text":" on other people's websites and platforms (search ads, display banners, sponsored social posts, influencer fees)."}]},{"text":[{"text":"Owned media:","bold":true},{"text":" channels the firm "},{"text":"controls itself","bold":true},{"text":": its website, blog, app, email list, official social media pages."}]},{"text":[{"text":"Earned media:","bold":true},{"text":" exposure the brand receives because of "},{"text":"what others say","bold":true},{"text":" about it: customer reviews, social shares, mentions and free press coverage."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Key metrics (formulas):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Click-through rate (CTR) = clicks / impressions x 100"}]},{"text":[{"text":"Conversion rate = conversions / clicks (or visitors) x 100"}]},{"text":[{"text":"Cost per click (CPC) = total spend / clicks"}]},{"text":[{"text":"Cost per conversion = total spend / conversions"}]},{"text":[{"text":"Cost per thousand impressions (CPM) = total spend / impressions x 1,000"}]}]}]},{"text":[{"text":"Impression:","bold":true},{"text":" one showing of an ad. "},{"text":"CTR:","bold":true},{"text":" the proportion of people who saw an ad and then clicked it. "},{"text":"Conversion:","bold":true},{"text":" a visitor completes a "},{"text":"desired action","bold":true},{"text":", such as making a purchase or signing up."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional TV, radio, print and billboards are not digital marketing communication. Digital communication is not one-way, fixed or hard to measure."}]},{"text":[{"text":"POE examples:","bold":true},{"text":" Jumia's own website and its official Instagram page are "},{"text":"owned","bold":true},{"text":"; Jumia buying banner space on a news site is "},{"text":"paid","bold":true},{"text":"; a shopper's glowing review shared widely is "},{"text":"earned","bold":true},{"text":". Billboards rented from an outdoor firm are bought space, but they are offline, so they never answer \"owned media\"."}]},{"text":[{"text":"Earned media links to PR and word of mouth: it is unpaid and the firm does not control it."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" a Lagos bakery's ad is shown 40,000 times, gets 800 clicks at ₦40 per click, and 24 people order."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CTR = 800 / 40,000 x 100 = "},{"text":"2%","bold":true}]},{"text":[{"text":"Spend = 800 x ₦40 = "},{"text":"₦32,000","bold":true}]},{"text":[{"text":"Conversion rate = 24 / 800 x 100 = "},{"text":"3%","bold":true}]},{"text":[{"text":"Cost per conversion = ₦32,000 / 24 = ₦1,333.33 (rounded to 2 decimal places)"}]}]}]},{"text":[{"text":"A visitor who leaves without doing anything is not a conversion; changing a logo is not a conversion."}]}]}]},{"number":"8.4","title":"Crafting digital marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Crafting digital marketing:","bold":true},{"text":" developing "},{"text":"strategic content suited to how audiences behave online","bold":true},{"text":". It requires "},{"text":"deep insight into online consumer behaviour and how each platform works","bold":true},{"text":"."}]},{"text":[{"text":"Steps in crafting a digital marketing strategy:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set clear objectives","bold":true},{"text":" (SMART: awareness, traffic, leads, sales)."}]},{"text":[{"text":"Define the target audience","bold":true},{"text":" and build "},{"text":"buyer personas","bold":true},{"text":"."}]},{"text":[{"text":"Choose the right digital channels and content","bold":true},{"text":" for that audience."}]},{"text":[{"text":"Create and publish","bold":true},{"text":" the content and campaigns (with a budget and schedule)."}]},{"text":[{"text":"Measure with analytics and improve","bold":true},{"text":" the campaign based on the results."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buyer persona:","bold":true},{"text":" a "},{"text":"detailed profile representing a typical member of the target audience","bold":true},{"text":" (age, location, job, interests, online habits, problems)."}]},{"text":[{"text":"Analytics after launch:","bold":true},{"text":" used to "},{"text":"measure performance and improve","bold":true},{"text":" the campaign."}]},{"text":[{"text":"Mobile-friendly (responsive) website:","bold":true},{"text":" essential because "},{"text":"many users access the internet mainly through their phones","bold":true},{"text":"."}]},{"text":[{"text":"Inbound vs outbound:","bold":true}]}]},{"type":"table","header":[[{"text":"Inbound marketing"}],[{"text":"Outbound marketing"}]],"rows":[[[{"text":"Attracts","bold":true},{"text":" customers to the firm through useful content, search and social media"}],[{"text":"Pushes","bold":true},{"text":" messages at people through cold calls and interruptive adverts"}]],[[{"text":"Customer finds the firm"}],[{"text":"Firm interrupts the customer"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT a step:","bold":true},{"text":" \"skipping measurement because digital results cannot be tracked\". Digital results can be tracked, so measurement is always a step."}]},{"text":[{"text":"Bad crafting: copying a print advert unchanged onto every website, using exactly the same message on every platform, ignoring which platforms the audience uses, focusing only on the cheapest channel, suppressing feedback, or avoiding measurement. Each platform has its own format: short videos on TikTok, professional posts on LinkedIn, pictures on Instagram."}]},{"text":[{"text":"Persona example:","bold":true},{"text":" \"Tola, 20, UNILAG student, lives in Akoka, spends most of her data on TikTok and Instagram, buys affordable skincare, pays by transfer.\" A brand plans content for Tola. A persona is not a product list, website owner or password."}]},{"text":[{"text":"In Nigeria, most people go online by phone, so a site that does not work well on a mobile phone loses customers."}]}]}]},{"number":"8.5","title":"Types of digital marketing","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Search engine optimisation (SEO):","bold":true},{"text":" improving a website so it "},{"text":"ranks higher in unpaid (organic) search results","bold":true},{"text":"."}]},{"text":[{"text":"Search engine marketing (SEM) / pay-per-click (PPC):","bold":true},{"text":" "},{"text":"paid search ads","bold":true},{"text":"; in PPC the advertiser "},{"text":"pays a fee each time someone clicks","bold":true},{"text":" its advert. Gives "},{"text":"immediate website traffic","bold":true},{"text":"."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing "},{"text":"free, useful content","bold":true},{"text":" (blogs, videos, guides) to attract an audience without pushing a direct sale each time."}]},{"text":[{"text":"Social media marketing:","bold":true},{"text":" using social platforms to "},{"text":"share content, engage users and build brand communities","bold":true},{"text":"."}]},{"text":[{"text":"Email marketing:","bold":true},{"text":" sending commercial messages such as "},{"text":"offers and newsletters","bold":true},{"text":" to people on an email list."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" paying partners "},{"text":"commission for each sale or lead","bold":true},{"text":" they bring through "},{"text":"referral links","bold":true},{"text":"."}]},{"text":[{"text":"Influencer marketing:","bold":true},{"text":" partnering with individuals who have a "},{"text":"large, engaged online following","bold":true},{"text":" to promote a brand."}]},{"text":[{"text":"Mobile marketing:","bold":true},{"text":" reaching consumers on their "},{"text":"phones","bold":true},{"text":" through "},{"text":"SMS, apps, mobile sites and location-based offers","bold":true},{"text":"."}]},{"text":[{"text":"Video marketing:","bold":true},{"text":" using online video (YouTube, TikTok, Reels) to promote and explain products."}]},{"text":[{"text":"Display advertising:","bold":true},{"text":" "},{"text":"visual adverts such as banners","bold":true},{"text":" shown on websites and apps; includes "},{"text":"retargeting (remarketing)","bold":true},{"text":", which shows ads to people who visited a site but did not buy."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" designing a message so that "},{"text":"people pass it on to others","bold":true},{"text":", spreading it rapidly like a virus."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Keywords:","bold":true},{"text":" the words and phrases people "},{"text":"type into a search engine","bold":true},{"text":" to find something."}]},{"text":[{"text":"Permission-based (opt-in) email:","bold":true},{"text":" send only to people who have "},{"text":"agreed (opted in)","bold":true},{"text":" to receive messages. "},{"text":"Spam:","bold":true},{"text":" unsolicited bulk commercial email sent to people who did not ask for it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SEO vs paid search:","bold":true},{"text":" SEO targets "},{"text":"unpaid organic listings","bold":true},{"text":"; paid search "},{"text":"buys advertising positions","bold":true},{"text":". A Port Harcourt hotel paying to appear at the top for \"hotels in Port Harcourt\" and charged only per click is "},{"text":"PPC search advertising","bold":true},{"text":", not SEO."}]},{"text":[{"text":"Affiliate vs influencer:","bold":true},{"text":" affiliate marketing pays partners "},{"text":"mainly according to sales or leads actually generated","bold":true},{"text":". A Nigerian e-commerce site giving bloggers a unique link and paying 5% commission only on purchases through that link is "},{"text":"affiliate","bold":true},{"text":". Influencer marketing often pays for exposure (a flat fee) whether or not sales follow: a drinks company paying a popular Nigerian comedy skit-maker with millions of Instagram followers to feature its drink is "},{"text":"influencer marketing","bold":true},{"text":"."}]},{"text":[{"text":"Content:","bold":true},{"text":" a Lagos skincare brand posting free weekly videos and blogs on caring for skin in hot, humid weather, without a hard sell, is "},{"text":"content marketing","bold":true},{"text":"."}]},{"text":[{"text":"Email:","bold":true},{"text":" an online bookshop's monthly email of new arrivals and discount codes to customers who signed up is "},{"text":"email marketing","bold":true},{"text":". Good practice: never hide the unsubscribe option, never buy lists of strangers' addresses, never flood inboxes."}]},{"text":[{"text":"Mobile:","bold":true},{"text":" an operator such as MTN or Airtel texting subscribers discounted data bundles bought by dialling a short code is "},{"text":"mobile (SMS) marketing","bold":true},{"text":"."}]},{"text":[{"text":"Retargeting:","bold":true},{"text":" a shopper views sneakers on a Nigerian online store, does not buy, and ads for the same sneakers follow her on other websites."}]},{"text":[{"text":"Viral:","bold":true},{"text":" the Hotmail signature line is the classic case. Text messages to phones are mobile, not display; supermarket shelf arrangement is merchandising, not display advertising."}]}]}]},{"number":"8.6","title":"Importance and challenges of digital marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Importance (advantages) of digital marketing:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reaches "},{"text":"large and even global audiences efficiently and at relatively low cost","bold":true},{"text":"."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" of specific audiences, so even "},{"text":"small businesses","bold":true},{"text":" can compete on a small budget."}]},{"text":[{"text":"Measurable in real time","bold":true},{"text":" (CTR, conversions, cost per sale)."}]},{"text":[{"text":"Instant customer engagement","bold":true},{"text":" and quick responses (two-way)."}]},{"text":[{"text":"Personalisation","bold":true},{"text":", which improves customer experiences and engagement."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" campaigns can be changed quickly while running."}]},{"text":[{"text":"Builds brand awareness and relationships 24 hours a day."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Challenges (limitations):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Data privacy and security","bold":true},{"text":" concerns."}]},{"text":[{"text":"Negative messages spread very quickly and widely","bold":true},{"text":" online."}]},{"text":[{"text":"Rapid change","bold":true},{"text":" in technology, platforms and search or social "},{"text":"algorithms","bold":true},{"text":", so marketers must keep learning."}]},{"text":[{"text":"Does "},{"text":"not reach people without internet or mobile access","bold":true},{"text":"."}]},{"text":[{"text":"Clutter","bold":true},{"text":", ad blocking and skipping."}]},{"text":[{"text":"Fraud, fake reviews and high competition for attention."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT an advantage:","bold":true},{"text":" \"messages reach people who have no internet or mobile access\". That is false; it is a limitation."}]},{"text":[{"text":"Digital marketing does not guarantee every customer will buy, does not remove competition, does not remove the need for a marketing plan or for understanding customers, and does not work only for big firms."}]},{"text":[{"text":"Negative spread:","bold":true},{"text":" an Abuja restaurant finds one angry customer's post about poor service shared thousands of times in a day. Firms must monitor and respond quickly and politely."}]},{"text":[{"text":"Data privacy matters in Nigeria too: firms holding customers' phone numbers and emails must protect them and use them only with consent."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Offline = TV, radio, newspapers, magazines, outdoor, cinema; online = search, display, social, email, mobile, websites."}]},{"text":[{"text":"TV: sight, sound, motion, mass. Radio: low cost, local, audio only. Newspapers: timely, local, short life. Magazines: long life, colour, selective. Outdoor: repeated exposure, brief message."}]},{"text":[{"text":"Online media: interactive, targeted, measurable; cannot reach people without internet."}]},{"text":[{"text":"Combine both (QR code on a billboard) in an integrated campaign."}]},{"text":[{"text":"Paid = bought; owned = firm controls; earned = reviews, shares, free press."}]},{"text":[{"text":"CTR = clicks / impressions x 100; conversion = desired action completed."}]},{"text":[{"text":"Crafting: objectives, audience and personas, channels and content, publish, measure with analytics."}]},{"text":[{"text":"SEO is organic; PPC pays per click; affiliate pays per sale; influencer uses followers; opt-in email, not spam."}]},{"text":[{"text":"Importance: low-cost global reach, targeting, real-time measurement, engagement, personalisation. Challenges: privacy, fast negative spread, changing algorithms."}]}]}],"theory":{"itemId":"5480d808-f6e5-5e9c-84d9-5734705f269c","question":[{"type":"paragraph","text":[{"text":"A Yaba phone-accessories shop runs a pay-per-click campaign. Its ad gets 60,000 impressions and 900 clicks at ₦60 per click, and 27 shoppers buy, each spending ₦6,000. Find the CTR, total spend, conversion rate, cost per sale, CPM and the revenue earned."}]}]},"practice":[{"topic":"Online and Offline Media and Digital Marketing","named":false}]}}]$expected_content$::jsonb,
  'marketing-communication: note published payload and identity match source');
select is((select count(*)::int from public.read_published_managed_content('ced55987-74eb-5998-929a-c1d5275c5a3b')
  where kind = 'cbt_question'), 0,
  'marketing-communication: CBT questions are withheld from the student content read');
reset role;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from (select i.id item_id, i.course_id, i.kind, i.question_id, i.source_key, i.parent_item_id,
    i.published_revision revision, r.payload from public.managed_content_items i
    join public.managed_content_revisions r on r.item_id = i.id and r.revision = i.published_revision
    where i.course_id = 'ced55987-74eb-5998-929a-c1d5275c5a3b' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"0ffc59fa-1c46-58f1-896b-5aa3451c8133","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2b9d228b-5755-5895-8268-2132dc10b8db","sourceKey":"bank:LAG-BUA123:COM-001","parentItemId":null,"revision":1,"payload":{"prompt":"The process of transmitting information and shared meaning from one person or group to another person or group is called:","options":["Perception","Negotiation","Communication","Motivation"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Communication is the transfer of information and shared meaning between a sender and a receiver. Option A is how a person interprets what they sense, and option B is bargaining to reach an agreement; both may involve communication but neither is the general process of passing meaning."}},{"itemId":"ab10e25f-f410-5d2c-8456-83f4e6fdf534","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3e418132-2ef4-5053-8c17-9e8adf486147","sourceKey":"bank:LAG-BUA123:COM-002","parentItemId":null,"revision":1,"payload":{"prompt":"The word 'communication' comes from the Latin word 'communis'. What does 'communis' mean?","options":["Common","Message","Speech","Exchange of goods"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"'Communis' means common, which reflects the idea that communication aims to create a common or shared understanding between sender and receiver. Option B and option C are things used in communicating, not the meaning of the Latin root."}},{"itemId":"d77a55d1-0985-5d0a-a7f2-fac214fc7786","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8eca12d3-b67b-5fd9-a3ec-165fc5eb4cd8","sourceKey":"bank:LAG-BUA123:COM-003","parentItemId":null,"revision":1,"payload":{"prompt":"Business communication is best described as:","options":["The use of paid mass media by a firm to promote its products to the general public","The exchange of information between people within and outside an organisation in order to achieve the organisation's goals","The face-to-face presentation of a product by a salesperson to a prospective buyer","The private conversations of employees about matters unrelated to their work"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Business communication covers all the information sharing that takes place inside a firm and between the firm and outsiders such as customers, suppliers and regulators, for the purpose of running the business. Option A is advertising and option C is personal selling, which are only specific promotional uses of communication."}},{"itemId":"2fc306cb-aac4-569a-a3d8-14c374e8e769","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8412ef1b-6acc-597e-82e3-a8ec50c39d76","sourceKey":"bank:LAG-BUA123:COM-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a purpose of business communication?","options":["To remove the need for planning and organising in the firm","To persuade customers and other stakeholders to take action","To coordinate the work of different departments","To inform employees and customers about decisions and offers"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Communication supports planning and organising; it cannot replace them, so option A is not a purpose. Informing (option D), persuading (option B) and coordinating (option C) are all standard purposes of business communication."}},{"itemId":"cffab9bc-1bad-5fd1-8beb-ceda40bc6493","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"058f8bfd-3ed8-5405-888f-cb2d01fe3a4c","sourceKey":"bank:LAG-BUA123:COM-005","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, the act of putting thoughts or ideas into symbolic form, such as words, pictures or sounds, is known as:","options":["Feedback","Decoding","Noise","Encoding"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Encoding is done by the sender, who converts an idea into symbols the receiver can understand. Option B is the reverse step, where the receiver interprets those symbols, and option A is the receiver's response sent back to the sender."}},{"itemId":"5d472ea0-a0a1-5120-a657-6faea507e1aa","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4ea0ced2-8616-521f-8e8d-892536f4e3fb","sourceKey":"bank:LAG-BUA123:COM-006","parentItemId":null,"revision":1,"payload":{"prompt":"The process by which the receiver assigns meaning to the symbols sent by the sender is called:","options":["Transmission","Encoding","Decoding","Feedback"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Decoding happens at the receiver's end, when the words, pictures or sounds received are interpreted and given meaning. Option B is done by the sender before the message is sent, and option A is simply the movement of the message through a channel."}},{"itemId":"36015c75-28c3-556c-b0e3-b4bf81d8bcfd","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0b6fbfc7-c64e-5665-a53c-87443067b673","sourceKey":"bank:LAG-BUA123:COM-007","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication model, 'noise' refers to:","options":["Any unplanned interference or distortion that prevents the message from being received as intended","The loud music used in radio and television advertisements","The medium through which the message travels from sender to receiver","The receiver's reply to the sender after receiving the message"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Noise is anything that disrupts or distorts communication, whether physical (such as a loud generator) or psychological (such as distraction). Option B takes the word too literally, option D describes feedback, and option C describes the channel."}},{"itemId":"31953f4d-11cb-5893-819d-1fce01cad95c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"00fde22d-ec7d-56f1-b07f-7763feb514b2","sourceKey":"bank:LAG-BUA123:COM-008","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback in the communication process is best defined as:","options":["The first message the sender transmits to the receiver","The distortion that occurs while the message is in the channel","The symbols the sender chooses to express an idea","The part of the receiver's response that is communicated back to the sender"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Feedback is the receiver's reaction returned to the sender, which tells the sender whether the message was understood. It turns communication into a two-way process. Option C is encoding and option B is noise."}},{"itemId":"9bba07cf-a0fa-56a2-95c0-93c61a5afe03","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a58d481f-5dfd-5175-bd34-eac52c9d5897","sourceKey":"bank:LAG-BUA123:COM-009","parentItemId":null,"revision":1,"payload":{"prompt":"The means or path through which a message travels from the sender to the receiver, such as radio, email or a face-to-face meeting, is called the:","options":["Encoder","Field of experience","Decoder","Channel"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"The channel (or medium) is the vehicle that carries the message, for example a phone call, a newspaper or social media. Option A and option C are the people who create and interpret the message, while option B is the background knowledge each party brings."}},{"itemId":"8a797cad-5875-5d89-ae61-b7179c0e1ea2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4a703c90-4008-59b2-878d-8f4cc949af3c","sourceKey":"bank:LAG-BUA123:COM-010","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, the sender (source) is:","options":["The reaction of the audience after seeing the message","The medium used to carry the message","The person or organisation that has an idea to share and starts the communication","The person or group for whom the message is intended"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The sender is where communication begins: the party with information to share who then encodes it into a message. Option D describes the receiver, option B the channel and option A the response."}},{"itemId":"45e3c0b1-eb61-5920-b8b9-706453752a75","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"87a22bca-762e-5d06-816a-956ed117464e","sourceKey":"bank:LAG-BUA123:COM-012","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing manager of a Lagos cement company wants customers to see the brand as strong and durable. She works with an agency to turn this idea into a TV script showing a building standing firm in heavy rain. In the communication process, this activity is:","options":["Noise","Encoding","Decoding","Feedback"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Converting the idea 'strong and durable' into pictures, words and sound is encoding, done on the sender's side. Option C would be the viewers interpreting the advert, and option D would be their response coming back to the company."}},{"itemId":"a74dd8d4-ba49-553f-ae0a-4dd98e3ef136","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"10b1a13e-e668-53ed-b563-f4643935d1a8","sourceKey":"bank:LAG-BUA123:COM-013","parentItemId":null,"revision":1,"payload":{"prompt":"A viewer in Ibadan watches a soft drink advert showing friends laughing at a party and concludes that the drink is for happy social occasions. Which stage of the communication process does this illustrate?","options":["Channel selection","Encoding","Decoding","Feedback"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The viewer is interpreting the symbols in the advert and giving them meaning, which is decoding. Option B is what the advertiser did when creating the advert, and option D would only occur if the viewer sent a response back, for example by commenting or buying."}},{"itemId":"876d0dce-71dd-5c12-990d-6af600d0225a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5d95a5bf-c13a-5a93-915f-4e05bceb4879","sourceKey":"bank:LAG-BUA123:COM-014","parentItemId":null,"revision":1,"payload":{"prompt":"A trader at Balogun Market cannot hear the details of a bank's radio jingle because of a loud generator nearby. In the communication model, the generator sound is an example of:","options":["Feedback","Encoding","Decoding","Noise"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Noise is any interference that stops a message from being received as intended, and a loud generator is a classic physical noise. Option A would be the trader's response to the bank, while options B and C are the sending and interpreting stages, not interference."}},{"itemId":"3b9fd273-c438-5ddb-a99d-87112e392584","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b4a9c505-a38f-5143-8795-83bf0dc6230f","sourceKey":"bank:LAG-BUA123:COM-015","parentItemId":null,"revision":1,"payload":{"prompt":"A telecoms company sends an SMS offering a N1,000 data bundle. Many customers reply 'YES' to subscribe, and others call the helpline to ask questions. These replies and calls represent:","options":["Feedback","The channel","Noise","Encoding"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Feedback is the receiver's response sent back to the sender; the replies and calls tell the company how the message was received. Option B would be the SMS itself as the medium, and option C would be something that disrupted the message."}},{"itemId":"ed8675a9-8281-5d69-bc2e-d8b17bf1ea9c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"07d116e1-5dd0-5bf0-bc68-6f7d0b41e202","sourceKey":"bank:LAG-BUA123:COM-016","parentItemId":null,"revision":1,"payload":{"prompt":"An insurance agent explains a policy to market women in Aba using terms like 'indemnity', 'actuarial loading' and 'subrogation'. The women leave confused. This is mainly an example of which barrier to communication?","options":["Information overload","Semantic (language) barrier","Organisational barrier","Physical barrier"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"A semantic barrier arises when words, technical terms or jargon are not understood in the same way by sender and receiver. Nothing physical blocked the message (option D), and the problem is not too many messages (option A) but unfamiliar language."}},{"itemId":"fd03e494-0704-5841-a23b-afce4b5a2966","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bf9e4339-00b9-5540-bc70-4a56e222fe0d","sourceKey":"bank:LAG-BUA123:COM-017","parentItemId":null,"revision":1,"payload":{"prompt":"A customer whose account was wrongly debited is so angry that he does not listen to the bank officer's explanation. Which barrier to communication is mainly at work?","options":["Physical barrier","Psychological (emotional) barrier","Semantic barrier","Cultural barrier"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Strong emotions such as anger, fear or distrust stop people from receiving messages properly, which is a psychological barrier. The officer's language is not the problem (option C), and there is no distance or physical interference (option A)."}},{"itemId":"69e080c1-66a3-52a2-835e-c0192610c5da","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6784e616-7453-5036-827d-4737714155fc","sourceKey":"bank:LAG-BUA123:COM-018","parentItemId":null,"revision":1,"payload":{"prompt":"A foreign company runs an advert in Nigeria using a hand gesture that is friendly in its home country but considered rude by many Nigerians. This problem is best described as a:","options":["Physical barrier","Semantic barrier caused by jargon","Cultural barrier","Organisational barrier"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Cultural barriers arise when symbols, gestures or customs mean different things in different cultures, so the receiver decodes the message differently from what the sender intended. Option A involves distance or interference, and option D relates to structures inside an organisation."}},{"itemId":"4ea31b3a-e4cf-5bdb-8e98-b29399782da0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9df44c58-190d-516b-bb71-bc9117f17790","sourceKey":"bank:LAG-BUA123:COM-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an element of the basic communication process model?","options":["Noise","Budget","Feedback","Encoding"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"The basic model is made up of the sender, encoding, message, channel, decoding, receiver, response, feedback and noise. A budget matters when planning a campaign, but it is not part of the communication process itself, whereas options D, A and C are all elements of the model."}},{"itemId":"7f414e80-f5d2-530c-9ef7-d504e7ccee60","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b4a5c0a1-2666-552c-88b8-6b91f52875f9","sourceKey":"bank:LAG-BUA123:COM-020","parentItemId":null,"revision":1,"payload":{"prompt":"A bank officer receives over 200 emails a day, and important messages from her manager are often missed or read late. This barrier to communication is called:","options":["Information overload","Semantic barrier","Selective retention","Cultural barrier"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Information overload happens when a receiver gets more messages than he or she can process, so some are ignored or misunderstood. Option B is about words being misunderstood, and option C is about remembering only messages that agree with one's beliefs."}},{"itemId":"5a113635-1f28-5e63-a87a-445a5f615f1e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"73d2c90a-4e6f-58a2-a443-4e986b9757e2","sourceKey":"bank:LAG-BUA123:COM-021","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency of people to notice and interpret messages in a way that fits their existing beliefs and attitudes, while ignoring others, is called:","options":["Selective perception","Information overload","Encoding","Feedback"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Selective perception means receivers filter messages through their own beliefs, so the same message may be understood differently by different people. Option B is about having too many messages, not filtering them by belief, and option C is done by the sender."}},{"itemId":"962dc94d-e115-548d-84a2-1a7fa9914f2b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d0f66f93-28a3-5e28-abe1-c6f074e78753","sourceKey":"bank:LAG-BUA123:COM-022","parentItemId":null,"revision":1,"payload":{"prompt":"According to the field of experience idea in communication, communication is most effective when:","options":["The sender uses as many technical terms as possible","The sender's and receiver's backgrounds, knowledge and experiences overlap","The receiver has no previous knowledge of the subject","The message is sent without expecting any response"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"The more the sender's and receiver's fields of experience overlap, the more likely the receiver is to decode the message as the sender intended. Option A usually reduces understanding, and option D removes feedback, which weakens communication."}},{"itemId":"89d1a5cc-a727-50aa-ba1d-4954c81ae59d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2f582a8f-89ce-544f-b934-cc11696e9d5b","sourceKey":"bank:LAG-BUA123:COM-023","parentItemId":null,"revision":1,"payload":{"prompt":"The main weakness of the linear (one-way) model of communication is that it:","options":["Does not include a sender","Does not include feedback from the receiver","Does not include a channel","Does not include a message"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"The linear model shows communication flowing in one direction only, from sender to receiver, so it ignores the receiver's response. A sender, message and channel (options A, D and C) are all present in the linear model."}},{"itemId":"cd1ff5f2-c8d8-511c-a790-b2d479e3d56f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"daf21a18-66ad-5b2e-ad45-56f45a12bae3","sourceKey":"bank:LAG-BUA123:COM-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication model, developed in 1949 from work on telephone signals, is best known for introducing the idea of 'noise' into communication?","options":["AIDA model","Lasswell's model","Shannon and Weaver model","Schramm's model"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The Shannon and Weaver model, a linear model based on telephone transmission, introduced noise as anything that distorts the signal between sender and receiver. Option B is the 'who says what' verbal model, and option A describes the stages a buyer goes through (attention, interest, desire, action)."}},{"itemId":"8091c548-6e90-5ac9-a6d9-1fe5680a2090","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"20ad1296-323e-5609-8460-9ad96b9373f4","sourceKey":"bank:LAG-BUA123:COM-025","parentItemId":null,"revision":1,"payload":{"prompt":"'Who says what, in which channel, to whom, with what effect?' is a famous description of communication associated with:","options":["Philip Kotler","Wilbur Schramm","Shannon and Weaver","Harold Lasswell"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Lasswell summarised communication as who (sender) says what (message) in which channel to whom (receiver) with what effect. Option C is linked with the noise idea, option B with the field of experience idea, and option A is a marketing writer rather than the author of this formula."}},{"itemId":"27c1badd-c6a9-5646-9c98-7514ce83ed03","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"283a7a18-02d0-5ed5-9a15-0a7576afa588","sourceKey":"bank:LAG-BUA123:COM-026","parentItemId":null,"revision":1,"payload":{"prompt":"In the transactional model of communication, communication is seen as:","options":["A process in which noise never occurs","A continuous process in which both parties send and receive messages at the same time","A one-way flow from sender to a passive receiver","A process that has no channel"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"The transactional model treats both parties as communicators who send and receive messages at the same time, for example through words and facial reactions during a conversation. Option C describes the linear model, and noise can occur in any model (option A)."}},{"itemId":"c9c64314-fa48-5c21-8eb5-f79366f1339f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7b3052b9-8cd9-54ca-aeda-108b61daa671","sourceKey":"bank:LAG-BUA123:COM-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of non-verbal communication?","options":["A sales letter","A salesperson's smile and firm handshake","A product brochure text","A telephone conversation"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Non-verbal communication sends messages without words, through facial expressions, gestures, posture, touch and appearance. Options A, D and C all rely on words, whether written or spoken."}},{"itemId":"37c88420-6846-5a01-b325-941ddc3fba12","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2ee19496-76fa-5ed8-ad90-47a9f895dcee","sourceKey":"bank:LAG-BUA123:COM-028","parentItemId":null,"revision":1,"payload":{"prompt":"The aspects of the voice, such as tone, pitch, speed and volume, that add meaning to spoken words are known as:","options":["Proxemics","Kinesics","Haptics","Paralanguage"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Paralanguage is how something is said rather than the words themselves; a shouted 'thank you' means something different from a warm one. Option A is the use of space, option B is body movement and option C is touch."}},{"itemId":"e38356f5-bd24-5336-ad4c-e879db3718ea","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"55f609b9-9b35-525a-9b96-a74c153958e4","sourceKey":"bank:LAG-BUA123:COM-029","parentItemId":null,"revision":1,"payload":{"prompt":"The study of how people use personal space and distance when communicating is called:","options":["Proxemics","Kinesics","Chronemics","Paralanguage"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Proxemics deals with space, for example how close a salesperson stands to a customer. Option B is body movement, option D is voice qualities and option C is the use of time."}},{"itemId":"554c6993-a6be-52d8-926e-5f30cd17478b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"abc0914e-09c6-5c2b-93d9-e8084b253cc9","sourceKey":"bank:LAG-BUA123:COM-030","parentItemId":null,"revision":1,"payload":{"prompt":"Communication through body movements such as gestures, posture, facial expressions and eye contact is known as:","options":["Paralanguage","Proxemics","Chronemics","Kinesics"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Kinesics, often called body language, covers gestures, posture, facial expression and eye contact. Option B is about space and option C is about time, such as punctuality."}},{"itemId":"bb6131e6-2b32-5484-86e3-69f5d7bfc226","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a80fbf3c-298d-5eda-a214-bf724d533ae9","sourceKey":"bank:LAG-BUA123:COM-031","parentItemId":null,"revision":1,"payload":{"prompt":"A supplier keeps a client waiting for two hours past their scheduled meeting in Abuja. The client concludes the supplier does not value the business. This message was sent through:","options":["Chronemics (the use of time)","Haptics (touch)","Paralanguage","Written communication"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Chronemics is non-verbal communication through time, such as punctuality and waiting, and lateness often signals disrespect. No voice tone (option C), touch (option B) or written words (option D) carried this message."}},{"itemId":"21cc1af9-0129-53d4-9754-c46c64ec2824","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e1a3d92c-9a1a-5f50-9b7a-2b81cf3cee9c","sourceKey":"bank:LAG-BUA123:COM-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a form of non-verbal communication?","options":["A memo sent to all staff","Eye contact","Tone of voice","Dress and appearance"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"A memo uses written words, so it is verbal (written) communication. Eye contact (option B), tone of voice (option C) and dress (option D) all communicate without the actual words being the message."}},{"itemId":"c8a77c90-66f1-53f6-af55-aab18cb4aaa7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"298745ce-8c29-5d4f-af12-717a4d0e4fd4","sourceKey":"bank:LAG-BUA123:COM-033","parentItemId":null,"revision":1,"payload":{"prompt":"The main advantage of oral communication over written communication is that it:","options":["Is always more suitable for legal agreements","Provides a permanent record for future reference","Can be checked and edited carefully before it is received","Allows immediate feedback and clarification"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"In oral communication, such as a meeting or phone call, the receiver can respond and ask questions at once, so misunderstandings are cleared quickly. Options B, A and C are advantages of written communication, not oral."}},{"itemId":"bb8b1f8a-daa8-57e4-852d-52881fa7586a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5dfb18fb-8632-58f7-9dea-a68b8bdabf24","sourceKey":"bank:LAG-BUA123:COM-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a major advantage of written communication?","options":["It provides a permanent record that can serve as evidence","It allows tone of voice to show the sender's feelings","It is always faster than speaking face to face","It gives instant feedback through facial expressions"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Written messages such as letters, contracts and emails can be stored and referred to later, which makes them useful as records and evidence. Options D and B are features of oral communication, and written communication is usually slower, not faster (option C)."}},{"itemId":"b482031d-1624-58e9-9b05-9e20d3bcba6a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fe5dd8ad-fc5a-560d-9e1e-7f2bfc625ef9","sourceKey":"bank:LAG-BUA123:COM-035","parentItemId":null,"revision":1,"payload":{"prompt":"A distributor in Kano agrees with a manufacturer on credit terms of N5 million payable in 60 days. Both want terms that can be relied on if there is a dispute later. The best form of communication for this is:","options":["Written communication, such as a signed agreement","Non-verbal communication","Oral communication in a phone call","Informal grapevine communication"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Written communication creates a permanent, signed record that can be used as evidence in a dispute. A phone call (option C) leaves no reliable record, and the grapevine (option D) is unofficial and unreliable."}},{"itemId":"ba44700f-cf2c-5cc0-901a-2d3af9c368fa","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c3bd9928-5588-518e-ab45-8a101dd429ed","sourceKey":"bank:LAG-BUA123:COM-036","parentItemId":null,"revision":1,"payload":{"prompt":"Formal communication in an organisation refers to communication that:","options":["Is always oral rather than written","Takes place only outside working hours","Spreads through friendships and casual conversations among staff","Follows official channels and lines of authority set by the organisation"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Formal communication flows through the official structure, such as reports, memos and meetings between managers and their staff. Option C describes informal communication (the grapevine), and formal messages can be written or oral, so option A is wrong."}},{"itemId":"a455cf4b-09df-50fa-9fd6-7988138de9ca","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e0dcf4fe-62a7-5bf6-80a3-3df2ddb9791b","sourceKey":"bank:LAG-BUA123:COM-037","parentItemId":null,"revision":1,"payload":{"prompt":"The informal network through which news and rumours spread among employees, outside official channels, is called the:","options":["Formal network","Downward channel","Grapevine","Chain of command"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The grapevine is the unofficial, informal communication network in an organisation. Option D is the official line of authority, and option B is formal communication from superiors to subordinates."}},{"itemId":"8d748f8e-0398-51f7-bed9-a2deedd5e849","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9bfc6948-5f23-5b65-b572-60fce621c348","sourceKey":"bank:LAG-BUA123:COM-038","parentItemId":null,"revision":1,"payload":{"prompt":"The Managing Director of a Lagos manufacturing firm sends a circular to all staff explaining a new resumption time. This is an example of:","options":["Downward communication","Upward communication","Grapevine communication","Horizontal communication"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Downward communication flows from higher levels of authority to lower levels, for example instructions, policies and circulars. Option B flows from subordinates to superiors, and option C flows between people at the same level."}},{"itemId":"523d988d-47d7-5cb2-b181-6fb80119d752","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2bfbda73-c344-5f49-9517-8979ec00aeac","sourceKey":"bank:LAG-BUA123:COM-039","parentItemId":null,"revision":1,"payload":{"prompt":"Sales representatives of a beverage company in Port Harcourt submit weekly sales reports to their regional manager. This is an example of:","options":["External communication","Horizontal communication","Upward communication","Downward communication"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Upward communication flows from subordinates to superiors, for example reports, suggestions and complaints. Option D would be the manager instructing the reps, and option A would involve people outside the company."}},{"itemId":"33bdff76-f216-52b1-b610-18b91f3b20a6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5478e7a7-0b87-59bc-8432-a6445702bc31","sourceKey":"bank:LAG-BUA123:COM-040","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing manager and the production manager of a company, who are at the same level, meet to agree on when a new product will be ready for launch. This is:","options":["Horizontal (lateral) communication","Downward communication","External communication","Upward communication"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Horizontal communication takes place between people or departments at the same level and is mainly used for coordination. Neither manager is above the other, so options B and D do not apply, and both are inside the firm (option C)."}},{"itemId":"483b37f7-2a14-5cd6-af93-6365de941d21","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"02e03918-87f9-51e5-9752-ad29b6a61da4","sourceKey":"bank:LAG-BUA123:COM-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of upward communication?","options":["A supervisor's instructions to the team","A job description given to a new employee","An employee suggestion box","A memo announcing a new company policy"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"A suggestion box carries ideas and complaints from employees up to management, so it is upward communication. Options B, D and A all move from management down to employees."}},{"itemId":"fb98630c-db82-5770-a2e4-ecaaa7d18137","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4b45ed9f-7526-5678-b127-34e65140369d","sourceKey":"bank:LAG-BUA123:COM-042","parentItemId":null,"revision":1,"payload":{"prompt":"A bank issues a press release to newspapers announcing that its mobile app has been upgraded. This is mainly an example of:","options":["Upward communication","Horizontal communication","External communication","Internal communication"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"External communication is between the organisation and outsiders such as customers, the media, suppliers and regulators. Option D would be messages among the bank's own staff, and options A and B describe directions of flow inside an organisation."}},{"itemId":"6487bf6f-6bfd-581f-a09b-61f078d6a27f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f0a975aa-3662-5862-9b83-d8ca4a76e0a9","sourceKey":"bank:LAG-BUA123:COM-043","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of internal communication?","options":["A letter of complaint to a supplier","A billboard advertisement","A product launch press conference","A staff newsletter"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Internal communication takes place among members of the organisation, and a staff newsletter is written for employees. Options B, A and C are all aimed at people outside the firm."}},{"itemId":"e05aac97-ef8d-5808-9484-308d96c8a372","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"908278c8-521a-56c7-87f0-1c70cfa1c22f","sourceKey":"bank:LAG-BUA123:COM-044","parentItemId":null,"revision":1,"payload":{"prompt":"The main disadvantage of the grapevine as a channel of communication is that:","options":["It cannot exist in large organisations","Messages are often distorted and can spread false rumours","It can only carry written messages","It is always slower than formal channels"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Because the grapevine is unofficial and passes from person to person, messages are often incomplete or distorted, and rumours can spread. In fact the grapevine is usually very fast (so option D is wrong), and it exists in organisations of every size (option A)."}},{"itemId":"195d6c28-62ef-5b6f-adbc-37fb270e21f8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"10dfb5c5-249e-5fbd-bb85-e20da9e075b4","sourceKey":"bank:LAG-BUA123:COM-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is generally considered an advantage of the grapevine?","options":["It is controlled by top management","Its messages are always accurate","It provides official records of decisions","It spreads information very quickly"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"The grapevine is known for its speed, since news passes quickly through informal networks of friends and colleagues. It is not always accurate (option B), management cannot control it (option A), and it does not create official records (option C)."}},{"itemId":"3e2e1dc9-0ef2-5cbc-b9d4-45596d753e90","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a9319e86-8bfe-5479-84b0-a0e614ba51c2","sourceKey":"bank:LAG-BUA123:COM-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a barrier to effective communication?","options":["Physical noise","Use of jargon","Active listening","Emotional stress"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Active listening means paying full attention, asking questions and confirming understanding, so it improves communication rather than blocking it. Jargon (option B), physical noise (option A) and emotional stress (option D) are all common barriers."}},{"itemId":"363d0906-a7b8-520b-be03-b53b0dccea6d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e28c3a57-40a0-57d5-9f5a-fcf2b6d32b40","sourceKey":"bank:LAG-BUA123:COM-047","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the best way to overcome barriers to communication?","options":["Using simple language and encouraging feedback to check understanding","Using more technical terms to sound professional","Sending the same message through as many channels as possible at once","Avoiding questions from the receiver to save time"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Simple language reduces semantic barriers, and feedback lets the sender confirm that the message was understood as intended. Option B creates jargon problems, option C can cause information overload, and option D removes feedback."}},{"itemId":"d384e187-bd1f-53e9-96d4-07cdcac5e5d8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1f8e0358-bab1-58ea-bc5c-d925f0866fbf","sourceKey":"bank:LAG-BUA123:COM-048","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, how does 'response' differ from 'feedback'?","options":["Response is created by the sender, while feedback is created by the channel","Response happens before encoding, while feedback happens before decoding","Response is the receiver's reaction to the message, while feedback is the part of that reaction communicated back to the sender","Response and feedback are two words for noise in the channel"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"After decoding, the receiver reacts in some way, which is the response, and the part of that reaction that reaches the sender is feedback. For example, a viewer may like an advert (response) and then post a comment to the brand (feedback). Options A, B and D misplace both terms in the process."}},{"itemId":"53b60076-5b3f-5f5a-b8e0-e91e89fdc1a9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4faa3058-43a1-5478-8ebb-2672432f96ce","sourceKey":"bank:LAG-BUA123:COM-049","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, the 'message' is:","options":["The reply the receiver sends back to the sender","The interference that distorts communication","The set of words, pictures, sounds or symbols that the sender transmits","The person who receives and interprets the communication"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The message is the actual content the sender transmits after encoding, such as the words and pictures in an advert. Option D is the receiver, option B is noise and option A is feedback."}},{"itemId":"95e82a52-7882-5d53-930b-3a9d7733ac5a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a1837d7c-415f-57f5-bafe-cff9e2d8d845","sourceKey":"bank:LAG-BUA123:COM-050","parentItemId":null,"revision":1,"payload":{"prompt":"The receiver in the communication process is:","options":["The person who creates and encodes the message","The person or group the message is intended for, who decodes it","The symbols used to express the message","The medium that carries the message"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"The receiver is the target of the message and is responsible for decoding it into meaning. Option A is the sender, option D is the channel and option C is the message."}},{"itemId":"d60c4d0c-19eb-5bb1-bb7a-34e492506dde","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4b3562a0-fcdb-58d4-954b-13cdd91d320d","sourceKey":"bank:LAG-BUA123:COM-051","parentItemId":null,"revision":1,"payload":{"prompt":"Communication is said to be effective when:","options":["The receiver receives the message without any opportunity to respond","The message has been sent through the most expensive channel","The meaning understood by the receiver matches the meaning intended by the sender","The sender has transmitted the message, whether or not it is understood"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Effective communication is about shared meaning: the receiver understands what the sender meant. Merely sending a message (option D) does not guarantee understanding, and the cost of the channel (option B) is not the test."}},{"itemId":"ac44a6fc-8ea2-5b13-955f-0f845da5285f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"90ba7361-f877-5fd4-be1e-29eea4eea4a5","sourceKey":"bank:LAG-BUA123:COM-052","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is the best example of one-way communication?","options":["A telephone call with a customer","A roadside billboard advert","A face-to-face sales negotiation","A question-and-answer session at a meeting"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"In one-way communication the message flows from sender to receiver with no direct chance for the receiver to respond, as with a billboard. Options C, A and D all allow immediate replies, so they are two-way."}},{"itemId":"6e3065e3-19aa-549c-8a7d-3a0790be8c29","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a87cfeca-8740-5a29-85ed-ce12b33a2002","sourceKey":"bank:LAG-BUA123:COM-053","parentItemId":null,"revision":1,"payload":{"prompt":"A channel's 'richness' is its ability to carry several cues and give immediate feedback. Which of the following is the richest communication channel?","options":["An email","A face-to-face meeting","A printed notice","A formal report"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Face-to-face communication carries words, tone of voice, facial expressions and gestures, and allows instant feedback, so it is the richest channel. Printed notices, emails and reports (options C, A and D) carry mainly words and give slow or no feedback."}},{"itemId":"253e4d37-12da-5b17-9bc7-dbff04249294","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"87c2ab1e-a02d-5e1a-b3f4-2e4d9f65e343","sourceKey":"bank:LAG-BUA123:COM-054","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency of people to remember mainly the information that supports their existing beliefs and to forget information that does not is called:","options":["Selective exposure","Selective retention","Encoding","Information overload"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Selective retention is about memory: people keep messages that agree with their beliefs and forget the rest. Option A is about which messages people choose to be exposed to in the first place, and option D is having too many messages to process."}},{"itemId":"3eb74036-daf4-5a84-9aeb-a17fe8ca6101","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"966d31ac-0ad9-5be9-a7d9-ef2bac937162","sourceKey":"bank:LAG-BUA123:COM-055","parentItemId":null,"revision":1,"payload":{"prompt":"Junior staff of a large Lagos firm are afraid to report problems directly to the Managing Director because of the many levels of authority and the MD's high status. This is mainly a:","options":["Cultural barrier between countries","Physical noise","Semantic barrier","Organisational (status) barrier"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Organisational barriers come from the structure of the firm, such as too many levels in the hierarchy and status differences that discourage upward communication. The problem is not words (option C), national culture (option A) or physical interference (option B)."}},{"itemId":"27e0dda0-4dfa-5935-97cd-b7975268011e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6b7551f4-f54b-5444-9bb4-2bb737ec893c","sourceKey":"bank:LAG-BUA123:DEF-001","parentItemId":null,"revision":1,"payload":{"prompt":"The channels and tools that companies use to communicate the necessary message to a target group are collectively called:","options":["Market segmentation","Distribution management","Product development","Marketing communications (MarCom)"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communications, shortened to MarCom, are the channels and tools a company uses to get its message to its target group. Option A is about grouping similar consumers, option B is about moving goods to buyers and option C is about creating the offering itself, so none of them is the communicating activity."}},{"itemId":"e15bb3e5-84ce-5121-a18a-a1d9af2e7b20","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ec9d3a59-926d-5490-a89e-80019ce4021a","sourceKey":"bank:LAG-BUA123:DEF-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the common definitions of marketing communication?","options":["The internal record-keeping of a firm's sales transactions","The setting of prices for goods based on production cost","A continuous interaction between the buyers and sellers in a marketplace","A one-time announcement made only when a new product is launched"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"One common definition sees marketing communication as a continuous interaction between buyers and sellers in a marketplace. Option D is wrong because MarCom is ongoing, not a one-off launch event, while options A and B describe accounting and pricing tasks."}},{"itemId":"d5eaf12d-6966-52c7-a84b-6fa6a1bce43e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"18c675c9-2127-5130-995a-ed2bd90aa616","sourceKey":"bank:LAG-BUA123:DEF-003","parentItemId":null,"revision":1,"payload":{"prompt":"One definition describes marketing communication as the means companies adopt to convey messages about their products and brands, directly or indirectly, to customers with the intention to:","options":["Reduce the number of products on offer","Discourage them from comparing brands","Persuade them to purchase","Collect taxes on behalf of government"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"This definition stresses persuasion: messages about products and brands are sent, directly or indirectly, so that customers will buy. Option B is not the stated intention, and options A and D have nothing to do with conveying brand messages."}},{"itemId":"b68ae213-e30a-5fdf-a707-034cc9e1ef97","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0955ec0d-d8ea-5b20-8052-56a74f10ed22","sourceKey":"bank:LAG-BUA123:DEF-004","parentItemId":null,"revision":1,"payload":{"prompt":"\"The process of creating and delivering messages that promote the interests of an organisation\" is a definition of:","options":["Marketing communications","Production planning","Market research","Financial reporting"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Creating and delivering messages that promote an organisation's interests is one of the common definitions of marketing communications. Option C gathers information from the market rather than sending messages to it, while options B and D are operations and accounting activities."}},{"itemId":"75d46b70-99c0-51f3-aae1-f1476a78e807","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a4bb7ba8-4f5e-57f4-b4c3-b925215ffba4","sourceKey":"bank:LAG-BUA123:DEF-005","parentItemId":null,"revision":1,"payload":{"prompt":"At its core, marketing communications encompasses the integration of all promotional tools and sources within a company in order to:","options":["Maximise the impact on consumers and other end-users at minimal cost","Maximise the number of advertisements regardless of cost","Limit the firm's messages to only one medium","Replace the need for a product with persuasive messages"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"This view of MarCom is about integration: combining all promotional tools so they have maximum impact on consumers and end-users at minimal cost. Option B ignores the cost side, option D wrongly suggests messages can replace the product, and option C contradicts the idea of integrating many tools."}},{"itemId":"6b1a1ca7-2b7e-5ce7-becc-d0be53ccb00e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2de8c5e6-9fc5-5d19-84b4-10cac267d8c9","sourceKey":"bank:LAG-BUA123:DEF-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about the definition of marketing communications is correct?","options":["It is defined only as face-to-face selling","It is defined only as television advertising","There is a single legally fixed definition used by all firms","There is no universal definition, so the subject has many interpretations"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"To date there is no universal definition of marketing communications, which is why several interpretations exist. Option C is therefore false, and options B and A reduce MarCom to just one tool when it covers many."}},{"itemId":"7ee32762-4d50-5f08-b962-bbc3b67c81fe","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8eea63de-735b-5cd3-9b4f-b6786877d546","sourceKey":"bank:LAG-BUA123:DEF-007","parentItemId":null,"revision":1,"payload":{"prompt":"By conveying messages and information of significant value, MarCom aims to encourage audiences to offer:","options":["Negative reviews of competitors","Neutral responses that change nothing","Positive attitudinal and behavioural responses","Lower prices for the firm's products"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"MarCom delivers valuable messages so that audiences respond positively in both attitude (how they feel about the brand) and behaviour (what they do, such as buying). Option A is not the goal, option D confuses audience response with pricing, and option B would mean the communication failed."}},{"itemId":"326b999d-456d-57f4-93fb-484f9fb59606","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"936cce9b-4675-5eee-9ef1-1e4ceb6caa1e","sourceKey":"bank:LAG-BUA123:DEF-008","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication offers answers to several questions. Which of the following is NOT one of them?","options":["What internal and external influences affect the exchange?","How much tax should the firm pay this year?","What is being exchanged?","Who is the customer?"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"MarCom helps answer who the customer is, what is being exchanged, and what internal and external influences affect that exchange. A firm's tax liability, option B, is a finance and accounting question, not a communication one."}},{"itemId":"8a9e28f0-bb9d-5279-9380-a7ef5d1f4dab","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b43529bc-5e2d-5a6d-b762-933b5f08a494","sourceKey":"bank:LAG-BUA123:DEF-009","parentItemId":null,"revision":1,"payload":{"prompt":"The process of using words, sounds or visual cues to supply information to one or more people is a definition of:","options":["Distribution","Pricing","Segmentation","Communication"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Communication is the process of using words, sound or visual cues to supply information to one or more people. Options A, C and B are other marketing activities that do not, by themselves, mean supplying information through cues."}},{"itemId":"7a99c03d-47dd-5c18-afda-2112d892211c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4281de66-66ba-583d-bd27-7f231ba68af2","sourceKey":"bank:LAG-BUA123:DEF-010","parentItemId":null,"revision":1,"payload":{"prompt":"In simple words, the establishment of mutually satisfying exchange relationships through the buying and selling of goods, services or ideas is called:","options":["Marketing","Auditing","Manufacturing","Accounting"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing, in simple terms, is establishing mutually satisfying exchange relationships through buying and selling goods, services or ideas. Option C is making the goods, while options D and B record and check financial information."}},{"itemId":"d77f07ff-2e5e-59d6-943f-632e6729e78c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"450e6c54-c7b8-5007-8443-e28ff7f628f0","sourceKey":"bank:LAG-BUA123:DEF-011","parentItemId":null,"revision":1,"payload":{"prompt":"Baker (2000) defines marketing as:","options":["The act of producing goods at the lowest possible cost","The process of planning the conception, pricing, communication and distribution of ideas","A way of managing profitable customer relationships","The process of grouping homogenous consumers"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Baker's short definition is that marketing is a way of managing profitable customer relationships. Option B is the longer planning-and-executing definition given by Strydom, Jooste and Cant, option A is about production efficiency, and option D describes segmentation."}},{"itemId":"ac86fa05-6462-5c88-8b11-2f25c1d877ba","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ffd7994e-2299-5be4-8b90-63fb4cafce91","sourceKey":"bank:LAG-BUA123:DEF-012","parentItemId":null,"revision":1,"payload":{"prompt":"Kotler and Armstrong (2006) view marketing as the process through which companies create value for customers and build strong customer relationships in order to:","options":["Capture value from customers in return","Avoid any contact with competitors","Eliminate the need for promotion","Reduce the range of customer choices"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"This definition sees marketing as a two-way value process: firms create value for customers and build strong relationships so that they get value back in return. Options B, C and D are not part of this definition and would not explain why firms build relationships."}},{"itemId":"ac117ad6-3d48-515b-8968-98b009ac085b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f7dc4b2f-c78c-5ad3-9b67-f2a761efb9fb","sourceKey":"bank:LAG-BUA123:DEF-013","parentItemId":null,"revision":1,"payload":{"prompt":"Stapleton and Ali note that the common definitions of marketing share some commonalities. Which of the following is NOT one of these commonalities?","options":["A focus on reducing the number of employees","The relationship between the customer and the organisation","The provision of suitable offerings to meet customers' needs","A focus on customers"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The shared features are a focus on customers, suitable offerings that meet customer needs, suitable benefits to the organisation, and the customer-organisation relationship through which value is created. Cutting staff numbers, option A, is not one of them."}},{"itemId":"e7f156a7-ef00-59b0-97af-7ed453322477","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5afa3500-a9c9-52b1-a4b4-99cef6152577","sourceKey":"bank:LAG-BUA123:DEF-014","parentItemId":null,"revision":1,"payload":{"prompt":"A customer's perception of a company or its brand is best described as:","options":["Formed only by the price of the product","Fixed at birth and unaffected by communication","Determined only by the company's television adverts","A synthesis of bundles of messages received through many forms of communication"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Perception of a brand is built up from many messages together, such as advertising, price, packaging design, direct marketing, publicity, sales promotion and websites. Options C and A each pick out only one of these messages, and option B wrongly says communication has no effect."}},{"itemId":"badc1d4e-c83d-5740-a9eb-cf40f85678e7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1c273aa8-5d6d-5b4d-af5d-fb6eb8594250","sourceKey":"bank:LAG-BUA123:DEF-015","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following organisations needs to communicate with a range of stakeholders?","options":["Only manufacturing firms","Only large multinational companies","All organisations, whether commercial, government, charity or not-for-profit","Only firms that sell online"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Every type of organisation, large or small, commercial or government, charity, school, manufacturer or service provider, needs to communicate with stakeholders. Options B, A and D wrongly limit this need to one kind of firm."}},{"itemId":"c41d50b5-3b84-5fa8-8489-4d5d59754beb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3a81d6cf-f40a-5de5-b770-b81272d30cb9","sourceKey":"bank:LAG-BUA123:DEF-016","parentItemId":null,"revision":1,"payload":{"prompt":"News distributed from a single broadcast point and made available over the airwaves or in mass print runs is an example of which type of communication?","options":["Many-to-one","One-to-one","Many-to-many","One-to-many"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"One-to-many communication starts from a single broadcast point and reaches a wide audience through airwaves or mass print, as in a general news announcement. Option A is the reverse flow (many replying to one), option B is a personal exchange like a sales talk, and option C is the internet pattern of everyone talking to everyone."}},{"itemId":"19a21aac-afa8-5660-b9bf-1cef5ee25d6f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"82798802-d1fe-5b2b-ae65-a11039bcd040","sourceKey":"bank:LAG-BUA123:DEF-017","parentItemId":null,"revision":1,"payload":{"prompt":"A bank in Lagos sends a newsletter by email, and hundreds of customers click the reply button to send their questions back to the bank. The replies illustrate which type of communication?","options":["One-to-one","Many-to-many","Many-to-one","One-to-many"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Many customers sending replies to one organisation is many-to-one communication, and the email reply button is the classic example. The newsletter itself is one-to-many, option D, while options A and B describe a single personal exchange and online group conversation."}},{"itemId":"6421c5a4-fd39-53bc-a377-21cb78f1af89","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1a364a50-5f70-50db-87e4-7567805196db","sourceKey":"bank:LAG-BUA123:DEF-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which type of communication is described as the most intensive and interactive, as in a sales presentation or a negotiation?","options":["One-to-many","One-to-one","Many-to-one","Many-to-many"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"One-to-one communication is the most intensive and interactive form because two parties deal directly with each other, as in a sales presentation or negotiation. Option A is a broadcast to a mass audience, option C is many replies going to one point, and option D is group interaction online."}},{"itemId":"9cc20a63-57f9-5c03-a6f8-5d0be1e605b7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b886685b-ce4c-5404-acfb-62de7ceddc7f","sourceKey":"bank:LAG-BUA123:DEF-019","parentItemId":null,"revision":1,"payload":{"prompt":"Students of a Nigerian university swap opinions about phone brands in an online chat room and on blogs, all talking to one another at once. This illustrates:","options":["Many-to-one communication","Many-to-many communication","One-to-one communication","One-to-many communication"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Many-to-many communication has grown with the highly developed internet, as in chat rooms and blogging websites where many people talk to many others. Option C involves only two parties, option D is a broadcast, and option A is many people replying to a single point."}},{"itemId":"b53af8b2-80ae-5549-8b65-ef88a75836a2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c93200ee-01e1-5953-b46c-a1f1e751918d","sourceKey":"bank:LAG-BUA123:DEF-021","parentItemId":null,"revision":1,"payload":{"prompt":"How many different types of communication are identified by the direction of flow between senders and receivers (one-to-many, many-to-one and so on)?","options":["Two","Seven","Three","Four"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"There are four types: one-to-many, many-to-one, one-to-one and many-to-many. Option B confuses this with the seven Ps of the marketing mix, and options A and C leave some of the types out."}},{"itemId":"13709c16-3cd7-5724-89f8-299b6b089862","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5b1e1234-bacb-5c2b-8410-afd95e44f5d0","sourceKey":"bank:LAG-BUA123:DEF-022","parentItemId":null,"revision":1,"payload":{"prompt":"When a brand develops its marketing communications strategy around the marketing mix, the 'Promotion' element considers:","options":["The people who interact with the brand's customers","Where the product is bought and sold","The pricing model used for the product","All of the ways in which the brand, product or service is communicated to the public"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Promotion covers every way the brand, product or service is communicated to the public, and it also involves Positioning. Option B is Place, option C is Price, and option A is People."}},{"itemId":"7b008687-b44c-5d9a-926b-77970ba8e2d3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f2504b6c-3858-5ef0-8eff-bd9ccfb3b1d2","sourceKey":"bank:LAG-BUA123:DEF-023","parentItemId":null,"revision":1,"payload":{"prompt":"Within the Promotion element of the marketing mix, which additional P is used to evaluate how people view and respond to the brand?","options":["Place","Process","Positioning","Packaging"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Positioning is the extra P inside Promotion that looks at how people view and respond to the brand. Option D deals with attracting customers in the physical and online marketplace, option B deals with the customer experience and communication process, and option A is where the product is sold."}},{"itemId":"6b51f5bd-4e74-5329-8761-fbf119eb0c67","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cc1bb4e2-322c-57fc-aaed-563e344b49da","sourceKey":"bank:LAG-BUA123:DEF-024","parentItemId":null,"revision":1,"payload":{"prompt":"In the seven Ps marketing mix around which a brand builds its MarCom strategy, 'Process' considers:","options":["How to attract customers in the physical and online marketplace","The customer experience and communication process","The features of the good or service","Where the good or service is bought and sold"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Process considers the customer experience and the communication process. Option C is Product, option D is Place, and option A is Packaging."}},{"itemId":"101d2473-3362-566f-85d7-43a5db3187e8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3fea9a60-4755-50a8-8972-adcfa7edafd0","sourceKey":"bank:LAG-BUA123:DEF-025","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing mix that a brand typically uses to develop its marketing communications strategy is now known as the Seven Ps. It was formerly called the:","options":["Five forces","Four Ps","Six stages","Three Cs"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The Seven Ps grew out of the older Four Ps of product, price, promotion and place, which were later extended. Option A is a competition model, option D is a different framework, and option C is not a name for the marketing mix."}},{"itemId":"cfea7cf4-4b46-55bb-8d39-30986542d26b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"21057a2f-528a-5da0-a049-a4bcecf390c5","sourceKey":"bank:LAG-BUA123:DEF-026","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos fashion brand trains its shop attendants and delivery riders on how to treat customers, because they all interact with buyers. Which P of the marketing mix is this?","options":["Product","People","Price","Place"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"People considers everyone who interacts with a brand's customers or clients, so training attendants and riders is about People. Option A is the features of the offering, option C is the pricing model, and option D is where the goods are bought and sold."}},{"itemId":"ef33baf0-c4f3-517b-a8ab-7b8383ff762a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9c1f6d27-2b7a-5ce4-b6d9-c2e0364a5b78","sourceKey":"bank:LAG-BUA123:DEF-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement about the emergence of marketing communication is correct?","options":["Marketing communication began only with the internet","Communication has been part of marketing for as long as people have exchanged goods","Marketing communication first appeared with social media in the 2000s","Marketing communication was invented in the 1950s with television"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication is not new; communication has been part of the marketing process for as long as people have exchanged goods. Options A, D and C each confuse a later medium that made MarCom more sophisticated with the start of MarCom itself."}},{"itemId":"c0e223d7-a512-594d-8ac4-e19f4d7cc47b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e390f94a-cc82-53f7-b6cf-260646550db5","sourceKey":"bank:LAG-BUA123:DEF-028","parentItemId":null,"revision":1,"payload":{"prompt":"The advent of technology and research made marketing communication increasingly sophisticated and gave rise to:","options":["The end of advertising","Integrated marketing communication (IMC)","The barter system","Handwritten manuscripts"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Technology, research and changing consumers made MarCom more sophisticated and gave rise to integrated marketing communication, where many channels deliver one unified message. Options C and D existed long before, and option A is the opposite of what happened."}},{"itemId":"357771f1-ec8c-53cb-8a4a-b028646f207e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"30f68506-9989-5fac-ac52-4a96f28f7f2b","sourceKey":"bank:LAG-BUA123:DEF-029","parentItemId":null,"revision":1,"payload":{"prompt":"The use of multiple channels to create a unified message describes:","options":["Integrated marketing communication","Market segmentation","One-to-one communication","Personal selling"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Integrated marketing communication means using multiple channels together so that they deliver one unified message. Option C is a single personal exchange, option B is grouping consumers, and option D is just one tool of the mix rather than the coordination of many."}},{"itemId":"daed1411-7eaf-5889-83aa-6d7ecd822854","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ccda4a16-bb06-557b-b037-c65f787b828a","sourceKey":"bank:LAG-BUA123:DEF-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT given as a way in which consumers have changed, driving more sophisticated marketing communication?","options":["They now have fewer choices than ever before","Their behaviour is more complex","Their media habits are different","They are more confident and outspoken"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Consumers have changed beyond recognition: their behaviour is more complex, their media habits differ and they are more confident and outspoken. Audiences actually have more choices than ever before, so option A states the opposite of the truth."}},{"itemId":"636f2378-6c61-581b-833f-91b568370893","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ea1ba56a-3bd3-5b84-91fd-884805b742b0","sourceKey":"bank:LAG-BUA123:DEF-031","parentItemId":null,"revision":1,"payload":{"prompt":"The invention of the printing press by Johannes Gutenberg in the 15th century marked, for businesses, the birth of:","options":["Email marketing","Television advertising","Radio commercials","Print advertising"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Before the printing press, information lived in handwritten manuscripts for the elite; printing made mass-produced messages possible and so gave birth to print advertising. Options B, A and C came centuries later with broadcasting and the internet."}},{"itemId":"f70b09bc-bf3c-5e2a-a476-c9e5826d4340","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"59ab7ed5-0391-5017-8451-e54059fda9ea","sourceKey":"bank:LAG-BUA123:DEF-032","parentItemId":null,"revision":1,"payload":{"prompt":"The first printed advertisements appeared in newspapers in the:","options":["17th century","20th century","19th century","15th century"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The first printed adverts appeared in 17th-century newspapers, promoting things from medicines to real estate. Option D is when Gutenberg invented the printing press, not when newspaper adverts appeared, and options C and B are too late."}},{"itemId":"823d6115-8a1a-5dcc-ac19-4b34d9d0ace9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"57f04f66-c0a7-5f46-a100-e11af3d663c6","sourceKey":"bank:LAG-BUA123:DEF-033","parentItemId":null,"revision":1,"payload":{"prompt":"Radio commercials, which gave brands a way to reach households with audio messages, began in the:","options":["1990s","1950s","1890s","1920s"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Radio commercials began in the 1920s. Option B, the 1950s, is when television became the dominant platform, and option A belongs to the internet age."}},{"itemId":"31d5c1fe-e00d-5451-ae10-b64e25e02978","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b59ca89c-5385-5e09-99ef-a6f3f3883731","sourceKey":"bank:LAG-BUA123:DEF-034","parentItemId":null,"revision":1,"payload":{"prompt":"By the 1950s, which medium had emerged as the dominant platform by combining visuals and sound to create compelling advertisements?","options":["Television","Email","Newspapers","Radio"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Television dominated by the 1950s because it combined pictures and sound. Option D offered sound only and started in the 1920s, option C is print, and option B came with the internet in the late 20th century."}},{"itemId":"bc797f33-1e8f-566b-adb6-2aafec3ddc82","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"224255bd-26e9-58b5-92ff-9886f42bf047","sourceKey":"bank:LAG-BUA123:DEF-035","parentItemId":null,"revision":1,"payload":{"prompt":"Volkswagen's \"Think Small\" campaign of the 1960s is cited as showing how television could be used for:","options":["Storytelling that fosters emotional connections with audiences","Sending replies through an email reply button","Running two-way conversations on social media","Collecting customers' email addresses"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"\"Think Small\" showed that television could tell stories that build emotional connections with audiences. Options D, C and B are digital-era practices that did not exist in the 1960s."}},{"itemId":"a5c76226-1955-5fe5-addc-4ac9016efeb6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"48896ff1-6ac5-583d-8673-5de1b55dc3e8","sourceKey":"bank:LAG-BUA123:DEF-038","parentItemId":null,"revision":1,"payload":{"prompt":"The journey from the printing press to social media illustrates which enduring truth about marketing communication?","options":["It has stayed the same since the 15th century","It no longer affects consumer behaviour","It is ever-evolving, so understanding its history helps firms anticipate future trends","It matters only to large firms"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The history shows that marketing communication is ever-evolving, and knowing that history helps businesses anticipate trends and craft strategies that resonate. Option A contradicts the evolution described, and options D and B are not supported."}},{"itemId":"2baf45ce-452c-539e-9140-d6b0cf3f148e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"080a6c7e-202b-5bb2-8aef-21141467b11d","sourceKey":"bank:LAG-BUA123:DEF-040","parentItemId":null,"revision":1,"payload":{"prompt":"Among the conditions for exchange, which one shows most directly why marketing communication is necessary?","options":["Each must have something of value to the other","Each party can communicate and deliver what it is offering","Each party is free to accept or reject the offer","There must be at least two parties"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"An exchange cannot happen unless each party can communicate and deliver what it offers, and this is exactly the job of marketing communication. Options D, A and C are also conditions, but they concern how many parties there are, what each one has, and freedom of choice, not communication."}},{"itemId":"211acfe1-e615-580f-ab1b-6237f9766fa0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6787a27b-1b75-5c24-98aa-7cacef1b4d66","sourceKey":"bank:LAG-BUA123:DEF-041","parentItemId":null,"revision":1,"payload":{"prompt":"The act of obtaining a desired object from someone by offering something of value in return is called:","options":["Publicity","Market segmentation","Brand switching","The exchange process"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The exchange process means getting a desired object from someone by offering something of value in return. Option B groups consumers, option A is free news coverage, and option C is customers moving from one brand to another."}},{"itemId":"1a4071a0-1bcb-5e6b-88ac-43e1bbe608ef","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a0b01b2b-4a2e-5a62-a818-1bce1c4a6610","sourceKey":"bank:LAG-BUA123:DEF-042","parentItemId":null,"revision":1,"payload":{"prompt":"Ada pays N4,500 to a Yaba bookshop and receives a textbook in return. The completed exchange between Ada and the bookshop is known as a:","options":["Transaction","Positioning statement","Press release","Segment"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"When an exchange between someone offering money or other resources and a company selling a good, service or idea is completed, the result is a transaction. Option D is a group of consumers, option B is about brand image, and option C is a publicity tool."}},{"itemId":"27879c6b-dde4-5760-90de-079d81f57e0c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1e231178-4e58-5ec5-bc4f-4466f1f13ac8","sourceKey":"bank:LAG-BUA123:DEF-046","parentItemId":null,"revision":1,"payload":{"prompt":"A pizza chain tells customers it delivers the newest and hottest pizza faster than rivals, in only 30 minutes. In the MarCom process, this is an example of:","options":["Determining the unique value (selling) proposition","Allocating the budget","Developing control measures","Identifying the target audience"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"A unique value or selling proposition (UVP or USP) is what makes a business stand out from rivals, and the 30-minute promise is the standard example. Options B and C concern money and monitoring, and option D is about choosing who to talk to, not what makes the offer special."}},{"itemId":"c0ebdb50-c38b-5c44-8ea7-befed5aac308","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fb64eba9-42ec-5084-a80a-9b80b2b46e42","sourceKey":"bank:LAG-BUA123:DEF-047","parentItemId":null,"revision":1,"payload":{"prompt":"In the process of marketing communications, deciding how much to spend on each channel is the stage called:","options":["Selecting channels","Execution","Budget allocation","Message development"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Budget allocation answers the question of how much to spend on each channel. Option D is crafting the key messages, option B is implementing the plan, and option A picks which channels to use but not how much each gets."}},{"itemId":"17ea5ee2-a8be-5709-aa34-9c7e8f472bda","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c7eb63a2-370c-532f-b36b-c5d23c2aa4c7","sourceKey":"bank:LAG-BUA123:DEF-048","parentItemId":null,"revision":1,"payload":{"prompt":"In the MarCom process, measuring a campaign's effectiveness against objectives and making the necessary adjustments is called:","options":["Developing control measures","Message development","Bringing the solution to customers' queries","Identifying the target audience"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Developing control measures means checking the campaign's effectiveness against its objectives and adjusting where needed. Option B is writing the messages, option D is the very first stage, and option C is about addressing customers' pain points."}},{"itemId":"a68f34d6-012d-5e24-8f30-638d2abc388c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7e6f08d7-1bfe-5bea-9e0e-10f2e5ff2402","sourceKey":"bank:LAG-BUA123:DEF-049","parentItemId":null,"revision":1,"payload":{"prompt":"In the process of marketing communications, the channels a firm uses to deliver its brand message should depend on:","options":["The personal hobbies of the marketing manager","Only the cheapest channel available","The objectives it wants to accomplish and its customers' preferences","Whatever channel its competitors used last year"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Channel choice depends on the objectives the firm wants to accomplish and on its customers' preferences. Options D, B and A ignore both of these and would waste the message on the wrong medium."}},{"itemId":"e46a2179-6be9-5997-83b3-f9412636b352","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ff7e725c-cb0d-5882-9ef3-aec5d46258b7","sourceKey":"bank:LAG-BUA123:DEF-050","parentItemId":null,"revision":1,"payload":{"prompt":"What is the primary objective of marketing communications?","options":["To cut production costs","To reduce the number of competitors by law","To avoid customer feedback","To increase sales volume through persuasive, informative and positive messages"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The primary objective of marketing communications is to increase sales volume through persuasive, informative and positive messages; the other objectives support this. Options B and A are not communication goals, and option C goes against the interactive nature of MarCom."}},{"itemId":"7f2c2492-40fd-58c9-8ff4-5ab2ab92273a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d42ef0d4-e7cc-5202-9ec5-3f810774a622","sourceKey":"bank:LAG-BUA123:DEF-051","parentItemId":null,"revision":1,"payload":{"prompt":"How are marketing communication objectives described in terms of time frame?","options":["As goals that apply only on a product's launch day","As daily targets that are dropped after one week","As objectives with no link to brand value","As long-term goals that aim to boost the brand's value over time"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication objectives are long-term goals through which marketing strategies aim to boost the brand's value over time. Options B and A make them short-lived, and option C removes the link to brand value."}},{"itemId":"c8fe391a-f66d-5567-a36e-c3b75cd9e017","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c9ca4b2a-c735-5128-8c7b-0d016761ccd4","sourceKey":"bank:LAG-BUA123:DEF-052","parentItemId":null,"revision":1,"payload":{"prompt":"A new fintech company has just entered the Nigerian market and runs radio commercials and print ads so that people know the business and its app exist. Which MarCom objective is it pursuing?","options":["Drive brand switching","Increase brand awareness","Stimulate repeat patronage","Change attitudes"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"When a firm first enters a market, people need to know that it and its offerings exist, so it broadcasts commercials or print ads to increase brand awareness. Option A targets rivals' customers, option C targets people who have already bought, and option D corrects mistaken beliefs."}},{"itemId":"b658641f-7d1d-538f-a501-60178000aab4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"14fe92f9-e308-5b32-b8f4-e6e1499583e4","sourceKey":"bank:LAG-BUA123:DEF-053","parentItemId":null,"revision":1,"payload":{"prompt":"False rumours spread that a Nigerian bottled-water brand is unsafe, so the firm runs a campaign showing its NAFDAC approval and factory tests. Which MarCom objective does this campaign serve?","options":["Stimulate trial purchase","Conduct research for the company","Increase brand awareness","Change attitudes"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Changing attitudes means altering views of a product or brand, especially when mistaken beliefs have spread in the market. Option C is about letting people know a brand exists, which they already do here, option A is getting first-time use, and option B is reading market trends."}},{"itemId":"dbf4754b-4a8e-5a9e-b973-ec510bff02ee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"14e9cfda-00e1-5870-be21-53888691759c","sourceKey":"bank:LAG-BUA123:DEF-054","parentItemId":null,"revision":1,"payload":{"prompt":"A cosmetics firm in Lagos hands out free sample sachets of a new cream at a mall so that shoppers can try it without risk. Which objective is it mainly pursuing?","options":["Stimulate trial purchase","Conduct research for the company","Change attitudes","Build a brand image over a long period"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Free trials or samples are popular ways to get consumers to try a product first, taking the risk off and letting them experience the brand. Option C corrects false beliefs, option B reads market trends, and option D is a long-term goal not specific to sampling."}},{"itemId":"f0c01536-9873-5127-ac59-18cdb53a10fe","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d08fa738-04e1-5c66-b3e3-08b123204f6c","sourceKey":"bank:LAG-BUA123:DEF-055","parentItemId":null,"revision":1,"payload":{"prompt":"A telecom company offers bonus data to customers of rival networks who port their lines to it. Which MarCom objective does this target?","options":["Drive brand switching","Conduct research for the company","Change attitudes","Increase brand awareness"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Driving brand switching aims to get customers who buy competing products to move to your brand. Option D only makes people aware a brand exists, option B studies the market, and option C corrects mistaken beliefs, none of which directly pulls rivals' customers across."}},{"itemId":"69337468-690a-5149-91d5-1e95023e2e84","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d04fd637-da88-5f7b-8dcb-1be73eeeeb55","sourceKey":"bank:LAG-BUA123:DEF-056","parentItemId":null,"revision":1,"payload":{"prompt":"Influencing purchase intent is typically achieved by compelling adverts that generally focus on:","options":["The company's internal staff structure","The firm's tax payments","The superior benefits to users compared to competitors","The history of the printing press"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Ads that influence purchase intent usually stress the superior benefits users get compared with competitors' products. Options A, D and B would not motivate a customer to buy."}},{"itemId":"ee03861c-8844-5ce6-a955-5c88a225667e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1087a147-720b-589a-8208-7f3435c09a3c","sourceKey":"bank:LAG-BUA123:DEF-057","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT listed as a specific objective of marketing communications?","options":["Building a brand image","Conducting research for the company","Doing direct selling","Fixing the company's production machinery"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The specific objectives include awareness, changing attitudes, purchase intent, trial and repeat purchase, brand switching, connecting companies with consumers, building brand image, conducting research and direct selling. Maintaining machinery, option D, is a production task."}},{"itemId":"391d60f3-7179-511d-9c19-6981124b8024","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1610e2e3-0457-5fdd-b169-56346ff06b0d","sourceKey":"bank:LAG-BUA123:DEF-058","parentItemId":null,"revision":1,"payload":{"prompt":"When marketing communications 'conducts research for the company', it is expected to:","options":["Write the company's annual financial statements","Connect company stakeholders with the market by reading trend movements in the sector","Recruit new staff for the company","Design the factory layout"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Some MarCom work links company stakeholders with the market, so marketers must read trend movements in the firm's sector. Options A, D and C belong to finance, operations and human resources."}},{"itemId":"efeccdab-9a19-5deb-8e88-8cc19fda3ce3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e1b65221-19cc-508d-962f-199a3045588b","sourceKey":"bank:LAG-BUA123:DEF-059","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the important roles of marketing communications?","options":["Shortening the sales cycle","Setting the legal minimum wage","Building brand awareness","Maintaining customer loyalty"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The key roles are building brand awareness, maintaining customer loyalty, creating demand, shortening the sales cycle and highlighting a competitive edge. Setting a minimum wage, option B, is a government function."}},{"itemId":"5ca64aca-7f86-523d-b3fb-f29b915c7936","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d5710bfe-4bf4-5b93-a656-c2236006603d","sourceKey":"bank:LAG-BUA123:DEF-060","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communications can shorten the sales cycle by:","options":["Removing all information about the product","Better understanding customer needs, motivations, influences and buying processes and using this insight when engaging consumers","Raising prices so that fewer people buy","Delaying responses to customer enquiries"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The sales cycle gets shorter when the firm understands customer needs, buying motivations, influences and processes and uses that insight when engaging consumers. Options A, C and D would slow down or block buying decisions."}},{"itemId":"d4fadc2c-e750-55b5-a06c-9b413c281486","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c828ae28-859a-5ced-b7f1-2211d39eecf5","sourceKey":"bank:LAG-BUA123:DEF-061","parentItemId":null,"revision":1,"payload":{"prompt":"Why is highlighting a competitive edge an important role of marketing communications?","options":["Because competitors are not allowed to advertise","In a crowded marketplace, the points that make a product unique must be shared with the public","Because products no longer differ from one another","Because customers dislike learning about product features"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The 21st-century marketplace is crowded, so MarCom must share the points of differentiation that make products unique and so strengthen competitive advantage. Option C contradicts the idea of differentiation, and options A and D are untrue."}},{"itemId":"2eb7b22c-dea4-580f-aea1-a9563b9b80df","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8e1b17b7-51bf-58ed-a838-68d4766e5090","sourceKey":"bank:LAG-BUA123:DEF-062","parentItemId":null,"revision":1,"payload":{"prompt":"\"It is not enough to have improved or innovative goods or services; people need to know they exist in order to buy them.\" This statement explains which role of marketing communications?","options":["Shortening the sales cycle","Conducting research for the company","Creating demand for products and services","Maintaining customer loyalty"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Creating demand depends on people knowing that a product exists, however good or innovative it is. Option D is about keeping an existing positive bond, option A is about speeding up buying, and option B is reading market trends."}},{"itemId":"d0f0aa20-16f8-5574-8c1b-edcb361811d7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cd128075-bbc4-5f47-8a86-4629c11151b0","sourceKey":"bank:LAG-BUA123:DEF-063","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket chain in Abuja sends birthday messages and loyalty-point updates to regular shoppers to keep a positive bond with them. Which role of MarCom is this?","options":["Building brand awareness","Maintaining customer loyalty","Highlighting a competitive edge","Creating demand for new products"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Maintaining customer loyalty is about making sure existing customers keep a positive bond with the company and its brands. Option A targets people who do not yet know the firm, option C stresses what makes it different from rivals, and option D is about getting people to want a new offering."}},{"itemId":"af4ad147-fbe6-506f-904b-397b78f4d86d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"556f065a-4d94-5602-8775-2d0aa9ce1424","sourceKey":"bank:LAG-BUA123:DEF-064","parentItemId":null,"revision":1,"payload":{"prompt":"Besides the main roles, marketing communications has other specific roles. Which of the following is NOT one of them?","options":["Integrating all marketing tools to achieve seamless communication","Engaging customers at various points along the buying journey","Influencing consumer behaviour to drive sales","Replacing the need for a quality product"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"The other specific roles are influencing consumer behaviour to drive sales, engaging customers along the buying journey and integrating all marketing tools for seamless communication. Communication supports a good product but cannot replace it, so option D is not a role."}},{"itemId":"62743cbd-24d8-5a58-b636-ee5622c55ad1","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4703293f-7acc-5b90-a816-94a0556aee2b","sourceKey":"bank:LAG-BUA123:DEF-065","parentItemId":null,"revision":1,"payload":{"prompt":"In the DRIP framework for the roles of marketing communications, the letters D, R, I and P stand for:","options":["Demand, Reach, Image, Profit","Design, Research, Implement, Plan","Differentiate, Reinforce, Inform, Persuade","Distribute, Retail, Invest, Price"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"DRIP sums up the four roles of MarCom: to Differentiate an offering from rivals, Reinforce earlier messages and experiences, Inform audiences, and Persuade them to act. Options D, B and A are made-up expansions mixing other business terms."}},{"itemId":"f30b9833-b34a-55fd-bb21-493b8442f648","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"06047712-92bf-5560-a3a9-03aceaaf7270","sourceKey":"bank:LAG-BUA123:DEF-066","parentItemId":null,"revision":1,"payload":{"prompt":"A popular Nigerian beverage brand that everyone already knows keeps running adverts reminding loyal buyers of the good experiences they have had with it. Under the DRIP roles, this mainly serves to:","options":["Differentiate","Inform","Reinforce","Persuade"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Reinforcing means reminding customers and confirming the benefits and positive experiences they have already had, which keeps existing buyers loyal. Option B gives new information to people who lack it, option A sets the brand apart from rivals, and option D pushes people towards a new action or attitude."}},{"itemId":"cf114d7f-7db7-5d40-9398-4e1d72ba334d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e0fc8bb5-58a1-59fe-90dc-6be93ba9298a","sourceKey":"bank:LAG-BUA123:DMK-001","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a group made up entirely of offline (traditional) media?","options":["Television, radio, newspapers and billboards","Radio, social media, magazines and websites","Television, email, billboards and search engines","Websites, search engines, email and mobile apps"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Offline or traditional media are channels that do not need the internet, such as TV, radio, print and outdoor. Option D lists only online media, and options B and C mix offline channels with online ones such as email, search, social media and websites."}},{"itemId":"d0d9548e-77e7-58f9-856b-80a55815a3b7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f2a1521a-7786-55dd-98fe-cd0059ef22f4","sourceKey":"bank:LAG-BUA123:DMK-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a group made up entirely of online media?","options":["Billboards, websites, radio and email","Newspapers, magazines, radio and television","Websites, search engines, social media and email","Television, social media, flyers and search engines"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Online media are internet-based channels such as websites, search engines, social media and email. Option B lists traditional offline media, while options A and D mix in billboards, radio, TV and flyers, which are offline."}},{"itemId":"68d5df24-3c65-55da-9b8f-c5ebb5b0e714","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0a7c2eba-f7e7-5497-8b27-cc244ea7a70c","sourceKey":"bank:LAG-BUA123:DMK-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an offline communication medium?","options":["A sponsored search engine advertisement","A full-page newspaper advertisement","A radio jingle on a local station","A roadside billboard on a highway"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"A sponsored search ad appears on a search engine results page, so it is an online medium. Options B, C and D are outdoor, broadcast and print media, all of which are traditional offline channels."}},{"itemId":"977dc4cc-710c-5f20-89c0-9bdfe6914383","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2508d6b1-f0d7-5bfa-bf75-9770d7254814","sourceKey":"bank:LAG-BUA123:DMK-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an online communication medium?","options":["A company's Instagram page","A painted advertisement on the side of a danfo bus","A banner advertisement on a news website","An email newsletter"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"An advert painted on a bus is transit (outdoor) advertising, which is offline. Options A, C and D are social media, email and website display advertising, all delivered over the internet."}},{"itemId":"a1c7d486-0316-5a45-ac18-bc5f8ffb3787","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4555412e-9047-5d50-a429-da2b7d18105a","sourceKey":"bank:LAG-BUA123:DMK-005","parentItemId":null,"revision":1,"payload":{"prompt":"A major advantage of online media over most offline media is that online media:","options":["Cannot be ignored, blocked or skipped by the audience","Always cost more than a national television campaign","Allow results such as clicks and views to be measured quickly","Reach people who have no internet access at all"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Online media make it easy to track how many people saw, clicked or bought, often in real time. Option D is actually a strength of offline media, option A is untrue because online ads are easily skipped, and option B is false since digital campaigns are often cheaper."}},{"itemId":"f43f3663-9a18-573b-bbd5-65a9aecb0ddc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b98f7642-f8db-5ce1-9d7c-03633fcbc9b1","sourceKey":"bank:LAG-BUA123:DMK-006","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with traditional offline media, online media are generally more:","options":["Limited to local audiences only","Difficult to target at specific groups","One-way, giving the audience no chance to respond","Interactive, allowing two-way communication with the audience"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Online media let audiences reply, comment, share and click, so communication can flow both ways. Option C describes traditional broadcast media, and options A and B are the reverse of the truth, because online media can reach global audiences and target specific groups precisely."}},{"itemId":"698216aa-68ec-5dae-90c2-c3a528003c24","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dbe6863a-5a15-5f40-9b97-cde55c45379b","sourceKey":"bank:LAG-BUA123:DMK-007","parentItemId":null,"revision":1,"payload":{"prompt":"An agro-chemical firm wants to reach farmers in remote villages in Benue State where internet access is poor but most households listen to local-language programmes. The most suitable medium is:","options":["Email marketing","Local radio","Instagram influencer posts","Search engine advertising"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Radio reaches people without internet, is cheap, can be in local languages and is widely listened to in rural areas. Options A, C and D all depend on internet access, which these farmers largely lack."}},{"itemId":"89cc454f-0c73-5f32-887e-28e5cc668632","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6e7d4818-033f-5a21-a288-b369b55cb51f","sourceKey":"bank:LAG-BUA123:DMK-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes the main strength of television as an advertising medium?","options":["It combines sight, sound and motion to reach a large mass audience","It reaches only a small, highly selective audience","It is the cheapest medium for very small local businesses","It allows readers to keep and re-read detailed information"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Television's power comes from combining pictures, sound and movement and from reaching very large audiences at once, although it is expensive. Option C is wrong because TV is costly, option D describes print, and option B is the opposite of TV's mass reach."}},{"itemId":"11e32add-d5f9-5f4b-9ef3-ae1159f61455","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d10c83ec-3b23-54cb-a530-e201846e24dd","sourceKey":"bank:LAG-BUA123:DMK-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which offline medium is best known for being low cost, locally targeted and audio only?","options":["Billboards","Radio","Magazines","Television"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Radio is relatively cheap, can be aimed at local listeners, and works through sound alone. Option D adds pictures and costs more, option C is a visual print medium, and option A is outdoor and visual."}},{"itemId":"e63fc4eb-9bb9-56d4-a975-8eb2494d1259","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4d2001be-f4bd-5da2-bdaf-769e388fcc75","sourceKey":"bank:LAG-BUA123:DMK-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which offline medium usually offers a long life, high-quality colour reproduction and a selective readership with specific interests?","options":["Billboards","Radio","Newspapers","Magazines"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Magazines are kept and passed around for weeks, print in good colour and target readers with particular interests. Option C has a short life and lower print quality, option B has no visuals, and option A carries only brief messages to passers-by."}},{"itemId":"fe806e71-6696-5f0f-9d6a-f5fb02203a82","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"05c48974-66ac-5b5e-831a-181cb3892253","sourceKey":"bank:LAG-BUA123:DMK-011","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with magazines, newspapers as an advertising medium are best known for:","options":["Timeliness and local coverage, but a short life","Sound and motion to grab attention","A long life and highly selective readership","Personal two-way interaction with each reader"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Newspapers come out daily, so ads can be placed quickly and aimed at a city or region, but each edition is soon thrown away. Option C describes magazines, option B describes TV, and option D describes personal or interactive media."}},{"itemId":"67422034-9885-5ad6-bbac-a7f3b80cb6f0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ab2114c5-549e-5f10-b2f4-412e5d697373","sourceKey":"bank:LAG-BUA123:DMK-012","parentItemId":null,"revision":1,"payload":{"prompt":"Outdoor advertising such as billboards is best described as a medium that:","options":["Gives repeated exposure to passers-by but carries only brief messages","Lets each viewer reply to the advertiser instantly","Allows long, detailed explanations of complex products","Reaches only people who subscribe to it"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Billboards are seen again and again by people passing the same spot, but they can only show a short message because people see them for a few seconds. Option C describes print, option B describes interactive online media, and option D describes email lists or magazine subscriptions."}},{"itemId":"04b59877-cd50-568a-a735-9feac9589fab","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a39f6750-a9e8-5398-92c9-f1c1d459c5d5","sourceKey":"bank:LAG-BUA123:DMK-013","parentItemId":null,"revision":1,"payload":{"prompt":"A fashion brand in Lagos puts a QR code on its billboards on Third Mainland Bridge which takes viewers straight to its online store. This is an example of:","options":["Using only offline media","Abandoning traditional advertising","Integrating offline and online media","Using only online media"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"The billboard is offline and the online store is digital; linking them with a QR code integrates the two so they support each other. Options A and D each ignore one side of the campaign, and option B is wrong because the billboard is still being used."}},{"itemId":"8e93bf6d-4b46-5b6a-a90f-ab29e33af3b3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c493b5eb-591a-5379-92fc-3365df7002d9","sourceKey":"bank:LAG-BUA123:DMK-014","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a limitation of online media?","options":["Messages may not reach people without internet access","Audiences can block or skip adverts","Heavy clutter from many competing messages","Results of campaigns can be tracked in detail"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Detailed tracking of results is one of the main advantages of online media, not a limitation. Options A, B and C are real drawbacks: limited internet access, ad blocking and skipping, and clutter."}},{"itemId":"ad3382f8-d183-5361-a289-341eb2243c2d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"946ee886-2b6d-5917-8df4-d2ef66ce17c2","sourceKey":"bank:LAG-BUA123:DMK-015","parentItemId":null,"revision":1,"payload":{"prompt":"Digital marketing is best defined as:","options":["Printing brochures and handing them out to people on the street","Selling goods face to face to customers in physical markets and shops","The use of the internet and digital channels to promote products and engage customers","The use of only television and radio to advertise products to the public"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital marketing uses digital channels such as websites, search engines, social media, email and mobile to promote products and connect with customers. Option D is broadcast advertising, option B is personal selling, and option A is offline print promotion."}},{"itemId":"0294199e-a8d8-5078-aaf9-97f3a894a895","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fc8192c2-3b3a-5448-8d04-9a58626a11f7","sourceKey":"bank:LAG-BUA123:DMK-016","parentItemId":null,"revision":1,"payload":{"prompt":"Promoting products and building customer relationships through websites, search engines, social media, email and mobile devices is called:","options":["Outdoor advertising","Personal selling","Digital marketing","Trade promotion"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Using internet-based and mobile channels to promote and engage is digital marketing. Option A uses billboards and transit, option B is face-to-face selling, and option D targets intermediaries such as wholesalers and retailers."}},{"itemId":"cabe6e0f-bd8d-52c2-b5eb-eb53358b189f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5021f1c4-b751-5d38-aa16-c8b106404ca1","sourceKey":"bank:LAG-BUA123:DMK-017","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a typical step in crafting a digital marketing strategy?","options":["Setting clear objectives for the campaign","Choosing the right digital channels and content","Defining the target audience","Skipping measurement because digital results cannot be tracked"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Measuring results is a key step in digital marketing, and digital results can in fact be tracked closely, so skipping measurement is not part of a sound strategy. Options A, B and C are standard steps: set objectives, know the audience, and pick channels and content."}},{"itemId":"69a9b9c7-5e3a-5aa7-9cd8-e1f10add9fa2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"64590f89-8f0c-55d4-9681-3957f60eaf7f","sourceKey":"bank:LAG-BUA123:DMK-018","parentItemId":null,"revision":1,"payload":{"prompt":"When crafting digital marketing, using analytics after a campaign is launched mainly helps a firm to:","options":["Stop customers from seeing competitors' ads","Remove the need to understand the target audience","Avoid setting any objectives for the campaign","Measure performance and improve the campaign based on the results"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Analytics show what is working, such as visits, clicks and sales, so the firm can adjust and optimise its campaign. Options B and C remove essential planning steps, and option A is not something analytics can do."}},{"itemId":"9aec51ae-330e-5ec4-8316-a456fbd9aa69","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e6b26705-dfa1-5281-97e7-9f15aee41606","sourceKey":"bank:LAG-BUA123:DMK-019","parentItemId":null,"revision":1,"payload":{"prompt":"In crafting digital marketing, a 'buyer persona' is:","options":["A detailed profile representing a typical member of the target audience","A list of all the products a firm currently sells","The legal owner who registered the company's website","The password used to access the firm's social media page"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"A buyer persona is a semi-fictional picture of a typical target customer, describing their needs, habits and online behaviour, which guides content and channel choices. Options B, C and D have nothing to do with understanding the audience."}},{"itemId":"4da581b6-7d40-53b1-b652-1b4676df167f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"917eadf9-52b0-5c09-89e8-e5b12b111c77","sourceKey":"bank:LAG-BUA123:DMK-020","parentItemId":null,"revision":1,"payload":{"prompt":"Search engine optimisation (SEO) is best described as:","options":["Paying the search engine each time someone clicks an advert","Sending promotional messages to a list of email subscribers","Improving a website so it ranks higher in unpaid (organic) search results","Paying celebrities to post about a product on their pages"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"SEO improves a website's content, keywords and structure so that it appears higher in the free, organic search listings. Option A is pay-per-click advertising, option B is email marketing, and option D is influencer marketing."}},{"itemId":"c7c6e25c-9bc3-59f5-8183-7deb0f1ef8f7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bdb73a93-1288-5a51-94f2-1c16b733435c","sourceKey":"bank:LAG-BUA123:DMK-021","parentItemId":null,"revision":1,"payload":{"prompt":"A digital marketing method in which the advertiser pays a fee each time someone clicks on its advertisement is called:","options":["Affiliate marketing","Search engine optimisation (SEO)","Content marketing","Pay-per-click (PPC) advertising"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"In pay-per-click advertising the advertiser is charged only when someone clicks the ad, commonly on search engines. Option B aims at free organic rankings, option C attracts audiences with useful content, and option A pays partners commission on sales or leads they bring."}},{"itemId":"5913904d-ca93-5034-be00-679ef24b49be","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d9281431-8fd1-583a-95f3-2c50adfb790f","sourceKey":"bank:LAG-BUA123:DMK-022","parentItemId":null,"revision":1,"payload":{"prompt":"The main difference between SEO and search engine marketing (SEM) through paid search ads is that:","options":["SEO targets unpaid organic listings while paid search buys advertising positions","SEO is used only on television while paid search is used on radio","SEO is paid per click while paid search is completely free","SEO sends emails while paid search sends text messages"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"SEO works to earn higher organic (free) rankings, while paid search places ads on the results page in return for payment, often per click. Option C reverses the two, and options B and D confuse search with broadcast, email and SMS."}},{"itemId":"9a9e825c-47f1-58b6-adbf-8f3539090fd8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e76513bf-3fac-550d-9f4b-86f2610a77cb","sourceKey":"bank:LAG-BUA123:DMK-023","parentItemId":null,"revision":1,"payload":{"prompt":"In search engine marketing, 'keywords' are:","options":["The passwords that staff use to log into the company website","The short slogans painted on roadside billboards and buses","The names of the directors listed in a company's annual report","The words and phrases people type into a search engine to find something"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Keywords are the search terms people enter, and firms choose them carefully so that their website or ads appear for relevant searches. Options A, B and C have no role in how search engines match results to users."}},{"itemId":"f50b6207-ff0a-5df1-952d-392fcb8e97f9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7d6968a4-6684-5300-b036-fa918e98fffd","sourceKey":"bank:LAG-BUA123:DMK-024","parentItemId":null,"revision":1,"payload":{"prompt":"A Port Harcourt hotel pays a search engine so that its advert appears at the top of the results when someone searches 'hotels in Port Harcourt', and it is charged only when a user clicks the advert. This is:","options":["Search engine optimisation","Public relations","Pay-per-click search advertising","Email marketing"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Paying to appear on the results page and being charged per click is pay-per-click search advertising. Option A would involve improving the website to rank organically without paying per click, option D uses subscribers' inboxes, and option B seeks unpaid media coverage."}},{"itemId":"dd1fa3f2-6a8e-5916-ba4e-c9805515e1e9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f72a348b-f0c3-5bd2-8d18-85444bcacfdd","sourceKey":"bank:LAG-BUA123:DMK-026","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos skincare brand publishes free weekly videos and blog posts on how to care for skin in hot, humid weather, without pushing a direct sale in each one. Its main approach is:","options":["Content marketing","Telemarketing","Affiliate marketing","Pay-per-click advertising"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Giving away helpful, relevant content to attract and build trust with an audience is content marketing. Option D involves paying for clicks on ads, option C pays partners for referred sales, and option B is selling by phone."}},{"itemId":"b73b6995-bf9c-591e-a8e4-357927224ee9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"77f99e70-9333-5724-9860-ef2e2a8564a3","sourceKey":"bank:LAG-BUA123:DMK-027","parentItemId":null,"revision":1,"payload":{"prompt":"Email marketing is best described as:","options":["Displaying adverts on roadside billboards and on the sides of buses","Sending commercial messages such as offers and newsletters to people on an email list","Improving a website's ranking in the free results shown by search engines","Paying influencers to recommend the firm's products on their social media pages"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Email marketing sends targeted messages, offers and newsletters directly to subscribers' inboxes. Option C is SEO, option D is influencer marketing, and option A is outdoor advertising."}},{"itemId":"cbcdaafe-771a-5160-95cb-42cc7ac6253d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4741ef93-6065-53da-a989-2d79075e1755","sourceKey":"bank:LAG-BUA123:DMK-028","parentItemId":null,"revision":1,"payload":{"prompt":"Good email marketing practice is permission-based, which means the firm should:","options":["Hide the option to unsubscribe from customers","Send messages only to people who have agreed (opted in) to receive them","Send as many emails as possible every day","Buy lists of strangers' email addresses and send to all of them"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Permission or opt-in email marketing contacts only people who have agreed to receive messages, which builds trust and avoids being treated as spam. Options A, C and D are poor practices that annoy recipients and damage the brand."}},{"itemId":"cb07cc78-92f3-5b18-80a7-6846f76a3403","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"21686833-03bb-5716-9352-d01818128dc6","sourceKey":"bank:LAG-BUA123:DMK-029","parentItemId":null,"revision":1,"payload":{"prompt":"Unsolicited bulk commercial email sent to people who did not ask for it is commonly called:","options":["Spam","Content marketing","An opt-in list","A newsletter"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Spam is unwanted bulk email sent without the receiver's permission, and it harms a brand's reputation. Option D is a regular email subscribers have signed up for, option C is a list of people who agreed to receive email, and option B is about providing valuable content."}},{"itemId":"2af371f0-f3bc-5ec9-80c5-0d10169cea44","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"599bf2e1-3c4d-5836-ab18-0d57c7263706","sourceKey":"bank:LAG-BUA123:DMK-030","parentItemId":null,"revision":1,"payload":{"prompt":"An online bookshop sends a monthly email with new arrivals and discount codes to customers who signed up on its website. This is:","options":["Search engine optimisation","Affiliate marketing","Email marketing","Outdoor advertising"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Sending offers and updates to subscribers who signed up is email marketing. Option A is about search rankings, option D uses billboards and transit, and option B rewards partner sites for referred sales."}},{"itemId":"8920a047-f25e-5906-b206-8f607881abaf","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9d0af77e-bd7c-5c0f-a459-29844094b359","sourceKey":"bank:LAG-BUA123:DMK-031","parentItemId":null,"revision":1,"payload":{"prompt":"Affiliate marketing is best described as:","options":["Placing the firm's adverts in daily newspapers and weekly magazines","Paying partners commission for each sale or lead they bring through referral links","Creating free educational content such as videos to attract an audience","Paying a search engine a fee for every click on the firm's advert"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"In affiliate marketing, other people or websites promote the firm's products and earn a commission only when their link produces a sale or lead. Option D is pay-per-click, option C is content marketing, and option A is print advertising."}},{"itemId":"82551ccf-4a53-5d7b-976c-b7a94c6045ff","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"437ad17c-6c0d-515b-96d2-5c690c00b777","sourceKey":"bank:LAG-BUA123:DMK-032","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian e-commerce site gives bloggers a unique link and pays them 5% commission only on purchases made by shoppers who click their link. This is:","options":["Public relations","Influencer marketing paid as a flat fee","Affiliate marketing","Search engine optimisation"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Paying a commission only on sales that come through a partner's unique link is affiliate marketing. Option B pays for exposure regardless of sales, option D improves organic rankings, and option A seeks unpaid media coverage."}},{"itemId":"84052733-1634-56d3-8389-af8a86434a34","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fbd2a4a0-b7ea-5485-a90d-deac8dff0861","sourceKey":"bank:LAG-BUA123:DMK-033","parentItemId":null,"revision":1,"payload":{"prompt":"Influencer marketing is best described as:","options":["Placing a firm's logo on hoardings around a football stadium","Improving the technical structure of a website so search engines rank it","Sending SMS alerts to every phone number held in a customer database","Partnering with individuals who have a large, engaged online following to promote a brand"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Influencer marketing uses people whom many others follow and trust online, such as content creators, to recommend a brand to their audience. Option B is SEO, option C is SMS marketing, and option A is sponsorship or outdoor advertising."}},{"itemId":"b304bbea-3890-52cd-8bb9-11b43a4d3b83","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cfe4c8b9-1f14-5adb-9a48-3442c297f2b6","sourceKey":"bank:LAG-BUA123:DMK-034","parentItemId":null,"revision":1,"payload":{"prompt":"A drinks company pays a popular Nigerian comedy skit-maker with millions of Instagram followers to feature its product in his videos. This is:","options":["Email marketing","Influencer marketing","Personal selling","Search engine optimisation"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Paying a person with a large, engaged following to feature a product is influencer marketing. Option A uses inboxes, option D improves search rankings, and option C is a salesperson dealing directly with a buyer."}},{"itemId":"12ac250c-f85e-5025-a310-4eac2199543a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"90aadc20-3cf6-5315-8a82-904cc105ee8f","sourceKey":"bank:LAG-BUA123:DMK-035","parentItemId":null,"revision":1,"payload":{"prompt":"The key difference between affiliate marketing and influencer marketing, as usually defined, is that affiliate marketing:","options":["Pays for exposure whether or not any sales result from it","Pays partners mainly according to the sales or leads they actually generate","Never uses the internet or any digital channel","Always involves famous celebrities with millions of followers"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Affiliate marketing is performance-based: partners are paid for the sales or leads their links bring. Influencer marketing focuses on the person's reach and influence, and is often paid for the promotion itself, as option A describes; options C and D are simply untrue."}},{"itemId":"7199777c-e5bc-5234-801f-7747ea60a7d2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5f4d127a-a343-5fc7-9c70-9d73878d5ef3","sourceKey":"bank:LAG-BUA123:DMK-036","parentItemId":null,"revision":1,"payload":{"prompt":"Social media marketing is best described as:","options":["Using social platforms to share content, engage users and build brand communities","Placing adverts on national radio stations during peak listening hours","Paying a commission to other websites only for the sales they refer","Sending printed letters and catalogues to customers' home addresses"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Social media marketing uses platforms such as Facebook, Instagram, X and TikTok to post content, talk with users and build communities. Option D is direct mail, option C is affiliate marketing, and option B is broadcast advertising."}},{"itemId":"58e30dd9-3471-5b57-865b-6489cf161010","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"61a5b4ca-17a7-5ab1-b1d0-f39799c29be0","sourceKey":"bank:LAG-BUA123:DMK-037","parentItemId":null,"revision":1,"payload":{"prompt":"Mobile marketing is best described as:","options":["Running adverts only on national television during prime time","Reaching consumers on their phones through SMS, apps, mobile sites and location-based offers","Advertising on buses and other vehicles that move around the city","Selling products from a moving van that travels between markets"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Mobile marketing targets people through their phones, using SMS, in-app ads, mobile websites and location-based offers. Options C and D involve physical movement, not mobile devices, and option A is broadcast advertising."}},{"itemId":"96c15cd5-6a12-56ab-ae51-46f64e72d8e5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e1665491-a772-5a03-9c80-5a7a3e26c390","sourceKey":"bank:LAG-BUA123:DMK-038","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian telecom operator sends subscribers text messages offering discounted data bundles that can be bought by dialling a short code. This is mainly an example of:","options":["Mobile (SMS) marketing","Content marketing","Outdoor advertising","Search engine optimisation"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Sending promotional text messages to phone users is mobile marketing. Option B relies on publishing valuable content, option D is about search rankings, and option C uses billboards and other outdoor sites."}},{"itemId":"a229f83f-109d-5720-be45-6ef386162c65","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0aac6356-f71c-556d-9b45-4202d618ea9b","sourceKey":"bank:LAG-BUA123:DMK-039","parentItemId":null,"revision":1,"payload":{"prompt":"A marketing approach in which a message is designed so that people pass it on to others, spreading it rapidly like a virus, is called:","options":["Telemarketing","Trade promotion","Viral marketing","Search engine optimisation"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Viral marketing creates messages people want to share, so the message spreads quickly from person to person. Option D is about search rankings, option B targets intermediaries, and option A uses phone calls."}},{"itemId":"e2d0d673-dba3-59fe-af50-cf4fa5a9cd26","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4998997d-003c-58fa-8366-7b6003d11631","sourceKey":"bank:LAG-BUA123:DMK-041","parentItemId":null,"revision":1,"payload":{"prompt":"Display advertising in digital marketing refers to:","options":["Text messages sent to customers' phones","Products arranged on shelves in a supermarket","Unpaid news stories about a company","Visual adverts such as banners shown on websites and apps"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Display advertising places visual ads, such as banners and image or video ads, on websites and apps. Option A is SMS marketing, option B is in-store merchandising, and option C is publicity."}},{"itemId":"e1915539-a489-5d7b-9638-f81e934ed69b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1bb081e0-aede-5209-9cf4-3bab517757c8","sourceKey":"bank:LAG-BUA123:DMK-042","parentItemId":null,"revision":1,"payload":{"prompt":"In digital marketing, 'owned media' refers to:","options":["Billboards and bus panels rented from outdoor advertising firms","Shares, reviews and mentions of the brand by customers and the press","Channels the firm controls itself, such as its website and official social media pages","Advertising space the firm buys on other people's websites and platforms"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Owned media are channels the brand controls, like its own website, app and social media accounts. Option D is paid media, option B is earned media, and option A is also paid space, just offline."}},{"itemId":"68ef0b7f-b3a2-504b-bd5d-d2a0ddae2d5c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"de290de2-36e8-5c26-b12c-18d2f79f7e79","sourceKey":"bank:LAG-BUA123:DMK-043","parentItemId":null,"revision":1,"payload":{"prompt":"Customer reviews, social media shares and free press coverage that a brand receives because of what others say about it are called:","options":["Earned media","Paid media","Owned media","Display media"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Earned media is exposure a brand gains through others, such as reviews, shares and news coverage, without paying for the space. Option B is bought advertising, option C is the brand's own channels, and option D refers to visual banner ads, which are paid."}},{"itemId":"e69597da-b7e1-5581-91a1-9496dab0dcaa","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f125b807-4d2e-5561-aef7-0e0e56fb46cb","sourceKey":"bank:LAG-BUA123:DMK-045","parentItemId":null,"revision":1,"payload":{"prompt":"Inbound digital marketing differs from outbound marketing in that inbound marketing:","options":["Relies only on television and radio commercials","Avoids the internet entirely","Pushes messages at people through cold calls and interruptive adverts","Attracts customers to the firm through useful content, search and social media"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Inbound marketing pulls customers in by being found and offering value, for example through content, SEO and social media. Option C describes outbound marketing, and options A and B describe traditional offline methods."}},{"itemId":"443be0ca-32bc-58ed-a8e2-5104ef012575","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f12c88ea-85a7-5bc5-9f5c-1eab795f3e88","sourceKey":"bank:LAG-BUA123:DMK-046","parentItemId":null,"revision":1,"payload":{"prompt":"Click-through rate (CTR) in digital advertising measures:","options":["The proportion of people who saw an advert and then clicked on it","The time it takes to design an advert","The number of employees in the marketing department","The total amount of money spent on a campaign"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"CTR compares the number of clicks an ad gets with the number of times it was shown, so it shows how attractive the ad is. Option D is campaign cost, and options B and C are internal measures unrelated to audience response."}},{"itemId":"98c943eb-a819-5aec-9b6f-1dd1ef32f3db","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"625ffaab-2eea-507d-9b4f-9bfb3291c30a","sourceKey":"bank:LAG-BUA123:DMK-047","parentItemId":null,"revision":1,"payload":{"prompt":"In digital marketing, a 'conversion' occurs when:","options":["A visitor leaves the website without clicking or doing anything","A visitor completes a desired action, such as making a purchase or signing up","A firm changes its company logo and colours","An advert is shown on a roadside billboard"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"A conversion is when a user does what the marketer wanted, such as buying, registering or downloading. Option A is a bounce, option C is a branding change, and option D is offline exposure."}},{"itemId":"3d29ba99-1a45-5ea2-8464-77222e2fb9fb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"36b44f98-5c63-5748-8621-ccaf838240af","sourceKey":"bank:LAG-BUA123:DMK-048","parentItemId":null,"revision":1,"payload":{"prompt":"After a shopper looks at a pair of sneakers on a Nigerian online store but does not buy, adverts for the same sneakers follow her on other websites she visits. This technique is called:","options":["Affiliate marketing","Search engine optimisation","Public relations","Retargeting (remarketing)"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Retargeting shows ads to people who have already visited a site or viewed a product, reminding them to come back and buy. Option B is about organic search, option A pays partners on referred sales, and option C seeks favourable unpaid coverage."}},{"itemId":"34a1eab8-3de1-5117-8281-3a5f269bb233","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a9669565-dfcc-5fac-8cd2-9d0b24779c55","sourceKey":"bank:LAG-BUA123:DMK-049","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key advantage of digital marketing for small Nigerian businesses?","options":["It works without any need for internet access","It guarantees that every customer will buy the product","It allows them to reach targeted audiences at relatively low cost","It removes all competition from the market"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital tools let small firms target the right people with modest budgets, helping them compete with bigger brands. Option B is untrue because no medium guarantees sales, option D is impossible, and option A is wrong because digital marketing depends on internet access."}},{"itemId":"05e442e0-9836-5fad-83e0-546694f19ab0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b4c31469-d935-5777-9c3a-ae6e9f168fe7","sourceKey":"bank:LAG-BUA123:DMK-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of digital marketing?","options":["Campaigns can reach audiences across the world","Results can be measured in real time","Messages can be personalised for different customers","Messages reach people who have no internet or mobile access"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital marketing depends on internet or mobile access, so it cannot reach people without it; that is a limitation, not an advantage. Options A, B and C are genuine advantages: measurability, personalisation and global reach."}},{"itemId":"ffab80e6-8c45-5919-b572-8fb4cea8456d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ddff3a34-9a37-5909-b165-5550dbfbb6d5","sourceKey":"bank:LAG-BUA123:DMK-051","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a major challenge of digital marketing?","options":["Inability to measure any campaign results","Concerns over customer data privacy and security","Being restricted to one small local area","Lack of any interaction with customers"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Collecting and using customer data raises privacy and security concerns, which firms must manage carefully. Options A, C and D are wrong because digital marketing is highly measurable, interactive and able to reach wide audiences."}},{"itemId":"2e893aea-0f2e-5233-911a-7db2c31e694a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"aa9c9972-cc21-5951-93db-3067d21e4e4b","sourceKey":"bank:LAG-BUA123:DMK-052","parentItemId":null,"revision":1,"payload":{"prompt":"A restaurant in Abuja finds that a single angry customer's post about poor service is shared thousands of times within a day. This illustrates which challenge of digital marketing?","options":["Online audiences never react to what brands do","Digital media reach only a handful of people","Digital messages cannot be shared with other users","Negative messages can spread very quickly and widely online"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Because online content is easy to share, a single negative post can spread fast and damage a brand, so firms must monitor and respond quickly. Options A, B and C contradict what happened in the scenario."}},{"itemId":"ac0bee2f-1f71-5195-b612-256e0b8d2ead","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0435194d-9b29-5dc3-9cb0-c3a27299084e","sourceKey":"bank:LAG-BUA123:DMK-053","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best explains why digital marketers must keep learning and adjusting their strategies?","options":["Digital platforms never change once they are created","Technology, platforms and search or social algorithms change rapidly","Offline media have completely disappeared","Consumers have stopped using the internet"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital channels change fast: new platforms appear and algorithms that decide who sees content are updated often, so strategies must keep adapting. Option A is false, and options C and D are untrue claims about consumers and offline media."}},{"itemId":"54904d87-8656-56f2-a21e-21cc80613536","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3a56f8c6-0fa3-5611-a054-e299a40510a3","sourceKey":"bank:LAG-BUA123:DMK-054","parentItemId":null,"revision":1,"payload":{"prompt":"Why is it important for a firm's website to be mobile-friendly (responsive)?","options":["Many users access the internet mainly through their phones","Search engines ignore all users on mobile phones","Mobile phones are unable to open any websites","People using mobile phones never make purchases"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"A large share of internet users, especially in Nigeria, go online mainly on their phones, so a site that works well on mobile keeps them engaged. Options B, C and D are false statements about mobile devices and their users."}},{"itemId":"5170df65-f1e5-5314-ba7e-2e497e4e8306","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d6926cce-aa32-59df-ad6e-ebbea2803375","sourceKey":"bank:LAG-BUA123:DMK-055","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best describes the relationship between online and offline media in a modern marketing communication plan?","options":["Online media have fully replaced offline media in every market","They must always carry completely different messages","They can be combined so that each supports the other in an integrated campaign","Offline media should never be used once a firm has a website"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Most firms use both: offline media for broad reach and credibility, online media for targeting, interaction and measurement, with a consistent message across them. Options A and D wrongly write off offline media, and option B goes against the idea of a unified, integrated message."}},{"itemId":"0f6b8725-e74e-5bdf-b10a-9787312dbf42","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"389d8664-ec85-5616-a915-e648a7d09ece","sourceKey":"bank:LAG-BUA123:MIX-001","parentItemId":null,"revision":1,"payload":{"prompt":"The set of tools that can be used in various combinations and different degrees of intensity in order to communicate with a target audience is called the:","options":["Marketing communications context","Media schedule","Marketing communications mix","Product life cycle"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The marketing communications mix is the combination of tools such as advertising, sales promotion, personal selling, public relations and direct marketing, used in different mixes and intensities to reach a target audience. Option A refers to the circumstances in which communication takes place, not the tools themselves. Option B is only a timetable for placing adverts."}},{"itemId":"74697478-f0da-5c72-85b9-3efffa59d0d1","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"be067ecd-9f2f-571e-862b-686585ab1972","sourceKey":"bank:LAG-BUA123:MIX-002","parentItemId":null,"revision":1,"payload":{"prompt":"Traditionally, the five main tools of the marketing communications mix are advertising, sales promotion, personal selling, public relations and:","options":["Direct marketing","Packaging","Pricing","Distribution"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Direct marketing completes the traditional five tools of the communications mix. Packaging, pricing and distribution in options B, C and D are elements of the wider marketing mix, not tools of the communications mix."}},{"itemId":"9f2cccf4-5f7e-546e-b0d2-053282ced85f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a543a43b-e15f-5295-ad97-51eb2f2c35f5","sourceKey":"bank:LAG-BUA123:MIX-004","parentItemId":null,"revision":1,"payload":{"prompt":"Advertising, as a tool of the marketing communications mix, is best described as:","options":["An indirect, paid way of informing customers about goods and services through media such as TV, radio, print and websites","Face-to-face presentation by a salesperson who builds personal relationships with prospects","Short-term incentives such as coupons and rebates offered to boost sales quickly","Free coverage of newsworthy events about a firm in the editorial section of the news media"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Advertising is a paid, non-personal (indirect) method of communicating with customers through mass media. Option D describes publicity, which is not paid for, option B describes personal selling, and option C describes sales promotion."}},{"itemId":"608ff45a-d0ed-54de-9e25-823a52ff3461","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"deaab48e-aadf-5f21-8a62-e61e24b25426","sourceKey":"bank:LAG-BUA123:MIX-006","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following are the most common forms of publicity?","options":["Telemarketing calls and catalogues","Coupons, rebates and premiums","News releases, photos and feature stories","Billboards, radio jingles and TV commercials"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"News releases (press releases), photos and feature stories are the usual ways firms get free editorial coverage. Option B lists sales promotion tools, option A lists direct marketing tools and option D lists paid advertising."}},{"itemId":"689bbabc-058b-55ab-b370-ce39f16729d5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cf89f3aa-1891-55d8-8f7d-08646be31417","sourceKey":"bank:LAG-BUA123:MIX-007","parentItemId":null,"revision":1,"payload":{"prompt":"The form of marketing communication that focuses on the firm's reputation through unpaid or earned communication, building positive relationships with media figures and other stakeholders, is:","options":["Public relations","Advertising","Direct marketing","Sales promotion"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Public relations is concerned with the organisation's reputation and its relationships with the media and other stakeholders, mostly through earned rather than paid communication. Option B is paid communication in bought media space, while options C and D aim at boosting sales through incentives or personalised offers."}},{"itemId":"36f8e53e-c44a-5050-bb23-59232c3555a5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"44d71ae9-120d-5de9-9eac-b733eb6aa789","sourceKey":"bank:LAG-BUA123:MIX-008","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following activities is typically part of public relations?","options":["Buying a 30-second TV commercial","Telemarketing to a customer list","A buy-one-get-one-free offer","Crisis management"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Crisis management, along with press releases and communication campaigns, is a core PR activity used to protect reputation and relationships with stakeholders. Option C is a sales promotion, option B is direct marketing and option A is paid advertising."}},{"itemId":"98f683f3-d28d-5bd2-aeb6-95d945b73a8a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c0d30de6-9050-55a7-979a-81aef516a319","sourceKey":"bank:LAG-BUA123:MIX-009","parentItemId":null,"revision":1,"payload":{"prompt":"After a rumour spread online that its bottled water was contaminated, a Lagos water company held a press conference, issued a press release and invited journalists to tour its factory. Which communication tool is the company mainly using?","options":["Sales promotion","Personal selling","Direct marketing","Public relations"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Responding to a rumour with press conferences, press releases and media tours is public relations, specifically crisis management aimed at protecting the firm's reputation. Option A would involve incentives such as discounts, and option C would involve personalised messages to individual customers."}},{"itemId":"eb2edcd5-a8cc-5d88-9d02-257851862370","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fa4f2fd6-c7e4-5f16-8806-ec8322d3d8d7","sourceKey":"bank:LAG-BUA123:MIX-010","parentItemId":null,"revision":1,"payload":{"prompt":"The area of marketing communications that aims to stimulate sales through incentives, short-term discounts and other promotional offers is:","options":["Advertising","Personal selling","Sales promotion","Public relations"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Sales promotion uses short-term incentives and offers to give people an extra reason to buy now. Option D is about reputation, option B is face-to-face selling, and option A is paid mass-media communication that does not by itself offer an incentive."}},{"itemId":"12453622-9967-549b-996b-7b5a2d38e5de","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a6210059-023e-5a67-8256-b75595da8a7d","sourceKey":"bank:LAG-BUA123:MIX-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a sales promotion technique?","options":["Coupons","Buy-one-get-one-free offers","Rebates","A press release"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"A press release is a publicity and PR tool used to gain free news coverage. Coupons, rebates and buy-one-get-one-free offers, options A, B and C, are all incentives used in sales promotion."}},{"itemId":"c31249f6-08ac-52c6-bf9e-4621a769c704","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"30693382-4c9f-573d-b272-c0f438fabfd1","sourceKey":"bank:LAG-BUA123:MIX-012","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere supermarket announces that, this weekend only, any customer who buys two packs of noodles gets a third pack free. This is an example of:","options":["Direct marketing","Sales promotion","Publicity","Public relations"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"A time-limited 'buy two, get one free' offer is a short-term incentive to boost sales, which is sales promotion. Option C would be free news coverage, and option D would focus on reputation rather than an immediate offer."}},{"itemId":"5dc71c90-2e36-5c53-b03f-b552aef2d6ee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"81023fe3-5979-56fa-a291-255dc3e479c0","sourceKey":"bank:LAG-BUA123:MIX-013","parentItemId":null,"revision":1,"payload":{"prompt":"Personal selling is best described as:","options":["Free coverage of a firm's activities in newspapers and on the television news","Paid, one-way communication to a mass audience through TV and radio broadcasts","Face-to-face communication in which a salesperson informs prospects and builds relationships","An online catalogue that lets customers place orders with no human contact"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Personal selling involves a salesperson approaching prospects directly, mostly face to face, to inform them and build relationships. Option B describes advertising, option A describes publicity, and option D lacks the personal salesperson contact that defines personal selling."}},{"itemId":"1a71dc34-70ba-5b20-88b6-1d0d0e111900","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5e92045d-bd89-52dd-98b3-bc7a3a3d0c3e","sourceKey":"bank:LAG-BUA123:MIX-014","parentItemId":null,"revision":1,"payload":{"prompt":"Personal selling is regarded as one of the most reliable modes of marketing communication mainly because:","options":["It reaches millions of people at the same moment","It has the lowest cost per customer contacted","It relies on the news media to carry the message free of charge","It is done directly with the prospect, orally face to face or in writing"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Personal selling is considered reliable because the seller deals directly with the prospect and can respond to that person. Options A and B describe advertising strengths; personal selling actually reaches few people and costs a lot per contact. Option C describes publicity."}},{"itemId":"c0c3979f-beb8-5c90-87cc-a357063c775e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"20e17135-ffeb-5f59-983f-1dd51b94b3e5","sourceKey":"bank:LAG-BUA123:MIX-015","parentItemId":null,"revision":1,"payload":{"prompt":"Direct marketing differs from advertising on mass media mainly because direct marketing:","options":["Communicates directly with individuals in a more personalised way","Is aimed at the general public rather than at selected individuals","Appears only in the editorial section of newspapers","Is always provided free of charge by the media"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Direct marketing is a more personalised form of communication that reaches individuals directly, rather than through general messages on mass media. Option B reverses this, and options C and D describe publicity rather than direct marketing."}},{"itemId":"62ddacbd-675a-5d37-b71f-9be4c6cd6ade","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ed49ec91-c6c4-5a9f-ac3c-957b798aa004","sourceKey":"bank:LAG-BUA123:MIX-016","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of direct marketing?","options":["Sponsoring a state football tournament","A personalised email offer sent to customers on a company's mailing list","A press release sent to newspaper editors","A television commercial shown during the evening news"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Emails sent to named individuals on a list are a classic direct marketing tool, along with brochures, interactive websites and telemarketing. Option D is mass advertising, option C is publicity, and option A is event sponsorship."}},{"itemId":"57228ce1-4d2b-509b-94f7-103b4b90bd9a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a7a335de-c21f-5800-a3f0-4c9d65a94fcd","sourceKey":"bank:LAG-BUA123:MIX-017","parentItemId":null,"revision":1,"payload":{"prompt":"An Ikeja furniture company mails printed brochures, each addressed by name and with a reply form, to 2,000 customers on its database. Which communication tool is this?","options":["Event sponsorship","Direct marketing","Publicity","Advertising"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Sending addressed brochures to individuals from a database is direct marketing, because the message goes straight to selected people and invites a response. Option D would use mass media to reach a general audience, and option C would rely on free news coverage."}},{"itemId":"6c91053a-0bbc-5dc2-8fa2-b0a31b0c735e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8f7c267e-955f-529e-b96a-02eab6121efd","sourceKey":"bank:LAG-BUA123:MIX-018","parentItemId":null,"revision":1,"payload":{"prompt":"When companies sponsor sports, entertainment, non-profit or community events in order to reinforce their brand in customers' minds and create a long-term association, they are using:","options":["Interactive marketing","Word-of-mouth marketing","Events and experiences","Direct marketing"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Events and experiences (sponsorship) link the brand to activities that customers value, giving brand exposure and a lasting association. Option A is about customers interacting with the firm online, and option B is customers sharing experiences with friends."}},{"itemId":"fc8e7705-51d9-52dc-9aca-4381a675b7b9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ceccbda1-af3a-5db2-b12e-2189b3b1b304","sourceKey":"bank:LAG-BUA123:MIX-019","parentItemId":null,"revision":1,"payload":{"prompt":"A telecom company pays to have its name attached to a university inter-faculty football competition, with its logo on jerseys and banners throughout the season. This is mainly an example of:","options":["Sales promotion","Events and experiences (sponsorship)","Direct marketing","Personal selling"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Paying to associate a brand with a sports event for exposure is sponsorship, which falls under events and experiences. Option D needs a salesperson dealing with prospects, and option A needs a short-term incentive to buy, neither of which is present here."}},{"itemId":"76207b85-ffee-5b51-9859-bd59cfc5ba6d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fc633f08-1fc9-5203-a4fe-378b430c9973","sourceKey":"bank:LAG-BUA123:MIX-020","parentItemId":null,"revision":1,"payload":{"prompt":"An online store lets customers ask questions and get them resolved online, and shows each customer what they chose or ordered in the recent past. This approach is called:","options":["Interactive marketing","Word-of-mouth marketing","Publicity","Personal selling"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Interactive marketing lets customers interact with the firm online and get their queries resolved there, as on Amazon. Option B involves customers talking to their peers, not to the firm, and option D needs a salesperson approaching the prospect."}},{"itemId":"7cd4db34-4345-5e6d-b7a9-a3f23cfa72f6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"613c65f6-e3bf-5223-b6ef-496aa2b36f1b","sourceKey":"bank:LAG-BUA123:MIX-021","parentItemId":null,"revision":1,"payload":{"prompt":"The communication tool in which customers share their experiences of goods and services they recently bought with their peers and friends is:","options":["Word-of-mouth marketing","Public relations","Interactive marketing","Direct marketing"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Word-of-mouth marketing happens when customers pass on their experiences to friends and peers. Option C is interaction between customer and firm, and option D is personalised communication sent by the firm itself."}},{"itemId":"639bce39-7bf6-5a97-be55-d910dca3fcf4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ac0fd181-c9cf-5961-abaa-4021c889cb3e","sourceKey":"bank:LAG-BUA123:MIX-022","parentItemId":null,"revision":1,"payload":{"prompt":"Apart from the communication tools, the marketing communications mix also includes media, which are best described as:","options":["The customers who receive and interpret the firm's messages","The channels in which time and space can be bought or used to deliver messages to target audiences","The incentives offered to customers to boost short-term sales","The staff who design and manufacture the product"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Media are the channels, such as TV, radio, newspapers or websites, in which time and space are bought or used to carry messages to the audience. Option A describes receivers, and option C describes sales promotion."}},{"itemId":"c3921a81-9deb-5ae1-8ea8-0518e90fe1e4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9966702a-9875-5b8f-8b56-7522a9f2947b","sourceKey":"bank:LAG-BUA123:MIX-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication tool is generally regarded by audiences as the most credible?","options":["Advertising","Public relations","Direct marketing","Sales promotion"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"PR messages usually reach people through third parties such as journalists, so audiences see them as more believable than messages the firm pays for. Option A, advertising, is often viewed with suspicion because everyone knows the firm paid to say good things about itself."}},{"itemId":"b89b8159-7ccb-5377-84a8-8ab222ca1192","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ee9606e0-46ca-5337-9226-d6ea7ccc61d8","sourceKey":"bank:LAG-BUA123:MIX-024","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication tool gives the organisation the LEAST control over the final message that reaches the audience?","options":["Sales promotion","Advertising","Public relations (publicity)","Direct marketing"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"With publicity, the media decide whether to use the story and how to present it, so the firm has little control over the final message. With advertising, direct marketing and sales promotion, options A, B and D, the firm pays for or designs the message and decides its content and timing."}},{"itemId":"3542e708-07cc-5283-b3bb-429d2d3e10df","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"15da2e4e-efab-59b1-8018-260d9eb66898","sourceKey":"bank:LAG-BUA123:MIX-025","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication tool usually has the highest cost per contact?","options":["Sales promotion","Public relations","Advertising","Personal selling"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Personal selling requires a salesperson's time, travel and pay for each prospect, so the cost of each contact is high. Option C, advertising, may cost a lot in total but spreads that cost over a very large audience, giving a low cost per contact."}},{"itemId":"cc42fc98-e3ef-5c72-8280-2ecb26a60e26","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bac8efa5-fdff-5ac0-b88b-099fc0d32362","sourceKey":"bank:LAG-BUA123:MIX-026","parentItemId":null,"revision":1,"payload":{"prompt":"Which communication tool allows the greatest two-way interaction and immediate feedback from the customer?","options":["Sales promotion","Personal selling","Advertising","Public relations"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"In personal selling the seller and buyer talk directly, so the seller can see reactions, answer questions and adjust the message immediately. Advertising, option C, is largely one-way communication with delayed feedback."}},{"itemId":"1f0e919b-3e8a-5d2b-a541-6ebaae5bff15","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1a94bb05-3505-5f6a-be1d-b1a84131d851","sourceKey":"bank:LAG-BUA123:MIX-027","parentItemId":null,"revision":1,"payload":{"prompt":"A major weakness of advertising compared with personal selling is that advertising:","options":["Cannot reach a large and widely spread audience","Is largely one-way and impersonal, so it cannot adapt to each person's questions","Has a very high cost per person reached","Gives the firm no control over the content of the message"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Advertising talks at the audience rather than with them, so it cannot respond to each individual the way a salesperson can. Options A and C are actually advertising's strengths reversed, since it reaches large audiences at a low cost per contact, and option D is wrong because the advertiser controls the message."}},{"itemId":"2aae344b-4d8c-5193-9b87-26d184138978","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"44ee2cbf-7cfe-5d9c-b7cf-b97a9e237f53","sourceKey":"bank:LAG-BUA123:MIX-028","parentItemId":null,"revision":1,"payload":{"prompt":"A major strength of advertising is its ability to:","options":["Close sales through face-to-face negotiation with each buyer","Obtain coverage in the news media without paying for it","Deliver a message tailored to one person at a time","Reach a large, geographically dispersed audience at a low cost per contact"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Advertising can repeat a message many times to a mass audience spread over a wide area, and the cost per person reached is low. Options A and C are strengths of personal selling, and option B describes publicity."}},{"itemId":"5a3b9625-fd22-5cc6-b4e4-e6f36b8c6348","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a0db8b1e-e6d4-56ff-8615-ada2b3103870","sourceKey":"bank:LAG-BUA123:MIX-029","parentItemId":null,"revision":1,"payload":{"prompt":"A main weakness of relying heavily on sales promotion is that it:","options":["Mainly gives short-term sales gains and can make buyers wait for deals","Takes many years before it has any noticeable effect on sales","Is seen as the most credible tool because journalists deliver it","Cannot be measured in any way, so its results are unknown"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Sales promotion gives a quick, short-term lift in sales, but frequent deals can make customers wait for offers and weaken the brand's image. Option B is the opposite, since promotions work fast, and option C describes publicity, not sales promotion."}},{"itemId":"d591496f-410d-57d5-8d46-6da81c68ac93","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2368f1cf-f707-5464-abbf-b772c08489a8","sourceKey":"bank:LAG-BUA123:MIX-030","parentItemId":null,"revision":1,"payload":{"prompt":"The main strength of publicity compared with advertising is that:","options":["It allows face-to-face negotiation with each customer","The firm can decide exactly when and how the story will appear","It guarantees an immediate increase in sales","Audiences tend to see it as more believable because it comes from a third party such as the news media"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"A story carried by journalists looks like news rather than a sales pitch, so people tend to believe it more. Option B is a weakness turned around, because the media, not the firm, control publicity, and option A describes personal selling."}},{"itemId":"41d8fb70-3e7a-5ea8-bf5d-87be38183172","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cb2f8c52-7370-535c-a528-47318ec0f20b","sourceKey":"bank:LAG-BUA123:MIX-031","parentItemId":null,"revision":1,"payload":{"prompt":"A key weakness of personal selling is that it:","options":["Reaches relatively few people and is expensive per contact","Has low credibility because the message is unpaid","Cannot respond to customers' questions and objections","Cannot be used for industrial or business products"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Each salesperson can only meet a limited number of prospects, and their pay and expenses make every contact costly. Option C is wrong because answering questions is personal selling's main strength, and option D is wrong because personal selling is especially important for business products."}},{"itemId":"d3852cad-400f-573c-a6cd-8c505bb21f81","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"56d49aaa-987e-52e2-b367-9d6a23f0f102","sourceKey":"bank:LAG-BUA123:MIX-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common weakness of direct marketing?","options":["Recipients may see unsolicited mail, calls or emails as intrusive 'junk'","The message cannot be personalised for individual customers","Responses to the campaign cannot be measured","It can only reach the mass market, not selected individuals"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Many people resent unrequested mail, calls or emails, which can irritate them and harm the firm's image. Options B, C and D are wrong because personalisation, measurable responses and reaching selected individuals are exactly what direct marketing does well."}},{"itemId":"a4c73246-d39e-5439-aec2-9759e1da916d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f2e460aa-0b3e-5cf8-bd29-06a7b8d61951","sourceKey":"bank:LAG-BUA123:MIX-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which set of criteria is commonly used to compare marketing communication tools when selecting the communications mix?","options":["Strengths, weaknesses, opportunities and threats","Product, price, place and promotion","Awareness, interest, desire and action","Communication effectiveness, credibility, cost and control"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Tools are compared on how well they communicate with the target audience, how believable they are, what they cost and how much control the firm has over the message. Option B is the marketing mix, option A is SWOT analysis, and option C is the AIDA model of how a message works."}},{"itemId":"4892b12b-6fa7-5201-a232-2d1295c2ad99","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"75cd1c8f-81ad-5387-9a09-135e6ae61b01","sourceKey":"bank:LAG-BUA123:MIX-034","parentItemId":null,"revision":1,"payload":{"prompt":"Television advertising is often said to have a high absolute cost but a low cost per contact. This means that:","options":["The total bill is large, but divided over the very large audience reached, the cost per person is small","The cost depends only on how many units are eventually sold","Both the total bill and the cost per person reached are small","The total bill is small, but the cost per person reached is very large"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Absolute cost is the total amount paid for the campaign, while cost per contact is that amount divided by the number of people reached. Because TV reaches so many people, a large total becomes small per person. Option D reverses the two ideas."}},{"itemId":"9d11dded-9293-52d3-96b8-67cc46322d30","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d83bd0bd-2e72-5ad2-bd60-c3dc62b4bdcb","sourceKey":"bank:LAG-BUA123:MIX-035","parentItemId":null,"revision":1,"payload":{"prompt":"A new small fashion business in Yaba has very little money for promotion. Which of the following is generally the most cost-effective way for it to gain wide coverage at launch?","options":["Sending a news release about an interesting launch event to local media","Sponsoring a national football league for a season","Hiring a large field sales force to visit customers","Running a national television advertising campaign"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"PR and publicity have a low absolute cost, so a newsworthy launch story can gain coverage without paying for media space. Options B, C and D all require large budgets that a small new business is unlikely to have."}},{"itemId":"960b2b54-e00b-5728-bf11-2a206e903df5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c5ac43db-df7f-5963-afd3-0a1b02f9eebc","sourceKey":"bank:LAG-BUA123:MIX-036","parentItemId":null,"revision":1,"payload":{"prompt":"Factors that influence the choice of the marketing communications mix can be grouped into product-related, customer-related, organisation-related and:","options":["Supplier-related factors","Media-related factors","Price-related factors","Competition and situation related factors"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The four groups of selection factors are product-related, customer-related, organisation-related, and competition and situation related factors. Options A, B and C are not among the four groups; for example, price comes in only as unit price within the product-related group."}},{"itemId":"fd04ab57-b066-5bfc-ae1f-84467f422868","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1e501291-a339-58dd-bc25-a3b4ae79f441","sourceKey":"bank:LAG-BUA123:MIX-037","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a product-related factor in selecting the marketing communications mix?","options":["The impact of competition","The promotion budget","The stage of the product in its life cycle","The characteristics of the target market"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Product-related factors are the amount and complexity of product information, the stage of the product life cycle, and product type and unit price. Option D is customer-related, option B is organisation-related and option A is a competition and situation factor."}},{"itemId":"407d2453-2e04-5249-a273-a568e798089c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c06cbdc6-7e1e-537e-9ad3-0a2484db4b33","sourceKey":"bank:LAG-BUA123:MIX-038","parentItemId":null,"revision":1,"payload":{"prompt":"In selecting the marketing communications mix, the type of buying decision the customer faces is classified as a:","options":["Customer-related factor","Product-related factor","Competition and situation related factor","Organisation-related factor"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Customer-related factors are the characteristics of the target market and the type of buying decision. Option B covers things like product complexity and life cycle stage, and option D covers channel, branding and budget."}},{"itemId":"b35cd51a-4be5-5244-8cc8-d7d7ae91bee7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a74d89be-9284-5ef5-8425-ee379ecbaf23","sourceKey":"bank:LAG-BUA123:MIX-039","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing channel adopted, the branding strategy and the budget are grouped as which type of factors affecting the choice of communications mix?","options":["Competition and situation related factors","Product-related factors","Organisation-related factors","Customer-related factors"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"These three are decisions and resources inside the firm, so they are organisation-related factors. Option D refers to the target market and buying decision, and option A refers to the firm's visibility, environment and competition."}},{"itemId":"00fd7feb-d5b2-55bb-a6f4-b2cf3d0b80bd","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"45aad94f-5045-58f8-b39d-1f429e0e31d5","sourceKey":"bank:LAG-BUA123:MIX-040","parentItemId":null,"revision":1,"payload":{"prompt":"The visibility of the firm and its political, legal and social environment, together with the impact of competition, are classified as:","options":["Competition and situation related factors","Organisation-related factors","Product-related factors","Customer-related factors"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"These factors describe the situation the firm finds itself in and the competition it faces, so they form the competition and situation group. Option B covers internal matters such as budget and branding, and option D covers the target market and buying decision."}},{"itemId":"cc03e7cc-e370-517f-a55b-1ef47bc4b090","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ab495b2c-fc40-5851-84ae-f2d9611d6fe8","sourceKey":"bank:LAG-BUA123:MIX-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a product-related factor in choosing the marketing communications mix?","options":["Product type and unit price","The amount and complexity of product information to be communicated","Branding strategies","The stage of the product in its life cycle"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Branding strategies are an organisation-related factor, alongside the marketing channel and budget. Options A, B and D are the three product-related factors."}},{"itemId":"4ebdac02-324f-5dfc-af6d-918f7d62dd1d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5a8e023c-6f05-50d9-8c3b-8133f6284f91","sourceKey":"bank:LAG-BUA123:MIX-042","parentItemId":null,"revision":1,"payload":{"prompt":"A firm sells expensive, technically complex medical scanners to a small number of hospitals. Which communication tool is it most likely to rely on most heavily?","options":["Mass television advertising","Free product samples at supermarkets","Personal selling","Coupons and other consumer sales promotions"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"When a product is costly, complex and bought by few business buyers, a salesperson is needed to explain details, answer questions and negotiate. Options B and D suit cheap consumer goods, and option A would waste money reaching millions of people who will never buy a scanner."}},{"itemId":"01b45efe-509c-5ffb-a67b-ef970ef85784","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"577f0fa2-d778-5ad1-b654-47d83e2257f9","sourceKey":"bank:LAG-BUA123:MIX-043","parentItemId":null,"revision":1,"payload":{"prompt":"For low-priced, frequently bought consumer goods such as soft drinks sold to millions of people, the communications mix usually leans most heavily on:","options":["Exhibitions at trade fairs only","Personal selling to each individual buyer","Negotiations led by senior managers","Advertising and sales promotion"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Cheap products bought often by a mass market need tools that reach many people at low cost per contact and encourage purchase, which is why advertising and sales promotion dominate. Options B and C are far too costly per buyer for a low-priced item."}},{"itemId":"08b34132-39d7-536c-90e9-f359c7bca958","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6d96070d-d790-596d-81d5-bbfcc2cf29fa","sourceKey":"bank:LAG-BUA123:MIX-044","parentItemId":null,"revision":1,"payload":{"prompt":"A push promotion strategy involves:","options":["Communicating with a wide range of stakeholders to build the corporate reputation","Directing communication such as personal selling and trade promotions at channel members, so they stock and promote the product to end users","Relying only on customers recommending the product to their friends","Directing advertising and consumer promotions at final consumers, so they ask retailers for the product"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"In a push strategy the producer promotes to wholesalers and retailers, who in turn push the product along the channel to consumers. Option D is a pull strategy, and option A is a profile strategy aimed at corporate reputation."}},{"itemId":"50e1708f-57ee-51f6-b44e-fd0560d6325d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4e0f6c7b-9436-52d2-8e16-84ac9ba16d1e","sourceKey":"bank:LAG-BUA123:MIX-045","parentItemId":null,"revision":1,"payload":{"prompt":"A manufacturer spends heavily on TV adverts and consumer coupons so that consumers ask retailers for its brand, which makes retailers order the brand from the manufacturer. This is a:","options":["Profile strategy","Push strategy","Trade promotion strategy","Pull strategy"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"In a pull strategy, communication is aimed at final consumers to create demand that pulls the product through the channel. Option B works the other way, by promoting to intermediaries, and option C is also aimed at intermediaries rather than consumers."}},{"itemId":"2ecd0c78-4d63-505e-a019-14bb3c85deac","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b24b409d-f8d4-5bd9-b5c0-f61f9aeeecda","sourceKey":"bank:LAG-BUA123:MIX-046","parentItemId":null,"revision":1,"payload":{"prompt":"A new seasoning brand gives wholesalers at Idumota market extra margins, display allowances and regular visits from sales representatives so that they stock it and recommend it to retailers. This is mainly a:","options":["Profile strategy","Pull strategy","Push strategy","Word-of-mouth strategy"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The effort is directed at wholesalers, the channel intermediaries, using trade incentives and personal selling, which is a push strategy. Option B would target final consumers with advertising and consumer promotions instead."}},{"itemId":"72b60375-cb26-5a5d-8730-957ef5a5cf0c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d4c157a9-9392-52d6-b73b-67be5feb0b90","sourceKey":"bank:LAG-BUA123:MIX-047","parentItemId":null,"revision":1,"payload":{"prompt":"A communication strategy aimed at a wide range of stakeholders, such as investors, government and the local community, to build the organisation's corporate reputation rather than to move products through the channel, is called a:","options":["Profile strategy","Push strategy","Pull strategy","Sales promotion strategy"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"A profile strategy focuses on how the organisation as a whole is seen by its stakeholders, building corporate identity and reputation. Options B and C are about moving products to intermediaries and consumers respectively."}},{"itemId":"65852be9-e90b-5262-83ae-850b12c53d05","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f0ac31ba-5bae-5222-b2b4-c8ae4cd633f6","sourceKey":"bank:LAG-BUA123:MIX-048","parentItemId":null,"revision":1,"payload":{"prompt":"At the introduction stage of the product life cycle, the communications mix typically emphasises:","options":["Reminder advertising only, since buyers already know the product","Cutting nearly all promotion to save costs","Advertising and publicity to build awareness, with sales promotion to encourage trial","Heavy price-off deals mainly to clear old stock before withdrawal"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"A new product is unknown, so advertising and PR are used to build awareness and sales promotion helps persuade people to try it. Option A fits the maturity or decline stages, and options B and D describe the decline stage."}},{"itemId":"3a893974-5711-53b2-9725-16ce9e81554b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ba040cdc-e729-50a9-9e41-d1d7eaf7fcb2","sourceKey":"bank:LAG-BUA123:MIX-049","parentItemId":null,"revision":1,"payload":{"prompt":"In the decline stage of the product life cycle, a firm usually:","options":["Doubles its sales force to explain the product's basic features","Launches a major PR campaign to introduce the product for the first time","Reduces promotion to a low level, perhaps keeping some reminder advertising","Raises advertising sharply to create awareness of a brand-new product"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"When sales are falling, most promotion is cut back, with perhaps enough reminder advertising to keep loyal buyers. Options A, B and D describe the heavy awareness-building effort typical of the introduction stage."}},{"itemId":"263c94d7-f4d1-567c-a42b-988a0e49e25b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cf56dbdc-ea8d-50db-bb37-51c8bbdca865","sourceKey":"bank:LAG-BUA123:MIX-050","parentItemId":null,"revision":1,"payload":{"prompt":"In the maturity stage of the product life cycle, when most buyers already know the brand and competition is intense, which tool tends to become relatively more important?","options":["Introductory publicity","Sales promotion","Personal selling to explain a brand-new concept","Teaser advertising for a new launch"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"In maturity, sales promotion grows in importance relative to advertising, as firms use incentives to defend market share against strong competitors. Options A, C and D are suited to launching something new, when buyers need to learn about it."}},{"itemId":"28d10ade-ceb4-59c3-a55e-793909de9556","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3fad0077-d4dd-5b96-b6eb-93248862af7f","sourceKey":"bank:LAG-BUA123:MIX-051","parentItemId":null,"revision":1,"payload":{"prompt":"When analysing the context in which marketing communications will take place, the four contexts usually considered are the:","options":["Introduction, growth, maturity and decline contexts","Source, message, medium and receiver contexts","Customer, business, internal and external contexts","Product, price, place and promotion contexts"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Context analysis looks at the customer context, the business context, the internal context of the organisation and the wider external context. Option D is the marketing mix, option B lists elements of the communication process, and option A lists stages of the product life cycle."}},{"itemId":"1dcc8988-4631-5ad9-a040-f31e9de4eb62","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a207bff9-e774-5481-9e61-124635913490","sourceKey":"bank:LAG-BUA123:MIX-052","parentItemId":null,"revision":1,"payload":{"prompt":"Before planning a campaign, a Kano food company finds that it has a small promotion budget, few staff skilled in social media and a cautious company culture. These findings relate to the:","options":["Customer context","Internal context","External context","Business context"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The internal context covers what is inside the organisation: its financial resources, staff skills, culture and identity. Option C covers forces outside the firm such as PEST factors, and option A covers the target audience's needs and behaviour."}},{"itemId":"eff3ba8a-1059-59bd-a6b1-de13b76d9d58","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4cc8e476-96d2-5019-8076-1e2c8ff5779e","sourceKey":"bank:LAG-BUA123:MIX-053","parentItemId":null,"revision":1,"payload":{"prompt":"Political, economic, social and technological (PEST) factors and the organisation's wider stakeholders are analysed as part of the:","options":["Customer context","External context","Internal context","Business context"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The external context covers forces outside the organisation that it cannot control, such as PEST factors and stakeholders. Option C is about the firm's own resources and culture, and option A is about the target segment."}},{"itemId":"82f20b10-d37f-579c-b8c6-13baca57c2ea","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"612c67b6-3870-588d-9dd8-01e733b14569","sourceKey":"bank:LAG-BUA123:MIX-054","parentItemId":null,"revision":1,"payload":{"prompt":"Analysing the needs, perceptions and decision-making process of the target segment is part of the:","options":["Internal context","Customer context","External context","Business context"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The customer context is about understanding the target audience: who they are, what they need, how they see the brand and how they make buying decisions. Option A looks inside the firm, and option C looks at wider environmental forces."}},{"itemId":"35006972-30d6-5aad-a55a-972c53230f9d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ce47ad57-1935-5c21-80c9-aba83806f55d","sourceKey":"bank:LAG-BUA123:PLN-001","parentItemId":null,"revision":1,"payload":{"prompt":"A model that shows communication as a one-way flow from a sender, through encoding, a message and a channel, to decoding by a receiver is called:","options":["The two-step flow model","The innovation-adoption model","The AIDA model","The linear model of communication"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The linear model shows communication moving in one direction from sender to receiver through encoding, message, channel and decoding, with feedback and noise added in later versions. Option A is about media influence passing through opinion leaders, while options C and B are hierarchy-of-effects models of buyer response."}},{"itemId":"e93f893b-4fcd-51cf-8a8d-e9bd8bbd40f3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f2c4a548-1b4d-5bae-8755-25333ee06e5a","sourceKey":"bank:LAG-BUA123:PLN-002","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, 'encoding' means:","options":["The receiver interpreting the message","Anything that distorts the message","The medium that carries the message","Turning the sender's ideas into a message made of words, pictures, symbols or sounds"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Encoding is the sender's job of putting an idea into a form that can be sent, such as words, images, symbols or sounds. Option A is decoding, option C is the channel or medium, and option B is noise."}},{"itemId":"0554e055-ab9b-50ad-ab58-8b25db423ffc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4c1c1a11-7eb1-55a8-9bed-ec5f49e02c14","sourceKey":"bank:LAG-BUA123:PLN-003","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication process, 'decoding' refers to:","options":["Interference that disrupts the message","The sender converting ideas into symbols","The sender choosing which medium to use","The receiver interpreting the symbols in a message to give it meaning"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Decoding is the receiver's work of interpreting the words, images or sounds and assigning meaning to them. Option C is a channel decision, option B is encoding, and option A is noise."}},{"itemId":"ab7a8a79-e16e-51da-acda-c9e96e809e09","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a412e208-f437-5f64-8c2e-270c608a9ca6","sourceKey":"bank:LAG-BUA123:PLN-004","parentItemId":null,"revision":1,"payload":{"prompt":"Any unplanned interference or distortion in the communication process that stops the receiver getting the message as intended is called:","options":["Encoding","Field of experience","Noise","Feedback"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Noise is any unplanned distortion or interference, such as a poor network signal or competing adverts, that prevents the message being received as intended. Option D is the receiver's response, option A is the sender putting ideas into symbols, and option B is the experience each party brings."}},{"itemId":"1fdc8d93-0b6b-5ca9-b5a1-fc1d7d638680","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a59e43a9-8ba5-5269-bdd4-800c9a2dda12","sourceKey":"bank:LAG-BUA123:PLN-005","parentItemId":null,"revision":1,"payload":{"prompt":"After hearing a radio jingle for a new noodle brand, a listener calls the toll-free line to ask where to buy it. In the communication model, the call is an example of:","options":["The channel","Noise","Encoding","Feedback"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Feedback is the part of the receiver's response that goes back to the sender, and a phone call asking where to buy is a direct example. Option C is done by the sender, option B is interference, and option A is the radio itself."}},{"itemId":"366483cc-046b-5613-9ad6-a789fbc4f80b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8c560e52-73f5-53ad-b955-518744b1cabf","sourceKey":"bank:LAG-BUA123:PLN-006","parentItemId":null,"revision":1,"payload":{"prompt":"In Schramm's model of communication, the 'field of experience' refers to:","options":["The budget available for the campaign","The number of times an advert is broadcast","The physical room where an advert is shown","The experiences, attitudes and perceptions that sender and receiver bring, with understanding greatest where they overlap"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Each party brings its own experiences, values and perceptions to the process, and communication works best where the sender's and receiver's fields of experience overlap. Options C, B and A are a place, a frequency and a budget, not shared understanding."}},{"itemId":"826c728e-43cc-5fa5-b4fb-10aa38f5e77b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4bc7e015-b197-5ef5-bddc-5add0fb811da","sourceKey":"bank:LAG-BUA123:PLN-007","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bank uses slang and references that its young target customers in Ibadan do not understand, so the advert fails. In Schramm's terms, the failure is mainly due to:","options":["Too much feedback from the receiver","Encoding the message in a shared language","Choosing a medium with no noise","Too little overlap between the fields of experience of sender and receiver"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"When sender and receiver share little experience, the receiver cannot decode the symbols as intended, so the message fails. Option A would help, not harm, option C describes an ideal situation, and option B would increase understanding."}},{"itemId":"f9d803b5-d957-5587-b2c0-78b9d54d2e9c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"50975472-2df6-5b75-a868-50a3b937fbad","sourceKey":"bank:LAG-BUA123:PLN-008","parentItemId":null,"revision":1,"payload":{"prompt":"A key weakness of the basic linear model of communication is that it:","options":["Applies only to personal selling","Treats communication as a one-way process with a passive receiver","Ignores the sender completely","Includes too many opinion leaders"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The basic linear model shows messages flowing one way to a passive receiver, which understates how audiences interpret, respond and talk back, especially in the digital age. Options D, C and A are not features of the linear model."}},{"itemId":"b52555cb-2e32-5be9-8ab1-cc474274bd3f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1bc3471c-d8c5-5400-b588-24e047941ad4","sourceKey":"bank:LAG-BUA123:PLN-009","parentItemId":null,"revision":1,"payload":{"prompt":"A model in which messages flow from the mass media to opinion leaders, who then pass them on to opinion followers, is the:","options":["AIDA model","DAGMAR model","One-step (hypodermic) model","Two-step flow model"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"In the two-step flow model, information passes first from the media to opinion leaders and then by word of mouth from those leaders to their followers. Option C assumes the media reach audiences directly with no go-between, and options A and B are hierarchy-of-effects models."}},{"itemId":"4b55d9d0-63eb-5117-8bf4-60f790cb0b71","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3cf81108-7a72-5365-a4e5-37e17e264a14","sourceKey":"bank:LAG-BUA123:PLN-010","parentItemId":null,"revision":1,"payload":{"prompt":"How does the one-step flow model of communication differ from the two-step flow model?","options":["The one-step model includes feedback while the two-step model does not","The one-step model has six stages of buyer response","In the one-step model opinion leaders are the only source of information","In the one-step model the media reach the audience directly, with no opinion leaders in between"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The one-step (or hypodermic) model assumes mass media messages go straight to the target audience and affect it directly, while the two-step model adds opinion leaders as go-betweens. Option C gets the models the wrong way round, and options A and B describe other ideas."}},{"itemId":"22dc773c-b96a-54fd-802e-359d8dc074ed","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"21402ec6-57b2-58a9-baa5-33ee3a06ca3b","sourceKey":"bank:LAG-BUA123:PLN-011","parentItemId":null,"revision":1,"payload":{"prompt":"A skincare brand sends free products to a well-known Nigerian beauty blogger, hoping her followers will copy her recommendations. Which communication model does this strategy rely on most?","options":["The one-step flow model","The innovation-adoption model","The two-step flow model","The DAGMAR model"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The brand is targeting an opinion leader who will pass the message on to her followers, which is the core idea of two-step flow. Option A would mean advertising straight to consumers, and options D and B describe response stages rather than how influence travels."}},{"itemId":"9aea7b42-9743-5351-b604-44f1471488bc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d1b215cf-9e4b-5848-afd4-3e471170fbff","sourceKey":"bank:LAG-BUA123:PLN-012","parentItemId":null,"revision":1,"payload":{"prompt":"The multi-step flow model develops the two-step model by recognising that:","options":["Messages always reach consumers in a single step","Information can flow in several directions among the media, opinion leaders and opinion followers","Only the sender can influence the receiver","Opinion leaders never use the media"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Multi-step flow accepts that information moves among media, opinion leaders, opinion formers and followers in several directions, and that followers can also get messages directly. Options D, C and A contradict the model."}},{"itemId":"8f52a7c7-0854-5080-bbc1-15e34eca209a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f62691e6-f02b-5666-a617-1c1476bfd9e4","sourceKey":"bank:LAG-BUA123:PLN-013","parentItemId":null,"revision":1,"payload":{"prompt":"Models that assume buyers pass through a set sequence of stages, from awareness to purchase, in response to marketing communication are called:","options":["Market segmentation models","Hierarchy-of-effects (response hierarchy) models","Pricing models","Distribution channel models"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Hierarchy-of-effects models, such as AIDA and Lavidge and Steiner's model, assume people move step by step from first noticing a brand to buying it. Options D, C and A cover other areas of marketing."}},{"itemId":"53371c64-3f0e-5fc8-832a-2194e29a89a5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"094567a0-09f9-538b-b4eb-16186d0b4828","sourceKey":"bank:LAG-BUA123:PLN-014","parentItemId":null,"revision":1,"payload":{"prompt":"The letters in the AIDA model stand for:","options":["Attention, Image, Demand, Advocacy","Attention, Interest, Desire, Action","Analysis, Implementation, Direction, Assessment","Awareness, Information, Decision, Adoption"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"AIDA describes the stages a buyer goes through: Attention, then Interest, then Desire, then Action. Options D, A and C swap in words from other models or planning steps."}},{"itemId":"8c803fba-27ea-565c-b72b-fcb3afaf7618","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"93ba391b-0eb6-54a1-a0c9-8912305e5f41","sourceKey":"bank:LAG-BUA123:PLN-015","parentItemId":null,"revision":1,"payload":{"prompt":"In the AIDA model, which stage comes immediately after Interest?","options":["Attention","Desire","Awareness","Action"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The sequence is Attention, Interest, Desire, Action, so Desire follows Interest. Option A comes before Interest, option D is the final stage after Desire, and option C is a stage in other models, not a letter in AIDA."}},{"itemId":"d33fdc54-1d42-5a30-8511-ceda32b2623e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fdc358f8-271f-5449-b424-601229d65a1d","sourceKey":"bank:LAG-BUA123:PLN-016","parentItemId":null,"revision":1,"payload":{"prompt":"A poster for a new Lagos gym uses bright colours and a bold headline so that passers-by stop and look at it. Which AIDA stage is the design mainly aimed at?","options":["Action","Desire","Interest","Attention"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Attention is the first AIDA stage: before anything else, the message must be noticed, which is what bold colours and headlines do. Option C comes when the viewer wants to learn more, option B when they want the product, and option A when they sign up."}},{"itemId":"a95171f6-94cd-5def-8d77-8621ff7b6747","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a72afe80-39e3-58db-8801-738abd4ca88e","sourceKey":"bank:LAG-BUA123:PLN-017","parentItemId":null,"revision":1,"payload":{"prompt":"An online store's advert ends with a \"Shop now - offer ends at midnight\" button. Which AIDA stage is this mainly aimed at?","options":["Attention","Desire","Action","Interest"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Action is the final AIDA stage, where the buyer is pushed to act, for example by clicking to buy before a deadline. Options A, D and B are earlier stages about getting noticed, holding curiosity and creating a want."}},{"itemId":"e02fdf52-a806-5438-86c0-efda4f50ebe9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c68ab3ba-8574-5de3-8143-ff3b6d170fa2","sourceKey":"bank:LAG-BUA123:PLN-018","parentItemId":null,"revision":1,"payload":{"prompt":"DAGMAR stands for:","options":["Designing Advertisements to Gain Market Access and Revenue","Direct Advertising Generates More Average Returns","Defining Advertising Goals for Measured Advertising Results","Developing Annual Goals for Marketing and Retail"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"DAGMAR means Defining Advertising Goals for Measured Advertising Results, an approach that says advertising goals should be clear and measurable. The other expansions in options A, B and D are invented."}},{"itemId":"b66671a0-a737-5115-913f-21ec94f2d46f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"34fcd4c5-7a9e-598d-8d94-054c7cf179c5","sourceKey":"bank:LAG-BUA123:PLN-019","parentItemId":null,"revision":1,"payload":{"prompt":"The DAGMAR approach to setting advertising objectives was developed by:","options":["Everett Rogers","E. St. Elmo Lewis","Lavidge and Steiner","Russell Colley"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Russell Colley proposed DAGMAR in 1961 for the Association of National Advertisers. Option C produced the six-stage hierarchy of effects, option B is linked with AIDA, and option A with the diffusion and adoption of innovations."}},{"itemId":"62af3275-a2ac-5a44-a9a7-82d6ff356d7b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"93205291-ec3d-5a17-b44c-7aafccc2c4b0","sourceKey":"bank:LAG-BUA123:PLN-020","parentItemId":null,"revision":1,"payload":{"prompt":"In the DAGMAR model, the communication stages a consumer passes through are:","options":["Attention, interest, desire, action","Awareness, knowledge, liking, preference, conviction, purchase","Awareness, comprehension, conviction, action","Awareness, interest, evaluation, trial, adoption"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"DAGMAR's communication spectrum runs from awareness to comprehension to conviction and finally action. Option A is AIDA, option B is Lavidge and Steiner's model, and option D is the innovation-adoption model."}},{"itemId":"d838e430-769c-5c8e-90fb-87fa2c7fea3b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"958749d7-2789-536a-9f89-3e260f4ef742","sourceKey":"bank:LAG-BUA123:PLN-021","parentItemId":null,"revision":1,"payload":{"prompt":"A central principle of DAGMAR is that advertising objectives should be:","options":["Specific and measurable, with a defined target audience, benchmark, degree of change and time period","Expressed only as total sales revenue","Set after the campaign has ended","Kept vague so that they can never be missed"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"DAGMAR says a good advertising objective is a specific, measurable communication task, stating the target audience, a starting benchmark, the degree of change wanted and the time period. Option D makes results impossible to measure, option B ignores that advertising's effect on sales is hard to isolate, and option C reverses the planning order."}},{"itemId":"2fa3c9e5-bc96-52b3-9902-6737ae86a770","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2bc1b6e6-4dd7-50bd-8c8e-21156e84248d","sourceKey":"bank:LAG-BUA123:PLN-022","parentItemId":null,"revision":1,"payload":{"prompt":"Lavidge and Steiner's hierarchy-of-effects model has six stages. Which sequence is correct?","options":["Awareness, knowledge, liking, preference, conviction, purchase","Attention, interest, desire, conviction, preference, action","Awareness, liking, knowledge, conviction, preference, purchase","Knowledge, awareness, preference, liking, purchase, conviction"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Lavidge and Steiner's steps are awareness, knowledge, liking, preference, conviction and purchase. Options C and D put the right words in the wrong order, and option B mixes in AIDA terms."}},{"itemId":"8668754c-18d1-5171-882b-f67ea8dffa0f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"10ddaa11-57fe-5e7f-bf0d-b5b5ee9223db","sourceKey":"bank:LAG-BUA123:PLN-023","parentItemId":null,"revision":1,"payload":{"prompt":"In Lavidge and Steiner's model, liking and preference belong to which component of attitude?","options":["Physical (sensory)","Conative (behavioural)","Affective (feeling)","Cognitive (thinking)"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Liking and preference are about feelings towards the brand, so they form the affective stage. Option D covers awareness and knowledge, option B covers conviction and purchase, and option A is not one of the three components."}},{"itemId":"11dbc640-decc-54df-ad8e-2900f6e81c8c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"52ceaf87-206f-5613-a437-352ac330a0ab","sourceKey":"bank:LAG-BUA123:PLN-024","parentItemId":null,"revision":1,"payload":{"prompt":"In hierarchy-of-effects models, the cognitive stage refers to:","options":["What the receiver knows or thinks, such as awareness and knowledge","What the receiver feels, such as liking","What the receiver does, such as buying","How much the sender spends on media"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The cognitive stage is the thinking or knowing stage, covering awareness and knowledge of the brand. Option B is the affective (feeling) stage, option C is the conative (behaviour) stage, and option D is a budget matter."}},{"itemId":"6f26fec5-5b74-503e-a597-6cdaaa6d302c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"40ae8064-786a-5485-8b50-526b8326e12b","sourceKey":"bank:LAG-BUA123:PLN-025","parentItemId":null,"revision":1,"payload":{"prompt":"The conative stage of a response hierarchy refers to:","options":["The liking stage","The awareness stage","The noise in the channel","The behaviour or action stage, such as trial and purchase"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Conative means action or behaviour, so it covers stages like conviction, trial and purchase. Option B is cognitive, option A is affective, and option C is a communication-model element."}},{"itemId":"6f64bece-ab2c-50dc-b609-1ae0847c671e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7b695378-f3c7-52cb-98a0-258a06cba8b4","sourceKey":"bank:LAG-BUA123:PLN-026","parentItemId":null,"revision":1,"payload":{"prompt":"The innovation-adoption model describes the stages a consumer goes through in accepting a new product as:","options":["Awareness, interest, evaluation, trial, adoption","Awareness, comprehension, conviction, action","Exposure, reception, cognitive response, behaviour","Attention, interest, desire, action"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The innovation-adoption model moves from awareness and interest through evaluation and trial to adoption of a new product. Option D is AIDA, option B is DAGMAR, and option C is the information-processing model."}},{"itemId":"786698c6-ac75-5a47-92d0-ce9ea508be5b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"34e4ff6a-5aa4-5e12-a570-721e73f9c2e3","sourceKey":"bank:LAG-BUA123:PLN-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a common criticism of hierarchy-of-effects models?","options":["They ignore purchase as an outcome","Consumers do not always pass through the stages in a fixed order; for example, impulse purchases may come before strong attitudes form","They can only be used for radio advertising","They pay no attention to awareness"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Critics argue the stages are not always linear: with low-involvement or impulse buys, people may purchase first and form attitudes afterwards. Options D and A are wrong because awareness and purchase are central to these models, and option C has no basis."}},{"itemId":"52deb0c2-4fd4-55ca-8464-0c21a0ada062","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3225fc9b-8876-52cc-a164-d8e1c8ab5e54","sourceKey":"bank:LAG-BUA123:PLN-029","parentItemId":null,"revision":1,"payload":{"prompt":"Why is a marketing communications plan needed?","options":["It sets out in a logical order what the firm wants to achieve with communication and how, so activities are coordinated and can be evaluated","It replaces the overall marketing plan","It removes the need to set objectives","It guarantees that every campaign will succeed"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A MarCom plan brings order and integration: it links objectives, strategy, tools, timing, budget and evaluation so that activities work together and results can be judged. Option C contradicts planning itself, option D overclaims, and option B is wrong because the MarCom plan comes from the marketing plan."}},{"itemId":"c7c46e4c-d9d1-5ae9-aaca-2cdaf8fb49aa","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d7cb4300-368c-5120-83a0-fa40d29add3b","sourceKey":"bank:LAG-BUA123:PLN-030","parentItemId":null,"revision":1,"payload":{"prompt":"The Marketing Communications Planning Framework (MCPF) is best described as:","options":["A list of all television stations in a country","A model of how opinion leaders influence followers","A sequence of linked stages that guides the development of a marketing communications plan","A financial statement showing advertising costs"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The MCPF is a framework of linked stages, from context analysis to evaluation, that helps managers build a marketing communications plan in a logical, integrated way. Option A is a media list, option D is accounting, and option B is the two-step flow model."}},{"itemId":"2faf1648-bdb1-530a-9e08-014c419225ee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0ff8c130-33d3-50e0-bce7-b2e463194c23","sourceKey":"bank:LAG-BUA123:PLN-032","parentItemId":null,"revision":1,"payload":{"prompt":"In the MCPF, which stage comes immediately after the context analysis?","options":["Control and evaluation","Setting communication objectives","Scheduling and implementation","Allocating resources"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Once the situation is understood through context analysis, the planner sets the communication objectives the plan must achieve. Option A is the last stage, and options D and C come only after strategy and the communications mix are decided."}},{"itemId":"46396794-ad05-54fb-93b2-e13e9a5a613b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"338e10cd-4432-5ada-8a44-db4fbd1104df","sourceKey":"bank:LAG-BUA123:PLN-033","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence best reflects the main stages of the Marketing Communications Planning Framework?","options":["Resources, strategy, mix, objectives, context analysis, control, schedule","Objectives, control, context analysis, resources, strategy, schedule, mix","Context analysis, objectives, strategy, coordinated mix, schedule, resources, control and evaluation","Mix, schedule, objectives, context analysis, resources, strategy, control"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The MCPF moves from understanding the situation (context analysis) to deciding goals (objectives), then the overall approach (strategy), the tools and media (coordinated mix), timing (schedule), budget and people (resources), and finally control and evaluation. Options B, D and A scramble this logic, for example setting goals before the situation is understood."}},{"itemId":"d1341530-ffa4-51b2-a464-e1a828f1951a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c5d046f1-cb33-5d3b-9fe2-fb842716145c","sourceKey":"bank:LAG-BUA123:PLN-034","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT usually examined in the context analysis stage of the MCPF?","options":["The final evaluation of the campaign's results","The customer context, such as buyers' needs and behaviour","The internal context, such as the firm's resources and culture","The business context, such as competitors and the market"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Context analysis looks at the customer, business, internal and external (wider environment) contexts before planning begins. Measuring the campaign's results, option A, belongs to the control and evaluation stage at the end."}},{"itemId":"81575735-99ef-527f-acf2-b92340235d1b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"20d2acd6-111a-52b8-a37b-450591c3bd34","sourceKey":"bank:LAG-BUA123:PLN-035","parentItemId":null,"revision":1,"payload":{"prompt":"Before planning a campaign, a Nigerian telecom firm studies new government regulations, inflation and changes in technology. These belong to which part of the MCPF context analysis?","options":["The coordinated communications mix","The control and evaluation stage","The internal context","The external (wider environment) context"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Regulation, the economy and technology are wider environmental (PEST-type) factors, so they form the external context. Option C concerns the firm's own resources and culture, option B is the end-of-plan review, and option A is the choice of tools and media."}},{"itemId":"94425d08-f564-53d4-b710-07a38b2be81a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"180b6674-9ccb-515d-b2c0-e77b7b029f97","sourceKey":"bank:LAG-BUA123:PLN-036","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication objectives in the MCPF are usually derived from:","options":["The personal preferences of the advertising agency","The colour scheme of the company logo","The corporate and marketing objectives of the organisation","Whatever competitors spent last year"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Communication objectives follow from the firm's corporate and marketing objectives, so MarCom supports the wider business goals. Options A, D and B are not a proper basis for objectives."}},{"itemId":"0acca0b0-387d-537b-a7c8-c988f9a24562","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"79e279d8-ad0b-53ef-9422-45c19e728f86","sourceKey":"bank:LAG-BUA123:PLN-037","parentItemId":null,"revision":1,"payload":{"prompt":"When setting marketing communication objectives, the SMART principle requires objectives to be:","options":["Specific, Measurable, Achievable, Realistic and Time-bound","Sales-based, Market-wide, Aggressive, Rapid and Targeted","Simple, Mass, Attractive, Repeated and Televised","Strategic, Monetary, Annual, Regional and Tactical"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"SMART objectives are Specific, Measurable, Achievable, Realistic and Time-bound, which makes it possible to judge whether the plan worked. The expansions in options C, D and B are invented."}},{"itemId":"c19988c4-d99c-5146-84b6-a93a2095f62f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0ae044cd-eb42-5edc-ac59-27b96dac7a81","sourceKey":"bank:LAG-BUA123:PLN-038","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos juice company states: \"Increase awareness of our new brand among undergraduates in Lagos from 20% to 45% within six months.\" Why is this a well-written MarCom objective?","options":["It avoids any measurable figure","It is specific, measurable and time-bound, with a clear target audience and benchmark","It sets no time limit, so it cannot fail","It mentions juice, which every objective must do"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The objective names the audience (Lagos undergraduates), a starting point and target (20% to 45%) and a deadline (six months), which makes it SMART and in line with DAGMAR. Option D is irrelevant, and options A and C describe the very things the objective avoids."}},{"itemId":"b49a663e-0282-5a6e-bd6b-d146f013661e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"52eff501-5fb7-550c-a822-45167c54d71c","sourceKey":"bank:LAG-BUA123:PLN-039","parentItemId":null,"revision":1,"payload":{"prompt":"In MarCom strategy, a pull strategy is directed mainly at:","options":["End-user consumers, to encourage them to ask for and buy the product","The firm's own production staff","Wholesalers and retailers, to encourage them to stock the product","All stakeholders, to build corporate reputation"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A pull strategy targets end users so that their demand pulls the product through the distribution channel. Option C describes a push strategy aimed at intermediaries, option D is a profile strategy, and option B is internal."}},{"itemId":"273dcaed-7f1f-511c-a15e-e0497299c3c9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e6005be6-e659-53bd-a8dc-e2a28039f884","sourceKey":"bank:LAG-BUA123:PLN-040","parentItemId":null,"revision":1,"payload":{"prompt":"A detergent maker gives extra margins and display allowances to distributors and supermarkets in Kano so they will stock and promote its brand. This is an example of a:","options":["Profile strategy","Push strategy","Two-step flow","Pull strategy"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A push strategy directs communication and incentives at channel intermediaries so that they push the product on towards consumers. Option D targets end users directly, option A builds the corporate image among all stakeholders, and option C is a communication model."}},{"itemId":"bc9d38a3-2265-5f0b-8dd3-2cad52f478ee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c8d45c26-0fa2-519b-9136-bba35ebc37ee","sourceKey":"bank:LAG-BUA123:PLN-041","parentItemId":null,"revision":1,"payload":{"prompt":"A profile strategy in marketing communications is aimed at:","options":["Only first-time buyers of a product","Only retailers who stock the product","A wide range of stakeholders, to build the organisation's corporate image and reputation","Only the firm's competitors"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A profile strategy communicates with stakeholders such as investors, employees, government and the community to build the organisation's identity and reputation, rather than to sell a particular product. Options B, A and D are too narrow or wrong."}},{"itemId":"45a05796-1fc1-5b8e-8206-4057b5dee00a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2abde261-6dd8-555b-9e47-bbecbb346680","sourceKey":"bank:LAG-BUA123:PLN-042","parentItemId":null,"revision":1,"payload":{"prompt":"The 'coordinated communications mix' stage of the MCPF involves:","options":["Choosing and combining the tools, media and messages so they work together","Studying the external environment","Deciding the firm's corporate mission","Measuring the campaign's final results"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"At this stage the planner selects and integrates the right tools (such as advertising, sales promotion and PR), the media and the content, so they deliver a consistent message. Option B is context analysis, option D is control and evaluation, and option C is corporate strategy."}},{"itemId":"25404d3f-e43a-5450-b514-511bf5961cf0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"65d3b827-e042-5ef8-8d7b-9a0981f6ea4c","sourceKey":"bank:LAG-BUA123:PLN-043","parentItemId":null,"revision":1,"payload":{"prompt":"In the MCPF, the scheduling (implementation) stage is concerned with:","options":["When each communication activity will happen and in what order","How the competitors set their prices","Which consumers liked the last campaign","Why the firm exists"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Scheduling sets out the timing and order of activities so that, for example, PR and adverts build awareness before sales promotions push purchase. Options D, B and C belong to corporate mission, competitor analysis and evaluation."}},{"itemId":"cce503ba-2b5a-5b51-892d-ba91d157c57e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5d4b15c4-2cde-5f67-8927-7c7240c1803e","sourceKey":"bank:LAG-BUA123:PLN-044","parentItemId":null,"revision":1,"payload":{"prompt":"The 'resources' stage of the MCPF mainly deals with:","options":["The market share of competitors","The budget, people and time needed to carry out the plan","The design of the company logo","The firm's raw materials for production"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Resources covers the money (the communication budget), staff and agency support, and time needed to put the plan into action. Options D, A and C are production, competitor and design matters."}},{"itemId":"4095df9f-d6c5-5f8d-8f28-ecd8dbd86387","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"14a06725-ecf3-5e50-9461-fc0123a0b3b6","sourceKey":"bank:LAG-BUA123:PLN-045","parentItemId":null,"revision":1,"payload":{"prompt":"Six weeks after a campaign launch, a Port Harcourt restaurant checks whether awareness rose to the target and adjusts its adverts where it fell short. Which MCPF stage is this?","options":["Control and evaluation","Scheduling","Setting objectives","Context analysis"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Control and evaluation compares actual results with the objectives and makes corrections, and the feedback goes into future planning. Option D happens before planning, option C sets the targets in the first place, and option B is about timing."}},{"itemId":"be75c6bd-a8fb-5600-82bc-1c0dbbf79d71","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f66d2c55-21fc-59c2-92c2-1a161762da9a","sourceKey":"bank:LAG-BUA123:PLN-046","parentItemId":null,"revision":1,"payload":{"prompt":"What is the role of feedback in the Marketing Communications Planning Framework?","options":["It ends the plan so that no further changes are made","It is used only to calculate the budget","Results from evaluation feed back into earlier stages so that future plans improve","It replaces the context analysis"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Feedback loops the lessons from evaluation back into context analysis and objective-setting, so planning is a continuous cycle rather than a one-off. Option A is the opposite of this, option B is too narrow, and option D is wrong because feedback adds to the analysis rather than replacing it."}},{"itemId":"e7d12f2c-0c33-5e69-b15f-1b35d0e0822b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e769d639-d2ae-58a7-93e1-14e17daa4c72","sourceKey":"bank:LAG-BUA123:PLN-047","parentItemId":null,"revision":1,"payload":{"prompt":"Context analysis is considered the foundation of a MarCom plan because:","options":["It decides the price of the product","It provides the information on which objectives, strategy and the mix are based","It is the only stage that costs money","It is carried out after the campaign is finished"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Every later decision, such as which objectives to set, which strategy to use and which tools to choose, depends on understanding the situation, which is what context analysis supplies. Option C is false, option D describes evaluation, and option A is a pricing decision."}},{"itemId":"295da762-238f-59db-aa40-3229af6fb297","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b9cb6f3e-1a5e-5051-a662-71ed8a3d6346","sourceKey":"bank:LAG-BUA123:PLN-048","parentItemId":null,"revision":1,"payload":{"prompt":"SOSTAC, a widely used marketing planning model, stands for:","options":["Situation, Objectives, Strategy, Tactics, Action, Control","Sales, Orders, Stock, Turnover, Accounts, Costs","Source, Objective, Signal, Target, Audience, Channel","Segment, Offer, Sell, Track, Adjust, Close"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"SOSTAC moves from situation analysis to objectives, strategy, tactics, action and control, the same logic used in MarCom planning. Options B, C and D are invented expansions."}},{"itemId":"876d3b61-f90e-550d-b193-0a07d9b0093b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f7842eef-a962-5a98-8d4b-097d584835bb","sourceKey":"bank:LAG-BUA123:PLN-049","parentItemId":null,"revision":1,"payload":{"prompt":"A planner states the overall approach for a new campaign: \"Position our bank as the friendliest choice for students, using a pull strategy built mainly on social media.\" This statement belongs to which MCPF stage?","options":["Marketing communications strategy","Context analysis","Resources","Control and evaluation"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Strategy sets the overall direction of the plan, such as positioning and whether to use pull, push or profile approaches. Option B is research into the situation, option D is checking results, and option C is the budget and staff needed."}},{"itemId":"d1528d35-25f0-5418-8ba0-64bb6da41181","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"928871fe-bdb1-5e83-a680-baf4af89b934","sourceKey":"bank:LAG-BUA123:PLN-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a stage of the Marketing Communications Planning Framework?","options":["Control and evaluation","Recruitment of factory workers","Context analysis","Communication objectives"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The MCPF stages are context analysis, objectives, strategy, the coordinated communications mix, scheduling, resources, and control and evaluation. Recruiting factory workers, option B, is a human resources task outside MarCom planning."}},{"itemId":"50923867-f356-527e-bbaf-fb5069c9e271","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"df57e02b-b03f-5be5-9289-06ec7bfea414","sourceKey":"bank:LAG-BUA123:PQ-001","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication can be most comprehensively defined as:","options":["A one-way process by which a firm announces its prices to buyers","The physical movement of goods from producers to final consumers","The set of activities used to design and manufacture new products","A strategic process of creating, delivering and exchanging value-laden messages to shape customer perceptions and behaviours"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication is about the messages a firm creates and shares with its audiences so that they understand it, think well of it and act, for example by buying. Option A is too narrow because it is one-way and only about price, while B describes distribution and C describes product development, which are other parts of marketing."}},{"itemId":"f2a319b6-dfba-5146-ad5a-9b43a5537b37","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f3d9185e-4799-51db-8862-caf329c75031","sourceKey":"bank:LAG-BUA123:PQ-002","parentItemId":null,"revision":1,"payload":{"prompt":"Which invention marked the birth of print advertising by revolutionising the way information was shared?","options":["The radio, which began carrying commercials in the 1920s","The printing press, invented by Johannes Gutenberg in the 15th century","Television, which became the dominant platform by the 1950s","The Internet, which arrived in the late 20th century"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Before Gutenberg's printing press, information lived in handwritten manuscripts that only the elite could access; printing made mass print advertising possible, and printed adverts soon appeared in 17th-century newspapers. Options A, C and D were important later stages in the history of marketing communication, but they came centuries after print advertising began."}},{"itemId":"fe2ed240-370d-570d-83da-615d8fdef8d9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bdb9693f-406f-50f4-a2ef-af8af1cbcbdc","sourceKey":"bank:LAG-BUA123:PQ-002-b","parentItemId":null,"revision":1,"payload":{"prompt":"Hotmail's 1996 strategy of adding the line \"Get your free email at Hotmail\" to every email its users sent is an early example of:","options":["Personal selling, where a salesperson meets each prospect face-to-face","Sales promotion, where buyers receive coupons and rebates","Viral digital marketing, where users spread the message as they use the product","Publicity, where a news editor writes a story about the firm"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Every email a user sent carried the advert to new people, so the message spread itself from person to person, which is what makes it viral; it helped Hotmail gain millions of users within months. Option A needs face-to-face contact, B relies on incentives such as coupons, and D depends on coverage in the editorial section of the news media, none of which happened here."}},{"itemId":"3805b854-db6b-5e37-bec6-85976505f100","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ebe5f1e0-0f37-5b3e-a48e-7fcba0eca334","sourceKey":"bank:LAG-BUA123:PQ-003","parentItemId":null,"revision":1,"payload":{"prompt":"How does marketing communication facilitate the exchange process in a competitive market?","options":["By physically delivering the product to the buyer's location","By generating awareness, fostering trust and driving purchase intent among target audiences","By removing the buyer's freedom to accept or reject the offer","By removing the need for the two parties to trust each other"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"An exchange can only happen when each party knows what the other offers and trusts it enough to take the deal seriously, and marketing communication creates that awareness and trust. Option A describes distribution, not communication. Options C and D are wrong because freedom to accept or reject and mutual trust are conditions that an exchange needs."}},{"itemId":"95aa8eb6-8b76-521d-b1e0-d013214f5799","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"faf706f4-276b-50c0-9523-1fe71186cd00","sourceKey":"bank:LAG-BUA123:PQ-003-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the conditions for an exchange to take place?","options":["There must be at least two parties","Each party must have something that might be of value to the other","Each party must be legally bound to accept whatever is offered","Each party must be able to communicate and deliver what it is offering"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"For an exchange to take place, each party must be free to accept or reject what is on offer, so being forced to accept is the opposite of a real condition. Options A, B and D are genuine conditions, along with the requirement that each party trusts the other enough to take the exchange seriously."}},{"itemId":"71163739-7ecc-57fe-8298-11e850c0b75a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dfe6d87f-dde5-545f-a6a2-fc835d327fee","sourceKey":"bank:LAG-BUA123:PQ-004","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following best exemplifies a core component of marketing communication?","options":["Product prototyping and design iteration","Setting production quotas for the factory","Integrated advertising campaigns across multiple channels","Warehousing and inventory control"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Advertising is one of the main tools of marketing communication, and running it across several channels with one consistent message is what integrated marketing communication means. Option A belongs to product development, while B and D are production and logistics activities rather than ways of communicating with customers."}},{"itemId":"8631d84f-9865-5b6f-9383-c1e62f216198","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ce0589d3-4752-54fd-aae9-e19865fa815b","sourceKey":"bank:LAG-BUA123:PQ-005","parentItemId":null,"revision":1,"payload":{"prompt":"The primary function of marketing communication in a business is to:","options":["Determine the production cost of each product","Set the prices charged to wholesalers and retailers","Inform, persuade and remind customers so as to sustain their engagement with the brand","Manage the recruitment and payment of factory workers"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication exists to tell customers about a firm and its offers, persuade them to buy and remind them so the brand stays in their minds. Option A is a cost accounting task, B is a pricing decision and D is a human resources task, so none of them is the main job of marketing communication."}},{"itemId":"d4c2c830-b432-5cd1-852f-d39061aa31e4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"520c3280-e8f9-59a5-a7ba-85f3c45fab3b","sourceKey":"bank:LAG-BUA123:PQ-006","parentItemId":null,"revision":1,"payload":{"prompt":"A strategic objective of marketing communication is to:","options":["Reduce the number of products in the firm's range","Lower the cost of the firm's raw materials","Influence consumer purchasing patterns through targeted messaging","Decide where the firm's factories should be located"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication objectives such as raising awareness, changing attitudes and influencing purchase intent all aim to shape what consumers buy. Option A is a product range decision, B is a purchasing and cost matter, and D is a production location decision."}},{"itemId":"ac6e344c-bb40-5bbf-ad80-8bb70a65b0ce","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"07717205-d2af-5b56-bf17-1ebf92b84503","sourceKey":"bank:LAG-BUA123:PQ-006-b","parentItemId":null,"revision":1,"payload":{"prompt":"A campaign that aims to get customers who currently buy competing products to start buying your brand is pursuing which marketing communication objective?","options":["Driving brand switching","Increasing brand awareness","Changing attitudes","Conducting research for the company"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Brand switching means moving customers away from a rival brand to yours, which is exactly what this campaign is trying to achieve. Option B is about making people know the business exists, C is about correcting mistaken beliefs about a brand, and D is about reading market trends, so none of them describes winning over a competitor's buyers."}},{"itemId":"2f12a5f0-cf3b-51d8-a093-4e4ee1cf0aea","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f926c976-30bf-5ef7-8e44-5aa5ea2ac172","sourceKey":"bank:LAG-BUA123:PQ-007","parentItemId":null,"revision":1,"payload":{"prompt":"Which combination of elements is most representative of marketing communication?","options":["Advertising, sales promotion and direct marketing","Product, price and place","Production, warehousing and transport","Segmentation, targeting and positioning"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Advertising, sales promotion and direct marketing are all tools of the marketing communication (promotion) mix, used to send messages to target audiences. Option B lists the other elements of the marketing mix apart from promotion, C lists operations and logistics activities, and D describes how a market is divided and targeted, not how a firm communicates."}},{"itemId":"8fd74beb-6ab0-58c6-84f7-568f8e787df5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0b69d59c-901a-5375-b6d4-d575217cecb5","sourceKey":"bank:LAG-BUA123:PQ-008","parentItemId":null,"revision":1,"payload":{"prompt":"In the context of marketing communications, the exchange process is best characterised as:","options":["A one-way transfer of goods from the seller to the buyer","A reciprocal creation of value that benefits both the organisation and its customers","A transaction in which only the seller gains value","A process in which the buyer cannot reject the offer"],"correctOption":1,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Exchange means obtaining something you want from someone by offering something of value in return, so both sides gain. Options A and C leave out the value flowing back to the other party, and D is wrong because each party must be free to accept or reject the offer."}},{"itemId":"7c7379ec-a67f-5651-90c9-9375b5ecdda5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9fcfacb1-8ba9-50bb-98e3-2fc9aa89a1e8","sourceKey":"bank:LAG-BUA123:PQ-009","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication strategically benefits businesses by:","options":["Guaranteeing that competitors leave the market","Removing the need for any market research","Directly lowering the firm's production costs","Enhancing brand equity, fostering loyalty and driving repeat purchases"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Good marketing communication builds the brand's value, keeps customers attached to it and encourages them to buy again. Option A overstates what communication can do, B is wrong because communication actually depends on understanding the market, and C is a production matter rather than a communication benefit."}},{"itemId":"13f3495c-dd7c-5f06-8d68-108b58d4fe4a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f5a66321-af4c-5166-a9dc-1358214e812c","sourceKey":"bank:LAG-BUA123:PQ-010","parentItemId":null,"revision":1,"payload":{"prompt":"The rise of social media platforms such as MySpace, Facebook and Twitter in the early 2000s changed marketing mainly by:","options":["Turning it into a two-way conversation in which brands engage directly with customers","Ending the use of print and broadcast advertising","Making marketing a one-way broadcast from the firm to its audience","Removing the need for brands to listen to customers"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Social media lets customers reply, comment and share, so brands now talk with their audiences instead of only talking to them. Option B is false because print and broadcast media are still used, while C and D describe the opposite of the two-way engagement that social media created."}},{"itemId":"43a7e1c2-ab06-5b7f-af5a-8b43a9cc7cde","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"17f80ff8-af10-5eb5-a653-5ce041b165f7","sourceKey":"bank:LAG-BUA123:PQ-011","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a role of marketing communications?","options":["Determining the product's physical features","Choosing the locations of the firm's warehouses","Calculating the cost of producing each unit","Shortening the sales cycle"],"correctOption":3,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"By understanding customers' needs, motivations and buying processes and using that insight when engaging them, marketing communications helps customers move to a purchase more quickly. Option A is a product design decision, B is a distribution decision and C is a costing task, so none of them is a communication role."}},{"itemId":"c27800c1-46c1-576d-b6fe-eca8ec115fd7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e3394378-5fdb-5b17-9b0f-971a126d64e5","sourceKey":"bank:LAG-BUA123:PQ-011-b","parentItemId":null,"revision":1,"payload":{"prompt":"Making sure that the things that make a firm's products unique are shared with the public, so as to strengthen its competitive advantage, describes which role of marketing communications?","options":["Maintaining customer loyalty","Shortening the sales cycle","Highlighting a competitive edge","Building brand awareness"],"correctOption":2,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"In a crowded marketplace, a firm must tell people about its points of differentiation, and doing this is the role called highlighting a competitive edge. Option A is about keeping a positive bond with existing customers, B is about speeding customers to purchase, and D is about making sure people know the business exists, which is broader than showing what makes it different."}},{"itemId":"d3eadb58-f593-5953-aea4-a93dbf9a096f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"25e0e763-37fe-5b88-bf91-f31a7c25a81c","sourceKey":"bank:LAG-BUA123:PQ-012","parentItemId":null,"revision":1,"payload":{"prompt":"The ultimate aim of marketing communication is to influence:","options":["Consumer decision-making and buying behaviour","The firm's factory production schedules","The firm's choice of raw material suppliers","The government's tax policy"],"correctOption":0,"section":"Nature, Types, Roles and Objectives of Marketing Communication","explanation":"Marketing communication is aimed at audiences outside the firm, mainly consumers, to shape how they think, decide and buy. Options B and C are internal operational decisions, and D is set by government rather than being the target of a firm's marketing messages."}},{"itemId":"98bb995b-ba13-50f4-be82-505f1c068a17","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fb196376-7bba-560e-8841-640a0d7b98f5","sourceKey":"bank:LAG-BUA123:PQ-013","parentItemId":null,"revision":1,"payload":{"prompt":"A basic model of the marketing communication process typically includes:","options":["Product, price, place and promotion","Sender, encoded message, medium, receiver and feedback","Segmentation, targeting and positioning","Strengths, weaknesses, opportunities and threats"],"correctOption":1,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A communication model shows how a sender encodes a message, sends it through a medium to a receiver who decodes it, and then gets feedback. Option A is the marketing mix, C is the process for choosing target markets, and D is a SWOT analysis used in planning, so none of them describes how a message travels."}},{"itemId":"f2791b55-25a8-50cd-bd4f-84f1952159b5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5226efd6-29bb-56b3-8b07-417a69c870dd","sourceKey":"bank:LAG-BUA123:PQ-014","parentItemId":null,"revision":1,"payload":{"prompt":"The Marketing Communications Planning Framework (MCPF) is designed to:","options":["Provide a structured approach for aligning communication strategies with business objectives","Calculate the unit cost of producing each product","Replace the need to set communication objectives","Decide the physical design of the product"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The MCPF gives planners an orderly sequence, from analysing the context and setting objectives to implementing and evaluating, so that communication supports the firm's goals. Option C is wrong because objective setting is part of the framework itself, while B and D are costing and product design tasks."}},{"itemId":"dba71d21-3062-5fd6-82cb-5b8a5116429e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"36e5cf61-b955-5630-8a87-f58ef3c474e2","sourceKey":"bank:LAG-BUA123:PQ-015","parentItemId":null,"revision":1,"payload":{"prompt":"The development of an effective marketing communications plan requires:","options":["Setting measurable goals, selecting appropriate tools and evaluating outcomes","Choosing media first and setting objectives only after the campaign ends","Copying a competitor's plan without analysing the target audience","Spending the budget equally on every available promotional tool"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A good plan starts with clear, measurable objectives, picks the tools that suit the audience and those objectives, and checks results afterwards. Option B reverses the logical order, C skips the audience analysis that the plan depends on, and D ignores the fact that tools should be chosen according to objectives and audience."}},{"itemId":"f82f7f14-4a4c-518e-929e-ff9594ea8861","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1dca5873-a441-54cf-8af7-e65fcbe72bf0","sourceKey":"bank:LAG-BUA123:PQ-016","parentItemId":null,"revision":1,"payload":{"prompt":"In the process of marketing communications, the first stage is to:","options":["Determine the company's unique value proposition","Select the channels to deliver the brand message","Allocate the budget to each channel","Identify the target audience"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Presenting an offer to everyone does not work, so the process begins by deciding exactly who the messages are for. Options A, B and C are real stages, but they come later, because the value proposition, channels and budget all depend on knowing the audience first."}},{"itemId":"3c31a05d-46cf-56af-beb0-d6542c35f258","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"10e44274-245f-5e62-8f9e-5536154a919c","sourceKey":"bank:LAG-BUA123:PQ-016-b","parentItemId":null,"revision":1,"payload":{"prompt":"Domino's Pizza positioning itself as the business that delivers the newest and hottest pizza faster than competitors, in only 30 minutes, is an example of a firm's:","options":["Unique value (selling) proposition","Target audience","Budget allocation","Control measure"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A unique value or selling proposition is what makes a business stand out and outperform rivals, and the 30-minute hot pizza promise is exactly that. Option B is the group of people the firm is talking to, C is how much is spent on each channel, and D is how results are checked against objectives."}},{"itemId":"83827a4b-1f00-5391-9025-c2b0feacd376","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1137beca-6891-586d-b6ad-efef629ae4ad","sourceKey":"bank:LAG-BUA123:PQ-017","parentItemId":null,"revision":1,"payload":{"prompt":"A sound marketing communication model underscores the significance of:","options":["Feedback as a way of refining the effectiveness of messages","One-way transmission with no response from the receiver","Choosing the medium only after the message has been received","Ignoring how the receiver interprets the message"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Feedback is the receiver's response, and it tells the sender whether the message was understood and acted on, so the next message can be improved. Option B describes a model with no feedback at all, C gets the order of the process wrong, and D ignores decoding, which is central to whether communication works."}},{"itemId":"6b8eabb3-c190-5d59-9100-6cbc8ad9b206","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"951c6403-8a6e-5daf-af44-20630be4bdac","sourceKey":"bank:LAG-BUA123:PQ-018","parentItemId":null,"revision":1,"payload":{"prompt":"In the Marketing Communications Planning Framework (MCPF), which element comes first?","options":["Context analysis","Evaluation and control","Scheduling and implementation","Allocation of resources (budget)"],"correctOption":0,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Planning starts by analysing the context, that is the customers, the business, the organisation and the wider environment, because every later decision depends on that understanding. Option B is the final stage, and C and D come after objectives and strategy have been set."}},{"itemId":"8868878b-307a-54b4-bc85-09e54946232f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a992f146-16e2-542d-bda3-0e9627daee2f","sourceKey":"bank:LAG-BUA123:PQ-019","parentItemId":null,"revision":1,"payload":{"prompt":"A well-executed marketing communications plan ensures:","options":["That each promotional tool sends a different, unrelated message","That only one promotional tool is ever used","Integration and consistency across all communication touchpoints","That evaluation becomes unnecessary once the campaign is launched"],"correctOption":2,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Planning brings the different tools together so that customers get one clear, consistent message wherever they meet the brand. Option A is the opposite of integration, B is wrong because plans usually combine several tools, and D is wrong because evaluation and control are part of every plan."}},{"itemId":"35d2a76d-4f58-5016-846f-4d9f4f0e90bb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3e030c10-fc73-51e7-8272-9036a1cb5ea8","sourceKey":"bank:LAG-BUA123:PQ-020","parentItemId":null,"revision":1,"payload":{"prompt":"The usefulness of a marketing communication model lies in its ability to:","options":["Set the selling price of the product","Forecast the firm's production output","Replace the need for audience research","Explain how persuasive messages are transmitted and received"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"A communication model maps the journey of a message from sender to receiver and back through feedback, which helps marketers see where communication can succeed or break down. Option A is a pricing decision, B is a production planning task, and C is wrong because the model actually highlights how much the receiver matters."}},{"itemId":"6322de57-24a6-5cc0-970c-8eacaa201c72","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1cfb349c-78ec-56bb-acef-62d5a6d006e1","sourceKey":"bank:LAG-BUA123:PQ-021","parentItemId":null,"revision":1,"payload":{"prompt":"In the Marketing Communications Planning Framework (MCPF), which element comes last?","options":["Context analysis","Setting communication objectives","Formulating the marketing communications strategy","Evaluation and control"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"After a plan has been implemented, the results are measured against the objectives and adjustments are made, which is why evaluation and control close the framework. Option A is the starting point, and B and C are early planning steps that come before resources, scheduling and implementation."}},{"itemId":"f53d1bcc-c935-5e15-986f-b598caa41c48","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"01f876d6-4bbc-5c15-abf2-0e2268d7e958","sourceKey":"bank:LAG-BUA123:PQ-022","parentItemId":null,"revision":1,"payload":{"prompt":"A foundational element of a marketing communications plan is:","options":["Choosing the cheapest medium regardless of the audience","Leaving objectives undefined to allow flexibility","Repeating the previous year's plan unchanged","Formulating precise, actionable and time-bound objectives"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"Clear, measurable and time-bound objectives guide every other choice in the plan and make it possible to evaluate results. Option B removes that foundation, A ignores the audience, and C ignores changes in the market and in the firm's goals."}},{"itemId":"dc9bcb7a-a871-5a38-98be-eb1b8fe3fb03","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d02c449a-41b7-52f4-b757-5d67a9faed78","sourceKey":"bank:LAG-BUA123:PQ-023","parentItemId":null,"revision":1,"payload":{"prompt":"Which sequence correctly shows the basic communication process?","options":["Receiver - encoding - medium - decoding - sender - feedback","Sender - decoding - medium - encoding - receiver - feedback","Sender - feedback - medium - encoding - receiver - decoding","Sender - encoding - medium - decoding - receiver - feedback"],"correctOption":3,"section":"Models of Marketing Communication and MarCom Planning","explanation":"The sender first encodes the idea into a message, sends it through a medium, the receiver decodes it, and the receiver's response travels back as feedback. Option B swaps encoding and decoding, A puts the receiver at the start, and C places feedback before the message has even been received."}},{"itemId":"730eb3e1-eddc-5214-83a5-ba2989c6a291","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7f1b5280-79b7-576c-886a-33e9956561d6","sourceKey":"bank:LAG-BUA123:PQ-025","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing communications mix is best described as encompassing:","options":["A blend of advertising, sales promotion, public relations and personal selling","Product, price, place and promotion","Segmentation, targeting and positioning","Source, message, medium and receiver"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The marketing communications mix is the set of promotional tools, traditionally advertising, sales promotion, personal selling, public relations and direct marketing, used in combination to reach a target audience. Option B is the wider marketing mix, of which promotion is only one part. Option C is about choosing markets and D lists the parts of the communication process."}},{"itemId":"606a49b6-ce9e-5811-a539-9ebacecc901f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1076159e-8c1c-5040-b000-dcdf8e4bb9de","sourceKey":"bank:LAG-BUA123:PQ-026","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing communication context refers to:","options":["Only the words and pictures used in an advertisement","Only the size of the firm's advertising budget","The circumstances, inside and outside the organisation, in which communication takes place and is interpreted","Only the price at which the product is sold"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Context covers the setting that shapes how messages are planned and understood, such as customers, competitors, the wider environment and the organisation itself. Options A, B and D each pick out a single item, the message, the budget or the price, and treat it as if it were the whole context."}},{"itemId":"48682013-fa74-5faf-ac68-f5c73ab7f27d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"90db1166-7fc0-5d7b-b3aa-3316529fb427","sourceKey":"bank:LAG-BUA123:PQ-027","parentItemId":null,"revision":1,"payload":{"prompt":"Factors that influence the choice of marketing communication mix are grouped into product, customer, organisation, and competition and situation related factors. Under which group does the communication budget fall?","options":["Product related factors","Organisation related factors","Customer related factors","Competition and situation related factors"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The budget is a resource controlled by the firm itself, so it sits with the marketing channel adopted and branding strategy under organisation related factors. Option A covers things like product complexity, life cycle stage and unit price, C covers target market characteristics and the type of buying decision, and D covers the firm's visibility, environment and competition."}},{"itemId":"9bc3e9c7-49fd-5d76-b355-b1bee5ac6855","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"37f17d59-dfca-5357-a8eb-b6c7deba6cdb","sourceKey":"bank:LAG-BUA123:PQ-027-b","parentItemId":null,"revision":1,"payload":{"prompt":"When choosing the marketing communication mix, the stage of the product in its life cycle is classified as a:","options":["Customer related factor","Organisation related factor","Product related factor","Competition and situation related factor"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Product related factors include the amount and complexity of product information, the product's life cycle stage, and the product type and unit price. Option A deals with the target market and type of buying decision, B with channels, branding and budget, and D with the firm's visibility, environment and competitors."}},{"itemId":"914bbfa5-1d27-5d05-8e92-25800f29177f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f3aab7de-a3b7-5309-af0e-46dd326ffab7","sourceKey":"bank:LAG-BUA123:PQ-028","parentItemId":null,"revision":1,"payload":{"prompt":"Within the marketing communications mix, advertising primarily serves to:","options":["Offer short-term incentives such as coupons to trigger immediate sales","Win unpaid coverage in the editorial section of the news media","Build brand recognition and reinforce market presence through paid media","Build personal relationships through face-to-face selling"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Advertising is a paid, indirect way of reaching many people through TV, radio, print and websites, which makes it well suited to building recognition and keeping a brand visible. Option A describes sales promotion, B describes publicity, and D describes personal selling."}},{"itemId":"765f057c-9c6e-5c6c-b63c-5dc4d325b7a0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ddf422da-ac95-59c6-93db-c09b39d027a1","sourceKey":"bank:LAG-BUA123:PQ-028-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which marketing communication tool is an indirect, paid method of informing customers about goods and services through television, radio, print and websites?","options":["Publicity","Personal selling","Word-of-mouth marketing","Advertising"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Advertising is paid for by the firm and delivered through mass media rather than in person, which is why it is called indirect. Option A is free coverage in the news media, B is direct contact between a salesperson and a customer, and C happens when customers share their own experiences with friends and peers."}},{"itemId":"e7f4d649-7dbc-55c3-9cc6-726904b8420b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0b34b456-ad37-5128-b96c-2325e33462e3","sourceKey":"bank:LAG-BUA123:PQ-029","parentItemId":null,"revision":1,"payload":{"prompt":"The role of sales promotion in the marketing communications mix is to:","options":["Win free editorial coverage in the news media","Trigger immediate purchase through incentives and short-term offers","Build the firm's long-term reputation with all stakeholders","Communicate with each customer face-to-face"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Sales promotion uses incentives such as discounts, coupons, rebates and buy-one-get-one-free offers to give people a reason to buy now. Option A describes publicity, C describes public relations, and D describes personal selling."}},{"itemId":"b424a255-546f-5b8c-b46c-c920b1739719","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9a5a0e8e-828d-5355-9916-3e4a30be92f4","sourceKey":"bank:LAG-BUA123:PQ-029-b","parentItemId":null,"revision":1,"payload":{"prompt":"Coupons, rebates and buy-one-get-one-free offers are examples of:","options":["Publicity","Sales promotion","Public relations","Direct marketing"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Each of these gives the buyer an extra incentive to purchase in the short term, which is what sales promotion is about. Option A is unpaid news coverage, C is about managing the firm's reputation, and D is personalised communication such as emails, brochures and telemarketing sent directly to individuals."}},{"itemId":"6f784f4f-2f1b-5abc-8f6b-625a806f46a6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"67432533-19bb-5514-b2d4-6b84f54ae830","sourceKey":"bank:LAG-BUA123:PQ-030","parentItemId":null,"revision":1,"payload":{"prompt":"Public relations within the marketing communications mix is mainly used to:","options":["Offer short-term price discounts to boost sales","Enhance the firm's reputation and credibility through earned media","Buy time and space on television and radio","Persuade individual customers in one-to-one sales meetings"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Public relations focuses on reputation, using unpaid or earned communication such as press releases, campaigns and crisis management to build good relationships with the media and other stakeholders. Option A is sales promotion, C is advertising, and D is personal selling."}},{"itemId":"b0d3cefb-3cb1-5a4a-b891-2fa774d1ad49","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"faed7340-1b0e-582e-929d-ab120a760e91","sourceKey":"bank:LAG-BUA123:PQ-030-b","parentItemId":null,"revision":1,"payload":{"prompt":"Publicity differs from advertising mainly because publicity:","options":["Is not paid for and appears as news in the editorial section of the media","Is always delivered face-to-face by a salesperson","Relies on coupons, rebates and discounts","Is aimed only at the firm's own employees"],"correctOption":0,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Publicity promotes to the mass market like advertising does, but it is free and depends on the media finding the story newsworthy, for example through press releases, photos and feature stories. Option B describes personal selling, C describes sales promotion, and D is wrong because publicity reaches the general public."}},{"itemId":"9d95f2ac-12d4-55ce-99db-acf88eb78fee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"658eaf0d-a477-5eed-a8ac-ef48bd0f4c38","sourceKey":"bank:LAG-BUA123:PQ-031","parentItemId":null,"revision":1,"payload":{"prompt":"Personal selling in the marketing communications mix is characterised by:","options":["Mass media campaigns aimed at very large audiences","Coupons and rebates that encourage quick purchase","Unpaid coverage of the firm in the news media","Tailored, face-to-face interaction that addresses each customer's needs"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"In personal selling a salesperson approaches prospects directly and uses skills to build personal relationships, adapting the message to each person. Option A describes advertising, B describes sales promotion, and C describes publicity."}},{"itemId":"f28306a0-5ff2-533f-aef1-d01484892519","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d2f75909-bbdc-5c56-ab07-f21b941171bc","sourceKey":"bank:LAG-BUA123:PQ-032","parentItemId":null,"revision":1,"payload":{"prompt":"An external factor within the marketing communication context is:","options":["The company's internal policies and procedures","Competitive positioning and market trends","The organisation's culture and values","The firm's own staff performance appraisals"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Competitors and market trends exist outside the firm, so they belong to the external context that communication plans must respond to. Options A, C and D all come from inside the organisation, so they are internal factors."}},{"itemId":"c6159d4c-fd0f-56b7-bb79-59776db0435a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"748e564f-040c-5c76-9aea-14b5f059273b","sourceKey":"bank:LAG-BUA123:PQ-033","parentItemId":null,"revision":1,"payload":{"prompt":"Selection criteria for the marketing communications mix are used to:","options":["Ensure every promotional tool receives an equal share of the budget","Choose tools based only on what competitors are using","Remove the need to set communication objectives","Identify and prioritise the tools that will be most effective for the audience and objectives"],"correctOption":3,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Factors such as the product, the customer, the organisation and the competitive situation help a firm decide which tools to use and how heavily to use each one. Option A ignores these differences, B wrongly treats competition as the only factor, and C is wrong because tools are chosen to meet objectives."}},{"itemId":"4ea55b7e-27d7-5d69-bc96-a17e7d18a2e6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d25501d4-4d7f-5ca4-b36b-2480fb831274","sourceKey":"bank:LAG-BUA123:PQ-034","parentItemId":null,"revision":1,"payload":{"prompt":"The marketing communications mix is designed to:","options":["Set the firm's production targets","Reach and persuade the intended audience effectively across channels","Decide where the firm's factories are located","Determine the wages paid to the sales force"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The mix combines tools such as advertising, sales promotion, public relations, personal selling and direct marketing in different degrees so that the target audience receives and acts on the firm's messages. Options A and C are production decisions and D is a human resources decision."}},{"itemId":"be429878-6f71-52a4-8621-98e26f903746","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"509c5ded-38c9-5c4a-8abb-3850d0e74cf3","sourceKey":"bank:LAG-BUA123:PQ-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an element of the marketing communications mix?","options":["Product design as a competitive differentiator","Public relations as a tool for reputation management","Pricing strategy as a way of signalling value","Inventory management as a way of controlling costs"],"correctOption":1,"section":"MarCom Context, Mix and Selection Criteria","explanation":"Public relations is one of the traditional tools of the marketing communications mix, alongside advertising, sales promotion, personal selling and direct marketing. Options A and C belong to the wider marketing mix (product and price), and D is an operations activity."}},{"itemId":"7fd55c63-3b88-56b0-a665-2caad9d8072f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6dd8725a-209c-5309-b704-3c188b5dab53","sourceKey":"bank:LAG-BUA123:PQ-036-b","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the five traditional tools of the marketing communications mix?","options":["Direct marketing","Personal selling","Pricing","Public relations"],"correctOption":2,"section":"MarCom Context, Mix and Selection Criteria","explanation":"The five traditional tools are advertising, sales promotion, personal selling, public relations and direct marketing. Pricing is part of the wider marketing mix, not the communications mix, while options A, B and D are all communication tools."}},{"itemId":"9abd87c8-570c-5cee-b791-48609058faa5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e45235ed-cd68-594d-8ed6-8fff12f44b67","sourceKey":"bank:LAG-BUA123:PQ-037","parentItemId":null,"revision":1,"payload":{"prompt":"In marketing communication, the source is best identified as:","options":["The originator of the message, such as a brand or spokesperson","The channel through which the message is spread","The audience that interprets the message","The feedback that shows how effective the message was"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"This is where the message starts, for example the company, the brand or a person who speaks for it, and how credible it is affects how the message is received. Option B is the medium, C is the receiver and D is feedback."}},{"itemId":"c2f20776-266e-56b4-a150-fbb995f62dd2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e32691ed-423c-5f73-bb48-7e7a50d42dad","sourceKey":"bank:LAG-BUA123:PQ-038","parentItemId":null,"revision":1,"payload":{"prompt":"The message in marketing communication refers to:","options":["The crafted content intended to inform, persuade or evoke a response","The platform that carries the communication","The target audience receiving the communication","The audience's response after receiving the communication"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The message is what is actually said or shown, the words, images and ideas the sender puts together for the audience. Option B is the medium, C is the receiver and D is feedback."}},{"itemId":"33ba98d1-01ef-5092-86c9-6fb97526ef4a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4544c974-eb18-57a1-ba7e-2c58dcbf016f","sourceKey":"bank:LAG-BUA123:PQ-039","parentItemId":null,"revision":1,"payload":{"prompt":"The receiver in marketing communication is defined as:","options":["The person or organisation that creates and sends the message","The intended audience that decodes and responds to the message","The medium that transmits the message","The content of the message itself"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The receiver is the person or group the message is aimed at, who interprets (decodes) it and may respond. Option A is the sender, C is the medium, and D is the message."}},{"itemId":"e87e7aa9-5385-5eea-914c-ee5e3e7a93c0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"85037767-ae2c-51ae-a38b-931fc99d8f9d","sourceKey":"bank:LAG-BUA123:PQ-040","parentItemId":null,"revision":1,"payload":{"prompt":"The medium in marketing communication is most accurately described as:","options":["The channel, such as digital platforms or broadcast media, that delivers the message","The sender who creates the communication","The audience that receives the message","The process of assessing the message's impact"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The medium is the route a message travels along, for example television, radio, print, websites or social media. Option B is the sender, C is the receiver and D is evaluation through feedback."}},{"itemId":"7afc269b-1e2d-5fb2-84ee-9f2daad5e902","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fdf8779b-bee5-565d-bd76-3c984401aa25","sourceKey":"bank:LAG-BUA123:PQ-041","parentItemId":null,"revision":1,"payload":{"prompt":"An opinion leader in marketing communication is best described as:","options":["A person with little knowledge of or interest in the product category","A trusted person whose views and recommendations shape other people's attitudes and actions","A mass medium used to broadcast the firm's messages","A firm's most junior salesperson"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Opinion leaders are people others look to for advice, so when they speak about a product their peers tend to listen and follow. Option A is the opposite, because opinion leaders usually know a lot about the category, C confuses a person with a medium, and D has nothing to do with social influence."}},{"itemId":"a0555cdb-aec0-5f7a-a383-472a4bbf1067","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0cf22a10-4414-550b-a5da-a1df606cc3dc","sourceKey":"bank:LAG-BUA123:PQ-042","parentItemId":null,"revision":1,"payload":{"prompt":"For a marketing communication to be effective, its source should be:","options":["Unknown to the audience so that the message seems neutral","Paid the highest possible fee, whatever the audience thinks of them","Perceived as credible, knowledgeable and relevant by the audience","Unconnected to the product to avoid any appearance of bias"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Audiences are more likely to believe and act on a message when they trust the person or organisation delivering it and see them as linked to the product. Option A removes the trust that comes from a known sender, B focuses on cost rather than credibility, and D weakens the relevance that makes a sender persuasive."}},{"itemId":"ff31c20a-781a-5acf-9988-6439d75256d0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9a0f0258-9b05-5c2a-acee-66bf2b008a58","sourceKey":"bank:LAG-BUA123:PQ-043","parentItemId":null,"revision":1,"payload":{"prompt":"An effective message in marketing communication should be:","options":["Ambiguous and open to many interpretations","Clear, compelling and tailored to the audience's needs and values","Packed with every product feature, whatever the audience needs","Exactly the same for every audience segment"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A message works best when the audience can understand it easily and sees something in it that matters to them. Option A invites misunderstanding, C overloads people with information they may not care about, and D ignores the differences between segments."}},{"itemId":"79b5d921-9dac-554d-9d95-050804a6966a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"36a75c8b-a2f0-5992-9d2d-535308f910e1","sourceKey":"bank:LAG-BUA123:PQ-044","parentItemId":null,"revision":1,"payload":{"prompt":"A receiver's reaction to a marketing communication depends on:","options":["Only the size of the firm's advertising budget","Only the number of times the message is repeated","The firm's production timelines","Their own interpretation, cultural background and how relevant the message is to them"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"People decode messages through their own experience, culture and needs, so the same advert can mean different things to different receivers. Options A and B are wrong because they claim a single sender-side factor decides everything, and C has no direct effect on how a message is interpreted."}},{"itemId":"b17440d3-0133-530d-8c07-3156eaffc7f3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"558527f5-8381-5676-ab62-fe49f195686a","sourceKey":"bank:LAG-BUA123:PQ-045","parentItemId":null,"revision":1,"payload":{"prompt":"The medium used in marketing communication should be:","options":["Selected to match the target audience's media preferences and habits","Always the cheapest one available","Always television, because it reaches the most people","Chosen before the target audience has been identified"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A message only works if it reaches the right people, so the medium should be one the target audience actually uses. Option B puts cost ahead of reach, C ignores audiences who rarely watch television, and D reverses the logical order of planning."}},{"itemId":"ee554a51-c0b1-503a-bfde-696cd3d6f518","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9ca744ac-c99a-5783-8599-ea45a15637e9","sourceKey":"bank:LAG-BUA123:PQ-046","parentItemId":null,"revision":1,"payload":{"prompt":"Opinion leaders are important in marketing communication because they:","options":["Remove the need for any paid advertising","Increase a message's reach and credibility through their social influence","Control the firm's distribution channels","Set the selling price of the product"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"When trusted people pass on or endorse a message, it spreads to their followers and peers and is believed more readily. Option A overstates their effect, since firms still use advertising, while C and D are distribution and pricing decisions made by the firm."}},{"itemId":"4b91025e-e577-5d88-b225-a84054eac014","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0a4f14da-3230-541b-8b2f-3bd43ead3f8c","sourceKey":"bank:LAG-BUA123:PQ-047","parentItemId":null,"revision":1,"payload":{"prompt":"The interplay of source, message, receiver and medium constitutes:","options":["The marketing mix of product, price, place and promotion","The stages of the product life cycle","The framework of the marketing communication process","The segmentation, targeting and positioning process"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"These four elements are the building blocks of any communication, so together they describe how marketing communication works. Option A is the marketing mix, B describes how sales change over a product's life, and D is how firms choose markets."}},{"itemId":"7a77d779-9863-5eff-b892-9aaa01c12214","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3e716461-eb81-553a-b590-45c729990db2","sourceKey":"bank:LAG-BUA123:PQ-048","parentItemId":null,"revision":1,"payload":{"prompt":"A strategically crafted message in marketing communication should:","options":["Focus only on what the firm wants to say about itself","Be as long as possible so that nothing is left out","Use technical terms the audience may not understand","Connect with the audience's aspirations, problems and motivations"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A message works when the audience recognises its own needs and goals in it, which makes them pay attention and respond. Option A ignores the receiver, B risks losing attention, and C creates a barrier to decoding the message."}},{"itemId":"1ac830c8-d4e5-55f5-bef7-923d982589b8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"78644f81-9e87-51d1-b74e-f5ea22c16b94","sourceKey":"bank:LAG-BUA123:PQ-049","parentItemId":null,"revision":1,"payload":{"prompt":"Business communication is most completely defined as:","options":["Communication that takes place only among employees","Messages sent only to customers outside the firm","The exchange of information within and outside the organisation to achieve its goals","Only written communication such as letters and memos"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Business communication covers internal communication among staff and departments as well as external communication with customers, suppliers and other stakeholders, in spoken, written or electronic form. Options A and B each cover only one direction, and D leaves out spoken and electronic communication."}},{"itemId":"c2531779-abda-57ad-8aab-f623e31431c3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"42bd1999-4000-536f-918b-efed520e535b","sourceKey":"bank:LAG-BUA123:PQ-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of business communication?","options":["Building a prototype of a new product","Carrying out routine maintenance on factory machines","Physically counting stock in the warehouse","Analytical reports circulated to stakeholders"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"A report sent to stakeholders passes information from one party to another for a business purpose, which is what business communication means. Options A, B and C are product development, maintenance and stock control activities that do not involve sending a message to anyone."}},{"itemId":"f20ccbed-21a8-5639-90d9-66c51fc9387d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0a52d66a-4e67-59e4-ba0a-1f5400ec2d94","sourceKey":"bank:LAG-BUA123:PQ-051","parentItemId":null,"revision":1,"payload":{"prompt":"The communication model in a business context typically comprises:","options":["Product, price, place and promotion","Attention, interest, desire and action","Sender, message, channel, receiver and feedback","Advertising, sales promotion, public relations and personal selling"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"The basic communication model follows a message from the sender, through a channel, to the receiver, with feedback showing the sender whether the message was understood. Option A is the marketing mix (the 4 Ps), Option B is the AIDA sequence of how buyers respond to a message, and Option D lists promotion tools, not the parts of the communication model."}},{"itemId":"dc5816e1-62b4-5c6d-a230-1e7959519d53","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5ec5a607-5b58-52cd-9858-4efe1e86d7cc","sourceKey":"bank:LAG-BUA123:PQ-051-b","parentItemId":null,"revision":1,"payload":{"prompt":"In the communication model, the stage at which the receiver interprets the symbols in a message to work out its meaning is called:","options":["Decoding","Encoding","Noise","Feedback"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"Decoding is the receiver's side of the process: turning the words, sounds or images received back into meaning. Option B, encoding, is done by the sender when putting an idea into a message, Option C, noise, is anything that distorts the message, and Option D, feedback, is the receiver's response sent back to the sender."}},{"itemId":"fd1e7887-cd6c-5ee5-81b7-4aeed4ee5022","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"23ebb456-fb02-5b46-a6a8-633e81834021","sourceKey":"bank:LAG-BUA123:PQ-052","parentItemId":null,"revision":1,"payload":{"prompt":"The communication process in business involves:","options":["Transmitting a message one way while deliberately blocking any feedback","Decoding a message before the sender has decided what to say","Setting a product's price and then choosing its distribution outlets","Encoding an idea into a message, transmitting it through a channel and decoding by the receiver"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Communication starts when the sender encodes an idea into a message, sends it through a channel, and the receiver decodes it to get the meaning. Option A is wrong because feedback is a normal part of the process, not something to block, Option B reverses the order, and Option C describes pricing and distribution decisions rather than communication."}},{"itemId":"180e63ab-25fe-5b0e-a14c-72dae0d87c3b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a953307d-3fc0-512c-87a7-a3b9446c74be","sourceKey":"bank:LAG-BUA123:PQ-053","parentItemId":null,"revision":1,"payload":{"prompt":"A common form of business communication is:","options":["Product manufacturing and assembly","Oral communication, such as discussions during meetings","Financial auditing and compliance checks","Stock-taking of raw materials"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Oral (spoken) communication, such as discussions in meetings, phone calls and presentations, is one of the main forms of business communication, alongside written and non-verbal forms. Options A, C and D are business activities, but none of them is a way of passing messages between people."}},{"itemId":"a5fd233c-b9f6-5728-bd7f-cdc9d8ba40f8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5bd2b222-1dc5-5008-9878-7ecb54b71c1f","sourceKey":"bank:LAG-BUA123:PQ-054","parentItemId":null,"revision":1,"payload":{"prompt":"The communication model is useful to a business because it:","options":["Explains how organisational messages are sent and received","Fixes the selling price of each product","Removes the need to know the target audience","Guarantees that every message will be understood"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"A communication model is a simple picture of how a message moves from sender to receiver, which helps managers see where communication can succeed or break down. Option D is tempting, but no model can guarantee understanding because noise can still distort a message, Option C is wrong because knowing the receiver is central to the model, and Option B is a pricing decision."}},{"itemId":"bfbeefd8-c539-5fe9-8386-25548ea236f8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"221c0b3e-dd97-5e89-98f9-bbe70db118e5","sourceKey":"bank:LAG-BUA123:PQ-055","parentItemId":null,"revision":1,"payload":{"prompt":"An effective communication process in business ensures that:","options":["Customer preferences are ignored for the sake of speed","Messages are sent without considering the receiver","Only senior managers are allowed to send messages","Messages are crafted, delivered and interpreted with clarity and purpose"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"The aim of a well-managed communication process is that the intended meaning is created by the sender, carried through a suitable channel and understood by the receiver. Option B and Option A would make communication fail because the receiver's needs shape how a message should be designed, and Option C wrongly limits communication to one group."}},{"itemId":"b3ca65e8-d397-59c2-ac8e-14aaf3f941c7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dedae230-b809-5998-8727-1b3ed3d14ffb","sourceKey":"bank:LAG-BUA123:PQ-056","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of business communication?","options":["Product design and feature improvement","Financial planning and budget allocation","Non-verbal cues, such as body language, that influence how stakeholders see a firm","Recruitment and sourcing of talent"],"correctOption":2,"section":"Communication, Business Communication and the Communication Process","explanation":"Non-verbal communication, such as gestures, facial expressions, posture and dress, passes messages without words and shapes how customers, staff and partners see a business. Options A, B and D are product, finance and HR activities, not forms of communication."}},{"itemId":"8a4e52bc-95cc-56d4-914a-44352ce40641","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5d3ee311-d9a1-5484-b054-0f9eca23a762","sourceKey":"bank:LAG-BUA123:PQ-057","parentItemId":null,"revision":1,"payload":{"prompt":"Feedback is a critical element of the communication model because it:","options":["Is the channel through which the message travels","Shows the sender how the message was received so it can be corrected or refined","Is the distortion that interferes with a message","Is the sender's act of putting an idea into words or symbols"],"correctOption":1,"section":"Communication, Business Communication and the Communication Process","explanation":"Feedback is the receiver's response sent back to the sender, and it tells the sender whether the message was understood so it can be adjusted. Option A describes the channel or medium, Option C describes noise, and Option D describes encoding."}},{"itemId":"6d0aa5d0-d012-52b6-89f0-ef3b75997e16","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"0cff4961-3bc6-5065-959b-8dc64bfd7743","sourceKey":"bank:LAG-BUA123:PQ-058","parentItemId":null,"revision":1,"payload":{"prompt":"Strategically, the communication process in business supports:","options":["Reducing contact with customers to cut costs","Lowering product quality to meet price targets","Restricting product availability to create scarcity","Building relationships with internal and external stakeholders"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"Good communication lets a business keep employees, customers, suppliers and other stakeholders informed and engaged, which builds trust and long-term relationships. Option A works against this goal, while Options B and C are product and distribution choices that have nothing to do with the communication process."}},{"itemId":"e2511033-4097-5631-bab0-12985ee77d6b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"84de10e6-44f9-5a79-94da-1fa9e36ab13c","sourceKey":"bank:LAG-BUA123:PQ-059","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a common form of business communication?","options":["Product manufacturing and quality control","Financial forecasting and risk assessment","Machine maintenance scheduling","Presentations used to align a team on its objectives"],"correctOption":3,"section":"Communication, Business Communication and the Communication Process","explanation":"A presentation is a form of business communication that combines spoken words with visual aids to share information and get a group working toward the same goals. Options A, B and C are operational or financial tasks rather than ways of exchanging messages."}},{"itemId":"e4284d3a-4ff1-5ef6-a5f0-e213626b266d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b899084c-27f8-5a8b-b37f-444f8731798e","sourceKey":"bank:LAG-BUA123:PQ-060","parentItemId":null,"revision":1,"payload":{"prompt":"The communication model is significant because it helps to:","options":["Identify barriers that can stop a message from being delivered and understood","Suppress feedback so the sender stays in control","Cut advertising spending without any plan","Reduce the number of products a firm sells"],"correctOption":0,"section":"Communication, Business Communication and the Communication Process","explanation":"By breaking communication into parts (sender, message, channel, receiver, feedback and noise), the model helps a business spot where a message can go wrong, for example a poor channel or a confusing message. Option B is wrong because feedback is a part of the model that should be encouraged, and Options C and D are budget and product decisions."}},{"itemId":"d9c57927-48cd-5637-a95a-dc799431a55d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6de68cff-7afc-5c31-9e7f-89c20116c265","sourceKey":"bank:LAG-BUA123:PQ-061","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication in the internet era is distinguished by:","options":["Reliance only on traditional print and broadcast media","Use of social media platforms for two-way engagement with audiences","Exclusive use of personal selling","A sole focus on public relations campaigns"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"The internet, and especially social media, turned marketing communication into a two-way conversation in which brands talk directly with customers and customers talk back. Option A describes the pre-internet era, and Options C and D are wrong because the word 'only' or 'exclusive' ignores the mix of tools firms use online."}},{"itemId":"4025eb12-25e8-51c5-bc4b-433cc3f714b4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"160a4597-243e-58c2-bbab-16283feb7110","sourceKey":"bank:LAG-BUA123:PQ-061-b","parentItemId":null,"revision":1,"payload":{"prompt":"Online chat rooms and blogging websites, where many people exchange messages with many others, are examples of which type of communication?","options":["One-to-many","Many-to-many","One-to-one","Many-to-one"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Many-to-many communication lets large numbers of people send and receive messages among themselves, and it has grown with the internet through chat rooms, blogs and social media. Option A is one sender broadcasting to many people, as in a TV advert, Option C is a personal exchange such as a sales presentation, and Option D is many people replying to one sender, such as replies to an email."}},{"itemId":"0b8d9978-75ed-53f3-8ea3-d2eb5e40c28e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d1d67fbe-30dd-5b08-9e3f-15a6c1c79ad7","sourceKey":"bank:LAG-BUA123:PQ-062","parentItemId":null,"revision":1,"payload":{"prompt":"Social media marketing is best described as:","options":["Placing advertisements only in newspapers and magazines","Using platforms such as X (Twitter) and LinkedIn to deliver targeted, interactive content","Selling products door to door","Sending printed catalogues to customers by post"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media marketing means using social networks to share targeted content, interact with followers and promote a brand. Option A is print advertising, Option C is personal selling, and Option D is offline direct mail, none of which uses social platforms."}},{"itemId":"626a2cac-4e28-5650-9c2b-4349b2785b8d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"455041b2-8b47-52da-9131-8e127c37d3e4","sourceKey":"bank:LAG-BUA123:PQ-063","parentItemId":null,"revision":1,"payload":{"prompt":"The strategic role of social media in marketing communication is to:","options":["Broadcast one-way messages while ignoring customer comments","Replace the need for any product quality","Foster dialogue, build communities and strengthen customer relationships","Cut advertising budgets without evaluation"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media is valuable because it lets brands hold conversations with customers, gather communities of fans and keep relationships going over time. Option A misses the point, since the strength of social media is its two-way nature, and Options B and D are not roles of communication at all."}},{"itemId":"decff992-27ae-56e4-8d51-8cc1bcbcd95e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6e1ca6c1-f07e-56dd-90e8-3c646571c400","sourceKey":"bank:LAG-BUA123:PQ-064","parentItemId":null,"revision":1,"payload":{"prompt":"In the internet era, word-of-mouth communication has been:","options":["Made less relevant than traditional advertising channels","Abandoned by businesses that want to keep control of messages","Amplified through online reviews, shares and influencer endorsements","Weakened because online noise stops people from hearing it"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Word-of-mouth is now amplified because a single customer review, post or share can reach thousands of people in minutes. Option A and Option D wrongly suggest it has lost influence, and Option B is wrong because firms actively encourage positive online word-of-mouth rather than abandon it."}},{"itemId":"88c1eadf-5f11-52fd-bbb0-af5c39d6506a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8d738a1c-0379-505c-bda3-38847c13ce16","sourceKey":"bank:LAG-BUA123:PQ-065","parentItemId":null,"revision":1,"payload":{"prompt":"Social media marketing enables businesses to:","options":["Reach only people who already buy the product","Avoid collecting any information about customers","Send the same message to everyone with no targeting","Deliver closely targeted messages based on data about their audience"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social platforms collect data on users' interests, location and behaviour, so businesses can aim messages at the exact groups most likely to respond. Option C and Option B ignore this targeting ability, which also reaches new prospects, and Option A is the opposite of how these platforms work."}},{"itemId":"dae7d0ec-8716-55f6-91a6-d07301de4441","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c814abe2-5247-56ee-8df8-68df17947d38","sourceKey":"bank:LAG-BUA123:PQ-066","parentItemId":null,"revision":1,"payload":{"prompt":"Marketing communication in the internet era is characterised by:","options":["Less customer interaction so that campaigns are simpler","Greater interactivity, real-time engagement and integration across many channels","Fewer advertising options because of digital saturation","Less feedback because online platforms limit responses"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"The internet lets customers respond instantly, lets firms reply in real time, and allows the same campaign to run across websites, email, search and social media. Options A, C and D all suggest a reduction, when the internet has actually increased interaction, advertising options and feedback."}},{"itemId":"a7ad92c2-4044-5aa9-a155-6063b12b1ee5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f0b921f6-99a4-5594-a2dd-816cbc1ed7b4","sourceKey":"bank:LAG-BUA123:PQ-067","parentItemId":null,"revision":1,"payload":{"prompt":"A major function of social media in marketing communication is to:","options":["Increase brand visibility, affinity and long-term loyalty","Avoid engaging with customers to save resources","Compromise product quality for profit","Restrict product availability to create exclusivity"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Regular, engaging social media activity keeps a brand in front of its audience, makes people like it more and encourages them to stay loyal. Option B defeats the purpose of social media, and Options C and D are product and distribution decisions rather than communication functions."}},{"itemId":"c87982c8-5e6f-5369-8177-e612360a9244","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2717c4ba-0ca8-55ff-8dea-80e6d00caf10","sourceKey":"bank:LAG-BUA123:PQ-068","parentItemId":null,"revision":1,"payload":{"prompt":"Word-of-mouth communication remains important in the internet era because it:","options":["Is fully controlled by the company that pays for it","Costs nothing and therefore needs no strategy","Builds trust, credibility and purchase intent through the influence of peers","Only spreads through face-to-face conversation"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"People tend to trust recommendations from friends, family and other customers more than company adverts, so word-of-mouth strongly shapes buying decisions. Option A is wrong because word-of-mouth comes from customers and is not controlled by the firm, Option B ignores that firms still plan how to encourage it, and Option D ignores online reviews and shares."}},{"itemId":"344c6993-d655-57b5-934b-8372e9088db0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b640e01c-4531-50d3-a98b-31c1b3e3fbb9","sourceKey":"bank:LAG-BUA123:PQ-069","parentItemId":null,"revision":1,"payload":{"prompt":"The effectiveness of social media marketing comes mainly from its ability to:","options":["Send messages one way without customer responses","Enable two-way communication and real-time interaction with customers","Replace all other forms of marketing communication","Work without any content being created"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media lets customers comment, ask questions and share, and lets the brand reply immediately, which makes communication two-way and personal. Option A describes traditional one-way media, Option C overstates its role since firms still combine it with other tools, and Option D is wrong because social media depends on content."}},{"itemId":"5bbf3c22-b782-5128-a9d1-c9c1cbef6b3f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"711349d7-b297-5c80-8316-84f46a73a2dc","sourceKey":"bank:LAG-BUA123:PQ-070","parentItemId":null,"revision":1,"payload":{"prompt":"The internet has transformed marketing communication by:","options":["Speeding up the spread of messages and widening their reach to global audiences","Reducing customer interaction to streamline efforts","Limiting advertising options to traditional media","Reducing feedback because of digital overload"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Online, a message can be published once and reach people across the world almost instantly, far faster and wider than traditional media. Options B, C and D describe the reverse of what happened, since the internet increased interaction, added new advertising options and made feedback easier."}},{"itemId":"4f90f486-9786-53c0-897a-942b6e084d48","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b767ab03-ecf0-5c17-ad1c-e38acf9b2c94","sourceKey":"bank:LAG-BUA123:PQ-071","parentItemId":null,"revision":1,"payload":{"prompt":"The role of social media in marketing communication includes:","options":["Allowing direct engagement with customers and providing useful customer insights","Avoiding customer interaction to reduce costs","Removing the need for market research of any kind","Limiting a brand to a single target audience"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"On social media, brands talk directly with customers, and the comments, likes and shares give them insight into what customers think and want. Option B is the opposite of engagement, Option C overstates things because social insight supports research rather than replacing it, and Option D is not a feature of social media."}},{"itemId":"1c58c289-a49e-5c7c-a872-69b2c207370a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2ce556d4-bccb-5986-ad22-fdc77cbc0eac","sourceKey":"bank:LAG-BUA123:PQ-072","parentItemId":null,"revision":1,"payload":{"prompt":"Online word-of-mouth is described as dynamic mainly because:","options":["It is controlled entirely by the business","It is confined to traditional offline channels","Its impact can be positive or negative depending on customers' feelings and experiences","It always has the same effect on every brand"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Word-of-mouth reflects what customers actually experienced, so happy customers spread praise while unhappy ones spread complaints, and both can travel fast online. Option A is wrong because customers, not the business, create word-of-mouth, Option B ignores reviews and social posts, and Option D contradicts its changing nature."}},{"itemId":"98651259-e132-550a-9a88-34cd0f80ba38","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"89df5ffe-9551-511a-a11f-13a1705fa599","sourceKey":"bank:LAG-BUA123:PQ-073","parentItemId":null,"revision":1,"payload":{"prompt":"The role of communication in market relationships is to:","options":["Complete a single sale with no further contact","Minimise contact with customers to save resources","Build trust, loyalty and lasting customer commitment","Restrict product availability to create scarcity"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Communication keeps a firm connected to its customers after the first sale, building the trust and loyalty that turn one-off buyers into long-term customers. Option A describes a pure one-off transaction, which is the opposite of a relationship, and Options B and D would weaken the relationship."}},{"itemId":"6fd7f3e0-0a6f-565f-b0e2-7c6b60c568ee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"502df87d-af98-5c68-8b6b-2f3ec17f5073","sourceKey":"bank:LAG-BUA123:PQ-074","parentItemId":null,"revision":1,"payload":{"prompt":"An interactional approach to communication focuses on:","options":["One-way messages that the business fully controls","Suppressing feedback to maintain authority","Reducing advertising costs without strategy","Two-way dialogue between businesses and customers"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"The interactional approach sees communication as an exchange in which both the business and the customer send and respond to messages. Option A is the opposite, a one-way or linear view of communication, and Options B and C have nothing to do with interaction."}},{"itemId":"ebc40853-dc2f-5501-b348-a73797cde118","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e8b9d567-472d-5b68-9715-fbfc33f18f00","sourceKey":"bank:LAG-BUA123:PQ-075","parentItemId":null,"revision":1,"payload":{"prompt":"A relational approach to communication is centred on:","options":["Maximising the profit from each single transaction","Sending the same mass message to all audiences","Building lasting, value-based relationships with customers","Reducing contact with customers after a sale"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"The relational approach treats communication as a way of creating and keeping long-term relationships that give value to both the customer and the firm. Option A is a transactional, one-off focus, Option B ignores the relationship context, and Option D would end the relationship instead of building it."}},{"itemId":"97eed519-dd91-5054-8392-0d46998471b2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6beab7d1-ec9f-59aa-a294-a19475bbb47c","sourceKey":"bank:LAG-BUA123:PQ-076","parentItemId":null,"revision":1,"payload":{"prompt":"A network approach to communication emphasises:","options":["Communication between one seller and one buyer only","One-way messages from the firm to the mass market","Communication limited to departments inside the firm","Connected exchanges among many stakeholders, including partners and suppliers"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"The network approach looks beyond a single buyer and seller to the web of relationships among suppliers, distributors, partners, customers and others, all communicating with each other. Option A is a single dyad, Option B is mass one-way communication, and Option C is internal communication only."}},{"itemId":"9083da94-23e1-5b51-bf72-046f0a19692e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"30f22647-3ce8-589c-a34d-9444bf87ddbc","sourceKey":"bank:LAG-BUA123:PQ-077","parentItemId":null,"revision":1,"payload":{"prompt":"Communication in market relationships strategically aims to:","options":["Avoid customer engagement to streamline operations","Win a sale once and then end contact","Restrict product availability to increase demand","Strengthen customer loyalty through consistent delivery of value"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"When a firm keeps communicating and keeps delivering what it promises, customers grow loyal and keep buying. Option B is a short-term, transactional view, Option A reduces the contact that relationships depend on, and Option C is a distribution tactic, not a communication aim."}},{"itemId":"b13ba886-0dda-5d26-a8a8-4c2078138439","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"aaeb9893-ceb8-5cf5-9941-47a47b8cbe2c","sourceKey":"bank:LAG-BUA123:PQ-078","parentItemId":null,"revision":1,"payload":{"prompt":"An interactional approach to communication ensures:","options":["Feedback is suppressed so the firm keeps control","Active engagement with customers and responsiveness to their needs","Messages flow only from the firm to the customer","Customers receive messages but cannot reply"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Because the interactional approach is built on two-way exchange, the firm listens to customers and responds to what they say and need. Options A, C and D all describe one-way communication with no real customer input, which is the opposite of interaction."}},{"itemId":"c703c129-6234-56cd-b62e-e2d893f28a05","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"04249c7d-427d-5c90-9171-51b702ad41ad","sourceKey":"bank:LAG-BUA123:PQ-079","parentItemId":null,"revision":1,"payload":{"prompt":"A relational approach to communication enables businesses to:","options":["Focus only on one-off sales","Build trust and develop long-term partnerships with customers","Minimise customer engagement to save resources","Constrain product availability to create exclusivity"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Relational communication keeps a steady, trusted connection with customers so the relationship grows into a long-term partnership. Option A is the transactional approach the relational view moves away from, and Options C and D would weaken rather than build relationships."}},{"itemId":"9bef8a44-66be-5e59-8f8d-2a07579c9cf0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4d5b09f5-a5cc-5645-8da7-9d6b69917b1c","sourceKey":"bank:LAG-BUA123:PQ-080","parentItemId":null,"revision":1,"payload":{"prompt":"A network approach to communication is valuable for:","options":["Dealing with one customer at a time in isolation","Keeping communication within a single department","Managing relationships across a web of interdependent stakeholders","Replacing all contact with suppliers and partners"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Businesses depend on many connected parties such as suppliers, distributors, partners and customers, and the network approach helps coordinate communication across all of them. Options A and B focus on a single relationship or unit, and Option D is the opposite of a network view."}},{"itemId":"6bbfb398-61b0-572f-8a97-9f0f92566845","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dafd9e5a-e157-5d5b-924e-072ed7df69d2","sourceKey":"bank:LAG-BUA123:PQ-081","parentItemId":null,"revision":1,"payload":{"prompt":"Communication in market relationships fundamentally seeks to:","options":["Avoid customer engagement to reduce costs","Attract new customers while ignoring existing ones","Increase customer trust, satisfaction and retention","Restrict product availability to build demand"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"The purpose of relationship-focused communication is to keep customers satisfied and trusting so that they stay with the firm. Option B ignores retention, which is the heart of relationship marketing, Option A removes the contact relationships need, and Option D is a distribution tactic."}},{"itemId":"7a7ef16a-0f65-553c-9dc7-24ea4be3d825","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cff73c61-39e4-5545-97a6-b17a993b4e51","sourceKey":"bank:LAG-BUA123:PQ-083","parentItemId":null,"revision":1,"payload":{"prompt":"A relational approach to communication treats which of the following as a basis of competitive advantage?","options":["The lowest possible price on each single transaction","The largest possible number of one-off buyers","The cheapest possible advertising medium","Sustained, long-term customer relationships"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Under the relational approach, loyal long-term customers are hard for competitors to copy or steal, so the relationship itself becomes an advantage. Options A and B focus on single transactions rather than relationships, and Option C is a media cost choice."}},{"itemId":"62f26110-5061-5d32-96a0-146a0a262585","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4e8f0257-e815-510f-a6f0-791db11bc482","sourceKey":"bank:LAG-BUA123:PQ-084","parentItemId":null,"revision":1,"payload":{"prompt":"A network approach to communication supports businesses by:","options":["Limiting communication to the firm and its final customers","Removing the need to communicate with suppliers","Enabling effective collaboration across different stakeholder groups","Making each department communicate only internally"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Since the network approach links many stakeholders, it helps a business coordinate and collaborate with suppliers, distributors, partners and customers together. Option A leaves out the wider network, Option B contradicts it, and Option D keeps communication inside the firm."}},{"itemId":"9df11340-8444-5f3e-af51-88d8b45d3a2d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7b3f99c8-6723-527d-b8c6-7413504cc7ae","sourceKey":"bank:LAG-BUA123:PQ-085","parentItemId":null,"revision":1,"payload":{"prompt":"Online communication media are best exemplified by:","options":["Traditional broadcast channels like television and radio","Print publications like newspapers and magazines","Outdoor advertising like billboards and posters","Digital platforms such as social media, websites and apps"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Online media are channels that work over the internet, such as social media, websites, mobile apps and email. Options A, B and C are all offline or traditional media, because they reach audiences through broadcast signals, paper or physical sites."}},{"itemId":"b5024e18-6f7f-5598-bcd0-a91c5d78550d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4d153417-b9d5-57c8-9c37-3e8d073a68df","sourceKey":"bank:LAG-BUA123:PQ-086","parentItemId":null,"revision":1,"payload":{"prompt":"Offline communication media are characterised by:","options":["Digital channels like email and social media","Online platforms like websites and blogs","Traditional outlets such as television, radio and print advertising","Streaming services and podcasts"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Offline media are the traditional, non-internet channels such as television, radio, newspapers, magazines and billboards. Options A, B and D all depend on the internet, so they are online media."}},{"itemId":"e70b383f-33c0-547d-9132-143bdf9d9faa","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"ee8d3779-d407-5af1-87f3-9a9c702f11a2","sourceKey":"bank:LAG-BUA123:PQ-087","parentItemId":null,"revision":1,"payload":{"prompt":"Crafting digital marketing involves:","options":["Copying a print advert unchanged onto every website","Avoiding any measurement of online results","Developing strategic content suited to how audiences behave online","Ignoring which platforms the target audience uses"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Good digital marketing starts from how the target audience searches, browses and interacts online, and then plans content and channels to match. Option A ignores the differences between platforms, Option B throws away one of digital marketing's biggest strengths, and Option D would waste the budget on the wrong channels."}},{"itemId":"1a2494b3-2747-5830-9154-865b7faf9da0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4ccb4cb2-3e0d-503e-b738-6aeafcbc1c0d","sourceKey":"bank:LAG-BUA123:PQ-088","parentItemId":null,"revision":1,"payload":{"prompt":"Digital marketing communication includes:","options":["Targeted email campaigns and social media advertising","Traditional television and radio commercials","Print media like newspapers and magazines","Physical signage like billboards and flyers"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Email campaigns and social media adverts are digital because they are delivered over the internet and can be aimed at specific people. Options B, C and D are traditional offline media."}},{"itemId":"ddf333e8-ceeb-5c49-8fe0-99228cdd6b6a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5f009d88-5826-5631-bfb6-65774e23c4b9","sourceKey":"bank:LAG-BUA123:PQ-089","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a form of digital marketing?","options":["Direct mail campaigns targeting local markets","Search engine optimisation (SEO) to improve online visibility","Television advertising for mass reach","Print advertising in trade journals"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"SEO means improving a website so that it ranks higher in search engine results, making it easier for people to find online. Option A is posted letters or leaflets, Option C is broadcast media, and Option D is print media, so none of them is digital."}},{"itemId":"5d72c953-c6b4-5f66-8542-838799fdc502","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c464ce92-b73a-55f2-a589-de9abf420c3d","sourceKey":"bank:LAG-BUA123:PQ-090","parentItemId":null,"revision":1,"payload":{"prompt":"The strategic importance of digital marketing lies in its ability to:","options":["Reach only customers within walking distance of a shop","Reach large and even global audiences efficiently and at relatively low cost","Remove the need for any marketing plan","Work only for very large companies"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital channels let even a small firm reach audiences far beyond its location, often for less money than traditional media, and campaigns can be scaled up or down easily. Option A describes a very local reach, Option C is wrong because digital marketing still needs planning, and Option D ignores its use by small businesses."}},{"itemId":"acb49372-14d7-533f-8906-9fb135161dee","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8242be65-8e07-5bb6-a210-609e77764e83","sourceKey":"bank:LAG-BUA123:PQ-091","parentItemId":null,"revision":1,"payload":{"prompt":"Online communication media stand out because of their capacity to:","options":["Deliver only one-way messages with no response","Reach audiences without any need for the internet","Deliver precise, interactive and data-driven interaction with audiences","Avoid collecting any data on audience behaviour"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Online media let firms aim messages at specific people, let those people respond, and record data on how they react. Option A describes traditional one-way media, Option B contradicts what 'online' means, and Option D ignores the data these channels produce."}},{"itemId":"500fecf8-f675-5b71-8e63-8b5210b03cf5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"47166671-3b53-5c7f-a01c-42716e5e9302","sourceKey":"bank:LAG-BUA123:PQ-092","parentItemId":null,"revision":1,"payload":{"prompt":"Offline communication media remain relevant because they:","options":["Offer more precise tracking of results than online media","Allow instant two-way chat with every viewer","Depend completely on internet access","Reach audiences, including local ones, through established traditional channels"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Traditional media such as radio, newspapers and billboards still reach many people, including those who use the internet less, and local radio or posters are good for reaching a particular community. Option A is wrong because online media are easier to track, Option B describes online interaction, and Option C contradicts the meaning of offline."}},{"itemId":"65f88845-72ec-5ada-a5c7-17b0cf841fd6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8c988eaf-8ab8-5559-b3ef-3f80be918171","sourceKey":"bank:LAG-BUA123:PQ-093","parentItemId":null,"revision":1,"payload":{"prompt":"Crafting effective digital marketing requires:","options":["Using exactly the same message on every platform","Suppressing feedback to maintain authority","Focusing only on the lowest-cost channel","Deep insight into online consumer behaviour and how each platform works"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"To succeed online, marketers need to understand how their audience behaves online and what works on each platform, since a format that works on one may fail on another. Option A ignores platform differences, Option B throws away valuable feedback, and Option C chooses channels on cost instead of audience fit."}},{"itemId":"f81148c1-ebfd-5e8d-aa6b-e61cc6aca888","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"34fe77a0-20fc-51dd-8adf-5e7b1d45f2bc","sourceKey":"bank:LAG-BUA123:PQ-094","parentItemId":null,"revision":1,"payload":{"prompt":"Digital marketing communication enables businesses to:","options":["Monitor and analyse campaign performance with real-time metrics","Avoid measuring campaign results","Wait until the end of the year to see any results","Reach customers only through printed materials"],"correctOption":0,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital tools record clicks, views, shares and sales as they happen, so firms can see at once how a campaign is doing and adjust it. Option B and Option C ignore this real-time tracking, and Option D describes offline print media."}},{"itemId":"3402a293-183b-5f06-8eac-6efac25c50b8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6e2f3ade-df2a-5e50-b86d-1a0bba6a1708","sourceKey":"bank:LAG-BUA123:PQ-095","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a type of digital marketing?","options":["Television commercials for broad awareness","Newspaper adverts for regional reach","Pay-per-click (PPC) advertising for immediate website traffic","Direct mail for personalised outreach"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"In pay-per-click advertising, an advertiser pays each time someone clicks its online ad, which can bring visitors to a website quickly. Options A, B and D are broadcast, print and postal media, which are traditional offline channels."}},{"itemId":"82ad0f29-35ba-5687-906b-feb87927165d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8dccdc41-b731-5e1f-9106-6a601ea06c96","sourceKey":"bank:LAG-BUA123:PQ-096","parentItemId":null,"revision":1,"payload":{"prompt":"The value of digital marketing is shown by its ability to:","options":["Prevent customers from giving feedback","Slow down communication with customers","Allow instant customer engagement and quick responses","Limit a firm to a single message for all customers"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital channels let customers comment, ask and share immediately, and let firms respond within minutes, keeping conversations alive. Option A and Option B are the opposite of what digital marketing offers, and Option D ignores its ability to tailor messages."}},{"itemId":"b84fab17-28cc-578f-9eeb-2a9bb94040b4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"81a457e8-66bc-5f67-b652-6a81744ff031","sourceKey":"bank:LAG-BUA123:PQ-097","parentItemId":null,"revision":1,"payload":{"prompt":"Online communication media include:","options":["Traditional television and radio broadcasts","Print media like newspapers and magazines","Email marketing and online display advertisements","Outdoor signage like billboards and flyers"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Email marketing and online display ads are delivered through the internet, so they are online media. Options A, B and D are offline media that reach people through broadcast signals, paper or physical locations."}},{"itemId":"33fa6ac7-8deb-58a9-a5c7-ce77a8703655","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"179889b2-f4c2-5f49-9414-2c7f6451fd93","sourceKey":"bank:LAG-BUA123:PQ-098","parentItemId":null,"revision":1,"payload":{"prompt":"Offline communication media are effective for:","options":["Tracking each viewer's clicks in real time","Strengthening brand presence through tangible, traditional touchpoints","Targeting individuals by their online browsing data","Allowing instant replies in comment threads"],"correctOption":1,"section":"Online and Offline Media and Digital Marketing","explanation":"Physical and traditional media such as billboards, print adverts, flyers and broadcast commercials keep a brand visible in people's everyday surroundings. Options A, C and D describe strengths of online media, which rely on internet data and interaction."}},{"itemId":"be790c46-dbdc-58bc-8461-78780b6487ff","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"db149317-fa99-52df-9c07-2a0f1873ef54","sourceKey":"bank:LAG-BUA123:PQ-099","parentItemId":null,"revision":1,"payload":{"prompt":"Digital marketing communication is distinguished by its:","options":["One-way flow and difficulty of measurement","Dependence on printed materials","Interactivity, measurability and adaptability to audience needs","Fixed messages that cannot be changed once launched"],"correctOption":2,"section":"Online and Offline Media and Digital Marketing","explanation":"Digital communication lets audiences respond, records detailed results and can be changed quickly to suit different audiences. Option A describes traditional media, Option B is offline print, and Option D is wrong because digital campaigns can be edited quickly."}},{"itemId":"a9f1223f-c9f1-505b-843e-eb292b17dc0e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c4d3d6a3-18d5-5c9d-8680-a875ac36db66","sourceKey":"bank:LAG-BUA123:PQ-100","parentItemId":null,"revision":1,"payload":{"prompt":"An important benefit of digital marketing is its capacity to:","options":["Avoid customer interaction to reduce costs","Send identical messages to all customers","Remove the need to understand customer needs","Improve customer experiences through personalisation and engagement"],"correctOption":3,"section":"Online and Offline Media and Digital Marketing","explanation":"Because digital channels collect data on customers, firms can tailor content and offers to each person and interact with them, making the experience more relevant. Option B ignores personalisation, Option A is the opposite of engagement, and Option C is wrong because personalisation depends on understanding customer needs."}},{"itemId":"d07d099b-6ac4-5ea3-b67e-7718f358e592","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"575a8fe8-5cbd-514a-acf7-f5b536a1c651","sourceKey":"bank:LAG-BUA123:REL-001","parentItemId":null,"revision":1,"payload":{"prompt":"Of the different types of exchange, which two can be most readily observed in marketing, with marketing communications playing roles in both?","options":["Barter exchange and monetary exchange","Market exchange and relational exchange","Direct exchange and indirect exchange","Internal exchange and external exchange"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Market (transactional) exchanges and relational exchanges are the two types of exchange most easily observed, and marketing communications supports both of them. Options A, C and D are other ways of grouping transactions, but they are not the pair used to explain the role of communication in market relationships."}},{"itemId":"55a1d4d0-6506-5e75-b99d-c6b00af131bb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bceb4069-330a-585a-9114-aab97eae857c","sourceKey":"bank:LAG-BUA123:REL-002","parentItemId":null,"revision":1,"payload":{"prompt":"The shift away from reliance on one-off market exchanges towards a longer-term perspective that creates and maintains enduring partnerships with customers is known as:","options":["Relationship marketing","Transactional marketing","Mass marketing","Production orientation"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Relationship marketing is the long-term approach that focuses on creating and keeping lasting partnerships with customers instead of chasing single sales. Option B, transactional marketing, is exactly the one-off market exchange approach the shift moves away from, while options C and D focus on reaching everyone or on making products efficiently."}},{"itemId":"705d52f4-59a5-5a29-841a-4e79ec07d571","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"38450cbb-4ae7-5839-bccc-7cf9ff63c8b6","sourceKey":"bank:LAG-BUA123:REL-003","parentItemId":null,"revision":1,"payload":{"prompt":"A market (transactional) exchange is best described as:","options":["A one-off, short-term exchange focused mainly on the product and its price","An exchange between departments inside the same organisation","An exchange in which buyer and seller jointly plan future products together","A long-term exchange built on trust and repeated contact over many years"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"A market or transactional exchange is a discrete, short-term deal in which the focus is on completing the sale, usually on the basis of product and price. Options C and D describe relational exchange, where parties stay connected and cooperate over time, and option B is internal communication, not a market exchange."}},{"itemId":"59dfcce4-3e23-5fe5-aff1-e29c6756ee2a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f18f011d-730b-5eb8-a651-ede126b9bdb6","sourceKey":"bank:LAG-BUA123:REL-004","parentItemId":null,"revision":1,"payload":{"prompt":"A relational exchange is best described as:","options":["An exchange carried out only through mass media advertising","An ongoing exchange in which buyer and seller build trust and interact repeatedly over time","An exchange in which price is the only thing both parties care about","A single exchange that ends once the goods and payment have changed hands"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Relational exchange is long-term: buyer and seller keep dealing with each other, develop trust and commitment, and see value in continuing the relationship. Options C and D describe a one-off market exchange, and option A wrongly ties relational exchange to a single one-way channel."}},{"itemId":"e68d8647-4bfa-5737-9a60-38acbb5ea13d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3085e75b-39d3-5f43-a158-e1193af23c69","sourceKey":"bank:LAG-BUA123:REL-005","parentItemId":null,"revision":1,"payload":{"prompt":"Chidi buys a used phone charger from a hawker at a Lagos bus stop. They bargain over the price, he pays N2,500, and neither expects to deal with the other again. This is an example of:","options":["A long-term relational exchange","A network-based exchange","A strategic business partnership","A market (transactional) exchange"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"This is a market or transactional exchange because it is a single deal, the focus is on price, and there is no expectation of future dealings. Option A would require repeated contact and a developing relationship, and options B and C involve ongoing links between several parties or organisations."}},{"itemId":"74935448-5abc-548c-8e2e-3259973e79fe","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4c43748c-8626-5493-86ab-2630131d8990","sourceKey":"bank:LAG-BUA123:REL-006","parentItemId":null,"revision":1,"payload":{"prompt":"A cement manufacturer and a construction company in Abuja have dealt with each other for eight years. They share delivery schedules, plan supply together for new projects, and resolve problems through regular meetings. Their exchange is best described as:","options":["A market (transactional) exchange","A relational exchange","A barter exchange","A one-off spot purchase"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Long-term dealings, information sharing and joint planning are signs of a relational exchange, in which both parties value keeping the relationship going. Options A and D describe single, short-term deals, and option C is about swapping goods without money, which is not what is happening here."}},{"itemId":"ae8f8284-1433-5755-bd16-8239ae519c39","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9a282cc0-4dc7-5056-ac95-c416266f2507","sourceKey":"bank:LAG-BUA123:REL-007","parentItemId":null,"revision":1,"payload":{"prompt":"In a purely transactional (market) exchange, the main role of marketing communication is usually to:","options":["Inform and persuade buyers about the offer so that a sale is completed","Develop deep trust and commitment over many years of dialogue","Coordinate joint planning between long-term partner organisations","Maintain an ongoing personal relationship after every purchase"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"In a one-off market exchange, communication mainly informs buyers about the product and price and persuades them to buy now. Options B, C and D describe what communication does in relational exchanges, where the goal is to keep and deepen a relationship over time."}},{"itemId":"b2cfb52b-7d7d-52be-877e-d9cc3d0bdcb8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"08664656-670b-5144-84bd-97ca8fddae26","sourceKey":"bank:LAG-BUA123:REL-008","parentItemId":null,"revision":1,"payload":{"prompt":"In a relational exchange, the main role of marketing communication is to:","options":["Replace all personal contact with one-way mass advertising","Close a single sale as quickly as possible at the best price","Build and maintain trust, commitment and dialogue between the parties","Announce product features once and then stop all contact"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"When an exchange is relational, communication is used to keep the relationship alive: it builds trust and commitment and keeps a two-way dialogue going. Option B is the aim of a one-off transactional exchange, while options A and D cut off the ongoing contact that relationships depend on."}},{"itemId":"184ec727-9150-5f6e-b084-4609bac2d89c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2bab19fe-4bc8-568c-8908-18f177ff381f","sourceKey":"bank:LAG-BUA123:REL-009","parentItemId":null,"revision":1,"payload":{"prompt":"Relationship marketing is best defined as:","options":["Reducing prices below competitors to win one-off sales","Attracting, maintaining and enhancing long-term relationships with customers","Selling as many units as possible to new customers in one season","Communicating with customers only through mass advertising"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Relationship marketing focuses on attracting customers and then keeping and strengthening relationships with them over the long term. Options A and C are short-term, sale-by-sale approaches, and option D is one-way mass communication rather than relationship building."}},{"itemId":"3955df78-9da7-55a4-b694-17f7e8094d2d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2a41f049-42b3-5e2b-9ed9-27792058f8d3","sourceKey":"bank:LAG-BUA123:REL-010","parentItemId":null,"revision":1,"payload":{"prompt":"Which statement best captures the idea behind relationship marketing?","options":["Marketing ends the moment the customer has paid, so no further contact is needed","Marketing is mainly about producing goods as cheaply and efficiently as possible","Marketing is only about advertising on television and radio to reach many people","Marketing is not just about selling products; it is about building relationships and creating value"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Relationship marketing sees marketing as building lasting relationships and creating value for both sides, not just making a sale. Option A reflects a one-off transactional view, option B is a production view, and option C confuses marketing with a single promotional tool."}},{"itemId":"2cc6c63d-e864-50f8-bab4-e78d73302471","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d247f08e-421f-58d4-bddd-ff950a36c930","sourceKey":"bank:LAG-BUA123:REL-011","parentItemId":null,"revision":1,"payload":{"prompt":"In relationship marketing, a customer's confidence in a supplier's reliability and integrity is called:","options":["Commitment","Satisfaction","Trust","Awareness"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Trust is the confidence one party has that the other is reliable, honest and will keep its promises. Option A, commitment, is the desire to keep a valued relationship going, while options B and D are about knowing a brand exists and being pleased with a purchase."}},{"itemId":"923c8c47-131b-53e4-8636-d696f40e4d30","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"40874572-95b2-5962-8c2f-4baf239cf3e8","sourceKey":"bank:LAG-BUA123:REL-012","parentItemId":null,"revision":1,"payload":{"prompt":"An enduring desire by a customer to maintain a valued relationship with a firm is called:","options":["Commitment","Brand awareness","Trial","Trust"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Commitment is the lasting wish to keep a relationship going because it is valued. Option D, trust, is confidence in the partner's reliability, which helps create commitment but is not the same thing; options B and C are early stages of buyer behaviour."}},{"itemId":"96730924-9991-54cd-a818-6790746a078a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8dc28385-280a-56a0-8d53-752713a60fa9","sourceKey":"bank:LAG-BUA123:REL-013","parentItemId":null,"revision":1,"payload":{"prompt":"Which two variables are regarded as central to the success of relationship marketing?","options":["Price and discounts","Speed and volume","Awareness and reach","Trust and commitment"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Trust and commitment are treated as the key ingredients of successful long-term relationships: when they are present, partners cooperate and stay together. Options A, B and C matter in marketing generally but they do not hold a relationship together over time."}},{"itemId":"bc1ff2f4-bc9f-58c4-8cc5-e107e6442bb7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1525377f-5117-51f5-96e2-969b3bf4758f","sourceKey":"bank:LAG-BUA123:REL-014","parentItemId":null,"revision":1,"payload":{"prompt":"For five years, a Kano wholesaler has always delivered rice to a retailer on the agreed date, in the agreed quantity and at the agreed price. The retailer now places orders without checking every bag. The quality the retailer has developed towards the wholesaler is best described as:","options":["Trust","Impulse buying","Cognitive dissonance","Brand switching"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"The retailer has developed trust: years of reliable, honest delivery give confidence that the wholesaler will keep its promises. Option D means moving to a competitor, option C is post-purchase doubt, and option B is unplanned buying, none of which fit the case."}},{"itemId":"acbfb297-807e-5b65-92ba-91f792d06373","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"20789d0d-db1c-544e-ac47-ea64574efacf","sourceKey":"bank:LAG-BUA123:REL-015","parentItemId":null,"revision":1,"payload":{"prompt":"Aisha has banked with the same bank for ten years. Another bank offers her a slightly better savings rate, but she stays because she values her relationship with her account officer and the bank. Her behaviour mainly shows:","options":["Price sensitivity","Commitment to the relationship","A transactional orientation","Brand switching"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Aisha stays even when a rival offers a better deal because she values the relationship, which is what commitment means. Options A and D would lead her to move for the better rate, and option C describes someone who judges each deal only on its own terms."}},{"itemId":"4fddfe10-fc86-5fb4-a70d-4126ad77a882","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"630ebb01-fb75-55fe-8bd0-947000158e30","sourceKey":"bank:LAG-BUA123:REL-016","parentItemId":null,"revision":1,"payload":{"prompt":"Customer retention refers to:","options":["The number of new products a firm launches each year","The amount a firm spends on television advertising","A firm's ability to keep its existing customers buying from it over time","A firm's ability to attract first-time buyers from rival brands"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Customer retention is about keeping current customers coming back over time. Option D describes customer acquisition and brand switching, while options A and B are measures of product development and media spending."}},{"itemId":"913f4c6a-72db-50a7-9b03-8ebe38da9fc1","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"08a2bf5f-6899-5684-8ce5-bab00124a47d","sourceKey":"bank:LAG-BUA123:REL-017","parentItemId":null,"revision":1,"payload":{"prompt":"Relationship marketing places strong emphasis on customer retention mainly because:","options":["Existing customers never compare prices with competitors","New customers always spend more than existing customers","Retention removes the need for any marketing communication","Keeping an existing customer usually costs less than attracting a new one"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"It generally costs less to keep a customer than to win a new one, and loyal customers tend to buy more and recommend the firm, so retention is profitable. Option B is untrue as a general rule, option A is unrealistic, and option C is wrong because retention itself depends on continued communication."}},{"itemId":"37a645d8-2e5f-55b5-9fdb-6034da233267","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b2f916cd-07c1-527e-b438-596d27a60944","sourceKey":"bank:LAG-BUA123:REL-018","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a characteristic of relational exchange?","options":["Long-term orientation towards keeping the customer","Trust and commitment between buyer and seller","Regular two-way communication and feedback over time","Focus on completing a single sale with no further contact"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"A focus on a single sale with no further contact is the mark of a transactional exchange, not a relational one. Options A, B and C are all typical features of relational exchange, which is long-term, trust-based and kept alive by ongoing dialogue."}},{"itemId":"5a284032-c2b5-57e9-8827-95ff44cdbade","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f3f451f1-d82c-52b3-a9b5-8053d79e8aee","sourceKey":"bank:LAG-BUA123:REL-019","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT typical of a transactional approach to marketing?","options":["A short time scale for each exchange","High emphasis on customer service and long-term contact","Emphasis on product features and on price","Focus on completing each single sale on its own"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"A strong emphasis on customer service and continuing contact belongs to relationship marketing. Options A, C and D are classic features of transactional marketing, which looks at each sale on its own, stresses features and price, and has a short time horizon."}},{"itemId":"dafc4fdf-0d70-5722-be7c-99ae2222af3b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"87b7a21a-6467-5b47-bca9-09258ad77f55","sourceKey":"bank:LAG-BUA123:REL-020","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with transactional marketing, relationship marketing focuses more on:","options":["Customer value and benefits over a long time scale","Mass production at the lowest possible cost","Single sales with limited customer contact","Product features over a short time scale"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Relationship marketing centres on the value the customer gets over time and on keeping the customer. Options C and D describe the transactional approach, and option B is a production orientation rather than either marketing approach."}},{"itemId":"5c4a2bbd-b286-58f7-a805-3912a87f688a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dbc9d458-7bd8-53ab-b26a-2ee3072c7da7","sourceKey":"bank:LAG-BUA123:REL-021","parentItemId":null,"revision":1,"payload":{"prompt":"Customer lifetime value is best described as:","options":["The price a customer pays for the firm's most expensive single product","The value of the very first purchase a customer makes with the firm","The number of years a product stays on the market before withdrawal","The total value a customer is expected to bring to a firm over the whole relationship"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Customer lifetime value looks at the whole stream of purchases a customer is expected to make over the entire relationship, which is why it supports retention. Option B looks only at one sale, option A at one price, and option C at the product life cycle rather than the customer."}},{"itemId":"030784c3-a5b4-5f6e-9498-5455004163a6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6459039b-b992-550e-9f35-9cf95d18d52a","sourceKey":"bank:LAG-BUA123:REL-022","parentItemId":null,"revision":1,"payload":{"prompt":"A supermarket in Ikeja gives shoppers a card that earns points on every purchase, which can later be redeemed for gifts. The main relationship marketing purpose of this card is to:","options":["Attract only one-time buyers from other cities","Reduce the number of visits each customer makes","Encourage repeat purchases and retain customers","Replace the need to stock popular products"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"A points card rewards customers each time they come back, so its main aim is repeat buying and customer retention. Option A targets one-off buyers, option B is the opposite of what the card aims for, and option D has nothing to do with loyalty schemes."}},{"itemId":"f546703b-acbe-5606-a726-579b4c83d610","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"12bd0e31-8c62-5ad9-8bcc-f0ae643cc6bc","sourceKey":"bank:LAG-BUA123:REL-023","parentItemId":null,"revision":1,"payload":{"prompt":"On the relationship marketing 'ladder of loyalty', a customer who actively recommends the firm to other people is described as:","options":["A lapsed customer","An advocate","A prospect","A first-time customer"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"An advocate is a customer who has moved high up the loyalty ladder and actively speaks well of the firm to others. Option C has not yet bought, option D has bought only once, and option A has stopped buying."}},{"itemId":"5fbf2c84-4f76-5712-a323-7eb745766c45","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4b813a34-3ace-5f7c-a751-8fcad75b9ce2","sourceKey":"bank:LAG-BUA123:REL-024","parentItemId":null,"revision":1,"payload":{"prompt":"The rate at which customers stop doing business with a firm over a period is known as:","options":["Customer churn (defection)","Customer acquisition","Market penetration","Brand awareness"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Churn, or defection, measures how many customers a firm loses over a period, so lowering it is a key goal of relationship marketing. Option B is gaining new customers, option C is selling more in existing markets, and option D is how well people know the brand."}},{"itemId":"98c1202d-b3b2-5a3c-ab20-cef2aaa1c05c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"27b8f397-f9e5-5b30-8155-3be37b28bafc","sourceKey":"bank:LAG-BUA123:REL-025","parentItemId":null,"revision":1,"payload":{"prompt":"The interactional approach to communication views communication as:","options":["A process whose meaning depends only on the medium through which it is sent","A message passed only through mass media with no response from the audience","A two-way process in which participants send messages, respond and give feedback to each other","A one-way flow of messages from a sender to a passive receiver who does not reply"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"In the interactional approach, communication is an interaction: both parties send and receive messages and respond to each other through feedback. Options B and D describe a one-way linear view, and option A wrongly makes the medium the only thing that matters."}},{"itemId":"f3759204-0337-51b1-b084-81fd3ef73205","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f3416537-54d0-5cb6-a3c3-7b57c639ab44","sourceKey":"bank:LAG-BUA123:REL-026","parentItemId":null,"revision":1,"payload":{"prompt":"The interactional approach to communication differs from the simple linear model mainly because it:","options":["Removes the receiver from the communication process","Treats the sender as the only active participant","Assumes every message is understood exactly as intended","Includes feedback and response, so communication flows both ways"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"The linear model shows messages moving one way from sender to receiver, whereas the interactional approach adds response and feedback so that both sides take part. Options B and C are features of the linear view, and option A would mean there is no communication at all."}},{"itemId":"76ce0899-0a09-5d1a-a005-c9ccf7251948","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7fe4feb0-b148-5076-b262-42266b913fb3","sourceKey":"bank:LAG-BUA123:REL-027","parentItemId":null,"revision":1,"payload":{"prompt":"A customer complains on social media that her mobile data was wrongly deducted. The telecom firm replies within minutes, asks for details, she responds, and the firm fixes the problem and checks back with her. This exchange best illustrates the:","options":["Linear (one-way) model of communication","Network approach to communication","Interactional approach to communication","Mass broadcast approach"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Both parties keep sending messages and responding to each other, which is the two-way exchange at the heart of the interactional approach. Options A and D involve one-way messages with no response, and option B is about messages spreading across a wide web of many people."}},{"itemId":"d6601876-b099-58ad-b8fa-135e2ad449e2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"782bd2eb-e4ef-5553-8415-7ba84da6dda2","sourceKey":"bank:LAG-BUA123:REL-028","parentItemId":null,"revision":1,"payload":{"prompt":"Which element is most central to the interactional approach to communication?","options":["The number of people reached by one message","Feedback and response between the parties","The colour and design of the advertisement","The size of the media budget"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"The interactional approach depends on the parties responding to each other, so feedback is its core element. Options A, C and D concern spending, reach and creative design, which matter in campaigns but do not define interaction."}},{"itemId":"7da3fce7-76e3-5a50-9287-4d4d50308815","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7e402e14-4b48-5b28-a673-3e2a470e3746","sourceKey":"bank:LAG-BUA123:REL-029","parentItemId":null,"revision":1,"payload":{"prompt":"Communication in which both parties listen, respond and build shared understanding together, rather than one party simply talking at the other, is best described as:","options":["Dialogue","Propaganda","Broadcasting","Monologue"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Dialogue is a two-way conversation where both sides listen and respond, and it is what interactional and relationship-based communication aim for. Options C and D are one-way forms of communication, and option B is one-sided persuasion that does not invite a reply."}},{"itemId":"cec30eb4-0743-55a9-a697-0b741ebed294","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f48c3222-6ce7-55e6-ab4d-78153ae62c3f","sourceKey":"bank:LAG-BUA123:REL-030","parentItemId":null,"revision":1,"payload":{"prompt":"The relational (contextual) approach to communication holds that:","options":["Only the technical quality of the channel decides how a message is understood","Communication works best when the parties have no previous relationship at all","The meaning of a message is fixed and identical for every receiver in every situation","Meaning depends on the relationship between the participants and the context of the message"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"The relational or contextual approach says that people interpret messages through the relationship they have with each other and the situation they are in. Option C ignores context, option A looks only at the channel, and option B contradicts the idea that relationships shape communication."}},{"itemId":"3c48bba2-1836-5837-8593-db58c40019f5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4a812f1e-5694-5fc8-a63a-1972bde08874","sourceKey":"bank:LAG-BUA123:REL-031","parentItemId":null,"revision":1,"payload":{"prompt":"Two suppliers send a food processor in Ibadan the same message: 'Your order will arrive tomorrow.' The processor fully believes the supplier it has used reliably for years but doubts the new supplier. This difference is best explained by the:","options":["Relational (contextual) approach to communication","Linear (one-way) model of communication","Hypodermic needle view of communication","Mass media approach"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"The same words are interpreted differently because of the relationship and history between the parties, which is the central idea of the relational or contextual approach. Options B, C and D all assume a message has the same effect regardless of who sends it or the relationship involved."}},{"itemId":"aae00152-2b9a-5050-ad69-f13ee7196cdb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"88daecab-4723-528a-8d59-0d4413cb2069","sourceKey":"bank:LAG-BUA123:REL-032","parentItemId":null,"revision":1,"payload":{"prompt":"Which pairing correctly matches each approach to communication with its main focus?","options":["Interactional - meaning shaped by context; relational - one-way flow of messages","Interactional - one-way flow of messages; relational - spread across many people","Interactional - two-way message exchange; relational - meaning shaped by the relationship","Interactional - spread across many people; relational - one-way flow of messages"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"The interactional approach stresses the two-way exchange of messages with response and feedback, while the relational or contextual approach stresses that the relationship and context give messages their meaning. Options A, B and D mix these up or attach the linear and network ideas to the wrong approach."}},{"itemId":"2cd55411-70fe-57d6-a754-639ca1cf7606","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bd583cba-d3fc-5152-afd4-905413701525","sourceKey":"bank:LAG-BUA123:REL-033","parentItemId":null,"revision":1,"payload":{"prompt":"The relational approach to communication is mainly concerned with:","options":["Communication that develops and sustains the relationship between the parties","Communication that persuades a buyer to make one quick purchase","Communication that depends only on the price of the product","Communication that avoids any reply from the receiver"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"The relational approach focuses on how communication builds and keeps up the relationship between the parties, which in turn shapes how later messages are understood. Option B is a transactional aim, option D is one-way communication, and option C ignores the relationship altogether."}},{"itemId":"61b75009-796c-59d8-88fc-edf8902c3a82","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"48b0ee11-8c2e-5eb9-b9dd-ddcf18145799","sourceKey":"bank:LAG-BUA123:REL-034","parentItemId":null,"revision":1,"payload":{"prompt":"The network approach to communication views communication as:","options":["Flows of information through a web of interconnected people and organisations","A process that takes place only inside one department","A private exchange that never spreads beyond two people","A single message passing from one sender to one receiver only"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"The network approach sees communication as moving through networks: many linked individuals and organisations pass information to each other. Options B, C and D all restrict communication to a single link or a closed group, which is the opposite of a network view."}},{"itemId":"3c15a720-4105-5834-9e5e-adef047cd4d5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b61c8c6f-63c5-5c3a-b2db-7c5bce111b81","sourceKey":"bank:LAG-BUA123:REL-035","parentItemId":null,"revision":1,"payload":{"prompt":"News about a new fintech app spreads among UNILAG students: a few share it in their class WhatsApp groups, members forward it to other groups, and within days thousands have heard about it. This pattern is best explained by the:","options":["Relational (contextual) approach to communication","Network approach to communication","Linear (one-way) model of communication","Personal selling process"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"The message is moving from person to person across many linked groups, which is exactly what the network approach describes. Option C is a single one-way flow, option A focuses on how one relationship shapes meaning, and option D is a salesperson dealing directly with a buyer."}},{"itemId":"f6234012-3f8d-5562-a16a-76119dbedfb1","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b992d9f0-9805-5752-832a-e297ec95819c","sourceKey":"bank:LAG-BUA123:REL-036","parentItemId":null,"revision":1,"payload":{"prompt":"Which approach to communication best explains how word-of-mouth and viral messages spread among consumers?","options":["The linear approach","The interactional approach between two parties only","The production approach","The network approach"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Word of mouth and viral messages travel from person to person through webs of contacts, which is what the network approach explains. Option A is one-way communication, option B is limited to two parties, and option C is a business orientation, not a communication approach."}},{"itemId":"58f23d1b-cc01-59a3-8024-df0d1a3ccf0f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f0b97fed-83c4-5d8c-98ab-142d4af57570","sourceKey":"bank:LAG-BUA123:REL-037","parentItemId":null,"revision":1,"payload":{"prompt":"In the network approach, people who are well connected and pass information on to many others are important because they:","options":["Remove the need for any message to be sent at all","Stop messages from reaching other members of the network","Speed up and widen the spread of messages through the network","Only receive messages and never share them with others"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Well-connected members, such as opinion leaders, act as hubs that carry messages to many other people, so they speed up and widen diffusion. Options B and D describe people who block or absorb information, and option A makes no sense because a network still needs messages."}},{"itemId":"039df4de-6cd4-55be-a843-914a5731f4eb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6ff3b53a-0d93-5da7-80eb-fd7e82b2d443","sourceKey":"bank:LAG-BUA123:REL-038","parentItemId":null,"revision":1,"payload":{"prompt":"A beverage company in Lagos coordinates its communication with suppliers, distributors, retailers, advertising agencies and regulators, recognising that information passes among all of them. This view is best described as the:","options":["Network approach to communication","Hypodermic needle view of communication","Transactional approach to exchange","Linear approach to communication"],"correctOption":0,"section":"Communication in Market Relationships","explanation":"Seeing communication as flowing among many interconnected organisations in and around the distribution channel is the network approach. Options B and D treat communication as one-way from one sender, and option C is about one-off exchanges rather than how communication flows."}},{"itemId":"84b42df7-325d-56ab-8951-6ce291471fb2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"246dc5f7-190b-566c-b3b9-860828ac2239","sourceKey":"bank:LAG-BUA123:REL-039","parentItemId":null,"revision":1,"payload":{"prompt":"The interactional, relational (contextual) and network approaches all differ from the simple linear model of communication in that they:","options":["Focus only on the technical channel used to carry the message","Ignore feedback and response between the sender and the receiver","Treat communication as more than a one-way transmission from sender to receiver","Assume the receiver is passive and never responds to any message"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"All three approaches move beyond the idea of a one-way message: they add response, relationships, context and networks of people. Options A, B and D are actually limitations of the linear view that these approaches set out to correct."}},{"itemId":"3a1db3ae-ee60-57bd-b8be-55f5c7629ccb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"73a4a82c-6c6a-5029-96e3-d97ef35136c8","sourceKey":"bank:LAG-BUA123:REL-040","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a benefit a firm usually gains from strong customer relationships?","options":["Customers who are less likely to switch to rivals","Positive word-of-mouth recommendations","Customers who buy once and never return","More repeat purchases"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Customers who buy once and disappear are what poor relationships produce, so this is not a benefit. Options A, B and D are all typical rewards of good relationships: loyal customers buy again, recommend the firm and resist rival offers."}},{"itemId":"c55fe068-459e-553e-a4e0-3a5b1cb3fd27","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"235f0f4a-e66b-5857-8259-145d0d568234","sourceKey":"bank:LAG-BUA123:REL-041","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian telecom operator sends each subscriber a personalised birthday message with bonus airtime, and its customer care team remembers past complaints when customers call. These actions are best described as:","options":["Price skimming","Mass marketing","Transactional marketing","Relationship marketing"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Personalised recognition and remembering each customer's history are ways of building long-term relationships and loyalty. Option C focuses on single sales, option B treats all customers the same, and option A is a pricing strategy for new products."}},{"itemId":"2626ed7a-44db-57f5-a290-7c58e8700b37","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"12ff0205-ca04-596c-9153-77811579dcdf","sourceKey":"bank:LAG-BUA123:REL-042","parentItemId":null,"revision":1,"payload":{"prompt":"Customer loyalty is best described as:","options":["A customer's first trial purchase of a newly launched brand","A customer's formal complaint to the firm about a faulty product","A customer's continued preference for and repeat purchase of a firm's brand over time","A customer's habit of always switching to whichever brand is cheapest"],"correctOption":2,"section":"Communication in Market Relationships","explanation":"Loyalty means the customer keeps preferring and buying the same brand over time, which is a main goal of relationship marketing. Option A is trial, option D is price-driven switching, and option B is a service recovery situation."}},{"itemId":"be1ab8f3-db7c-5ddf-8167-2b7b46657cdb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cbff0035-2cdb-52d7-9e24-887382f00310","sourceKey":"bank:LAG-BUA123:REL-043","parentItemId":null,"revision":1,"payload":{"prompt":"In a transactional exchange, the relationship between buyer and seller typically:","options":["Requires regular two-way meetings to sustain it","Ends once the goods and payment have been exchanged","Depends heavily on trust built over repeated dealings","Continues for many years through joint planning"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"A transactional exchange is complete once the product and payment change hands; nothing binds the parties to continue. Options A, C and D describe the continuing, trust-based contact of relational exchange."}},{"itemId":"055f00e9-36a5-5d0d-a857-a7a4041b8c0b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9911e3d2-1748-5758-af7b-b289d993cecb","sourceKey":"bank:LAG-BUA123:REL-044","parentItemId":null,"revision":1,"payload":{"prompt":"A relational exchange is characterised by interdependence, which means that:","options":["Each party acts alone and ignores the other's interests","Each party relies on the other and gains from continuing the relationship","The parties never communicate after the first sale","Only the seller benefits from the exchange"],"correctOption":1,"section":"Communication in Market Relationships","explanation":"Interdependence means both sides depend on each other and benefit from keeping the relationship going, so they cooperate. Option A describes independent, one-off dealing, option D is one-sided, and option C describes a transactional exchange."}},{"itemId":"7772f291-8ba7-599d-a1e2-b1ae9139044a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b45d8ab2-4ad1-5b30-9383-cbff20488b18","sourceKey":"bank:LAG-BUA123:REL-045","parentItemId":null,"revision":1,"payload":{"prompt":"Among the conditions for exchange, the requirement that 'each party trusts and respects the other sufficiently to take the exchange seriously' shows that even a single transaction depends on:","options":["The use of television advertising","The seller offering the lowest price in the market","A long-term written contract","A basic level of trust between the parties"],"correctOption":3,"section":"Communication in Market Relationships","explanation":"Even a one-off exchange needs enough trust for both parties to take it seriously, which is why trust is so central when exchanges become long-term relationships. Option C is not required for every exchange, and options A and B are marketing choices, not conditions of exchange."}},{"itemId":"75b66b6c-159e-5df1-b02d-67c5acb9ce79","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1f49273d-708d-5473-8e85-ed6ba56456fd","sourceKey":"bank:LAG-BUA123:SMR-003","parentItemId":null,"revision":1,"payload":{"prompt":"Unplanned distortion or interference during the communication process, which can cause the receiver to get a different message from the one the sender sent, is called:","options":["Noise","Encoding","Feedback","Response"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Noise is anything that disturbs the message on its way, whether physical sounds, clutter from other adverts, or misunderstanding. Option C is the receiver's reply to the sender, and option D is the receiver's reaction after receiving the message."}},{"itemId":"8a613ec0-5cee-5ae5-9c0e-77bb06d316d4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cb95c83b-a9e7-5e5e-ba6d-9c66a381fbfb","sourceKey":"bank:LAG-BUA123:SMR-004","parentItemId":null,"revision":1,"payload":{"prompt":"A radio jingle for a paint brand is broadcast while loud generator sounds drown it out in many homes, so listeners miss the brand name. In communication terms, the generator sound is:","options":["Feedback","Noise","Decoding","Encoding"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Noise is interference that prevents the message from being received as intended, and here the generator sound physically blocks the jingle. Option A would be listeners' reactions sent back to the firm, and option D is the firm's job of creating the jingle."}},{"itemId":"22dadafb-9168-5254-ab98-e41fab42e2ef","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"36bf4151-e523-5945-89ac-cf04ee800020","sourceKey":"bank:LAG-BUA123:SMR-005","parentItemId":null,"revision":1,"payload":{"prompt":"The part of the receiver's response that is communicated back to the sender is called:","options":["Noise","Encoding","The medium","Feedback"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Feedback closes the communication loop by telling the sender how the message was received. Option A is interference with the message, and option C is the channel that carries the message."}},{"itemId":"1e09caec-a93b-5be3-addc-831bb8a893eb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"54a23a49-6d34-51b0-99e9-ba19a4bd0b16","sourceKey":"bank:LAG-BUA123:SMR-006","parentItemId":null,"revision":1,"payload":{"prompt":"After a new advert runs, a company tracks calls to its hotline, changes in sales and comments on its social media page to judge how the message was received. These are all forms of:","options":["Feedback","Message sidedness","Encoding","Noise"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Calls, sales changes and online comments all carry the audience's response back to the sender, which is feedback. Option D would be interference that distorts the message, and option C is the sender's work of creating the advert."}},{"itemId":"63e4914f-d6de-56ca-909f-3f46b708c775","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fe833c22-74c5-5598-a028-b2a09221d3ee","sourceKey":"bank:LAG-BUA123:SMR-007","parentItemId":null,"revision":1,"payload":{"prompt":"Communication is most effective when the sender's and receiver's ______ overlap, that is, when they share similar experiences, attitudes and language.","options":["Fields of experience","Noise levels","Media budgets","Adopter categories"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A field of experience is the background of knowledge, values and language a person brings to communication, and the more sender and receiver share, the better the message is understood. Options B, C and D have nothing to do with shared understanding between the two parties."}},{"itemId":"b355eb4e-b7ca-56a9-a668-f5b43037b9f9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2f07da68-770a-5f5d-bbb1-336e0b0ab3b3","sourceKey":"bank:LAG-BUA123:SMR-008","parentItemId":null,"revision":1,"payload":{"prompt":"An agency writes an advert full of slang popular with Lagos teenagers, but the product is aimed at elderly rural farmers, who cannot understand the advert. The main communication problem is:","options":["Too much feedback from the target audience","Too little overlap between the fields of experience of sender and receiver","A source with too much expertise","A message that is two-sided instead of one-sided"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The sender encoded the message in language that the receivers do not share, so they cannot decode it correctly. Option D concerns presenting pros and cons, which is not the issue here, and option A makes no sense because the farmers did not respond at all."}},{"itemId":"8f2769e5-61c5-5476-bb54-3241ce40ecab","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"67b7e9c7-0066-538d-a1cf-b7a2fc824b21","sourceKey":"bank:LAG-BUA123:SMR-009","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a personal communication channel?","options":["A television commercial","A newspaper advertisement","A salesperson's face-to-face conversation with a customer","A roadside billboard"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Personal channels involve two or more people communicating directly with each other, such as face to face, by phone or by email, with personal feedback. Options A, B and D are non-personal mass media that carry messages without personal contact or feedback."}},{"itemId":"3547f3cd-cf3e-569c-99f0-af30f7e3d397","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"bcf95a33-66a8-56da-9d85-e8e58065c801","sourceKey":"bank:LAG-BUA123:SMR-010","parentItemId":null,"revision":1,"payload":{"prompt":"Non-personal communication channels include:","options":["Independent experts speaking with clients","Salespeople, friends and family members","Print and broadcast media, display media, atmospheres and events","Neighbours discussing products over the fence"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Non-personal channels carry messages without personal contact or feedback, and include major media, designed environments (atmospheres) and staged events. Options A, B and D all involve people communicating directly, which makes them personal channels."}},{"itemId":"af928821-1b65-52cd-b006-274aa98ba747","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2701a2d6-2ead-55ca-84c5-e74c6fc1b3a5","sourceKey":"bank:LAG-BUA123:SMR-011","parentItemId":null,"revision":1,"payload":{"prompt":"When a buyer's friends, neighbours and family members talk to them about a product, this is which kind of personal communication channel?","options":["An advocate channel","A social channel","An expert channel","A non-personal channel"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Social channels are made up of neighbours, friends, family and associates talking to target buyers. Option A is company salespeople contacting buyers, and option C is independent experts making statements to buyers."}},{"itemId":"cbdc2947-297e-5394-8371-0cf9a7a2966a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e743f861-98f3-54b6-adae-bc55690e95e4","sourceKey":"bank:LAG-BUA123:SMR-012","parentItemId":null,"revision":1,"payload":{"prompt":"Which medium offers sight, sound and motion and very wide mass reach, but has a high absolute cost?","options":["Newspapers","Television","Billboards","Radio"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Television combines pictures, sound and movement and reaches huge audiences, but producing and airing commercials is expensive in total. Option D is audio only, option A has no sound or motion, and option C can show only a short, still message."}},{"itemId":"5b91793c-b2ad-5297-a36a-e7ce0472b32f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7fd4a0e6-c009-5711-9db4-54681cd1b2b0","sourceKey":"bank:LAG-BUA123:SMR-013","parentItemId":null,"revision":1,"payload":{"prompt":"The three basic categories of source characteristics that influence how persuasive a source is are:","options":["Reach, frequency and impact","Encoding, decoding and feedback","Credibility, attractiveness and power","Awareness, trial and adoption"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A source persuades through credibility (expertise and trustworthiness), attractiveness (similarity, familiarity and likability) and power (ability to reward or punish). Option B lists parts of the communication process, option A lists media planning terms, and option D lists steps in adoption."}},{"itemId":"76a1a94c-cf45-51df-9f85-0b8852644710","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b01b449b-9c30-5f5a-8153-0fe6d1622fe0","sourceKey":"bank:LAG-BUA123:SMR-014","parentItemId":null,"revision":1,"payload":{"prompt":"Source credibility is made up mainly of the source's:","options":["Similarity and familiarity","Reach and frequency","Power and control","Expertise and trustworthiness"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A credible source is seen as knowing what it is talking about (expertise) and as being honest and unbiased (trustworthiness). Option A lists parts of source attractiveness, and option C relates to source power."}},{"itemId":"e14ca6fc-90a7-5413-a9ec-f2448089c5bc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"14078bb1-6954-51f1-bddc-265e1b34c9d8","sourceKey":"bank:LAG-BUA123:SMR-015","parentItemId":null,"revision":1,"payload":{"prompt":"A toothpaste advert features a qualified dentist in a clinic explaining how the product helps prevent tooth decay. The advert relies mainly on the source's:","options":["Expertise","Physical attractiveness","Similarity to the audience","Power"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A dentist is seen as having specialised knowledge about teeth, so the advert draws on source expertise, a part of credibility. Option B would be a good-looking model, option D needs the ability to reward or punish, and option C would be an ordinary person like the viewers."}},{"itemId":"74c527da-5cba-51a2-add9-2c9dea901bcc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c179044d-851f-5c4c-b717-3ef7418020a0","sourceKey":"bank:LAG-BUA123:SMR-016","parentItemId":null,"revision":1,"payload":{"prompt":"The honesty, integrity and believability of a source, that is, the audience's belief that the source has no motive to mislead them, is called:","options":["Trustworthiness","Expertise","Power","Likability"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Trustworthiness is about whether the audience believes the source is being honest and objective. Option B is about knowledge and skill, which a source can have without being trusted, and option D is affection for the source's looks or personality."}},{"itemId":"a0f950a9-02e3-50f9-96e1-3af620171893","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f2c0eca6-5c47-5a80-a218-82233a1cb464","sourceKey":"bank:LAG-BUA123:SMR-017","parentItemId":null,"revision":1,"payload":{"prompt":"When a receiver accepts a credible source's view because they believe the information is accurate, so that it becomes part of their own beliefs, the process at work is:","options":["Selective exposure","Compliance","Identification","Internalisation"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Credibility works through internalisation: the receiver adopts the position because it seems correct and keeps it even when the source is not present. Option C is how attractiveness works, through wanting to be like the source, and option B is how power works, through reward or punishment."}},{"itemId":"fddb23cd-41bd-5fcc-b27c-55f32db4b42e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cd84bce4-b657-5d2a-8db2-ec45f4123815","sourceKey":"bank:LAG-BUA123:SMR-018","parentItemId":null,"revision":1,"payload":{"prompt":"Source attractiveness includes the source's:","options":["Ability to reward or punish the receiver","Formal position in a professional body","Expertise and trustworthiness","Similarity, familiarity and likability"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Attractiveness covers how similar the source is to the receiver, how familiar the receiver is with the source, and how much the receiver likes the source. Option C describes credibility, and option A describes power."}},{"itemId":"a71dfb92-5c90-5a70-8ac3-3d045ffda0f9","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a5cf5d61-dd4d-5f2d-9c17-b0300939db16","sourceKey":"bank:LAG-BUA123:SMR-019","parentItemId":null,"revision":1,"payload":{"prompt":"A detergent advert shows an ordinary mother of three in a busy Lagos home, just like the women the brand targets, explaining why she uses the product. The advert relies mainly on the source's:","options":["Formal authority","Power","Similarity to the audience","Expertise"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Viewers who see someone like themselves using the product feel 'she is like me', which is similarity, a part of source attractiveness. Option D would need a specialist such as a chemist, and options A and B need the ability to reward, punish or command."}},{"itemId":"658c326b-8eaa-5e6b-994d-0239cb43daa5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"aa4b1729-31d8-56c1-a394-ac00db4579ac","sourceKey":"bank:LAG-BUA123:SMR-020","parentItemId":null,"revision":1,"payload":{"prompt":"A source has power when it can administer rewards or punishments to the receiver. The receiver then goes along with the source's request mainly through:","options":["Decoding","Compliance","Identification","Internalisation"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Power leads to compliance: the receiver accepts the request to gain a reward or avoid a punishment, not necessarily because they agree. Option D is linked to credibility and option C to attractiveness."}},{"itemId":"e00f6e25-7698-5a3b-8335-67baf7d8927d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cd462bb1-ea31-56b0-9beb-4a7c5e4e2efc","sourceKey":"bank:LAG-BUA123:SMR-021","parentItemId":null,"revision":1,"payload":{"prompt":"Why is source power rarely usable in mass advertising?","options":["Powerful sources always cost more than any firm can afford","Consumers always ignore sources that have expertise","Advertisers usually cannot reward or punish consumers, nor check whether they comply","Power works only when the message is carried on radio"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Power depends on being able to reward or punish and to watch whether the receiver complies, which a TV or press advert cannot do, so it is more relevant in personal selling. Options A, B and D are not true statements about power or about consumers."}},{"itemId":"2cd36f31-8206-5cad-adbc-9e79a5b50587","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1da2d8bf-6f52-5977-917e-fcf6aa696c70","sourceKey":"bank:LAG-BUA123:SMR-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a commonly cited risk of using a celebrity endorser?","options":["The celebrity is involved in a scandal that harms the brand's image","The celebrity endorses so many brands that the endorsement loses impact","The celebrity attracts attention to the advert","The celebrity overshadows the product, so viewers remember the star but not the brand"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Attracting attention is actually the main benefit of using a celebrity, not a risk. Options A, B and D are the standard risks: overshadowing the product, overexposure, and negative publicity from the celebrity's behaviour."}},{"itemId":"4a13f1b6-59fd-5de3-a5df-3581730e53da","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b04409ca-d4bf-5f33-b04a-bad42c02ef23","sourceKey":"bank:LAG-BUA123:SMR-023","parentItemId":null,"revision":1,"payload":{"prompt":"A model appears in a perfume advert only to draw attention and enhance the ad's appearance, but does not deliver any message. The model is a(n):","options":["Opinion former","Advocate channel","Indirect source","Direct source"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"An indirect source draws attention to the advert without actually delivering the message, while a direct source is a spokesperson who delivers the message or demonstrates the product. Option A is someone with formal expertise whose views are sought, which does not fit a silent model."}},{"itemId":"50e6cad7-c8cd-5656-ae0e-810fdcb2ea3e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"161dbf4d-6c4a-56dd-832a-ac6067d5c663","sourceKey":"bank:LAG-BUA123:SMR-024","parentItemId":null,"revision":1,"payload":{"prompt":"The tendency for the persuasive impact of a message from a low-credibility source to increase over time, as people forget the source but remember the message, is called the:","options":["Recency effect","Sleeper effect","Halo effect","Primacy effect"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"With the sleeper effect, people at first discount a message because the source is not credible, but later the message's influence grows as the link to the source fades. Options A and D concern where arguments are placed in a message, not changes over time due to the source."}},{"itemId":"297a2759-c37a-582c-bd2b-706b98a5b4df","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"7f0cf8ff-53ba-5389-8600-a548c44f31cb","sourceKey":"bank:LAG-BUA123:SMR-025","parentItemId":null,"revision":1,"payload":{"prompt":"A two-sided message, which presents both good and bad points about a product, is usually most effective when the audience:","options":["Already strongly favours the brand and is unlikely to hear opposing claims","Needs a simple message with only one clear conclusion","Is well educated, initially opposed, or likely to hear competitors' counter-arguments","Has no interest in the product category"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Educated or sceptical audiences, and those who will hear rival claims, find a balanced message more believable. Option A describes the situation where a one-sided message works best, and option B also favours a simple one-sided appeal."}},{"itemId":"6f1d46fc-a6e2-542c-b985-0967b6e4b152","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"e6c31103-5d6c-514d-a5d8-9a74e657e501","sourceKey":"bank:LAG-BUA123:SMR-026","parentItemId":null,"revision":1,"payload":{"prompt":"An advert for a new smartphone presents only its positive features and says nothing about any drawbacks. This is a:","options":["Comparative advertisement","Refutational appeal","Two-sided message","One-sided message"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A one-sided message mentions only the positive attributes or benefits of the product. Option C would also admit some weaknesses, and option B would raise the other side and then argue against it."}},{"itemId":"b32b9eb2-4100-5bda-84b8-d689d529e34b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"274e20d8-d363-5544-abf3-6d88a1b7e43f","sourceKey":"bank:LAG-BUA123:SMR-027","parentItemId":null,"revision":1,"payload":{"prompt":"A message that presents both sides of an issue and then argues against (refutes) the opposing viewpoint is called a:","options":["Fear appeal","Comparative advertisement","One-sided message","Refutational appeal"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"A refutational appeal raises the opposing argument and then knocks it down, which can help 'inoculate' the audience against competitors' claims. Option C ignores the other side entirely, and option B compares the brand with a named competitor."}},{"itemId":"bcf584e4-06e7-56cd-9ab9-b45319f90589","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"b39af775-677a-5646-a3bd-81825b42675c","sourceKey":"bank:LAG-BUA123:SMR-028","parentItemId":null,"revision":1,"payload":{"prompt":"Placing the strongest arguments at the beginning of a message, on the basis that information presented first is learned best, relies on the:","options":["Sleeper effect","Halo effect","Recency effect","Primacy effect"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The primacy effect says that what comes first in a message is most effectively learned and remembered. Option C says the opposite, that what comes last is remembered best, and option A concerns the fading influence of a low-credibility source over time."}},{"itemId":"a6e299f3-3e38-5c5c-b968-254ac9bac2e3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2a1ed171-5a81-5dc7-84cd-61078e688c1e","sourceKey":"bank:LAG-BUA123:SMR-029","parentItemId":null,"revision":1,"payload":{"prompt":"Leaving the conclusion of a message open for the audience to draw for themselves is usually more effective when the audience is:","options":["Less educated and not interested in the product","Highly educated and highly involved with the product","Likely to see the message only once and in passing","Facing a complex issue they may not follow without help"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Educated, involved audiences prefer to work out the conclusion themselves and may resent being told what to think. Options A, C and D describe situations where an explicit conclusion works better, because the audience may not reach the intended conclusion alone."}},{"itemId":"7f5c7581-184d-5505-b299-c80c07acd886","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6aaf8280-a9e0-51fc-97b8-8ef7f9e8197d","sourceKey":"bank:LAG-BUA123:SMR-030","parentItemId":null,"revision":1,"payload":{"prompt":"A message appeal that focuses on the product's features, quality, economy, value or performance is a(n):","options":["Fear appeal","Moral appeal","Emotional appeal","Rational (informational) appeal"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Rational appeals relate to the audience's self-interest by showing that the product delivers practical benefits such as quality, value or performance. Option C works on feelings such as love, pride or joy, and option B works on the audience's sense of right and wrong."}},{"itemId":"346d185e-6a98-5767-aa1b-263f38bbf31e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"02a35bab-7c31-57f6-89d2-638ae89fedbe","sourceKey":"bank:LAG-BUA123:SMR-031","parentItemId":null,"revision":1,"payload":{"prompt":"A milk advert shows a mother lovingly feeding her smiling baby, aiming to stir feelings of warmth and care rather than giving product facts. This uses a(n):","options":["Emotional appeal","Rational appeal","Comparative appeal","Moral appeal"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Emotional appeals try to stir positive or negative feelings that motivate purchase, here love and care. Option B would focus on facts such as vitamin content or price, and option C would compare the milk directly with a rival brand."}},{"itemId":"4d5d61bb-a4a7-503c-8a32-f09011574467","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"6e7397ab-c48f-5dc9-ac52-754134976512","sourceKey":"bank:LAG-BUA123:SMR-032","parentItemId":null,"revision":1,"payload":{"prompt":"Appeals directed to the audience's sense of what is right and proper, often used to urge people to support social causes such as a cleaner environment, are called:","options":["Rational appeals","Moral appeals","Humour appeals","Comparative appeals"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Moral appeals ask people to do the right thing, which is why they are common in campaigns for social causes. Option A focuses on practical product benefits, and option C tries to amuse the audience."}},{"itemId":"84da54ef-88d5-56cc-ad4a-1ec3f392972c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"71afdb58-9b23-5a7f-8ac5-f6a6024f35e2","sourceKey":"bank:LAG-BUA123:SMR-033","parentItemId":null,"revision":1,"payload":{"prompt":"For a fear appeal, such as a campaign against drink-driving, to work well, it should generally:","options":["Show the threat and also give a clear, easy action the audience can take to avoid it","Be aimed only at people who are not at any risk","Avoid stating what the danger actually is","Use the most shocking images possible without offering any solution"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Fear appeals tend to persuade when they combine the threat with a recommended action the audience believes it can carry out. Option D can make people block out the message because there is no way to reduce their fear, and option C removes the threat that makes it a fear appeal."}},{"itemId":"91b3f568-24ad-51a6-9867-a2a8911297c2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"44e40bce-a0b7-52a4-a1b5-8784d9b3cfd1","sourceKey":"bank:LAG-BUA123:SMR-034","parentItemId":null,"revision":1,"payload":{"prompt":"A key weakness of using humour in advertising is that:","options":["The joke can distract attention from the brand and may wear out with repetition","Humour never succeeds in attracting attention","Humour can be used only on radio","Humour always reduces how much people like the advert"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Humour is good at catching attention and creating liking, but viewers may remember the joke and forget the brand, and jokes lose their effect when repeated. Options B and D reverse humour's known strengths, and option C is untrue since humour is used in all media."}},{"itemId":"b805f98b-6a8b-549f-aa3a-25723db05b2a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d55e2f87-2f11-5350-841a-5a0ed0cfb2cc","sourceKey":"bank:LAG-BUA123:SMR-035","parentItemId":null,"revision":1,"payload":{"prompt":"An advert that directly or indirectly names a competitor and compares the brand with it on one or more attributes is called:","options":["Comparative advertising","A two-sided message","Reminder advertising","A refutational appeal"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Comparative advertising compares the advertised brand with a competitor's, either by name or by clear implication. Option D refutes an opposing argument but need not mention a rival brand, and option B admits the brand's own weaknesses rather than comparing it with a competitor."}},{"itemId":"a3d0832f-4732-5318-aeb1-447be05538a5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"84d134df-8798-590b-8cd1-019820d490b9","sourceKey":"bank:LAG-BUA123:SMR-036","parentItemId":null,"revision":1,"payload":{"prompt":"Consumers notice only some of the many adverts they are exposed to, interpret them in ways that fit what they already believe, and remember only part of them. On the receiver's side, this filtering is called:","options":["Selective perception","Encoding","The sleeper effect","Message sidedness"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Selective perception (attention, distortion and retention) explains why the receiver may not get the message the sender intended. Option C concerns source credibility over time, option D concerns the message's structure, and option B is done by the sender."}},{"itemId":"055e97e6-dfd7-5729-a5a0-5aa81df574dd","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f728fe22-d64a-53d9-afe3-81cf3ed90ae7","sourceKey":"bank:LAG-BUA123:SMR-037","parentItemId":null,"revision":1,"payload":{"prompt":"A person within a reference group who, because of special skills, knowledge, personality or other characteristics, exerts social influence on others is called a(n):","options":["Advocate channel","Opinion leader","Laggard","Opinion follower"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Opinion leaders are ordinary members of a group whose advice others seek because of their knowledge or personality. Option D is a person who receives that advice, option C is the last adopter category, and option A is company salespeople contacting buyers."}},{"itemId":"cee354d5-ddb4-5d75-818a-ca16f5820e26","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"38c6af85-984c-59fb-9c5c-f1e80153c86f","sourceKey":"bank:LAG-BUA123:SMR-038","parentItemId":null,"revision":1,"payload":{"prompt":"Opinion formers differ from opinion leaders mainly because opinion formers:","options":["Are ordinary peers with no formal position whose advice is sought informally","Are always the last group in society to adopt any new product","Hold a formal or professional position, e.g. journalists or critics, that gives their views authority","Never use the mass media to obtain information about products"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Opinion formers influence others because of their formal expertise, profession or position, while opinion leaders are informal peers within a social group. Option A describes opinion leaders, not opinion formers, and options B and D describe neither group."}},{"itemId":"feda4b4e-c405-5b27-b227-0299c4eca707","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f46a8c05-b968-577c-8ee2-328beee24a6b","sourceKey":"bank:LAG-BUA123:SMR-039","parentItemId":null,"revision":1,"payload":{"prompt":"A professional food critic, whose influence comes from her formal position, writes a weekly column in a national newspaper reviewing new restaurants. In marketing communication terms, she is best described as a(n):","options":["Laggard","Opinion former","Opinion follower","Indirect source"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Her influence comes from her professional role as a critic, which makes her an opinion former. Option C would be a reader who takes her advice, and option D is a model who draws attention in an advert without delivering a message."}},{"itemId":"1059a3bf-6a6f-564a-a3d2-7541b9bf0930","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"979126fb-0668-5011-9db9-2c8e75b3d27f","sourceKey":"bank:LAG-BUA123:SMR-040","parentItemId":null,"revision":1,"payload":{"prompt":"Tunde is not paid by any company, but friends in his estate always ask his advice before buying phones because he reads technology blogs and tries new devices early. Tunde is a(n):","options":["Advocate channel","Laggard","Opinion former","Opinion leader"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Tunde is an informal member of his social group whose advice is valued because of his interest and knowledge, which is what an opinion leader is. Option C would need a formal professional position such as a journalist, and option A is a company salesperson."}},{"itemId":"425ab4d4-929f-56c0-b852-e6eeca3905e3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c3f4e155-a9a8-588b-be00-7c781a79e7dd","sourceKey":"bank:LAG-BUA123:SMR-041","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is typically TRUE of opinion leaders?","options":["They are equally influential across all product categories","They are paid employees of the brands they recommend","They usually come from a very different social class from their followers","They tend to be more exposed to media in their area of interest than their followers"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Opinion leaders tend to follow media related to their interest closely, which is why messages often reach the wider public through them. Option C is wrong because opinion leaders are usually similar to their followers, and option A is wrong because opinion leadership tends to be specific to a product area."}},{"itemId":"f5a04e05-38bb-5366-be00-f1cc6ec01218","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d2b2e1f2-f524-5320-a750-19bfd5fe0c5a","sourceKey":"bank:LAG-BUA123:SMR-042","parentItemId":null,"revision":1,"payload":{"prompt":"The two-step flow model of communication holds that:","options":["The mass media directly and equally influence every member of the audience","A message must pass through two separate media before it reaches anyone","Information flows from consumers to the company and then to the media","Information flows from the mass media to opinion leaders, who then pass it on to the wider population"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"In the two-step flow, opinion leaders pick up information from the media and then pass it on and interpret it for others through personal influence. Option A is the one-step (direct) view of media influence, which the two-step model rejected."}},{"itemId":"8a932578-87b1-571b-9ade-bf7f42b3e78c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"3e45d351-e837-5034-afc3-00a555f4e423","sourceKey":"bank:LAG-BUA123:SMR-043","parentItemId":null,"revision":1,"payload":{"prompt":"The multi-step flow model improves on the two-step flow model by recognising that:","options":["Followers never discuss products with one another or with leaders","Opinion leaders never use the mass media to get information","Media reach both leaders and followers directly, and influence flows in several directions","Mass media influence every person directly in exactly one step"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"The multi-step model accepts that the media reach opinion leaders and followers alike, and that people influence one another in more than one direction. Option B is wrong because opinion leaders are heavy media users, and option D is the one-step view."}},{"itemId":"011d7ca9-eef0-52a0-9c67-9dbab493dcbf","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c8749643-ad1f-5ecf-b281-4ae99b7320b2","sourceKey":"bank:LAG-BUA123:SMR-044","parentItemId":null,"revision":1,"payload":{"prompt":"Marketers who apply the two-step flow idea in their communication plans often:","options":["Target opinion leaders, e.g. with free samples, so they spread the word","Avoid people who often talk about products with others","Ignore mass media because opinion leaders never use it","Direct their messages only at laggards in the market"],"correctOption":0,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"If messages pass through opinion leaders, it makes sense to reach them first and encourage them to share their views with followers. Option B works against the model, and option C is wrong because opinion leaders actually make heavy use of media in their area."}},{"itemId":"6c2444f5-0d76-5621-94a1-4da9dbc7bbb8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"47e2b676-ee09-5509-bfb9-ca6344901246","sourceKey":"bank:LAG-BUA123:SMR-045","parentItemId":null,"revision":1,"payload":{"prompt":"The correct order of the adopter categories, from the first to adopt an innovation to the last, is:","options":["Innovators, early majority, early adopters, laggards, late majority","Early adopters, innovators, early majority, late majority, laggards","Innovators, early adopters, early majority, late majority, laggards","Early majority, innovators, early adopters, late majority, laggards"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Innovators adopt first, followed by early adopters, the early majority, the late majority and finally laggards. Option B swaps the first two groups, a common slip, because innovators come before early adopters."}},{"itemId":"e7e928dd-0822-55dc-967e-6e9d689ff9a1","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a0d1f4e8-0178-53cc-aee7-24603dc944f1","sourceKey":"bank:LAG-BUA123:SMR-046","parentItemId":null,"revision":1,"payload":{"prompt":"Which adopter category is most closely associated with opinion leadership and is respected within its community?","options":["Innovators","Early adopters","Laggards","Late majority"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Early adopters are guided by respect, are often opinion leaders in their communities, and adopt new ideas early but carefully. Option A, innovators, are venturesome and try new ideas at some risk, but are often seen as too far ahead of others to be role models."}},{"itemId":"2a55926e-e635-5e2b-ac0f-6a52fd1fe15d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"13c2edb7-c1aa-5bd3-8842-d2d042f47101","sourceKey":"bank:LAG-BUA123:SMR-047","parentItemId":null,"revision":1,"payload":{"prompt":"Consumers who are tradition-bound, suspicious of change, and adopt an innovation only when it has become something of a tradition itself are called:","options":["Innovators","Late majority","Laggards","Early majority"],"correctOption":2,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Laggards are the last group to adopt and resist change. Option B, the late majority, are sceptical and adopt after most people have, but they are not as tradition-bound as laggards."}},{"itemId":"34150322-4820-5f06-84e9-b1186041a3e2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"08f3bdc0-303c-5f23-ac2d-ddbdf8d58b18","sourceKey":"bank:LAG-BUA123:SMR-048","parentItemId":null,"revision":1,"payload":{"prompt":"Mobile money services spread quickly in Nigeria partly because many users saw them as clearly better than queuing in banking halls to send money. Which characteristic affecting the rate of adoption does this illustrate?","options":["Compatibility","Relative advantage","Observability","Complexity"],"correctOption":1,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Relative advantage is the degree to which an innovation appears superior to existing products or ways of doing things. Option A is how well it fits people's values and experiences, and option D is how hard it is to understand or use."}},{"itemId":"98233ef4-2bf0-5173-b8d6-ab921cad3b47","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"65820a0e-bd37-58a7-886f-a1fba40a1b05","sourceKey":"bank:LAG-BUA123:SMR-050","parentItemId":null,"revision":1,"payload":{"prompt":"The adoption process differs from the diffusion of an innovation because adoption refers to:","options":["The spread of an innovation through a whole market over time","The flow of information from the mass media to opinion leaders","The division of buyers into innovators, early adopters and other categories","The mental process an individual goes through from first hearing about an innovation to finally adopting it"],"correctOption":3,"section":"Source, Message, Receiver, Medium and Opinion Leaders","explanation":"Adoption is about one person's journey from awareness to regular use, while diffusion describes how the innovation spreads through the whole population over time. Option A describes diffusion, option C describes adopter categories, and option B describes the two-step flow."}},{"itemId":"cd977780-06da-592c-8d9e-802d5cc53a8a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5b0c50e1-dc94-589b-b36e-58daeabc886d","sourceKey":"bank:LAG-BUA123:SOC-001","parentItemId":null,"revision":1,"payload":{"prompt":"The most important change the internet and social media brought to marketing communication is that it shifted from:","options":["A one-way monologue from firms to a two-way conversation between firms and customers","Targeted messages to messages for the whole population only","Customer-focused messages to product-focused messages","Paid communication to completely free communication for all firms"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Traditional mass media mainly let firms talk at customers, while the internet and social media let customers reply, comment and talk to each other, turning marketing into a two-way conversation. Online communication still has costs (option D), and it made targeting easier, not harder (option B)."}},{"itemId":"bd400ec3-1586-56ef-99f4-57e7c9151d4d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"9eb0978f-ce87-5c3f-9ff4-908d4afbb687","sourceKey":"bank:LAG-BUA123:SOC-002","parentItemId":null,"revision":1,"payload":{"prompt":"In 1996, Hotmail added the line 'Get your free email at Hotmail' to every email its users sent and gained millions of users within months. This is a well-known early example of:","options":["Sales promotion","Viral marketing","Personal selling","Outdoor advertising"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Viral marketing gets customers themselves to pass a message along, so it spreads rapidly from person to person; every Hotmail user who sent an email advertised the service. No salesperson was involved (option C), and no short-term incentive such as a discount was offered (option A)."}},{"itemId":"4a7ea133-0e37-5d27-ae40-2331da586bb7","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"87839d8b-cee1-51c5-8544-6b60f3581d90","sourceKey":"bank:LAG-BUA123:SOC-003","parentItemId":null,"revision":1,"payload":{"prompt":"Which platforms rose in the 2000s and changed how businesses interacted with their audiences by making marketing a two-way conversation?","options":["MySpace, Facebook and Twitter","Newspapers and magazines","Radio and television","Billboards and posters"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media platforms such as MySpace, Facebook and Twitter appeared in the 2000s and allowed brands to engage directly with customers. Radio and television (option C) became important in the 20th century, and print media (option B) are much older."}},{"itemId":"e5fc226f-0109-5e9e-9d79-b4fa181d1883","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"08b4f39d-1902-57c3-b802-fcdcae477d4d","sourceKey":"bank:LAG-BUA123:SOC-004","parentItemId":null,"revision":1,"payload":{"prompt":"Online chat rooms, discussion forums and blogs, where many people communicate with many others at the same time, are examples of which type of communication made possible by the internet?","options":["One-to-one","Many-to-many","Many-to-one","One-to-many"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Many-to-many communication lets large numbers of people exchange messages with each other, and it has grown with the internet through chat rooms, forums and blogs. Option D is a single broadcast to many, such as a TV news bulletin, and option A is a personal exchange, such as a sales negotiation."}},{"itemId":"4356c4e4-59d2-5991-bfdc-84fea1c13e4d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"fb977d70-a819-5bd4-928a-98211264ca12","sourceKey":"bank:LAG-BUA123:SOC-005","parentItemId":null,"revision":1,"payload":{"prompt":"In the internet era, consumers can easily compare prices, read reviews and publicly share their opinions about brands. This has resulted in:","options":["Firms gaining total control over what consumers hear about brands","Consumers depending only on advertising for product information","The end of the need for marketing communication","Greater consumer power and control over marketing communication"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"The internet gives consumers access to information and a public voice, which shifts power towards them. Firms now have less control over what is said about them (option A), and consumers rely on many sources besides advertising (option B)."}},{"itemId":"f0817249-5bb0-5658-abbf-8e15338fefbc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c607fe41-e52a-5b80-ab42-6d081f8ddc7f","sourceKey":"bank:LAG-BUA123:SOC-006","parentItemId":null,"revision":1,"payload":{"prompt":"Social media marketing is best defined as:","options":["Using social media platforms to engage audiences, build the brand, and drive traffic and sales","Sending printed catalogues to customers' homes","Placing adverts only on television and radio","Selling products only through face-to-face meetings in social gatherings"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media marketing uses platforms such as Facebook, Instagram, X, TikTok and LinkedIn to share content, interact with customers and promote the brand. Option D is personal selling, option C is traditional broadcast advertising, and option B is offline direct mail."}},{"itemId":"28f47eaf-672e-5e0b-bafe-776a5daafccb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"14ada9d6-a04a-5bd5-8b9b-83c0642a4857","sourceKey":"bank:LAG-BUA123:SOC-007","parentItemId":null,"revision":1,"payload":{"prompt":"User-generated content (UGC) refers to:","options":["Content such as reviews, photos and videos about a brand that is created by customers rather than by the brand","Adverts written by a firm's advertising agency","Press releases issued by a firm's public relations department","Product information printed on the package by the manufacturer"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"UGC is created by consumers themselves, for example product reviews, unboxing videos and posts using a brand's hashtag. Options B, C and D are all created or controlled by the firm or its agents."}},{"itemId":"f8458688-a8e9-5c21-a8a9-f6f5bfa8c305","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cad0c787-7dca-54dc-b4ef-2d8274971f42","sourceKey":"bank:LAG-BUA123:SOC-008","parentItemId":null,"revision":1,"payload":{"prompt":"Customers of a Lekki restaurant post their own photos and short videos of its jollof rice on Instagram and TikTok with the restaurant's hashtag, without being paid. These posts are best described as:","options":["Paid media advertising","User-generated content","Sales promotion","Personal selling"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Content created and shared voluntarily by customers about a brand is user-generated content. It is not paid media (option A) because the restaurant did not pay for the posts, and no salesperson or price incentive is involved (options D and C)."}},{"itemId":"325be646-3ba6-5d5d-b646-67696d490838","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8dc674fd-70e8-5110-991d-ae3b822df22e","sourceKey":"bank:LAG-BUA123:SOC-009","parentItemId":null,"revision":1,"payload":{"prompt":"Viral marketing is best described as:","options":["Reducing prices for a short period to attract buyers","Advertising medicines and health products","Creating content so interesting that people pass it on to others, spreading it rapidly online","Sending the same advert to customers several times a day"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Viral marketing is often called the internet version of word-of-mouth: the content is so engaging that consumers share it, so it spreads like a virus. Option B takes the word 'viral' literally, option D is simply repetition, and option A is sales promotion."}},{"itemId":"232a7ff7-49da-5c4e-8606-a59b91231979","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"1cdae3a0-e8d7-55c2-a6a2-9a0b084e359c","sourceKey":"bank:LAG-BUA123:SOC-010","parentItemId":null,"revision":1,"payload":{"prompt":"Word-of-mouth (WOM) communication refers to:","options":["Formal sales presentations made by a firm's sales force","Paid announcements read by radio presenters","Informal person-to-person communication among consumers about products, services and brands","Messages printed on a product's label"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Word-of-mouth is when customers share their experiences and opinions about products with friends, family and peers. Paid announcements (option B) are advertising, and sales presentations (option A) are personal selling, both controlled by the firm."}},{"itemId":"32a880f3-81ec-55cc-83cf-588e3fd6bea6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4dc36fd8-e842-575b-afea-2935ec9a590a","sourceKey":"bank:LAG-BUA123:SOC-011","parentItemId":null,"revision":1,"payload":{"prompt":"Why is word-of-mouth usually seen as more credible than advertising?","options":["It is always more detailed than advertising","It comes from people who are seen as independent of the firm and not paid to promote the product","It is controlled and checked by the company before it is shared","It always reaches more people than advertising"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Consumers trust friends, family and fellow customers because they are not seen as having a commercial interest in the sale. WOM is not controlled by the firm (option C), and it does not always reach more people than advertising (option D)."}},{"itemId":"6668df8c-0c00-566a-b486-9bb1eab1a45e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5d90eb09-b927-52c6-82f5-4d361776a3b2","sourceKey":"bank:LAG-BUA123:SOC-012","parentItemId":null,"revision":1,"payload":{"prompt":"Electronic word-of-mouth (eWOM) is best defined as:","options":["Banner adverts placed by a firm on websites","Positive or negative statements by potential, actual or former customers about a product or company, made available to many people through the internet","Phone calls between a salesperson and a customer","Emails sent by a company to its mailing list"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"eWOM is word-of-mouth that happens online, through reviews, posts, comments and forums, and it can be seen by many people. Options D and A are messages controlled and sent by the firm, and option C is personal selling."}},{"itemId":"2fcb1afe-9a16-51c9-ab82-d28f49c6bd9a","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"28a80c92-9007-5ea4-b646-a6d89d911da5","sourceKey":"bank:LAG-BUA123:SOC-013","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with traditional word-of-mouth, electronic word-of-mouth (eWOM):","options":["Disappears as soon as the conversation ends","Takes place only face to face between close friends","Can reach many more people faster and stays available online for a long time","Can only be positive about a brand"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Traditional WOM is usually spoken between a few people and is quickly forgotten, while eWOM can spread to thousands, even strangers, within hours and remains searchable. Options B and A describe traditional WOM, and eWOM can be positive or negative (option D)."}},{"itemId":"b5cb6066-871c-5458-ad0f-4ca06c7b2230","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"f6cc2c9a-a51b-54cb-a75f-fb00ef5f7807","sourceKey":"bank:LAG-BUA123:SOC-014","parentItemId":null,"revision":1,"payload":{"prompt":"Before buying a blender on an online store, Amaka reads 40 customer reviews and star ratings posted by previous buyers. These reviews are an example of:","options":["Personal selling","Direct marketing","Publicity","Electronic word-of-mouth (eWOM)"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Reviews and ratings posted online by customers are a common form of eWOM, since they are consumers' opinions shared through the internet. Option C, publicity, is unpaid coverage in the news media, and option B is personalised communication sent by the firm to individuals."}},{"itemId":"d6a4e21f-a9ea-5673-9d5b-273a4f8c09b4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"95e53180-11a4-57f5-b26f-45022d18e485","sourceKey":"bank:LAG-BUA123:SOC-015","parentItemId":null,"revision":1,"payload":{"prompt":"A customer posts a video complaint on X about poor service at a bank branch in Ikeja. Within a day it is shared thousands of times and the bank's name is trending. This mainly shows which risk of social media?","options":["Negative eWOM can spread quickly and damage reputation","High printing costs","Slow delivery of messages","Lack of any audience on social media"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media lets dissatisfied customers reach huge audiences very quickly, so one complaint can become a reputation problem. Social media has no printing costs (option B), and the fast spread shows a large audience (option D) and speedy delivery (option C)."}},{"itemId":"32fc0220-a5e5-5316-9809-8b9aef05af62","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"2bb5c08e-ab02-511f-9894-f859899239c6","sourceKey":"bank:LAG-BUA123:SOC-016","parentItemId":null,"revision":1,"payload":{"prompt":"A social media influencer is best described as:","options":["A person who has built a following online and can affect the opinions and purchases of that audience","Any customer who buys a product online","A government official who regulates advertising","A company's head of production"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Influencers are content creators with an engaged online following whose recommendations can shape their followers' attitudes and buying decisions. Simply buying online (option B) does not make someone an influencer, and options D and C are roles that do not depend on an online following."}},{"itemId":"75217a21-fb2e-5d93-8c6f-0be1a86cc885","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"623eaa7a-eef6-5744-b639-b8dafd02ffc4","sourceKey":"bank:LAG-BUA123:SOC-017","parentItemId":null,"revision":1,"payload":{"prompt":"Compared with celebrity (mega) influencers, micro-influencers typically have:","options":["Audiences that never interact with their posts","No followers at all","Much larger audiences and much higher fees","Smaller, more specialised audiences and often higher engagement and trust"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Micro-influencers have smaller, niche followings, and their followers often see them as relatable, so engagement and trust tend to be high. Option C describes mega or celebrity influencers, and options B and A contradict the idea of an influencer."}},{"itemId":"026c3978-df80-5fde-a04e-50d453f5cf74","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"530907dc-34f8-5fd0-970e-405cb3c406cf","sourceKey":"bank:LAG-BUA123:SOC-018","parentItemId":null,"revision":1,"payload":{"prompt":"A small Abuja skincare brand has N200,000 to spend on influencers. It wants believable recommendations to women who follow skincare content closely. The most suitable approach is to:","options":["Spend the entire budget on a TV commercial","Avoid social media and print flyers only","Pay one celebrity musician for a single post","Work with several micro-influencers who focus on skincare"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Micro-influencers in a niche such as skincare are affordable, trusted by their followers and reach exactly the target audience. A top celebrity (option C) would probably cost more than the budget and reach many people outside the target, and option A is not influencer marketing at all."}},{"itemId":"6e07b084-7b43-5189-bb63-f2e1651b4800","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"4daf6f30-9487-5a65-8bf7-defff819e0e1","sourceKey":"bank:LAG-BUA123:SOC-019","parentItemId":null,"revision":1,"payload":{"prompt":"Why should an influencer clearly disclose when a post is a paid partnership with a brand?","options":["So that the brand can avoid paying the influencer","Because paid posts cannot contain pictures","So that followers know it is advertising and are not misled","So that the post reaches fewer people"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Disclosure (for example marking a post as an ad or paid partnership) is about honesty: followers have a right to know when content is sponsored. Hidden sponsorship can mislead consumers and damage trust in both the influencer and the brand. Options D, B and A are not reasons for disclosure."}},{"itemId":"419344d3-2019-5b1b-9fb0-e0b4390b7266","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"85f1394b-bb69-516c-8f55-42b6566b2c20","sourceKey":"bank:LAG-BUA123:SOC-020","parentItemId":null,"revision":1,"payload":{"prompt":"In the paid-owned-earned media framework, 'earned media' refers to:","options":["The salary earned by a firm's marketing staff","Publicity and exposure gained free through customers, fans and the press sharing or talking about the brand","Channels the firm controls, such as its own website and social media pages","Media space a firm buys, such as sponsored posts"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Earned media is exposure the brand earns rather than pays for, such as shares, reviews, word-of-mouth and news coverage. Option D is paid media and option C is owned media."}},{"itemId":"ec55642f-a65b-5ac6-b555-a65ec63038df","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"74b6f920-4df9-5d24-9c97-f0b350b09f77","sourceKey":"bank:LAG-BUA123:SOC-021","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of owned media?","options":["A sponsored post bought on Facebook","A newspaper story about the company","A company's official website and Instagram page","A customer's review on a blog"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Owned media are channels the firm itself controls, such as its website, app and official social media accounts. Option A is paid media, while options D and B are earned media because the firm did not create or pay for them."}},{"itemId":"52fc0520-b76d-5598-9c85-35405c19c59b","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"73c86c4c-58a0-5f7e-a9c2-36f5bd2fdd02","sourceKey":"bank:LAG-BUA123:SOC-022","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is an example of paid media?","options":["A free news story about a product launch","Customers sharing a brand's video for free","A boosted (sponsored) Instagram post","A firm's own blog"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Paid media is exposure the firm pays for, such as boosted posts, search ads and display ads. Option D is owned media, and options B and A are earned media."}},{"itemId":"6d8f32e8-bd2a-5b2f-8c24-038c65bbcac0","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"31bf854b-a523-57be-bd72-9d3f91f6b4ef","sourceKey":"bank:LAG-BUA123:SOC-023","parentItemId":null,"revision":1,"payload":{"prompt":"After many customers praised a new Lagos fintech app on social media, a national newspaper wrote a free feature story about it. The newspaper story is best classified as:","options":["Owned media","Personal selling","Earned media","Paid media"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"The fintech did not pay for the story or control the newspaper, so the coverage is earned media. Option D would apply only if the firm had bought the space, and option A covers the firm's own channels such as its website."}},{"itemId":"1bac3c12-0b87-517a-97ed-9c5bbd5ee055","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"46440b60-ad24-5bb0-92c6-ad112eb996b3","sourceKey":"bank:LAG-BUA123:SOC-024","parentItemId":null,"revision":1,"payload":{"prompt":"Buzz marketing involves:","options":["Cutting prices temporarily to clear stock","Getting opinion leaders and early users talking about a product so that excitement spreads to others","Sending catalogues to a mailing list","Running loud adverts at a high volume on radio"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Buzz marketing deliberately creates excitement by involving opinion leaders or enthusiastic customers who then spread the word in their communities. Option D takes 'buzz' literally, option A is sales promotion, and option C is direct marketing."}},{"itemId":"40c1a3d8-1610-5764-8f2a-2be53a4d1d16","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8144a19d-3adf-5f27-bc75-a7734d13bf70","sourceKey":"bank:LAG-BUA123:SOC-025","parentItemId":null,"revision":1,"payload":{"prompt":"Deliberately giving a new product or piece of content to selected well-connected people first, so that they will share it with their networks, is called:","options":["Encoding","Rebating","Seeding","Segmentation"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Seeding places content or products with chosen people who are likely to pass them on, and it is commonly used to start viral and word-of-mouth campaigns. Option D is dividing a market into groups, and option B is a sales promotion refund."}},{"itemId":"ab255856-075b-52a3-a76a-82ada7d77862","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"07ab404d-a5db-5eb9-bf19-946f22877798","sourceKey":"bank:LAG-BUA123:SOC-026","parentItemId":null,"revision":1,"payload":{"prompt":"Social listening refers to:","options":["Holding telephone interviews with job applicants","Listening to radio adverts on a smartphone","Playing music in the background of social media videos","Monitoring online conversations to learn what people are saying about a brand, its competitors and its industry"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social listening means tracking mentions, comments and hashtags across social media and the web to understand opinions and spot problems or opportunities early. Options C, B and A involve sound or listening but have nothing to do with tracking online conversations."}},{"itemId":"8ccfc8ad-f15e-56ca-b43b-7a6118faffce","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"16aec43e-35f0-5d33-9a58-76a9ac9687cd","sourceKey":"bank:LAG-BUA123:SOC-027","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a measure of engagement on social media?","options":["The firm's annual electricity bill","The number of staff in the finance department","The size of the firm's office","The number of likes, comments and shares on a post"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Engagement measures how actively people interact with content, through likes, comments, shares and saves. Options C, B and A are internal business facts that say nothing about audience interaction."}},{"itemId":"d6a4a95f-9a73-5407-a477-d09f5ac4490c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"85d978f9-c588-52e6-9925-8d6d7bd98382","sourceKey":"bank:LAG-BUA123:SOC-028","parentItemId":null,"revision":1,"payload":{"prompt":"On social media, how does 'reach' differ from 'impressions'?","options":["Reach counts only shares, while impressions counts only comments","Reach and impressions always give exactly the same figure","Reach is the number of times content was displayed, while impressions is the number of different people who saw it","Reach is the number of different people who saw the content, while impressions is the total number of times it was displayed"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Reach counts unique viewers, while impressions count every display, so one person seeing a post three times adds one to reach and three to impressions. Option C reverses the two terms, and option B is wrong because impressions are usually higher than reach."}},{"itemId":"5bc0f825-3b70-57d7-9fa4-b467e920fc04","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"dbdda7d0-7383-5636-af55-fc8c1d31f9e0","sourceKey":"bank:LAG-BUA123:SOC-029","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key advantage of social media for marketing communication?","options":["It guarantees that every customer will say only good things","It allows precise targeting of audiences at relatively low cost","It works only for very large companies","It removes the need for any marketing planning"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media lets firms target people by location, interests and demographics, often for far less than traditional mass media. It does not control what customers say (option A), still needs planning (option D), and is widely used by small businesses (option C)."}},{"itemId":"e6c02ce7-db2b-51c5-a771-7d36fa8d6a12","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"a20630e4-0500-5e88-af97-784ca622d889","sourceKey":"bank:LAG-BUA123:SOC-030","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT an advantage of social media marketing?","options":["Ability to measure responses such as clicks and shares","Quick, real-time feedback","Direct two-way interaction with customers","Full control over what customers say about the brand"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"On social media customers say what they like, so firms lose some control over the conversation; this is a risk, not an advantage. Two-way interaction (option C), real-time feedback (option B) and measurability (option A) are genuine advantages."}},{"itemId":"73b6f96c-c977-5aeb-90c7-842d533275f4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"cf2c2b9c-5e90-51b8-809d-209b9e305aa2","sourceKey":"bank:LAG-BUA123:SOC-031","parentItemId":null,"revision":1,"payload":{"prompt":"A major risk for brands using social media is that:","options":["They have less control over the message, because customers can comment, share and change its meaning","Their messages can never reach young people","Customers cannot respond to brand posts","Social media does not allow pictures or videos"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Once a brand posts content, customers can reply, criticise, remix and share it, so the final meaning is shaped by the audience as well as the brand. Social media is popular with young people (option B), supports pictures and video (option D), and is built for customer responses (option C)."}},{"itemId":"1cbf6c0b-0dd0-56a7-91ef-a137ffa717fd","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"23c87bf6-5b74-5808-ac44-49d8af0f4b4f","sourceKey":"bank:LAG-BUA123:SOC-032","parentItemId":null,"revision":1,"payload":{"prompt":"Creating fake reviews or fake 'ordinary customer' accounts to make it look as if there is genuine public support for a product is known as:","options":["Seeding","Astroturfing","Social listening","Owned media"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Astroturfing is a deceptive practice that disguises paid or company-made messages as spontaneous grassroots opinion. Seeding (option A) openly gives content to real people to share, and social listening (option C) is monitoring conversations, not faking them."}},{"itemId":"d39efa79-5c54-5383-a159-b92db11e1aa6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"77a22761-a11a-5738-8a02-b93f3c088309","sourceKey":"bank:LAG-BUA123:SOC-033","parentItemId":null,"revision":1,"payload":{"prompt":"A brand launches a hashtag inviting customers to share happy memories with its product. Instead, many people use the hashtag to post complaints about poor quality. This illustrates:","options":["Hashtag hijacking, a risk of losing control of a social media campaign","Sales promotion through coupons","Use of owned media to control the message","Successful seeding of positive content"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"When users take over a brand's hashtag to push their own, often negative, messages, the campaign is said to be hijacked, which shows how little control brands have on social media. Options D and C wrongly suggest the brand kept control, and option B involves no incentive."}},{"itemId":"80696750-9699-53e3-94a0-64fe3d88c1e8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8b328306-dea5-5980-a01c-0446b0877af1","sourceKey":"bank:LAG-BUA123:SOC-034","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos bakery posts two new cake flavours on Instagram in the morning. By evening, hundreds of comments show customers prefer one flavour, so the bakery decides to produce more of it. This shows which advantage of social media?","options":["Real-time customer feedback","Higher printing costs","One-way communication","Complete control over customer opinions"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Social media gives firms quick feedback from customers, which they can use to adjust products and messages. Option C is wrong because the comments show two-way communication, and option D is wrong because customers freely gave their own opinions."}},{"itemId":"be1bace8-9542-55ec-b5c6-04f181e3e21c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"69c08847-e3ae-56aa-9668-9554446e7867","sourceKey":"bank:LAG-BUA123:SOC-035","parentItemId":null,"revision":1,"payload":{"prompt":"The ongoing activity of building and managing relationships with a brand's online followers, such as replying to comments and answering questions, is called:","options":["Community management","Publicity","Market segmentation","Personal selling"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Community management covers the daily interaction a brand has with its online audience, such as replying, moderating discussions and building loyalty. Option D is face-to-face selling by a sales force, and option B is unpaid coverage in the news media."}},{"itemId":"f1d98658-a57c-5856-84c9-3feb4c19095f","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"41ef0709-ff1a-56bd-9574-dc5073e3a9d3","sourceKey":"bank:LAG-BUA123:SOC-036","parentItemId":null,"revision":1,"payload":{"prompt":"Loyal customers who voluntarily recommend a brand to others and defend it online, without being paid, are called:","options":["Brand advocates","Wholesalers","Paid influencers","Competitors"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Brand advocates are satisfied customers who freely promote the brand, and their recommendations are a major driver of positive word-of-mouth. Paid influencers (option C) are compensated, and wholesalers (option B) are channel members."}},{"itemId":"a4158ffe-ab50-5d3b-aba6-26dfd0cdf040","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"23225c8c-ccb1-50d5-b116-7627fc83a776","sourceKey":"bank:LAG-BUA123:SOC-037","parentItemId":null,"revision":1,"payload":{"prompt":"A Nigerian payment app gives existing users N500 for every friend they get to sign up using their personal code. This programme is mainly a way of:","options":["Organising personal selling by the sales force","Encouraging word-of-mouth through referral marketing","Issuing a press release","Running a television advertising campaign"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"A referral programme rewards existing customers for recommending the product, which deliberately stimulates word-of-mouth. No TV adverts (option D), press release (option C) or sales force (option A) are involved."}},{"itemId":"c9b496f5-2113-5fa1-ba23-79cd7bec19af","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"94a5131f-1ec1-5ad8-8b8b-81f25538c692","sourceKey":"bank:LAG-BUA123:SOC-038","parentItemId":null,"revision":1,"payload":{"prompt":"'Organic reach' on social media refers to:","options":["The number of people reached by paid adverts only","The number of farm products advertised online","The number of people who see a brand's content without the brand paying to promote it","The number of staff who manage the brand's pages"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Organic reach is free exposure from followers seeing and sharing a post, while paid reach comes from boosted posts or ads. Option A is paid reach, and option B takes 'organic' literally."}},{"itemId":"193a385a-e9c0-57af-91a9-798f05c27d89","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"af29dd7b-3697-583c-877c-bd84a3d3e365","sourceKey":"bank:LAG-BUA123:SOC-039","parentItemId":null,"revision":1,"payload":{"prompt":"Many brands find that only a small share of their followers see their unpaid posts, because platforms decide what appears in users' feeds. As a result, brands often:","options":["Stop creating content altogether","Pay to boost posts so they reach more people","Delete all their social media accounts","Rely only on the grapevine within the company"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Platform algorithms limit how many followers see unpaid posts, so brands combine organic content with paid promotion to extend reach. Options C and A would remove the brand from social media entirely, and the grapevine (option D) is internal to an organisation."}},{"itemId":"40d105b9-974f-5898-8ac5-8ad9f4a422d3","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8a2f6949-a374-5a3a-9048-3856910e12ea","sourceKey":"bank:LAG-BUA123:SOC-040","parentItemId":null,"revision":1,"payload":{"prompt":"Content marketing is best described as:","options":["Copying competitors' adverts word for word","Selling the content of a warehouse at a discount","Printing content on product packages only","Creating and sharing valuable, relevant content, such as articles, videos and tips, to attract and keep a target audience"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Content marketing attracts customers by giving them useful or entertaining content rather than direct sales messages, for example a bank sharing money-saving tips. Option A is unethical copying, and option B confuses 'content' with stock."}},{"itemId":"a6654b8e-dd75-565e-8c45-da1b1b865de8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"11b8a817-8e4d-5e49-9931-75d3489d25ab","sourceKey":"bank:LAG-BUA123:SOC-041","parentItemId":null,"revision":1,"payload":{"prompt":"In the internet era, consumers increasingly search for brand information, follow pages and choose what content to watch. This means marketing communication has moved more towards:","options":["Communication without any channels","Communication only through door-to-door selling","Push communication only, where consumers cannot avoid messages","Pull communication, where consumers seek out the messages they want"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"With search engines and social media, consumers pull information when they want it, so brands must create content people choose to find and follow. Option C describes interruptive mass advertising, which consumers can increasingly skip or block."}},{"itemId":"922ac7aa-98c5-50a7-a868-c81d275bb4ff","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"20b4b3f8-2734-543f-8eea-7c260cb88a5c","sourceKey":"bank:LAG-BUA123:SOC-042","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following features makes content most likely to go viral?","options":["It is very long and full of technical details","It avoids any emotion and humour","It is shown only once to a small group","It is emotional, entertaining or useful enough that people want to share it"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"People share content that makes them laugh, feel strongly or learn something useful, which is what drives viral spread. Long technical content (option A), very limited exposure (option C) and emotionless content (option B) give people little reason to pass it on."}},{"itemId":"2ff46bee-65f2-5f50-90bf-ef536ba5b5ad","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"43222468-d5ab-56a1-8efc-3c3b9e64bde8","sourceKey":"bank:LAG-BUA123:SOC-043","parentItemId":null,"revision":1,"payload":{"prompt":"A key limitation of viral marketing is that:","options":["It only works for government agencies","It always costs more than television advertising","Firms cannot guarantee that the content will spread or control how people interpret it","It cannot be used on the internet"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Whether content goes viral depends on consumers choosing to share it, so results are unpredictable and the message may be changed or criticised as it spreads. Viral campaigns are often cheap (option B), are mainly internet-based (option D), and are used by all kinds of organisations (option A)."}},{"itemId":"55732413-1087-5021-aeb2-2f40a3a12bfc","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"5adefc13-7db9-56ac-affe-535089f0ce7c","sourceKey":"bank:LAG-BUA123:SOC-044","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is a key advantage of internet-based marketing communication over traditional mass media?","options":["Responses such as clicks, views and shares can be measured quickly and accurately","It never requires any creative ideas","It removes all competition among firms","It reaches only people without phones"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Online channels record actions such as clicks, views, shares and purchases, so firms can measure results and adjust campaigns quickly, which is harder with TV or print. Options B, D and C are untrue of internet communication."}},{"itemId":"328058d9-b0ff-52f8-955a-9b9ffabf1153","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c9c2bd7d-d1f9-5573-9181-88b2d527d977","sourceKey":"bank:LAG-BUA123:SOC-045","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a form of electronic word-of-mouth (eWOM)?","options":["A tweet recommending a restaurant","A customer's product review on an online store","A company's television commercial","A forum post complaining about a phone brand"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"eWOM is created by consumers and shared online, while a TV commercial is paid advertising created by the company. Options B, A and D are all consumer opinions shared over the internet."}},{"itemId":"3f73333d-1dad-5ee7-b355-1c004d34e6f2","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"8a07e563-f85a-52d0-8476-09e5000f32e9","sourceKey":"bank:LAG-BUA123:SOC-046","parentItemId":null,"revision":1,"payload":{"prompt":"Social media influencers are often seen as an online version of which traditional marketing communication concept?","options":["Wholesalers","Opinion leaders","Market regulators","Retail sales assistants"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Opinion leaders are people whose advice and views influence others in their group, and influencers play this role online for their followers. Wholesalers (option A) are channel intermediaries, and retail sales assistants (option D) are employees doing personal selling."}},{"itemId":"ba4998eb-159a-5f09-ad79-925f93efb50c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"c4f0699e-d728-5b29-b4d1-7bd4448b348f","sourceKey":"bank:LAG-BUA123:SOC-047","parentItemId":null,"revision":1,"payload":{"prompt":"When a negative post about a company starts spreading on social media, the generally recommended response is to:","options":["Argue aggressively with the customers in public","Ignore it completely and hope it disappears","Respond quickly, honestly and politely, and address the problem openly","Delete every critical comment and block the customers"],"correctOption":2,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Fast, transparent and respectful responses show customers that the firm takes complaints seriously and can limit damage to reputation. Ignoring the issue (option B), deleting comments (option D) or arguing publicly (option A) usually makes the situation worse."}},{"itemId":"0e5402a1-5e10-52f9-bd8b-4c9ef018e65e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"198d5d0a-66e0-5297-b7ba-2b0b33553fdf","sourceKey":"bank:LAG-BUA123:SOC-048","parentItemId":null,"revision":1,"payload":{"prompt":"Interactivity, as a key feature of internet marketing communication, means:","options":["Messages are sent only by firms and never answered","Firms and consumers can communicate with each other in both directions and respond to each other's messages","Communication takes place only through printed media","Consumers can watch adverts only at a fixed time"],"correctOption":1,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Interactivity allows a two-way exchange: customers can comment, ask, rate and share, and brands can respond, often in real time. Option A describes one-way communication, and options D and C describe traditional media."}},{"itemId":"7dc846b1-67bd-5d20-a2e9-a677f6729dc6","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"d37f7194-46d4-5006-b911-bfb71bb1f176","sourceKey":"bank:LAG-BUA123:SOC-049","parentItemId":null,"revision":1,"payload":{"prompt":"Platforms mainly used for sharing photos and videos, such as YouTube, Instagram and TikTok, are best classified as:","options":["Media-sharing networks","Search engines","Online banking platforms","Professional networking sites"],"correctOption":0,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Media-sharing networks are built around posting and viewing photos and videos, which makes them powerful for visual brand content. A professional networking site (option D) is built around careers and business contacts, as LinkedIn is, and search engines (option B) help users find information across the web."}},{"itemId":"eaddcaa6-4e97-5504-91a3-ed28f436cc84","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"cbt_question","questionId":"04315a4f-b3ec-5988-bc99-3ae07a63e016","sourceKey":"bank:LAG-BUA123:SOC-050","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT a risk of using social media for marketing communication?","options":["Negative comments spreading quickly to many people","Fake reviews misleading customers","Influencer scandals damaging the brand's image","Reaching large audiences at relatively low cost"],"correctOption":3,"section":"MarCom in the Internet Era, Social Media and Word-of-Mouth","explanation":"Reaching large audiences cheaply is one of the main benefits of social media, not a risk. Fast-spreading negative comments (option A), scandals involving influencers linked to the brand (option C) and fake reviews (option B) are all genuine risks firms must manage."}}]$expected_content$::jsonb,
  'marketing-communication: cbt_question published payload and identity match source');
set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('ced55987-74eb-5998-929a-c1d5275c5a3b')
  where kind = 'theory_question') = $expected_content$[{"itemId":"b1e247aa-afc5-562a-bdb7-676783d6166e","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"State the five conditions for an exchange to take place and explain which of them shows why marketing communication is needed."}},{"itemId":"375505a3-1862-516c-b36b-c37951d4c922","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"A Lagos snack maker had sales of ₦250 million last year and forecasts ₦300 million this year. It budgets 3% of sales for promotion. (a) Find the budget using past sales and using forecast sales. (b) If rivals together spend ₦36 million, what is the firm's share of voice using the forecast-based budget?"}},{"itemId":"922c23bb-5130-582c-894f-f17688cfd613","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"A drinks firm compares two options. A radio campaign costs ₦2,400,000 and reaches 1,600,000 listeners. A sales team costs ₦1,800,000 and makes 300 calls on supermarket buyers. Calculate the cost per contact of each, the radio CPM, and state which tool suits building awareness and which suits closing orders."}},{"itemId":"fae777aa-140e-58e7-bab6-c1817b21c519","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"Name the three categories of source characteristics and state the process through which each influences the receiver, with one example each."}},{"itemId":"c9a5202d-1616-506e-a213-b4b275bba75d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"Using a Nigerian example, explain the elements of the communication process and show two points at which noise can occur."}},{"itemId":"0227e2a3-f51d-5204-8306-be19cdc71765","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"A brand pays ₦40,000 to boost a TikTok video. It reaches 8,000 people, each seeing it 3 times on average, and gets 360 likes, comments and shares. Find (a) impressions, (b) engagement rate by reach, (c) cost per 1,000 impressions. State whether the boost is paid, owned or earned media."}},{"itemId":"7823aa23-a370-533f-9be6-b129116c5fc4","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"Bukola buys bread worth ₦3,500 from a neighbourhood bakery twice a week, every week of the year, and is expected to stay a customer for 4 years. The bakery's profit margin is 25%. Its customer base fell from 16,000 to 15,200 over the year with no new customers counted. Calculate (a) Bukola's CLV in revenue and profit terms and (b) the bakery's churn and retention rates."}},{"itemId":"5480d808-f6e5-5e9c-84d9-5734705f269c","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"A Yaba phone-accessories shop runs a pay-per-click campaign. Its ad gets 60,000 impressions and 900 clicks at ₦60 per click, and 27 shoppers buy, each spending ₦6,000. Find the CTR, total spend, conversion rate, cost per sale, CPM and the revenue earned."}}]$expected_content$::jsonb,
  'marketing-communication: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('ced55987-74eb-5998-929a-c1d5275c5a3b')
  where kind = 'model_answer') = $expected_content$[{"itemId":"7a40c8bc-c8fa-5d11-b356-528cdcf8bfde","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:1","parentItemId":"b1e247aa-afc5-562a-bdb7-676783d6166e","revision":1,"payload":{"body":"(1) at least two parties; (2) each has something that might be of value to the other; (3) each can communicate and deliver what it offers; (4) each is free to accept or reject the offer; (5) each trusts/respects the other enough to take the exchange seriously. Condition 3 shows the need for marketing communication: without a way to tell buyers what is on offer, no exchange (and so no transaction) can happen. MarCom fills this gap by generating awareness, fostering trust and driving purchase intent."}},{"itemId":"d9d24ae4-2371-5fa4-9822-1c1def9c5b17","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:2","parentItemId":"375505a3-1862-516c-b36b-c37951d4c922","revision":1,"payload":{"body":"• (a) Past sales: 0.03 x ₦250,000,000 = ₦7,500,000. Forecast sales: 0.03 x ₦300,000,000 = ₦9,000,000.\n• (b) Total category spend = ₦9m + ₦36m = ₦45m. SOV = 9 / 45 x 100 = 20%."}},{"itemId":"9643ba11-20f5-5d0e-8d2f-579d7c03846d","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:3","parentItemId":"922c23bb-5130-582c-894f-f17688cfd613","revision":1,"payload":{"body":"• Radio cost per contact = ₦2,400,000 ÷ 1,600,000 = ₦1.50 per listener.\n• Radio CPM = ₦1.50 × 1,000 = ₦1,500 per thousand listeners.\n• Sales team cost per contact = ₦1,800,000 ÷ 300 = ₦6,000 per call.\n• Each sales call costs ₦6,000 ÷ ₦1.50 = 4,000 times a radio contact.\n• Radio (advertising) suits awareness: wide reach at low cost per contact. The sales team (personal selling) suits closing orders with supermarket buyers: two-way, tailored, able to negotiate. Selling to supermarkets so they stock the drink is also a push approach."}},{"itemId":"8122bdb5-3e5e-5946-b9b6-e2c429b3e764","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:4","parentItemId":"fae777aa-140e-58e7-bab6-c1817b21c519","revision":1,"payload":{"body":"1. Credibility (expertise and trustworthiness) works through internalisation: the receiver accepts the view because they believe it is accurate. Example: a dentist recommending a toothpaste.\n2. Attractiveness (similarity, familiarity, likability) works through identification: the receiver wants to relate to or be like the source. Example: an ordinary Lagos mother praising a detergent.\n3. Power (ability to reward or punish) works through compliance: the receiver goes along to gain a reward or avoid punishment. Example: a manager instructing staff; rarely usable in mass advertising because advertisers cannot reward, punish or monitor consumers."}},{"itemId":"6e658aae-c226-5693-a281-87d21f4ee5f8","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:5","parentItemId":"c9a5202d-1616-506e-a213-b4b275bba75d","revision":1,"payload":{"body":"1. Sender: MTN wants subscribers to buy a new data bundle.\n2. Encoding: its team turns the idea into an SMS: \"Get 1.5GB for ₦1,000. Reply YES.\"\n3. Message: the words and figures in the SMS.\n4. Channel: the SMS network.\n5. Receiver and decoding: a subscriber reads the SMS and understands the offer.\n6. Response and feedback: she decides to buy (response) and replies \"YES\" (feedback, because it returns to MTN).\n7. Noise, point 1 (channel): network failure delays or garbles the SMS (physical noise).\n8. Noise, point 2 (receiver): she receives dozens of promotional SMSs that day and ignores this one (information overload), or does not understand an abbreviation used (semantic).\n9. Close by stating that the message works best when the fields of experience of MTN and the subscriber overlap and when feedback is used to refine later messages."}},{"itemId":"bb2a2722-8f33-532c-b0f9-549f32919a49","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:6","parentItemId":"0227e2a3-f51d-5204-8306-be19cdc71765","revision":1,"payload":{"body":"• (a) Impressions = reach × frequency = 8,000 × 3 = 24,000.\n• (b) Engagement rate = 360 ÷ 8,000 × 100 = 4.5%.\n• (c) CPM = (₦40,000 ÷ 24,000) × 1,000 = ₦1,666.67 (rounded to the nearest kobo).\n• The boost is paid media; any free shares it triggers are earned media."}},{"itemId":"0cb00211-f452-5f12-9887-e152ea190cb5","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:7","parentItemId":"7823aa23-a370-533f-9be6-b129116c5fc4","revision":1,"payload":{"body":"• (a) Purchases per year = 2 x 52 = 104. Spend per year = ₦3,500 x 104 = ₦364,000. CLV (revenue) = ₦364,000 x 4 = ₦1,456,000. CLV (profit) = ₦1,456,000 x 0.25 = ₦364,000.\n• (b) Customers lost = 16,000 - 15,200 = 800. Churn rate = 800 / 16,000 x 100 = 5%. Retention rate = 100 - 5 = 95%.\n• Interpretation: losing Bukola would cost the bakery ₦364,000 of profit, so communication that keeps her (friendly dialogue, a loyalty card, remembering her order) is worth far more than one sale."}},{"itemId":"260e47ed-d5e1-5d5a-991d-56ea0cef1bbb","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","kind":"model_answer","questionId":null,"sourceKey":"guide-answer:8","parentItemId":"5480d808-f6e5-5e9c-84d9-5734705f269c","revision":1,"payload":{"body":"• CTR = 900 / 60,000 x 100 = 1.5%\n• Total spend = 900 x ₦60 = ₦54,000\n• Conversion rate = 27 / 900 x 100 = 3%\n• Cost per sale = ₦54,000 / 27 = ₦2,000\n• CPM = ₦54,000 / 60,000 x 1,000 = ₦900\n• Revenue = 27 x ₦6,000 = ₦162,000, which is 3 times the ad spend (₦108,000 more than the spend)."}}]$expected_content$::jsonb,
  'marketing-communication: model_answer published payload and identity match source');
