  where kind = 'theory_question') = $expected_content$[{"itemId":"e310cac9-bb61-5215-81d6-0a503d9c8621","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:1","parentItemId":null,"revision":1,"payload":{"prompt":"A firm expects profits of ₦8m, ₦9m and ₦10m at the end of years 1, 2 and 3. Using a 12% discount rate (compounded annually), find the value of the firm to 2 decimal places."}},{"itemId":"05c9ca48-cb8f-5ac6-a10d-bd84f49d7fe2","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:2","parentItemId":null,"revision":1,"payload":{"prompt":"Funke earns revenue of ₦10,000,000 from her catering firm. Explicit costs are ₦6,500,000. She gave up a salary of ₦1,500,000 and put in ₦4,000,000 of her own savings that could earn 12% a year. Find her accounting profit and economic profit."}},{"itemId":"4bd3c121-03a7-5136-8083-ef24dea93d88","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:3","parentItemId":null,"revision":1,"payload":{"prompt":"A Surulere kiosk cuts the price of a chilled drink from ₦500 to ₦400, and daily sales rise from 200 to 300 bottles. Using the midpoint method, find the price elasticity of demand, classify it, and state what happened to total revenue."}},{"itemId":"ef914fd9-9610-5ce7-b1de-3f701eff4930","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:4","parentItemId":null,"revision":1,"payload":{"prompt":"A Kano rice seller sold 60, 64, 70, 66 and 72 bags in weeks 1 to 5. Find the 4-week simple moving average forecast for week 6. Then, using exponential smoothing with alpha = 0.5 and a week-5 forecast of 68 bags, find the week-6 forecast."}},{"itemId":"00a2f083-5476-5812-9189-babd4a5c029c","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:5","parentItemId":null,"revision":1,"payload":{"prompt":"A firm's TFC is ₦200. Its TVC at 1, 2, 3 and 4 units is ₦80, ₦140, ₦210 and ₦320. Find AVC, ATC and MC at each output, and the lowest price at which a price-taking firm would keep producing in the short run."}},{"itemId":"676cac5a-37f5-5f0d-a8da-ac1420773b8b","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:6","parentItemId":null,"revision":1,"payload":{"prompt":"A snack firm with a small budget compares two campus segments. Segment A: 30,000 students, 20% interested, each spending ₦4,000 a month. Segment B: 8,000 staff, 50% interested, each spending ₦5,000 a month. Find each segment's monthly value and name the targeting strategy if the firm serves only the better one."}},{"itemId":"060f6630-377b-5ee1-a865-be44efa268f4","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:7","parentItemId":null,"revision":1,"payload":{"prompt":"State three differences between a private limited company and a public limited company, and one feature they share."}},{"itemId":"5d65ec8b-d2fe-516b-8e5e-90e1b712669f","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","kind":"theory_question","questionId":null,"sourceKey":"guide-theory:8","parentItemId":null,"revision":1,"payload":{"prompt":"A perfectly competitive firm produces 800 units where MR = MC. The market price is ₦250, its ATC is ₦290 and its AVC is ₦230. Find its profit or loss and say whether it should keep producing in the short run."}}]$expected_content$::jsonb,
  'managerial-economics: theory_question published payload and identity match source');
