  where kind = 'course_overview') = $expected_content$[{"itemId":"a7ce1bb4-06e5-5f46-9abf-3142e628c775","courseId":"0412653e-c891-5f49-abd8-927ed986fb78","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Introduction to Cost Accounting","body":"Every topic is examinable.","outcomes":["Explain the nature, objectives and scope of cost accounting and how it differs from financial accounting.","Classify costs by element, function and behaviour, and build up a cost sheet.","Separate semi-variable costs with the high-low method and estimate total cost from a cost function.","Control and price materials (FIFO, LIFO, average), set stock levels and calculate the economic order quantity.","Calculate wages under time, piece and bonus schemes, and treat overtime, shift premium and idle time correctly.","Allocate, apportion and absorb overheads, and work out under- or over-absorption.","Cost jobs and batches and prepare quotations.","Prepare marginal and absorption costing statements and reconcile their profits.","Use break-even analysis for planning and decisions.","Calculate direct material and labour variances and reconcile standard and actual cost.","Explain contemporary developments in cost accounting."],"assessment":["Questions may be multiple choice, short problems and long problems.","Many questions are calculations. Work through every worked example in Topics 3 to 10 until you can do them quickly."]}}]$expected_content$::jsonb,
  'introduction-cost-accounting: course_overview published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
